			["10-day Free Trial"] = { content = "You can download a demo version of [[World of Warcraft]] and play for free for 10 days. You can also try [[World of Warcraft: The Burning Crusade]] for 10 days, if you have an existing World of Warcraft [[account]].\r\nUS Trials\r\n<div style=\"border-bottom:1px solid gray; width:75%;\"> [[World of Warcraft|<span class=\"speciallink\">World of Warcraft</span>]]</div>\r\n:\r\n<div style=\"border-bottom:1px solid gray; width:75%;\"> [[World of Warcraft: The Burning Crusade|<span class=\"speciallink\">World of Warcraft: The Burning Crusade</span>]]</div>\r\nEuropean Trials\r\n<div style=\"border-bottom:1px solid gray; width:75%;\"> [[World of Warcraft|<span class=\"speciallink\">World of Warcraft</span>]]</div>\r\n:\r\n:\r\n:\r\n:\r\n<div style=\"border-bottom:1px solid gray; width:75%;\"> [[World of Warcraft: The Burning Crusade|<span class=\"speciallink\">World of Warcraft: The Burning Crusade</span>]]</div>",},
