			["Belbi Quikswitch"] = { content = "'''Belbi Quikswitch''' can be found in [[Dun Morogh]].\r\n==Quest==\r\n \r\n==Sells==",},
			["Belgrom Rockmaul"] = { content = "'''Belgrom Rockmaul''' is a level 35 [[quest giver]] located in the [[Valley of Honor]] in the [[orcish]] city of [[Orgrimmar]].\r\nHe punished [[Jediga]].\r\nHe starts the following quests:\r\n* The Swarm Grows\r\n* A Threat in Feralas\r\n* Betrayed\r\nSee [[List of Orgrimmar NPCs]].",},
			["Belia Thundergranite"] = { content = "'''Belia Thundergranite''' is a level 40 [[pet]] trainer located at the [[Hall of Arms]] in [[the Military Ward]] within the [[dwarf]] city of [[Ironforge]]. She may be related to [[Regnus Thundergranite]].\r\nSee [[List of Ironforge NPCs]].",},
			["Belker"] = { content = "'''Belkers''' are medium-sized elemental creatures of air living in both the [[Skywall]] of the [[Elemental Plane]], as well as the [[Twisting Nether]]. In the [[air elemental]] hierarchy they reside just after [[revenant]]s but before [[djinni]] nobles. They often travel as a group known as a clutch.",},
			["Bellowing Roar"] = { content = "Ability used by various Dragons([[Onyxia]], [[Nefarian]], [[Taerar]], and [[Nazan]]) that fears the enemy. Similar in action to a warlock's fear.",},
			["Belmara's Tome"] = { content = "This item drops from [[Abjurist Belmara]] in [[Kirin'Var Village]] in [[Netherstorm]]\r\n==Belmara's Tome as a quest objective==\r\n*Abjurist Belmara\r\n==Notes==\r\nThe quest requires you to return the tome to its bookshelf at coordinates 55,86. When you put the book on the shelf, Belmara will appear for a short mini-event. Once you complete the quest, Abjurist Belmara will no longer be hostile to you.",},
			["Belt of Deep Shadow"] = { content = "==Source==\r\nThis item is made by [[Leatherworking|Leatherworkers]] with a skill level of 375. The recipe has been seen dropped by [[mobs]] in [[Eye (Tempest Keep)|The Eye]] and [[Serpentshrine Cavern]].\r\nIngredients:\r\n*2 icon=\r\n*4 icon=\r\n*10 icon=\r\n*2 icon=\r\n*10 icon=",},
