			["Belt of the Archmage"] = { content = "The '''Belt of Archmage''' is a [[tailor]]ed cloth belt that provides bonuses to [[stamina]], [[intellect]], and [[critical hit]] chance. \r\n==Source==\r\nThis item is crafted by [[tailor]]s with a skill level of 300. The components are:\r\n*16 [[Bolt of Runecloth]]\r\n*10 [[Ghost Dye]]\r\n*10 [[Mooncloth]]\r\n*12 [[Essence of Water]]\r\n*12 [[Essence of Fire]]\r\n*6 [[Large Brilliant Shard]]\r\n*6 [[Rune Thread]]\r\nPattern: Belt of the Archmage appears inside [[Knot Thimblejack's Cache]].",},
			["Belt of the Black Eagle"] = { content = "==Source==\r\nThis item requires [[Leatherworking|Leatherworkers]] with a skill level of 375. The recipe drops in [[Eye (Tempest Keep)|The Eye]] and [[Serpentshrine Cavern]].\r\nIngredients:\r\n*2 [[Nether Vortex]]\r\n*4 [[Heavy Knothide Leather]]\r\n*10 [[Primal Air]]\r\n*10 [[Wind Scales]]\r\n*2 [[Rune Thread]]",},
