			["List of death knights"] = { content = "==Others==\r\nLord Nightsorrow, Lord Soulrender, Lord Dethstorm, [[Lord Maldazzar]], Lord Darkhallow, Lord Lightstalker, Baron Bloodbane, Baron Felblade, Duke Dreadmoore, Duke Ragereaver, Baron Frostfel, [[Baron Perenolde (Warcraft III)|Baron Perenolde]], Duke Wintermaul, and Baron Morte.\r\n''Note: Many of these names represent random heroes in Warcraft III.''",},
