			["Little Jimmy Vishas"] = { content = "#REDIRECT [[James Vishas]]", redirect = "James Vishas",},
			["Little Timmy"] = { content = "'''Little Timmy''' first appeared in ''[[Warcraft III: Reign of Chaos]]''. He was a villager boy, the son of [[Alicia]]. He lived in the outskirts of [[Strahnbrad]] at the beginning of the [[Third War]]. However, while Strahnbrad was under attack by [[Blackrock clan|Blackrock orcs]], Timmy was kidnapped by [[Gnoll|gnolls]]. The rescuing of Timmy from the gnoll camp was done by [[Arthas|Prince Arthas]].\r\nTimmy makes yet another appearance in the Scourge campaign chapter called \"[[King Arthas]]\" as a vendor selling [[Ice Shards]].\r\nLittle Timmy appeared again in ''[[Warcraft III: The Frozen Throne]]''. He and Alicia can be found in [[Theramore]] in chapter II of the bonus campaign called \"[[Old Hatreds]]\" indicating their escape from [[Lordaeron]] together with [[Jaina Proudmoore]]. \r\n===In World of Warcraft===\r\nIn [[Stormwind]], there is an NPC named [[Lil Timmy]] who looks very much like Little Timmy from Warcraft III. In Warcraft III there is a ghoul named [[Timmy]], and in WoW there is a ghoul named [[Timmy the Cruel]]. They could be the same. Some speculate that Timmy-ghoul was in fact Little Timmy, though Timmy can be seen in Warcraft III later in the Undead campaign selling Ice Shards. In the neutral campaign in Warcraft III set chronologically later in the timeline, Timmy is with his mother on Theramore very much alive.\r\nTimmy may have later moved to Stormwind to sell cats, explaining how there is a living Timmy there bearing such a resemblance.",},
			["Living Action Potion"] = { content = "'''Living Action Potion''' is a [[potion]] that frees the consumer from stun and movement impairing effects.\r\n==Source==\r\nThis potion is made by [[Alchemy|Alchemists]] with a skill level of 285.\r\nThe components are:\r\n* 2 [[Icecap]]\r\n* 2 [[Mountain Silversage]]\r\n* 2 [[Heart of the Wild]]\r\n* 1 [[Crystal Vial]]\r\nThe [[recipe]] is sold by [[Rin'wosho the Trader]] on [[Yojamba Isle]] in [[Stranglethorn Vale]]. You must be [[Exalted]] with the [[Zandalar Tribe]] to purchase it.",},
			["Living Blaze"] = { content = "'''Living Blaze''' can be found in [[Un'Goro Crater]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.04% Chance of a [[rare]] drop.\r\n0.47% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Living Bomb"] = { content = "''\r\n'''Living Bomb''' is a [[mage]] spell that debuffs the target with a [[DoT]], dealing 1380 damage over 12 seconds (at max rank). After the debuff expires, or when it is dispelled, the target explodes, dealing 690 damage to all enemies within 10 yards (at max rank).\r\nLiving Bomb deals [[fire]] damage, and thus gains the benefit of the talents [[Impact]], [[Ignite]], [[Burning Soul]], [[Master of Elements]], [[Critical Mass]], [[Fire Power]], [[Pyromaniac]], and [[Elemental Precision (mage talent)|Elemental Precision]].\r\nAs with all mage spells capable of critical hits [[Arcane Instability]], [[Spell Power]], [[Molten Fury]], [[Playing with Fire]] and [[Shatter]] can increase the effective damage output of this spell.\r\n==Notes==\r\nDuring the beta of [[Wrath of the Lich King]], the original effect of the spell was to make the caster themselves the Living Bomb, doing [[AOE]] damage to enemies within 10 yards, with a final explosion doing more damage. The spell was criticized as the damage was very low. The spell was then changed to be a castable debuff, but again was criticized for it's low damage. A mana-burn was added to the final explosion, burning off an amount of mana equal to the damage to the target, but the spell was still criticized. Eventually the damage was increased, the mana-burn was removed, and a knock-up effect was added to the final explosion, which knocked the target up into the air. This effect was removed before the spell was released.",},
			["Living Breastplate"] = { content = "'''Living Breastplate''' is leather chest armor with [[stamina]], [[spirit]], [[Resistance|nature resistance]], and an increase to healing.\r\n==Source==\r\nLiving Breastplate is crafted by [[Leatherworking|Leatherworkers]] with a skill level of 300.\r\nThe [[pattern]] drops off [[Decaying Horror]] in [[The Weeping Cave]] in [[Western Plaguelands]].\r\n==Class==\r\nMost definetely a restoration druid item.",},
			["Living Decay"] = { content = "'''Living Decay''' can be found in [[Eastern Plaguelands]] .\r\n==Drops == \r\n \r\n0.02% Chance of an [[epic]] drop.\r\n0.02% Chance of a [[rare]] drop.\r\n0.54% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\n0.50% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Living Dragonscale Helm"] = { content = "==Source==\r\nLiving Dragonscale Helm is crafted by [[Leatherworking|leatherworkers]] with a skill level of 365.\r\nThe components are:\r\n*6x icon=\r\n*28x icon=\r\n*12x icon=\r\n*12x icon=\r\n*1x icon=\r\nThe [[pattern]] is a random world drop\r\n*Pattern: Living Dragonscale Helm",},
			["Living Essence"] = { content = "==Source==\r\nThis item can be crafted using [[Alchemy]] (275); taught by Recipe: Transmute Earth to Life. \r\nThis item can be looted from most level 50-72 [[Elemental]], and [[Giant]] monsters.\r\n==Living Essence as an ingredient==\r\nThis item is used to make: \r\n* Primal Batskin Gloves\r\n* Primal Batskin Jerkin\r\n* Band of Natural Fire\r\n* Living Emerald Pendant\r\n* Ironvine Gloves\r\n* Wisdom of the Timbermaw\r\n* Hide of the Wild\r\n* Living Shoulders\r\n* Living Breastplate\r\n* Ironvine Belt\r\n* Bramblewood Belt\r\n* Bramblewood Helm\r\n* Heavy Timbermaw Boots\r\n* Mantle of the Timbermaw\r\n* Dreamscale Breastplate\r\n* Sylvan Shoulders\r\n* Gaea's Embrace\r\n* Primal Batskin Bracers\r\n* Sylvan Crown\r\n* Might of the Timbermaw\r\n* Living Leggings\r\n* Essence of Earth\r\n* Ultra-Flash Shadow Reflector\r\n* Timbermaw Brawlers\r\n* Golden Mantle of the Dawn\r\n* Ironvine Breastplate\r\n* Heavy Timbermaw Belt\r\n* Sylvan Vest\r\n* Lifelike Mechanical Toad\r\n* Force Reactive Disk\r\n* Bramblewood Boots\r\n* Wildthorn Mail\r\nAnd to enchant:\r\n* Enchant Weapon - Lifestealing",},
			["Living Fire"] = { content = "==Source==\r\nThis item is provided for Blessing of Incineratus.\r\n==Living Fire as a quest objective==\r\nThis item is an objective of Blessing of Incineratus.",},
			["Living Grove"] = { content = "'''The Living Grove''' is a wooded region of southwestern [[Blade's Edge Mountains]], which contains [[Sylvanaar]] and [[Veil Lashh]]. [[Lynx]]es, [[faerie dragon]]s and [[treant]]s roam the area, and it is guarded by [[night elf]] sentinels.",},
			["Living Leggings"] = { content = "The '''Living Leggings''' are a pair of crafted [[leather]] pants, obviously with mid-50's [[druid]]s in mind. They are crafted by [[Elemental Leatherworking|Elemental Leatherworkers]], the pattern requires skill 285/300, and drops off Deadwood Shamans in [[Felwood]] with a 1.08% chance registered on Allakhazam.\r\nThey match quite well with the [[Living Breastplate]] and [[Living Shoulders]], also crafted by an Elemental Leatherworker. Though these items bear similar names, and are obviously designed with the same general texture appearance, they are not a real set and provide no set bonus.",},
			["Living Monstrosity"] = { content = "'''Living Monstrosity''' can be found in [[Naxxramas]] .\r\n==Quests== \r\n==Drops == \r\n \r\n3.45% Chance of an [[epic]] drop.\r\n1.15% Chance of a [[rare]] drop.\r\n2.30% Chance of an [[Uncommon]] drop.\r\n0.29% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Living Ruby"] = { content = "==Source==\r\nThis gem is mined from [[Fel Iron Ore|Fel Iron]],\r\n[[Adamantite Ore|Adamantite]], [[Adamantite Ore|Rich Adamantite]]\r\nand [[Khorium]] deposits, and by [[Prospecting]] [[Fel Iron Ore]] or [[Adamantite Ore]].\r\nIt is also a [[world drop]]. \r\n==Living Ruby as an ingredient==\r\n'''Living Ruby''' is used in the following recipes:\r\n===[[Jewelcrafting]]===\r\n*Figurine - Living Ruby Serpent\r\n*Living Ruby Pendant\r\n* Gems:\r\n===[[Engineering]]===\r\n*Deathblow X11 Goggles\r\n*Furious Gizmatic Goggles\r\n*Gadgetstorm Goggles\r\n*Gnomish Battle Goggles",},
			["Living Shoulders"] = { content = "==Source==\r\nThis item can be crafted using [[Leatherworking]] (270); taught by Pattern: Living Shoulders.",},
			["Living Wood"] = { content = "'''The Living Wood''' is the forested area just east of [[the Dead Scar]]. The contrast to the nearby black line of decay is striking.",},
			["Lizard"] = { content = "==Species==\r\n*Common Lizard\r\nCommon lizards are small, non-venomous lizards of perhaps a foot or two in length, such as an iguana. Lizards prefer flight to combat, but they can bite painfully if there is no other option.\r\n*Iguana\r\n*Skink\r\n*Monitor Lizard\r\nMonitor lizards are a fairly large, carnivorous lizards ranging between 3 to 5 feet in length. Monitor lizards can be aggressive, using their powerful jaws to tear at prey or enemies. They can hide well in forested or overgrown areas. Some druids choose them as their an animal companion.",},
			["Llane"] = { content = "#REDIRECT [[Llane Wrynn I]]", redirect = "Llane Wrynn I",},
			["Llane Beshere"] = { content = "'''Llane Beshere''' is a level 5 [[warrior trainer]] located in [[Northshire Abbey]] in the [[human]] starting zone of [[Elwynn Forest]].\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Llane Wrynn"] = { content = "#REDIRECT [[Llane Wrynn I]]", redirect = "Llane Wrynn I",},
			["Llane Wrynn I"] = { content = "'''Llane Wrynn I''' was the ruler of the [[Kingdom of Stormwind]] during the [[First War]]. He was the child of King [[Barathen Wrynn]] and Lady [[Varia]], and the father of King [[Varian Wrynn]]. His grandson King [[Anduin Wrynn]] was given his middle name Llane to honor him.\r\n===The Gurubashi War===\r\nLlane was born in the year 564 by the [[Warcraft: Orcs & Humans manual|accounting of years]] (40 years before the First War) formerly used in that kingdom. Llane spent his childhood with [[Medivh]] and [[Anduin Lothar]]. One day, while out on the road in [[Stranglethorn Vale]], Medivh and his two friends were ambushed by three [[jungle troll]]s. None were hurt badly, however, Medivh fainted after casting several spells. In 577 (according to ''[[The Last Guardian]]'', Medivh's coma lasted 20 years, hinting at larger timeframe), Llane reached to the [[Age of Ascension]] and was given the full title of Prince of Stormwind. During the evening feast arranged to honor the young Prince, the great wizard Medivh, who had been absent from events of the world for many years, interrupted, announcing his return to the world and giving an obsidian hourglass to Llane, symbolizing Stormwind's unending prosperity. The sands in the glass ran, but the top half never emptied into the lower half.\r\nYears after the [[Gnoll War]], Stormwind's farmers and settlers would continue to push southward, claiming territory close to the jungles of [[Stranglethorn Vale]], home of the [[Gurubashi Tribe]]. Skirmishes would erupt between the Gurubashi and Stormwind forces, but the elderly [[Barathen Wrynn|Barathen]] would refuse to order an invasion of Stranglethorn in favor of a defensive war, to Prince Llane's outrage. While King Barathen's strategy against the Gurubashi was effective, it would be unable to stop every attack, one which saw slow, barbaric, and gruesome deaths delivered to the villagers of three towns in [[Westfall]]. This would ultimately prove to be the final straw for Prince Llane, [[Anduin Lothar]] and [[Medivh]], who, in defiance of King Barathen's wishes, journeyed south to bring war to the Gurubashi. Though initially shielded by Medivh's magic, the three friends would end up in the fight for their lives when they battled [[Jok'non]], a Gurubashi Warlord empowered by [[Hakkar the Soulflayer]]. Ultimately, the three friends would prove victorious and return to Stormwind, though remain shaken by Medivh's powers.\r\nWhile none of the Gurubashi who witnessed Jok'non's death survived, it was clear to the trolls who was responsible. Rallying under Jok'non's son, [[Zan'non]], the Gurubashi launched [[Gurubashi War|an invasion]] intent on destroying Stormwind. In the face of the troll onslaught, Barathen recalled all his forces to the stronghold's gate, believing that the survival of Stormwind would depend on one colossal battle. As the death toll mounted on both sides, Barathen mounted a desperate counterattack against the Gurubashi which would cost him his life. Llane, driven by guilt, would plead with Medivh to unleash his power on the Gurubashi as he had against Jok'non. Though frightened of his power, Medivh would accept Llane's request and destroy Zan'non and the Gurubashi forces, avenging Barathen. With his father's death and the victory over the Gurubashi, Llane would be welcomed as Stormwind's new ruler.\r\nLlane Wrynn's son, [[Varian Wrynn]], was born to him in [[Stormwind City]] ten years before the [[First War]]. He taught him how to ride a horse and oversaw his combat training.\r\n===The First War===\r\nWhen reports of mysterious creatures lurking around the [[Black Morass]] reached Stormwind, rumors spread through the streets that they were either vengeful spirits, [[troll]]s armed with some new breed of power, or a strange race from across the [[Great Sea]]. King Llane dispatched [[Anduin Lothar]] to discover what these new creatures were. Lothar led a small force of the [[Knights of Stormwind]] to scout the Black Morass, resulting in humans clashing with [[orc]]s for the first time in what would become a series of bloody skirmishes and battles. Though Lothar and his men scored a number of small victories, they found themselves outnumbered more and more with each battle and were eventually forced to pull back, never discovering [[Dark Portal|the portal]] through which the orcs were arriving. Lothar informed King Llane the invaders were bringing in reinforcements from somewhere, and the kingdom readied itself for a full-scale war that became known as the [[First War]]. Llane named Lothar the \"King's Champion\", the highest military rank in the kingdom, and entrusted him to end the orcish threat.\r\nThough messengers were dispatched by King Llane to the other human kingdoms, warning of mysterious, fearsome green-skinned invaders, few believed the reports indicated a real threat. [[Lordaeron (kingdom)|Lordaeron]] was considered the most likely nation to help, but the [[Black dragonflight|black dragon]] [[Deathwing]], disguised as a visiting Stormwind noble, openly mocked King Llane, claiming the threat was actually a rebellion of disgruntled citizens, and as a result Lordaeron declined to send aid. This general lack of aid was likely influenced by Stormwind's pride in standing alone and recently developed policies of isolationism, which other kingdoms saw as signs of arrogance.\r\nAfter [[Brightwood]], [[Westfall]], and the [[Redridge Mountains]] fell to the orcs, the newly-formed [[Old Horde|Horde]] marched onto Stormwind City. Thousands of Horde soldiers marched through [[Elwynn Forest]] and encircled Stormwind, cutting off all access except for the sea. Warchief [[Blackhand]] had ordered [[Kilrogg Deadeye]] and [[Cho'gall]] to lead their [[Bleeding Hollow clan|Bleeding Hollow]] and [[Twilight's Hammer]] clans in the assault on Stormwind. To weaken the city's defenses, [[siege engine]]s bombarded the city walls through the night, and at dawn Kilrogg and Cho'gall launched their attack. While orcs charged the battlements, [[warlock]]s engulfed Stormwind's soldiers in [[fel]] fire, resulting in staggering losses. Just as it seemed Stormwind would fall that day, cries of an attack came from the Horde's rear lines- Lothar and the majority of Stormwind's [[knight]]s had moved around the Horde by sea. The King's Commander was now leading a charge through Elwynn Forest, catching the orcs in the rearguard by surprise. While the Bleeding Hollow and Twilight's Hammer were distracted by the knights, Stormwind soldiers emerged from the front gates to flank the orcs in a counterattack. Flanked on both sides and suffering many casualties, the orcs were forced into a retreat. This was the greatest disaster to ever happen to the Horde, which withdrew to Redridge to devise a new plan. Lothar and King Llane had received information about the Horde's battle plans from Medivh's apprentice [[Khadgar]], who had learned of them from [[Garona Halforcen]], which helped prepare for the attack on Stormwind.\r\nThough the war effort continued, fronted by King Llane and Anduin Lothar, the pair of friends were never able to gather accurate data of the orcs' numbers and could only guess at how great a force they would have to contend with.\r\nDuring this time, King Llane also sent many surveyors into the hills and mountains throughout the kingdom in search of new deposits of gold.\r\nAt some point, Llane was visited by a mysterious stranger who revealed herself to be [[Aegwynn]], the mother of Medivh. She revealed that Medivh was behind the arrival of the orcs into the kingdom, warning that Stormwind would eventually have to deal with him.\r\nAs the war continued to rage, both armies found themselves strained by internal conflict. King Llane, who believed the bestial orcs to be incapable of conquering the city, contemptuously held position at Stormwind and refused to press the front into orc territory. After a few years, the majority of the orcish Horde had crossed into the Kingdom of Stormwind, and [[Gul'dan]] deemed that the time for the primary strike against humanity had come. The Horde launched its full might against the human kingdom.\r\nThe war began to turn badly for Stormwind. After losing ground to the Horde's newfound organization and brazen assaults, Llane prepared his armies for a counterattack, sensing that the final confrontation was at hand. It was around this time that Garona Halforcen and Khadgar revealed that his old friend Medivh was responsible for the orcs' arrival. Despite this information, Llane refused to believe that his friend would willingly betray them, and that all his actions could be justified as part of a brilliant scheme. Llane felt confident in Medivh's allegiance, and that his army and Medivh's powers would be enough to beat back the Horde. Garona would later return after Medivh's defeat and become a close friend and adviser to Llane.\r\nMeanwhile, Warchief Blackhand's second in command, [[Orgrim Doomhammer]], set out to free the Horde from demonic corruption, culminating in his killing of the corrupt Blackhand and assuming the role of warchief. Under his decisive leadership, the Horde laid siege to Stormwind Keep once again. Though the city walls were breached and fighting took to Stormwind's streets, Llane and his commanders organized the city's defense from within the fortified Stormwind Keep and held them at bay.\r\nThough considered a trusted friend of the King, Garona remained an agent of the Horde. During the orcish siege of Stormwind, Garona, controlled by the [[Shadow Council]], assassinated Llane, cutting his heart out with [[the Kingslayers]]. Garona knew from a vision she had seen in [[Karazhan]] that she was fated to kill one of the few men who accepted her for what she was, and thus it was she who mourned her victim most of all. Llane's assassination was witnessed by his son, Varian.\r\n==Statue==\r\nUntil its removal in ''[[World of Warcraft:Cataclysm|Cataclysm]]'', a statue of King Llane could be found in Stormwind Keep; the plaque reads:\r\n==Notes and trivia==\r\n*Llane was adviced by the [[King's Council]].\r\n*According to ''The Last Guardian'', Llane had blond hair. His hair has most often since been depicted as light brown. Llane Wrynn's appearance varies a lot between sources. Sources either depict with a full beard, a mustache, or a clean-shaven look.\r\n*[[King Llane]] is also seen in Karazhan as the Alliance king piece in the chess event, his Horde counterpart being [[Warchief Blackhand]].\r\n*In [[Ulduar (instance)|Ulduar]], King Llane's assassination is seen in a vision within the mind of [[Yogg-Saron (tactics)|Yogg-Saron]]. Yogg-Saron also drops the [[Royal Seal of King Llane]]: his symbol of office, stained with blood from his demise, as well as [[Kingsbane (dagger)]], which was at the time presumed to have been used for the assassination. How these items came to be in Yogg-Saron's possession is unknown.\r\n**After they were added in-game, [[the Kingslayers]] were retroactively added to the vision.\r\n*The ''[[Llane's Oath]]'' gunship was named after him.\r\n*On [[Remembrance Day]], [[Varian Wrynn]] has a nightmare in which he recalled the events of him witnessing his father's assassination. He could only watch on in horror, as [[Garona]], with a tear streaked smirk, plunged a dagger in his father's chest. Varian went to his father's side, holding him in his arms. The dying King Llane's parting words to the young Varian was, \"This is how it always ends... with Wrynn kings.\" After which, maggots erupted from the dead king's maw—thousands upon thousands of writhing worms obliterating Llane's ashen face. This horrifying scene caused the king to scream out in terror, awakening him from his nightmare and finding himself in [[Stormwind Keep]].\r\n*Llane died in Year 3. This coincides with the novel ''[[Wolfheart]]'' that says that Varian was \"some thirteen years old\" since Varian was born 10 years before the First War.\r\n**It was previously stated that he died in Year 4.\r\n*[[Varian's compass]], first seen in [[Azeroth's Last Hope|''Legion'' cinematic trailer]], was originally intended by the cinematic artists to be a family heirloom that Llane had passed down to Varian. The compass' model in the cinematic therefore features the initials \"L.W.\". This was later [[retcon]]ned into [[Anduin Wrynn]] having ordered the compass made for Varian's birthday. However, the [[Enchanted Compass]]' model in [[patch 9.1.0|patch 9.1]] still features the inscription \"L.W.\".\r\n*According to the ''[[Ultimate Visual Guide]]'' and [[Warcraft II: Tides of Darkness manual|''Warcraft II: Tides of Darkness'' manual]], Garona cut out Llane's heart and gave it to Gul'dan. This is not valid as according to the current lore, Gul'dan was already in a coma by the time of Llane's death. The [[World of Warcraft: Ultimate Visual Guide, Updated and Expanded|second UVG]] removed the heart part.\r\n*King Llane appointed [[Defender of the Crown]] to participate in the [[First War]] and lead his army, beginning with securing supplies, scouting and eventually marching into battle against the orcs. After [[Abbot of Northshire Abbey]] received a vision about Anduin Lothar being trapped in the Deadmines, Llane also ordered the Defender to rescue the missing knight. As Llane died, he wished the Defender take the mantle of [[War Leader]] but from the moment of King's death, the lore has been retconned and the subsequent fate of the Defender is unknown.\r\n*According to the History of Warcraft chapters, ''Llane grew wary of the darkness which seemed to taint the spirit of his former friend. King Llane shared his concerns with Lothar whom he named his lieutenant-at-arms. Even so, neither man could have imagined that Medivh's slow descent into madness would bring about the horrors that were to come.'' This is in conflict with the Last Guardian as Llane was confident in Medivh and only Lothar was worried.\r\n* An unused NPC representing Llane is situated in the same ID range as other legendary [[warrior]]s presumably meant to [[Skyhold|appear]] in [[Skyhold]]. He and most of these NPCs didn't make it out of the ''[[World of Warcraft: Legion|Legion]]'' alpha stage.\r\n*During his appearances in [[Return to Karazhan]], Llane is seen wielding the sword [[Replica Lion's Fang|Lion's Fang]]. This is a reference to the sword of the same appearance used by Llane's [[Llane Wrynn (film universe)|movie counterpart]]. Prior to this, he used a large hammer, as seen in the [[Chess Event]] of the original [[Karazhan (raid)|Karazhan]].\r\n*In early lore, Barathen Wrynn was said to have died during the [[First War]], with the following description: Llane would discover, to his horror, that Medivh's hourglass was almost completely spent and rushed to inform his father. As Barathen looked at the hourglass and last sands fell, the [[orc]]s first assaulted [[Stormwind Keep]], and Adamant sent Llane and [[Varia Wrynn|Queen Varia]] away to [[Northshire Abbey]]. The attack on Stormwind would ultimately end in defeat for the Horde and chieftains to blaming one another for the debacle, threatening the unity of the Horde. With this victory, Adamant decided to leave his family in the safety of Northshire Abbey and promised to call for them when the foul beasts had been destroyed, but died before that pledge could ever be fulfilled. King Llane succeeded his father a year later and set about ridding the lands of the orcs.\r\n*[[Llane Beshere]] shares the first name with the king.\r\n==Alternate timeline==\r\n[[Llane Wrynn (film universe)|Llane Wrynn]] from a separate timeline appears in the [[Warcraft film universe]].",},
			["Lo'Gosh"] = { content = "#REDIRECT [[Goldrinn]]", redirect = "Goldrinn",},
			["Loa"] = { content = "'''Loa''' is the name given by [[troll]]s to the beings they worship, such as the [[Wild God]]s, beings such as [[Kith'ix]] or [[G'huun]], or spirits like [[wisp]]s. Countless loa exist, most weak, but some very powerful. Most are shapeless, whereas others have animal or creature forms. Powerful, enlightened [[Zandalari troll|Zandalari]] can become loa upon their death - or so it is believed. Many of the loa make their home in the [[Garden of the Loa]] in [[Zuldazar]], or across [[Zandalar]] more generally, with major temples found in traditional troll lands.\r\n==Background==\r\nEarly troll [[tribe]]s, though varying wildly in customs and traditions, all shared a common [[religion]]: the worship and reverence for the Wild Gods. The mountain range of [[Zandalar]] in southern [[Kalimdor (landmass)|Kalimdor]] was home to many loa, and was thus treated as being sacred. Troll [[priest]]s are devoted to only one loa per troll, while troll [[druid]]s use the powers of several loa at once. This is something the loa do not like, as they prefer to be worshiped one at a time. [[Shadow hunter]]s commune with multiple loa as well, and the loa can even channel themselves through the shadow hunters when they use their ceremonial [[rush'kah]] masks.\r\nThe loa can grant wondrous boons or inflict terrible punishments to trolls. Tales abound in troll culture, of those blessed by the loa with extraordinary regenerative abilities, strengthening their already powerful, natural [[Regeneration (racial)|regeneration]]. The tale of [[Vula'jin the Void]] speaks of how he regrew almost his entire body after standing in a pool of [[Shadowflame (spell school)|shadowflame]]. But just as the loa can bless, they can also curse; troll children are taught legends of those cursed by the loa, such as [[Gri'lek]], unable to heal even flesh wounds, to instill the proper respect for their patron spirits.\r\n[[Zandalar tribe|Zandalari]] (as well as [[Darkspear tribe|Darkspear]]) families often worship their own family loa, cities usually have their own civic deities, and the greatest loa are worshiped by the nation as a whole. Powerful, enlightened Zandalari can become loa upon their death - or so it is believed. An example of such a case is [[Zanza the Restless]]. Different troll tribes may call upon different sets of loa.\r\nTroll [[druid]]s visiting the [[Moonglade]] have been overheard calling the [[wisp]]s who reside there loa, just as they refer to [[Goldrinn]], [[Aviana]], and the other returned [[Ancient Guardian|Ancients]] as loa. [[Night elf|Night elves]] and [[tauren]] have tried to counsel these trolls on \"correct\" druidic nomenclature, but the trolls thus far have been stuck in their ways. The loa were later confirmed to be the [[Wild God|same type of being]] as the Ancient Guardians.\r\nAfter [[Vol'jin]] was mortally wounded during the battle at the [[Broken Shore]], he thought that the loa spirits spoke to him, claiming that the death will come soon. They also whispered the name [[Sylvanas Windrunner]]. Vol'jin, thus, named her [[Warchief]] of the [[Horde]] with his last breath. However, during the [[Fourth War]], the spirit of Vol'jin was summoned by [[Talanji]], [[Master Gadrin]], and [[Spiritwalker Ebonhorn]], and Vol'jin revealed that it was not the loa spirits who told him to name Sylvanas Warchief but something far more powerful. He could not tell who the voices belonged to, the memory being denied by some shadows. It was eventually revealed that the culprit behind getting Vol'jin to name Sylvanas Warchief was [[Mueh'zala]]. \r\nSome [[jungle troll]]s of the [[Darkspear tribe]] consider bird spirits to be weak, capricious, undeserving of their worship, and best left to the Amani.\r\nLoa gain in strength and power the more worshipers, offerings, idols and sacrifices they receive. Carrying the symbol of a loa can help strengthen them. [[Bwonsamdi]] also grows in power with every soul under his care.\r\n===Other loa===\r\n*[[Wild God]]s\r\n*[[Wisp]]s\r\n*The being that the [[Lun'alai]] worship.\r\n*The [[Fetid Devourer]] was a chimaera-like creature created by [[G'huun]] from the corpse of several loa who inhabited the forests around [[Zandalar]] and who were experimented upon in [[Uldir]] by the [[titanic watcher]]s. After the experiments proved lethal, the loa's remains were improperly disposed of. Its three heads are reptilian, avian, and leonine, and it possesses hooves on its back legs, hints of the species of loa it was made of.\r\n*[[Guardian Tak'u]] was a [[Zandalari golem]] that had the power of four different loa channeled into it by the [[Priest of the Direhorn]], [[Priest of the Serpent]], [[Priest of the Hydra]] and the [[Priest of the Hawk]].\r\n===High priests===\r\n* [[High Priestess Arlokk|Arlokk]], high priestess of [[Bethekk]]\r\n* [[High Priest Hawinni|Hawinni]], high priest of [[Quetz'lun]] \r\n* [[High Priestess Jeklik|Jeklik]], high priestess of [[Hir'eek]]\r\n* [[High Priestess Kilnara|Kilnara]], high priestess of [[Bethekk]] \r\n* [[Wardruid Loti|Loti]], high priestess of [[Gonk]] \r\n* [[High Priestess Mar'li|Mar'li]], high priestess of [[Shadra]]\r\n* [[High Priest Mu'funu|Mu'funu]], high priest of [[Quetz'lun]] \r\n* [[Hexlord Raal|Raal]], high priest of [[Pa'ku]] \r\n* [[High Priest Thekal|Thekal]], high priest of [[Shirvallah]]\r\n* [[High Priestess Tua-Tua|Tua-Tua]], high priestess of [[Quetz'lun]] \r\n* [[High Priest Venoxis|Venoxis]], high priest of [[Hethiss]]\r\n* [[Qiaga the Keeper|Qiaga]], high priestess of [[Shadra]]\r\n* [[Yazma]], high priestess of [[Shadra]] \r\n===High prophets===\r\n* [[Gal'darah]], high prophet of [[Akali]] \r\n* [[Moorabi]], high prophet of [[Mam'toth]] \r\n* [[Slad'ran]], high prophet of [[Sseratus]] \r\n* [[The Prophet Tharon'ja|Prophet Tharon'ja]], high prophet of [[Tharon'ja]] \r\n===Drakkari prophets===\r\n* [[Prophet of Akali]] \r\n* [[Prophet of Har'koa]] \r\n* [[Prophet of Quetz'lun]] \r\n* [[Prophet of Rhunok]] \r\n* [[Prophet of Sseratus]] \r\n===Others===\r\n*[[Loa Speaker]]s\r\n===RPG loa===\r\n* [[Ula-tek]], Goddess of Serpents. (never stated to be a Loa)\r\n* [[Shadow ascendant]]s\r\n*Shadowhunter\r\n** [[Legba]], Loa of Speed.\r\n** [[Ogoun]], Loa of War.\r\n==Items==\r\nThere are several loa idols, loa-blessed, or other loa-referencing gear items:\r\n==Notes and trivia==\r\n*Zekhan uses the term loa for [[Elune]], [[fire elemental]]s that wanted to be worshiped, and [[tauren]] deities, the [[Earth Mother]] and [[Sky Father]].\r\n*The Zandalari gods empowered King [[Rastakhan]].\r\n*Loa are referred to as spirit gods.\r\n*[[Gurubashi Worshipper]]s prayed to \"the Zandalari gods of darkness\".\r\n*A [[Darkspear tribe|Darkspear]] unit called [[Rok'nah Loa-Singer|loa-singer]] is a [[priest]].\r\n*[[Shadow Hunter Bwu'ja]] communed with the loa while weaving her garb.\r\n*The stresses on the land from the [[Scourge]] and the death of many gods in [[Zul'Drak]] caused the wall between worlds to weaken, and [[water elemental]]s to emerge at [[Drak'Sotra Fields]].\r\n*Some loa prefer being the only one worshiped by an individual troll, rather than said troll worshiping multiple at a time. Though this seems to not always be the case.\r\n*[[:Brittle Chitinous Shoulderpads]] are etched with loa sigils.\r\n*[[Empowered Fire Mojo]] creates a loa-blessed flame.\r\n*Krag'wa allowed the spirit of his witch doctor, [[Witch Doctor Zentimo|Zentimo]], to live on after death, and join his children.\r\n*Many aspects of Loa worship in-game are derivatives of or based upon real-world African, African Diasporic, and Amerindigenous peoples and history, or media based on them.\r\n**Troll loa worship started with the Zandalari practices, much like how is the mother of African Diasporic Voodoo and much of their Lwa. \r\n**Two in-game loa bear the name of two real-world voodoo loa, [[Bwonsamdi]] and [[Dambala]], another two bear the name or name based on real-world Amerindigenous deities, [[Xibala]] and [[Quetz'lun]], and another two likely derive their name from the Spanish language world for eagle ''aguila'' based on the latin ''aquila'' (AH-key-la), [[Akil'darah]] and [[Akil'zon]].\r\n**Many of the animals represented through the loa bear similarity to animal-cultural associations either in comics, mythologies, or otherwise: The Gurubashi worshipping the black panther [[Bethekk]] may be a gesture to how the royal tribe in Marvel's Black Panther worships one; the description [[Shadra]] bears similarity to and ; the that Rezan is based on most commonly lived in North America during the Cretaceous period.\r\n===Death===\r\nThere is contradicting information regarding the deaths of certain loa. Notably, the [[House of the Lost Loa]] seems to consider many loa as \"lost\", gone, or dead, despite some having been shown to return or maintain influence in some form after their death.\r\n*[[Hakkar the Soulflayer]] was originally slain by the [[Zandalari Empire|Zandalari]] and the [[Gurubashi tribe|Gurubashi]] over 1,500 years ago. Yet he recently returned to [[Zul'Gurub (Classic)|Zul'Gurub]], where he was defeated once more. After his defeat, his [[Heart of Hakkar|cursed heart]] was banished by the Zandalari which still did not stop him as three years later, during the events of ''[[World of Warcraft: Cataclysm|Cataclysm]]'', he was still active from within the spirit realm. He sought to have his [[Avatar of Hakkar|avatar]] summoned into the physical world. [[Jin'do the Godbreaker]] attempted to subdue his spirit, but the loa was freed by [[adventurer]]s, whom he told that he would \"''deal with [them] another time''\" before returning them to the physical plane. He was later shown to have passed into Ardenweald.\r\n*When [[Mam'toth]] committed suicide, [[Har'koa]] said that there was nothing they could do to bring him back to life. This is because he used his own spirit as a bomb, thus killing his spirit as well as his physical manifestation.\r\n*[[Rhunok]] was sacrificed by his followers during the events in [[Zul'Drak]], but his spirit lived on and appeared to an [[adventurer]], asking them to return to Har'koa and tell her \"''No matter what, we [loa] are eternal''.\" [[Har'koa]] stated that Rhunok would return as his spirit would live on forever. This is most likely also the fate of the other Drakkari loa that did not have their fate mentioned in quests; [[Akali]] and [[Sseratus]].\r\n*[[Quetz'lun]] was too sacrificed by her followers. She lived on, and created her own underworld domain where she tortured the followers and high priests that turned on her.\r\n*[[Tharon'ja]] was also sacrificed during the events of Zul'Drak, but his [[Eternal Spirit of Tharon'ja|eternal spirit]] was still called to the [[Isle of Thunder]] by the [[Zandalari troll|Zandalari]] years later.\r\n*There is an ancient [[sethrak]] belief that loa can be reborn.\r\n*[[Sethraliss]]' physical manifestation died long ago after sacrificing herself to kill [[Mythrax]]. After the battle, her followers \"awaited her rebirth\". They could still feel her presence, and believed that one day she would be returned to them. She also still possesses an [[Avatar of Sethraliss|avatar]].\r\n*[[Shadra]] was originally killed in [[Shadra'Alor]]. Despite this, her spirit remained and was held against her will in [[Zul'Gurub (Classic)|Zul'Gurub]]. In ''Cataclysm'', she was summoned and killed once more. Yet she was still active during the [[Pandaren Campaign]], and communicated with [[Vol'jin]]. She was also summoned by the [[sand troll]]s who offered her sacrifices. Her high priestess, [[Yazma]], consumed Shadra at her underground temple in the [[Garden of the Loa]].\r\n*[[Torga]] was slain by [[blood troll]]s. However, his spirit could still be called upon and interacted with through the help of the loa of the dead, [[Bwonsamdi]]. When the [[tortollan]]s tried to put Torga's spirit to rest, Torga decided to be reincarnated instead.\r\nIt was, however, confirmed that the lost loa are not permanently gone and that they could return.\r\n===Possible loa===\r\nThe following beings were never called \"loa\" but may share similarities with them and thus may or may not be loa:\r\n*[[Sen'jin]] has been hinted at to possibly be among the loa.\r\n*[[Oacha'noa]], a sea-goddess revered by the [[tuskarr]], wonders if the player was instead sent by the [[Drakkari tribe|Drakkari trolls]] of [[Zul'Drak]] to kill her in order to take her power as their own, apparently aware of the fate of the Drakkari loa.\r\n*Some [[pandaren]] believe [[G'nathus]] to be an ancient [[Zandalari troll|Zandalari]] loa left behind to guard the waters south of [[Lei Shen]]'s [[Isle of Thunder|island citadel]].\r\n*The [[Bloodscalp]] tribe worships three totemic spirits known as [[Mahamba]], a crocodile called \"the Water Spirit\", [[Tsul'Kalu]], a gorilla called \"the Earth Spirit\", and [[Pogeyan]], a mountain lion called \"the Fire Spirit\".\r\n*The four Drakkari gods [[Dubra'Jin (god)|Dubra'Jin]], [[Zim'Abwa (god)|Zim'Abwa]], [[Zim'Rhuk (god)|Zim'Rhuk]], and [[Zim'Torga (goddess)|Zim'Torga]]\r\n*[[Gahz'rilla]] was worshiped by the [[Sandfury tribe]] and called a [[demigod]]\r\n*[[Kith'ix]] was believed to be an undiscovered loa, however, he turned out to be a [[C'Thrax]].\r\n*[[Xolotal]], a being supposedly manifesting as a lightning wolf in [[Zuldazar]].\r\n*[[Ksu'la]], whose spirit infused and transformed [[Arcanital Ra'kul]] into an arcane serpent on the [[Isle of Thunder]].\r\n==See also==\r\n*[[A Loa of a Tale]]",},
			["Loading screen tips"] = { content = "* Nearby questgivers that are awaiting your return are shown as a question mark on your mini-map.\r\n* Your spell casting can be cancelled by moving, jumping or hitting the escape key.\r\n* Clicking on a player name in the chat window lets you send a private message to them.\r\n* If you <Shift>Click on a player name in the chat window it tells you additional information about them.\r\n* You can <Control>Click on an item to see how you would look wearing that item.\r\n* An item with its name in gray is a poor quality item and generally can be sold to a vendor.\r\n* An item with its name in white is useful to players in some way and can be used or sold at the auction house.\r\n* If you are lost trying to complete a quest, the quest log will often tell you what to do next.\r\n* You can send mail to other players or even to your other characters from any mailbox in game.\r\n* You can <Shift>Click on an item to place an item link into a chat message.\r\n* You can remove a friendly spell enhancement on yourself by right-clicking on the spell effect icon.\r\n* When you learn a profession or secondary skill the button that allows you to perform that skill is found in the general tab of your spellbook.\r\n* All of your action bars can have their hotkeys remapped in the key bindings interface.\r\n* If a profession trainer cannot teach you any more, they will generally tell you where to go to get further training.\r\n* On your character sheet is a reputation tab that tells you your status with different groups.\r\n* You can use the Tab key to select nearby enemies in front of you.\r\n* If you are having trouble finding something in a capital city, try asking a guard for directions.\r\n* You can perform many fun actions with the emote system, for instance you can type /dance to dance.\r\n* A Blizzard employee will NEVER ask for your password.\r\n* You can only know two professions at a time, but you can learn all of the secondary skills (fishing, cooking and first-aid).\r\n* You can right-click on a beneficial spell that has been cast on you to dismiss it.\r\n* The interface options menu <ESC> has lots of ways to customize your game play.\r\n* You can turn off the slow scrolling of quest text in the interface options menu.\r\n* Spend your talent points carefully as once your talents are chosen, you must spend gold to unlearn them.\r\n* A mail icon next to the minimap means you have new mail. Visit a mailbox to retrieve it.\r\n* You can add additional action bars to your game interface from the interface options menu.\r\n* If you hold down <Shift> while right-clicking on a target to loot, you will automatically loot all items on the target.\r\n* Your character can eat and drink at the same time.\r\n* If you enjoyed playing with someone, put them on your friends list!\r\n* Use the Looking for Group interface (\"I\" Hotkey) to find a group or add more players to your group.\r\n* There are a number of different loot options when in a group. The group leader can right-click their own portrait to change the options.\r\n* You can choose not to display your helm and/or cloak with an option from the interface options menu.\r\n* You can target members of your party with the function keys. F1 targets you; F2 targets the second party member.\r\n* Being polite while in a group with others will get you invited back!\r\n* Remember to take all things in moderation (even World of Warcraft!)\r\n* You can click on a faction in the reputation pane to get additional information and options about that faction.\r\n* A monster with a silver dragon around its portrait is a rare monster with better than average treasure.\r\n* If you mouse over a chat pane it will become visible and you can right-click on the chat pane tab for options.\r\n* Sharing an account with someone else can compromise its security.\r\n* You can display the duration of beneficial spells on you from the interface options menu.\r\n* You can lock your action bar so you don't accidentally move spells. This is done using the interface options menu.\r\n* You can assign a Hotkey to toggle locking/unlocking your action bar. Just look in the Key Bindings options to set it.\r\n* You can cast a spell on yourself without deselecting your current target by holding down <Alt> while pressing your hotkey.\r\n* Ensure that all party members are on the same stage of an escort quest before beginning it.\r\n* You're much less likely to encounter wandering monsters while following a road.\r\n* Killing guards gives no honor.\r\n* You can hide your interface with <Alt>Z and take screenshots with <Print Screen>.\r\n* Typing /macro will bring up the interface to create macros.\r\n* Enemy players whose names appear in gray are much lower level than you are and will not give honor when killed.\r\n* From the Raid UI you can drag a player to the game field to see their status or drag a class icon to see all members of that class.\r\n* A blue question mark above a quest giver means the quest is repeatable. \r\n* Use the assist button (F key) while targeting another player, and it will target the same target as that player.\r\n* <Shift>Clicking on an item being sold by a vendor will let you select how many of that item you wish to purchase.\r\n* Playing in a battleground on its holiday weekend increases your honor gained.\r\n* If you are having trouble fishing in an area, try attaching a lure to your fishing pole.\r\n* You can view messages you previously sent in chat by pressing <Alt> and the up arrow key.\r\n* You can Shift-Click on an item stack to split it into smaller stacks.\r\n* Pressing both mouse buttons simultaneously will make your character run.\r\n* When replying to a tell from a player (Default 'R'), the <TAB> key cycles through people you have recently replied to.\r\n* Clicking an item name that appears bracketed in chat will tell you more about the item.\r\n* It's considered polite to talk to someone before inviting them into a group, or opening a trade window.\r\n* Pressing 'v' will toggle the display of a health bar over nearby enemies.\r\n* Your items do not suffer durability damage when you are killed by an enemy player.\r\n* <Shift>click on a quest in your quest log to toggle quest tracking for that quest.\r\n* The auction houses in each of your faction's major cities are linked together. \r\n* Nearby questgivers that are awaiting your return are shown as a yellow question mark on your mini-map.\r\n* Quests completed at maximum level award money instead of experience.\r\n* <Shift>-B will open all your bags at once.\r\n* When interacting with other players a little kindness goes a long way! \r\n* Bring your friends to Azeroth, but don't forget to go outside Azeroth with them as well.\r\n* If you keep an empty mailbox, the mail icon will let you know when you have new mail waiting!\r\n* Never give another player your account information.\r\n* When a player not in your group damages a monster before you do, it will display a gray health bar and you will get no loot or experience from killing it.\r\n* You can see the spell that your current target is casting by turning on the 'Show Enemy Cast Bar' options in the basic interface options.\r\n* You can see the target of your current target by turning on the 'Show Target of Target' option in the advanced interface options tab.\r\n* You can access the map either by clicking the map button in the upper left of the mini-map or by hitting the 'M' key.\r\n* Many high level dungeons have a heroic mode setting. Heroic mode dungeons are tuned for level 70 players and have improved loot.\r\n* Spend your honor points for powerful rewards at the Champion's Hall (Alliance) or Hall of Legends (Horde).\r\n* The honor points you earn each day become available immediately. Check the PvP interface to see how many points you have to spend.\r\n* You can turn these tips off in the Interface menu.\r\n* Dungeon meeting stones can be used to summon absent party members. It requires two players at the stone to do a summoning.\r\n* The Parental Controls section of the Account Management site offers tools to help you manage your play time.\r\n* Quest items that are in the bank cannot be used to complete quests.\r\n* A quest marked as (Failed) in the quest log can be abandoned and then reacquired from the quest giver.\r\n* The number next to the quest name in your log is how many other party members are on that quest.\r\n* You cannot advance quests other than (Raid) quests while you are in a raid group.\r\n* You cannot cancel your bids in the auction house so bid carefully.\r\n* To enter a chat channel, type /join [channel name] and /leave [channel name] to exit.\r\n* Mail will be kept for a maximum of 30 days before it disappears.\r\n* Once you get a key, they can be found in a special key ring bag that is to the left of your bags.\r\n* You can replace a gem that is already socketed into your item by dropping a new gem on top of it in the socketing interface.\r\n* City Guards will often give you directions to other locations of note in the city.\r\n* You can repurchase items you have recently sold to a vendor from the buyback tab.\r\n* A group leader can reset their instances from their portrait right-click menu.\r\n* You can always get a new hearthstone from any Innkeeper.\r\n* You can open a small map of the current zone either with Shift-M or as an option from the world map.\r\n* Players cannot dodge, parry, or block attacks that come from behind them.\r\n* If you Right Click on a name in the combat log a list of options will appear.\r\n* You can only have one Battle Elixir and one Guardian Elixir on you at a time.\r\n* The calendar can tell you when raids reset.",},
			["Loatheb"] = { content = "'''Loatheb''' is a [[Fungal monster]] [[boss]] in [[Naxxramas]]. \r\n==Attacks and Abilities==\r\n* Corrupted Mind — Loatheb places a 1 minute linked cooldown on all healing spells, including cleanse/dispel/remove poison. This means you only get 1 healing spell to cast per 1 minute, including cleanse/dispel/remove poison. Essentially, any beneficial spell cast on a friendly target is affected.\r\n* Poison Aura — 5 yard range. 196 Nature damage inflicted every 6 seconds for 12 seconds. 12 seconds between each poison aura.\r\n* [[Inevitable Doom]] — Loatheb begin to cast it after 2 mins in fight. Inflicts 2550 Shadow damage after 10 sec. 100 yards, every 30 secs. 5 mins after engaging, this will be every 15 secs. This debuff can not be dispelled, cleansed, or decursed and the damage can not be resisted.\r\n* [[Decurse]] — Every 30 seconds, starting at about 2 seconds in fight, Loatheb will remove all curses on himself.\r\n* Fungal Bloom — Critical-hit chance increased by 50%. Spell critical-hit chance increased by 60%. Spells and abilities cause no threat. Get from environment, you can control who gets it. 90 secs duration, spawns every 12 secs, every time only 5 people can get it.\r\n==Strategy==\r\nThe encounter with Loatheb is fairly straightforward in theory but much harder in execution due to the high amount of DPS required.\r\nHealers will only be allowed to cast one healing spell every minute. This means healers will only be able to heal the Main Tank while the rest of the raid must use consumables to stay alive. Healers should set up a rotation to determine when and who heals the tank.\r\nLoatheb has an aura that deals Nature damage to players and pets in melee range. It's important to have [[Judgement of Light]] or [[Poison Cleansing Totem]] active at all times since melee must save their consumables to recover damage taken from Inevitable Doom.\r\nGroups should be assigned an order to kill Spores for the Fungal Bloom debuff. Spores spawn every 13 seconds on the opposite side of the room from the majority of the raid/Loatheb.\r\nAll players must use consumables to survive the Inevitable Dooms. Players will need to use [[Bandage]]s and [[Healthstone]]s or [[Whipper Root Tuber]]s.\r\nNote that [[Greater Shadow Protection Potion]]s, which used to be consumed at least two minutes before the encounter, have been changed to have a 2 minute duration (from 1 hour), and can no longer be used in this way.\r\nInevitable Doom is cast every 30 seconds after the first 2 minutes of the encounter. 5 minutes into the fight, it's cast every 15 seconds.\r\nThe order of consumables should be as follows.\r\nDepending on how much health a player has, the Inevitable Doom cast at 5:15 may mark the final 10 seconds before the debuff kills that player. It's very unlikely a player will survive another doom when it hits at 5:40.\r\n==Tips==\r\n*Players can carry multiple [[Healthstone]]s depending on the rank of the Healthstone and the number of talent points the conjuring warlock has in [[Improved Healthstone]], but all [[Healthstone]]s share a 2 minute cooldown.\r\n*[[Lightwell]]s are not afflicted by the cooldown, so you can use them to heal people who are about to die.\r\n*Shadow priests are excellent for healing groups with current talents (as of 4th January 2007) as shown by Death and Taxes, who successfully managed to kill him with five people (",},
			["Lobster Stew"] = { content = "==Source==\r\n'''Lobster Stew''' is crafted by [[Cooking|Cooks]] with a skill level of 275. This requires a [[Cooking Fire]].\r\nThe components are:\r\n*1 [[Darkclaw Lobster]]\r\n*1 [[Refreshing Spring Water]]\r\nThis recipe can be purchased from [[Sheendra Tallgrass]] in [[Camp Mojache]] and [[Vivianna]] in [[Feathermoon Stronghold]] in [[Feralas]]",},
			["Lobstrock Slicer"] = { content = "==Scource == \r\nThis item is a reward from Oh Noes, the Tadpoles!",},
			["Lobstrok"] = { content = "'''Lobstrok''' (sometimes pluralized as '''lobstroks''') are a race of humanoid lobsters native to [[Draenor]] (and its ) before its destruction. During the destruction of Draenor many of these creatures were killed, however, fortunate ones that were living near the [[Zangar Sea]] managed to survive in what later would be called [[Zangarmarsh]]. Lobstrok are well adapted to living underwater, but are usually found on beaches and islands similar to the [[makrura]] and [[murloc]]s of [[Azeroth]].\r\nLobstrok are ravenous carnivores and a large specimen has the capability to devour prey at least as large as a [[Broken]]. The insubordination of the naga's Broken slaves is often punished by the feeding of offenders to these monsters.\r\n==Territories==\r\nOutland\r\nLobstroks are found in and around [[Marshlight Lake]] and were enslaved by the [[naga]] inside the [[Slave Pens]].\r\n===Outland===\r\nTypes\r\n* Bogstrok (mob) — found in Slave Pens.\r\n* Bogstrok Clacker — found in Zangarmarsh.\r\n* Bogstrok Crusher — found in Zangarmarsh.\r\n* Bogstrok Hatchling — found in Zangarmarsh.\r\n* Bogstrok Razorclaw — found in Zangarmarsh.\r\n* Greater Bogstrok — found in Slave Pens.\r\nNotable\r\n* Mr. Pinchy\r\n* Rokmar the Crackler\r\n* Terrorclaw\r\n===Draenor===\r\nTypes\r\n* Bluewater Clawcaster\r\n* Bluewater Marauder\r\n* Cerulean Clacker\r\n* Clearwater Clacker\r\n* Clearwater Mistweaver\r\n* Clearwater Pincher\r\n* Clearwater Protector\r\n* Clearwater Tempest\r\n* Darktide Boneshell\r\n* Darktide Husk\r\n* Frenzied Lobstrok\r\n* Lobstrok Hatchling\r\n* Strandstrider Brute\r\n* Tangled Lobstrok\r\n* Tidewater Pincer\r\n* Zangar Pincer\r\nNotable\r\n* Mr. Pinchy Sr.\r\n* Ru'klaa\r\n==Companion==\r\n*[[Zomstrok]] has a chance to drop from the undead lobstroks in Shadowmoon Valley, [[Darktide Husk]] and [[Darktide Boneshell]].\r\n==Makrura==\r\nLobstrok can also refer to the makrura as well for the following reasons:\r\n*The ''[[Ultimate Visual Guide]]s'' state that makrura are sometimes known as lobstrok.\r\n*The prefix '''Lobstrokk''' also exists for the makrura sound set and icons in the'' [[Warcraft III: The Frozen Throne]]'' [[World Editor]]. It is unknown whether or not this was the original name for the [[makrura]], or if this is a term related to someone or something within the lobster-like race of [[humanoid]]s. It is probable that this creature type has undergone a renaming, much like the relation between the [[owlbear]] and the [[wildkin]].\r\n*The texture model that exists within the World of Warcraft file structure that depicts a makrura is labeled as a \"lobstrok\". This term does not exist in-game, and may be the original name that was changed in favor of makrura. This same situation existed in Warcraft III's files versus the game itself.\r\n*[[Claximus]] is called a lobstrok. This may be an error, as in his \"gossip\" text [[King Mrgl-Mrgl]] also calls him a makrura.\r\n**Also, the [[Lobstrock Slicer]] is a reward from [[Oh Noes, the Tadpoles!]].\r\n*In \"''Gallywix: Trade Secrets of a Trade Prince''\", there is a food named lobstrok puffs.\r\n*[[Drysnap Crawler]]s and [[Drysnap Pincer]]s drop [[Tender Lobstrock Tail]] for a quest that refers to them as lobstrock.\r\n*Most, if not all, of the makrura around [[Pandaria]] use the Lobstrok model.",},
			["Location"] = { content = "'''Locations''' in ''[[World of Warcraft]]'' fall under several levels of classification:\r\n*[[Planet|Worlds]] / [[Plane]]s\r\n**[[Continent]]s\r\n**[[Zone|Zones / Regions]]\r\n**[[Subzone|Subzones / Sub-areas]]\r\n***[[Settlement]]s\r\n***[[Instance]]s\r\nTo reference a certain location you can use [[coordinates]] or a [[map]].\r\n==See also==\r\n*[[Maps]]\r\n*[[Lore location]]s",},
			["Loch"] = { content = "'''Loch''' refers to two different lakes in [[World of Warcraft]]:\r\n*[[The Loch]] in [[Loch Modan]]\r\n*[[Loch Verrall]] in the [[Twilight Highlands]]",},
			["Loch Frenzy"] = { content = "'''Loch Frenzies''' are level 12-13 [[Frenzy (fish)|frenzies]] found in the water at the northern end of [[Loch Modan]].\r\nThey can be skinned for Shiny Fish Scales, and they can also drop Raw Loch Frenzy and, Raw Rainbow Fin Albacore used in cooking. (Note that Loch Frenzy is an inland fish and Rainbow Fin Albacore is a coastal fish.)",},
			["Loch Modan"] = { content = "'''Loch Modan''' is a large area east of [[Dun Morogh]], situated in eastern [[Khaz Modan]]. It is known for its temperate climate, abandoned archaeological dig site and, until the cataclysm, the huge lake from which the region takes its name. The gray and rugged mountains rise up on all sides around the loch, and the hills are lightly wooded with pine and birch. The loch was held in place by the now broken [[Stonewrought Dam]], an architectural wonder of no equal on [[Azeroth]]. The dam was destroyed when Deathwing burst into and flew over Azeroth, and its destruction caused the loch to drain and cause massive changes to the area.\r\nLoch Modan is heavily populated by hostile [[trogg]]s, unearthed from caves below ground by the dwarven digs. They have since settled in the surrounding mountainous area and built crude camps and caves from which to strike at passing travelers. Other dangers include dangerous wildlife, aggressive [[kobold]]s, and the powerful [[ogre]]s of the [[Mo'grosh Stronghold]].\r\n==History==\r\nDespite its serene appearance, Loch Modan has seen its share of conflict and bloodshed. In the [[Second War]], the [[orc]]s of the [[Horde]] overran Loch Modan and made a stand against the defenders of the [[Alliance]]. The dwarves of [[Ironforge]] were ultimately successful in their defense, and reclaimed the area in the war's aftermath. Broken [[catapult]]s and [[ballista]]e can still be seen scattered about on the bottom and islands of the loch, mute evidence to the region's bloody history.\r\n==Geography==\r\nThere are no instanced dungeons or battlegrounds in Loch Modan. However, the [[elite area|micro dungeon]] [[Mo'grosh Stronghold]] can be found in this area.\r\nSince the [[Alliance]] has no travel hub in the [[Badlands]], they have to fly to [[Thelsamar]] in Loch Modan and ride from there to get to [[Uldaman]]. Newer players are often unacquainted to the higher-level activity in a teens level zone in comparison to the starting zones they have come from.\r\n===== [[Flight path]]s from [[Thelsamar]]=====\r\n*[[Ironforge]], [[Dun Morogh]]\r\n*[[Gol'Bolar Quarry]], [[Dun Morogh]]\r\n*[[Farstrider Lodge]], Loch Modan\r\n*[[Slabchisel's Survey]], [[Wetlands]]\r\n*[[Menethil Harbor]], [[Wetlands]]\r\n*[[Refuge Pointe]], [[Arathi Highlands]]\r\n*[[Dustwind Dig]], [[Badlands]]\r\n*[[Thorium Point]], [[Searing Gorge]]\r\n===== [[Flight path]]s from [[Farstrider Lodge]]=====\r\n*[[Thelsamar]], Loch Modan\r\n*[[Fuselight]], [[Badlands]]\r\n==Notable characters==\r\nLoch Modan is home to several [[Dwarf|dwarves]] of various levels of importance. In the Valley of Kings, [[Captain Rugelfuss]] sends promising young dwarves to eradicate the troggs who infest the region. At the Stonewrought Dam, [[Chief Engineer Hinderweir VII]] seeks to rid Loch Modan of the vile and terrible Dark Iron dwarves. And at his excavation site, the unlucky [[Prospector Ironband]] recruits \"slightly\" more experienced adventurers to investigate the ruins of Uldaman.\r\n==Quests==\r\nLoch Modan is the level 10-20 destination zone for [[Dwarf|dwarves]] and [[gnome]]s from the adjacent starting zone of [[Dun Morogh]]. However it is easy enough for all other [[Alliance]] races to quest here, via the [[Deeprun Tram]] from [[Stormwind]].\r\n==Resources==\r\n*[[Cloth]]\r\n**[[Linen Cloth]]\r\n**[[Wool Cloth]]\r\n*[[Fishing]]\r\n**[[Raw Brilliant Smallfish]]\r\n**[[Raw Bristle Whisker Catfish]]\r\n**[[Raw Loch Frenzy]]\r\n**[[Raw Longjaw Mud Snapper]]\r\n*[[Herb]]s\r\n**[[Peacebloom]]\r\n**[[Silverleaf]]\r\n**[[Earthroot]]\r\n**[[Mageroyal]]\r\n**[[Swiftthistle]]\r\n**[[Briarthorn]]\r\n**[[Bruiseweed]]\r\n*[[Leather]]\r\n**[[Ruined Leather Scraps]]\r\n**[[Light Leather]]\r\n**[[Medium Leather]]\r\n*[[Ore]]\r\n**[[Copper Vein]]\r\n**[[Tin Vein]]\r\n**[[Silver Vein]]\r\n==Battle pets==\r\n*[[Rat]]\r\n*[[Little Black Ram]]\r\n*[[Snow Cub]]\r\n==Wild creatures==\r\n*[[Bear]]s\r\n*[[Boar]]s\r\n*[[Condor]]s\r\n*[[Crocolisk]]s\r\n*[[Dark Iron dwarf|Dark Iron dwarves]]\r\n*[[Eagle]]s\r\n*[[Fox]]es\r\n*[[Frenzy (Fish)|Frenzies]]\r\n*[[Kobold]]s\r\n*[[Lynx]]es\r\n*[[Ogre]]s\r\n*[[Tarantula]]s\r\n*[[Threshadon]]s\r\n*[[Trogg]]s\r\n===History===\r\nThe rampaging [[orc]]s overran Loch Modan in the Second War, but in the war's aftermath the dwarves returned and reclaimed their land. The [[Wetlands]] to the north didn't have such luck as Horde and [[Scourge]] forces devastated them in the Second and [[Third War]]s, forcing the Ironforge dwarves to retreat to Loch Modan and [[Dun Morogh]].\r\n[[Goblin]] [[sapper]]s, hired by an unknown enemy, blasted [[Dun Algaz Gate]] and severely damage the edifice. The gate had to be repaired before another attack. [[King Magni Bronzebeard]] offers a sizable reward to whoever discovers the enemy behind the sabotage.\r\n===Geography===\r\nThe cold, wet, and mountainous Loch Modan lies in the foothills of [[Ironforge Mountain]]. To its south are the [[Badlands]] and the [[Searing Gorge]]; while to the north, after crossing Dun Algaz Gate, lie the [[Wetlands]]. Loch Modan is a [[lake]] — the largest body of fresh water in the world of [[Azeroth]]. It teems with fish, and the surrounding mountains are rich in timber and precious metals. Dwarves and their allies fish the lake, mine the cliffs and cut the timber.\r\nThe region is constantly gray and cold. The sun burns through the mist rarely, creating a twilit world of rolling wisps and limited vision. Constant rainfall keeps the land lush and green. A bitter chill claims the mornings and evenings, though warm currents from the eastern seas prevent the loch from freezing. A bit too rugged for [[human]] sensibilities, but perfect for dwarves. The air smells better in Loch Modan, and the humidity is a stark contrast to the Badlands.\r\nThe loch is massive, occupying a great deal of [[Khaz Modan]], and it seems no one has ever measured it. Three large islands grace the lake's interior. Upon the northernmost island are ruins from the Second War, while the southern islands are barren save for occasional [[Stonesplinter tribe|Stonesplinter]] [[trogg]]s and [[crocolisk]]s. Huge gray mountains rise up on all sides around the lake, while pine forests cover the area.\r\nThe lake abounds with fish, including piranhalike [[Frenzy|frenzies]], and its fish population draws a variety of predators to the area. Black [[bear]]s and [[threshadon]]s frequent the shoreline, the bears snatching fish from the water while the threshadons chew on the aquatic plantlife. The threshadons occasionally try to run off fishermen as well, so dwarves use them for target practice.\r\n==Notes==\r\n*[[Dun Morogh]] and Loch Modan were originally concepted as a single zone.",},
			["Loch Modan NPCs"] = { content = "The following [[NPC]]s can be found in [[Loch Modan]].\r\n=== Alliance===\r\n* Bailor Stonehand\r\n** Bailor's Ore Shipment (Elite)\r\n* Bingles Blastenheimer\r\n** Bingles' Missing Supplies\r\n* Brock Stoneseeker\r\n** Honor Students\r\n* Captain Rugelfuss\r\n** The Trogg Threat\r\n** In Defense of the King's Lands\r\n* Chief Engineer Hinderweir VII\r\n** A Dark Threat Looms\r\n** A Dark Threat Looms\r\n** A Dark Threat Looms (Elite)\r\n** A Dark Threat Looms\r\n* Daryl the Youngling\r\n** A Hunter's Boast\r\n** A Hunter's Challenge\r\n** Vyrin's Revenge\r\n* Ghak Healtouch\r\n** Badlands Reagent Run\r\n** Uldaman Reagent Run (Dungeon)\r\n** Badlands Reagent Run II (Alchemy) (Elite)\r\n* Huldar\r\n** After the Ambush\r\n* Jern Hornhelm\r\n** Report to Ironforge\r\n** Resupplying the Excavation\r\n** Ironband's Excavation\r\n* Magistrate Bluntnose\r\n** Mercenaries (Elite)\r\n* Magmar Fellhew\r\n** Gathering Idols\r\n* Marek Ironheart\r\n** Crocolisk Hunting\r\n* Miran\r\n** Protecting the Shipment\r\n* Mountaineer Cobbleflint\r\n** In Defense of the King's Lands\r\n* Mountaineer Gravelgaw\r\n** In Defense of the King's Lands\r\n* Mountaineer Kadrell\r\n** Rat Catching\r\n** Mountaineer Stormpike's Task\r\n** Report to Mountaineer Rockgar\r\n** Stonegear's Search\r\n* Mountaineer Pebblebitty\r\n** Proof of Deed (Elite)\r\n* Mountaineer Rockgar\r\n** The Algaz Gauntlet\r\n* Mountaineer Stormpike\r\n** Stormpike's Order\r\n** Filthy Paws\r\n* Mountaineer Wallbang\r\n** In Defense of the King's Lands\r\n* Prospector Ironband\r\n** Excavation Progress Report\r\n** Find Agmond\r\n** Agmond's Fate (Dungeon)\r\n* Thorgrum Borrelson\r\n** Ride to Ironforge\r\n* Vidra Hearthstove\r\n** Thelsamar Blood Sausages (Cooking)\r\n* Vyrin Swiftwind\r\n** Vyrin's Revenge (Elite)\r\n=== Neutral===\r\n* Elder Silvervein ([[Lunar Festival]])\r\n** Silvervein the Elder ([[Lunar Festival]])\r\n=== Alliance===\r\n* Dargh Trueaim\r\n** Claude Erksine\r\n=== Alliance===\r\n* Brock Stoneseeker\r\n* Deek Fizzlebizz\r\n* Ghak Healtouch\r\n* Kali Healtouch\r\n* Warg Deepwater\r\n=== Alliance===\r\n* Aldren Cordon\r\n* Cliff Hadin\r\n* Drac Roughcut\r\n* Gothor Brumn\r\n* Greishan Ironstove\r\n* Honni Goldenoat\r\n* Irene Sureshot\r\n* Karm Ironquill\r\n* Kat Sampson\r\n* Khara Deepwater\r\n* Morhan Coppertongue\r\n* Nillen Andemar\r\n* Rann Flamespinner\r\n* Vrok Blunderblast\r\n* Xandar Goodbeard\r\n* Yanni Stoutheart\r\n=== Alliance===\r\n* Innkeeper Hearthstove\r\n* Lina Hearthstove\r\n* Thorgrum Borrelson",},
			["Lock"] = { content = "In [[World of Warcraft]], a '''lock''' usually refers to a few of things:\r\n* Something that keeps a [[container]] or [[door]] closed. Usually requires a [[key]] or [[Lockpicking]] to [[unlock]].\r\n* An [[abbreviation]] for a [[Warlock]].\r\n* To engage a lock so it becomes [[locked]].",},
			["Lockbox"] = { content = "A [[container]], like a [[Chest (container)|chest]], that is usually an [[item]] [[drop]] and not a [[fixed device]].\r\nSee [[Lockpicking]] for a overview which level of lockpicking skill is needed for the lockboxes.\r\nTypes of '''lockboxes''':",},
			["Locked"] = { content = "A property of a [[container]] [[item]] or [[door]] that requires it to be ''[[unlocked]]'' by a specific [[Key|key]] quest item, generic [[Seaforium_Charge|seaforium charge]] (as of [[2.1.0.6729|Patch 2.1.0]]), generic [[Skeleton key (Blacksmith)|skeleton key]], or minimum level of [[Lockpicking]] skill by a [[Rogue]] before it can be opened and [[Loot|loot]]ed or passed.",},
			["Locke Okarr"] = { content = "'''Locke Okarr''' is a level 28 [[quest giver]] located at [[Splintertree Post]] in the [[contested]] territory of [[Ashenvale]].\r\nHe gives the quest Warsong Supplies.\r\nSee [[List of Ashenvale NPCs]].",},
			["Lockpicking"] = { content = "The [[Pick Lock]] skill allows [[rogue]]s to open locked doors, chests, and lockboxes. It is like a gathering skill, such as Fishing or Mining; the rogue must have it at or above a certain level to open certain types of locks. This skill typically doesn't advance quickly enough with casual use; rogues must occasionally go out on runs to improve their lockpicking. Fortunately, your rogue trainer can point you to areas which contain footlockers at your skill level. The basic formula for your maximum lockpicking skill at a particular level is (5 * level). Lockpicking can be learned from a rogue trainer at level 16.\r\n==Strategy==\r\n[Quick Note: As of patch 3.0.2 Thieves' Tools are no longer required for the Lockpicking skill. \r\n===1 to 170===\r\nEarly on you might get some Practice Lock from an [[Engineering|engineer]] to increase your '''lockpicking''' up to skill level 80. The quest to obtain Lockpicking will point you toward plenty of practice chests.\r\nThe best way for [[Alliance]] [[Rogue]]s to get their lockpicking skill up at level 16-20 (after getting the [[Pick Lock]] skill) is [[Alther's Mill]] in the [[Redridge Mountains]] region. The quest Alther's Mill requires lockpicking a chest in Alther's Mill for a quest item and is close to the practice lockboxes. These chests respawn quickly and may be practiced upon from 1-100 skill (though this is capped at 80 if the rogue goes there while still level 16). [[Horde]] Rogues can gain early levels from an equivalent quest on the ship off the [[Merchant Coast]], south of [[Ratchet]] in the [[Barrens]]. Additionally, [[Blood Elf]] Rogues may take the quest, [[Greed|Quest:Greed]] in the [[Ghostlands]] at level 16 which takes them to the [[Amani Catacombs]] where they may practice lockpicking up to 100 (currently level * 5). In addition to training, these chests contain treasure. \r\nThe Rogue [[poisons]] quests for Horde and Alliance provide the next opportunity for solid skill gains. The quest is gained at level 20 although it may be too difficult for many players at level 20. The item required to complete this quest is contained inside a locked chest that can be picked repeatedly up to 170. (You are likely to hit your skill level cap first, if you are on the poison quest.) If you've already finished the quest, you can still use the chests to gain skill. ''The chests don't highlight when you mouse over them after the first time, when you obtain the quest item, so you have to activate your lockpicking skill first and then click the chest.'' The chest will be empty if you already have the quest item or have completed the quest. Be sure to close the empty loot window in order to speed along the chest respawning (it is very quick if the loot window is not left open.) The poison [[Touch of Zanzil]] is applied every time the chest is lockpicked. The poisons can be dispelled if you have the cure from the poison quest chain, [[Anti-Venom]] skill (and Anti-Venom in your pack) from the [[First Aid]] profession, or by the Dwarf racial [[Stoneform]]. The boss guarding the chest will probably respawn a couple of times while you are leveling your lockpicking skill on this chest. (It appears that either faction could use the opposite faction chest; not tested.)\r\nAlso, level 1 Battered Footlockers can be pick pocketed from the mobs around [[Durnholde Keep]] in the [[Hillsbrad Foothills]]. Continuously make routes around Durnholde Keep, and pickpocket mobs for [[Junkbox]]es. Note again that these are level 1, so if you've already leveled up using the lock box in the rogue poisons quest, these will be grey and therefore useless for leveling your skill.\r\n===170 to 300===\r\nOnce you get to 150-170, you can go to [[Angor Fortress]] in [[Badlands]]. Go to the upper parts, and again pickpocketing for junkboxes will help. Once you get to 175 you can open all of the boxes in the fortress. Another very good place to go is [[Sar'theris Strand]] in northwest [[Desolace]]. Underwater, there are plenty of Waterlogged Footlockers, that will easy get you to 210. Highly recommended to bring an elixir of waterbreathing though.\r\nOnce at 205 or so, go to the [[Scarlet Monastery]] doors. Read below the doors section on what to do. Open each door, go into the instance and pickpocket 3 mobs. Come back out and open the doors and the timer will have reset for the skillups from the doors. Continuously do this until 225. At 225, go to [[Searing Gorge]]. Down in the slag pit are Dented Footlockers. You can open all of them, and again pickpocket for junkboxes. Additionally, you can travel to the [[Swamp of Sorrows]]. A water breathing potion makes circling the deep water around the [[Sunken Temple]] much easier, as Mossy Footlockers spawn throughout the area. Stay in either of these locations until 250-255. \r\nThe best place to raise your skill from 250 to 300 is in [[Blackrock Depths]]. Simply go in, turn to the left and unlock the Shadowforge Gate. Continue forward and take the first right, picking the next Shadowforge Gate. Pick the first door on the left, the East Garrison Door, and head forward staying on the bottom level. If you are level 60 or above, pick the large wooden object sticking out of the ground below the giant gear, The Shadowforge Lock; younger levels can agro the mobs around it. Then head out of the instance and reset it before doing all four again. Note that you can only reset the instance 5 times before it disables you from entering, saying \"You have entered too many instances recently\". This is valid for the whole account and resets roughly an hour after you entered the first time.\r\nAnother place for 250-300 is [[Tyr's Hand]] in [[Eastern Plaguelands]]. Pickpocket the mobs and find all of the Scarlet Footlockers. In the time it takes to take a full circle of Tyr's Hand, the starting point will be pickpocketable and have boxes respawned. Do this until 300.\r\n===After 300===\r\nThe best place at 70 is in [[Feralfen Village]] in [[Zangarmarsh]]. This is located south of [[Coilfang Reservoir]] and [[Twin Spire Ruins]], west of the [[Lagoon]] and east of [[Quagg Ridge]]. There are three areas of buildings clumped together with a handful of wicker chests in each. They typically spawn inside and around the huts. The tower in the western section of the village has wicker chests on the first floor and on the top floor. You can also pickpocket the mobs (levels 61-63) with an 11% chance of getting a Strong Junkbox (requires Lockpicking 300).\r\nAnother location for leveling lockpicking between 300 and 350 is outside of [[Black Temple]] in [[Shadowmoon Valley]] (very east side, hunk of land sticking out). Stay near the blood elves that are paladins/warriors (not by name), not the demon hunters. Pickpocket these and kill them to have them respawn. As many know, there is an [[thrown]] weapon that can be taken out of the Strong Junkbox that come out of [[Outland]], Spinesever, however it was recently nerfed. \r\nEither way, from 350 you can open any door that can be picked, any box, and any chest. Good luck!\r\n===Gear===\r\nDark Leather Gloves, created through [[Leatherworking]], increase lockpicking skill by 5. They reduce the chance of a lockpicking attempt failing and also can be used to pick locks slightly out of your skill range.\r\n===Crafted Items===\r\n===Beta===\r\nIn the early closed beta, [[mage]]s had a spell called [[Khadgar's Unlocking]] which could unlock lockboxes and doors by consuming a reagent, but this spell was removed in [[Patch 0.9]].\r\n==Lockpicking Etiquette==\r\nThere is very little consensus on what standard policies for lockpicking are; Rogue expectations can vary wildly from server to server. Some expect a tip, and some gladly open locks for free. Common assumptions can be:\r\n# If the Rogue is '''not''' sending messages via Trade, General chat or by yelling, then it is never acceptable to open a trade with a Rogue without first asking him/her if he can open a certain box. Among other things, it can disrupt a mail composition, an [[auction house]] scan, or a profession crafting, and can be very irritating. Many Rogues will automatically ignore people who open trade windows unsolicited. HOWEVER, if the Rogue is clearly stating that he/she is opening lockboxes, it can be considered even more irritating to the Rogue who then has to deal with floods of PMs coming in, so simply open trade.\r\n# Rogues will generally offer their service for free, it is generally expected to offer a tip if you can afford it.\r\n# If a Rogue expects a fee for lockpicking, he should negotiate it ahead of time. Otherwise, gracious players often tip anywhere between 2 gold and 5 gold to the opening Rogue, based on the type of lockbox opened. Most locks under Thorium Lockboxes, are usually worth tipping the Rogue 50 silver and Thorium and above is worth about 1 gold based on most servers. A generally good guideline to follow would be one silver for every skill on the lockbox (ex. Thorium Lockboxes would be 2 gold 50 silver .\r\n# If you ask a Rogue before opening, usually he/she will open it for free.",},
			["Lock and Load"] = { content = "'''Lock and Load''' is a Clearcasting-type talent. When it activates, it causes your next two Arcane Shots or Explosive Shots (the 51-point Survival talent) to be fired with no cooldown (though it still invokes the global cooldown), no mana cost, and no ammo expenditure. Much like the Warlock talent, [[Nightfall_(Warlock_talent)|Nightfall]], its primary source of activation is the Hunter DoT, Serpent Sting.\r\n==Notes==\r\nThis talent will also proc on [[Serpent Sting]] damage ticks.\r\n==Past changes==\r\nOriginally three shots in beta, but balancing team reduced it to one, hunter team bumped it up to two.",},
			["Loganaar"] = { content = "'''Loganaar''' is a level 51 [[druid trainer]] located in [[Nighthaven]] in the [[contested]] territory of [[Moonglade]].\r\nHe starts the quest Morthis Whisperwing.",},
			["Logannas"] = { content = "'''Logannas''' is a level 52 [[alchemy]] [[vendor]] located in [[Feathermoon Stronghold]] in the [[contested]] territory of [[Feralas]].\r\nHe sells recipes for [[Ghost Dye]] and [[Nature Protection Potion]] in limited quantities.\r\nSee [[List of Feralas NPCs]].",},
			["Logistics Officer Ulrike"] = { content = "'''Logistics Officer Ulrike''' is a level 62 [[Honor Hold]] faction [[vendor]] located at [[Honor Hold]] in the [[contested]] territory of [[Hellfire Peninsula]]. Her coordinates are .\r\nSee [[List of Hellfire Peninsula NPCs]].\r\n==Notes==\r\n As of patch 2.4.0 Outland faction quartermasters also sell reputation based, class specific armor sets. Each class has between one and three different armor sets, each of which are PvP oriented, superior quality loot. See",},
			["Loh'atu"] = { content = "'''Loh'atu''' is a level 45 [[quest giver]] located at [[Talrendis Point]] in the [[contested]] territory of [[Azshara]]. He is thought to be affiliated with the [[Alliance]], but he is in fact [[friendly]] to both [[factions]] and offers the quests to both.\r\nHe starts the following quests:\r\n* Spiritual Unrest\r\n* A Land Filled with Hatred\r\nSee [[List of Azshara NPCs]].",},
			["Lok'vadnod"] = { content = "A '''lok'vadnod''' is a prestigious song composed for a specific individual. It is commonly seen as the greatest honor the [[orc]]s can grant to an individual. Great chieftains, shamans, and warchiefs are the usual candidates for ''lok'vadnod'', and [[Orgrim Doomhammer]], [[Grom Hellscream]], [[Broxigar the Red]] and [[Durotan]] have all been granted ''lok'vadnod''. Thrall does not have one in his name, as ''lok'vadnod'' are composed after the tale of a hero is finished, when they die. \r\nIt is not known how many non-orcs in total have been honored with a ''lok'vadnod'', but to date, only one [[human]] has been granted one: [[Taretha Foxton]], the childhood friend of Warchief [[Thrall]].\r\n===Recipients===\r\n* [[Orgrim Doomhammer]]\r\n* [[Grom Hellscream]]\r\n* [[Durotan]]\r\n* [[Broxigar the Red Axe]]\r\n* [[Taretha Foxton]]",},
			["Loken"] = { content = "'''Loken''' is a [[giant]] and is presumed to be the leader of the [[iron dwarves]] in [[Northrend]]. Having previously served the [[Pantheon]], he has recently heard the calls of the old god [[Yogg-Saron]]. Since that moment, he has lost all faith in the Titan's vision and considers the Old God his new master. He can be encountered as the final boss in the [[Halls of Lightning]].\r\nHe is also involved in the following quests:\r\n*The Delicate Sound of Thunder\r\n*Put on Your Best Face for Loken\r\n*Loken's Orders\r\n*The Reckoning\r\n==Abilities==\r\n*'''Lightning Nova''': Emit a pulse of energy that deals 6013 to 6987 Nature damage to enemies within 20 yards. (5 sec cast)\r\n*'''Pulsing Shockwave''': Shocks all enemies every 2 sec., dealing damage based on distance from Loken. Damage is increased the greater the distance away from Loken.\r\n==Tactics==\r\nThe damage of his aura is range dependent, so stay as close as you can. If he casts Lightning Nova move out and return as soon as his cast has finished to minimize aura damage.\r\n==Loot==\r\n<!---->\r\n===Encounter in [[Howling Fjord]]===\r\n Come, minions! Your master calls!\r\n The work of your brothers in the [[Storm Peaks]] has reached a frenzied pace. Soon, Father will be freed.\r\n Your brothers to the north have subjugated the stone behemoths and set them on the path to [[Ulduar]]. Soon, the remaining defenses of the [[Pantheon]] will be neutralized.\r\n The three fissures opened by the mortals of this region must be silenced. The earth hears and sees what we do and will continue to interfere with our efforts if the way is not closed.\r\n Bury this place, your master demands it!\r\n===Encounter in [[Grizzly Hills]]===\r\nImage of Loken says: You're late, overseer.\r\nImage of Loken says: Destiny will not wait. Your craftsmen must increase their production of the war golems before the stone giant leader and his army reach Ulduar.\r\nImage of Loken says: Tell your rune-smiths to continue converting what stone giants you can. Those that will not submit must be destroyed.\r\nImage of Loken says: If the stone giants interfere with our work at Ulduar, I will hold you and your thane responsible. Mortals must not be allowed to come to the aid of the giants.\r\nReturn to your duties, overseer. Be certain to impress upon your workers the urgency of their tasks.\r\n===Encounter in [[Halls of Lightning]]===\r\nUpon entering his room:\r\n* \"I have witnessed the rise and fall of empires. The birth and extinction of entire species. Over countless millennia the foolishness of mortals has remained beyond a constant. Your presence here confirms this.\"\r\n* \"My master has shown me the future, and you have no place in it. Azeroth will be reborn in darkness. [[Yogg-Saron]] shall be released! The Pantheon shall fall!\"\r\nUpon being aggroed:\r\n* \"What hope is there for you? None!\"\r\nWhen casting Lightning Nova:\r\n* \"You cannot hide from fate!\"\r\n* \"Come closer. I will make it quick.\"\r\n* \"Your flesh cannot hold out for long.\"\r\nUpon slaying a player:\r\n* \"Only mortal...\"\r\n* \"I... am... FOREVER!\"\r\n* \"What little time you had, you wasted!\"\r\nUpon reaching \r\n75% health:\r\n* \"You stare blindly into the abyss!\"\r\n50% health:\r\n* \"Your ignorance is profound. Can you not see where this path leads?\"\r\n25% health:\r\n* \"You cross the precipice of oblivion!\"\r\nUpon death:\r\n* \"My death... heralds the end of this world.\"",},
			["Lokholar the Ice Lord"] = { content = "'''Lokholar the Ice Lord''' is a massive [[ice elemental]] spirit [[boss]] summoned by the [[Horde]] in the [[Alterac Valley]] battleground.\r\n==Behavior==\r\nLok'holar, once successfully summoned, will patrol around the [[Field of Strife]] for ten minutes before pushing into the [[Stormpike]] base. As of [[Patch 1.11]], Lok'holar no longer attacks enemy NPCs, and will only attack enemy players. If Lok'holar successfully reaches the Stormpike base, he will stand in front of the [[Dun Baldar]] keep and stay there unless provoked by enemy players, in which case he will give chase until he either leashes back, kills the enemy player, or is killed himself.\r\nLok'holar starts out relatively weaker than his counterpart [[Ivus the Forest Lord]], but he can grow significantly stronger over time if supported by the Horde offensive. Lok'holar will gain strength each time an [[Alliance]] player in the vicinity is killed, and this is shown by the yell: \"Lok'holar drinks in your suffering! Let your essence congeal with Lok'holar!\" However, Lok'holar, while powerful, is not invincible. Without significant Horde assistance, he can be killed by the enemy Alliance forces with relative ease. Lok'holar can be [[kite]]d, but due to his frost-based attacks is not easy to do, as he can often [[snare]] or [[root]] the kiter and kill it before returning to his original position or advance movement.\r\nLok'holar is notorious for his small attackable melee body, with melee players often having to be right dead-center of his body in order to successfully attack him. If he's moving around a lot, this can make bringing him down difficult.\r\n==Abilities==\r\n*Frost Bolt — Deals 638-862 Frost Damage and reduces movement speed by 50% for 4 seconds. \r\n*Frost Nova — Deals 188-211 Frost Damage and immobilizes for 8-10 (correction needed) seconds.\r\n*Frost Shock\r\n*Blizzard\r\n*Ice Tomb (10 seconds stun)\r\nThe buff he gains upon killing an Alliance player appears to be \"Swell of Souls\". It increases his size, speed, and attack power by 75. It apparently stacks 10 times for 750 maximum additional attack power.\r\n==Quotes==\r\n*WHO DARES SUMMON LOKHOLAR? The blood of a thousand Stormpike soldiers shall I spill...none may stand against the Ice Lord!\r\n*I drink in your suffering, mortal. Let your essence congeal with Lokholar!\r\n*Your base is forfeit, puny mortals!",},
			["Lokhtos Darkbargainer"] = { content = "'''Lokhtos Darkbargainer''' is a level 60 [[Dark Iron dwarf]] found in the [[Grim Guzzler]], a tavern in [[Blackrock Depths]].\r\nLokhtos was the overseer of the [[Thorium Brotherhood]] during the [[War of the Three Hammers]] and the Dark Irons' enslavement in [[Blackrock Depths]]. When the rest of the guild escaped, the aging Lokhtos chose to stay behind, believing he would only slow his compatriots. Despite his abdication, Lokhtos remains a respected member of the Brotherhood, though he keeps his allegiance to himself to avoid reprisal from [[Ragnaros]] and his elemental minions. When not at work in the forges, Lokhtos is often at the [[Grim Guzzler]]; from a darkened corner he quietly conducts business on the guild’s behalf. Lokhtos’s opinion of a person has a definite effect on how the rest of the guild views the person.\r\nSee [[Blackrock Depths NPCs]].\r\n==Reputation Quests==\r\nLokhtos Darkbargainer accepts items from Blackrock Depths to raise your reputation with the Thorium Brotherhood.\r\nHe starts the following quests:\r\n* Favor Amongst the Brotherhood, Dark Iron Ore\r\n* Favor Amongst the Brotherhood, Fiery Core\r\n* Favor Amongst the Brotherhood, Lava Core\r\n* Favor Amongst the Brotherhood, Core Leather\r\n* Favor Amongst the Brotherhood, Blood of the Mountain\r\nItems required and reputation rewards:\r\nYou start with a reputation with the Thorium Brotherhood. The amounts needed to move up to the next level of reputation are:\r\n* to : 3,000 points \r\n* to : 6,000 points \r\n* to : 12,000 points \r\n* to : 21,000 points\r\n==Reputation Recipes==\r\nWhen you reach reputation becomes with the Thorium Brotherhood, Darkbargainer will start selling plans and pattern available to friends of the Brotherhood. As your reputation goes higher, you will gain access to more plans.\r\n========\r\n*[[Transmute: Elemental Fire]] (Alchemy 300)\r\n*[[Dark Iron Bracers]] (Blacksmithing 295)\r\n*[[Enchant Weapon - Strength]] (Enchanting 290)\r\n*[[Molten Helm]] (Leatherworking 300)\r\n*[[Corehound Boots]] (Leatherworking 295)\r\n*[[Flarecore Gloves]] (Tailoring 300)\r\n========\r\n*[[Fiery Chain Girdle]] (Blacksmithing 295)\r\n*[[Dark Iron Helm]] (Blacksmithing 300)\r\n*[[Dark Iron Destroyer]] (Blacksmithing 300)\r\n*[[Dark Iron Reaver]] (Blacksmithing 300)\r\n*[[Enchant Weapon - Mighty Spirit]] (Enchanting 300)\r\n*[[Lava Belt]] (Leatherworking 300)\r\n*[[Black Dragonscale Boots]] (Leatherworking 300)\r\n*[[Flarecore Mantle]] (Tailoring 300)\r\n*[[Flarecore Robe]] (Tailoring 300)\r\n========\r\n*[[Fiery Chain Shoulders]] (Blacksmithing 300) \r\n*[[Dark Iron Leggings]] (Blacksmithing 300) \r\n*[[Dark Iron Gauntlets]] (Blacksmithing 300) \r\n*[[Black Amnesty]] (Blacksmithing 300) \r\n*[[Blackfury]] (Blacksmithing 300) \r\n*[[Enchant Weapon - Mighty Intellect]] (Enchanting 300)\r\n*[[Chromatic Gauntlets]] (Leatherworking 300) \r\n*[[Molten Belt]] (Leatherworking 300) \r\n*[[Corehound Belt]] (Leatherworking 300) \r\n*[[Flarecore Leggings]] (Tailoring 300)\r\n========\r\n*[[Dark Iron Boots]] (Blacksmithing 300) \r\n*[[Nightfall (Axe)|Nightfall]] (Blacksmithing 300) \r\n*[[Ebon Hand]] (Blacksmithing 300) \r\n*[[Blackguard]] (Blacksmithing 300)\r\n==Sulfuron Hammer==\r\nIf you give a Sulfuron Ingot to Lokhtos Darkbargainer, he will provide you with plans to the Sulfuron Hammer, a two-handed mace which requires a skill level 300 [[blacksmith]] to craft. The Sulfuron Hammer can then be combined with the Eye of Sulfuras to create Sulfuras, Hand of Ragnaros.",},
			["Lok Orcbane"] = { content = "'''Lok Orcbane''' is a level 25 [[quilboar]] found in the [[Barrens]].\r\n[[Mangletooth]] wants Loc's skull.\r\n==Quests==\r\n*Betrayal from Within\r\n==Loot==\r\n*Lok's Skull ''(Quest Item)''",},
			["Lolo the Lookout"] = { content = "'''Lolo the Lookout''' is a level 39 [[quest giver]] located in [[Faldir's Cove]] in the [[contested]] territory of [[Arathi Highlands]].\r\nHe starts the quest Land Ho!.\r\n==A Popular Name==\r\nIt seems being that Lookout Captain Lolo Longstriker of the [[Thorium Brotherhood]] seems to be the Lookout for [[Thorium Point]], that the name 'Lolo' might be a popular name for most lookouts. If Blizzard made this intentional or not is still undetermined.",},
			["Lone druid"] = { content = "'''Lone druids''' are druids without animal companions. Druids are closely tied to nature - of all the classes, they represent the closest connection to the natural world. Because of this, many druids befriend specific animals, taking them as their animal companions. A druid's animal companion serves as a steadfast ally, and is useful in combat, vigilance and espionage. However, some druids - particularly among the night elves - give up the standard animal companions. They may feel that it is unfair to put a living member of the natural world through the perils of adventure; they might feel they work better alone; or they might have some other reason. These lone druids focus their extra energy on improving either their combat or spellcasting abilities.\r\n''The playable [[druid]] in World of Warcraft is likely the lone druid version of a [[druid of the wild]]. Like lone druids, playable druids do not have animal companions, and instead rely on spellcasting or shapeshifting abilities.''\r\n==Famous/Named==\r\n*[[Cerise Moonrain]]",},
			["Lone wolf runemaster"] = { content = "'''Lone wolf runemasters''' alter the traits of regular [[runemaster]]s a bit. Many of them travel alone, and have no need of runes that empower others — but extra skill with the fists is always in need. Lone wolf [[runemaster]]s cannot place or empower runes on any creature or object other than themselves. Thus, they cannot use glyphs at all, and can place sigils only on their own bodies. Lone wolf runemasters are the only runemasters who know the secret of the rune of the flashing blade, though it is merely a simple rune. It is the pattern made in the sand by skilled, dueling fighters.\r\nOther lone wolf runemasters join adventuring parties but see no reason to waste their skills on others. Let them take care of themselves! Or, better yet, let the runemaster pound their foes into paste; then her allies won’t have to worry. Among races that produce runemasters (which are few), lone wolf runemasters are common among [[pandaren]], as these creatures often embark on solitary expeditions to explore [[Azeroth]]. [[Tuskarr]] occasionally become lone wolf runemasters as well, and the occasional male [[naga]] runemaster is undoubtedly a lone wolf — they leave most of the spellcasting to the women.",},
			["Longbraid the Grim"] = { content = "'''Longbraid the Grim''' is a level 35 [[quest giver]] located outside [[Dun Modr]] in the [[Alliance]]-aligned territory of the [[Wetlands]].\r\nHe starts the quest A Grim Task (Elite).\r\nSee [[List of Wetlands NPCs]].",},
			["Longjaw Mud Snapper"] = { content = "==Source==\r\nThis item can be crafted using [[Cooking]] (50); taught by Recipe: Longjaw Mud Snapper. \r\nThis item can be purchased for c=20 gold from:\r\n* Innkeeper Velandra in [[Silvermoon City]]\r\n* Caregiver Breel in [[The Exodar]]\r\n* Wigcik in [[Stranglethorn Vale]]\r\n* Innkeeper Skindle in [[Stranglethorn Vale]]\r\n* Shrye Ragefist in [[Alterac Valley]]\r\n* Brogus Thunderbrew in [[Alterac Valley]]\r\n* Hal McAllister in [[Hillsbrad Foothills]]\r\n* Stuart Fleming in [[Wetlands]]\r\n* Vernon Hale in [[Redridge Mountains]]\r\n* Lard in [[The Hinterlands]]\r\n* Himmik in [[Winterspring]]\r\n* Wik'Tar in [[Ashenvale]]\r\n* Kilxx in [[The Barrens]]\r\n* Innkeeper Heather in [[Westfall]]\r\n* Harklane in [[Feralas]]\r\n* Khara Deepwater in [[Loch Modan]]\r\n* Innkeeper Brianna in [[Redridge Mountains]]\r\n* Innkeeper Thulbek in [[Stranglethorn Vale]]\r\n* Gikkix in [[Tanaris]]\r\n* Laird in [[Darkshore]]\r\n* &quot;Dirty&quot; Michael Crowe in [[Dustwallow Marsh]]\r\n* Innkeeper Wiley in [[The Barrens]]\r\n* Heldan Galesong in [[Darkshore]]\r\n* Kriggon Talsone in [[Westfall]]\r\n* Gretchen Vogel in [[Redridge Mountains]]\r\n* Innkeeper Kimlya in [[Ashenvale]]\r\n* Talaelar in [[Teldrassil]]\r\n* Caregiver Topher Loaal in [[Bloodmyst Isle]]\r\n* Heron Skygaze in [[Ghostlands]]\r\n* Oloraak in [[Shattrath City]]",},
			["Longship"] = { content = "A longship is a 75-foot-long ship with forty oars and a total crew of 50. It has a single mast and a square sail. It can carry fifty tons of cargo or 120 soldiers. A longship can make sea voyages. It moves about 3 miles per hour when being rowed or under sail.",},
			["Longshore"] = { content = "'''Longshore''' is the vast stretch of coastline along [[Westfall]]. Travel along the coast is hazardous as swarms of [[Murloc]]s roam the beaches unchecked. Longshore is also where [[Night Elf]] [[Druids]] must travel to find half of the amulet required to gain [[aquatic form]] at level 16. The other half is in [[Darkshore]] on [[Kalimdor]].",},
			["Long Tail Feather"] = { content = "==Source==\r\n==Long Tail Feather as an ingredient==\r\nThis item is used to make: \r\n* Fletcher's Gloves",},
			["Long Vigil"] = { content = "The '''Long Vigil''' was the period of history during which [[Tyrande Whisperwind]] and her [[sentinel]]s kept watch over [[Kalimdor]], while [[Malfurion Stormrage]] and the other [[druid]]s slumbered in the [[Emerald Dream]]. It ended with the awakening of the druids at the second coming of the [[Burning Legion]].",},
			["Long Wash"] = { content = "'''The Long Wash''' is ironically enough the shortest stretch of coast in [[Darkshore]]. It is the desolate stretch of sand that runs south from the [[Ruins of Auberdine]] in [[Darkshore]] until due west of [[Ameth'Aran]]. The shore is gloomy and dark under the perpetual overcast skies of Darkshore, and the beach is littered with debris and the carcasses of dead sea animals. [[Murloc]]s have recently been showing up with greater frequency along the coastline.\r\nDuring the [[War of the Thorns]], the area became a small battlefield between the night elves and the invading [[Horde]], hunting for food.\r\n==NPCs==\r\n*[[Luminous Grouper (Darkshore)|Luminous Groupers]]\r\n*[[Tide Crawler (Battle for Azeroth)|Tide Crawlers]]\r\n*[[Shimmershell Snail]]s\r\n==Etymology==\r\n\"Wash\" is an obsolete word meaning \"the portion of the shore washed by the waves\".",},
			["Loorana"] = { content = "'''Loorana''' is a level 49 [[bread]] and [[drink vendor]] located in [[Camp Mojache]] in the [[contested]] territory of [[Feralas]].\r\nSee [[List of Feralas NPCs]].",},
			["Loosely Turned Soil"] = { content = "'''Loosely Turned Soil''' can be found in the graveyard wing of [[Scarlet Monastery]] during the [[Hallow's End]] seasonal event.\r\nUsing the Dreary Candle on this object summons the [[Headless Horseman]].\r\n==Quests==\r\nCall the Headless Horseman",},
			["Loose Chain collection"] = { content = "Note: This set is almost identical in looks to the [[Flimsy Chain Armor Set]]",},
			["Loot"] = { content = "In [[World of Warcraft]], '''loot''' can mean a couple of things:\r\n# Stuff (treasure: [[item]]s or [[money]]) you get from [[mob]]s or containers (barrels, boxes, chests, etc).\r\n# The act (to loot; looting) of getting the stuff mentioned above.\r\n===Looting While Solo===\r\nWhen soloing, looting is easy — a \"[[lootable]]\" corpse emits a \"glistening\" effect, and the cursor will change to the \"trade\" cursor when you mouse over the corpse. Simply right-click (or Command-click on a Mac with 1-button mouse) on the corpse of the mob you just killed, and a window will pop up containing any loot the mob was carrying. (Sometimes this window is empty, which means the mob had no loot.) Using Shift-right/Command-click \"autoloots\" the corpse, which picks up all items except \"[[Bind on Pickup|bind on pickup]]\" items.\r\n===Looting While In A Party===\r\nIn [[Party|group]] situations, looting can be much more complicated. The leader of the group can set the group [[Loot Level|looting parameters]], as well as the [[Loot Quality Threshold|threshold]] where items of particular quality are automatically [[roll]]ed for. There are five group looting parameters:\r\n* ''Free-for-all:'' (FFA) First-come, first-serve. You snooze, you lose.\r\n* ''[[Main Looter|Master Loot]]:'' One person in the group, designated by the [[leader]], loots all corpses and distributes the loot.\r\n* ''Round-robin:'' Party members take turns looting corpses.\r\n* ''[[Group Loot]]:'' Like Round-robin, except that there is a threshold set by the leader for which items must be rolled off (see details in following discussion).\r\n* ''[[Need before Greed]]'': \"Pass\" is automatically selected for party members who cannot use the item.\r\nIn all loot settings, money on the corpse is distributed as evenly as possible among all the party members.\r\n[[Quality|Grey or white]] items on the corpse can be picked up by whomever is looting it.\r\n[[Quest]] Loot: Quest loot is on a separate loot distribution and there are two common modes for this to occur. 1) In quests where the party is to collect one of a specific item from a specific mob (''Collect the head of (mob name here)'') then regardless of loot setting, the mob will indicate lootable by every party member with the quest (and without the object). Each member may loot the quest item off the corpse. The other loot on the corpse is subject the party loot setting. 2) In other quests which require collecting several items of a type (harpy feathers for example), the quest items will drop on some mobs and be looted in the normal way, except that if the current looter can't collect the items (not on quest, already has full set) then the quest loot is FFA for those members who can still pick up the quest items. Other items on the corpse are governed by the party loot setting. On some quests the quest loot is always free-for-all and this may be the above mechanic gone haywire. Some quests where the party is collecting one item will use the named mob mechanism (1) (the [[Shaman Voodoo Charm]] from The Sleeping Druid quest, for example, where all party members can get the charm off the same shaman.)\r\n===Loot Options: Need, Greed, and Pass===\r\nItems of [[Uncommon|good (green) quality]] or higher might not be immediately lootable, depending on the [[Loot Quality Threshold|loot rolling threshold]] established by the party leader. When an item is available that falls within that rolling threshold, the looter is prohibited from taking the item and a 'roll window' pops up for all party members with an image of the item and three buttons — a pair-of-dice button, a coin button, and a red circle with diagonal line button. \r\n===Group Policies and Other Loot Options===\r\n*Some groups have a policy that, when a [[bind on pickup]] item is found as loot, ''all characters are expected to 'pass' on the item'' so that a more deliberate selection can be made. It's good to know if your group follows this policy before you find such an item. While this system does nothing to stop a [[Loot ninja|ninja]] from taking an item, some groups still insist on using it. Going against the grain while in a group usually just creates unrest and fights over loot.\r\n*If you are the group leader, or the group leader seems levelheaded, it would be wise to use (or ask to use) the normal, built-in looting systems. While a ninja can still roll need on items they do not actually need, other people who do need the item will still have a shot at it, rather than the ninja just picking it up after everyone passes, or rolling after everyone else has passed.\r\n*Often, Instances will be run with one character of much higher level leading the charge. This is frequently done in clans where senior members want to help others in acquiring good loot. In these cases, it is common that the senior party member will serve as party leader and set loot settings to Master Loot, so as to best distribute all loot.\r\n*Another common protocol for distributing chest loot is 'high to low', where the highest level member of the group gets first crack at the chest, takes anything he likes, then anything left is available for the next highest level group member, etc., until the chest is empty or no one wishes to take anything else. Money in chests is distributed evenly among the party members who are nearby just like money from corpses.\r\n*Many players consider it to be very rude if someone intentionally loots a corpse while combat is still going on. To avoid any conflicts, it is best to wait until combat is over and everyone has been rezzed (waiting for everyone to be rezzed is particularly important; a player can't roll on any items if they are not close enough to the body that is being looted).\r\nNote that loot from containers — chests, [[food]] crates, and the like — as opposed to corpses, also uses the party loot threshold (if one is in effect), although the container will always be lootable by any party member. If the container holds a high-quality item, that item will be rolled on (or not), the same as if it were looted from a corpse. Since this is a recent change (Patch 2.1.0), many groups may still require rolling on content, or at least to link the common items such as foods and potions to give to those who need it.\r\n===Miscellaneous Looting Info===\r\nIn battlegrounds, players can loot enemy corpses. This will remove their insignia so that they must revive at the [[graveyard]], and give the looter a small sum of money. Note that if the player's ghost is running toward the corpse when its insignia is removed, he'll have to run all the way back to the graveyard to resurrect, so it may be wise to wait a moment before looting. Looting the player's corpse will also force its spirit to release, if they have not already done so, thus preventing their ghost from spying on the area around their corpse.",},
			["Looting"] = { content = "#REDIRECT [[Loot]]", redirect = "Loot",},
			["Loot council"] = { content = "In the computer role playing games of old, one player managed a whole party with several members. When a new item became available, the player decided which party member would profit most, and give the item to them. Overall progress was the only goal. In its purest form, a loot council works exactly the same, one person decides which raid members get which items. If that player is impartial and the decisions are correct, there can be no issues about \"justice\", because overall progress is the one primary goal in [[raid]]ing.\r\nAs it's nearly impossible for a single person to be godlike and impartial, most raids use several people to take this kind of decision - a loot council. Normally the loot council also has less absolute powers than the pure form. A frequently seen loot council policy is to restrict items by class and/or talent build. Loot councils are always used to give a higher emphasis on the success of the raid as a whole over the selfish interests of individual raid members. Commonly used categories to limit loot to certain classes/builds are:\r\n*Tank (prot warrior or paladin, bear druid)\r\n*Melee DPS (arms or fury warrior, rogue, enhancement shaman, cat druid, ret paladin)\r\n*Spell DPS (mage, warlock, shadow priest, elemental shaman, moonkin druid)\r\n*Healer (holy priest or paladin, resto shaman, tree druid)\r\nFor some spell DPS items it is a good idea to restrict them further by damage type (nature, fire, frost, shadow), but this happens normally automatically because +nature damage is of no particular use to a warlock.\r\nDespite not being a hybrid class in the true sense of the word, hunters can also often find some use for nearly anything they're able to equip. Depending on playstyle and preference, and keeping usefulness towards the raids goals in mind, hybrids and hunters should be watched very closely, to avoid loot whoring. Usually this means that all players should give their build to their class leaders, so they can judge into which category the player belongs.\r\nUsually the main tank(s) are a class of their own. Since the raid's main tank is extremely important, they are frequently given precedence on any tanking gear they need.\r\n====Advantages====\r\n* The people on the council (should) know what is best for the guild/raid and can give loot to where it is most needed or deserved.\r\n* Loot Council can sometimes have less of a cutthroat feeling than DKP, where there is a high pressure to be always at the top of the list.\r\n* Many of the problems of other (point) loot systems can be avoided, including inflation or hate bidding (draining).\r\n* Exceptionally rare items can be given to those who need them most, rather than who has the most points at the time (for example, a Thunderfury to the main tank).\r\n====Disadvantages====\r\n* '''Loot Council is only as fair as the people on the council.''' One corrupt council member can destroy a whole guild.\r\n* It requires more work on the part of council members to pay attention to and keep track of that which determines loot distribution.\r\n* Actually awarding loot can take more time as council members debate whom it should go to.\r\n*Loot council a system assumes that the people making the decisions are better informed *than the people that will end up using the Items. It's in most cases a wrong assumption. \r\n*Loot council systems can result in a huge waste of resources of the guild. i.e.: Time. It takes away the “cost” of bad decisions by the players themselves. The cost of bad decisions made by the council are now hidden, and everybody ends up paying for them. Since those costs are hidden, they will be more frequent.\r\n*A loot council system destroys the “ME Factor” so important in incentive application. It can take away the control of equipping the character from the player. Depending on other factors, this will result in a destruction of the incentives to Raid. For young and non homogeneous raiding guilds, this process will result in a lot of drama and in a “shortage” of raiders.\r\n*Loot council system generates accusations of corruption and grievances from members towards the people that are making the decisions. It breeds unrest inside the guild, especially if the guild has a non homogeneous raid group.\r\n*Loot Council Systems could create a “caste” of people inside the guild that are not rewarded because they have the merit to be so, but in fact are rewarded because they have good relations with the ones distributing the Loot.\r\n*These types of loot distribution systems incentive a lack of dedication from people near the decision makers, if a tank knows, no matter what, he will be handed over good gear, he will not be so eager to farm for better gear, or even to show up in every raid. In fact the Loot Council System will make it more difficult to discover who really is contributing more to the Raid.\r\n*Many of the bad things this type of distribution system brings up to the equation are hidden. And most people won’t realize that it is the Council that caused these problems, but the problems will be there nonetheless. \r\n*Guilds that have problems such as: shortage in attendance, too many “casual” raiders and people that does not put effort in raiding, drama related to loot, drama related to the alleged “inflation” of the Point systems will likely not benefit from this arrangement. \r\n*Guilds that have homogeneous raiding groups, a homogeneous commitment and attendance, non overcrowded guilds and guilds doing the very high end content of the game in server with little “competition” can benefit from this arrangement IF the main problem in the guild is people hoarding DKPs and hence not equipping themselves properly.",},
			["Loot ninja"] = { content = "A '''loot ninja''', aka '''ninja looter''' or simply '''ninja''' (on some servers, particularly in the EU, it is also called '''pirate looting''' since pirates were reknown for stealing, which seems like a more logical name for the term), is a [[player]] who takes [[loot]] to which he or she is not entitled. The act is referred to as ninja looting or ninjaing. The term predates World of Warcraft, and originated with the notion of looting as quickly as possible (that is, with ninja-like speed). The term seems to have a few different meanings depending on whom you ask, including:\r\n* A player who, when in a group, [[roll]]s \"Need\" on everything regardless of if he or she can use it, also known as (despite its name) a greeder,\r\n* A player who takes everything not nailed down in an [[instance]] without asking: [[Chest (container)|chest]]s, [[ore]]s, [[skin]]s, [[herb]]s, etc., \r\n* A player who rolls on an [[BoP]] item that everyone else has passed on or a player who loots a corpse without permission after everyone has passed on a [[BoP]] item. Generally, groups decide how to best make use of the item that no one can use, sometimes [[DPS]] classes will back out of +healing/+spell damage (as opposed to just +spell damage) even if it is an upgrade and will ask for the item if no one else needs it. Additionally, if no one needs it and no one reconsidered, it often goes to a [[enchanter]], who [[disenchant|disenchants]] it, and then the group rolls for the materials acquired from the disenchanted item. Sometimes players loot items for more sentimental reasons (like \"town clothes\" in RP servers) and will normally pass on it unless no one else needs it. If there are no enchanters in the group and no one changes their mind, generally the group will roll for it's NPC value.\r\n* A player who loots a chest or harvests a resource while another player is fighting the [[mob]]s which were defending it, possibly using [[stealth]] or a [[dash]] ability to aid in this, and \r\n* A [[party]] or [[raid]] [[leader]] who changes the looting system to \"[[Main Looter|Master Loot]]\" near the end of a boss kill and steals the loot off of a [[corpse]] without letting other players roll for the [[item]]s. Especially one who sets up a group just for the first or second boss, and then [[hearthstone|hearthstones]] without speaking or claiming he has to sleep or work, meanwhile setting up another group to loot it again, perhaps prominent of [[Gold Farmer|Gold Farmers]].\r\n* A player's reputation can go down if they continuously win upgrades over other players. It is not uncommon for people to whine if a player has won 3 out of 3 items for their class, sometimes being labeled as a roll hacker. The worst case is generally when 2 greens drop from trash, both being upgrades to the same slot, and the player equips the items (and therefore binds the items to themself). Later in the raid or instance, a [[BoP]] Blue drops from a boss and the same player wins that item (thus binding it to themself). In this situation ,the party may be displeased as not only could the greens have been sold on the [[Auction House]] but it is very likely they could have upgraded two other players with the same role. \r\n[[Gold Farmer|Gold farmers]] also try to join instance groups in order to ninja/pirate loot items and sell them.\r\nLoot ninjas are, understandably, not well liked by other players. Often, a ninja will get a bad reputation on a [[realm]] which eventually prevents them from being invited to participate in any high level instances. Many guilds also have rules stating that ninjas/pirates should be kicked from the [[guild]] on their first offense. \r\n==See Also==\r\n*[[Blacklist]]\r\n==World of Warcraft Game Design==\r\nSeveral features in [[World of Warcraft]] were designed to minimize the opportunities for players to ninja/pirate loot, addressing problems which had occurred in earlier games.\r\n* A mob is tagged by the first [[player character]] or [[group]] to damage it, and it can not be looted by anyone else.\r\n* [[Rogue]]s, [[druid]]s and [[Night Elf|Night Elves]] cannot remain stealthed while looting or harvesting resources.\r\n* The [[Loot|loot options]] in the game allow a person to roll on items that drop. While a ninja/pirate may roll on items he or she shouldn't, there is a chance the more deserving player will win.",},
			["Lor'khan"] = { content = "#REDIRECT [[Zealot Lor'Khan]]", redirect = "Zealot Lor'Khan",},
			["Lor'themar"] = { content = "#REDIRECT [[Lor'themar Theron]]", redirect = "Lor'themar Theron",},
			["Loramus Thalipedes"] = { content = "'''Loramus Thalipedes''' is a level 60 [[quest giver]] located on an island southeast of [[Hetaera's Clutch]] in the [[contested]] territory of [[Azshara]]. From his attirement and remarks it can be concluded that Thalipedes is a [[demon hunter]]. He has 3 elite felhounds guarding him.\r\nHe starts the quests:\r\n* Loramus\r\n* Breaking the Ward\r\n* The Name of the Beast\r\n* Azsharite (Elite)\r\n* The Formation of Felbane",},
			["Lordaeron"] = { content = "'''Lordaeron''' (also known as '''Lordaeron Empire''') is an extinct [[human]] [[kingdom]] that once occupied substantial territory on the [[Lordaeron (continent)|northern subcontinent]] of the [[Eastern Kingdoms]]. Originally one of the [[Seven Kingdoms]] to emerge during the collapse of [[Arathor]], Lordaeron was ruled by the [[House of Menethil]] and provided refuge for the people of [[Stormwind]] following that kingdom's destruction at the end of the [[First War]]. During the [[Second War]] Lordaeron spearheaded the [[Alliance of Lordaeron|first Alliance's]] campaign against the [[Horde (pre-Thrall)|Horde]], but was almost entirely consumed by the [[Scourge]] during the [[Third War]]. Its former territory is now contested between the Scourge, the [[Forsaken]], and fragmented pockets of human resistance, most notably the [[Scarlet Crusade]] and the [[Argent Dawn]].\r\n==City-state of Arathor==\r\nLordaeron was settled by the lords of [[Strom]], capital of the nation of [[Arathor]], desirous of the verdant lands to the north. The capital [[City of Lordaeron|city]] served as a spiritual destination for the citizens of the seven human kingdoms.\r\n==Lordaeron in Warcraft II==\r\n*'''Leader:''' ''King Terenas II''\r\n*'''Nation Color:''' ''White''\r\n*'''Background:''' ''Ruled by the benevolent King Terenas II, the nation of Lordaeron stands as the last bastion of hope for humanity. The armies of Lordaeron were the first to heed the call to arms issued by Sir Lothar and the people of Azeroth. As patron of the Alliance, King Terenas II has assumed the heavy mantle of leadership to protect all who abide in his domain. The armies of Lordaeron are deeply religious and are driven by the belief that humanity must stand steadfast against the blasphemous onslaught of the Horde.''\r\n==The Alliance of Lordaeron==\r\nFollowing the opening of the [[Dark Portal]], the nations of [[Azeroth]] and [[Khaz Modan]] were conquered by the [[Horde (pre-Thrall)|Horde]]. The refugees from Azeroth, led by Lord [[Anduin Lothar]], fled across the sea to Lordaeron. There, Lothar convinced the leaders of the human nations, as well as the [[dwarf|dwarves]] of [[Ironforge]], [[gnome]]s of [[Gnomeregan]], and [[high elf|high elves]] of [[Quel'Thalas]], to join forces in the [[Alliance of Lordaeron]].\r\nUnder the leadership of King [[Terenas Menethil II]] and Lord Lothar, the Alliance was victorious, pushing the Horde back to the Dark Portal, and destroying the gateway to the orcs' homeworld. Lothar fell in the assault on [[Blackrock Spire]], and with the loss of his political skill, rifts developed between the Alliance nations. The main issue of dispute was a tax levied by King Terenas to finance the internment of the orcs. Though Lordaeron attempted to retain its central role, several nations pulled their support from the Alliance.\r\n==The Scourge of Lordaeron==\r\nFollowing years of debate over the internment of the orcs, a [[plague]] appeared in the north of Lordaeron. As it spread throughout the towns and cities of Lordaeron, one after another fell to the [[Scourge]], most notably [[Andorhal]] and [[Stratholme]]. Finally, with the corruption of the heir to the throne of Lordaeron, Prince [[Arthas Menethil]], the capital city itself succumbed. In an ironic twist of fate, it was Lordaeron that lay in ruins, with refugees streaming to [[Khaz Modan]] and [[Azeroth]].\r\nArthas briefly assumed the title of King, and ruled as an agent of the [[Scourge]], before the eruption of a civil war between his forces, the remaining [[dreadlord]]s, and the free undead led by [[Sylvanas Windrunner]]. Windrunner's forces, the [[Forsaken]], achieved a victory over the dreadlords and Scourge, claiming the ruined former capital of Lordaeron (the \"[[Ruins of Lordaeron]]\"), under which they constructed the [[Undercity]].\r\n==Lordaeron Territories==\r\nThe kingdom of Lordaeron consisted of the [[Eastern Plaguelands]], the [[Western Plaguelands]], the [[Tirisfal Glades]], the [[Hillsbrad Foothills]], most of [[Silverpine Forest]], and part of the [[Alterac Mountains]] ([[Chillwind Point]], and the town of [[Strahnbrad]]).\r\nAlso possibly [[North Lordaeron]], which is currently a [[Closed Zone]].\r\n==Modern Lordaeron==\r\nOf the original cities and towns of Lordaeron, only [[Southshore]], the townships of [[Hillsbrad Fields]] and [[Pyrewood Village]] remain under the control of humans loyal to the [[Alliance]] and also the [[Azurelode Mine]] (even then, the residents of Pyrewood Village are not entirely human either).\r\nTwo small [[high elf|high elven]] outposts can also be found in the [[Eastern Plaguelands]] with [[Quel'Lithien Lodge]] and [[The Hinterlands]] [[Quel'Danil Lodge]]. These elves have stayed committed to the Alliance, and are hostile to the Horde.\r\nThe Forsaken exert control over the ruined capital city, [[Deathknell]], [[Brill]], [[Tarren Mill]], and [[The Sepulcher]]. \r\nThe majority of Lordaeron's former territory is now the [[Plaguelands]]. The cities of [[Stratholme]] and [[Andorhal]] are dominated by the Scourge forces. Larger pockets of resistance are held by the [[Scarlet Crusade]], including [[Tyr's Hand]] and [[Hearthglen]] and minor ones such as the [[Solliden Farmstead]]. The [[Argent Dawn]] also maintains a smaller presence, primarily at [[Chillwind Camp]] and [[Light's Hope Chapel]], but with a few agents at the [[Bulwark]] and at a small camp near the [[Plaguewood]].\r\n==Notable Leaders==\r\n* [[Terenas Menethil II]]\r\n* [[Arthas Menethil]]\r\n* [[Balnazzar]]\r\n* [[Sylvanas Windrunner]]\r\nThis is a chart following the events of [[Warcraft III]]\r\n==See also==\r\n*[[The Seven Kingdoms]]\r\n*[[The Alliance of Lordaeron]]\r\n*[[Ruins of Lordaeron]]",},
			["Lordaeron (city)"] = { content = "#REDIRECT [[Capital City]]", redirect = "Capital City",},
			["Lordaeron Citizen"] = { content = "'''Lordaeron Citizen''' are level 15 invisible [[wraith]]s found in the [[Ruins of Lordaeron]] of [[Undercity]]. They can only be seen by various methods of detecting invisibility, such as the [[Warlock]] spell [[Detect Invisibility]], or through the [[Mage]] spell [[Invisibility]].",},
			["Lordaeron Corps"] = { content = "The '''Lordaeron Corps''', was a faction among the [[Survivors of Lordaeron]] who followed [[Jaina Proudmoore]] to [[Kalimdor]]. From the name, they're probably made up of the people of Lordaeron.",},
			["Lordamere"] = { content = "#redirect [[Lordamere Lake]]", redirect = "Lordamere Lake",},
			["Lordamere Internment Camp"] = { content = "'''Lordamere Internment Camp''' is the only [[Internment Camp]] based in [[Alterac Mountains]]. It is located on a hill overlooking the rebuilding city of [[Dalaran]], and is defended by Dalaran forces. Four treacherous [[forsaken]] hide here, and agents of the [[Horde]] are asked to seek them out and kill them for their misdeeds.",},
			["Lordamere Lake"] = { content = "'''Lordamere Lake''' acts as a natural barrier between the [[Forsaken]] lands of [[Tirisfal Glades]] and [[Silverpine Forest]], and the contested lands of the [[Alterac Mountains]]. At its center is [[Fenris Isle]], which has since been taken over by agents of the [[Scourge]]. This situation threatens the nearby Forsaken outposts in Silverpine Forest. East of Fenris Isle is a small group of islands called [[the Dawning Isles]]. It is reportedly the second largest lake in the known world — after [[Darrowmere Lake]]. \r\nAlthough the lake was once a beautiful and safe place to swim, [[Vile Fin]] [[murlocs]] have now built encampments along the shores and among the islands of the lake, and on the Dawning Isles live monstrous creatures of animated flora.\r\nIn earlier maps, [[Cross Island]] was in the centre of Lordamere Lake. However, it does not exist in [[World of Warcraft]]. Its possible that Fenris Isle is whats left from Cross Island. Some parts of the island have seemingly sunken into the water.",},
			["Lords of the Emerald Flame"] = { content = "According to [[Velinde's Journal]], the Lords of the Emerald Flame are an incredibly powerful enemy of the [[worgen]]. They do battle with the worgen on their native homeworld, and [[Velinde Starsong]] got to know of this ferocious war through her use of the [[Scythe of Elune]]. Apparently, the struggle against the Lords of the Emerald Flame does not go too well, as the worgen found their enemy to be an unflinching one indeed.\r\n''\"Holding the Scythe in my hands, I received a vision of chaos. Wolf-men... the worgen... battled an incredible enemy. The worgen fought savagely, as fit their primitive race, but their enemy was unflinching: the Lords of the Emerald Flame.\"''",},
			["Lord Admiral"] = { content = "The official title of the king of [[Kul Tiras]], as the commander of the Kul Tiras fleet. It is not to be confused with the title; [[Grand Admiral]] of the Alliance fleet.",},
			["Lord Afrasastrasz"] = { content = "He is involved in the following quests:\r\n* Report to Lord Afrasastrasz\r\n* Defending Wyrmrest Temple",},
			["Lord Agrovane"] = { content = "'''Lord Agrovane''' is the human who \"bought\" [[Rehgar Earthfury]]. Eventually, Rehgar was able to escape his captors.",},
			["Lord Ahune"] = { content = "#REDIRECT [[Ahune]]", redirect = "Ahune",},
			["Lord Alexei Barov"] = { content = "'''Lord Alexei Barov''' is an [[elite]] [[death knight]] [[boss]] found in [[Scholomance|Scholomance]].\r\n==Background==\r\nLord Alexei Barov was the lord of [[Caer Darrow]], [[Brill]], [[Tarren Mill]] and [[Southshore]]. He was the father of [[Alexi Barov|Alexi]], [[Weldon Barov|Weldon]], and [[Jandice Barov]] and husband of [[Lady Illucia Barov]]. Like Jandice and Illucia, he is now an agent of the Scourge found in [[Scholomance]].\r\nAlexei Barov is one of the six bosses that must be defeated to summon [[Darkmaster Gandling]]. He also guards [[The Deed to Caer Darrow]].\r\n==Abilities==\r\n*'''Immolate''' - Burns an enemy, then inflicts additional Fire damage every 3 sec. for 15 sec.\r\n*'''Unholy Aura''' - Causes the caster to automatically inflict 100 Shadow damage every 2 sec. to nearby enemies. The aura lasts until cancelled.\r\n*'''Veil of Shadow''' - Reduces healing effects for nearby enemies by 60% for 15 sec.\r\nHe has a damaging [[shadow]] [[AoE]] (Unholy Aura, deals 150 Shadow Damage per second to any nearby enemy) similar to the one [[Baron Rivendare]] has. [[Resistance Aura]] or [[Shadow Protection]] are extremely helpful, if not imperative, to fight him. He also casts Immolate and Veil of Shadow, a curse that reduces healing effects on the target. It should be removed immediately if its on the tank.\r\nDuring the fight itself he has 2 guardian [[mob]]s with him. Don't even try pulling them separately, as the three are linked.\r\nIt is common when a party reaches these rooms for Alexei to be the first of the six bosses killed to summon Darkmaster Gandling. This fight is more difficult than that of any of the other bosses, or that of Gandling himself. Any party that can defeat Alexei is virtually guaranteed to be able to finish the instance.\r\n==Strategy==\r\nBecause of Barov's Unholy Aura, it's important no matter what strategy used that he is tanked in a place where the Unholy Aura won't be damaging non-melee classes. One of the best places is at the bottom of the stairs in Gandling's Study; casters and hunters can do damage to Barov and heal [[melee]] classes from near the door between the crypt and the study or the corners of the study. But tanking Barov in a corner of the crypt or even down where he originally stands will do.\r\n===Priest and hunter===\r\nHave the priest stand on the right set of stairs while the hunter places a [[Freeze Trap]] right where the priest stands. The priest can then [[Shackle Undead|shackle]] the '''LEFT''' mob. The undead guards are around the same speed as the boss so it is likely that the mob will get to the trap before Barov. The priest must then run a few steps back while the [[tank]] [[Sunder Armor|sunders]] Barov and everyone else does as much [[DPS]] on him as possible. If the mob will cool before Alex dies, have an offtank take a few hits while the rest of the group keeps attacking Barov. The priest will need to keep an eye on the shackled guard in case a reshackle is needed (which, for most groups, will be likely).\r\n===Alternate for priest and hunter===\r\nHave the hunter and the tank stand on one of the stairs down to Barov, and the rest of the party at the other. Have the hunter start the encounter by firing on Barov; immediately after, have the priest shackle one guard and the tank rush the other. The hunter must now [[kite]] Barov upstairs and around the upper ring of Gandling's Study while the party defeats the unshackled guard, then the shackled one. After both are defeated, the hunter will bring Barov back downstairs (or simply [[Feign Death]]) where the tank engages Barov in the lower level of the study. After 5 sunders, melee DPS will need to move in while the hunter and casters stay out of Barov's AoE; if possible have the tank engage Barov hold at the bottom of the stairs while casters stay in Barov's original room or right at the doorway to the Study.\r\n===Mage and priest===\r\nStart the encounter with the priest shackling a guard. The mage will then need to [[Frostbolt]] Barov. (Use level 1 frostbolts to cause minimal [[aggro]] but retain the [[snare]] effect — it's far more important at this point that the tank will be able to take Barov's aggro quickly than Barov being damaged.) The mage will then need to use frostbolt, [[Blink]] and [[Frost Nova]] to kite Barov around the upper ring while the rest of the party defeats the unshackled guard. Unless the mage is doing really well with his health during the kiting, you will probably want to reshackle the guard and bring Barov downstairs immediately after the unshackled guard falls.\r\n*Note: The mage kiting strategy still works -although, due to being a boss, the chill effect no longer works on Barov, and neither doe Frost Nova. A mage can still kite him though — an initial pull with a frostbolt or similar, and subsequent blinking is fine. Eventually healing on the rest of the group will pull him off you, unless you use the odd spell to maintain his interest. I tested this strategy on the 17/11/06 — I can pick him up with a frostbolt, and avoid too much damage from his aura by continual blinking. Using [[Ice Barrier]] whenever the cooldown is available, and [[Mana Shield (original)]] if nothing else was available, I took almost no damage from the Aura. By the time healing on the rest of the group attracts his attention, the other guards should be dead — at which point, you can jump down, and let the Tank pull him off you.\r\n===Priest only===\r\nShackle one guard and make sure the [[offtank]] can take care of the other one while the rest of the party dpses Barov.\r\n===Hunter without a priest===\r\nHave the hunter send their pet to tank one of the adds and the main tank take the other add. At the same time the hunter hits Barov with a arcane shot and then runs with Aspect of Cheetah switched on. The hunter runs up the stairs and then kites Barov round the balcony. It is important to maintain maximum range otherwise the hunter takes damage from Barov's shadow aura. Once the adds are downed the hunter jumps back down and enters the room again the tank picking up Barov on his return. It is important that Barov is held well into the room otherwise you may risk immediately aggroing Gandling when Barov dies, if he's the last of the 6 bosses before Gandling.\r\n===Mage kiting===\r\nIf you have a frost mage with you, you can use this tactic. Have the main tank start the fight at the top of the stairs on the right side of Barov's room. You must start with a ranged attack. You will then start a blizzard on top of the stairs where the guards and Barov will be coming from. You should be standing in the entrance-way to the room. As soon as you have gained aggro on the guards, break your blizzard and move out into the main chamber. Proceed to kite the guards with your various frost spells. I find it easiest to go to the upper floor and to move around the edge of the room. If the guards are getting too close, simply jump down the lower floor, and hit them as they come around and down the stairs. This should allow enough time for the other players to take out Alexei and then you can either drag the guards back inside, or the party can move out to you. This one takes a bit of practice, but once mastered, can be highly effective. Alternatively, the mage can pull Alexei to begin with, and pull him around the upper floor. Provided judicial use of Blink and a barrier spell, and Major Health Potions, a reasonably geared mage can survive until the rest of the party have dispensed with the other two guards, and can come to the mage's aid. It is likely that you will need to be healed at some point - depending on how fast the two guards can be killed - so build aggro against Alexei with the odd instant cast. A priest's Shadow resistance buff is extremely useful to this strategy, due to the fact that Alexei's damage buff can be partially resisted.\r\n===Paladin Fear===\r\nIf you have a paladin in the group you can have him cast Turn Undead on one of the adds and they very rarely leave the room. When the Turn Undead wears off the paladin will then be able to recast fairly soon and keep the add out of the battle until Alexei has been brought down. **NOTE: If there is a priest in the group the other add can be shackled to be out of the fight as well.\r\n===Retribution Paladins===\r\nIf you have a Retribution Paladin in the group, have instead of the tank calling out the adds, follow this strategy, first to cast repentance on the add causing it to be incapacitated for a minute so long as no one hits it, and cast Turn undead on the other add thus freeing you and the group to take out Alexei quickly. Repentance lasts only a minute the same amount of time it takes to recharge the spell, this strategy will allow the group to only fight Alexei and later get rid of the adds once they've taken care of Alexei, this strategy also works very well as a solo strategy.\r\n===Druid kiting===\r\nIf you have a druid available to kite, you can start off with the druid using a combination of starfire-moonfire on Alexei to obtain aggro. The two guards are picked off by the party, while the druid shifts to Cat form and uses Dash to kite Alexei away from the group, occasionally using Faerie Fire(Feral) if the druid has it available. Once Dash wears out, the druid can shift to bear form and continue to keep Alexei occupied, either by running or offtanking. Once the party gives the \"All clear\" shout, use Bash on Alexei to gain some distance and run him back to the party.(Strategy by Xenigma, Stonemaul server)\r\n===Hunter kiting===\r\nThe hunter drops an ice trap at the top of one set of stairs, where the rest of the party begins. The hunter pulls Alexei, two of the remaining party members tag the guards. The hunter kites Alexei around the top of the study, or better, to Ras Frostwhisper's chamber if it has been cleared ahead of time. One of the guards will freeze, kill the other. Typically, even in low dps groups the second guard has fallen by the time Alexei reaches Ras's room, giving plenty of time to mana up, bandage, and heal before he returns. If not, the hunter can allow Alexei to approach, feign, then pop up, run back with him, and tag him again in Gandling's Study, rekiting him over and over again until the party is ready. I prefer to kite to Ras's room because of the corners in Gandling's Study. With a weak or lower leveled group, every health point will count when killing this guy because of the aura. You can avoid that almost entirely on the Ras kite. Once the guards are down and the party is ready, let him return after a feign and kill him. It's helpful to mark the farther guard with a skull and tag the closer guard first to ensure that it is the one that freezes and that the ice trap isn't broken.\r\n==Loot==\r\nAlexei Barov has a chance to drop one of the following items.\r\n==In Hearthstone==\r\nAlexei's living form appears as a in the ''[[Hearthstone: Scholomance Academy|Scholomance Academy]]'' expansion for ''[[Hearthstone (game)|Hearthstone]]''. His flavor text reads: \"''Alexei Barov stayed at Scholomance despite leasing it to Kel’Thuzad. He says it’s for \"supervision.\"''\"\r\n<gallery>\r\nStouthoof Barov HS.jpg| hero skin in ''Battlegrounds''.\r\n</gallery>\r\n==Notes==\r\n*Along with Baron Rivendare, Alexei was one of the first [[Death Knight]]s to be implemented into ''World of Warcraft''.",},
			["Lord Aliden Perenolde"] = { content = "#REDIRECT [[Aliden Perenolde]]", redirect = "Aliden Perenolde",},
			["Lord Aliden Perenolde (quest)"] = { content = "'''Lord Aliden Perenolde''' is a Horde quest in [[Hillsbrad Foothills]] and [[Alterac Mountains]] that involves killing the leader of the [[Syndicate]], [[Lord Aliden Perenolde]]. You must have completed Blackmoore's Legacy before you can get this quest.\r\n==Objectives==\r\nKill Lord Aliden Perenolde and ask his mistress, [[Elysa]], about Taretha's pendant.\r\nKill:\r\n* [[Lord Aliden Perenolde]]\r\n==Details==\r\n* Lord Perenolde is in the house at [[Dandred's Fold]] in the upstairs room. It's an easy fight. The mobs that lead up to him are harder then he is. \r\n==Description==\r\nIt is clear that Perenolde must be killed, his foulness removed from the world. His manor lies a ways to the north of here, on the shores of Lordamere Lake. Do your duty, <name>, then retrieve the pendant that the Warchief desires, and return here.\r\n==Completion==\r\nNo, no please don't hurt me! I never meant your people any harm, he's had me against my will! Please... spare me!\r\n==Quest Progression==\r\n* Infiltration\r\n** Gol'dir\r\n** Blackmoore's Legacy\r\n** Lord Aliden Perenolde\r\n*** Taretha's Gift",},
			["Lord Arkkoroc"] = { content = "'''Lord Arkkoroc''' (aka Arkkoran) is a level 60 [[sea giant]] [[quest giver]] located in the [[Temple of Arkkoran]] in the [[contested]] territory of [[Azshara]]. He is the supposed god of the sea giants. The [[makrura]] and the [[murloc]]s in the area consider him some kind of divinity as well. [[Loramus Thalipedes]] describes him as a lesser deity, and his sons, the [[sea giant]]s, patrol around the temple. Many of Lord Arkkoroc's sons were slain by the [[hydra]] [[Hetaera]], and he now seeks revenge. Arkkoran only leaves the temple when he’s in a foul mood.\r\nHis name might be inspired by \"Arcoroc\", french brand of unbreakable glassware. \r\nSee [[List of Azshara NPCs]].\r\n==Quests==\r\n* The Name of the Beast \r\n** The Name of the Beast (2) \r\n*** The Name of the Beast (3)",},
			["Lord Azrethoc"] = { content = "'''Lord Azrethoc''' is a level 40 [[elite]] [[doomguard]] found in [[Mannoroc Coven]] in [[Desolace]]. [[Takata Steelblade]] of [[Ghost Walker Post]] wants Azrethoc killed.\r\n==Background==\r\nLord Azrethoc leads several agents of the [[Burning Legion]], including fel hunters,\r\n[[infernals]], doom guards and [[succubi]], that reside in the [[Mannoroc Coven]].\r\nHe is a powerful demon who seeks to gain influence with the [[Burning Blade]] cult by signing a number of demonic contracts with its members.\r\n==Quests==\r\n*The Corrupter (5)",},
			["Lord Banehollow"] = { content = "'''Lord Banehollow''' is a level 59 [[quest giver]] located in [[Shadow Hold]] in the [[contested]] territory of [[Felwood]]. He is an [[elite]] [[dreadlord]], and the leader of [[Jaedenar]], the seat of the [[Shadow Council]] on [[Azeroth (world)|Azeroth]]. He is guarded by a wide variety of warlocks, demons, and his personal attendant [[Ur'dan]]. Any [[warlock]] seeking to steal a [[dreadsteed]] must deal with Banehollow by first drinking a [[Shadowy Potion]]. He assists and directs you in stealing the steed from a rival of his, [[Lord Hel'nurath]] of [[Xoroth]]. \r\n\"Banehollow\" is also one of the random names given to the dreadlord hero in Warcraft III.\r\nHe starts the following quests:\r\n* Ulathek the Traitor\r\n* Xorothian Stardust\r\nSee [[List of Felwood NPCs]].",},
			["Lord Baurles K. Wishock"] = { content = "Lord Baurles K. Wishock is a minor functionary in the royal court of Stormwind. He is a frequent patron of the [[Slaughtered Lamb]] tavern in the [[Mage Quarter]] of Stormwind City--and it is alleged that he does not keep his tab current.\r\nLord Baurles has discovered that [[warlock]] trainers and others have set up shop in the basement below the Slaughtered Lamb, and intends to petition the king to shut down the establishment--something [[Zardeth of the Black Claw]] would prefer he didn't. A quest line given by Zardeth requires that the player outright murders Lord Baurles with a deadly poison administered to a drink.\r\n'''Lord Baurles K. Wishock''' can be found in [[Stormwind Keep]] in [[Stormwind City]] .",},
			["Lord Blackforest"] = { content = "'''Lord Blackforest''' was a [[night elf]] noble. He was one of the many nobles who looked to [[Jarod Shadowsong]] for leadership during the later battles against the [[Burning Legion]].\r\nHe perished when he — along with a few [[highborne]] and night elves — found [[Illidan Stormrage|Illidan]] trying to recreate the Well of Eternity by pouring previously filled vials of magical water into a lake on [[Mount Hyjal]]. Illidan burned the sorcerors and caused the ground beneath Blackforest to explode, throwing him into the air and impacting against a tree with a resounding crack.",},
			["Lord Blackwood"] = { content = "'''Lord Blackwood''' is a level 60 [[elite]] [[skeleton]] [[mini-boss]] found in [[Scholomance]] during the [[Scourge Invasion]].\r\nHe appears as a giant, violet, glowing skeleton with a distinctive sword. He can be found wandering in the room just beyond the Chamber of Summoning. It is highly recommended to kill the first three groups before engaging combat with him.\r\n==Strategy==\r\nThere is not much to say about how to fight him since he's very easy but it's worth mentioning that if there is no one to [[tank]] him, he will start shooting arrows at the group. Healers should know that he has the health worthy for a boss beyond his level so be warned to preserve your mana.",},
			["Lord Cobrahn"] = { content = "'''Lord Cobrahn''' is a level 20 [[elite]] [[night elf]] in the [[Wailing Caverns]].\r\n==Lore==\r\nOne of the leaders in the Wailing Caverns. His unique traits that differ him from the other druids is a claw on his right hand, is surrounded by deviate pythons and is much larger in size than the other druids. \r\n==Abilities==\r\n'''Poison''' - Inflicts Nature damage over a small period.\r\n* School: [[Nature]]\r\n* Dispel: [[Poison]]\r\n'''Lightning Bolt''' - Blasts an enemy with lightning, inflicting Nature damage.\r\n* School: [[Nature]]\r\n==Combat Info==\r\nLord Cobrahn is the easiest of the Fanglords. If you have a mage with you, just [[AoE]] the non-elite snakes, and start beating Cobrahn down. When he gets low on health, he'll turn into a rather large snake, and his [[DPS]] will increase slightly. Just keep attacking him, and he should drop fast. Yet again, like [[Lady Anacondra]], with a decent group this fight is easily won.\r\n==Quests==\r\n*Leaders of the Fang\r\n==Quotes==\r\n'''Aggro''' ''You will never wake the dreamer!''",},
			["Lord Cyrik Blackforge"] = { content = "'''Lord Cyrik Blackforge''' is a level 23 [[dwarf]] found in [[Bael Modan]] in the [[Barrens]]. He is the pilot of one of the Bael Modan flying-machines.",},
			["Lord Daval Prestor"] = { content = "#redirect [[Daval Prestor]]", redirect = "Daval Prestor",},
			["Lord Daval Prestor II"] = { content = "'''Daval Prestor II''' was the second Lord Prestor after [[Daval Prestor|Daval Prestor the First]] who was believed to be making a return in World of Warcraft, as he was seen in [[Stormwind]] during the beta test. However, at some point he was removed and replaced by [[Lady Katrana Prestor]] - the human form of Deathwing's daughter, [[Onyxia]], who took the name Prestor in homage to her father.\r\nIf Daval Prestor II was intended to be Deathwing or another black dragon altogether is unknown.",},
			["Lord Del'theon"] = { content = "'''Lord Del'theon''' was a [[night elf]] noble. He was one of many leaders killed during the fight against the [[Burning Legion]]. After his death, many of the nobles looked to [[Jarod Shadowsong]] as their leader on the battlefield.",},
			["Lord Ello Ebonlocke"] = { content = "'''Lord Ello Ebonlocke''' is a level 30 [[quest giver]] located in the [[Darkshire Town Hall]] in the [[human]]-aligned territory of [[Duskwood]]. He is the mayor of [[Darkshire]] and ruler of Duskwood. He is the father of [[Commander Althea Ebonlocke]], the leader of [[the Night Watch]].\r\nHe starts the following quests:\r\n* Messenger to Darkshire\r\n* Translate Abercrombie's Note\r\n* Bride of the Embalmer (Elite)\r\nSee [[List of Duskwood NPCs]].\r\n==Excerpt from a Letter to King Wrynn==\r\n''\"There is little hope for us if you do not send forces to our aid. \r\n''The [[undead]] overwhelm our scouts, our livestock does not grow, \r\n''a pregnancy - [[human]], [[elven]] or [[dwarven]] - has not been carried to \r\n''term in two years. The [[Alliance]] has abandoned our residents to \r\n''fuel the undead forces.\r\n''If our pleas remain unheeded, I can only pray that after I fall to\r\n''the undead I will lead the [[Scourge]] against [[Stormwind]] so that \r\n''you will know the horror we live with every day.\r\n:::::::''Your loyal servant,\r\n:::::::''Lord Ello Ebonlocke\"",},
			["Lord Falconcrest"] = { content = "'''Lord Falconcrest''' is a level 40 [[human]] found in [[Stromgarde Keep]] in the [[Arathi Highlands]].\r\n==Background==\r\nLord Falconcrest is a former noble of the Kingdom of [[Alterac]]. After Lord [[Perenolde]]'s betrayal of the [[Alliance]] during the [[Second War]], Falconcrest and the rest of the Alterac nobility were stripped of their lands and titles. He is now one of the leaders of the Syndicate, a vicious group of brigands led by former lords of Alterac bent on regaining their old territory and taking revenge on their enemies. Falconcrest is rarely seen without his servant and bodyguard [[Otto]] by his side. He is currently marked for death by the Alliance for his crimes.\r\nLord Falconcrest was one of the many lesser nobles under Lord Perenolde. He never liked the older man, but he admitted that Perenolde had a good idea from time to time, and thought it was a fine idea to work with the Horde. After they were exiled, he believed the Syndicate should be under his control as he blamed Perenolde for the loss of their holdings. He thinks he would have been able to get lesser sentences from the Alliance instead of exile to the wild to fend for themselves like peasants. He does admit that their plans to take Lordaeron lands have worked better than expected, and grabbed the opportunity to lead the Syndicate faction in Stromgarde in the Arathi Highlands.\r\nFar enough away from Perenolde’s control, he slowly groomed the rogues under him to work against Perenolde and the northern Syndicate, although he knew he must move slowly and methodically to make sure his forces were strong enough before he made the schism. He was younger than Perenolde, only in his forties, and is prepared to bide his time until he was ready. He has red hair, white skin and light blue eyes and dresses in flowing, light garments to keep the sun from burning his sensitive skin. After Aiden Perenolde was recaptured by the Alliance, and his son, Aliden took over the Syndicate, Lord Falconcrest probably turned his eye toward overthrowing him.\r\n==Quests==\r\n*Wanted! Otto and Falconcrest\r\n==Loot==\r\n*Falconcrest's Head ''(Quest Item)''",},
			["Lord Garithos"] = { content = "#REDIRECT [[Othmar Garithos]]", redirect = "Othmar Garithos",},
			["Lord Grayson Shadowbreaker"] = { content = "'''Lord Grayson Shadowbreaker''' is a level 60 [[paladin trainer]] located in the [[Cathedral of Light]] in [[Cathedral Square]], in the [[human]] city of [[Stormwind]]. He is currently the commanding officer of the paladins in Stormwind. He is a war veteran from both the [[Second War|Second]] and the [[Third War]] and a Knight of the [[Silver Hand]]. \r\n''On his tombstone will be engraved three words: respect, tenacity, and compassion.''\r\nHe starts the following quests:\r\n* The Tome of Divinity\r\n* Chillwind Camp\r\n The quest chain, leading to: [[Charger]].\r\n* Emphasis on Sacrifice\r\n* Exorcising Terrordale\r\n* The Work of Grimand Elmore\r\n* Ancient Equine Spirit (Dungeon)\r\n* The Divination Scryer\r\n* Judgment and Redemption (Dungeon)\r\nSee [[List of Stormwind NPCs]].",},
			["Lord Gregor Lescovar"] = { content = "==Quests==\r\nObjective of The Attack!",},
			["Lord Hel'nurath"] = { content = "'''Lord Hel'nurath''' is a level 62 [[rare mob|rare]] [[elite]] [[demon]] summoned in [[Dire Maul]] West.\r\nA member of the [[nathrezim]] ruling over the world of [[Xoroth]]. You have to defeat him and one of his [[dreadsteed]]s to be able to summon a [[dreadsteed]] on the quest line for the [[warlock]] epic [[mount]].\r\n==Quests==\r\n*Dreadsteed of Xoroth",},
			["Lord Illidan Stormrage"] = { content = "#REDIRECT [[Illidan Stormrage]]", redirect = "Illidan Stormrage",},
			["Lord Incendius"] = { content = "==Background==\r\n'''Lord Incendius''' is a [[fire elemental]] that guards the [[Black Anvil]] located in [[Blackrock Depths]].\r\n==Abilities==\r\n* Knockback: Be sure to have your back toward the anvil at all times, he can knock you into the lava. Or if you don't want to take any risks, pull '''Lord Incendius''' back to the hallway.\r\n* Fire Storm: [[AoE]] fire attack\r\n* Curse of the Firelord: -100 Fire Resistance debuff which can stack at least 5 times (FR gear is useless, but it counts as a curse and can be dispelled)\r\n*Incendius is immune to [[stun]]s, [[gouge]], [[blind]], [[garrote]], and some [[poison]]s\r\n===Stealth Run===\r\n'''Lord Incendius''' is reachable in a typical [[Stealth Run]] in about 2 minutes flat, and takes about a minute to kill. To reach him, go straight left as soon as you enter the instance and unlock the door, avoid the roaming fire elemental and distract either the left or right dog. Pass this small group by staying close to the dwarves. Note that the dogs will detect stealth at an alarming distance, but as a level 60 you will have no problems passing as close as 1-2 feet away from the dwarves even if they are facing directly at you (no improved stealth required). Then simply head right and pass trough the large door, and across the bridge. After this you'll pass by 3 groups of 2 fire elementals, still nothing so far should have attacked you.\r\n===Soloable Kill===\r\nIncendius was fairly easy to solo either as a [[Rogue]] or [[Druid]], presuming you had at least 150-200 [[Fire Resistance]]. In [[Patch 1.10]] Incendius received a considerable buff. He now gives a stackable Fire Resistance Debuff (-100 FR), making him near impossible to solo without consumables. It is necessary to use a [[Greater Fire Protection Potion]] as soon as you enter the instance so you can drink one more during the fight. Unless you can easily make these, it is recommended that you duo him to eliminate error and wasting useful consumables.\r\nAs a [[druid]] he is soloable in fact, since his [[fire resistance]] debuff counts as a curse. They can remove it and not get the -100 [[Fire resistance]] debuff. However, the easiest way is to use [[Omen of Clarity]] and melee him in the normal [[Druid]] form. It can take time, but he will go down. Since patch 1.11, all druids, no what matter spec, can cast [[Innervate]], so it's basically just a matter of time, and you'll be surprised how much you resist of his attacks with 150 fire resistance.\r\n===Warlock Kill===\r\nHere's how to solo him as a [[warlock]]. Being affliction specced or having [[Demonic Sacrifice|demonic sacrifice]] is highly recommended to do this, as the fight can be fairly long and you'll need health regen to heal through the fireballs and regenerate some mana. You will need the [[Shadowforge Key]] to open the 3 doors that are directly left after entering the instance. \r\nAfter opening the last door take the way up, killing the patrolling elemental on the way. You have to take the left corridor, and jump through the window at the end of it. There's a patrolling elemental that can be single pulled, to reduce the number of mobs.\r\nUse a [[voidwalker]] to aggro all the dwarves that guard the way, directly sending him on the next pack when he has aggroed one. When you're at the middle he should be near death, sacrifice him and run through the window. Directly below the window is a small platform, from which you can jump down to a large platform leading to '''Lord Incendius'''. The mobs will reset after a while once you've jumped. You will lose some health doing this, so have a healthstone ready.\r\nOnce you've jumped down on the platform, be careful of the dwarf patrol standing there. You can proceed to killing the 4 groups of two elementals that guard the way. Just banish one while killing the other.\r\nOnce you finally get to the boss, you will have to kite him by running on the circular edge around the room. Just throw and refresh your instant dots on him. He will periodically stop to cast his various spells, giving you time to put distance between you and him. The main difficulty here is directing your character so you don't fall into the lava below. If the boss catches up, the knockback can throw you in the little niches around the room, so be very careful getting out of them before you go back to running around. You can also turn around to cast a bolt while he's channeling a spell, in order to speed up the process.\r\n===Two-Person Kill===\r\nOne [[Rogue]] and one [[Druid]] can kill this boss and be out of the instance in 5 minutes or less, no [[fire resistance]] required (though it always helps). Simply stealth to him and kill him, although bringing along a full party of blacksmiths is wise so they can all use the Black Anvil. Let the rogue tank, while the druid heals and mixes in some moonfire to speed up the damage.\r\n==Quests==\r\n*Incendius!\r\n*Disharmony of Fire\r\n==Loot==\r\n* Ace of Elementals leads to Darkmoon Card: Maelstrom\r\n* Cinderhide Armsplints (Leather)\r\n* Emberplate Armguards (Plate)\r\n* Flameweave Cuffs (Cloth)\r\n* Pyremail Wristguards (Mail)\r\n* Incendic Bracers (Cloth)\r\n*Tablet of Kurniya ''(Quest Item)''\r\n==Notes==\r\n*Since patch [[1.8]], you are limited to five instances \"per hour\"; Incendius is farmable in 4-5 minutes per run, thus you will reach the instance limit within half an hour. You can do him five times in that amount of time, so have something to do after every other kill so that you make the most of your time.\r\n*While you are in the area it is a good idea to mine all the [[Dark Iron]] veins as well, as commonly at least one is accessible without a single fight, or having to fight more than three dog packs.\r\n*Was level 55-56 prior to patch [[2.3]]\r\nSee also: [[Dark Iron stealth guide]]",},
			["Lord Irulon Trueblade"] = { content = "'''Lord Irulon Trueblade''' is a [[human]] at [[Valgarde]] in the [[Howling Fjord]]. He ends the quest Guided by Honor.\r\nSee [[Howling Fjord NPCs]].",},
			["Lord Itharius"] = { content = "'''Itharius''' is a [[green dragon|dragon]] who serves as the [[green dragonflight]] ambassador with the [[Wyrmrest Accord]]. His old friend [[Eranikus]], the consort of [[Ysera]], which he considered as a brother, succumbed to the [[Emerald Nightmare]]'s corruption. \r\n===Swamp of Sorrows===\r\nHe used to be a [[quest giver]] located in [[Itharius's Cave]] in the [[Swamp of Sorrows]]. He appears as a [[high elf]] who dwells in a reasonably civilized cave near the perimeter of the swamp. Itharius seems almost to be 'baby sitting' a flock of rather cantankerous green whelps.\r\nWhen the green dragons in the [[Temple of Atal'Hakkar]] were driven mad by both the [[Emerald Nightmare]] and the [[Atal'ai]], Itharius called for help from the [[Cenarion Circle]] who in turn sent a force from the [[Alliance]] to clear the temple.\r\n===Wyrmrest Temple===\r\nHe later appears as '''Lord Itharius''' , a [[quest giver]] found at [[Wyrmrest Temple]] in the [[Dragonblight]], working to defend the [[Emerald Dragonshrine]].\r\n===The Return to Atal'Hakkar===\r\nLord Itharius was relocated from his cave in Swamp of Sorrows and relocated to the sunken Temple of Atal'Hakkar and is the primary quest giver for the revamped dungeon.\r\n===Deaths of Chromie===\r\nSeeking leads on who wants her dead Chromie asks Itharius if he's noticed anything suspicious and he speaks of the ancients being unable to rest at the [[Emerald Dragonshrine]].\r\n==Quests==\r\n*[[Seeds of the Lashers]] \r\n*[[That Which Creates Can Also Destroy]] \r\n*[[Blessing of the Green Dragonflight]] \r\n*[[The Dragon and the Temple]] \r\n*[[Legends of the Sunken Temple]] \r\n*[[Pool of Tears (quest)]] \r\n*[[Step One: The Priestess]] \r\n*[[Step Two: The Bloodletter]] \r\n*[[The Heart of the Temple]] \r\n*[[To Marshtide Watch]] \r\n*[[To Stonard]] \r\n*[[The Heart of the Temple]] \r\n*[[Darkened Dreams]] \r\n*[[The Essence of Eranikus (2)]] \r\n*[[In Eranikus' Own Words]] \r\n*[[Adventurers Wanted: The Sunken Temple]] \r\n===Gossip===\r\nSwamp of Sorrows\r\nGreatings, <race>. I am Lord Itharius of the green Dragonflight.\r\nI am here to free my kin from the evil within this temple, hopefully for good. with you assist me?\r\nTemple of Atal'Hakkar\r\nHakkar is known by many names. Some call him the Blood God, other simply refer to him as The Soulflayer. Titles aside, he is an entity of enormous power with malicious intentions for our world.\r\nMy flight discovered this temple early on and sank it beneath the Swamp of Sorrows. Unfortunately, we only seemed to aid the Atal'ai by ensuring their efforts to summon Hakkar went undisturbed. Many of the dragons tasked with guarding the temple have been corrupted, and the Soulflayer's presence grows with each passing day.\r\nI cannot stop them alone. Together, though, we might have enough time to stop this madness.\r\n===Conversation with Itharius===\r\nI know who you are, <name>. Fate and forces beyond that have brought you to me for a reason, and it is one I take no pleasure in being a part of. There are many decisions you will make in the coming times, and I hope you are wise enough to make the correct ones.\r\nBelieve me, <race>, when I tell you this - there are correct choices.\r\n''Itharius clasps.''\r\nYou are quite inquisitive, though such inquisitiveness belies a general lack of understanding. I say this because were you to have a definite purpose in being here, the question you ask would seem pointless\r\nWith that, I bid you good day. \r\nYou know I do, mortal; I am abandoning a fair number of pretenses here, and I recommend you do the same.\r\nYou have come here clearly because you know that what you possess, garned from your actions within the Sunken Temple of the Atal'ai, has brought you to me for a purpose. The purpose is to put my associate... my brother, to rest. He is trapped within a nightmare within the Dream itself. He cannot break free alone.\r\nThe god that the Atal'ai trolls had brought forth is to blame for this. We destroyed the god's physical manifestation and sunk the temple but the god was so much stronger than even we had anticipated. Its seed of corruption ran deep twisting everything in its path.\r\nEranikus was charged to watch over the sunken temple to ensure that neither the simple Atal'ai nor their god would rise again. He was an unwitting victim of this corruption, and we in underestimating its potency.\r\nThe fact that you are here is a first step... a correct choice if you will, in aiding Ysera's Dragonflight.\r\nYou may be here for purely the lure of personal gain, or you may be here because you are morally compelled. Neither reason is important on its own, but both are in fact critical to this end: The agony that Eranikus endures is what rousted me from my Dream, and it is now my charge to see his torment ended. I now ask you to aid me in this quest.\r\nWyrmrest Temple, Dragonblight\r\nYes?\r\nOrgrimmar\r\nI can show you the aftermath of Deathwing's destruction at the Maelstrom, if you wish.\r\nDeaths of Chromie\r\n==Notes==\r\n*He once bred and raised a unique breed of green dragons, that have since settled in the wilds of [[Feralas]].\r\n==See also==\r\n*[[Mantle of Itharius]]",},
			["Lord Jorach Ravenholdt"] = { content = "'''Lord Jorach Ravenholdt''' is a level 60 [[quest giver]] located in [[Ravenholdt Manor]] in the [[contested]] territory of [[Alterac Mountains]].\r\nHe starts the quest Sealed Azure Bag.\r\nSee [[List of Alterac Mountains NPCs]].",},
			["Lord Kazzak"] = { content = "'''Supreme Lord Kazzak''' is a battle-hardened [[doomlord]] and commander of [[Burning Legion]] forces. After the [[Third War]], Lord Kazzak remained on [[Azeroth]], in the [[Blasted Lands]], and later reopened the [[Dark Portal]], allowing the Legion to invade once more and marking the beginning of the [[invasion of Outland]]. Though Doom Lord Kazzak himself was defeated, he returned as Supreme Lord in the [[war in Draenor]].\r\n==Biography==\r\nWhen the Burning Legion began its [[Third War|second invasion of Azeroth]], Lord Kazzak participated it, being summoned by [[Kel'Thuzad]] near [[Dalaran]], coming right after [[Mannoroth]]. His most fearsome lieutenant was [[Razelikh the Defiler]]. Following the defeat of the Burning Legion at the end of the Third War, the remaining enemy forces, led by the colossal demon Lord Kazzak, pulled back to the [[Blasted Lands]]. He tasked Razelikh to secure the land.\r\nIn the year 25, Kazzak was located in the [[Tainted Scar]], terrorizing the adventurers of the Horde and Alliance.\r\nOne year later, with the future in peril, a relic of the past had also surfaced, radiating renewed energy. This relic had enabled Lord Kazzak to activate the current [[Dark Portal]], thereby reopening the gateway to the shattered realm of [[Outland]]. With the portal now opened, Lord Kazzak was seen departing through the Dark Portal. In his stead he left his most powerful lieutenant, [[Highlord Kruul]], to sow fear and confusion among the defenders. He also entrusted him with retrieving the shards of the [[Glaive of the Aspects]].\r\nAccompanied by a host of infernals, Kruul was seen near a number of major cities in Azeroth. Once Lord Kazzak passed through back to Outland, he was promoted to [[Doom Lord Kazzak]], commanding the Legion in the broken world, and set up his seat at the [[Throne of Kil'jaeden]], a mountain in the [[Hellfire Peninsula]], which he protected until he was defeated.\r\nKazzak re-emerged from the [[Twisting Nether]] in the alternate version of and is located at the [[Throne of Kil'jaeden (alternate universe)|Throne of Kil'jaeden]] where adventurers of the Horde and Alliance attack him once again.\r\n==See also==\r\n*[[Doom Lord Kazzak (March of the Legion)]], TCG card",},
			["Lord Kazzak (tactics)"] = { content = "'''Lord Kazzak''' was originally found in [[Tainted Scar]] in [[Blasted Lands]].\r\nSince [[WoW's 13th Anniversary]], Lord Kazzak is available during the anniversary event.\r\n==Information==\r\nLord Kazzak was a [[World raid encounters|world raid encounter]], which means that players are allowed to participate in high-end content without the time investment necessary to hack one’s way to the bottom of the dankest dungeons. Instead, he spawned within the back of the [[Tainted Scar]] in the [[Blasted Lands]], a valley that is guarded by elite demonic forces left over from the [[Third War]]. The addition of these encounters opens up new game dynamics, both good and bad. While [[Blizzard Entertainment|Blizzard]] expects a certain amount of competition for such high-end creeps, some players have been abusing Kazzak's special abilities with the specific intent to harass other players.\r\n==Abilities==\r\n*\r\n*\r\n*\r\n*\r\n==Strategy==\r\nFrom: \r\nOnce he is aggroed and the fight begins, you have no more than three (3) minutes to kill him. I'll explain later why. He starts off with everything he's got. He keeps meleeing the main tank while Cleaving once in a while for rogues swarming around him and keeps sending Shadowbolt Volleys to hurt everyone around. The volleys are not on a timer, instead he casts them as he sees fit. In some rare cases there's about 30 seconds between the casts, sometimes he does it every five seconds. In the meantime, he casts Twisted Reflection and the rarer Mark of Kazzak on random people. \r\nWhat to do here: \r\nSend your main tank in and let him build some aggro for a short while, just enough so he won't come at you the first time you cast something on him. Then unload. Have your DPS classes give him everything they have. Priests have to be extra mindful about the magical debuff he casts on your group. It has to be removed as soon as possible or the attempt will soon end in a disaster. Priests are also in charge of healing their groups thanks to that Shadowbolt Volley that keeps hitting everyone all the time. Mages need to be on top of the curse situation. Mark of Kazzak can and will cause a wipe if you let it go off on you. Dispel the curse as soon as you can. All casters should also leave about 1000 mana in their mana pool just in case he casts the curse on you. That'll give the mages four seconds to dispel before it goes off. In other words, 1000 mana is out of mana in this raid encounter. Also, anyone dying during the fight is not an option. Unless it happens during the first five seconds of the fight, you've failed already. Do not use grounding totems, pets or other small things he can kill for the 70,000 health heal. \r\nYour group will have exactly three minutes to finish the demon off. If you fail to kill him in that time due to lack of DPS, people dying or not dispelling Twisted Reflection properly, Lord Kazzak will enter what is called the Supreme Mode. Named after his yell once it triggers, the supreme mode causes him to cast his Shadowbolt every second. That's 800-1000 DPS on everyone, and that means a wipe.\r\n==Loot==\r\nThere are a number of epic items that a player could only acquire by killing Lord Kazzak, this loot table is identical to that of [[Highlord Kruul]] post [[Burning Crusade]]. Each of these ten items are listed below. Since there are ten items, each item had a 10% chance of dropping from Lord Kazzak after a successful kill. Also note that he dropped more than one item.\r\nOne interesting item that players could get from Lord Kazzak is [[The Eye of Shadow]], a component in the [[Priest]] [[epic]] class quest. The reward is a [[staff]] that can transform to suit the talent build of the [[Priest]]: [[Anathema]] / [[Benediction]]. The reason this is important is that there is a 100% chance Lord Kazzak will drop this item, which is significantly better than the 0.5% chance a Priest will have on the Demons in [[Darkwhisper Gorge]], [[Winterspring]]. Some items he drops grant shadow and fire resistance.\r\n==Quotes==\r\nAggro\r\nKill\r\n==Notable attempts==\r\n* Lord Kazzak was kited to Stormwind on numerous servers. Due to the fact that he becomes virtually unkillable after three minutes, he would wreak havoc until a GM intervened. This kiting is no longer possible as Lord Kazzak now will not travel beyond the Blasted Lands.\r\n* Shortly after the introduction of [[Reckoning (paladin talent)]] (a retaliatory attack that can be stored as charges), a paladin on [[Server:Azgalor]] was able to solo Lord Kazzak with a reckoning attack that had 1816 charges. Reckoning was hotfixed shortly after to only allow a maximum of 4 stored charges. of this event.",},
			["Lord Kragaru"] = { content = "'''Lord Kragaru''' is a level 38 male [[naga]] found in [[Desolace]]. Kragaru guards the [[Book of the Ancients]]. He can be summoned by placing the gem provided by [[Azore Aldamort]] in the hand of the [[Serpent Statue]] on the [[Ranazjar Isle]].\r\n==Quests==\r\n*Book of the Ancients\r\n==Loot==\r\n*Book of the Ancients ''(Quest Item)''",},
			["Lord Kri"] = { content = "#redirect[[Three Bugs]]", redirect = "Three Bugs",},
			["Lord Lakmaeran"] = { content = "==Background==\r\nLord Lakmaeran is a [[named]] [[chimaera]] located on the [[Isle of Dread]] in Feralas. He requires 7-10 people to kill. He has no significant loot table, but is required for the [[Scepter of the Shifting Sands]] quest line. He respawns in 15-25 minutes.\r\n==Attacks and Abilities==\r\n*[[Lightning Shield]]\r\n25% chance of inflicting 496 Nature damage on hit.\r\nType: Magic\r\nCharges: 20\r\nNotes: Dispellable\r\n*Static Conduit\r\n200 Nature damage inflicted every 3 seconds. Nature damage taken is increased by 100.\r\nNotes: Stacks up to 50 times\r\n*[[Enrage]]\r\nPhysical damage dealt is increased by 122. Attack speed increased by 60%\r\nNotes: Occurs when his health is at 50%.\r\n==Strategy==\r\nHe starts off with Lightning Shield so [[dispel]] it immediately to reduce the damage your melee will take. Throughout the fight he will attempt to recast this so just dispel it every time. Spread out your raid as much as possible as his chain lightning will arc through players and in turn cause the stackable Static Conduit. He will hit your tank for around 1000 to 1200 damage on average. Beyond this it is a fairly straight-foward fight.\r\n==Quests==\r\n*The Isle of Dread!\r\n==Loot==\r\n*icon= ''(Quest Item)''",},
			["Lord Lothar"] = { content = "#REDIRECT [[Anduin Lothar]]", redirect = "Anduin Lothar",},
			["Lord Marshal Raynor"] = { content = "'''Lord Marshal Raynor''' is a level 70 [[elite]] [[human]] of the [[Alliance]] who appears at the [[Dark Portal]] in the [[Blasted Lands]] during the [[Dark Portal Opens]] event, specifically when the Dark Portal starts to be overrun by demons spawns. Raynor spawns accompanied by several level 65 [[Stormwind Marshal]]s.\r\n==Quotes==\r\n* ''Yells as he spawns:'' \"Marshals... brothers and sisters of the sword. I'd rather fight alongside you than an army of thousands. We are lions! You know what's waiting through these demons and beyond that Dark Portal? Immortality! Take it!\" (from )\r\n* ''Says:'' \"This day we fight!! By all that you hold dear in these good lands, I bid you stand, heroes of [[Azeroth]]!\" (from )\r\n* ''Says:'' \"Yes. Fight and may die. Run and you will live, but for how long? The devils are upon us! And those not here, dying in their villages weeks from now, would they be willing to trade all the days from this day to that, for one chance to come here and stop these horrors from invading our world?\" (from )\r\n* ''Says:'' \"Hold your ground! Hold your ground! Sons of the Alliance! Of the Horde! My brothers and sisters! I see in your eyes the same fear that would wither my own heart. A day may come when our courage fails, when we forsake our friends and break our fellowships... but it is not this day!\" (Also from: )\r\n* ''Says:'' \"We few, we happy few, we band of brothers and sisters. For those today that shed their blood with me. Shall be my kin; be they never so vile, This day shall gentle their conditions.\" (Almost directly from \"'''Henry V\"''' )\r\n* ''Yells as he despawns:'' \"Argent Dawn! We go to gather more aid! Fight on, brothers and sisters. And know that you will not long fight alone!\"",},
			["Lord Maxwell Tyrosus"] = { content = "'''Lord Maxwell Tyrosus''', nicknamed '''Max''' by [[Argus Highbeacon]], is a [[human]] [[paladin]] located at [[Light's Hope Chapel]] in the [[Eastern Plaguelands]], and in the [[Sanctum of Light]] as the Hand of the [[Adventurer|Highlord of the Silver Hand]] during the [[third invasion of the Burning Legion]].\r\nHe was one of the first to join the [[Argent Dawn]] and quickly rose through the ranks to great prominence, second only to [[Tirion Fordring]] himself in the [[Argent Crusade]]. Whether he was fighting against the scourge of [[Naxxramas]] or the very [[Lich King|lord of the Scourge]], Tyrosus has always remained a steadfast leader and a true champion of the [[Light]].\r\nHe is the former leader of the Argent Dawn, and currently the highest rank member of the Argent Crusade following Highlord Tirion's death, leading and representing the Crusade during the third invasion.\r\n===The Ashbringer===\r\nSoon after the [[Third War]], Lord Maxwell Tyrosus joined [[Alexandros Mograine]]'s crusade against the [[undead]] and insisted on working with other races. Maxwell accompanied his lord and comrades, [[Brigitte Abbendis]] and [[Fairbanks]] to the [[Scarlet Monastery|Monastery]] where they found troll [[Zabra Hexx]]. While Brigitte insisted on killing him, he stopped her to speak with the troll.\r\nFollowing Alexandros' demise, the order became more zealous and fanatic and eventually reformed itself into the [[Scarlet Crusade]]. He left the order with [[Argent Officer Pureheart|Pureheart]] and joined the [[Argent Dawn]], eventually succeeding [[Lord Raymond George]] and becoming its leader in the [[Plaguelands]] and one of the highest-ranking officers in the organization as a whole. He found [[Darion Mograine]] and let him join the order. Maxwell brought him to the [[Chillwind Point]] and learned that Alexandros' spirit may be alive. He wanted to help Darion to attack [[Naxxramas]] but Darion insisted that he is very important for the Dawn. Instead, Darion found volunteers at the Point.\r\nMaxwell and the rest of the Dawn moved to the [[Light's Hope Chapel]] where the [[Scourge]] was about to attack them. Darion, having visited [[Tirion Fordring]], returned to the Chapel and Maxwell revealed to him the Chapel's secret. When the Scourge attacked, he alongside other Argent Dawn members defended the place and witnessed the sacrifice of Darion. He then remained in contact with [[Tirion Fordring]].\r\n===Compendium of Fallen Heroes===\r\nDuring the [[Siege of the Sanguine]], a major battle between the Scourge and the Argent Dawn at Light's Hope Chapel, Lord Maxwell Tyrosus dealt a critical blow to [[Kirkessen the Zealous]], a powerful [[lich]] who reported directly to the [[Lich King]] himself. Since its defeat, the lich is now no longer able to assume a corporeal form.\r\n===World of Warcraft===\r\nLord Maxwell Tyrosus resides in Light's Hope Chapel and rarely sees visitors from outside his organization, as it has been years since he has granted audience to outsiders. From there he coordinates the troops of the Argent Dawn to fight the Scourge in the Eastern Plaguelands, and was planning with [[Nicholas Zverenhoff|Duke Nicholas Zverenhoff]] an offensive on [[Stratholme]] to eliminate [[Baron Rivendare]].\r\nHe also received a husk from a silithid by an adventurer sent by [[Colossus Researcher Sophia]], which he thought to be useful in the war against the Scourge.\r\n==Abilities==\r\n*Avenging Wrath\r\n*Crusader Strike\r\n*Denounce\r\n*Divine Storm\r\n*Hammer of the Righteous\r\n==Quests==\r\n*[[Shrine of the Truthguard (quest)]] \r\n*[[The Silver Hand (quest)]] \r\n*[[The Search for the Highlord]] \r\n*[[We Meet at Light's Hope]] \r\n*[[An Urgent Gathering]] \r\n*[[A Hero's Weapon (paladin)]] \r\n*[[Walking in Shadows]] \r\n*[[Crossing Legion Lines]] \r\n*[[Hope Prevails]] \r\n*[[Seeking Guidance]] \r\n*[[The Light Reveals (quest)]] \r\n*[[A United Force]] \r\n*[[Logistical Matters]] \r\n*[[A Light in the Darkness (paladin)]] \r\n*[[Seeker of Truth (artifact)]] \r\n*[[The Mysterious Paladin]] \r\n*[[Weapons of Legend (paladin)]] \r\n*[[A Sign From The Sky]] \r\n*[[An Urgent Warning (paladin)]] \r\n*[[Bolstering Your Arsenal]] \r\n*[[Completing Your Arsenal]] \r\n*[[Growing Power (paladin)]] \r\n*[[Investigate the Broken Shore (paladin)]] \r\n*[[Meeting of the Silver Hand]] \r\n*[[Rise, Champions (paladin)]] \r\n*[[The Blood Matriarch]] \r\n*[[The Highlord's Command]] \r\n*[[The Scion's Legacy]] \r\n*[[Forging New Strength]] \r\n*[[The Fate of Azeroth]] \r\n*[[Visitors]] \r\n*[[A Boyhood Dream]] \r\n*[[Argent Call: The Noxious Glade]] \r\n*[[Argent Call: The Trial of the Crypt]] \r\n*[[Lord Maxwell Tyrosus (quest)]] \r\n*[[The Argent Hold (quest)]] \r\n*[[Secrets of the Colossus - Zora]] \r\n===Legion===\r\nQuest text\r\n*Highlord, so long as you wield the [[Ashbringer]], the [[Burning Legion|Legion]] will do everything in their power to strike you down.\r\nWe must not allow that to come to pass - you are our single greatest hope to drive the demons back to the holes they crawled out of.\r\nI humbly submit myself to your direct service, <name>. I will act as your eyes and blade where you are not; I will carry out your will until my dying breath.\r\nLord Maxwell Tyrosus at your service.\r\n====On-click====\r\nGreeting\r\n*We will prevail.\r\n*Azeroth will not fall while we stand.\r\n*At your service.\r\nPissed\r\n*I've been through more than you know.\r\n*Don't test me! I always hated tests.\r\n*The light does not favor those who pastor.\r\n*Ugh, I need a blessing of patience.\r\nFarewell\r\n*Walk always in the light.\r\n*Take care of yourself out there.\r\n*You can always count on me.\r\n*May the light give you strength.\r\n====Gossip====\r\nSanctum of Light\r\nWith the Order of the Silver Hand reformed under your leadership, we have new direction and guidance.\r\nWe have much work ahead of us.\r\n=====Ashbringer appearance - Shard of Darkness=====\r\nDo you feel it as well, Highlord? Something isn't right.\r\n''''\r\nI see.\r\nI trust your wisdom, Highlord, but I can't say that this sits well with me.\r\nHow can we ever be sure that the power within that thing won't... change you?\r\n''''\r\nYou're right, but how can we ever hope to tap into that safely? Our power will only...\r\n<Tyrosus pauses.>\r\nThe Ebon Blade.\r\n==Notes and trivia==\r\n*Maxwell Tyrosus and [[Uther the Lightbringer]] are old friends.\r\n*Despite ''[[World of Warcraft: Ashbringer|Ashbringer]]'' implying he was the original leader of the Argent Dawn when it was created by stating that he is \"the leader of the new order\", [[Lord Raymond George]] is stated to have been the original leader.\r\n**It is just possible that Raymond died soon after the Argent Dawn was formed. Given that the Argent Dawn did not exist for very long prior to its Classic depiction, during which time Tyrosus had taken charge, Raymond must have died very early onto the organization's inception; perhaps early enough that the Dawn would still be considered a 'new order'.\r\n*Tyrosus was voiced by an unknown actor in ''[[World of Warcraft: Wrath of the Lich King|Wrath of the Lich King]]'', and is voiced by [[Josh Petersdorf]] in ''[[World of Warcraft: Legion|Legion]]''.\r\n*He wears [[White Tiger Plate]] and wields a [[Greatsword of the Silver Hand]] during his appearance in ''[[World of Warcraft: Legion|Legion]]''.\r\n*Humorously, while holding his telescope during his time at the Broken Shore, he will be holding it up to the eye with the patch covering it.\r\n==See also==\r\n*[[Champion: Maxwell Tyrosus]]",},
			["Lord Maxwell Tyrosus (quest)"] = { content = "==Objectives==\r\nSpeak with [[Lord Maxwell Tyrosus]]. He is inside the church. \r\n==Description==\r\nI am about to bestow a great honor upon you, <name>.\r\nLord Maxwell wishes to reward you for your service to the [[Argent Dawn]]!\r\nIt has been years since Maxwell has granted audience to outsiders. \r\n==Completion==\r\nYou are a worthy ally, <name>. You shall reap the rewards of your stalwart dedication.",},
			["Lord Melenas"] = { content = "'''Lord Melenas''' is a level 8 [[satyr]] found in [[Fel Rock]] in [[Teldrassil]]. He is a vicious Satyr, who managed to amass a small army of [[grell]]s led by [[Threggil]], to protect him in his chosen lair of Fel Rock, just north of [[Dolanaar]]. Melenas has the ability to transform into a black [[saber]], which means some satyrs possibly still practice druidism. [[Tallonkai Swiftroot]] wants Melenas' head for his practices.\r\n==Quests==\r\n*Twisted Hatred\r\n==Loot==\r\n*Melenas' Head - Quest Item",},
			["Lord of the Clans"] = { content = "'''''Lord of the Clans''''' is a novel by [[Christie Golden]] telling the story of [[Warchief Thrall]]'s rise to glory after the collapse of the [[Old Horde|Horde]]. It is an adaptation of the cancelled [[Blizzard Entertainment|Blizzard]] game ''[[Warcraft Adventures: Lord of the Clans]]''. It was republished in 2016 for the [[Blizzard Legends]] series.\r\nAn [[audiobook]] version read by [[wikipedia:Dick Hill (narrator)|Dick Hill]] was released in February 2009. \r\n==Description==\r\n''\"I will not be here long,\" said Thrall.\r\n\"Come spring, I will rejoin Grom Hellscream, and help his noble clan storm the camps and free our people.\"\r\n\"Grom Hellscream,\" sneered the stranger, waving his hand dismissively. \"A demon-ridden dreamer. I have seen what the humans can do, and it is best to avoid them, believe me.\"\r\n\"I was raised by humans, and believe me, they are not infallible!\" cried Thrall. \"Nor are you, I would think, you coward!\"\r\n\"Thrall--\" began Drek'Thar, speaking up at last.\r\n\"No, Master Drek'Thar, I will not be silent. This stranger comes seeking our aid, eats at our fire, and dares to insult the courage of our clan and his own race. I will not stand for it. I am not the chieftain, nor do I claim that right. But I will claim my right to fight this stranger, and make him eat his words sliced upon my sword!\"\r\nThe strange Orc laughed heartily and rose. He was almost as big as Thrall, and now, to his astonishment, Thrall saw that he was completely clad in black plate armor, trimmed with brass. Uttering a fierce cry, the stranger opened his pack and pulled out the largest warhammer Thrall had ever seen. He held it aloft with seeming ease, then brandished it at Thrall.\r\n\"See if you can take me, whelp!\"''\r\n==Back-of-book description==\r\nSlave. Gladiator. [[Shaman]]. [[Warchief]]. The enigmatic [[orc]] known as [[Thrall]] has been all of these. Raised from infancy by cruel [[human]] masters who sought to mold him into their perfect pawn, Thrall was driven by both the savagery in his heart and the cunning of his upbringing to pursue a destiny he was only beginning to understand—to break his bondage and rediscover the ancient traditions of his people. Now the tumultuous tale of his life's journey—a saga of honor, hatred, and hope—can at last be told....\r\n==Characters==\r\n==Locations==\r\n*[[Alterac Mountains]]\r\n*[[Arathi Highlands]]\r\n**[[Hammerfall]]\r\n*[[Hillsbrad Foothills]]\r\n**[[Durnholde Keep]]\r\n==Other==\r\n*[[Cycle]]\r\n*[[Hawks and Hares]]\r\n*[[Hunting cup]]\r\n*[[Magical net]]\r\n*[[Mock fighter]]\r\n*[[Morningstar]]\r\n*[[Oath Cry]]\r\n*[[Courier station]]\r\n*[[Choose]]",},
			["Lord Prestor"] = { content = "#REDIRECT [[Deathwing]]", redirect = "Deathwing",},
			["Lord Pythas"] = { content = "'''Lord Pythas''' is a level 20 [[elite]] [[night elf]] found in the [[Wailing Caverns]].\r\n==Background==\r\nA seasoned [[warrior]] and once one of [[Naralex]]'s personal guard, the corrupted Lord Pythas now uses his skills in battle to aid the Druids of the Fang.\r\n==Abilities==\r\n'''Thunderclap''' - Inflicts Nature damage to nearby enemies, slowing their movement and attack speed.\r\n* School: [[Nature]]\r\n* Dispel: [[Magic]]\r\n'''Lightning Bolt''' - Blasts an enemy with lightning, inflicting Nature damage.\r\n* School: [[Nature]]\r\n'''Sleep''' - Puts a member of the party to sleep for 15 seconds.\r\n* Dispel: [[Magic]]\r\n==Combat Info==\r\nPythas is the toughest of the Leaders of the Fang. He puts out a lot of melee damage, and he has a lot of hitpoints. He also has 1 elite [[druid]] and 1 Elite [[shambler]] with him. Either kill the [[add]]s first, or keep them [[Crowd Control|CC]]'d until Pythas is dead. \r\n*Note that the druid that accompanies Pythas can sleep a member of the party. If the tank is asleep, Pythas will move to the next highest target on his aggro list.\r\n*If the other two adds are cc'd, or off tanked ( another leather / mail wearer or a pet tanking the shambler ) and the druid polymorphed or ignored, a balanced party can take down Pythas fairly quickly. Then focusing on the remaining adds shouldn't be a problem.\r\nPythas has a chance to drop the [[Armor of the Fang]], which is part of the bind-on-pickup [[Embrace of the Viper]] set; the drop rate for this is quite high.\r\nIt can happen under certain circumstances that Pythas, like Kresh before in the instance, due to a bug, walks into the ground or a rock and becomes stuck. This counts as a death for the Naralex summoning event, but the NPC in question cannot be looted.\r\n==Quests==\r\n*Leaders of the Fang\r\n==Quotes==\r\n'''Aggro''' ''The coils of death... Will crush you.''",},
			["Lord Raadan"] = { content = "'''Lord Raadan''' is one of several potential adds in the [[Hex Lord Malacrass]] encounter in Zul'Aman. He casts [[Thunderclap]] and [[Flame Breath]] and can be slept.",},
			["Lord Ravencrest"] = { content = "#REDIRECT [[Kur'talos Ravencrest]]", redirect = "Kur'talos Ravencrest",},
			["Lord Roccor"] = { content = "'''Lord Roccor''' is a level 51 [[elite]] [[lava elemental]] [[mini-boss]] found in the [[Halls of the Law]] inside [[Blackrock Depths]].\r\nHe is notable for dropping a [[Relic|druid idol]], as well as the [[enchanting]] formula for the [[Smoking Heart of the Mountain]].\r\nHis attacks are [[physical]], [[fire]] and [[nature]] based. \r\nCasts:\r\n*[[Earth Shock]]\r\n*[[Flame Shock]]\r\n*Ground Tremor: Knockback and stun to all enemies within a 15 yard radius.\r\n*Reflective Skin(passive): Gives the ability to reflect an offensive spell back to the caster.\r\nPointers:\r\n*He patrols the back half of the circular [[Halls of the Law]].\r\n*Keep tank well healed as his Ground Tremor ability will interrupt any spells being cast.",},
			["Lord Saltheril"] = { content = "'''Lord Saltheril''' is a level 18 [[quest giver]] located at [[Saltheril's Haven]] in the [[blood elf]] starting zone of [[Eversong Woods]].\r\n==Quests==\r\n* The Party Never Ends\r\n* finishes Saltheril's Haven\r\n==See Also==\r\n*[[List of Eversong Woods NPCs]]",},
			["Lord Sanguinar"] = { content = "'''Lord Sanguinar''' is one of the four blood elf advisors that aid [[Kael'thas]] during the boss encounter in [[the Eye]]. He appears to be a [[Paladin]]. Kael'thas refers to him by the title \"The Blood Hammer\".\r\nSee [[Kael'thas Sunstrider (tactics)]] for details on the fight.\r\n===Encounter in The Eye===\r\n* \"Blood for blood!\"\r\n* \"No! I will not...\"",},
			["Lord Serpentis"] = { content = "Lord Serpentis is a [[hostile]] level 20 [[elite]] [[night elf]] in the [[Wailing Caverns]].\r\n==Background==\r\nOnce a [[druid]] of great power and prestige, Lord Serpentis has been corrupted by [[Naralex]]'s nightmare and now leads the Druids of the Fang.\r\n==Abilities==\r\n'''Lightning Bolt''' - Blasts an enemy with lightning, inflicting Nature damage.\r\n* School: [[Nature]]\r\n'''Sleep''' - Puts an enemy to sleep for up to 10 seconds. Any damage caused will cancel the effect.\r\n* School: [[Nature]]\r\n* Dispel: [[Magic]]\r\n==Combat Info==\r\n* 2800 health\r\nSerpentis doesn't do anything particularly noteworthy, but he's almost as tough as Pythas. Kill the [[mob]]s around him before you pull him, and then just kill him as fast as possible. You shouldn't have any significant problems with him; just keep him away from your [[caster]]s.\r\nSerpentis has a chance to drop the Footpads of the Fang, which is part of the bind-on-pickup [[Embrace of the Viper]] set.\r\n==Quests==\r\n*Leaders of the Fang\r\n==Quotes==\r\n'''Aggro''' ''I am the serpent king, i can do anything.'' (A parody of the Jim Morrison line, \"I am the lizard king, I can do anything.\")",},
			["Lord Shalzaru"] = { content = "'''Lord Shalzaru''' is a level 47 [[named]] [[naga]], and is the cruel royal leader of the [[Hatecrest Naga]]. It is rumored that he himself has uncovered an odd relic during a recent naga excavation in a cave south of the main ruins, across the water on the [[Isle of Dread]] in [[Feralas]].\r\n==Quests==\r\n*Against Lord Shalzaru\r\n==Loot==\r\n*Mysterious Relic ''(Quest Item)''",},
			["Lord Skwol"] = { content = "'''Lord Skwol''' is a [[hydra]] [[boss]] summoned at a [[Wind stone|Greater Windstone]] in [[Silithus]]. He is a powerful elemental being requiring 20-40 people to defeat. ''He is significantly more difficult than the other 3 summoned bosses''. Summoning him requires a full [[Twilight Trappings]] set, a [[Twilight Cultist Medallion of Station]], and a [[Twilight Cultist Ring of Lordship]].\r\n==Abilities==\r\n* Venom Spit - 1200 damage to everyone in the raid. 40 yard range. Also leaves a stackable poison [[DoT]]. Once every 20 to 30 seconds.\r\n* Sunder Armor - Uses stackable [[Sunder Armor]] on the main tank. Decreases armor by 1000. \r\n==Strategy==\r\n* Cleanse the stackable poison [[DoT]] quickly.\r\n* Set up a 2 or 3 man [[tank]] rotation to counter the stackable [[Sunder Armor]] ability.\r\n==Loot==\r\n*Abyssal Scepter\r\n*Wavefront Necklace\r\n*Abyssal Mail Armguards of ...\r\n*Abyssal Plate Epaulets of ...\r\n*Essence of Water\r\n*Elemental Water\r\n*Globe of Water",},
			["Lord Solanar Bloodwrath"] = { content = "'''Lord Solanar Bloodwrath''' is a level 70 [[quest giver]] located in [[Farstriders' Square]] in [[Silvermoon City]], standing in the room formerly inhabited by [[M'uru]]. He has taken over the training of aspiring Blood Knight Masters, a task formerly handled by the Blood Knight Matriarch, [[Lady Liadrin]] — who has since journeyed to Shattrath and become part of the [[Shattered Sun Offensive]]. He may be related to [[Champion Bloodwrath]].\r\nHe is involved in the following quests:\r\n# A Summons from Lord Solanar\r\n# The Master's Path\r\n# A Gesture of Commitment\r\n# A Demonstration of Loyalty\r\n# True Masters of the Light\r\n# True Masters of the Light (2)\r\n# True Masters of the Light (3)",},
			["Lord Talendar"] = { content = "'''Lord Talendar''' is a skeleton king killed by [[Rexxar]], [[Cairne Bloodhoof]], [[Rokhan]] and [[Chen Stormstout]] in the [[Tomb of the Ancients]] outside of [[Vol'jin]]'s new base camp in Act Two of the Orcish Bonus Campaign.\r\nWhile he lived, Talendar was drawn to the arcane, even though he was unable to cast spells himself. He thus decided to surround himself with the arcane and locked himself within the temple which was to become his tomb.\r\n==Statistics==\r\n* level 16\r\n* 10,000 HP\r\n* 301-307 normal melee damage\r\n* 10 heavy armor",},
			["Lord Thorval"] = { content = "'''Lord Thorval''' is a level 80 elite [[human]] [[death knight trainer]] at [[Acherus: The Ebon Hold]] in the [[Eastern Plaguelands]].",},
			["Lord Valthalak's Amulet"] = { content = "==Source==\r\nThis item can be aquired through crafting or another combine-type effect.\r\nThis item is provided for Final Preparations.\r\n==Lord Valthalak's Amulet as a quest objective==\r\nThis item is an objective for the following quests:\r\n* The Right Piece of Lord Valthalak's Amulet\r\n* The Right Piece of Lord Valthalak's Amulet\r\n* The Right Piece of Lord Valthalak's Amulet\r\n* The Right Piece of Lord Valthalak's Amulet\r\n* Mea Culpa, Lord Valthalak",},
			["Lord Valthalak"] = { content = "'''Lord Valthalak''' is a [[Drakonid]] [[boss]] summoned in [[Upper Blackrock Spire]] by a [[Brazier of Beckoning]]. Strangely, he is categorized as a [[humanoid]], and not as a [[dragonkin]] like other drakonids. He is the last boss in the [[Dungeon Set 2]] quest line.\r\n===Phase 1:===\r\nValthalak has a caster type weak melee attack in phase 1. A slow one that does 400-500 damage to a warrior.\r\n====Shadow Wrath====\r\nA shadow-based, chain life drain, which obviously translates into healing for himself. Hits for 750 Shadow damage on the first target, and will jump to another target if anyone is close enough. Each time it jumps, it doubles in damage in the manner of Holy Wrath from [[High Priest Venoxis]] from [[Zul'Gurub]]. At the 4th jump, the damage will be 6k and lethal for most people. Being a life-drain, all damage dealt will heal Valthalak.\r\n*Keep him away from the raid party and don't let anyone get close enough for a bounce to chain to the rest of the group. A distance of 20 to 30 yards is fine.\r\n*Ensure that your party is spread out from each other so if a chain is unavoidable, you at least minimize the bounces. Or alternatively, try the Blackstar Triangle of Doom, described below.\r\n====Heal====\r\nThe chain life drain (noted above) will replenish his health, so it is important that you have a warrior tank the mob alone (until phase 2). Alternately, if you have more people in melee range, you will need to interrupt when he casts the life drain. It will show as a purple beam that chains between friendly targets.\r\nHave one or two people mana drain him (his regen and total mana are quite low). The spell is also interruptible using standard methods([[Shield Bash]], [[Earth Shock]], [[Counterspell]], etc.). A mod such as EnemyCast or Spell Alert can be helpful. All his spells will sadly not show up on the standard 'EnemyCastBar' you can have displayed below the enemy portrait.\r\nLord Valthalak apparently has no specific animations when he heals. Warriors with [[Mortal Strike]] would greatly assist, as well as rogues with wound poisons. It is also possible to just DPS through the heals. The rate that Valthalak heals himself appears to be random.\r\n====Spectral Assassins====\r\nThese spawn two at a time throughout phase 1. They will run towards someone in your raid (can include pets) and eventually cast a mindflay-like Defile ability (a purple vile beam). Defile cannot be dispelled/cleansed and stuns its target for ten seconds. If the spell is allowed to complete, its target dies and is transformed into an additional Spectral Assassin. The assassins have around 1,500 hp with little to no armor and resistances.\r\n*Everyone must kill Spectral Assassins as soon as they appear. Be wary if you use a mouse to target because they can be hard to see and click. You can hit 'v' to bring up the Mob Health panes or use this macro: ''/target Spec'' (recommended). If you use a keyboard for targeting, no adjustments are necessary; just do as usual.\r\n*They '''can''' be damaged by [[Area of Effect]] spells.\r\n*The spectral assassins' Defile '''cannot''' be interrupted by normal methods([[Kick]], [[Shield Bash]], etc). Other abilities like [[Scatter Shot]], [[Concussion Blow]], [[Hammer of Justice]],... do work. Use them if you cannot kill the Assassin in time to save a raid member.\r\n*Ranged DPS plays a key role here as [[Hunters]], [[Mages]], [[Warlocks]], and [[Shaman]] can kill the assassins without having to frantically cross the room. This can be critical particularly when they spawn at or near Valthalak.\r\n*[[Stun]] spells work best to disrupt Defile.\r\n===Phase 2: Enrage===\r\nAt 40% health he will switch weapons and start hitting very hard. He stops spawning Spectral Assassins but still does Shadow Wrath if he has mana.\r\n*[[Disarm]] him whenever available.\r\n*By this point your tank should have a great deal of threat accumulated so just burn him down.\r\n===Phase 3: Shadow Bolt Volley===\r\nAt 15% health, he will frequently cast an AoE [[Shadow Bolt]] on the entire raid in addition to the changes in phase 2.\r\n*Maximize your DPS, finish him fast.\r\n*Use a [[Greater Shadow Protection Potion]] if necessary to minimize the shadow damage.\r\n==General Advice==\r\n*If you plan on doing several attempts, have someone logout a character that can resurrect in The Beast's room. If you wipe, you can simply log them in and resurrect a healer in your party to continue.\r\n*Valthalak can be disarmed so do it whenever it's up (particularly in phase 2). He doesn't hit that hard to begin with, but this will help your healers conserve mana, which will be much more needed when his damage picks up in phases 2 and 3.\r\n*If all rogues and other melee dps stay behind Valthalak at max range opposite the tank shadow wrath will not hop to them.\r\n*Have priests cast [[Prayer of Shadow Protection]] on the group before starting.\r\n==Summary==\r\nThis strategy results in an easy, but long fight, usually 7-10 minutes. Your healers need to come prepared for an endurance fight, other than that it makes for an easy run.\r\n==Quests==\r\n*Mea Culpa, Lord Valthalak",},
			["Lord Victor Nefarius"] = { content = "#REDIRECT [[Nefarian]]", redirect = "Nefarian",},
			["Lord Xavius"] = { content = "#redirect [[Xavius]]", redirect = "Xavius",},
			["Lore"] = { content = "'''Lore''' in the Warcraft series of games is a term used for \"background story\". The use of the term stems from Blizzard's snippets of \"lore\" for many of the multiplayer maps in their Warcraft RTS games, although how much of it has a relationship to the main [[Warcraft universe]] storyline is unclear.\r\n==Major areas==\r\nArticles\r\n*[[Timeline (disambiguation)|Timelines]]\r\n*[[Retcon]]s — changes in lore\r\n*[[:Category:Worlds|Locations]]\r\n*[[Organization|Organizations, clans, factions, etc.]]\r\n*[[Religion]]s\r\n*[[Magic]]s\r\n*[[Technology|Technologies]]\r\n*[[Class lore]]\r\n*[[Language]]s\r\n*[[Warcraft universe|Source]]s\r\n==What is \"canon\" lore?==\r\n'''Canon''' is a term oft-used to refer to official lore, specifically the fictional accounts in the Warcraft universe. It is used to define which lore should be considered a genuine part of the universe's history. \r\nThe Warcraft 'canon' comprises those works and sources of information considered to be authoritative and representative of the 'true' or official history of the Warcraft universe. Therefore, 'canon' or 'canonical' lore is that which is part of this body of work, and is thus considered part of the true history of the Warcraft universe.\r\nIn contrast, 'non-canon' information, while often containing characters and depicting events from canon sources, is not necessarily a reliable source of official information regarding the Warcraft universe. An example of non-canon lore might be a piece of fan fiction which introduces new characters or events, or expands upon the background of a known character such as Thrall. \r\nCharacters, events and items from non-canon sources do not necessarily exist in the official Warcraft universe. Non-canon versions of known events may differ substantially from official sources. Non-canon sources frequently feature characters from canon lore, but their exploits in these sources are not considered canon. \r\nNote that even canon lore is sometimes contradictory (or [[retcon|retconned]]), often representing the beliefs or perspectives of an individual or group, rather than any absolute truth. Nonetheless, the beliefs themselves can be considered a genuine part of the Warcraft universe as [[flavor lore]], regardless of their accuracy.\r\n===Canon===\r\n* Everything released by Blizzard except mods and the table-top RPG is considered canon. This includes games, novels, short stories, manga, and comics as well as trailers and cinematics. [[Warcraft Encyclopedia]], [[History of Warcraft]], game [[manual]]s and original Warcraft RTS games are also considered canon but in some cases they are overwritten or modified by novels (i.e. history of [[eredar]] retconned in ''[[Rise of the Horde]]'', ''[[War of the Ancients]]'' and its aftermath slightly altered by the time-travel in the novel, ''[[Dawn of the Aspects]]'' revealing the true history of the Aspects instead of a legend told in a History chapter, and ''[[Tides of Darkness]]'' with ''[[Beyond the Dark Portal]]'' setting a canon line of events for the first RTS games which had two versions of the ending).\r\n* The current history of Warcraft was slightly retconned by the ''[[WoW Chronicle]]'' series.\r\n* No longer available quests that were not replaced by new information should be canon.\r\n===Non-canon===\r\n* As ''[[Warcraft Adventures: Lord of the Clans|Warcraft Adventures]]'' was never released, its story and information are non-canon.\r\n* While not officially confirmed by Blizzard, the multiplayer RTS maps (such as [[Griffon's Roost]], [[Brokenrock Mountains]] and [[Beetle Island]]) are probably non-canon.\r\n* [[Alex Afrasiabi]] clarified that [[Med'an]] as a character, as well as the comic book series, is canon. Only Med'an becoming the Guardian is considered non-canon.\r\n====Roleplaying Game====\r\n*Though originally considered to be part of lore, Blizzard has stated that the sourcebooks for the ''[[Warcraft RPG]]'' are not considered canon by default.\r\n*They were created to provide an engaging table-top role-playing experience, which sometimes required diverging from the established video game canon. Blizzard helped generate a great deal of the content within the RPG books, so there will be times when ideas from the RPG will make their way into the game and official lore, but unless otherwise stated, an element from the RPG is not canon.\r\n*\"When something goes out the door at Blizzard—in a game, a novel, a manga, or anything other than mods or the table-top RPG—it's canon.\"\r\n====Trading Card Game====\r\n*While the artwork of some cards was overseen and sometimes edited with Blizzard's Creative Development department input, with [[Chris Metzen]] suggesting some of the cards and being particularly vigilant about the way named heroes were handled, Blizzard declared that the ''[[World of Warcraft Trading Card Game]]'' is not considered canon, and neither are its cards descriptions. Moreover, and contrary to ''[[Hearthstone (game)|Hearthstone]]'', \"there is no tie-in story for the TCG and it is not a mini-game within ''[[World of Warcraft]]''\".\r\n====Film universe====\r\n* The [[Warcraft (film)|''Warcraft'' film]] and its related publications are similar in concept to the line and are a separate continuity from the games because it is an alternative universe. That fact makes it canon in Lore terms, like the WoD universe and other alternative universes. Chris Metzen talked about this at [[BlizzCon 2013]] and compared it with the with the Warcraft Universe film, that makes the two universes canon but separated from the main universes.\r\n====Hearthstone====\r\n* From an in-universe Warcraft perspective, ''[[Hearthstone (game)|Hearthstone]]'' is a magical card game played by many of Azeroth's denizens, containing its own colourful depictions and \"tavern tales\", constituting [[flavor lore]].\r\n* From an out-of-universe perspective, ''Hearthstone'' as a video-game is not canon to the lore of Warcraft, and it also may not accurately represent things as they really are, as it is more of a \"what-if?\" scenario and spin on ''Warcraft''. However, if the ''World of Warcraft'' team wants to, they are able to take elements of ''Hearthstone'' and implement them into ''World of Warcraft'', such as happened with [[Sir Finley Mrrgglton]], making them canon.\r\n** See also: [[hswiki:Hearthstone lore|Hearthstone lore]]\r\n====Heroes of the Storm====\r\n*''[[Heroes of the Storm]]'' is not canon when it comes to the lore of ''World of Warcraft''.\r\n*The Heroes team does contact teams behind the respective franchises in order to obtain the most accurate source material regarding descriptions of various items and maps, but in terms of \"canon\" the Nexus is pretty loose, as they experiment with alternate realities and crossovers. Nexus lore should not be taken as die hard facts, but as more of a crazy \"what-if?\" universe.\r\n===Azeroth's scale===\r\nThe representation of the world in ''World of Warcraft'' is not entirely canon as Azeroth's scale had to be reduced for gameplay purposes. For example, [[Ironforge]] is a lot bigger than we see in the game. Similarly, [[Ruins of Lordaeron|Lordaeron]] is bigger in lore as evidenced in the ''[[Battle for Azeroth]]'' cinematic. The ''[[World of Warcraft: Chronicle|Chronicle]]'' series also offers [[:File:Chron3 map of Azeroth after the Cataclysm.jpg|a more accurate scale]] of the world, continents and islands, than the in-game world map; for instance, the [[Broken Isles]] are shown to be roughly the size of the [[Howling Fjord]], and [[Kul Tiras]] is about the size of [[Gilneas peninsula|Gilneas]], compared to the [[:File:WorldMap-World.jpg|in-game map]].\r\nFor example of continental size, [[Kalimdor]] in-game is about 20,920 yards, or roughly 19 kilometers long from the bottom of [[Uldum]] to the tip of [[Winterspring]]. When compared to in real life, which is about 8,000 kilometers long, Kalimdor is a meager 0.002375% the size of Africa. As such, Kalimdor would be somewhere around 421 times longer in lore than it is in-game if the size of Azeroth is comparable to and Kalimdor to Africa.\r\n===Dungeons, quests, mobs and other===\r\nSometimes, player actions in dungeons are not taken into consideration, as observed in the story of [[Blackfathom Deeps]]. Despite the fact that the players / adventurers killed its inhabitants, when the dungeon was updated, it was stated that the inhabitants were killed by the new inhabitants instead of players / adventurers. Another example may be seen in the [[Dagran Thaurissan]] encounter where players from both factions killed the Emperor, but ''[[The Shattering: Prelude to Cataclysm]]'' established that Dagran was killed by the Alliance agents. Another one may be seen in the original [[Scarlet Monastery]] dungeon with the [[Corrupted Ashbringer/Scarlet Monastery Event|Ashbringer event]] which were made non-canon as they were retconned by the [[World of Warcraft: Ashbringer|Ashbringer comic]].\r\nSeveral quests and quest lines become non-canon and retconned when overwritten by a later source of lore such as the ending of the [[Onyxia]] [[Onyxia's Lair attunement|questline]] (originally available since Vanilla) being replaced by the story of ''[[World of Warcraft: The Comic|The Comic]]'' (happening between the events of ''[[World of Warcraft: The Burning Crusade|The Burning Crusade]]'' and ''[[World of Warcraft: Wrath of the Lich King|Wrath of the Lich King]]'').\r\nIn several occasions, ''[[World of Warcraft: Cataclysm|Cataclysm]]'' brought continuity errors, such as mobs being killed (their heads being brought to the quest givers) but remained alive after the revamp (such as the deaths of [[Weldon Barov]] and [[Alexi Barov]]). Sometimes, these \"deaths\" were explained as having evaded death and being just wounded as in case of [[Lieutenant Valorcall]] or [[Vanessa VanCleef]].\r\nThe final cinematic of ''[[World of Warcraft: Warlords of Draenor|Warlords of Draenor]]'' doesn't seem to be entirely canon as Blizzard stated that [[Archimonde (Hellfire Citadel tactics)|Archimonde]] died in the [[Twisting Nether]] instead of at the [[Black Gate]] in [[Tanaan Jungle]] on [[Draenor (alternate universe)|alternate Draenor]].\r\n==Blizzard's universes==\r\nAlthough some easter eggs exist within the Diablo, Starcraft and Warcraft games, the Diablo and Warcraft lore is separate.\r\n==Wowpedia's position on canon lore==\r\nWowpedia strives to have a [[Wowpedia:Neutrality policy|neutral point of view]] on official lore due to it being rarely discussed by [[Blizzard Entertainment|Blizzard]], although examples exist:\r\n*[[Chris Metzen]] has stated that some things are less canon than others, but he wants everything as integrated as possible:\r\n''...yeah, the novels are pretty much considered canon, ahm, the funny thing is that some things are less canon, you know, but we shoot for canon... that's a strange statement... <small>we shoot for canon...</small> but yeah, typically the characters in novels are canon.''\r\n''A lot of times... depending on when one thing gets started during another, we happen to be in the middle of the game, or doing the [[manga]] thing for instance or this [[World of Warcraft: The Comic|comic series]] specifically, we try to engineer as much inner play as possible. Like characters in the manga series showing up in [[Netherstorm]] and we are doing stuff like that, so we want to make everything feels as continuity friendly and as integrated as possible. Cause that would make it cool as if all its moving, right.''\r\n*Creative Development Blog explains some of the hazards of game writing:\r\n''...As more content is added to a given universe, by different teams, there is always the danger of unintentionally contradicting existing lore. But we have never intentionally done it. When something goes out the door at Blizzard—in a game, a novel, a manga, or anything other than mods or the table-top RPG—it's canon. This can be quite unwieldy; someone may have made a decision 12 years ago that was a well-reasoned, smart choice back then, but boxes us in today… but that's the hazard of game writing. We have to find a way to live with it and still tell our story.''\r\n''Sometimes there is an area where we haven't established exactly what happened, and we have room to define it at need. When we do this, some think that we've \"retconned\" it, but it's only retconning if we actively contradict known lore, not if we elaborate on something that was not defined.''\r\nWhile we cannot stop the use of the term \"canon\" in talk page discussions, the term is not allowed in articles. The only exceptions are when one is denoting RPG information, or when verifiable public quotes from actual first-party Blizzard employees (such as Chris Metzen) are allowed in articles, and then only if there are direct links to the sources of the quotes.\r\n'''For more on Wowpedia's lore policy, see [[Wowpedia:Lore policy]].'''\r\n==See also==\r\n*[[Lore links]] - external lore sources.\r\n*[[In-jokes and references]]",},
			["Lorekeeper Lydros"] = { content = "'''Lorekeeper Lydros''' can be found in [[the Athenaeum]] of [[Dire Maul]] West, which can be accessed from the West or North wings.\r\n==Quests== \r\n==Quotes==\r\n*''\"What you must understand is that being able to index 10,000 years of existence has given me a rather unique perspective on life. Your present day trials and tribulations are meaningless.\"''\r\n*''\"I very much doubt that [[Kariel Winthalus|he]] will have anything to say, stranger... I personally did not mind him. It was the Prince who took exception to a high elf in his domain. Alas, I am not one to question the Prince. In his defense, he did not incinerate Master Winthalus immediately. We most definitely do not need any more attention drawn to us, stranger. Return to those who sent you in search of the lost master and tell them that nothing could be found. When this is done - and I will know when it is so - return and I shall reveal the secrets of the deceased.\"''",},
			["Lorekeeper Polkelt"] = { content = "'''Lorekeeper Polkelt''' is a level 60 [[elite]] [[zombie]] [[mini-boss]] found in the [[Scholomance]]. Polkelt is one of the six mini-bosses that are required to call forth [[Darkmaster Gandling]]. Polkelt is notable among them in that he is the only one of the six that does not drop a [[Corruptor's Scourgestone]]. As we can tell from his name, he was once the keeper of knowledge, knowledge that has sadly been lost, however, as he is now a shambling, uninteligent monster.\r\n==Spells and Abilities==\r\n*'''Corrosive Acid''': reduces target's armour by 960\r\n*'''Noxious Catalyst''': reduces nature resistance by 88\r\n*'''Volatile Infection''': 400-500 nature damage to the target and the target's allies",},
			["Lorena"] = { content = "'''Lorena''' is an officer in the [[Theramore]] Army. She is one of the very few female soldiers and has worked very hard to gain what she has attained. She is one of Lady [[Jaina Proudmoore]]'s most trusted soldiers and Proudmoore frequently makes good use of Lorena's military leadership abilities.\r\n===The Cycle of Hatred===\r\n[[Lorena]]. was one of the main characters in Cycle of hatred.\r\nAfter the Third War, Lorena has been promoted by Jaina herself to a colonel. \r\n[[Margoz]] was one of the recruiters at Theramore at the [[Demonsbane]] Inn, [[Burx]] was believed to fool Thrall and make the Horde forces, and [[Kristoff]] to get the forces of Theramore while [[Jaina Proudmoore]]'s Absence. Kristoff has tasked Lorena into gooing with a group of warrior's to [[Northwatch Hold]] [[Northwatch]]. she took with her four warriors, and droped the reinforcements at Northwatch, and continued to [[Bladescar]]. she arrived and met [[Aegwynn]] and [[Jaina]] and rescued them from Bladescar by [[Zmodlor]]'s wards, they found the minor demon, and destroyed [[Zmodlor]] Forever.",},
			["Loreth'Aran"] = { content = "#redirect [[Ruins of Loreth'Aran]]", redirect = "Ruins of Loreth'Aran",},
			["Lore Keeper of Norgannon"] = { content = "'''The Lorekeeper of Norgannon''' is an artificial intelligence construct left by the [[Titan]] [[Norgannon]] the Lorekeeper in the bowels of the Titan research facility known as [[Uldaman]]. The primary role of the lorekeeper seems to be the recording and dissemination of information stored on the Disks of Norgannon, which are involved in the quest The Platinum Discs (Neutral). The watcher shares a great deal of information about the [[Earthen]], the [[Troggs]], and the [[Dwarves]]; all of which appear to be the result of a single experiment in creating subterranean life on the part of the Titans. While the Dwarves were believed to be in some ways superior to their Earthen ancestors, the Troggs were considered an undesirable aberration.\r\nSee [[Uldaman NPCs]].\r\n==The Lorekeeper's Knowledge==\r\nThe transcript of the conversation players have with the Lorekeeper in Uldaman has been highly requested, as it is usually either quickly browsed or skipped altogether in the player's haste to exit the instance. Below is the complete text of the conversation. Text in quotation marks indicate the player's chosen response to the Lorekeeper (there's actually only one answer to choose in between).\r\nSalutations. My function is to offer access to and, when permissible, insight into informations regarding the Creators' synthesis of the Earthen on the world designated as Azeroth. I am ready to share this information with you now at your leisure.\r\n ''Who are the Earthen?''\r\nThe [[Earthen]] are a synthesized race engineered by the Creators, functioning as one of the seed races in the initial population of the world designated as [[Azeroth (world)|Azeroth]]. The [[Earthen]] were created to aid the Creators' efforts in shaping the deep regions of this world.\r\nThey are a modification of the standard subterranean being matrix used on other worlds that the Creators have seeded. The construction of this prototype race created various anomalies that were observed after initial synthesis.\r\n''What is a 'subterranean being matrix' ''\r\nIt is one of the synthesis matrices the Creators use when seeding a world. Each synthesis matrix is used to achieve the Creators' goals. For Azeroth, a subterranean being matrix was modified to create a being with increased durability with an affinity for deep region shaping; the Earthen are the product of this modification.\r\nAfter the Earthen had been put into service for the Creators, unforeseen anomalies were discovered that affected their synthesis matrix due to high-stress environments.\r\n''What are the anomalies you speak of?''\r\nAdditional background information on the Earthen must be given to you before this question may be answered properly. Processing.\r\nTo understand the anomalies of the Earthen, it is first important to understand what the Earthen represent in their design intent. The Earthen represent the Creators' attempt at improving the survivability paradigm of the standard subterranean being matrix. This was done by incorporating a resilient foundation of construction inherent to the world into said matrix.\r\n''What is a resilient foundation of construction?''\r\nIt is the baseline material used in race synthesis. A cross-section of Azeroth's crust was used as the foundation for the Earthen's synthesis rather than the typical biomass construction foundation used by the Creators.\r\nResearch on the world's composition led the Creators to theorize that an enhanced being could be synthesized that would epitomize the resiliency of this world's essence. This was accomplished by choosing to use a blend of Azeroth's various stone core compounds as the foundation.\r\n''So... the Earthen were made out of stone?''\r\nSimply stated, this is correct.\r\nThe Earthen's physical features are that of a smaller stature humanoid, though their composition is that of Azeroth's various stone core compounds. Their design maximizes strength and stamina without sacrificing cognitive processing power. Their skin and musculature are nearly impervious to physical damage, and with very minor modifications the Earthen display a remarkable resiliency to unwanted magical forces.\r\n''Anything else I should know about the Earthen?''\r\nIt is integral to the assimilation of this data that it is understood that the Creators wanted to synthesize a race that would long be an integral part of this world's development cycle after they had departed. This race would be instrumental in fulfilling the Creators' long-term development objectives for Azeroth.\r\nAs an ancillary note, the nomenclature \"Earthen\" was deemed apropos for the new race by the Creators, based on the Earthen's composition.\r\n''I think I understand the Creators' design intent for the Earthen now. What are the Earthen's anomalies that you spoke of earlier?''\r\nThe Earthen's only anomaly in synthesis is the tendency for [[Curse of Flesh|matrix destabilization]] while being utilized in high-stress environments.\r\nAddendum: Deep earth sculpting was naturally suited to the new matrix design and thus never met the qualifications of duplicating a high-stress environment.\r\nDestabilization was not discovered until well into the Earthen's primary service cycle for the Creators. The Creators began work on post-synthesis modification, rather than recall and re-synthesis.\r\n''What high-stress environments would cause the Earthen to destabilize?''\r\n[There is a noticeable pause after you ask this question.]\r\nThe information you request is not currently available in this repository's data cycling. I sincerely apologize for this omission.\r\nPlease request this information after a data cycling update has been performed on this information repository. You may also request this information from another information repository located on Azeroth.\r\n''What happens when the Earthen destabilize?\r\nThere are two potential results when the Earthen's synthesis matrix destabilizes. Initiating visual aid representation number one.\r\nThe first variant matrix is a degenerative product of synthesis, hereby designated with the common nomenclature of \"Trogg\". This variant maintains strength and stamina comparable to the Earthen, but its cognitive processing power has been almost completely compromised. Force of will and a strong sense of cunning are the only driving factors in the psyche of the trogg.\r\n''Troggs?! Are the troggs you mention the same as the ones in the world today?''\r\nI am unable to process your chronological reference in comparison to the recording of this data, my apologies.\r\nThe trogg retains some composition of Azeroth's various stone core compounds, but the loss of cognitive power makes this variant unacceptable to the Creators.\r\nThe trogg procreates as per a standard biomass. By default it consumes stone and anything else it can acquire, including other troggs. Cannibalism is considered unacceptable by the Creators.\r\n''You mentioned two results when the Earthen destabilize. What is the second?''\r\nInitiating visual aid representation number two.\r\nThe second resultant variance of the Earthen matrix retains many desired elements when compared to the standard subterranean matrix. The common nomenclature for this variant is \"Dwarf\".\r\nThis variant retains strength and stamina inherent to the Earthen. In some cases, the dwarf even exceeds the cognitive powers of the Earthen's matrix. The dwarf, however, retains none of the physical composition of Azeroth's various stone core compounds.\r\n''Dwarves!!! Now you're telling me that dwarves originally came from the Earthen?!\r\nThe data stored in this repository does indeed correlate with your astute proclamation.\r\nThe dwarf maintains an affinity for the stone composition of Azeroth, but due to the high-stress environmental anomaly within the Earthen's synthesis matrix, the dwarf reverts to a default biomass composition as seen in the standard subterranean matrix.\r\nErgo, the dwarf variant does synthesize from the degeneration of the Earthen creation matrix, as you inferred with your query.\r\n''These dwarves are the same ones today, yes? Do the dwarves maintain any other links to the Earthen?''\r\nI am unable to process your chronological reference in comparison to the recording of this data, my apologies.\r\nThough the dwarf maintains most of the Earthen's mental attunement to Azeroth's stone composition, the reversion back into living biomass remains the main degeneration of the matrix. Dwarves eat and procreate through means typical to other standard biomasses.\r\nThe Creators view the dwarf as an acceptable variant, worthy of genesis in its own right.\r\n''Who are the Creators?''\r\nThe Creators are... the Creators.\r\nThey are the beings that seeded and shaped this world by their own design. They are the reason for this world's existence, as well as many other worlds. They are the wellspring from which Azeroth flows.\r\n''This is a lot to think about.\r\nThe Creators are cognizant of the magnitude of the information housed in this repository. Subsequently, a portable copy of the data stored here will be made available to your once you are attuned with the Discs of Norgannon. \r\nPlease consider your cursory requirements for the assimilation of this knowledge to be complete. At your leisure, access the Discs of Norgannon to begin synthesis of your discs.\r\n''I will access the discs now.''",},
			["Lorin Remka"] = { content = "Major '''Lorin Remka''' was the commander of one of the many internment camps where the [[orc]]s were held after the [[Second War]]. During the Second War, Remka disguised herself as a male to join the Alliance army so she could avenge the killing of her family and the sacking of her village. Her deception was discovered, and her commander placed her back at the front hoping she would be killed (to spare him the trouble of reporting her). She survived, however, and took great pleasure in killing orcs in combat—even going so far as to cover her face with their blood to mark her victory. \r\nRemka apparently enjoyed as much luxury as she was able while in command of her camp—even using a female orc slave named [[Greekik]] as one of her servants. When [[Thrall]] was captured and held there, word reached [[Aedelas Blackmoore]], master of the internment camps, at his fortress of [[Durnholde]]—and he immediately travelled to the encampment to retrieve his \"pet orc\". However, Remka's orc servant warned Thrall of Blackmoore's arrival, and the future Warchief took the opportunity to escape from Remka's camp. \r\nUpon realizing that Thrall had been there but had managed to escape, Blackmoore demoted Remka and placed one of her lieutenants, [[Waryk]], in command of the camp. Her fate following this is unknown.",},
			["Lorokeem"] = { content = "'''Lorokeem''' is a level 63 [[master]] [[alchemy trainer]] located in [[Lower City]] in the [[neutral]] [[Shattrath City]].\r\nHe is located on the lower tier of the far west treehouse in the north part of the city.\r\nSee [[List of Shattrath City NPCs]].",},
			["LoS"] = { content = "#REDIRECT [[Line of sight]]", redirect = "Line of sight",},
			["Lost Barrens Kodo"] = { content = "Level 14-15 [[kodo]]s found around the various oasises in the northern [[Barrens]]. They drop Kodo Meat and Thin Kodo Leather. Druids seek out their Kodo Horns for use in preparing antidotes, and NPC|Horde|Brewmaster Drohn}} uses their Kodo Livers to make Trogg Ale.",},
			["Lost Fleet"] = { content = "'''The Lost Fleet''' (also known as the '''Doomed Fleet''', or the '''Third Fleet''', and the '''Kul Tiras Third Fleet''') are the remnants of the [[Kul Tiras (kingdom)|Kul Tiras]] fleet which was under the command of [[Derek Proudmoore]] during the [[Second War]]. They were destroyed by [[red dragon]]s controlled by the [[Dragonmaw clan]] and subsequently sunk in [[Baradin Bay]] off the coast of northern [[Bluegill Marsh]]. The ships located here are named ''[[Wave Mistress]]'' and ''[[Intrepid]]''. A third ship, ''[[Flying Osprey]]'', was part of the Third Fleet, but sank south of [[Menethil Harbor]]. The only survivor was [[First Mate Fitzsimmons]] of the ''Wave Mistress''.\r\nThe crew of the ships are cursed with [[Undead|undeath]] due to a forbidden artifact one of the vessels carried: A [[:Cursed Eye of Paleth]], a blackened orb hidden deep in the cargo hold of the ''Intrepid'', kept locked away by its greedy commander, [[Captain Halyndor]]. Its curse affects anyone trying to locate the orb, transforming the living temporarily into an illusionary undead form and weakening their spirits. The ghost of [[First Mate Snellig]] can be found on the nearby shore. He appears to be the only undead crew member that has retained his sanity.\r\nAt Fitzsimmons' urging, the Eye of Paleth was recovered by an adventurer and cleansed several years before the [[Cataclysm (event)|Cataclysm]], however the curse was not lifted. Fitzsimmons eventually drank himself to death, but even then did not escape the curse, and is damned to forever hear his crewmates calling for him.\r\n[[Third Fleet shipwrecks|More shipwrecks]] of the fleet were found by the Horde in a different location on the bottom of the [[Great Sea]] decades later. The Horde obtained the corpses of Derek Proudmoore and [[Marshal M. Valentine]] from the wrecks.\r\n==Ships and crew==\r\n*''[[Pride of Tiragarde]]'' - Sunk in the Great Sea\r\n** [[Marshal M. Valentine]], Captain, and Marshal of the Kul Tiran Third Fleet\r\n** [[Derek Proudmoore]], Captain of the Kul Tiran Third Fleet\r\n** [[Gerard (Tides of Darkness)|Gerard]], Lookout\r\n*''[[Fathomdasher]]'' - Sunk in the Great Sea\r\n** [[Ellis R. Ladimore|Knight-Captain Ellis R. Ladimore]], Captain\r\n** [[Alison Flint|Sergeant Major Alison Flint]]\r\n** [[Jameson Keefe|Corporal Jameson Keefe]]\r\n** [[Lorelai Whetstone|Private Lorelai Whetstone]]\r\n** [[James Simmons|Private James Simmons]]\r\n*''[[Songswallow]]'' - Sunk in the Great Sea\r\n** [[Andrew Avrinn|Lieutenant Commander Andrew Avrinn]], Captain\r\n** [[Murgatroyd Smith|Master Sergeant Murgatroyd Smith]]\r\n** [[J. Mills|Sergeant J. Mills]]\r\n** [[Jarrod|Provisioner Jarrod]]\r\n** [[Geoffrey Van Houten|Private Geoffrey Van Houten]]\r\n*''[[Gale's Reprieve]]'' - Sunk in the Great Sea\r\n** [[Priscilla Hawes|Commander Priscilla Hawes]], Captain\r\n** [[Samuel Robertson|Knight-Lieutenant Samuel Robertson]]\r\n** [[O'Keefe|Quartermaster O'Keefe]]\r\n** [[Eloise Hesterfield|Corporal Eloise Hesterfield]]\r\n** [[Sarah Gallows|Private Sarah Gallows]]\r\n*''[[Drustvaria]]'' - Sunk in the Great Sea\r\n** [[Dirk Longfellow|Knight-Champion Dirk Longfellow]], Captain\r\n** [[Chris Lee|Sergeant Chris Lee]]\r\n** [[Evan Morris|Sergeant Evan Morris]]\r\n** [[Aloysius Millsworth|Corporal Aloysius Millsworth]]\r\n** [[Ava MacArthur|Private Ava MacArthur]]\r\n*''[[Wave Mistress]]'' - Wreck in the Wetlands\r\n** [[First Mate Fitzsimmons]]\r\n*''[[Intrepid]]'' - Wreck in the Wetlands\r\n** [[Captain Halyndor]] - Captain\r\n** [[First Mate Snellig]] (presumed)\r\n*Unknown ships\r\n** [[Cursed Sailor]]s\r\n** [[Cursed Marine]]s\r\n===High elven ships===\r\n*''[[Flying Osprey]]'' - Wreck in the Wetlands\r\n==Notes==\r\n*The undead of the Lost Fleet can transmit you the [[Curse of the Eye]] when hitting you.\r\n==See also==\r\n*[[Third Fleet Cloak]]",},
			["Lost Fold"] = { content = "'''The Lost Fold''' on [[Bloodmyst Isle]] is a site where broken cages and debris from the crashing [[Exodar]] has landed, similar to the [[Menagerie Wreckage]] on [[Azuremyst Isle]]. It contains numerous wandering [[ravager]]s and is located just North of Kessel's Crossing",},
			["Lost in Battle"] = { content = "==Objectives==\r\nFind Mankrik's wife and then return to him in the Crossroads.\r\n*Find Mankrik's Wife\r\n==Description==\r\n''We battled in a small tauren camp when we were separated--she held three of the Bristlebacks off by herself. But the odds began to overwhelm us. I led some away only to see her overwhelmed by newcomers. In my rage, I turned to face my enemies, but they brought me down easily with their vast numbers.\r\nI awoke to a tauren druid tending my wounds--he had come across me on the Gold Road as I fell.\r\nPlease, <class>, find some sign of my wife.'' - ''Mankrik''\r\n==How to Complete==\r\nFrom the Crossroads, head south. You'll cross a bridge - on your map it's close to where a small trail leads south from Lushwater Oasis (Wailing Caverns) and meets the main road. From the bridge you'll see two huts off to the western side. In front of one of them lies a [[Beaten Corpse]] (Mankrik's Wife). Inspect it, then return to Mankrik.\r\n===Inspection Text===\r\n''You turn the body over and see the marks from blades and spells upon the deceased orc -- her armor all but destroyed, her hair matted to her face.\r\nBased on Mankrik's description of her, there is no doubt in your mind that this was his wife.\r\nHe will be upset by the news, but you are sure he should know the truth.''\r\n==Completion==\r\n''I understand. Thank you, <class>.''\r\n==Rewards==\r\nYou will receive: s=9 gold \r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*1150 [[XP]] (or s=7 gold c=20 silver at level 70)\r\n*150 with [[Orgrimmar]]",},
			["Lost One"] = { content = "The '''[[Draenei]] Lost Ones''' are highly mutated and [[wiktionary:devolution|devolved]] draenei. They have devolved further than the [[Broken]] draenei, and have become more savage and primitive. The term can be used in two senses: to refer to all of these devolved draenei, or to refer solely to a tribe of Lost Ones living in the [[Swamp of Sorrows]] in [[Azeroth (world)|Azeroth]].\r\n==History==\r\nThe Draenei that originated in the world of [[Argus]] moved to the world they called [[Draenor]] and began living among the races of that world. The draenei lived alongside [[orcs]] for countless generations. However, when the orc clans of Draenor became the [[Horde]] at the behest of the [[Burning Legion]], their blades were first whetted on the peaceful draenei tribes. Nearly the entire race was eradicated by this horrendous massacre. \r\nSoon after, the demonic energies that now seethed through Draenor began to corrupt and twist many of the surviving draenei, turning them into [[Broken]]. Later, when that world exploded and crumbled into what is now known as [[Outland]], a few managed to survive the cataclysm. However, some of them were further devolved into a more primitive stage than the Broken ones. These draenei became the Lost Ones, and are usually shunned by the rest of the draenei. They have forsaken the Holy Light practices which they once had and have instead started to use [[Warlock]] magic. They have became violent and unpredictable, even toward their own kind. \r\n==Tribes==\r\nThere are several tribes of Lost Ones, both in Azeroth and in Outland.\r\nThe Lost Ones tribe in Azeroth is sometimes referred simply as \"Lost Ones\". When the [[Dark Portal]] was reopened into Azeroth, a small number of Broken draenei lead by [[Magtoor]] travelled through, scarred by the ordeal of their world’s destruction. Called the [[Broken Exiles]], they live in [[the Harborage]] in the [[Swamp of Sorrows]]. However, many of these Brokens' sanity slipped from them, accelerated by their separation from their homeworld. They devolved, sequestered themselves from outsiders, and began attacking anyone and everyone on sight. These ragged wretches now call themselves the \"Lost Ones\", in mourning of their former world.\r\nThese Lost Ones separated from Magtoor's Broken Exiles, and established a colony in the [[Swamp of Sorrows]] called the [[Fallow Sanctuary]], though some have begun to travel beyond the Swamp’s borders in recent times. Some of these Lost Ones, called [[Portal Seeker]]s, continually wander around the [[Blasted Lands]], desperately seeking a means to return home. Another factor that keeps these draenei alive is revenge against the orcs who once lived among them. They will take any risk to see an orc killed.\r\nThere are several Lost Ones tribes in Outland. There are three tribes in [[Zangarmarsh]]: the [[Daggerfen]], the [[Feralfen]] and the [[Umbrafen]]. There is also a tribe in [[Terokkar Forest]], the [[Tuurem]], and another one in [[Nagrand]], the [[Windyreed]]. See also [[Draenei factions and organizations]] for more details.\r\n==Name==\r\nThe name first came from the tribe in the Swamp of Sorrows who called themselves \"Lost Ones\". This was in mourning of their former world that they were homesick for, and unable to return to with the Dark Portal closed.\r\nAccording to [[Rise of the Horde]], these draenei who had been living on Azeroth for years were ''nicknamed'' \"lost ones\", and are still considered as draenei to others.\r\nThe short story ''[[Unbroken (story)| Unbroken]]'' hints that the name was given to them by the draenei in Outland long before they came to Azeroth because their minds are lost.\r\n==Notable Lost Ones==\r\n*Chieftain Mummaki\r\n*Elder Kuruti\r\n*Kataru\r\n*Noboru the Cudgel",},
			["Lost Ones"] = { content = "#redirect [[Draenei Lost Ones]]", redirect = "Draenei Lost Ones",},
			["Lost Point"] = { content = "'''Lost Point''' is a run-down, decrepit tower built by the [[humans]] of [[Theramore Isle]]. It is located in western [[Dustwallow Marsh]], and is currently inhabited by Theramore deserters. [[Balos Jacken]] is these deserters' leader, and has information about [[Private Hendel]]'s part in the kidnapping of a very important personality.",},
			["Lost Rigger Cove"] = { content = "Protected by mountains on three sides, '''Lost Rigger Cove''' is the hideout of the [[Southsea Pirates]] on the coast of [[Tanaris]]. Agents of the [[Steamwheedle Cartel]] constantly attempt to disrupt the pirates' shipbuilding operations here. Killing Southsea Pirates will earn [[reputation]] with [[Gadgetzan]].\r\n==Quest Guide==\r\nThe area is loaded with humanoids, bearing [[human]] male, human female, male [[goblin]], male and female [[trolls]], and male [[gnoll]] models. Outside, there are camps and random mobs scattered about, easy enough for single pulls. But nearing the dock, there are houses with mobs packed tightly together. Consider bringing a friend or being heavily specialized in your pet to handle multiple mobs and possibly adds.\r\n====[[Gadgetzan]]====\r\n* WANTED: Andre Firebeard\r\n====[[Steamwheedle Port]]====\r\n* Southsea Shakedown - from [[Security Chief Bilgewhizzle]]\r\n* Pirate Hats Ahoy! - from <Fashion Designer> [[Haughty Modiste]]\r\n===Quests to Get After Arriving===\r\n* Ship Schedules - from item Ship Schedule to [[Steamwheedle Port]]\r\n* Cuergo's Gold - from item Cuergo's Treasure Map to [[Lands End Beach]]\r\nCuergo's Treasure Map is formed by joining the Upper, Middle, and Lower Map Fragments, each random drops from Pirate's Footlockers. The Ship Schedule is another random from Pirate's Footlockers.",},
			["Lost Soul"] = { content = "The '''Lost Soul''' is a level 7 [[rare mob]] [[ghost]] found roaming a small area by [[Agamand Mills]] in [[Tirisfal Glades]]. She is one of the many [[banshee]]s of the [[Scourge]] that are still loyal to the [[Lich King]] and remains under his control. She is on a 1-2 hour respawn timer, however it is possible for several to be out at the same time.\r\n==Loot==\r\n*Wispy Cloak",},
			["Lost Thunderbrew Recipe"] = { content = "The '''Lost Thunderbrew Recipe''' shows how to brew Thunderbrew Lager, an ale created by [[Ragnar Thunderbrew]] which is reported to give the inbiber great strength. The recipe was stolen by [[Hurley Blackbreath]] of the [[Dark Iron Dwarves]].\r\n==Source==\r\nThis item drops from [[Hurley Blackbreath]] in the [[Grim Guzzler]] tavern in [[Blackrock Depths]].\r\n==Lost Thunderbrew Recipe as a quest objective==\r\n*Hurley Blackbreath\r\n*Lost Thunderbrew Recipe",},
			["Lost Torranche"] = { content = "'''Lost Torranche''' can be found in [[Terokkar Forest]] . It can be tamed by a [[hunter]]. \r\nThis [[tallstrider]] cannot be found on the mainland. The only existing population is found at [[Sorrow Wing Point]]. \r\n==Drops == \r\n \r\n0.05% Chance of a [[rare]] drop.\r\n1.48% Chance of an [[Uncommon]] drop.\r\n1.70% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Lothar"] = { content = "Lothar may refer to;\r\n*[[Anduin Lothar]]\r\nor\r\n*Lothar of Theramore.",},
			["Lothos Riftwaker"] = { content = "'''Lothos Riftwaker''' is a level 60 [[quest giver]] located just outside the entrance to [[the Grinding Quarry]] in the [[contested]] territory of [[Blackrock Mountain]]. To get to him, walk down the second chain heading towards [[Blackrock Depths]]. He is standing in a small chamber right at the entrance. Just talk to him after having completed the attunement quest at any time and to be teleported into the [[Molten Core]]. This also works while you are dead and corpse running back. Jumping in the lava outside the window works just the same as talking to him.\r\nLothos starts the quest Attunement to the Core (Dungeon).\r\nSee [[List of Blackrock Mountain NPCs]] and [[List of blood elves in Azeroth]].\r\nFor his old model,",},
			["Lothros"] = { content = "'''Lothros''' is a Lieutenant of [[Illidan]] at [[Illidari Point]], [[Shadowmoon Valley]].\r\nHe is involved in Against the Illidari quest.",},
			["Lotwil Veriatus"] = { content = "'''Lotwil Veriatus''' is a level 36 [[quest giver]] located in a small camp just east of [[Kargath]] in the [[contested]] territory of [[Badlands]]. Born in [[Kharanos]], this [[gnome]] wants to build a University for the [[Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences]]. He is stationed together with his sarcastic assistant [[Lucien Tosselwrench]] and his robot guardian [[Servo]], working on his newest project: shackles of elemental binding. This proved to be quite unsuccessful, summoning an elemental of big proportions. He is very absent-minded, and is very focused on his work. He likes to join everything together: in his latest project, [[engineering]], [[alchemy]] and arcane arts were joined together to.. fail.\r\nHe starts the following quests:\r\n* Study of the Elements: Rock\r\n* Coolant Heads Prevail (Alchemy)\r\n* Gyro... What? (Engineering)\r\n* Study of the Elements: Rock\r\n* Study of the Elements: Rock\r\n* This Is Going to Be Hard\r\n* This Is Going to Be Hard\r\n* 58] [[Quest:The Rise of the Machines|The Rise of the Machines]] (Dungeon)\r\nSee [[List of Badlands NPCs]].",},
			["Love is in the Air"] = { content = "'''Love is in the Air''' is an event that takes place around Valentine's Day (around February 11-15). The first Love is in the Air event occurred in 2006, and was repeated in 2007 and 2008.\r\nFrom on the official site:\r\n''Something is in the air in the major cities of Azeroth. Some call it love, and some just call it friendship and admiration. Whichever it is, many guards and townsfolks now spend their days giving and receiving tokens and gifts to other amorous citizens.''\r\n''The more skeptical, however, are suspicious of the strange \"love sickness\" clouding the hearts of so many. Will this widespread occurrence be simply taken as a recent outbreak of amore? Or will our brave adventurers find a sinister plot behind the source of this plague of passion? Only time will tell...''\r\n==Details==\r\nTo start, talk to an [[Innkeeper]] with a over their head and purchase Love Token, and either a Perfume Bottle or a Cologne Bottle. Immediately use either the perfume or cologne on yourself. This will provide a 60 minute Cologne/Perfume [[buff]]. Walk around any major city and you should see [[NPC]] city guards with hearts () above their heads.\r\n===Giving Tokens===\r\nInteract with any one of them and you will be prompted (talk bubble) to give them a love token.\r\nA guard will not give out items after receiving a token for 1-2 minutes.\r\nIf your inventory is full and you talk to a guard with a heart above their head and they accept your token, they will '''not''' give you something in return.\r\n====Cologne vs. Perfume====\r\n* Use cologne if you want to give a love token to a female NPC.\r\n* Use perfume if you want to give a love token to a male NPC.\r\nAfter giving a token, several things will happen:\r\n===Pledge or Gift===\r\nIf you do not currently have the debuff [[Adored]], you will receive a Pledge of Adoration or Gift of Adoration [[gift]], and the debuff Adored. If you do currently have the debuff Adored they will give a Pledge of Friendship or Gift of Friendship gift. This rule applies for all NPCs.\r\n====Heartbroken====\r\nSometimes when you attempt to give a token to an [[NPC]] they will not give you an item in return and will instead give you the \"[[Heartbroken]]\" debuff. This debuff prevents you from giving tokens to any [[NPC]]s for 60 minutes. This happens randomly.\r\nThe debuff can be removed if a [[player character]] uses an Unbestowed Friendship Bracelet on you. Once this happens the debuff will disappear and you will have a Friendship Bracelet in your inventory. This item does not have a known purpose.\r\n====Pledge of Adoration====\r\nWhen you get a Pledge/Gift of Adoration, you cannot receive another until the Adored Buff fades. During that 60 minute period you will receive Pledges/Gifts of Friendship instead.\r\nThe Pledge/Gift of Adoration can contain a variety of items:\r\nBox of Chocolates: Contains an assortment of six chocolates with a variety of powerful buffs:\r\n* Buttermilk Delight - Increase [[Defense Rating]] by 20.\r\n* Dark Desire - Increase [[Hit Rating]] by 20.\r\n* Sweet Surprise - Increase [[Healing]] by 44.\r\n* Very Berry Cream - Increase [[Spell]] [[Damage]] by 23\r\nBag of Candies: Binds on pickup. Has 10 charges and a cooldown of 10 minutes. When used, creates a Heart Candy with the [[player character|player character's]] name stamped on it. Heart Candies are based on the . Each one bears an expression of affection such as \"I'm all yours!\" or \"I'll follow you around Azeroth.\" Their only purpose is to give to other players.\r\nHandful of Rose Petals: Causes rose petals to rain down around a player for a period of time. This is a purely cosmetic effect. ''Not [[Soulbound|<font color=\"white\">Soulbound</font>]].''\r\nLove Rocket: Shoots a heart-shaped firework into the air.\r\nRomantic Picnic Basket: This item is permanent and has a 3 minute cooldown. Sets up a picnic basket with hearts on an umbrella. When one person alone clicks the basket, he will sit down and receive the buff \"Looking for Love...\" which is represented by the \"broken heart\" icon. When two or more people sit by it, they will receive a buff \"Romantic Picnic - You are enjoying a lovely meal...\" which is represented by the \"romantic picnic basket\" icon and all the players sitting will have floating hearts above their heads, randomly drink, eat, blow kisses, and laugh.\r\nSilver Shafted Arrow: Shoot at a [[player character]] and the [[small pet]] version of [[Kwee Q. Peddlefeet]] will follow them around providing that player character doesn't already a have a pet. Can have up to 10 charges. Expires after 10 days in-game.\r\nUnbestowed Friendship Bracelet: Use to cure [[Heartbroken]] [[debuff]]. The recipient gets a Friendship Bracelet with no known purpose after curing the broken heart.\r\nTruesilver Shafted Arrow: Summon's [[Truesilver Shafted Arrow|Kwee Q. Peddlefeet]], a [[small pet]] that will follow you around.\r\nLove Fool: Acts like a Target Dummy. When dropped on the ground, nearby monsters will attack it. Lasts for 3 minutes. ''Not [[Soulbound]].'' Expires after 10 days.\r\nLovely Black Dress: A \"rare\" chest piece that is not soulbound.\r\n====Pledge/Gift of Friendship====\r\nAn NPC will give you a package after getting a token if you have the Adored Buff. What this contains highly depends on who you talk to.\r\n# Guards give a Card specific to the type of guard or a Pledge of Loyalty specific to their town.\r\n#* Horde cards: [[Grunt's Card]], [[Bluffwatcher's Card]], and [[Guardian's Moldy Card]].\r\n#** 5 of each makes: [[Package of Cards]], [[Satchel of Cards]], and [[Sheaf of Cards]].\r\n#* Alliance cards: Ironforge Guard's Card, Stormwind Guard's Card, and Sentinel's Card.\r\n#** 5 of each makes: Parcel of Cards, Bundle of Cards, and Stack of Cards.\r\n#* Horde pledges: [[Pledge of Loyalty: Orgrimmar]], [[Pledge of Loyalty: Thunder Bluff]], and [[Pledge of Loyalty: Undercity]].\r\n#* Alliance pledges: Pledge of Loyalty: Ironforge, Pledge of Loyalty: Stormwind, and Pledge of Loyalty: Darnassus.\r\n# Civilians (ie. shopkeepers) give \"Gifts of Friendship\"; trade goods like wine, boxes, bread, etc. specific to their town.\r\n#* Horde items: [[Freshly Baked Pie]], [[Freshly Picked Flowers]], and [[Romantic Poem]].\r\n#** 5 of each makes: [[Box of Fresh Pies]], [[Basket of Flowers]], and [[Book of Romantic Poems]].\r\n#* Alliance items: Dwarven Homebrew, [[Homemade Bread]], and [[Handmade Woodcraft]].\r\n#** 5 of each makes: Case of Homebrew, [[Sack of Homemade Bread]], and [[Box of Woodcrafts]].\r\n====Making a City Gift Collection====\r\n# When you have 5 Cards, 5 Pledges, and 5 Trade Goods, you can form a city-specific Gift Collection. When you complete this collection you will receive a 30 minute buff. You can only have one such buff active at a time.\r\n#* Horde: Undercity: +30 intellect, Orgrimmar: +30 Agility, Thunder Bluff: +30 Stamina.\r\n#* Alliance: Stormwind: +30 intellect, Darnassus: +30 Agility, Ironforge: +30 Stamina.\r\n# Collect Gift Collections from the all major cities to make an Alliance Gift Collection or Horde Gift Collection.\r\n# Turn the Alliance/Horde Gift Collection into [[Kwee Q. Peddlefeet]] near a city leader of your choice. The city leader that receives the most gift collections will have cupid hang around and buff players.\r\n# Handing this in gives you a Box of Chocolates, as well as your choice of one of the following:\r\n#* Handful of Rose Petalsx5\r\n#* Silver Shafted Arrowx5\r\n#* Love Rocketx5\r\n====Other Items====\r\nIt is not widely talked about, but during this time, a special item drops from 4 elites in a variety of old-world dungeons. Bouquet of Red Roses - This item acts the same as Handful of Rose Petals, but has an unlimited number of shots. It randomly drops from [[Archivist Galford]] in [[Stratholme]], [[Illyanna Ravenoak]] in [[Dire Maul]], [[Lorekeeper Polkelt]] in [[Scholomance]], and [[Princess Moira Bronzebeard]] in [[Blackrock Depths]].\r\n==[[Kwee Q. Peddlefeet]]==\r\nKwee Q. Peddlefeet is the host of the event. He is a goblin with wings. There is a Kwee Q. Peddlefeet by each faction leader. If you /kiss Kwee Q. Peddlefeet he gives a 60 minute +200 health buff. He also accepts Alliance and Horde Gift Collections.\r\nWhen you turn in an Alliance or Horde Gift Collection, Kwee Q. Peddlefeet will give you a choice of 5 Handful of Rose Petals, 5 Silver Shafted Arrow, or 5 Love Rocket.\r\nAt the end of the week the faction leader with the most gift collections will have Kwee Q. Peddlefeet stay by them and buff players for a week.\r\n===Dearest Colara, (Alliance quests)===\r\nNote: you will only be able to do one of these quests per character.\r\n* Ironforge: [[Tormek Stoneriver]] works at the bank in Ironforge and had his heart stolen by Colara and wants you to deliver a [[Creased Letter]] to her.\r\n* Stormwind: [[Lieutenant Jocryn Heldric]] wanders near the Auction House in Stormwind and wants you to deliver a [[Carefully Penned Note]] to his sweetheart Colara in Stormwind.\r\n* Darnassus: Starts by the bank in Darnassus from [[Aldris Fourclouds]], a night elf obsessed with the beauty of Colara in Stormwind (also near the bank) who wants you to give her a letter. Go to Stormwind and give the [[Immaculate Letter]] to [[Colara Dean]].\r\n===Dearest Elenia, (Horde quests)===\r\n* Dearest Elenia, (Orgrimmar) Starts by the bank in Orgrimmar from [[Orok Deathbane]], a lovesick orc who wants you to deliver a [[Slightly Creased Note]] to his... undead girlfriend whom he is embarrassed to be seen with. Is a prerequisite for the Fenstad's Hunch quest from [[Fenstad Argyle]].\r\n* Dearest Elenia, (Thunder Bluff) [[Temma of the Wells]] has found love outside the bluffs and wants you to deliver a [[Carefully Written Letter]] to Elenia.\r\n* Dearest Elenia, (Tirisfal Glades)Outside Undercity: Also given by [[Deathguard Tor]] who was once betrothed to Elenia and wants you to giver her a [[Lovingly Composed Letter]]. Go to the Undercity and speak with [[Elenia Haydon]] near the bank.\r\n===Dangerous Love (Alliance)===\r\nNote: Dearest Colara is the introduction to this quest. If you have it in your log, you can't get this one. However, if you start this chain before doing Dearest Colara, you will not be able to do that one.\r\nDangerous Love starts by the bank in Stormwind with [[Aristan Mottar]]. The first objective is to get a Stormwind Guard's Card. Then you must give a [[Perfume Bottle]] and a [[Cologne Bottle]] (purchasable at the inn) to [[Morgan Pestle]]. You will receive a box of chocolate and a handful of rosepetals for completing this step.\r\nUpon talking to [[Aristan Mottar]] again, he will ask you to speak with Innkeeper Allison. Allison will tell you to talk to Evert Sorisam, a man in \"The Finest Thread\" in the Stormwind Canals. [[The Finest Thread]] is near [[Cathedral Square]]. He will lead you to [[Apothecary Staffron Lerent]], who is behind [[Ravenholdt Manor]] in the [[Hillsbrad Foothills]]. Just in front of the manor you will see a practice ring, behind that is a path through the mountains. Go through that path and then to the left. You can sort of see on the map how this leads behind the manor.\r\nAfter talking to him, he will offer you the contents of his cauldron, which is a choice of:\r\n* [[Blue Dinner Suit]]\r\n* [[Purple Dinner Suit]]\r\n* [[Red Dinner Suit]]\r\n* [[Lovely Blue Dress]]\r\n* [[Lovely Purple Dress]]\r\n* [[Lovely Red Dress]]\r\nNote: You '''must''' right click on his cauldron and open it, otherwise you will not get your reward.\r\n===Dangerous Love (Horde)===\r\nNote: Before you can do this, you must complete Dearest Elenia.\r\n[[Fenstad Argyle]]...\r\nThe short quest chains that start with Dangerous Love eventually lead to the discovery of who is behind the love plague. The end reward is a choice of:\r\n* [[Blue Dinner Suit]]\r\n* [[Purple Dinner Suit]]\r\n* [[Red Dinner Suit]]\r\n* [[Lovely Blue Dress]]\r\n* [[Lovely Purple Dress]]\r\n* [[Lovely Red Dress]]",},
			["Lower Blackrock Spire"] = { content = "'''Lower Blackrock Spire''' is a 5-man instance designed for adventurers around levels 56-60. Its entrance is located inside [[Blackrock Mountain]], on the south side of the [[Hall of Blackhand]], across from [[Upper Blackrock Spire]].\r\n==Background==\r\nThe majority of [[Rend Blackhand|Rend]]'s [[Dark Horde]] reside in Lower Blackrock Spire, making the city a sort of sprawling [[barracks]]. Only the elite members of the Dark Horde are allowed to live in the upper reaches of the city. [[Overlord Wyrmthalak]] acts as the ruler and taskmaster of these soldiers.\r\nThe orcs of the [[Blackrock Clan]] dominate most of the ruins of Lower Blackrock Spire, though they are divided up into various legions. These include the [[Scarshield Legion]], the [[Bloodaxe Legion]], and the [[Firebrand Legion]]. The elite [[Blackhand Legion]] resides in Upper Blackrock Spire. The orcs share the city with a contingent of [[Spirestone]] [[ogre]]s and [[Smolderthorn]] [[troll]]s, who are also members of Rend's Dark Horde. The ruins are also home to a host of [[Spire Spider]]s who have infested a ruined corner of the city.\r\nAfter the fall of Rend's Dark Horde, [[Drakonid Monstrosity|Drakonid Monstrosities]] and [[Dragonspawn Refugee]]s can be seen in a portion of the dungeon.\r\n====Badlands====\r\n* [[Warlord's Command]]\r\n* [[Operative Bijou]]\r\n** [[Bijou's Belongings (Horde)]]\r\n* [[The Pack Mistress]]\r\n====Burning Steppes====\r\n*[[Kibler's Exotic Pets (quest)]] Stand-alone quest given by [[Kibler]] in [[Flame Crest]], [[Burning Steppes]].\r\n*[[En-Ay-Es-Tee-Why]] Stand-alone quest given by Kibler in [[Flame Crest]], [[Burning Steppes]].\r\n*[[Mother's Milk (quest)]] Stand-alone quest given by [[Ragged John]] in [[Flame Crest]], [[Burning Steppes]].\r\n*[[Put Her Down]] Stand-alone quest given by [[Helendis Riverhorn]] in [[Morgan's Vigil]], [[Burning Steppes]].\r\n====Lower Blackrock Spire====\r\n* [[Urok Doomhowl (quest)]] Stand-alone quest given by [[Warosh]], who wanders around the Spire\r\n* [[Bijou's Belongings (Alliance)]] Given by [[Bijou]], near the top of the troll area\r\n** [[Message to Maxwell]] Also given by [[Bijou]]\r\n*** [[Maxwell's Mission]] Given by [[Marshal Maxwell]] in [[Morgan's Vigil]] in the [[Burning Steppes]]\r\n* [[General Drakkisath's Command (quest)]] Starts from an item of the same name dropped by Overlord Wyrmthalak\r\n** [[General Drakkisath's Demise]] Given by [[Marshal Maxwell]] in [[Morgan's Vigil]] in the [[Burning Steppes]], enters [[Upper Blackrock Spire]]\r\n* [[Seal of Ascension (quest)]] Given by [[Vaelan]], to the left as you enter [[Hordemar City]], relatively near the entrance to the Spire. This grants you the \"key\" for [[Upper Blackrock Spire]].\r\n* [[Hot Fiery Death]] Requires [[Blacksmith]]\r\n====Winterspring====\r\n*[[Snakestone of the Shadow Huntress]] (reqs axesmith)\r\n====Elsewhere====\r\n*[[The Final Tablets]] Given by [[Prospector Ironboot]] in Steamwheedle Port in Tanaris, this quest is in the middle of a long quest chain between the Sunken Temple and Zul'Gurub\r\n==Related achievements==\r\n*[[Lower Blackrock Spire (achievement)]]\r\n*[[Lower Blackrock Spire Guild Run]]\r\n==Notes==\r\nPrior to Patch 6.0.2, it was part of the large [[Blackrock Spire]] instance, though it was often treated as separate from [[Upper Blackrock Spire]].\r\nSee also: [[Removed Lower Blackrock Spire quests]] and [[Lower Blackrock Spire walkthrough]].",},
			["Lower Blackrock Spire walkthrough"] = { content = "===The entry room===\r\nWhen you enter BRS, you will be in an \"entry room\" from which you can enter the Upper Spire (on the left) or the Lower Spire (on the right). The Upper Spire requires the [[Seal of Ascension]], and is entered through the door on left just up the short stairs. The Lower Spire can be reached by simply jumping off a ledge through the archway on the right-hand side, just up the stairs.\r\nAfter entering the first room, pull the 2 orcs on the left. Kill the patrols, and move to the bridge. Jump down the drop-off on the right side of the bridge. \r\n===To the Omokk/Voone fork===\r\nYou will now move through a series of platforms with groups of orcs and wolves. At the end of this section you will be at a fork where you can choose to enter the Ogre area (for Omokk) or to descend into the Troll area (for Vosh'gajin and Voone).\r\nAfter jumping down from the ledge, wait for another patrol there, being careful not to aggro it until it is far enough from the other mobs in this room. Pull and kill it.\r\nYou are now facing your first 'big' pull, of 4 orcs and 2 non-elite wolves.\r\nThe warlock must be controlled or killed immediately, because it will open a portal and summon demons which will overwhelm your group. If one of the Orcs is a warlock, follow these rules:\r\n* If you got a mage or a warlock using succubus, sheep/seduce the Warlock, and kill it last.\r\n* If you do not have the above classes, kill the Warlock FIRST. (Yes, even if you have a rogue; Sap just doesn't last long enough and the warlock will most likely awake before you are done with the rest).\r\n* In any case, use stuns and interrupts as much as you can to slow down the summon.\r\nAfter this group, go through the archway to the next room, which has another group of 4 orcs and 2 wolves. This group can often be split if you pull the left-hand wolf first. Warlock control rules apply again, as for all encounters in this area. You can then hug the left-hand wall to skip the orcs, as well as the next group of orcs as you descend the ramp down into the room.\r\n Note: This room has a shortcut to \"orc alley\", the first part of Wyrmthalak's area. If you jump off the right edge of the first platfrom, nearest the wall, you will reach a ledge from which you can jump down to an area full of orcs, close to the Spider lair. This is useful only if you want to skip ahead to the spider/Wyrmthalak part of the dungeon.\r\n Note: If you hang tight to the left wall and go ''up'' the slope, you will reach a platform where a Scarshield Infiltrator stands alone. Do not fear; this mob is actually Vaelan, a friendly NPC in disguise. When you approach him, he will turn into a friendly NPC that will give you the quest for the Upper Blackrock Spire key. This probably will not interest you until you get your Unadorned Seal of ascension and the Gems.\r\nBy hugging the left you wall you can reach the bottom of the ramp and handle another four orcs and two wolves. Cross the wooden bridge to the left and start pulling the groups of four orcs. This is where the pulls get tricky because you have to fight in a very small perimeter, while dealing with a warlock, and other casters that you must somehow pull to your group (using counterspell, earth shock, shield bash) to avoid runners.\r\nClear the next platform, unless the whole group is 60, in which case the left-most group can be skipped. Take the next wooden bridge to the right, clear the mobs after the 2nd bridge, and move up. Along the left wall you should see clickable \"Roughshod Pikes\". Pull the sleeping orcs next to them, and then loot the pike. It is needed for the quest Urok Doomhowl later on. By now, you should already have met Warosh, that ugly Trogg looking npc roaming around, and you should have the quest from him.\r\nPull to the right, then move up around a large crack in the floor. Be careful near this crack, characters below 60 or a misplaced totem near the edge will aggro many, many trolls from the area below the crack. Doing so will cause an almost certain wipe. You will now be facing an arch guarded by 3 ogres. This is the first fork. You may proceed through the arch to the ogre area, or go right and down the slope to the troll area. We'll be doing the ogre area first!\r\n===The Ogre Area===\r\nPull the ogres down the hallway, avoiding the bridges. The Ogre reavers have a knockback attack that will tend to toss people in the air and off the bridge if you're not careful. After you pass the bridge, you will enter a big room.\r\nSeveral rare mobs spawn around this area. On the left is a small rock \"hill\" with ogres on it. It can be ignored as long as everyone stands close to the right wall, but sometimes you'll find a [[Spirestone Battlelord]] or a [[Spirestone Lord Magus]]. Also a [[Spirestone Butcher]] may appear on the bridge leading into the room. All drop decent rare quality items.\r\nClear a few more ogres, and you'll see Highlord Omokk and his two guards.\r\n[[Highlord Omokk]] is possibly the easiest boss fight in Lower Blackrock Spire. Sheep, sap, freeze, or seduce one of the guards, or both if you can. If you can only control one, have your warrior tank the boss while the rest of the group focuses on killing the other ogre. Omokk has one annoying ability, which is an aggro-clearing knockback. The main tank should stand with his or her back to a wall so the knockback doesn't lead to an accidental pull on the hill, and should be ready to re-establish aggro with taunt or mocking blow.\r\nOmokk can drop a [[Gemstone of Spirestone]] needed for the [[Seal of Ascension]], and several blues, including the warrior set belt. The \"Important Documents\" required for the Horde quest [[Quest:Warlord's Command|Warlord's Command]] is on the floor next to where you fought Omokk.\r\nGo back to the fork, and this time go down the ramp toward the troll area.\r\n===The Troll Area===\r\nDescend the slope, clearing the few trolls there. Then start pulling the next room back to the slope. Pulling to the ramp is strongly recommended since the trolls are ranged and casters and all run when they get hurt.\r\nThe Witch Doctors cast Hex Frog, so have a priest or paladin ready to dispel if possible.\r\nOnce you feel you have pulled enough of the next room, move in. Straight ahead in the middle of opposite wall, a ramp leads up to [[Shadow Hunter Vosh'gajin]], an optional boss who drops the rogue set gloves and is the target of the Axecrafting quest.\r\n How to fight Vosh'gajin: Pulling each of the groups of guards down to the bottom of the ramp leading to their room is recommended, since they run and can easily add Vosh'gajin. Once the far guards are down, you'll take on Vosh and her two guards simultaneously. The difficult part of this fight is that Vosh casts an AoE Frog Hex, so you need to tank her far away from your groups priest or paladin. A bear druid is, of course, immune to polymorph and preferable as a tank to other classes in this encounter. If possible, control the two guards and focus on Vosh; if not, control a guard and kill the other first, then the first guard, then Vosh.\r\n It is useful to keep an emergency tank (e.g. hunter's pet, voidwalker or off tank) with the caster group to instantly grab aggro if the main tank gets polymorphed, especially if there is no option to quickly dispel the Hex on the main tank.\r\n In the back of the room is one of the two missing tablets from the quest \"The Final Tablets.\"\r\nGo back to the big room and start clearing down the slope to the middle platform.\r\n===To Bijou===\r\nThe large troll room has witchdoctors, seers, headhunters, and berserkers. There are multiple patrols that criss-cross the center of the room and go up and down the ramps, so be careful and take your time. The witch doctors have a \"Flame Buffet totem\" that does AoE fire damage, and should be killed quickly.\r\nWhen you reach the platform in the middle of the three slopes, go up the opposite slope, and clear a few more patrols to reach the NPC goblin Bijou. Whether or not you have the quest to find her, she will grant you the follow-up quest \"Bijou's Belongings.\"\r\nGo back down to the middle platform, and take the slope leading down, then pull to the right. Clear yourself a way to the door in front of you down the last slope. You'll pull through the archway into the small room, clear the small room after that, and will then be facing Voone.\r\n===Warmaster [[Voone]]===\r\nVoone is a straight-forward boss. He hits like a truck, especially by the end of the fight, so make sure your healers are ready and your tank has solid aggro.\r\nWhen he dies, Horde should check for \"Important Documents\" for the Warlord's Command quest. \r\nYou should also look for \"Bijou's Belongings\" which looks like a brown trunk. If it's not there, it will be further, in the Orc alley. Also, Warmaster Voone has a ~15% chance to drop the second Gem you need for the Upper Spire key, the Gem of Smolderthorn. Make sure everyone checks the corpse, as it may appear for any character. In his room you can also find the last tablet for the \"The Final Tablets.\"\r\nVoone drops the Hunter set gloves as well as a number of other unremarkable items.\r\n Alliance: As soon as you get Bijou's Belongings, I recommend you go back to Bijou immediately and get the followup quest, which will have you take a message to Marshall Maxwell at the outpost in Burning Steppes. Maxwell will give you the main quest for BRS, \"Maxwell's Mission,\" so it's even worth it to warp and run back. But you can wait to fight Mother Smolderweb before doing that, because you will need to warp back to the outpost if you want to complete the quest Mother's Milk as well.\r\nNow is the time to take your first big shortcut! Go back up all the way to the start of the troll area, past the big room full of trolls, until you are back at the first ramp, where you encountered the first trolls. The exact spot where you must jump down is located right next to the door connected to the big room. Be very careful before you jump: you must aim so you fall as close as possible to the corner right under you. If you jump too far or too much to the right, you will immediately aggro mobs. If you do though, keep your cool, deal with them, and be very careful to not let them run and aggro more.\r\n===The Orc Alley===\r\nAfter jumping down, ignore the Orcs on your right behind the rock. Start pulling from straight ahead of you. Your first two pulls should be patrols, a one-orc and a two-orc patrol.\r\nPulls are very tricky here, so do it with caution, as you can quickly get two camps at the same time. To avoid pulling two groups, it's advised you do long Line-of-Sight pulls to get all the casters to chase your puller to the end of the hallway to the area where you first jumped down. Firebrand Grunts are heavy-hitting melee types and the others are casters; fortunately there are no more warlocks. The Evokers do some mean damage, so typically you should kill them first. Watch out for a rare spawn, [[Bannok Grimaxe]] who can sometimes be found in Orc Alley. He is a melee type who hits harder than other orcs.\r\nBijou's Belongings can sometimes be found somewhere on the sides, all along the Orc Alley, so keep your eyes open for it a small brown trunk. Keep pulling and working your way through those orcs, until you reach the spider area.\r\n Note: The Orc Alley is where you land if you take the first shortcut described above in section two.\r\n===The Spiders===\r\nThis is the place everyone dreads, where many groups stop and give up. But with a bit of organization, the spiders aren't that hard.\r\nThe deal: The first pull of spiders will consist of two Elite Spire Spiders (don't even try to split them) and a bunch of mini-spiders, which are tough normal mobs. They hit really fast, which is bad when they start beating on casters.\r\nThe big spiders cast a long stun (about eight seconds), which can hit several targets at a time, so it's best to make sure not too many characters stand close to them at a time. And when you kill one of the big spiders, a bunch of other little spiders spawn.\r\nThe drill:\r\n* Make sure everyone is full mana before pulling.\r\n* Assign targets before pulling. Decide which of the two spiders the mage/druid will be controlling. If you haven't got either, assign who will be offtanking the 2nd spider. No matter who it is, this person must keep the second spider away from the rest of the fight.\r\n* The warrior will be tanking the first spider and as much of the little spiders as he can. (Spam some demoralizing shout; have Thorns or Imp Fire Shield on before you start)\r\n* Kill the little spiders first in the fashion you prefer, AoE them or use good Assist technique to kill them one by one. \r\n* Kill the first Spire Spider. When she dies, more little spiders will appear; kill them, just like you killed the other ones before.\r\n* Depending on the general mana situation of your healer, keep sheeping/sleeping the second big spider until enough mana is regenerated.\r\n* Go for the second spider; from now on it should be easy. The main difficulty is to control the pull and the first spiders.\r\nNote: Try to pull those spiders way down the ramp, on flat ground, to avoid evade bugs. Also note that the stun can be dispelled.\r\nIf you manage to be victorious, this means your group can probably go until the end of the instance. Congratulations. But don't cheer too fast though, there are many more spiders to kill. (I hear you cry)\r\nLoot the immature venom sacs and put them on a hotkey, you can right click them to remove the poison from Mother Smolderweb.\r\n===Mother Smolderweb===\r\nAfter the first pull of two spiders, you should be able to pull the spider named [[Mother Smolderweb]]. She acts much like a slightly tougher Spire Spider. She also splits into more little spiders when she dies. She can drop the Druid set boots.\r\nShe also casts the poison you need to keep on yourself if you want to finish the quest \"Mother's Milk\". If you do, after the spider dies, warp back to Kargath/Lakeshore and go to [[Flame Crest]] as fast as you can. (It's kinda annoying because the venom of the spider is actually casting net on you and immobilizing you every now and then). Then just run back to the Spire, take the first shortcut (as described above), run down Orc Alley, and you're back in action.\r\nContinue up the ramp, and pull the solo roaming spider. You can usually skip the two spiders in the \"pit\" on the left. Just run as close as you can on the right, at the edge of those ledges. Stop at the point where they cross, and pull the next two spiders there. Deal with them exactly as I described the first pull.\r\nThe last (and third) double-spider pull might have a rare spawn, \"[[Crystal Fang]],\" in it. Fang spawns twice the number of little spiders when killed. If Fang spawns, you have a chance at some interesting rare items, including half of the [[Spider's Kiss]] set.\r\nIf you go through all the spider pulls sucessfully, you will reach a platform, with ogres all over it. Oh, and if you feel up to killing a few extra spiders, you can click the eggs and try to finish \"En-Ay-Es-Tee-Why\". Open one egg at a time, as it can spawn spiders.\r\n===Urok Doomhowl's pad===\r\nOnce you have that pad full of ogres clear, you will find a pile of skulls in a corner. If you plant the Roughshod Pike and The Head of Highlord Omokk on it, a script will start.\r\n''Don't do that now'' though, there is a very high chance you will wipe on this script. It is the hardest battle in the whole dungeon, and it is optional. You can come back after you have killed the other \"easy\" bosses and do this script as last thing you do before leaving the instance. I will describe in the last paragraph how to deal with this script.\r\n===To [[Halycon]]===\r\nFrom the ogre pad, move on and pull a large group of non-elite scorpids. Tank them, and AoE them down. Another pull of those and wait for an orc patrol.\r\nGo up the stairs and wait for another patrol coming down from the other stairs. Turn right and pull the three orcs standing there against the wall. Left of those three orcs is the entrance to Halycon's Nest, so don't get too close until you are ready.\r\n Halycon's room contains a lot of [[Worg Pup]]s. If you want to complete \"[[Kibler's Exotic Pets]]\", you should target one of the pups and right-click the cage. If pulled carefully, you can probably get the bunch of pups without agroing Halycon herself.\r\nIn any case, pull Halycon and defeat her. The only hard thing in the fight is that when she dies, her mate comes to avenge her. [[Gizrul the Slavener]] is a bit tougher than Halycon, but it shouldn't be much of a problem. He comes immediately after the fight from the hallway ramp upon which you entered, so the casters at the back of your group should be ready to move.\r\nGizrul can drop several blue items, including the Druid set shoulders. \r\nBy killing Halycon, you complete \"[[The Pack Mistress]]\"/\"[[Put Her Down]]\".\r\n===To Wyrmthalak===\r\nWhen coming out of Halycon's nest, you have two options. You can go right and up the wide stairs to clear an optional NPC, [[Quartermaster Zigris]], who has some extra loot. Zigris always drops 5 Major Healing Potions and 5 Major Mana Potions, he sometimes has the plans for Annihilator, and in his room there is sometimes a chest. On the other hand, sometimes he has the potions, a few coins, and no other loot. So while optional, he's worth the time. Otherwise start pulling from the other door, up the stairs.\r\nPull a good chunk of the next room (a large room with cracks in the floor and wooden planks to cross them) before going up. Runners are the main killer here. Also, beware of the Evokers, which deal massive damage plus an AoE Knockback and stun. Control them first, and pull back to the hallway if you can. Also, there is usually a chest in this room, so keep an eye open for it.\r\nKeep pulling a path through this big room, until you can reach the opposite side and go through the door that leads you to the last area, and the last boss.\r\n===Overlord Wyrmthalak===\r\nKeep going right and up until you face Overlord Wyrmthalak.\r\n* Wyrmthalak hits fairly hard, has quite a lot of health, and an aggro-clearing knockback. The main tank must be ready to tank to re-acquire aggro. A good tactic is to pull him down from his high point to the area just below it. The warrior can get his back to the wall easily there, and traps and totems can be preset as well.\r\n* At some point in the fight, he will call for help. Two adds will come running to his aid from behind; you should be ready to sheep or seduce them if you can, or have a freezing trap down already. If you can't, kill them while your warrior tanks Wyrmthalak.\r\nWhen Wyrmthalak dies, don't forget to make everyone check the corpse for a possible Gem, and also check the floor for possible \"Important Documents\".\r\nThat's the end of the three mainbosses of Lower Blackrock Spire! That means you can farm them at will (they drop nice items), and also work on getting all three Gems for the key to Upper Blackrock Spire. Also, you may need to come back to complete pieces of your main quest.\r\nOverlord Wyrmthalak's loot list consists of six blue items, including the Hunter set shoulders, and, if you are lucky, a purple item.\r\n''But'' - there is one last thing you must face before going out of the instance, you have to save that stupid Trogg, Warosh, and get his mojo back! In short, you have to defeat a very hard script, and Urok Doomhowl.\r\n===Face Urok Doomhowl===\r\nGo back to the pad with the pile of skulls. You can take a shortcut by jumping down the first crack in the big room with the planks before Wyrmthalak. Move your group to the pad and brief them.\r\nWhen Omokk's head is placed on the pike in the pile of bones:\r\n* A bunch of Ogres starts to spawn, in waves of up to three. They are Elite, they hit hard, and they spawn fast. No five-man group could normally withstand so many elite mobs, but there is a trick to this encounter.\r\n* The pike you just planted in the skulls has a magical ability: it can nuke one ogre dead every 30 seconds. So you must have someone on duty, next to the pike, ready to click it everytime it's possible.\r\n* Organize your group well. Use sheep, succubus, and freeze traps to control them, assist one person, and take the ogres down as fast as you can. You should have previously cleared the whole area, so that means using fear in this encounter can be a lifesaver, rather than pulling in adds. Try to bring a full HP ogre next to the pike every 30 seconds and nuke it dead.\r\n* Also, the Urok Enforcers really hurt. They are easy to recognize because they use two-hand spiked maces, and hit really hard. Try to get those nuked down and killed fast, because they are the main threat.\r\nIf you stay alive long enough through those waves of ogres, Urok Doomhowl will appear. He will most likely appear as you already are overwhelmed by ogres. But do not panic! He can be sheeped, succubus seduced, or even kited, as he walks very slowly.\r\nSo, don't fight him until you've deal with the remaining other ogres. The nuke-pike disappears when Urok spawns too, to spice things up a little more.\r\nOnce only Urok is alive, fight him. He isn't that hard when he is alone. He hits reasonably hard and fears, but isn't that bad otherwise.\r\nUpon killing him, Warosh will appear next to you. Loot the Mojo from Urok, and complete the quest!\r\nUrok Doomhowl's loot table consists of three blue items, including the Shaman set boots.",},
			["Lower City"] = { content = "The '''Lower City''' is the gathering place for many of the refugees who fled from the war, including [[Arakkoa]], [[Sporelings]], and almost every other [[Outland]] race.\r\nIt also has a large number of useful NPCs and items.\r\n* [[Battlemaster]]s for all four Battlegrounds, and an [[Arena]] battlemaster, for both [[Horde]] and [[Alliance]].\r\n* A [[Mana Loom]], which allows tailors to create Bolt of Imbued Netherweave.\r\n* Grand Master trainers for nearly every profession, including [[Cooking]], [[Leatherworking]], and [[Alchemy]].\r\n* An [[Alchemy Lab]] next to the Alchemy trainer, who also gives the [[Quest: Master of Elixirs]] specialization quest for alchemists. Warlocks should note that this lab CANNOT be used instead of the one in [[Scholomance]] for the [[Dreadsteed]] quest.\r\n* Three tailors who allow you learn [[tailoring]] specializations, and buy new [[epic]] tailoring recipes for armor sets and special bags [including 20 slot bags]. Each of these armor sets is [[bind on pickup]] however, and thus is only usable by the person crafting them.\r\n** [[Spellfire Tailoring]] — Patterns for the [[Wrath of Spellfire]] set\r\n** [[Primal Mooncloth Tailoring]] — Patterns for the [[Primal Mooncloth]] set \r\n** [[Frozen Shadoweave Tailoring]] — Patterns for the [[Shadow's Embrace]] set\r\n===Until Honored===\r\nPlayers aiming for faction higher than Honored should wait until honored to complete lower city quests. Run [[Auchenai Crypts]] and [[Sethekk Halls]], and complete the repeatable quest More Feathers. This quest rewards random common, uncommon and/or rare items in addition to rep.\r\n ''If no instance runs are done it will take to get from zero to Honored''\r\n===Through Exalted===\r\nRun [[Shadow Labyrinth]] and Heroic Mode [[Auchindoun]] (except [[Mana Tombs]], which gives [[Consortium]] rep) and complete all available quests.\r\n==Rewards==\r\nFaction items sold by [[Nakodu]], located at the Lower City market :\r\n===General===\r\nNote: Quest chains are listed under the sub-zone they start in.\r\n====[[Daily Quests (Heroic Instances)]] (1400 Rep)====\r\n*Wanted: Shaffar's Wondrous Pendant (+350 reputation) [[Wind Trader Zhareem]] ([[Lower City]])\r\n*Wanted: The Headfeathers of Ikiss (+350 reputation) [[Wind Trader Zhareem]] ([[Lower City]])\r\n*Wanted: The Exarch's Soul Gem (+350 reputation) [[Wind Trader Zhareem]] ([[Lower City]])\r\n*Wanted: Murmur's Whisper (+350 reputation) [[Wind Trader Zhareem]] ([[Lower City]])\r\n====[[Shattrath City]] (500 Rep)====\r\n*The Outcast's Plight (+250 reputation) [[Vekax]] ([[Shattrath City]] ~48,18)\r\n**More Feathers (+250 reputation) (Repeatable until Honored)\r\n====[[Allerian Stronghold]]/[[Stonebreaker Hold]] (2825 Rep)====\r\n*Secrets of the Arakkoa (+75 reputation) [[Lady Dena Kennedy]] ([[Terokkar Forest]] 58,56)\r\nSurrender to the Horde (+75 reputation) [[Rokag]] ([[Terokkar Forest]] 49,45)\r\n**The Eyes of Skettis (+250 reputation) (Prereq: Speak with Rilak the Redeemed) [[Kirrik the Awakened]] ([[Terokkar Forest]] 37,51)\r\n**Seek Out Kirrik (+25 reputation)\r\n**Veil Skith: Darkstone of Terokk (+250 reputation)\r\n**Veil Rhaze: Unliving Evil (+250 reputation)\r\n**Veil Lithic: Preemptive Strike (+250 reputation)\r\n***Veil Shalas: Signal Fires (+250 reputation)\r\n***Return to Shattrath (+150 reputation)\r\n***The Skettis Offensive (+500 reputation)\r\n**Missing Friends (+250 reputation) [[Ethan]] ([[Terokkar Forest]] 37,51)\r\n**The Tomb of Lights (+250 reputation) [[High Priest Orglum]] ([[Terokkar Forest]] 37,51)\r\n**Recover the Bones (+250 reputation) [[Soolaveen]] ([[Terokkar Forest]] 37,49)\r\n***Helping the Lost Find Their Way (+250 reputation)\r\n====[[Veil Shalas]] (350 Rep)====\r\n*Skywing (+350 reputation) [[Skywing]] ([[Terokkar Forest]] ~57,70)\r\n====[[Refugee Caravan]] (1175 Rep)====\r\n*Before Darkness Falls (+250 reputation) [[Mekeda]] ([[Terokkar Forest]] 37,51)\r\n*Cabal Orders (+75 reputation) [[Cabal Orders]] (Drop from mobs for the previous quest: Before Darkness Falls)\r\n**The Shadow Tomb (+350 reputation) \r\n*Escaping the Tomb (+250 reputation) [[Akuno]] ([[Terokkar Forest]] ~31,52)\r\n*The Vengeful Harbinger (+250 reputation) [[High Priest Orglum]] ([[Terokkar Forest]] 37,51)\r\n====[[Sha'tari Base Camp]] (1600 Rep)====\r\n*An Improper Burial (+250 reputation) [[Commander Ra'vaj]] ([[Terokkar Forest]] 31,76)\r\n**A Hero Is Needed (+250 reputation)\r\n**The Fallen Exarch (+250 reputation)\r\n*Digging Through Bones (+250 reputation) [[Chief Archaeologist Letoll]] ([[Terokkar Forest]] ~31,74)\r\n**Fumping (+250 reputation)\r\n**The Big Bone Worm (+350 reputation)\r\n====[[Auchindoun]] (1950 rep)====\r\n*Brother Against Brother (+350 reputation) (Optional Prereq: Can't Stay Away) [[Isfar]] ([[Terokkar Forest]] 44,65)\r\n*Find Spy To'gun (+250 reputation) [[Spy Grik'tha]] ([[Terokkar Forest]] 40,72)\r\n**The Soul Devices (+350 reputation)\r\n*Trouble at Auchindoun (+150 reputation) [[Spymistress Mehlisah Highcrown]] ([[Shattrath City]] 51,45)\r\n**The Codex of Blood (+350 reputation)\r\n**Into the Heart of the Labyrinth (+500 reputation)\r\nTotal Rep: 8225 (+250 per completion of More Feathers)\r\n===Profession-Specific===\r\n*Becoming a Mooncloth Tailor (+150 reputation)\r\n*Becoming a Shadoweave Tailor (+150 reputation)\r\n*Becoming a Spellfire Tailor (+150 reputation)\r\n*Master of Elixirs (+250 reputation)\r\n===Children's Week-Special===\r\n*Children's Week (+10 reputation) [[Orphan Matron Mercy]] ([[Shattrath City]] 74,48)",},
			["Lower city (Stormwind)"] = { content = "The '''lower city''' was a portion of [[Stormwind City]] during the [[First War]]. It was afire from the [[orc]]s' attacks and [[bucket brigade]]s were ordered to get [[water]] from the public baths to fight it.",},
			["Lower Karazhan"] = { content = "When [[Karazhan]] was first announced, there were rumors that an upside-down version of the tower existed, extending down from the bottom floor, deep underground. Whether or not Blizzard actually plans to implement this 'Lower Karazhan' remains unknown. \r\nIt is likely that this is a reference to [[The Last Guardian]] by Jeff Grubb, a novel which details the last weeks of (living) activity within the tower. Several references are made to an \"inverse\" of Karazhan which begins at the lowest level and works its way downward, with Medivh's secret chambers lying at the very bottom. There exists a building behind the nearby graveyard in which there is a stair downward towards a locked gate. One could (and may still be able to) go through this gate as a ghost and explore the large area beyond. This is likely to play a part in Karazhan's future in [[World of Warcraft]], if there is any.\r\nKarazhan's basement could possibly be added in [[Wrath of the Lich King]] as an instance related to the [[Black Riders]]. \r\nThere is also a door outside the Kitchen, in the area above the Stables. The door is locked and cannot be opened by any means. Looking into this room in a Map Viewer shows that it is an empty triangular room, about 10 yards in size. This also could be part of an extention to Karazhan.\r\nDuring the Hallow's End seasonal event, this room appears to be occupied by Prince Tenris Mirkblood (\r\nAccording to a Blue post by Tigole (",},
			["Lower rise"] = { content = "The '''Lower Rise''' is [[Thunder Bluff]]'s main hub of trade, and also contains some professional trainers, as well as several points of interest, such as the [[inn]], the [[bank]], the [[auction house]], and a [[mailbox]]. It connects to the [[middle rise]] and [[high rise]] through the [[wind rider]] roost and paths along the edges of the mesa, and to [[Hunter Rise]] and [[Spirit Rise]] by separate rope bridges. A pair of hydraulic lifts enable the [[tauren]] to access the plains of [[Mulgore]] below.",},
			["Lower Veil Shil'ak"] = { content = "'''Lower Veil Shil'ak''' one of the four veils that make up the [[arakkoa]] capital of [[Skettis]] in southeastern [[Terokkar Forest]].",},
			["Lower Wilds"] = { content = "A eastern part of Feralas infested by [[Ironfur Bear]] and Longtooth Runner.",},
			["Low Common"] = { content = "Low Common is a language used by many races. Low Common is not to be confused with ''broken Common'' which is different. \r\nSome of the most famous low common phrases include the battle cries of [[kobold]]s, \"You no take candle!\", and [[ogre]]s: \"Me smash! You die!\"\r\nIts also used by many of the troll tribes of the world that descended so far into barbarism that have forgotten the [[Zandali]] language.\r\nThere are likely separate dialects of Low Common based on a races culture.\r\n'''Note: The use of Low Common does not have to mean that those who speak it are less intelligent than others.'''",},
			["Low Path"] = { content = "'''The Low Path''' is the road leading down towards [[Terokkar Forest]] in southeastern [[Nagrand]].",},
			["Loyalty"] = { content = "With Patch Version 3.02, hunter pet loyalty has been completely removed. \r\nHappiness, however remained. All pets start out with an amount of skill points, which depends on the level of the pet, not loyalty and level as before.",},
			["Lucan Cordell"] = { content = "'''Lucan Cordell''' is a level 35 [[artisan]] [[enchanting trainer]] located in [[the Canals]] (Mage Quarter section) in the [[human]] city of [[Stormwind]].\r\nSee [[List of Stormwind NPCs]].",},
			["Lucifron"] = { content = "Among the ranks of the [[flamewaker]]s, overseers and their guards constantly jockey for higher status among the hierarchy of elementals in hopes of gaining favor with [[Ragnaros]]. '''Lucifron''' is no exception. He has clashed with [[Gehennas]] on several occasions, particularly during their incarceration within the [[Elemental Plane]]. This rivalry has now extended to the [[Molten Core]] where Lucifron quietly waits for his opportunity to capitalize on any weakness shown by the other flamewakers.\r\nLucifron, and his two [[Flamewaker Protector]] guards, can be found watching over the enormous core hound [[Magmadar]], favored pet of [[Ragnaros]].\r\n===Lucifron===\r\n*[[Impending Doom]]\r\nInflicts 2000 Shadow damage to nearby enemies after 10 sec.\r\nDispel Type: Magic\r\nSchool: Shadow\r\nRadius: 40 yards\r\n*[[Lucifron's Curse]]\r\nCurses nearby enemies, increasing the costs of their spells and abilities by 100% for 5 min. This cost increase applies to all spells and abilities, whether they cost mana, rage, or energy.\r\nDispel Type: [[Curse]]\r\nSchool: Shadow\r\nRadius: 40 yards\r\n*Shadow Shock\r\nInstantly lashes nearby enemies with dark magic, inflicting Shadow damage.\r\nSchool: Shadow\r\nRadius: 20 yards\r\n===Flamewaker Protectors===\r\nApproximately 90,000 HP.\r\n*[[Cleave]]\r\nInflicts normal damage to an enemy and its nearest allies, affecting up to 5 targets.\r\nSchool: Physical\r\n*Dominate Mind\r\nTakes control of a humanoid enemy for 15 sec.\r\nDispel Type: Magic\r\nSchool: Shadow\r\n*NOTE: It is believed that if you pull the Flamewakers from Line-of-Sight of Lucifron, there will be no mind-control. Blizzard designed the battle area with this in mind, **hint: notice the small dug cave in the room.*\r\n==Strategies==\r\nIn most cases, raids will first dispatch the first [[Core Hound Pack]] to give some room for the pullers and the main tank. It is important when Lucifron is pulled that he not come near the main raid group or there could be an instantaneous wipe. His guards have the ability to mind control, so it is sometimes easier to have one or two dummies move ahead of the main tank to suck up the mind control. Additionally, no one can move near the tunnel to the west, or the imps and surgers inside could chain aggro and wipe the raid.\r\nGenerally, two hunters will use one of their insta-cast shots to pull the Flamewalker Protectors, while the Main Tank must run up, tag, and pull Lucifron in the opposite direction of his guards. Generally the back cove is where the guards are pulled, while Lucifron is taken to another alcove on the east, far from the main raid. Each of the guards must then be picked up by two offtanks and dispatched accordingly before Lucifron is targeted.\r\nMages will not be contributing any large part of the DPS in this fight as they will be tied up with removing the curse that Lucifron casts on the raid every 15 seconds. Priests (and Paladins if Alliance) will also be tied up dispelling the Impending Doom debuff from healers, and especially the main tanks, and whoever becomes mind controlled. The core DPS for this fight therefore falls upon the rogues, hunters, and warlocks.\r\nOnce the two guards are defeated, all DPS will shift over to Lucifron. Usually around 20-25%, it is safe for some of the mages to begin casting their nukes, depending on their mana and how quickly they decurse the raid.\r\nLucifron's debuffs have a range of 40 yards. It is possible for every healer (except the MT-decurser), and properly spec'ed hunters to stay out of Lucifron's curse-range, so with a good group you can minimize every curse-wave to about 10 raid members (melees). This makes the fight much easier and allows the mages to do damage too. You can also choose to keep only necessary players within the radius (healers, decursers, dispellers, tanks), and hold back the DPS players out of the range until Luci's mana is depleted. It takes a few minutes, but it saves the trouble of nearly wiping when the entire raid is bing hit by the curses and magic effects. Its good to note that any ranged DPS that can attack at 41 yards through talents can exceed Luci's range and still DPS him down. They just have to be at their maximum range.\r\nIf Lucifron is not defeated before the group wipes, the guards will respawn.\r\n==Quests==\r\n*Hands of the Enemy\r\n==Reward==\r\nLucifron drops [[Tranquilizing Shot|Tome of Tranquilizing Shot]], which is necessary for hunters to learn in order to combat [[Magmadar]]. In addition he will drop two epic items, which may include one of the [[Tier 1]] epic boots or gloves for some sets.\r\nYou receive 100 Reputation with the [[Hydraxian Waterlords]] at all reputation levels before exalted.\r\n==Notes==\r\n* Lucifron's name is probably a reference to Lucifer, Satan's angel name before he was cast down into hell.\r\n* See other Molten Core [[Molten_Core|Bosses]].",},
			["Luck Be With You"] = { content = "This quest leads to the Cache of Mau'ari. The Cache allows you to gather [[E'ko]], which is turned in to [[Witch Doctor Mau'ari]] for various buffs.\r\n==Objectives==\r\nCollect 4 [[Frostmaul Shards]] for [[Witch Doctor Mau'ari]] in [[Everlook]].\r\n*Frostmaul Shards (4)\r\n==Description==\r\nAh, I can tell just by lookin' at ya -- you be wantin' to make a lucky charm. Mau'ari always knows!\r\nTo da south. you'll find a canyon, an' giants made a' solid ice. The giants sometimes be carryin' dem, but ya can always gather da shards yerself from da canyon. These shards have a powerful reflective quality.\r\nBring back 10 frostmaul shards, and my lucky charm will be yours.\r\n==Progress==\r\nBring back da shards, and I be tellin' you more!\r\n==Completion==\r\nAhh, yes... I will make da charm for ya now. Just you wait!\r\n==Reward==\r\n*You will receive: 90 silver \r\n==Gains==\r\n* 9550 [[XP]]\r\n==Notes==\r\nFollow the road south out from Everlook. Eventually you go over a bridge.\r\nThe elite 59/60 giants around and under the bridge drop the crystals. Also, though, there are crystals standing around for the taking, both in the canyon and on the lip around it. If you can fear the nearby giants, or they simply wander far enough away, you can loot the crystals without fighting the giants.\r\nThe entrance to the canyon is to the west. (Coords: 59,62)\r\nEven though the quest description tells you to get ten shards, you only need four. Before [[Patch 2.3.0]], ten shards were required, obviously Blizzard changed the quest objective but forgot to change the description.\r\nAs of 2.3.4 the quest text reads correctly that you need 4 shards instead of 10.\r\n==Quest progression==\r\n# Luck Be With You\r\n# Cache of Mau'ari",},
			["Luffa"] = { content = "'''Luffa''' is a trinket that can remove a [[bleed]] effect.\r\n==Source==\r\nLuffa is a quest reward from the quest [[Quest:Incendosaurs Whateverosaur is More Like It|Incendosaurs? Whateverosaur is More Like It]].\r\n==Notes==\r\nPrior to [[The Burning Crusade]], this item was not considered to be very valuable, however its ability to dispel some bleed effects in the new end-game instances (e.g., [[Moroes]]'s garrotte) made it very desirable. Unfortunately, Patch 2.0.10 made Luffa unable to dispel bleed effects above level 60, leaving little reason to save it, after entering [[Outland]]",},
			["Lui'Mala"] = { content = "'''Lui'Mala''' is a level 30 [[fishing trainer]] located in [[Shadowprey Village]] in the [[contested]] territory of [[Desolace]].\r\nSee [[List of Desolace NPCs]].",},
			["Lukou"] = { content = "'''Lukou''' is the Loa of healing and respite, and she grants the ability to heal allies. With a word, the shadow hunter invokes healing with a wave of soothing light or can invoke a scintillating rain of positive energy, which drops from the sky to heal all living allies it touches. Her power has no effect against undead in the area- Lukou grants the capacity to heal, but she has no power over the restless dead.",},
			["Luma Skymother"] = { content = "'''Luma Skymother''' is a [[tauren]] [[quest giver]] located in the [[Slave Pens]] of [[Coilfang Reservoir]]. She is located 5 pulls in, at the end of the first tunnel, near some Earthen Ring Flamecaller.\r\nShe is involved in the following quests:\r\n*Ahune is Here!\r\n*Summon Ahune\r\nSee [[Coilfang Reservoir NPCs]].",},
			["Lumber mill"] = { content = "'''Lumber Mills''' are structures used by several races to process wood into useable lumber.\r\n===Human Lumber Mills===\r\nDuring the first war, this is where the raw wood supplied by peasant harvesters is made into building supplies, arrows, and catapults. The ability to craft wood to the specific shapes and sizes needed to make certain buildings makes them an essential part of your community. The Mill can also provide your Archers with better shafts for their arrows that will make them fly truer, and increase the amount of damage that they inflict.\r\nDuring the third war, the master masons of the human lumber mills strive constantly to improve\r\nstructural integrity. The site is also a processing mill for lumber harvested from\r\nthe surrounding landscape. The wood harvested is used in everything from raw\r\nbuilding materials to weapon handles.\r\n===Elven Lumber Mills===\r\nDuring the second war, seeking insight into the mysteries of the great [[Ironwood tree]]s of [[Northeron]], the Elves of Quel’thalas constructed Lumber Mills where they became exceptional craftsmen. The Elves offered their superior skills in service to the Alliance, providing more efficient means for processing lumber. The production of ships and war machines becomes possible with the addition of these structures. Lumber mills are also responsible for producing the perfectly crafted arrows that make the Elven Archers feared throughout the Horde. When given the necessary resources, Elven\r\ncraftsmen will upgrade the quality of these arrows, thus increasing the possible damage that can be inflicted. Elven Rangers, after being trained at the Barracks, have been known to gather at the mills, honing their skills in Longbow, Marksmanship and Scouting.\r\n'''Lumber Mills''' run by the [[High Elf|High Elves]] helped fend off Arthas as he tried to attack their capital [[Silvermoon]] and [[Quel'thalas]] in Warcraft III by serving as a returning point for lumber. The [[Blood Elf|Blood Elves]] use a similar lumber mill in the Frozen Throne Expansion Campaign in Warcraft III. It cannot be built by the \"[[High Elf Worker|High Elf (Worker)]]\" probably due to the limited ability of the map editor prior to the Frozen Throne Expansion. With the Frozen Throne Expansion map editor, it is possible to make additional groups with building orders.\r\n===Blood Elven Lumber Mill===\r\nThe '''Lumber Mill''' helped the [[Blood Elf|Blood Elves]] and [[Kael'thas]] in Warcraft III Frozen Throne Human Expansion Campaign.\r\n<gallery>\r\nImage:Warcraft Orcs and Humans - Lumber Mill.jpg|Human Lumber Mill from the First War\r\nImage:Lumber Mill.jpg|Human Lumber Mill from the Third War\r\nImage:HumanLumbermill.gif|High Elven Lumber Mill from the Second War\r\nImage:HighBloodElfLumberMill.jpg|High Elven/Blood Elven Lumber Mill from the Third War\r\n==World of Warcraft Lumbermills==\r\nLumber Mills can be found all over World of Warcraft either abandoned or run by various factions.\r\n===Statistics in Warcraft III(High Elves)===\r\n* 900 HP\r\n* 5 fortified armor\r\n* returning point for lumber\r\n===Statistics in Warcraft III(Blood Elves)===\r\n* 900 HP\r\n* 5 fortified armor\r\n* upgrades building armor and amount of lumber [[Blood Elf Worker|workers]] carry.",},
			["Lumber Mill (Arathi Basin)"] = { content = "The '''Lumber Mill''', or '''LM''' for short, is a [[resource node]] in [[Arathi Basin]].",},
			["Luminous Flame Spessarite"] = { content = "#REDIRECT [[Reckless Flame Spessarite]]", redirect = "Reckless Flame Spessarite",},
			["Luminous Noble Topaz"] = { content = "'''Luminous Noble Topaz''' is a cut gem that matches Red Sockets and Yellow Sockets.\r\n==Source==\r\nThis [[gem]] is crafted by [[Jewelcrafter]]s with a skill of 350 or greater.\r\nIt requires a [[Simple Grinder]].\r\nTaught by [[Design: Luminous Noble Topaz]].\r\nComponents:\r\n*1 [[Noble Topaz]]\r\nThe [[Design: Luminous Noble Topaz|design]] for this gem is a random lvl 65+ world drop",},
			["Luminrath's Mantle"] = { content = "'''Luminrath's Mantle''' starts the quest Conjurer Luminrath.\r\n==Source==\r\nThis item drops from [[Conjurer Luminrath]] at [[Kirin'Var Village]] in [[Netherstorm]].",},
			["Lunaclaw"] = { content = "'''Lunaclaw''' is a level 12 [[named]] [[moonkin]] that can be summoned using [[Cenarion Moondust]] in either [[Darkshore]] or [[The Barrens]].\r\n[[Night Elf]] [[druid]]s can summon Lunaclaw at the Moonkin Stone in the [[Moonkin Caves]], directly east of [[Auberdine]] in Darkshore. [[Tauren]] druids can summon Lunaclaw at the Moonkin Stone west of [[Camp Taurajo]] in The Barrens.\r\nWhen Lunaclaw is defeated, the druid can learn [[bear form]] from the [[Lunaclaw Spirit]].\r\n==Attacks and abilities==\r\n*'''[[Thrash]]''': [[School|Physical]]. Gives the caster 2 extra attacks.\r\n==Quests==\r\n*Body and Heart (Alliance) ''(Druid Quest)''\r\n*Body and Heart (Horde) ''(Druid Quest)''",},
			["Lunar Festival"] = { content = "The '''Lunar Festival''' is a time of celebration. The people of [[Azeroth]] celebrate their triumph of many thousands of years ago, when an alliance of good races (the [[Night Elves]], [[Tauren]], [[Furbolg]]s and [[Earthen]], though all other races were probably involved at the time) defeated a terrible evil, the [[Burning Legion]]. It is also a time of remembrance for the valor and wisdom of that ancient age.\r\nToday, the Lunar Festival is held by the [[Druid]]s of [[Nighthaven]]. Both the [[Horde]] and [[Alliance]] are welcomed to celebrate and shoot fireworks - a symbol of [[Elune]]'s power. Ancient heroes of the past also appear throughout the land, offering gifts to those who find and honor them.\r\nIt is a time of happiness, fortune and celebration, but it has a deeper motive as well.\r\n[[Omen (boss)|Omen]], defeated so many centuries ago, yet remains in [[Lake Elune'ara]]. Although driven insane by the Burning Legion, the [[demigod]] still possesses Elune's blessing and thus is immortal. During the Lunar Festival, he stirs... and heroes of the land are called to defeat him once again.\r\n==Details==\r\nDecorations are placed in every capital as well as in the regions of Nighthaven and Moonglade. Revellers celebrating the Lunar New Year will be spread throughout the world (the revellers are concentrated in Moonglade, except for those that show up for the fireworks shows in Stormwind/Thunder Bluff/Booty Bay); the lunar festival specific NPCs can be found in each capital and in Moonglade. There are also other NPCs - spread throughout the world - that are ghost-like elders who players must find and honor, as noted below.\r\nLunar Festival events focus on the celebration of the inhabitants of Azeroth's ancestors. Quests can be found throughout the world offering holiday-related items such as fireworks and other memorabilia to celebrate one's elders and ancestors. Elder Ghosts are found throughout the world of Azeroth and each time players finds a new Elder, they receive a token that can be redeemed for special holiday-related items.\r\n===Dates===\r\nIt appears that Blizzard moves the dates of this event to conform to the real-life Chinese Lunar New Year on which this festival is based.\r\n*For 2006 &ndash; The Lunar New Year is on January 29th; the Lunar Festival was held January 27th to February 14th.\r\n*For 2007 &ndash; The Lunar New Year is on February 18th; the Lunar Festival was held February 16th to March 8th.\r\n*For 2008 &ndash; The Lunar New Year is on February 7th; the Lunar Festival is scheduled for February 5th to February 23rd.\r\n===Mini-events===\r\n* On the date of the actual lunar New Year, celebrations occur in Stormwind, Thunder Bluff, Booty Bay and Moonglade. \r\n* On the last day of the festival, one last firework show will be held in Moonglade. This parallels the Chinese \"Festival of Lanterns,\" with extra lanterns spawned around Lake Elune'ara (the firework show occurs over the lake). \r\n===Items===\r\nSome holiday items that reminiscent players of the Chinese New Year include:\r\n* Various rockets and fireworks\r\n* Festival dumplings\r\n* Costumes that depict festive Lunar holiday dresses and suits in a variety of colors besides red\r\n* Recipes that will allow players to create red Lunar holiday clothing\r\n* A special red lockbox with a surprise inside (Inspired by the [[wikipedia:red packet|red packets]] that is given during Chinese New Year)\r\n===Outdoor Raid===\r\nFinally, there is [[Omen (boss)|Omen]], a high-level boss that spawns in Moonglade during the festival, giving players a chance to experience a raid-style encounter that only appears during this time of year. Omen is inspired by the tale of \"[[wikipedia:Nian|Nian]]\" from Chinese lore. In the Chinese version of WoW, Omen's name will be left as Nian.\r\n==Quests==\r\nSimple quests exist at each major city that provides a 24-hour invitation that allows the bearer to teleport to Moonglade from inside a nearby circle of moonlight. Once in Moonglade, one hill contains a number of similar circles of moonlight, each of which teleports you back (using the invitation) to one of the cities. Though the invitation has a 10-minute cooldown, this provides a convenient way to move from city to city for the duration of the festival (see the [[Travel Guide]]). In addition, this provides a flight point to Moonglade, usually reserved to Druids and high-level characters.\r\nEven if you completed these quests (including the veneration of the elders quests) in a previous year, they will once again be available to you this year (2008).\r\n===Lead-in quests===\r\n* \"The Lunar Festival\", from the [[Lunar Festival Herald|heralds]] or [[Lunar Festival Emissary|emissaries]] in the cities, direct you to your city's harbinger. Reward: 5 [[Cenarion Circle]] reputation.\r\n** The Lunar Festival (Orgrimmar)\r\n** The Lunar Festival (Thunder Bluff)\r\n** The Lunar Festival (Undercity)\r\n** The Lunar Festival (Stormwind)\r\n** The Lunar Festival (Ironforge)\r\n** The Lunar Festival (Darnassus)\r\n* Lunar Fireworks, from the [[Lunar Festival Harbinger|harbinger]] in your city, directs you to set off 8 small and 2 cluster fireworks (purchasable from the nearby vendor, or made by an engineer), and rewards you with 150 [[Cenarion Circle]] reputation, and a Lunar Festival Invitation allowing you to teleport to Moonglade.\r\n* \"Valadar Starsong\" directs you to teleport to [[Moonglade]] and speak with Valadar in the village of Nighthaven. Reward: 1250 experience (or 75 silver at max level).\r\n** Valadar Starsong\r\n===Gaining Coins of Ancestry===\r\nYou don't need a prerequisite for these. Just find the Elder, talk to them, and the quest is complete. There are 50 elders: 26 in Kalimdor and 24 in Eastern Kingdoms. The Elders stand in circles of light, and give you tips as to where to find the other nearby Elders. You can complete the quest with any Elder, though some are harder to get to than others, such as those in your opposing faction's capital cities.\r\nAll of these quests give 1 Coin of Ancestry and 75 (changed from 50) of your faction's reputation. (No Cenarion reputation). This means +75 to each of your faction's five cities. If you finished these quests in 2006 you weren't able to repeat them in 2007, but as of 2008 you can complete the quests for Elders you finished in previous years (in other words, the 2008 festival ignores which ones you completed in previous festivals).\r\nAbout 8 hours after completing one of these quests, the Elder whom you met mails you a Lucky Red Envelope, which may contain an Elder's Moonstone (summons a circle of light, same as Elune Stone) or a Lucky Rocket Cluster, which gives you and anyone near you a +250 health buff for 30 minutes, when thrown into a Cluster Launcher.\r\nA complete list of all the Elder locations including coordinates can be found on the [[Elders]] page.\r\nThere is no special reward for obtaining all 50 coins.\r\nThe coins don't have a limited duration, so if you can't collect enough one year save them up for the next festival.\r\n===Other quests===\r\n* Elune's Blessing from Valadar Starsong - Summon [[Omen (boss)]], defeat him and gain his blessing. The blessing itself is a buff giving +10% to all stats for one hour. Rewards: Elune's Lantern, 3 solid stone and a box of fireworks (100 [[Cenarion Circle]] reputation).\r\n===Repeatable turn-in quests===\r\nYou may turn in coins to purchase various items. These quests do not give reputation.\r\n====[[Valadar Starsong]]====\r\nNo level requirement.\r\n* Festive Lunar Dresses: Turn in 5 coins of ancestry for a choice of three dresses, and a box of fireworks\r\n* Festive Lunar Pant Suits: Turn in 5 coins of ancestry for a choice of three pant suits, and a box of fireworks\r\n* Festive Dumplings: Turn in 1 coin of ancestry for a stack of 8 dumplings, each of which restores 4% health and mana per second for 25 seconds\r\n* Elune's Candle: Turn in 5 coins of ancestry for Elune's Candle which has 88 charges that shoot fireworks at your target. These may be shot at the minions of Omen to freeze them, and does damage to Omen. On players and other NPCs, it produces a fireworks effect. This quest is not repeatable, although you may purchase additional candles for 10 silver each (they are unique, so you can only carry one at a time).\r\n====Fariel Starsong====\r\nLevel Required\r\nLevel 25 \r\n* Small Rockets: Turn in 5 coins of ancestry for (Package of 3 small rocket recipes)\r\nLevel 35 \r\n* Large Rockets: Turn in 5 coins of ancestry for (Package of Large rocket recipes) \r\nLevel 45 \r\n* Cluster Rockets: Turn in 5 coins of ancestry for (Package of 3 rocket cluster recipes)\r\n* Firework Launcher: Turn in 5 coins of ancestry for Schematic: Firework Launcher\r\nLevel 50 \r\n* Festive Recipe Turn in 5 coins of ancestry for Pattern: Festival Dress or Pattern: Festival Suit\r\nLevel 55 \r\n* Large Cluster Rockets: Turn in 5 coins of ancestry for (Package of 3 Large Cluster Rocket Recipes)\r\n* Cluster Launcher: Turn in 5 coins of ancestry for Schematic: Cluster Launcher\r\n===Lunar Festival===\r\nEvery year the druids of Moonglade hold a celebration of their city's great triumph over an ancient evil. During the Lunar Festival, citizens of Azeroth have the opportunity to honor their elders by celebrating their sage wisdom, sharing in magnificent feasts, and of course... shooting fireworks!\r\n===Features===\r\n'''Type:''' Holiday Event\r\n'''Date:''' February 5 - 23\r\n'''Location:''' Stormwind, Thunderbluff, Booty Bay, Moonglade\r\n====[[Omen]]====\r\nThe beast of Omen was once a hero of this world. A wolf of great strength and fortune, Omen fought beside the heroes of the War of the Ancients until he succumbed to demonic magics. Turning against his allies, he raged across Azeroth and carried death and terror in his wake. Finally defeated in Moonglade, Omen now sleeps among the silt of Lake Elune'ara. But each new year, during the festival, he stirs...<br clear=\"right\" />\r\n====[[Elders]]====\r\nDuring the Lunar Festival, adventurers will have the opportunity to honor many of their elders, and by doing so, they will also honor their culture and their people. For this, the [[Coins of Ancestry]] serve as a tangible means to recognize those who have chosen the venerable path of respect. Those who are recognized thus will have their diligence rewarded with a selection of unique items.<br clear=\"right\" />\r\n====[[Fireworks]]====\r\nThe innovative and artistic engineers of Undermine have been slaving away since their display of pyrotechnics in July. Their latest and greatest -- not to mention highly dangerous to operate -- creations will be on display in the cities of the world every hour after sunset. Keep your eyes to the skies, and be sure to stick around for the finale!<br clear=\"right\" />\r\n====Revelers, All====\r\nMany soldiers formerly abroad have come home to engage in the festivities. Share in the merriment and dance with the revelers, or, if you're so inclined, blow a kiss to one that catches your eye. It's all in fun, after all; they appreciate the attention!\r\nFestival Outfits To help celebrate the festivities, a selection of unique clothing become available to adventurers. Such outfits have been worn in times past during the Lunar Festival and each is hand-crafted with only the finest soft fabrics and other quality components.\r\n<center>\r\n</center>\r\n===History===\r\n''The Lunar Festival is a time of celebration. The peoples of Azeroth celebrate their triumph of many thousands of years ago, when an alliance of good races (Night Elves, Tauren, and Earthen - a proto-dwarven race) defeated a terrible evil. It is also a time of remembrance for the valor and wisdom of that ancient age.''\r\n''The demi-god Omen was a being of great strength and knowledge. Blessed by Elune, Omen wandered primordial Kalimdor, guiding hunters and gatherers and offering luck and advice to all he met. When the Burning Legion launched their attack, Omen allied with Azeroth's defenders. He fought bravely but after many battles his wounds from demonic forces plunged Omen into a deep, dreaming sleep... where fel-inspired nightmares slowly consumed him. When he finally awoke, centuries later, he had fallen to madness.''\r\n''The transformed Omen rampaged. No longer a creature of wisdom - but still possessing the strength of Elune's blessing - he tore through the land, killing and devouring. Terror rode before him, and death trailed in his wake.''\r\n''Omen's spree of horror ended when a coterie of ancient heroes gathered in the village of Nighthaven and faced the beast. They called down the moon's wrath and Omen, blinded and stunned by the power of the moon goddess, fled into the deep waters of Lake Elune'ara. That day marked the end of his rampage, and symbolized a new beginning for the people of Azeroth and the followers of Elune.''\r\n''Today, the Lunar Festival is held by the druids of Nighthaven. Both the Horde and Alliance are welcomed to celebrate and shoot fireworks - a symbol of Elune's power. Ancient heroes of the past also appear throughout the land, offering gifts to those who find and honor them.''\r\n''It is a time of happiness and fortune and celebration, but it has a deeper motive as well...''\r\n''Omen, defeated so many centuries ago, yet remains in Lake Elune'ara. Although driven insane by the Burning Legion, the demi-god still possesses Elune's blessing and is, hence, immortal. During the Lunar Festival, he stirs... and heroes of the land are called to defeat him once again.''\r\n \r\n==Screenshots==\r\n<center>\r\n<imagelink>\r\n<imagelink>\r\n<imagelink>\r\n</center>\r\n<center>\r\n<imagelink>\r\n<imagelink>\r\n<imagelink>\r\n</center>",},
			["Lunar Festival Elders"] = { content = "During the [[Lunar Festival]], there will be 75 '''Elders''' spread around the world. Some are located in [[town]]s, some in [[instance]]s, and some in the wild. Each gives you a [[Coin of Ancestry]]. Note that each Elder may tell you the location up to 5 other Elders in nearby [[zone]]s. You can only receive one coin per Elder. The quests for receiving coins are reset from year to year (previously, some characters were affected by a bug that made seasonal quests unrepeatable in subsequent years, but this issue has been corrected. i.e. The quests have been reset in 2008 and are all \"re-doable\". They were not reset in 2007. It is expected that they will be reset for 2009).\r\n[[Coin of Ancestry|Coins of Ancestry]] can be turned in for several tailoring and engineering patterns, as well as other items. Each coin you receive also generates 75 faction with either the [[Horde]] or [[Alliance]] for a total of 5625 for most races and 6187 for humans if all 75 coins are gathered. Furthermore, each Elder you visit will send you a letter via in-game [[mail]] which contains fireworks or an [[Elder's Moonstone]] and a +250 health [[buff]].\r\n Through the [[Achievements]] system, players are rewarded for participating in the Lunar Festival. 160 achievement points are available through 14 achievements. Upon completing all of the Lunar Festival achievements, you will complete the [[World Events achievements|world event achievement]] [[To Honor One's Elders]] which gives the title.\r\n==Walkthrough for All Coins: Alliance==\r\nYou should have [[Hearthstone]] set to Shattrath City, and use the portal to Ironforge.\r\nThis is fairly easily doable at lvl 70 solo. Even instances like LBRS you can just walk past most of the mobs. The only real challenge is the enemy racial cities where buffed guards and enemy faction players can make achieving your goal difficult.\r\nSTART AT [[Ironforge|IRONFORGE]]:\r\n# [[Ironforge]] - [[Mystic Ward]]\r\n'''Fly gryphon to [[Thorium Point]]'''\r\n# [[Searing Gorge]] - Southwest corner in [[Blackchar Cave]]: \r\n# [[Blackrock Spire]] - After a few pulls into [[LBRS]], the Elder will be across the first wooden bridge. \r\n# [[Blackrock Depths]] - In the middle of the [[Ring of Law]]. \r\n# [[Burning Steppes]] - Flame Crest (that cave with the Libram guy): \r\n# [[Burning Steppes]] - On top of [[Dreadmaul Rock]] north of [[Morgan's Vigil]]: \r\n# [[Stormwind]] - [[The Park]] \r\n# [[Elwynn Forest]] - In [[Goldshire]], behind blacksmith: \r\n# [[Westfall]] - Atop the [[Sentinel Hill]] tower: \r\n'''Fly gryphon to Nethergarde Keep (via Sentinel Hill)'''\r\n# [[Blasted Lands]] - Just North of the [[Dark Portal]]: \r\n# [[Sunken Temple]], [[Swamp of Sorrows]] - Head left when you zone-in. Go up the set of stairs, kill the first set of dragon, and enter the main room with all the dragons. The Elder is in the Northeast alcove.\r\n'''Fly (via Nethergarde) or ride to [[Rebel Camp]]'''\r\n# [[Stranglethorn Vale]] - Outside [[Zul'Gurub]] zone-in: \r\n# [[Stranglethorn Vale]] - Above the bank in [[Booty Bay]]: \r\n'''Take the boat to Ratchet'''\r\nBecause this continent is more horde friendly you will basically follow this route on your mount rather than searching out flight points.\r\n# [[The Barrens]] - In [[Ratchet]], behind the bank: \r\n# ''[[Orgrimmar]] - [[Valley of Wisdom]]: (Luckily for you, Orgrimmar is the largest horde city. And just like in Ironforge, the most crowded places is the bank, the mailbox and the auction house. Orgrimmar has two entrances. One in the south, and one in the west. You would like to enter the western entrance, since this is the entrance with the least players, however you still have to outrun guards!)''\r\n# [[Durotar]] - [[Razor Hill]]: \r\n# [[The Barrens]] - [[Crossroads]]: \r\n# [[The Barrens]] - [[Camp Taurajo]]: \r\n# [[Mulgore]] - North end of [[Bloodhoof Village]] by bridge: \r\n# ''[[Thunderbluff]] - [[Elder Rise]]: (Unlike Orgrimmar, Thunder Bluff is not a very big city, therefore you are much more likely to meet enemy players. However, Thunderbluff is just as popular city as Darnassus is, and therefore you have great chances of not being outnumbered. (At least not by anything more than lvl 15 tauren druids) Enter by the north lift, and go east towards the elder rise.)''\r\n# [[Thousand Needles]] - In [[Freewind Post]]: \r\n# [[Thousand Needles]] - In [[Shimmering Flats]] by [[Mirage Raceway]]: \r\n# [[Tanaris]] - In [[Gadgetzan]]: \r\n# [[Zul'Farrak]] - In [[Gahz'rilla]]'s room by the gong. \r\n# [[Tanaris]] - Outside [[Uldum]], far south Tanaris: \r\n# [[Un'goro Crater]] - By [[Slithering Scar]], above ground: \r\n# [[Silithus]] - Northwest in the [[Crystal Vale]]: \r\n# [[Silithus]] - In [[Cenarion Hold]]: \r\n'''Hearth back to Shattrath and take the portal to Ironforge'''\r\n# [[Dun Morogh]] - In [[Kharanos]] by the inn: \r\n# [[Loch Modan]] - In [[Thelsamar]]: \r\n'''Fly to Aerie Peak\r\n# [[Hinterlands]] - In the middle of Hinterlands by the [[Creeping Ruin]]: \r\n# [[Western Plaguelands]] - Elder Moonstrike is atop the [[Scholomance]] tower, outside the instance: \r\n# [[Western Plaguelands]] - In the Northeast, south of the [[Weeping Cave]]: \r\n# [[Eastern Plaguelands]] - At [[Crown Guard Tower]] in the south: \r\n# [[Eastern Plaguelands]] - By Light's Hope Chapel: \r\n# [[Stratholme]] - North of the [[Festival Lane]] mailbox. Enter through the back door. Make your first left in the instance, go through the gate, turn right, and the Elder will be standing at the back.\r\n# [[Tirisfal Glades]] - Slightly south of the town of [[Brill]]: \r\n# [[Silverpine Forest]] - By The Sepulcher: \r\n# ''[[Undercity]] - In the middle of Undercity, above ground: \r\n'''While in Undercity, use the Lunar Festival Invitation to port to [[Moonglade]]'''\r\n'''Fly to [[Everlook]]'''\r\n# [[Winterspring]] - In Everlook: \r\n# [[Winterspring]] - [[Ruins of Kel'Theril]], southwest of Everlook: \r\n'''Fly to [[Emerald Sanctuary]]'''\r\n# [[Felwood]] - North of [[Jaedenar]]: \r\n'''Fly to [[Azshara]]'''\r\n# [[Azshara]] - Far Southeast corner in [[Ravencrest Monument]], right between the statue's feet: \r\n'''Hearth back to Shattrath and take the portal to Darnassus.'''\r\n# [[Darnassus]], in [[Cenarion Enclave]]: \r\n# [[Teldrassil]] - Southern end of [[Dolanaar]]: \r\n# [[Darkshore]], Auberdine - East of the Hippogryph Master: \r\n# [[Ashenvale]], Astranaar - in the gazebo near the hippogryph: \r\n'''Fly to [[Nijel's Point]]'''\r\n# [[Maraudon]] - Jump into the water by the [[Princess]] and [[Rotgrip]]. Swim to the east and head up the ramp. Turn right and head up a 2nd ramp. The Elder will be in front of you.\r\n# [[Feralas]] - [[Dire Maul]], in the [[Arena]] in the center of the [[Broken Commons]], outside the instance: \r\n# [[Feralas]] - [[Lariss Pavilion]], North East of [[Camp Mojache]]: \r\n==Walkthrough for All Coins: Horde==\r\nYou should have your Hearthstone set to in [[Shattrath City]] and start in [[Orgrimmar]].\r\nSTART AT [[Orgrimmar|ORGRIMMAR]]:\r\n# [[Azshara]] - Far Southeast corner in [[Ravencrest Monument]]: \r\n'''Fly to Everlook'''\r\n# [[Winterspring]] - In [[Everlook]]: \r\n# [[Winterspring]] - [[Ruins of Kel'Theril]], southwest of [[Everlook]]: \r\n'''Fly to [[Bloodvenom Post]]'''\r\n# [[Felwood]] - North of [[Jaedenar]]: \r\n'''Fly to [[Emerald Sanctuary]]'''\r\n# [[Ashenvale]] - West side [[Astranaar]]: [Elder Riversong]\r\n# [[Darkshore]] - Just south of [[Auberdine]]: \r\n'''Take the northern boat from the docks west of [[Auberdine]] to get to Darnassus'''\r\n# [[Teldrassil]] - [[Darnassus]], in [[Cenarion Enclave]]: \r\n# [[Teldrassil]] - Southern end of [[Dolanaar]]: \r\n'''Hearth to [[Shattrath City]] & take the portal to [[Orgrimmar]]'''\r\n# [[Orgrimmar]] - [[Valley of Wisdom]]: \r\n# [[Durotar]] - [[Razor Hill]]: \r\n# [[The Barrens]] - [[Ratchet]], behind the bank: \r\n'''Fly to [[Crossroads]]'''\r\n# [[The Barrens]] - [[Crossroads]]: \r\n'''Fly to [[Camp Taurajo]]'''\r\n# [[The Barrens]] - Camp Taurajo: \r\n# [[Mulgore]] - Northend of [[Bloodhoof Village]]: \r\n# [[Thunder Bluff]] - Elder Rise: \r\n'''Fly to [[Shadowprey Village]]'''\r\n#: If you are going to skip the [[Maraudon]] instance, then [[Crossroads]] - [[Thunder Bluff]] - Bloodhoof - Taurajo - [[Feralas]] is quicker\r\n# [[Maraudon]] - Jump into the water by the Princess and Rotgrip. Swim to the east and head up the ramp. Turn right and head up a 2nd ramp. The Elder will be in front of you.\r\n'''Fly to [[Camp Mojache]]'''\r\n# [[Feralas]] - [[Lariss Pavilion]], North East of [[Camp Mojache]]: \r\n# [[Feralas]] - [[Dire Maul]], in the arena outside the instance: \r\n'''Fly to [[Freewind Post]]'''\r\n# [[Thousand Needles]] - Freewind Post: \r\n# [[Thousand Needles]] - [[Shimmering Flats]] by [[Mirage Raceway]]: \r\n# [[Tanaris]] - [[Gadgetzan]]: \r\n# [[Zul'Farrak]] - In Ghazrilla's room by the gong. \r\n# [[Tanaris]]- In [[Uldum]], far south Tanaris: \r\n# [[Un'Goro Crater]] - By Slithering Scar, above ground: \r\n# [[Silithus]] - In [[Cenarion Hold]]: \r\n# [[Silithus]] - Northwest in the [[Crystal Vale]]: \r\n'''Hearth to [[Shattrath City]] & take the portal to [[Undercity]]'''\r\n# [[Undercity]] - In the middle of Undercity, above ground: \r\n'''Fly to [[Light's Hope Chapel]]'''\r\n# [[Eastern Plaguelands]] - By [[Light's Hope Chapel]]: \r\n# [[Eastern Plaguelands]] - At [[Crown Guard Tower]] in the south: \r\n# [[Stratholme]] - North of the Festival Lane mailbox. If you go in via the back door, make your first left in the instance, go through the archway, turn right, and the Elder will be standing just past the next turn on the left. If you do not have a key, you will need to clear a lot of the instance in order to reach the Elder, so it's best just to find someone who can let you in.\r\n# [[Western Plaguelands]] - In the East, south of the [[Weeping Cave]] on the north side of the road: \r\n# [[Western Plaguelands]] - Atop the [[Scholomance]] tower, outside the instance: (enter Scholomance castle, go right, up step, left, left again-not straight, right, up stairs, up stairs, to room lit by torch, right-not up wheelchair ramp, up and up and up stairs, she's on rampart).\r\n# [[Tirisfal Glades]] - Slightly south of the town of Brill: \r\n'''Fly to [[The Sepulcher]]'''\r\n# [[Silverpine Forest]] - By The Sepulcher: \r\n'''Fly to [[Revantusk Village]], [[Hinterlands]]'''\r\n# [[The Hinterlands]] - In the middle of The Hinterlands by the [[Creeping Ruin]]: \r\n'''Fly to [[Hammerfall]], run through [[Wetlands]] to [[Loch Modan]] or Fly to [[Kargath]], then run up into Loch Modan'''\r\n# [[Loch Modan]] - [[Thelsamar]]: \r\n# [[Dun Morogh]] - [[Kharanos]] by the inn: \r\n# [[Iron Forge]] - [[Mystic Ward]]\r\n'''Run all the way to Stormwind or run to [[Kargath]], Fly to [[Grom'gol Base Camp]] and run to Stormwind or take the Deeprun Tram'''\r\n# [[Stormwind City]] - [[Park]]\r\n# [[Elwynn Forest]] - [[Goldshire]], behind blacksmith: \r\n# [[Westfall]] - Atop the [[Sentinel Hill]] tower: \r\n# [[Stranglethorn Vale]] - Outside [[Zul'Gurub]] zone-in: \r\n'''Fly from Grom'Gol Base Camp to Booty Bay'''\r\n# [[Stranglethorn Vale]] - Near the Horde Wind Rider Master in [[Booty Bay]]: \r\n'''Fly from Booty Bay to Stonard'''\r\n# [[Sunken Temple]] - [[Swamp of Sorrows]] - Head left when you zone-in. Go up the set of stairs, kill the first set of dragon (you can stealth through them at level 60), and enter the main room with all the dragons. The Elder is in the northeast corner.\r\n# [[Blasted Lands]] - Just North of the [[Dark Portal]]: \r\n'''Fly from [[Stonard]] to [[Flame Crest]]'''\r\n# [[Burning Steppes]] - Flame Crest (that cave with the Libram guy): \r\n# [[Burning Steppes]] - On [[Dreadmaul]] rock north of [[Morgan's Vigil]]: \r\n'''Fly from [[Flame Crest]] to [[Thorium Point]]'''\r\n# [[Searing Gorge]] - Southwest corner in [[Blackchar Cave]]: \r\n# [[Blackrock Spire]] - After a few pulls into LBRS, the Elder will be across the first wooden bridge. \r\n# [[Blackrock Depths]] - In the middle of the [[Ring of Law]].",},
			["Lunar Festival Emissary"] = { content = "'''Lunar Festival Emissaries''' are level 55 [[quest giver]]s located outside the banks and at the Lunar Pools in [[Darnassus]], [[Ironforge]] and [[Stormwind]].\r\nThey are only available during the annual [[Lunar Festival]] event.\r\nThey start the quest The Lunar Festival ([[Lunar Festival]]).\r\nSee [[List of Darnassus NPCs]], [[List of Ironforge NPCs]], & [[List of Stormwind NPCs]].",},
			["Lunar Festival Harbinger"] = { content = "'''Lunar Festival Harbingers''' are level 55 [[quest giver]]s located at the Lunar Pools in [[Darnassus]], [[Ironforge]], [[Stormwind]], [[Orgrimmar]], [[Thunder Bluff]] and [[Undercity]].\r\nThey are only available during the annual [[Lunar Festival]] event.\r\nThey start the following quests:\r\n* Lunar Fireworks ([[Lunar Festival]])\r\n* Valadar Starsong ([[Lunar Festival]])\r\nSee [[List of Darnassus NPCs]], [[List of Ironforge NPCs]], [[List of Stormwind NPCs]], [[List of Orgrimmar NPCs]], [[List of Thunder Bluff NPCs]], & [[List of Undercity NPCs]].",},
			["Lunar Festival Herald"] = { content = "'''Lunar Festival Heralds''' are level 55 [[quest giver]]s located outside the banks and at the Lunar Pools in [[Orgrimmar]], [[Thunder Bluff]] and [[Undercity]].\r\nThey are only available during the annual [[Love is in the Air]] event.\r\nThey start the quest The Lunar Festival ([[Lunar Festival]]).\r\nSee [[List of Orgrimmar NPCs]], [[List of Thunder Bluff NPCs]], & [[List of Undercity NPCs]].",},
			["Lunar Festival Invitation"] = { content = "==Source==\r\nThis item is a quest reward from Lunar Fireworks.",},
			["Lupos"] = { content = "'''Lupos''' is level 23 [[rare mob]] [[wolf]] found roaming around [[Brightwood Grove]] and [[the Darkened Bank]] in [[Duskwood]]. Lupos used to inflict [[shadow]] damage when it attacked. It has a 4-6 hour respawn timer.\r\n==Loot==\r\n*Hide of Lupos\r\n*Nightbane Staff",},
			["Lurch!"] = { content = "''Braaaaaaaains!''",},
			["Lure"] = { content = "#REDIRECT [[Fishing lure]]", redirect = "Fishing lure",},
			["Lurker below"] = { content = "#REDIRECT [[The Lurker Below]]", redirect = "The Lurker Below",},
			["Lushwater Oasis"] = { content = "The '''Lushwater Oasis''', just south of the [[Crossroads]], is probably the most important of the oases in the Barrens, in that it is the entrance to the accursed [[Wailing Caverns]]. [[Kolkar]] [[Centaur]] stalk between the trees, eager to hunt the wild beasts coming to drink. Due to it's closeness to the Wailing Caverns and to the Crossroads, this is a popular spot to fish for the [[Deviate Fish]], the integral ingredient in the popular (if idiosyncratic) [[Savory Deviate Delight]].",},
			["Lustrous Star of Elune"] = { content = "'''Lustrous Star of Elune''' is a [[socket]]ed [[gem]] crafted by [[Jewelcrafting]]. It requires a minimum skill of 350 and a [[Simple Grinder]].\r\n Materials required:\r\n1x [[Star of Elune]]\r\nThe recipe for this item is taught by [[Design: Lustrous Star of Elune]], a random [[world drop]].",},
			["LW"] = { content = "#REDIRECT [[Leatherworking]]", redirect = "Leatherworking",},
			["Lykul Wasp"] = { content = "'''Lykul Wasp''' can be found in [[The Underbog]].\r\n==Abilities==\r\n \r\n==Drops==\r\n \r\n0.00% Chance of a [[epic]] drop.\r\n0.00% Chance of a [[rare]] drop.\r\n0.45% Chance of an [[Uncommon]] drop.\r\n0.00% Chance of a [[common]] drop.\r\n0.27% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created.",},
			["Lylandor"] = { content = "'''Lylandor''' is a level 61 [[Warsong Gulch]] [[battlemaster]] located in the [[Lower City]] of the [[neutral]] [[Shattrath City]]. He doesn't speak much, and replies only with \"Mmm\".\r\nAs of [[Patch 2.4.0]] he no longer sits down but rather stands up. He has also stopped conversing with [[Haelga Slatefist]].\r\nSee [[List of Shattrath City NPCs]].",},
			["Lylandris"] = { content = "'''Lylandris''' is a level 61 [[Warsong Gulch]] [[battlemaster]] located in the [[Hall of Arms]] in [[the Military Ward]] in the [[dwarf]] city of [[Ironforge]].\r\nSee [[List of Ironforge NPCs]].",},
			["Lynore Windstryke"] = { content = "==Quotes==\r\nWe are quickly learning the price of death in this frigid wasteland, <name>. The [[Lich King|Lich King's]] power extends across every inch of [[Northrend]], permeating into the earth itself! He turns our own fallen people against us.\r\nFrom the sky, [[Risen Gryphon Rider|risen gryphon riders]] rain down their vengeful [[stormhammer]]s as the walking dead assail us on the ground.",},
			["Lynx"] = { content = "A '''lynx''' is a red or brown colored big cat found in [[Eversong Woods]], [[Ghostlands]], [[Netherstorm]], and [[Blade's Edge Mountains]]. They come in Springpaw and Ghostclaw varieties. The Ghostclaw were apparently affected by the undead [[Scourge]] during their invasion and what they did to the [[Ghostlands]] to the south. The lynx may be a native to [[Quel'Thalas]], but other speculation leads some to believe that they may have been [[nightsaber]]s or panthers that came with the [[highborne]] during their exodus.\r\nThey drop [[Lynx Meat]] that can be cooked with the [[Lynx Steak]] recipe.\r\nAn interesting note is that the Lynx uses the same Model as the [[night elf]] [[Druid]]'s [[Cat Form]].",},
			["Lynx Meat"] = { content = "'''Lynx Meat''' is lean and skinny, tasty but not very nutritious.\r\n==Source==\r\nLynx Meat can be acquired from the various [[lynx]]es in Quel'Thalas, [[Springpaw Stalker]]s and [[Elder Springpaw]]s in [[Eversong Woods]], and the [[Ghostclaw Lynx]], [[Ghostclaw Ravager]] and [[Starving Ghostclaw]] in the Ghostlands.\r\n==Lynx Meat as an Ingredient==\r\nLynx Meat is used in the following recipes:\r\n===[[Cooking]]===\r\n*[[Lynx Steak]]\r\nYou can buy the recipe from [[Landraelanis]] in [[Falconwing Square]].",},
			["Lynx Steak"] = { content = "'''Lynx Steaks''' have a slightly gamey flavour.\r\n==Source==\r\nThis meal is made by [[Cooking|cooks]] with a skill level of 1. The components are:\r\n*1 Lynx Meat\r\nRecipe: Lynx Steak is sold by [[Landraelanis]] in [[Falconwing Square]] in [[Eversong Woods]].\r\n==Notes==\r\nThe only way [[Alliance]] cooks can attain this recipe is through the neutral [[auction house]]s.",},
			["Lyranne Feathersong"] = { content = "'''Lyranne Feathersong''' is a level 56 [[food]] and [[drink vendor]] located in [[Starfall Village]] in the [[contested]] territory of [[Winterspring]].\r\nSee [[List of Winterspring NPCs]].",},
			["Lyria Du Lac"] = { content = "'''Lyria Du Lac''' is a level 12 [[warrior trainer]] located in [[Goldshire]] in the [[human]] starting zone of [[Elwynn Forest]].\r\nSee [[List of Elwynn Forest NPCs]].",},
			["M'uru"] = { content = ":''This article is about the character M'uru. For information on how to defeat M'uru in World of Warcraft, please see [[M'uru (tactics)]].''\r\n'''M'uru''' was the sole [[naaru]] guardian of [[Tempest Keep]] and currently resides on the [[Sunwell Plateau]]. When the keep was invaded by [[Kael'thas Sunstrider|Kael'thas]] and his [[blood elf]] followers, M'uru was captured and taken to [[Farstriders' Square]] in [[Silvermoon City]], where his energy was being drained for use by the [[blood knight|Blood Knights]].\r\nM'uru was a [[hostile]] level 73 to [[Horde]] players prior to patch 2.4, but did not attack and could not be attacked. He was not hostile to [[Alliance]] players, however. The blood elves draining him could not be killed (they would remain at one percent health).\r\n==Patch 2.4==\r\nIn [[Patch 2.4.0]], Kael'thas and his [[felblood]] minions captured M'uru from Silvermoon City and took him to [[Sunwell Plateau]]. The magisters who were draining him now stand dazed.\r\nWithout M'uru, [[Lady Liadrin]] was forced to seek out another source of power for the Blood Knights. She speaks to [[A'dal]] in [[Shattrath City]], asking for forgiveness for M'uru's imprisonment, and pledging her allegiance to the [[Shattered Sun Offensive]]. In that same instant, it is revealed that M'uru's imprisonment was foretold by [[Velen]]. M'uru willingly accepted his role in the events that unfolded, knowing that it would lead to the elves' redemption.\r\nBlood elf paladins completing Claiming the Light must now gather remnants of \"holy energy\" that linger around the magisters, rather than the previous requirement of draining M'uru directly.\r\n[[M'uru (tactics)|M'uru]] appears as a boss in [[Sunwell Plateau]]. He is now a darkened naaru, transforming into [[Entropius]] part-way through the encounter.\r\nAfter [[Kil'jaeden (tactics)|Kil'jaeden]] is defeated, [[Velen]] uses M'uru's \"spark\" to reignite the Sunwell.\r\n==Possible origins of name==\r\nM'uru's name is possibly derived from the writings of Tolkein. In one of the languages of Middle Earth, the evil spider goddess Ungoliant was referred to as Múru.",},
			["M'uru (tactics)"] = { content = ":''This article is about how to defeat M'uru in World of Warcraft. For character biography, please see [[M'uru]].''\r\nAs of patch 2.4, '''M'uru''' is missing from his location beneath the [[Blood Knight]] headquarters in [[Silvermoon]]'s [[Farstriders' Square]], having been captured by [[Kael'thas]] and brought to the [[Sunwell Plateau]]. [[Magister Astalor Bloodsworn]] curses Kael'thas and his [[felblood]]s for their treachery, commenting that [[Lady Liadrin]] is looking for another source to power the Blood Knights' magic.\r\nM'uru is located behind [[Rohendor]], the Second Gate and ahead of [[Archonisus]], the Final Gate, placing it as the fifth boss encounter of the instance. M'uru was made accessible at the same time across all servers five weeks (29th April, 2008) after the opening of [[Rohendor]], the Second Gate. The removed quest Rohendor, the Second Gate warns that M'uru is now a \"[[Entropius|twisted reflection of its former self]]\".\r\n*M'uru was first downed by SK Gaming (EU - Vek'nilash) on May 4th, 2008.\r\n===M'uru===\r\n* Negative Energy: A black beam used on 4-5 random targets every second throughout the fight. This does ~940-1060 unresistable Shadow damage.\r\n* Summons 2 [[Shadowsword Berserker]]: Run very fast, can be crowd controlled. Dual Wielders, hit for 3.5k with Main Hand, 1.5 with Off Hand. Has buff called Flurry in which attack speed increased is by 100%, movement speed increased is by 100% for 6 sec. 124k HP. \r\n* Summons 1 [[Shadowsword Fury Mage]]: Run very fast, can be crowd controlled. Fel Fireball (2 sec cast) deals 4250 to 5750 fire damage (resistible.) Also melees for 3-4k damage. Has a buff called Spell Fury which can be spell stolen. Spell Fury causes spells cast to be instant, increase magic damage by 50% and make them unable to move. 104k HP.\r\nThese spawn 1 Mage and 2 Berserkers at both sides every 60 seconds. That is 6 Humanoid adds every minute. The Humanoid adds spawn from the corridor behind M'uru, and the ramp/doorway from which you enter, running towards the center.\r\n* Summon [[Void Sentinel]]: Summons a large [[Voidwalker]] that hits very hard, roughly 8-10k melee on tanks (~25k unmitigated). 70k HP.\r\n** Shadow Pulse: AoE ability which deals about 4k shadow damage about every 3 sec.\r\n** Void Blast: Single target attack which deals 10-11k dmg and puts a debuff slowing your attack by 35% (is spell reflectable and can be resisted).\r\n**8 [[Void Spawn]]s appear upon a [[Void Sentinel]]s death, doing 700-900 melee damage each. 30k HP. Can be enslaved by warlocks, can be worthwhile enslaving a few at the end of phase one to use against Entropius or even during phase 1.\r\n***Shadow Bolt Volley: 1200-1600 shadow damage to targets around them (resistible.)\r\n[[Void Spawn]]s and [[Void Sentinel]] can be snared, [[Void Spawn]]s can be feared.\r\n* Darkness: Every 45 sec, creates a large Void Zone, covering the larger circle (i.e. from up to the outside edge of the wide purple band in the center) in the middle of the room, and does ~3,000 shadow damage per second to anyone standing in it and they cannot be healed. This also spawns 8 [[Dark Fiend]]s which explode for 5,000 raid-wide damage and leaves a 2000 damage dot on raid when one reaches a target (resistible). These can be killed by Dispels or Purges.\r\n* Enrage: M'uru and Entropius share a 10 minute enrage timer. At this point all damage increases by 5x and the raid instantly wipes due to 2500 - 10,000 damage Negative Energy attacks.\r\n===Entropius===\r\n* Negative Energy: Becomes a Chain Lightning type attack with random targets every second throughout the fight. This does ~1885 to 2115 Shadow damage to the 1st target, ~50% of that to 2nd target and ~25% to 3rd target. The number of primary targets increases every 12-13 seconds. Unresistable.\r\n* Darkness: Spawns a Void Zone under a player dealing 3000 Shadow damage every second. Will spawn 1 Dark Fiend after a few seconds which must be Dispelled or Purge.\r\n* Singularity: Spawns over a player. After a few seconds will move around and toss any nearby players around dealing 500 damage a tick.\r\n==Raid Composition==\r\nM'uru is a very DPS intensive fight, and as such it requires stretching your healing and tanking as much as possible. This includes having about 4 tanks, 6 healers and 15 DPS. It is highly recommended, if not absolutely necessary, to include a Protection Paladin as one of your tanks to pick up the Void Spawns that spawn.\r\nYou must divide your DPS up into a few sub-groups, that are able to each put out substantial amounts of DPS. Generally you will have 2 groups assigned to killing Humanoid adds, as well as a Warlock group assigned to kill Void Sentinels and Void Spawns.\r\n===Pulling M'uru===\r\nWhen you are ready to pull M'uru, DPS will mount up in the door way and be ready to run in to their positions and burn M'uru as hard as possible before switching to your respective jobs. Humanoid tanks should be ready to pick up their adds on each side from the start, using only one or two attacks to throw up a [[Sunder Armor]] or [[Faerie Fire]] on the boss.\r\nCan also use an Eye of Kilrog to engage and quickly reset him, allowing 30 seconds for the raid to setup and position themselves.\r\n==Phase 1==\r\nWhile your raid group runs in and attacks M'uru, you will be in Phase 1. This phase is a combination of a control fight and a DPS race. Each Humanoid group, which will be comprised of one tank, one healer, and three to four DPS, will be in charge of controlling each add entrance (the doorway and the opposite side of the room, where the ramp down to [[Kil'jaeden (tactics)|Kil'jaeden]] is blocked off.) A Mage is also highly recommended on each side, to [[Polymorph]] a Berserker or Mage. You will also have a group of AoE, generally Warlocks, to control the Void Sentinels and Spawns. This AoE group is recommended to be comprised of a Protection Warrior or Feral Druid, a Protection Paladin, 3-4 Warlocks and 2 healers (one for each tank). You should also have two raid healers assigned to keep the rest of the raid up.\r\n===Humanoid Adds===\r\nEach Humanoid Wave consists of two Berserkers and one Mage. When the Humanoid wave enters the room, the tank should pick up all 3 of them while a mage sheeps a Berserker and the tank drags the other two adds slightly away from the sheep so multitarget attacks such as [[Blade Flurry]], [[Cleave]], [[Sweeping Strikes]] or [[Multi-Shot]] can occur.\r\n===Void Sentinels and Void Spawns===\r\nThe warrior will need to be fast in picking up the Void Sentinels, and the warlocks need to be quick in DPSing the Void Sentinels to allow this mobility.\r\nWarlocks will have to manage a rotation on the Sentinels and Spawns to ensure that DPS is still active on M'uru, you need to allow the Protection Paladin to gather up two or three sets of spawns before AoEing them down. Warlocks should DPS the Void Sentinels, kill them, allow the Protection Paladin to pick up the adds and while this is occurring DPS M'uru until another Sentinel is ready to be DPSed.\r\n===Darkness===\r\nYou should assign a Shadow Priest to DPS M'uru full time and Mass Dispel the Dark Fiends when Darkness comes up inside of it, thereby killing them. Be ready to target ones that resist with a single Dispel or call it out so someone else can Dispel/Purge.\r\n==Phase 2==\r\nAfter M'uru has been slain, he transforms into [[Entropius]], a demon-type [[void god]]. Most of the adds that were alive during the transition should be dead or almost dead as there is 10 seconds before Entropius engages the raid. Entropius has 1,450,000 health and at this point the fight turns into an all-out DPS race before the raid damage from Negative Energy ramps up substantially and overwhelms your healers. This fight also tests the reflexes of all players in the raid and their ability to move on a seconds notice.\r\n==Quotes==\r\nUnknown.\r\n==Loot==\r\nM'uru drops 3 items plus one of the Sin'dorei rings.",},
			["Ma'ruk Wyrmscale"] = { content = "'''Ma'ruk Wyrmscale''' <Dragonmaw Warlord> is a level 23 [[rare mob]] [[orc]] found in the [[Wetlands]].\r\n==Loot==\r\n*Scythe Axe\r\n*Warchief's Girdle",},
			["MA"] = { content = "#REDIRECT [[Main assist]]", redirect = "Main assist",},
			["Mac"] = { content = "#REDIRECT [[World of Warcraft on Mac]]", redirect = "World of Warcraft on Mac",},
			["Macalroy"] = { content = "'''Macalroy''' is the first quest giver members of the [[Alliance]] will see after getting off the ship at [[Valgarde]] in the [[Howling Fjord]].\r\nHe is involved in the following quest:\r\n* Hell Has Frozen Over...",},
			["Mace"] = { content = "A '''mace''' is a [[one-handed]] or [[two-handed]] [[blunt]] [[weapon]], usually in the form of a large heavy metal piece (with a varying set of short edges, points or protrusions) on a short rod. Some maces have the heavy piece on a swinging chain (commonly called a ''flail'') or more fiercesome points and edges, but rarely a long enough pole to qualify as a [[polearm]].\r\nThe list of trainers can be found here: [[Weapon master|Weapons Trainers]]. \r\nA popular sub-type is the [[hammer]] which resembles the more practical tool used in some [[professions]]. \r\nOne-handed maces are often used by combat [[Rogue]]s because of their high delay and high damage range, and [[Priest]]s, [[Shaman]] and [[Druid]]s because many exist that give [[proc]]s or [[attribute]] bonuses beneficial to [[caster]]s.\r\nTwo-handed maces can be used by Druids, Paladins, Shaman, and Warriors. According to WarCraft [[lore]], the two-handed [[warhammer]] was the favored weapon of the [[Knights of the Silver Hand]], led by [[Uther]] the Lightbringer. Following the death of Uther at the hands of [[Arthas]] and the devastation of the Order, the weapon fell out of favor as that exclusively used by [[paladins]].\r\nHumans have [[sword]] and mace [[specialization]] which now (following patch 2.3) translates into 5 additional points of [[Expertise]].\r\nSignificant maces:\r\n* Verigan's Fist, the reward for completing the [[Paladin]] quest [[Quest:The Test of Righteousness|The Test of Righteousness]].\r\n* The Unstoppable Force, available at [[Exalted]] [[Reputation]] with your respective [[Alterac Valley]] faction.\r\n* Sulfuras, Hand of Ragnaros\r\n* Might of Menethil epic two-hand mace that drops off from [[Kel'Thuzad]] in [[Naxxramas]].\r\n* Hammer of the Naaru another epic two-hand mace that drops from [[High King Maulgar]] in [[Gruul's Lair]] in [[Blade's Edge Mountains]].\r\n* The [[Doomhammer]], legendary weapon of the orc Warchief [[Orgrim Doomhammer]].",},
			["Mace Specialization"] = { content = "*[[Mace Specialization (Rogue talent)|Mace Specialization]] (Rogue talent)\r\n*[[Mace Specialization (Warrior talent)|Mace Specialization]] (Warrior talent)\r\n*[[Mace Specialization (human racial)|Mace Specialization]] (Human racial)",},
			["Machinima"] = { content = "Machinima (pronounced /məˈʃiːnəmə/ or /məˈʃɪnəmə/), a Portmanteau of machine cinema, is a collection of associated production techniques whereby computer-generated imagery (CGI) is rendered using real-time, interactive 3-D engines, such as those of games, instead of professional 3D animation software.\r\nCreating '''machinima''' is a popular past time among WoW players. It is the process of creating movies about the game by capturing game play and putting it together with music with editing software.\r\nNote that just recording gameplay (for example PvP videos) isn't considered machinima. Machinima implies that a movie editing program has been used at some point.\r\n==Production==\r\nTo make WoW Movies one needs a couple of programs (most of them can be downloaded for free), a bit of time and some creativity.\r\nSo first you need to get some video capturing software from fraps.com, Wegame.com (I prefer this one because it works well and its free), or planetgamecam.com. The next step to making your own WoW Movie is the video editing software which if you are using Windows XP you already have, it's called Windows Movie Maker. Or you can use [[WoW Model Viewer]].\r\nNow you have the software you need, next come up with an idea, capture some game play, edit it down and add some music or voice overs. Then up load your new WoW Movie to places like YouTube.com, Wegame.com, Warcraftmovies.com, Machinima.com, or Google video and your on you're way to stardom.",},
			["Macintosh"] = { content = "#REDIRECT [[World of Warcraft functionality on Macs]]", redirect = "World of Warcraft functionality on Macs",},
			["Maclure Vineyards"] = { content = "'''The Maclure Vineyards''', located in southern [[Elwynn Forest]], belong to the Maclure Family. The Maclures are in a bitter rivalry with the nearby Stonefield Family, but despite their intense dislike of each other, a child from both families has fallen in love with each other in true Romeo and Juliet fashion. There is hope their love can bring the two families together, and there are several quests that involve the feuding families. The Maclure Vineyards are a great place to practice [[skinning]] as there are over a dozen [[boar]]s in the [[Farm|vineyards]] alone.\r\n==Related quests==\r\n*[[Give Gerard a Drink]]\r\n*[[Pie for Billy]]\r\n*[[Lost Necklace]]\r\n*[[Note to William]]\r\n*[[Young Lovers]]\r\n*[[Speak with Gramma]]\r\n*[[Back to Billy]]\r\n*[[The Escape (Alliance)]]\r\n*[[Collecting Kelp]]\r\n*[[Kobold Candles]]\r\n*[[Shipment to Stormwind]]\r\n*[[Goldtooth (quest)]]\r\n*[[Princess Must Die!]]",},
			["Macro"] = { content = "In the ''[[World of Warcraft]]'', a '''macro''' is a method of combining several actions to execute in a single button press or keystroke. At any time, you can have 18 macros that are available to all your characters on all servers within one [[account]], and 18 other macros that are available to each specific character, for a total of 36 macros that each character has access to.\r\nA macro may also refer to some automated method (programmed keystrokes and/or mouse movements) to fight or repeat some action. Macros, if performed ''outside of the standard game client'' may be considered [[cheating]]. Don't be afraid though: Everything you can do with in-game macros is ok.\r\n'''To edit your account-wide macros outside the game''', find your <code>World of Warcraft\WTF\Account\''<account name>''\macros-cache.txt</code> file, and edit it using Notepad or another trusted text editor. (Wordpad does not work even if you save it as a text file.) To edit your character-specific macros, find your <code>...\Account\''<account name>''\''<server name>''\''<char name>''\macros-cache.txt</code> file, and edit it in the same manner. As you do this, note that the macros should probably be numbered starting with 1 and continue to 18 on the account-wide macros; and starting with 16777217 and continue to 16777234 for your character-specific macros. They don't need to be in order from the beginning of the file. It is probably best to save at least one account-wide and one character-specific macro in the game before you create your own macro file, to be familiar with macro file structure and to be sure of the numbering of macros.\r\n==Macros in ''World of Warcraft'' 2.0==\r\nThe 2.0 release of the ''World of Warcraft'' game engine revamped how macros were made and how they were used.\r\nFor a comprehensive guide to the new macros, see [[HOWTO: Make a Macro|2.0 Macro guide]].\r\n----\r\nWelcome to the macros section. Here you will find sample macros others have developed to meet a particular need. If you are unclear what a [[UI_Beginners_Guide|slash command]], [[UI_Beginners_Guide|macro]] or [[UI_Beginners_Guide|script]] is, you are encouraged to visit the [[UI Beginners Guide]]. Although slash commands, macros, and scripts are technically different, the term ''macro'' is often used loosely. \r\nIf you need detailed instructions for creating your first macro, please visit [[HOWTO: Make a Macro]]. If you have questions regarding the limitations and capabilities of macros, please visit [[UI FAQ/Macros and Scripts]]. If you have questions concerning the logic of a particular macro, you may find your answers under the [[World of Warcraft API]].\r\nThis section is broken down by macro use or application. General purpose macros used by all classes can be found under [[Useful macros]]. Macros that are class specific can be found under the respective class page.\r\nYou will notice a navigation box on many of the macro pages including this one. This box can help you quickly move between various collections of macros.\r\nOne final note: Macro functionality may change as Blizzard continues to evolve World of Warcraft. Over time, some macros may cease to function. Keep this in mind when working with a macro written by someone else.\r\nHave fun and good luck!",},
			["Macros"] = { content = "#REDIRECT [[Macro]]", redirect = "Macro",},
			["Madame Eva"] = { content = "'''Madame Eva''' is a level 25 [[quest giver]] located in [[Darkshire]] in the [[human]]-aligned territory of [[Duskwood]]. She is the grandmother of [[Alyssa Eva]] and [[Lohgan Eva]].\r\nShe starts the following quests:\r\n* Ghost Hair Thread\r\n* Deliver the Thread\r\n* The Totem of Infliction\r\n* The Shadowy Search Continues\r\n* The Legend of Stalvan\r\n==Quotes==\r\n*\"The stars speak to me. They whisper of the horrors waiting in the night.\"",},
			["Madcap's Outfit"] = { content = "'''Madcap's Outfit''' is the [[Zandalar Tribe set]] for [[Rogue]]s.\r\n==Source==\r\nMost Items of Madcap's Outfit can be acquired through quests given by [[Falthir the Sightless]], who can be found on the [[Yojamba Isle]] in [[Stranglethorn Vale]].\r\nThe quests require a given Reputation with the [[Zandalar Tribe]] and a token from a boss in [[Zul'Gurub]].\r\nThe only exception is Renataki's Charm of Trickery, which is formed by combining a Punctured Voodoo Doll with Gri'lek's Blood, Renataki's Tooth, Wushoolay's Mane, and Hazza'rah's Dream Thread.\r\nWhile the voodoo dolls can be found in [[Jinxed Hoodoo Pile]]s (which are found throughout [[Zul'Gurub]]), the rest can be found on the respective boss in the [[Edge of Madness]], in [[Zul'Gurub]].\r\n==Items==\r\n \r\n==Notes==\r\nSee also: [[Set look alikes]]",},
			["Madoran"] = { content = "#REDIRECT [[Madoran Bronzebeard]]", redirect = "Madoran Bronzebeard",},
			["Madoran Bronzebeard"] = { content = "'''Madoran''' was ruling [[Thane]] of [[Ironforge]] and [[Ironforge Clan]] during the [[War of the Three Hammers]]. Following the defeat of [[Thaurissan]] and the [[Dark Iron Clan]] he had the [[Thandol Span]] bridge built to maintain links with the [[Wildhammer Clan]] dwarves of the [[Hinterlands]].\r\nAfter his death, his and Khardros' sons had statues built to honor both he and [[Khardros Wildhammer]] in the [[Valley of Kings]] in southern [[Loch Modan]]. They keep a constant vigil over the blasted lands to the south, site of the [[Dark Iron Clan]] betrayal and defeat. His son became the new thane of Ironforge.",},
			["Madrigosa"] = { content = ":''For how to defeat her Undead Form found in Sunwell Plateau see [[Felmyst]].''\r\n'''Madrigosa''' is a female [[blue dragon]] flying above Brutallus in the [[Dead Scar]], visible from both the [[Isle of Quel'Danas]] and within the [[Sunwell Plateau]]. She came to the island with [[Kalecgos]] in order to defend [[Anveena]] from [[Kil'jaeden]] and the rest of the [[Burning Legion]], though the two became separated within the Plateau.\r\nInside the raid, when players approach the Den of Iniquity, a room overlooking the Dead Scar, Madrigosa blocks their way with a wall of ice and does battle with Brutallus, demanding answers about Anveena and Kalecgos, only to be killed by the pit lord. When the raid defeats Brutallus, his blood seeps into the ground and flows beneath her body, dissolving her flesh and raising her skeletal remains as [[Felmyst]], a [[fel dragon]], who is the third boss of the Sunwell Plateau.\r\nSee [[Sunwell Plateau NPCs]].\r\n===Isle of Quel'Danas===\r\n* Brutallus yells: Grraaarrr! You think to make an icicle out of me? Come down, then I will add real fire to your life.\r\n* Madrigosa yells: I hear [[Pit lord|Pit Lord]]s are born from maggots, Brutallus!\r\n* Brutallus yells: Stupid blue birdie! Let's see if you can pull this maggot from the dirt!\r\n* Madrigosa yells: I prefer my meals a bit colder!\r\n* ''Madrigosa encases Brutallus in a block of ice''\r\n* Brutallus yells: Come down! I tear your wings from your shoulders and feed you to the dirt. Then YOU be the maggot, dragon!\r\n===Sunwell Plateau===\r\n* Madrigosa yells: Hold, friends! There is information to be had before this devil meets his fate!\r\n* ''Madrigosa creates a wall of ice between the Den of Iniquity and the Dead Scar, preventing the raid from passing.\r\n* Madrigosa yells: Where is [[Anveena]], demon? What has become of [[Kalec]]?\r\n* Brutallus yells: Puny lizard! Death is the only answer you'll find here!\r\n* ''Madrigosa freezes Brutallus.''\r\n* Madrigosa yells: You will tell me where they are!\r\n* ''Brutallus breaks free from the ice.''\r\n* Brutallus yells: Grah! Your magic is weak!\r\n* ''Madrigosa traps Brutallus in an arcane barrier.\r\n* Madrigosa yells: Speak, I grow weary of asking!\r\n* ''Brutallus does battle with Madrigosa, eventually killing her.''\r\n* Madrigosa yells: [[Malygos]], my lord! I did my best!\r\n* Brutallus yells: That was fun, but I still await a true challenge!\r\n* Brutallus yells: Come, try your luck!\r\n* ''Brutallus roars, shattering the ice barrier.\r\n==See also==\r\n* [[Isle of Quel'Danas NPCs]]",},
			["Mad Magglish"] = { content = "'''Mad Magglish''' is a level 18 [[goblin]] who stole some [[99-Year Old Port]] from [[Ratchet]]. He fled to the [[Wailing Caverns]]. He is found outside the [[instance]] portal.\r\n==Abilities==\r\n'''Smoke Bomb''' - Casts a smoke bomb, stunning nearby enemies for 3 seconds. and putting the caster into stealth mode.\r\n* School: [[Physical]]\r\n'''Sneak''' - Stealthed, 50% reduced movement speed until engaged in combat.\r\n==Quests==\r\n*Trouble at the Docks",},
			["Mad Servant"] = { content = "'''Mad Servants''' can be found in [[Zul'Gurub]] .\r\n==Quotes==\r\nTroll mojo da strongest mojo!\r\n==Drops == \r\n \r\n0.09% Chance of an [[epic]] drop.\r\n1.06% Chance of a [[rare]] drop.\r\n4.40% Chance of an [[Uncommon]] drop.\r\n0.35% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Maelstrom's Tendril"] = { content = "==Source==\r\nThis item is a quest reward from The Maelstrom's Tendril.\r\n==Maelstrom's Tendril as a quest objective==\r\nThis item is an objective of Maelstrom's Wrath.",},
			["Maelstrom"] = { content = "The '''Maelstrom''' is the gigantic rift that was created when the [[Well of Eternity]] collapsed at the [[Sundering|Sundering of the World]].\r\nFrom the ''[[Warcraft III: Reign of Chaos]]'' manual:\r\n ''As the aftershocks from the [[Well of Eternity]]'s implosion rattled the bones of the world, the seas rushed in to fill the gaping wound left in the earth. Nearly eighty percent of [[Kalimdor]]'s landmass had been blasted apart, leaving only a handful of separate continents surrounding the new, raging sea. At the center of the new sea, where the [[Well of Eternity]] once stood, was a tumultuous storm of tidal fury and chaotic energies. This terrible scar, known as the Maelstrom, would never cease its furious spinning. It would remain a constant reminder of the terrible catastrophe... and the Utopian era that had been lost forever.''\r\nAs things currently stand, the Maelstrom is a large storm only viewable in ''World of Warcraft'' on the world map, where it sits between Kalimdor and the Eastern Kingdoms. Ship and Zeppelin routes go out of their way to avoid the Maelstrom, for fairly obvious reasons. It is implied that the Maelstrom is slowly drawing the [[Broken Isles]] towards itself, and will ultimately destroy them for good.\r\nAt the center of the Maelstrom is a location known as The [[Eye (Maelstrom)|Eye]]. The empires of the [[Makrura]] and [[Naga]] lie beneath it.\r\nIn ''Warcraft III'', when [[Thrall]]'s fleet crashed, it made an emergency landing on an island near the maelstrom where the trolls were fighting desperately against human colonists and murloc raiders. The island was destroyed (though not by the Maelstrom) and Thrall barely escaped.\r\nTo some, the sea around the Maelstrom is known as the \"Blood Sea\".\r\n==Zones & Locations==\r\n*The [[Eye (Maelstrom)|Eye]]\r\n*[[Nazjatar]]\r\n*The [[Boiling Terrace]]\r\n*The [[Rift]]\r\n*[[Scintal Reef]]\r\n*The [[Drowned Reaches]]\r\n*[[Gishan Caverns]]\r\n*[[Mak'aru]]\r\n*[[Pillar Deep]]",},
			["Mael Shelub"] = { content = "'''Mael Shelub''' is a bitter and cruel [[nerubian]] [[necromancer]]. He despises everyone, especially the [[Lich King]] and the [[Scourge]], and though still alive - unlike many of his kin - he prefers the company of the dead rather than the living. His hatred of the Lich King stems from his belief that [[undead]] creatures should always be under mortal control — anything else is an abomination. \r\nMael offered his services to [[Blarus Whitrick]], a Forsaken undead, who readily accepted. They settled in [[Gaval Moch]], a ruined castle in [[Silverpine Forest]], with a number of acolytes. Mael only pretended to serve Blarus however, as his beliefs concerning undead extended to the free-willed Forsaken, whose use of magical arts repelled him. The nerubian also despised Blarus's (supposed) servant, the dreadlord [[Ganthrifal]] who he consider to have moved in on his territory. Mael often entertained the thought of murdering the cunning dreadlord. Much like Ganthrifal, he only pretended to serve Blarus as he believed he could use him in his own schemes; though he would have slayed him if given the opportunity. For a long time, Mael had felt that joining forces with a hated Forsaken was a poor idea, though he had not been able to determine how to extricate himself from the situation. Though he believes that he is a surpassingly competent necromancer, the truth is the Lich King, dimly aware of a remote threat, granted Mael a small amount of power to combat Blarus’ plans.\r\nHis magic allows him to animate minor undead creatures — zombies and skeletons — that did routine work around Gaval Moch but were useless in combat. They performed routine maintenance, repairing the doors and strengthening the walls of Gaval Moch. He also convinced (making liberal use of the Command Undead spell) a local [[ghost|specter]] to join him, and the creature serves him unquestioningly. When a roving [[ogre]] band attacked Gaval Moch, hoping to use the ruins for its own purposes, Blarus’s forces drove the ogres away and Mael Shelub attempted to reanimate the corpses of the ogre dead to replace the acolytes lost in the attack. He knew the possibility was remote since ogres, being giants, were extremely difficult to resurrect. Much to his surprise, they rose from the ground.\r\nWhen a group of heroes invaded Gaval Moch in order to destroy Blarus's plans, Mael leapt at the chance to take command. He offered to join forces with the heroes and once they had served their purpose, turned on them. However, he was wounded in the ensuing battle; avoiding death by teleporting away. Some time later, Mael Shelub’s twenty children came looking for their father... \r\nThe creature is currently found operating in Lordaeron. His alignment is towards chaotic evil and he is most certainly not to be trusted.",},
			["Maer-thiss"] = { content = "'''Maer-thiss''' is a [[blood elf]].",},
			["Maestra's Post"] = { content = "'''Maestra's Post''' is located in western [[Ashenvale]], south of [[the Ruins of Ordil'Aran]] and northwest of [[Astranaar]]. It is a small camp consisting of a tower and a large [[night elven]] building. It is also home to several quest givers, including [[Ashenvale]]'s only population of [[human]]s - [[Feero Ironhand]] and [[Delgren the Purifier]].\r\nDue to the low level of the NPCs here, Horde players often come to spawncamp [[Feero Ironhand]] and the other two with him.",},
			["Maeva's Mystical Apparel"] = { content = "Located in [[The Mystic Ward]] of [[Ironforge]]\r\n==NPCs located here==\r\n*Maeva Snowbraid - Ground Floor\r\n*Ingrys Stonebrow - Upstairs",},
			["Maexxna"] = { content = "==Attacks and Abilities==\r\n*'''''': Cast at the 20 second mark, and then every 40 seconds after that. Sends three players straight back to the NE wall (web wall), encasing them in a cocoon and incapacitating them. This ability sends the player backwards, and they can therefore control the location of their cocoons on the wall. When encased, 650 to 850 Nature damage is done every 2 seconds. The cocoon, which has about 6,000 health, can be destroyed from the outside, some people may be free'd and take 300-700 falling damage when he/she hits the ground. You can PvP Trinket out of this.\r\n*'''''': Cast every 40 seconds incapacitating everyone for 8 seconds, and dealing 1750-2250 Nature damage. This ability cannot be resisted, and the only way to avoid it is to be dead, have [[Flask of Petrification]], have [[Divine Intervention]], or be already incapacitated by Web Wrap. \r\n*'''''': Does 1750-2250 Nature damage in a 15 yard frontal cone.\r\n*'''''': Reduces healing taken by 90% for 30 seconds. This needs to be cleansed immediately, [[Abolish Poison]] being the most effective way to remove it during the Web Spray.\r\n*'''''': At 30% health, Maexxna will enrage, increasing attack speed and dealing significantly more damage.\r\n*'''Spider Spawn''': 8-10 Small spiders are spawned at the 30 second mark, and then every 40 seconds after that. They hit very fast, but only for 100-150 damage, and only have about 4k health. They have to be grouped up and AoE'd before the Web Spray commences.\r\n===Positioning===\r\n*Maexxna should be positioned in the middle of the room with the tank on one side and the rest of the raid behind her. This does two things:\r\n*#Having everyone grouped up will make it easier for the AoE classes to kill the bugs efficiently\r\n*#Allows everyone to keep the backs to the nearby wall. This way, when people are knocked back by the web, they are not knocked back far, and therefore in range of all casters and healers.\r\n*A few Hunters are ideal for Web Wrap duty, standing a bit farther back, closer to the wall, and targeting the players stuck on the wall, killing the web before it kills the victim. \r\n*A Warrior (or Paladin with Consecrate) should be casting Demoralizing Shout to keep the spiders attacking and grouped up on him, instead of the healers/AoE'ers behind Maexxna. \r\n*Druids and Priests in the raid that have the most +heal (try to aim for about 1k) should be used to cast Regrowth, Rejuvenation and Renew just before \"Web Spray\" is incoming. This will provide a total of approxiamtely 1200 healing every tick and will help the Main Tank stay alive.\r\n*The druid with the most +heal can do the regrowth, rejuv, AND abolish poison in that order before the spray with good timing. Regrowth lasts 21seconds, rejuv 12sec, and abolish poison 8seconds. Use other druids to help heal the raid or MT.\r\n*Small spider spawns should be dealt with well before the Web Spray fires, otherwise they may kill players low on health, or do additional damage to the main tank, (which should be avoided). \r\n*It helps to get those players who are \"Web Wrapped\" AND out of \"Line of Sight\" for heals out of the 'Cocoon' before players that are able to be healed as they will die if left there too long without heals. There should be no players still in \"Web Wrap\" when the small spider spawns come. \r\n*Aim to DPS her down about 15%-20% per 40 second cycles. \r\n*Nature Resistance Potions DO help with the longevity of your raid group, whilst learning the process of killing her.\r\n==Timing==\r\nThis fight is on a 40 second cycle, with several mini-phases. Ideal DPS is around 20% per rotation.\r\n* '''1-20''' seconds - Spent putting solid DPS on Maexxna, no damage should be done to anyone but MT, so top everyone off for the next phases. After the first complete cycle, the first 8 seconds will be spent incapacitated via Web Spray.\r\n* '''20-30''' seconds - At 20 seconds, Maexxna will toss 3 random raid members (not MT) onto the nearest wall, and will need ranged DPS to destroy the 3 Web Wraps before the next phase. The victims will need to be topped off once they are released. Generally, they will be hit for about 3 ticks (2250 damage) before being freed. If Maexxna is enraged, do not worry about dpsing the people on the wall, just kill Maexxna.\r\n* '''30-40''' seconds - At 30 seconds, Maexxna will spawn 8-10 small spiders from directly underneath her. Mages/Warlocks need to AoE kill them. Frost Nova'ing is very effective. Make sure the Warlocks do not Hellfire, and instead use Rain of Fire, as they will be vulnerable to dying to the Web Spray.\r\n \r\n* at '''40''' seconds - Everyone in the room will be affected by Web Spray, doing ~2,000 damage and incapacitating them for 8 seconds. The timing resets to 0 seconds.\r\n'''How to get the MT to survive the Web Spray:'''\r\nAt roughly 5 seconds (35 seconds into the cycle) before the Web Spray, healers should put all Heal over Times (and PW:Shield) on the MT and max rank heal to ensure that the tank is at full health before Web Spray is cast. It is ESSENTIAL that the MT has an [[Abolish Poison]] on him before Web Spray is cast. The Necrotic Poison will negate all the HoTs that were put on the tank unless it is cleansed off.\r\nIf the MT is fully buffed, and receives the appropriate, timely heals and cleanse, then he should survive the 8 seconds of Web Spray without dying. This forces the MT to generally be the best geared Warrior in the raid, with a very high health total and gear equivalent to full Wrath equipment.\r\nDuring Maexxnas Enrage, have the warrior shield wall for the web wrap. If you need to go into a second enraged web wrap, I recommend the warrior blowing [[Last Stand]] and [[Lifegiving Gem]]. It's also a good idea for the warrior to pop a [[Greater Stoneshield Potion]] about halfway through the fight. It should last for the rest of the encounter. Make certain Demoralizing Shout and some type of melee slow (Thunderfury or Thunderclap) is on Maexxna at all times.\r\n===Main Phase===\r\n*Amplify Magic (with Magic Attunement) on MT Helps but is NOT a must, Amplify magic alone should be enough.\r\n*If you have mages who can time it, the use of Frost Nova immediately as the spiders spawn will hold them under Maexxna. Three benefits of this are 1) Additional damage dealt to Maexxna with the AoE's, 2) Less damage dealt to the Raid group resulting in less cross raid healing needed and 3) Less chance of someone having low health and dying from the Web spray. Usually 5 mages on AOE duties is enough.\r\n===Web Wrap===\r\n*There is a bug that causes people encased in the web spray to be out of healers line of sight. This tends to happen most between 8 and 10 o'clock. Having two priests and a druid put a shield/rejuv/and renew on the wrapped people at 8 and 10 oclock before they get encased gives the DPS enough time to dps down the cacoons.\r\n*The most efficient way of dealing with Web Wraps is assigning 2 range DPS on each cocoon: closest to the entrance, the middle one and the furthest. If it is possible, consider to have 3 people on the nearest cocoon due to the healing bug.\r\n===Web Spray===\r\n*A Nature's Swiftness/Lay on Hands rotation may also be set up to have at least one instant heal up for the end of each Web Spray. \r\n*Alternatively, have two druids cast rejuvenation and regrowth on the MT right before the Web Spray, and then have the druids swiftmend as soon as they are free - this will consume both HoT's for instant heals, and since it is on a 15 second cooldown, a rotation will not need to be set up.\r\n*8 piece stormrage will ensure that rejuv lasts long enough for swiftmend, as sometimes the druids can mess up the timing and the rejuv may not last long enough for swiftmend after the webspray. \r\n*Shamans with [[Shaman_Talents|Healing Way]] should try to have it stacked 3 times on the tank before the Spray, to maximize the NS heal.\r\n*Have a druid set to pre-emptively cast Abolish Poison on the MT immediately before the Web Spray, and having a Poison-Cleansing Totem down won't hurt either.\r\n*Make sure an abolish poison is on the Main Tank five seconds before the web spray, as having the main tank poisoned just when people are casting their big heals to keep him topped off is not a nice sight. Don't forget to abolish poison the Main Tank .5 seconds before the webspray. Have a paladin or shaman ready to spam cleanse on the main tank when he gets out of the webspray, as being poisoned right as big heals arrive tends to lead to wipes.\r\n===Enrage===\r\n*Maexxna will often kill the tank during the Web Spray if she lands a crit during the Enrage, the MT should Last Stand/Lifegiving Gem/Shield Wall/etc. to stay alive during that phase. Usually for the first Web Spray after Enrage Shield Wall is required. For the second Web Spray have a healer with SS or Divine Shield ready. Shamans with Reincarnation also do.\r\n*Her enrage can be treated like that of [[Princess Huhuran|Huhuran]], in that you can control when it comes. The fight is on a 40 second rotation, and therefore, halfway through a rotation when she is around 50%, Warlocks can cast [[Curse of Doom]]. She should be taken down to 30%, just before the Enrage, until the end of the next rotation, so you can start the enrage with multiple 4k damage procs. \r\n*It has been witnessed that with surgical timing Rogues (using Vanish) and Mages (with Iceblock) can avoid the Web Spray and continue to DPS her down during the final Web Spray when they would normally be immobilised. Also, since a Web Wrap takes a half second to be removed after it's been DPS'd down, a player can avoid Web Spray if timed correctly.\r\n*It's very important for the tank to spam Shield Block and healers should heal the MT non-stop during the enrage phase between the Web Sprays. There have been cases when the boss deals 10k+ damage in 2 seconds.",},
			["Mag'hari Procession"] = { content = "The '''Mag'hari Procession''' is a small camp near [[Sunspring Post]] in [[Nagrand]]. This procession was apparently intended to lay a dead farseer to rest at the [[Ancestral Grounds]], when they were ambushed by the [[Murkblood]] [[Broken]] that sacked [[Sunspring Post]]. The camp is populated by farseers, and a level 70 elite named [[Saurfang the Younger]].",},
			["Mag'har (faction)"] = { content = "The '''Mag'har''' are a faction of [[orc]]s that had escaped the corruption of the [[Horde]].\r\n==History==\r\nAt some point, apparently prior to the Blood Pact with [[Mannoroth]], a virulent plague known as the \"[[red pox]]\" spread throughout the Horde, and Geyah established a quarantine village in [[Nagrand]], homeland of the [[Frostwolf clan]]. For reasons unclear, the orcs managed to avoid the corruption that plagued even their parents and the rest of the world. The orcs, and Nagrand, became known as \"mag'har\" - which in [[Orcish]] means, literally, \"uncorrupted\". They eventually recovered and constructed the stronghold of [[Garadar]].\r\nThe orcs of Mag'har have never been corrupted by either Mannoroth or [[Magtheridon]] and thus remained untouched by the bloodlust. Unlike their former clanmates who live in the ruins of their once-mighty holds, the Mag'har are made up of members of different orc clans who escaped corruption. The current leader of the Mag'har, venerable [[Greatmother Geyah]], is an old and wise orc, yet she has recently fallen extremely ill. [[Garrosh Hellscream]], son of the mighty [[Grom Hellscream]], serves as the Mag'har's military chief, aided by [[Jorin Deadeye]], son of the venerable chieftain of the [[Bleeding Hollow]] clan, [[Kilrogg Deadeye]]. [[Saurfang the Younger]] is also mag'har. \r\n==Architecture==\r\nThe architecture of the Mag'har seems to be based off the buildings from [[Warcraft: Orcs & Humans]]. This suggests that during the [[First War]], orcs used similar building types to those back at home on Draenor. However, over time their buildings become more and more \"warlike\" and nomadic. Those back on Draenor/Outland never changed their building style.\r\n==[[Reputation]]==\r\nAfter completing the quest A Spirit Guide in [[Hellfire Peninsula]], [[Horde]] characters become with the '''Mag'har''' and are able to interact with them. (Before completing this quest, they are with them.)\r\nAll repeatable quests and mobs will give reputation all the way to exalted.\r\nCharacters trying to simultaneously earn reputation with the Mag'har and the [[Consortium]] may want to focus on killing Ogres in Nagrand, which award 10 Mag'har reputation per kill, and saving the [[Obsidian Warbeads]] for [[Consortium]] turn-ins, which are good for [[Consortium]] reputation from Friendly through Exalted.\r\nCharacters trying to simultaneously earn reputation with the Mag'har and the [[Aldor]] may want to focus on killing Orcs at [[Kil'sorrow Fortress]] in southeastern [[Nagrand]] as they drop [[Mark of Kil'Jaeden|Marks of Kil'Jaeden]] in addition to awarding 10 Mag'har reputation per kill.\r\n===Questing===\r\nQuests for the Mag'har begin in [[Hellfire Peninsula]] with the quest The Assassin from [[Thrallmar]]. This quest will lead you to a small Mag'har outpost north of [[Hellfire Citadel]]. Once in [[Nagrand]], players will find the main Mag'har city, [[Garadar]]. The city holds most of the remaining quests that will reward Mag'har reputation.\r\nNote: To talk to most of the NPCs in Garadar, you must have completed the quest chain starting with The Assassin up until the quest A Spirit Guide. Alternately you can do the Garadar quest The Impotent Leader. The Garadar flight master belongs to the [[Thrallmar]] faction, so you can always talk to him.\r\n===Repeatable Quest===\r\nYou can turn in 10 [[Obsidian Warbeads]] in [[Garadar]] for 500 Mag'har reputation. The best Place to find [[Obsidian Warbeads]] is located in the north and south caves in the Halaa valley.\r\nFor information regarding Obsidian Warbeads drop rates, check out \r\nBe aware that the [[Obsidian Warbeads]] are also used for [[Consortium]] reputation, so think carefully on where you want reputation before handing them in.\r\n===Mobs===\r\nKilling any [[ogre]] and most [[murkblood]] mobs will yield 10 Mag'har reputation, Murkblood Scavenger mobs only give 2 reputation.\r\n==Rewards==\r\n==Quests (13,220 Reputation)== \r\n* A Debilitating Sickness (500 reputation)\r\n** Administering the Salve (500 reputation)\r\n* Finding the Survivors (700 reputation)\r\n* Missing Mag'hari Procession\r\n** War on the Warmaul (500 reputation)\r\n** Cho'war the Pillager (700 reputation)\r\n* Proving Your Strength (500 reputation)\r\n* The Impotent Leader (500 reputation)\r\n** Don't Kill the Fat One (1000 reputation)\r\n** Success! (20 reputation)\r\n** Because Kilrath is a Coward (500 reputation)\r\n** Message in a Battle (500 reputation)\r\n** An Audacious Advance (700 reputation)\r\n*** Diplomatic Measures (300 reputation)\r\n* Message to Garadar (700 reputation)\r\n* The Missing War Party (50 reputation)\r\n** Once Were Warriors (500 reputation)\r\n** He Will Walk The Earth... (150 reputation)\r\n* Wanted: Giselda the Crone (500 reputation)\r\n* Wanted: Zorbo the Advisor (500 reputation)\r\n** Wanted: Durn the Hungerer (700 reputation)\r\n* Standards and Practices (500 reputation)\r\n** Bleeding Hollow Supply Crates (500 reputation)\r\n* Murkblood Invaders (500 reputation)\r\n* Vile Idolatry (500 reputation)\r\n* Murkblood Leaders... (500 reputation)\r\n* The Totem of Kar'dash (Horde) (700 reputation)\r\n==[[Quest:Hero of the Mag'har|Hero of the Mag'har]]==\r\nThis chain becomes available when you have completed all the Mag'har quests, including the Blademaster (series starting with Armaments for Deception after Diplomatic Measures from [[Lantresor of the Blade]]), Demon Hunter (the series starting with Survey the Land from [[Altruis the Sufferer]]), and the Sunspring Escort quest called the The Totem of Kar'dash, and have reached level 66.",},
			["Mag'har Grounds"] = { content = "'''Mag'har Grounds''' is located in northwestern [[Hellfire Peninsula]]. It is a cresting plateau containing a simple [[Mag'har]] village. The [[Mag'har Post]] looms in a pass nearby.",},
			["Mag'har Post"] = { content = "'''Mag'har Post''' is a fortress outpost of the [[Mag'har]] orcs in [[Hellfire Peninsula]], east of the [[Temple of Telhamat]]. Mag'har Post is led by [[Gorkan Bloodfist]]. Not many know about the existence of this place, and it is full of injured Mag'har orcs.",},
			["Magatha Grimtotem"] = { content = "'''Magatha Grimtotem''' is a level 62 [[quest giver]] located on [[Elder Rise]] in the [[tauren]] city of [[Thunder Bluff]]. She is attended by her guards, [[Cor Grimtotem|Cor]] and [[Gorm Grimtotem]], and by her servant, [[Rahauro]]. She is the elder crone and leader of the mighty [[Grimtotem Clan]].\r\nShe starts the following quests:\r\n* Forsaken Aid\r\n* Arikara\r\n* Magatha's Payment to Jediga\r\nSee [[List of Thunder Bluff NPCs]].\r\n==Biography==\r\nMagatha is the elder crone of the mighty [[Grimtotem Clan]]. Blessed with shamanic powers when she was just a young girl, Magatha has sought power and prestige nearly all her life. She became the matriarch of the Grimtotem clan through an arranged marriage that many suspect she arranged herself, but subsequently lost her mate to an unforeseen climbing accident. Since her mate's death, Magatha has commanded the stern Grimtotem warriors. The Grimtotems believe that Magatha will lead them in eradicating the lesser races from [[Kalimdor]] and retaking the [[tauren]]'s ancestral holdings abroad. Magatha constantly spars with [[Cairne Bloodhoof]] over the direction of the tauren's future and feels that only she is fit to rule her people.\r\nMagatha’s the oldest living Grimtotem and the most powerful shaman of the tribe. She is an elderly tauren female with powerful shoulders and a white muzzle. She hasn’t let age slow her down one bit, and she defends her position with every spark of magic at her command. She’s forging ties with the Forsaken, and thinks they’re the type to understand an unwavering hatred against all other races. It is rumored that she’s planning on killing Bloodhoof, though she’s not nearly strong enough to do so now.\r\nFor reasons known only to herself at this time, Magatha has given more aid to the [[Forsaken]] than any other high-ranking tauren such as Cairne Bloodhoof or [[Hamuul Runetotem]]. This has included arguing on their behalf when the idea of forming an alliance with them was first suggested.([[Quest:Delivery to Magatha]]) Ostensibly she's helped them and continues to work closely with them because she feels the tauren and their ways can help the Forsaken find a path back to being human. Skeptics believe her motives to be much less altruistic. Skeptics also do not trust the Forsaken. It is also implied in the [[Arikara]] quest that the serpent seeks her, not Cairne Bloodhoof as she suggests.",},
			["Mage"] = { content = "The '''mage''' (or '''magician''') is a [[damage (role)|damage-dealing]] spell-[[caster]] that specializes in [[burst damage]] and [[area of effect]] [[spell]]s. Mages are well known for their formidable damage output, as well as their range of [[crowd control]] abilities. Mages are also capable of performing a number of utility roles, from [[Conjure Refreshment|conjuring refreshments]] for their allies to [[teleport]]ing or opening [[Portal]]s to major cities.\r\nMages wear only [[cloth armor]], but compensate for this with a range of armor spells, wreathing themselves in [[Molten Armor|flame]], [[Frost Armor|frost]] or even [[Mage Armor|arcane energies]]. Nonetheless, when fighting melee opponents, mages stay alive by incapacitating attackers and always keeping one step ahead - and well out of reach. Mages are quick and can [[Blink]] away from attackers, deploy a [[Frost Nova]] to freeze whole groups in their tracks or even use [[Invisibility]] to slip into the shadows. Mages are masters of [[kiting]], and can use their enviable range of [[snare]]s and [[crowd control]] abilities to defeat whole groups of opponents without putting a hair out of place.\r\nMages' primary role in groups at lower levels is damage dealing and [[crowd control]] through the use of [[Polymorph]], temporarily changing [[humanoid]]s and [[beast]]s into harmless critters. At end-game levels, mages' impressive damage output is supplemented with useful abilities such as [[Counterspell]] and [[Spellsteal]].\r\nIn [[PvP]], mages deal ranged damage while using snares, stuns and [[Polymorph]] to control enemy players. Mages are the archetypal \"glass cannons\", capable of dealing an immense amount of damage if left uninterrupted, but vulnerable to attack. Mages compensate for this with a range of [[snare]]s, [[stun]]s and [[incapacitation]] effects, and must keep on their toes if they are to survive.\r\nMages can be an extremely fun class to play, with enviable damage output, strong crowd control and some interesting utility spells. Whether blasting foes with [[Dragon's Breath]] or freezing attackers in a [[Ring of Frost]], mages are a powerful presence on the battlefield. Masters of the arcane, mages can use their mental powers to alter the very fabric of reality, turning snarling attackers into harmless sheep or even [[Alter Time|altering time]] itself. Quick of mind and fleet of foot, mages stay one step ahead of their enemies, summoning frost and ice to entrap their assailants, and great fireballs and walls of flame to decimate their foes. Undisputed masters of the very fabric of reality, only the foolish do not fear the coming of a mage.\r\n==Class overview==\r\n''Students gifted with a keen intellect and unwavering discipline may walk the path of the mage. The arcane magic available to magi is both great and dangerous, and thus is revealed only to the most devoted practitioners. To avoid interference with their spellcasting, magi wear only cloth armor, but arcane shields and enchantments give them additional protection. To keep enemies at bay, magi can summon bursts of fire to incinerate distant targets and cause entire areas to erupt, setting groups of foes ablaze. Masters of ice can command blizzards that tear into flesh and limit movement. Should enemies manage to survive this assault, the mage can shrink them into harmless sheep in the blink of an eye.''\r\n''Powerful magi can even generate enhancements and portals, assisting allies by sharpening their minds and transporting them instantly across the world.''\r\n===Creation screen description===\r\n''Magi are wizards of immense knowledge and skill. Their obvious physical frailty is deceptive, for they can call upon the cosmic energies of the Twisting Nether. Rarely do magi engage in melee combat. Instead, they prefer to attack from a distance, hurling powerful bolts of frost and flame at their unsuspecting enemies.''\r\n''Mages are the iconic magic-users of Azeroth who learn their craft through intense research and study. They make up for their light armor with a potent array of offensive and defensive spells.''\r\n===Classic guide===\r\n''Mages are spellcasting savants, flinging fire, frost, and arcane sorcery at their foes from afar.''\r\n==Background==\r\nEarly [[kaldorei]] civilization was defined by direct manipulation of magic drawn from the Well of Eternity to create and sustain their society. Their constant use of the Well attracted attention from [[Sargeras]] and the [[Burning Legion]], who manipulated the [[Highborne]] Queen Azshara into using the Well as a gateway, granting the Legion entry into Azeroth. The Legion's arrival sparked a massive conflict which would later be known as the [[War of the Ancients]]. The war had grave consequences, for even though the combined might of Azeroth's mortal races were victorious, the continent of [[Kalimdor]] was shattered, and a swirling, raging miasma of sea storms flowed into the vacant area where the Well of Eternity used to reside. This [[Great Sundering]] caused the Well's energies to permeate the atmosphere and spread magic all over the world.\r\nThis event convinced the majority of night elves to reject arcane magic and embrace [[Malfurion Stormrage]]'s call for [[druid]]ism. Many of the surviving Highborne could not endure this lifestyle, suffering as they were from withdrawal now that they could no longer draw on the Well's arcane energies. Their leader, [[Dath'Remar Sunstrider]], called the druids cowards for refusing to use the magic he considered their birthright. In spite of Malfurion's warning that any use of magic would be punishable by death, Dath'Remar led his fellow Highborne in revolt, conjuring a giant magical storm in Ashenvale in an attempt to convince the druids to suspend the law. Unwilling to execute so many of their fellow elves, Malfurion and the druids instead exiled the Highborne from their lands. Dath'Remar and his followers chose to set sail from Kalimdor, eventually landing in [[Lordaeron]] where they would ultimately found the kingdom of [[Quel'Thalas (kingdom)|Quel'Thalas]] and call themselves [[high elves]]. When their kingdom came under siege by the trolls of [[Zul'Aman]] the high elves agreed to teach one hundred humans the arts of magic in exchange for military aid from the human nation of [[Arathor]]. From these two races, the arcane arts have spread to various races all over Azeroth.\r\n===In Warcraft II===\r\nMages first appeared as a unit of the [[Alliance of Lordaeron]] in ''[[Warcraft II: Tides of Darkness]]''. They were described as such:\r\n''Once students of the [[Conjurer]]s of [[Stormwind (kingdom)|Azeroth]], this new order of Mages have been forced to discover untapped magical forces to command in their war against the ruthless [[Orc]]s. Although masters of their arts, the Conjurers who fell during the [[First War]] were unprepared for the rigors of warfare. Determined to avoid a similar fate, the Mages have undertaken a regimen equally demanding on body and soul, thus dedicating themselves to the command of more aggressive and destructive [[Magic|magiks]]. Whether in their sanctum at the [[Violet Citadel]] in [[Dalaran]] or on the many battlefields of [[Lordaeron]], the Mages are resolute in their efforts to defend the people.''\r\nPut together, the pre-''Warcraft III'' games and novels painted a fairly specific picture of the place of mages in human society. ''Warcraft I'' showed that [[Stormwind (kingdom)|Stormwind]] had its own secretive conjurer order and that the kingdom had a special relationship with them, even promoting them to advisors of the [[Court of Stormwind|court]]. ''[[The Last Guardian]]'' confirmed that this southern mage group was officially separated from Dalaran to the point of being referred to as [[Hedge wizard|\"hedge wizards\"]], though some of them still belonged to the [[Council of Tirisfal]]. Speaking of Dalaran, the ''Warcraft II'' manual hinted that most Lordaeron mages ultimately answered to the [[Violet Citadel]], with ''[[Day of the Dragon]]'' showing that the different monarchies of Lordaeron seemed to be wary of the [[Kirin Tor]] [[wizard]]s and their politics, and to have no mage advisors of their own, as none were there to protect the various kings during the events of the [[Alterac crisis]]. How much of this remains canonical is unclear.\r\nOf note is that in the aftermath of the [[Second War]], an [[Alterac (kingdom)|Alteraci]] mage stole the [[Book of Medivh]] from [[Stormwind City]] and exchanged it to [[Ner'zhul]] for military aid against [[Lordaeron (kingdom)|Lordaeron]] and [[Stromgarde (kingdom)|Stromgarde]] forces, showing that some mages were eventually more loyal to their nation than to the Violet Citadel.\r\n==Organizations==\r\n \r\n*[[Kirin Tor]]\r\n**[[Council of Six]]\r\n**[[Violet Eye]]\r\n*[[Tirisgarde]]\r\n*[[Magisters]]\r\n*[[Moon Guard]]\r\n*[[Academy of Arcane Arts and Sciences]]\r\n*[[Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences]]\r\n''Former organizations''\r\n*[[Council of Tirisfal]]\r\n*[[Mages' Guild]]\r\n*[[Sorcerers' League]]\r\n*[[Kelani Magi]]\r\n*[[Mennar Academy]]\r\n*[[Zann'esu clan]]\r\n==Races==\r\nThe mage class can be played by the following races:\r\nMage Beneficial Racial Abilities:\r\n[[Draenei]]\r\n* [[Heroic Presence]] is one of the most important mage beneficial racial abilities for PvE encounters as it increases the [[spell hit]] by 1%.\r\n* [[Gift of the Naaru]] is a minor heal.\r\n[[Dwarf]]\r\n* [[Stoneform]] is a minor defence trait which can be used in PvP and PvE.\r\n[[Gnome]]\r\n* [[Expansive Mind]] is one of the most important mage beneficial racial abilities as it increases mana by 5%. Note that it increases mana pool but not [[Intellect]], [[spell power]] or [[spell critical]].\r\n* [[Escape Artist]] removes snares and speed reduction effects. Usable to PvP and certain PvE encounters. (Note: does not remove stun effects).\r\n[[Human]]\r\n* [[Every Man for Himself]] is another beneficial trait enabling players to remove all incapacitating effects on the character (Slow, stun, fear, immobilize effects)\r\n* [[Diplomacy]] grants a 10% extra reputation gains for every faction.\r\n[[Night Elf]]\r\n* [[Quickness]] mainly useful in PvP, gives a slight advantage over receiving damage.\r\n* [[Shadowmeld]] acts as a minor and temporary focus distraction from PvE encounters. However, the player is still vulnerable (in contrast with [[Ice Block]]), does not reduce threat (unlike [[Invisibility]] but it removes Combat status (similar to [[Vanish]]). Shadowmeld can also be used when an enemy is casting a spell on the mage, forcing the enemy to lose their target and acting as an interrupt.\r\n[[Worgen]]\r\n* [[Viciousness]] is another of the most mage beneficial racial abilities as it increases [[spell critical strike]] by 1%\r\n* [[Darkflight]] enables the player to move faster. Usable in both PvP and PvE encounters.\r\n[[Blood Elf]]\r\n* [[Arcane Torrent]] has similarities with [[Counterspell]] and restores a percentage of mana. Due to its limit in [[AoE]] range, it has limited use in Boss PvE encounters and is half effective on PvP.\r\n* [[Arcane Acuity]] increases spell critical strike rate by 1%, therefore is handy in both PvP and PvE, especially considering higher possibility of an instant cast [[Pyroblast]] of the [[Mage talents|Fire specialization]].\r\n[[Goblin]]\r\n* [[Rocket Barrage]] is a small damage ability.\r\n* [[Rocket Jump]] similar to [[Blink]] for use in PvE and PvP.\r\n* [[Time is Money]] is a slight reduction in casting time.\r\n[[Orc]]\r\n* [[Blood Fury]] gives an increase in spell power whenever activated.\r\n* [[Hardiness]] a reduction in the total time of stun effects.\r\n[[Troll]]\r\n* [[Berserking]] has similar effects to [[Time Warp]], has 10 seconds duration, 3 minutes cooldown but the most important is that unlike [[Bloodlust]] does not place a 10 minutes debuff thus making it an extremely beneficial racial ability.\r\n* [[Regeneration (racial)]] is useful as an additional health regeneration effect, especially beneficial on long encounters.\r\n* [[Da Voodoo Shuffle]] has use in both PvE and PvP.\r\n[[Undead]]\r\n* [[Will of the Forsaken]] is usable in all cases in PvP and PvE when losing control of character (does not include slow or immobilize effects)\r\nThe above list includes only the abilities that interact directly with the mage abilities, playstyle and needs over specific situations.\r\nOther traits are available and are usable as to what a player wishes to do with the character.\r\n==Overview==\r\nThe mage is a pure DPS class, with all mage [[specialization]]s focusing on dealing damage, and as such is capable of enviable damage output, whether launching an [[Ice Lance]] against a [[Shatter|frozen]] target or invoking a [[Blizzard]] to decimate whole groups of opponents. However, mages also have an extremely diverse selection of [[crowd control]] and [[utility]] abilities, making them far more than just damage-dealers. From [[Spellsteal]] and [[Slow Fall (ability)]] to [[Ice Block]] and [[Mirror Image]], mages have some fun and interesting spells at their disposal.\r\n===Spells===\r\n, a [[female]] [[gnome]] mage.]] \r\n''For a full list, see [[Mage abilities]]''\r\nMages have a wide variety of spells which fall into three schools of magic: [[arcane]], [[fire]] and [[frost]]. All spell schools include damage spells. Arcane includes some crowd control and utility, and most Frost spells provide a movement-slow effect supplementing their damage.\r\n* '''Fire''' spells are primarily damage-dealing spells, including direct single-target damage and [[area of effect]] damage. Many Fire spells include [[damage over time]] effects. Fire mages trust heavily on RNG in raid situations.\r\n* '''Frost''' spells are primarily single-target and [[area of effect]] damage-dealing spells, but with more emphasis on chilling effects. Nearly every frost spell has a chill or freeze effect that fully or partially immobilizes an enemy. This includes freezing it in place (called a [[root]]) or slowing its movement speed (called a [[snare]]). Frost specialized mages can further improve these chilling effects and increase frost damage output to respectable levels. Frost spells help the mage use [[kiting]] as a combat tactic.\r\n* '''Arcane''' spells include single-target damage spells and utility. Arcane spells allow the mage to remove [[curse]]s, provide [[crowd control]], absorb damage, [[teleport]] himself or others to major capital cities, [[Slow Fall (ability)]], [[Counterspell]], buff players' [[spell power]] and mana pools, save mana for later use in the form of mana gems, [[conjure]] food for himself or others, and provide many other conveniences.\r\nMages' in-combat mana regeneration is provided by abilities such as [[Nether Attunement]] and [[Evocation]], and the use of low-mana casting cycles (such as [[Scorch]] for fire mages or heavy use of [[Arcane Missiles]] for arcane mages).\r\n===Gear===\r\nA mage can only wear [[cloth armor]].\r\nA mage is able to wield [[staff|staves]], [[wand]]s, [[dagger]]s, [[one-handed]] [[sword]]s, and can use items with the slot \"[[Held in Off-hand]]\" if using a dagger or one-handed sword in the [[main hand]]. Wands go in the main hand slot and will continue to shoot once manually started.\r\n===Attributes===\r\nAs a spell-caster, a mage's primary stat is [[intellect]], which directly increases the mage's [[spell power]] and [[spell critical strike]] chance. Secondary stats beneficial to mages are [[spell hit|hit rating]] (until reaching the hit cap), [[Spell critical strike|critical strike rating]], [[haste rating]] and [[mastery|mastery rating]]. [[Stamina]] also benefits mages, but should not be focused on at the expense of other stats unless gearing for PvP. [[Agility]], [[strength]], [[spirit]], and the other secondary stats should be ignored completely.\r\n==Specializations==\r\n''For a full list of specialization abilities, see [[Mage abilities|Mage abilities]]''\r\nMages can choose one of three [[specialization]]s, gaining access to unique abilities and bonuses. Mage specializations focus on enhancing individual schools of magic – quick, aggressive Fire spells; efficient, controlling Frost spells and punishing Arcane spells.\r\n===Arcane===\r\n'''''Manipulates the arcane, destroying enemies with overwhelming power.'''''\r\nArcane mages' damage focuses on [[Arcane Blast]] and [[Arcane Missiles]]. The Arcane specialization includes [[Slow]], a powerful instant single-target slowing effect, and [[Arcane Barrage]], an instant-damage ranged attack. Arcane mages can provide substantial burst damage with [[Arcane Power]] and [[Presence of Mind]]. Leveling as an arcane mage was once very difficult, but with the signature arcane spells ([[Arcane Barrage]], [[Arcane Missiles]], and [[Arcane Blast]]) learned much earlier it is now a far more feasible leveling build.\r\n''Mages of the arcane are diviners of secrets, balancing the ebb and flow of incredible mystic energies. Unparalleled skill is required to manipulate the volatile forces of the universe. These practitioners push their magical knowledge to its very limits—often to the brink of their own exhaustion, and at great risk to the world around them. Those who master this craft are capable of releasing a barrage of unrelenting power upon their enemies, drawing upon replenishing energies to maintain their assault for as long as the battle demands.''\r\n===Fire===\r\n'''''Ignites enemies with balls of fire and combustive flames.'''''\r\nFire mages' damage output is oriented around [[Pyroblast]] procs; whenever a Fire mage deals two critical strikes in a row, their next [[Pyroblast]] spell is instant. Fire is very strong in AoE where [[Combustion]], [[Pyroblast]], and [[Living Bomb]] can be spread via [[Inferno Blast]]. Fights in which players are forced to move frequently can also benefit Fire mages, as [[Scorch]] and instant Pyroblasts can fill the movement time which Arcane mages can only use [[Arcane Barrage]]. The Fire spec provides few survival tools. This has historically made Fire a good choice for high-end raiders who seek to maximize damage output, but poor in PvP due to [[Arena]]'s survival requirements.\r\n''While any worthy mage is an unparalleled expert in the use of magic and heavily dedicated to their craft, those who master the forces of fire tend to be a little more audacious than their peers. If a threat stands before them, the answer is always to neutralize it in a glorious blaze. A lifetime dedicated to the study of fiery forces only fuels their pyromania, and these mages take pride—even pleasure—in igniting their enemies in wild bursts of flame. Mistake their affinity for watching things burn as a lack of self-control at your own peril.''\r\n===Frost===\r\n'''''Freezes enemies in their tracks and shatters them with Frost magic.'''''\r\nFrost mages specialize in crowd control and snaring foes with their various chills, allowing for powerful [[kiting]], and providing good AoE capability. Frost mages also learn [[Summon Water Elemental]], gaining a pet which has a Freeze ability similar to [[Frost Nova]]. Frost's AoE makes it the spec best suited to five-player dungeons. \r\n''Frost mages stand apart from their colleagues, in that their chosen school of magic focuses on maintaining supreme control over the capabilities of their enemies. Mages who command frost perform chilling displays on the battlefield, rendering foes immobile as they bombard them with ice. Often, the blade never reaches the caster before the bitter cold takes hold. The frost mage exudes frigid power as icicles form around them, foreshadowing the wintry demise of those who stand opposed on the field of battle.''\r\n==Endgame expectations==\r\nIn a group or raid environment, mages are usually tasked with ranged [[DPS]], [[AoE]], [[Counterspell]], [[Spellsteal]], [[crowd control]] and finally [[Ritual of Refreshment|providing food]].\r\nWith the introduction of [[patch 1.11]], mages enjoyed a high degree of flexibility in the endgame. Previous to patch 1.11, it was expected that most mages would spend at least 11 talent points in the arcane tree for [[Evocation]], as it is a quite powerful mana-regenerative spell. It was given free without the use of talent points. New changes to all three trees also made investing points into both the fire and the frost trees much more viable. This still holds true with the release of [[Burning Crusade]]. It should be mentioned that a build predominantly using the fire tree will usually contribute greater DPS in multiple-target encounters; those using a predominantly arcane tree will usually contribute greater DPS in single-target encounters; and finally, those using a predominantly frost tree will contribute a fair amount of control.\r\nThe endgame mage also acts as a utility class, providing drink, food, buffs and portals. Originally, when it came to providing drink and food, mages were by some considered equal to \"vending machines\" due to their unique ability to create food and drink and provide them with no cost except mana and time. In [[Wrath of the Lich King]], Refreshment Tables may also be created at level 80 at the cost of five [[Arcane Powder]]; the table lasts for three minutes or 50 charges of [[Conjured Mana Strudel]], whichever comes first. It is expected that a mage provides his party or raid with food and drink for free. A second (or third) table can sometimes be called for while mustering players at the beginning of a raid if the first expires before everyone has received their strudel.\r\n==PvP==\r\nPvP-wise, mages are considered \"glass cannons\" - a design philosophy which gives mages generous burst damage at the cost of generally low health and armor values. Aided by talents such as [[Presence of Mind]] and [[Arcane Power]], they are one of the classes with the potential for dealing out the greatest amount of damage in the shortest amount of time. In group PvP, mages will stay back and focus on crowd control with [[Polymorph]] and pick off targets from range. Depending on the Battleground and the situation, mages typically AoE to prevent node captures or nuke flag carriers as fast as possible. In solo PvP, a skilled frost mage is a formidable opponent. Fire mages are in PVP well known for their burst damage, and arcane mages are known as venerable supporters.\r\n==See also==\r\nGame mechanics:\r\n* [[Mage theorycraft]]\r\n* [[Spell power coefficients]]\r\n* [[Mages as tanks]]\r\nLore:\r\n* [[Arcane]]\r\n* [[Magic schools (RPG)|The eight categories of arcane and divine magic (often used by mages)]]\r\n* [[List of mages]]\r\n* [[Wizard]]\r\n* [[Sorcerer]]",},
			["Mageroyal"] = { content = "'''Mageroyal''' is a [[Herb]] that can be gathered by [[Herbalist]]s, or bought in limited quantities from selected [[Vendors]]. Requires 50 Herbalism to gather. Mageroyal seems to be edible as it is used in the recipe for [[Delicious Chocolate Cake]].\r\n==Source==\r\nMageroyal can be found on plains in low-level zones. Sometimes, you may find [[Swiftthistle]] while picking Mageroyal. It can also be found in limited supply at [[vendor]]s. It is also a quest reward from the Alliance Alchemy quest [[Quest:Elixirs for the Bladeleafs|Elixirs for the Bladeleafs]].\r\n===Pickable Zones===\r\n*[[The Barrens]] 27.4%\r\n*[[Westfall]] 9.9%\r\n*[[Silverpine Forest]] 9.2%\r\n*[[Darkshore]] 9.1%\r\n*[[Loch Modan]] 8.2%\r\n*[[Wetlands]] 8.1%\r\n*[[Redridge Mountains]] 7.3%\r\n*[[Duskwood]] 4.6%\r\n*[[Stonetalon Mountains]] 3.1%\r\n*[[Ashenvale]] 2.9%\r\n*[[Teldrassil]] 2.8%\r\n*[[Hillsbrad Foothills]] 2.6%\r\n*[[Wailing Caverns]] 2.2%\r\n*[[Durotar]] 1.5%\r\n*[[Ghostlands]] 1.0%\r\n==Mageroyal as an Ingredient==\r\nMageroyal is used in the following recipes:\r\n===[[Alchemy]]===\r\n* Minor Mana Potion\r\n* Minor Rejuvenation Potion\r\n* Elixir of Wisdom\r\n* Minor Magic Resistance Potion\r\n* Lesser Mana Potion\r\n===[[Cooking]]===\r\n* Delicious Chocolate Cake\r\n===[[Inscription]]===\r\n* Dusky Pigment\r\n* Verdant Pigment",},
			["Mages' Guild"] = { content = "The '''Mages' Union''' (or '''Mages' Guild''') was one of three factions within Dalaran, including the [[Kirin Tor]] and [[Sorcerer's League]], which tried to hold back the forces of the Scourge, during [[Arthas]]' siege of the [[Third War]].",},
			["Mages"] = { content = "#REDIRECT [[Mage]]", redirect = "Mage",},
			["Mageweave"] = { content = "#REDIRECT [[Mageweave Cloth]]", redirect = "Mageweave Cloth",},
			["Mageweave Bandage"] = { content = "==Source==\r\nThe '''Mageweave Bandage''' is crafted by players with a [[First Aid]] skill of at least 210.\r\nThe components are:\r\n*1 [[Mageweave Cloth]]\r\nThe skill is taught by [[Manual: Mageweave Bandage]], a vendor-sold book sold for 50 silver by:\r\n* [[Balai Lok'Wein]] at [[Brackenwall Village]] in [[Dustwallow Marsh]].\r\n* [[Deneb Walker]] at [[Stromgarde]] in the [[Arathi Highlands]]\r\n==Mageweave Bandage as a quest objective==\r\nDuring the [[Gates of Ahn'Qiraj]] one-time event, the following quests were available:\r\n* The Horde Needs Mageweave Bandages!\r\n* The Horde Needs More Mageweave Bandages!",},
			["Mageweave Cloth"] = { content = "A fine [[cloth]] woven with magic.\r\n==Source==\r\n'''Mageweave Cloth''' can be found as a [[drop]] from any number of mid- to high-level [[humanoid]]s.\r\n==Mageweave Cloth as an ingredient==\r\n'''Mageweave Cloth''' is used in the following recipes:\r\n===[[Blacksmithing]]===\r\n* Heavy Mithril Gauntlet\r\n* Ornate Mithril Gloves\r\n* Mithril Coif\r\n* Dazzling Mithril Rapier\r\n===[[Engineering]]===\r\n* Unstable Trigger\r\n* Mechanical Repair Kit\r\n* Ez-Thro Dynamite II\r\n* Goblin Sapper Charge\r\n* Gnomish Mind Control Cap\r\n===[[Leatherworking]]===\r\n* Nightscape Shoulders\r\n===[[First Aid]]===\r\n* Mageweave Bandage\r\n* Heavy Mageweave Bandage\r\n===[[Tailoring]]===\r\n* Bolt of Mageweave\r\n==Mageweave Cloth as a quest item==\r\n'''Mageweave Cloth''' is needed for the following quests:\r\n Hand in 60 Mageweave Cloth to a faction quartermaster to gain [[Reputation|Reputation]]\r\n==Places to farm==\r\nThe best place to farm Mageweave is the Deadwood Furbolgs in southern Felwood, they drop 1-4 mageweave off of 33% of the furbolg kills, as well as nice green drops without a lot of junk. The furbolgs are normal, rather than elite, so die much faster, and respawn very quickly. This is far superior to all other locations, and generates Timbermaw rep at the same time. Unfortunately, this is also well known, so finding 70 mages or warlocks mass farming there is common, and can make it difficult for lower levels to get to kill anything.\r\n*'''Lvl. 30-39:''' [[Hillsbrad Foothills]]: [[Syndicate|Syndicate thieves]], fairly low droprate.\r\n*'''Lvl. 32-42:''' [[Scarlet Monastery]] mobs drop Mageweave at rate of roughly 5%. (Good place to farm silk, though.)\r\n*'''Lvl. 32-38:''' [[Boulderfist]] ogres in [[Arathi Highlands]], droprate of roughly 10%.\r\n*'''Lvl. 40+:''' [[The Hinterlands]], [[Quel'Danil Lodge]] is full of [[Elf|elves]] apart from some quest around there, you can easily farm Mageweave. This is only applicable to the Horde; Alliance can go further east to fight [[Witherbark]] and [[Vilebranch]] trolls. ''Note:'' The Vilebranch trolls are non-elite since patch 2.3 and have a very high drop rate for Mageweave.\r\n*'''Lvl. 35-40:''' [[Stranglethorn Vale]] The Venture Co. Shredders drop mageweave fairly reliably.\r\n*'''Lvl. 44-47:''' [[Dunemaul|Dunemaul Ogres]] in the mid- to southwest of [[Tanaris]]. [[Wastewander]] bandits East of [[Gadgetzan]]. Also, the pirate camps on the southern coastal area occasionally drop mageweave.\r\n*'''Lvl. 47-50:''' Deadwood furbolgs in southern [[Felwood]] drop mageweave at a very good rate better than 100%.\r\n*'''Lvl 48+''' Horde can farm [[Garrison Armory]] and even [[Nethergarde Keep]] itself in [[Blasted Lands]]\r\n*'''If you have a high level [[Zul'Farrak]] is also a great place to farm mageweave.",},
			["Mage (Warcraft II)"] = { content = "==Statistics of a [[mage]] from Warcraft II==\r\n* Abilities\r\n** Lightning \r\n** Fireball (line damage)\r\n** Slow (lowers target's movement speed and attack rate)\r\n** Polymorph (permanently turns target into a defenseless critter)\r\n** Invisiblity (makes target temporarily invisible until it either attacks or casts a spell)\r\n** Flame Shield (AoE damage around target unit)\r\n** Blizzard (ranged AoE damage)",},
			["Mage abilities"] = { content = "'''Mage abilities''' come in three schools of magic: [[Magic|Arcane]], [[Magic|Fire]], and [[Magic|Frost]], which are usually affected by their [[talent|tree's]] respective [[Mage talents|talents]]. '''Mage spells''' are also usually delineated by their purpose: [[direct damage]], [[area of effect]] damage, and utility. Mages are also the only class with the ability to [[teleport]] themselves or their group members to the variety of the capital cities.\r\nThe spells themselves can be classified quite easily by the school they are in. Most Fire spells will have the purpose of heavily damaging an opponent, while the majority of Frost spells are weaker, but usually with an inherent [[snare]] built in, which allows them a greater modicum of control. Arcane consists of many of the utility spells, while also supporting either of the other trees through the usage of talent trained abilities.\r\n==Talent Spells==\r\nTalent spells are spells or abilities that are acquired from spending talent points in a certain tree. For example Pyroblast is from the Fire tree while Ice Barrier is from the Frost tree. higher ranks of some talent spells can be bought from the trainer while others only have one rank.\r\n====Single-target Damage====\r\n[[Frostbolt]] for ice-based single target damage (and a [[snare]]); [[Fire Blast]] for [[instant]] fire damage (and brief cooldown); [[Fireball]] for a big whopper of fire damage. [[Scorch]] is another fire-based spell which has a short [[Casting Time|casting time]] and does good damage. [[Arcane Missiles]] are channeled over 5 seconds, with one wave of arcane damage fired each second and can be made uninterrupted by normal damage with talents. [[Arcane Blast]], made available in the BC expansion, adds a buff to the caster that decreases Arcane Blast cast time while increasing mana cost, stacking up to 3 times.\r\nWith [[Mage Talents|talents]], [[Pyroblast]] can be acquired. It is basically a slow-casting, huge [[Fireball]] with a large [[DoT]] component.\r\n====Area of effect damage====\r\nThis category of spells includes your first AoE spell: [[Arcane Explosion]], an [[instant]] cast arcane [[Area of Effect|point blank area of effect]]; [[Blizzard]], a [[channel]]ed [[Area of Effect|ground target area of effect]] cold spell; and [[Flamestrike]], a fire-based [[Area of Effect|ground target area of effect]] spell.\r\n[[Blast Wave]] (another [[Mage Talents|talent]] spell) is an [[instant]] cast, [[Area of Effect|point blank area of effect]] fire spell which dazes the enemy. It has a moderate cooldown (45 seconds).\r\n====Snares and roots====\r\n[[Frostbolt]] [[snare]]s the enemy, and [[Frost Nova]] is a [[Area of Effect|point blank area of effect]] [[root]] which also inflicts a small amount of damage.\r\n[[Frost Armor]] (and later, [[Ice Armor]]) gives the [[Mage]] both an armor [[buff]] and a reactive [[debuff]] to enemies that hit the [[Mage]] in melee, along with a small resistance to ice magic. Attackers are [[snare]]d and [[slow]]ed.\r\nMages who go 41 points in to the Arcane tree can get [[Slow (Mage spell)|Slow]], which snares 50% and also reduces casting speed and reduces ranged attack speed by 50%.\r\n====Crowd control====\r\n[[Polymorph]] allows the [[Mage]] to turn a Humanoid, Beast or Critter into a sheep, pig, or turtle (depending on the spell used) for a certain amount of time.\r\n====Damage absorption====\r\n[[Mana Shield]] allows the [[Mage]] to absorb physical and magical damage taken at the cost of mana, at a 2:1 rate (50 damage = 100 mana). A talent can reduce the mana usage.\r\n[[Fire Ward]] absorbs fire damage; [[Frost Ward]] absorbs cold damage.\r\nWith [[Mage Talents|talents]], [[Ice Barrier]] can be acquired. It's an [[instant]] cast shield that protects you from all damage types up to a limit or 1 minute, whichever comes first. It has a short cooldown (30 seconds).\r\n[[Mage Armor]] increases resistances to all schools of magic while also allowing mana regeneration during the [[Five second rule]].\r\n===Utility spells===\r\n[[Slow Fall]] - a \"defensive\" spell of sorts - protects against falling damage, requires a Light Feather to use.\r\n====Intellect buffs====\r\nA very good [[buff]] for the [[Mage]] (and any class that uses mana) is [[intellect]]. Mages have two flavors of these: [[Arcane Intellect]] and the group version, [[Arcane Brilliance]]. Since [[intellect]] affects the rate at which all weapon skills are gained, non-casters might appreciate it too.\r\n====Conjuration====\r\n[[Conjure Mana Stone]] gives you a stone that acts as a free mana potion on a separate [[cooldown]] from your other potions. These stones can not be shared. [[Conjure Food| Food]] and [[Conjure Water| Water]] of varying levels can also be conjured for restoring health and mana, and is an important preparation for reducing downtime for a solo mage or an entire raid.\r\n====Evocation====\r\nThe fastest way to regenerate your mana, [[Evocation]] can refill the majority of your mana bar over the course of its 8 second cast. Be sure not to be at risk of getting hit, since this is a channeled effect.\r\n====[[Teleport|Self]]====\r\nThis includes the [[Teleport|Teleport: <Capital City>]] spells as well as [[Blink]].\r\n====[[Portal (spell)|Portals]]====\r\nCreates a portal that can be clicked to instantly move your group to a friendly city.\r\n==Spells by source==\r\nAll spells not listed here are immediately available at the Mage trainers at the appropriate level. \r\n===Talent spells===\r\n*[[Pyroblast]] - 11 point Fire tree talent for first rank\r\n*[[Blast Wave]] - 21 point Fire tree talent for first rank\r\n*[[Combustion]] - 31 point Fire tree talent\r\n*[[Dragon's Breath]] - 41 point Fire tree talent for first rank\r\n*[[Icy Veins]] - 11 point Frost tree talent\r\n*[[Cold Snap]] - 21 point Frost tree talent\r\n*[[Ice Barrier]] - 31 point Frost tree talent for first rank\r\n*[[Summon Water Elemental]] - 41 point Frost tree talent\r\n*[[Presence of Mind]] - 21 point Arcane tree talent\r\n*[[Arcane Power]] - 31 point Arcane tree talent\r\n*[[Slow (Mage spell)|Slow]] - 41 point Arcane tree talent\r\n===Quests===\r\n*[[Conjure Water|Conjure Water VII]] - Taught by [[Lorekeeper Lydros]] in the [[Dire Maul|Dire Maul (North) Library]] at level 60.\r\n*[[Polymorph|Polymorph: Pig]] - Taught by [[Archmage Xylem]] in [[Azshara]] at level 60.\r\n===Item loot === \r\nAs of Patch 2.0, all of these except [[Polymorph|Polymorph: Turtle]] are learnable from the mage trainers in the major cities, and are otherwise deprecated.\r\n*[[Arcane Brilliance|Tome of Arcane Brilliance]] - Level 60 spell learned from a Tome that drops off of random [[creeps]] in 5 and 10 man level 60 instances and also from [[Onyxia]].\r\n*[[Arcane Brilliance|Tome of Arcane Brilliance 2]] - Level 70 spell learned from a Tome that drops in Outland.\r\n*[[Conjure Food|Tome of Conjure Food VII]] - Level 60 rank obtained from a Tome that drops off of [[Archivist Galford]] in the Scarlet Bastion of [[Stratholme]].\r\n*[[Frost Ward|Tome of Frost Ward V]] - Level 60 rank obtained from a Tome that drops off of random [[creeps]] in 5 and 10 man level 60 instances and also from [[Onyxia]].\r\n*[[Arcane Missiles|Tome of Arcane Missiles VIII]] - Level 60 rank obtained from a Tome that drops off of bosses in the [[Ruins of Ahn'Qiraj]].\r\n*[[Fireball|Tome of Fireball XII]] - Level 60 rank obtained from a Tome that drops off of bosses in the [[Ruins of Ahn'Qiraj]].\r\n*[[Frostbolt|Tome of Frostbolt XI]] - Level 60 rank obtained from a Tome that drops off of bosses in the [[Ruins of Ahn'Qiraj]].\r\n*[[Polymorph|Tome of Polymorph: Turtle]] - Level 60 spell obtained from a Tome that drops off of [[Gahz'ranka]] (the \"fish boss\") in [[Zul'Gurub]].\r\nThese spells are learned from tomes and cannot be learned from a mage trainer:\r\n*[[Conjure Food|Tome of Conjure Food VIII]] - Level 70 spell learned from a Tome that drops in Outland. Restores 7500 health over 30 seconds.\r\n*[[Conjure Water|Tome of Conjure Water IX]] - Level 70 spell learned from a Tome that drops in Outland. Restores 7200 mana over 30 seconds.\r\n===Footnotes===\r\n* = Spell acquired by [[Mage Talents|talents]]. The first level it appears is the minimum required to reach it.\r\n* + Known at character creation.\r\n* @ Spell acquired via a tome or quest instead of at the trainer. See the spell for more information on how to obtain it.\r\n* Many damage spells scale slightly with level after training them.",},
			["Mage Armor"] = { content = "''A spellcaster is comfortable with spells when surrounded by arcane energy that quickly replenishes any magical effort.''\r\n'''Mage Armor''' is a self-only [[buff]] that improves your resistance to all magical schools and allows you to regenerate your mana at 30% your normal regeneration rate when casting. (Without this spell, you do not regenerate mana for 5 seconds after completing any spell. See [[Five second rule]].) Lasts 30 min.\r\n==Tips and tactics==\r\nThis is very handy in groups and on [[raid]]s when you're not being hit, but your ability to keep fighting over a long period of time is important.\r\nUnlike [[Frost Armor]] and [[Ice Armor]], this will not [[snare]] or [[slow]] your attackers, so don't leave this up when running through a dangerous area.\r\nThis armor stacks additively with the Arcane Talent [[Arcane Meditation]] - in other words, if both are active, you will regenerate at 60% of your normal mana regen rate.",},
			["Mage glyphs"] = { content = "#REDIRECT [[Mage abilities]]", redirect = "Mage abilities",},
			["Mage Quarter"] = { content = "The '''Mage Quarter''' (also called the '''Mage District''' or the '''Mage's District''') lies in the southern corner of [[Stormwind City]]. The infamous [[Slaughtered Lamb]] [[tavern]] is located there, as well as the [[Wizard's Sanctum]], the [[portal room]] to most of the major Alliance cities. Within the Sanctum, [[mage]]s train to increase their powers, and there are also several [[portal]]s in the tower. In the Slaughtered Lamb, shady [[warlock]]s are often drawn to the dark cellars, where they practice their [[Shadow (magic)|dark]] [[Fel|arts]] in the shadows of polite society. Throughout the rest of the quarter, you can find [[herbalism]], [[alchemy]], and [[tailoring]] related stores and [[NPC]]s.\r\nTo get to the Mage Quarter, visitors can travel southwest across the [[Canals (Stormwind City)|Canals]] from either [[Cathedral Square]], [[Lion's Rest]], or the [[Trade District]].\r\n===Taverns===\r\n*[[Blue Recluse|The Blue Recluse]]\r\n*[[Slaughtered Lamb|The Slaughtered Lamb]] ( Tailoring trainer; Warlock trainer)\r\n===Shops===\r\n*[[Alchemy Needs]] ( Alchemy trainer)\r\n*[[Ancient Curios]]\r\n*[[Cone of Cold (shop)|Cone of Cold]] (during the [[Children's Week]])\r\n*[[Duncan's Textiles]] ( Tailoring trainer)\r\n*[[Essential Components]]\r\n*[[Larson Clothiers]]\r\n*[[Pyrotechnics]]\r\n*[[Stormwind Staves]]\r\n====Canals' shops====\r\n*[[Cordell's Enchanting]]\r\n*[[Scribe of Stormwind|The Scribe of Stormwind]]\r\n===Other===\r\n*[[Stormwind Stockade|The Stockade]] (in the [[Canals (Stormwind City)|Canals]] area)\r\n*[[Wizard's Sanctum]] ( Mage trainer; portal to [[Blasted Lands]])\r\n**Stormwind Portal Room\r\n===Demon Hunter area===\r\n*Elerion Bladedancer\r\n*Falara Nightsong\r\n*Illidari Darkdealer\r\n*Captive Wyrmtongue\r\n''Excludes the above areas.''\r\n*Erich Lohan\r\n*Officer Pomeroy\r\n*Tannysa\r\n*Collin Mauren\r\n*Archmage Malin\r\n*Janey Anship\r\n*Lisan Pierce\r\n*Suzanne\r\n*Archivist Thomas\r\n*Lisa Schaefer\r\n*Mikey Schaefer\r\n*Karlee Chaddis\r\n*Paige Chaddis\r\n*Gil\r\n*Archmage Nakada\r\n*Linda\r\n*Daniel\r\n*Elizabeth\r\n*Jenna\r\n*Jeremy\r\n*Naomi\r\n*Sammy\r\n==Suzanne - Janey - Lisan conversation==\r\nTheir conversation is a randomized three-liner containing one of the following sentences:\r\n1st line:\r\n*\r\n*\r\n*\r\n*\r\n2nd line:\r\n*\r\n*\r\n*\r\n*\r\n3rd line:\r\n*\r\n*\r\n*\r\n*\r\n==Notes and trivia==\r\n*A few [[Night elf|night elves]] live in this district.\r\n*A [[Riftwarden Acolyte]] is seen walking with a [[High Elf Sorceress]] in the Mage Quarter.\r\n*Stormwind's Mage District features as an attraction in the [[Blizzard World]] in-universe map in ''[[Overwatch franchise|Overwatch]]'', but is not seen in the in-game map itself.",},
			["Mage quests"] = { content = "==Introduction to Mage Trainer==\r\n* Glyphic Letter (Human)\r\n* Glyphic Memorandum (Gnome)\r\n* Mage Training (Draenei)\r\n* Mage Training (Blood Elf)\r\n* Glyphic Scroll (Forsaken)\r\n* Glyphic Tablet (Troll)\r\n==Quest for Staff or Orb==\r\n* Mirror Lake (Human)\r\n* Mage-tastic Gizmonitor (Gnome)\r\n* Control (Draenei)\r\n* Ju-Ju Heaps (Troll)\r\n* The Balnir Farmstead (Forsaken)\r\n* Fetch! (Blood Elf)\r\n==Quest Chain for Robe==\r\n* Report to Jennea (Optional)\r\n** Investigate the Blue Recluse\r\n** Gathering Materials (Alliance)\r\n* Report to Anastasia (Optional)\r\n** Investigate the Alchemist Shop\r\n** Gathering Materials (Horde)\r\n==Quest Chain for Adept's Robe==\r\n* High Sorcerer Andromath\r\n** Ur's Treatise on Shadow Magic\r\n** Pristine Spider Silk\r\n* Speak with Deino\r\n** Waters of Xavian\r\n** Laughing Sisters\r\n==Quest Chain for Mage's Wand==\r\nCan be obtained at level 30. Starts at mage trainers in capital cities and directs you to [[Tabetha]], a witch in the middle of [[Dustwallow Marsh]]. The final reward is a choice of 3 [[wands]], each giving +9 spell damage to Fire, Frost or Arcane spells.\r\n* Journey to the Marsh\r\n** Hidden Secrets\r\n** Get the Scoop\r\n** Rituals of Power\r\n** Items of Power\r\n==Quest Chain for Celestial Orb or Celestial Stave==\r\nCan be obtained at level 35. Starts at mage trainers in capital cities and continues with [[Tabetha]], who again gives a series of challenging quests. The final reward is a choice of [[Celestial Orb]] or [[Celestial Stave]], [[rare]] quality items that give increased spell damage and [[intellect]].\r\n* Return to the Marsh\r\n** The Infernal Orb\r\n** The Exorcism\r\n** Power in Uldaman\r\n*** Mana Surges\r\n==Quest Chain for [[Glacial Spike]], [[Arcane Crystal Pendant]] or [[Fire Ruby]]==\r\nOnce again, mage trainers in the capital cities will direct you to [[Archmage Xylem]] for this quest chain.\r\n* Magic Dust\r\n** The Siren's Coral\r\n** Destroy Morphaz\r\n==Quest for Spell: Conjure Water (Rank 7)==\r\nStarts at [[Lorekeeper Lydros]] in the Library in [[Dire Maul]] North.\r\n* Arcane Refreshment\r\n==Quest for Spell: Polymorph: Pig==\r\nStarts at Archmage Xylem.\r\n* Warlord Krellian\r\n** Fragmented Magic",},
			["Mage Sets"] = { content = "#REDIRECT [[Mage sets]]", redirect = "Mage sets",},
			["Mage Summoner"] = { content = "==Objectives==\r\nSlay Sarilus Foulborne and bring his head to [[Sentinel Velene Starstrike]] in Silverwind Refuge. \r\n* Sarilus Foulborne's Head\r\n== Description==\r\nThere's only one undead mage in the Barrens capable of defiling this many water elementals. He's also the only one foolish enough to try. Sarilus Foulborne is probably sitting at the top of Dreadmist Peak, laughing at me.\r\n<name>, you must go into enemy territory and destroy this miscreant. I have had enough of his idiocy and we must show him what happens to those who annoy the Sentinels.\r\nDestroy him and bring me his head. Be wary though, the [[Horde]] may be watching for you. \r\n== Progress==\r\nIs it done? Is Sarilus Foulborne dead? \r\n== Completion==\r\nNow I can see that repugnant smile wiped from his face forever. You have done very well, <name>. Take this, the Light of Elune, drink of it when all seems lost and death is near. It may save you, Goddess willing. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*2550 [[XP]] (or 15 silver 60 copper at level 70)\r\n*350 [[reputation]] with [[Darnassus]]\r\n==Quest progression==\r\n# Elemental Bracers\r\n# Mage Summoner",},
			["Mage talent"] = { content = "#REDIRECT [[Mage abilities]]", redirect = "Mage abilities",},
			["Mage talents"] = { content = "#REDIRECT [[Mage abilities]]", redirect = "Mage abilities",},
			["Mage trainer"] = { content = "#REDIRECT [[Mage trainers]]", redirect = "Mage trainers",},
			["Mage trainers"] = { content = "A '''mage trainer''' is an [[NPC]] that offers [[mage]]s the opportunity to train and learn ranks of spells, including [[talent]]-based abilities.\r\n== Neutral Trainers==",},
			["Mage twinking guide"] = { content = "= Basic Gear & Enchants (Level 19) =\r\n*Head\r\n**Lucky Fishing Hat ([[BoP]])\r\n**Green Tinted Goggles ([[BoE]])\r\n**Enchant: Lesser Arcanum of Constitution\r\n*Neck\r\n**Thick Bronze Necklace ([[BoE]])\r\n*Shoulder\r\n**Talbar Mantle ([[BoP]])\r\n*Back\r\n**Engineer's Cloak ([[BoP]])\r\n**Feyscale Cloak ([[BoP]])\r\n**Caretaker's Cape (level 18) ([[BoP]]) **Enchant: Enchant Cloak - Superior Defense or Enchant Cloak - Greater Resistance\r\n*Chest\r\n**Tree Bark Jacket ([[BoE]])\r\n**Robe of the Moccasin ([[BoP]])\r\n**Inferno Robe ([[BoP]]) (Horde Only)\r\n**Enchant: Enchant Chest - Major Health, Enchant Chest - Major Mana or Enchant Chest - Greater Stats\r\n*Wrist\r\n**Mindthrust Bracers ([[BoE]])\r\n**Crystalline Cuffs ([[BoP]])\r\n**Enchant: Enchant Bracer - Superior Stamina or Enchant Bracer - Greater Intellect\r\n*Hand\r\n**Magefist Gloves ([[BoE]])\r\n**Serpent Gloves ([[BoP]])\r\n**Gold-flecked Gloves ([[BoP]])\r\n**Jutebraid Gloves ([[BoP]])\r\n**Enchant: Enchant Gloves - Fire Power or Enchant Gloves - Frost Power. In some cases Enchant Gloves - Healing Power (The last is for hybrids that want Fire, frost AND arcane damage!)\r\n*Waist\r\n**Keller's Girdle ([[BoE]])\r\n*Legs\r\n**Darkweave Breeches ([[BoE]])\r\n**Enchant: Runic Spellthread\r\n*Feet\r\n**Sanguine Sandals ([[BoE]])\r\n**Nat Pagle's Extreme Anglin' Boots ([[BoP]])\r\n**Enchant (Sanguine Sandals): Enchant Boots - Greater Stamina or in some cases Enchant Boots - Minor Speed\r\n**Enchant (Nat Pagle's Extreme Anglin' Boots): Enchant Boots - Boar's Speed or Enchant Boots - Fortitude\r\n*Rings\r\n** Seal of Wrynn ([[BoP]]) ** Lorekeeper's Ring ([[BoP]]) **Lavishly Jeweled Ring ([[BoP]])\r\n**Black Pearl Ring ([[BoE]])\r\n**Band of Purification ([[BoE]])\r\n**Bronze Band of Force ([[BoE]])\r\n**Black Widow Band ([[BoE]])\r\n**Blood Ring ([[BoE]])\r\n*Trinkets\r\n**Goblin Jumper Cables (Only Gnomes, Engineering)\r\n**Insignia of the Alliance ([[BoP]]) **Minor Recombobulator (Engineering)\r\n*There are also two [[TCG|WoW: TCG]] Trinkets usable by twinks:\r\n**Perpetual Purple Firework ([[BoP]])\r\n**Carved Ogre Idol ([[BoP]])\r\n*Weapons\r\n**Twisted Chanter's Staff ([[BoE]])\r\n**Evocator's Blade ([[BoE]])\r\n**Enchant: Enchant Weapon - Spell Power\r\n*Off-hand\r\n**Antipodean Rod ([[BoE]]) (Fire/Frost hybrid)\r\n**Pulsating Hydra Heart ([[BoE]]) (Fire/Stamina)\r\n*Wand\r\n**Banshee Rod of the Sun ([[BoE]]) (Best stats)\r\n**Gravestone Scepter ([[BoP]]) (Best Damage/DPS); Quest reward from [[Quest:Blackfathom Villainy|Blackfathom Villainy]] \r\nThis is just one of the many armor combinations you can use. For more options go to and click on the mage section. \r\nMages aren't known for twinking at Level 19, but after you get killed by one you will hope no one saw you.\r\n= Basic Gear & Enchants (Level 39) =\r\nAt level 39, all twinks become much more dangerous to non-twinks because of access to level 70 enchants like Enchant Weapon - Sunfire (Note that this enchant \"Requires a level 35 or higher item.\")\r\n*Head\r\n**Green Lens ([[BoE]]) (Crafted, Engineering, Random Enchant)\r\n**Enchant: Arcanum of Focus comes from Libram of Focus\r\n**Note: The Green Lens comes in many random enchant flavors, including +dmg to any of the three schools of magic a Mage can cast. As an example, there's a Green Lens of Fiery Wrath which adds either +35 or +36 to Fire spell damage.\r\n*Neck\r\n**Jade Pendant of Blasting ([[BoE]])\r\n**Glowing Eye of Mordresh ([[BoP]])\r\n**Scorn's Icy Choker ([[BoP]]) Note: Only available during the [[Scourge Invasion]].\r\n*Shoulder\r\n**Inquisitor's Shawl ([[BoP]])\r\n*Back\r\n**Gossamer Cape ([[BoE]])\r\n**Enchant: Enchant Cloak - Spell Penetration\r\n*Chest\r\n**Robe of the Magi ([[BoE]])\r\n**Robe of Crystal Waters ([[BoP]])\r\n**Robes of the Lich ([[BoP]])\r\n**Enchant: Enchant Chest - Exceptional Health, Enchant Chest - Exceptional Mana or Enchant Chest - Exceptional Stats\r\n*Wrist\r\n**Bloodwoven Bracers ([[BoE]])\r\n**Royal Bands ([[BoE]])\r\n**Lunar Bindings ([[BoE]]) (See Note)\r\n**Regal Cuffs ([[BoE]])\r\n**Enchant: Enchant Bracer - Spellpower\r\n**Note: All four of the above wrists provide the same amount of additional damage except for the Lunar Bindings which have a chance of one damage below the others.\r\n*Hand\r\n**Revelosh's Gloves of Fiery Wrath ([[BoP]]) (Random enchant)\r\n**Royal Gloves ([[BoE]])\r\n**Lunar Handwraps ([[BoE]])\r\n**Regal Gloves ([[BoE]])\r\n**Darkmist Handguards ([[BoE]])\r\n**Enchant: Enchant Gloves - Major Spellpower.\r\n*Waist\r\n**[[Defiler's Cloth Girdle (level 38)]] ([[BoP]]) (Horde)\r\n**[[Highlander's Cloth Girdle (level 38)]] ([[BoP]]) (Alliance)\r\n*Legs\r\n**Regal Leggings ([[BoE]])\r\n**Enchant: Runic Spellthread\r\n*Feet\r\n**[[Defiler's Cloth Boots (level 38)]] ([[BoP]]) (Horde)\r\n**[[Highlander's Cloth Boots (level 38)]] ([[BoP]]) (Alliance)\r\n**Enchant: Enchant Boots - Fortitude\r\n**These Arathi Basin PVP Reward boots include a Run Speed passive ability that does not stack with other other Run Speed enchants like Enchant Boots - Boar's Speed\r\n*Rings\r\n**Golden Ring of Power\r\n**[[Advisor's Ring (level 38)]] ([[BoP]]) (Horde)\r\n**[[Lorekeeper's Ring (level 38)]] ([[BoP]]) (Alliance)\r\n*Trinkets\r\n**[[Rune of Perfection (level 20)]]\r\n**Mechanical Dragonling (Engineering)\r\n*Weapons\r\n**Staff of Jordan ([[BoE]]) (Epic!)\r\n**Enchant: Enchant Weapon - Sunfire\r\n*Off-hand\r\n**There are alternatives, but none are worthy of competition to the Staff of Jordan ([[BoE]]).\r\n*Wand\r\n**Icefury Wand ([[BoP]])\r\n**Nether Force Wand ([[BoP]])\r\n**Ragefire Wand ([[BoP]])\r\n*Level 39 Twink Mage Notes\r\n**At level 39, twink Mages beat all other classes for damage per kill (overall damage / # kills), but are second in overall damage to Warlocks (dot -n- run) and are usually even with Hunters for most kills. Mages liven-up during the 30s due mostly to talent points, and specifically, access to the Fire tree talents 'Critical Mass' and 'Fire Power.'\r\n**Twink Mages at level 39 have been known to get above 400 Fire spell damage, throw Pyroblasts for over 2,000 hit points, Fireballs nearing 2,000 hit points, and Fire Blasts around 1,500 hit points.\r\n**The lack of Shoulder-slot items with +damage to the mage spell schools is a limiting factor for competing better with Warlocks.\r\n*Wowarmory examples:\r\n** \r\n*Level 39 Twink Mage Guide by [[User:Isidis|Isidis]] ([[User talk:Isidis|talk]]) 18:24, 15 July 2008 (UTC)Isidis",},
			["Magga"] = { content = "'''Magga''' can be found in [[Durotar]]. She ends the quest Welcome! (Valley of Trials).",},
			["Maggoc"] = { content = "The [[gronn]] '''Maggoc''' is one of the seven sons of [[Gruul the Dragonkiller]], found patrolling [[Razor Ridge]] and [[Scalewing Shelf]] in the [[Blade's Edge Mountains]].\r\n----\r\nMaggoc has a stacking healing debuff (5% healing reduction every 15 seconds or so) and throws boulders which daze at random targets. The debuff appears to be a normal melee attack, and can miss; a high-mitigation tank that can dodge/parry at a high rate can keep it from stacking.\r\nHe hits a well geared druid for about 600, so a warrior should expect hits between 900 and 1000. Maggoc will also occasionally enrage for 10-15 seconds, substantially increasing his damage output.\r\n===Quests===\r\nMaggoc must be killed for Maggoc's Treasure Chest (Group) given by [[Mog'dorg the Wizened]].",},
			["Maggore"] = { content = "'''Maggore''' is a [[Grimtotem]] tauren and member of Sparkeye's team. He's wounded by [[Lo'Gosh]] in a battle with Rehgar's team.",},
			["Maggot"] = { content = "'''Maggots''' are emplyed as the young stage of various insectoid creatures, notably the [[Silithid]]s and [[Nerubian]]s.\r\nMaggots inhabit only a few places in the world of [[Azeroth]], often among more adult stages of Silithid such as in [[the Barrens]], or in huge variants in the [[Eastern Plaguelands]]. They usually come in a variety of colors, including white, yellow, brown, green, pink and purple, and may or may not be aggressive.\r\nMaggots vary quite much in size, from the cat-sized larvae of the Silithid to the enormous carrion grubs of the Plaguelands, the largest of which can be the size of elephants.",},
			["Maggot Eye"] = { content = "'''Maggot Eye''' is a level 10 [[Rot Hide]] [[gnoll]] found in [[Tirisfal Glades]].\r\n[[Executor Zygand]] wants Maggot Eye's paw.\r\n==Quests==\r\n*Wanted: Maggot Eye\r\n==Loot==\r\n*Maggot Eye's Paw ''(Quest Item)''\r\n*Spiked Wooden Plank",},
			["Maggran Earthbinder"] = { content = "'''Maggran Earthbinder''' is a level 30 [[quest giver]] located in [[Sun Rock Retreat]] in the [[contested]] territory of [[Stonetalon Mountains]].\r\n==Quests==\r\n* Harpies Threaten\r\n* Bloodfury Bloodline\r\n* Calling in the Reserves\r\n* Arachnophobia\r\nSee [[List of Stonetalon Mountains NPCs]].",},
			["Magi"] = { content = "#REDIRECT [[Mage]]", redirect = "Mage",},
			["Magic"] = { content = "The universe is a realm filled with potent '''magics''' (or '''magiks''' and '''magicks''') and mighty beings. Since the dawn of time, these forces have influenced the cosmos, setting the stars in motion and the destiny of countless worlds and mortal civilizations.\r\nMagical energies are most apparent beneath the earth as well as in special locations - centers of elemental forces, otherworldly powers, and mystical energies.\r\n==The cosmic forces==\r\nCreated by the [[First Ones]], the cosmic forces have influenced [[Azeroth]] and the surrounding cosmos, setting the stars in motion and shaping the destiny of countless worlds and mortal civilizations. \r\n===Light and Shadow===\r\n[[Light]] and [[Void|Shadow]] are the most fundamental forces in existence. Although contradictory by their very nature, they are bound together on a cosmic scale. One cannot exist without the other. Pure Light and Shadow dwell in a [[plane|realm]] outside the borders of reality, but shades of their presence are found in the physical universe. Light manifests as [[holy]] magic, while Shadow (also called the [[Void]]) appears as [[shadow (magic)|shadow]] magic.\r\n===Life and Death===\r\nThe forces of [[Life]] and [[Death|Death]] hold sway over every living thing in the physical universe. The energies of Life, known commonly as [[nature]] magic, promote growth and renewal in all things. Death, in the form of [[necromancy|necromantic]] magic, acts as a counterbalance to Life. It is an unavoidable force that breeds despair in mortal hearts and pushes everything toward a state of entropic decay and eventual oblivion. Another type of Death magic is [[domination]], which is capable of controlling and reshaping souls.\r\n===Order and Disorder===\r\nThe forces of Order and Disorder (also called Chaos) govern the cosmic systems of the physical universe. Order is most commonly perceived in reality as [[arcane]] magic. This type of energy is innately volatile, and wielding it requires intense precision and concentration. Conversely, Disorder is manifested as highly destructive [[fel]] magic. This brutal and extremely addictive energy is fueled by drawing life from living beings.\r\nIt has been hinted that when titans die, their souls would return to their own Order plane.\r\n===The Elements===\r\nThe elements of fire, air, earth, and water serve as the basic building blocks of all matter in the physical universe. [[Shaman]]ic cultures have long sought to live in harmony with, or assert dominion over, the elements. To do so, they called upon the primordial forces of [[Spirit (lore)|Spirit]] and [[Decay]]. Those who seek to bring balance to the elements rely on Spirit (sometimes referred to as the fifth element by shaman, or [[chi]] by [[pandaren]]). This life-giving force interconnects and binds all things in existence as one. Decay is the tool of [[Dark shaman|shaman]] seeking to subjugate and weaponize the elements themselves.\r\n====Elemental duality====\r\nElements can influence a variety of emotionally positive and negative states:\r\n*Fire influences passion and fury\r\n*Air influences cunning and madness\r\n*Earth influences stability and stubbornness\r\n*Water influences tranquility and indecisiveness\r\n*Spirit influences bravery and naiveté\r\n*Decay influences efficiency and ruthlessness\r\n===The seventh force?===\r\nA few in-game sources imply the presence of a potential seventh force. The [[broker]] Al'firim compiled [[Expedition_Report_A37J_-_Part_1|a report]] on his findings of a force he refers to as the \"fractals\". Additionally, a [[Korthia]]n relic, the [[Everliving Statuette (item)]], whispers \"\".\r\n===Commonalities===\r\nThere are many different [[Magic schools|schools of magic]], tapping into various cosmic energies and using different methods to sometimes reach similar goals. Most magic [[spell]]s however require specific components, physical requirements the [[caster]] must meet in order to use them. These requirements might be verbal, with the spellcaster using specific words of power, somatic, with the spellcaster having to make motions, or material, with the spell requiring [[reagent]]s. Some clothes might even be more adapted than others for the casting of certain spells. As such these spells might have different [[cast time]]s and can even be [[interrupt]]ed by circumstances. [[Spellbook]]s are known to describe spells, their effects and their components. [[Medivh]] personally had [[Karazhan]] fitted with a fully equipped pantry of spell components, including a larder of aromatic and thaumaturgic herbs, and a lapidarium of crushed semi-precious stones.\r\nFailing to follow a spell's components, such as changing a hand-motion or not using a required incense, would most of the times result in failure, with the energies of the spell dissipating harmlessly. Occasionally the energies may go wild and out of control, but usually the only result of a failed spell is a frustrated spellcaster. Changing the incantation or altering the motions isn't also enough to refit a spell for a new activity. Changing an existing spell requires a deep and precise understanding of how it works, and this activity is more dangerous than simply following a list of components, as a failed spell being very close to the final intended spell would lead to the magics trying to close the gap, to make something happen, though then resulting in unintended results or spectacular and dangerous failure.\r\n===Arcane===\r\nOn [[Azeroth]], volatile arcane magic was once concentrated in the [[Well of Eternity]], but its destruction spread arcane magic throughout the world. Arcane is distinctive for its ability to bend other energies (such as [[Fire]], [[Life]]) to the caster's will. It can be used to manipulate space and [[time]].\r\nArcane is derived from the phase transitions of [[mana]] - if mana were water, then arcane would be steam pressure. Arcane energy is so similar to an element it might as well be one, for all magical intents and purposes. [[Ley line]]s carry arcane magic. Sub-branches of arcane:\r\n====Technomancy====\r\nTechnomancy, or techno-sorcery, is a form of magic employed by the [[ethereal]]s, capable of [[Reforging|modifying]] an item's [[arcane]] essence or [[Void Storage|housing items in a pocket dimension]], as well as opening portals.\r\n====Chronomancy====\r\nChronomancy is the art of weaving time.\r\n===Fel===\r\nFel magic is a destructive form of [[magic]] often used by the members of the [[Burning Legion]]. It is demonic, entropic, chaotic and extremely volatile. Its use results in the alteration of the individual, or [[Fel|corruption]], which manifests as a physical transformation such as a change to an individual's eyes or skin color, or heavy genetic mutations. All of the Burning Legion carry the taint of fel magic within their very blood, allowing them to spread greater evil. [[Warlock]]s use life force to power their fel magic.\r\n===Holy===\r\nPure [[Light]] cannot exist within the physical universe but shades of it manifest as holy magic. It can be channeled to heal, cleanse, and protect. Practitioners of the Light are called [[priest]]s or [[paladin]]s, devoted to cleansing the universe of darkness. The Light is often said to bring about feelings of positive emotion—hope, courage, comfort—coming from the \"heart.\"\r\n===Shadow===\r\nShadow magic is the manifestation of the [[Void]] in the universe. A source of terrible power, it is the kind that comes at a price. Although destructive, it can also be used to raise the undead or to harm the mind, imparting feelings such as despair, doubt, and panic—emotions based on survival logic.\r\n====Twilight====\r\nTwilight magic is presumably [[Old God]] magic of the void branch.\r\n===Necromancy===\r\nNecromancy is the study and use of magic to raise and control the dead. The manifestation of [[Death]] magic, it has many functions. Masters of this tainted field of magic can conjure festering diseases, harness the shadows into [[Shadow Bolt|bolts of incendiary energy]], and reconstruct the flesh of [[undead]] creatures, allowing them to function again even after the foul monsters have been destroyed.\r\n===Nature===\r\nThe energies of [[Life]], commonly known as nature magic, promote growth and renewal in all things.\r\n====Blood magic====\r\n[[Blood magic]] is a form of tortured life magic that uses blood as a power source.\r\n====Druidism====\r\n[[Druid]]s maintain a deep connection to nature through the [[Emerald Dream]], a primordial realm that encompasses all aspects of nature.\r\n====Shamanism====\r\n[[Spirit of Life|Spirit]], or [[Chi]] as the [[pandaren]] call it, is the life force that [[shaman]] manipulate. Spirit energy is intrinsically linked to the elements—earth, air, fire, and water. This life-giving force interconnects and binds all things in existence as one. Shamanism is a deeply spiritual form of elemental magic that involves a connection with both the natural and spirit worlds. [[Shaman]] do not normally enslave [[elemental]]s, but honor them, asking the elements to heed their call. Shaman are not inherently imbued with magic—they harness the powers of the elements through ceremonial [[totem]]s. Shamanism is also practiced by some of the draenei who learned shamanism from the orcs of [[Draenor]].\r\n====Geomancy====\r\nGeomancy is a crude form of shamanism.\r\n====Voodoo====\r\nVoodoo is a dark and powerful form of magic practiced by troll shadow hunters, hexxers, and witch doctors. They use [[mojo]] in their voodoo.\r\n===Runic===\r\nRunic magic is a magic that employs runes. The vrykul practice a runic magic that even the most experienced wizards find unfamiliar. The runes can access various types of magic, such as fel, void, arcane, and death.\r\n===Arcane===\r\nArcane, the most common form of magic, comes from the Well of Eternity, which itself draws from the Twisting Nether. Arcane magic is very powerful, but if not used carefully can cause corruption and great destruction. . Used by [[mage]]s, [[wizard]]s, and other [[sorcerer]]s, such as those of the [[Kirin Tor]], arcane magic is ever present in the atmosphere and accessible to any who are capable of drawing upon its energies. Arcane magics were discovered by the kaldorei and later refined by the [[high elves]] of [[Quel'Thalas]] and the [[human]] nations, and are most commonly practiced by mages.\r\n===Fel===\r\nFel energy is arcane magic at its most corrupt. If arcane magic is an addiction, fel magic is the embodiment of the drug at its purest form.\r\n===Necromancy===\r\nNecromancers are capable of reviving living creatures from death to do their bidding as [[undead]] servants.\r\n===Nature===\r\nDruids derive their power from the earth itself, although they do not require totems to channel energy like shamans. They become agents of nature itself, forming a bond with all beings of nature and pulling their strength directly from that bond.\r\n===Geomancy===\r\nThe practice of divination and elemental combat native to several humanoid races of [[Azeroth]]. It is similar to shamanism in that disciples of geomancy wield the powers of the earth and encourage respect of earth’s spirits. The main difference between a geomancer and a shaman is the method through which the trust of the elements is gained. A shaman speaks directly with the elemental spirits, whereas a geomancer uses rituals, songs, and sacrifices to appease and propitiate the spirits.\r\n===Rune magic===\r\nRunic magic was created by the [[titan]]s. Their creation, the [[Dwarf|dwarves]], quickly mastered the mysteries of the runes taught to them. However, as generations passed, the dwarves forgot their heritage and lost all knowledge of runes and their hereditary powers.\r\n[[Tauren]] in [[Kalimdor]] rediscovered the power of runes. An ancient race as well, the tauren remembered the myths of runecasting and revived interest in this nearly lost art. The dwarves that came to Kalimdor with [[Jaina Proudmoore]]'s Alliance Expedition learned tauren runecasting techniques. Tauren and dwarves do not share good relations, but they were eager to share knowledge of runes and titan myths.\r\n===Voodoo===\r\nVoodoo is a strange tribal mix between the power of arcane and divine magic, practiced by [[witch doctor]]s and [[shadow hunter]]s. They often combine reagents in a cauldron to create strange brews that most often result in bizarre transformations when consumed. They are widely known for placing [[hex]]es to morph victims into various creatures or placing curses. The majority of voodoo users are trolls, although other races of the Horde have taken up the craft.\r\n==Notes==\r\n*The nature and uses of the forms of magic are vigorously [[Flavor lore|debated]] on Azeroth, but the magnitude of what magic can accomplish cannot be doubted.\r\n*The four motifs at the corners of the cosmology chart are identical to the four motifs used in the map of Azeroth after the sundering in .\r\n==See also==\r\n*[[Hoodoo]]\r\n*[[Azeroth magic]] \r\n*[[Gadgetzan Times/A Magical History of Azeroth]]\r\n*[[Magic breaker]]\r\n*[[Magic schools]]\r\n**[[Magic schools (RPG)]]\r\n*[[Magic (dispel type)]]\r\n*[[Cord of Infinity]]\r\n*[[Higher Learning]]\r\n*[[The Schools of Arcane Magic]]",},
			["Magical Crawdad"] = { content = "#REDIRECT [[Magical Crawdad Box]]", redirect = "Magical Crawdad Box",},
			["Magic & Mayhem"] = { content = "'''Magic & Mayhem''' is a source book for the [[Warcraft RPG]] and was published in 2004.\r\nIt is said in the introduction that the book was compiled by [[Han'al]], Master Lorekeeper and mage of the Kirin Tor.\r\nThe material he compiled covers lore from all eras up to the founding of Undercity.\r\n==Short Stories==\r\n[[Short stories]] found in [[Magic & Mayhem]].\r\n*Gimbolt Stormhammer and his blood elf companion Maelr'thiss travel to the hut of the witch doctor Zul'ajik. They visited the troll in order to hire him to perform a ritual to contact spirits which would lead to the Demonwell. Because of Zul'ajik's hatred for goblins their third companion Ziggler chose stay outside of the camp, and to tinker on his [[Clockworks|clockwork]] dwarf. Ziggler ends up interrupting the ritual when he pilots the dwarf and tramples through the troll's hut. Gimbolt decides to flee with Ziggler, while Maer'thiss and Zul'ajik decide to kill them both.\r\n*[[Verius]], a pit lord disguised as a human, enters a chapel, belonging to the Knights of the Silver Hand, in order to infiltrate the Order of the Silver Hand. Father Rommel sees through his disguise, as does an elven cleaning girl who later enters the room. The elven girl breaks Verius disguise, and he attacks Rommel. Rommel, who had also been in disguise shows his true appearance that of a blood elf, and both elves fall upon Verius to feed on his energy.\r\n*Jocas Irongear, a goblin who left Theramore with his companions the warden, Blackhawk, and Ashar Ghosthoof on his zeppelin. They had picked up a fourth passenger who hired them to smuggle cargo of crates out of Theramore for him. The warden discovers that are smuggling [[carrion beetle]]s, and find out the passenger is not who he said he was. The passenger sensing he was caught removes his hood, showing his true self, that of a troll. He then attacks the crew, but is slain by the Warden. The zeppelin is damaged during the fight, and Jocas is forced to fix it before it crashed.\r\n*Zaj'tal a naga attacks a night elf sentry mistaking her for a male. The two have a battle of spells, however Zaj'tal still wins. He stands over her battered body, pleased even more that instead of torturing a man, he will be able to torture a woman.\r\n*Bohen a tauren, and his goblin companion, Isek attempt to break into an ancient vault on top of a mesa, while besieged by an undead swarm. Bohen tells Isek to have vault opened while he attacks the undead. Using a special potion, Isek is able to stand on the side of the mesa, and run down into the undead, in attempt to hold them back. Isek is successful at opening the door, and found a book inside. After Bohen returned to the top of the Mesa he took the book from Isek, and used a spell inside to stop the undead.\r\n*Sunestorm attacks a camp of trolls and orc raiders, along with his dwarven companion [[Nuji Kodosbreath]]. They then send their forces of high elves and [[steamwarrior]]s, to push the Horde forces back into a trap. [[Dirtworm]] crews dig a pit under the Horde troops. Gnomish helicopters then covered the pit with nets, while tinkers staked net in place. They ended up catching sixty orc prisoners for interrogation.\r\n==See also===\r\n*",},
			["Magic (Dispel Type)"] = { content = "#REDIRECT [[Magic (dispel type)]]", redirect = "Magic (dispel type)",},
			["Magic Absorption"] = { content = "'''Magic Absorption''' is a [[mage]] talent that increases [[resistance]] to all schools, and restores mana each time a spell is resisted.\r\nThis talent is most useful to mages that expect to take a lot of magical damage. Aside from the resistance added to all schools, it will restore mana for each full resist. The amount of mana restored is a percentage of the mage's total mana pool, meaning that the talent scales with gear. Pre-expansion, there were quite a few raid encounters that required high amounts of resistance, such as [[Ragnaros]], [[Vaelastrasz the Corrupt]] and [[Viscidus]]. With the [[Burning Crusade]] expansion, there are fewer raid encounters that rely on the entire raid wearing a lot of resist gear, and this talent has become less useful. This could still be somewhat useful in PvP situations.\r\nAlthough the following should not weigh heavy in any consideration for the talent, it is observed that if you do a run through a low-level instance, you will resist essentially all magic attacks against you, and that will give you significant mana regeneration.\r\nMost mages first choose [[Arcane Concentration]] at this tier in the Arcane tree, and take Magic Absorption as filler for later talents in the tree.",},
			["Magic and Mayhem"] = { content = "#REDIRECT [[Magic & Mayhem]]", redirect = "Magic & Mayhem",},
			["Magic Attunement"] = { content = "'''Magic Attunement''' is a [[Mage]] talent that increases the effect of your [[Amplify Magic (removed mage ability)]] and [[Dampen Magic]] spells by up to 50% at max rank and increases the range of all Arcane spells by up to 6 yards.\r\nWith 2 points in this talent, Amplify Magic (Rank 6) will increase damage taken by 180 and healing taken by 360. Dampen Magic (Rank 6) will reduce damage taken by 180 and healing taken by 360. The range increase is subjectively useful, but broad as it covers all Arcane spells. It is often taken as a filler talent to get later talents in the Arcane tree. For Arcane specialized mages that use Amplify Magic and Dampen Magic often enough, this talent would make a good filler.\r\nThe talent is also important in certain PvP builds for its use in extending Polymorph's range from 30 yards to 36 at full rank.",},
			["Magic Elemental"] = { content = "#redirect [[Elemental]]", redirect = "Elemental",},
			["Magic Quarter"] = { content = "[[The Magic Quarter]] is located in the northeastern parts of the [[Undercity]]. This is where the most arcane-inclined of the [[Forsaken]] come to research, learn new spells, and practice their arts, under the watchful eye of [[Bethor Iceshard]]. \r\nFacilities:\r\n* [[Mage]] trainers\r\n* [[Warlock]] and their pets' trainers\r\n* [[Tailoring]] training to [[Expert]] (skill level 225) (inner ring)\r\n* [[Portal]] trainer",},
			["Magic Resistance Potion"] = { content = "'''Magic Resistance Potion''' increases your resistance to all schools of magic by 50 for 3 min. \r\n==Source==\r\n'''Magic Resistance Potion''' are crafted by [[Alchemy|Alchemist]] with a skill level of 210.\r\nThe components are:\r\n*1 [[Khadgar's Whisker]]\r\n*1 [[Purple Lotus]]\r\n*1 [[Crystal Vial]] \r\nThe alchemy recipe to create the Magic Resistance Potion is a random drop from mid-level humanoids (like many recipes).\r\n==Notes==\r\n*The herbs are easily farmed in Azshara, Feralas and elsewhere. For many encounters they are more useful than a \"absorbs X of Y damage\" type Protection potion.\r\n*The potion DOES stack with Paladin auras / Shaman totems. (this requires confirmation, testing now shows it does not stack with other classes)\r\n*This potion no longer stacks with a priest's [[Shadow Protection]] buff or with a with druid's [[Gift of the Wild]] buff.\r\nSee [[Potion]].",},
			["Magic school"] = { content = "#redirect [[Magic Schools]]", redirect = "Magic Schools",},
			["Magic schools"] = { content = "Every [[ability]], [[power]], or [[spell]] belongs to one of seven '''magic schools''' which define what can be done to [[absorb]], [[immune|immunize]] against, or [[resist]] it. Your [[resistance]] against five of these schools are displayed in your [[Paper doll|character information]]. The magic schools are also used as damage types, but even abilities that don't cause damage have schools.\r\nIf you are a caster, and an opponent uses an [[interrupt effect]] such as [[Counterspell]], [[Kick]] or [[Mind Freeze]] on you while you're casting a spell, your cast will be interrupted, and you will be prevented from casting any spell in that school for a certain period time. It's good to know what schools your abilities are in so you can switch to another when this happens. It's fairly clear for [[mage]]s (the school of the spell is the same as the tree it falls under) and [[warlock]]s (if it doesn't involve fire, it's Shadow). For other classes, it's not always clear. Fortunately, the tooltip of any damage spell will specify the type of damage it does. Some abilities belong to [[|multi-schools]], and behave a little differently.\r\n[[Warrior]]s are the only class that strictly deals only one damage type, that being Physical. [[Hunter]]s and [[shaman]] have the most varied damage types, with both being able to deal Physical, Nature, and Fire damage, as well as Arcane and Shadow for hunters and Frost for shaman.\r\n==[[Physical]]==\r\nNot presented as magic to the user, but treated as a school by the game mechanics. All weapons except [[wand]]s deal physical damage; the target can use [[Dodge]] to avoid the attack, a shield to [[Block]] it, the [[Parry]] skill to block it with a weapon, and [[Armor]] to resist some of the damage if all else fails. Damage taken is physical damage. Most [[warrior]] and [[rogue]] abilities are Physical. [[Death knight]] abilities obtained by spending talent points in the Blood Tree do physical damage. [[Armor penetration]] only ever applies to physical damage dealt.\r\nSome physical abilities, like [[Demoralizing Shout]] and [[Thunder Clap]], are treated like spells. These abilities have a chance to miss like all spells, which can be offset by [[Hit]] rating, but resistance to these abilities cannot be increased.\r\n==[[Arcane]]==\r\nArcane magic is typically utility magic that causes various effects rather than dealing direct damage, and is used by [[mage]]s, [[druid]]s, [[hunter]]s, and [[blood elf|blood elves]].\r\nMost non-damaging magical [[hunter]] abilities, including [[Silencing Shot]], [[Hunter's Mark]], [[Misdirection]], and [[Distracting Shot]] are Arcane-based. [[Arcane Shot]], however, is a main source of direct damage, as is the [[druid]]s' [[Moonfire]] and [[Starfire]]. Also, the [[blood elf]] racial ability [[Arcane Torrent]] is Arcane-based. (Before patch [[Patch_3.0.2|3.0.2]], night elf priests could do Arcane damage with [[Starshards]].)\r\nThe true masters of the Arcane, however, are [[mage]]s. For mages, the Arcane school is primarily a utility line rather than a damage line. Any spell from a mage's Arcane ability category is of the Arcane school, including four spells that do damage ([[Arcane Missiles]], [[Arcane Explosion]], [[Arcane Blast]], [[Arcane Barrage]]) and a very broad range of utility spells: [[Polymorph]]s, [[Arcane Intellect]], [[Mana Shield (original)]], [[Mage Armor]], [[Blink]], [[Teleport]]s, [[Portal (Spell)|Portal]]s, [[Counterspell]], and [[Conjure Mana Gem]]s, [[Conjure Food|Food]], and [[Conjure Water|Water]].\r\nHostile Arcane spells (including those that do no damage) can be resisted; there are items that increase one's [[Arcane resistance]]. Arcane is the only resistible magic school against which players cannot increase their Resistance via class abilities.\r\n==[[Fire]]==\r\nSpells of the '''Fire''' school typically inflict damage, which can be [[direct damage]] and/or [[DoT|damage over time]]. [[Mage]]s and [[warlock]]s use it as one of their primary source of damage, while [[shaman]]s, [[hunter]] [[hunter trap|trap]]s, and [[Engineering|engineers]] also use the Fire school.\r\nMany spells and environmental effects (such as lava) do Fire damage. The classes most associated with the ability to control fire are [[warlock]]s and [[mage]]s. Fire is also one of the fundamental elements that shamans can manipulate with their Totems. In the same way, [[Warlock]]s deliver huge burst of Fire damage. [[Destruction]] warlocks are sometimes called \"Firelocks\". Hunters' [[Explosive Trap]] and [[Explosive Shot]] also deal Fire damage; similarly, explosives and damaging trinkets created by [[Engineers]] typically do Fire damage.\r\nLike Arcane resistance, [[Fire resistance]] is a statistic that can be affected by spells and items.\r\n==[[Frost]]==\r\nThe '''Frost''' school is effective both for attack (doing damage) and defense (raising armor value). Frost spells often inflict [[snare]] or [[root]] effects, as well. [[Mage]]s, [[shaman]]s, [[death knight]]s and the occasional [[hunter]] [[hunter trap|trap]] use the Frost school.\r\n[[Mage]]s and [[death knight]]s have Frost specializations, and obviously any spell in those trees are of the Frost school. Shamans' [[Frost Shock]] is also of the Frost school, as well as the hunter's [[Freezing Trap]], [[Freezing Arrow]] and [[Ice Trap]].\r\n[[Frost Resistance]] exists as a statistic as well.\r\n==[[Nature]]==\r\nThe '''Nature''' school is usually used for nature based attacks, [[buff]]s, and curative spells. Nature damage can be [[direct damage]] (like lightning) or [[DoT|damage over time]] (like poison). This means that [[rogue]]s (poison), [[shaman]]s, [[druid]]s, and [[hunter]]s (stings) have access to Nature damage.\r\nAcids, [[disease]]s, and [[poison]]s inflict Nature damage, and damage from lightning is also considered part of the Nature school. Shamans' and druids' healing spells are Nature spells, and other non-damaging spells such as [[Entangling Roots]] and [[Faerie Fire]] are in this school as well. Hunters' Stings and the [[Snake Trap]]'s viper poisons are Nature-based, as are their [[Mend Pet]] and [[Revive Pet]] abilities. Rogues' poisons are also Nature-based.\r\nA [[Nature resistance]] statistic exists.\r\n==[[Shadow (magic)|Shadow]]==\r\nThe opposite of Holy magic, '''Shadow''' is probably the most versatile school. Used by [[priest]]s, [[warlock]]s, [[death knight]]s, [[rogue]] and [[hunter]]s ([[Black Arrow]]) it contains a wide variety of spells. Apart from [[Direct Damage]] and [[Damage over Time]] spells, there are various utility spells, including [[Drain]]s, [[Crowd Control]] spells, [[Debuff]]s, and even [[healing]].\r\nShadow damage is dealt by dark spells such as those of the [[priest]]'s Shadow abilities and most of the warlock's repertoire. The creation of a [[Healthstone]] or [[Soulstone]] and the summoning of demons are Shadow effects. Warlocks can also absorb Shadow damage with [[Twilight Ward]].\r\n[[Shadow Resistance]] is the final resistance type.\r\n==[[Holy]]==\r\nThe '''Holy''' school is usually related to abilities which heal and aid living beings. There are also a few spells that do Holy damage, including [[Smite]] and [[Consecration]]. Contrary to popular belief, Holy Magic does not deal additional damage to [[undead]] or [[demon]]s.\r\n[[Priest]]s and [[paladin]]s are the primary users of the Holy school, including all their healing and resurrection abilities. \r\n===Holy damage===\r\nIt is not possible to resist Holy magic, giving it a slight advantage over other schools, but it does have a basic miss chance like all spells. This is of little value to players, and in [[PvE]], NPCs' resistance is usually minimal anyway. However, NPC abilities that deal Holy damage can be significantly more harmful to a buffed raid group than damage of other schools.\r\nItems and Buffs which give a bonus to all resistances do not include Holy resistance, but percentage-based damage-reduction abilities successfully reduce damage from Holy spells. Also, the [[Holy Protection Potion]] and [[Major Holy Protection Potion]] items will also absorb limited amounts of Holy damage.\r\n==Multi-school==\r\nSome abilities belong to multiple schools of magic. These multi-school abilities benefit from bonuses that affect any of their schools. They use the lowest resistance value among their schools, and they ignore absorption and immunity effects that apply to only some of their schools. Multi-schools were introduced with [[patch 4.0.1]], although [[Frostfire Bolt]] had served as a prototype of the effects of multi-schools since [[patch 3.0.2]]. \r\n[[Interrupt effect]]s are far less effective at locking players out of using multi-school spells. As long as any of the spell's schools is available, the player will still be able to cast the spell. This makes multi-school spells extremely hard to lock down, requiring the use of at least two consecutive interrupts (one for each school) in a very short space of time. This means that these abilities will almost always be available for players to cast when one of their schools is locked. In addition, some multi-school spells such as [[Wake of Ashes]] belong to schools that are not used by any of the class's other spells. When these spells are instant cast, this means that it is not possible for that spell to be locked down.\r\n==See also==\r\n*[[Resistance]]\r\n*[[Magic schools (RPG)]]",},
			["Magic schools (RPG)"] = { content = "''Were you looking for [[magic schools (WoW)|magic schools in World of Warcraft]], or [[magic schools (RPG)|magic schools in the Warcraft RPG]]?''\r\nThis article is about lore behind ''magic schools''. It contains a list of all [[school]]s of [[magic]] in published sources and lore behind them. The final section discusses how mechanics in the MMO do not necessarily fit with the published lore.\r\n==Paths==\r\nMost spells fall into two main categories; arcane and divine. All magic on Azeroth came from the kaldorei, both divine and later arcane. However, not all magic fits neatly into these two categories. Other magic types lurk outside or within arcane and divine, powerful and strange in their own rights. For example Priests have access to divine magic, while druids wield nature magic. One of the most sinister is fel magic. \r\n*[[Arcane]] - cast by [[arcanist]]s\r\n*[[Divine]] - cast by [[healer]]s and experienced [[paladin]]s\r\n*[[Fel|Fel Magic]] - Often a darker form of Arcane.\r\n*[[Rune magic|Rune Magic]] - Arcane in nature but accessed more naturally.\r\n*[[Nature|Nature Magic]] (aka druidic magic) - Usually divine in nature, but also can be arcane.\r\n==Divine domains==\r\nDivine domains describe healer spells and help define divine spells.\r\n*Arcana\r\n*Animal\r\n*Ancestors\r\nMagic derived from the worship of ancestors, and by the power of ancestors is the ancestor domain. Several faiths believe in ancestral worship, including tauren, orcs, and tuskarr.\r\n*Crusader\r\n*Death\r\n*Destruction\r\n*Elements\r\n*Foretelling\r\n*Healing\r\n*Madness\r\nThe madness domain is magic often derived from chaotic and terrible sources such as the old gods. It grants power to certain nihilistic cults or crazed priests.\r\n*Power\r\n*Protection\r\n*Spirits\r\nSpirits has some overlap with the Elements and the Ancestors domain. It can cover abilities dealing with ancestral spirits, voodoo spirits and [[elemental spirit]]s/spirits of nature.\r\n*War\r\n*Wild\r\n===Rune types===\r\n*Marks\r\nA rune inscribed on a creature.\r\n*Glyphs\r\nRunes inscribed on an object.\r\n*Sigils\r\nRunes inscribed on a surface subsequently acts as the rune's trigger.\r\n===Rune Patterns (aka families)===\r\n*Awareness family\r\n*Beast family\r\n*Flame pattern\r\n*Frost pattern\r\n*Healing family\r\n*Motion family\r\n*Restoration family\r\n*Shielding family\r\n*Stone pattern\r\n*Storm pattern\r\n*Striking family\r\n==Branches==\r\nBranches mentioned in the lore in the RPG and other sources.\r\n===Divine branches===\r\n*[[Nature]] (Elune & the Ancients)\r\n*[[Shamanism]]\r\n*[[Holy]] (aka [[Light]])\r\n*[[Voodoo]]\r\n===Arcane branches===\r\n*[[Fel Magic]] (aka fel energy or shadow magic)\r\n*[[Rune magic]] (runes manifest magical power that is arcane in nature)\r\n*[[Nature]] (rare arcane variation)\r\n*[[fire magic|Fire Magic]] (a subcategory of arcane magic.)\r\n===Miscellaneous branches===\r\n*[[earth magic|Earth Magic]]\r\n==Schools==\r\nCutting across the categories of arcane and divine spells are the eight schools of magic. These schools represent the different ways that spells take effect.\r\n*Abjuration - one who specializes in abjuration would be known as an [[abjurer]].\r\n*Conjuration - one who specializes in conjuration is known as a [[conjurer]].\r\n*Divination - one who specializes in divination would most likely be known as a [[diviner]].\r\n*Necromancy (aka necromantic magic)- one who specializes in Necromancy is known as a [[necromancer]].\r\n*Enchantment - one who specializes in enchanting is known as an [[enchanter]].\r\n*Transmutation - one who specilizes in transmutation would be known as a [[transmuter]]\r\n*Evocation - one who specializes in evocation is known as an [[evoker]]. Queen Azshara is the inventor of most evocation spells.\r\n*Illusion - one who specializes in illusion is known as an [[illusionist]]\r\n*Universal - Spell falls under all eight categories. Not a true school.\r\n==Subschools==\r\nThe main schools split into several subschools. Some of the subschool categories can be found within more than one school.\r\n*Healing\r\n*Calling\r\n*Charm\r\n*Compulsion\r\n*Summoning\r\n*Creation\r\n*Glamer\r\n*Figment\r\n*Pattern\r\n*Phantasm\r\n*Scrying\r\n*Shadow\r\n*Soul\r\n*Teleportation\r\n==Descriptor==\r\nA descriptor further categorizes spells in some way. Some spells have more than one descriptor. Descriptors govern how the spell interacts with other spells, with special abilities, with unusual creatures, with alignment, and so on.\r\n*Acid\r\n*Air\r\n*Blessing\r\n*Chaotic\r\n*Cold\r\n*Darkness\r\n*Death\r\n*Earth (aka [[earth magic]])\r\n*Electricity\r\n*Evil\r\n*Fear\r\n*Fel\r\n*Fire (aka [[fire magic]])\r\nFire magic is a subcategory of arcane magic.\r\n*Force\r\n*Good\r\n*Language-Dependent\r\n*Lawful\r\n*Light\r\n*Mind-affecting\r\n*Seal\r\n*Sonic\r\n*Totem\r\n*Water\r\n==Special powers==\r\nThese magical discriptions usually have ties to enchantments or enhancements or bonus abilities on items.\r\n*Frost/Ice\r\n*Holy\r\n*Unholy\r\n*Shadow\r\n*Positive\r\n*Negative\r\n*[[Nature]]\r\n==The World of Warcraft MMO Schools==\r\nThe World of Warcraft MMO has schools that are used for game mechanics and may not fit into the lore described in other sources.\r\n* [[Arcane]] - Not considered a school, but instead it is a path of magic (fire and frost fall under this path for example). \r\n* [[Fire]] - Not considered a school, but an elemental descriptor. Fire magic is a subcategory of the arcane magic.\r\n* [[Frost]] - Not considered a school, but an elemental descriptor.\r\n* [[Nature]] - Not considered a school, but a branch of divine magic & sometimes arcane. In some cases it is considered its own branch (covering all spells that a druid would cast for example).\r\n* [[Shadow]] - Not considered a school, but instead its a subschool.\r\n* [[Holy]] - Not a school, but instead is a branch within the divine path of magic.\r\nNot technically magic:\r\n* [[Physical]]\r\n=Science Behind Casting=\r\n===Arcane, Runic, and Fel===\r\nArcane and Runic magic involve manipulating ley lines, which were laid down by the titan [[Norgannon]] during the creation of the universe. By manipulating the energies of the ley lines, arcane and runic casters can manipulate the world around them, causing changes in the physical universe.\r\nSimilar to arcane and runic magic, Fel magic involves the caster's manipulating the physical world by making compacts with demons. Every manipulation of fel energies requires a small sacrifice of the caster's humanity to the demon world, having a similar effect as arcane magic, but without the burdensome study.\r\n[[Hydromancy]], [[Geomancy]], [[Pyromancy]], and [[Aeromancy]] are magical specializations that require the caster use his/her manipulation over supernatural forces (like manipulating ley lines or compacting with demons) to command the loyalty of the elements from within the [[Elemental Plane]].\r\n[[Necromancy]] is a similar specialization that allows fel (like the [[dreadlords]]) or arcane ([[Cult of the Damned]]) magicians to use their powers to call upon spirits from the afterlife and reanimate dead flesh as [[undead]] minions .\r\n===Divine===\r\nDivine magic involves the blessings of a supernatural being.\r\nThe [[Holy Light]] of Creation grants supernatural healing and, in some cases, destructive powers to anyone who follows the strict discipline prescribed by its religious philosophy. The [[Forgotten Shadow]] provides similar powers to those people who follow its nihilistic religious doctrine. [[Troll]] witch doctors draw their abilities from the [[Loa]] gods, invoking their powers by enticing them with voodoo rituals. Some of the abilities of a [[druid]] are divine, drawing their power from the Night Elf goddess, [[Elune]].\r\n===Nature===\r\nNature magic involves drawing upon the spirits of the earth to invoke natural phenomenon.\r\nShamans draw upon the power of the elements, creating a personal relationship with each of the five elements (Fire, Water, Air, Earth, and Wilds) and asking for their assistance when it becomes necessary. This procedure is unlike the elemental practices of arcane or fel magicians, who use their manipulation over the physical universe to command the loyalty of elementals at their leisure.\r\n \r\nDruidism draws its mastery over the natural world from the [[Emerald Dream]], where the [[Spirit of the Wilds]] and the spirits of all living things in the universe reside. Unlike in shamanism, a druid makes a physical connection between his/her spirit and the spirits of the Dream, becoming literally a part of the natural world. This explains the way all druids appear to have foliage growing from them, and their ability to shape-shift, because their spirit has made itself one with all other living things.\r\nThere are [[arcane druids]], who use supernatural forces to command a link between themselves and the Dream. Though this practice does require an advanced knowledge of the Emerald Dream, it does not necessitate the close connection and respect of the natural world that true druidism does.",},
			["Maginor Dumas"] = { content = "'''Maginor Dumas''' is a level 60 [[mage trainer]] located in the [[Wizard's Sanctum]] in [[the Mage Quarter]] within the [[humans]] city of [[Stormwind]].\r\nHe is likely related to [[Elissa Dumas]], and maybe [[Torgal]].\r\nSee [[List of Stormwind NPCs]].",},
			["Magister's Crown"] = { content = "==Source==\r\nThis item drops from [[Darkmaster Gandling]] in [[Scholomance]].\r\n==Magister's Crown as a quest objective==\r\nThis item is an objective for the following quests:\r\n* Saving the Best for Last (Alliance)\r\n* Saving the Best for Last (Horde)",},
			["Magister's Terrace"] = { content = "#REDIRECT [[Magisters' Terrace]]", redirect = "Magisters' Terrace",},
			["Magisters' Terrace"] = { content = "'''Magisters' Terrace''' is a 5-man instance located on the northeastern corner of the [[Isle of Quel'Danas]], which was released in [[patch 2.4.0]]. The instance includes outdoor walkways and courtyards, as well as indoor areas that use similar architecture as [[Silvermoon City]]. There is a [[Scrying Orb (Magisters' Terrace)|Scrying Orb]] found on a balcony past the second boss that gives a sneak peek of the nearby [[Sunwell Plateau]] raid. Following this, players meet with [[Kalec]], the half-elf avatar of the [[blue dragon]] [[Kalecgos]]. The final boss is none other than [[Kael'thas Sunstrider (Magisters' Terrace tactics)|Kael'thas Sunstrider]], who has survived his ordeal in [[Tempest Keep]]. He appears in both normal and heroic modes and drops epic level loot from both levels of difficulty.\r\n==Background==\r\nDuring the [[Scourge invasion of Quel'Thalas]], after [[Dar'Khan Drathir]] killed half of of the [[Convocation of Silvermoon]], the traitorous high elf hid in a hall of the Magisters' Terrace and started a spell of binding the Sunwell and shot a fireball outside to let his [[Arthas Menethil|Master Arthas]] know that the time has come to invade Quel'Danas.\r\nSituated on a ridge in northeastern Quel'Danas, Magisters' Terrace serves as a convenient base for Kael'thas and his underlings as they assist the proceedings in the [[Sunwell Plateau]]. Kael'thas stands poised to desecrate the ancient lands of his people with an incomparable evil. Should he succeed, the Legion's darkness will rapidly spread to all corners of Azeroth, extinguishing everything in its path.\r\n===Dungeon Journal===\r\n''After his defeat in the [[Tempest Keep]], [[Kael'thas Sunstrider]] publicly revealed his alliance with the ruthless [[Burning Legion]]. Intent upon summoning the demon lord [[Kil'jaeden]], Kael'thas has returned to the [[Isle of Quel'Danas]] to make the final preparations for his master's arrival.''\r\nKael'thas SunStrider, disgraced lord of the blood elves, made his final stand in the terrace and ultimately lost his life. He was buried on Quel'Danas.\r\nThe blood elves continue to care for the terrace. [[Swift White Hawkstrider|Kael'thas' hawkstrider]] is looked after here, as well as a [[Phoenix Hatchling|rare phoenix hatchling]]. The terrace has become something of a museum since the war on Outland: items and artifacts reclaimed from the Sunwell have found their way here, others having been donated anonymously. [[Apolyon, the Soul-Render]] and [[Thori'dal, the Stars' Fury]] are two notable items in the blood elves' keeping. The possessions and artifacts of the fallen Sunstrider dynasty are given places of honor in the terrace.\r\nMagisters' Terrace is where the [[Trial of Style]] is held. [[Shadreen]] made a brief appearance here, collecting some information.\r\n===Normal mode===\r\nA full Magisters' Terrace clear will yield around 1640 reputation with the [[Shattered Sun Offensive]] up to [[revered]], while after revered with the faction you will only get 1230 reputation. Most elite trash yield 12 reputation. [[Sunblade Sentinel]]s yield 24 reputation. The Wretched [[Wretched Bruiser|Bruisers]], [[Wretched Husk|Husks]] and [[Wretched Skulker|Skulkers]] yield 9 reputation. The first three bosses yield 120 reputation until revered (0 after revered), while [[Kael'thas Sunstrider (Magisters' Terrace tactics)|Kael'thas]] yields 240 reputation until revered (120 after revered). [[Brightscale Wyrm]]s yield 1 reputation until revered (0 after revered).\r\n===Heroic mode===\r\nA full clear will yield exactly 2503 reputation with the [[Shattered Sun Offensive]]. Most elite trash yield 15 reputation. [[Sunblade Sentinel]]s yield 30 reputation. The Wretched [[Wretched Bruiser|Bruisers]], [[Wretched Husk|Husks]] and [[Wretched Skulker|Skulkers]] yield 11.25 reputation. All the bosses yield 250 reputation each. [[Brightscale Wyrm]]s yield 2 reputation.\r\nMost of the boss fights are the same as in normal mode. The Kael'thas fight is a little different in that he casts a Pyroblast one minute into the fight (won't cast it if he enters gravity lapse mode before that). During the cast time he puts up a shield (Shock Barrier, absorbs 10K damage) which makes him immune to all interrupts. The shield is vulnerable to normal attacks and MUST be taken down before the Pyroblast casts. Once the shield is down, normal spell interrupts (counterspell, shield bash, kick etc.) will stop the casting. If the Pyroblast is not interrupted it will deal upwards of 40,000 damage to the tank. Pally tanks can bubble out of the first pyroblast, and it is suggested that if dps isn't able to burn through the Shock Barrier that a warrior tank pop shield wall and last stand, it is possible that this might enable him to live through 1 pyroblast but should a 2nd come he has no recourse. If you fail to stop the Pyroblast and your tank goes down, you can still easily finish. For at this point there is no aggro, Kael just spams the gravity effect\r\n===At Level 85===\r\nFor those solo farming Shattered Sun reputation or for the mount or pet drops, Magisters' Terrace is fairly easy at level 85, but not a total walk in the park. Carelessness can result in dying to the mob groups after Vexallus, as they have an assortment of close-in and ranged abilities that can prove dangerous if not accounted for properly, depending on one's class. As for the bosses, Selin Fireheart and Vexallus are rather easy DPS races at this level, as is Kael'thas Sunstrider (Magisters' Terrace tactics) (though unless one has exceptional DPS, he will cast his gravity lapse, which is little more than an annoyance). The Priestess Delrissa encounter, however, does require a little planning, as the assortment of stuns available to her group (depending on which ones are present) can make this encounter a challenge for cloth-wearing characters if one is not careful. As for gold farming, the mobs usually drop between 50 silver and one gold each, though sometimes (considerably) less. With the gold from selling the drops off the bosses and mobs, one can usually realize between 100-200 gold for a full heroic run, minus repair costs.\r\n==Quests==\r\n*[[Severed Communications]]\r\n**[[The Scryer's Scryer]]\r\n***[[Hard to Kill]]\r\n*[[A Radical Notion]]\r\n*[[Twisted Associations]]\r\n*[[WANTED: Sisters of Torment]]\r\n*[[WANTED: The Signet Ring of Prince Kael'thas]]\r\n==Related achievements==\r\n*[[Magister's Terrace (achievement)]]\r\n*[[Heroic: Magister's Terrace]]\r\n*[[Heroic: Magister's Terrace Guild Run]]\r\n*[[Swift White Hawkstrider (achievement)]]\r\n==Notes==\r\n*Magisters' Terrace was the third 5-man instance to be added via patch. The first was [[Maraudon]] in [[Patch 1.2]] and the second was [[Dire Maul]] in [[Patch 1.3]], which opened in December 2004 and March 2005, respectively. The next 5-man instance to be added via patch would be [[Trial of the Champion]] in [[Patch 3.2]], released in August 2009.\r\n*For a time this was the only dungeon to contain a [[Cut Scene|cut scene]] while playing the game. It has later been joined by others such as [[Throne of the Tides]], [[Gate of the Setting Sun]], [[Shadowmoon Burial Grounds]] and [[Kings' Rest]]. Most other cut scenes in-game happen when you first create a new character or for a few specific quests.\r\n*A standardized abbreviation for the instance has yet to be decided upon. Among the various player-created abbreviations seen in game are the following: MgT, MsT, MrT (presumably after [[Wikipedia:Mr. T|Mr. T]]), MT (causes ambiguity problems with [[Mana-Tombs]]), QD5 (Quel'Danas five-man), SPLAT5 (Sunwell Plateau five-man), Terrace, and MagT (differentiated from Magtheridon by the capital T at the end). Blizzard Community Manager [[Drysc]] commented on the official forums: \"I think MST makes the most sense, Magisters' Terrace. But MGT works too.\" For German players the abbreviation \"TdM\" is common. \"Bancal\" is the most common abbreviation for Spanish players.\r\n*It is also worth noting that this dungeon is kind of like a \"best of\" [[The Burning Crusade]]. The bosses each take something from one core aspect of Burning Crusade, but tune it down (or keep it at a similar difficulty). The First boss, Selin Fireheart, is very similar to [[Warlord Kalithresh]], a 5-man final boss. The second boss, Vexallus, is similar to [[The Curator]], a boss from the 10-man, [[Karazhan]]. The 3rd boss, is similar to [[Moroes]], or even more so (due to the difficulty to tank it) a 5v5 [[Arena]]. And the final boss Kael'thas, is similar to a fight from a 25-man raid. Thus this dungeon takes the core aspects of 5-man dungeons, 10-man dungeons, PvP, and 25-man endgame, and tunes it down to a 5-man encounter.\r\n*Groups had to come prepared to this instance as the level of difficulty was greater than the hardest of the level 70 5-man instances like [[Shattered Halls]] and [[Shadow Labyrinth]], and was on a similar level to that of beginning heroics such as [[Hellfire Ramparts]] and [[Underbog]]. On heroic mode Magisters' Terrace was one of the most difficult five man experiences at level 70.\r\n*Behind Kael'thas is an [[Orb of Translocation]] (\"Escape to the Isle of Quel'Danas\") that ports you to [[Vindicator Xayann]] at the [[Shattered Sun Staging Area]].\r\n==Patches and hotfixes==\r\n*",},
			["Magisters"] = { content = "'''The Magisters''' are a group of [[Blood Elf]] mages and warlocks and one of three factions in the government of [[Silvermoon City]] and all of [[Quel'thalas]]. They are led by [[Grand Magister Rommath]]. Out of the three main factions within Silvermoon, the Magisters are probably the oldest, as the [[Highborne]] exiles who originally conceived the nation were mages, first and foremost, before they began to compose their ranks with those trained in archery and martial combat.\r\n= History =\r\n===Origin===\r\nThe Magisters' exact origin and time of ascension to authority are unknown, but it is presumable that they existed maybe before, or during the founding of Quel'thalas. They have been Silvermoon's top authority on all things pertaining to magic, and have been in possession of a vast reservoir of knowledge on all things arcane, for many years. \r\n===Recent Activities===\r\nAfter [[Kael'thas]]'s departure to [[Outland]], the Magisters have taken a more direct approach to gaining power within Silvermoon's political climate. Their authority on magic has led to them having an easily establishable sense of power over the addicted masses of Silvermoon and thus, allow them to control many citizens with ease. They are true to the Jingoist philosophy that Elves have always practiced, although after the [[Third War]], they have begun to enforce it rigorously.\r\nThey've also constructed large, green crystals (known as \"The Burning Crystals.\"), filled with demonic essence, all around Silvermoon, so that the Blood Elves may easily restore their energies, as well as to empower the various extravagances that Blood Elves enjoy indulging in. The need for these has become apparent as many of the Arcane Sanctums in the land have either begun to weaken or malfunction due to the various problems caused by the [[Scourge Invasion]].\r\n===Ranking System===\r\nThere are several ranks within the Magisters, each one a title that showcases their mastery of the arcane, as well as their importance within the order.\r\n*Grand Magister - Leader and overseer\r\n*Magister / Magistrix - A position similar to a Magistrate.\r\n*Arcanist - A middle-ranked mage, with a slight amount of authority.\r\n*Apprentice - A newly inducted member into the order.\r\n=Known Members=",},
			["Magister Astalor Bloodsworn"] = { content = "'''Magister Astalor Bloodsworn''' is a powerful [[blood elf]] Wizard, who was the first person on [[Azeroth]] to come into contact with the [[naaru]], a group of sapient energy beings aligned with the Holy Light. After the capture of [[M'uru]], the naaru guardian of [[Tempest Keep]], Astalor had the naaru returned to [[Silvermoon City]] and imprisoned, and several mages began harnessing the naaru's natural Light energy. At first, the Magister was hesitant to use these powerful energies, as the blood elves would be effectively going back to their previous high elven, Light-following ways, something that was completely opposite to what the blood elves are now. However, Light or no, it was still magical energy to be fed on by his people.\r\n[[Lady Liadrin]], a former priestess, was the first blood elf to offer herself to test the powers, thus becoming the first [[Blood Knight]].\r\n==See also==\r\n* in the .",},
			["Magister Duskwither's Journal"] = { content = "==Source==\r\nTaken from the [[Magister Duskwither's Journal (object)|Magister Duskwither's Journal]] in [[Eversong Woods]].\r\n==Objective of==\r\n*Abandoned Investigations",},
			["Magister Hawkhelm"] = { content = "'''Magister Hawkhelm''' is a level 52 [[rare mob]] [[blood elf]] found in [[Azshara]]. She accompanied [[Magus Rimtori]] on her expedition.\r\nSee [[List of blood elves in Azeroth]].",},
			["Magister Ilastar"] = { content = "'''Magister Ilastar''' is a level 70 [[blood elf]] [[quest giver]] located in the [[Sun's Reach Armory]] of the [[Isle of Quel'Danas]].\r\nHe is involved in the following quests:\r\n*Taking the Harbor†\r\n*Crush the Dawnblade",},
			["Magister Kaendris"] = { content = "'''Magister Kaendris''' is a level 20 [[quest giver]] located at [[Sanctum of the Sun]] in the [[blood elf]] territory of [[Ghostlands]].\r\nHis name is very similar to that of [[Magister Kalendris]], a mini-boss in [[Dire Maul]].\r\n==Quests==\r\n* Report to Magister Kaendris \r\n* The Farstrider Enclave \r\n* The Twin Ziggurats \r\n* The Traitor's Destruction \r\n** Hero of the Sin'dorei &ndash;OR&ndash;\r\n** Friend of the Sin'dorei (''If not a blood elf'')\r\n==See also==\r\n[[List of Ghostlands NPCs]]",},
			["Magister Theledorn"] = { content = "'''Magister Theledorn''' is a level 68 [[quest giver]] located on the south side of [[Manaforge Ara]] in the [[contested]] territory of [[Netherstorm]].\r\nHe starts the quest Damning Evidence.\r\nSee [[List of Netherstorm NPCs]].",},
			["Magistrate's Temple"] = { content = "#REDIRECT [[Magistrates Temple]]", redirect = "Magistrates Temple",},
			["Magistrate Barthilas"] = { content = "'''Magistrate Barthilas''' is a level 58 [[elite]] [[wight]] [[mini-boss]] found in the [[Scourge]] side of [[Stratholme]].\r\n==Background==\r\n'''Barthilas''' was an ambitious [[paladin]] who served under [[Tirion Fordring]] at [[Mardenholde Keep]]. He ''may'' be the same character as Magistrate Barthilas.\r\nBarthilas was ordained a paladin just as the [[Second War]] ended, a war which claimed his parents' lives, and left the young man a deep hatred for all [[orc]]s. When [[Tirion Fordring|Tirion]] was found injured and unconscious, Barthilas immediately assumed that he had been attacked by an orc, and began to scour the countryside for a force of them.\r\nAfter Barthilas discovered that Tirion had protected the orc [[Eitrigg]], he personally oversaw the paladin's persecution, as well the plans for the torture and execution of the orc, only to see Eitrigg rescued.\r\nBarthilas eagerly assumed his new position as head of Mardenholde, but was killed shortly afterwards, during [[Thrall]]'s raid on Stratholme, his title eventually passing to Tirion's son [[Taelan Fordring]].\r\n==Location==\r\nThe Magistrate can be found in two locations in [[Stratholme]]. If the party enters through the eastern gate (typically referred to as the dead side or the Baron side), the Magistrate sounds an alarm and runs from just inside the instance to the gates just before the Baron. If the party enters through the western gates (typically referred to as the main gates or Strat Scarlet Side or the living side), he remains near the eastern entrance in front of [[Aurius]]. \r\nSee the at Worldofwar.net for a layout of [[Stratholme]]. The location marked as 6 is where he is located when entering though the Scarlet Side gates. The location for the Baron side is unmarked, but it is between 10 and 12 ([[Maleki the Pallid]] and [[Ramstein the Gorger]]).\r\nThis is only important if you are trying to farm the Magistrate for drops. In particular, the druid idol ([[Idol of Brutality]]) that drops from the Magistrate is excellent for bear druids and the quickest way to get to him is by entering through the Scarlet Side gates.\r\n==Strategy==\r\nThis fight is fairly straightforward, with one caveat. When tanking the Magistrate, it is best to have the tank back up against a wall, as this mob will punt the player with aggro a fairly good distance. In addition, if mobs were skipped near the gate, it is possible to be punted into them. \r\nThe punt effect is either a complete threat wipe or a large threat reduction that will hit the character currently tanking the Magistrate. It is important that dps run towards the tank rather than away from the tank if the Magistrate targets them following a punt. He is tauntable so it's easy to establish threat after the punt if the tank can reach him.\r\n==Memorable Quotes==\r\n*\"The future of our people is no longer your concern. I rule Hearthglen now, Tirion. And as long as I do, I swear there will never be peace with the orcs! On my parents' departed souls, I swear that every last orc in Lordaeron will burn for what they've done!\"",},
			["Magistrate Bluntnose"] = { content = "'''Magistrate Bluntnose''' is a level 20 [[quest giver]] located in [[Thelsamar]] in the [[dwarven]] territory of [[Loch Modan]].\r\nMagistrate Bluntnose, Thelsamar's mayor, keeps the village safe and orderly.\r\nHe starts the quest Mercenaries (Elite).\r\nSee [[List of Loch Modan NPCs]].",},
			["Magistrate Burnside"] = { content = "'''Magistrate Rutherford Burnside''' is a level 30 [[human]] found near [[Hillsbrad]] in the [[Hillsbrad Foothills]]. He is the current leader of the [[Hillsbrad Fields]].\r\n[[High Executor Darthalia]] wants Burnside killed in order to disrupt the leadership of the Hillsbrad.\r\nHe may be related to the bankers in [[Stormwind]].\r\n==Abilities==\r\n* Inferno Shell\r\n* [[Fireball]]\r\n* Fire Nova\r\n==Objective Of==\r\n*Battle of Hillsbrad (4)",},
			["Magistrate Henry Maleb"] = { content = "'''Magistrate Henry Maleb''' is a level 60 [[elite]] [[quest giver]] located in the [[Southshore Town Hall]] in the [[contested]] territory of [[Hillsbrad Foothills]].\r\nHe starts the following quests:\r\n* Syndicate Assassins\r\n* Noble Deaths\r\n* Dark Council\r\n* Baron's Demise\r\nSee [[List of Hillsbrad Foothills NPCs]].\r\n==Timeline issue==\r\nMagistrate Henry Maleb can also be found in the [[Old Hillsbrad]] dungeon in the [[Caverns of Time]], years younger but already positioned in the Town Hall of [[Southshore]]. This is quite strange, since in the quest \"Syndicate Assassins\" referenced above, his present-day self claims that he only just attained the position of magistrate:\r\n* \"I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate. The assassins were never found, but through our investigations we're almost certain they were hired by the [[Syndicate]] - a group of thieves led by villainous nobles of the now fallen kingdom of [[Alterac]].\"\r\nThis would make his presence as Magistrate in the Southshore of the past utterly impossible; yet there he is.\r\nAn explanation to this can be that in the 7 years, he lost the position and recently regained it...or perhaps it was his 'father' (of the same name) who was killed.",},
			["Magistrate Marduke"] = { content = "'''Magistrate Marduke''' is a level 57 [[quest giver]] located by the entrance to the [[Scholomance]] on [[Caer Darrow]] in the [[contested]] territory of [[Western Plaguelands]]. He is normally [[invisible]], and can only be seen once the player has equipped the Spectral Essence item from the quest Kirtonos the Herald.\r\nHe starts the following quests:\r\n*The Human, Ras Frostwhisper (Elite)\r\n*The Dying, Ras Frostwhisper (Elite)\r\n*The Lich, Ras Frostwhisper (Dungeon)\r\nSee [[List of Western Plaguelands NPCs]].\r\n==The Magistrate's Quest==\r\n*The following conversation leads into the Ras Frostwhisper questline.\r\n''Some were spared the anguish that memories provide.''\r\n Tell me about the [[Cult of the Damned]].\r\n''The Cult of the Damned has grown large in scope. Nearly every city, from the capitals to the small hamlets and hovels of both the [[Horde]] and [[Alliance]], have Cult members hidden amongst their citizenry.''\r\n''Do not look so surprised. The Cult only wears a uniform for ritual and ceremony. It is quite possible that you have interacted with one during your adventures and not even known.''\r\n Impossible.\r\n''Is it? This has always been their method of operation. What is of greater value to [[Kel'Thuzad]] and the ever growing [[Scourge]] army? A zealous, living, follower that can work their way into a society and then unleash a [[Plague of Undeath|plague]], destroying thousands; or a single undead trooper? Certainly you cannot be that dense''\r\n''Yes, <race>, they live, work, and plot among you.''\r\n This is disheartening. Is there anything I can do to stop this?\r\n''Stop - no. Slow down - maybe.''\r\n''The Scholomance is their primary source of training and education. It is from there that the Cult members fan out and ultimately, make their way into our societies.''\r\n''That is why we must strike at the source. The very heart of the Cult of the Damned!''\r\n Who do I need to kill?\r\n''Slow down, <race>. The one you need to kill is already dead. Killing him again will serve no purpose. There are very few ways in which a lich can actually be destroyed and none of those means are available to you or I. That is why I have a plan. A plan that will have a very noticeable and real impact upon the Cult.''\r\n What is this plan?\r\n''It's simple, really. Rob the [[lich]], [[Ras Frostwhisper]], of his powers. Return him to his mortal form and then slay him, once and for all.''\r\n Ras Frostwhat? Who is that?\r\n''Ah, I suppose that I am getting ahead of myself. Ras Frostwhisper is the overseer of this school. The being responsible for training all of its Dark Masters. A lieutenant and favored pupil of Kel'Thuzad. He was once a hedge mage of [[Stromgarde]]: A rogue wizard that never received his formal training from [[Dalaran]].''\r\n''When Kel'Thuzad opened the Cult, Ras was among the first to join his ranks. Ras knew that through dark magic, he would find immortality.''\r\n Continue, please.\r\n''Magistrate Marduke:''' And find it he did. After quickly advancing through the ranks of the Cult, the [[Lich King]] himself granted Ras immortality. Thus was born Ras Frostwhisper, the lich.''\r\n''Now do you understand?''\r\n Yes I do.\r\n''Good. In order to carry out my plan, we must first create a lifestone. Are you prepared to act?''\r\n Yes I am.",},
			["Magistrate Randalvarr"] = { content = "'''Magistrate Randavarr''' is the [[half-elf]] ruler of the town council of the township of [[Valgarde]] in the [[Howling Fjord]]. He is a skilled [[scout]] and [[warrior lore|warrior]].",},
			["Magistrate Sevren"] = { content = "'''Magistrate Sevren''' is a level 14 [[quest giver]] located in the [[Brill Town Hall]] in [[Brill]], in the [[Forsaken]] starting zone of [[Tirisfal Glades]].\r\n==Quests==\r\n* Graverobbers\r\n* The Prodigal Lich\r\n* Forsaken Duties\r\n* The Family Crypt\r\n* Raleigh and the Undercity\r\n* Return to the Magistrate\r\n* Speak with Sevren\r\n* The Engraved Ring\r\n==Quotes==",},
			["Magistrate Solomon"] = { content = "'''Magistrate Solomon''' is a level 36 [[quest giver]] located in the [[Lakeshire Town Hall]] in the human-aligned zone of [[Redridge Mountains]]. \r\nMagistrate Solomon, is the most serious person in the town of Lakeshire. He is the elected ruler of Redridge Mountains. He is dedicated to keeping the town safe from [[orcs]] and [[gnolls]]. He is short on supplies and always on the lookout for mercenaries.\r\nHe starts the following quests:\r\n* Messenger to Stormwind\r\n* Messenger to Westfall\r\n* Messenger to Darkshire\r\n* The True Masters\r\n* The True Masters\r\nSee [[List of Redridge Mountains NPCs]]",},
			["Magistrix Aminel"] = { content = "'''Magistrix Aminel''' is a level 16 [[quest giver]] located on top of the inn in [[Tranquillien]] in the [[blood elf]] territory of [[Ghostlands]]. She encourages visitors to her town to fight [[Scourge]] in the [[Dead Scar]] by offering rewards for turning in special items that drop from the undead there.\r\nShe starts the following quests:\r\n* Rotting Hearts\r\n* More Rotting Hearts (Repeatable)\r\n* Spinal Dust\r\n* More Spinal Dust (Repeatable)\r\nSee [[List of Ghostlands NPCs]].",},
			["Magistrix Carinda"] = { content = "'''Magistrix Carinda''' can be found in [[Hellfire Peninsula]] at [[Falcon Watch]] with her pet cat, [[Twinkle]]. She asks the player to retrieve the journal of her dead husband, beginning a short chain of quests.\r\n==Quests== \r\n==Quote==\r\nMy husband's been missing for days. We went on this pilgrimage together; we were supposed to finish it together.\r\nAll this worry has gotten me tapping into mana crystals more often than I really should.",},
			["Magistrix Elosai"] = { content = "'''Magistrix Elosai''' is a level 28 [[Blood Elf]] [[quest giver]] located in [[Freewind Post]] in the [[contested]] territory of [[Thousand Needles]]. She can be found on the east side of the post (46,50) and was added with patch 2.0.1, \"Before the Storm\".\r\n==Quests==\r\nShe starts the following quest:\r\n*A Different Approach\r\nShe ends the following quest:\r\n*Testing the Tonic\r\nSee [[Thousand Needles NPCs]] and [[list of blood elves in Azeroth]].\r\n==The wretched Elosai==\r\nElosai has been exiled into the [[Thousand Needles]] because she has been researching for a cure to the [[Blood Elf|Blood Elves']] magical addiction. In the end though, her cure fails, instead of curing her addiction the tonic accelarates it causing her to become a Wretched. She is understandably upset by the effects of her concoction and despairs that her years of research have been for nothing. She miserably wonders whether the other [[Blood Elf|Blood Elves]] were right and that their magical addiction is something they must live with, that cannot be overcome.",},
			["Magistrix Eredania"] = { content = "'''Magistrix Eredania''' is a level 16 [[enchanting trainer]] located at [[Saltheril's Haven]] in the [[blood elf]] territory of [[Eversong Woods]].\r\nSee [[List of Eversong Woods NPCs]].",},
			["Magistrix Erona"] = { content = "'''Magistrix Erona''' is a level 5 [[quest giver]] located on [[Sunstrider Isle]] in the [[blood elf]] starting zone of [[Eversong Woods]].\r\nShe starts the following quests:\r\n* Reclaiming Sunstrider Isle\r\n* Hunter Training\r\n* Mage Training (Blood Elf)\r\n* Paladin Training\r\n* Priest Training (Blood Elf) \r\n* Rogue Training\r\n* Warlock Training\r\n* Unfortunate Measures\r\n* Report to Lanthan Perilon\r\nSee [[List of Eversong Woods NPCs]].",},
			["Magistrix Fyalenn"] = { content = "'''Magistrix Fyalenn''' is a level 73 [[quest giver]] located on the [[Scryer's Tier]] of the [[neutral]] [[Shattrath City]]. Fyalenn is located by the entrance to [[the Seer's Library]], coords 45,81.\r\nShe starts the following quests:\r\n* Firewing Signets\r\n* Single Firewing Signet (Repeatable)\r\n* More Firewing Signets (Repeatable)\r\n* Sunfury Signets\r\n* Single Sunfury Signet (Repeatable)\r\n* More Sunfury Signets (Repeatable)\r\nThese are used to gain faction with the [[Scryers]].\r\nSee [[List of Shattrath City NPCs]].",},
			["Magistrix Seyla"] = { content = "'''Magistrix Seyla''' is a female [[blood elf]] [[quest giver]] riding a [[dragonhawk]] located at the [[Throne of Kil'jaeden]] in [[Hellfire Peninsula]].\r\nShe is involved in the following quests:\r\n*The Missing Magistrix\r\n*Blood for Blood\r\n*Blast the Gateway\r\n==See also==\r\n*[[Hellfire Peninsula NPCs]]",},
			["Magis Sparkmantle"] = { content = "'''Magis Sparkmantle''' is a level 10 [[mage trainer]] located in [[Thunderbrew Distillery]] in [[Kharanos]], in the [[dwarven]] starting zone of [[Dun Morogh]].\r\nHe starts the quest Speak with Bink.\r\nSee [[List of Dun Morogh NPCs]].\r\n==Inspiration==\r\nMagis is a Jesuit phrase that means \"the more\".",},
			["Magmadar"] = { content = "A terrifying behemoth composed of igneous rock and roiling magma, '''Magmadar''' serves as the origin of the core hounds that roam the earthen halls of [[Molten Core]]. Favored among [[Ragnaros|Ragnaros's]] pets, Magmadar is protected by the flamewaker [[Lucifron]] and surrounded by vicious packs of ravenous hounds. It is said that while Ragnaros was imprisoned in the [[Elemental Plane]], the Firelord would feed the remains of his captured enemies to the eagerly awaiting twin maws of Magmadar. As a result, the hound grew strong and loyal, and even now Magmadar's savage ferocity remains uncontested.\r\nHe lives within [[Magmadar Cavern]] guarding the [[Rune of Kress]]. He is found directly behind [[Lucifron]].\r\n==Attacks and abilities==\r\n*Magma Spit\r\nDeals 93-107 Fire damage and an additional 75 Fire damage every 3 seconds for 30 seconds. Stacks up to 3 times.\r\nSchool: Fire\r\nRange: ?? yards\r\n*Lava Breath\r\nInflicts 1157 to 1343 Fire damage to enemies in front of the caster.\r\nSchool: Fire\r\nRadius: 35 yards\r\n*Panic\r\nPanics nearby enemies, causing them to flee in fear for 8 sec.\r\nType: Magic\r\nSchool: Shadow\r\nRadius: 30 yards\r\n*Lava Bomb\r\nThrows a Lava Bomb at an enemy, creating a fire that inflicts 3200 Fire damage over 8 sec.\r\nSchool: Fire\r\nRange: 100 yards\r\nFire Radius: 5 yards\r\n==Strategies==\r\nThe main tank should pull Magmadar so that he is facing towards the main group of healers, hunters, etc. Healers need to stand at max range behind the main tank. To find max range get to where you are too far away to heal the main tank and then slowly get closer until you are in range. If you are at max range you will be able to heal the tank, but too far away to be affected by the AOE fear. Priests should keep Fear Ward on the main tank. Hunters must use Tranquilizing Shot (a learned skill that comes from a tome with a 100% drop rate from Lucifron) when he frenzies, they must pay attention to the order they use it in and whether it is a hit or a miss. Melee DPS should come in on the sides and behind Magmadar. They need to be sure to avoid the Conflagrate and will be responsible for removing themselves from battle and bandaging since they will be out of range of the healers. If Fear Ward is not available, the warrior can \"stance dance\" in and out of berserker stance in order to use Berserker's Rage about every 30 seconds to avoid being feared. It is important that the main tank doesn't get feared - otherwise, while aggro will no longer be lost, Magmadar will follow the fleeing tank and the healers will suddenly be in range of him, and it is unlikely that the raid group will recover.\r\n*A guild new to Magmadar may wish to have 2 groups of MT healers, only one of which is on the MT at a time. If the group that is actually healing the MT gets feared, the other group rushes in. My guild used this method until the healers became better at staying just out of AoE fear range. We found that 2&ndash;3 healers per group is enough so long as the hunters are quick with the tranq shots.\r\n*The BoJ setup method: The easiest way to control the encounter is having healers and ranged DPS classes outside the fear range from the start. The trick to this is setting up the pull. Have your main tank walk up to maximum bow range from Magmadar and stay there. Now have your healers adjust position so they are just in healing range of the main tank. Healing range is 40 yards, and AoE fear range is 30 yards, so this should be easy. (Hint: if you can cast dispel or cleanse on the main tank, you are too close.) Hunters and mages with extended range now move to the same radius as the healers, but may need to move in a little to get range once the encounter starts. The healers and ranged DPS should be in a semi-circle and spread out to reduce the chances of a multiple people being affected by a conflag puddle. Once the healers and ranged DPS are in position, the main tank pulls Magmadar with a bow/gun.\r\n==Reward==\r\nLoot: He can be skinned for Core Leather. All [[Tier 1]] set leggings drop from Magmadar.\r\nReputation: 100 Reputation with the [[Hydraxian Waterlords]] at revered.\r\n==Notes==\r\n* Magmadar's name is clearly a reference to magma, the name used for lava yet exposed to the surface.\r\n* Magmadar's spawn point is next to one of the Runes you will need to douse with [[Aqual Quintessence]].\r\n* After Magmadar is defeated, the [[Ancient Core Hounds]] and [[Core Hound Pack]]s will no longer spawn in the zone until the weekly instance reset. Additionally, any [[Ancient Core Hounds]] in the instance will despawn after a soft instance reset. The lack of wandering Core Hounds makes the early part of the instance much easier to deal with for newer groups.\r\n* See other Molten Core [[Molten_Core|Bosses]].",},
			["Magma Elemental"] = { content = "'''Magma Elemental''' are [[lava elemental]] mobs, and can be found in [[Searing Gorge]] .\r\n==Drops == \r\n \r\n0.03% Chance of an [[epic]] drop.\r\n0.07% Chance of a [[rare]] drop.\r\n0.81% Chance of an [[Uncommon]] drop.\r\n0.03% Chance of a [[common]] drop.\r\n0.01% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Magma Fields"] = { content = "'''Magma Fields''' are a green-glowing lava pool-filled set of plains in western [[Shadowmoon Valley]]. It is populated with felfire [[diemetradon]]s.",},
			["Magma Lord Bokk"] = { content = "'''Magma Lord Bokk''' is a level 60 [[lava elemental]] found in the [[Burning Steppes]]. [[Mux Manascrambler]] wants a piece of Bokk.\r\n==Location==\r\nYou can find him hanging out at the northern tip of the lava pool (shown on the map) that's just west of the [[Pillar of Ash]].\r\n==Strategy==\r\nHe is quite easily soloable in basically every way. He moves slowly, he's stunnable, he doesn't hit that hard, he has relatively low HP, you name it. He does interrupt casting by throwing [[Earth Shock]] often, and he has a knockback attack.\r\n==Quests==\r\n*A Portable Power Source\r\n==Loot==\r\n*Magma Core ''(Quest Item)''",},
			["Magma Totem"] = { content = "'''''Feel heat? Don't worry, it's not you. Everyone else around is feeling it.''''' \r\n'' Summons a Magma Totem with 5 health at the feet of the caster for 20 sec that causes '''XX''' Fire damage (see [[Magma Totem|Description]] by rank level) to creatures within 8 yards every 2 seconds.'' \r\nThis totem pulses every two seconds, damaging all enemies nearby for XX damage. It is one of the Shaman's two [[AoE]] attacks, doing it as a [[DoT]] instead of a single burst. It pulls a significant amount of aggro, and will quickly be destroyed by mobs unless you consistently damage all of them, or have something else holding their attention.\r\n'''''Note:''' Not very useful against a single opponent, but it's great for whittling down the health bars of groups of opponents when grouped.''\r\n===Use===\r\n*'''Casting Time:''' Instant Cast\r\n*'''Range:''' Not Applicable\r\n*'''Duration:''' 20 seconds\r\n*'''Cooldown:''' Global Totem Cooldown\r\n===Limitations===\r\n*Must be within 8yd radius of the totem.\r\n*The totem (at any rank) has only 5 hp; it is easily destroyed by mobs and players.\r\n*Useless against high [[element|Fire resistant]] players/[[mob|mobs]].\r\n*Generates a high amount of threat.\r\n===Talents===\r\nTalents that can improve the totem:\r\n===Tips===\r\n*This totem is particularly useful in PvP against stealthed rogues.\r\n*In Patch 1.3.0, it was changed to cause much more [[aggro]], so now it'll probably only get off one attack, and then be destroyed by one of the [[NPC]]s you're attacking. Previously, it wouldn't generate any aggro. Magma Totem has the advantage (if one could call it that) of being an extremely weak AoE, so if any other player has used one, Magma Totem will not draw sufficient aggro for monsters to attack it.\r\n* Solo, this totem is useful if you open the fight with a [[Chain Lightning]]. Any mobs that your lightning does not hit, you should engage and swing at a few times, then drop Magma Totem.\r\n* If you drop a [[Stoneclaw Totem]], it will generate enough threat that the Magma totem will survive to do the majority of its damage.",},
			["Magmus"] = { content = "'''Magmus''' is a level 56 [[elite]] fiery [[Molten Giant]] [[mini-boss]] found in the Iron Hall in [[Blackrock Depths]].\r\nMagmus protects the Emperor's Seat from penetration by any interested adventurers. When forced into battle, Magmus triggers statues in the Iron Hall to spew fire. The fire can be avoided by standing between statues while taking down Magmus.\r\n==Loot==\r\n*Golem Skull Helm\r\n*Lavastone Hammer\r\n*Libram of Truth\r\n*Magmus Stone\r\n*Totem of Rage",},
			["Magnataur"] = { content = "'''Magnataur''' are creatures that can be encountered in the upcoming [[World of Warcraft: Wrath of the Lich King|WotLK expansion.]]\r\n''Magnataur have the torso of a giant attached to the body of a mammoth. This peculiar appearance has sparked speculation that their race might be related to [[centaur]] or even [[Keepers of the Grove]]. Many wonder if these races share a common ancestor, and some have even suggested [[Cenarius]] himself.\r\n''The notoriously long-lived magnataur are rumored to engage in cannibalism during times when food is scarce. Single males are known to control giant herds and produce sizable litters, but in the frigid, perilous wastes at the roof of the world, only the strongest and meanest survive.\r\n''Despite their hostility to most races, the magnataur have become tolerant of the [[Snobold|arctic kobold]]s, who follow the herds for safety and mutual benefit during long hunts. Although the redoubtable magnataur lead solitary lives, adventurers who cross paths with them quickly learn that it would have been wiser to stay at a safe distance.\r\n==Introduction==\r\n[[Azeroth]] has many hybrid races — creatures that resemble two different species put together — but the magnataur are unique among them for many reasons. First, they are by far the largest; a magnataur resembles a centaur, but on a colossal scale. A magnataur’s lower half is that of a wooly mammoth, and in total, they are about 20–30 feet tall and weigh 15–20 tons. Magnataur appear to be pure evil, brutal and uncaring even beyond the level associated with the centaur. It is unknown where magnataur came from. While they obviously resemble [[centaur]], [[dryad]]s and other hybrid races, they do not appear to be descendants of [[Cenarius]]. [[Brann Bronzebeard]] believes that they are in some way related to one of the [[Old Gods]], but there is little to confirm or dispute this idea. They do not worship the Old Gods, or any gods at all, and nobody has yet to find any writings that detail their creation, even through legends or hearsay. Magnataur never played a major role in the history of humanoid societies, but there is a potential for that to change in the coming years.\r\nThe overwhelming majority of magnataur are powerful melee fighters, charging into combat and using fear and massive clubs as their only weapons. Still, a few more specialized magnataur exist, including the shamans that often dominate small groups of their kind, and a few rare hunters, scouts and rogues. Regardless of their specialty, magnataur are among the deadliest creatures of Northrend, if not the world in general. They are a dying breed, but their recent desperation leads them to levels of cooperation never before seen, and this could prove disastrous for the other mortal races living on the glacial [[continent]].\r\n==Description==\r\nGenerally speaking, magnataur are raiders, and they spend most of their lives pillaging caravans, small towns, and even full-sized cities on the rare occasions that they work together as a group. Magnataur are one of few races that rarely even get along with other members of their own species, and these disagreements usually lead to bloodshed. For this reason, there are few magnataur left in the world. Due to their large size, magnataur are constantly hungry, and they eat almost anything. When raiding a caravan, they eat the humans, pack animals, and whatever else they can find that won’t break their teeth.\r\nMagnataur are intelligent enough to know that humanoid creatures can provide food for them, and a few historical mentions have even been found of magnataur setting up kingdoms and making humans into slave labor to provide them with nourishment. Such kingdoms don’t last long, however, as magnataur are universally too impatient to deal with such situations for long. Those magnataur who tire of a lifestyle of raiding often take up fishing or whaling. Whales are considered a delicacy among magnataur, and those who are able to catch them frequently are highly respected.\r\nThe only places where large numbers of magnataur dwell are the [[Dragonblight]] and the [[Storm Peaks]] on [[Northrend]]. In the past, they inhabited a larger portion of Northrend, but they have suffered as many losses to the Scourge as any other race.\r\n===History===\r\nThe history of the magnataur race is largely shrouded in mystery, but it is known that at one point in time, they were a dominant race. The shattered remnants of a few magnataur kingdoms have been found, but they were all extremely crude and underdeveloped by modern standards, having never progressed beyond the point of making simple tools and structures. A few early writings exist from cultures of [[human]]s who were kept as slaves by magnataur, but not many.\r\n==Appearance==\r\nThis creature has the upper torso, head, and arms of a giant with massive tusks and the body of a great woolly [[mammoth]], similar to a [[Centaur]] that is half [[Horse]]. They wear little clothing, although the shamans often adorn themselves with stolen jewelry. It is fearsome to behold as it strides forward, its mighty hooves making the ground quake with each step. They weigh 15-20 tons and stand 20-30 feet tall. The origins of magnataur are a mystery, though speculation abounds. What is clear is that their numbers are few. This fact is somewhat of a blessing, given the pleasure these creatures take in destruction and torment. Survivors of caravans speak of wagons and horses smashed into the snow. Some paused in their flight long enough to see a massive figure carefully placing screaming people into a huge sack, destined certainly to unknown horrors. Such a creature requires a great deal of food to feed, so magnataur eat people and animals once they have their fun. In several places, they have set up crude kingdoms, sparing people from terror so long as food is provided. Eventually, either the populace fails to provide or the magnataur gets bored and another rampage begins. Others have some skill at fishing for [[whale]]s and many take to the water. Magnataur do not trust or like one another any more than they like other creatures. Magnataur will occasionally fight one another, but typically avoid these situations.\r\nMagnataurs come in an assortment of colors from lighter brown (warriors), dark brown (reavers) to blue/white (destroyers). Magnataurs in Wrath range in brown to blueish-white in color.\r\n==Culture==\r\nMost magnataur never learn to read or write, including many of the shamans, and thus there is little written culture left behind from the rare instances where they have set up small civilizations. Their buildings are simple wooden structures at best, and while a few cave paintings have been found, they create little art. Generally, abandoned weapons, dishes for eating, and simple beds are the most intricate works left behind in their settlements. Perhaps the most unique creations of magnataur are their sacrificial chambers, where a number of crude wooden or metal cages hold prisoners as they are burned alive in a central ring of fire. The easiest way to distinguish a magnataur ruin from any other is the sheer number of objects that have been crushed by massive force; when magnataur leave a city, they intentionally destroy anything they consider valuable that they cannot take with them, and they can be amazingly thorough. It is suspected that this is because they use the destruction of their own cities as a way of alleviating the frustration of having to move to another home.\r\nTypically, the size of a magnataur is directly related to its place in society; the largest and strongest are almost always dominant, and this is true even of spellcasters. Magnataur appear to continue growing throughout their lives, and thus the oldest are also the largest, strongest and most powerful.\r\nStrength means everything to magnataur, and they listen only to those who they feel are strong enough to threaten them or can somehow feed their gluttonous appetites. A given magnataur largely considers other creatures, including other magnataur, inferior. For the most part, a magnataur lacks long-term goals, save to grow more powerful and find ideal supplies of food. Outsiders are viewed as food, threats, or providers of food. There are few exceptions: Magnataur are wise enough to give dragons a wide berth and know that invading the territory of a dragon can be deadly. Likewise, they avoid the Scourge, knowing that the undead are dangerous and taste unpleasant. Magnataur attack adventurers on sight, holding back only if they feel the adventurers would potentially have something to offer them — which is a rarity.\r\n===Society===\r\nMost magnataur live much of their lives alone, and as such, no formal society exists among the majority of them. A small number of tribal groups exist, and in these cases, they are held together by their mutual fear of their shaman leader. In most cases, these small tribal groups end with the assassination of their leader, but a few shamans have been strong enough to hold a tribe together for a number of years. The only system of rank that magnataur understand is dictated by power, and thus, a larger or more combat-worthy magnataur is always considered superior. The race as a whole is not formal enough to have an elite group of warriors, though small groups of powerful shamans do exist; these shamans are considered the leaders of the magnataur as a whole, although they lack any formal institution of this leadership.\r\nMale and female magnataur differ only in that females have a slightly greater obligation to care for their children for a few years after childbirth. There is no mating season for magnataur; they simply mate when they feel like it. They breed when food is plentiful and chance brings a potential mate into close proximity. Once the act is complete, the pair separates, often never to see each other again. Mothers teach basic hunting, weapon making, basic language skills, and how to craft needed tools. Humans and other animals are brought back to the lair for the child to play with. When young are old enough, they accompany the mother on raids. Once reaching adolescence, children are abandoned and fend for themselves, and to hunt on their own. Magnataur will occasionally fight one another, but typically avoid these situations. Mating, however can pit males against each other. These fights are usually all display. The two shout and smash the ground until one looses his nerve and flees.\r\nExperienced magnataur tend to advance as [[warrior]]s or [[scout]]s. A few rare and powerful magnataur also learn the path of [[shamanism]], or advance far enough as warriors to become [[gladiator]]s. There have been a few [[arcanist]]s, [[runemaster]]s and [[inscriber]]s in the history of magnataur, but they are rare. [[Hunter]]s are not unheard of among their number, but they are looked down upon for favoring ranged weapons over melee. Due to their size, it is difficult for magnataur to become [[rogue]]s, but a rare few exist; they are incapable of the kind of stealth most rogues enjoy, but specialize instead in setting traps and ambushes. [[Paladin]]s, [[priest]]s, [[witch doctor]]s and [[druid]]s do not exist among the magnataur.\r\n===Faith===\r\nMost magnataur have no specific religious beliefs, although many have superstitions that are passed on within a specific family. There are a few [[shaman]]s among the magnataur race, but their perverted concept of shamanism is most comparable to that of the forest trolls. For example, magnataur shamans often sacrifice large numbers of humanoids in their barbaric rituals — of course, they still eat the remains afterward. Overall, most magnataur distrust [[magic]], although they fear only the most powerful spellcasters, such as dragons.\r\n===Combat===\r\nMagnataur employ two basic strategies. The first is simply to charge a victim or settlement and start laying waste with his club. Fleeing victims are trampled. The other approach is to lie in wait or behind cover for passing caravans. Magnataur sometimes follow caravans, looking for an opportunity to surprise them. This desire for surprise is not out of caution or fear, but rather to limit the chance that any victims escape the encounter. Given the lack of any appropriate weapons for their size, magnataur have some skill at shaping trees into serviceable clubs. These huge clubs weigh between 200 and 600 pounds and can be wielded one-handed by a magnataur. Gargantuan magnataur have even larger clubs.\r\n===Language===\r\nMagnataur speak Low Common. They do not interact with any other cultures enough to learn other languages.\r\n===Relations===\r\nSince there is no formal magnataur society, they never go to war as a whole, and thus they largely try to avoid the threat of the [[Scourge]], [[dragon]]s and anything else they cannot handle individually. Magnataur routinely attack [[ice troll]]s and [[tuskarr]], pillaging their villages for food and supplies. Generally, tuskarr defend themselves well against such attacks, and the [[Drakkari]] simply take their losses. Occasionally, a troll leader grows infuriated at the magnataur raids and sends out a massive group to hunt the creatures, but such an expedition usually ends up with so many troll casualties that future generations remember that retaliation is not worth the cost. \r\n[[Murloc]]s often try to serve magnataur in an effort to save their own lives, and it occasionally works for a while. Most of the time, though, magnataur can’t resist the taste of murloc and end up eating their slaves. [[Furbolg]]s know to hide from magnataur attacks, and magnataur find them irritating to hunt, and thus only the most desperate or skilled of magnataur try to hunt a furbolg. Magnataur have few allies, even with other Magnataur, but they seem to tolerate the Arctic [[Kobolds]].\r\nMagnataur adventurers are rare, but a few have given up their life of raiding or whaling for a more fulfilling existence. With the growing threat of the Scourge, many magnataur are forced into a new way of thinking, and the wisest among their number realize that they may not be able to stand against the undead alone. It is also possible for a magnataur to be taught the value of more peaceful forms of shamanism or other faiths, much like Thrall taught the Darkspear trolls to curb their cannibalistic practices. Magnataur have a difficult time getting along with other races, but given time and effort, they could learn to adapt and teach others that they are different from the other creatures of their race. A magnataur adventurer is an exceptional individual, but adventurers are exceptions by default.\r\n==Noteable Magnataur==\r\n* [[Grom'thar the Thunderbringer]]\r\n* [[Dammia Frostcut]]\r\n* [[Gigantaur]]\r\n==Annihilan speculation==\r\nThey resemble the demonic [[Annihilan]] both physically and culturally far more than any Azerothian hybrid race, though this is probably just a coincidence and product of presumably similarly harsh natural habitats.\r\nPerhaps it is just model reuse.",},
			["Magni"] = { content = "#REDIRECT [[Magni Bronzebeard]]", redirect = "Magni Bronzebeard",},
			["Magni Bronzebeard"] = { content = "'''King Magni Bronzebeard''' is the current ruler of the [[dwarven]] kingdom of [[Khaz Modan]] and head of the [[Bronzebeard Clan]].\r\n==History==\r\nThe eldest of the three Bronzebeard brothers, Magni was destined to be the king under the mountain. Strong of arm and keen of mind, Magni loved his two brothers above all else in the world.\r\nHe was one of the heroes during the [[second war]], often directly leading his people into battle. Upon the liberation of [[Ironforge]] by the forces of the [[Alliance|Alliance of Lordaeron]] he pledged his kingdom's support, his two brothers accompanying the Alliance host.\r\nDuring the recent fall of [[Lordaeron|Kingdom of Lordaeron]], his middle brother, [[Muradin Bronzebeard|Muradin]], was reportedly slain by the [[death knight]] Prince [[Arthas]] in [[Northrend]]. Magni was overcome with grief at the news of Muradin's demise, but he and the youngest brother, [[Brann Bronzebeard|Brann]], remained steadfast in their desire to continue serving the dwarven people. \r\nBrann, an explorer of some renown, went missing only months ago, and King Magni had lost hope that he still lived. Though he remains a wise and strong leader, his pain and sorrow weigh heavily upon him. Many dwarves wonder whether the kingdom will ever see another Bronzebeard sitting on the throne of Ironforge. Recently, the intrepid Brann popped up once more, seeming to have survived his [[Silithus]] venture and somehow getting the base of [[Atiesh]] into [[C'thun]]'s otherworldly carapace. Much to Magni's dismay and a series of agonized groans from the [[Explorer's League]], Brann has again managed to misplace himself within [[Outland]] and recently again in [[Northrend]].\r\nKing Magni's only child, [[Moira Bronzebeard]], was recently captured by Emperor [[Dagran Thaurissan]], and is now under a magical charm spell, serving the evil emperor without question. Thaurissan made her fall in love with him, and together, they have conceived a child. Much to the kingdom's despair, Magni's grand heir will apparently be a dwarf who is both the heir of the King of Ironforge and the Emperor of Blackrock.\r\nIn recent times Magni has diplomatically approached Stormwind for assistance against the ever increasing Dark Iron threat, citing their destruction and control of the [[Thandol Span]]. Much to his frustration, his pleas have fallen on deaf ears. While [[Bolvar Fordragon|Bolvar]] concurs with the dwarven king, [[Lady Katrana Prestor]], advisor to the recently returned King Varian, accuses Magni of trying to involve [[Stormwind]] in the dwarves' personal war, and refuses to send reinforcements. Luckily, Jaina already informed Magni of the appearance of Lo'gosh.\r\n==Involvement with the creation of the [[Ashbringer]]==\r\nIn the first issue of the '''Ashbringer''' comics, it was revealed that Magni is the forger of the legendary blade, brought to him in its raw form by [[High Inquisitor Fairbanks]] and [[Alexandros Mograine]].\r\n==World of Warcraft==\r\n'''King Magni Bronzebeard''' is a Level ?? (Boss) quest giver located in [[The High Seat]] in [[The Great Forge]], in the [[Dwarf]] city of [[Ironforge]].\r\nHe starts the following quests:\r\n* A King's Tribute\r\n* Kharan Mighthammer (Dungeon)\r\n* The Fate of the Kingdom (Dungeon)\r\nHe ends the quest The Feast of Winter Veil ([[Feast of Winter Veil]]).\r\nSee [[List of Ironforge NPCs]].\r\n==Tactics==\r\nKing Magni has several nasty abilities at his disposal including a powerful Thunderclap, Charge, and a massive knock back. In addition he can launch players into the air, transform into Avatar which increases his damage and armor, as well as summon guards to aid him. When his health drops low he heals himself by using an ability similar to Lay on Hands.\r\n===Abilities===\r\n*Avatar: Increases the Physical damage dealt by the caster by 50% and enhances its armor by 50% for 15 sec. \r\n*Thunderclap\r\n*Charge\r\n*Knockback\r\n*Summon Guards\r\n*Self Heal\r\n==Quotes==\r\n'''Aggro''' ''For Khaz'Modan!''\r\n'''Aggro''' ''Feel the fury of the mountain!''\r\n'''Greeting''' ''Strength, honor. I see them in you. Why have you come?''\r\n'''Greeting''' ''What brings you to Ironforge?''\r\n'''Greeting''' ''How can the dwarves help you?''\r\n'''Greeting''' ''What do you seek within the mountain?''\r\n===Response to [[Princess Moira Bronzebeard|Princess Moira Bronzebeard's]] revelation===\r\n''<King Magni Bronzebeard is visibly upset.>''\r\n''It seems that even in death, Thaurissan has won.''\r\n''You are dismissed, <name>. Before you leave, you may choose your reward from the royal vault.''\r\n''<King Bronzebeard slumps into his throne to mull over this bizarre change of events.>''",},
			["Magnus Frostwake"] = { content = "'''Magnus Frostwake''' is a level 50 [[blacksmithing]] and [[alchemy]] [[recipe]] [[vendor]] located in [[Caer Darrow]] in the [[contested]] territory of [[Western Plaguelands]]. He is normally invisible, and can only be seen once the player has equipped the Spectral Essence item from the quest Kirtonos the Herald.\r\nHe sells the following items:\r\n* Plans: Ebon Shiv\r\n* Plans: Huge Thorium Battleaxe\r\n* Plans: Ornate Thorium Handaxe\r\n* Plans: Storm Gauntlets\r\n* Recipe: Major Mana Potion\r\n* Recipe: Transmute Water to Air\r\nSee [[List of Western Plaguelands NPCs]].",},
			["Magocracy"] = { content = "'''Magocracy''' is the term used to describe the government of the [[Humans of the Eastern Kingdoms|human nation]] of [[Dalaran]], which is ruled by a group of [[mage (lore)|archmagi]] called the [[Kirin Tor]].\r\nMagocracy literally means 'Rule of the Magi'. 'Mago-' is derived from the old Persian word, 'magus' meaning 'priest' or 'mage', while the suffix '-cracy' comes from the Greek 'kratein', 'to rule'. The word is therefore a blend of Greek and Persian, as is the word '[[archmage]]'.\r\nSince a magocracy only means that the government is made up of magic-users, it can incorporate elements from other political styles. Dalaran's magocracy is a political oligarchy with democratic elements, in much the same way most city-states in ancient Greece were run. Though the foremost leaders of the Kirin Tor's archmagi councils tend to be the nation's most skilled mages, they are elected democratically from all eligible.",},
			["Magocrat"] = { content = "#REDIRECT [[Magocracy]]", redirect = "Magocracy",},
			["Magocrats"] = { content = "The '''Magocrats''' (also referred as '''Magocrat lords''' and '''Magocrat Lords of Arathor''') were the ruling [[archmage|archmagi]] of the city-state of [[Dalaran]].\r\n==History==\r\nAfter the foundation of [[Dalaran]], the Magocrats eagerly devoted themselves to the arcane. They housed their growing libraries and research laboratories in the [[Violet Citadel]], a towering spire raised by magic in the heart of the city.\r\nHowever, the constant and ungoverned use of magic began to tear the fabric of reality around the city and demons started to slip back into [[Azeroth]], bringing with them conflict and misery and sowing considerable confusion and chaos within the streets of Dalaran. Most of these demonic encounters were isolated events, and the ruling Magocrats did what they could to keep such events hidden from the public.\r\nFearing that the peasants would revolt and that Strom would take action against them, the Magocrats turned to the only group they felt would understand their particular problem: the [[Quel'dorei|elves]].\r\nUpon hearing the ruling [[human]] archmagi news of demonic activity in the [[Dalaran|thriving magocracy]], the [[Quel'dorei|elves]] quickly dispatched their mightiest wizards to the lands of [[Arathor]] in order to investigate and report. As a result, they informed the Magocrats that as long as they used magic, they would need to protect their people from the [[Burning Legion]]. Thus, the elves and the Magocrats formed a secret order known as the [[Council of Tirisfal]], charged to fight a never-ending secret war against the Legion.\r\nAs [[Dalaran]] became the chief center of learning for magicians throughout the land, the Magocrat lords founded the [[Kirin Tor]]: a specialized sect charged with cataloging and researching every spell, artifact, and magic item known to mankind at the time. The Kirin Tor eventually replaced the Magocrats at the head of Dalaran.",},
			["Magra"] = { content = "'''Magra''' <The Third Khan> is a level 43 [[elite]] [[undead]] [[centaur]] found in [[Maraudon]]. The [[Magram]] tribe may be named after him. He manifests when the [[Amulet of Spirits]] is used on the [[Spirit of Magra]].\r\nNote, [[Blizzard]] has made an in-game typo in the titles of the five [[khan]]s. ''<The Nth Kahn(sic)>''\r\n==Quests==\r\n*The Pariah's Instructions",},
			["Magram"] = { content = "#REDIRECT [[Magram clan]]", redirect = "Magram clan",},
			["Magrami Spectre"] = { content = "'''Magrami Spectre''' can be found in [[Desolace]] .\r\n==Drops == \r\n \r\n0.01% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Magram Bonepaw"] = { content = "A level 37-38 Hyena native to Desolace. Colored white. Is always in the company of its [[Magram]] centaur masters, but is not counted as a minion, and thus is tamable.",},
			["Magram clan"] = { content = "The '''Magram clan''' of [[centaur]] have made their home in the southeastern parts of [[Desolace]]. They are mortal enemies of the [[Gelkis clan]] of centaur, a brother tribe also located in southern Desolace. The founding leader, or [[Khan]], of the Magram was [[Magra]], third of the alleged offspring of [[Zaetar]] and [[Theradras]]. The Magram were once willing to befriend adventurers of the Horde and Alliance in exchange for doing evil acts towards the Gelkis clan, while under [[Khan Jehn]]'s leadership. [[Khan Kammah]] now leads the clan.\r\nThe Magram held no alliance with their brother tribes, until some time after having lost their lands to the demons.\r\n==History==\r\nOriginally led by the Third Khan Magra, the Magram situated themselves against the mountain ranges of Desolace when the centaur divided into five tribes and have remained there ever since. \r\nBefore the death of Magra, he installed the idea that strength was essential and the tribe’s survival depended on their fighting spirit. When their brother tribe of Gelkis centaur spoke out against this notion, arguing that Theradras always watches over the centaur and will keep the tribes safe and alive, an eternal feud between the two tribes was born.\r\nThe life-long pursuit of strength has carried on through the Khans of Magram to this day, turning them violent and determined. To solidify their title as the strongest the tribe still fights fiercely to weaken or destroy their brother clans, viewing the Kolkar as weak, the Gelkis as nothing more than a nuisance, and the [[Maraudine]] as a formidable enemy.\r\nIt can be assumed that the Magram’s culture has developed into revolving around strength worship above all else. When compared to the Gelkis, the Magram hold very primitive forms of speech and social structure. For example, their grasp of common is limited and the position of Khan would likely be sought through a death match of sorts.\r\n[[Horde]] forces sent by [[Thrall]] quickly discovered that the centaur were slaughtering their other tribes just as much as they were attacking outsiders. When they investigated further they met [[Warug]], who told them of the origins of the centaur and Theradras's recent actions, how she had empowered the centaur because she feared the Horde would drive them to extinction. The Horde allied with Warug and the Magram, who held no loyalty to Theradras unlike the other clans, to suppress the other tribes. They then entered Maraudon and slew Theradras. Their victory halted the spreading corruption in Desolace and stopped the violent bloodlust in the centaur. With the Horde's blessing, the Magram became the leaders of the united centaur and led them to an age of tranquility. Yet none knew how long they would stay on the path of peace.\r\n===Desolace===\r\nSince its founding, the Magram tribe has not ventured past the borders of their native homeland. Situated in the southeast, within range of the [[Valley of Bones]], lies the [[Magram Village]]. Patrols of [[warrior]]s and [[Caster|spell casters]] line the borders of their settlement, the many tents within housing their beast of a Khan, Jehn. Like the Kolkar, the Magram have domesticated [[hyena]]s and utilize them for scouting purposes around the village.\r\n====Valley of Bones====\r\nSouthwest of the Magram Village is a great valley infested with undead known as the Valley of Bones. The ghosts of Magram ancestors roam here undisturbed among the two giant serpent skeletons that line the valley. It is believed that Magram and their necromancers may be creating a \"new\" scourge, and this makes them a potential danger to everyone.\r\n===Named===\r\n* [[Khan Kammah]]\r\n* [[Khan Jehn]]\r\n* [[Magra]]\r\n*[[Warug]]\r\n===Unnamed===\r\n*[[Magram Bonepaw]]\r\n*[[Magram Defender]]\r\n*[[Magram Marauder]]\r\n*[[Magram Mauler]]\r\n*[[Magram Outrunner]]\r\n*[[Magram Pack Runner]]\r\n*[[Magram Scout]]\r\n*[[Magram Stormer]]\r\n*[[Magram Warden]]\r\n*[[Magram Windchaser]]\r\n*[[Magram Wrangler]]\r\n*[[Magrami Spectre]]\r\n*[[Warug's Bodyguard]]\r\n===Faction description===\r\n''These centaur have made their home in the eastern region of Desolace. Mortal enemies of the Gelkis Centaur.''\r\n===Gaining reputation===\r\nReputation with the Magram Clan Centaur is gained by killing hostile mobs at [[Shok'Thokar]] and by completing the quest [[Death to Agogridon]], with the latter granting enough reputation to reach ranking with the faction.\r\nShould the player have already finished the quest before [[Patch 8.0.1]], they can speak to [[Karnum Marshweaver]] at [[Karnum's Glade]] to receive the reputation reward.\r\n===Magram vs. Gelkis===\r\nThe clashing cultural values of the Magram and Gelkis are the founding reason for their animosity towards one another, and it has only spiraled downwards since their initial disagreement. While the Magram only respect strength, the Gelkis respect nature and their birthmother Theradras, calling upon her protection and the power of earth to maintain their existence. The Magram view this as weak however, especially their trust in Theradras to protect the centaur tribes. \r\nThe Magram representative [[Warug]], stationed at the base of the mountains on the eastern borders of Magram territory, recruits foreign aid to strike against the Gelkis and organizes strategic missions to weaken them. In order to be deemed worthy of fighting with the Magram, adventurers must gain [[reputation]] with the tribe by slaying members of the Gelkis until they reach status with the Magram. Each kill gives 20 (22 with [[Diplomacy]]) reputation to the [[Magram]] faction and lowers the reputation of the [[Gelkis]] by 100. Reputation with the Magram from kills caps at , or one point below . Reputation can be gained past this point by completing Magram quests.\r\nWarug also sends foreign assistance to combat the [[Kolkar]] and [[Maraudine]] clans.\r\nIn earlier builds, a player could become friendly or higher with both Centaur clans at the same time, by having someone else in a party kill a member of the Gelkis or Magram, which would cause the player to gain reputation with one Centaur clan, while not losing reputation with the other. As of [[patch 2.2]] the player will gain and lose reputation regardless of who in the party actually does the killing.\r\n==Notes==\r\n*They are named after their first khan, [[Magra]].\r\n*Majority of the Magram centaur fashion light green-colored armor. They also tend to be yellow-skinned.\r\n*Unlike the Gelkis clan who end up becoming by the time you unite the three clans, the Magram stay .",},
			["Magram Clan Centaur"] = { content = "#REDIRECT [[Magram clan]]", redirect = "Magram clan",},
			["Magram Village"] = { content = "'''Magram Village''' is a [[centaur]] village, home to the [[Magram]] tribe. It is located in southeast [[Desolace]] on the shores and islands of a series of polluted yellow pools. Crude bridges connect the islands to each other and the shore. Adventurers can choose to ally with the Magram tribe in their ongoing war against the [[Gelkis]] tribe.",},
			["Magroth the Defender"] = { content = "'''Magroth the Defender''' was a paladin who joined [[Malfurion Stormrage]] and [[Maiev Shadowsong]] to destroy the [[Eye of Sargeras]] thus bringing [[Illidan]]'s destruction of [[Icecrown]] to a halt.\r\nHe later joined [[Dagren the Orcslayer]] and [[Halahk the Lifebringer]] as part of the resistance against [[Arthas]] near the ruined [[Lordaeron palace gardens]] for which he fell in battle against the [[death knight]] and his forces.\r\n==Quotes==\r\n*''\"Our righteous might will always overcome the forces of darkness! We shall aid you against these unholy beasts\"'' - To his [[night elven]] rescuers\r\n*''We will never abandon Lordaeron, Arthas! We will never give up!''",},
			["Magtheridon's Lair"] = { content = "'''Magtheridon's Lair''' is the raid wing of the [[Hellfire Citadel]] dungeon in [[Outland]] where you fight the brutish [[pit lord]] [[Magtheridon]] himself. You can find the entrance to Magtheridon's Lair on the very bottom of the western side of the Citadel (opposite side from the other 3 entrances). It is a quick raid encounter (like [[Onyxia's Lair]], which contains four \"guard mobs\" before the boss encounter, [[Onyxia]]).\r\nPlayers can get a preview of Magtheridon by doing the [[Blood Furnace]] instance. He is being held captive underneath the room where you fight [[Keli'dan the Breaker]].\r\n==Attunement==\r\nYou do not need a key to enter Magtheridon's Lair. It is possible to zone in provided you are level 65 and are in a raid group.\r\n==Trash mobs==\r\n'''Hellfire Warders''' - Come in groups of 3. One group patrols. 4 groups total. They are immune to Silence effects and all forms of CC, including stuns. They have several spell damage abilities:\r\n Basic Melee : These melee for around 7.1k on cloth, 2-3k on plate.\r\n Shadow Bolt Volley : Hits everyone in range for ~2k shadow damage. Must be interrupted by mages/shamans, rogues will get feared too much to be reliable here. \r\n Shadow Word: Pain : Ticks for 500 per 3 sec and lasts 18 seconds.\r\n Unstable Affliction : Ticks for ~500 and deals 3000 damage if dispelled and will silence the dispeller.\r\n Rain of Fire : Ticks for 1900 every 2 seconds. This is the most dangerous spell and is instant cast and cannot be interrupted, so raid members must run around it.\r\n Death Coil : Seems to target the 2nd closest person in threat to the warder, but will often be cast on the tank. Deals 2k and lasts 3 seconds.\r\n Fear : Lasts 8 seconds, cannot be dispelled. Tremor totem will NOT work. \r\n Shadow Burst : Deals 2k damage to the main aggro target, knocks them back and reduces their threat.\r\nYou must clear each pack of Warders, or they will run at the raid when you engage the boss. They can be affected by Curse of Tongues and Mind Numbing Poison.\r\nThe respawn timer on Hellfire Warder Packs is 2 hours.\r\n==Loot==\r\nSee [[Magtheridon's Lair loot]]",},
			["Magtheridon"] = { content = "''This article is about the character Magtheridon. For the realms please visit the [[Server:Magtheridon US|US realm]] or the [[Server:Magtheridon Europe|EU realm]]. For information on how to slay Magtheridon, please see [[Magtheridon (tactics)]].''\r\n'''Magtheridon''', the former Lord of [[Outland]], is a [[pit lord]] who conquered the ruins of the orcish homeworld following its destruction. His reign was ended by the arrival of [[Illidan Stormrage]], who [[Lord of Outland|took]] Magtheridon's throne at the [[Black Citadel (TFT)|Black Temple]] for himself. Deciding that Magtheridon would have a further part to play, Illidan had Magtheridon's body dragged to the [[Hellfire Citadel]] where he imprisoned the pit lord, leaving him at the mercy of the fel orcs. His rumbling cries are heard throughout the Hellfire Citadel. It is interesting to note that his wardens are not fel orcs, but normal green-skinned orcs. It seems that Illidan is keeping Magtheridon alive for the sole reason of creating more fel orcs under his rule. Strangely, he was purple in WCIII but now in WoW he is green like most (if not all) pit lords.\r\n==Biography==\r\nA brutal [[pit lord]] and servant of [[Mannoroth]] the Destructor, Magtheridon found his way to [[Draenor]] after its cataclysm. With the clans in disarray, and most killed in the disaster, Magtheridon was quick to show his power, and rallied the surviving orcs under his pennant. The orcs were corrupted and became [[fel orc]]s. He declared himself the ruler of the ruined world [[Outland]]. Over the years, Magtheridon brought legions of demons to Outland through the four [[dimensional gateway]]s which [[Ner'zhul]] shattered the world with, and his forces became very expansive. These demons included [[nether dragon]]s, [[voidwalker]]s, [[Succubus|succubi]], [[felguard]]s, [[felbeast]]s, [[doomguard]]s, [[eredar]], and [[infernal]]s.\r\nIt was almost twenty years after the cataclysm that [[Illidan]] and his servants came to Outland, to escape [[Kil'jaeden]], Illidan's vengeful master, and his wrath. Magtheridon found himself under attack by Illidan, Kael'thas' legion of [[blood elves]], Lady Vashj's army of [[naga]], and even the elusive [[broken draenei]], led by the [[Draenei Elder Sage|elder sage]], [[Akama]]. The group managed to shut down the [[dimensional gateway]]s which supplied Magtheridon with reinforcements, and then laid siege to Magtheridon's [[Black Citadel (TFT)|Black Citadel]]. The Pit Lord rallied his forces to defend him, but the combined skills and armies of the heroes crushed his resistances. Eventually Illidan broke through and Magtheridon was defeated by the four generals. He asked if Illidan had been sent to test him. Illidan cackled in reply, saying that he had come to replace him.\r\nBefore [[World of Warcraft: The Burning Crusade]], it was commonly accepted that he had been killed by Illidan and his forces. However new information revealed the truth:\r\n''\"Though the pit lord was defeated, he apparently still serves some yet undiscovered purpose in the dark designs of the new lord of Outland...\"''\r\nRecently it was discovered that after his defeat, Magtheridon was dragged all the way to Hellfire Peninsula and is locked up in a lair created for him underneath Hellfire Citadel, his blood being used to create fel orcs for Illidan Stormrage. His wardens are mainly orcs. While he is not an ally of Illidan, he remains a powerful tool.",},
			["Magtheridon (tactics)"] = { content = "''This article is about the in-game raid boss. For character biography and Warcraft III appearances, see [[Magtheridon]].''\r\n'''Magtheridon''' is a quick raid encounter, similar to that of [[Onyxia's Lair]], it's the raid wing of the [[Hellfire Citadel]] dungeons. The first phase of the fight is a relatively simple [[gear check]]/[[DPS race]], the second phase an interesting [[battle for survival]].\r\n==Abilities==\r\n'''Hellfire Channelers:'''\r\n*Level: ??\r\n*Health: 240,000\r\n*Shadow Volley: 1-second interruptible cast, 30-yard AoE, up to 2k on cloth\r\n*Fear: Single target fear, 40-yard range\r\n*Dark Mending: 2-second interruptible cast, heals itself or another Hellfire Channeler within 60 yards for up to 32k.\r\n*Summon Abyssal: Summon Infernal (despawns after one minute)\r\n*Soul Transfer: When one Channeller dies, all surviving Channellers gain this stacking buff, increasing size by 20% and damage and casting speed by 30% (with four buffs, the last Channeler has 220% cast speed)\r\nNote that they are vulnerable to mind-numbing poison and Curse of Tongues\r\n'''Burning Abyssals: ''' \r\n*Deals 2625 to 3375 with a 10-yard range to the player on which it lands.\r\n*Casts Fire Blast, which does 3300 damage in a 20-yard range.\r\n*May be frost nova'd, banished, feared, stunned, or trapped.\r\n*At most 5 Abyssals can be up at the same time.\r\n'''Magtheridon:''' \r\n*Level: ?? ([[Boss]])\r\n*Health: 4,750,000 (Patch 2.0.12)\r\n*Hit: ~6k on plate\r\n*Cleave: ~8k on plate, frontal cone AoE\r\n*Conflagration: A small AoE spell cast on random floor patches that does 6000 fire damage over 8 seconds.\r\n*Quake: 50-second cooldown, first cast after 40 seconds. A knockback that hits every player every second for 7 seconds, interrupts spells\r\n*Blast Nova: 60-second cooldown, about 2,500 damage every 2 seconds for 10 seconds to every player in the lair.\r\n*Enrage: 22 minutes after the start of the fight, Magtheridon enrages and wipes the raid.\r\n'''Manticron Cubes:'''\r\n*When clicked by a player, a channeling effect starts. This deals 800 damage per tick (400 dps) to the player clicking it\r\n*If all 5 cubes are active at the same time, Magtheridons Blast Nova is interrupted, and while the five cubes all stay active, he takes 300% damage\r\n*When the channel breaks, the player receives the 30 sec Mind Exhaustion debuff\r\n===Composition and setup===\r\n*One Main Tank (Magtheridon)\r\n*2-4 Off-Tanks (Channelers)\r\n*6-7 Healers\r\nNo special buffs or gear are required, fire resistance in particular is *not* needed. Warlocks and hunters are handy for Infernal CC, but not needed.\r\nInitially, five Hellfire Channelers are distributed around the room, each next to a [[Manticron Cube]]. All mobs in the room have no aggro range, the fight is started by any harmful action.\r\nIt's best to have one tank and one healer assigned to each Channeler so that they can be tanked in their places and their shadow volleys do not overlap. If only four tanks are available, the first two Channelers can be tanked together. All other raid members start out at one Channeler, and then work their way (either clockwise or counter-clockwise) through the room.\r\n===Phase 1===\r\nAfter the first attack on a Channeler, the raid has 120 seconds before Magtheridon becomes active. During that time, as many Channelers as possible must be killed, three must be dead at least when the boss enters the fight.\r\nAll Channeler casting should be interrupted as much as possible, the most dangerous being Dark Mending. After the first adds are dead, free healers should concentrate on the later tanks because they take more damage.\r\nThe Infernals should be banished, [[kite]]d, or simply tanked. Warlocks and Hunters can do this job - early on they're free to DPS, but when Infernals start to appear they can concentrate on them. Tanks whose Channeler is dead or not being dpsed down can pick up roaming Infernals (although they should be careful not to drag Channelers close to the current dps target, or they risk a Dark Mending).\r\n===Phase 2===\r\nWhen Magtheridon breaks his banish, he starts to build threat only when he actually targets someone. Use aggro building moves or [[misdirection]], but not too early - let him target someone first. Besides killing any remaining Channeler(s) first and then nuking Magtheridon, the raid has to avoid Blast Nova by clicking on the cubes (see below). This is complicated by Quake, and in Phase 3 by Collapse.\r\n===Phase 3===\r\nAt 30% Magtheridon shatters the walls of his lair, causing the roof to crash down. This deals 5250-6750 physical damage plus a 2 sec stun to every raid member. It's very bad if the start of phase 3 coincides with a Blast Nova. Therefore, DPS should stop at about 35%, wait until a Blast Nova is over, and then quickly bring him below 30%. For the remainder of the fight, the ceiling randomly caves in on players ('Collapse''). Collapses kill everybody in an 8 yard radius of the spot of impact. There is a cave-in animation shortly preceding it so players are able to safely move out of the way.\r\nDamage from the initial shatter can be avoided by the usual means ([[Divine Shield]], [[Ice Block]] etc.), but be careful to time these abilities correctly. The animation starts about 15-20 seconds before the raid actually takes damage.\r\n===Manticron Cubes===\r\nEvery 60 seconds Magtheridon starts to cast Blast Nova. About all wipes at Magtheridon happen because of an uninterrupted Blast Nova. In order to stop it, all five Manticron cubes must simultaneously be clicked (channeled) by players. Each cube should have one primary clicker assigned, with one backup if the primary clicker is disabled.\r\nDuring both Phases 2 and 3, Quake makes clicking the cubes more difficult. Since the cooldowns of Quake and Blast Nova are slightly different (50 and 60 sec), after three or four cycles, they happen at nearly the same time (fortunately Blast Wave cancels any active Quake), and then move out of sync again. It is important to know that each cube has a \"safe spot\". Standing up against the wall, directly behind the cube when facing into the middle of the room grants immunity to the knock-back from Earthquake. People standing there simply bounce in place.\r\nCube clicking should be done by the most reliable raid members, it's the single most important element of the fight. All other things being equal, it's possible to have the off-tanks from phase 1 do the clicking, because their DPS usually are the lowest, and they have higher HP and thus can keep the channel up for longer. It's desirable to keep channeling the cubes as long as possible, but staying alive is actually more important. Clickers should synchronize the release so that nobody takes unnecessary damage.\r\n===Notes===\r\n*The cubes can be clicked from any direction, so aware players are able to channel from a safe location.\r\n*Stand several yards from the cube while waiting for the next Blast Nova.\r\n*A player under the effect of a Paladin's Divine Protection cannot click Manticron cubes.\r\n*In particular, do not stand close to a cube in Phase 3. If Collapse targets a player close to the cube, this may make the cube inaccessible.\r\n*It is very important click all the Manticron cubes within the 2-second cast timer that happens some time after the raid warning \"Magtheridon Begins to Cast Blast Nova\" is shown. People must wait for the emote and not click too early.\r\n*Immediately before starting his cast, Magtheridon will detarget the tank. This is a good time for the callout, as it gives clickers an extra moment to react, and can prevent any damage from Blast Nova.\r\n==Quest information==\r\nKilling Magtheridon is required for Trial of the Naaru: Magtheridon, the last quest to obtain the [[Tempest Key]]. Even though the key isn't needed to get into [[Eye (Tempest Keep)|The Eye]] anymore, the quest is still there, and the regular rewards are still available. The title [[Champion of the Naaru]] was given to players who completed the quest, up until the release of patch 3.0.\r\n==Quotes==\r\nMagtheridon randomly utters these quotes as players progress through [[The Blood Furnace]] instance, as well as his lair:\r\n*\"How long do you believe your pathetic sorcery can hold me?\"\r\n*\"Illidan is an arrogant fool! I will crush him and reclaim Outland as my own!\"\r\n*\"Wretched, meddling insects! Release me, and perhaps I will grant you a merciful death!\"\r\n*\"Away, you mindless parasites! My blood is my own!\"\r\n*\"Vermin! Leeches! Take my blood and choke on it!\"\r\n*\"My blood will be the end of you!\"\r\nIn addition during the fight:\r\n*Aggro: \"Thank you for releasing me. Now... die!\"\r\n*Draining: \"Not again... NOT AGAIN!\"\r\n*Freed from the draining: (laughs evilly) \"I... am... UNLEASHED!!!\"\r\n*Phase 3: \"I will not be taken so easily. Let the walls of this prison tremble... and FALL!!!\"\r\n*Kills a player: \"Did you think me weak? Soft? Who is the weak one now?!\"\r\n*Death: \"The Legion... will consume you... all....\" (gurgles, dies)\r\n==First Kills==\r\nSee [[The Burning Crusade: Guild Progression]] for the first kills\r\n===Databases===",},
			["Magtoor"] = { content = "'''Magtoor''' is a level 42 [[quest giver]] located at [[the Harborage]] in the [[contested]] territory of [[Swamp of Sorrows]]. He was one of a few [[draenei]] who went through the [[Dark Portal]] with the hopes of finding a new life, and settled in the [[Swamp of Sorrows]]. Unfortunately, most of them were driven mad due to homesickness, and attack all on sight. There are a few, led by Magtoor, that remember their noble roots and survive on in the swamp separate of their mad brothers. Magtoor has now the painful task to kill those who were once his brethren.\r\nHe used to be a lost one but he was retconned into a broken. He still says the lost ones look like them even though they no longer look remotely similar.\r\nHe starts the quest \r\n*Draenethyst Crystals.\r\n===Quotes===\r\n*\"Be careful [[Anchorite Avuun|Avuun]]. One of the merchants that I trade with in [[Stonard]] has heard of a raving about some horrible disease [[Cersei Dusksinger|she]]'s trying to perfect. They say it's for use against the Draenei!\"\r\n*\"[[Anchorite Avuun|Anchorite]], we are honoured that you are here, but I am curious as to what you truly believe you can accomplish.\"\r\n==See also==\r\n*[[Swamp of Sorrows NPCs]]\r\n*[[List of draenei in Azeroth]]",},
			["Magus Commerce Exchange"] = { content = "The '''Magus Commerce Exchange''' is the main trade district of [[Dalaran]].\r\n<!--",},
			["Magus Rimtori"] = { content = "'''Magus Rimtori''' is a level 55 female [[blood elf]] [[mage]] found in [[Azshara]].\r\n==Background==\r\nRimtori seduced [[Belgrom]], and manipulated him into escorting her party. Once the [[orcs]] had served her purpose, she betrayed the [[Horde]] and slaughtered the entire orcish guard. Positioning her entire escort at the [[Thalassian Base Camp]] under [[Magister Hawkhelm]]'s supervision, Rimtori set off to explore Azshara with her bodyguards.\r\nAngered, Belgrom sent agents after Rimtori.\r\nIt is not known precisely when or why the Thalassian expedition came to Azshara. Rimtori's most prized possession is the [[Kaldorei Tome of Summoning]] in the base camp, with which demons can be summoned. Her link to demons and the ancient nature of Azshara can lead one to assume she is on a personal crusade for power, digging up old relics as she explores the region. It is also possible that she serves [[Kael'thas]], and like [[Kariel Winthalus]], travelled to [[Kalimdor]].\r\n[[Kim'jael]], a [[goblin]] she employed before betraying him, claims that Rimtori is searching for \"[[Some Rune]]\". It is not known why Rimtori and her expedition seek this rune, nor what purpose it may serve.\r\n==Abilities==\r\n* '''[[Fireball]]'''\r\n* '''[[Frost Nova]]'''‎\r\n==Quests==\r\n*Betrayed (3)\r\n==Lore==\r\n*Head of Magus Rimtori ''(Quest Item)''\r\nSee [[List of blood elves in Azeroth]].",},
			["Magus Wordeen Voidglare"] = { content = "'''Magus Wordeen Voidglare''' is a level 42 [[quest giver]] located in [[Tarren Mill]] in the [[contested]] territory of [[Hillsbrad Foothills]]. He spends some of his time studying the artifacts used by [[Dalaran]] wizards to control their elementals. He is assisted by [[Keeper Bel'varil]].\r\nHe starts the following quests:\r\n* Prison Break In\r\n* Dalaran Patrols\r\nSee [[List of Hillsbrad Foothills NPCs]].",},
			["Magus Zabraxis"] = { content = "'''Magus Zabraxis''' is a level 60 [[reagent]] & [[poison vendor]] located at [[Honor Hold]] in the [[contested]] territory of [[Hellfire Peninsula]].\r\nSee [[List of Hellfire Peninsula NPCs]].",},
			["Mahren Skyseer"] = { content = "'''Mahren Skyseer''' is a level 32 [[quest giver]] located in a small camp on [[the Tidus Stair]], in the [[Horde]]-aligned territory of [[the Barrens]]. She is friendly to both [[Horde]] and [[Alliance]].\r\nShe starts the quest Isha Awak.\r\nSee [[List of the Barrens NPCs]].",},
			["Mai'ah"] = { content = "'''Mai'ah''' is a level 10 [[mage trainer]] located in the [[Valley of Trials]] in the [[orc]] and [[troll]] starting zone of [[Durotar]].\r\nSee [[List of Durotar NPCs]].\r\n==Quests==\r\nShe ends the quest Glyphic Tablet.\r\n==Quotes==\r\nGreetings, mage. Are you here to learn of the hidden arts?",},
			["Mai'Lahii"] = { content = "'''Mai'Lahii''' is a level 30 [[fishing]] [[vendor]] located in [[Shadowprey Village]] in the [[contested]] territory of [[Desolace]].\r\nShe starts the quest Clam Bait.\r\nSee [[List of Desolace NPCs]].",},
			["Mai'Zoth"] = { content = "'''Mai'Zoth''' is a level 45 [[Ogre Mage]] found in the [[Mosh'Ogg Ogre Mound]] in [[Stranglethorn Vale]]. \r\nMai'Zoth used an artifact called the Mind's Eye to corrupt [[Colonel Kurzen]]. Both [[Brother Nimetz]] and [[Kin'weelay]] want the Mind's Eye.\r\n==Quests==\r\n*Mai'Zoth\r\n*The Mind's Eye\r\n==Loot==\r\n*Mind's Eye ''(Quest Item)''",},
			["Maiden's Anguish"] = { content = "==Maiden's Anguish as an ingredient==\r\nThis item was used to make: \r\n* Deadly Poison VI\r\n* Anesthetic Poison\r\n* Instant Poison VII\r\n* Deadly Poison VII",},
			["Maiden's Folly"] = { content = "The '''''Maiden's Folly''''' is one of the two sunken [[Blackwater Raiders]] [[boat|ships]] located in [[the Drowned Reef]] in southern [[Arathi Highlands]]. The other ship is named the ''[[Spirit of Silverpine]]'', and lies to the west of the ''Maiden's Folly''. Both ships were part of an expedition, along with a third ship, the ''[[Harbinger]]'', in search of a lost elven treasure. When the ships were signaled by [[Shakes O'Breen]] to come dock at their location, the sea rumbled, the tides lowered, and the two ships crashed into the reef. \r\n[[Captain Steelgut]] was the captain of the ''Maiden's Folly''. He watched all the survivors being killed by terrible beasts, and not sure how he ended up on shore. Sadly, he was the only one to survive.",},
			["Maiden's Virtue"] = { content = "The '''''Maiden's Virtue''''' is a [[boat|ship]] docked in [[Menethil Harbor]] in the [[Wetlands]]. Her human crew stand around the dock waiting for supplies to be loaded so they can sail off. \r\n==Crew==\r\n* [[Bart Tidewater]] (Captain)\r\n* [[Maiden's Virtue Crewman| Crewman]]",},
			["Maiden of Grief"] = { content = "The '''Maiden of Grief''' is a female titan statue boss, much like the [[Maiden of Virtue]] in [[Karazhan]]. She is a boss of the non-linear instance [[Halls of Stone]].\r\n==Tactics==\r\nThis fight works similar to [[Maiden of Virtue]] in Karazhan.\r\nShe occasionally drops a big void zone instead of consecration, and puts a magical debuff dealing shadow damage instead of holy firing.\r\nShe also casts [[Shock of Sorrow]], which deals 1750 to 2250 shadow damage and incapacitates all group members for 10 seconds. This ability has a 4 second cast time. If the healer is positioned near a void zone, the healer can jump into it to avoid being incapacitated for the full duration.\r\n==Quotes==\r\nAggro:\r\n*You shouldn't have come...now you will die!\r\nKill:\r\n*Why must it be this way?\r\n*You had it coming!\r\n*My burden grows heavier.\r\n*This is your own fault!\r\nStun:\r\n*So much lost time... that you'll never get back!\r\nDeath:\r\n*I hope you all rot! I never...wanted...this.",},
			["Maiden of Virtue"] = { content = "The '''Maiden of Virtue''' is a [[giant]] Boss in the '''Guest Chambers''' wing of [[Karazhan]]. She is behind the rooms full of ladies of the night because she was sent to clear up Karazhan but somehow fell under the evil influence within the tower. It is unclear how this happened or who sent her. The Maiden is optional; it is not necessary to kill her in order to reach other bosses.\r\n==Abilities==\r\n* '''Melee''': on 14k armor: normally 2500&ndash;3500 every 1.8 sec, 4000-4800 crushing\r\n* '''Immune to Taunt'''\r\n* '''Holy Ground''': permanent 240&ndash;360 holy damage every 3 sec [[AoE]] 12 yards around her. Also silences for 1 second.\r\n* '''Holy Fire''': 1 second cast, 3238&ndash;3762 fire damage up front and 1750 fire damage every 2 seconds for 12 seconds. The DoT is a Magic effect and can be dispelled.\r\n* '''Holy Wrath''': AoE chained holy damage, instant cast, 20 second cooldown. Cast on a random target. Does not target or chain onto /off of pets.\r\n* '''Repentance''': Deals 1750&ndash;2250 holy damage and incapacitates the whole raid for 12 seconds. Thirty second cooldown. Dispellable only by [[Divine Shield]] and [[Ice Block]], but broken by any damage taken. Does not hit the Maiden's target.\r\n* '''Berserk''': Berserks after exactly 10 minutes, increasing her damage by ~500%. This isn't a concern for normal raid groups as she usually goes down within 2 to 3 minutes.\r\n==Strategy==\r\nThe Maiden of Virtue does not have phases in her fight. She behaves the same from the start of the fight to the end. \r\nThe Maiden uses all her abilities at random, not on a strict timer. For example, when the Repentance cooldown is over, she does not always cast it immediately; it just means that it's ''possible'' for her to cast it. However, she does not cast Holy Fire while Repentance is active.\r\nWipes occur at this boss for mainly two reasons - either the tank dies while the healers are incapacitated from a Repentance, or too many raid members die from Holy Fire. A wipe is also possible due to poor positioning which leads to a chained Holy Wrath. Once these risks are managed correctly, this is a fairly easy fight.\r\n===Positioning===\r\nCorrect positioning of the raid is the key here, healer positioning in particular. Ranged and healers should be far enough away from the Maiden to be outside of the Holy Ground attack. At the same time, the whole raid needs to be in range and sight of a dispeller and be spread out far enough to avoid chaining Holy Wrath. These requirements are easily matched with the following setup:\r\nThere are eight pillars around the room. Put one non-melee raid member at the outside wall in each gap between two pillars. Place the healers opposite of each other. Melee and tank can start wherever they like.\r\nTank her in the center of the room, right where she stands. After the pull, the raid members all move to their assigned gap between the pillars, and take exactly one step up the stair leading to her. This puts the whole raid in [[LoS]], healing and dispel range of each other, but far enough apart to prevent the Holy Wrath from hitting more than the melee group.\r\nInstead of standing between the pillars, it's just as good if the raid members stand with their backs to the pillars. Just synchronize so that everybody takes the left (or right) pillar, and no two people end up using the same one.\r\n===Repentance===\r\nThere are several ways to survive Repentance:\r\n* A paladin healer casts and refreshes [[Blessing of Sacrifice]] (rank 1) on any melee character to constantly take damage, breaking the effect.\r\n* A paladin uses [[Divine Shield]] to dispel repentance, then heals. This is usable only once per paladin.\r\n* A healer (preferably one which cannot dispel) moves into the Holy Ground after the Repentance cooldown is over. Since it can take a while until she casts Repentance, this may effectively take the healer out of the combat for a while (due to the silence effect). This also increases the danger from a chained Holy Wrath. After she casts Repentance, the healer moves out of Holy Ground and resumes healing.\r\n* The tank moves the Maiden towards a healer, to wake up the healer with damage from Holy Ground.\r\n* The tank is loaded with [[HoT]] spells.\r\n* The tank uses cooldown moves such as [[Last Stand]], [[Shield Wall]], potions, healthstones, and [[Nightmare Seed]]s.\r\n* Melee damage-dealers that can heal (cat druids, retribution paladins, and enhancement shamans) run out to heal during Repentance.\r\nAll of these methods work well, and they work better in combination with each other.\r\n===Holy Fire===\r\nHoly Fire will quickly kill its victim unless removed. It is imperative to deal with it.\r\nThe easiest method to deal with Holy Fire is to have [[Grounding Totem]]s up. With an alert Shaman and a little luck this one totem can absorb all Holy Fires targeted at that group. With one shaman in each group the fight actually becomes quite easy. Grounding totems have a limited range, so positions must be assigned carefully to make sure that everyone in the group is protected.\r\nHoly Fire is a Magic debuff, and thus can be removed by the following:\r\n* Priests' [[Dispel Magic]]\r\n* Paladins' [[Cleanse]] and [[Divine Shield]]\r\n* Felhounds' [[Devour Magic]]\r\n* [[Restorative Potion]]\r\n* Warlocks' [[Spellstone]]\r\n* Mages' [[Ice Block]]\r\n* Rogues' [[Cloak of Shadows]]\r\nHoly Fire can also be spell reflected.\r\nHealers and dispellers must be very alert to deal with Holy Fire. Every raid member needs to be topped off at all times, and Holy Fires must be dispelled as quickly as possible. This cannot be stressed enough, as it is the most important aspect of the fight: ''Dispel as quickly as possible.'' Unless someone would die, cancel the spell you're currently casting to dispel immediately, so you spend less time and mana healing Holy Fire victims. Some raids place two dedicated dispellers on opposite sides of the room.\r\nHoly Fire deals fire damage (not holy), thus [[Major Fire Protection Potion]]s are useful.\r\nThis is the first fight since [[Chromaggus]] where dispelling debuffs is critical. Priests and paladins that are new to this fight usually have some initial difficulty dispelling fast enough to avoid wipes. This is normal, so be patient. Once they have a little practice and figure it out, though, the Maiden is a fairly easy fight.\r\n==Additional Tips and Methods==\r\n* If a Priest casts Shadow Word: Death on the Maiden during the 0.5 second cast of Repentance the backfiring damage will break the Repentance. This requires a timing mod, keeping the Maiden as the target (or using a [[HOWTO:_Make_a_Macro|focus macro]]) during the time she could cast Repentance and of course a fast reaction by the priest.\r\n*Pets are not valid targets for Holy Fire or Holy Wrath, and may thus be sent into melee with no fear of causing a chain.\r\n*Melee should stand at the edge of Maiden's hit box, as far from each other as possible (forming a triangle or square around her). [[Major Holy Protection Potion|Holy Protection potions]] help diminish damage taken by melee significantly, and are recommended over health pots.\r\n*Warriors who pop [[Berserker Rage]] can become immune to or break Repentance. Being immune to Repentance effect also prevents the 2k front-end damage.\r\n*In contrast to some people's belief, paladin tanks can tank Maiden well despite Holy Ground's silence. The silence effect only lasts one second for every three seconds. As all of the paladin tanking skills used during the actual tanking are instant cast, the one second silence does not cause much problem usually.\r\n*[[Dampen Magic]] on melee DPS reduces the Holy Ground tick damage to 150-200 so that a single HoT, shadow priest, or feral druid can keep them alive.\r\n*Amplify Magic is not a good idea at all; it appears to drastically boost her damage.\r\n*The rooms off the hallway prior to the Maiden do not need to be cleared. If you choose to skip them, be sure to hug the wall to your right or you risk drawing aggro from the mobs in the side rooms. The hallway and patrols are on a 60 minute timer. However, the servants quarters adds spawn quicker at 20-25 minutes.\r\n* The following macro is handy for warrior tanks to pull the Maiden to a healer under the effects of repentance:\r\n<pre>/target <healer's name>&#x000D;/cast Intervene&#x000D;/targetlasttarget&#x000D;</pre>\r\n* Priests, paladins, and warlocks may use a dispel assist add-on such as , , or to speed up removal of Holy Fire. The following simple macro is a reasonable replacement:\r\n<pre>/stopcasting&#x000D;/cast [target=mouseover] Dispel Magic</pre>(Replace \"Dispel Magic\" with \"Cleanse\" or \"Devour Magic\" for paladins or warlocks.) Drag the group windows out of the raid panel before the fight. When the Holy Fire icon appears beside someone's name, just point at the name and hit the macro hotkey. No clicking or target switching is required.\r\n* The following macro is useful for Paladins keeping up Blessing of Sacrifice on the Main Tank but are busy targeting other party members with cleanses and heals:\r\n<pre>/cast [target=NAMEOFTANK] Blessing of Sacrifice</pre>The macro will not mess with your targeting at all. Max-rank BoS is recommended since the whole point is to keep the tank up and the pally won't take much damage anyway.\r\n* The Maiden cannot be reset. She will pursue her targets all the way to the zone portal.\r\n* Since Maiden casts Repentance at specific intervals throughout the fight, certain mods exist that can warn the raid of an impending Repentance. This can allow a healer to walk into the Holy Ground effect just before the Repentance lands, instead of having to stand there taking damage for an extended period.\r\n* Beast Mastery Hunters can use [[Bestial Wrath]] just before a Repentance to negate its effect.\r\n* The [[Insignia of the Alliance]] and [[Insignia of the Horde]] can both be used while under the effects of Repentance to break its effect.\r\n==Quotes==\r\n'''Aggro:'''\r\n*''Your behavior will not be tolerated.''\r\n'''Repentance:'''\r\n*''Your impurity must be cleansed.''\r\n*''Cast out your corrupt thoughts.''\r\n*''Impure thoughts lead to profane actions.''\r\n'''Player Death''':\r\n*''Ah ah ah...''\r\n*''This is for the best.''\r\n'''Death:'''\r\n*''Death comes. Will your conscience be clear?''\r\n===Strategy Guides===\r\n{{",},
			["Maiev"] = { content = "#REDIRECT [[Maiev Shadowsong]]", redirect = "Maiev Shadowsong",},
			["Maiev Shadowsong"] = { content = "'''Maiev Shadowsong''', along with her younger brother [[Jarod Shadowsong]], played a key role in the battle against the [[Burning Legion]] during the [[War of the Ancients]]. In the aftermath, Maiev asked to be and was appointed the [[Warden|jailor]] of [[Illidan Stormrage]] and took on the mantle of leader of the [[Watchers]]. Mistress Shadowsong herself now resides in the infernal [[Shadowmoon Valley]] in a prison cell guarded by Illidari jailors and minions, Servants of Illidan, as well as [[Akama]]-led guardians of the Ashtongue Deathsworn.\r\n===The War of the Ancients===\r\nMaiev was originally a young [[Sisters of Elune|priestess]] of [[Elune]] during the [[War of the Ancients]]. She was stationed at the [[Hajiri]] temple in northwestern [[Kalimdor]] just before the War of the Ancients. Like the rest of the sisterhood, Maiev took up arms against the [[Burning Legion]] at the start of the invasion, joining the resistance under [[Kur'talos Ravencrest]]. She could do little but observe the destruction, and witnessed demons slaughtering her family and friends. She was horrified. When [[Tyrande]] was declared the new High Priestess, a disgruntled Maiev raised an opposition, though she knew better than to deny Tyrande's power. Following her disappearance and the death of [[Marinda]], Maiev was elected High Priestess by default. This reunited her with her estranged brother Jarod.\r\nMaiev was an opponent of the leadership of [[Desdel Stareye]], but took no action for fear of dividing the troops. She urged Jarod to do something, but her brother wouldn't listen. After Stareye fell in \"combat,\" and Jarod was recognized commander of the host, Maiev neglected to say, \"I told you so.\" Maiev continued to serve with distinction, and grudgingly relinquished the office of High Priestess back to Tyrande. When she miraculously survived the War of the Ancients, she was certain that arcane magic was a horrid, filthy power that had brought doom to the world. Maiev was selected as Tyrande's second in the sisterhood, and accompanied the leaders of the night elf survivors to their inspection of a water source upon [[Mount Hyjal]]'s summit. There they discovered that a pristine lake had been transformed into a new Well of Eternity by [[Illidan Stormrage]]. \r\nOutraged, the night elves hastened to apprehend the traitor. During Illidan's capture, he unleashed an arcane attempt to resist arrest that nearly claimed the lives of all in the party, rendering [[Dath'Remar Sunstrider]] and Jarod comatose. Only the efforts of Tyrande, [[Shandris Feathermoon]], and Dath'Remar's wife ensured Illidan's capture and the heroes' survival. \r\nKnowing full well where Illidan's ruthless schemes would eventually lead, Illidan's brother [[Malfurion Stormrage|Malfurion]] decided to deal with his power-crazed brother once and for all. With Cenarius's help, Malfurion sealed Illidan within a vast underground barrow prison, where he would remain chained and powerless until the end of time. \r\nThe second Well of Eternity's creation shocked Maiev, and she was glad when Malfurion imprisoned Illidan beneath the earth. In fact, she approached the druid and demanded that she be allowed to watch over him, ensuring that he never escaped to wreak his evil. The young elf's zeal and skills impressed Malfurion, and he appointed her Illidan’s eternal jailor.\r\nThus it came to pass that Maiev led the [[Watcher]]s, a specialist sect of night elves who were not [[Sentinel]]s, dedicated to the imprisonment of the Betrayer and the upkeep of the [[Barrow Deeps]]. Though her primary charge was Illidan Stormrage, Maiev, as senior warden, also served as bounty hunter and assassin of enemies and escaped criminals. Cenarius stationed [[Califax]] and a number of tamed beasts to aid them in their task. Maiev served well for 10,000 years, training constantly.\r\n===After The Third War===\r\nAfter ten thousand years of security, the Barrow Deeps were raided by [[Tyrande Whisperwind]], who recklessly murdered the Watchers and Califax, and then released Illidan from his prison, hoping to use him to defeat the [[Legion]]. However when he absorbed the [[Skull of Gul'dan]], he was banished from [[Ashenvale]]. Despite Illidan's major contribution to the war effort by slaying the [[dreadlord]] [[Tichondrius]], Maiev concluded that the [[Skull of Gul'dan]] made Illidan even more unstable (the truth of the deduction has yet to be established). She resolved to hunt him down and lock him away again.\r\nWith her lieutenant [[Naisha]] at her side, Maiev pursued Illidan throughout [[Kalimdor]]. With his impromptu force of [[satyr]]s and other corrupt creatures, he managed to keep her at bay, but to her credit, Maiev stayed close to him as he fled.\r\nFinally, Maiev closed in on him in [[Queen Azshara]]'s former [[Azshara|provincial holdings]], now on the coast of Kalimdor, where he had destroyed many fishing villages and left nothing but mutilated bodies and flaming footprints in his wake. But Maiev found some tracks which she could not identify...\r\nMaiev soon found the creatures who had made the tracks. They identified themselves as the [[naga]], and professed servitude to Illidan. Maiev defeated them, but was troubled that they were burning boats, and thought that perhaps Illidan meant to flee across the ocean. Maiev took to the port of [[Nendis]], where she found Illidan stealing away in a transport. The naga began to destroy the ships, but Maiev killed them before they completed their task. Maiev quickly found some transport ships, and took the Watchers across the sea.\r\nThey stopped unexpectedly soon when they came across some islands which were not on their maps, but Maiev knew where they were, as she had once spent a great deal of time there. The [[Broken Isles]] were the remains of [[Suramar]]. As she established a base camp, Maiev found landmarks she recognized from the ancient, ruined city, such as the library of [[Izal-Shurah]], and the Boughs of Azshara. Naisha realized that the city must have been raised from the seafloor for some sinister purpose, and Maiev commented that few powers were capable of such a thing.\r\nMaiev found the answer when she came across [[Drak'Thul]], a former [[warlock]] of the [[Stormreaver Clan]]. Drak'Thul told her that he was hunted by ghosts, and that if Maiev rid the island of them he would tell her his tale. The warden later found the ghosts of which he spoke: animated orcish corpses fighting one another, as if reliving a battle fought in their former lives (in fact they were former members of the [[Blackrock Clan]], the [[Twilight's Hammer Clan]] and the [[Stormreaver Clan]]). Maiev destroyed the summoning pits that kept bringing the dead orcs back to repeat the cycle of battle and death and then returned to Drak'Thul to inform him that the dead would no longer trouble him. Drak'Thul then told her his tale as promised. He recounted how he had been a disciple of [[Gul'dan]], the warlock who raised the islands twenty years before to search for the powers of the [[Sargeras|Dark Titan]]. Gul'dan hoped to gain power, but instead he and the rest of his Stormreaver clan unleashed crazed demons who slaughtered all but a handful of the warlocks, Drak'Thul among the survivors. He had lived on the island since, haunted by the ghosts of his dead comrades. Maiev told him that he deserved a far worse punishment than that for what he and the Stormreavers had unleashed. Troubled by the news, Maiev suspected that the [[Tomb of Sargeras]] was Illidan's goal here, as well. After [[The Broken Isles|battling]] through his ample forces of naga, Maiev and Naisha chased Illidan into the Tomb itself.\r\nWhile there, Maiev read magical orcish runes Gul'dan had created to relate his tale. It continually referenced an \"Eye,\" which seemed to be an artifact, and Maiev guessed that this was what Illidan sought. Maiev and Naisha realized that the Eye must have been tremendously powerful for Gul'dan to have been lured by it so potently. ''It was never revealed how Maiev gained the ability to read orcish runes.''\r\nMaiev soon had a run-in with the leader of the naga, [[Lady Vashj]], who told her that the night elves' justice had no place in the Broken Isles. Maiev asked Vashj what she knew of their justice, and Vashj replied that she was once a night elf herself, and that the explosion of the [[Well of Eternity]] had transformed them into the naga. ''She may have actually recognized who Vashj was from Tyrande's accounts of the events at Zin-Azshari.''\r\nMaiev, however, displayed a simple revulsion for the Naga, and chased Illidan into the central chamber, where he had already found the [[Eye of Sargeras]]. Since Illidan had been confined by Maiev for ten thousand years, he felt that trapping her in the tomb (alive or otherwise) was the least he could do to repay her, caving in the Eye Chamber before teleporting himself out. Naisha and the Watchers were stranded, but Maiev, using her abilities, teleported through the temple and reluctantly left her forces to die in the dark tomb.\r\nMaiev battled an army of naga as she sent a [[Night Elf Runner|runner]] out to sea to get a message to Malfurion Stormrage to plea for assistance. She was being attacked by a large naga force led by [[Serena Scarscale]]. After a desperate battle, the runner was away, and Maiev quickly returned to her base to defend her Watchers.\r\nAfter taking heavy damage, on the island of the [[Broken Isles]] south of [[Izal-Shurah]], Maiev was finally reinforced by Malfurion, but was displeased to find that Tyrande had come along as well. She snidely proclaimed that Tyrande deserved to be locked in a cage just as Illidan was, to which Tyrande fired back that she was doing what was right at the time. Before things got out of hand, Malfurion told them to let it be for now and focus on the matters at hand, namely winning the battle against the naga forces led by [[Lady Serpentra]]. After they defeated the naga, however, Illidan took to the sea and fled once again. The three heroes were quick to follow.\r\nThey arrived upon the shores of [[Silverpine Forest]] in [[Lordaeron]]. After Malfurion left them to commune with the forests, Maiev bowed to Tyrande's greater knowledge of the [[Alliance]] and Tyrande met [[Kael'thas]], the prince of the [[blood elves]]. When told of Illidan, Kael thought that perhaps that was the reason that the undead were so agitated in [[Dalaran]]. Maiev wanted to get back on the hunt as soon as possible, but Tyrande wished to help Kael; Maiev's objections were silenced when Kael agreed to help them fight Illidan. The two warriors escorted Kael's caravan to [[Pyrewood Village]], where they were suddenly ambushed. Kael and Maiev saw his caravan across the river while Tyrande held the line on the bridge. When she called down the [[Starfall|stars]] of [[Elune]] to destroy the undead, Elune's fury was unleashed. The bridge, unable to stand the weight of a fully armored night elf on tigerback, crumbled beneath Tyrande, and she was swept down the river.\r\nKael was about to attempt to save her when Maiev stopped him. She knew that time was growing short, and that Illidan had to be stopped, and insisted that Tyrande had been prepared to make the sacrifice if needed. She demanded that Kael help her find the demon in return for her assistance protecting his caravan. Kael helped her track Illidan to Dalaran's ruins, where they met up with Malfurion, who had felt the land being torn apart and seen a vision that it was Illidan's doing. He suspected the worst and feared for the fate of the world itself. Maiev told Malfurion that Tyrande had been ''torn apart'', and that his only recourse was to gain revenge on Illidan. Maiev reminded Malfurion that Tyrande would never have come to Lordaeron and met her alleged death if not for Illidan's actions, and thus he was to blame. Malfurion's grief and anger made him completely focused on stopping and punishing his brother, just as Maiev had hoped.\r\nWith the help of Kael and a [[paladin]] of the [[Silver Hand]] - [[Magroth the Defender]] - Maiev and Malfurion pushed back Illidan's naga on the [[Dalaran|Dalaran ruins]] and destroyed the [[Naga Summoner]]s casting spells around the Eye. Cornering Illidan with the night elf and Alliance forces, Malfurion grimly told his brother that for what he had done this time confinement would not be sufficient and that he was to be put to death. Maiev enthusiastically volunteered to execute him personally then and there. Illidan explained that his spell had not been meant to harm anybody but the [[Lich King]] at [[Northrend]] and his undead servants, whom the Night Elves surely had no love for. His spell had been specifically targeting the area where the Frozen Throne was based. Not placated, Malfurion raged that Illidan had given no thought to the cost of his actions and that Tyrande had died because of him. Illidan was shattered by this statement, since he had never wanted anything to happen to the woman he loved and had even tried to dissuade her from following him to Lordaeron since he was concerned for her safety. Then Kael spoke up, much to Maiev's chagrin, saying it was premature to pronounce her dead. The elven prince explained the bridge's collapse and the noted absence of tearing apart. Malfurion, understandably furious with Maiev for her lies, entangled her. He asked her bitterly who the \"betrayer\" was now.\r\nThey found Tyrande in [[Silverpine Forest]]. Now that there was hope, Illidan was quick to volunteer the services of his naga who could scour the river and locate Tyrande faster than the night elves. Malfurion accepted his offer, and they were able to save Tyrande.\r\nWhen Maiev finally did get free (exactly why it took her so long isn't explained), she tracked down Malfurion, and found him allowing Illidan to go free. Furious at his apparent folly, she took what Watchers would follow her and pursued Illidan into the portal he had formed, ignoring Tyrande's insistence that Illidan was no longer a threat. Furion alone knew what Maiev had become: she was now vengeance itself.\r\nWhen she arrived on the other side, she found herself in the ruins of the orcish homeworld, [[Draenor]]. Now, though, without his servitors to protect him, Illidan was easy prey. Maiev and her followers pursued him long and hard in the desolate, broken wasteland, and eventually, she caught him and imprisoned him under a magical sedative.\r\nAs she was escorting him back to her base, however, Maiev was ambushed by [[Lady Vashj|Vashj's]] naga, and - to her shock - [[Kael'thas Sunstrider|Kael's]] blood elves. The Watchers fought Illidan's forces back and forth for control of Illidan's prison wagon, but eventually Kael and Vashj were victorious, and the wagon was secured at his base. There have been rumors that an unidentified [[pandaren]] assisted in the rescue, but these have been neither confirmed nor disproved (see \"[[Pandaren_Brewmaster|Appearance in The Frozen Throne campaigns]]\" section of [[Pandaren Brewmaster]]).\r\n===The Burning Crusade===\r\nMaiev first appears in the Warden's Cage in Shadowmoon Valley, guarded by Akama and his Ashtongue Deathsworn. She is indignant that Akama seems to be merely sitting there, scheming, while Illidan's grasp over Outland tightens. However, Maiev and Akama join forces to overthrow Illidan, and enter the [[Black Temple]] aided by their allies (at the end of the [[Medallion of Karabor]] quest chain). Akama begins the encounter with Illidan and aids the party in battling him. At some point towards the end, Maiev joins the party and helps out by laying traps to incapacitate Illidan.\r\n==Personal traits==\r\nMaiev is a driven, austere individual. She both fears and despises arcane magic, and shows her derision openly to its practitioners. Aloof and silent, Maiev is always concerned with her duties or latest assignment. She does not care for the company of others; she refuses to let interpersonal relationships interfere with her cause. Maiev moves with fluid, deadly grace. Her voice is velvet-covered steel. Maiev is cold; her only warmth comes from her rage when she thinks of the Legion’s destruction and Illidan’s horrible treason. Hers is an achingly lonely existence. \r\nMaiev sees things very much in black and white, and in recent years, had belief in the concepts of rehabilitation or redemption that she was trained to uphold in Elune's name. She is unwilling to forgive any association that is tied to the Legion or brings harm to others, whether a large one such as Illidan's ultimately siding with Azshara and causing the deaths of millions of life-forms or a comparatively small one such as Drak'Thul's presence during the raising of the [[Tomb of Sargeras]], leading to the deaths of many orcs.\r\nMaiev is loyal to her comrades and determined to ensure they come to no harm. Her fury at Illidan was originally motivated by her disapproval of his actions with Azshara and the fact that he nearly killed Jarod. Later, she is driven to blind hatred after his murder of Naisha and the other Watchers. \r\nBy tracing her personality first as a priestess, then as a warden, and finally as vengeance, we can see how she came to hate Illidan in particular. Her election as Illidan's jailor really meant that she became as much a prisoner as he; they merely occupied opposite sides of the bars. Given that, her resentment and rage towards Illidan is easy to understand.\r\nHer first motivation was to punish Illidan for his transgression (which a Kaldorei tribunal sentenced him to, not she), then to stop him from killing anyone else, and finally, pure vengeance.\r\n==Combat==\r\nMaiev prefers to strike vulnerable targets from surprise, often sending her forces to distract the enemy while she uses her blink ability to appear behind them. She throws a slicing torrent against lesser opponents, or uses her Fan of Knives feat if surrounded. If facing her quarry, she uses the umbra crescent’s‡‡ greater shadow strike ability before moving in to attack. After one strike, she blinks away and casts hold person. If the target succumbs to the spell, she moves forward quickly to finish him off or secure the captive. If he resists hold person, Maiev activates her weapon’s quickened shadow strike abilities to assail her target at range. If the enemy still stands, she uses her own lesser shadow strike†† ability and charges into melee, where she wields her umbra crescent with two hands. If pressed, Maiev flees via blink, greater invisibility and expeditious retreat.\r\n==Presumed death==\r\nAccording to The Frozen Throne, Maeiv was \"slain\", and several sources say that Maiev Shadowsong's died or is believed to have been slain (see ''[[Alliance & Horde Compendium]]'' page 9, ''[[Shadows & Light]]'' page 51 and ''[[Alliance Player's Guide]]'' page 68, and Warcraft Encyclopedia).\r\nThe \"death\" originates from the mission, The Search for Illidan, in which the mission objective is to slay the guardians of the cage, the [[Watchers]], carrying Illidan to the [[Sentinels]] base. There were four guardians included Maiev;\r\nLord Illidan has been captured by the cunning Warden in a cage of magical enchantments. Slay the guardians of the cage and take it from the Night Elves before they reach safety the safety of their base.\r\nTo complete the mission objective, Maiev must be \"slain\" along with the other three Watchers, in order to unlock the next mission. After being \"slain\" she is resurrected several times from an invulnerable [[Altar of Elders]] (though it became vulnerable if the complete night elf base was destroyed) in the [[Sentinels]] base, her death can be explained away with the [[resurrection]]s.\r\nHere's the corresponding quote from ''Shadows & Light'':\r\n''Sinking into vengeful madness, Maiev pursued Illidan all the way to Outland. Emotion clouded her vision, and Illidan slipped away from her several times. Finally, when Maiev was all but blinded by frustration and vengeance, the Betrayer got the better of her. Maiev died alone on the red sand, unmourned, unsung, with none to remember her fall, her soul empty of all but rage.''\r\nThe [[warden]] article in Alliance Player's Guide discusses the information from an in-universe POV, and mentions that other wardens believe she died, and the ways they view her \"failure\". Here is the corresponding quote from Alliance Player's Guide;\r\nThe most (in)famous warden is Maiev Shadowsong, the woman responsible for keeping the most dangerous prisoner in night elf history - Illidan Stormrage. Maeiv failed in her duties, as all know, and hunted Illidan across Azeroth and Outland to retrieve him. Her hunt and failure embittered her, and when Illidan bested her in Outland, Maiev died alone and hollow on an alien, red world. Despite Maiev's failure, many young wardens see her as the epitome of dedication. Though her charge escaped, she pursued him across the worlds, giving up only when death prevented her from continuing her chase. Other wardens view Maiev with ambivalence, seeing her single-minded focus as responsible for her failure.\r\nWarcraft Encyclopedia explains further;\r\nHer lengthy absence from Azeroth, together with Illidan's continued freedom, has led the night elves to presume her dead\r\nShe was presumed dead for the five years after she disappeared through the portal, slain during her pursuit of vengeance..\r\n==Memorable quotes==\r\n*\"Blood elves and naga! Your bastard races are an affront to everything the night elves stand for!\"\r\n*\"[[Illidan]] has grown powerful - of that there is no doubt. He consumed the energies of the [[skull of Gul'dan]]. Now he is neither Night Elf nor demon - but something more.\"\r\n*\"Naga? Many craven races have tempted our wrath over the centuries. None have survived!\"\r\n*\"Illidan has much to answer for. He'll wish he were still chained in his cell when I get through with him.\"\r\n*\"I am the Hand of Justice, Illidan. Long ago, I swore an oath to keep you chained... and by all the Gods - I shall!\"\r\n*\"Illidan Stormrage, for recklessly endangering countless lives and threatening the very balance of the world, I hereby sentence you to death!\"\r\n*\"Their fury pales before mine, Illidan. We have some unsettled business between us.\"\r\n*\"[[Illidan Stormrage|He]] is right. I feel nothing. I am...nothing.\"",},
			["Mail"] = { content = ":''This article is about sending mail in WoW. For information about mail armor (e.g. plate mail, chain mail, etc.), see the articles [[Mail armor]] and [[Armor]].''\r\n----\r\nIn [[World of Warcraft]], '''mail''' is a means of communicating messages or shipping items between [[Player]] characters, from [[NPC]]s, or the [[Auction House]].\r\n==Messages and Shipping==\r\nThe in-game mail system provides a way to send messages and items among [[Player]] characters and from [[NPC]]s or the [[Auction House]] to player characters.\r\n===What mailboxes look like===\r\n===How do I check mail?===\r\n# Find a [[Mailbox]], usually near an [[Inn]]. (see [[Forges, Anvils, and Mailboxes]] for a list of detailed locations)\r\n# Right-click the Mailbox.\r\n#:Pointers for using mailbox:\r\n#: ''in range to check'' ''out of range''\r\n# Click the Inbox tab, if necessary (Inbox should be the default).\r\n# Click a message to read it. ''(Prior to [[Patch 2.1.3 (Release Notes)|Patch 2.1.3]], the expiration time in days dropped to 3 days once you open a message to read.)''\r\n# In the message window you have the following options:\r\n#* Click the message icon in the first \"Take Attachments:\" [[slot]] to save a copy of the message (only if the message has a body).\r\n#* Click the [[item]] in the second \"Take Attachments:\" [[slot]] to move it to your [[Backpack]].\r\n#* Click the [[money]] icon in the third \"Take Attachments:\" [[slot]] to move it to your [[Backpack]].\r\n#* Click Reply to create a reply message (see \"How do I send mail?\" below).\r\n#* Click Return to return the message to sender without taking any remaining attachments. \r\n#* Click Delete to delete the message when you are finished with it.\r\n#* Click Close to close the message window.\r\nAdditional notes:\r\n* Any [[money]] enclosed will deposit to your character when the message opens, you click the coins icon and it disappears.\r\n** Enclosed amounts < 1 gold will appear as a [[silver]] coins icon.\r\n** Enclosed amounts &ge; 1 gold will appear as a [[gold]] coins icon.\r\n* Items in COD messages will not move to your backpack until you agree to pay the specified money amount (deducts automatically when you accept).\r\n===How do I send mail?===\r\n# Find a [[Mailbox]], usually near an [[Inn]].\r\n# Right-click the Mailbox.\r\n# Click the Send Mail tab (Inbox should be the default).\r\n# In the To: field, enter the name of the recipient.\r\n#: Notes: Names in your [[Guild]] and [[Friends List]] will auto-fill.\r\n#: Mail can not be sent to characters in the opposing faction (e.g. Alliance characters can't send mail to Horde characters)\r\n# In the Subject: field, enter the message title.\r\n#: This is optional if any items are attached to the message; the name and quantity of the first attached item or stack will auto-fill the subject if it is left blank. (e.g. \"Gold Bar (20)\" if a stack of 20 gold bars is attached)\r\n# Optionally, enter a message in the message body. (The message body has a limit of 500 characters.)\r\n# In the message window you have the following options:\r\n#* Optionally, drag an [[item]] or stack of items to an item [[slot]].\r\n#*: Notes: In [[Patch 2.3]], 11 more slots for items were added (see image to right; only 7 visible at a time).\r\n#* Optionally, enter an amount of [[money]].\r\n#* Optionally, change Send Money radio button to [[Cash on Delivery|C.O.D.]] \r\n#* Click Send to Send the message.\r\n#* Click Cancel to close the message window without sending.\r\nAdditional notes:\r\n* A confirmation warning appears, if the message has any [[money]] enclosed with the Send Money option selected.\r\n* Returning mail sends it back to the sender. In some cases you can't return mail, because the character was deleted or moved to another realm, so the sender is listed as ''Unknown''.\r\n===How long does delivery take?===\r\n* Simple messages arrive immediately.\r\n* Mail from the same [[account]], regardless of attachments, arrives immediately.\r\n* Mail from another account if items or money are attached takes one hour.\r\n* Mail from the [[Auction House]] to the seller with the money attached takes 1 hour, although a notification mail is sent immediately (New with [[Patch 2.2]]).\r\n* Return mail arrives immediately.\r\n===Mail expiration===\r\nMail received stays in your [[mailbox]] for 30 days. Prior to patch 2.1.3, mail that you read would only last for 3 more days.\r\nAfter the expiry period the mail is returned to the sender. If the mail comes from the [[Auction House]], a quest NPC, or anything similar it is simply discarded and any item or money attached is lost.\r\n===Mailbox size===\r\nThe maximum number of messages that a Mailbox can hold is unknown, but the Mailbox will only display the first 50 messages. Any messages over 50 will still exist within the Mailbox, but will not be displayed. To view the messages beyond the first 50, some of the messages will have to be removed (by reading and taking the attachment or by deleting). Once a message has been removed (making a spot available for one of the non-displayed messages), simply close the mail window, and reopen the mailbox. (Prior to patch 2.0.10, you would need to logout or talk to an auctioneer)\r\n===Non-player senders of mail===\r\nSometimes [[NPC]]s send mail with [[money]], [[item]]s, or just messages to player characters, usually related to completion of a [[quest]].\r\nThe [[Auction House]] will send mail in the following situations:\r\n* Money from failed bids returned in mail.\r\n* Items that failed to sell in auction returned in mail.\r\n* Items you placed a winning bid on.\r\n* Money from successful auction sales arrive in mail.\r\n* Items from cancelled auction listing and listing money refund.\r\nBlizzard [[Game Master|GMs]] may send you in-game mail in response to [[open ticket]]s.\r\n[[Battleground]] Marks of Honor you may not receive upon the completion of a battle will be sent by Mail, with an expiration of 24 hours.\r\nMr. Pinchy will send you your Mr. Pinchy's Gift if your inventory was full when you \"spoke with him\".\r\n==See also==\r\n* [[Cash on Delivery|COD]]\r\n* [[Forges, Anvils, and Mailboxes|Mailbox Locations]]",},
			["Mailbox"] = { content = "#REDIRECT [[Mail]]", redirect = "Mail",},
			["Mailboxes"] = { content = "#redirect [[Mail]]", redirect = "Mail",},
			["Mail armor"] = { content = "'''Mail [[armor]]''' is worn by [[warrior]]s and [[paladin]]s below level 40, as well as [[hunter]]s and [[shaman]]s above level 40. At level 40, both warriors and paladins gain access to [[Plate Armor|plate armor]].\r\nSome mail [[armor set]]s:\r\n*[[Chain of the Scarlet Crusade]] - Ideal for Levels 30-40\r\n*[[The Elements]] - A level 60 Shaman specific set\r\n*[[Gronnstalker's Armor]] - The [[tier 6]] [[hunter]] set\r\n==See also==\r\n* [[Mail armor randomized set]]\r\n* [[:Category:World of Warcraft mail items]]",},
			["Maim"] = { content = ":''Were you looking for [[Maim Blackhand]], brother of [[Rend Blackhand]]?''\r\n \r\n''Your legs look tired. Let me fix that for you.''\r\n'''Maim''' is a finishing move that deals damage and incapacitates the target.\r\n==Rank table==\r\n*Damage formula: (x+w)-(x+W), where w indicates low end weapon damage, W indicates high end weapon damage, and x indicates bonus damage per combo point:\r\n*1 point: 129\r\n*2 points: 213\r\n*3 points: 297\r\n*4 points: 381\r\n*5 points: 465\r\n==Notes==\r\n* Bleed effects/DoTs continue to damage the target without breaking Maim. Therefore, using [[Pounce]] and a combination of [[Mangle]](cat) and [[Rake]] will not only allow you to stun the target with decent damage, but also your bleeds will continue to damage the target.\r\n* This is an incapacitation, NOT A STUN. It will stop spellcasting, but any damage that is not a bleed/DOT may stop the effect.\r\n* Maim does not directly interrupt spells: incapacitation does, but many mobs are immune. Season 3 Feral gloves add a counterspell-lock to Maim that is applied independently from the rest of the effect.\r\n* Maim produces a very distinctive noise.\r\n==Tips and tactics==\r\n*A four combo point Maim gives you enough time to heal yourself with a Healing Touch, or give your energy enough time to regenerate for a Shred. Also in 1vs1 you may have time to [[Prowl]] and [[Ravage]] or [[Pounce]] again.",},
			["Maim Blackhand"] = { content = "'''Maim Blackhand''' was the son of former warchief [[Blackhand|Blackhand the Destroyer]], brother of [[Rend Blackhand]] and [[Griselda]].\r\nAfter their father’s assassination, Maim and his brother Rend took what followers they could and splintered off from the [[Blackrock Clan]], making the [[Black Tooth Grin]] clan. They did this to retain some of the power which they believed was their birthright, without directly opposing [[Orgrim Doomhammer]]'s accession to power. So he would take no action against them. During the [[Second War]], they were given control of the [[Dark Portal]]. Some rumors say that Maim retreated with Kilrogg Deadeye to Draenor, only to die there to human blades or betrayal. However, this was not the case.\r\nSometime after the Second War, Rend and Maim set up a base in Blackrock Spire, serving as dual chieftains over the Black Tooth Grin clan and the weakened Blackrock clan forming the [[Dark Horde]]. About two years later, the portal reopened and emissaries from [[Ner'zhul]] were immediately sent to Rend and Main asking them to rejoin the Horde and to borrow the red dragons held captive by the allied [[Dragonmaw clan]]. Rend refused. Not long after [[Nefarian]] came to Blackrock Spire and took control of the Blackhand brothers and the forces under their control.\r\nEventually, Dark Iron dwarves from Blackrock Depths tried to destroy the Dark Horde. The Dark Horde fought back, and Maim was killed in savage battle. His sacrifice, plus Rend's \"alliance\" with the black dragonflight, allowed them to drive back the Dark Irons and maintain their hold on Blackrock Spire.\r\n==History as told by [[Eitrigg]]==\r\n''At the end of the Second War, Rend and his brother, Maim, fled to find sanctuary within the mountainous stronghold of [[Blackrock Spire]]. It was there that Rend declared himself Warchief of the weakened Blackrock clan.\r\n''Rend and his brother Maim ruled the Spire, in constant conflict with the [[Dark Iron Dwarves]]. They managed to displace the dwarves in the upper portion of the city, but only after the [[Black Dragonflight|dragons]] came and only after the death of Maim.''\r\n==Removed from game?==\r\nSimilar to Garona being removed from the game, Maim had his own npc that is still located in the game as creature 17028: Maim Blackhand. His model appears to be that of a [[Fel Orc]], or a chaos orc as he does not seem to have spikes or any serious mutations, just red skinned. Whether this was a place holder or Maim somehow became a fel orc is unknown.",},
			["Main"] = { content = "'''Main''' refers to a [[player]]'s primary [[player character]]. Sometimes this is the first character the player created and played, but often it is not. A player's main is usually the one that has seen the most play time and investment of resources and usually is the highest level out of any other [[Alt]]s.\r\nIn addition to their main, many players have one or more [[alt]]s.\r\nSee also [[Dual box]].",},
			["Main assist"] = { content = "'''''Please note that since the introduction of [[Raid target icons]] in Patch 1.11, main assists are not commonly used anymore.'''''\r\nThe '''main assist''' (MA) is the player in a [[raid]] or [[party]] who calls the shots on which [[mob]] should be taken down next by the [[damage dealer]]s. The main assist's job is to have one specific mob targeted at all times until it's dead, and then to switch to the next target to be killed, whereas the main tank must switch targets frequently to keep [[aggro]] up. In many cases, the MA will sometimes also serve as off-tank which means he will peel the mob he's dpsing off from the tank (by taunt or pulling dps aggro). In five-man groups having a non-tanking warrior, this is common but not universal.\r\n==Introduction==\r\n<div style=\"margin-left:3%;\">\r\nAny party with more than one attacker should have a '''main assist''' (MA). This is important to reduce the damage being dealt to the party. Concentrating on one mob at a time reduces the inbound damage faster than every one killing their own mob.\r\nIdeally the MA will be familiar with the instance and must be able to prioritize the targets at hand. Prioritizing targets is very hard to quantify and depends almost always on the specific circumstances. However, as a general rule of thumb, you must ensure your [[squishies]] are ok, and then take down the [[healer]]s, [[summoner]]s, [[nuker]]s, and then the rest. This is where knowledge of the instance comes in.\r\n* If there is a [[mob]] who can nuke your whole party in two shots, take him out first\r\n* Mobs doing [[AoE]] damage increases the inbound damage to the party a ''lot'' and needs to be taken out of the fight.\r\n* If there is a [[heal]]ing mob, it will prolong the fight unnecessarily by keeping your enemies alive longer. It should probably go down fast.\r\n* If the [[main tank]] is having problems building [[aggro]] on one mob (perhaps due to the mob staying at range far away from the rest), that mob will want to target the party's healer. It is a high priority to dispatch.\r\n* When left only with \"regular\" mobs, i.e. ones doing roughly the same kind of damage to the tank, it is best to first target the ones that will go down faster, e.g. ones already damaged, or non-[[elite]] mobs over elite ones.\r\nNaturally, the ordering depends on the instance and case in hand. Also, some of the more dangerous and/or annoying mobs can be [[crowd control]]led, or some simply [[off-tank]]ed somewhere out of range where they can't cause much trouble. The party [[leader]] will usually call these shots ahead of the fight.\r\nHaving a main assist makes both [[tanking]] and [[healing]] easier. Since most [[mobs]] will not have too much aggro, the Main [[tank]] just has to keep an eye on managing aggro, and mainly concentrate on the MA's target, and it obviously helps the [[healer]] since they don't have to heal everyone who accidentally gets [[aggro]].\r\n The '''main assist''' is not to be confused with a [[main tank]] who manages the [[aggro]]. There is also a common misunderstanding that the MA is the one that assists others (this is sometimes called '''sweeping''').\r\n===Classes suitable as main assist===\r\n<div style=\"margin-left:3%;\">\r\n* [[Hunter]]s have the [[Hunter's Mark]], which helps to identify the mob which is selected to the party.\r\n* [[Rogue]]s do not need to switch targets, and they are not expected to take the aggro, but if they do, it is probably because dps is high enough that the mob he pulls aggro on will die in a matter of just a few seconds.\r\n* [[Warrior]]s not responsible for being the [[Main tank]] or [[Off tank]].\r\n* group or raid [[leader]] posses the ability to place identifying marks over key mobs, which can be used at the beginning of a fight to designate which mob should be considered the main target. While this technically does not fit the definition of main assist the concept of focusing on the pre-marked mob first is similar to having a main assist and provides the same advantages. If using this tactic make sure you know which mark is designated for damage as often other marks are placed on mobs to be [[CC]]’ed and you will not want to attack those opponents.\r\n</div>\r\n===Classes that should not be main assist===\r\n<div style=\"margin-left:3%;\">\r\nClasses who change their target often due to other party duties are not particularly useful MAs. Classes dealing ranged damage usually have more oversight. [[Mage]]s sometimes have their sheep targeted, all healing classes also tend to target something else from time to time. Tanking [[warrior]]s must keep switching targets around them to make sure they don't run off and go kill a [[squishy]].\r\n</div>\r\n</div>\r\n==What the Main Assist wants You to do==\r\n<div style=\"margin-left:3%;\">\r\nIf a party has a main assist, then other members of that party should be helping the MA to take that target down. Obviously this should not get in the way of other roles such as [[healing]], [[crowd control]], etc.\r\nIt is ''invaluable'' to have a macro set up such as the [[Most_used_macros|Assist Main Tank/Main Assist]] macro. Being able to target the MA's target with the press of a key is much quicker and less error-prone than having to first target the MA and then press a key to target ''his'' target. An alternative is to use a target-frame [[AddOn]] which continually shows the target of the MA, and that you can quickly click on.\r\n</div>",},
			["Main Chambers Access Panel"] = { content = "The '''Main Chambers Access Panel'''s are located in [[Steamvault]] behind Hydromancer Thespia and Mekgineer Steamrigger.\r\n==Usage==\r\nThese panels grant access to go further in Steamvault.",},
			["Main Hall"] = { content = "#REDIRECT [[Main Hall (Northshire)]]", redirect = "Main Hall (Northshire)",},
			["Main Hall (Northshire)"] = { content = "The '''Main Hall''' of [[Northshire Abbey]], located in [[Northshire Valley]] in [[Elwynn Forest]], is the part of the abbey through which all access to the tower, [[Hall of Arms (Northshire)|Hall of Arms]], and [[Library Wing]] is done. This is also where young [[human]] adventurers receive their first quests.",},
			["Main Hall (Tyr's Hand)"] = { content = "''Were you looking for the [[Main Hall (Northshire)|Main Hall]] of [[Northshire Abbey]]?''\r\nThe '''Main Hall''' of [[Tyr's Hand Abbey]], located in [[Tyr's Hand]] in the [[Eastern Plaguelands]], is the part of the abbey through which all access to the tower, [[Hall of Arms (Tyr's Hand)|Hall of Arms]], and [[Library Wing (Tyr's Hand)|Library Wing]] is done. It is heavily patrolled by the [[Scarlet Crusade]].",},
			["Main hand"] = { content = "The primary [[weapon]] hand [[slot]] for [[weapon]]s that only need [[one-handed|one hand]] to wield ([[equip]]), but also used for [[weapon]]s that require [[two-handed|two hands]].\r\nAdditional notes:\r\n* Information about the [[weapon]] should tell you if it can be used on the Main Hand.\r\n* The other hand is known as the [[off hand]].\r\n* For those with [[dual wield]] capability, [[weapon]]s identified as Main Hand can not be used in the [[Off Hand]] slot.\r\n* [[Two-handed]] [[weapon]]s use both Main Hand and [[Off Hand]] slots, but the [[Off Hand]] slot will appear empty.\r\n*[[Patch 2.4.2]] changed many Main Hand [[weapon]]s into [[one hand|one-handed]] [[weapon]]s",},
			["Main Tank"] = { content = "#REDIRECT [[Main tank]]", redirect = "Main tank",},
			["Maith'hal"] = { content = "'''Maith'hal''' is a [[high elf]] [[mage]] and a member of the [[Alliance]]. He owns a Staff of arcane missiles. It is simply a quarterstaff combined with a wand of arcane missile. He has much knowledge of the [[planes]] and arcana, and is able to decipher scripts. His knowledge of spells includes; detect magic, light, burning hands, protection from evil, frost armor, and mana burn. He was once hired by [[Molus Blackburn]] (who had been in disguise) to break into the lair of the necromancer [[Toren Snapjoint]] and destroy him. She was hired along with fellow Alliance members, including [[Widge Whistlevalve]], [[Botrek Pahno]], [[Cerise Moonrain]], [[Jarlath Brewbelly]], and [[Yinny]]. After battling Toren, his acolytes and his undead servants in the necromancer's cave, Molus, entered the cave no longer disguised, and with some hired muscle. He attacked the weakened heroes, however Maith'hal and the other heroes managed to defeat him after a tough fight.",},
			["Majis'Tomon"] = { content = "'''Majis'Tomon''' is a male [[nerubian]] [[spiderlord]] [[aristocrat]]. He is the chief lawgiver of the [[Sundered Monolith]]. He was 77 years old when [[Brann Bronzebeard|Brann]] met him.",},
			["Majordomo Executus"] = { content = "At the top of the elemental hierarchy, just beneath [[Ragnaros]] himself, resides '''Majordomo Executus'''. This flamewaker gained his exalted status by proving to be nearly invincible in the battles that raged within the elemental plane. Rumor has it that Executus supplanted [[Baron Geddon]], and the two have been rivals ever since. Although this rumor has yet to be confirmed, there is certainly no doubt that Ragnaros does not tolerate failure. Thus, the lesser [[flamewaker]]s (and, of course, Baron Geddon) eagerly await a misstep by Executus, anticipating their chance to vie for the coveted attention of the Firelord.\r\nExecutus will only be spawned after you have defeated all the other bosses in Molten Core and doused the runes using [[Aqual Quintessence]]. You obtain the Aqual Quintessence by gaining Honored status with the [[Hydraxian Waterlords]], and completing the quest chain ending with [[Quest:Hands of the Enemy|Hands of the Enemy]].\r\nExecutus comes with four [[Flamewaker Healer]]s and four [[Flamewaker Elite]] guards making this a total of a nine enemy encounter. Executus will \"submit\" and the fight is won when all the adds are dead. He then appears in Ragnaros' chamber and will summon the Firelord to begin the encounter.\r\n===Majordomo Executus===\r\n*Does not hit particularly hard, but must still be tanked as he can do serious damage to the lower armor class characters in the raid.\r\n*Aegis of Ragnaros : Majordomo frequently casts this spell on himself, absorbing 30,000 damage, reflecting 250 damage on successful melee attacks, and healing himself to full. This means that it is literally impossible to kill him.\r\n*Shield : The shield spells last for 10 seconds before fading. Majordomo will give the shield to all his followers.\r\n**Purple Shield – While this shield is up, up to 100 melee damage per hit reflects back to those inflicting it.\r\n**White Shield – While this shield is up, Each magic attack has a 50% chance to reflect back to the attacker.\r\n*Teleport – Any enemy Majordomo is engaged with can be targeted with this random spell that teleports its target into the nearby fiery pit of Molten Core. There is nothing to counter this ability aside from running back. You'll also get randomly hit with 1-2K fire damage while standing on it, so move out quickly. Whoever has been teleported to the center should be overhealed as not to die.\r\n*Blast Wave – A damaging area of effect flame attack which hits nearby players with moderate fire damage.\r\n===Elites===\r\n*Hits a tank for 800 - 1000 damage\r\n*Fire Blast deals 900 - 1200 fire damage\r\n*Shield – Same as Majordomo.\r\n*Blast Wave – Same as Majordomo.\r\n===Healers===\r\n*Shield – Same as Majordomo. Do not have your groups' mages cast Polymorph on the healers while the white shield is up, as they can sheep themselves.\r\n*Random Shadowbolts – The Healer’s will also hit random secondary targets with ~1000 damage shadow bolts at raid members in range.\r\n==Strategies==\r\nMajordomo is not the target of this encounter, to win you must kill all his guards. \r\nYou can sheep the healers, however you can only keep them \"chain-sheeped\" for the beginning of the battle, but sheeping is disabled after 4 of the adds die.\r\nUse [[Stun]] and [[Counterspell]] when bringing down the healers. This is important for stopping spell casting and bringing them down fast.\r\n===Pull===\r\nThe [[MT]], a hunter, and a paladin will engage Majordomo. The paladin will pull with divine shield. This paladin will attempt to stand closer to Domo than the MT throughout the fight; Majordomo usually teleports the closest player to him to the fire pit. The hunter distracting shots Domo whenever he charges off so that the tank can regain aggro. Majordomo is susceptible to [[Taunt]], but teleporting the MT, thus lowering his aggro makes him randomly wander away from the MT and into the main raid.\r\nAlternatively you can use a fifth [[Mage]] using [[Ice Block]], or hunter pet to pull Majordomo.\r\n===Sheeps===\r\n[[Mage]]s will pull their adds from the group with [[Counterspell]] and then sheep them. [[Hunter]]s will pull their adds to the [[Tank]]s. From a mage point of view, while sheeping, it is critical to drink a Fire protection potion 2 minutes prior to the fight. As well, while sheeping, you should ALWAYS have [[Mana Shield]] / [[Fire Ward]] up, as well as detect magic on the sheep. Never lose your target unless you are far away from all other sheeps and you keep your eye on it. Bandage right after casting a new polymorph. Do NOT [[Polymorph]] while magic reflection is up. [[Sheeping]] is fine with damage reflection. At the pull, mages should have fire ward/mana shield up. Get within max distance of Counterspell and use it to pull aggro, and immediately sheep.\r\nBe sure to keep notice of which shields are up on the mobs. White means that casters should take a break from hurling DPS, and purple means that melee classes should stay back (aside from the tank, who should be keeping aggro). We have mods which will give notification when the shields go up and down.\r\nEach [[Paladin]], except the portal caster, is assigned to a mage. If the healer unsheeps while shield is up or the mage dies, pally needs to stun or off tank till shield is down. Alternatively you could use a hunter for this.\r\n===Powers===\r\nEvery so often, Majordomo will give his helpers a shield. The shields last for 10 seconds and either have a 50% chance of reflecting magic attacks, or can reflect up to 100 melee damage when hit. Keep an eye on raid chat for these.\r\n===Killing the adds===\r\nThe order of the kills is important to new guilds trying this encounter, and less so to those who have done this enough times to allow some small errors.\r\nFollow the Leader\r\nFor new guilds, the most forgiving method is to kill one Elite, then the four Healers, then the other Elites. This means that you won't have tanks switching targets mid-way through the fight, with the exception of the Leading Tank. It also frees up the Mages a little quicker, increasing the DPS.\r\nAssign one Tank to Majordomo. 4 Tanks to the Elites. 4 Mages to the Healers. One of the Tanks on the Elites is the Leading Tank. His Elite is killed first. He then chooses a sheep, and starts to tank it. Everyone follows him, and kills it. Then he chooses another sheep, and so on, until all of them are down.\r\nOnce the Healers are down, the Leading Tank makes his way to the nearest Elite, and the raid kills that. Repeat until all adds are down.\r\n===Materials===\r\nThis battle is a test of the mana efficiency of the healers, who should bring as many [[Major Mana Potion]]s as possible. Other raid members should be liberal in their use of fire and shadow protection potions, healing potions, and bandages.\r\n===Alternate Strat===\r\nAnother way to do this is instead sheep all 4 priests, kill 3 elites, then kill the last elite and 1 priest at the same time. Then proceed to kill the priests with the original tanks on the priests. This strategy frees the tank groups from excessive healing and allows more DPS to flow on the adds. Healers can keep DPS up, Tank warriors can DPS, etc.\r\n===Another Strategy===\r\nPolymorph the healers as normal, then kill two elites, then one healer. This leave you with 3 polymorphable healers and 2 elites left. DPS an Elite down to 10-15%, then switch DPS to the other Elite and kill it, then the other damaged Elite in quick succession. This allows the raid to not have to deal with 4 targets at once when the Healers become immune to the polymorph and makes things a little bit easier but is a bit tricky to implement.\r\n===And another strategy===\r\nPolymorph the healers, kill two elites, bring the other two elites to 30% health. Break a sheep and kill that healer. Break the next sheep and kill that healer. Assist train the two elites that were brought down to 30% earlier, then kill the remaining healers. The idea here is similar to the strategy outlined above, but is meant to limit the amount of time the raid must deal with 4 targets up by making the 2 elites left alive quick kills after the healers become immune to polymorph.\r\n==Reward==\r\nMajordomo Executus himself does not drop loot as he in fact does not die. He instead offers access to the [[Cache of the Firelord]].\r\nReputation: Does not provide reputation gains with the [[Hydraxian Waterlords]].\r\n==Notes==\r\n* Majordomo must be defeated before you can fight [[Ragnaros]]\r\n* See other Molten Core [[Molten_Core|Bosses]].",},
			["Major Dreamless Sleep Potion"] = { content = "'''Major Dreamless Sleep Potion''' is a [[potion]] that puts the consumer to sleep to restore health and mana. Useful in a fight when unable to escape combat and not being hit.\r\n==Source==\r\nThis potion is made by [[Alchemy|Alchemists]] with a skill level of 350.\r\nThe components are:\r\n* 1 Dreaming Glory\r\n* 1 Nightmare Vine\r\n* 1 Imbued Vial\r\nThe recipe is taught by Recipe: Major Dreamless Sleep Potion. \r\n==Notes==\r\n*The effect cast to make you sleep can't be canceled but it can be dispelled. \r\n*If it is dispelled you don't get the full effect of the potion.\r\n*Use a Dreamless Sleep Potion on [[Blackheart the Inciter]] right as he yells \"Time for fun!\".\r\n*Use this in [[Karazhan]] on [[Netherspite]] during the banish phase!\r\n*Use this in [[Serpentshrine Cavern]] on [[Morogrim Tidewalker]] when you need it and he calls for murlocs (you have to be out of Morgrims range). It's dangerous to heal during this moment anyway!\r\n*Use this in [[Gruul's Lair]] when he ground slams- if you take it in the air, you shatter away from everyone! More importantly no one will shatter near you (unless they drink one as well, and you're ''really'' unlucky...)\r\n*There are 3 varieties: [[Dreamless Sleep Potion]], [[Greater Dreamless Sleep Potion]], and [[Major Dreamless Sleep Potion]].",},
			["Major Fire Protection Potion"] = { content = "'''Major Fire Protection Potion''' is a consumable that protects the player from Fire attacks and all spells that have Fire damage.\r\n==Source==\r\nMajor Fire Protection Potion is created by [[Alchemy|Alchemists]] with a skill level of 360.\r\nThe components are:\r\n*1 x Primal Fire\r\n*3 x Mana Thistle\r\n*5 x Imbued Vial\r\nNote that this recipe creates 5 Major Fire Protection potions at a time.\r\nThe Recipe: Major Fire Protection Potion is [[Bind on Pickup|BoP]] dropped by [[Sunseeker Astromage]]s in [[The Mechanar]].",},
			["Major glyph"] = { content = "#REDIRECT [[Glyph]]", redirect = "Glyph",},
			["Major Healing Draught"] = { content = "==Source==\r\nThis item is a PvP reward, and can be purchased for h=2 gold from:\r\n* Gaelden Hammersmith in [[Alterac Valley]]\r\n* Thanthaldis Snowgleam in [[Hillsbrad Foothills]]\r\n* Grunnda Wolfheart in [[Alterac Valley]]\r\n* Jekyll Flandring in [[Hillsbrad Foothills]]\r\n* Illiyana Moonblaze in [[Ashenvale]]\r\n* Kelm Hargunth in [[The Barrens]]",},
			["Major Healing Potion"] = { content = "'''Major Healing Potion''' is a [[potion]] that restores 1050 to 1750 health.\r\n==Source==\r\nThis item can be crafted using [[Alchemy]] (275); taught by Recipe: Major Healing Potion before the Burning Crusade expansion, or trainable from Master Alchemist trainers in the Burning Crusade. \r\nThis item can be purchased for 40 silver copper from:\r\n* Lieutenant General Andorov in [[Silithus]]\r\n* Daga Ramba in [[Blade's Edge Mountains]]\r\n* Dealer Hazzin in [[Netherstorm]]\r\n* Dealer Sadaqat in [[Netherstorm]]\r\nThis item can be looted from most level 48-72 [[Humanoid]] monsters.\r\nThis item is a quest reward from the following quests:\r\n* Noggle's Last Hope\r\n* Deadwood Ritual Totem\r\n* Winterfall Ritual Totem\r\n* Bloodpetal Poison\r\n* Major Healing Potion\r\n* Major Healing Potion\r\n* Scouring the Desert\r\n* Scouring the Desert\r\n==Notes==\r\nThis potion shares the same 1 minute cooldown as all other healing and mana potions, provided the imbiber is out of combat.\r\nThe major healing potion has the same healing properties as volatile Healing Potion, but is more widely available and requires a slightly lower level to use.",},
			["Major Mana Draught"] = { content = "==Source==\r\nThis item is a PvP reward, and can be purchased for h=2 gold from:\r\n* Gaelden Hammersmith in [[Alterac Valley]]\r\n* Thanthaldis Snowgleam in [[Hillsbrad Foothills]]\r\n* Grunnda Wolfheart in [[Alterac Valley]]\r\n* Jekyll Flandring in [[Hillsbrad Foothills]]\r\n* Illiyana Moonblaze in [[Ashenvale]]\r\n* Kelm Hargunth in [[The Barrens]]",},
			["Major Mana Potion"] = { content = "'''Major Mana Potion''' is a [[potion]] that restores 1350 to 2250 mana. \r\n==Source==\r\nThe alchemy recipe to create the Major Mana Potion is a rare (6%) drop from [[Darkmaster Gandling]] in [[Scholomance]] and can be purchased from [[Magnus Frostwake]], a ghost in one of the buildings outside the entrance to Scholomance. Magnus is normally invisible, however; characters must complete the Scholomance quest chain \"Justice for the Sarkhoffs,\" which begins with Doctor Theolen Krastinov, the Butcher, to see him and purchase items from him.\r\nIt is crafted using [[Recipe: Major Mana Potion]] by alchemists with a skill level of 295.\r\n==Notes==\r\nThis potion shares the same 1 minute cooldown as all other healing and mana potions, provided the imbiber is out of combat.",},
			["Major Mattingly"] = { content = "'''Major Mattingly''' is a level 60 NPC located in [[the Valley of Heroes]] in the [[human]] city of [[Stormwind]].",},
			["Major Mills"] = { content = "'''Major Mills''' is a level 50 [[quest giver]] located on [[Theramore Isle]] in the [[contested]] territory of [[Dustwallow Marsh]].\r\nHe starts the quest Take Down Tethyr!.\r\nSee [[List of Dustwallow Marsh NPCs]].",},
			["Major Rejuvenation Potion"] = { content = "'''Major Rejuvenation Potion''' is a [[potion]] that restores 1440 to 1760 health and 1440 to 1760 mana.\r\n==Source==\r\nThis potion is made by [[Alchemy|Alchemist]] with a skill level of 300.\r\nThe components are:\r\n*1 [[Heart of the Wild]]\r\n*4 [[Golden Sansam]]s\r\n*4 [[Dreamfoil]]s\r\n*1 [[Imbued Vial]]\r\nThe [[recipe]] is a rare drop from bosses in the [[Molten Core]].\r\n==Notes==\r\nThis potion shares the same 1 minute cooldown as all other healing and mana potions, provided the imbiber is out of combat.",},
			["Major Shadow Protection Potion"] = { content = "==Source==\r\nThis item is crafted by [[Alchemy|Alchemists]] with a skill level of 360. It is learned from Recipe: Major Shadow Protection Potion.\r\n5 potions are created each time, hence the need for 5 vials. \r\nThe recipe for this potion drops from [[Shadow Council]] Warlocks in [[Legion Hold]], [[Shadowmoon Valley]]. It is [[bind on pickup]] and has an approximately 0.3% chance of dropping.",},
			["Mak'aru"] = { content = "'''Mak'aru''' is the capital of the [[makrura]] civilization. It is built on the ocean floor directly beneath the eye of the [[Maelstrom]]. [[Brann Bronzebeard]] describes it as composed of a seemingly organic material, possibly grown out of coral.\r\nThe makrura despise the [[Naga]] of [[Nazjatar]] and are forever at war with them.",},
			["Makaba Flathoof"] = { content = "'''Makaba Flathoof''' is a level 25 [[quest giver]] located west of [[Honor's Stand]] close to the entrance to [[Stonetalon Mountains]], in the [[Horde]]-aligned territory of [[the Barrens]].\r\nHe starts the following quests:\r\n* Avenge My Village\r\n* Kill Grundig Darkcloud\r\n* Kaya's Alive\r\nSee [[List of the Barrens NPCs]].",},
			["Makazradon"] = { content = "'''Makazradon''' is one of two massive pit lords found at [[Legion Hold]] in [[Shadowmoon Valley]]. He and his companion, [[Morgroron]], wield weapons crafted with powerful anti-demon enchantments intended for use against [[Illidan]].\r\nThese demons and their weapons are the subjects of the quest Capture the Weapons.\r\nWarlocks are no longer able to enslave this demon as of Patch 2.3. \r\n==Loot==\r\n*Makazradon's Glaive",},
			["Maker's Terrace"] = { content = "'''The Maker's Terrace''' is a large excavation site located just outside the entrance to [[Uldaman]] in the [[Badlands]]. For most adventurers first venturing into the Badlands from [[Loch Modan]], it will be the first place they travel past. Exercise caution, as the Terrace is patrolled by elite [[Dark Iron Clan|Dark Iron Dwarves]].",},
			["Makil"] = { content = "'''Makil''' is a [[goblin]] [[tinker]]. He is a companion to [[Drann]].",},
			["Making Amends"] = { content = "==Objectives==\r\nYou must've done something really bad to us or our friends, <name>. At any rate, I'm here to offer you a way to get our good graces back.\r\nAs you know, [[Winterspring]] is quite cold. With so many of us goblins coming from other cities, we could use a hand keeping warm. Bring me some runecloth and coal and I'll put in the good word for ya. Be warned though, our enemies are not going to take kindly to your helping us. \r\n* Coal (4)\r\n* Runecloth (40)\r\n== Completion==\r\nThank you, <name>. You're on a quick path to redeeming yourself with our fair town. \r\n \r\n== Reputation Rebuilding ==\r\nIf you are at 0/36000 hated: \r\nYou will need to do 72 turn ins of 40 runecloth and 4 coal to reach: \"Hostile\" \r\nif you are at 0/3000 hostile: \r\nYou will need to do 6 turn ins of 40 runecloth and 4 coal to reach: \"Unfriendly\" \r\nIf you are at 0/3000 unfriendly: \r\nYou will need to do 6 turn ins of 40 runecloth and 4 coal to reach: \"Neutral\" \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*+500 [[Rep]] to [[Everlook]]\r\n*-500 [[Rep]] to [[Bloodsail Buccaneers]]",},
			["Making Money Guide"] = { content = "#REDIRECT [[Guide to making money]]", redirect = "Guide to making money",},
			["Making money with Alchemy"] = { content = "Alchemy, at least once you have reached a certain level of skill and acquired a few high-demand recipes, is a fairly good money-making venture (especially when combined with [[Herbalism]]).\r\nCompared to other production professions ([[Blacksmithing]], [[Enchanting]], [[Leatherworking]], [[Tailoring]]), goods you sell from Alchemy are, for the most part, consumable so your customers will keep coming back for more. Also, there isn't anything that requires farming ridiculous amounts of rare materials; even the highest-level recipes require only a few herbs per potion. Although some of the recipes are quite difficult or time-consuming to obtain, these recipes will become your premier money-makers.\r\nAs with any economy the main way to make money involves supply and demand. Be prepared to spend top price for rare recipes and spend hours grinding reputation with several factions. If you have [[Herbalism]] as well as Alchemy, be sure to check how much you can just sell the raw materials for. For the common recipes you can often make more selling the herbs than you could by turning them into potions!\r\nBefore making potions to sell, check prices and demand on your server. You should be able to make a profit from buying herbs from the Auction House and selling the finished product. If you cannot make a profit from doing this at higher alchemy levels, then you need to find better recipes.\r\n==High Demand Products==\r\nHealing and Mana potions are constantly in demand, although you'll find more buyers for the higher-level versions.\r\n===Stat-buffing Elixirs===\r\nEspecially the highest-level versions and the ones that buff multiple stats, such as [[Elixir|Elixirs of Strength]], [[Elixir|Elixirs of Intellect]], and [[Elixir|Elixirs of Major Agility]] are usually good sellers. [[Elixir|Elixirs of Damage]] boost spell damage, like [[Elixir of Major Frost Power]] or [[Elixir of Major Firepower]], and are also often in demand. Again, the higher-level versions will sell better, since higher-level characters have more disposable income.\r\n===PvP Potions===\r\nThere are a number of potions that PvP players will constantly need. These include: [[Free Action Potion]], [[Swiftness Potion]], [[Living Action Potion]], [[Greater Stoneshield Potion]], [[Purification Potion]], [[Invisibility Potion]], [[Limited Invulnerability Potion]], and [[Rage Potion]].\r\n===Quests and Professions===\r\nSome potions are needed for quests, or for other professions. [[Elixir of Defense]] are needed to make [[Toughened Leather Gloves]] (an excellent set of blue gloves); there is a quest that needs a [[Strong Troll's Blood Potion]]; [[Goblin Rocket Fuel]] is needed for a number of Engineering recipes; [[Ghost Dye]] is needed for a number of Tailoring recipes; [[Elixir of Shadow Power]] is needed for the Warlock epic mount quest. [[Swiftness Potion]], in addition to their PvP demand, can be used to make [[Swift Boots]] and [[Deadly Bronze Poniard]]. [[Shadow Oil]] and [[Frost Oil]] are also used in various recipes or weapon enchants. Transmutation is also quite valuable, especially high-end transmutes involving primals. The Thorium->Arcanite transmute (since it is needed for so many other professions' pre-TBC top items) is fairly useful, but not as it used to be. Prices have also gone down sharply after the 23 hour cooldown was removed in patch 2.4 (was 48 hours before TBC). Mithril->Truesilver can produce some decent (but not spectacular) returns from level 20 until level 35.\r\n===Raiding Potions===\r\nDepending on your server, the greatest possible profits may be in making potions that are useful for high-level characters running endgame instances -- For instance, in the past Greater Fire Protection Potions were in high demand for running Molten Core, and AQ content was driving up demand for Greater Nature Protection Potions. The outstanding buffs provided by the \"Flask\" recipes are also always in demand. With the newly updated requirements for resistance Flasks in some Outlands instances, and profession specializations, Flasks are quickly becoming the raid consumable of choice (their ability to persist through death is highly useful).\r\nIt should be noted that flasks can only be produced with an alchemy lab present. Such labs are found in [[Scholomance]], [[Blackwing Lair]], and [[Shattrath City]], although the last may only be used if you have the Burning Crusade expansion. Scholomance and Blackwing Lair require fighting in order to reach the labs, while the one in Shattrath City is in neutral territory.\r\n===Due to hard to get ingredients===\r\n[[Herbalism]] will allow you to gather most of the materials yourself. This works even at lower levels, there are a number of potions at the 225 skill level or below that are still useful to higher-level characters, but farming the ingredients for them is often a slow process, and a high-level character will gain little of value other than the herbs. [[Fishing]] can also be useful. Alchemy-related fish ([[Oily Blackmouth]], [[Firefin Snapper]], and especially [[Stonescale Eel]]) are very valuable relative to the time taken getting them.\r\nIf you have Herbalism profession, consider farming [[Grave Moss]]. It is one of the rarest herbs of the game, as it is found only in graveyards (and only at a few of the many in the game). Grave Moss is an ingredient for both [[Shadow Oil]] and [[Greater Shadow Protection Potion]]. The [[Kodo Graveyard]] in [[Desolace]] can be a good source for Grave Moss. Another valuable herb is [[Ghost Mushroom]]. This is the rarest of all herbs in Azeroth (not including those exclusive to instances)and is prized for its use as an ingredient in Invulnerability Potions.\r\nAt level 70, many of the best-selling potions and elixirs are those that require [[Ancient Lichen]] [[Node]]s of which are exclusively found in instances introduced in The Burning Crusade. [[Ironshield Potion]] and [[Elixir of Major Shadow Power]] both sell for high prices but require either running high level dungeons or farming the Ancient Lichen off various mobs, at a very low drop rate.\r\n===Due to hard to get recipes===\r\nThe potions made from recipes obtained from [[Zul'Gurub]]'s [[Zandalar Tribe]] reputation still sell for high prices on the AH.\r\n[[Flask]]s used to be a fantastic source of income for any alchemist lucky enough to have one or more recipes, mats (especially [[Black Lotus]]), and regular access to an [[Alchemy Lab]]. Since the release of [[The Burning Crusade]] and the availability of most flasks through [[reputation]] grinds, and later the relaxation of the discovery system, all three of these have become much less hard to find, and flasks have been reduced in power as well, reducing demand. However, they are still limited in supply on many [[realm]]s and remain popular for heroic instances and raids, so it is possible for a flask-making alchemist to find regular buyers.\r\n==Random Tips==\r\nKeep an eye out in the AH for any Alchemy recipes selling cheaply. This is less common than it used to be, but sometimes people will sell recipes for considerably less than their market value (since most of them have misleadingly low vendor sell values). *Most* lower-level recipes that are not trainable can be bought from a vendor in one of the cities (though some are limited supply, so you may have to camp the vendor for a while to get them). But others, like the [[Recipe: Swiftness Potion]], are random drops and are very difficult to find.\r\nAlso keep an eye out for anybody selling herbs for low prices. Buy low and sell high, or hang on to herbs for later recipes. \r\nMake as many transmutes as possible, even if you have to spend your last money on materials. It is easier to sell transmuted materials in stacks of 5 or more. Of course you can sell your transmutes only, but will not profit as much as by transmuting for yourself and then selling.",},
			["Making money with enchanting"] = { content = "In contrast to most other [[profession]]s, [[Enchanting]] offers two different methods to earn money. The first method is to buy items from the auction house, disenchant them and sell the resulting materials, while the second method is to actually sell enchantments. Very rarely it's also possible to sell the service of disenchanting for a small fee.\r\n==Making money through disenchanting==\r\nThis method follows the usual pattern for most professions, scan the AH and compare buy and sell prices. The general idea is to buy a magic item, disenchant it, and sell the resulting materials for a higher price than the items price. Example:\r\n The current AH price for Arcane Dust is 2.5g\r\n A green lvl 63 armor item is available for a buyout of 4g\r\n Disenchanting this item usually results in two Arcane Dust\r\n Therefore, a gain of 1g is possible by buying the item, and selling two dusts\r\nThis calculation can be done manually, but the mods or automate this, and include the current AH value of items in their disenchanted form in the tooltip.\r\nUnfortunately, on most servers, there are a lot of enchanters trying to make money using this approach, therefore the spread (between item price and disenchant value) is usually rather low. With time and commitment though it's possible to find bargains and/or a niche (like lower-level materials). This is basically the same with all items traded on the AH - supply and demand may fluctuate, a good feel for the market dynamic helps gaining profits.\r\nDisenchanting involves some randomness. Items generally do not disenchant into a fixed number of materials, rather there are probabilities involved. Particularly the chance that items may produce shards is interesting. Therefore, even when the split is small, it's possible to make a profit with these lucky disenchants. Some players who are not enchanters themselves like to keep all items they collect, and then have them disenchanted. This is not a source of substantial income though.\r\n==Making money through enchanting==\r\nSelling enchantments is possible, but rather difficult. First of all it suffers from the unique problem that buyer and seller must meet in person, it's impossible to sell or buy an enchant in the AH. This requires quite some commitment from the enchanter, standing in one of the major cities and repeatedly advertising in the trade channel. The second problem is that most enchants don't sell well. The low-level enchants are not good enough to be worth the effort, most players start enchanting their gear only after they hit the [[level cap]]. Even then, only the rare, top-of-the-line enchants can be sold with a profit. The problem with these receipes is that they are usually available only through running the harder [[instance]]s, which in turn usually requires membership of an endgame [[raid]]ing guild.\r\nIn summary, for players planning to be member of a raiding guild, enchanting is a good opportunity to get extra income. For solo or casual players though it's difficult to obtain the rare receipes, and thus hard to really earn money.\r\nWhen trying to sell enchants, there are a few rules which make life easier (for both, the enchanter and the customers):\r\n* Don't spam. Repeating an advertisment more frequently than once per minute is not helpful, once in 5 minutes actually suffices in most cases.\r\n* Make the advertisment short but informative. Don't try to include every enchant available, three of the top enchants is enough.\r\n* Include the information whether the price includes materials (\"my mats\"), or whether the customer has to provide them (\"your mats\").\r\n* The least invasive method is to sell the enchantments reactively, that is to wait until somebody asks for an enchant.\r\n* On Tuesdays, many players spend their newly awarded arena points for new gear. On weekends, more players overall are online. Both are good opportunities to sell enchants.\r\n===Popular enchantments needed by other players (subset)===\r\n+81 Healing on weapon: - All healers want this. \r\n+30 Healing on gloves: - All healers want this too \r\n+20 damage/healing on gloves: - Popular with DPS spellcasters\r\n+12 stamina on boots: - Drops in mana Tombs, popular with all classes and pretty rare\r\n+20 strength on gloves: - Most warriors want this. \r\n+6 stats on chest : - surprisingly popular all around\r\n===Tips===\r\n* The most cost-effective method of first leveling enchanting is to do nothing but disenchant items until skill level 60, which is when disenchanting no longer yields skill points. \r\n* As an early Journeyman enchanter, creating (vendors for around 15 silver) is rather cheap, and sometimes may even be sold for a slight profit.\r\n* Although it's a waste, there is no way to avoid spamming the same enchant on the same item over and over again if trying to level enchanting in a time-efficient way. Low-level enchants are in such low demand that they are frequently not even wanted for free.\r\n* It helps a lot to buy green items from friendly players (or guild mates) at the vendor price (or slightly more, or, if they're very friendly, for free).\r\n* Tailoring is often suggested as a secondary profession to enchanting because finding cloth does not require a secondary tradeskill, and this combination of crafts permits to convert the cloth found on mobs into enchanting materials. Looking at this strictly from a cash-flow point of view, taking a collecting craft like [[herbalism]], [[skinning]] or [[mining]] yields more profit, because selling all the collected resources plus cloth and buying cheap magic items from that money effectively yields more materials than the method using tailoring.\r\n* Prior to level 54, Artisan enchanting (300) and some later enchanting recipes can only be obtained in [[Uldaman]] from [[Annora]]. For higher-level characters, there's an enchanting trainer in [[Shattrath]].\r\n*In summary, enchanting is a rather expensive craft to learn, and difficult to level up in the early game. It is recommended for players in guilds, or for an alt with a higher-level main that can feed items to the enchanter.",},
			["Making money with engineering"] = { content = "==Services==\r\nServices are using an item to do a service in exchange for money\r\nLock Opening\r\n*Using Seaforium Charges you can open locked boxes. Just like a rogue usually you do it for free with a tip.\r\n==Amateur Items==\r\nAmateur [[item]]s do not require [[skill]] to [[use]] or [[equip]].\r\n'''[[Consumable]]s'''\r\n*Flame Deflector\r\n*Ice Deflector\r\n*Discombobulator Ray\r\n*Ez-Thro Dynamite\r\n*Ez-Thro Dynamite II\r\n'''[[Device]]s'''\r\n*Ornate Spyglass\r\n'''[[Equipment]]'''\r\n*Goblin Rocket Boots \r\n*Voice Amplification Modulator\r\n'''[[Small pet]]s'''\r\n*Mechanical Squirrel Box\r\n*Lifelike Mechanical Toad\r\n*Tranquil Mechanical Yeti\r\n==Hobbyist Items==\r\nHobbyist [[item]]s require a [[skill]] other than [[Engineer]]ing to [[use]] or [[equip]].\r\n'''[[Profession]]s'''\r\n*[[Alchemy]]: Recipe: Goblin Rocket Fuel\r\n*[[Blacksmithing]]: Plans: Inlaid Mithril Cylinder\r\n*[[Fishing]]: Aquadynamic Fish Attractor\r\n*[[Leatherworking]]: Salt Shaker\r\n'''[[Gun]]s'''\r\n*70 Gyro-balanced Khorium Destroyer\r\n*70 Ornate Khorium Rifle\r\n*70 Felsteel Boomstick\r\n*69 Adamantite Rifle\r\n*63 Fel Iron Musket\r\n*60 Core Marksman Rifle\r\n*56 Flawless Arcanite Rifle\r\n*50 Dark Iron Rifle\r\n*47 Thorium Rifle\r\n*39 Mithril Heavy-bore Rifle\r\n*36 Mithril Blunderbuss\r\n*24 Moonsight Rifle\r\n*21 Silver-plated Shotgun\r\n*19 Lovingly Crafted Boomstick\r\n*16 Deadly Blunderbuss\r\n* 5 Rough Boomstick\r\n'''[[Arrow]]s'''\r\n*52 Thorium Headed Arrow ''(+17.5 [[dps]])'' - Acquired by completing either of these [[quest]]s which require 1 [[stack]] of 200 Thorium Shells.\r\n**Arrows Are For Sissies (from [[Artilleryman Sheldonore]] in [[The Commons]], [[Ironforge]]; ''repeatable'')\r\n**A Fair Trade (from [[Bounty Hunter Kolark]] in [[Valley of Honor]], [[Orgrimmar]]; ''repeatable'')\r\n'''[[Bullet]]s'''\r\n*62 Adamantite Shells ''(+43 [[dps]], third best bullets besides the Timeless Shell and Mysterious Shell) Created via Adamantite Shell Machine''\r\n*57 Fel Iron Shells ''(+26 [[dps]])''\r\n*52 Thorium Shells ''(+17.5 [[dps]])''\r\n*44 Mithril Gyro-Shot ''(+15 [[dps]])''\r\n*37 Hi-Impact Mithril Slugs ''(+12.5 [[dps]])''\r\n*30 Crafted Solid Shot ''(+8.5 [[dps]])''\r\n*15 Crafted Heavy Shot ''(+4.5 [[dps]])''\r\n*5 Crafted Light Shot ''(+2 [[dps]])''\r\n'''[[Scope]]s'''\r\n*60 Stabilized Eternium Scope ''(+28 ranged [[critical strike|critical strike rating]])''\r\n*55 Khorium Scope ''(+12 ranged [[damage]])''\r\n*55 Adamantite Scope ''(+10 ranged [[damage]])''\r\n*50 Biznicks 247x128 Accurascope ''(+30 ranged [[hit|hit rating]])''\r\n*40 Sniper Scope ''(+7 ranged [[damage]])''\r\n*30 Deadly Scope ''(+5 ranged [[damage]])''\r\n*20 Accurate Scope ''(+3 ranged [[damage]])''\r\n*10 Standard Scope ''(+2 ranged [[damage]])''\r\n*5 Crude Scope ''(+1 ranged [[damage]])''\r\n==Enthusiast Items==\r\nEnthusiast [[item]]s are needed to complete a [[quest]].\r\nChasing A-Me 01\r\n*1 x Mithril Casing\r\nGizmo for Warug ''([[Magram Clan Centaur]])''\r\n*1 x Advanced Target Dummy\r\nGyro... What?\r\n*1 x Gyrochronatom\r\nThat's Asking A Lot\r\n*8 x Hi-Explosive Bomb\r\n*8 x Unstable Trigger\r\nLook To The Stars\r\n*1 x Bronze Tube\r\nThe Touch of Zanzil ''(Rogue only)''\r\n*1 x Bronze Tube\r\nWarsong Saw Blades\r\n*1 x Deadly Blunderbuss\r\n==Professional Items==\r\nProfessional [[item]]s are crafted by Specialist [[Engineer]]s that require [[Engineering]] [[skill]] (but not the same [[Engineering]] discipline) to [[use]] or [[equip]].\r\n[[Gnome Engineering]]\r\n*Gnomish Alarm-O-Bot\r\n*Gnomish Harm Prevention Belt\r\n*Gnomish Mind Control Cap\r\n*Gnomish Net-o-Matic Projector\r\n*Gnomish Rocket Boots\r\n*Gnomish Shrink Ray\r\n[[Goblin Engineering]]\r\n*Goblin Jumper Cables XL\r\n*Goblin Mortar\r\n*Goblin Rocket Helmet\r\n*Goblin Sapper Charge\r\n*The Big One",},
			["Making Repairs"] = { content = "==Objectives==\r\n[[Lurz]] at [[Blue Sky Logging Grounds]] wants you to collect 4 Grooved Cogs, 3 Notched Sprockets, and 2 High Tension Springs.\r\n* Grooved Cog (4)\r\n* Notched Sprocket (3)\r\n* High Tension Spring (2)\r\n==Description==\r\nTwenty shredders by noon tomorrow!\r\nWho makes these schedules, anyway? No one who ever put one of these garbage cans back together, that's who....\r\nIf I'm going to hit my quota, I'll need a hand. Help me out and I'll share my commission with you - fair enough?\r\nI need cogs, sprockets and springs. They're littered across the ground down by the shredders. \r\n==Rewards==\r\nYou will receive: 5 gold 60 silver \r\n==Progress==\r\nYa fetch those parts for me yet?\r\n==Completion==\r\n...\r\n==Notes==\r\nAccepting this quest will flag you for PvP as long as the quest is in your log.",},
			["Makrura"] = { content = "The '''Makrura''' are a race of [[humanoid]] lobsters (or more likely crayfish) from city of [[Mak'aru]] that live primarily in the sea, but are capable of surviving on land for short periods of time. They are most commonly found on the coastlines of [[Durotar]], [[The Barrens]], [[Desolace]], and [[Dustwallow Marsh]]. Some can also be found in the waters surrounding [[Sardor Isle]] in [[Feralas]] and around [[Temple of Arkkoran]] in [[Azshara]].\r\nThe term \"Makrura\" denotes the entire race.\r\nMakrura speak [[Nerglish]], and in fact they may have invented the language. They use a primitive but powerful form of magic that is related to the element of water. They are also incredibly hostile and will attempt to kill anybody that comes near them. They are often found underwater guarding shipwrecks.\r\n==Background==\r\nMakrura are aquatic creatures that superficially resemble enormous crayfish, and uneducated observers have mistakenly dubbed them “lobster men.” They sport strong pincers used solely for combat, as well as six small tentacles close to the head that can be used for finer manipulation. They walk on four small legs that extend out from under a flat, flippered tail and have two clawed arms they use for combat. Makrura are amphibious and dwell equally well on land or under water, although they prefer shallow tropical seas. Makrura fight by grappling an opponent with one pincer and holding it in place while the other pincer tears it apart. Makrura defend their territory aggressively, although they attack murlocs and naga on sight.\r\nMakrura are hardy creatures with exceptionally powerful pincers, but they are clumsy, their primitive society allows for little intellectual stimulation, and their strange mindset unnerves others.\r\n===Society===\r\nMakrura society is matriarchal. Male makrura mate only once and then molt into sexless drones (although they are still referred to as “he” for all practical purposes). Makrura appear scattered and tribal, but in reality they have a large capital city, Mak’aru, in the Eye, close to the naga capital of Nazjatar. Makrura are primitive, knowing little of advanced magic, craftsmanship, or technology. They use tools only to build their crude underwater dwellings and shellfish traps, or to break apart giant clams (their favorite food). Makrura decorate their hard carapaces with tribal markings and colors, but otherwise disdain clothing, armor, and other trappings of civilization.\r\nTheir carapaces come in many colors, including shades of red, blue, and black. Makrura, regardless of gender, are typically 12 feet long and weigh 500 pounds. Both appear identical to non-makrura observers unless a female is carrying a clutch of eggs on her torso. Females typically bear several hundred eggs at a time, maintaining them for several months until they hatch, but less than one fifth of these survive to maturity.\r\nMakrura have little or no access to advanced technologies, metalworking, or arcane magic. The vast majority of heroic makrura are barbarians. Scouts, warriors, and healers other than shaman and are uncommon, while arcanists and tinkers are virtually unknown. Makrura are gregarious by nature and fiercely protective of their fellow makrura and their communities. Occasionally, though, a wanderer sets\r\nout on his own, driven by a desire to explore and see new things.\r\n==Relations==\r\nMakrura suffer from the extreme disadvantage of being tasty to many carnivorous races, a fact appreciated all too well by their enemies on both land and sea. While land dwellers sometimes hunt them for food, a makrura’s most hated enemies are murlocs and naga (but especially the latter). Murlocs consider makrura a snack to be eaten raw, while naga maintain a wide variety of makrura recipes and sometimes raise the poor creatures from birth in special farms.\r\nMany of these individuals turn to the land, where the dangers posed by murlocs and naga are not as acute. Wandering makrura are rare, so much so that members of the Horde or Alliance don’t know what to make of them. If a makrura can speak an understandable tongue, he might be able to make his own way, but he is always treated with curiosity or outright wonder. In wilder areas, their resemblance to shellfish might cause a makrura to be mistaken for a walking seafood dinner.\r\n==Languages==\r\nMakrura speak Nerglish, a low aquatic tongue. Makrura sometimes learn the language of their hated enemies, to better combat them. Those makrura who deal with shore-dwellers may learn languages appropriate to trading and negotiations.\r\n==Tribes==\r\n*Coast Crawl, in [[Feralas]]\r\n*Drysnap, in [[Desolace]]\r\n*Arrkoran, in [[Azshara]]\r\n*Murkshallow, in [[Blackfathom Deeps]]\r\n*Muckshell, in [[Dustwallow Marsh]]\r\n*Makrinni, in [[Azshara]]\r\n*Slimeshell, in [[The Barrens]]\r\n==Lobstrok?==\r\nA texture model exists within the World of Warcraft file structure that depicts a [[Lobstrok]], a creature similar to a Makrura. This creature does not exist in-game and may be the original name that was changed in favor of \"Makrura\" — or it may also be a boss, tribe, or tribal leader that will appear in the future. Outland makrura are called 'Bogstrok'.",},
			["Maktu's Revenge"] = { content = "==Objectives==\r\nLocate and kill [[Mragesh]], then return to [[Maktu]] at the [[Orebor Harborage]].\r\n==Description==\r\nLast time Maktu was out hunting hydras for hides at [[Serpent Lake]], he was attacked by the biggest [[hydra]] he's ever seen. Maktu reached for his spear, but it was too late. He had just enough time to escape becoming hydra food.\r\nWho knows? Maybe next time, Maktu not be so lucky. Maktu wants to be there so there won't be a next time. Will you help Maktu get his revenge on Mragesh?",},
			["Maktu"] = { content = "'''Maktu''' is a level 64 [[armor]] [[vendor]] located at [[Orebor Harborage]] in the [[contested]] territory of [[Zangarmarsh]].\r\nHe starts the following quests:\r\n* Natural Armor\r\n** Maktu's Revenge\r\nHe always refers himself in third person.\r\nRequires Neutral reputation with the Kurunai before he will speak to you.\r\nSee [[List of Zangarmarsh NPCs]].",},
			["Mal'Ganis"] = { content = "'''Mal'Ganis''' (or '''Mal'ganis''') was one of the [[nathrezim]] sent by [[Archimonde]] as a jailor of the [[Lich King]]. He was chosen to head up the plot to turn Prince [[Arthas Menethil]] to darkness, and make him the Lich King's greatest champion, before being betrayed and \"killed\" by the death knight. During the [[war against the Lich King]], he led the [[Scarlet Onslaught]] under the guise of [[Barean Westwind]], plotting to take revenge and overthrow the Lich King, but he had to flee after being discovered by [[adventurer]]s sent by the [[Knights of the Ebon Blade]].\r\nMal'Ganis only reappeared years later during the [[third invasion of the Burning Legion]], before making his return in the [[Shadowlands]] where he revealed to be an agent in the service of [[Sire Denathrius]]. He infiltrated [[Revendreth]], but was captured by the [[Adventurer|Maw Walker]] and the [[Venthyr]], and revealed that it was a diversion to save his master. He later managed to escape his prison, promising that he would take revenge on the Maw Walker and that he would be by the Jailer's side for their next confrontation.\r\n===The breaking of Ner'zhul===\r\nAt [[Kil'jaeden]]'s command a group of dreadlords consisting of Mal'Ganis, [[Tichondrius]], [[Balnazzar]], [[Detheroc]], and [[Varimathras]] tortured the [[orc]] [[shaman]] [[Ner'zhul]] after he had escaped from [[Draenor]] to the [[Twisting Nether]]. Eventually, Ner'zhul, his sanity cracking, would agree to serve Kil'jaeden. Kil'jaeden passed the orc's spirit through death and revived as a [[Lich King|spectral entity]]. The dreadlords bound his disembodied spirit to a specifically crafted set of armor and a mighty [[runeblade]] called [[Frostmourne]]. These items were locked in a diamond-hard block of ice to imprison Ner'zhul. The Lich King and the dreadlords who had tortured him were then sent to Azeroth in order to weaken any resistance that the [[Burning Legion]] would in face during the [[Third War]]. While the Lich King gathered his strength, Mal'Ganis and his fellow dreadlords would serve as jailors and executors meant to hasten the Lich King's task by any means necessary. To this end, they would construct the [[Icecrown Citadel]] within [[Northrend]]. Though seemingly broken by the dreadlords, Ner'zhul sought vengeance and was able to play on the dreadlord's fears of Kil'jaeden in order trick them into allowing him to hurl Frostmourne out of the [[Frozen Throne]].\r\n===The Third War===\r\nAs Arthas and [[Jaina Proudmoore]] were investigating rumors of plague, they were attacked again and again by the forces of the Scourge posing as the personal army of the dreadlord Mal'Ganis. [[Kel'Thuzad]] helped play the part by telling Arthas that it was Mal'Ganis himself and not the Lich King behind the plague. Each attack, each town destroyed hit at Arthas' weakness, his pride. Arthas began to take his inability to protect his people from the [[Scourge]] personally, and soon became obsessed with killing the dreadlord.\r\nMal'Ganis led Arthas to [[Stratholme]], and left him with the choice of either slaughtering all of its inhabitants or watching them fall to the [[Plague of Undeath|plague]]. Arthas chose to kill his own subjects rather than let them become slaves to Mal'Ganis in death, killing most of the inhabitants of the town. Mal'Ganis was there in the wreckage, and goaded Arthas once again to come to [[Northrend]] to finish their battle. As expected, Arthas took the royal fleet and sailed north. The Prince's obsession with the hated dreadlord led him further down the path of evil, first lying to his men, betraying his mercenaries, and finally forsaking his own soul to take up the runeblade [[Frostmourne]], grievously wounding [[Muradin Bronzebeard]] in the process.\r\nThe moment Arthas took up Frostmourne he became a tool of the Lich King, completely subservient to his will. This was what Mal'Ganis had planned all along. Confidently he approached Arthas and informed him of his fate. However, the manipulative and traitorous dreadlord was himself betrayed, as the Lich King's first whispers to Arthas were that the time for his vengeance had come (this was the first step towards [[Ner'zhul]]'s independence). Arthas defeated the dreadlord, and both Arthas and the Lich King believed him to be slain. However, the dreadlords had ensured they would be shielded from the power of Frostmourne when they created it. The sword was incapable of consuming Mal'Ganis's soul, which instead returned to the Twisting Nether where he would be reborn in a new body.\r\n====Culling of Stratholme====\r\nMal'Ganis is the final [[boss]] in [[Culling of Stratholme (instance)|the Stratholme of the past]], the fourth wing of the [[Caverns of Time]] that opened with the release of ''[[World of Warcraft: Wrath of the Lich King]]''. In the ''Warcraft III'' scenario [[The Culling (WC3 Human)|The Culling]], Mal'Ganis would always resurrect after a certain period and return to continue his corruption of the [[city]]. In the [[instance]], however, once Mal'ganis is taken to 1% health, he teleports out of the city after telling Arthas to meet him in Northrend.\r\n====Surprise encounter====\r\nMal'Ganis returned under the guise of [[Barean Westwind]] and has taken over control of the [[Scarlet Onslaught]], much like [[Balnazzar]] had done with the original [[Scarlet Crusade]]. He stood in seclusion in [[Onslaught Harbor]] until agents from the [[Knights of the Ebon Blade]] [[The Admiral Revealed|forced him to show his true identity]] and flee back to his homeworld. He claimed to be plotting his revenge against the traitorous [[Lich King]], but this never came to fruition.\r\n====Sylvanas====\r\nIn the aftermath of the defeat of the Legion, Mal'Ganis secretly met with [[Sylvanas Windrunner]] within the [[Undercity]] after the Dark Lady agreed to join [[Zovaal]]. During this meeting, Mal'Ganis informed Sylvanas of the particulars of the Jailer's plans, of how the [[Arbiter]] had been shut off by the death of [[Argus (titan)|Argus]] and that the flow of all souls were being funneled into the [[Maw]]. He then revealed that Zovaal merely asks that Sylvanas does what she does best: kill. That she unleash death upon Azeroth on a scale never before witnessed. He further stressed how every soul sent screaming into the Maw, would empower the Banished One, when the time was right [[Sire Denathrius]] shall unleash the torrent of [[anima]] that he has been hiding within [[Revendreth]], and how in the aftermath Zovaal would gain access to the [[Sepulcher of the First Ones]] and remake reality itself. When Sylvanas questioned as what Mal'Ganis gained from allying with Zovaal, the nathrezim remarked that when the Jailer succeeded in making reality anew that all who served faithfully would be rewarded. Having no desire to spend more time in his presence, Sylvanas instructed Mal'Ganis to tell Zovaal that she would do everything she could to manifest their plan with all speed. He then subsequently departed from the Undercity.\r\n====Shadowlands====\r\nHaving infiltrated [[Renathal]]'s inner circle, Mal'Ganis was eventually exposed as the [[Adventurer|Maw Walker]], [[Kael'thas Sunstrider]], [[Lady Vashj]], and [[The Stonewright]] sought to recover the [[Medallion of Wrath]] from [[Nal'ragas]]. Having claimed the medallion himself, Mal'Ganis and his allies attempted to hide as [[Suspicious Dredger]]s before being exposed. After being beaten and captured, he rejected Renathal's request to repent and join the [[Venthyr]], and further revealed that while Renathal and his allies had focused on the medallion, his fellow nathrezim were able to acquire [[Remornia]], and thus free [[Denathrius]] from his imprisonment. Mal'Ganis then boasted that they had the Master's bidding in secret for years, of how [[Burning Legion|The Legion]], [[The Scourge]], [[Argus]] were all pawns in a game beyond their grasp, and declared that the medallion and Revendreth was dust in the face of the Sire's true plans.\r\nAfter being imprisoned within [[Dominance Keep]], Mal'Ganis attempted to sway the Maw Walker into freeing him by claiming that it would grant them untold power. However, under the advice of [[Lady Moonberry]], the Maw Walker revealed how easy it was to acquire the keys to his prison to his guards. In the aftermath, Mal'Ganis warned that the Maw Walker would regret this betrayal soon enough.\r\nHaving escaped through unknown means, Mal'Ganis sent a projection of himself to the Maw Walker within [[Korthia]]. Though promising that the Maw Walker would pay for crossing him, Mal'Ganis departed claiming that other matters demanded his attention more. In the aftermath the Maw Walker was certain when the Jailer was finally confronted, Mal'Ganis would be by his side.\r\n=====Eternity's End=====\r\nAfter the covenant forces arrived to [[Zereth Mortis]], Mal'Ganis took advantage of high trust shown to the Maw Walker by disguising himself as them, sabotaged defenses, and positioned the covenant forces where they would be of little help. However, Bolvar was to quick to realize that something amiss, and the Maw Walker would later personally confront Mal'Ganis. As the pair came to blows, the Maw Walker was soon joined by [[Baine Bloodhoof]] and [[Jaina Proudmoore]]. Finding it a pity that Jaina hadn't arrived sooner, Mal'Ganis claimed that he had stalled long enough for Zovaal's 'champion' and quickly departed.\r\nMal'Ganis, alongside [[Kin'tessa]], were later [[Lords of Dread|confronted]] within the [[Sepulcher of the First Ones]].\r\n==Quests==\r\n*[[Mal'appropriated]] \r\n==Objective of==\r\n*[[The Nathrezim]]\r\n==In Hearthstone==\r\nMal'Ganis appears as for the warlock class in the ''[[Hearthstone: Goblins vs Gnomes|Goblins vs Gnomes]]'' expansion for ''[[Hearthstone (game)|Hearthstone]]''. His flavor text reads: ''\"Mal'Ganis doesn't like being betrayed, so if you discard him, watch out.\"''\r\nHis card art was originally created to depict [[Varimathras]] in the [[World of Warcraft Trading Card Game|TCG]].\r\n==In Heroes of the Storm==\r\nMal'Ganis is a in ''[[Heroes of the Storm]]''.\r\n==Notes and trivia==\r\n*The name of Mal'Ganis comes from a space vampire lord in [[Blizzard Entertainment|Blizzard]]'s canceled game \"Bloodlines\" named \"Mal Ganis.\" According to [[Chris Metzen]], the name was later lifted for use in ''Warcraft''.\r\n*Though plotting his revenge upon the Lich King, developers hinted that he would have no role in [[Icecrown Citadel (instance)|Icecrown Citadel]]. This eventually proved true. Mal'Ganis is nowhere to be found within Icecrown Citadel.\r\n*During the [[Purge of Dalaran]], [[Archmage Lan'dalock]] summoned images of various Wrath of the Lich King era bosses, Mal'Ganis among them, to fight for him against the [[Horde]].\r\n*In a manga [[Nightmares]], [[Jaina]] was dreaming about traveling with Arthas to Northrend. There, they defeated the dreadlord and then found [[Frostmourne Cavern]] and Frostmourne in it. As Arthas was about to approach the blade, Mal'Ganis reappeared and attacked him, almost overwhelming him. In hoping to rescue Arthas, Jaina took the blade and slew the dreadlord, damning her own soul and eventuality becoming the Lich Queen.\r\n*In [[Frostmourne (Warcraft III)|the final level]] of [[The Scourge of Lordaeron]] in ''Warcraft III: Reign of Chaos'', using the given base and units it is possible to invade and destroy Mal'Ganis' base, but if Mal'Ganis is killed before Arthas returns with Frostmourne, Mal'Ganis will die, drop 2-3 [[Ankh of Reincarnation]], and come back to life. This can be repeated numerous times and when he does finally stay down (you will see the death animation when he finally dies), Ankhs will continuously spawn from where he died.\r\n*In the ''Warcraft III'' campaigns, dreadlord characters were given different colors out of concern that players wouldn't be able to tell them apart.\r\n*Mal'Ganis is voiced by [[Christopher Corey Smith]] in ''[[World of Warcraft: Wrath of the Lich King]]'' and Michael Gough in ''[[Heroes of the Storm]]''.\r\n*An suggests that he was at some point intended to appear during [[World of Warcraft|vanilla]] as a boss named '''Dreadlord Malganis''' <Overfiend>.\r\n==See also==\r\n*[[The Dreadlord's Deceit]]\r\n*[[Mal'Ganis (Reign of Fire)]], TCG card",},
			["Mal'Ganis (tactics)"] = { content = "'''Mal'Ganis''' is the last boss of [[Culling of Stratholme]].\r\n==Attacks and abilities==\r\n*Carrion Swarm: A cresting wave of chaotic magic splashes over enemies in front of the caster, dealing 3230 to 3570 Shadow damage and 380 to 420 Shadow damage every 3 sec. for 15 sec. \r\n*Sleep: Puts an enemy to sleep for up to 10 sec. Any damage caused will awaken the target. \r\n*[[Mind Blast]]: Inflicts 4163 to 4837 Shadow damage to an enemy. \r\n*Vampiric Touch: Heals the caster for half the damage dealt by a melee attack\r\n==Strategies==\r\nMal'Ganis will spawn when the party enters Crusader Square at the end of the instance. Arthas will aid the party in the encounter, but does not tank the boss and does not do any special abilities. He is like Anertheron, with a AoE spell and a Sleep spell. The party should position themselves behind him and as spread out as possible to avoid taking too much damage from this when he targets any given player. Sleep should be dispelled all the time. If not, it is also possible to use PvP trinkets other similar methods like [[Ice Block]]\r\nAlso, his Vampiric Touch buff can be dispelled and should be as soon as possible. \r\nWhen Mal'Ganis reaches below 10% health, he escapes, breaking combat and disappears after a little speech. The loot from the encounter is from a chest left behind.\r\nIf the party wipes, Mal'Ganis despawns. Speak to Arthas to restart the encounter. \r\n==Quotes==\r\nIntro:\r\n*''Yes, this is the beginning. I've been waiting for you, young prince. I am Mal'Ganis.''\r\n*''As you can see, your people are now mine. I will now turn this city, household by household, until the flame of life has been snuffed out forever.''\r\nAggro:\r\n*''This will be a fine test, [[Prince Arthas]].'''\r\nSleep:\r\n*''Time out.''\r\n*''You seem tired.''\r\nUpon slaying a player:\r\n*''All too easy.''\r\n*''The dark lord is displeased with your interference.''\r\n*''It is Prince Arthas I want, not you.''\r\nOutro:\r\n*''Your journey has just begun, young prince. Gather your forces, and meet me in the arctic land of [[Northrend]]. It is there we shall settle the score between us. It is there that your true destiny will unfold.''",},
			["Malachite"] = { content = "'''Malachite''' is a [[mineral]].\r\n==Source==\r\nMalachite is a mineral that [[miner]]s can extract from [[Copper Vein]]s. However, the chances of actually getting it by mining copper is approx 1%.\r\nOther potential sources include [[mob]] [[drop]]s, [[prospecting]] on [[Copper Ore]], and [[Chest (container)|chest]]s.\r\n==Malachite as an Ingredient==\r\nMalachite is used in the following recipes:\r\n===[[Blacksmithing]]===\r\n*Copper Battle Axe\r\n*Copper Chain Vest\r\n*Gemmed Copper Gauntlets\r\n===[[Engineering]]===\r\n*Crude Scope\r\n*Deepdive Helmet\r\n*Gnomish Universal Remote\r\n*Mechanical Squirrel Box\r\n===[[Jewelcrafting]]===\r\n*Bronze Band of Force\r\n*Inlaid Malachite Ring\r\n*Malachite Pendant",},
			["Malacrass"] = { content = "#REDIRECT [[Hex Lord Malacrass]]", redirect = "Hex Lord Malacrass",},
			["Malagav the Tactician"] = { content = "'''Malagav the Tactician''' was the leader of the tauren of the [[Might of Kalimdor]] - the army raised by both the Horde and the Alliance in opposition to the growing threat from [[Ahn'Qiraj]]. He was present in World of Warcraft until the ringing of the Scarab Gong by the holder of the [[Scepter of the Shifting Sands]] (which, as of September 2007, the majority of servers have done).",},
			["Malaka'jin"] = { content = "'''Malaka'Jin''' is a small [[Horde]] village in the [[Stonetalon Mountains]](71.94), just south of the [[Grimtotem Post]]. It houses a small community of [[troll]] hunters, who make a modest income by selling their catches to passing Horde adventurers. The trolls of Malaka'Jin are also mounting covert attacks against the [[night elves]] of [[Stonetalon Peak]], lead by the efforts of the [[Witch Doctor Jin'Zil]]. Inside this troll encampment, night elves are being held by the shaman Jin'Zil. He seeks ingredients for his voodoo potions. However, there aren't enough trolls here to be a great threat to the elves. [[Brann Bronzebeard]] once picked off a good number of the trolls here before they noticed him. He felt good for protecting the night elves, but since they weren't much of a threat, he didn't put more effort into killing them.",},
			["Malchezaar"] = { content = "#redirect [[Prince Malchezaar]]", redirect = "Prince Malchezaar",},
			["Malcomb Wynn"] = { content = "'''Malcomb Wynn''' is a level 23 npc located in [[the Apothecarium]] in the [[forsaken]]'s [[Undercity]].",},
			["Malden's Orchard"] = { content = "'''Malden's Orchard''' is a small orchard in northern [[Silverpine Forest]]. The trees in the orchard are dark and evergreen, but their fruits have not been picked in years. The orchard is named for its former owner, who was forced to flee his home when the [[Scourge]] invaded [[Lordaeron]]. \r\nRecently, large numbers of black [[worg]]s have taken up residence around the orchard and its single small cottage. When the [[Deathstalker]]s [[Rane Yorick]], [[Quinn Yorick]], and [[Deathstalker Erland|Erland McKree]] were conducting their reconnaissance mission, Erland was tasked with exploring Malden's Orchard. When he arrived he encountered the numerous worgs and was forced to take refuge within the abandoned cottage. He was pinned down for several days until with the aid of forsaken agents, he managed to make his escape and flee back to his partners at the [[Ivar Patch]] to the southwest.",},
			["Malediction"] = { content = "'''Maledition''' is a [[Warlock Talents|warlock talent]] that increases the damage bonus of your Curse of the Elements debuff.",},
			["Malefic Raiment"] = { content = "'''Malefic Raiment''' is the [[Tier 6]] set for Warlocks.\r\n==Notes==\r\nThe wing animation is tied to the head piece, and randomly appears once every few minutes. It appears at different times on each client. It does not allow you to fly.\r\nSee also: [[Set look alikes]]",},
			["Maleki the Pallid"] = { content = "[[Mini-boss]] of [[Stratholme]]. Maleki is a mortal [[human]] and the leader of the [[Thuzadin]], a sect of the Cult of the Damned named after [[Kel'Thuzad]]. He is adept at Frost and Shadow magic.\r\n==Attacks and abilities==\r\n*[[Frost Bolt]]\r\n*[[Frost Nova]]\r\n*[[Drain Life]]\r\n*[[Drain Mana]]\r\n*Ice Tomb, stuns a target for 8 sec.\r\n==Strategies==\r\nMaleki the Pallid is the easiest of the three [[Ziggurat]] bosses. He's a caster, so he dies pretty quickly. He’ll cast Frost Bolt and Frost Nova throughout the fight, but neither are very powerful. He casts a very nasty life drain at the primary aggro target on occasion though, this needs to be healed through or interrupted. The aim is to kill him and then destroy the Ash'ari crystal. (Thanks to",},
			["Malevolent Hatchling"] = { content = "'''Malevolent Hatchling''' is a level 64 bird released from [[Cursed Egg]]s in [[Veil Lithic]] of [[Terokkar Forest]].\r\n==Objective of==\r\nNeed to be killed for the quest Veil Lithic: Preemptive Strike.",},
			["Malevus the Mad"] = { content = "==Info==\r\nMalevus the Mad appears to be a [[Blood Elf]] [[Paladin]]. She is one of the random prisoners that was trapped in a [[Ethereum Prison]] and drops an [[Ethereum Prisoner I.D. Tag]]. She is the weakest hostile being that you can get from opening an Ethereum Prison, having the least health, and no abilities. She is immune to stun.",},
			["Male Kaliri Hatchling"] = { content = "'''Male Kaliri Hatchling''' can be found in [[Hellfire Peninsula]] .\r\nWhen '''Male Kaliri Hatchling''' is tamed by a [[hunter]] it teaches [[Claw]] Rank 8. Claw Rank 8 will requires 25 points to train your other pets.\r\n==Drops == \r\n \r\n0.05% Chance of a [[rare]] drop.\r\n0.84% Chance of an [[Uncommon]] drop.\r\n0.01% Chance of a [[common]] drop.\r\n0.29% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Malfas"] = { content = "'''Malfas''' can be found in [[Shattrath City]] .",},
			["Malfurion's Barrow Den"] = { content = "#REDIRECT [[Stormrage Barrow Dens]]", redirect = "Stormrage Barrow Dens",},
			["Malfurion"] = { content = "#REDIRECT [[Malfurion Stormrage]]", redirect = "Malfurion Stormrage",},
			["Malfurion Stormrage"] = { content = "'''Malfurion Stormrage''' is the greatest [[druid (lore)|Archdruid]] ever to live, and one of the most powerful beings in the Warcraft Universe. In World of Warcraft, during a once per server event, he can be found as a level ?? [[quest giver]] located on the shores of [[Lake Elune'ara]] in the [[contested]] territory of [[Moonglade]].\r\nHe starts the quest Eranikus, Tyrant of the Dream.\r\nSee [[List of Moonglade NPCs]].\r\n==Introduction==\r\nAmong the druids, Malfurion is the greatest, making him one of the most powerful beings in Azeroth. He is the twin brother of [[Illidan Stormrage]], and the beloved of [[Tyrande Whisperwind]]. Malfurion started the practice of [[druid]]ism among the night elves under the tutelage of the demigod [[Cenarius]]. Following the conclusion of the [[War of the Ancients]], he became the Archdruid of the night elves. He first appeared in ''[[Warcraft III]]: Reign of Chaos'' (\"Eternity's End\") and subsequently appeared in ''The Frozen Throne'' (\"Terror of the Tides\") and the ''War of the Ancients'' trilogy. Often he is called ''[[shan'do]]'', which means \"honored teacher\". However, some close friends occasionally tend to call him \"Furion\" or \"Mal\", the shortened versions of Malfurion.\r\n===Personality===\r\nMalfurion is the wise and peaceful leader of the night elf druids. He has a fatherly air about him, and takes great pleasure in guiding people to discover insights about themselves and the environment around them. He prefers not to solve problems directly for individuals, or to give completely thorough answers, but rather provide useful hints and advice so that others may achieve discovery on their own.\r\nHe is grateful to the orc and human armies for their assistance against the Burning Legion and welcomes visitors of those races with open arms. He also holds great respect for tauren and dwarves. However, Malfurion considers high elves and goblins extremely distasteful, and will expel them from Ashenvale whenever he encounters them. Horde and Alliance politics hold little interest for Malfurion as, in his mind, the needs of his people and their environment transcend what he considers to be petty rivalries between the other races.\r\nVisitors who display a proper respect for the natural environment and its inhabitants will be greeted warmly by Malfurion and his druids. They welcome outsiders for short periods of time with offers of shelter and sustenance. However, Ashenvale is the sacred home of the night elves,and Malfurion does not appreciate or tolerate prolonged visits by members of the other races. Emissaries and adventurers are occasionally welcome, but settlers and those who attempt to wrest profit from the land are expelled immediately.\r\n\"Stalwart,\" \"wise\" and \"righteous\" are the words that best describe Shan'do Stormrage. He is set in his path of safeguarding his beloved forests and the sanctity of life on Azeroth. Malfurion's burden is a hard one to shoulder; he must safeguard both the forests of Kalimdor and the Emerald Dream, a nearly impossible task. Malfurion must sometimes be reminded that others may help him shoulder the burden — Cenarius was his teacher and the other Druids and Ancients are more than willing to aid their Shan'do. The one thing Malfurion loves above nature and life is [[Tyrande]], his beloved — to live without her is not to live at all.\r\n===Combat===\r\nMalfurion calls on nature to aid him in battle. He relies on summoned creatures, treants, dryads, night elf warriors and other allies. He supports them with spells and acts as their general. If Malfurion is encountered alone, he usually uses his spells and abilities to escape into the forests and return later with help.\r\n===War of the Ancients===\r\nMalfurion was the most dedicated of [[Cenarius]]' disciples. In the ancient world before the [[Great Sundering]], Malfurion was a respected scholar loyal to his beloved [[Queen Azshara]]. He was among the first to notice the distance Azshara and her followers were keeping from their people, and he began to suspect that the powers granted by the [[Well of Eternity]] were not as pure as all had believed. Though he could not possibly fathom what was soon to come, Malfurion knew that the [[Kaldorei]] would be forever changed.\r\nAzshara and her [[Highborne]] were interested in the Well and ordered them to find as much as possible about the well. As time passed, the Highborne learned how to draw power from the Well and manipulate its energies. Finally, Azshara's reckless use of magic drew the attention of [[Sargeras]], Enemy of All Life and Lord of the [[Burning Legion]]. By opening a portal in Azshara's palace, Azshara's Highborne sorcerers, led by the High Lord Counselor [[Xavius]], let hordes of [[demon]]s into Kalimdor, including the Legion's commanders, [[Archimonde]], [[Mannoroth]] and [[Hakkar the Houndmaster]], and they ran rampant among the lands, striking down all who opposed them. The [[night elves]] desperately fought them back, but too many were falling to lend them aid. The Burning Legion was winning. The Highborne also managed to cast a bigger portal over the Well of Eternity to start the summoning of [[Sargeras]].\r\nBut from the ranks of the desperate Kaldorei rose Malfurion Stormrage. Convincing his twin brother, [[Illidan]], to forsake the use of magic, Malfurion and his love, [[Tyrande Whisperwind]], High Priestess of [[Elune]], quickly went to seek out the [[demigod]] Cenarius, in the hopes that he might have reprieve for their beleaguered people.\r\nEven with the help of Cenarius and [[Alexstrasza]] the [[Dragon Queen]], Malfurion knew that his people could not stand up to the constant barrage of demonic invaders. Believing the Well of Eternity to be their gateway, Malfurion decided that it must be destroyed. Knowing that its destruction would render them mortal and without any magic, the night elves reluctantly agreed to storm Azshara's stronghold and bring an end to the invasion.\r\nHowever, Illidan, spurred by his addiction to magic and his frustrated love for Tyrande, refused to give up his power, and left their resistance to warn the Highborne. Knowing that Illidan would quickly reach them, Malfurion attacked immediately to retain some surprise.\r\nAzshara and her Highborne were prepared for them, and her chaotic magics ripped Furion's forces to shreds. But it was the sight of Tyrande falling to the hands of Azshara's former Highborne, now transformed into [[satyr]]s that gave Malfurion the strength for one final strike.\r\nAzshara's battle with Malfurion threw the portal out of its magical alignment, and the vortex grew unstable. Malfurion cast a spell to create a gigantic gale that would rip all the demons from the ground and send them on a one-way trip into the Well and to the [[Twisting Nether]]. The Well of Eternity then started to collapse on itself, pulling land, Azshara's palace and the ruined city of [[Zin-Azshari]] into itself. Although Sargeras knew that the portal was closing, he tried to do the unthinkable - step into the portal to recreate it and enter Azeroth. The portal finally collapsed and trapped Sargeras in it. The Well of Eternity exploded in a catastrophic eruption that left the world sundered forever.\r\nHowever, Malfurion survived. Constructing crude rafts and sailing to what would become Kalimdor, Malfurion, Tyrande, and Cenarius agreed to lead their peoples to a new home. \r\nTo their horror, however, a lake atop [[Mount Hyjal]] had become fouled by the magical energies of the Well of Eternity, which they had hoped was gone forever. Illidan, who had sought to preserve the arcane magic he was addicted to, had taken seven vials of the Well's waters and poured three of them into the lake, creating a new Well of Eternity. Knowing that Illidan's addiction to magic would always be a threat to the safety of the world, Malfurion imprisoned his brother in the caverns below Hyjal; the [[Barrow Deeps]]. However, with the Sundering still fresh in their minds, Malfurion and the night elves dared not attempt to destroy the new Well.\r\nSeeking the counsel of the [[Aspect]]s, Malfurion requested the presence of [[Alexstrasza]], [[Ysera]], and [[Nozdormu]], returned from their hiding places, and they were shocked to hear of the new Well. All of them suspected that the Burning Legion would sniff out its energies once again and find [[Azeroth]] a second time.\r\nMalfurion agreed, and they all decided to safeguard this Well. To this end, they created the [[World Tree]], [[Nordrassil]], which they pledged to use to protect the Well of Eternity and the night elves themselves. Alexstrasza, the Life-Binder, grew the tree herself from an enchanted acorn of [[G'Hanir]]. Nozdormu, the Timeless, placed an enchantment upon the tree: for as long at it stood, the night elves would never die of old age or sickness. Ysera, the Dreamer, linked Nordrassil to the [[Emerald Dream]]. Through the tree, she would slowly rebuild the world. However, to maintain the Emerald Dream, she needed consciousnesses to roam its eternal pathways. To sustain it, all the druids agreed to sleep for centuries at a time, despite the years they would lose, and be linked to the Emerald Dream forever.\r\nMalfurion and Tyrande helped their people rebuild their society amongst the forests of [[Ashenvale]] surrounding Hyjal. Cenarius taught them the ways of the wood, and Malfurion grew considerably in power as he learned the art of the [[druid]], and he became a great Archdruid, first among his people.\r\nThough he dearly wished to remain with Tyrande, Malfurion and his druid kindred slept peacefully for many years until they were awakened by an attack by [[Dath'Remar]] and the Highborne survivors. He was quickly routed, but the druids refused to destroy them with so many lives already lost, so Malfurion decided that the Highborne were to be exiled. Dath’remar and his followers would later become the [[high elves]]. Though it pained his heart beyond belief, Malfurion left Tyrande to rejoin the Emerald Dream, settling into his long sleep in [[Furion's Barrow Den]] on the [[Moonglade]] Island.\r\n''At times, it is hinted that Malfurion and the other druids were asleep for all ten millenia between the War of the Ancients and the Third War, awakening only in times of great peril. However, most sources agree that there was a cycle, and that the druids would awaken every few centuries to interact with their wives, sisters, and daughters. This cycle could be easily interrupted if needed, but the druids must return to the Dream at the earliest opportunity.''\r\n===Eternity's End (10,000 years later)===\r\nAfter [[Tyrande]] battled through the three enchanted keepers of the grove: [[Lightning Protector]], [[Fire Protector]] and [[Ice Protector]] she reached the [[Horn of Cenarius]]. Malfurion was awakened to the sound of the [[Horn of Cenarius]]. He could sense the corruption and decay of his land, even in the Emerald Dream, and when he awoke, he summoned treants from the forest to dispose of the undead invaders who were closing on his [[Furion's Barrow Den]].\r\nTyrande, responsible for his awakening, told him that [[Archimonde]] had returned to [[Kalimdor]], and he had brought the Burning Legion with him. Malfurion immediately knew what the [[warlock]] was after; he would assail Mount Hyjal, and attempt to drain the mystical energies of Nordrassil. Their mission was clear: they had to awaken the druids and stop Archimonde.\r\nWhen Malfurion saw the outlander races battling the [[undead]], he thought that perhaps they would make good allies in the coming conflict. But Tyrande immediately rejected the idea, stating that they had killed Cenarius, and deserved whatever fate the undead had in store for them. \r\nThis savage nature became more prevalent as they attempted to awaken the [[Druids of the Talon]], sleeping in [[Druid of the Talon's Barrow Den]]s in [[Winterspring]]. Tyrande found a group of [[furbolg]]s, whom she had tried to help in Ashenvale, and who were now corrupted by the darkening shadow. Tyrande's forces killed them all. They fought their way through the undead, with orcs and humans fighting them at every turn, until they reached the Barrow-Dens, where Malfurion sounded the Horn of Cenarius. The Druids of the Talon awoke, and pledged to help Malfurion awaken the [[Druids of the Claw]] in the Barrow Deeps of Hyjal.\r\nUpon entering the mountainous caverns, Malfurion and [[Tyrande]] discovered gigantic spiders and other creatures, vastly mutated by the evil corruption, even within the sanctity of Hyjal. Soon, they came upon a doorway that led to the halls which held Furion's treacherous brother, Illidan. Despite Furion's protests, Tyrande entered the prison to free Illidan. Malfurion continued on, and found that the Druids of the Claw had forgotten themselves, and had embraced their feral bear forms as opposed to their night elven forms. The druids' minds were now identical to those of bears, making them impossible to reason with. But with the Horn of Cenarius, Malfurion broke them free of this state. Grateful to have their minds restored, the Druids of the Claw agreed to participate in the fight against the Legion.\r\nMeanwhile, Tyrande had released Illidan, hoping that he could also make a significant contribution in the war effort. Still, after all these years, Malfurion refused to trust Illidan for his betrayal. Illidan pointedly reminded Malfurion that they fought the demons together once, but Malfurion was adamant; he would have nothing to do with this.\r\nIllidan took a force of night elves into the corrupted forests of [[Felwood]], and began to battle [[Tichondrius]]. Tyrande and Malfurion immediately rushed to reinforce Illidan, but when they arrived, Illidan was already victorious, and in the form of a monstrous demon. Illidan had claimed the powers of the [[Skull of Gul'dan]] for his own in order to gain the power to slay Tichondrius. Malfurion and Tyrande both could not believe Illidan's dire choice, and Malfurion banished him from the forests forever. Illidan did not bother to argue with his brother, and left of his own accord.\r\nThat night, Malfurion received a vision. A great raven came to him and told him to bring Tyrande to the base of Mount Hyjal. Curious, he did as was instructed, and they met [[Jaina]] and [[Thrall]], the leaders of the outlander forces in Kalimdor.\r\nTyrande rebuked them and was about to battle them when suddenly, the raven appeared, and revealed himself to be [[Medivh]], the Last [[Guardian of Tirisfal]]. Medivh convinced the night elves to join forces with the outlanders in a last ditch effort to stop Archimonde's relentless assault towards the world tree. Tyrande reluctantly agreed.\r\nFrom \"The Sacrifice\" at Hyjal's summit, where the World Tree and the Well of Eternity rested, Malfurion formed a plan of attack. The defenders quickly built fortifications all the way up the mountain, and prepared for Archimonde's ascent. Malfurion knew what had to be done; in order for Archimonde to be defeated, he had to unleash the powers of the world tree upon the mighty demon lord.\r\nArchimonde, aided by three of his most powerful remaining lieutenants (the lich [[Rage Winterchill]], [[Azgalor]], successor of [[Mannoroth]], and [[Anetheron]], successor of [[Tichondrius]]) laid siege to Hyjal, ripping through Jaina and Thrall's bases. Finally, he came to Tyrande's last stronghold, and in turn, tore it to shreds, blew open the enchanted gates, and made his way to the World Tree. Tyrande and Malfurion watched as he approached, heedless of the Ancestral Guardians who had gathered during the battle, at the base of the World Tree. Archimonde's victory over the desperate defenders had made him overconfident, and he was completely unaware of the trap they had set for him.\r\nWhen Archimonde reached the Tree, Malfurion sounded the Horn of Cenarius. The thousands of Ancestral Guardians, roused by nature herself, stirred from the trees and attacked Archimonde, detonating in an explosion so large it unmade Archimonde and incinerated the forests atop Hyjal, shattering the world tree and ending the night elves' immortality.\r\n===Terror of the Tides===\r\nWhile checking on Nordrassil one day, Malfurion and Tyrande were unexpectedly met by a runner from [[Maiev]] the [[Warden]], pleading for assistance against Illidan. The former [[demon hunter]] had resurfaced and recruited a race of amphibious snake-people known as [[naga]] to aid him in his plans, which had come to include the [[The Broken Isles|attempted slaughter]] of Shadowsong and her troops. Malfurion immediately left with Tyrande to assist them.\r\nMalfurion brought [[mountain giant]]s with him to aid in the [[Balancing the Scales|battle]], and they battled through hordes of naga to reach Maiev. When they did, she was upset with Tyrande since the priestess had killed many of Maiev's [[Watcher]] guards when she freed Illidan. Malfurion stopped the argument between the two women before it got out of control and advised them to set aside their personal feud until Illidan was dealt with. They battled fiercely against the naga, until they finally confronted Illidan when he captured Tyrande. But he let her go with a warning not to go after him, and fled before they could apprehend him. They followed him across the sea, and landed on the shores of [[Lordaeron]].\r\nTroubled by the corruption of the forests, Malfurion retreated into the woods to commune with the forest spirits, but commanded Maiev and Tyrande to forget their differences for the time being in his absence during their search for Illidan.\r\nAs he went into the woods, Malfurion felt the pain of the earth, and was met by benevolent spirits of the forest who granted him a vision of [[Northrend]], which was crumbling apart due to Illidan's reckless magics with the [[Eye of Sargeras]]. Malfurion feared for the world and resolved to stop his brother.\r\nBut when he found Maiev, he could not see Tyrande. Maiev sadly reported that Tyrande had fallen in battle. Infuriated, Malfurion led his forces against Illidan's [[naga]], and with the help of Maiev and her new ally, [[Kael'thas]], they defeated Illidan's forces and captured him. Malfurion accused Illidan of causing Tyrande's death, but Kael chimed in, saying that it was premature to assume her dead, and that she had only been swept down a river. Realizing that he had been deceived, Malfurion entangled Maiev and left to look for Tyrande, with Illidan volunteering his naga to scour the river.\r\nWhen they found Tyrande, she and a small contingent of [[Sentinels]] were desperately battling the undead. Illidan fought to get to her through the river with his naga while Malfurion fended off the undead attackers. Finally, they pushed through the undead forces and Illidan rescued Tyrande.\r\nWhen Illidan brought Tyrande back to Malfurion, he was grateful. He decided that Illidan had earned his freedom, but Malfurion warned his brother that if he ever disturbed the night elves again, he would not be so forgiving. Illidan agreed to those terms, and opened a mystic portal.\r\nAs he retreated, Maiev caught up with them, and furiously chastised Malfurion and Tyrande for allowing Illidan to leave. In a rage, she and her Watchers followed Illidan into his portal. Tyrande tried to stop her, but Malfurion let her go, knowing that nothing they could say would change her mind.\r\nWith a heavy sigh, Malfurion and Tyrande left to return to their own realm and people, for there was still work to be done.\r\n===Recent Activities===\r\nMalfurion Stormrage stands as both prophet and savior to his people. Some time after returning to Kalimdor alongside Tyrande, he learned that a number of night elves were planning to create a new [[World Tree]] in the hopes of regaining their lost immortality. Malfurion warned against it, arguing that nature would never bless such a selfish act. Shortly after that, Malfurion returned to the spirit realm known as the [[Emerald Dream]], to replenish his powers after the events of the Second Invasion of the Burning Legion.\r\nRecently, something went wrong with Malfurion's dreamstate. Now he is trapped somewhere within the Dream, beyond even the reach of the [[Green Dragons]] who control it. In-game quests and events indicate he is fighting alongside [[Cenarius]]' spirit against [[The Nightmare]]. Whether he does not return by choice or because he has been made Unwaking by The Nightmare is unknown. What is known is that with Malfurion lost, the night elves continue to stumble blindly into darkness...\r\nAfter speaking with the druids in Moonglade, [[Brann Bronzebeard]] was given an explanation behind the mysterious circumstances of Malfurion's coma — that someone actually attacked Malfurion. \"An unknown assailant recently did ''something'' to the famed leader of the druids, Malfurion Stormrage, and he has been in some sort of catatonic state ever since. With the knowledge that the Cenarion Circle has an enemy powerful enough to incapacitate their leader, the druids have become increasingly worried and suspicious. After speaking with some of the druids here, I learned some unusual — and unsettling — facts.\" Brann believes that whatever did this may be one of the most powerful entities in the world. \"Prime suspects are Remulos and Fandral Staghelm, since they are the only druids powerful enough to potentially sabotage Malfurion’s efforts in the Emerald Dream; but perhaps the betrayer wasn’t a druid at all.\"\r\nWith Malfurion missing, Arch Druid [[Fandral Staghelm]] took over the leadership of the druids, convincing the [[Circle of Ancients]] in Darkshore that it was time for the elves to rebuild, and that it was time for them regain their immortality. With the approval of the Circle, and over the objection of a number of other groups, Staghelm and the most powerful druids grew [[Teldrassil]], the new World Tree.\r\nMalfurion's condition is a state secret. Only the highest-ranking members of the Cenarion Circle and the Sisterhood of Elune are aware of it.\r\n==In World of Warcraft==\r\nMalfurion, still in a comatose state has not yet physically appeared in game. That is not to say however he has had no impact and is slumbering peacefully. He appears via the emerald dream twice, once in [[Moonglade]], and another time in the [[Temple of Atal'Hakkar]].\r\n===Conversation with Remulos===\r\nIt seems that Malfurion Stormrage still visits Azeroth from time to time to chat with old friends about momentous events. Here follows a conversation with [[Keeper Remulos]] presumably concerning the disturbing rise of the [[Four Dragons]]:\r\n<font color=\"#EFEF00\">\r\nKeeper Remulos says: Malfurion!\r\nMalfurion Stormrage says: Remulos, old friend. It is good to see you once more. I knew the message would find its way to you &ndash; one way or another.\r\nKeeper Remulos says: It was shrouded in nightmares, Malfurion. What is happening in the [[Emerald Dream|Dream]]? What could cause such atrocities?\r\nMalfurion Stormrage says: I fear for the worst, old friend. Within the Dream we fight a new foe, born of an ancient evil. Ysera's noble brood has fallen victim to the old whisperings. It seems as if the [[Emerald Nightmare|Nightmare]] has broken through the realm to find a new host on Azeroth.\r\nKeeper Remulos says: I sensed as much, Malfurion. Dark days loom ahead.\r\nMalfurion Stormrage says: Aye Remulos, prepare the mortal races.\r\nKeeper Remulos says: You have been gone too long, Malfurion. Peace between the Children of Azeroth has become tenuous at best. What of my father? Of your brother? Have you any news?\r\nMalfurion Stormrage says: Cenarius fights at my side. [[Illidan]] sits atop his throne in [[Outland]] &ndash; brooding. I'm afraid that the loss to [[Arthas]] proved to be his breaking point. Madness has embraced him, Remulos. He replays the events in his mind a thousand times per day, but in his mind, he is the victor and Arthas is utterly defeated. He is too far gone, old friend. I fear that the time may soon come that our bond is tested and it will not be as it was at the Well in [[Zin-Azshari]].\r\nMalfurion Stormrage says: Remulos, I am being drawn back... [[Tyrande]]... send her my love... Tell her I am safe... Tell her... Tell her I will return... Farewell...\r\nKeeper Remulos says: Farewell, old friend... Farewell...\r\n</font>\r\nIt is presumed that Malfurion continues to fight along with Cenarius at present time.\r\nWhile Malfurion and the Emerald Dream will not be a component of the upcoming [[World of Warcraft: Wrath of the Lich King]], it has been confirmed that the plot will arise again after this expansion.\r\n==More Quotes==\r\n*\"Come forth, ye [[Treant|defenders of old!]]\" ''(To the forests, after being awakened by Tyrande to defend Ashenvale once again)''\r\n*\"If pride gives us pause, my love, then perhaps we have lived long enough already.\" ''(Regarding the loss of the night Elves' powers without Nordrassil)''\r\n*\"Whatever happens, my love, know this: our bond is eternal.\" \r\n*\"[[Darnassian|Andethoras-Ethil]]... [[Illidan|brother]].\"\r\n*\"[[Varo'then|You]] want <I>power?</I> Feel the power of the world you would betray, captain!\"",},
			["Malgen Longspear"] = { content = "Malgen Longspear is a level 60 [[elite]] [[centaur]] [[hunter]], and is part of [[Theldren]]'s team of gladiators at the [[Blackrock Depths]] arena. He has a pet called [[Gnashjaw]].\r\nHis weapon, Malgen's Long Bow, can sometimes be found in the [[Arena Spoils]] after defeating Theldren's team.",},
			["Malgin Barleybrew"] = { content = "'''Malgin Barleybrew''' is a level 25 [[rare mob]] [[dwarf]] found in the [[Barrens]]. He also happens to be the closest [[Alliance]] [[vendor]] to the [[Razorfen Kraul]] and [[Razorfen Downs]] [[instance]]s, selling an assortment of alcoholic beverages.\r\nOther members of the Barleybrew family include [[Marleth Barleybrew|Marleth]], [[Rejold Barleybrew|Rejold]], [[Mountaineer Barleybrew|Wellart]], and [[Yorus Barleybrew|Yorus]].",},
			["Mallet of Zul'Farrak"] = { content = "The '''Mallet of Zul'Farrak''' allows the player to summon a boss in [[Zul'Farrak]], [[Gahz'rilla]].\r\n==Source==\r\nThe steps to obtaining the Mallet of Zul'Farrak are simple. They are explained in Ancient Tablet, which is a random drop in Zul'Farrak. First, you need to head to [[The Hinterlands]]. Go to the [[Altar of Zul]]. At the top are two mobs, [[Qiaga the Keeper]] and [[Morta'gya the Keeper]]. The [[Sacred Mallet]] drops off of Qiaga.\r\nNext, you need to go to [[Jintha'Alor]], namely, the altar at the top. You'll fight your way through level 45-50 mobs on the long trek up. At the top is an amphitheater, with the Altar of Jintha'alor in the middle. On it is [[Elder Torntusk]], a Horde NPC. After clearing the mobs, stand by the altar and right-click the Sacred Mallet. This will transform it into the Mallet of Zul'Farrak.\r\n==Notes==\r\nTo summon Gahz'rilla in Zul'Farrak, you need to have the Mallet of Zul'Farrak in your backpack. Then just click the gong on the one side of the pool. The gong will sound and the hydra will emerge from the pool.\r\nQiaga the Keeper, Morta'gya the Keeper and the mobs at Jintha'alor used to be [[elite]] mobs until [[Patch 2.3.0]]",},
			["Malorne"] = { content = "''The enormous stag is a white so pure that he radiates a soft glow, like moonlight. He stares at you with eyes that are silver pools of deep and ancient wisdom, and his mere presence gives off an aura of calm, safety, and peacefulness.''\r\n'''Malorne''', or '''Apa'ro''', was an enormous white stag that roamed the land as protector of nature. His power lay in nature itself and he was responsible for the creation and nurturing of nature in the world. He was the father of [[Cenarius]], who inherited his dominion over nature.\r\n===Early history===\r\nIt is theorized that Malorne is older than Elune herself.\r\nThe earliest record of Malorne is in the [[tauren mythology|tauren myth]] [[The White Stag and the Moon]]. It describes how Malorne, being hunted by the [[tauren]], bargained with [[Elune]] in exchange for help. Malorne accepted Elune's help and loved her as part of the deal. Elune gave birth to [[Cenarius]] from that relationship.\r\nMalorne the Waywatcher showed up to help the [[Night Elf|night elves]] when a great crisis affected the world or the night elf civilization. Although he has great magical power, he is never shapeshifted into any other form. The stag prevented two civil wars among the night elves simply by making himself present before the astonished eyes of the night elves. Malorne was an excellent diplomat, opening dialogue between and pacifying conflicting parties.\r\nMalorne was able enter the [[Emerald Dream]] and the physical world at any time, and perceived what happens in both realms as if he had omniscience of what happens simultaneously in both planes. \r\nThere are rumors of the existence of a group of [[druid (lore)|druid]]s that take on the aspect of Malorne as Druids of the Antler, but it has not been proven.\r\n===Relationships===\r\nAs told in the above myth, Malorne was the lover of Elune, the mother of his son Cenarius. He subsequently became partner to the [[Dragon Aspect]] [[Ysera]], who adopted Cenarius as her own. This has led to speculation that Ysera and Elune were one and the same, but this theory has been officially [[Retcon|denied]].\r\nThe Warcraft Encyclopedia , clearly states (several times) that Malorne was never romantically involved with Ysera. The rumor was apparently started by the close relationship between Ysera and Cenarius (now known to be one of teacher and student), which led to speculation that she was his [[Elune|absent mother]].\r\n===Malorne's death and resurrection===\r\nNight elves worship Malorne for his great assistance during the [[War of the Ancients]] against the first invasion of the [[Burning Legion]] where he lost his life in defense of the world of Azeroth.\r\nCenarius had gone into a frenzy seeing [[Ursol, Ursoc]], [[Aviana]], and [[Agamaggan]] die. Cenarius crushed hundreds of [[felguard]]s and [[felhunter]]s.\r\nThe demons finally got hold of Cenarius, but before the [[demon]]s could slay him, Malorne came into the fray blinding all demons with his majestic white flashing body. Malorne's hooves crushed many demons, while his antlers killed many others. Malorne defended his son Cenarius, and with a look toward the elves as if telepathically commanding them to come for his son, [[Jarod Shadowsong]] and others dragged Cenarius to safety.\r\nMalorne's fury might have begun to turn the tide against the Burning Legion, had [[Archimonde]] not appeared. Black lightning struck the land around Malorne, baking it, then green fire from the ground engulfed Malorne, burning at his coat, while the land and rock formed giant hands that pinned his four legs to the ground. Archimonde swelled in size matching Malorne's height.\r\nMalorne freed himself from his magical trap, and charged Archimonde with his antlers, causing tremors and lightning as demons and Azeroth's races nearby shook and fell to the ground flat on their backs with astonishment. Malorne and Archimonde battled for some time, until, finally, Archimonde managed to seize Malorne and with great force snapped his neck. Cenarius's brave rescuer and father, limp and lifeless, was tossed aside by Archimonde.\r\n[[Malfurion]] knowing Cenarius was unconscious and that Archimonde had just slain Malorne, cast a spell that engulfed most of Archimonde's body with vines. The Archdemon, analytical as always, decided to retreat by vanishing in a green flare of flames that consumed the vines.\r\nShortly thereafter (a few moments, in fact), [[Alexstrasza]], [[Ysera]], and [[Soridormi]], along with their dragonflights, joined the War of the Ancients. Ysera came to a screeching halt at the sight of Malorne and opened wide her brilliant jade eyes (one of only a few times she did so in recorded history) with a deafening shriek. As she tore through the carnage to her friend, thousands of demons were thrown in all directions with her paws and wings. Her rampage continued, making her way through to her goal, until she came still, her chin on Malorne's head; sobs could be heard as She of the Dreaming mourned the White Stag's end.\r\nIt is currently believed by night elves, that he transcended death and that he has returned to Elune's side or sleeps in the Emerald Dream.\r\n==Power==\r\nThere is some confusion as to the accuracy of the tauren tale, ''The White Stag and the Moon''. It seems unlikely that a being of Malorne's power would fear the tauren, much less be hunted by them. The question is not about the parentage of Cenarius, but rather, about the circumstances that led to this liaison. Some think it unlikely that the tauren could have posed a threat to him, and thus question the hunt that chased Malorne into the sky. There are likely explanations for the story:\r\n# The tale is literally true (see below).\r\n#:A) The tauren chased him in such numbers that they posed a threat.\r\n#:B) The tauren had heroes among them that might have posed a threat to Malorne.\r\n#:C) He may not have wished to battle the tauren, due to them being a peaceful race and children of the [[Earth Mother]], and Elune gave him an opportunity to avoid conflict. \r\n#:D) Malorne was less powerful than at the time of his death, his liaison with Elune somehow unlocked latent powers.\r\n#:E) The hunt for Malorne was not a serious life-death adventure at all but it was more of a game between Malorne and the tauren. Marlorne did not actually run from the Tauren because he feared them but because he found it fun or exciting to be hunted and played along with mortals. Upon the point when he could not run anymore he simply could not accept defeat in the hunting game at hands of the mortals. \r\n# The tale is a myth based upon true events; though Malorne was forced to ask Elune's aid to escape a threat, it was not the tauren he was running from, and as the tauren retold the tale over the millennia, they replaced the unknown enemy with themselves. \r\n# The entire story is fictional, and was created to explain the liaison between Malorne and Elune that led to the birth of Cenarius.\r\nGiven the tauren's attitude towards demigods and other natural powers, however, it seems unlikely that they would even be hunting Malorne in the first place.\r\n==See also==\r\n*[[Server:Malorne]]\r\n*[[The White Stag and the Moon]]\r\n*[[Malorne Armor]]",},
			["Malorne Bladeleaf"] = { content = "'''Malorne Bladeleaf''' is a level 17 [[artisan]] [[herbalism trainer]] located in [[Dolanaar]] in the [[night elf]] starting zone, [[Teldrassil]].\r\nSee [[List of Teldrassil NPCs]].",},
			["Malorne Harness"] = { content = "'''Malorne Harness''' is the [[Tier 4]] set for Feral Druids. \r\n==Items==\r\n \r\n==Notes==\r\nThe set name is a reference to the white stag, [[Malorne]], father of [[Cenarius]].\r\nAlsoSee: [[Set look alikes]]",},
			["Malukaz"] = { content = "'''Malukaz''' can be found in [[Stonebreaker Hold]], [[Terokkar Forest]] .",},
			["Malux"] = { content = "'''Malux''' is a level 30 [[artisan]] [[skinning trainer]] located in [[Shadowprey Village]] in the [[contested]] territory of [[Desolace]].\r\nSee [[List of Desolace NPCs]].",},
			["Malyfous Darkhammer"] = { content = "'''Malyfous Darkhammer''' is a level 59 [[quest giver]] located in [[Everlook]] in the [[contested]] territory of [[Winterspring]]. He crafts three epic items for you via quests: Breastplate of Bloodthirst, Leggings of Arcana and the Cap of the Scarlet Savant. When [[The Beast]] in [[Upper Blackrock Spire]] is killed and skinned, [[Finkle Einhorn]] appears. He offers a quest that can be turned in to Malyfous to allow you to take these quests from a [[Malyfous's Catalogue|catalog]] on a desk next to him. \r\nMalyfous starts the following quest:\r\n* Fiery Plate Gauntlets (Blacksmithing)\r\nSee [[List of Winterspring NPCs]].\r\n==Notes==\r\nHe is also involved in three quests which you can gain by reading his catalogue. The quests result in the Cap of the Scarlet Savant, Breastplate of Bloodthirst, and Leggings of Arcana. Each of these quests requires a [[Pristine Hide of the Beast]] among other items from high-level instances.\r\nThe Pristine Hide can be [[Skinning|skinned]] from [[The Beast]] in [[Blackrock Spire]]. The Beast requires 310 skill to be skinned, but drops [[Finkle's Skinner]] which provides a +10 bonus to Skinning, thus enabling any skill 300 skinner to skin it (except [[paladin]]s, who cannot equip daggers). The only other item in the game that adds +10 skinning is the [[Zulian Slicer]] from [[High Priest Thekal]] in [[Zul'Gurub]], along with [[Enchant Gloves - Skinning]], which gives only +5 to skinning.\r\n'''NOTE:''' ''With the release of the [[Burning Crusade]] it is possible to raise your profession level to a maximum of 375, thus making it a simple task for any skinner who has been to Outland to skin the Beast.''",},
			["Malygen"] = { content = "'''Malygen''' is a level 55 general goods and [[weapon]]s [[vendor]] located at [[Talonbranch Glade]] in the [[contested]] territory of [[Felwood]].\r\nAlso, in patch 2.4, he sells 2 [[cooking]] recipes: [[Recipe: Juicy Bear Burger]] and [[Recipe: Charred Bear Kabobs]]. Opposing faction vendor of these recipes is [[Bale]].",},
			["Malygos"] = { content = "''The sinuous dragon rises from the water, a seemingly endless serpentine beast covered with crystalline scales of purest azure. The wings, looking too small to carry such a massive creature, are slick, and they shimmer as they reflect the light.''\r\n[[Norgannon]], the [[Titan]] master-magician and keeper of lore, granted the [[Blue Dragonflight|blue dragon]], '''Malygos''', a portion of his vast power. From then on, Malygos would be known as The Spell-weaver, the guardian of magic and hidden arcanum.\r\nMalygos is a leviathan with small wings. His body is covered with crystalline scales of pure azure. His body shines with shifting colors that change constantly from blue to silver. Theoretically, since he and his children specialize in magic it is likely that their powers far exceed those of the other dragon flights since magic is the element they rule.\r\nMalygos the Spellweaver is the blue Dragon Aspect, and the master of the blue dragonflight. He is one of the most ancient creatures living on Azeroth, and one of only a handful who were alive at the time the Titans departed. Now that he has regained his sanity, he is once again taking an active role in the protection of the world.\r\nMalygos, the Lord of Magic, is said to have created magic and spells, although this is likely mere legend. His command of magic is quite impressive, rivaling that of a demigod, although he does not aspire to such power. While physically he is not as powerful as some of the other Aspects, Malygos counters this disadvantage with his phenomenal command of magic. Like most of his kind, Malygos is a solitary creature who avoids contact with others. He is believed to dwell in Northrend, in a lair filled with some of the greatest magical artifacts known to exist, including many whose powers are discussed only in hushed whispers. Returned to sanity after Deathwing’s defeat at Grim Batol, Malygos now attempts to rebuild his decimated dragonflight. He spends his days studying magic, refining his abilities, and studying the various planes of the multiverse both remotely and in person, while his few remaining children scour the world for ancient artifacts and repositories of arcane power.\r\nMalygos does not seek out combat; and although he and his dragonflight are still routinely hunted by black dragons, he avoids their kind if at all possible. He protects his lair and himself with illusions and misdirection. Those who discover his home are encouraged to depart through a variety of means; Malygos takes direct action only as a last resort. When he does fight, he engages spellcasters first, using his breath weapon and other abilities to sweep spells from their minds.\r\n==History==\r\nAccording to the tome [[Legacy of the Aspects]], written by a human seeking knowledge amongst the [[Night elf|night elves]], Malygos does not have the form of a \"typical [[dragon]].\" The human author of the book writes that Malygos can change his form \"at will,\" which is, of course, not a unique ability among the [[dragonflights]]. Particularly interesting are the words that follow. The human author writes, \"Rarely seen after his retreat to the far north, he is almost always in the form of an insect-like creature, but while in dragon form he, and his flight, are varying blues in color.\" If the account is true, it strongly suggests Malygos lives -- or once lived -- among the [[Nerubian]] race of [[Northrend]].\r\nMalygos has an extraordinary command over magic, and although he is not as powerful physically, his spellcasting more than counters that disadvantage. Malygos lives in a cave within Northrend, and his lair contains many arcane magical artifacts. Malygos and his flight search for any magical source and artifacts and protect them so that mortal races may not endanger the world with their reckless use. He was closest to his brother [[Neltharion]], the Earth Warder, prior to [[the War of the Ancients]].\r\nWith his flight nearly annihilated, Malygos began to lose his mind. He felt deep guilt for his role in convincing the other [[Dragon Aspects|Aspects]] to infuse their powers into the [[Demon Soul]]. He traveled to his lair in Northrend, where he hid for millennia. Feelings of remorse paralyzed him. During the ten thousand years following The War of the Ancients, he was rarely seen by the other Aspects. His body was a caricature of his former self. A thin body surrounded by frozen ice, almost skeletal.\r\nMalygos is the oldest of the five Aspects, possibly the oldest dragon still living.\r\n===The War of the Ancients===\r\nDuring [[The War of the Ancients]] when [[Queen Azshara]] and her [[Highborne]] opened a portal in the [[Well of Eternity]] to allow the [[Burning Legion]] access to the world of [[Azeroth]], the [[Dragon Aspects|Great Aspect]]s congregated at the lair of [[Alexstrasza]] to discuss the coming invasion and what part they should play in defending the world. Neltharion proposed that to end the invasion of [[demons]], the dragonflights should create a weapon with which they could eradicate the [[demon]] armies.\r\nNeltharion persuaded Malygos to aid him in convincing the other Great Aspects to lend a part of their power to create the weapon, [[Dragon Soul|The Dragon Soul]]. The artifact was a simple unassuming golden disc created by Neltharion. The Dragon Soul was to be used as a weapon against the demons. All the Great Aspects and their flights contributed a bit of their power in creating the Dragon Soul with the exception of Neltharion. Through the disk, Neltharion was able to magically take control of all other dragons including the other Great Aspects.\r\nDuring one of the final battles the Great Aspects called all of their flights together and flew toward the battle where the Ancients had already perished and only night elves were holding back the Demons. With ease, a crazed Neltharion, now known as Deathwing, destroyed both demons and night elves by using the Dragon Soul -- now known as the Demon Soul -- against them. The other Aspects tried to stop Neltharion. Malygos's flight surrounded Deathwing in an attempt to take the Demon Soul from him. With a single command, they were engulfed by the magic of Demon Soul and were pulverized. Malygos was also terribly injured, both mentally and physically, but did not suffer the same fate as his flight.\r\n[[Krasus]] helped ease this loss by going to Malygos' lair, taking eggs that still had life and storing them somewhere unknown; at the end of the war, he hands them over to Nozdormu.\r\n===The Second War===\r\nAfter the [[Second War]], Alexstrasza was kidnapped by the [[Dragonmaw Clan|Dragonmaw]] [[orc]]s and taken to [[Grim Batol]]. Her younger consort [[Korialstrasz]], known as Krasus when disguised as an [[elf]], visited Malygos to seek his aid in an attempt to free Alexstrasza. Although Malygos initially refused, [[Krasus]] convinced Malygos to assist him by revealing that Deathwing was still alive and that Deathwing had indirectly led the Dragonmaw orcs to find the Demon Soul. Krasus finally said that Alexstrasza could use her powers over life to grant Malygos a new dragonflight. Seeing an opportunity to avenge the death of his flight, see their resurrection, and redeem himself, Malygos agreed to rejoin the world and confront Deathwing.\r\nAfter Deathwing was defeated and the Demon Soul destroyed, Malygos seemed to reclaim the vitality of his former self. [[Rhonin]] the [[mage]] destroyed the artifact using a scale of Deathwing and with a spell, all the magic and power of the Demon Soul was transferred back to the other Great Aspects, returning their full power to them. Although still a sparsely populated dragonflight, the blue brood grows slowly, giving hope to Malygos.\r\n===Quests===\r\nAs Coldarra is inaccessible without flying mounts, players are sent there on the back of a red dragon from NPCs located at [[Amber Ledge]]. On Coldarra, players meet [[Keristrasza]], who sends you on a quest to build a trap for [[Saragosa]], Malygos' consort. Keristrasza burns Saragosa's body at the culmination of the quest line, infuriating Malygos. Malygos descends upon the area and uses his magic to freeze Keristrasza and put her under his control. She is then forced to become his new consort and subsequently becomes a boss within the [[Nexus]].\r\n==Memorable quotes==\r\n* ''[[Deathwing|He]] didn't impart his own (power), didn't impart his own! Tell [[Rhonin|him]], [[Ysera]]! Tell him how, after the demons were defeated, he turned on us! Used our own power on us!''\r\n* ''I lost much - too much! But you, you who call yourself Krasus, you who once also wore the form of dragon, you lost all, too!''\r\n* ''Much to babble about, much to babble about!'' (To [[Nozdormu]])\r\n*''That [[Dragon Soul|obscenity]] should have never become reality, and as I've become instrumental in encouraging it's creation, 'tis only fair, old friend, that I erase it!''\r\n*''I have lost much in my time, mortal, too much in fact. Your lesser intellect could not possibly begin to understand the pain that infernal [[Demon Soul|disk]] can impart on its victims, Now begone from my realm before I show you a piece of what I have suffered!''\r\n*''What could you hope to accomplish, to storm brazenly into [[Eye of Eternity|my domain]]? To employ MAGIC? Against ME?''\r\n==Names and titles==\r\n* The Spell-Weaver\r\n* The Hand of Magic\r\n* Guardian of Magic\r\n* Lord of Magic\r\n==See also==\r\n* [[Day of the Dragon]]\r\n* [[The Well of Eternity]]\r\n* [[The Demon Soul]]\r\n* [[The Sundering]]",},
			["Malykriss"] = { content = "#REDIRECT [[Malykriss: The Vile Hold]]", redirect = "Malykriss: The Vile Hold",},
			["Malykriss: The Vile Hold"] = { content = "'''Malykriss: The Vile Hold''' is an under construction [[Necropolis]] made of [[Saronite]]. Under it is a whole Mmetalworking facility, producing [[Saronite]] for Malykriss and the Scourge in general.",},
			["Mammoth"] = { content = "'''Mammoths''' are shaggy beasts that resemble [[elephant]]s. They live in [[Northrend]] and are capable of dealing frightening damage. In addition to their long tusks, a horny protrusion of bone juts from their foreheads and another protrudes from their backs. Mammoths charge large foes.\r\n==Species==\r\n*Icetusk Mammoth\r\nIcetusk mammoths are large and aggressive, and intelligent creatures often avoid them.\r\n*Dire Mammoth\r\n*Wooly mammoth\r\n==Notes==\r\n*Mammoths share some resemblance to [[elephant]]s (or even [[elekk]]s), such as having a trunk, and ear flaps.\r\n==[[Wrath of the Lich King]]==\r\nPlayers will get a chance ride a mammoth into battle during a [[D.E.H.T.A]] quest and deploying its devastating charge, trample, and bellow attacks.\r\n''After making peace with the mammoths of the plains, I approached a mammoth elder and (somehow) spoke to him, and he told me I could now approach any bull mammoth mob and right-click to mount him, and then ride him to defeat some evil mammoth-oppressing Tauren dude. The mammoth mount had a little action bar and could trample enemies and charge, Warrior style. The mean, elite Tauren hopped on his own subjugated mammoth, and we dueled atop our great beasts like the cavemen of yore. Mounted combat: the secret new feature for Lich King. Sort of.''-Sean of 1UP\r\nThey have a new model that looks more like an stone elephant than the WCIII model.",},
			["Mammoth Shark"] = { content = "'''Mammoth Shark''' can be found in [[Durotar]] and [[Azshara]] .\r\n==Drops == \r\n \r\n66.67% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Man'ari eredar"] = { content = "#REDIRECT [[Eredar]]", redirect = "Eredar",},
			["Mana-Tombs"] = { content = "The '''Mana-Tombs''' are a wing of the [[Auchindoun]] [[instance]]. It is accessed north from the [[Ring of Observance]]. Note that although the instance itself is called Mana-Tombs, the entrance area outside the portal is called '''Mana Tombs''' without the dash. The instance normally takes about 90-120 minutes.\r\n==History==\r\n[[Auchindoun]] is a former [[draenei]] holy site and Horde fortress in the middle of the Bone Wastes, in Outland's [[Terokkar Forest]]. It was a holy ground for draenei burial until the Shadow Council took over, summoned an extremely powerful demon as old as time itself, and destroyed half of [[Terokkar Forest]] in the process. Different factions now vie for power in this magical spot: Ethereals suck the arcane energy from the Mana-Tombs, the Burning Legion harvests souls inside the Auchenai Crypts, arakkoa zealots work dark magic in the Sethekk Halls, and the Shadow Council plots its domination of Outland from within the Shadow Labyrinth.\r\nIts inhabitants are mostly [[ethereal]]s opposing the [[Consortium]]. The Mana-Tombs provide reputation for the Consortium until Honored; afterwards, in order to gain rep with the Consortium in Mana-Tombs, it must be run on Heroic (which requires honored with [[Lower City]]). The ethereals of the Consortium cannot enter due to the anti-ethereal wards set by [[Nexus-Prince Shaffar]]; they have attempted to breach the gates with little success, but have still tested whether or not their efforts worked - often resulting in the spotaneous combustion (for lack of a better term) of the ethereal tester sent through the gate. According to the Consortium, the ethereals in the Mana-Tombs are robbing it blind and if you wish to do business with them, you'll have to aid in taking out the competition.\r\n===Group and Level Guidance===\r\nIt is recommended that you take characters in the 64-66 level range. It is essential to have Crowd Control and/or Anti-caster abilities in group. One primary mage or warlock and a secondary can be helpful (Mage, Warlock, Second Priest, Hunter, Rogue). Tanking is not nearly as important in mana-tombs as it is in other instances so an off tank is not required. Having a back up healer is also helpful on boss fights, but they should be able to add to dps when demanded. A Priest or paladin is also needed for their shadow resistance buffs.\r\n===Preparation for the Instance===\r\nHaving Shadow resist items will make the first boss a lot easier, in fact, shadow resist items will be essential for players at the lower end of spectrum (63-64) that do not have a perfectly well formed party.\r\nIn order to summon Yor, at least one player from your party must have the quest Nexus-Prince Shaffar's Personal Chamber (Repeatable) or have completed The Eye of Haramad.\r\n===Stealth Runs===\r\nThis dungeon provides moderate to heavy difficulty for a party made entirely of rogues and druids. No mobs have stealth detection, but there are several 'pinch-points' where 2 saps may not be enough to sneak by.\r\n* Pandemonius is linked to all mobs in his room. Everything inside the room must be cleared. You may safely sneak around this boss.\r\n* Tavarok fights alone, and can be pulled with little to no preparation from the east side. You may safely sneak around this boss.\r\n* Yor fights alone, but the eels around its prison should be cleared at the very least.\r\n* Shaffar is linked to all mobs in his room. Everything past the stairs must be cleared. This fight is especially cruel to melee, and may be impractical for stealth running.\r\n===Bosses===\r\n* First Boss: [[Pandemonius]] - \r\n* Second Boss: [[Tavarok]] - \r\n* Third Boss: [[Nexus-Prince Shaffar]] - \r\n* Summoned Boss: [[Yor]] (Heroic Mode only) - \r\n==Loot==\r\nSee [[Mana-Tombs loot]].\r\n==Reputation==\r\nReputation gains go to [[Consortium]].\r\n* Trash mobs: 7 (heroic: 15)\r\n* [[Nexus Terror]]: 10 (heroic: 23)\r\n* [[Mana Leech]]: 1 (heroic: 3)\r\nA complete clear of Mana-Tombs will give about 1200 reputation with the Consortium until Honored, and 2400 each Heroic clear.\r\n==Maps==\r\n'''Sub-areas'''\r\n*[[Ravaged Crypt]]\r\n*[[Crescent Hall]]\r\n*[[Hall of Twilight]]\r\n==Quests==\r\nTwo quests are available at the entrance to the instance:\r\n* Safety Is Job One - Kill mobs in the instance, completed at the control panel prior to reaching Shaffar\r\n** Someone Else's Hard Work Pays Off - Escort the head engineer back to entrance. Probably best done after killing Shaffar and clearing the whole instance. (As soon as you finish the quest ''Safety Is Job One'', several friendly NPCs will spawn, one of them will offer you this quest.)\r\n* Undercutting the Competition - Kill Nexus-Prince Shaffar\r\nThe following are part of a quest chain that begins with Image of Commander Ameer in [[Blade's Edge Mountains]] after completing The Mark of the Nexus-King:\r\n* Stasis Chambers of the Mana-Tombs\r\n** Nexus-Prince Shaffar's Personal Chamber (Repeatable)\r\n** The Eye of Haramad - Not set inside the Mana-Tombs, but the reward is a permanent key to unlock Nexus-Prince Shaffar's Stasis Chamber",},
			["Mana-Tombs loot"] = { content = "This is a page listing '''loot to be found in [[Mana-Tombs]]'''. For information about the instance itself, see [[Mana-Tombs]]. __TOC__\r\n==Shared loot table (Heroic)==\r\nAll [[Mana-Tombs]] bosses share the following loot while in [[Heroic]] mode.",},
			["Manaclaw"] = { content = "'''Manaclaw''' is a level 58 [[elite]] blue [[drake]] found in the [[Mazthoril]] cave in [[Winterspring]].\r\nHe usually freezes one of the party members (who is then rendered as \"stunned\") during the fight for a few seconds.",},
			["Manaforge"] = { content = "A '''manaforge''' is a nether-collecting structure that harvests mana from the [[Twisting Nether]]. Manaforges suck energy from Nether (same energy that mages use at their spells) and it goes directly along the pipes to Tempest Keep, into Kael´thas use. Now ethereals smuggle energy in manacubes to the Isle of Quel´Danas, where Kael´thas and his army has moved. \r\nTheir original purpose is unclear, though their architectural similarity to [[Tempest Keep]] implies that they are of [[Naaru]] manufacture, much like the Keep itself. So we can assume that when Kael'thas armies took Tempest Keep from the Naaru, they also took Manaforges.\r\nA speculation can be made about their purpose, based on the [[Tempest Keep]] lore (post-BC release; see bottom of entry). If Tempest Keep and its surrounding vessels ([[The Mechanar]], [[The Botanica]], [[The Arcatraz]], and [[The Exodar]]) were originally deployed by the Naaru to assist in post-catastrophe operations in Outland, then perhaps the Manaforges were constructed as a means to fuel them after their arrival. There would be no reason for them to exist in the lush environment of Farah, still preserved within each [[Eco-dome]] and around [[Stormspire]].\r\nThe blood elves control all manaforges execept Manaforge Ultris, which was taken from the blood elves by the [[Voidwalker]]s, along with the mine beneath it.\r\nFour manaforges are operating in the [[Netherstorm]], under the control of [[blood elf|blood elves]] loyal to [[Kael'thas Sunstrider]]. They are:\r\n* [[Manaforge Ara]]\r\n* [[Manaforge B'naar]]\r\n* [[Manaforge Coruu]]\r\n* [[Manaforge Duro]]\r\nThe manaforge that has been destroyed:\r\n* [[Manaforge Ultris]]",},
			["Manaforge Ara"] = { content = "'''[[Manaforge]] Ara''' is one of the five facilities that 'collect' the mana energies from the air of [[Netherstorm]] for [[Kael'thas]]' [[blood elves]]. It seems that the blood elves did not build the buildings but only conquered them.\r\nAra is located on a separate floating island directly north of [[Area 52]]. Not only are there blood elves inhabiting the manaforge, but there are also members of the [[Burning Legion]] - potentially indicative of Kael'thas' new loyalties.",},
			["Manaforge B'naar"] = { content = "'''[[Manaforge]] B'naar''' is one of the five facilities that 'collect' the mana energies from the air of [[Netherstorm]] for [[Kael'thas]]' [[Blood elf|blood elves]]. It seems that the blood elves did not build the buildings, merely took them over for their own use. \r\nB'naar is to the west of [[Area 52]], and can be seen from the [[Gyro-Plank Bridge]] that connects Netherstorm to the [[Blade's Edge Mountains]].",},
			["Manaforge Coruu"] = { content = "'''[[Manaforge]] Coruu''' is one of the five facilities that 'collect' the mana energies from the air of [[Netherstorm]] for [[Kael'thas]]' [[blood elves]]. It seems that the blood elves did not build the buildings but only conquered them. Manaforge Coruu is also the base of [[Spellbinder Maryana]], one of Kael'thas' lieutenants.\r\nCoruu is located on the southernmost floating island of Netherstorm.",},
			["Manaforge Duro"] = { content = "'''[[Manaforge]] Duro''' is one of the five facilities that 'collect' the mana energies from the air of [[Netherstorm]] for [[Kael'thas]]' [[Blood elf|blood elves]]. It seems that the blood elves did not build the buildings but only conquered them. Manaforge Duro is also the home of [[Summoner Kanthin]], one of the most senior magisters of Prince Kael'thas.\r\nDuro is located on the floating island directly west of [[Tempest Keep]].",},
			["Manaforge Ultris"] = { content = "'''[[Manaforge]] Ultris''' is one of the five facilities that 'collect' the mana energies from the air of Netherstorm for [[Kael'thas]]' [[blood elves]]. This manaforge has been destroyed and taken over by creatures from the [[void]]. Before being destroyed, it had a mine underneath it that the blood elves used to supply materials for running the manaforges.\r\nUltris is located on a floating island northwest of [[Tempest Keep]].",},
			["Manaweave Cloak"] = { content = "==Source==\r\nThis item is crafted by [[Tailoring|Tailors]] with a skill level of 365.\r\nThe components are:\r\n*10 Spellcloth\r\n*12 Primal Mana\r\n*1 Primal Nether\r\nThe [[pattern]] is a random [[world drop]].",},
			["Manawraith"] = { content = "'''Manawraith''' are level 4-7 [[elementals]] found at the [[West Sanctum]] in [[Eversong Woods]] .\r\n==Quests== \r\n==Drops == \r\n \r\n0.05% Chance of an [[Uncommon]] drop.\r\n0.06% Chance of a [[common]] drop.\r\n0.10% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Mana bomb"] = { content = "'''Mana bombs''' are powerful explosive devices developed by [[Kael'thas Sunstrider]]'s [[blood elf|blood elves]] for use against enemy spellcasters. The exact workings are unclear, but it appears to utilize some kind of massive mana burn that kills its intended targets almost instantly.\r\nKael'thas utilized these vile weapons to remove what he perceives as \"obstacles\". He has used this weapon twice: A [[Broken draenei]] from [[Tuurem]] suicide-bombing the [[Cenarion Thicket]] in [[Terokkar Forest]], and bombing [[Kirin'Var Village]] in [[Netherstorm]]. A third is prepared in the courtyard of [[Firewing Point]], the closest of Kael'thas' outposts to [[Shattrath City]], for use against either the [[Allerian Stronghold]] or [[Stonebreaker Hold]] (the Alliance and Horde bases, respectively, near the edge of the [[Bone Wastes]]) or possibly Shattrath itself. After a series of quests investigating what happened to Cenarion Thicket and discovering the blood elves' complicity, adventurers from both sides are tasked to attack Firewing Hold and set off the bomb before it can be used; [[The Final Code|the final code]] to set off the bomb is held by a Blood Knight named [[Sharth Voldoun]], who resides at the top of the tower high above the courtyard.",},
			["Mana Burn"] = { content = "'''Mana Burn''' is a [[Shadow]]-based Priest spell. It drains mana from the enemy, causing Shadow damage.\r\n==Notes==\r\n*Mana Burn has some strange behaviour in combination with the Shadow tree. It works with [[Shadow Weaving]], [[Shadowform]], [[Vampiric Embrace]], and [[Vampiric Touch]]. However, it does not proc [[Blackout]], nor does it benefit from [[Darkness]] or [[Shadow Affinity]]. [[Shadow Focus]] probably does not affect it as well.\r\n*Its [[threat]] simply depends on its damage and follows normal rules; the mana drain does not cause any additional threat.\r\n*[[Priest_Talents|Shadowform]] will increase damage done by this spell.\r\n==Talent improvement==\r\n*[[Priest_Talents|Improved Mana Burn]] reduces the casting time of Mana Burn.\r\n*[[Priest_Talents|Force of Will]] increases spell damage and critical strike chance for all offensive spells.\r\n==Tips and tactics==\r\n* Mana Burn is useful both in PvE and PvP. It can be used against enemy spell casters in PvE to prevent them from casting their spells, especially healing spells. In PvP this spell is helpful against healing classes.\r\n* With [[Improved Mana Burn]], its effectiveness can be raised enormously. In addition, its susceptibility to interrupt effects can be reduced.\r\n* Combined with a shadow spec'd priest's Vampiric Embrace, Mana Burn can be an amusing and effective way to use the target's mana to heal your party (while damaging them in the process). Adding the Shadow spec Vampiric Touch to this also allows your mana to be somewhat replenished in the process.",},
			["Mana Feed"] = { content = "'''Mana Feed''' is a Warlock talent in the Demonology tree that causes Life Tap and Drain Mana to also restore a percentage of the gained mana to the Warlock's pet.\r\n==Notes==\r\nMana Feed is especially useful for grinding, where the paltry mana totals of a [[Voidwalker (Warlock pet)|Voidwalker]] or [[Felguard (Warlock pet)|Felguard]] might come up a bit short, or to recharge the waning mana of your Felguard or [[Imp]] during long battles.\r\nSome people are apt not to use [[Suffering]] because of the large mana cost, but this talent compensates for that and allows for the Voidwalker to be a much stronger tank. That said, if you have a lot of +dmg gear, you may not need to buy in all the way, since pet mana totals are quite small.\r\nAlso, it is possible to talent for both [[Dark Pact]] and Mana Feed, which combined with effects like [[Siphon Life]] can turn your pet into an almost inexhaustible mana battery.",},
			["Mana Fiend"] = { content = "'''Mana Fiend''' can be found in [[Ruins of Ahn'Qiraj]].",},
			["Mana Gem"] = { content = "#REDIRECT [[Conjure Mana Gem]]", redirect = "Conjure Mana Gem",},
			["Mana Leech"] = { content = "'''Mana Leech''' can be found in [[Mana-Tombs]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[Uncommon]] drop.\r\n0.01% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Mana Loom"] = { content = "Most [[Tailoring Patterns]] do not require you to be in or near a special place or device to create items. As long as you have all the required materials in your inventory, you can stitch the item anywhere. However, to craft a Bolt of Imbued Netherweave [[cloth]] the [[Tailor]] needs to stand near a '''Mana Loom'''.\r\nMana Looms can only be found in two currently known locations:\r\n* [[Shattrath City]]: In the [[Lower City]], positioned in between two of the Tailoring Specialist trainers, Nasmara Moonsong and Eiin . There is another one located near Eral, the General Goods vendor . Watch out, the vendor vomits when someone completes Of Thistleheads and Eggs..., which can interrupt your crafting.\r\n* [[Silvermoon City]]: In the [[Bazaar]], at the Tailoring shop.",},
			["Mana Oils"] = { content = "#REDIRECT [[Mana oils]]", redirect = "Mana oils",},
			["Mana Potion"] = { content = "'''Mana Potion''' is a [[potion]] that restores between 455 and 585 mana.\r\n==Source==\r\nThis potion is made by [[Alchemy|Alchemist]] with a skill level of 160.\r\nThe components are:\r\n*1 [[Stranglekelp]]\r\n*1 [[Kingsblood]]\r\n*1 [[Leaded Vial]]\r\nThe [[recipe]] is learned from a trainer.\r\nMana Potion can also be [[fishing|fished]] from level 30 - 40 zones and drops from level 30 - 40 mobs.\r\nMana Potions can also be bought from [[Bro'kin]] in the [[Alterac Mountains]], [[Drovnar Strongbrew]] in [[Arathi Highlands]], [[Vendor-Tron 1000]] in [[Desolace]], [[Uma Bartulm]] in [[Dustwallow Marsh]], [[Nandar Branson]] in [[Hillsbrad Foothills]], and [[Glyx Brewright]] in [[Stranglethorn Vale]].\r\n===[[Jewelcrafting]]===\r\n*[[Moonsoul Crown]]\r\n===[[Tailoring]]===\r\n*[[Crimson Silk Robe]]\r\n*[[Long Silken Cloak]]\r\n==Mana Potion as a Quest Objective==\r\n*1 is required for the [[Uldaman]] quest [[Quest:Replacement Phial|Replacement Phial]].\r\n==Notes==\r\nThis potion shares the same 1 minute cooldown as all other healing and mana potions, provided the imbiber is out of combat.",},
			["Mana regeneration"] = { content = "The condition of a game character gaining [[mana]] points over time is referred to as ''mana regeneration''. Players can gain mana from basically two sources - [[Spirit]] or items. Spirit regenerates rather high amounts of mana, but suffers from the restriction that it is interrupted for five seconds after spending mana for a spell (see 5 second rule below), while item-based regeneration is usually lower, but continues uninterrupted at all times.\r\nMana regeneration takes place once per [[tick]], but it's usually measured in the amount regenerated every 5 seconds (mp5), because that's the unit used in the tooltips.\r\n==Spirit-based regeneration==\r\nThe main base stat which regenerates mana is [[spirit]]. To a lesser extent, [[intellect]] also contributes, and the character level adversely affects regeneration. It's a good rule of thumb to assume that 1 spi = 1 mp5 while not casting.\r\nResearch by [[User:Whitetooth|Whitetooth]] shows that since [[Patch 2.4]] one uniform mana regeneration formula is used across all classes:\r\n \r\n MP5 = 5 * (0.001 + sqrt(Int) * Spirit * Base_Regen) ''rounded up''\r\n<tt>Base_Regen</tt> is a variable dependent on character level and is summarized in the following table:\r\nThe above chart was generated using this data. The formula shows that regeneration increases linearly with spirit and with the square root of intellect. The base regeneration goes down as level increases. When analyzing the plot it appears that levels 1-10 have one curve, 11-60 another and 61-70 have a jagged but almost linear decrease which seems to have been tweaked by hand.\r\nTogether these design elements seem to enforce balanced stats, so that stacking spirit to the detriment of intellect is to be avoided. It seems that 1 spirit = 1 MP5 was the target of the game designers. A level 70 caster needs about 460 intellect to reach this point.\r\n==Five Second Rule==\r\nAfter a character expends mana in casting a spell, the effective amount of mana gained per tick from spirit-based regeneration is reduced (''interrupted'') for a period of 5 seconds. This is commonly referred to as the '''five second rule''' ('''FSR''').\r\nChanneled spells are handled a little differently. The FSR starts when the spell's channeling starts; i.e. when mana is expended. The interruption continues for at least five seconds, and longer if the channeled takes more than five seconds. For example, Mind Flay channels for 3 seconds and interrupts regeneration for 5 seconds (from the moment the spell cast starts), while Tranquility channels for 10 seconds and interrupts regeneration for the full 10 seconds, but not longer.\r\nBy default, the interrupted mana regeneration ratio is 0%. Several effects can increase this ratio, including:\r\n<span style=\"font-size: smaller\">* Depending on rank</span>\r\nMultiple ratios do stack, but can never exceed 100%.\r\nSpells which don't cost mana do not start the FSR. This includes spells with a normal mana cost of zero (e.g. [[Nature's Swiftness]]), but also spells whose effective cost is reduced to zero by some effect (e.g. by [[Clearcasting]] or an item ability or proc like [[Eye of Gruul]]).\r\nPrior to [[Patch 1.4]] regeneration was also interrupted during a spells cast time (since then it's only interrupted when mana is expended). For this resaon, in-game textual references to the FSR still read \"while casting\" where they actually should read \"after expending mana to cast\".\r\n==Direct regeneration==\r\nMany effects increase mana regeneration directly i.e. without increasing spirit. These effects are governed by different rules than spirit-based regeneration, in particular they're never subject to the five second rule.\r\nThe most frequent source of non-spirit-based regeneration is the \"regenerates X mana in 5 seconds\" stat on items. This stat is usually written abbreviated as \"mp5\".\r\nThere are some effects which regenerate mana (e.g. [[Insightful Earthstorm Diamond]]) which deliver their mana the instant they [[proc]]. Some items (e.g. [[Second Wind]]) do not regenerate mana in 2 second ticks but rather in the intervals actually advertised in their tooltip.\r\n==Comparing spirit based and direct regeneration==\r\nIn theory, direct regeneration is preferable as it is not subject to the FSR. Unfortunately though, mp5 is much harder to get and more \"expensive\" than spirit. All attributes have an [[Formulas:Item Values|Item Value]], a kind of \"cost\" associated. This value for mp5 is 2.5 times higher than for spirit. For example the two top mana regeneration enchants for chest items yield either 15 spirit or 6 mp5 (Enchant Chest - Major Spirit and Enchant Chest - Restore Mana Prime) - this shows the factor of 2.5 very clearly.\r\nIn order to find out what's better, characters should first find out their personal time spent inside the FSR, e.g using an addon like or RegenFu. It's important to perform the measurement under realistic conditions - the time spent inside the FSR while grinding is typically much lower than during a boss fight. Some players actually argue that in a tight situation, it's safe to assume that the FSR is in effect 100% of the time. It is possible to calculate the percentage of time which has to be spent outside the 5 second rule so that 2.5 points of spirit are more effective than 1 point of mp5. Examples:\r\nAverage lvl 70 priest with maxed [[Meditation]]:\r\n2.5 spirit return 2.5 mp5 outside the FSR, and 0.75 mp5 inside. The mathematical form of the question is thus \r\n 2.5 * x + 0.75 * (1 - x) = 1\r\n 1.75 * x = 0.25\r\n x = 0.14\r\nSo if that priest spends 14% percent of the time outside the FSR, the enchant with 15 spirit yields a higher regeneration than 6 mp5. If the time inside the rule is 86% or more, 6 mp5 is more efficient.\r\nFor lvl 70 characters without spirit regeneration inside the FSR:\r\n 2.5 * x = 1\r\n x = 0.4\r\nThat is they have to spend 40% of their time outside the rule for spirit to be better than mp5.\r\n==Additional notes==\r\n* Mana regeneration is not affected by sitting down or standing up\r\n* Spell casting never stops direct mana regeneration effects from items\r\n* Spell casting does not in itself have an effect on regeneration, only mana expenditure",},
			["Mana Shield (original)"] = { content = "[[Mana Shield]] is a self-cast [[mage]] spell that shields the caster from all damage. It can be a mage's best friend or worst killer. When this shield up, physical and magical damage will be absorbed at the cost of 2 mana per point of damage. The shield collapses after absorbing a set amount or 1 minute passes, whichever comes first.\r\n===Talent improvements===\r\nThe [[Arcane Shielding]] talent will reduce the amount of mana consumed per point of damage up to a 33% reduction at max rank. This makes the damage to mana ratio 1 to 1.\r\n==Tips and Tactics==\r\nAfter it absorbs the given damage (consuming twice that amount of mana) it will collapse, but no [[cooldown]] means you can recast immediately, or even while it's still partially up to \"refresh\" the absorption pool.\r\nDon't be fooled by the cheap casting cost. Mana Shield can drain your mana deceptively fast. Rank 3, for instance, will leave you (80 + 2 x 300) 680 mana poorer in exchange for a measly 300 health. Use wisely.\r\nThe Improved Mana Shield talent can make stomaching this spell somewhat easier - with both ranks of the talent active the quoted figure of 680 mana for 300 health drops to 560 mana (80 initial cast + ( 600 - [600 / 5])), thus saving you 120 mana, which is at least enough for one Frost Nova at that level.",},
			["Mana Spring Totem"] = { content = "==Overview==\r\n '' Summons a Mana Spring Totem with 5 health at the feet of the caster for 2 min that restores '''XX''' mana every 2 seconds (see [[Mana Spring Totem|Description]] by rank level) to group members within 20 yards.'' \r\n==Functionality==\r\nApplies a [[buff]] to party members which restores XX mana every 2 seconds, regardless of the [[5 second rule]] of mana regen. \r\n===Use===\r\n*Casting Time: Instant Cast\r\n*Range: Not Applicable\r\n*Duration: 120 seconds (2 minutes)\r\n*Cooldown: Global Totem Cooldown\r\n===Limitations===\r\n*Must be within 20 yard radius of the totem.\r\n*The totem of any rank has only 5 hp; it is easily destroyed by mobs and players.\r\n===Talents===\r\nTalents that can improve the totem:\r\n===Tips and tactics===\r\nStill, this is one of the two water totems with general appeal. All other water totems are either very situational (poison/disease cleansing) or need talents (mana tide, which has also a CD). While taking damage, [[Healing Stream Totem]] is usually better, when in a group with other casters, mana spring is a viable choice.\r\nIn raiding/instances, an Elemental specced Shaman with Water Shield and Mana Spring Totem has amazing casting endurance if only Lightning Bolt is used. Save Chain Lightnings for whenever a critical hit happens and the casting cost is reduced.\r\n===Notes===\r\nIn [[Patch 2.3]], mana regeneration effect increased to 6/9/13/17/20 mana every 2 sec from 4/6/8/10/12 mana.",},
			["Mana Stalker"] = { content = "'''Mana Stalkers''' are level 5-6 [[elemental]] found at the [[West Sanctum]] in [[Eversong Woods]] .\r\n==Quests==",},
			["Mana surge"] = { content = "'''Mana surges''' are a magic-based elementals which are a type of air [[elementals]]; They exist in [[Azeroth]] as physical manifestations of pure arcane magic, or even of [[mana]] energy itself. Mana surges are approximately 1 foot in diameter and weigh almost nothing, although their relative size fluctuates depending on how much magic they have drained recently.Most are found in [[Dire Maul]]. Not to be mistaken for [[Arcane Elemental]]s which contain air, water, earth and fire.\r\nMana surges are air elementals spawned in areas where magical energy naturally combines with electrical storms. It is like a glowing blob of light that bobs up and down as it flits along. Tiny sparks dance around the creature as it moves. They consume magic and are drawn to sources of power, such as magic items or spellcasters. They move constantly but randomly, ever seeking new sources of energy on which to feed. Mana surges are aggressive, especially if they sense magic nearby. They distract foes with electrical charges while consuming whatever magic they can absorb. Once sated, they lose interest and fly away. A mana surge can be distracted by giving it a charged item, such as a wand or staff, to feed upon.\r\nMana surges are approximately one foot in diameter and weigh almost nothing, although their relative size fluctuates depending on how much magic they have drained recently. Mana surges do not speak or understand any sort of language. Although sometimes captured for use against spellcasters, they cannot be trained and make poor pets. Mana surges automatically sense the most powerful source of magic in the area and attack that opponent exclusively, ignoring all other threats. They drain magic until dated and then depart the area to digest. Mana surges have no sense of self-preservation and attack regardless of any danger to themselves.\r\nMana surges are an aberration in the natural flow of magic. If [[ley line]]s and moon wells are the arteries and organs of the magical world, mana surges are its cancer. Some believe that these creatures are the side effects of powerful summoning spells or a violent disruption of ley lines. A few wizards research these creatures, hoping for some dramatic insight into the nature of magic. More experienced scholars warn all to stay clear. A mana surge is rather like an [[ooze]] in many ways, though its substance is incredibly concentrated magic rather than protoplasm. They can appear like liquid or gaseous coalescence of energy, and have a consistency that feels rubbery to the touch. Mana surges are sometimes found with treasures. Random magical forces can transmute its surroundings into valuable metals or even enchant objects. Whether the mana surge wanders away before destroying such items is a matter of chance.\r\n==Notes==\r\n*Magic elemental or mana elemental is currently a fan description of this class of creature, the closest equivalent description has been \"''burning elementals crafted of pure mana''\" according to one source.\r\n*Some share more of a relation with oozes than elementals, having a rubbery consistency.\r\n*Magic elementals commonly do arcane damage.\r\n*In the [[Monster Guide]], 2007, these creatures are classified as mana surges. They are also confirmed to be elemental in nature.\r\n==Types==\r\n*[[Mana Surge]]\r\n*[[Mana Burst]]\r\n*[[Mana Fiend]]",},
			["Mana Tap"] = { content = "A [[Blood_elves_(playable)|Blood elf]] [[racial ability]] used in combination with [[Arcane Torrent]]. '''This ability was removed in patch 3.0.2.'''\r\n==Notes==\r\n* The value of X = (50 + level).\r\n==Tips and Tactics==\r\n*Mana Tap breaks [[Polymorph]], [[Sap]], and [[Freezing Trap]] as the mana drain counts as an attack.\r\n*Since Mana Tap costs zero mana, its good to use mana tap as quickly as possible, remembering that arcane energy stacks up to 3 times.\r\n*An enemy that has run out of mana will have any remaining mana drained up to the maximum of the ability.\r\n*Doesn't work on enemies with no mana bar.\r\n*Can be used to pull [[mobs]] efficiently if you lack any other means.\r\n*Mana tap activates the [[GCD]].",},
			["Mana Thistle"] = { content = "'''Mana Thistle''' is an [[herb]] that can be gathered by [[Herbalism|herbalist]]s. It can only be found in places accessible by flying, except for the [[Isle of Quel'Danas]]. It is typically found in groups of two, meaning that for a given area, you can usually find two nodes. It requires 375 Herbalism to gather.\r\n==As an ingredient==\r\nMana Thistle is used in the following recipes:\r\n[[Alchemy]]\r\n* [[Cauldron of Major Arcane Protection]]\r\n* [[Cauldron of Major Fire Protection]]\r\n* [[Cauldron of Major Frost Protection]]\r\n* [[Cauldron of Major Nature Protection]]\r\n* [[Cauldron of Major Shadow Protection]]\r\n* [[Elixir of Empowerment]]\r\n* [[Fel Mana Potion]]\r\n* [[Flask of Arcane Fortification]]\r\n* [[Flask of Mighty Restoration]]\r\n* [[Flask of Relentless Assault]]\r\n* [[Flask of Shadow Fortification]]\r\n* [[Flask of Fortification]]\r\n* [[Major Arcane Protection Potion]]\r\n* [[Major Fire Protection Potion]]\r\n* [[Major Frost Protection Potion]]\r\n* [[Major Nature Protection Potion]]\r\n* [[Major Shadow Protection Potion]]\r\n* [[Super Rejuvenation Potion]]\r\n==Notes==\r\n*Gathering a Mana Thistle will restore 500 to 3500 mana to the gatherer. \r\n*Gathering a Mana Thistle will occasionally yield [[Mote of Life]] in addition to the herb.\r\n*Unlike normal herb nodes, you will only obtain one or two Mana Thistle per each node picked. \r\n*Mana Thistle is sold by [[Dealer Sadaqat]] in a limited supply (1) in the Netherstorm.\r\n*It is possible for players under 70, without a flying mount, to gather this herb. It is located on [[Socrethar's Seat]], which is accessible through a quest before 70.",},
			["Mana Tide Totem"] = { content = "'' Summons a Mana Tide Totem with 5 health at the feet of the caster for 12 sec that restores '''6%''' of total mana every 3 seconds to group members within 20 yards.'' \r\n===Use===\r\n*Casting Time: Instant Cast\r\n*Range: 20 yards (30 with talents)\r\n*Duration: 12 seconds.\r\n*Cooldown: 5 minutes Cooldown\r\n===Limitations===\r\n*Must be within 30yd radius of the totem.\r\n*The totem has only 5 hp; it is easily destroyed by mobs and players.\r\n*Has a cooldown of 5 minutes.\r\n*Second shortest duration for a totem.\r\n===Talents===\r\nTalents that can improve the totem:",},
			["Mana Tombs"] = { content = "#REDIRECT [[Mana-Tombs]]", redirect = "Mana-Tombs",},
			["Mana Wyrm"] = { content = "#REDIRECT [[Mana wyrm]]", redirect = "Mana wyrm",},
			["Mandred Grummel"] = { content = "Sergeant '''Mandred Grummel''' is a [[human]] [[fighter]]. He is the commander of the [[Stormwind City Guard]]. He is intimidating and known for his ruthless command (he does not allow his allies to grant quarter or mercy.)",},
			["Manga"] = { content = "The Warcraft '''manga''' are a series of Manga from various artists. (including ''Korean-language '''[[wikipedia:manga|manga]]''')or ''[[wikipedia:manwha|manwha]]''. \r\nSo far the [[Warcraft]]-related \"manga\" stories have been illustrated by [[Kim Jae-Hwan]], Mi-Young No (Korean artists), [[Carlos Olivares]] (a Spanish artist), and Nam Kim\r\n...I was only familar with Jae-Hwan's work from the visceral King of Hell series, it was clear from the get-go that his super detailed (yet totally gritty) art style would capture the Warcraft feel perfectly. Translating Warcraft's over-the-top hyper proportionate art style to the 'manga style' was tricker than one might think - but Mr. Kim made it look efortless. Now, I know I'm a bit biased, but I think this book is one of the most strikingly illustrated manga series on the market today.\r\n-Chris Metzen,from the Aftword, in the Sunwell Trilogy Ultimate Edition.\r\nAre you looking for:\r\n*[[The Sunwell Trilogy]] manga.\r\n*'''Hardcover Collection''': [[Sunwell Trilogy (Ultimate Edition)|Ultimate Edition]]\r\n*'''Volume 1:''' [[Dragon Hunt]]\r\n*'''Volume 2:''' [[Shadows of Ice]]\r\n*'''Volume 3:''' [[Ghostlands (book)|Ghostlands]]\r\nor\r\n*[[Dragons of Outland]] manga.\r\n*'''Volume 1'''\r\n*'''Volume 2'''\r\n*'''Volume 3'''\r\nor\r\n*[[Warcraft: Legends]] manga.\r\n*'''[[Warcraft: Legends Volume 1|Volume 1]]'''\r\n*'''Volume 2'''\r\n*'''Volume 3'''\r\n*'''Volume 4'''\r\n==Notes==\r\n*''Korean-language manga'' or ''[[wikipedia:manwha|manwha]]'' are comics produced by Korean comic artists. Their style varies from that of Japanese manga (Japanese comics) and western comics. Blizzard and [[wikipedia:Tokyopop|Tokyopop]] markets all of its original English language manhwa as manga, as the term is well established in its target audience market and manhwa is not.",},
			["Mangle!"] = { content = "''Braaaaaaaains!''",},
			["Mangle"] = { content = "''Oh, I'm sorry, did you ''need'' your arms and legs?''\r\n'''Mangle''' is the 41 point talent of the [[Feral Combat]] [[druid]] talent tree. It can be first attained at level 50.\r\n==Rank tables==\r\n'''Dire Bear Form version'''\r\n'''Cat Form version'''\r\n==Notes==\r\nFor both Bear Form and Cat Form, Mangle causes the target to take 30% additional damage from Shred and [[Bleed|bleed effects]] for 12 sec.\r\nFor Bear Form, the attack causes 115% normal damage plus a bonus amount, and generates an as yet unknown amount of additional [[threat]].\r\nFor Cat Form, the attack causes 160% normal damage plus a bonus amount, and awards 1 [[combo point]].\r\n==Tips and tactics==\r\n* Due to identical energy costs, cooldowns, and applications, [[Claw]] is outperformed by the more damaging '''Mangle (Cat)'''.\r\n* Mangle (Bear) makes significant contributions to aggro gain and should be reapplied whenever possible. However, it is limited by the [[attack table]] and its own cooldown. To improve the frequency of its use, include it in an ability rotation (e.g. spam it), or install a cooldown timing AddOn.\r\n==Past Changes==\r\n* Prior to v2.0.10, Mangle (Bear) caused 1.3x normal damage + a (larger) bonus amount. Mangle (Bear) was also affected by the 20% damage increase from the [[Savage Fury]] talent.\r\n* Post v2.0.10, Mangle (Bear)'s damage was reduced. [[Savage Fury]] was modified to no longer affect Bear Form attacks.\r\n* As of a hotfix on 3/6/07, Mangle (Bear) has a threat modifier of 1.5x damage done.\r\n* For v2.1, Mangle (Bear) is slated to be 1.15x normal damage + some (unknown) bonus amount. The threat modifier is also expected to be modified to keep the final threat output roughly the same.\r\n* Post v2.2, reapplying Mangle on the target will now fully refresh the debuff, instead of only partially.",},
			["Mangletooth"] = { content = "'''Mangletooth''', a [[quilboar]] of the [[Razormane]] tribe, is a level 17 [[quest giver]] located in [[Camp Taurajo]] in the [[Horde]]-aligned territory of [[the Barrens]]. He was captured by the orcs and tauren and is waiting his execution. At first, Mangletooth will try to convince players to attack the enemy of his tribe, the [[Bristleback]]s, in hope this will convince his own tribesman to save him. However, after he sees his clansmates - [[Nak]], [[Kuz]] and [[Lok Orcbane]] - for who they truly are, he starts plotting his revenge... \r\nBring him lots of [[Blood Shard]]s, and he will cast the blessings of [[Agamaggan]] upon you.\r\nHe starts the following quests:\r\n* Tribes at War\r\n* Blood Shards of Agamaggan\r\n* Betrayal from Within\r\n* Betrayal from Within (2)\r\nHe takes [[Blood Shard]]s in exchange for buffs in the following quests:\r\n*Agamaggan's Agility (repeatable)\r\n*Agamaggan's Strength (repeatable)\r\n*Razorhide (repeatable)\r\n*Rising Spirit (repeatable)\r\n*Spirit of the Wind (repeatable)\r\n*Wisdom of Agamaggan (repeatable)\r\nSee [[List of the Barrens NPCs]].",},
			["Mangy Duskbat"] = { content = "'''Mangy Duskbats''' are a weak, unaggressive red bat found outside [[Deathknell]]. Larger species can be found throughout [[Tirisfal Glades]]. They are sometimes hunted by the [[Forsaken]] of the town for their wings, which are used to make armor.\r\n==Attacks and abilities==\r\n*'''[[Melee|Basic Melee]]''': 2-5 damage (before subtracting armor)\r\n==Quests==\r\n* The Damned - from [[Novice Elreth]] in the church in [[Deathknell]]\r\n:Objective: Acquire 6 [[Scavenger Paw]]s from [[Young Scavenger]]s and 6 [[Duskbat Wing]]s from [[Duskbat]]s.",},
			["Mangy Nightsaber"] = { content = "These nightsabers live in the sheltering forest of [[Shadowglen]], on the great tree [[Teldrassil]]. Unfortunately, the nightsaber population in the area has recently skyrocketed to unhealthy numbers. The [[night elf|night elves]] of the area have begun culling the cats in an attempt to keep their population in check (see The Balance of Nature (2)).\r\n==Quests==\r\n* The Balance of Nature (2) - from Conservator Ilthalaine in [[Shadowglen]]\r\n:Objective: Kill 7 [[Mangy Nightsaber]]s and 7 [[Thistle Boar]]s.",},
			["Manifestation of Water"] = { content = "An [[elemental]] at [[The Tidus Stair]], summonable by [[Islen Waterseer]].\r\nThe \"Manifestation of Water\" is summoned by Islen when you bring [[Corrupt Moonwell Water]] to her as part of the [[Quest:Seeking Spiritual Aid|Seeking Spiritual Aid]] quest.\r\nSee also:\r\n==Islen speaks to Manifestation of Water==\r\n<font style=\"color:#dddd88;\">\r\nIslen Waterseer says: Spirits of Water, I give you praise, and beg of you a favor. You have heard ''<the adventurer>'s'' pleas, and I trust ''<her/his>'' intent is noble.\r\nPlease, will you aid us?\r\nManifestation of Water says: &#91;[[Kalimag|<font style=\"color:]]&#93; Ma reth bromo zoln kilagrin dra ma zoern tu ko fraht ko kadrom Ma krin drinor zoln drinor Ma krin kan aasrugel korsul\r\n</font>",},
			["Mani Winterhoof"] = { content = "'''Mani Winterhoof''' is a level 30 [[alchemy]] [[vendor]] located on the [[Middle Rise]] in the [[tauren]] city of [[Thunder Bluff]]. \r\nSee [[List of Thunder Bluff NPCs]].",},
			["Mankrik's Wife"] = { content = "'''Mankrik's Wife''' refers to the [[quest]] [[Quest:Lost in Battle|\"Lost in Battle\"]] in the [[Barrens]], in which [[Mankrik]] asks you to find his wife, who fell in battle. \r\nMankrik's wife is very far away from him, and he offers almost no directions to her location. There is also no NPC called \"Mankrik's Wife\", as she is called \"[[Beaten Corpse]]\". This results in almost everyone accepting this quest resorting to asking for her location in [[Barrens Chat|Barrens general chat]]. This becomes extremely annoying, as [[Horde]] characters spend large amounts of time in the Barrens, and hearing the same question repeated over and over and over again tends to drive the somewhat more experienced players a tad irritable.\r\nRepeated requests for the location of Mankrik's Wife have resulted in responses that vary wildly in accuracy — some place her quite close to her actual location (though such responses are probably given out of pity for the lost player), while others — depending on the prevailing mood — attempt to send players to far-off, hard-to-reach (or often totally impossible to reach) places (such as 'Inside Blackrock Mountain' or 'Next to Illidan's Throne').\r\nOn many realms \"Mankrik's Wife\" has also become a generic response to general chat questions involving quest-givers, merchants, etc. For example:\r\nPlayer 1: ''\"Where do you train Shadow bolt?\"''\r\nPlayer 2: ''\"Mankrik's Wife.\"''\r\nMany people who begin Blood Elves often ask in General Chat for the location of the [[Shrine of Dath'Remar]]. A handful of people have recently dubbed this \"The Shrine of Mankrik's Wife\"\r\nOn the U.S. server Burning Blade the Mankrik's Wife question was taken to new heights when three PCs \"Mankrik\" Mankrik's Wife\" and \"Mankrik's gay lover\" when to the barrens and had a soap Oprah style fight in barrens chat. The show ended with all three dieing next to each other on the ground out side of the crossroads.\r\nAmong the [[Saurfang facts|facts]] about [[High Overlord Saurfang]], one of them is \"Mankrik's wife made the mistake of telling Saurfang that Sword Specialization is superior to Axe Specialization\".",},
			["Mankrik"] = { content = "'''Mankrik''' is a level 15 [[quest giver]] located at [[the Crossroads]] in the [[Horde]]-aligned territory of [[the Barrens]].\r\nMany people misspell Mankrik to Man''kirk''.\r\nIt is possible that Mankrik is a former member of the [[Burning Blade Clan]] and a blademaster, as he shows signs of obsession (asking you to kill dozens of thorntusks) and also displays a Burning Blade banner outside his hut.\r\nHe starts the following quests:\r\n* Consumed by Hatred\r\n* Lost in Battle (also known as \"[[Mankrik's Wife]]\")\r\nSee [[List of the Barrens NPCs]].",},
			["Manni"] = { content = "'''Manni''' can be found in [[Hellfire Peninsula]] . Manni is currently being held prisoner by the nearby [[Fel orc]]s. [[Foreman Razelcraz]] would like you to save him.\r\n==Objective of==\r\n*How to Serve Goblins",},
			["Mannoroc Coven"] = { content = "'''Mannoroc Coven''' is located directly to the south of [[Ghost Walker Post]] and east of [[Shadowprey Village]] among the ruins of the [[night elves]]. It is named after the dreaded [[Pit Lord]], [[Mannoroth]]. The already dead earth has been even further blasted by the fel magic of the [[demons]] that inhabit the area. The magic is thick in the air and travelers will notice that a deadly pall falls over the region upon entering. The [[infernal]], the [[succubus]], the [[felhound]] and the [[felguard]] stalk the area and are hostile to all foolish enough to pass through. \r\nSeveral agents of the Burning Legion, including fel hunters, infernals, doom guards and succubi, reside here, led by [[Lord Azrethoc]]. The orc warlock [[Jugkar Grim'rod]] also represents the Burning Blade here. This group is the largest demonic coven in central Kalimdor.\r\nThe coven is a haven for the demons who have been summoned into the world by the Burning Blade cultists using a number of magical portals. The demons that populate the Mannoroc Coven are proof that this nefarious scheme has been dangerously successful. Recently, a number of adventurers have sealed some of these portals using the [[Hand of Iruxos]] on the behest of [[Taiga Wisemane]], but no matter how many portals are banished, more inevitably appear over time, suggesting that a more permanent solution needs to be found to prevent Desolace from turning into a stronghold of the [[Burning Legion]] in Azeroth.",},
			["Mannoroth"] = { content = "'''Mannoroth the Destructor''' was a [[pit lord]] whose ruthlessness and vile cunning made him into one of the favoured lieutenants of his masters, [[Archimonde]] and [[Kil'jaeden]], the champions of the [[Burning Legion]]. Known as “the Destructor” and \"the Flayer\", Mannoroth was the barbaric leader of the pit lords when the dark titan Sargeras subjugated them and bent them to his will. When Archimonde was placed in command of the pit lords, he recognized Mannoroth’s value as a brutal, bloodthirsty fighter and made the pit lord his second-in-command. Mannoroth helped lead the Burning Legion in assaults on countless worlds, and led the first invasion of Azeroth.\r\n===War of the Ancients===\r\nMannoroth was among the demons who entered into [[Kalimdor]] during the [[War of the Ancients]].\r\nHe singlehandedly slaughtered entire regiments of Kaldorei defenders and sowed chaos by unleashing squads of doomguard across the land. Though he battled with brutal ferocity and slaughtered many, he was defeated by [[Cenarius]] and his followers and sent back into the [[Twisting Nether]] when the [[Well of Eternity]] was destroyed.\r\nAlthough his forces were ultimately defeated and forced to flee from Azeroth, Mannoroth was pleased with the level of carnage that he had inflicted.\r\n===Mannoroth and the orcs===\r\nIn preparation for the Burning Legion’s second invasion of Azeroth, Kil’jaeden dispatched Mannoroth to Draenor. Describing him to Gul'dan, Kil'jaeden mentioned that \"Mannoroth is known for many things. Patience is not among them.\" There, twelve clan chieftains of the orc Horde drank from Mannoroth’s blood and fell prey to the curse of bloodlust. Their corruption quickly spread to the rest of the Horde and ultimately led to their ill-fated assault on the human kingdoms on Azeroth.\r\nMannoroth made his mark upon the orcs in [[Draenor]]. Many years before the [[Dark Portal]] was first formed, Mannoroth, under orders from [[Kil'jaeden]], took part in the plan to put the orcs under the thumb of the Burning Legion. Though he would later say that the orcs were his \"by right\", it was likely just plain arrogance of his blood pact with the orcs. His own master, Kil'jaeden, could claim rule over the orcs since it was he who discovered them. They would serve as harbingers of chaos, wiping out any potential resistance when the Legion arrived on a world. With the help of [[Gul'dan]], the [[Blood of Mannoroth]] was drunk by the chieftains of the clans. They were engulfed by a demonic [[bloodlust]] that wiped out the [[draenei]] and damned the orcs forever.\r\nHowever, after the Dark Portal was opened and the [[orc]]s engaged the humans over the course of two wars, they were unexpectedly defeated and routed by the humans. The orcs, and in turn, Mannoroth, had failed. Mannoroth, painfully aware of this fact, made plans to have his vengeance.\r\n===The Third War===\r\nKil'jaeden, however, ignored Mannoroth's desires for vengeance, and crafted a new pawn: the [[Lich King]] and his [[undead]] [[Scourge]]. This Scourge would succeed where the orcs had failed.\r\nFinally, Archimonde was summoned by the [[lich]], [[Kel'Thuzad]], to the world of [[Azeroth]]. Mannoroth, eager to finally have his revenge on the night elves and the orcs, followed his master.\r\nThe [[dreadlord]], [[Tichondrius]], gloated openly that the Scourge (whom he regarded as his in the same way Mannoroth felt about the orcs) had succeeded where the orcs had failed. This only enraged Mannoroth further, and he was infuriated to discover that the orcs had left. Mannoroth and Tichondrius, in pursuit, followed [[Thrall]] and the [[Horde]] across the sea to Kalimdor. Archimonde reminded Mannoroth, though, that the orcs could still be a useful tool to them.\r\nUpon arriving in Kalimdor, Mannoroth sensed the presence of Cenarius, and he worried that the [[demigod]] could prove to be a chink in their plans. Tichondrius suggested that perhaps the orcs could be used to destroy Cenarius, for the orc who Mannoroth once corrupted years ago on Draenor, [[Grom Hellscream]], was here, and had incurred the wrath of the demigod. \r\nMannoroth spilled his [[Blood of Mannoroth|blood]] into a fountain of life, defiling it. Hellscream's [[witch doctor]]s, sensing the power, initially led him to the fountain, but quickly realized it was cursed, and implored Hellscream not to meddle with it. Grom ignored them and corrupted his clan by drinking its waters. Infused with the powers of the Legion, Cenarius was no match for the bloodlust filled [[Warsong]] Clan.\r\nWith the demigod dead, Mannoroth appeared and took full control of Hellscream as the true invasion, the ''Legion's'' invasion, of Kalimdor began. Realizing that the remaining orcs were still a formidable force under the leadership of Thrall, Mannoroth formed a new plan to take him out. \r\nThrall found his former friend Grom had fallen under the sway of the legion and vowed to save him. With the help of [[Jaina Proudmoore]] and her expedition, the orc-[[human]] alliance successfully defeated Hellscream's corrupted clan, captured Hellscream, and purged him of his madness. The taint however, was still within him.\r\n===Mannoroth's defeat===\r\nAfter Thrall reclaimed Hellscream, Mannoroth lured them into the craters formed by the falling [[infernal]]s, where he hoped to battle them to the death. Thrall confronted the demon lord in battle pouring all his strength and hatred for the demon into one powerful blast with the [[Doomhammer]]. Mannoroth applauded the effort and revealed that it had caused only a slight scarring of his wing. He then tossed the young war chief against a cliffside with a powerful charge, knocking him out cold and leaving only Hellscream. Mannoroth reminded Grom that he owned his body and soul and gloated that the blood curse could never be broken. \r\nHellscream then faced the choice between giving into the demon corruption once more or resisting and saving Thrall, and indeed his entire race. Refusing to accept that the orcs were cursed forever, he chose his kin. In a heroic last stand Grom slipped past Mannoroth’s defenses and sliced open his chest. \r\nMannoroth was thus slain by his greatest creation and most favored pupil, Grom Hellscream — a fitting irony, some might say. The demonic fires erupted outward, destroying the astonished Mannoroth and mortally wounding Hellscream.\r\nWith the death of Mannoroth the blood curse on the Orcs was finally lifted. After his defeat, Mannoroth's remains and armor were spirited to [[Orgrimmar]] and were attached to a large, irregularly shaped tree (possibly shaped or newly grown by [[tauren]] [[druids]] to accommodate the trophies). However the large double blade used by the mighty pit lord remains in [[Ashenvale]], locked in time to show where the bloodpact was ended. The remains have become a memorial to warn against consorting with [[demon]]s and celebrating the feat of Grommash Hellscream in finally lifting the blood curse.\r\n==Personality==\r\nMannoroth was a simple being with no overriding ambition to change his station in life. Craving blood and carnage over everything else, he willingly acted as an enforcer for Archimonde and the Burning Legion. His only desire was to wage unending war against the mortal races of the universe. He was a terribly efficient weapon of destruction for the demonlords and could always be found at the forefront of their invasion forces. Mannoroth had forever been cursed with an immeasurable, unending thirst for blood. Even the bloodlust of the orcs was a minor compulsion compared to the absolute addiction that bloodletting was for Mannoroth. In the absence of mortals to fight, Mannoroth often turned on his own demon kin, slaying felhounds and infernals with an unnerving sense of satisfaction. He preferred the kill to the chase, and would quickly slay mortals who were unfortunate enough to stumble upon him. Mannoroth sought out the most concentrated area of foes and wades into battle. He was not happy unless he was spilling the entrails of his enemies at his feet. When a victim fell, he usually spent an extra attack or two on the victim making sure the target was quite dead. This could be quite messy, which was exactly how Mannoroth liked it. In fact, he could get a bit reckless if foes were not dropping to his massive two-bladed sword at least every attack.\r\n==Memorable quotes==\r\n*(As Thrall and Grom Hellscream enter the fissure) ''So predictable... I knew you would come... and I see you brought the mighty Hellscream... his blood, is mine...'' (Thrall and Grom turn, to be confronted by Mannoroth) ''As is your whole... misbegotten race!''\r\n*(After blocking an attack from Thrall) ''A worthy effort... but futile.''\r\n*(To Grom Hellscream) ''The boy believed you could be saved... But he didn't know, what burns within your soul... when in your heart, you know, we are the same!''",},
			["Mannoroth the Destructor"] = { content = "#REDIRECT [[Mannoroth]]", redirect = "Mannoroth",},
			["Manor Mistmantle"] = { content = "'''Manor Mistmantle''' is the family stead of the Mistmantle family. It is located in northeastern [[Duskwood]], north of [[Darkshire]] and west of [[Beggar's Haunt]]. The lone survivor of the Mistmantle legacy is [[Stalvan Mistmantle]], a former school teacher and personal tutor who is now an agent of the [[undead]]. The manor grounds are rotten and overrun by Stalvan's [[ghoul]]ish minions. The only sign of life on the property is a single flower in the garden, known as the [[Tear of Tilloa]].",},
			["Manta"] = { content = "'''Manta''', the Behemoth of the Deep, was a creature that was shot with an arrow covered in three drops of a black liquid from a vial. The arrow was used in a crossbow to kill Manta, a creature ten times the size and strength of a dragon. It was believed that, like [[Deathwing]], the Manta was unstoppable.\r\nIt was said that the black liquid was used to kill this beast 100 years ago which is about 90 years before [[Warcraft I]].\r\nSome speculate that Manta was somehow linked to the [[Old Gods]], but chances of that are low since four of the five [[Old Gods]] were chained beneath Azeroth (Possibly 3 now that [[C'thun]] may be dead) and the 5th God was slain with a sword.",},
			["Mantle"] = { content = "#REDIRECT [[Augment]]", redirect = "Augment",},
			["Mantles of the Dawn"] = { content = "== Who==\r\n*[[Quartermaster Lightspark]] in [[Chillwind Camp]] in [[Western Plaguelands]]\r\n*[[Quartermaster Hasana]] in the [[Bulwark]] in [[Western Plaguelands]]\r\n*[[Quartermaster Breechlock]] in [[Light's Hope Chapel]] in [[Eastern Plaguelands]]\r\n==Level of Quest==\r\nLevel 60\r\n==Pre-Requisites==\r\n*Must have Revered reputation with [[Argent Dawn]]\r\n==Task==\r\n'''Bring 10 [[Argent Dawn Valor Token]]s to [[Quartermaster Lightspark]] at [[Chillwind Camp]], [[Western Plaguelands]].'''\r\nor\r\n'''Bring 10 [[Argent Dawn Valor Token]]s to [[Quartermaster Hasana]] at the [[Bulwark]], [[Western Plaguelands]].'''\r\nor\r\n'''Bring 10 [[Argent Dawn Valor Token]]s to [[Quartermaster Breechlock]] at [[Light's Hope Chapel]], [[Eastern Plaguelands]].'''\r\n''Your service to the Argent Dawn is to be commended, <name>. You are truly revered amongst us. I have been authorized to make available for you to purchase one of the Dawn's most valued items - our magic resistance mantles.''\r\n''Application of a mantle to your existing shoulder piece will enhance your resistance to the powers of magic in one of five potential ways. As a sign of continued dedication to our cause, I ask for no less than ten of our valor tokens in exchange for access to these mantles.''\r\n==Reward==\r\nYou can now purchase any of the following:\r\n*[[Arcane Mantle of the Dawn]] (+5 arcane resistance) \r\n*[[Flame Mantle of the Dawn]] (+5 fire resistance) \r\n*[[Frost Mantle of the Dawn]] (+5 frost resistance) \r\n*[[Nature Mantle of the Dawn]] (+5 nature resistance) \r\n*[[Shadow Mantle of the Dawn]] (+5 shadow resistance) \r\n==Notes==\r\nThese are some of the few shoulder enchantments in [[World of Warcraft]]. The other shoulder enchantments are available to those with good reputation with the [[Zandalar Tribe]].\r\n----\r\nGo to [[Quests]]",},
			["Mantle of the Timbermaw"] = { content = "The '''Mantle of the Timbermaw''' is a [[Tailoring]]-crafted shoulder protector that gives a bonus to mana regeneration. This makes it great for [[priests]] and [[druids]] who act as main healer.\r\n==Source==\r\nThe '''Mantle of the Timbermaw''' is crafted by [[Tailoring|Tailors]] with a skill level of 300.\r\nThe components are:\r\n*5 [[Mooncloth]]\r\n*5 [[Essence of Earth]]\r\n*5 [[Living Essence]]\r\n*2 [[Ironweb Spider Silk]]\r\nThe [[pattern]] is a [[Limited Sale Recipe]] sold by [[Meilosh]] in the [[Timbermaw Hold]] in [[Felwood]]. You must have Revered reputation with the [[Timbermaw Furbolgs]] to purchase these plans.",},
			["Manual"] = { content = "== In World of Warcraft==\r\nThe term '''manual''' can mean several things in [[World of Warcraft]]:\r\n* Alternative term for a [[recipe]] book or an [[ability]] or [[skill]] book.\r\n* There are a few equipable items also called manuals.\r\n* Many other items have \"operating manual\", \"owner's manual\", \"user's manual\", or something like that in their name.\r\nAll [[First Aid]] books are called manuals, but some ability or skill books are manuals also.\r\nFirst Aid manuals:\r\n* Manual: Heavy Silk Bandage\r\n* Manual: Mageweave Bandage\r\n* Manual: Netherweave Bandage\r\n* Manual: Heavy Netherweave Bandage\r\n* Manual: Strong Anti-Venom\r\nAbility or skill manuals:\r\n* Manual of Battle Shout VII ([[Warrior]])\r\n* Manual of Eviscerate IX ([[Rogue]])\r\n* Manual of Heroic Strike IX ([[Warrior]])\r\n* Manual of Revenge VI ([[Warrior]])\r\nOther manuals:\r\n* Manual of Engineering Disciplines (Quest item)\r\n* Manual of the Nethermancer (Off-Hand item)\r\n==Warcraft Manuals==\r\nWoWWiki has excerpts of game manuals for some Warcraft games prior to World of Warcraft.\r\n===Warcraft: Orcs & Humans===\r\n* [[Chronicles of the War in Azeroth]]\r\n* [[The Destiny of the Orcish Hordes]]\r\n* The [[Azeroth Army of the First War]]\r\n* The [[Orcish Horde of the First War]]\r\n* [[Creatures of the Land]]\r\n===Warcraft II===\r\n [[Warcraft II: Tides of Darkness]]\r\n[[Warcraft II manual|Mostly complete full version]]\r\n* [[Legends of the Land (Azeroth)]]\r\n* [[Places of Mystery]]\r\n* [[A Brief History of the Fall of Azeroth]]\r\n* [[The History of Orcish Ascension]]\r\n* [[Nations of the Alliance]]\r\n* [[Clans of the Horde]]\r\n [[Warcraft II: Beyond the Dark Portal]] (expansion)\r\n* [[The Aftermath of the Second War]]\r\n* [[Legends of the Land (Draenor)]]\r\n* [[Clans of Draenor]]",},
			["Manual of Engineering Disciplines"] = { content = "The '''Manual of Engineering Disciplines''' is provided for and objective of:\r\n* Goblin Engineering\r\n* Gnome Engineering",},
			["Manual of Eviscerate IX"] = { content = "'''Manual of Eviscerate IX''' teaches rogues the 9th rank of [[Eviscerate]]. It can only be obtained from a drop, but may be traded.\r\n==Source==\r\nManual of Eviscerate IX drops from Blackhand Assassins in [[Upper Blackrock Spire]].\r\n==Notes==\r\nAs of [[Patch 2.0.1 Release Notes|Patch 2.0]], Eviscerate (rank 9) can be learned from any rogue trainer at level 60.",},
			["Manual of Monsters"] = { content = "The ''Manual of Monsters'' is a source book for the [[Warcraft RPG]] and was published in 2003. It contains descriptions and game statistics for a large number of creatures that inhabit the Warcraft setting. As the book was published before the release of [[World of Warcraft]] it only covers a few creatures that were introduced in the [[MMORPG]], and mostly covers material from RTS series.\r\nThe book is out of print. However it can still be obtained in PDF format. A new creature source book for the Warcraft RPG was released on February 7th, 2007, called the [[Monster Guide]]. It covers new creatures that appear in the WoW MMORPG and updates some of the creatures from the Manual of Monsters with new game statistics and rules of the new edition of the World of Warcraft RPG. \r\nChris Metzen was one of the co-authors on the book, as well on the \"Design Assistance and Additional Material\" staff for the book.\r\nAlso see:\r\n* \r\n==Chapter One: Creatures of Azeroth==\r\n==Chapter Two: The Burning Legion==\r\n* [[Doomguard]]\r\n* [[Dreadlord]] (Nathrezim)\r\n* [[Eredar]] Warlock\r\n* [[Felguard]]\r\n* Fel Stalker\r\n** Fel Hunter\r\n* [[Infernal]]\r\n* [[Pit Lord]]\r\n* [[Fel|Tainted]]\r\n==Chapter Three: The Undead Scourge==\r\n* [[Abomination]]\r\n* [[Banshee]]\r\n* [[Crypt Fiend]]\r\n* [[Dire Gargoyle]]\r\n* [[Forsaken]]\r\n* [[Ghost]]\r\n* [[Ghoul]]\r\n* [[Lich]]\r\n* [[Shade]]\r\n* [[Skeletal Mage]]\r\n* [[Skeletal Warrior]]\r\n* [[Withered]]\r\n* [[Wraith]]\r\n* [[Zombie]]\r\n==Appendix One: Animals and Vermin==\r\n* [[Dire bear|Bear, Dire]]\r\n* [[Carrion Beetle]]\r\n* [[Elk]]\r\n* [[Spider]]\r\n** [[Forest Spider]]\r\n** [[giant spider|Giant Spider]]\r\n** [[Venom Spider]]\r\n* [[Storm Crow]]\r\n* [[Tallstrider]]\r\n* [[Wolf]]\r\n** [[Dire Wolf]]\r\n** [[Giant Wolf]]\r\n** [[Timber Wolf]]\r\n==Appendix Two: Villains of Warcraft==\r\nIn Appendix Two the book also contains descriptions and game statistics for the following major villains of the Warcraft universe:\r\n* [[Azgalor]]\r\n* [[Illidan Stormrage]]\r\n* [[Kael'thas Sunstrider|Prince Kael'thas Sunstrider]]\r\n* [[Kel'Thuzad]]\r\n* [[Lich King|The Lich King]]\r\n* [[Sylvanas Windrunner]]\r\n* [[Lady Vashj]]\r\n==Appendix Three: Other Monsters in Warcraft==\r\nFinally, Appendix Three contains original lore for monsters and creatures adapted into the Warcraft Setting from other d20 books (''Monster Manual v3.5'', ''Creature Collection Revised'', ''Creature Collection II: Dark Menagerie'' and ''Tome of Horrors''). According to the book the updated lore takes precedence over descriptions found in the previous non-Warcraft books. The section also contains information on how to incorporate other monsters into a campaign for the Warcraft RPG. The background lore could be used by someone who wanted to include the monsters in their campaigns.\r\n\"Other Monsters in Azeroth... Some creatures in Manual of Monsters are similar to the described in the MM-centaur, dragons, [[elemental]]s, [[golem]]s, and so on. In some cases the MM descriptions are suitable for use as-is, such as for elementals. Under circumstances, the creature receives no listing in the Manual of Monsters. In other cases, monsters are different enough in their ecology or abilities to require a new description here. When a creature is listed in the Manual of Monsters with the same one as the MM, the description in this book takes precedence for a Warcraft campaign. The same is true for an animals or vermin particular to the world of Azeroth, as described in Appendix One. In the case of identical types of animals the ones in the Manual of Monsters takes precedence.\r\nMany of these creatures are unique, and have not appeared in previous Warcraft video games (although a few like \"[[floating eye]]s\", \"[[shadow]]s\", \"[[bone golem]]s\", \"[[shadow demon]]s, [[forest walker]]s\" have been incorporated later). A few entries ([[wyvern]], [[dryad]], [[centaur]]) seem at first glance to contradict other known lore on the subject, however the book explains that they are unique, or a rare variations of those creatures.\r\nAlso, its notable that Appendix III expands upon creatures that were referenced in other chapters, appendixes, and sections of the book, for example [[mite]]s, [[nymph]], [[shambling mound]]s and [[wight]]s. Some sections from the 3rd appendix such as articles about [[hag]]s, centaurs in the eastern kingdoms, [[elemental]]s, [[giant eagle]]s, [[sprite]]s, [[nymph]]s, [[half-ogre]]s, [[devourer]]s, [[wight]]s, elemental [[salamander]]s etc, have been referenced or expanded upon in later sources. The article about the gargoyle (a non-dire version), elementals, eastern centaurs, etc, were derived and expand upon ideas made in previous Warcraft games.\r\nAppendix III is not the only Warcraft source to establish original Warcraft related back stories to creatures from the DnD MM, and other non-Warcraft sourcebooks. Some of the earlier chapters in the Manual of Monster's incorporated a few creatures not included in Appendix III, including references to [[darkmantle]] and [[girallon]]. Even more original creatures were established in other Warcraft sourcebooks including [[Lands of Conflict]], [[Shadows & Light]], [[Magic & Mayhem]], [[World of Warcraft The Roleplaying Game]], and [[Monster Guide Web Supplement]]. A few examples include, [[dire lion]]s, [[lizard familiar]]s, and steam [[mephit]]s in the story, \"[[Dark Iron Chains]]\" that [[Brann Bronzebeard]] recounts in [[Lands of Conflict]].\r\nThe appendix was split into several sections which sometimes included a small background explanation on how the material related to biology or history of Azeroth. The following is a listing of some of these quotes;\r\nThe Kaldorei count many more allies than have been documented so far. Amongst these allies are several species from the Tome of Horrors by Necromancer Games. Some are ancient allies, others newly recruited (or reclaimed) allies, befriended by the night elves in the wake of their lost immortality. The minions of the Burning Legion are countless, yet below is a list of shock troops, animal cohorts, and generals alike. In addition to quilboar, tauren, elves, and orcs, other sapient species populate the world of Azeroth. Three of them are described in the Tome of Horrors. Orcs and goblins are not the only [[goblinoid]]s on Azeroth. Some of the previously unknown species are crossbreeds, while others seem to be races unto themselves. Three of these species are discussed briefly below. The diversity of animal life on Azeroth is limitless. In addition to the creatures described elsewhere in this book, several species described in the Tome of Horrors can also be found on Kalimdor and throughout Azeroth. In addition to the diversity of life on the surface of Kalimdor, the seas of Azeroth are also teeming with life. Much of this life is mundane, if monstrously large, though the sea has her secrets-- and threats. The following aquatic creatures listed in the Tome of Horrors can be found in the rivers, lakes and oceans in around Kalimdor.\r\n==Monsters Ranked by Challenge Ratings==\r\nThe final section is a table showing a variety of monsters how much of a challenge they are, and what classes they tend to be.\r\n==Appendix III Controversy==\r\nAppendix III has some controversy surrounding it by the fans. Although some material from Appendix III has made it into other sources, this does not necessarily mean that all the material will make it into future sources. Even though some of the material has made it into other sources; it is the opinion of some of freelance writers and editors of the RPG line, and many of the fans that Appendix 3 is not considered canon. However, the rpg staff involved has admitted that their opinion is their own, and does not represent [[Blizzard Entertainment]]. Blizzard has never officially given their stance on the issue.",},
			["Manufactory"] = { content = "The '''Manufactory''' is located inside [[Blackrock Depths]] and is accessible from the [[West Garrison]]. It is the location of numerous [[gnome]] technicians who assemble the parts for the [[golem]]s that have been carved in the [[Hall of Crafting]] before they are sent to the [[Mold Foundry]]. \r\nThe Manufactory's most notable inhabitant is the cruel [[Golem Lord Argelmach]] who oversees the production and assembly of these magical machines. This area leads on into [[the Grim Guzzler]], [[Shadowforge City]]'s famed tavern.",},
			["Map"] = { content = "''Were you looking for [[Maps]] of places in the [[World of Warcraft]]?''\r\nIn [[World of Warcraft]], this usually refers to the World Map accessible from a globe button on the [[Mini-Map]], in the very top right corner (or using the default key shortcut: '''M''').\r\nSometimes people use this term when referring to the [[Mini-Map]].\r\n====Map Features====\r\n'''Explored areas''':\r\n* Any areas of the map your character has \"Discovered\", will appear with details (buildings, cave entrances, etc).\r\n'''Character locations''':\r\n* Your character: Your character will appear on the map at the location as a <font color=\"#CCCCBB\">grey</font> arrow, pointing at your direction.\r\n* Party members: If your character is in a party, any party members will appear on the map at the location as a <font color=\"gold\">gold</font> dot.\r\n===UI Mods===\r\n[[Atlas (AddOn)|Atlas]] is a UI mod that grants access to maps that would normally not be available in-game. The package includes maps for all the instances, flight path maps and more. Be wary that those maps are NOT interactive (i.e. you cannot see your current position nor your teammates').\r\n is a UI mod that allows the user to view the entire minimap of both continents. Features include panning, zooming, player tracking and functionality with CT_MapMod mapnotes.\r\n===On the web===\r\n is a -based map of all of Azeroth. You can activate location names, zone names, travel paths, as well as the resources found in each region. Very useful for farming ore, herbs, etc.",},
			["Maple Seed"] = { content = "'''Maple Seed''' is needed by druids to give [[Rebirth]] (Rank 1) to dead allies.\r\n==Source==\r\nThis item can be purchased from all reagent vendors in unlimited supply for 2 silver .\r\n===[[Enchanting]]===\r\n* [[Minor Wizard Oil]]\r\n* [[Minor Mana Oil]]",},
			["Maps"] = { content = ":''Were you looking for the in-game [[Map]]?''\r\nUseful and interesting '''maps''' relating to [[World of Warcraft]] and the general Warcraft universe.\r\nFor details on individual zones:\r\n* [[:Category:Zones|Zones category]]\r\n* [[List of regions]]\r\n===Official sites===\r\n* -interactive on the \r\n** at \r\n** at \r\n** at \r\n==WoWWiki==\r\n* () - Overview maps of Outland and Azeroth from in-game.\r\n* - Azeroth in-game.\r\n* - Outland in-game.\r\n===Other locations===\r\n* '''''' - \"satellite\" maps, displaying a bird's-eye view of the entire land, with labels for all the sub-zones.\r\n* '''''' with transport fees and detailed maps for the starting zones.\r\n* '''''' and '''''' using the Google Maps API. Presents an ultra-high detail scalable map of the World of Warcraft universe using the same interface as Google Maps, and includes more than 15,000 herb, ore, and treasure locations. \r\n* '''''' (use to show specific locations to your friends).\r\n* '''''' at .\r\n* [[Fansites|WoW.Stratics.com]] '''''' of Azeroth and Outland including [[Instances]] and [[Battlegrounds]].\r\n* '''[[WorldOfWar.net]] '''\r\n** '''''' (high resolution map with flight routes and more info).\r\n** '''''' (high resolution map with flight routes and more info).\r\n** '''''' (high resolution map with flight routes and more info).\r\n*** ''''''\r\n* '''WoWCartographe''' - a map program with annotations (/, Windows only).\r\n* '''WoWMapper''' - An indoor and outdoor minimap generator. (/, Windows only).\r\n* '''''' at WorldofWarcraftStuff.com (create or view maps e.g. , or )\r\n* '''''' - complete interactive mapping system with locations, quests, items, crafting materials and flight routes. (Burning Crusade and WoW Classic) Linking function to '''''', the German WoW Database.\r\n==Regional and City Maps==\r\n* below indicates '''''' at [[WorldOfWar.net]] (with extra detail).\r\n===[[Kalimdor]] Regions===",},
			["Map coordinates"] = { content = "'''Map coordinates''' are numerical references to locations on the WoW maps. You can display your coordinates with many [[AddOns]]. They are also called '''tloc''', an abbreviation for \"[[Thottbot]] location\". It consists of a set of x/y coordinates, which is two numbers ranging from 0 to 100, representing a location on the current [[zone]] map.\r\n* '''0,0''' represents the top left corner\r\n* '''100,0''' represents the top right corner\r\n* '''0,100''' represents the bottom left corner\r\n* '''100,100''' represents the bottom right corner\r\n* '''50,50''' is the exact center of the map\r\n[[Cosmos]] users can show their current position under the minimap by typing <tt>/mntloc</tt>.\r\nVarious other [[AddOns]] are also capable of displaying your current location. Examples include:\r\n*[[Titan Panel]]\r\n*[[Map Notes]]\r\n==Checking coordinates without addons==\r\nIn-game, simply copy the following:\r\n /script SetMapToCurrentZone() local x,y=GetPlayerMapPosition(\"player\") DEFAULT_CHAT_FRAME:AddMessage(format(\"%s, %s: %.1f, %.1f\",GetZoneText(),GetSubZoneText(),x*100,y*100))\r\nGo into the game, open a chat box, paste, hit enter. Your present coordinates for the zone will appear in the default chat frame. This code can also be placed in a [[macro]].\r\n==Showing coordinate locations in WoWWiki==\r\nYou can use the templates and to indicate locations on a map using the map coordinates.\r\n===Tooltip===\r\nYou can also add coordinates (with a map tooltip), as a note, to an item or NPC using :\r\nExample: The Rokk",},
			["Mar'li"] = { content = "#REDIRECT [[High_Priestess_Mar'li]]", redirect = "High_Priestess_Mar'li",},
			["Marapor"] = { content = "The '''Marapor cultists''' are a demon cult which resides along the coast region of [[Desolace]]. They have a brand in the shape of a six-sided star hidden under the hair on their scalp. Perhaps one of the myriad [[Shadow Council]] cults.",},
			["Marauder"] = { content = "'''Marauders''' are a breed of morally suspect fighters sometimes associated with [[pirate]]s. Their distinctive feature is they like to loot and pillage, often in roving packs.\r\n==In World of Warcraft==\r\nIn [[World of Warcraft]], most marauders are not associated with pirates. The [[kolkar]] and [[naga]] usually have marauders among them.\r\n* Rotlimb Marauder\r\n* Wrathscale Marauder\r\n* Kolkar Marauder\r\n* Galak Marauder\r\n* Gelkis Marauder\r\n* Magram Marauder\r\n* Maraudine Marauder\r\n* Daggerspine Marauder\r\n* Ghostly Marauder\r\n* Spectral Marauder\r\n* Twilight Marauder\r\n* Twilight Marauder Morna\r\n* Bonechewer Marauder",},
			["Maraudine"] = { content = "#REDIRECT [[Maraudine clan]]", redirect = "Maraudine clan",},
			["Maraudine clan"] = { content = "'''Tribe Color''': Purple\r\n'''Founding Khan''': [[Maraudos]]\r\n'''Current Khan''': [[Khan Hratha]]\r\nThe tribe of [[centaur]] founded by [[Maraudos]]. One of five main tribes of centaur, they occupy and maintain the temple of [[Maraudon]], a shrine to their ancient [[Khan]] and the procreators of the centaur in [[Desolace]].",},
			["Maraudon"] = { content = "'''Maraudon''' is a system of caves located in the [[Valley of Spears]], north east of [[Shadowprey Village]], in [[Desolace]]. It is a combination of ancient [[centaur]] burial grounds, as well as a primal temple dedicated to the elemental earth. The enemy level range lies at 45-51 (44-48 after [[Patch 2.3]]) and the instance portal will block out all adventurers under 35. Maraudon was added in [[Patch 1.2]], was the first [[instance]] to be added after the release of [[World of Warcraft]], and is the first of only three 5-man instances to be added in a patch (the others being [[Dire Maul]] and [[Magisters' Terrace]]).\r\n==History==\r\nMaraudon is a holy place to the centaur — it is the tomb of Zaetar, keeper of the grove and son of [[Cenarius]], and the house of Princess Theradas, an earth elemental. Zaetar rejected his Keeper heritage when he joined with the princess of the chaotic earth elementals, Theradras. Their unholy union gave birth to the misshapen and cursed centaur, who promptly slew their father for his part in their misbegotten creation. Fearful of Cenarius' wrath, the grief-stricken Theradras sequestered her dead lover's body in her secret sanctuary, the Crystal Caverns of Terramok, where she watches over him to this day. Travelers who come to Desolace have little trouble spotting Zaetar's tomb, for the blessing of nature that permeates his being transformed his resting place into a verdant paradise of flora and tranquil pools. Today, this tomb is now trodden by the hooves of Zaetar's children, who have claimed this great cavern as their sacred stronghold Maraudon.\r\nWithin the tomb is a maze of underground caves and tunnels, populated by the spirits of the long-dead centaur khans. Earth elementals, basilisks and rock borers also inhabit the site. It is rumored that satyrs and other emissaries of the Burning Legion have moved into these caverns as well.\r\nAlthough each of the five [[centaur]] tribes known as Black tribe, Brown tribe, Green tribe, Red tribe, and Yellow tribe maintained its own stronghold elsewhere in Desolace, this was once the region's capital (shortly after the [[Battle of Mount Hyjal]]), when there were no other cultures of any note in all of Desolace. At that time the centaur had run all others down in their unceasing lust for conquest. However, now that Desolace has no affiliation, and members of other civilizations have moved back in, it is only one of several major settlements. Desolace no longer has a capital.\r\nMaraudon has a vast gathering of palatial tents surrounded by a palisade, the [[Valley of Spears]], it once served as a cultural center and meeting place for all centaur. However, in recent times many of centaur tribes are at war, and now it is inhabited only by the [[Maraudine]] clan. They are the protectors of Maraudon, and only the bravest and mightiest of the tribe's warriors are chosen to guard the tomb of Zaetar.\r\nBehind a series of spiked barriers in the center of this mesa stands '''[[Terramok]]''', an ancient [[titan]] vault, rumored to hold Theredras, former princess of the vile earth elementals and legendary mother of the centaur race. Some even claim that Theradras guards the tomb of her husband, the Keeper of the Grove killed by the first khans. The only permanent centaur resident is [[Krullaran the Prophet]]. The centaur of Desolace turn to the khans for protection, but they look to Krullaran for guidance. Many believe he communes with the titans and possesses insight to the glorious return that the centaur will someday make to the northern lands. The name Maraudon may come from [[Maraudos]].\r\n''Protected by the fierce Maraudine centaur, Maraudon is one of the most sacred sites within Desolace. The great temple/cavern is the burial place of Zaetar, one of two immortal sons born to the demigod, Cenarius. Legend holds that Zaetar and the earth elemental princess, Theradras, sired the misbegotten centaur race. It is said that upon their emergence, the barbaric centaur turned on their father and killed him. Some believe that Theradras, in her grief, trapped Zaetar's spirit within the winding cavern - used its energies for some malign purpose. The subterranean tunnels are populated by the vicious, long-dead ghosts of the Centaur Khans, as well as Theradras' own raging, elemental minions.''\r\n====Pre-instance====\r\n \r\n==Quest guide==\r\n'''Note''': the last two quests (The Scepter of Celebras and Seed of Life) are obtained ''after'' you enter the dungeon itself. Also, Legends of Maraudon is found in the Maraudon area but before you go through the portal, in the pre-instance area.\r\n===Pariah Quest===\r\nYou need to do the following:\r\n* Kill The Nameless Prophet at the start of the dungeon. Get the amulet.\r\n* Find the five khans. Use the amulet on each. Kill them and loot the gem.\r\n* Use one of the gems\r\n* Return to the Pariah\r\nThe khans are found in these areas: \r\n*Middle area = 1st \r\n*Purple area = 2nd \r\n*Orange area = 3rd \r\n*Purple instance = 4th \r\n*Orange instance = 5th \r\nBasically, if you do everything else, you'll find all of them.\r\n==Guide==\r\nThis is a quick guide to doing the [[Maraudon]] [[instance]] for [[Alliance]] characters. [[Horde]] information has been added where possible.\r\n===Quick Run Down===\r\nMaraudon can be split into several sections. At the start of the dungeon, you'll kill the mobs without blinking. You will eventually find an area with purple glowing rocks on the left, orange on the right. There is also a central entrance which takes you to the Princess, but you can't do that at first. Following the rocks, you enter an orange area or purple area, which lead to orange and purple entrances to the instance.\r\nYou can do Orange or Purple Maraudon at level 45 or 46. On the other hand, the Princess requires at least a couple of level 50's. I can't emphasize this enough: take a Mage. There are a lot of points where you get attacked by a lot of non-elites, and [[AoE]] attacks are vital. (Ironically, the place they're needed least is on killing the Princess, but I'd still advise one even there.)\r\nNote: At least since patch 2.3 Princess is now level 48 and doesn't seem to spawn any adds anymore and you won't need to be level 50 (the whole instance is advised 43-48)\r\n===Orange Side===\r\nThe big pools aren't lava, they're water. Jump into one and fill your vial for [[Quest:Vyletongue Corruption|Vyletongue Corruption]]. Talk to Cavindra. Kill the Khan and go into the instance.\r\nThere are small plants dotted around. They're not selectable. Use the filled vial near them and you'll get attacked (quite viciously). Killing each assailant purifies one plant. If you systematically clear the place you'll get 8 plants on the way to Noxxion. Every group member will get credit for the plant purification, regardless of who used the vial on the plants.\r\nA couple of notable things: the bright green [[Creeping Sludge]] move very slowly and hit very hard - usually for 200-300 damage per hit, so its best to stay out of melee range, with a tank kiting them, and have your ranged DPS take them out one at a time. These aren't very difficult to kite around since they do move very slowly. A few tips:\r\n*Melees should only attack mobs that are nearly dead\r\n*Ranged attackers should unload everything they got and kite. Arcane Missiles are really useful here.\r\n*Anyone with a slowing attack (including Mind Flay) should unload it on the leading mob.\r\n*It is possible to run away from these things forever. As long as you run in a circle. In the middle of a very bad battle, I saw a paladin get seven of these to follow him around the instance. We picked them off one at a time and prevented the wipe.\r\nYou've got to kill Noxxion for [[Quest:Legends of Maraudon|Legends of Maraudon]]. About halfway through he will split up and spawn some non-elite elementals and will re-form after you've killed them.\r\nAfter Noxxion, you can leave or push forward. There's one more boss () with a couple of good drops, and then Celebras. There's no point in doing Celebras without both the rod and the diamond.\r\n===Purple Side===\r\nAfter 2.3 [[Shadowshard Fragments]] is now solo-able and involves killing lvl42-ish rock elementals outside of the instance. The good news is you only need to kill 10.\r\nInside is a very easy instance that drops a lot of green AH fodder. Vyletongue himself has four stealthed guards. Two of them can be pulled without aggroing him. He's easy, anyway. He drops the other piece of what you will need to create the Staff of Celebras.\r\nDo note, however, that the Satyrs can gouge your tank, which can be disastrous if you aren't prepared.\r\nYou'll notice that there's a lot of information about the orange side and not very much about the purple side. That is, quite simply, because the purple side is very easy in comparison.\r\n===Celebras===\r\nYou get to him either by pushing on in the orange or purple sides. A bit of an insane battle because he keeps summoning non-elites. A lot of AoE is the only way to go here.\r\nAfter that (assuming you have the rod and diamond from Noxxion and Vyletongue), talk to him repeatedly and complete the sceptre quest. No more monsters will appear, so this bit is completely safe.\r\nPhew, now you're halfway through the instance. If you push on, you'll fall into a big lake.\r\n===The Princess===\r\nIf you've got the sceptre, you can go through the central part right at the start, use the sceptre and you will fall into the big lake mentioned in the Celebras section. This area is full of interesting bosses to kill, but they're all pretty easy apart from the Princess. The ordinary mobs present more of a challenge:\r\n*The basilisks in this area silence all the time. Casters should stand much further back than they usually do.\r\n*The rock elementals splinter and produce non-elites. AoE is very effective. Aggro management is essential if you don't want to kill your healers.\r\nThere are a lot of patrols. Always wait for them, because they'll wipe even a good group very fast. The worst is that you can get pincered at T junctions by patrols going different ways.\r\nThe princess herself is a level 48 elite, but has a kick like a mule. She has two main notable attacks. She fears melees quite a lot and has a large range AoE attack. Nature protection potions are extremely useful here. If your party is underlevelled, make sure you buy some before going after her. Although fast, she's very kitable. As long as you can stay away from her, a hunter or mage can pound away without difficulty. A good way of maximizing that is to actually have your ranged casters on opposite sides of her, although this can obviously cause problems for your healers. '''Important:''' Make sure you're not close to the edges, or else you can get knocked off and down into the river below.\r\nHaving killed her, you'll get a quest called the [[Quest:Seed of Life|Seed of Life]]. You need to get to [[Moonglade]] to do that, which involves grinding reputation with the [[Timbermaw Furbolgs]], but that's another story... (An alternative quick way to get to [[Moonglade]] is to swim North of [[Darkshore]] until you get a notice that you are entering [[Moonglade]] waters. Then drown, and you will be taken to the [[Moonglade]] cemetery. Rez at the spirit healer, and you will be in [[Moonglade]]!) Of course, Druids are exempt from doing any of these since they can simply teleport themselves to [[Moonglade]].\r\n===Other Interesting Bosses===\r\nFor details of the items these mini-bosses drop, see [[Maraudon loot]].\r\nA few other bosses need a mention as they drop blue items. Some, of course, are more interesting than others.\r\n[[Rotgrip]] can be found by jumping off the waterfall after you kill the Princess.He's a big crocodile that hits pretty hard but otherwise is pretty straightforward. You may want to pull him to surface to eliminate problems with breathing underwater.\r\n[[Tinkerer Gizlock]] you can do by going up, past Zaetar's Grave, and clearing some non-elite snake clusters. He has a channeled fire attack that you can back away, but otherwise is straightforward.\r\n[[Landslide]] is up in the central cavern, after you climb up several ramps and fight off a patrol and several stationary guards. He's tricky in that he summons additional non-elites rock fellows, but they all spontaneously combust if you kill Landslide, so kill Landslide as soon as possible while distracting the little guys. Also, he occasionally has an AoE stun attack which can be annoying.\r\n[[Meshlok the Harvester]] is a rare spawn between the orange and purple zones who drops some very nice rogue/hunter armor. He is a little bugged and sometimes will be hard to see without using a \"/target Meshlok\" macro. He can be soloed by a skillful 49-52 rogue on a stealth run (bring some free action potions to prevent getting stunned).\r\n==Useful resistances==\r\nJust about everything in '''Maraudon''' uses [[nature]] spells or [[poisons]]. Equipping gear with good [[nature resistance]] isn't necessary but will make your life easier. [[Hunter]]s are very beneficial in this instance thanks to their [[Aspect of the Wild]] which gives all group members an extra 45 nature resistance.\r\nAgainst the princess, [[shadow resistance]] is helpful for the [[tank]]s to prevent the [[Fear]] effect. Once again, this is handy but not necessary. If you have a [[priest]] in the party with [[Fear Ward]], this may also be useful applied against all of the party or just the tanks.\r\n==Resources==\r\nHerbs:\r\n* [[Blindweed]]\r\n* [[Ghost Mushroom]]\r\nOre:\r\n* [[Gold Vein]]\r\n* [[Mithril Deposit]]\r\n==Dungeon Denizens==\r\n* [[Basilisk]]s\r\n* [[Bog beast]]s\r\n* [[Centaur]]s\r\n* [[Crocolisk]]s (one, at least)\r\n* [[Diemetradon]]s\r\n* [[Dryad]]s\r\n* [[Earth elemental]]s\r\n* [[Frog]]s\r\n* [[Ghost]]s\r\n* [[Goblin]]s (one, at least)\r\n* [[Grell]]s\r\n* [[Hydra]]s\r\n* [[Lasher]]s\r\n* [[Maggot]]s\r\n* [[Mountain giant]]s\r\n* [[Ooze]]s\r\n* [[Roach]]es\r\n* [[Satyr]]\r\n* [[Schools of Fish]]\r\n* [[Snake]]s\r\n* [[Treant]]s\r\n* [[Turtle]]s\r\n* [[Water elemental]]s (one, at least)\r\n* [[Worm]]s\r\n==Notes, Tips, & Additional Info==\r\n* It is pronounced: Mara - dawn\r\n* Lesser bosses: Noxxion (a poison elemental), Razorlash (a [[lasher]]), Lord Vyletongue (a [[satyr]]), Meshlok the Harvester (a rare-spawned [[Bog Beast|bog beast]]) and Celebras the Cursed (a [[Keepers of the Grove|Keeper of the Grove]])\r\n* Pre-end boss: Landslide, a bigger [[mountain giant]]\r\n* End boss: Princess [[Theradras]]\r\n* Post-end bosses: Rotgrip (a [[crocolisk]]) and Tinkerer Gizlock (a [[goblin]])\r\n* If you /camp (note that this boots you from your group) behind the final Keeper of the Grove spirit (after defeating Princess Theradras) and then log back in, it's possible to appear inside of the orange side of the instance and avoid having to hearth (since it's not possible to run out). Note that it may not work, leaving 1 group member stuck inside.\r\n* Maraudon does not get many groups anymore, biggest reason being that most people do not have a flight path to Desolace. This may be because most people between levels 30-39 head to [[Stranglethorn Vale]] instead of levelling in Desolace. Other reasons are that the instance is too far to get to even though it's possible to get there from [[Feralas]]. The instance itself is also very long to go through.",},
			["Maraudon loot"] = { content = "This is a page listing loot to be found in [[Maraudon]]. For information about the instance itself, see [[Maraudon]].\r\n__TOC__\r\n===Outside the Instance===",},
			["Maraudon NPCs"] = { content = "The following [[NPC]]s can be found in [[Maraudon]].\r\n=== Neutral===\r\n* Cavindra\r\n** Legends of Maraudon\r\n* Celebras the Redeemed\r\n** The Scepter of Celebras\r\n* Elder Splitrock ([[Lunar Festival]])\r\n** Splitrock the Elder ([[Lunar Festival]])\r\n* Zaetar's Spirit\r\n** Seed of Life",},
			["Maraudos"] = { content = "<!---->\r\n'''Maraudos''' <The Fourth Khan> is a level 46 [[elite]] [[undead]] [[centaur]] found in [[Maraudon]] in [[Desolace]]. He manifests when the [[Amulet of Spirits]] is used on the [[Spirit of Maraudos]].\r\nMaraudon could be named after Maraudos.\r\nNote, [[Blizzard]] has made an in-game typo in the titles of the five [[khan]]s. ''<The Nth Kahn(sic)>''\r\n==Quests==\r\n*The Pariah's Instructions",},
			["Marcel Dabyrie"] = { content = "'''Marcel Dabyrie''' is a level 34 [[human]] found in the [[Arathi Highlands]]. Marcel lives with [[Fardel Dabyrie]] and [[Kenata Dabyrie]] at the [[Dabyrie's Farmstead]]. [[Genavie Callow]] wants their heads.\r\n==Abilities==\r\n*[[Defensive Stance]]\r\n*[[Shield Bash]]\r\n*[[Shield Wall]]\r\n==Quests==\r\n*To Steal From Thieves\r\n==Loot==\r\n*Marcel's Head ''(Quest Item)''",},
			["Marcus Auralion"] = { content = "'''Marcus Auralion''' is a level 73 humanoid located at [[Crimson Watch]] in [[Shadowmoon Valley]].\r\nHe ends the following quest:\r\n*The Journal of Val'zareq: Portends of War\r\nand begins the following quest:\r\n*Battle of the Crimson Watch\r\nIn both quests, he is listed as \"Crystal Prison\".\r\nJudging by his title, Auralion was the commander of the Sha'tar forces under [[Xi'ri]] that laid siege to [[Illidan Stormrage]]'s [[Black Temple]]. He appears to have been captured and imprisoned in one of the fel crystals near the Path of Conquest by members of the Crimson Sigil - the elite blood elf guard of the Betrayer. After killing a member of the Sigil, Val'zareq the Conqueror, and taking his journal, the player is directed to speak with Auralion in his crystal prison, where he then directs the player group to destroy the Crimson Sigil.\r\n==Name==\r\nThe High General appears to be named after [[wikipedia:Marcus Aurelius|Marcus Aurelius]] (121-180), the last of the \"Five Good Emperors\" of the Roman Empire.",},
			["Marcus Redpath"] = { content = "'''Marshal Marcus Redpath''' (\"Marshal Redpath\") is a level 41 [[quest giver]] located in [[Southshore]] in the [[contested]] territory of [[Hillsbrad Foothills]].\r\nHe starts the following quests:\r\n* Farren's Proof\r\n* Crushridge Bounty\r\n* Crushridge Warmongers (Elite)\r\nSee [[List of Hillsbrad Foothills NPCs]].\r\n==Background==\r\nMarcus Redpath was the headman of Southshore prior to the onset of the [[Second War]], greeting [[Anduin Lothar]], [[Khadgar]], and the refugees from the [[Kingdom of Stormwind]]. He sent his fastest rider, [[Willem]], to [[Terenas Menethil II|King Terenas]] to alert him to their arrival.\r\nHe is possibly related to [[Joseph Redpath|Joseph]] and [[Carlin Redpath]].\r\nHe might have been the Redpath briefly mentioned in the quest [[Quest:Daelin's Men|Daelin's Men]], which would have made him a member of the Theramore city guard at some point.",},
			["Mardenholde"] = { content = "#REDIRECT [[Mardenholde Keep]]", redirect = "Mardenholde Keep",},
			["Mardenholde Keep"] = { content = "'''Mardenholde Keep''' is the fortress keep within the town of [[Hearthglen]], currently held by the [[Scarlet Crusade]]. It is the location of [[Highlord Taelan Fordring]], and is heavily guarded by soldiers of the Scarlet Crusade.\r\nBefore the destruction of the [[Third War]] and the rise of the Scarlet Crusade, Mardenholde was the seat of Lord [[Tirion Fordring]], the governor of the [[Alliance]] principality of Hearthglen. It was a bustling center of regional commercial activity and was one of the bastions of the Alliance that never fell to the [[orcs]] during the war. Although the keep is still intact, it's original image as a bastion of hope has long since been destroyed.",},
			["Marduk Blackpool"] = { content = "'''Marduk Blackpool''' is a level 58 [[elite]] [[named]] [[Death Knight]] [[Scourge]] in [[Scholomance]].\r\n==Background==\r\n'''Marduk Blackpool''' is a brutal warlord of the [[Scourge]], also known as \"Marduk the Black\". Amongst his many campaigns against the humans of [[Lordaeron]], he cut a swath through their forces at the Battle of [[Darrowshire]] causing great death and suffering with his foul, rune laden sword. \r\nMarduk's involvement in the Battle of [[Darrowshire]] was corrupting [[Joseph Redpath]] (Captain Redpath) and many other members of the Redpath Militia to ensure the defeat of the Defenders of Darrowshire.\r\nSome days after the battle, his [[Shattered Sword of Marduk|blade]] was lost in another battle near [[Corin's Crossing]]. A [[Dwarf]] captain shattered the sword on his enchanted shield, forcing Marduk to flee the field and winning the day for the Alliance. Marduk's sword sank into the earth and corrupted it, eating a gorge into the land, now known as the [[Infectis Scar]]. However, it seems that the Death Knight still retained the hilt of his sword and is still able to spread corruption through it.\r\nAfter the initial invasion, he became a tutor in the [[Scholomance]]. He was a partner of [[Vectus]], who researched corrupted dragon eggs in the hopes of creating a plagued dragonflight for their use. Blackpool paid little heed to the battles raging throughout Scholomance, until the [[Dawn's Gambit]] was unleashed in the [[Viewing Room]]. Then, he charged into battle to defend Vectus.\r\n==Quotes==\r\n''\"Your future is clouded. Concentrate, and ask again.\"''\r\n''\"You don't look like a student...\"''\r\n''\"Your mind is unfocused. Are you hiding something from me?\"''\r\n''\"I sense a disturbance, lurking around you...\"''\r\n==Note==\r\n\"Marduk\" is also a name of an ancient [[wikipedia:Marduk|Mesopotamian deity]].\r\nAnother theory is that his name and position as a teacher refer to [[wikipedia:Neon Genesis Evangelion|Neon Genesis Evangelion]], where the Marduk Institute was in charge of choosing and training the \"Children\" that would control the EVAs.",},
			["Marduk the Black"] = { content = "#REDIRECT [[Marduk Blackpool]]", redirect = "Marduk Blackpool",},
			["Marek Ironheart"] = { content = "'''Marek Ironheart''' is a level 15 [[quest giver]] located in [[the Farstrider Lodge]] in the [[dwarven]] territory of [[Loch Modan]]. Marek Ironheart is a grizzled Ironforge dwarf. He manages the hunting enclave at the Farstrider Lodge. Marek and Brann Bronzebeard knew each other when they were young lads; Brann believes he was always a pain in the ass, but that he has mellowed out some.\r\nHe may be related to [[Archaeologist Adamant Ironheart]].\r\nHe starts the quest Crocolisk Hunting.\r\nSee [[List of Loch Modan NPCs]].",},
			["Marez Cowl"] = { content = "'''Marez Cowl''' is a level 40 [[orc]] [[warlock]] member of the [[Syndicate]] found in [[Stromgarde Keep]] in the [[Arathi Highlands]].\r\n[[Tor'gan]] wants the bloodstone orb that Marez carries, while [[Captain Nials]] wants Marez's head.\r\nAlthough considered a warlock, Marez has no mana points and does not have any special abilities.\r\nIn the quest description of Foul Magics (2), Tor'gan doesn't know the identity of the warlock, and so refers to Marez as a he. Considering that Marez is an orc warlock, described as being an emissary between the Syndicate and an unknown evil organization, it can be assumed that she is a member of the [[Argus Wake]].\r\n==Stats==\r\n*'''Damage''': 18-64.\r\n*'''XP Given At Level 43''': 400.\r\n*'''Average Coin Drop''': 2 silver 37 copper .\r\n*'''Respawn Rate''': 5-10 minutes.\r\n==Location==\r\nMarez has two spawn points:\r\n#She can be found up the ramp when you first enter [[Stromgarde Keep]] and to the left behind a house in the corner near a well. There is a [[Syndicate Prowler]] nearby. \r\n#Sometimes she spawns on the lower level of the Keep's grounds; from the start of the keep, ignore the ramp and turn left, follow the twisting street all the way back, and walk through the narrow alley between the keep wall and the last house to find her (either side has a path). Note that this is distinct from the location listed above, and instead of a well there is a table with bloody meat and cleavers on it. \r\nNote that if you go to either spot you can find out where she is located - in either spot you can /target Marez to see if she is alive in the other spot than the one you are at.\r\n==Objective of==\r\n*Marez's Head ''(Alliance Quest Item for Wanted! Marez Cowl)''\r\n*Befouled Bloodstone Orb ''(Horde Quest Item for Foul Magics (2))''\r\n==Notes==\r\n*Even though she is with the Syndicate, she awards no reputation lose/gain for her death.\r\n*She was elite prior to patch [[2.3]].",},
			["Margol the Rager"] = { content = "'''Margol the Rager''' is a level 43 [[thunder lizard]] found in [[Searing Gorge]]. Margol wanders in and out of her cave in the hills east of the [[Tanner Camp]], in the southeastern part of the land.\r\n[[Mountaineer Pebblebitty]]'s axe head is stuck in Margol's horn.\r\n==Quests==\r\n*The Horn of the Beast\r\n==Loot==\r\n*Margol's Horn\r\n==Patches==\r\n'''[[Patch 2.3.0]]''': Margol is no longer elite, and has been tuned down to level 43",},
			["Margoz"] = { content = "==Objectives==\r\nSpeak with [[Margoz (orc)|Margoz]].\r\n==Description==\r\nOne of our [[Shaman]]s, Margoz, knows more of the Burning Blade's corruption. He speaks of a cave called Skull Rock in the mountains - just outside Orgrimmar! - that shelters a large band of Burning Blade cultists.\r\nBefore you go to Skull Rock speak with Margoz. He is wise and his council is valued.\r\nHe is camped to the northeast, between the coast and Drygulch Ravine.\r\nFollow his advice, but whatever Margoz says, <name>, I still want you to crush those cultists!\r\n==Rewards==\r\nYou will receive:\r\n* 90 [[XP]]\r\n* +10 [[reputation]] with [[Orgrimmar (faction)|Orgrimmar]]\r\n* +10 reputation with [[Darkspear Trolls]]\r\n* 120 experience (Season of Mastery)\r\n==Completion==\r\nWelcome, <name>. Word reached me of your coming, and of your exploits in Durotar.\r\nYou are a <class> of growing skill and renown.\r\nStay on the pure path, and your future will be great indeed.",},
			["Margoz (human)"] = { content = "''This article is about the [[Cycle of Hatred]] character. For the [[Horde]] quest giver in [[Durotar]], see [[Margoz]].\r\n'''Margoz''' was a fisherman native to [[Kul Tiras]] who had come to [[Theramore]] soon after the [[Battle of Mount Hyjal]] in an attempt to make more profit than he had in Kul Tiras. Still, according to his fellow fishermen he was very unskilled and continued to live a very poor life. He was eventually recruited into service to a demon [[Zmodlor]], who had then started the [[Burning Blade]] cult among both orcs and humans of Kalimdor. The cult's goal was to start a full-scale war between orcs and humans again, and Margoz's job was to sow anti-orc sentiments in Theramore. His attempts to do so in the Demonsbane tavern were very successful, and Zmodlor continued to manipulate both the orcs and humans into starting the war between the Alliance and the Horde again. The demon's plans were eventually discovered and he was banished into the [[Twisting Nether]]. Margoz's fate after that is unknown.",},
			["Margoz (orc)"] = { content = "'''Margoz''' is an [[orc]] [[shaman]] [[quest giver]] located in a tent south of [[Bladefist Bay]] in [[Durotar]].\r\n==Quests==\r\n*[[Margoz (quest)]] \r\n*[[Skull Rock (quest)]] \r\n*[[Arnak Fireblade (quest)]] \r\n*[[Neeru Fireblade (quest)]] \r\n==See also==\r\n*[[List of Durotar NPCs]]",},
			["Margoz (quest)"] = { content = "==Objectives==\r\nSpeak with [[Margoz]].\r\n==Description==\r\nOne of our [[Shaman]]s, Margoz, knows more of the [[Burning Blade]]'s corruption. He speaks of a cave called [[Skull Rock]] in the mountains - just outside [[Orgrimmar]]! - that shelters a large band of Burning Blade cultists.\r\nBefore you go to Skull Rock speak with Margoz. He is wise and his council is valued.\r\nHe is camped to the northeast, between the coast and [[Drygulch Ravine]].\r\nFollow his advice, but whatever Margoz says, <name>, I still want you to crush those cultists!\r\n==Completion==\r\nWelcome, <name>. Word reached me of your coming, and of your exploits in Durotar.\r\nYou are a <class> of growing skill and renown.\r\nStay on the pure path, and your future will be great indeed.\r\n==Quest progression==\r\nThis quest is part of a chain.\r\n*Report to Orgnil\r\n**Dark Storms\r\n**Margoz\r\n**Skull Rock\r\n**Neeru Fireblade\r\n**Ak'Zeloth\r\n***The Demon Seed",},
			["Margrave Dhakar"] = { content = "He is involved in the following quests:\r\n*The Flesh Giant Champion",},
			["Maria Lumere"] = { content = "'''Maria Lumere''' is a level 30 [[alchemy]] [[vendor]] located in [[the Mage Quarter]] in the [[human]] city of [[Stormwind]].\r\nSee [[List of Stormwind NPCs]].",},
			["Marijah"] = { content = "'''Marijah''' is a female human [[ghost]]. The being is clad in simple gaments, though her translucent form makes it difficult to see any details of what she wears and carries. She was a scout in life. She speaks [[Common (language)|Common]], [[Dwarven (language)|Dwarven]], and [[Giant (language)|Giant]].",},
			["Marinda"] = { content = "Marinda was a senior priestess of [[Sisters of Elune]]. It was she who informed [[Tyrande Whisperwind]] that she had been chosen as the new High Priestess. During Tyrande's initial tenure, she was chosen to succeed Whisperwind in the event anything should befall the new High Priestess. Shortly after that, an [[Eredar]] warlock killed Marinda. [[Maiev Shadowsong]] succeeded her as Interim High Priestess, who in turn returned the title to Tyrande.",},
			["Marine"] = { content = "'''Space Marines''' were [[human]]s in space suits who fought [[Fel Space Orc]]s in the [[Warcraft III: The Frozen Throne]] bonus clip after the player beats the game on the hardest difficulty mode. They are actually well-known unit from the [[StarCraft]] universe.",},
			["Mariner Everwatch"] = { content = "'''Mariner Everwatch''' is a member of the ''[[Feathermoon Ferry]]'', the boat that runs between [[Feathermoon Stronghold]] and [[The Forgotten Coast]]. Is in charge of watching for lost souls, with the help of the [[wisp]].\r\n==Notes==\r\n* Can be killed, but respawns almost instantly giving no XP or loot.\r\n* Will not attack unless attacked first.\r\n* Does not help her allies when they are attacked, so its hard to believe they would help players if they are attacked (as they were intended to do).",},
			["Mariner Farseeker"] = { content = "'''Mariner Farseeker''' is a member of the ''[[Elune's Blessing]]'', the boat that runs between [[Auberdine]] and [[Valaar's Berth]]. Only has the time to speak to the wisps and her captain, she asks for your forgiveness. \r\n==Notes==\r\n* Can be killed, but respawns almost instantly giving no XP or loot.\r\n* Will not attack unless attacked first.\r\n* Does not help her allies when they are attacked, so its hard to believe they would help players if they are attacked (as they were intended to do).",},
			["Mariner Frostnight"] = { content = "'''Mariner Frostnight''' is a member of the crew of the ''[[Elune's Blessing]]'', the boat that runs between [[Auberdine]] and [[Valaar's Berth]].\r\n==Notes==\r\n* Can be killed, but respawns almost instantly giving no XP or loot.\r\n* Will not attack unless attacked first.\r\n* Does not help her allies when they are attacked, so its hard to believe they would help players if they are attacked (as they were intended to do).",},
			["Mariner Keenstar"] = { content = "'''Mariner Keenstar''' is a member of the crew of the ''[[Elune's Blessing]]'', the boat that runs between [[Auberdine]] and [[Valaar's Berth]]. Blessed by Elune she is quite happy with the discoveries they have made.\r\n==Notes==\r\n* Can be killed, but respawns almost instantly giving no XP or loot.\r\n* Will not attack unless attacked first.\r\n* Does not help her allies when they are attacked, so its hard to believe they would help players if they are attacked (as they were intended to do).",},
			["Mariner Moonblade"] = { content = "'''Mariner Moonblade''' is a member of the ''[[Feathermoon Ferry]]'', the boat that runs between [[Feathermoon Stronghold]] and [[The Forgotten Coast]]. She may be related to [[Sentinel Tysha Moonblade]].\r\n==Notes==\r\n* Can be killed, but respawns almost instantly giving no XP or loot.\r\n* Will not attack unless attacked first.\r\n* Does not help her allies when they are attacked, so its hard to believe they would help players if they are attacked (as they were intended to do).",},
			["Mariner Softsong"] = { content = "'''Mariner Softsong''' is a member of the ''[[Feathermoon Ferry]]'', the boat that runs between [[Feathermoon Stronghold]] and [[The Forgotten Coast]]. Wants to make to not lose any more souls.\r\n==Notes==\r\n* Can be killed, but respawns almost instantly giving no XP or loot.\r\n* Will not attack unless attacked first.\r\n* Does not help her allies when they are attacked, so its hard to believe they would help players if they are attacked (as they were intended to do).",},
			["Mariner Stillglider"] = { content = "'''Mariner Stillglider''' is a member of the crew of the ''[[Elune's Blessing]]'', the boat that runs between [[Auberdine]] and [[Valaar's Berth]]. She is also the helmsman, leave her be, as she must focus on her job.\r\n==Notes==\r\n* Can be killed, but respawns almost instantly giving no XP or loot.\r\n* Will not attack unless attacked first.\r\n* Does not help her allies when they are attacked, so its hard to believe they would help players if they are attacked (as they were intended to do).",},
			["Mariner Stillwake"] = { content = "'''Mariner Stillwake''' is a member of the ''[[Feathermoon Ferry]]'', the boat that runs between [[Feathermoon Stronghold]] and [[The Forgotten Coast]]. Forgive her, but she must concentrate on her job.\r\n==Notes==\r\n* Can be killed, but respawns almost instantly giving no XP or loot.\r\n* Will not attack unless attacked first.\r\n* Does not help her allies when they are attacked, so its hard to believe they would help players if they are attacked (as they were intended to do).",},
			["Marine Anderson"] = { content = "'''Marine Anderson''' is a soldier onboard the ''[[Lady Mehley]]'', the boat that runs between [[Theramore Isle]] and [[Menethil Harbor]]. Anderson is a member of the Theramore [[Marine]]s, and was assumed to be onboard for the protection of the crew. However, she, along with [[Marine Halters|Halters]], were assigned to guard the passengers as it is felt the ship goes to [[Theramore]] enough.\r\nAlthough she can be attacked, she will not strike the first blow.\r\n==Notes==\r\n* She is mostly for looks as she doesn't even protect the passengers as she claims she does. \r\n* Although not flagged for PvP, she will flag her attackers.",},
			["Marine Halters"] = { content = "'''Marine Halters''' is a soldier onboard the ''[[Lady Mehley]]'', the boat that runs between [[Theramore Isle]] and [[Menethil Harbor]]. Halters is a member of the Theramore [[Marine]]s, and was assumed to be onboard for the protection of the crew. However, he along with [[Marine Anderson|Anderson]] were assigned to guard the passengers as it's felt the ship goes to [[Theramore]] enough.\r\nAlthough he can be attacked, he will not strike the first blow. \r\n==Notes==\r\n* He is mostly for looks as he doesn't even protect the passengers as he claims she does. \r\n* Although not flagged for PvP, he will flag his attackers.",},
			["Marin Noggenfogger"] = { content = "'''Marin Noggenfogger''' is a level 40 [[quest giver]] located in [[Gadgetzan]] in the [[contested]] territory of [[Tanaris]].\r\nHe starts the following quests:\r\n* Noggenfogger Elixir\r\n* The Thirsty Goblin\r\n* In Good Taste\r\nOnce his quest chain is completed, he will sell [[Noggenfogger Elixir|Noggenfogger Elixirs]].\r\nSee [[List of Tanaris NPCs]].",},
			["Marion Call"] = { content = "'''Marion Call''' is a level 13 [[rogue trainer]] located in [[Gallows' End Tavern]] in [[Brill]], in the [[Forsaken]] starting zone of [[Tirisfal Glades]].\r\n==Quests==\r\nShe starts the quest Mennet Carkad.\r\n==See Also==\r\nSee [[List of Tirisfal Glades NPCs]].",},
			["Marisa du'Paige"] = { content = "'''Marisa du'Paige''' (aka Marisa Du'Paige)is a level 18 [[elite]] [[rare mob]] [[human]] [[mage]] that spawns in the caves outside the [[Deadmines]] [[instance]].\r\nA Defias mage and a skilled transmuter, Du’Paige is the daughter of one of VanCleef’s most skilled lieutenants, who was killed during the Stormwind City riot. Marisa, a golden-haired woman in her mid-twenties, always had an affinity toward both magic and cruelty; and the Defias Brotherhood gives her opportunities to indulge in both. She oversees operations in the upper levels of the Deadmines and the training of magical adepts.\r\n==Abilities==\r\n*[[Fireball]]\r\n*Polymorph: Chicken - Transforms the enemy into a chicken that cannot cast, and does 66% less damage for up to 10 sec",},
			["Marjak Keenblade"] = { content = "'''Marjak Keenblade''' is a level 9 [[weapon]] [[vendor]] located in [[Camp Narache]] in the [[tauren]] starting zone of [[Mulgore]].\r\nSee [[List of Mulgore NPCs]].",},
			["Mark"] = { content = "'''Mark''' may mean any of the following:\r\n*[[Mark of the Wild]], the druid buff. \r\n*[[Hunter's Mark]], the hunter non-aggro debuff.\r\n*[[Raid Target Icon]], raid leader's utility.",},
			["Marka"] = { content = "'''Marka''' is second-in-command to the bandit [[Kenry the Robber]]. She ran afoul of a trap set by [[Subversive]]s, and her face was scarred by acid.",},
			["Markaru"] = { content = "'''Markaru''' can be found in [[Netherstorm]] .\r\n==Drops == \r\n \r\n0.10% Chance of a [[rare]] drop.\r\n1.55% Chance of an [[Uncommon]] drop.\r\n0.07% Chance of a [[common]] drop.\r\n1.32% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Market Row"] = { content = "'''Market Row''' is located inside [[Stratholme]] Scarlet Side, north from [[King's Square]]. It can also be accessed from [[Festival Lane]] to the east, and leads on into [[Crusaders' Square]], which contains [[the Scarlet Bastion]].\r\nMarket Row holds numerous perpetually burning buildings, including '''[[Kirtonos the Herald|Kirtonos]] Bros. Funeral Home'''. It is the location of [[Hearthsinger Forresten]], and [[the Unforgiven]] appears in a tunnel adjacent to Market Row.",},
			["Marksman's Bow"] = { content = "'''Marksman's Bow''' is an epic bow. It can be purchased from [[Quartermaster Urgronn]] <small><Thrallmar Quartermaster></small> for 159 gold 99 silver 84 copper . You must also be with [[Thrallmar]].",},
			["Marksman"] = { content = "'''Marksmen''' are warriors who have embraced firearms as their weapon of choice. Studying the techniques of the dwarves, these soldiers craft their own weapons and hone their aim until they are capable of incredible feats of speed and accuracy. Marksmen learn to trust their instinctive ability with firearms to make incredibly skilled shots.\r\nThe most experienced marksmen become [[epic marksman|epic marksmen]].\r\n==Marksmen in WoW==\r\n*[[Kaldorei Marksman]] - \r\n*[[Dark Iron Marksman]] - Searing Gorge\r\n*[[Highvale Marksman]] - The Hinterlands\r\n==Famous/named== \r\n*[[Galamav the Marksman]]\r\n==See also==\r\n*[[Gunman]]\r\n*[[Rifleman]]",},
			["Marksmanship"] = { content = "#REDIRECT [[Hunter]]", redirect = "Hunter",},
			["Marks of Honor"] = { content = "#REDIRECT [[Mark of Honor]]", redirect = "Mark of Honor",},
			["Marks of Sargeras"] = { content = "==Objectives==\r\nBring 10 Marks of Sargeras to [[Adyen the Lightwarden]] in [[Shattrath]] City.\r\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.\r\n*Mark of Sargeras (10)\r\n==Description==\r\nBy now it should be clear to you why we oppose the Burning Legion and those who serve them.\r\nIf you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers. The highest-ranking Legion can be found in [[Netherstorm]] and [[Shadowmoon Valley]].\r\n==Progress==\r\nDo you bear any of our enemies' insignias, <name>?\r\n==Completion==\r\nFacing the demons of the Burning Legion and the mad cultists that worship them is no small feat, <name>. You've shown great dedication and courage. Keep it up and your renown among the Aldor will continue to grow.\r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*12650 [[XP]] (or 7 gold 59 silver copper at level 70)\r\n*250 [[reputation]] with [[The Aldor]]\r\n*-275 [[reputation]] with [[The Scryers]]",},
			["Marks of Thrallmar"] = { content = "#REDIRECT [[Mark of Thrallmar]]", redirect = "Mark of Thrallmar",},
			["Markus Scylan"] = { content = "'''Markus Scylan''' is a level 60 [[gem]] [[vendor]] located at [[Honor Hold]] in the [[contested]] territory of [[Hellfire Peninsula]]. He is located at the Inn in the Hold; he is next to the wall on the inside of the Inn, to the left when you first face the main room.\r\n==Merchant==\r\n'''This vendor sells:'''\r\n*Bold Tourmaline\r\n*Bright Tourmaline\r\n*Delicate Tourmaline\r\n*Runed Tourmaline\r\n*Teardrop Tourmaline\r\n*Lustrous Zircon\r\n*Solid Zircon\r\n*Sparkling Zircon\r\n*Brilliant Amber\r\n*Gleaming Amber\r\n*Rigid Amber\r\n*Smooth Amber\r\n*Thick Amber\r\n==See Also==\r\n* [[List of Hellfire Peninsula NPCs]]",},
			["Mark of Conquest"] = { content = "==Source==\r\nThis item is sold by:\r\n*Alliance Field Scout at [[Telredor]] in [[Zangarmarsh]] for 30 [[Mark of Honor Hold]]\r\n*Horde Field Scout at [[Zabra'jin]] in [[Zangarmarsh]] for 30 [[Mark of Thrallmar]]",},
			["Mark of Death"] = { content = "==Mark of Death==\r\n==Notes==\r\nThis [[debuff]] is applied to players who die while engaged with the Doomwalker to prevent graveyard zerging, and acts like other world boss knockout debuffs by lasting for 15 minutes. The debuff will cause you to instantly die if you get too close to Doomwalker. However, you will not take any [[durability]] loss to your armor.",},
			["Mark of Defiance"] = { content = "==Source==\r\nThis item is sold by:\r\n*[[Alliance Field Scout]] at [[Telredor]] in [[Zangarmarsh]] for 30 Mark of Honor Hold (mh=30 gold )\r\n*[[Horde Field Scout]] at [[Zabra'jin]] in [[Zangarmarsh]] for 30 Mark of Thrallmar (mt=30 gold )\r\n==Notes==\r\nThis item is triggered from landing any harmful spell on a target. That includes the following spells and effects:\r\n*Non-damaging, offensive abilities (e.g. [[Vampiric Embrace]]) \r\n*Hits from item procs (e.g. [[Satyr's Lash]]'s Shadow Bolt) and temporary enchants (e.g. [[Bloodboil Poison]])\r\n*Hits from [[mage]] armor spells ([[Ice Armor]], [[Frost Armor]] and [[Molten Armor]])\r\n*Secondary effects (e.g. [[Frostbite]], [[Improved Blizzard]])\r\nHits from the shaman's weapon buffs ([[Frostbrand Weapon]] and [[Flametongue Weapon]]) cannot trigger it, however. \r\nThe effect seems to have an internal cooldown of approximately 16 seconds.",},
			["Mark of honor"] = { content = "#REDIRECT [[Mark of Honor]]", redirect = "Mark of Honor",},
			["Mark of Honor Hold"] = { content = "The '''Mark of Honor Hold''' is an [[Alliance]] [[PvP token]] earned for [[world PvP]] in [[Hellfire Peninsula]] and [[Zangarmarsh]], akin to [[Alterac Valley Mark of Honor]]. For horde rewards, see the [[Mark of Thrallmar]] page.\r\n==Source==\r\nPlayers can earn marks in two ways:\r\n* The repeatable PvP quest Hellfire Fortifications (Alliance) awards three marks for capturing forts in [[Hellfire Peninsula]].\r\n* Delivering a killing blow a player of the opposing faction in the vicinity of Outdoor PVP objectives in either [[Hellfire Peninsula]] or [[Zangarmarsh]] awards one mark to each member of the killer's group or raid. However, it appears that this will only award a mark to those that would also gain honor from the kill. Killing a grayed out player will not award an honor mark.\r\n==Rewards==\r\nMarks can be turned in to [[Warrant Officer Tracy Proudwell]] in [[Honor Hold]] or the [[Alliance Field Scout]] in [[Telredor]] for a variety of rewards.\r\nWarrant Officer Tracy Proudwell offers:\r\nThe Alliance Field Scout offers:",},
			["Mark of Sargeras"] = { content = "'''Mark of Sargeras''' drops from high-60 level mobs in [[Blade's Edge Mountains]], [[Netherstorm]], [[Shadow Labyrinth]] and [[Shadowmoon Valley]].\r\nPopular farming spots include:\r\n* [[Death's Door]] - [[Blade's Edge Mountains]],\r\n* [[Forge Camp: Anger]] - [[Blade's Edge Mountains]],\r\n* [[Arklon Ruins]] - [[Netherstorm]] (Artifact Seeker drop rate may have been nerfed),\r\n* [[Legion Hold]] - [[Shadowmoon Valley]],\r\n* [[Forge Base: Gehenna]] - [[Netherstorm]],\r\n* [[Forge Base: Oblivion]] - [[Netherstorm]],\r\n* [[Shadow Labyrinth]] - [[Auchindoun]],\r\n* [[The Arcatraz]] - [[Tempest Keep]],\r\n* [[The Mechanar]] - [[Tempest Keep]]\r\n==As a quest objective==\r\nMarks of Sargeras are used for these quests to increase reputation with the [[Aldor]] (and decrease it with the [[Scryers]]):\r\n* Marks of Sargeras (Shattrath City)\r\n* Marks of Sargeras (Shadowmoon Valley)\r\n* Single Mark of Sargeras\r\n* More Marks of Sargeras\r\nList of mobs dropping this item .",},
			["Mark of the Illidari"] = { content = "Mark of the Illidari can be exchanged for [[flask]]s which usage is restricted to raid instances.\r\n==Source==\r\nThis item drops from trash mobs in the [[Burning Crusade]] raid instances [[Serpentshrine Cavern]], [[Tempest Keep]], [[Black Temple]] and [[Battle of Mount Hyjal]].\r\n==Notes==\r\nTo exchange this item for a flask, players must have reputation with the [[Aldor]] or [[Scryers]], the [[Sha'tar]] and the [[Cenarion Expedition]].\r\nGives:\r\n* icon=\r\n* icon=\r\n* icon=\r\n* icon=\r\n* icon=\r\n* icon=",},
			["Mark of the Wild"] = { content = "''\"May [[Cenarius]] smile upon you.\" — Archdruid [[Hamuul Runetotem]]''\r\nAccording to the World of Warcraft pen-and-paper RPG, '''Mark of the Wild''' is a druidic spell shared by druids, hunters, and elven rangers. By channeling the wild into a willing receptacle a caster can fill an ally with the feral grace and swiftness of the dire beasts of the Emerald Dream. Druids know two related druid-only spells called Greater Mark of the Wild, and Lesser Mark of the Wild.\r\nWithin World of Warcraft, only Druids have access to this ability. It is a [[buff]] that adds to a friendly target's armor, stats, and resistances.\r\nIt is seldom referred to by its full name. Players request \"Mark\", \"Mo(t)W\", or \"(pink) paw\".\r\n==Notes==\r\n* Mark of the Wild (Rank 1) is a level 1 spell that the starting Druid does not know. It can be bought at the Druid trainer in the starting area.\r\n* Mark of the Wild can be cast on any friendly target, including [[NPC]]s, players of your faction, and their [[pet]]s.\r\n* The resistance benefit of any rank of this spell does not stack with other resistance buffs. See [[Resistance]]s for more information.\r\n==Tips and tactics==\r\n*Unlike some buffs, Mark of the Wild benefits ''every'' class in some way.\r\n*A Druid should always have Mark of the Wild on themselves, and be sure that every member of their group has been buffed too (and any pets).\r\n*If you have Mana to spare while soloing, any nearby friendly player will appreciate and benefit from this ability. \r\n*[[Gift of the Wild]] is a group version of this spell, available at level 50 (Rank 1), level 60 (Rank 2) and level 70 (Rank 3). It is learned from books dropped in high level instances. As of [[patch 2.1]], ranks 1 and 2 are also trainable from druid trainers.",},
			["Mark of Thrallmar"] = { content = "The '''Mark of Thrallmar''' is a [[Horde]] [[PvP Token|PvP token]] earned for [[world PvP]] in [[Hellfire Peninsula]] and [[Zangarmarsh]], akin to [[Alterac Valley Mark of Honor]]. For alliance rewards, see the [[Mark of Honor Hold]] page.\r\n==Source==\r\nYou can earn marks in two ways:\r\n* The repeatable PvP quest Hellfire Fortifications (Horde daily) awards three marks for capturing forts in [[Hellfire Peninsula]]. Note that as of [[Patch 2.1.0]], this quest can only be done once per 24 hours, but now rewards 150 Thrallmar reputation in addition to the three Marks.\r\n* Delivering a killing blow to players of the opposing faction in the vicinity of Outdoor PVP objectives in either [[Hellfire Peninsula]] or [[Zangarmarsh]] awards one mark to each member of the killer's group or raid.\r\n==Rewards==\r\nMarks can be turned in to [[Battlecryer Blackeye]] in [[Thrallmar]] or the [[Horde Field Scout]] in [[Zabra'jin]] for a variety of rewards.\r\nBattlecryer Blackeye offers:\r\n \r\nThe Horde Field Scout offers:",},
			["Marlene Redpath"] = { content = "'''Marlene Redpath''' is a level 10 [[quest giver]] located in an abandoned house at [[Sorrow Hill]] in the [[contested]] territory of [[Western Plaguelands]] (coordinates 49,78). Killed in the coming of the [[Scourge]], her spirit is determined to discover the fate of her niece [[Pamela Redpath]]. Conversely, little Pamela offers a quest called Auntie Marlene, where Marlene Redpath must be located.\r\nMarlene starts the following quests:\r\n* Little Pamela\r\n* A Strange Historian\r\nSee [[List of Western Plaguelands NPCs]].",},
			["Marleth Barleybrew"] = { content = "'''Marleth Barleybrew''' is a level 12 [[quest giver]] located in [[Brewnall Village]] in the [[dwarven]] starting zone of [[Dun Morogh]].\r\nOther members of the Barleybrew family include [[Malgin Barleybrew|Malgin]], [[Rejold Barleybrew|Rejold]], [[Mountaineer Barleybrew|Wellart]], and [[Yorus Barleybrew|Yorus]].\r\nShe starts the quest Bitter Rivals.\r\nSee [[List of Dun Morogh NPCs]].",},
			["Marris Stead"] = { content = "The '''Marris Stead''' rests atop a small ridge in the [[Eastern Plaguelands]] near the border of the [[Western Plaguelands]], located northwest of the ruins of [[Darrowshire]]. It is the long time family home of [[Nathanos Blightcaller|Nathanos Marris the Blightcaller]], who still makes the stead his home, despite being one with the [[Forsaken]] and hunted by the [[Alliance]].",},
			["Marshal's Refuge"] = { content = "'''Marshal's Refuge''' is a [[neutral]] outpost at the northern edge of [[Un'Goro Crater]] with a mixed population of stranded travellers near the entrance to a crystal-filled cave. [[Williden Marshal]] and his family are present along with the survivors of his failed expedition. \r\nWilliden’s group claimed a cave in the north as its semi-permanent home in Un’Goro. Here these stalwart explorers live a primitive existence as they study the crater. Although among them they have the means to improve their settlement, none of them has bothered to spend the time doing so. They’re too busy with their research. Vistors to the the place are adviced to bring their own supplies — they only have enough to support themselves.\r\nThis zone contains numerous refences to the 70s T.V. show \"Land of the Lost\", which focused on the adventures of a family of three (father Rick Marshall, son Will, and younger daughter Holly) who are trapped in an alien world inhabited by dinosaurs.\r\n==Features==\r\n* Neutral [[Flight Path]] located at 45,6.\r\n* General goods vendor\r\n* Weapons Merchant (provides repairs)\r\n* No inn or mailbox is available.\r\n===Flight===\r\n [[Gadgetzan]]\r\n [[Cenarion Hold]]\r\n==Marshal's Refuge NPCs==\r\n*Gibbert\r\n*Gryfe\r\n*Nergal\r\n*Gadgetzan Bruiser\r\n*J.D. Collie\r\n*Karna Remtravel\r\n*Krakle\r\n*Linken",},
			["Marshal"] = { content = "'''Marshals''' are [[Vanndar Stormpike]]'s elite officers, most of whom reside in the [[Dun Baldar]] in [[Alterac Valley]] next to their general. At the start of the battle for Alterac Valley, Vanndar is protected by four Marshals, one for each of the Stormpike Bunkers; each is named for his Bunker, rather than given a personal name.\r\nTied to their general, Marshals cannot be pulled separately from Vanndar. The only way to deprive the Stormpike General of his protectors is to destroy the Bunkers before assaulting Dun Baldar. As each Bunker is destroyed, the associated Marshal is removed from the Valley.\r\nEach Bunker must be protected carefully if the Expedition wishes to keep their Marshals, as there is no longer a way to gain more. Furthermore, each Marshal - and thus each Tower - represents 75 [[Reinforcements]], a full 12.5% of the initial Stormpike army. Losing all four Marshals and Bunkers means losing half of the Expedition's Reinforcements. Still, losing Bunkers may be considered acceptable losses if other objectives are archived in the meantime.\r\nEach Marshal is an elite of the level cap for the Valley - level 60 for 51~60 AV, level 70 for 61~70 AV. Level 60 Marshals have 61,000 health; and their level 70 counterparts have 140,000 health. Level 80 marshals have 327,500 health with no 25% more health buffs. Each generally requires his own tank and healer, so it is often advisable to destroy as many Bunkers as possible before beginning the encounter.\r\n==Patch 2.3 changes==\r\nPrior to [[Patch 2.3.0|2.3]], Marshals and their counterparts, the Frostwolf [[Warmaster]]s, could be pulled separately from their Generals. Additionally, the destruction of a Horde Tower would not only despawn a Warmaster but also spawn an extra Marshal - and vice versa. Now, each side will only ever have the four guards they start the battle with.\r\n==Patch 2.4 changes==\r\nVanndar Stormpike's and Balinda's health have been reduced to match the total of Galvangar and Drek'Thar. Warmasters/marshals now buff each other for 25% more health and damage. This is a stackable effect and is stacked separately. So at 1 marshal, the general has 25% more health and damage, 2 marshals 56%, 3 marshals 95%, 4 marshals 144%. This is compared to the generals' base damage and health.",},
			["Marshal Bluewall"] = { content = "'''Marshal Bluewall''' is a level 60 [[quest giver]] located at the [[Hive'Zora]] [[Alliance]] camp in the [[contested]] territory of [[Silithus]].\r\nHe starts the quest Scouring the Desert (Alliance) (PvP, Repeatable).\r\nHe may have been named for the practice of [[bluewall]]ing.\r\nSee [[List of Silithus NPCs]].",},
			["Marshal Dughan"] = { content = "'''Marshal Dughan''' is a level 25 [[quest giver]] located in [[Goldshire]] in the [[human]] starting zone of [[Elwynn Forest]]. He is the elected ruler of [[Elwynn Forest]], as well as the leader of the military forces stationed there on behalf of the [[Stormwind Army]]. He is very concerned about the [[Kobold]]s to the north, and the [[Gnoll]]s and thieves to the west. He wants to know just how far they have spread over the land and ask adventurers to help him with related tasks.\r\nHe starts and ends the following quests: \r\n* The Fargodeep Mine \r\n* The Jasperlode Mine \r\n* Manhunt \r\nHe starts the following quests: \r\n* Westbrook Garrison Needs Help! \r\n* Further Concerns \r\n* Cloth and Leather Armor \r\n* Report to Gryan Stoutmantle \r\nHe ends the following quests: \r\n* Report to Goldshire \r\n* Wanted: \"Hogger\" \r\n* A Fishy Peril \r\n* Deliver Thomas' Report \r\n* The Collector \r\nSee [[List of Elwynn Forest NPCs]].",},
			["Marshal Gryan Stoutmantle"] = { content = "#REDIRECT [[Gryan Stoutmantle]]", redirect = "Gryan Stoutmantle",},
			["Marshal Haggard"] = { content = "'''Marshal Haggard''' is a level 20 [[quest giver]] located in [[Eastvale Logging Camp]] in the [[human]] starting zone of [[Elwynn Forest]]. He is a former military leader of the [[Stormwind Army]] before retiring from active duty to Elwynn Forest. Warriors in training are directed to him. Should they complete his task, they are given one of his weapons. \r\nRecently, a Defias Brotherhood member named [[Dead-Tooth Jack]] stole the Haggard's Marshal Badge. At one point, Dead-tooth Jack disguised himself as [[Marshal Dughan]] by wearing a [[Stormwind]] tabard and tricked Haggard into giving him his old Stormwind Marshal's badge. Jack reportedly laughed as he took off with the badge. Haggard blames the fact that he was tricked on the poor lighting that day. He claims later on that he is nearly blind and wears an eyepatch as well. \r\nIn his younger days as the leader of the Stormwind Guard, he drank at the Scarlet Raven Tavern with his soldiers. He knows [[Tavernkeep Smitts]] from there. \r\nWhen he moved into Elwynn forest the previous owner of his dwelling left various papers in it, one of which was a faded journal page left that details the Legend of [[Stalvan]]. \r\nName given after Singer Merle Haggard\r\nHe starts the following quests: \r\n* Dead-tooth Jack\r\n*Report to Gryan Stoutmantle\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Marshal Isildor"] = { content = "'''Marshal Isildor''' is a level 71 [[quest giver]] located at [[Honor Hold]] in the [[contested]] territory of [[Hellfire Peninsula]].\r\nHe starts the quest Force Commander Danath.\r\nSee [[List of Hellfire Peninsula NPCs]].\r\nThe name Isildor is very probably a reference to [[wikipedia:Isildur|Isildur]], the High King of Gondor who cut the ring from the hand of Sauron in the ''[[wikipedia:The Lord of the Rings|Lord of the Rings]]'' trilogy by [[wikipedia:J. R. R. Tolkien|J.R.R. Tolkien]]. Can be kited to Thrallmar to amusing results. Has enough health to tank a [[Fel Reaver]]. \r\n===Quotes===\r\n*\"This war - and don't mistake this for anything but a war - is not going to win itself. If we do not fight, scratch, claw and kick for every speck of land in this shattered world, all will be lost.\"\r\n*\"I regret to inform you all that we sent home another ten soldiers today - in body bags.\"\r\n*\"Do you think that demons will play fair? These beasts are more savage then orcs and more cunning than the undead. Do not attempt to engage Legion by normal standards of war.\"",},
			["Marshal Marris"] = { content = "'''Marshal Marris''' is a level 35 [[quest giver]] located near the bridge in [[Lakeshire]] in the human-aligned zone of [[Redridge Mountains]]. He may be related to [[Nathanos Marris]].\r\nHe starts the following quests:\r\n* Blackrock Menace\r\n* Shadow Magic (Elite)\r\n* Tharil'zun (Elite)\r\nSee [[List of Redridge Mountains NPCs]]",},
			["Marshal Maxwell"] = { content = "'''Marshal Maxwell''' is a level 55 [[quest giver]] located at [[Morgan's Vigil]] in the [[contested]] territory of [[Burning Steppes]]. He may be related to [[Kirk Maxwell]].\r\nHe starts the following quests:\r\n* Marshal Windsor (Dungeon)\r\n* The True Masters\r\n* Stormwind Rendezvous\r\n* Maxwell's Mission (Raid)\r\n* General Drakkisath's Demise (Raid)\r\nSee [[List of Burning Steppes NPCs]].",},
			["Marshal McBride"] = { content = "'''Marshal McBride''' is a level 20 [[quest giver]] located in [[Northshire Abbey]] in the [[human]] starting zone of [[Elwynn Forest]]. He is a military leader of the [[Stormwind Army]] assigned to [[Northshire Valley]].\r\nHe starts the following quests:\r\n* Consecrated Letter (Human)\r\n* Encrypted Letter (Human)\r\n* Glyphic Letter (Human)\r\n* Hallowed Letter (Human)\r\n* Simple Letter (Human)\r\n* Tainted Letter (Human)\r\n* Kobold Camp Cleanup\r\n* Investigate Echo Ridge\r\n* Skirmish at Echo Ridge\r\n* Report to Goldshire",},
			["Marshal Redpath"] = { content = "#REDIRECT [[Marcus Redpath]]", redirect = "Marcus Redpath",},
			["Marshal Windsor"] = { content = "#REDIRECT [[Reginald Windsor]]", redirect = "Reginald Windsor",},
			["Marshlands"] = { content = "The Marshlands is a subzone in the Southeastern portion of [[Un'Goro Crater]] inhabited by very large [[raptors]]. The entrance to Un'goro from [[Tanaris]] is on the cliff wall here.",},
			["Marshlight Lake"] = { content = "'''Marshlight Lake''' is a vast lake in western [[Zangarmarsh]]. There is a [[Portal Clearing]] on the west banks of the lake.",},
			["Marsh Dredger"] = { content = "'''Marsh Dredger''' can be found in [[Zangarmarsh]] . Dredgers are the quest target of Saving the Sporeloks\r\n==Drops==\r\n \r\n0.14% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\n0.04% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Marsh Lurker"] = { content = "'''Marsh Lurker''' can be found in [[Zangarmarsh]] . The Lurker is the objective of Saving the Sporeloks\r\n==Drops == \r\n \r\n0.14% Chance of an [[Uncommon]] drop.\r\n0.01% Chance of a [[common]] drop.\r\n0.04% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Martek the Exiled"] = { content = "'''Martek the Exiled''' is a level 42 [[quest giver]] located in a small camp in the [[Valley of Fangs]] in the [[contested]] territory of [[Badlands]].\r\nHe starts the following quests:\r\n* News for Fizzle\r\n* Indurium\r\nHe ends the followign quests:\r\n* Martek the Exiled\r\n* Indurium\r\nSee [[List of Badlands NPCs]].",},
			["Martial enchanter"] = { content = "Many enchanters are students of magic. Yet, not all enchanters are spellcasters. The act of destruction releases energy and sometimes a reckless [[warrior]] or an inquisitive [[tinker]] may stumble upon the means to absorb this energy and channel it into creation.",},
			["Martin Thunder"] = { content = "'''Martin Thunder''' is an weapon which can rarely be linkable on certain realms. Quite uniquely, it has no weapon type so it can be wielded by any class. Given its description, the weapon is likely a weapon used by Blizzard for testing purposes. It is not accessible to regular players and has only appeared wielded by [[Game Master]]s in screenshots.\r\nIt also shares the same graphic as the Argent Avenger from a [[Stratholme]] quest line.",},
			["Martyrdom"] = { content = "''Let us all be brave enough to die the death of a martyr, but let no one lust for martyrdom.''\r\n'''Martyrdom''' is a priest talent which provides spell pushback and interrupt resistance upon receipt of a critical strike.\r\n==Notes==\r\nThis talent is extremely useful in PvP, where melee classes will often land strings of hits. The Focused Casting effect allows you to continue to cast through these hits, and potentially avoid interrupts as well.\r\n==Known Bugs==\r\n*Due to the built in resilience system occasionally counting non-critical hits as critical hits, Focused Casting sometimes does not proc on critical strikes. This system also prevents Focused Casting, Blessed Resilience, and Blessed Recovery from proccing from the same attack the majority of the time.\r\n \r\n <!-- ClassX = class which can use this ability, eg \"Mage\" --",},
			["Maruff Grandhorn"] = { content = "'''Maruff Grandhorn''' is a tauren healer. He is the friend of of the [[high elf]] [[Leonine Starborn]]. He once agreed to let her use ''absorb mana'' on him to recover some of her energy. When leanine finished casting the spell, she absorbed all of Maruff's unused mana.",},
			["Marukai"] = { content = "'''Marukai''' is a level 35 [[quest giver]] located at the [[Zoram'gar Outpost]] in the [[contested]] territory of [[Ashenvale]].\r\nShe gives the quest Naga at the Zoram Strand.\r\nSee [[List of Ashenvale NPCs]].",},
			["Marvon Rivetseeker"] = { content = "'''Marvon Rivetseeker''' is a level 40 [[quest giver]] located at the [[Broken Pillar]] in the [[contested]] territory of [[Tanaris]]. He studies the ancient areas of the world, and his workshop is located in the goblin town of [[Ratchet]]. He recently set off on an expedition in [[Tanaris]], and was last seen heading south from [[Gadgetzan]].\r\nHe starts the following quests:\r\n*Gahz'ridian\r\n*The Stone Circle\r\n**Into the Depths (Dungeon)\r\n**Secret of the Circle (Dungeon) (You can get both Into the Depths and Secret of the Circle at the same time, after finishing The Stone Circle)\r\nSee [[List of Tanaris NPCs]].",},
			["Marzon the Silent Blade"] = { content = "==Quests==\r\nObjective of The Attack!",},
			["Masked Orphan Matron"] = { content = "==Quests==\r\n*Fire Training \r\n*The Headless Horseman \r\n*Free at Last! (Horde) \r\n*Masked Orphan Matron",},
			["Mask of Death"] = { content = "Gives melee Heroes a vampiric attack that converts 50% of their attack damage into life.\r\n==Source==\r\n[[Thrall]] and [[Cairne Bloodhoof]] can find one in [[By Demons Be Driven]], chapter 8 of the [[Warcraft III: Reign of Chaos|Warcraft III]] orc campaign, [[The Invasion of Kalimdor]].\r\n[[Illidan]] can find one in [[The Brothers Stormrage]], chapter 8 of the [[Warcraft III: The Frozen Throne|Frozen Throne]] sentinels campaign, [[Terror of the Tides]].\r\n[[Illidan]], [[Kael]], [[Lady Vashj]] and [[Akama]] can find one in [[Lord of Outland]], chapter 6 of the alliance campaign, [[Curse of the Blood Elves]].",},
			["Masonary"] = { content = "'''The Masonary''' is located beneath the central rock of [[Blackrock Mountain]], beyond [[the Grinding Quarry]], just before the entrance to [[Blackrock Depths]].",},
			["Masophet the Black"] = { content = "'''Masophet the Black''' is one of the four lieutenants of [[Dar'Khan Drathir]], the master of [[Deatholme]]. Masophet is a skeleton mage and resides in one of two ziggurats - one near the slaughterhouse in eastern Deatholme, and the other near the slaughterhouse in southern Deatholme (usually near [[Borgoth the Bloodletter]], in other words).\r\n==Quests==\r\n* Dar'Khan's Lieutenants - from Magister Idonis at the [[Sanctum of the Sun]] in [[Ghostlands]]\r\n:Objective: \r\n::*Kill [[Borgoth the Bloodletter]]\r\n::*Kill [[Jurion the Deceiver]]\r\n::*Kill '''Masophet the Black'''\r\n::*Kill [[Mirdoran the Fallen]]",},
			["Massacre at Gruul's Lair"] = { content = "==Objectives==\r\n[[Baron Sablemane]] has tasked you and your friends with the deaths of 10 [[Bladespire Enforcer]]s, 5 [[Bladespire Battlemage]]s, 5 [[Bladespire Ravager]]s and their leader, [[Fingrom]]. When you have managed this feat, return to [[Baron Sablemane|him]] at the [[Circle of Blood]] in the [[Blade's Edge Mountains]].\r\nYou will need:\r\n* [[Bladespire Enforcer]] slain 0/10\r\n* [[Bladespire Battlemage]] slain 0/5\r\n* [[Bladespire Ravager]] slain 0/5\r\n* [[Fingrom]] slain 0/1\r\n==Description==\r\nYou've proven yourself resourceful, and now I think I'm going to put you to personal use in my own fight against Gruul and his sons.\r\nThe Bladespire clan are the favored of the gronn, and while you may have thinned out their numbers elsewhere, you haven't yet dealt with their strongest.\r\nGruul protects the exterior of his lair with only the toughest of ogres, and it is those that you must kill. Head north through the Daggermaw Canyon and you will find Gruul's Lair at the end.\r\n==Rewards==\r\nYou will receive:\r\n* 14600 [[XP]] (Translated to 8 gold 76 silver at 70)\r\n* 7 gold 40 silver (for a total of 16 gold 16 silver at 70)\r\n==Quest progression==\r\n* A Date with Dorgok\r\n** Favor of the Gronn\r\n** Pay the Baron a Visit\r\n** Into the Churning Gulch\r\n** Goodnight, Gronn\r\n** It's a Trap!(Alliance)\r\n*** Gorgrom the Dragon-Eater\r\n*** Baron Sablemane Has Requested Your Presence\r\n*** Massacre at Gruul's Lair",},
			["Massively multiplayer online game"] = { content = "A '''massively multiplayer online game''', or '''MMO''', or '''MMOG''', is a type of computer game that enables hundreds or thousands of players to simultaneously interact in a game world they are connected to via the Internet. Typically this kind of game is played in an online, multiplayer-only persistent world.\r\n[[World of Warcraft]] is a \"MMOG\" and a \"MMORPG\".\r\n==MMOGs compared to other computer games==\r\nThere are a number of factors shared by most MMOGs that make them different from other types of computer games. MMOGs create a persistent universe where the game continues playing regardless of whether or not anyone else is. Since these games strongly or exclusively emphasize multiplayer gameplay, few of them have any significant single-player aspects or client-side [[Artificial Intelligence|artificial intelligence]]. As a result, players cannot \"beat\" MMOGs in the typical sense of single-player games. One exception is \"Star Sonata,\" a free-download MMOG located at \r\nMost MMOGs also share characteristics that make them different from other multiplayer online games. MMOGs host a large number of players in a single game world where all those players can interact. Popular MMOGs might have thousands of players online at any given time usually exclusively on a company owned server. Non-MMOs, such as ''Battlefield 1942'' or ''Half-Life'' usually have less then 50 players online and are usually played on private servers. Also, MMOs do not have any significant [[modification|mods]] since the game must work on company servers. MMOs are special in having spawned [[Virtual Economy|virtual economies]] of game items, something that other game types have not yet created. \r\nThere is some debate if a high head-count is the requirement to be a MMO. Some say that it is the size of the game world and its capability to support a large number of players that should matter. For example, despite technology and content constraints, most MMOGs can fit up to a few thousand players on a single game server at a time. Given technology development online multiplayer may eventually become MMOs as well as the average server size increases. However, by then the benchmark may have increased as well and MMO's will host many times even that. Alternatively, if the defining characteristic of MMOs is that all the players must be in a single-world where they can interact, online games with a highly fragmented un-connected sever base are not MMOs.\r\nTo support all those players, MMOGs need large-scale game worlds. In MMOGs, large areas of the game are interconnected within the game such that a player can traverse vast distances without having to switch servers manually. For example, ''Tribes'' comes with a number of large maps a server plays in rotation (one at a time), but in the MMOG ''PlanetSide'' all map-like areas of the game are accessible via flying, driving, or teleporting.\r\nThere are few more common differences between MMOGs and other online games. Most MMOGs charge the player a monthly fee to have access to the exclusive servers. The game state in a MMOG rarely resets; what the player earned yesterday is with them still today. MMOGs often feature in-game support for clans and guilds, such as the ability to manage an association with in-game tools.\r\nThe boundaries between multiplayer online games and MMOGs are not always clear or obvious. ''Neverwinter Nights'' (2002) and ''Diablo II'' are usually called online RPGs, but are also sometimes called MMORPGs (a type of MMOG).\r\nThe popularity of MMOGs is mostly restricted to the computer game market. Online games have not yet gained huge audiences on console game systems. Nevertheless, there have been several console MMOGs, including ''Phantasy Star Online'' (Dreamcast), ''EverQuest Online Adventures'' (PlayStation 2), and the multi-platform ''Final Fantasy XI'' (Microsoft Windows, Playstation 2, and Xbox 360).\r\n==Types of MMOGs==\r\nThere are several types of massively multiplayer online games.\r\n===ARG===\r\nAlthough not prefixed with '''MMO''', ARGs (Alternate Reality Games) are massively multiplayer, allowing thousands of players worldwide to co-operate in puzzle trails and mystery solving.\r\n===MMORPG===\r\nMassive multiplayer online [[Role Playing Game|role-playing games]], known as MMORPGs, are perhaps the most famous type of MMOG.\r\n===MMOFPS===\r\nSeveral MMO first-person shooters have been made. These games provide large-scale, team-based combat. The addition of persistence in the game world means that these games add elements typically found in RPGs, such as [[experience point]]s. The first MMOFPS was probably ''10SIX'', released in 2000. Other popular MMOFPS games include ''World War II Online'' and ''PlanetSide''.\r\n===MMORTS===\r\nA number of developers have attempted to bring [[Real Time Strategy|real-time strategy]] games into the MMOG fray. Some notable MMORTS games include ''Mankind'', ''Shattered Galaxy'', and ''Ballerium'', which is still in development.\r\n===Others===\r\nMost other MMOs are apparently simulation games, such as ''Motor City Online'', ''The Sims Online'' (though this is often called an MMORPG), ''Ace of Angels'', and ''Jump Gate''. There are also games like ''Second Life'' and ''There'' that derive from the tradition of MUSHes, emphasizing socializing and world-building.\r\nAn interesting variation from the classic MMOs is ''Game Neverending'' - a \"game of social, political and economic actions\" which was announced in 2002 and is still in closed beta.\r\nIn April [[2004]], the United States Army announced that it is developing a massively multiplayer training simulation called ''AWE'' (asymmetric warfare environment) that is expected to begin operation among soldiers by June. The purpose of ''AWE'' is to train soldiers for urban warfare and there are no plans for a public commercial release. Forterra Systems Inc. is developing it for the Army based on the ''There'' engine.\r\n==History==\r\nThe first type of MMOG was the MMORPG. MMORPGs themselves trace their roots to MUDs, Bulletin board system (BBS) games, and browser-based games. As computer game developers applied MMO ideas to other computer and video game genres, new acronyms started to develop, such as MMORTS. ''MMOG'' emerged as a generic term to cover this growing class of games. These games became so popular that a magazine, called ''Massive Online Gaming'', released an issue in October 2002 hoping to cover MMOG topics exclusively, but it never released its second issue.\r\n==Naming==\r\nBy applying MMO to a number of different genres, and sometimes to multiple genres at once, game developers, gamers, and marketing departments have created long and obscure acronyms. One humorous example is \"SFMMORPGRTSFPS\" once used to describe ''PlanetSide'' (\"sci-fi, MMORPG, RTS, FPS\"). There have been a number of attempts to popularize new names, but \"MMO\" and \"massively multiplayer\" became gaming buzzwords in the late 1990s and early 2000s. ''Massive Online Gaming'' magazine attempted to shorten the name to just \"massive online gaming\" (or \"MOG\"), but few used this version. MMO had entrenched itself as a selling point for many games.\r\nAnother small controversy exists over whether it is \"massively multiplayer\" or \"massive multiplayer\" (without the \"-ly\"). Some say that massive multiplayer emphasizes the nature of the game over how many players actually play it. Others also prefer massive since they believe that ''multiplayer'' is an absolute adjective and cannot be sensibly modified by the adverb ''massively'' (e.g., just like \"very dead\"). Many gamers feel that the issue is trivial.",},
			["Massive Iron Axe"] = { content = "The '''Massive Iron Axe''' is a [[Blacksmithing]]-crafted two-handed axe with a [[stamina]] and [[strength]] bonus.\r\n==Source==\r\nThe '''Massive Iron Axe''' is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 185.\r\nThe components are:\r\n*14 [[Iron Bar]]s\r\n*2 [[Strong Flux]]\r\n*2 [[Heavy Grinding Stone]]\r\n*4 [[Gold Bar]]s\r\n*2 [[Heavy Leather]]\r\nPlans: Massive Iron Axe are a [[Limited Sale Recipe]] sold by :\r\n*[[Vharr]] in [[Grom'gol Base Camp]] in [[Stranglethorn Vale]]\r\n*[[Jaquilina Dramet]] at [[Nesingwary's Expedition]] in [[Stranglethorn Vale]]\r\n==Massive Iron Axe as a Quest Objective==\r\n*Arms for the Field (Horde)\r\n*The Way of the Weaponsmith (Alliance) from [[Ironus Coldsteel]] in [[Ironforge]]\r\n*The Way of the Weaponsmith (Horde) from [[Borgosh Corebender]] in [[Orgrimmar]]",},
			["Mass Dispel"] = { content = "'''Mass Dispel''' is a new level 70 [[priest]] [[spell]] in [[Burning Crusade]] available from a [[trainer]]. It can remove Paladin [[Divine Shield]] and Mage [[Ice Block]] abilities, as well as other normally undispellable Magic effects like the Banish some mobs use.\r\nAs of 2.0.8, this spell had a very annoying game mechanic bug concerning the normally undispellable magic effects. If the paladin or mage had any other buffs on them besides Divine Shield or Ice Block, Mass Dispel would try to remove these other magic effects.\r\n==Notes==\r\nThe spell targets those closest to the casting Priest first, and then moves outward.\r\n==Talents==\r\n*[[Absolution]]\r\n*[[Focused Power]]\r\n===Patch 2.0.10===\r\nAs of [[Patch 2.0.10]] Mass Dispel has been changed to always pick immunity granting effects as its target. Note that even if Ice Block, Divine Shield, Divine Protection or Banish are dispelled by Mass Dispel, you'll still get the immune message even though it has been removed.\r\n===Patch 2.2.0===\r\nAs of [[Patch 2.2.0]] Mass Dispel has a chance to be resisted when dispelling immunity effects. This will be displayed to the combat log. In addition, it will no longer cause [[Rogue]]s and [[Druid]]s in [[Cat Form]] to lose [[Stealth]]. The flashing area graphic has been removed.\r\n===Patch 2.4===\r\n[[Patch 2.4]] increased the number of affected targets from 5 to 10.",},
			["Master's Cellar"] = { content = "'''The Master's Cellar''' is an area riddled with level 68-70 [[ghost]]s in the southernmost portion of [[Deadwind Pass]], just south of [[Karazhan]]. It is below the ruins of a small town, probably the former home of servants that worked in the nearby tower. \r\nThere are two separate entrances to the Master's Cellar. One leads into a vast wine cellar, filled to the brim with [[Unliving Resident]]s, [[Unliving Caretaker]]s, [[Damned Soul]]s, [[Restless Shade]]s, and [[Wailing Spectre]]s. The other leads into a similar cellar, but here the floor has collapsed into a cave system leading deep underground. The second cellar and cave system are also filled with the same type of undead, and there are no named or rare undead of any type to be found.\r\n==Quests==\r\n*Arcane Disturbances\r\n*Restless Activity",},
			["Master's Glaive"] = { content = "The '''Master's Glaive'''[39,87] is located in the southwest part of [[Darkshore]]. To the west of Darkshore stands a mysterious monument, a massive adamantine glaive buried in an unmovable boulder called the Old God Skull. The night elves consider this a sacred area, as they believe the mysterious titans, creators of the world, are the only ones who could have wielded the gigantic glaive. It appears as a snail shell-like skull, with a massive weapon imbedded in the crown. It is the site of an enormous skeleton [[forgotten one]]. It is believed that a Titan killed one of the Old Gods or one of their minions here.\r\nThis unusual monument is surrounded by a small lake. While it was once a night elf holy place, the area is now under the control of the Twilight’s Hammer. They believe the statue is some sort of divine corpse — the remains of an Old God. The term \"Master’s Glaive\" refers to part of the monument — the sword embedded in the skull.\r\nThere are rumors of a complex underground labyrinth underneath the remains.\r\nThe shell has holes where presumably eyes should be, and tentacles are draped around the area, giving it an appearance similar to a kraken. The [[Twilight's Hammer]] have chosen it as a location for one of their dark altars.\r\nA popular theory is that this is the place where one of the [[Old Gods]] fell to the might of the [[Titan]]s. [[Onu]] refers to it being where an \"old lord of the earth\" fell long ago in the quest [[Quest:The Master's Glaive|The Master's Glaive]]. \r\nSome speculate that the sword is [[Taeshalach]], half of the great sword of [[Sargeras]] called [[Gorshalach]]. However, it is said that [[Aggramar]] currently wields Taeshalach.\r\n \r\nIt is confusing why titans would have impaled an old god and left such a powerful a weapon in its dead corpse. Some theorize that the sword in its remains prevents it from regenerating and putting Azeroth in danger once again. The [[Twilight's Hammer]] are worshipping the Old God's remains, and perhaps they are trying to reawake it by removing the sword from the creature.",},
			["Masterwork Stormhammer"] = { content = "'''Masterwork Stormhammer''' is a crafted main-hand hammer made by Hammersmiths with a powerful AoE proc. \r\n==Source==\r\nThis item is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 300 who also have the Hammersmith specialty.\r\nThe components are:\r\n*20 [[Enchanted Thorium Bar]]s\r\n*8 [[Huge Emerald]]s\r\n*8 [[Large Opal]]s\r\n*6 [[Essence of Earth|Essences of Earth]]\r\n*4 [[Enchanted Leather]]\r\nThe [[plans]] drops off [[Goraluk Anvilcrack]] in the [[Blackrock Spire]].\r\n==Background==\r\nThe masterwork version of the traditional Wildhammer [[stormhammer]].",},
			["Masterwork Target Dummy"] = { content = "'''Masterwork Target Dummy''' is a consumable device used to control aggro.\r\n==Source==\r\nMasterwork Target Dummy is crafted by [[Engineering|Engineers]] with a minimum skill level of 275.\r\nThe components are:\r\n*1 [[Mithril Casing]]\r\n*1 [[Thorium Tube]]\r\n*2 [[Thorium Widget]]\r\n*2 [[Truesilver Bar]]\r\n*2 [[Rugged Leather]]\r\n*4 [[Runecloth]]\r\nThe recipe for this item is taught by Schematic: Masterwork Target Dummy.\r\nThis [[schematic]] is a [[limited sale recipe]] that can be purchased for 1 gold 60 silver copper from Xizzer Fizzbolt in [[Winterspring]].\r\n==Notes==\r\n*Once the target dummy is destroyed, items can be looted from it; sometimes including [[Fused Wiring]]",},
			["Mastery: Master Demonologist"] = { content = "Tree: [[Demonology]]\r\nGrants both the Warlock and the summoned demon an effect as long as that demon is active:\r\n* [[Imp]] - Reduces [[threat]] caused by 4% / 8% / 12% / 16% / 20%.\r\n* [[Voidwalker (Warlock pet)|Voidwalker]] - Reduces [[Physical|physical damage]] taken by 2% / 4% / 6% / 8% / 10%.\r\n* [[Succubus (Warlock pet)|Succubus]] - Increases all [[damage]] by 2% / 4% / 6% / 8% / 10%.\r\n* [[Felhunter]] - Increases all [[resistance]]s by 0.2 / 0.4 / 0.6 / 0.8/ 1 per [[level]].\r\n* [[Felguard (Warlock pet)|Felguard]] - Increases all damage caused by 1% / 2% / 3% / 4% / 5% and all resistances by .1/.2/.3/.4/.5 per level.",},
			["Master Apothecary Faranell"] = { content = "'''Master Apothecary Faranell''' is a [[Forsaken]] [[quest giver]] located in the [[Apothecarium]] in the [[Forsaken]]'s [[Undercity]]. He is a [[doctor]] or has at least some type of a doctorate, and enjoyed experimenting with different brews and tinctures, trying this or that to cure something or improve one's life.\r\nFaranell and his alchemist minions work to brew their newest toxins, as well as creating more powerful [[abomination]]s to serve the Forsaken. As the Master of the Apothecarium, he oversees the most ambitious of their alchemical attempts.\r\n==History==\r\nIn life, Faranell was a respected alchemist of great renown and spent the better part of his days studying medicine amongst the learned wizards of [[Dalaran]]. He enjoyed nothing more than experimenting with concoctions of every sort, always looking to create a serum for this, an antidote for that. After he died from the [[Plague of Undeath|plague]] and rose as one of the [[Forsaken]], his limitless curiosity was twisted by depthless sadism. Faranell became one of the foremost experts on the undead plague and is loyal to the Banshee Queen. Now Faranell uses his skills in service to [[Queen Sylvanas]] and [[Grand Apothecary Putress]] by crafting alchemical monstrosities and designing newer, more devastating and virulent plagues and toxins.\r\n===World of Warcraft===\r\nFaranell worked with other apothecaries on toxins and the [[New Plague]]. [[Apothecary Renferrel]] sent a [[Horde]] [[adventurer]] with [[Grizzled Bear Heart|bear hearts]] and [[Skittering Blood|spider blood]] to Faranell for study their toxic and contaminable properties. Faranell then asked the adventurer to go to [[Pyrewood Village]] to retrieve the [[Berard's Journal|journal]] of his former colleague, now the crazed [[worgen]] [[Apothecary Berard]], and bring it to Renferrel. From the journal, Renferrel learned about ingredients that could help in the creation of the new plague. After the adventurer collected moss and tumor from [[bog beast]]s and [[murloc]]s, they brought them to Faranell. From the journal's notes, Faranell was able to create the new plague.\r\nLater, Faranell worked with [[Apothecary Lydon]] on a new elixir. Lydon asked him to apply his colloid of decay on [[:Mudsnout Composite]], and Faranell then directed the adventurer to gather more reagents in order to activate the contaminating agents in the [[:Mudsnout Mixture]].\r\nAfterward, Faranell asked for a [[:Kraul Guano]] from the [[Kraul Bat|bats]] in [[Razorfen Kraul]]. With the guano experiment, he wanted to observe what effect two diametrically opposed chemical substances can have on each other, with an added ever-toxic agent. Thus he sent the adventurer to collect hearts of the [[Scarlet Crusade]] members in the [[Scarlet Monastery]].\r\nLater, [[Lydon]] sent him [[Shadra]]'s poison for testing.\r\n===Arthas: Rise of the Lich King===\r\nFaranell showed a [[New Plague]]'s effect as two prisoners, a [[human]] female and a [[Forsaken]] male drank it and decomposed. [[Sylvanas Windrunner]] was pleased with this result, but warned Faranell that the blight should never fall into the wrong hands.\r\n==Abilities==\r\n[[Battle for Darkshore]]\r\n*\r\n==Quests==\r\n*[[Throwing Blight]] \r\n*[[Fish Head]] \r\n*[[The Undercity (quest)]] \r\n*[[A Recipe For Death]] \r\n**[[A Recipe For Death (2)]] \r\n***[[A Recipe For Death (3)]] \r\n*[[Elixir of Agony (2)]] \r\n**[[Elixir of Agony (3)]] \r\n*[[Going, Going, Guano! (Classic)]] \r\n**[[Hearts of Zeal]] \r\n*[[Venom to the Undercity]] \r\n==Objective of==\r\n*[[Southshore Sabotage (Alliance)]]\r\n===Gossip===\r\nAfter the Wrathgate event\r\n*It's true [[Kor'kron|our new... guests]] are limiting our work somewhat, but it is only natural to be wary when a genocidal attempt is made. Perhaps in time they will be convinced that [[Grand Apothecary Putress|Putress]] was an unfortunate anomaly and allow us to continue our work in peace.\r\nKor'kron gone\r\nIt is so nice to see the Undercity returned to the calming wheezes and gas-expulsions of the abominations. The orcs smelled far worse.\r\nHall of Shadows\r\nWhen that brute Kraggosh and his overseers moved into the Undercity, we were forced to do our real work in secret. Surely you can see how such an arrangement inevitably led me here.\r\n===Dialogue===\r\nConversation with [[Overseer Kraggosh|Kraggosh]]:\r\n===Introduction===\r\nHe is the leader of the the [[Royal Apothecary Society]]. Sylvanas had initially chosen two brilliant minds to lead her new Apothecary Society: Faranell, a [[human]] [[wizard]] who excelled in magical potion creation, and [[Oni'jus]], a [[half-elf]] [[infiltrator]] who was a master of mundane poison concoction (and whose idea it was to add \"Royal\" in front of their fledgling group’s name). A [[dwarf]] [[tinker]], [[Brightflame Masjenal]], later rounded out her three leaders, with Faranell leading the three.\r\n===Biography===\r\nThe first Royal Apothecary member, this human was a [[wizard]] taken by the [[Scourge]] at Dalaran. A personal friend of [[Jaina Proudmoore]], he watched as she failed to protect her people from her former lover. He hates the [[human]]s and the [[Alliance]] almost as much as he hates the Scourge for taking his life. The [[Lich King]] paid him little interest as he never showed much promise with [[necromancy]], which left his will free enough to be rescued by Sylvanas. Despite his inability to create death [[magic]], he is a valuable asset as his skill at crafting potions is unparalleled. He leads the Research & Development branch of the Society and urges the wizards and sorcerers under him to develop their death magic so that the forsaken will have the might to go against the Scourge some day. He adores his Lady and daily his heart aches more and more for her, but love is not for the undead, only sorrow and loss. He looks like most of the undead in the Society, as his body is covered in sores and rotting flesh. He is permanently stooped from some crushed vertebrae he suffered in the fall of Dalaran. He looks no one in the eye except for his queen, upon whom he gazes adoringly.\r\nThe apothecary Faranell headed the project to create a master plague, similar to Ner'zhul's, to wipe out the living races as well as the Scourge, constructing a new plague to wipe out all of humanity and the Forsaken’s nemesis. For a long time the society had not yet produced results. Since the world at large refused to accept them as people instead of undead, they continued their dark designs to eliminate all non-Forsaken life forms on Azeroth. However, for a while their plague only killed only humans, and didn't affect the Scourge at all. The Royal Apothecary Society believed that their usefulness to the Dark Lady was coming to an end. If they couldn't finish their master plague, they were worried their Society would be disbanded. Due to repeated failures by the society to make a new plague of undeath, Sylvanas recruited necromancers to find other means of raising slain enemies, into her cause.\r\nThe figure is hunched over, clutching a withered staff for support as if his body is too feeble to remain standing without assistance. Dressed in a dark cloth robe, the figure is emaciated and pale, with skin stretched tightly across his bony frame. He is surrounded by an almost sickeningly sweet odor, apparently emanating from several pouches of herbs and reagents located on the chest of his robe. Two wands dangle from his belt, clinking against each other as he moves. Master Apothecary Faranell is an expert alchemist who prefers to avoid direct combat, but is resigned to it as a means of periodically acquiring new test subjects for his experiments. Faranell always prefers to incapacitate enemies with spells rather than kill them outright, in order to maximize their usefulness as “volunteers.” His first actions in combat are to cast greater invisibility or another more appropriate defensive spell on himself and then move to a location with an easy escape route. He then attempts to hamper his enemies with stinking cloud and cripple and uses mana burn to disrupt enemy spellcasters. As a last resort, Faranell uses his wand of frost nova to finish off wounded enemies, not hesitating to include himself in the blast radius due to his immunity to cold.\r\n==Notes and trivia==\r\n*[[Mathias Shaw]] reported that prior to the [[Battle for Lordaeron]], they managed to get the upper hand on Faranell, and an [[SI:7]] agent retrieved [[:Berard's Journal]] from him.\r\n*Even though Kraggosh's status was changed and the Kor'kron forces removed from the city, Faranell retained his quote about their \"new guests\" for some time until it was fixed at one point..\r\n*[[Master Apothecary Faranell]] was described as the leader of the [[Royal Apothecary Society]], however in ''[[World of Warcraft: Sylvanas]]'', it was established that [[Grand Apothecary Putress]]' was the societies original leader with Faranell being revealed as one of his subordinates.\r\n**As the ''Ultimate Visual Guide'' entry kept the timeframe of leading vague, only saying that \"Faranell now leads the Society\", it could be interpreted as relating to the present time of UVG's timelines (MoP & WoD) instead of the past.",},
			["Master Builder's Shirt"] = { content = "*The '''Master Builder's Shirt''' is a rare shirt drop from [[Fineous Darkvire]].\r\n*This shirt is one of only three Bind on Pickup (BOP) shirts that currently are available to both factions. \r\n*The shirt's colors make it a good match for the rogue's [[Shadowcraft Armor]].\r\n==Source==\r\nThis is a rare drop from [[Fineous Darkvire]] in [[Blackrock Depths]].\r\n==Notes==\r\nThis item has a drop rate of approximately 4%.",},
			["Master Chef Mouldier"] = { content = "'''Master Chef Mouldier''' is a level 14 [[cooking trainer]] and [[vendor]] located at [[Tranquillien]] in the [[blood elf]] territory of [[Ghostlands]].\r\nHe starts the quest Culinary Crunch.\r\n==Teaches==\r\n*Boiled Clams\r\n*Coyote Steak\r\n*Crab Cake\r\n*Dry Pork Ribs\r\n*Goblin Deviled Clams\r\n*Spice Bread\r\n*Spiced Wolf Meat\r\n*Spider Sausage\r\n==Sells==\r\n*Hot Spices\r\n*Mild Spices\r\n*Recipe: Bat Bites\r\n*Recipe: Crunchy Spider Surprise\r\n*Recipe: Sagefish Delight\r\n*Recipe: Smoked Sagefish\r\n*Refreshing Spring Water\r\n*Simple Flour\r\n*Soothing Spices\r\n==Notes==\r\nMaster Chef Mouldier is the only source of the [[recipe]] for Bat Bites, making it a [[Faction exclusive recipes|horde-only recipe]].",},
			["Master Cookbook"] = { content = "==Source==\r\nThis item can be purchased for g=2 gold from:\r\n* Gaston in [[Hellfire Peninsula]]\r\n* Naka in [[Zangarmarsh]]\r\n* Baxter in [[Hellfire Peninsula]]",},
			["Master Elemental Shaper Krixix"] = { content = "'''Master Elemental Shaper Krixix''' is a level 60 [[elite]] [[goblin]] found in [[Blackwing Lair]].\r\n==Background==\r\nThe apprentice of the [[high elf]] [[Earthcaller Franzahl]]. He now resides in [[Blackrock Mountain]].\r\n==Notes==\r\nHe is an easy mob that summons 10 level 62 guardians. He can teach [[Smelt Elementium]]; to do this a [[priest]] must [[mind control]] him, the priest can then cast a spell that teaches you how to [[Smelt Elementium]]. This can be taught to anyone within 100yrd range regardless of [[profession]], although you have to be a [[miner]] to be able to use it.",},
			["Master Engineer's Goggles"] = { content = "'''Master Engineer's Goggles''' are cloth head armor that require 280 [[engineering]] to wear.\r\n==Source==\r\nMaster Engineer's Goggles are made by [[Engineering|Engineers]] with a skill of 290.\r\nThe components are:\r\n*1 [[Fire Goggles]]\r\n*2 [[Huge Emerald]]s\r\n*4 [[Enchanted Leather]]s\r\nThe recipe for this item is taught by Schematic: Master Engineer's Goggles, which is rarely dropped by [[Doomforge Arcanasmith]] in [[Blackrock Depths]].",},
			["Master Engineer Telonicus"] = { content = "'''Master Engineer Telonicus''' is one of the four blood elf advisors that aid [[Kael'thas]] during the boss encounter in [[the Eye]]. He appears to be a [[Hunter]].\r\nSee [[Kael'thas Sunstrider (tactics)]] for details on the fight.\r\n==Strategy==\r\nDuring the Phase 1 encounter hunters should lay snake traps for the tank to pull Telonicus through to reduce the chance of players being remote toyed.\r\nDuring Phase 3, the Telonicus tank can avoid bombs by continuously moving. Telonicus will often begin to only throw bombs while the tank is at range, allowing the tank to completely avoid bomb damage until melee are ready to kill him.\r\nOnce DPS begins on Telonicus, the tank should no longer attempt to avoid bombs -- bomb kiting can result in large numbers of DPS taking bomb damage without the mace's buff.\r\n===Encounter in The Eye===\r\n* \"Anar'alah Beloreh!\"\r\n* \"More perils await...\"",},
			["Master Gadrin"] = { content = "[[Master Gadrin]] is a level 12 [[quest giver]] located in [[Sen'jin Village]] in the [[orc]] and [[troll]] starting zone of [[Durotar]].\r\nGadrin is one of [[Vol'jin]]’s most trusted advisers. Along with a young witch doctor named [[Zalazane]], Gadrin led the mystical training of many [[Darkspear]] [[priest]]s and [[mage]]s. However, Zalazane went mad from the mystical forces he had unleashed. The crazed witch doctor placed a curse upon the [[Echo Isles]] and drove Gadrin and his brethren away. Now Gadrin seeks to end Zalazane’s rampage and put the souls of his cursed brethren to rest.\r\nSee [[List of Durotar NPCs]].\r\n==Quests==\r\nHe starts the following quests:\r\n*Report to Orgnil\r\n*Minshina's Skull\r\n*Zalazane\r\n*The Spider God (Dungeon)\r\n*Summoning Shadra (Elite)",},
			["Master Kang"] = { content = "'''Master Kang''' is a level 62 [[orc]] found near [[Ravenholdt Manor]] in the [[Alterac Mountains]].\r\nKilling Kang causes an increase of [[Syndicate]] [[reputation]] and a decrease of [[Ravenholdt]] reputation.",},
			["Master Kelerun Bloodmourn"] = { content = "'''Master Kelerun Bloodmourn''' is a level 30 [[quest giver]] located in [[Eversong Woods]] between [[Sunstrider Isle]] and the [[Ruins of Silvermoon]]. It is rumored that he wields [[Martin Thunder]], the apparent weapon of the [[Game Masters]].\r\nHe begins the following quests:\r\n*The Second Trial (1)\r\n*Return to Silvermoon",},
			["Master looter"] = { content = "A '''master looter''' or '''main looter''' (often abbreviated as '''ML''') is a [[player]] designated by the [[party]] [[leader]] to decide how [[loot]] is distributed in a [[party]] or [[raid]].\r\nMaster Loot is a good safeguard against ninjas when a guild or group includes characters they have never partied with before. With one trustworthy person being the only one to loot a boss's body and distribute the loot there is no chance of a ninja looting the body or selecting need or greed after everyone else has passed for rolling.\r\nHowever, some players are against using the Master Looter rules, possibly due to time issues, or because there is the risk of the Master Looter himself/herself being a ninja looter (which this loot system is meant to prevent).\r\n==How to distribute loot as the Master Looter==\r\nWhen the Master Looter (who is the Party Leader in a group of five, but can be assigned to someone else by a Raid Leader in a Raid), loots the body, the loot window comes up just like when playing solo. When the loot is clicked a submenu appears off to the side of that particular piece of loot listing every group in the raid. Each of those groups lists the people in that group when moused over. The Master Looter then clicks on the specific name of the character getting that piece of loot. When the Master Looter assigns a [[Bind on Pickup]] piece of loot, they also get an alert verifying that the loot is definitely supposed to go to that person.\r\n==Warning==\r\nAny loot on a dead mob can only be looted by the player who was Master Looter at the time that mob was killed. If the Master Looter leaves the party, no one else will be able to loot that mob.\r\n==See also==\r\n*[[Loot|Looting While In A Party]]\r\n*[[Party|Looting]]",},
			["Master of Deception"] = { content = "'''Master of Deception''' is a [[Rogue]] talent located in the 1st tier of the [[Rogue_talents|Subtlety Tree]]. Each rank increases effectiveness.",},
			["Master of Elements"] = { content = "'''Master of Elements''' is a popular PvE talent for any talent build with more than 15 points in the [[Fire]] tree. It restores up to 10/20/30% of the mana cost of a [[Fire]] or [[Frost]] spell that critically hits one or more targets (so [[AoE]] spells such as [[Flamestrike]], [[Cone of Cold]] and [[Blast Wave]] are affected by this talent). Since most mages critically hit between 20 and 40% of the time this talent is equivalent to an effective mana cost reduction to Fire and Frost spells.\r\nOther talents that reduce mana cost include [[Elemental Precision]], which reduces mana cost of Fire and Frost spells up to 3% directly, and [[Frost Channeling]] which reduces the mana cost of Frost spells only by up to 15% directly. In addition [[Pyromaniac]] also reduces the mana cost and increases the critical strike chance of all [[Fire]] spells by 1%/2%/3%. [[Pyromaniac]] is deep in the [[Fire]] tree next to [[Combustion]].",},
			["Master of Pain"] = { content = ":''Are you looking for statistics? See [[Warcraft III Units]].''\r\n==History==\r\nThe '''Master of Pain''' was a powerful [[doomguard]] champion who lived in red desert of [[Outland]] under the command of [[Magtheridon]].He guarded treasure in [[Magtheridon]]'s [[Black Temple]]. He was killed when a force of [[blood elves]] and [[Broken draenei|draenei]] under the command of [[Akama]] and [[Kael]] (themselves serving [[Illidan]]) assaulted the Temple. Upon his death and the [[Mistress of Torment]], the gates to the Throne Chamber opened.",},
			["Master of Subtlety"] = { content = "'''Master of Subtlety''' is a 25 point [[Rogue]] talent located in the 6th tier of the [[Rogue_talents|Subtlety Tree]].\r\n==Notes==\r\nThe effect of this talent is indicated in the Damage tooltip in Character sheet. \r\nA rogue who wants to do as much Ambush damage as possible should take this talent.",},
			["Master Pyreanor"] = { content = "'''Master Pyreanor''' is a level 70 [[paladin trainer]] located in [[Grommash Hold]] in [[Orgrimmar]] - the only Horde paladin trainer in Kalimdor (and the second outside of Quel'Thalas, the first being [[Champion Cyssa Dawnrose]]). He and two Blood Knight Honor Guards stand where [[Nazgrel]] was before he was moved to Outland.\r\nHis official duty is to protect the Blood Elf ambassador in Orgrimmar but he eagerly trains and spars any fellow Paladin he can find, to help with what he deems a boring assignment. \r\nSee [[Orgrimmar NPCs]] and [[list of blood elves in Azeroth]].",},
			["Master Sergeant Biggins"] = { content = "'''Master Sergeant Biggins''' is a level 55 [[PvP]] accessories [[vendor]] located in the [[Champions' Hall]] in the [[human]] city of [[Stormwind]].\r\nSee [[List of Stormwind NPCs]].",},
			["Master Sergeant Lorin Thalmerok"] = { content = "'''Master Sergeant Lorin Thalmerok''' is a level 58 [[stable master]] located at [[Honor Hold]] in the [[contested]] territory of [[Hellfire Peninsula]].\r\nSee [[List of Hellfire Peninsula NPCs]].",},
			["Master Smith Burninate"] = { content = "'''Master Smith Burninate''' is a level 52 general goods, [[blacksmithing]], [[meat]] and [[drink vendor]] located at [[Thorium Point]] in the [[contested]] territory of [[Searing Gorge]]. He is a quest giver for the [[Thorium Brotherhood]], and his quests can be repeated to get Thorium Brotherhood reputation up to Honored.\r\nHis name may or may not be a reference to Homestar Runner's Trogdor the Burninator.\r\nHe starts the following quests:\r\n* What the Flux?\r\n* Restoring Fiery Flux Supplies via Heavy Leather (Skinning, Repeatable)\r\n* Restoring Fiery Flux Supplies via Iron (Mining, Repeatable)\r\n* Restoring Fiery Flux Supplies via Kingsblood (Herbalism, Repeatable)\r\n* Gaining Acceptance (Friendly, Repeatable)\r\nSee [[List of Searing Gorge NPCs]].",},
			["Master Tactician"] = { content = "'' \"He's more vulnerable than you'd think. All we have to do is hit him... here.\" ''\r\n'''Master Tactician''' is a tier-8 talent in the Hunter Survival Tree. Your ranged attacks gain a 6% chance to increase your critical strike chance with all attacks by 2-10% for 8 seconds. \r\n==Notes==\r\nThis is an unreliable, but useful way to increase the hunter's crit chance. Survival gives up some DPS potential for control (much like a frost Mage), but this makes up for it. To get the most out of this talent, one needs a fast weapon, frequent use of instant attacks, and an item/buff that affects their haste.",},
			["Master Trainer"] = { content = "#redirect [[Trainer]]", redirect = "Trainer",},
			["Master Vornal"] = { content = "'''Master Vornal''' is a level 11 [[quest giver]] located in [[Sen'jin Village]] in the [[orcish]] starting zone of [[Durotar]].\r\nHe starts the quest A Solvent Spirit.\r\nSee [[List of Durotar NPCs]].",},
			["Mastok Wrilehiss"] = { content = "'''Mastok Wrilehiss''' is a level 30 [[quest giver]] located at [[Splintertree Post]] in the [[contested]] territory of [[Ashenvale]]. \r\nHe is really powerful 30 [[Elite]], has about 20.000 hp, immune to most [[CC]]s and enrages at 50%.\r\nHe gives the following quests:\r\n* Stonetalon Standstill\r\n* Je'neu of the Earthen Ring\r\nHe finishes the quest:\r\n* The Befouled Element\r\nSee [[List of Ashenvale NPCs]].",},
			["Mast Room"] = { content = "The '''Mast Room''' lies beyond the second set of mines, and is where adventurers first encounter [[goblin]]s inside [[the Deadmines]]. It is occupied by [[Goblin Woodcarver|goblin woodcarvers]] as well as [[Sneed]] and [[Sneed's Shredder|his shredder]].",},
			["Mathias Shaw"] = { content = "'''Master Mathias Shaw''' is a level 62 quest giver located in [[SI:7]] in [[Old Town]], in the [[human]] city of [[Stormwind]]. He is the head of the organization known as SI:7, the agency of intelligence for the city of Stormwind, and in fact much of the [[Alliance]]. From his base of operations in the barracks of Old Town, he coordinates reconnaissance efforts for many agents of the Alliance regarding matters as far apart as the [[Defias Brotherhood]] to the [[Undead]] [[Scourge]]. Shaw is also a master of stealth and infiltration tactics himself, and specializes in operations involving the [[rogues]] in the employ of the Alliance. He is also leader of the [[Stormwind Assassins]]. Shaw was a childhood friend of [[Edwin VanCleef]], and personally trained him as a rogue.\r\nMathias Shaw is a young man to lead such a powerful organization, but the 33-year-old isn’t daunted. His mother was a First Finger assassin who died on the job when he was 4 years old. He grew up at Grandmother Pathonia’s knee, as the founder of the guild did not see fit to lie to him about her death or his family’s business. He was the youngest member of the guild when his grandmother made him a Fourth Finger at 10, and he worked his way up slowly, spending much more time in the various levels than most. This worked very well for him, as he knows intimately what is done at every level, and what is needed in new recruits. When his grandmother passed control to him on his 30th birthday, choosing to retire instead of die and leave things in disarray for him, he eagerly took the reins. He attempted to make improvements on her designs, but after a couple of months finally had to accept that her design was flawless, and he simply needed to run the already well-oiled machine. He has deep brown eyes and is diminutive, very unassuming for a guild leader of assassins. His first kill was the target his mother had failed to eliminate.\r\nHe starts the following quests:\r\n* Snatch and Grab\r\n* The Defias Brotherhood (4)\r\n* Mathias and the Defias\r\n* The Touch of Zanzil\r\n* Look to an Old Friend\r\n* Brotherhood's End\r\n* Honor the Dead\r\nSee [[List of Stormwind NPCs]].",},
			["Mathogg"] = { content = "'''Mathogg''' was an [[orc]]ish military leader who led an orcish encampment north of the [[Darkspear]] village during the [[Third War]].\r\nThe encampment was raided by the [[Kolkar]] [[centaur]] and its inhabitants were taken captive. He was found by [[Rexxar]], [[Rokhan]] and [[Chen Stormstout]], who agreed to help the captured Orc. The trio of heroes hunted down and killed the Kolkar Khan [[Khan Gragtor|Gragtor]], taking from him the key needed to release Magthogg and his comrades. Upon release, Mathogg vowed that, now that his people were safe, he would travel to [[Orgrimmar]] to lend his services to the [[Horde]].",},
			["Mathredis Firestar"] = { content = "'''Mathredis Firestar''' is a level 60 [[quest giver]] located at [[Flame Crest]] in the [[contested]] territory of [[Burning Steppes]]. He is an [[mage|arcanist]] who seeks to slake his racial magic addiction by feeding off of the energies released during the creation of [[Arcanum]]s, powerful magic gems invented by Mathredis's deceased master, [[Kariel Winthalus]], who was murdered in [[Dire Maul]] while attempting to gain knowledge from the [[Shen'dralar]] ancients therein. \r\nWhile his master's three most powerful arcanums are beyond his abilities, Mathredis can create the Lesser Arcanums of Constitution, Resilience, Rumination, Tenacity and Voracity when provided with the proper [[libram]]s and magical materials.\r\nHe starts the following quests:\r\n* Libram of Constitution\r\n* Libram of Resilience\r\n* Libram of Rumination\r\n* Libram of Tenacity\r\n* Libram of Voracity\r\n==See also==\r\n*[[Burning Steppes NPCs]]\r\n*[[List of blood elves in Azeroth]]\r\n*For his old model,",},
			["Matilda"] = { content = "'''Villager Matilda''' was [[Villager Gerard]]'s wife. Villager Gerard had his ledge stolen by the bandit [[Menag]] when [[Arthas]] was in [[Strahnbrad]]. [[Arthas]] killed [[Menag]] and gave the ledger back.",},
			["Matrix Punchograph 3005-B"] = { content = "#REDIRECT [[Matrix Punchograph 3005]]", redirect = "Matrix Punchograph 3005",},
			["Matrix Punchograph 3005-D"] = { content = "#REDIRECT [[Matrix Punchograph 3005]]", redirect = "Matrix Punchograph 3005",},
			["Matrix Punchograph 3005"] = { content = "Matrix Punchograph 3005 is a [[fixed device]] located throughout [[Gnomeregan]]. There are four models: 3005-A, 3005-B, 3005-C and 3005-D. These [[device]]s are [[use]]d in Data Rescue and to gain access to [[schematic]]s.\r\n*Matrix Punchograph 3005-A access via White Punch Card (a [[Static drop]] from [[mob]]s in [[Gnomeregan]]) grants Yellow Punch Card.\r\n*Matrix Punchograph 3005-B access via Yellow Punch Card grants Blue Punch Card. The [[schematic]] for Minor Recombobulator can also be accessed by [[Engineer]]s with 140 [[skill]].\r\n*Matrix Punchograph 3005-C access via Blue Punch Card grants Red Punch Card.\r\n*Matrix Punchograph 3005-D access via Red Punch Card grants Prismatic Punch Card. The [[schematic]] for Discombobulator Ray can also be accessed by [[Engineer]]s with 160 [[skill]] and a Security DELTA Data Access Card.",},
			["Matron Protectorate"] = { content = "#redirect [[Haleh]]", redirect = "Haleh",},
			["Matron Qualia"] = { content = "'''Matron Qualia''' is a level 64 general goods [[vendor]] located at [[Garadar]] in the [[contested]] territory of [[Nagrand]].\r\nSee [[List of Nagrand NPCs]].",},
			["Matron Varah"] = { content = "'''Matron Varah''' is a level 60 [[innkeeper]] located at [[Mok'Nathal Village]] in the [[contested]] territory of [[Blade's Edge Mountains]].\r\nSee [[List of Blade's Edge Mountains NPCs]].",},
			["Matters of Security"] = { content = "==Objectives==\r\nZerid at Aeris Landing in Nagrand wants you to kill 12 Voidspawn near Oshu'gun.\r\nKill:\r\n* 12 [[Voidspawn]]\r\n==Description==\r\nGezhe chose to base our operations as close to Oshu'gun as possible, without any regard for the safety of our crew. Why? Because he projected a ten percent increase in productivity by setting up shop here instead of in the mountains to the south.\r\nNever mind the crazed voidspawn wandering all of ten feet away from us. That would be the security officer's problem, not Gezhe's.\r\nKill some voidspawn for me and I'll pay you a tenth of our security budget. Don't get excited, it's not much of a budget.\r\n==Reward==\r\nYou will receive: 3 gold 50 silver copper \r\n==Completion==\r\nYou bring a smile to my face, <name>. Or you would, rather, if I had a face.\r\nKeep it up and you and I are going to be the best of friends.",},
			["Matthew Yang King"] = { content = "'''Matthew Yang King''' is a voice actor who has provided several voices for ''World of Warcraft'' and its various expansions. He couldn't reprise his job as Illidan in [[World of Warcraft: The Burning Crusade]] due to guild union issues.\r\n==Credits==\r\n*[[Illidan Stormrage]]\r\n*[[Pandaren (playable)|Pandaren]] Male\r\n*[[Haiyan the Unstoppable]]\r\n*[[Shan Bu]]\r\n*[[Margrave Dhakar]]\r\n*[[Master Windstrong]]\r\n*[[Cato]]",},
			["Matthias Lehner"] = { content = "'''Matthias Lehner''' is a [[ghost]]ly child who appears in several locations in [[Icecrown]], and offers several quests related to the [[Lich King]] depending on the location.\r\nHe starts the following quests:\r\n* Do Your Worst\r\n* Army of the Damned\r\n* Futility\r\n* The Hunter and the Prince\r\n* Knowledge is a Terrible Burden\r\n* Time to Hide\r\n* Return to the Surface\r\n* Where Dragons Fell\r\n* Time for Answers\r\n==Arthas Menethil's spirit?==\r\n\"Matthias Lehner\" is an anagram of \"[[Arthas Menethil]]\", which has sparked speculation that Matthias Lehner is the spirit of Arthas Menethil or a being that has some connection with him.",},
			["Mature Spore Sac"] = { content = "'''Mature Spore Sac''' hold the young [[Sporeling]]s, soon to 'hatch'.\r\n==As a quest objective==\r\nThis item is turned in to [[Fahssn]] for the following quests to obtain [[Sporeggar]] reputation.\r\n* The Sporelings' Plight\r\n** More Spore Sacs ([[Repeatable Reputation Quest]] for [[Sporeggar]]. This quest is repeatable until .) \r\n==As an object==\r\nThe '''Mature Spore Sac''' can be found throughout the [[Spawning Glen]] in [[Zangarmarsh]].",},
			["Maul"] = { content = ":''Did you mean the weapon Maul (Weapon), or the Dire Maul arena [[the Maul]]?''\r\n \r\n''' Maul''' is [[druid]]'s basic Direct Damage melee attack in [[Bear form]]. The ability increases the damage of the druids next attack by a specific amount based on rank. In higher ranks, this ability also grants some extra [[aggro]] generation. Druids gain this ability for free with the ability to use bear form.\r\n==Notes==\r\n* Rank 1 of this ability is learned automatically with [[Bear Form]].\r\n* The Idol of Brutality increases Maul damage by 50.\r\n==Tips and Tactics==\r\n* This is the Bear Form ability that you'll be using the most for damage before obtaining [[Cat Form]] at level 20.\r\n* For tanking, this is the staple threat generation ability until you have [[Mangle]] and [[Lacerate]].\r\n* At level 70, Maul should be downplayed in favor of Lacerate and Mangle unless you have extra rage, because using Maul consumes rage and forfeits the rage gained by hitting the enemy with an autoattack.\r\n* You can keep using Lacerate and Mangle while a Maul is waiting to strike, since it's an \"on the next attack\" kind of ability.\r\n==Past changes==\r\n* Threat generation was changed from a 1.75 damage multiplier to a static +threat component (similar to a warrior's [[Heroic Strike]]) when [[Patch 2.0.3]] (Burning Crusade) was released.",},
			["Maulgar"] = { content = "#REDIRECT [[High King Maulgar]]", redirect = "High King Maulgar",},
			["Maurin Bonesplitter"] = { content = "'''Maurin Bonesplitter''' is a level 35 [[quest giver]] located in [[Ghost Walker Post]] in the [[contested]] territory of [[Desolace]]. One of the few undead inhabitants there, Maurin possesses advanced knowledge of ancient lore and is filled with contempt for the [[Burning Blade]], lamenting their ignorance and their inability to comprehend that their power only stems from those whom they serve. He is a powerful spellcaster in his own right and has extensive knowledge of the Burning Blade operations. This knowledge earned him his current position in Desolace, as he was appointed by [[Keldran]] to hamper the Burning Blade effort and eventually eliminate the cult from the region. \r\nMaurin Bonesplitter is specifically responsible for the cruel use of [[Burning Gem]]s to trap the souls of Burning Blade cultists. It has been argued, however, that the cruel nature of Burning Gems was probably justified as it clearly demonstrated to all other races that the Horde would never show any sympathy or remorse to those worshipping the Burning Legion, thus proving that there were no ties between the Horde and the Burning Blade. From this point of view, it can be argued that Maurin Bonesplitter's mission was a success, although there is clearly still a need for a more permanent solution of the Burning Blade issue.\r\nDespite the malicious nature of the Burning Gems, their use, while successful, was most probably intended as a purely punitive measure, as its impact on the overall composition and effort of the Burning Blade in Desolace was highly marginal, casting doubts on the competence of Maurin Bonesplitter or possibly even on his allegiance. In fact, many have remarked that Maurin's deference to the Warchief and the Horde are exaggerated enough to possibly warrant an investigation into his true motives and loyalties.\r\nHe starts the following quests:\r\n* The Burning of Spirits\r\n* The Corrupter\r\n* The Corrupter\r\n* The Corrupter\r\nSee [[List of Desolace NPCs]].",},
			["Maury \"Club Foot\" Wilkins"] = { content = "'''Maury \"Club Foot\" Wilkins''' is a level 43-44 [[ghoul]] found in the [[Ruins of Jubuwal]] in [[Stranglethorn Vale]].\r\nMaury owes a debt to [[\"Sea Wolf\" MacKinley]] even in undeath.\r\n==Quests==\r\n*Voodoo Dues\r\n==Loot==\r\n*Maury's Clubbed Foot ''(Quest Item)''",},
			["Maur Grimtotem"] = { content = "'''Maur Grimtotem''' is a level 14 deceased [[tauren]] found in [[Ragefire Chasm]].\r\n[[Oggleflint]] guards his corpse.\r\nMaur starts the quest Returning the Lost Satchel (Dungeon).\r\nSee [[Ragefire Chasm NPCs]].",},
			["Mavoris Cloudsbreak"] = { content = "'''Mavoris Cloudsbreak''' is a level 32 [[night elf]] [[ghost]] found in the [[Dor'Danil Barrow Den]] in [[Ashenvale]]. [[Kayneth Stillwind]] would like Mavoris put to rest.\r\n==Quests==\r\n*Insane Druids",},
			["Mawg Grimshot"] = { content = "'''Mawg Grimshot''' can be found in [[Terokkar Forest]] .",},
			["Maws"] = { content = "'''Maws''' is a massive [[shark]] [[boss]] that guards the Blue Scepter Shard of The Scepter of the Shifting Sands. Azuregos refers to Maws as a \"minnow\". He is summoned by using an Arcanite Buoy at the [[Swirling Maelstrom]] which is an enormous floating wreckage off the coast of [[Azshara]] around .\r\n==Strategy==\r\nFor a [[guild]] on quest chain, this fight should not be a challenge and can be done with as few as 15 members. Maws is a straightforward boss fight in the waters of Azshara. There is no need to submerge during this encounter, so [[Water Breathing]] is not necessary. Maws will hit the [[MT]] pretty hard and somewhat sporadically so you need a fair amount of healers on him. Maws will [[frenzy]], so it is important that your [[hunter]]s use a [[Tranquilizing Shot]] when this occurs. Maws enrages every 25 seconds, and every 15 seconds when his health reaches 20%. When Maws is below 20%, he will occasionally [[AoE]] for 2000-3000 damage every 15 seconds. [[Prayer of Healing]] should be able to keep all raid members up due to the long interval between AoE ticks. Make sure the [[druid]]s and [[paladin]]s/[[shaman]]s step up the healing on the MT while the [[priest]]s are group healing.\r\n==Loot==\r\n*icon= ''(Quest Item)''",},
			["Maxan Anvol"] = { content = "'''Maxan Anvol''' is a level 10 [[priest trainer]] located in [[Thunderbrew Distillery]] in [[Kharanos]], in the [[dwarven]] starting zone of [[Dun Morogh]].\r\nHe starts the quest Garments of the Light.",},
			["Maxima Blastenheimer"] = { content = "'''Maxima Blastenheimer''' is a level 35 Darkmoon Faire [[Darkmoon Cannon|Cannoneer]] located in the [[Darkmoon Faire]] camp, which is only available during the monthly Darkmoon Faire event. It rotates each month to a different location. One month it will be south of [[Goldshire]] in the [[human]] starting zone of [[Elwynn Forest]]. Then, it is off to [[Kalimdor]] where it is southwest of [[Thunder Bluff]] in the [[tauren]] starting zone of [[Mulgore]]. Then it travels to [[Outland]] near [[Shattrath City]].\r\nSee [[List of Elwynn Forest NPCs]].\r\nSee [[List of Mulgore NPCs]].\r\nSee [[List of Shattrath City NPCs]].",},
			["Maximillian Crowe"] = { content = "'''Maximillian Crowe''' is a level 10 [[warlock trainer]] located in the kitchen basement of [[Lion's Pride Inn]] situated in [[Goldshire]], in the [[human]] starting zone of [[Elwynn Forest]].\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Maximillion"] = { content = "'''Maximillion''' is a level 5 [[warlock trainer]] located in [[Deathknell]] in the [[forsaken]] starting zone of [[Tirisfal Glades]].\r\nSee [[List of Tirisfal Glades NPCs]].",},
			["Maxnar"] = { content = "#REDIRECT [[Maxnar the Ashmaw]]", redirect = "Maxnar the Ashmaw",},
			["Maxnar the Ashmaw"] = { content = "'''Maxnar the Ashmaw''' is a level 68 black [[drakonid]] found in [[Blackwing Coven]] in [[Blade's Edge Mountains]]. He is of the [[dragonkin]], half-man, half-dragon.\r\nMaxnar, known as the Ashmaw, is the leader of the Blackwing [[Wyrmcult]]ists. The druids of [[Evergrove]] ask that any able adventurers slay him.\r\n==Quests==\r\n*Maxnar Must Die!",},
			["Maxwell's Mission"] = { content = "==Objectives==\r\nTravel to Blackrock Spire and destroy [[War Master Voone]], [[Highlord Omokk]], and [[Overlord Wyrmthalak]]. Return to [[Marshal Maxwell]] when the job is done. \r\n*Highlord Omokk slain\r\n*War Master Voone slain\r\n*Overlord Wyrmthalak slain\r\n== Description==\r\nThis information fills in the gaps to our otherwise impeccable intelligence of Blackrock Spire.\r\nThe attack must be decisive, <name>.\r\nFirst their war master, the [[troll]] Voone, must be destroyed. Without his battle plans, the Blackrock orcs will be thrown into chaos.\r\nYou must then take out the ogre Highlord, Omokk. The cowardly ogres of Blackrock are powerless without his leadership.\r\nLastly, the overlord of the citadel: Wyrmthalak. With Wyrmthalak dead, their central command unit is without a conduit. \r\n== Reward==\r\nYou will also receive:1 gold 80 silver copper \r\n== Completion==\r\nExcellent work, <name>. At the very least, you have bought us more time - precious, precious time. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*8300 [[XP]] (or 49 silver 50 copper at level 70)",},
			["Maxwort Uberglint"] = { content = "'''Maxwort Uberglint''' is a level 42 [[quest giver]] located at [[Flame Crest]] in the [[contested]] territory of [[Burning Steppes]].\r\nHe starts the following quests:\r\n* Tablet of the Seven\r\n* The Heart of the Mountain (Dungeon)\r\nSee [[List of Burning Steppes NPCs]].",},
			["Mayara Brightwing"] = { content = "'''Mayara Brightwing''' is a level 57 [[quest giver]] located at [[Morgan's Vigil]] in the [[contested]] territory of [[Burning Steppes]]. Although she shares the same last name with [[Halduron Brightwing]], apparently they are not related.\r\nSee [[List of Burning Steppes NPCs]].\r\n==Quests==\r\n* Mayara Brightwing \r\n** Doomrigger's Clasp \r\n*** Delivery to Ridgewell",},
			["Mayara Brightwing (quest)"] = { content = "==Objectives==\r\nSpeak with [[Mayara Brightwing]] in the [[Burning Steppes]]. \r\n==Description==\r\nAn agent of mine, [[Mayara Brightwing]], was sent to the [[Burning Steppes]] to scout the ruined city of Thaurissan. That destroyed city of the Dark Iron dwarves may hide objects of great value... objects that would fit nicely into our family museum.\r\nMayara says she found something and will need aid in retrieving it, but it is not in Thaurissan. Instead, a foray into Blackrock Spire will be required.\r\nI do not know the details, but if interested then speak with Mayara in the [[Burning Steppes]]. \r\n==Completion==\r\nYou came from Stormwind? Wonderful -- I know of an object of art that Remington would kill to have in his museum, but extracting it won't be easy.\r\nThat's where you come in. \r\n==Gains==\r\n*950 [[XP]] (or 5 silver 70 copper at level 70)",},
			["Mayor Quimby"] = { content = "He is involved in the following quest:\r\n*Nowhere To Run And Nowhere To Hide",},
			["Mazgrek"] = { content = "'''Mazgrek'' is a [[Tothrezim]] [[rogue]]. He is a member of a group of Tothrezim debt collectors lead by [[Thathrell]], maintained for particularly dangerious debt collections.",},
			["Mazra'Alor"] = { content = "'''Mazra'Alor''' is the large ziggurat temple located at the heart of [[Zul'Mashar]] in the [[Eastern Plaguelands]]. It is populated by a few [[forest troll]] shadow hunters of the [[Mossflayer]] tribe.",},
			["Mazrigos"] = { content = "'''Mazrigos''' was an [[orc]] [[farseer]] who defended the demon gate which the lich [[Kel'Thuzad]] used to commune with the demon lord [[Archimonde]]. [[Arthas]] and [[Kel'Thuzad]] killed him along with four other orcs guarding the demon gate.\r\n==Name==\r\nInterestingly, Mazrigos's name follows a naming trend common to [[blue dragon]]s, the ending -gos being shared by numerous dragons including [[Malygos]] himself and the prefix Maz- calling to mind [[Mazthoril]], the blue dragons' home in [[Winterspring]]. Despite this, however, the orc Mazrigos does not appear to be a dragon or in any way related to the [[Blue Dragonflight]], and his name is therefore almost definitely coincidental.",},
			["Mazthoril"] = { content = "'''Mazthoril''' is a huge and deep icy cavern - populated by the Cobalt Brood. Within these caverns lies the true stronghold of the [[blue dragon]]s, the forces of [[General Colbatann]]. Guarding this stronghold is an entire legion of [[dragonspawn]] sworn to protect Mazthoril. Night elf forces - including those rare few [[wintersaber]] riders who can tame the feral frostsaber cats - often clash with the dragonspawn legion, using blade and fang in an attempt to rid themselves of the malevolent dragons.\r\nThe blue dragons here are primarily on watch for activity from the black dragonflight, although there have recently been concerns that the blue dragonflight will be needed to assist the dragons at Mount Hyjal if the demons in Darkwhisper Gorge attack. Since Deathwing's disappearance after the battle of Grim Batol, the black dragonflight's members have been busy fighting each other for dominance. To this end, the blue dragonflight organizes an army here, lead by the dragonspawn General Cobaltann, to protect the world from the increasing threat of the black dragons. Specifically, Cobaltann focuses on the protection of dragon eggs, which are being stolen by the blacks for some evil purpose.\r\nTheir matriarch being the radiant [[Haleh]] - only encountered in [[high elf]] form at the peak of the cavern, and accessible by a portal rune in the cavern floor. It is she who completes the key to [[Onyxia's Lair]] for [[Alliance]] heroes. Haleh has four powerful [[drake]]s who guard Mazthoril, and leads a sizable army of highly sorcerous spawn and young whelps. [[Spellmaw]] is the brood's main patrol, and wanders a slow path around a good third of the lower section of [[Winterspring]]. [[Manaclaw]] and [[Scryer]] guard the runes at the rear of the cavern. [[Azurous]] patrols nearby regions in Winterspring for threats against the forces of [[Malygos]]. [[General Colbatann]], a notable general of the blue flight, has also been spotted near Mazthoril.",},
			["Mazzranache"] = { content = "'''Mazzranache''' is a level 9 [[rare mob]] [[tallstrider]] found in [[Mulgore]]. He has a unique, pink skin.\r\nMazzranache is [[tame]]able by a [[Hunter]]. He is the most popular of the tallstrider family as a [[pet]], due to his flamingo-like appearance. Up until [[patch 1.12]], he had an unusually slow pursuit speed, which has since been normalized.\r\nHe is [[hostile]], meaning if you get too close he will attack you, without you necessarily initiating the battle. He attacks with [[poison]] (a skill which is lost to him upon taming).\r\n==Note==\r\nAlso known as pink flamingo.\r\n==Location==\r\nMazzranache can be found south-west of [[Thunder Bluff]]. \r\n==Loot==\r\n*Sleek Feathered Tunic\r\n*Pioneer Cloak",},
			["Maz Drachrip"] = { content = "Thane '''Maz Drachrip''' was a former ruler and [[thane]] of [[Hinterlands]] and the [[Wildhammer Clan]] of hill dwarves at [[Aerie Peak]], he was in charge after the former thane [[Kurdran Wildhammer]] went through the [[Dark Portal]]. He acquired his position through a hereditary monarchy, held by the Wildhammer Clan, who proved themselves by might. He was a great [[fighter]] and [[windrider]]. \r\nAs part of clan-like caste system a thane rules each clan, and the mightiest thane rules Aerie Peak, this has been the Wildhammer Clan since the [[War of the Three Hammers]]. As Maz held the position of thane of Aerie Peak it would mean that he proved himself the mightiest thane, or at least his family had proven themselves, the mightiest clan of the Hinterlands in order to keep the hereditary monarchy. \r\nHe may have died or retired between the time [[Brann Bronzebeard]] wrote [[Lands of Conflict]] and his reports for the [[Alliance Player's Guide]], because [[Falstad Dragonreaver]] now holds the position of thane of Aerie Peak. Since the position is a hereditary monarchy this would imply that Falstad is related to Maz. So it is likely that Maz's true name was \"Maz Wildhammer\" like most Wildhammer dwarves. Following Wildhammer tradition, \"Drachrip\" like Falstad's name \"Dragonreaver\" is his title of honor (likely meaning \"drake rip\", since \"Drache\" is German for \"drake\" or \"dragon\") and replaced his true name \"Wildhammer\".",},
			["MC"] = { content = "An [[acronym]] usually for one of the following:\r\n# [[Molten Core]], a very difficult lvl. 60 [[Raid]] [[instance]] in the depths of [[Blackrock Mountain]].\r\n# [[Mind Control]]. This is an ability of [[Priest]]s and, to a lesser extent, [[Engineering|Engineers]] with the [[Gnome_Engineering|Gnomish Mind-Control Cap]].\r\n# [[Mooncloth]], a type of cloth.",},
			["Meat"] = { content = "'''Meat''' is the edible flesh of animals in and is one of the six main types of [[food]] WoW. However, the edible flesh of fully aquatic animals is a separate food type, [[fish]]. \r\n==Types of meat==\r\nThere is also a distinction between meat that is ready to eat, which is a consumable, and meat ingredients, using in cooking food, which are trade goods. Player characters can only eat consumable meat, but hunter pets can often eat meat ingredients. Consumable meat will have a description of the meat benefits, clearly indicating consumable meat status. Meat ingredients are merely trade items with little description.\r\nSome inventory items are 'meat' and use meat graphics for their icon, but are not meat food in the game. These will usually be quest items. Many of the beginning quests are a 'hunt for food' quest that use this type of object. (Similarly, many of the beginning quests are a 'hunt for hides' quest that use hides that are not leather trade goods items.) Two [[mace]]s, obtainable though [[Darkmoon Faire Tickets|Darkmoon Faire ticket redemption]], use meat graphics and a leg of meat 3D model.\r\n===Raw food types===\r\nTwo new food types, raw meat and raw fish, were added with the release of [[The Burning Crusade]]. There is not a whole lot of documentation or examples of raw meat and raw fish. It is clear that consumable food items with the name 'raw ...' such as the raw fishes, are not of the type 'raw ...'; raw fish are (generally) edible consumables, and player characters cannot eat the new raw food types. The one example is Partially Digested Meat which appears to be a poor [[quality]] [[vendor trash]] item. The addition of the two 'raw ...' types does not appear to be a significant factor in game play; the four pet types ([[Dragonhawk]]s, [[Nether Ray]]s, [[Ravager]]s, and [[Serpent]]s) that can eat one or both of these can also eat the more readily available normal version. Interestingly, the [[mob]], [[Crocolisk]]s, that drop the one known example, Partially Digested Meat, will not eat it when tamed as a pet. \r\n'Ingredients' is not the same thing as the raw types, but there may be some overlap. Meat eaters will all eat pretty much any meat ingredient that looks like meat, but will not eat Spider Ichor, for example.\r\n==Uses==\r\n*[[Player Character]]s can eat meat to recover health. Many [[cooking|cooked]] meat items also provide a [[Well Fed]] [[buff]].\r\n*[[Hunter]]s can feed meat to some [[hunter pet|pet]]s; some of the more popular pets eat only meat. \r\n*Many meat items are used as ingredients for foods that can be created by [[cooking]]. \r\n(These are the same uses as other types of food.)\r\n==Sources==\r\n*[[Player]]s can '''frequently''' [[loot]] meat (flesh) from dead [[beast]] [[mob]]s. Because of this, hunter pets that only eat meat, which is the most restrictive hunter pet diet, are actually easy to feed. The beast flesh meat is generally ingredient meat and is not directly edible by player characters.\r\n*Players can loot edible meat (carried food) from dead [[humanoid]] mobs and from [[Chest (container)|chest]]s.\r\n*Edible meat can be gotten as [[quest]] rewards.\r\n*Players can purchase edible meat from [[meat vendor]]s. \r\n*Many meat type foods can be created by [[cooking]]. \r\n*Since meat drops so frequently from beasts, and meat can be traded, the [[auction house]] is always a good source.\r\n==Types of buyable meat==\r\n1 This is the base price before any discounts.\r\nSee also: [[Meat vendor]]",},
			["Meathook"] = { content = "'''Meathook''' is an [[abomination]] and the first boss of the [[Culling of Stratholme]], a wing of the [[Caverns of Time]].\r\n==Quotes==\r\nAggro:\r\n*New toys!\r\nSpawn:\r\n*Play time!\r\nSlay:\r\n*Boring...\r\n*Why you stop moving?\r\n*Get up! Me not done!\r\nDeath:\r\n*This not fun...",},
			["Meat vendor"] = { content = "#REDIRECT [[Meat vendors]]", redirect = "Meat vendors",},
			["Meat wagon"] = { content = "One of the strangest and most dire tools utilized by the Scourge is the dreaded meat wagon. This rickety contraption is used to collect and store recently slain corpses from the field of battle. At any time, if the meat wagon carries a necromancer corpses can be pulled from the meat wagon and raised into undead warriors to swell the undead ranks. When upgraded, the Meat Wagon can also fling diseased corpses at enemy units with its crude catapult device. An invaluable support vehicle for the Scourge, the meat wagon strikes fear and woe into the hearts of even the most resolute defenders. Meat Wagons use a Meat-A-Pult™ to fling Corpses at the enemy.\r\n==World of Warcraft==\r\nIn WoW, abandoned Meat Wagons can be seen littering the landscapes in various places on Azeroth, but most prevalently in the [[Western Plaguelands|Western]] and [[Eastern Plaguelands]], [[Eversong Woods]] and the [[Ghostlands]], the territory of the [[blood elf|blood elves]], who, along with humans, arguably have suffered the most because of the [[Scourge]].",},
			["Mea Culpa, Lord Valthalak"] = { content = "==Objectives==\r\nUse the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak.\r\n*[[Lord Valthalak]] slain\r\n*Lord Valthalak's Amulet\r\nProvided Item:\r\n*Brazier of Beckoning\r\n==Description==\r\nAll is now ready, <name>.\r\nWhen alive, Lord Valthalak used to inhabit what is now The Beast's chamber. Go there and use the Brazier of Beckoning to summon forth Lord Valthalak. It will reincorporate him, so he'll have to be killed again. I'd take care of The Beast first, and be sure take enough friends along to survive the upper portion of Blackrock Spire.\r\nOnce you've dispatched Valthalak, use the amulet on his corpse. With his spirit reunified, he'll likely want his amulet back, as well.\r\nGood luck! \r\n==Progress==\r\n<class>, you dare disturb my rest!\r\n==Completion==\r\nHow fortunate for you that I know you're not part of the original group that stole this from me.\r\nI'll take back what is mine now, mortal! Give the amulet to me!\r\n==Quest Chain==\r\n#Bodley's Unfortunate Fate: Bodley's Unfortunate Fate (Alliance) / Bodley's Unfortunate Fate (Horde)\r\n#Three Kings of Flame\r\n#Components of Importance: Components of Importance (Tyr's Hand) / Components of Importance (Purgation Isle) / Components of Importance (Hive'Regal) / Components of Importance (Frostwhisper Gorge)\r\n#The Left Piece of Lord Valthalak's Amulet: The Left Piece of Lord Valthalak's Amulet (Stratholme) / The Left Piece of Lord Valthalak's Amulet (Scholomance) / The Left Piece of Lord Valthalak's Amulet (Lower Blackrock Spire) / The Left Piece of Lord Valthalak's Amulet (Dire Maul)\r\n#I See Alcaz Island In Your Future...\r\n#More Components of Importance: More Components of Importance (Tyr's Hand) / More Components of Importance (Purgation Isle) / More Components of Importance (Hive'Regal) / More Components of Importance (Frostwhisper Gorge)\r\n#The Right Piece of Lord Valthalak's Amulet: The Right Piece of Lord Valthalak's Amulet (Stratholme) / The Right Piece of Lord Valthalak's Amulet (Scholomance) / The Right Piece of Lord Valthalak's Amulet (Lower Blackrock Spire) / The Right Piece of Lord Valthalak's Amulet (Dire Maul)\r\n#Final Preparations\r\n#Mea Culpa, Lord Valthalak\r\n#Return to Bodley\r\n#Back to the Beginning: Back to the Beginning (Alliance) / Back to the Beginning (Horde)\r\n#Saving the Best for Last: Saving the Best for Last (Alliance) / Saving the Best for Last (Horde)\r\n==Notes==\r\n*This is the ninth step in the quest chain to upgrade your [[Dungeon Set 1]] Helm and Chestpiece into [[Dungeon Set 2]].\r\n*[[Lord Valthalak]] can be summoned in the chamber where [[The Beast]] resides.",},
			["Mechagnome"] = { content = "Mechagnomes are apparently small gnome-like [[clockwork]] creatures, who eventually became [[gnome]]s, due to the [[Curse of Flesh]]. Although this is not certain as the one who says this is clearly mad, so it might not be true. \r\n==Named==\r\n[[Gearmaster Mechazod]]",},
			["Mechanar"] = { content = "'''The Mechanar''' is the first wing of the [[Tempest Keep]] [[instance]]. It serves as a base for [[Pathaleon the Calculator]] and also generates [[Overcharged Manacell|manacells]], which contain an incredible amount of power. It used to belong to the [[Naaru]].\r\nThis is the purple crystal building south of the main palace. As you need a flying mount to get inside the instance, it is not possible to run the Mechanar until level 70 (68 for druids). After [[Patch 2.4]], it is now possible to enter the Mechanar via warlock summoning instead.\r\nOne full run with all mobs cleared yields about 1620 reputation with the [[Sha'tar]].\r\n==Layout==\r\nThe Mechanar consists of two levels joined by an elevator. The first level has two named elites and one boss. Both named elites must be killed to open the elevator. You must also kill both Gatewatchers to open the [[Cache of the Legion]]. The first optional boss ([[Mechano-Lord Capacitus]]) has a decent loot table of his own.\r\nOn Heroic mode, these first three bosses (prior to [[Patch 2.3]]) are known as the Three Free Badges, as the Gatekeepers remain virtually unchanged from regular mode and [[Mechano-Lord Capacitus]] becomes a ridiculously easy fight with proper positioning. Moderately geared groups can fight their way through the first floor in less than an hour, even with a wipe or need to retreat. As of Patch 2.3 the Gatekeepers no longer drop a Badge of Justice each, instead one is found in the Cache of the Legion.\r\nA second optional boss and the end boss of the instance are up the elevator.\r\n==Bosses==\r\n [[Mechano-Lord Capacitus]]\r\n 72 Elite\r\n [[Nethermancer Sepethrea]]\r\n 72 Elite\r\n [[Pathaleon the Calculator]]\r\n 72 Elite\r\n===Mini-bosses===\r\n[[Gatewatcher Gyro-Kill]] and [[Gatewatcher Iron-Hand]] are mini-bosses. Each drops a portion of a key which is used to open the [[Cache of the Legion]] just before the elevator.\r\n==Quests==\r\n* Fresh from the Mechanar\r\n* How to Break Into the Arcatraz\r\n==Issues and bugs==\r\nThere are currently a number of issues in this instance. They are listed here along with workarounds. These are issues acknowledged in Blizzard posts that are planned to be resolved.\r\n===Elevator is not visible===\r\n'''Problem:''' This client-side issue causes some players to not be able to see the elevator. This occurs on a per-instance basis.\r\n'''Workaround:''' If you encounter this problem, the only ways around it are to:\r\n* Use a Warlock's Ritual of Summoning to go around the elevator.\r\n* Log into another computer long enough to move your character up the elevator.\r\n* Full reboot of player's computer (worked at least once)\r\n===The upper floor is locked===\r\n'''Problem:''' Under certain circumstances, the elevator gateway remains closed after the group wipes. This issue is still not fixed as of 7 March, 2007 in patch 2.0.10.\r\n'''Workaround:''' The best ways to deal with this are:\r\n* Making sure the group has a wipe bailout in place, such as a [[soulstone]], [[Reincarnation|ankh]], [[Divine Intervention]], and so on.\r\n* Zoning everybody out and back in again.\r\n* Filing an in-game ticket reporting an environmental issue and putting \"Mechanar\" as first word in the issue.\r\n* Similar to zoning everyone out, dying apparently can solve the issue.\r\n* A \"soft reset\", which was described by a GM as leaving the instance for 30 minutes.\r\n''Note:'' GM stated that devs have asked that players not be ported to the other side of the gate after this occurs, as this may cause other problems.\r\n===Resetting Pathaleon Breaks the Instance===\r\n'''Problem:''' If attempting to reset the final boss by running towards the elevator, sometimes he may bug, keeping the remainder of the instance inaccessible. When Pathaleon mind-controls the players, they will release and fall under the map. When this happens, the client may be disconnected and will have difficulty getting back on. After this, Pathaleon and his adds will be scattered between several rooms in the back half of the instance, rendering the instance unplayable. \r\nCurrently (Patch 2.3.3) there is no known workaround, a GM must be paged to reset the mobs and, occasionally, the players as well.\r\n==Loot==\r\nSee [[Mechanar loot]].",},
			["Mechanar loot"] = { content = "This is a page listing loot to be found in the [[Mechanar]]. For information about the instance itself, see \r\n[[Mechanar]]. \r\n \r\n__TOC__\r\n==Shared Loot Table (Heroic)==\r\nAll [[Mechanar]] bosses (excluding mini-bosses) share the following loot while in [[Heroic]] mode.",},
			["Mechanic"] = { content = "==Overview==\r\nIn [[World of Warcraft]], a '''mechanic''' can mean a couple of things:\r\n# Short for \"Game Mechanic\". A way that a computer game simulates virtual world conditions, such as combat, consciousness, health, magic and movement. See [[Formulas and Game Mechanics]].\r\n# A mode of interaction for your character in game. See [[Mechanic|Mechanic as Mode]] below.\r\n==Mechanic as Mode==\r\nA way in which your game character interacts with the rest of the game world. Most of the time the game's normal mechanic is in effect, but there are [[buff]]s and [[debuff]]s that can change your mechanic. Debuffs that impose mechanic-altering effects come in all [[Dispel Type|dispel type]]s, and some have no dispel type at all, meaning that they either must run their course and expire over time or have a specific way in which they can be removed.\r\nFor example, if a [[Priest]] or [[Warlock]] puts a [[|Fear]] mechanic on you, there are two options available to you: if you have the \"Insignia of the Alliance/Horde\" [[Trinket|trinket]] and are a [[Druid]], [[Mage]], [[Paladin]], [[Priest]], [[Rogue]], or [[Warlock]], or if you are [[Undead]] (see [[Racial Traits|Will of the Forsaken]]), you can remove the Fear effect yourself. Or, if there happens to be a friendly Priest or Paladin (or Warlock with a [[Felhunter]]) around, they can remove the effect as well, as both [[Fear]] and [[Psychic Scream]] cause [[Dispel Type|Magic debuff]]s.\r\nIf one attains the second [[PvP]] [[ranking|rank]] (Corporal/Grunt) in the [[Honor System (pre-2.0)]], one can purchase an \"[[Insignia of the Alliance]]/[[Insignia of the Horde|Horde]]\" trinket, which when activated can remove three class-dependent types of mechanics; this power has a cooldown of 5 minutes. This table shows which class's \"Insignia of the Alliance/Horde\" trinket removes which effects. A \"Y\" means the class's trinket can remove the listed type of effect, while an \"N\" means it can't.\r\n===Charm===\r\n(Examples: [[Seduction]])\r\nYou can't control your character, who stands still, usually with hearts floating above his/her head. Some classes' PvP trinkets cancel this effect, as does the [[Undead]] racial ability [[Racial Traits|Will of the Forsaken]].\r\n===Confuse===\r\n(Examples: [[Polymorph]], [[Scatter Shot]])\r\nYou can't control your character, who wanders aimlessly. There may be items that help remove this effect (if this happens as part of a Polymorph, see [[|Polymorph]] for more), and these would of course be usable in this situation.\r\n===Damage Reduction===\r\n(Examples: [[Curse of Weakness]], [[Hex of Weakness]], [[Touch of Weakness]])\r\nThe damage dealt by every melee attack you make is reduced. There is to my knowledge no way to remove this mechanic specifically, although the debuff that causes it is usually either a [[Dispel Type|Curse]] or a [[Dispel Type|Magic]]-type debuff, which can be removed in the usual way.\r\n===Daze===\r\nYou move slowly. This is a lot like the Snare mechanic, although it has the added effect of knocking you off your mount, if you're on one to begin with. These effects are usually very short-duration. A Blizzard post to the official forums indicated that it is intentionally impossible to remove a Daze other than by waiting it out. There was once a bug (appeared in patch 1.6; fixed in patch 1.7) that allowed [[Paladin]]s' [[Paladin|Blessing of Freedom]] and [[Druid]]s' [[Druid|Shapeshifting]] to remove Daze, but this was a mistake.\r\n===Fear===\r\n(Examples: [[Fear]], [[Howl of Terror]], [[Psychic Scream]])\r\nYou run uncontrollably away, out to a certain radius, then mill about randomly, also uncontrollably. PvP trinkets for many classes remove this effect, as does Will of the Forsaken.\r\n===Incapacitate===\r\n(Examples: [[Gouge]], [[Sap]], (possibly) [[Maim]])\r\nYou cannot move and cannot use abilities, however the effect is broken when you take damage.\r\nThere is some debate over whether the [[expansion]] cat [[Druid]] ability [[Maim]] is an incapacitate debuff. It does break when the afflicted takes damage, but not when they take damage from periodic damage (such as damage from [[rake]] or [[rip]]). Currently, incapacitates do break when hit by damage from [[DoT]]s.\r\n===Periodic Damage===\r\n(Examples: [[Corruption (spell)|Corruption]], [[Rend]])\r\nYou continue to take damage every few seconds for the duration of the effect. The amount of damage depends on the effect, as does how often the damage occurs. There are items (such as the mighty [[Luffa]]) that remove [[School|physical]] Periodic Damage mechanics, which are known as Bleed effects.\r\n===Polymorph===\r\n(Examples: [[Polymorph]] (duh!))\r\nThis is basically a combination of a [[|Confuse]] effect and a [[|Transform]] effect. The reason why it's a separate mechanic from those other two is that there are items (for example, the PvP trinkets) and class abilities (such as the [[Druid]] ability to shapeshift) that remove both components of a Polymorph effect.\r\n===Possession===\r\n(Examples: [[Mind Control]])\r\nYou are under the control of a mob or another player.\r\n===Root===\r\n(Examples: [[Entangling Roots]], [[Frost Nova]])\r\nYou are frozen in place, attached to the ground. The [[Gnome]] racial ability [[Racial Traits|Escape Artist]] can remove most Root effects.\r\n===Silence===\r\n(Examples: [[Counterspell]])\r\nYou are unable to cast spells. This may be from a Magic-type debuff, in which case a Priest or Paladin ally could remove it from you, although you couldn't do so yourself.\r\n===Sleep===\r\n(Examples: [[Hibernate]])\r\nYou are asleep. Your character stands still, head bowed, with \"Zzz\" above his/her head. Very similar to Incapacitate; you cannot move or take any actions, but the effect will break if taken damage.\r\n===Snare===\r\n(Examples: [[Curse of Exhaustion]], [[Frost Bolt]])\r\nYou move more slowly than normal. Escape Artist can remove some Snare effects.\r\n===Speed===\r\n(Examples: [[Sprint]], [[Swim Speed Potion]])\r\nYou move more quickly than normal. Debuffs can remove some Speed effects.\r\n===Stun===\r\n(Examples: [[Hammer of Justice]], [[Kidney Shot]], [[Pounce]], [[Racial Traits|War Stomp]])\r\nYou are unable to move, cast spells, or use items, with the exception of those which allow you to break free of stun effects, of course. Some of the PvP trinkets will remove this.\r\n===Transform===\r\n(Examples: [[Druid]] shapeshifting, [[Polymorph]])\r\nYou look like something else. When imposed upon you by another, this is usually combined with a Confuse mechanic, but not necessarily -- several items and effects in the game will transform you, but the only confusion they cause is in the minds of onlookers.",},
			["Mechanical"] = { content = "A type of creature or [[mob]] in the game as distinguished from the fleshy type. This includes most constructed creatures except some [[Elemental]]s (like [[Golem]]s) and [[Undead]] (like [[Flesh Golem]]s).\r\nMost mechanicals are found in [[Gnomeregan]], and most can be controlled using the [[Gnomish Universal Remote]].\r\nNot having blood as such, most Mechanicals are [[Immune]] to bleed type melee attacks: [[Rend]], [[Garrote]], etc. They are also immune to draining abilities, such as a Warlock's Drain Life spell.\r\n==Examples of Mechanicals==\r\n* [[Alarm-O-Bot]]s\r\n* [[Bombling]]s\r\n* [[Explosive Sheep]]\r\n* [[Fel Reaver]]s\r\n* [[Gnomish Mech]]s\r\n* [[Harvest Golem]]s\r\n* [[Lifelike Mechanical Toad]]s\r\n* [[Mechanical Chicken]]s\r\n* [[Mechanical Dragonling]]s\r\n* [[Mechanical Greench]]s\r\n* [[Mechanical Squirrel Box|Mechanical Squirrels]]\r\n* [[Mechanical Yeti]]s\r\n* [[Mechanized Guardian]]s\r\n* [[Mechanized Sentry]]s\r\n* [[Spider Tank]]s\r\n*[[Shredder]]",},
			["Mechanicals"] = { content = "#redirect [[Mechanical]]", redirect = "Mechanical",},
			["Mechanical Chicken"] = { content = "The '''Mechanical Chicken''' item summons and dismisses a Mechanical Chicken, a [[chicken]] [[small pet]]. It is a non-combat pet and will not aid you in battle. \r\nOglethorpe Obnoticus, the master gnomish engineer, has created three larger metal chickens to explore [[Tanaris]], [[Feralas]], and the [[Hinterlands]], but his strange inventions have gotten lost. If a player finds a beacon to lead them to the downed bird, they can escort the mechanical chicken to safety. If you save all three of his inventions, Oglethorpe Obnoticus gives you a gift: a pet mechanical chicken!\r\n==Source==\r\nThe Mechanical Chicken is the final quest (An OOX of Your Own) reward from [[Oglethorpe's Homing Robots quest chain]], which involves completing three escort quests in [[Feralas]], [[Tanaris]] and [[The Hinterlands]]. Each escort quest begins with an item drop.\r\nThe easiest way to obtain the drop for the Tanaris escort quest is by doing [[Zul'Farrak]], however if the object drops only one person can have it, so make sure you tell your group you need it before you enter the instance.\r\nThe object for the escort quest in The Hinterlands has the highest drop chance in [[Jintha'Alor]].\r\nThe object for the escort quest in Feralas is a random drop from any mob in that zone, so the best thing is just to do quests there.\r\n==Notes==\r\nThis is not to be confused with the Gnomish Battle Chicken, a more vicious sort of machine created by [[Engineering]]. They are unusual items that protect their maker when used.",},
			["Mechanical dragon"] = { content = "A '''Dragonling''' is a class of [[mechanical]] [[guardian pet]]s that an [[engineering|engineer]] can make. \r\nThe significance is that according to the [[pet]] article, an engineer can deploy both a Gnomish Battle Chicken and a dragonling at the same time.\r\n==Types==\r\n* Mechanical Dragonling\r\n* Mithril Mechanical Dragonling\r\n* Arcanite Dragonling\r\n==In other uses==\r\nThe word 'dragonling' can be used in a broader sense to mean a small biological [[dragon]], although in the game these are usually referred to as [[Dragon whelp|whelps]].",},
			["Mechanical Dragonling"] = { content = "A [[Mechanical Dragonling]] is a [[trinket]] that summons a mechanical dragonling [[Guardian pet]].\r\nIt requires engineering skill of at least 200 to use.\r\n==Source==\r\nMechanical Dragonling is created by [[Engineering|engineers]] with a skill of 200.\r\nThe components are:\r\n*1x Bronze Framework\r\n*4x Iron Strut\r\n*4x Gyrochronatom\r\n*2x Citrine\r\n*1x Fused Wiring\r\nThe recipe for this item is taught by Schematic: Mechanical Dragonling.\r\nThis [[schematic]] is a [[limited sale recipe]] sold by [[Gnaz Blunderflame]] in [[Stranglethorn Vale]].\r\n==Notes==\r\nThe summoned dragon gains one level for every 5 points the user has in Engineering. So an engineer with Engineering 375 summons a level 75 dragonling.\r\nUsing this item starts a 20 minute cooldown on this trinket, and a 1 minute cooldown on other guardian pet trinkets (such as the other mechanical dragonling type trinkets, [[Defender of the Timbermaw]], etc). This means that there is still some value in keeping older dragonling trinkets after creating new ones.\r\nAs of [[Patch 2.4]], the Engineering combat pets no longer scaled with the user's Engineering skill. A Mechanical Dragonling will always be a Level 40 creature. The cooldown was reduced from 60 minutes to 20 minutes as partial compensation.\r\nAs of [[Patch 2.4.3]], these pets may once again scale with user's Engineering skill.\r\n==See also==\r\n* [[Mithril Mechanical Dragonling]]\r\n* [[Arcanite Dragonling]]",},
			["Mechanical Greench"] = { content = "==Source==\r\nContained in Ticking Present.",},
			["Mechanical Repair Kit"] = { content = "'''Mechanical Repair Kit''' is used to restore 700 health to a friendly mechanical target. Use this in emergencies or after you've had a huge fight.\r\n==Source==\r\nMechanical Repair Kit is created by an engineer with a skill of 200. The schematic is learned from a trainer.\r\nThe components are:\r\n*1 [[Mithril Bar]]\r\n*1 [[Mageweave Cloth]]\r\n*1 [[Solid Blasting Powder]]\r\n==Mechanical Repair Kit as a quest objective==\r\nThis item is an objective of Mechanical Repair Kits,\r\na [[Darkmoon Faire]] quest that rewards you with [[Darkmoon Faire Ticket]]s.\r\n==Notes==\r\nA '''Mechanical Repair Kit''' has only one charge. You can use it once, and then it's gone. If you intend to repair a lot, bring multiple kits. They stack in lots of five.\r\nWhile there exist some mechanical targets you might wish to repair, there are not many. Note that of the ones below, the Battle Chicken lasts the longest (90 seconds).\r\nExamples:\r\n* [[Compact Harvest Reaper]]\r\n* [[Mechanical Dragonling]]\r\n* [[Gnomish Battle Chicken]]\r\n* [[Target Dummy]]\r\n* [[Advanced Target Dummy]]\r\n* [[Masterwork Target Dummy]]",},
			["Mechanical Squirrel"] = { content = "#REDIRECT [[Mechanical squirrel]]", redirect = "Mechanical squirrel",},
			["Mechanical Squirrel Box"] = { content = "The '''Mechanical Squirrel Box''' item summons and dismisses a [[Mechanical Squirrel]], a [[squirrel]] [[companion]] that follows you around, meaning it is a non-combat pet and will not aid you in battle.\r\n==Source==\r\nMechanical Squirrel Box is crafted by [[Engineer]]s with a skill level of 75. \r\nThe components are: \r\n* 1 [[Copper Modulator]]\r\n* 1 [[Handful of Copper Bolts]]\r\n* 1 [[Copper Bar]]\r\n* 2 [[Malachite]]\r\nThe [[schematic]] drops off creatures with their levels in the 10s-20s.\r\n==Notes==\r\nA Mechanical Squirrel Box can sell in the [[Auction House]] typically for around 1 gold , but can get much higher (up to 50 gold ) on some servers.",},
			["Mechanical Yeti"] = { content = "==Source==\r\nA guardian pet obtained from the [[quest]] Are We There, Yeti?\r\nin [[Everlook]]. It has three charges and packs a powerful punch. If you don't need a guardian, you may prefer the [[Tranquil Mechanical Yeti]].",},
			["Mechanized animal"] = { content = "Tinkers strive constantly to create the perfect tool. Some actually believe that constructs are the purest form of life, so they recreate the world's natural creatures in this \"perfect state.\" Most mechanized animals barely resemble their organic counterparts, but many tinkers claim they are perfect nonetheless and keep them as pets. Most mechanized animals are simply referred to as mechanized versions of their natural equivalent. However, some mechanical animals in widespread use go by different names, such as \"[[mechanostrider]]\".",},
			["Mechanized Guardian"] = { content = "'''Mechanized Guardian''' can be found in [[Gnomeregan]].\r\nThese are both standard mobs, and mobs summoned by a [[Mobile Alert System]] that is not suppressed (destroyed) in time.\r\n==Drops == \r\n \r\n0.82% Chance of an [[Uncommon]] drop.\r\n0.11% Chance of a [[common]] drop.\r\n0.24% Chance of a [[poor]] drop.\r\nNote: % drop chance was thought correct as of November 1, 2007, and has not been updated.",},
			["Mechanized Sentry"] = { content = "A robo-gnome who is sitting on a [[Mechanostrider]]. This mob is found in [[Gnomeregan]].",},
			["Mechano-Hog"] = { content = "The '''Mechano-hog''' is a motorcycle mount that is created by top Horde engineers. Its Alliance counterpart is the [[Mekgineer's Chopper]].\r\n==Source==\r\nThis item can be crafted using [[Engineering]] (450); taught by Schematic: Mechano-hog.",},
			["Mechano-Lord Capacitus"] = { content = "'''Mechano-Lord Capacitus''' is an optional [[Arcane titan]] boss in [[Mechanar|The Mechanar]] of [[Tempest Keep]]. He is likely involved in the process of creating the [[Overcharged Manacell|manacells]] in the Mechanar.\r\n==Attacks and abilities==\r\n'''Head Crack''': Stamina decreased by 200, hits the tank (i.e. aggro target) only.\r\n'''Nether Bomb''': Spawns a small bomb that flies around. 1500-3000 AoE Arcane damage when it detonates. Spawns constantly throughout the encounter. \r\n'''Reflective Damage Shield''': (Red glow) - Inflicts 750 damage on melee attackers when struck. Normal mode only.\r\n'''Reflective Magic Shield''' : (Green glow) - 100% chance to reflect spells to the caster. Normal mode only.\r\n===Heroic mode===\r\n'''Polarity Shift''': Instead of the Reflective Shields, Capacitus periodically debuffs the party with a charge, similar to [[Thaddius]] in Naxxramas. Every 45-60 seconds, party members randomly get a 'positive' or 'negative' charge. Players with identical charges grouped together increase damage by 100%. Players with opposite charges cause 2000 damage per tick to those nearby. \r\n'''Enrage''': If not killed in 3 minutes, Capacitus enrages, causing a damage increase.\r\n==Strategies == \r\nKeep Capacitus far away from the group - this is primarily a ranged DPS fight. This is especially true for rogues as your healer needs to focus on healing the Main Tank and the bombs that spawn will deal high damage. If possible, save your healer headaches and mana by using your ranged weapon. However, this is not always possible in Heroic mode if your group is heavy on melee DPS, as the fight is timed.\r\nYour tank should be prepared to move Capacitus from side to side to avoid the bombs. Ranged should be wary of bombs approaching them.\r\nThe bombs themselves spawn and then move around slightly before pulsing two or three times then exploding. They are easy enough to spot and easy to avoid if everyone keeps their distance. When the boss dies, the bombs do not despawn, but will all explode!\r\n===Strategy 1: Using the stairs for positioning===\r\nUse the stairs to decrease the number of bombs that hit ranged party members. This strategy still requires vigilance on all players' parts -- the reflective shields the boss places will still wipe the group if ignored.\r\n* Have the tank stay below the stairs. The bombs will rarely find their way around the stairs (causing any bombs to only hit melee). \r\n** Alternatively, have the tank stand at the edge of the railing, about the third step up. This will be out of range of most of the exploding bombs.\r\n* Be cautious when standing on the railing: line of sight issues can occur if you're too far back, and bombs exploding very near the edge can still damage you if you're too close.\r\n===Strategy 2: Kiting===\r\nAnother strategy is to use the stairs on the right side of the instance to kite Capacitus. You should engage him when he is at his furthest point away from the stairs.\r\n*Have the tank pull and slowly [[kite]] the boss in a circle up the stairway. The key is to keep all melee and casters behind the tank and in front of the boss essentially keeping the whole group moving as the tank keeps him moving. The bombs will stay behind the boss and due to the large [[hitbox]] of the boss, this strategy also allows melee to add significant DPS to this boss. You should easily have enough DPS to kill the boss by the time he reaches the top of the stairs or even the front of the instance if necessary.\r\n* When DPS is low and the team are not well-geared enough to absorb 2-3 hits from the bombs, this method helps in minimizing damage from the bombs. If the bombs are getting too close to the melee classes, have the tank run (not walk backwards) a fair distance away from the bombs before picking him up again. He can be kited all the way up to the main entrance and back down to the stairs on the other side of the room.\r\n*If party members die, it is possible for a hunter to kite him around the instance until the rest of the group can zone back in and continue killing him.\r\n===Strategy 3: Using melee DPS===\r\nIt is possible for melee to DPS to be useful in this fight, and while an offhealer helps, it can be done by the main healer. The tank should hold Capacitus on the glass floor that he patrols. If the tank stays in the small indent near the front-center of the glass floor and keeps Capacitus in the middle of the room, two things happen:\r\n*99% of the bombs will bounce off the raised lip at the edge of the glass and stay away from your casting group.\r\n*Melee can stand on the edge of the lip and be in range of Capacitus's very large hitbox.\r\nAt this point, only two things need to happen for successful melee DPS: they need to stop attacking when he glows red (the tank should too -- do your healer a favor!), and they need to keep one eye on any bombs and move out of the way if necessary. Melee should also run up off the glass and bandage so the healer can focus on the tank.\r\n===Heroic===\r\nIn heroic mode, Capacitus hits harder, but releases fewer bombs (although they hit for higher damage). He neither changes colors nor reflects damage/magic. Instead, Capacitus has an ability called Polarity Shift, which is similar to the [[Thaddius]] fight in [[Naxxramas]]. After three minutes, Capacitus becomes enraged and it will be nearly impossible to kill him.\r\n====Polarity Shift====\r\n* Negative charge\r\n* Positive charge\r\nApproximately 30 seconds into the encounter and every 30 seconds thereafter, Capacitus casts Polarity Shift on all members of the party. Each person gets either a positive or negative charge, which is visible to yourself and others as a debuff icon.\r\nThe charges themselves do nothing if you are standing alone. If two people with '''opposite''' polarity stand close together, this causes damage to both members at 2,000 damage per tick and can easily cause a wipe. However when two people with the '''same''' polarity stand close together, the charge becomes beneficial and increases both members' damage output by 100% each.\r\nWhen you are correctly positioned with like-charged party members, the polarity icon is multiplied to indicate the increase in damage output.\r\n====Strategy====\r\nDetermine before the encounter starts, where ranged/casters should stand once Polarity Shift is in effect (for example, positives on the right and negatives on the left). Polarity Shift is a cast, so make sure that each pending shift is called out to the party. Everyone should take a moment to check their new polarity and move immediately to the predetermined location, switching back and forth as necessary.\r\nBecause the tank cannot move, rogues may need to move away if they are oppositely charged from the tank. As long as members are grouped correctly, damage output is increased so substantially that even feral-specced (but non-tanking) druids can shift out and cast damage spells (thus allowing them to stand away from the tank).\r\nPriests: If you use your [[Shadowfiend]] while your polarity is stacked, you will do more damage and return more mana.\r\nThis fight goes VERY quickly if you properly stack charges, and can easily be finished even if a party member goes down early.\r\n===Notes===\r\n''Enslaved Drill Master'': A warlock can enslave a drill master when you're one pull away from the boss. When you have a drill master enslaved it casts a debuff that stacks on the boss reducing its armor by 100% and increasing effective DPS.\r\n''\r\nThis tactic is only functional in NON-HEROIC DIFFICULTY.\r\n''\r\n==Quotes==\r\n*Aggro: You should split while you can.\r\n*Yells: Go ahead, gimme your best shot. I can take it!\r\n*Yells: Think you can hurt me, huh? Think I'm afraid a' you?\r\n*Killing a player: Damn, I'm good!\r\n*On death: Bully!",},
			["Mechano-tank"] = { content = "'''Spider Tanks''' are a spider-like type of [[Mechanical]] found in [[Gnomeregan]].\r\nSpider tank type mobs:\r\n* [[Electrocutioner 6000]] - A boss in Gnomeregan, and a big Spider Tank.\r\n* [[Mechano-Tank]] - Standard mob of this type.\r\n* [[Mechano-Flamewalker]] - Flame-throwing mob of this type.\r\n* [[Mechano-Frostwalker]] - Frost-spraying mob of this type.\r\nCurrently, no mobs in World of Warcraft have the exact name \"Spider Tank\".\r\nThe Spider Tank is vaguely reminiscent of the tachikoma from the anime \"Ghost in the Shell: Stand Alone Complex.\"",},
			["Mechanostrider"] = { content = "The '''Mechanostrider''' is a construct which vaguely resembles a mechanized tallstrider. Small oval lamps replace its eyes, while great mufflers extend where its tailfeathers should be.\r\nWhen gnomes set out to explore the world once again after their city's fall, they soon realized that they needed reliable mechanical mounts, because they were mocked for their short stature and slow land speed.. Tired of being mocked, the gnomes developed these revolutionary modes of travel. One ingenious gnome spied a flock of tallstriders and remarked upon their grace and strength. Soon after was born the mechanostrider, which quickly became a favorite mount of all gnome-kind. Using steam compression and duro-steel plating, the finest gnomish tinkers created these ostrich-like striders to use as mounts. The Mechanostrider can move at speeds up to 30 mph. This is the one device that gnomes refuse to restructure for their larger allies. All gnome tinkers agree that the striders are only available for small humanoids. Although some goblins have purchased striders for themselves, most of these striders have only proud gnomish passengers. This mechanostrider represents an older model and, while outdated, is a viable and cheaper vehicle. The current model is mechanostrider v. 2.0 (see below)\r\nThe gnomes' revolutionary mechanostrider represents yet another marvel of their engineering prowess. Each strider is specifically designed with the individual rider in mind. They are constructed using state-of-the-art steam compression, servo-motor dynamics, and duro-steel plating. This offers the rider a reliable and durable means of transportation. Some claim that the mechanostrider's lack of true sentience makes for a very dumb mount. However, the gnomes counter that under a skilled rider, the mechanostrider is more responsive than even the best trained live mount. \r\nThey were made for long distance treks through [[Khaz Modan]] and for trade between [[Ironforge]] and [[Gnomeregan]]. They have since become a widespread multi-use vehicle for all [[Gnome]]s.\r\nMechanostriders can be purchased at [[Steelgrill's Depot]] in [[Dun Morogh]]. Non-gnomes must be [[Exalted]] with [[Gnomeregan]] to buy a mechanostrider, and only Gnomes and Dwarves are able to ride them.\r\nFor other things to ride, see [[Mounts]].\r\nTheir footsteps all metalic and cool. - Yeomi\r\n==Mechanostrider v. 2.0 (Mechanized Tallstrider)==\r\nThe mechanostrider 2.0 is the current version of the vehicle that the gnomish race employs. While these constructs are as dumb as a brick (and even some bricks are smarter, it is said...), they are reliable mounts and, when handled by the best mechanoriders, better than live mounts. A mechanostrider fights only when ordered to or threatened, lashing out with its sharp beak and claws, or simply hammering at the danger with its heavy metallic head.\r\nThis may be describing the epic mount.\r\n==Epic Mount==\r\nAn epic mount for sale at [[Steelgrill's Depot]]. The PvP mount is the Black Battlestrider.\r\n*The original epic mount variants ([[Icy Blue Mechanostrider Mod A]] and [[White Mechanostrider Mod A]]) used the original art. These varieties are no longer offered.\r\n===Extra info===\r\n*The Mechanostrider is one of the only mounts that is non-organic, the others being the engineer [[Flying Machine Control|flying]] [[Turbo-Charged Flying Machine Control|machines]].\r\n*With an exception to the Battlestrider (obtained by PvP), the Mechanostrider can only be bought, and cannot be obtained through drops.\r\n*The rare mounts come in red, blue, green, and unpainted, and the epic mounts come in green, yellow, white, and black (PvP only).\r\n*A Fluorescent Green Mechanostrider was given to a European player early in the game as a replacement for his original Mechanostrider, which he was having problems with. It is the only one that exists in the entire game.",},
			["Medallion of Faith"] = { content = "'''Medallion of Faith''' is the objective of the quest The Medallion of Faith.\r\nIt is found inside [[Malor's Strongbox]].",},
			["Medallion of Karabor"] = { content = "''For the quest item, see [[Medallion of Karabor (quest item)]]. For the upgraded version of this item, see [[Blessed Medallion of Karabor]].''\r\nThe '''Medallion of Karabor''' is an epic necklace that provides stamina and shadow resistance. It was originally held by [[draenei]] priests in order to allow them entrance to the Temple of Karabor. Now it serves the same purpose for adventurers seeking to challenge [[Illidan Stormrage]], who has taken residence in the Temple of Karabor - now called the [[Black Temple]]...\r\n==Notes==\r\nThe Medallion of Karabor is mentioned as a quest-item from [[Akama]] at the [[Warden's Cage]], west of the Black Temple. In a [[Quest:Tablets of Baa'ri|long quest line]] beginning with the [[Aldor]] or [[Scryers]] (depending on the player's faction), the player is sent to the Ata'mal Terrace, located on the Temple's northern battlements, to obtain the [[Heart of Fury]], one of the shards of the [[Ata'mal crystal]]. Akama places the Heart of Fury into the empty socket of his Medallion of Karabor and instructs the player to bring it to A'dal (Akama's Promise). Afterwards, a Broken named [[Seer Olum]] is opened up in [[Serpentshrine Cavern]], where he reveals that the [[Ashtongue Deathsworn|Ashtongue's]] secret - their intent to overthrow Illidan - has been uncovered by [[Lady Vashj]]'s [[naga]]. Then under orders from Illidan himself, Akama's Ashtongue are sent to [[Tempest Keep]] to slay [[Al'ar]], [[Kael'thas Sunstrider]]'s [[phoenix]]. Lastly, the players travel to the very gates of the Temple itself and do battle with Illidari demons, allowing Akama and [[Maiev Shadowsong]] to enter the Temple to later aid you in the battle against Illidan. The naaru [[Xi'ri]] will then give you the Medallion.\r\nThe Medallion of Karabor presumably works like a similar necklace-attunement, the [[Drakefire Amulet]] ([[Onyxia|Onyxia's]] [[Onyxia's Lair|Lair]]), in that you must have it in your inventory but not necessarily be wearing it, in order to enter the Black Temple.\r\nAfter completing the quest [[Quest:The Fall of the Betrayer|The Fall of the Betrayer]], the Medallion becomes the , which, prior to patch 2.4, allowed entry into the Black Temple, also allows the player to teleport directly to the doorstep of Illidan's fortress. The medallion is no longer needed to enter the Black Temple.",},
			["Medallion of Karabor (quest item)"] = { content = "''Were you looking for the epic necklace, Medallion of Karabor?''\r\n----\r\n==Source==\r\nThis is a quest item for Akama's Promise.",},
			["Medallion of the Alliance"] = { content = "'''Medallion of the Alliance''' may refer to:\r\n* [[Medallion of the Alliance (rare)]], the version\r\n* [[Medallion of the Alliance (epic)]], the version\r\n* The [[TCG]] card, [[Medallion of the Alliance (Drums of War)|Drums of War ]]",},
			["Medallion of the Horde"] = { content = "'''Medallion of the Horde''' may refer to:\r\n* [[Medallion of the Horde (rare)]], the version\r\n* [[Medallion of the Horde (epic)]], the version\r\n* The [[TCG]] card, [[Medallion of the Horde (Drums of War)|Drums of War ]]",},
			["Medic"] = { content = "#REDIRECT [[First Aid]]", redirect = "First Aid",},
			["Meditation"] = { content = "''Meditation brings wisdom; lack of meditation leaves ignorance. Know well what leads you forward and what holds you back, and choose the path that leads to wisdom.''\r\n'''Meditation''' is a tier 3 talent which allows mana regeneration to continue while casting.\r\n==Tips and tactics==\r\nIn PvE, this talent is essential for Holy Priests and useful for Shadow Priests in weaker gear. By allowing 30% of regular mana regen to occur while casting, it enables the priest to cast far more spells during a fight.\r\nShadow Priests in high end raid gear (Tier 6.5) can, thanks to the way Vampiric Touch scales, start dropping points in this for more beneficial talents (e.g. Imp. Vampiric Embrace).\r\n==Past changes==\r\n[[Patch 2.3]] changed the regen while casting from 5/10/15% to 10/20/30%\r\n",},
			["Medium Leather"] = { content = "'''Medium Leather''' is used as a reagent in many professions.\r\n==Source==\r\n*It can be created by [[leatherworking|leatherworkers]] by combining four [[Light Leather]].\r\n*This [[leather]] can be [[Skinning|skinned]] from [[beast]] and a few [[humanoid]] monsters ranging up to level 35. \r\n==As an ingredient==\r\nMedium Leather is used in the following recipes:\r\n[[Leatherworking]]\r\n* Black Whelp Cloak\r\n* Black Whelp Tunic\r\n* Dark Leather Boots\r\n* Dark Leather Cloak\r\n* Dark Leather Pants\r\n* Dark Leather Shoulders\r\n* Dark Leather Tunic\r\n* Earthen Leather Shoulders\r\n* Fine Leather Pants\r\n* Fletcher's Gloves\r\n* Heavy Earthen Gloves\r\n* Herbalist's Gloves\r\n* Hillman's Belt\r\n* Hillman's Leather Gloves\r\n* Hillman's Shoulders\r\n* Medium Armor Kit\r\n* Nimble Leather Gloves\r\n* Pilferer's Gloves\r\n* Red Whelp Gloves\r\n* Toughened Leather Armor\r\n* Toughened Leather Gloves\r\n[[Tailoring]]\r\n* Reinforced Woolen Shoulders\r\n* Spidersilk Boots\r\n[[Blacksmithing]]\r\n* Big Bronze Knife\r\n* Bronze Axe\r\n* Bronze Battle Axe\r\n* Bronze Greatsword\r\n* Bronze Mace\r\n* Bronze Shortsword\r\n* Bronze Warhammer\r\n* Deadly Bronze Poniard\r\n* Heavy Bronze Mace\r\n* Heavy Copper Broadsword\r\n* Iridescent Hammer\r\n* Mighty Iron Hammer\r\n[[Engineering]]\r\n* Bronze Framework\r\n* Deadly Blunderbuss\r\n* Green Tinted Goggles\r\n* Minor Recombobulator\r\n* Portable Bronze Mortar\r\n* Shadow Goggles\r\n* Small Blue Rocket\r\n* Small Green Rocket\r\n* Small Red Rocket",},
			["Medivh's Chambers"] = { content = "'''[[Medivh]]'s Chambers''', located near the summit of [[Karazhan]], are the private bedchambers and study of the last Guardian of Tirisfal. The room contains a worktable, an elevated bed, and many paintings and statues.\r\nTo enter Medivh's Chambers, it's recommended that Karazhan be cleared first, as there are several [[fleshbeast]]s within the room. There are two entrances; the first, which appears to be the \"front door\", is just outside the [[Gamesman's Hall]] on the way to [[Prince Malchezaar]]. Leave the Gamesman's Hall and enter the doorway to the left, and up the ramp to the door. The second entrance, which appears to be the \"back door\", is halfway up the staircase to the tower summit.",},
			["Medivh's Journal"] = { content = "==Source==\r\nThis item drops from [[Shade of Aran]] in [[Karazhan]].\r\n==As a quest objective==\r\nThis item is an objective of The Shade of Aran.",},
			["Medivh"] = { content = "Magus '''Medivh''' was the last [[Guardian of Tirisfal]], an ancient line of protectors bestowed with great powers to do battle with the agents of the [[Burning Legion]]. He was corrupted from birth and possessed by the spirit of the demonlord [[Sargeras]], who used Medivh in his plan to conquer [[Azeroth]]. Medivh contacted the [[orc]]ish [[warlock]], [[Gul'dan]], and together they opened the [[Dark Portal]], which allowed the [[Horde]] to begin its destruction of Azeroth. He was slain shortly after by a party led by one of his friends, [[Lothar]]. Shortly before the beginning of the [[Third War]], Medivh returned as a mysterious prophet, guiding the mortal races to victory at the [[Battle of Mount Hyjal]]. The prophet's name means \"keeper of secrets\" in [[Thalassian]]. He possessed .\r\nHe is voiced by [[Michael Bell]] in [[Warcraft III]] and [[Cam Clarke]] in [[World of Warcraft: The Burning Crusade]].\r\nIn World of Warcraft, he ends the quest The Master's Touch, and begins the quest Return to Khadgar.\r\nSee [[Caverns of Time NPCs]] and [[Karazhan NPCs]].\r\n===Birth and childhood===\r\nMedivh's mother, [[Aegwynn]], served as the Guardian of Tirisfal before him. Eight centuries before the coming of the orcs, she fought and seemingly defeated Sargeras. This was according to the demon lord's plan, as he used the opportunity to transfer his essence into her body, where he would lay in wait.\r\nForty-five years before the coming of the orcs, Aegwynn desired to give birth to a child to whom she could pass on her powers, against the wishes of the [[Order of Tirisfal]]. She seduced the court conjurer of the [[kingdom of Azeroth]], [[Nielas Aran]], who was a powerful [[sorcerer]] of the Order in his own right, only returning later to leave the child in his care. Naming the boy Medivh, which means \"keeper of secrets\" in the high elven tongue, Aegwynn was unaware that Sargeras had possessed the defenseless child while it was still in her womb. The boy, and Sargeras, were given all of Aegwynn's powers, which were to lay dormant until he reached adulthood.\r\nMedivh had a happy childhood, primarily spent with friends Prince [[Llane Wrynn]] and [[Anduin Lothar]]. One day, while out on the road in [[Stranglethorn Vale]], Medivh and his friends were ambushed by three [[jungle troll]]s. None were hurt badly, however, Medivh fainted after casting several spells. He would at some point succumb to a coma on his fourteenth birthday, awaking in the middle of the night from evil dreams, where he pictured figures giving chase through deep chasms. In a sweat, he stumbled into his father's room, and when his father touched his brow, the power his mother had given him awoke. By the time the force had subsided, his father was dead and Medivh nearly so himself. Spanning over twenty years, Medivh, in a coma caused by Sargeras, was tended by his friend Lothar, as well as the [[Clerics of Northshire|clerics]] at [[Northshire Abbey]]. It is unknown if the two events are connected in some way.\r\n===The fallen Guardian===\r\nMedivh awoke over twenty years later under a facade of control, and assured the court and his mother Aegwynn that he was fine. But the dark spirit of Sargeras twisted his thoughts and emotions towards an insidious end. With Medivh's powers growing exponentially daily, he had set out to know everything, and he even consorted with the [[Burning Legion|Legion of the Lower Planes]]. He began to search for something with which to destroy the humans of Azeroth, who he saw as the only thing standing in his way of true power. He found that on [[Draenor]]. Bargaining with the warlock Gul'dan from his chambers in the tower of [[Karazhan]], Medivh promised to furnish Gul'dan with the location of the [[Tomb of Sargeras]] if Gul'dan would bring the Horde to Azeroth and destroy the humans. And so, aided on the other side by Gul'dan's [[Shadow Council]], Medivh opened the Dark Portal between Azeroth and Draenor. Aegwynn then appeared to Medivh, trying to reason that this was the wrong path to take, but he heard nothing. They battled, with Medivh emerging the victor and banishing her from his sight. But the battle had drained him, so he attempted to draw power from the very land itself. Aegwynn had survived the battle with Medivh, who promptly set up magical wards to ensure that his mother lived in peace.\r\nAegwynn wasn't the only one to confront the maverick guardian. [[Arcanagos]], a blue dragon and one of the guardians of magic, paid visit to Karazhan to attempt to sway Medivh from the path he was being led down. Finally the blue resorted to using force, but was overpowered by Medivh and burned from within. Once again Medivh was left drained and left to recover his strength.\r\nIt was shortly after this time that the mages of [[Dalaran]] sent Medivh an apprentice. This young apprentice was known as [[Khadgar]], a name which among the dwarves meant ''Trust''. Time passed as \"Young Trust\" studied under Medivh. He lived within Karazhan with a few others: Medivh studying, [[Moroes]] serving as his aide, and [[Cook the Chef]] making meals.\r\nAround this time, the war began picking up between the orcs and the humans, as the orcs increasingly struck out of [[the Black Morass]]. Medivh was sober about this, even remarking that it was happening as planned. Khadgar would be the first to discover that it was Medivh who has brought the orcs upon the lands of Azeroth. During this time, Khadgar and the Horde's emissary, [[Garona Halforcen]], had an audience with King Llane and Anduin Lothar, where Lothar was convinced of Medivh's corruption. Lothar, one of Medivh's best friends, led a troop of human forces, which included Khadgar and Garona, to deal with the crazed Guardian. During the battle with Medivh, Khadgar—magically aged by Medivh's spellwork—held Lothar's blade to the Guardian's chest, and finally ran it through Medivh's heart. The demon within him awakened at that point, right up until Lothar delivered the mercy stroke, decapitating the Guardian and banishing Sargeras into the Nether.\r\nAt the height of his powers, Medivh worked his magics and struggled with Sargeras in his tower of Karazhan. His powers were such that the trauma of his death laid a curse on his once wondrous tower and the surrounding area that became [[Deadwind Pass]]. The tower has become such a dangerous and accursed place, that those that venture in never return ([[Violet Eye]] chain). Medivh's magics created [[Medivh's Beetle]] at the time of the Second War.\r\n===Resurrection===\r\nWhen Lothar slayed Medivh's body and destroyed the spirit of Sargeras, Medivh’s spirit escaped. The spirit of Medivh forsaw the eventual downfall of Lordaeron and began to manipulate events in order to arrange the formation of a last-ditch alliance between the mortal races on Kalimdor. With his mother's help his spirit attained form, and he was resurrected by the last of her magic as she had also forseen the new threat looming over the world of Azeroth.\r\nMedivh briefly returned to Karazhan, where he interacted with a past version of Khadgar (though it was a future version of Medivh from Khadgar's perspective). He explained to his erstwhile apprentice that with his burial in the past by Khadgar and his current return to life, the good (the Guardian) and the evil (Sargeras) battling within him had been destroyed, and that he was, perhaps for the first time, only Medivh.\r\n===A prophet emerges===\r\nLong after the Second War, a strange prophet appeared to various denizens of Azeroth. He appeared to deliver a warning of a looming apocalyptic threat. The young Warchief of the Horde—[[Thrall]], son of [[Durotan]]—sensed the truth of his words and set sail to the ancient lands of [[Kalimdor]] in the far west beyond the sea. With the humans, however, he found some difficulty. He chose to remain uninvolved directly in the upcoming war (leading some to suspect he had remained a ghost).\r\nKing [[Terenas]] of Lordaeron and [[Antonidas]] of Dalaran both dismissed the prophet as a madman. The King's son, Prince [[Arthas]], refused to leave his beleaguered people. Only the young daughter of [[Daelin Proudmoore]], and apprentice of Antonidas, [[Jaina]], sensed that he was perhaps right. When he appeared to her after the destruction of [[Stratholme]], she heeded his warning and prepared to leave for the west. She set sail with a group of her people just as the invasion began. The prophet remained aloof for some time, until he reappeared to Thrall and Jaina as they prepared to do battle with each other. He told them that they must cease hostilities if they ever hoped to defeat the Burning Legion. They reluctantly agreed to his words. \r\nFinally, the prophet revealed his identity when the time came to rally the forces. Appearing in a dream to Thrall, the night elves [[Malfurion Stormrage]] and [[Tyrande Whisperwind]], and Jaina, the prophet told them that they must form an alliance to battle the common enemy. He told them that he was, in fact, Medivh, the Last Guardian of [[Tirisfal]], and that it was his doing that brought the orcs, and, in turn, the Burning Legion, to Azeroth. Jaina, Thrall, and Tyrande became convinced that victory could only be achieved through an alliance, and they rallied together to defend the World Tree, [[Nordrassil]]. In the final hour, nature's spirits, called into action by the [[Horn of Cenarius]]' clarion call, swarmed around [[Archimonde]], and destroyed the demon once and for all.\r\nConfident that the world was safe for now, and that he had repaid a fraction of debt for his terrible sins, Medivh vanished, to take his place \"amongst the legends of the past.\" His actions ensured Azeroth's survival and he found some redemption for his previous crimes.\r\nExactly what happened to him after the events of the Battle of Mount Hyjal is unknown; he may have met the end of his wandering on Azeroth, dying or somehow departing the material plane, or he may have simply retired somewhere distant. More recently, a black raven can be seen endlessly circling Karazhan, leading some to suggest that the Last Guardian may linger on in some form. Nonetheless, his fate remains unknown, though it is quite clear from his final comments that he intends to never be heard from or seen again.\r\n==Deaths==\r\nMedivh's death is unique in that it has been experienced by players in at least three different ways. In the original Warcraft game, the player had to enter his lair and slay him. His lair was filled with summoned and cave beings: Skeletons, scorpions, fire elementals and daemons. Lothar, Khadgar, and Garona are all absent. Medivh's death was clearly described in ''The Last Guardian,'' where it is clearly established that he was slain by the three listed above—with Khadgar wielding the blade that was run through Medivh's heart (and Lothar then decapitating him). Finally, in the interlude ''The Last Guardian'' in the '''Eternity's End''' campaign in Warcraft III, Medivh is shown in a flashback being killed by human footmen. Though the captain figure in the scene could be Lothar; Khadgar and Garona are nowhere to be seen. \r\nIn [[Tides of Darkness]] its explained that Lothar was with Garona, Khadgar and a handful of men when they defeated Medivh, perhaps combining all three versions.\r\nIn WoW its possible to allow Medivh to be killed by infinite dragonflight in the Black Morass, initiating a special comment.\r\n==Personality==\r\nMedivh’s soul constantly struggles with that of Sargeras for control of his body and mind. The fight between them is constant, and results in Medivh shifting periodically between stretches of calmness and lucidity and bouts of strangely incomprehensible behavior. To outsiders, he often seems to make abrupt decisions or reverse his position on issues. When the struggle between the two souls becomes too great for Medivh’s body to handle, he sinks into a catatonic state and becomes completely unresponsive. These periods vary greatly in duration and can range from a matter of minutes to months.\r\nWhen Medivh is in control of his body and mind, he is a friendly and wise individual. He cares deeply for a number of the high-ranking human leaders and puts the needs of the kingdom above almost everything else. He has defended Lordaeron from attack many times throughout the years and has built a great reputation as a staunch defender of the land. He is not naturally biased against any of the races, and displays a fair amount of interest in people who bring to him stories of distant lands or cultures.\r\nHowever, when Sargeras is in control, Medivh’s personality shifts dramatically. He becomes sullen and distant, barely acknowledges the presence of close friends, and practically ignores strangers. He is secretive and often travels to faraway places abruptly. In private, Medivh will not hesitate to do away with annoying visitors by using his spells to kill or incapacitate them. However, he is moderately concerned about his cover being blown with the Lordaeron leadership and will not act out of character in public \r\n==Combat==\r\nMedivh’s tactics are often erratic, depending upon which personality is in control at the time. Nonetheless, the common theme with both personalities is to stay at range and harass enemies with potent spells. He often casts only a few spells and then retreats for a few rounds to strike again later from another direction.\r\n==World of Warcraft: The Burning Crusade==\r\nIn [[the Burning Crusade]] expansion, three major instances are linked to Medivh. The first is his tower of Karazhan in Deadwind Pass, which has been abandoned since Medivh's death at the hands of Khadgar and Lothar, shortly before the end of the First War. The other two are battles within the [[Caverns of Time]]: the Battle of Mount Hyjal, where Medivh convinced the Alliance and the Horde to fight against Archimonde, and the Opening of the Dark Portal, where Medivh himself is seen in World of Warcraft. An \"echo\" of Medivh is also seen in Karazhan itself, where players play a [[Chess Event|game of chess]] against him in the Gamesman's Hall.\r\n===Caverns of Time===\r\nMedivh makes his appearance in World of Warcraft in [[Opening the Dark Portal]], the second instance within the Caverns of Time, opened after Thrall's [[escape from Durnholde]]. It is set in the Black Morass just as Medivh prepares to open the Dark Portal, and the player group must protect him from members of the [[Infinite Dragonflight]] attempting to kill him and prevent the opening of the Portal—and the foundation of the [[horde]].\r\nMedivh is also involved in the attunement process for Karazhan. After obtaining the fragments of Khadgar's key from instances in Outland, Khadgar sends you to the Black Morass to speak to Medivh and gain possession of [[the Master's Key]]. However, you must have completed the instance (Medivh must survive to open the Dark Portal) before you can speak to him and gain his key.\r\nStrangely, Medivh's character model, from where his animations are derived, is that of a male night elf as opposed to a human, which accounts for his increased height.\r\n==Status as an Eternal==\r\nMedivh is classified as an [[Eternal]] in the legends chapter of [[Shadows & Light]], but the book is unclear as to how or when he reached that status. The article is mostly concerned with the period in history when he was possessed by Sargeras. This likely means that he was an Eternal only because he was possessed by one. It doesn't seem to be related to the fact he was a guardian, as other guardians are not Eternals, for example [[Aranda]]. It's less likely but it might be possible that it refers to when he became the legendary Oracle. In this case it would mean that Medivh transcended beyond even his powers as the last Guardian to become an Eternal; however the book implies he was only a ghost at that point. The book is also pretty clear that no new Eternals have appeared in modern times.\r\n==Atiesh==\r\nThe most powerful mages focus their powers into magical staves, and Medivh was no different. His staff, , was possessed by an agent of Sargeras, thus boosting Medivh's already-immeasurable powers. When Medivh was killed, Atiesh was taken to Dalaran, where it was revealed that the [[Atiesh, Hand of Sargeras|spirit]] within killed anyone who dared try to wield it. It was locked away in a secret and secure vault for nearly three decades following Medivh's death, until Dalaran was destroyed by Archimonde. The staff was shattered into 42 pieces—the 40 splinters of the shaft, the base, and the headpiece.\r\nThe base found its way into [[C'Thun]]'s possession in the [[Temple of Ahn'Qiraj]] in an unknown way from [[Brann Bronzebeard]] (who found it through his exploration of Azeroth), and the headpiece was located by the necromancer-lich [[Kel'Thuzad]], who was responsible for summoning Archimonde in the first place. The 40 splinters of the shaft are in the hands of Kel'Thuzad's lieutenants, spread out across his citadel of [[Naxxramas]] in the [[Eastern Plaguelands]]. Even if the staff were restored, it would need to be [[Quest:Atiesh, Greatstaff of the Guardian|exorcised of the dark taint within...]]\r\n==Quotes==\r\nMedivh has made many statements, worthy of quotation. However, there is one that is the most memorable; his farewell at the end of the Third War (and [[Warcraft III]]), below.\r\n''The roots will heal in time... as will the entire world. The sacrifices have been made. Just as the orcs, humans, and night elves discarded their old hatreds and stood united against a common foe, so did Nature herself rise up to banish the Shadow...forever. As for me, I came back to ensure that there would be a future, to teach the world that it no longer needed Guardians. The hope for future generations has always resided in ''mortal'' hands. And now that my task is done, I will take my place...amongst the legends of the past.''\r\n==Magna Medivh==\r\nMagus Medivh may also be known as '''Magna Medivh''' following the tradition of previous Guardians. Although this hasn't been specifically confirmed. Most sources only refer to him as Magus Medivh. Medivh is never specifically referred to as Magna in any known source.\r\n==See also==\r\n*[[Chronicles of the War in Azeroth]] - A detailed history of Medivh's childhood and his relationship to [[Prince Llane]]\r\n*[[History of Warcraft]]\r\n*[[The Last Guardian]] - The tale of Khadgar's stay with Medivh\r\n**[[Aegwynn and the Dragon Hunt]]\r\n**[[The Last Guardian (History of Warcraft)|The Last Guardian]]",},
			["Meeda"] = { content = "'''Meeda''' is a level 66 [[banker]] located in [[Area 52]] in the [[contested]] territory of [[Netherstorm]].\r\nSee [[List of Netherstorm NPCs]].",},
			["Meela Dawnstrider"] = { content = "'''Meela Dawnstrider''' is a level 10 [[shaman trainer]] located in [[Camp Narache]] in the [[tauren]] starting zone of [[Mulgore]].\r\nSee [[List of Mulgore NPCs]].",},
			["Meeting Note"] = { content = "==Source==\r\nThis item is provided for Wyrmskull Watcher.\r\n==Meeting Note as a quest objective==\r\nThis item is an objective of Wyrmskull Watcher.",},
			["Meeting Stone"] = { content = "'''Meeting Stones''', also known as '''Summoning Stones''', are very large thumb-shaped stones with a mystical, glowing symbol that appear next to [[instance]]d dungeons. , they were for filling in partial (or just-starting) [[Party|parties]] whose members meet the required by auto-inviting suitable candidates. Later, the option was added to enter a Meeting Stone queue for a dungeon whose level requirements you met by talking to any innkeeper.\r\nIn [[Patch 2.0.1]], the Meeting Stones were reworked with the implementation of the new [[Looking For Group|LFG System]]. They now are used to summon party members to the stone near an instance. One player targets a faraway player, and clicks the Meeting Stone, creating a portal. When a second player clicks the portal, the targeted player is given a summoning dialogue very similar to the [[Ritual of Summoning| Warlock Summon]] spell.\r\nNote that the summoner and the person being summoned must both meet the suggested level range for the dungeon for the stone to be usable. The second person, who clicks on the portal to finalize the summon, can be of any level.\r\nNOTE: On PvP servers, several Meeting Stone areas are very popular ambush points. E.g., Alliance attempting to use the [[Scarlet Monastery|SM]] Meeting Stone, in Horde territory and close to an occasionally highly trafficked instance, frequently find themselves ganged up on, depending on server population, levels and the social norms of the server. Enjoy.",},
			["Mehlar Dawnblade"] = { content = "'''Mehlar Dawnblade''' is a level 58 [[blood elf]] [[quest giver]] located at the [[Bulwark]] on the border between [[Tirisfal Glades]] and the [[Western Plaguelands]]. He harbors deep hatred toward his former mentor, the late [[Uther the Lightbringer]], for teaching [[Prince Arthas]] in the way of the [[paladin]], believing he was responsible for Arthas' betrayal and the subsequent destruction of [[Quel'Thalas]]. However, the ending text to Defiling Uther's Tomb implies his realization that his actions might be both too harsh and too hasty. His counterpart is the [[draenei]] [[Anchorite Truuen]] at [[Chillwind Camp]].\r\nMehlar appeared at the Bulwark after patch [[2.0.1]], \"Before the Storm\".\r\nHe starts the following quests: \r\n* Prove Your Hatred\r\n**Wisdom of the Banshee Queen\r\n* The So-Called Mark of the Lightbringer\r\n** Defiling Uther's Tomb\r\nHe ends the following quests:\r\n*To The Bulwark\r\n*Ancient Evil\r\n==See also==\r\n*[[Tirisfal Glades NPCs]]\r\n*[[List of blood elves in Azeroth]]",},
			["Meilosh"] = { content = "'''Meilosh''' is a level 55 [[tradeskill]] [[vendor]] and (though accepts only [[Runecloth]] and [[Mooncloth]] from players [[Friendly]] or above) [[cloth quartermaster]] located in [[Timbermaw Hold]] in the [[contested]] territory of [[Felwood]]. He is a member of the [[Timbermaw Furbolgs]], and some of the items he sells require a good reputation with his tribe.\r\nHe starts the following quests:\r\n* Runecloth (Friendly)\r\n* Sacred Cloth (Friendly)\r\nBoth quests reward experience points, an item, and better reputation with the Timbermaw Furbolgs.\r\nSee [[List of Felwood NPCs]].\r\n==Reputation Recipes==\r\nWhen your reputation becomes Friendly with the Timbermaw Furbolgs, Meilosh will start selling plans and patterns available to friends of the Timbermaw. As your reputation goes higher, you will gain access to more plans. \r\n===Alchemy===\r\nFriendly\r\n*[[Transmute: Earth to Water]] (Alchemy 275, [[Limited Sale Recipe]])\r\n===Blacksmithing===\r\nHonored\r\n*[[Heavy Timbermaw Belt]] (Blacksmithing 290, [[Limited Sale Recipe]])\r\nRevered\r\n*[[Heavy Timbermaw Boots]] (Blacksmithing 300)\r\n===Enchanting===\r\nFriendly\r\n*[[Enchant 2H Weapon - Agility]] (Enchanting 290)\r\nHonored\r\n*[[Enchant Weapon - Agility]] (Enchanting 290, [[Limited Sale Recipe]])\r\n===Leatherworking===\r\nFriendly\r\n*[[Warbear Harness]] (Leatherworking 275, Tribal, [[Limited Sale Recipe]])\r\n*[[Warbear Woolies]] (Leatherworking 285, Tribal, [[Limited Sale Recipe]])\r\nHonored\r\n*[[Might of the Timbermaw]] (Leatherworking 290, [[Limited Sale Recipe]])\r\nRevered\r\n*[[Timbermaw Brawlers]] (Leatherworking 300)\r\n===Tailoring===\r\nHonored\r\n*[[Wisdom of the Timbermaw]] (Tailoring 300, [[Limited Sale Recipe]])\r\nRevered\r\n*[[Mantle of the Timbermaw]] (Tailoring 300)",},
			["Meitre"] = { content = "The '''Meitre scrolls''', so named because they were written by the [[night elf]] [[wizard]] [[Meitre]], were a collection of academic spell scrolls that were considered highly advanced. In arcane academies, such as those in [[Dalaran]] and [[Silvermoon]], it was established policy that apprentices not be allowed near them. The students of [[Scavell]] all read the scrolls, though only [[Aegwynn]] did so with permission, and was able to gain mastery over the spells and rituals in the scrolls in record time. The scrolls covered magical topics ranging from transmutation to advanced ward-penetration, and likely a number of other subjects. \r\nFor much of Aegwynn's tenure as Guardian, the Meitre Scrolls served as a sort of advanced guideline for magical theory; however, by the time that [[Jaina Proudmoore]] was training, the Scrolls had been largely laid aside, and the only known copies were lost when the Violet Citadel was destroyed.",},
			["Meitre scrolls"] = { content = "#REDIRECT [[Meitre]]", redirect = "Meitre",},
			["Mei Francis"] = { content = "'''Mei Francis''' is a [[vendor]] found in [[Dalaran]] that sells unique mounts.",},
			["Mekeda"] = { content = "'Auchindoun is home to my ancestor's spirits. We might not look it, but all Broken were once draenei... our spirits are all the same.'\r\n <span style= \"font-variant:small-caps\">~ Mekeda - Refugee Caravan, Terokkar Forest</span>\r\n'''Mekeda''' is a level 70 [[quest giver]] located at the [[Refugee Caravan]] in the [[contested]] territory of [[Terokkar Forest]]. He is a [[Broken]] belonging to the [[Lower City]] faction. His friend, [[Akuno]] is held hostage in the [[Shadow Tomb]] to the west. Tired of waiting on aid for the caravan to come from Shattrath, he takes the initiative of thinning the [[Cabal]]'s members. He is disgusted with how the cult has treated [[Auchindoun]] and its sacred relics. \r\nHe starts the following quests:\r\n* Before Darkness Falls\r\n* The Shadow Tomb\r\nSee [[List of Terokkar Forest NPCs]].",},
			["Mekgineer's Chopper"] = { content = "The '''Mekgineer's Chopper''' is a motorcycle mount created by top Alliance engineers. Its Horde counterpart is the [[Mechano-hog]].\r\n==Source==\r\nThis item can be crafted using [[Engineering]] (480).",},
			["Mekgineer Sicco Thermaplugg"] = { content = "#REDIRECT [[Sicco Thermaplugg]]", redirect = "Sicco Thermaplugg",},
			["Mekgineer Steamrigger"] = { content = "'''Mekgineer Steamrigger''' is the second [[boss]] in [[Steamvault|The Steamvault]] of [[Coilfang Reservoir]]. It is a large bipedal robot controlled by [[leper gnomes]]. ''Sprawling pumping systems operate day and night throughout Coilfang Reservoir, built by the naga and their servants to drain the waters of Zangarmarsh. At the heart of this industrial complex is the Steamvault, where arcane technology drives the machinery used in the distillation process. To command the engineers who maintain and operate this machinery, Lady Vashj hired the renowned Mekgineer Steamrigger, a gifted gnome technician whose illness has damaged his sanity, but not his fierce dedication to his craft.''\r\n==Abilities==\r\n*'''Shrink Ray''': Reduces damage done by 35% with chance to backfire.\r\n*'''Sawblade''': Mekgineer Steamrigger will randomly toss out a sawblade hitting for around 1500-2500 to everyone within range. \r\n*'''Electrified Net''': Immobilizes target for 10 sec. 600-700 damage.\r\n*'''Gnome Repairers''': A few times during the fight at 75%, 50% and 25% health, he will call upon 3-4 gnomes to heal him. These gnomes have 5k hp and deal 200-500 melee damage on hit. These are non-elite mobs and should receive all focus from DPS, to prevent boss from healing. The healing is a channeled spell which break on damage, and after it has been broken the gnome will start it again after a few seconds, so keep the DPS up.\r\n*'''Melee''': 800-1300 damage at 55% reduction (13k Armor)1500-2000 damage to cloth.\r\n*'''Enrage''': Enrages after 5 minutes (heroic mode only)\r\n==Strategy==\r\nEvery 25% health at 75%, 50% and 25% health he shouts \"Tune 'em up good boys!\", three to five Steamrigger Mechanics appear. These are non-elite, and can be killed quickly and should be first priority as they start healing Mekgineer Steamrigger. Pvp trinket and [[gnome]] [[tank]] can be helpful here, if you want to grab the [[aggro]] back after you had a net on you; druids can also shift form to break the net. Any damage whatsoever to the mechanics forces them to attack you and not heal the boss. So if your tank has an attack that can hit multiple mobs at once, you can disrupt them and bring them to your tank, giving your [[DPS]] time to pick them off one by one without them healing the boss.\r\nOnly one of Mekgineer Steamrigger's attacks causes magical damage (the electrical net), and the amount is negligible compared to the rest of his damage, so a mage may want to put [[Amplify Magic]] on the party before the fight.\r\n===Poison Notes===\r\n*[[Deadly Poison]] works on him, as does [[Envenom]].\r\n*[[Wound Poison]] also works on him.\r\n===Heroic Mode===\r\nSteamrigger in [[heroic mode]] is almost identical to normal mode, except that an extra gnome appears every 7 seconds or so. So DPS need to burn it down in addition to the normal 3 spawn that comes when Steamrigger announces \"Tune em' up boys!\". The tank can Thunderclap to interrupt heals temporarily, but the gnomes quickly switch back to healing so it only buys 3-4 seconds at most. Druid tanks can use swipe to prevent healing until dps can pick up the gnomes. Priests should [[Fear]] gnomes that are beating on [[clothies]] when possible.\r\nThis fight is made trivial by the use of a paladin who uses [[Consecrate]]. Consecrate will almost kill the gnomes and stop them from healing by the time there are so many that you should [[AoE]] them down. [[Thunder Clap]] will most likely do marginal damage but will hold aggro and reduce healing until there are enough that AoE will be worth it. If you do not have any serious AoE then you can use low mana AoE effects to keep them from healing since every damage done will stop their heal ability. A Magma Totem works fine if you can keep them from destroying it. \r\nSteamrigger also enrages after 5 minutes on [[heroic mode]] and quickly one shots the party.\r\n==Quotes==\r\nAggro: 'I'm bringin' the pain!'\r\n'You're in for a world of hurt!'\r\n'Eat hot metal, scumbag!'\r\n'I'll come over there!'\r\nSummon: 'Tune 'em up good boys!'\r\nKill: 'You just got served, punk!'\r\n'I own you!'\r\nEnrage: 'Have fun dyin', cupcake!'\r\nDeath: 'Mommy!",},
			["Mekgineer Thermaplugg"] = { content = "#REDIRECT [[Sicco Thermaplugg]]", redirect = "Sicco Thermaplugg",},
			["Mekkatorque"] = { content = "#REDIRECT [[Gelbin Mekkatorque]]", redirect = "Gelbin Mekkatorque",},
			["Meklo"] = { content = "'''Meklo''' was the older [[goblin]] in charge of creating the [[Dragon Soul]] and armor for [[Neltharion]]. He was always muttering calculations to himself.",},
			["Melaris"] = { content = "'''Melaris''' is a level 30 [[alchemy]] [[vendor]] located in [[Court of the Sun]] in the [[blood elf]] capital of [[Silvermoon City]].\r\nSee [[List of Silvermoon City NPCs]].",},
			["Melee"] = { content = "'''Melee''' is a form of [[combat]] (usually physical) that requires the attacker to be relatively close (arm plus weapon length) to the target as opposed to a [[ranged]] attack. Sometimes also called \"hand-to-hand\" or \"close combat\". Pronounced as mā-ˌlā / may-lay.\r\nClose [[Weapon|weapon]] combat as opposed to [[Ranged|ranged]] weapon or [[Spell|spell]] combat.\r\nWorld of Warcraft typically defines 'Melee Range' as 5 Yards or closer.\r\n==Typical Melee Weapons==\r\nTypical melee weapons used:\r\n* ([[Unarmed]])\r\n* [[Axe]]\r\n* [[Dagger]]\r\n* [[Fist Weapon]] \r\n* [[Hammer]]\r\n* [[Mace]]\r\n* [[Polearm]]\r\n* [[Staff]]\r\n* [[Sword]]\r\n==Melee Ability Comparison By Class==\r\nNOTE: This is only a comparison of overall melee DPS ability (It does not include mitigation). Spellcasting or at least spellcasting specialized classes will have poor melee DPS, while the pure melee or melee specialized classes will have high melee DPS.\r\nExcellent:\r\nThese classes have the highest potential for melee DPS, even without specialization.\r\n* [[Warrior]] (Arms or Fury spec providing highest DPS)\r\n* [[Rogue]] (Openers, stuns, other skills, and finishers)\r\nFair:\r\nThese classes can comfortably hold their own in melee, but unless specialized in it will be inferior to a Warrior or Rogue. With equal level of gearing, talents, and playing ability they can meet or exceed said classes' melee DPS.\r\n* [[Paladin]] (Auras and Seals/Judgments)\r\n* [[Shaman]] (Totems, Weapon Enchants, AP Buffs, Dual Wield, etc)\r\n* [[Druid]] (Feral spec (cat form), rogue-like dps, Leader of the Pack aura) \r\nPoor:\r\nThese classes can just about cope in melee, but have more efficient means of combat at their disposal.\r\n* [[Priest]] (Inner Fire and Shadow Form (if specced for it), Power Word Shield gives mitigation, but should Fear and run away to cast better spells)\r\n* [[Hunter]] (Raptor Strike and Mongoose Bite, but should [[Wing Clip]] to gain range/kite)\r\nBad:\r\nThese classes should avoid any kind of melee combat where possible; even running away rather than engaging in melee.\r\n* [[Mage]] (Use Frost Nova and Sheep crowd control, back off and nuke.)\r\n* [[Warlock]] (Defend with [[Fire Shield]] and [[Demon Skin]]/[[Demon Armor]], but should use the pet to handle melee. Warlock should instead DOT/Nuke [depending on spec] from a distance)",},
			["Melee hunter"] = { content = "Some hunters focus their talents on melee weapons. These brave individuals take up the spear or axe and stalk dangerous creatures until they are close enough to pounce. They revel in the danger of their actions, feeling an unparalleled rush when they can bring a deadly creature down in equal combat - especially if they use their bare hands. Other hunters will prefer to use twin daggers, augmented by the elemental power of their traps, although their style of dagger fighting is much more loose and improvisatory than that of the [[Rogue]].\r\nThe melee hunter's animal companion assists its master by distracting the enemy and flanking it.\r\n===Melee hunters in World of Warcraft===\r\nThe ''melee hunter'' in WoW is popularly considered a poor joke, as melee hunters do laughably little damage compared to a hunter actually using ranged weapons. Calling a hunter a ''melee hunter'' would be considered an insult by most hunters.\r\nUnfortunately, some new hunters are lured into thinking that meleeing is a viable way of playing their class, since in the early levels, they have no pet to keep their enemies [[tank]]ed at a distance. And, indeed, melee combat is not ''that'' much worse than ranged at very low levels. \r\nThough often looked upon as inferior, Melee Hunting is indeed a very viable spec for PVP.\r\nThe spec is: \r\nGearing is loose, as long as it contributes to both melee and ranged. The strategy is to use the hunter's dance in excess, using melee, but also using special ranged abilities and damage, as well as CC. The logic behind it is that you output average damage if the enemy is at range or manages to close at melee. Many 5v5 teams of all melee hunters have managed to reach 2000+ arena ratings.",},
			["Melee weapon"] = { content = "'''Melee weapons''' include any weapon [[equip]]pable in the [[Main Hand]] or [[Off Hand]] [[slot]].",},
			["Melgromm Highmountain"] = { content = "'''Melgromm Highmountain''' is a level 70 [[elite]] [[tauren]] [[shaman]] for the [[Horde]]. He spawns during the [[Dark Portal Opens]] event, specifically when the [[Dark Portal]] is starting to be overrun by demons. He spawns along with 5 other elite 60 Thunder Bluff Hunters. Surprisingly he wields a two-handed totem/carved log as a weapon, which is rare. Although he is definitely associated with the Horde, he is friendly to everyone. He must reach the very front of the portal to despawn. He can cast Chain Healing and Chain Lighting. He is probably related to [[Trag Highmountain]] and/or [[Huln Highmountain]]. After this event he can later be found on the [[Stair of Destiny]], which is where players come out to when crossing through the [[Dark Portal]]. Here he battles with Horde forces on the right and Alliance forces on the left against Legion siegebreakers attempting to go through the reopened Dark Portal.\r\n==Quotes==\r\n* Yells as he spawns: \"Hunters, to me! Let us show these demons what it is to fight and die in Azeroth!\"\r\n* Says: \"The spirits sing to us! They sing the song of battle!\"\r\n* Says: \"Strike true, brothers and sisters! Today our quarry is demons!\"\r\n* Says: \"Once again, we will show this Burning Legion that our world is not for the taking!\"\r\n* Says: \"These fiends will fail! For Azeroth!\"\r\n* Says: \"If it is our fate to die this day, then we will not go easy! Mark me, these demons will fall like wheat!\"\r\n* Says: \"Though your sinews tire and your blood flows from cuts and wounds to this sodden ground, you fight for the spirits of your world. No evil force can stand against us!\"\r\n* Yells as he despawns: \"My brethern, my commands-in-arms! I must go to seek the forces of the Horde and direct them here! Keep your spirits strong, brave hunters! Do not fall to the portal-spawned fiends!\"\r\n<Note: He only \"yells\" during the [[Dark Portal Opens]] [[Event]], and not in Outland.>",},
			["Melika Isenstrider"] = { content = "'''Melika Isenstrider''' is a level 11 [[NPC]] located at [[Lion's Pride Inn]] in [[Goldshire]], in the [[human]] starting zone of [[Elwynn Forest]]. She is the Assistant [[innkeeper]].\r\nShe may be related to [[Falkhaan Isenstrider]].\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Melithar Staghelm"] = { content = "'''Melithar Staghelm''' is a level 5 [[quest giver]] located outside [[Aldrassil]] in the [[night elf]] starting zone of [[Teldrassil]].\r\nHe starts the quest The Woodland Protector.\r\nIt is unknown what his relationship with Arch Druid [[Fandral Staghelm]] is, but presumably they are related in some manner.\r\nSee [[List of Teldrassil NPCs]].",},
			["Melizza Brimbuzzle"] = { content = "'''Melizza Brimbuzzle''' is a level 39 [[quest giver]] located in a cage in the [[Valley of Spears]] in the [[contested]] territory of [[Desolace]]. Her brother is [[Hornizz Brimbuzzle]].\r\nShe starts the quest Get Me Out of Here!.\r\nSee [[List of Desolace NPCs]].",},
			["Melor Stonehoof"] = { content = "'''Melor Stonehoof''' is a level 62 [[quest giver]] located on the [[Hunter Rise]] in the [[tauren]] city of [[Thunder Bluff]].\r\nHe starts the following quests:\r\n* The Hunter's Way\r\n* Sergra Darkthorn\r\n* Steelsnap\r\n* Frostmaw\r\n* Deadmire\r\nSee [[List of Thunder Bluff NPCs]].",},
			["Melris Malagan"] = { content = "'''Melris Malagan''' is a level 58 Captain of the Guard located in [[the Trade District]] in the [[human]] city of [[Stormwind City]].\r\nSee [[Stormwind City NPCs]].",},
			["Membership Benefits"] = { content = "==Description==\r\nThe [[Consortium]] is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.\r\nThe quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us.\r\n==Rewards==\r\n* At reputation with The [[Consortium]]: Gem-Stuffed Envelope\r\n* At reputation with The [[Consortium]]: Unmarked Bag of Gems\r\n* At reputation with The [[Consortium]]: Bulging Sack of Gems\r\n* At reputation with The [[Consortium]]: Bag of Premium Gems\r\n==Notes==\r\n* At the beginning of each new month you can collect a bag of gems.\r\n* This is the only [[monthly quest]] to exist in the game.",},
			["Menag"] = { content = "'''Menag''', the Bandit Lord of the [Bloodhill Bandits]], accosted the farmer [[Villager Gerard|Gerard]] and his wife, [[Villager Matilda|Matilda]] when [[Arthas]] was in [[Strahnbrad]]. Menag stole Gerard's ledger. Without the ledger, Gerard would lose his farm. Menag then fled with his men across a river as he saw Prince Arthas, a paladin, approaching. Arthas hunted Menag down at the request of Gerard, killed Menag and got the ledger back.",},
			["Menagerie Wreckage"] = { content = "The '''Menagerie Wreckage''' is an area containing multiple crashed cages and escaped [[ravager]]s. The caged creatures tumbled from the [[Exodar]] before it plowed into the eastern part of the [[Azuremyst Isle]], and now threaten the local fauna with the alien presence.",},
			["Menara Voidrender"] = { content = "'''Menara Voidrender''' is a level 50 [[quest giver]] located in [[Ratchet]] in the [[Horde]]-aligned territory of [[the Barrens]].\r\nShe starts the following quests:\r\n* Components for the Enchanted Gold Bloodrobe\r\n* Components for the Enchanted Gold Bloodrobe\r\n* Components for the Enchanted Gold Bloodrobe\r\n* Components for the Enchanted Gold Bloodrobe\r\n* The Completed Robe\r\n* Fragments of the Orb of Orahil\r\n* The Completed Orb of Dar'Orahil\r\n* Shard of a Felhound\r\nSee [[List of the Barrens NPCs]].",},
			["Mending Old Wounds"] = { content = "==Objective==\r\nBring the [[Mupsi Shacklefridd]] 40 Linen Cloth and 4 Empty Vial.\r\n==Quest Text==\r\nYou'd better think twice before setting foot in Ratchet, ''<name>''! Words been getting around of your dirty deeds.\r\nYou're in luck though, a ship just arrived with many wounded from an encounter with the [[Bloodsail Buccaneers]]. This is your chance to prove you're not an complete scoundrel. Lend us a hand by bringing linen cloth for bandages and empty vials for potions.\r\n==Completion==\r\nI'm happy you're seeing the error of your ways, ''<name>''. Keep the supplies coming; We're not going to forget about you so easily, mister!\r\n==Rewards==\r\n* Reputation with [[Ratchet]] +500\r\n* Reputation with [[Booty Bay]], [[Everlook]], and [[Gadgetzan]] +250 (Unmentioned)\r\n* Reputation with [[Bloodsail Buccaneers]] -500\r\n==Notes==\r\nIf you are at 0/36000 :\r\n* You will need to do 72 turn ins of 40 Linen Cloth and 4 Empty Vials to reach: \"\"\r\nIf you are at 0/3000 :\r\n* You will need to do 6 turn ins of 40 Linen Cloth and 4 Empty Vials to reach: \"\"\r\nIf you are at 0/3000 :\r\n* You will need to do 6 turn ins of 40 Linen Cloth and 4 Empty Vials to reach: \"\"\r\nSo in all you will need to do a grand total of 90 turn ins which is:\r\n* 3600 Linen Cloth\r\n* 360 Empty Vial",},
			["Mend Pet"] = { content = "'''Mend Pet''' is a level 5 [[hunter]] ability. This is a hunter's primary method of healing their pet.\r\nIn the [[spellbook]], this ability is found inside the Pet Utility button. It also shares a button with [[Revive Pet]]; when you have a pet out and alive, Mend Pet will show on the shared button. When your pet is dead or you don't have a pet summoned, Revive Pet will show instead.\r\n==Notes and trivia==\r\n*Unaffected by [[critical strike]].\r\n*Pet healing is counted for purposes of the [[Leech]] tertiary stat. What this means is that the hunter will share in Mend Pet's effect, though for a ''significantly less'' amount.\r\n*Mend Pet is one of [[hots:Rexxar|Rexxar]]'s abilities in ''[[Heroes of the Storm]]''.",},
			["Menethil's Gift"] = { content = "'''Menethil's Gift''' refers to the pentagram-like symbol upon the ground at the slaughterhouse in [[Stratholme]]. [[Baron Rivendare]] stands not far from it.\r\nMenethil's Gift is ground that was 'blessed' by the [[Lich King]]. It is the Scourge-equivalent of holy ground.\r\nIt was the site where [[Ras Frostwhisper]] committed suicide and was raised as a Lich. Interestingly, [[Leonid Barthalomew the Revered]], in describing the ceremony, implies that the Lich King was corporally present in [[Stratholme]]: \"The Lich King stood over the fallen mage...\" This would seem to imply that the Lich King has at some point visited Lordaeron following his joining with [[Arthas Menethil]], or perhaps that Arthas' past actions are being attributed to the Lich King, for they now are one.\r\n==Quests==\r\n*Menethil's Gift \r\n*Menethil's Gift (2)",},
			["Menethil Bay"] = { content = "'''Menethil Bay''' is a portion of the [[Great Sea]] off the west coast of central [[Eastern Kingdoms]], mostly noted by travelers on the western coast of the [[Wetlands]] around [[Menethil Harbor]]. It is crawling with [[crocolisks]] of various ages and sizes, often hunted for their fine leather.",},
			["Menethil Harbor"] = { content = "*Population: 12,000\r\n'''Menethil Harbor''' (men-a-thill) is a port [[town]] on the western shore of the [[Wetlands]]. It has a [[boat]] that sails to [[Theramore Isle]] in [[Dustwallow Marsh]], on the continent of [[Kalimdor]]. Within the city are many [[vendor]]s; a [[First Aid Trainer]], the [[Deepwater Tavern]], and a [[Gryphon]] [[Flight Master]]. \r\nThis major port city represents the [[Alliance]] presence in the Wetlands. Murlocs and Dragonmaw orcs are a constant threat to its citizens, who are braver and sterner than their kin. [[Captain Stoutfist]], the town's military leader, can be found in [[Menethil Keep]] working to repel the Dragonmaw orcs. The captain is particularly concerned because the orcs seem to be preparing for a major assault.\r\n==History==\r\nMenethil Harbor is named after the ruling dynasty of Lordaeron. The first Menethil Harbor existed between the times of the Second and Third Wars.\r\nHorde and Scourge forces devastated the Wetlands in the Second and Third Wars, forcing the Ironforge dwarves to retreat to Loch Modan and Dun Morogh. Alliance forces have since established the current Menethil Harbor, but the area is still wild and untamed.\r\nIt was originally established at the end of the [[Third War]] as the main sea link between [[Khaz Modan]] and the kingdoms of [[Alliance]]. It is the only stationary Alliance presence in the Wetlands, a small well-fortified city that numbers a little over ten thousand souls. Murloc and pirate incursions are a minor threat.\r\nMenethil Harbor still serves a critical purpose as it serves as the main hub of Alliance naval routes between the old kingdoms of [[Khaz Modan]] and [[Stormwind]], and their new allies at [[Theramore Isle]] and [[Auberdine]].\r\n===Flight===\r\n [[Ironforge]]\r\n [[Thelsamar]]\r\n [[Refuge Pointe]]\r\n [[Southshore]]\r\n===Boat===\r\n [[Theramore Isle]]\r\n [[Valgarde]] (replaces Auberdine, WotLK)",},
			["Menethil Keep"] = { content = "'''Menethil Keep''' is the fort that dominates the port town of [[Menethil Harbor]]. It is currently led by [[Captain Stoutfist]], the commander of the Menethil militia. Besides several guards, it also holds a few additional [[quest giver]]s and a [[vendor]].",},
			["Mennet Carkad"] = { content = "'''Mennet Carkad''' is a level 30 [[quest giver]] located in [[the Rogues' Quarter]] in the [[forsaken]]'s [[Undercity]].\r\nHe starts the following quests:\r\n* The Deathstalkers\r\n* The Deathstalkers (2)\r\n* The Deathstalkers (4)\r\n* Fenwick Thatros\r\n* Tools of the Trade\r\nSee [[List of Undercity NPCs]].",},
			["Mennu the Betrayer"] = { content = "After betraying his kind to the naga under Lady Vashj's rule, '''Mennu the Betrayer''' and several loyal [[Draenei]] subordinates now guard the [[Slave Pens]] in [[Coilfang Reservoir]]. Mennu is an example of a Broken who has found a way to turn Illidan's reign of terror to their advantage, by betraying his fellow draenei he gained favor with his naga overlords. His betrayal has tainted his shaman training, and he now wields corrupted totems, which make him a formidable opponent for any group. He is the first of the three bosses in the [[Slave Pens]].\r\n==General Information==\r\n*Health (Normal): 60,000\r\n*Mana (Normal): about 6,700\r\n*Health (Heroic): 185,000\r\n*Mana (Heroic): Approximately 30,000\r\n==Spells and Abilities==\r\n*'''Mennu's Healing Ward:''' Heals Mennu for 1% of his total life every second (600 non-heroic, 1,850 heroic).\r\n*'''Tainted Earthgrab Totem:''' Periodically casts an [[AoE]] [[Entangling Roots]]. Causes very low (~72 a tick on heroic) damage and has a relatively small range.\r\n*'''Tainted Stoneskin Totem:''' Gives Mennu a large boost in armor, reducing damage from melee.\r\n*'''Corrupted Nova Totem:''' Explodes after 5 secs for around 2,500 fire damage to everyone in a 10 yard radius of the totem.\r\nHeroic mode: Explodes after ~15 seconds or when destroyed for around 6500 fire damage in a 10 yard radius of the totem. Melee DPS should put on gear in which they get ~7.1k health so they can survive a higher end damage range if the totem is accidentally destroyed. Ranged DPS and healers should take care not to stand close to the totem because higher end damage will probably oneshot them.\r\n*'''[[Lightning Bolt]]:''' Deals 1,000 - 1,600 nature damage, cast only on the character who currently has aggro. Uninterruptible.\r\nHeroic mode: Hits for about 2600-3200 nature damage, cast only on the character who currently has aggro. Uninterruptible.\r\n==Strategies==\r\nFighting Mennu is an endurance test. He has 60,000 HP and healing abilities, but doesn't put out a lot of damage. It is, however, critical that his totems be killed relatively quickly. \r\nMennu paths up and down a ramp which you use to get to [[Rokmar the Crackler]]. The mobs at the bottom of the ramp pull in two separate groups, though neither of them must be pulled to kill the boss. Mennu can be pulled at range as he is going up the ramp and he will not aggro the groups at the base of the ramp. After he is dead, these groups can be avoided by going around behind the ramp to the other side and up the ramp. Caution: Lower level characters may aggro these mobs after the boss is defeated when mounting the ramp.\r\nHealers should not have any trouble healing through damage. An excellent strategy is to have the tank walk backwards in a large circle while keeping aggro on Mennu; this will ensure that he is out of range of his totems most of the time. Note that hitting his Corrupted Nova Totem will cause it to go off instantly, so avoid shooting it whenever possible. Any class can one-shot the totems, so even the healer can deal with most of them via wanding, simple melee damage or rank one [[Earth Shock]]/[[Moonfire]].\r\n[[Grounding Totem]] will absorb lightning bolts (in both heroic and non-heroic modes), and warriors can use [[Spell Reflection]] on them.\r\n==Heroic mode strategies==\r\nHeroic Mennu the Betrayer is fundamentally the same fight as the non-heroic. He is generally considered to be the easiest heroic boss but his totems (particularly the Corrupted Nova) can quickly ruin the fight if left alive. Use the same strategy as normal mode Mennu, having the tank walk backwards in a large circle while a party member kills all his totems but the Corrupted Nova.\r\n==Quotes==\r\n'''On aggro:''' ''The work must continue.''\r\n'''On aggro:''' ''Don't make me kill you!''\r\n'''On aggro:''' ''You brought this on yourselves.''\r\n'''On killing a player:''' ''It had to be done.''\r\n'''On killing a player:''' ''You should not have come.''\r\n'''On death:''' ''I... Deserve this.''",},
			["Mental Agility"] = { content = "'''Mental Agility''' is a tier 4 talent which reduces the mana cost of instant cast spells.\r\n==Tips and tactics==\r\nThis talent is fairly essential in a Circle of Healing build, as it significantly reduces the mana cost of one of your main healing spells.\r\n",},
			["Mental Dexterity"] = { content = "==Rank table==\r\n==Notes==\r\n* New talent, useful for Enhancement Shamans who use intellect to boost their attack power and mana pool.",},
			["Mental Quickness"] = { content = "'''Mental Quickness''' is a [[Shaman]] passive talent that reduces the mana cost of instant cast spells by {2/4/6%} and increases [[spell damage and healing]] by {10/20/30%} of your [[attack power]].\r\n==Notes==\r\n*Mental Quickness affects totems, shocks, elemental shields ([[Lightning Shield]], [[Water Shield]]), and other spells such as [[Bloodlust]] or [[Heroism]].\r\n==Past changes==\r\n*In [[Patch 2.3]], added increased spell damage and healing equal to 10/20/30% of your attack power",},
			["Mephistroth"] = { content = "A horrifically powerful [[Dreadlord]], '''Mephistroth''' was third in the ranks of the [[Nathrezim]]. Mephistroth remained in the [[Twisting Nether]], with [[Anetheron]] during the Third War.\r\nWhen Archimonde came to Azeroth, he brought Anetheron with him, but Mephistroth remained behind in the Twisting Nether, presumably to maintain order within the Nathrezim. Even after the systematic deaths of Tichondrius, Anetheron, and Archimonde, Mephistroth remained intact (he is presumed to have taken the place of both Tichondrius and Anetheron as leader of the Dreadlords), waiting to wreak his havoc on the world another day.\r\n==Memorable quotes==\r\n*\"The [[Arthas|human]] means nothing in the long run. [[Ner'zhul]] wouldn't dare undermine our efforts now.\"''",},
			["Mephit"] = { content = "'''Mephits''' are clawed elemental flying creatures hailing from the [[Elemental Plane]] and the [[Twisting Nether]]. On the elemental plane mephits and lesser elementals share a position of power just above [[Sprite|elemental sprites]], but are below all other denizens of the planes. Mephits are tolerated only because they amuse the Elemental Lords or because the Lord in question sees fit to keep them around, to Al'Aqir they are akin to pets, while [[Therazane]] treats hers as her cherished children. Mephits fight in mobs, which is often the case when encountered in the Twisting Nether. The mobs may be made up of various types. Some can be found on [[Azeroth]] such as a [[Dark Iron dwarf|Dark Iron]] cave in the [[Badlands]].\r\n==Mephit Types==\r\nAir Mephit : A type of mephit found in the [[Skywall]]. Holds a position in the air elemental hierarchy just above air elemental sprites (spark sprites, lightning sprites).\r\nEarth Mephit : A type of mephit found in [[Deephome]]. Holds a position in the earth elemental hierarchy just above earth elemental sprites (stone sprites).\r\nFire Mephit : A type of mephit found in the [[Firelands]]. Holds a position in the fire elemental hierarchy just above fire elemental sprites (flame sprites).\r\nWater Mephit : A type of mephit found in the [[Abyssal Maw]]. Holds a position in the water elemental hierarchy just above water elemental sprites (frost sprites).\r\nSteam Mephits : Steam mephits are perhaps a conglomerate mephit of fire and water. Some steam Mephits live in a Dark Iron controlled cave in the Badlands inside of a sulfurous hot spring. The steam mephits get along well with the Dark Irons, who find them amusing. But they eagerly attack other interlopers. The mephits rarely get a chance to do some damage, so they fight with enthusiasm. When they begin a fight they all use their boiling rainstorm ability from the far side of the pool. They can also summon more steam mephits which also can cast the boiling rainstorm. They then often flit about the chamber breathing steam and raking with their claws. They use their flight and the hot spring to their tactical advantage, submerging themselves in the pool to heal..",},
			["Mercenary"] = { content = "'''Mercenaries''' (\"Mercs\") are players who have decided to fight for money, rather than traditional methods such as Professions. Although primarily an RP thing, anyone who accepts cash for non-material goods on a regular basis can be considered a Mercenary. [[Rogue]]s and [[Warrior]]s might seem more inclined toward Mercing than other classes, but any class can be a Mercenary.\r\n==Mercenary types==\r\nThe sole requirement of being a Merc is that they are worth being hired, since free is a hard price to beat. There are different approaches to this problem, each distinctive in strengths and weaknesses.\r\n===Skill===\r\nThese are the simplest type of Mercenary: They are hired because they are better players than someone that could be gotten for free. They, unlike Level or Gear mercenaries, are able to sell their services to almost anyone, as they are not dependent upon being a higher level or having better Gear than those hiring them. Most commonly used as a little extra kick on an otherwise shaky Raid, or as an escort through dangerous territory. They are (Usually) better at the former than the other two kinds, as most Skill Mercs require more cunning than their kin.\r\nTheir primary disadvantage of a Skill Merc is that until they reach end game, their market is limited to those of their level range. This being said, it becomes obvious Skill Mercs aren't exactly ridden with flaws.\r\nThey have the largest Market of all Solo Mercs.\r\n===Level===\r\nThe most common kind of Mercenary, the Level Merc depends on being a higher level than their employers. Mainly used to run through instances. The primary disadvantage of a Level Merc is low profits: They only appeal to those a lower level than them, and as such at lower levels they have a very small market, and unless their employer is a funded alt, they receive low pay in comparison to their level. They have the smallest Market of all Mercs.\r\n===Gear===\r\nIn practicality more or less the same as a Skill Merc, a Gear Merc depends on being better geared than whoever is paying them. They are more or less [[Twinks]] that get paid, and for this many see them as less skilled, even if better combatants, than the employer.\r\nThe Gear Merc's biggest weakness is that they must spend most of their earnings towards obtaining and maintaining their gear. Their market is limited to jobs that would not normally be taken on by someone with the same or better equipment as them.\r\nThey have the second smallest market of Solo Mercs.\r\n===Group===\r\nThe Group Merc depends on others, they belong to a group of other Mercs that will be able to take on jobs they could not individually accomplish. This group is usually referred to as a Merc Band, or Band for short. Bands can be composed of any of the above Mercs, or simply of Players that prefer numbers to Gear, Level, or skill. Bands are used as muscle in groups and raids to lower the player count, therefor increasing the xp and gear split between the group. Since there is strength in numbers, the only times when a Group Merc setup would not be optimal is when the employer wants a little help grinding, or when the level limit is beyond their capability.\r\nLarge Mercenary forces have been hired in the past by kingdoms to defeat opposing factions, though it is rare for such forces to be used.\r\nThe biggest weakness of group Mercs is that they must split the pay amongst themselves, meaning that there is only a fraction of the pay to each member. Although the fact that the jobs are usually bigger than Solo Mercs, thus increasing pay per job, offsets this to a degree, more often than not a Group Merc finds themselves working harder than most Mercs for their Gold.\r\nGroup Mercs have the largest market of all Mercenaries, and are likely to see more action.\r\n==Greed==\r\nAlthough Greed is always an incentive to a Merc, more often Mercs will hire themselves out because it's a more interesting source of income than farming resources for professions or running dungeons for sellable gear. In fact, Mercing probably pays less than the aforementioned methods, simply because most Players do not hire Mercs on a regular enough basis for there to be a thriving market.",},
			["Merchant Coast"] = { content = "The '''Merchant Coast''' is the name given to the small portion of the [[Barrens]] that forms the coastline of the [[Great Sea]]. Along the Merchant Coast is the [[goblin]] port town of [[Ratchet]], and the [[Theramore]] outpost, [[Northwatch Hold]]. Off the coast is the [[warrior|warrior's]] haven, [[Fray Island]]. The Merchant Coast receives its name from the lucrative trade that takes place through the thrifty hands of the Ratchet goblins.",},
			["Merchant Felagunne"] = { content = "'''Merchant Felagunne''' is a general goods vendor onboard the ''[[Feathermoon Ferry]]'', the boat that runs between [[Feathermoon Stronghold]] and [[The Forgotten Coast]]. He sells anything you could possibly need, and also repairs gear. \r\n==Notes==\r\n* He can not be killed.\r\n* He does not sell ammunition.",},
			["Merchant Frostwalker"] = { content = "'''Merchant Frostwalker''' is a general goods vendor onboard the ''[[Elune's Blessing]]'', the boat that runs between [[Auberdine]] and [[Valaar's Berth]]. He sells anything you could possibly need, and also repairs gear.\r\n==Notes==\r\n* He can not be killed.\r\n* He does not sell ammunition.",},
			["Merciless Gladiator's Leather Gloves"] = { content = "==Source==\r\nThis item is a PvP reward, and can be purchased for a=1125 gold from Krixel Pinchwhistle in [[Netherstorm]].",},
			["Mereldar"] = { content = "#redirect [[Lake Mereldar]]", redirect = "Lake Mereldar",},
			["Meridith the Mermaiden"] = { content = "'''Meridith the Mermaiden''' is a level 60 [[naga]] [[quest giver]] in [[Tanaris]]. She is encountered during the [[Scepter of the Shifting Sands]] quest chain, and can be found off the eastern part of [[Land's End Beach]].\r\nShe has been in love with [[Narain Soothfancy]] ever since he crashed (with a Gnomish flying machine, as expected) onto her shore, though it is implied that he kindly accepted her help and ran away as soon as he could (and realized that she was into him).\r\n==Notes==\r\n*She is one of the few friendly Naga in game. The others being the renegade [[Skar'this the Heretic]], and [[Zalashji]] who just roams a cave named after him.\r\n==Quests==\r\n*Love Song for Narain",},
			["Merissa Stilwell"] = { content = "'''Merissa Stilwell''' can be found at [[Goldshire]] in [[Elwynn Forest]] and ends the quest Welcome! (Northshire Abbey).",},
			["Merithra of the Dream"] = { content = "The ancient [[Green Dragon]] '''Merithra''' (known as '''Merithra of the Dream''') is a child of [[Ysera]] and a major figure in the War of the Shifting Sands. She can be found in the Temple of [[Ahn'Qiraj]] taking the form of a [[Night Elf]], taken captive by the [[Qiraji]] alongside [[Caelestrasz]] and [[Arygos]]. When approached she, like [[Arygos]], offers to craft weapons when given Imperial Qiraji Regalia and three [[Elementium]] Ores.\r\n==History==\r\nWhen the [[Qiraji]] started their [[War of the Shifting Sands|first invasion]] of [[Kalimdor]], [[Anachronos]] agreed to enlist the [[Bronze Dragonflight]] against the marauding Qiraji with the [[Night Elf|Night Elves]]. Even with the might of the dragons backing them, however, the sheer numbers of the Qiraji and silithid proved overwhelming. And so Anachronos called upon the progeny of the remaining flights, including Merithra of the [[Green Dragonflight]]\r\nMerithra, along with [[Caelestrasz]] and [[Arygos]], pushed the [[Qiraji]] back into [[Ahn'Qiraj]] to allow [[Anachronos]], [[Fandral Staghelm]], and the Night Elves to create a magical barrier to hold in the Qiraji. The three dragons and their companions flew headlong into the Qiraji legions, into the city where they hoped their sacrifice would not be in vain. Though the magical barrier was created, the three dragons were lost within the walls, where they still remain today, in humanoid form, as prisoners of the Old God [[C'thun]].\r\n==Quests==\r\nMerithra of the Dream starts the quest Imperial Qiraji Regalia.\r\nSee [[Temple of Ahn'Qiraj NPCs]].\r\n==Quotes==\r\n*Succumb to the endless dream, little ones. Let it consume you!",},
			["Meri Ironweave"] = { content = "'''Meri Ironweave''' is a level 19 [[armor]] & [[shield]] [[vendor]] located in [[Dolanaar]] in the [[night elf]] starting zone, [[Teldrassil]].\r\nSee [[List of Teldrassil NPCs]].",},
			["Merrin Rockweaver"] = { content = "'''Merrin Rockweaver''' is a level 30 [[quest giver]] located at [[Whelgar's Excavation Site]] in the [[dwarven]] territory of the [[Wetlands]]. She is affiliated with the [[Explorers' League]].\r\nShe starts the quest In Search of The Excavation Team. She also completes the previous stage of the same chain of quests, which you pick up from her husband on the bridge before the gate to Menethil. As you enter the excavation site from the north heading south, don't start killing raptors in the dig, looking for her in the dig as I did. Instead, turn left and find a banner that starts a path climbing the mountain, she is in a cave on top. Her companion gives a quest to find some items in the site. Now you can go down and kill raptors to your heart's content. Two of the items are in the dig, the other two are up the hill to the west.\r\nSee [[List of Wetlands NPCs]].",},
			["Meryl Felstorm"] = { content = "Meryl Felstorm is an undead warlock featured in DC Unlimited's ''World of Warcraft: Series 1'' action figure set.\r\nMeryl appears to be wearing the [[Corruptor Raiment]].\r\nMeryl has not yet appeared in any other media.\r\n==See also==\r\n[[Warcraft Action Figures]]",},
			["Mesa Buzzard"] = { content = "'''Mesa Buzzard'''s are level 34-35 [[Carrion Bird]]s native to the [[Arathi Highlands]].\r\n==Patch Changes==\r\nPrior to patch [[2.3.2]] these birds were , but are no longer.",},
			["Meshlok the Harvester"] = { content = "[[Meshlok the Harvester]] is a level 48 [[elite]] [[rare mob]] [[bog beast]] found in [[Maraudon]]. He is found at the end of the purple section, near where it converges with the orange section at the Poison Falls.",},
			["Message to Maxwell"] = { content = "==Objectives==\r\nTravel to the [[Burning Steppes]] and give [[Bijou's Information]] to [[Marshal Maxwell]]. \r\n* Bijou's Information (Provided)\r\n== Description==\r\nI'm a goblin of my word, <race>. Now listen closely:\r\nThese orcs are used primarily as beasts of burden and cannon fodder for the black dragonflight!\r\nTheir true leader is none other than Nefarian, brood of Deathwing. I've also discovered the location of Nefarian's subordinates in this part of the citadel.\r\nTake this map to [[Marshal Maxwell]] in the [[Burning Steppes]]. It has the location of these fiends marked for easy identification. \r\n== Reward==\r\nYou will receive:1 gold 80 silver copper \r\n== Progress==\r\nAh, <name>. It has been a long time. \r\n== Completion==\r\nThis coincides with much of what we already knew. Regardless, it is interesting and rather unfortunate information.\r\nThe markings on this map will prove valuable in thinning the Blackrock menace. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*6400 [[XP]] (or 39 silver copper at level 70)\r\n*250 [[reputation]] with [[Stormwind]]",},
			["Metal"] = { content = "A mineral [[item]] found as raw [[ore]] (in most cases) from [[Mining]] [[vein]]s and [[deposit]]s often usable as an [[ingredient]] for [[professions]] (usually [[Blacksmithing]] or [[Engineering]]) after being [[smelt]]ed into a purer [[bar]] form.\r\n===Mined Metals===\r\n* [[Copper]]\r\n* [[Tin]]\r\n* [[Bronze]] — Alloy of Tin and Copper\r\n* [[Silver]]\r\n* [[Iron]]\r\n* [[Gold]]\r\n* [[Steel]] — Alloy of Iron and [[Coal]]\r\n* [[Mithril]]\r\n* [[Truesilver]]\r\n* [[Thorium]]\r\n* [[Dark Iron]]\r\n===[[BC]] Metals===\r\n* [[Adamantite]]\r\n* [[Hardened Adamantite]] — Smelted from Adamantite\r\n* [[Fel Iron]]\r\n* [[Eternium]]\r\n* [[Khorium]]\r\n* [[Felsteel]] — Alloy of Fel Iron and Eternium\r\n* [[Hardened Khorium]] — Alloy of Hardened Adamantite and Khorium\r\n===Special Metals===\r\n* [[Enchanted Thorium]] — Created by [[Enchanting|Enchanters]]\r\n* [[Arcanite]] — Created by [[Alchemy|Alchemists]]\r\n* [[Elementium]] — Dropped in [[Blackwing Lair]]\r\n===Other Metals===\r\n* [[Adamantine]] - from \r\n* [[Darkspine Iron Ore|Darkspine Iron]] - Quest; dropped by [[Darkspine]] [[naga]]s and their [[Greengill]] slaves and found in Darkspine ore chests on the [[Isle of Quel'Danas]]\r\n* [[Elunite Ore|Elunite]] - Quest; from a crate in [[Darkshore]]\r\n* [[Fel Stone]] - from \r\n* [[Lead]] - No known use; from [[Gnomeregan]]\r\n* [[Lesser Bloodstone Ore|Lesser Bloodstone]] - Quest; from cave in the [[Arathi Highlands]]\r\n* [[Incendicite Ore|Incendicite]] - Quest; from cave in the [[Wetlands]]\r\n* [[Indurium Ore|Indurium]] - Quest; from [[Uldaman]]\r\n* [[Platinum]] - from \r\n* [[Rethban Ore|Rethban]] - Quest; from cave in the [[Redridge Mountains]]\r\n* [[Umbral Ore|Umbral]] - Quest; from a strongbox in [[Dun Morogh]]\r\n* [[Underlight Ore|Underlight]] - Quest; dropped by [[Blackpaw]] [[gnoll]]s in the [[Ghostlands]]",},
			["Metallic Fragments"] = { content = "'''Metallic Fragments''' are quest items needed by the Horde for the quest Natural Materials.\r\n==Source==\r\nMetallic fragments drop from mobs in [[Feralas]] and [[The Hinterlands]]:\r\n*Feralas\r\n**Hippogryphs in the [[Frayfeather Highlands]]\r\n**[[Wandering Forest Walker]]s\r\n**Giants\r\n*The Hinterlands\r\n**Owlbeasts\r\n==Metallic Fragments as a Quest Objective==\r\n*Natural Materials\r\n==Notes==\r\nStacks in groups of 40.",},
			["Meta gem"] = { content = "A '''meta gem''' is a gem that only fits in a ''meta gem socket''. A '''meta gem socket''' only accepts a ''meta gem''.\r\n==Meta gem requirements==\r\nPrior to [[patch 7.0.3]], each meta gem had a set of requirements. These requirements were that the wearer's equipment also had a particular number of other gems. If those requirements were met, the meta gem provided its bonus. If they were not, the meta gem was inactive.\r\nExample:\r\n[[Shielded Skyflare Diamond]]\r\nFor this meta gem, if the character's gear had\r\n:-- at least 2 gems that \"fit in sockets\" (are blue, green, purple or prismatic)\r\n:-- and 1 gem that \"fits in sockets\" (is red, orange, purple, or prismatic)\r\nthis meta gem would be active.\r\nA gem that matched more than one required color (purple or prismatic, for the above example) would satisfy any requirements that it matched. For instance, this meta gem would become active with as little as one blue gem and one purple gem socketed in equipped items.\r\nA [[prismatic]] gem on your gear counted for all meta gem color requirements. One [[Nightmare Tear]], for example, was enough to activate your [[Destructive Skyflare Diamond]].\r\nMeta gems added in ''[[World of Warcraft: Mists of Pandaria|Mists of Pandaria]]'' did not have this requirement.\r\n==What equipment has meta gem sockets?==\r\nMeta gem slots are [[socket]]s that (currently) only appear on particular varieties of [[:Category:World of Warcraft head items|headgear]]. Most often, meta gem slots are found on items intended for \"end game usage\": level 70/80/85/90 gear, arena gear, ''dungeon sets'', and so on.\r\n==Meta gem properties==\r\nMeta gems of the same name adjective have the same effects, but may have different activation requirements.\r\n==See also==\r\n* [[Meta gems|List of meta gems]]\r\n* [[:Category:Meta socketable gems|The '''meta gems''' category]]",},
			["Meta gems"] = { content = "'''Meta gems''' match meta sockets. These gems have special requirements that must be met for the gem's bonus to activate. For example, in order to gain the benefits of a [[Destructive Skyfire Diamond]] there must be a minimum of 2 gems of each color between all the items currently equipped on the character. \r\nIt should be noted that gems which match multiple socket colors can fulfill meta gem requirements for any color they match. For example, if a meta gem needs 3 red and 2 yellow to activate, 3 orange (red/yellow) gems can activate this gem. Also, a gem does not have to match its socket to contribute to a meta gem; therefore, the player may choose to lose an item's gem bonus in order to activate the meta gem's bonus. So far only high-end helms have meta sockets.\r\n==See also==\r\n*[[Meta Socket Helmet List]]",},
			["Metzen"] = { content = "#REDIRECT [[Chris Metzen]]", redirect = "Chris Metzen",},
			["Metzen on Lore"] = { content = "#REDIRECT [[Metzen on lore]]", redirect = "Metzen on lore",},
			["Metzen the Reindeer"] = { content = "'''Metzen the Reindeer''' is a level 5 [[deer]] who was kidnapped during the [[Feast of Winter Veil]] by both the [[Dark Irons]] of [[Searing Gorge]], and the [[Southsea Freebooters]] of [[Tanaris]], somehow at the same time.\r\nHe can be freed using a Pouch of Reindeer Dust.\r\n==Quests==\r\n* Both versions of Metzen the Reindeer. Note, that Metzen can be freed from either location regardless of what your quest notes say.",},
			["Meven Korgal"] = { content = "'''Meven Korgal''' is a messenger of the [[Scarlet Crusade]] found in a camp of [[Scarlet Convert]]s and [[Scarlet Initiate]]s southeast of [[Deathknell]] in [[Tirisfal Glades]]. [[Executor Arren]] wants the documents he carries.\r\n==Attacks and abilities==\r\n*'''[[Melee|Basic Melee]]''': 4-7 damage (before subtracting armor)\r\n==Quests==\r\n* The Red Messenger - from [[Executor Arren]] in [[Deathknell]]\r\n:Objective: Kill '''Meven Korgal''', the messenger, at the Crusader camp, then return [[Scarlet Crusade Documents|any information]] you find to [[Executor Arren]].\r\n==Quotes==\r\n*\"The Scarlet Crusade shall not fail in its mission!\"\r\n*\"These lands shall be cleansed!\"\r\n*\"These undead atrocities will be destroyed!\"",},
			["Miao'zan"] = { content = "'''Miao'zan''' is a level 25 [[artisan]] [[alchemy trainer]] located in [[Sen'jin Village]] in the [[orcish]] starting zone of [[Durotar]].\r\nSee [[List of Durotar NPCs]].",},
			["Miblon Snarltooth"] = { content = "'''Miblon Snarltooth''' guards a nursery of evoroot which is used by [[Gregan Brewspewer]] to make Videre Elixir.\r\nYou can find Miblon north east of the main ruins . Simply drop the bait bought from Gregan on the floor and he will run to eat it. This will open up the nursery and you can collect the evoroot for your quest.",},
			["Michael Bell"] = { content = "'''Michael Bell''' provided the voice of [[Medivh]], Druids of the Talon, and Necromancers in [[Warcraft III: Reign of Chaos]], and also provided the voice of the Druid player-character and the Harrogath elder Nihlathak in ''Diablo II: Lord of Destruction''. Outside of Blizzard, he is also famous for his voice work in ''Batman, the Animated Series'', ''Voltron'', ''Star Trek'', ''Transformers'', ''Rugrats'' and the ''Metal Gear Solid'' series. Other video game credits include the voice of Raziel, the main character in the Soul Reaver games.",},
			["Michael McConnohie"] = { content = "'''Michael McConnohie''' provided the voices of [[Uther the Lightbringer]] in [[Warcraft III]], [[Kel'Thuzad]] in both Warcraft III and [[World of Warcraft]], and [[Aeonus]] and [[Epoch Hunter]] in ''[[World of Warcraft: The Burning Crusade]]''. He also voiced Warriv and the Necromancer player-character in ''Diablo II'' and ''Diablo II: Lord of Destruction''.\r\nOutside of Blizzard, he is renowned as being a major voice actor in English dubs of Japanese anime, including ''Witch Hunter Robin'', ''Appleseed'', ''Naruto'' and ''Ghost in the Shell: Stand Alone Complex''. He has also provided other voices for video games, including Astaroth in ''Soulcalibur III'' and ''Soulcalibur Legends''. In live action work, he provided voices of villians in the various ''Power Rangers'' series, and was the voice of Master Tatsu, the Shredder's lieutenant, in the first two ''Teenage Mutant Ninja Turtles'' movies.",},
			["Michael Schweitzer"] = { content = "'''Michael Schweitzer''' is the manager of [[Level 80 Elite Tauren Chieftain]]. He is [[forsaken]]. His friend Steven Thomas has come to visit him while he is in [[Silvermoon City]] with the band, he is organizing the bands latest tour. They are found in [[Walk of Elders]] with his roadie [[troll]] Roitau.",},
			["Micha Yance"] = { content = "'''Micha Yance''' is a level 40 trade goods [[vendor]] located in [[Southshore]] in the [[contested]] territory of [[Hillsbrad Foothills]]. Likely related to [[Thomas Yance]].\r\nSee [[List of Hillsbrad Foothills NPCs]].",},
			["Michelle Belle"] = { content = "'''Michelle Belle''' is a level 11 [[first aid trainer]] located in [[Lion's Pride Inn]] in [[Goldshire]], in the [[human]] starting zone of [[Elwynn Forest]].\r\nHer name is quite probably a reference to the Beatles song, 'Michelle, ma belle\"\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Michel Koiter"] = { content = "'''Michel Koiter''' was one of Blizzard's best and most influential artists. The Shrine of the Fallen Warrior in the Barrens, west of the Crossroads, was erected in his honor.\r\n* Twin brother of [[René Koiter]]. Duo known as [[Twincruiser]].\r\n* Died March 18, 2004\r\n*",},
			["Micro dungeon"] = { content = "#redirect [[Elite area]]", redirect = "Elite area",},
			["Micro menu"] = { content = "#REDIRECT [[Micro Menu]]", redirect = "Micro Menu",},
			["Middenvale"] = { content = "'''Middenvale''' is a wooded area of southwestern [[Bloodmyst Isle]]. Its most notable feature is a pair of crashed escape pods from the [[Exodar]]. [[Treant]]s, [[bear]]s and [[lasher]]s roam the vale.",},
			["Midnight"] = { content = "'''Midnight''' is Attumen the Huntsman's personal mount, with which he used to terrorize intruders and fight his enemies. She is known as one of the (if not ''the'') fastest and strongest existing horses. A local rumor says that a supernatural mount still haunts the domain, in search of a worthy rider, most notably Midnight after the death of her rider.\r\nShe is a neutral boss in Karazhan and attacking her starts the Attumen encounter.\r\nAttumen can drop Midnight as a mount, as [[Fiery Warhorse's Reins]].\r\n==Notes==\r\n*Her saddle was taken by the [[Ebon Blade]] during the [[Burning Legion]]'s [[third invasion]].",},
			["Midrealm Post"] = { content = "'''Midrealm Post''' is a very small settlement located in the southeastern part of [[Eco-Dome Midrealm]]. It is led by [[Consortium|the Consortium]], but also has a couple of [[goblin]] representatives from [[Area 52]].",},
			["Midsummer Festival"] = { content = "#REDIRECT [[Midsummer Fire Festival]]", redirect = "Midsummer Fire Festival",},
			["Midsummer Fire Festival"] = { content = "The '''Midsummer Fire Festival''' is a seasonal event that celebrates the hottest season of the year. It starts on the (earthly) northern summer [[wikipedia:solstice|solstice]], and lasts about two weeks (June 21 &ndash; July 4). It is similar to the [[Lunar Festival]] and other holidays, featuring some useful buffs, food, and toys to play with.\r\nIt was introduced in [[Patch 1.11]], and given a major revamp in June 2008.\r\nFrom on the official website:\r\n''Ah, so you weren't chosen for Flamekeeper this year? Don't fret, my friend! The Midsummer Fire Festival isn't merely about that traditional honor; it's a time of merriment, a chance to celebrate the hottest season of the year by lighting great fires across the land and sharing in what the elemental spirits can offer. Come to our camps and join in the revelry!''\r\nThe ending of the Festival seems to have been merged with the [[Engineers' Explosive Extravaganza]] holiday:\r\n''The lengthy Midsummer Fire Festival traditionally ends with the sky itself being set alight. The goblins of Undermine have lent their considerable skill (and copious amounts of gunpowder) to the task, resulting in a tremendous fireworks show! Take up a festival mug and raise a toast to the season as the multicolored explosions dance across the sky above you!''\r\n==Overview==\r\n* Using Ribbon Poles causes a colorful streamer of energy to go to your hand and causes you to dance. This gives a 3 minute [[Ribbon Dance]] buff increasing earned experience by 10%. This buff stacks up to 20 times (60 minutes), increasing its duration by 3 minutes for every 3 seconds you keep dancing around the pole. Shamans, buff your weapon with flametongue.\r\n* When thrown into a festival fire, Burning Blossoms give you a buff [[Fire Festival Fury]], 3% critical strike and spell critical strike rating for sixty minutes as well as causing fire damage to attackers.\r\n* If a bonfire has gone out, tossing a Burning Blossom in it will provide a zone wide buff, [[Bonfire's Blessing]], that gives you a 30% chance to inflict Fire damage on any melee, range or spell attack - the exact amount of Fire damage dealt is based on your level x10. Bonfire's Blessing is capable of delivering a critical hit with 100% additional damage and is subject to spell bonus damage. This buff goes away if the opposite faction desecrates the bonfire.\r\n* Special flame samples can be collected from the bonfires in each of the four main cities of the opposing faction. Each sample will begin a quest called \"Stealing the [City]'s Flame.\" Upon completing each quest, everyone in the capital city will receive [[Fire Festival Fortitude]], a +30 stamina buff. Once all 4 have been collected and returned to a Festival representative, you receive the quest \"A Thief's Reward\" and are rewarded with the [[Crown of the Fire Festival]]. Anyone can loot the flame, but taking the quest requires level 50. \r\n==Burning Blossom redemption==\r\nThere are several items you can get from redeeming Burning Blossom at [[Midsummer Supplier]]s and [[Midsummer Merchant]]s. You can get 632 (H), 622 (A) Blossoms at the first day of the Festival and 20 Blossoms through Daily Quests from the second day until the end of the festival. It is not possible to get all rewards in one year if you farm the maximum possible amount of Blossoms.\r\n===Given from Festival Loremasters & Talespinners===\r\n[[Burning Blossom]] can be earned through a variety of quests. The blossoms can be consumed for a small buff, or saved for a variety of items including [[Brazier of Dancing Flames]]. Finding all the flames and doing all the quests during the 14-day period should award 882 (A) or 892 (H) Blossoms.\r\nStarter quests:\r\n* The Master of Summer Lore\r\n* Incense for the Summer Scorchlings\r\n* The Spinner of Summer Tales\r\n* Incense for the Festival Scorchlings\r\nDaily quests:\r\n* Torch Tossing (Alliance)\r\n* Torch Catching (Alliance)\r\n* More Torch Tossing (Alliance)\r\n* More Torch Catching (Alliance)\r\n* Torch Tossing (Horde)\r\n* Torch Catching (Horde)\r\n* More Torch Tossing (Horde)\r\n* More Torch Catching (Horde)\r\nQuest chains:\r\n# Unusual Activity\r\n# An Innocent Disguise\r\n# Inform the Elder\r\nPlayers then are given access to quests based on their level:\r\n* Striking Back (level 22)\r\n* Striking Back (level 32)\r\n* Striking Back (level 43)\r\n* Striking Back (level 51)\r\n* Striking Back (level 60)\r\n* Striking Back (level 67)\r\n* Ahune, the Frost Lord\r\n** Ahune is Here!\r\n*** Shards of Ahune\r\n*** Summon Ahune\r\n===Lord Ahune===\r\nA new chain of quests was added to the game, beginning at a talespinner. The end of the chain culminates in a daily quest to summon [[Lord Ahune]], a new boss in the [[Slave Pens]].\r\n===Bonfires (2008)===\r\nFinding a bonfire of your own faction and speaking to the appropriate NPC will reward you with 5 Burning Blossom and 5 gold 95 silver at level 70.\r\nFinding a bonfire of the opposite faction and using (stamping upon) it will reward 10 Burning Blossom and 11 gold 99 silver at level 70. All opposing faction bonfires may be doused without pulling guards, providing you are sufficiently high level, but the bonfire in [[Wildhammer Stronghold]] in [[Shadowmoon Valley]] may be doused without pulling guards only if you have a flying mount or can stealth to the fire, making this a fast and easy way to generate Midsummer Festival currency. Dousing another faction's bonfire will flag you for PVP combat.\r\nThe bonfires of Capital cities have separate quests and you cannot 'Honor the Flame' of your own faction's Capitals.\r\nAs there are 32 Alliance Fires and 30 Horde Fires, you can get as Alliance 550 gold 10 silver and 460 Blossoms, and as Horde 562 gold 18 silver and 470 Blossoms, not counting quests or capital bonfires.\r\n''See [[Alliance Bonfire]]s and [[Horde Bonfire]]s.''\r\n[[Quest:Bonfires (Horde)|Here]] is a suggested order for Horde to complete quests to honor and desecrate fires.\r\n===Stealing the Cities' Flames===\r\nEach faction can \"loot\" the Flames of the opposing faction's cities, each of which starts a quest. Stealing all four cities flames will offer the quest A Thief's Reward. '''While any character can loot the quest item, the quests themselves require level 50.'''\r\n'''Horde'''\r\n*[[Orgrimmar]] - Next to [[Mannoroth]]'s armor in the Valley of Wisdom \r\n*[[Thunder Bluff]] - On the Spirit Rise \r\n*[[Undercity]] - In the courtyard, just inside \r\n*[[Silvermoon City]] - Court of the Sun, inside, in the back \r\n*Flame of Darnassus -> Stealing Darnassus's Flame\r\n*Flame of Ironforge -> Stealing Ironforge's Flame\r\n*Flame of Stormwind -> Stealing Stormwind's Flame\r\n*Flame of the Exodar -> Stealing the Exodar's Flame\r\n'''Alliance'''\r\n*[[Stormwind]] - Outside Stormwind Stockades, North of Mage Quarter \r\n*[[Ironforge]] - Hall of Explorers \r\n*[[Darnassus]] - Rut'theran Village \r\n*[[The Exodar]] - The Crystal Hall \r\n*Flame of Orgrimmar -> Stealing Orgrimmar's Flame\r\n*Flame of Thunder Bluff -> Stealing Thunder Bluff's Flame\r\n*Flame of the Undercity -> Stealing the Undercity's Flame\r\n*Flame of Silvermoon -> Stealing Silvermoon's Flame\r\nReward: Crown of the Fire Festival (no bonuses).\r\n==Sortable list of bonfires==\r\n''See also [[Alliance Bonfire]]s and [[Horde Bonfire]]s.''",},
			["Midsummer Merchant"] = { content = "''Were you looking for the alliance midsummer vendor? See [[Midsummer Supplier]].''\r\n'''Midsummer Merchant''' can be found by bonfires in horde capital cities. It is worth noting, that while they can be aggroed, and hit, they cannot be killed, stopping at 1% health. For this reason they may want to be avoided while stealing flames. This can also be used to cause a never ending battle by pulling Midsummer Merchants/Suppliers of the opposing faction into a friendly city.\r\n==Sells==\r\nSee [[Midsummer Fire Festival|Burning Blossom redemption]].",},
			["Midsummer Supplier"] = { content = "''Were you looking for the horde midsummer vendor? See [[Midsummer Merchant]].''\r\n'''Midsummer Suppliers''' can be found by bonfires in alliance capital cities. It is worth noting, that while they can be aggroed, and hit, they cannot be killed, stopping at 1% health. For this reason they may want to be avoided while stealing flames. This can also be used to cause a never ending battle by pulling Midsummer Merchants/Suppliers of the opposing faction into a friendly city.\r\n==Sells==\r\nSee [[Midsummer Fire Festival|Burning Blossom redemption]].",},
			["Might"] = { content = "==Armor==\r\n*[[Battlegear of Might]], [[Tier 1]] raid set for [[warrior]]s\r\n==Spell==\r\n*[[Blessing of Might]], [[paladin]] [[blessing]] for [[melee]] classes\r\n==Groups==\r\n*[[Might of Cenarius]]\r\n*[[Might of Hakkar]]\r\n*[[Might of Kalimdor]]\r\n*[[Might of the Scourge]]\r\n*[[Might of the Timbermaw]]\r\n*[[Might of the Tribe]]",},
			["Mightfish Steak"] = { content = "==Source==\r\n'''Mightfish Steak''' is crafted by [[Cooking|Cooks]] with a skill level of 275. This requires a [[Cooking Fire]].\r\nThe components are:\r\n*1 Large Raw Mightfish\r\n*1 Hot Spices\r\n*1 Soothing Spices\r\nRecipe: Mightfish Steak can be purchased from [[Sheendra Tallgrass]] in [[Camp Mojache]] and [[Vivianna]] in [[Feathermoon Stronghold]] in [[Feralas]]",},
			["Might of Kalimdor"] = { content = "The '''Might of Kalimdor''' was a combined [[Alliance]]-[[Horde]] army raised in response to the stirring of the [[Qiraji]], locked behind the [[Scarab Wall]] in [[Silithus]]. They were gathered at [[Cenarion Hold]] - in the center of the silithid hives that dominated the region - during the [[Ahn'Qiraj]] [[War Effort]]. After [[Shiromar]] opened the [[Scarab Wall]] and the war ended, the Alliance members of the Might of Kalimdor splintered off to continue their duty in Outland, in the form of the [[7th Legion]]. As the 7th Legion, they did battle with the threats present in Outland, and are now situated in [[Northrend]] as the Alliance's elite vanguard against the legions of [[Naxxramas]].\r\n==Saurfang's Speech==\r\n<div style=\"background-color:#222222; color:#ff3030; margin-left:24px; padding:4px 8px 4px 8px;\">\r\n<span style=\"color:#f0d000;\">[[Varok Saurfang|<span style=\"color:]] stands before the Might of Kalimdor.</span>\r\nHigh Overlord Saurfang: I am Saurfang. Brother of [[Broxigar|<span style=\"color:]]. You know me to be the Supreme Commander of the Might of Kalimdor. An [[orc|<span style=\"color:]] - a true orc warrior - wishes for one thing: To die in the glory of battle against a hated enemy. Some of you have fought in battles. Peace has been with us for many years. Many years we sat idle but many years we battled. In those years - where strife, the land and [[Legion|<span style=\"color:]] and [[Scourge|<span style=\"color:]], sacked our homes, killed our families - these insects dwelled beneath us. Beneath our homes - waiting. Waiting to crush the life from our little ones. To slay all in their path. This they do for their god. And for our gods? We defend. We stand. We show that as one. United. We destroy. Their god will fall. To die today, on this field of battle, us to die an orcish death. To die today is to die for our little ones. Our old ones. Our … loved ones. Would any of you deny yourselves such a death? Such an honor?\r\n<span style=\"color:#f0f0b0;\">Ironforge Cavalryman: FER MAGNI!</span>\r\n<span style=\"color:#f0f0b0;\">Kaldorei Marksman says: FOR HONOR!</span>\r\nHighlord Leoric Von Zeldig: I am with you until I gasp my last dying breath.\r\nHigh Commander Lynore Windstryke: FOR [[Kalimdor||<span style=\"color:]]!\r\n</div>\r\n==Commanders==\r\n*[[High Overlord Saurfang]]\r\n*[[Highlord Leoric von Zeldig]]\r\n*[[High Commander Lynore Windstryke]]\r\n*[[Malagav the Tactician]]\r\n*[[Duke August Foehammer]]\r\n===Units===\r\n*Might of Kalimdor Archer\r\n*Might of Kalimdor Archmage\r\n*Might of Kalimdor Captain\r\n*Might of Kalimdor Druid\r\n*Might of Kalimdor Grunt\r\n*Might of Kalimdor Infantry\r\n*Might of Kalimdor Lieutenant\r\n*Might of Kalimdor Mage\r\n*Might of Kalimdor Major\r\n*Might of Kalimdor Marshal\r\n*Might of Kalimdor Priest\r\n*Might of Kalimdor Restorer\r\n*Might of Kalimdor Sergeant\r\n*Might of Kalimdor Shaman\r\n*Might of Kalimdor Skirmisher",},
			["Might of the Timbermaw"] = { content = "'''Might of the Timbermaw''' is a [[Leatherworking]]-crafted belt that give bonuses to [[Strength]] and [[Stamina]].\r\n=Source=\r\nMight of the Timbermaw is crafted by [[Leatherworking|Leatherworkers]] with a skill level of 290.\r\nThe components are:\r\n*30 [[Rugged Leather]]\r\n*2 [[Powerful Mojo]]\r\n*4 [[Living Essence]]\r\n*2 [[Cured Rugged Hide]]\r\n*2 [[Rune Thread]]\r\nThe [[pattern]] is a [[Limited Sale Recipe]] sold by [[Meilosh]] in the [[Timbermaw Hold]] in [[Felwood]]. You must have Honored reputation with the [[Timbermaw Furbolgs]] to purchase this pattern.\r\n=Notes=",},
			["Miihi"] = { content = "'''Miihi''' can be found in [[Terokkar Forest]] .",},
			["Miiji"] = { content = "'''Miiji''' can be found in [[Terokkar Forest]] .",},
			["Mike Miller"] = { content = "'''Mike Miller''' is a level 20 [[bread vendor]] located in [[Sentinel Hill]] in the [[human]] territory of [[Westfall]].\r\nSee [[List of Westfall NPCs]].",},
			["Mike Morhaime"] = { content = "#REDIRECT [[Michael Morhaime]]", redirect = "Michael Morhaime",},
			["Mike Schramm"] = { content = "#REDIRECT [[WoW Insider]]", redirect = "WoW Insider",},
			["Mikhail"] = { content = "'''Mikhail''' is a level 30 [[quest giver]] located in [[Deepwater Tavern]] in [[Menethil Harbor]], in the [[Alliance]]-aligned zone of [[Wetlands]].\r\nHe starts the following quests:\r\n* The Missing Diplomat\r\n* The Missing Diplomat\r\nSee [[List of Wetlands NPCs]].",},
			["Mild Spices"] = { content = "'''Mild Spices''' are used in many recipes to give the food extra flavor.\r\n==Source==\r\nThis item is sold by Cooking Suppliers and Trade Goods Merchants worldwide. They sell for c=10 gold for a stack of 5.\r\n==Mild Spices as an Ingredient==\r\n'''Mild Spices''' are used in the following recipes:\r\n===[[Cooking]]===\r\n*Delicious Chocolate Cake\r\n*Herb Baked Egg\r\n*Crispy Bat Wing\r\n*Spiced Wolf Meat\r\n*Roasted Kodo Meat\r\n*Goretusk Liver Pie\r\n*Fillet of Frenzy\r\n*Loch Frenzy Delight\r\n*Crab Cake\r\n*Dry Pork Ribs\r\n*Crocolisk Steak\r\n*Smoked Sagefish\r\n*Cooked Crab Claw\r\n*Savory Deviate Delight\r\n*Clam Chowder\r\n*Lean Venison\r\n*Lean Wolf Steak",},
			["Military Ward"] = { content = "'''The Military Ward''' serves as the command center for the [[Ironforge]] Military, as well as a center for all things martial. Weapon, armor, and gun shops are all located here. The center of the ward is the [[Hall of Arms]], which contains [[hunter]] and [[warrior]] trainers, [[battlemaster]]s, and a hangar for both [[steam tank]]s and [[dwarven flying machine]]s.\r\nTo get to the Military Ward, you can head east from [[the Commons]], southeast from [[the Great Forge]], or south from [[Tinker Town]].\r\n==Buildings==\r\n* [[Hall of Arms]]\r\n* Goldfury's Hunting Supplies\r\n* Bruuk's Corner, a bar\r\n* Timberline Arms, home of [[Buliwyf Stonehand]],50 [[Weapon Master]], and weapon merchants.\r\n* Craghelm's Plate and Chain, Armour Merchants",},
			["Millhouse Manastorm"] = { content = "'''Millhouse Manastorm''' is a level 70 elite [[gnome]] [[mage]] imprisoned in the [[Arcatraz]] wing of [[Tempest Keep]]. In order to acquire the [[Tempest Key]], formerly required to unlock [[Eye (Tempest Keep)|The Eye]] wing of Tempest Keep, players must enter Arcatraz on heroic mode, and make sure that Millhouse survives until the death of Harbinger Skyriss.\r\nHe is a gnome of unusual size, being about as tall as a [[dwarf]] \r\nHis rescue is a required part of Trial of the Naaru: Tenacity.\r\nSee [[Tempest Keep NPCs]].\r\n==Info==\r\nWhile the Arcatraz is a place of imprisonment for dangerous beings the [[Naaru]] encountered, Millhouse, in fact, was merely a victim of circumstance - A stowaway who was in the wrong Naaru vessel at the wrong time. It is unknown how he actually got to a Naaru vessel but it's quite possible that his curiosity over the mysterious Naaru and his knowledge of the Arcane played a major part in his entry.\r\nIn combat, he appears to be a jack of all trades, using [[Improved Frostbolt]]s, [[Ice Block]], [[Pyroblast]] and [[Improved Arcane Missiles]]. Of course, most elite NPC's have grown beyond the simple boundaries of talent specs, and Millhouse is no different.\r\n==Quotes==\r\n* \"Where in Bonzo's brass buttons am I? And who are-- yaaghh, that's one mother of a headache!\" (shortly after being released)\r\n* \"Lowly? Nobody refers to the mighty Millhouse Manastorm as lowly!\" (after Mellichar calls him a \"Lowly Gnome\")\r\n* \"I have no idea what goes on here, but I will gladly join your fight against this impudent imbecile!\" (when the fighting resumes)\r\n* \"Aaalllriiiight!! Who ordered up an extra large can of whoop-ass?\"\r\n* \"I'm gonna light you up, sweet cheeks!\" (when casting Pyroblast)\r\n* \"Ice ice baby!\" (when iceblock is used)\r\n* \"For the love of all that is holy, somebody HEAL me!\" (upon 20%)\r\n* \"You'll be hearing from my lawyers!\" (upon death)\r\n* \"Who's bad? Who's bad? That's right: we bad!\" (after Killing [[Harbinger Skyriss|Skyriss]])",},
			["Milling"] = { content = "'''Milling''', a sub-[[skill]] of [[Inscription]], is used to make pigments from [[herb]]s and can be obtained via the [[Herbalism]] skill. Five herbs of the same type are consumed per milling attempt and produce 1-4 pigments, with the most common result being a single pigment milled. Higher level herbs may also occasionally produce rarer pigments. \r\nSimilar to [[Prospecting]], the types of herbs that can be milled for pigments scales up according to your Inscription skill level.\r\n==Macros==\r\nMilling herbs has never been easier. (Fill in \"<herb>\" with your herb name)\r\n/cast Milling\r\n/use <herb>\r\n==Products==\r\nSo far, Milling has been seen to produce the following reagents:\r\n* Alabaster Pigment\r\n** From Silverleaf, Peacebloom, Earthroot\r\n* Dusky Pigment, Verdant Pigment\r\n** From Briarthorn, Swiftthistle, Bruiseweed, Stranglekelp, Mageroyal\r\n* Golden Pigment, Burnt Pigment\r\n** From Wild Steelbloom, Grave Moss, Kingsblood, Liferoot\r\n* Emerald Pigment, Indigo Pigment\r\n** From Fadeleaf, Goldthorn, Khadgar's Whisker, Wintersbite)\r\n* Violet Pigment, Ruby Pigment\r\n** From Firebloom, Purple Lotus, Arthas' Tears, Sungrass, Blindweed, Ghost Mushroom, Gromsblood\r\n* Silvery Pigment, Sapphire Pigment\r\n** From Golden Sansam, Dreamfoil, Mountain Silversage, Plaguebloom, Icecap\r\n* Nether Pigment, Ebon Pigment\r\n** From milling herbs native to Outland\r\n* Azure Pigment, Icy Pigment\r\n** From milling herbs native to Northrend",},
			["Milly Osworth"] = { content = "'''Milly Osworth''' is a level 2 [[quest giver]] located in [[Northshire Valley]] behind [[Northshire Abbey]], in the [[human]] starting zone of [[Elwynn Forest]]. She is the owner of the [[Northshire Vineyards]], which have been overrun by the [[Defias Brotherhood]]. She provides for the store of food and drink managed by [[Brother Neals]]. Milly is looking for anyone willing to help her get her harvest of grapes out of the vineyard in time.\r\nShe starts the following quests:\r\n* Milly's Harvest\r\n* Grape Manifest\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Milton Beats"] = { content = "==Pre-Patch 1.11==\r\n'''Milton Beats''' is a level 33 [[elite]] [[human]] found in the tunnel from the [[Hillsbrad Foothills]] to [[Ravenholdt Manor]]. Oddly enough, he wears an orange [[Syndicate]] bandana, as well as studded leather, whereas the rogues of Ravenholdt are garbed in mostly royal blue and black and lack bandanas.\r\nMilton ambushes [[rogue]]s who are foolish enough not to use [[Detect Traps]] during the quest The Manor, Ravenholdt.\r\n==Post-Patch 1.11==\r\nMilton still spawns after the change of [[Detect Traps]] from an activated ability to a passive one. Now, however, the giant warning above the chest from which he springs forth, is much more visible and clear to eager and uncautious rogues. Anyone still foolish enough to open the decoy is sure to be hazed as they enter Ravenholdt.",},
			["Mimblis Evermorne"] = { content = "'''Mimblis Evermorne''' was a [[paladin]] and member of the [[Knights of the Silver Hand]]. He was a friend of [[Uther Lightbringer]].",},
			["Mimmil"] = { content = "'''Mimmil''', a male [[murloc]], is the senior [[tiderunner]] of the [[Dark Ray tribe]]. He is revered as the mightiest [[tiderunner]] to appear since the murlocs moved above the water, and his skills are legendary. His talent at taming and riding [[shark]]s is particularly admired.",},
			["Min'loth"] = { content = "'''Min'loth the Serpent''' was a powerful magician, shaman or priest (him being referred to as \"The Snake\" would indicate that he was most probably a [[Loa Gods|Snake-God]] priest) in service of [[Var'gazul]]. His seat of power was in the city of [[I'lalai]].\r\nFor some reasons, either the plans of conquest, or the water magic used by Min'loth, caused the wrath of [[Neptulon]] to come upon an unsuspecting [[Gurubashi|Gurubashi Empire]], proving its ultimate downfall. Min'loth was, however, successful in causing pain to the [[Krakken]], a feat not achieved by a mortal in aeons. This only caused the Krakken to become angrier for they are old and they hold many secrets. And though Min'loth's spell was strong, it, like the troll, was mortal. The Kraken caused great waves to move towards I'lalai. Min'loth had time to turn to his adepts and whisper his last words — which were etched in stone. The ocean then fell upon I'lalai and its inhabitants. Even after the waters had receded from the lands, they surged around I'lalai and remained, drowning it forever.",},
			["Mind's Eye"] = { content = "==Source==\r\nThis item drops from [[Mai'Zoth]] in [[Stranglethorn Vale]].\r\n==Mind's Eye as a quest objective==\r\nThis item is an objective for the following quests:\r\n* The Mind's Eye\r\n* Mai'Zoth",},
			["Mind-numbing Poison (item)"] = { content = "'''Mind-numbing Poison''' is a poison that is created by [[rogue]]s who then apply it to their weapons. Every time the rogue hits with the weapon, there is a 50% (60% with [[Improved Poisons]]) chance of the victim being poisoned for 10 seconds. The poison will increase the amount of time it takes for the victim to cast spells.\r\n==Source==\r\n'''Mind-numbing Poison''' is sold by poison vendors.\r\n==Notes==\r\nMind-numbing poison doesn't work on most bosses, but notable exceptions are as follows;\r\n*[[Pathaleon the Calculator]] ([[Mechanar]])\r\n*[[Reliquary of Souls]] ([[Black Temple]])",},
			["Mindfang"] = { content = "'''Mindfang''' is dagger which can be bought by [[Horde]] players. Mindfang is geared more towards casters like [[Warlocks]] and less towards melee characters like [[Rogues]].\r\n==Source==\r\nMindfang is sold by [[Rutherford Twing|Rutherford Twing <Defilers Supply Officer>]] in the [[Arathi Highlands]].",},
			["Mindless Zombie"] = { content = "'''Mindless Zombies''' are very weak [[undead]] monsters in the [[Forsaken]] starting area, north of [[Deathknell]]. Along with [[Wretched Zombie]]s, they are main inhabitants of the deserted northern half of Deathknell. [[Shadow Priest Sarvis]] sends newly recruited Foresaken to cull their numbers.\r\n==Attacks and abilities==\r\n*'''[[Melee|Basic Melee]]''': 1-2 Damage (before subtracting armor)\r\n==Quests==\r\n* The Mindless Ones - from [[Shadow Priest Sarvis]] in the church in [[Deathknell]]\r\n:Objective: Kill 8 '''Mindless Zombies''' and 8 [[Wretched Zombie]]s.",},
			["Mind Blast"] = { content = "'''Mind Blast''' is [[School|Shadow]]-based [[Direct Damage|direct damage]] spell. It has a quick cast-time considering its high damage and mana costs, at the expense of having a relative long [[cooldown]]. \r\n==Notes==\r\nThe formula for Mind Blast is calculated based on the damage given in the table above. The value given on the tooltip includes up to 10% bonus damage from the Darkness talent, which is a bit wrong since talent effects is supposed to be included after bonus damage for damage spells. To convert between the tooltip-listed base damage and real base damage use the following formula. \r\n Real_base_damage = Listed_base_damage / (1 + Darkness_bonus)\r\nThe formula for calculating the damage from this spell is as follows:\r\n Damage_done = (Real_base_damage + (1.5/3.5) * Spelldamage * Downrank_factor) * (1 + Darkness_Bonus)\r\nA lvl 70 priest with 760 shadowdamage and full ranks in Darkness would end up with (max damage)\r\n Damage_done = (752 + (1.5/3.5) * 760 * 1.0) * ( 1 + 0.10 ) = 1185\r\n==Related talents==\r\n*[[Focused Mind (Priest)|Focused Mind]], reduces the mana cost of Mind Blast by 5/10/15%.\r\n*[[Improved Mind Blast]], reduces the cooldown of Mind Blast by 0.5 up to 2.5 seconds. \r\n*[[Shadow Power]], increases the critical strike chance of Mind Blast by 3 up to 15%.\r\n*[[Blackout]], gives your Shadow damage spells a 2/4/6/8/10% chance to stun the target for 3 seconds.\r\n*[[Darkness]], increases your Shadow spell damage by 2 up to 10%.\r\n*[[Force of Will (talent)|Force of Will]], increases your spell damage by 1/2/3/4/5% and the critical strike chance of your offensive spells by 1/2/3/4/5%.\r\n*[[Shadow Affinity]], reduces the threat generated by your Shadow spells by 8/16/25%. \r\n*[[Shadow Focus]], reduces your target's chance to resist your Shadow spells by 2 up to 10%.\r\n*[[Shadowform]], increases Shadow damage dealt by 15% and reduces physical damage taken by 15%.\r\n*[[Shadow Reach]], increases the range of your offensive Shadow spells by 10/20%.\r\n*[[Shadow Weaving]], debuffs the target, increasing all shadow damage by 2% per application.\r\n==Past changes==\r\n*Prior to [[Patch 2.0]], it caused 100% extra [[threat]], reducing its [[PvE]] viability.",},
			["Mind Control"] = { content = "'''Mind Control''' is a [[shadow]] [[spell]] that allows a unit to temporarily take control of an enemy target for up to one minute and use it to attack other enemies. \r\n==Talent Improvement==\r\n[[Shadow Affinity]] reduces [[threat]] generated. \r\n[[Shadow Focus]] reduces the target's chance to resist or break free.\r\n==Functionality==\r\nMind control serves as a unique form of [[crowd control]] in that not only is the target removed from the fight temporarily but the target's powers can be directed against other enemies. On a successful cast of Mind Control, the priest's viewpoint will shift to the controlled player or [[mob]] and the priest's movement keys will move this unit. The pet bar appears and allows the unit's special abilities to be used. Mind Control forms a general-purpose [[crowd control]] similar to [[sap]]ping and [[sheep]]ing; however, unlike most other forms of crowd control, the [[priest]] himself is essentially removed from battle for the duration of the spell and cannot cast any of his own heals or attacks until the Mind Control is broken. \r\nMind Control's full duration is one minute, but there are several factors which can cause it to break early. A break is checked vs '''mob's level / distance from controlling priest / resistances of target, every x seconds''', and the spell can break without warning even if the channelling bar is still mostly full. In addition, if the MCed unit is moved too far from the controlling priest the spell will automatically be disrupted. Attacks directed against the controller will shorten the duration of the spell but will have no effect on the the target's ability to break free of their own volition. [[Death]] (of the priest or the MCed target), [[silence]]s, and some other abilities will entirely disrupt the spell.\r\nCasting Mind Control generates a great deal of [[threat]] from the controlled mob against the priest who controlled it. To this date it is not clear precisely how much threat Mind Control causes, but it is very substantial – a priest who releases a mob for it to be killed in an instance is well advised to do nothing else to generate threat until [[aggro]] has been rock-solidly established by a [[tank]]ing character. Apparently, mobs don't like having their free will stripped away by someone they can kill in two hits.\r\n[[Elite]] mobs can generally be MCed, but not [[boss]]es. You can even MC other players, although you are limited to melee attacks while doing so. The signature usage of MC in PvP is to MC an enemy player atop a tower or other high place and then run that player off the edge, causing a large amount of falling damage (if not death).\r\nWhen learned, Mind Control actually lets a priest usurp the will of a player or mob higher the priest's level. It is not known if Rank 4 is harder to resist than Ranks 1 through 3, so it could be worth using the lower ranks to save mana if the target unit is within the priest's range. In general, however, MC is seldom used until endgame or PvP situations.\r\nThe WoW Priest forums have a stickied thread with a variety of uses for Mind Control, which can be found .\r\nSee also a [[List of mind controllable mobs]] for information on MC-able enemies as well as their locations and special abilities.\r\n==Tips, Hints and Info about Mind Control==\r\n# Mind control duration is partly controlled by distance. The farther your 'pet' is from you, the higher the chance of breaking. Park it on top of yourself if you wish to reduce its chances of resisting - unless you have other plans in mind for it, OR if the NPC you are fighting has some sort of stun/cc (Shield bash/gouge/polymorph etc).\r\n# Mind control a healer if it's available. Why spend your own mana and get possible aggro when you can easily mind control that medic and use its prayer of healing which heals for 2k+ AND uses only 400 mana over your own? Don't forget that the medic has 8k mana, meaning it can chain cast it for a while. And if it gets aggro and dies... just remember that it wasn't you. :P\r\n# Mobs within aggro range of an MCed target will regard it as hostile - they have no qualms over beating up a unit that was a trusted ally only moments before, so you can mind control something and let the surrounding 'linked' NPCs kill it. Note, however, that if the MCed target is freed from your control, they will once again regard it as a friend and will immediately seek another hostile target to attack - which may be you.\r\n#Mind controlled NPCs have their own aggro; spells cast by an NPC do not get 'added' to your current aggro, so in group situations you do not have to worry about enemies that you attacked with an MCed mob favouring you over your tank.\r\n#Mobs must take damage from players or player pets in order to generate loot; should they be killed solely by a Mind Controlled mob they will drop no items. In addition, a Mind Controlled mob will generate no loot if it dies while still MCed; it must be released if you wish to take its items.\r\n# [[Mind Soothe]] is VERY useful in getting close to humanoid NPCs without them jumping you due to the 20 yard range of mind control. If you want them to focus on pet and not on you first (Remember [[aggro|aggro rules]]) use Mind Soothe.\r\n# Effects that reduce an enemy's shadow resistance (such as the [[Warlock]]'s [[Curse of the Elements]] spell) can decrease a mob's ability to resist or break free of Mind Control.",},
			["Mind Flay"] = { content = "''\"Melting faces is what I do best...\"''\r\nMind Flay is a [[Channeling|channeled]] spell that can be acquired from the Shadow talent tree. It is the spell with the best damage/mana ratio for the priest, and it has the additional bonus to stop runners (the target is slowed by 50%).\r\n===Talents===\r\n*[[Blackout]], [[Darkness]], [[Force of Will (talent)|Force of Will]], [[Martyrdom]], [[Shadow Affinity]], [[Shadow Focus]], [[Shadow Reach]], [[Shadow Weaving]], [[Shadowform]], [[Vampiric Embrace]]\r\n===Notes===\r\n*Mind Flay used to receive a largely reduced amount of spell damage (59% of total +spell damage, divided over 3 sec.). Originally, Blizzard said this was due to its snare. Later they revised their statement, claiming that it would be too powerful. In patch 3.0.1, the amount of spell damage coefficient has been increased by approximately 30%.\r\n*Its debuff has no classification, hence it cannot be dispelled.\r\n*When attacking a Druid with Mind Flay, shapeshifting cancels it.\r\n*Mind Flay does additional threat. This is most likely due to its snare.\r\n*Since patch 3.0.1, Mind Flay can crit.",},
			["Mind Mastery"] = { content = "'''Mind Mastery''' is a [[mage]] talent that increases [[spell damage]] by a percentage of the mage's intellect - 5% per rank up to 25% at max rank. This talent includes intellect from gear, buffs and other talents, such as [[Arcane Mind]]. For most high level mages, the amount of spell damage gained from this talent is significant.",},
			["Mind Numbing Poison"] = { content = "#REDIRECT [[Mind-Numbing Poison]]", redirect = "Mind-Numbing Poison",},
			["Mind Soothe"] = { content = "Mind Soothe reduces the [[aggro]] radius of a target mob, which means you can tactically avoid pulling certain enemies. This is very useful to skip certain pulls, or to run through certain areas without drawing enemies, and thus comparable to a targeted version of [[stealth]] in some situations. Beware that if the mob resists Mind Soothe you will aggro it and enter combat. Using Mind Soothe on players of the enemy faction is an aggressive action and will cause guards of neutral cities to aggro. \r\n==Functionality==\r\nMind Soothe only works on humanoids. If it is resisted, it will [[aggro]] the target. \r\n==About Aggro==\r\n*The aggro radius of a mob with the same level as a player is about 20 yards, so if using Mind Soothe against the same level mob as the player, you will gain an extra 10 yards to move with.\r\n*Beware of casting it on higher level mobs, as they are more likely to resist, which puts you into combat.\r\n----",},
			["Mind Vision"] = { content = "'''Mind Vision''' is a [[Channeling|channeled]] utility spell. It allows to see through the target's eyes.\r\n==Tips and Tactics==\r\n*Mind Vision can be enormously powerful in [[Warsong Gulch]], as the flag carrier can easily be targeted via ''/target <name>'' and then function as the target for the spell.\r\n*When defending a node [[Arathi Basin]] you can Mind Vision an incoming rogue or druid before they stealth, then pop them out with SWP once they come into range.\r\n*It can be used to annoy other people, as it cannot be dispelled.\r\n*As a consequence of this skill remaining 'glitched' (insta-cast spells work on your target while channeling Mind Vision) it is possible to chain-cast Mind Vision between multiple mobs/players. Useful for maintaining the watch on the flag in Warsong Gulch, or third-person scouting in raid encounters.\r\n*Combined with the Warlock's [[Eye of Kilrogg]] or the Hunter's [[Eyes of the Beast]], this can prove useful for allowing multiple players to scout the same region.\r\n*Using /target to target a known PvP player nearby, then use mind vision to determine exactly where they are.\r\n*When trying to find a certain mob character for a quest, use /target to target them and then mind vision to locate them. When you leave mind vision a small dot appears on your mini-map for a second showing you where he/she is.\r\n==Notes==\r\n*Rank 1 has a line of sight requirement when cast, Rank 2 does not.\r\n*Mind Vision cannot be dispelled, neither by friends nor by enemies.\r\n*Can be \"chain\" casted from target to target to potentially scout instances for rare mobs/patrols.\r\n*A mind-visioned rogue or druid who stealths can still be seen, and even hit with an instant cast spell. Any normally cast spell will interrupt Mind Vision earlier than the new spell hits, causing a loss of the target. \r\n*If your target does not target anyone, this spell causes them to automatically target you.\r\n*It is not affected by [[spell haste]].",},
			["Mine"] = { content = "In [[World of Warcraft]], '''mine''' can mean one of several things:\r\n#Performing an action to gather from a [[Resource|resource]] node with the [[Mining]] [[Profession|profession]].\r\n#A location such as a cave or underground area, which may include vein or deposit nodes that characters with the [[Mining]] profession can use to [[Gather|gather]] [[Gem|gems]], [[Ore|ore]], [[Stone|stone]], and [[Mote|motes]].\r\n#A mineral node, such as a [[Vein|vein]] or [[Deposit|deposit]].\r\n#[[Gold Mine (Arathi Basin)]], a resource node in [[Arathi Basin]].",},
			["Mineable Mobs"] = { content = "#REDIRECT [[Mob mining]]", redirect = "Mob mining",},
			["Miner"] = { content = "#redirect [[Mining]]", redirect = "Mining",},
			["Miners"] = { content = "#redirect [[Mining]]", redirect = "Mining",},
			["Mine Spider"] = { content = "'''Mine Spider''' can be found in [[Elwynn Forest]] .\r\n'''Mine Spider''' can be tamed by a [[hunter]]. \r\n==Drops == \r\n \r\n0.51% Chance of an [[Uncommon]] drop.\r\n1.33% Chance of a [[common]] drop.\r\n0.03% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Mini-boss"] = { content = "'''Mini-Bosses''' (or sub-bosses) are tough [[mob]]s that are usually only found in [[instance]]s on the way to an instance [[Boss]] or guarding them; most sub-areas in an instance will usually have an intermediate encounter with a \"Mini-Boss\". Mini-Bosses can be tougher than an [[elite]] with the same level, but may often be equivalent to the same level elite mob. Some Mini-Boss mobs are also immune to [[Crowd Control]] and may have other select immunities as well.\r\nSome [[quest]]s chains end with needing to kill what amounts to a Mini-Boss, but might also be considered a Boss, so the distinction is fuzzy.\r\nExamples of minibosses include [[Gatewatcher Gyro-Kill]] and [[Gatewatcher Iron-Hand]] in [[Mechanar]].\r\nAlso see:\r\n* [[Boss]]",},
			["Mini-Diablo"] = { content = "#REDIRECT [[Diablo Stone]]", redirect = "Diablo Stone",},
			["Mini-map"] = { content = "#REDIRECT [[Minimap]]", redirect = "Minimap",},
			["Minimap"] = { content = "The '''minimap''' is a circular, zoom-able overhead view of the area around your character (represented as silver arrow pointing the direction your character is facing).\r\nBesides being able to zoom the view in and out, the '''minimap''' has a variety of informational UI features.\r\n====Location name====\r\n* The name of the current location of your character appears at the top of the minimap.\r\n====Terrain and buildings====\r\n* A reasonable shadowed, textured view of the surrounding terrain appears in the minimap.\r\n* Rough silhouettes of buildings (mostly to scale) also appear on the minimap.\r\n====Character locations====\r\n* Your character (): Your character will appear as silver arrow pointing the direction your character is facing always at the center of the minimap.\r\n* Your [[corpse]] (): If you die, your corpse will appear and a small tombstone on the minimap and an arrow () on the edge of the minimap circle will point to it if it is out of view.\r\n* Your Graveyard: If you die, but don't press the \"Release Spirit\" button, there will be a golden arrow () pointing towards the nearest available Graveyard.\r\n* [[Party]] members: If your character is in a party, any party members will appear on the map as white-outlined, <font color=\"#6688FF\">light blue</font> blips ( ). Arrows () on the edge of the minimap circle will point to party members out of view.\r\n====Flight masters====\r\n[[Flight master]]s that you have not yet gotten the [[flight point]] for will display on the minimap as a <span style=\"color:#66ff66;\">light green</span> exclamation point ().\r\n====Detected [[Creature|creatures]] or [[Resource|resources]]====\r\nMoving the pointer over the blip will give the creatures name.\r\n* A small circular indicator at the top-left of the minimap shows the current detection method [[Ability|ability]] (like [[Hunter]]'s [[Track Beasts]], [[Herbalism]] [[Profession|profession]]'s [[Find Herbs]], or [[Mining]]'s [[Find Minerals]]). You can right-click on this indicator to change the kind of tracking that is active.\r\n* Any detectable creatures appear as gold-outlined <font color=\"red\">red</font> blips ( ; like with the Hunter ability, Track Beasts). \r\n* Detectable creatures would appear as <font color=\"gold\">gold</font> blips ( ). \r\n* Detectable creatures appear as gold-outlined <font color=\"#44FF44\">green</font> blips ( ).\r\n* Any detectable minerals appear as <span style=\"color:gold;\">gold</span> blips ( ; like with the Herbalism ability, Find Herbs or the Mining ability, Find Minerals). Moving the pointer over the blip will give the type of herb or mineral (usually a [[Vein|vein]] or [[Deposit|deposit]]). If the color of the blip is slightly dimmed ( ), it means that the resource is on a different level (underground if you are above ground and vice versa).\r\n====[[Quest giver]]s and [[quest ender|ender]]s====\r\n* [[Quest]] [[NPC]]s will show up on the minimap as <span style=\"color:gold;\">gold</span> exclamation marks (), or as a question mark () when you have a completed quest to turn in to them, and the tooltip will give the NPC name when you mouse over it. If the color of the indicator is slightly dimmed ( or ), it means that the questgiver is inside a building, or on another level. Repeatable quest giver NPCs show up as a <span style=\"color:#6688FF;\">blue</span> mark ( or ) instead of gold.\r\n====Guard Directions====\r\nWhen you talk to a [[guard]] and ask for directions, minimap features will help you find your target.\r\n* A golden guide arrow () will appear on the edge of the minimap pointing in the direction of your target.\r\n* A red marker flag () will appear on the minimap roughly where your target is located.\r\n====City/Town Directions====\r\nWhen your character is near a [[city]] or [[town]] a silver edge arrow () will appear on the edge of the minimap indicating the direction of the settlement.\r\n====Detecting other players====\r\nUsually only applies to [[Druids]] and [[Hunters]] with [[Track Humanoids]].\r\n* Any detectable players appear as white-outlined <font color=\"#44FF44\">green</font> blips ( ).\r\n* Enemy players, when you're not flagged appear as white-outlined <font color=\"gold\">gold</font> blips ( ).\r\n* Enemy players, when you are flagged appear as white-outlined <font color=\"red\">red</font> blips ( )\r\n====Pinging a location====\r\nIf you click on the minimap, you can [[ping]] a location that is visible to other members of your party.\r\n====Day/Night and time====\r\n* A small circular indicator at the top-right of the minimap shows a sun or crescent moon depending on whether it is day or night in game time.\r\n*: ''day'' ''night''\r\n* Moving the pointer over this indicator shows the current [[In-Game Time|in-game time]].\r\n====Mail status====\r\n* A smaller circular indicator () under the day/night indicator shows an envelope if your character has unread [[Mail|mail]].\r\n*: ''you have mail!''\r\n*Moving the pointer over the icon will let you know who sent the recent unopened mail.\r\n====Time clock====\r\n''This can be turned off through the interface display options.''\r\n* A small clock () at the bottom of the minimap shows the server time.\r\n* Moving the pointer over the clock will show you server time and local time.\r\n===Minimap UI===\r\nThe minimap only has zoom in and zoom out buttons at the bottom-right:\r\n* Click the <font color=\"gold\">gold '''+'''</font> button () to zoom in the minimap view. If the button is a <font color=\"gray\"> gray '''+'''</font> (), that means the view is zoomed in as much as possible.\r\n* Click the <font color=\"gold\">gold '''-'''</font> button () to zoom out the minimap view. If the button is a <font color=\"gray\"> gray '''-'''</font> (), that means the view is zoomed out as much as possible.",},
			["Mining"] = { content = "'''Mining''' allows you to find and mine [[mineral]]s, [[ore]]s, and [[stone]]s from [[resource]] nodes scattered throughout the world. It is one of the primary professions. Materials from mining and the items miners can create from them are reagents needed for recipes within other professions.\r\n[[The Burning Crusade]] expansion contains several mobs that are capable of being mined. See [[Ore skinning]] for a general definition, and [[Mineable Mobs]] for a list.\r\nMining pointers:\r\n ''in range of deposit/vein that can be mined''\r\n ''out of range of deposit/vein'' \r\nFor other articles related to '''Mining''', see the [[:Category:Mining|Mining category]].\r\n==Uses==\r\nThe main professions which need the raw materials from mining are [[Blacksmithing]], [[Engineering]] and [[Jewelcrafting]]; occasionally recipes from other professions may need mining materials too. Mining is one of the three collecting professions (the others being [[Herbalism]] and [[Skinning]]). Some argue that it creates the highest income of the three.\r\nCharacters trying to maximize their income should take two collecting professions at the start of their career, sell the products they find, and switch to crafting professions only after reaching the level cap and having a solid financial foundation. When miners try to sell the materials they find, they should pay attention to whether there is a price difference between the raw ore and the smelted bars. Frequently the ore is more valuable (because mining skill can be gained from smelting, and Jewelcrafters require ore for [[Prospecting]]).\r\nPlayers actually interested in crafting items usually combine mining with one of the three trading professions which mostly use mining products.\r\n==Tools and Abilities==\r\nA [[Mining Pick|mining pick]] is needed for mining and can typically be found for sale by the following types of [[NPC]]: trade goods, mining supplier, blacksmithing supplier, or engineering supplier. To perform mining, the pick must be in the player's inventory.\r\nAfter learning mining the \"[[Find Minerals]]\" ability becomes available in the General tab on the [[spellbook]]. Activating this ability will show all mineral nodes in the player's vicinity on the [[Mini-Map|mini-map]]. Find Minerals cannot be used at the same time as any other minimap \"find\" ability (like [[Find Herbs]] or Hunters [[tracking]]). To make collecting easier, two types of special mining [[bags]] can be [[Bag|created]] or bought, which have 20 or 28 slots respectively and will automatically store gathered ores.\r\nMiners are also able to learn [[smelting]]. This allows them to melt down ore and mould it into a [[bar]]. For this to work, the player must be in proximity of a [[forge]]. Melted bars are the end product of Mining/Smelting, and usually are the raw material used by the other professions. Smelting certain ore can also give you skill points.\r\nWorthy of note:\r\n* [[Enchant Gloves - Advanced Mining]] adds +5 to mining skill.\r\n* Goblin Mining Helmet adds +5 to mining skill.\r\n==Mining Skill and its Increase==\r\nDifferent veins will require different mining skill levels to loot (e.g. [[mithril]] veins require a skill of 175). The relative difficulty of the mining attempt is colour coded as usual:\r\nTo actually mine a [[resource node]] right click on it. After a short time, the mining attempt either fails (particularly while the nodes difficulty is still orange), or a loot box comes up, containing [[ore]], [[stone]] and sometimes rare drops like [[gem]]s or [[mote]]s. Normal nodes may usually be mined about 2-4 times, rich ones about 4-8 times.\r\nThe normal method to gain mining skill is to use it on nodes which are not grey. Each node can yield up to one point of skill increase per miner, thus if several players mine the same node, each can gain a skill point (it is actually possible to gain a skill point without even removing the ore, allowing a large party of miners to skill up on the same node). \r\nThe much quicker method to level mining is by smelting. Particularly at the start of a mining career, smelting [[Copper]] will yield an easy and quick increase in mining skill. Unfortunately, at higher levels, even brand new smelting [[recipe]]s will be green or even grey. [[Gold]] and [[silver]] however are an exception; unfortunately these ore types are quite rare.\r\n===Mining Etiquette===\r\nIf someone is already looting a resource node, it is polite to abstain from attempting to loot as well. Similarly, it is considered poor form to use a speed enhancing ability to grab a node before someone else does. Ask if you can take a whack for the skill up, but otherwise leave other miners alone. It is important to note that while it is considered impolite to take a node from another player, the game rules do not classify such behavior as harassment and therefore it is not punishable.\r\nIn a party, share your nodes with other miners so you can split the skill ups and ores. If somebody is fighting a mob near a mining vein, either help kill the mob, or wait until the person is done, to see if he was planning to mine the vein. If they are of the same faction (Horde/Alliance) you can simply ask them.\r\nProper etiquette can vary from server to server. You may wish to disregard etiquette for miners of the opposing faction on a PVP server, but as with all PVP encounters, it is up to you how to act. Doing so may result in you getting [[gank]]ed and camped, however, so you may wish to exercise caution.\r\nIf someone is trying to steal a node from you you can simply not loot the ore out of your window and stand there. They will be unable to mine the node. Most players will give up shortly; if they don't give up, mark yourself afk, they will usually leave after a few minutes.\r\n===By Skill Level===\r\nSee [[Mining proficiencies]] and [[Smelt]] proficiencies.\r\n===Quest Items===\r\n* Incendicite Ore (objective of Search for Incendicite\r\n* Lesser Bloodstone Ore (objective of Favor for Krazek)\r\n* Indurium Ore (objective of Indurium Ore)\r\n* Rethban Ore (objective of Rethban Ore)\r\nQuest ore is usually mined off special nodes, but can also drop off certain mobs in the same area. The ores cannot be smelted and are not \"quest items\" ''per se'', so they can be traded or purchased off the AH.\r\n==Tips==\r\n* has some great Google-Earth like ways of figuring out where to find good places to ride around and level up your mining skill if you're not doing it as you level (epic mount preferred by far here). It will not, however, tell you that if you're at about skill 175-ish, finding Mithril nodes becomes quite the pain. If you play rogue or druid and have the skills and gear to stealth around Uldaman and not die too much, there are quest nodes in there as well as tons of Mithril.\r\n* Gatherer is a great free-standing addon that will help you track where you find herbs or mining nodes - which will make leveling mining A LOT easier and faster with a mount.\r\n* Cartographer_Mining is another great addon that will do the same and a lot more (using modules that can be turned off easily), and uses the common Ace2 modding framework with Ace2's common libraries. Which of these mods uses more memory for you may depend on how you configure either of them. Both can be found at Curse Gaming.\r\n* Cartographer_Data is a great database of known mining nodes gathered from WoWHead to use with Cartographer_Mining.\r\n* Pro Tip: if you find a few (say minimum 3-4) nodes that are yellow or orange to you and you have decently fast transportation between them, DO NOT empty them one at a time. Get a skillup from one (which, if you do get it, will always happen on the first successful smack on that node), then immediately move to the next, and come back around after you've hit all three or four. The timing at which you can repeat getting a skillup from the same node is dependent on time elapsed to the best of my limited research, - not if you kill a mob in between, or if you hit up another node, or if you count to 74 backwards while jumping in a circle barefoot in a pentagram. Thus by the time you knock off the 4th node, you *should* be able to get a skillup from the first one again. Your mileage may vary, and any further research would be much appreciated, specifically the exact amount of time that needs to elapse between skillups from the same node. \r\n* Addendum to the comment above: It seems that skinning between every time you try to mine a node will perhaps reset the skillup timer thing. It was in this way possible to get 4 skillups from one single node by killing mobs and skinning them between each try. It would be interesting to see if this can be done indefinitely by not taking any ore, thus preserving the node.\r\n* Mining Node Spawns: to the best of limited research, nodes in a given zone seem to spawn in a few patterns. Thus you will frequently find that if you find a node in spot X and Y, and the next day find a node in spot Y, there's a better than average chance that X is also active (but you never know if another miner is around...). If neither is there, more than likely another 'set' of nodes is active. The length of time it takes for a node to respawn is not known at this time, outside of Blizzard HQ.\r\n==Mining Bugs==\r\nCurrently the most consistent mining bug is the double vein appearance. \r\n*Double vein appearance - Sometimes two veins will spawn in the same place, effectively doubling the amount of ore you can get. Furthermore, the minimap symbol acknowledges the location of both veins on the exact same spot. This is considered a beneficial bug.\r\n*The minimap might show that a vein exists, but the wall of the mine falls between the player and the location of the mine. This can be especially annoying with underground mines, sometimes players discover after wading through a lot of mobs that the node actually cannot be looted. (Though most of the time it's merely that the vein is on another floor of the mine. such as the Kobold mine south of Goldshire).\r\n*The minimap does ''not'' always show all nodes. This mostly happens underground as well. A few common examples are in [[BRD]]: the [[Dark Iron]] nodes do not always show up on the minimap.\r\n*Sometimes a node will appear on the minimap, but the harvestable volume a node will not be exposed so it can be clicked. Seen at the entrance of Zzarc' Vul cave in [[Duskwood]] and in the hills above [[Dustbelch Grotto]] in southwestern [[Badlands]].\r\n*Occasionally, and perhaps most noticeably in Blade's Edge plateaus, a vein will spawn in mid-air, appearing as a ball of rock floating one or two feet above ground.",},
			["Mining (enchant)"] = { content = "Permanently enchant gloves to grant +2 [[mining]] skill.\r\n==Source==\r\nTaught by Formula: Enchant Gloves - Mining.",},
			["Mining Pick"] = { content = "The '''Mining Pick''' must be in the inventory of characters who wish to [[mining|mine]] [[ore]].\r\n==Source==\r\nMining Pick can be bought off of any ''Trades Good Vendor'' or ''Mining Supplier.''\r\n==Notes==\r\nIt does not require a weapon proficiency to use as a weapon and does not count as a melee weapon for the purposes of skills that require one - such as [[Sinister Strike]], or [[Heroic Strike]].",},
			["Mining recipes"] = { content = "Mining recipes, otherwise known as smelting recipes, allow miners to convert ore into much more useful bars.\r\n</noinclude>\r\n</noinclude>",},
			["Mining trainer"] = { content = "#REDIRECT [[Mining trainers]]", redirect = "Mining trainers",},
			["Minion's Scourgestone"] = { content = "'''Minion's Scourgestones''' are small talismans that are taken from the mindless [[Scourge]]. The [[Argent Dawn]] will accept the [[Scourgestone]]s as proof of your willingness to fight the Scourge.\r\n==Source==\r\nThis item drops from the weaker Scourge in the [[Western Plaguelands]], the [[Eastern Plaguelands]], [[Scholomance]] and [[Stratholme]]. You must have the [[Argent Dawn Commission]], the [[Seal of the Dawn]], or the [[Rune of the Dawn]] equipped to pick up the Scourgestones.\r\n==Minion's Scourgestones as a Quest Objective==\r\n*Minion's Scourgestones\r\n*Dispelling Evil\r\n*Prove Your Hatred",},
			["Minion's Scourgestones"] = { content = "==Prerequisites==\r\nNone\r\n==Objectives==\r\nTurn in 20 Minion's Scourgestones.\r\nItems Needed:\r\n*20 x [[Minion's Scourgestone]]\r\n==Quest Text==\r\nA Minion's Scourgestone is the insignia of the Scourge rank and file. These are sometimes found on the weaker of their troops positioned in the Plaguelands, though the term \"weaker\" is certainly to be considered in context. The Scourge, no matter where they are, should never be underestimated. \r\nThe Argent Dawn currently offers a valor token in exchange for twenty of these insignia - an exchange I'm happy to do, provided you have earned enough scourgestones!\r\n==Reward==\r\n*[[Argent Dawn Valor Token]]\r\n==Additional Notes==\r\n*Many people decide to save their scourgestones and not turn them in until they are honored with the Argent Dawn. When you become honored, you no longer gain reputation killing non-elite Scourge.",},
			["Minion of Omen"] = { content = "'''Minions of Omen''' are [[wolf|wolves]] that appear during the [[Lunar Festival]] in [[Moonglade]]. They serve the evil [[demigod]] [[Omen]].",},
			["Mini Diablo"] = { content = "#REDIRECT [[Diablo Stone]]", redirect = "Diablo Stone",},
			["Mini map"] = { content = "#REDIRECT [[Minimap]]", redirect = "Minimap",},
			["Minor Beastslayer"] = { content = "The enchant permanently enchant a [[melee]] weapon to do 2 additional points of damage to [[beast]]s. Despite the low attack power upgrade, this enchant remains popular because it is the cheapest enchant that provides a weapon glow.\r\n==Source==\r\nFormula: Enchant Weapon - Minor Beastslayer is a [[world drop]] from mobs as low as [[level]] 11 and as high as level 26, though it is most common between level 15 and 20.",},
			["Minor Darkmoon Prize"] = { content = "==See also==\r\n* [[Darkmoon Faire]]\r\n==Notes==\r\nThe Minor Darkmoon Prize contains a level 15-25 item. It is often Uncommon, but it could be common, or it could be Rare. Some examples:\r\n* Rough Blasting Powder\r\n* Citrine\r\n* Huge Brown Sack\r\n* Oak Mallet\r\n* Scouting Gloves\r\n* Rakzur Club",},
			["Minor glyph"] = { content = "#REDIRECT [[Glyph]]", redirect = "Glyph",},
			["Minor Healing Potion"] = { content = "'''Minor Healing Potion''' is a [[potion]] that restores 70 to 90 health.\r\n==Source==\r\nThis item can be looted from most level 5-20 [[Humanoid]] monsters, and from containers in the same areas.\r\n[[Rogue]]s can [[pickpocket]] this item from many level 3-11 [[Humanoid]] mobs.\r\nThis item can be caught while fishing in level 1-10 zones. \r\nThis item is a quest reward from the following quests:\r\n* Keeper of the Flame\r\n* The Escape\r\n* Burning Blade Medallion\r\n* Inoculation\r\nThis item is made by [[Alchemy|Alchemist]] with a skill level of 1. The [[recipe]] is included when learning [[Apprentice]] level [[Alchemy]] profession training.\r\n==Minor Healing Potion as an ingredient==\r\nThis item is used to make: \r\n* Lesser Healing Potion\r\n==Notes==\r\nThis potion shares the same 1 minute cooldown as all other healing and mana potions, provided the imbiber is out of combat.",},
			["Minor Inscription Research"] = { content = "'''Minor Inscription Research''' is taught by [[Inscription]] (75). When you do this, you will create some random scrolls that you can currently make, and you have a possibility to learn how to make a minor glyph in the process. You can use this once every 20 hours.",},
			["Minor Mana Oil"] = { content = "'''Minor Mana Oil''' can be applied to a wielded weapon, then it restores 4 mana to the caster every 5 seconds, for 1 hour.\r\n==Source==\r\nThis item can be crafted using [[Enchanting]] (150); taught by Formula: Minor Mana Oil. \r\n==Notes==\r\nThis item does not stack at all. Use up your most depleted one first to minimize the inventory space consumed.",},
			["Minor Manifestation of Fire"] = { content = "The '''Minor Manifestation of Fire''' is a level 12 [[fire elemental]] found in [[Durotar]].\r\nThe Minor Manifestation of Fire is part of the quest-line a [[shaman]] undertakes to receive the [[Fire Totem]].\r\n==Quests==\r\n*Call of Fire (4)\r\n==Loot==\r\n*Glowing Ember ''(Quest Item)''",},
			["Minor Speed"] = { content = "Permanently enchant boots to give a slight (8%) movement speed increase.\r\n==Reagents==\r\n*1x Small Radiant Shard\r\n*1x Aquamarine\r\n*1x Lesser Nether Essence\r\nRequires: Runed Truesilver Rod\r\n==Source==\r\nTaught by:\r\n* [[Annora]] in [[Uldaman]].\r\n* [[Enchanter Aeldron]] in [[Shattrath City]].\r\n* [[Enchantress Volali]] in [[Shattrath City]].\r\n* [[Hgarth]] in [[Stonetalon Mountains]].\r\n* [[Kitta Firewind]] in [[Elwynn Forest]].",},
			["Minor Wizard Oil"] = { content = "'''Minor Wizard Oil''' can be applied to a wielded weapon, then it increases spell damage by up to 8, for 1 hour.\r\n==Source==\r\nThis item can be crafted using [[Enchanting]] (45); taught by Formula: Minor Wizard Oil. \r\n==Notes==\r\nThis item does not stack at all. Use up your most depleted one first to minimize the inventory space consumed.",},
			["Minshina's Skull"] = { content = "'''Minshina's Skull''' is contained in [[Imprisoned Darkspear]] on the [[Echo Isles]] in [[Durotar|Durotar]].\r\n==As a quest objective==\r\nIt needs to be obtained for [[Master Gadrin]] in [[Minshina's Skull (quest)]].",},
			["Miracle"] = { content = "A '''miracle''' requests a deity’s intercession. One doesn't so much cast a miracle as request one. A person states what he would like to have happen and requests that his [[Eternal]] (or the power he prays to for spells) intercede. A miracle can do any of the following things.\r\n* Duplicate any healer spell (including spells to which the person has access because of his domains).\r\n* Duplicate any other spell, including arcane spells.\r\n* Undo the harmful effects of certain spells, such as geas/quest or insanity.\r\nAlternatively, a healer can make a very powerful request. Casting such a miracle costs the healer because of the powerful divine energies involved. Examples of especially powerful miracles of this sort include the following.\r\n* Swinging the tide of a battle in his favor by raising fallen allies to continue fighting.\r\n* Moving his allies, with all his and their gear, from one plane to another through planar barriers to a specific locale with no chance of error.\r\n* Protecting a city from an earthquake, volcanic eruption, flood or other major natural disaster.\r\n* Restoring a Forsaken back to mortal life. It can return them to being living humans or high elves.\r\n* A miracle spell can restore a reincarnated character to his or her original form.\r\nIn any event, a request that is out of line with the Eternal’s or faith’s (or alignment’s) nature is refused.",},
			["Mirador"] = { content = "'''Mirador''' is a level 50 [[horse]] found at [[Tirion Fordring]]'s cottage on the shores of the [[Thondroril River]] near the south entrance to [[Terrorweb Tunnel]] in the [[Eastern Plaguelands]].",},
			["Mirage Raceway"] = { content = "The '''Mirage Raceway''' is a race track, deep within the dry lake bed known as the Shimmering Flats. After the end of the [[Third War]], both the [[goblin]]s and the [[gnome]]s decided that the large alkali desert known as the [[Shimmering Flats]] near [[Thousand Needles]] would be a perfect place to test their new rocket designs. The natural animosity between the two engineering teams created the perfect opportunity for races to see once and for all whether [[Goblin Engineering]] or [[Gnome Engineering]] was superior.\r\nGoblin and gnome tinkers labor constantly to perfect the ultimate racing machines. At regular intervals, they participate in trials of their creations, and twice monthly the Mirage Raceway hosts a series of events to determine which side is the best. While no prizes are officially awarded, being \"the best\" is usually enough. Besides, there’s plenty of betting going on behind the scenes to make a shrewd gambler a tidy fortune — or break the bank if he chooses poorly.\r\nAt the start of each month, the [[Mirage Raceway Independent Oversight Committee]] (MRIOC) announces the parameters for the next race (length, vehicle class, special rules, and so on). The first race is considered the \"preliminaries,\" while the final race of the month determines the overall winner. The side that achieves victory then lords it over the losers for the next month.\r\nThe Goblin team's pilot is named [[Nazz Steamboil]].\r\nSince then, the Mirage Raceway has become a unique draw for both the [[Horde]] and the [[Alliance]], as supporters come to cheer on their respective favorites. Races between the Gnome and Goblin drag cars take place daily, as both teams scramble to come up with improvements that will give their side an edge. The track has also drawn a number of seedy types, attracted to the prospect of gambling on the winner.\r\nIn the RPG and early WoW, a [[Gnomish mech]] raced for the Gnomish team, [[Brivelthwerp]] sells Ice Cream on the track.",},
			["Mirdoran the Fallen"] = { content = "'''Mirdoran the Fallen''' is one of the four undead lieutenants of [[Dar'Khan Drathir]], the master of [[Deatholme]]. Mirdoran is a skeleton who resides in a gazebo just to the left of the main gate.\r\n==Quests==\r\n* Dar'Khan's Lieutenants - from Magister Idonis at the [[Sanctum of the Sun]] in [[Ghostlands]]\r\n:Objective: \r\n::*Kill [[Borgoth the Bloodletter]]\r\n::*Kill [[Jurion the Deceiver]]\r\n::*Kill [[Masophet the Black]]\r\n::*Kill '''Mirdoran the Fallen'''",},
			["Mire Lord"] = { content = "The '''Mire Lord''' is a level 42 [[bog beast]] found in the [[Misty Valley]] in the [[Swamp of Sorrows]].\r\n[[Apothecary Faustin]] wants the Mire Lord's enchanted fungus.\r\n==Quests==\r\n*Nothing But The Truth\r\n==Loot==\r\n*Mire Lord Fungus ''(Quest Item)''",},
			["Mirkfallon Lake"] = { content = "'''Mirkfallon Lake''', high in the Stonetalon range , was once home to the tallest waterfall in Kalimdor. Aside from the breathtaking falls, one could also find the legendary hippogryphs, which migrate here from the cooler north. It is host to a wide variety of creatures, including wyverns, slimes, and thunder lizards. The spiders of Stonetalon also lay their egg clusters here.\r\n==Fishing==\r\nGeneration of fish nodes is quite frequent, example school of sagefish and pile of junk. Possible catch includes watertight trunk, raw sagefish and the usual common fish. Watertight trunk may contain large healing potion, medium leather and [[Weather-Beaten Journal]].",},
			["Mirror Lake"] = { content = "'''Mirror Lake''' is situated in western [[Elwynn Forest]], near an [[Mirror Lake Orchard|orchard]]. It is rather small, but nonetheless features a pretty waterfall. The lake always shines brightly in the afternoon sun, which explains the origin of its name. \r\nAlthough Mirror Lake would usually be an ideal spot for [[swimming]] or [[fishing]], the [[Defias]] bandits that infest the area make such sports hazardous.",},
			["Mirror Lake Orchard"] = { content = "'''Mirror Lake Orchard''' is situated in western [[Elwynn Forest]], on the southern banks of [[Mirror Lake]]. Although the trees growing here used to produce fresh fruit, they have all been picked and eaten by [[Defias]] bandits who have taken possession of the orchard as well as the nearby cottage. Whoever lived here is long gone, another victim of the growing banditry in the region.",},
			["Misdirection"] = { content = "Redirects threat caused by the hunter onto a friendly target for the next three shots. \r\n==Functionality==\r\n'' Threat caused by your next 3 attacks is redirected to the target raid member. Caster and target can only be affected by one Misdirection spell at a time. Effect lasts 30 sec. ''\r\n===Use===\r\n*9% of [[Base Mana]]\r\n*Cast time: Instant\r\n*Duration: 30 seconds\r\n===Limitations===\r\n*Requires level 70\r\n*Hunter must be within 100 yards range of the target raid member and in line of sight.\r\n*[[Cooldown]]: 2 minutes\r\n*Requires [[ranged weapon]] equipped\r\n===Tips===\r\n*This is a great skill in instance/raid. All raiding hunters '''MUST''' know how to use it.\r\n**It allows the hunter to [[pull]] for the tank in some difficult pulls.\r\n**It adds threat to the tank at the pull, as well as during the mid of long boss fights if used repeatedly.\r\n*Usually the autoshot timer will start after applying your first special shot, thus only giving you two specified shots (i.e. Cast misdirection, fire an [[Arcane Shot]], autoshot is triggered, then follow up with a [[Distracting Shot]] or [[Multishot]]).\r\n**Hint: start with an [[Aimed shot]] (half of the time you'd be pulling anyway). Due to the new behavior of Aimed shot, you will have time before auto-shot fires off. Hit a [[Distracting Shot]] or an [[Arcane Shot]], jump to interrupt (or instead, cancel Auto-shot), and restart an aimed shot. Decent crit% will allow roughly 4~5k damage dealt. \r\n*[[Multishot]] is sometimes considered as a single shot (see below). Thus the three hits from one multishot will transfer over to the friendly target. This can be handy in pulls of 2 or more mobs.\r\n*If you use misdirection to pull groups that are linked to others, all [[mobs]] will go onto the target of misdirection.\r\n*Also great on AoE pulls to be used with [[Explosive Trap]], solidly anchoring your trap aggro onto the [[main tank]].\r\n*Works with [[Volley]] as well, counting as one shot fired. Easier than explosive trap since you don't have to get close to them to fire it. Follow with a multishot and probably an autoshot will use the last point.\r\n===Mechanics===\r\nThese are some observations regarding how Misdirection works. For example, multi-shot does not count as \"one shot\" as such. Moreover, the mechanisms seem to be:\r\n*Shots that were Immune to the mob do not count as one of your 3 misdirects, seen in [[Karazhan]].\r\n*When misdirection is active, ALL attacks that happen on a tick during which ANY attack happens, is Misdirected.\r\n*On next tick, the buff counter is reduced with the number of attacks that happened.\r\nWhat this means:\r\n*You can misdirect more than three targets with [[Explosive Trap]] (Tested in Steam Vault with the yellow slave groups of four - all were misdirected, counter just went to zero).\r\n*Note that only the initial explosion damage is misdirected; The damage on next tick counts against the hunter again.\r\n*If you want \"optimal\" misdirectioning with multiple targets, save Multishot for last (eg. [[Aimed shot]] => [[Distracting Shot]] => [[Multishot]]). The first two shots reduce counter by one, and Multishot takes it to zero even though it's hitting multiple targets.\r\n*If, against three or more targets, you use multishot first, Misdirection counts to zero after that first Multishot since three attacks occured.\r\n----\r\nGo to [[Templates]]\r\nGo to [[Classes]]",},
			["Misha"] = { content = "'''Misha''' is a level 72 [[elite]] [[named]] [[bear]] that accompanied [[Rexxar]] through the [[Stonetalon Mountains]], [[Desolace]], and [[Feralas]]. In ''[[The Burning Crusade]]'', Rexxar and Misha can be found in the [[Thunderlord Stronghold]] in the [[Blade's Edge Mountains]], an area in [[Outland]].\r\n==Lore==\r\nRexxar's trusted companion, Misha, is a magical bear who will fight at Rexxar's side whenever he is called upon. Misha battles ferociously, and loyally follows Rexxar to every location he travels to. Rexxar is very protective of Misha when they enter civilized areas, and ensures that the bear stays close to him.\r\n==Attacks==\r\n*Hits for 902-1,198 Damage\r\n==Name==\r\n\"Misha\" is a common Russian name (full version is \"Mikhail\", anglicized to \"Michael\") which usually was given to bear characters in fairy tales, perhaps because of it's similarity to \"medved\" which means \"bear\" in the Russian language. Misha was also the name of the bear mascot of the 1980 Moscow Olympic Games.",},
			["Misha Tor'kren"] = { content = "'''Misha Tor'kren''' is a level 5 [[quest giver]] located in a farm just southeast of [[Thunder Ridge]] in the [[orcish]] starting zone of [[Durotar]] .\r\nShe starts the quest Lost But Not Forgotten.\r\nSee [[List of Durotar NPCs]].",},
			["Mishiki"] = { content = "'''Mishiki''' is a level 14 [[herbalism trainer]] located in [[Sen'jin Village]] in the [[orcish]] starting zone of [[Durotar]].\r\nSee [[List of Durotar NPCs]].",},
			["Mishta"] = { content = "'''Mishta''' is a level 58 trade goods [[vendor]] located at [[Cenarion Hold]] in the [[contested]] territory of [[Silithus]].\r\nSee [[List of Silithus NPCs]].",},
			["Miss"] = { content = "A miss is a failed attack; it deals no damage and will not proc any mechanic that may have resulted from a successful attack.\r\n==Base Miss Rate==\r\nThe Base Miss Rate for White Attacks is calculated using the difference between the attacker’s [[Attack Rating]] and the defender’s [[Defense]]. It is 5% if the Attack Rating is equal to the Defense Skill. If a player is Dual Wielding, they inherit an additional 19% miss chance. This applies to mobs, as well. Prince Malchezzar crushes so often in Phase 2 because the additional miss chance pushes non-crushing attacks much further off of his attack table.\r\nThe Base Miss Rate for Yellow Attacks is at a maximum 5%, not including any debuffs. The Dual Wield Penalty does not affect the miss rate for yellow attacks.\r\n===Player/Mob vs Player===\r\nWhen a player or mob attacks a player, the base miss rate is 5%.\r\nFor each point of the defender's defense skill over the attacker's attack rating, the base miss rate increases by 0.04%.\r\nFor each point of the attacker's attack rating over the defender's defense skill, the base miss rate decreases by 0.02%.\r\n===Player vs Mob===\r\nIn PvE, a player's chance to miss is determined solely by the difference between the defending mob's Defense Skill and the player's Weapon Skill. There are actually two formulas to determine miss chance against a mob:\r\nIf the difference between the mob's Defense Skill and your Weapon Skill is less than or equal to 10 then the formula for calculating your base miss rate against that mob is: \r\n<pre>5% + (Defense Skill - Weapon Skill)*.1%</pre>\r\n''If dual-wielding, substitute 24% for 5% in this formula''\r\nIf the difference between the mob's Defense Skill and your Weapon Skill is greater than 10, then the formula for calculating your base miss rate against that mob is: \r\n<pre>7% + (Defense Skill - Weapon Skill - 10)*.4%</pre>\r\n''If dual-wielding, substitute 26% for 7% in this formula''\r\nThese data show that a level 70 character with maximum base Weapon Skill (350) will need a Hit Rating of 142 (9.00%) to theoretically never miss a Level 73 boss (or skull mob). It is possible to completely negate melee and ranged melee miss. There is, however, a hard floor of 1% spell miss.\r\n''Level is not a factor except when attacking a mob level 9 or lower.''\r\n''Miss chance against a low-level mob is a percentage of normal equal to the mob’s level divided by 10.''\r\n'''Calculating a mob's Defense Skill or Attack Rating'''\r\nThis is a rather simple formula. It is the Mob's level multiplied by 5.\r\nFor Skull Bosses, the formula is your level plus 3, multiplied by 5.\r\n==See also==\r\n*[[Combat]]\r\n*[[Combat rating system]]",},
			["Missile Barrage"] = { content = "Missile Barrage is a Mage talent in the Arcane tree.",},
			["Miss Danna"] = { content = "'''Miss Danna''' <School Mistress> is a level 25 [[human]] school teacher who roams the city of [[Stormwind]] with a gaggle of [[children]].\r\nSee [[List of Stormwind NPCs]].",},
			["Mist's Edge"] = { content = "'''Mist's Edge''' is by far the longest stretch of coast in [[Darkshore]], reaching all the way from [[Auberdine]] in the south to the region's northern tip. It is dominated by gloomy bays and gray beaches, often littered with huge carcasses of sea animals — which are part of some quests — and dotted with the wrecks of sunken ships. [[Murloc]]s are an ever-present threat, but even more common are the [[crab]]s which scuttle along the entire stretch of shore.",},
			["Mist"] = { content = "'''Mist''' is a level 10 [[quest giver]] located in the northwestern corner of the [[Oracle Glade]] in the [[night elf]] starting zone, [[Teldrassil]].\r\nShe starts the quest Mist.\r\nSee [[List of Teldrassil NPCs]].",},
			["Mistell"] = { content = "Sending a [[chat]] message ([[tell]]) to the wrong person or group. Often shortened to the [[acronym]] MT.",},
			["Mistmantle Family Ring"] = { content = "==Source==\r\nThis item drops from [[Stalvan Mistmantle]] in [[Duskwood]].\r\n==Mistmantle Family Ring as a quest objective==\r\nThis item is an objective of The Legend of Stalvan.",},
			["Mistress Nagmara"] = { content = "'''Mistress Nagmara''' is a level 54 [[elite]] [[succubus]] found in [[Blackrock Depths]].\r\nNagmara works as a barmaid at the [[Grim Guzzler]] and is in love with Private Rocknot, one of the patrons.\r\nShe starts and ends the quest The Love Potion.\r\nSee [[Blackrock Depths NPCs]].\r\nPlayers who have completed her quest can suggest that she and Rocknot go out the backdoor of the bar for some privacy. This is the most pacifist means of getting the door opened.",},
			["Mistress Natalia Mar'alith"] = { content = "#REDIRECT [[Natalia Mar'alith]]", redirect = "Natalia Mar'alith",},
			["Mistress of Torment"] = { content = "The '''Mistress of Torment''' was a malevolent demon who took pleasure in nothing but agony and sorrow. She was the greatest of the [[sayaad]] who found their way to [[Outland]]. Showing on many occasions her diabolical zeal and appetite for slaughter and mayhem, she quickly became one of [[Magtheridon]]'s greatest generals. The many torture devices and Cages of Discipline found in her sanctuary are but the tip of the iceberg when it comes to her evilness.\r\nWhen Illidan and his allies came to Outland and laid [[Lord of Outland|siege]] to the [[Black Temple]], the Mistress of Torment was called to guard one of the two Shadowkeys needed to unlock the inner sanctum. [[Vashj]] and her [[naga]] infiltrated the aqueducts and attacked the Black Citadel from a side entrance, as [[Akama]] and his [[draenei]] destroyed the automated defenses. [[Vashj]] was responsible for killing the Mistress of Torment with aid from only a few myrmidons and snap dragons for support. The Mistress of Torment was killed, and the doors were opened.\r\n==Statistics of <font color=mediumorchid>'''Mistress of Torment'''</font> in Warcraft III==\r\n* 3400 HP <font color=limegreen> (+113% more than a regular Queen of Suffering)</font>\r\n* 1000 MP <font color=limegreen>(+100% more than a regular Queen of Suffering)</font>\r\n* 69-77 chaos melee damage <font color=slategray>(same as a regular Queen of Suffering)</font>\r\n* 8 heavy armor <font color=limegreen>(+700% more than a regular Queen of Suffering)</font>\r\n* Abilities\r\n** Banish (makes target ethereal)\r\n** Bloodlust (+X damage buff)\r\n** Bash (sometimes attacks stun target)\r\n** Black Arrow (+X damage and if attacks kill target, they create a Dark Minion)\r\n** Curse (causes attacks to miss buff)\r\nNote:''The Mistress of Torment's statistics are being compared to the most powerful non-unique type of Succubus and not the weakest type of Sayaad which is called a \"Succubus\".''",},
			["Mistrunner"] = { content = "The '''Mistrunners''' are a tribe of druidic tauren. They seek to heal the earth and ease the suffering of the[[ Earthmother]].\r\n==Known Mistrunners==\r\n*[[Aska Mistrunner]] <Cooking Trainer>\r\n*[[Fyr Mistrunner]] <Bread Vendor>\r\n*[[Gart Mistrunner]] <Druid Trainer>\r\n*[[Kaga Mistrunner]] <Meat Vendor>\r\n*[[Kah Mistrunner]] <Fishing Trainer>\r\n*[[Naal Mistrunner]] <Cooking Supplier>\r\n*[[Nan Mistrunner]] <Fruit Vendor>\r\n*[[Pawe Mistrunner]]\r\n*[[Sewa Mistrunner]] <Fishing Supplier>\r\n*[[Shadi Mistrunner]] <Trade Goods Supplier>",},
			["Mists of Dawn"] = { content = "'''Mists of Dawn''' is a part of [[tauren mythology]]. It is recorded in-game on a wall hanging in the Archdruid's tent in [[Thunder Bluff]].",},
			["Mistvale Giblets"] = { content = "==Source==\r\nThis item drops from [[Elder Mistvale Gorilla]] in [[Stranglethorn Vale]].\r\n==Mistvale Giblets as a quest objective==\r\nThis item is an objective of Scaring Shaky.",},
			["Mistvale Valley"] = { content = "A valley in the southern part of Stranglethorn Vale inhabited by the great Mistvale [[gorilla]]s. Adventurers often come through, looking to find [[Mistvale Giblets]], [[Gorilla Fang]]s, or the very rare [[Aged Gorilla Sinew]].",},
			["Misty Pine Refuge"] = { content = "'''Misty Pine Refuge''' is an outpost building of [[the Argent Dawn]]. It is located in central [[Dun Morogh]], and currently houses only one agent of the organization - [[Father Gavin]], who has been assigned to maintain the base and do some research into the plague of undeath while the rest of the force fights the [[Scourge]] in the [[Plaguelands]].",},
			["Misty Reed Post"] = { content = "'''Misty Reed Post''' is a small [[Horde]] outpost between the [[Stagalbog]] and the southern [[Misty Reed Strand]]. There is no flight path from here, and it holds only a couple of [[quest giver]]s and guards.",},
			["Misty Reed Strand"] = { content = "The '''Misty Reed Strand''' is the gloomy coastline of the [[Swamp of Sorrows]]. There is little along the vast stretch of beach but driftwood, debris, and [[crocolisk]]s, [[crab]]s, and [[murloc]]s. Adventurers of the [[Alliance]] come here to collect driftwood and slay crabs, and the [[Horde]] have several missions to slay the various murlocs spread about the beach.",},
			["Misty Shore"] = { content = "'''Misty Shore''' is a stretch of waterline running from [[Dandred's Fold]] to [[Dalaran]] in the [[contested]] territory of [[Alterac Mountains]]. Aside from its rather large population of [[turtle]]s, the shore also houses a pair of [[Scarlet Crusade]]-affiliated humans, who zealously attack those who pass too close.\r\nIt is possible to view [[the Dawning Isles]] from the Misty Shore, with the eerie [[Fenris Keep]] in the distance.",},
			["Mist Veil"] = { content = "The '''''Mist Veil''''' is one of the two sunken [[boat|ships]] in [[Darkshore]] whose lockboxes are the objective of the quest Deep Ocean, Vast Sea. She was attacked and sunk by [[murloc]]s as she was approaching [[Auberdine]] after crossing the [[Great Sea]]. Some of her crew survived by swimming ashore, but her captain went down with her. She lies just north of ''[[Silver Dawning]]''.",},
			["Mithril"] = { content = "'''Mithril''' [[ore]] is found in mithril [[vein]]s and can be smelted into mithril [[bar]]s.\r\nMithril is a rare, silvery, glistening metal that is lighter than [[iron]] but just as hard. When worked like [[steel]], it becomes a wonderful material from which to create armor; it is occasionally used for other items as well. Most mithril armors are lighter than other metals. An item made from mithril weighs half as much as the same item made from other metals. In the case of weapons, this lighter weight does not change the weapon’s ease with which it can be wielded (whether it is light, one-handed or two-handed). Items not made primarily of metal are not meaningfully affected by being partially made of mithril.\r\n==Mithril Vein==\r\nMithril [[vein]]s require a skill of 175 to mine. They can also produce [[gem]]s and [[Solid Stone]]. \r\nKnown Precious Gems found with Mithril Veins\r\n* [[Aquamarine]]\r\n* [[Black Vitriol]]\r\n* [[Citrine]]\r\n* [[Solid Stone]]\r\n* [[Star Ruby]] \r\nMithril veins are most frequently mined in:\r\n* [[Azshara]]\r\n* [[Badlands]]\r\n* [[Desolace]]\r\n* [[The Hinterlands]]\r\n* [[Stranglethorn Vale]]\r\n* [[Searing Gorge]]\r\n* [[Tanaris]]\r\n* [[Arathi Highlands]]\r\n==See also==\r\n*[[Mithril Ore]]\r\n*[[Mithril Bar]]",},
			["Mithril Bar"] = { content = "'''Mithril Bars''' are smelted from [[Mithril Ore]], and are heavily used in [[Blacksmithing]], [[Engineering]], and [[Jewelcrafting]]. The [[Mithril Order]] was named after the mineral.\r\n==Source==\r\nMithril Bars can be created at a [[forge]] by [[miner]]s with their [[smelting]] skill. It requires a [[mining]] skill of 175.\r\n==As an ingredient==\r\nMithril Bar is used in the following recipes:\r\n===Alchemy===\r\n*[[Transmute: Mithril to Truesilver]]\r\n===Engineering===\r\n* [[Deepdive Helmet]]\r\n* [[Unstable Trigger]]\r\n* [[Mechanical Repair Kit]]\r\n* [[Mithril Blunderbuss]]\r\n* [[Mithril Casing]]\r\n* [[Mithril Tube]]\r\n* [[Mithril Heavy-Bore Rifle]]\r\n* [[Mithril Mechanical Dragonling]]\r\n* [[Snowmaster 9000]]\r\n===Jewelcrafting===\r\n* [[Citrine Ring of Rapid Healing]]\r\n* [[Mithril Filigree]]\r\n==As a quest objective==\r\n'''Mithril Bar''' is needed for the following quests:\r\n*[[Smelt On, Smelt Off]]\r\n*[[The Great Silver Deceiver]]\r\n*[[The Art of the Imbue]]\r\n==Notes==\r\nThese quests are no longer available, but once were:\r\n* [[The Horde Needs More Mithril Bars!]]\r\n** one of the quests active during the [[Gates of Ahn'Qiraj]] event.\r\n* [[Zinfizzlex's Portable Shredder Unit (quest)]]\r\n** a quest active in [[Alterac Valley]] until about patch 1.7",},
			["Mithril Blunderbuss"] = { content = "==Source==\r\nMithril Blunderbuss is created by [[engineering|engineers]] with 205 skill.",},
			["Mithril Casing"] = { content = "'''Mithril casing''' is a craftable item that is used for [[Engineering]] [[Recipes]]. \r\n==Source==\r\nMithril Casing is created by [[Engineer]]s with a skill of 215.\r\nThe components are:\r\n*3 [[Mithril Bar]]s\r\nThe [[schematic]] is learned from a trainer.\r\n==Mithril Casing as an Ingredient==\r\n'''Mithril Casing''' is used in the following recipes:\r\n===[[Engineering]]===\r\n*[[Mithril Frag Bomb]]\r\n*[[Hi-Explosive Bomb]]\r\n*[[The Big One]]\r\n*[[Goblin Bomb Dispenser]]\r\n*[[Gnomish Battle Chicken]]\r\n*[[Salt Shaker]]\r\n*[[Masterwork Target Dummy]]\r\n*[[World Enlarger]]\r\n*[[Deepdive Helmet]]\r\n*[[Thorium Rifle]]\r\n*[[Firework Launcher]]\r\n*[[Cluster Launcher]]\r\n==Mithril Casing as a Quest Objective==\r\n*Chasing A-Me 01 (2)",},
			["Mithril Deposit"] = { content = "'''Mithril Deposits''' can be found primarily in zones that have a minimum level of 30, 35, or 40.\r\n==Contents==\r\nWith [[Mining]] (1) in retail or Mining (175) in ''[[World of Warcraft: Classic|Classic]]'', these veins can be looted for:\r\n*[[Mithril Ore]] (guaranteed if Mining is 150 or higher)\r\n**[[Mithril Ore Nugget]] (if Mining is 149 or lower; retail only)\r\n*[[Solid Stone]] (common / uncommon)\r\n*[[Aquamarine]] (rare / very rare)\r\n*[[Black Vitriol]] (rare / very rare)\r\n*[[Citrine]] (rare / very rare)\r\n*[[Star Ruby]] (rare / very rare)\r\n<small>''Items with multiple listed rarities signify a difference between retail and ''Classic''. (retail rarity / ''Classic'' rarity).''</small>\r\n===Quest items===\r\nMithril Deposits in [[Felwood]] can also contain [[Tainted Vitriol]] if the player has a [[Cenarion Beacon]] in their inventory.\r\n==Locations==\r\nKalimdor\r\n*[[Azshara]] (''Classic'' only)\r\n*[[Badlands]]\r\n*[[Desolace]] (''Classic'' only)\r\n*[[Felwood]]\r\n*[[Feralas]]\r\n*Southern [[Dustwallow Marsh]]\r\n*[[Tanaris]]\r\n*[[Thousand Needles]]\r\n*[[Un'Goro Crater]]\r\n*[[Silithus]] (''Classic'' only)\r\n*Western [[Winterspring]] (''Classic'' only)\r\n*The [[Charred Vale]], [[Stonetalon Mountains]] (''Classic'' only)\r\nEastern Kingdoms\r\n*[[Alterac Mountains]] (''Classic'' only)\r\n*Southwestern [[Arathi Highlands]] & cave east of [[Hammerfall]], Arathi Highlands\r\n*[[Blasted Lands]] (''Classic'' only)\r\n*[[Burning Steppes]]\r\n*Northern [[Eastern Plaguelands]]\r\n**Southwestern Eastern Plaguelands (''Classic'' only)\r\n*The [[Hinterlands]]\r\n*[[Searing Gorge]]\r\n==Notes==\r\n*Mithril Deposits in the [[Garrison Armory]] mine in [[Blasted Lands (Classic)|Blasted Lands]] can only be mined by [[Horde]] players.",},
			["Mithril Filigree"] = { content = "==Source==\r\nThis item can be acquired through crafting or another combine-type effect.\r\n==Mithril Filigree as an ingredient==\r\nThis item is used to make: \r\n* Aquamarine Pendant of the Warrior\r\n* Jade Pendant of Blasting\r\n* Blazing Citrine Ring\r\n* Figurine - Jade Owl\r\n* Opal Necklace of Impact\r\n* Engraved Truesilver Ring",},
			["Mithril Frag Bomb"] = { content = "==Source==\r\nThe '''Mithril Frag Bomb''' is crafted by [[Engineering|Engineers]] with a skill level of 215. \r\nThe components are:\r\n*1 [[Mithril Casing]]\r\n*1 [[Unstable Trigger]]\r\n*1 [[Solid Blasting Powder]]\r\nProduces 3 bombs.\r\nThe recipe for this item is taught by the [[Engineering trainer]]s.",},
			["Mithril Heavy-Bore Rifle"] = { content = "'''Mithril Heavy-bore Rifle''' is a gun that increases ranged attack power.\r\n==Source==\r\nMithril Heavy-bore Rifle is crafted by [[Engineering|Engineers]] with a minimum skill level of 220.\r\nThe components are:\r\n*2 [[Mithril Tube]]\r\n*1 [[Unstable Trigger]]\r\n*1 [[Heavy Stock]]\r\n*6 [[Mithril Bar]]\r\n*2 [[Citrine]]\r\nThe recipe for this item is taught by Schematic: Mithril Heavy-bore Rifle, which is a world drop from level 40 - 50 mobs.",},
			["Mithril Mechanical Dragonling"] = { content = "'''Mithril Mechanical Dragonling''' is a [[trinket]] that summons a [[mechanical]] [[dragonling]] [[guardian pet]]. It requires an Engineering skill of at least 250 to use.\r\n==Source==\r\nThis item can be crafted with [[Engineering]] (250); taught by [[Schematic: Mithril Mechanical Dragonling]]. \r\n===Engineering===\r\n* [[Arcanite Dragonling]]\r\n==Notes==\r\nUsing this item starts a 5 minute cooldown on this trinket, and a 1 minute cooldown on other guardian pet trinkets (such as the other mechanical dragonling type trinkets, [[Defender of the Timbermaw]], etc). This means that there is still some value in keeping older dragonling trinkets after creating new ones.\r\n==See also==\r\n* [[Mechanical Dragonling]]\r\n* [[Arcanite Dragonling]]",},
			["Mithril Order"] = { content = "The Mithril Order is an association of Mithrilsmiths - artisan blacksmiths who specialize in working with [[Mithril]]. Members of The Mithril Order can be found in Horde, Alliance, and neutral [[cities]]. The Order appears to be a part of the larger [[Thorium Brotherhood]] [[faction]], but you do not gain reputation with the larger faction by helping them or doing their quests.\r\n==Notable Members of The Mithril Order==\r\n* Hank the Hammer\r\n* Ox\r\n* McGavan\r\n* Galvan the Ancient\r\n* Trenton Lighthammer\r\n==Joining The Mithril Order==\r\nThe Mithril Order only accepts new members that prove their skills in working with Mithril. To do that, upcoming blacksmiths can do the '''[[Mithril Order quest chain]]'''. During this quest chain a blacksmith receives all blacksmithing plans that are needed for doing [[Quest:The Art of the Armorsmith]]. Note that the quester is '''not''' obliged to specialize in [[Armorsmithing]] to start or complete this series of quests.\r\nFollowing is a short overview of this quest chain:\r\n# The Origins of Smithing/The Old Ways\r\n# In Search of Galvan/Booty Bay or Bust!\r\n# The Mithril Order\r\n# Three quests, which can be completed in any order:\r\n#* Smelt On, Smelt Off\r\n#* The Great Silver Deceiver\r\n#* The Art of the Imbue\r\n#: Complete all of the above to get the quest\r\n#: Expert Blacksmith!\r\n# Complete any one of the three to progress:\r\n#: Galvan's Finest Pupil\r\n# Again, three quests which can be completed in any order:\r\n#* The World At Your Feet\r\n#* A Good Head On Your Shoulders\r\n#* The Mithril Kid\r\n# Did You Lose This?",},
			["Mithril Order quest chain"] = { content = "'''The Mithril Order''' quest chain provides a blacksmith with the recipes they need to\r\ncomplete the quest\r\n* [[The Art of the Armorsmith]]\r\nThe quester learns 7 blacksmithing plans in the course of this chain, and gains\r\ntwo trinkets. The quester is '''not''' obligated to specialize in\r\n[[armorsmithing]] to start or complete this series of quests.\r\n===Preamble===\r\n [[The Origins of Smithing]] / [[The Old Ways]]\r\nAn older smith in town ([[Orgrimmar]] for the Horde, [[Stormwind]] for the Alliance) offers to teach you something new.\r\n* [[Horde]]: [[Aturk the Anvil]] asks you to bring back 4 [[Steel Breastplate]]s and 4 [[Steel Plate Helm]]ets. In exchange, he will teach you how to make [[Orcish War Leggings]].\r\n* [[Alliance]]: [[Hank the Hammer]] asks you to make 6 [[Golden Scale Bracers]]. In return, he offers you [[Plans: Golden Scale Gauntlets]].\r\n===Part one: Galvan the Ancient===\r\n [[In Search of Galvan]] / [[Booty Bay or Bust!]]\r\n[[Hank the Hammer]] (or for the Horde, [[Ox]]) recognizes your achievement, and\r\nasks you to take a [[Mithril Insignia]] to [[McGavan]] in [[Booty Bay]],\r\nat the southern end of [[Stranglethorn Vale]].\r\nThis is, of course a test. Those not worthy of joining the Mithril Order will\r\naccept the insignia and not turn it over. But those who ''are'' worthy...\r\n [[The Mithril Order]]\r\nMcGavan is happy to find another worthy of induction into the Order. And he\r\nknows where the smith Galvan the Ancient is! He directs you to take a\r\n[[Mithril Pendant|token]] to Galvan, to show that McGavan sent you.\r\nGalvan, you are told, is deep in the wilds of\r\n[[Stranglethorn Vale]],\r\nbetween [[Zul Gurub]] and the [[Mosh'Ogg Ogre Mound]].\r\nIndeed, you find him there. And more, seeing the pendant, he wants to start\r\nyour induction into the [[Mithril Order]] immediately!\r\nGalvan the Ancient gives three quests (these may be completed in any order):\r\n [[Smelt On, Smelt Off]]\r\n Materials Required:\r\n* 40 [[Iron Bar]]\r\n* 40 [[Mithril Bar]]\r\n*Reward: [[Plans: Ornate Mithril Pants]]\r\n[[The Great Silver Deceiver]]\r\n Materials Required:\r\n* 40 [[Mithril Bar]]\r\n* 5 [[Truesilver Bar]]\r\n*[[Plans: Ornate Mithril Gloves]]\r\n[[The Art of the Imbue]]\r\n Materials Required:\r\n* 40 [[Mithril Bar]]\r\n* 4 [[Citrine]]\r\n*[[Plans: Ornate Mithril Shoulder]]\r\n[[Galvan's Finest Pupil]]\r\nComplete any one of the above three quests, and Galvan will direct you to\r\nhis finest pupil, Trenton Lighthammer,\r\nin [[Gadgetzan]].\r\n[[Expert Blacksmith!]]\r\nComplete all three of the above quests, and Galvan declares you to be The\r\nBig Winner!\r\n===Part 2: Trenton Lighthammer===\r\nTrenton gives you three quests. Like Galvan's quests, these can be completed\r\nin any order. Trenton teaches you the plans directly; there is no separate\r\nitem \"Plans: Ornate Mithril Boots\" (or breastplate or helm).\r\n [[The World At Your Feet]]\r\n* 2 [[Heavy Mithril Boots]]\r\n* 1 [[Ornate Mithril Pants]] (from [[Smelt On, Smelt Off]])\r\n* Reward: Trenton teaches you how to make [[Ornate Mithril Boots]]\r\n [[The Mithril Kid]]\r\n* 2 [[Heavy Mithril Breastplate]]\r\n* 1 [[Ornate Mithril Gloves]] (from [[The Great Silver Deceiver]])\r\n* Reward: Trenton teaches you how to make [[Ornate Mithril Breastplate]]\r\n [[A Good Head On Your Shoulders]]\r\n* 2 [[Mithril Coif]]\r\n* 1 [[Ornate Mithril Shoulder]] (from [[The Art of the Imbue]])\r\n* Reward: Trenton teaches you how to make [[Ornate Mithril Helm]]\r\nEach of Trenton's quests use knowledge you got from Galvan the Ancient and rewards you with something you will need for the final quest.\r\n [[Did You Lose This?]]\r\nIf you complete all three of these quests, Trenton rewards your dedication\r\nby offering you another trinket:\r\n===Postlude: The Art of the Armorsmith===\r\n''Main article: [[The Art of the Armorsmith]]''\r\nThe quests [[Galvan the Ancient]] gives you provides the recipes you need\r\nfor [[Trenton Lighthammer]]. And the quests Trenton gives you provide\r\nthe recipes you need for this quest.\r\n* [[The Art of the Armorsmith (Alliance)]] or [[The Art of the Armorsmith (Horde)]]\r\n* 4 [[Ornate Mithril Helm]]\r\n* 2 [[Ornate Mithril Boots]]\r\n* 1 [[Ornate Mithril Breastplate]]\r\n==Total Materials Required==\r\nTo complete the ''entire'' chain, from the initial quest all the way up through the [[The Art of the Armorsmith]] quest, you will need:\r\nDue to differences in the initial quest, [[Horde]] characters must use\r\nthese addition resources:\r\n* 90 [[Steel Bar]]\r\n* 16 [[Solid Stone]]\r\n* 4 [[Citrine]]\r\n==Notes==\r\nOrcish War Leggings were formerly learned from a set of [[Plans: Orcish War Leggings|plans]]. They are now learned directly.",},
			["Mithril Ore"] = { content = "'''Mithril Ore''' is mined from Mithril Deposits, with a minimum [[mining]] skill of 150. The [[Mithril Order]] was named after the mineral.\r\nIt's very lightweight.\r\n==Source==\r\nMithril Deposits may be found in many areas where the typical creature level is between about 35 and 55.\r\nMithril Deposits are most frequently mined in:\r\n* [[Badlands]]\r\n* [[Burning Steppes]]\r\n* [[Eastern Plaguelands]]\r\n* [[Felwood]]\r\n* [[Searing Gorge]]\r\n* [[Tanaris]]\r\n* [[Thousand Needles]]\r\n===Also found in Mithril Deposits===\r\n* [[Solid Stone]]\r\n* [[Black Vitriol]]\r\n* [[Citrine]]\r\n* [[Aquamarine]]\r\n* [[Star Ruby]]\r\n==As an ingredient==\r\n* Mithril Ore is smelted into [[Mithril Bar]]s at a [[forge]], requiring a [[mining]] skill of 150 or more.\r\n* Mithril Ore can be [[prospecting|prospected]] (consuming 5 ore) with a [[Jewelcrafting]] skill of 150 or more, resulting in:\r\n* [[Citrine]] (50%)\r\n* [[Aquamarine]] (44%)\r\n* [[Star Ruby]] (38%)\r\n* [[Huge Emerald]] (3%)\r\n* [[Blue Sapphire]] (3%)\r\n[[Alchemy|Alchemist]]s can use Mithril Ore to make:\r\n* [[Lesser Stoneshield Potion]]\r\n==Notes==\r\n[[Gold Vein]]s and [[Truesilver Vein]]s appear, uncommonly, wherever Mithril Deposits are found. \r\n==See also==\r\n* [[Mithril Bar]]",},
			["Mithril Shield Spike"] = { content = "The '''Mithril Shield Spike''' is an enhancement for a shield. Any time the user blocks an attack, the shield spike does some damage to the attacker.\r\n==Source==\r\nThis item is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 215.\r\nThe components are:\r\n*4x Mithril Bar\r\n*2x Truesilver Bar\r\n*4x Solid Grinding Stone\r\nPlans: Mithril Shield Spike are a [[World Drop]].\r\n==Notes==\r\n*The Mithril Shield Spike does 16-20 points of damage for every block.\r\nAs of [[Patch_2.4.2]], Blacksmithing is not required to apply the shield spike to a shield.",},
			["Mithril Spurs"] = { content = "'''Mithril Spurs''' are created by the [[Blacksmithing]] profession.\r\n==Source==\r\nTaught by Plans: Mithril Spurs.\r\n==Notes==\r\nThis item increases mount speed by 4%. It does not increase running or swimming speed.",},
			["Mithril Tube"] = { content = "A simple tube of mithril. Used in [[Engineering]].\r\n==Where to find Mitril Tube==\r\n'''Mithril Tube''' is created by [[engineer]]s with a skill of 195.\r\nComponents required:\r\n*3 Mithril Bar\r\n==Mithril Tube as an ingredient==\r\n'''Mithril Tube''' is used in the following recipes:\r\n===[[Engineering]]===\r\n*Deadly Scope\r\n*Gnomish Death Ray\r\n*Gnomish Goggles\r\n*Gnomish Net-o-Matic Projector\r\n*Gnomish Rocket Boots\r\n*Gnomish Shrink Ray\r\n*Goblin Dragon Gun\r\n*Goblin Mortar\r\n*Goblin Rocket Boots\r\n*Mithril Blunderbuss\r\n*Mithril Heavy-bore Rifle\r\n*Sniper Scope\r\n*Thorium Rifle\r\n==As a quest objective==\r\n* Show Your Work (Gnome) (for specializing in [[Gnome Engineering]]).",},
			["Mitigation"] = { content = "#REDIRECT [[Damage mitigation]]", redirect = "Damage mitigation",},
			["Mitrius"] = { content = "'''Mitrius''' is an old [[human]] [[druid]] who has had some success trading with a [[murloc]] [[tribe]]. He had spent two years on the [[Shiverwind Coast]], studying various plants and sea creatures, and his camp was less than a day's travel from a murloc tribe. After a few months the tribe no longer felt him dangerous and began to trade with him. At some point they even invited Mitrius into their home. He became a regular guest, and was able to ask them many questions about their culture. He is known for being the most tolerated non-murloc in all [[Azeroth]], and being one of, if not the eminent, expert on murlocs.",},
			["Mitsuwa"] = { content = "'''Mitsuwa''' is a level 31 [[quest giver]] located at the [[Zoram'gar Outpost]] in the [[contested]] territory of [[Ashenvale]].\r\nHe gives the quest Troll Charm.\r\nHis name is a reference to Mitsuwa Marketplace in California. The marketplace neighbors the Blizzard HQ.\r\nSee [[List of Ashenvale NPCs]].",},
			["Mixie Farshot"] = { content = "'''Mixie Farshot''' is a level 52 [[gun]] and [[ammo vendor]] located at [[Spinebreaker Post]] in the [[contested]] territory of [[Hellfire Peninsula]]. Although she shares the same last name with [[Lanka Farshot]], they apparently are not related, though this could be a loose reference to the MMORPG comic 'Looking For Group,' where two of the main characters are a Tauren and his adopted green-skinned daughter.\r\nSee [[List of Hellfire Peninsula NPCs]].",},
			["Mizgill"] = { content = "When [[Illidan]], [[Kael'thas]], and [[Vashj]] undertook their campaign to close the [[Dark Portal|Dimensional Gate]]s that supported the [[Demon|demonic]] army of [[Magtheridon]], they encountered two [[Fel Orc]] clans. [[Illidan]] closed the gates and his forces killed '''Mizgill''' and [[Gorgosh]], who were engaged guarding the portals from [[Akama]]'s rebels.\r\n==Statistics from Warcraft III==\r\n* 825 HP\r\n* 405 MP\r\n* 47-67 (+5 lightning orb) chaos melee damage\r\n* 7 hero armor\r\n* Attributes\r\n** 29 Strength\r\n** 31 Agility '''Primary Attribute'''\r\n** 27 Intelligence",},
			["Mizjah"] = { content = "#redirect [[Mizjah Ruins]]", redirect = "Mizjah Ruins",},
			["Mizjah Ruins"] = { content = "The '''Mizjah Ruins''' are an area southeast of [[Grom'gol Base Camp]] inhabited by [[Mosh'Ogg Brute]]s and [[Mosh'Ogg Witch Doctor]]s. These [[ogre]]s are responsible for ambushing supply caravans going to to [[Stonard]].\r\n==Relevant quests==\r\nThe Defense of Grom'gol - from [[Commander Aggro'gosh]] in [[Grom'gol Base Camp]], part of a quest line.",},
			["Mmmrrrggglll"] = { content = "'''Mmmrrrggglll''' is the chieftain of the [[Grimscale Murloc]]s who are situated at both the [[Tranquil Shore]] and the [[Golden Strand]]. It is possible that he was the one responsible for the theft of cargo from [[Captain Kelisendra]]'s ship. To find him, simply keep an eye throughout the Golden Strand as he wanders the length of the Murloc camps on the shoreline. He can easily be recognized by his somewhat unique colors.\r\nWhen low on health, he will heal himself back up to full health using [[Healing Wave]]. However, he only appears to do this once or twice in any given fight. He also utilizes the [[Shaman]] abilities [[Frost Shock]] and [[Chain Lightning]]. Mmmrrrggglll respawns very quickly, about 3-5 minutes.\r\n==Objective of==\r\n*Drops Ring of Mmmrrrggglll for the quest The Ring of Mmmrrrggglll.\r\n==Loot==\r\nHas a chance to drop:\r\n*Captain Kelisendra's Cargo ''(Quest Item)''\r\n*Captain Kelisendra's Lost Rutters ''(Quest Starter)''\r\n==Notes==\r\n*If you're on the quest \"The Ring of Mmmrrrggglll\", upon death the rest of the [[Grimscale]] murlocs will run around in fear for a few seconds.\r\n*His name may be a reference to the popular .",},
			["MMORPG"] = { content = "#REDIRECT [[Massively multiplayer online game]]", redirect = "Massively multiplayer online game",},
			["Mo'arg"] = { content = "The '''mo'arg''' are a demonic race within the ranks of the [[Burning Legion]]. Tall and broad in stature, they are particularly proficient in hand-to-hand combat. Many mo'arg are tinkerers, scientists, blacksmiths and engineers among the ranks of the Legion and have 'improved' their own bodies with bionic parts. Some have gone so far with their enhancements that they resemble the [[abomination]]s of the [[Scourge]], with the only difference of their undead counterparts being that they are actually very clever (as well as very alive...). Nevertheless, other mo'arg are far less intelligent and used as front line soldiers. These grunts are commonly termed '[[felguard]]'.\r\nThe [[gan'arg]] subrace bears little resemblance to the mo'arg mother race, being stunted and weak to the point that they seem far more similar to [[kobold]]s than they do the gargantuan demons of the Burning Legion. However, they are often just as intelligent and cunning as their mo'arg masters and should not be underestimated.\r\nSome mo'arg seem to serve their own agenda, and are not hostile to players.\r\n''\"Brutish though they seem, these iron-stitched horrors are exceedingly brilliant engineers and forge-smiths. Their black iron constructs have sown death across a thousand worlds.\"'' - Exodar Holographic Emitter in the [[Vault of Lights]]\r\n==Famous Mo'arg==\r\n*The Maker\r\n*Forgemaster Morug\r\n*Gatewatcher Gyro-Kill\r\n*Gatewatcher Iron-Hand\r\n*Doomclaw\r\n*Overseer Razorsaw\r\n*Overseer Ripsaw",},
			["Mo'grosh"] = { content = "An clan of [[Ogre]]s that have taken up residence to the northeast of [[Loch Modan]]. Their leader, [[Chok'sul]], has coordinated attacks against the town of [[Thelsamar]], [[Stonewrought Dam]], and [[dwarf|dwarven]] excavation sites in the area.\r\nKnown members:\r\n==See also==\r\n*[[Ogre]]",},
			["Mo'grosh Stronghold"] = { content = "'''Mo'grosh Stronghold''' is a set of [[ogre]]-infested caves located in northeastern [[Loch Modan]]. The [[ogre]]s number several shamans, enforcers, and brutes, ranging from level 18-20. Adventurers come here seeking to eradicate these dangerous enemies of the kingdom, and the most ambitious even attempt to claim the head of the ogres' leader, [[Chok'sul]]. As of [[Patch 2.3]] these ogres are no longer elite.\r\nJudging from the ruins in the area, it is likely that the stronghold was a troll settlement at one time, though whether the ogres drove the trolls out or the trolls had left lond before, leaving the land open for the ogres to move in, is unknown.",},
			["Mo'mor the Breaker"] = { content = "'''Mo'mor the Breaker''' is a level 67 [[quest giver]] located at [[Telaar]] in the [[contested]] territory of [[Nagrand]].\r\nHe starts the following quests:\r\n* The Ruins of Burning Blade\r\n* The Twin Clefts of Nagrand\r\n* Diplomatic Measures\r\nSee [[List of Nagrand NPCs]].",},
			["Moa'ki Harbor"] = { content = "'''Moa'ki Harbor''' is a [[Tuskarr]] port in south-central [[The Dragonblight]].",},
			["Moam"] = { content = "During the [[War of the Shifting Sands]], three great dragons - [[Arygos]], [[Merithra|Merithra of the Dream]], and [[Caelestrasz]] sacrificed themselves to aid in the creation of the [[Scarab Wall]]. \r\nThough the wall prevented the [[Qiraji]] from venturing out, the insect empire refused to remain idle. In preparation for their reemergence in the world, [[C'Thun|the shadowy master of Ahn'Qiraj]] commanded Emperor Vek'lor to create a new obsidian statue superior to all other [[Obsidian Destroyer|Destroyers]]. Vek'lor sought his twin brother's aid in the task, and while Vek'nilash used his physical might to craft a grand body of volcanic rock, Vek'lor fortified the shell with powerful magic. \r\nEmperor Vek'lor named the finished construct Moam, and observed as the dark master infused it with life. He was pleased and surprised to find that the improved Obsidian Destroyer was far more versatile than its earlier counterparts. The [[Twin Emperors]] intended to use Moam as a colossal weapon, knowing that its strengths would help it survive in the thick of melee as well as magical combat-but they did not expect for the construct's abilities to advance further without their own assistance. \r\nFar more surprising, even to the arcane emperors, was Moam's ability to summon burning elementals crafted of pure mana. \r\nIt was only after Vek'lor witnessed this demonstration of Moam's unbridled power that the source of the construct's seemingly limitless energy was revealed - three tortured dragons: Arygos, Merithra and Caelestrasz, trapped alive within Ahn'Qiraj but not granted the mercy of death as the emperors had believed. \r\nThe twins were stunned to learn that their overseer had somehow bound the three dragons, then drained their inherent magical energy and corrupted it for his own use - fortifying not only Moam, but the rest of his twisted creations as well. Truly, it seemed as if there was no limit to the powers of the Ancient One.\r\n===Moam===\r\n* '''Trample''' - AOE melee range attack that deals about 900 -1200 damage to a tank.\r\n* '''Drain Mana''' - Drains 500 mana from 6 people. Virtually unlimited range. Gives 1000 mana to Moam per person. This attack is not directional.\r\n* '''Arcane Explosion''' - If Moam's mana reaches 100% he emotes \"Moam bristles with energy\" and unleashes a 3000 damage arcane explosion plus fall damage.\r\n* '''Summon Mana Fiend''' - 90 seconds into the battle, Moam summons 3 Mana Fiends, which are arcane elementals. These are banishable and rootable.\r\n* '''Turn to Stone''' - Also at 90 seconds, after summoning the mana fiends, Moam will turn to stone. In this state he cannot attack and does not drain mana (but does regenerate some). After a 90 seconds, or if his mana reaches 100%, he comes out of stone.\r\n===Mana Fiend===\r\n* '''Arcane Explosion''' - An arcane explosion that deals 900 - 1100 arcane damage, but has no knockback. \r\n* '''Counterspell''' This ability also interrupts spellcasting and blocks out that school of magic for twelve seconds. I do not know who it preferentially targets, or if it's an AOE.\r\n===3 Priests, Warlocks, and Hunters===\r\nHaving three each of [[warlock]]s and [[priest]]s, and a [[hunter]] (Viper Sting does not stack) makes this fight easier, if you have the coordination together. Basics of this strategy are mana drain, ice traps/banish, and DPS like crazy.\r\nStarting out, you need to send in your MT, any non-mana users, and the [[shaman]]s and [[druid]]s to heal. [[Warlock]]s and [[priest]]s should stay behind and wait 2-3 seconds before running in (This will prevent them from getting their mana drained by '''Moam''').\r\nHave all three [[warlock]]s and all three [[priest]]s drain mana. Also have a [[hunter]] keep a [[Viper Sting]] on it. This is enough mana burning to keep Moam from doing an Arcane Explosion. All other classes will be doing damage and healing.\r\nAfter 90 seconds, 3 arcane elementals (Mana Fiends) will spawn - You want Moam to be below 45% by this time. [[Hunter]]s can lay freeze traps in front of the Mana Fiends, then have a [[warlock]] banish when he is able. Using [[Feign Death]]/Freeze Trap, a hunter can pick up the add and prevent the arcane explosion. [[Warlock]]s will re-banish whenever capable.\r\nWith Moam a 45%, 1 [[priest]] can take a quick break to perform heals on essential members (no more than 30 seconds). At this point Non-stop DPS on Moam will bring him down easily.\r\n*Take down the adds, and reap the rewards.\r\n===3 Priests and 3 Warlocks===\r\nHave all three [[warlock]]s and all three [[priest]]s drain mana. Also have a [[hunter]] keep a [[Viper Sting]] on it. This is enough mana burning to keep Moam from doing an Arcane Explosion. All other classes will be doing damage and healing.\r\nAfter 90 seconds, 3 arcane elementals (Mana Fiends) will spawn. The warlocks will keep these banished for the remainder of the fight. Priests will continue to mana burn. The rest of the raid will continue to attack Moam and try to kill it before it reverts to normal. Since Moam cannot move while it is turned to stone, there is no need for the raid to manage aggro.\r\nWhen Moam dies, the raid should heal themselves. Let the banish end on the Mana Fiends one at a time and proceed to kill them. They do not despawn when Moam dies, but if the Mana Fiends wipe the raid when Moam is dead, they will despawn.\r\nIf the raid is short on warlocks, the elementals can be burned down as they only have approximately 15,000 health. It may be advisable to have 3 warlocks as the elementals do considerable AoE arcane damage.\r\nNote that the priests will possibly run out of mana during this fight. Druids can use Innervate on priests if necessary. Mana potions are highly recommended. Priests should be aware that Inner Focus and the free spell therein do not count as casting for purposes of interrupting 100% mana regeneration. A carefully timed Inner Focus and mana burn can result in enough regeneration to cast the spell once more.\r\n===Fewer than 3 priests or warlocks===\r\nAll priests and warlocks should still be mana burning Moam, but it '''will''' do an Arcane Explosion. Let it explode at about 80 seconds. This will cause Moam to turn to stone with very little mana, allowing warlocks and priests to keep up the mana drain so Moam will not not revert to normal prematurely.\r\nEveryone but the main tank and a healer needs to run away from Moam before it does the Arcane Explosion. A [[Greater Arcane Protection Potion]] on the tank is recommended. After Moam explodes, it's mana returns to 0. When it stoneforms, either kill or banish the Mana Fiends and finish Moam off.\r\n===DPS===\r\nIf the raid has a lot of DPS, the raid can try to kill Moam in under 90 seconds to prevent it from turning to stone and summoning Mana Fiends. If the raid is lacking warlocks and priests, then this may be the raid's best strategy. He has about 340000 HP, requiring an average DPS from the raid of 3778 in this time (just under 200 DPS per person on average).\r\n===Not Enough DPS===\r\nIf the raid is wiping to Moam when it reaches full mana and there are not enough warlocks, hunters, and priests to mana drain it fast enough, then [[druid]]s can shapeshift into cat form for extra damage. Since druids in cat form are not affected by the mana drain, Moam will have fewer players to mana drain from.\r\n==Quotes==\r\n*\"Moam senses your fear.\"\r\n==Rewards==\r\n* Provides 150 [[Cenarion Circle]] reputation at friendly.\r\n* Provides 50 [[Brood of Nozdormu]] reputation at hated.",},
			["Moaoto"] = { content = "'''Moaoto''' can be found in [[Shattrath City]]. This pig farmer will give players, who attended the Blizzard World Wide Invitational 2007 and provide a code, a Fortune Coin.",},
			["Moa’ki Harbor"] = { content = "#REDIRECT [[Moa'ki Harbor]]", redirect = "Moa'ki Harbor",},
			["Mob"] = { content = "A '''mob''' (short for ''mobile'' or ''mobile object'') is a non-player entity whose primary purpose is to be killed for [[experience]], [[quest objectives|quest objective]], or [[loot]]. \r\nThe gaming term \"mob\" is not to be confused with its usual meanings in the English language, i.e. a large disorderly crowd or an organized gang of criminals.\r\nMobs are also known as bad guys, beasts, enemies, monsters, non-player attackers, and opponents. The World of Warcraft-specific term for a ''mob'' is [[creep]], coined by [[Blizzard]] and first used in ''Warcraft III''. The term ''mob'' is in wide-spread use in the [[MMORPG]]s genre.\r\n===Etymology===\r\nThe term was originally used in Multi User Dungeons (MUDs) the text-based precursors to MMORPGs. In-game objects were defined either as stationary items - \"objects\" (ranging from fountains to wearable equipment that you could pick up) or \"mobs\" (this included any NPC, be that aggressive monster or friendly shopkeeper, even if they weren't actually moving around due to STAY_ROOM or similar flags in their properties).\r\nIn World of Warcraft, Mobs differ from [[NPCs]] in that they are usually monsters that share a common name with several others rather than having a unique name or title, are non-friendly, are non-interactive, and/or exist solely for the purpose of being killed. These are the main aspect of [[PvE]], and are found throughout the game world.\r\n==See also==\r\n* [[Boss Mob]]\r\n* [[Trash Mob]]",},
			["Mobs"] = { content = "#REDIRECT [[Mob]]", redirect = "Mob",},
			["Mob"] = { content = "A '''mob''' (short for ''mobile'' or ''mobile object'') is a non-player entity whose primary purpose is to be killed for [[experience]], [[quest objectives|quest objective]], or [[loot]]. \r\nThe gaming term \"mob\" is not to be confused with its usual meanings in the English language, i.e. a large disorderly crowd or an organized gang of criminals.\r\nMobs are also known as bad guys, beasts, enemies, monsters, non-player attackers, and opponents. The World of Warcraft-specific term for a ''mob'' is [[creep]], coined by [[Blizzard]] and first used in ''Warcraft III''. The term ''mob'' is in wide-spread use in the [[MMORPG]]s genre.\r\n===Etymology===\r\nThe term was originally used in Multi User Dungeons (MUDs) the text-based precursors to MMORPGs. In-game objects were defined either as stationary items - \"objects\" (ranging from fountains to wearable equipment that you could pick up) or \"mobs\" (this included any NPC, be that aggressive monster or friendly shopkeeper, even if they weren't actually moving around due to STAY_ROOM or similar flags in their properties).\r\nIn World of Warcraft, Mobs differ from [[NPCs]] in that they are usually monsters that share a common name with several others rather than having a unique name or title, are non-friendly, are non-interactive, and/or exist solely for the purpose of being killed. These are the main aspect of [[PvE]], and are found throughout the game world.\r\n==See also==\r\n* [[Boss Mob]]\r\n* [[Trash Mob]]",},
			["Mob difficulty colors"] = { content = "This list shows you the color of a [[quest]] / [[mob]], depending at your own level.\r\n* Gray mobs give no [[XP]] and reduced [[reputation]]\r\n* Gray players give no [[HK]]s\r\n* [[Quest]]s 5 or more levels below you give reduced XP but full reputation\r\nA quest or mob's difficulty color is sometimes referred to as its 'con'. IE: a gray-con mob, or something cons red. This is a holdover from [[MUD]]/[[MUSH]]/[[MUCK]]s where the standard command to determine difficulty was /con or /consider. Everquest1 had/has similar system in that you had to type the command. World of Warcraft has simplified the consider command in that it shows it every time you target something, and you can tell at a glance (once you are familiar with the system). Exceptions to the following are [[elite creature|elites]].\r\n*Grey [[mobs]] are well below you. You should have little difficulty dispatching them unless you are [[AFK]] during the whole fight or near death when you pick the fight up, regardless of class.\r\n*Green mobs are somewhat below you, and while one to three of them should pose little challenge to you (depending on your class), beware of large groups of them.\r\n* Yellow mobs are always within your character level. Make sure to give them your full attention and you should be able to kill them. &plusmn; 2.\r\n* Orange mobs are always 3 and 4 levels above you. Depending on your class, they are either to be avoided, or to be given your all to defeat.\r\n* Red mobs are always 5 though 9 levels above you. You should always avoid these if you can help it, or be well prepared if you can't or are summoning it for a quest. Even then, most classes should not try it.\r\n* Skull mobs are always 10 or more levels above you. Regardless of class, never, ever engage these mobs alone.",},
			["Mob mining"] = { content = "'''Ore skinning''' is the act of gathering [[ore]]s and other related items from the corpse of dead creatures, exclusively [[giant]]s and [[elemental]]s.\r\nTo do so one must have the appropriate level of [[Mining]] and a [[mining pick]], and simply act as though they were gathering from any other ore [[node]]. Similar to [[skinning]] the player requires a mining skill of at least five times the target mob's level, but unlike skinning miners can not skill up this way.\r\n==Ore skinnable creatures==\r\nOnly some stone based [[giant]]s and [[elemental]]s (notable only elementals that resemble giants) can currently be ore skinned. The total is currently 23 and these appear in [[Netherstorm]], [[Terrokar Forest]], [[Blade's Edge Mountains]], [[Shadowmoon Valley]], [[Nagrand]], [[Hellfire Peninsula]] as well as [[Mana-Tombs]].\r\nSome of the skinnable creatures include:\r\n* [[Colossi]] in [[Netherstorm]], [[Nagrand]], [[Blade's Edge Mountains]], [[Shadowmoon Valley]] and [[Hellfire Peninsula]].\r\n* [[Earth elemental]]s in [[Shadowmoon Valley]] and [[Nagrand]].\r\n* [[Tavarok]] in [[Mana-Tombs]].\r\n==Drops==\r\nAs you can currently only skin [[Outland]] mobs you can only obtain Outland (301+) level ores. Ores are not all you receive however, alongside them you will get a variety of [[vendor trash]] items and even [[mineral]]s.\r\n==See also==\r\nFor more information see:\r\n* [[Mining]]\r\n* [[Ore]]s\r\n* [[Mineral]]s",},
			["Mocking Blow"] = { content = "'''Mocking blow''' is a bizarre taunt attack. It deals a small amount of damage and forces a target to attack you for a brief period of time. If you have problems [[Warrior_Taunt|Taunting]] an enemy off a party member, or don't have time to switch to defensive stance, this may be something useful.\r\n==Functionality==\r\nMocking Blow is a 10 [[Warrior|Rage]] ability that deals some damage and forces a target to attack you for six seconds. Unfortunately, it seems that after the six seconds, the mob resumes attacking whatever it was attacking previously. This is pretty much just an emergency ability to pull someone off a party member before switching to defensive stance and [[Warrior_Taunt|Taunting]] it. Unlike [[Warrior Taunt|Taunt]] and [[Challenging Shout]] this ability can be used while silenced. There are no [[Warrior Talents|Talents]] available for this skill.\r\n===Use===\r\n*Cast Cost: 10 [[Rage]]\r\n*Cast Time: [[Instant]]\r\n*Duration: 6 seconds (Taunt)\r\n*School and Damage Type: Physical\r\n*Targets/Positioning: Single target/front\r\n*Range: 5 yards (Melee)\r\n*Cooldown: 2 minutes\r\n*Stances: [[Battle Stance]]\r\n===Notes===\r\nRequires Melee Weapon\r\n==Tips and Tactics==\r\n*This is basically a powerful emergency taunt. Requires [[Stance Mastery]] to use well, since you need to switch to [[Battle Stance]] to use it, then back to [[Defensive Stance]] to tank. Nonetheless, this can be a very effective tactic if your taunt is resisted.\r\n*In PvP it's not very useful, as damage done is low, and hostile players won't be forced to attack you.\r\n*Against Hunters, Mocking Blow can be extremely useful to keep their pet attacking you during a freeze trap, breaking it, thus negating most hunters' main kiting technique. However [[Challenging Shout]] is perhaps a better option as it is can be used from any stance and is an [[AoE]] ability (Which means you do not have to change your target) and costs half as much rage as Mocking Blow.\r\n----\r\nMocking blow is similar to, but not the equivalent of, [[Warrior_Taunt|Taunt]] when the warrior is in [[Battle Stance]]. It has a longer [[cooldown]], and costs 10 rage whereas [[Warrior_Taunt|Taunt]] is free. This means it can't be used as liberally as [[Warrior_Taunt|Taunt]] for regaining aggro. It also only forces a target to attack you without generating any threat, unlike [[Warrior_Taunt|Taunt]]. Typically it is used when a high level mob is attacking a party member who has low health. If many mobs are attacking that party member, the better alternative is [[Challenging Shout]], although that has a long [[cooldown]]. \r\n \r\nThis is one of the abilities that needn't be upgraded in rank, as the damage increases are not significant.\r\n----",},
			["Mod"] = { content = "#REDIRECT [[AddOn]]", redirect = "AddOn",},
			["Modera"] = { content = "#REDIRECT [[Archmage Modera]]", redirect = "Archmage Modera",},
			["Modgud"] = { content = "The Sorceress wife of Emperor [[Thaurissan]], '''Modgud''', led the the assault on [[Grim Batol]] during the [[War of the Three Hammers]]. She was able to break through the gates of Grim Batol and devastate the fortress, although ultimately, she was killed by the leader of the [[Wildhammer]] [[dwarves]], [[Khardros Wildhammer]], during the battle.\r\nDue to Modgud's death, however, an evil taint spread through the fortress. Realizing that Grim Batol was now uninhabitable, the Wildhammer dwarves sought out a new home in [[Aerie Peak]].",},
			["Modimus Anvilmar"] = { content = "'''Modimus Anvilmar''' was the high king of all the dwarves. The [[Bronzebeard]], [[Wildhammer]], and [[Dark Iron Dwarf|Dark Iron]] clans were united under his rule. When he died, the [[War of the Three Hammers]] began. \r\n[[Anvilmar]], the town in the [[Coldridge Valley]] where [[dwarf]] and [[gnome]] adventurers begin their quests, is named after him.\r\nThe mighty statue of King Anvilmar is found at the city gates of Ironforge. It is a massive statue nearly 100 feet high. The dwarf depicted there wore intricate chain armor and held two great hammers on high. His mouth was open in a soundless battle-cry.\r\nIn WoW, the impressive figure of the High King faces the outer gate and the hallway just behind it. It is frozen in the dwarven \"/cheer\" posture, with a battlehammer in the right hand and a double-headed battleaxe in the left. The flightpath entering and leaving the city goes right over the statue's head.\r\nThe last of his relatives, [[Thargas Anvilmar]] and [[Hjalmar Anvilmar]], appear in the Warcraft Comic.",},
			["Mogor, Hero of the Warmaul"] = { content = "#REDIRECT [[Mogor]]", redirect = "Mogor",},
			["Mogor"] = { content = "The treacherous [[ogre]] lord of the [[Laughing Skull Clan]], '''Mogor''' remained in [[Draenor]] during both of the crossings.\r\n===Horde version===\r\nBefore Ner'zhul rebuilt the [[Dark Portal]] to [[Azeroth]] and sent his [[orc]]s through to gather the materials required for his grand scheme, he required the knowledge held by an order of [[death knight]]s to complete his preparations. This group of death Knights, though bearing the colors of the [[Shattered Hand Clan]], was currently under the control of Mogor, the renegade ogre-mage of the Laughing Skull clan, who was using them for some dark purpose of his own. \r\nNer'zhul sent his forces against the Laughing Skull to subjugate the death knights and kill Mogor for his rebelliousness. With the help of [[Grom Hellscream]], who was freed from captivity at the hands of the Laughing Skull clan, Ner'zhul's attack succeeded in destroying the death knights.\r\n===Alliance version===\r\nWhen the [[human]] armies invaded, Mogor sided with them in exchange for the dominance of his Clan in the [[Blade's Edge Mountains]]. He promised to deliver to them the [[Book of Medivh]].\r\nMogor was uncharacteristically true to his word, and even managed to escape the wrath of the [[shaman]] [[Ner’zhul]].\r\n==Mogor in World of Warcraft==\r\nIn the Burning Crusade expansion, Mogor leads the Warmaul Ogres in the Laughing Skull Ruins in northern Nagrand in Outland. He watches, while shouting insults at you, during the series of battles in the [[Ring of Blood]]. After you finish pummeling (or getting pummeled by) the 5 elites, Mogor himself comes down to fight you personally. He has a slight heal, (but has a ton of health, making it a very annoying ability) When he is first killed he will resurrect himself (He will have less health this time around) and will enrage, hitting for over 1000 damage on plate armor.\r\n==Abilities==\r\n[[Chain Lightning]] (Will hit everyone in front of him)\r\n[[Healing Wave]] (Uses throughout the fight, cannot be interrupted)\r\n[[Frost Nova Totem]] (Lays down throughout the fight and constantly fires off [[Frost Nova]])\r\n[[Reincarnation]] (Can resurrect himself)",},
			["Mograine"] = { content = "*[[Alexandros Mograine|Highlord Alexandros Mograine]], the Ashbringer, founder of the Scarlet Crusade.\r\n*[[Highlord Darion Mograine|Darion Mograine]], Alexandros' second son, Leader of the [[Knights of the Ebon Blade]].\r\n*[[Renault Mograine]], Alexandros' first son, Commander of the Scarlet Monastery.",},
			["Mogrin"] = { content = "A messenger for the Horde, '''Mogrin''' was entrusted with a report to be delivered to [[Thrall]] in [[Orgrimmar]], but he was ambushed by [[quilboar]]s and received a fatal wound. He found himself being helped by [[Rexxar]], a [[Mok'Nathal]]. But Mogrin was devastated, for his mission failed and he would die without honor. Rexxar, however, volunteered to deliver the message for him. Mogrin was grateful, and was about to tell Rexxar some additional information, but died before he could (Perhaps this information pertained to Proudmoore's impending invasion?).\r\n==See also==\r\n* [[Rexxar]]",},
			["Mogul"] = { content = "'''Moguls'''are the hands of the trade princes. They are entrepreneurs: men and women who run various businesses, such as deforesting, drilling, mining, and the like, throughout the world. [[Mogul Razdunk]] of the [[Venture Company]] is an example. They run numerous smaller companies.",},
			["Mogul Razdunk"] = { content = "'''Mogul Razdunk''' is the founder and ruler of the [[Venture Trading Company]].\r\nA large suit of steam armor looms threateningly, its mithril construction speaking of sharpness and speed rather than elegance. A long, mithril-and-wood rifle, its barrel the size of a [[human]] head, replaces its left arm. Its right hand is a huge, distorted claw-fist, and above it on the arm sits a perforated iron nozzle projecting from a dragon’s mouth. Arcing over the contraption’s back, like spider legs, are two spindly arms. One ends in a pair of scissor-like blades, while the other ends in a circular saw that whines as it spins. The pilot, a goblin with a mad grin, is visible through a rectangular window in the thing’s front. The goblin’s hands dart among a bewildering array of levers, buttons and hanging chains.\r\nRazdunk’s steam armor is legendary on [[Kezan]], and he prefers to intimidate and threaten his opponents into submission rather than actually attack them. When forced into combat, Razdunk begins by using his arcitech connection ability to imbue frost nova into his long rifle (opening a small hatch in the armor’s side to touch the weapon), then blasts away with it. After this tactic, he takes great joy in all of his armor’s weapons, flailing away with rifle, dragon mouth, steam fist and slicers. If Razdunk is having problems hitting his opponents, he calms down enough to make single attacks with his steam fist. If the battle looks grim, he attempts to escape with the help of invisibility.\r\nRazdunk’s familiar is a toad named Bernard.",},
			["Moh"] = { content = "'''Moh''' can be found in [[Hellfire Peninsula]] . Moh is currently being held prisoner by the nearby [[Fel orc]]s. [[Foreman Razelcraz]] would like you to save him.\r\n==Objective of==\r\n*How to Serve Goblins",},
			["Moira Thaurissan"] = { content = "Queen-Regent '''Moira Thaurissan''' (born '''Moira Bronzebeard''') is the daughter of King [[Magni Bronzebeard]] of [[Ironforge (kingdom)|Ironforge]] and the widow of Emperor [[Dagran Thaurissan]] of the [[Dark Iron clan]]. As such, she is both Princess of Ironforge as well as Empress of the Dark Irons. Since the [[Cataclysm (event)|Cataclysm]], Moira serves as the Dark Iron representative on the [[Council of Three Hammers]], Ironforge's ruling body.\r\nAn only child, Moira's relationship with her father Magni would become strained as she reached adulthood, particularly following the death of her mother [[Eimear]]. Eventually, the princess was ambushed and captured by the order of Emperor Thaurissan of the Dark Iron clan. Despite the circumstances, Moira and her captor would ultimately fall in love, and have a child — [[Dagran Thaurissan II]].\r\nKing Magni, believing these events to be mere rumors, sent a squad on a rescue mission that resulted in Emperor Dagran's death. However, Moira refused to return to her home. Having inherited the Dark Iron throne, Moira would steadily consolidate her power and that of what she considered her new people. After Magni's petrification during the Cataclysm, Moira marched on [[Ironforge]] and tried to seize power, but the attempt was thwarted by the King of [[Stormwind (faction)|Stormwind]] [[Varian Wrynn]] and the [[Alliance]].\r\nUnder Varian's suggestion, the clans established the [[Council of Three Hammers]], the new ruling body of Ironforge and the united [[Dwarf|dwarven]] people, with Moira representing the Dark Iron clan. She would continue to be heavily involved in Ironforge's politics as conflict between the clans constantly threatened civil war. Since the campaign in [[Pandaria]], the Queen-Regent has also taken a more active role in the Alliance itself, and was a prominent member of the [[Conclave]], an order of [[priest]]s that fought the [[demon]]s during the [[Third invasion of the Burning Legion|third invasion]] of the [[Burning Legion]]. Later, she was a driving force behind the Dark Irons' official entry into the Alliance during the [[Fourth War]].\r\n===Youth===\r\nMoira Bronzebead was born to King Magni Bronzebeard, King of [[Ironforge]]. While Magni did love his daughter, he had always wanted a son to rule the throne after him, and was disappointed that Moira was not the male heir he had hoped for. Nevertheless, Magni did love and raise Moira. But after her mother [[Eimear]] was killed by the [[Frostmane tribe|Frostmane troll]]s, Magni - acting on Eimear's last wish to always be there for Moira - began training Moira in the ways of the warrior to prepare her for anything. This formed a rift between the two of them, as he forced her to be something she was not.\r\nThe laws of succession for Ironforge state that Moira, having no brothers, would be the rightful heir to the throne. However, even though it would have been highly unlikely that Magni would ever dispute that claim, he still believed that a woman could not rule with the same ability as a man would be able to. His opinion on the matter was known to those he would have had some regular contact with, such as [[Advisor Belgrum]], [[High Priest Rohan]] and others, such as [[Aerin]].\r\n===World of Warcraft===\r\nYears later, when [[Magistrate Solomon]] of [[Lakeshire]] sent envoys to Ironforge to ask for aid against incursions from the [[Blackrock clan|Blackrock]] [[orc]]s, Moira volunteered to help and set out toward Lakeshire with twenty-one guardsmen, but as the group was traveling through the [[Burning Steppes]], they were ambushed and captured by [[Dark Iron dwarf|Dark Iron dwarves]]. Moira was brought to [[Emperor Dagran Thaurissan]] in [[Shadowforge City]], who intended to use her as a hostage of last resort once war began. Thaurissan believed that Magni would never consider assaulting Blackrock Mountain if it meant putting Moira in harm's way. However, Thaurissan found himself falling in love with Moira; she had a sharp wit and strong will, and was not intimidated in the slightest by her predicament. The two dwarves began to speak at length about their hopes for the future, and Thaurissan confided in Moira that he wanted to free his people from enslavement and was willing to do anything to achieve that. [[Kharan Mighthammer]], the only escorting guard to survive the kidnapping, came to believe that the Princess was presumably ensorcelled, reporting this to [[adventurer]]s that came to rescue him.\r\nKing Magni, upset that Moira was with an arch-enemy of his family, sent a team to kill Emperor Thaurissan and retrieve the presumably ensorcelled Moira back to Ironforge. However, Moira refused to come home and announced that she was pregnant; additionally, the death of her husband has left a terrible, fiery rage within her heart. She would not be heard from for a few years, estranged from her father, who still preferred to believe that she was captured and seduced via magical means rather than contemplate that she had fallen in love and married a Dark Iron of her own free will. Although devastated by the news and despite the rift between father and daughter, Magni hoped that some day Moira would return to Ironforge, and never made any move to disinherit her.\r\nAfter all of this happened, Aerin and a few other qualified women were promoted to become a part of Magni's elite guard. Aerin believed this was a result of him finally realizing that his sexist attitude had not been very fair to Moira.\r\nMoira stayed in Shadowforge after her husband's death. Hoping to further Dagran's plans to free the Dark Iron from Ragnaros' tyranny, she spread the news that the [[Ragnaros|Firelord]] was amassing an army and that Dagran Thaurissan's death only had delayed its formation. She also told of riches and artifacts hidden in his stronghold, the [[Molten Core]]. She hoped that this would attract adventurous (or greedy) heroes that would strike at the Firelord and banish him. Her plan succeeded, with her finding an unsuspecting ally in the [[Hydraxian Waterlords]], who had their own rivalry with the denizens of the Firelands and offered their own rewards for striking against Ragnaros. Soon, powerful champions broke into the Molten Core, destroyed Ragnaros' protective runes with the aid of the water elementals and banished him back to the Firelands. The Dark Iron dwarfs celebrated and many pledged themselves to Moira for orchestrating their liberation.\r\nNow, Moira turned her attention to the [[Dark Horde]] that occupied the [[Upper Blackrock Spire|Upper Blackrock Spire]]. She knew that the [[Black Dragonflight]] had entered an alliance with the orcs and conducted experiments to create [[Chromatic dragonflight|draconic monstrosities]]. Her spies made sure that word of that reached [[Durotar]], where the Horde was infuriated. Champions traveled to Blackrock and defeated both [[Warchief]] [[Dal'rend Blackhand]] and his master, [[Nefarian]], taking the head of the dragon with them to [[Orgrimmar]]. The Dark Irons had lost another enemy thanks to Moira's shrewdness.\r\n===The Shattering===\r\nIn the wake of King Magni's petrification, Moira returned to Ironforge with her infant son [[Dagran Thaurissan II]] to claim the throne. Backed by the [[Dark Iron clan]], Moira ruled Ironforge arrogantly and with an iron fist. She had the [[gryphon]]s moved out of the city and the [[Deeprun Tram]] closed, holding all the people of Ironforge hostage, including Prince [[Anduin Wrynn]], who was there as a Stormwind diplomat that would aid the dwarves in such troubling times.\r\nBeing royals, Moira and Anduin proceeded to engage in a subtle battle of political niceties and social status. Moira 'invited' (ordered) Anduin to a private official dinner to which she was intentionally late and kept him standing by his chair; to her annoyance, he in turn only bowed to her as an equal and not a ruler. During dinner, having learned the more personal details of her past from Aerin, Anduin managed to subtly trick Moira into dropping her guard for a short while in order to provoke an honest reaction from her and learn her true motives. Moira revealed that she was never ensorcelled by her husband but rather fell in love with him because he respected her, unlike her father who always wanted a son and didn't think a female was fit to rule. While Anduin privately agreed that she had been wronged, he quickly realized that Moira had not turned that into a strength, but had allowed her resentment of Magni to eat away at her.\r\nAfter Anduin escaped to [[Theramore]], King [[Varian Wrynn]] learned from Anduin of how Moira and her Dark Iron clan had taken over Ironforge and had held him hostage. Enraged, Varian and eighteen [[SI:7]] operatives embarked on a mission to liberate Ironforge and assassinate Moira. When Varian was about to execute Moira, Anduin — who had rushed back to Ironforge — convinced Varian that it would be better to guide Moira to be a better leader instead. Despite Moira being a tyrant who held the city hostage, she was still the legitimate heir to the throne and killing her would only put the succession of Ironforge into question, thus leading to more chaos and conflict that could lead into another [[War of the Three Hammers|bloody civil war]] and suck the rest of the Alliance into it. Where as if she lived; through her and her son all dwarven clans could unite. Varian slowly agreed but was also conflicted as Moira had caused so much chaos and had already threatened the safety of his son. Varian agreed to spare Moira’s life but stipulated that if Moira was to be a leader and unite the dwarves, then she’d have to earn her crown by earning her people's respect. In order to take into account the opinions of all dwarves, Varian called for the formation of the [[Council of Three Hammers]], which includes Moira's uncle [[Muradin Bronzebeard|Muradin]] and [[Wildhammer clan|Wildhammer]] [[Thane]] [[Falstad Wildhammer]].\r\n===Fire and Iron===\r\nMoira is trying in every way to integrate the Dark Iron clan into the Ironforge Kingdom. To do so, she planned to reconstruct the [[Hammer of the High King]] (even with fake pieces if need be) as a symbol of unity between the dwarven clans. [[Kurdran Wildhammer]] hesitated to give his piece but after several days of convincing all three parts were together and ready to be forged. The next day, Moira and [[Drukan]] found Kurdran and [[Sky'ree]] during a walk. Drukan feared the gryphon and even disrespected her but Moira convinced her advisor to apologize. Moira then thanked Kurdran for giving the final part of the hammer and left. After Sky'ree's death, Kurdran was shocked and took the Wildhammer piece. Moira saw this and the two started to argue. Kurdran then realized that she also tried to focus estrangement on the Wildhammer clan in order to shift the Bronzebeard dwarves' alienation away from the Dark Irons. During the public ceremony to reforge the Hammer of the High King, Kurdran smashed the Wildhammer piece, justifying that the dwarves' unity could not be based on a physical artifact that could be broken apart one day, and they should begin anew with a clean slate. Muradin gladly agreed to this, and Moira having been politically outmaneuvered, was forced to follow suit, having also the Dark Iron piece of the hammer smashed.\r\n===Blood in the Snow===\r\nOne day, [[Varian Wrynn|King Varian]]'s [[SI:7|scouts]] had discovered that [[Zandalar tribe|Zandalari trolls]] threatened the [[Ironforge|dwarven capital]] by rallying the [[Frostmane tribe|Frostmane trolls]] against them. Surely, the king thought, if he helped them with their [[troll]] problem, they would give him more troops for his campaign against the [[Horde]]. But what the King did not realize is that the dwarves did not trust one another. When Varian sought the help from the [[Council of Three Hammers]], both [[Muradin Bronzebeard|Muradin]] and [[Falstad Wildhammer|Falstad]] declined to offer aid in Ironforge’s defense for they feared that if they left to fight the Frostmane trolls, the Dark Irons would take advantage of their absence to defeat the remaining clan and take over Ironforge. Frustrated, Varian argued that if no one would help, then Ironforge will fall under siege. Only Moira offered aid, stating that the Dark Irons will prove their loyalty to the Council, [[Ironforge]], and the [[Alliance]] in the defense of Ironforge. And so Moira, her [[Forgeguard|personal guard]] and the High King set out in the snow to save the city, leaving the others to think about their actions.\r\nWhen they arrived at [[Shimmer Ridge]], they discovered that their enemies were using an unnatural storm to prevent their forces from advancing on them. At Varian's request, Moira led her personal guard against the enemy troll village once the king's champions stopped the magical storm protecting Shimmer Ridge. After rescuing the surviving mountaineers and slaying the elemental that the trolls were satiating with blood sacrifices to elicit the unnatural storm, the king's champions regrouped with Moira’s [[Forgeguard]] and together their forces slew the Zandalari leader and captured the Frostmane village.\r\nIn the aftermath of the battle, Varian commended Moira and the Dark Irons on their victory, even stating that the Bronzebeards and Wildhammers will regret not having been there to share in her glory. Moira however, humbly stated that her intention was to protect and impress, not to shame; to which Varian acknowledged that she accomplished just that. Both returned to Ironforge to announce her victory to the Council. On their return, the other dwarven leaders were ashamed of their behavior and vowed never again to allow fear or distrust to cloud their judgment. Free to trust one another, all three dwarven leaders pledged their full strength to the Alliance cause.\r\n===War Crimes===\r\nMoira, alongside other Alliance leaders, received a letter from [[Xuen]] inviting them to the trial of [[Garrosh Hellscream]]. She traveled to [[Pandaria]] and [[Jaina]] noticed her arguing with a pandaren about the cart they were traveling by to the [[Temple of the White Tiger]]. She was present during the trial itself and a vision from the past, the one when Moira was almost executed by Varian, was shown.\r\n===The Jade Hunters===\r\nMoira and the other members of the council would blackmail [[Fendrig Redbeard]], [[Fenella Darkvire]] and [[Carrick Irongrin]] to form a team and help rebuild the Jade Serpent statue.\r\n===Fault Lines===\r\nFour years after [[Magni Bronzebeard|Magni]]'s petrification, Moira was asked by [[Muradin Bronzebeard|Muradin]] and some of the [[priest]]s to talk to her petrified father, as she often did when times were trying, in the hopes that it would wake him up. Moira herself saw it as a fool's errand and scolded her father, saying that the thought of his daughter sitting the throne of Ironforge would eat him up inside and that he never gave her a chance to prove herself due to being female. However, to the vast surprise of both Moira and [[Advisor Belgrum]], Magni suddenly awoke with a mighty crash as a living statue made of diamond. Though the Council of Three Hammers were worried about what Magni's return would mean for the political stability of Ironforge, Magni replied by saying that he had not come to reclaim his crown, but to offer a warning about the [[Burning Legion]]'s return. He asked his daughter to see him off and talked with her outside the gates of Ironforge. He revealed that he had watched her progress and develop into a leader since her return, and unlike what she had thought earlier that day, that he couldn't be prouder of what she'd become. Saying that he had failed her as a father and hoped she would give him another chance to be a family again, the former king headed off to warn the rest of the [[Alliance]], wanting to give Moira time to think about it and letting her know that his connection to the earth would allow him to watch over her. As Moira watched him walk away, she began to cry.\r\n===Before the Storm===\r\nAs a member of the [[Council of Three Hammers]], Moira welcomed King [[Anduin Wrynn]] who had gifted [[Ironforge]] ten wagons of [[:Barley]], being the primary ingredient of dwarven brews. Ironforge treated Anduin and his entourage to a feast to celebrate this gift. By the time dessert was being served, Moira, Anduin, and her son [[Dagran Thaurissan II]] strolled through [[Old Ironforge]] to help them digest their meal. As they walked, Anduin reminisced about his last visit to Ironforge and thanked the Council of Three Hammers for attending his father's funeral; especially Moira since the last time [[Varian Wrynn|Varian]] and Moira met in Ironforge, he tried to kill her. Moira made light of the past event and explained that she and Varian made peace with that moment a long time ago and stated that they even grew to respect each other. She also admitted that if she had been in Varian's position and Dagran had been held hostage, she'd probably have done the same thing. Both Moira and Anduin spoke of their fathers, how the Council of Three Hammers are now much more harmonious, and [[Aerin Stonehand]]'s influence on Anduin's swordsmanship. As Anduin and Moira had a pleasant conversation while Dagran explored [[Old Ironforge]], a messenger told them that [[Magni Bronzebeard]] has returned to Ironforge and required a conference with the both of them. Moira and Anduin found Magni in the [[Library (Ironforge)|Library]] section of the [[Hall of Explorers]], conversing with [[High Explorer Muninn Magellas]] and [[Prophet Velen]], while [[Falstad Wildhammer|Falstad]], [[Muradin Bronzebeard|Muradin]], [[Gelbin Mekkatorque]], and [[Captain Tread Sparknozzle]] stood beside them listening intently. Magni explained that [[Azeroth]] is wounded, and that they must set to healing her or all will perish. Thus Magni has been recruiting priests and other healers for that express purpose. Moira proposed that they reach out to the [[Conclave]] to aid in this endeavor. Anduin also showed the council of Alliance leaders the shard of [[:Azerite]] he had and explained its relevance to Azeroth and technology. With their purpose clear, the leaders of the Alliance set out on their tasks. Before Moira left, however, she introduced Magni to his grandson.\r\nLater on, Anduin, Velen, and Moira portaled to [[Netherlight Temple]], where Moira recruited the [[Conclave]] in their endeavors to heal Azeroth from [[Sargeras]]' destruction. Anduin also told them about Azerite and urged them to recruit other healers such as [[shaman]] and [[druid]]s to their mission. After accomplishing their task, Anduin gave Moira his shard of Azerite to deliver to Mekkatorque, while he made preparations to return to [[Stormwind]].\r\n==Abilities==\r\nThe Imperial Seat, Blackrock Depths\r\nIronforge\r\n*'''Heal''' - Calls upon Holy magic to heal an ally.\r\n*'''Mind Blast''' - Inflicts Shadow damage to an enemy.\r\n*'''Renew''' - Heals an ally every 3 sec. for 15 sec.\r\nBlood in the Snow\r\n*'''Moira's Majesty''' - Periodically healing all friendly units within 10 yards.\r\n==Quests==\r\n*[[Demanding Answers]] \r\n*[[Seize the Ambassador]] \r\n===Battle for Azeroth===\r\n*[[Heritage o' the Dark Iron]] \r\n===Removed===\r\n*[[The Fate of the Kingdom]] \r\n**[[The Princess's Surprise]] \r\n*[[The Royal Rescue]] \r\n**[[The Princess Saved?]] \r\n===Battle for Azeroth===\r\nGreetings\r\n*You address the Queen-Regent of the Dark Iron Clan.\r\n*Let's get down to business, then.\r\n*The Dark Iron Clan WILL have the respect it is due!\r\n*Well? I'm listenin'.\r\n*Best mind yer manners in the presence of a Queen.\r\n*The mountain lends us its strength.\r\n*The Alliance has need of our sorcery, as well as our strength.\r\nPissed\r\n*Well, at first, I was irritated by all that \"YAAAAAS QUEEN\" nonsense, but, eh... I'll permit ye to carry on with it.\r\n*Well, of COURSE I've got a complicated relationship with my da! Hard enough to get along with any parent, let alone one made out of freakin' DIAMOND!\r\n*Go ahead. Make a short joke. We'll see how well you get along without yer kneecaps!\r\n*My people live inside a volcano. Keep pokin' me, and I'll show ye how a Dark Iron erupts!\r\nFarewell\r\n*''I dismiss ye.''\r\n*''Ye may take yer leave.''\r\n*''Well, go on. I've got work to do.''\r\n*''The Dark Irons WILL claim their rightful place in this world.''\r\n*''May the Black Anvil watch over ye.''\r\n====Stormwind Embassy====\r\nIn 8.3.0\r\nThe Alliance an' Horde have both suffered terribly in this war, an mistakes were surely made on both sides.\r\nWhat matters now is how we move forward! Do we learn somethin' from all o' the bloodshed an' loss, or do we keep on repeatin' the past?\r\nIn 8.0.1\r\nThe [[Alliance]] needs strength. Unity. The king's plan tae bring in fresh blood is a good one.\r\nAs fer the [[Dark Iron clan]], the Alliance needs us now more than ever.\r\nIf only I can show the rest o' me clan how much we need allies ourselves, perhaps we can finally all agree that we are indeed already part o' the Alliance.\r\nIn 7.3.5\r\nThe Alliance needs strength. Unity. The king's plan to bring in fresh blood is a good one.\r\nBut I can't help thinking of my own Dark Iron clan. Of the fractures that divide us.\r\n==In Hearthstone==\r\nMoira in the against [[Dagran Thaurissan|Emperor Thaurissan]], the last boss of the Blackrock Depths wing in the ''[[Hearthstone: Blackrock Mountain|Blackrock Mountain]]'' adventure for ''[[Hearthstone (game)|Hearthstone]]''. The boss fight revolves around defeating Thaurissan while keeping Moira alive; if she dies at any point during the fight, Thaurissan will deal 30 damage to the player's hero at the start of his next turn, which in most cases means the player's instant death.\r\n==Notes and trivia==\r\n*Her eye color is green.\r\n*Moira is the youngest of the Three Hammers.\r\n*Unlike most dwarves, Moira prefers wine over beer.\r\n*One of the possible default names for [[destroyer]]s constructed at the [[Lunarfall Shipyard]] is ''[[Moira's Hammer]]''.\r\n*In Magni's nightmare caused by the [[Emerald Nightmare]], the king led a team to Blackrock Depths to free Moira and kill Dagran. While he accepted that her son would be born, he would banish him from the kingdom of Ironforge. Upon hearing this, Moira stabbed Magni and revealed that \"Fenran\" was only meant to watch over the throne until her new baby was born, whom she revealed to be the child of Ragnaros.\r\n*Moira is voiced by [[Elle Newlands]]. Some have commented that Moira's Scottish accent sounds fake, even though Newlands is actually Scottish herself.\r\n**Moira's accent has been inconsistently depicted between ''World of Warcraft'' and its literature. In-game, she has consistently spoken with a thick Scottish accent since she first received unique voice acting in ''[[World of Warcraft: Cataclysm|Cataclysm]]''. However, in ''[[The Shattering: Prelude to Cataclysm|The Shattering]]'', ''[[Fire and Iron]]'', and ''[[The Jade Hunters]]'', she speaks with no noticeable accent at all, in contrast to other dwarven characters. In ''[[War Crimes]]'', it is mentioned that by the time of [[Garrosh Hellscream]]'s trial, Moira had only recently begun taking on the more typical accent of her people. In ''[[Before the Storm]]'', her dialogue is still not written with any noticeable accent (for instance, she says \"you\" rather than \"ye\"), though she has apparently started including some typical dwarven phrases like \"wee\" and \"aye\" in her speech.\r\n*Due to storyline issues with Blackrock Depths, Moira is the only racial leader that can be killed by her own race and faction, discounting the echoes in [[End Time]].\r\n*Moira's headpiece is identical to the ones that [[Muradin Bronzebeard]] and [[Halduron Brightwing]] wear.\r\n*In the original quest lines, [[Thrall]] sent [[Horde]] adventurers to deal with the Emperor Dagran Thaurissan and help the captured princess. However, the Horde quests were later rendered non-canon, as ''The Shattering'', the ''[[World of Warcraft: Ultimate Visual Guide|Ultimate Visual Guide]]'', and ''[[World of Warcraft: Chronicle Volume 3|Chronicle Volume 3]]'' only mention Dagran being killed by Magni's team.\r\n*The ''Ultimate Visual Guide'' lists Moira as '''Moira Bronzebeard Thaurissan'''.\r\n*Moira's hair style and the outfit that she wore during the classical Blackrock Depths instance was likely inspired by Princess Leia from ''Star Wars Episode VI: The Return of the Jedi''.\r\n*Data exists for Moira in ''[[Heroes of the Storm]]''. She is currently the only member of the Council of Three Hammers to not be a playable character in that game.\r\n==Video==\r\n*",},
			["Mojo Stormstout"] = { content = "'''Mojo Stormstout''' is a famous [[Pandaren]] who is very knowledgeable about Warcraft information. He has compiled everything from the [[Third War]] and its aftermath in his . This guide includes military strategy and comprehensive taxonomy of the Warcraft Universe's inhabitants. He is probably related to [[Chen Stormstout]].\r\nHis name is most likely a reference to the StarCraft hero, Mojo Stormscout.\r\n===Cartography===\r\n'''Mojo Stormstout''' is an avid cartographer. He has many maps of battle grounds, stretching from [[Azeroth]] to [[Outland]].\r\n===Taxonomy===\r\n'''Mojo Stormstout''' is a life-form taxonomist. He has compiled a database of living creatures on [[Azeroth]], including [[Northrend]], the [[Maelstrom]] and [[Ashenvale]]. His collection of data extends to [[Outland]], including the [[Black Citadel]] ([[Black Temple]]), as well. He has studied the movements, magic and attributes of most creatures. He also has vast knowledge of the taxonomy of the life-forms of the [[Scourge]], [[Alliance]] and the [[Horde]] and others.\r\n===Military Tactics===\r\n'''Mojo Stormstout''' is a military tactician. He knows the best military strategies for the armies of the [[Scourge]], [[Alliance]] and the [[Horde]]. In particular, he knows different tactics based on the opposing force.",},
			["Mok'Morokk"] = { content = "#redirect [[Overlord Mok'Morokk]]", redirect = "Overlord Mok'Morokk",},
			["Mok'nathal"] = { content = "The '''Mok'Nathal''' (\"The Sons of [[Nath]]\") is a clan originally from the planet [[Draenor]]. The clan consists of mostly [[half-ogre]]s, but apparently has members of other races as well. The clan is near defunct, and apparently [[Rexxar]] was one of the only remaining left on [[Azeroth]]. They have a last remaining spot in [[Outland]] - in [[Mok'Nathal Village]] in eastern [[Blade's Edge Mountains]].\r\nIt had been thought that mok'nathal half-ogres had been extinct on Azeroth, but after Rexxar's exploits on Azeroth, mok'nathal are showing up again. There is only a hundred to two hundred that exist in the world.\r\n===In of World of Warcraft===\r\n* [[Braagor]]\r\n* [[Erool]]\r\n* [[Grikka]]\r\n* [[Krugash]]\r\n* [[Leoroxx]]\r\n* [[Sky-Master Maxxor]]\r\n* [[Ogrin]]\r\n* [[Ragar]]\r\n* [[Rexxar]]\r\n* [[Ruka]]\r\n* [[Matron Varah]]\r\nAll of these people, with the exception of Rexxar, can be found in [[Mok'Nathal Village]] in the [[Blade's Edge Mountains]]. Rexxar is located at nearby [[Thunderlord Stronghold]].\r\n===Out of World of Warcraft===\r\nOther named half-ogres who may or may not be Mok'Nathal include Mag Bearmaul, [[Tagar Bearclaw]], Gorsh Talonfang, Maxx Rocmane, Gaz Boartusk, Mok Rocksnout, and Gish Eagle Eye. ''They are [[Beastmaster]]s that can be hired from Mercenary camps in The Frozen Throne. Horde player's guide confirms them to be half-ogres, and they would be mok'nathal by use of orcish terminology, although not necessarily members of the Mok'Nathal Clan.''\r\n==History==\r\nHow the Mok'Nathal came to Azeroth at all is unknown. It isn't likely that they were brought by [[Gul'dan]]. Some, like Rexxar, might have been in the ranks of the [[Horde (pre-Thrall)|Horde]] but were not in large numbers so went unnoticed.\r\nThe novel ''Cycle of Hatred'' Rexxar is described to as \"the last of the Mok'Nathal Clan\", if further says that he was \"Born of orc and ogre blood both, as most of his now-defunct clan...\"(DeCandido). This can imply several things, that he is one of the last of the Mok'Nathal clan, and/or he may have been one of the last half-ogres of the clan, though maybe not one of the last half-ogres. [[The Burning Crusade]] references the Mok'Nathal Clan as well, such as in [[Mok'Nathal Clan Ring]].\r\n==Name Meaning==\r\n[[Leoroxx]], Rexxar's father, states that \"being born a half-breed does not make you Mok'Nathal\", implying that being Mok'Nathal is not a racial designation, but rather a philosophy. It may also be related to the fact that not all Mok'Nathal are half-ogres.\r\nThe Horde Player's Guide implies that \"mok'nathal\"(lower-case) is the Orcish term and honorific for \"half-ogre\", while half-ogre is the [[Common]] name for the race.\r\n==Languages==\r\nMok'Nathal usually speak Common or Low-Common, the language of their ogre parents. Their ogre progenitors used to be part of the Horde, and some learn the languages of those cultures.",},
			["Mok'Nathal Clan"] = { content = "#REDIRECT [[Mok'nathal]]", redirect = "Mok'nathal",},
			["Mok'Nathal Clan Ring"] = { content = "==Source==\r\nDrops from [[Nazan]] in the [[Hellfire Ramparts]] wing of [[Hellfire Citadel]] on normal difficulty.",},
			["Mok'Nathal Village"] = { content = "'''Mok'Nathal Village''' is a settlement situated in the eastern [[Blade's Edge Mountains]] and inhabited by the [[Mok'Nathal Clan]] - [[half-ogre]]s of brownish hue wearing distinctive shoulder armor. The village is guarded by Mok'Nathal Hunters and has several notable characters - along them [[Leoroxx]], father of the Champion of the Horde, [[Rexxar]]. A couple of tamed clefthooves can be seen around. There is an innkeeper, a leatherworking supplies merchant, some other vendors and a Grand Master [[Leatherworking|Leatherworker]], [[Grikka]]. The village hosts a couple of buildings and a watch tower and its inhabitants are friendly to Horde members. A flight path can be found here as well.\r\n==Quests==\r\n* Mok'Nathal Treats\r\n* The Softest Wings\r\n* Silkwing Cocoons\r\n* The Stones of Vekh'nir\r\n** Trial and Error\r\n** Ruuan Weald\r\n** Understanding the Mok'Nathal\r\n** Since Time Forgotten...\r\n** Slay the Brood Mother\r\n** The Totems of My Enemy\r\n** Spirit Calling\r\n** Gather the Orbs\r\n** Inform Leoroxx!\r\n*** There Can Be Only One Response\r\n===Flight===\r\n [[Thunderlord Stronghold]]\r\n [[Area 52]]",},
			["Mok'thardin's Enchantment"] = { content = "==Objectives==\r\nFar Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a [[Pristine Tigress Fang]]. \r\n* Shadowmaw Claw (8)\r\n* Pristine Tigress Fang\r\n== Description==\r\nThe power of the jungle's magic must be realized and then harnessed by the [[Horde]]. My rituals have proven successful so far. I can cast very powerful enchantments. For you, brave <class>, I shall make a special item indeed.\r\nBring to me some Shadowmaw Panther claws along with a Tigress fang. Not just any fang will do. It must be in pristine condition.\r\nThe beasts lurk throughout the jungle but you will find some close by, just across the river from Mizjah Ruins to the southeast. \r\n== Progress==\r\nWhat news do you bring? \r\n== Completion==\r\nYour knowledge of the jungle is strong, <name>. These specimens will be perfect. I will thank the spirits for sacrificing such fine beasts for the cause of the [[Horde]]. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*2150 [[XP]] (or 13 silver 20 copper at level 70)\r\n*250 [[reputation]] with [[Orgrimmar]]",},
			["Mokasa"] = { content = "'''Mokasa''' is an orc female located at [[Stonebreaker Hold]] in the [[contested]] territory of [[Terokkar Forest]].",},
			["Mokk the Savage"] = { content = "'''Mokk the Savage''' is a level 44 [[named]] [[gorilla]] found in [[Stranglethorn Vale]]. [[Witch Doctor Unbagwa]] can summon Mokk using [[Gorilla Fang]]s. [[Fin Fizracket]] wants to eat Mokk's heart to cure his illness.\r\n==Stats==\r\n*'''Damage''': 72-96\r\n*'''Armor''': 2557\r\n*'''Cannot be Tamed'''\r\n==Objective of==\r\n*Stranglethorn Fever\r\n==Loot==\r\n*Heart of Mokk ''(Quest Item)''",},
			["Moktar Krin"] = { content = "'''Moktar Krin''' is a level 35 [[quest giver]] located at [[Ironstone Camp]] in the [[contested]] territory of [[Thousand Needles]].\r\nHe starts the quest The Swarm Grows (3)\r\nSee [[List of Thousand Needles NPCs]].",},
			["Mold Foundry"] = { content = "The '''Mold Foundry''' is located inside [[Blackrock Depths]], and is accessible from the [[Chamber of Enchantment]]. It leads on to the [[Summoners' Tomb]]. This is where the [[Dark Irons]] forge their [[golem]]s.\r\nThis area is small, filled with small groups of elite golems and non-elite dark iron dwarves. The rare spawn [[Panzor the Invincible]] will spawn here occasionally.",},
			["Molok"] = { content = "One of the gryphon rider dwarves under the command of [[Falstad]] guarding Hasic. He helped to defeat a dragon that was attacking [[Rhonin]] and [[Vereesa]], although he lost an axe during the fight. He got into a quarrel with Rhonin when the latter insisted he fly him to [[Khaz Modan]], but Vereesa convinced Falstad to take them. He rode with Rhonin, and during the travel the group ran into a patrol of dragon riders from the [[Dragonmaw Clan]]. Rhonin forced Molok to alternate between helping their allies and trying to make it to the shoreline of Khaz Modan. Molok died when he and Rhonin were knocked off their mount by a dragon. Falstad and Molok were called brothers.",},
			["Molsen Farm"] = { content = "'''The Molsen Farm''' is another of the farms of [[Westfall]] that have been taken over by the [[Defias Brotherhood]]. Now, the deadly mechanical [[harvester]]s terrorize the fields and the Defias have claimed the farmstead as their own.",},
			["Molten Armor"] = { content = "Born of the belief that \"the best defense is a good offense\", '''Molten Armor''' is a [[mage]] spell that both imbues the caster with greater offensive power and protects him by harming his assailants, as well as greatly increasing the possibility of a critical strike. It is a self-buff armor spell. Molten Armor was introduced in the [[Burning Crusade]] expansion.\r\n==Notes==\r\nUnlike the damage caused by [[damage shield]]s, Molten Armor's damage is considered [[direct damage]], and as such can crit and can proc both talent effects like [[Impact]] and item effects like the one of [[Mark of Defiance]].\r\n==Talent improvements==\r\n[[Impact]]: The chance to stun is applied to this damage as well. At 5/5, anyone attacking you essentially has a 10% chance to be stunned, giving you time to throw a [[Scorch]] in unmolested, or a head start on getting away.\r\nThis spell benefits from all other talents that increase damage and critical strike chance for all spells and fire spells. This spell does not trigger the [[mana]] replenishment effect from [[Master of Elements]], however.\r\nFire vulnerability from [[Curse of the Elements]] will also increase the damage dealt by this effect.\r\nAs of [[patch 2.3]] Molten Armor will no longer trigger [[Ignite]]. This is significant because an unexpected DoT from this talent could cause problems when trying to [[polymorph]] a mob.\r\n==Tips and tactics==\r\nThe last acquired armor spell is generally considered one of the best. The large increase to crit chance is unique, and by far the best offensive augmentation available from the armor spells. For solo and PvP, this alone makes the spell worth taking. However, in group PvE, it is sometimes better to use [[Mage Armor]] as the longevity increase from the mana regeneration while casting effect outweighs the damage increase.\r\nThe damage to attackers may not seem like a lot, but it quickly adds up if you are being attacked by a rogue or other fast attacker. It's also wonderful for taking multiple mobs at the same time. The damage can crit and is affected by talents like [[Impact]], so additional effects can be triggered by it. Especially when combined with [[Molten Shields]], it will prove a very good defensive combination, as Molten Shields extends the damage caused by Molten Armor to ranged and spell attacks, resulting in a 10% chance to stun an enemy on any attack.\r\nWhile Fire Mages and most Arcane Mages use this armor for PvP, it is suggested that Frost Mages use Ice Armor as Frostbite and Ice Lance can be deadly to melee classes.\r\nIt is unclear whether or not this buff can proc while the mage is sitting: this has been included in numerous patches.",},
			["Molten Belt"] = { content = "'''Molten Belt''' is a [[Leatherworking]]-crafted belt that is suitable for classes that wear both leather armor and mail armor. This is a nice belt for [[Rogues]] if they don't have a full set. [[Hunters]] also like this belt due to the high [[Agility]].\r\n==Source==\r\nMolten Belt is crafted by [[Leatherworking|Leatherworkers]] with a skill level of 300.\r\nThe components are:\r\n*2 [[Fiery Core]]\r\n*7 [[Lava Core]]\r\n*6 [[Essence of Earth]]\r\n*4 [[Cured Rugged Hide]]\r\n*4 [[Ironweb Spider Silk]]\r\nThe [[pattern]] is sold by [[Lokhtos Darkbargainer]] in [[Blackrock Depths]]. You must have a Revered reputation with the [[Thorium Brotherhood]] to purchase this pattern.",},
			["Molten Core"] = { content = ":''Were you looking for [[World of Warcraft: The Molten Core]]?''\r\n----\r\n'''Molten Core''' is located beyond [[Blackrock Depths]], in the deepest part of [[Blackrock Mountain]]. It is the home of the Firelord [[Ragnaros]] - one of the four elemental lieutenants of the Old Gods - and his elemental minions. Molten Core is a 40-man raid, and requires \"attunement\" to enter (see [[|Notes]] for info about how to avoid the need for completing the quest). The one-step attunement quest is called [[Quest:Attunement to the Core|Attunement to the Core]], and requires a run through almost to the end of [[Blackrock Depths]] to complete.\r\n==History==\r\nThe Molten Core was created during the [[War of the Three Hammers]], more than 300 years ago. Near the end of the war, Thaurissan, the leader of the Dark Iron Dwarves, sought to summon a powerful fire elemental to defeat the combined forces of the Bronzebeard and Wildhammer clans. He was more successful than he could have imagined, as he released Ragnaros the Fire Lord from millennia of captivity under the Redridge Mountains.\r\nRagnaros destroyed the city of Thaurissan (named after the Dwarven leader) and created the volcano of Blackrock Spire. He dwells there to this day with his elemental servants and the enslaved remnants of the Dark Iron dwarf clan.\r\n''The Molten Core lies at the very bottom of [[Blackrock Depths]]. It is the heart of [[Blackrock Mountain]] and the exact spot where, long ago in a desperate bid to turn the tide of the dwarven civil war, Emperor [[Thaurissan]] summoned the elemental [[Firelord]], [[Ragnaros]], into the world. Though the firelord is incapable of straying far from the blazing Core, it is believed that his elemental minions command the Dark Iron dwarves, who are in the midst of creating armies out of living stone. The burning lake where Ragnaros lies sleeping acts as a rift connecting to the plane of fire, allowing the malicious elementals to pass through. Chief among Ragnaros' agents is [[Majordomo Executus]] - for this cunning elemental is the only one capable of calling the Firelord from his slumber.''\r\n==Overview==\r\nOn release, Molten Core was the only 40 man instance in the game, thus Ragnaros was the first \"game end boss\". With the advent of [[Blackwing Lair]], [[Ahn'Qiraj]], [[Naxxramas]], and the Burning Crusade, defeating Ragnaros has long since ceased to be the pinnacle of raid achievement. However, prior to the Burning Crusade, slaying him was still considered a very important step in raid progression before engaging in more challenging content. It is the first level 60 raid encounter which requires a concerted effort in acquiring massive amounts of a particular statistic (in this case, fire resistance). Moreover, the encounter is the first one to demand the extensive use of consumables, at least in the learning process and in the first few kills. As such, it was once a very important stage in the evolution of a raiding guild.\r\nMolten Core poses an interesting problem to advanced raiding guilds. Killing Ragnaros requires a full Molten Core clear, all 9 other bosses must be down in order to be able to summon him. On one hand, for guilds deep into more challenging instances, the time required to clear MC (3 hours for a reasonably mature guild) is wasteful and inhibits raid progression. On the other hand, many guild members (especially recruits) will need to farm Ragnaros for the [[Tier 2]] pants he drops. For many classes, better pants won't be found until deep into AQ40 or Naxxramas. Exacerbating this is the fact that trash mobs in MC respawn fairly quickly, so the instance must be run (more or less) all in one night.\r\nThus, while Molten Core helps the itemization of the raid significantly, the time cost required to farm Ragnaros often hurts raid progression. Guilds commonly struggle with balancing these competing goals. Usually guild members are very happy when they are finally able not to run MC any more, especially since most of the encounters only require large amounts of DPS.\r\nHowever, as of the [[Burning Crusade]] expansion, this is no longer the case, as this instance is largely obsolete with the introduction of Outland green items with superior stats to most of Tier 1. (And the fact that most higher instances are lower than 40 man, making them a much more practical way to go.) With this in mind, the future of this instance is debatable. In its current state it looks only set to gather dust as level 60s visit the Auction House to pick up their gear. \r\nHowever, the Lava Cores that drop are materials for the best scope in the game, and some guilds still run it to obtain the materials required to craft Sulfuras, Hand of Ragnaros.\r\n==Prerequisites and Quests==\r\nWhile technically there are no prerequisites to enter Molten Core through its entrance at the bottom of Blackrock Depths, every Core raider will want to complete the [[Quest:Attunement to the Core|Attunement to the Core]] quest to enable the shortcut at the bottom of Blackrock Mountain. This quest is given at level 55 by [[Lothos Riftwaker]] who is located just outside The Quarry, on the way to [[Blackrock Depths]]. Once attuned you can access Molten Core by talking to Lothos again. When dead (as ghost) you also have the possibility to jump into the lava near Lothos. This can also be done by living players if they have a way to slow fall, or by jumping first onto the small ledge in the pillar on the right as you enter the main chamber of Blackrock Mountain, healing, then jumping down, back toward the wall of the lava pit, to cover the remaining distance to the platform below. \r\nThere are very few quests that involve the Molten Core. The only significant quest chain is the [[Hydraxian_Waterlords|Hydraxian Waterlords]] chain, which can be started by a visit to [[Hydraxian Waterlords|Duke Hydraxis]] off the coast of Azshara. Completing this quest chain will require killing one of each of the trash mobs in the Core, and then defeating the four \"naga bosses\" in Molten Core (Lucifron, Gehennas, Shazzrah, and Sulfuron Harbinger). In addition, all the trash mobs and bosses in Molten Core provide Hydraxian Waterlord reputation. The final reward options for this quest chain are Tidal Loop or Ocean's Breeze, both rare rings with high Fire Resistance.\r\nBefore Ragnaros can be summoned, the raid must defeat Majordomo Executus. Majordomo Executus will only appear if the raid douses the runes that are located near certain bosses in the Molten Core. Dousing the runes requires a vial of [[Aqual Quintessence]], which can only be acquired by speaking with Duke Hydraxis. Once a player reaches Revered status with the Hydraxian Waterlords, Hydraxis will provide a vial of [[Eternal Quintessence]], which can be used once every hour without a trip back to Azshara.\r\n===Raid Mechanics===\r\nMolten Core is a [[raid]] instance. This means that it is on a strict timer schedule, which resets once a week, and once a character has been \"saved to the instance\" by killing a boss, that character cannot enter a different instance of Molten Core that week.\r\nEach of the bosses in Molten Core has a very specific [[Molten Core Loot|loot table]], which includes the [[Tier 1]] armor pieces as well as a number of other epic-quality items. In addition, the trash mobs in Molten Core provide Fiery Cores, Lava Cores, and Core Leather, which can be used with recipes earned at high levels of [[Thorium Brotherhood]] reputation to craft epic armor and weapons. It is generally the case that a raid progressing through Molten Core will use these Cores to craft Fire Resistance armor, which will allow the melee DPS of the raid to survive the final encounters with Majordomo Executus and Ragnaros.\r\n==Resources==\r\n* [[Core Leather]] (Skinning [[Ancient Core Hound]]s, 310 skinning required - use [[Finkle's Skinner]] from [[The Beast]] in [[Blackrock Spire]] or [[Zulian Slicer]] from [[High Priest Thekal]] in [[Zul'Gurub]], or go to Outland and learn Master Skinning.)\r\n* [[Dark Iron Deposit]]\r\n* Fiery Core\r\n* Lava Core\r\n* Sulfuron Ingot\r\n==Dungeon Denizens==\r\n*[[Molten Giant]]\r\n*[[Molten Destroyer]]\r\n*[[Firelord]]\r\n*[[Lava Annihilator]]\r\n*[[Ancient Core Hound]]\r\n*[[Lava Surger]]\r\n*[[Flame Imp]]s\r\n*[[Core Hound Pack]]\r\n*[[Lava Pack]]\r\n**[[Lava Reaver]]\r\n**[[Lava Elemental]]\r\n**[[Flameguard]]\r\n**[[Firewalker]]\r\n===Bosses===\r\n*[[Lucifron]]\r\n*[[Magmadar]]\r\n*[[Gehennas]]\r\n*[[Garr]]\r\n*[[Baron Geddon]]\r\n*[[Shazzrah]]\r\n*[[Sulfuron Harbinger]]\r\n*[[Golemagg the Incinerator]]\r\n*[[Majordomo Executus]]\r\n*[[Ragnaros]]\r\n==Guides==\r\n* How to solo [[How to solo Attunement|Attunement to the Core]]\r\n* including all bosses\r\n* \r\n==Loot==\r\nAll pieces of the [[Tier 1]] sets, and much more Epic quality gear.\r\nSpecial profession recipes & special crafting items, e.g. Core Leather.\r\nFor more details see: [[Molten Core Loot]]\r\n==Notes==\r\nWith the [[warlock]]'s [[Ritual of Summoning]] ability anyone can be summoned to the instance, no matter whether he/she is completed the \"attunement\" quest or not. So at least 2 people and a warlock (with MC \"attunement\") is able to summon the whole raid group right into the instance.",},
			["Molten Core (TCG)"] = { content = "The second World of Warcraft Raid Deck, named Molten Core.\r\n===Card Totals===\r\nTotal Cards: 89\r\n* 30 Treasure Cards\r\n* 10 double-sided oversized Boss cards\r\n* 7 Rune cards\r\n* 15 Main deck card (3 copies in 1 basic Raid Deck)\r\n* 8 minion cards (3 copies in 1 basic Raid Deck)\r\n* 13 Ragnaros deck cards (2 in each Raid deck)\r\n* 6 ally tokens. Double-sided with multiples in each deck\r\n===Treasure Pack Cards===",},
			["Molten Core Loot"] = { content = "#REDIRECT [[Molten Core loot]]", redirect = "Molten Core loot",},
			["Molten Destroyer"] = { content = "==Background==\r\nA much bigger and harder version of [[Molten Giant]]. These guys start to show up in pairs before [[Gehennas]] and should not be taken lightly. \r\n==Abilities==\r\n* Hits tank for 700 - 800 damage.\r\n* Massive trample - 1000 damage AOE attack\r\n* Smash Attack - 1000 - 1100 damage against a tank.\r\n* Knock down - Knocks a target down for a few seconds.\r\n==Strategies==\r\nIf it is paired with a Molten Giant, kill the Giant first. Keep the Destroyer away from the main group. Newer groups that can't take the damage and afford the healing should do ranged damage only and keep the melee out of the fight.",},
			["Molten Giant"] = { content = "'''Molten Giants''' are a type of fiery and molten [[mountain giant]]s found in the [[Molten Core]]. [[Molten giant]]s are huge fiery creatures that reside in the darkest hottest places of Azeroth and the [[Firelands]] of the [[Elemental Plane]]. Their skin is a deep red, and they are affiliated with fire elementals, which often coexist with them. Their largest numbers can currently be found in Molten Core. \r\nFirst two mobs in the instance. These always come in pairs, and are impossible to pull alone. As you progress through the [[Molten Core]], Molten Giants will gradually be replaced with [[Molten Destroyer]]s, starting with one Destroyer and one [[Giant]], and eventually two Destroyers. The easiest way to deal with them is to put a tank on each and separate them so their stomps do not hurt the same group. Finish one then the other.\r\nThis mob spawns in pairs. The giants are very tough beasts with high HP.\r\n==Abilities==\r\n* Normally hits a tank for 600 - 800 damage.\r\n*\r\n==Strategy==\r\nEach giant has a tank with one or two healers each to keep them up through the stomps. Hunters can use their instant shots to pull the giants to each tank. The giants are then kept separated and away from the main raid. DPS begins after 2 to 3 sunders, focusing first on giants and then destroyers.\r\nNote to tank: Since the Knockback is threat reducing, you might lose aggro on the giant. So once you tank the giant, do not use the [[taunt]]. Just as the giant hit you with a knockback, taunt him back, and build the threat up again. Also, tanking him with your back to a wall is helpful, since the knockback won't knock you out of melee range.\r\n==Notes==\r\nThe main focus of the giants in the zone seems to be to slow players down, and pace the speed at which the zone is cleared. They are the high hp meat-and-potatoes of the initial clear.\r\n==See also==\r\n*[[Molten Giants|Molten Giant TCG card]]",},
			["Molten Helm"] = { content = "==Source==\r\nThis item can be crafted using [[Leatherworking]] (300); taught by Pattern: Molten Helm.",},
			["Molten Shields"] = { content = "This talent gives your [[Fire Ward]] a chance to reflect fire spells back to their source. Reflected spells do not deduct from the remaining shield of your [[Fire Ward]], thus increasing its overall effectiveness. \r\nThis talent also gives your [[Molten Armor]] a 50n% chance to affect ranged and spell attacks. Combined with [[Impact]] this means that all spells and ranged attacks used against you will have a 10% chance to stun the attacker. \r\nThis talent replaced [[Improved Fire Ward]] with patch 2.4.",},
			["Molten Span"] = { content = "'''The Molten Span''' is located inside [[Blackrock Mountain]]. It is the large central chamber with lava in the bottom and a central rock chained to the sides.",},
			["Molten War Golem"] = { content = "'''Molten War Golem''' is a 54-56 [[Elite]] [[Golem]] that can be found in [[Blackrock Depths]].\r\n==Drops == \r\n \r\n Quest items dropped by Molten War Golem\r\nAlso 9 random [[Uncommon]] item drops",},
			["Molthor"] = { content = "'''Molthor''' can be found in [[Stranglethorn Vale]] .",},
			["Molt Thorn"] = { content = "'''Molt Thorn''' is a level 42 [[rare mob]] [[bog beast]] found in the [[Swamp of Sorrows]].",},
			["Molus Blackburn"] = { content = "'''Molus Blackburn''' was an ambitious and cruel [[Dark Iron dwarf]] who began making efforts to serve the [[Burning Legion]]. He hoped the demons would be pleased and reward him with greater power. To that end, he now seeked to establish a secret base near [[Ironforge]] to further the Legion's goals. He used magic to disguise himself as a [[Bronzebeard]] dwarf and headed to [[Khaz Modan]] to search for an appropriate spot. After a few days, he discovered a cave that was perfect for his purposes. Natural geography hid it from the eyes of travelers and explorers, and it was large enough to comfortably house a small army of nascent warlocks and to carry out his experiments. However, a problem presented itself: The cave was already in use. A necromancer, [[Toren Snapjoint]], was in the cave. Toren had two acolytes with him as well. Molus kept tabs on Toren for a couple of weeks and saw him raid the local graveyards and animate the dead as skeletons. Toren also slew some traveling dwarves but Molus managed to hide the bodies before anyone discovered them.\r\nMolus worried that if Toren was not careful then Ironforge would soon discover his dealings and would be on high alert for other dark magic. It also angered him that Toren was a servant of the Scourge — who had betrayed Molus's masters of the Burning Legion. Molus had one option: Destroy Toren, quickly and quietly, and take the necromancer's cave as his base. Molus did not relish the idea of facing Toren alone though. While disquised as [[Lugni Scopewol]], he hired a group of adventurers, including [[Widge Whistlevalve]], [[Jarlath Brewbelly]], [[Botrek Pahno]], [[Cerise Moonrain]], [[Maith'hal]], and [[Yinny]], to go in and take care of the problem for him.\r\nAfter they defeated Toren, Molus entered the cave, no longer disguised, with some hired muscle. He attacked the heroes who were weakened from their previous encounter. The group managed to defeat Molus although it was a tough fight.",},
			["Money-sink"] = { content = "#REDIRECT [[Gold sink]]", redirect = "Gold sink",},
			["Money"] = { content = "'''Money''' is some amount of [[copper]] pieces (), [[silver]] pieces (), [[gold]] pieces (), or a combination of any those types of coins. Your current total is shown at the bottom right of your open [[backpack]] window.\r\n==Using money==\r\nYou can spend it at a vendor [[NPC]], [[trade]], [[mail]] it to other [[Player character]]s, bid with it for an [[item]] at the [[Auction House]], use it as a deposit to auction at the Auction House, or just save it.\r\nOther uses are to buy additional bag slots at the [[Bank]] or [[Hunter]]s can buy stable slots for their pets from a [[Stable Master]].\r\n==Obtaining money==\r\nYou can get money by looting dead [[mob]]s, completing [[quest]]s, selling [[item]]s to vendor NPCs, via [[trade]] or mail from other player characters, or by selling an item at the Auction House. If you use money to put a deposit down for auctioning an item, you lose the deposit if it doesn't sell or if you cancel the auction, but any failed bids are returned via mail.\r\nThe accumulation of wealth within World of Warcraft is almost as complex a science as it is in the real world, and thousands of words have been written on how to do it.\r\n==Types of coins==\r\n* [[Copper]] coins &ndash; copper Also known as copper pieces or '''c'''.\r\n* [[Silver]] coins &ndash; silver Also known as silver pieces or '''s'''.\r\n* [[Gold]] coins &ndash; gold Also known as gold pieces or '''g'''.\r\n\"Coin\" as a term can also refer to the currency of World of Warcraft, though its use is mostly limited to questgivers giving out monetary rewards to players.\r\n===Conversion rates===\r\n* 100 copper = 1 silver \r\n* 100 silver = 1 gold \r\n* 10,000 copper = 1 gold \r\nNOTE: You can never have more than 99 copper — if you get to 100 copper , it will automatically change to 1 silver in the silver column. The same is true when you get to 99 silver 99 copper , if you add another copper then it will automatically change to 1 gold . There is no conversion rate for gold coins, so you may have more than 99 gold .\r\n==Technical considerations==\r\nThe amount of money on a server is not constant. From a technical point of view, money can be \"created\" (ie, added to the player economy) and \"destroyed\" (removed from the player economy).\r\n'''Money is \"created\" when:'''\r\n* A player sells an item to a vendor.\r\n* A player loots money from a mob or chest.\r\n* A player completes a quest with a monetary reward.\r\n* A character joins that realm or moves to that realm via transfer.\r\n* A player at the maximum level completes a quest with an experience reward component. The experience would be converted to money at 6 copper per experience point, and so a quest that would normally grant 10,000 exp would instead give him 6 gold .\r\n'''Money is \"destroyed\" when:'''\r\n* A player buys an item from a vendor or a skill from a trainer or takes a taxi flight.\r\n* A player pays a deposit / cut to the Auction House.\r\n* A player pays for repairs.\r\n* A player completes a quest that has a monetary requirement (not so common).\r\n* A player deletes his character (or otherwise stops using it).\r\n* A character moves to another realm.\r\nMoney is also traded between players in exchange for items and services, but this does not itself affect the amount of money in circulation.\r\nWhile leveling a character from 1 to 70, a player naturally \"creates\" hundreds of gold, though much of it is \"destroyed/spent\" by repair costs, training costs and personal spendings.\r\nSince a character starts with no money, it is clear that a perfectly new server has no money in circulation. As the server ages, money will be \"created\" at a greater rate, as players kill mobs (monsters) that drop more money and do quest with larger rewards.\r\nHowever, the amount of money \"destroyed\" also increases with age. Players obtain better gear which has higher repair cost. More players raid which means more total repairs, as raiding increases the average players chance of death. Older servers also see an increased significant one-time destruction's of money as people buy increased riding skills and expensive mounts.\r\n==Deflation==\r\nThere is also economic deflation on many realms since [[Gold Farmer]]s and [[Bot (character)|Bots]] have a dramatic effect on the local realm economy by selling items at reduced price on the Auction House. This is equally annoying to players as it means their own item value decreases over time. The launch of the new [[Burning Crusade]] patch had a predictable effect on the economy, as many level 70 players now have gold reserves in excess of 10,000 where before few players would have seen more than 1 or 2 thousand after quite some time at level 60. Auction house prices have soared as a result, and [[Twink]] items are even higher in price than usual. Another effect of the patch was that the market became flooded with \"high\"-level (level 60) items such as [[Brilliant Chromatic Scale]] which was already declining in price on certain realms pre-TBC (reportedly decreasing from 100g per scale to 5g per scale on some of the more economically manic realms.) These items are now worth much less than they were pre-TBC which has meant players who weren't able to sell them before the expansion have missed out on quite a lot of gold. Of course, the average wealth isn't affected by auction-house transactions, but a lot of players have been put out by the fluctuating prices.\r\n==Economy summary==\r\nThe WoW economy will always fluctuate, and large events such as the Burning Crusade launch will have a knock-on effect. My advice to any player worried about an economic decline on their realm is not to buy any gold from gold sellers, as this will have a worse effect on the economy. Also, make sure you price your auctions based on market-value and not just stab-in-the-dark wishwork. \r\nAlthough it is technically against the ToS to affect other's gameplay in a negative way (including the economy), it's generally accepted that under-pricing doesn't count as it doesn't affect the average wealth of players on your realm. It's also generally accepted that underpricing is very annoying, since other players will find it difficult to sell items at the correct price, and it may even lower the value of the item you're selling. Slight underpricing (up to around 10% of market value off) is acceptable, however.\r\nAlthough little is known about the actual average WoW player's wealth, there is much speculation about it and wherever you look you'll find a different figure. Blizzard has yet to publish anything regarding the economic status of any of the servers in any country. \r\n==Gold limit==\r\nThe limit to the amount of money a player can carry, due to Blizzard's use of a 32-bit integer to display it, is 214,748 gold 36 silver 48 copper . Screenshots of players reaching the gold limit have been taken on both and servers.\r\n==History==\r\nIn the past, all coinage was in gold. After three wars, silver and copper have come into use. Platinum coinage has not come to use yet. The Defias Brotherhood enjoys marring Stormwind minted coins creating \"cross-eyed coins” which is a sign of treason to the throne. Some coins that are not minted any longer are worth more to some people.",},
			["Mongoose Boots"] = { content = "'''Mongoose Boots''' are [[leather]] boots created through the [[Leatherworking]] profession.\r\n<clrl>\r\n==Source==\r\nThis item is crafted by [[Leatherworking|Leatherworkers]] with a skill level of 300.\r\nThe components are:\r\n*12 [[Rugged Leather]]s\r\n*6 [[Essence of Air|Essences of Air]]\r\n*4 [[Black Diamond]]s\r\n*2 [[Cured Rugged Hide]]s\r\n*4 [[Rune Thread]]s\r\nThe [[pattern]] is found in [[Knot Thimblejack's Cache]].",},
			["Monk"] = { content = "'''Monks''' are culturally considered ascetic and studious. When [[Malygos]] is in humanoid form, he takes the shape of a studious monk or similar individual. [[Pandaren]] are formidable monks, following their philosophies to the letter and perfecting their martial arts as they see fit. Runemasters are said to be monk-like as well. Monks can be found throughout Azeroth; some belong to the Scarlet Crusade, and others are found in the ranks of the draenei.\r\n==In World of Warcraft==\r\nSome monks do exist in [[World of Warcraft]].\r\n*[[Crimson Monk]]\r\n*[[Auchenai Monk]]\r\n*[[Condemned Monk]]\r\n*[[Scarlet Monk]]\r\n''Note: Monks initially were a [[denied class]] in the original Warcraft RPG sourcebook, at the time believed not to be relevant to the Warcraft world. However, monks were later incorporated through the [[Runemaster]], and references to monks appear throughout various points in RPG lore as well as World of Warcraft. However no specific monk class was ever created.''",},
			["Monster"] = { content = "#REDIRECT [[Mob]]", redirect = "Mob",},
			["Monsters"] = { content = "Any creature or [[NPC]] that is [[hostile]] to your character.\r\nThe developers of WoW popularized the jargonized abbreviation of \"monsters\" as \"[[Mobs]]\" or \"[[Creeps]]\".",},
			["Monster Guide"] = { content = "The '''Monster Guide''' is the creature source book for the [[World of Warcraft RPG]]. Additional animals were released and sold under the title of [[Monster Guide Web Supplement]].\r\nIt was released on Wednesday 07 February, 2007.\r\n==Description==\r\nBrave Azeroth’s Denizens\r\nThe undead Scourge dominates Lordaeron and Northrend. Servants of the insidious Burning Legion summon demons. Naga strike from the depths, and troggs burst from dark places beneath the surface. To carve your name into legend, you must match swords, wits, skill, and spell with these and hundreds of other creatures.\r\nA sourcebook for World of Warcraft: The Roleplaying Game\r\n• Over 200 monsters drawn from Blizzard Entertainment’s World of Warcraft fully usable in the WoW RPG and other d20 campaigns.\r\n• A beautiful full-color encyclopedia of monsters appealing to online and tabletop players alike.\r\n• Includes detailed entries on many of Azeroth’s key villains, such as Baron Geddon, Illidan Stormrage, Lord Kazzak, and Onyxia.\r\n• Includes full rules on monster abilities, on improving monsters, and on using monsters as heroes, villains and player characters.\r\nSword & Sorcery books are published under the Open Game License and are 100% compatible with v.3.5 rules and the d20 System.\r\nUS Page Count: 240 (full-color hardcover) \r\nISBN 1-58846-936-0\r\nAlso See;\r\n==List of Monsters==\r\nChapter 1: The Dangers of Being a Hero\r\n*[[Arcane nullifier X-21]]\r\n*[[Basilisk]]\r\n*[[Black ooze]]\r\n*[[Bloodpetal]]\r\n*[[Bloodpetal Flayer]]\r\n*[[Carrion grub]]\r\n*[[Cloud serpent]]\r\n*[[Core hound]]\r\n*[[Corrupted creature]]\r\n*[[Fel orc]]\r\n*[[Crowd pummeler 9-60]]\r\n*[[Crypt fiend]]\r\n*Nerubian worker crypt fiend\r\n*[[Darkhound]]\r\n*[[Dinosaur]]\r\n*[[Devilsaur]]\r\n*[[Diemetradon]]\r\n*[[Pterrordax]]\r\n*[[Stegadon]]\r\n*[[Threshadon]]\r\n*[[Dire animal]]s\r\n*Dire ape\r\n*Dire bat\r\n*Dire bear\r\n*Dire boar\r\n*Dire condor\r\n*Dire hyena\r\n*Dire lion\r\n*[[Dire gargoyle]]\r\n*[[Doomguard]]\r\n*[[Dragons]]\r\n*[[Black dragon]]\r\n:*[[Black whelp]]\r\n:*[[Black drake]]\r\n*[[Bronze dragon]]\r\n:*[[Bronze whelp]]\r\n:*[[Bronze drake]]\r\n*[[Green dragon]]\r\n:*[[Green whelp]]\r\n:*[[Green drake]]\r\n*[[Red dragon]]\r\n:*[[Red whelp]]\r\n:*[[Red drake]]\r\n*[[Dragonspawn]]\r\n*[[Dragonspawn wyrmkin]]\r\n*[[Dragonspawn scalebane]]\r\n*[[Dreadlord]]\r\n*[[Dwarf]], [[Dark Iron]]\r\n*[[Elementals]]\r\n*[[Air elemental]]\r\n:*[[Wind elemental]], lesser\r\n:*[[Wind elemental]]\r\n:*[[Wind elemental]], greater\r\n:*[[Whirlwind Ripper]]\r\n:*[[Whirlwind Shredder]]\r\n:*[[Whirlwind Stormwalker]]\r\n*[[Earth elemental]]\r\n:*[[Lesser Rock Elemental]]\r\n:*[[Rock Elemental]]\r\n:*[[Greater Rock Elemental]]\r\n:*Thundering boulderkin\r\n:*Rumbling exile\r\n:*Enraged rock elemental\r\n*[[Fire elemental]]\r\n:*Lesser living flame\r\n:*Living flame\r\n:*Greater living flame\r\n:*Flaming elemental\r\n:*Blazing elemental\r\n:*Fiery destroyer\r\n*[[Lava elemental]]\r\n:*Lava elemental\r\n:*Lava surger\r\n*[[Water elemental]]\r\n:*Lesser deep elemental\r\n:*Deep elemental\r\n:*Greater deep elemental\r\n:*Befouled water elemental\r\n:*Sea spray\r\n:*Sea elemental\r\n*[[Blood elf|Elf, blood]]\r\n*[[Elite creature]]\r\n*Dark iron [[rifleman]]\r\n*[[Entropic beast]]\r\n:*[[Entropic horror]]\r\n*[[Felguard]]\r\n*Felguard elite\r\n*[[Felhound]]\r\n*Felstalker\r\n*Fel ravager\r\n*[[Felsteed]]\r\n*[[Dreadsteed]]\r\n*[[Flamewaker]]\r\n*[[Ghost]]\r\n*[[Ghostly Warrior]]\r\n*[[Ghoul]]\r\n*[[frost giant|Giant, frost]]\r\n*[[molten giant|Giant, molten]]\r\n*[[sea giant|Giant, sea]]\r\n*[[Gnoll]]\r\n*[[Leper gnome|Gnome, leper]]\r\n*[[Golem]]\r\n*[[Harvest golem]]\r\n*[[Grell]]\r\n*[[Grellkin]]\r\n*[[Harpy]]\r\n*[[Helboar]]\r\n*[[Hydra]]\r\n*[[Imp]]\r\n*[[Infernal]]\r\n*Lesser infernal\r\n*Massive infernal\r\n*[[Kobold]]\r\n*[[Lich]]\r\n*Human lich\r\n*[[Makrura]]\r\n*Makrura tidecaller\r\n*[[Mana surge]]\r\n*Mana burst\r\n*[[Mechanized animal]]\r\n*[[Mechanostrider]]\r\n*[[Naga]]\r\n*[[Obsidian destroyer]]\r\n*[[Obsidian statue]]\r\n*[[Primal ooze]]\r\n*[[Quilboar]]\r\n*[[Razormane]]\r\n*[[Risen]]\r\n*[[Risen warrior]]\r\n*[[Rock Borer]]\r\n*[[Satyr]]\r\n*[[Scorpid]]\r\n*Scopid dunestalker\r\n*[[Shade]]\r\n*[[Silithid]]\r\n*Silithid reaver\r\n*Silithid swarmer\r\n:*Silithid broodling swarm\r\n*Silithid wasp\r\n*[[Skeletal creature]]\r\n*[[Skeletal warrior]]\r\n*Sentient skeletons\r\n*[[Succubus]]\r\n*:Queen of Suffering\r\n*[[Swarm]]\r\n*Bat swarm\r\n*Rat swarm\r\n*[[Tar beast]]\r\n*[[Tar Lord|Tar lord]]\r\n*[[Thistleshrub]]\r\n*[[Timberling]]\r\n*[[Swampwalker]]\r\n*[[Trogg]]\r\n*[[Ice troll]]\r\n*[[Sandfury troll]]s\r\n*[[Drakkari]] and [[Zandalar Troll]]s\r\n*[[Voidwalker]]\r\n*[[Wendigo]]\r\n*[[Yeti]]\r\n*[[Wildkin]]\r\n[[Owlbeast]]\r\n*[[Withered creature]]\r\n*[[Rot Hide gnoll]]\r\n*[[Worg]]\r\n*[[Worgen]]\r\n*[[Tainted one]]\r\n*[[Wraith]]\r\n*[[Zombie]]\r\n*Human zombie\r\n*Sentient zombies\r\nChapter 2: Villains\r\n*[[Archaedas]], Stone Guardian of the Vault\r\n*[[Balnazzar]]\r\n*[[Baron Geddon]]\r\n*[[Baron Rivendare]], Death Knight of Stratholme\r\n*[[Drakkisath]], General of Nefarian's Armies\r\n*[[Garr]]\r\n*[[Kel'Thuzad]], Lich Lord of the Plaguelands\r\n*[[Lady Onyxia]], Mistress of the Black Dragonflight\r\n*[[Lord Kazzak]]\r\n*[[Mekgineer Sicco Thermaplugg]]\r\n*[[Nefarian]] (or Lord Victor Nefarius), Lord of Blackrock Spire.",},
			["Monster Guide II"] = { content = "Monster Guide II is the second unofficial RPG book after [[Even More Magic and Mayhem]]. It planned to include every Azeroth critter and monsters that weren't published in the official line.\r\n==Contents==\r\n*Animated Object \r\n*Alarm-o-Bot \r\n*Anubisath \r\n*Avatar of the Soul Flayer \r\n*Battle-Trained Creature (Template) \r\n*Chicken \r\n*Cattle (from SRD) \r\n*Cockroach, Giant \r\n*Dire Troll \r\n*Drakonid \r\n*Irradiated Creature (Template) \r\n*Elemental Lords (we're talking BIG EFFING ELEMENTALS like ragnaros and thunderaan here) \r\n*Flesh Giant (see WoWWiki) \r\n*Flesh Titan (see WoWWiki) \r\n*Lasher \r\n*Gargoyle (just need a lesser version, since we have dire gargoyles as well) \r\n*Gazelle \r\n*Golem, Bone (see WoWWiki) \r\n*Golem, War \r\n*Highborne \r\n*Horusath \r\n*Incendosaur \r\n*Megalodon \r\n*Maggot, Giant \r\n*Mummy (Template; from SRD) \r\n*Qiraji: Qiraji Gladiator (the females) \r\n*Qiraji: Qiraji Battleguard (the males) \r\n*Qiraji: Qiraji Prophet (the big ones. note apparently all qiraji prophets can split into three versions. Please pay attention to this when making said creatures. Give them Mirror Image as a spell-like ability. Maybe 3 times per day) \r\n*Parrot \r\n*Pig (like a boar, less nasty-like) \r\n*Prairie Dog \r\n*Octopus, Giant (from SRD) \r\n*Rabbit \r\n*Rare Creature (Template) \r\n*Revenant (we can just use the MoM versions, unless someone objects) \r\n*Shambling Mound (from SRD) \r\n*Spectral Creature (basically, ghost animals) \r\n*Spider, Lava \r\n*Spider, Venomspitter (in all sizes) \r\n*Squirrel \r\n*Swarm (Template) \r\n*Toad, Giant \r\n*Undead Beast (see WoWWiki) \r\n*Vile Familiar (already done) \r\n*Void Terror \r\n*Young Creature (Template; representing children, applied all across the spectrum) \r\n*Wight \r\n*Zhevra \r\n==Bosses== \r\n*Twin Emperors (qiraji) \r\n*C'thun \r\n*Rend Blackhand (and his mount) \r\n*All the animal-shifting guys from Zul'Gurub. Maybe as one entry, just 4 stat blocks. \r\n*Hakkar the Soulflayer \r\n*Sapphiron \r\n*Thaddius \r\n*The Four Horsemen \r\n*Loatheb \r\n*Maexxna",},
			["Monster Guide Web Supplement"] = { content = "As mentioned in the World of Warcraft [[Monster Guide]], this web supplement contains information on animals and vermin similar in format to the monsters outlined in the book.\r\n==Table of Contents==\r\n===Animals=== \r\n*[[Ape]]\r\n*[[Badger]] \r\n*[[Bear]]\r\n*[[Black Bear]]\r\n*[[Grizzly Bear]]\r\n*[[Polar Bear]] \r\n*[[Bison]] \r\n*[[Boar]]\r\n*[[Battleboar]]\r\n*[[Buzzard]] \r\n*[[Giant Buzzard]]\r\n*[[Cat]] \r\n*[[Cheetah]] \r\n*[[Crocodile]] \r\n*Giant Crocodile\r\n*[[Crocolisk]]\r\n*[[Dog]] \r\n*[[Eagle]] \r\n*[[Frenzy (fish)|Frenzy]] \r\n*[[Giraffe]] \r\n*[[Horse]] \r\n*Light horse\r\n*Heavy horse\r\n*Light warhorse \r\n*[[Hyena]] \r\n*[[Lion]] \r\n*[[Lizard]] \r\n*Common Lizard\r\n*Monitor Lizard \r\n*[[Mammoth]] \r\n*Icetusk mammoth\r\n*[[Mountain Lion]] \r\n*[[Octopus]] \r\n*[[Owl]]\r\n*Common Owl\r\n*Giant owl\r\n*[[Pony]] \r\n*[[Rat]]\r\n*[[Ravens|Raven]] \r\n*[[Rhinoceros]] \r\n*[[Sea Turtle]] \r\n*[[Shark]] \r\n*Medium shark\r\n*Large shark\r\n*Huge shark\r\n*[[Sheep]] \r\n*[[Snake]]\r\n*Constrictor\r\n*Vipers \r\n:*Tiny viper \r\n:*Medium viper\r\n:*Large viper\r\n:*Huge viper \r\n*[[Spider Crab]] \r\n*[[Squid]] \r\n*Giant squid \r\n*[[Stag]] \r\n*[[Storm Crow]] \r\n*[[Tallstrider]] \r\n*[[Tiger]] \r\n*[[Toad]] \r\n*[[Weasel]]\r\n*[[Whale]]\r\n*Baleen Whale\r\n*Cachalot Whale\r\n*Orca Whale\r\n*[[Wind serpent]] \r\n*Variant wind serpents \r\n*[[Wolverine]]\r\n===Vermin===\r\n*[[Carrion Beetle]] \r\n*[[Giant Scarab]] \r\n*[[Monstrous Scorpion]]\r\n*Tiny monstrous scorpion\r\n*Small monstrous scorpion\r\n*Medium monstrous scorpion\r\n*Large monstrous scorpion\r\n*Huge monstrous scorpion\r\n*Gargantuan monstrous scorpion\r\n*Collossal monstrous scorpion\r\n*[[Monstrous Spider]]\r\n*Tiny monstrous spider\r\n*Small monstrous spider\r\n*Medium monstrous spider\r\n*Large monstrous spider\r\n*Huge monstrous spider\r\n*Gargantuan monstrous spider\r\n*Collossal monstrous spider",},
			["Monster Slaying"] = { content = "Monster Slaying is a talent in the Survival tree, you will need to spend 3 points in Survival to max it.\r\n==Notes==\r\nSee [[Hunter Talents]] for more details.",},
			["Monstrous Crawler"] = { content = "'''Monstrous Crawlers''' are level 43-44 [[crab]]s found in [[Swamp of Sorrows]]. When tamed, they come with Claw 6.\r\n==Objective of==\r\nThese crabs have a chance to drop Monstrous Crawler Leg for the quest Fresh Meat.",},
			["Monstrous Kaliri"] = { content = "'''Monstrous kaliri''' are huge [[owl]]s bred by the [[arakkoa]]. These huge avians are bred within the bounds of [[Skettis]] itself, and are often seen patrolling the skies above the city. The [[Sha'tari Skyguard]] regularly sends daring fliers to [[Quest:Fires Over Skettis|bomb the monstrous kaliri eggs]] before they can hatch, thus preventing the possibility of losing any more of their numbers to them.\r\n==Suggestion==\r\nYou can avoid their attack by flying up and right or left at the same time as soon as they aggro on you, if you can do so before you're dismounted (or if you're a druid), they end up looping up next to you as you move upward and are unable to attack. \r\nAnother method is to fly up and straight until reaching maximum altitude, then going into a steep dive. Usually, by the time you go into the dive, you'll be at the edge of their chase range. This works because even rare flying mounts can climb faster than the kaliri.",},
			["Monstrous Spider"] = { content = "All '''monstrous spiders''' are aggressive predators that use their poisonous bites to subdue or kill prey. Monstrous spiders come in three general types: hunters, webspinners, and spitters. Hunters and spitters rove about, while webspinners usually remain immobile and attempt to trap prey. (Hunting and spitting spiders can spin webs to use as lairs, but cannot use their webs as weapons the way webspinners can.) A monstrous spider has a poisonous bite (and poisonous spit, in the case of spitting spiders). All types of monstrous spiders often wait in their webs or in trees, then lower themselves silently on silk strands and leap onto prey passing beneath. A single strand is strong enough to support the spider and one creature of the same size. A monstrous spider can move across its own web at its climb speed and can pinpoint the location of any creature touching its web. A monstrous spider can detect and pinpoint any creature or object within 60 feet in contact with the ground, or within any range in contact with the spider’s webs.\r\nMonstrous spiders could be found in Warcraft III, often surrounded by [[Spitting Spider]]s, [[Spider Broodling]]s, and [[Spider]]s.",},
			["Montarr"] = { content = "'''Montarr''' is a level 36 [[reagent]] [[vendor]] located in [[Freewind Post]] in the [[contested]] territory of [[Thousand Needles]].\r\nSee [[List of Thousand Needles NPCs]].",},
			["Monte Gazlowe"] = { content = "'''Gazlowe''' is a level 60 [[quest giver]] located in [[Ratchet]] in the [[Horde]]-aligned territory of [[the Barrens]]. Although he is shown as a group of goblins in Warcraft 3, he is only one person. He is leader of Ratchet in World of Warcraft.\r\n==Background==\r\nIn his younger days, Gazlowe was a thief, like many goblins. Through adventuring, he gradually managed to make enough money to begin legitimate business, and proved to excel at it. \r\nHe was hired by Thrall to help build the new capital of [[Orgrimmar]]. Gazlowe sent an expedition into a nearby cave to [[Orgrimmar Tunnels|dig out some tunnels]] for artesian wells for use in the newly founded city, but they accidentally tunneled into a den of [[kobold]]s who immediately flooded into the caves and drove the goblin workers into retreat.\r\nWhen [[Rexxar]] was looking to earn his keep in Orgrimmar, Gazlowe sent him into [[Ragefire Chasm]] to help collapse the offshoot tunnels which the kobolds were using. When Rexxar did so, Gazlowe rewarded him with some magical items. \r\nNow, at the age of 40, he runs one of the largest and most successful port towns in Kalimdor — if not the entire globe. While Gazlowe’s city operates under the watchful eyes of the trade princes, he has considerable free rein, and proves effective because of it. A well-respected member of the goblin community, he also has a good heart, and is willing to help someone for little in return on occasion — but he wouldn’t mind payback later, of course. This goblin’s smile looks almost friendly, but for his sharp teeth.\r\nGazlowe now resides in [[Ratchet]] as the manager of the port trading operation. He ships and receives to and from [[Booty Bay]] and [[Undermine]].\r\n==Quests==\r\nHe starts the following quests:\r\n* Southsea Freebooters\r\n* The Missing Shipment\r\n* Stolen Booty\r\n* Goblin Sponsorship\r\nSee [[List of the Barrens NPCs]].\r\n==Warcraft Adventures==\r\nIn [[Warcraft Adventures]], after the Second War, Gazlowe would have been an ally of [[Thrall]], and helped him travel around the Eastern Kingdoms after his escape from the internment camp by fixing a zeppelin.\r\n==Quotes==\r\n*Aggro: Oh no, you didn't!\r\n*Greetings: Welcome to Ratchet! I hope you're looking for work!\r\n*Greetings: Here to stay, or just passin' through?\r\n*Greetings: Keep it quick, kid! I ain't got all day!\r\n*Greetings: I sure could use your help, kid!",},
			["Monthly quest"] = { content = "Monthly quests are repeatable once per calendar month.\r\nCurrently, there appears to be only one such quest in the game:\r\n* Membership Benefits.\r\nAs of [[Patch_2.4|Patch 2.4]], they will reset at midnight server time.",},
			["Monument of Remembrance"] = { content = "The '''Monument of Remembrance''' is a monument located in the center courtyard of the [[Alliance]] [[Alliance Expedition|Expedition]]'s fortress of [[Honor Hold]] in [[Hellfire Peninsula]].\r\nIt is a memorial to [[Anduin Lothar]], namesake of the [[Sons of Lothar]], and all of the defenders of Honor Hold who have fallen in battle against the [[Horde]] and the [[Burning Legion]].\r\n==Plaque on the monument==\r\nThere is a plaque in front of the monument, which reads:",},
			["Monument to Grom Hellscream"] = { content = "The '''Monument to Grom Hellscream''' is located in [[Demon Fall Canyon]] of [[Ashenvale]].",},
			["Monument to the Fallen"] = { content = "The '''Monument to the Fallen''' is a landmark located just outside the [[Sun's Reach Sanctum]] on the [[Isle of Quel'Danas]]. Its completion opens up [[Shattered Sun Offensive|Phase 4B]] of the [[Shattered Sun Offensive]].\r\nThe monument is a double-sided statue showing a draenei (representing the [[Aldor]]) and a blood elf (representing the [[Scryers]]). This is to symbolize the alliance between the two opposing factions - which culminated in the Shattered Sun Offensive - against [[Kael'thas Sunstrider]]'s nefarious scheme on the Sunwell Isle, and also to memorialize the Aldor and Scryer dead who fought Kael'thas and the Legion to reclaim [[Sun's Reach]].",},
			["Mood"] = { content = "#REDIRECT [[Happiness]]", redirect = "Happiness",},
			["Moodan Sungrain"] = { content = "'''Moodan Sungrain''' is a level 11 [[bread]] and [[drink vendor]] located in [[Camp Narache]] in the [[tauren]] starting zone of [[Mulgore]].\r\nSee [[List of Mulgore NPCs]].",},
			["Moogul the Sly"] = { content = "'''Moogul the Sly''' is a [[blademaster]] in the service of the [[Horde]]. He moves with quickness and fluidity, carrying a long slender blade in one hand. A red banner rising over his back marks him as a leader, and his long white beard marks him as a sage.",},
			["Moon"] = { content = "[[Azeroth]] has two '''moons''':\r\n* The larger bright and silver moon, known as the '''White Lady''', is worshipped as [[Elune]] by the [[night elves]], and referred to as [[Mu'sha]], the left eye of the [[Earthmother]] in the [[tauren]] myth [[Tauren mythology|Sorrow of the Earthmother]].\r\n* The smaller cool, blue-green moon is known as the '''Blue Child'''.\r\nFor some reason, the \"Blue Child\" is not visible in [[WoW]], it once was but was removed from the game.\r\n*Draenor and now Outland has the moon known as the [[Pale Lady]].\r\n==Sources==\r\n* The prologue to [[The Last Guardian]] indicates two moons: ''The larger of the two moons had risen first this evening, and now hung pregnant and silver-white against a clear, star-dappled sky.''\r\n* The quest [[Quest:Of Love and Family (2)|Of Love and Family]] refers to the twin moons of Azeroth.\r\n* [[Lord of the Clans]] also makes several references to two moons.\r\n* [[How to Win Friends]] also makes reference to the moons.",},
			["Moonberry Juice"] = { content = "==Source==\r\nThis item can be purchased for 20 silver copper from:\r\n* Joshua Maclure in [[Elwynn Forest]]\r\n* Barkeep Hann in [[Duskwood]]\r\n* Innkeeper Farley in [[Elwynn Forest]]\r\n* Barkeep Dobbins in [[Elwynn Forest]]\r\n* Corporal Bluth in [[Stranglethorn Vale]]\r\n* Sergeant De Vries in [[Elwynn Forest]]\r\n* Thultash in [[Swamp of Sorrows]]\r\n* Uthok in [[Stranglethorn Vale]]\r\n* Kazan Mogosh in [[Dun Morogh]]\r\n* Innkeeper Belm in [[Dun Morogh]]\r\n* Thurman Mullby in [[Stormwind City]]\r\n* Elly Langston in [[Stormwind City]]\r\n* Innkeeper Helbrek in [[Wetlands]]\r\n* Keeg Gibn in [[Dun Morogh]]\r\n* Natheril Raincaller in [[Winterspring]]\r\n* Lyranne Feathersong in [[Winterspring]]\r\n* Innkeeper Anderson in [[Hillsbrad Foothills]]\r\n* Neema in [[Hillsbrad Foothills]]\r\n* Barkeep Kelly in [[Hillsbrad Foothills]]\r\n* Innkeeper Shay in [[Hillsbrad Foothills]]\r\n* Kayren Soothallow in [[Hillsbrad Foothills]]\r\n* Malygen in [[Felwood]]\r\n* Bale in [[Felwood]]\r\n* Vikki Lonsav in [[Arathi Highlands]]\r\n* Graud in [[Arathi Highlands]]\r\n* Nixxrax Fillamug in [[Stranglethorn Vale]]\r\n* Grawl in [[Badlands]]\r\n* Gretchen Vogel in [[Redridge Mountains]]\r\n* Gabrielle Chase in [[Burning Steppes]]\r\n* Trak'gen in [[Durotar]]\r\n* Asoran in [[Durotar]]\r\n* Denni'ka in [[Stonetalon Mountains]]\r\n* Sarah Raycroft in [[Hillsbrad Foothills]]\r\n* Bernie Heisten in [[Blasted Lands]]\r\n* Dalaran Brewmaster in [[Silverpine Forest]]\r\n* Kurll in [[Azshara]]\r\n* Rarck in [[Alterac Valley]]\r\n* Laer Stepperunner in [[Thousand Needles]]\r\n* Gruna in [[Burning Steppes]]\r\n* Grimtak in [[Durotar]]\r\n* Zlagk in [[Durotar]]\r\n* Moodan Sungrain in [[Mulgore]]\r\n* Jhawna Oatwind in [[Mulgore]]\r\n* Innkeeper Boorand Plainswind in [[The Barrens]]\r\n* Kira Songshine in [[Elwynn Forest]]\r\n* Nantar in [[Ashenvale]]\r\n* Maliynn in [[Ashenvale]]\r\n* Dendrythis in [[Teldrassil]]\r\n* Jaeana in [[Teldrassil]]\r\n* E