			["Razormane Pathfinder"] = { content = "'''Razormane Pathfinder''' can be found in [[The Barrens]] .\r\n==Drops == \r\n \r\n0.06% Chance of a [[rare]] drop.\r\n0.82% Chance of an [[Uncommon]] drop.\r\n0.13% Chance of a [[common]] drop.\r\n0.57% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Razormane Quilboar"] = { content = "'''Razormane Quilboar''' can be found in [[Durotar]] .\r\n==Quests== \r\n==Drops == \r\n \r\n0.06% Chance of an [[Uncommon]] drop.\r\n0.15% Chance of a [[common]] drop.\r\n0.21% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Razormane Scout"] = { content = "'''Razormane Scout''' can be found in [[Durotar]] .\r\n==Quests== \r\n==Drops == \r\n \r\n0.09% Chance of an [[Uncommon]] drop.\r\n0.15% Chance of a [[common]] drop.\r\n0.22% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Razormane Seer"] = { content = "'''Razormane Seer''' can be found in [[The Barrens]] .\r\n==Drops == \r\n \r\n0.03% Chance of a [[rare]] drop.\r\n0.37% Chance of an [[Uncommon]] drop.\r\n0.07% Chance of a [[common]] drop.\r\n0.10% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Razormane Stalker"] = { content = "'''Razormane Stalker''' can be found in [[The Barrens]] .\r\n==Drops == \r\n \r\n0.05% Chance of a [[rare]] drop.\r\n0.42% Chance of an [[Uncommon]] drop.\r\n0.10% Chance of a [[common]] drop.\r\n0.13% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Razormane Thornweaver"] = { content = "The '''{{PAGENAME}}''' is the caster mob of the [[Razormane]] [[quilboar]] tribe, located in [[Thorn Hill]]. They are capable of casting [[Faerie Fire]] and buffing themselves with [[Thorns]].",},
			["Razormane tribe"] = { content = "The '''Razormane''' are a tribe of [[quilboar]] that inhabit [[Durotar]] and [[Barrens|The Barrens]].\r\nRazormanes are one of the two most prominent quilboar tribes. Native to the Barrens, they frequently raid and pillage nearby settlements.\r\nTheir members come in several flavors:\r\n* [[Razormane Quilboar]]\r\n* [[Razormane Scout]]\r\n* [[Razormane Dustrunner]]\r\n* [[Razormane Battleguard]]\r\n* [[Razormane Water Seeker]] - melee\r\n* [[Razormane Thornweaver]] - caster\r\n* [[Razormane Hunter]] - ranged attacker, pet user\r\n** [[Razormane Wolf]]\r\n* [[Razormane Geomancer]]\r\n* [[Razormane Defender]]\r\n* [[Razormane Mystic]]\r\n* [[Razormane Pathfinder]]\r\n* [[Razormane Stalker]]\r\n* [[Razormane Seer]]\r\n* [[Razormane Warfrenzy]]\r\n* Razormane Champion\r\n** [[Spirit pig]]\r\n* [[Razormane destroyer]]\r\nKnown members:",},
			["Razormane Warfrenzy"] = { content = "'''Razormane Warfrenzy''' can be found in [[The Barrens]] .\r\n==Drops == \r\n \r\n0.03% Chance of a [[rare]] drop.\r\n0.46% Chance of an [[Uncommon]] drop.\r\n0.08% Chance of a [[common]] drop.\r\n0.12% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Razormane Water Seeker"] = { content = "The '''{{PAGENAME}}''' is the melee mob of the [[Razormane]] [[quilboar]] tribe, located in [[Thorn Hill]]. They are capable of inflicting [[Creeping Mold]].",},
			["Razormane Wolf"] = { content = "'''Razormane Wolves''' are the level 7-8 [[wolf]] pets of the [[Razormane Hunter]]s. Together, they patrol [[Thorn Hill]] in the [[Barrens]]. Razormane Wolves cannot be tamed by players.",},
			["Razormaw"] = { content = "'''Razormaw''' is a level 20 [[elite]] [[undead]] black [[dragon]] that haunts [[Wyrmscar Island]] off the coast of [[Bloodmyst Isle]].\r\nHe is summoned by using the Bundle of Dragon Bones, provided by [[Prince Toreth]], on the [[Ever-burning Pyre]].\r\n==Background==\r\nRazormaw is a former lieutenant of [[Deathwing]]. Many thousands of years before the present time, the Night Elves of Silvergale Isle made a pact with the Aspect [[Ysera]]'s brood. The elves were gifted with Ysera's blessing and were allowed to ride the [[Dragons]] into battle against their enemies. They were known as the [[Dragon Riders of Loreth'Aran]]. This unfortunately attracted [[Deathwing]]'s ire, and he sent his flight, including his lieutenant '''Razormaw''', to launch an attack on the Night Elves while they were sleeping. The [[Green Dragons]] rose up to protect their elven allies but eventually they were all defeated by Deathwing's brood. '''Razormaw''' however, also perished in the final battle.\r\nMany thousands of years later the remains of battle can still be seen. Gigantic draconic skeletons litter the isle and the spirits of green whelps wander aimlessly, attacking all that approach. Razormaw's hatred was so great that even in death he still remains, as a spectral dragon circling overhead. Prince Toreth, a ghost of one of the riders that remains to keep the world from forgetting the Dragon Riders of Loreth'Aran, asks passing adventures to summon down the ghostly black dragon, and defeat it to end the haunting of the isle.\r\n==Quests==\r\n*Razormaw",},
			["Razormaw Matriarch"] = { content = "The '''Razormaw Matriarch''' is a level 31 [[rare mob]] yellow [[raptor]] in the [[Wetlands]].",},
			["Razorthorn Rise"] = { content = "'''Razorthorn Rise''' is a newly-named area located in the mountains at the northern edge of [[Terokkar Forest]] bordered by [[Hellfire Peninsula]] to the north, [[Silmyr Lake]], [[Veil Reskk]] and [[Razorthorn Shelf]] from southwest to southeast, and is only accessible via [[flying mount]]. Two [[daily quest]]s for the [[Shattered Sun Offensive]] take place here.\r\nResident wildlife include Razorthorn Flayer and Razorthorn Ravager",},
			["Razorthorn Shelf"] = { content = "[[Razorthorn Shelf]] is a passage between southwestern [[Hellfire Peninsula]] and northeastern [[Terokkar Forest]]. Inhabited by Ravagers, it is the shortest route from Hellfire Peninsula to Shattrath City.",},
			["Razorthorn Trail"] = { content = "'''Razorthorn Trail''' is the pathway from [[Hellfire Peninsula]] to [[Terokkar Forest]]. It is a nesting ground for the Razorthorn [[ravager]]s.",},
			["Razorwind Canyon"] = { content = "The '''Razorwind Canyon''' is the proper nesting grounds for the Dustwind [[harpy|harpies]] of [[Durotar]]. Adventurers had better prepare themselves for battle before heading into this area, as the aggressive bird women are quite numerous through the canyon, and can quickly subdue or kill unwary travelers.",},
			["Razor Hill"] = { content = "'''Razor Hill''' is an [[orc]]ish outpost built on a crossroads in central [[Durotar]]. The southern road eventually leads to [[Sen'Jin Village]] and the [[Valley of Trials]]. The northern road leads to [[Orgrimmar]], and the road west ends up in [[the Barrens]] and eventually to the major [[Horde]] gathering point of the [[Crossroads]]. The [[Razor Hill Barracks]] is the single most prominent structure in the town. The orc, [[Orgnil Soulscar]] is the current leader of Razor Hill, occupied with investigating the activities of the [[Burning Blade]] in the area. \r\nRazor Hill is the second place of training for all new orcs and trolls except mages. Usually people achieve level 10 before venturing on to [[the Barrens]].\r\nShortly after the [[Third War]], the forces of [[Kul Tiras]] arranged a summit with Thrall at Razor Hill. It was in fact a planned ambush. However, having speculated this, [[Rexxar]] insisted that he should go in Thrall's place. In turn, Rexxar defeated the assassins. \r\n==Inhabitants==\r\n* [[Orgnil Soulscar]]\r\n* [[Gar'Thok]]\r\n* [[Takrin Pathseeker]]\r\n* [[Cook Torka]]\r\n* [[Shoja'my]] - Stable Master\r\n* [[Innkeeper Grosk]] - Innkeeper\r\n* [[Yelnagi Blackarm]]\r\n* [[Ophek]]\r\n* [[Furl Scornbrow]]\r\n* Guards: [[Razor Hill Grunt]]\r\n===Vendors===\r\n* [[Cutac]] - Cloth and Leather merchant\r\n* [[Wuark]] - Armor and Shieldcrafter\r\n* [[Uhgar]] - Weaponsmith\r\n* [[Grimtak]] - Butcher\r\n* [[Ghrawt]] - Bowyer\r\n* [[Flakk]] - Trade Supplies\r\nInside [[Razor Hill Barracks]]:\r\n* [[Jark]] - General Goods\r\n===Trainers===\r\n* [[Dhugru Gorelust]] - [[Warlock]] Trainer\r\n* [[Dwukk]] - [[Blacksmith]] Trainer [Journeyman]\r\n* [[Harruk]] - [[Pet]] Trainer\r\n* [[Kaplak]] - [[Rogue]] Trainer\r\n* [[Kitha]] - [[Demon]] Trainer\r\n* [[Krunn]] - Mining Trainer\r\n* [[Mukdrak]] - [[Engineering]] Trainer [Journeyman]\r\n* [[Thotar]] - [[Hunter]] Trainer\r\nIndside [[Razor Hill Barracks]]:\r\n* [[Rawrk]] - First Aid Trainer\r\n* [[Swart]] - [[Shaman]] Trainer\r\n* [[Tai'jin]] - [[Priest]] Trainer\r\n* [[Tarshaw Jaggedscar]] - [[Warrior]] Trainer\r\n==Quests==\r\n*Vanquish the Betrayers\r\n**From The Wreckage....\r\n*The Admiral's Orders (2)\r\n*Carry Your Weight\r\n*Break a Few Eggs\r\n*Encroachment\r\n*Dark Storms\r\n**Margoz\r\n*Conscript of the Horde\r\n===Class specific===\r\n*Taming the Beast (Orc and Troll 1)\r\n**Taming the Beast (Orc and Troll 2)\r\n**Taming the Beast (Orc and Troll 3)\r\n***Training the Beast (Orc and Troll)\r\n*Gan'rul's Summons",},
			["Razor Hill Barracks"] = { content = "The '''Razor Hill Barracks''' features trainers for [[warrior]]s, [[priest]]s, [[shaman]]s and [[first aid]]. It also has a general goods vendor. Along with the [[zeppelin]] tower and [[Tiragarde Keep]], the barracks is one of the largest orc structures in [[Durotar]] (excluding [[Orgrimmar]]).",},
			["Razor Hill Grunt"] = { content = "'''Razor Hill Grunts''' are level 28 [[guard]]s located in the town of [[Razor Hill]] in the [[orcish]] starting zone of [[Durotar]]. They are stationed at the town entrance/exits, structures and patrol the streets. They are simple grunts that serve to protect Razor Hill citizens from the dangers in the environment such as boars and snakes as well as crush any sailors or marines that decide to launch an attack on Razor Hill from the Alliance fortress of [[Tiragarde Keep]]. They can provide directions to various locations.\r\nSee [[List of Durotar NPCs]].",},
			["Razor Ridge"] = { content = "'''Razor Ridge''' is an area near [[Toshley's Station]] that is crawling with [[ravager]]s.",},
			["Razuvious"] = { content = "#redirect [[Instructor Razuvious]]", redirect = "Instructor Razuvious",},
			["Razzeric"] = { content = "'''Razzeric''' is a level 30 [[quest giver]] located at the [[Mirage Raceway]] in the [[contested]] territory of [[Thousand Needles]].\r\nHe starts the following quests:\r\n* Razzeric's Tweaking\r\n* Safety First\r\nSee [[List of Thousand Needles NPCs]].",},
			["Razzle Sprysprocket"] = { content = "'''Razzle Sprysprocket''' is a level 20 quest giver located in [[Kharanos]] in the [[dwarven]] starting zone of [[Dun Morogh]]. Although he shares the same last name with [[Rizzle Sprysprocket]], they apparently are not related.\r\nHe starts the quest Operation Recombobulation.\r\nSee [[List of Dun Morogh NPCs]].",},
			["Reaching the Badlands travel guide"] = { content = "==Reaching the Badlands==\r\nThe fort of [[Kargath]], in the [[Badlands]], contains a key [[Horde]] [[Flight Path]] connecting the north and south of the [[Eastern Kingdoms]]. Moreso than other regions of its level range (35-45), the Badlands is fairly difficult for Horde to reach. The only entrances to the region come either through Alliance territory far from Horde flight paths ([[Loch Modan]]) or high level areas far from Horde flight paths ([[Searing Gorge]]).\r\nThere are a few alternatives. All of these assume that you are traveling from [[Orgrimmar]], but it should be fairly obvious how to alter them to account for alternate starting points.\r\nThe route with the least amount of running makes use of a teleporter in [[Booty Bay]], accessible via a short quest chain that starts in Orgrimmar. This path goes through two low-level Alliance regions, so is more risky on PvP servers, but fairly easy on PvE servers. If you are a level high enough to survive in the Badlands, you should not have much problem. Do the following:\r\n*From the engineer in Orgrimmar, get the [[Quest:Chief Engineer Scooty|Scooty quest]]. You may need to accept [[Quest:Rig Wars|Rig Wars]] first, but you do not need to complete it.\r\n*Get to Booty Bay (see [[Travel Guide:Crossroads to Booty Bay|here]]).\r\n*Find Scooty (south of the tavern) and turn in the quest. Scooty will issue you another quest, but all you need to do is stand there for a minute to complete it. Turn that in to get the item that allows you to use the transporter.\r\n*Step on the teleporter\r\n*You materialize inside [[Gnomeregan]], quite close to the entrance. Most of what is around you will be hostile, but are only around level 24.\r\n*Move into the entrance elevator (to the southeast). You'll probably need to kill the [[Leper Gnome]]s guarding the room. Take the elevator and exit Gnomeregan.\r\n*Follow the roads in [[Dun Morogh]], moving all the way to the east. Avoid towns, and follow the signs to Loch Modan.\r\n*Go through the Southern Gate into [[Loch Modan]]. You'll need to either fight or avoid the guards. The road will lead down a long hill to a T intersection. Take a left.\r\n* Travel through Loch Modan to a gap in the center of the southern mountains, right below the tip of the lake. Avoid towns. \r\n*Go through this gap into the Badlands.\r\n*Once in the badlands, [[Kargath]] is in the most western part. Keeping an eye out for mobs, skirt the edge of the mountains.\r\nA more traditional route overland route runs from the [[Undercity]] through five other regions. With care, this can be done by level 20+ characters, but the distance is quite long so a travel form or mount is recommended.\r\n*Take the Zeppelin to [[Undercity]].\r\n*Travel along the road South past the [[Undercity]] to [[Silverpine Forest]].\r\n*Continue along the road in Silverpine and grab the flight Path at the [[Sepulcher]].\r\n*Travel south from the Sepulcher along the road and turn east towards [[Hillsbrad Foothills]].\r\n*Grab the flight point at [[Tarren Mill]], then continue east towards the [[Arathi Highlands]].\r\n*Continue east on the road and grab the flight point at [[Hammerfall]]. Then head south towards the [[Wetlands]].\r\n*There is no Horde flight path in the [[Wetlands]]. Continue south on the road towards [[Dun Algaz]].\r\n*[[Dun Algaz]] is a series of three tunnels between [[Wetlands]] and [[Loch Modan]]. The third and highest tunnel has a roaming 30's level guard inside the tunnel. There are more guards stationed at the tunnel exit into [[Loch Modan]]. To pass through the tunnel without fighting the roaming guard, position yourself to the right of the entrance tunnel up on the hillside. Wait for the roaming guard to exit the tunnel, then run quickly into the tunnel. You will be attacked on exiting the tunnel into [[Loch Modan]]. Have whatever defensive measures you have ready. Run as far out of the tunnel as you can. If you die in [[Loch Modan]] you will arrive at the Spirit Healer just north of [[Thelsamar]]. Slip into the woods and continue south to the Badlands if you opt not to return for your corpse.\r\n*If you successfully pass through [[Dun Algaz]], keep heading south in [[Loch Modan]]. Avoid the Alliance town [[Thelsamar]]. Once you are safely south of [[Thelsamar]], head east towards the Loch. Travel along the shore until you hit the southern most point and head south.\r\n*Once in [[The Badlands]] head south, then west always travelling along the mountains on the edge of the map (watch out for the stealthed tigers here). Soon you will reach [[Kargath]].\r\n*If you die in the Badlands before the halfway point to [[Kargath]], you will appear at the Spirit Healer near [[Loch Modan]]. If you die past the halfway point to [[Kargath]], You will appear at the Spirit Healer just south of [[Kargath]]. Move quickly in the Badlands.\r\nAn overland approach also exists from the south, but it is even longer and much more dangerous, heading through a couple level 50+ regions:\r\n*Take [[zeppelin]] to [[Grom'Gol Base Camp]] in [[Stranglethorn Vale]].\r\n*Follow the roads north into [[Duskwood]].\r\n*Follow the road all the way to the northeast, avoiding the town of [[Darkshire]] (unless you like that kind of trouble). If you want to get the flight path at Stonard, you can dodge Darkshire and head eastward into [[Deadwind Pass]]. Here continue directly east, following the road, as there are high-level mobs just right off it (not close enough to aggro when you're on the road, though). When you get into the [[Swamp of Sorrows]], follow the road (which is guarded by some Horde-friendly orcs) until you pass by the crossroads past Splinterspear Junction and take the southern road. Follow this road eastward, passing by the road leading to the [[Blasted Lands]], until you reach Stonard.\r\n*The north road out of Darkshire will take you into the [[Redridge Mountains]].\r\n*Follow the road north, avoiding the village of [[Lakeshire]], into the [[Burning Steppes]].\r\n*Ride to the north of the [[Ruins of Thaurissan]] to [[Flame Crest]] in the Steppes and grab the flight path there, then travel west and enter [[Blackrock Mountain]].\r\n*Follow the path through the mountain (no mobs along the path) into [[Searing Gorge]]\r\n*Follow the road to the northeast.\r\n*After passing by a dwarven dig site on the right, turn right through a pass (70,54) to the east and enter [[Badlands]].\r\n*Head north to [[Kargath]]",},
			["Reaching the Swamp of Sorrows travel guide"] = { content = "When players come across Dream Dust in the Swamp, they may be faced with a dilemma: where is the [[Swamp of Sorrows]], and more importantly, how in the world do you get there? This is much simpler for [[Alliance]] players who can simply run through [[Darkshire]] to [[Deadwind Pass]], but has proven difficult for some Horde characters.\r\n===Conventional Route===\r\nThis path assumes that you are beginning in [[Orgrimmar]], though you may be able to skip ahead if you are already familiar with [[Stranglethorn Vale]]. Do the following:\r\n*From [[Orgrimmar]], take the Zepplin to [[Grom'gol Base Camp]]\r\n*Follow the road from the camp northeast, then north. Lower levels are advised to stick to the roads, as the surrounding jungle is filled with mobs level 30 and up.\r\n*When the road ends, turn east and cross the bridge into [[Duskwood]].\r\n*Continue north until the road forks. Turn right and head east.\r\n*Skirt the [[Alliance]] town of [[Darkshire]].\r\n*Once clear of the town, run back onto the road and go east into [[Deadwind Pass]].\r\n*Continue east through [[Deadwind Pass]]. The road twists south, then continues east once again. Players under level 50 are again highly advised to stick to the road, as mobs here are level 50+. Leaving the road can quickly turn deadly, and the unprepared should stay clear of the south, lest they end up near [[Karazhan]].\r\n*The east road will turn into the [[Swamp of Sorrows]].\r\n*Follow the road east until it forks. Take the right path towards [[Stonard]], which is near the middle of the swamp.\r\nNote: Upon entering Duskwood, it is highly suggested to shed all clothes which have durability (anything other than rings or necklaces) to prevent durability loss due to death.\r\n===Alternate route===\r\nWhile this is a very long swim, there are ''no mobs'' to deal with (except those in Wetlands or Arathi depending on how you originally got to the span) until you get where you need to be to find the crawlers. (Watch for swimming crocs!)\r\n*Jump off the [[Thandol Span]] (that separates the [[Wetlands]] from the [[Arathi Highlands]]) into the sea (or walk down the land ramp on the Arathi side).\r\n*Swim east, then south, staying close to the mountainous coast, past [[Badlands]], [[Burning Steppes]], and [[Redridge Mountains]] all the way to the Swamp of Sorrows, right up to the north end of the [[Misty Reed Strand]]. \r\nNote: As you swim you will likely see your zone change directly from Wetlands to Swamp of Sorrows. After you enter the Swamp of Sorrows zone, you have to swim a while longer before you get to Misty Reed Strand. There is no way to access Badlands, Burning Steppes or Redridge Mountains from the sea. There are a couple places you can climb the mountain bases into the Redridge zone \"border\", but you cannot climb into the main area of the zone. \r\nAlso Note: This route means swimming trapped between mountains and the sea for at least 1/2 an hour (I advise against the alternate route).\r\n===Other Alternate routes===\r\nMuch shorter swim (still long trip):\r\n*If you are weak and afraid of mobs - Jump off the dock in [[Booty Bay]] and swim around [[The Cape of Stranglethorn]]. Swim for 15 minutes(?) till you see crocodiles and trees.\r\nor\r\n*To shorten the trip, if you're not troubled by mobs ('''advisable''') but want to avoid PvP conflict, enter [[Stranglethorn Vale]] via [[Booty Bay]]. Go directly to the sandy East coast beach. Travel North on that beach until there is no more land. Jump in the water and swim for all your worth until you see crocs and trees. \r\nNote: The Swamp of Sorrows is the ''only'' way out of the ocean so you cannot miss it.\r\nNote: Stay close to shore when swimming or fatigue will kill you.\r\nNote: If the constant drone of bullfrogs and crickets annoys you, bring your own music.",},
			["Read"] = { content = "As a verb, the act of [[use|using]] certain [[item]]s with some sort of text on them. This includes [[book]]s ([[:Category:World of Warcraft in-game books|in-game books]] and [[training]] manuals), [[quest]] items with text, or [[scroll]]s. Books and items that can be read can be right-clicked to bring up the text.",},
			["Ready check"] = { content = "A '''ready check''' is an automatic survey that can initiated by a party or raid leader. Anyone promoted to raid assistant by the leader is also able to use the command. The command is initiated by typing <tt>''/readycheck''</tt>, or by clicking the \"Ready Check\" button in the raid ui panel.\r\nAll members of the raid will receive a popup window that asks if the player is ready. If all players click \"yes\", the person who initiated the check will receive a message indicating so. If a player clicks \"no\" or does not respond withing the prescribed time limit a message will be sent to the leader indicating that they are either not ready or AFK, respectively. Players who are flagged with the <[[AFK]]> flag will auto-respond as being AFK.\r\nReady checks are most often used in preparation for a boss encounter to make sure ready to commence. They are also often used as a means to survey which players have returned if the raid takes a break for any reason.\r\nNote: The ready check popup window will not appear for group members who are currently playing in a [[Battleground]]. This can sometimes make a raid leader (especially when organizing a [[Premade]]) erroneously believe that a team member is AFK.",},
			["Reagent"] = { content = "A '''reagent''' is an item that is required in order to cast a specific [[spell]] or use a specific [[ability]]. A reagent differs from a [[Tool]] in that successfully using the ability/spell will consume the reagent. The origin of the term comes from chemistry and items used in chemical reactions, but [[Blizz]]ard as adopted the term to be extended to spells and some recipes. Reagents are generally '''not''' tradeskill or crafting ingredients, although this usage is often abused.\r\nFrom a game design perspective, reagents have a similar effect on magic-using classes as [[durability]] does on [[melee]] classes. Since magic-users generally pay very little for repairs compared to their front-row melee counterparts, they must purchase and keep a supply of spell reagents instead. \r\nOne class, the [[Warlock]], heavily uses [[Soul Shard]]s created from dying enemies as spell reagents. A major aspect of the Warlock class involves strategic management of Soul Shards.\r\n[[Rogue]]s also make use of reagents for their [[Vanish]] ability (As of [[Patch 2.3.0]] [[Blind]] no longer has a reagent requirement}.\r\n==Reagents Used by Spells or Abilities==",},
			["Reagents for Reclaimers Inc. (quest)"] = { content = "This is part of the [[Reagents for Reclaimers Inc quest chain]].\r\n==Prerequisites==\r\nMust have completed [[Quest:Reclaimers' Business in Desolace|Reclaimers' Business in Desolace]].\r\n==Objectives==\r\nBring 10 [[Hatefury Claw]]s, and 10 [[Hatefury Horn]]s to [[Kreldig Ungor]] in [[Desolace]].\r\n*Hatefury Claw (10)\r\n*Hatefury Horn (10)\r\n==Quest Text==\r\nOne of my tasks out here involves picking up some reagents for [[Leftwitch]], a [[gnome]] [[mage]] in [[Kharanos]]. [[Roetten Stonehammer|Roetten]] seems to think it's easy coin in the bank since we're out here already. He doesn't really care that we're short-handed as is.\r\nThe first few items on his list should be easy enough to get, and it'd be a good chunk of coin for anyone helping me out.\r\nI need some horns and claws from the [[Hatefury]] [[satyr]] to the east of here. Bring 'em back to me and we'll get started on the rest of the list.\r\n==Progress==\r\nDespicable creatures, the satyr. Story says they're somehow tied to the night elves, but I'm not so sure I believe it.\r\nI think they get that on account of that one elf that brought them into the war few years back. World's never been the same since. Lot more dangerous, and a lot scarier.\r\n==Completion==\r\nGood good, <name>. Not sure if these are of any good quality, but\r\nif Leftwitch wanted a specific type, he should have specified\r\nbefore sending the Reclaimers out here to begin with.\r\nWhat say you to getting on with the next item on his list?\r\n==Reward==\r\nYou will receive:\r\n* 35 silver \r\n==Gains==\r\n* 2650 [[XP]]\r\n* +250 [[Ironforge]] reputation\r\n==Notes==\r\nThe [[Hatefury]] [[satyr]]s are located directly east of [[Nijel's Point]] in the [[Sargeron]] ruins.",},
			["Reagent Pouch"] = { content = "The '''Reagent Pouch''' is at the bottom of the bay on deck of one of the sunken ships. Pick up Daggercap Divin' from [[Harold Lagras]], also at the bottom of the bay to pick up a Diving Helm to enable water breathing.\r\n==Objective of==\r\nThis item is an objective of Into the World of Spirits.",},
			["Realm"] = { content = "A '''realm''' is an instance of the ''[[World of Warcraft]]'' (WoW) game world. Realms are hosted on physical devices called '''[[server blade]]s''' (for this reason, the terms \"realm\" and \"server\" are often used interchangeably). This prevents any one realm from becoming too crowded and overwhelming its associated server, provides for better connection times by allowing players to connect to local servers, allows for [[localization|localized]] communities based on language, and allows different play-styles for different groups of users. Each realm also has its own name, generally taken from an important character, location or group within the Warcraft universe. \r\nTo play ''WoW'', you must first choose a realm to play on. You then connect to this realm over the Internet. Blizzard has servers in the US, Europe, China, and Korea. For a list of all realms, see [[realms list]].\r\nChoosing a server is an important decision involving many factors. For a fuller exploration and some helpful tips for choosing, see [[Newbie_guide/Picking_a_Server|Picking a Server]].\r\n==Functionality==\r\nEach realm is a complete version of the game world but has its own player characters who are tied to that particular realm. Players can interact with all the characters on their current realm but cannot generally interact with players on other realms. This includes communicating, forming parties and guilds, sending mail, trading and directly interacting. Each realm is a discrete instance of the game world, and as such events that take place on one realm will not affect other realms, including world progression such as the [[Isle of Thunder]], and realm first achievements.\r\nA character must be created on a specific realm, and can only be played by selecting that realm. Players may create characters on any number of realms up to a maximum of fifty characters on an account.\r\nCharacters cannot move between realms via in-game means. However, players may take advantage of free character migrations (FCMs) or paid [[Character Transfer]]s to move characters between realms. It is not possible to move characters between different [[|regions]].\r\nExceptions to the above rules include [[Connected Realms]], where multiple realms function as a single cohesive realm; [[cross-realm zone]]s, where certain [[zone]]s may feature characters from several different servers; and [[battleground]], [[Dungeon Finder]] and [[arena]] instances, which may feature characters from separate servers. One notable exception is the [[RealID]] and [[BattleTag]] systems, which allow players to invite other players from other realms to join their party. All characters in the party will be moved to the realm of the current leader and will function fully in that realm, including queuing for arena and instances.\r\n==Types==\r\n''For more information on each type of realm and advice on choosing the right type for you, see [[Newbie_guide/Picking_a_Server|Picking a Server]]''.\r\nThere are currently four main types of realm available to players: Player vs. Environment (PvE), Player vs. Player (PvP), Roleplaying (RP), and Roleplaying Player vs. Player (RP-PvP). Each type of realm features a slightly different ruleset. While PvE realms are the basic option, PvP and RP-PvP realms allow for increased [[world PvP]], while RP and RP-PvP realms are designed to facilitate [[roleplaying]], and accordingly have certain requirements and expectations of their players. Test realms are a special type of realm available for players to test features from coming patches.\r\nAccording to the North American realm status page, there are 241 total NA realms. Of these 113 are Normal (PvE) servers, 105 are PvP, 17 are RP, and 6 are RP-PvP. For Europe, there are 109 English speaking realms, 87 German, 37 French, 11 Spanish, and 19 Russian, for a total of 263 realms. This breaks down into 99 Normal (PvE), 129 PvP, 20 RP, and 15 RP-PvP servers.\r\n===Player versus environment===\r\nAbbreviated '''PvE''', the [[PvE realm|player versus environment realm]] allows for a more relaxed style while in the world. PvE realms focus on [[player versus environment]] (PvE) play and depending on the location within the world, it is more difficult to initiate [[player versus player]] (PvP) combat on these realms. This type of realm is also referred to as a \"normal\" realm. PvE realms are generally recommended for new players, since there is no risk of unwanted PvP combat or ganking from other players.\r\n===Player versus player===\r\nAbbreviated '''PvP''', the [[PvP realm|player versus player realm]] differs from the normal realm. PvP realms have an increased amount of [[player versus player]] combat, in the form of [[World PvP]]; entering any [[contested territory|contested]] or enemy territory automatically [[PvP flag|flags]] the character being used for PvP combat, and the character cannot be unflagged while in these zones. The player will remain flagged for five minutes after having left a contested or enemy territory. PvP realms are generally recommended for those who enjoy knowing that they could be attacked at any time.\r\n===Roleplaying===\r\nAbbreviated '''RP''', the [[roleplaying]] realm features the PvE playstyle with roleplaying rules, which apply to behavior and naming.\r\n===Roleplaying player versus player===\r\nAbbreviated '''RP-PvP''', the [[RP-PvP|roleplaying-player versus player realm]] features the PvP playstyle with roleplaying rules, which apply to behavior and naming.\r\n===Test===\r\nNot a normal option for character creation, [[Test Realm]]s are special realms that are periodically made available, in which players can try experimental features in development before they get released as general [[patches]]. Test realms often exist in both PvE and PvP varieties.\r\n==Regions==\r\n''Main article: [[Region]]''\r\nAs with all ''World of Warcraft'' play, servers are divided into regions. The current regions are Americas & Oceania, Europe, China, Taiwan and Korea. ''World of Warcraft'' accounts are region-specific and only allow for use of features related to that region, including access to servers.\r\nCharacters cannot be transferred to realms in other regions, and a player cannot communicate with or invite players from other regions. Cross-realm features such as [[cross-realm zone]]s and battleground instances do not function cross-region. Currently, all leaderboards and ladders (eg [[Challenge Mode]]) are region- or realm-specific.\r\nMany server names are found in multiple regions. Non-US realms are distinguished on multi-region server lists by use of a prefix, such as [[Server:Aegwynn US|Aegwynn]] and [[Server:Aegwynn Europe|EU-Aegwynn]].\r\n==Languages==\r\nEuropean realms are divided up by which language is primarily spoken on them, each realm having a specified language. Fully localized realms also feature game text and names in the specified language.\r\nWhile you will not be banned if you do not fluently speak that realm's specified language, you may feel more comfortable in a realm where the majority of players speak a language that you understand.\r\n==Population==\r\nEach realm has a population listed on the realm selection screen. Each realm is characterized as having Recommended, Low, Medium, High, or Full population. Recommended realms are realms that [[Blizzard Entertainment]] feels will give a new player the best experience, while the rest are categorized based on how many players are currently logged into the realm. Players cannot create a character on a Full realm unless they already have characters on that realm. Full realms are deemed 'full' by Blizzard and as such, their 'full' status does not fluctuate like a 'high' population realm's might. There is no reason to wait until off-peak times to see if you will be allowed to create a character on a 'full' realm.\r\nA realm's population impacts its play experience in many ways. Higher population server boasts far more players with whom to communicate, trade and group, but may feature waiting times simply to log into the game, and users may experience lag and server stress problems at peak times. On lower population servers there are fewer other players to group with, making non-cross-realm features such as an arena, trading and serious end-game play much harder to achieve. However, players do not have to queue to play the game, and lag and server problems are minimal.\r\nThe population can also affect play within the larger game world. High population servers may feature far more competition for resources and quest mobs, and an increased chance of [[griefing]] or [[world PvP]], especially on [[PvP server]]s. In extreme cases, high numbers of players in busy areas can cause long queues to complete quests, or even cause the server to crash. Lower population servers typically feature little such competition, but also make it harder to find other players with whom to interact. However, in extremely low population areas, the [[cross-realm zones]] feature may act to mitigate these differences by introducing players from other realms. This feature does not affect capital cities or most end-game zones but may improve the experience while leveling on lower population servers. While server population affects many areas of the game world, it has little impact on cross-realm aspects of the game, such as non-rated [[battleground]]s or dungeons queued for through the [[Dungeon Finder]].\r\n===Faction balance===\r\nAside from the overall population, each server features a different balance between the factions. Unlike the overall population, this information is not displayed in the server list, although it can be viewed through sites such as . The population of a character's faction is often far more important than the combined population of the server, and since many aspects of play including the [[auction house]] are faction-specific, individual characters' play experience is largely determined by this rather than by the total population. For example, a Horde character may play on a server highly populated with Alliance characters, yet find few other Horde characters with whom to play, trade, etc. [[World PvP]] is one area where the population of the opposite faction can be directly significant, especially on [[PvP server]]s.\r\n==Individuality==\r\nWhile different realms are almost identical in their game world, NPCs and rules, in practice each offers a slightly different playing experience, as well as a unique collection of players to encounter and interact with. While server type, population, and language are some of the more obvious differences between servers, there are many other factors that can lead to realms offering their own unique environment. \r\nAs separate instances of the game world, realms may develop their own reputation or sub-culture, specific to that server, or even to one faction of that server's population. The presence of well-known guilds or players may also affect the reputation of a realm, with some realms becoming well-known or notorious as a result of the actions of certain inhabitants.\r\nPlayer interaction ensures that each realm offers a unique experience, with communication and group play largely only available within a server. Aside from population and server type, some realms feature more guilds with a certain focus, such as rated battlegrounds or high-end raiding, with players sometimes choosing to transfer characters between servers in order to join a particularly prestigious or desirable guild. \r\n==Statistics==\r\nRealm statistics provide some interesting insight into overall player trends and certain differences between regions and server types. The following data was taken from , current for October 2015, and represents only the number of characters recorded on US and EU servers.\r\nFaction balance:\r\n* Total: 58% of characters are [[Alliance]]; only 42% are [[Horde]].\r\n* Alliance are slightly more popular with EU players than US players, with an A:H ratio of 59:41 for the EU, compared to 57:43 for the US.\r\n* Average faction balance depends heavily on realm type:\r\n** PvE servers in both the US and EU feature a heavy imbalance of Alliance characters, with an A:H ratio of 65:35.\r\n** PvP servers feature an imbalance of Horde characters, with an A:H ratio of 46:54 in the US, and 43:58 in the EU.\r\n** US roleplaying servers also feature more Alliance characters in PvE and more Horde in PvP, with an A:H ratio of 60:40 on RP servers, and 45:55 for RP-PvP servers.\r\n** EU roleplaying servers feature a heavy bias toward Alliance characters regardless of PvE or PvP, with an A:H ratio of 71:29 on RP servers, and 90:10 on RP-PvP servers.\r\nServer type:\r\n* Roleplaying realms\r\n** RP and RP-PvP servers combined account for around 15% of each region's characters. The RP:RP-PvP ratio is also very similar for both regions, heavily favoring PvE, with RP servers containing around 77% of characters for the US and 81% for the EU, with RP-PvP having 23% and 19% respectively.\r\n* Non-roleplaying realms\r\n** US servers have slightly more characters on PvE realms, with a PvE:PvP ratio of 64:36.\r\n** EU servers have slightly more characters on PvP realms, with a PvE:PvP ratio of 41:59.\r\n==See also==\r\n*[[Realms list]]\r\n*[[Connected Realms]]\r\n*[[Cross-realm zones]]\r\n*[[Realm name lore]] - a list of all realm names, along with a brief description of the lore significance of each",},
			["Realms List"] = { content = "#redirect [[Realms list]]", redirect = "Realms list",},
			["Realm History"] = { content = "'''Realm History''' (\r\nWe recently added support for Guild Recruitment. It takes around 30 seconds for a guild member to submit his guild recruitment status and after the data is validated by a Realm History Administrator it will become visible on our site in the respective realm \"Guild Recruitment\" section but also in the worldwide \"Last Recruiting Posts\" page which will be browsed by players from all realms that are looking to transfer.\r\nAnother function which we just added is the Screenshot Gallery. You can either browse the screenshots from a specific realm or from all the realms and you can view the newest screenshots added, or the most popular ones.\r\n'''Realm Features:'''\r\n- Screenshot Gallery (new)\r\n- Guild Index\r\n- Guild Recruitment (new)\r\n- PvE Progression\r\n- Rare Crafts database\r\n'''Worldwide Features:'''\r\n- Instance Status\r\n- Guild Search by PvE progress and Recruitment Status (new)\r\n- Last Recruiting Guilds (new)\r\n- Last Downed bosses\r\n- Screenshot Gallery (new)\r\nThe idea behind this site was to come with a fresh take on the whole handling of data that realm communities feel the need to record during their process of organization. The painful updating of endless threads on the official forums, dealing with cumbersome excel tables or rudimentary hosted charts constituted the drive of the project and we think we have come to the point where we are able to offer an easy, fast and appealing interface for best reading and appealing interface for best reading and updating your realm's guild index, PVE progression and rare crafts' list.\r\nAt the moment our incipient network provides services for about a dozen of realm communities and around another dozen is being brought up to date by our administrators so as to be released in the near future. For information on how to host your realm on Realm History please drop by and leave us a note on our forums, Affiliation section.",},
			["Realm Name Lore"] = { content = "#redirect [[Realm name lore]]", redirect = "Realm name lore",},
			["Reanimated Corpse"] = { content = "'''Reanimated Corpse''' can be found in [[Scholomance]].\r\nIt moves real slow so kill it quickly, before it touches you and cast Dark Plague on you. When it returns to life again, dps it down quickly, this time it will stay down.\r\n==Rewards==\r\n'''Reputation ([[Agent Dawn]])''': +5",},
			["Reaver's Fall"] = { content = "'''Reaver's Fall''' is a small [[Horde]] settlement between the [[the Legion Front]] and [[Thrallmar]] (). [[Forward Commander To'arch]] assigns tasks to Horde adventurers who report there. [[Supply Officer Isabel]] does equipment repair. The encampment takes its name from the fact that it is constructed from the remains of a destroyed [[Fel Reaver]]. This is the location where Horde members can complete \"bombing runs\" on the back of a flying mount in order to disrupt the forces of the Burning Legion.",},
			["Rebel Camp"] = { content = "The '''Rebel Camp''' is a camp of former men of [[Colonel Kurzen]]. It is situated in the northernmost part of [[Stranglethorn Vale]], just west of the road leading south from [[Duskwood]] and northwest of [[Kurzen's Compound]]. These soldiers have their task set: To overthrow their former master, Kurzen. Their leader is [[Lieutenant Doren]].\r\nAs of [[Patch 2.3]], a new Alliance flight path was added.\r\n===Flight===\r\n [[Stormwind City]]\r\n [[Sentinel Hill]]\r\n [[Darkshire]]\r\n [[Booty Bay]]",},
			["Rebirth"] = { content = "''Birth: it's less painful the second time.''\r\n'''Rebirth''' is the [[Druid]] [[resurrection]] ability that will restore a [[player character]] from their [[corpse]] with partial [[health]] and [[mana]]. The spell can be cast in combat and is interrupted when attacked. [[Nature's Swiftness]] allows this spell to become instant cast.\r\n==Notes==\r\n* You must have a reagent in order to cast this spell.\r\n* Take note of the 20 min. cooldown. (Reduced from 30 minutes in patch 2.3)\r\n* This is the only resurrection ability that can be used [[Formulas:In combat|in combat]].\r\n* Other [[Class|classes]] have similar spells but usually with slightly different requirements and effects:\r\n** [[Paladin]]: [[Redemption]]\r\n** [[Priest]]: [[Resurrection]]\r\n** [[Shaman]]: [[Ancestral Spirit (Shaman Spell)|Ancestral Spirit]]\r\n==Tips and tactics==\r\n*Due to a lengthy cooldown and the use of a reagent, this spell should only be used in emergency situations.\r\n*The spell's unique advantage over other classes' resurrection spells is that it allows resurrection ''during'' combat (in fact most players refer to the spell as \"Battle Res\" instead of \"Rebirth\"). From a balance point of view this explains why Blizzard put the 20 minute cooldown on it (30 mins prior to patch 2.3). Without a significant cooldown it could be possible for a raid that has nearly [[Wipe|wiped]] to be completely resurrected without breaking combat with the boss.\r\n*In raids, another common use would be to resurrect a [[tank]] that has been killed so that they can regain [[aggro]] on either the boss or any adds that may be present.\r\n*Due to the short cast time, Rebirth can be used like a short-term [[Soulstone]]. If a party is going to wipe and a member of a class with a resurrection spell has already died, the Druid can cast Rebirth on that player. The player receiving the Rebirth can wait until after the wipe to accept the resurrection and then continue to resurrect the rest of the party. This is an unconventional use of Rebirth and should only be done with good communication, as it achieves no benefit and wastes the cooldown if the resurrected player accepts before the wipe is complete. Also note that the player this is cast on needs to have died outside of the [[aggro range]] of the boss. '''Make sure the healer you use this tactic with doesn't have any mods that auto-accept resurrection spells!'''\r\n* On very rare occasions, the threat attached to restoring X hitpoints to a player, along with their life, can cause an aggro switch.\r\n* Should you ever feel generous enough to rez a corpse found at the side of the road, check to see if it's flagged PvP first!",},
			["Reborn From The Ashes"] = { content = "==Objectives==\r\nGather [[Bolvar Fordragon|Fordragon's]] Shield from the field of battle at [[Angrathar the Wrath Gate]] and return it to [[Varian Wrynn|King Varian Wrynn]] at [[Stormwind Keep]] in [[Stormwind City]].\r\n* Fordragon's Shield\r\n==Description==\r\nOur fate is emblazoned upon our souls at birth. Bolvar's fall, while tragic, was unavoidable.\r\nAll that you can do now is honor your hero, <name>. Collect Bolvar's shield from the field of battle and return it to your king. When you present the shield to Varian, tell him this: \"All is not lost. From the ashes of the fallen will rise a force that will unite nations and purge the evil from this world.\"\r\nHe mustn't lose faith. Go now, <name>. Your people need a hero. They need you. \r\n==Progress==\r\n<King Wrynn brushes away a tear.>\r\n<King Wrynn nods.>\r\nThis is my fault.\r\n==Completion==\r\nThe Dragon Queen is right, <name>. All is not lost. I will be the force that rises from the ashes and I will purge the evil of the [[Horde]] from this world. The deaths of our brothers and sisters will not have been in vain.\r\n==Notes==\r\nFordragon's shield is about 10 yards west of Alextrasza's left foreleg at .\r\nAll is normal in Stormwind, though Jaina has showed up and is standing next to Varian.",},
			["Rebuff"] = { content = "The act of renewing beneficial spells that \"[[buff]]\" or improve the target. (e.g., Recasting [[Power Word: Fortitude]] on a party member to reset its expiration.)",},
			["Recipe"] = { content = "A set of required [[ingredient]]s that can make or produce an [[item]] depending on a required [[profession]] or [[class]] and a required level. This can be in the form of an item (like a note, parchment or scroll) or given by a [[trainer]]. When in the form of an item, they are sometimes found (in limited supply) on [[vendor]]s throughout the world, or as drops from [[mob]]s. In the game manuals they are sometimes called '''blueprints'''.\r\nNotes:\r\n* [[Tailoring]] and [[Leatherworking]] recipes are called [[Pattern]]s.\r\n* [[Engineering]] recipes are called [[Schematic]]s.\r\n* [[Enchanting]] recipes are called [[Formula]]s.\r\n* [[Alchemy]] and [[Cooking]] recipes are called '''Recipes'''.\r\n* [[Blacksmithing]] recipes are called [[Plans]].\r\n* [[Jewelcrafting]] recipes are called [[Design]]s.\r\n* Most [[First Aid]] recipes are called [[Manual]]s, although one is a [[Formula]].\r\nRecipe names are, to an extent, interchangeable. For example, it's not uncommon to see people referring to ANY recipe, be it jewelcrafting, alchemy, etc as a \"pattern\", \"plans\" or \"design\".\r\n==See also==\r\n* [[:Category:Recipes]]\r\n* [[:Category:Ingredients]]",},
			["Recipes"] = { content = "#REDIRECT [[Recipe]]", redirect = "Recipe",},
			["Recipe: Charred Bear Kabobs"] = { content = "==Source==\r\nThis item can be purchased for 2 gold copper from:\r\n* Bale in [[Felwood]]\r\n* Malygen in [[Felwood]]",},
			["Recipe: Elixir of Major Firepower"] = { content = "==Source==\r\nThis item is a reputation reward; you must be [[Revered]] with [[The Scryers]] to purchase it for g=6 gold from Quartermaster Enuril in [[Shattrath City]]. \r\nAn [[Elixir of Major Firepower]] increases the imbiber's ''fire'' spell damage by up to 55 for 1 hour.",},
			["Recipe: Goblin Rocket Fuel"] = { content = "==Source==\r\nThis item is created with [[Goblin Engineering]] (205); taught by trainers.",},
			["Recipe: Golden Fish Sticks"] = { content = "==Source==\r\nThis item can be purchased for g=3 gold from:\r\n* Rungor in [[Terokkar Forest]]\r\n* Innkeeper Biribi in [[Terokkar Forest]]",},
			["Recipe: Greater Fire Protection Potion"] = { content = "==Source==\r\nThis item drops from:\r\n* [[Firebrand Pyromancer]] in [[Blackrock Spire]]\r\n* [[Firebrand Invoker]] in [[Blackrock Spire]]",},
			["Recipe: Greater Frost Protection Potion"] = { content = "</noinclude>",},
			["Recipe: Greater Nature Protection Potion"] = { content = "'''Recipe: Greater Nature Protection Potion''' drops from Decaying Horrors and Rotting Behemoths in [[Weeping Cave|The Weeping Cave]] of [[Western Plaguelands]].",},
			["Recipe: Greater Shadow Protection Potion"] = { content = "==Source==\r\nThis item drops from:\r\n* [[Shadowmage]] in [[Eastern Plaguelands]]\r\n* [[Dark Adept]] in [[Eastern Plaguelands]]",},
			["Recipe: Juicy Bear Burger"] = { content = "==Source==\r\nThis item can be purchased for 2 gold copper from:\r\n* Bale in [[Bloodvenom Post]], [[Felwood]]\r\n* Malygen in [[Talonbranch Glade]], [[Felwood]]",},
			["Recipe: Shadow Protection Potion"] = { content = "==Source==\r\nThis item can be purchased for s=9 gold from:\r\n* Christoph Jeffcoat in [[Hillsbrad Foothills]]\r\n* Harklan Moongrove in [[Ashenvale]]",},
			["Recipe: Spicy Crawdad"] = { content = "'''Recipe: Spicy Crawdad''' teaches you how to cook a [[Spicy Crawdad]].\r\n==Source==\r\nThis recipe is sold by:\r\n*[[Rungor]], the trade goods vendor in [[Stonebreaker Hold]], [[Terokkar Forest]]\r\n*[[Biribi]], the innkeeper in [[Allerian Stronghold]], [[Terokkar Forest]]",},
			["Recipe: Transmute Primal Might"] = { content = "==Source==\r\nThis item can be purchased for 8 gold copper from:\r\n* Melaris in [[Silvermoon City]]\r\n* Altaa in [[The Exodar]]\r\n* Skreah in [[Shattrath City]]\r\n==Notes==\r\nPerforming this transmute causes a 20-hour cooldown on your [[Philosopher's Stone]].",},
			["Reclaiming Sunstrider Isle"] = { content = "'''Reclaiming Sunstrider Isle''' is the starter [[quest]] for [[Blood Elf]] players. This is a blood elf only quest and gives access to two quest chains.\r\n==Objectives==\r\nKill 8 Mana Wyrms; they are located close to the [[Burning Crystal]]s that are adjacent to the tower and gazebo. Return to [[Magistrix Erona]] at the tower on [[Sunstrider Isle]] when you are done.\r\n* Mana Wyrm slain (8)\r\n==Description==\r\nThe sooner you begin your education, <name>, the better for us all. There is little room for error, so listen closely.\r\n[[The Burning Crystals]] - the green floating objects to the west of the [[Sunspire]] here - have long been used to power the isle's experimentations. The mana wyrms were their guardians, but the [[Scourge]] invasion of [[Quel'Thalas]] has driven them errant from our lack of magical control over them.\r\nThere is little choice but to thin their numbers for reclamation. Do this, then return to me.\r\n==Progress==\r\nOur work in rebuilding our society begins here, <name>. Once we are able to secure our home, we can look outward and upward.\r\n==Completion==\r\nYou have successfully completed your first task; for that, you are to be congratulated. Such success gives me faith that you will turn out better than those young blood elves who fail to heed the lessons of their masters. Continued success will be rewarded - not only with knowledge, but also with tangible rewards as well.\r\nYour work here, however, is not finished. There is much more to learn, my young friend...\r\n==Reward==\r\n* You will receive 30 copper \r\n==Gains==\r\n* 100 [[XP]]\r\n* 250 [[reputation]] with [[Silvermoon City]]\r\n==Notes==\r\nKilling the eight Mana Wyrms will give you exactly the [[experience]] needed to reach the second level.\r\nThe Mana Wyrms are quite plentiful and will most likely be the first creature you encounter near Magistrix Erona, they are not aggressive and will not attack you until you attack them.",},
			["Record of Defias Activity"] = { content = "The following is a composite account of all known activities of the [[Defias Brotherhood]] up to and including their involvement in the World of WarCraft game. Almost everything listed below either occurs or is otherwise documented in-game.\r\n==Early History==\r\n* The human [[Edwin VanCleef]] grows up in the city of [[Stormwind]]. He trains as a rogue alongside his childhood friend, [[Master Mathias Shaw|Mathias Shaw]]. Eventually VanCleef joins the society known as the [[Stonemasons]], establishing a network of clandestine contacts.\r\n* The [[Horde]] wins the [[First War]], seizing control of the kingdom of Stormwind and driving its inhabitants into exile. The city of Stormwind itself is burned to the ground.\r\n* Six years later, the [[Alliance of Lordaeron]] achieves supreme victory over the Horde and is able to reclaim its holdings.\r\n* [[Terenas Menethil II|Terenas Menethil]], king of [[Lordaeron]], offers to rebuild the ruined city of Stormwind. To accomplish this reconstruction, heavy taxes are introduced among all the member nations of the Alliance.\r\n* The newly reformed Stormwind [[House of Nobles]] contracts the remaining [[Stonemasons]] to perform the physical rebuilding of the city using the resources raised by Terenas.\r\n* After several years, the project is completed. The Stonemasons then approach the House of Nobles seeking payment for their work. The Nobles, however, admonish the Stonemasons for not performing the service to the Alliance out of the kindness of their hearts.\r\n* Alienated and enraged, many of the Stonemasons rally behind Edwin VanCleef. VanCleef makes impassioned pleas to the Nobles for payment, but the Nobles continue to refuse.\r\n* After much argument and debate, VanCleef and his followers leave Stormwind, going into hiding in the nearby wilderness.\r\n==Origins of the Brotherhood==\r\n* VanCleef's followers soon form a secret organization called the Defias Brotherhood.\r\n* Needing a base for their plans, the Defias cultivate a hideout in the heart of the [[Deadmines]] cave system in southern [[Westfall]], concealing the entrance inside a barn in the town of [[Moonbrook]]. VanCleef names [[Bazil Thredd]] his second-in-command.\r\n* Utilizing many of his contacts from his Stonemason days, VanCleef lures more members into the Defias. The Brotherhood begins to change its form from alienated Stonemasons to a coalition of brigands and thieves.\r\n* Stationing his men at key points along the main river that runs through the kingdom, VanCleef is able to create a network of communication and transport that stretches from the [[Redridge Mountains]] west to Stormwind, and south as far as [[Booty Bay]].\r\n* Around this same time, VanCleef makes valuable contacts inside the [[House of Nobles]] itself; most notably in the form of [[Lord Gregor Lescovar]]. Though Lescovar and his lackeys refuse to be made VanCleef's subordinates, the two men manage to reach an uncomfortable agreement, and begin working to destroy Stormwind from within.\r\n* Goblin engineers are contracted by VanCleef to work in the Deadmines, building mechanical [[Harvest Golem|Harvest Golems]] that resemble scarecrows.\r\n* VanCleef also buys out the [[Riverpaw]] gnolls, hiring them as thugs and stationing them throughout Westfall.\r\n* At some point, the Stormwind army mysteriously disappears to fight the Horde in foreign lands. This departure leaves Stormwind and its provinces of [[Goldshire]], [[Lakeshire]], [[Darkshire]] and [[Westfall]] completely defenseless. VanCleef knows the time has come to make his move.\r\n==Conquest of Westfall and Elwynn==\r\n* The Defias spill out of the Deadmines, taking complete control of the town of [[Moonbrook]] and scattering the townsfolk across the region.\r\n* The Defias attack the [[Alexston Farmstead]], the family farm owned by [[Baros Alexston]], a former Stonemason who did not join with VanCleef. The Defias deploy goblin-made [[Harvest Golem|Harvest Golems]] to frighten off the inhabitants.\r\n* Defias Pathstalkers, Knuckledusters and Highwaymen set up camps in the [[Dagger Hills]] south of Moonbrook.\r\n* The Defias attack the farms called [[The Dead Acre]] and [[Demont's Place]], burning the houses there to the ground.\r\n* Defias agents led by [[Benny Blaanco]] attack [[Furlbrow's Pumpkin Patch]] , running off the families that live there and placing [[Harvest Golem|Harvest Golems]] in the fields.\r\n* The Defias take control of [[The Molsen Farm]] and [[The Jansen Stead]], also with the aid of mechanical golems.\r\n* [[Farmer Saldean]] and his family refuse to leave their farm, holing themselves up in their farmhouse.\r\n* The Defias take control of Westfall's two remaining mines, the [[Jangolode Mine]] and the [[Gold Coast Quarry]].\r\n* Defias agents led by [[Klaven Mortwake]] capture the mage tower in southeastern Westfall and begin using the docks located there.\r\n* The surviving inhabitants of Westfall finally gather under the leadership of the paladin [[Gryan Stoutmantle]], who forms the [[People's Militia]] to protect the populace from further harm.\r\n* After the successful taking of Westfall, VanCleef sets his gaze on Elwynn Forest, immediately surrounding Stormwind. Seeing that Stormwind will offer no response to his actions in Westfall, VanCleef first sends in his lackeys, the [[Riverpaw]] Gnolls, who set up a sizable camp at [[Forest's Edge]] along the border of Elwynn and Westfall. The Defias will use this gnoll camp as a staging ground for their campaign into Elwynn.\r\n* The Defias set out to take control of Elwynn's southern farmsteads. Men led by [[Erlan Drudgemoor]], [[Surena Caledon]] and [[Morgan the Collector]] take over the [[Brackwell Pumpkin Patch]], while other groups seize the [[Maclure Vineyards]], the [[Stonefield Farm]] and the [[Mirror Lake Orchard]].\r\n* Defias agents secure [[Jerod's Landing]], a property conveniently located along the river, and take advantage of the dock located there.\r\n* Defias agents under the command of [[Dead-Tooth Jack]] set up a camp near [[Ridgepoint Tower]] in southeastern Elwynn.\r\n* Defias under the command of [[Garrick Padfoot]] penetrate the guarded valley of [[Northshire]] and capture the lucrative [[Northshire Vineyards]].\r\n* Finally, the Defias organize the capture of various mines throughout Elwynn: the [[Jasperlode Mine]], [[Fargodeep Mine]] and [[Echo Ridge Mine]]. [[Kobold]] gangs are commissioned to begin mining at these locations.\r\n* Some time after the offensive in Elwynn, a small number of Defias agents also expand into [[Duskwood]], taking over the farms at [[Addle's Stead]] and [[The Yorgen Farmstead]]. Among these is the man who will later be known as [[Jitters]].\r\n==Underground Operation==\r\n* The Defias are now ready to proceed with the next phase of the plan. Steel, copper and other minerals are harvested in large quantities from the captured mines and collected in the [[Deadmines]]. Wood timber felled in Westfall and materials gathered in Redridge (perhaps by the Redridge Gnolls) are also stored in the caves, as are minerals harvested within the Deadmines themselves.\r\n* VanCleef contracts a number of Goblin Shipbuilders, stationing them within the Deadmines. There the goblins begin construction on VanCleef's secret weapon of mass destruction: a giant [[Juggernaut]], modeled on the orcish warships used during the [[Second War]]. The Lumbermaster [[Sneed]] constructs a [[Mast Room]] within the mines, using the space to create masts and wooden rigging for the Juggernaut.\r\n* A team of Goblin Craftsmen are called upon to create a massive Foundry in the mines. The Foundry is used to process ore into metals used in the construction.\r\n* The Defias enter into an agreement with the [[Bloodsail Buccaneers]] of southern [[Stranglethorn Vale]]. The Bloodsail leader, [[Fleet Master Firallon]], sends a crew of his pirates led by [[Captain Greenskin]] the goblin to man VanCleef's new vessel.\r\n==Fighting Back==\r\n* The first blow to the Defias Brotherhood's power base occurs in [[Northshire Valley]], where the locals under the leadship of [[Marshal McBride]] manage to wrest control of the [[Echo Ridge Mine]] from the Defias-employed [[Kobolds]]. Believing the Kobolds to be a nuisance unto themselves, however, the liberators fail to connect the vermin with the Defias.\r\n* Agitated by the actions of the Defias, [[Marshal McBride]] places a bounty on their ringleader in [[Northshire Valley]], one [[Garrick Padfoot]], which leads to his death. Padfoot's band is driven off from the [[Northshire Vineyards]] soon after.\r\n* Next, the Defias lose control of the [[Fargodeep Mine]] just south of the town of [[Goldshire]], as adventurers set out to explore the mine at the behest of [[Marshal Dughan]], and collect candles and gold dust from the Kobolds for [[William Pestle]] and Remey Two-times. Similar conditions also result in the liberation of the distant [[Jasperlode Mine]] in eastern Elwynn.\r\n* The Defias scoundrel [[Dead-Tooth Jack]] steals the tabard of a Stormwind Marshal, using it as a disguise that fools the near-blind [[Marshal Haggard]]. Jack tricks Haggard into giving up his Marshal's badge, but this ironically leads to Jack's end; for Haggard enlists a local warrior to deal with the brigand and reclaim the badge.\r\n* [[Master Mathias Shaw|Mathias Shaw]], leader of the Stormwind intelligence organization known as [[SI:7]], plots a successful infiltration of the Defias dock site at [[Jerod's Landing]], leading to the recovery of valuable Defias shipping information.\r\n* The notorious Defias warlock, [[Surena Caledon]] also meets her death in the days following the Elwynn offensive, as the warlock coven in Stormwind declares her life forfeit. She and her lover, [[Erlan Drudgemoor]] are slain by one of the coven's junior members, and Surena's choker is recovered on the orders of [[Gakin the Darkbinder]], the warlock who once instructed Surena. The choker is then used by Gakin in an incantation to summon and subdue a voidwalker.\r\n* Around this time, VanCleef's second-in-command, [[Bazil Thredd]] is captured and placed in the [[Stormwind Stockade]].\r\n* Meanwhile, the rogue [[Wiley the Black]] manages to infiltrate the Defias organization, learning much about their goals and endeavors. He remains quiet, however, out of fear.\r\n* Perhaps most damaging to VanCleef's agenda comes the death of [[Morgan the Collector]], who was stationed with Caledon and Drudgemoor in Elwynn Forest. Morgan had served as VanCleef's chief lieutenant in Elwynn and he effectively ran the Elwynn operation, facilitating the transport of gold and other materials from the Elwynn mines to the Deadmines. Morgan's communications were carried by the [[Riverpaw]] Gnolls, because Morgan believed this would keep them from being discovered by agents of Stormwind. That plan failed, however, as a raid upon the gnoll camp in [[Forest's Edge]] resulted in [[Marshal Dughan]] recovering a particularly damaging message from Morgan, including a schedule of shipments. In short order, the leaked information leads to Morgan's assassination and the end of the Defias mining operation in Elwynn Forest.\r\n==The People's Militia==\r\n* Meanwhile, the [[People's Militia]] based at [[Sentinel Hill]] are facing their own Defias problems. The locals have been run off their family farms, and the township of [[Moonbrook]] has been completely overrun by the Defias brigands.\r\n* [[Gryan Stoutmantle]], leader of the Militia, is driven to desperation by the grim events, and finally contacts the rogue known as [[Wiley the Black]], based in [[Lakeshire]]. Though fearful of the Defias, Wiley owes Stoutmantle his life, and so consents to share what information he knows of the Defias. Wiley reveals the true scope of the Defias operations, which he claims stretch from Stormwind all the way to [[Booty Bay]]. He accurately claims that the Defias control every mine in Elwynn and Westfall, and that they are using the resources from these mines to fund a weapon of mass destruction.\r\n* Additionally, Wiley hints that the Defias are in fact related to the [[Stonemasons]] that rebuilt Stormwind City. Stoutmantle has this connection confirmed to him by [[Master Mathias Shaw|Mathias Shaw]] of [[SI:7]], a childhood friend of Edwin VanCleef's and something of an expert on the Stonemasons. Still, Stoutmantle seeks further proof of VanCleef's guilt.\r\n* This proof comes with the interception of a [[Defias Messenger]] bearing instructions from VanCleef himself. His note claims that their mysterious project is nearing completion, and that the time has come to strip everything that isn't nailed down in their other holdings. The note is retrieved for Stoutmantle, who can no longer deny VanCleef's involvement with the Defias and orders his assassination.\r\n* Around this time, a [[Defias Traitor]] is captured attempting to steal [[Farmer Saldean]]'s wagon. In exchange for his life, the traitor betrays his Defias brothers and reveals the exact location of the entrance to VanCleef's hideout in the [[Deadmines]].\r\n* Stoutmantle at last contracts a party of adventurers, who infiltrate the [[Deadmines]] on his orders, causing massive damage to the mining, smelting and ship construction operations going on there and finally succeeding in assassinating [[Edwin VanCleef]].\r\n==The Brotherhood After VanCleef==\r\n* Rather than ending the Defias threat, however, VanCleef's death only makes the Brotherhood more mysterious and difficult to track.\r\n* Shortly before his death, VanCleef pens a hasty letter to fellow former [[Stonemasons|Stonemason]] [[Baros Alexston]], presumably begging Alexston's support of the Defias. As a city architect, Alexston has valuable connections to the [[House of Nobles]] which might have made people like [[Lord Gregor Lescovar]] obsolete.\r\n* VanCleef does not live long enough to send the letter; however, his killers deliver to Alexston. Predictably, Alexston wants nothing to do with VanCleef's mad schemes. After all, it was the Defias who ran off Alexston's family from their [[Alexston Farmstead|farm]] in [[Westfall]]; one would hardly expect him to be sympathetic to the Defias or their aims.\r\n* Alexston suggests that the prisoner [[Bazil Thredd]], might be of use in recovering information on the Defias, since Thredd had been VanCleef's second-in-command prior to the former's capture and imprisonment in the [[Stockade]]. Getting information out of Thredd, however, might be difficult...\r\n==The Stockade Riots==\r\n* For many months, the Defias underboss [[Bazil Thredd]] had no visitors as he languished in the [[Stormwind Stockade]], and it was presumed by his jailors that he had outlived his usefulness to the Defias Brotherhood. All that changed shortly before the death of [[Edwin VanCleef]], however, when Thredd began to receive frequent visits from the assassin [[Marzon the Silent Blade]] (under the alias of Maelik).\r\n* Marzon then facilitated a sort of three-cornered conversation, carrying messages between Thredd, VanCleef and [[Lord Gregor Lescovar]] the Noble. As VanCleef's Stormwind support, Thredd and Lescovar masterminded a grand uprising within the Stockade, planned to esnure the mass breakout of Thredd and many other Defias underlings.\r\n* [[Nikova Raskol]]'s teenage grandson Mac was working as a guard in the Stockade when riots began. Mac had previously chastised the Defias inmates for creating their iconic crimson masks out of fabric ripped from their pillowcases; as punishment for this, he was one of the first casualties of the riots, stabbed in the back by the men he had disciplined.\r\n* In orchestrating the riots, Thredd succeeded in inducting many of the other prisoners into the Defias Brotherhood, including those who might not have been a part of the Brotherhood prior to the riots. Among these were:\r\n** [[Dextren Ward]], a human from [[Darkshire]] who was imprisoned in The Stockade for selling bodies to the necromancer, [[Morbent Fel]]. Ward was sentenced to death by [[Lord Ello Ebonlocke]] and the Darkshire Council, but the Stormwind Nobles refused to carry out the execution.\r\n** [[Targorr the Dread]], a [[Blackrock Clan]] orc who previously served as an executioner and torturer under the warlord [[Gath'Ilzogg]] in [[Redridge Mountains]]. Like Ward, Targorr's death sentence was suspended by a Noble (presumably Lescovar), either because of his usefulness to Thredd or for some other, unknown reason.\r\n** [[Kam Deepfury]], a [[Dark Iron]] dwarf and political prisoner who was previously responsible for the attack on the [[Thandol Span]].\r\n** [[Hamhock]], a terrible two-headed ogre.\r\n** [[Bruegal Ironknuckle]], a dwarf prisoner of little apparent consequence.\r\n* Though the chaos cause by The Stockade uprising is significant, it is not enough to win the inmates' escape, and the revolt is eventually put down. Thredd and the other ringleaders are killed during the fighting.\r\n==The Attack==\r\n* After Thredd's death, investigation commences regarding his mysterious contact, Maelik. [[Master Mathias Shaw|Mathias Shaw]] correctly identifies Maelik as an alias of the assassin [[Marzon the Silent Blade|Marzon]], known to be under the employ of the Noble [[Lord Gregor Lescovar]]. Though this points to Lescovar as being in league with Thredd and VanCleef, his Noble status makes the Lord effectively invulnerable from the likes of Shaw who work 'within the system'.\r\n* In order to bring Lescovar to justice, Shaw enlists the aid of his peer and rival, the secretive spymaster [[Elling Trias]]. Unlike Shaw, Trias heolds no official connection to Stormwind and is free to do as he likes. Moreover, the secrecy surrounding Trias' true profession, aided by the cover of his successful cheese shop, gives him the ability to operate outside the law.\r\n* As it happens, Trias has had his own agent (the gnome [[Tyrion]]) observing Lescovar for weeks. At Trias's instruction, Tyrion organizes a meeting in the gardens of [[Stormwind Keep]] between Lescovar and Marzon, niether of whom appear to know that both Thredd and VanCleef are dead. Marzon bears a message to Lescovar from VanCleef himself, warning that [[Gryan Stoutmantle]]'s men have been seen 'snooping around'. In the middle of the meeting, Lescovar and Marzon are ambushed by one of Trias's operatives, and killed.\r\n* In reward, [[Baros Alexston]] secures an audience between Lescovar's killer and the King of Stormwind, [[Varian Wrynn]]. At the audience, however, the agent is received not by the king but by the Noble [[Lady Katrana Prestor]], who explains that the king is away on a diplomatic mission.\r\n==The Missing Diplomat==\r\n* In truth, the King's mission has gone awry. The King himself has been captured! This is of course a closely guarded secret within Stormwind, as is the fact that the King is the diplomat who's gone missing. The Defias are suspected to have been involved, although any further information is classified.\r\n* The Defias first attempt to apprehend the King at some point previous, by use of an underground tunnel connected somehow to Stormwind (possibly the [[Deeprun Tram]], or even the [[Stockade]]). The dwarf [[Dashel Stonefist]], a.k.a. 'Fist', successfully switches out the rosters of guards in the tunnel, allowing the Defias agents to infiltrate the area where the King will be. However, the infiltrators have a run of bad luck and a group of adventurers from Stormwind intervene, allowing the King to elude capture.\r\n* Their contingency plan is more successful. While the King and his retainers board ship in Menethil Harbor, [[Tapoke \"Slim\" Jahn]] helps [[Private Hendel]] of the Theramore marines to acquire station aboard the King's ship.\r\n* With Hendel in position and other, unknown allies of the Defias (possibly either Strashaz [[Naga]] or members of the [[Black Dragonflight]]) waiting closer to Theramore, the trap is sprung. The King is captured a few miles offshore from Theramore, where he intended to meet with [[Jaina Proudmoore]]. The King is imprisoned temporarily in an underground cell on [[Alcaz Island]], guarded by Naga warriors.\r\n* Back in Stormwind, [[Bishop DeLavey]] attempts to discreetly investigate the King's disappearance. Through the aid of his assistant [[Thomas]], whom he has set up as an altar boy within the [[Cathedral of Light]], DeLavey enlists the aid of an adventurer in investigating the diplomat's disappearance. His other options exhausted, DeLavey sends his new agent to his contact, [[Jorgen]], who in turn sends the agent to [[Elling Trias]] with a letter of introduction.\r\n* Trias, though irritated at DeLavey and Jorgen's presumption, immediately suspects Defias involvement and promptly takes the matter into his own hands. His own contact, [[Watcher Backus]], has been planted within the ranks of the [[Night Watch]] in [[Darkshire]], and has been keeping watch over Defias activity in the area for some time.\r\n* Backus recounts a large gathering of Defias some time previous, out at the farmstead called [[Addle's Stead]] in the middle of the night. Investigation of the farm leads to the recovery of a [[Defias Docket]].\r\n* The contents of the Docket lead Trias to 'Fist', who in turn fingers 'Slim', who in turn fingers Hendel.\r\n* DeLavey's agent apprehends Hendel in Theramore just as news of the plot reaches Lady Proudmoore, and she takes the traitor into custody.\r\n* Some time after, the King escapes from his cell on Alcaz Isle and attempts to swim to safety; however, he loses his memory and washes up in Durotar. Though his exploits continue after this point, the Defias have no real further involvement. You can read more about the ensuing events [[Varian Wrynn|here]].\r\n==A Note About Timing==\r\nThe quest system in World of WarCraft unfortunately gives little indication of time, and so the general time frame for the above events is largely subject to speculation. The later portion of the events, however, from VanCleef's death on, probably occur within a very short time of one another. Both The Stockade Riots and The Attack clearly occur soon after VanCleef's death, since Marzon and Lescovar do not appear to have heard that VanCleef is dead. Then, when Lady Prestor receives Lescovar's killer following The Attack, the King is already missing, meaning the Missing Diplomat chain is intended to occur around the same time (perhaps immediately after). It can be further inferred that while the kidnapping was carried out after the Deadmines project fell apart with VanCleef's death, the abduction was planned well before that time and therefore was likely VanCleef's brainchild.\r\nCompared to these two plots, both of which threaten all of Stormwind, it would appear that the Stockade uprising organized by Thredd and Lescovar was merely intended merely as a side project, which explains why VanCleef did not have a very heavy hand in it.",},
			["Recover the Key!"] = { content = "==Objectives==\r\n[[Elder Torntusk]] at [[Jintha'alor]] wants you to kill [[Hitah'ya the Keeper]] to get the [[Shackle Key (hinterlands)|Shackle Key]] to his bindings. Return to Elder Torn'tusk when you have recovered the key. \r\n*Shackle Key (hinterlands)\r\n==Description==\r\nThe key to my bindings is held by Hitah'ya the Keeper. She is in the nearby cave. Be careful, <class>, for she is guarded well.\r\nKill her and bring the key back to loosen my shackles. Only then will I be free to return home. \r\n==Progress==\r\nYou must hurry! \r\n==Completion==\r\nFreedom at last! Thank you, <name>. [[Revantusk]] will know your deeds! \r\n==Gains==\r\n*8800 [[XP]])",},
			["Red"] = { content = "The color <font color=\"#CC0000\">red</font> is used in [[World of Warcraft]] in various different ways. One way it may be used is as part of the [[Blizzard]] color system for items (gray, white, green, blue, purple, orange, red) or mobs (gray, green, yellow, orange, red). Probes into the code indicate that the highest ([[artifact]]) level of rarity has been switched to a dark yellow color referred to as gold (no relation to the metal [[gold]]).\r\n==Red Items==\r\nThere are no items with a '''red''' rarity level ([[Blizz]]ard has supposedly proposed gold as the replacement color). You may see though, items with various properties of that item Red. Thus meaning you can not use that item. For example a Weapon might have the words \"Mace\" in '''red''', that means your character can not use that item. Levels requirements and armor type may also effect your ability to use these items.\r\nFor the most part, in World of Warcraft, when items are '''red''' in some way, you can not use or obtain them yet. When browsing at a [[vendor]], some items will have a reddened icon. These cannot be used at this time, due to a requisite that is not met. When looting an item that you cannot use, however, its icon is ''not'' red. But in both cases, the tooltip that appears when you move the mouse over the item, it indicates the unmet requirement in red. In these cases, the item may be said to be red, even though it may also be said that it is [[blue]], [[green]], [[white]], or some other color.\r\n==Red Mobs==\r\n'''Red [[mob]]''' can mean any of two different things. Either:\r\n# The mob has a red name, meaning the mob simply is able to be [[aggro]]ed from some distance, or\r\n# the mob has a red level number and should be considered too difficult to defeat without help.\r\nAt very early levels, all mobs that you will meet will not by itself be aggroed to attack you. These such mobs will have a yellow name. From early on, however, you will see mobs that have red names. These mobs ''will'' automatically be aggroed. The aggro radius depends on the level differential, and can be either very close or very far away.\r\nAt all levels, you may see from time to time a mob that has a red level number. [[Gray]] and [[green]] mobs (having gray and green level indicators) should be easy for you to solo; [[yellow]] should be a little harder, but easy enough for a party of two; such red mobs should be considered rather dangerous, but you may be able to take them on with a party of three or more.\r\n==Red Names==\r\n'''Red names''' might refer to two different things:\r\n# the color of the name found above the [[player]] or [[mob]] in the main play screen, or\r\n# the color of the name found in the target pane at the top left of the screen.\r\nThe color of the name of a [[hostile]] mob in the main play screen will always be red. In the [[Player vs Player]] system, if two members of opposite factions were allowed to attack one another, each would appear with a red name to the other.\r\nIn the target pane, the name of a now-hostile (whether hostile or not by nature) mob will have either a yellow name with a red background, or it will have a yellow name with a [[gray]] background. The red background means that if it is killed, the credit will go to you and your party. The gray background means that if it is killed, the credit will go to someone else and his party.",},
			["Redeemed Avian"] = { content = "'''Redeemed Avian''' can be found in [[Terokkar Forest]] and [[Shattrath City]] .",},
			["Redeemed Hatchling"] = { content = "'''Malevolent Hatchling''' is a level 62 bird released from [[Cursed Egg]]s in [[Veil Lithic]] of [[Terokkar Forest]].\r\n==Objective of==\r\nNeed to be released for the quest Veil Lithic: Preemptive Strike.",},
			["Redemption"] = { content = ":''For other uses, see [[Redemption (disambiguation)]].''\r\n'''Redemption''' is the [[Paladin]] [[resurrection]] ability that will restore a [[player character]] from their [[corpse]] with partial [[health]] and [[mana]]. The spell cannot be cast in combat and is interrupted when attacked.\r\nRedemption is first obtained at level 12 through a quest. For Alliance Paladins, that is [[Quest:The Tome of Divinity|The Tome of Divinity]], which can be had from Tiza Battleforge, Duthorian Rall, or Jol. For the Horde, that quest is Summons from Knight-Lord Bloodvalor, which can be obtained from Noellene.\r\n==Notes==\r\nOther [[class]]es have similar spells but usually with slightly different requirements and effects:\r\n* [[Druid]]: [[Rebirth]]\r\n* [[Priest]]: [[Resurrection]]\r\n* [[Shaman]]: [[Ancestral Spirit (Shaman Spell)|Ancestral Spirit]]",},
			["Redemption Armor"] = { content = "'''Redemption Armor''' is the [[Tier 3]] set for Paladins. \r\n==Source==\r\nMost [[Tier 3]] items can be acquired through quests given by [[Eligor Dawnbringer]], who can be found in [[Light's Hope Chapel]] in the [[Eastern Plaguelands]]. Before the quests become active, [[Quest:Echoes of War|Echoes of War]] must be completed.\r\nThe quests require several crafting materials, Wartorn Plate Scraps (which drop from [[Trash Mob]]s in [[Naxxramas]]) as well as a token from a boss in [[Naxxramas]]\r\nThe only exception is the Ring of Redemption, which drops directly from [[Kel'Thuzad]] in [[Naxxramas]]\r\n==Notes==\r\nHoly Power (the 6-piece-Bonus) is a temporary buff that lasts 8 seconds. Depending on the class, a target recieves one of the following effects:\r\n* Warrior: +700 Armor\r\n* Hunter, Rogue: +140 Attack Power\r\n* Mage, Warlock: +80 Spell Damage and Healing\r\n* Paladin, Priest, Druid, Shaman: +28 mana per 5 seconds regeneration\r\nSee also: [[Set look alikes]]",},
			["Redemption Boots (quest)"] = { content = "This quest involves gathering items from Naxxramas to turn in for the [[Tier 3]] [[paladin]] boots, [[Redemption Boots]].\r\n==Objectives==\r\n*Desecrated Boots x1\r\n*Wartorn Plate Scrap x12\r\n*Arcanite Bar x2\r\n*Cured Rugged Hide x3\r\n==Description==\r\n''Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make Redemption Boots if you bring him the following: 1 Desecrated Boots, 12 Wartorn Plate Scraps, 2 Arcanite Bars and 3 Cured Rugged Hides.''\r\n[[Desecrated Boots]]: 0/1\r\n[[Wartorn Plate Scrap]]: 0/12\r\n[[Arcanite Bar]]: 0/2\r\n[[Cured Rugged Hide]]: 0/3\r\n''You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.''",},
			["Redemption Girdle (quest)"] = { content = "This quest involves gathering items from Naxxramas to turn in for the [[Tier 3]] [[paladin]] belt, [[Redemption Girdle]].\r\n==Objectives==\r\n*Desecrated Girdle x1\r\n*Wartorn Plate Scrap x8\r\n*Arcanite Bar x1\r\n*Nexus Crystal x3\r\n==Description==\r\n''Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make a Redemption Girdle if you bring him the following: 1 Desecrated Girdle, 8 Wartorn Plate Scraps, 1 Arcanite Bar and 3 Nexus Crystals.''\r\n[[Desecrated Girdle]]: 0/1\r\n[[Wartorn Plate Scrap]]: 0/8\r\n[[Arcanite Bar]]: 0/1\r\n[[Nexus Crystal]]: 0/3\r\n''You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.''",},
			["Redemption Handguards (quest)"] = { content = "This quest involves gathering items from Naxxramas to turn in for the [[Tier 3]] [[paladin]] gloves, [[Redemption Handguards]].\r\n==Objectives==\r\n*Desecrated Handguards x1\r\n*Wartorn Plate Scrap x8\r\n*Arcanite Bar x1\r\n*Cured Rugged Hide x5\r\n==Description==\r\n''Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make Redemption Handguards if you bring him the following: 1 Desecrated Handguards, 8 Wartorn Plate Scraps, 1 Arcanite Bars and 5 Cured Rugged Hides.''\r\n[[Desecrated Handguards]]: 0/1\r\n[[Wartorn Plate Scrap]]: 0/8\r\n[[Arcanite Bar]]: 0/1\r\n[[Cured Rugged Hide]]: 0/5\r\n''You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.''",},
			["Redemption Headpiece (quest)"] = { content = "This quest involves gathering items from Naxxramas to turn in for the [[Tier 3]] [[paladin]] headpiece, [[Redemption Headpiece]].\r\n==Objectives==\r\n*Desecrated Headpiece x1\r\n*Wartorn Plate Scrap x15\r\n*Arcanite Bar x5\r\n*Cured Rugged Hide x2\r\n==Description==\r\n''Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will a Redemption Headpiece if you bring him the following: 1 Desecrated Headpiece, 15 Wartorn Plate Scraps, 5 Arcanite Bars and 2 Cured Rugged Hides.''\r\n[[Desecrated Headpiece]]: 0/1\r\n[[Wartorn Plate Scrap]]: 0/15\r\n[[Arcanite Bar]]: 0/5\r\n[[Cured Rugged Hide]]: 0/2\r\n''You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.''",},
			["Redemption Legguards (quest)"] = { content = "This quest involves gathering items from Naxxramas to turn in for the [[Tier 3]] [[paladin]] legs, [[Redemption Legguards]].\r\n==Objectives==\r\n*Desecrated Legguards x1\r\n*Wartorn Plate Scrap x20\r\n*Arcanite Bar x4\r\n*Nexus Crystal x2\r\n==Description==\r\n''Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make Redemption Legguards if you bring him the following: 1 Desecrated Legguards, 20 Wartorn Plate Scraps, 4 Arcanite Bars and 2 Nexus Crystal.''\r\n[[Desecrated Legguards]]: 0/1\r\n[[Wartorn Plate Scrap]]: 0/20\r\n[[Arcanite Bar]]: 0/4\r\n[[Nexus Crystal]]: 0/2\r\n''You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.''",},
			["Redemption Spaulders (quest)"] = { content = "This quest involves gathering items from Naxxramas to turn in for the [[Tier 3]] [[paladin]] shoulders, [[Redemption Spaulders]].\r\n==Objectives==\r\n*Desecrated Spaulders x1\r\n*Wartorn Plate Scrap x12\r\n*Arcanite Bar x2\r\n*Nexus Crystal x2\r\n==Description==\r\n''Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make Redemption Spaulders if you bring him the following: 1 Desecrated Boots, 12 Wartorn Plate Scraps, 2 Arcanite Bars and 2 Nexus Crystals.''\r\n[[Desecrated Spaulders]]: 0/1\r\n[[Wartorn Plate Scrap]]: 0/12\r\n[[Arcanite Bar]]: 0/2\r\n[[Nexus Crystal]]: 0/2\r\n''You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.''",},
			["Redemption Tunic (quest)"] = { content = "This quest involves gathering items from Naxxramas to turn in for the [[Tier 3]] [[paladin]] chestpiece, [[Redemption Tunic]].\r\n==Objectives==\r\n*Desecrated Tunic x1\r\n*Wartorn Plate Scrap x25\r\n*Arcanite Bar x4\r\n*Cured Rugged Hide x3\r\n==Description==\r\n''Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make a Redemption Tunic if you bring him the following: 1 Desecrated Boots, 25 Wartorn Plate Scraps, 4 Arcanite Bars and 3 Cured Rugged Hides.''\r\n[[Desecrated Tunic]]: 0/1\r\n[[Wartorn Plate Scrap]]: 0/25\r\n[[Arcanite Bar]]: 0/4\r\n[[Cured Rugged Hide]]: 0/3\r\n''You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.''",},
			["Redemption Wristguards (quest)"] = { content = "This quest involves gathering items from Naxxramas to turn in for the [[Tier 3]] [[paladin]] bracers, [[Redemption Wristguards]].\r\n==Objectives==\r\n*Desecrated Wristguards x1\r\n*Wartorn Plate Scrap x6\r\n*Arcanite Bar x1\r\n*Cured Rugged Hide x2\r\n==Description==\r\n''Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make Redemption Wristguards if you bring him the following: 1 Desecrated Wristguard, 6 Wartorn Plate Scraps, 1 Arcanite Bar and 2 Cured Rugged Hides.''\r\n[[Desecrated Wristguards]]: 0/1\r\n[[Wartorn Plate Scrap]]: 0/6\r\n[[Arcanite Bar]]: 0/1\r\n[[Cured Rugged Hide]]: 0/2\r\n''You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.''",},
			["Redoubt"] = { content = "'''Redoubt''' was a talent in the Protection tree, you had to spend 3 points in Protection to max it.\r\n==Talent Overview==\r\n* It was not adequate to rely on this skill to be [[uncrushability|uncrushable]], as it proc'd off randomly.\r\n* For uncrushable tankadins, the extra blocking from Redoubt was useless when tanking a single target. However, during AoE tanking, where [[Holy Shield]] was sure to expire quickly, the frequent Redoubt procs helped mitigate significant amount of damage.",},
			["Redpath the Corrupted"] = { content = "'''Redpath the Corrupted''' is a level 60 [[elite]] [[undead]] found in the [[Eastern Plaguelands]].\r\nRedpath the Corrupted is the spirit of [[Joseph Redpath]] and spawns during the recreation of the [[Quest:The Battle of Darrowshire|Battle of Darrowshire]].\r\n==Quests==\r\n*The Battle of Darrowshire",},
			["Redridge"] = { content = "#REDIRECT [[Redridge Mountains]]", redirect = "Redridge Mountains",},
			["Redridge Canyons"] = { content = "The '''Redridge Canyons''', or Red Ridge Canyons, form a labyrinthine network of passages nestled in the northwestern [[Redridge Mountains]]. Although it used to be a favored spot for hunting deer and mountain boar by the local populace, it has been claimed by a tribe of gnolls led by the ferocious [[Yowler]], and it is no longer a safe place to venture.",},
			["Redridge Mountains"] = { content = "The '''Redridge Mountains''' (also known as the '''Red Ridge Mountains''', the '''Redridge Range''', or simply '''Redridge''') are located east of [[Elwynn Forest]], northeast of [[Duskwood]], and south of the [[Burning Steppes]]. Although it may be considered [[contested]], [[Horde]] characters have no settlements or NPCs and it is thus a place they use mostly for passing through to reach [[Flame Crest]] or [[Stonard]].\r\nAn idyllic region of rushing rivers, towering elms and rising elevations, the Redridge Mountains are under [[Stormwind|Stormwind's]] protection. Their inhabitants supply Stormwind with timber, fish, and crops. A force of [[Blackrock clan|Blackrock]] orcs from the Burning Steppes has once secured [[Stonewatch Keep]], but are still in control of the northern roads. In comparison with Westfall, Redridge is still relatively stable.\r\nOn the western bank of [[Lake Everstill]] is the [[Alliance]] town of [[Lakeshire]], the central hub for this faction's adventurers, offering many services and quests, as well as [[flight path]]s. As the town is under constant siege by [[gnoll]]s and [[Blackrock Clan|Blackrock]] [[orc]]s the townsfolk are concerned and can be seen protesting at the Town Hall. Adventurers should use caution on the roads to this town, especially the ones northbound.\r\nThe enemy-held [[Stonewatch Keep]] and [[Tower of Ilgalar]] are connected with quests, but are also very dangerous and require a party to handle properly.\r\nThe crossroads known as the [[Three Corners]], located in the southwest corner of the zone, connects the town of Lakeshire with Elwynn, Duskwood and, via the Lakeridge Highway, Stonewatch Keep. The highway itself is quite a dangerous place occupied by [[gnolls]], [[murloc]]s, and wild animals. There are also a few camps located in Redridge — an orc camp in [[Render's Valley]], [[Shadowhide clan|Shadowhide]] gnoll camps near the Tower of Ilgalar, and murloc camps near the lake. While the lake's surface appears peaceful enough, murlocs reside beneath the waves, and rumors of sightings of a sea monster persist. There are also [[raptor]] nests in the Mountains.\r\n==History==\r\nGeographically, the Redridge Mountains form the spine of the continent of [[Azeroth (continent)|Azeroth]], although its many limbs and valleys have come to be known by separate, often ominous names such as '[[Deadwind Pass]]' and the '[[Burning Steppes]]'. After the [[War of the Ancients]], the dangerous and destructive [[Demon Soul|Dragon Soul]] created by [[Deathwing]] was hidden beneath the Redridge Mountains. Protected by magical wards and [[Orastrasz]], it would remain hidden for ten thousand years before Deathwing led the [[Dragonmaw clan]] there in dreams and visions.\r\nCenturies ago, throughout the [[Eastern Kingdoms]], the disparate human nations flourished, among them the smallest and most isolated of the kingdoms was [[Stormwind (kingdom)|Stormwind]]. Over the years, it found prosperity through the farmsteads that dotted the surrounding fertile region, and as its population grew, small towns sprang up in the nearby regions, notably Redridge Mountains.\r\nAlthough claimed by the [[human]]s, the [[Dark Iron dwarf|dwarven]] [[Dark Iron clan]] founded its own kingdom in the northern reaches, fleeing defeat in the [[War of the Three Hammers]]. Summoning the [[Firelord]] [[Ragnaros]] to aid them, their leader [[Sorcerer-Thane Thaurissan|Thaurissan]] inadvertently caused the eruption of a new, immense volcano; [[Blackrock Mountain]]. This not only destroyed his clan's [[Ruins of Thaurissan|new city]] but utterly devastated the ecology of northern Redridge, forever leaving it an ash-choked wasteland.\r\nThe humans of [[Stormwind (kingdom)|Stormwind]] remained dominant in the unblemished southern ranges. Now a much smaller region, the Redridge Mountains were eventually conquered by the [[Old Horde|Orcish Horde]] in the [[First War]], in which the southern kingdom was forced into exile. The humans eventually returned triumphant and began rebuilding their former holdings. Yet the orcs of the [[Blackrock clan|Blackrock]] and [[Black Tooth Grin clan]]s would also return, this new \"[[Dark Horde]]\" plaguing the town of Lakeshire from their former stronghold of Blackrock Mountain.\r\nEventually, the orcs allied with the wicked human [[warlock]] [[Morganth]] and his [[Shadowhide Gnoll Clan|Shadowhide]] [[gnoll]] lackeys, and seized the eastern half of Redridge, capturing the human castle of [[Stonewatch Keep]] before the events of ''[[World of Warcraft]]''. Weakened by political turmoil in Stormwind, Lakeshire was left with little military aid to fend off the encroaching orcs until the return of [[Marshal Reginald Windsor|Reginald Windsor]].\r\nThe region remains heavily contested. Desperate, the people of Redridge seek help from outside sources, recruiting passing adventurers to help in the defense of Lakeshire and the liberation of Stonewatch.\r\nWith the guidance of the dragon [[Darkblaze]], the [[Dark Horde]] have also begun invading Redridge sometime after the [[Cataclysm (event)|Cataclysm]]. An Alliance adventurer deputized by the [[Stormwind Army]] traveled to Redridge to aid the beleaguered Stormwind guards and reform [[Bravo Company]] to combat the threat. During their war with the [[Blackrock clan|Blackrock orcs]], [[Render's Valley]] was blown up but the Dark Horde has been driven back to the [[Burning Steppes]]. Stonewatch Keep has also been reclaimed.\r\nStormwind also increased Redridge's security by constructing [[Tower Watch]] on the [[Three Corners]] and stationing a garrison of [[Redridge Garrison Watchman|Redridge Watchmen]] there.\r\nAt some point in the past, [[Greydon Thorne]] hid three crystal shards from the [[Diamond Blade]] that held the essence of a [[naaru]] that was a key do the defense of Azeroth against the [[Darkstorm]]. [[Gazlowe]], [[Charnas]], and [[Gimble Sprysprocket]] transported [[Makasa Flintwill]] and her friends to the area on the ''[[Cloudkicker]]''. Due to the political situation, while Makasa and her group were in Lakeshire and surrounding areas looking for the crystal shards, the [[Horde]] [[zeppelin]] and the [[goblin]]s stayed hidden somewhere in the northern mountains. The first shard was in Lakeshire, in the backyard of the [[Glade]]s' house, the second one was in a cave northeast of the village that has been guarded by a [[blue drake]] named [[Telagos]] for several years, and the last one was in a mine shaft of the [[Lake Everstill|Lakeshire quarry]]. Later, [[Murky (Traveler)|Murky]] also secured the help from the [[Everstill murlocs]], taking them aboard the ''Cloudkicker'' to the [[Blasted Lands]].\r\nDuring [[Death Rising]], Redridge Mountains came under attack from the [[Scourge]]. To fight against the undead, troops of the [[Argent Crusade]] were mobilized in order to protect the region and its inhabitants.\r\n==Geography==\r\nThe Redridge Mountains contain no dungeons, raid dungeons, or battlegrounds. The micro dungeon [[Stonewatch]] can be found in this zone. The Redridge Range stretches from the zone of the Redridge Mountains to the zone of [[Deadwind Pass]].\r\n===Redridge Range===\r\nThe '''Redridge Range''' is a mountain range in the southern sub-continent of [[Azeroth (continent)|Azeroth]]. It reaches from the [[Deadwind Pass]] in the south to what's now called the [[Searing Gorge]] in the north. Two hundred years before the opening of the [[Dark Portal]], the northern reaches of the range were obliterated by the summoning of [[Ragnaros|Firelord Ragnaros]] and the creation of [[Blackrock Mountain]].\r\n===== [[Flight path]]s from [[Lakeshire]]=====\r\n* [[Stormwind]], [[Elwynn Forest]]\r\n* [[Eastvale Logging Camp]], [[Elwynn Forest]]\r\n* [[Sentinel Hill]], [[Westfall]]\r\n* [[Camp Everstill]], Redridge Mountains\r\n* [[Darkshire]], [[Duskwood]]\r\n* [[Morgan's Vigil]], [[Burning Steppes]]\r\n* [[The Harborage]], [[Swamp of Sorrows]]\r\n===== [[Flight path]]s from [[Camp Everstill]]=====\r\n* [[Lakeshire]], Redridge Mountains\r\n* [[Shalewind Canyon]], Redridge Mountains\r\n===== [[Flight path]]s from [[Shalewind Canyon]]=====\r\n* [[Camp Everstill]], Redridge Mountains\r\n* [[Bogpaddle]], [[Swamp of Sorrows]]\r\n===Quest and travel hubs===\r\n#Initially unoccupied, Keeshan's Post gets quests and NPCs after [[AHHHHHHHHHHHH! AHHHHHHHHH!!!]] has been completed.\r\n==Notable characters==\r\nThe Redridge Mountains are home to several humans of note, the great bulk of which reside in Lakeshire. At the fallen bridge [[Marshal Marris]] sends promising young humans to eradicate the clusters of Shadowhide gnolls and Blackrock orcs who have taken a chokehold on the land. He is assisted in his efforts by [[Verner Osgood]], who also seeks to rid Redridge of the vile gnolls. And at the Lakeshire Town Hall, the aging [[Magistrate Solomon]] recruits adventurers to seek help from Stormwind's other settlements like Stormwind City, Sentinel Hill, and Darkshire.\r\n==Resources==\r\n* [[Cloth]]\r\n** [[Linen Cloth]]\r\n** [[Wool Cloth]]\r\n** [[Silk Cloth]]\r\n* [[Herb]]s\r\n** [[Earthroot]]\r\n** [[Mageroyal]]\r\n** [[Swiftthistle]]\r\n** [[Briarthorn]]\r\n** [[Bruiseweed]]\r\n* [[Leather]]\r\n** [[Light Leather]]\r\n** [[Medium Leather]]\r\n** [[Black Whelp Scale]] (Skinning level 17-25 [[Black whelp|whelps]])\r\n* [[Ore]]\r\n** [[Copper Vein]]\r\n** [[Tin Vein]]\r\n** [[Silver Vein]]\r\n==Battle pets==\r\n*[[Roach]]\r\n*[[Fossilized Hatchling]] - [[Archaeology]] only\r\n*[[Rabbit]]\r\n*[[Mountain Cottontail]]\r\n*[[Pterrordax Hatchling]] - [[Archaeology]] only\r\n*[[Fledgling Buzzard]]\r\n*[[Chicken]]\r\n*[[Flipsy]] \r\n*[[Dipsy]] \r\n*[[Flufftail]] \r\n==Wild creatures==\r\n* [[Boar]]s\r\n* [[Carrion bird]]s\r\n* [[Black whelp]]s\r\n* [[Gnoll]]s\r\n* [[Murloc]]s\r\n* [[Orc]]s\r\n* [[Tarantula]]s\r\n* [[Threshadon]]s\r\n* [[Giant]]s (only one though, the rare mob [[Boulderheart]])\r\n* [[Freshwater Eel]]s\r\n*Wolves (could be seen near Lakeshire when [[Ben Howell]] perished)\r\n* [[Raptor]]s (in lore)\r\n===History===\r\nRedridge was once a larger stretch of mountains in which the [[Dark Iron dwarf|Dark Iron dwarves]] established a colony in the northern reaches called [[Ruins of Thaurissan|Thaurisan]] after their exile from [[Ironforge]]. Their mad [[thane]] [[Sorcerer-Thane Thaurissan|Thaurisan]] befouled the region when he summoned [[Ragnaros]]. Half the mountain range melted into the Burning Steppes, but the rest remained pristine.\r\nThese mountains and foothills were used as thoroughfares in the many wars in the past fifty years, but they somehow remained untouched while the surrounding regions suffered. Now it is the last true area wholly under Alliance influence in [[Azeroth (continent)|Azeroth]], and it sometimes struggles to remain so.\r\n===Geography===\r\nWhile the ravaged mountains of the [[Burning Steppes]] border it on the north and the deadly [[Swamp of Sorrows]] and [[Deadwind Pass]] border it on the south, the Redridge Mountains more reflects the beautiful [[Elwynn Forest]] to the west. Redridge matches Elwynn's climate, being warm and temperate with just the right amount of rain. The higher altitude and closer proximity to the mountains make it a bit cooler than Elwynn, but no less pleasant.\r\nSeveral elms and pines make up the forests in this region, providing a traveler much needed relief from the sun if he is coming from far away lands, but also giving monsters and orcs good places to hide. [[River]]s snake through the area, most of them emptying into the massive [[Lake Everstill]].\r\nAlthough a peaceful Alliance region, the mountains remain dangerous at times, with [[tarantula]]s in the east and [[orc]]s in the north, and the usual [[gnoll]]s or [[Wolf|wolves]] prowling the forests.\r\n==Film universe==\r\nThe Redridge Mountains are depicted close to their ''[[World of Warcraft]]'' incarnation. [[Stonewatch Keep|Stonewatch Keep]] is shown falling to the .\r\n==Notes==\r\n*Some of the trees here are oaks.\r\n*It's recommended that one wears a helmet when in the Redridge Mountains, as buzzards view humanoid hair as excellent nesting material.\r\n*Redridge had one of the game's highest level-gaps between zones at its border with the [[Burning Steppes]], which is a 30 level jump from 20 to 50. Players were instead directed to [[Duskwood]] (to the southwest) after completing all the quests here. This is now obsolete with the changes to level ranges.",},
			["Redridge Range"] = { content = "#REDIRECT [[Redridge Mountains]]", redirect = "Redridge Mountains",},
			["Redstone Basilisk"] = { content = "'''Redstone Basilisk''' can be found in [[Blasted Lands]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.05% Chance of a [[rare]] drop.\r\n0.55% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\n0.01% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Redstone Crystalhide"] = { content = "'''Redstone Crystalhide''' can be found in [[Blasted Lands]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.02% Chance of a [[rare]] drop.\r\n0.78% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\n0.02% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Reduced healing"] = { content = "'''Reduced healing''' effects are [[Debuff|debuffs]] that reduce the effectiveness of [[Healing]].\r\n==Healing received==\r\nExamples of abilities that cause a reduced healing effect to those receiving the healing:\r\nSome other sources of reduced healing effects include:\r\n* The orc racial [[Blood Fury]]\r\n* '''Curse of the Deadwood''', cast by [[Deadwood]] mobs in [[Felwood]].\r\n* [[Gluth]]'s '''Mortal Wound'''\r\n* [[Watchkeeper Gargolmar]]'s '''Mortal Wound'''\r\n==Healing dealt==\r\nThere are also debuffs that reduce the effectiveness of healers to heal others.\r\n* [[Anetheron]]'s '''Carrion Swarm'''",},
			["Red Belt of Battle"] = { content = "==Source==\r\nThis item is created by [[Blacksmithing|blacksmiths]] with a skill level of 375; taught by Plans: Red Belt of Battle.\r\n* 2x Nether Vortex\r\n* 5x Hardened Adamantite Bar\r\n* 10x Primal Fire\r\nThe recipe is a drop from random mobs inside [[Serpentshrine Cavern]] and [[Eye (Tempest Keep)|The Eye]].",},
			["Red Cloud Mesa"] = { content = "'''Red Cloud Mesa''' is the name for the rolling plains atop the high cliffs in southern [[Mulgore]]. Here, young tauren adventurers cut their teeth on the nearly harmless wildlife. While they aren't out training on the grasslands, they return to [[Camp Narache]] in the northwest portion of the Mesa. \r\nRed Cloud Mesa is known for being a place of peaceful, serene beauty without the threats found in the rest of the world. Only in the extreme northeast is any danger present. [[Brambleblade Ravine]], so named for its enormous twisting, thorned vines, is infested by the [[Bristleback]] [[quilboar]].\r\nHere, Tauren can find [[Greatmother Hawkwind]] for the quest A Humble Task.",},
			["Red Defias Mask"] = { content = "This item drops from members of the [[Defias Brotherhood]] throughout [[Westfall]]. It is also dropped by [[Grave Robbers]] patrolling the [[Raven Hill Cemetery]] in northwest [[Duskwood]].\r\n==Notes==\r\nThis item is a head item that is used by [[rogues]] that cannot find any other head armor. It is dropped by members of the [[Defias Brotherhood]] in [[Westfall]] in the [[Eastern Kingdoms]]. Because the item drops in mostly [[Alliance]] territory it is difficult, but not impossible, for [[Horde]] members to get the mask. A low level [[Horde]] member can sneak north through [[Stranglethorn Vale]] after taking a [[Zeppelin]] to [[Grom'Gol Base Camp]], and end up in [[Duskwood]], where they can kill Grave Robbers for the drop. It has a 1% - 2% chance to drop.",},
			["Red dragon"] = { content = "'''Red dragons''' are the adults of the [[red dragonflight]].\r\n==Notable==\r\n==Types==\r\n*[[Red Dragon Soldier]]\r\n*[[Ruby Consort]]\r\n*[[Ruby Keeper]]\r\n*[[Wyrmrest Guardian]]\r\n*[[Wyrmrest Vanquisher]]\r\n===Description===\r\nRed dragons once ruled as lords over all dragonkind. This nobility is reflected in every aspect of a red dragon, from its proud demeanor to its aura — one that inspires awe. It is as debilitating as the terrifying presence that other dragons possess, except that it overwhelms with a beatific aura.\r\nRed dragons exemplify the serenity of life and nature. Legends hold that the earth is renewed wherever a red dragon walks upon the earth or burns the soil with its flaming breath. Although they use fire to protect and punish, the flames always give way to new life.\r\n===Red Dragon Society===\r\nThe red flight was once charged with the protection of all living things on [[Azeroth]]. In time, their vision became clouded. Humanoid races were in an uprising, and some red dragons insisted that they must make war upon them to protect the wilderness. Others believed that the mortal races could be allies to help in bettering the world. This led to a great schism within the red flight that has never been repaired. When their Aspect, [[Alexstrasza]], went missing, the red dragons scattered in order to find her. [[Deathwing]] and his black flight took this opportunity to attack the leaderless, scattered red flight. They fought back against the black flight and forced a detente, but doing so caused delays in looking for Alexstrasza. They soon found out that [[orc]]s held the Dragonqueen, and even were using the new generations of red dragons in the [[Second War]]. Soon, mortals helped free Alexstrasza, and the red flight resumed its ancient charge of defending Azerorth.\r\n===Combat===\r\nRed dragons are honorable and fight on even terms if battling honorable or worthy opponents. They will sacrifice their aerial advantage if they are met fairly on the ground. The red dragon's wrath, however, dispenses with honor when facing those they consider dishonorable — any evil creatures, as well as orcs. Such beings are to be expunged with every instinct and ability that red dragons possess. Red dragons prefer to use flame to entrap enemies and force them to difficult terrain, using their aeial advantage for greater mobility. They prefer to destroy an opposing force's leadership first, ruining its power structure and hopefully setting the younger or less experienced combatants to flight.\r\n==Notes==\r\n\"Ruby\" and \"crimson\" is usually associated with the red dragons.",},
			["Red Dragonflight"] = { content = "#REDIRECT [[Red dragonflight]]", redirect = "Red dragonflight",},
			["Red Dragonhawk Hatchling"] = { content = "==Source==\r\nThis item can be purchased for s=50 gold from Jilanne in [[Eversong Woods]].",},
			["Red dragons"] = { content = "#REDIRECT [[Red dragonflight]]", redirect = "Red dragonflight",},
			["Red Dragonscale"] = { content = "'''Red Dragonscale''' is the scale of red and chromatic [[dragonkin]].\r\n==Source==\r\nRed Dragonscale can be found by [[skinning]] red dragonkin throughout the lands and the chromatic dragonkin in [[Upper Blackrock Spire]]. You can also occasionally find a stash of dragonscales in [[Knot Thimblejack's Cache]] in [[Dire Maul]].\r\n===[[Leatherworking]]===\r\n*[[Chromatic Cloak]]\r\n*[[Red Dragonscale Breastplate]]",},
			["Red Dragonscale Breastplate"] = { content = "==Source==\r\nThis item can be crafted using [[Leatherworking]] (300); taught by Pattern: Red Dragonscale Breastplate.",},
			["Red dragonspawn"] = { content = "A red [[dragonspawn]] is a creature that has the lower body of a reptile, with four legs and a tail. Its torso and arms are humanoid, while its head is that of a dragon. A red [[wyrmkin]] has a scaled hide of deep red and bright crimson. He wears scale mail that is of superior quality, a dark copper in tone and etched with draconic sigils. His golden eyes gleam with zealous fervor as he hefts an exotic longsword in one hand and a broad shield in the other.",},
			["Red drake"] = { content = "Red [[drake]]s are the adults of the [[red dragonflight]], and most are fully grown at this stage. Once friends to nearly every living creature, [[red dragon]]s are now much more suspicious, tending to seek only the company of their own kind. The capture of the Dragonqueen and the accompanying loss of a great number of their flight has left reds crippled, but not defeated. Although many reds feel they owe a debt of gratitude to the Alliance for its assistance in [[Alexstrasza]]’s rescue, others distrust all mortals, noting that even the [[night elves]] once brought danger and death to the world. Generally, though, red dragons are friendly to [[humans]], [[elves]], and their other traditional friends and allies; for the most part, it is the representatives of the flight near [[Grim Batol]] who are strangely hostile to any outsiders. Red drakes typically consider the various [[Horde]] races to be enemies, with the possible exception of [[tauren]], whom they respect for their druidic abilities.\r\nThis dragon has a lithe frame; though large, the crimson drake is graceful and noble in form. The fiery horns atop the dragon’s skull resemble a crown upon the head of a worthy king. Golden orbs scrutinize every motion, obviously judging whether one might be friend or foe.\r\nRed drakes are honorable and always fight on equitable terms if battling honorable or worthy opponents. For instance, they sacrifice their aerial advantage if their enemies meet them fairly on the ground. They quickly dispense with honor when facing those they consider dishonorable, however; such beings are to be expunged with every instinct and ability that red dragons possess. Red drakes use flame to entrap enemies and force them into difficult terrain, using their aerial advantage for greater mobility. They seek to destroy an opposing force’s leadership first, ruining its command structure\r\nand hopefully setting the younger or less experienced combatants to flight. Like younger reds, drakes willingly put themselves at risk to protect a companion (or even more so, their eggs).\r\nRed drakes speak [[Common]] and [[Draconic]], and some speak other languages.",},
			["Red Hakkari Bijou"] = { content = "==Source==\r\n'''Red Hakkari Bijou''' is a small [[Hakkari Bijou|token of power]] from the mobs in [[Zul'Gurub|Zul'Gurub]].",},
			["Red Moth"] = { content = "#REDIRECT [[Red Moth Egg]]", redirect = "Red Moth Egg",},
			["Red Moth Egg"] = { content = "The '''Red Moth Egg''' item summons and dismisses a Red Moth, a [[moth]] [[small pet]] that follows you around, meaning it is a non-combat pet and will not aid you in battle.\r\n \r\n==Source==\r\nRed Moth Eggs are sold by [[Dealer Rashaad]] in [[Stormspire]] for 10 gold .",},
			["Red pox"] = { content = "The '''red pox''' is a disease that ravaged many [[mag'har]] [[orcs]] in the years following the [[rise of the Horde]]. The pox's main symptoms were red pustules welling up on the skin, seeping a watery red fluid, and also the vomiting of blood. The disease was debilitating and affected many remaining \"brown orcs\". Its origin is unknown.\r\nWhen [[Kargath Bladefist]] arrived at a Mag'har village in [[Nagrand]] — likely the modern town of [[Garadar]] — he found many, including [[Garrosh Hellscream]], son of [[Grom Hellscream|Grom]], affected by this disease. [[Nagrand]] had by that time become the home of the sick and weakened, but remained the most vibrant place on the otherwise dying world of [[Draenor]] (although it was not completely free of the corruption having suffered from long droughts). The [[Shattered Hand]] chieftain sneered at them for their \"weakness\" and made his way back to the battle.\r\n''It would appear that the red pox is part of the reason for the mag'har and Nagrand escaping corruption; the other clans were likely to have given the afflicted a wide berth, thus they were never exposed to warlock magic. It should be noted that according to Rise of the Horde tribes living in Nagrand had not completely escaped corruption and that Nagrand itself suffered affects of the corruption but not nearly to the extent seen everywhere else on the planet.\r\n \r\nIt might be possible that the red pox might have innoculated the orcs who caught it from the effects of fel magic, as well as the land. Though not clearly stated, [[Jorin Deadeye]], [[Saurfang the Younger]] and most mag'har appearing in-game were probably also afflicted by the disease. The red pox has apparently been cured by the time of ''[[World of Warcraft: The Burning Crusade]].",},
			["Red Qiraji Resonating Crystal"] = { content = "'''Red Qiraji Resonating Crystal''' is a [[mount]] summoning device.\r\n==Source==\r\nThis item drops in the [[Temple of Ahn'Qiraj]] from random [[mob]]s.\r\n==Notes==\r\nThis mount, the Red Qiraji Battle Tank, grants 100% increased speed within the confines of the Temple of Ahn'Qiraj. It is a necessity for movement as a raid through the instance, as normal mounts can not be used after defeating [[Prophet Skeram]]. Thankfully, they are fairly common, also coming in the [[Blue Qiraji Resonating Crystal|blue]], [[Green Qiraji Resonating Crystal|green]], and [[Yellow Qiraji Resonating Crystal|yellow]] varieties. There is another, more special mount that is accessed by completing the quest-chain to open the [[Gates of Ahn'Qiraj]], and that is the [[Black Qiraji Resonating Crystal|Black Qiraji Battle Tank]].",},
			["Red Ring of Destruction"] = { content = "'''Red Ring of Destruction''' is an [[uncommon]] ring that will likely be desired by Spellcasters that desire great spell criticals. This includes Fire [[Mages]] and Elemental [[Shamans]]. It can be crafted by [[Jewelcrafter]]s with a skill level of 230.",},
			["Red Rocket Cluster"] = { content = "'''Red Rocket Cluster''' a type of large firework that [[Engineering|engineers]] can make.\r\n===Engineering===\r\nRed Rocket Cluster is crafted by [[Engineering|engineers]] with a skill of 225. \r\nThe components are:\r\n*1 [[Solid Blasting Powder]]\r\n*1 [[Thick Leather]]\r\nSchematics can be obtained by turning in Coins of Ancestry at the [[Lunar Festival]].\r\n===Vendors===\r\nThis item can be purchased for 1 silver copper from Lunar Festival Vendor in [[Thunder Bluff]].\r\n==See also==\r\n*Cluster Rockets",},
			["Red Rocks"] = { content = "The Red Rocks are located in north-eastern [[Mulgore]]. They are ancient ancestral holy grounds for the [[Tauren]] tribes because it holds a great spiritual energy potential. Recently, a group of [[Quilboar]]s had invaded the Red Rocks and defiled the holy place with their filth, which has greatly enraged the tauren of [[Thunder Bluff]].",},
			["Red Scepter Shard"] = { content = "The '''Red Scepter Shard''' must be recovered from Nefarian (tactics) ([[Blackwing Lair]]) to form icon=.\r\n==As a quest objective==\r\nNefarius's Corruption begins with Vaelastrasz. Kill Nefarian in 5 hours and retrieve the shard for Anachronos.\r\n==Notes==\r\nOnly one person will be able to loot the shard, even if multiple people have the quest. To clear things up, you have 5 hours to kill Nefarian and loot the shard, afterwards you can keep the shard in your bags/bank for as long as you like, as long as you got the shard, you can keep it for as long as you like and still hand it in successfully.",},
			["Red Snapper"] = { content = "==Source==\r\nThis item can be fished from a [[School of Red Snapper]], and drops from [[Angry Murloc]]s.\r\n==As a quest objective==\r\nThis item is an objective of Red Snapper - Very Tasty!.",},
			["Red Snapper - Very Tasty!"] = { content = "'''Red Snapper - Very Tasty!''' is an [[Alliance]]-only quest in the [[draenei]] starting zone [[Azuremyst Isle]]. Players must collect Red Snapper using a net in order to help feed the [[draenei]] refugees in nearby [[Azure Watch]].\r\n====How to Get This Quest====\r\n[[Diktynna]] is on the beach of [[Ammen Ford]] - if you are taking the road from [[Ammen Vale]] to [[Azure Watch]], you can't miss her.\r\n==Objectives==\r\nUse the Draenei Fishing Net to catch 10 Red Snapper. Return both the fish and the net to [[Diktynna]] on [[Azuremyst Isle]] when the task is complete.\r\nRequires:\r\n* Red Snapper x10\r\n* Draenei Fishing Net (Provided)\r\n==Details==\r\nOnce you start the quest, take your Draenei Fishing Net to the river. Look for [[School of Red Snapper|Schools of Red Snapper]]. Walk/swim up to the school and right click the net to collect Red Snapper. Occasionally a [[Murloc]] will spawn where you use the net - if you kill it, it will drop a snapper.\r\n==Description==\r\n''I've found that these waters are bustling with red snapper, a very tasty fish. With a fishing net, I can catch enough to feed dozens of [[draenei]]! Unfortunately, I was recently attacked by a creature known as a [[murloc]] while netting in the river and have suffered some injuries that prevent me from doing my job. I need help!\r\n''Use this fishing net near schools of red snapper, found in the Crystalbrook river to the east to catch the fish.\r\n''What do you say? Remember to return the net when you are finished. \r\n==Progress==\r\n''Watch out for [[murlocs]]: Strange and extremely annoying little creatures.\r\n==Completion==\r\n''I hope the [[murlocs]] didn't cause too much trouble, <name>. I owe you a great debt of gratitude for all that you've done.\r\n''Perhaps I could teach you how to fish? I'll even supply the fishing pole and a bauble.\r\n==Quest Progression==\r\n*Red Snapper - Very Tasty!\r\n**Find Acteon!\r\n==Notes==\r\n*The title of the quest is a reference to the 1980's movie \"\". In this movie, a peculiar game show named ''Wheel of Fish'' (which is a spoof of Bob Barker's ''Wheel of Fortune'') is hosted by a former karate master. As a contestant wins a red snapper from a spin of the Wheel, the host expresses his enthusiasm. The snapper is subsequently wagered on a mystery box, which is empty.\r\n*It is also a tribute to Oxhorns movie \"Red Snappah\" (",},
			["Red Socket"] = { content = "#REDIRECT [[Socket]]", redirect = "Socket",},
			["Red whelp"] = { content = "Red [[whelp]]s are the youngest of red dragonkind. Scales resembling solid flame glisten on the small dragon’s form. Although not great in size, she nevertheless has wicked claws, and her fangs are visible as she turns her head. Though clearly a predatory creature, the glint of wisdom and kindness shines in her eyes. These hatchlings are highly intelligent; unless newborn, they know enough about humanoid creatures to be friendly even when first encountered. They are suspicious of orcs, and avoid them if possible, due to the Horde’s previous enslavement of the red flight. Those red whelps raised near Grim Batol are more aggressive due to the events that occurred there (and possibly for other reasons connected to the contents of the fortress).\r\nRed whelps flee combat if alone or clearly overwhelmed. If they are with a group, older whelps attack in order to give the younger children a chance to retreat; red dragons invariably put their own health and wellbeing second to that of a friend or loved one, even at this young age.\r\nRed whelps speak Common and Draconic.\r\nYou can have your own young newly hatched red whelp that is less likely to burn your hair off!\r\nsee [[Tiny Crimson Whelpling]]",},
			["Red Wolf Meat"] = { content = "==Source==\r\nThis item can be looted from most level 30-67 [[Beast]] monsters.\r\n==Red Wolf Meat as an ingredient==\r\nThis item is used to make: \r\n* Hot Wolf Ribs\r\nThe recipe can be purchased from:\r\n* Sheendra Tallgrass in [[Camp Mojache]]\r\n* Vivianna in [[Feathermoon Stronghold]] \r\n* Super-Seller 680 in [[Desolace]].",},
			["Red Wyrmkin"] = { content = "'''Red Wyrmkin''' can be found in [[Wetlands]].\r\n==Drops == \r\nAlso 12 random [[Uncommon]] and 3 random [[Common]] item drops.",},
			["Reef Crawler"] = { content = "'''Reef Crawler'''s are level 15-17 [[crab]]s native to [[Darkshore]]. They are often hunted for their fine crab meat along with [[Encrusted Tide Crawler]]s.\r\n==Drops==",},
			["Reef Shark"] = { content = "'''Reef Shark''' can be found off the coasts of [[Westfall]], [[Darkshore]], [[Silverpine Forest]], and [[Ashenvale]].\r\n==Drops == \r\n \r\n6.67% Chance of a [[common]] drop.\r\n13.33% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Reflect"] = { content = "'''Reflection''', more commonly called '''Spell Reflection''', is a defensive mechanic that allows mobs and players to avoid a spell, as well as reflecting it back to the caster. It is the most flexible avoidance mechanic, but also the rarest one.\r\nOnly targeted spells can be reflected; [[Area of Effect]] spells cannot. Spells which hit multiple targets but are targeted (such as [[Chain Lightning]]) can be reflected individually for each hit. Rogue [[poison]]s use the [[spell]] mechanic and as such can be reflected, too.\r\n==Reflect Effects==\r\n* Some mobs have a native chance to reflect spells, or abilities to do so.\r\n* The mage talents [[Molten Shields]] and [[Frost Warding]] give a chance to reflect fire and frost spells, respectively.\r\n* Warriors can use [[Spell Reflection]] in Battle and Defensive Stances.\r\n* Some items and consumables grant spell reflection chance, most notably [[Destructive Skyfire Diamond]].\r\n==Mechanic==\r\nReflected spells behave as if the caster directly targeted themself. Apart from the reflect itself, there is no further connection between the spell and the reflector. This means:\r\n*The spell uses the caster both as the source and the target for calculations. As a result, it is not possible for spells to be reflected more than once, as any further reflect would not change the target.\r\n*The damage done is still considered to be caused by the caster. \r\n*All spell enhancing effects (such as [[talent]]s and [[proc]]s) are solely taken from the caster. Talents and effects from the reflector do not have any impact on the spell. For example, [[Dampen Magic]] on the original target of the spell does not reduce a reflected spell's damage.\r\n*Any secondary effects caused by the spell will be incurred by the caster. However, not all additional effects can affect them. For example, [[Ignite]] and [[Impact]] can hit the caster, whereas [[Improved Scorch]]'s Fire Vulnerability fails, stating that it cannot affect friendly targets.\r\n==Spells with unusual behavior==\r\n*Spells which cannot affect the caster (e.g. [[Banish]] vs. [[humanoid]]s) can be reflected but have no effect.\r\n*[[Seed of Corruption]] does not deal damage to the caster's enemies but to the target's allies. This means that a reflected SoC will deal damage to its caster's pet and allies.\r\n*Neither [[Shadowburn]]'s debuff nor [[Drain Soul]] will take effect when reflected.\r\n*[[Holy Shock]], when used offensively and reflected, will damage the paladin that casted it, despite the fact that it is normally a healing spell if casted directly on oneself.\r\n==See also==\r\n*[[Combat]]\r\n*[[Combat rating system]]",},
			["Reflective Shield"] = { content = "''Stop hitting yourself. Stop hitting yourself...''\r\n'''Reflective Shield''' is a seventh tier priest discipline talent. It allows a percentage of the damage absorbed by [[Power Word: Shield]] to be reflected back at the attacker.\r\n==Notes==\r\n*Damage reflected is in the form of Holy Damage, and can crit.\r\n*Damage caused by this talent will not break crowd control effects such as Polymorph.\r\n*This talent is very useful in a PvP discipline build in conjunction with [[Improved Power Word: Shield]], as it will reflect a good amount of damage back at your attackers.\r\n*This talent is not as useful in PvE since normal mobs have a relatively low damage output and warriors and druids cannot generate rage from the damage absorbed by [[Power Word: Shield|PW:S]].\r\n==Past Changes==\r\n*As of [[Patch 2.4]], Reflective Shield will no longer break crowd control effects.\r\n",},
			["Reflex Blades"] = { content = "==Source==\r\nThis item drops from [[Dalliah the Doomsayer]] in the [[Arcatraz]].",},
			["Reforged Saronite"] = { content = "'''Hardened Saronite Bar''' is a new alloyed metal bar made in [[Northrend]] from 10 Saronite Bar.\r\n==Source==\r\nThis item can be crafted using [[Mining]] (425); taught by Grand Master Mining trainers for 9 gold .\r\n==As an ingredient==\r\n...",},
			["Refreshing Spring Water"] = { content = "'''Refreshing Spring Water''' is clean, clear, and pure.\r\n==Source==\r\n'''Refreshing Spring Water''' is sold by merchants worldwide.\r\nIt is also a quest reward for the following quests:\r\n*A Peon's Burden\r\n*A Rogue's Deal\r\n*A Task Unfinished\r\n*Completing the Delivery\r\n*The Scarlet Crusade\r\n*Dolanaar Delivery\r\n*Rest and Relaxation\r\n*Supplies to Tannok\r\n*Word from Azure Watch\r\nSome low-level [[mob]]s can also drop Refreshing Spring Water.\r\nCan also be found in [[Water Barrel]]s in low level zones.\r\nMost races start with 2 Refreshing Spring Water in their inventory as well.\r\n===[[Cooking]]===\r\n*[[Boiled Clams]] (level 50)\r\n*[[Thistle Tea]] (level 60)\r\n*[[Jungle Stew]] (level 175)\r\n*[[Heavy Kodo Stew]] (level 200)\r\n*[[Nightfin Soup]] (level 250)\r\n*[[Lobster Stew]] (level 275)\r\n*[[Goldthorn Tea]]\r\n===[[Engineering]]===\r\n*[[Small Seaforium Charge]] (level 100)\r\n*[[Snowball]] (level 190 using [[SnowMaster 9000]])\r\n*[[Large Seaforium Charge]] (level 200)\r\n*[[Powerful Seaforium Charge]] (level 275)",},
			["Refreshment Table"] = { content = "A '''Refreshment Table''' is an object conjured by the [[Mage]] spell [[Conjure Refreshment]], if in a [[group]]. The table can be right-clicked by group members to obtain a stack of refreshments, and has a duration of 3 minutes, or 50 charges.\r\n==Notes==\r\n*It was originally summoned by [[Conjure Refreshment Table]] prior to [[patch 7.0.3]].",},
			["Refugee"] = { content = "A '''refugee''' is a person who \"owing to a well-founded fear of being persecuted for reasons of race, religion, nationality, membership of a particular social group, or political opinion, is outside the country of their nationality, and is unable to or, owing to such fear, is unwilling to avail him/herself of the protection of that country\".\r\n==In World of Warcraft==\r\nIn [[World of Warcraft]], many of various races can be found. This is a testament to the hardships of war.\r\n*Bleeding Hollow Refugee\r\n*Broken Refugee\r\n*Draenei Refugee\r\n*Dwarf Refugee\r\n*Haggard Refugee\r\n*High Elf Refugee\r\n*Human Refugee\r\n*Injured Refugee\r\n*Lost One Refugee\r\n*Mag'har Refugee\r\n*Orc Refugee\r\n*Peasant Refugee\r\n*Refugee Child\r\n*Refugee Kid\r\n*Shattrath Refugee\r\n*Sickly Refugee\r\n*Skettis Refugee\r\n*Sporeling Refugee\r\n*Sunspring Post Refugee",},
			["Refugee Caravan"] = { content = "'''Refugee Caravan''' is a small [[neutral]] makeshift camp in the northern part of [[the Bone Wastes]] in [[Terokkar Forest]]. It is populated by several refugees of numerous races who are living in Shattrath City. They were going to assault [[Auchindoun]] but were attacked by [[Shadow Council]] raiders before they arrived. [[Caravan Defender]]s and [[Sha'tar Vindicator]]s protect the refugees and people who are diligently working to repair wagons to get the caravan back to the city. There were a number of children who have been kidnapped and brought to [[Veil Skith]], a Skettis village. [[Ethan]], a small boy, asks passersbyers to rescue his friends. There are also other people with various quests to offer. The vindicators and defenders will also attack anyone who disturbs the peace, Horde or Alliance, as well eliminate any threats from creatures that lurk around.\r\n==Facilities==\r\n*Equipment Repair\r\n*Food & Drink\r\n*Engineering/Mining/Blacksmithing Goods\r\n*Trade Goods\r\n*General Goods\r\n*Cooking Fire\r\n==Merchants==\r\n*[[Skraa]] <Trade Goods>\r\n*[[Ruogo]] <General Goods>\r\n*[[Morula]] <Food & Drink>\r\n*[[Siflaed Coldhammer]] <Tinker> (Engineering & Mining Supplies)\r\n==Other Characters==\r\n*[[Kirrik the Awakened]]\r\n**[[Redeemed Avian]]\r\n*[[Mekeda]]\r\n*[[High Priest Orglum]]\r\n*[[Soolaveen]]\r\n*[[Ethan]]\r\n*[[Lakotae]]\r\n*[[Miihi]]\r\n*[[Miiji]]\r\n*[[Aimi]]\r\n*[[Skettis Refugee]]\r\n*[[Orc Refugee]]\r\n*[[Shattrath Refugee]]\r\n*[[Human Refugee]]\r\n*'''Guards''': [[Sha'tar Vindicator]], [[Caravan Defender]]",},
			["Refuge Point"] = { content = "#redirect [[Refuge Pointe]]", redirect = "Refuge Pointe",},
			["Refuge Pointe"] = { content = "'''Refuge Pointe''' is a base of the [[Stromgarde (kingdom)|kingdom of Stromgarde]]. When the [[Stromgarde Keep|Stromgarde capital]] was in ruins following the [[Third War]], most of the populace fled south, while the proud remnants of Stromgarde's elite army stayed behind, determined to fight on to reclaim their land. It is from Refuge Pointe that the [[Alliance]]'s military operations in the area are conducted, most of which is concerned with aiding the Stromgarde army retake their former capital and securing resources for the Alliance in the [[Arathi Highlands]]. There is also an Alliance entrance to the [[Arathi Basin]].\r\nIt is more of an outpost than a full [[town]] since it has only tents and no [[mailbox]]. The [[inn]] is the southernmost tent.\r\n===Flight===\r\n [[Ironforge]]\r\n [[Thelsamar]]\r\n [[Menethil Harbor]]\r\n [[Southshore]]\r\n [[Aerie Peak]]",},
			["Regeneration"] = { content = "In [[World of Warcraft]], '''regeneration''' can mean a few things:\r\n* A passive ability that provides 10% health regen bonus and allows a 10% health regeneration during combat. This is a racial trait of [[Troll|Trolls]].\r\n* A [[buff]] that grants a [[Heal over Time]] or [[mana]] gain over time from a [[spell]] (like [[Blessing of Wisdom]], [[Healing Stream Totem]], [[Rejuvenation]], or [[Renew]]) or [[potion]] (like any potion with \"Troll's Blood\" in the name or [[Mageblood Potion]]).\r\n* A property of an [[item]] that grants a [[Heal over Time]] or [[mana]] gain over time when [[equip]]ped. \r\n* An [[enchant]] ([[Enchant Bracer - Mana Regeneration]]) for [[bracers]] that grants mana gain over time property.",},
			["Reginald Windsor"] = { content = "'''Reginald Windsor''' is a level 63 [[elite]] [[quest giver]], who plays a major role in the [[Alliance]] [[Onyxia]] Quest Chain, resulting in obtaining the [[Drakefire Amulet]].\r\n, for his appearance in [[Blackrock Depths]]\r\n==History==\r\nMarshal Reginald Windsor was a legendary knight and commander in his best days. With nerves of thorium, wielding the epic hammer [[Ironfoe]], he has become a living legend in [[Stormwind]]. Later he was assigned a post of commanding officer of Alliance forces in [[Burning Steppes]].\r\nAs threats of Blackrock Orcs grew, he sent agents to [[Blackrock Mountain]] to investigate. While traveling with the information they gathered, he was ambushed by a [[Dark Iron]] raiding party. Only one of his men, [[Ragged John]], escaped to tell the tale. Marshal Windsor was captured and imprisoned, his hammer taken by the Emperor, [[Dagran Thaurissan]], and the precious information seemed lost.\r\nIn [[World of Warcraft]], an [[Alliance]] [[player character]] can discover his notes, scattered among major individuals of [[Shadowforge]] City. Returning his notes restores Windsor's hopes, and the player escorts him to freedom. Returning to Stormwind, Windsor is greeted as a hero, despite orders from [[Lady Katrana Prestor]] for his arrest. Windsor proceeds to [[Stormwind Keep]] to reveal Katrana's true identity as Lady [[Onyxia]] before being slain by her.\r\n==Quests==\r\nHe ends the quest Stormwind Rendezvous.\r\nHe gives the quest The Great Masquerade.",},
			["Region"] = { content = "Region has a few definitions in warcraft terminology.\r\n1. In the MMO, regions are a subcategory within the lands (lands being continents of Kalimdor and the Eastern Kingdoms). Regions are major continents, which are comprised of a varying amount of [[zone]]s (zones are like countries or states).\r\nWoW MMO Regions;\r\nThese are the regions as published in the World of Warcraft Official strategy guide, and World of Warcraft manual;\r\n*[[Northern Kalimdor]]\r\n*[[Southern Kalimdor]]\r\n*[[Lordaeron]]\r\n*[[Khaz Modan]]\r\n*[[Azeroth]]\r\nRegions added in the expansions;\r\n*[[Outland]]\r\n*[[Quel'Thalas]]\r\n*[[Azuremyst Isles]]\r\n*[[Northrend]]\r\nor\r\n2. Region is an alternate term used for the individual zones within a continent as in the published lore, novels, rpg, etc.",},
			["Regions"] = { content = "#redirect [[region]]", redirect = "region",},
			["Regions by Continent"] = { content = "#REDIRECT [[Zone]]", redirect = "Zone",},
			["Regnus Thundergranite"] = { content = "'''Regnus Thundergranite''' is a level 40 [[hunter trainer]] located at the [[Hall of Arms]] in [[the Military Ward]] within the [[dwarf]] city of [[Ironforge]]. He may be related to [[Belia Thundergranite]].\r\nSee [[List of Ironforge NPCs]].",},
			["Regrowth"] = { content = "''\"When life ceases new life always begins to grow... The eternal cycle always remains!\"''\r\nA combination [[healing]] and [[HoT]] spell.\r\n==Notes==\r\n*Doesn't heal as much as [[Healing Touch]], but takes less time to cast.\r\n*Until you get Lifebloom at level 64, Regrowth will be your most mana-efficient healing spell. See [[Comparison of Druid Healing]] for details.\r\n*This is a hybrid direct-heal and [[HoT|Heal-over-time]] spell. The direct-heal portion of the spell can crit for 1.5x normal effect, but the heal-over-time portion will not be affected by the crit.\r\n*The direct-heal portion of regrowth gains ~30% of your + healing while the [[HoT|Heal-over-time]] receives an additional 70% of + healing for a total benefit of approximately 100% of your + healing.\r\n*The total net [[Threat]] is not reduced by using a heal-over-time versus an immediate-heal spell, but it can avoid generating a dramatic spike of mob hate.\r\n==Tips and tactics==\r\n*Use it when you know you don't have enough time to cast [[Healing Touch]].\r\n*This is pretty handy if multiple group members are taking aggro as you can pop one of these on the MT along with a rejuvenation which will keep his health topped up long enough to heal everyone else (Rank 9 regrowth coupled with Rank 10 rejuvenation will tick at +227). However depending on your talents and gear this may turn mana inefficient (certainly at low levels it is).\r\n*On the [[Tree of Life form]], it becomes more mana efficient. However, it is still recommended to go with a [[Rejuvenation]]/[[Swiftmend]] and (when available) [[Lifebloom]] combo to keep healing.\r\n'''See also''': [[Druid Tactics]], [[Comparison of Druid Healing]]",},
			["Regthar Deathgate"] = { content = "'''Regthar Deathgate''' is a level 15 [[quest giver]] located in a small fortified camp by the road west of [[the Crossroads]], in the [[Horde]]-aligned territory of [[the Barrens]].\r\nHe starts the following quests:\r\n* Centaur Bracers\r\n* Kolkar Leaders\r\n* Verog the Dervish\r\n* Hezrul Bloodmark (2)\r\n* Counterattack!\r\n* The Kolkar of Desolace\r\nSee [[List of the Barrens NPCs]].",},
			["Rehgar"] = { content = "#redirect [[Rehgar Earthfury]]", redirect = "Rehgar Earthfury",},
			["Rehgar Earthfury"] = { content = "==Backstory==\r\n'''Rehgar Earthfury''' was born on [[Draenor]] into a clan warring with a band of [[ogre]]s. He made his first kill long before the normal age of an orc's rite of passage, and was captured by the ogres to be used as a training tool for their youths. However, Reghar grew into a strong warrior, and after slaying many of their young fighters, was sold to the orc arenas in an attempt to recoup their loses.\r\nDespite his young age, he was a superb warrior, and was chosen to participate in the orcs' invasion of Azeroth, leading to his eventual capture and internment. However, unable to subjugate him, the guards sold him as a gladiator to fight for the human, Lord Agrovane. He escaped and became a fighter in underground arenas, gaining riches and fame.\r\nUsing his savings, he purchased the [[Blackrock]] orc, [[Bloodeye Redfist]], from authorities in [[Booty Bay]], and followed [[Thrall|Thrall's]] teachings, becoming a [[shaman]]. After arriving in [[Durotar]], they traveled the fighting circuit, Rehgar teaching Bloodeye the ways of the gladiator. Bloodeye became the Orc's favored champion, dominating in single combat, earning both himself and Rehgar riches. Bloodeye bought his freedom, and the two pooled their money to purchase and train [[Valeera Sanguinar]] and [[Broll Bearmantle]] to join Bloodeye in team combat.\r\nShortly after, Bloodeye was killed, poisoned by the mate of a fighter he slew in the arena. Following Bloodeye's funeral pyre, Rehgar set out to find a replacement for his team.\r\n==World of Wacraft: The Comic==\r\nRehgar discovers an amnesiac human on the coast of Durotar, and enslaves(using the excuse he was a theramore deserter) him as a gladiator. After the human helps Rehgar's team to victory in a competition at [[Dire Maul]], Rehgar takes his team to [[Thunder Bluff]] in order to find a [[tauren]] gladiator to take the place of [[Valeera Sanguinar]]. On the way there, the human (dubbed \"[[Lo'Gosh]]\" by the spectators at Dire Maul, a name which stuck) and his teammate [[Broll Bearmantle]] request to visit the [[Pools of Vision]]. The two of them hope to discover answers by taking part in a ritual there--Lo'Gosh hopes to fill in the missing pieces of his memory, and Broll hopes to discover the fate of his daughter. Rehgar grants their request and visits with his friend, Arch Druid [[Hamuul Runetotem]]. After Lo'Gosh and Broll defeat a mysterious elemental monster that has taken up residence in the Pools of Vision, the gladiators are taken to see Hamuul and Rehgar. After conversing for a time, Hamuul gives Lo'Gosh the feather of a [[hippogryph]] as a gesture of thanks for destroying the monster. Rehgar knows that Hamuul's purpose in the gift is that it can be used by his gladiators, through Broll's druidic powers, to summon a hippogryph that will carry them to freedom, but says nothing at the time.\r\nAt the end of the third issue of the comic, Lo'Gosh and Broll took flight on the back of the hippogryph [[Sharptalon]] and Rehgar sent his guards to recapture them. However, it appeared as though Rehgar privately hoped his fighters would successfully escape. After Hamuul observes that Rehgar does not appear concerned by the loss of his slaves, Rehgar replies as follows:\r\n'''''\"At Dire Maul, I recouped my investment in those two a thousand times over. I knew this day was coming. A man is truly a prisoner only as long as he agrees to remain one. After that, in his heart, at least, he is free. And where his heart is, his body may follow if his will is strong enough.\"'''''\r\n==Action Figure==\r\nRehgar Earthfury was first featured in DC Unlimited's ''World of Warcraft: Series 1'' action figure set, which was the basis for the comic book character.\r\nRehgar appears to be wearing either the [[Epaulets of Ten Storms]] or the [[Pauldrons of Wild Magic]], with wolfs head. He wields a [[fist weapon]] in his off-hand.\r\n==See also==\r\n* [[World of Warcraft: The Comic]]\r\n* [[Warcraft Action Figures]]",},
			["Reign of Chaos"] = { content = "Were you looking for:\r\n* The game [[Warcraft III: Reign of Chaos]]?\r\n&ndash; OR &ndash;\r\n* Information on the time period in [[Warcraft]] history known also as the [[Third War]]?",},
			["Reincarnate"] = { content = "With this spell, a caster brings back a dead creature in another body, provided that its death occurred no more than one week before the casting of the spell and the subject’s soul is free and willing to return. If the subject’s soul is not willing to return, the spell does not work; therefore, a subject that wants to return has no problems. Since the dead creature is returning in a new body, all physical ills and afflictions are repaired. The condition of the remains is not a factor. So long as some small portion of the creature’s body still exists, it can be reincarnated, but the portion receiving the spell must have been part of the creature’s body at the time of death. The magic of the spell creates an entirely new young adult body for the soul to inhabit from the natural elements at hand. This process takes an hour to complete. When the body is ready, the subject is reincarnated (the body may no longer be of his previous race). The reincarnated creature gains all abilities associated with its new form, including forms of movement and speeds, natural armor, natural attacks, extraordinary abilities and the like, but it doesn’t automatically speak the language of the new form. Common incarnations include, ironforge dwarves, high elves, night elves, gnolls, gnomes, goblins, humans, kobolds, murlocs, orcs, pandaren, tauren, troggs, and jungle trolls. A reincarnated creature recalls the majority of its former life and form. It retains any skills it formerly possessed. A wish or a miracle spell can restore a reincarnated character to his or her original form.\r\nA creature that has been turned into an undead creature or killed by a death effect can’t be returned to life by this spell. Constructs, elementals, outsiders and undead creatures can’t be reincarnated. The spell cannot bring back a creature that has died of old age.",},
			["Reincarnation"] = { content = "''Ha! And you thought you were done with me.'' \r\n'''Reincarnation''' allows the shaman to resurrect themselves upon death with 20-40% health and mana.\r\n==Tips and tactics==\r\n* When you are in a battle and you know you are not going to win, you can find a safe place to die, wait for mobs to reset, reincarnate, and then resurrect the other players. This avoids everyone having to run back (and possibly refight trash), but the ability will not be available to use in a boss battle where being able to reincarnate can mean the difference between a win and a loss.\r\n* If you are out of mana, you can choose to deliberately die and resurrect with 20-40% mana and health and continue the fight. \r\n* Do not try this when playing solo because mobs will immediately get health back when you are dead.\r\n* If you reincarnate and die again you will take durability damage twice.\r\n* You can equip the [[Totem of Rebirth]] right before you die to decrease the cooldown of this ability by 10 minutes.\r\n* Dying will reset your threat. This is sometimes jokingly referred to as \"the shaman aggro dump\", and unlike [[Feign Death]], it cannot be resisted.",},
			["Reindeer"] = { content = "#REDIRECT [[Jingling Bell]]", redirect = "Jingling Bell",},
			["Reinforced Fel Iron Chest"] = { content = "This object can be found in [[Hellfire Ramparts]]. The chest appears after killing [[Vazruden]] and [[Nazan]].",},
			["Reins of the Black War Tiger"] = { content = "==Source==\r\nThis item is a PvP reward, and can be purchased for av=30 gold ab=30 silver wsg=30 copper from Lieutenant Karter in [[Champions' Hall]].",},
			["Reins of the Raven Lord"] = { content = "The '''Reins of the Raven Lord''' summon a Raven Lord epic ground [[mount]] that requires 150 Riding skill to ride. It looks like a hybrid between a raptor and bird; however, as a ground mount, it does not allow the rider to actually fly.\r\n==Source==\r\nReins of the Raven Lord drops off [[Anzu]], who is available to fight against in Heroic Sethekk Halls for the Druid Epic Flight Form quest line.\r\nThe drop rate, according to [[|external data sites]], seems to be less than 1%.",},
			["Reins of the Swift Mistsaber"] = { content = "==Source==\r\nThis item can be purchased for g=100 gold from Lelanai in [[Teldrassil]].\r\nThis item is a quest reward from the following quests:\r\n* Frostsaber Replacement\r\n* Nightsaber Replacement",},
			["Reins of the Swift Spectral Tiger"] = { content = "The '''Reins of the Swift Spectral Tiger''' summon a Swift Spectral Tiger epic [[mount]].\r\n==Source==\r\nThis item comes from a special loot card from the [[TCG Fires Of Outland|Fires of Outland]] set of the [[World of Warcraft Trading Card Game]]. The loot card unlocks the option to buy it from Landro Longshot in [[Booty Bay]]. The mount costs 100 gold copper .\r\nThe code also unlocks the option to purchase a non-epic standard mount; Reins of the Spectral Tiger at level 40.\r\nThe odds of pulling a Spectral Tiger Loot card out of a Fires of Outland TCG pack are speculated to be around 1 in 7,260.\r\nThe first Spectral Tiger card sold on eBay for $2,000. Cards currently sell in the range of $500 to $800 on eBay.\r\nUnlike other loot cards in WOW TCG sets 1 and 2, this loot item requires you to spend gold to acquire it. This is because the loot items are not supposed to affect gameplay by giving a player an advantage over another; thus, it merely unlocks the option to purchase a different mount rather than giving a free mount.",},
			["Reins of the Winterspring Frostsaber"] = { content = "'''Reins of the Winterspring Frostsaber''' summons a unique [[frostsaber]] [[mount]] that is not wearing any armor. It is the only [[epic]] mount (100% speed increase) that can be used with the novice riding skill; however, players must still be level 60 to use the mount.\r\n==Source==\r\nThis mount is sold by [[Rivern Frostwind]] on [[Frostsaber Rock]] in [[Winterspring]] for 100 gold . You must be with the [[Wintersaber Trainers]] to purchase this mount.\r\n==Notes==\r\nNo longer requires exalted reputation with [[Darnassus]] to ride.\r\n",},
			["Rejold Barleybrew"] = { content = "'''Rejold Barleybrew''' is a level 10 [[quest giver]] located in [[Brewnall Village]] in the [[dwarven]] starting zone of [[Dun Morogh]].\r\nOther members of the Barleybrew family include [[Malgin Barleybrew|Malgin]], [[Marleth Barleybrew|Marleth]], [[Mountaineer Barleybrew|Wellart]], and [[Yorus Barleybrew|Yorus]].\r\nHe starts the following quests:\r\n* A Favor for Evershine\r\n* Return to Bellowfiz\r\n* The Perfect Stout\r\n* Shimmer Stout\r\nSee [[List of Dun Morogh NPCs]].",},
			["Rejuvenation"] = { content = "The first druid [[Heal over Time]] spell.\r\n==Notes==\r\n*Heal over Time is useful to \"prevent\" damage while in combat.\r\n==Tips and tactics==\r\n*Use it while traveling. This will allow you to remain alive long enough to get past a mob without needing to defeat it.\r\n*Rejuv is a cheap, effective HoT. Use it when you or your teammates are moderately damaged or are not in immediate danger of being hit. At lvl 64 and beyond, [[Lifebloom]] can be substituted for this purpose.\r\n*Use it on the tank(s) ''before'' a pull (before they enter combat) so that its ticks will heal the damage of the first few hits done to him without putting you into combat, reducing your threat and increasing the tank's aggro (since the mob thinks he's healing himself).\r\n*To increase Healing per Second, use [[Swiftmend]] after the 3rd tick, and recast Rejuvenation right away.",},
			["Relara Whitemoon"] = { content = "Daughter of Pelturas Whitemoon. She suffers from raging nightmares and a mysterious magical fever that can only be cured by three separate ingredients: [[Handful of Stardust|Stardust]], [[Elune's Tear]], and a [[Fallen Moonstone]].",},
			["Relentless Strikes"] = { content = "'''Relentless Strikes''' is a 10 point [[Rogue]] talent located in the 3rd tier of the [[Rogue_talents|Assassination Tree]].\r\n==Tips & Tactics==\r\n*Relentless Strikes is one of the best talents you can buy. Make sure you include this in all your combat and mutilate builds.\r\n*It essentially allows certain finishing moves to be used in such a way that your energy acts as though you did not use a finishing move at all. For example, if you use a finishing move that requires 25 energy, then you will have not used any energy at all.",},
			["Relfthra"] = { content = "Not much is known of '''Relfthra''', other than the fact that he was an elder [[high elf]] and a member of the [[Order of Tirisfal]] when [[Aegwynn]] was chosen as Guardian. After Aegwynn banished the demon [[Zmodlor]] to the [[Nether|Twisting Nether]], Aegwynn was met with criticism from Relfthra, who, along with [[Erbag]] the [[gnome]], claimed she had rushed in to counter the threat from Zmodlor without thinking of possible greater risks to the world. \r\nIt is likely that Relfthra still lived during the time of the council's downfall, as he was present when Aegwynn went against the council to choose [[Medivh|her own successor]].",},
			["Relic"] = { content = "'''Relic''' refers to a type of equipment worn in the relic [[equipment slot]] by [[druid]]s, [[paladin]]s and [[shaman]]s and ranged [[equipment slot]] by [[warlock]]s. Relics were added in [[Patch 1.10]]. Relics usually give bonuses to a specific spell or ability.\r\nThere are five different types of relics, each specific to a class:\r\n* [[Idols]] used by Druids.\r\n* [[Libram (relic)|Librams]] used by Paladins.\r\n* [[Totem (relic)|Totems]] used by Shamans.\r\n* [[Spellstone]]s and [[Firestone]]s used by Warlocks.\r\n* [[Sigil]]s used by Death knights.",},
			["Relic Bundle"] = { content = "== As a quest objective==\r\nThis item is provided for The Battle of Darrowshire.",},
			["Relic Coffer Key"] = { content = "The '''Relic Coffer Key''' is required to open the [[Relic Coffer Door]]s in [[Blackrock Depths]]. These doors cannot be [[Pick Lock|lockpicked]].\r\n==Source==\r\nThis item is a common drop from [[Trash Mob]]s in [[Blackrock Depths]].\r\n==Note==\r\nYou need 12 Relic Coffer Keys to open all the coffer doors to spawn [[Watchman Doomgrip]] for the quest [[Quest:The Heart of the Mountain|The Heart of the Mountain]]. Once you have defeated Doomgrip, the quest item [[Heart of the Mountain]] spawns in the back of the Vault.",},
			["Religion"] = { content = "Most races possess some sort of cultural faith that reflects their values, fears and hopes. Races sometimes personify their faiths in the form of a god, but members of the race understand that their “god” is really just a symbol of their philosophical beliefs, not an actual being. Some, however, see actual beiungs as God or Demi-Gods that do exist (either as a God or as a demigod is debatable among the races thmselves), such as those who view Cenarius as a Demigod. Others, such as the Titans, are seen as beings that actually exist, not symbolism for philisophic beliefs. Others, such as the Firelord Ragnaros, are seen by some to have achieved a god-like status. Most racial faiths include the concept of an afterlife, along with cultural mores and taboos to indicate the correct path to the afterlife. Spiritual leaders who guide their race along the proper philosophical path tend to be shaman or druids. Few races revere an actual deity to whom they can dedicate their lives as priests.In the quest The Formation of Felbane, the quest giver, [[Loramus Thalipedes]], mentions the concept of a singular god as a blessing; \"May your determination and faith, carry you through this ordeal. Should you fail, know that your God smiles down upon you, mortal.\"\r\nThe following are the currently known '''religions''' in the [[Warcraft Universe]]:\r\n*'''The [[Holy Light]]'''\r\n** Members: [[human]]s, [[Dwarf|Ironforge dwarves]], [[Wildhammer|Wildhammer dwarves]], [[high elf|high elves]], [[naaru]], [[draenei]], [[Half-elf|half-elves]], [[blood elf|blood elves]] (somewhat)\r\n** Organizations: The [[Church of the Holy Light]], The [[Silver Hand]], The [[Argent Dawn]], The [[Scarlet Crusade]], The [[Brotherhood of the Light]], The [[Sha'tar]], The [[Aldor]], The [[Scryers]], the [[Hand of Argus]], the [[Blood Knight]]s (somewhat)\r\n*'''[[Shaman lore|Shamanism]]'''\r\n** Members: [[orc]]s, [[troll]]s, [[tauren]], [[draenei]], [[furbolg]]s, [[Wildhammer|Wildhammer dwarves]], [[tuskarr]], [[quilboar]] and [[ogre]]s\r\n** Organizations: The [[Earthen Ring]], The [[Mag'har]], The [[Kurenai]]\r\n*'''[[Druid (lore)|Druidism]]'''\r\n** Members: [[night elves]], [[tauren]], [[half-elves]], [[Wildhammer|Wildhammer dwarves]], [[furbolg]]s (debated), [[High Elves]] (somewhat)\r\n** Organizations: The [[Cenarion Circle]], The [[Cenarion Expedition]]\r\n*'''[[Elune]]'''\r\n** Members: [[night elves]], [[wildkin]]s\r\n** Organizations: The [[Sisters of Elune]], The [[Priestess of the Moon|Priestesses of the Moon]], The [[Sentinel]]s\r\n*'''[[Mystery of the Makers]]'''\r\n** Members: [[Dwarf|Ironforge dwarves]]\r\n** Organizations: The [[Explorers' League]], The [[Sister of steel|Sisters of steel]]\r\n*'''[[Shadow]] and [[Necromancy]]'''\r\n** Members: [[undead]] beings, living followers\r\n** Organizations: The [[Cult of the Damned]], The [[Scourge]], The [[Cult of the Forgotten Shadow]]\r\n*'''[[Fel]] and [[Demonology]]'''\r\n** Members: [[warlock]]s, [[demon]]s, [[satyr]], [[fel orc]]s, Fel-corrupted races\r\n** Organizations: The [[Burning Legion]], The [[Illidari]], The [[Shadow Council]]\r\n*'''Followers of The [[Old Gods]]'''\r\n** Members: [[naga]], [[elemental]]s (prior to [[The Old Gods and the Ordering of Azeroth|the ordering]]), [[qiraji]], [[nerubian]]s\r\n** Organizations: The [[Twilight's Hammer Cult|Twilight's Hammer]]\r\n*'''[[Voodoo]] and [[Loa|Loa-worship]]'''\r\n** Members: [[troll]]s\r\n*'''[[Geomancy]]'''\r\n** Members: [[pandaren]], [[trogg]]s, [[quilboar]], [[kobold]]s\r\n*'''[[Mage (lore)|Arcanum]]'''\r\n** Members: [[human]]s, [[High elf|high elves]], [[naga]], [[gnome]]s, [[Blood Elf|blood elves]], [[draenei]], [[undead]], [[troll]]s, \r\n** Organizations: The [[Kirin Tor]], The [[Echo of Life]]\r\n*'''[[Dragons]]'''\r\n** Members: [[human]]s, [[orc]]s, [[draenei]], [[Night elf|night elves]], [[dragonspawn]]\r\n** Organizations: The [[Wyrmcult]], the [[Sect of the Dragons]]\r\n==Miscellaneous faiths==\r\n*[[Divine humanism]] is the concept that the self shapes the universe. In essence, each sentient creature in the world is a tiny god, able to exert her will to manifest small changes in the universe.\r\n===Scourge/Cult of the Damned===\r\nHeeding the call of the god-like Lich King, Kel'Thuzad traveled to Northrend and offered his soul to Ner’zhul. Kel'Thuzad’s first mission was to found a new religion that would worship the Lich King as a god. Sometimes liches act as though Ner'zhul were a god and they were his chosen priest or prophet. The lich king wants to retake control of the Forsaken, becoming king — or god — of all undead.\r\n===Furbolgs culture===\r\nSome accounts have them worshipping primitive godlike figures, but primarily they revere nature and the spirits of the world.\r\n===Night elves in other cultural beliefs===\r\nIn the early histories of dwarves and humans, the Kaldorei are shadowy figures of dark perfection wielding incredible god-like powers. Tauren sometimes view night elves with awe and fear. Tauren have long seen the Kaldorei as a mythic race of demigods, possessed of great magic and steeped in natural powers.\r\n===Ogre culture===\r\n*Among ogres, bone crushers are seen as the living avatars of Nath. In a society that prize strength above anything else, a bone crusher is as close to a god as an ogre can get.\r\n*[[Nath]] is the ogre war god revered by both ogres and half-ogres. The term mok'nathal means the \"sons of nath\".\r\n===Forsaken culture===\r\n*Forgotten shadow is a faith that preaches the ability to ascend to godhood. The ultimate goal of practitioners of the Forgotten Shadow is to ascend. Ascension occurs once a person achieves complete control over herself and the power to transcend death. A Forsaken who ascends becomes invulnerable, invincible and eternal. In essence, she becomes a god.\r\n===Outland faiths===\r\n*[[Anzu]] \r\nAnzu the Raven God is said to be rising again soon in the Prophecy of the Raven God. \r\n*[[Terokk]]/[[Rukhmar]] \r\nTerokk was the greatest hero of the arakkoa, closely associated with their god Rukhmar. He left his people when worship of Rukhmar began to wane, leading to speculation that he was Rukhmar in mortal form. It is unknown if they are the same being, or are separate beings that were combined in stories as the legends of Terokk were retold throughout the years. \r\n*[[Murmur]] \r\nMurmur is a being from a dimension of the cosmos unfathomable to mortal minds. Its very entrance into existence shattered all reality around it. Murmur is a god that, when summoned by a mortal possessed of arcane and dark knowledge, eventually destroyed the world of the summoner. The Shadow Council is now trying to bring forth this entity into Outland.\r\n===Murloc culture===\r\n*[[Deep Mother]]\r\n*The [[One in the Deeps]]\r\n*[[Sea Witch]] a mysterious goddess, a powerful naga spellcaster.\r\n==See also==\r\n* [[Shamanism and Nature Worship]]\r\n* [[:Category:Religions|Religions category]] for a list of other categories or articles on religions.",},
			["Reliquary of Souls"] = { content = "'''Reliquary of the Lost''' (often also referred to as the Reliquary of Souls) is a [[boss]] in the [[Black Temple]]. This boss is a figure with three faces, representing the Essences of Anger, Desire and Suffering respectively. The three have to be defeated one after the other. They all are [[DPS race]]s, each with a different twist.\r\n==Abilities==\r\nEach Essence has an aura which is not removable, and raid-wide in effect until the aspect is defeated.\r\n===Essence of Suffering===\r\n*'''Health''': ~2.500.000 HP\r\n*'''''': Reduce healing, regeneration and armor by 100% and defense by 500\r\n*'''''': lock aggro on closest target every 5 sec\r\n*'''Enrage''': every 45 sec increase physical damage by 25% and attack speed by 50% for 15 sec. (Please confirm. In 2.4 our WWS log seems to indicate double the damage and double the speed. 2,500 average damage every 0.5 seconds during enrage, versus 1,250 damage every 1.0 seconds normally)\r\n*'''''': 30 sec dispellable debuff on three random targets, 2625 to 3375 damage plus 2625 to 3375 mana drain every 3 sec\r\n*Cannot crit or crush\r\n===Essence of Desire===\r\nAll spells used by EoD can be interrupted, reflected or spell stolen.\r\n*'''Health''': ~3.000.000 HP\r\n*'''''': 50% of damage dealt hits the player. Healing increased by 100%. Max player mana reduced by 5% every 8 seconds (after 160 seconds mana users have 0 mana)\r\n*'''''': 1 sec cast, increase damage taken by 100%, 10 second duration\r\n*'''''': 1 sec cast, 9250-10750 arcane damage plus 5 sec confuse\r\n*'''''': 15 sec duration. Absorb 50000 damage, grant immunity to interrupt effects. Increases attack and cast speed by 100%\r\n===Essence of Anger===\r\n*'''Health''': ~3.000.000 HP\r\n*'''''': Deals shadow damage which increases by 100 per 3 second [[tick]] (100 after 3sec, 200 after 6 sec then 300 etc..). Also increases damage dealt by players by 5% each tick\r\n*'''''': After aggro switch or taunt ability usage, EoA gets a 10 sec buff increasing attack speed by 100% and size by 20%, the raid takes a 10 sec debuff increasing threat gained by 200%\r\n*'''''': 5 targets in a 10-yard frontal cone take 2625-3375 shadow damage plus 4375-5625 mana/rage burn (0.5 damage for 1 mana, 100 damage for 1 rage), 10 sec cooldown\r\n*'''''': 3 random targets get a debuff which grants 2 sec immunity, then deals 7444-7556 nature damage followed by another 2 sec immunity\r\n===Enslaved Souls===\r\n* '''Melee''': ~600 on cloth\r\n* '''Soul Release''': 15 yard AoE, restoring about 30% health and mana upon death\r\n==Preparation==\r\nRaid composition:\r\n*1 Warrior Tank (additional paladin tank useful in phase 3)\r\n*6-7 healers (6 healers is better than 7)\r\n*17-18 damage dealers including at least 2 (better 3) Rogues\r\n===Running the Gauntlet===\r\nIn the corridor leading to the boss, mobs are on a 15 sec [[respawn]] timer, so the raid has to run through it fast. There is no safe place between the trash mobs and the boss. The raid must stay close together at all times. No totems must be dropped (else they aggro respawns). The raid should stop and [[AoE]] after one third of the distance, a second time after two thirds, and the last time on top of the ramp leading down to the boss. When nuking, AoE capable classes should do AoE, and point damage dealers should concentrate on the red ghosts first, these are the most dangerous type. It's best to continue moving after all red ghosts are dead, and just keep the larger blue and purple ones tanked - these two types don't deal substantial amounts of damage.\r\nUpon reaching the top of the ramp, it's safest to wait for one repop of the last group, kill them, and then engage RoS fully rezzed, buffed and coordinated. The boss becomes active 15 seconds after the first person steps on the ramp.\r\n==Phase 1: Essence of Suffering==\r\nThis phase is characterized by two things - healing is impossible, and aggro can be easily controlled. Beyond that, Soul Drain must be dispelled immediately.\r\n===Tank switching===\r\nSince no healing is possible, tanks must be rotated. To facilitate this EoS should move as little as possible. The red circle on the ground marks EoS' melee range. The current tank should stand in the center of EoS, only if a change is due the new tank moves into the current tank, and the current tank takes one step back. Tanks can usually stay for several fixates and should switch only after their health is low (~15%), or if an enrage is due.\r\nHigh block value is desirable for all players planning to tank in this phase.\r\n===Enrage===\r\nBest suited for enrage tanking are rogues with [[Evasion]] available (incidentally evasion and the enrage have exactly the same duration). With normal DPS, three enrages can be expected, thus three rogues should be pre-designated. They must step in and take a fixate as in the normal tank rotation, and hit evasion as soon as EoS enrages.\r\nThe rogue must not use [[Vanish]] after the enrage is over, but rather hand over aggro as described above. If the current tank dies or somehow removes himself from the combat (e.g. with a paladin bubble), EoS switches to normal aggro mechanics (which is very bad).\r\nWith good dodge/parry gear, one rogue can tank a whole cycle (all non-enraged fixates plus one enrage).\r\n===Healing===\r\nNormal healing cannot take place during this phase. The only abilities which help are [[Blessing of Sacrifice]], [[Power Word: Shield]] and [[Pain Suppression]]. Priests should spam PW:S freely, it's also a good idea to cast it on the enrage tank 15 sec before the enrage, so that the weakened soul debuff has worn off and a second shield can be cast during enrage. The safest method to deal with Soul Drain is to have two priests hit [[Mass Dispel]] every time it happens.\r\n===Alternate tanking rotation===\r\nThe whole raid (except the three rogues) stand on the boss. When a player gets fixated, he moves outside the group (but not far, so that the boss doesn't move), thus another player gets fixated next. When an enrage is near, everyone moves out from under the boss except the current fixated person and a rogue moves in. The raid moves back in when less than five seconds of enrage remain, so that the next fixate after the enrage is taken by somebody else again.\r\n==Ghost interphase==\r\nAfter EoS is defeated, it goes back into the Reliquary. At that point, several ghosts spawn and head towards the raid. To maximize the health and mana gain, the raid should all stand on one spot. It's a good idea to use mana intensive abilities (such as making mana gems or summoning new demons) at the beginning of the ghost phase so that the players can start the next phase with full mana. Paladins with [[Improved Lay on Hands]] can use it on the tank at the very start of this phase to give him the 30% armor buff.\r\n==Phase 2: Essence of Desire==\r\nThis phase is all about spell steal/interrupt/reflect, beyond healing through the massive damage the raid deals to itself (from the aura). Since EoD deals only low amounts of melee damage, rage generation can be a problem. Therefore the tank should not use abilities like Demo Shout or Thunderclap, while [[Curse of Recklessness]] is very useful. Warlocks should keep [[Curse of Tongues]] up, and a rogue should use [[Mind-numbing Poison]]. Paladins in caster groups should use [[Concentration Aura]]. Similarly, put [[Earth Shield]] on casters to reduce spell interruption by damage. For classes whose DPS consists of many hits for smaller amounts of damage (such as rogues and affliction warlocks), [[Dampen Magic]] can be useful.\r\n===Spell handling===\r\n*The main tank must use [[Spell Reflection]] on Deaden (the first time after about 30 seconds)\r\n*Two rogues should set up a Spirit Shock interrupt routine so that it doesn't hit the MT. Using two rogues has the advantage that they each know that the next Shock is due when their Kick becomes available again\r\n*It's best to [[spellsteal]] the Rune Shield, but that incurs the danger of a not interruptable Spirit Shock (if the mage is slow), so having a [[Felhunter]] eat it is safer (because the Felhunter is always on the boss)\r\n===Healing===\r\nThis phase is very healing intensive. Since all damage dealers take 50% of their damage done, raid healers are very busy. Particularly after a spell reflected Deaden is up, damage dealers must be careful not to kill themselves.\r\n===Tips===\r\n*If the raid gets near 0% mana and a kill is within reach, priests can use [[Inner Focus]] to cast one last spell (e.g. [[Mass Dispel]] the shield), yielding a few precious extra seconds to kill it for the melee damage dealers\r\n*Resummoning felhunters during this phase resets their mana to 100% so even though the raid is drained they may still have mana (depending only on how long they have been in the fight)\r\n*Players can restore their mana pools by dying and rezzing ([[Reincarnation]], [[Soulstone]], or [[Rebirth]]), [[Divine Intervention]] kills the paladin but restores the targets mana pool too (so if the paladin has a soulstone, two players can restore their mana)\r\nOnce Essence of Desire returns to the Reliquary, the ghosts appear once more and refill the raids mana and health\r\n==Phase 3: Essence of Anger==\r\nThe initial Seethe buff on the boss can be removed with [[Shield Slam]]. To avoid further Seethes, the tank must never lose aggro. Nonetheless, all raid members initially have the Seethe debuff and must therefore be very careful not to draw aggro.\r\n===Tanking===\r\nSince the tank is regularly affected by Soul Scream, and the damage by rage burn is higher than that from mana burn, a paladin tank is a good alternative to a warrior tank in this phase.\r\nEoA should be tanked facing away from the raid. Threat generation is crucial. The tanks must spam all his abilities to keep rage (or mana) low. If a Soul Scream is near and a warrior tank has excess rage, he must stance dance to reduce the rage, even though this hurts aggro buildup. Paladins can dump excess mana by rebuffing [[Righteous Fury]] (or [[Lay on Hands]]).\r\n===DPS===\r\nDamage dealers must be very careful while they have the Seethe debuff. After the second scream (at about 20 seconds), everybody should use all DPS cooldowns (and [[Heroism]]/[[Bloodlust]]), Hunters should use [[Misdirection]], and everybody should go all-out (still trying not to draw aggro).\r\n===Healing===\r\nAbout two healers should be on the tank, and four (preferably shamans and/or priests) on the raid. While the Aura damage is low, healers may even DPS a little if they have excess mana. Players afflicted by Spite must be topped up before they take the nature damage, and then immediately topped up again before the Aura kills them.\r\n===Alternate Strategy===\r\nThe seethe (de)buff increases aggro generation by 200% for 10 seconds. If an off-tank initially pulls EoA and the main tank [[taunt]]s after 1-2 seconds, the MTs aggro generation is increased substantially. As in the normal scenario, the raid must be very careful at start, but can start all-out DPS a little earlier (at about 12-15 seconds).\r\n==Quotes==\r\n*Note: Sounds are as they are named in the MPQ file.\r\n==Notes==\r\n* Arcane spec mages excel on this fight, -40% threat from talents, 100% interrupt resist and mana reset to 100% after every phase they can make the most of the superior dps offered by the spec while going oom should not be a problem\r\n* [[Tranquil Air Totem]]s can be useful in phase 3 as damage is restricted by threat, the extra threat reduction allows more damage than the Windfury or Wrath of Air totems would bring. \r\n* Windfury Totem in the MT's group helps '''significantly''' with threat generation in phases 2 and 3.",},
			["Rellian Greenspyre"] = { content = "'''Rellian Greenspyre''' is a level 17 quest giver located outside the [[Cenarion Enclave]] in the [[night elf]] city of [[Darnassus]].\r\nHe starts the following quests:\r\n* Tumors\r\n* Return to Denalan\r\nSee [[List of Darnassus NPCs]].",},
			["Remains of a Paladin"] = { content = "'''Remains of a Paladin''' is a level 35 [[quest giver]] found in [[Uldaman]]. Not much is known about him, apart from the fact that he is dead. He has the model of a [[forsaken]].\r\nHis remains are located close to the beginning of the instance, on the northern side where the temple is split into four corridors (the paths with right angles) - it is in the latter half of this section.\r\nThe remains starts the following quests:\r\n*Translating the Journal\r\n*Find the Gems\r\nSee [[Uldaman NPCs]].",},
			["Remains of Trey Lightforge"] = { content = "==Source==\r\nThis item is a quest reward from Retribution of the Light in [[Felwood]].\r\nThis item is provided for The Remains of Trey Lightforge in [[Felwood]].\r\n==Remains of Trey Lightforge as a quest objective==\r\nThis item is an objective of The Remains of Trey Lightforge in [[Felwood]].",},
			["Remen Marcot"] = { content = "'''Remen Marcot''' is a level 10 quest giver located in the basement of the [[Lion's Pride Inn]] of [[Goldshire]] in [[Elwynn Forest]].\r\nHe begins the [[warlock]] quest Gakin's Summons.",},
			["Remka"] = { content = "#redirect [[Lorin Remka]]", redirect = "Lorin Remka",},
			["Remorseful Highborne"] = { content = "The '''Remorseful Highborne''' is a level 56 [[quest giver]] [[banshee]] located at the [[Ruins of Kel'Theril]] in the [[contested]] territory of [[Winterspring]].\r\nShe ends the quest Tormented By the Past.\r\nShe starts the quest Remorseful Highborne.\r\nSee [[List of Winterspring NPCs]].",},
			["Remorseless Attacks"] = { content = "'''Remorseless Attacks''' is a [[Rogue]] talent located in the 1st tier of the [[Rogue_talents|Assassination Tree]].\r\n==Notes==\r\n*This effect stacks with the talent [[Improved Ambush]].",},
			["Remote-Controlled Golem"] = { content = "'''Remote-Controlled Golem''' can be found in [[The Deadmines]].",},
			["Remove Curse"] = { content = "'''Remove Curse''' is a [[mage]] spell that removes one [[curse]]-type [[debuff]] from a [[friendly]] target player.\r\n==Notes==\r\n[[Druids]] have a spell named [[Remove Curse]], both spells are capable of removing the same curses.\r\n==Tips and tactics==\r\nKeep this one handy. A lot of [[mob]] curses are crippling to your group members, especially in raid situations. This is also effective against [[Warlocks]] in [[PvP]]. One of their nastiest [[DoT]]s is a curse: [[Curse of Agony]]. They'll use much more mana putting up curses then you will taking them back down.\r\n===Handy macro===\r\nThe following macro will cast Remove Lesser Curse on the target underneath your mouse pointer, without losing your current target. This is handy if you have a group or raid party frame that prominently displays curses that you can remove. Simply hover the mouse over the target and tap this macro. \r\n /cast [target=mouseover] Remove Lesser Curse",},
			["Remove Lesser Curse"] = { content = "#REDIRECT [[Remove Curse]]", redirect = "Remove Curse",},
			["Remtravel's Excavation"] = { content = "'''Remtravel's Excavation''' is named after the famous archaeologist, [[Prospector Remtravel]]. At the digsite, he has discovered a most unusual fossil of mystic properties, but the absent-minded prospector has forgotten where he put it. The digsite has also been invaded by [[trogg]]s and huge [[golem]]s which have been unearthed in the dig, and entering the excavation without the proper training can be very hazardous.",},
			["Remulos"] = { content = "'''Keeper Remulos''' is a level 72 [[elite]] [[quest giver]] located at the [[Shrine of Remulos]] in the [[contested]] territory of [[Moonglade]]. He is one of the younger sons of [[Cenarius]], and a [[Keeper of the Grove]]. [[Zaetar]] is his elder brother.\r\nRemulos was Malfurion's chief advisor and, a thousand years ago, he helped forge the Cenarion Circle by teaching men to become druids. Perhaps the most powerful druid in the world, the other members of the group hold Remulos in great reverence.\r\nLike [[Cenarius]], he has produced many children, including [[Celebras]], [[Cavindra]] and several other [[dryads]]. He resembles his father, having the lower body of a stag, the upper body of a night elf sporting antlers, and a long wooden talon for one hand. Remulos maintains the Moonglade, the sacred center of all [[druid]]ic studies. He is also an important member of the [[Cenarion Circle]], but has found himself increasingly in conflict with the [[night elf]] Archdruid [[Fandral Staghelm]]. Against Staghelm's wishes, Remulos welcomed the [[tauren]] into the Cenarion Circle and taught them many closely guarded secrets. Remulos also vehemently opposed the creation of a new [[World Tree]], seeing it as nothing more than a selfish gesture by the night elves eager to reclaim their immortality.\r\nHe starts the following quests:\r\n* The Nightmare's Corruption\r\n** The Nightmare Manifests\r\n*** The Champion Returns\r\n* Waking Legends\r\nSee [[List of Moonglade NPCs]].",},
			["Remy \"Two Times\""] = { content = "'''Remy \"Two Times\"''' is a level 5 [[quest giver]] located in [[Goldshire]] in the [[human]] starting zone of [[Elwynn Forest]]. He gets his nickname \"Two Times\" by repeating the few words ending his sentences twice. He is originally from [[Redridge Mountains]].\r\nHe starts the following quests: \r\n* A Fishy Peril\r\n* Gold Dust Exchange\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Renataki's Charm of Trickery"] = { content = "==Source==\r\nThis trinket can be created by using the Punctured Voodoo Doll (rogue).\r\nThis item can be acquired through crafting or another combine-type effect.",},
			["Renataki"] = { content = "'''Renataki''', of the Thousand Blades, is a [[ghost]] [[boss]] summoned in [[Zul'Gurub]] by using [[Gurubashi Mojo Madness]]. ''Pain is his lifeblood. Fear, his ally. May he one day return and bring joyous bloodshed with him.''\r\n==Strategy==\r\nRenataki is a [[rogue]], one of several bosses which can spawn during the [[Edge of Madness]] event within [[Zul'Gurub]]. His special ability is to use [[vanish]] and he will randomly appear and ambush someone which can do quite a bit of damage. He is not that hard of a boss, just throw a few rogues on him and have them [[tank]] him and you can [[DPS]] him down. His vanish will not break on [[dot]]s.\r\nIt can break now and then on [[AoE]] damage (also by [[warrior]]'s casting [[Demoralizing Shout]]) and bring him out of stealth, so it might be a good idea to huddle up the caster group with an OT and have the [[mage]]s and other AoE capable stand at the edges to try and make him visible again before an ambush from him, which usually kills a cloth wearer, and then let the OT pick up the [[aggro]] and bring it back to the melee group. Before he vanishes, he usually [[gouge]]s everyone in melee range, so the mages have a bit of time to get into position.\r\nOne useful tactic is to stick [[hunter]]s' and/or [[warlock]]s' [[pet]]s on him. They will continue to follow him even after he vanishes, giving you a steady indication of his position.",},
			["Renault Mograine"] = { content = "Scarlet Commander '''Renault Mograine''' is the young commander of the military forces of the [[Scarlet Crusade]] at the [[Scarlet Monastery]]. He is a level 40 [[elite]] [[paladin]] [[boss]] located in the Crusader's Chapel of the Cathedral in the Scarlet Monastery.\r\n==Biography==\r\nRenault Mograine was the older son of Highlord [[Alexandros Mograine]] — also known as the Ashbringer because of the [[Ashbringer|weapon sword]] he wielded against the Undead. When the first hint of the [[plague of undeath]] started to spread around Lordaeron he lived in a farmhouse in the south with his father and brother (his mother died due to post partum complication when his little brother, Darion was born). He joined the Silver Hand at relatively young age (he was believed to be about fifteen, soon after the end of the Third War).\r\nThe Grand Crusader [[Saidan Dathrohan]] (the mortal form of the Dreadlord [[Balnazzar]]) had struck a deal with [[Kel'Thuzad]], the lich who served as the Scourge overlord in the Plaguelands, to kill Mograine; Dathrohan/Balnazzar would be in a position to take over the Crusade and Kel'Thuzad would be rid of a great threat to his hold in Lordaeron. To that end, Dathrohan recruited young Renault, promising him great power and prestige in his Crusade if he could kill his father.\r\nRenault led Mograine and his advisor [[High Inquisitor Fairbanks|Fairbanks]] into the ruined city of [[Stratholme]], the primary fortress of the Scourge in Lordaeron, where they were to be ambushed. Fairbanks fell relatively early on, but Mograine was able to destroy the Scourge attackers. When it became clear that Mograine would prevail, Renault turned and ran, hiding until he could seize the opportunity to complete his \"mission\" from the Grand Crusader. After expending his energies against the Scourge, Mograine was weakened and dropped his sword to the ground. That was the opportunity Renault had waited for. Coming from behind his father, the boy picked up Ashbringer and ran it through Mograine's heart, killing the Highlord and fouling the blade...and dooming both to the service of Kel'Thuzad.\r\nAs promised, Renault was promoted to Scarlet Commander, and sent to the Monastery in Tirisfal as commander of the operations there. His treachery would not be forgotten though, even by the death knight that was Highlord Mograine. An army of soldiers from the [[Argent Dawn]] and the Scarlet Crusade entered into the Necropolis [[Naxxramas]] and destroyed the corrupted Highlord. One of them took his [[Corrupted Ashbringer|fouled blade]] and travelled to the Scarlet Monastery, where Renault cheered the coming of a new Ashbringer to lead the Scarlet Crusade to victory against \"the filth of this world\" — in essence, those who were not of the Crusade. Upon entering the Crusader's Chapel, however, Highlord Mograine was to have his revenge...\r\nThe Highlord's spirit, chained to the corrupted blade, appeared in the chapel and confronted his horrified son with his treachery. He then lashed out, killing the Scarlet Commander instantly. Thus, as had happened in the reverse five years earlier, Renault Mograine was killed by his own father, an act of revenge that would not be forgotten by either the Scarlet Crusade or any who witnessed it that day.\r\n==In World of Warcraft==\r\n[[Raleigh the Devout]] in the [[Hillsbrad Foothills]] instructs Alliance players to kill Mograine as part of [[Quest:In the Name of the Light|In the Name of the Light]], while [[Varimathras]] in the [[Undercity]] instructs Horde players to kill him to fulfill [[Quest:Into the Scarlet Monastery|Into the Scarlet Monastery]]. However, these attempts to end the Commander's life seem to have failed, as he is in the end slain by his own father's spirit as part of the Corrupted Ashbringer event.\r\n===Encounter===\r\nMograine and Whitemane are part of a scripted two-part boss fight. After clearing the Crusader's Chapel of the other Crusaders (every nook and cranny in the Chapel MUST be cleared, to avoid being attacked by the trash during the battle with Mograine), you can safely aggro the Scarlet Commander. Only the patrolling trash will respawn, so you can take as long as you like on the stationary mobs in the cathedral. He uses [[Hammer of Justice]] (3 sec stun), Crusader Strike (increases holy damage on target), [[Retribution Aura]], and [[Divine Shield]] (invulnerable for 10 seconds). He hits hard and can take a lot of pain — but he does not heal.\r\nAfter he dies, High Inquisitor Whitemane comes out and attacks; once she reaches about 40-50%, she sleeps the entire group (even any high level help you might have) and resurrects Mograine. Due to popular belief it is thought that you need to kill Whitemane first or she will resurrect Mograine again, she does not, but it is good to kill Whitemane first because she will heal herself and Mograine occasionally. <strike>If Whitemane is killed before she resurrects Mograine, he becomes unlootable.</strike> It is not possible to kill Whitemane before she resurrects Mograine, only to bring her down to 1% health. Also, if you kill Whitemane but die while fighting Mograine, then when you go back into the instance you will not be able to find him.\r\n===Quests===\r\n*In the Name of the Light\r\n*Into the Scarlet Monastery\r\n==Quotes==\r\nRenault Mograine can be found as a young boy in Southshore in the [[Old Hillsbrad Foothills]], accessible via the [[Caverns of Time]].\r\nIn [[Old Hillsbrad Foothills]], you are able to see younger versions of [[Sally Whitemane]], Renault Mograine, and [[James Vishas|Little Jimmy Vishas]] playing around and capturing a critter next to them (a frog).\r\n'''Sally Whitemane''' says: My champion, destroy this monster!\r\n'''Renault Mograine''' says: The infidel shall be purified, milady!\r\n'''Renault Mograine''' says: ARGH! It has struck a fatal blow! I have failed you...\r\n''(Renault Mograine staggers about as if he were mortally wounded.)''\r\n'''Sally Whitemane''' says: Mograine has fallen! You shall pay for this treachery! Arise, my champion! Arise!\r\n''(Sally Whitemane pretends to cast a healing spell on Renault.)''\r\n'''Renault Mograine''' says: At your side, milady!\r\n'''Sally Whitemane''' says: We will attack as one!\r\n[not in orange letters ingame] (the captured critter dies)\r\n(The children cheer.)\r\n'''Sally Whitemane''' says: We are victorious!\r\n==Scarlet Monastary==\r\n'''Aggro:''' ''\"Infidels. they must be purified!\"''\r\n'''Resurrected:''' ''\"At your side, [[Sally Whitemane|milady]].\"''\r\n'''Killing A Player:''' ''\"Unworthy.\"''",},
			["Rend"] = { content = ":''Were you looking for [[Rend Blackhand]]?''\r\n''\"I gave him a choice: die piece by piece, or all at once.\" — Gorebelly''\r\n'''Rend''' is a damage over time ability. It is an instant cast, so it doesn't replace a normal attack. It is also one of the few [[warrior]] attacks that isn't mitigated by enemy armor.\r\nEven without investing in talents to improve it, Rend is a very rage-efficient attack. Investments in [[Improved Rend]] and [[Blood Frenzy]] makes it shine even brighter. It's disadvantages are partly that it loses efficiency if the target dies before the Rend has completed it's duration. Also, Rend can not be used in Berserker Stance.\r\n==Use==\r\n*Cast Cost: 10 [[Rage]]\r\n*Cast Time: [[Instant]]\r\n*Duration: 9-21 seconds (varies with rank)\r\n*School and Damage Type: Physical ([[Bleed]])\r\n*Targets/Positioning: Single target/front\r\n*Range: 5 yards (Melee)\r\n*Cooldown: Global\r\n*Stances: [[Battle Stance]], [[Defensive Stance]]\r\n*Requires a melee weapon\r\n==Talents==\r\n[[Improved Rend]] (Increases total damage by up to 75%)\r\n[[Blood Frenzy]]\r\n==Rank Table==\r\n1Additional damage is added based on weapon damage and other factors. See below.\r\n==Additional damage==\r\nIn addition to the base damage, Rend will deliver extra damage depending on how hard the weapon hits. The formula looks a bit complicated, but it basically calculates the average weapon damage modified for attack power and takes a fraction of this:\r\n<pre> Weapon Speed x Attack Power 743 \r\nExtra damage = ( --------------------------- + Average Weapon Damage ) x Duration x ------\r\n 14 300000</pre>\r\nNote, The DPS of the weapon isn't the most important factor. It's much more important that the weapon is slow.\r\nExample: Wally the Warrior has an attack power of 1400, and he uses a Rend with a duration of 21 seconds. When he uses [[The Unstoppable Force]] (Speed 3.8, average damage 233½) his rends will do 32 points additional damage. When he uses [[Widow's Remorse]] (Speed 1.6, average damage 100½) his rends will only do 13 points of additional damage, even though Widow's Remorse has a slightly higher DPS-rating than the Unstoppable Force.\r\n==Tips and Tactics==\r\nThis is also a good skill to use in PvP against Rogues, as it makes it more difficult (but not impossible) for them to use [[Vanish]] and an additional opener such as [[Cheap Shot]] or [[Ambush]].\r\nAs with other bleeding effects, elementals and skeletal undead are immune to Rend.",},
			["Render's Camp"] = { content = "'''Render's Camp''' is an [[orcish]] outpost in the northwestern [[Redridge Mountains]] near the entrance to the [[Burning Steppes]]. The camp, much like [[Render's Valley]] and [[Render's Rock]], is named after [[Rend Blackhand]] and contains a number of powerful [[Blackrock Clan|Blackrock]] orcs.",},
			["Render's Rock"] = { content = "'''Render's Rock''' is a large cave in the northwestern [[Redridge Mountains]] near the entrance to the [[Burning Steppes]]. The cave, much like [[Render's Valley]] and [[Render's Camp]], is named after [[Rend Blackhand]] and contains a number of powerful [[Blackrock Clan|Blackrock]] orcs.\r\nRender's Rock is also the location of the wounded [[Corporal Keeshan]], who needs help in getting to [[Lakeshire]] in one piece.",},
			["Render's Valley"] = { content = "'''Render's Valley''' is an [[orcish]] outpost in the southeastern [[Redridge Mountains]]. The valley, much like [[Render's Camp]] and [[Render's Rock]], is named after [[Rend Blackhand]] and contains a number of [[Blackrock Clan|Blackrock]] orcs. The orcs here are not as powerful as the ones in the northwest.\r\nThere is a [[Captured Servant of Azora]] in one of the valley's camps, and he offers special tailoring supplies to adventurers who can reach him.\r\nThe mountains just south of Render's Valley contain an \"undocumented\", hard to find mountain pass to the [[Swamp of Sorrows]].",},
			["Rendow"] = { content = "'''Rendow''' is a level 45 [[leather]] [[armor]] [[vendor]] located in [[Thalanaar]] in the [[contested]] territory of [[Feralas]].\r\nSee [[List of Feralas NPCs]].",},
			["Renee Lauer"] = { content = "'''Innkeeper Renee''' is a level 30 [[innkeeper]] and general goods [[vendor]] located in [[Gallows' End Tavern]] in [[Brill]], in the [[forsaken]] starting zone [[Tirisfal Glades]].\r\n==Quests==\r\nShe ends the quest A Rogue's Deal.\r\n==See also==\r\nSee [[List of Tirisfal Glades NPCs]].",},
			["Renew"] = { content = "==Overview==\r\nRenew is a [[Heal over Time]] (HoT) spell. Renew is a strong heal, and one of the more mana efficient heals the priest has available. Being by nature a HoT, it has slow moving [[Threat|threat]], so it can play as a useful opening heal while your tank gains [[Formulas:Aggro|aggro]] or serves as a solid heal while aggro is bouncing.\r\n===Use===\r\n*Cast Time: Instant\r\n*School: [[Schools_of_Magic|Holy]]\r\n*Type: Single Target Heal over Time\r\n*Range: 40 yards\r\n*Cooldown: [[Cooldown|Global]]\r\n*Duration: 15 sec.\r\n*Classification: [[Dispel_Type|Magic]]\r\n===Talents===\r\n*[[Priest_Talents|Improved Renew]]\r\n*[[Priest_Talents|Mental Agility]], [[Priest_Talents|Silent Resolve]], [[Priest_Talents|Spiritual Healing]], [[Spiritual_Guidance|Spiritual Guidance]]\r\n===Notes===\r\n*In order to be susceptible to a specific Renew rank, the target may not be more than 10 levels below the rank's level. There are a few high rank exceptions.\r\n===Description===\r\n*Spell description: \"''Heals the target of X damage over 15 sec.''\"\r\n*Buff description: \"''Healing X damage every 3 seconds.''\"\r\n===Improved Renew===\r\nPreviously there was a minor disadvantage to not taking this talent. Prior to the [[Patch_2.0.1_%28Release_Notes%29|2.0 patch]] WoW's [[Buff|buff]] system did not allow for multiple HoTs of the same spell from different players. Thus a spell such as Renew would overwrite a buff of the same spell if the spell being cast most recently was more powerful. Because of this, players who had not taken this talent were sometimes unable to refresh the duration of Renew as they could not overwrite the renew of a player who had taken Improved Renew. However as of the 2.0 patch, HoTs from different sources will now stack. For example, if two Priests each cast Renew on another player, the target will be healed by both Renews simultaneously regardless of the magnitude of either spell.",},
			["Renmar"] = { content = "Renmar is a human spellcaster. He is the brother of [[Talario]], and companion to [[Drann]].",},
			["Renn McGill"] = { content = "'''Renn McGill''' is a level 37 [[quest giver]] located in the ocean off [[Dreadmurk Shore]] at in the [[contested]] territory of [[Dustwallow Marsh]].\r\nHe is involved in the quests:\r\n# Renn McGill\r\n# Secondhand Diving Gear\r\n# Recover the Cargo!\r\n# Jaina Must Know\r\nSee [[List of Dustwallow Marsh NPCs]].",},
			["Renzik \"The Shiv\""] = { content = "'''Renzik \"The Shiv\"''' is a level 40 quest giver located in [[Old Town]] in the [[human]] city of [[Stormwind]].\r\nHe starts the quest Redridge Rendezvous.\r\nRenzik has connection both to the [[Hidden Circle]] in [[Ironforge]] as well as the [[rogue]]s in [[Darnassus]]. He is [[Mathias Shaw]]'s second in command.\r\nSee [[List of Stormwind NPCs]].",},
			["René Koiter"] = { content = "'''René Koiter''' is one of Blizzard's best and most influential artists.\r\n*Twin brother of [[Michel Koiter]]. Duo known as [[Twincruiser]].\r\n*Nowadays works as a web designer for Blizzard Entertainment & [[Sons of the Storm]]\r\n*Plays an [[Orc]] [[shaman]].",},
			["Rep"] = { content = "#REDIRECT [[Reputation]]", redirect = "Reputation",},
			["Repair"] = { content = "#REDIRECT [[Durability]]", redirect = "Durability",},
			["Repeatable Reputation Quest"] = { content = "#REDIRECT [[Repeatable reputation quest]]", redirect = "Repeatable reputation quest",},
			["Repeatable Reputation Quests"] = { content = "#redirect [[Repeatable reputation quest]]", redirect = "Repeatable reputation quest",},
			["Repentance"] = { content = "''\"Repent, sinners! Retribution is at hand!\"''\r\n==Notes==\r\nAs of Patch 3.0.2, this ability:\r\n*now affects Demons, Dragonkin, Giants and Undead - in addition to Humanoids\r\n*uses 9% Base mana\r\n*have 1 minute duration for PvE and 6 seconds for PvP\r\nThis is a second crowd control abilitfor Retribution Paladins (after [[Hammer of Justice]]), which is very useful in both PvP and PvE, as it allows two targets to be stunned/incapacitated at the same time (if the mob is not immune). However, note that damaging a target affected by Repentance will end the effect. It is useful in duels, to get a quick chance for a self-heal.\r\nThis talent is required for the [[Fanaticism]] talent.\r\n==Tips==\r\n*Warriors can use [[Berserker Rage]] to break out of Repentance.\r\n*Mages can not [[blink]] out of Repentance\r\n*With 1 minute duration and 1 minute cooldown, this talent has become a reliable crowd-control for PvE - particularly since it's instant-cast, and works with many races: Humanoids, Demons, Dragonkins, Giants, Undead.\r\nSee [[Paladin Talents]] for more details.",},
			["Report to Kadrak (Barrens)"] = { content = "Starts at [[The Crossroads]] from [[Thork]] and ends with [[Kadrak]] in the tower on the [[Ashenvale]] border.\r\n==Objectives==\r\nReport to [[Kadrak]] at the watch tower in northern [[Barrens]].\r\n==Description==\r\nHave you ever been to [[Ashenvale]], to the north? The horde has recently set up an outpost on the [[Zoram Strand]] there, and we can always use some new recruits to help defend our new fronts.\r\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.\r\n==Completion==\r\nAshenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called [[Splintertree]].\r\n==Rewards==\r\n* 15-150 [[XP]]\r\n==Quest Progression==\r\n# One of:\r\n#*Report to Kadrak (Barrens)\r\n#*Report to Kadrak (Stonetalon Mountains)\r\n# The Warsong Reports",},
			["Report To Scourge Commander Thalanor"] = { content = "==Objectives==\r\nReport to [[Scourge Commander Thalanor]] at the balcony on the first floor of [[Ebon Hold]].\r\n==Description==\r\nScourge Commander Thalanor awaits your arrive at the overhang located directly southeast of our current position. Report to Thalanor and requisition a [[Scourge Gryphon]] to deliver you to [[Death's Breach]].\r\n[[Prince Valanar]] will be waiting for you down below.\r\nSuffer well, <brother/sister>!\r\n==Completion==\r\nThe war has begun, [[death knight]]! I shall place you on my finest [[gryphon]] and deliver you to Death's Breach. Chaos, death, destruction! You will herald in all of this and more!",},
			["Reptilian warrior"] = { content = "A '''reptilian warrior''' with a shell reminiscent of a turtle's was an [[Ancient Guardian]] during the [[War of the Ancients]].",},
			["Reputation"] = { content = "You can gain or lose favor, otherwise known as '''Reputation''', with many of the several different factions in Azeroth by completing certain quests or killing certain creatures. Doing so will usually unlock special rewards or new quests to accomplish.\r\nYou can also increase your reputation by doing [[Repeatable Reputation Quest|repeatable reputation quest]]s.\r\n==Reputation levels and points==\r\nReputation is very similar to experience. Reputation is divided into a number of different levels for which players must earn reputation points to progress through. Higher reputation levels generally require more points than the previous level to progress. The exception is , which spans a very large number of reputation points. Reputation points, just like experience points, are gained through quests and killing various mobs. Unlike experience, it is possible to lose reputation points with some factions, either by killing members of the faction or by assisting rival factions. For rival factions, gaining reputation with one will normally decrease reputation with the other, but at a greater rate. For instance, if you kill a magram centaur, you will gain 20 points of reputation from the gelkis, but will lose 100 points from the magram. Currently there are 4 of these rival-faction pairs: [[Aldor]] (Draenei) vs. [[Scryers]] (Blood Elves), [[Gelkis]] vs. [[Magram]] (both Centaur), [[Steamwheedle Cartel]] (Goblins) vs. [[Bloodsail Buccaneers]] (pirates), and [[Ravenholdt]] (rogues) vs. [[Syndicate]] (Thugs).\r\nVarious quests and faction-specific rewards are available across the levels, but the player must be able to interact with the faction NPCs to gain access to these rewards. This usually requires or better standing. \r\n ''NOTE: All NPCs with whom you have Friendly or higher reputation will appear in game. The level colors above are only used in WoWWiki and in the [[Armory]].''\r\n==Reputation sheet==\r\nYou can check your reputation with all factions by pressing the \"u\" hotkey or by going to the Character window (\"c\" hotkey) and clicking on the Reputation tab along the bottom. You can also enable or disable various options:\r\n* '''Show as experience bar:''' Allows you to display one reputation bar as a experience bar on your main display.\r\n* '''[[At War]]:''' If checked, you can initiate combat with NPCs of that faction, and your AoE spells will affect the mobs of that faction. It's always checked if you are Hated or Hostile; it can't be checked for other races within the Alliance/Horde.\r\n* '''Inactive:''' Moves the selected faction to the bottom of the reputation pane.\r\n==Gaining and losing reputation==\r\nCompleting non-repeatable [[quests]] will usually increase your reputation with the quest giver's faction(s) by a fixed number of points. Most of the factions also have special repeatable quests that give reputation when completed, or special mobs that give reputation when killed.\r\nFull reputation is still gained by questing at a higher level. For example, completing low level quests with a level 70 character now gives full reputation. This makes it easier to get to exalted and buy another faction's mount.\r\nFor mob kills, as long as the mob cons green or higher to you, then you will receive full reputation. Grey mobs give 20% of the normal reputation. See the [[mob difficulty colors]] chart for when mobs transition from green to grey.\r\nMobs and quests sometimes both increase your reputation with a faction but decrease it with another. For example, killing [[Gelkis]] centaurs will increase your reputation with the [[Magram]], but it will also decrease your reputation with the [[Gelkis]]. Thus there is no way to be Friendly with the Gelkis and the Magram at the same time. It is possible to bypass this by grouping with someone and getting them to kill the relevant mobs, this will grant you the gained reputation, but you will not decrease with the faction you are killing.\r\nFor higher-end factions, a general strategy exists to make a reputation grind as painless as possible. Take the [[Argent Dawn]] for example. There are several ways in which to earn reputation for them: doing standard quests, killing mobs in and around [[Scholomance]] and [[Stratholme]], killing bosses, and doing repeatable quests. The problem is that each of these methods will only work to a certain extent. Killing standard mobs will usually only get you to Revered or so. After that, only quests and bosses will give reputation and these are of course harder to do. Therefore, it is in a player's best interest to go as far as possible on mob kills alone and then use repeatable quests and standard quests to get through revered. Example: for Argent Dawn reputation, run Scholomance and Stratholme to get reputation from kills until you reach Revered status. At this point, reputation gained from killing mobs will stop, but you should have built up quite a collection of Scourgestones and such to turn in in rapid succession to further boost your reputation. Similar tactics can be applied to other factions, simply varying the instances you run.\r\n==Gaining reputation with the Horde or Alliance factions==\r\nEvery playable race has a home faction, for example, Darnassus for Night Elves, Orgrimmar for Orcs, etc.\r\nExcluding the increased discount, gaining reputation with the faction of your own race is useless (although in [[Wrath of the Lich King]] it will count towards certain reputation [[achievements]]). However, if you want a mount of a faction that is not your own, you must be Exalted with that faction. For example, if you are a Troll and you want to buy a Wolf mount, you must be Exalted with Orgrimmar.\r\nOne method of gaining reputation with your faction is by donating Wool, Silk, Mageweave, or Runecloth through repeatable quests to designated NPCs.\r\nMost quests for an Alliance or Horde faction will give full reputation gain for that faction, and one quarter of that reputation gain for the other factions on that side. For example, a quest completed for a Stormwind NPC will give 250 Stormwind reputation and 62.5 reputation for the other Alliance factions.\r\nThere is no way to increase or even view your reputation with factions of the opposite team (ex: You cannot increase your Undercity reputation while playing an Alliance character).\r\n==List of factions and rewards==\r\nFor a list of recipes available grouped by tradeskill, see these pages:\r\nMost factions listed below have itemized lists of reputation rewards at their respective entries.\r\n==In Wrath of the Lich King==\r\n''See also [[championing]].''\r\nWe now know from the Beta that the reputations from Classic WoW and from Burning Crusade will not be re-used in the Wrath of the Lich King. In the same way that \r\n[[Cenarion Circle]] of Azeroth turned into [[Cenarion Expedition]] in Outlands, several old factions will have new reputations. For example, the [[Argent Dawn]] made its \r\nway to Northrend, but since it has allied with the Knights of the Silver Hand, they are called The [[Argent Crusade]].\r\nHowever, with the new achievement system many old reputations will receive new attention. Nearly all factions will have an achievement tied to them\r\n(excluding the not-in-use factions such as [[Ravenholdt]] and [[Shen%27dralar]]), and there are even additional achievements for pairs or groups of factions. For instance, \r\nacquiring Exalted with both [[Cenarion Circle]] and the [[Cenarion Expedition]] will get you the title of 'Guardian of Cenarius.' See [[Achievements]] for more details.\r\n:\r\n<div class=\"blizztext\">\r\n:While we haven't discussed reputation factions for Wrath of the Lich King, I can explain that from a design philosophy we prefer to NOT give players more experienced players a distinct advantage when it comes to new content. If you take The Burning Crusade as an example, there was no reputation that gave you an edge in Outland or would speed you further. Based on this example I wouldn't think the current Argent Dawn faction would be re-used for Northrend.\r\n</div>\r\n==See also==\r\n* [[Faction]]",},
			["Reputation achievements"] = { content = "This set of [[achievements]] includes attaining [[reputation]] with each [[faction]] in the game.\r\n__TOC__\r\n==[[Burning Crusade|The Burning Crusade]]==",},
			["Rerjik Mashnose"] = { content = "'''Rerjik Mashnose''' is a [[gnoll]] [[barbarian]], [[healer]], and [[shaman]].",},
			["Rescued Cenarion Expedition Druid"] = { content = "'''Rescued Cenarion Expedition Druid''' is a level 71 Friendly NPC that can be free'd from [[Ethereum Prison]]s. Each Prison has a chance to spawn a friendly NPC or a hostile NPC, for more information please see Ethereum Prison. Rescued Cenarion Expedition Druid grants 500 reputation toward the Cenarion Expedition to his or her rescuer. They appear in full tier 3 minus the helm.\r\nSaid upon release: ''At last I am released! Thank you gentle, <race>. I must return to the expedition at once! They will know of your deeds. This I vow.''",},
			["Reservoir Key"] = { content = "</noinclude>\r\n==Source==\r\nThis item is purchased from [[Fedryen Swiftspear]] in [[Zangarmarsh]]. You must be with the [[Cenarion Expedition]] to buy this item.",},
			["Resilient Sinew"] = { content = "==Source==\r\nThis item drops from:\r\n* [[Marauding Owlbeast]] in [[The Hinterlands]]\r\n* [[Frayfeather Hippogryph]] in [[Feralas]]\r\n* [[Frayfeather Skystormer]] in [[Feralas]]\r\n* [[Frayfeather Patriarch]] in [[Feralas]]\r\n* [[Antilus the Soarer]] in [[Feralas]]\r\n* [[Frayfeather Stagwing]] in [[Feralas]]\r\n* [[Vicious Owlbeast]] in [[The Hinterlands]]\r\n* [[Savage Owlbeast]] in [[The Hinterlands]]\r\n* [[Primitive Owlbeast]] in [[The Hinterlands]]\r\n==Resilient Sinew as a quest objective==\r\nThis item is an objective of Natural Materials.",},
			["Resist"] = { content = "'''Resist''' is when a [[player]], [[mob]] or [[NPC]] was not or only to a lesser extent affected by a [[spell]] or an [[elemental]] [[attack]]. ''Full resists'' completely negate the effect and have the same effect as ''[[Immune]]''. ''Partial resists'' only reduce the damage received by a percentage; these can only occur with non-binary spells.\r\nThere are two sources for spell resists. Firstly, the level difference between the caster and their target determines the [[Spell hit|spell hit chance]]. A spell which misses its target results in a full resist, whereas partial resists can not occur. [[Spell hit rating]] decreases the chance of getting a resist due to this difference. Secondly, [[Resistance]]s increase the chance to resist a spell. They can cause both full and partial resists, and can be overcome with [[spell penetration]] (and, limited to [[binary spell]]s, [[spell hit rating]]). A full resist due to level difference cannot be distinguished from a full resist due to resistances.\r\n==Notes==\r\nThere are also some negative spell hit effects in the game, such as the [[Balance of Power]] and [[Unbreakable Will]]. The former decreases the total spell hit chance of the attacker, whereas the latter only affects the spell hit chance of specific abilities.\r\nResists are the magical counterpart of ''[[Miss]]'', ''[[Dodge]]'', and ''[[Parry]]''. Even though the [[Attribute|Armor attribute]] and [[Defense]] [[Skill|skill]] generally affect the ability to mitigate physical damage, they are not considered resistances. However, there are some border cases; for example, the Hunter's [[Arcane Shot]] can be partially resisted, but a full resist is shown as a miss in the combat log.\r\n==See also==\r\n*[[Combat]]\r\n*[[Combat rating system]]",},
			["Resistance"] = { content = "== Miss Chance==\r\nWhen an offensive spell is cast, the target has two separate chances to resist the attack. \r\nFirst, there is a check based purely on <i>the level difference between the caster and the target</i>. This is referred to as the spell miss chance, and is affected by any Spell Hit Rating equipment that the caster is wearing. Talents that reduce the enemies' chances to resist spells, such as [[Arcane Focus]], are also taken into account by this check.\r\nIf the target is of a significantly higher level, the spell will usually fail completely. If the target is significantly lower level, the spell will very rarely fail. This first check is why spell-casting players have such a hard time landing spells consistently on all monsters a few levels higher. In PvP combat, however, this is less of a factor; a level 10 Mage can land polymorph on a level 70 player with some regularity.\r\nAlthough players can reduce their spell-miss chance with equipment or talents, it cannot be reduced to below 1%. What this means is that for a level 70 player in PvP, stacking Spell Hit Rating beyond a +3% \"to hit\" bonus doesn't help. In endgame raiding content, however, as much as +16% \"to hit\" bonus will help, since for these purposes, bosses are generally considered three levels over the player.\r\n<br style=\"clear:both;\">\r\n''Note'': Level-based resistance (not to be confused with level-based miss) can play a factor in total resists. For every level that a mob has over the player, there is 8 resist (believed; the exact number may be higher) added. For boss fights, this means there is 15-24 resistance added. This extra resistance means there will be partial resists on non-binary spells from the added resistance. However, this resistance has been shown to not apply to binary spells at all.\r\nThis level based resistance cannot be reduced by any means, not even Spell Penetration.\r\n==Magical Resistances==\r\nIn addition to the miss chance, there is a roll based on <i>the level of the caster and the resistance stat of the target</i>. As with [[Formulas:Damage_reduction|armor]], the level of the target is not a factor in this roll. \r\nAverage resistance may be no higher than 75%. Of course, what it takes to reach 75% average resistance depends on the spellcaster's level. One quirk here is that casters below level 20 are treated as if they were level 20 for purposes of calculating the resistance scaling here. So against a spellcaster of level 20 or below, it would take a resistance stat of 100 to get 75% resistance; level 30 would take 150 resistance; level 50 would take 250; level 60 would take 300; and level 63 would take 315.\r\nWhy is it called \"average resistance\"? For spells that have a non-damage effect&#151;such as slow, root, stun&#151;you'll either take the hit or avoid the hit altogether. The average resistance is the chance you'll totally avoid the hit. Adding the word \"average\" is a little redundant in this case. \r\nHowever, when spells do only damage, it's not just a full hit or full miss situation. Pure damage spells can be resisted for 0%, 25%, 50%, 75%, or 100% of their regular damage. Your average resistance can still be anywhere betweeen 0% and 75%. If your average resistance is maxed out, then there's a really good chance of having 75% of the spell's damage be resisted. There's also a fairly good chance of having 100% of the spell's damage be resisted, a slightly lower chance of 50% of its damage being resisted, a small chances of only 25%, or even 0% of the damage being resisted. It's a weighted average. Visualize it as a bell curve around your average resistance. \r\n<br style=\"clear:both;\">\r\n==Damage Absorbed==\r\nUnlike with armor, each extra point of magical resistance becomes more effective the more a character has. For example, going from 0 to 200 resistance halves the amount of damage a level 60 character takes, but to halve it again (to 25%) the character only needs 100 more resistance.\r\nSimilar to how [[Formulas:Damage_reduction|melee damage reduction]] works, it is possible to calculate how much magical damage a character can take with a certain amount of health.\r\nThis is the measure of how much damage a character can soak per point of health they have. Against a level 60 caster, a character with 200 resistance will resist 1000 damage for every 1000 damage they take, whereas with 240 resistance they will resist 1500 for every 1000 they take.\r\nSo for an example, if there are two mages in a fight against Ragnaros (boss level mobs are calculated as 3 levels higher then your current level), both with 3000 health, but one (Mage A) has just the 15 fire resist from mage armor, while the other (mage B) has 150 and is in a group with a paladin/shaman, so has an actual 210 resistance.\r\nMage A will resist, on average, 111 damage before his 3k HP are gone and he dies.\r\nMage B will resist, on average, 3000 damage before his 3k HP are gone and will likely have enough time to use a potion or something.\r\n<br style=\"clear:both;\">\r\n==See Also==\r\n* [[Spell hit]]\r\n* [[Resistance]]",},
			["Resistances"] = { content = "Were you looking for:\r\n* General information on [[Resistance]]s to [[Schools of Magic]]?\r\n&ndash; OR &ndash;\r\n* The [[hunter]]'s [[pet]] ability to increase their [[Resistances (Pet)|Resistances]]?",},
			["Resolute Cape"] = { content = "==Source==\r\nThis item is crafted by [[Tailoring|Tailors]] with a skill level of 365.\r\nThe components are:\r\n*10 Primal Mooncloth\r\n*12 Primal Earth\r\n*1 Primal Nether\r\nThe [[pattern]] is a random [[world drop]].",},
			["Resourcefulness"] = { content = "'''Resourcefulness''' is a 3 rank [[hunter talent]] starting at level 35 requiring 25 points in [[Survival]] talents. Part of the [[Physical]] school of abilities.\r\nReduces the mana cost of all traps and melee abilities by 20-60% and reduces the cooldown of all traps by 2-6 sec.",},
			["Resource node"] = { content = "'''Resources''' are a part of the game world that a [[Player]] character can [[Loot|loot]] by [[Gather|gathering]] or [[Harvest|harvesting]] for raw [[Ingredient|ingredient]] [[item|items]] usable by [[Professions|professions]] or items required by [[quest|quests]].\r\nExamples of resources:\r\n* [[Herb]] plants (gathered with [[Herbalism]]).\r\n* Mineral [[vein]]s or [[deposit]]s (gathered with [[Mining]]).\r\n* [[Skinnable]] corpses (gathered with [[Skinning]]).\r\n* Fish-able bodies of water (gathered with [[Fishing]]).\r\n* Fishing Pools and [[Schools of Fish]] in bodies of water (gathered with [[Fishing]]).\r\n* Quest based nodes (Gaea Seeds, Shellfish Traps, Incendia Agave Plants, etc.)",},
			["Respawn"] = { content = "#redirect [[Spawn]]", redirect = "Spawn",},
			["Respawn Time"] = { content = "A '''respawn time''' is simply the amount of time it takes for an [[NPC]] to be replaced after being killed. Different [[NPC|NPC's]] can have very different respawn times. While some [[NPC|NPC's]] such as factional guards and quest objectives have an extremely short respawn time, [[rare mob|rare mobs]] can take many hours before they appear again.\r\nIn zones or areas where there are expected to be a large number of players killing [[NPC|NPC's]] (such as [[Northshire Valley]] or the [[Valley of Trials]], the enemies will typically have an extremely short respawn time.\r\nIn larger [[raid dungeon|raid dungeons]] the [[NPC|NPC's]] will typically be on a one week respawn time. This is a measure taken by [[Blizzard]] to prevent high-level players from repeatedly [[farming]] the [[raid dungeon|dungeons]]. This does not apply to normal instances.\r\n*Note: while [[looting]] and [[skinning]] corpses can in some cases cause the body to disappear faster, there is no evidence that these actions actually make the [[NPC]] respawn faster.\r\n*Note: bosses in instances do not respawn at all because killing them without their guards would not be enough of a challenge.",},
			["Ressan the Needler"] = { content = "'''Ressan the Needler''' is a level 11 [[rare mob]] [[bat]] found roaming a small area in [[Nightmare Vale]] in [[Tirisfal Glades]]. It is white with pink wings, and is popular because of these unusual colors. Only one other bat — the [[Blind Hunter]] — shares this color, and it is located at the end of [[Razorfen Kraul]] and is a [[rare mob]]. Ressan is on a 1.5-2.5 hour respawn timer.",},
			["Rest"] = { content = "'''Rest''' is a device that allows more casual gamers to stay somewhat on par with other players, as to character [[level]]. It's also a clever device to encourage less-active players to keep their accounts, making players want to come back and play some more after some time away from the game. Rest also adds more value to the subscription fee. In light of the controversy of game addiction, rest also gives players reason to cease play. Blizzard has also indirectly stated that World of Warcraft play should be taken in moderation according to [[Loading Screen Tips|loading screen tips]].\r\n==Storing up rest==\r\nWhile in an [[inn]] or anywhere in a [[capital]] [[city]], your player portrait will begin to glow and your level circle will say <span style=\"color: #999933;\">''zzz''</span>, indicating that you are resting. If you log off here, you will continue to rest while offline. \r\nOne bar of rested [[XP]] (5% of a level) is earned for every 8 hours spent resting. A maximum of 30 bars (150% of a level) may be earned. In other words, you can leave your character resting in an inn or capital city for up to 10 days (without gaining experience) before you earn the maximum amount of rest state, and a resting character stores up one full level of rest in 160 hours (6.67 days).\r\nYou also become rested while logged off in the wilderness, but the accumulation is slower. When logged off \"outside,\" rest is gained at one fourth the rate in an inn, or one bar every 32 hours.\r\nIt may also be possible to engage the [[resting]] state while in [[ghost form]], or [[dead]].\r\n==Consuming rest==\r\nWhen rested, your XP bar will turn <span style=\"color:#6cc;\">blue</span>, and a notch will appear indicating exactly how rested you are. You will earn double XP from killing monsters while rested until your XP bar fills to the notch. A rested character earns double combat XP until this rest state is consumed, at which point the message\r\n<span style=\"color:#ff33cc;\">You feel normal.</span>\r\nappears and you resume normal XP gains for kills.\r\nNOTE: Your rested state marker-notch can go off the right side of your XP bar such that you won't see it until you gain at least one level.\r\nWhen you are rested, when you kill a monster, in the combat log it may say something like \r\n<span style=\"color:#3399ff;\">120 XP (+60 rested XP).</span>\r\nIn this case, you did not get 180 XP. Your total experience was 120, half of which was a rested bonus. Unrested, that kill would have yielded 60 XP.\r\nA note on consuming rested XP: Let's say you had 5000 rested XP. You get 120 XP for killing a mob. You now have 4880 rested XP left, not 4940. That extra XP that you got \"(+60 rested XP)\" was not the only XP pulled from your rested XP pool.\r\nNon-combat experience such as exploration and quest experience does not consume rest state. The rest marker will be moved forward by as many XP as you gain from the exploration or quest.\r\n==Further information==\r\nWhen you are about 5th or 6th level, you will receive quests to go to another town area. This town is where the first inn is available to a new character. Put another way, until you get your first 5 or 6 levels out of the way you will not happen across an inn and so you will have to 'camp out' when you logout, accumulating rest at the slower \"wilderness\" rate. It is easy enough to get these first five levels, so it is good to finish those quests and hurry over to the inn.\r\nAt this inn, and at all other inns that you find, you will find an [[innkeeper]], who can bind your [[hearthstone]] to that inn. Activating your hearthstone you will move your character to that bound inn. This is useful for rapid or unexpected logout situations; you can activate your hearthstone and log out at the inn, gaining rest.\r\nSince rest XP is based on percentage, higher level characters will receive higher absolute rest xp. So the higher your level, the better rest is for you.\r\nBy having at least two characters, you can rest on one while playing the other! This is one pro of having alts.\r\nAlso see:\r\n* [[Hearthstone]]\r\n* at the .",},
			["Restalaan"] = { content = "'''Restalaan''' was a long-time friend and second-in-command of the Prophet [[Velen]] who escaped with him and other eredar refugees - known henceforth as the [[draenei]] - from [[Sargeras]]' corruption of [[Argus]]. When the draenei settled on [[Outland|Draenor]], Restalaan became the captain of the guard in the city of [[Telmor]]. During a routine patrol, he and his men saved two future [[orc]] chieftains - [[Durotan]] of the [[Frostwolf Clan]] and [[Orgrim Doomhammer|Orgrim]] of the [[Blackrock Clan]] - from an [[ogre]] attack, and brought them to Telmor, revealing the hidden defenses of the city using a shard of the [[ata'mal crystal]] and a phrase in his native tongue.\r\nWhen the orcs began making war on the draenei, Durotan, now chieftain of the Frostwolves, met Restalaan and his men in battle. Restalaan defeated him, but spared his life because of an earlier incident in which Durotan spared and released Velen (on his way to [[Oshu'gun]]) from his custody. Later, Durotan - having remembered the incantation used to lower the invisibility shield that protected Telmor - was tasked by Warchief [[Blackhand]] to assault the city, as it was close to Frostwolf territory. Locating the crystal and speaking the words Restalaan had used, Durotan revealed the city for the orc invasion force, which proceeded to sack the city. With the city being torn apart around them, the two met again in combat, holding nothing back. In the end, Durotan defeated and killed Restalaan - a deed that, along with the events that were soon to follow, would be a heavy burden on Durotan's conscience for the remainder of his life.\r\nRestalaan was succeeded as Velen's lieutenant by [[Larohir]].",},
			["Rested"] = { content = "#redirect [[rest]]", redirect = "rest",},
			["Restless Shade"] = { content = "'''Restless Shades''' are the [[shade]]s of former people living in the small settlement below [[Karazhan]] in [[Deadwind Pass]]. They are level 68-69 and also inhabit [[the Master's Cellar]] below the village.",},
			["Restless Skeleton"] = { content = "'''Restless Skeleton''' can be found in [[Karazhan]].",},
			["Restoration"] = { content = "'''Restoration''' may refer to:\r\n* [[Druid|Restoration]], a [[druid]] [[specialization]].\r\n* [[Shaman|Restoration]], a [[shaman]] specialization.\r\n*[[Restoration (quest)]], a [[garrison]] quest in .\r\n* [[Restoration (pet battle ability)]], a [[Pet Battle]] ability.",},
			["Restoration tree"] = { content = "#REDIRECT [[Restoration]]", redirect = "Restoration",},
			["Restorative Potion"] = { content = "==Source==\r\nThis item is a quest reward from the following quests:\r\n* Uldaman Reagent Run (Alliance)\r\n* Uldaman Reagent Run (Horde)",},
			["Resurrect"] = { content = "To '''Resurrect''' is to bring a [[dead]] character back to life.\r\nAny player may resurrect ''themselves'' by running back to their corpse as a [[ghost]]. Or, they may have a [[Spirit Healer]] do this at a [[graveyard]] for a penalty of increased [[durability]] loss and [[resurrection sickness]]. See [[Death]] for more information. \r\nSeveral [[class]]es also have spells that can resurrect themselves or other player characters. Classes who can resurrect are highly sought after in groups. This is especially true for [[instances]] where [[mob|mobs]] may respawn if too much time is wasted. \r\n==Classes Capable of Resurrecting == \r\n* [[Druid]]: [[Rebirth]]. The Druid has the only [[in combat]] resurrection spell, but this spell is not capable of resurrecting an entire party due to the long [[cooldown]] time on this spell.\r\n* [[Druid]]: [[Revive]]. Added [[patch 3.0.2]]\r\n* [[Paladin]]: [[Redemption]]\r\n* [[Priest]]: [[Resurrection]]\r\n* [[Shaman]]: [[Ancestral Spirit (Shaman Spell)|Ancestral Spirit]]\r\n* [[Death Knight]]: [[Raise Dead]]\r\n* Any [[Class]] with [[Engineering]]: [[Goblin Jumper Cables]] and [[Goblin Jumper Cables XL]]. These may fail though.\r\n==Classes Capable of Resurrecting After Death==\r\n* [[Warlock]]: [[Create Soulstone]]. The warlock can indirectly resurrect a unit after death.\r\n* [[Shaman]] : [[Reincarnation]]. The shaman is the only class capable of solo [[wipe recovery]], but this skill has a cooldown of 60 minutes, reducible to 40 by talents.\r\n* Any [[class]] with [[Darkmoon Card: Twisting Nether]].\r\n==Resurrection Timer==\r\nAfter dying there is a time in which you can not return to your body, this is known as the Resurrection Timer. This timer increases with each death to a maximum of 2 minutes.",},
			["Resurrecting class"] = { content = "Any class that has an ability to resurrect a dead player can be considered a Resurrecting Class.\r\n==Classes==\r\nThere are 5 [[classes]] that can resurrect a dead player [[Paladins]], [[Priests]], [[Shamans]], [[Warlocks]], and [[Druids]].\r\n===Paladins===\r\nPaladins gain their resurrection spell [[Redemption]] from their level 12 paladin quest. Redemption can only be used out of combat and has a 10 second cast.\r\n===Priests===\r\nPriests gain the [[Resurrection]] spell at level 10 from a priest trainer and it is almost identical to the paladin resurrection spell.\r\n===Shamans===\r\nShamans have two forms of resurrection, [[Ancestral Spirit]] which is gained at level 12 and it works just like the redemption or resurrection but shamans have the ability to revive themselves with [[Reincarnation]].\r\n====Reincarnation====\r\nShamans have the ability to resurrect themselves without the aid of any other players with this ability that can only be used once per hour.\r\n===Warlocks===\r\nWarlocks can put cast their spell [[Create Soulstone]] to create a [[soulstone]] which can store a soul inside it allowing them to revive themselves.\r\n====Soulstones====\r\nThese can be placed on any party member by a warlock every 30 minutes giving that player the choice to resurrect themselves instead of releasing to the nearest graveyard.\r\n===Druids===\r\nDruids have [[rebirth]], a resurrection spell that is different from all others because it can be cast while still in combat with a 2 second cast and using a [[reagent]], but with a 30 minute cooldown time sometimes it can be difficult to know when to use it and who to use it on.\r\n===Other Resurrection===\r\n*Classes with [[Pets]] can revive their own pets but nothing else\r\n**[[Hunters]] can revive their fallen pets with [[Revive pet]]\r\n**Warlocks can summon a new minion when theirs dies\r\n*Any class with the [[Engineering]] [[Profession]] can attempt to resurrect with their trinkets.",},
			["Resurrection"] = { content = "'''Resurrection''' is the resurrection spell of the [[priest]] class. You must cast this spell out of combat, and you'll probably have to heal and buff the target once they revive. Also, the target will be revived to where the spell is cast, not where their corpse is or where you are after you cast it.\r\nOther [[Class|classes]] have similar spells but usually with slightly different requirements and effects:\r\n* [[Druid]]: [[Rebirth]]\r\n* [[Paladin]]: [[Redemption]]\r\n* [[Shaman]]: [[Ancestral Spirit (Shaman Spell)|Ancestral Spirit]]\r\n==Functionality==\r\nBrings a dead allied player back to life. This spell cannot be cast while the priest is flagged as being in combat.\r\nNote that there is no way to know if a corpse belongs to the priest's faction or not except by inspecting it visually. If the corpse ''does'' belong to the priest's faction, it is possible to tell whether the player is still online or not by typing \"/who playername.\" A response of \"0 players found\" indicates that the player has logged off (or is of the wrong faction). A response giving the target's race, level, and class indicates that the player is still online and can be successfully resurrected. Note that landing a resurrection on an offline or cross-faction player's corpses is indistinguishable from landing one on an online player's corpse who simply declines the resurrection. In both cases, the mana is wasted. Note that if the dead character is flagged for PvP (also impossible to determine visually), then the priest will also become flagged.\r\nThere are some common misconceptions involving Resurrection and releasing. Players can be resurrected whether or not they release. If the player has not released, the priest resurrecting can select the body and cast the spell. If they have released, the priest must click the spell and mouse over the corpse since the corpse is not selectable. There are reasons not to release however. If a player releases, they will not see loot on mobs killed while the player is dead. Players who release do not receive credit if a required quest event happens while the player is dead. Players being resurrected will come back at the feet of the priest (or paladin with Redemption) performing the resurrection not at the site of the corpse. Players dead while a kill is made receive reputation but *not* experience (if eligible for experience).",},
			["Resurrection Sickness"] = { content = "#redirect [[Resurrection sickness]]", redirect = "Resurrection sickness",},
			["Retaliation"] = { content = "''Don't think of it as retaliation. Think of it as instant punishment.''\r\n'''Retaliation''' is a warrior ability, trained at level 20 for 36 silver . For a short time, any frontal attacks will be met with a vicious counterattack. Its obviousness, however, makes it easy to counter.\r\n==Functionality==\r\nRetaliation is a self-buff that costs no [[Rage]]. It has a 5 minute cooldown, which is linked to the [[Shield Wall]] and [[Recklessness]] timers. While it is active, the first 20 melee attacks taken from the front will result in an instant counterattack with your weapon. It has a very obvious animation making it nearly useless in PvP as players will simply stop attacking the warrior when they see the spinning blades clearly indicating that it is active. It has limited usefulness in PvE but being on the same timer as [[Shield Wall]] and [[Recklessness]] means that the warrior should carefully consider using it.\r\nAvailable in [[Battle Stance]] only.\r\n==Tips and Tactics==\r\n*Before the implementation of its animation this was one of your most powerful abilities, now it is at best of marginal utility in PvE. The counterattacks from Retaliation are not instant attacks, they are normal swings. Because of this, Retaliation is most powerful when used with an extremely slow two-handed weapon.\r\n*Although it has a cap on how many counterattacks you can make, it is higher than your average [[mob]] will trigger in a fight. So, this skill is best used against multiple enemies, particularly if they attack quickly.\r\n*Remember retaliation is linked to the 30 minute timers of the more useful [[Shield Wall]] and [[Recklessness]] abilities, so only use if you are certain that you will not need to use the latter in the next 5 minutes.",},
			["Retch!"] = { content = "''Braaaaaaaains!''",},
			["Retcon"] = { content = "A '''retcon''' (short for '''retroactive continuity''') is a retroactive expansion or alteration in the official [[lore]] of a series of works of fiction. These changes can either be:\r\n*Additional backstory to explain and expand upon present circumstances.\r\nOR\r\n*Historical facts which are rewritten and are meant to be taken as having always been that way.\r\nA large portion of the lore of the [[Warcraft universe]] would fall under the first meaning, since it was all developed around a relatively simple war between orcs and humans. This article deals with the second meaning of ''retcon'', a retroactive change in the history or backstory.\r\nSome apparently conflicting lore is actually written as [[flavor lore]], and was not necessarily intended to be accurate observations of what actually occurred, but rather competing beliefs held by inhabitants of the world of Azeroth. An example of this is the [[tauren]] belief that they were the first [[druid]]s, which was definitely stated to be false in the [[Warcraft Encyclopedia]].\r\n==Metzen on continuity==\r\n[[Chris Metzen]] has emphasized the importance of ensuring continuity within the Warcraft universe:\r\n''We're taking the process of building a world seriously and it wasn't just churned out. It had a strong sense of continuity. We've always tried to do that with our ancillary products like the [[Warcraft RPG|D&D line]] and our [[novels]]. We are kind of painstakingly anal, about making sure all the details add up, that continuity is held to be sacred. So that no matter in what medium you are experiencing Warcraft it all feels like a contiguous experience.\r\nHe has also said that the novels are pretty much considered canon, though some things are less canon:\r\n''...yeah, the novels are pretty much considered canon, ahm, the funny thing is that some things are less canon, you know, but we shoot for canon... that's a strange statement... <small>we shoot for canon...</small> but yeah, typically the characters in novels are canon.'' - Chris Metzen\r\nMetzen also said that Blizzard wants to integrate every source as much as possible with each other to get a good continuity:\r\n''A lot of times... depending on when one thing gets started during another, we happen to be in the middle or the game, or doing the [[manga]] thing for instance or this [[World of Warcraft: The Comic|comic series]] specifically, we try to engineer as much inner play as possible. Like characters in the manga series showing up in [[Netherstorm]] and we are doing stuff like that, so we want to make everything feels as continuity friendly and as integrated as possible. Cuz that would make it cool as if all its moving, right.'' - Chris Metzen\r\n==Retcon speculation==\r\nThe [[Retcon speculation]] article lists discrepancies in the [[Warcraft universe]].\r\nIt is left to the reader's opinion whether the discrepancies listed in the article constitute errors, retcons, flavor lore, or merely artistic license. The criteria for inclusion in the article is a clear, apparent contradiction between two official sources. Where the sources are reconciled by another official source, that explanation is provided.",},
			["Retcon 2"] = { content = "#REDIRECT [[Retcon speculation]]", redirect = "Retcon speculation",},
			["Retcon speculation"] = { content = "It is left to the reader's opinion whether the discrepancies listed below constitute errors, '''retcons''', [[flavor lore]], or merely artistic license. The criteria for inclusion in this article is a clear, apparent contradiction between two official sources. Where the sources are reconciled by another official source, that explanation is provided. More retcon speculation can be found at [[Retcon 2]].\r\n===Black Temple/Fortress Shadowmoon===\r\nThe Black Temple dungeon trailer claims that the Draenei Temple of [[Karabor]] was captured by orcs for a time before it became the sinister fortress of [[Magtheridon]]. This suggests that the Shadowmoon Fortress assaulted in WarCraft II was in fact another name for this structure. Although this would imply that Alliance didn´t manage to destroy Fortress Shadowmoon and Warcraft II's story was ignored or retconned.\r\n''For full analysis see: [[Black Citadel and Temple]]''.\r\n===Cenarius' mother===\r\nThe [[War of the Ancients Trilogy]] describes [[Ysera]] as the mother of [[Cenarius]], while other sources in the World of Warcraft, such as [[tauren mythology]], suggest that [[Elune]] was his mother. This was later explained by the author of the trilogy, [[Richard A. Knaak]]:\r\n''[[Elune]] birthed Cenarius, but gave him up to [[Malorne]] because Cenarius was more a creature of the mortal world and could not be with her. Malorne, who had relations with both Elune and [[Ysera]], knew that he could not properly care for his son, but Ysera's love was so great for Malorne that she took Cenarius as her own. Hence being his mother (or adoptive mother).\r\n — [[Blizzard_lore_posts|Source]]\r\nMore recent sources appear to have established that Ysera was in fact ''not'' involved romantically with Malorne, and that rumors of the relationship were mortal interpretations of Cenarius's relationships with his father, Malorne, and teacher, Ysera.\r\n===Dark Portal appearance change explain/theory===\r\nIn [[Warcraft: Orcs & Humans]], the [[Dark Portal]] was a stone arch, and a minor lore footnote (like most things back then). It could be explained through graphic limitations.\r\nIn Warcraft II, the dark portal was shown to be a much more decorated arch with a ring of obsidian stones around it. It was shown to be like this on both sides and described as such in older texts. The [[Azeroth]] side is confirmed to have looked like this in current lore, as the [[Caverns of Time]] version keeps this look.\r\nThe Warcraft II Azeroth side portal was destroyed by the humans, and then rebuilt by [[Ner'zhul]]. In Warcraft IIx, it keeps the look from before, but it can be explained again through graphic reuse. It is at this point that the Dark Portal gets its new look.\r\nThe \"new look\" is first seen in the Warcraft IIIx Interlude: [[The Dusts of Outland]] where Kael remembers that the [[Dimensional gateway]]s Ner'zhul opened looked like this, or on the cover of [[The Last Guardian]] which takes place oddly in the First War.\r\nIn World of Warcraft, the new look is shown in the [[Blasted Lands]] with little change. Come [[The Burning Crusade]], the [[Stair of Destiny]] is shown as a more extreme version of the new look. All lore still fits.\r\nIn [[Rise of the Horde]], Medivh gives Gul'dan a vision on how to make the dark portal look, he did this before in the WCII manual lore, but this time he shows the Stair of Destiny as it is now. Gul’dan does not know who or what the figures are (they are mentioned only as \"cowled figures\",) and called the dragon a lizard (this ties in with the [[Dragonmaw Clan]] retcon confusion). The dragon may be Deathwing in honor of his alliance with Ner’zhul (if Ner’zhul did in fact rebuild the Stair of Destiny like that), but has no armor.\r\n===The draenei===\r\nIn the ''[[Warcraft III]]'' and ''[[World of Warcraft]]'' game manuals, the [[draenei]] are described as a pacifistic race of shamans, native to [[Draenor]], who were easily slaughtered by the orcs prior to the opening of the [[Dark Portal]]. In ''The Burning Crusade'', however, the draenei are in fact an offshoot of the eredar race, native to the planet [[Argus]]. These eredar fled Argus at the beginning of the Burning Crusade and exiled themselves on Draenor some twenty-five thousand years before the time period of the Warcraft games, during which time the Burning Legion hunted unceasingly for them. Upon their discovery, and the unleashing of the orcish [[Horde (pre-Thrall)|Horde]] upon them, the Draenei, using the powers of the [[Holy Light]], fought for eight years against the orcs before being defeated.\r\nThe draenei playable race in the expansion is a previously-unseen refugee group of uncorrupted eredar who fled Draenor. The draenei that were previously seen in ''Warcraft III'' and ''World of Warcraft'' are explained as a subspecies, including the [[Broken]] and the [[Lost Ones]], who had been mutated by [[fel]] energies.\r\n===Garona's parentage===\r\nIn the ''[[Warcraft: Orcs & Humans]]'' manual and ''[[The Last Guardian]]'', [[Garona]] describes herself as being half orc and half human. In the novel ''[[The Last Guardian]]'', she states that orcs see only \"her human parts\", while [[Medivh]] speculates that her homeworld must have had \"humans or near humans\".\r\n[[Blizzard]] Community Manager [[Caydiem]] stated on the official World of Warcraft forums that Garona is half orc and half [[draenei]] (another is [[Lantresor of the Blade]]). This has not yet been confirmed however.\r\nHorde Player's Guide, 2006, mentions that she is not [[half-draenei]], and that if her other half is not human, it is something unknown. The book implies that actual half-draenei show draenei physical traits.\r\n===The Holy Light===\r\nIn the description of [[Stormwind Army of the First War|Warcraft I units]], the [[Clerics of Northshire]] are described as worshippers of [[God]]. This is followed in some of the later sources, such as Warcraft II and Day of the Dragon. By the time of Warcraft III they are shown as followers of the [[Holy Light]], which is described as a non-theistic philosophy, although a reference to a single all powerful god-like being creating the universe is mentioned. This creation myth is also mentioned in the in-game book, [[Mythology of the Titans]]. It is possible that the Clerics & some Knights of the Silver Hand, being originally unaware of the [[Naaru|power behind the Light]], found their basis of this \"God\" from this [[creation myth]] of Azeroth.\r\nFor more info, see [[Retcon speculation]].\r\n===Magtheridon's death===\r\nThe death of [[Magtheridon]] has been revised in the [[Burning Crusade]], though he was defeated. He is now imprisoned within [[Hellfire Citadel]] and you can visit him in the [[Magtheridon's Lair]] instance.\r\n===Maiev's death===\r\nAccording to a mission objective in The Frozen Throne a player had to slay [[Maiev Shadowsong|Maiev]] and the other guardians guarding Illidan's cage to progress in the mission (soon after she is resurrected by an invincible altar on the map). This was adapted into several of the books for the [[Warcraft RPG]] where it said Maiev Shadowsong had died (see ''[[Alliance & Horde Compendium]]'' page 9, ''[[Shadows & Light]]'' page 51 and ''[[Alliance Player's Guide]]'' page 68). Here's the corresponding quote from ''Shadows & Light'':\r\n''Sinking into vengeful madness, Maiev pursued Illidan all the way to Outland. Emotion clouded her vision, and Illidan slipped away from her several times. Finally, when Maiev was all but blinded by frustration and vengeance, the Betrayer got the better of her. Maiev died alone on the red sand, unmourned, unsung, with none to remember her fall, her soul empty of all but rage.''\r\nSince Maiev is confirmed to be Illidan's prisoner in the [[Warden's Cage]], without the use of altar (in TFT) to explain her resurrection this would either have to be flavor lore or a retcon.\r\n===Rend and Maim===\r\n[[Rend Blackhand|Rend]] and [[Maim Blackhand|Maim]], the sons of [[Blackhand]] the Destroyer, led the [[Blacktooth Grin]] clan during the [[Second War]], which was a clan that was almost destroyed at the end of the war, after their defeat they run away, set up a base in Blackrock Spire and formed the [[Dark Horde]]. They next appeared without mention during the [[Curse of the Blood Elves|Alliance campaign]] of [[Warcraft III: The Frozen Throne]], in the service of [[Magtheridon]], inexplicably on [[Draenor]], ''See: [[Rend (fel orc)]] and [[Maim (fel orc)]]''. [[Horde Player's Guide]] mentions rumors that they went through the [[Dark Portal]] back to Draenor and that Maim was killed by the [[human]]s. However in [[World of Warcraft]] Rend appears in a prominent role as head of the [[Blackrock Clan|Blackrock]] clan on [[Azeroth]], and Maim is stated to be killed by the [[Dark Iron Dwarf|Dark Iron Dwarves]] in [[Azeroth]].\r\n===Sargeras and the eredar===\r\nIn the ''[[Warcraft III]]'' and ''[[World of Warcraft]]'' game manuals (and in [[Sargeras and the Betrayal]] from the [[History of Warcraft]]), the [[eredar]] are described as being a demonic and evil race that had consumed their own world through arcane powers, and had already destroyed countless other worlds by the time [[Sargeras]] discovered them. It was not until after Sargeras destroyed them that he himself became corrupted, and the [[Burning Legion]] was born. \r\nIn''[[The Burning Crusade]]'', however, the Burning Legion had already begun under Sargeras' leadership when he encountered the eredar, who became corrupt through his influence. Furthermore, a faction of the eredar did not join the Burning Legion, instead became followers of the Holy Light, and renamed themselves [[Draenei]].\r\nPresumably, either another demonic race (such as the pit lords) take the place of the eredar in the role of corrupting Sargeras, or it is left completely up to the dreadlords. Blizzard has not released any official information on the matter.\r\nChris Metzen admitted the contradiction was a mistake in a [[Metzen on Lore|forum post]], but it has become the current story.\r\n===Stormwind and Azeroth===\r\nThe human kingdom in the southern [[Eastern Kingdoms]] was referred to as ''Azeroth'' from ''Warcraft I'' to ''Warcraft III''. In ''[[World of Warcraft]]'', the name ''Stormwind'' is used for the kingdom, even in historical contexts, without any mention of its former name. The ''[[Alliance Player's Guide]]'' uses the name ''Azeroth'' for the kingdom in a historical context, and ''Stormwind'' for the modern kingdom.\r\n===''Warcraft I'' and ''II''===\r\n''[[Warcraft I]]'' featured two separate storylines. While there were some interweaving events, most were stand alone, which lead to some contradictory elements. Some elements from each storyline were taken and included in the backstory for the next game in the series. In contrast ''[[Warcraft II]]'' evolved with two campaign stories that wove together in a tighter way, with references to missions from one campaign being mentioned in the events of the other campaign, although ending missions lead to alternate endings. The expansion was unique however in that it was a completely linear story; it set the Alliance campaign after the Orc campaign chronologically (though one could play the campaigns in any order). In contrast, ''[[Warcraft III]]'' featured campaigns with story lines which formed a single linear narrative that had to be unlocked as you beat each campaign.\r\n====''Warcraft I''====\r\n''Warcraft I'' featured many levels which are best described as generic battles with some interweaving plot elements, and contradictory endings.\r\nNote: That no later source has given any detailed analysis of all the events of the First War. Not all the battles or locations have been referenced in later sources. As such skirmishes and events surrounding said locations is up in the air. Some of these locations include [[Grand Hamlet]], [[Sunnyglade]], [[Kyross]], and [[Rockard]]. The history of defense, rebuilding and destruction surrounding these locations is unknown as they have never been mentioned again in later sources.\r\nWhile the orc campaign ending most closely matches the outcome of the First War as portrayed in later games, both [[Battles of the First War|campaigns]] and the manual for the game contained important plot points that became part of the lore:\r\n*The [[History of the Horde|Orcish Horde]] did come from [[Draenor]], their planet that they had just finished conquering (orc campaign).\r\n*The Orcish Horde was repelled the first time they tried to attack [[Stormwind Keep]] (human campaign).\r\n*[[Stormwind Keep]], [[Northshire Abbey]], and all the human towns of the kingdom, including [[Goldshire]], [[Moonbrook]] were destroyed (orc campaign). [[Grand Hamlet]] and [[Sunnyglade]] are not mentioned in later sources, but it can be assumed they were destroyed as well.\r\n*[[Blackhand]] was overthrown as [[warchief|War Chief]] (orc campaign).\r\n*[[Medivh]] was killed in his tower by a raiding party (human campaign).\r\n*King [[Llane]] was assassinated by [[Garona]] (human campaign).\r\n*[[Lothar]] was rescued from a 20-month imprisonment after obtaining the [[Tome of Divinity]] in the [[Deadmines]] (human campaign). Mentioned in [[Alliance Player's Guide]].\r\n*Blackhand's daughter [[Griselda]] was killed in the Deadmines (orc campaign). Griselda is confirmed in [[Rise of the Horde]].\r\n*The Orcish Horde did win the [[First War]] (orc campaign).\r\n*[[Medivh]] did win his battle against his mother [[Aegwynn]] (manual).\r\nSome elements of the game's plotlines were expressly left out of the ultimate account of the war:\r\n*[[Aegwynn]] did not first come to the court of [[Wrynn III]], instead she first came to the court of [[Landen Wrynn]] (human campaign). Confirmed in [[Cycle of Hatred]].\r\n*The [[Swamp of Sorrows]] was not located in the southern part of the [[Black Morass]], instead it was located in the northepart of the Black Morass (orc campaign). According to [[World of Warcraft]] map.\r\n*[[Medivh]] was not in a coma for six years, instead he was in coma just twenty years (manual).\r\n*The [[Dark Portal]] was not located in the Swamp of Sorrows, instead it was located in the southern part of the Black Morass (human campaign). According to [[World of Warcraft]] map.\r\n*Medivh did not \"accidentally\" open the Dark Portal, instead he did it on purpose (manual).\r\n*King [[Llane]] was not killed at the fall of [[Stormwind]] by the [[Orgrim Doomhammer|Orc War Chief]] (orc campaign, manual). Instead he was killed by [[Garona]].\r\n*The humans did not succeed in destroying [[Blackrock Spire]] (human campaign). As this fortress was mantained in orcish hands until the [[Assault on Blackrock Spire]] this cannot have happened.\r\n*The commander of the human armies did not succeed Llane as king after destroying Blackrock Spire (human campaign). As the Horde win the First War this cannot have happened.\r\n*[[Garona]] did not aid [[Orgrim Doomhammer]] with new and powerful magiks (orc campaign). Instead Dommhammer tortured her to get the information of the Shadow Council.\r\n*Orgrim Doomhammer did not have the backing of the [[Shadow Council]] (orc campaign). Instead he discovered it's location and destroyed them.\r\n*The [[Shadow Council]] did not survive the [[First War]] (orc campaign).\r\n*Blackhand was not assassinated by the Shadow Council (orc campaign). Instead he was killed by Orgrim Doomhammer.\r\n*The Humans did not win the First War (human campaign). In [[Alliance Player's Guide]], [[Brann]] tells that the [[high elf|high elves]] offered little support to the [[kingdom of Azeroth]] during the [[First War]], but when the humans were '''defeated''' the [[dwarf|dwarves]] sent emissaries to meet the high elves to discuss about the threatening Horde.\r\n*The Humans did not successfully defend [[Stormwind Keep]], [[Northshire Abbey]], and all the human towns of the kingdom, including [[Goldshire]], [[Moonbrook]], [[Sunnyglade]], and [[Grand Hamlet]], were destroyed (human campaign). Grand Hamlet and Sunnyglade are not mentioned in later sources it can be assumed they were destroyed, Northshire Abbey did not survive, Stormwind Keep fell, Goldshire and Moonbrook were likely destroyed as they were between Stormwind Keep and the Horde offensive.\r\n*The Orcish Horde was not an independent force, instead they were being secretly manipulated by [[Medivh]]/[[Sargeras]] with the promise of giving to [[Gul'dan]] access to the powers in the [[Tomb of Sargeras]] (human campaign).\r\n*The Shadow Council's leader was not nameless, instead [[Gul'dan]] was their leader (orc campaign).\r\n*[[Blackhand the Destroyer]] was not the highest leader of the Orcish Horde, instead it was Gul'dan (orc campaign).\r\n*Blackhand the Destroyer did not survive the whole of the First War, instead he was killed by Orgrim Doomhammer sometime during the events of the First War (human campaign).\r\nOther events are indeterminate, not conflicting with any other accounts, but also not being referred to again:\r\n*Existed a land being called the [[Borderlands]].\r\n*The [[Orcs_%26_Humans_missions|destruction of a Blackhand's key Orcish]] outpost in the Black Morass by Orgrim Doomhammer (orc campaign).\r\n*The destruction of the orc outpost of [[Kyross]] in the Swamp of Sorrows (human campaign).\r\n*The destruction of the [[Temple of the Damned]] in the Black Morass (human campaign).\r\n*The destruction of [[Rockard]] and [[Stonard]] (human campaign).\r\n*The attack of [[Northshire Abbey]] by a band of warriors that had been convinced by enemy agents to fight against the crown (human campaign). As the mission ends with the destruction of the human revels it can be assumed they were all killed and that's why they aren't present in the [[Second War]]; also it can be assumed this mission didn't happen.\r\n*[[Turok]]'s death (orc campaign).\r\n*The rebuilding of [[Sunnyglade]], and/or later destruction (human campaign).\r\n====''Warcraft II''====\r\nHowever, ''Warcraft II'' featured [[Battles of the Second War|two interweaving campaigns]] with two separate and alternate endings. The true ending was found in the [[Alliance of Lordaeron|Alliance]] campaign, with the nearly complete defeat of the [[Horde (pre-Thrall)|Horde]] in the [[Eastern Kingdoms]]. The expansion took it further by making the campaigns linear, with Horde campaign taking place entirely before the Alliance campaign: \r\n*The [[high elf|high elves]] joined the Alliance following an attack on their archers passing through [[Tarren Mill]] (human campaign).\r\n*The Horde was driven from the [[Hillsbrad]] region and [[Khaz Modan]]\r\n*The nation of [[Alterac]] betrayed the Alliance of Lordaeron and was destroyed (human campaign).\r\n*The [[Runestone|Runestone at Caer Darrow]] was captured by the Horde and used to create the [[Ogre Mage|ogre magi]] (orc campaign).\r\n*[[Gul'dan]] betrayed [[Orgrim Doomhammer]] and withdrew his forces in order to seek out the [[Tomb of Sargeras]] (orc campaign).\r\n*Dalaran was razed by the Horde (orc campaign).\r\n*The Alliance forces defeated the Horde at [[Blackrock Spire]], then recaptured and attempted to destroy the [[Dark Portal]] (human campaign).\r\n*[[Lothar]] is betrayed, ambushed and killed by the [[Horde]] when invited to [[Blackrock Spire]] for a diplomatic parley. Others say Lothar died in single combat against Doomhammer during the [[assault on Blackrock Spire]]. Although, Alliance Player's Guide 2006, still mentions that ambush still occurred and hints that foul play was involved, and the single combat wasn't as honorable as perceived (more than one against him). Horde Player's Guide explains further that witnesses and historians give mixed accounts which include elements of both versions of the event\r\n*After having been defeated by [[Doomhammer]]'s forces at the [[Tomb of Sargeras]] in ''Warcraft II'' (orc campaign), Gul'dan is attacked by demons after he opens the Tomb (as forshadowed during a cutscene at the beginning of the act). In ''The Frozen Throne'', it further shows that he was killed by the demons he unwittingly set free while searching the tomb.\r\n*[[Quel'Thalas]] razed by the Horde (orc campaign). While it did not completely fall, much of Quel'Thalas was destroyed by dragons during the second war (and ravaged by the undead in the third), forming the [[Blackened Woods]] (later known by is alternate nickname, Ghostlands).\r\n*[[Dun Algaz]] razed by the Alliance (Human campaign). Hinted at in Lands of Conflict that it was important in the Second War and left a derelict after.\r\nEvents which occurred in one of the Warcraft II campaigns, but which did not ultimately form part of the lore, include:\r\n*[[Lordaeron]] did not fall to the Horde (orc campaign ending).\r\n*[[Stromgarde]] did not fall to the Horde (orc campaign).\r\n*[[Grim Batol]] did not fall to the Alliance (Human campaign).\r\n \r\nOther events are indeterminate, not conflicting with any other accounts, but also not being referred to again:\r\n*The razing of Stratholme and Tyr's Hand by the Horde.\r\nDeathwing: see [[Deathwing timeline issue]] for details.",},
			["Rethban Caverns"] = { content = "The '''Rethban Caverns''' is an extensive series of caves that extend deep into the northwestern [[Redridge Mountains]]. Adventurers sometimes visit the caverns in search of [[Rethban Ore]], which can be found in the possession of the local gnolls, led by the cunning [[Ardo Dirtpaw]].",},
			["Rethban Ore"] = { content = "'''Rethban Ore''' is a [[quest]] [[item]] used in the Alliance quest Rethban Ore, and is technically speaking not really an [[ingredient]].\r\nThis item is found in a series of caves north-west of [[Lakeshire]] in the [[Redridge Mountains]] called the [[Rethban Caverns]]. These caves are currently infested by gnolls who are mining the ore. Rethban Ore is named after [[Bart Rethban]], who found it. The ore is not as strong as [[iron]], but is used by some scribes in their dyes, as it doesn't run or smear and dries very quickly.",},
			["Retherokk the Berserker"] = { content = "'''Retherokk the Berserker''' is a level 48 [[rare mob]] [[forest troll]] found near the [[Altar of Zul]] in the [[Hinterlands]].\r\nHe was notable as the only non-[[elite]] forest troll that gave more than 1 or 2 [[reputation]] with the [[Wildhammer Clan]] at level 60.",},
			["Rethiel the Greenwarden"] = { content = "'''Rethiel the Greenwarden''' is a level 30 [[quest giver]] located behind a hill in [[the Green Belt]], in the [[Alliance]]-aligned territory of the [[Wetlands]].\r\nHe starts the following quests:\r\n* Tramping Paws\r\n* Fire Taboo\r\n* Blisters on The Land\r\nSee [[List of Wetlands NPCs]].",},
			["Rethilgore"] = { content = "'''Rethilgore''' <The Cell Keeper> is a level 20 [[elite]] [[worgen]] found in [[Shadowfang Keep]].\r\nRethilgore is the first [[mini-boss]] that players will encounter in [[Shadowfang Keep]]. He guards the cells of both [[Deathstalker Adamant]] and [[Sorcerer Ashcrombe]] which players will need to progress further into the keep.\r\n==Strategy==\r\nRethilgore is not very hard to kill. He does 54-62 physical damage in melee, mitigated by armor. He will cast Soul Drain, which immobilizes a player for 10 seconds and drains 35 health, healing himself with it. Easiest way to beat him is to just bring him down with attacks and spells. Look out for worgs and wolves around him. They are weak so kill them quickly and finish Rethilgore.",},
			["Rethress Sanctum"] = { content = "'''Rethress Sanctum''' is a ruined shrine located in [[the Ruined Reaches]], southwest of the [[Ravencrest Monument]]. It is currently uninhabited, visited only by stray [[murloc]]s and [[makrura]].",},
			["Retribution"] = { content = "#REDIRECT [[Paladin]]", redirect = "Paladin",},
			["Retribution Aura"] = { content = "''Retribution looms for those beyond redemption.''\r\n'''Retribution Aura''' is an instant cast aura that surrounds the paladin. If an enemy hits the paladin or a party member that is within 30 yards of the paladin, the attacker will take Holy damage. Like a group version of [[Thorns]].\r\n==Rank table==\r\n==Talent Improvements==\r\n*[[Improved Retribution Aura]] (2 Ranks) will improve the damage done by the aura by 25/50%\r\n*Retribution Aura is not affected by +spell damage.\r\n*[[Aura Mastery]] will extend the radius of all the Paladin's auras to 40 yards.\r\n==Tips & Tricks==\r\n*Retribution Aura best suits tanks, as it is a permanent costless source of threat. As it works \"on-hit\", it is especially suitable for multi-mob scenarios, as they will hit a lot for (usually) little damage per hit. In this case, it synergizes well with [[Holy Shield]] and [[Blessing of Sanctuary]].\r\n*When there's only a single paladin in a 5-man group or the tanks group in raid, this aura is best for a group that can take a few hits. For the non-tanks group in raid, Devotion Aura is more useful.\r\n*Since there is no resistance to Holy damage, the paladin's enemies will always take full damage (unless they resist it by the base miss chance).\r\n*Damage is not increased if the attacker is under [[Judgement of the Crusader]]. However, it does benefit from a possible party [[Sanctity Aura]]. (The same restrictions apply for Blessing of Sanctuary.)\r\n==Related Equipment==\r\n*The Protection-centric [[Tier 5]] Paladin Armor Set, [[Crystalforge Armor]] has a 2-piece set bonus that increases all damage done by Retribution Aura by 15.",},
			["Retribution guide"] = { content = "#REDIRECT [[Damage shield]]", redirect = "Damage shield",},
			["Return to Bodley"] = { content = "==Pre-Requisites==\r\nMust complete the quest [[Quest:Mea Culpa, Lord Valthalak|Mea Culpa, Lord Valthalak]]\r\n==Task==\r\n'''Return to [[Bodley]] inside [[Blackrock Mountain]] and give him the [[Brazier of Beckoning]].'''\r\n''I will ignore your impertinence this time, <class>, because you have done a noble thing today; returning the rest of my stolen spirit to me. Despite your obviously weak nature, <race>, you have shown courage where those that stole from me did not, and probably never could!''\r\n''Return to them, before I change my mind and slay you where you stand. Go back and tell them that they are safe... for now.''\r\n==Reward==\r\n*[[Brazier of Invocation]]\r\n*[[Brazier of Invocation: User's Manual]]\r\n==Quest Chain==\r\n*[[Quest:Bodley's Unfortunate Fate|Bodley's Unfortunate Fate]]: [[Quest:Bodley's Unfortunate Fate (Alliance)|Alliance]]/[[Quest:Bodley's Unfortunate Fate (Horde)|Horde]]\r\n**[[Quest:Three Kings of Flame|Three Kings of Flame]]\r\n**[[Quest:Components of Importance|Components of Importance]]: [[Quest:Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Left Piece of Lord Valthalak's Amulet|The Left Piece of Lord Valthalak's Amulet]]: [[Quest:The Left Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:I See Alcaz Island In Your Future...|I See Alcaz Island In Your Future...]]\r\n**[[Quest:More Components of Importance|More Components of Importance]]: [[Quest:More Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:More Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:More Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:More Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Right Piece of Lord Valthalak's Amulet|The Right Piece of Lord Valthalak's Amulet]]: [[Quest:The Right Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:Final Preparations|Final Preparations]]\r\n**[[Quest:Mea Culpa, Lord Valthalak|Mea Culpa, Lord Valthalak]]\r\n***'''Return to Bodley'''\r\n***[[Quest:Back to the Beginning|Back to the Beginning]]: [[Quest:Back to the Beginning (Alliance)|Alliance]]/[[Quest:Back to the Beginning (Horde)|Horde]]\r\n***[[Quest:Saving the Best for Last|Saving the Best for Last]]: [[Quest:Saving the Best for Last (Alliance)|Alliance]]/[[Quest:Saving the Best for Last (Horde)|Horde]]\r\n==Notes==\r\n*This is the tenth step in the quest chain to upgrade your [[Dungeon Set 1]] Helm and Chestpiece into [[Dungeon Set 2]].\r\n----\r\nGo to [[Quests]]",},
			["Return to Jaina (BC Classic)"] = { content = "==Objectives==\r\nSpeak with [[Lady Jaina Proudmoore]] in [[Theramore]].\r\n==Description==\r\nDo not let [[Lady Katrana Prestor|Lady Prestor]]'s protestations distract you, <name>. That she is blind to this problem does not surprise me, but that is a separate matter.\r\nAs I was saying, you and Lady Jaina have my thanks for bringing your findings to me in such haste. Let her know that no good citizen of [[Stormwind]] will rest until our [[Varian Wrynn|king]] walks among us again.\r\nGo to the [[Mage Quarter]] at the western end of the city and speak with [[Archmage Malin]] at the foot of the tower there. He will speed your return to Theramore.\r\n==Interaction with Archmage Malin==\r\n Can you send me to Theramore? I have an urgent message for Lady Jaina from Highlord Bolvar.\r\n''You are teleported back to Lady Jaina's presence in Theramore.''\r\n==Completion==\r\nThat is excellent news, <name>! I was worried the [[Highlord Bolvar Fordragon|highlord]] might question the veracity of our information, but I see now my concern was misplaced.\r\nYou are to be well rewarded for your efforts on behalf of [[Theramore]] and the [[Alliance]].\r\n==Rewards==\r\nYou will also receive: 80 silver and 4600 [[XP]]\r\n==Notes==\r\nSpeak to [[Archmage Malin]] in the [[Mage Quarter]] to get a free teleport back to Jaina!",},
			["Return to Kristoff"] = { content = "Return to Kristoff is the 5th quest in the '''Speaking of Fortitude''' quest chain.\r\n==Objectives==\r\nReturn to Brother Kristoff in the Cathedral Square. Give him the book The Stresses of Iron.\r\n* Book: Stresses of Iron (Provided)\r\n==Description==\r\nNow that I've finished copying the book, here's the original Stresses of Iron. Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay.\r\n==Progress==\r\nWere you able to find the book?\r\n==Completion==\r\nThat's the one! Thank you, <name>. May the Light shine brightly upon both your body and spirit!\r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*1950 [[XP]] (or s=12 gold at level 70)\r\n*250 with [[Stormwind]]\r\n==Quest chain== \r\n*Speaking of Fortitude\r\n**Brother Paxton\r\n**Ink Supplies\r\n**Rethban Ore\r\n***Return to Kristoff\r\n==Notes == \r\nThis Quests ends the chain;",},
			["Return to Primal Torntusk"] = { content = "==Objectives==\r\n[[Elder Torntusk]] at [[Jintha'alor]] wants you to return to [[Primal Torntusk]] at [[Revantusk Village]] with news of his rescue. \r\n==Description==\r\nReturn to my mate, [[Primal Torntusk]] at [[Revantusk Village]]. Tell her that I am coming home! She is sure to reward you. \r\n==Completion==\r\nYou have done the [[Revantusk]] a great service, <name>! We owe you a great debt of gratitude. \r\n==Rewards==\r\nYou will also receive: 2 gold 25 silver copper \r\n==Gains==\r\n*7050 [[XP]]",},
			["Return to Tinkee"] = { content = "==Objectives==\r\nBring Felnok's Package to Tinkee Steamboil in the Burning Steppes.\r\n*icon= (Provided)\r\n==Description==\r\nOk, everything is prepared and packed and ready for transport! Good luck in your journey, and make sure you tell Tinkee that she owes me!\r\n==Progress==\r\n<name>! Did you talk to Felnok? Did you bring the components I need?\r\n==Completion==\r\nYou brought them! Great! I'll get to work right away! Thanks a ton, <name>!\r\nYou've been so helpful to me, I might need you for even more important tasks later...\r\n==Notes==\r\nOpens up Egg Freezing.",},
			["Revantusk"] = { content = "#REDIRECT [[Revantusk tribe]]", redirect = "Revantusk tribe",},
			["Revantusk Tribe"] = { content = "#REDIRECT [[Revantusk tribe]]", redirect = "Revantusk tribe",},
			["Revantusk Trolls"] = { content = "#REDIRECT [[Revantusk tribe]]", redirect = "Revantusk tribe",},
			["Revantusk Village"] = { content = "'''Revantusk Village''' is the only visitable settlement of the [[Revantusk Tribe|Revantusk Trolls]]. You can find the village at the coast in the [[The Hinterlands]]. Before patch 1.11, you could get quests there which increased your [[reputation]] with the Revantusk Troll faction. \r\nNow it is just a Horde settlement.\r\n===Flight===\r\n [[Undercity]]\r\n [[Tarren Mill]]\r\n [[Hammerfall]]\r\n [[Light's Hope Chapel]]\r\n==Revantusk Village NPCs==\r\n* [[Katoom the Angler]]\r\n* [[Lard]]\r\n* [[Mystic Yayo'jin]]\r\n* [[Primal Torntusk]]\r\n* [[Smith Slagtree]]\r\n* [[Huntsman Markhor]]\r\n* [[Otho Moji'ko]]\r\n==Quest Guide==\r\nSnapjaws, Mon! and Gammerita, Mon!, both given by [[Katoom the Angler]], can be completed in one pass, right outside of the village to the north. Northeast of there is a little island where you can find [[Lard's Lunch]] for Lard Lost His Lunch.\r\nDark Vessels, Kidnapped Elder Torntusk!, Separation Anxiety, Job Opening: Guard Captain of Revantusk Village, and Wanted: Vile Priestess Hexx and Her Minions are all done at [[Jintha'Alor]].\r\n===Quests===\r\n* Stalking the Stalkers\r\n* Hunt the Savages\r\n* Avenging the Fallen\r\n* Message to the Wildhammer\r\n** Another Message to the Wildhammer\r\n*** The Final Message to the Wildhammer\r\n* Cannibalistic Cousins\r\n* Vilebranch Hooligans\r\n* Gammerita, Mon!\r\n* Lard Lost His Lunch\r\n* Snapjaws, Mon!\r\n* Dark Vessels\r\n* Separation Anxiety\r\n* Kidnapped Elder Torntusk!\r\n** Recover the Key!\r\n*** Return to Primal Torntusk\r\n* Job Opening: Guard Captain of Revantusk Village\r\n* Wanted: Vile Priestess Hexx and Her Minions",},
			["Revelosh"] = { content = "'''Revelosh''' is a level 40 [[elite]] [[trogg]] found in the Hall of the Keepers in [[Uldaman]].\r\nHe carries [[The Shaft of Tsol]], half of the [[Staff of Prehistoria]] needed to summon [[Ironaya]]. The other half, the [[Gni'kiv Medallion]], is in [[Baelog's Chest]].",},
			["Revenant"] = { content = "'''Revenants''' are armored [[elemental]] creatures. They look similar to floating suits of crude armor. They also wield large maces and carry giant shields. The most notable revenant was [[the Guardian]], protector of [[Frostmourne]]. Some are soldiers of the [[Old God]]s in the [[Elemental Plane]].\r\n==In World of Warcraft==\r\nRevenants appear in several different zones of [[Northrend]], such as the [[Dragonblight]] and [[Zul'Drak]].\r\n* [[Earth revenant]] \r\n* [[Fire revenant]] \r\n* [[Air revenant]] \r\n* [[Water revenant]] \r\nNote that there are more types, but there are only four models. Classifications such as ''all'' blue earth revenants being ice or frost (and which is which) is partly speculation. Death revenants seem to be clearly separate, despite using the model of air revenants.\r\n* [[Ice revenant]]",},
			["Revenant of Burning Souls"] = { content = "The '''Revenant of Burning Souls''' was the undead leader of an abandoned temple called the [[Magistrate's Temple]] outside of [[Vol'jin]]'s new base camp. [[Rexxar]], [[Rokhan]], [[Cairne Bloodhoof]] and [[Chen Stormstout]] put this spirit to rest. It wore the Necklace of Burning Souls, a powerful artifact.\r\n==Statistics of <font color=\"olivedrab\">'''Revenant of Burning Souls'''</font> from Warcraft III==\r\n* 4000 HP <font color=\"limegreen\"> (+119% more than a regular Deeplord Revenant)</font>\r\n* 1000 MP <font color=\"limegreen\">(+100% more than a regular Deeplord Revenant)</font>\r\n* 203-260 chaos melee damage <font color=\"limegreen\">(+217% more than a regular Deeplord Revenant)</font>\r\n* 15 heavy armor <font color=\"limegreen\">(+650% more than a regular Deeplord Revenant) </font>\r\n* Abilities\r\n** Bash (sometimes stuns target)\r\nNote:''The Revenant of Burning Souls is being compared to the Deeplord Revenant which is the most powerful non-unique type of revenant.''",},
			["Revenge"] = { content = "''\"Revenge is a dish best served cold...\"''\r\n'''Revenge''' is a low/moderate damage [[warrior]] counterattack skill (thanks to the new patch improving Revenge's damage). It is mainly used for tanking due to its high [[threat]] generation. It is only usable immediately after [[block]]ing, [[Dodge|dodging]], or [[parry]]ing an attack.\r\nRevenge costs 5 [[Warrior|Rage]], giving it the same cost, but less damage per rage, as [[Overpower]]. Unlike Overpower, Revenge may be [[Block|blocked]], [[Dodge|dodged]], or [[Parry|parried]]. Unfortunately, this skill is not based on weapon damage. It should also be noted that it shares the same [[Cooldown]] as Overpower.\r\n==Tips and Tactics==\r\n*This ability is often the best way to hold a [[mob]]'s attention at the beginning stages of a fight due to its very high [[threat]]-per-[[Rage]] ratio (which becomes even better with 3/3 [[Focused Rage]]). [[Sunder Armor]] or [[Devastate]] are available on command and can be spammed (given sufficient Rage, of course), and [[Shield Slam]] still generates more threat per application, but smart tanking warriors will still use Revenge at almost every opportunity.\r\n*[[Shield Block]] is a popular way to enable Revenge by getting a near-guaranteed block within a few seconds (generally much less).\r\n*Revenge may seem similar the Battle Stance ability [[Overpower]] in that it is a situationally reactive skill, but there are important differences to be aware of. First, revenge is available after '''your warrior''' blocks, dodges, or parries; Overpower only after '''your target''' dodges. Second, revenge is a flat amount of damage, ignoring weapon damage. Third, the [[Improved Revenge]] talent gives you a chance to stun the target, whereas [[Improved Overpower]] increases critical hit percentage.\r\n*Note that you don't necessarily need to Revenge the mob that you blocked/parried/dodged: once Revenge is lit up you can use it on any target until the timer expires. This can be a very Rage-efficient way of building threat on multiple mobs over a short period of time: if multiple mobs are targetting you, there is a high likelihood that Revenge will become available regularly, particularly if your [[Defense]] skill, [[dodge]] rating, [[parry]] rating, and/or shield [[block]] percentage are high.\r\n*Higher ranks of the skill generate bonus threat in addition to causing more damage.\r\n*With 3/3 [[Improved Revenge]], this ability can be an important alternate spell interrupt while tanking or in PvP. Although [[Shield Bash]] and [[Pummel]] are superior in almost every way, they have a relatively long cooldown in comparison with their effect duration, only work on one school of magic, and cause relatively small amounts of damage. Although there is only about a base 50% chance of a stun occurring with a fully-talented Revenge and it is subject to [[diminishing returns]], this is still far better than the alternative of allowing an enemy caster to complete a spell because the other options are on cooldown and/or in a different stance. Further, although Revenge requires Defensive Stance, it does not require a shield equipped, giving it more flexibility in some situations. (Although this is hardly an excuse for doing large amounts of PvP as a Protection-spec Warrior, it does give some additional utility to those who wish to occasionally PvP but not enough to justify the cost of multiple [[respec]]s.)\r\n== Patch changes==\r\nIn [[Patch 2.3]], according to the last set of patch notes, the stun effect of revenge was made subject to diminishing returns. Each time it used, the time the stun lasts will be half of the previous time. While this is intended for PvP, some have seen it in PvE (which might be a bug).",},
			["Revered"] = { content = "#REDIRECT [[Reputation]]", redirect = "Reputation",},
			["Revive"] = { content = "'''Revive''' is the new [[druid]] ability that allows them to revive a fallen ally with no reagent cost or cooldown, but only while out of combat.",},
			["Reward"] = { content = "One or more [[Item|items]], [[Ability|abilities]], [[Spell|spells]], or [[Money|money]] given by a [[Quest|quest]] giver [[NPC]] for completing a quest. All quests tend to include [[XP]] as part of the reward.\r\nAdditional notes:\r\n* At lower levels, most rewards are items and/or money.\r\n* Sometimes a reward or part of the reward is another quest.\r\n* Some quests allow you to choose among reward items.\r\n* Most reward items will be bind on pickup, also known as [[Soulbound]].\r\n* The completion of quests will also impact your reputation with particular factions, which can have further beneficial effects such as cheaper prices at vendors and access to special vendors such as mounts.\r\n* Some reward items may not be usable by your character (based on [[class]] usually).\r\n*At level 70 all quest rewards are money, based on [[XP]] usually gained from the quest",},
			["Rexxar"] = { content = "'''Rexxar''' the [[half-ogre]] is known as the last son of the [[Mok'Nathal]]. He is the [[Champion of the Horde]]. He is a half-ogre, half-orc [[beastmaster]] of the [[Mok'Nathal Clan]], and may be one of the last half-ogres of the clan. He saved the city of [[Orgrimmar]] from the hatred of an enemy of the Horde. He was instrumental in assisting the [[Horde]] after the fall of the [[Burning Legion]]. Due to his mixed lineage, he is a huge and fierce warrior, and wields two huge axes. Rexxar is always seen with his loyal bear companion [[Misha]].\r\nPrior to [[World of Warcraft: The Burning Crusade|the ''Burning Crusade'' expansion]], the warrior wandered a path from the [[Charred Vale]] in [[Stonetalon Mountains]], along the main road through [[Desolace]], continuing to [[the Twin Colossals]] in northern [[Feralas]]. Currently he can be found in [[Thunderlord Stronghold]] in the [[Blade's Edge Mountains]] of [[Outland]], protecting the settlement against ogres and [[gronn]], and trying to find more of his people.\r\n===The Orcish Wars===\r\nRexxar was one of the few orcish warriors who had been formed of a union with [[orcs]] and [[ogres]]. Rexxar was originally part of the pacifist Mok'Nathal tribe, based on Draenor in the [[Blade's Edge Mountains]], under the watchful guard of his father, [[Leoroxx]]. But their pacifist ways gave him no reason to stay, and despite his father's wishes, he joined the Horde and left through the [[Dark Portal]]. The Beastmaster was accompanied by a large black wolf, [[Haratha]], his loyal companion.\r\nAfter the Horde's defeat in the [[Second War]], Rexxar briefly returned to Draenor. When Ner'zhul launched his own invasion of Azeroth to retireve certain artifacts, Rexxar was stationed with [[Grom Hellscream]] and the [[Warsong Clan]] on the Azerothian side of the Dark Portal. He remained in Horde's service until just after the destruction of Draenor and the second destruction of the Dark Portal. Rexxar grew sickened by the senseless killing that the orcish race seemed to favor, and particularly the constant betrayals — first by [[Gul'dan]] and then by [[Ner'zhul]]. His resolve was further weakened when Haratha was drained of its life essences by a orcish warlock when he lept in between them to save his master. He slew the warlock but had lost his companion. He declared that he would only trust beasts from thereon out, and left the Horde to wander the world on which he was now stranded.\r\nThrough his journeys in the wilderness, he came to befriend an bear named Misha, who would come whenever summoned by Rexxar. Together, they traveled to [[Kalimdor]], where they roamed the [[Barrens]] away from civilization. But his journeys had seen nothing but wars amongst the so-called \"civilized\" creatures.\r\n===Founding of Durotar and the new Horde===\r\nUpon one of his journeys, however, he encountered [[Mogrin]], an orc warrior who came under attack by a group of [[quilboar]]s. Rexxar tried to help the orc, but the quilboars struck a fatal blow, and the warrior fell. In his last wish, Mogrin asked Rexxar to deliver a message to [[Thrall]], the orc [[Warchief]], in the city of [[Orgrimmar]], to keep Mogrin's death an honourable one. Rexxar agreed, and made the journey to Orgrimmar.\r\nWhen he arrived, he found Thrall and delivered the message, and Thrall invited him to stay a while, saying that this land was as much Rexxar's as it was his own. But, insisting to earn his keep, Rexxar volunteered to help out around the city. He visited [[Drek'Thar]], [[Nazgrel]], and [[Gazlowe]], who commissioned him to retrieve [[Shimmerweed]] from [[Thunder Ridge]], kill the [[harpy]] queen [[Bloodfeather]], and collapse the [[Kobold Mining Column]]s, respectively. He also received the help of [[Rokhan]].\r\nHe also encountered on his journeys a jovial Brewmaster of Pandaria called [[Chen Stormstout]] and killed a powerful [[kobold]] named [[Noggrin Onetooth]]. He helped an orc [[shaman]] named [[Morg Wolfsong]] regain his honor by killing the [[orc]] [[warlock]]s who had killed his party. \r\nAfter he had helped out Thrall's friends, Rexxar was sent to [[Gar'thok]]'s outpost, where the orc surveyed the coast for activity. Rexxar fought his way to the observatory nearby and found a suspicious amount of human activity along the coast. Rexxar reported his findings to Thrall, who sent Nazgrel to go with Rexxar back to Gar'thok's outpost. \r\nRexxar made a short detour to meet Drek'Thar at Thunder Ridge, where the Farseer found the thunder lizards driven mad. Upon further investigation, they found a [[human]] lumber mill, where many trees had been harvested. Rexxar was ready to destroy the mill, but Drek'Thar forbade it, citing a non-aggression treaty with the humans. Rexxar was forced to put the maddened thunder lizards down before they caused more harm.\r\nUpon arrival at Gar'thok's outpost, Nazgrel and Rexxar found it razed by the humans, and so followed the trail of blood back to a human camp at the coast. Immediately hostile, Rexxar threw all treaties aside and destroyed the camp, then returned to report to Thrall.\r\nThrall was amazed at the audacity of these humans, and questioned [[Jaina]]'s involvement. Rokhan was worried, however, that the humans may strike at the [[Echo Isles]], where his people had settled. Rexxar, Rokhan, and their allies traveled by [[zeppelin]] to the Echo Isles, where they found that the [[Darkspear]] tribe had already come under attack. \r\nTheir leader, [[Vol'jin]], briefly transformed Rexxar, Chen, and Rokhan into [[spirit wyvern]]s so that they could assist the [[Troll batrider|batriders]] in destroying the [[battleships]] assaulting the coastal villages. Upon return, Vol'jin sent Rexxar to light signal pyres telling the trolls to head for the mainland. These were guarded by the lord of the [[sea giant]]s known as the [[Sea King]].\r\nRexxar returned to Thrall, where the Warchief had received summons to a peace summit with Jaina, but Rexxar didn't trust the humans, and volunteered to go in his place. When he arrived at the summit, he found an ambush waiting, and no Jaina.\r\nThrall suspected that deceit was afoot, and prepared a letter for Jaina in the hopes of mending the problem, and sent Rexxar to meet with her on [[Theramore]] Island. Rexxar and his party asked [[Samuro]], a blademaster to plant explosives to distract the guards on the [[human]] coastal settlement on [[Dustwallow Marsh]] long enough for Rexxar to slip by. Samuro took this opportunity to eliminate an enraged [[wildkin]] named [[Bloodbeak]] who was hiding nearby. Rexxar then met with Jaina, who denied any knowledge of this force, and condemned any attack on Thrall. She demanded to see these soldiers for herself. \r\nRexxar brought Jaina back to the camp, only to find it destroyed by the [[naga]]. Rexxar and Jaina fought through the force of snake-people, looking for any survivors. After finally defeating the naga led by the [[naga]] [[sea witch]] [[Lady Darkscale]] and her guard [[Scilla Murkshadow]], they found a single human footman, dying, who said that the \"Admiral\" would be pleased to see Jaina all right.\r\nRexxar was confused at Jaina's horror, but trusted her enough to follow her back to Theramore quickly. Upon arriving, however, a fleet of ships arrived, and Jaina's father, [[Daelin Proudmoore]], arrived. The moment he saw Rexxar, he immediately ordered his capture, despite Jaina's pleas. Rexxar and his friends fled the city, fighting through the naval guards, and returned to the Darkspear village, informing Vol'jin what had passed.\r\nRexxar's forces fought around the [[Vol'jin]]'s village to gain experience for the coming battle. He entered the [[Tomb of the Ancients]] and killed the dungeon master [[Lord Talendar]]. Across the ocean's shallows he fell the [[Eldritch Deathlord]]. In the [[Magistrate's Temple]] the ghost lord named the [[Revenant of Burning Souls]] was laid to rest. In the [[Den of the Lost]] an [[Ancient Wendigo]] reign was finished over his icy cavern. Notable stations of [[human]] naval guards were led by grand wizard [[Zerx Hydromon]] and naval royal guard [[Thornby]]. Rexxar's forces entered the [[Outland Arena]] and fought three powerful [[demon]] lords named [[Destroyer Zardikar]], [[Sinstralis of the Pain]] and [[Talnivarr the Sleeper]] to get the tomes they held. He released the [[orc]] [[Mathogg]] from a prison after killing [[Khan Gragtor]] and getting his iron key.\r\nVol'jin made it out to inform Thrall of the imminent invasion, and suggested that Rexxar go and enlist the aid of the [[tauren]] tribes along the mesas of the land of [[Mulgore]] to aid them in the coming battle. Rexxar traveled to [[Mulgore]] to meet with [[Cairne Bloodhoof]], and when he arrived Cairne told him to return to Thrall and tell him that he had died. His second, [[Tagar]], explained that Cairne's son, [[Baine Bloodhoof]], had been kidnapped by [[centaur]], and that Cairne had since grown depressed and lethargic. Rexxar led an expedition to rescue [[Baine Bloodhoof]] with the help of the [[tauren]] spirit walker leader [[Bovan Windtotem]]. Upon returning, Cairne was re-energized, and agreed to pledge his people to the Horde, and to personally return with Rexxar.\r\nWhen they returned to the Darkspear village, Vol'jin showed them a tired ogre, who had come from [[Dustwallow]] with news that a new warlord had taken over the [[Stonemaul]] clan of ogres, and that his cruelty and brutality were leading the ogres to ruin. Vol'jin and Rexxar agreed that this was an excellent opportunity to sway the ogres onto their side. Rexxar traveled to Dustwallow and found the Stonemaul clan. Though they initially rejected Rexxar because of his mixed blood, he proved himself by running a gauntlet and returning alive. The warlord [[Kor'gall]] was impressed and allowed Rexxar to join the clan.\r\nRexxar used his new position to ask the ogres for assistance. [[Kor'gall]] mockingly reminded him that they were no longer friends to the orcs. Rexxar was forced to fight Kor'gall for leadership of the clan. Kor'gall proved to be a powerful foe, and Rexxar had to rely heavily on his beast friends to defeat him. But finally, Kor'gall fell, and Rexxar assumed the position of chieftain. He then led the Stonemaul ogres back to [[Tidefury Cove]], where Thrall was assembling the Horde. Thrall named Rexxar champion of the Horde, and gave him the honour of leading the Horde against Proudmoore's forces. After a difficult battle, they razed Proudmoore's stronghold and sent the Admiral into a retreat. But Thrall knew that Proudmoore would not stop there.\r\nThe Horde pursued Proudmoore back to the shores of Theramore. Thrall sent in his foot soldiers to keep Proudmoore's forces at bay while Rexxar and his few companions wove through the [[A Blaze of Glory|battle]] to face off against Proudmoore and his most loyal retainers. In the end, Rexxar and Proudmoore squared off in mortal combat. Rexxar emerged victorious. At Proudmoore's defeat, the battle ground to a halt, and Jaina collapsed at the body of her father. Rexxar, Thrall, and the rest of the Horde withdrew from Theramore.\r\nThrall invited Rexxar to return to Durotar with him, but Rexxar told him that his place was still in the wild. He named the ogre [[Mok'Morokk]] as the leader of the Stonemaul Clan and then disappeared into the barren wilderness.\r\n===Later activities===\r\nRexxar briefly returned to Orgrimmar to seek medical aid for an old orc who was attacked by the [[Burning Blade Clan]], and was peripherally involved the subsequent altercation between Durotar and Theramore. Rexxar swiftly returned to the wilds.\r\n===In World of Warcraft===\r\nUnfortunately, the Stonemauls were assailed by the [[Black Dragonflight]] and forced from their home. However, Mok'Morokk is revealed as a selfish tyrant, and is eventually usurped by another ogre named [[Tharg]] with the help of an ogre-mage [[Draz'Zilb]]. Mok'Morokk flees [[Brackenwall]].\r\n \r\nRexxar himself left to roam the wild lands of Kalimdor once again, and could be found patrolling [[Desolace]] and [[Feralas]], with Misha always at his side. He assists heroes of the Horde in destroying [[Onyxia]].\r\n===In the Burning Crusade===\r\nSince the re-opening of the Dark Portal, the Mok'Nathal warrior now resides in [[Thunderlord Stronghold]] in the [[Blade's Edge Mountains]] in [[Outland]], protecting the base from the beasts and monstrosities of Blade's Edge. He has been replaced by an orc named [[Rokaro]], who is another Champion of the Horde. He is located at [[Shadowprey Village]] in Desolace.\r\nRexxar wishes to find more of his people, and perhaps one day make peace with his father, Leoroxx, who remains embittered about Rexxar's decision to join the Horde.\r\n==Rexxar's Pets==\r\nAs his title of Beastmaster suggests, Rexxar is a master of the wild, and has befriended many creatures in his travels. Though he is most often seen with his faithful bear Misha, he's also been known to call upon his other animal friends when needed. They are:\r\n* Haratha (wolf) - deceased\r\n* Misha (bear)\r\n* Spirit (hawk)\r\n* Huffer (boar)\r\n* Leokk (wyvern)\r\n==Memorable quotes==\r\n* \"The orcs changed because one person said so. That person stands before you now as Warchief. Do you doubt him?\"\r\n*\"I have watched the other races... Seen their squabbling, their ruthlessness. Their wars do nothing but scar the land, and drive the wild things to extinction.\"\r\n*\"No.... They cannot be trusted. Only beasts are above deceit.\"\r\n*\"Where I lay my head is home.... See that rock? That's my pillow.\" A possible reference to the 1991 song \"Wherever I May Roam\" by Metallica.\r\n==Quests==\r\nHe starts the following quests:\r\n* Whispers on the Wind\r\n* On Spirit's Wings\r\n* Baron Sablemane\r\n* The Smallest Creatures\r\n* A Boaring Time for Grulloc\r\n* Gorgrom the Dragon-Eater\r\n* Prisoner of the Bladespire (Group)\r\n* Showdown (Horde) (Group)\r\nThe quests Rexxar used to give the player before the expansion are now given by [[Rokaro]] in [[Shadowprey Village]].\r\n==Notes==\r\n*Rexxar is described as a half-breed in some sources, a half-ogre half-orc (or half-orc, half-ogre) in others. Along with these descriptions there are other sources, imply that one of his parents was orc, and one of them ogre.\r\n*Rexxar is called the \"last son of the Mok'Nathal\", sometimes \"last of the Mok'Nathal\". This could mean several things, either that he was the last of his clan (which has been proven false), the last half-ogre in the Mok'Nathal clan (unknown), last of his kind on Azeroth (other half-ogres have appeared after his exploits although they may not be part of the Mok'Nathal Clan), or the last Mok'Nathal born to his clan (there is implication Rexxar may have fathered more half-ogres in Azeroth, though these don't appear to be affiliated with the clan).\r\n*Prior to the [[Burning Crusade]] expansion, his model appeared to be that of just an recolored orc; his model now more strongly resembles his appearance in Warcraft III.\r\n==See also==\r\n*[[List of Blade's Edge Mountains NPCs]].\r\n*[[Warcraft III: The Frozen Throne]]",},
			["Rex Ashil"] = { content = "'''Rex Ashil''' is a level 57 [[elite]] [[rare mob]] [[Silithid]] found in [[Hive'Ashi]] in [[Silithus]].\r\nThe word \"Rex\" means \"King\", so he must be interpreted as the \"King of Ashi\". This is reinforced by the fact he's elite while the rest of the mobs are elite no more.",},
			["Rez"] = { content = "#REDIRECT [[Resurrect]]", redirect = "Resurrect",},
			["Rezlak"] = { content = "'''Rezlak''' is a level 5 [[quest giver]] located by the road just north of the canyons south of [[Orgrimmar]] in the [[orcish]] starting zone of [[Durotar]]. He is affiliated with the [[Tinkers' Union]]. He also gives the only 2 Alliance quests available in Durotar.\r\nHe starts the following quests:\r\n* Winds in the Desert\r\n* Securing the Lines\r\nSee [[List of Durotar NPCs]].",},
			["RFK"] = { content = "#REDIRECT [[Razorfen Kraul]]", redirect = "Razorfen Kraul",},
			["Rhahk'Zor"] = { content = "'''Rhahk'Zor''' <The Foreman> is a level 19 [[elite]] [[ogre]] in the [[Deadmines]]. Rhahk'zor is the foreman in charge of [[Edwin VanCleef]]'s construction projects.\r\nAs in [[Warcraft I]], the Deadmines were invaded by Ogres and were slaughtered by [[Blackhand]]'s army, Rhahk'Zor could be a survivor of the massacre perpetrated by the [[Orcs]] in order to punish them for plotting with [[Griselda]]. However, this event happened during the First War, and Rhahk'zor belonging to this band of Ogres is pure speculation.\r\n==Combat Info==\r\nRhahk'Zor provides a fairly straightforward fight and has the most health out of all bosses except for Edwin VanCleef who his health is roughly tied with. The only \"trick\" to this fight is the pull. Just wait til he walks farther away from the two Defias mobs, and then pull. Of course, with any decent group, these mobs don't present any sort of difficulty and so can be pulled with the big ogre. Rhahk'zor cannot be slowed by mages frost spells.\r\n==Abilities==\r\n*'''Rhahk'Zor Slam''' - Inflicts 64 to 86 damage to an enemy, stunning it for 3 sec.\r\n==Quotes==\r\n'''Aggro''' ''VanCleef pay big for your heads!''",},
			["Rhakish"] = { content = "'''Rhakish''', though only mentioned, was the grandfather of [[Draka]], making him the father of [[Kelkar]] and the great-grandfather of [[Thrall]].",},
			["Rhapsody Shindigger"] = { content = "'''Rhapsody Shindigger''' is a level 44 [[quest giver]] located in [[Shindigger's Camp|his camp]] in the [[contested]] territory of the [[Hinterlands]]. He used to be one of the finest [[gryphon]] riders in the lands. He also happened to be one of the biggest drinkers in the lands. After one fateful flight where he fell off his gryphon over the [[Swamp of Sorrows]] due to a few too many ales, he was released from his duties as a gryphon rider. He now has a small moonshine camp east of [[Aerie Peak]].\r\nHe starts the following quests:\r\n*Rhapsody's Kalimdor Kocktail\r\n**Rhapsody's Tale\r\nSee [[List of the Hinterlands NPCs]].",},
			["Rhonin"] = { content = "'''Rhonin''' is the current leader of the [[Kirin Tor]]. A powerful [[human]] [[mage]], Rhonin was instrumental in breaking the power of the [[orc]]s at the end of the [[Second War]] by freeing the Dragonqueen [[Alexstrasza]] from her imprisonment by [[Nekros Skullcrusher]], a former [[orc]] [[warlock]] of the [[Dragonmaw Clan]] who used the [[Demon Soul]] to keep her prisoner.\r\nWith the war intensifying in [[Northrend]], Rhonin has come to the forefront and now leads the Kirin Tor from the [[Violet Citadel]] in the rebuilt city of [[Dalaran]].\r\n==Biography==\r\nRhonin was once a promising mage of the Kirin Tor until a disastrous mission involving the reckless use of magic cost the lives of all his comrades - whilst Rhonin was casting a spell, others in his group got in the path of his attack. He was cast into probation until the opportunity for penance arose with a dangerous mission into [[Khaz Modan]]. He was assisted in this mission by the [[High elf|high elven]] ranger [[Vereesa Windrunner]], the warrior [[dwarf]] [[Falstad Dragonreaver]], and the dragon-mage [[Korialstrasz|Krasus]], who was the instigator of this mission.\r\nHe was also assisted (at first) by the evil dragon [[Deathwing]], but Deathwing's true purpose was to steal some of Alexstrasza's eggs to replenish his own decimated dragonflight. With a gemstone created from Deathwing's scale, Rhonin was able to destroy the Demon Soul and release Alexstrasza.\r\nDuring this mission, Rhonin and Vereesa fell in love, and were later married. Along with Vereesa and Krasus, Rhonin was among the few well-known survivors of the [[Scourge]] that destroyed Lordaeron, Dalaran and Quel'Thalas after the corruption of [[Arthas Menethil|Prince Arthas]]. Most of Rhonin's family, including his father, were killed during the fall of the town of [[Andorhal]].\r\nWhile he and Vereesa were preparing for the birth of their twin offspring, Rhonin was once again summoned by Krasus for help. Apparently, the dragon-mage had discovered a rift in time, which swallowed both of them, along with the orc veteran [[Broxigar]]. The three were sent 10,000 years back in time to the first invasion of the [[Burning Legion]].\r\nWhile in the past, Rhonin encountered legendary beings such as [[Cenarius]], [[Malorne]], [[Aviana]], and became friends with the heroes [[Illidan Stormrage|Illidan]] and [[Malfurion Stormrage]], [[Tyrande Whisperwind]], [[Jarod Shadowsong|Jarod]] and [[Maiev Shadowsong]] and [[Shandris Feathermoon]]. Rhonin actually became Illidan's mentor, not in the least to try and harness his reckless power, but despite Illidan's admiration, much of Rhonin's work involved cleaning up Illidan's mistakes. When Illidan defected, Rhonin assumed command of the [[Moonguard]]. As a reward for Rhonin's courage, [[Nozdormu]] allowed Rhonin to return to Vereesa at the moment she went into labor to ensure he would not miss a moment of the twins' lives. Nozdormu also offered the children the friendship of the Bronze Dragonflight.\r\nHis surname or title appears to be Redhair.\r\nHe is apparently able to speak or translate [[Ursine]]. He has also become a skilled swordsman.\r\n==Personality==\r\nRhonin is a studious type who knows a little bit about a great many things, but generally keeps his knowledge to himself. He is very young, but his youth disguises a spellcaster of great power and flexibility. He is reckless and hot-headed, and is known frequently not to look before he leaps, a character flaw he recognizes in himself and yet is hard pressed to keep under control.\r\n==Combat==\r\nAs a quick study of his spell selection will indicate, Rhonin prefers to use his sorcerer abilities for versatility in combat while his wizard spells are usually left to more mundane tasks. He generally starts off a fight with the most powerful spells at his disposal, working his way down to employing searing arrows in concert with his crossbow once all his other combat spells are exhausted.\r\n==World of Warcraft==\r\nAn epic cloth chest piece known as the Robes of Rhonin drops off [[Archimonde (tactics)|Archimonde]] in the [[Caverns of Time]] raid [[Battle for Mount Hyjal]]. Presumably, these may have been robes worn by Rhonin himself. This raises the question of how Archimonde came to possess his robes...\r\n===''World of Warcraft: Wrath of the Lich King''===\r\nRhonin will appear in the upcoming [[Wrath of the Lich King]] expansion as the leader of the [[Kirin Tor]]. He will be located in the rebuilt and relocated city of [[Dalaran]] in [[Northrend]], with [[Vereesa Windrunner]], [[Archmage Modera]] and [[Archmage Aethas Sunreaver]] at his side. He will be fighting the [[Blue Dragonflight]] and their leader [[Malygos]], who is determined to destroy mortal magic-users.\r\nHe begins the following quest:\r\n*Discretion is Key\r\n==Memorable quotes==\r\nRhonin: \"The plan sounds too simple to work...\"\r\n[[Huln Highmountain]]: \"Simple can be good, if it's drawn from reason.\"\r\nRhonin: \"Somehow, I doubt [[Stareye]] has reason. I don't understand why [[Ravencrest]] and he got along so well.\"\r\n[[Jarod Shadowsong]]: \"They are of the same caste.\"\r\nRhonin: \"Oh! It all makes so much sense then...Never mind, we'll just have to watch out and hope for the best.\"\r\n----\r\n\"The other races may see no reason to ally themselves with ones who'd almost as much as the [[Burning Legion]] prefer to see them all wiped out. We're talking centuries of enmity, [[Krasus]].\"\r\n----\r\nNight Elf Noble: [[Tauren]] in [[Zin-Azshari]]? How barbaric!\r\nRhonin: They'd rather have demons?\r\n[[Malfurion Stormrage]]: You wouldn't understand.\r\nRhonin: No, I wouldn't.\r\n==See also==\r\n*''[[Day of the Dragon]]'' by [[Richard A. Knaak]]\r\n*''[[War of the Ancients Trilogy]]'' by [[Richard A. Knaak]]",},
			["Ribbly Screwspigot"] = { content = "==Background==\r\n'''Ribbly Screwspigot''' hides from bounty hunters in the Grim Guzzler bar in Blackrock Depths.\r\n''My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another. Well, his last scheme must have been his worst, because Baron Revilgaz of Booty Bay just put a price on poor Ribbly's head. I can't tell you how happy this makes the Screwspigots! Our little Ribbly's finally worth something! But now he's hiding out, deep in Blackrock Depths. Please, find him and bring him to me! Or, if he won't come, then that's ok... just bring me his head.'' - [[Yuka Screwspigot]]\r\n==Quests==\r\n*Ribbly Screwspigot\r\n==Loot==\r\n*Plans: Dark Iron Plate\r\n*Ribbly's Bandolier\r\n*Ribbly's Quiver\r\n*Wayfarer's Knapsack\r\n*Ribbly's Head ''(Quest Item)''",},
			["Ribbon Dance"] = { content = "<onlyinclude><onlyinclude>\r\n'''Ribbon Dance''' is a [[buff]] gained by dancing around the [[Ribbon Pole]]s.\r\n==Notes==\r\nThe longer you dance around the pole the longer the buff will last, up to 60 minutes.",},
			["Richard A. Knaak"] = { content = "<div style=\"border:1px solid gray; float:right; padding:6px 0px 6px 6px; text-align:center;\"><imagelink>\r\n<small>Picture from \r\n</small></div>\r\n'''Richard A. Knaak''' is the author of several ''[[Warcraft]]'' books and. He has also written for [[Blizzard Entertainment|Blizzard]]'s other franchises, ''[[Diablo]]'' and ''[[StarCraft]]''.\r\n==Involvement==\r\nKnaak was approached by Blizzard because of his work for ''Dragonlance''. Some of the heads of Blizzard had grown up on his Dragonlance works and asked him to write for both Warcraft and Diablo. Knaak accepted because it allowed him to write for both of the kinds of fantasy that he liked: ''Lord of the Rings''-type fantasy (Warcraft) and dark fantasy (Diablo) He familiarized himself with Warcraft by playing [[Warcraft II]] quite a bit. He also played [[World of Warcraft]] a little bit, but used a lot of background material and screen shots for inspiration. Knaak communicates regularly with Blizzard's lore department to make sure that the facts presented in his works are consistent.\r\nKnaak was heavily involved in the draconic mythos. The characters of [[Ysera]], [[Nozdormu]], and [[Malygos]], the remaining dragon [[Aspect]]s (both Alexstrasza and Deathwing were in the mythos previously), were introduced in ''Day of the Dragon'', which set the stage for many of the new developments in [[Warcraft III]]. The characters remain vital to lore today.\r\nUntil recently, most characters introduced in Knaak's books were not physically present in games. The minor character of [[Soridormi]] was introduced with the [[Caverns of Time]], and [[Tyrygosa]] and [[Jorad Mace]] were introduced with [[The Burning Crusade]]. [[Anveena]] and [[Kalec]] were added in [[Patch 2.4.0]], and Ysera and Nozdormu will make small cameos in [[Wrath of the Lich King]]. [[Vereesa]], [[Rhonin]] and [[Krasus]] will act as quest-givers in Wrath, in a storyline centered around Malygos.\r\n==Warcraft Bibliography==\r\n*''[[Day of the Dragon]]'' (2001)\r\n*''[[War of the Ancients Trilogy]]''\r\n**''[[The Well of Eternity]]'' (2004)\r\n**''[[The Demon Soul]]'' (2004)\r\n**''[[The Sundering]]'' (2004)\r\n*''[[The Sunwell Trilogy]]''\r\n**''[[Dragon Hunt]]'' (2005)\r\n**''[[Shadows of Ice]]'' (2006)\r\n**''[[Ghostlands]]'' (2007)\r\n*''[[Night of the Dragon]]'' (2008, yet to be released)\r\n*''[[Dragons of Outland]]'' (2009)\r\n*''[[Stormrage (novel)|Stormrage]]'' (TBA)\r\n==Controversy==\r\nThere is currently a hot debate in regards to Knaak's writing styles and talents among the Warcraft player community. This debate is fueled by individuals who argue that Knaak's \"pet characters\" such as [[Rhonin]] and [[Krasus]], are given far too much attention (as well as in-story power) by comparison to characters who dwell in the games, such as [[Tyrande]] and [[Malfurion]] in the War of the Ancients Trilogy, while others argue that, since the books are considered canon to the lore, it makes no difference how Knaak treats the characters provided that the story is good (Which, in itself, is an entirely different debate.)",},
			["Richard Epcar"] = { content = "'''Richard Epcar''' is the voice actor who provided the voice for [[Priest (WC3)|Priest]]s in [[Warcraft III]] and its expansion, [[The Frozen Throne]].",},
			["Richard Knaak"] = { content = "#redirect [[Richard A. Knaak]]", redirect = "Richard A. Knaak",},
			["Rich Adamantite"] = { content = "#REDIRECT [[Adamantite]]", redirect = "Adamantite",},
			["Rich Adamantite Deposit"] = { content = "#REDIRECT [[Adamantite]]", redirect = "Adamantite",},
			["Rich thorium vein"] = { content = "#REDIRECT [[Thorium]]", redirect = "Thorium",},
			["Ricket's Folly"] = { content = "'''Ricket's Folly''' can be found just to the west of [[K3]].",},
			["Ricter"] = { content = "'''Ricter''' is a level 33 [[Forsaken]] found in the [[Lordamere Internment Camp]] in the [[Alterac Mountains]].\r\n[[Magus Wordeen Voidglare]] wants the Bloodstone Marble that Ricter stole.\r\n==Quests==\r\n*Prison Break In\r\n==Loot==\r\n*Bloodstone Marble ''(Quest Item)''",},
			["Ride to Orgrimmar"] = { content = "Ride to Orgrimmar is the 2nd quest in the '''Meats to Orgrimmar''' quest chain.\r\n==Objectives==\r\nBuy a wind rider to Orgrimmar from the wind rider master Devrak, then bring Zargh's Meats to Gryshka in Orgrimmar.\r\n* Zargh's Meats (Provided)\r\n==Description==\r\nFor just a few coins I will have a wind rider bring you to Orgrimmar. When you get there, you can take Zargh's Meats to Gryshka. Her inn is in the Valley of Strength, not far from the Skytower, where my wind rider will drop you off.\r\nSpeak with me again when you are ready for the journey.\r\n==Progress==\r\nSomething smells good! You don't have raw meat on you, do you?\r\n==Completion==\r\nOh, wonderful! Those are fine cuts! These are from Zargh, are they? That <race> sure knows his way into a lady's heart...\r\nOh, I can't wait to cook it. But not too much! Meat is best served rare, don't you think?\r\n==Rewards==\r\nYou will receive: s=1 gold c=75 silver \r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*420 [[XP]] (or s=2 gold c=40 silver at level 70)\r\n*75 with [[Darkspear Trolls]]\r\n*75 with [[Orgrimmar]]\r\n==Quest chain== \r\n#Meats to Orgrimmar\r\n#Ride to Orgrimmar\r\n#Doras the Wind Rider Master\r\n#Return to the Crossroads.\r\n==Notes==\r\n*This quest is for [[Orc]]s and [[Darkspear]]s only.\r\n*You will need one inventory spot to accept this quest and receive , which is required to complete this quest.\r\n*Devrak is the Wind Rider Master in the western part of Crossroads.\r\n*Completion of this quest will allow one to receive the Doras the Wind Rider Master quest.",},
			["Ride to Thunder Bluff"] = { content = "==Objectives==\r\nBuy a wind rider to [[Thunder Bluff]] from the wind rider master [[Devrak]], then bring the [[Bundle of Hides]] to [[Ahanu]] in [[Thunder Bluff]]. \r\n* Bundle of Hides (Provided)\r\n== Description==\r\nFor a small fee, I will give you a wind rider to [[Thunder Bluff]]. There's no faster way to the city!\r\nIf that is acceptable, speak to me again when you are ready to go.\r\nIf you're taking those hides to [[Ahanu]], then I think he's at Hewa's Armory, at the base of the wind rider tower in [[Thunder Bluff]]. And that's right where you'll land! \r\n== Reward==\r\nYou will receive:1 silver 75 copper \r\n== Progress==\r\nThere is dust on your shoulders that must be from the Barrens. You have spoken with my friend Jahan? \r\n== Completion==\r\nAh, a new bundle of hides. I will get to work on these immediately!\r\nThank you, brother. You have done me a great service. Here are some coins to pay for your time and travel costs. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*420 [[XP]] (or 2 silver 40 copper at level 70)\r\n*75 [[reputation]] with [[Thunder Bluff]]\r\n= Notes = \r\n*This quest is [[Tauren]] only.",},
			["Ridgepoint Tower"] = { content = "'''Ridgepoint Tower''' is one of the guard towers constructed in [[Elwynn Forest]]. These towers are well defended against any enemies who encroach into [[Human]] lands. Ridgepoint in particular serves as a watchpost against encroachment by gnolls and orcs from [[Redridge Mountains]], undead from [[Duskwood]], as well as [[Defias]] from nearby camps.",},
			["Riding"] = { content = "'''Riding''' is a secondary [[profession]] in which [[character]]s may learn to ride '''[[mounts]]'''. Every mount has a minimum skill level required for riding.\r\nIn general, a normal mount will require [[Apprentice]] riding skill, and a swift mount will require [[Journeyman]] skill, but there are exceptions.\r\n''More detail on the requirements for each mount can be found on the [[Mounts]] page.''\r\n==Skill levels==\r\nThe following table lists the skill levels available and the cost to train the skill. Due to the high cost of training, the price with discount is also listed in the table. The only discount available is a faction discount (5% , 10% , 15% , and 20% ).\r\nThe expert and artisan riding masters are not part of any faction, and therefore it is not possible to receive any discount for those riding skills.\r\nNote that [[Paladin]]s and [[Warlock]]s receive the 75 and 150 skills as part of buying their level 30 and 60 mounts from their Trainer, and [[Druid]]s receive the 225 skill (if they already have 150) with flight form at level 68.\r\nAlso note that, like all professions, all lower ranked skill levels must be learned before training further (eg Expert skill is required to train Artisan skill).\r\nThe level requirement for apprentice riding was reduced from 40 to 30 on July 15, 2008 by patch 2.4.3.\r\n==Flying==\r\nDisambiguation:\r\n* [[Mounts| Flying mounts]]\r\n* [[Content exclusive to flying mounts]]\r\n* [[Flight master]]\r\n* [[Flight path]]\r\n* [[Movement]] > [[Transportation]]\r\n* [[Flight Form]] (The [[Druid]]'s flight form)\r\n* [[Swift Flight Form]] (The [[Druid]]'s epic flight form)\r\n* [[Flying Machine]]\r\n==Historical note==\r\nThe cost structure and functionality of Riding and [[Mounts]] was changed in patch 1.12.1.\r\nPrior to that patch, Riding was an [[ability]] rather than a secondary [[Profession]], and had only one rank. Each faction had its own riding skill (tiger riding, horse riding, mechanostrider piloting, ram riding) and the cost was 20 gold , available at level 40. reputation was required to learn cross-faction riding skill, but mounts were [[Bind on Use]] and purchasable by anyone for 80 gold . This meant that characters who were PvP rank 3 or higher could pass on the 10% discount directly to other characters by buying the mount for them. This is no longer possible because all mounts are now [[Bind on Pickup]], and the majority of the cost is built into the riding skill training (which is no longer faction-specific) rather than the cost of the mount.\r\nPvP rankings also no longer grant the player an additional 10% discount as of [[patch 2.0.1]].\r\nBefore [[TBC]] the cost of Journeyman riding was 900 gold , so the total cost of getting an epic mount was the same as before. It has since been reduced to 600 gold to make it easier to buy Expert riding skill.\r\n[[Patch 2.4.3]] lowers the Apprentice Riding level requirement from 40 to 30. It also reduces the cost from 90 gold to 35 gold .",},
			["Riding Crop"] = { content = "'''Riding Crop''' is a craftable [[trinket]] which increases a mount's speed.\r\n==Source==\r\nRiding Crop is crafted by [[Leatherworking|Leatherworkers]] with a skill level of 350.\r\nThe [[pattern]] is sold by [[Thomas Yance]] in the [[Old Hillsbrad Foothills]] for 5 gold .\r\n==Notes==\r\n* This trinket works on flying as well as land based mounts\r\n* It gives approximately 1.5% more mounted speed than the [[Enchant Gloves - Riding Skill| Riding Skill]]/[[Mithril Spurs]]/[[Carrot on a Stick]] combo (and saves two bag spots).\r\n* This trinket does NOT stack with other mount-speed increasing items such as [[Carrot on a Stick]] or spells such as [[Crusader Aura]].\r\n* This trinket does NOT work with any druid flight form. \r\n* Skybreaker Whip is a quest reward that does the same thing as the Riding Crop. The quest requires Honored [[Netherwing]] and Epic flying.\r\nThis has been tested with visual comparison to other players with varying degrees of speed enhancing items as well as with speed measuring in-game mods.\r\n* This trinket is now only useful for two levels; requires 69 to use, and does not affect anyone over 70.\r\n==See also==\r\n[[Mount]]",},
			["Riding instructor"] = { content = "#REDIRECT [[Riding trainers]]", redirect = "Riding trainers",},
			["Riding Silithid"] = { content = "#REDIRECT [[Qiraji battle tank mounts]]", redirect = "Qiraji battle tank mounts",},
			["Riding trainer"] = { content = "#REDIRECT [[Riding trainers]]", redirect = "Riding trainers",},
			["Riding trainers"] = { content = "The following trainers teach the skill necessary to ride specific mounts.",},
			["Rifleman"] = { content = "A '''rifleman's''' tactics are fairly basic; find a nice corner from which he can survey as much of the surrounding area without being spotted as possible, plot an escape route, and wait for his target to walk into his sights.\r\n==Dwarven Rifleman==\r\nThe brave dwarven riflemen have faithfully protected their mountain kingdom of Khaz Modan ever since the battle of Grim Batol. Yet, as new threats arose to threaten their hard-won freedom, they offered their expert skills and tenacity to the Alliance. Using the legendary single-shot Blunderbuss Long Rifles, riflemen are excellent marksmen and can shoot both land based and airborne opponents.\r\nThe dwarven rifleman is a native of the Ironforge clans who specializes in use of the long rifle. Typically, they use their climbing skills to work their way into a good vantage point, then rain death upon their enemy from above. Riflemen usually have long beards and wear blue, hooded cloaks. They carry a long rifle against their shoulder and scowls on their faces. Riflemen are dwarven [[sharpshooter]]s. Dwarven Riflemen are the first ranged units available to the humans. \r\n \r\n==Pandaren Rifleman==\r\nRecently introduced to the pandaren are firearms, which are beginning to take a more important role in the way the pandaren wage war. While only a few of the [[shao'din]]s have rifle regiments, the pandaren have taken to the rifle like a dwarf to ale. Some pandaren riflemen even go so far as to travel abroad to learn the shooting techniques of other races, and bring the best techniques back to Pandaria. These riflemen mark a new evolution in the way the pandaren wage war, a change to traditions that most likely have not altered in millennia.\r\n==Quotes==\r\n*See [[Quotes_of_Warcraft_III/Human_Alliance|Warcraft II Rifleman Quotes]]",},
			["Riflemen"] = { content = "A rifleman's tactics are fairly basic; find a nice corner into which he can survey as much of the surrounding area without being spotted as possible, plot an escape route, and wait for his target to walk into his sights.\r\n==Dwarben Rifleman\r\nThe brave dwarven Riflemen have faithfully protected their mountain kingdom of Khaz Modan ever since the battle of Grim Batol. Yet, as new threats arose to threaten their hard-won freedom, they offered their expert skills and tenacity to the Alliance. Using the legendary single-shot Blunderbuss Long Rifles, riflemen are excellent marksmen and can shoot both land based and airborne opponents.\r\nThe dwarven rifleman is a native of the Ironforge clans who specializes in use of the long rifle. Typically, they use their climbing skills to work their way into a good vantage point, then rain death upon their enemy from above. Rifleman usually have long beards and wear blue, hooded cloaks. They carry a long rifle against their shoulder and scowls on their faces.",},
			["Rift (Maelstrom)"] = { content = "The '''Rift''' is the remains of the first [[Well of Eternity]]. At the end of the [[War of the Ancients]], the powers released in the Well of Eternity blasted the well downward into [[Azeroth]]'s molten core. 10,000 years later that core is still exposed. The well's descent broke an enormous fissure in the ocean floor. The red and orange light from lava is visible deep, deep down. It is held sacred by the [[Naga]], who are capable of reaching its depths. The seafloor around The Rift is noted for its thermal activity. [[Nazjatar]] is constructed on the sides of the Rift.",},
			["Rift Keeper"] = { content = "'''Rift Keeper''' can be found in [[The Black Morass]] .",},
			["Rift Lord"] = { content = "'''Rift Lord''' can be found in [[The Black Morass]] .",},
			["Rigglefuzz"] = { content = "'''Rigglefuzz''' is a level 37 [[quest giver]] located in a small camp in the [[Valley of Fangs]] in the [[contested]] territory of [[Badlands]]. He is affiliated with the [[Steamwheedle Cartel]].\r\nHe starts the following [[quest]]s:\r\n* Power Stones (Dungeon)\r\n* Pearl Diving\r\n* Barbecued Buzzard Wings (Cooking)\r\nSee [[List of Badlands NPCs]].",},
			["Riggle Bassbait"] = { content = "Riggle Bassbait is the goblin who organizes the [[Stranglethorn Fishing Extravaganza]], together with his mechanical help [[Fishbot 5000]] and his assistant [[Jang]] in [[Booty Bay]].\r\n==Riggle's Story==\r\nGull cries echoed off the cliffs surrounding Booty Bay as the sun dipped toward the horizon. [[Baron Revilgaz]] leaned against the wall of the inn, sifting through the latest reports from the marketplace. The news was troubling; with the recent wars in Alterac Valley and Warsong Gulch, far from the shores of Stranglethorn, business had been struggling of late. The goblin frowned. It would be difficult to draw visitors back to his colorful port without a gimmick of some kind; the old wounds between Alliance and Horde still ran deep in the adventurers of the day. \r\nThe light in the room disappeared suddenly. Revilgaz turned to find the large, grizzled [[Fleet Master Seahorn]] in the doorway. \"There's some nutty goblin rowing into the harbor,\" Seahorn rumbled. \"He's shouting your name over and over. Sounds like a damn parrot.\" \r\nCurious, the Baron walked out onto the balcony, his eyes seeking this mysterious visitor. The search was short; he quickly sighted the simple rowboat tied at the dock, as well as the bruisers escorting the owner. From this height, it was impossible to confirm the identity of the individual, but at the least it would prove a distraction from the trials of administration. \r\nThe escort reached his balcony at last and pushed the guest forward. Revilgaz arched a brow at the thin goblin before him, trying hard to maintain his smile as his nostrils were assailed by the stench of fish. \"It's Riggle Bassbait, isn't it?\" he said, determined to get through this meeting as quickly as possible. \"What can I do for you?\" \r\nRiggle's face split into a hopeful smile. \"You remember me! Please, Baron Revilgaz, I've just made the most amazing discovery. It's sure to breathe life back into the fishing industry, you mark my words! There's just one problem. . .\" The fisherman rubbed the back of his neck nervously. \"I don't have the gold I'd need to properly fund such an operation. I don't suppose you could give me a loan...?\" \r\nRevilgaz's smile vanished instantly, all pretense of friendliness gone. \"I already extended you credit once, Bassbait. I can't afford to be handing out favors; particularly not now. Sorry I can't be of more help.\" He gestured dismissively to the bruisers, who took hold of Riggle's wrists. \r\n\"Wait!\" the angler cried, fighting as the bruisers pulled him away. \"I brought a sample of what I've found. Please, let me prepare it for you!\" \r\nA sigh escaped the Baron's lips. \"Oh, all right. I hope you're not wasting my time.\" \r\nAn hour later, the Blackwater cooks presented the Baron with a steaming plate of fish. The master angler stood to one side, wringing his hands anxiously, as Revilgaz took a tentative bite. His eyes flew wide as soon as the meat hit his tongue. \"This is fantastic!\" the Baron exclaimed. \"What is this? I've never tasted the like.\" \r\n\"Tastyfish, I call it,\" Bassbait said with a sheepish grin. \"I can get more, but I need money first...\" \r\nRevilgaz stood and patted the fisherman's shoulder. \"I have a better idea, one that will serve us both. I'll have my economy bustling again, and you will have your name on the lips of every angler in Azeroth. Come, let's discuss the terms.\" With that, he led the curious Riggle into his office... \r\n \r\nWeeks later, a satisfied Baron Revilgaz looked out over his beloved town, adventurers pouring from the recently arrived ships. Goblin vendors were out among the new arrivals, doing brisk business on bait and tackle. Beside the Baron, an amazed Riggle Bassbait stood with jaw agape. \r\n\"You see?\" Revilgaz said with a grin. \"Everyone's here for your new tournament. They'll catch the fish you seed along the coast, and everyone profits.\" He clapped the angler on the back. \"Go seed the waters; they're anxious to begin. Oh - and make sure to keep the water around Booty Bay itself clear; I'd rather the participants have to hike a bit. They'll be thirstier when they get here; all the better for business.\" \r\nRiggle hurried down to the submarine, his mind awhirl. At long last, his favorite sport would be back in the limelight. Soon everyone would know the name of Riggle Bassbait, Angler Extraordinaire! \r\n© Blizzard Entertainment 2005",},
			["Right-Handed Blades"] = { content = "==Source==\r\nThis item can be purchased for g=2 gold s=17 silver c=8 copper from:\r\n* Lissaf in [[Shattrath City]]\r\n* Thalgus Thunderfist in [[Dun Morogh]]\r\n* Shoma in [[Durotar]]\r\n* Ariyell Skyshadow in [[Teldrassil]]",},
			["Right-Handed Brass Knuckles"] = { content = "==Source==\r\nThis item can be purchased for s=21 gold c=30 silver from:\r\n* Lissaf in [[Shattrath City]]\r\n* Thalgus Thunderfist in [[Dun Morogh]]\r\n* Shoma in [[Durotar]]\r\n* Ariyell Skyshadow in [[Teldrassil]]",},
			["Right-Handed Claw"] = { content = "==Source==\r\nThis item can be purchased for 81 silver 18 copper from:\r\n* Shoma in [[Durotar]]\r\n* Ariyell Skyshadow in [[Teldrassil]]\r\n* Thalgus Thunderfist in [[Dun Morogh]]\r\n* Lissaf in [[Shattrath City]]",},
			["Righteous Armor"] = { content = "'''Righteous Armor''' is the third [[Armor Set|Dungeon set]] for Paladins. \r\n==Notes==\r\nThis set is intended for protection Paladins.\r\nSee also: [[Set look alikes]]",},
			["Righteous Defense"] = { content = "Introduced in [[Patch 2.0|2.0]] (The Burning Crusade), '''Righteous Defense''' is a method for Paladin's to temporarily [[taunt]] NPCs.\r\nAs of [[Patch 2.4|2.4]], Righteous Defense can also be cast on an enemy mob, much like the [[Warrior|Warrior's]] [[Taunt (Warrior)|Taunt]] ability. Its behavior when used in this way seems to be much like its behavior if cast on a party member. If the enemy that is taunted is attacking another player, 2 more enemies that may be attacking that player will also be taunted.\r\n==Tips and tricks==\r\nUnlike Warrior's [[Taunt (Warrior)|Taunt]] and Druid's [[Growl (Druid)|Growl]], this ability is ranged. This allows for some interesting tactics to be used in PvE. However, given the majority of a paladin's abilities are short ranged, the possible tactics is fairly limited as the tanking paladin would have difficult time retaining the aggro until he is once again in melee range with the mobs.\r\n===Macros for this ability===\r\nThis macro causes Righteous Defense to act similarly to a warrior's [[Taunt (Warrior)|Taunt]] ability. (Not necessary since patch 2.4 as Righteous Defense now works on enemy mobs as well.)\r\n /cast [target=targettarget,help] Righteous Defense\r\nThis lets you cast the spell without changing targets. Another thing you can do is add \"combat\" to the conditionals, and add another spell at the end to cast if you're not in combat (You'd likely never cast Righteous Defense out of combat).\r\n #showtooltip\r\n /cast [help,target=mouseover] [help,target=mouseovertarget] Righteous Defense",},
			["Righteous Fury"] = { content = "''\"A Paladin's fury is a quiet, solemn thing, ever a hair before the bloodlust of a Warrior or the ferocity of a beast. But it holds his foes just the same.\"''\r\nIncreases the threat generated by all of the Paladin's Holy spells. Lasts 30 minutes.\r\n==Talent Improvements==\r\n*[[Improved Righteous Fury]] (3 Ranks) will additionally decrease damage taken by the Paladin by 2/4/6%.\r\n==Tips & Tricks==\r\n*'''Righteous Fury''' is absolutely necessary for Paladins who are [[Main Tank]]ing to ensure adequate threat generation. The 6% damage reduction from the Improved Righteous Fury also makes a significant difference.\r\n*It is a good practice to recast it frequently even when it may still have half the duration left, and always recast it before any boss fight. This is to ensure it will not expire in the mid of the fight, which will likely resulting in the DPS pulling aggro easily.\r\n*This increases the threat generated by all holy spells, including healing spells.\r\n*Depending on the fight and spec, healing with Righteous Fury active can be either good or bad. Numerous higher tiered raids have large amounts of AOE damage, where the 6% damage reduction from Improved Righteous Fury can save a healer's life, and healing aggro is seldom an issue. However, many fights include aggro wipes or reductions, and 6% damage reduction is not worth pulling off the tank. Keep an eye on the threat meters and know the fights before activating Righteous Fury as a healer.\r\n*Activating this spell with a Retribution build will deactivate the threat-reducing properties of [[Fanaticism]] while the buff is active.\r\n==Mana Usage Bug==\r\n* Previously, players would note that casting this spell drains more mana than the listed cost. This issue was resolved in [[Patch 2.3.2]].",},
			["Righteous Orb"] = { content = "A white sphere, filled with the holy power of righteousness. Used in crafting.\r\n==Source==\r\nThis item drops from [[humanoid]] mobs on the Scarlet side of [[Stratholme]].\r\n==Righteous Orb as an Ingredient==\r\nRighteous Orb is used in the following recipes:\r\n===[[Blacksmithing]]===\r\n* [[Arcanite Champion]]\r\n* [[Girdle of the Dawn]]\r\n* [[Gloves of the Dawn]]\r\n===[[Tailoring]]===\r\n* [[Truefaith Vestments]]\r\n===[[Enchanting]]===\r\n* [[Enchant Weapon - Crusader]]\r\n* [[Enchant Weapon - Healing Power]]\r\n* [[Enchant Gloves - Healing Power]]\r\n==As a quest objective==\r\n* The Dread Citadel - Naxxramas",},
			["Rilak the Redeemed"] = { content = "'''Rilak the Redeemed''' is a level 63 [[quest giver]] located in the [[Lower City]] of the [[neutral]] [[Shattrath City]].\r\nHe starts the following quests:\r\n* The Eyes of Skettis\r\n* Seek Out Kirrik\r\n* Countdown to Doom\r\nSee [[List of Shattrath City NPCs]].",},
			["Rimblat Earthshatter"] = { content = "'''Rimblat Earthshatter''' is a level 60 [[quest giver]] located at [[Light's Hope Chapel]] in the [[contested]] territory of [[Eastern Plaguelands]]. He is affiliated with the [[Earthen Ring]].\r\nHe starts the following quests:\r\n* Earthshatter Boots (Raid)\r\n* Earthshatter Girdle (Raid)\r\n* Earthshatter Handguards (Raid)\r\n* Earthshatter Headpiece (Raid)\r\n* Earthshatter Legguards (Raid)\r\n* Earthshatter Spaulders (Raid)\r\n* Earthshatter Tunic (Raid)\r\n* Earthshatter Wristguards (Raid)\r\nSee [[List of Eastern Plaguelands NPCs]].",},
			["Rin'ji"] = { content = "'''Rin'ji''' is a level 46 [[quest giver]] located in a cage inside [[Quel'Danil Lodge]] in the [[contested]] territory of [[the Hinterlands]]. Even though he (like the rest of his tribe) are enemies of the Horde, Rin'ji is not only friendly to [[Horde]] members, but is also flagged as a Horde member himself. \r\nSee [[List of the Hinterlands NPCs]].\r\n==Quests==\r\nHe starts the quest Rin'ji is Trapped!.",},
			["Rin'wosho the Trader"] = { content = "'''Rin'wosho the Trader''' is a level 56 trade recipe [[vendor]] located on [[Yojamba Isle]] in the [[contested]] territory of [[Stranglethorn Vale]]. He is a member of the [[Zandalar Tribe]] of [[troll]]s. Once your reputation with his tribe reaches friendly, he will start selling various [[formula]]s, [[plans]], [[pattern]]s, and [[recipe]]s only available through the Zandalar Tribe.\r\nHe starts the quest Essence Mangoes (Raid, Repeatable, Honored).\r\nSee [[List of Stranglethorn Vale NPCs]].\r\n======\r\n*[[Greater Dreamless Sleep Potion]] - Alchemy 275\r\n*[[Bloodsoul Gauntlets]] - Blacksmithing 300\r\n*[[Darksoul Shoulders]] - Blacksmithing 300\r\n*[[Brilliant Mana Oil]] - Enchanting 300\r\n*[[Bloodvine Lens]] - Engineering 300\r\n*[[Primal Batskin Bracers]] - Leatherworking 300\r\n*[[Bloodvine Boots]] - Tailoring 300\r\n======\r\n*[[Major Troll's Blood Potion]] - Alchemy 290\r\n*[[Bloodsoul Shoulders]] - Blacksmithing 300\r\n*[[Darksoul Leggings]] - Blacksmithing 300\r\n*[[Brilliant Wizard Oil]] - Enchanting 300\r\n*[[Bloodvine Goggles]] - Engineering 300\r\n*[[Blood Tiger Shoulders]] - Leatherworking 300\r\n*[[Primal Batskin Gloves]] - Leatherworking 300\r\n*[[Bloodvine Leggings]] - Tailoring 300\r\n======\r\n*[[Mageblood Potion]] - Alchemy 275\r\n*[[Bloodsoul Breastplate]] - Blacksmithing 300\r\n*[[Darksoul Breastplate]] - Blacksmithing 300\r\n*[[Blood Tiger Breastplate]] - Leatherworking 300\r\n*[[Primal Batskin Jerkin]] - Leatherworking 300\r\n*[[Bloodvine Vest]] - Tailoring 300\r\n======\r\n*[[Living Action Potion]] - Alchemy 285",},
			["Ring"] = { content = "'''Ring''' refers to a type of [[armor]] worn in the finger [[equipment slot]]. Rings are also called band, seal, signet and other references.\r\n==Notable Rings==\r\n* Don Julio's Band\r\n* Don Rodrigo's Band\r\n* Seal of Ascension\r\n* The Rock\r\n==See also==\r\n* [[:Category:World of Warcraft finger items]]",},
			["Ringo"] = { content = "'''Ringo''' is a level 54 [[quest giver]] located in a cave at coordinates 51,50 at the [[Fire Plume Ridge]] in the [[contested]] territory of [[Un'Goro Crater]].\r\nHe starts the quest A Little Help From My Friends.\r\nSee [[List of Un'Goro Crater NPCs]].\r\n'''Ringo''' is named after The Beatles drummer Ringo Starr, who also sings \"With a Little Help from My Friends\" on the Sgt. Pepper's Lonely Hearts Club Band album.",},
			["Ring of Blood"] = { content = "'''The Ring of Blood''' is a quest line given by a [[Goblin]] named [[Gurgthock]] () in the very north of [[Nagrand]], at the [[Laughing Skull Ruins]]. Completing the quest line, which simply involves one fight after another, rewards you with 66 gold 60 silver , 10x Super Healing Potion and 10x Super Mana Potion, 85,050 Experience, and one of six very popular weapons. The enterprising Gurgthock has turned an area of the ruins into a pit for some good old-fashioned deathmatches. The player starts off as an inexperienced newbie, and finds him or herself steadily pitted against more powerful foes as they win their matches. The fight only ends when one side is a red stain on the ground! Since the enemies encountered in the Ring of Blood are very powerful, this must be done in a group, preferably with a proper [[tank]], a dedicated [[healer]], and lots of dps.\r\nOnly one group can be doing a Ring of Blood fight at a time. After each fight everyone in your party must talk to the NPC to turn the quest in, and then one of you talks to the NPC to start the next fight. The NPC is not available during fights. The result can be frustrating if several groups are trying to do the Ring of Blood at the same time, as everyone is madly trying to talk to the NPC at the same time and start their next fight. (Note: As soon as you drop one of the opponents, another group can start their quest. This '''does not''' interfere with your progress. After the other group has finished off their mob, you can trigger your groups next encounter.) Your entire group MUST stay within the ring for the duration of the fight, although if you have any non-party members helping, they can stay on the sidelines (the quest cannot be raided, but other players can help out). If any party member dies within the ring, they should not release until they get quest credit for a kill.\r\n==Brokentoe==\r\n''Main article: [[Quest:The Ring of Blood: Brokentoe|Brokentoe]]''\r\nThe first quest will pit the party up against Brokentoe, an old and powerful [[Clefthoof]].\r\n'''Rewards'''\r\n* 11 gold 10 silver \r\n==The Blue Brothers==\r\n''Main article: [[Quest:The Ring of Blood: The Blue Brothers|The Blue Brothers]]''\r\nAfter conquering Brokentoe, Gurgthock's next challenge is a pair of [[Lost Ones]] from the [[Murkblood]] tribe, calling themselves The Blue Brothers.\r\n'''Rewards'''\r\n* 11 gold 10 silver \r\n==Rokdar the Sundered Lord==\r\n''Main article: [[Quest:The Ring of Blood: Rokdar the Sundered Lord|Rokdar the Sundered Lord]]''\r\nAfter defeating The Blue Brothers, Gurgthock's next challenge is a giant from the [[Blade's Edge Mountains]], Rokdar the Sundered Lord.\r\n'''Rewards'''\r\n* 11 gold 10 silver \r\n*5 [[Super Mana Potion]]s\r\n*5 [[Super Healing Potion]]s\r\n==Skra'gath==\r\n''Main article: [[Quest:The Ring of Blood: Skra'gath|Skra'gath]]''\r\nAfter defeating Rokdar, Gurgthock's next challenge is an enormous [[Voidcaller]] called [[Skra'gath]].\r\n'''Rewards'''\r\n* 11 gold 10 silver \r\n*5 [[Super Mana Potion]]s\r\n*5 [[Super Healing Potion]]s\r\n*20 [[Netherweave Bandage]]s\r\n==The Warmaul Champion==\r\n''Main article: [[Quest:The Ring of Blood: The Warmaul Champion|The Warmaul Champion]]''\r\nAfter defeating Skra'gath, Gurgthock's next challenge is either an [[Orc]], [[Ogre]], [[Lost One]], or [[Ethereal]] that is chosen at random.\r\n'''Rewards'''\r\n* 11 gold 10 silver \r\n==The Final Challenge==\r\n''Main article: [[Quest:The Ring of Blood: The Final Challenge|The Final Challenge]]''\r\nAfter defeating the champion, Gurgthock's final challenge is the [[ogre]] that has been watching you all along. [[Mogor, Hero of the Warmaul]] decides to fight you last. Once he is killed the first time he will reincarnate and fight you again.\r\n'''Rewards'''\r\n* 11 gold 10 silver \r\n* Mogor's Anointing Club\r\n* Staff of Beasts\r\n* Mag'hari Fury Brand\r\n* Honed Voidaxe\r\n* Battle Mage's Baton\r\n* Ceremonial Warmaul Blood-blade",},
			["Ring of Law"] = { content = "'''Ring of Law''' is an encounter at the [[Ring of the Law]] in [[Blackrock Depths]], overseen by [[High Justice Grimstone]].\r\nThe event is started when a player stands on the mesh circle at the center of this area. The entrance to the ring is closed, and High Justice Grimstone appears in the ring. This dark iron dwarf is flagged red, but cannot be attacked; his purpose is to explain what is about to happen.\r\n==Adventure Guide==\r\n''There is only one punishment for crimes committed against the Dark Iron dwarves: death. Ancient tradition calls for the guilty to pay the blood price in the Ring of the Law by battling savage creatures gathered from across Azeroth. To date, it is unknown if anyone has ever survived this brutal crucible.''\r\n==Abilities==\r\n** \r\n*** Burrowing Thundersnout\r\n*** Borer Beetle\r\n*** Deep Stinger\r\n*** Dark Screecher\r\n*** Dredge Worm\r\n*** Cave Creeper\r\n** \r\n*** Grizzle\r\n*** Anub'shiah\r\n*** Eviscerator\r\n*** Ok'thor the Breaker\r\n*** Hedrum the Creeper\r\n*** Gorosh the Dervish\r\n==Alternate Ring of Law battle==\r\n''NOTE: Only players who completed the requisite quest prior to its removal in [[Cataclysm]] and did not destroy their Banner of Provocation are still able to initiate this alternate encounter.''\r\nThe alternate boss-fight was a quest in the [[Dungeon_Set_2|Dungeon 2 set upgrade questline]] which asks the player to kill a dwarf named [[Theldren]] and his gladiators in order to retrieve the [[Top Piece of Lord Valthalak's Amulet]]. To do this, just go in the arena, use the [[Banner of Provocation]] (must be placed near the center of the arena) while High Justice Grimstone is \"sentencing\" you, and destroy all the mobs that come out of the gates. On the second wave, where a boss should have arrived, Theldren and some random gladiators will appear instead. \r\nDo not forget to get the Top Piece of Lord Valthalak's Amulet from Theldren.\r\nThese mobs behave like a PvP group which may include mages, healers, a hunter with a pet, rogues, a dynamite tossing goblin and always Theldren himself, who is a warrior. For more information, see [[Theldren]]'s page. They are immune to taunts, so they will likely go for any healers in the player's group. [[Crowd control]] is a must in order to win this battle unless the group have a high-level player to help them.\r\nThe completion of the event spawns a box of loot. In addition, you get to keep the banner in case you want to get the loot again in the future.\r\n===Loot of note===\r\nIf Theldren is killed, an [[Arena Spoils]] chest appears. One of these items will be inside it:\r\n*[[Ironweave Mantle]]\r\n*[[Shroud of Arcane Mastery]]\r\n*[[Lefty's Brass Knuckle]]\r\n*[[Malgen's Long Bow]]",},
			["Ring of Observance"] = { content = "The '''Ring of Observance''' is the inner cloister of the ruined draenei necropolis of [[Auchindoun]]. It is here - accessed either by flight, the ramps leading from the Bone Wastes, or by being summoned via the [[meeting stone]] - that players gather to access the four instance wings of Auchindoun.\r\n==Location==\r\nContinent: [[Outland]]\r\n \r\nRegion: [[Terokkar Forest]] \r\n==Quests For==\r\n'''[[Mana-Tombs]]'''\r\n[[Artificer Morphalius]]\r\n*Safety Is Job One\r\n**Someone Else's Hard Work Pays Off\r\n[[Nexus-Prince Haramad]]\r\n*Undercutting the Competition\r\n'''[[Auchenai Crypts]]'''\r\n[[Greatfather Aldrimus]]\r\n*Everything Will Be Alright\r\n'''[[Sethekk Halls]]'''\r\n[[Isfar]] \r\n*Brother Against Brother\r\n*Terokk's Legacy\r\n'''[[Shadow Labyrinth]]'''\r\n[[Spy Grik'tha]]\r\n*Find Spy To'gun\r\n**The Soul Devices\r\n[[Field Commander Mahfuun]]\r\n*The Codex of Blood\r\n**Into the Heart of the Labyrinth\r\n'''Vendors'''\r\n*[[\"Slim\"]] <shady dealer>\r\n*[[Provisioner Tsaalt]]\r\n*[[Dealer Tariq]]\r\n==Related Articles==\r\n*[[Auchindoun]]\r\n*[[Mana-Tombs]]\r\n*[[Auchenai Crypts]]\r\n*[[Sethekk Halls]]\r\n*[[Shadow Labyrinth]]",},
			["Ring of Silver Might"] = { content = "==Source==\r\nThis item is crafted by [[jewelcrafting|jewelcrafters]] with a skill level of 80.",},
			["Ring of the Law"] = { content = "The '''Ring of the Law''' is located inside [[Blackrock Depths]]. It is accessed through the [[Halls of the Law]] just beyond the [[Detention Block]].\r\nWhen a player stands on the mesh circle at the center of this area, it starts a plot event. The entrance to the ring is closed, and [[High Justice Grimstone]] appears in the ring. This dark iron dwarf is flagged red, but cannot be attacked; his purpose is to explain what is about to happen.\r\nHe releases three waves of non-elite monsters, and then an elite mini-boss. The type of monsters and specific mini-boss which appear vary randomly between several alternatives.\r\nMonsters: varies. Bats, scorpions, worms, and slimes are all possible.\r\nMini-Bosses: [[Anub'shiah]], [[Eviscerator]], [[Gorosh the Dervish]], [[Grizzle]], [[Hedrum the Creeper]], or [[Ok'thor the Breaker]].\r\nOnce the players are victorious in the ring, the ring's entrance reopens, and a second gate also opens, leading to the ring's upper levels and the rest of the instance. The arena spectators on the upper level are normally hostile, but become neutral when the ring event is won.\r\nThe Ring of the Law event can be bypassed via the west garrison side door, which can be opened with the [[Shadowforge Key]] or by lockpicking (skill 250) or its alternatives.\r\nThe stairs leading up through the opened gate leads to the [[East Garrison]], [[West Garrison]], and the [[Shrine of Thaurissan]].\r\n===Alternate Ring of the Law battle (0.5 upgrade quest chain)===\r\nThis is the Dungeon 2 set upgrade task to kill Theldren's Army and retrieve the Top Piece of Lord Valthalak's Amulet. To do this, just go in the arena, use the banner while the dwarf is \"sentencing\" you, and destroy all the mobs that come out of the gates.\r\nNOTE: Do not forget to get the Top Piece of Lord Valthalak's Amulet from Theldren.\r\nThese mobs behave like a pvp group with a mage, healer, warrior, rogue, and sometimes a dynamite tossing goblin. Can't taunt them so they go for healers. Not too hard if done with a mage. Every enemy who fights with theldren is immune to a warrior's taunt, so crowd control is a must.\r\nThe completion of the event spawns a box of loot and you get to keep the banner in case you want to get the loot again in the future.\r\n====Loot of note====\r\nIf Theldren is killed, an [[Arena Spoils]] chest appears. Rare loot includes:\r\n*Ironweave Mantle\r\n*Shroud of Arcane Mastery\r\n*Lefty's Brass Knuckle\r\n*Malgen's Long Bow",},
			["Ring of Trials"] = { content = "'''Ring of Trials''', also called the '''Nagrand Arena''', is located in [[Nagrand]], southeast of [[Garadar]]. It used to be an ancient orcish proving ground. This arena supports up to 5 players on each side. \r\nThis arena is an open field with 4 supporting columns near the middle. The starting areas are opposite each other. Like all arenas, after five minutes, two [[Shadow Sight]] power ups would appear that let the user see stealthed and invisible characters; however, it also does a little damage to the user. \r\n==Notes==\r\nPrior to Patch 2.1, a cyclone would appear one minute into the fight and randomly spin into players, slowing and damaging them.",},
			["Ring of Twilight Shadows"] = { content = "==Source==\r\nThis item can be acquired through crafting or another combine-type effect.",},
			["Ring of Valor"] = { content = "The '''Ring of Valor''' is located in the [[Valley of Honor]] in [[Orgrimmar]].\r\nThe Ring of Valor is a massive gladiatorial arena. Here warriors fight to honor the [[Horde]], not for the amusement of bloodthirsty crowds. Young [[orcs]] practice here with blunted weapons, but occasionally fight to severe injury or death.\r\n==Purpose==\r\nIt was supposed to serve the same purpose as the [[Gurubashi Arena]], except there would be no treasure in the middle. On the , under one of the guides, it's clearly stated that each alliance has a city arena to [[PvP]] against the players of the same [[Faction]]. This feature is still not implemented, so for now, the Ring of Valor doesn't serve any game purpose.\r\nInformation pasted from :\r\n'''''Player-vs.-player combat areas''''' - Players thirsty for a bit of friendly competition can try out their swords and spells on each other in the combat arenas located in the cities. What better way to hone one's skills than against a fellow player?\r\nThis place could have been used for [[RP]] reasons or a staging area, however it is not possible to enter the ring itself, just the stands.\r\n==Arena==\r\nThe '''Orgrimmar Arena''' is an arena located in the [[Valley of Honor]] of [[Orgrimmar]] in [[Durotar]]. It replaces the currently unused [[Ring of Valor]]. It has a larger \"scale\" and will be the first and only arena designed to allow [[mount]]s.\r\n[[Line of sight]] will be handled differently compared to [[Dalaran Arena]]. There will be two pillars in the arena, moving up and down on timers to block line of sight. There will also be two sets of spikes on triggers for when the pillars move, which will deal damage and also block line of sight. A player can stand on the pillars and move up and down with them to escape melee combat. Players will be forced into decisions of taking damage from spikes for waiting in order to get to opponents.\r\nPlayers will be hidden during the waiting period, but start 10 yards next to each other as lifts bring them up through the floor. Spikes will surround the lifts for a few seconds before coming down, so you can see your opponents and react just before the fight starts.\r\n===Overview===\r\nThe Ring of Valor includes multiple sets of dynamic map features that create a variety of opportunities for pitched, fast-paced combat.\r\n====The Staging Platforms====\r\nThe staging areas in the Ring of Valor are not the standard sheltered rooms at opposite ends of the Arena. As the pre-match countdown progresses, the two staging areas slowly rise out of the ground until they emerge at ground level, mere yards apart. When the match begins, the gates around the platforms retract, and the two teams find themselves in very close proximity.\r\n====The Fire Walls====\r\nOn either side of the staging platforms is an intermittent fire wall that blasts from the ground. The two fire walls trigger at the same time and inflict damage equal to a percentage of total health per second to anyone passing through or standing within the flames. The walls do not otherwise break line of sight or inhibit player movement.\r\n====The Elevating Platforms====\r\nTwo roughly circular platforms at opposite ends of the Arena rise and lower throughout the match, obstructing movement and blocking line of sight when raised. Because they are essentially temporary pillars, they create an ever-changing dynamic of line-of-sight and kiting opportunities.\r\n===Map Walkthrough===\r\nDue to its array of unique features, the Ring of Valor is the most complex and dynamic of all the Arenas in World of Warcraft thus far, and it will likely give rise to some of the most creative and active player strategies yet seen. In general, teams that combine constant, coordinated movement with opportunistic use of the platforms and fire walls will rule the day.\r\nOne key element of the Arena that teams should use to their benefit is the timing of the fire walls and platforms. The elevating platforms rise and lower in sync with the fire walls' activation and deactivation. When the platforms are lowered, the fire walls cut off that section of the Arena. Thus, players who are cut off from teammates or targets due to the fire wall's activation must quickly decide whether to wait out the duration or to suffer the high damage cost of running through the wall. Using the platform to kite or block line of sight is no longer an option in that case.\r\nTeams that quickly identify when opposing players are cut off from support can rapidly burn those isolated players down, and so coordinated burst DPS will be a boon. Similarly there will be a greater need for and emphasis on healing, for the extra damage from the fire walls will take its toll. Keeping teammates alive through the match's initial frenzy will be a singular healing challenge as well, for the teams will likely be trading blows in close quarters while simultaneously establishing position.",},
			["Rinling"] = { content = "'''Rinling''' is a level 55 [[quest giver]] located in in the [[Darkmoon Faire]] camp, which is only available during the monthly Darkmoon Faire event. On even months, it is south of [[Goldshire]] in the [[human]] starting zone of [[Elwynn Forest]]. On odd months, it is southwest of [[Thunder Bluff]] in the [[tauren]] starting zone of [[Mulgore]].\r\nRinling has to keep a smile on your face, or he has to cut off his hand and eat no flesh until it regenerates. He also like collecting [[engineering]] stuff, to make his tent better.\r\nHe starts the following quests:\r\n* Copper Modulator\r\n* Green Fireworks\r\n* Mechanical Repair Kits\r\n* Thorium Widget\r\n* More Thorium Widgets (Repeatable)\r\n* Whirring Bronze Gizmo\r\nSee [[List of Elwynn Forest NPCs]] and [[List of Mulgore NPCs]].",},
			["Rip"] = { content = "''Just when you thought it couldn't get any worse...''\r\n'''Rip''' serves to clear all [[combo points]] and inflict a strong [[DoT|Damage Over Time]] on the target.\r\n==Rank Table==\r\n(Combo) refers to the amount of combo points on the target when the ability is used.\r\nAP is the player's attack power.\r\n==Notes==\r\n*The target must have at least one combo point on them in order to be able to use this ability.\r\n*As described by the tooltip, Rip damage is affected by attack power per combo point. Empirical data gathered by player Staralfur in patch 2.0 suggests these calculations:\r\nRip(5) 942 + .24*AP\r\nRip(4) 774 + .24*AP\r\nRip(3) 606 + .18*AP\r\nRip(2) 438 + .12*AP\r\nRip(1) 270 + .06*AP\r\n==Tips and Tactics==\r\n*This is a great \"finishing move\" for the harder enemies that are only half dead when you get 5 combo points on them.\r\n*This is considered a bleed effect. Bleed effect damage is not reduced by armor.\r\n*Rip gains a 30% bonus to damage if [[Mangle]] is on the target.\r\n==Past changes==\r\n* Prior to version 1.12, Attack Power did not factor into the damage of a Rip.\r\nStarting in version 1.12, Attack Power adds into the damage caused by a Rip. To balance this addition, the base damage was reduced.\r\n* Before Patch 2.4, all [[Mechanical]], most [[Elemental]]s, and some [[Undead]] enemies were immune to bleed effects. They no longer are.",},
			["Ripfang Paw"] = { content = "==Source==\r\nThis item is a quest reward from Declawing Doomclaw.",},
			["Riplash Ruins"] = { content = "Found at the southern most portion of the [[Borean Tundra]], the '''Riplash Ruins''' are ruins from the ancient [[Nerubian]] empire. \r\nThe old ruin stands at the tundra’s south end — the southern tip of [[Northrend]]. From its architecture it appears to be nerubian except that it’s mostly above ground. There may have been an earthquake long ago, possibly the result of magma beneath, which uplifted this section of [[Azjol-Nerub]] up to the surface. Regardless, nerubians aren’t there now, and a pack of naga moved in some time ago. They’re nasty and attack anyone who gets within range. From here the [[Naga]] seek to flood the region by melting the icecaps. \r\nIn [[Wrath of the Lich King]] the ruins have now been described as a ancient [[night elf]] city and not a section of Azjol-Nerub.",},
			["Riptide"] = { content = "'''Riptide''' is the 61 point talent in the [[Shaman]]'s [[Shaman talents|Restoration]] tree.",},
			["Risen Aberration"] = { content = "'''Risen Aberration''' can be found in [[Scholomance]] .\r\n==Drops == \r\n \r\n0.10% Chance of a [[rare]] drop.\r\n0.40% Chance of an [[Uncommon]] drop.\r\n0.05% Chance of a [[common]] drop.\r\n0.16% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Risen Bonewarder"] = { content = "*Type:Undead\r\n*Level:59-60 (elite)\r\n*Found:[[Scholomance]]\r\nThe Bonewarders are found with [[Lady Illucia Barov]]. They are not hard to kill and have nearly no armour.\r\nSpells they cast:\r\n[[Drain Life]], drains 200 health per sec for 5 secs.\r\nBone Armour, caster is shielded for a certain amount of damage for 15 secs.\r\nConsuming Shadows,deals 200 damage per second and reduces movement speed by 30% to the target (channeled spell for 10 secs)\r\n===Strategy===\r\nYou don't really need to carefully kill them slowly, they ae quite fragile, so just blast away. Keep piling the damage on them and they will fall. Silence them when they cast Drain Life.",},
			["Risen Construct"] = { content = "*Type: Undead\r\n*Level: 58-60 (elite)\r\n*Found: [[Scholomance]]\r\n'''Risen Constructs''' are [[bone golem]]s found near [[Rattlegore]]. They have lots of health and powerful melee attacks, so casters stay back.\r\nSpells they cast:\r\n[[Cleave]]\r\n===Strategy===\r\nNothing much to do, just pile on the damage onto them and watch out for their [[Cleave]] spell. It deals absurd amounts of damage to casters.",},
			["Risen Hungerer"] = { content = "'''Risen Hungerer''' can be found in [[Ghostlands]] .\r\n==Quests== \r\n==Drops == \r\n \r\n0.18% Chance of an [[Uncommon]] drop.\r\n0.07% Chance of a [[common]] drop.\r\n0.06% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Risen Protector"] = { content = "'''Risen Protector''' can be found in [[Scholomance]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.13% Chance of a [[rare]] drop.\r\n1.13% Chance of an [[Uncommon]] drop.\r\n0.10% Chance of a [[common]] drop.\r\n0.42% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Risen warrior"] = { content = "#redirect [[Risen Warrior]]", redirect = "Risen Warrior",},
			["Rise of the Blood Elves"] = { content = "'''\"Rise of the Blood Elves\"''' is a section of the [[History of Warcraft]], Chapter V. It recounts events of the Alliance campaign of ''[[Warcraft III: The Frozen Throne]]''.\r\nFound at:\r\n* [[Darnassus]] in [[Craftsmen's Terrace]] .\r\n* [[Hammerfall]] in [[Arathi Highlands]] - Inn.\r\n* [[Scholomance]] in the [[Western Plaguelands]].\r\n* [[Tower of Azora]] in [[Elwynn Forest]] .\r\nTimeline: \r\n* ← Previous book: [[The Betrayer Ascendant]]\r\n* → Next book: [[Civil War in the Plaguelands]]",},
			["Rise of the Blood Elves"] = { content = "'''\"Rise of the Blood Elves\"''' is a section of the [[History of Warcraft]], Chapter V. It recounts events of the Alliance campaign of ''[[Warcraft III: The Frozen Throne]]''.\r\nFound at:\r\n* [[Darnassus]] in [[Craftsmen's Terrace]] .\r\n* [[Hammerfall]] in [[Arathi Highlands]] - Inn.\r\n* [[Scholomance]] in the [[Western Plaguelands]].\r\n* [[Tower of Azora]] in [[Elwynn Forest]] .\r\nTimeline: \r\n* ← Previous book: [[The Betrayer Ascendant]]\r\n* → Next book: [[Civil War in the Plaguelands]]",},
			["Rise of the Defiler"] = { content = "The '''Rise of the Defiler''' is a craggy set of mountains placed near the middle of the [[Blasted Lands]]. They are the home to the great demon, [[Razelikh]].",},
			["Rise of the Horde"] = { content = "'''Rise of the Horde''' is a novel by [[Christie Golden]] focusing on the events of the [[History of the Horde|Horde]] and its culture in the Warcraft universe.\r\n[[Chris Metzen]] himself commented on the book, which features the [[draenei]]'s flight from [[Argus]] and, as the title implies, the corruption of the [[orc]]s. \r\n''\"The book DOMINATES, and you're going to really dig it. [[Durotan]], [[Ner'zhul]], [[Gul'dan]], [[Doomhammer]], [[Grom Hellscream|Hellscream]], [[Kil'jaeden]], [[Velen]]; this story is the one you've been waiting for. I'm getting geeked up just thinking about it.\"''\r\nThe book is written from the 3rd-person perspective, except for a note every chapter, narrated by [[Thrall]] in the first person. Most of the story is told from the perspective of Durotan and Velen.\r\nThe book finally answers questions relating to Ner'zhul, the massacre of the draenei, the true color of orcish skin, and [[daemon]]s. It is notable for painting a much more sympathetic picture of Ner'zhul than previous lore, showing him as a generally good-hearted but deceived and somewhat ineffectual leader.\r\nThough the orc on the cover is almost certainly [[Grom Hellscream]], he only appears briefly in the novel.\r\nA number of plot elements introduced in ''Rise of the Horde'', such as [[Oshu'gun]], the [[Ata'mal crystal]] and the [[Throne of Kil'jaeden]], were developed solely by Golden, but the lore department at Blizzard liked them so much that they included these elements in ''The Burning Crusade''.\r\n==Major characters==\r\n(In order of appearance)\r\n* [[Velen]]\r\n* [[Kil'jaeden]]\r\n* [[Thrall]] (narrator)\r\n* [[Durotan]]\r\n* [[Orgrim Doomhammer]]\r\n* [[Draka]]\r\n* [[Drek'Thar]]\r\n* [[Ner'zhul]]\r\n* [[Gul'dan]]\r\n* [[Blackhand]]\r\n===Minor characters===\r\nThough the following individuals play larger parts later in Warcraft, they have minor parts in ''Rise of the Horde'':\r\n* [[Archimonde]]\r\n*[[Mannoroth]]\r\n* [[Grom Hellscream]]\r\n* [[Kargath Bladefist]]\r\n* [[Kilrogg Deadeye]]\r\n* [[Rend Blackhand|Rend]] son of Blackhand\r\n* [[Maim Blackhand|Maim]] son of Blackhand\r\n* [[Griselda]], daughter of Blackhand\r\n* [[Medivh]]\r\n====Other minor characters====\r\n*[[Garad]]\r\n*[[Ghun]]\r\n*[[Grekshar]]\r\n*[[Guthor]]\r\n*[[Mother Kashur]]\r\n*[[Kur'kul]]\r\n*[[Rokkar]]\r\n*[[Rulkan]]\r\n*[[Tal'kraa]]\r\n* [[Telkar Doomhammer]]\r\n*[[Urukal]]\r\n*[[Krol]]\r\n* [[Restalaan]]\r\n* [[Larohir]]\r\n*[[Talgath]]\r\n*[[Nightstalker (wolf)|Nightstalker]]\r\n*[[Skychaser (wolf)|Skychaser]]\r\n==See Also==\r\n*[[Rise of the Horde (History of Warcraft)]]",},
			["Rise of the Horde (History of Warcraft)"] = { content = ":''For the book by [[Christie Golden]], see [[Rise of the Horde]].''\r\n'''\"Rise of the Horde\"''' is a section of the [[History of Warcraft]], Chapter III. \r\nFound at:\r\n*The [[Hall of Explorers]] in [[Ironforge]].\r\n*[[Tiragarde Keep]] in [[Durotar]].\r\n*[[Stonard]] in [[Swamp of Sorrows]] - building with the trainers\r\nTimeline: \r\n* ← Previous book: [[Kil'jaeden and the Shadow Pact]]\r\n* → Next book: [[The Dark Portal and the Fall of Stormwind]]",},
			["Rise of the Silithid quest chain"] = { content = "... wherein you investigate the infestations of insect life arising in Tanaris, and find a threat to all [[Azeroth]].\r\nThis series of quests is available to both [[Horde]] and [[Alliance]]; the\r\ndifferences being to whom you report the news. Also note that there is a\r\nlevel gap between Rise of the Silithid and\r\nMarch of the Silithid which may make the second half of the chain\r\ntemporarily unavailable.\r\n==Part 1: Rise of the Silithid==\r\n*'''Gadgetzan Water Survey'''\r\n[[Senior Surveyor Fizzledowser]] is looking for assistants to go looking for\r\nwater sources for [[Gadgetzan]]. It seems that the nomads have been seizing\r\nall the wells, and he is looking to find more water sources. The pay sounds\r\ngood, the work easy, so you volunteer.\r\nFizzledowser hands you a dowsing widget, and asks you to head to a pool\r\nnear the troll-held [[Sandsorrow Watch]]. You find the pool. Carefully\r\navoiding the trolls, you use the dowser. But your sampling is interrupted\r\nby a couple of pony-sized insects burrowing out of the ground at your\r\ndisturbance.\r\nYou return with the dowsing results. Fizzledowser apologizes for not\r\nmentioning the possibility of the insects, as he had thought them mere\r\ninventions of the nomads to cover their water thefts. Now he knows better.\r\n*'''Noxious Lair Investigation'''\r\nAnd knowing your foe is the first step to being able to control or defeat\r\na threat. Fizzledowser asks you to go to the [[Noxious Lair]] and bring back\r\nenough parts for [[Alchemist Pestlezugg]] to investigate.\r\nWhile you can get plenty of parts (carefully - those are bad bugs), getting\r\n''useful'' parts take a bit longer. Still, you manage it. You return with\r\nthe parts to the alchemist, who tells you that Fizzledowser has had some\r\nemergency come up that he'd like your help with. The analysis will take\r\nsome time anyway; you have time.\r\n*'''The Scrimshank Redemption'''\r\nFizzledowser, it turns out, had sent his top assistant, one Junior Surveyor\r\nScrimshank, out to [[Gaping Chasm]], and he's gone missing. Fizzledowser\r\nwould like you to go out and find out what happened to him. Rescue him\r\nif he's still alive, or at least retrieve his equipment.\r\nYou don't find sign of him anywhere on the surface, so you head into the nest.\r\nQuite some distance in, you find what is left of his survey equipment, where\r\nthe bugs probably stored it.\r\n*'''Insect Part Analysis (1)'''\r\nYou return the survey equipment to Fizzledowser. He asks you to check in with\r\n[[Alchemist Pestlezugg]] to see if he's got results from those parts you gave\r\nhim.\r\nHe does indeed, it turns out. Those results seem to confirm that the bugs are\r\nbeing controlled by some outside force, and a pretty malign one at that.\r\n*'''Insect Part Analysis (2)'''\r\nPestlezugg insists that Fizzledowser needs to see this immediately. Not only\r\nthat, but he feels you should show the report to anyone you can get to sit\r\ndown and read it. The threat, he says, is not only to Tanis and Gadgetzan, but\r\nto all of Southern Kalimdor, possibly to the whole of Azeroth.\r\nSharing (for free) does not come naturally to Senior Surveyor Fizzledowser, but\r\nPestlezugg is a long time associate, and he trusts the alchemist's judgement.\r\n*'''Rise of the Silithid (Horde) /Rise of the Silithid (Alliance)'''\r\nThe Senior Surveyor urges you to take the report to a scholar who has studied\r\nthis sort of thing. \r\n*Alliance members are directed to [[Gracina Spiritmight]], a night elf scholar living at the [[Temple of the Moon]], in [[Darnassus]].\r\n*Horde members are directed to [[Zilzibin Drumlore]], a troll scholar living in the [[Drag]] in [[Orgrimmar]].\r\nThe scholar you are sent to agrees with Fizzledowser, that this threat is real\r\nand serious, to both Alliance AND Horde.\r\nThey even have a name for it: [[Silithid]].\r\n==Part 2: March of the Silithid==\r\n*'''March of the Silithid'''\r\nYour scholar contact asks you to return to [[Alchemist Pestlezugg]] in\r\n[[Gadgetzan]] and relay to him that he believes the direction is coming from\r\n[[Un'Goro Crater]].\r\nPestlezugg is very glad for your experience fighting the Silithid. He's a\r\nlittle less sure that Un'goro is the ultimate source, but it's a start.\r\n*'''Bungle in the Jungle'''\r\nThe alchemist asks you to venture into Un'Goro and retrieve an intact scent\r\ngland from one of the Silithid, as well as several samples of the native\r\nUn'Goro soil. He believes that if the Queen can be drawn out of hiding\r\nand slain, the rest of the hive will be disrupted.\r\nThe soil you find easily enough. Clods of it stick to your shoes all the time.\r\nThe scent gland is a bit more difficult, as the process of killing the bug\r\noften renders the gland unusable. Still, you manage, and return with the\r\nparts.\r\n*'''Pawn Captures Queen'''\r\nPestlezugg brews up the lure and advises you on how to use it. Somewhere in\r\nthe hive, he says, is a crystal that they use for communication. Putting the\r\nlure near the crystal should draw the queen - and her bodyguards - out where\r\nyou can get to her.\r\nYou venture into [[The Slithering Scar]] in [[Un'Goro Crater]], and find a\r\nhive much smaller than either of the ones you found earlier. You find the\r\ncrystal Pestlezugg mentioned fairly easily and lay out the lure.\r\nAs hoped for, the queen comes out. And as predicted, a number of bodyguards\r\naccompany her. With some assistance, you finally manage to dispatch them.\r\nAs requested, you slice out the queen's brain, and bring it back to Pestlezugg\r\nfor analysis.\r\n*'''Calm Before the Storm (Horde 1) /Calm Before the Storm (Alliance 1)'''\r\n[[Alchemist Pestlezugg]] puts together another report, on the events in\r\nUn'Goro, and asks you to return to your scholar with it, and asks you to pass\r\non the request for more aid.\r\n... and disconcertingly, the scholars on both sides are similarly frustrated.\r\nThe leadership of both the Horde ''and'' the Alliance are so fixated, each\r\nupon the other, that they are almost certain to ignore this threat.\r\n*'''Calm Before the Storm (Horde 2) /Calm Before the Storm (Alliance 2)'''\r\nYour scholar contact thanks you, but warns that you are certain to be called\r\nupon again some time soon, to assist against the [[Silithid]] further. The\r\nresults from your foray show that instead of being directed from Un'Goro,\r\nthere exists a far stronger presence elsewhere.\r\nIn the mean time, she presents you with a note to take to an agent at the\r\nbank. You present the note, and are given an item from\r\nthe scholar's vault as a token of gratitude.\r\n==Rewards==\r\nOver the course of the chain, you earn amazing amounts of faction:\r\n* +850 [[Alliance]]/[[Horde]]\r\n* +1160 [[Gadgetzan]]\r\n* +250? [[Steamwheedle Cartel]]\r\n* +10 [[Darnassus]]/[[Orgrimmar]]\r\nYou also earn\r\n* 38300 XP in quest completion awards\r\n* 1 gold 55 silver \r\n==Notes==\r\nThis chain introduces you to plot line of [[Silithus]], a region where the\r\ninsects have built great nests and the [[Cenarion Circle]] struggles to\r\nmaintain even a minimal base there.\r\n==Summary==\r\n</noinclude>",},
			["Rite of Strength"] = { content = "==Objectives==\r\nKill Bristlebacks in Brambleblade Ravine and bring 12 Bristleback Belts to [[Chief Hawkwind]] in [[Camp Narache]].\r\n*[[Bristleback Belt]] (12)\r\n==Description==\r\nThe Rites of the Earthmother are the steps a young tauren needs to take to gain respect in [[Thunder Bluff]].\r\nFirst you must pass the Rite of Strength. In this test you must prove your bravery by slaying enemies of the tribe.\r\nBristlebacks of [[Brambleblade Ravine]] to the east are encroaching on our tribal lands. They ambush our hunting parties and steal from the village by dark.\r\nShow your valor by slaying these villains and return to the Chief in [[Camp Narache]] with their belts as proof of your deeds.\r\n==Rewards==\r\nYou will also receive:\r\n*450 [[XP]] (or 2 silver 70 copper at max level)\r\n*+350 [[reputation]] with [[Thunder Bluff (faction)|Thunder Bluff]]\r\n==Progress==\r\nHave you completed the Rite of Strength, <name>? I require proof of your valor against the enemy of our tribe, the Bristlebacks.\r\n==Completion==\r\nYou have passed the first test of the Rites of the Earthmother. The tribe will be proud.",},
			["Rite of Wisdom"] = { content = "==Objectives==\r\nTravel to [[Red Rocks]] east of [[Thunder Bluff]] and speak with the [[Ancestral Spirit (NPC)|Ancestral Spirit]].\r\n==Description==\r\nTo gain acceptance amongst the elders of Thunder Bluff you must next complete the Rite of Wisdom.\r\nNow that you have passed the Rite of Vision, the ancestral spirits of Red Rocks will give you the blessing of our ancestors. Only those who have drunk from the Water of Seers can gain the blessing.\r\nTravel east of Thunder Bluff, to Red Rocks and seek out the Ancestral Spirit, <name>.\r\n==Rewards==\r\nYou will receive:\r\n* 840 [[XP]]\r\n* +100 reputation with [[Thunder Bluff (faction)|Thunder Bluff]]\r\n==Completion==\r\nYou have shown great diligence in your yearning to pass the Rites of the Earthmother, <name>.\r\nWe, the Ancestral Spirits, represent the mighty <race> who gave their lives bravely to found and protect our great city of Thunder Bluff. I hereby pass the duty of that protection over to you.\r\nYou have passed the Rite of Wisdom, young <class>. Enter Thunder Bluff with pride.\r\n==Notes==\r\n*Red Rocks is in the mountains directly east from Thunder Bluff. The Ancestral Spirit is in an old [[Tauren]] graveyard. The graveyard is guarded by [[gnoll]]s.",},
			["Ritual of Doom"] = { content = "''\"When it comes to the absolute power of a Doomguard, no friend's life is worth more than the raw demonic energy of the horror about to leave the Twisting Nether.\" ''\r\n'''Ritual of Doom''' is a [[Warlock]] spell that sacrifices a party member for the benefit of summoning a [[Doomguard (Warlock pet)|Doomguard]].\r\nLearned from a Grimoire of Doom or Suppression.",},
			["Ritual of Summoning"] = { content = "'''Ritual of Summoning''' is designed to [[Summon|summon]] a non-present [[Party|party]] member to the [[Warlock|warlock]]'s location. The [[Spell|spell]] requires 2 other party members present, which can be of any class, and the summoning consumes a [[Soul Shard]] when accepted.\r\nThe warlock begins the ritual by casting Ritual of Summoning, which opens a portal. The other 2 present party members (without moving) then right-click on the portal to concentrate on it. Once the portal is ready, the targeted party member has 2 minutes to accept the summoning, and if accepted, will be teleported to the portal's location. Summoning can be accepted while in flight, but not while in combat (if the summoned player drops out of combat during the two-minute time period, he can still accept the summon; the Accept button is merely grayed out until then). \r\nThe warlock can determine if the spell was accepted by watching the soul shard count. If the targeted player receives the summon and clicks to accept it, the shard count decreases. If the player does not receive the summon or cancels it, the shard count remains the same. Ensuring that the shard count decreases allows for very quick summons of large groups.\r\nThe targeted player will be teleported to the location where the portal appeared.\r\nA warlock can target him or herself as the summoning target in order to quickly hearth, repair, and quickly return back to the spot the ritual was performed. This works inside of an instance as long as the warlock meets the requirements for the instance.\r\n==Limitations==\r\nA Warlock (with two party members standing with the Warlock to assist - this always applies except when using a [[Meeting Stone]]), can summon from anywhere in Azeroth or Outland to wherever the Warlock is, whether it be in Azeroth, Outland or the Warlocks instance, however only if the summoned player is within the level restriction of the instance.\r\nBecause parts of the [[Netherstorm]] zone are impossible to access without a flying mount, Blizzard initially made it impossible for Warlocks to summon inside the zone. The lore reason for this was that Netherstorm's chaotic energies make summoning magically impossible. As of patch 2.4 this restriction has been lifted",},
			["Rival Nations"] = { content = "Rival Nations is a custom map for [[Warcraft III]] in which there are three teams of three, pitted against each other in a free-for-all [[AoS|Aeon of Strife]] format. Each player begins the game with one hero of their choosing, and battles computer controlled armies until becoming powerful enough to destroy the opposing teams' Castle. The biggest difference between Rival Nations and other AoS styled maps is that in Rival Nations you are able to purchase and control more than one hero. This leads to increased strategy and micro requirements in order to be victorious. Started in the summer of 2002, it was developed by [[MicrosoftXP]] until June 2004. The last version released by MicrosoftXP was x2.0b for [[Warcraft_III:_The_Frozen_Throne|The Frozen Throne]]. After a few months [[AwaKening]] took over development. The map was renamed to 'Rival Nations Reborn' and is currently at version 1.03d as of 2007-03-13.\r\n==Features==\r\nRival Nations pioneered a number of features now seen frequently in custom maps. Unfortunately there are so many features, that the learning curve of the map is quite steep and does not lend itself well to new players versus more experienced ones. This is perhaps the greatest flaw of the map and the biggest reason why it has gone down considerably in popularity.\r\n===Feature List===\r\n* Multiple Hero control and combat\r\n*: (see multiple heroes section below)\r\n* Free-for-all gameplay\r\n*: some people like free-for-all, some don't. In Rival Nations it can make every game unpredictable and challenging even for the best of players. It allows weaker teams who might not stand a chance in a 1v1 vs another team the strategic option to focus on the stronger team and possible overpower them with the help of the 3rd team. A very few of the most elite players who have a reputation for being very good would typically be double teamed. And if their skill was great enough, they may still be able to overcome both teams.\r\n* Bounty System\r\n*: the bounty system is what determines the reward that a player gains for killing another player's hero in battle. It is influenced by various things, but largely reflects how a player has been doing in the current game. The better the player has been doing, the larger their bounty and vise versa. The system was designed to keep the game interesting from start to finish as it provided a means by which a losing team can gain a significant advantage and turn the tables. Many a game has been headed in one direction, however a few hero kills on a high bounty player later and the game can turn on a dime.\r\n* Taunting\r\n*: taunts are a selection of sound clips from the game such as the Far Seer's \"Outlook not so good,\" or the Blade Master's \"My blade can cut through armor, and still slice a tomato.\" They can be directed a player by typing -taunt <player color> and they occasionally happen automatically when one player kills another's hero.\r\n* Set Items\r\n*: its not accurate to claim this as an original concept, as it was most likely copied from the Diablo games, however it was one of the first to implement a Set Item bonus for certain items (the Dragon Set).\r\n* Moving Shops\r\n*: there is a traveling merchant which sells rare and . His inventory is randomly generated from a list of 20-30 items each time he appears in a team's base. He stays for a few minutes then gets into a zeppelin and heads to another random base. He also has a wagon, from which even more powerful items may be .\r\n* Gambling\r\n*: some of the most powerful items available in the map were not even sold in shops had to be gained by gambling. The odds of getting a particularly rare item could be as low as 1 in 800. \r\n* Upgrades\r\n*: Rival Nations has a very rich , in which everything from unit strength/armor to increased/custom units to unlocking attack upgrades for units could be attained. In addition, some upgrades provided other miscellaneous advantages such as increased building strength, an improved fountain of healing, magic sentry and temporary building invulnerability.\r\n* Trainers\r\n*: special units can be purchased which will give a town increased troop production. These units are called trainers and should be placed next to a barracks to increase production at that barracks. Some players like to mass trainers and attempt to overwhelm their enemies. Sometimes this can work, particularly if they can destroy their enemies' barracks, however versus more experienced players, it can merely serve to fuel their income.\r\n* Ending Sequence and Awards\r\n*: originally seen in the map Valley of Death, Rival Nations implemented the cinematic/awards concept and improved upon it by having a sort of parade with each of the heroes that a player controlled, as well as a final battle at the end in which all players, even the ones previously on your team, are now all hostile and battle it out as the awards scroll.\r\n* Custom Rules\r\n*: Rival Nations is actually various forms of the same map combined into one. There is an option which allows the host player to set custom rules for the game which can determine everything from a time limit, to forced random heroes.\r\n* Random Weather and random tree regrowth\r\n* Random Heroes\r\n*: Rival Nations was one of the first maps to provide the option of selecting a hero randomly for players who are confident enough in their skills to prevail under all circumstances.\r\n* -take command\r\n*: Rival Nations not only divides resources and shares control of a dropped or quitting teammate between the remaining teammates but it also allows the ability to take full ownership of that players heroes and other units. By typing '-take' hero ownership is transfered, and prevents a loss from what should be a win if some player drops or decided to leave unexpectedly.\r\n* Town Boss\r\n*: the Captain, like much of Rival Nations is not designed to be incredibly powerful, however he is more than enough to repel standard troops for a decent amount of time. As well some players with a paladin hero will kill or wait until he is killed, then resurrect him (resurrected units have their ownership transfered), and use him as additional combat support for their heroes.\r\n==Heroes==\r\nRival Nations primary focus is heroes and hero to hero combat. There are other strategic options that can be explored, such as town and troop upgrades, as well as non-hero mercenaries, however ultimately \r\n====Popular Hero Combos====\r\n* Stun crew\r\n*: this combination was designed to trap one or more heroes in a 'stun lock' preventing them from running or even teleporting away. It is very effective and was the combination favored by the game's creator MicrosoftXP.\r\n** Tauren Chieftain (war stomp)\r\n** Mountain King (storm bolt)\r\n** Dreadlord (sleep, inferno)\r\n** Shadow Hunter (hex)\r\n* Nukers\r\n*: the strategy here was to exploit the 66% increase in direct damage cause to a banished target. Executed correctly, one could instantly kill an enemy hero before they have time to do much of anything.\r\n** Blood Mage (banish)\r\n** Death Knight (death coil, frost nova)\r\n** Mountain King (storm bolt)\r\n* Ranged\r\n*: one of the least popular combinations, this one was weak to direct attacks from nuke and stun combinations, but could be a very effective backup/support group due to easy and high damage focused fire. Load up each hero with as much damage increasing items/tomes as possible, such that one volley can easily take a sizable amount of an enemy hero's life.\r\n** Archmage\r\n** Keeper of the Grove\r\n** Priestess of the Moon\r\n** Far Seer\r\n** Shadow Hunter\r\n** Blood Mage\r\n** Naga Sea Witch\r\n====Racial Combinations====\r\nIf a player gets the 4 primary heroes from the same race, they would get additional benefits for themselves and their team. If a player gets five heroes and they include the four primary heroes plus a neutral hero of the same race, further additional benefits are rewarded. The benefits included a general town bonus and a powerful magic item. The bonus later came to include a racial shop that would be created in the player's base which contained useful and powerful items.\r\n===== Human =====\r\nThe Human Alliance enhances the army by training a random specialty unit at each barracks. Possible units include Sorceress, Priest, Spell Breaker, Dragonhawk Rider and Gryphon Rider.\r\nSpecialty Item: Magic Forged Gauntlets\r\nThese magical gauntlets grants their owner inceased Armor, Movement Speed, Strength, Intelligence, and Agility. They also grant the ability to cast Inner Fire and can be used to summon aid.\r\n \r\nSummons: Blood Elf Lieutenants\r\nPowerful lieutenants from Prince Kael's Blood Elf army. Experts at destroying spellcasters.\r\n===Secret Hero===\r\nThe Lich was for a long time nothing more than a myth to many players, very few knew it even existed and fewer knew how to actually get it. This was done in the interests of balance, as the Lich's ultimate ability was Death and Decay, which is by far the best building killing spell in the game, and it would have caused many complications to allow this spell to be available at the start of the game. Thus, in order to acquire the Lich, one first had to have the other two available Undead Heroes: the Death Knight and the Dreadlord. Once these two were acquired, if another hero was purchased, a message would appear that said 'Can you find the secret hero?' The trick then was to simply wait approximately 60 seconds for the Lich to spawn.",},
			["Rivendark's Perch"] = { content = "'''Rivendark's Perch''' is the lair of the [[black dragon]] [[Rivendark]], who flies over the [[Vortex Pinnacle]].",},
			["Rivendark"] = { content = "'''Rivendark''' is a [[black dragon]] that flies over the [[Vortex Pinnacle]]. Be very careful around Rivendark - if he detects you he will spit a fireball at you. (~3000 damage)\r\nAs of patch 2.4.2 the dragons in Blade’s Edge Mountains will no longer instantly knock you off your flying mount.",},
			["Rivern Frostwind"] = { content = "'''Rivern Frostwind''' is a level 62 [[wintersaber]] [[riding instructor]] located at [[Frostsaber Rock]] in the [[contested]] territory of [[Winterspring]]. He gives quests to [[Alliance]] characters to earn reputation with the [[Wintersaber Trainers]]. At , he will sell the Reins of the Winterspring Frostsaber.\r\n==Quests==\r\nHe starts the following quests, all repeatable:\r\n* Frostsaber Provisions\r\n* Rampaging Giants (Elite)\r\n* Winterfall Intrusion\r\n==See also==\r\nSee [[List of Winterspring NPCs]].",},
			["Riverpaw pack"] = { content = "The Riverpaw are a violent tribe of [[Gnolls]] led by vicious individuals such as the notorious [[Hogger]], and [[Sergeant Brashclaw]]. Their villainous hold over the western regions of [[Elwynn Forest]] is one that the forces at [[Westbrook Garrison]] seek to alleviate. From [[Forest's Edge]], Hogger leads his Riverpaw into battle. Sergeant Brashclaw has a hold over the far reaches of [[Westfall]]. [[Fedfennel]] heads the Riverpaw presence at [[Stone Cairn Lake]].\r\nThere is also evidence to support the rumours that the Riverpaw may be in a loose alliance with the [[Defias Brotherhood]]. Their leaders drop a document known as The Collector's Schedule. This indicates that there is payment being processed between the Defias and the Riverpaw. [[Morgan the Collector]] conducts the relevant transactions of gold. [[Wiley the Black]] also reveals that the Defias are working with gnolls, kobolds and goblins, clearly hinting at Hogger's pact with [[Edwin VanCleef]].",},
			["River Arevass"] = { content = "'''River Arevass''' is a river located in [[Silverpine Forest]], just west of [[Lordamere Lake]]. It was where [[Tyrande]] made a stand against invading [[Scourge]], which ended with the bridge spanning the river breaking and the high priestess being swept downriver.\r\n==In-game Possibility==\r\nIn Silverpine forest, there is the remains of a river that once flowed either in to or out of [[Lordamere Lake]]. All that remains of it is the dried up canyon, a few remaining pools, and a human bridge crossing it near the lake its self. This is possibly the Arevass, and its drying up could be due to a hypothesized fall of water around the time of Warcraft 3 that could have also eliminated [[Cross Island]]. It seems to have flowed in, because of there being no trace of its flow between the canyon and the seashore, and the canyon hints that it was a fast flowing, highly erosive river.",},
			["River Golem"] = { content = "==Story==\r\nThe '''River Golem''' was hiding north of River Arevass when [[Illidan]] killed him in the eighth map of the Warcraft III Frozen Throne Expansion Night Elf Campaign. [[Illidan]] and [[Malfurion]] were trying to save [[Tyrande]] from attacks by the [[Scourge]].\r\n==Statistics from Warcraft III==\r\n* 1500 HP\r\n* 600 MP\r\n* 61-68 chaos melee damage\r\n* 46-51 chaos air damage\r\n* 5 heavy armor\r\n* Abilities\r\n** Bash (attacks sometimes stun target)\r\n** War Stomp (AoE slow and damage around caster)\r\n** Hurl Boulder (ranged stun and damage for one unit)",},
			["Riznek"] = { content = "'''Riznek''' is a level 35 [[drink vendor]] located at the [[Mirage Raceway]] in the [[contested]] territory of [[Thousand Needles]].\r\nSee [[List of Thousand Needles NPCs]].",},
			["Rizzle Brassbolts"] = { content = "'''Rizzle Brassbolts''' is a level 30 NPC located at the [[Mirage Raceway]] in the [[contested]] territory of [[Thousand Needles]]. He is currently working for the gnomish crew, and is the brother of [[Wizzle Brassbolts]] and [[Fizzle Brassbolts]].\r\nHe is involved with the following quests:\r\n* Keeping Pace\r\n* Rizzle's Schematics\r\nSee [[List of Thousand Needles NPCs]].",},
			["Rizzle Sprysprocket"] = { content = "'''Rizzle Sprysprocket''' is a level 70 [[Goblin]] [[NPC]] in [[Azshara]]. She appears during the [[Druid]] epic [[Flight Form]] [[Quest]] Chasing the Moonstone. She steals the moonstone before the druid can take it and leads them on a merry chase down the river, dropping [[Rizzle's Depth Charge|depth charges]], until she finally gives up and offers the item.\r\nAlthough she shares the same last name with [[Razzle Sprysprocket]], they apparently are not related.",},
			["Roach"] = { content = "'''Roaches''', or '''cockroaches''' are small [[insect]]s that can be found skittering about in the dankest corners of [[Azeroth]]. A nuisance to most, their incredible survivability sets them apart from other species, and most creatures cannot withstand a fraction of the harsh conditions that roaches can thrive in. However, not even cockroaches were strong enough to withstand the [[demon]]ic corruption in [[Felwood]]. Some roaches have developed a resistance to fire. The outer member of the roaches' eggs protect the larva from incineration, and it is here in incubation that they gain the ability to resist the scorching temperatures of their volcanic environment.\r\nThe cockroaches of [[Deepholm]] can burrow into stone itself to make their nests. The roaches of the [[Dread Wastes]] dwell in the shadows. Some people swear the shadows travel with them.\r\n[[Nether Roach|Nether roaches]] have adapted to the cold vacuum of space and require no air to survive, though inside it bears almost no resemblance to a common roach.\r\n==Notable==\r\n*Fester (roach)\r\n==As a companion pet==\r\n*[[Cockroach]]es and [[Roach (critter)|roach]]es can be captured in pet battles in many zones across the world.\r\n*[[Death's Head Cockroach]]es can be captured in pet battles in [[Mount Hyjal]].\r\n*[[Deepholm Cockroach]]es can be captured in pet battles in [[Deepholm]].\r\n*[[Experimental Roach]] and [[Junkheap Roach]] can be captured in pet battles on [[Mechagon Island]]]].\r\n*[[Fire-Proof Roach]]es can be captured in pet battles in [[Frostfire Ridge]] and Mount Hyjal.\r\n*[[Irradiated Roach]]es can be captured in pet battles around [[New Tinkertown]] in [[Dun Morogh]].\r\n*[[Locust]]s can be captured in pet battles in [[Uldum]].\r\n*[[Mechanical Cockroach]] can be bought from [[Micro Zoox]] in [[Dun Morogh]] for 1 [[Pristine Gizmo]].\r\n*[[Nether Roach]]es can be captured in pet battles in the [[Netherstorm]].\r\n*[[Resilient Roach]]es can be captured in pet battles in the [[Dread Wastes]].\r\n*[[Tainted Cockroach]]es can be captured in pet battles in [[Felwood]].\r\n*[[Undercity Cockroach]] can be purchased from Jeremiah Payson in the [[Undercity]] and Dealer Rashaad in the Netherstorm.\r\n*[[Void-Scarred Locust]] can be captured in pet battles in the [[Black Empire]]-assaulted [[Uldum]].",},
			["Road to Damnation"] = { content = "\"'''Road to Damnation'''\", aka \"'''The Road to Damnation'''\", is a short story written by Evelyn Fredericksen and published on the [[World of Warcraft]] community site as the precursor to [[Patch 1.11]].\r\n==Dramatis Personae==\r\n*[[Kel'Thuzad]], the main character\r\n*Members of the [[Kirin Tor]]:\r\n**[[Antonidas]], head of the Kirin Tor\r\n**[[Drenden]]\r\n**[[Archmage Modera|Modera]]\r\n**[[Kael'thas Sunstrider|Prince Kael'thas Sunstrider]]\r\n**[[Jaina Proudmoore]]\r\n*[[Lich King|The Lich King]], master of the [[Scourge]]\r\n*[[Anub'arak]], [[crypt lord]] in Scourge service\r\n==Text==\r\nPage 1:\r\n\"This continual harassment grows tiresome. I was in the midst of important studies, delicate magic that requires weeks of preparation and ritual.\" Kel'Thuzad had been forced to wait for hours, fuming at the insult, before he was permitted the bare courtesy of confronting his accusers. The group's apparent spokespersons, Drenden and Modera, had long been two of his most vocal critics. Nonetheless, they would not have launched this latest inquisition without support from Antonidas, who had yet to show himself. What was the old man up to?\r\nDrenden snorted. \"That's the first time I've heard your sort of magic called 'delicate.'\"\r\n\"An ignorant opinion from an ignorant man,\" said Kel'Thuzad with cold precision.\r\nA distant voice spoke to him then, the voice of a friend. By now its remarks had grown so familiar that they felt like his own thoughts. ''They fear and envy you. After all, thanks to this new course of study, you are continuing to gain in knowledge and power.''\r\nThere was a sudden flash of light, and a scowling gray-haired archmage appeared in the hall. A small wooden chest was tucked under his arm. \"I would not have believed it if I had not seen it myself. You have abused our patience for the last time, Kel'Thuzad.\"\r\n\"The venerable Antonidas graces us with his presence at last. I began to think you had fallen ill.\"\r\n\"Age frightens you, doesn't it?\" Antonidas snapped. \"You realize there's only one alternative.\"\r\n''Let him think so, if that comforts him.''\r\nCalming somewhat, Antonidas said, \"As for my health, you need not have concerned yourself. I was merely busy elsewhere.\"\r\n\"Searching my chambers for evidence of forbidden magic? You should know better.\"\r\n\"True, your chambers bore no such evidence. The warehouses you own in the northlands, on the other hand...\" Antonidas gave him a disgusted look.\r\nDamn the man for being a self-righteous snoop. \"You had no right...\"\r\nAntonidas tapped his staff to the floor, silencing him, and turned to the other magi. \"He has turned the buildings into laboratories for a series of foul experiments. See for yourself, colleagues. Behold the fruit of his labors.\" He opened the chest and tilted it so that all could see.\r\nThe decaying remains of several rats. Two were still scrabbling clumsily at the sides of the chest in a vain attempt to escape. Several magi bolted to their feet, and there was a hubbub of dismay. Even the golden-haired high elf who had been sitting in the back of the room seemed startled, though Prince Kael'thas was a man whose age made that feat nearly impossible.\r\nTurning back to the captive rats, Kel'Thuzad saw that they had collapsed and stopped moving. Another set of failures, apparently. No matter. Someday he would create a stable undead specimen. His hard work would be vindicated. It was only a matter of time.\r\n''There are loose threads in the spell that silences you. Shall I show you how to unravel it?''\r\nTime, and his unknown ally, whose enigmatic voice occasionally helped him to move one step closer to his goal. ''Show me,'' he thought.\r\nA young woman arrived in another flash of light. As she went to stand by Antonidas, the high elf's gaze followed her with troubled, brooding intensity. But Jaina Proudmoore took no notice; she was utterly focused on her duties. The handsome prince didn't stand a chance.\r\nHer vivid blue eyes spared Kel'Thuzad a curious glance. She took the box from Antonidas, who explained, \"My apprentice will see to it that the chest and its contents are incinerated.\"\r\nThe woman inclined her head and teleported from the room. Across the room, the high elf frowned at the spot she had vacated. Under other circumstances, Kel'Thuzad might have found the silent drama amusing. However, left unchallenged, Antonidas was continuing his tirade. Mutely seething, Kel'Thuzad resumed his efforts to free himself.\r\n\"We have permitted this state of affairs long enough. Rapped his knuckles occasionally for his more questionable pursuits. Tried to guide him. Now we find he has been practicing evil magic. The name of the Kirin Tor is fast becoming a curse on the lips of the local villagers.\"\r\n\"You lie!\" Kel'Thuzad burst out, and a few of the magi were his again, waiting for him to offer an explanation. \"Peasants remember the Second War just as well as we do. Say what you like about the orcs; their warlocks wielded great power. Power against which we had precious little defense. We have an obligation: we must learn to wield and counter these magics ourselves.\"\r\n\"To form an army of dead rats, their unnatural existence measured in hours?\" Antonidas asked dryly. \"Yes, my boy, I found your journals, too. You kept quite detailed records regarding this abominable enterprise. You cannot mean to use these pathetic creatures against orcs. Assuming, of course, that the orcs should ever emerge from their current lethargy, escape the internment camps, and somehow manage to become a threat again.\"\r\n\"Being younger than you hardly qualifies me for boyhood,\" retorted Kel'Thuzad. \"As for the rats, they are the gauge by which I measure my progress. It is a standard experimental technique.\"\r\nA sigh. \"I am aware that you spend most of your time in the north these days. Your increasingly lengthy absences were what caught my attention in the first place. Yet even you must have heard that the king's new tax has given rise to civil unrest. Your selfish pursuit of power could incite the peasantry to revolt. Lordaeron would be engulfed in civil war.\"\r\nHe hadn't known about the tax. Antonidas must be exaggerating. Besides, true magi would focus on matters of greater substance. \"I will be more discreet,\" he offered, gritting his teeth.\r\n\"No amount of discretion could possibly hide a secret of this magnitude,\" said Drenden.\r\nModera added, \"You know that we have always walked a fine line in order to protect our people without becoming a danger ourselves. We dare not sacrifice our humanity- not in appearance, and certainly not in truth. At best, your methods would see us condemned as heretics.\"\r\nIt was too much. \"We've been called heretics for centuries. The church has never been fond of our methods. Such sentiments notwithstanding, we are still here.\"\r\nShe nodded. \"Because we avoid dark magic, which leads to corruption and catastrophe.\"\r\n\"Because we are necessary!\"\r\n\"Enough.\" Antonidas sounded weary. To Modera and Drenden, he added, \"If words alone could have reached him, they would have done so before now.\"\r\n\"I have heard your words,\" Kel'Thuzad said in exasperation. \"Merciful gods, I have heard them until I am sick of them! It is you who will not hear mine, and put aside your antiquated fea...\"\r\n\"You mistake our purpose here today,\" interrupted Antonidas. \"This is not a debate. At this moment, your properties are being thoroughly searched. All items tainted by dark magic will be confiscated and, once identified to our satisfaction, destroyed.\"\r\nHis nameless ally had warned him this might happen, but Kel'Thuzad had not believed. Strange. He felt almost relieved that events had come to this pass. The need for secrecy had limited the scope of his work, hindered his advancement.\r\n\"In light of the evidence,\" Antonidas said heavily, \"King Terenas has agreed with our judgment. If you do not abandon this madness, you will be stripped of your rank and holdings, and you will be exiled from Dalaran- indeed, from all of Lordaeron.\"\r\nHis mind racing, Kel'Thuzad bowed and left the hall. Doubtless the Kirin Tor were keeping his so-called disgrace quiet, fearing repercussions should his actions become public knowledge. For once, their cowardice would work in his favor. His wealth would never line the king's coffers.\r\nA pack of wolves stalked Kel'Thuzad for miles, just out of spell range, before they fell behind. Glancing warily over his shoulder, he saw them snarl and flatten their ears before darting away. Thankfully the arctic winds were dying out as well. In the distance he could make out the summit, a bleak mountaintop, the sight of which gave him a sense of triumph and foreboding. The very peak of Icecrown. Few explorers had ventured onto the glacier, and even fewer had survived to tell the tale. But he, Kel'Thuzad, would scale its heights alone and look down on the rest of the world.\r\nUnfortunately almost no maps existed of the frigid continent of Northrend, and he found them woefully inadequate, like the supplies he'd proudly packed for this journey. Uncertain of the path ahead and his ultimate destination, he could not teleport. Not sparing himself, he staggered onward. He had lost track of how long he'd been walking. Despite his fur-lined cloak, he was shivering uncontrollably. His legs felt like pillars of stone: awkward and numb. His body was beginning to shut down. If he didn't find shelter soon, he was going to die out here.\r\nEventually a glint of light drew his gaze: a stone obelisk carved with magical symbols, with a citadel beyond it. At last! He hurried past the obelisk and crossed a bridge of what looked like pure energy. The citadel's doors opened at his approach, but he stopped short.\r\nThe entryway was guarded by two grotesque creatures that resembled giant spiders from the waist down. Six narrow legs supported each creature's weight; the other two limbs were attached like arms to a vaguely humanoid torso. More fascinating than the creatures themselves, though, was their current state. Their bodies showed an assortment of open wounds, the worst of which had been roughly bandaged. One guard's arms were bent at improbable angles. Ichor oozed from the other's fanged maw, but the guard made no effort to wipe it away.\r\nDespite the familiar stink of undeath, the guards showed no sign of confusion, unlike Kel'Thuzad's rats. The spider-like creatures must also have retained most of their original strength and coordination. Otherwise, they would have made poor guards. Their creator was clearly a skilled necromancer.\r\nTo his surprise, they moved aside to let him pass. Unwilling to question his good fortune, he gladly entered the citadel, which was significantly warmer. In the hallway ahead was a battered statue of one of the half-spider creatures. The building itself was of recent construction, but the statue was quite old. Come to think of it, he'd seen similar statues in the ancient ruins he'd passed through on his way north. The cold was slowing his wits.\r\nAt a guess, the necromancer had conquered a kingdom of these spider-like beings, successfully converted them into undeath, and taken their treasures as the spoils of war. Exultation filled him. He would surely learn great things here.\r\nAt the end of the hall, a gigantic creature lumbered into view: a grotesque mixture of beetle and spider. It approached him at a deliberate pace, and Kel'Thuzad observed that its towering body sported an even greater number of wounds and bandages. Like the guards, it was undead, but its sheer bulk made him feel more frightened than impressed. He doubted he had sufficient skill to vanquish such a monster, much less raise it from the dead.\r\nThe creature greeted him in a deep bass voice that reverberated within its ponderous body. Although it spoke perfectly understandable Common, the sound chilled him. Strange buzzing and clicking underlaid its words. \"The master has been expecting you, archmage. I am Anub'arak.\"\r\nIt had both the intelligence and motor skills for speech - astonishing! \"Yes. I wish to become his apprentice.\"\r\nThe huge creature simply looked down at him. Possibly it was debating whether he would make a tasty snack.\r\nHe cleared his throat nervously. \"May I see him?\"\r\n\"In due time,\" Anub'arak rumbled. \"Thus far, you have devoted your life to the pursuit of knowledge. An admirable goal. Still, your experiences as a mage cannot have prepared you for serving the master.\"\r\nWhat could have inspired such a speech? Did the majordomo consider Kel'Thuzad a rival? That was a misconception to dispel as soon as possible. \"As a former member of the Kirin Tor, I have more magic at my command than you could probably imagine. I am more than prepared for whatever tasks the master gives me.\"\r\n\"We shall see.\"\r\nPage 2:\r\nAnub'arak led him through a number of tunnels that took them far beneath the earth. At last Kel'Thuzad and his guide emerged into a vast ziggurat whose name, so Anub'arak said, was Naxxramas. From its architecture, the building was another product of the half-spider creatures. Indeed, the first chambers Anub'arak showed him were populated by the undead things, which swiftly lost their novelty. Actual spiders also skittered here and there among the undead, busily spinning cobwebs and laying eggs. Kel'Thuzad hid his distaste. He wouldn't give the enormous majordomo the satisfaction. Indicating one of the undead spider-things, he said, \"You bear them some resemblance. Are you all derived from the same race?\"\r\n\"The nerubian race, yes. Then the master came. As his influence spread, we made war upon him, foolishly believing we stood a chance. Many of us were slain and raised into undeath. In life I was a king. Today I am a crypt lord.\"\r\n\"In return for immortality, you agreed to serve him,\" Kel'Thuzad mused aloud. Remarkable.\r\n\"'Agreed' implies choice.\"\r\nWhich meant that the necromancer could compel obedience from the undead. Kel'Thuzad might be the first living being to come here of his own free will. Faintly disquieted, he changed the subject. \"This place is full of your people. I take it you rule here?\"\r\n\"After my death, I led my brethren in conquering this ziggurat for our new master. I also oversaw the process of altering it to serve his design. However, Naxxramas does not fall under my authority. Nor are my people its only occupants. This is but one wing out of four.\"\r\n\"In that case, lead on, crypt lord. Show me the rest.\"\r\nThe second wing was everything Kel'Thuzad could have hoped. Magical artifacts, laboratory equipment, and other supplies that put his old laboratories to shame. Huge rooms that could hold a veritable army of assistants. Undead beasts that had been cleverly sewn together from a hodgepodge of animals and reanimated. Even a few undead humanoids composed of body parts from assorted humans. The human body parts bore no wounds: unlike the nerubians, the humans had not fought their fate. The necromancer must have acquired the bodies from a local graveyard. Wise to avoid drawing notice. The Kirin Tor would have taken immediate action.\r\nUnfortunately the third wing proved less interesting. Anub'arak showed him an armory and an area for combat training. Next the crypt lord led him through chambers filled with hundreds - no, thousands - of sealed barrels and shipping crates. Why would Naxxramas need so much in the way of supplies? Well, the pyramid was well stocked in the unlikely event that it was besieged.\r\nAt last he and Anub'arak reached the last wing. Giant mushrooms grew in a garden area and gave off noxious fumes that made Kel'Thuzad feel ill. The soil beneath each mushroom seemed unhealthy, possibly diseased. Going closer to inspect it, he stepped on something that squished: a fist-sized creature that resembled a maggot.\r\nHe shuddered and hastily moved on. The next room had a number of small cauldrons filled with a bubbling greenish liquid. Curious despite the substance's revolting odor, Kel'Thuzad took a step forward, but a massive claw abruptly blocked his way.\r\n\"The master wishes you to remain among the living. Your time has not yet come.\"\r\nHis breath caught in his throat. \"It would have killed me?\"\r\n\"There are many who will not serve the master in life. The fluid resolves that difficulty.\" At Kel'Thuzad's blank look, the crypt lord said, \"Come. I will show you.\"\r\nAnub'arak took him to a cell that held two prisoners. Villagers, by their homespun clothing. The man was cradling the woman in his arms; she was ghastly pale and soaked in sweat. Alive, both of them, though the woman was clearly ill. Kel'Thuzad glanced at the crypt lord uneasily.\r\nHer desperate glassy eyes found Kel'Thuzad and brightened. \"Mercy, my lord! My body fails. I have seen what will happen next. One bolt of flame, I beg of you. Let me rest in peace.\"\r\nShe was afraid of becoming the necromancer's thrall. According to Anub'arak, she would have no choice. Kel'Thuzad looked away queasily. After all, she couldn't live much longer anyway.\r\nShe struggled out of the man's arms and clung to the cell bars. \"For pity's sake! If you will not aid me, at least take my husband to safety!\" And she wept hopelessly.\r\n\"Hush, sweetheart,\" the man murmured behind her. \"I will not leave you.\"\r\n\"Make her be quiet!\" Kel'Thuzad whispered fiercely at Anub'arak.\r\n\"The noise distresses you?\" With one lightning-quick motion, Anub'arak shot one claw through the bars and speared the woman through the heart. Then the crypt lord casually shook the corpse off onto the floor.\r\nHer husband howled with anguish. Guiltily relieved, Kel'Thuzad began to turn away, but froze when the corpse started thrashing and arching against the stone floor. The male villager gaped in shock and fell silent.\r\nThe dead woman's skin was changing color: shifting to a faintly greenish gray. Gradually the spasms died off, and she scrambled unsteadily to her feet. She rolled her head to one side, then shivered as she spotted her husband. \"Guards, get this man out of here.\" she rasped.\r\nThe guards didn't move. With a groan, she raked her fingers through her tangled brown hair, and Kel'Thuzad got a good look at her face. Blood vessels were darkening under the skin, and her eyes seemed feral, crazed.\r\nHer husband asked doubtfully, \"My love? Are you all right?\"\r\nA bitter laugh escaped her and twisted into a snarl when he took a hesitant step toward her. \"Don't come any closer.\"\r\nThe man ignored her protest and went toward her, but she shoved him away with enough force to send him flying. He hit the cell bars and slid down, stunned.\r\n\"Stay back.\" Her speech was becoming more guttural. \"Hurt you.\" She wrapped her arms around herself, backed up until she bumped against the opposite side of the cell. \"Hurt you, hurt you,\" she whined, and something began to be wrong with the way she said it.\r\nUncomprehending, Kel'Thuzad watched her slowly, jerkily lift a hand to the hole in her chest. She hissed, grimaced, and brought her fingers to her mouth. Licked them. Sucked at them. Then in a blur of movement, she was leaping at her husband, lashing out, baring her teeth -\r\nThe man screamed, and blood spurted onto the cell floor. Kel'Thuzad flinched away. Closing his eyes didn't help; he could still hear unspeakable sounds. Ripping, shredding. Chewing. A soft, wretched mewling that he very much feared meant the undead woman was aware of her actions on some level, but unable to stop herself.\r\nSickened and horrified, he teleported out of Naxxramas altogether, staggered a little distance away, and threw up. Finding a patch of unsullied snow, he scooped up handfuls and scrubbed viciously at his mouth and face. It felt as if he would never be clean again. What had he gotten himself involved in?\r\nOne by one, his scattered thoughts fell into place. The necromancer was no simple academic, interested in studying a widely condemned field of magic. Nor did he plan to stop at fortifying his home against attack. He was mass-producing a fluid that converted people into zombies. Naxxramas also had an enormous stockpile of supplies, weapons, armor, training grounds...\r\nThese weren't defensive measures. They were preparations for war.\r\nA sudden wind buffeted him with an unearthly shriek, and a group of cold wraiths coalesced in front of his eyes. He had read of them years ago in the Violet Citadel. The vague description of their cloudy, translucent forms had mentioned nothing of the frigid malice in their glowing eyes.\r\nOne of the wraiths drifted closer and asked, \"Second thoughts? As you see, your little trick will not avail you. You cannot escape the master. At any rate, what could you hope to accomplish? Where would you go? More to the point, who would believe you?\"\r\nFight or flight: those would have been the heroic choices. Heroic, but pointless. His death would serve nothing. By agreeing to become the necromancer's apprentice, Kel'Thuzad bought himself time in which to bolster his own skills. With enough training, he could surpass the necromancer or catch the man off guard.\r\nHe nodded to the wraith. \"Very well. Take me to him.\"\r\nPage 3:\r\nThe wraiths teleported him back to the citadel and escorted him downward through a series of halls and rooms that Kel'Thuzad knew he wouldn't be able to remember later. At last, deep beneath the earth, he and the wraiths entered a huge cavern whose dank chill sank into his bones. In the center of the cavern was a dizzyingly tall spire of rock. Blanketed in snow, a set of stairs spiraled up the sides of the spire.\r\nHe and the wraiths began the ascent. His heart pounded with excitement and dread. When he realized that his steps were slowing, he sped up again. His resolution didn't last long, however. It felt as if a weight was pulling at him. Evidently the long journey across Northrend had tired him more than he'd thought.\r\nFar above him, at the top of the spire, he could barely make out a large chunk of crystal. Untouched by snow, it had a faint bluish gleam. There was no sign of the necromancer.\r\nOne of the wraiths used a frigid gust of wind to give him a push. His pace had been lagging again. Irritably he tugged his cloak closer and forced himself to keep climbing, though he was breathing hard.\r\nTime passed, and a blast of sleet brought him back to full awareness. He had stopped in the middle of the stairs to lean on his staff. The air was foul and suffocating; he was panting by now. \"Give me a moment,\" he managed.\r\nA wraith behind him said, \"We cannot rest. Why should you?\"\r\nGrimly Kel'Thuzad resumed the climb and hunched his shoulders against the growing exhaustion. He raised his head with an effort and saw that the glimmering crystal was drawing close. At this distance, it looked like a jagged throne with hazy dark shapes inside it. There was a palpable aura of menace about the thing.\r\nThe wraiths brushed against him and startled him into crying out. Echoes of the sound reverberated throughout the cavern. He clutched at his fur cloak with clammy, trembling hands. His breath rattled in the back of his throat, and he had the sudden terrible urge to turn around and start running. \"Where is the master?\" he asked, and his voice was high and quavering.\r\nNo answer, just a storm of hail that lashed at him cruelly. He stumbled and recovered his footing. With each step, the throne looming above him felt more oppressive, pushing his head down, bending his spine. He could barely walk upright. Before long, he fell to his hands and knees.\r\nThe necromancer spoke directly to Kel'Thuzad then in a voice that was no longer even remotely kind. ''Let this be your first lesson. I have no love for you or your people. On the contrary, I intend to scour humanity from this planet, and make no mistake: I have the power to do it.''\r\nRelentless, the wraiths did not permit him to stop. Beyond humiliation, he abandoned his staff and began to crawl. The necromancer's malevolence beat down upon him and pressed him deeper into the snow. Kel'Thuzad was shaking and whimpering, and o gods, he'd been wrong--stupidly, colossally wrong. This wasn't fatigue. It was stark terror.\r\n''You will never catch me unaware, for I do not sleep, and as you should have already guessed, I can read your thoughts as easily as you might read a book. Nor can you hope to defeat me. Your puny mind is incapable of handling the energies I manipulate on a whim.''\r\nKel'Thuzad had long since torn his robes, and his leggings were useless against the icy rock of the rough-hewn stairs. His hands and knees left bloody tracks behind him as he struggled up the last spiral. The throne radiated bone-chilling cold, and mist surrounded it. A throne not of crystal, but of ice.\r\n''Immortality can be a great boon. It can also be agony the likes of which you have not yet begun to fathom. Defy me, and I will teach you what I have learned of pain. You will beg for death.''\r\nHe came within a few feet of the throne and could go no farther, pinned helplessly beneath the thing's overwhelming aura of inhuman might and hatred. An unseen force bore down on him and ground the side of his face into the unyielding stone. \"Please,\" he found himself sobbing. \"Please!\" Further words escaped him.\r\nFinally the pressure eased. The wraiths flitted away, but he knew better than to rise. Doubted, in any case, that he could. His eyes, however, unwillingly sought out his tormentor.\r\nA set of plate armor was seated within the throne, rather than upon it. Kel'Thuzad might have thought the armor merely black, but, blinking hard, he saw that no light at all was reflected from its surface. In fact, the longer he looked, the more it seemed to devour all light, hope, and sanity.\r\nThe ornate spiked helm obviously doubled as a crown. It was set with a single blue gem and, like the rest of the armor, appeared empty. In one gauntlet, the figure clasped a massive sword whose blade had been etched with runes. Here was power. Here was despair.\r\n''As my lieutenant, you will gain knowledge and magic to surpass your most ambitious dreams. But in return, living or dead, you will serve me for the rest of your days. If you betray me, I shall make you into one of my mindless ones, and you will serve me still.''\r\nServing this spectral being--this Lich King, as Kel'Thuzad was beginning to think of him--would assuredly bring Kel'Thuzad great power... and damn him for all eternity. But that knowledge came far too late. Besides, damnation had little meaning without the prospect of true death.\r\n\"I am yours. I swear it,\" he said hoarsely.\r\nIn response, the Lich King sent him a vision of Naxxramas. Small black-robed figures stood in a broad circle outside on the glacier. Their arms, visibly wreathed in dark magic, rose and fell in time with a droning chant that eluded Kel'Thuzad's understanding. Tremors shook the earth beneath their feet, but they kept casting.\r\n''You will go forth and bear witness to my power. You will be my ambassador to the living, and assemble a group of like-minded people to further my plans. Through illusion, persuasion, sickness, and force of arms, you will establish my hold upon Azeroth.''\r\nTo Kel'Thuzad's astonishment, the ice shifted and cracked, and the top of a ziggurat pierced the frozen ground. A building was being pulled up out of the soil. While the robed figures redoubled their efforts, the vast pyramid continued its impossible emergence. Chunks of dirt and ice flew outward with explosive force. Soon the entire structure had broken free of the earth's embrace. Slowly but surely, Naxxramas rose into the air.\r\n''And this will be your vessel.''\r\n&copy; Blizzard Entertainment 2006",},
			["Roanauk Icemist"] = { content = "'''Roanauk Icemist''' is the leader of the [[Taunka]] in [[Northrend]]. He is being imprisoned in the ruins of [[Icemist Village]] by the scourge. The player aids him in the quest chain [[Quest:Strength of Icemist|Strength of Icemist]], where the player frees him. He is then found with other Taunka Refugees where the player offically inducts him into the Horde as the leader of the Horde taunka.",},
			["Roar"] = { content = "'''Roar''' is a [[tigon]] boss in the Opera House of [[Karazhan]], accompanied by [[Dorothee]], [[Strawman]], [[Tinhead]], Dorothee's pet [[Tito]], and followed by [[The Crone]].\r\n''Roar is an homage to The Cowardly Lion of [[Wikipedia:The Wizard of Oz (1939 film)|The Wizard of Oz]].''\r\n==Abilities==\r\n*'''Basic Melee''' - Hits for around 3000 on cloth.\r\n*'''Frightened Scream''' - Instant. Lets out a scream, causing up to 3 nearby enemies to flee for 2 sec.\r\n==Strategy==\r\nAs befitting his inspiration, Roar is rather [[Wikipedia:Cowardly Lion|cowardly]], and susceptible to [[fear]].\r\nHe can be feared by either the [[fear]] spell itself, or by a Hunter's [[Scare Beast]] ability, or by [[Howl of Terror]] or [[Psychic Scream]]. As of the 2.1 patch, Roar is also vulnerable to horror effects, i.e. [[Deathcoil]].'''\r\nHe is immune to [[snare]]s and [[Hibernate]].\r\nA thing to note about fear is that he runs into the walls while he's doing this he can not be targeted by a fearer, so a suggested strategy is to have the tank not worrying about Tinhead, grab enough aggro on Roar that once fear breaks he turns to the tank rather than a squishy.\r\n==Quotes==\r\n* \"Wanna fight? Huh? Do ya? C'mon, I'll fight you with both claws behind my back!\"",},
			["Roasted Clefthoof"] = { content = "==Source==\r\nThis item can be crafted using [[Cooking]] (325); taught by Recipe: Roasted Clefthoof. \r\n==Uses==\r\n4 are used as a component in Soup for the Soul.",},
			["Roast Raptor"] = { content = "==Source==\r\nThis item can be crafted using [[Cooking]] (175); taught by Recipe: Roast Raptor. \r\n==Roast Raptor as a quest objective==\r\nThis item is an objective for the following quests:\r\n* The Alliance Needs Roast Raptor!\r\n* The Alliance Needs More Roast Raptor!",},
			["Roberick Dartfall"] = { content = "'''Roberick Dartfall''' is the leader of a small force of [[Forsaken]] in the [[Tirisfal Glades]]. He travels through the glades welcoming visiters and defending anyone who comes into danger. He protects them from the mindless undead and mutant creatures living there. He believes that the Forsaken are different than the [[Scourge]], and they wish it was destroyed. He believes that they have become forsaken by their friends; forgotten or dismissed by the families they once loved and by their former allies. His group works to change that and prove to the world that there are good (not evil) Forsaken. \r\nHe believes that it is true that many of their kind are jealous of the living, and some have allowed that jealousy to become hatred. However, he believes that the Forsaken should not be judged by those individuals, and that they should be judged by their actions instead. Unfortunately its suggested that he may be overly optimistic, and that there is more evil within their organization than he suspected. \r\nHe and his group once defended [[Brann Bronzebeard]] from a pack of [[Rothide gnolls]]. A spell was cast by one of his group incinerating half the gnolls, and the rest charged into the clearing with their swords and pikes and routed the remaining gnolls. He explained who he was, and welcomed Brann to the glades, and suggested he meet the [[Horde]] [[Ambassador Galavosh]] in the [[Undercity]].\r\nDartfall represents a Forsaken who remains a member of the organizaion despite evil that exists within it. He believes that they are ultimately good and that they can prove that to their former allies. In contrast [[Kegan Darkmar]] and [[Leonid Barthalomew the Revered]] represent fellow Forsaken who left the organization after noticing the evil inside of it, and [[Trevor]] plans to leave it because of the darkness.",},
			["Robe of Power"] = { content = "==Source==\r\nThis item is crafted by [[Tailoring|Tailors]] with a skill level of 190.\r\nThe components are:\r\n*2 [[Bolt of Mageweave|Bolts of Mageweave]]\r\n*2 [[Elemental Earth]]\r\n*2 [[Elemental Fire]]\r\n*2 [[Elemental Water]]\r\n*2 [[Elemental Air]]\r\n*2 [[Silken Thread]]s\r\nThe [[pattern]] is taught by the Tailoring trainer.",},
			["Robe of the Archmage"] = { content = "'''Robe of the Archmage''' (aka Robe of the Archmagi) is a [[mage]]-specific [[Tailoring|tailored]] item.\r\n==Background==\r\nThis silk robe comes in three colors, depending on alignment. It can be white (good alignment), gray (neutral) or black (evil). Many of these robes were destroyed when Dalaran fell, but there are still arcanists making them. The robe’s wearer, if an arcanist, gains several powers. Including armor bonuses and magic resistence. If an evil character dons a white robe, she immediately loses power. The reverse is true when a good character dons a black robe. If a good or evil character wears a gray robe, or a neutral character puts on a white or black robe, she loses some power. The loss of power lasts as long as the robes are worn and disappear when the robe is removed.\r\n==Source==\r\nThis item is crafted by [[Tailoring|tailors]] with a skill level of 300. Since it is [[bind on pickup]] and only wearable by Mages, there's little point in learning the pattern or crafting the robe unless the tailor is also a Mage. The components are:\r\n*12 Bolt of Runecloth\r\n*10 Essence of Air\r\n*10 Essence of Earth\r\n*10 Essence of Fire\r\n*10 Essence of Water\r\n*2 Rune Thread\r\nPattern: Robe of the Archmage drops off of [[Firebrand Pyromancer]]s in [[Blackrock Spire]]. Its estimated drop rate is 12%.\r\n==Notes==\r\nThe Robe of the Archmage granted a relatively large [[Spell damage]] bonus to casters playing prior to the release of ''[[The Burning Crusade]]''. The mana clicky was extremely effective for mana conservation; using that, than a gem, could get the mage through several thousand mana before needing to use [[Evocation]]. However, the Robe is not without it's downfall; it has relatively low stats compared to other similar-level Mage chestpieces such as the [[Zandalar Illusionist's Robe]] or [[Netherwind Robes]]. However, the five-minute ability to restore 375 to 625 mana effectively grants the robe an additional 25 to 41 [[intellect]] as far as its effect on the wearer's max mana is concerned. This robe was easily the best until upgrading to [[Enigma Vestments]] or another higher tier robe.",},
			["Robe of the Void"] = { content = "The '''Robe of the Void''' is a [[Warlock]] robe created by [[Warlock]] [[Tailoring|Tailor]]s with a skill of 300. The components are:\r\n*12 [[Bolt of Runecloth]]\r\n*20 [[Demonic Rune]]s\r\n*40 [[Felcloth]]\r\n*12 [[Essence of Fire]]\r\n*12 [[Essence of Undeath]]\r\n*2 [[Rune Thread]]\r\nPattern: Robe of the Void drops from [[Darkmaster Gandling]], final boss of [[Scholomance]] approximately 6% of the time.",},
			["Robe of Winter Night"] = { content = "The '''Robe of Winter Night''' is [[Tailoring|Tailor]]-made robe which provides a nice addition to any Warlock's, Shadow Priest's or Frost Mage's wardrobe.\r\n==Source==\r\nThe '''Robe of Winter Night''' is crafted by [[Tailoring|Tailors]] with a skill level of 285.\r\nThe components are:\r\n*10 [[Bolt of Runecloth]]\r\n*12 [[Felcloth]]\r\n*4 [[Essence of Undeath]]\r\n*4 [[Essence of Water]]\r\n*1 [[Rune Thread]]\r\nThe [[pattern]] drops off [[Cobalt Mageweaver]]s in [[Winterspring]]. The pattern is [[Bind on Pickup]].",},
			["Rob Pardo"] = { content = "'''Rob Pardo''' (alias '''EnoYls''') is the Vice President of Game Design at [[Blizzard Entertainment]]. Prior to his position at Blizzard, he was a producer at Interplay. He holds a degree from the University of California at Irvine.\r\nHe does not post frequently on the official forums.",},
			["Roc"] = { content = "'''Rocs''' are a type of birds that can be found in various regions of [[Azeroth]], including [[Sholazar Basin]], [[Tanaris]], [[Feralas]], [[Mount Hyjal]] and the [[Broken Isles]].\r\nThe rocs of the latter category differ vastly from those in the old world. Whereas the rocs of [[Kalimdor]] and [[Northrend]] mostly resemble [[eagle]]s or [[vulture]]s, the Broken Isle rocs are enormous, [[dread raven]]-like birds, created when [[harpy|harpies]] use their foul magics to corrupt the noble giant [[eagle]]s of the [[Skyhorn tribe]]. [[Bloodbeak]] is a roc found among the harpies on [[Exile's Reach]].\r\n==Notable==\r\n*Ala'washte\r\n*Crawshuk the Hungry\r\n*Emberwing\r\n*Goretalon Matriarch\r\n*Irewing\r\n*Skawn\r\n==Types==\r\nCarrion birds\r\n*Greater Rocs are found in [[Feralas]].\r\n* [[Fire Roc]]s and [[Searing Roc]]s are found in [[Tanaris]]. They are capable of throwing fireballs and appear with fire around them. According to [[Driz Plunkbow]], the fire rocs are extremely valuable due to their unique anatomy, and [[Alchemy|alchemists]] will pay expensively for their body parts (even though Driz may occasionally claim the rocs' innards to be [[dragon]] parts).\r\nBirds of prey\r\n*Goretalon Rocs are found in [[Sholazar Basin]]. They are led by the [[Goretalon Matriarch]].\r\n*Hyjal Rocs are found in [[Mount Hyjal]].\r\nBroken Isles\r\n*Coven Roc\r\n*Cursedwing Guardian\r\n*Fierce Hatchling\r\n*Fleshrender Roc\r\n==As a [[hunter]] pet==\r\nRocs can be either [[Bird of prey|birds of prey]] or [[carrion bird]]s. To see which group the roc belongs to, check the model. If it uses the eagle or giant roc model, it is a bird of prey. Otherwise, it's a carrion bird.\r\n==Notes and trivia==\r\n*[[Windroc]]s are [[kaliri]]-like birds native to [[Nagrand]], but it's unknown if they are a subspecies of roc or their own species, since rocs generally use a different model.\r\n*[[Deathroc]]s in [[Maldraxxus]] are stitched constructs.\r\n*[[Feralfen Druid]]s can assume a roc form.\r\n*[[Elerethe Renferal]] transforms into a \"[[Emerald Nightmare|Nightmare]] roc\" form during [[Elerethe Renferal (tactics)|her encounter]] in the [[Emerald Nightmare (instance)|Emerald Nightmare]] raid.\r\n*The is a gargantuan legendary bird in Middle Eastern and Indian mythology, said to be able to carry off and eat entire elephants. The roc is also the inspiration for the name of the [[arakkoa]]n sun goddess [[Rukhmar]].\r\n*Rocs in the [[Broken Isles]] use the same animations as [[dread raven]]s and [[skyscreamer]]s.\r\n*[[Roc Talon|A talon]] belonging to an ancient roc species found off of the southern coasts of [[Stranglethorn]] is exhibited in the [[Ironforge museum]]. It is believed to be that of an [[sun roc]], a creature that featured prominently in primitive [[Tauren mythology|tauren mythological cycles]].",},
			["Rockard"] = { content = "#REDIRECT [[Okril'lon Hold]]", redirect = "Okril'lon Hold",},
			["Rockbiter (mountain giant)"] = { content = ": ''Did you mean [[Rockbiter Weapon]], the temporary weapon buff granted by a [[Shaman]] ability?''\r\n'''Rockbiter''' is a level 45 [[quest giver]] located in a small camp south of the [[Ruins of Ravenwind]] in the [[contested]] territory of [[Feralas]].\r\nHe starts the quest The Giant Guardian.\r\nRockbiter is a direct reference to a character in the film [[Wikipedia:The NeverEnding Story (film)|The Neverending Story]].\r\nSee [[List of Feralas NPCs]].",},
			["Rockbiter Weapon"] = { content = "'''''A few pounds of extra weight is nothing but good on a weapon... especially if only the victim can feel its crush.'''''\r\n'' Imbue the Shaman's weapon, increasing its damage per second by '''XX''' (see [[Rockbiter Weapon|Description]] for different damage per second per each rank level). Lasts for 30 minutes.''\r\n===Use===\r\n*Casting Time: Instant Cast\r\n*Range: Not Applicable\r\n*Duration: 30 minutes\r\n*Cooldown: Global Spell Cooldown\r\n===Limitations===\r\n*Self-casting only.\r\n===Talents===\r\nTalents that can improve the weapon [[buff]]:\r\n====[[Windfury Weapon|Windfury]] vs [[Rockbiter Weapon|Rockbiter]] vs [[Flametongue Weapon|Flametongue]] vs [[Frostbrand Weapon|Frostbrand]]====\r\n*'''Windfury''' is by far the best end-game enhancement enchant. It adds a flat +56% boost(talented) to what would be a gear boosted high DPS amount. Windfury is not as good if that DPS amount isn't gear boosted, which is where the other weapon attacks come in.\r\n*'''Rockbiter''' is the poor shaman's best friend. It is only superior in DPS to Windfury (both at level 60) if the base DPS of the shaman was less than 75 (Base DPS = Weapon DPS + Atk power DPS).\r\n*'''Flametongue''' is the elemental shaman's weapon enchant. Does exceptional damage on an incredibly fast 1 hander as the +10% spell damage effect does not scale with weapon speed.\r\n*'''Frostbrand''' is a great enchant for a poorly equipped enhancement shaman or any resto shaman. It procs off of stormstrike, making it acceptable. Its main bonus is its snare, so it is often used by elemental or resto shamans who aren't looking to kill, just to maim.",},
			["Rocket-Chief Fuselage"] = { content = "'''Rocket-Chief Fuselage''' is a level 70 [[quest giver]] located at [[Area 52]] in the [[contested]] territory of [[Netherstorm]].\r\nHe starts the following quests:\r\n* You're Hired!\r\n* Invaluable Asset Zapping\r\n* Report to Engineering\r\n* Doctor Vomisa, Ph.T.",},
			["Rockfist"] = { content = "==Source==\r\nThis item previously dropped from [[Phalanx]] a boss inside the [[instance]] '''[[Blackrock Depths]]'''. However it was removed from the game.",},
			["Rockhide Strongfish"] = { content = "==Source==\r\n'''Rockhide Strongfish''' is a one-handed mace shaped like a fish, which can be fished during the [[Stranglethorn Fishing Extravaganza]]. It has a low drop-rate from schools of tastyfish, and as it bind on equip it can be sold to other players.",},
			["Rocklance"] = { content = "'''Rocklance''' is a level 17 [[elite]] [[rare mob]] [[centaur]] found in the [[Barrens]].",},
			["Rocknot"] = { content = "#REDIRECT [[Private Rocknot]]", redirect = "Private Rocknot",},
			["Rockscale Cod"] = { content = "'''Rockscale Cod''' is a common fish, which offers no special bonuses besides the regeneration of [[Health]] when eaten.\r\n==Source==\r\nThis fish is cooked by [[Cooking|Cooks]] with a skill level of 175.\r\nThe components are:\r\n*1 Raw Rockscale Cod\r\nRecipe: Rockscale Cod is sold by various cooks and fisherman, including Lizbeth Cromwell in [[Undercity]] and Tansy Puddlefizz in [[Ironforge]].",},
			["Rocktusk Farm"] = { content = "Situated in [[Durotar]] just outside the gates of [[Orgrimmar]], '''Rocktusk Farm''''s owners feel fairly safe as they [[pig farm|raise]] their swine to provide sustenance for the [[Horde]]. Apparently this farm is being used by two [[Blood Elves]] as home.",},
			["Rockwing Gargoyle"] = { content = "==General Information==\r\n*Level: 57-58 (Elite)\r\n*[[:Category:Zones|Location]]: [[Stratholme]] in the [[Eastern Plaguelands]]\r\n*[[Creature type|Type]]: [[Creature type|Undead]]\r\n==Background==\r\nThe gargoyles were first utilized by the [[Scourge]] during the [[Third War]] and are still found in the areas under Scourge control, such as the Rockwing Gargoyles that patrol the dead-side of Stratholme. \r\nThey are general [[mob]] enemies groups will encounter while inside the [[instance]] and will spawn when intruders are spotted by the [[Eye of Naxxramas]].\r\n==Attacks and Abilities==\r\n* '''Fear''' - Causes all party members within melee range to flee in fear for 5 seconds.\r\n==Strategies==\r\nWhen fighting gargoyles it is important to always pull them away from other [[mob|mobs]] and fight them as far away as possible. It is also a good idea to keep them stunned as much of the fight as possible. When you are fighting two or more, try to keep one [[Shackle|shackled]] until the first is dealt with. In multiple pulls (where other types of mobs are involved) these must be a priority.\r\n==Reward==\r\nReputation: Argent Dawn Reputation increase\r\n==Sources==\r\n* at",},
			["Rock Borer"] = { content = "'''Rock Borer''' can be found in [[Desolace]] and [[Maraudon]] .\r\n==Drops == \r\n \r\n0.04% Chance of an [[epic]] drop.\r\n0.26% Chance of a [[rare]] drop.\r\n5.05% Chance of an [[Uncommon]] drop.\r\n0.07% Chance of a [[common]] drop.\r\n0.07% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Rock Elemental"] = { content = "'''Rock Elemental''' can be found in [[Badlands]] .\r\n==Drops == \r\n \r\n0.02% Chance of a [[rare]] drop.\r\n0.24% Chance of an [[Uncommon]] drop.\r\n0.01% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Rock Flayer"] = { content = "#REDIRECT [[Rock flayer]]", redirect = "Rock flayer",},
			["Rock Flayers"] = { content = "#REDIRECT [[Rock flayer]]", redirect = "Rock flayer",},
			["Rock of Durotan"] = { content = "The '''Rock of Durotan''' is a monument located in southern [[Alterac Valley]] near the [[Horde]] entrance, northeast of [[Frostwolf Keep]]. It is the marker over the grave of [[Durotan]], chieftain of the [[Frostwolf Clan]] and father of [[Thrall]].\r\n==Plaque on the Rock of Durotan==\r\nThe memorial plaque on the Rock reads:\r\n''Here lies Durotan - first Chieftain of the Frostwolf Clan, and father of our honored Warchief, Thrall. He was the bravest of our kind - betrayed by those who would see our people enslaved. Durotan gave his life that our freedom might be gained. We honor him - and the legacy he passed onto us through his son.''\r\n''-[[Drek'Thar]], Far Seer of the Frostwolves''",},
			["Rock Stalker"] = { content = "'''Rock Stalker''' can be found in [[Silithus]] .\r\n'''Rock Stalker''' can be tamed by a [[hunter]]. \r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.02% Chance of a [[rare]] drop.\r\n0.58% Chance of an [[Uncommon]] drop.\r\n0.04% Chance of a [[common]] drop.\r\n0.01% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Rod"] = { content = "In [[World of Warcraft]], a '''rod''' can mean several things:\r\n# A [[weapon]] variant of a [[staff]].\r\n# A base item created by a [[Blacksmith]] that only has use for [[Enchanting]].\r\n#* A tool used by [[Enchanter]]s for the Enchanting [[profession]] made from base rods from [[Blacksmithing]].\r\n# An [[off-hand]] item.\r\n# A [[quest]] item.",},
			["Rogthur"] = { content = "Rogthur is a dwarven rifleman, and a friend of [[Jaeson]].",},
			["Rogue"] = { content = "The '''rogue''' is a lightly armored [[class]] that specializes in [[melee]] [[damage (role)|damage]]. Rogue combat centers around using [[instant]] attacks to build [[combo point]]s, which are used to unleash more powerful [[finishing move]]s on the target. With their distinctive [[stealth]] ability, rogues are capable of sneaking through the shadows unnoticed, dispatching their foe in a whirl of attacks, then [[vanish]]ing from sight. Rogues can also stifle their opponents with a variety of [[poisons]], [[bleed]]s, [[stun]]s, and other disabling effects. Rogues are renowned for their elusiveness, having a number of defensive abilities that make them adept at escaping combat when the odds turn against them. Many of the rogue's abilities depend on their ever-replenishing pool of [[energy]].\r\nThe rogue's primary attributes are [[agility]] and [[stamina]], but also place great value in their secondary stats ([[haste]], [[critical strike]], [[mastery]], and [[versatility]]). Rogues can wear only leather or cloth armor and are unable to use shields. They can only wield one-handed weapons (daggers, swords, axes, maces, and fist weapons), but are able to [[dual wield]] two of these weapons at a time.\r\nTheir role in the world is that of an elite assassin, sneaky pickpocket, waylaying bandit and more. Some aren't magic users but use magic items. Others utilize the [[Void]] to attain relative invisibility, with some being able to instantly become completely invisible even in broad daylight.\r\n==Class overview==\r\n''Rogues fend for themselves, looking for fights in which they dictate the terms. They’re the shadows in the night that remain unseen until the right moment comes to strike—then they dispatch an opponent with quick blade work or a deadly toxin snuck acutely into the bloodstream. Rogues are opportunistic thieves, bandits, and assassins, but there’s an unparalleled art to what they do.''\r\n===Game guide===\r\n''For rogues, the only code is the contract, and their honor is purchased in gold. Free from the constraints of a conscience, these mercenaries rely on brutal and efficient tactics. Lethal assassins and masters of stealth, they will approach their marks from behind, piercing a vital organ and vanishing into the shadows before the victim hits the ground. Rogues can dip their weapons in paralyzing toxins that render foes unable to defend themselves. These silent stalkers wear leather armor so they can move unencumbered, ensuring that they land the first strike.''\r\n''With the rogue’s poisons and speed, the first strike is often the last step before the killing blow.''\r\n===Creation screen description===\r\n''Rogues are most successful when their deeds never come to light. Fond of poisons and silent projectile weapons, rogues rely on a blend of stealth and minor mysticism. Usually in the employ of rich nobles or local governments, the rogue redistributes wealth or eliminates designated targets. A rogue's allegiance lasts only as long as the latest contract.''\r\n''Rogues often serve as assassins or scouts, though many are lone wolves. Rogues can often sneak around enemies or attack an opponent from behind to try and finish them off quickly.''\r\n===Classic guide===\r\n''Fans of knives and poisons, Rogues stalk their foes from the silent dark, always ready to slit throats and pick the pockets of the unwary.''\r\n==Background==\r\nFor as long as there were dark alleys and needs for dark services, there have been rogues, and thus they are one of the oldest professions in Azeroth. Rogues are a diverse class, and they are typically made up from the dregs of society — cutthroats, pirates, robbers, and low-lifes. The only code rogues live by is the contract, and their word is only as good as the money their services are bought for. The diverse aspects of their trade requires rogues to be well versed in lockpicking, toxicology, rudimentary alchemy and brawling. In combat, rogues rely on the element of surprise, and tactics which are regarded by most as vile and cowardly. They are rarely seen entering a fight without weapons laced in poisons and ample supplies of everything from bombs to elixirs in their backpacks. Their attacks concentrate on weak points in the body in an attempt to finish fights brutally and quickly. Rogues play prominent roles in every aspect of society — albeit, they will rarely be written in history books because their involvements will be largely unknown to the common person, but they are always there, greatly affecting the flow of events from the shadows.\r\nFrom the high-contract assassin hired in secret by respected noblemen to the lowly street mugger, rogues are the ones called upon when maintaining the status quo requires a questionable solution — and by fulfilling it, are branded as outcasts by the very society that calls upon their service.\r\nIn Azeroth several rogues are free [[agent]]s, though most prefer to join a guild for safety and ease of employment. [[Ravenholdt]] and the [[Syndicate]] are examples of said guilds. Other recognized rogue organizations include the [[Shattered Hand clan|Shattered Hand]], the [[Deathstalkers]] and [[SI:7]].\r\n==Races==\r\nThe following races can play the rogue class:\r\nAll races except [[draenei (playable)|draenei]] and [[tauren (playable)|tauren]], as well as their [[allied race]] offshoots, [[Lightforged draenei (playable)|Lightforged draenei]] and [[Highmountain tauren (playable)|Highmountain tauren]], can play as rogues. The cloven hooves possessed by these races may well serve as an impediment to the rogue's stealthy ways, although members of these races may choose not to embrace the shadowy path of the rogue for more philosophical reasons. The mythical [[tauren rogue]] is a persistent joke.\r\n==Attributes==\r\nRogues depend on the following primary attributes:\r\n* [[Agility]] - Increases [[attack power]], [[critical strike]], and [[dodge]]. Agility is a rogue's most important stat.\r\n* [[Stamina]] - Increases [[health]]. While not a priority for rogues compared to other stats, stamina is necessary to stay alive. Most rogue gear pairs agility with stamina.\r\nRogues also desire the following secondary attributes:\r\n* [[Attack power]] - Increases the [[damage per second]] of melee weapons. This is mainly derived from agility (2 AP), but is sometimes found on items as a raw stat.\r\n* [[Haste]] - Increases [[attack speed]] and makes [[energy]] recover more quickly.\r\n* [[Critical strike]] - Improves the chance that attacks do extra damage.\r\n* [[Versatility]] - Increases overall damage done and decreases damage taken for increased survivability.\r\n* [[Mastery]] - Improves mastery ability ([[Mastery: Potent Poisons]], [[Mastery: Main Gauche]], or [[Mastery: Executioner]], depending on spec).\r\n[[Attributes|Strength]], [[Attributes|intellect]] and related caster stats give no benefits for rogues.\r\n==Equipment==\r\n \r\nRogues can use five types of melee weapons: [[daggers]], [[fist weapon]]s, one-handed [[mace]]s, one-handed [[sword]]s, and one-handed [[axe]]s. They [[dual wield]], which means they can equip a weapon in each hand when most classes can equip only one; the trade-off, however, is an increased chance to miss with each weapon and reduced damage from the off-hand. Rogues cannot equip two-handed weapons or [[shield]]s. A rogue's choice of weapon typically reflects their talent specialization: the [[rogue talents|Assassination]] and [[rogue talents|Subtlety]] trees favor the use of daggers, while the Outlaw tree favors the use of swords, axes, maces, and fist weapons. In order to optimize damage, rogues must pay attention to the [[weapon speed]] and [[damage per second]] of the weapon in each hand.\r\nRogues wear [[leather]] armor. Leather is weaker than the [[mail]] and [[plate]] worn by other melee classes, making rogues more \"[[squishy]].\" To compensate for this, rogues have an array of defensive abilities to improve their survivability, including [[Evasion]], [[Feint]], [[Sprint]], [[Vanish]], and [[Cloak of Shadows]]. Rogues can also wear cloth, but this is not recommended, as virtually all cloth items are intended for casters. Rogues also benefit from [[Leather Specialization (rogue)]] when wearing only leather.\r\n===Melee combat===\r\nRogues specialize in [[melee]] combat. A large portion of a rogue's damage comes from [[auto-attack]]s and [[poisons]], but they can increase their damage using a variety of offensive abilities. Many abilities require [[energy]], a [[resource]] with a fixed capacity that is spent quickly and regenerates quickly. Certain abilities are [[instant]] attacks that add up to five [[combo point]]s to the target (\"builders\"); these combo points can then be used to execute [[finishing move]]s that last longer or are more powerful per combo point (\"finishers\"). Rogues also have powerful opening moves that can only be used from [[stealth]] (\"openers\"), as well as [[cooldown]]-restricted abilities that greatly increase damage for a short period of time (\"cooldowns\"). The following are examples of offensive rogue abilities categorized according to this terminology:\r\n* Openers: [[Ambush]], [[Garrote]], [[Cheap Shot]], [[Shadowstrike (rogue ability)]]\r\n* Builders: [[Backstab]], [[Mutilate]], [[Hemorrhage]], [[Sinister Strike]], [[Pistol Shot]]\r\n* Finishers: [[Eviscerate]], [[Slice and Dice]], [[Rupture]], [[Envenom]], [[Dispatch]], [[Roll the Bones]]\r\n* Cooldowns: [[Vendetta]], [[Killing Spree]], [[Adrenaline Rush]], [[Shadow Blades]], [[Exsanguinate]]\r\n===Stealth===\r\nRogues have the ability to enter [[stealth]], which makes them essentially invisible to enemies their level and lower. Stealthed rogues are detectable at close range, though will remain stealthed and appear translucent. Many rogue abilities require stealth, and others require being behind the target, which is often achievable only in stealth. Some abilities, notably [[Sprint]] and [[Distract]], interact well with stealth, but normally using any ability or performing any action will break stealth.\r\nStealth opens up a range of tactics and roles for rogues. Groups may rely on a rogue's stealth ability to [[scout]] dungeons, and to use [[Sap]] for added [[crowd control]]. In PvP, stealth combined with disables and burst damage gives an element of surprise that can be especially effective against cloth-wearers. Stealth also enables rogues to bypass mobs that other classes would be forced to engage, which is useful for solo play.\r\nIn addition to stealth, rogues have a number of other \"sneaky\" abilities, such as the ability to [[Pick Pocket|pickpocket]] mobs, and [[Pick Lock|pick locks]] (breaks stealth).\r\nMajor glyphs have been removed, but the cooldown for [[Stealth]] has been reduced for the entire class, mimicking the effect that was provided by [[Glyph of Stealth]]. Similarly, [[Pick Lock]] is now faster and mimics the effect from [[Glyph of Pick Lock]].\r\nRogues no longer have access to [[Disarm Trap]] and [[Detect Traps]]. [[Glyph of Detection]] still exists but does not work on traps.\r\n===Poisons===\r\nRogues are the only class that can coat their weapons with [[poisons]]. Poisons generally either cause damage to the target (either instantly or as [[damage over time]]) or other hindering effects (slowing the target, reducing the effectiveness of healing on the target). They are applied as a buff to the player, lasting for one hour before they need to be reapplied; one Lethal and one Non-Lethal poison can be applied at the same time, and faster attacks (through faster weapon speed and attack speed, higher haste, and greater energy regeneration) will cause the poison to [[proc]] more often. Poisons are a core component of the Assassination spec and should always be used.\r\nPoisons are no longer available to all three specs and can now only be used by Assassination rogues.\r\nPoisons are now no longer items, but individual [[buff]]s that can be applied to the weapons by the rogue. Also [[poison vendor]]s no longer sell poisons.\r\n===Disabling effects===\r\nRogues have a number of ways to harm their enemies aside from raw damage. Note that [[diminishing returns]] apply to all effects that cause players to lose control of their character (stun, incapacitate, fear, etc.), as well as to status effects applied to NPCs.\r\n* Stun: [[Cheap Shot]], [[Kidney Shot]], [[Between the Eyes]], [[Shadowstrike (rogue ability)]] (when paired with [[Strike from the Shadows]])\r\n* Incapacitate: [[Sap]], [[Gouge]], [[Parley]]\r\n* Disorient: [[Blind]]\r\n* Silence: [[Garrote]] (from stealth)\r\n* Interrupt: [[Kick]]\r\n[[Dismantle]] and other [[Disarm]] abilities have been completely removed.\r\n===Mobility, elusiveness and survivability===\r\nRogues are characterized by their high mobility as well as their adeptness at quickly engaging, disengaging or outright escaping from a skirmish. These two elements form a significant part of the rogue's core playstyle across all three specs, enabling them to use the battleground to their advantage, strike at an opportune moment and utilize their speed and abilities not only to attack from an advantageous position and stick to their targets, but also to evade pursuers, dodge targeted attacks, and mitigate ground effects and area of effect damage.\r\nThe rogue's use of stealth and their ability to vanish in the middle of combat aid in their ability to stay alive and oftentimes escape from a dire situation, but they also open up a number of offensive tools; for example, attacks that are only usable from [[Stealth]] such as [[Ambush]] or [[Shadowstrike (rogue ability)]] deal high damage, which can be increased further by adding the talent [[Nightstalker]]. [[Vanish]] is also utilized as a means of increasing damage output in the middle of a fight, most notably for Assassination and Subtlety rogues, as this enables them to use their stealth-only abilities and proc the damage increase from [[Nightstalker]].\r\nMobility and elusiveness are among the rogue's most important tools, as vital as their ability to deal heavy damage in a small window of time and quickly dispatch their targets. Numerous talents and abilities fall under one or the other of these traits; they are listed as follows:\r\n* [[Sprint]] increases running speed by 70% for 8 seconds (60-second cooldown). It is usable both in and out of [[Stealth]].\r\n** [[Worgen]] rogues are also able to use their racial ability, [[Darkflight]], which increases movement speed by 40% for 10 seconds and can be treated as a longer but slower additional [[Sprint]]. The two abilities do not stack on top of each other, meaning that you will only receive the 70% movement speed bonus from [[Sprint]] if both abilities are active at the same time.\r\n* [[Vanish]] allows a rogue to disappear from combat and enter stealth instantly (2-minute cooldown). Stealth cannot be broken by enemy attacks or other harmful effects for 3 seconds after triggering [[Vanish]], and movement-impairing effects that were applied to your character will be removed. In a dungeon or raid setting, casting [[Vanish]] can be utilized as part of an offensive rotation, as well as to drop aggro if you come under attack.\r\n* [[Tricks of the Trade]] is meant for use in dungeons, raids or other PvE groups, and will redirect any [[threat]] that you generate, applying it to a selected friendly player; when cast, the player will be marked for 30 seconds, and the spell will trigger after your first attack, with the effects lasting for 6 seconds. This ability is best-utilized proactively instead of reactively, as you may not immediately lose [[aggro]] from enemy NPCs if you use it when you are already under attack.\r\n* [[Fleet Footed]] is a class-wide passive trait that increases movement speed by 15%.\r\n* [[Hit and Run]] is a level 30 passive talent for Outlaw rogues that increases movement speed by an additional 15%.\r\n* [[Nightstalker]] is a level 30 passive talent for Assassination and Subtlety rogues, with different effects for each:\r\n** Increases movement speed by 20% while in [[Stealth]] or while [[Shadow Dance]] is active, and increases damage dealt by your abilities while in stealth by 12%. (Subtlety)\r\n** Increases movement speed by 20% while in [[Stealth]], and increases damage dealt by your abilities while in stealth by 50%. (Assassination)\r\n* [[Grappling Hook]] is a level 30 talent for Outlaw rogues that allows you to quickly grapple to a targeted location within 40 yards of your character (30-second cooldown). It can be used in mid-air to limit or avoid fall damage, and can also be used to pull your character to areas that are higher or lower in elevation, but can sometimes not be used on sloped or bumpy terrain and as such, is most reliable on flat ground.\r\n* [[Shadowstep]] can be used by Subtlety and Assassination rogues to quickly teleport behind a selected target within 20 yards and can be utilized while in or out of stealth (30-second cooldown). Movement speed is also increased by 20% for 2 seconds after the teleport.\r\n* [[Shadowstrike (rogue ability)]] allows Subtlety rogues to attack from [[Stealth]] and teleport behind their target; it has a range of 15 yards and consumes 40 energy, generating 1 combo point (2 with [[Premeditation]]).\r\n* [[Cloak of Shadows]] removes all harmful spell effects, as well as granting immunity from these effects for 5 seconds (90-second cooldown).\r\n* [[Feint]] is a powerful damage mitigation tool that reduces area-of-effect damage by 50% for 5 seconds; consumes 20 energy.\r\n** [[Elusiveness (rogue talent)]] is a level 60 talent available to all specs that augments [[Feint]], causing it to also reduce damage from all other sources (i.e., non area-of-effect damage) by 30%.\r\n* [[Crimson Vial]] restores 30% of your maximum health over 6 seconds, costing 30 energy (30-second cooldown).\r\n** [[Iron Stomach]] is a level 60 passive talent for Outlaw rogues that increases the amount of health restored by [[Crimson Vial]], Healthstones and potions by 30%.\r\n* [[Cheat Death]] is a level 60 passive talent for all specs that causes fatal attacks to instead lower you to 7% of your maximum health; once triggered, you will take 85% reduced damage for 3 seconds and cannot trigger it again for 2 minutes. [[Cheat Death]] will not activate if you are hit by an attack that deals damage greater than 200% of your maximum health; as an example, if your maximum health is 200,000, then the spell will not trigger if you are hit by an attack that deals more than 400,000 damage.\r\n* A pair of cooldowns can help rogues to temporarily tank NPCs in an emergency situation or to weather an attack from multiple targets or single, dangerous targets:\r\n** [[Evasion]] increases your [[dodge]] chance by 100% for 10 seconds, available to Assassination and Subtlety rogues (2-minute cooldown).\r\n** [[Riposte (rogue ability)]] increases your [[parry]] chance by 100% for 10 seconds, available to Outlaw rogues; when active, every attack that you parry will return damage to the attacker, no more than once per second (2-minute cooldown).\r\n* Major glyphs have been removed. [[Shadowstep]] is no longer available for all specs and can only be used by Assassination or Subtlety rogues; Outlaw rogues are the only spec that can utilize [[Grappling Hook]].\r\n* [[Recuperate]] has been removed, and is now effectively replaced by [[Crimson Vial]].\r\n==Specializations==\r\n''For a full list of specialization abilities, see [[Rogue abilities|Rogue abilities]]''\r\nAt level 10 rogues may choose a [[specialization]]. All rogue specializations are themed around a certain type of historical scoundrel and primarily fulfill a [[melee]] [[damage (role)|damage]] role:\r\n===Assassination===\r\n '''''A deadly master of poisons who dispatches victims with vicious dagger strikes.'''''\r\nMuch of an Assassination rogue's toolkit is based on heavy damage over time through poison effects, rapid auto-attacks (assassination rogues require daggers in both hands to utilize many of their abilities), and abilities that cause [[bleed]] damage. Combat centers upon maintaining and managing bleed effects on your targets, focusing on the amount of time left on each bleed and maximizing your damage output by ensuring that they are constantly in effect. The use of poisons is exclusive and central to the assassination spec, forming a significant part of its damage output in unison with [[Envenom]], [[Venomous Wounds]] and [[Mastery: Potent Poisons]].\r\nAs their name suggests, Assassination rogues are themed around assassins: ''One of the favorite tools of the assassin is a pair of daggers coated with vicious poisons. The damage they inflict is deceiving at first—the initial wounds often seem survivable, even superficial. Then the toxins set about their business. Wounds don’t close, and blood loss continues unabated. Assassins begin their work stealthily, choosing their targets and methods of engagement carefully—but once committed to a course of action, they stick to their target until the job is done rather than disappearing into the shadows to avoid their quarry’s blows.''\r\n'''Signature Abilities & Talents'''\r\n* [[Mutilate]]\r\n* [[Deadly Poison]]\r\n* [[Garrote]]\r\n* [[Envenom]]\r\n* [[Rupture]]\r\n* [[Venomous Wounds]]\r\n* [[Seal Fate]]\r\n* [[Mastery: Potent Poisons]]\r\n* [[Hemorrhage]]\r\n* [[Exsanguinate]]\r\n* [[Vendetta]]\r\n===Outlaw===\r\n '''''A swashbuckler who uses agility and guile to stand toe-to-toe with enemies.'''''\r\nOutlaw rogues focus on consistent weapon (auto-attack) damage and cleave damage in multi-target situations via [[Blade Flurry]] to provide sustained DPS. Rather than requiring stealth and relying on powerful openers, you can simply run up to most targets and quickly hack away at them, building combo points with [[Saber Slash]] and [[Pistol Shot]] while maintaining personal buffs through the use of [[Roll the Bones]]; these enhancements are random and will either augment the characteristics of some of your abilities, reduce your cooldown times, or boost your secondary stats. As such, Outlaw tends to be the best spec for fast leveling, since you can move quickly from one enemy to the next with very little downtime instead of trying to sneak up on enemies.\r\nOutlaw rogues are mainly themed around pirates: ''Outlaw rogues are the unscrupulous scoundrels of Azeroth. Operating outside the law, they bend the rules and distort the truth to get what they need. While they share plenty in common with other rogues, these outlaws have little use for tact or discretion, happy to engage in a tavern brawl or spontaneous duel, rarely patient enough to wait in stealth for the opportune time to engage. To survive in such a world, outlaws must become master swordsmen in toe-to-toe combat—and they can’t shy away from fighting dirty. If blade fails to cut too deeply, the outlaw takes advantage of a concealed pistol, catching the enemy by surprise with a quick blast.''\r\n'''Signature Abilities & Talents'''\r\n*[[Sinister Strike]]\r\n* [[Pistol Shot]]\r\n*[[Dispatch]]\r\n* [[Between the Eyes]]\r\n* [[Roll the Bones]]\r\n* [[Grappling Hook]]\r\n* [[Ghostly Strike]]\r\n* [[Slice and Dice]]\r\n*[[Blade Flurry]]\r\n* [[Mastery: Main Gauche]]\r\n* [[Adrenaline Rush]]\r\n===Subtlety===\r\n '''''A dark stalker who leaps from the shadows to ambush his or her unsuspecting prey.'''''\r\nSubtlety rogues like to stay in the shadows. This spec is based on moving quickly and staying hidden, choosing to strike at the most advantageous moment. Once they have initiated their attack, a subtlety rogue focuses on accumulating as many combo points as possible in a short amount of time, relying on high burst damage at the beginning of combat and pooling [[energy]] to maximize damage during phases of [[Shadow Dance]] as a fight progresses.\r\nSubtlety is the archetypal (and infamous) PvP rogue spec, appearing from nowhere to overwhelm and defeat a player in a matter of seconds using a combination of incapacitating abilities and deadly damage. Subtlety rogues try to avoid a straight fight; their greatest strength is centered on their ability to catch their prey by surprise, and if they are unable to defeat the opponent in their initial burst, then they will often slip back into the shadows before their opponent is able to rally.\r\nSubtlety rogues are mainly themed around ninjas: ''Subtlety rogues are the masters of the shadows, and they strike unseen. They don’t have the lethal poison-tipped daggers of the assassin or the brawling prowess of the outlaw, but their acumen on the battlefield and ability to hide in plain sight are unrivaled. Some claim the art of subtlety looks like malevolent shadow magic—but no matter from where their power is derived, these rogues are capable of performing devastating assaults on their enemies, slipping away unharmed to strike again without detection. Most rogues train their entire lives to learn how to walk in the shadows—subtlety rogues were born there.''\r\n'''Signature Abilities & Talents'''\r\n* [[Shadow Dance]]\r\n* [[Backstab]]\r\n* [[Eviscerate]]\r\n* [[Nightblade (rogue ability)]]\r\n* [[Shuriken Storm]]\r\n* [[Shadowstrike (rogue ability)]]\r\n* [[Shadow Techniques]]\r\n* [[Symbols of Death]]\r\n* [[Deepening Shadows]]\r\n* [[Mastery: Executioner]]\r\n* [[Shadow Blades]]\r\n* [[Master of Subtlety]]\r\n* [[Subterfuge]]\r\n* [[Premeditation]]\r\n* [[Master of Shadows]]\r\n==General role in raids and dungeons==\r\nAs with all damage-dealers, the rogue's main priority in [[raid]]ing and PvE group settings is to maximize [[DPS]] while staying alive. In dungeons, rogues may be asked to preemptively disable certain enemies with [[Sap]], [[Blind]] or [[Parley]] before the party enters combat. More frequently, rogues may also be tasked with [[interrupt]]ing important spells during some encounters, notably against bosses such as [[Xhul'horac]], [[Kel'Thuzad (tactics)|Kel'Thuzad]] and [[General Vezax]]. General raid etiquette will also require you to handle any other responsibilities that your raid leader may ask of you, as well as to provide your own [[flask]]s, food, [[potions]] and other supplies to maximize your buffs.\r\nIn general, rogues should not expect to be healed on a regular basis, meaning that you must oftentimes fend for yourself and rely on your mobility, positioning, and prudent use of abilities such as [[Sprint]], [[Shadowstep]], [[Grappling Hook]], [[Cloak of Shadows]] and [[Feint]] to quickly move away from targeted attacks and ground effects and to minimize incoming damage. Utilize [[Crimson Vial]], potions and [[healthstones]] as needed, and especially in encounters with a large number of enemies, be sure to use [[Tricks of the Trade]] to transfer [[threat]] to one of your [[tank]]s and reduce the chances of taking [[aggro]]. If you come under attack, drop aggro with [[Vanish]], or mitigate damage by using [[Riposte (rogue ability)]] or [[Evasion]]. As a melee class, rogues will almost always find themselves in the middle of the action, usually alongside tanks, and will need to be wary of area of effect attacks and damaging auras; you can expect to come under fire from multiple directions, and must strike a balance between avoiding attacks while maintaining your own attacks and remaining close enough to your targets to deal as much damage as possible.\r\n==Notes and trivia==\r\n*In ''[[Warcraft: Orcs & Humans ranks|Warcraft: Orcs & Humans]]'' and ''[[Warcraft II ranks|Warcraft II: Tides of Darkness]]'', it is a rank you can achieve.\r\n*During early development of ''[[World of Warcraft]]'', the Rogue class was originally called [[Assassin]].\r\n*During the early beta days of ''[[World of Warcraft]]'' rogues could wear [[Shield|bucklers]].\r\n*During the alpha, the following items taught rogues how to disguise themselves as various humanoid mobs: [[Knowledge: South Seas Pirate Disguise]], [[Knowledge: Stonesplinter Disguise]], [[Knowledge: Dalaran Wizard Disguise]], [[Knowledge: Dark Iron Dwarf Disguise]], [[Knowledge: Syndicate Disguise]] and [[Knowledge: Defias Disguise]].\r\n==See also==\r\n* [[Rouge]] - A common (and often intentional) misspelling of the word 'rogue', arguably a sub-class in itself.\r\n* [[Rogue professions]] - Discussion of professions as they relate to the rogue class.",},
			["Roguefeather Den"] = { content = "A cave filled with aggressive [[harpies]]. They zealously guard their gathered foodstuffs in the back of the den.",},
			["Rogues' Quarter"] = { content = "The '''Rogues' Quarter''' is located in the southeast corner of the [[Undercity]]. It is home of many of the [[Forsaken]]'s more shady characters, the rogues' guild, and a few profession trainers.\r\nFacilities:\r\n* [[Rogue]] trainers.\r\n* [[Poison]] vendor\r\n* [[Leatherworking]] trainers\r\n* [[Skinning]] trainers\r\n* [[Engineering]] trainers\r\n* [[First Aid]] trainers",},
			["Rogues"] = { content = "#REDIRECT [[Rogue]]", redirect = "Rogue",},
			["Rogues Do it from Behind"] = { content = "\"'''Rogues Do it from Behind'''\" is the third song by [[Level 80 Elite Tauren Chieftain]], which made its live debut on August 4, 2007 at the year's annual [[BlizzCon]]. The song contains comedic double entendres for both the prowess of the [[rogue]] [[class]], and anal sex.\r\n==Cultural references==\r\n* [[One shot]]\r\n* [[Mage]]\r\n* [[Priest]]\r\n* [[Player vs Player]]\r\n* [[Newbie]]\r\n* [[Rogue]]\r\n* [[Bloodfang Armor]]\r\n* [[Bonescythe Armor]]\r\n* [[Netherblade]]\r\n* [[Warlock]]\r\n* [[Perdition's Blade]]\r\n* [[Sinister Strike]]\r\n* [[Eviscerate]]\r\n* [[Cheap Shot]]\r\n* [[Backstab]]\r\n* [[Slice and Dice]]\r\n* [[Ambush]]\r\n* [[Rupture]]\r\n* [[Blind]]\r\n* [[Gank]]\r\n* [[Ranking]]\r\n* [[Dagger]]\r\n* [[Mace]]\r\n* [[Sword]]\r\n* [[Alliance]]\r\n* [[Horde]]\r\n* [[wikipedia:Ice-T|Ice-T]]\r\n* [[wikipedia:O.G. Original Gangster|O.G. Original Gangster]]\r\n* [[Corpse camping]]",},
			["Rogue abilities"] = { content = "'''Rogues abilities''' are used in order to both deal damage and attempt to avoid it.\r\nOpening Moves are used as the first move in an encounter, and require the rogue to be stealthed to use.\r\nCombo Moves are intermediate moves, typically used to build up extra combo points. Some may also be used as opening moves, such as [[Backstab]] - particularly when [[stealth]] isn't available.\r\nFinishing Moves are moves which use up all of the rogue's combo points, typically dealing devastating damage or severely debilitating their foe.\r\nIn addition to these combat moves, rogues have a number of other abilities, in particular those in the Subtlety field such as [[Stealth]] and [[Distract]].\r\nSee [[Detailed Rogue Abilities]] for a greater description on all abilities.\r\n==Abilities table==\r\n''Note for [[Combo Point]]s:''\r\n* +x indicates the move will award x combo points\r\n* 0 indicates the move will reset the combo points back to zero\r\n* - indicates the move doesn't use combo points in any form\r\nThe following tables lists all of the Rogue's non-passive abilities, along with the first level at which the ability can be attained. \r\n==Abilities by type==\r\n<div style=\"float: left; width: 15em\">\r\n===Opening Moves===\r\n*[[Ambush]]\r\n*[[Cheap Shot]]\r\n*[[Garrote]]\r\n*[[Premeditation]]\r\n*[[Sap]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Finishing Moves===\r\n*[[Deadly Throw]]\r\n*[[Envenom]]\r\n*[[Eviscerate]]\r\n*[[Expose Armor]]\r\n*[[Kidney Shot]]\r\n*[[Rupture]]\r\n*[[Slice and Dice]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Positional===\r\n*[[Backstab]]\r\n*[[Ambush]]\r\n*[[Garrote]]\r\n*[[Mutilate]]\r\n*[[Gouge]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Additional Damage===\r\n*[[Ambush]]\r\n*[[Sinister Strike]]\r\n*[[Backstab]]\r\n*[[Mutilate]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Dodge and Resist===\r\n*[[Evasion]]\r\n*[[Ghostly Strike]]\r\n*[[Cloak of Shadows]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Stealth===\r\n*[[Shadowstep]]\r\n*[[Stealth]]\r\n*[[Vanish]]\r\n*[[Distract]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Ability Modifiers===\r\n*[[Premeditation]]\r\n*[[Cold Blood]]\r\n*[[Preparation]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Debuffs===\r\n*[[Hemorrhage]]\r\n*[[Riposte]]\r\n*[[Expose Armor]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Locks===\r\n*[[Pick Pocket]]\r\n*[[Pick Lock]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Traps===\r\n*[[Detect Traps]]\r\n*[[Disarm Trap]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Aggro Management===\r\n*[[Feint]]\r\n*[[Vanish]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Haste===\r\n*[[Slice and Dice]]\r\n*[[Blade Flurry]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Stuns===\r\n*[[Cheap Shot]]\r\n*[[Kidney Shot]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Bleed Effects (DoT)===\r\n*[[Garrote]]\r\n*[[Rupture]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Passive===\r\n*[[Detect Traps]]\r\n*[[Parry]]\r\n*[[Safe Fall]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Incapacitating===\r\n*[[Sap]]\r\n*[[Gouge]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Interrupts===\r\n*[[Kick]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Energy Generation===\r\n*[[Adrenaline Rush]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Disorienting===\r\n*[[Blind]]\r\n</div>\r\n<div style=\"float: left; width: 15em\">\r\n===Movement===\r\n*[[Sprint]]\r\n</div>",},
			["Rogue Flame Spirit"] = { content = "'''Rogue Flame Spirit''' can be found in [[Stonetalon Mountains]] .\r\n==Drops == \r\n \r\n0.08% Chance of a [[rare]] drop.\r\n1.54% Chance of an [[Uncommon]] drop.\r\n0.21% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Rogue glyphs"] = { content = "#REDIRECT [[Rogue abilities]]", redirect = "Rogue abilities",},
			["Rogue Ice Thistle"] = { content = "'''Rogue Ice Thistle''' can be found in [[Winterspring]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.04% Chance of a [[rare]] drop.\r\n0.57% Chance of an [[Uncommon]] drop.\r\n0.05% Chance of a [[common]] drop.\r\n0.24% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Rogue quest"] = { content = "#redirect [[Rogue quests]]", redirect = "Rogue quests",},
			["Rogue quests"] = { content = "The following guide is an outline to a few of the early level Rogue quests. While not a complete walkthrough since I have not played all of the quests, it should provide enough information for you to get through the quest with little to no frustration. This guide will be split into a few main parts. The three prominent parts are the \"Alliance\", \"Horde\", and \"Both\". They will then be subcategorized by race and level. The \"Both\" category will be subcategorized by level only. This guide contains spoilers, so don't read it if you don't want to know what happens before you finish the quest.\r\n==Early quest overview==\r\nThe quests are initially divided up by race. Your first class quest, at level 2, no matter which race you are, will consist of \"Take an encrypted (message, the colorful descriptive word for message depends on your race)\" to the nearby rogue trainer. The quest-giver will give you a general location, such as a town name or area, and it's up to you to find it, but the trainer is close by, within the starting area. Once finished, you will receive 5-40 experience depending on your race and be able to train new abilities as long as you are the proper level and have enough money, a few available immediately at level 2. This initial trainer can train you in rogue skills up to level 6.\r\nAt level 10, each race that has a rogue class has a quest chain that gives them a Blade of Cunning, a good dagger. (It is possible to do these quests for each race of your faction (except races that share the same area, trainers, and quests), but because the reward is [[unique]], and you have to be able to receive the reward before you can turn in the completion (the WoW mechanics require it), you have to sell or otherwise destroy your Blade of Cunning from the previous turn-in before you can complete the next turn-in.)\r\nAt level 16, each race that has a rogue class has a quest chain that funnels them to a shared faction level 16 quest giver. Even though these funneling quests have different names, you can do only one. You do not have to do the one that is nominally for your race. \r\n====Mennet Carkad====\r\nLevel 10 Quest. Speak with [[Marion Call]], the rogue trainer in Brill (upstairs at the inn). You will be instructed to speak with Mennet Carkad in the Rogues' Quarter of the [[Undercity]]. You earn 210xp from this quest. This leads to the level 13 quest called \"The Deathstalkers\".\r\n====The Deathstalkers====\r\nLevel 13 Quest. This quest is broken into four stages of running around the Rogues' Quarter of the Undercity.\r\n# Speak with [[Mennet Carkad]] in the Rogues' Quarter of the Undercity. Ask an [[Abomination]] for directions to the rogue trainer; he standing out front of the building. You are instructed to acquire [[Astor's Letter of Introduction]]. [[Astor Hadren]] (level 13) walks back and forth along the road between the Undercity and the [[Sepulcher]], pausing at each end. You must first speak to him, at which point he will become aggressive and you must kill him for the letter. If you want to try this quest at level 10, make sure to bring a friend or two! Once you've killed him, return the letter to Mennet Carkad in the Rogues' Quarter. You will receive a little XP.\r\n''Note: Hadren is aggressive towards any Alliance players he sees and will attack them on sight, regardless of level. If Hadren dies before you can kill him, he respawns a few minutes later near the Sepulcher.''\r\n# Speak with Mennet Carkad in the Rogues' Quarter of the Undercity. Mennet gives you Astor's Letter of Introduction to deliver to [[Andron Gant]], in the Apothecarium. He is in the plaza nearest the Rogues' Quarter, where [[Mage]]s do their [[Quest:Investigate the Alchemist Shop|quest]] for their robe. The quest is considered \"complete\", so look for the gold dot on your minimap. You will receive a little XP.\r\n# Speak with Andron Gant in the Apothecarium of the Undercity. Andron instructs you to get [[Andron's Ledger]] from the bookshelf behind him and deliver it back to your \"mutual acquaintances\". Instead, bring it back to Mennet Carkad in the Rogues' Quarter. You will receive a little XP.\r\n# Give Mennet Carkad the ledger. He will tell you to deliver the good news to [[Varimathras]] in person and welcomes you into the Deathstalkers. Seek Varimathras in the Royal Quarter (ask for directions to the Battlemaster). He will reward you with 900 XP and a Blade of Cunning.\r\n====Find the Shattered Hand====\r\nLevel 16 Quest. Speak with Mennet Carkad the Rogues' Quarter of the Undercity. You are instructed to journey to Orgrimmar and speak with [[Shenthul]] at the Cleft of Shadow. This leads to the Orc quest \"Zando'zan\", which is the Horde [[Lockpicking]] quest.\r\n====Fenwick Thatros====\r\nLevel 16 Quest. Speak with Mennet Carkad the Rogues' Quarter of the Undercity. You are instructed to kill [[Fenwick Thatros]]. You are instructed that Thatros can be found near the decrepit dock on Lordamere in [[Silverpine Forest]]. You will receive 875 XP. This quest leads to the level 20 quest \"Tools of the Trade\".\r\n====Tools of the Trade====\r\nLevel 20 Quest. Speak with Mennet Carkad in the Rogues' Quarter of the Undercity. Objective: Find the Dalaran Status Report. You can find it amongst the Dalaran Wizards of Kirin Tor at Ambermill in the Silverpine Forest. Coordinates: 63, 64. The wizards are level 19 & 20. The locked chest with the report is on the second floor in the back room of the house to the right as you enter the walled area of Ambermill. You will need to lock pick the chest. You will receive 1550 XP\r\n===Trolls===\r\nAt level 16, your trainer will give you a quest to go to the [[Rogue]] [[Trainer]] in the [[Cleft of Shadow]] in [[Orgrimmar]]. There, you must learn the [[Lockpicking]] skill, and you will be sent to [[Ratchet]]. Once there, you will receive a [[Quest]] to sneak onto the pirates' boat south of [[Ratchet]]. Grab the two items that the quest giver tells you to from the nearby robot, and head south to the boat along the coast (you can't miss it). Enter it by walking along the spike on the ship's front. Once inside, there is a room full of locked chests on the first floor of the ship. You can [[grind]] up your skill to 80 (chests remain green at 100) on these chests (they respawn after you pick them, and they are all empty). After doing so, descend further into the boat. There will be a singular chest in the back of the bottom floor. Open it. A large parrot will spawn nearby and start coming towards you. Feed it the cracker you were given when you took the quest. This will allow you to fight it. He will drop the treasure you need for your quest. Return it to [[Ratchet]] for your reward, a stack of [[Thistle Tea]].\r\n===Orcs===\r\nAt level 10, Kaplak at [[Razor Hill]] in [[Durotar]] will give you the quest Therzok where you'll speak with Therzok in [[Orgrimmar]]. Then you'll get the quest The Shattered Hand where you'll kill Tazan, a [[troll]] south of [[Ratchet]], and get his [[Tazan's Satchel|satchel]]. But the satchel must be opened with a key, and so Therzok asks you in [[Quest:The Shattered Hand (2)|the next quest]] to pick-pocket Gamon and get the key he holds. After you've done that, open up the satchel with the key to get [[Tazan's Logbook]], and you've completed the chain.\r\n*Reward: Blade of Cunning\r\n====Find Keltus Darkleaf====\r\nLevel 10 Quest. Speak with [[Zelanis]], the rogue trainer in [[Silvermoon City]] (in murder row). You will be instructed to Locate [[Keltus Darkleaf]] and return his reports to [[Zelanis]]. [[Keltus Darkleaf]] is located in [[Ghostlands]] at 33,11 watching the Night Elves. He gives you a quest to pickpocket the Leader of the Night Elves before he hands over his reports. You will receive about 175 XP and a Blade of Cunning for completing this quest chain.\r\n====Greed====\r\n[[Quest:Greed|Level 16 quest]]. Get a ring from the chests in the Amani Wood Catacombs.\r\n==Alliance==\r\nThe four races that make up the Alliance (Humans, Dwarves, Gnomes, and Night Elves) are all allowed to become Rogues. Each race's quests in their starting zones are different, but at level 16 they all converge in Stormwind. Dwarves and Gnomes have the same quest line, since they start in the same zone.\r\n===Night Elves===\r\nRogue trainer quest:\r\n#Simple Sigil \r\nChain 1:\r\n#The Apple Falls\r\n#Destiny Calls\r\nChain 2:\r\n#Erion Shadewhisper\r\n#Erion's Behest\r\n===Humans===\r\nRogue trainer quest:\r\n#Encrypted Letter \r\nChain 1:\r\n#Seek out SI:7\r\n#Snatch and Grab\r\nChain 2:\r\n#SI: 7\r\n===Dwarves===\r\nRogue trainer quest:\r\n#Encrypted Rune \r\n===Gnomes===\r\nRogue trainer quest:\r\n#Encrypted Memorandum \r\n===Dwarves and Gnomes===\r\nChain 1:\r\n#Road to Salvation\r\n#Simple Subterfugin'\r\n#Onin's Report\r\nChain 2:\r\n#To Hulfdan!\r\n#Kingly Shakedown\r\n===All Races===\r\nAt level 16, all the races' quest lines converge.\r\nChain 1:\r\n#Redridge Rendezvous\r\n#Alther's Mill \r\nChain 2:\r\n====Gaining the Poisons Skill====\r\nAt level 20, rogues are able to begin a [[quest]] chain which ends with the acquisition of the Poisons skill. The exact quests depend on the rogue's [[faction]].\r\nFor [[Alliance]], go to the Old Town in [[Stormwind]]. The quest is available at [[SI:7]] headquarters. The quest takes place in a tower on the southern border of [[Westfall]] near [[Stranglethorn Vale]], along the river. . You cannot get the key by the kill even though it suggests this, you must pickpocket the spicky undead. Then go and get the book by lockpicking at the top of the tower. You will end up with a poison that gimps you as a rogue for 7 days. Return the book and key to SI7 and you can get the poison removed. However, if you get the book first, you cannot get the key without removing the poison. This can be removed by the first aid item, or a druid. Priests may also be able to remove it.\r\nFor [[Horde]], go to the [[Cleft of Shadow]] in [[Orgrimmar]] and perform [[Quest:The Shattered Salute|The Shattered Salute]]. The Horde quest chain is difficult to complete solo at level 20, but two level 20 characters or a solo rogue around level 23 should be able to complete it. The two main quests in the chain take place in a tower in the northeast corner of the [[Barrens]]. When the quest objectives are completed, the rogue will be poisoned with a very slow-acting poison [[debuff]]. After turning in the quest at the Cleft of Shadow, the rogue travels to [[Tarren Mill]] in the [[Hillsbrad Foothills]], where they will be cured of the poison debuff (though the poison is easily curable through a variety of other means as well) and gain the Poisons skill.\r\n====[[Quest:The Manor, Ravenholdt|The Manor, Ravenholdt]]====\r\nAt level 24, the rogue trainers will give you a letter containing a Seal of Ravenholdt. The letter instructs you to find the Manor Ravenholdt, which is hidden in the hills of northeastern Hillsbrad. If you make your way to the tunnel, you will see a chest that appears like it can be opened. Your Detect Traps ability will warn you not to open the chest if you get near it. Walk up to the chest but do not open it - you will get the \"Rite of Cunning - Complete\" message. Proceed through the tunnel and talk to Fahrad.\r\nAt [[map coordinates]] 75,22 there is the beginning of a path that leads to the manor. For those of your without map mods: If you head straight east from Tarren Mill you should end up at the path, you just have to pay attention to your mini map.\r\n====Syndicate Emblems====\r\nIf you complete \"The Manor, Ravenholdt\", any Ravenholdt guard will give you a quest to collect Syndicate Badges, which can only be obtained by pickpocketing them from Syndicate mobs (in Hillsbrad, Alterac, or Arathi Highlands). The badges can be turned in to the guards outside the tunnel. Turning in 30 badges (one at a time) will gain Friendly reputation with Ravenholdt (250 rep each). Much later in your Rogue career, you can then turn in [[Heavy Junkbox]]es (which can be pickpocketed off mobs in the 50-60 range) 5 at a time to further gain rep (+50) with Ravenholdt as well as a mediocre throwing knife reward. As of now there are no reputation rewards from the Ravenholdt Assassins' League. There is a supply NPC in the Manor, though, who sells a limited supply [[Engineering]] [[Schematic]] (the [[Gnomish Cloaking Device]] which can only be obtained here. Anyone can purchase it, of course, but few people know where the Manor is, so a shady dealer such as yourself can perhaps make a profit.\r\n====A Simple Request====\r\nAt level 50, a rogue trainer in any main city will send you to see Lord Jorach Ravenholdt, who then sends you to [[Archmage Xylem]] in [[Azshara]]. This quest series culminates in The Azure Key and gives a choice of several decent blue item rewards.\r\nPart of the quest line involves retrieving an item from a Timbermaw Shaman. If you don't mind destroying your [[Timbermaw Hold]] reputation, then go ahead and kill them for the drop - but if you value your [[Furbolg]] rep, try to get the item via [[pickpocket]]ing. This may draw aggro if it is resisted, but if you run rather than fight it will not damage your reputation.",},
			["Rogue talents"] = { content = "#REDIRECT [[Rogue abilities]]", redirect = "Rogue abilities",},
			["Rogue trainer"] = { content = "#REDIRECT [[Rogue trainers]]", redirect = "Rogue trainers",},
			["Rogue trainers"] = { content = "A '''rogue trainer''' is an [[NPC]] that offers [[rogue]]s the opportunity to train and learn ranks of abilities, including [[talent]]-based abilities.\r\n== Horde Trainers==",},
			["Rohan the Assassin"] = { content = "'''Rohan the Assassin''' is a level 60 [[quest giver]] located at [[Light's Hope Chapel]] in the [[contested]] territory of [[Eastern Plaguelands]]. He is affiliated with the [[Scarlet Crusade]]. He collects [[Bone Fragments]] to help create [[Bonescythe Armor]] sets.\r\nHe tells about the time he was in a barber shop quartet. This is a reference to the movie .\r\nHe starts the following quests:\r\n* Bonescythe Digs (Repeatable)\r\n* Bonescythe Bracers (Raid)\r\n* Bonescythe Breastplate (Raid)\r\n* Bonescythe Gauntlets (Raid)\r\n* Bonescythe Helmet (Raid)\r\n* Bonescythe Legplates (Raid)\r\n* Bonescythe Pauldrons (Raid)\r\n* Bonescythe Sabatons (Raid)\r\n* Bonescythe Waistguard (Raid)\r\nSee [[List of Eastern Plaguelands NPCs]].",},
			["Rohendor"] = { content = ":''Were you looking for the (removed from game) [[quest]] Rohendor, the Second Gate?''\r\n----\r\n'''Rohendor''' is the second of three gates guarding the [[Sunwell]] in the raid instance of [[Sunwell Plateau]]. It is the gate encountered after fighting Eredar Twins, and bars the way when adventurers attempt to fight M'uru (tactics).\r\nThat is, between [[Agamath]], the first gate, and [[Archonisus]], the third gate.\r\nOn the [[Test Realm|PTR]], the three gates were opened by handing in a [[Quest:Rohendor, the Second Gate|quest]], although now they will open by themselves over time. Rohendor opened on US and EU servers after an extended maintenance on 29th of April, 2008.",},
			["Rohok"] = { content = "'''Rohok''' is a level 60 [[master]] [[blacksmithing trainer]] and [[vendor]] located at [[Thrallmar]] in the [[contested]] territory of [[Hellfire Peninsula]].\r\nSee [[List of Hellfire Peninsula NPCs]].",},
			["Roitau"] = { content = "Roitau is a [[Troll]] who is in charge of the roadies for [[Level 80 Elite Tauren Chieftain]]. He is in charge of the workers, packing and unpacking the wagon, and driving it. He sets the stage up and breaks it down. He is most credited for the spectacular pyrotechnics at their famous [[Shattrath City]] show. He is currently found in [[Silvermoon City]] in the [[Walk of Elders]], he is with the manager Michael Schweitzer.",},
			["Rokad the Ravager"] = { content = "'''Rokad the Ravager''' is a level 73 [[named]] [[elite]] [[darkhound]] in the Servant's Quarters in [[Karazhan]]. The Servant's quarters are located immediately to the right after you enter the instance from the main entrance.\r\nRokad only does straight up melee damage on the main tank, but does so a lot (about 1800 damage). The encounter is a straightforward tank and spank fight.\r\nMost of the trashmobs in the room can be cleared before starting the bossfight. The only exceptions are the two dogs closest to him: they seem to be linked to the boss and pulling them will aggro the boss as well. [Edit - We body pulled the two hounds and did not aggro Rokad]\r\nThe random animal boss spawn seems to work like this: 1. Clear the area (boss hasn't spawned yet). 2. Start clearing the respawns. 3. Get the announcement by the spawned boss. 4. Clear the path to the announced boss. 5. Kill the boss - (confirmation needed on this) - Apr. 8\r\n'''Faction Gain'''\r\nClearing the area requires the raid to kill around 50 mobs worth 15 [[Violet Eye]] rep each. With reputation from the boss, this adds up to about 1000 [[Violet Eye]] reputation.\r\n==Strategy==\r\nWhile Rokad does relatively strong melee damage to the tank, this encounter is essentially a \"tank 'n' spank\" fight; just DPS him down and heal as needed.\r\nA warlock can enslave or banish the two dogs that aggro with him. They have a cleave that can hit for 2-3k and crit for over 7k. If enslaved and used against the boss, they can actually pull aggro away from the main tank. - July 2 07.\r\n==Loot==\r\nRokad drops one set of purple bracers each time. These are randomly selected from Cloth, Leather, Mail, Plate, with a random enchantment.",},
			["Rokag"] = { content = "'''Rokag''' is a level 70 Horde [[quest giver]] located at the [[Stonebreaker Hold]] in [[Terokkar Forest]].\r\nHe starts the following quests:\r\n* The Missing Merchant\r\n* Surrender to the Horde\r\n* Stymying the Arakkoa\r\n* A Bird's-Eye View\r\n* Lookout Nodak\r\nHe ends the following quests:\r\n* Rescue Dugar!",},
			["Rokaro"] = { content = "'''Rokaro''' is a [[Champion of the Horde]], located in [[Shadowprey Village]] in [[Desolace]]. According to the quest [[Quest:The Champion of the Horde|The Champion of the Horde]], given by [[Thrall]], Rokaro was a companion of [[Rexxar]], the original NPC in the Horde's [[Drakefire Amulet]] chain. After the series of patches before the release of ''[[World of Warcraft: The Burning Crusade|Burning Crusade]]'', Rexxar and his companion [[Misha]] was moved to the [[Thunderlord Stronghold]] in the [[Blade's Edge Mountains]] of [[Outland]], and Rokaro has taken over Rexxar's duties.\r\nInterestingly, he is dressed like a [[rogue]].\r\nHe starts the following quests:\r\n* Blood of the Black Dragon Champion (Raid)\r\n* The Testament of Rexxar\r\nSee [[List of Desolace NPCs]].",},
			["Rokar Bladeshadow"] = { content = "'''Rokar Bladeshadow''' is a level 35 Orc farmer living just east of [[Razorwind Canyon]], northeast the town of [[Razor Hill]] in [[Durotar]]. He has a house and a small patch of crops. He also has a farmhand living with him, a level 5 Orc named [[Harroc]].\r\n==Quotes==\r\n''What's a young <class> like you out visiting an old farmer like me?''",},
			["Rokdar the Sundered Lord"] = { content = "The 3rd Boss in the [[Ring of Blood]] quest chain in [[Nagrand]]",},
			["Rokhan"] = { content = "'''Rokhan''' is a [[shadow hunter]] of the [[Darkspear Tribe]] of [[jungle troll]]s. He previously assisted [[Rexxar]] to halt [[Admiral Proudmoore]]'s campaign. At present, he can be found in [[Dragon's Fall]] in the [[Dragonblight]] as a Horde questgiver.\r\n===Old Hatreds===\r\nFormerly led by [[Sen'jin]] on the [[Broken Isles]], Rokhan joined [[Thrall]] and his [[Horde]] when he saved them from the [[Sea Witch]] and led them to [[Kalimdor]]. After the [[Battle of Mount Hyjal]], the [[troll]]s settled on the [[Echo Isles]] off the coast of [[Durotar]], but Rokhan remained in [[Orgrimmar]] as a scout for Thrall. When [[Rexxar]] came to Orgrimmar with [[Mogrin]]'s report, Thrall asked Rokhan to accompany the [[beastmaster]]'s trek through the wilds.\r\nRokhan and Rexxar found [[humans]] on the coast of Durotar after they got to the observatory in [[Gar'thok|Gar'thok's Outpost]], and when they reported to Thrall, he sent them back to find the outpost ruined, and the humans quite hostile.\r\nRokhan began to worry about his own people on the Echo Isles, and thought that perhaps they should come to the mainland to avoid any danger. Thrall agreed, and sent Rokhan and his band to the Echo Isles to warn [[Vol'jin]] and see them off the island. \r\nAfter destroying the battleships that blocked their path and lighting signal fires for the outlying village, Rokhan and Rexxar were sent to a summit in Thrall's place. When they were ambushed, Thrall, hoping to finish things peacefully, sent Rokhan and his friends to [[Theramore Island]] to secretly parlay with [[Jaina Proudmoore]].\r\nWith Jaina's aid, they discovered the invaders were led by Jaina's own father Admiral [[Daelin Proudmoore]], who was determined to wipe out the Horde in Durotar. Rokhan battled alongside Rexxar as they hastily traveled around the [[Barrens]] enlisting aid from their allies. Finally, the human and [[orc]] forces clashed in a titanic battle at [[Tidefury Cove]], and when the orcs emerged victorious, they chased the humans back to Theramore. Rokhan helped to lead the [[A Blaze of Glory|raid]] on Theramore, and battled Daelin Proudmoore's elite forces beside Rexxar. After Proudmoore's defeat and the end of the war, Rokhan was honoured by his people and Thrall's.\r\n===Afterwards===\r\nTensions remained high between the orcs of durotar and the humans of Theramoore. War nearly broke out once again, due to the scheming of a minor demon [[Zmodlor]] and a few [[Burning Blade]] cultists. Rokhan was still in Thrall's service as a scout - his finest - and made a sudden appearance to warn the Warchief of reinforcements to Northwatch Hold on the border between human and orc territory. He is described as having a surprisingly gentle face for a troll, with kind eyes.\r\nRokhan was rumored to have been sent on an important mission by Vol'jin.\r\n==In World of Warcraft==\r\nRokhan more recently killed [[Serena Bloodfeather]]'s older sister, accompanied by Rexxar, as [[Witch Doctor Jin'Zil]] reports.\r\n==In Wrath of the Lich King==\r\nIn [[Wrath of the Lich King]] Rokhan can be found in a small camp named [[Dragon's Fall]] in the [[Dragonblight]]. Rokhan ventured to [[Northrend]] to help in the various troll tribes fight against the [[Lich King]].\r\n==Quotes==\r\n*\"Whadaya mean, what kinda accent is dis? It's a troll accent! I swear, ja makin' me crazy.\" \r\n*\"I've lost me head! It was about, ah, yea big, I was keeping in on my spear. If you find it let me know.\" \r\n*\"I've got the righteous groove...\" \r\n*\"Sadly, the name '[[Pinkspear Tribe]]' was already taken.\" \r\n*\"Death be a real treat mon! \r\n*\"I'll be spearheading that right away!",},
			["Rokkar"] = { content = "'''Rokkar''' was an [[orc]] warrior who was [[Durotan]]'s second in command on [[Draenor]]. He was ordered by his chieftain to tie up the Prophet [[Velen]] and confiscate the crystals he was carrying, [[Heart of Fury]] and [[Brilliant Star]]. He perished during an attack against a [[Draenei]] hunting party when the elements refused to assist the orcish attackers.",},
			["Rokmar the Crackler"] = { content = "'''Rokmar the Crackler''' is the largest [[Bogstrok]] in [[The Slave Pens]], and he is the second of the three bosses in this zone. If threatened, he will engage and kill any creature that does not belong in his domain by using his tearing claws and water blasting abilities.\r\n==Spells and Abilities==\r\n*'''Grievous Wound''': [[Bleed]] debuff, it causes Rokmar's current target to bleed for 900 physical damage every 2 seconds until the player with the [[debuff]] has been healed to full health; [[Divine Shield]] and [[Stoneform]] will also remove it. Also, the debuff is not timed, and will last until you are dead or cured.\r\n*'''Water Spit''': [[AoE]], deals 1600-1800 [[frost]] damage to nearby targets. [[Frost]] resist gear would be useful, as it would save the healer's mana and the [[healer]] will not [[aggro]] that easily. But it's not necessary if you have strong dps. The range is 40 yards, so Hunters/Mages can stay out of range, depending on spec.\r\n*'''Ensnaring Moss''': increases attack speed and casting time by 50%. The range is roughly 30 yards. If you are healing, be sure to get out of this, as if you get it, it's a sure wipe since you have to keep your tank topped.\r\n*'''Enrage''': ([[Heroic Mode|Heroic]] only.) At 20% health he enrages, increasing his physical damage done by 213 and attack speed by 60%.\r\n==Strategies==\r\n'''Tanking'''\r\nTake your time, and this is easy. If the tank loses aggro, you will be in trouble. When he enrages you must lay down heavy heals. Any class with heals spells should be healing the tank; Rockmar hits hard.\r\nTo save everyone's life if the tank is dead — and Rokmar is nowhere near dying — all the remaining group members can jump into the pools of water. It appears that, although Rokmar is a gigantic Bogstrok/prawn, he cannot swim! When you jump into the water you will exit combat mode in a moment and Rokmar will go back to patrolling. Be '''sure''' that you do get out of range of his Water Spit. If you make it near the ramp it will be far enough. Note that if you jump into the Western pool, you will have to walk the long way around to return to Rockmar. Try to jump into the southeastern pool.\r\n'''Water Spit Attack'''\r\nRockmar occasionally attacks with Water Spit. The attack is an AoE frost-based attack, so frost resist of any kind is good. Paladins should put up Frost Resistance Aura. There is, however, a way for the healers to escape this attack. If the tank positions himself so that he is between Rokmar and the healers, the 40 yard range of the healers will place them just outside the 40 yard range of the Water Spit. This saves mana that the healers would otherwise use on themselves. Everyone else should hang in fairly close to the tank so they can be in range of the healers. Don't be afraid! Interrupts such as [[Silence]], [[Earth Shock]], [[Kick]], [[War Stomp]], and [[Shield Bash]] also do not work. Heal yourself with [[bandage]]s to save your healer some mana.\r\n'''Grievous Wound Attack'''\r\nHis most devastating attack is a bleed effect, which will increase the already tremendous amount of damage per second over time. The only way to remove this is to heal the afflicted member to their maximum hit points. When this is done, the bleed is removed. This fight is a cakewalk with two good healers (a shaman and a druid/priest works very well) who can keep the tank from bleeding out. With a single healing class, it is easy to run out of mana trying to keep up with the bleed; for this reason, Rokmar is one of the most difficult fights to heal. Keeping the tank's health high and immediately healing to full when the bleed hits is advisable though not always possible.\r\n'''Dwarven Stoneform'''\r\nNote that [[dwarves]] can activate [[Stoneform]] to remove the bleed effect Rockmar inflicts the tank with. This can be a useful maneuver, but keep in mind that Stoneform's 2 minute cooldown means you can only get rid of one bleed effect, so use it well.\r\n==Heroic Mode==\r\nWater Spit hits for about 1.5k, easily outhealable by a shadow priest's [[Vampiric Embrace]] or lower rank HoTs. A warrior's Spell Reflect does not work against his Water Spit, so healers will need to time their heals to hit either right before, or space out their mana as to not be drained before the fight can be over. Frost resist gear, frost protection potions, or any healing potions or stones will be helpful.\r\nHis 20% enrage isn't that bad but will test your healer's gear if combined with an active Grievous Wound. It is very helpful to save cooldowns such as [[Healing Potion]]s and [[Healthstone]]s for this.\r\nGrievous Wound ticks for around 1.1k every 2 seconds.\r\nHe is often considered relatively easier than he is on normal mode at the appropriate level. This is likely due to the additional tools available to healers at level 70 — such as Prayer of Mending for priests — which make it easier to get the tank back to full health quickly when the bleed hits.",},
			["Rok Orhan"] = { content = "'''Rok Orhan''' is a level 40 [[quest giver]] located at [[Camp Mojache]] in the [[contested]] territory of [[Feralas]]. Bloodthirsty even by [[orc]] standards, she instructs adventurers on how they can best aid the war effort, giving them tasks that all too often focus on decimating the [[Gordunni]] population in the area.\r\nShe starts the following quests:\r\n* The Ogres of Feralas\r\n* The Ogres of Feralas\r\n* Dark Ceremony\r\n* The Gordunni Orb\r\nSee [[List of Feralas NPCs]].",},
			["Roland's Doom"] = { content = "'''Roland's Doom''' is the mine which the [[Scythe of Elune]] apparently resides. The mine, now [[Worgen]]-infested, is where [[Jitters]] first found the Scythe, releasing the [[Worgen]] and in time the [[Dark Riders]] upon [[Duskwood]] and [[Darkshire]], condemning them to permanent darkness. Whoever Roland was, he apparently died here. It is possible he led the team who uncovered the scythe, and were subsequently murdered by the worgen. The mine is now the location of [[Gutspill]] and [[Nefaru]], who lead the worgen at [[the Rotting Orchard]].",},
			["Roland"] = { content = "Roland was a paladin in [[Duncan Senturus]]'s command. He assumed Duncan's rank after he perished while journeying to Grim Batol.",},
			["Roland Geardabbler"] = { content = "'''Roland Geardabbler''' is a level 43 [[gnome]] keeping the supposedly trapped crew in the ''[[Horizon Scout]]'' alive.",},
			["Roleplay"] = { content = "#REDIRECT [[Roleplaying]]", redirect = "Roleplaying",},
			["Roleplayer"] = { content = "#REDIRECT [[Roleplaying]]", redirect = "Roleplaying",},
			["Roleplaying"] = { content = ":'''''RP''' may also less commonly refer to [[Refuge Pointe]] or [[Honor|Rank Points]].''\r\n'''Roleplaying (RP)''', or '''Role Playing''', in World of Warcraft means taking on the role of a character and acting it out in-game through emotes, /say, /yell, and sometimes other channels. Players may also participate in roleplay outside the game by posting on blogs, wikis, or forums (official or otherwise). Roleplaying has similarities to improvisational theater, with the participants acting out characters in unscripted situations. The character's personality, goals, morals, and quirks may resemble that of the player or be completely different. Regardless, roleplayers recognize a boundary between what is [[in character]] and what is [[out of character]]. \r\n'''RP''' also refers to RP [[Realm]]s. There are several [[:Category:RP servers|RP Servers]] available to Warcraft roleplayers. RP servers are functionally the same as [[:Category:PvE servers|PvE Servers]], with added social rules and stricter naming enforcement. \r\nThe same is true for [[:Category:RP-PvP Servers|RP-PvP Servers]] and [[:Category:PvP servers|PvP Servers]]. Both sets of rules apply. RP-PvP is commonly misunderstood to mean that the roleplaying part is optional. In fact, these servers were started in response to petitioning from roleplayers, who felt that the ability to engage in PvP added realism.\r\n \r\n===Basic Expectations on RP Servers===\r\nIn addition to Blizzard's normal , players on Roleplaying servers are expected to abide by the rules outlined in the . In summary, players should:\r\n* '''Create a name that fits within the World of Warcraft universe.''' Remember that rules for Roleplaying servers are in addition to the regular . \"Iwillcrushyou\", \"Roguesftw\" and \"shammysrule\" are examples of names that would be against the Roleplaying Naming Policy.\r\n* '''Stay in character in /say, /yell, in emotes, or any other channel used for roleplaying.''' This means no discussion of real life events or people in these areas. Players should also take the time to spell out words and phrases. Refrain from using internet jargon and acronyms such as \"lol\" or \"pwn\". \r\n* '''Maintain a positive atmosphere for roleplaying.''' Harassment of other players is never tolerated.\r\nPlease note that rules about the General chat channel state that is required to be on-topic, not in-character. Traditionally, General is used on roleplaying servers in much the same way as it is on any other server type. However, many people on roleplaying servers enjoy maintaining the same character persona across all channels. Roleplaying on the General channel is infrequent but not uncommon.\r\n===Supporting Roleplay on RP Servers===\r\nRoleplayers are sometimes disappointed at the amount of out-of-character chat, inappropriate character names, or anti-roleplaying behavior seen on the official RP servers. Forum threads lamenting the state of enforcement are on the official forums.\r\nBlizzard Customer Service Representative Pavonum how Blizzard handles RP server violations: \r\n<blockquote class=\"blizztext\">...we '''work reactively''' in response to players' reports. Thus, if you observe players attempting to disrupt roleplaying events through the use of verbal, physical, or visual harassment, I would encourage you to submit an in-game petition...\r\n<blockquote class=\"blizztext\">...it is contrary to our stance of not \"policing\" realms in search of policy violations -- which is, again, in line with the '''reactive nature''' of our investigation -- and partly because it is simply not logistically feasible to offer such a service, given the resources it would require. We urge you, however, to report any wrongdoing you observe...\r\n''-(Emphasis added)''\r\n[[Game Master|Blizzard GMs]] do not go looking for RP violations. They address these issues ''entirely in response to player requests''. It is up to the community on each RP server to establish the degree of policy enforcement they wish to see. Whereas one server's community may take a very strict approach to naming, another may be relatively lax. Rather than Blizzard GMs deciding how far to take it, it's up to the players themselves to \"set the barometer\" and determine what is acceptable or not. The GMs can then compare the infraction to the policy as worded, and apply disciplinary measures as required.\r\nThus, it is up to players on RP servers to proactively support the enforcement of the official RP server policies by [[Help Request|reporting infractions]] to GMs.\r\n===Related Links===\r\n* [[Lore]]\r\n* [[WoWRP]]\r\n* [[Roleplaying FAQ|Roleplaying Forum FAQ]]\r\n* [[Roleplaying Forum Writing Guide]]\r\n* [[WoWWiki:Fan fiction guidelines|WoWWiki Fan Fiction Guidelines]]\r\n* [[WoWWiki:Roleplaying Compendium|WoWWiki Roleplaying Compendium]]\r\n* [[Tbelle's RP Guide]]\r\n* [[User:Burgrsch/Class and Guild RP Tips|Burgrsch's Class/Guild RP Tips]] (Under construction)\r\n* -- A ''WoW'' roleplay community with race-themed monthly events with prizes, as well as a decent-sized community of immersive roleplayers.\r\n===WoW Role Play Podcasts===\r\n* Featuring sightseeing guides, RPing tips, audio dramas, and more!",},
			["Roleplaying FAQ"] = { content = "An extremely detailed FAQ on [[Role Playing]]. Originally based on the forum thread found at the . The credits for the original FAQ go to Chro, Mortiz, Nycte, Scarletbeard, Intuki, Karathos, Rhi, [[Silvermist]], Hurbert, Skyfire, Malverity, Shabadu, and Elianna.\r\nSee also:\r\n* [[Role Playing Policy]]\r\n* [[Roleplaying Forum Writing Guide]]\r\n==Role Playing FAQ==\r\n by (Chro, Level 38 Human Rogue, Guild: Night Blades, Realm: Feathermoon):\r\n* 1. '''[[Roleplaying FAQ|Role Playing FAQ]]''' | 3/30/2005 7:55:27 AM PST\r\n* 2. '''[[Roleplaying FAQ|Forum Role-Playing]]''' | 3/30/2005 7:56:01 AM PST\r\n* 3. '''[[Roleplaying FAQ|In-Game Role-Playing]]''' | 3/30/2005 7:56:31 AM PST\r\n===FAQ===\r\nEvery day the Role-Playing forums get the same questions over and over again. In this article the most common questions will be answered for the betterment of those who are new.\r\nIf you are simply looking for the rules of the Role-Playing servers, please read this: \r\nAlso included in this FAQ is a [[Roleplaying Guide|guide to Role Playing on the forums]]. It can be found here: \r\n====What is Role-Playing? (RP)====\r\n-Role Playing is when you act out a specific character In-Game or in a Role-Playing thread. Basically you are an actor in an unscripted environment and act as you think your avatar would. \r\n====What is the difference between a PvE server and RP server?====\r\n-A PvE server is one in which you simply play the game as a game, leveling and looking for loot. An RP server is different only in the fact that you are required to Role-Play as your character. If you are caught going Out-Of-Character too often and in the wrong ways you can, and probably will be reported for it.\r\nThe game mechanics, however, are the exact same for these two servers. \r\n====Is there a PvP Role-Playing server?====\r\n-Yes, the [[Patch 1.8]] has added the [[RP-PvP]] server type. Their number will grow over time.\r\n====Ok then, can I still participate in PvP on a RP server?====\r\n-Absolutely. In fact there are many guilds devoted to PvP on RP servers. Many think that for a true RP environment players should always be flagged for PvP. Others even have called for a Free For All RP server, but don't expect that to happen anytime soon.\r\n====Ok, I've got down Role-Playing in-Game, but what about the forum Role-Playing?====\r\n-Role-Playing on these forums is done in written form. It is best to give an example of it instead of trying to explain it.\r\n-Bad RP: \r\nBilly Zepher comes into the room. \r\n/wave \r\nhey everyone he says. We need to go now They all walk out the door. \r\n-Good RP \r\nThe door creaks open as Billy Zepher quietly slips into the room, waving shyly to those inside. \"Excuse me,\" he says meekly. \"Sorry to interrupt, but we need to be going soon.\" \r\nThe first example uses poor description, In-Game emotes, and little grammar. It also 'God-Modes,' meaning that your post uses the other people's characters without their consent. The second example is descriptive, even though it is short and most posts are preferred at least a paragraph. It also gives the other players a chance to respond and take action. \r\n====What are good RP Names? I want to use real ones, but not like 'Fred' or 'Bobertthegreat'.====\r\n- \r\n====What does OOC stand for?====\r\n-OOC stands for Out of Character. If something happens in which you need to leave the game or if you want to explain something to someone, this is the way you do it. It can be displayed in several forms. \r\n-OOC: I have to go to the bathroom. \r\n-(I have to go to the bathroom) \r\n-((I have to go to the bathroom)) \r\n-The third version is the most preferred, as it is easily recognizable as OOC. In the game, you should probably use OOC talk in /party or in a whisper, as people tend to get ticked when they see it in /say. \r\n====So what is IC then?====\r\n-IC stands for In Character. Basically whenever you are role-playing you are In Character. It is a good thing to note that when a person acts like a jerk or starts flirting with you, it may have nothing to do with the actual person behind the avatar, just how the character would act. It is wise not to become offended by anything someone does In Character. \r\n====The rules say I need a storyline. Do I have to write out a five page essay and submit it to make my character?====\r\n-This just means that your character has to have come from somewhere. You don't have to have a glorious past, and you probably shouldn't as you'll be starting at level 1. You could be fresh off a farm, or just came of age. Just make sure your character didn't pop into being when you hit the 'create character' button. \r\n===== I just got totally flamed for a thread I made! =====\r\nYou most likely posted one of the following threads that are not generally accepted in the RP community. \r\n''' ''- A Personal Ad'' '''\r\nThese threads are the kind that are \"Looking for Love\". You are in the wrong place for that kind of thing. \r\n''' ''- An Anti-Roleplay Thread'' '''\r\nThis most likely doesn't need an explanation at all. Frankly, if you are just here to make fun of roleplayers, you are just itching for a fight.\r\n''' ''- A \"What is RP?\" Thread'' '''\r\nThese are threads that ask questions that are so trivial, and/or so common, that its obvious that the poster hasn't take a moment to read the FAQ. \r\n''' ''- A Completely Off Topic Thread'' '''\r\nOften, many of the threads that should be put in the off-topic forums get dumped in here. Most RPers don't take to kindly to this. \r\nIf you are courteous, and avoid the preceding threads, you will most likely not be flamed. \r\n \r\n===== I just got yelled at for not knowing the lore of Warcraft. Is there a place I can learn it? =====\r\n-Yes. Blizzard has a full history on the world of Azeroth on the website. You can find it here- \r\n====Ok, I just got reported for being out of character! I have a troll character and all I said was: \"Hey mon, did ya be seeing dat movie \"Dude, Where's My Car?\"====\r\n-Adding an accent does not mean that you have a solid character. An accent does not hurt at all, but a character it does not make. \r\n-Also talking about things your character would have no knowledge of (movies and such) is OOC in any case, accent or not. Similarly, a dwarf or troll character may not have a heavy accent at all, and still be believable.\r\n====Ok, ok, I know an accent isn't all that makes a character. But I still want mine to have one. What are the race's different accents?====\r\nBased on common observations and stereotypes:\r\n-Troll = Jamaican\r\n* ''Hey mon, ya need ta be staying away from da voodoo.''\r\n* ''Watchu want?''\r\n* ''Dis was me brutha! I an' I be killin' ya now.''\r\n-Dwarf = Scottish\r\n* ''Aye lass, ye dinna know ale 'til ya try Dwarf ale!''\r\n* ''I ken yer meanin', but it's a daft idea.''\r\n* ''Ah, Loch Modan. Always a great sight for me old eyes. Ev'rythin' so neat and tidy, an' tha few beasts around 'ere... we'll be takin' care o' them in no time.''\r\nAll other races use an American English dialect.\r\nNPC voices have noticeable accents (orcs are gravelly, gnomes are squeaky, Draenei sound east-Asian), but these can't be expressed in text. Draenei can, to some extent, usually by using bad grammar and replacing 'g' with 'k' in certain places.\r\nEvery other race is free to pick an accent they might like within logical boundaries. Troll and Dwarf are the only two with defined stereotype dialects when it comes to accents. Add-ons are available to automatically edit what you type if you feel like cheating.\r\n====What kind of Role-Playing goes on on these forums?====\r\n-There are several different types. \r\n''- Open RP'' \r\nYou are free to join these on-going stories so long as you don't 'God-mode' and you join in a logical fashion. \r\n''- Structured RP'' \r\nIn these, the Original Poster is a narrator of sorts. They have a story to tell and try to steer things in the direction they want. If you are uncomfortable with someone else taking mild control of your character, do not join these. \r\n''- Story'' \r\nJust a plain story, or 'fan-fic' as some like to call them. You aren't part of the story, you just read and give a review or compliment. \r\n''- Off Topic'' \r\nThese are just casual threads about nothing or something odd. You usually participate as your character, but removed from the world of Azeroth. Not traditional RP and are fairly lacking on the rules. Feel free to blow up, decapitate, or rob blind anyone else most of the time. They'll just come back without explanation (Or at least a really weak one.) \r\n====\"L0L0L0L!!!1111 I pwo|\|s u N00B!!!!11111\" What kind of language is that?====\r\n-That is what is known as 'leet speak' and it is not tolerated on the Role-Playing forums. If you post a message in this style on roleplaying forums (or even worse, use such language in the IC channels in-game), you will most likely be ignored, flamed, or even reported.\r\n====Ok, I know what RP is now. But why do you guys do it? It seems dumb to me.====\r\n-Role Playing adds another level of immersion to the game for some and allows the players to expand the creative side of their mind. However, some players may prefer less immersed, more laid-back style of playing, or simply focus on other aspects of the game. These players would feel more at home on non-RP realms and outside of the roleplaying forums.\r\n====I want to Role Play, but I don't have good spelling.====\r\n-That's OK. Just keep writing and asking people to correct your words and you'll do fine. And if you want to be aggressive about getting good at spelling, type up all of your posts on a word processor and spell-check. You'll get better in no time. So long as you make a genuine effort, others should accept you and try to help you along. \r\n====What is the best RP server?====\r\nWe would all like to say that our own is, but it is a matter of opinion. Try a few and see which fits you, though you will probably need to get up some levels before you can tell what kind of RP goes on there. Be mindful that many old RP servers are full and suffer lots of lag and downtime, so a newer one might be preferable.\r\n====Is it true that Trolls and Night Elves came from a common ancestor?====\r\nThis is a hot topic for those concerned with RPing, but for now the roleplayers have come to the conclusion that there is not enough hard and fast lore (or at least lore that doesn't contradict itself) provided by Blizzard to make any concrete conclusion.\r\n====I'm looking for a guild, what's the difference between Light, Medium and Heavy RP?====\r\nThese definitions are tough to classify as to the meaning. In general, always read as much as you can of what the guild says about themselves and how they say it, plus chat with some members prior to joining. There is a lot of variations within each classification of RP type. However, some common traits can still be found that define the \"heaviness\" of RP:\r\n Heavy RP :Characters are expected to remain in character at all times – in /say, /yell, /party, /guild, etc... There may be a special channel setup for out of character (OOC) discussions or the guild may allow members to use ((OOC discussion info)) style notations in guild chat or only allow OOC in 1 on 1 situations via /whisper. Some may have rules about how you can RP, others may have rules against telling someone how they can RP so there are personality variations between guilds. The activities such a guild gets involved in may range from story telling – in pubs or chat channels – through end-game raiding and/or PvP in battlegrounds or around the world. When looking to join a Heavy RP guild, it is best to chat with a member a bit about their activities first – if you’re into story telling, a guild that does battlegrounds or raids may not be a good fit or visa versa.\r\n Medium RP :Characters are expected to remain in character MOST of the time but always in /say, /yell or other situations. OOC may be allowed in guild chat, as normal conversation, or may require (( )) style notation when speaking out of character. In general, Heavy and Medium RP guilds tend to have many of the same properties but Medium RP guilds are a bit more tolerant of slips. Medium RP guilds may also use Ventrilo/Team-Speak servers, or the like, where it is 100% OOC and tend to be 100% OOC when raiding in /raid chat.\r\n Light RP :This “classification” of guilds tends to range from folks that deal with role-playing lightly through the “Anti-RP” types that verbally attack role-players or sneer/snicker at them. Often folks who are new to role-playing and are interested in the idea of trying it out, look for a Light RP guild to \"learn the ropes\" and \"try it out\" and some guilds encourage this but many don't. It is usually best to read the guilds statement about itself and “look for the signs” such as a blunt statement of “no RP”, “separate RP channel provided”, through “encouraged by the guild”. Most light RP guilds don’t require nor desire any RP in guild chat channels nor groups, parties or raid channels. Some are into the lore of the world and will discuss the subject whereas others aren’t interested in anything but playing the game.\r\n No RP :Where it states, “we are indifferent towards role-playing” through the “we don’t tolerate role-playing”. Such an addition would clear up many misunderstandings on actual role-playing. However, it should be stressed that communities that \"don't tolerate role-playing\" are not welcome on RP realms, and posting recruitment threads for such communities on RP realm forums will most likely end in the thread being closed.\r\n====Do I have to play only a playable character on the forums? Say I want to play a goblin, but my avatar has a Night Elf?====\r\n-On the forums it is perfectly acceptable to role-play as a no-playable race. However, be aware that some people may become confused by your avatar, so make sure you clearly state what species you are.\r\n====Someone called me a troll here on the forums while I'm clearly a Tauren! (Or Murloc if is April 1st.) What gives?====\r\n-A forum troll is someone who basically goes through the forum posting stupid replies and acts like a jerk. They want a fight and are willing to ruin other people's experience to get it. Trolls will be shot, hung, shot with an accursed shotgun again, and then fed to the In-Game trolls. \r\n====Hey! My role-playing topic is gone! What gives?====\r\n-If your topic does not receive any replies after about a week, it will be deleted. This is to keep the forums from getting too congested. \r\n====I don't want that to happen. Can I bump my own topic?====\r\n-Bumping your own topic is acceptable, but not suggested. However, if you are going to bump it, don't just say \"Bump.\" Make another addition to your story/Open RP/whatever. It will keep you from seeming desperate. \r\nAlso, there is a thing called a 'stealth bump.' You bump the thread and then delete your post, and no-one knows you bumped it. It is kind of smarmy and probably will be looked down upon, so only do that to keep your thread alive and concise if you must. \r\nStealth bumps are impossible on the new World of Warcraft forums.\r\n====What kind of topics aren't allowed here?====\r\n-If you have a question about the mechanics of the game or the forums, you had better ask it on general. If you want to see something added to the game, put it in the suggestions forum. Most forums are self explanatory, so only post here if you have something related to role-playing. \r\n====I role-played a character on Everquest/City of Heroes/ whatever. Can I play the same character here?====\r\n-It is possible, but you must make sure that you change the character to fit Azeroth's settings. In other words, don't try to pass yourself off as a monk from another game, play it as a druid or something similar. \r\n \r\n====Are there any other times when I should talk out of character?====\r\nA good time is probably when feelings or relationships are at stake, as well as when your In-Game decisions differ drastically from your real life ones. For example:\r\n*A paladin and a warlock enter the room. Both alliance* \r\nPaladin: A warlock! Foul demon caster! \r\nWarlock: I am just passing though Paladin. What do you want? ((What have I done to you?)) \r\nPaladin: I saw you fighting earlier! You were killed by a spider three seasons under you! You need my assistance!\r\nThis scene would much better go as: \r\n*A paladin and a warlock enter the room. Both alliance* \r\nPaladin: A warlock! Foul demon caster! \r\nWarlock: I am just passing though Paladin. What do you want? (What have I done to you?) \r\nPaladin: ((Oh, sorry. Did I come off a bit strong? I must apologize. Anyway, I did see you make a few mistakes. Would you like some help with them? I also play a warlock. )) \r\n====Ok then, how about some other OOC times? In which channels can I go OOC in and when?====\r\nI'll address each channel of communication separately. \r\n''/Say ''\r\nSay is your primary way of Role-Playing. You should attempt to stay In-Character at all times when you /Say anything as those around you can hear. Sometimes, however, you want to say something OOC that you want many people to hear, so in those hopefully rare cases you should always put double brackets around your words. \r\n''/Yell ''\r\nNever ever go OOC in this form. There is absolutely no reason to do so as you make everyone in the region listen to your comments. Doing this will most likely get you put on many a ignore list, even if you do put brackets around your words. \r\n''/General ''\r\nThis is usually your OOC channel if you have a problem that you need answered and there is no need to put brakets around your words when you talk in it as most people know you're OOC. It is alright to Role-Play there as well, just don't expect others to do the same. \r\n''/Trade ''\r\nThough it is acceptable to do this OOC, you will probably get a bit more respect if you advertise your items in a Role-Playing form. This is another one that is up to you. \r\n''/Local Defense ''\r\nThough many go OOC in this channel, it reflects very well on you if you stay IC while communicating through it. Some roleplayers adopt the idea that your Hearthstone acts as a way to communicate to the channels you tune it to, but that is a personal decision. This is commonly known as the \"hearthstone excuse\", but not all roleplayers accept it. \r\n''/Looking For Group ''\r\nLike Local Defense, it will probably net you a group much quicker if you stay In-Character. It is ok to do this OOC, but it is in your benefit that you stay IC. \r\n''/Party ''\r\nThis is generally your OOC form of communication between party members and it is a good idea to stay in /say even though you have this. Use it for communicating across distances or for establishing group tactics. \r\n''/tell ''\r\nWhispering is usually the way you tell someone something OOC without disrupting the RP flow of those around you, but it can be a powerful tool for IC communication. put up an emote that says you are whispering to someone and it will pipe the interest of others around you. You can oftentimes also RP through /tells across great distances though you by no means have to, and you must make up an explanation for such long-distance IC communication. In this form it is a good idea to put brackets around your words if they are OOC. \r\n====I know you can get reported for spamming. What if I have a really hyper character who tends to be very chatty? Can I get reported?====\r\nMost likely not. So long as you stay IC most people will not mind. Sure they might get annoyed by the character, but they aren't allowed to do anything against you so long as you are Role-Playing. Now if you keep saying the same thing over and over and over again it can be reported as spamming, so you better have a darn good IC reason for doing it.\r\n====Are there times when I can be completely and totally OOC?====\r\nYes, so long as it is in /tells, /party, an explicit OOC channel, or you place brackets around your words and you are not talking about things in the Real World. Times for this are like when determining group loot rules and during trades. It is, however, to your benefit that you stay IC as often as you can. People will be quite impressed if you pull off some RPing in places they would have never thought possible. \r\n====What about stuff like lag and glitches and just all around nasty stuff that is totally RP breaking?====\r\nAgain, if you can pull RP out of unlikely places, people will remember it and you will look good for it. Though it is ok to go OOC to explain these things, sometimes RPing them can lead to quite a bit of fun. \r\n====What is Meta-Gaming and why shouldn't I do it?====\r\nMeta-Gaming is when you know things about the world that your character has no way of knowing and you still exploit that knowledge. It is not a good idea to do so as it has no RP basis. It is better that your character heard a rumor from someone sometime that such and such might be somewhere than to say something and have no way to tell them how you know it.",},
			["Roleplaying Forum Writing Guide"] = { content = "A guide to [[Role Playing]] beginning with writing in forums.\r\nSee also:\r\n* [[Role Playing Policy]]\r\n* [[Roleplaying FAQ]]\r\n==Guide to Writing a Role-Playing Thread==\r\nOriginal version from by (Chro, Level 38 Human Rogue, Guild: Night Blades, Realm: [[Server:Feathermoon US|Feathermoon]]).\r\nIf you are reading this guide, you have probably already read the [[Roleplaying FAQ|FAQ]] or know how to Role-Play from past experiences. This addition is to give hints and tips for how to further your Forum Role-Playing. If you have noticed that you don't always get the response from other posters that you were hoping for, this is for you. \r\n===Types of RP:===\r\nAs stated in the FAQ, there are a few different types of Role-Playing. For the purpose of this guide, this article will only be focusing on Open-Role-Playing, Structured-Role-Playing, and Closed Role-Playing as these are the only three that require you to type up paragraphs and think in a plot line fashion. \r\nOpen Role Playing\r\nIn this type, every person in the thread is a equal actor and you may never God-Mode anyone unless they give their \r\npermission. The Original Poster (OP) usually starts with an end in mind and will try to steer the thread in that direction but \r\ntry to give everyone their own camera-time. \r\nStructured Role Playing\r\nThis type is still open for people to jump into and contribute, but is more rigid than an Open RP thread. The OP has a story \r\nto tell and is allowed a small amount of God-Moding throughout the thread if things deviate too far from the plot line, but should still always respect the other actor's character rights. \r\nClosed Role Playing\r\nThese threads are sort of like a sign up, as a separate thread is created for people to ask questions and register their character. These tend to be rare, but were once commonplace in the Beta Role-Playing forums. \r\n===Joining===\r\nThere are a few rules for joining an Open Role Playing thread. First of all, you must join in a logical fashion. The thread starts in Stormwind and you are a Forsaken. What are you doing in Stormwind in the first place? How did you get in? \r\nBad Example:\r\nFors came down the stairs of the Lion's Pride Inn, yawning. He began slaughtering the pitiful humans all around him.\r\n'''Critique:''' How did Fors get into the Inn? Why was he sleeping upstairs? How would no humans see him? You don't know, and the author probably has no idea either. \r\nGood Example:\r\nFors crept into the open window of the Lion's Pride Inn, quietly slitting the throat of the only human in the room. It hadn't been easy sneaking past the guards or climbing the wall, but that was what he had been trained to do. He was here on a mission, and he meant to complete it. With a light foot and a quick dagger he stepped out of the room and slew another human who had been standing just outside of the door without a sound. He only hoped that no-one would find him before he had a chance to slay them.\r\n'''Critique:''' A real, logical entrance was made and he obviously has a plan, even if he didn't reveal it yet. Plus he has given someone else a chance to interact with him. \r\nMany times you simply cannot think of a good reason for your character to be in that place a that time, so you have three options. One: You can start your character in a different location and wait for the plot to advance before joining the others. Two: You can switch to another character. Most Role-Players have many different characters to call upon, so be sure to use them. Three: Just sit back and enjoy the ride. Just because you enjoy a thread, it doesn't mean that you need to join it. \r\n===Posting===\r\nThis part is broken up into a few rules. \r\n===God-Moding===\r\nThis is the thing that every decent Role-Player hates to see. To God-Mode is to use another person's character without their consent. This can range anywhere from putting words in their mouth to killing them. Here is an example how the story can be played out, going from good to bad. \r\nGood Example:\r\nElly knocked the head off one of the advancing Scourge, shouting to her comrade Rajhin, \"We can't keep this up! There are simply too many of them!\" It was then that she noticed that behind the tidal wave of Scourge stood a single Forsaken, the one they had seen before called Kamith. He was holding his hand up high and shouting an incantation. She quickly slashed through the mass of Scourge, hoping she could interrupt him in time.\r\n'''Critique:''' This establishes what is happening and does not take control of other's characters at all, assuming that Kamith had already posted that he was beginning to cast something. \r\nOk Example:\r\nElly knocked the head off one of the advancing Scourge, shouting to her comrade Rajhin, who seemed to be having trouble, \"We can't keep this up! There are simply too many of them!\" Rajhin shouted back, \"Ya mon! We need ta be getting away!\" It was then that she noticed that behind the tidal wave of Scourge stood a single Forsaken, the one they had seen before called Kamith. He was holding his hand up high and shouting an incantation. She quickly slashed through the mass of Scourge, raising her mallet to bring it down on Kamith's head.\r\n'''Critique:''' This isn't too bad. Elly, however, is determining how Rajhin is fairing against his foes, which is a no-no, plus she is putting words in his mouth. What if Rajhin wants to keep on fighting to the death? Elly also reaches Kamith and is about to smash him. Sure she leaves that up to him, but what if he had wanted to do something while the two of them were still at a fair distance? All in all, this isn't all that bad, but treads the line of God-Moding quite dangerously. \r\nNot Good Example:\r\nElly knocked the head off one of the advancing Scourge, shouting to her comrade Rajhin, who had been stabbed in the leg and was bleeding profusly, \"We can't keep this up! There are simply too many of them!\" Rajhin shouted back, \"Ya mon! IWe need ta be getting away!\" It was then that she noticed that behind the tidal wave of Scourge stood a single Forsaken, the one they had seen before called Kamith. He was holding his hand up high and shouting an incantation. She quickly slashed through the mass of Scourge, smashing her mallet into his side, interrupting his spell. He got back to his feet quickly and usheathed his dagger. \"Mellding Paladin! You will die!\"\r\n'''Critique:''' This simply takes too many allowances. First off, Elly has portrayed Rajhin's fight in a way he probibly doesn't want. Again, always leave personal fighting against NPC's to the individual. Secondly, she puts words in both of the other players' mouths. What if Kamith wanted to act slyly and not say a word, pretend he was dead? That is the kind of thing only the other player can determine. This is definitely God-Moding, but can be played if the others let it slide, but Elly will probibly get a comment about it. \r\nBad Example:\r\nElly knocked the head off one of the advancing Scourge, shouting to her comrade Rajhin, who was barely conscious after the severe injuries he had sustained, \"We can't keep this up! There are simply too many of them!\" Rajhin could only scream as yet another blade entered his side. It was then that she noticed that behind the tidal wave of Scourge stood a single Forsaken, the one they had seen before called Kamith. He was holding his hand up high and shouting an incantation. She quickly slashed through the mass of Scourge, smashing her mallet into his side, interrupting his spell. He lay on the floor, nearly dead an drained of all his power. \"You can kill me, but my spirit and power will linger on, Light blinded Paladin!\" Elly just sneered and brought her mallet down on his skull crushing it. The Scourge behind her fell apart, saving Rajhin from an assured death.\r\n'''Critique:''' This is just bad as far as God-Moding goes. She portrays Rajhin as an almost incompetent fighter, obviously with much less skill than her. She then not only interrupts Kamith, puts a lot of words in his mouth, but also kills him! And to top it off, she just ended the battle before any of the others had a chance to do anything. This kind of thing is unacceptable. \r\nBad Just For Fun Example:\r\nElly lit into the advancing Scourge army, taking out dozens of them with every swipe. Rajhin, however, fell without even taking out a single one. She sighed, raising him from the dead while keeping the tide of Scourge away with one hand. \"Must I always say your ass, Rajhin?\" \"I be sorry, miss Elly. I be incompetent,\" he replied. She laughed and proceeded to destroy the rest of the Scourge army with a few swipes. She noticed The Forsaken Kamith trying to cast a spell, but his obvious fear of her kept his hands shaking and kept him from concentrating. She walked up to him as he begged, \"Please! Please don't kill me! I just wanted to be a real boy!\" She Destroyed him with a single flick of her finger, his body exploding. \"Well, Rajhin, my clumsy sidekick, I think all is well in Azeroth again.\" And with that, they all lived happily ever after.\r\n'''Critique:'''... \r\nAs you can see, God-Moding can be very destructive to a thread's plot line. Watch yourself to make sure you don't do it. \r\n===Too liberal use of NPCs===\r\nToo liberal use of NPCs, especially ones that are crucial to others' story, can also sometimes be harmful. Take for example the 'Bad Just For Fun Example\" above. Elly there defeats the entire army of NPCs without letting anyone else interact with them. Just like God-Moding, you want to avoid doing this. A little rule is that no matter how many soldiers you defeat, the army is always bigger until that phase of the thread is over. \r\n===Grammar===\r\nThis does not come naturally to many people and can take a while to get used to. The best suggestion for finding the proper grammar of a sentence would be to read it out loud and see if it sounds right. If it doesn't, re-arrange the words until it sounds right.\r\nEx: Brian ate the muffin, hesitant.\r\nto: Brian hesitantly ate the muffin.\r\nEven though it might not seem like a big thing, it can make all the difference that your sentences flow together, otherwise people will need to stop and re-read you post and suddenly they find that the immersion is broken just because something doesn't sound right. Don't let it get you down if you don't have good skills when it comes to grammar. To get better at recognizing the structure of sentences you should read other novels or even pick up a book on grammar. \r\n===Spelling===\r\nThe thing with spelling is to look at the word and ask yourself if it looks right. If it looks odd, change it around until it looks better. If you do that and it still doesn't look right, you can look it up in the dictionary or ask someone to correct you. Many people make the argument, \"I didn't come here to spell good!\" No, but it is important that the person you are trying to communicate to understand you. A little spelling error every now and again is nothing to fret about, but five in every sentence? Again, reading novels will help correct this problem.\r\nOf course it makes your RP look much better. Don't hesitate if you think your spelling is really bad, just ask around (with double brackets of course) how to spell those things, ignore teens that don't know you're having trouble with it and all should be fine.\r\n===Length===\r\nThe length of a post can be subjective to the situation. The ideal post is one that is around two to five paragraphs in length. Any more and people will start to feel their eyeballs drying out from staring at the screen that long. If you are having a back and forth conversation, short posts are fine, but at least try to put in a whole paragraph to keep interest up. There are few key things in a post that should always be covered.\r\nSetting: If it hasn't been established, establish it. Nothing makes it harder to imagine what is going on than if the characters are just floating in a 'white space.' Give them a world to interact with. Describing a new setting should probably take up a full paragraph.\r\nAction: What is happening in this post that makes us want to read it? Action does not have to mean that fighting is going on, action simply means that something is happening. It could be internal conflict, it could be Rarkal found a seat at the bar, Bobby might have picked some lint out of his belly-button. It doesn't matter the specifics of the action, just that something happened and you made us interested enough to read it.\r\nResolution/Suspense: You post must contain a logical end to it. You can use these to hint at what you would like to happen next. Such as, \"Killia fired his shotgun at Garmend, hoping that it would hit him. If it did, then his plan would begin.\" Naturally Garmend is going to be curious to see what Killia's plan is, so he's now more likely to let the bullet hit him. The ending of your post is crucial in that you finish your step and wait for someone else to start theirs. Give them something to work with. \r\n===Description===\r\nThis is the meat of your post. Describe, describe, describe. You are painting a picture for people to look at, so you should make it good. What ever you do, do it with description. Don't just say that you ran from the enemy, say you ran like a deer away from a fire. Say that the table wasn't only green, but that it had elvish runes carved into it. Did you kill something? Well then say how you killed it.\r\nNow too much detail can be a problem sometimes, but if you are having that problem, just back off a little bit and you'll be fine. The point of description is just so that people reading it can get a mental picture of what is going on. Remember 'white space?' You don't want your character to just stand there with his hands straight down at his sides while he talks. \r\n===Players' inactivity===\r\nAnother problem that can occur in forum roleplaying is players who introduce a character and then don't respond for 3-4 days or weeks. Basically, you end up having a character that has to fade in and out of existence and cause disjoins in character interactions. \r\ni.e.:\r\nPlayer 1: Hurbert enters the room, dropping body parts on his way in. \r\nPlayer 2: (someone else) picks up a rotting middle finger asks Hurbert, \"Did you lose this?\" holding it up. \r\n(Hurbert doesn't respond for 3-4 days or weeks so the story has to continue without any conclusion to that event, which makes that other person's part disjointed.)\r\n(In other words, when joining an RP thread one should try to make an entrance and an exit to let people know whether they are still around.)\r\nMore is to come...",},
			["Roleplaying Guide"] = { content = "For detailed information about [[Roleplaying]], see the following:\r\n* In-game: [[Roleplaying FAQ]]\r\n* In forums: [[Roleplaying Forum Writing Guide]]\r\n* [[Guide to roleplaying]]\r\nSee the [[:Category:Roleplaying|Roleplaying category]] for detailed roleplaying guides.\r\n==See also==\r\n*[[Roleplaying policy]]",},
			["Role Playing"] = { content = "#REDIRECT [[Roleplaying]]", redirect = "Roleplaying",},
			["Roll"] = { content = "== Overview==\r\nTo generate a random number in a particular range (usually 1 - 100) by [[player]]s vying for n [[loot]]ed [[item]] or [[Chest (container)|chest]].\r\nIn [[World of Warcraft]], most players would generate a random number using the [[Slash Command]]:\r\n /random <#>\r\nor\r\n /roll <#>\r\nThe number <#> denotes the range of numbers to pick randomly from. This can be a range (two numbers separated by a \"&dash;\"), or a single number. If a single number is given, 1 will be used as lower bound and the number as the higher, if no numbers are given at all 1-100 is assumed. Examples:\r\n*\"/roll 1337-1337\" will result in rolling the number 1337,\r\n*\"/random 20\" returns a number from 1 to 20 (inclusive),\r\n*\"/roll\" yields a result between 1 and 100.\r\nIn a [[Party|group or party]], rolling is [[|involuntary]] depending on the [[Loot|loot options]].\r\n===Voluntary Rolling===\r\nExample scenario:\r\n# '''Player 1''': \"Hey, I see a chest!\"\r\n# '''Player 2''': \"Okay, let's roll for it.\"\r\n# '''Player 3''': /random 100\r\n#:''System Message:'' <font color=\"yellow\">Player 3 rolled a 3 of 100.</font>\r\n# '''Player 3''': \"I guess I don't get to open it... :-(\"\r\n# '''Player 1''': /rand 100\r\n#:''System Message:'' <font color=\"yellow\">Player 1 rolled a 97 of 100.</font>\r\n# '''Player 1''': \"W00t!\"\r\n# '''Player 2''': \"Hold on, cowboy...\"\r\n# '''Player 2''': /roll\r\n#:''System Message:'' <font color=\"yellow\">Player 2 rolled a 56 of 100.</font>\r\n# '''Player 2''': \"Darn, roll hack! ;-)\"\r\n# '''Player 1''' opens the chest and loots its contents... but being nice, gives stuff not needed or can't use to the other players...\r\n# '''Player 2''': \"Sweet\"\r\n# '''Player 3''': \"Thx\"\r\n''Blizzard claims that there is no such thing as [[Roll hack|roll hacks]].''\r\nWhen you are the one who has rolled, it says '''You''' instead of your character's name.\r\n===Involuntary Rolling===\r\nSee [[Loot|Looting While In A Party]].",},
			["Rolling Plains"] = { content = "'''The Rolling Plains''' cover much of southern [[Mulgore]], stretching from [[Bloodhoof Village]] to the [[Barrens]] border. It is inhabited by many species of animal; [[wolf|wolves]], [[kodo]], [[tallstrider]]s and [[cougar]]s can all be found here. This is also the only place in all Mulgore where [[centaur]]s have been able to penetrate - their outriders have been known to wander the grassy fields. A nest of [[Windfury harpies]] can be found in the eastern part of the region.",},
			["Rom"] = { content = "'''Rom''' is a [[hill dwarf]] who helped [[Vereesa Windrunner]] and [[Falstad]] in the book [[Day of the Dragon]]. He also cooperated with [[Krasus]]. During the [[Second War]], Rom's clan was left with fourty-seven members where once they numbered in the hundreds.\r\n==Dwarves in Rom's command==\r\n*[[Gimmel]]\r\n*[[Joj]]\r\n*[[Narn]]",},
			["Rommath"] = { content = "#REDIRECT [[Grand Magister Rommath]]", redirect = "Grand Magister Rommath",},
			["Romulo"] = { content = "'''Romulo''' is one of two bosses in the fourth encounter in [[Karazhan (raid)|Karazhan]].\r\nHe can be seen backstage during the [[Return to Karazhan]].\r\n==Quotes==\r\nKarazhan\r\nReturn to Karazhan\r\nMaybe if her acting had been less transparent, we wouldn't be out of a job!\r\n==See also==\r\n*[[Julianne]]",},
			["Ronald Burch"] = { content = "'''Ronald Burch''' is a level 30 [[cooking]] [[vendor]] located in [[the Trade Quarter]] in the [[forsaken]]'s [[Undercity]].\r\nSee [[List of Undercity NPCs]].",},
			["Rookery"] = { content = "The '''Rookery''' is an area of [[Upper Blackrock Spire]]. It is accessed through the sealed door in the [[Hall of Binding]] by defeating [[Pyroguard Emberseer]] in that area. It contains a few [[dragonspawn]] guarding masses of [[dragon whelp]] eggs, which hatch if anyone comes near enough. The eggs respawn very quickly, so trying to clear the room is pointless.\r\nThis chamber also holds the [[Father Flame]] event, where [[Solakar Flamewreath]] and several more dragonspawn are summoned through the use of a post at the end of the room. Needless to say, masses of hatched dragon whelps will also join in the event, which means most groups will skip it altogether since it is entirely optional.\r\nThe Rookery leads on to the upper levels of the [[Hall of Blackhand]] which is accessed by ascending the Rookery ramp and entering through one of the hall's two doorways.",},
			["Rookery Hatcher"] = { content = "'''Rookery Hatcher''' can be found in [[Blackrock Spire]] .\r\n==Drops == \r\n \r\n0.10% Chance of an [[epic]] drop.\r\n0.41% Chance of a [[rare]] drop.\r\n5.69% Chance of an [[Uncommon]] drop.\r\n0.41% Chance of a [[common]] drop.\r\n3.21% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Roon Wildmane"] = { content = "'''Roon Wildmane''' is a level 45 [[quest giver]] located in [[Shadowprey Village]] in the [[contested]] territory of [[Desolace]].\r\nHe starts the quest Hunting in Stranglethorn.\r\nSee [[List of Desolace NPCs]].",},
			["Root"] = { content = "'''Root''' effects are a form of [[Crowd Control|crowd control]] that cause the victim to be locked in place and unable to move. Root effects are often known as '''immobilize''' effects in-game. A root effect differs from a [[Stun|stun]] effect in that the target is still able to use [[Ability|abilities]], [[Spell|spells]] or [[Melee|melee]]/[[ranged]] attacks, but cannot move from its location as long as the effect is active.\r\nExamples of abilities that can root opponents:\r\n* Druid: [[Entangling Roots]]\r\n* Mage: [[Frost Nova]]\r\n* Hunter: [[Counterattack]]\r\nAdditionally, talents such as [[Frostbite]], [[Improved Wing Clip]] and [[Improved Hamstring]] give some abilities the potential to root an opponent.\r\nA rooted [[mob]] that has no ranged attacks will be unable to attack its current [[aggro]] target. However, if players are standing in melee range, it will attack the player that has the highest [[threat]] level. Thus, it is not wise to stand near a rooted mob. Also, it is not wise to root a mob next to a player that has some threat on it, as it might get him killed.\r\n==Counters==\r\n* Items that can dispel root effects:\r\n** Ornate Mithril Boots\r\n** Spider Belt\r\n** Free Action Potion\r\n** Living Action Potion\r\n** Insignia of the Alliance\r\n** Insignia of the Horde\r\n* [[Hunter]] [[pet]]s of hunter's with the [[Bestial Wrath]] [[talent]] are immune to root effects.\r\n* [[Paladin]]s can apply a [[Blessing of Freedom]] to provide a brief immunity to root effects.\r\n* [[Mage]]s can use [[Blink]] to free themselves from root effects.\r\n* [[Rogue]]s with the Tier 9 [[Subtlety]] [[talent]] [[Shadowstep]] can use it to remove root effects.\r\n* [[Gnome]]s can use [[Escape Artist]] to free themselves from root effects.\r\n* [[Druid]]s can [[Shapeshift]] to free themselves from root effects.",},
			["Rorelien"] = { content = "'''Rorelien''' is a level 60 [[master]] [[herbalism trainer]] located in [[Honor Hold]] in the [[contested]] territory of [[Hellfire Peninsula]].\r\nShe's found in the tower in Honor Hold in an alcove on the ground floor. So it is easy to miss her.\r\nSee [[List of Hellfire Peninsula NPCs]].",},
			["Rorgish Jowl"] = { content = "'''Rorgish Jowl''' is a level 25 [[rare mob]] [[furbolg]] found roaming the [[Thistlefur Village]] camps in [[Ashenvale]]. He is on a 4-6 hour respawn timer.",},
			["Rose Colored Goggles"] = { content = "'''Rose Colored Goggles''' are cloth head armor that require 230 [[engineering]] to wear.\r\n==Source==\r\nRose Colored Goggles are made by [[Engineering|engineers]] with a skill of 230.\r\nThe components are:\r\n*4 [[Thick Leather]]s\r\n*2 [[Star Ruby|Star Rubies]]\r\nThe recipe for this item is learned from Artisan level [[Engineering Trainer]]s.",},
			["Rotation"] = { content = "==Overview==\r\nA healing rotation is a raid healing technique, where only one healer is actively healing, while the others regain their mana. When this healer is out of mana, the next one replaces him, allowing him to regenerate. This continues in a cycle until the task is finished (or, in most cases, the boss is defeated).\r\nHealing rotations rely on very good communication, high skill level (as one healer must be able to keep the Main Tank alive on his own while the others sit and regain their mana), and high awareness of the boss fight. \r\n==Good Communication==\r\nIt is imperative that you have good communication about when to switch. Using voice communication software is an increasingly useful solution.",},
			["Rotfang"] = { content = "'''Rotfang''' is a level 60 [[elite]] [[gnoll]] [[rogue]], and is part of [[Theldren]]'s team of gladiators at the [[Blackrock Depths]] arena.",},
			["Rotgrip"] = { content = "\"Deep in the depths of Maraudon lurks a great white crocolisk of myth.\" - Year of Fear calendar\r\n'''Rotgrip''' is a giant [[crocolisk]] that lives in the bottom of [[Maraudon]]. Usually this [[mini-boss]] is done after [[Princess Theradras]] by jumping off the bridge that leads to her island.\r\n==Attacks and Abilities==\r\nRotgrip has an ability called Puncture, he applies a dot that does increased physical damage everytime it stacks.",},
			["Rothos"] = { content = "'''Rothos''' is level 62 [[elite]] green [[drake]] found patrolling in [[Seradane]] in the [[Hinterlands]].\r\nThe portal in the area possibly leads to the [[Emerald Dream]] which is not implemented yet in the game. He is aided by various [[dragonkin]] and another drake, [[Dreamtracker]].",},
			["Rotting Agam'ar"] = { content = "'''Rotting Agam'ars''' are level 25-26 [[elite]] [[boar]]s found in [[Razorfen Kraul]]. Despite their odd name and appearance, they are tamable by hunters and come with Charge 3.\r\nThey are named after [[Agamaggan]].",},
			["Rotting Forest-Rager"] = { content = "'''Rotting Forest-Ragers''' can be found in [[Terokkar Forest]], from the north to southeast edge of [[Bone Wastes]], clockwise.\r\nIt is noted that this mob has the highest drop rate of Mote of Life (up to 85%) - this is however inaccurate as it is not recorded when the mob has no drops, but when it has drops it is a 85% chance to have 1-2 Mote of Life.\r\nThey can be gathered with the [[herbalism]] skill upon death, and can drop [[Unidentified Plant Parts]], one of the only [[mob]]s outside of [[Zangarmarsh]] to do so.",},
			["Rotting Hearts"] = { content = "==Objectives==\r\nBring back 10 Rotting Hearts to [[Magistrix Aminel]] in [[Tranquillien]].\r\n* icon= x10\r\n==Description==\r\nI hear the [[Amani]] [[troll]]s eat their enemies' hearts to steal their strength. They might just be on to something, <name>. With the proper treatment, the hearts of the unliving can produce potent elixirs. Hunt down the zombies that roam the [[Dead Scar]] and bring me their hearts. I'll show you the kind of enhancement we can perform to your physical prowess against the undead.\r\n==Completion==\r\n''Take this draught, <name>. After you drink it, your physical strength against the [[Scourge]] will receive a boost. If you need more than this sample bring me more hearts.''\r\n==Gains==\r\n*1150 [[XP]]\r\n*500 [[reputation]] with [[Tranquillien]]\r\n==Notes==\r\nThe items drop from [[Risen Hungerer]]s and [[Risen Stalker]]s in the Dead Scar. They are not soulbound and are not quest items (you can collect them when you don't have the quest).\r\nAfter completion of this quest, it allows you to take the repeatable quest, More Rotting Hearts, which does not grant XP or reputation.",},
			["Rotting Orchard"] = { content = "[[The Rotting Orchard]] is located in southern [[Duskwood]], east of the [[Yorgen Farmstead]], and west of the [[Tranquil Gardens Cemetery]]. It was once a bright fruit orchard loaded with apples, pears, and peaches. Now the orchard lies abandoned, the fruit fallen and rotting in the fields. Recently, the orchard has become home to many ravenous [[Worgen]] led by [[Gutspill]] and [[Nefaru]] at the nearby [[Roland's Doom]].",},
			["Rotting Slime"] = { content = "'''Rotting Slime''' can be found in [[Ashenvale]].\r\n==Drops == \r\n \r\n Quest items dropped by '''Rotting Slime''' \r\nAlso 2 random [[Uncommon]] item drops\r\nAlso 1 random [[Common]] item drops",},
			["Rotting Sludge"] = { content = "'''Rotting Sludge''' can be found in [[Eastern Plaguelands]] .\r\n==Drops == \r\n \r\n0.02% Chance of a [[rare]] drop.\r\n0.76% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\n0.53% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Rot Hide"] = { content = "#redirect [[Rot Hide gnolls]]", redirect = "Rot Hide gnolls",},
			["Rot Hide Gnoll"] = { content = "'''Rot Hide Gnolls''' are found at [[Garren's Haunt]] in [[Tirisfal Glades]]\r\n==Abilities==\r\n*'''Curse of Thule''': Reduces the Spirit of an enemy by 2 for 4 min.\r\n==Objective of==\r\n*Drops [[Embalming Ichor]] for [[Graverobbers]].",},
			["Rot Hide gnolls"] = { content = "#REDIRECT [[Rot Hide gnoll]]", redirect = "Rot Hide gnoll",},
			["Rouge"] = { content = "'''Rouge''' is by Webster's Dictionary as:\r\n# Any of various cosmetics for coloring the cheeks or lips red.\r\n# A red powder consisting essentially of ferric oxide used in polishing glass, metal, or gems and as a pigment.\r\n==Conclusion==\r\nNote the lack of anything regarding [[Stealth]], [[Pickpocket]]ing, or high [[DPS]]. You would probably be more interested in reading about a '''[[rogue|ROGUE]]'''. Oh, did we mention that \"Rouge\" is a common misspelling for Rogue?",},
			["Roughshod Pike"] = { content = "Combining this with Omokk's Head at Urok's Tribute Pile will summon [[Urok Doomhowl]].\r\n==As an object==\r\nThe '''Roughshod Pike''' is located in [[Lower Blackrock Spire]].\r\n===Directions to find===\r\nDirectly across the room from the entrance to the room with the Ogre boss, you'll see two sleeping Scarshield Legionnaires. On the wall behind them are you pikes waiting for you to pick them up. They do have gears when you mouse over.",},
			["Rough Arrow"] = { content = "==Source==\r\nThis item is sold in [[stack]]s of 200 from a General Goods [[vendor]], fletcher, or bowyer for 10 copper .\r\n==Notes==\r\nThis item cannot be sold back to a vendor.\r\n'''Rough Arrow''' is low-level [[ammo]] for a [[bow]]s or [[crossbow]]s.",},
			["Rough Blasting Powder"] = { content = "'''Rough Blasting Powder''' is a component for various [[explosives]].\r\n==Source==\r\nRough Blasting Powder is created by [[Engineering|engineers]] with at least 1 skill.\r\nThe components are:\r\n*1 [[Rough Stone]]\r\nThe [[schematic]] is learned from the engineering trainer.\r\n==Rough Blasting Powder as an Ingredient==\r\n'''Rough Blasting Powder''' is used in the following recipes:\r\n===[[Engineering]]===\r\n*[[Rough Dynamite]]\r\n*[[Crafted Light Shot]]\r\n*[[Rough Copper Bomb]]",},
			["Rough Bronze Leggings"] = { content = "'''Rough Bronze Leggings''' are low level mail leg armor that provide [[stamina]] and [[spirit]].\r\n==Source==\r\nRough Bronze Leggings are made by [[blacksmithing|blacksmiths]] with a skill of 105.\r\nThe [[plans]] are learned from a trainer.",},
			["Rough Copper Bomb"] = { content = "'''Rough Copper Bomb''' is a type of [[Bomb]] that [[Apprentice]] [[Engineering|Engineers]] can make.\r\n==Source==\r\nRough Copper Bomb is crafted by [[Engineering|engineers]] with a skill of 30.\r\nThe components are:\r\n*1 [[Copper Bar]]\r\n*1 [[Handful of Copper Bolts]]\r\n*2 [[Rough Blasting Powder]]s\r\n*1 [[Linen Cloth]]\r\nThe [[schematic]] is learned from the Engineering trainer.\r\n==Notes==\r\nProduces 2 bombs.",},
			["Rough Grinding Stone"] = { content = "==Source==\r\nRequires [[Blacksmithing]] (25)\r\nThis item can be acquired through crafting or another combine-type effect.\r\n==Rough Grinding Stone as an ingredient==\r\nThis item is used to make: \r\n* Copper Battle Axe\r\n* Ironforge Breastplate\r\n* Copper Chain Vest\r\n* Copper Claymore\r\n* Runed Copper Gauntlets\r\n* Thick Bronze Darts\r\n* Silver Skeleton Key\r\n* Copper Dagger\r\n* Silver Rod\r\n* Runed Copper Bracers\r\n* Runed Copper Pants\r\n* Rough Bronze Boots\r\n* Thick War Axe\r\n* Big Bronze Knife\r\n* Runed Copper Breastplate",},
			["Rough Sharpening Stone"] = { content = "'''Rough Sharpening Stones''' are created by [[Blacksmithing|Blacksmiths]] and will sharpen a [[sword]], [[axe]], [[dagger]], or [[polearm]] to perform more damage.\r\n==Source==\r\n'''Rough Sharpening Stones''' are crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 1.\r\nThe components are:\r\n*1 [[Rough Stone]]\r\nThe [[plans]] are taught by the Blacksmithing trainer.",},
			["Rough Stone"] = { content = "Rough Stone can be found while [[mining]] and is used in [[Blacksmithing]], [[Engineering]] and [[Jewelcrafting]].\r\n==Source==\r\nFound in [[copper]] veins. \r\n==Rough stone as an Ingredient==\r\nRough Stone is used in the following recipes:\r\n===[[Blacksmithing]]===\r\n* [[Rough Grinding Stone]]\r\n* [[Rough Sharpening Stone]]\r\n* [[Rough Weightstone]]\r\n===[[Engineering]]===\r\n* [[Rough Blasting Powder]]\r\n====[[Jewelcrafting]]====\r\n*[[Rough Stone Statue]] \r\n==Notes==\r\nAlso see: [[Stone]]s",},
			["Rough Stone Statue"] = { content = "==Source==\r\nRough Stone Statue is crafted by [[Jewelcrafting|Jewelcrafters]]. This crafting skill is learned when you learn the [[Jewelcrafting]] profession.\r\nThe components are:\r\n*8 [[Rough Stone]]",},
			["Rough Weightstone"] = { content = "==Source==\r\nRequires [[Blacksmithing]] (1)\r\nThis item can be acquired through crafting or another combine-type effect.",},
			["Rowboat"] = { content = "A '''rowboat''' is an 8- to 12-foot-long [[boat]] for 2 or 3 people. It moves about 1 1/2 miles per hour. Rowboats can be life rafts. [[Humans]], [[orcs]], [[night elves]], and [[blood elves]] all have a different style of rowboat in WoW.",},
			["Roxxik"] = { content = "'''Roxxik''' is a level 46 [[artisan]] [[engineering trainer]] located in the [[Valley of Honor]] in the [[orcish]] city of [[Orgrimmar]] .\r\nSee [[List of Orgrimmar NPCs]].",},
			["Royal Apothecary Society"] = { content = "The '''Royal Apothecary Society''' is an [[alchemy|alchemical]] society based in the [[Apothecarium]] in [[Undercity]]. It was created by Lady [[Sylvanas Windrunner]] in order to create a new Undead plague to wipe out the scourge and other forms of life. Its members are all [[Forsaken]] or other types of Undead beings who joined Sylvanas' cause. They are constantly brewing up new plagues to unleash upon Sylvanas' enemies. The other races of the [[Horde]] believe they are working on a remedy to cure their \"illness\". Members of the Apothecary society are called [[Apothecary|Apothecaries]]. Due to repeated failures by the society to make a new plague of undeath, Sylvanas has recruited [[necromancer]]s to find other means of raising slain enemies to her cause. If the society cannot finish their master plague soon, they may find their society disbanded by Sylvanas.\r\n==Background==\r\nOriginally based in the Apothecarium in Undercity, the Royal Apothecary Society was active in [[Tirisfal Glades]] and [[Silverpine Forest]]. They can can also be found in Outland, and Northrend. Wherever there are Forsaken, there are Society members. Undead tinkers, rogues and wizards continued their studies of science to eradicate the [[humans]] and [[Scourge]] from the area. When Lady Sylvanas shrugged off the control of [[Arthas]] and the Scourge and began to free the forsaken, they staked out an area of Lordaeron for their own and attempted to exist in the ruins of [[Capital City|Lordaeron City]]. The forsaken burned with a desire to eradicate the Scourge, seeing it as the reason behind their undeath and misery. Attacks from humans forced them to realize they truly had no friends in this harsh post-war world.\r\nThe [[Scarlet Crusade]] and the Scourge were their greatest enemies, both refused to let the forsaken exist as they are. When the Scourge began attempting to control Lady Sylvanas' subjects after she had freed them, she knew drastic measures were needed to protect the forsaken’s way of existence. The Scourge had a limitless supply of warriors: any mortal they killed could be raised as an undead to be controlled. The forsaken do not have that level of necromantic power at their disposal, and the Lady realized she needed another way of dealing with the threats. Then she discovered that mortals, particularly the zealots of the Scarlet Crusade, did not believe that the forsaken were not like the Scourge, and destroyed any undead they found regardless of affiliation. When her scouts didn’t return from their missions around human territory, Lady Sylvanas correctly assumed the worst and began making plans for defenses against humans as well.\r\nThe forsaken queen initially chose two brilliant minds to lead her new Apothecary Society. Faranell, a human wizard who excelled in magical potion creation, and Oni'jus, a half-elf infiltrator who was a master of mundane poison concoction (and whose idea it was to add \"Royal\" in front of their fledgling group’s name). A dwarf tinker, Brightflame Masjenal, later rounded out her three leaders, with Faranell leading the three. They were set to build a society dedicated to researching ways to protect the forsaken from both mortal and Scourge attacks using toxins and poisons. Lady Sylvanas has ordered her Master Apothecary to construct a plague to match the one Ner’zhul brought to Azeroth, only killing undead as well as mortals. This impressive feat has not been accomplished yet, in large part because of the lack of necromancers in the Royal Apothecary Society. Yet Faranell has the best minds under him working on the problem and they slowly make progress. Their plague still kills mortals without giving them undeath, but Faranell promises results in the future. The Royal Apothecary Society has grown to 3,500 members now. Its top minds are making deadlier and more destructive toxins as Lady Sylvanas works to free more beings from the Scourge’s control. The Forsaken, and the Society, are alone in the world, liked by neither mortals nor their fellow undead, but they will fight to maintain their freedom from both.\r\nThe base of the Royal Apothecary Society is in Lady Sylvanas’ Throne Room in the Undercity, where the three leaders can meet with their queen and discuss plans of attack and reported Scarlet Crusade and\r\nScourge movements. The laboratories and testing rooms of the Society are also located in the Undercity.\r\n==Organization==\r\nThe Royal Apothecary Society is broken into three groups: Research and Development; Testing; and Implantation. R&D is staffed by wizards and rogues with a talent for mixing poisons. They make a variety of toxins from run-of-the-mill nerve gas, delayed poison and flesh dissolving sprays, to more magical potions such as fire potion (which burns the drinker from the inside), and even one that makes the drinker insane, assuming the mannerisms of another race. They are also in charge of roaming the countryside to look for ingredients for their foul concoctions. This group resides solely in the Undercity and reports directly to Master Apothecary Faranell.\r\nTesting is comprised of the more daring undead, many who were fighters and rangers in their lives. Their job is to scout the area of Tirisfal Glades and Silverpine Forest for subjects on which to test what comes out of R&D. Mortals or Scourge, it doesn’t matter as long as they’re not Forsaken. They must take these beings alive, and preferably as unharmed as possible, and return them to the Undercity. Here the Testing department applies the various potions the R&D department has concocted, seeing if they have the desired effects. The desired effects are commonly horrific — the best mortals can hope for is that a potion merely kills them instead of having its intended effect. Quick death is rarely the goal of these vile brews. The Scourge have it a little easier, as potions may commonly have little to no effect, as there is no life to be taken away. However, if they survive a round of tests, they will be present for the next round. It is very unlikely these unwilling test subjects will return alive — or undead. Master Apothecary Oni-jus heads this area in addition to aiding the R&D department.\r\nThe third group, Implantation, is dedicated to getting the finished toxins to their target, which is primarily the job of tinkers, rogues and other crafty types. Some devise mechanisms to deliver toxins or design and forge weapons for the job; others have the more dangerous job of administering the toxins personally, wielding the weapons or sneaking into the dwellings of the targets. This group reports to Master Apothecary Brightflame Masjenal.\r\n==Membership==\r\nThe Royal Apothecary Society originally was created from those forsaken with poison-concocting skills: wizards and rogues. The forsaken had no claim to necromancers — they were all closely guarded by the Scourge — so Sylvanas freed as many mages and rogues as she could, although they were few and far between. She was best at freeing fighters and barbarians to follow her. Later, the Society became large enough to find places for anyone who felt qualified to join, as the brawnier undead were needed to catch test subjects and the more intellectual were needed to develop the toxins and the delivery mechanisms. As Sylvanas must free every undead she can (being picky isn’t an option), the Society is not particular as to who joins. A willingness to work hard, a talent that can be utilized and a deep-seated hatred for the Scourge is all that is needed.\r\nLady Sylvanas does not prefer one race over another, despite her high elf roots. The forsaken, and therefore the Society, are mostly human because the undead who existed around Lordaeron City were human. As it grows, dwarves, high elves, half-elves, and even some orcs and trolls have joined the Society. An undead who wishes to join the Royal Apothecary Society only has to inform an existing member, usually identified by an armband with a flask and crown embroidered on it, of her interest. The Society member will inform his leader, one of the Master Apothecaries, who sets up an interview with the interested party. If Sylvanas manages to free a wizard or sorcerer from the Lich King’s control, she will invite him or her to the Society herself.\r\n==Structure of the Royal Apothecary Society==\r\nThe society is led by [[Master Apothecary Faranell]], and is divided into three departments:\r\n* ''Research & Development'' also controlled by Faranell;\r\n* ''Testing'' under [[Apothecary Oni'jus]], a former female [[half-elf]] who used to serve [[Prince Arthas]] as an infiltrator before he allied with the [[Scourge]] and the [[plague]] killed her;\r\n* ''Implantation'' under Apothecary [[Brightflame Masjenal]], an undead female [[Ironforge]] [[dwarf]] with tinker abilities.",},
			["Royal Exchange"] = { content = "'''The Royal Exchange''' is the eastern of the two large trade districts in [[Silvermoon]].",},
			["Royal Gallery"] = { content = "The '''Royal Gallery''' is beyond the small courtyard park, next to the [[Royal Library]]. The gallery features grandoise statues of such illustrious personas as [[Mara Fordragon]], [[King Llane]], and [[Daelin Proudmoore]].",},
			["Royal Historian Archesonus"] = { content = "'''Royal Historian Archesonus''' is a [[dwarf]] located in the [[High Seat]] in [[Ironforge]]. She wrote [[The Fall of Lordaeron and the Scouring of the Eastweald]] and [[On Plagues, Curses, and Blights]].\r\n==Quests==\r\n*[[The Smoldering Ruins of Thaurissan]] \r\n**[[The Smoldering Ruins of Thaurissan (2)]] \r\n==Quotes==\r\nGossip\r\nGreetings, <name>. Have you come to learn of the history of Ironforge?\r\n==See also==\r\n*[[List of Ironforge NPCs]]",},
			["Royal Library"] = { content = "The '''Royal Library''' of [[Stormwind]] is located inside [[Stormwind Keep]]. There is an extensive collection of scrolls, tomes, books and texts on anything of historical, religious, cultural or bureaucratic significance here, and adventurers from all races of the [[Alliance]] come here to peruse the lore.\r\n==History==\r\nDuring the [[Second War]], the [[Book of Medivh]] was stored here for a period. The book was stolen from here, either by agents of [[Alterac]] (according to the orc campaign of Beyond the Dark Portal) or by [[Ner'zhul]]'s Death Knights (according to the human campaign).",},
			["Royal Quarter"] = { content = "The '''Royal Quarter''' of the [[Undercity]] contains the throne room where the Dark Lady [[Sylvanas Windrunner]], and her general the [[dreadlord]] [[Varimathras]] control their burgeoning empire of undeath. It is protected by a squad of elite royal deathguards. It can be found right next to [[the Apothecarium]].\r\nThis is also the home to the [[Battlemaster]]s, the NPCs who provide a means to access [[Battlegrounds]].",},
			["Royal Seal of Eldre'Thalas"] = { content = "The '''Royal Seal of Eldre'Thalas''' is a [[quest reward]] from The Emerald Dream....",},
			["RP-PvP"] = { content = "#Generally, an [[acronym]] for \"[[Role Playing|'''R'''ole '''P'''laying]] plus [[PvP|'''P'''layer '''v'''s '''P'''layer]]\".\r\n#A type of [[Realm]] in [[World of Warcraft]] that combines the [[RP]] and [[PvP]] [[ruleset]]s.\r\n#:This is the new server type (as of 1.8) which combines [[RP]] and [[PvP]] into one server:\r\n#:* [[RP]] behaviour rules.\r\n#:* [[PvP]] experience.\r\n==History==\r\nOriginally, the World or Warcraft realm choices were:\r\n*Normal (PvE ruleset, roleplaying not enforced)\r\n*PvP (PvP ruleset, roleplaying not enforced)\r\n*RP (PvE ruleset, roleplaying enforced)\r\nHowever, players demanded another realm type, which combined the PvP ruleset with the roleplaying policies. This new realm type, called RP-PvP, was finally introduced in [[Patch 1.8]].\r\nIdeally these realms would be the perfect choice for roleplayers who want to have less restrained, more spontaneous PvP experience than they would on realms with the PvE ruleset, and free of [[bluewall]]ing. However, RP-PvP realms have a large share of players who break the RP policies, as well as those who engage in [[ganking]], [[corpse camping]] and other kinds of [[griefing]]. If you come from a RP or PvE server, you may quickly come to realize this world as much more hostile and irritating then you may have expected.\r\n==Difficulties==\r\nUnlike a normal RP server where you can play both Alliance and Horde, there is a complete in-game isolation of the factions. So RP based battles are a little harder to coordinate. Not to mention the social barrier for players. Just like any PvP server, you may never know what your enemy was thinking.\r\nIt is not true that most RP-PvP'ers don't RP. There is a less ''noticeable'' focus on RP because, plain and simply, people are trying to kill you constantly. Many would agree that PvP'ers in general have a more competitive mind set, and RP time is divided between time spent trying to get decent gear to survive or victimize more effectively. Another common misconception is that RP policies on RP-PvP realms are less strict than on normal RP realms, this is completely false. However, the enforcement of rules tends to vary server to server as it does on all types of servers.\r\nThe most frequent difficulty on RP-PvP or normal RP servers comes from the expectations of disgruntled would be role-players. There is a small percentage that has their own idea of the way RP should be, that don't feel there is enough RP, or maybe simply feel left out. As a result, forum threads declaring that RP is dead are commonplace.\r\n===US Servers===\r\n** [[Server:Emerald Dream|Emerald Dream]] \r\n** [[Server:Lightninghoof|Lightninghoof]] \r\n** [[Server:Maelstrom|Maelstrom]] \r\n** [[Server:Ravenholdt US|Ravenholdt]]\r\n** [[Server:The Venture Co US|The Venture Co]]\r\n** [[Server:Twisting Nether|Twisting Nether]]\r\n===EU Servers (English)===\r\n** [[Server:Defias Brotherhood Europe|Defias Brotherhood]]\r\n** [[Server:Ravenholdt Europe|Ravenholdt]]\r\n** [[Server:Scarshield Legion Europe|Scarshield Legion]]\r\n** [[Server:Sporeggar Europe|Sporeggar]]\r\n** [[Server:The Venture Co Europe|The Venture Co]]\r\n===EU Servers (German)===\r\n** [[Server:Das Konsortium Europe|Das Konsortium]]\r\n** [[Server:Das Syndikat Europe|Das Syndikat]]\r\n** [[Server:Der abyssische Rat Europe|Der abyssische Rat]]\r\n** [[Server:Die Arguswacht Europe|Die Arguswacht]]\r\n** [[Server:Die Todeskrallen Europe|Die Todeskrallen]]\r\n** [[Server:Kult der Verdammten Europe|Kult der Verdammten]]\r\n===EU Servers (French)===\r\n** [[Server:Conseil des Ombres Europe|Conseil des Ombres]]\r\n** [[Server:Culte de la Rive noire Europe|Culte de la Rive noire]]\r\n** [[Server:La Croisade écarlate Europe|La Croisade écarlate]]\r\n===EU Servers (Spanish)===\r\n** [[Server:Shen'dralar Europe|Shen'dralar]]\r\n===Role-Playing AddOns===\r\n* FlagRSP - Provides role play status flags & character descriptions:\r\n** (No longer supported. Shown here for posterity)\r\n* FlagRSP2 - Continuation of Flokru's work:\r\n** 1.1.2\r\n** 1.1.2\r\n** [[FlagRSP2]] wowwiki entry.\r\n* MyRolePlay - Provides extensive role play status options and many features for enchancing role play. Developed by Moncader(Moncader of Shadow Council) and k0nker(Xynistari of Shadow Council)\r\n** \r\n** Alpha 2.7.40\r\n===RP-PvP Communities===\r\n* - Community for roleplayers of the RP-PvP realms.",},
			["RP"] = { content = "#REDIRECT [[Roleplaying]]", redirect = "Roleplaying",},
			["RPG"] = { content = "#REDIRECT [[Warcraft RPG]]", redirect = "Warcraft RPG",},
			["RPG classes"] = { content = "Articles concerning [[Warcraft RPG]] & World of Warcraft RPG [[class]]es.\r\nSome of these classes are playable in the MMO, some are featured just as [[NPC]]'s, and others may be added in the future.\r\n==[[Core class]]es==\r\nCore classes are the most common classes\r\n[[:Category:Epic classes|Epic core classes]]\r\n==[[Prestige class]]es==\r\nPrestige classes are specific paths to power and renown (or infamy, as the case may be).They are less common in the world.\r\n==[[Variant class]]es==\r\nVariant Classes are slightly altered core classes, except the [[martial enchanter]] that is a slightly altered prestige class.\r\n==[[Creature class]]es==",},
			["RRQ"] = { content = "#redirect [[Repeatable reputation quest]]", redirect = "Repeatable reputation quest",},
			["Ru'sad"] = { content = "'''Ru'sad''' is a [[scourge]] [[necromancer]] in charge of the undead forces found in [[Zul'Aman]]. He was under command of leaders in [[Stratholme]]. He was interested in killing the [[high elves]] found there, to prevent them from rejoining any high elves in [[Hillsbrad]] or [[Khaz Modan]]], in order to prevent them from reviving the Sunwell. He had sent gargoyles, ghouls, and zombies into the jungles to look for them. [[Brann Bronzebeard|Brann]] killed one of these gargoyles during his journey in Zul'aman and found a letter written by Ru'sad on its corpse, giving hints that the lost and scattered high elves, still had importance.\r\n==Ru'sad's letter==\r\n:To my illustrious masters,\r\n:I regret to inform you that several Quel’dorei\r\nbands still wander loose in Zul’Aman. The elves know\r\nforests better than I, and the ghouls and zombies\r\nmake a fearsome amount of noise trudging through\r\nthe overgrowth. The gargoyles are somewhat more\r\nhelpful; they allowed me to discover one refugee\r\ngroup and kill them as they slept. However, I\r\nrespectfully request additional support. Incorporeal\r\ntroops — shades or ghosts, perhaps — would be\r\nparticularly useful.\r\n:Despite the current problems, I am confident that\r\nit is only a matter of time before we finally destroy\r\nthe elves. They will not join with their allies in\r\nHillsbrad or Khaz Modan. They will not rally\r\ntogether. They will not revive the Sunwell.\r\n:Respectfully,\r\n:Necromancer Ru'sad",},
			["Ru'zah"] = { content = "'''Ru'zah''' can be found dancing in the inn of [[Stonebreaker Hold]] in [[Terokkar Forest]] .",},
			["Ruak Stronghorn"] = { content = "'''Ruak Stronghorn''' is a level 65 [[master]] [[herbalism trainer]] located at [[Thrallmar]] in the [[contested]] territory of [[Hellfire Peninsula]]. He is in the tower at the top of the tallest hill in [[Thrallmar]].\r\nSee [[List of Hellfire Peninsula NPCs]].",},
			["Ruby Crown of Restoration"] = { content = "==Source==\r\nThis item can be crafted using [[Jewelcrafting]] (225); taught by Design: Ruby Crown of Restoration.",},
			["Ruby Dragonshrine"] = { content = "The '''Ruby Dragonshrine''' is the final resting place of the [[Red Dragonflight|red dragonflight]]. Under attack by the Scourge, both the [[Alliance]] and the [[Horde]] have sent squads to assist the red flight.\r\nLocated on the western edge of [[The Dragon Wastes]], south of the [[Obsidian Dragonshrine]], north of the [[Azure Dragonshrine]], west-northwest of [[Wyrmrest Temple]], just to the northeast of [[Snowfall Glade]], and southeast of [[Agmar's Hammer]]. The Area is guarded by [[Ruby Watcher]]s.\r\n[[Dahlia Suntouch]] was the shrine's previous keeper until she was slain at the feet of the deathknight Duke Vallenhal.",},
			["Ruby Pendant of Fire"] = { content = "'''The Ruby Pendant of Fire''' is an [[uncommon]] necklace that will likely be desired by fire [[Mage]]s or the odd [[Warlock]] that focuses on fire spells. It can be crafted by [[jewelcrafter]]s with a skill level of 235.",},
			["Ruby Slippers"] = { content = "'''Ruby Slippers''' are epic cloth boots for DPS casters.\r\n==Source==\r\nThis item drops from the [[Wizard of Oz]] encounter in [[Karazhan]].\r\n==Notes==\r\n*The Use effect has a 10 second cast time and can be used while in combat, the same as the [[hearthstone]].\r\n*The hearthstone and the slippers will have the same Inn. You cannot set a different inn to the slippers.\r\n*The hearthstone and the slippers are on a shared cooldown, so all this power does is save an inventory space. If you end up replacing the slippers, you can get a new hearthstone from an innkeeper.\r\n*The hearth ability will not work when the slippers are broken.",},
			["Rudra Amberstill"] = { content = "'''Rudra Amberstill''' is a level 10 quest giver located at [[Amberstill Ranch]] in the [[dwarven]] starting zone of [[Dun Morogh]].\r\nShe starts the quest Protecting the Herd (Elite).\r\n==See also==\r\n*[[List of Dun Morogh NPCs]]",},
			["Rufus Montaine"] = { content = "Sir '''Rufus Montaine''' was a handsome red-haired [[human]] [[knight]] who died during the [[A Blaze of Glory|Battle of Theramore]]. Although he fought on the side of [[Daelin Proudmoore]] during the battle, \"his honor was without stain\" and he is remembered with honor as the one that taught [[Thrall]] \"...about respect\", and being \"...a very good teacher\" in the lesson. \r\nThrall had first encountered Rufus at [[Durnholde Keep]] during one of [[Aedelas Blackmoore]]'s gladiatorial tournaments. Rufus was with his mercenary father [[Morgan Montaine|Morgan]] as spectators at the tournament. Rufus was impressed by Thrall and saw dignity in the [[orc]]. He wanted to know what his grandfather knew, when he fought the orcs in the [[Second War]]; the spirit of the orcs. His father was reluctant, and didn't want his son to fight, but was goaded into giving permission by fellow mercenaries and Blackmoore himself. He was given permission to duel with Thrall using battlesticks. Rufus bowed before Thrall before the match began to show respect to the young orc (although Thrall thought it an odd gesture). Both fighters were skilled, and the duel lasted a while, but Thrall ultimately won. Rufus smiled at Thrall as he got up, and shook Thrall's hand in respect (despite his father's disgust at the action). It was the first time anyone had ever shown Thrall that gesture and he had no idea what it meant, or what the emotion was. It was the first time anyone had ever shown him respect.\r\nSome time later still in his youth, he left his home and pledged his service to the Proudmoore family, after his father had gotten into shady dealings. Years later, he traveled with Proudmoore to [[Kalimdor]] and died during when the [[Horde]] besieged Theramore. He fought in a particularly fierce section of the battle in a field of tall grass. He fought against six high ranked orcs. During the skirmish he was wounded many times (though his face was unblemished), and two arrows were shot into his back. He was killed in that spot.\r\nHis body was later discovered on the battlefield by [[Jaina]] and Thrall not long after the battle. Jaina recognized his crest and his reputation. She remembered him as the grandson of a Montaine that fought by her father's side during the Second war. Thrall remembered him as being the teacher who taught him respect. Thrall closed the dead knight's eyes, and they tended his body with honor.",},
			["Ruga Ragetotem"] = { content = "'''Ruga Ragetotem''' is a level 30 [[quest giver]] located in [[Camp Taurajo]] in the [[Horde]]-aligned territory of [[the Barrens]].\r\nHe starts the following quests:\r\n* Trial at the Field of Giants\r\n* Speak with Thun'grim\r\nSee [[List of the Barrens NPCs]].",},
			["Rugged Armor Kit"] = { content = "==Source==\r\nTrained at 225+ Leatherworking Trainer.\r\n==Quests==\r\nRugged armor kits can be turned in for completion of several quests:\r\n*8 rugged armor kits can be exchanged for 20 [[Darkmoon Faire]] tickets and 100 reputation (at all rep levels)\r\n*8 rugged armor kits are part of the items required for completion of [[Logistics Task Briefing VII]] in Silithus\r\n*25 rugged armor kits are required for completion of [[Craftsman's Writ]] - Rugged Armor Kit at [[Lights Hope Chapel]]\r\n*Upon completion of the quest \"Pristine Yeti Hide\" (A) or [[Quest:Perfect Yeti Hide|Perfect Yeti Hide]] (H) you will receive one rugged armor kit in the mail.",},
			["Rugged Hide"] = { content = "==Source==\r\n==Rugged Hide as an ingredient==\r\nThis item is used to make: \r\n* Cured Rugged Hide",},
			["Rugged Leather"] = { content = "'''Rugged Leather''' is used mainly by [[Leatherworking|Leatherworkers]] to create various leather armor.\r\n==Source==\r\nRugged Leather is the last stage of non-Outland [[leather]] [[Skinning|skinned]] directly from normal monsters(lvl 55-60). [[Leatherworking|Leatherworkers]] with 250 skill can create a Rugged Leather from six [[Thick Leather]]s.\r\n==As an Ingredient==\r\nRugged Leather is used in the following recipes:\r\n===[[Blacksmithing]]===\r\n* [[Corruption (Sword)]]\r\n* [[Dawn's Edge]]\r\n* [[Enchanted Battlehammer]]\r\n* [[Huge Thorium Battleaxe]]\r\n* [[Imperial Plate Belt]]\r\n* [[Imperial Plate Shoulders]]\r\n* [[Ornate Thorium Handaxe]]\r\n* [[Thorium Boots]]\r\n* [[Volcanic Hammer]]\r\n===[[Enchanting]]===\r\n* [[Enchanted Leather]]\r\n===[[Engineering]]===\r\n* [[Alarm-O-Bot]]\r\n* [[Dark Iron Rifle]]\r\n* [[Field Repair Bot 74A]]\r\n* [[Large Blue Rocket Cluster]]\r\n* [[Large Green Rocket Cluster]]\r\n* [[Large Red Rocket Cluster]]\r\n* [[Lifelike Mechanical Toad]]\r\n* [[Masterwork Target Dummy]]\r\n* [[Powerful Seaforium Charge]]\r\n===[[Leatherworking]]===\r\n* [[Black Dragonscale Breastplate]]\r\n* [[Black Dragonscale Leggings]]\r\n* [[Black Dragonscale Shoulders]]\r\n* [[Blue Dragonscale Breastplate]]\r\n* [[Blue Dragonscale Leggings]]\r\n* [[Blue Dragonscale Shoulders]]\r\n* [[Chimeric Boots]]\r\n* [[Chimeric Gloves]]\r\n* [[Chimeric Leggings]]\r\n* [[Chimeric Vest]]\r\n* [[Chromatic Cloak]]\r\n* [[Dawn Treaders]]\r\n* [[Devilsaur Gauntlets]]\r\n* [[Devilsaur Leggings]]\r\n* [[Frostsaber Boots]]\r\n* [[Frostsaber Gloves]]\r\n* [[Frostsaber Leggings]]\r\n* [[Frostsaber Tunic]]\r\n* [[Girdle of Insight]]\r\n* [[Green Dragonscale Breastplate]]\r\n* [[Green Dragonscale Gauntlets]]\r\n* [[Green Dragonscale Leggings]]\r\n* [[Heavy Scorpid Belt]]\r\n* [[Heavy Scorpid Bracers]]\r\n* [[Heavy Scorpid Gauntlet]]\r\n* [[Heavy Scorpid Helm]]\r\n* [[Heavy Scorpid Leggings]]\r\n* [[Heavy Scorpid Shoulders]]\r\n* [[Heavy Scorpid Vest]]\r\n* [[Hide of the Wild]]\r\n* [[Ironfeather Breastplate]]\r\n* [[Ironfeather Shoulders]]\r\n* [[Living Breastplate]]\r\n* [[Living Leggings]]\r\n* [[Living Shoulders]]\r\n* [[Might of the Timbermaw]]\r\n* [[Mongoose Boots]]\r\n* [[Red Dragonscale Breastplate]]\r\n* [[Rugged Armor Kit]]\r\n* [[Runic Leather Armor]]\r\n* [[Runic Leather Belt]]\r\n* [[Runic Leather Bracers]]\r\n* [[Runic Leather Gauntlets]]\r\n* [[Runic Leather Headband]]\r\n* [[Runic Leather Pants]]\r\n* [[Runic Leather Shoulders]]\r\n* [[Shifting Cloak]]\r\n* [[Stormshroud Armor]]\r\n* [[Stormshroud Pants]]\r\n* [[Stormshroud Shoulders]]\r\n* [[Swift Flight Bracers]]\r\n* [[Volcanic Breastplate]]\r\n* [[Volcanic Leggings]]\r\n* [[Volcanic Shoulders]]\r\n* [[Warbear Harness]]\r\n* [[Warbear Woolies]]\r\n* [[Wicked Leather Armor]]\r\n* [[Wicked Leather Belt]]\r\n* [[Wicked Leather Bracers]]\r\n* [[Wicked Leather Gauntlets]]\r\n* [[Wicked Leather Headband]]\r\n* [[Wicked Leather Pants]]\r\n===[[Tailoring]]===\r\n* [[Felcloth Boots]]\r\n* [[Felcloth Shoulders]]\r\n* [[Runecloth Bag]]\r\n* [[Runecloth Boots]]\r\n* [[Runecloth Gloves]]\r\n* [[Runecloth Shoulders]]\r\n* [[Soul Pouch]]",},
			["Ruin"] = { content = "[[Ruin]] is a [[warlock]] [[talent]] that increases the bonus that [[spell critical strike]]s get. Normally a [[spell critical strike|crit]] gets +50% damage -- with Ruin, the bonus is increased to +100%.\r\n==Burst Damage==\r\nA normal crit does 1.5 times your usual damage. A Ruin crit does 2 times your usual damage.\r\n2 / 1.5 = 1.333...\r\nThis means that Ruin crits do 1.333 times (a gain of 33%) the damage of a normal crits. This is a nice boost for situations where you want more burst damage, such as [[PvP]].\r\n==Long Term Damage==\r\nThis is a formula that calculates how much of a boost (over a large number of spell casts) in damage you can expect to get from this talent when using spells that can crit. The formula uses the \"three outcomes\" model, as well as a concept from probability theory called expected value. This calculation does not take into account resists and partial resists.\r\n====Mathematical Derivation====\r\nThe \"three outcomes\" model states that in WoW, when one casts a spell there are three possible results: a hit, a critical hit (crit), or a miss. If we know the probability of each outcome, we can use probability theory to calculate the expected value of damage. Then, we can calculate the percentage difference in damage we can expect to see from various crit rate/hit rate combinations.\r\n'''&#91;''(chance to crit)'' &times; ''(crit damage)''&#93;''' + '''&#91;''(chance to hit and not crit)'' &times; ''(average damage)''&#93;''' + '''&#91;''(chance to miss)'' &times; 0&#93;'''\r\n====Variables====\r\n* <tt>C</tt> = Chance to get a [[crit]].\r\n* <tt>H</tt> = Chance to hit.\r\n* <tt>A</tt> = Average spell damage (including all damage modifiers).\r\n* <tt>1.5&times;A</tt> = Normal crit damage.\r\n* <tt>2&times;A</tt> = Crit damage due to Ruin.\r\n* <tt>(1-H)</tt> = Chance you will miss (and do 0 damage).\r\n* <tt>(H-C)</tt> = Chance to hit and not crit.\r\n====The Algebra====\r\nWithout [[Ruin]], the expected amount of damage one does with spells is:\r\n<tt>C&times;1.5&times;A + (H-C)&times;A + (1-H)&times;0</tt>\r\nWith [[Ruin]], one expects:\r\n<tt>C&times;2&times;A + (H-C)&times;A + (1-H)&times;0</tt>\r\nThe percentage difference would be:\r\n<tt>( (C&times;2&times;A+(H-C)&times;A) - (C&times;1.5&times;A + (H-C)&times;A) ) / (C&times;1.5&times;A + (H-C)&times;A)</tt>\r\nThis expression simplifies to:\r\n'''<tt>C/(C+2H)</tt>''', where <tt>0 ≤ C ≤ 1</tt>; <tt>0 ≤ H ≤ 1</tt>; and <tt>(H-C) ≥ 0</tt>\r\n====Results====\r\nEssentially, this result states that the increase in long term damage you get from this talent depends on two variables. The first variable is C, your crit rate. The other variable is H, your chance to hit.\r\nThe role that your chance to hit plays may seem counter-intuitive (i.e. lower hit rates leads to higher bonus). This is a consequence of the the \"three outcomes\" model. Crits and hits share the same \"probability space\", and therefore hit rate puts a cap on crit rate. It must be thought of in this way: if you are missing more often, then the critical hit to \"normal\" hit ratio is higher.\r\nLet's say one has a 5% chance to [[crit]].\r\n*'''Scenario 1''': If you have a 1% chance to miss, then you have an 99% chance to hit. Therefore, 5/99 is your chance to critically hit, when you hit.\r\n*'''Scenario 2''': If you had a 95% chance to miss, then you have a 5% to hit you'll have a 5/5 chance to [[crit]] if you don't miss. Keep in mind that you are missing 95% of the time. In this special case, Ruin will give you a nice bonus compared to a character that doesn't have it. Chances are that this character will be dead before he can witness his \"mad [[Ruin]] [[crits]]\".\r\n*'''Scenario 3''': If you have a 99% chance to miss, then you have a 1% chance to hit. You have a 5% chance to crit, but only a 1% chance to hit. It is unclear how the game would react to this situation. It is likely that misses take priority over crits when the percentages overlap. From a practical point of view, it would not matter because you are probably not going to win the encounter. The best course of action would be to use a [[Swiftness Potion]] and run away!\r\nIt would be foolish to pass up +hit gear and use the excuse that it will ruin [[Ruin]]. One has to realize that if you are missing more often, you are doing less damage. Overall, [[Ruin]] is a nice 1 point talent that gives a nice DPS increase to spells that can crit. A 21.333% [[crit]] rate, and a 96% hit chance will match the 10% bonus effect that 5 points in [[Shadow Mastery]] has on shadow spells.\r\n====Examples====\r\nThe Wowwiki article [[Formulas:Spell_hit_chance]] states that against enemies that are the same level as you, you have a 96% base chance to hit.\r\n*5% crit rate, 96% chance to hit\r\n<tt>0.05 / (0.05 + 2*(0.96)) = 0.025641...</tt>, or about +2.6% expected damage\r\n*10% crit rate, 96% chance to hit\r\n<tt>0.10 / (0.10 + 2*(0.96)) = 0.04950...</tt>, or about +5% expected damage\r\n*21.3333% crit rate, 96% chance to hit\r\n<tt>0.213333 / (0.213333 + 2*(0.96)) = 0.1</tt>, +10% damage (about the same as 5 points in [[Shadow Mastery]]).\r\n*20% crit rate, 80% chance to hit\r\n<tt>0.20 / (0.20 + 2*(0.80)) = 0.11...</tt> or 11% boost in damage, but [[DPS]] is lower because you miss more often.\r\n*5% crit rate, 5% chance to hit\r\n<tt>0.05 / (0.05 + 2*(0.05)) = 0.33...</tt> or 33% bonus. Counter-intuitive, but remember that you're missing 95% of the time. You are also critting every time you hit because crits and hits overlap. You will likely never experience this in the game.\r\n==See also==\r\n*[[Ice Shards]]\r\n*[[Spell critical strike]]\r\n*[[Spell hit]]",},
			["Ruined Leather Scraps"] = { content = "==Source==\r\nThese tattered bits of [[leather]] are [[Skinning|skinned]] from low-level [[beast]]s and critters, up to level 11 or so\r\n==Uses for Ruined Leather Scraps==\r\nThree [[Ruined Leather Scraps]] are turned into one [[Light Leather]] by [[Leatherworker]]s.",},
			["Ruined Reaches"] = { content = "'''The Ruined Reaches''' form the southern coast of [[Azshara]] near the border to [[Durotar]]. It is mostly stretches of beach and cliffs broken up by inlets of water and dotted with various ruins and shipwrecks. Like the [[Jagged Reef]] to the north, travel along the reaches can be hazardous, both due to the treacherous shallows lying just below the surface of the ocean, but also due to aggressive [[murloc]]s, [[hydra]]s, and [[makrura]].",},
			["Ruins of Aboraz"] = { content = "The '''Ruins of Aboraz''' is a collection of ancient [[troll]] ruins on the southeastern coast of Stranglethorn Vale, now the home of the witch doctor [[Zanzil the Outcast]]. Zanzil's ghoul, naga, and troll minions wander the ruins, and the captured Darkspear troll [[Yenniku]] is also here as a thrall of Zanzil. The bewitched debtor to [[\"Sea Wolf\" MacKinley]], [[Chucky \"Ten Thumbs\"]], also roams the ruins as a ghoul.\r\nIt is located southeast of [[Ruins of Jubuwal]], east of [[Spirit Den]], and south of [[Crystalvein Mine]].",},
			["Ruins of Ahn'Qiraj"] = { content = "The '''Ruins of Ahn'Qiraj''' is a 20-man outdoor raid dungeon located in southern [[Silithus]]. Its release was joined by massive server-dependent event called the [[Gates of Ahn'Qiraj]]. It can be found by entering the main [[Ahn'Qiraj]] Gate and continuing on the left path.\r\nIt uses a similar loot system to [[Zul'Gurub]], via tokens dropped from bosses which are used to complete quests that give item rewards. Additionally, the quests can only be completed once a certain reputation has been reached with the [[Cenarion Circle]]. The rewards are class-specific: a ring at honoured, a cloak at revered and a weapon at exalted. There is a set bonus for all three.\r\nThe entrance to the [[Temple of Ahn'Qiraj]], which is a 40-man raid instance intended to be the step after [[Blackwing Lair]], is via a separate portal following the right path from the Scarab Wall gate.\r\nMost of the area is mountable, however, the bug mounts from the [[Temple of Ahn'Qiraj]] do not work here.\r\nIf any member of your party is in combat then your entire party is in combat no matter where they are in the instance.\r\n==History==\r\nDeep within the deserts of Silithus lies an ancient and powerful race of beings known as the Qiraji. One thousand years ago, the Night Elves and Bronze Dragonflight combined their considerable powers to seal the Qiraji behind the scarab wall with the help of the children of some of the aspects. This is remembered as the \"War of the Shifting Sands\".\r\nRecently it was discovered that some of the Qiraji were finding ways past the wall. Anachronos, the bronze dragon, helped the adventurers of Azeroth open the Scarab Wall to prevent more incursions. The mortal races have now banded together to confront the evil Qiraji in their own land. A champion has opened the gate and the Horde and Alliance have driven the armies of the Qiraji back into the ruins in retreat. It now falls to heroes to delve into the lair of the Qiraji and put an end to their masters once and for all.\r\n==Quests==\r\n*The Fall of Ossirian ''Starts with the quest item [[Head of Ossirian the Unscarred]]''\r\n*The Perfect Poison ''Given by [[Dirk Thunderwood]] at [[Cenarion Hold]] in [[Silithus]], collect the quest item [[Kurinnaxx's Venom Sac]] from [[Kurinnaxx]] as well as a similar item from [[Zul'Gurub]]''\r\n==Preparation==\r\nMany of the mobs in the Ruins of Ahn'Qiraj use poison or nature-based attacks, so nature resistance gear would be ideal. However, nature resistance in Ahn'Qiraj seems not to be near as crucial as fire resistance to Molten Core. \r\nGuilds who attempt the Ruins of Ahn'Qiraj should not be required to be decked out in epic-quality equipment. A 20-man raid can be managed with mostly blues, and even some greens.\r\nLikewise to nature resistance gear, Greater Nature Protection potions have some potential use in Ahn'Qiraj. However, the formula for these potions is known to sell for more than Greater Fire Protection potions.\r\nSince the progression for the instances of this size is to go from Blackrock Spire to Zul'Gurub to the Ruins of Ahn'Qiraj, the type of gear to have would be ZG-level or above. Those wearing Tier 1 gear and above will find this instance a lot simpler.\r\nInside the Gates of Ahn'Qiraj there are two portals. The one on the left side is the portal to the Ruins of Ahn'Qiraj. The one on the right is the portal to the [[Temple of Ahn'Qiraj]].\r\nHaving at least 1 druid on your raid is not only a good idea, but essential. Entangling Roots, although unreliable, is the only form of Crowd Control that will work in AQ20. A balance Druid will shine in AQ20.\r\n==Dungeon denizens==\r\n* [[Qiraji]]\r\n* [[Silithid]]s\r\n===Trash mobs===\r\n* [[Anubisath Guardian]]\r\n* [[Canal Frenzy]]\r\n* [[Flesh Hunter]]\r\n* [[Hive'Zara Collector]]\r\n* [[Hive'Zara Drone]]\r\n* [[Hive'Zara Sandstalker]]\r\n* [[Hive'Zara Soldier]]\r\n* [[Hive'Zara Stinger]]\r\n* [[Hive'Zara Tail Lasher]]\r\n* [[Hive'Zara Wasp]]\r\n* [[Obsidian Destroyer]]\r\n* [[Qiraji Gladiator]]\r\n* [[Qiraji Swarmguard]]\r\n* [[Shrieker Scarab]]\r\n* [[Spitting Scarab]]\r\n===Bosses===\r\nOne of the nice things about AQ20 is that you don't need to kill all the bosses to finish it. The only ones you need to kill to progress are Kurinnaxx and General Rajaxx, and then you can head straight to Ossirian if you like.\r\n*[[Kurinnaxx]]\r\n*[[General Rajaxx]]\r\n*[[Moam]]\r\n*[[Buru the Gorger]]\r\n*[[Ayamiss the Hunter]]\r\n*[[Ossirian the Unscarred]]\r\n==Loot==\r\nThe loot in AQ20 comes from:\r\n* killing [[boss]]es.\r\n* killing [[mob]]s.\r\n* coffer chests in the instance containing scarabs and idols, requiring coffer keys that drop off of mobs. The keys are not soulbound and as of 1.10 no longer disappear when you leave the zone. If you only receive one (1) key it is recommended you use it on the chest near Ossirian. \r\n* If you're in an aq20 group and your group downs at least the second boss then all the mobs up to him do not respawn after a soft reset, aka 30 minutes. But, the scarab coffers do respawn along with the level 55 non-elite scarabs. Typically you get one idol and 11-15 scarabs.\r\n* After killing [[Ossirian the Unscarred]], his head will drop and that will start the quest the The Fall of Ossirian, which rewards the player with an epic neck piece.\r\n====Loot-quest system====\r\nAQ20 loot-quests require scarabs and idols which drop from trash mobs and Qiraji items which drop from bosses, combined with a certain level of faction with the [[Cenarion Circle]]. \r\nPlayers must collect ten scarab items of two certain types (two lots of five), two stone idols of a certain type, and a single Qiraji item. When a player has the appropriate collection for a particular item and a certain level of reputation with the [[Cenarion Circle]], they can turn them in for the item.",},
			["Ruins of Ahn'Qiraj Quest Loot"] = { content = "#REDIRECT [[Ruins of Ahn'Qiraj quest loot]]", redirect = "Ruins of Ahn'Qiraj quest loot",},
			["Ruins of Alterac"] = { content = "The '''Ruins of Alterac''' City lie in the snowy mountains at the center of the [[Alterac Mountains]]. After the Kingdom of [[Alterac]] was destroyed by the [[Alliance of Lordaeron| Alliance]] for their betrayal during the [[Second War]], most of the population abandoned the ruins of their former homes. Now, [[Crushridge]] [[Ogre]]s have taken up the deserted ruins. Of the former capital city, only the mighty keep remains relatively intact. As of [[patch 2.3]], all of the mobs here expect [[Grel'borg the Miser]] have had their elite tag removed.\r\n==Quests to Get Before Arriving==\r\n* Coolant Heads Prevail - [[Badlands]]\r\n* Preserving Knowledge - [[Southshore]]\r\n* The Perenolde Tiara - [[Stormwind]]\r\n* The Crown of Will - [[Tarren Mill]]\r\n==Herbs==\r\n [[Wintersbite]] (rare)",},
			["Ruins of Andorhal"] = { content = "The '''Ruins of Andorhal''' is a large city ruin in the central [[Western Plaguelands]]. The ruins's leader is [[Araj the Summoner]], a level 61 [[elite]], surrounded by [[Scourge]] agents. The inhabitants is for the most part [[ghoul]]s, [[skeleton]]s, [[banshee]]s, and [[abomination]]s.\r\nFor an article about the city itself, see [[Andorhal]].",},
			["Ruins of Baa'ri"] = { content = "The '''Ruins of Baa'ri''' are located just northeast of [[the Hand of Gul'dan]] in central [[Shadowmoon Valley]]. They are populated by [[Broken]] and [[elekk]]s in service to [[Illidan]]. Something to be noted is that the temple was originally the home of a supposed faction of draenei priests with close ties to the Temple of Karabor, the Priests of Baa'ri. Originally going to become a faction within itself, it would sell recipes, patterns, and actual equipment with a great deal of Holy Resistance. Though even now, only WoW-Europe has even found listing of them. One of their sold trinkets is as well sold by the Aldor priesthood, though it is unknown if this is just a coincidence or a sign that it may be part of Blizzard's infamous April Fools, in addition to the Tinfoil Hat and what might possibly be the Black Temple attunement. No sign has been seen of them yet, so as of now there is no verified proof.",},
			["Ruins of Constellas"] = { content = "The '''Ruins of Constellas''' is an area of [[Felwood]] populated by [[satyr]]. Judging by the architecture, it used to be one of the many [[night elven]] settlements near [[Mount Hyjal]], but was presumably destroyed in the [[Great Sundering]].\r\n==Quests to Get Before Arriving==\r\n* Well of Corruption - from [[Winna Hazzard]] at [[Bloodvenom Post]]",},
			["Ruins of Eldarath"] = { content = "The '''Ruins of Eldarath''' are all that remains an ancient [[Night elf|night elven]] [[city]] located in central [[Azshara]].\r\nBefore the [[Great Sundering]], Eldarath was a flourishing city—a mighty stronghold, even. It is believed that many ancient and powerful Highborne artifacts may be found among its ruins. [[Pandaren]] once gifted a chest to the [[Highborne]], who kept it in Eldarath. 10,000 years later, it was found by [[Li Li Stormstout]]. Some of the most powerful mages of the Highborne created runes and tablets citing rules of the arcane and insights into their findings. They would leave these for all to ponder in public places. Multiple such tablets can be found in the Ruins of Eldarath.\r\nDuring the [[War of the Ancients]], a battle was fought here between the [[Kaldorei Resistance]] and [[Burning Legion]]. [[Tichondrius]] was fought by [[Jarod Shadowsong]] and [[Huln Highmountain]]. The Great Sundering caused most of the city to crumble to the [[Bay of Storms]] below.\r\n==History==\r\nA cluster of ruins clings to the eastern cliffs, long shunned by night elves. Ferocious bands of [[Spitelash|naga]] appear to have claimed Eldarath for their own. The powerful warlord [[Krellian]] controls the remaining ruins from the [[Temple of Zin-Malor]]. The [[Explorer's League]] became interested in Eldarath and [[adventurer]]s of the [[Alliance]] were sent here to discover rubbings of the ancient runes.\r\nThe presence of [[Azuregos]], the blue dragon, seems to suggest that items of extreme significance—perhaps the fabled [[Well of Eternity|Vials of Eternity]] themselves—can be found in the wilderness near these ruins.\r\n==Ruins of Eldarath digsite==\r\nThe Ruins of Eldarath are a night elf [[archaeology]] [[dig site]].",},
			["Ruins of Eldarath"] = { content = "The '''Ruins of Eldarath''' are all that remains an ancient [[Night elf|night elven]] [[city]] located in central [[Azshara]].\r\nBefore the [[Great Sundering]], Eldarath was a flourishing city—a mighty stronghold, even. It is believed that many ancient and powerful Highborne artifacts may be found among its ruins. [[Pandaren]] once gifted a chest to the [[Highborne]], who kept it in Eldarath. 10,000 years later, it was found by [[Li Li Stormstout]]. Some of the most powerful mages of the Highborne created runes and tablets citing rules of the arcane and insights into their findings. They would leave these for all to ponder in public places. Multiple such tablets can be found in the Ruins of Eldarath.\r\nDuring the [[War of the Ancients]], a battle was fought here between the [[Kaldorei Resistance]] and [[Burning Legion]]. [[Tichondrius]] was fought by [[Jarod Shadowsong]] and [[Huln Highmountain]]. The Great Sundering caused most of the city to crumble to the [[Bay of Storms]] below.\r\n==History==\r\nA cluster of ruins clings to the eastern cliffs, long shunned by night elves. Ferocious bands of [[Spitelash|naga]] appear to have claimed Eldarath for their own. The powerful warlord [[Krellian]] controls the remaining ruins from the [[Temple of Zin-Malor]]. The [[Explorer's League]] became interested in Eldarath and [[adventurer]]s of the [[Alliance]] were sent here to discover rubbings of the ancient runes.\r\nThe presence of [[Azuregos]], the blue dragon, seems to suggest that items of extreme significance—perhaps the fabled [[Well of Eternity|Vials of Eternity]] themselves—can be found in the wilderness near these ruins.\r\n==Ruins of Eldarath digsite==\r\nThe Ruins of Eldarath are a night elf [[archaeology]] [[dig site]].",},
			["Ruins of Enkaat"] = { content = "The '''Ruins of Enkaat''' are the remains of a [[draenei]] settlement in western [[Netherstorm]]. It is now haunted by the disembodied ghosts of the dead draenei that used to live there.",},
			["Ruins of Farahlon"] = { content = "The '''Ruins of Farahlon''' were once a [[draenei]] settlement. The ruins are located in northern [[Netherstorm]] just northeast of the [[Stormspire]].\r\nA mighty [[dreadlord]] named [[Culuthas]] killed all of [[Socrethar]]'s Burning Legion demons in the ruins and summoned his own [[void terror]]s called [[Hound of Culuthas|Hounds of Culuthas]] and [[beholder]] minions called [[Eye of Culuthas|Eyes of Culuthas]].\r\nHe holds an Ata'mal crystal, a powerful draenei artifact, which he apparently retrieved off the dead Burning Legion after they excavated it. \r\n[[Void terror]]s may have a connection to [[Floating eye]]s as [[Socrethar]] hints that [[Culuthas]] summoned both many-eyed demons the same way.\r\nFarahlon was also the old name of Netherstorm.",},
			["Ruins of Isildien"] = { content = "A large [[Night Elf]] ruin in the southeast part of Feralas, it now is inhabited by Gordunni [[Ogre]]s.",},
			["Ruins of Jubuwal"] = { content = "Ancient [[troll]] ruins, just east of the [[Gurubashi Arena]], along main road that spans the length of [[Stranglethorn Vale]]. Ghoul, naga, and troll minions of [[Zanzil the Outcast]] currently inhabit the ruins, including [[Jon-Jon the Crow]] and [[Maury \"Club Foot\" Wilkins]], debtors to the ruthless [[\"Sea Wolf\" MacKinley]].",},
			["Ruins of Karabor"] = { content = "'''Ruins of Karabor''' are the southern part of the [[Black Temple]] that lie outside its massive gates. It is filled with [[blood elves]] and [[doomguard]] in service to [[Illidan Stormrage]]. It is here that [[Varedis]], the first blood elf to be trained as a [[demon hunter]] by Illidan himself, oversees the instruction of other blood elves to become demon hunters as well.",},
			["Ruins of Kel'Theril"] = { content = "''Not to be confused with [[Kel'Thuzad]].''\r\n'''The Ruins of Kel'Theril''' are the remnants of the great [[night elven]] city of Kel'Theril. It was destroyed long ago during [[the Sundering]], and it now lies in complete ruin, haunted by the tormented spirits of the [[Highborne]] who did not survive the disaster. The ruins lie on the edges of [[Lake Kel'Theril]] in [[Winterspring]].",},
			["Ruins of Lordaeron"] = { content = "The '''Ruins of Lordaeron''' is all that remains of the [[City of Lordaeron]], the great Capital City of the [[Alliance]]. Now it serves as nothing more than a sad reminder of the power of the [[Scourge]]. The area is literally haunted by the final tragic events that led to the death of [[King Terenas]] and the city's destruction. \r\nTo this day you can still hear the moments before [[King Terenas]]' death; hushed whispers in the courtyard, the clanging of bells in the entryway, the faint cheer echoing the welcome of Prince [[Arthas]], and the murmur of voices in the throne room. One such sentence that is uttered says \" This kingdom shall fall, and in the ashes shall rise a new order that will shake the very foundations of this world.\" - Arthas after slaying his father, and proclaiming the Scourge's invasion and victory over Lordaeron. If you can [[Invisibility|detect invisibility]], you will see the [[Lordaeron Citizen|ghosts]] of the citizens of Lordaeron still haunting the castle's courtyard. Beneath the ruins now lies the [[Forsaken]] capital [[city]] - the [[Undercity]], where the dark queen prepares to reclaim her lost lands to the east.\r\nThe lands outside the ruins are no longer full of cheerful people enjoying the sun, but with demons such as [[Darkhound]]s and [[Duskbat]]s and the Scourge lurking nearby at the borders of the [[Plaguelands]].\r\nThere is also a new section of this zone holding an [[Orb of Translocation]] that connects the Undercity to the [[blood elf]] capital of [[Silvermoon]] for those with the [[Burning Crusade]] expansion.\r\n==The Ruined Palace==\r\n[[Undercity]] is beneath Lordaeron’s ruins, but above the Forsaken city one can visit Lordaeron’s palace. Terenas’ throne room and the royal crypts are still intact. The bloodstain where [[Arthas]] slew his father can still be seen. The magnificent gardens are also accessible, though they have grown wild and play home to lurking beasts. You may also even hear the voices of the Cinematic at the end of the Human Campaign in [[Warcraft III: Reign of Chaos]].\r\n==Arena Details==\r\nAs of Patch 2.1, the Ruins of Lordaeron have become the first [[arena]] to be set outside of Outland, and the only one to be set in a capital city (even though it's technically above the capital - the Undercity - and not accessible outside of speaking to the Arena Battlemaster).\r\nVideo of Ruins of Lordaeron arena: (taken from )\r\nAlthough very similar in appearance to the Ruins of Lordaeron subzone above Undercity, the arena version has some notable differences. For one it is more symmetrical (one end doesn't lead to Tirisfal and the other to the Throne Room). Also, the Lordaeron Citizens are visible without the aid of invisibility detection, and of course in the arena they cannot be attacked. One of the most unusual details is that the arena is located on a map that is set not at [[Tirisfal Glades]], but rather in [[Silverpine Forest]]. Players can only see the effects of this in-game through the mini-map, but an observant player might notice the road placement does not match up with that of the area around Undercity. In fact, the arena appears to have been placed in the same general location as [[Ambermill]]. Using an external map viewer application, one can see the roads to [[Hillsbrad Foothills]] and [[Greymane Wall]], and even [[Shadowfang Keep]]. All of this is only an aesthetic effect however, and should not be interpreted as lore.",},
			["Ruins of Lordaeron Arena"] = { content = "#redirect [[Ruins of Lordaeron]]", redirect = "Ruins of Lordaeron",},
			["Ruins of Loreth'Aran"] = { content = "The '''Ruins of Loreth'Aran''' are ancient remains of a night elven city that was destroyed during the [[Great Sundering]]. They can be found in northeastern [[Bloodmyst Isle]], and are populated by [[Wrathscale]] [[naga]]. \r\nFurther ruins are located further to the northeast on [[Wyrmscar Island]]. The night elves who once inhabited this city were blessed by the [[Green Dragonflight]] and its queen [[Ysera]] and the Dragon Riders of Loreth'Aran rode these powerful dragons into battle and lived alongside them. The city was destroyed when the [[Black Dragonflight]] betrayed their green kin and descended upon the unwary night elves and green dragons. Led by a lieutenant of [[Deathwing]], the fearsome Razormaw, the [[Black Dragonflight]] wiped out Loreth'Aran and its noble defenders in a savage maelstrom of flame and death. \r\nThe city of Loreth'Aran's destruction was made complete by the cataclysm, as the ocean swept in and the earth erupted, leaving only a few remaining ruins scattered across separate islands where once a shining city stood. \r\n[[Wyrmscar Island]] is now home to bones, the restless spirits of slain green whelplings, and the ghost of Prince Toreth, a night elf prince of Loreth'Aran. Prince Toreth beseeches adventurers to retrieve stolen dragon bones, help lay the green whelpling spirits to rest and slay the evil shade of Razormaw, whose hatred is so great he remained even in death.",},
			["Ruins of Mathystra"] = { content = "The '''Ruins of Mathystra''' are located in northern [[Darkshore]], just past the [[Tower of Althalaxx]]. Mathystra used to be a night elven city before the [[Great Sundering]], but it was utterly decimated by the destruction of the [[Well of Eternity]], and has long since been abandoned by the night elves in favor of the smaller coastal villages further south. \r\nThe ancient ruins are now inhabited by the [[Stormscale Naga]], who aggressively guard against any intrusions from outside sources. The ruins contain scattered relics of the old Highborne, and young night elves sometimes attempt to search through Mathystra in search of these relics.\r\nThe WoW manual shows the [[Blackfathom Deeps]] entrance here (it was located here during alpha), and a ruined structure identical to the current entrance with no purpose can be found here. \r\n[[Ghost Saber]] can be found here.",},
			["Ruins of Ordil'Aran"] = { content = "'''The Ruins of Ordil'Aran''' are located in northwestern [[Ashenvale]], north of [[Maestra's Post]] and south of [[Bathran's Haunt]]. Although not much remains of the ancient city that once stood here, the site was a favorite spot for the [[Cult of the Dark Strand]], who inhabited what is left of the ruins, ready to strike at any who approach. They have since been ousted by [[furbolg]]s of the [[Thistlefur]] tribe, who have taken over the ruins for themselves. Dead cultists still lie about the area.\r\nThe Ruins of Ordil'Aran are also the site of the [[Heartswood]] tree.\r\n==Quests==\r\n*[[The Tower of Althalaxx (4)]]\r\n*[[Heartswood (quest)]]\r\n==Ruins of Ordil'Aran (digsite)==\r\nThe Ruins of Ordil'Aran north of [[Maestra's Post]] is a night elf [[archaeology]] [[dig site]].",},
			["Ruins of Ravenwind"] = { content = "The '''Ruins of Ravenwind''' are the remains of ancient [[Kaldorei]] civilization in northern [[Feralas]], specifically the [[Highborne]] (much like [[Dire Maul]]). It is currently overrun with [[Harpy|Harpies]].\r\nA quest from [[Feathermoon Stronghold]] sends [[Alliance]] players to this ruin in search of several magic flames and an altar to recharge the [[Stave of Equinex]].\r\n[[Shay Leafrunner]], a rather absent-minded young [[Night Elf]] girl, can also be found here. She can be escorted back to her guardian friend, [[Rockbiter]], a [[mountain giant]] to the south of the ruins. (Rockbiter is a reference to Never Ending Story. A reference that becomes even more obvious when you read the quest )\r\nA ways north of the ruins, players can run into [[Miblon Snarltooth]], a hungry [[Gnoll]] that zealously guards a small nursery of [[evoroot]]. He has a taste for meat.",},
			["Ruins of Sha'naar"] = { content = "The '''Ruins of Sha'naar''' are the remains of an old [[draenei]] temple, located south of the [[Cenarion Post]] in [[Hellfire Peninsula]]. It is now occupied by [[Illidari]] [[fiend]]s and their unwilling [[Dreghood]] [[Broken]] servants. The cruel fiend [[Arzeth the Merciless]] is stationed here.\r\nThe [[Temple of Telhamat]] was called the [[Temple of Sha'naar]] in an early patch.",},
			["Ruins of Shandaral"] = { content = "'''Ruins of Shandaral''' is in the center of the [[Unbound Thicket]], between [[Sunreaver's Command]] and [[Windrunner's Overlook]] in eastern [[Crystalsong Forest]].",},
			["Ruins of Silvermoon"] = { content = "The area known as the '''Ruins of Silvermoon''' makes up the western half of the city of [[Silvermoon]], the capital of the Kingdom of [[Quel'Thalas]]. It is split from the reconstructed Silvermoon (the eastern half) by the Dead Scar, the path taken by [[Arthas Menethil]] and the undead [[Scourge]] on their way to the [[Sunwell]], to resurrect the dead necromancer [[Kel'Thuzad]]. As they marched across Quel'Thalas at the bidding of the [[Dreadlord]] [[Tichondrius]], Arthas and his warriors corrupted everything in their path. The Scourge smashed through the Elfgates defending Silvermoon from attackers, and destroyed the Rangers of Silvermoon, led by [[Sylvanas Windrunner]], before finally reaching the [[Sunwell Plateau]] and placing Kel'Thuzad's rotted corpse into the holy waters of the Sunwell. Kel'Thuzad was resurrected as a powerful lich, and the waters of Eternity forever corrupted.\r\nThis area holds a small town, [[Falconwing Square]], which serves as an intermediary point for new Blood Elf players between [[Sunstrider Isle]] and [[Silvermoon City]], much like [[Brill]], [[Dolanaar]], [[Goldshire]], [[Razor Hill]], [[Kharanos]], [[Bloodhoof Village]], and [[Azure Watch]]. It has an inn, a mailbox, profession and class trainers, and quests within the ruins of the west half of Silvermoon. For example, a level 5 player can pick up the cooking profession and a recipe they will need to raise that profession for the next 15 levels here in the inn, in the Ruins of Silvermoon. However there are not many quests here, and is probably only good for a level or two, before you move on to the quests immediately south of the Ruins of Silvermoon or to [[Fairbreeze]].",},
			["Ruins of Solarsal"] = { content = "[[Night Elf]] ruins south of [[Feathermoon Stronghold]]. [[Naga]] inhabit the grounds.",},
			["Ruins of Stardust"] = { content = "The '''Ruins of Stardust''' are located in southwestern [[Ashenvale]], south of [[Astranaar]] and west of [[the Talondeep Path]]. The ruins are situated on a lake island, and several large [[bog beast]]s roam the ruins, corrupted by the lake's tainted waters. Much like [[Iris Lake]], the ruins have been exposed to the demonic rot from [[Felwood]], and the area is tinted a sickly yellowish green color. The most notable exception is the stardust shrubs scattered about the area. They are unmarred by the taint, and are known to contain powerful healing properties if imbibed.",},
			["Ruins of Thaurissan"] = { content = "The '''Ruins of Thaurissan''' are what remains of the [[Dark Iron dwarves]]' original city of Thaurissan (aka city of Thaurisan). Little is known of the great city, and [[Royal Historian Archesonus]] has led research into the ruins found in the [[Burning Steppes]], to reveal some information about the place.\r\nHundreds of years ago, the city, named after [[Emperor Dagran Thaurissan]], stood proudly in a lush expanse of land that is now the dilapidated Burning Steppes.\r\nThaurissan was home to the nation of Dark iron dwarves and at the time, in the midst of a [[War of the Three Hammers|civil war]] among the dwarven nation at large.\r\nThat area of the world was at one point in time part of the [[Redridge Mountains]] - until the day that Thaurissan was consumed by a gigantic explosion, as Thaurissan attempted to summon the ancient Firelord [[Ragnaros]]. The city lay in ruin, the surrounding areas reduced to an ashy wasteland.\r\nThe Dark Irons that survived made their way into the mountain and began rebuilding their city.\r\nFrom the ashes of Thaurissan then rose [[Blackrock Spire]] and the new Dark iron nation. Additional fortifications were made within the [[Searing Gorge]], in the area known as the [[Cauldron]].\r\nAn expedition was commissioned, to find mysterious relics rumored to still lie within the ruins of the city. While none of the relics were able to be brought back in one piece, the information revealed was still priceless. Apparently, merely touching the relics caused memories of the destruction of Thaurissan to overwhelm the explorers, flooding his sight with visions of the terrible ruin wrought upon the city.\r\n'''Notes taken by the explorers are recorded here:'''\r\n* \"...threatened, 'Defiler... you will be punished for this incursion.' A symbol of flame radiated from the relic before it crumbled to the earth.\"\r\n* \"I could hear tormented voices pleading... 'Help us, outsider.' even as the relic crumbled to dust in my hands... I saw eight Dark Iron dwarves performing some sort of ritual...\"\r\n* \"...me to 'Leave this place.' A white hot arc of flame sprung from the relic, and I saw a lone Dark Iron dwarf, surrounded by seven corpses, kneeling before a monolith of flame.\"\r\n* \"...only make out 'Do not taint these ruins, mortal,' before I was engulfed in a blinding flash of light. A creature composes entirely of flame is the only thing I can remember seeing.\"\r\n* \"I heard the words 'You will perish here' as my mind was filled with visions of chaos and destruction.\"\r\n* \"...'He cannot be defeated,' that much I am sure of. The relic burned away to nothing in my hands. Whatever destroyed this city was a being not of this world.\" \r\nsome taken from",},
			["Ruins of the Scarlet Enclave"] = { content = "The '''Ruins of the Scarlet Enclave''' is the combined region around the towns of [[New Avalon]] and [[Havenshire]], which were destroyed by the Scourge (with the aid of [[death knight]] player characters). The Enclave is accessable by going through [[Tyr's Hand]] or the cave between the [[Noxious Glade]] and [[Death's Breach]].\r\nThroughout the ruins, the banner of the [[Knights of the Ebon Blade]] (rather than that of the Scourge) can be seen in certain areas, such as the courtyard of New Avalon and outside the ruined [[Scarlet Hold]].\r\n==Notes==\r\nThis area contains no [[NPC]]s, [[mob]]s, [[herb]]s, or ore [[vein]]s.",},
			["Ruins of Zul'Kunda"] = { content = "The '''Ruins of Zul'Kunda''' are very large [[troll]] ruins in the northern part of Stranglethorn Vale. This is the territory of the [[Bloodscalp]] trolls, and their leaders, [[Nezzliok the Dire]] and [[Gan'zulah]], are stationed here.",},
			["Ruins of Zul'Mamwe"] = { content = "The '''Ruins of Zul'Mamwe''' is an ancient [[Gurubashi]] ruin located south of the Mosh'Ogg Ogre Mound. It is surrounded by mountains on all sides exept north. The second major troll tribes of [[Stranglethorn Vale]], the [[Skullsplitter]]s, inhabit Zul’Mamwe. These [[trolls]] are mostly solitary, and are led by their vicious chieftain, Ana’thek the Cruel. The name of this place is probably associated with Zimbabwe, a country in Africa.",},
			["Ruka"] = { content = "'''Ruka''' is a level 60 blunt [[weapon]] [[vendor]] located at [[Mok'Nathal Village]] in the [[contested]] territory of [[Blade's Edge Mountains]].\r\nSee [[List of Blade's Edge Mountains NPCs]].",},
			["Rukhmar"] = { content = "Rukhmar is the traditional god of the [[Arakkoa]], the veneration of which was abandoned some time ago in favor of the worship of the mysterious master of the [[Sethekk]] cult. Rukhmar is associated with the great Arakkoa hero [[Terokk]].",},
			["Rulkan"] = { content = "'''Rulkan''' was the mate of [[Ner'zhul]] before she died an unknown death. [[Kil'jaeden]], using information gained through his scout [[Talgath]], impersonated her spirit. She was the one who told him about the false [[draenei]] threat, and of Kil'jaeden. Sometime later Ner'zhul encountered the real Rulkan (who, as with the spirits of most orcs was living an afterlife in [[Oshu'gun]]), but she looked upon him in hatred and would not have anything to do with him.",},
			["Rumored Expansions"] = { content = "#REDIRECT [[expansion ideas]]", redirect = "expansion ideas",},
			["Rumsey Rum (brand)"] = { content = "'''Rumsey Rum''' is a brand of several alcoholic beverages. Varieties include Rumsey Rum, Rumsey Rum Light, Rumsey Rum Dark, and Rumsey Rum Black Label.\r\nIn addition to getting you drunk, Rumsey Rums provide a \"well fed\" stamina bonus. The Stamina bonus will replace any \"well fed\" aura.\r\n==Source==\r\nRumsey Rum is a quest reward from Whiskey Slim's Lost Grog.\r\nRumsey Rum Light, Rumsey Rum Dark, and Rumsey Rum Black Label can be [[Fishing|fished]] from [[Floating Wreckage]]. \r\nRumsey Rum Black Label can also be purchased at the inn in [[Southshore]], in [[Old Hillsbrad Foothills]]. (Note that this is not Alliance only.)",},
			["Rumstag Proudstrider"] = { content = "'''Rumstag Proudstrider''' is a level 35 [[quest giver]] located in the building with the armor merchants on the middle rise in Thunder Bluff on the [[Middle Rise]] in the [[tauren]] city of [[Thunder Bluff]]\r\nHe starts the following quests:\r\n* A Donation of Wool\r\n* A Donation of Silk\r\n* A Donation of Mageweave\r\n* A Donation of Runecloth\r\n* Additional Runecloth (Repeatable)\r\nSee [[List of Thunder Bluff NPCs]].",},
			["Rune"] = { content = "#redirect [[Runes]]", redirect = "Runes",},
			["Runeblade"] = { content = "'''Runeblades''' are usually swords inscribed with magical or demonic runes that grant certain powers to the wielder. All high-ranking [[death knights]] wield their own personal, named runeblade, called [[vampiric runeblade]]s. However, runeblades are not unique to the [[Scourge]]. Although [[Frostmourne]] is undoubtedly the most prominent runeblade in existence (Kael'thas' [[Flamestrike (sword)|Flamestrike]] being the second), there are quite a few additional ones.\r\n==Famous Runeblades==\r\n*[[Vampiric runeblade]]s\r\n*[[Runeblade of Baron Rivendare]] \r\n*[[Iblis, Blade of the Fallen Seraph]]\r\n*[[Gressil, Dawn of Ruin]]\r\n*[[The Hungering Cold]]\r\n*[[Frostmourne]]\r\n*[[Orkenblade]]",},
			["Runeblade of Baron Rivendare"] = { content = "The '''Runeblade of Baron Rivendare''' is a two-handed sword with a passive boost to the wielder's movement speed and life regeneration rate. It is a well suited weapon for mainly [[Warriors]] and [[Paladins]].\r\n==Background==\r\nBaron Rivendare’s Runeblade is a powerful bastard sword. It is Baron Rivendare's most prized possession, next to his undead steed, [[Deathcharger's Reins|Deathcharger]]. The finely-crafted blade bears a false hilt and is etched with necromantic runes all down the blade. The blade pulses with cold power, seeming all too ready to draw blood from enemies. In anyone else's hands, the blade is a simply a bastard sword. In the Baron's hands, however, the weapon becomes a keen frost/unholy bastard sword. The powerful blade also grants anyone who wields the blade fast healing. The sword also allows any wielder to cast Bloodlust on themselves.\r\n==Source==\r\nThe Runeblade drops from [[Baron Rivendare]] in [[Stratholme]] at an approximate 0.10% rate.\r\n==Notes==\r\n*The health regeneration is 20hp per 5 secs, and the movement speed bonus is +8%. Other movement speed increasing effects do not stack.\r\n*This is a reference to the Unholy Aura skill of the Death Knight in Warcraft III.",},
			["Runecloth"] = { content = "'''Runecloth''' is a [[cloth]] [[item]] [[drop]] from [[humanoid]]s in the 51-60 level range, marking it as the second most powerful of the normal cloths. Rarer than Mageweave Cloth, but not as rare as Felcloth.\r\nWith the introduction of Burning Crusade, this item was exceeded as the most powerful normal cloth by Netherweave Cloth.\r\n==Source==\r\nRunecloth is a staple of any server's economy. Typically, it isn't necessary to grind specifically for runecloth; since so many other mobs drop it, simply as a part of normal adventuring and other grinds you will accumulate quite a lot of it. \r\nAs a rule of thumb, if you are grinding runecloth for any reason other than home city faction (such as for tailoring), then grind all other materials first. Just grinding felcloth, for example, will produce large amounts of runecloth. Then continue with whatever reputation grind (with [[Argent Dawn]], [[Cenarion Circle]] or [[Timbermaw Hold]] for example) you are already on until sufficient runecloth appears. \r\nThis holds true for city faction grinds as well; however, in these cases it might be necessary to look for mobs that have particularly good drop rates. These are the mobs that gold farmers target. Blizzard has periodically adjusted drop rates. The demons of Azshara, for example, were once excellent sources of nearly everything. Now their loot tables are typical for mobs of their type and level. At the moment, the ogres of the Vice, in [[Deadwind Pass]], are a good source of runecloth. However, even on PVE servers, the normal grinding rule holds: too much competition will slow you down far more than a marginally better drop rate. So be sure to farm in relatively uninhabited areas before being picky about drop rates. \r\n==Runecloth as an ingredient==\r\nRunecloth is used in the following recipes:\r\n===[[Blacksmithing]]===\r\n* Dense Weightstone\r\n===[[Engineering]]===\r\n* Arcane Bomb\r\n* Dark Iron Bomb\r\n* Dense Dynamite\r\n* Major Recombobulator\r\n* Masterwork Target Dummy\r\n* Snake Burst Firework\r\n* Spellpower Goggles Xtreme Plus\r\n* Thorium Grenade\r\n* Thorium Widget\r\n===[[Leatherworking]]===\r\n* Runic Leather Armor\r\n* Runic Leather Belt\r\n* Runic Leather Bracers\r\n* Runic Leather Gauntlets\r\n* Runic Leather Headband\r\n* Runic Leather Pants\r\n* Runic Leather Shoulders\r\n===[[Tailoring]]===\r\n* Bolt of Runecloth\r\n===[[First Aid]]===\r\n* Runecloth Bandage\r\n* Heavy Runecloth Bandage\r\n==Runecloth as a quest objective==\r\nRunecloth is needed for the following quests:\r\n* Additional Runecloth\r\n* A Donation of Runecloth\r\n* Collection of Goods\r\n* Dalson's Tears Cauldron\r\n* Felstone Field Cauldron\r\n* Gahrron's Withering Cauldron\r\n* Making Amends\r\n* Runecloth\r\n* Writhing Haunt Cauldron\r\n==Places to farm==\r\nNumber one farming place seems to be in [[Silithus]].\r\n[[Twilight Avenger]]s, located mainly north-west and south-west in [[Silithus]], have a drop rate of 34% (According to www.wowhead.com, based on over 155,000 kills)\r\nThose who have The Burning Crusade expansion can farm in The Outlands at the [[Hellfire Peninsula]].\r\nBleeding Hollow Peons (59), located in the south-east section of Hellfire Peninsula, have an average drop rate of 33% (According to www.wowhead.com, based on over 125,000 kills).\r\n(There are reported drop rates of 37% or higher on wowhead, however those figures are based on very, very low kill counts mostly only within the hundreds and thus might not be as accurate. Please see wowhead.com link at bottom of page).\r\nPre-TBC farming locations:\r\n*'''Lvl. 50+:''' [[Felwood]], [[Timbermaw]] furbolgs drop runecloth, but this is not recommened, because the Timbermaw furbolgs populate the passageway from Felwood to Winterspring\r\n*'''Lvl. 50+:''' [[Felwood]], just west and north west of [[Jadefire Run]] located in the North part of [[Felwood]] ([[Felcloth]] Drops here also)\r\n*'''Lvl. 51+:''' [[Western Plaguelands]], all the [[undead]]. Places to look are:\r\n**[[Felstone Field]] (51+)\r\n**[[Sorrow Hill]], more suitable for [[Alliance]] players due to the proximity with [[Chillwind Camp]] (51+)\r\n**[[Dalson's Tears]] (53+)\r\n**[[The Writhing Haunt]] (55+)\r\n**[[Ruins of Andorhal]], from the [[ghoul]]s and the [[lich]] (55+)\r\n**[[Gahrron's Withering]] (57+)\r\n**[[Hearthglen]] (humans)(55-57 non-elite, 55-58 elite)\r\n**[[Scholomance]] (instance) (58 elite)\r\n*'''Lvl. 51+:''' [[Azshara]]\r\n**[[Thalassian Base Camp]] (51+)\r\n*'''Lvl. 55+:''' [[Eastern Plaguelands]], any undead mobs. Places to look are:\r\n**[[Corin's Crossing]] (56+)\r\n**[[The Undercroft]] (55+)\r\n**[[The Noxious Glade]] (58+)\r\n**[[Northdale]] (58+)\r\n**[[Tyr's Hand]] (humans) (53-57 elite)\r\n**[[Plaguewood]] (57+)\r\n**[[Stratholme]] (instance)(58 elite)\r\n*'''Lvl. 55+:''' [[Silithus]]: Twilight Cultists of all sorts.\r\n*'''Lvl. 59+:''' [[Dire Maul]] North (instance)\r\n*'''Lvl. 56+:''' [[Blackrock Depths]] (instance)\r\n*'''Lvl. 57+:''' Lower [[Blackrock Spire]] (instance)\r\n*'''Lvl. 58+:''' Upper [[Blackrock Spire]] (instance)\r\n==Notes==\r\nRaw '''Runecloth''', as it's dropped from monsters, can be used in a variety of tradeskill recipes. Most notably it creates [[Runecloth Bandage]] and [[Heavy Runecloth Bandage]] with [[First Aid]]. It's also needed for the runic leather line of [[Leatherworking]], and five pieces of Runecloth can be combined to form one [[Bolt of Runecloth]] with [[Tailoring]].\r\nThe bolts are used for most of the high-end Tailoring recipes, sometimes mixed with [[Felcloth]] or [[Mooncloth]].\r\nYou can also deliver Runecloth in stacks of 20 per delivery to the cloth quartermasters in each of the major faction cities, to gain [[Reputation]], after having completed their initial 3 quests.",},
			["Runecloth Bag"] = { content = "'''Runecloth Bag''' is a 14 slot [[bag]] made from [[Runecloth]].\r\n==Source==\r\nThis item is crafted by [[Tailoring|Tailors]] with a skill level of 260.\r\nThe components are:\r\n*5 [[Bolt of Runecloth|Bolts of Runecloth]]\r\n*2 [[Rugged Leather]]\r\n*1 [[Rune Thread]]\r\nThe [[pattern]] is a limited supply vendor item sold by [[Qia]] in [[Everlook]], in [[Winterspring]].",},
			["Runecloth Bandage"] = { content = "'''Runecloth Bandage''' is a bandage created with runecloth for high level players.\r\n==Source==\r\nThis bandage is made by players with a [[First Aid]] skill of at least 260.\r\nThe components are:\r\n*1 [[Runecloth]]\r\nIf you have a [[First Aid]] skill above 260, the following NPCs will teach you how to make it for free:\r\n* [[Doctor Gustaf VanHowzen]] in [[Theramore Isle]]\r\n* [[Doctor Gregory Victor]] in [[Hammerfall]]\r\n==Runecloth Bandage as a quest objective==\r\nDuring the [[Gates of Ahn'Qiraj]] one-time event, the following quests were available:\r\n* The Alliance Needs Runecloth Bandages!\r\n* The Alliance Needs More Runecloth Bandages!\r\n* The Horde Needs Runecloth Bandages!\r\n* The Horde Needs More Runecloth Bandages!",},
			["Runecloth Belt"] = { content = "==Source==\r\nThis item is crafted by [[Tailoring|Tailors]] with a skill level of 255.\r\nThe [[pattern]] is taught by the tailoring [[trainer]].",},
			["Runecloth Boots"] = { content = "'''Runecloth Boots''' are a [[Tailoring]]-made pair of cloth boots that provide bonuses needed by any cloth caster.\r\n==Source==\r\n'''Runecloth Boots''' are crafted by [[Tailoring|tailors]] with a skill level of 280.\r\nMaterials required\r\n* 4x Bolt of Runecloth\r\n* 4x Rugged Leather\r\n* 2x Ironweb Spider Silk\r\n* 1x Rune Thread\r\nThe recipe for this item is taught by tailoring trainers. Formerly, it was exclusively taught by Pattern: Runecloth Boots, an item sold by a vendor in [[Moonglade]].",},
			["Runecloth Cloak"] = { content = "'''Runecloth Cloak''' is a [[Tailoring]]-made cloak that provide bonuses needed by any cloth caster.\r\n==Source==\r\n'''Runecloth Cloak''' is crafted by [[Tailoring|tailors]] with a skill level of 265.\r\nThe [[pattern]] is sold by [[Darnall]] in [[Moonglade]] for 1 gold 20 silver in limited quantity.",},
			["Runecloth Gloves"] = { content = "'''Runecloth Gloves''' are cloth gloves made by tailors.\r\n==Source==\r\nRunecloth Gloves is crafted by [[Tailoring|Tailors]] with a skill level of 275. \r\nThe components are:\r\n* 4 [[Bolt of Runecloth]]\r\n* 1 [[Rune Thread]]\r\n* 4 [[Rugged Leather]]\r\nThe recipe for this item is taught by tailoring trainers. Formerly, this recipe was taught by the item Pattern: Runecloth Gloves, sold by vendors.",},
			["Runecloth Headband"] = { content = "'''Runecloth Headband''' are a [[Tailoring]]-made cloth headband that provide bonuses needed by any cloth caster.\r\n=Source=\r\n'''Runecloth Headband''' is crafted by [[Tailoring|tailors]] with a skill level of 295.\r\nMaterials required\r\n* 4x Bolt of Runecloth\r\n* 2x Ironweb Spider Silk\r\n* 1x Rune Thread\r\nThe recipe for this item is offered by tailoring trainers.\r\nFormerly, the recipe for this item was taught exclusively by Pattern: Runecloth Headband, a [[World Drop]] [[pattern]].",},
			["Runecloth Pants"] = { content = "==Source==\r\nThis item can be crafted using [[Tailoring]] (285) \r\nThe recipe for this item is now taught by tailoring trainers. Formerly, it was exclusively taught by Pattern: Runecloth Pants, a very hard to acquire world drop.",},
			["Runecloth Robe"] = { content = "==Source==\r\nThis item can be crafted using [[Tailoring]] (260); taught by Pattern: Runecloth Robe. \r\nMaterials Required:\r\n* 5x Bolt of Runecloth\r\n* 1x Ironweb Spider Silk\r\n* 1x Rune Thread\r\n==as a quest item==\r\n* [[Craftsman's Writ|Craftsman's Writ - Runecloth Robe]] requires 8 of these",},
			["Runecloth Shoulders"] = { content = "'''Runecloth Shoulders''' is a [[Tailoring]]-made cloth shoulder armor that provide bonuses needed by any cloth caster.\r\n==Source==\r\nRunecloth Shoulders are crafted by [[Tailoring|tailors]] with a skill level of 300.\r\nThe recipe for this item is now offered by tailoring trainers. Formerly, the recipe for this item was exclusively taught by Pattern: Runecloth Shoulders, a [[world drop]] [[pattern]].",},
			["Runecloth Tunic"] = { content = "'''Runecloth Tunic''' is a [[Tailoring]]-made cloth tunic that provide bonuses needed by any cloth caster.\r\n==Source==\r\n'''Runecloth Tunic''' is crafted by [[Tailoring|tailors]] with a skill level of 260.\r\nThe [[pattern]] is a world drop.",},
			["Runed Arcanite Rod"] = { content = "The '''Runed Arcanite Rod''' is a tool used by [[Enchanting|Enchanters]] to help enchant items with new abilities. The rod is created by the enchanter and only he or she can use it. The rod is not consumed when used in enchanting.\r\n==Source==\r\nThe '''Runed Arcanite Rod''' is crafted by [[Enchanting|Enchanters]] with a skill level of 290.\r\nThe Formula: Runed Arcanite Rod is a [[Limited Sale Recipe]] sold by Lorelae Wintersong in [[Moonglade]].\r\n==Reagents==\r\nRuned Truesilver Rod x 1\r\nArcanite Rod x 1\r\nGolden Pearl x 1\r\nIllusion Dust x 10\r\nGreater Eternal Essence x 4\r\nLarge Brilliant Shard x 2\r\nThe Runed Truesilver Rod is now consumed by the enchant (as of patch 2.0.1).\r\n==Runed Arcanite Rod as a Tool==\r\n*[[Enchant Bracer - Mana Regeneration]]\r\n*[[Enchant Weapon - Agility]]\r\n*[[Enchant Weapon - Strength]]\r\n*[[Enchant 2H Weapon - Agility]]\r\n*[[Enchant 2H Weapon - Superior Impact]]\r\n*[[Brilliant Mana Oil]]\r\n*[[Brilliant Wizard Oil]]\r\n*[[Enchant Bracer - Healing Power]]\r\n*[[Enchant Chest - Greater Stats]]\r\n*[[Enchant Cloak - Dodge]]\r\n*[[Enchant Cloak - Greater Fire Resistance]]\r\n*[[Enchant Cloak - Greater Nature Resistance]]\r\n*[[Enchant Cloak - Stealth]]\r\n*[[Enchant Cloak - Subtlety]]\r\n*[[Enchant Gloves - Fire Power]]\r\n*[[Enchant Gloves - Frost Power]]\r\n*[[Enchant Gloves - Healing Power]]\r\n*[[Enchant Gloves - Shadow Power]]\r\n*[[Enchant Gloves - Superior Agility]]\r\n*[[Enchant Gloves - Threat]]\r\n*[[Enchant Weapon - Crusader]]\r\n*[[Enchant Weapon - Lifestealing]]\r\n*[[Enchant Weapon - Healing Power]]\r\n*[[Enchant Weapon - Mighty Intellect]]\r\n*[[Enchant Weapon - Mighty Spirit]]\r\n*[[Enchant Weapon - Spell Power]]\r\n*[[Enchant Weapon - Superior Striking]]\r\n*[[Enchant Weapon - Unholy Weapon]]\r\n*[[Enchant 2H Weapon - Major Intellect]]\r\n*[[Enchant 2H Weapon - Major Spirit]]",},
			["Runed Copper Rod"] = { content = "The '''Runed Copper Rod''' is a tool used by [[Enchanting|Enchanters]] to help enchant items with new abilities. The rod is created by the enchanter and only he or she can use it. The rod is not consumed when used in enchanting. This rod is used for low level enchanting.\r\n==Source==\r\nThis item is crafted by [[Enchanting|Enchanters]] with a skill level of 20.\r\n==Reagents==\r\n*Copper Rod x 1\r\n*Strange Dust x 1\r\n*Lesser Magic Essence x 1\r\nThe [[formula]] is learned from the trainer.\r\n==Trainers==\r\n* [[Malcomb Wynn]] - [[The Apothecarium]], [[The Undercity]]\r\n* [[Vance Undergloom]] - [[Brill]], [[Tirisfal Glades]]\r\n===Runed Copper Rod as a Tool===\r\n*Enchant Bracer - Minor Health (1)\r\n*Enchant Chest - Minor Health (1)\r\n*Lesser Magic Wand (15)\r\n*Enchant Bracer - Minor Deflect (20)\r\n*Enchant Chest - Minor Mana (20)\r\n*Enchant Chest - Minor Absorption (40)\r\n*Enchant Cloak - Minor Resistance (45)\r\n*Minor Wizard Oil (45)\r\n*Enchant Bracer - Minor Stamina (50)\r\n*Enchant Bracer - Minor Spirit (60)\r\n*Enchant Chest - Lesser Health (60)\r\n*Enchant Cloak - Minor Protection (70)\r\n*Greater Magic Wand (70)\r\n*Enchant Bracer - Minor Agility (80)\r\n*Enchant Bracer - Minor Strength (80)\r\n*Enchant Chest - Lesser Mana (80)\r\n*Enchant Weapon - Minor Beastslayer (90)\r\n*Enchant Weapon - Minor Striking (90)\r\n*Enchant 2H Weapon - Lesser Intellect (100)\r\n*Enchant 2H Weapon - Minor Impact (100)\r\n*Enchant 2H Weapon - Lesser Spirit (110)\r\n*Enchant Cloak - Lesser Protection (115)\r\n*Enchant Shield - Minor Stamina (115)",},
			["Runed Giant"] = { content = "'''Runed Giants''' are strange,magical giants who wander the northeastern areas of [[Grizzly Hills]]. Their origins are unknown, but could have something to do with the [[Shade of Arugal|shade of Archamge Arugal]] who dwells at [[Bloodmoon Isle]] off the northeast coast.",},
			["Runed Living Ruby"] = { content = "'''Runed Living Ruby''' is a crafted [[gem]] that matches a Red [[Socket]].\r\n==Source==\r\n'''Runed Living Ruby''' is crafted by [[Jewelcrafter]]s with a skill of 350 or greater, and requires a [[Simple Grinder]].\r\nComponents:\r\n*1 [[Living Ruby]]\r\nThe [[Design: Runed Living Ruby|Design]] for this item is a world drop.",},
			["Runed Stygian Belt"] = { content = "'''Runed Stygian Belt''' is [[Tailoring|Tailor]] created cloth belt that provides a bonus to [[stamina]] and shadow resistance.\r\n==Source==\r\n'''Runed Stygian Belt''' is crafted by [[Tailoring|tailors]] with a skill level of 300.\r\nThe [[pattern]] is an random quest reward for completing a repeatable quest for [[Hermit Ortell]].",},
			["Runed Stygian Boots"] = { content = "'''Runed Stygian Boots''' are [[Tailoring|Tailor]] created cloth boots that provide a bonus to [[stamina]] and shadow resistance.\r\n=Source=\r\n'''Runed Stygian Boots''' are crafted by [[Tailoring|tailors]] with a skill level of 300.\r\nThe [[pattern]] is an random quest reward for completing a repeatable quest for [[Hermit Ortell]].\r\n=Notes=",},
			["Runed Stygian Leggings"] = { content = "'''Runed Stygian Leggings''' are cloth armor that offers a large amount of [[Shadow Resistance]].\r\n==Source==\r\nRuned Stygian Leggings are crafted by [[Tailoring|Tailors]] with a skill level of 300.\r\nThe [[pattern]] is received in the mail by turning in Encrypted Twilight Text to [[Hermit Ortell]] in [[Silithus]]. There is a small chance he will mail this pattern to you.",},
			["Runeforge"] = { content = "A '''runeforge''' is a special type of forge used by [[death knight]]s to emblazon their weapon with [[runes]]. A runeforge is required to modify any runes already in your weapon (done via [[runeforging]]). [[Acherus: The Ebon Hold]] — the death knight starting area — is the only location with runeforges, which are set around the room inside the necropolis.",},
			["Runeforging"] = { content = "'''Runeforging''' is a skill specific to [[death knight]]s, involving the affixing of runes to the death knight's weapon. It requires a [[runeforge]], these can be found in [[Acherus: The Ebon Hold]] and [[Shadow Vault (Icecrown)|Shadow Vault]].\r\n==Limitations == \r\nRuneforge enchants will count as a permanent enchant, and thus overwrite any regular [[Enchanting|enchants]] such as mongoose or executioner.\r\n==Runes==\r\nThere are eight different [[Rune system|runes]] that can be affixed to your weapon. Four are for both one- and two-handers, two are for one-handers only, and two are for two-handers only. Only one rune may be affixed to a weapon at a time, and they can only be changed at the runeforge in Acherus or Shadow Vault in Icecrown.",},
			["Runemaster"] = { content = "'''Runemasters''' are [[monk]]-like arcane spellcaster & melee fighters who empower themselves with magical energies by inscribing runes onto their bodies. The runemaster is a free spirit, more at home in the wild than in the city. The runemaster is a mystic who sees the power of ley lines. Moreover, those who study runes understand that these are not simply symbols of power - they are the power. The runemaster seeks to become one with the land, but not in the fashion of druids. Rather, the runemaster desires to become a microcosm of the land, seeking to overlay his body with runes in the same fashion that the land itself is overlaid with patterns of ley lines.\r\nHe merges brute strength with arcane magic, covering his body with mystic tattoos and often imbuing them with magical energies to increase his skill in hand-to-hand combat. While a runemaster shuns armor, this is more to prevent hindrances to inscribing his runes than to demonstrate his subtlety and finesse with unarmed strikes. Quite to the contrary, a runemaster prefers to get in the face of his enemies. Using little trickery or subterfuge, the runemaster takes down foes with toe-to-toe, all-out assaults, hammering them with tattooed fists and feet brimming with arcane power. Runic magic is considered primitive yet complex by most other races. The dwarves have taken to it with deft skill, while the tauren study it more slowly.\r\nMost runemasters are heavily tattooed with runic patterns - not simply the unique ones that form the basis for rune families, but the so-called \"simple runes\" as well. Simple runes mimic patterns of ley energy that appear, again and again, in the environment. These patterns occur in nature and are responsible for things such as the strength of a given type of stone, the ferocity of a given windstorm and the coolness of a given stream; when a runemaster uses these patterns, he learns to channel his power into them at all times, attaining similar traits.\r\nRunemasters are proficient with simple weapons, but not with any type of armor or shield. Armor of any type interferes with a runemaster’s movements, which can cause his empowerments with somatic components to fail.\r\nA runemaster has the ability to scribe and empower [[runes]]. A runemaster does not prepare spells the way other arcane spellcasters do. Rather, a runemaster has a certain number of rune patterns that he simply knows, and he may empower any rune within those patterns. To scribe and empower a rune, the runemaster must have a high Spirit.\r\nA runemaster can create any rune he knows at any time. He does not have to decide ahead of time which runes he will create, nor does he need to prepare anything in advance. To inscribe a rune, a runemaster must have an high intelligance. The runemaster can sense the presence of runes in his vicinity, a runemaster gains an intuitive sense that alerts him to danger from runes. A runemaster's marks can be made permanent.A creature can have only few magic tattoos. To replace a magic tattoo, the creature must first have an old one erased. The runemaster bears simple runes (see below) on his knuckles.\r\nThe runes that make up the runic patterns are powerful and unique, based upon patterns of [[ley line|ley-line]] energy found nowhere else in all of [[Azeroth]]. These are not the only such patterns in nature, however. There are patterns that are not unique, but are found over and over in certain dynamic situations in nature. These repeating patterns are the basis for simple runes: sets of runes that only runemasters may use.\r\nSimple runes are tattooed to the skin of the runemaster. It isn’t enough that the pattern be there — rather, the runemaster must understand how his own energy is like that of the ley line energy of the world around him, so that he can empower the pattern instinctively. Simple runes flicker with suppressed energy until the runemaster needs their power, then they blaze with brilliant potency. Simple runes radiate faint magic of no specific school.\r\nA runemaster begins with a single simple rune. As his understanding of the runes grows, he can add others.\r\n*The pattern of swift water flowing over a streambed, the rune of flowing water speeds the movements of the runemaster.\r\n*The pattern that heated coals make in the air above them, the rune of glowing coals grants the runemaster bonus damage with his unarmed attacks.\r\n*The pattern left in the air by the passage of sparks from a fire, the rune of leaping sparks lightens the body and aids the jumps of a runemaster. \r\n*The pattern of mangrove roots in brackish swamp water, the rune of the mangroves grants the runemaster immunity to non-magical poisons and diseases.\r\n*The pattern of rings that develop within the trunk of an oak as it ages, the rune of the oaks grants the runemaster a natural armor.\r\n*The pattern that the energy flowing through perfectly-crafted steel creates, the rune of perfect steel is tattooed to the back of a runemaster’s hands, allowing him to deal lethal or nonlethal damage with his unarmed attacks. (He makes the choice each time he attacks).\r\n*The pattern flame leaves in the wake of grasslands fire, the rune of raging flames grants the runemaster quicker land speed.\r\n*The pattern that results from heavy starlight upon rock, the rune of starlight allows the runemaster to foresee those attacks that are aimed at him.\r\nRunemasters fill many roles. They are adept melee combatants. They possess runes to enhance themselves and their allies, as well as to ward certain areas and otherwise make life difficult for their opponents. The most experienced runemasters become [[epic runemaster]]s. Others may be [[lone wolf runemaster]]s.\r\n==History==\r\nThe traditions of the runemasters date back to the ancient time of the [[Titan]]s, creators of runic magic. Their creation, the [[Dwarves]], quickly mastered the mysteries of the runes taught to them. However, as generations passed, the dwarves forgot their heritage and lost all knowledge of runes and their hereditary powers.\r\n[[Tauren]] in [[Kalimdor]] rediscovered the power of runes. An ancient race as well, the tauren remembered the myths of runecasting and revived interest in this nearly lost art. The dwarves that came to Kalimdor with [[Jaina Proudmoore]]'s Alliance Expedition learned tauren runecasting techniques. Tauren and dwarves do not share good relations, but they were eager to share knowledge of runes and Titan myths.\r\n==Affiliation==\r\nRunemasters may be found in either the Horde of the Alliance. Thought the arts of the runemaster originated among the ancient tauren, these techniques have been adopted by many races. After the tauren, dwarves are the most likely to practice the runemaster's art, with night elves, orcs and trolls making up a small population as well. Rare is the human runemaster, and dwarven mentors teach almost all of them. Many runemasters, particularly those whose studies of natural runic patterns take them away from the centers of civilization, end up taking a neutral stance.\r\n==Named==\r\n*smallicon=IconSmall_Tauren Male.gif\r\n*[[Dammia Frostcut]]\r\n*Eramas Brightblaze (presumed)\r\n==See also==\r\n*[[Rune magic]]",},
			["Runes"] = { content = "Where you looking for the:\r\n#[[Death knight]]'s resource system, then see [[rune system]] article.\r\n#Lore on runes, then see [[rune magic]] article.\r\n#Runes in [[blacksmithing]], then see [[rune (blacksmithing)]] article.",},
			["Runestone"] = { content = "'''Runestones''' are large blocks of rock carved with powerful runes of elven magic. They were placed by [[high elf|high elven]] [[druid magi]] to mark the boundaries of their new kingdom, [[Quel'Thalas]], and to create a magical barrier that stopped the use of [[arcane magic]] from being sensed by the [[Burning Legion]]. \r\nWhen the high elves founded Quel’Thalas, they erected monolithic runestones to mark their new kingdom’s borders. These enchanted monuments created a magic barrier that prevented the savage trolls from penetrating the elven lands. The barrier has not been used for millennia, but the runestones, untouched by fire and blade, remain.\r\nIn the [[Second War]] the great Runestone at [[Caer Darrow]] was captured by the [[orc]] [[warlock]] [[Gul'dan]] who used its potent magics to create the [[Altar of Storms|Altars of Storms]], which in turn created the first [[ogre-magi]]. Gul'dan speculated that the high elves had used enslaved trolls to physically move the stones into place, similarly to how he used ogre slaves to destroy them and build the Altar, though this is unconfirmed. \r\nFollowing Thrall's reformation of the Horde, many Altars were retooled by troll masons into structures capable of channeling shamanistic energies with the intent of reviving fallen heroes.\r\n===Quel'Thalas===\r\n*[[Runestone Falithas]], [[Eversong Woods]] (functional)\r\n*[[Runestone Shan'dor]], Eversong Woods (offline, but able to be reactivated)\r\n*Runestone in the [[Scorched Grove]], Eversong Woods (destroyed)\r\n*Mentioned fourth Runestone.\r\n===Other===\r\n*Runestone at [[Caer Darrow]] (destroyed, used to create [[Altar of Storms|Altars of Storms]])",},
			["Runestones"] = { content = "#REDIRECT [[Runestone]]", redirect = "Runestone",},
			["Runestone Falithas"] = { content = "'''Runestone Falithas''' is one of the four remaining runestones that protect [[Eversong Woods]] from the effects of the plague. Of the four, it is the only one to remain completely intact and functional.",},
			["Runestone Shan'dor"] = { content = "'''Runestone Shan'dor''' is one of the four remaining runestones that protect [[Eversong Woods]] from the effects of the plague. It has become deactivated, but can be reclaimed by using the energy from an arcane gem.",},
			["Runetotem clan"] = { content = "The '''Runetotems''' are a tribe of tauren residing throughout [[Mulgore]], [[The Barrens]], and [[Feralas]]. They have only recently rediscovered the ways of the druid.\r\n==Known Runetotems==\r\n*[[Arch Druid Hamuul Runetotem]]\r\n*[[Bashana Runetotem]]\r\n*[[Dela Runetotem]]\r\n*[[Elder Runetotem]]\r\n*[[Gennia Runetotem]]\r\n*[[Mura Runetotem]]\r\n*[[Sanuye Runetotem]]\r\n*[[Sheal Runetotem]]\r\n*[[Tonga Runetotem]]\r\n*[[Turak Runetotem]]",},
			["Rune (blacksmithing)"] = { content = "A [[consumable]] [[item]] that temporarily absorbs damage to armor. Runes are created by the [[blacksmithing]] profession.\r\n*'''Runes of Warding''' are applied to chest armor and absorb a set amount of damage every 2 minutes. This effect lasts 1 hour.",},
			["Rune magic"] = { content = ":\r\n----\r\nA rune is an arcane symbol inscribed on a creature, surface or object. Runes exist in groups called families, which are composed of ten runes. No runes ever require a verbal component. Inscribing a rune reqires physical contact with the target.\r\n==The Runic Art==\r\nThose who seek to understand and master runic power understand that the convergences of the [[ley lines]] are not the only important part of this power — the patterns formed by the lines themselves are important as well. These patterns, which resemble letters in a strange alphabet, are called runes. Each rune is a reflection of a pattern of energy lines somewhere in the world. Each such pattern creates a certain magical effect when energy flows in that specific formation, though in its natural occurrence, this effect is much too broad and scattered to have a meaningful impact.\r\nThose who master runes, then, seek to duplicate those patterns in smaller forms; their runes manifest [[magic]]al power that is [[arcane]] in nature, but purely benign and non-corrupting. They are manifestations of [[Azeroth]]’s own unique flows of power, nothing more.\r\nThese secrets represent recent understandings of rune magic — until recently, it was believed that runes were simply symbols of power from ancient days. With the discovery of the ties between the form of runes and the patterns of natural power in the world, it is only a matter of time before more rune families are uncovered, extrapolated from other natural power sites.\r\nRunes are organized into rune patterns, which are not actually separate runes. Instead, each rune pattern is a grand, complex rune that encompasses the individual designs of each rune within that pattern. Thus, the rune for a more complex spell actually includes the pattern of the less complex spell that precedes it in the rune pattern, which itself includes the pattern of the cantrip that begins that pattern. Essentially, each rune pattern is a larger and larger pattern, the center of which is the rune for the simplest rune, which is added to in greater degrees of complexity the higher up the tree one goes.\r\n==Empowering a Rune==\r\nEmpowering a rune means flooding it with arcane power, and the process is nearly identical to casting a spell. Runes are inert before their creator empowers them. Thus, rune magic is a two-part process: first the caster creates the rune, and then, immediately or some time later, he empowers it. All characters with this ability are called rune-casters (just as all characters able to cast spells are spellcasters). Note that the character empowering a rune does not have to be the same character who created the rune, but he does have to be aware of the rune’s existence and know the rune pattern.\r\nWhile empowering a rune is akin to casting a spell, the two actions are very different. Where the normal arcane caster channels arcane power and shapes it through the use of gesture, word and material components, the runecaster simply shunts the energy into the pattern formed by the rune, serving as the channel between the energy and the rune.\r\nThis process defines the difference between runecasting and arcane spellcasting, and is the reason that the use of runes does not cause arcane corruption. The patterns of traditional arcane spellcasting are not natural — the energy of the world, which emanates from the [[Well of Eternity]], does not flow into those patterns without the dominating will of the arcane caster to bend and spindle it into those shapes. This is an act of supreme hubris; the forcing of the world’s essential power to submit to the desires of the caster is the reason that other kinds of arcane casting cause corruption.\r\nRune-casting uses patterns that already exist in the world. Since these are naturally occurring patterns created by manifestations of the Well of Eternity’s power in the world, the rune-caster need not force the energy to obey him. It flows willingly into the patterns — these are the patterns that the energy itself created, duplicated\r\non a smaller scale.\r\n==Rune Patterns==\r\nAncient lore groups runes into rune patterns. In reality, each pattern is the two-dimensional depiction of an intricate network of ley lines located somewhere in the world. These patterns are incredibly complex, made up as they are of many lines and curves. Runes are the written representation of the paths that the ley lines follow around and through geographical features in magically powerful sites.\r\nA character learns new runes the same way other characters learn new spells, by paying another runecaster. However, rune-casters who seek out runic sites may meditate on the flows of power to gain new understanding.\r\n==Runic Sites==\r\nThe patterns that make up rune patterns are not simply arcane scribblings, each is the two-dimensional representation of a place in the world that some runecaster has had the opportunity to study. By discovering the precise layout of the [[ley lines]] in a place of power, the nature of that place can be recreated: The ley lines of a scorching desert rendered into a rune might create effects of burning destruction, while those of a deep swampland might perhaps create runes of rot or decay.\r\nWhen a rune-caster is present at the site upon which a rune pattern is based, he is considered to be more skilled for the purpose of determining the effects of runes from the native pattern.\r\n==Types of Runes==\r\nThere are three kinds of runes: marks, glyphs and sigils. A mark is inscribed upon a creature, and each mark targets a single creature. A glyph is cast upon an object, and each glyph targets a single object. A sigil is placed upon an object or creature in order to create an effect in an area, with that object or creature at the center. Each sigil has an area that it affects.\r\n===Marks===\r\nMarks are runes inscribed on a creature. The subject must be still, so marks cannot be inscribed on unwilling creatures, however a mark can be inscribed on any helpless creature. Marks generate their effects immediately upon completion. Some inscribes have the ability to delay mark activation or even to make a mark permanent.\r\n===Glyphs===\r\nGlyphs are runes inscribed on an object. As with marks, a glyph can not be inscribed on an object in the possession of an unwilling creature. Glyphs activate immediately upon completion. Again, some inscribes are able to extend the life of a glyph or even to make one permanent.\r\n===Sigils===\r\nSigils are runes inscribed on a surface that subsequently acts as the rune's trigger. The affected surface is always five-foot by five-foot area, and the first creature to enter the space with a sigil activates it, even if the creature is unaware of the sigil. Sigils last until triggered, dispelled or erased. The inscriber can choose to activate a sigil upon its completion as part of the final inscription process. An activated sigil always generates a thirty-foot-radius burst centered on the rune, affecting all creatures in its area.\r\n==Crafting Runes==\r\nBecause the power of rune magic is dependent upon the pattern of the rune itself, the one thing that all rune effects have in common is the necessity for the rune to physically exist in order for the magic to take effect. Every rune can be used in one of three ways: as a spontaneous rune, as a scribed rune, and as a permanent rune.\r\n===Spontaneous Runes===\r\nSpontaneous runes are created when the rune-caster doesn’t have the time to properly scribe a rune on a surface (in combat, for instance). All rune-casters keep small pieces of wood or stone upon which they scribe the runes they know. These small plaques cost almost nothing to create, and most rune-casters create them in their spare time, storing them with their material components. When casting a rune, the rune-caster touches one of these runestones or runesticks to the target and channels the power through the rune. The rune fades from the runestone and appears on the target, appearing to be burned onto non-living objects or etched in glowing lines onto the flesh of creatures. While the quickest form of rune-making possible, spontaneous runes are also the most fragile. Casting a spontaneous rune, unlike other runes, is only a one-step process: Placing the rune on the target and empowering it occur at the same time.\r\n===Scribed Runes===\r\nScribed runes represent the preferred method of creating runes. Using a set of special paints, the runecaster can create a lasting rune. Because the rune exists upon the subject, none of the spell’s energy need be wasted in creating the rune, as is done with spontaneous runes. The benefit of a scribed rune is that it is more difficult to destroy and dispel than a spontaneous rune, and the range is usually longer. Placing a scribed rune upon the body of a creature requires that the creature be willing or helpless, while placing such a rune upon an object requires that the rune-caster handles the object. Scribed runes last for number of days depending on the skill of the caster, or until empowered. After the rune’s empowerment ends, the rune fades away.\r\n===Permanent Runes===\r\nPermanent runes are runes that, once created, are nearly impossible to destroy, for their magic is such that even with the passage of time, the rune remains. Living flesh must be tattooed with the marks (though some orc runemasters are said to practice a form of ritual branding). Most nonliving material is etched with a ritual stylus or set of special chisels. The rune-caster must also place a small part of his own spirit into the rune. The benefit of a permanent rune is that it is more difficult to destroy than a spontaneous rune. Thus, when the magic empowering the rune fades (i.e., its duration expires), the rune still exists on the target, and the runecaster can empower it again. Placing a permanent rune upon the body of a creature requires that the creature be willing or helpless, while placing such a rune upon an object requires that the rune-caster handles the object.\r\n==Detecting Runes==\r\nPerhaps the primary downfall of rune-casting lies in the fact that it is unsubtle. Objects, places and people marked with runes are obvious, for the runes are sprawling, complex patterns that appear to be inked, etched, tattooed or seared into the surface of the thing they affect. A rune may be concealed beneath something (such as clothing for runes upon creatures, or behind a tapestry for a rune etched into a wall), but if the rune is currently generating a magical effect, it gives itself away, for it glows with arcane energy.\r\nWhen runes generate magical effects, they glow. The color depends upon the caster and the rune, but is often gold or silver. These runes are obviously magic and active. If the rune is concealed, a better look allows a creature to notice the glow or see the effects of the rune in the air around the target. An empowered rune sometimes creates a strange rippling effect, like heat off of stone in the middle of a desert. A detect magic spell reveals the presence of an empowered rune, though it does not reveal what specific effect is in place. It does grant a glimpse at the pattern of energy it forms, however, so that those who use detect magic may gain an idea of a rune’s pattern is.\r\n==Destroying Runes==\r\nBecause the scribed pattern of the rune provides the pattern for the power to flow, destroying a rune can destroy the magic it creates. However, it is the nature of such patterns to be self-preserving. so they are hard to destroy because the patterns are natural, and energy is easily pulled into them. As a result, the runes themselves are difficult to destroy.\r\nA rune has a hardness, and a toughness equal to the runes power. A rune catches attacks in arcane streams of power, so attacking a rune deals no damage to the object or person upon which it is placed, unless the attack deals enough damage to destroy the rune (in which case the rune’s bearer takes the excess damage).\r\nSpontaneous runes are easily destroyed in the fashion of other magic, through the use of dispel magic and similar spells. Additionally, destroying the rune itself dispels the effect.\r\nScribed and permanent runes are more difficult to destroy. The inks used to create them provide no great resistance until they are empowered, but once the rune is empowered, the inks regenerate for as long as the empowerment lasts. Additionally, in order to use a dispel magic or a similar ability on a scribed or permanent rune, the rune must be greatly damaged. A dispelling effect that is more powerful than the rune can dispel it without this restriction. If the rune’s magic is dispelled in such a fashion, the rune is destroyed.\r\n==Runecasters==\r\n*[[Runemaster]]\r\n*[[Inscriber]]\r\n==Dark Runecasters==\r\nIn an interview about [[Dark Factions]] with Luke Johnson he said that [[dark inscriber]]s use [[rune]]s to channel necromantic and/or demonic [[magic]]. It is likely that lore about the dark channeling of runes will be explained in Dark Factions.\r\n==Runes in Warcraft II==\r\nThe casting of ancient and powerful Runes enables the [[Ogre-Mage]] to lay an abstruse trap for those hapless enough to enter into it. When these Runes explode, they cause massive damage to anyone standing over them as well as all those in adjacent areas. Those who are diligent and watchful will catch a glimpse of the Rune as they approach it. The chaotic forces that make up this enchantment can not discern between ally or enemy and will kill a friend as surely as a foe. Heed these warnings well, as even staying near these Runes can be hazardous - for when the dwoemer dissolves, they explode as if their magiks had been triggered.\r\n==Runes in Wrath of the Lich King==\r\nRunes will be featured in the second WoW expansion, in the [[death knight]]s [[rune system]], in the new profession [[Inscription]], the [[Vrykul]] practice a runic magic that even the most experienced wizards find unfamiliar, and the [[iron dwarf|iron dwarves]] that will be etched with runes of power on their metallic skin.",},
			["Rune of Duty"] = { content = "The '''Rune of Duty''' is a [[quality]] [[PvP]] reward [[trinket]] for melee fighters of the [[Horde]] and [[Alliance]] (same item for both factions) from the [[Warsong Gulch]] battleground. There are two versions of the trinket:\r\n* [[Rune of Duty (level 20)]] (level 20)\r\n* [[Rune of Duty (level 40)]] (level 40)\r\nThe caster equivalent is Rune of Perfection.",},
			["Rune of Koro"] = { content = "The '''Rune of Koro''' can be found inside [[Molten Core]], guarded by [[Sulfuron Harbinger]]. It must be doused using Eternal Quintessence or Aqual Quintessence in order to summon [[Majordomo Executus]].",},
			["Rune of Mazj"] = { content = "The '''Rune of Mazj''' can be found inside [[Molten Core]], guarded by [[Shazzrah]]. It must be doused using Eternal Quintessence or Aqual Quintessence in order to summon [[Majordomo Executus]].",},
			["Rune of Mohn"] = { content = "The '''Rune of Mohn''' can be found inside [[Molten Core]], guarded by [[Gehennas]]. It must be doused using Eternal Quintessence or Aqual Quintessence in order to summon [[Majordomo Executus]].",},
			["Rune of Perfection"] = { content = ":\r\n==Source==\r\nThis item is a PvP reward, and can be purchased for h=118 gold wsg=30 silver from:\r\n* Illiyana Moonblaze in [[Ashenvale]]\r\n* Kelm Hargunth in [[The Barrens]]",},
			["Rune of Teleportation"] = { content = "'''Rune of Teleportation''' is a reagent used by [[mages]] to [[teleport]] the mage to major cities. \r\nCompare Rune of Portals which is used by a mage to portal the entire party to one of the major cities.\r\n*Stacks in lots of 20. (Before [[Patch 2.3.0/Undocumented changes|Patch 2.3.0]], they stacked in lots of 10.)\r\n*Any class may purchase and hold these, however they can only be used by [[mage]]s.\r\n*When the mage finishes casting a teleport spell, one '''Rune of Teleportation''' is consumed, and the mage is transported.\r\n==Source==\r\n'''Runes of Teleportation''' are sold by [[reagent]] [[vendors]].\r\nThe cost of these runes may be discounted, depending on the [[reputation]] held with the vendor's [[faction]]. At honored reputation the cost for each is 9 silver .",},
			["Rune of Theri"] = { content = "The '''Rune of Theri''' can be found inside [[Molten Core]], guarded by [[Golemagg the Incinerator]]. It must be doused using Eternal Quintessence or Aqual Quintessence in order to summon [[Majordomo Executus]].",},
			["Rune of the Dawn"] = { content = "'''Rune of the Dawn''' is a [[trinket]] that serves as an [[Argent Dawn Commission]] and increases magical damage against undead.\r\n==Source==\r\nRune of the Dawn is a quest reward from the quest [[Quest:The Active Agent|The Active Agent]] which starts with [[Betina Bigglezink]] at [[Light's Hope Chapel]] in [[Eastern Plaguelands]]. To complete the quest, you must turn the following item to Betina Bigglezink:\r\n*1 [[Scourge Data]]\r\n==Notes==\r\nIf you destroy the Rune of the Dawn, talk with Betina Bigglezink to choose again between [[Seal of the Dawn]] and Rune of the Dawn.",},
			["Rune of Zeth"] = { content = "The '''Rune of Zeth''' can be found inside [[Molten Core]], guarded by [[Baron Geddon]]. It must be doused using Eternal Quintessence or Aqual Quintessence in order to summon [[Majordomo Executus]].",},
			["Rune system"] = { content = "The '''Rune system''' is the resource system that is used by [[death knight]]s, as opposed to [[Mana]], [[Energy]], or [[Rage]]. Details on the '''Rune system''' will be presented as the development of the [[World of Warcraft: Wrath of the Lich King| new expansion]] continues, and information is subject to change.\r\n==Runes==\r\nThe '''Rune system''' revolves around three different types of runes, each of which corresponds to one the Death Knight's ability schools and talent trees. \r\nThe Death Knight has 6 Runes (2 of each main type) to power their abilities. Different abilities consume different types and amounts of runes, and when used, will place the corresponding runes on a 10 second recharge. Some abilities will also be able to refresh certain runes.\r\nThe three main rune types are:\r\n* '''Blood'''\r\n* '''Frost'''\r\n* '''Unholy'''\r\nAlong with a fourth type, which can act as any of the main types: \r\n* '''Death'''\r\nThe death rune can be created by using the ability [[Blood Tap]], as well as through a Blood tree talent [[Death Rune Mastery]], which will give you a chance to convert any rune that is activated into one. Also by the Frost tree talent [[Blood of the North]], which for each point gives you a 20% chance, max five points, to turn Blood Strke Blood Runes into Death Runes.\r\nThere is also a concept with a similar name called [[Runeforging]] which works like an enchant on the weapon.\r\n==Runic Power==\r\nRunic Power is a resource which builds up as the Death Knight uses rune abilities, displayed as a visible glow around the sword located under the Death Knight's portrait. Like Rage, Runic Power gradually diminishes when not being consumed or accumulated. Similar to [[Combo Point]]s and [[finishing move]]s, Death Knights have abilities which will completely unleash all stored Runic Power; the more Runic Power that has been gathered, the more powerful the ability becomes.\r\n==Development==\r\nDevelopers at [[BlizzCon 2007]] said they didn't want the new Death Knight to use the traditional resource systems because they wanted the death knight to have a different mode of play. They stated their intention was for the Death Knight to use a mixture of spells ''and'' melee in close combat. Because of this, a system that didn't specifically rely on either Mana or Rage was more appropriate.\r\nHow the original icons looked: \r\nDuring the 2008 [[WWI]], it was noted that the original runes were replaced because they were too complex to show the refresh inside the character portrait bar. However, the replacement runes are only temporary while they design new ones.\r\nHow the replacement icons looked:",},
			["Rune Thread"] = { content = "==Source==\r\nThis item can be purchased for s=50 gold from:\r\nMajor Cities\r\n* Jillian Tanner in [[Stormwind City]]\r\n* Alexandra Bolero in [[Stormwind City]]\r\n* Edna Mullby in [[Stormwind City]]\r\n* Mythrin'dir in [[Teldrassil]]\r\n* Elynna in [[Teldrassil]]\r\n* Deynna in [[Silvermoon City]]\r\n* Zaralda in [[Silvermoon City]]\r\n* Parnis in [[Silvermoon City]]\r\n* Neii in [[The Exodar]]\r\n* Haferet in [[The Exodar]]\r\n* Nurguni in [[The Exodar]]\r\n* Trader Endernor in [[Shattrath City]]\r\n* Eral in [[Shattrath City]]\r\n* Ernie Packwell in [[Shattrath City]]\r\n* Cro Threadstrong in [[Shattrath City]]\r\n* Eiin in [[Shattrath City]]\r\nAzeroth\r\n* Felicia Doan in [[Tirisfal Glades]]\r\n* Millie Gregorian in [[Tirisfal Glades]]\r\n* Daniel Bartlett in [[Tirisfal Glades]]\r\n* Joseph Moore in [[Tirisfal Glades]]\r\n* Mahu in [[Mulgore]]\r\n* Shadi Mistrunner in [[Mulgore]]\r\n* Ziz in [[Azuremyst Isle]]\r\n* Kinamisa in [[Eversong Woods]]\r\n* Sempstress Ambershine in [[Eversong Woods]]\r\n* Borya in [[Durotar]]\r\n* Felika in [[Durotar]]\r\n* Shimra in [[Durotar]]\r\n* Tamar in [[Durotar]]\r\n* Gorbold Steelhand in [[Darkshore]]\r\n* Valdaron in [[Darkshore]]\r\n* Rann Flamespinner in [[Loch Modan]]\r\n* Saenorion in [[Teldrassil]]\r\n* Lardan in [[Ashenvale]]\r\n* Shandrina in [[Ashenvale]]\r\n* Dalria in [[Ashenvale]]\r\n* Harlown Darkweave in [[Ashenvale]]\r\n* Kalldan Felmoon in [[The Barrens]]\r\n* Yonada in [[The Barrens]]\r\n* Wrahk in [[The Barrens]]\r\n* George Candarte in [[Hillsbrad Foothills]]\r\n* Mallen Swain in [[Hillsbrad Foothills]]\r\n* Christopher Hewen in [[Westfall]]\r\n* Jennabink Powerseam in [[Wetlands]]\r\n* Danielle Zipstitch in [[Duskwood]]\r\n* Sheri Zipstitch in [[Duskwood]]\r\n* Lohgan Eva in [[Duskwood]]\r\n* Franklin Hamar in [[Redridge Mountains]]\r\n* Captured Servant of Azora in [[Redridge Mountains]]\r\n* Clyde Ranthal in [[Redridge Mountains]]\r\n* Androd Fadran in [[Arathi Highlan