			["Rungor"] = { content = "'''Rungor''' is a level 63 trade goods [[vendor]] located at [[Stonebreaker Hold]] in the [[contested]] territory of [[Terokkar Forest]]. He can be found outside the inn, on the south side of town. Coords: 48,46.\r\nHe sells the following items:\r\n*[[Recipe: Spicy Crawdad]]\r\n*[[Recipe: Golden Fish Sticks]]\r\n*[[Formula: Runed Adamantite Rod]] (limited supply)\r\nSee [[List of Terokkar Forest NPCs]].",},
			["Runic Breastplate"] = { content = "The '''Runic Breastplate''' is plate chestplate that improves [[resistance]] to both fire and nature damage.\r\n==Source==\r\nThe '''Runic Breastplate''' is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 300.\r\nThe components are:\r\n*40 [[Thorium Bar]]s\r\n*2 [[Arcanite Bar]]s\r\n*1 [[Star Ruby]]\r\nThe [[plans]] drop off [[Strashaz Myrmidon]]s on the [[Alcaz Island]] in [[Dustwallow Marsh]].",},
			["Runic Hammer"] = { content = "==Source==\r\nThis item is crafted by [[blacksmith]]s who have skill 365 or greater.\r\nMaterials required:\r\n* 10x Khorium Bar\r\n* 10x Felsteel Bar\r\n* 8x Primal Might\r\n* 2x Primal Nether\r\nPlans: Runic Hammer is a [[world drop]].",},
			["Runic Leather Armor"] = { content = "==Source==\r\nThis item can be crafted using [[Leatherworking]] (300); taught by Pattern: Runic Leather Armor.",},
			["Runic Leather Pants"] = { content = "==Source==\r\nThis item can be crafted using [[Leatherworking]] (300); taught by Pattern: Runic Leather Pants.",},
			["Runic Leather Shoulders"] = { content = "==Source==\r\nThis item can be crafted using [[Leatherworking]] (300); taught by Pattern: Runic Leather Shoulders.",},
			["Runic Plate Boots"] = { content = "'''Runic Plate Boots''' are plate boots that improve [[resistance]] to both fire and nature damage.\r\n==Source==\r\n'''Runic Plate Boots''' are crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 300.\r\nThe components are:\r\n*20 [[Thorium Bar]]\r\n*2 [[Arcanite Bar]]\r\n*10 [[Silver Bar]]\r\nThe [[Plans: Runic Plate Boots|plans]] drop off the [[Scarlet Cavalier]] in the [[Western Plaguelands]].",},
			["Runic Plate Helm"] = { content = "'''Runic Plate Helm''' is a [[crafted]] plate head armor with Fire and Nature Resistance for warriors and paladins.\r\n==Source==\r\nRunic Plate Helm is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 300.\r\nThe components are:\r\n*30 [[Thorium Bar]]s\r\n*2 [[Arcanite Bar]]s\r\n*2 [[Truesilver Bar]]s\r\n*1 [[Huge Emerald]]\r\nThe [[Plans: Runic Plate Helm|plans]] drop off [[Strashaz Warrior]]s on [[Alcaz Island]] in [[Dustwallow Marsh]].",},
			["Runic Plate Leggings"] = { content = "'''Runic Plate Leggings''' are plate legguards that give extra [[resistance]] to fire and nature magic.\r\n==Source==\r\n'''Runic Plate Leggings''' are crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 300.\r\nThe components are:\r\n*40 [[Thorium Bar]]\r\n*2 [[Arcanite Bar]]\r\n*1 [[Star Ruby]]\r\nThe [[Plans: Runic Plate Leggings|plans]] drop off the [[Scarlet Smith]] in the [[Western Plaguelands]].",},
			["Runic Plate Shoulders"] = { content = "'''Runic Plate Shoulders''' are [[plate]] [[Equipment_slots|shoulders]] that offer some fire resistance and nature resistance.\r\n==Source==\r\nRunic Plate Shoulders is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 300.\r\nThe components are:\r\n*20 [[Thorium Bar]]\r\n*2 [[Arcanite Bar]]\r\n*6 [[Gold Bar]]\r\n[[Plans: Runic Plate Shoulders]] are a [[BoP]] recipe that sometimes drops off a Strashaz Serpent Guard in the [[Dustwallow Marsh]].",},
			["Runic Power"] = { content = "#REDIRECT [[Rune system]]", redirect = "Rune system",},
			["Runic Spellthread"] = { content = "Use: Permanently embroiders [[spellthread]] into pants, increasing [[spell damage]] and [[healing]] by up to 35 and [[Stamina]] by 20.\r\n==Source==\r\nPattern: Runic Spellthread is sold by Quartermaster Enuril in [[Scryer's Tier]] in [[Shattrath City]] and requires reputation to purchase. Level 375 [[Tailoring]] is required to make it.\r\nMaterials required:\r\n*1x Rune Thread\r\n*10x Primal Mana\r\n*1x Primal Nether\r\n==Notes==\r\nThe spellthread is not [[BoP]] and can therefore be traded. Character level 60 is required to apply the spellthread on leg armor.",},
			["Runner"] = { content = "Runner(s) is usually referred to a [[mob]](s) that is escaping from a battle engagement (usually from you or/and from your teammates) because it is either low in health points or [[Fear Effect|feared]]. Usually, you don't want runners (especially in instances) because they call other nearby [[mob|mobs]] for assistance. To prevent runners, players try to finish the mobs with low health points as quickly as possible or to [[snare]]/[[stun]]/[[root]] them long enough to kill them before they call for more help.\r\nThe [[Warlock]] spell [[Curse of Recklessness]] prevents a [[mob]] from running, as does the [[Paladin]] with [[Judgement of Justice]].",},
			["Running"] = { content = "#REDIRECT [[Movement]]", redirect = "Movement",},
			["Ruogo"] = { content = "'''Ruogo''' is a level 60 general goods [[vendor]] located at the [[Refugee Caravan]] in the [[contested]] territory of [[Terokkar Forest]].\r\nSee [[List of Terokkar Forest NPCs]].",},
			["Rupture"] = { content = "''''''You may have escaped my blades, but how long will it take for you to bleed to death?''''''\r\n'''Rupture''' is a [[rogue]] finishing move that inflicts a bleeding wound on the target, working as a [[DoT]].''\r\n==Functionality==\r\nFinishing move that causes damage over time, increased by your attack power. Lasts longer per [[Combo point]].\r\n===Use===\r\n25 [[Energy]]\r\n[[Instant cast]]\r\n5 yard range\r\nRequires Melee Weapon\r\n===Notes===\r\nPreviously, rupture was a static damage finishing move that offered the same [[DPS]] no matter how many combo points were saved up -- additional combo points only extended the duration of rupture. The prevalent strategy was to gauge how many seconds left your target had to live, and to only use enough combo points to match it. However, rupture was overhauled to improve its scalability and make it a more attractive ability for end-game use.\r\nRupture now increases damage and duration per combo point used, for example: \r\n* Rupture (Rank 1) with 1 combo point will deal 40 damage over 8 seconds, which calculates to 10 damage per tick (5 damage per second)\r\n* Rupture (Rank 1) with 5 combo points will deal 144 damage over 16 seconds, which calculates to 18 damage per tick (9 damage per second)\r\nA 5 combo point rupture at rank 1 is an 80% damage increase from 1 combo point, and lasts twice as long.\r\nRupture also factors in a percentage of your total attack power as bonus damage that is spread out over the duration of your rupture, for example: A rogue with 1000 attack power using a 5 combo point (rank 7) rupture will do 1000+240 damage over 16 seconds, which is an additional 30 damage per tick. The bonus damage from your attack power scales based on the number of combo points on the target as outlined in the damage calculation table below.\r\n===Limitations===\r\n*Requires [[Combo Points]].\r\n===Rank Table===\r\n* Note to use the below, multiply the coefficient by the number of combo points and add that to the base dps value. Which will result in the actual dps per combo point for that rank.\r\n==Related Talents==\r\n*[[Serrated Blades]] increases the damage of your Rupture by 10%, 20%, or 30%.\r\n*[[Master of Subtlety]] increases damage of the opener and attacks in the next 6 seconds by 4%, 7%, 10%.\r\n==Related Items==\r\n*The 5 piece bonus of the [[Madcap's Outfit]] armor set reduces the energy cost of Rupture by 5.\r\n==Damage Calculation Formula==\r\nThe rough formula for rupture(rank 7) damage is:\r\n 1pt = Attack Power * 0.04 + 324\r\n 2pt = Attack Power * 0.10 + 460\r\n 3pt = Attack Power * 0.18 + 618\r\n 4pt = Attack Power * 0.21 + 798\r\n 5pt = Attack Power * 0.24 + 1000\r\nan interesting side effect is the damage per tick\r\n 1pt x 4 ticks at = Attack Power * 0.01 + 81\r\n 2pt x 5 ticks at = Attack Power * 0.02 + 92\r\n 3pt x 6 ticks at = Attack Power * 0.03 + 103\r\n 4pt x 7 ticks at = Attack Power * 0.03 + 114\r\n 5pt x 8 ticks at = Attack Power * 0.03 + 125\r\n==Tips==\r\n*Save this for longer fights, or fights against highly-armored opponents. Don't waste combo points extending the duration for longer than the fight is likely to last.\r\n*Be careful of using any [[DoT]]-type attacks, as it commits you to the fight in that many [[Crowd Control]] abilities will be broken by the damage it causes.\r\n*The [[Hemorrhage]] talent/ability will not add damage to Rupture (or any other DoT). \r\n*As of patch 2.4, skeletal and non-corporeal undead (such as wraiths), elementals and mechanical creatures are now susceptible to bleed effects.\r\n*Works well against other Rogues who may use vanish to escape, since any damage removes stealth.",},
			["Rustmaul Digsite"] = { content = "#REDIRECT [[Rustmaul Dig Site]]", redirect = "Rustmaul Dig Site",},
			["Rustmaul Dig Site"] = { content = "An abandoned [[Dwarven]] digsite in the [[Shimmering Flats]]. Some [[Dwarves]] that were digging here were driven off by a raid of [[Horde]] [[Hunters]] and [[Warriors]]. Much to the raid's dismay, [[Silithid|Silithids]] began pouring out of an uncovered nest. Some killed and some injured, they fled to Horde Territory. [[Korran]] was one of them. Now the aggressive Silithid wander over the abandoned dig.",},
			["Rusty Harvest Golem"] = { content = "'''Rusty Harvest Golem''' is a 8-10 [[Golem]] that can be found in [[Westfall]].\r\n==Drops == \r\n Quest items dropped by Rusty Harvest Golem\r\nAlso 9 random [[Uncommon]] and 28 random [[Common]] item drops.",},
			["Rut'theran Village"] = { content = "'''Rut'theran Village''' was a [[village]] [[harbor|port]] for the [[Night elf|night elven]] [[city]] of [[Darnassus]], located at the very bottom of the [[World Tree]] [[Teldrassil]]. There is a [[portal]] here that goes directly into Darnassus, as well as three docks with regular boats going to the ''[[Exodar]]'' and [[Stormwind City]]. There is also a [[hippogryph]] roost that goes, for free, to both [[Darkshore]] and, for [[druid]]s, [[Moonglade]] in [[Northern Kalimdor|Northern]] [[Kalimdor]]. The [[Midsummer Fire Festival]] braziers are lit here.\r\nThe first settlement by this name was destroyed by the sea during the [[Cataclysm (event)|Cataclysm]], but the second one was quickly built. It was humble by night elf standards but with an exceedingly fresh appearance. In the hippogryph breeding area, hippogryph eggs were meticulously cared for and the young were raised. The kaldorei living in the village worked to support their capital above, but they also hosted all kinds of celebrations, like the Midsummer.\r\n===World of Warcraft===\r\nRut'theran Village originally had just one dock connected to [[Auberdine]] via ''[[The Moonspray]]'' boat.\r\n===Quest givers===\r\n* Krennan Aranas\r\n===Goods and services===\r\n* Androl Oakhand\r\n* Nessa Shadowsong\r\n* Vesprystus\r\n===Additional NPCs===\r\n* Daryn Lightwind\r\n* Erelas Ambersky\r\n* Gilneas Refugee\r\n*Guards: Darnassus Sentinel x8\r\n===Portal===\r\n* [[Darnassus]]\r\n* [[Stormwind Harbor]]\r\n===Flight===\r\n* [[Exodar]] 88 copper \r\n* [[Lor'danel]], [[Darkshore]] (free)\r\n* [[Darnassus]] (free)\r\n===Boat===\r\n* [[Exodar]] from western dock \r\n* [[Stormwind Harbor]] from southern dock (no longer functional as of , instead replaced with a portal).\r\nThe boat on the eastern dock is permanently berthed and doesn't go anywhere. In the ''Cataclysm'' beta, this was where [[worgen]] characters disembarked after leaving [[Gilneas (starting zone)|Gilneas]] for the main world, but at some point it was changed to the western dock.",},
			["Rutgar Glyphshaper"] = { content = "'''Rutgar Glyphshaper''' is a level 60 [[quest giver]] located at [[Bronzebeard Encampment]] in the [[contested]] territory of [[Silithus]].\r\nHe starts the following quests:\r\n* Glyph Chasing (Elite)\r\n* Unraveling the Mystery\r\nSee [[List of Silithus NPCs]].",},
			["Rutherford Twing"] = { content = "'''Rutherford Twing''' is a level 55 [[pvp rewards]] [[vendor]] located in [[Hammerfall]] in the [[contested]] territory of [[Arathi Highlands]]. He is the [[Forsaken Defilers]]' Supply Officer, and he stands outside the entrance to the [[Arathi Basin]] in the north part of town. [[Horde]] players that have a good reputation with the Defilers can buy special items from him.\r\nDue to the level banding that occurs in battlegrounds, many of these items have multiple versions with the same name. For example, there are 4 versions of the [[Defiler's Cloth Girdle]] available at levels 28, 38, 48, and 58. Each one is more powerful than the next.\r\n===Friendly===\r\n*[[Defiler's Enriched Ration]]\r\n*[[Defiler's Field Ration]]\r\n*[[Defiler's Iron Ration]]\r\n*[[Defiler's Mageweave Bandage]]\r\n*[[Defiler's Runecloth Bandage]]\r\n*[[Defiler's Silk Bandage]]\r\n*[[Defiler's Talisman]]\r\n*[[Superior Healing Draught]]\r\n*[[Superior Mana Draught]]\r\n===Honored===\r\n*[[Defiler's Chain Girdle]] - Hunter, Shaman\r\n*[[Defiler's Cloth Girdle]] - Priest, Mage, Warlock\r\n*[[Defiler's Lizardhide Girdle]] - Rogue, Druid\r\n*[[Defiler's Leather Girdle]] - Rogue, Druid\r\n*[[Defiler's Mail Girdle]] - Hunter, Shaman\r\n*[[Defiler's Plate Girdle]] - Warrior\r\n===Revered===\r\n*[[Defiler's Chain Greaves]] - Hunter, Shaman\r\n*[[Defiler's Cloth Boots]] - Priest, Mage, Warlock\r\n*[[Defiler's Lizardhide Boots]] - Rogue, Druid\r\n*[[Defiler's Leather Boots]] - Rogue, Druid\r\n*[[Defiler's Mail Greaves]] - Hunter, Shaman\r\n*[[Defiler's Plate Greaves]] - Warrior\r\n===Exalted===\r\n*[[Defiler's Chain Pauldrons]]\r\n*[[Defiler's Epaulets]]\r\n*[[Defiler's Lizardhide Shoulders]]\r\n*[[Defiler's Leather Shoulders]]\r\n*[[Defiler's Mail Pauldrons]]\r\n*[[Defiler's Plate Spaulders]]\r\n*[[Deathguard's Cloak]]\r\n*[[Ironbark Staff]]\r\n*[[Mindfang]]\r\nSee [[List of Arathi Highlands NPCs]].",},
			["Ruthlessness"] = { content = "'''Ruthlessness''' is a 3 point [[Rogue]] talent located in the 2nd tier of the [[Rogue_talents|Assassination Tree]].\r\n==Notes==\r\nIn [[Patch 2.3]], only affects melee finishing moves and no longer works with [[Deadly Throw]].",},
			["Ruuan Weald"] = { content = "'''Ruuan Weald''' is a forested glade located in eastern [[Blade's Edge Mountains]]. It houses both [[Evergrove]] and [[Veil Ruuan]], and has two ramps leading down into [[Cursed Hollow]] and [[Daggermaw Canyon]]. It is heavily patrolled by aggressive members of the [[Wyrmcult]].",},
			["Ruul Snowhoof"] = { content = "'''Ruul Snowhoof''' is a level 26 [[quest giver]] located deep in [[Thistlefur Hold]] in the [[contested]] territory of [[Ashenvale]]. A tauren druid, he was captured by the corrupted Thistlefur [[furbolgs]] while in bear form. They believe him to be a bear and are, for some reason, starving him to death.\r\nRuul will ask Horde players to free him and escort him to safety, for the questFreedom to Ruul.\r\nCuriously, Ruul's bear form is that of a polar bear, instead of the standard tauren [[bear form]].\r\nRuul has apparently not changed form in front of the Thistlefur to prove to them he is a tauren. This could be because he believes he would be treated worse if they knew, or because the cage is too low to the ground to accommodate his humanoid form.\r\nSee [[List of Ashenvale NPCs]].",},
			["Ruul the Darkener"] = { content = "'''Ruul the Darkener''' can be found in [[Shadowmoon Valley]] wandering .\r\n==Drops ==",},
			["Ruuzel"] = { content = "'''Ruuzel''' is a level 22 female [[naga]] found in [[Ashenvale]].\r\n[[Talen]] wants the ring Ruuzel possesses.\r\n==Abilities==\r\n*[[Heroic Strike]]\r\n*[[Battle Stance]]\r\n==Quests==\r\n*Ruuzel\r\n==Loot==\r\n*Ring of Zoram ''(Quest Item)''",},
			["Ruuzlu"] = { content = "'''Ruuzlu''' is a level 45 [[elite]] [[troll]] found in [[Zul'Farrak]]. He accompanies [[Chief Ukorz Sandscalp]].",},
			["Ruw"] = { content = "'''Ruw''' is a level 44 [[artisan]] [[herbalism trainer]] located in [[Camp Mojache]] in the [[contested]] territory of [[Feralas]].\r\nSee [[List of Feralas NPCs]].",},
			["Ruzan"] = { content = "'''Ruzan''' is a level 10 [[quest giver]] located in [[Valley of Trials]] in the [[orc]] and [[troll]] starting zone of [[Durotar]].\r\nSee [[List of Durotar NPCs]].\r\n==Quests==\r\nHe starts the following quests:\r\n* Vile Familiars (Warlock)\r\n* Vile Familiars (Warlock 2)",},
			["Rwag"] = { content = "'''Rwag''' is a level 8 [[rogue trainer]] located in [[the Den]] in the [[orc]] and [[troll]] starting zone of [[Durotar]].\r\nSee [[List of Durotar NPCs]].\r\n==Quests==\r\nHe ends the following quests:\r\n*Encrypted Parchment (Orc)\r\n*Encrypted Tablet (Troll)",},
			["Ryedol's Lucky Pick"] = { content = "A [[quest objective]] of the A Dwarf and His Tools.",},
			["Rynthariel the Keymaster"] = { content = "'''Rynthariel the Keymaster''' is a [[dryad]] in the [[Stonetalon Mountains|Stonetalon Mountains]]. [[Kadrak]] wanted Rynthariel killed.\r\nRynthariel was the Keymaster of the [[Talon Den]] on [[Stonetalon Peak]]. Together with the [[druid]]s, she built the Talon Den, where they kept many powerful items. Hidden in a small lantern at the entrance of the Den, she hid the [[Gatekeeper's Key]], with which she was able to open caches around the Den. She once guarded the entrance of the Den with [[Gatekeeper Kordurus]].\r\n==Abilities==\r\n*Slowing Poison\r\n*Throw\r\n==Objective of==\r\n*[[Horde Presence]]",},
			["Sa'at"] = { content = "'''Sa'at''' is a level 70 [[quest giver]] located in [[Opening the Dark Portal|Black Morass]].\r\nHe starts the following quests:\r\n* The Opening of the Dark Portal (Dungeon)\r\n* Hero of the Brood\r\nSee [[Caverns of Time NPCs]].",},
			["Sab'aoth"] = { content = "'''Sab'aoth''' is a level 68 [[reagent]] and [[poison vendor]] located at [[Cosmowrench]] in the [[contested]] territory of [[Netherstorm]].\r\nA former member of the [[Twilight's Hammer clan]], he has taken a break from battling anyone who would challenge him to write a book on his experiences in the Clan while his Reagent business gets off the ground.\r\nHe starts the quest Bloody Imp-ossible!.\r\nSee [[List of Netherstorm NPCs]].",},
			["Sabellian"] = { content = "'''Sabellian''', also known as '''Baron Sablemane''', is a [[black dragon]], son of the black [[Dragon Aspect]], [[Deathwing]]. He was described as his lieutenant in all things prior to the black Aspect's abandonment of [[Draenor]].\r\n===Beyond the Dark Portal===\r\nDuring the black dragonflight's alliance with [[Ner'zhul]]'s [[Horde of Draenor|Horde]], Sabellian and his brethren transported the orc chieftains [[Fenris the Hunter|Fenris Wolfbrother]], [[Tagar Spinebreaker]], and a small party of orcs to [[Menethil Harbor]], on their way to retrieve the [[Jeweled Scepter of Sargeras]]. Once the artifacts were secured he followed Deathwing to the orcs' homeworld of [[Draenor]].\r\nOnce on Draenor, the black dragons settled into [[Blade's Edge Mountains|Gorgrond]] and [[Blade's Edge Mountains|Frostfire Ridge]]. They were not there long before they were attacked by [[Gruul the Dragonkiller|Gruul]], his offspring, and a small group of [[Alliance Expedition]] fighters. The eggs were destroyed and Deathwing was forced to flee from battle, followed immediately by Sabellian.\r\n===The Burning Crusade===\r\nDeathwing managed to return to Azeroth, but Sabellian remained behind on Draenor — now [[Outland]]. He is a fierce enemy of [[Gruul the Dragonkiller]] and Gruul's seven sons, and hates them deeply for killing Sabellian's own people and children.\r\nSabellian has admitted that he counts [[Rexxar]] as one of his friends, though he has not revealed to Rexxar that he is a black dragon.\r\nHe communicates regularly with [[Samia Inkling]] through [[Baron Sablemane's Blackwhelp]].\r\nSabellian wears the guise of Baron Sablemane. He is a [[quest giver]] located outside the [[Circle of Blood]] in the [[Blade's Edge Mountains]] -- the land that was created as a merger of Frostfire Ridge and Gorgrond. He assists adventurers in killing two of Gruul's sons: [[Gorgrom the Dragon-Eater]] and [[Goc]], reverting to his true [[dragon]] form and personally fighting the latter.\r\nCurrently he and the [[black dragons]] under him remain in [[Outland]]; [[Wrathion]] is unaware of their continued existence.\r\n===Exploring Azeroth===\r\nA report from [[Mathias Shaw]] mentions that the [[SI:7]] knows the true nature of Sabellian, that he is still in Outland, and actually, is not an immediate threat.\r\n==Abilities==\r\n*Chains of Ice\r\n*Fireball\r\n==Quests==\r\n*[[A Boaring Time for Grulloc]] \r\n*[[Baron Sablemane (quest)]] \r\n*[[Baron Sablemane Has Requested Your Presence]] \r\n*[[Pay the Baron a Visit]] \r\n*[[Into the Churning Gulch]] \r\n*[[Goodnight, Gronn]] \r\n*[[Baron Sablemane's Poison (quest)]] \r\n*[[It's a Trap! (quest)]] \r\n*[[Massacre at Gruul's Lair]] \r\n*[[Showdown (Alliance)]] \r\n==Quotes==\r\nGossip\r\nMy loathing of interruptions is overshadowed only by my hatred of [[Gruul the Dragonkiller]] and his seven sons!\r\nShowdown\r\n===Old God's influence?===\r\nSabellian is noticeably much less hostile than other black dragons towards non-black dragonkin, as seen how he treats the player and Rexxar (while somewhat rude, he isn't openly hostile and shows no intent to actually attack). It is possible that due to his extended period away from Azeroth (and the Old Gods) that he no longer hears the maddening whispers that plague the rest of his corrupted flight. However, [[Fahrad]] too did not show any sign of old god influence, until Wrathion forced them onto him by angering the old gods.\r\n===Relatives===\r\nWhile the lineage pictures from ''[[Thrall: Twilight of the Aspects]]'' and The Magazine #2 list him as the son of [[Deathwing]] and [[Sintharia]], ''[[Ultimate Visual Guide]]'' refers to him as the half-brother of [[Onyxia]] and [[Nefarian]]. It can be speculated that Sintharia is not Sabellian's mother, but it is said that only Sintharia could survive mating with Deathwing. Moreover, comparing the other lineages it does not seem to be true as in case of [[Malygos]]'s child, [[Balacgos]], the mother is clearly listed as unknown. It could be possible that he was born before Deathwing succumbed to the whispers of the Old Gods.",},
			["Saber"] = { content = "#redirect [[saber cat]]", redirect = "saber cat",},
			["Saber cat"] = { content = "'''Saber cats''' are a special type of large fanged cat, similar to the (now-extinct) sabertooth cats of our world. They come in a variety of colors, and have either spotted or striped coats, the striped type being the more common. [[Night Elves]] carry a special affinity for sabers, and use them as mounts, which are available for purchase in [[Darnassus]].\r\n'''Saber cats''' are proud magnificent felines have helped the night elves against foes of all sorts since Kalimdor was first settled. The great cat moves with fluid grace along the mountainsides of Kalimdor, its golden eyes gleaming with intelligence. They are intelligent and loyal when domesticated, but are feral and quite aggressive when left in their natural environments. \r\n==Nightsaber==\r\nLarge cat used as a primary [[mount]] for the [[Night elf|Night Elves]]. The Nightsaber is similar in appearance to a real-world , but is black with grey stripes or spotted like a or . The [[Frostsaber]] is a color variation of the Nightsaber - the [[Frostsaber]] is typically white with black stripes.\r\n===Combat===\r\nIn combat, the nightsaber cat is a deadly foe, leaping from the shadows to rend its foes with its fangs and claws.\r\n===Shadowmeld===\r\nA nightsaber cat is virtually invisible while under cover of darkness.\r\n===Nightsaber Mounts===\r\nNightsabers are the traditional mounts of the Sentinels, and about as common among the elves as a riding horse might be in a human city.\r\n==Frostsaber==\r\nLarge cat used as a [[mount]] for the [[Night elf|Night Elves]]. The Frostsaber is similar in appearance to a real-world , but is white with black stripes. Frostsabers can also have spots like a or . The typical Frostsaber is a color variation of the [[Nightsaber]] - the [[Nightsaber]] is black with white stripes. A variety of the Frostsaber is the purple [[Wintersaber]].\r\n===Description===\r\nFrostsabers are legendary cats native to Winterspring, and they are highly sought after by the most experienced Sentinels as mounts. The night elves view frostsabers as sacred, and treat them with more respect than almost any other creature. In recent years, with the coming of the goblins to Winterspring, frostsaber trainers have begun selling their trained mounts for the first time in history. Traditionalists view this as blasphemous, but many understand that the coin from such sales often goes to a worthy cause (and the frostsaber trainers are highly selective about just who they are willing to sell to). Frostsaber cats are intelligent and loyal when domesticated, but feral and aggressive when left in their natural environments.\r\n===Combat===\r\nThe frostsaber cat is a fearless opponent; its thick fur has the resilience to shrug off minor damage. It uses its fangs and claws against those foolish enough to engage it in melee combat.\r\n===Frostsaber Mounts===\r\nFrostsabers are difficult to train, and thus traditionally only experienced Sentinels were ever capable of convincing one to serve as a mount.\r\n==Ghost Saber==\r\n'''[[Ghost Saber]]s''' are occasionally summoned by looting [[Cat Figurine]] relics found in the [[Ruins of Mathystra]] in northern [[Darkshore]]. They have white pelts with black spots just like [[Snow Leopard]]s except they are transparent. \r\nThey can be tamed and are good choice for a unique look, appearing as if they are stealthed all the time. When truly stealthed, they become almost completely transparent. Once tamed, the Ghost Saber will die spontaneously after a few minutes. This appears to be from the pet retaining a timer it was spawned with. It appears to only happen once, after which it behaves normally. They have a 2.0 attack speed.\r\n==Wintersaber==\r\nA purple [[Frostsaber]] native to [[Winterspring]], usable as a [[mount]] by the [[Alliance]]. Requires Exalted with [[Wintersaber Trainers]] to buy the mount and [[Apprentice]] (75) [[Riding]] skill.\r\n==Corrupted Saber==\r\nThe '''Corrupted Saber''' is the form taken by a regular [[cat]] that is exposed to large quantities of [[Moonwell]] water from the corrupted Moonwell at the [[Ruins of Constellas]]. It is large and green with orange stripes, a homage to Cringer/Battlecat from the cartoon ''He-Man''. [[Winna Hazzard]], an [[Undead]] at [[Bloodvenom Post]], requests that passing by adventurers take one of her cats to the corrupted Moonwell, which is possessed by the Jadefire [[Satyr]]s, to create a corrupted saber for her use. \r\n==Epic Mount==\r\nThe epic saber mounts, also known as a [[swift saber mounts]] are bought in [[Darnassus]]. The PvP mount is the [[Black War Tiger]]. A rare epic orange saber is the [[Swift Zulian Tiger]], a rare drop from a [[Zul'Gurub]] boss.\r\n==Saber drops==\r\n*[[Nightsaber Fang]]\r\n*[[Small Furry Paw]]\r\n*[[Small Leather Collar]]",},
			["Sabotage the Warp-Gate!"] = { content = "==Objectives==\r\nEscort [[Drijya]] to the warp-gate at Invasion Point: Destroyer, and see to it that he is kept safe while he attempts to sabotage it. Then speak to [[Gahruj]] at the Midrealm Post inside Eco-Dome Midrealm in the [[Netherstorm]]. \r\n*Burning Legion warp-gate sabotaged\r\n== Description==\r\nWith the Burning Legion nearby at the fel reaver scrap field, we must do what we can to stop the flow of demons into the area.\r\nThey have a warp-gate to the south in an area that they've cleverly named Invasion Point: Destroyer.\r\nI need you to go with me to the site and keep me safe while I sabotage it.\r\nAfterward, go to the Midrealm Post to the north inside Eco-Dome Midrealm and apprise [[Gahruj]] of our success.\r\nWe're going to need a friend or two of yours along to help with this. \r\n== Reward==\r\nYou will also receive:8 gold 80 silver copper \r\n== Completion==\r\nThat is most excellent news, my friend!\r\nYou and [[Drijya]] have done us a great service. With that warp-gate out of commission, the nearby demons will not be getting any further reinforcements.\r\nPlease allow me to reward you in the proper manner of the Consortium. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*15800 [[XP]] (or 9 gold 48 silver copper at level 70)\r\n*350 [[reputation]] with [[The Consortium]]\r\n==Notes==\r\nAlthough the quest is tagged as 'group quest', it is pretty well soloable by skilled players.",},
			["Sacred Candle"] = { content = "'''Sacred Candles''' are used in rituals that will invoke the favors of the gods.\r\n==Source==\r\n'''Sacred Candles''' can be bought from Reagent Vendors world wide.\r\n==Notes==\r\n[[Priest]]s use the '''Sacred Candles''' as a reagent in the following spells:\r\n*[[Prayer of Fortitude]]\r\n*[[Prayer of Spirit]]\r\n*[[Prayer of Shadow Protection]]",},
			["Sacred Grove"] = { content = "'''The Sacred Grove''' is a hidden glade in northwestern [[Ammen Vale]]. It is inhabited by [[elemental]]s of all sorts, and is used as a test area for [[draenei]] [[shaman]]s.",},
			["Sacred Mallet"] = { content = "==Source==\r\nThis item drops from [[Qiaga the Keeper]] in [[The Hinterlands]].",},
			["Sacrolash"] = { content = "#REDIRECT [[Lady Sacrolash]]", redirect = "Lady Sacrolash",},
			["Safety is Job One"] = { content = "==Objectives==\r\nArtificer Morphalius wants you to kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers and 5 Ethereal Spellbinders.\r\nOnce that's done, find the Ethereal Transporter in the chamber before Shaffar's and activate it.\r\nKill:\r\n* 10 [[Ethereal Crypt Raider]]\r\n* 5 [[Nexus Stalker]]\r\n* 5 [[Ethereal Sorcerer]]\r\n* 5 [[Ethereal Spellbinder]]\r\n==Description==\r\nShaffar's ethereals have completely blocked us out of the Mana-Tombs. Thankfully, I've got a plan. While we can't go in through the front door, there are sure to be several transporters inside.\r\nI want you to clear the way for my crew first and then I want you to activate one of their transporters to teleport us inside.\r\nActivate the teleporter in the chamber right before Shaffar's chambers when the way has been cleared. Don't worry, I'll make it worth your while...\r\n==Completion==\r\n<You close your eyes and press a button.>\r\n==Quest Progression==\r\n* Safety Is Job One\r\n** Someone Else's Hard Work Pays Off",},
			["Sageblade"] = { content = "'''Sageblade''' is a caster blade that is crafted by highly skilled [[Blacksmithing|Swordsmiths]].\r\n==Source==\r\nSageblade is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 300. It currently does not also require Swordsmithing specialty.\r\nThe components are:\r\n*12 [[Arcanite Bar]]s\r\n*2 [[Nexus Crystal]]s\r\n*2 [[Flask of Supreme Power|Flasks of Supreme Power]]\r\n*4 [[Enchanted Leather]]s\r\nPlans: Sageblade is a [[world drop]].",},
			["Sage Korolusk"] = { content = "'''Sage Korolusk''' is a level 59 [[quest giver]] located at [[Camp Mojache]] in the [[contested]] territory of [[Feralas]].\r\nHe starts the quest Elven Legends (Horde) (Dungeon).\r\nSee [[List of Feralas NPCs]].",},
			["Sage Palerunner"] = { content = "'''Sage Korolusk''' is a level 49 sage located at [[Camp Mojache]] in the [[contested]] territory of [[Feralas]]. He may be related to [[Fera Palerunner]].\r\nSee [[List of Feralas NPCs]].",},
			["Sage Truthbearer"] = { content = "'''Sage Truthbearer''' was a [[paladin]] protecting [[King Terenas]]'s urn alongside [[Uther Lightbringer]] and [[Ballador the Bright]]. He and his [[Champions of Truth]] were slain by [[Arthas]].\r\n==Quotes==\r\n*''\"Light have mercy on you! Your betrayal has broken Uther's heart, boy. He would have given his life for yours in a second and this is how you repay his loyalty?\"''\r\n==Notes==\r\nHe could also be a random hero on other maps.",},
			["Sagra'nel"] = { content = "'''Sagra'Nel''' was a [[fel orc]] Blademaster guarding [[Magtheridon]]'s [[Black Temple|Black Citadel]] in [[Outland]]. He was killed in the assault of the Citadel orchestrated and conducted by [[Illidan]], [[Vashj]], [[Akama]], and [[Kael'thas]].\r\n==Statistics in Warcraft 3==\r\n* 725 HP\r\n* 330 MP\r\n* 30-52 hero melee damage\r\n* 6 hero armor\r\n* Attributes\r\n** 25 Strength\r\n** 28 Agility '''primary attribute'''\r\n** 22 Intelligence\r\n* Abilities\r\n** Critical Strike (chance to critical hit)\r\n** Mirror Image (create illusions of self)\r\n** Whirlwhind (Blademaster spins around for huge damage)\r\n** Windwalk",},
			["Sahaak"] = { content = "'''Sahaak''' is a level 70 specialty goods [[vendor]] located in a building on the island in [[Blackwind Lake]] in the [[contested]] territory of [[Terokkar Forest]]. To be able to buy and trade with Sahaak, you need to do the quest [[Quest:A Shabby Disguise|A Shabby Disguise]]. You will be required to get an [[arakkoa]] disguise. \r\nSee [[List of Terokkar Forest NPCs]].",},
			["Sahaak"] = { content = "'''Sahaak''' is a level 70 specialty goods [[vendor]] located in a building on the island in [[Blackwind Lake]] in the [[contested]] territory of [[Terokkar Forest]]. To be able to buy and trade with Sahaak, you need to do the quest [[Quest:A Shabby Disguise|A Shabby Disguise]]. You will be required to get an [[arakkoa]] disguise. \r\nSee [[List of Terokkar Forest NPCs]].",},
			["Saidan Dathrohan"] = { content = "'''Saidan Dathrohan''' was one of the first [[Knights of the Silver Hand]], and subsequently Grand Crusader of the [[Scarlet Crusade]]. He was later killed by [[Balnazzar]], in order for the demon to possess his corpse.\r\n==Conflict with Fordring==\r\nFollowing the [[Second War]], Dathrohan was called to [[Mardenholde]] to witnessed [[Fordring]]'s exile for his crime, and the supposed draining of his powers of the [[Holy Light]].\r\n==The Grand Crusader==\r\nDuring an assault on the Scourge-held city of [[Stratholme]], Dathrohan was separated from the other fromer knights of the Silver Hand and captured by the [[Dreadlord]] [[Balnazzar]]. Balnazzar killed him and possessed his corpse, his powerful magic sustaining the former paladin's body. In his new guise, he helped found the [[Scarlet Crusade]] along with [[Isillien]], the [[Abbendis]]es, and the [[Mograine]]s. Not long after, the paladin Saidan Dathrohan became Grand Commander Dathrohan. Once [[Highlord Mograine]] was murdered, he became the head of the Scarlet Crusade, Balnazzar used Dathrohan's form to slowly transform the Crusade into a paranoid regime. From the [[Scarlet Bastion]] in the ruins of Stratholme, he directly leads a group of warriors known as the [[Crimson Legion]] and manipulates the two supreme chiefs of the Crusade, [[Isillien]] and [[High General Abbendis (daughter)|Abbendis]].\r\n==Notes==\r\nSaidan Dathrohan is described as helping found the crusade. The \"Grand Crusader\" (who is not mentioned by name), appears to have come after the Crusade's founding, as indicated [[High Inquisitor Fairbanks]]. Dark Factions clarifies that Saidan was only a paladin when he helped form the Crusade, but later was promoted to Grand Crusader. So indeed the Grand Crusader did come after the founding, though Saiden was around before he became the Grand Crusader.\r\n==Failed Assault on Naxxramas==\r\nSeveral items that drop within [[Naxxramas]] bear the title \"Grand Crusader,\" such as [[Belt of the Grand Crusader]], [[Leggings of the Grand Crusader]], and [[Spaulders of the Grand Crusader]]. This hints that Balnazzar may have at one time attempted to raid Naxxramas together with his Crimson Crusaders, but was repelled by the servants of [[Kel'Thuzad]], who claimed parts of his armor in the process. It is quite possible that it was during this encounter that Balnazzar struck the deal with Kel'Thuzad in order to get rid of Highlord Mograine, at the same time securing his own survival.",},
			["Sailing Ship"] = { content = "#REDIRECT [[Sailing ship]]", redirect = "Sailing ship",},
			["Sailor"] = { content = "'''Sailor''' is a [[crafts and professions (RPG)|profession]] in the [[Warcraft RPG]].\r\nThe term \"sailor\" generically refers to those who sail the seas of Azeroth and their practices range from benign to despicable. [[Human]]s are well known for their sailing prowess, but many races have proficiency on the waters of [[Azeroth]].\r\nThe basic sailor, sometimes called a [[crewman]], performs all the basic duties aboard ship that usually don't involve cooking food or maintaining machines aboard. The head cook on a ship is usually called the [[galley chief]]. The [[engineer]] maintains machines and mechanisms. The leaders of most sailors and the boats they serve on are called [[captain]]s. The more skilled among them are usually called [[mate]]s and [[navigator]]s who serve their captain and act as the captain's lieutenants. The second in command is usually called \"first mate\". Often ships carry soldiers called [[marine]]s who specialize in battle at sea or from a ship. Marines may or may not have specific sailing skills.\r\nSailor and crewman are a neutral terms, whereas [[buccaneer]], [[freebooter]], and [[pirate]] tend to have negative connotations.\r\n==Sailors in World of Warcraft==\r\nThis is a partial list of known sailors:\r\n*Cursed Sailor\r\n*Alliance\r\n*Sailor Fairfolk\r\n*Sailor Henders\r\n*Sailor Melinan\r\n*Sailor Stoneheel\r\n*Sailor Vines\r\n*Sailor Wicks\r\n*Sailor Wills",},
			["Sailor Fairfolk"] = { content = "'''Sailor Fairfolk''' is a member of the crew of [[the Bravery|the ''Bravery'']], the boat that runs between [[Stormwind Harbor]] and [[Auberdine]]. Almost jealous of how [[First Mate Wavesinger|Wavesinger]] looks, she's worried he might be prettier than she is.",},
			["Sailor Henders"] = { content = "'''Sailor Henders''' is a member of ''[[Lady Mehley]]'', the boat that runs between [[Theramore Isle]] and [[Menethil Harbor]].",},
			["Sailor Stoneheel"] = { content = "'''Sailor Stoneheel''' is a member of the crew of [[the Bravery|the ''Bravery'']], the boat that runs between [[Stormwind Harbor]] and [[Auberdine]]. She's not afraid to ask you if you think she has an unlucky name for a sailor.",},
			["Sailor Vines"] = { content = "'''Sailor Vines''' is a member of ''[[Lady Mehley]]'', the boat that runs between [[Theramore Isle]] and [[Menethil Harbor]]. Nervous about being caught talking to ya by [[First Mate Kowalski|Kowalski]], she'll quickly tell ya to be on your way.",},
			["Sailor Wicks"] = { content = "'''Sailor Wicks''' is a member of ''[[Lady Mehley]]'', the boat that runs between [[Theramore Isle]] and [[Menethil Harbor]]. Thinks the captain works them hard, but knows he a good captain.",},
			["Sailor Wills"] = { content = "'''Sailor Wills''' is a member of the crew of [[the Bravery|the ''Bravery'']], the boat that runs between [[Stormwind Harbor]] and [[Auberdine]]. He's the oldest member of the crew, but also the toughest, just look at those arms.",},
			["Salamander"] = { content = "There is more than one type of creature called a '''salamander''' or '''fire salamander''' on [[Azeroth]].\r\n[[Flamewaker]]s are not to be confused with salamanders (even if they drop [[Cape of the Fire Salamander]] and [[Salamander Scale Pants]]) nor [[diemetradon]].\r\n==Third War==\r\nSalamanders are subterranean beasts that share a common ancestry with the mighty [[kodo beast]]s. However, they have adapted to life beneath the earth by evolving a number of natural defenses and abilities.\r\n*[[Salamander Hatchling]]\r\n*[[Salamander (Warcraft III)|Salamander]]\r\n*[[Salamander Vizier]]\r\n*[[Salamander Lord]]\r\n*[[Salamander (campaign)|Draenei Salamander]]\r\n===Behavior===\r\nA salamander typically bites or claws its prey. If a salamander is beset with superior opposition, it will attempt to keep them at bay with its breath weapon. Since they are not fast enough to run down prey, salamanders will also use their breath weapon to cook fleeing prey. Such cooked prey lasts longer than fresh kills, and salamanders seem to know instinctively to save such pre-cooked meals for a time when they are hungry. When not in combat, they tend to spend their time lying still, in wait for prey.\r\n===[[Elemental]]===\r\nThe salamander are one of the types of the elemental kin and can be found in different levels of strength in the [[Elemental Plane]]. They are found in the [[Firelands|fire domain]]. Noble salamanders can be summoned by druids as nature's allies.\r\nThese type of [[Manual of Monsters/Appendix Three|salamanders]] are fully described in [[Manual of Monsters/Appendix Three|Appendix Three]] of ''[[Manual of Monsters]]'', however the validity of the source is disputed.",},
			["Salamander (campaign)"] = { content = "The '''Draenei Salamander''' is a [[Draenei]] unit that helped kill the [[Fel Orc]]s when [[Illidan]] was closing the [[Dark Portal]]s in [[Outland]] to prevent [[Magtheridon]]'s [[demon]]s from getting through. They are trained at the [[Draenei Barracks]]. They are found in Warcraft III Frozen Throne Expansion Human Campaign.\r\n==Statistics from Warcraft III==\r\n* 625 HP\r\n* 33-40 piercing ranged damage\r\n* 1 medium armor\r\n* Abilities\r\n** Lightning Attack (slows enemy unit and does not cost mana)",},
			["Salamander Scale Pants"] = { content = "'''Salamander Scale Pants''' are leather leg armor with [[intellect]], [[stamina]] and [[Fire Resistance| fire resistance]]. They increase healing done by spells and restore mana every five seconds. These pants are definitely more competitive than [[Cenarion Leggings]], and are regarded to be very slightly better than [[Stormrage Legguards]] (situationally).\r\n=Source=\r\nSalamander Scale Pants drop off [[Lucifron]], [[Gehennas]], [[Shazzrah]], and [[Sulfuron Harbinger]] in the [[Molten Core]].",},
			["Salanar the Horseman"] = { content = "He is involved in the following quests:\r\n#Grand Theft Palomino\r\n#Into The Realm of Shadows",},
			["Salandria"] = { content = "'''Blood Elf Orphan''' is a level 1 quest giver located in the [[Lower City]] in the [[neutral]] [[Shattrath City]].\r\nHer name is '''Salandria''', and apparently has the potential to become a Blood Knight in Silvermoon's service. She is also a huge fan of the Tauren Chieftains, and aspires to be a rock star.\r\nShe is available only during [[Children's Week]]. To summon the orphan, the adventurer gets a whistle from [[Orphan Matron Mercy]] as part of the [[Quest:Children's Week|Children's Week]] quest.\r\nShe starts the following quests:\r\n* Hch'uu and the Mushroom People ([[Children's Week]])\r\n* A Trip to the Dark Portal ([[Children's Week]])\r\n* Visit the Throne of the Elements ([[Children's Week]])\r\n* Now, When I Grow Up... ([[Children's Week]])\r\n* Time to Visit the Caverns (Horde) ([[Children's Week]])\r\n* Back to the Orphanage (Horde) ([[Children's Week]])\r\nSee [[List of Shattrath City NPCs]].\r\n==Quotes==\r\n* \"I bet Illidan is a nice guy underneath. He just needs a mama, too.\"\r\n* \"I bet ice cream would taste better if it were socketed!\"\r\n* \"If the demons fell, where did they fall from?\"\r\n* \"Would a tauren paladin be a holy cow?\"\r\n* \"Boys have cooties and girls have beauty!\"\r\n* \"Does this dress make me look fat?\"\r\n* \"I think I need a bath. *sniff* I think you need one, too!\"\r\n* \"Are we there yet?\"\r\n==Future?==\r\n \r\nDuring the quest chain, the guards at the Caverns of Time attack her, only to be stopped by [[Zaladormu]], who says she will not be punished for \"things she might do or fail to do in the future\". She also says when she get's the [[Toy Dragon]] \"Someday I plan to own a real one.\"\r\nIn [[Wrath of the Lich King]] you can [[fish]] up an item in [[Dalaran]] called Salandria's (The Blood Elf Orphans name) Shiny Copper Coin, with the flavor text \"Someday, I'm gonna be more powerful than all of these mages!\"\r\nIt is possible, due to these things, that Salandria, may in fact, grow up to kill Zaladormu, and enslave the Bronze Dragonflight. It is theorized by many fans that she will be the villain of a future game or expansion pack.",},
			["Saldean's Farm"] = { content = "'''Saldean's Farm''' is unique in [[Westfall]] in that it is the only farm that has not been completely taken over by the [[Defias Brotherhood]]. Though Defias [[harvester]]s roam the fields, Farmer Saldean and his wife have stubbornly refused to leave. Both Farmer Saldean and his wife offer a quest, and Farmer Saldean further aids adventurers by selling basic supplies to those in need.",},
			["Saldor Shallowbrook"] = { content = "'''Saldor Shallowbrook''', was an aged, placid [[high elf]]. He oversaw the [[Quel'Danil Lodge]] in the [[Hinterlands]]. His whereabouts are currently unknown.",},
			["Salfa"] = { content = "'''Salfa''' is a level 55 [[quest giver]] located by the entrance to [[Timbermaw Hold]] in the [[contested]] territory of [[Winterspring]].\r\nSalfa has the following quests available which increase Timbermaw faction:\r\n* Beads for Salfa (Repeatable)\r\n* Winterfall Activity\r\n* Winterfall Activity\r\nSee [[List of Winterspring NPCs]] and the [[Timbermaw Hold reputation guide]].",},
			["Sally Whitemane"] = { content = "'''High Inquisitor Sally Whitemane''' is a level 40 [[elite]] [[human]] [[boss]] found in the [[Scarlet Monastery]]'s Cathedral. Whitemane, a [[priest]]ess of the Light, leads the activities in the Scarlet Monastery.\r\n==Lore==\r\nThe Monastery was once a proud bastion of [[Lordaeron]]'s priesthood - a center for learning and enlightenment. However, with the rise of the [[undead]] [[Scourge]] during the [[Third War]], the peaceful Monastery was converted into a stronghold of the fanatical [[Scarlet Crusade]]. Under Whitemane's command, the members of the Scarlet Crusade have become ever more extreme in their battle against the Scourge. Their grasp on reality was slipping and as time moved on, Whitemane and her followers no longer trusted anyone that was not part of their own Scarlet Crusade, considering them plagued. Large numbers of innocent men and women were tortured and eventually killed because of this. \r\nIt is known that both [[Raleigh the Devout]] in the [[Hillsbrad Foothills]] and [[Varimathras]] in the [[Undercity]] are determined to eliminate the leadership of the Scarlet Monastery, albeit for different reasons. The [[dreadlord]] of the [[Forsaken]] wishes to end the continued threat of the Scarlet Crusade so close to his capital and the [[human]] in [[Southshore]] believes the only way the Scarlet Crusade can be brought back to its original purpose is to remove the corrupted leaders.\r\nThe young Sally Whitemane can be seen playing with her friends in the town of [[Southshore]] in the [[Old Hillsbrad Foothills]] instance in the [[Caverns of Time]].\r\n==Combat info==\r\nBefore the High Inquisitor enters the fight, players will first have to defeat [[Scarlet Commander Mograine]]. The second he falls down Whitemane will emerge from the room behind the altar and immediately join the battle. Note that like most bosses she is immune to [[stun]] effect. If kept in combat long enough, she will [[mind control]] a random party member.\r\nWhen she has about 50% health left she will shield herself, [[Sleep Effect|sleep]] the entire party, and begin to resurrect the Scarlet Commander. Before the sleep spell wears off she will heal Mograine to full health and he will use a Lay on Hands on her, so they will both be at 100% HP when you wake up. A common tactic is to then remain focused on killing Whitemane before dealing with Mograine again.\r\n==Spells and Abilities==\r\n*[[Smite]]\r\n*[[Mind Control]]\r\n*[[Power Word: Shield]]\r\n''Scripted abilities''\r\n*Deep Sleep (All enemies are put to sleep for 8 seconds.)\r\n*Scarlet Resurrection (2 second cast resurrection spell.)\r\n*Heal (Instant cast heal that heals 100% health and mana.)\r\n==Quotes==\r\n'''Intro''' ''Mograine has fallen? You shall pay for this treachery!''\r\n'''Killing A Player''' ''The light has spoken!''\r\n'''Resurrect''' ''Arise, my [[Renault Mograine|champion]]!''\r\n==Quests==\r\n*In the Name of the Light\r\n*Into the Scarlet Monastery",},
			["Salome"] = { content = "'''Salome''' is a level 1 [[housecat]] located at [[Ravenholdt Manor]] in the [[contested]] territory of [[Alterac Mountains]]. She seems to belong to [[Smudge Thunderwood]].",},
			["Salramm the Fleshcrafter"] = { content = "'''Salramm the Fleshcrafter''' is a [[necromancer]] and the second boss of the [[Culling of Stratholme]]; an instance introduced in [[Wrath of the Lich King]].\r\n==Quotes==\r\nSpawn:\r\n*You are too late, champion of [[Lordaeron]]. The dead shall have their day.\r\nAggro:\r\n*Ah, the entertainment has arrived!\r\nExplode ghouls:\r\n*BOOM! Hahahahah...\r\n*Blood... destruction... EXHILARATING!\r\nSteal flesh:\r\n*I want a sample...\r\n*Such strength... it must be mine!\r\n*Your flesh betrays you.\r\nSummon ghouls:\r\n*Say hello to some friends of mine.\r\n*Come, citizen of [[Stratholme]]! Meet your saviors.\r\nSlay:\r\n*The fun is just beginning!\r\n*Aah, quality materials!\r\n*Don't worry, I'll make good use of you.\r\nDeath:\r\n*You only advance... the master's plan...",},
			["Salthem"] = { content = "#REDIRECT [[Blizzard forum posters]]", redirect = "Blizzard forum posters",},
			["Saltheril's Haven"] = { content = "'''Saltheril's Haven''' is a small enclave hosted by [[Lord Saltheril]], a man who likes to throw elaborate parties in spite of the imminent threat of the [[Scourge]]. Saltheril is always happy to give invitations to his party table for those who can help him get supplies for his parties. (5-10 Quest NPC area.)\r\nAmong his party guests are two notables. [[Magistrix Eredania]], who is happy to instruct newcomers to the mystical world of [[enchanting]], and [[Botanist Tyniarrel]], who likes to show off his knowledge of native flora.",},
			["Saltspray Glen"] = { content = "'''Saltspray Glen''' is a small area in the northwestern [[Wetlands]] bordered by [[Bluegill Marsh]] to the south, [[Ironbeard's Tomb]] to the east, and [[Baradin Bay]] to the north and west. Like [[Black Channel Marsh]], [[Whelgar's Excavation Site]], and [[Raptor Ridge]], Saltspray Glen is crawling with the numerous [[raptor]]s who nest here. The glen is so named for the ease with which the ocean throws seawater inland here when there is a strong wind blowing off from the bay.",},
			["Saltstone Basilisk"] = { content = "'''Saltstone Basilisk''' can be found in [[Thousand Needles]] .\r\n==Quests== \r\n==Drops == \r\n \r\n0.05% Chance of a [[rare]] drop.\r\n0.41% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\n0.01% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Saltstone Crystalhide"] = { content = "'''Saltstone Crystalhide''' can be found in [[Thousand Needles]] .\r\n==Quests== \r\n==Drops == \r\n \r\n0.05% Chance of a [[rare]] drop.\r\n0.47% Chance of an [[Uncommon]] drop.\r\n0.01% Chance of a [[common]] drop.\r\n0.01% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Saltstone Gazer"] = { content = "'''Saltstone Gazer''' can be found in [[Thousand Needles]] .\r\n==Quests== \r\n==Drops == \r\n \r\n0.05% Chance of a [[rare]] drop.\r\n0.68% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\n0.02% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Salty Sailor Tavern"] = { content = "The '''Salty Sailor Tavern''' is an inn located in [[Booty Bay]].\r\nNPCs located here:\r\n*[[Deeg]]\r\n*[[Catelyn]]\r\n*[[Whiskey Slim]]\r\n*[[Ian Strom]]\r\n*[[Skindle]]\r\n*[[Nixxrax Fillamug]]\r\n*[[Crank Fizzlebub]]\r\n*[[Krazek]]\r\n*[[Kebok]]",},
			["Salt Flats Scavenger"] = { content = "A level 30-32 carrion bird native to Thousand Needles. Wild Salt Flats Scavengers have a heavily damaging [[Execute]] ability much like a warrior's.",},
			["Salt Flats Vulture"] = { content = "A level 32-34 Carrion Bird native to Thousand Needles.",},
			["Salt Shaker"] = { content = "==Source==\r\nA Salt Shaker is crafted by [[Engineers]] with a skill of 250.\r\nMaterials required\r\n* 1x Mithril Casing\r\n* 6x Thorium Bar\r\n* 1x Gold Power Core\r\n* 4x Unstable Trigger\r\n==Use==\r\nThis item is used by [[Leatherworking|Leatherworkers]] to create Refined Deeprock Salt which is used to cure Rugged Hide into Cured Rugged Hide.\r\nThe item has a two day [[cooldown]] after being used.",},
			["Salvation"] = { content = "#REDIRECT [[Hand_of_Salvation]]", redirect = "Hand_of_Salvation",},
			["Samedi"] = { content = "'''Samedi''' is the [[Loa]] of cemeteries and the restful sleep of the dead. In Samedi’s eyes, the undead are abominations that should be destroyed.",},
			["Samia Inkling"] = { content = "'''Samia Inkling''' is a level 68 [[quest giver]] located at [[Evergrove]] in the [[contested]] territory of [[Blade's Edge Mountains]].\r\nShe starts the following quests:\r\n* Poaching from Poachers\r\n* Whelps of the Wyrmcult\r\nIt is hinted in Whelps of the Wyrmcult that she may be [[dragonkin]], if not a [[black dragon]], trying reestablish the brood after [[Gruul the Dragonkiller]]'s massacre.\r\nSee [[List of Blade's Edge Mountains NPCs]].",},
			["Samophlange"] = { content = "==Objectives==\r\nAccess the control console at the Venture Company research site.\r\n*[[Control Console Operating Manual]] (provided)\r\n==Description==\r\nThe [[Venture Company]] set up a small research facility far to the north of here, southwest of the [[Sludge Fen]]. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"[[:samophlange]]\".\r\nNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.\r\nI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.\r\n==Rewards==\r\nYou will receive:\r\n* 740 [[XP]]\r\n* +75 reputation with [[Ratchet]]\r\n*75 or +150 [[reputation]] with [[Ratchet]]\r\n==Completion==\r\nA variety of buttons, levers and blinking lights are somewhat erratically arrayed on the face of the control console. A small gauge indicates that the apparatus is currently operating within optimal levels, and indicates that control valves one through three are currently open. There is a small keyhole set into the lower right side of the control panel.",},
			["Samuel Wrenchwright"] = { content = "'''Samuel Wrenchwright''' was a popular member of the [[Tinkers' Union|Tinker's Guild]] in [[Ratchet]]. The first [[tinker]]s arm was created for him by the Guild, when he lost a limb in an accident. When others saw that Wrenchwright had not only gained a useful limb but also increased strength, they asked the tinkers to develop a version that might be used without the loss of a living arm.",},
			["Samul Strangehands"] = { content = "'''Samul Strangehands''' is one of [[Brann Bronzebeard]]'s mentors, who later joined him in founding the [[Explorers' Guild]].\r\n\"An experienced veteran of the [[First War|First]] and [[Second War]]s, by avocation Samul is a renowned stonecarver and sculptor who gained a taste for the outdoors wandering the mountains of [[Khaz Modan]] in search of raw material for his statues. Always trying to evoke the fiery spirit of his people in his art, he was fascinated to discover that the titans may have lit that spark long ago. In search of the truth, he was among those who founded the Explorer’s Guild to go in search of titan artifacts that might uncover the heritage of the dwarven race. Though Samul is a trusted advisor to the [[High Explorer]], he is content to keep the simple title of 'Prospector' and mentor many young explorers.\"\r\nA quote by him is carved into the wall of the [[Explorers' Guildhall]]:\r\n''The most useful souvenir a traveler can pick up in a foreign land is its tongue''",},
			["Samwise"] = { content = "#redirect [[Samwise Didier]]", redirect = "Samwise Didier",},
			["Samwise Didier"] = { content = "'''Sam 'Samwise' Didier''' is the art director at [[Blizzard Entertainment]]. Among the veteran Blizzard employees, Samwise Didier has been a consistent artist for many years, and recently his style has been the artistic direction of choice for all Blizzard franchises.\r\nDidier's greatly exaggerated physiques and vibrant, bright color palette has dictated the artistic style of [[Warcraft III]], [[World of Warcraft]], and even the now defunct [[wikipedia:StarCraft: Ghost|StarCraft: Ghost]]. Didier has also designed and drawn many of the graphical icons found in Warcraft III and World of Warcraft, and even provided some for both.\r\nSamwise is the frontman of [[Level 80 Elite Tauren Chieftain]], the band of Blizzard employees that played at [[BlizzCon]] and the 2008 edition of [[WWI]].\r\nAway from Blizzard, Samwise is responsible for much of the album art of Swedish power metal band [[wikipedia:HammerFall|HammerFall]].\r\n''\"Basically, he's a WoW icon in every sense of the word.\"'' ([[Mike Schramm]])\r\n==Personal touches==\r\nDidier has a heavy fixation on pandas, which he explains in the , among other things;\r\n''\"... for some reason, I decided to do like a panda guy because, actually, also like “Samwise,” “Panda” is my nickname because I’m kind of a big hairy bear dude, but I’m not very fearsome. <Laughs> So I got the nickname “Panda.”\"''\r\nThrough this personal link, Didier became responsible for the creation of the [[pandaren]], a race originally regarded by fans — and used by Blizzard — as a \"joke race\", but still with legitimacy within the lore. Among other things, panda icons also appeared accompanying much of Samwise's art, and could be seen in Warcraft III as the emblem adorning night elf demon hunters' warblades. Much of the pandaren culture, dress, society, and weapons were inspired by samurai and Hong Kong martial arts films, both of which Didier greatly appreciates.\r\n* '''[[Warcraft II]]''' - a random [[doodad]] is the name \"Sam\" scrawled in the dirt.\r\n* '''Warcraft III''' - when certain paladins cast spells they open their books to do so. Upon inspection, the interior of these books read \"Sam\" on a page. \r\n* '''Warcraft III''' - an in-game cube skin unused by any unit in game has Samwise's face on all sides, named \"Sammy!\".\r\n* '''Warcraft III''' - Samwise's face is used as an icon and unit model that can be accessed from WorldEditor. The model is a cube with his face on the faces.\r\n* '''Warcraft III''' - Samwise's face was also used on a kobold model in the world editor..\r\n* '''Warcraft III''' - the ashes that form after the usage of the Blood Mage's Flame Strike ability has a pattern of a panda's face.\r\n* '''Warcraft III and World of Warcraft''' - several classy items in both games have an icon depicting a sceptre with a decorative \"SD\" likely standing for Samwise Didier.\r\n* '''World of Warcraft''' - his face is also seen in as an icon for spells and abilities that do not have an image associated with them (see top left). For instance, several spells cast by quest givers use this icon. Since they are not 'real' spells, they use this as the icon. They can be visible if you turn on \"Show Enemy Spellcast Bar\" and target the NPC during casting.",},
			["San'layn"] = { content = "'''The San'layn''' is a [[faction]] of [[darkfallen]], renegade elves from [[Quel'Thalas]] under the rule of the [[Lich King]]. The San'layn in particular appear to be a group of elven princes.\r\n==Known Members==\r\n*[[Darkfallen Bloodbearer]] - Retainers of Prince Valanar.\r\n*[[Darkfallen Deathblade]] - Retainers of Prince Valanar.\r\n*[[Luthion the Vile]] - One of Prince Valanar's lieutenants.\r\n*[[Prince Atherann]] - Took part in the ritual to raise [[Archmage Arugal|Arugal]].\r\n*[[Prince Keleseth]] - Overlord of [[Howling Fjord]] and ambassador to the [[vrykul]].\r\n*[[Prince Navarius]] - Resides in [[Zul'drak]].\r\n*[[Prince Sandoval]] - Resides in [[Icecrown Citadel]] and challenges fighters to battle at [[Valhalas]].\r\n*[[Prince Taldaram]] - Boss in [[Ahn'kahet]], presumably a leader of [[Scourge]] forces attempting to conquer [[Azjol-Nerub]].\r\n*[[Tenris Mirkblood|Prince Tenris Mirkblood]] - Resides in [[Karazhan]] during the [[Scourge Invasion|Second Scourge Invasion]] prior to the release of Wrath of the Lich King.\r\n*[[Prince Theraldis]] - Led the ritual to raise Arugal.\r\n*[[Prince Valanar]] - Overlord of [[Borean Tundra]] and master of [[Naxxanar]].\r\n*[[Vanthryn the Merciless]] - One of Prince Valanar's lieutenants.",},
			["Sanctified Crusader"] = { content = "'''Sanctified Crusader''' was a talent in the Retribution tree, you would need to spend 33 points in Retribution to max it.\r\nIn [[Patch 2.3]], this talent was renamed to [[Sanctified Seals]] and improved.\r\n==Notes==\r\nA good talent which increases your chance to make a critical strike. But it also increases critical chance for all others players and for all attacks, physical or magic. A very good \"buff\" in PvE for the raid.",},
			["Sanctified Judgement"] = { content = "==Overview==\r\nSanctified Judgement is a talent in the Retribution tree, you will need to spend 28 points in Retribution to max it.\r\n==Notes==\r\nExcellent talent for increasing mana efficiency for PvE grinding. A must have for long boss fights.\r\nIn PvP, this greatly reduces the cost of [[Judgement]], giving you much higher mana efficiency in long fights where mana might usually be a problem. \r\nIn the PTR version of Patch 2.3.2 the talent was reworked, now returning 80% of the Seal's mana cost, increased from 50%.",},
			["Sanctified Light"] = { content = "'''Sanctified Light''' is a talent in the Holy tree, you will need to spend 23 points in Holy to max it.\r\n==Rank table==\r\n==Talent Overview==\r\n*Improves the [[critical|crit]] chance of the Paladin's [[Holy Light (ability)|Holy Light]] and [[Holy Shock]] spells.",},
			["Sanctified Retribution"] = { content = "==Rank table==\r\n==Notes==\r\n2% more damage for 1 point, it's a \"must have\".",},
			["Sanctified Seals"] = { content = "'''Sanctified Seals''' is a 15 point [[retribution]] talent with 3 ranks that increases your chance to [[critical]]ly hit with all [[spell]]s and [[melee]] by 1/2/3%.\r\nIn [[Patch 3.1]], this talent was renamed to [[Sanctity of Battle]] and improved.",},
			["Sanctity Aura"] = { content = "''As per its benevolent nature, the Light readily heals and eases suffering with great effectiveness. It takes focus and determination to use it as a weapon against living things. Knowing this, the Crusader may focus his mind away from defense and into offense to amplify his power.''\r\n==Notes==\r\nSanctity Aura is a talent in the Retribution tree; you will need to spend 21 points in Retribution to learn it. It is a staple of the Retribution specialization due to the offensive, DPS nature of the spec. Its presence typically indicates that the paladin is primarily oriented towards dealing damage and enhancing his party's as well, becoming something of a \"combat buffer\".\r\n==Talent improvement==\r\n[[Improved Sanctity Aura]] increases damage of anyone affected by the aura by 1%/2%. This includes physical as well as Holy damage. This is a base change to melee damage and an end-damage amplification to spells. (Note: Prior to Patch 2.1.0 this instead gave a 3%/6% bonus to healing done to party members.)\r\n==Tips and tactics==\r\nSanctity Aura is, for obvious reasons, ''the'' ret-spec aura and part of what separates ret pallies from the other specs. With the Improved Sanctity Aura talent, it benefits all other damage-dealing classes as well.\r\nSanctity Aura is very useful for shockadins (40/0/21 build), because it increases their Holy Shock and Seal of Righteousness damage by 10%.\r\nPaladin tanks also like Sanctity Aura in their group, as it helps their threat generation enormously.",},
			["Sanctuary"] = { content = "A '''sanctuary''' is a type of territory, seen in the [[Burning Crusade]] expansion, in which all PvP combat is prohibited. \r\n==Known Sanctuaries==\r\n*[[Stair of Destiny|The Stair of Destiny]], [[Hellfire Peninsula]]\r\n*[[Shattrath City]]\r\n*[[Acherus: The Ebon Hold]], [[Eastern Plaguelands]]\r\n*[[Dalaran]]",},
			["Sanctum"] = { content = "A '''sanctum''' is a structure in the [[Warcraft universe|''Warcraft'' universe]]. There are numerous locations named such:\r\n*[[Sanctum (Stromgarde Keep)|The Sanctum]], the church in the ruined city of [[Stromgarde Keep|Stromgarde]].\r\n*[[Sanctum (Silvermoon City)|The Sanctum]], [[warlock]] headquarters in [[Silvermoon City]].\r\n*[[Sanctum of Light|The Sanctum of Light]], [[paladin]]s' [[Class Hall|order hall]] beneath [[Light's Hope Chapel]].\r\n*[[Arcane sanctum]]s, a type of building introduced in ''[[Warcraft III: Reign of Chaos|Warcraft III]]''.\r\n**[[East Sanctum]]\r\n**[[North Sanctum]]\r\n**[[West Sanctum]]\r\n**[[Sanctum of the Moon]]\r\n**[[Sanctum of the Sun]]\r\n*The [[Obsidian Sanctum]]\r\n*The [[Sanctum of the Sages]], a [[portal room]] in [[Boralus]].\r\n*[[Covenant Sanctum]]s, the places of the four [[Covenant]]s in ''[[World of Warcraft: Shadowlands|Shadowlands]]''.\r\n*[[Sanctum of Domination]], a location and raid instance within [[Torghast]].\r\nThere are also several [[Inner Sanctum]]s.\r\n==See also==\r\n*[[Sanctum (Azerite trait)]], a priest [[Azerite trait]].",},
			["Sanctum (Stromgarde Keep)"] = { content = "'''The Sanctum''' is a church found inside [[Stromgarde Keep]]. It is currently under control of the [[Alliance]], and is the residence of [[Galen Trollbane]].",},
			["Sanctum of the Moon"] = { content = "The '''Sanctum of the Moon''' is located just to the west of [[Tranquillien]]. It has been overrun with arcane elementals and [[Mana Wyrm]]s, and has been partially destroyed. An ideal hunting area level 10-15 adventurer.",},
			["Sanctum of the Stars"] = { content = "'''Sanctum of the Stars''' is a [[Scryers]]-only base located in southeastern [[Shadowmoon Valley]] .\r\nIt contains several [[vendor]]s and [[quest giver]]s, as well as an [[innkeeper]] and a [[flight master]].\r\n===Flight===\r\n [[Wildhammer Stronghold]]\r\n [[Shadowmoon Village]]",},
			["Sanctum of the Sun"] = { content = "The '''Sanctum of the Sun''' is located to the southeast of [[Tranquillien]], still in working order, and the magisters who are tending to it give a number of level 15-20 tasks related to saving the [[Ghostlands]] from the [[Scourge]] and other invaders, including the [[Night elves]]. The building is guarded by a few [[Ghostlands Guardian]]s.\r\nBehind the building, there is a secret passage through the mountains to [[Tranquillien]], which saves a lot of time when travelling between the two areas.\r\n==Occupants==\r\n* Arcanist Janeda\r\n* Magister Idonis\r\n* Magister Kaendris\r\n* Magister Quallestis",},
			["Sandfury Acolyte"] = { content = "'''Sandfury Acolyte''' can be found in [[Zul'Farrak]].",},
			["Sandfury Executioner"] = { content = "The '''Sandfury Executioner''' is a level 46 [[elite]] [[troll]] found in [[Zul'Farrak]]. He waits with the prisoners atop the Pyramid. The executioner has a potent cleave attack but otherwise is not particularly dangerous.\r\n==Quotes==\r\n'''Aggro''' ''Let the executions begin.''\r\n'''Killing A Player''' ''Justice is done.''\r\n==Loot==\r\n*Executioner's Key ''(used to release the prisoners and start the Pyramid event)''",},
			["Sandreaver"] = { content = "#redirect [[Sand reaver]]", redirect = "Sand reaver",},
			["Sandsorrow Watch"] = { content = "'''Sandsorrow Watch''' is an area of Tanaris heavily populated by [[Sandfury trolls]] (previously [[elite]] until [[Patch 2.3]]). Their dwellings and powerful soldiers dot the landscape.",},
			["Sands of Nasam"] = { content = "''Not to be confused with [[Plains of Nasam]], also in Borean Tundra.''\r\nThe '''Sands of Nasam''' are a beach area outside [[Valiance Keep]] in the [[Borean Tundra]]. The region is infested with undead nerubians, primarily [[Crypt Crawler]]s and [[Risen Crypt Lord]]s.",},
			["Sand Crawler"] = { content = "'''Sand Crawlers''' are level 13-14 [[crab]]s native to [[Westfall]].",},
			["Sand reaver"] = { content = "A '''sand reaver''' is a creature that resembles a camel spider or wind scorpion. Not much is known about them, but they are found in areas infested by the Silithid. They can only be found in [[Ahn'Qiraj]]. Kurinnaxx, a boss in the [[Ruins of Ahn'Qiraj]] is a sand reaver, as is Fankriss the Unyielding from the [[Temple of Ahn'Qiraj]].\r\n==Famous/Named==\r\n*[[Kurinnaxx]]\r\n*[[Fankriss the Unyielding]]",},
			["Sand Shark"] = { content = "'''Sand Shark''' can be found in [[Durotar]] and [[The Barrens]].\r\n==Drops == \r\n \r\n15.22% Chance of an [[Uncommon]] drop.\r\n2.17% Chance of a [[common]] drop.\r\n4.35% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Sand troll"] = { content = "#redirect [[Sandfury troll]]", redirect = "Sandfury troll",},
			["Sand worm"] = { content = "Little is known about the '''sand worms'''. They are [[worm]]-like creatures with burrowing claws growing from the upper body. These enable the beasts to dig through most kinds of soil with frightening speed, often surprising unwary pray by bursting up through the ground beneath the creature and killing it with its sharp beak-like mouth. You can spot where they are because rocks/the ground move above them.\r\nThe massive worm [[Ouro]] was believed to be the only one in existence, but smaller versions of the worms can be found in [[Outland]]. They are found in [[Hellfire Peninsula]], [[Terokkar Forest]], and [[Blade's Edge Mountains]]. The Hellfire variants are called burrowers, the Blade's Edge variant is known as [[Crust Burster|crust bursters]], and the Terokkar strain is called [[Bone Worm|bone worms]].\r\nWhilst underground, sand worms cannot be targeted. This means that you will most likely not get the opening move if you run into one — no ambush, pounce, charge, or uninterrupted starfire/shadowbolt/fireball, since you'll already be in combat if you can target it.\r\nYoung Burrowers are unable to tunnel, and also seem to lack the characteristic claws.\r\n==Noteworthy sand worms==\r\n*[[Fulgorge]]\r\n*[[Hai'shulud]]\r\n*[[Ouro]]",},
			["Sanuye Runetotem"] = { content = "'''Sanuye Runetotem''' is a level 15 [[leather]] [[armor]] [[vendor]] located in [[Camp Taurajo]] in the [[Horde]]-aligned territory of [[the Barrens]].\r\n==Merchant==\r\n*Tanned Leather Jerkin\r\n*Tanned Leather Belt\r\n*Tanned Leather Pants\r\n*Tanned Leather Boots\r\n*Tanned Leather Bracers\r\n*Tanned Leather Gloves\r\n==See Also==\r\n* [[List of the Barrens NPCs]]",},
			["Sap"] = { content = "''Hey...did you feel something?...buddy?''\r\n'''Sap''' is the longest-lasting [[crowd control]] ability a [[rogue]] has. It will completely incapacitate a target for upto 45 seconds.\r\n==Notes==\r\n*Does not have a chance to break early, always lasting the full duration unless the sapped humanoid is hit. Suffers diminishing returns & duration in PVP.\r\n*No longer considered an incapacitate effect.\r\n==Related talents==\r\n*[[Dirty Tricks]], increases the Sap range and decreases energy cost.\r\n==Tips==\r\n*Sap is an effective [[crowd control]] technique, especially with the improved talent. Don't forget to tell the party which [[mob]] you are sapping, as any damage breaks the effect.\r\n*Sap does not cause [[threat]], meaning that if you Sap a [[mob]] and then move out of normal [[aggro]] range, the mob will not attack you after the sap effect is broken.\r\n*You may choose to sap a different target. The first sap will wake when the second one is sapped.\r\n*Out in the world, mobs that are sapped won't be tagged as your kill until you deal damage to them. Be wary of other players stealing your kill.\r\n*Sap can be useful in a [[PvP]] environment, to even out a 2-on-1, to take out a [[Shaman Totems|shaman's totems]] before you fight him, to capture a flag quickly in Battlegrounds, or even after a [[vanish]]. Remember, like all [[crowd control]] effects, Sap is limited to a 10 second duration in PvP.\r\n*Sapping a player of the opposite [[Faction]] will turn on your [[PvP Flag]]. Be wary.",},
			["Sapper"] = { content = "KABOOM! If ever a sound was associated with a particular class, it's this one. Quite simply, sappers love to blow things up. However, unlike many goblin tinkers, they don't necessarily like the idea of killing themselves in the process. No, to a sapper, the fiery blast of a good explosion is a form of art unto itself. Some spend a great deal of their lives trying to find new and interesting ways to generate beautiful, classy explosions. Sappers are experts in all sorts of explosive devices, from small firecrackers to powerful seaforium charges capable of blowing holes in thick castle walls. Even when they don't have a prepared explosive available, a good sapper can put one together out of whatever natural materials he can find lying around. \r\nGoblins are likely candidates for this class, since goblins like making things go boom! Gnomes and dwarves also make able sappers, with humans following close behind. The Horde made heavy use of goblin sappers in the Second War; indeed, goblin sappers were a key aspect of the Horde's strategy. Thus, the Horde knows how effective this class can be. In an adventuring party, a sapper often takes the role of a rogue or ranged combat support. He disdains typical rogue skills such as opening locks and disarming traps - he simply destroys such obstacles. When a battle erupts, he stays behind the lines, lobbing bombs into groups of enemies or employing fire-based [[technological]] devices to pick off more determined foes.\r\nA sapper generally takes great care to avoid harming himself; but still, he spends so much time around explosives that accidents are bound to happen. As a result, his body gradually becomes covered with a layer of tough scarring that protects against fire.\r\nThe sapper has learned new tricks to increase the yield of his explosives. Any grenade, bomb or other technological device he creates that deals explosive fire damage deals an additional damage per die.\r\nThe sapper is an expert in both the crafting and use of explosive devices. Any sort of bomb or grenade — basically anything that blows up — is his specialty.\r\nA sapper can attempt to build small explosive devices out of whatever materials are available. Even in the midst of an untamed wilderness, he can usually locate certain plants or minerals that, when mixed together, become something flammable.\r\nThe sapper is an expert on the delivery of explosive devices from a distance, whether employing any thrown or launched explosive device (such as a mortar).\r\nThe highly skilled sapper has transformed explosives into works of art. He can deploy a perfect blast — a thing of beauty (at least to himself and his allies). He can use this ability with any explosive device — as small as a grenade all the way up to massive wall-cracking charges — but he must prepare, set and activate the device himself. Doing so takes twice as long as normal for the device in question, but if it is successfully set off, the explosive deals the maximum possible.\r\n==Goblin Sapper==\r\nA great number of sappers - primarily [[goblin]] sappers - perished during the last war, mostly as a result of their overzealous use of too many explosives at once. Those who survived have become much more focused in their art, preferring precision to risks. Generally, the older a sapper is, the more careful and cautious he is - and the more respect his associates give him. \r\n*See [[goblin sapper]].\r\n==Alliance Sapper==\r\nSappers are engines of destruction; when the Alliance needs a structure removed from the battlefield, a dwarven demolition team is sent to blow it away. Sappers invite bloody death (and hearing loss) every time they go into action, but the sight of a [[Horde]] gatehouse collapsing into a pile of rubble is well worth such risks.\r\n===Dwarven Sappers===\r\n*See [[Dwarven Demolition Squad]]\r\nCheerfully striding onto the battlefield is a team of odd [[dwarves]], scarred and blackened faces, a mace in one hand, a pistol in the other, hauling kegs of powder strapped to their backs. They seem to ignore the rest of the field. The sapper’s tactics focus on delivering large amounts of gunpowder to a target and using his skills to destroy it. They are aware of the surrounding battle only as it concerns their ability to reach their target and have enough time to set a charge and escape.\r\nThis team likely later evolved into the Dwarven [[Mortar Team]].\r\n==Famous/Named==\r\n*[[Mareek]]\r\n==Sappers in WOW==\r\n*[[Hakkari Sapper]] - The Temple of Atal'Hakkar \r\n*[[Dark Iron Sapper]]- Loch Modan\r\n*[[Dark Iron Demolitionist]] - Wetlands",},
			["Sapphire Pendant of Winter Night"] = { content = "==Source==\r\nThis item can be acquired through crafting or another combine-type effect.",},
			["Sapphire Signet"] = { content = "==Source==\r\nThis ring is crafted by [[Jewelcrafting|Jewelcrafters]] with a skill level of 275. \r\nThe components are: \r\n*2 x Truesilver Bar\r\n*4 x Blue Sapphire\r\n*1 x Thorium Setting\r\nIt is learned from the Jewelcrafting [[trainer]].",},
			["Sapphiron"] = { content = ":''This article is a character biography. For information on how to defeat Sapphiron in World of Warcraft, see [[Sapphiron (tactics)]].''\r\n==Biography==\r\nAn ancient servant of [[Malygos]], Hand of Magic, '''Sapphiron''' was a [[blue dragon]] who lived with a powerful brood in [[Northrend]] by the [[Dragonblight]], where he communed with the ancient spirits of the dead dragons. Sapphiron was magnificently powerful, and protected the lands of Northrend as best he could. Though [[Ner'zhul]]'s malevolent influence defiled the [[Dragonblight]], Sapphiron and his brood continued to guard his hoard of treasure from any and all intruders. \r\nSapphiron and his brood lived in relative peace until King [[Arthas]], champion of the [[Lich King]], was suddenly called back to Northrend to save his weakening master, Ner'zhul. After three weeks at sea, the Death Knight landed on the shores of Northrend near Sapphiron's frozen lair, and was greeted almost immediately by the Crypt Lord [[Anub'arak]], King of [[Azjol-Nerub]], another powerful servant of Ner'zhul. Anub'arak had sensed Sapphiron nearby and suggested to the young Death Knight that perhaps by equipping themselves with the ancient blue wyrm's treasures, he and Arthas might be better prepared for the perilous journey through the underground kingdom of Azjol-Nerub to [[Icecrown]] Glacier. Arthas agreed, and boldly journeyed into Sapphiron's lair with Anub'arak. \r\nThe two servants of the Lich King fought their way through Sapphiron's minions till they finally reached the great blue dragon himself. Sapphiron greeted the undead as they approached him. He found Arthas's honesty about stealing his treasure quite refreshing. Sapphiron and his fellow [[dragons]] attacked with all their might, unleashing their strange, cold frost magics upon them. In the end, despite all odds, Arthas was victorious, and Sapphiron was defeated. As a final, clinching victory, however, Arthas used what remained of his dwindling [[necromancy|necromatic]] power to recreate Sapphiron as a [[frost wyrm]] to serve the [[Scourge]]. \r\nSapphiron was called upon to destroy the dwarves guarding the gates to Azjol-Nerub, but the great dragon was left outside of the tunnels, where he guarded it against all who would disturb his new master. Something never explained is how and why Sapphiron lost his ability to talk after being resurrected.\r\nSome years later the Scourge attacked once again and Sapphiron was sent with [[Kel'Thuzad]] to the [[Eastern Plaguelands]] to guard the Black Citadel [[Naxxramas]].\r\nSapphiron's powers are significantly greater than those of the average Frost Wyrm. This could be because Arthas, the Lich King's champion, revived him personally, or it could be a reflection of Sapphiron's greater power in life, or it could be some combination of both.\r\n==Encounter with Arthas==\r\n'''Sapphiron:''' ''You dare enter my lair? I am Sapphiron, ancient servant of Malygos the Spell-Weaver! Explain yourselves!''\r\n'''Arthas:''' ''Sorry we don't have time to chat, great wyrm. We've come to murder you and steal whatever artifacts you've been hoarding over the centuries.''\r\n'''Sapphiron:''' ''Honesty...how refreshing. None may challenge Sapphiron and live!''\r\n(Sapphiron is defeated by Arthas)\r\n'''Arthas:''' ''At least I still have enough power to do this...''\r\n(Sapphiron is raised by Arthas as an enormous Frost Wyrm)\r\n==Statistics of <font color=\"aqua\">'''Sapphiron'''</font> from Warcraft III==\r\n* 2750 HP <font color=\"limegreen\">(+50% more than a regular Blue Dragon)</font>\r\n* 500 MP <font color=\"limegreen\">(Blue Dragons have no MP)</font>\r\n* 58-91 anti-ground ranged chaos damage <font color=\"limegreen\">(+37% more than a regular Blue Dragon)</font>\r\n* 58-82 anti-air ranged chaos damage <font color=\"orange\">(-4% less than a regular Blue Dragon)</font>\r\n* 6 medium armor <font color=\"slategray\">(same as a regular Blue Dragon)</font>\r\n* Abilities\r\n** Frost Breath (attacks slow target)\r\n** Frost Nova (ranged direct damage and AoE slow)",},
			["Sapphiron (tactics)"] = { content = "'''Sapphiron''' is a gigantic undead dragon who guards the entrance to [[Kel'Thuzad]]'s inner sanctum in [[Naxxramas]].\r\n==Attacks and abilities==\r\n* Sapphiron is immune to frost spells.\r\n* Berserker enrage after 15 mins, making his '''''' do 600% damage.\r\n* Sapphiron will first take to the air 45 secs after engaging, then fire 5 '''Icebolts''' and 1 '''Frost Breath''' and land. After that, he will stay on the ground for 67 secs before flying up again and repeating the process.\r\n* Cleave - Your basic Frontal cleave, keep him faced away from the group.\r\n* '''''' - Deals 2625-3375 frost damage, 10 yard splash radius, 25 second duration, stuns chosen target for 3 sec. Only occurs when Sapphiron is in the air. Appears to induce an iceblock-like effect with the functionality of the Mage's Ice Block spell; ie. you cannot take any action but are immune to attacks for the duration. Ice Bolt last for 22 secs.\r\n* '''''' - Slow-moving, wide-range \"ice bomb\" AoE attack. Sapphiron will \"take a deep breath\" after 5 Icebolts in the air. It can be resisted. Only happens when Sapphiron is in the air - he breathes a cloud of frost which floats slowly to the ground and explodes when it touches the ground, doing 75000-125000 damage in a 70 yard radius. Sapphiron will land after Frost Breath. It takes about 5-6 seconds to land. Its target is the middle of the room, not a specific person. Anyone who has been frozen by Icebolt will be immune to this. This attack cancels the Ice Block. Raid members can stand behind the Iceblocked individuals and will be considered out of LoS of the Frost Breath.\r\n**Graphic wise the ball of frost explodes before hitting the ground, roughly around a second or two prior to hitting the ground.\r\n* '''''' - Frost-damage DoT-type attack. 100 yard radius, damages afflicted targets for 600 frost damage every two seconds. Keeps applying. (Can be partially resisted)\r\n* '''''' - 12 second duration, 100 yard range, curse-type. Drains 1750 to 2250 health and heals Sapphiron for 3500 to 4500 every 3 sec. Used every 24 secs as well.\r\n \r\n* '''''' - Much denser and larger than normal Blizzard. Deals 3063 to 3937 damage every 2 sec. Slows movement speed by 65%, 15 sec duration. Drifts in directions very much like green outdoor dragon sleep cloud. (Binary spell - the damage can be resisted completely or not at all)\r\nNote that once Sapphiron goes below 10% health, he will not fly back up into the air. This is almost certainly to prevent any error with a corpse in the air that may be unlootable. However, he will life drain below 10% health, and if you have him at 10% health, it is likely you'll kill him anyway.\r\n==Strategies==\r\n*Stay out of the blizzard\r\n*Decurse quickly\r\n*Get behind the ice blocks at the right moment\r\n*Bring a lot of healers\r\n==TBC==\r\nWhether purposely or not (possibly to make legendaries more difficult to obtain) the function of the iceblocks has changed slightly in The Burning Crusade expansion, merely standing behind them is no longer enough to avoid the frost breath attack. To check your character is standing in the correct position you should check if you can cast a spell or use a ranged ability against Sapphiron, if you are able to use an ability against him YOU ARE NOT SAFE, you keep moving until you recieve an \"target is out of line of sight\" message, then stand still, you are safe.",},
			["Sap Beast"] = { content = "'''Sap Beasts''' are level 22-23 [[ooze]]s found in the [[Stonetalon Mountains]].\r\n[[Witch Doctor Jin'Zil]] wants their sap.\r\n==Quests==\r\n*Jin'Zil's Forest Magic\r\n==Loot==\r\n*Stonetalon Sap ''(Quest Item)''",},
			["Sar'theris Strand"] = { content = "'''Sar'theris Strand''' is the name of the coast of [[Desolace]]. It is heavily populated by [[sea giant]]s, [[naga]], and [[makrura]]. The Karnitol Shipwreck lies off the northern part of the strand, and a small boat lies smashed on the beach below [[Ethel Rethor]]. Though Desolace is a grey, gloomy wasteland, the Sar'theris Strand is sunny and grassy.",},
			["Sar'theris Striker"] = { content = "==Source==\r\nThis item is [[fishing|fished]] from the [[Sar'theris Strand]], just south of [[Shadowprey Village]].\r\n==Sar'theris Striker as a quest objective==\r\n*Nat Pagle, Angler Extreme",},
			["Sar'this"] = { content = "'''Sar'this''' can be found in [[Terokkar Forest]] .\r\n==The Soul Cannon==\r\nDuring the quest The Soul Cannon of Reth'hedron, the character talks to Sar'this and gets its help to obtain the [[Flawless Arcane Essence]].\r\n==Soul Cannon Cut Scene==\r\n<font color=\"yellow\">Sar'this says: So my blood was not a sufficient payment, eh? Fine, let us recover your arcane essence. After this, I owe Balthas nothing.</font>\r\n<font color=\"orange\">Sar'this places a fetish at the ritual pile.</font>\r\n<font color=\"yellow\">Sar'this says: The process is arduous. We must first summon forth acolytes of the elements. you must then destroy these acolytes so that my minions can make preparations.</font>\r\n''Sar'this walks around the edge of [[Lake Jorune]] to cardinal compass points. At each stop, an elemental is summoned.''\r\n''At this station, an Air elemental is summoned. You slay it.''\r\n<font color=\"yellow\">Sar'this says: Well done! Let's continue.</font>\r\n<font color=\"yellow\">Sar'this says: Prepare yourself! The acolyte of water is soon to come...</font>\r\n''A water elemental is summoned. You slay it.''\r\n<font color=\"yellow\">Sar'this says: Well done! Let's continue.</font>\r\n''Sar'this continues on around the lake.''\r\n<font color=\"yellow\">Sar'this says: Come forth, acolyte of earth!</font>\r\n''An earth elemental is summoned. You slay this as well.''\r\n<font color=\"yellow\">Sar'this says: Well done! Let's continue.</font>\r\n''Sar'this continues around the lake.''\r\n<font color=\"yellow\">Sar'this says: Fire, show yourself!</font>\r\n''A fire elemental is summoned. Again, you slay it.''\r\n<font color=\"yellow\">Sar'this says: Well done! Let's continue.</font>\r\n''Again, Sar'this moves on.''\r\n<font color=\"yellow\">Sar'this says: Now we call forth the the arcane acolyte.</font>\r\n''Flawless Arcane Elemental is summoned.''\r\n<font color=\"yellow\">Flawless Arcane Elemental says: I require your life essence to maintain my existence in this realm.</font>\r\n<font color=\"yellow\">Sar'this says: It is yours my lord!</font>\r\n''You slay the elemental and retrieve the [[Flawless Arcane Essence]].''",},
			["Sarah Ladimore"] = { content = "'''Sarah Ladimore''' , also known as '''Watcher Ladimore''', is a level 28 [[quest giver]] located in [[Darkshire]] in the [[human]]-aligned territory of [[Duskwood]]. She is the daughter of [[Morgan Ladimore]], now known as the [[undead]] beast [[Mor'Ladim]].\r\nShe ends the quest The Daughter Who Lived.\r\nShe starts the quest A Daughter's Love.\r\nSee [[List of Duskwood NPCs]].",},
			["Sarah Tanner"] = { content = "'''Sarah Tanner''' is a level 50 [[artisan]] [[elemental leatherworking]] [[leatherworking trainer|trainer]] located at [[Tanner Camp|her camp]] in the [[contested]] territory of [[Searing Gorge]].\r\nAs of [[Patches|Patch 2.0.3]]. If you have unlearned your specialization, Sarah will tell you to first go see [[Narain_Soothfancy|Narain Soothfancy]] in the [[Tanaris_Desert|Tanaris Desert]], just north of the Steamwheedle Port. This is only necessary if you have learned any specialization before, and want to re-learn another one. Narain points you to the book on the table which will learn you either Dragonscale, Elemental or Tribal [[Leatherworking|leatherworking]].\r\nYou can also unlearn your Elemental specialization with Sarah, but it costs g=100 gold .\r\nShe gives the quest Elemental Leatherworking (Leatherworking). This is where you go if you want Elemental Leatherworking, and have 225 skill, Artisan, and you are at least level 40.\r\nSee [[List of Searing Gorge NPCs]].",},
			["Sarath'Najak"] = { content = "'''Sarath'Najak''' was a [[highborne]] sorcerer who assisted [[Dath'Remar Sunstrider]] in the escape from [[Zin-Azshari]].",},
			["Sarathstra"] = { content = "'''Sarathstra''', Scourge of the North, is a mighty [[frost wyrm]]. In the heart of the [[Dragonblight]], is a field full of nothing but [[dragon]] bones and snow. The Scourge have set up multiple camps in the central tundra and are raising frostwyrms to send against the forces at the [[Wrathgate]]. While most of these frostwyrms are easily dealt with by [[Rokhan]] and his dragon hunters, one of them is proving to be a bit problematic. Rokhan is out of hunters and he recruits adventurers to bring down the mighty wyrm.\r\n==Name==\r\nHer name sounds very similar to [[wikipedia:Zoroaster|Zarathushtra]], an ancient Iranian poet and prophet, and creator of one of the earliest monotheistic religions.",},
			["Sardor Isle"] = { content = "West of mainland [[Feralas]] is '''Sardor Isle'''. On the island's northern shore stands [[Feathermoon Stronghold]], led by the night elf general [[Shandris Feathermoon]], head of the Sentinel army. The night elves keep a watchful eye on the [[Isle of Dread]], located to the south of Sardor Isle, where things most unspeakable now walk the earth.",},
			["Sargeras"] = { content = "'''Sargeras''' the Destroyer, the Fallen Titan, is the creator and leader of the [[Burning Legion]]. Sargeras was once a [[Titan]], a champion chosen by his fellow members of the [[Pantheon]] to defend the worlds they had created. \r\nSargeras has changed over the millennia. While he once served his race as guardian and protector, he is now the titans' worst enemy. Sargeras works to undo what the titans have strived for ages to achieve. He is now the master of all that is evil and demonic. Lesser beings quake and flee in his presence. \r\n===Champion of the Pantheon===\r\nSargeras was a mighty giant of molten bronze who led the armies of the Pantheon, the champion of the titans' cause. Like the rest of his kind, he was altruistic and just, unable to conceive of pure evil. Sargeras was called upon to defeat and imprison the hordes of demons native to the [[Twisting Nether]], so that their evil would not contaminate the titans' vision of order. Sargeras went about his task devoutly for countless millennia. \r\nWhile his confusion and misery deepened, Sargeras was forced to contend with another group intent on disrupting the Titans' order: the [[Nathrezim]]. This dark race of vampiric demons (also known as dreadlords) conquered a number of populated worlds by possessing their inhabitants and turning them to the shadow. The nefarious, scheming dreadlords turned whole nations against one another by manipulating them into unthinking hatred and mistrust. Sargeras defeated the Nathrezim easily, but their corruption affected him deeply. \r\nShaken by the evil of demons in general and the Nathrezim in particular, Sargeras began to despair of his task and gradually slipped into a brooding depression. As doubt and despair overwhelmed Sargeras' senses, he lost all faith not only in his mission, but also in the Titans' vision of an ordered universe. Eventually he came to believe that the concept of order itself was folly, and that chaos and depravity were the only absolutes within the dark, lonely universe. His fellow Titans tried to make Sargeras realize his erroneous way of thinking and calm his raging emotions, but he disregarded their more optimistic beliefs as self-serving delusions. Storming from their ranks forever, Sargeras set out to find his own place in the universe. Although the Pantheon was sorrowful at his departure, the Titans could never have predicted just how far their lost brother would go.\r\n===Fall of Sargeras and the Dawn of the Burning Legion===\r\nBy the time Sargeras' madness had consumed the last vestiges of his valiant spirit, he believed that the Titans themselves were responsible for creation's failure. Deciding at last to undo their works throughout the universe, he resolved to form an unstoppable army that would set the physical universe aflame.\r\nConvinced that the Titans’ ordering of the universe was unnatural and ultimately responsible for the corrupted nature of the demons, Sargeras decided to undo the work of the Titans throughout the universe. The only way that he could correct their mistakes was to destroy all of the worlds that the Titans had shaped and brought order to so long ago. \r\nSargeras roamed the Twisting Nether, freeing the many demon races that he had previously hunted down and imprisoned. He bound the newly released demons to his will and used them to construct an army of massive proportions — one that eventually became known as the Burning Legion. These cunning creatures bowed before the dark Titan's vast rage and offered to serve him in whatever malicious ways they could. However, among the various beings who served him, none of them had the natural cunning and power to act as commanders and tacticians for his new army, so Sargeras looked about for a race who would serve as his favored agents in exchange for horrific power.\r\nOn the planet [[Argus]], Sargeras found the agents he sought — the [[Eredar]], a race of highly intelligent beings with a natural affinity for magic in all its myriad forms. Sargeras appeared to the Eredar's three greatest leaders, [[Kil'jaeden]], [[Archimonde]], and [[Velen]], and made his offer: untold power and prestige in exchange for their alleigance. Though Velen had doubts, Kil'jaeden and Archimonde readily agreed. Velen and his followers fled, becoming the [[draenei]]. The remainder of the eredar embraced the darkness, and became the stuff of nightmares: [[man'ari eredar]]. \r\nSargeras tasked Kil'jaeden the Deceiver to seek out the darkest races in the universe and recruit them into Sargeras' ranks. Meanwhile, Archimonde the Defiler would lead Sargeras' vast armies into battle against any who might resist the Titan's will. Now that his armies were amassed and ready to follow his every command, he launched his raging forces into the vastness of the [[Great Dark]]. To this date, it is still unclear how many worlds his Burning Legion has consumed and burned on their unholy [[Burning Crusade]] across the universe.\r\n===The Temptation of Azeroth===\r\nThey eventually became aware of the young world of [[Azeroth]] due to the night elves’ reckless use of arcane magic, and Sargeras began to hunger for the limitless energies of the Well of Eternity. The elven [[Queen Azshara]] and her people, the [[Highborne]], were wielding magic as their plaything. Sensing the great potential of the [[Well of Eternity]], and knowing that it could satiate his hunger for magic, Sargeras called the Burning Legion to the ethereal outskirts of Azeroth, and the Enemy of All Life called to Azshara. The highborne Queen was impressed and overwhelmed by Sargeras' great power. He used a subtle form of mental manipulation while speaking to her and her councilor, [[Xavius]]. They saw Sargeras as a god and worshiped him. Azshara agreed to allow him entrance to her world if only for a taste of a portion of his knowledge and energy. Thus did the first invasion of Azeroth begin.\r\n \r\nArchimonde and the great [[Pit Lord]] [[Mannoroth]] stormed through [[Kalimdor]], ripping the world to shreds and sucking every ounce of energy from it that they could. Meanwhile, Sargeras waited in the Twisting Nether for Azshara to strengthen the Portal enough to allow him entrance. That time was growing very near very soon.\r\nHowever, at the last moment, the [[night elves]], aided by [[Cenarius]]' woodfolk and [[Alexstrasza]]'s [[dragon]]s, mustered their forces and rebelled against the highborne, in a climactic battle that destroyed the Well of Eternity and crushed much of the world to rubble. The defenders of Azeroth paid a great cost to throw the demons back into the Twisting Nether, but in the end, Sargeras' mission had failed for the very first time. Because the portal rift into the Twisting Nether vanished in such a great display of magical power, the forces holding the worlds together ruptured, causing the Well of Eternity to implode. A massive part of Kalimdor sank beneath the ocean, and where the Well of Eternity had been before, there was only a gigantic oceanic vortex, later named the [[Maelstrom]].\r\nSargeras’ first invasion of Azeroth failed, and his armies were defeated by the demi-god Cenarius and the dragon Aspects left by the titans.\r\nIn the novel [[War of the Ancients]], [[Krasus]], [[Rhonin]], and [[Brox]] are thrown back in time and are able to help the demi-god Cenarius and the dragon Aspects fight the [[Burning Legion]]. Once again, in this new timeline, Sargeras’ first invasion of Azeroth fails.\r\n===Aegwynn & Medivh===\r\nThe second time that Sargeras entered Azeroth was in the form of an avatar. [[Aegwynn]], the Guardian of Tirisfal at the time, detected Sargeras’ presence, hunted his avatar down and defeated it in combat. \r\nSome nine thousand years after the [[War of the Ancients]], Aegwynn kept a constant vigil over Azeroth, destroying demons wherever she found them. Sargeras saw that Aegwynn was a serious threat, but he also saw how she could be manipulated. The Dark Titan sent demonic agents on a great dragonhunt. The demons killed several dragons, but Aegwynn inevitably appeared to aid the great beasts. Together, they destroyed the band of demons before they could do irreparable damage.\r\nAs Aegwynn surveyed the scene, she found the rift from which the Legion's agents had come through in the [[Storm Peaks]]. Using this portal, Sargeras entered Azeroth to confront Aegwynn. The Guardian of Tirisfal did not hesitate in attacking, but Sargeras held back, letting the mage destroy his physical body. However, as it died, Sargeras’ spirit reached inside Aegwynn’s body and hid, lying dormant for many years. Unaware of the tainted presence inside her body, Aegwynn buried Sargeras’s physical body in a tomb and cast it deep into the ocean.\r\nYears later, the [[Order of Tirisfal]] informed Aegwynn that her time as a Guardian was up, and asked her to proceed to [[Dalaran]] to choose her successor. Aegwynn disobeyed the Order's command, deciding that only one of her own lineage would suffice. She sought out the great mage and advisor to King [[Landen Wrynn]], [[Nielas Aran]]. Aegwynn seduced the mage, eventually mothering a son by him.\r\nEventually Sargeras’s spirit awoke and possessed the mind of Aegwynn’s unborn son, [[Medivh]]. Medivh, son of Aegwynn, was born. \r\nWhen Medivh reached fourteen, his powers as a Guardian manifested and he fell into a coma that lasted for twenty years. During this time, Sargeras tapped into the Guardian's enormous power, and when Medivh at last awoke, the Dark Titan had nearly taken complete control. In his new body, Sargeras contacted the orcish warlock [[Gul'dan]], leader of a host of orcs on the world of Draenor, which had been discovered by his lieutenant, [[Kil'jaeden]], a few generations beforehand. Medivh went to the [[Black Morass]] in the remote, southern parts of Azeroth and opened the Dark Portal, allowing the orcs permanent access to the planet. Gul'dan's Orcish Horde swarmed through the rift, waging war upon the native humans of the [[Kingdom of Azeroth]].\r\nMedivh's nature was thoroughly changed after his coma, and his closest friends and relatives noticed something was wrong. Medivh's mother Aegwynn, now banished from the realm for her misdeeds against the Order of Tirisfal, had figured out what Sargeras had done to her, and got into contact with King Llane and his general, Lord [[Lothar]]. Lothar felt he had no choice but to destroy the corrupted Medivh in order to prevent the evil Guardian from doing any more damage to Azeroth. Medivh's apprentice, [[Khadgar]], helped Lothar and an orcish emissary, [[Garona]], infiltrate Medivh's dark tower, [[Karazhan]]. Despite his enormous power, Medivh was caught off his guard, and was in the end killed by his former friends and comrades in his underground sanctum. \r\nSargeras desired vengeance against the human kingdoms, and expected the orcs to travel through the portal and destroy the humans. Although the orcs did enter the portal and eventually caused a great amount of damage to the human kingdoms, Sargeras ultimately failed in his plans because of Medivh's death. Eventually, Sargeras wanted to shed the body of Medivh and once again enter his avatar.\r\nAs Medivh died, the portion of Sargeras’ spirit that had possessed him was released and swiftly dispersed. This spirit was sent reeling in pain back into the Twisting Nether. There it remains in limbo, unable to access a vessel body powerful enough to hold his demonic spirit.\r\nMany believe that Sargeras’ spirit yet endures, somewhere — hungering for revenge against the only world ever to withstand the Burning Legion’s might…\r\n==The Real Sargeras & the Banishment of his Spirit==\r\nInteresting enough according additional lore, it is said that Aegwynn may not have fought Sargeras' original body, but rather only fought an avatar of Sargeras. It is said that this avatar was infused with a portion of Sargeras' soul which he controlled. Medivh was born with this fragment of his soul, and it later escaped back to the Twisting Nether. Brann Bronzebeard is pretty confident that the real Sargeras never actually set foot on Azeroth, implying the real Sargeras is still around in the Twisting Nether. Brann also believes, along with others, that the portion of the spirit that escaped still endures, hungering for revenge. \r\n[[Richard A. Knaak]] said in an earlier interview:\r\n''Sargeras ceased to be in the sense of his physical being in the mortal world of Azeroth. He was cast into limbo, so to speak, as Blizzard wanted. Otherwise, he pretty much would have immediately returned to try to destroy Azeroth again. 'Ceased to be' was used specifically for that reason.''\r\n in [[Warcraft III]]]] The orcish warlock Gul'dan believed the [[Tomb of Sargeras]] to hold amazing power, since he had been told as much by both Medivh and the eredar demon [[Kil'jaeden]]. Gul’dan attempted to claim the tomb for himself, but when he gained access to the grave, Sargeras' avatar was not there. Instead Gul'dan found a plethora of demons that had been driven mad by their long imprisonment, the demons proceeded to tear Gul'dan to shreds but he survived the first ambush. Then [[Gul'dan]] saw Sargeras (or at least an illusion of him) laughing at him, he understood that he had been a pawn, a fool, now he would not get the [[Eye of Sargeras]] and will die in tomb, he wrote his story in runes with his own blood. Shortly afterwards the demons came for him and killed him, eventually using his [[Skull of Gul'dan|skull]] as a focal point of demonic power. To this day, it is unknown what happened to Sargeras' avatar. \r\n==Appearance==\r\nSargeras is a huge being almost beyond comprehension. He is fully clad in a burning suit of molten, black armor. Wildly dancing flames surround his head and form a thick mass of hair and a sweeping beard. A pair of horns extends from his forehead and a burning tail sweeps behind, leaving a trail of glowing embers in its wake. One of its arms hefts a massive,\r\netched lance that is lined with a series of viciously hooked barbs. Demonic influences have given Sargeras body flames.\r\n==Skills and abilities==\r\nSargeras doesn't fight fair. He fights dirty and goes for the throat as quickly as possible. He also doesn't fight alone. Sargeras has a universe of formerly vanquished demons that he now commands to do his bidding. Most of them even do so\r\ngladly.\r\nAs a former champion of the titans, Sargeras is nearly impervious to physical damage. He is highly resistant to magical attacks. His natural attacks are more powerful than other titans. Demonic influences have given Sargeras' body flames and made him totally immune to fire damage and fel damage. Sargeras’ flesh burns with demonic energy, scorching everything in his path. Sargeras' body flames slowly increase the ambient temperature by up to fifty degrees in every direction for one thousand miles. The effect on natural climates can be devastating.\r\nWhen he has his normal horde of demons on hand, Sargeras usually begins a fight by casting enlarge person, displacement, haste, mage armor and shield on himself, plus slow on as many enemies as he can. He identifies the most powerful threat in a battle and instructs his own most powerful forces to focus on the single threat until it's dead or at least banished from the fight. He then identifies the next most dangerous foe, and continues in this way working down the ladder until he is victorious. Sargeras uses his most powerful spells and abilities first, such as domination on evil outsiders; energy drain on an enemy spellcaster; blasphemy on visitors from other planes; or power word stun, disintegrate, phantasmal killer and flame strike. He uses quickened telekinesis to toss enemies around and disrupt his enemies’ attempts to coordinate their side of the battle.\r\nSargeras is deadly in melee. He has no problem forcing his way with his demon bodyguards through enemy lines to strike at the most dangerous foes. If somehow severely damaged, Sargeras begins casting dimension door to maintain his distance while using heal to restore his life. All other tactics aside, Sargeras’ truly favored tactic is to use summoned minions to aid him. If the battle is going to rage for a long time, he uses planar binding spells to bring forth powerful evil outsiders and dominates them. As the battle draws on, he uses summon monster spells instead.\r\n===Powers===\r\nThe exact powers at the Dark Titan's command are unclear, though certainly formidable given his status as a former Titan and Lord of the Legion. \r\nHe has been shown to display the following powers:\r\n* Telepathy (able to commune with his servants, such as [[Mannoroth]] and [[Archimonde]], from the Nether)\r\n* Illusion (created a false vision of what he offered to the eredar in exchange for their obedience)\r\n* Invulnerability against mortal weapons, and limited immunity to immortal ones (the axe created by [[Cenarius]] for [[Broxigar]] was able to wound him, but not to any great effect), while the powers of the [[Demon Soul]] had no effect) as well as complete immunity to fire and fel magics.\r\n* Various magical abilities (lashed out with energy at Illidan via the portal being opened to summon him).\r\n* Able to look into the mortal realm through the eyes of a chosen servant (his \"gift\" to [[Illidan]]).\r\n* Cosmic knowledge (as a former Titan, Sargeras was likely aware of the existence of the malevolent [[Old Gods]]).\r\n* Ability to enter mortal bodies (remained within [[Aegwynn]]'s womb for nearly a millennium) and take control of them ([[Medivh]]).\r\n* Body Flames (Sargeras’ flesh burns with demonic energy, scorching everything in his path. Sargeras’s body flames slowly increase the ambient temperature by up to 50 degrees in every direction for 1,000 miles. The effect on natural climates can be devastating.).\r\n* His molten armor can nearly burn your eyes..\r\n* The strength of 100 dragons is merely a fraction of Sargeras' strength; his strength nearly matches the power of a portal closing.\r\n* In comparison to Sargeras, [[Mannoroth]] and [[Archimonde]] were as fleas. This could be a reference to either power or height.\r\n* He wields the horrific broken sword, [[Gorribal]].\r\n==Character Development==\r\n''In the original lore, Sargeras was sent to confront the insidious eredar prior to his confrontation with the Nathrezim. This has now been [[retcon]]ned by new lore that establishes that the eredar, and other races were transformed into demons by Sargeras.''\r\n''Sargeras was originally a footnote in Warcraft lore, a fallen Daemonlord whose dark legacy was used by Medivh to manipulate Gul'dan. Gradually, novels and game material built up his role to the primary lore villain.''\r\n==Related Artifacts==\r\nSargeras has various weapons:\r\n*[[Jeweled Scepter of Sargeras]] This powerful staff was used by Sargeras for purposes unknown, but it is known that it can make portals. It was eventually stolen by Ner'zhul and was used to make the portals that destroyed [[Draenor]]. Its fate is unknown, though given the fact that it was in Ner'zhul's possession when he entered the rift, it has probably been returned to Kil'jaeden. \r\n*[[Gorshalach]]: Sargeras wielded this sword when he was still a champion of the Pantheon. It sundered itself into two pieces upon Sargeras' fall into madness. Sargeras reforged one of the two fragments into his current weapon, [[Gorribal]], while the other fragment was claimed by [[Aggramar]] and reforged into [[Taeshalach]].\r\n*[[Eye of Sargeras]]: It is unknown if it was his real eye or a [[Trinket]] he had with him when he was \"killed\" by [[Aegwynn]], although it was described by [[Brann Bronzebeard]] as \"the last remnant of his withered form\". It appears to have had the ability to focus magics into a single destructive force. It was destroyed in [[Dalaran]] when Illidan's spellwork was interrupted.\r\n*[[Atiesh, Greatstaff of the Guardian]]: This weapon was used by [[Medivh]]. Sargeras made a powerful demon inhabit it when he possessed Medivh. The demon still inhabited the staff, even when it was shattered. The demon is now known as [[Atiesh, Hand of Sargeras]]. He must be killed to purify the staff. \r\n* The unnamed spear of Sargeras, wielded when Aegwynn battled his avatar. The spear is inscribed with runes that continuously bleed.\r\nSee also: [[Tomb of Sargeras]]",},
			["Sargeras and the Betrayal"] = { content = "'''\"Sargeras and the Betrayal\"''' is a section of the [[History of Warcraft]], Chapter I.\r\nFound at:\r\n* [[Astranaar]] in [[Ashenvale]] .\r\n* [[Hammerfall]] in [[Arathi Highlands]] - Inn\r\n* [[Ratchet]] in the [[Barrens]] - Inn\r\n* The Reliquary of [[Scholomance]] in the [[Western Plaguelands]].\r\nTimeline: \r\n* ← Previous book: [[The Titans and the Shaping of the Universe]]\r\n* → Next book: [[The Old Gods and the Ordering of Azeroth]] \r\n==See also==\r\n* [[Sargeras]]\r\n* [[Eredar]]\r\n* [[Kil'jaeden]]\r\n* [[Archimonde]]\r\n* [[Burning Legion]]",},
			["Sargeron"] = { content = "'''Sargeron''' was once a [[night elven]] city, but has lain in ruins since the [[War of the Ancients]]. The town's original name has been lost to time, but its ruins are home to numerous [[satyr]], which have redubbed it Sargeron after their demonic master [[Sargeras]].",},
			["Saria Nightwatcher"] = { content = "A [[night elf]] [[warden]] and [[Argent Dawn Templar]]. As a templar she developed the spell known as Saria's Crown of Divinity. It causes a halo of light to appear over a subject's head, giving off light equivalent to a torch. Great resolve bolsters the subject, and they also gain immunity to fear and improvement of moral against mind-affecting effects. She once elected to improve her spell-like ability shadowmeld. She replaced it with invisibility, and later greater invisibility.",},
			["Sarilus Foulborne"] = { content = "'''Sarilus Foulborne''' is a level 25 [[Forsaken]] [[mage]] who fills the [[Mystral Lake]] in [[Ashenvale]] with corrupted [[water elemental]]s. He is the only undead mage in the [[Barrens]] capable of defiling this many water elementals. Sarilus Foulborne is probably sitting at the top of [[Dreadmist Peak]].\r\n[[Sentinel Velene Starstrike]] wants his head.\r\n==Quests==\r\n*Mage Summoner\r\n==Loot==\r\n*Sarilus Foulborne's Head ''(Quest Item)''",},
			["Sarkoth"] = { content = "Sarkoth is a level 4 [[scorpid]] found in the [[Valley of Trials]] in [[Durotar]].\r\n[[Hana'zua]] was poisoned by Sarkoth, and wants Sarkoth's claw.\r\nHe wanders on a plateau in the Valley of Trials.\r\n==Quests==\r\n*Sarkoth\r\n==Loot==\r\n*Sarkoth's Mangled Claw ''(Quest Item)''",},
			["Sark Ragetotem"] = { content = "'''Sark Ragetotem''' is a level 60 [[warrior trainer]] located on [[Hunter Rise]] in the [[tauren]] city of [[Thunder Bluff]].\r\nSee [[List of Thunder Bluff NPCs]].",},
			["Saronite"] = { content = "'''Saronite''' is a [[metal]] found in [[Northrend]]. It is the blood of [[Yogg-Saron]]. According to [[Daggle Bombstrider]], it's a very popular item on the black market.\r\n==Origin==\r\nSaronite is an [[element]] associated with the [[Old God]] [[Yogg-Saron]]. It first appeared across [[Azeroth]] around the year -4,500 in areas in [[Ashenvale]], [[Crystalsong Forest]], [[Feralas]], [[Duskwood]], and the [[Hinterlands]] but was eradicated with the help of [[Fandral Staghelm]]. According to the [[Archivum Console]] in [[Ulduar (instance)|Ulduar]], a powerful acid found within Yogg-Saron is believed to be responsible for the liquefaction of saronite.\r\nThe [[tuskarr]] called it the \"Black Blood of Yogg-Saron\".\r\n==Properties==\r\nThe quest [[Pure Evil]] shows how strong and resistant the evil metal is. The saronite [[ore]] collected was completely unscratched by the attacks from [[Crusade Commander Korfax|Crusade Commander Korfax's]] [[Arcanite Reaper]]. The ore was also completely resistant to the nature magic used against it by [[Rayne]] and [[Rimblat Earthshatter]]. Finally, the ore was struck by the powers of the [[Light|Holy Light]] by [[Avenger Metz]], and the ore reacted but seemed to reflect the spell back at everyone in the area. The metal itself is very strong yet lightweight.\r\n[[Borus Ironbender]], the Horde Grand Master Blacksmith trainer in [[Agmar's Hammer]] in the [[Dragonblight]], remarks — from his observations of [[Angrathar the Wrathgate]] — that he had never seen a metal \"breathe\" before, and sends adventurers to the [[Pit of Narjun]] outside [[Azjol-Nerub]] to collect samples of this metal for his research.\r\nSince the Lich King's psychic powers are powerful, and his undead minions have no will of their own to speak of, they might be resistant to the evil of Yogg-Saron. This would seem to be the main reason the [[Lich King]] chose to use this evil ore to create his fortresses in Icecrown as well as create his war machines.\r\nIt is unknown if the mind of the [[Knights of the Ebon Blade]] are affected by wearing saronite now that they are free from the grasp of the [[Lich King]]. However, the [[Ashen Verdict]] appears to have found a way to bend saronite to their will and equip their greatest champions in their ascent of [[Icecrown Citadel]].\r\nIt also has powerful properties that are useful against [[undead]], capable of destroying both their flesh and their soul. [[Sylvanas Windrunner]] used saronite to end her unlife, reasoning; \"The fall alone couldn't kill her: her animate flesh was nigh indestructible. But the spikes, the hardened blood of an Old God, they not only would tear the body apart but would obliterate the soul as well.\" Properties that could be forged into a weapon. As such, Sylvanas threw herself off from the Frozen Throne, believing that saronite would grant her rest. Apparently aware of this property, [[Bolvar Fordragon]] hurled saronite projectiles at Sylvanas during their confrontation at [[Icecrown Citadel]], but she was easily able to evade or shatter them.\r\nHowever, saronite isn't indestructible; as seen with a [[Iron Colossus|Colossus]] constructed from a saronite alloy who is still vulnerable to the acid of the massive [[Jormungar]], or even when the [[Argent Crusade]] used a [[battering ram]] to bring down the doors of [[Icecrown Citadel]]. Smelted saronite has also been described as being \"brittle\" on two separate occasions, first in the quest [[I'm Smelting... Smelting!]] where the Scourge used broken shards of saronite to create deadlier [[Ghoul]]s and later in [[Tempering The Blade (Alliance)]] and [[Tempering The Blade (Horde)]] where it was said \"that jagged saronite edge is brittle and will shatter the moment it strikes anything\" unless it was properly tempered.\r\nDespite its saronite composition, the [[paladin]] [[Uther the Lightbringer]] managed to crumple Arthas' armor with a powerful attack of his [[holy]] warhammer. Later, the [[dark ranger]] Sylvanas Windrunner managed to injure and paralyze Arthas with a poison arrow, the latter described that her arrow had \"piercing through his armor as if it were as flimsy as parchment\".\r\nAlthough saronite armor can withstand and protect from [[magic]]al flames, its wearer is not immune to the resulting heat, as the flesh of Arthas was burned and wounded by the [[Arcane|arcanic]] flames of the [[mage]] [[Kael'thas Sunstrider]] and the [[fel]] flames of the [[demon hunter]] [[Illidan Stormrage]] during their respective battle in [[Northrend]].\r\n===Uses of saronite===\r\nThe major user of saronite is the [[Scourge]], who utilizes this evil metal to its full potential. They have used saronite to power their war machine and construct their master's stronghold, [[Icecrown Citadel]], as well as the ramparts, spires, and [[Cathedral of Darkness|cathedrals]] that practically cover the Icecrown region. The Scourge, in the laboratories of the [[Fleshwerks]], have also begun implanting broken shards of saronite into the bodies of ghouls, resulting in much deadlier minions in the Scourge legions. The Lich King has even commissioned the construction of a [[necropolis]], [[Malykriss: The Vile Hold|Malykriss]], which would be made completely of saronite.\r\nWhen [[Arthas Menethil]] became the first of the Lich King's [[death knight]]s in [[Northrend]], he was given a suit of saronite armor.\r\nAs an agent of the Lich King in [[Acherus: The Ebon Hold|Acherus]], the death knight [[adventurer]] was given a saronite armor after they proved themselves in battle against the enemies of the Scourge. In the [[Scarlet Enclave]], the skeletal archers led by [[Orithos the Sky Darkener]] used saronite-headed arrows to rain death on the citizens of [[Havenshire]], before sending [[death knight]]s to retrieve them due to their limited number, as they are far from Northrend.\r\nTo contain the energies that dance across its cold edges, [[Shadowmourne]] was hewn with piles of impure saronite, treated only by master metal-shapers. As the base of the legendary weapon, [[Shadow's Edge]] was created from [[Light's Vengeance]], the hammer of Arthas Menethil before he took up [[Frostmourne]], reforged by a [[Adventurer|champion of Azeroth]] with saronite under the order of [[Darion Mograine|Highlord Darion Mograine]].\r\nSaronite is also used by player characters of both the Alliance and the Horde, as grand master [[blacksmith]]s can make armor and weaponry from saronite, and grand master [[engineer]]s can craft explosives.\r\n===The side effects of saronite mining===\r\nOften, mortals who mine saronite for prolonged periods of time appear to be driven insane. Indeed, many of the people who have been rescued from the [[Saronite Mines]] tell of hearing strange whispers of unknown origins, attempting to shape their perceptions of those around them. Others became enraged and simply attacked their would-be rescuers at the very suggestion of being taken away from the [[Yogg-Saron|\"Master\"]], while still others yell madly about their mysterious \"Master\", and attempt to offer their lives to it by hurling themselves down into the deep recesses of the mines.\r\nPlayers who spend time in the [[Saronite Mines]] of [[Ymirheim]] in central [[Icecrown]] or [[Whisper Gulch]] in the [[Howling Fjord]] will begin seeing whispers from a set of \"Unknown Voices\" appearing in their chat logs.\r\n==Appearances==\r\n*[[Angrathar the Wrathgate]] in [[Dragonblight]]\r\n*The [[Saronite Mines]] in [[Icecrown]]\r\n*The Scourge fortresses all over [[Icecrown]], including [[Icecrown Citadel]] and the [[Shadow Vault]]\r\n===Nodes===\r\n*[[Saronite Deposit]]\r\n*[[Rich Saronite Deposit]]\r\n*[[Pure Saronite Deposit]]\r\n*[[Strange Ore]] for a quest\r\n====Ore====\r\nNodes when mined produce [[Saronite Ore]].\r\n[[Chunk of Saronite]] is used in a quest.\r\n====Bars====\r\n[[Saronite Bar]] is [[smeltable]] from 2 [[Saronite Ore]].\r\n==Faceless ones==\r\nThe [[N'raqi|faceless ones]], creatures created by the [[Old God]]s, appear for some of them to be partially composed of saronite as well. [[General Vezax]], the faceless general, gives off saronite Vapors and says, \"The black blood of Yogg-Saron courses through me!\" Other faceless ones are depicted with saronite-colored blood in their veins.\r\n==Mobs==\r\n*Saronite Animus\r\n*Saronite Horror\r\n*Saronite Shaper\r\n*Saronite Vapors \r\n==Notes and trivia==\r\n*In the game's files, its icon is named yoggthorite.\r\n==See also==\r\n*[[Smelt Saronite]]\r\n*[[Saronite Bar]]\r\n**[[Reforged Saronite]]\r\n*[[Whisper Gulch Ore Fragment]]\r\n*[[Contents of Mosh'Ogg Bounty]]",},
			["Saronite Bar"] = { content = "'''Saronite Bar''' is a new metal bar made in [[Northrend]] from Saronite Ore.\r\n==Source==\r\nThis item can be crafted using [[Mining]] (400); taught by Grand Master Mining trainers for 15 gold .\r\n==As an ingredient==\r\n...",},
			["Saronite Mines"] = { content = "'''The Saronite Mines''' are located in the middle of [[Ymirheim]]. There, the [[Vrykul]] mine [[Saronite]] for the [[Scourge]] and also [[Darkspeaker R'khem]] is imprisoned in these mines.",},
			["Saronite Ore"] = { content = "'''Saronite Ore''' is a metal ore found only in [[Northrend]]. The [[Scourge]] uses saronite to provide [[death knight]]s with armor.\r\nSaronite will be a new metal ore for [[mining]] in Northrend.\r\n==Source==\r\n* Mined from Saronite Nodes or Rich Saronite Nodes.\r\n===[[Smelting]] ([[Mining]])===\r\n* [[Smelt Saronite]] - requires mining skill 400\r\n** 2 ore are converted into 1 Saronite Bar at a [[forge]]\r\n===[[Prospecting]] ([[Jewelcrafting]])===\r\n'''Saronite Ore''' can be prospected by Jewelcrafters with a skill of 400, resulting in a random uncommon and possible rare gem:\r\n* Dark Jade\r\n* Sun Crystal\r\n* Huge Citrine\r\n* Chalcedony\r\n* Bloodstone\r\n* Shadow Crystal\r\n* Twilight Opal\r\n* Scarlet Ruby\r\n* Autumn's Glow\r\n* Forest Emerald\r\n* Monarch Topaz\r\n* Sky Sapphire",},
			["Sartharion"] = { content = "'''Sartharion''' is a [[black dragon]] boss located in the [[Obsidian Sanctum]] of the [[Chamber of Aspects]].\r\nThis part of the Obsidian Sanctum contains 4 mobs of interest. These are Sartharion the raid boss himself and 3 drakes, Vesperon, Shadron and Tenebron. Each has their own form of adds depending on how you engage. The drake mobs are known as 'Disciple of ...' respectively.\r\n===Twilight Drakes===\r\n* Vesperon-\r\n** Has aura: Power of Vesperon: Maximum health decreased by 25%.\r\n* Shadron-\r\n** Has aura: Power of Shadron: Fire damage taken increased by 100%.\r\n* Tenebron-\r\n** Has aura: Power of Tenebron: Shadow damage taken increased by 100%\r\nEach drake can be taken down without engaging Sartharion. The achievements require leaving them up. If you do down them, they each give a Emblem of Heroism, but no loot.\r\nEach drake fight is a typical spank and tank, but after ?s the drake will open a portal. One healer and some dps and the OT need to take the portal to shift to fighting the add. Much like phased content, you'll be in the same place (totems still exist where you left them), but instead of seeing the drake, you'll fight a disciple of X, depending on which drake it is. they have a shadow aura that reduces damage taken by 25%, but periodically pulses shadow damage to you. Once that add is downed, a portal appears and returns you to the drake. You cycle portals/dps on the drake until down.\r\n===Sartharion===\r\n* Has ? HP\r\n* Has Cleave. ? damage.\r\n* Has Tail Whip. ? damage.\r\n* Has Frontal Breath. Fire attack. did ~15-18k with Shadron's debuff up unresisted.\r\nHis immediate area is surrounded by a small moat of lava. The east/west sides of this lava spawn lava waves by Sartharion during his emotes every ?s. See layout/positioning images below for details.\r\n==Strategy==\r\n* Layout:\r\n** GREEN is the instance portal\r\n** PURPLE are the 3 drakes up in the hills (Tenebron on the ?, Vesperon on the ?, Shadron on the east)\r\n** Light RED is the lava border immediately surrounding Sartharion\r\n** YELLOW is Sartharion's position before the pull\r\n* Positioning:\r\n** YELLOW is Sartharion's position after being rotated to face east\r\n** GREEN is the MT location\r\n** PURPLE is the melee\r\n** BLUE is the ranged/healing camp\r\n'''Lava Waves''':\r\nThe light blue paths are to illustrate where the gaps in each of the waves are when he emotes. If the wave comes from the right side, heading west, as you face Sartharion's initial position, they should come behind the tank, and the gap will be by the melee group. If the wave comes from the left side, heading east, the gap will be back where the ranged camp is located. Failing to get to the gap means the wave will hit you and leave a minor fire dot on you (1500-2000dmg? before Shadron's modifier).\r\nWhether your tank eats the wave to stay put, or rotates to the gap, as when you have Shadron up still, is up to your group. Just be clear with your melee/ranged on rotating along the gap path to avoid Cleave and Breath attacks.\r\n'''Sardarion's Fire elemental Adds''': \r\nThese adds are summoned every ?s in groups of 2-4 to be offtanked. After ? these adds will ? to deal 400% more damage, so ~800 becomes 4k, modified by Shadron's aura. DPS will have to drop these as priority after they spawn and are picked up by the OT.\r\nThe major drake of issue is Shadron since everything in the encounter is fire damage. Vesperon is less an issue as your raid is better geared. First time groups like ours will take down all 3 drakes, making the encounter a tank and spank, minor add control and minor movement to avoid waves, like Heigan. Subsequent visits will leave Tenebron/Vesperon up.\r\nIf you leave the drakes alone, shortly after engaging Sardarion, the remaining drakes will come to Sardarion's aid and thus their auras come into play. Tenebron's aura will only impact the raid when they take the portal to deal with those disciples. Shadron's aura will be in play the rest of the time and Vesperon's will affect both (verify?).\r\nThe apparent strategy for leaving all 3 drakes in play with Sardarion requires having a group assigned to deal with the fire adds from Sardarion, as well as a subgroup to deal with the portals and their adds. We didn't test with all 3 up, so unsure if multiple drake portals can exist, but you can be caught with fire adds and portal disciples at the same time making for an interesting juggling match.\r\n==Drops==\r\nApparently the loot drops are modified by the number of drakes left standing when Sartharion is down:\r\n* '''Normal''': (10man)\r\n** 1 Drake up - Bonus ilvl 200 Item\r\n** 2 Drakes up - Bonus ilvl 213 item\r\n** 3 Drakes up - Reins of the Black Drake\r\n* '''Heroic''': (25man)\r\n** 1 Drake up - Bonus ilvl 213 item\r\n** 2 Drakes up - Bonus ilvl 226 item\r\n** 3 Drakes up - Reins of the Twilight Drake\r\n==Quotes==\r\nAggro:\r\n*It is my charge to watch over these eggs. I will see you burn before any harm comes to them!\r\nBerserk:\r\n*This pathetic siege ends NOW!\r\nBreath Attack:\r\n*Burn, you miserable wretches!\r\nFire Special:\r\n*Such flammable little insects....\r\n*Your charred bones will litter the floor!\r\n*How much heat can you take?\r\n*All will be reduced to ash!\r\nKill:\r\n*You will make a fine meal for the hatchlings.\r\n*You are at a grave disadvantage!\r\n*This is why we call you lesser beings.\r\nCall [[Shadron]]:\r\n*Shadron! Come to me, all is at risk!\r\nCall [[Tenebron]]:\r\n*Tenebron! The eggs are yours to protect as well!\r\nCall [[Vesperon]]:\r\n*Vesperon! The clutch is in danger! Assist me!\r\nDeath:\r\n*Such is the price... of failure...",},
			["Sartharion the Onyx Guardian"] = { content = "#REDIRECT [[Sartharion]]", redirect = "Sartharion",},
			["Sartura"] = { content = "#redirect [[Battleguard Sartura]]", redirect = "Battleguard Sartura",},
			["Sasquatch"] = { content = "The species of monstrous humanoid known as [[sasquatch]] is a cousin race to the [[wendigo]] of [[Northrend]]. These massive humanoid stands 9 feet tall. It looks vaguely ogre-like, but is covered in a furry, sandy-colored pelt. It has long, sharp claws and a hungry gleam in its eye. They are huge beings of limited intelligence and even less personality. They roam singularly and prefer solitary hunting. Sasquatch are incredibly strong and fiercely territorial. They have sharp claws and are very fond of human and orc flesh. Though they will eagerly kill elves who encroach on their territory, it is well established that sasquatch will not eat elven flesh, instead leaving their night elf victim's corpse where it falls, untouched. (Sasquatch seem to be able to distinguish between night and high elves, perhaps by smell, and have no problem devouring high elf flesh.)\r\nLike [[ogre]]s, sasquatch tend to solve problems by smashing them. Unlike ogres, they tend to avoid other creatures, unless it is to smash or eat them. They prefer forests, but will occupy any convenient location that provides them with food, treasure, and things to smash. Fortunately, Sasquatch mate only rarely. In groups, their aggression can be devastating to unprepared heroes. Sasquatch are matriarchal, and as a result, bands of Sasquatch typically represent a mother with her young, often only a single litter. Sasquatch are non-discerning in combat. They tend to use their claws and great strength in melee combat to rend their opponents.\r\n==See also==\r\n*[[Wendigo]]\r\n*[[Yeti]]",},
			["Satchel of Cenarius"] = { content = "The '''Satchel of Cenarius''' is a bag that will only hold [[herb]]s. This was the largest herb-bag in the game before [[TBC]].\r\n==Source==\r\nThis item is crafted with [[Tailoring]] (300); taught by [[Pattern: Satchel of Cenarius]], a [[Cenarion Circle]] reputation reward.\r\n==Notes==\r\nThis bag has been surpassed by the larger bags [[Mycah's Botanical Bag]] and [[Emerald Bag]]. This means that, for tailors, you no longer have to farm rep for Cenarion Circle if you want to make the largest herb bag in-game.",},
			["Sathera"] = { content = "'''Sathera''' was a high elven mage who was a close friend of [[Antonidas]]. She teleported into the [[Violet Citadel]]'s [[Arcane Vault]] when the alarm was sounded. It had been infiltrated by [[Teron Gorefiend]] and his [[death knights]], who had been sent by [[Ner'zhul]] to retrieve the [[Eye of Dalaran]]. Antonidas had been afflicted by some dark spell cast by one of the death knights, but Sathera lifted the spell, saving her old friend. Soon afterwards, one of the death knights targeted her and blasted her with dark magic. She withered before Antonidas' eyes, and fell to the ground, dead.\r\nShortly after, Teron Gorefiend and his death knights escaped with the Eye of Dalaran atop the backs of [[Deathwing]] and his [[black dragon]] brood.",},
			["Sathrovarr the Corruptor"] = { content = "'''Sathrovarr the Corruptor''' is a [[dreadlord]] and part of the first boss encounter of the [[Sunwell Plateau]] raid. He has possessed the [[blue dragon]] [[Kalecgos (tactics)|Kalecgos]], who fights players at Apex Point, above the Parhelion Plaza. While doing battle with Kalecgos, players will be transported to the Inner Veil, a shadowy realm where [[Kalec]] battles Sathrovarr in his [[half-elf]] form in an attempt to stave off his own corruption.\r\n==Quotes==\r\nAggro:\r\n*Gyahaha... There will be no reprieve. My work here is nearly finished.\r\nKill:\r\n*Pitious mortal!\r\n*Haven't you heard? I always win!\r\nSpell:\r\n*Your misery is my delight!\r\n*I will watch you bleed!\r\nBerserk:\r\n*I have toyed with you long enough!\r\nDeath:\r\n*I'm... never on... the losing... side...",},
			["Saturated Ooze"] = { content = "'''Saturated Ooze''' can be found in [[The Temple of Atal'Hakkar]] and [[Sunken Temple]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.12% Chance of a [[rare]] drop.\r\n1.68% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\n0.49% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Satyr"] = { content = "The original '''Satyr''' are the descendants of [[kaldorei]], typically [[Highborne]], who allied directly with the [[Burning Legion]] during the [[War of the Ancients (novel account)|first invasion]] ten thousand years before the [[First War]]. Unlike most Highborne, who aided the Legion simply to gain access to more magic, those who would become satyr embraced demonic power for its own sake and swore their allegiance to [[Xavius]], the first satyr. Xavius had been corrupted by [[Sargeras]] himself and had the power to turn other willing [[night elves]] into satyr.\r\nThese former elves were taken by the demons and twisted into shapes that more accurately reflected their nature. In place of their former sinewy elven bodies, they now possessed massive hairy forms, standing upwards of 9 feet tall. Their hands became claws, their feet replaced by cloven hooves and horns sprouted from their head. Even after the destruction of the [[Well of Eternity]], the satyr continued to serve the Legion, working to corrupt the land and pave the way for a second invasion. During the [[Third War]], the satyr fought with the Legion and the [[Scourge]] against the [[Horde]] and the [[Alliance]]. Satyr are often found guarding corrupted [[moonwell]]s. The satyrs tend these moon wells corrupted with demonic energy. It is said that these pools are the source of new satyrs, transforming night elves into the twisted minions of the Legion. No one knows if corrupted moon wells work similar transformations in other species. Though [[high elf]] satyrs are rare, they do exist. Non-elves may not differentiate between high elf and night elf satyrs, but elves and satyrs claim the differences as clear as night and day. In the years since the War of the Ancients, other races have also joined the ranks of the satyrs, including; [[goblins]], [[orcs]], [[half-elves]], high elves & [[blood elves]], and low common speaking races. It may be possible for members of nearly every race to become satyrs. A critical hit from the [[Xavius|Dirk of the Beast]] can transform others into Satyr, regardless of race. The black magic invoked in the transformations is known as the [[shadow curse]].\r\nThe satyr still work to spread corruption and death, and are especially prevalent in [[Felwood]], though they inhabit most of regions of northern Kalimdor, around Mount Hyjal. Most satyr are capable of using [[warlock]] magic as well. They are the most hated enemy of the Night elves, but are hostile to just about every other natural race in Azeroth as well. Satyrs are immortal.\r\n==Culture==\r\nSatyrs possess little culture. Their society is loosely hierarchical, and they are organized into groups. Each group is called a \"sect\". A sect of satyrs lives in the same geographical region and has a specific mission. Satyrs of different sects get along only some of the time. They live in ruins scattered throughout northern Kalimdor and Desolace; satyrs prefer places of corruption to make their homes, such as Felwood and certain areas of Darkshore. Their sects are small, usually no more than a hundred individuals. Satyrs are cruel and sadistic creatures. They enjoy tormenting other creatures, particularly intelligent ones. Satyrs patrol their territory, hoping they can find travelers they can eviscerate in the most bloody manner possible. They operate at a faster level than their former selves — while before they may have been stately and calm, they now burn with feverish energy. Their movements are swift and jagged, like predators sensing prey.\r\n==Military==\r\nSatyrs are organized only loosely, into a variety of sects. When the alarm sounds, all members of a sect throw themselves into battle. Like all demons, when the Legion calls, they scramble to obey.\r\nFew creatures clash with satyrs on their own territory, however. Satyr camps are well hidden and often located in areas already dangerous, like Felwood. They are also well protected; only army divisions or powerful adventurers could hope to rampage through a satyr community. Thus, most encounters with satyr forces occur elsewhere — often on the roads and paths through the forests.\r\nSatyrs have no sense of honor, especially concerning warfare. They do whatever is necessary to destroy their opponents, preferably causing a good deal of pain — both physical and psychological — at the same time. They prefer ambushes and scare tactics, perhaps stalking a group for several days, leaving subtle clues to their presence to make their prey more and more paranoid and fearful; then they strike. They enjoy incapacitating their enemies with nets and dark magic so they can carve them up at their leisure; they also enjoy the fear and panic they cause when they weaken and capture and bleed instead of outright kill.\r\nFew satyrs become warriors or barbarians, so they don’t possess the tough, front line soldiers that other forces do. In their strongholds they rely on corrupted ancient protectors to serve in this capacity; but when they strike out at others, they are weak in this area. Many satyrs become rogues, and this disparity is one reason they prefer ambushes and guerilla tactics — hopefully, satyr rogues can incapacitate enemy warriors soon after combat is joined, thereby leaving them free to strike at vulnerable spellcasters and war machine crews.\r\nSatyr rogues who distinguish themselves — or show a certain penchant for painful traps and ambushes — are called satyr tricksters. Satyr ranged support usually comes from magic. A few satyrs become necromancers or warlocks; some become dark spellcasters called soulstealers or hellcallers. Satyr rogues are fairly common. Some rogues take some training as warlocks in order to add some curses to their repertoire; these individuals are called shadowdancers. Warlocks, necromancers, hellcallers, and rogues work well together; the rogues dart in to disembowel their enemies while the spellcasters summon reinforcements, enhance their allies, hamper their enemies, and call up blasts of entropic flame.\r\n==Names==\r\nSatyr naming practices are similar to those of their original race, but focus on their unique and corrupt natures. Their surnames often develop from their evil deeds, while some go without surnames. A few satyrs don’t change their names after their transformations.\r\n*Male Names: Zalan, Delmanis, Makron, Zevrim.\r\n*Female Names: Akhzor, Marigore, Nektis, Zydaxxis\r\n*Tribe Names: Banebreath, Darkthought, Thornhoof, Vileclaw.\r\nThere are many tribes (sects) of satyr on Kalimdor, though how exactly and why are they distinct from each other, is hard to tell:\r\n* The Hatefury, in [[Desolace]]\r\n* The Jadefire, in [[Felwood]]\r\n* The Deth'ryll, in [[Darkshore]]\r\n* The Putridus, in [[Maraudon]]\r\n* The Wildspawn, in [[Dire Maul]]\r\n* The Felmusk, in [[Ashenvale]]\r\n* The Bleakheart, in [[Ashenvale]]\r\n* The Fallenroot, in [[Blackfathom Deeps]]\r\n* The Haldarr, in [[Azshara]]\r\n* The Legashi, in [[Azshara]]\r\n* The Nazzivus, at [[Bloodmyst Isle]]\r\n* The Axxarien, at [[Bloodmyst Isle]]\r\n* The Xavian, in [[Ashenvale]]\r\n* The Illidari, in [[Shadowmoon Valley]], [[Black Temple]]\r\n* The Sargeron, in [[The Arcatraz]]\r\n* The Nethervine, in [[The Botanica]]\r\n* The Shadowhoof, in [[Shadowmoon Valley]]\r\nAlthough satyr are usually thought of as a race of [[demon]]s, some unique satyr are classified as [[humanoid]]s for inexplicable reasons. It is possible that these satyr have somehow established a spiritual connection with [[Azeroth]], or that they have severed their bond with their demonic masters. Or it might just be a mistake on Blizzard's part. However, satyrs encountered in WC3 and RPG material related to that era were treated as humanoids, so humanoid satyrs may exist.\r\n===Languages===\r\nSatyrs speak Eredun, and whatever was the primary language of the satyr's former life. Darnassian, Low Common, Goblin, Orcish, and Thalassian are often secondary languages (unless one of these was the satyr's primary language in his former life then it remains one of their primary languages). Satyrs pick up the languages of their enemies and those creatures who they might find useful.\r\n===Humanoid satyr===\r\n*[[Bazzalan]], [[Ragefire Chasm]]\r\n*[[Sethir the Ancient]], [[Teldrassil]]\r\n*[[Zenn Foulhoof]], [[Teldrassil]]\r\n===Demonic satyr===\r\n*[[Xavius]]\r\n*[[Vyletongue]], [[Maraudon]]\r\n*[[Vorlus Vilehoof]], [[Teldrassil]]\r\n*[[Zevrim Thornhoof]], [[Dire Maul]]\r\n*[[Twilight Corrupter]], [[Duskwood]]\r\n*[[Alzzin the Wildshaper]], [[Dire Maul]]\r\n*[[Delmanis the Hated]], [[Darkshore]]\r\n*[[Geltharis]], [[Ashenvale]]\r\n*[[Xabraxxis]], [[Darkshore]]\r\n*[[Lord Melenas]], [[Teldrassil]]\r\n*[[Aligar the Tormentor]], [[Darkshore]]\r\n*[[Balizar the Umbrage]], [[Darkshore]]\r\n*[[Caedakar the Vicious]], [[Darkshore]]\r\n*[[Thorngrin the Tender]], [[Tempest Keep]]\r\n*[[Terestian Illhoof]], [[Karazhan]]\r\n*[[Xandivious]], [[Winterspring]]\r\n*[[Xavaric]], [[Felwood]]\r\n*[[Xavathras]], [[Felwood]]\r\n*[[Prince Xavalis]], [[Felwood]]\r\n==Locations in World of Warcraft==\r\n*[[Ashenvale]]\r\n**[[Xavian]]\r\n**[[Satyrnaar]]\r\n**[[Night Run]]\r\n*[[Azshara]]\r\n**[[Haldarr Encampment]]\r\n**[[Legash Encampment]]\r\n*[[Felwood]]\r\n**[[Jadefire Glen]]\r\n**[[Jadefire Run]]\r\n**[[Ruins of Constellas]]\r\n*[[Bloodmyst Isle]]\r\n**[[Axxarien]]\r\n**[[Nazzivian]]\r\n==Units from the Blizzard Monolith Frozen Throne Scenario==\r\n* Heroes\r\n** [[Satyr Incinerator]] \r\n* Buildings\r\n** [[Satyr Portal]] (provides food, returning point for resources, trains all Satyrs and revives hero)\r\n* Moving Units\r\n** [[Satyr Gimp]] (worker unit)\r\n** [[Satyr]]\r\n** [[Satyr Hellcaller]]\r\n** [[Satyr Shadowdancer]]\r\n** [[Satyr Soulstealer]]\r\n** [[Satyr Trickster]]\r\n==See also==\r\n* The [[Origin of the races]]\r\n* [[Highborne]]",},
			["Satyrnaar"] = { content = "'''Satyrnaar''' is located in northeastern [[Ashenvale]], northeast of [[Splintertree Post]] and southwest of [[Forest Song]]. It is one of the three Ashenvale [[satyr]] settlements, the other two being [[Night Run]] and [[Xavian]]. Of the three, Satyrnaar is the most intact and centrally located, boasting several tents among the ruined buildings as shelter for the satyr who live there. It the easiest of the satyr settlements to get to, as it is located just off the main road from Splintertree towards Azshara. As such, it is also the most contested of the three satyr ruins.",},
			["Satyrs"] = { content = "#REDIRECT [[Satyr]]", redirect = "Satyr",},
			["Satyr Gimp"] = { content = "The '''{{PAGENAME}}''' is a satyr used in the Blizzard [[Warcraft III]] 'Monolith'. Because of the power of the Monolith which has been attracting wildlife with its mysterious energies, it allows a Satyr gimp to gather gold and summon portals. A Satyr Gimp is the lowest level of Satyr in [[Warcraft III]] costing One food and 50 gold and is classified as a worker. A Satyr Gimp can build [[Satyr Portal]]s allowing it to summon more of their brethren from the underworld for combat purposes and Monolith shards, becoming the Satyrs only form of defensive structure. The appearance of Gimps are much smaller than other satyrs, and have a tint of green to their skin.",},
			["Satyr Hellcaller"] = { content = "The Satyr Hellcaller is the strongest Satyr in [[Warcraft III]]. It is a strong melee unit with deadly spells, such as Animate Dead, Unholy aura and bloodlust. This Satyr has 1100 Hitpoints and 500mana. the reason this unit is the top of the ranks in satyrs it because of its spells and its attack of 49-55 Chaos Damage, making him a deadly opponent.",},
			["Satyr Incinerator"] = { content = "The '''{{PAGENAME}}''' only appears in the [[Warcraft III]] map 'Monolith' and is seen as the hero for this race. It attacks land and air units, and because it is the only 'hero type' unit for the race, it comes free of charge but will cost the player five food, With the description \"The Satyr Incinerator has a fascination with fire which other satyrs find unnerving\". Its seen as a medium sized, Agility based satyr, with a tint of orange in the skin and surrounded by fire. It is able to learn Firebolt, Flame Strike, Breath of Fire and Inferno. The Incinerator also comes with Permanent Immolation, explaining the Fire that surrounds him.",},
			["Satyr Portal"] = { content = "A '''{{PAGENAME}}''' is only able to be built on the [[Warcraft III]] map 'Monolith' by a [[Satyr Gimp]] which has drawn power from the Mysterious Monolith. A Satyr portal takes shape of the aura 'Unholy Aura' and provides 20 food to the player, it also has 1200 hit points making it difficult to destroy quickly, but cheap to construct needing on 180 gold. The Structure summons seven types of Satyr from Warcraft3 known as [[Satyr Gimp]], [[Satyr]], [[Satyr Trickster]], [[Satyr Shadowdancer]], [[Satyr Soulstealer]], [[Satyr Hellcaller]] and [[Satyr Incinerator]].",},
			["Satyr Shadowdancer"] = { content = "The '''{{PAGENAME}}''' is a sly Satyr, and is one of the medium sized satyrs. It is a light ranged satyr with 23-27 Piercing Damage, but only has 340 Hit points and 300 mana. The Shadowdancer is able to cast Curse on its opponents, giving them a 33% chance to miss their attack, and is able to hide with shadowmeld during the night. The use of Shadowmeld indicates the link between the satyrs and Night Elves.",},
			["Satyr Soulstealer"] = { content = "The '''{{PAGENAME}}''' is a medium melee unit, with 600 hit point and 400 mana. This Satyr has a strong variety of spells including Mana burn and Raise dead. It can only attack land units and has 24-27 Normal Damage. It is one of the more bigger Satyrs, and his a tint of orange/red to its skin.",},
			["Satyr Trickster"] = { content = "'''Satyr tricksters''' are the satyr version of the [[contender]]. They are satyr rogues who distinguish themselves — or show a certain penchant for painful traps and ambushes. Satyr tricksters revere and mimic Lord Xavius' manipulations of his enemies.",},
			["Saurfang's Blessing"] = { content = "==Objectives==\r\nDeliver the letter to [[Thrall]], Warchief of the [[Horde]] at [[Orgrimmar]].\r\n* To Thrall, Warchief of the Horde (Provided)\r\n==Description==\r\nYou are now, and forever will be, a [[Knights of the Ebon Blade|Knight of the Ebon Blade]], <name>, but know this: you were once a hero of the Horde.\r\n<[[Darion Mograine|Darion]] stares at you.>\r\nThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Horde.\r\nOn the platform, southeast of me, is a portal to Orgrimmar. Take this letter, given to me on your behalf by [[Tirion Fordring|Lord Fording]], and deliver it to Thrall. Use the portal.\r\n==Progress==\r\nAn interesting turn of events.\r\n==Completion==\r\n[[Eitrigg]] is alive because of this paladin. He would have been executed had Lord Fordring not broken him out of [[Stratholme]].\r\nTirion Fordring, to have sacrificed everything to save the life of an orc... I have ever only known one other human to make such a sacrifice.\r\n<Thrall blinks back a tear.>\r\nYou will be in my heart always, [[Taretha]].\r\nYes. For Tirion Fordring and for Eitrigg! We will accept you as a member of the Horde and your order as allies.\r\nBlood and honor! For the Horde!\r\n==Notes==\r\nPlayers will find themselves outside the gates of a very unfriendly Orgrimmar. Any and all NPCs will show their displeasure and call for a rope or spit or throw rotten food. Thrall himself tells the player that it is an interesting turn of events before handing in the letter.\r\nOn completion:\r\nThrall yells: Horde, hear the call of your Warchief!\r\nThrall yells: Today marks the first of many defeats for the Scourge! Death knights, once in service of the Lich King, have broken free of his grasp and formed a new alliance against his tyranny! \r\nThrall yells: You will welcome these former heroes of the Horde and treat them with the respect that you would give any ally of Orgrimmar! \r\nThrall yells: For the Horde!",},
			["Saurfang"] = { content = "#redirect [[Varok Saurfang]]", redirect = "Varok Saurfang",},
			["Saurfang facts"] = { content = "This article contains \"true\" facts about [[High Overlord Saurfang]]. They started after he revealed his greatness leading the [[Might of Kalimdor]] in the [[Gates of Ahn'Qiraj]] event, and expanded via the infamous [[Barrens chat]].\r\nFacts must be Warcraft-related, must not be repeated from facts already in the list, and must use good, concise, English grammar. Incoherent, un-funny, or facts which are similar to another will be edited out. Facts must also be 'appropriate' (see talk page). \r\n==Abilities, attributes, and behavior==\r\n*Saurfang once used Whirlwind the result is now called the maelstrom\r\n*Saurfang uses the Old Gods as punching bags.\r\n*Whenever a nerf occurs, High Overlord Saurfang grows in power.\r\n*Whenever an Alliance raid attempts to kill High Overlord Saurfang, he cleaves them all in one shot, and then gives them a de-buff known as \"Rejection\". This de-buff destroys all of the player's armor, reduces their stats to -100, and constantly gives them fatigue. It also lasts 3 hours and persists through death.\r\n*High Overlord Saurfang's level has recently been changed from 72 to 82. This is not an actual reflection of his level, but rather a more accurate update, since 82 is closer to infinity.\r\n*Saurfang was born at 13:37o'Cleave.\r\n*The Saurfangs frown on bad facts and such behavior.\r\n*High Overlord Saurfang doesn't mourn the loss of those close to him; he considers them lucky not to have died by his own hand.\r\n*If a tree falls in the forest, it screams from agony since Saurfang cleaved it.\r\n*Saurfang doesn't eat pork.\r\n*Saurfang’s cleave is his auto attack\r\n*Saurfang’s cleave is so unimaginably powerful that it instantly obliterates anything that is imaginable; the cleaving come as fast as the thinking.\r\n*Saurfang doesn’t need a flying mount for Tempest Keep instances; they fly to him instantly as and when he want it.\r\n*After distillation, 100% Saurfang becomes 100% Saurfang. We tried to determine the potential of the new Saurfang by running some tests. The method involves cleaving and none of our test subjects get past one shot. We hereby conclude that old Saurfang = new Saurfang = pure awesomeness.\r\n*The only reason High Overlord Saurfang does not cleave every rookie Horde [[Death Knight]] who comes to see Thrall is because three top Death Knight talents were originally named Might of [[Mograine|Saurfang]], Guile of [[Teron Gorefiend|Saurfang]] and Rage of [[Baron Rivendare|Saurfang]]. Blizzard had to change it because Saurfang is a modest person and cleaves anyone who dares to disagree.\r\n*High Overlord Saurfang can wield [[Axe of the Gronn Lords]] not only with just one hand but with only just one finger.\r\n*High Overlord Saurfang's [[Death Knight]] alt does not need any diseases or runes to use [[Obliterate]]. It just replaces his autoattack.\r\n*High Overlord Saurfang can move when [[Shade of Aran]] casts Flame Wreath. Unfortunately, Shade doesn't last long enough to cast it, we just have to take Saurfang's word on this.\r\n*High Overlord Saurfang can make a triple play in Baseball, with only the batter and one other runner.\r\n*[[Arthas Menethil]] only killed 100 of Stratholme's 25,000 Citizens, what happened to the rest? Saurfang cleaved them. \r\n*When High Overlord Saurfang uses [[Intimidating Shout]] on you, you don't just run away in fear. You awake from unconsciousness several hours later with your pants soiled, your weapon broken, and in the next zone over from where he cast it. \r\n*Once, High Overlord Saurfang became slightly angered after a stealthed gnome in Orgrimmar thought it would be funny to /spit him. Saurfang Intercepted the gnome, throwing him across the globe to Blackrock Mountain, where he was eaten alive by The Beast.\r\n*High Overlord Saurfang doesn't need to eat, drink, defecate or other mortal measures; he just does it sometimes because he wants to.\r\n*High Overlord Saurfang never kills [[Gamon]]; Gamon just kills himself if Saurfang wants.\r\n*The level shown in High Overlord Saurfang's portrait is just there because his real level is not fit for mortal eyes.\r\n*Saurfang doesn't need mounts, sprints or any speed enhancement stuff; he just APPEARS.\r\n*Titan's Grip was originally planned to be named Saurfang's Grip, but Blizzard didn't want to imply he could only use two 2-handers at once, so they changed the name.\r\n*Once, out of boredom Saurfang tried to kill himself. The servers were down for a week.\r\n*Despite what many people say about him, Saurfang does not raid. The bosses die before he even shows up.\r\n*Chuck Norris and Mr. T are actually Saurfang in disguise.\r\n*There is no Cow Level. At least, until Saurfang went there.\r\n*The Plaguelands were created when Saurfang did a /burp emote in northern Lordaeron.\r\n*High Overlord Saurfang doesn't swear. Curse words are too afraid of him.\r\n*The [[Infinite Dragonflight]] aren't the ones screwing up the Caverns of Time. It's actually Saurfang in disguise.\r\n*Saurfang is in your bedroom, wearing your watch.\r\n*In a fight between Saurfang and Saurfang, Sargeras would lose.\r\n*High Overlord Saurfang doesn't have a respawn timer. He doesn't need one.\r\n*Saurfang's hearthstone crits for 1337 damage.\r\n*Saurfang vendors [[Head of Nefarian]].\r\n*Saurfang is too mighty for mere flags. When he fights in [[Warsong Gulch]], he runs back to the Horde Base with Darnassus tied on a stick.\r\n*If High Warlord Saurfang uses something that triggers the GCD, everyone in a 50,000 yard radius gets the GCD instead.\r\n*Saurfang doesn't actually wear armor, what you see is his skin.\r\n*When High Overlord Saurfang says \"It's Peanut Butter Jelly Time!\", every damn player and NPC on Azeroth sits down and eats a peanut butter and jelly sandwich, except for Tauren males, who start dancing.\r\n*High Overlord Saurfang can use a bow, and he uses axes as ammunition.\r\n*No one has ever seen Saurfang's angry face, because his cleave moves faster than his facial expression can change.\r\n*High Overlord Saurfang once learned Soul Link by punching a demon in the face.\r\n*High Overlord Saurfang has infinite talent points. He has spent 20.\r\n*Saurfang's Taunt is completely useless, as nothing on Azeroth is stupid enough to focus all of their attention on him.\r\n*High Overlord Saurfang is the only being in existence to have survived Tirion Fordring's Reckoning Bomb.\r\n*Saurfang once asked for [[Enchant Weapon - Major Intellect]] on his axe. No one dared ask why.\r\n*Overlord Saurfang is only afraid of one thing... .\r\n*Saurfang will be able to play the hero class \"Bard\".\r\n*Saurfang needs no healers. He needs no one to tank for him. He's the one-man raid who will take Sargeras down. While sleeping and with one hand tied behind his back.\r\n*Saurfang will once, and only once kneel down to anything. It will be to loot Sargeras. You have been warned.\r\n*When Saurfang drinks [[Darkmoon Special Reserve]], his perception of your level doesn't decrease; your level actually decreases.\r\n*Officially, High Overlord Saurfang is exalted with the Horde and the Alliance at the same time, but that's because Thrall and the Alliance Lords couldn't afford to be at war with him. Even so, he hates both sides to keep his rage bar full.\r\n* When Saurfang was level 10, he joined the queue for Warsong Gulch. When he entered, he was level 72. His first cleave cleaved the battlefield in half, his second killed both Spirit Guides, his third killed everyone else.\r\n*Any attempt to [[Shield Wall]] against Saurfang results in a broken shield and a cleaved face.\r\n*Saurfang eats gnomes and craps out cleaves.\r\n*Saurfang whistles in Darnassian.\r\n*High Overlord Saurfang doesn't actually have a rage bar... instead the bar below his health is actually a new measure of power not implemented yet. The only reason it isn't implemented is because Blizzard was afraid that putting a numerical measure of Saurfang's awsomeness would cause a paradox.\r\n*Once, High Overlord Saurfang used Cleave while affected by [[Sweeping Strikes]]. The attack caused a chain reaction of attacks that slaughtered every single gnome in a 700 mile radius.\r\n*You know, it's not [[Kil'jaeden]] who Kael is trying to summon from the Sunwell. It's actually Saurfang.\r\n*In reality, Saurfang has already killed all of us. It's just that his attack is so powerful it creates an alternate universe where it seems that we are still alive.\r\n*In a base defense game, Saurfang is a tower class.\r\n*If Saurfang were your pet, he'd dismiss you.\r\n*Saurfang's rage stays at 100. \r\n*Saurfang's class is not 'Warrior', it's actually 'Saurfang'.\r\n*When High Overlord Saurfang does a pushup, he isn't lifting himself up, he's pushing the universe down. \r\n*If Saurfang killed himself everyone else would die instead.\r\n*Saurfang can kill a player in a duel before the 3 second countdown is finished.\r\n*Saurfang can swim from Kalimdor to Eastern Kingdoms in a single stroke. \r\n*High Overlord Saurfang can use Shield Bash, Shield Block, Shield Wall, Shield Slam, Spell Deflection, and Intervene all at the same time...without using a shield.\r\n*Saurfang doesn't get Mind Controlled. He gets so bored when he fights that he falls asleep and sleep walks. \r\n*Saurfang is immune to the looks change that comes with Blix's Eyesight Enhancing Romance Goggles. And your face will get cleaved if you even THINK why that's so.\r\n*If Saurfang cleaves you, you do not lose 10% durability. You will lose all your armor, and will be unable to return to your corpse because the pieces will be too far apart from each other to rez all at once. You cannot even create a new character, as the cleave has already killed any character you've ever had or ever will have.\r\n*The green glow around Saurfang’s weapon is actually a poison. When one is affected by this poison, they feel as if they were continuously being cleaved in the face until the excruciating pain causes them to commit suicide. However, no one has ever been infected with it because Saurfang’s cleaves are always fatal.\r\n*Saurfang does not have every profession; Saurfang ''is'' every profession.\r\n*Saurfang once visited Drek'Thar in Alterac Valley; the result caused the entire Alliance and Explorer's League forces to execute a full retreat.\r\n*High Overlord Saurfang's Cleave is so powerful that it can be seen from Outland by the naked eye.\r\n*High Overlord Saurfang can kill two stones with one bird.\r\n*High Overlord Saurfang has never been to a dentist\r\n*High Overlord Saurfang once thought he was a goat\r\n*High Overlord Saurfang always has a full Rage bar, because he is permanently pissed.\r\n*High Overlord Saurfang is always Out of Combat, because any opposition made against him is considered too trivial and one-sided to be considered as actual combat.\r\n*High Overlord Saurfang can never fight honorably, because every kill he makes is considered a [[Dishonorable Kill]].\r\n*Items cannot be soulbound to High Overlord Saurfang. He has no soul.\r\n*High Overlord Saurfang collects only the heads of dragons. He eats the rest. \r\n*When High Overlord Saurfang AFK's out of a Battle Ground, YOU get the deserter buff. \r\n*\"Hardcore\" is a word to describe the flesh of High Overlord Saurfang. No other word has been invented so strong or descriptive enough to describe what lies beneath that entire hide.\r\n*High Overlord Saurfang wasn't killed, he feigned death because Kruul wasn't worth his time.\r\n*Blizzard once tried to nerf Saurfang but changed their mind after he murdered the programming team.\r\n*High Overlord Saurfang IS prepared.\r\n*High Overlord Saurfang always knows the EXACT location of [[Kranal Fiss]], [[Stolen Silver]] and [[Mankrik's Wife]].\r\n*THERE ARE NO LEGENDARY WEAPONS IN OUTLAND!!...Saurfang lives in Orgrimmar.\r\n*High Overlord Saurfang wasn't actually trying in Silithus. If he had been, no one else would have been able to fight.\r\n*High Overlord Saurfang is the REAL faction leader of the Horde... Thrall is just the peon who cleanses his cave and picks up the skeletons of the floor.\r\n*High Overlord Saurfang does not use weapons, armor, or any other type of equipment. What we see is just a manifestation of his absolute awesomeness.\r\n*High Overlord Saurfang is not affected by resurrection sickness since 75% of infinity is still infinity.\r\n*Saurfang gets the \"Your target is dead\" message any time he tries to use a skill on anyone, because if he's targeting you, you're already done for. \r\n*If Saurfang were to open a trade window with you, all your gold would instantly be sent to him.\r\n*Saurfang doesn't have crits. If he did, WoW would have many major server crashes, due to the fact that Saurfang's attacks make enough lag already.\r\n*Saurfang doesn't fall off Outland. Outland falls off Saurfang.\r\n*Saurfang overaggroed the Shade of Aran\r\n*High Overlord Saurfang is immune to Rick Roll.\r\n*SAURFANG IS PREPARED!\r\n*High Overlord Saurfang is never late, nor is he early. He arrives precisely when he means to.\r\n*High Overlord Saurfang's awesomeness is OVER 9000.\r\n*High Overlord Saurfang can kite a critter.\r\n*It is rumoured that High Overlord Saurfang has an enrage timer. The fact that we are all still alive, however, is proof that no one fighting Saurfang has yet survived long enough for said enrage to happen.\r\n*High Overlord Saurfang doesn't really have a whirlwind, he is just spamming his cleave so fast that it looks like a whirlwind.\r\n==Impossibilities==\r\n* High Overlord Saurfang IS prepared.\r\n* When Saurfang /kicks or /gkicks someone, their account disappears. When he /gdisbands, the servers go down. \r\n*If you ever insult High Overlord Saurfang, he will cleave you; hunt down your ghost, cleave it; hunt down your account, cleave it; hunt you down in life, cleave you in life; and cleave every trace of your existence from the fabric of space and time.\r\n*Chuck Norris is High Overlord Saurfang's abandoned level 1 alt.\r\n*High Overlord Saurfang knows the Question to Life, the Universe, and Everything.Too bad he won't tell you.\r\n*[[Draenor]] was actually ripped apart when High Overlord Saurfang had a temper tantrum because [[Ner'zhul]] scratched his axe.\r\n*[[Malygos]] threatens to destroy all spellcasters except Saurfang. Both because he is technically not a spellcaster, and because he knows if Saurfang kills him, he won't respawn later.\r\n*Saurfang can both see and attack creatures that are out-of-phase.\r\n*One Old God can make Sargeras cry for mercy. Saurfang can make an Old God cry for mercy by unsheathing his axe. However, the last time Saurfang unsheathed his axe, the sun glinting off it turned Tanaris into a desert.\r\n*High Overlord Saurfang was the first to know that Blizzard´s secret project was Diablo III, even before Blizzard itself.\r\n*Saurfang uses the [[Jormungar]] worm as Dental floss.\r\n*High Overlord Saurfang didn't need to sign up for the Beta.\r\n*The fastest leveling record was set by Saurfang. This occurred so fast that he BROKE the limit. \r\n*Saurfang taunted Happy Fun Ball.\r\n*High Overlord Saurfang once attacked a rogue with cheat death on, the rogue still died in one hit.\r\n*If you somehow managed to polymorph Saurfang, you'd be the first person in WoW to be killed by a sheep.\r\n*The only known way to survive a Saurfang cleave is for High Overlord Saurfang to have rez sickness when he cleaves you. Too bad he can't die.\r\n*High Overlord Saurfang can \"Pop\" Enrage.\r\n*Saurfang can put Cleave, Sunder Armor, Thunder Clap, and Eviscerate into one macro, and use it at will even though the last isn't even a warrior skill. This is because no rogue trainer is stupid enough to refuse to teach him.\r\n*Saurfang take candle.\r\n*Saurfang CAN cast Fireball, Flamestrike, Fire Shock, Scorch, Immolate, Rain of Fire, Blast Wave, and Dragon's Breath with his rage bar.\r\n*Saurfang CAN wield wands. They shoot cleaves.\r\n*Saurfang CAN stealth. It's just that you can't see it.\r\n*A druid tried to cast Entangling Roots on Saurfang. He pulled them out of the ground and uprooted Orgrimmar.\r\n*High Overlord Saurfang can use [[Spell Reflection]] against the use ability of [[Martin Thunder]].\r\n*GMs have concluded that if [[The Unstoppable Force]] and [[The Immovable Object]] were to collide, there would be no survivors... except for Saurfang.\r\n*Although impossible, if you were to dodge one of High Overlord Saurfang's attacks, he'd be mildly aggravated and kill you twice on the spot.\r\n*Saurfang DOES know the location of the cow level, and beat it 42 times.\r\n*High Overlord Saurfang enchanted his High Warlord's Greataxe with Agility because he can. \r\n*Saurfang can Execute his enemy at 100% Health. Just to save him time.\r\n*High Overlord Saurfang considers \"Two-Hand\" to just be a suggestion for his weapon, not a requirement. \r\n*High Overlord Saurfang doesn't appear to have a mount, but look closer -- everything on the planet is standing on it.\r\n*Saurfang cannot target anything, because him concentrating on a single thing would cause massive server crashes.\r\n*Saurfang can roll a level 1 Death Knight, even before [[Wrath of the Lich King]] was released.\r\n*If someone somehow found Saurfang's TCG Card, they and anyone else who saw it would be erased from existence because Saufang's card is not fit for mortal eyes.\r\n==Relations with other characters==\r\n*Thottbot once tried to upload High Overlord Saurfang to their database. The resulting explosion created Wowhead as an accidental by-product of his awesomeness.\r\n*Saurfang the younger is level 1336 because he's not L33T enough to be level 1337.\r\n*The reason Saurfang the Younger can be killed (This task alone requires a 42 man raid group with atleast 20 healers with over 2,000 healing) is cause High Overlord Saurfang has only spent 2 minutes with his son.\r\n*The only time Orgrimmar was attacked was when Saurfang went to the Caverns of Time to kill his past self. The reason he still exists is the same as why no one has seen Nozdormu in years.\r\n*Grom once dared Saurfang to surgically remove his own eye with his axe. This is why he is now known as Hellscream.\r\n*The reason [[Hogger]] is so powerful is because Saurfang says so.\r\n*Saurfang farted behind [[Al'Akir]] who was behind [[Ragnaros]] which caused alot of Azeroth to be burnt, thus making the [[Burning Steppes]], [[Searing Gorge]] and the [[Badlands]]\r\n*Ysera heard a rumor that Saurfang was coming for her. The Emerald Dream started becoming the Nightmare that day.\r\n*Varimathras didn't kill Balnazzar because he was still loyal to him, he only defeated him because Saurfang had dibs on him, and NOBODY CROSSES SAURFANG!\r\n*Kel'Thuzad is moving to Northrend because Saurfang finally decided to kill him and destroy his phylactery. But Saurfang became aware of this and now he, too, is going to Northrend.\r\n*In Tales of the Past III, Arthas didn't kill Saurfang. Saurfang merely fell asleep from boredom.\r\n*When in the end of the first WotLK trailer Arthas said \"in the end, all must serve the one, true king\" he actually referred to Saurfang.\r\n*[[Kil'jaeden]] wasn't sucked back in by the Sunwell. When he decided to come out and send all raid members to hell, he saw Saurfang and retreated. However, he left his pendant behind to please Saurfang.\r\n*Nightbane is Saurfang's Dragon-kite.\r\n*Saurfang once cleaved Echo of Medivh in the face for cheating in a game of chess.\r\n*Archimonde lied when he said that doom had come to world. It came when Saurfang was born.\r\n*Deathwing is hiding because of Saurfang.\r\n*Saurfang stares C´thun down.\r\n*Sargeras isn't trapped in the Twisting Nether, he's just too afraid of High Overlord Saurfang to set foot on land.\r\n*Before Saurfang cleaved him, he used to be known as Cookie McAwesomelyStrongSauce.\r\n*Jaina is currently cheating on Thrall with Saurfang. Thrall knows, but is too afraid of Saurfang to say anything.\r\n*Cairne called High Overlord Saurfang crazy; the result gave him his name of \"Bloodhoof\".\r\n*The Four Horsemen of Naxxramas actually live in Saurfang's nut sack.\r\n*Ivus the Forest Lord Is Saurfang's firewood.\r\n*Saurfang really killed Mannoroth, while practicing his Throwing Axe skill it carved from Orgrimmar through the mountain and struck the demon in the chest.\r\n*If High Overlord Saurfang was a hunter he would tame [[Omen (boss)|Omen]], if he was a warlock, he would enslave [[Doom Lord Kazzak]], if he decided to go to Outland, [[Nefarian]] would be his flying mount. \r\n*Kil'Jaeden sent Illidan instead of Saurfang to destroy the Lich King because he was afraid that after Saurfang was done with the Lich King, he'd come for him next.\r\n*High Overlord Saurfang is currently suing The Lich King, claiming that The Scourge was already the trademarked name for his teeth. \r\n*Arthas was actually the Lich King's second choice... High Overlord Saurfang mocked his request.\r\n*Once High Overlord Saurfang used Hamstring on Wirt and sliced his leg off, because Wirt insisted there was no cow level.\r\n*The Horde would have gotten High Overlord Saurfang to destroy Archimonde with one blow but they were too scared to wake him up.\r\n*When Archimonde used to yell \"None can stand before the Burning Legion!\" he made sure not to say it too loud, in case High Overlord Saurfang took offense.\r\n*At first, Thrall considered High Overlord Saurfang to accompany him in killing Mannoroth, but Saurfang refused, claiming that Mannoroth simply wasn't worth the effort.\r\n*Once known as Screamer, he was reduced to Murmur after meeting Saurfang.\r\n==Things coming from Saurfang==\r\n*The Netherstorm used to be a single rock attached to Blade's Edge Mountains. That is, until Saurfang used his Cleave there.\r\n*Saurfang's favorite number is 1337.\r\n*Has anyone tried to kill Saurfang? Yes, Mankrik's Wife has, though now she is known as \"Beaten Corpse\".\r\n*[[Forest Trolls]] are really [[Goblins]] trained by Saurfang.\r\n*If Saurfang says there is no [[Cow Level]], then there damn well better not be a Cow Level!\r\n*20% of [[Fel Iron]] is made out of bits of Saurfang's bacteria.\r\n*Kael'thas didn't create the Sunwell by emptying his vial of the Well of Eternity into, Saurfang just needed to wash up after a day of cleaving the Alliance, and that fountain was the closest thing to him.\r\n*High Overlord Saurfang once met someone who questioned his right as High Overlord. The [[Master's Glaive]] is a result of this.\r\n*Saurfang once urinated on Onyxia's Lair's front doorstep to express his disdain for her. The resulting acidic reactions turned Dustwallow Marsh from a beautiful land of rolling green hills into the dive it is today.\r\n*One day, High Overlord Saurfang decided that he wanted to play Diablo II, but with new content and better graphics. The very same day, Blizzard announced Diablo III.\r\n*Saurfang had a pet dog who ran away one day. The dog now resides in the Upper Blackrock Spire.\r\n*The dark portal was really closed because the Alliance was afraid of Saurfang.\r\n*It was actually Saurfang's pure awesomeness that corrupted the orcs, not the Burning Legion.\r\n*High Overlord Saurfang is really the person who gets First Posts, but due to a glitch a random name appears.\r\n*The Infinite Dragonflight is the result of Saurfang chewing up a Nether Dragon.\r\n*Frostmourne was a normal sword... that is, until Saurfang found it. \r\n*[[Highlord Kruul]] was removed from the game after Saurfang used [[Spell Reflection]] when Kruul tried using Kazzak's Assault and killed every NPC in Kalimdor.\r\n*High Overlord Saurfang once drank gasoline and pissed on a rock, thus giving birth to [[Supremus]].\r\n*Saurfang farted over a candle, thus [[Ragnaros]] was born.\r\n*The Light no longer answered the prayers of [[Nobundo]] because Saurfang decided religion is a load of crap.\r\n*In his youth, Saurfang stepped on an ant. From this moment of contact with his awesomeness, the [[Silithid]] were born.\r\n*The destruction of Archimonde and Nordrassil at the Battle of Mount Hyjal was the result of Saurfang blowing his nose. The Wisps were his boogers.\r\n*Deciding he needed a way to terrorize the Alliance without leaving Orgrimmar, Saurfang took 2 boar pelts, sewed them together, vomited into them and left the resulting mess in Elwynn Forest. 2 days later, the mess came alive, becoming the creature we now know as [[Hogger]].\r\n*The reason [[Naxxramas]] is really getting moved has nothing to do with lore or the [[Wrath of the Lich King]] expansion. Blizzard just got tired of Saurfang's Tuesday morning solo jaunts through it, then selling all the loot, thereby crushing every server's economy.\r\n*Once, Saurfang sneezed. It's result can be seen at the center of a map of Azeroth.\r\n*Saurfang and Foror once got into an eye poking fight. There is an item called [[Foror's Eyepatch]]. Go figure.\r\n*The Sword of a Thousand Truths is actually Saurfang's toothpick.\r\n*At the end of the Third War,at the top of Mount Hyjal, Saurfang had to fart. The resulting blast destroyed Archimonde and everything in a 10 mile radius around the World Tree.\r\n*[[Scholomance]] is where Saurfang went to Nursery.\r\n*High Overlord Saurfang created Un'Goro crater by crapping in a ditch.\r\n*Saurfang is Azeroth's one true god. The Earth Mother exists because Saurfang doesn't want a bunch of cattle praying to him.\r\n*The crystal from which the [[Ashbringer]] was forged is neither a piece of a Naaru, nor an [[Ata'mal crystal]], but a piece of Saurfang's snot that was left behind as he cleaved through the battlefields.\r\n*The Sunwell's corruption is the result of Saurfang using it as a toilet.\r\n*The progression percent on Isle of Quel'danas is not how close they are to capturing something, it's how much more they have to convince Saurfang until he allows more NPCs onto Azeroth.\r\n*Saurfang cleaved in Argus and it cut all Apples in Azeroth and Outland in half.\r\n*Blizzard is debating to remove the warrior talent Improved Cleave because Alliance raids complained it was OP. Wonder why.\r\n*The Dead Scar was created when Saurfang accidentally dropped his axe on the floor on the Sunwell Isle. He did it again in Orgrimmar, and it cleaved the canyon to Razor Hill.\r\n*Everyone knows that all the lore about the Sundering and the Well of Eternity was just a myth. The big swirly thing in the middle of the map screen was actually caused by Saurfang sitting down. That is the reason why he has to stand up all the time. That is also the reason why us humans invented the word \"continents\".\r\n*When Saurfang came into existence, all the big shots of WoW decided to migrate, and various landmasses and dimensions decided to break off. That's the reason why we have so many realms. But what happened to the original realm? Blizzard just decided not to put it up for us people to select, feeling that the mortality rate would shoot through the roof, and all the Spirit Healers would retire.\r\n*Once upon a time, Saurfang farted. Gnomeregan remains irradiated.\r\n*High Overlord Saurfang once said \"It wasn't me! It was the one-armed troll!\" — Zul'jin's arm remains severed. \r\n*High Overlord Saurfang once had a massive thirst. Afraid to put the blame on Saurfang, the Cenarion Expedition insisted that the Naga were responsible for draining the [[Dead Mire]] of its water.\r\n*There is no Cow Level. Or at least not since Saurfang was there. His awesomeness destroyed it to the point where everyone who knew of its existence was made to think it didn't exist.\r\n*Dwarves are really gnomes trained by Saurfang.\r\n*William Shatner joined the horde because he's too afraid of Saurfang to join the Alliance.\r\n*It was in fact Saurfang, not Mr. T, who created the Mohawk class.\r\n*Sargeras wasn't actually corrupted. Saurfang forced him to create the Burning Legion so he had something to kill.\r\n*Saurfang urinated in the water of Wailing Caverns and it became corrupted because the water couldn't contain that much awesomeness.\r\n*[[Kwee Q. Peddlefeet]] won't go away because Saurfang wants him to stay and annoy the crap out of everyone.\r\n*People are AFK in battlegrounds because they are scared that High Overlord Saurfang may be in the battle.\r\n*Saurfang the Younger is not really Saurfang's child. He is actually Saurfang himself, who Saurfang kidnapped as a newborn using the Caverns of Time. This has been done by Saurfang for thousands of years to grant him everlasting life. The Bronze Dragonflight still have no idea how taking his newborn self to the future does not damage his existence.\r\n*The last time Saurfang performed a cannonball, Un'Goro Crater was created.\r\n*Dalaran moved to Northrend because of High Overlord Saurfang.\r\n*The Dark Portal was known as the Sunshine Portal until Saurfang walked through it.\r\n*Saurfang was actually the Titan's chosen guardian of Azeroth; Saurfang's refusal's created the Dragon Aspects. \r\n*The Great Sundering was caused when Saurfang farted in the Caverns of Time...\r\n*Once, Saurfang took a walk from Duskwood to the Swamps of Sorrows. This is why there is no sign of life in Deadwind Pass.\r\n*Barrens Giraffes were created when Saurfang uppercut a Zhevra.\r\n*The [[Corrupted Ashbringer]] was actually forged by High Warlord Saurfang from a ballpoint pen, two chunks of granite, three copper bars, continuous spitting, and a half mug of Chen Stormstout's beer.\r\n*Raids are not epic encounters against the various supernatural denizens of Azeroth. They are actually garage sales for items Saurfang does not desire anymore.\r\n*High Overlord Saurfang secretly contrived the invasion of the Burning Legion to challenge his strength.\r\n*Area-effect target caps were implemented after Saurfang used Cleave on Stormwind and it shattered Draenor.\r\n*High Overlord Saurfang was once dared by Thrall to punch a wall in Orgrimmar. The impact created Ragefire Chasm. \r\n*High Overlord Saurfang demands 6 hours of silence for meditation every week. The result of this is Tuesday morning downtime. \r\n*Once, when High Overlord Saurfang was one-manning Ironforge, he needed more adds for a proper [[whirlwind]]. So he charged Stormwind, straight through the mountain. This created the tunnel later utilized by the gnomes when they built the Deeprun Tram.\r\n*The Horde lost the Second War because High Overlord Saurfang simply got bored.\r\n*High Overlord Saurfang used to be able to be mind controlled by Alliance players. Blizzard later changed this because Saurfang killed half of the Blizzard crew and said that he only obeyed himself.\r\n*The Light that paladins and priest pray to is actually a by product of High Overlord Saurfang's rage. The Naaru are just trinkets that High Overlord Saurfang has no use for.\r\n*Outland still exists because it's afraid to be on the same world with High Overlord Saurfang.\r\n*When Azeroth was created by Titans the order came from Saurfang.\r\n*[[Deathwing]] is Saurfang's epic mount.",},
			["Savagekin"] = { content = "The most primal of [[druid]]s, '''savagekin''' bear an ancient but obscure legacy. Whereas some druids seek to command nature or bond with it, the savagekin surrenders himself to the natural world, abandoning much of his humanity to live with the beasts. Those who adopt this role may find they pay a steep price for power.\r\nSavagekin are druids who spend most of their time in animal form. They travel in packs with their fellow beasts. As animals they gain strength and finesse, but come close to becoming irreversibly feral. Savagekin constantly battle the inner beasts that threaten to consume them, clinging to their last vestiges of sentience.\r\n[[Half-elves]], who straddle the world between [[human]] and [[elf]], and [[night elves]] are the most common savagekin, though hermitic humans who wish to be closer to the animal world occasionally adopt this class. Most people think of savagekin only as \"druids who've gone feral.\" Savagekin hate species that practice cruelty toward animals (particularly [[ogre]]s, though some [[human]]s and [[orc]]s qualify), and usually adventure solely to hunt them down and kill them.\r\nThe savagekin may remain in animal form indefinitely. In addition, returning to her natural (humanoid) form is difficult; savagekin enjoy their wild shapes and prefer remaining in animal form. The savagekin may speak with animals at will, while in wild shape. while in animal form, the savagekin may fly into a rage. A savagekin can invoke the power of tooth and claw. When in animal form, the savagekin’s natural weapons sharpen and her hide toughens. the savagekin can draw upon the feral forces of nature to increase her physical abilities. The savagekin may adopt the shape of her animal companion, if she has one. The savagekin may use wild shape to assume the shape of any animal with which she is familiar.\r\n==Famous/Named==\r\n*[[Aliastra]]",},
			["Savage Coast"] = { content = "The '''Savage Coast''' is a coastline on the northern part of Stranglethorn Vale. It takes up the shore from the Westfall border, all the way down to the shore east of The Vile Reef, to the Grom'Gol Base Camp. Many [[crocolisk]]s and even some [[basilisk]]s inhabit the shore. Several [[troll]] settlements are along this area.",},
			["Savage Frond"] = { content = "'''Savage Frond''' are the leaves of [[treant]]s and [[Bloodpetal]]s throughout [[Azeroth]].\r\n==Source==\r\nSavage Frond drops off treants in [[Maraudon]], [[Felwood]], [[Feralas]] and [[Dire Maul]] and Bloodpetals in [[Un'Goro Crater]].\r\nThe drop rate was recently reduced in Dire Maul East, and no longer drops from the non elite packs of lashers.\r\n==As a quest objective==\r\n*Savage Flora ''Turn in 30 fronds to [[Rayne]] at [[Light's Hope Chapel]] for 1 [[Insignia of the Crusade]] or [[Insignia of the Dawn]]''\r\n**Savage Fronds ''Repeatable version of the quest Savage Flora''",},
			["Savage Fury"] = { content = "''Don't make the kitty angry... you wouldn't like it when its angry.''\r\n'''{{PAGENAME}}''' is a 2 rank [[Feral Combat]] talent requiring level 30 and 20 points in Feral Combat talents.\r\n==Notes==\r\nLevel 70 druids seldom use Rake or Claw; most damage comes from Rip and Shred. Only the buff to Mangle (Cat) is useful in endgame raiding.\r\n==Known bugs==\r\n...\r\n==Past changes==\r\n...\r\n",},
			["Savage Guard"] = { content = "'''Savage Guard''' is attached to head and leg armor to enchant the item with [[Resistance|nature resistance]].\r\n==Source==\r\nSavage Guard is a quest reward from the quest [[Quest:The Savage Guard|The Savage Guard]] which starts with [[Zanza the Restless]] in [[Zul'Gurub]] in [[Stranglethorn Vale]]. To complete the quest, you must turn ONE of the following items to Zanza the Restless:\r\n* Arcanum of Focus\r\n* Arcanum of Protection\r\n* Arcanum of Rapidity\r\nYou must also be honored with the [[Zandalar Tribe]].\r\n==Notes==\r\n*Zanza the Restless is located at the top of a small temple beyond [[High Priest Venoxis]]' room and to the left of the pathway leading to [[Bloodlord Mandokir]] and [[High Priestess Mar'li]].\r\n*To obtain an Arcanum of Focus, turn a [[Libram of Focus]], a [[Pristine Black Diamond]], 4 [[Large Brilliant Shard]]s, and 2 [[Skin of Shadow|Skins of Shadow]] to [[Lorekeeper Lydros]] in the library of [[Dire Maul]].\r\n*To obtain an Arcanum of Protection, turn a [[Libram of Protection]], a Pristine Black Diamond, 2 Large Brilliant Shards, and a [[Frayed Abomination Stitching]] to Lorekeeper Lydros.\r\n*To obtain an Arcanum of Rapidity, turn a [[Libram of Rapidity]], a Pristine Black Diamond, 2 Large Brilliant Shards, and 2 [[Blood of Heroes]] to Lorekeeper Lydros.\r\n*To be able to turn in the items for an arcanum, the quest Elven Legends ([[Quest:Elven Legends (Alliance)|Alliance version]] / [[Quest:Elven Legends (Horde)|Horde version]]) must be completed first.\r\n*Cannot be attached to another player's armor through the trade window.",},
			["Savage Hills"] = { content = "The '''Savage Hills''' are located in [[Stranglethorn Vale]]. It is here that Journeyman [[Aron Kodosbreath]] traveled to for an expedition.\r\nThey are said to be at least \"four days' travel east of [[Booty Bay]]\".",},
			["Savage Strikes"] = { content = "'''Savage Strikes''' ia a Tier 1 Talent in the Hunters' Survival tree.\r\n==Functionality==\r\nIncreases the critical strike chance of [[Raptor Strike]] and [[Mongoose Bite]] by 10% per rank.",},
			["Saving Sharpbeak"] = { content = "This is the final quest in a chain involving saving the [[gryphon]] [[Sharpbeak]].\r\n==Objectives==\r\nFight to the top of Jintha'Alor, kill Vile Priestess Hexx for the key to Sharpbeak's cage, and save Sharpbeak.\r\n* Open [[Sharpbeak's Cage]]\r\n==Details==\r\nTo complete this quest you must fight to the top of [[Jintha'Alor]] and kill [[Vile Priestess Hexx]]. She will drop [[Hexx's Key]] which allows you to open [[Sharpbeak|Sharpbeak's]] cage. The cage is not in the cave behind [[Vile Priestess Hexx]], it is through the north exit of the pit and is guarded by two mobs.\r\nIt is noteworthy to mention that a lot of mob clearing on the way up [[Jintha'Alor]] can be skipped by using a [[mount]] to run to the top.\r\n==Description==\r\nWe must save Sharpbeak!\r\nFight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!\r\n==Progress==\r\nSave Sharpbeak!\r\n==Completetion==\r\nSwiftwind and Keenclaw returned with their child moments ago, and are fussing over him like new parents. Seeing them together again is enough to give even this old dwarf mist in the eyes...\r\nWe cannot repay you enough for what you have done, <name>. The gryphons of Aerie peak, and their riders, will sing your name for a long, long time.\r\n==Rewards==\r\nYou will also receive: 2 gold 25 silver \r\n==Gains==\r\n*7350 [[XP]]",},
			["Saving the Best for Last"] = { content = "Both the [[Alliance]] and the [[Horde]] have a quest named '''Saving the Best for Last'''.\r\n*For information on the Alliance quest, go to [[Quest:Saving the Best for Last (Alliance)]].\r\n*For information on the Horde quest, go to [[Quest:Saving the Best for Last (Horde)]].",},
			["Saving Yenniku"] = { content = "In '''Saving Yenniku''', you must use the Soul Gem to capture [[Yenniku]]'s soul and return it to his people. This is the final quest in a long chain, all available in [[Grom'gol Base Camp|Grom'gol]], the first being Hunt for Yenniku which can be obtained from [[Nimboya]] at the north exit to the camp.\r\n==Objectives==\r\nBring the Filled Soul Gem to [[Nimboya]] at the [[Grom'gol Base Camp]].\r\nYou will need:\r\n* Filled Soul Gem\r\n==Details==\r\nTake the Soul Gem you get when you accept the quest and head to the [[Ruins of Aboraz]]. [[Yenniku]] is in the south-western corner of the ruins, almost completely alone. Simply use the Soul Gem while targeting him (you don't have to weaken him first or anything), and he will become friendly. Right click him to capture his soul in the gem and create the Filled Soul Gem.\r\n[[Yenniku]]'s coordinates are 38,58. \r\n==Description==\r\nI have reshaped the Mind's Eye into a Soul Gem. Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul.\r\nThen, bring the gem to Nimboya.\r\nYenniku dwells with Zanzil the Outcast, at the Ruins of Aboraz, along the Crystal Shore on the distant Cape of Stranglethorn.\r\n==Reward==\r\nYou will be rewarded with the following:\r\n* 500-5050 XP\r\n* [[Darkspear Trolls]] +350 rep\r\nIn addition, you will be allowed to chose one of the following:\r\n==Progress==\r\n<name>. Kin'weelay told me you set out to capture Yenniku.\r\nIs it true? Do you have him?\r\n==Completion==\r\nYou've done it! You freed Yenniku from the will of Zanzil, and completed the mission I had thought was so desperate.\r\nOur tribe will remember your name in songs, <name>, and we will etch your tale in stone so that it will live forever.",},
			["Savory Deviate Delight"] = { content = "''Eat me!!!''\r\n'''Savory Deviate Delight''' is [[cooking|cooked]] using Deviate Fish, which can be fished from various ponds in the [[Barrens]]. The components are:\r\n* 1 Deviate Fish\r\n* 1 Mild Spices\r\n* [[Cooking Fire]]\r\nRecipe: Savory Deviate Delight drops from the various mobs in [[The Barrens]].\r\n==Notes==\r\nEating a Savory Deviate Delight randomly has one of these two effects:\r\n* '''Flip Out''' - a [[buff]] that changes the character model into a ninja for 60 minutes. The ninja is a human dressed entirely in black with a black bandana across its face. (This transformation looks very similar to a human dressed in the Defias Leather armor set, with a black bandana rather than a red bandana)\r\n* '''Yaaarrrr''' - this buff transforms the character into a human pirate for 60 minutes.\r\nIn earlier patches, Savory Deviate Delight also bestowed a number of other possible effects, including \"fake death,\" a short-term Fear effect, and a rapid-cast buff. Some players misused the Savory Deviate Delight's Fear-like effect to glitch their way past closed gates such as those in [[Blackwing Lair]]. Blizzard removed all effects other than the Pirate/Ninja transformations in [[Patch 1.7]].\r\n[[Druid]]s and [[Shaman]]s lose the effect when they change [[Druid Forms|forms]]. As of Patch 2.3 a Priests [[Shadowform]] no longer removes the effect.\r\nFor non-humans, certain emotes change while '''Flip Out''' or '''Yaaarrrr''' are in effect. These include /cry, /laugh, /cheer, /chicken, /yawn, /train, /silly and /sigh which are all replaced by the human versions.",},
			["Sawbones Shirt"] = { content = "==Notes==\r\n*This shirt is one of only three [[Bind on Pickup]] (BOP) shirts that currently are available to both factions.\r\n*This is a rare drop from [[Doctor Theolen Krastinov]] in [[Scholomance]]. Drop rate approx 0.1-1%",},
			["Sayaad"] = { content = "The '''sayaad''' (pronounced say-ahd) (adjective form '''sayaadi''') are a species of seductive and sadistic [[demon]]s who look similar to the [[nathrezim]]. Many serve the [[Burning Legion]], but others serve only themselves or can be impressed by a [[warlock]] master. Only female sayaad are commonly seen, and are known as '''succubi''' (singular '''succubus'''). The males are named '''incubi''' (singular '''incubus'''). Sayaad can change their appearance between succubus and incubus form to match their master's preferences.\r\n==Succubus==\r\n'''Succubi''' serve as intelligence agents and torturers for the [[Burning Legion]]. Exemplifying the subtler side of the [[Burning Crusade]], the cruel sayaadi temptresses revel in causing anguish and pain, and their murderous interrogations are the stuff of nightmares. Creatures of incredible mental powers, they can lull those of weak minds into their servitude. Succubi know much about love and slake their lust with coupling. They are described as devourers of souls, destroyers of hearts, dominators of minds, and tempters of men. Succubi have a tendency to keep detailed logs of their day-to-day activities. Their accounts are often lurid, almost always grotesque, and are typically written onto \"paper\" made from the skin of an enemy or a captive.\r\n'''Fel succubi''' are a more powerful variant, with red skin, more elaborate, spiked armor, and wings and whips that drip with fel energy.\r\n==Incubus==\r\n'''Incubi''' are much more rarely seen than succubi, but can be summoned by [[warlock]] [[adventurer]]s. There are several different rumors concerning incubi, all of which are perpetrated by the succubi themselves. A few of the most common rumors are:\r\n*The spell to summon them has been conveniently forgotten by mortal practitioners and Burning Legion agents.\r\n*Incubi are kept as slaves on their home planet, having been rendered incapable of escape or independent movement.\r\n*The succubi consumed the males of their race when they were brought into the Burning Legion. Alternatively, the act of devouring the males is what caught the attention of the Burning Legion.\r\nDuring her battle against demons in the [[Dragonblight]], [[Aegwynn]] encountered a demon who mentioned incubi as part of the Legion's forces. \r\n==As a warlock minion==\r\nThe sayaad is the third [[warlock minion|demon minion]] available to [[warlock]]s, summoned by the [[Summon Sayaad]] spell. The spell randomly summons either an incubus or succubus, but warlocks can speak to certain warlock trainers to change the spell into [[Summon Incubus]] or [[Summon Succubus]], ensuring that only that gender is summoned.\r\n==As a companion pet==\r\n[[Sultry Grimoire]] drops from [[Mother Shahraz]] in [[Black Temple]].\r\n===Languages===\r\nAs members of the Burning Legion, succubi speak [[Eredun]], and most also speak Common. Common is a language known by most races who would summon these beings, those who summon them likely know Eredun as well.\r\n==Notes and trivia==\r\n*In the ''[[Ultimate Visual Guide]]'', the sayaad entry is written as \"sayaad (succubus)\", paring the two names like nathrezim (dreadlord) and shivarra (shivan). This could imply that the sayaad is the demon term, while the succubus is the [[Common (language)|Common]] language term.\r\n*In all of the [[Kirin Tor]]'s research into succubi and other sayaad, they have come to one conclusion - they are not to be trusted.\r\n*Succubi outfits are actually designed for the temperatures of inferno worlds mostly on fire. Being on a world like [[Azeroth]] in such clothes leaves them feeling cold.\r\n*One succubus whip was formed of the plaited flesh of several different creatures, some of them likely [[humanoid]].\r\n*Apparently, even some [[nathrezim]] find sayaad attractive: [[Gorgannon]] accused his fellow dreadlord [[Diathorus the Seeker|Diathorus]] of using all of their blood ink to write love letters to the [[Mannoroc Lasher]]s.\r\n*Without being born of the sayaadi species, some people were known to have been transformed into succubi, like [[Sensiria]].\r\n*''Ṣayyād'' (صياد) means \"hunter\" or \"trapper\" in Arabic.\r\n*For most of ''Warcraft''<nowiki/>'s history, only succubi were seen in-game. When incubi were requested as a [[warlock]] pet in April 2011, Community Manager [[Zarhym]] responded that Blizzard had plans for offering players a choice between male and female versions of all warlock demons, but that they didn't have a time frame for when it might be implemented. 10 years later, in September 2021, Blizzard announced that incubi would be added to the game following [[patch 9.1.5]]—both as a [[glyph]] option for warlocks and as an addition to places where succubus models appear—as part of ongoing efforts to make the game world feel more inclusive and to offer more ways for players to express themselves. Incubi were added in [[patch 9.2.0]], though not as a glyph; instead, the old [[Summon Succubus]] spell was replaced by [[Summon Sayaad]] as the default, with the preference of summoning exclusively an Incubus or Succubus being added as a cosmetic option.",},
			["Sayge's Fortunes"] = { content = "Main Article: [[Darkmoon Faire]]\r\nAfter [[Sayge]] tells your fortune, you will receive a [[buff]] depending on the answers you gave.\r\n==Guide to Answering Sayge==\r\nHere is a chart of the buffs with answers you need to give to get them.\r\nNOTE: Upon entering TK raid instance this buff disappeared for me and some others. Be warned it may do it for others, but more testing is needed. Tested in SSC - Buff vanishes non entry. Seems like a non-raid buff. Probably works for PVP though (imbalance in WOW?!?)\r\nHere are the results based on the following answers:\r\n# \"Slay the Man\" (+Damage, +Magic Resist, or +Armor)\r\n## +1 to 10% Damage - Sayge's Dark Fortune of Damage\r\n##:1st: Slay the Man\r\n##:2nd: Execute your friend painfully\r\n## +25 All Resistances - Sayge's Dark Fortune of Resistance\r\n##:1st: Slay the Man\r\n##:2nd: Execute your friend painlessly\r\n## +10% Armor - Sayge's Dark Fortune of Armor\r\n##:1st: Slay the Man\r\n##:2nd: Let your friend go\r\n# \"Turn him over to liege\" (+Spirit, +Intellect, or +Magic Resist)\r\n## +10% Spirit - Sayge's Dark Fortune of Spirit\r\n##:1st: Turn him over to liege\r\n##:2nd: Confront the diplomat\r\n## +10% Intellect - Sayge's Dark Fortune of Intelligence\r\n##:1st: Turn him over to liege\r\n##:2nd: Show not so quiet defiance\r\n## +25 All Resistances - Sayge's Dark Fortune of Resistance\r\n##:1st: Turn him over to liege\r\n##:2nd: Remain quiet\r\n# \"Confiscate the corn\" (+Stamina, +Strength, or +Agility)\r\n## +10% Stamina - Sayge's Dark Fortune of Stamina\r\n##:1st: Confiscate the corn\r\n##:2nd: Speak against your brother openly\r\n## +10% Strength - Sayge's Dark Fortune of Strength\r\n##:1st: Confiscate the corn\r\n##:2nd: Help your brother in\r\n## +10% Agility - Sayge's Dark Fortune of Agility\r\n##:1st: Confiscate the Corn\r\n##:2nd: Keep your brother out without letting him know\r\n# \"Let him go and have the corn\" (+Intellect, +Spirit, or +Armor)\r\n## +10% Intellect - Sayge's Dark Fortune of Intelligence\r\n##:1st: Let him go and have the corn\r\n##:2nd: Take credit, keep gold\r\n## +10% Spirit - Sayge's Dark Fortune of Spirit\r\n##:1st: Let him go and have the corn\r\n##:2nd: Take credit, share the gold\r\n## +10% Armor - Sayge's Dark Fortune of Armor\r\n##:1st: Let him go and have the corn\r\n##:2nd: Let the knight take credit\r\n==Text of the Fortunes==\r\nWhen you answer Sayge's questions and receive the buff, you will receive a fortune item in your inventory with a random saying upon it. Most of these items are for flavor and humor only and can be safely discarded. A few of the items will start a quest if you right click on them.\r\nBelow is a list of the sayings found on each fortune. If the given item starts a quest, it is noted here as well.\r\n* Sayge's Fortune #1: \"Never eat beef with a tauren.\"\r\n* Sayge's Fortune #2: \"You will find something wonderful tomorrow.\"\r\n* Sayge's Fortune #3: \"An enemy from your past will soon become an ally.\"\r\n* Sayge's Fortune #4: \"You will be fortunate in everything you put your hands to.\"\r\n* Sayge's Fortune #5: \"Someone is speaking well of you.\"\r\n* Sayge's Fortune #6: \"Be cautious when landing in unfamiliar territory.\"\r\n* Sayge's Fortune #7: \"Avoid taking unnecessary gambles.\"\r\n* Sayge's Fortune #8: \"You will receive a fortune.\"\r\n* Sayge's Fortune #9: \"Your first love and last love is self-love.\"\r\n* Sayge's Fortune #10: \"Rest is a good thing, but boredom is its brother.\"\r\n* Sayge's Fortune #11: \"Those with simple tastes are always satisfied with the best.\"\r\n* Sayge's Fortune #12: \"Let not the tides of war wash you away.\"\r\n* Sayge's Fortune #13: \"You leave your adversaries speechless.\"\r\n* Sayge's Fortune #14: \"You have a good eye for spotting hypocrisy.\"\r\n* Sayge's Fortune #15: \"One learns most when teaching others.\"\r\n* Sayge's Fortune #16: \"The time will soon come for you to make a choice in a pressing matter.\"\r\n* Sayge's Fortune #17: \"Never punt a gnome without due cause.\"\r\n* Sayge's Fortune #18: \"Accept the next proposition you hear.\"\r\n* Sayge's Fortune #19: \"The Forsaken are up to something.\"\r\n* Sayge's Fortune #20: \"Many a false step is made by standing still.\"\r\n* Sayge's Fortune #21: \"Divine Shields and Hearthstones do not make a hero heroic.\"\r\n* Sayge's Fortune #22: \"An answer in blue is always true.\"\r\n* Sayge's Fortune #23: \"Your fortune awaits you in Eastvale.\"\r\n** ''(This item begins a quest.)'' Your_Fortune_Awaits_You..._(1), requires level 10\r\n* Sayge's Fortune #24: \"Your fortune awaits you inside the Deadmines.\"\r\n** ''(This item begins a quest.)'' Your_Fortune_Awaits_You..._(2), requires level 10\r\n* Sayge's Fortune #25: \"Your fortune awaits you inside the Wailing Caverns.\"\r\n** ''(This item begins a quest.)'' Your_Fortune_Awaits_You..._(3), requires level 10\r\n* Sayge's Fortune #26: \"Time is nothing; timing is everything.\"\r\n* Sayge's Fortune #27: \"Your fortune awaits you outside Palemane Rock.\"\r\n** ''(This item begins a quest.)'' Your_Fortune_Awaits_You..._(4), requires level 10\r\n* Sayge's Fortune #28: \"Hunters who specialize in survival are not guaranteed to survive.\"\r\n* Sayge's Fortune #29: \"Look out!\"",},
			["Sayge"] = { content = "'''Sayge''' is a level 55 buff vendor (free) and [[quest giver]] associated with the [[Darkmoon Faire]].\r\n==Description==\r\nSayge is a [[gnoll]] and is one of the few gnolls that are not hostile. He is either from the [[Shadowhide]], [[Palemane]], or [[Mudsnout]] clans of Gnoll, based on his coloration. Asides from being neutral he has also been able to learn to speak full [[Common]]. Most gnolls can only speak [[Low Common]].\r\n==Services==\r\nSayge will buff you and tell you your fortune for free, all you have to do is answer his questions. He asks two questions with multiple answers, after which he buffs you. The buffs are linked to which answers you choose; so if you desire, you can specify the buff reliably, see [[Sayge's Fortunes]]. The buffs last for 2 hours, and the cooldown between receiving buffs is even longer.\r\nAfter you answer you answer Sayge's questions and he has just buffed you, he asks you if you want a written fortune. You can turn Sayge down, but assuming you accept, you get a soulbound fortune cookie-like fortune item in your inventory (must have a free slot). (See [[Sayge's Fortunes]]) Right click to open it (the result is an opened soulbound fortune item), then mouse over it to read it. Most of these can be discarded, but four of his fortunes are quest items which start the following quests:\r\n* Your Fortune Awaits You... (1)\r\n* Your Fortune Awaits You... (2)\r\n* Your Fortune Awaits You... (3)\r\n* Your Fortune Awaits You... (4)\r\n==Location==\r\nSayge is a member of the [[Darkmoon Faire]], so is located in in the Darkmoon Faire camp, which is only available during the monthly Darkmoon Faire event. The Darkmoon Faire rotates each month to a different location. One month it will be south of [[Goldshire]] in the [[human]] starting zone of [[Elwynn Forest]]. Then, it is off to [[Kalimdor]] where it is southwest of [[Thunder Bluff]] in the [[tauren]] starting zone of [[Mulgore]]. Then it travels to [[Outland]] near [[Shattrath City]].\r\n==Quote==\r\n\"Come speak with me, and what once was cloudy shall become crystal clear.\"\r\n''\"Choices''\r\n''I have long known you'd seek me out, adventurer.''\r\n''Every sapient being in this world is driven by the choices they make. Choices begat further choices, and these in turn make someone who they are. This is where your fortune is drawn from - who you are, and the choices you make.''\r\n''Are you ready to discover where your fortune lies, adventurer?\"''\r\n==See also==\r\n* [[Sayge's Fortunes]]\r\n* [[Darkmoon Faire|Darkmoon Buffs]]",},
			["Sayoc"] = { content = "'''Sayoc''' is a level 50 [[weapon master]] located in the [[Valley of Honor]] in the [[orcish]] city of [[Orgrimmar]].\r\nTeaches the skill to wield the following:\r\n*[[Bow]]s\r\n*[[Thrown Weapon]]s\r\n*[[Dagger]]s\r\n*[[Fist Weapon]]s\r\n*[[One-handed]] [[axe]]s\r\n*[[Two-handed]] [[axe]]s\r\nSee [[List of Orgrimmar NPCs]].",},
			["Scalawag Point"] = { content = "Located on the south end of the island south of the [[Isle of Spears]] at 35.5, 81.5 in the [[Howling Fjord]].",},
			["Scale"] = { content = "A '''scale''' is a type of [[item]] usually [[gather]]ed with the [[Skinning]] [[profession]] from a [[skinnable]] scaled corpse [[resource]]. These items can usually be used directly by the [[Leatherworking]] profession without prior processing or treatment, but usually only with [[recipe]]s acquired from non-[[Trainer]] [[NPC]]s or as [[drop]]s.\r\n==Scales==\r\n* [[Deviate Scale]]\r\n* [[Perfect Deviate Scale]]\r\n* [[Slimy Murloc Scale]]\r\n* [[Thick Murloc Scale]]\r\n* [[Turtle Scale]]\r\n* [[Scorpid Scale]]\r\n* [[Heavy Scorpid Scale]]\r\n* [[Silithid Chitin]]\r\n* [[Fel Scales]]\r\n* [[Cobra Scales]]\r\n* [[Wind Scales]]\r\n* [[Naga Scale]]\r\n* [[Incendosaur Scale]]\r\n===Whelp Scales===\r\n* [[Black Whelp Scale]]\r\n* [[Red Whelp Scale]]\r\n* [[Green Whelp Scale]]\r\n===Dragon Scales===\r\n* \r\n* \r\n* \r\n* \r\n* [[Nether Dragonscales]]",},
			["Scalebane"] = { content = "'''Scalebanes''' are the most elite and powerful of the [[dragonspawn]], and they represent a small fraction of dragonspawn society. These are the leaders, the most powerful spellcasters, and the elders of the dragonspawn race. While scalebanes were wyrmkin earlier in life, scalebanes are technically a different species, having been transformed by a complicated ritual similar to those undergone by dragons as they mature. Scalebanes are chosen from the best of the lesser ranks, those who demonstrate exceptional leadership as well as combat or magical abilities. While most scalebanes are intellectual, they still have large builds, powerfully built for combat, standing seven feet tall or just little under on average, and wear elaborate armor with dragon-crested helms that stand out from the rest their unit. Many scalebanes may also carry banners or other markings delineating their command. These banners represent their draconic patron or matron, such as [[Azuregos]] the [[Blue dragonflight|blue]] or [[Vaelastrasz]] the [[Red dragonflight|red]]. \r\nScalebanes spend most of their time in combat commanding their units, but those with spellcaster abilities pepper their enemies with spells from a distance. If pressed, they fight fearlessly, but avoid melee combat because they know they are most effective in command positions. Scalebanes are clearly in control of a unit's movements and strategies. Scalebanes carry swords and shields, two-handed swords, or other impressive weapons, usually a greatsword. These weapons are always magical, retaining an enhancement and possibly an additional magical feature. A scalebane always has a secondary magic item: shield, armor, rod, wand, or another item used for the benefit of the entire squadron. They are considered the most adept followers of their dragon mentor and are looked on by other dragonspawn as acolytes of the dragon's wisdom and prophets of the dragon's will. They are [[fighter]]s or [[sorcerer]]s, and sometimes [[rogue]]s and [[paladin]]s. Scalebanes are trained in the use of all martial weapons and all types of armor and shields. \r\nThey speak Common and Draconic.",},
			["Scalebeard's Cave"] = { content = "'''Scalebeard's Cave''' is located on a tiny island in the western part of the [[Bay of Storms]]. It is the home of the [[turtle]] [[Scalebeard]], but he tends to not be present, usually preferring to spend his time hunting in [[the Great Sea]].",},
			["Scalebeard"] = { content = "'''Scalebeard''' is a level 52 neutral [[elite]] [[rare mob]] [[turtle]] in [[Azshara]], found at Scalebeard's Cave. He is not tamable as a hunter pet.\r\nStats (according to Beast Lore):\r\nDamage: 110-147\r\nArmour: 4647\r\nHealth: 8298",},
			["Scalewing Shelf"] = { content = "'''Scalewing Shelf''' is an area of southeastern [[Blade's Edge Mountains]] that is home to many [[wind serpent]]s and [[raptor]]s.",},
			["Scale Belly"] = { content = "'''Scale Belly''' is a level 45 [[rare mob]] [[basilisk]] found in [[Stranglethorn Vale]].\r\n==Loot==\r\n*Chromatic Sword\r\n*Iridescent Scale Leggings",},
			["Scale of the Sands"] = { content = "'''The Scale of the Sands''' is a secretive subgroup of the [[bronze dragonflight]], led by [[Soridormi]], prime mate of [[Nozdormu]]. [[Arazmodu]] is a member of this faction. Until patch 2.4 a friendly reputation with the faction was required to enter the [[Battle of Mount Hyjal]].\r\n==Reputation==\r\nNote: Mobs will not give rep until first wave has been cleared or if previous boss was cleared within the soft reset time; this was implemented by Blizzard to prevent reputation grinding by small groups.\r\n==Rewards==\r\nYou get each ring as a quest reward from [[Soridormi]]. You get the first from her at friendly after completing [[The Vials of Eternity]], and you turn in your old one for a new one at each reputation level.\r\n==Designs==\r\n[[Indormi]] will also sell [[jewelcrafting]] designs as you advance in Scale of the Sands reputation.\r\nNote that copies of these designs are also offered by [[Shattered Sun Offensive]] vendors. It is easier for individuals and small groups to gain reputation with The Shattered Sun Offensive, but the designs are significantly more costly.",},
			["Scarab (mob)"] = { content = "'''Scarabs''' are level 43-46 [[beetle]]s found in [[Zul'Farrak]].\r\n[[Krazek]] and [[Tran'rek]] want the scarab's hard shells.\r\n==Quests==\r\n*Scarab Shells\r\n==Loot==\r\n*Uncracked Scarab Shell ''(Quest Item)''\r\n==Species==\r\n*Giant Scarab\r\nThese enormous beetles carry foul disease. The trolls of Zul’Farrak consider them sacred. A giant scarab attacks prey mindlessly, releasing a disease cloud as it closes. A giant scarab can release a cloud of diseased air that extends outward from the beetle in a 15-foot-radius spread. Creatures within the cloud are subject to chokemist disease.",},
			["Scarab Dais"] = { content = "'''The Scarab Dais''' is where the [[The Scarab Gong]] is located, just northwest of the [[Scarab Wall]] outside of [[Ahn'Qiraj]].\r\n==NPCs==\r\nJonathan the Revelator\r\n==Quests==\r\n*Bang a Gong!\r\n*Treasure of the Timeless One",},
			["Scarab Lord"] = { content = "The '''Scarab Lord''' [[title]] is a reward for opening [[Ahn'Qiraj]] by completing the quest Bang a Gong!.\r\nWhen the instances [[Ruins of Ahn'Qiraj]] and [[Temple of Ahn'Qiraj]] were added in [[patch 1.9]], the [[Gates of Ahn'Qiraj]] were still closed and both instances could only be made accessible by completing a series of player-driven quests.\r\nIn addition to all players on a realm working towards completing the [[War Effort]], one player had to create the [[Scepter of the Shifting Sands]] - a very difficult task that could only be solved by a server's top guild(s) back when the quest-line was added. After the War Effort was finished and the army of the alliance and the horde arrived in [[Silithus]], the Scepter of the Shifting Sands could be used on the [[Scarab Dais|Scarab Gong]]. Doing so resulted in [[Ahn'Qiraj]] being opened. The first player to bang the Scarab Gong and anyone else who followed within 10 hours, mostly only 1-3 people each server, obtained the Scarab Lord title.\r\nAlthough it is still possible to complete the quest-line for the Scepter of the Shifting Sands even when the gates are already open, doing so at a later time will not reward the quest-solver with the [[Black Qiraji Resonating Crystal]] or the Scarab Lord title.\r\nIn lore, it is likely that [[Shiromar]] is the Scarab Lord rather than a random player.\r\n==See also==\r\n* [[List of scepter holders by server]]",},
			["Scarab Wall"] = { content = "'''The Scarab Wall''' lies at the southern edge of [[Silithus]], marking the boundary between the silithid-controlled desert and the ancient kingdom of [[Ahn'Qiraj]]. It is an impressive structure, including some sort of magical shield that also prevents creatures capable of flight to simply fly over it.\r\nThere is a [[World Event]] to open the [[Gates of Ahn'Qiraj]].\r\nWhile ingame, a player attains the rank of [[Scarab Lord]] when opening the wall, it is known that [[Shiromar]] was the one who rang the gong in lore. This potentially means that she is the Scarab Lord when it comes to the storyline.\r\nSee:\r\n* [[Ahn'Qiraj]] for information on the area and lore\r\n* [[Gates of Ahn'Qiraj]] and [[The Scepter of the Shifting Sands quest chain]] for details on the massive quest to open those gates.",},
			["Scare Beast"] = { content = "==Rank table==\r\n==Tips and tactics==\r\n*This can be used as [[crowd control]] when fighting multiple [[mob]]s and one happens to be a beast.\r\n*This skill works on [[druid]]s when they are in [[Bear form]] or [[Cat form]], and [[shaman]]s in [[Ghost Wolf]] form.\r\n==Notes==\r\n*A scared beast may bring [[add]]s.",},
			["Scargil"] = { content = "'''Scargil''' is a level 30 [[rare mob]] [[murloc]] found on the [[Western Strand]] in [[Hillsbrad Foothills]]. It is on a 5-8 hour respawn timer.",},
			["Scarlet Armband"] = { content = "==Source==\r\nThis item drops from:\r\n* [[Scarlet Initiate]] in [[Tirisfal Glades]]\r\n* [[Meven Korgal]] in [[Tirisfal Glades]]\r\n* [[Scarlet Convert]] in [[Tirisfal Glades]]\r\n==Scarlet Armband as a quest objective==\r\nThis item is an objective of The Scarlet Crusade.",},
			["Scarlet Armies Approach..."] = { content = "==Objectives==\r\nDeliver The Path of Redemption to [[Highlord Darion Mograine]] at [[Acherus: The Ebon Hold]]\r\n*The Path of Redemption (provided)\r\n==Description==\r\nWe must prepare for encroaching armies, <name>. You will take what you have discovered to Highlord Mograine at once! I will open a portal directly to Acherus. Step inside and it will transport you.\r\nGive Highlord Mograine [[High General Abbendis (female)|Abbendis']] journal as well. Perhaps he'll find it useful.\r\n==Rewards==\r\nYou will receive: 2 gold 50 silver , 3 Bonus talents, Blood-soaked Saronite Plated Spaulders\r\n==Progress==\r\nYou did what?\r\n==Completion==\r\nYou have become an instrument of doom, [[death knight]]! We will ravage these approaching armies and raise the dead as our own!\r\n==Notes==\r\nAccepting this quest starts phase 3. More NPCs have moved around.",},
			["Scarlet Ballista"] = { content = "They are involved in the following quest:\r\n*An End To All Things...",},
			["Scarlet Base Camp"] = { content = "The '''Scarlet Base Camp''' is a small barricaded fortification located on the east banks of [[Lake Mereldar]], not far from the religious bastion of [[Tyr's Hand]].",},
			["Scarlet Basilica"] = { content = "'''The Scarlet Basilica''' is a large cathedral located inside [[Tyr's Hand]] in the [[Eastern Plaguelands]]. It is the high seat of religious power for the [[Scarlet Crusade]], and has close ties to the [[Tyr's Hand Abbey]] nearby as well as the [[Scarlet Monastery]] much further west in [[Tirisfal Glades]]. It is the location of [[Crusader Lord Valdelmar]].\r\nThe Scarlet Basilica is built very much like the [[Cathedral of Light]] in the city of [[Stormwind]].\r\nThe [[Crimson Courier]] and her 4 bodyguards will eventually walk into this building if they are not killed. However, they will stop once they reach the altar and disappear, respawning back at the front of [[Stratholme]].",},
			["Scarlet Bastion"] = { content = "'''The Scarlet Bastion''' is a fortified cathedral located in the western districts of the ruined city of [[Stratholme]]. The Scarlet Bastion serves as a small outpost in the undead-infested city of Stratholme. Grand Crusader Dathrohan struggles to hold the [[Scarlet Crusade]] stronghold. He coordinates the fight for control of the ravaged city. It is manned by members of the [[Crimson Legion]], the elite guard of the Crusade. It is the Scarlet Crusade’s holiest site. The Scarlet Bastion is where the Scarlet Crusade first formed, and where the founding members took their oaths.\r\nThe bastion is located in [[Crusaders' Square]], and contains [[the Hall of Lights]], [[the Hoard]], and [[the Crimson Throne]].",},
			["Scarlet battle mage"] = { content = "While most associate the [[Scarlet Crusade]] with the decline of the [[Knights of the Silver Hand]], members of the organization come from many different backgrounds — the Scarlet Crusade includes former members of the [[Kirin Tor]] and other arcane spellcasters. Battle magi are some of the deadliest members of the Scarlet Crusade; their knowledge of arcane magic is tempered with zeal and training in martial arms. In combat, powerful battle magi might charge into a unit of [[Scourge]] creatures and lay it to waste with incendiary magic, and then obliterate any survivors with ordinary or enchanted steel. Battle magi are among the rarest of their order and are highly respected. The overwhelming majority of battle magi are trained in [[Tyr’s Hand]] and the newly founded [[Scarlet Monastery]], and then sent to the locations where they are most needed. While the Scarlet Crusade opposes both the [[Forsaken]] and the Scourge, battle magi are typically assigned to deal with the latter, since the Scourge is considered more dangerous. Since normal spells and swords are typically ineffective against the stronger members of the Scourge, Scarlet battle magi focus their studies on fire magic. While most of their spells are designed to destroy large groups of weak monsters, battle magi also learn to empower their weapons, knowing that situations arise where ranged magic might fail. Overall, Scarlet battle magi are versatile, and that quality makes them feared by their enemies — and the rest of the world.\r\nLike all members of the Scarlet Crusade, Scarlet battle magi are humans. Most began their careers as magi.\r\nAs members of the Scarlet Crusade, and typically among the most zealous members of the organization, battle magi are unpopular among the educated members of the [[Alliance]]. A battle mage who flaunts her title is likely to be considered insane and turned away by any adventuring party; many battle magi know this well enough conceal their identities. Some battle magi despise or disdain the rest of the world and travel only with other members of their organization. When a battle mage participates in an adventuring group, she often takes a leadership or front line role, in spite of the tendency of most spellcasters to do the opposite. Battle magi have a reputation for fearlessly charging into battle — a reputation that is not always remembered in a positive light. Battle magi deal with their targets quickly, using instantaneous spells to eliminate weak opponents immediately. Their spells and reflexes are impressive, which may ensure the battle mage’s stay within an adventuring group, even if she is\r\nnot entirely trusted.\r\n==In WoW==\r\nCrimson Battle Mages can be found in [[Stratholme]].",},
			["Scarlet Beastmaster"] = { content = "'''Scarlet Beastmaster''' can be found in [[Scarlet Monastery]] Library wing.\r\n==Abilities==\r\n*[[Shoot]]\r\n*[[Spell:7896|Exploding Shot]]\r\n==Drops == \r\n \r\n0.03% Chance of a [[rare]] drop.\r\n0.59% Chance of an [[Uncommon]] drop.\r\n0.05% Chance of a [[common]] drop.\r\n0.16% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scarlet Chaplain"] = { content = "'''Scarlet Chaplain''' can be found in [[Scarlet Monastery]].",},
			["Scarlet Cleric"] = { content = "==Notes==\r\n* Heal for about 1500-2000 health.\r\n* Mindblast for around 300-400 damage.",},
			["Scarlet Commander Marjhan"] = { content = "'''Scarlet Commander Marjhan''' <The [[Scarlet Crusade]]> is a level 60 elite female [[human]] at [[Light's Hope Chapel]] in the [[Eastern Plaguelands]].\r\n==Background==\r\nScarlet Commander Marjhan serves as an ambassador of the [[Scarlet Crusade]] at Light's Hope Chapel in the Eastern Plaguelands. Currently, she is engaged in a meeting with the [[Argent Dawn]] and [[Brotherhood of the Light]], deciding how to counter the ever growing threat of the [[Undead]] [[Scourge]]. She seems to despise the [[Horde]] (standard Scarlet Crusader reaction), judging by her calling them \"heathens...the revolting, unkempt Horde filth,\" and believes that finding the Ashbringer is the only hope for victory over the Scourge.\r\n==Quote==\r\n\"The Argent Dawn might be impotent idealists but their delusional leader knows that they are outmatched. I have been sent here as an emissary of the Scarlet Crusade. An ambassador, if you will... It is doubtful that we could even dent the armies of [[Kel'Thuzad]] - united or not - but we might be able to contain them long enough for some sort of miracle to happen.\r\nAs for me? I'll die in battle...\r\n<Marjhan shrugs.>\"",},
			["Scarlet Commander Mograine"] = { content = "'''Scarlet Commander Renault Mograine''' is the commander of the military forces of the [[Scarlet Crusade]] at the [[Scarlet Monastery]]. He is second only to [[High Inquisitor Whitemane]] in rank. He can be found in the Chapel inside the Monastery, and he is a part of a scripted-boss event along with Whitemane. For the commander's dark secret, find [[Highlord Mograine]].\r\nMograine is a level 42 [[elite]] [[paladin]] [[boss]]. He uses [[Hammer of Justice]] (3 sec stun), Crusader Strike (increases holy dmg on target), and [[Divine Shield]] (invulnerable for 10 seconds). He hits hard and can take a lot of pain - but he doesn't heal.\r\nCommander Mograine's father, [[Highlord Mograine]], was known as the [[Highlord Mograine|Ashbringer]] and wielded the [[loot|Legendary|Ashbringer|sword of the same name]]. He was corrupted by the [[Scourge]] and now resides in [[Naxxramas]] as one of [[Kel'Thuzad]]'s death knights.\r\n==Lore Status==\r\n[[Raleigh the Devout]] in the [[Hillsbrad Foothills]] instructs Alliance players to kill Mograine as part of [[Quest:In the Name of the Light|In the Name of the Light]], while [[Varimathras]] in the [[Undercity]] instructs Horde players to kill him to fulfill [[Quest:Into the Scarlet Monastery|Into the Scarlet Monastery]]. Mograine is also slain by his father's spirit as part of the Corrupted Ashbringer questline.\r\n==Quests==\r\n*In the Name of the Light\r\n*Into the Scarlet Monastery\r\n==Quotes==\r\n'''Aggro''' ''Infidels. they must be purified!''\r\n'''Resurrected''' ''At your side, milady.''\r\n'''Killing A Player''' ''Unworthy.''\r\n==Loot==\r\n*Aegis of the Scarlet Commander\r\n*Gauntlets of Divinity\r\n*Mograine's Might\r\n*Scarlet Leggings\r\n==External Links==\r\n*AmpWoW -",},
			["Scarlet Conjuror"] = { content = "'''Scarlet Conjuror''' can be found in [[Scarlet Monastery]].\r\n==Abilities==\r\n \r\n==Drops==\r\n \r\n0.00% Chance of a [[epic]] drop.\r\n0.04% Chance of a [[rare]] drop.\r\n0.84% Chance of an [[Uncommon]] drop.\r\n0.07% Chance of a [[common]] drop.\r\n0.23% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created.",},
			["Scarlet Convert"] = { content = "'''Scarlet Converts''' are the freshly recruited, dagger-wielding fanatics of the [[Scarlet Crusade]]. They have set up a camp southeast of [[Deathknell]] to harass the undead-infested village of [[Deathknell]]. Executor Arren sends new players to battle them and collect their armbands.\r\n==Attacks and abilities==\r\n*'''[[Melee|Basic Melee]]''': 3-4 damage (before subtracting armor)\r\n==Quests==\r\n* The Scarlet Crusade - from [[Executor Arren]] in [[Deathknell]]\r\n:Objective: Collect 12 [[Scarlet Armband]]s from [[Scarlet Convert]]s and [[Scarlet Initiate]]s.",},
			["Scarlet Courier"] = { content = "He is involved in the following quest:\r\n*Ambush At The Overlook\r\n==Quotes==\r\nWhen using the Makeshift Cover:\r\nHrm, what a strange tree. I must investigate.\r\nWhat's this!? This isn't a tree at all! Guards! Guards!",},
			["Scarlet Crusade"] = { content = "The '''Scarlet Crusade''' (also known as the '''Scarlet Brotherhood''' or simply the '''Crusade''') is a fanatical [[Religion|religious]] sect that evolved from the [[Knights of the Silver Hand]], dedicated to the eradication of the [[undead]] from [[Lordaeron]]. A major adversary of the [[Forsaken]] and [[Scourge]], their name has become synonymous with corruption and extremism, and several quests in [[Tirisfal Glades]] involve attacks on Scarlet Crusade troops, leaders, and strongholds. The Scarlet Crusade maintains several bastions throughout the former lands of Lordaeron, namely the [[Scarlet Monastery]], and up until the [[Cataclysm (event)|Cataclysm]] - [[Hearthglen]], [[Tyr's Hand]], the fortified [[Scarlet Bastion]] of [[Stratholme]], and several smaller camps and [[scout tower]]s spread throughout the whole area of northern Lordaeron.\r\nIt is one of the hierarchies left over from the [[Lordaeron (kingdom)|kingdom of Lordaeron]] after its destruction by the Scourge. After the attack on the [[Scarlet Enclave]], the Scarlet Crusade renamed itself to the [[Scarlet Onslaught]] and operated in [[Northrend]], though some members of the original Scarlet Crusade did not transfer to the Scarlet Onslaught.\r\nSince the fall of the [[Lich King]], the Scarlet Crusade has experienced a downfall, losing many of its holdings in the now-recovering Plaguelands to the [[Argent Crusade]], and many of its surviving members, ironically, to [[undeath]] as the [[Risen]].\r\nDuring the [[third invasion of the Burning Legion]], the remnants of the Scarlet Crusade in Lordaeron regrouped at the Monastery under the command of [[High Commander Goodchilde]], they were soon assaulted by the [[Knights of the Ebon Blade]] who totally wiped them out, in order to resurrect [[Sally Whitemane]] as a member of their new [[Four Horsemen]]. In Northrend, while the Scarlet Onslaught was largely dismantled and originally stated to be the replacement for the Crusade, [[New Hearthglen]] continues to operate, even though it has lost the majority of its leadership and its goals have been dashed away, and was interchangeably referred as the Crusade and as the Onslaught.\r\nAs of the end of the [[Fourth War]], the \"Scarlet Brotherhood\" was formed, marking a resurgence of the Scarlet ideology in Lordaeron, they declared themselves to be [[House Menethil]] loyalists and were politically opposed to the [[Alliance]], which they saw as being led by a traitor.\r\n===Third War===\r\nThose who would later become the founders of the Crusade met in [[Southshore]] during the [[Third War]], where together they purified a dark crystal into what would become the core of the holy [[Ashbringer]] sword. By that time a faction had started growing in the [[Knights of the Silver Hand]], largely led by [[High General Abbendis|Abbendis]]. This faction was intolerant of what they deemed as the \"lesser races\".\r\nThe core of the Crusade's forces began as a group of survivors of the Silver Hand who regrouped in [[Hearthglen]] after an offer of [[Taelan Fordring]]. Ashbringer in hand, Highlord [[Alexandros Mograine]] led the knights of the now disbanded Silver Hand through Lordaeron. Such were his acts that he and his weapon quickly became legends.\r\n===The Ashbringer===\r\nFollowing the death of [[Terenas Menethil II|Terenas]] and [[Uther]] at the hands of [[Arthas Menethil]], the core of the Crusade's force came to a meeting in Hearthglen to determine whether they should pursue and eliminate Arthas or fight to take back Lordaeron from the [[Scourge]]. Their meeting concludes with the decision of Saidan Dathroan to focus their efforts on [[Stratholme]] and [[Andorhal]] to stop the spread of the undead epidemic.\r\nDuring an assault on Stratholme, however, Saidan Dathrohan became separated and lost during the assault. They were overjoyed when he finally reappeared, but none of them could have imagined the truth: that during his absence he had been killed and replaced by the [[Nathrezim|dreadlord]] [[Balnazzar]].\r\nThe remnants of the Silver Hand managed to strike an alliance with the communities of [[Tyr's Hand]] while also establishing a forward base in an old [[Scarlet Monastery|monastery]] not far of [[Capital City]]. However, dissensions started appearing in the leadership of the human resistance. [[Lord Maxwell Tyrosus]] suggested that in order to retake their fallen cities, the order should recruit among the [[Night elf|night elves]] of [[Kalimdor]] and the [[Dwarf|dwarves]] and [[gnome]]s of [[Khaz Modan]]. Other prominent leaders such as [[High General Abbendis]] disagreed, considering the fate of Lordaeron the affairs of men.\r\nWhen [[Alexandros Mograine]] showed the will to attack the Forsaken, Balnazzar began manipulating the organization to serve his own ends. Together with his brother [[Varimathras]], he devised a plan to remove a serious threat to both of them: Mograine and his [[Ashbringer]] sword. As Saidan Dathrohan, he started talking a lot with Alexandros's son [[Renault Mograine|Renault]], playing on his desire for approval and recognition, until he eventually managed to convince him to betray his father. Renault led his father and High Inquisitor Fairbanks into Stratholme, where they were set upon by the Scourge. Though Alexandros fought bravely, and many undead fell before his blade, he eventually dropped the Ashbringer, which Renault used to stab his father through the back before fleeing. Fairbanks, who had been buried beneath the undead bodies and thought slain, eventually returned to the Scarlet Monastery and tried to tell the others what had happened. Saidan Dathrohan claimed he had been tainted by the undead, and he was executed. However, there were those who believed that their comrades had fallen from their once-noble purpose, and left to form their own order, the [[Argent Dawn]]. Those that remained formally named themselves the Scarlet Crusade.\r\nOne day, Renault's younger brother Darion Mograine, who had joined the Argent Dawn, came walking into the chapel of the Scarlet Monastery. Renault initially assumed he had come to join the Scarlet Crusade, until he saw what he was carrying: the Ashbringer. Furious, he began to savagely beat Darion, not noticing that a strange shadow was emerging from the blade. The shadow coalesced into the form of Alexandros Mograine and, after accusing his son of betrayal and murder, killed him. Darion took the Ashbringer and left, and soon after [[Taelan Fordring]] was appointed as commander at the Monastery.\r\n[[High General Abbendis]] was later mortally wounded by the undead and died in his daughter's arms while defending [[Hearthglen]]. The reinforcements from the Monastery led by [[Sally Whitemane|High Inquisitor Whitemane]] managed to save the city.\r\n===A Cleansing Fire===\r\nIn year 24, the Scarlet Crusade patroled Lordaeron villages, checking them for the plague. On one such patrol, Saidan and [[Sir Thomas]] led a group of crusaders into a village, which was deemed corrupted by the Grand Crusader. Thus, the crusaders slew the townsfolk.\r\nLater, the crusaders struck at a settlement north of [[Dalson's Tears]] in the [[Western Plaguelands]] which housed Sir Thomas' family. Unbeknownst to him, Thomas killed his family, and it was too late when he realized what he has done, and went mad. The other crusaders dragged him back to the Scarlet Monastery. Saidan then convinced Thomas to join the crusaders in an attack against the Scourge during [[Hallow's End]]. Although he killed Scourge, Thomas also killed his fellow crusaders. As such, the Crusade was forced to cut down their former brother. Then, the soldiers brought his body back to the monastery.\r\n===World of Warcraft===\r\nThe Crusade seemingly established their own Church to persuade the folk to join in.\r\nAt some point, rumors flew that a plaguebearer was hiding around a village. The Scarlet Crusade had seen to it that every last inhabitant was rounded up and burned alive. Among the villagers was the family of the [[paladin]] [[Lord Thorval]], who yearned to hunt down the Crusaders.\r\nDue to its origins as the regrouped survivors of the Silver Hand, the Scarlet Crusade counted members from citizens and races of all over the [[Alliance of Lordaeron]], including [[High elf|high elves]] of [[Quel'Thalas]], [[Dwarf|dwarves]] of the [[Alterac Mountains]] and human citizens of [[Stormwind (kingdom)|Stormwind]], [[Alterac (kingdom)|Alterac]], [[Kul Tiras (kingdom)|Kul Tiras]] and [[Dalaran (kingdom)|Dalaran]]. Their opinion of the exterior world turned sour, however, and they started seeing other races than humans as unclean. Human outsiders were still recruited but only after facing dangerous trials. It was additionally suspected that the organization had ties to wealthy intolerant families that supported them.\r\nThe Scarlet Crusade continued to cling to their scattered holdings, obsessed with eradicating the undead and retaking their once-beautiful homeland. The Crusaders became intolerant of all non-human races, regardless of alliance or affiliation. They started believing that any and all outsiders were potential carriers of the undead plague - and must be destroyed. The [[Scarlet Monastery]] was converted into a Scarlet Crusade stronghold by [[Renault Mograine|Scarlet Commander Mograine]], who commanded a large garrison of fanatically devoted warriors, and High Inquisitor [[Sally Whitemane]], the true master of the fortress. However, after Commander Mograine's mysterious death, he was eventually replaced by [[High Commander Goodchilde]].\r\nAt some point after the formation of the Scarlet Crusade, the Scarlet Monastery was attacked by the [[Scourge]] three times in the [[Summertide Assault]]s. The Crusade also attempted a strike against the Scourge base in [[Northrend]], and built a [[Scarlet Fleet|fleet]] specifically for that purpose. The attempt failed, although the Crusaders reached as far as the mouth of [[Icecrown Glacier]]. There were many casualties among the high ranks of the Crusade, including its first and only [[Barean Westwind|Grand Admiral]], first [[Orman of Stromgarde|Captain General]] and first [[Invar One-Arm|Chief Assassin]].\r\nThe Scarlet Crusade also created many new anti-undead weapons, such as an attempt at a second [[Ashbringer]] in the form of a staff they called [[:Light's Wrath]]. However, [[Balnazzar]] intervened, interrupting their efforts and triggering a violent magical explosion. The damaged staff's power proved nearly uncontrollable. After several wielders tried and failed to use the staff safely, the elite magi of the [[Kirin Tor]] hid it away lest it unleash further deadly calamities. The human mage [[Timolain the Accursed|Timolain]] was also commissioned to create powerful new bows and guns.\r\nThe Scarlet Crusade has been raiding the [[Forsaken]]'s holdings, and the Forsaken of [[Brill]] have fended off their incursions, retaliated in kind, and tested their poisons on [[Captured Scarlet Zealot]]s. The Forsaken in turn has enlisted [[Horde]] [[adventurer]]s to aid [[Nathanos Blightcaller]] in conducting strategic strikes against the Scarlet Crusade in [[Tyr's Hand]] in order to soften them up for the assault on [[Stratholme]]. Nathanos directed adventurers to slay [[Demetria]] — the chief advisor to Grand Crusader [[Saidan Dathrohan]].\r\nMeanwhile, [[Tirion Fordring]] enlisted the aid of adventurers to redeem his son [[Taelan Fordring]], who has risen through the ranks of the Scarlet Crusade and is now their [[Highlord]]. Tirion has the adventurer collect numerous mementos and deliver them to Taelan in order to restore his faith in honor and nobility. Tirion's plan worked; Taelan was moved by the mementos and desires to reunite with his father so they can both become heroes of the [[Alliance]] and of [[Lordaeron]]. Taelan and the adventurer sneak out of [[Hearthglen]] to regroup with Tirion but they were caught by [[Grand Inquisitor Isillien]] who murdered Taelan for his desertion. Tirion Fordring slays Isillien in retribution while the adventurer dispatched Isillien's [[Crimson Elite]]s. In the aftermath of the battle, Taelan's death had spurred Tirion to redeem the [[Order of the Silver Hand]] so that evil, regardless of its politics or pleasantries, is extinguished from the world.\r\nIn Stratholme, the [[undead]] [[Scourge]] — led by the powerful [[lich]], [[Kel'Thuzad]], is locked in battle with a contingent of Scarlet Crusaders, led by Grand Crusader Dathrohan. Both forces held portions of the ravaged city and both sides were locked in constant, violent combat. The [[Argent Dawn]] has been sending adventurers into Stratholme to contend with both factions. Despite their tenuous alliance, [[Duke Nicholas Zverenhoff]] of the [[Argent Dawn]] condemned the Scarlet Crusade as [[Blasphemy|blasphemers]] and directed adventurers to slay [[Archivist Galford]] and burn down his archives in order to take away the Scarlet Crusade's most valued documents and punish them for their heretical zealotry. Adventurers eventually confronted Grand Crusader Dathrohan and during their battle with him, uncovered that he was really the [[nathrezim]] [[Balnazzar]] in disguise. Adventurers sent the [[Head of Balnazzar]] to Duke Nicholas Zverenhoff as proof of Balnazzar's evil masquerade. Zverenhoff was shocked that the Crusade was manipulated by such an evil force and pondered what the ramifications of Balnazzar's corruption will have on the Scarlet Crusade should the truth come out.\r\nAt some point, the Scarlet Crusade seems to have launched a first assault on [[Northrend]]. [[Admiral Barean Westwind]], [[Invar One-Arm]] and [[Orman of Stromgarde]] were all lost there.\r\nSome Scarlet Crusaders allied with the [[Argent Dawn]] at [[Light's Hope Chapel]] in order to attack [[Naxxramas (Classic)|Naxxramas]], though the temporary truce was not sanctioned by the Grand Crusader.\r\n===The Burning Crusade===\r\nBy that point, the Scarlet Crusade's misguided zeal was so strong that it had even tainted the blessing spoken over their [[Tyr's Hand Holy Water|holy water]]. The [[Blood Knights]] of [[Quel'Thalas (kingdom)|Quel'Thalas]] sought to exploit that taint to prepare a [[Extinguishing Mixture|mixture]] that was to extinguish the [[Alonsus Chapel Eternal Flame|eternal flame]] of the [[Alonsus Chapel]] in [[Stratholme]].\r\n====The Fall of the Scarlet Enclave====\r\nBy that point, the death knights had laid waste to [[Havenshire]] and were now seeking to find out more about this \"Crimson Dawn\" mentioned in [[New Avalon]]'s registry, taken from the [[town hall]] after they murdered New Avalon's [[Mayor Quimby]]. They discovered that a [[Scarlet Courier|courier]] had been sent from [[Hearthglen]] by High Commander [[Galvar Pureblood]], informing Abbendis that an army of Crusaders from Hearthglen and Tirisfal were being assembled to reinforce the Enclave and battle the forces of Acherus. One of the death knights, disguised as the courier (having murdered the real courier, taking his clothing and Pureblood's message), delivered the message to Abbendis. Realizing that the Plaguelands were lost, Abbendis ordered \"the courier\" to return to Pureblood, inform him to turn his armies around and prepare for the journey to Northrend. She gave \"the courier\" a copy of her diary, claiming it would explain everything. It was at this point that she declared that the Scarlet Crusade was no more - that they were now the [[Scarlet Onslaught]].\r\nThe message never reached Pureblood, and his forces were annihilated by the Scourge as a result. With the combined army marching to their doom, High General Abbendis boarded her flagship, the ''[[Sinner's Folly]]'', and set sail for Northrend, leaving the Crusade to its fate.\r\n===Shadowlands===\r\nScarlet Crusaders can be found as [[Fanatic Crusader]]s atoning for their sins in Revendreth. [[Houndmaster Loksey]] is also located in Revendreth facing atonement.\r\n==Territories==\r\nOnce, the Scarlet Crusade controlled much of the [[Plaguelands]] in northern [[Lordaeron]]. All of their major holdings have been destroyed or taken over by other forces.\r\nIn the [[Eastern Plaguelands]] they had the city of [[Tyr's Hand]], and the [[Scarlet Bastion]] within the ruins of [[Stratholme]] under their control. Both fell to the undead when its inhabitants were transformed, at least in Stratholme, into the [[Risen]]. Some time prior the [[war against the Lich King]] they lost the [[Scarlet Enclave]], east of Tyr's Hand, to the [[Scourge]]. Its survivors would organize into the [[Scarlet Onslaught]] and sail to [[Northrend]] where they would begin anew.\r\nIn the [[Western Plaguelands]] they once settled the town stronghold of [[Hearthglen]], but they would ultimately lose it to the [[Argent Crusade]] who transformed it into their new headquarters. They held outposts throughout Western Plaguelands as well, though, these have all been purged; such as the [[Charred Outpost]].\r\nIn [[Northrend]], the Onslaught primarily operates out of [[New Hearthglen]], located in the [[Dragonblight]], on Northrend's southern coast. There are two other bases in the Dragonblight: the [[Onslaught Base Camp]] located north of the [[Carrion Fields]] beneath [[Naxxramas]], and the [[Scarlet Point]] east of the [[Crystal Vice]]. There is also a more secluded base, the [[Onslaught Harbor]], set on a broken island off the mountainous, western coast of [[Icecrown]].\r\nThe last bastions of the Crusade were located in the [[Tirisfal Glades]]. The [[Scarlet Monastery]], a peaceful monastery that was converted into a stronghold of the fanatical Crusade, and the [[Scarlet Palisade]], an outpost which protects the [[Solliden Farmstead]], as well as several towers scattered through the zone. One of these towers, the [[Scarlet Watchtower]], was dispatched by the Forsaken, killing its leader, [[Captain Perrine]]. The Forsaken ultimately dispatched the Crusaders at the [[Scarlet Palisade]] as well after rescuing [[Lilian Voss]], removing it as a threat. The [[Scarlet Watch Post]] was then slaughtered when their leader, [[High Priest Benedictus Voss]] was killed by his daughter, Lilian, in vengeance. The monastery was noted as being attacked several times, though it was ultimately finished off by the [[Knights of the Ebon Blade]] when they sought to raise [[Sally Whitemane]] as one of the [[Four Horsemen]].\r\nThe status and safe locations of the Scarlet Brotherhood are largely unknown. They reference having the last Menethil heir in a secure safe location, which is specified to be secret. While it is possible this location, and heir, is fabricated (namely as Calia was noted as having a daughter, not a son as the Scarlet Brotherhood claims); it is unknown. The only hint of their presence is that the Brotherhood's pamphlets are entirely centralized in Tirisfal Glades, namely near the Calston Estate. The last remaining Scarlet tower in Tirisfal to not have been destroyed is the [[Crusader Outpost]]. Led by [[Captain Vachon]], the area is assailed by adventurers sent by [[High Executor Derrington]] . Rather than kill the captain, however, the area is merely assailed to set the Crusade back and the Captain is never actually killed; despite being present through both this attack and a previous attack from [[Lilian Voss]]. Whether he or any of his remaining crusaders became part of the Brotherhood or were slain another time is unknown.\r\n==Relations==\r\nThough the Crusade's ranks are all human, it is not openly welcomed by the [[Alliance]]. However, its mission appeals to most within the Alliance, who generally agree that the [[undead]] need to be removed from [[Lordaeron]] so its citizens can return home. As news of the Crusaders' rising madness compete with tales of their good deeds and names of heroes amongst their ranks, especially the less informed peasants of regions far away from former Lordaeron still view this organization as a stalwart defender against the undead threat. In part, this is true, as the Crusade has indeed rescued refugees and defended civilian settlements in the Plaguelands many times, including a project to re-settle villages that have been destroyed by the Scourge during the war. Scarlet Crusaders protected the [[Solliden Farmstead]] and its inhabitants, making it one of the few places in northern Lordaeron where the native farmfolk were able to survive to this day and also one of the few places in Lordaeron where they can get food that is unaffected by the [[plague of undeath]]. Until the Forsaken sent their newly risen champions from [[Deathknell]] to deal with the situation.\r\nGenerally, the actions of the Scarlet Crusade are tolerated out of ignorance, and both the [[Alliance]] and the [[Church of Holy Light]] distance themselves from the Crusade's activities officially, but without trying to interfere. The Scarlet Crusade, maintained recruitment officers within the Alliance prior to its destruction - examples can be found in the [[Cathedral of Light]] in Stormwind and in the Alliance outpost of [[Nijel's Point]].\r\nThe Scarlet Crusade has killed countless refugees fleeing the horrors of the Scourge, regarding them as possible carriers of the plague or even undead sympathizers, and their growing zealotry made the Crusade enemies all over [[Azeroth]]. Travelers were advised to stay clear of Scarlet Crusaders regardless of whether any undead are in the party.\r\nDespite their \"alliance\" against [[Kel'Thuzad]] in the flying citadel of [[Naxxramas]], the Scarlet Crusade and the [[Argent Dawn]] were strongly opposed to each other. At [[Light's Hope Chapel]], [[Duke Nicholas Zverenhoff]] denounced the blind zealotry of the Crusade, and how they have destroyed many innocents in the name of the Light, even calling them [[Blasphemy|blasphemers]] for their crimes. During their meeting, [[Eligor Dawnbringer]] of the [[Brotherhood of the Light]] managed to keep relations between the organizations from turning violent, but he threatened them to leave them to the justice of [[Tirion Fordring]] and the [[Knights of the Silver Hand]] if the representatives of the Crusade were no longer present on amicable terms. Another example of their hostility, after raiding a Scarlet Crusade prison house, the [[Adventurer|Death knight of Acherus]] discovered that there were a number of Argent Dawn prisoners there, with apparently most of them already dead.\r\n===Scarlet Onslaught===\r\nThe rallied forces of [[Brigitte Abbendis]] that sailed to [[Northrend]] to combat the [[Lich King]]. Establishing numerous footholds, such as [[New Hearthglen]] and [[Onslaught Harbor]]; they sought to find justice for Lordaeron and their own crusaders who had been slaughtered fighting the Scourge. Despite this, they remained overtly hostile to any and all outside forces; leading to the [[Argent Crusade]] under [[Eligor Dawnbringer]] to dispatch Abbendis and many of her subordinates. Rallied by [[Barean Westwind]], the legendary Scarlet admiral who was found by Abbendis wandering Northrend (claimed to have survived by a miracle of the light); the remaining Onslaught members moved to Onslaught Harbor to assail the Lich King directly. Here, they were once again harried by heroes at the behest of the [[Knights of the Ebon Blade]]; where it was revealed that Barean had indeed died years ago in Northrend. \r\nSimilar to the Crusade's own Saiden Dathrohan, Barean's corpse was possessed by the defeated Dreadlord, [[Mal'Ganis]], who had harbored a desire for vengeance after his near death in battle against [[Arthas Menethil]]. Disappearing and leaving the Onslaught leaderless, it miraculously survived in New Hearthglen past the war. It was revisited again by priests of the [[Conclave]], seeking allies in their war against the [[Burning Legion]]. There, [[Mariella Ward]] and her fellow Scarlet Apostates were recruited after defeating the new Scarlet leader, [[Inquisitor Ward]]; though the Onslaught remains firmly rooted in New Hearthglen.\r\nIt is the only branch of the Crusade that is still active with a militant force; though they are extremely far from their homeland and their objectives, if they have any, are completely unknown.\r\n===Crimson Legion===\r\nAn elite force of the Crusade is the Crimson Legion, led by the Grand Crusader himself. The Crimson Legion appeared to have directly linked back to Dathrohan and guarded his sanctum within [[Stratholme]]. They held their own version of the Scarlet Crusade tabard, an alternating pattern of white and red with a white version of their Scarlet flame iconography upon the middle. This tabard was also worn by high-ranking members of the Crusade, such as [[Brigitte Abbendis]], though it is unknown if that means they were also part of the Crimson Legion. It, alongside most of the Crusade in the Eastern Plaguelands, was decimated by various forces. They were put to an end when [[Balnazzar]] revealed his treachery and shed his Dathrohan disguise; raising them all into the ranks of his [[Risen]].\r\n===Scarlet renegades===\r\nThe Scarlet renegades were former members of the Scarlet Crusade who have openly rebelled against the order. They sought to reform the order after having realized the evil corruption of the crusade. The Renegades sought redemption after the actions of the crusade and have thus allied themselves with the Alliance. They asked for their aid to seize control of the crusade and, while successful in doing so, their leadership appears to have fallen to madness.\r\nTheir status following ''Mists of Pandaria'' is unclear.\r\n==Books and other texts==\r\n*[[News From The North]]\r\n*[[Priestly Preening: Be Like Your Betters]]\r\n*[[Turning the Other Cheek]]\r\n*[[Musings of the High General]]\r\n*[[Grand Inquisitor Isillien's Journal]]\r\n*[[The Cursed Old Wolf]]\r\n*[[The Last Menethil]]\r\n*[[The Traitor King (item)]]\r\n*[[The Would-Be Queen]]\r\n===Military ranks===\r\n===History of the Crusade===\r\n[[Isillien]] was formerly a priest of the [[Light|Holy Light]] in Lordaeron, assigned to be the liaison for the Knights of the Silver Hand. There he worked closely with the elder [[High General Abbendis]] and his youthful charges, tutoring the young paladins in their quest for truth. [[Priest]]s and paladins fought as the Scourge attacked the city, but they fled as Lordaeron fell around them. Some whisper it was the wounds both men received in battle, or perhaps just the shock of seeing their whole purpose destroyed, but since that day both Isillien and Abbendis had become quite insane. Isillien and Abbendis wandered the area as the Scourge defiled the land, destroying what undead they could, gathering what warriors would join them. They had but one concern: eradication of all that had destroyed Lordaeron.\r\nIsillien and High General Abbendis gathered together several other people to join them. Among them were Abbendis's daughter [[Brigitte Abbendis|Brigitte]], [[Alexandros Mograine]] (wielding the newly-forged [[Ashbringer]]) and his son [[Renault Mograine|Renault]], [[Taelan Fordring]], and [[Saidan Dathrohan]]. This group was focused on the singular goal of defeating the Scourge in all its forms.\r\nIn the times after the [[ascension of the Lich King]] and [[Plaguelands civil war|the rise]] of the [[Forsaken]], the elder Abbendis and Isillien felt that although they had a good base, they really needed to attack the [[Scourge]] where they were the thickest: in the [[Eastern Plaguelands]]. Isillien took on the title of Grand Inquisitor, while the elder Abbendis led the majority of the forces to Tyr's Hand in the east to strike at [[Stratholme]]. As they established their bases and took in many more warriors, they destroyed any undead they found.\r\nTaelan Fordring, one of Isillien’s protégés, adored his tutor and his general. He offered his family’s keep and land, untouched by the undead, for their base of operations. The group gained members whose lives had been ruined by the Scourge. Most members have seen a loved one die and, more often than not, be raised to fight alongside her murderer. Isillien became the spokesman for the group, his ravings gaining more followers than repelling them — and who could argue with the man that the undead were evil?\r\nSome had reason to pause when Isillien’s young page was found with Isillien’s knife through his heart, and the priest calmly reported that the page had died that afternoon while hunting, and the undead had raised him and sent him back as an assassin. He was so convincing that the incident cemented the fear for most: if a freshly killed and raised undead can look just like a regular human, they had no idea who among them may or may not be with the Scourge. After a month of quarantine, all priests and [[warrior]]s with the Crusade were declared clean. Frequently, groups of refugees fleeing the undead also fell beneath their furious swords. As the Grand Inquisitor claims, one cannot be too careful. All undead — good, evil or neutral, Scourge or Forsaken — are the rivals of the Scarlet Crusade. The undead are abominations and must be destroyed before the land and the people can heal. They count the Alliance and the [[Church of Holy Light]] as their allies, but these organizations quickly distance themselves from these fanatics and instruct all travelers to give a wide berth to any Crusaders.\r\n===Organization===\r\nThe Scarlet Crusade is structured much like the military. The male Abbendis and Isillien were the leaders. Abbendis was the official head of the Scarlet Crusade. He considered himself the arm of the Crusade while Isillien is the heart. Abbendis guided the military attacks of the Crusade from Tyr’s Hand in the Eastern Plaguelands, communicating frequently with Isillien, who guides the priests in the Crusade in their new roles as inquisitors, based in the Western Plaguelands. He is in charge of questioning undead and mortals alike to ferret out whatever information he can on the movement and settlement of the undead. Isillien acts as the leader of the priests and guides the inquisitions in the west along with his impressionable paladin Taelan, while Abbendis controlled the warriors in the east. The Crusade has thirteen generals leading the lower ranks: 2,000 troops based in Hearthglen and 10,000 based in Tyr’s Hand. The generals were not only chosen by the ranks they had in the war, but also by their dedication to the cause. Few make it very high in the ranks if they do not have a burning fervor to destroy all undead. Veterans who have fought the Scourge before are quickly promoted. Any dissent in the ranks is considered to be caused by undead infiltration, for the Crusade cannot fathom a reasonable mortal having any disagreement with the elimination of the undead. Such individuals are considered to be undead themselves, or worse, deranged undead sympathizers. Thus the organization of the Scarlet Crusade is flawless, as the crusaders work with one mind towards one goal. If they do not work with total agreement, it is at least complete fear of their superiors that keeps them in line. It's based in the Plaguelands, but hunts undead everywhere it can in northern Lordaeron. With the death of the elder Abbendis fighting the scourge, his daughter took over as High General.\r\nCurrently, the head of the Scarlet Crusade is [[Saidan Dathrohan|Grand Crusader Saidan Dathrohan]]. Serving beneath him are [[Demetria]] (the Scarlet Oracle), [[Brigitte Abbendis|High General Abbendis]], [[Grand Inquisitor Isillien]], [[Taelan Fordring|Highlord Taelan Fordring]], and [[Crusader Lord Valdelmar]]. The grand crusader handles the grisly, prolonged siege of Stratholme. Abbendis commands military assaults and assists the grand crusader in the siege, while Isillien handles interrogations and intelligence in the west.\r\n====Membership====\r\nMembership in the Scarlet Crusade is high, relative to the human population of the region. The strong sense of abandonment, futility and fear runs high in all humans on Lordaeron, and the Scarlet Crusade feeds that fear with reassurance that the evil will fall while the good remain untainted. The Crusade attracts mostly warriors, people who find in this post-war state that living by the sword is the only way to survive. They feel the need for a strong community where their skills will be utilized, and the Scarlet Crusade maintains that they need strong warriors for their cause. Some priests are drawn to the righteous eradication of the undead, but they often see the Crusade for the zealots they are and rethink their entry. This, of course, is considered suspicious, and they are often slain for their misgivings. The biggest problem prospective members encounter is assuring the Crusaders that they are not undead themselves. Since the Grand Inquisitor was almost killed by his own page (so the story goes), the group is incredibly paranoid about the undead infiltrating their ranks. There is however one [[undead]] in their ranks ([[High Inquisitor Fairbanks]]) however he has been locked away in an secret room, why the crusaders haven't killed him yet remains a mystery. The supposedly common knowledge that undead are hideously deformed and easy to discern from the living makes no difference to these people; they believe necromancers are capable of disguising the undead as living. Thus, new members (if they survived alerting the Crusade to their desire to join) are quarantined for 30 days to see if they begin to exhibit signs of the plague or being an undead. They are visited by the Grand Inquisitor or the High General during this time and are \"questioned\". No Scarlet Crusader discusses his quarantine and initiation.\r\nMembership is comprised chiefly of human [[warrior]]s, [[ex-paladin]]s, [[priest]]s and [[paladin]]s (dark or otherwise), [[scarlet knight]]s, [[scarlet inquisitor]]s, [[Scarlet Chaplain]]s, [[Scarlet Crusader]]s, and [[scarlet battle mage]]s professions.\r\n====Military====\r\nDespite their increasingly small numbers, the members of the Scarlet Crusade never falter, turn aside, or retreat. The Scarlet Crusade fights directly and it fights to the death.\r\nMost military forces fight conservatively and hoard their members, but the crusaders take no care for their own lives. They wade into battle with zealous fervor, slashing and hacking until they either fall or vanquish all enemies.\r\nOnly the backing of the priests and paladins keep the order alive, both literally and figuratively. The impassioned speeches and charismatic leadership of the order’s healers motivates their troops into battle, and their healing magic keeps their zealots whole. The military training of the order’s paladins serves the crusade well, as the paladins train the members in basic troop formations and simple tactics that increase their odds of survival.\r\nGenerally, members of the Scarlet Crusade don’t bother flanking their enemies, as they’re used to fighting undead that are slow and easy to strike and immune to backstabs. Scarlet Crusade units fight in tight formations. They form rings whenever possible, standing shoulder to shoulder, so no one member risks being surrounded by a shambling mob of undead. If forced to disperse, members try to pair up and fight back to back.\r\nPaladins and priests freely use their healing abilities and spells in combat, not only to bolster their own troops, but to harm undead enemies. Paladins and priests try not to use their turn undead ability, as their goal is to destroy their enemies, not scatter them. If overwhelmed by superior numbers, though, or confident in their ability to destroy nearby undead with a turn attempt, the commanders call upon their holy power. Many Scarlet Crusade priests can rebuke undead; they force their undead foes to cower long enough for the knights to do their work.\r\nWhen fighting living opponents, the Scarlet Crusade varies its tactics only slightly. The Crusade rarely takes on hordes of living enemies; when they do engage the living, it is usually to target individuals or small groups. Members of the Crusade do use flanking maneuvers when fighting the living. They’re most concerned with preventing the escape of their prey, as living opponents move much faster than undead, and often panic. Mounted knights run down fleeing enemies, while the foot soldiers remain behind to engage slower targets. Foot soldiers also use trip attacks to reduce the odds that their prey will escape.\r\n====Locations====\r\nThe Western Crusade’s headquarters are in the rural area of Hearthglen, the inheritance of Taelan Fordring. Their main headquarters are in the Eastern Plaguelands in the small community of Tyr’s Hand. They command from the [[Scarlet Basilica]]. The community is also host to several churches including a newly built [[Scarlet Monastery]], a massive building that draws refugees looking for safety.\r\n==Notes and trivia==\r\n*[[Mathias Shaw]] describes them as a cruel and narrow-minded [[cult]].\r\n*The [[Forsaken]] called them the Scarlet Scum.\r\n*Before the [[Cataclysm (event)|Cataclysm]], the Scarlet Crusade in [[Stratholme]] celebrated the [[Midsummer Fire Festival]].\r\n*According to [[Chris Metzen]], the [[Church of the Holy Light]] fully supports the [[Argent Crusade]] and hates the Scarlet Crusade.\r\n*The Scarlet Crusade was unique among the human factions for having many houndmasters and huntsmen even before the [[hunter]] class was introduced to the [[Human (playable)|human]] race in ''[[World of Warcraft: Cataclysm]]''.\r\n*In ''[[World of Warcraft]]'' the story of the Crusade was originally slightly different: founded by [[Brigitte Abbendis|High General Abbendis]], [[Grand Inquisitor Isillien|High Inquisitor Isillien]], and the Scarlet Highlord [[Alexandros Mograine]], the Crusade was at first a noble order. The madness and insane zealotry were only brought later by Grand Crusader [[Saidan Dathrohan]], and this is presumably why the [[Hall of Champions]] in the [[Scarlet Monastery]] pays homage to various races other than humanity. The [[World of Warcraft: Ashbringer|''Ashbringer'' comic]] would depict the formation of the Crusade occurring ''after'' Alexandros and [[High Inquisitor Fairbanks|Fairbanks]]' deaths, in which case they would have never been members.\r\n*There is a [[roleplaying]] server called [[Server:Scarlet Crusade US|Scarlet Crusade US]].\r\n==See also==\r\n*[[Crimson Dawn]]",},
			["Scarlet Crusade Documents"] = { content = "'''Scarlet Crusade Documents''' are important reports and orders carried by [[Meven Korgal]] for distribution throughout the [[Scarlet Crusader]] commanders throughout [[Tirisfal Glades]].\r\n==Source==\r\nThe documents can be found after killing [[Meven Korgal]] southeast of [[Deathknell]].\r\n==As a quest objective==\r\n*The Red Messenger\r\n*Vital Intelligence\r\n==Notes==\r\nRequires The Red Messenger quest to drop.\r\nOn this document [[Captain Melrache]] is referred to as Captain Melrose.",},
			["Scarlet High Clerist"] = { content = "The '''Scarlet High Clerist''' is a level 63 [[elite]] [[rare mob]] [[human]] found in the [[Western Plaguelands]]. Usually by the Scarlet's Guard Tower outside their town of [[Hearthglen]], he has a fairly strong Power Word: Shield and a very large greater heal spell.",},
			["Scarlet Hold"] = { content = "'''Scarlet Hold''' is located in east [[New Avalon]]. [[High Abbot Landgren]] and [[High General Abbendis (female)|High General Abbendis]] are situated out front fending off a mob of displeased [[Citizen of Havenshire|Citizens of Havenshire]] and [[Citizen of New Avalon|New Avalon]] who are distraught over the [[Scourge]]'s attacks on New Avalon and [[Havenshire]].\r\nThe hold is involved in the following quest:\r\n*Death Comes From On High",},
			["Scarlet inquisitor"] = { content = "'''Inquisitors''' are the reason that even the dead have learned to fear the [[Scarlet Crusade]]. These former [[priest]]s and [[healer]]s, once dedicated to aiding the wounded, have turned their training in the [[Holy Light]] to a more devious\r\nend — torturing a captured subject without allowing the prisoner the luxury of death. For this reason, inquisitors are given high authority within their own organization — and are feared by their own people as much as their enemies. In spite of their title, inquisitors do not always torture simply to extract information — many enjoy inflicting pain, and that quality makes them dangerous in combat.\r\nGrand Inquisitor [[Isillien]] is one of the most influential figures in the Scarlet Crusade, and rumors say he handpicks the few others who are deemed worthy to bear the mantle of inquisitor. High-ranking inquisitors train pupils in the subtle art of manipulation as well as the destructive and fearsome arts for which the inquisitors are famous. It is the duty of the inquisitor to transform a broken [[Knight of the Silver Hand]] into a loyal zealot of the Scarlet Crusade, such as Highlord [[Taelan Fordring]]. Inquisitors are also responsible for detecting treachery in their own ranks; Inquistors are affiliated with the Scarlet Crusade (at least initially; defectors are possible). Hardly a day passes that the [[Scarlet Crusader|Crusaders]] do not find an [[infiltrator]] loyal to the [[Cult of the Damned]]. \r\nWith the skill to judge a potential traitor comes the power of the executioner; inquisitors have the right and the responsibility to deal with traitors. Betrayal is not limited to siding with the [[Scourge]], of course; disagreeing with [[Grand Crusader Dathrohan]] might be grounds for elimination as well. The final responsibility of the inquisitor is morale — in many ways, inquisitors retain the role of normal priests, and they ensure the soldiers in their care remain in good spirits. In spite of the fear that even other members of the Scarlet Crusade feel toward inquisitors, they retain the role of confessor, moral support, and other responsibilities that one might expect from a priest of the [[Church of the Holy Light]].\r\nScarlet inquisitors are almost exclusively human priests, but a few [[paladin]]s have the dedication and magical skill to follow this path. As high-ranking members of the Scarlet Crusade, individuals outside the organization look down on them even more than other Crusaders, and with justification. Even inquisitors who are still sane have a level of zeal that the\r\naverage person or adventuring party cannot tolerate. The Church of the Holy Light takes a stand against the inquisitors' torture and other methods, but the Crusaders dismiss such accusations as naïve. The [[knight]]s and priests of [[Stormwind]] have not yet experienced the full force of the Scourge, and the Crusade believes that this lack of knowledge prevents them from being willing to use the necessary amount of force. The Scarlet Crusade's loyal knights and priests are convinced (by their inquisitors) that the church will eventually see their way of life as necessary. Inquisitors see themselves as the voices of reason in a world clouded with deception; they burn through the lies of the world with the searing flame of truth. Most inquisitors are self-confident, and a large number of them take leadership roles, such as [[High Inquisitor Whitemane]] in the Scarlet Monastery. On the rare occasions that an inquisitor leaves an outpost to go adventuring, he functions much the same as he does within the organization: as a leader and support for his group. Unlike many other members of the Scarlet Crusade, however, inquisitors are cautious in combat and remain as far from melee as possible, using their magic to disorient their enemies or bless their allies with the power of the Holy Light. While inquisitors are potent healers, this role is typically considered secondary to eliminating their targets or enhancing their allies’ abilities.\r\n==Known inquistors==\r\n*[[Sally Whitemane]]\r\n*[[Isillien]]\r\n*[[Fairbanks]]\r\n==Inquisitors in WoW==\r\n*[[Scarlet Inquisitor]]\r\n*[[Crimson Inquisitor]]",},
			["Scarlet Key"] = { content = "#REDIRECT [[The Scarlet Key]]", redirect = "The Scarlet Key",},
			["Scarlet knight"] = { content = "The '''scarlet knights''' are [[ex-paladin]]s, [[warrior]]s, and [[mounted warrior]]s that joined the [[Scarlet Crusade]]. The Scarlet Crusade has a couple of ex-paladins dedicated to training new [[paladins]] that join the organization. Paladins seem drawn to the organization, but few can balance their commitment to the Light with the dark deeds done by the Scarlet Crusade, so few keep their holy status. Most abandon the teachings of the [[Light]] and find their abilities changing to suit their new mindsets. A broken [[Knight of the Silver Hand]] is transformed into a loyal zealot of the [[Scarlet Crusade]] by [[Scarlet inquisitor]]s. The Scarlet Crusade's loyal knights are convinced (by their inquisitors) that the [[Church of the Holy Light]] will eventually see their way of life as necessary. The common folk are terrified of the Crusade, and few oppose the scarlet knights out of fear for their lives. Scarlet knights work with the Scarlet Crusade [[priest]]s, who rebuke undead, forcing the undead foes to cower long enough for the mounted knights to do their work. They also run down fleeing enemies.\r\nThe shields of the former knights of the Holy Light once glowed white. As they turned to the Scarlet Crusade, the light of their shields turned blood red.",},
			["Scarlet Monastery"] = { content = ":<span class=\"noexcerpt\">''For the pre-''Mists of Pandaria'' instances, see [[Scarlet Monastery Graveyard]], [[Scarlet Monastery Library]], [[Scarlet Monastery Armory]], and [[Scarlet Monastery Cathedral]].''</span>\r\n<div style=\"float:right;\">\r\n<tabber>\r\n Instance=\r\n Lore=\r\n</tabber>\r\n</div>\r\nThe '''Scarlet Monastery''' is one of the last strongholds in the world that belonged to the fanatical [[Scarlet Crusade]]. The [[Scarlet Bastion]] within the ruins of [[Stratholme]], the [[town]] of [[Hearthglen]], the town of [[Tyr's Hand]] and the [[Scarlet Enclave]] all fell during the last years. Located in the northeast corner of the blighted [[Tirisfal Glades]], the Scarlet Monastery was once a [[church|cathedral]] to the [[Light]], taken over by zealots.\r\nThe Scarlet Monastery is a complex of two [[instance]]d dungeons, [[Scarlet Halls]] and [[Scarlet Monastery (instance)|Scarlet Monastery]]. Heroic mode is available for both wings at level 90.\r\n==History==\r\n''The Monastery was once a proud bastion of Lordaeron's priesthood - a center for learning and enlightenment. With the rise of the undead [[Scourge]] during the [[Third War]], the peaceful Monastery was converted into a stronghold of the fanatical Scarlet Crusade. The Crusaders are intolerant of all non-human races, regardless of alliance or affiliation. They believe that any and all outsiders are potential carriers of the undead plague - and must be destroyed. Reports indicate that adventurers who enter the monastery are forced to contend with [[Scarlet Commander Mograine]] - who commands a large garrison of fanatically devoted warriors. However, the monastery's true master is [[Sally Whitemane|High Inquisitor Whitemane]] - a fearsome priestess who possesses the ability to resurrect fallen warriors to do battle in her name.''\r\nBefore the [[Third War]], the Monastery served as a seminary for [[paladin]]s-in-training. In his youth, [[Alexandros Mograine]] spent months training and praying here.\r\n===Ashbringer===\r\nBefore the [[Knights of the Silver Hand]] that would later form the Scarlet Crusade inhabited this abandoned monastery, a [[jungle troll]] named [[Zabra Hexx]] made it his home. From its many books, he learned the ways of the [[Light]]. [[Alexandros Mograine]], [[Brigitte Abbendis]], and [[Lord Maxwell Tyrosus]] found the troll and claimed the monastery for the Silver Hand as a defensible forward base. Later, the Silver Hand splintered into the Scarlet Crusade and [[Argent Dawn]], with the Crusade keeping the Monastery and renaming the place to Scarlet Monastery.\r\n[[Sally Whitemane|Inquisitor Whitemane]] and [[Renault Mograine]] then relocated here. Not only did it become a home of the Crusade, but it also was a military area as well as a place for their prisoners. When the Crusade learned about a Scourge attack on [[Hearthglen]], Renault commanded Whitemane to gather a squad of soldiers and head to Hearthglen. As Whitemane left, [[Darion Mograine]], guided by the voice of the Ashbringer, arrived to the Monastery, where the voice manifested into the spirit of Alexandros who killed Renault for his betrayal in the Monastery's chapel.\r\nAfter the battle at the [[Light's Hope Chapel]], there was a meeting between [[Castillian]], [[Balnazzar]], and [[Varimathras]] taking place north of the Scarlet Monastery.\r\n===Compendium of Fallen Heroes===\r\nAt some point after the formation of the Scarlet Crusade, the Monastery was attacked by the Scourge three times in the [[Summertide Assault]]s.\r\nSeveral [[Forsaken]] were captured and brought to the monastery, being interrogated by [[Halbin]]. During one night of torture, anger overwhelmed him, and for only a brief instant, his hold over [[:Light's Wrath]] slipped. An explosion rocked the torture chamber and engulfed Halbin in holy fire. It is said he died a slow death, his howls of agony ringing through the Scarlet Monastery for days on end.\r\n===World of Warcraft===\r\n[[Raleigh the Devout]] believed in the cause of the Scarlet Crusade to rid Azeroth of the undead. As he spent time at the Monastery, he realized that the Crusade's grasp on reality was slipping because they thought everyone was plagued who didn't wear the tabard of the Crusade. Innocent men and women were tortured because they were supposedly plagued.\r\n[[Meven Korgal]] was sent from the Monastery to spy on [[Deathknell]].\r\n===Legends===\r\nDuring the [[Hallow's End]] in Year 24, the [[Headless Horseman]] was created in the Monastery by [[Balnazzar]] using [[fel]] energies over the dead body of [[Thomas Thomson]].\r\n===Exploring Azeroth===\r\nFollowing the third invasion and the [[Fourth War]], [[Mathias Shaw]] mentioned in his reports that the Scarlet Crusade was totally wiped out by the Ebon Blade when they went to the Monastery to destroy them and resurrect Sally Whitemane.\r\n===Map===\r\nOld instance maps\r\n==Notes==\r\n*In the game, north of the monastery there are inaccessible mountains. In the ''[[World of Warcraft: Ashbringer|Ashbringer]]'' comic, the area was portrayed as a forested area.",},
			["Scarlet Onslaught"] = { content = "The '''Scarlet Onslaught''' were once the [[Scarlet Crusade]], and have traveled to the [[Dragonblight]] of [[Northrend]] in their hopes of defeating the [[Lich King]].\r\nThe Onslaught appears to have even lower moral scruples than the original Scarlet Crusade, as they now accept [[Onslaught Death Knight|death knights]] and [[Onslaught Raven Priest|shadow priests]] within their ranks. They are led by [[High General Abbendis (female)|High General Abbendis]] (the last of the original founders, as [[Alexandros Mograine|Highlord Mograine]] and [[Grand Inquisitor Isillien]] are dead at this point in time and [[Tirion Fording]] has long left the organization), who now resides in the cathedral of [[New Hearthglen]].",},
			["Scarlet Overlook"] = { content = "The '''Scarlet Overlook''' is located east of [[New Avalon]], just to the southwest of the [[Scarlet Hold]] on the bluffs above [[King's Harbor]].",},
			["Scarlet Point"] = { content = "East from the [[Crystal Vice]], west of [[Light's Trust]].",},
			["Scarlet Raven Tavern"] = { content = "'''Scarlet Raven Tavern''' (aka '''Scarlet Raven Inn'''), is located in [[Darkshire]], [[Duskwood]]. It was once a cheerful and friendly place full of people relaxing after a hard day's work at the fields. Although the hearth has been kept warm, it now holds a more morose crowd, who sit by their tables and drink silently while the darkness presses in on the tavern outside. The inn features several [[quest giver]]s, as well as a few [[vendor]]s.",},
			["Scarlet Scout"] = { content = "'''Scarlet Scout''' can be found in [[Tirisfal Glades]] and [[Scarlet Monastery]] .\r\n==Abilities==\r\n*[[Shoot]]\r\n==Drops == \r\n \r\n0.08% Chance of a [[rare]] drop.\r\n0.96% Chance of an [[Uncommon]] drop.\r\n0.11% Chance of a [[common]] drop.\r\n0.25% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scarlet Tavern"] = { content = "The '''Scarlet Tavern''' is located in southern [[New Avalon]], south of the [[New Avalon Orchard]] and east of the [[Chapel of the Crimson Flame]].\r\n[[Orbaz Bloodbane]] and [[Thassarian]] relocate here from [[Acherus: The Ebon Hold]] in phase two after players complete Victory At Death's Breach!",},
			["Scarlet Tracking Hound"] = { content = "'''Scarlet Tracking Hound''' can be found in [[Scarlet Monastery]].\r\nWhen '''Scarlet Tracking Hound''' is tamed by a [[hunter]] it teaches [[Dash]] Rank 1. Dash Rank 1 will requires 15 points to train your other pets.\r\n==Drops == \r\n \r\n0.05% Chance of a [[rare]] drop.\r\n0.77% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scarlet Trainee"] = { content = "'''Scarlet Trainees''' are level 30 [[human]]s found in the [[Scarlet Monastery]]'s Armory Wing. A large group of them rushes in after [[Herod]] dies.",},
			["Scarlet Trooper"] = { content = "'''Scarlet Troopers''' are level 58-59 non-[[elite]] [[human]] [[paladin]]s that spawn and escort [[Demetria]] <The Scarlet Oracle>.\r\nWhen a player accepts the quest The Scarlet Oracle, Demetria, she and eight Scarlet Troopers will spawn in [[Tyr's Hand]]. They follow a fixed path through [[Corin's Crossing]], still walking on the path, to the [[Plaguewood]]s, and finally to [[Stratholme]] where they will despawn. Scarlet Troopers are not to be taken lightly and are in fact some of the tougher non-elites in the game. The Troopers along with Demetria will attack all [[undead]] or [[hostile]] enemies they encounter, including [[player character]]s.\r\n==Abilities==\r\n*[[Hammer of Justice]]: Stuns the target for X amount of time. Can be dispelled. Does not stack. Believe to be on a ten second cooldown.\r\n*[[Divine Shield]]: Makes the caster invulnerable to all forms of damage and reduces attack speed by 50% for four (or six, I forgot) seconds. Cannot be (normally) dispelled.\r\n*[[Holy Light]]: Heals target for X amount of health. Causes [[Forbearance]].\r\nFor information on strategy, see Demetria's article.\r\n==Additional Info==\r\nIt is very possible that while encountering Demetria you will also encounter the [[Crimson Courier]], who has her own entourage of elite warriors who frequently Charge. There is no scripted event between the two, but the two will help each other. If the Courier and her entourage are added to the fight, it may cause a wipe.",},
			["Scarlet Watchtower"] = { content = "This [[Crusader's Outpost]] is a guard tower located in southern [[Tirisfal Glades]] near the entrance to the [[Sewers]] of [[Undercity]]. It is under the control of the [[Scarlet Crusade]] who can keep a watchful eye on the flight routes from and to [[Undercity]] from here. It is one of the four [[Crusader's Outpost]] towers in [[Tirisfal Glades]]. This particular tower is commanded by [[Captain Perrine]] who guards a chest that contains Egalin's Grimoire.",},
			["Scarlet Watch Post"] = { content = "The '''Scarlet Watch Post''' is a guard tower located in northeastern [[Tirisfal Glades]], just north of the [[Scarlet Monastery]]. Its maintenance despite its remote location is solely to prevent enemies of the [[Scarlet Crusade]] from assaulting the monastery from its less defensible north side. It's one of the four [[Crusader's Outpost]] towers in [[Tirisfal Glades]]. This particular tower is commanded by [[Captain Melrache]].",},
			["Scarlet Zealot"] = { content = "'''Scarlet Zealot''' can be found in [[Tirisfal Glades]] .\r\n==Quests== \r\n==Drops == \r\n \r\n0.11% Chance of an [[Uncommon]] drop.\r\n0.22% Chance of a [[common]] drop.\r\n0.11% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scarshield Infiltrator"] = { content = "#REDIRECT [[Vaelastrasz]]", redirect = "Vaelastrasz",},
			["Scarshield Legion"] = { content = "The '''Scarshield Legion''' is a division of [[Rend Blackhand]]’s [[Blackrock Clan|Blackrock Orcs]] that reside primarily in the [[Lower Blackrock Spire|lower levels of Blackrock Spire]] where they breed and train attack [[worg]]s.\r\n==History==\r\nThe defining characteristic of this organization of [[orc]]s is their use of worgs in battle, evident by their swarming numbers within the halls of [[Hordemar]]. Rend’s ability to harness beasts like worgs into formidable troops is no surprise considering that he and his brother were once part of the [[Sythegore Arm]], the group of orcs once known as [[Raiders]] in the [[Horde (pre-Thrall)|old Horde]] who rode on the backs of the giant creatures. It is possible that when Rend and [[Maim Blackhand]] fled to [[Blackrock Mountain]] they brought with them other surviving members of Sythegore Arm with whom they forged the Scarshield Legion. \r\nUnlike the Arm, however, the Scarshield Legion has been seen fighting along side the worgs as opposed to on the backs of them. The reasons for this are unknown, but it is likely due to the closed quarters of the Legion’s current residence, making most of the members’ destinations within the City reachable by foot. Given the need, however, it is likely that the Scarshield's worgs double as [[mounts]].\r\n==Ranks==\r\nThe current known ranks of Scarshield Legion are:\r\n* [[Scarshield Sentry]]\r\n* [[Scarshield Grunt]]\r\n* [[Scarshield Acolyte]]\r\n* [[Scarshield Quartermaster]]\r\n* [[Scarshield Raider]] \r\n** [[Scarshield Worg]]\r\n* [[Scarshield Infiltrator]]\r\n* [[Scarshield Legionnaire]]\r\n* [[Scarshield Spellbinder]]\r\n* [[Scarshield Warlock]]\r\n==Worg Breeding==\r\n''\"Some say the worg controlled by the Blackrock orcs are the creation of a supernatural force. Others say they are not true worg but instead a breed of demon dog, granted to the orcs by a fallen pit lord. The truth is far less contrived but every bit as frightening.\"'' - [[Galamav the Marksman]]\r\nThe vast population of worgs within lower Blackrock Spire is easily achieved by the Legion’s role to breeding the beasts, as well as train them. Despite the common rumours and belief that the Legion's vicious canines are the product of something otherworldly, their conceiver is not far off. The Legion currently cares for and provides home for the giant [[Halycon]] and her equally large mate [[Gizrul the Slavener]], the parents of nearly all battle-ready Scarshield and [[Bloodaxe Legion|Bloodaxe]] worgs. Both are kept in lower Blackrock spire where they are tended to and heavily guarded, despite their capability to hold their own.",},
			["Scarshield Quartermaster"] = { content = "The '''Scarshield Quartermaster''' guards the [[Orb of Command]] used to teleport into [[Blackwing Lair]]. [[Warchief Rend Blackhand]] calls the quartermaster an incompetent idiot.\r\nWhilst he has the silver dragon indicating a [[rare mob]], he is actually one of the fastest spawning mobs in the game (1 minute 40 seconds).\r\n==Quests==\r\n*Blackhand's Command\r\n==Loot==\r\n*Blackhand's Command ''(Quest-Starting Item)''",},
			["Scarshield Raider"] = { content = "'''Scarshield Raider''' can be found in [[Blackrock Spire]] .\r\n==Drops == \r\n \r\n0.41% Chance of a [[rare]] drop.\r\n2.82% Chance of an [[Uncommon]] drop.\r\n0.25% Chance of a [[common]] drop.\r\n1.05% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scarshield Spellbinder"] = { content = "'''Scarshield Spellbinder''' can be found in [[Blackrock Spire]].\r\n==Drops == \r\n \r\n0.02% Chance of an [[epic]] drop.\r\n0.24% Chance of a [[rare]] drop.\r\n1.12% Chance of an [[Uncommon]] drop.\r\n0.11% Chance of a [[common]] drop.\r\n0.44% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scarshield Warlock"] = { content = "'''Scarshield Warlock''' can be found in [[Blackrock Spire]] .\r\n==Drops == \r\n \r\n0.04% Chance of an [[epic]] drop.\r\n0.33% Chance of a [[rare]] drop.\r\n2.55% Chance of an [[Uncommon]] drop.\r\n0.24% Chance of a [[common]] drop.\r\n1.02% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scarshield Worg"] = { content = "'''Scarshield Worg''' can be found in [[Blackrock Spire]]. When Scarshield Worg is tamed by a [[hunter]] it teaches [[Dash]] Rank 3. Dash Rank 3 will requires 25 points to train your other pets.\r\n==Drops == \r\n \r\n0.03% Chance of an [[epic]] drop.\r\n0.07% Chance of a [[rare]] drop.\r\n1.06% Chance of an [[Uncommon]] drop.\r\n0.04% Chance of a [[common]] drop.\r\n0.03% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scatter Shot"] = { content = "'''Scatter Shot''' is a [[disorient]] effect. \r\n==Tips and tactics==\r\n*If you need to interrupt a spell or ability, Scatter Shot can do it.\r\n*When you're running somewhere and there's a mob in your way that you don't want to fight, Scatter Shot will shut him down long enough for you to run past and out of melee range. Once you're past you can either [[Feign Death]] to reset him or lay a [[Freezing Trap]] or [[Frost Trap]] to gain extra distance.\r\n*If chasing after a mob and within range of this shot, you can use it to disorient the target long enough to lay a Freezing Trap or Frost Trap under it. This will stop it from running, allowing you time to get the kill.",},
			["Scavell"] = { content = "'''Magna Scavell''' of the Order of Tirisfal was the [[Guardian]] for several centuries, starting around more than a millennium prior to the First War. Scavell, a human, was one of the more successful Guardians, working in tandem with the Council to great effect — [[Erbag]] and [[Relfthra]], the Gnomish and Elven representatives to the council, were among his closest friends. Some eight hundred years ago, Scavell decided that he'd had enough of the Guardianship, and sought out likely successors. Over the next few years, he gathered five powerful apprentices: \r\n*Falric was eldest and the smartest.\r\n*Jonas was apparently the most powerful — and the least original.\r\n*Manfred was the most creative.\r\n*Aegwynn mastered the powerful [[Meitre scrolls]] in her first year.\r\n*Natale, despite a fear of demons, was effective at banishing undead.\r\nOf the five, [[Aegwynn]] showed the greatest overall aptitude, and was invested with the power of the ''Tirisfalen'' halfway through her apprenticeship. Scavell survived the transference ritual by only a year- all of his apprentices joined the Order, but only succeeded their master by decades. Four hundred years after his death, Aegwynn named her pet [[Thunder Lizard]] after her long-gone master.",},
			["Scavenger Paw"] = { content = "'''Scavenger Paws''' are collected by [[Forsaken]] from the [[Young Scavenger|Young]] and [[Ragged Scavenger]]s of [[Deathknell]] to make armor.\r\n==Source==\r\nScavenger Paws drop from [[Ragged Scavenger]]s and [[Young Scavenger]]s found just outside [[Deathknell]]. \r\n==As a Quest Objective==\r\n*The Damned",},
			["Scepter of Beckoning"] = { content = "'''Scepter of Beckoning''' may refer to:\r\n* Scepter of Beckoning: Fire\r\n* Scepter of Beckoning: Stone\r\n* Scepter of Beckoning: Thunder\r\n* Scepter of Beckoning: Water",},
			["Scepter of Celebras"] = { content = "==Source==\r\nThis item is a quest reward from The Scepter of Celebras.\r\n==Use==\r\nYou can only use this item at the location of the first khan in the [[Maraudon]] pre-instance area.",},
			["Scepter of Shifting Sands"] = { content = "#REDIRECT [[The Scepter of the Shifting Sands]]", redirect = "The Scepter of the Shifting Sands",},
			["Scepter of the Council"] = { content = "==Objectives==\r\n'''Bring an Abyssal Scepter to [[Bor Wildmane]] in [[Cenarion Hold]].'''\r\n==Quest Text==\r\nHuum and I were just talking about you. He tells me you're just about ready to try your hand at fighting an Abyssal Lord!\r\nI must tell you this is a very dangerous endeavor. You'd better bring backup. And I don't mean one or two of your friends, I'm talking about a top-notch, battle-ready fighting force. If your friends are as good as you, you might even defeat it!\r\nIf you do - and I'll want evidence, as always - I'll give you a truly great reward.\r\n==Reward==\r\nChest of Spoils\r\n==Quest progression==\r\n# Goldleaf's Discovery\r\n# Lords of the Council\r\n# Bor Wishes to Speak\r\n# Scepter of the Council\r\n==Additional notes==\r\nRequires [[Revered]] with [[Cenarion Circle]]",},
			["Scepter of the Shifting Sands"] = { content = "#REDIRECT [[The Scepter of the Shifting Sands]]", redirect = "The Scepter of the Shifting Sands",},
			["Sceptre of Light"] = { content = "The [[Burning Blade]] in [[Thunder Axe Fortress]] to the east is rumored to have acquired the Sceptre of Light from the [[Naga]]. Legend tells that the sceptre is able to sink entire cities under the great seas.\r\n==Source==\r\nThis item drops from [[Burning Blade Seer]] in [[Desolace]].\r\n==Sceptre of Light as a quest objective==\r\nThis item is an objective of Sceptre of Light.",},
			["Schematic"] = { content = "#REDIRECT [[Engineering schematics]]", redirect = "Engineering schematics",},
			["Schematics"] = { content = "#REDIRECT [[Engineering schematics]]", redirect = "Engineering schematics",},
			["Schematic: Deepdive Helmet"] = { content = "==Source==\r\nThis item can be purchased for 36 silver copper from Jubie Gadgetspring in [[Azshara]].",},
			["Schematic: Field Repair Bot 110G"] = { content = "==Source==\r\nThis item drops from [[Gan'arg Analyzer]]s in the [[Blade's Edge Mountains]].",},
			["Schematic: Field Repair Bot 74A"] = { content = "The '''Schematic: Field Repair Bot 74A''' can be found in [[Blackrock Depths]]. \r\n==Objective of==\r\nContains for the quest .\r\n==Quests==\r\n*",},
			["Schematic: Gnomish Cloaking Device"] = { content = "Schematic used to make the [[Gnomish Cloaking Device]]. It requires a skill of 200 in engineering to learn, but not specialization in [[Gnomish Engineering]].\r\n==Source==\r\nThis item is sold by [[Zan Shivsproket]] in the [[Alterac Mountains]].\r\nIt has also been reported that [[Mekgineer Thermaplugg]] will drop this item about 0.2% (2 per 1000) of the time.",},
			["Schematic: Gnomish Universal Remote"] = { content = "==Source==\r\nThis item can be purchased for s=12 gold from:\r\n* Gearcutter Cogspinner in [[Ironforge]]\r\n* Jinky Twizzlefixxit at the [[Mirage Raceway]] in [[Thousand Needles]]\r\nThis item drops from [[Mekgineer Thermaplugg]] in [[Gnomeregan]].",},
			["Schematic: Goblin Jumper Cables XL"] = { content = "==Source==\r\nThis item drops from [[Plugger Spazzring]] in [[Blackrock Depths]].",},
			["Schematic: Hyper-Radiant Flame Reflector"] = { content = "==Source==\r\nThis item drops 5% of the time off of [[Solakar Flamewreath]] in [[Blackrock Spire]].\r\n==Notes==\r\nSolakar is the last mob in [[The Rookery]] area of [[Upper Blackrock Spire]].\r\nThis item only reflects fire spells that do actual damage, not ones that only debuff.\r\nAs of patch 1.8, this item no longer reflects [[Onyxia]]'s 'Deep Breath' attack.",},
			["Schematic: Lovingly Crafted Boomstick"] = { content = "Teaches how to create a Lovingly Crafted Boomstick.\r\n==Source==\r\nThis is a [[Limited sale recipe]] available for s=10 gold from\r\n*[[Fradd Swiftgear]] in [[Sundown Marsh]] in [[Wetlands]]\r\n*[[Jinky Twizzlefixxit]] in [[The Shimmering Flats]] in [[Thousand Needles]]",},
			["Schematic: Steam Tonk Controller"] = { content = "==Source==\r\nSince patch 2.3, it has been possible to buy this schematic from the following vendors:\r\n* [[Gearcutter Cogspinner]] in [[Ironforge]]\r\n* [[Sovik]] in [[Orgrimmar]]\r\nOriginally it was only available as a [[Darkmoon Faire Prize Ticket|40-ticket]] turn-in reward with the [[Darkmoon Faire]].",},
			["Scholar"] = { content = "A '''scholar''' is one who studies scholarship — the body of principles and practices used to make their claims about the world as valid and trustworthy as possible, and to make them known to the public.\r\n==In World of Warcraft==\r\nThere is only one [[NPC]] as of [[Burning Crusade]] with \"Scholar\" in their name or title: Scholar Runethorn in [[Feathermoon Stronghold]] off the coast of [[Feralas]].",},
			["Scholar Runethorn"] = { content = "'''Scholar Runethorn''' is a level 59 [[quest giver]] located at [[Feathermoon Stronghold]] in the [[contested]] territory of [[Feralas]].\r\nShe starts the quest Elven Legends (Dungeon).\r\nSee [[List of Feralas NPCs]].",},
			["Scholomance"] = { content = "The '''Scholomance''' (SKOH-loh-mance), a vile academy for prospective necromancers of the [[Scourge]], is located in the ruins of the palatial House of Barov, on a rise overlooking the abandoned city of [[Caer Darrow]]. The enemy level range is 57-62.\r\n==History==\r\nThe Scholomance was founded by the rogue wizard [[Kel'Thuzad]] nearly ten years ago. His [[Cult of the Damned]] renovated the ancient crypts beneath Caer Darrow (an old Arathorian fortress) and turned them into a school for necromancy. The Cult used this place to train its mortal agents and prepare to unleash the [[Plague of Undeath]] upon [[Lordaeron]]. It has been brewing with young talented wizards and adepts all this time. No one in Lordaeron knew. Originally, the Barov family owned the land and gave it to the Cult in exchange for the [[Lich King]]'s blessing of immortality. Now the Barovs remain as undead monsters. One of Kel'Thuzad's mightiest agents, the [[Ravenian]], also lives within the recesses of the school - ever ready to devour those students who show any sign of weakness. The [[lich]] [[Ras Frostwhisper]] rules over the site and guards it for the Scourge, but the mortal necromancer, [[Darkmaster Gandling]], serves as headmaster of the school, succeeding [[Araj the Summoner]] who was headmaster after Kel'Thuzad.\r\n''The Scholomance is housed within a series of crypts that lie beneath the ruined keep of [[Caer Darrow]]. Once owned by the noble [[Barov]] family, Caer Darrow fell into ruin following the [[Second War]]. As the wizard [[Kel'thuzad]] enlisted followers for his [[Cult of the Damned]], he would often promise immortality in exchange for serving the Lich King. The Barov family fell to Kel'thuzad's charismatic influence and donated the keep and its crypts to the [[Scourge]]. The cultists then killed the Barovs and turned the ancient crypts into a school for necromancy known as the Scholomance. Though Kel'thuzad no longer resides in the crypts, devoted cultists and instructors still remain. The powerful lich, [[Ras Frostwhisper]], rules over the site and guards it in the Scourge's name - while the mortal necromancer, Darkmaster Gandling, serves as the school's insidious headmaster.\r\n==Quests==\r\n*[[Aberrations of Bone]]\r\n*[[Plagued Hatchlings...For Now]]\r\n*[[Alexi's Gambit (quest)]]\r\n*[[Barov Family Fortune]]\r\n*[[Doctor Theolen Krastinov, the Butcher]]\r\n*[[Kirtonos the Herald (quest)]]\r\n*[[The Lich, Ras Frostwhisper]]\r\n*[[School's Out Forever (quest)]]\r\n==Denizens==\r\n* [[Bone golem]]s\r\n* [[Crypt fiend]]s\r\n* [[Gargoyle]]s (one, [[Kirtonos the Herald]])\r\n* [[Ghoul]]s\r\n*Gnomes\r\n* [[High elf|High elves]]\r\n*Humans\r\n* [[Lich]]es (one, [[Ras Frostwhisper]])\r\n* [[Plagued dragonflight|Plagued]] [[dragon whelp]]s\r\n* [[Rat]]s (critters)\r\n* [[Shade]]s\r\n* [[Skeletal mage]]s\r\n* [[Skeletal warrior]]s\r\n* [[Skeleton]]s\r\n* [[Sayaad]] (one, [[Blood Steward of Kirtonos]])\r\n* [[Wight]] (one, [[the Ravenian]])\r\n* [[Wraith]]s\r\n* [[Zombie]]s\r\n===Mobs===\r\nThe Students\r\n* [[Scholomance Acolyte]]s cast: [[Mind Flay]], Dark Mending (healing spell), [[Shadowform]], Cripple\r\n* [[Scholomance Adept]]s cast: [[Frostbolt]], [[Frost Shock]], [[Cone of Cold]]\r\n* [[Scholomance Dark Summoner]]s cast: Summon Skeletal Lackey (Summoning spell, 1.5 sec cast), [[Drain Life]], Curse of Blood (Increases physical damage taken)\r\n* [[Scholomance Handler]]s cast: [[Cone of Cold]], [[Blast Wave]], Arcane Blast (Arcane damage plus knockback)\r\n* [[Scholomance Necrolyte]]s cast: Shadow Barrier (reduces shadow damage taken by 50), [[Shadowbolt]]\r\n* [[Scholomance Necromancer]]s cast: Call to the Grave, Shadowbolt Volley (AoE Shadowbolt spell), Explode Corpse (Blows up a nearby corpse, dealing shadow damage to all enemies within a 5 yard radius)\r\n* [[Scholomance Neophyte]]s cast: [[Shadowbolt]], Dark Mending (healing spell), [[Shadow Word: Pain]], [[Mind Flay]], [[Fear]]\r\n* [[Scholomance Occultist]]s cast: [[Counterspell]], turns into a Dark Shade\r\n*Dark Shade: casts Shadowbolt Volley (AoE Shadowbolt), immune to physical damage\r\n* [[Scholomance Student]]s\r\n[[Plagued dragonflight]]\r\n* [[Plagued Hatchling]]s cast: Diseased Spit (Nature damage and reduces stamina for 30 sec. Stacks)\r\nMindless Undead\r\n* [[Risen Aberration]]s cast: Fixate, immune to magic (except holy)\r\n* [[Risen Construct]]s\r\n* [[Risen Bonewarder]]s cast: [[Drain Life]], Bone Armor (absorbs a set amount of damage), Consuming Shadows (Channeled AoE spell that slows and damages enemies around the caster)\r\n* [[Risen Guard]]s: cast [[Shield Slam]], [[Sunder Armor]]\r\n* [[Risen Guardian]]s\r\n* [[Risen Protector]]s cast: [[Shadow Word: Pain]], Shadow Shock (Instant cast Shadow damage spell), Silence (AoE silence)\r\n* [[Risen Warrior]]s cast [[Heroic Strike]], [[Rend]], [[Thunderclap]], Knockdown (knocks the target down for 3 sec)\r\n* [[Splintered Skeleton]]s\r\n* [[Reanimated Corpse]]s cast: Dark Plague (38 Nature damage every 5 sec for 2 mins. Stacks)\r\n* [[Unstable Corpse]]s\r\n* [[Diseased Ghoul]]s cast: Wandering Plague (Physical damage taken increased by 5, Stamina reduced by 3), Disease Cloud (Deals Nature damage to all enemies near the caster)\r\nUndead\r\n* [[Spectral Researcher]]s cast: [[Mana Burn]], Wail of Souls (AoE cone spell)\r\n* [[Spectral Teacher]]s cast: [[Banish]], [[Mana Burn]], Arcane Focus (Increases casting speec by 66%)\r\n* [[Spectral Tutor]]s cast: [[Mana Burn]], Silence (AoE silence), Spectral Projection (Turns invulnerable, summons 5 Speltral Projections to attack, 6 sec duration)\r\n* [[Necrofiend (Scholomance)|Necrofiends]] cast: Web Explosion (Immobolizes all targets for 5 sec)\r\n===Bosses and mini-bosses===\r\n*[[Blood Steward of Kirtonos]]\r\n*[[Kirtonos the Herald]] ''(requires [[Blood of Innocents]] to summon)''\r\n*[[Lord Blackwood]] ''(during of the [[Scourge Invasion]] in patch [[1.11]])''\r\n*[[Jandice Barov|Jandice Barov]]\r\n*[[Rattlegore|Rattlegore]]\r\n*[[Death Knight Darkreaver]] ''(requires [[Divination Scryer]] to summon)''\r\n*[[Marduk Blackpool]]\r\n*[[Vectus]]\r\n*[[Ras Frostwhisper]]\r\n*[[Kormok]] ''(requires [[Brazier of Beckoning]] or [[Brazier of Invocation]] to summon)''\r\n*[[Doctor Theolen Krastinov|Doctor Theolen Krastinov]]\r\n*[[Lorekeeper Polkelt]]\r\n*[[Instructor Malicia|Instructor Malicia]]\r\n*[[Lady Illucia Barov]]\r\n*[[Lord Alexei Barov]]\r\n*[[The Ravenian|The Ravenian]]\r\n*[[Darkmaster Gandling|Darkmaster Gandling]]\r\n==Achievements==\r\n*[[Scholomance (achievement)]]\r\n*[[Scholomance Guild Run]]\r\n==Scholomance Faculty==\r\n*[[Darkmaster Gandling|Darkmaster Gandling]] - School Headmaster, Course: Advanced Studies\r\n*[[Ras Frostwhisper]] - School Chairman, Alchemy\r\n*[[Doctor Theolen Krastinov|Doctor Theolen Krastinov]] - Torturer, Anatomy, Demonology\r\n*[[Lorekeeper Polkelt]] - Librarian, History\r\n*[[Instructor Malicia|Instructor Malicia]] - Occultism, Shadow Magic\r\n*[[Vectus]] - Arcane Magic, Plagued Dragonflight\r\n*[[The Ravenian|Ravenian]] - Janitor, Corporal Punishment\r\n*[[Jandice Barov|Jandice Barov]] - Zombification, Corpse Control, Plague Research, Course: Advanced Illusions\r\n*[[Rattlegore|Rattlegore]] - Course: Reanimation 101\r\n==Difficulty==\r\nAt release, Scholomance was an extremely challenging dungeon. Typically, the dungeon was raided in 10-man parties, with a difficulty similar to [[Upper Blackrock Spire]]. Subsequent patches in the summer of 2006 changed Scholomance drastically. Mobs were weakened slightly, and a great many were removed. However, Scholomance could no longer be run with more than 5 party members. At the time, this \"Scholo [[Nerf]]\" was a common topic for party chat among long-time players. Loot in Scholomance has changed gradually over time. Originally, each boss dropped some relatively weak loot. The dungeon waned in popularity as players saw little point in running it after they had completed their quests and acquired their [[Dungeon Set 1]] hat. Blizzard again patched the dungeon. At this point, Scholomance drops a moderate amount of fairly useful items, including a very small chance at the epic Headmaster's Charge and Alanna's Embrace. The rewards available from the [[Argent Dawn]] have also broadened through patches. Scholomance is a staple source of Argent Dawn reputation and [[Scourgestone]]s. Players seeking [[Argent Dawn]] tradeskill recipes, resistance enchantments or [[Argent Dawn|Armaments of the Dawn]] often spend a great deal of time in Scholomance or [[Stratholme]].\r\n==Notes==\r\n*According to Romanian legend, a real exists by an unnamed lake in the mountains south of the city of Hermannstadt (called Sibiu in Romanian) in Transylvania. This school of black magic is said to be run by the Devil, and would accept only ten students at a time. The tenth would remain to serve the Devil as payment for his teachings. The Scholomance in WoW is placed in the middle of the lake, much like its legendary namesake. In Bram Stoker's ''Dracula'', Count Dracula is said to have spent several years training under the Devil in the Scholomance. It is referenced in both Stoker's novel and an article titled \"Transylvanian Superstitions\" on page 136 of ''The Nineteenth Century'' by Emily Gerard.\r\n*It is difficult for a [[warrior]] to completely solo this instance without having any special items that inflict non-physical damage. To make Darkmaster Gandling appear, the six rooms around him must be fully cleared. However, the Scholomance Occultists turn into Dark Shades, which are immune to physical damage. Unless a warrior has special items (like [[Stratholme Holy Water]]), or Engineering explosives, they will have to be very careful to 1-shot the Occultists otherwise they will not be able to kill these mobs and summon Darkmaster Gandling.\r\n**If a Dark Shade ''does'' appear, there's a way to force it to reset. Go to the Ravenian's room (on the lower level), kill the Ravenian, and jump in the water behind one of the tombs. The shade will be unable to reach you, and will reset (turning back into an Occultist, at its starting location). You don't actually have to one-shot the occultist; if you kill it quickly enough, it won't turn into a shade.\r\n*Mages looking to solo Scholomance should beware of Risen Aberrations since they are immune to all magic except holy. They can be avoided with careful movement, or the mage can cast [[Invisibility]] to get out of combat in case he/she accidentally aggros one. Otherwise, it is a good idea to bring along a wand that can do holy damage, such as Nurturing Touch. For the same reason, warlocks should have a pet other their [[imp]] out, preferably their [[Voidwalker (warlock minion)|voidwalker]] or [[Felguard (warlock minion)|felguard]].\r\n*Trivia, according to early blue posts: Scholomance was originally thought of as an outdoor non-instanced area, much smaller, where [[Uther's Tomb]] is now. The designers made it so visually stunning that it was turned into an instance, so that it could be moved and enlarged.\r\n*In ''[[Lands of Conflict]]'', Scholomance is said to be below Andorhal, while the narrator was not able to explore Caer Darrow.\r\n*Non-Boss high elves in the instance still use the old model based off of Night elven models rather then the ones based on Blood elven models.\r\n*Near Ras Frostwhisper is one of two [[Alchemy Lab (object)|Alchemy Labs]] known to exist in Azeroth, the other is in [[Blackwing Lair]]. However, for ''[[The Burning Crusade]]'' players, there are Alchemy Labs in [[Shattrath City]] and [[Sun's Reach]].\r\n*Scholomance was probably the single most efficient pre-TBC instance for farming, with trash runs up to the Great Ossuary taking about 45 minutes for a fast player, and potentially yielding 100-200 gold, depending on which blue items drop. The instance had a very rich loot table for the level range, and individual mobs tended to drop good amounts of both coins and [[Runecloth]] as well, which would sell well on the Auction House. In addition, [[Scholomance Necromancer|necromancers]] and [[Scholomance Dark Summoner|dark summoners]] (as well as a few of the bosses) dropped the prized [[Dark Rune]]s, which were useful for raiders and could command prices of 15-20 gold each on the Auction House. It was not uncommon for 3-4 to drop during a single run, adding potentially another 80 gold to the instance's yield.",},
			["Scholomance Acolyte"] = { content = "==General Information==\r\n*Level: 57-59 (elite)\r\n*Found in: [[Scholomance]]\r\n*Type: [[Humanoid]]\r\nScholomance Acolytes are melee casters, their spells are not very powerful, but their melee deals 300-450 damage to casters, so its very important for a caster not to [[aggro]] them.\r\nThey cast the following spells:\r\n*, increases shadow damage by 20% and reduces physical damage taken by 20%\r\n*[[Mana Burn]], instant cast version\r\n*, lasts 15 secs \r\n*, works just like a normal heal.\r\n*Passive: [[Mind Flay]]\r\n===Strategy===\r\nThere isn't anything special about this fight, but their [[Mind Flay]] is very potent and always [[dispel]] Cripple if its on the [[tank]].",},
			["Scholomance Adept"] = { content = "'''Scholomance Adept''' can be found in [[Scholomance]] .\r\n==Drops == \r\n \r\n0.05% Chance of a [[rare]] drop.\r\n0.41% Chance of an [[Uncommon]] drop.\r\n0.03% Chance of a [[common]] drop.\r\n0.15% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.\r\n==Tactical Notes==\r\nThese mobs are ranged casters, utilising either [[Frostbolt]] or [[Shadow Bolt]] spells. They generally will not engage players in melee until they run out of mana. Their spells are not particularly lethal, but can cause problems if they are present in numbers.",},
			["Scholomance Handler"] = { content = "==Spells and abilities==\r\n*[[Cone of Cold]]\r\n*[[Blast Wave]]\r\n==Strategy==\r\nThey come with a pack of plagued dragon whelps, so a good idea is to have a Priest to Mind Control the Handler and use his/her AoE abilities against the dragons.\r\n==Drops == \r\n \r\n0.03% Chance of an [[epic]] drop.\r\n0.29% Chance of a [[rare]] drop.\r\n1.23% Chance of an [[Uncommon]] drop.\r\n0.08% Chance of a [[common]] drop.\r\n0.50% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scholomance Necrolyte"] = { content = "'''Scholomance Necrolyte''' can be found in [[Scholomance]] .\r\n==Drops == \r\n \r\n0.10% Chance of a [[rare]] drop.\r\n0.58% Chance of an [[Uncommon]] drop.\r\n0.05% Chance of a [[common]] drop.\r\n0.22% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.\r\n==Tactical Notes==\r\nUsually found in groups attending a [[Scholomance Dark Summoner]]. Attacks with [[Shadow Bolt]]. Generally low risk.",},
			["Scholomance Necromancer"] = { content = "'''Scholomance Necromancer''' can be found in [[Scholomance]] .\r\n==Drops == \r\n \r\n0.06% Chance of a [[rare]] drop.\r\n0.44% Chance of an [[Uncommon]] drop.\r\n0.04% Chance of a [[common]] drop.\r\n0.17% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.\r\n==Tactical Notes==\r\nGenerally found in groups with [[Spectral Researcher]]s and [[Scholomance Adept]]s. Although it can cast several spells, including [[Mana Burn]] and [[Shadow Bolt]], these mobs tend to favour moderately high damage melee combat, if they have a target within a suitable distance. This makes them a good target for CC with [[Freezing Trap]] if a Hunter is present in the group.\r\nThese should generally be crowd controlled, and the [[Scholomance Adept]]s present with them killed first, as the Adepts' spells do higher damage, and the Necromancers' melee tendencies make crowd controlling them easier.",},
			["Scholomance Neophyte"] = { content = "'''Scholomance Neophyte''' can be found in [[Scholomance]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.05% Chance of a [[rare]] drop.\r\n0.54% Chance of an [[Uncommon]] drop.\r\n0.04% Chance of a [[common]] drop.\r\n0.20% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scholomance Occultist"] = { content = "'''Scholomance Occultist''' can be found in [[Scholomance]] .\r\n==Drops == \r\n \r\n1.74% Chance of a [[rare]] drop.\r\n4.35% Chance of an [[Uncommon]] drop.\r\n3.48% Chance of a [[common]] drop.\r\n7.83% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scholomance Student"] = { content = "'''Scholomance Student''' can be found in [[the Viewing Room]] of [[Scholomance]].\r\n==Quotes==\r\n''\"Did you forget your student's attire? Do you think fashion is more vital than the Scourge's domination?\"\r\n''\"Did you finish yesterday's assignment? If so, then sit by me!\"\r\n''\"Be quiet! Can't you see the master is speaking?\"\r\n''\"We must focus if we are to spawn our dragonflight!\"\r\n''\"Spend less time rattling and more time listening.\"\r\n''\"Did you bring your textbooks? Can I look on with you?\"\r\n''\"Watch your step in here, <boy/girl>. The master sees all...\"\r\n''\"Be silent! I cannot afford to miss even a moment of this lecture!\"",},
			["School"] = { content = "==Biological==\r\n*[[Schools of Fish]]\r\n==Magic==\r\n*[[Magic schools (RPG)]] (non-canon information) & [[Magic schools]] (MMO game mechanics)\r\n==Academies and schools==\r\n*[[Academic Scholar's Society]] in [[Suramar City]]\r\n*[[Brock's School of Mining and Surveying]] in [[Thelsamar]]\r\n*[[Gremlock's School of Caterers]] in [[Kharanos]]\r\n*[[Lonika's School of Roguery]] in the [[Hall of Shadows]] \r\n*[[Moonbrook Schoolhouse|Moonbrook School]] in [[Westfall]]\r\n*[[Scholomance]] in [[Western Plaguelands]]\r\n*[[Siren's School for Spells]] in [[Suramar City]]\r\n*Unnamed school in [[Stormwind City]]\r\n*Unnamed magic school in [[Dalaran]] \r\n*Various [[Academy|academies]] and [[University|universities]]",},
			["Schools"] = { content = "#REDIRECT [[School]]", redirect = "School",},
			["Schools of Fish"] = { content = "#redirect [[School of Fish]]", redirect = "School of Fish",},
			["Schools of Magic"] = { content = "#REDIRECT [[Magic schools]]", redirect = "Magic schools",},
			["School of Fish"] = { content = "'''Schools of Fish''' are groups of individual fish that swim together. In WoW, these are cylindrical regions in the water with individual fish swimming in circles. There are schools of fish that are a fishable [[Fishing pool]]s and there are schools of fish that are ambiance [[critter]]s and are not fishable. \r\n==Fishing pools==\r\nSome Schools of Fish are [[Fishing pool]]s that contains (primarily) fish. They are location objects found in bodies of water in WoW that have a higher portion of more desirable items that can be fished. Some fish can only be obtained from fishing pools. Schools of Fish can be found in both Azeroth and Outland, so presumably will also be found in new areas in future releases. \r\nFishing pool Schools of Fish are shallow cylindrical regions within fishable water, just under the surface, sharing a common top surface. They designate small regions within fishable water that give better kinds of catches than the surrounding water. The graphical representation is more than just the surface definition significant to fishing. You can swim though a School of Fish and see individual fishes swimming around at different depths within the pool.\r\nMost Schools of Fish (including the ambiance schools below) use the same plain fish model. The [[Red Snapper]]s in a [[School of Red Snapper]] use a red skin on the fish model. \r\nSee [[Fishing pool]]s for fishing particulars and varieties. \r\n==Ambiance schools of fish==\r\nThere are also schools of fish [[critter]]s which are for ambiance only and have nothing to do with fishing. There are two flavors, one that can be targeted that has a yellow ([[neutral]]) label, 'School of Fish', and one that cannot be targeted and has no label. They can both be found swimming near each other in the same body of water; there does not appear to be a particular reason some are targetable and some are not. These swim deeper than the Fishing Schools of Fish and have no surface effect. \r\nEven though these are made up of individual fish graphic models, they act as a single object. If you kill the targetable school of fish, the each individual fish dies and rolls over on its back in unison. \r\n(There are also non-targetable free swimming individual critter fish.)\r\nFish critters of any sort seem to appear only in fishable waters. Absence does not mean the water is not fishable, but presence is a good indication that the water is fishable.",},
			["School of Necromancy"] = { content = "#REDIRECT [[Scholomance]]", redirect = "Scholomance",},
			["School of Red Snapper"] = { content = "'''Schools of Red Snapper''' can be found all along the Crystalbrook river, which divides the [[draenei]] starting area [[Ammen Vale]] from the rest of [[Azuremyst Isle]]. The red snappers are an important source of food for the nearby draenei camp [[Azure Watch]], and one of the draenei (named [[Diktynna]]) has been fishing here to provide for the camp. However, murlocs have recently started causing trouble in the area, and have injured [[Diktynna]] so that she can no longer do her job. Adventurous young [[draenei]] passing through the area of [[Ammen Ford]] may want to pay her a visit (see Red Snapper - Very Tasty!). \r\n[[Diktynna]] possesses a special Draenei Fishing Net which allows her to catch many Red Snapper from these schools.\r\n==Activation==\r\nTo gather Red Snapper, swim/walk up to [[School of Red Snapper|Schools of Red Snapper]] in the Crystalbrook river ([[Ammen Ford]]) on [[Azuremyst Isle]]. When you are close to the fish school, right click the Draenei Fishing Net provided with the quest to loot Red Snapper. If a [[murloc]] appears instead, kill it and loot Red Snapper from it.\r\n==Quests==\r\n'''School of Red Snapper''' is involved in the following quests:\r\n*Red Snapper - Very Tasty! from Diktynna\r\n:Use the Draenei Fishing Net to catch 10 Red Snapper. Return both the fish and the net to [[Diktynna]] on [[Azuremyst Isle]] when the task is complete.\r\n==Loot==\r\n[[School of Red Snapper]] contains the following items:\r\n* Red Snapper",},
			["Science"] = { content = "#redirect [[Technology]]", redirect = "Technology",},
			["Scilla Murkshadow"] = { content = "'''Scilla Murkshadow''' was a [[Naga Sea Witch]] who guarded [[Lady Darkscale]]. She was killed by [[Jaina]], [[Rokhan]], [[Chen Stormstout]] and [[Rexxar]] after they had received news from [[Jaina]] that she was not commanding the [[Human]]s to attack the [[Orc]]s. The [[Human]] forces were slaughtered by these [[Naga]] before the heros killed them. This occurred in the second map of Rexxar's Campaign in Warcraft III the Frozen Throne Expansion.\r\n==Statistics from Warcraft III==\r\n* 725 HP\r\n* 555 MP\r\n* 39-47 hero ranged damage\r\n* 4 hero armor\r\n* Attributes\r\n** 25 Strength\r\n** 19 Agility\r\n** 37 Intelligence '''Primary Attribute'''\r\n* Abilities\r\n** Frost Arrows (slows target and more damage)\r\n** Forked Lighting (multiple target damage)\r\n** Mana Shield (attacks take away mana '''not'' life)\r\n** Tornado (summons a tornado that incapacitates enemies)\r\n==Scilla Murkshadow in World of Warcraft==\r\nOne of the [[realm]]s in [[World of Warcraft]] is named after Scilla.\r\n*[[Server:Scilla US|Scilla US]]",},
			["Scintal Reef"] = { content = "This miles-long coral reef sweeps around the southwest perimeter of the [[Eye (Maelstrom)|Eye]] of the [[Maelstrom]]. [[Makrura]] activity here keeps the [[naga]] at bay — the makrura capital of [[Mak'aru]] is within.",},
			["Scooty"] = { content = "'''Scooty''' is a level 30 [[quest giver]] located in [[Booty Bay]] in the [[contested]] territory of [[Stranglethorn Vale]]. He maintains the teleporter, and claims to be a \"master engineer\".\r\nClearly an homage to Lt. Cmdr. Montgomery \"Scotty\" Scott, the chief engineer of the ''U.S.S. Enterprise'' from the Star Trek universe. Note the additional existence of [[Sprok]] - <Away Team> in [[Gnomeregan]].\r\nHe starts the quest Gnomer-gooooone! (Dungeon).\r\nSee [[List of Stranglethorn Vale NPCs]].",},
			["Scope"] = { content = "'''Scopes''' are [[augment]]s crafted by engineers. They can be applied to [[bow]]s, [[crossbow]]s and [[gun]]s to boost damage, critical strike rating or ranged hit rating. Scopes function like an [[Enchantment]] in that they are a permanent augmentation and that only one can be applied to the item at any given time.\r\nWhile the scope itself can only be created by someone skilled in [[Engineering]], the act of applying it to the ranged weapon can be done by anyone who meets the base level requirement of the item.\r\n* Items tagged with require [[The Burning Crusade]] to craft only. Items with level 60 or less requirements can still be used by non-BC players.",},
			["Scorch"] = { content = "'''Scorch''' is a [[mage]] spell that deals [[fire]] [[direct damage]]. Its short cast time offers proportional damage output when compared to other direct damage fire spells. Scorch’s damage is instant once the spell is cast. It is a blast effect rather than a missile or [[projectile]]. This makes it hard to trace back to the casting mage. Scorch has the best [[DPM|damage per mana]] ratio of all fire spells.\r\n==Talent improvements==\r\n[[Flame Throwing]] extends the range of Scorch to 36 yards at max rank.\r\nThe talent [[Improved Scorch]] adds a debuff to the spell target that increases all fire damage. This debuff stacks up to 5 times, increasing fire damage done by a maximum of 15% for 30 seconds. The 2 point talent [[Incineration]] increases the critical strike chance of scorch by 2% and 4%.\r\nScorch deals [[fire]] damage, and thus gains the benefit of the talents [[Impact]], [[Ignite]], [[Burning Soul]], [[Master of Elements]], [[Critical Mass]], [[Fire Power]], [[Pyromaniac]], and [[Elemental Precision (mage talent)|Elemental Precision]].\r\nAs with all mage spells [[Arcane Instability]], [[Spell Power]], [[Molten Fury]] and [[Playing with Fire]] will increase the effective damage output of this spell.\r\n==Tips and tactics==\r\nThis spell has excellent [[DPM]], and when combined with [[Arcane Concentration]] is a great way for the mage to do good single-target damage without needing to rest often. A mage can constantly cast Scorch (each immediately after the the last, since the cast time is the same as the [[Universal Cooldown]]) until he reaches the [[clearcasting]] state, which he can then \"cash in\" for a free heavy damage spell like [[Arcane Missiles]]. This is a group-only technique, however, as Scorch's [[DPS]] is too low for you to kill even-leveled mobs (especially while losing casting time to damage) without being killed yourself.\r\nThe [[Improved Scorch]] talent is a wonderful way to stack on the damage done to mobs when working in groups. A 3% fire vulnerability debuff that stacks up to 5 times gives a whopping 15% increased damage from fire spells, and combined with [[Fire Power]] and [[Molten Fury]] talents, can increase fire damage by 45% for the mage. The scorch debuff is also not just something that not only fire mages can enjoy, but Shamans and Warlocks as well.\r\nScorch is a much overlooked primary attack spell in raids. When used with appropriately high levels of critical strike rating as part of a scorch and fireblast rotation, in conjuction with the fire and arcane talents that boost critical strike damage and rate it produces perfectly viable raid DPS with excellent mana efficiency.\r\nFireball is preferrable is most situations however, as it has a higher coefficient to cast time ratio, receiving a larger benefit from one's spell damage gear.",},
			["Scorched Basilisk"] = { content = "'''Scorched Basilisks''' are level 27-28 [[basilisk]]s found in the [[Stonetalon Mountains]].",},
			["Scorched Ectoplasm"] = { content = "==Source==\r\nThis item drops from:\r\n* [[Tortured Druid]] in [[Silithus]]\r\n* [[Tortured Sentinel]] in [[Silithus]]\r\n==Scorched Ectoplasm as a quest objective==\r\nThis item is an objective of Hunting for Ectoplasm.",},
			["Scorched Grove"] = { content = "'''The Scorched Grove''' is an area of southwestern [[Eversong Woods]] that has been completely burned down by the [[blood elves]] to try to halt the [[Scourge]] forces and the spreading of the [[blight]] which is the tainting of the soil that precedes the [[Scourge]] because the [[runestone]] protecting this area was destroyed during an attack by the [[Scourge]] forces. It is now populated by several aggressive [[treant]]s who defiantly try to nurture life back into the burned soil.",},
			["Scorched Rocket Boots"] = { content = "==Source==\r\nWhen [[Goblin Rocket Boots]] explode, they place [[Scorched Rocket Boots]] in the user’s inventory, which can be looted for components. Contained inside will be: [[Black Mageweave Boots]] and [[Heavy Leather]] in addition to either [[Fused Wiring]] or [[Mithril Tube]]. Other than that, these items are [[Vendor Trash]].",},
			["Scorching Elemental"] = { content = "'''Scorching Elemental''' can be found in [[Un'Goro Crater]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.04% Chance of a [[rare]] drop.\r\n0.47% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scorchscale Drake"] = { content = "These drakes fly around [[Onyxia's Lair]] in southern [[Dustwallow Marsh]]. To attack then, have a hunter shoot and pull it down, or climb up the back of the lair and wait for one to fly by.",},
			["Scorpid"] = { content = "The Scorpid are gigantic creatures similar to [[scorpion]]s and [[arachnathid]]s. \r\nScorpids are quick, vicious, poisonous predators who stalk sand dunes in search of prey. Scorpids possess a strong racial identity; they band together to fight interlopers, form family units called nests, and willingly ally with other scorpids. Scorpids eat meat, including carrion, but prefer freshly killed food. They live underground, digging burrows in soft sand or earth. Scorpid females are indistinguishable from males to the naked eye, but after giving birth, a scorpid female carries her young on her back until they are old enough to fend for themselves (a period of 2-3 weeks). On average, a scorpid female gives birth to ten to twenty live young at a time, each one no bigger than a rat.\r\nScorpid young routinely molt, shedding their old, soft skin and growing a harder carapace in its place. Scorpids molt 5 to 6 times before reaching maturity. Cautious travelers watch for shed scorpid skins when traveling in the desert.\r\nScorpids grow to about 3-1/2 feet in length and 2-1/2 feet tall. They are heavy for their size, weighing 60 pounds when fully grown. Scorpids come in many colors, including black, yellowish brown, red, and a mottled white that blends with moonlit desert dunes. A strange quality of the scorpid's carapace causes it to fluoresce weakly in certain underground environments, such as an area with phosphorescent plants, moss, or fungi.\r\nScorpids live an average of thirty years. Solitary scorpids retreat and seek out assistance if they know a fellow scorpid is close enough to render aid; scorpids always try to attack in groups if they can. As many scorpids as possible target an individual in combat before moving on to a new enemy. Scorpids can opt not to poison an enemy when making a sting attack, but they rarely choose to do so. Sometimes, though, scorpid groups reserve their poison and make nonlethal attacks to subdue weak enemies. They then drag the unconscious foe back to the nest to teach their young to kill.''\r\nThey attack anything they perceive as a threat with their claws and venomous sting. Hunting and killing scorpid is considered a rite of passage by the Orcs. Scorpids are found in [[Durotar]], [[The Barrens]], the [[Burning Steppes]], [[Thousand Needles]], [[Uldaman]], [[Desolace]], the [[Blasted Lands]], [[Blackrock Depths]], [[Silithus]], [[Tanaris]], [[Shadowmoon Valley]], and [[Terokkar Forest]].\r\nDuring the [[First War]], Conjurers were adept at summoning [[scorpion|monstrous scorpion]]s.\r\n==As a [[Hunter]]'s [[Pet]]==\r\n* Their poison can break crowd control if not carefully managed.",},
			["Scorpid Poison"] = { content = "'''Scorpid Poison''' infects a single target with [[poison]] doing X [[Nature]] damage over 10 seconds. This effect can stack up to 5 times, increasing the damage done and refreshing the duration of the poison.\r\n==Details==\r\n*Beast Families: [[Scorpid]]\r\n*Focus Cost: 30\r\n*Duration: 10 second [[poison]]\r\n*Cooldown: 4 seconds\r\n*Range: 5 yards\r\n==Notes==\r\n*Adds a small amount of threat.\r\n* Scorpid poison is affected by the pets [[spell damage]] (increased by the hunter's [[Attack power|Ranged Attack Power]]) which increases damage dealt. As part of the patch 2.2.0 the damage dealt with this ability has been reduced to 1/3 of what it used to deal.\r\n* Any damage increasing effects active when the first scorpid poison afflicts the target will continue to affect each tick of the poison for as long as it stacks making very high damage over time possible.\r\n*Poison-[[Dispel (mechanic)|dispelling]] abilities remove only one application of Scorpid Poison, not the entire stack.",},
			["Scorpid Scale"] = { content = "Used in several [[Leatherworking]] patterns.\r\n==Source==\r\n'''Scorpid Scale''' can be found by [[skinning]] any number of high-level [[scorpid]]s throughout the land\r\n===[[Leatherworking]]===\r\n*[[Tough Scorpid Boots]]\r\n*[[Tough Scorpid Bracers]]\r\n*[[Tough Scorpid Breastplate]]\r\n*[[Tough Scorpid Gloves]]\r\n*[[Tough Scorpid Helm]]\r\n*[[Tough Scorpid Leggings]]\r\n*[[Tough Scorpid Shoulders]]",},
			["Scorpid Sting (hunter ability)"] = { content = "==Overview==\r\n''Taken from the stingers of the deadly insectoid beasts of the desert, Hunters fashion poisons that slow the mind and numb the body.''\r\n'''Scorpid Sting''' is a ranged ability that reduces the target's chance to hit with melee and ranged attacks by 5%.\r\n===Use===\r\n*Cast Time: Instant\r\n*Tree, School: Marksmanship, [[Schools_of_Magic|Nature]]\r\n*Type: Single Target Debuff\r\n*Range: 5-35 yards\r\n*Cooldown: N/A\r\n*Duration: 20 seconds.\r\n*Classification: [[Dispel_Type|Poison]]\r\n===Notes===\r\n*Prior to Patch 2.0, Scorpid Sting was a debuff that reduced the strength and agility of the target, with multiple ranks. It has now been changed to a -5% hit debuff. There is only one rank.\r\n===Talents===\r\n*[[Improved Stings]]\r\n*[[Efficiency (Hunter Talent)|Efficiency]]\r\n*[[Hawk Eye]]\r\n==Tips and tactics==\r\n*The old version of Scorpid Sting was of dubious utility, and was rarely used. The new version may deserve a second look. When used against fast hard-hitting melee mobs, it can make a significant difference to damage taken by a tank. When a mob is dealing several thousand damage per hit, an increased miss rate greatly matters.\r\n*Scorpid Sting does not apply to spell hit, and is useless against casters. However, using Scorpid Sting against Warriors and Rogues should be considered.\r\n*Scorpid Sting does not stack. If there are multiple hunters in the group or raid, designate one to use Scorpid Sting when appropriate.\r\n*Scorpid Sting doesn't cause damage, and so won't break various crowd control effects (like [[Freezing Trap]] or [[Polymorph]]) unlike [[Serpent Sting]]. Since only one sting can be active at a time, this can be useful for removing Serpent Sting.",},
			["Scorpion"] = { content = "'''Scorpions''' are a type of arthropod similar or related to [[scorpid]]s or [[arachnathid]]s, and native to both Azeroth and Draenor. They are summonable monsters which can be called upon through [[conjuror]]s and summoning arts. \r\nConjurers of the First War were capable of using the spell [[Summon Scorpion]]s to help fight against the Horde.\r\n===Human Description===\r\n''Creatures of the arid lands, these giant arachnids strike with venomed stingers that are located in their tails to kill their prey. The poison they employ is extremely painful, and is a slow and wicked death. They are hunters by nature that will attack anything that strays near their nests.''\r\n===Orc Description===\r\n''Hunters of the underground, these are as venomous and deadly as any creation of the Warlocks. Their tails are tipped by a sharp spike, and can tear through the armor and flesh of their prey to inject a deadly and painful poison into the unfortunate. The Humans have learned to command the smallest of these fiends, and can summon them to do their bidding.''\r\n==Species==\r\n*Monstrous Scorpion\r\n*:Monstrous scorpions are likely to attack any creature that approaches, and they usually charge when attacking prey. A monstrous scorpion has a poisonous sting, with details that vary by the scorpion’s size.",},
			["Scorpok Pincer"] = { content = "==Source==\r\nThis item drops from:\r\n* [[Clack the Reaver]] in [[Blasted Lands]]\r\n* [[Scorpok Stinger]] in [[Blasted Lands]]\r\n==Scorpok Pincer as a quest objective==\r\nThis item is an objective for the following quests:\r\n* Snickerfang Jowls\r\n* Rage of Ages\r\n* A Boar's Vitality\r\n* Spirit of the Boar\r\n* The Decisive Striker\r\n* Salt of the Scorpok",},
			["Scourge"] = { content = "The '''Scourge''' (sometimes called the '''Undead Scourge''' or '''Scourge Army''') is one of three major [[undead]] factions existing in the world of [[Azeroth]] (the other two being the [[Forsaken]] and the [[Knights of the Ebon Blade]]). Until recently, it was a major player for control of the world. Created initially as the precursor to an invasion by the [[Burning Legion]], the Scourge broke free from their demonic masters and — under the iron rule of the dread [[Lich King]] — have built up their power base on the arctic continent of [[Northrend]]. Their influence spreads throughout Northrend, as well as the [[Plaguelands]] in northern [[Lordaeron]] and southern [[Quel'Thalas]], and even [[Kalimdor]] to a small degree. Consisting of thousands of walking corpses, disembodied spirits, beasts of the north, and damned mortal men, the Scourge is a terrifying and insidious enemy which, before its downfall, was perhaps the most dangerous threat to the world of Azeroth.\r\nA [[Scourgestone]] is an item given to all Scourge upon birth or creation. It provides certain benefits to the holder, but more importantly it provides Scourge leaders insight into the location and movement of their units. Please note that by \"birth\", [[The Ebon Watcher]] is referring to necromancers and other dark magic wielders who are born into the ranks of the Scourge alive and gradually become undead, never actually dying themselves. It's important to clarify however that beings that transition in this way are also physically dead, their bodies bearing the mark of decay.\r\n===Creation===\r\nThe [[Burning Legion]] had experimented with the undead for at least ten thousand years, with the first hint of the Scourge's creation being an experiment by the [[nathrezim]] to raise undead [[Night elf|night elves]] in the ruins of [[Suramar]] during the [[War of the Ancients]].\r\nThe Scourge was (and still is) a vast army of the undead serving the Lich King — the being formerly known as the [[orc]] [[shaman]] [[Ner'zhul]]. Under the control of the Burning Legion, the Scourge's mission was to spread terror and destruction across the world in anticipation of the Legion's inevitable invasion. A mission that was almost undone before it even began when the [[nerubian]]s attacked and began the [[War of the Spider]], however, the conflict ultimately ended with the Lich King's first major triumph (while the nerubians were immune to the plague, their corpses could still be reanimated). The Lich King was impressed by his enemy, however, and adopted nerubian architecture for his own, as a testament to the spider lords' tenacity and age.\r\nThe Lich King, now uncontested in the ice realm of [[Northrend]] where he ruled from the [[Frozen Throne]], unleashed the terrible [[Plague of Undeath]] southward into [[human]] lands. As the plague encroached on the southlands, countless humans fell prey to Ner'zhul's mental control and life-draining sickness every day. With the help of [[Kel'Thuzad]] and the [[Cult of the Damned]] the plague was spread. Many of Lordaeron's northern villages were contaminated almost immediately. Just as in Northrend, the citizens who contracted the plague died and arose as the Lich King's willing slaves. The cultists under Kel'Thuzad were eager to die and be raised again in their dark lord's service. They exulted in the prospect of immortality through undeath. As the plague spread, more and more feral zombies arose in the northlands. Kel'Thuzad looked upon the Lich King's growing army and named it the Scourge, for soon it would march upon the gates of Lordaeron and scour humanity from the face of the world.\r\n===Reign of Chaos===\r\nThough Ner'zhul and his undead Scourge were bound to the will of the Burning Legion, the Lich King constantly strove to free himself and gain vengeance upon the demons for dismembering his body and damning him so completely. To this end, he sought a champion to carry out his will and decided that [[Arthas Menethil|Prince Arthas Menethil]] would be the perfect choice. During the [[Scourging of Lordaeron]], Arthas became increasingly enraged at the devastation the undead caused and sought to end their threat by any means necessary, including [[Culling of Stratholme|culling a city]]. This would lead the young prince to Northrend, the roof of the world. There, the Scourge engaged in combat with the [[1st Legion]] and [[Dwarven Expedition]], which would eventually team up and proceed to [[Mal'Ganis]]' citadel. Fearing of being overwhelmed, Arthas would obtain the [[runeblade]] [[Frostmourne]] and kill the nathrezim, who he had thought was in command of the Scourge. It was there that the whispers of the Lich King guided Arthas into becoming Ner'zhul's champion and the greatest of his [[death knight]]s. Arthas returned to his soldiers and killed them, raising them as Scourge.\r\nIn the days since Prince Arthas took the fleet to Northrend, the Silver Hand was fighting the spread of the plague. However, the undead soon mysteriously pulled back from the [[Plaguelands|Eastweald]] and vanished from sight. The citizenry didn't know the cause, but suspected that their prince succeeded in his quest to destroy the Scourge in Northrend. The truth was that the Lich King ordered the Scourge to retreat in order to prepare for Arthas' homecoming. Arthas, now the champion of the Scourge, returned home, and brought a mighty Scourge army with him, consisting of death knights, [[necromancer]]s, [[abomination]]s, [[crypt fiend]]s, [[gargoyle]]s, and [[frost wyrm]]s. The prince ordered the army to remain hidden for the time being, and only a handful of death knights accompanied him to [[Capital City]] where he killed [[Terenas Menethil II|his own father]] and destroyed the capital, along with hundreds of citizens. At the same time, the Scourge emerged from hiding across Lordaeron and attacked the living. When the Scourge attacked Tirisfal, the [[Agamand]] family fortified their [[Agamand Mills|mills]]. However, [[Devlin Agamand|Devlin]] betrayed his people and made a deal with the Scourge. The [[ranger]] [[Nathanos Marris]] held his ground on [[Marris Stead]] in defense of Lordaeron. The farm and all on it were waylaid by a gigantic wave of Scourge, with Nathanos perishing to [[Ramstein]] and subsequently being rased as a Scourge himself.\r\nWhen [[Alexandros Mograine]] returned from [[Ironforge]] with the mighty [[Ashbringer]] in hands, the Highlord was reported to be paring down the Scourge's numbers. Neighboring human and dwarven nations converged on Lordaeron to vanquish the Scourge. However, the Scourge was numerous and defeated any Alliance resistance. Ultimately, the Scourge took Lordaeron, ravaging many towns and farms across Eastweald, including [[Darrowshire]] in the [[Battle of Darrowshire]]. The undead also continued to spread the [[Plague of Undeath]], corrupting the land. The Scourge attempted to invade [[Gilneas]], however, King [[Genn Greymane]] turned to [[Archmage Arugal]] who summoned feral [[worgen]] from the [[Emerald Dream]] to repel the undead attacking [[Greymane Wall]].\r\n[[Tichondrius]] sent Arthas on a mission, rallying the Cult of the Damned to his banner and invading [[Andorhal]] where Arthas ended the life of [[Uther the Lightbringer]]. The death knight and his army continued to [[Scourge invasion of Quel'Thalas|invade]] the ancient [[High elf|elven]] [[kingdom]] of [[Quel'Thalas (kingdom)|Quel'Thalas]], defiling the [[Sunwell]] and using it to resurrect the [[necromancer]] [[Kel'Thuzad]] into a [[lich]]. With Kel'Thuzad once more among them, the Scourge moved forward to [[Siege of Dalaran|destroy]] the magi-city of [[Dalaran]] and claim the [[Book of Medivh]], the result of which was the summoning of the [[demon lord]] [[Archimonde]] into the world, as well as Dalaran's destruction. It was at this point that Archimonde ordered that the Scourge be commanded by the [[Nathrezim|dreadlords]]; however, Ner'zhul was planning a different move.\r\nShortly before the [[Battle of Mount Hyjal]], Ner'zhul engineered the downfall of the Legion by having his lieutenant, Arthas Menethil, alert the demon hunter [[Illidan Stormrage]] to the presence of the Legion in [[Felwood]]. Illidan's attack on the demons there brought about the death of [[Tichondrius]] and the destruction of the [[Skull of Gul'dan]], which greatly weakened the Legion and made it possible for the Alliance, Horde, and night elf forces to stop Archimonde during the Battle of Mount Hyjal. It was at this point that Ner'zhul was finally capable of making his bid for freedom, effectively cutting all ties to the remaining demons as well as the remaining demon lord, Kil'jaeden. Such a move inspired Kil'jaeden to incredible heights of anger, and it was now the demon's turn to lust after vengeance. But, thanks to the Legion's defeat, Kil'jaeden was stripped of his capacity to simply bring about swift destruction, and was forced to use more subtle methods to dispose of his rebellious creation.\r\nIn Felwood, the Scourge decimated the area with attacks of [[infernal]]s and other demonic magics, with the slimes supposedly creeping up through the earth during the attacks.\r\n===The Frozen Throne===\r\nShortly after the Battle of Mount Hyjal, Kil'jaeden contacted [[Illidan Stormrage]] with an offer too tempting for the demon hunter to refuse: Slay the Lich King and be granted the awesome power of a demon lord. Gathering his once-[[Highborne]] allies, the [[naga]], Illidan traveled to the [[Tomb of Sargeras]] and began weaving a massive spell targeting the [[Frozen Throne]] using the [[Eye of Sargeras]]. However, the spell was interrupted at the eleventh hour by Illidan's brother [[Malfurion Stormrage]], [[Maiev Shadowsong]], and Prince [[Kael'thas Sunstrider]]. Though the spell was not completed, enough potent [[fel]] energy had been siphoned to cause a fracture in the Lich King's icy prison. This caused Ner'zhul's powers to weaken, especially his control of his undead. It was during this time that a large band of undead, led by [[Sylvanas Windrunner]], regained their free will and left the Scourge. After [[Plaguelands civil war|warring]] over the control of the Plaguelands and defeating the remaining nathrezim, she named her followers as the [[Forsaken]]. Desperate, Ner'zhul contacted Arthas, the greatest of his [[death knight]]s, by telepathy and commanded him to return to [[Icecrown Citadel]] at once.\r\nHowever, this matter was complicated by Kil'jaeden once again. Growing impatient with Illidan's failures, the demon lord instructed him, with his allies the Naga and newly named [[Blood elf|blood elves]], to travel to Northrend and put an end to the Lich King personally. Arthas's undead forces battled Illidan's army at the base of the glacier, the aftermath of which left Illidan wounded and his troops broken. Arthas, victorious, proceeded into the Lich King's throne chamber where he used the runeblade [[Frostmourne]] to shatter the Frozen Throne and free the essence of Ner'zhul. The spirit of the [[orc]]ish [[shaman]] then bonded with Arthas and they became one of the most powerful beings the world had ever known.\r\n===Interim===\r\nThe survivors of the [[Knights of the Silver Hand]] in northern [[Lordaeron]] continued to strike at Scourge, including [[Stratholme]]. Due to the machinations of [[Balnazzar]] and [[Kel'Thuzad]], the Silver Hand splintered after the death of [[Alexandros Mograine]] who had been lured to Stratholme's gates where he fought against waves of the undead, but ultimately was betrayed by his son, [[Renault Mograine]]. This heralded the birth of the [[Scarlet Crusade]] and [[Argent Dawn]], which later led to further battles, including an attack on [[Hearthglen]] where [[High General Abbendis]] died, attack on [[Naxxramas]] led by [[Darion Mograine]] to free his father Alexandros, and an attack on [[Light's Hope Chapel]] where Darion sacrificed himself. The Scourge would manage to recover several bodies of the fallen Argent Dawn members, including Darion and his weapon, the Ashbringer. Naxxramas served as the war factory for the Scourge.\r\n[[Lord Raymond George]] and his Argent Dawn fought against the Scourge. Their necromancers raised the Dawn's fallen soldiers and created twisted golems to slay more soldiers.\r\nTwo years after the end of the [[Third War]], the Scourge were edging closer to [[Hillsbrad Foothills]] according to [[Kalecgos]]. [[Anveena Teague]]'s farm and the [[human]]-controlled [[Tarren Mill]] were attacked by the Scourge led by the traitor [[high elf]] [[Dar'Khan Drathir]] who was looking for the essence of the [[Sunwell]]. They were eventually defeated by Kalec, [[Tyrygosa]], Anveena, [[Jorad Mace]], and [[Harkyn Grymstone]]. At some point in the past, the Scourge had invaded [[Barony Mordis]] in the [[Alterac Mountains]], killing Baron [[Valimar Mordis]], and continued to operate there until Kalec, Anveena, and his group arrived there. They were led by the [[ghoul]] [[Ichor]] who had the [[Orb of Ner'zhul]] that they used to raise undead beasts. The baron had the orb stolen, and he wanted to use it to create his own army from remains dug out by a group of dwarves. When their frost wyrm attacked, Ichor captured Jorad and Tyrigosa. Soon, however, the prisoners and Kalec's group fought against the undead, while [[Trag Highmountain]] struggled with his former comrade, destroying the orb and causing the deaths of Ichor and Mordis. Dar'Khan managed to capture Anveena and brought her to Quel'Thalas. The [[Farstriders]] continued to fight against the undead and noted that the Scourge numbers were increasing in the area. As they learned, Dar'Khan's return was the cause. In the meantime, the orb of Ner'zhul had reanimated Trag, who sought revenge against the Lich King. When the two clashed, the Lich King revealed that he wanted to make Trag his champion and a Scourge commander.\r\nAt some point, the Scourge led by [[Kirkessen the Zealous]] tried to invade Light's Hope Chapel once again in the [[Siege of the Sanguine]], but failed. [[Diodor the Damned]] led a [[Summertide Assaults|series of attacks]] against the [[Scarlet Monastery]], two of which were successful while the final third one marked the Scourge's defeat.\r\nAround year 24 on [[Hallow's End]], the Scarlet Crusade attacked the Scourge. The battle was joined by the mad [[Sir Thomas]] who killed not only the Scourge force, but also his fellow crusaders.\r\nAt some point, the [[paladin]] [[Lord Thorval]] scouted an area for Scourge presence. While he was away from his village, the Scarlet Crusade burned the villagers, Thorval's family among them. He and his scouting party discovered this but were ordered to continue to the nearest remaining waypost. Not long after nightfall, they heard the ominous cackling of the undead echoing from the trees, and a wave of Scourge overtook them. Thorval was killing them, but for each of the fallen, two more crawled forth from the hills. They were caught in the same tide of Scourge they had been hunting, only now they were broken and unprepared. Thorval's allies were succumbing to wounds and exhaustion. Thinking of his deceased family filled Thorval with hatred. Suddenly, he came to a realization that death was the only real end to any mortal tale, wielding power to protect led inalterably to failure, and that success met only those who used it for a different end. As such, Thorval swore allegiance to the Lich King. The lord of the Scourge purged him of his hateful human sensations that had tormented him, and he was reborn as a death knight.\r\nTwo years after his previous defeat, Dar'Khan re-emerged in Quel'Thalas with a band of undead and lured [[Lady Liadrin]] into a trap, seeking her new [[Blood Knights]] killed and reanimated into powerful Scourge warriors. The ploy failed, and Dar'Khan and his minions were defeated once more.\r\n===World of Warcraft===\r\nThe Scourge was primarily concentrated in the [[Plaguelands]] with a large concentration in [[Andorhal]] and [[Scholomance]]. Their primary fortification and \"capital\" in [[Lordaeron]] was the ruined city of [[Stratholme]], under the rule of [[Baron Rivendare]]. The Scourge controlled the majority of the city, but the humans of the [[Scarlet Crusade]] held a small section. The Scourge has also been seen in [[Tirisfal Glades]] and [[Silverpine Forest]] holding [[Fenris Isle]].\r\nThe Scourge is also reported to have a presence as far away as the [[Barrens]] in [[Kalimdor]]; The lich [[Amnennar the Coldbringer]] and his forces participated in the Scourge's assault on Mount Hyjal during the Third War. Afterward, the Lich King instructed his servant to remain in Kalimdor and expand the Scourge's influence, and so Amnennar began plans to create a base from which to strike at [[Orgrimmar]] and [[Theramore Isle|Theramore]]. To that end, Amnennar has set his sights on recruiting the recently displaced and desperate [[quilboar]] of [[Razorfen Downs]], promising them power over death so they can repel invaders in their lands.\r\nThe necromancer-lich Kel'Thuzad, the majordomo of the Lich King, once controlled the Scourge in Lordaeron from his citadel of [[Naxxramas]], floating over Stratholme and [[Plaguewood]] in the [[Eastern Plaguelands]].\r\nThe Lich King and Kel'Thuzad later sent [[necropolis]]es to [[Scourge Invasion|invade]] various areas across Eastern Kingdoms and Kalimdor, including Azshara, the Blasted Lands, the Burning Steppes, the Tanaris Desert, the Eastern Plaguelands, Winterspring, and capital cities. The Scourge were establishing small staging points in the places under attack, receiving communications and other assistance from the necropolises that flew overhead.\r\nAfter defending the lands, heroes of the Alliance and Horde stormed Naxxrammas, forcing Kel'Thuzad to retreat along with his floating fortress to [[Northrend]].\r\n====The Burning Crusade====\r\nThe Scourge appeared many times in the blood elven lands of [[Quel'Thalas]], mostly on the tainted land known as the [[Dead Scar]]. The high elf traitor [[Dar'Khan Drathir]], slain during the Third War, ruled the Scourge in Quel'Thalas from the fortress of [[Deatholme]] until he was eventually slain by blood elf and Forsaken forces. A few members of the Scourge were seen fighting the [[Burning Legion]] on [[Isle of Quel'Danas|Quel'Danas]].\r\nFor years, Andorhal remained in the hands of the Scourge. At some point, [[Maddox]] and his group tried to [[Retaking of Andorhal|retake]] it with the help of the Argent Dawn, but the effort failed, and the Scourge overwhelmed the soldiers.\r\nJust prior to the [[war against the Lich King]], a large Scourge army was amassing somewhere in Lordaeron, and [[Korialstrasz]] suspected that they were headed for Dalaran, so the red dragon decimated them.\r\n====We Ride Forth====\r\nBelieving that [[Sylvanas Windrunner]] would come for the [[Helm of Domination]], the Lich King Bolvar employed a daring gambit. He deceived the [[Four Horsemen]] into thinking that he had fallen under the dark powers of the [[Lich King]] by bringing and hiding the forces of the Scourge around Icecrown Citadel, so that when Sylvanas inevitably confronted him, the horsemen would arrive soon after and finish off the winner, before choosing who would be the new Lich King.\r\n====Shadowlands====\r\nAfter the defeat of the [[Lich King]] and the destruction of the [[Helm of Domination]] at [[Sylvanas Windrunner]]'s hands, as foreshadowed by King Terenas years earlier, the now-masterless Scourge marauded all across Azeroth, emboldened by the message of [[the Jailer]] brought by the [[Mawsworn]] [[kyrian]] [[Herald Dalora]]. Off the heels of yet another brutal war, the forces of Azeroth mounted a counterattack and assaulted the source at Icecrown Citadel. During this conflict, [[Darion Mograine]] and [[Thoras Trollbane]] were forced to regain control of [[Acherus: The Ebon Hold]], while the [[Knights of the Ebon Blade]] and the [[Argent Crusade]] stepped in to lead the offensive against the Scourge.\r\nDuring the course of the [[war against the Jailer]] in the [[Shadowlands]], the Scourge also invaded [[Lakeshire]] in the [[Redridge Mountains]].\r\nThough the Jailer was slain by the war's end, the Scourge remained a threat as the mightiest of the Scourge vied for supremacy, like vicious warlords in the wake of their king's death. One such warlord was the [[San'layn]] [[Vorath]], who commanded his Scourge forces from within [[Deatholme]] against the [[Sin'dorei]] of [[Quel'Thalas]].\r\n==Organization==\r\nPrior to Arthas' defeat, he was at the top of the organization as the Lich King, who sent orders from his [[Icecrown Citadel|ice fortress]] in Northrend. His direct underlings were liches, undead mages, and necromancers with incredible power to spread plague and command undead armies. It is unknown how many liches there were, but Arthas's right-hand lich was Kel'Thuzad, who reigned in Lordaeron and had his hands full fighting the [[Scarlet Crusade]] and the [[Forsaken]], the undead who broke free from the control of the Lich King. Kel'Thuzad contained the fight against the Horde and Alliance in Northrend when Naxxramas moved to the Dragonblight prior to his final defeat (or his ''presumed'' defeat, as his [[phylactery]] was nowhere to be seen after his death). The banshees under his command often led scouting troops to discover new areas to infiltrate, while other important Scourge members included necromancers, responsible for raising and commanding the dead, and the [[Cult of the Damned]], a bizarre group of mortals so fascinated by the undead that they follow them, worship them, even emulate them, hoping to one day be damned as the undead are. They don’t see the foulness and evil, but rather power and eternal life.\r\nMost of the undead reported to a region's leadership of necromancers or liches, who in turn reported to Kel'Thuzad. He reported pertinent information to Arthas. The rogue undead, the Forsaken, were wild cards: the Lich King lost much of his power over the undead before merging with [[Arthas Menethil]]. This allowed one of the more powerful banshees, Sylvanas Windrunner, to escape his hold. She freed many more undead creatures, and currently leads the Forsaken from her [[Undercity|tunnel complex underneath the former capital city of Lordaeron]]. While they are not part of the Scourge and do not fall into the Scourge organization, they work along roughly the same lines — kill or otherwise eliminate those that oppose them and dominate the undead. He had many plans for Azeroth, so he couldn't focus entirely on Sylvanas and devote much of his time to 'reclaiming' the Forsaken. A thing to note about the Scourge was that the further from a lich or a necromancer the weaker undead got, the more disoriented they were. They lost the command of the Lich King, but they didn't necessarily become free. Once the will of the necromancer or other controlling force left them, they had no memory of their former selves, and they shuffled around as mindless husks, searching for someone to lead them. \r\nArthas led the Scourge in Northrend from the Frozen Throne, completely dominating Icecrown. The Scourge's secondary base was the continent of Lordaeron, in the city of Stratholme, Arthas's first conquest. Now it lies in burning ruin. There are few remaining mortals there, except for those of the Cult of the Damned and the Scarlet Crusade. Lordaeron's northern and eastern areas are practically abysmal with the Scourge. Their foul stench permeates the air. Yet the Scourge has reached all areas of the world, dripping down through Khaz Modan and into Azeroth, and even west to [[Razorfen Downs]] Kalimdor. Arthas wanted his finger on everything happening in the world, and he had the forces to do it.\r\nWith Arthas' defeat and Fordragon's ascendancy as the new Lich King, the Cult of the Damned chose to become independent of the Bolvar-controlled Scourge, while during the [[third invasion of the Burning Legion]], the Knights of the Ebon Blade come to an agreement with the new Lich King by acting voluntarily as his agents if the Scourge remains contained in Northrend. It is still unknown what the new Scourge command structure was during Bolvar's reign.\r\nFollowing the destruction of the [[Helm of Domination]] at the hands of [[Sylvanas Windrunner]] after the [[Fourth War]], the Scourge marauded masterless all across Azeroth, emboldened by the [[Cult of the Damned]] and the [[Zovaal|Jailer]]'s [[Mawsworn]]. Though Zovaal the Jailer would be ultimately slain, the mightiest Scourge would seize control and vie for supremacy, like vicious warlords in the wake of their king's death.\r\n==Notable former servants==\r\n* [[Sylvanas Windrunner]] - Once the [[Ranger-General of Silvermoon]], before being slain and raised by [[Arthas Menethil|Prince Arthas]] personally into the first of the high elven banshees. She served as one of Arthas' primary generals, until she and a number of banshees broke free from the Lich King's control, creating the foundations of what would become the [[Forsaken]].\r\n* [[Alexandros Mograine]] - Once a renowned [[paladin]], known as the [[Ashbringer]]. He was murdered by his son, [[Renault Mograine|Renault]], and was raised by Kel'Thuzad as a [[death knight]]. His soul was later saved by his son, [[Darion]].\r\n* [[Darion Mograine]] - Once a member of the [[Argent Dawn]], and eventually became a high-ranking servant of the Lich King. Mograine and the [[death knight]]s under his command broke free of the Lich King's grasp and became known as the [[Knights of the Ebon Blade]], dedicating themselves to bringing down the Scourge.\r\n* [[Thassarian]] - The first of the [[Knights of the Ebon Blade|death knight]]s to rejoin the Alliance. Like the other death knights, he was once a servant of the Lich King.\r\n* [[Koltira Deathweaver]] - Notable [[Knights of the Ebon Blade|death knights]] of the New Horde. Like the other death knights, he was once a servant of the Lich King.\r\n* [[Alonsus Faol]] - The creator of paladins, he was raised from his [[Faol's Rest|tomb]] after Arthas invaded Lordaeron. Was able to free his bond by himself. \r\n==Former command structure==\r\n*''' [[Lich King]]''' ( '''[[Arthas Menethil]]''') \r\n** '''[[Kel'Thuzad]]''' (Second-in-command to the Lich King and Master of [[Naxxramas]])\r\n** [[Lady Deathwhisper]]\r\n** [[Deathspeaker Kharos]]\r\n** [[Grand Widow Faerlina]]\r\n** [[High Invoker Basaleph]] (Overseer of [[Cathedral of Darkness]])\r\n** [[Grimkor the Wicked]] (Overseer of [[Aldur'thar: The Desolation Gate]])\r\n** [[Dar'Khan Drathir]]\r\n** [[Borgoth the Bloodletter]]\r\n** [[Jurion the Deceiver]]\r\n** [[Masophet the Black]]\r\n** [[Mirdoran the Fallen]]\r\n** [[Thel'zan the Duskbringer]] (Commander of the Scourge forces assaulting [[Wintergarde Keep]])\r\n**The Four Horsemen (tactics)\r\n** [[Baron Rivendare]] (Former ruler of [[Stratholme]] and leader of the Four Horsemen (tactics))\r\n** [[Thane Korth'azz]]\r\n** [[Sir Zeliek]]\r\n** [[Lady Blaumeux]]\r\n** [[Instructor Razuvious]]\r\n** [[Salanar the Horseman]]\r\n** [[Underking Talonox]] (Leader of [[Scourgeholme]])\r\n** [[Sapphiron]]\r\n** [[Araj the Summoner]] (Ruler of the ruins of [[Andorhal]])\r\n** [[Ras Frostwhisper]] (Ruler of [[Scholomance]])\r\n** [[Lord Alexei Barov]]\r\n** [[Lady Illucia Barov]]\r\n** [[Blood Steward of Kirtonos]]\r\n** [[Kirtonos the Herald]]\r\n** [[Lord Blackwood]]\r\n** [[Death Knight Darkreaver]]\r\n** [[Marduk Blackpool]]\r\n** [[Kormok]]\r\n** [[Lorekeeper Polkelt]]\r\n** [[Instructor Malicia]]\r\n** [[The Ravenian]]\r\n** [[Darkmaster Gandling]] (Headmaster of [[Scholomance]])\r\n** [[Instructor Chillheart]]\r\n** [[Jandice Barov]]\r\n** [[Doctor Theolen Krastinov]]\r\n** [[Rattlegore]]\r\n** [[Patchwerk]]\r\n** [[Captain Dargol]] (Leads Scourge forces in [[Agamand Mills]])\r\n** [[Devlin Agamand]]\r\n** [[Vectus]] (Head of [[Plagued dragonflight]] production)\r\n** '''[[Anub'arak]]''' (Ruler of the ruins of [[Azjol-Nerub]])\r\n** [[Under-King Anub'et'kan]] (Leader of the Scourge forces in the ruins of [[Icemist Village]])\r\n** [[Scourgelord Tyrannus]] (Overseer of the [[Pit of Saron]])\r\n** [[Bronjahm]] (Godfather of Souls)\r\n** [[Artruis the Heartless]] (Overseer in [[Sholazar Basin]])\r\n** [[Eydis Darkbane]] / [[Fjola Lightbane]]\r\n** [[Hildana Deathstealer]]\r\n** [[Lich-Lord Chillwinter]] (Commander of [[Talramas]])\r\n** [[Sindragosa]]\r\n** '''[[Lord Marrowgar]]''' (Commander of [[Icecrown Citadel]] defenses)\r\n** [[Falric]]\r\n** [[Marwyn]]\r\n** [[Deathbringer Saurfang]]\r\n** [[Professor Putricide]]\r\n** [[Grand Necrolord Antiok]] (The Grand [[Necrolord (occupation)|Necrolord]] of the Scourge)\r\n** [[Thiassi the Lightning Bringer]]\r\n** [[Rothin the Decaying]] (Chief Reanimator in the [[Obsidian Dragonshrine]])\r\n** '''[[Amnennar the Coldbringer]]''' (Overseer of [[Razorfen Downs]])\r\n** [[Charlga Razorflank]]\r\n** [[Glutton]]\r\n** [[Mordresh Fire Eye]]\r\n** [[Tuten'kash]]\r\n** Orbaz Bloodbane\r\n** '''[[Blood-Queen Lana'thel]]''' (Blood Queen of the [[San'layn]])\r\n** [[Blood Prince Council]]\r\n** Shade of Arugal\r\n** [[King Ymiron]] (King of the [[Vrykul]], Chieftain of the [[Dragonflayer clan]])\r\n*** [[Queen Angerboda]] (Queen of the Vrykul)\r\n** [[Overlord Drakuru]] (Scourge warlord of [[Voltarus]])\r\n** [[Blood-Princess Thal'ena]]\r\n===After the [[Fall of the Lich King]]===\r\n*''' [[Lich King]]''' ( '''[[Bolvar Fordragon]]''') (Undisputed ruler)\r\n**Adventurer\r\n**[[Four Horsemen|The Four Horsemen]] (Volunteer agents after an agreement)\r\n**Darion Mograine (Current leader of the Four Horsemen)\r\n**Sally Whitemane\r\n**Thoras Trollbane\r\n**Nazgrim\r\n** [[Salanar the Horseman]]\r\n**''' [[Lyandra Sunstrider]]'''\r\nWith most of Arthas' commanders dead, and his desire to lead a more passive Scourge, it is unclear what command structure, if any, Bolvar employed during his reign, except his agreement with the [[Knights of the Ebon Blade|Ebon Blade]] and the [[Four Horsemen]] who act voluntarily as his agents if the Scourge remains contained in Northrend during the [[Third invasion of the Burning Legion|demons' third invasion]].\r\nIt is noted though that all remaining Scourge posts in Azeroth that continue as a threat are run by the [[Cult of the Damned]], who had retained their will during their service to the Scourge to begin with.\r\n==Organizations==\r\n*[[Nerubian]]s\r\n**[[Ahn'kahar]] - Undead nerubians that can be found within [[Ahn'kahet]].\r\n**[[Anub'ar]] - A group of undead nerubians, located around [[Icemist Village]] and within [[Azjol-Nerub]].\r\n**[[Hath'ar]] - Undead nerubians located in [[Zul'Drak]].\r\n**[[Nerub'ar]] - Undead nerubians who are attacking [[Valiance Keep]].\r\n*[[Boneguard]] - A group of Scourge members located at the [[Court of Bones]].\r\n*[[Frostbrood]] - Elite frost wyrms that were raised from the bones of blue dragons at [[Sindragosa's Fall]]. These frost wyrms are now one of the strongest weapons the Scourge have.\r\n*[[Plagued dragonflight]] - The Cult of the Damned began breeding a plagued dragonflight within [[Scholomance]] as another method of spreading the [[Plague of Undeath]].\r\n*[[San'layn|The San'layn]] - A faction of undead blood elves, led by a host of 'vampiric blood elf princes' who appear to hold influential positions within the Scourge. The San'layn were created after Arthas took the most powerful of [[Kael'thas]]' shattered forces into his service.\r\n**[[Blood Prince Council]] - A group of three [[San'layn]] princes.\r\n*[[Ymirjar]] - The elite warrior caste of the Lich King, the victorious vrykul in the battle of ascendance at [[Jotunheim]]. They inhabit the city of [[Ymirheim]] in the center of [[Icecrown]].\r\n*[[Cult of the Damned]] - An organization of the living beings who serve the Lich King. Members are mostly [[human]], but including other races. The Cult was formed during the opening days of the [[Third War]], when the Scourge was loyal to the [[Burning Legion]], and establishing its foothold on [[Lordaeron]].\r\n**[[Thuzadin]] - A group of necromancers and dark wizards in the burning city of [[Stratholme]].\r\n*[[Black Guard]] - An elite group of [[skeleton]]s serving [[Baron Rivendare]].\r\n*[[Mindless Ones]] - wandering undead around [[Deathknell]].\r\n*[[Death knights of Acherus]] - A death knight order under the command of the Lich King, specifically trained for destroying the [[Scarlet Crusade]] and the [[Argent Dawn]]. The necropolis [[Acherus]] is their base.\r\n**[[Host of Suffering]] - Another death knight order under the command of the Lich King. It succeeded the death knights of Acherus who were, for the most part, freed of the Lich King's will after the [[Battle for Light's Hope Chapel]].\r\n*[[Dragonflayer clan]] - A vrykul clan under the control of the slumbering [[King Ymiron]]. They have taken up residence in [[Utgarde Keep]].\r\n*[[Drakuru trolls]] - A small group of hostile [[scourge troll]]s found in [[Zul'Drak]]. They are led by [[Overlord Drakuru]].\r\n*[[Rot Hide tribe]] - A group of gnolls, like many other creatures in northern [[Lordaeron]], were unable to escape the [[Lich King]]'s [[Plague of Undeath|Plague]]. Now a number of them serve as undead minions to the Scourge.\r\n*[[Death's Head tribe]]\r\n*[[Valkyrion]] - A [[vrykul]] settlement located in the western area of the [[Storm Peaks]]. The [[frost vrykul]] of [[Brunnhildar Village]] hate them for becoming the Lich King's servants. The Blighted Pool can be found here, where proto-drake eggs are corrupted by hyldnir of Valkyrion.\r\n*[[Winterskorn clan]] - A tribe of vrykul that live in [[Skorn]] and [[Baleheim]] in [[Howling Fjord]] of Northrend. They are led by [[Bjorn Halgurdsson]].\r\n*[[Wolfcult]] - A mysterious organization that is predominantly found in the Grizzly Hills of southern Northrend. It is led by none other than the [[Shade of Arugal]], who had previously adopted the [[worgen]] of [[Silverpine Forest]] in northern [[Lordaeron]] as his children.\r\n*[[Undead Ravagers]]\r\n*[[Sveldrek]] - A group of [[vrykul]] operating in the [[Pit of Saron]].\r\n*Aerial Surveillance Squadron\r\n==In ''Warcraft III''==\r\nUndead Scourge was the undead faction led by [[Mal'Ganis (Warcraft III)|Mal'Ganis]] and [[Arthas (Warcraft III)|Arthas]]. Their team color was green. It appeared as an enemy faction in and [[Ravages of the Plague]] and [[The Cult of the Damned]]. Their units consisted of regular undead units with the addition of sketelons.\r\n===Monstrous Scourge===\r\nSome creatures of the Scourge are not technically undead, but instead are monstrous constructions created by the science and magical experimentation of the [[acolyte]]s and [[necromancer]]s following [[Ner'zhul]]. These are constructed creatures fashioned by the perverse experimentation of the Lich King's followers and do not occur in any natural fashion.\r\nMonstrous members of the Scourge are not particularly intelligent, having been created from the leftover pieces of enemies and friends alike. They are, however, very loyal and almost fanatically devoted to whatever task is appointed to them. These creatures are not truly individuals, having little will of their own other than that given to them on creation or through the current descriptions given in their orders.\r\n===Membership===\r\nThe members of the Scourge are easy to spot, smell, and identify. And it doesn't take much to join. All it takes is to either love the Scourge or be undead and under the Lich King's spell, and you're in. One does not need to do much to be in this organization. Some of the first members were mortals who had fallen in the undead plague. People sickened from the plague and died, only to rise as zombies. This city-razing technique proved to be not as efficient as the Lich King desired, apparently, because he started telling his necromancers to desecrate graveyards and raise up even more members. Only two things seem to separate a Scourge servitor from the Lich King's will: whatever faltering in the Lich King's power allowed the Forsaken to free themselves from his grasp, and destruction of their bodies. Scourge creatures are bidden to do the Lich King's will, and they do this with a blind fervor. The Cult of the Damned is an enigma. No one knows why they do what they do. Whatever the reason, they willfully follow the Scourge, dressing in dark robes, doing their bidding, while helping to spread the plague into more and more cities.\r\n==Notes==\r\n*[[Kel'Thuzad]] wrote ''[[The Decree of the Scourge]]''.\r\n*[[Menethil's Gift]] is holy ground to the Scourge.\r\n*The architecture of the Scourge buildings is very similar to the one of the [[Maldraxxus]] necrolords, however they are inspired by the [[nerubian]]s of [[Northrend]]. What happened is that it is the nerubians themselves who were inspired by Maldraxxus, as Death's influence was present on Azeroth long, long before Ner'zhul became the Lich King.\r\n*A tabard bearing the Scourge crest was added to the game files in ''[[World of Warcraft: Cataclysm|Cataclysm]]'' but is strangely labeled as a [[Forsaken]] tabard. The model is inaccessible to players but is worn by a number of Forsaken NPCs—including [[Gilnean Envoy]]s, [[Angela Hipple]], [[Andrew Vestal]], [[Captain Amalia Stone]], [[Kaldras Snape]], [[Plague Master Herbert]], and [[Bulwark Dreadguard]]s—and the corresponding in-game icon is used by the [[Tall, Dark, and Sinister]] achievement. The date when it was first added and its use by the Gilnean Envoys suggest that the tabard would've been associated with the [[Battle for Gilneas]] battleground (or its original version, the [[Battle for Gilneas|Battle for Gilneas City]]), but this doesn't explain why the Forsaken would choose to wear the symbol of their archenemy.",},
			["Scourgeholme"] = { content = "'''Scourgeholme''' is a [[Scourge]] fortress located in eastern [[Icecrown]]. The [[Argent Crusade]] plans on purging the area of Scourge forces and building a new fortress on the site, which [[Tirion Fordring]] has called \"Justice Keep\". (Coincidentally, \"Justice Keep\" was the original name for what became [[Valiance Keep]] in [[Borean Tundra]].)",},
			["Scourgestone"] = { content = "[[Undead]] creatures sent out by the [[Lich King]] and his forces will have a chance to carry upon them three different levels of '''Scourgestones'''. One may obtain these stones by equipping one of the following trinkets:\r\n*Argent Dawn Commission - Gained at level 50 from any Argent Dawn Quartermasters\r\n*Seal of the Dawn - Gained after completing \"[[Quest:The Active Agent|The Active Agent]]\"\r\n*Rune of the Dawn - Gained after completing \"[[Quest:The Active Agent|The Active Agent]]\"\r\n*Mark of the Champion - Gained after turning in [[the Phylactery of Kel'Thuzad]]\r\nUndead [[mob]]s, along with their living compatriots of the [[Cult of the Damned]] in [[Western Plaguelands]], [[Eastern Plaguelands]], [[Scholomance]] and [[Stratholme]] have the chance to carry one of these stones.\r\nBoss type mobs such as [[Ras Frostwhisper]], [[Darkmaster Gandling]] and [[Baron Rivendare]] will ''always'' carry a Corruptor's Scourgestone.\r\n==Types of Scourgestones==\r\n*[[Minion's Scourgestone]] - turn in 20 for an [[Argent Dawn Valor Token]]. Found on mobs level 50 and up.\r\n*[[Invader's Scourgestone]] - turn in 10 for an [[Argent Dawn Valor Token]]. Found on mobs level 53 and up.\r\n*[[Corruptor's Scourgestone]] - turn in one for an [[Argent Dawn Valor Token]]. Found on bosses.\r\n==Background==\r\nThe Argent Dawn needs them so that [[paladin]]s can turn the scourgestones into \"[[Holy Mightstone|mightstones]]\".",},
			["Scourge Cauldron"] = { content = "The '''Scourge Cauldron'''s, also known as [[Plague Cauldron]], can be found in the fields of [[Western Plaguelands]].",},
			["Scourge Data"] = { content = "'''Scourge Data''' is an item found in one of the Stratholme ziggurats and the objective of the quest [[Quest:The Active Agent|The Active Agent]].\r\n==Scourge Data as a Quest Objective==\r\n*The Active Agent\r\n==As an object==\r\nThe '''Scourge Data''' is found on the floor in one of the three [[ziggurat]]s in [[Stratholme]]. It can spawn in any one of the three ziggurats.",},
			["Scourge Gryphon"] = { content = "The '''Scourge Gryphon''' serves as a [[flight path]] taxi between [[Acherus: The Ebon Hold]] and [[Death's Breach]] during the starting instance for [[Death Knight]]s. They also ferry players from [[Light's Point]] back to [[Death's Breach]] after annihilating 200 [[Scarlet Fleet Defender]]s while on the quest Massacre At Light's Point.",},
			["Scourge Haunt"] = { content = "'''Scourge Haunt''' follows players who have a Haunted Memento in their bags.",},
			["Scourge Invasion"] = { content = "The '''Scourge Invasion''' was a [[World Event|world event]] in [[Patch 1.11]] that heralded the opening of [[Naxxramas]], the citadel of the dreaded [[Kel'Thuzad]]. It was reintroduced into the game in preparation for [[Wrath of the Lich King]] and tuned for the new level cap which players had achieved (70).\r\nSeveral regions of [[Azeroth]] have come under attack by [[Scourge]] forces. Members of the [[Argent Dawn]] are already organizing a worldwide counter to the Scourge invasion, keeping an eye out for any [[necropolis]] sightings and passing on their information to all adventurers willing to aid them in their struggle.\r\nWith each victory against the Scourge, the defense grows stronger. As more and more invasion attempts are beaten back by the defenders, the Argent Dawn will be able to bestow increasingly more powerful blessings upon those fighting the invaders. If the mortal races focus on clearing the Scourge camps all over the world that have sprung up beneath each necropolis, perhaps the invasion can effectively be halted or even repelled. Those who wish to take up arms against the undead invaders should speak with a representative of the Argent Dawn to learn what regions need help and how the defense is holding up.\r\n \r\n==Necropolis invasions, Necrotic Runes and the Shards==\r\nDuring the Scourge Invasion, numerous high-level zones are under attack by one or two flying [[necropolis|necropoli]] each. The zones under attack have purple skull markers on the continent-level maps. The zones that get attacked are [[Eastern Plaguelands]], [[Burning Steppes]], [[Blasted Lands]], [[Tanaris]], [[Azshara]], and [[Winterspring]]. See showing possible spawnpoints for scourge forces\r\nNPCs near Argent Dawn tents in the major cities will note where the Necropoli are attacking, and how many are in each zone. There are also Necropoli over the capitals. The ones over the major cities seem to be permanent but they only spawn low level scourge for the introductory quest.\r\n===Assaulting the Necropolis===\r\nThe Necropoli are accompanied by [[Necrotic Shard]]s, which are visible on the ground near each of the flying citadels. These shards are always surrounded by a large number of undead. The undead are non-elite and grant 5 Argent Dawn reputation until the end of , unlike normal undead. They yield Invader's Scourgestone if slain while having the Argent Dawn Commission equipped.\r\nThe Shards near the undead are weakened as the undead are killed. When the strength of the shard reaches zero, four [[Cultist Engineer]]s will appear and start to heal it. Each of these engineers can be \"disrupted\" through the use of '''eight [[Necrotic Rune]]s'''. The Acolyte will then convert into a [[Shadow of Doom]], which is a tough 70 elite mob. Upon its defeat, the Shadow of Doom will yield a Corruptor's Scourgestone, 50 reputation with the Argent Dawn, 30 Necrotic Runes, and has a chance to drop a chest piece of the [[Undead Slaying]] set.\r\nDestroying all four Shadows of Doom will destroy the Necrotic Shard, heal nearby players for 10,000, grant them a powerful buff, and stop new Scourge from spawning there (at least for a short time).\r\nDestroying all the Necrotic Shards attached to a Necropolis will destroy the Necropolis. Destroying all the Necropoli in a zone will cause that zone to no longer be under attack. The Scourge will eventually deploy more Necropoli however, so clearing a zone does not mean it is safe forever.\r\n====Marks of the Dawn====\r\nAfter a certain number of battles have been won on a server, additional rewards are available. After the battles have been completed, a new NPC will spawn at Lights Hope Chapel and in your faction capital and will hand 3 of the item out for free!\r\n====Necrotic Rune turn-ins====\r\nThe undead have a chance to drop a Necrotic Rune. [[Commander Thomas Helleran]] at [[Light's Hope Chapel]] wants ten of these runes to complete the quest Under the Shadow; after completing Under the Shadow the remainder can also be turned in to the [[Argent Quartermaster]] at Light's Hope Chapel or in camps in your faction capital city for various rewards:\r\n====Mob drops====\r\nIn the original Scourge Invasion, three [[rare spawn]]s appear at each of the Shards, which drop two to three Necrotic Runes as well as the bracers of the [[Undead Slaying]] set. Like most rare spawns, they are not elite but are slightly higher level. These spawns appear roughly every fifteen minutes after engagement of Scourge in the area, and despawn about fifteen minutes later.\r\nIn the second Scourge Invasion, the rare spawns are level 70, and instead drop the pants for the new [[Blessed Undead Slaying]] sets.\r\n===Letters from the Scourge===\r\nNon-elite undead around the Necrotic Shards will occasionally drop letters. There are six total, each of which starts a turn-in quest at the [[Keeper of the Rolls]] in [[Light's Hope Chapel]] for a small reward. Once the quest is started, the letters may be read. They contain well-written bits of lore, mainly related to the events in [[Warcraft 3]].\r\nA week after turning in a letter you will receive through the mail a message from the Keeper indicating an NPC that is mentioned in the original (quest) letter. This does not start a quest. The NPCs indicated become vendors that will sell you Freshly-Squeezed Lemonade (2934 mana over 30 secs) and Friendship Bread (2148 health over 30 secs). There is no other reward, and the lemonade and bread are functionally equivalent to normal level 45 vendor food and drink, though while consuming them an animation of a cartoon heart is displayed above your character and a short, tinging sound will repeat. These vendors continue to sell these items after the Scourge Invasion ends. There is one vendor in each faction [[capital city]] as well as [[Booty Bay]], [[Eastern Plaguelands]], and [[Silithus]].\r\nThese letters appear in both versions of the Scourge Invasion.\r\n==Capital City Invasions==\r\nAside from the Necropolis events outdoors, Scourge mobs will occasionally appear in [[Stormwind]] and [[Undercity]]. They spawn seemingly at random, causing city NPCs to yell for help. The most common are Flameshockers, level 55 mobs (update: they are level 63 elite mobs during the 2008 incarnation of this event) which do not hit very hard, but have a very large amount of health points. The city NPCs are capable of killing the Flameshockers on their own, but if a player or group chooses to tag them, they will receive 5 Argent Dawn rep (at Honored). Flameshockers can drop Necrotic Runes.\r\nThere are also groups of tougher elite mobs (Pallid Horror) that periodically spawn in Stormwind and Undercity and attempt to get to the city leader, causing him/her to yell that he/she is under attack. (These do not pose an actual threat to racial leaders, they are easily able to defeat the creatures if they manage to reach them.) When all the mobs are defeated, the city leader will yell that they are safe, and a dead Necrotic Shard will spawn. The shard will give a quest to talk to an NPC at [[Light's Hope Chapel]]. Any player can receive this quest, even if they did not tag the mobs that spawned the shard.\r\nAll the mobs that spawn inside cities are yellow (passive) and do not attack players who haven't attacked them first. They also appear not to attack vital NPCs such as bankers and vendors. So, it would seem players who aren't interested in the city events are not threatened by them in any way, and can simply ignore them and go about their business.\r\n==New bosses==\r\nThere are also reports of Scourge agents showing up in [[Stratholme]], [[Scholomance]], [[Dire Maul]], the [[Scarlet Monastery]], [[Shadowfang Keep]], [[Razorfen Downs]], and [[Karazhan]]. These new boss mobs can be idenitified by the glowing purple aura they have which is similar to those of the invading Scourge outside the instances.\r\n===Tenris Mirkblood‎===\r\nTenris Mirkblood, a [[darkfallen]], can be found above [[Attumen the Huntsman]]'s room in the kitchen. He is the objective of Chamber of Secrets.\r\n===Balzaphon===\r\nBalzaphon is a [[lich]] who formerly patrolled the fountain courtyard to the left of the service entrance in [[Stratholme]]. Balzaphon uses many frost based abilities. He has since (patch 3.0.2) been moved from his patrol route and now stands in a corner northeast of the fountain.\r\n===Lord Blackwood===\r\nLord Blackwood resides in [[Scholomance]]. He is a large [[skeleton]] who attacks with both ranged bow attacks and heavy melee attacks.\r\n===Revanchion===\r\nRevanchion, a [[wraith]], wanders the hallway behind Tendris Warpwood in [[Dire Maul]].\r\n===Scorn===\r\nThe lich Scorn appears in the graveyard portion of the [[The Scarlet Monastery]] once [[Bloodmage Thalnos]] is defeated.\r\n===Sever===\r\nThe [[abomination]] Sever appears in [[Shadowfang Keep]] along the corridor that runs parallel to the Great Hall and Kitchen. He is arguably the hardest boss in the instance.\r\n===Lady Falther'ess===\r\nLady Falther'ess, a [[banshee]], and can be found in the slaughter pens area of [[Razorfen Downs]].\r\n==Quests==\r\nThe following is a list of quests currently available in the 2008 invasion.\r\n*Investigate the Scourge of Stormwind\r\n*Investigate the Scourge of Darnassus\r\n*Investigate the Scourge of Exodar\r\n*Investigate the Scourge of Ironforge\r\n*Cracked Necrotic Crystal\r\n*Investigate the Scourge of the Undercity\r\n*Investigate the Scourge of Orgrimmar\r\n*Investigate the Scourge of Silvermoon\r\n*Investigate the Scourge of Thunder Bluff\r\n*Faint Necrotic Crystal\r\n*The Keeper's Call\r\n*Light's Hope Chapel\r\n*Under the Shadow\r\n*Shadows of Doom\r\n*Chamber of Secrets\r\nThe following quests start from rare drops off the non-elite Scourge near any crystal.\r\n*Letter from the Front\r\n*Page from the Front\r\n*Envelope from the Front\r\n*Note from the Front\r\n*Document from the Front\r\n*Missive from the Front\r\nIn [[Shattrath]], on the [[Terrace of Light]], members of the [[Church of the Holy Light]] for the Alliance and the [[Royal Apothecary Society]] for the Horde work to combat the [[Plague of Undeath]] and the floating [[necropolis]]es.\r\n<!--\r\n == The End of the Invasion==\r\nEarly reports indicate that when 150 victories over the Necropoli are won, the invasion ends. Realms that have already reached this point indicate that there is no way to turn in Necrotic Runes that you may still be holding at that point, and that there is no way to complete any of the remaining quests, even if their goals have been met. The new bosses in the instances are also removed.\r\n[[Drysc]] promises in a post on the Blizzard forums:\r\n<span class=\"blizztext\">We will be implementing something soon that will allow you to continue to turn in your remaining Necrotic Runes, so don't throw them away! After the celebrations subside the Argent Dawn will certainly want to continue commemorating those who fought valiantly to stave off the invasion.</span>\r\nThere is no firm indication from Blizzard indicating whether or not the event will ever occur again. The closest thing to a hint is from [[Kisirani]] (on the concurrence of the fire festival and the Scourge Invasion), which indicates that it may be an annual event:\r\n<span class=\"blizztext\">...but I'll look into getting the sun patched so it hits its highest point later next year. ;)</span>\r\nThe insignia quests, and the insignia item drops, are still intact, as well as the Marks of the Dawn. -->\r\n==[[Zombie Infestation]] - Scourge Invasion Vol.2==\r\nOn Oct. 22, 2008, Healers from the Argent Dawn posted themselves in key positions in all cities across Azeroth, anticipating that a new invasion was on the rise. This would prove to be a wise decision, as the Invasion's first salvo did not take the form of necropoli and undead cannon fodder, but was aimed mostly at the far-traveled adventurers that were instrumental in the defeat of the first invasion.\r\nMysteriously appearing [[Conspicuous Crate]]s would come to peak the curiosity of some hero, who would open them only to be infected with a fast-acting Zombie Plague. On October 23, [[Plagued Roach]]es began to appear in the capital cities; killing them would release a plague cloud and infect the attacker, even if he or she struck from a distance.\r\nShould the infected person not be able to recieve treatment in 10 minutes time from the [[Argent Healer]]s or a fellow adventurer trained in treating disease, they will transform into a [[Plague Zombie]]. Not only does this new Undead add to the Scouge's ranks as a warrior, but is also capable of infecting others with the very same disease that turned him or her. It has been observed that healing from sources other than the Argent Dawn agents is becoming less and less successful with the passing of time, often requiring numerous attempts to remove the plague infection; this indicates the plague is becoming stronger and more resistant, leaving adventurers with only the Argent Healers as their safest and surest method for escaping undeath as a Plague Zombie.\r\nOnly time will tell if the heroes of the world will once again turn back the Lich King's new attack... or become a part of it.\r\nBy October 25, 2008, the necropoli have returned, and all the minions were leveled up to 70. Necropoli emerged in the zones that originally showed signs of the invasion, and the zombie infection is now down to 2 minutes.\r\nBy October 26, 2008, the infection was down to 1 minute.\r\nBy October 27, 2008, the infection has been cured, but the Scourge Invasion still is happening.",},
			["Scourge Siege Engineer"] = { content = "'''Scourge Siege Engineers''' man the [[Scourge Meat Wagon]]s that are assembled outside the gates of [[Quel'Thalas]]. They are located in [[Eastern Plaguelands]]. \r\n==Objective of==\r\nFifteen of the engineers need to be killed for the quest A Demonstration of Loyalty.",},
			["Scout's Blade"] = { content = "*Scout's Blade (level 18)\r\n*Scout's Blade (level 28)\r\n*Scout's Blade (level 38)\r\n*Scout's Blade (level 48)\r\n*Scout's Blade (level 58)",},
			["Scout's Medallion"] = { content = "The '''Scout's Medallion''' is [[PvP]] reward necklace for the [[Horde]] from the [[Warsong Outriders]]. It can be purchased for the correct amount of honor points and Warsong Gulch Marks of Honor depending on the level. There are 5 versions of this necklace which correspond to the 5 level brackets in [[Warsong Gulch]].\r\nThe [[Alliance]] equivalent is [[Sentinel's Medallion]].\r\n==Source==\r\nThe Scout's Medallion is sold by Kelm Hargunth at [[Mor'shan Base Camp]] in the [[Barrens]]. Previously, players had to have Honored status in order to purchase this necklace. Now it can be purchased with honor points and the correct amount of Warsong Gulch Marks of Honor.",},
			["Scout"] = { content = "'''Scouts''' of various races serve the [[Horde]], [[Alliance]] and neutral and hostile organizations in Azeroth and beyond.\r\n==Named==\r\n* Alleria Windrunner\r\n* Scout Makha\r\n* Scout Neftis\r\n* Scout Galiaan\r\n* Scout Manslayer\r\n* Scout Riell\r\n* Scout Proudhill\r\n* Scout Stronghand\r\n* Scout Tharr\r\n* Scout Jalia\r\n* Cenarion Scout Landion\r\n*Thuran Whitewind \r\n* Scout Bloodfist\r\n* Cenarion Scout Azenel\r\n* Williden Marshal\r\n* [[Kurdran]]\r\n==Scouts in WoW==\r\n*[[Argent Scout]]\r\n* [[Gravelflint Scout]] - Darkshore\r\n* [[Forsaken Scout]] - Ashenvale\r\n* [[Kolkar Scout]] - Desolace\r\n* [[Stonard Scout]] - Swamp of Sorrows\r\n* [[Maraudine Scout]] - Desolace, Maraudon\r\n* [[Gelkis Scout]] - Desolace\r\n* [[Magram Scout]] - Desolace\r\n* [[Cenarion Scout]] - [[Acherus: The Ebon Hold]], [[Scarlet Enclave]]\r\n* [[Warsong Scout]] - Ashenvale\r\n* [[Dragonmaw Scout]] - Wetlands\r\n* [[Tunnel Rat Scout]] - Loch Modan\r\n* [[Galak Scout]] - Thousand Needles\r\n* [[Firemane Scout]] - Dustwallow Marsh\r\n* [[Riverpaw Scout]] - Westfall\r\n* [[Murloc Scout]] - Redridge Mountains\r\n* [[Blackrock Scout]] - Redridge Mountains\r\n* [[Stonesplinter Scout]] - Loch Modan\r\n* [[Highvale Scout]] - The Hinterlands\r\n* [[Scarlet Scout]] - Tirisfal Glades, Scarlet Monastery\r\n* [[Razormane Scout]] - Durotar\r\n* [[Horde Scout]] - Ashenvale\r\n* [[Mossflayer Scout]] - [[Eastern Plaguelands]] \r\n* [[Bloodscalp Scout]] - [[Stranglethorn Vale]] \r\n* [[Skullsplitter Scout]] - [[Stranglethorn Vale]] \r\n* [[Blood Elf Scout]] - [[Shadow Ridge]], [[Azuremyst Isle]]\r\n===Satyr scout===\r\nSatyr scouts are the antithesis of everything that night elf scouts stand for. While their hated night elf cousins fight with bows and use their abilities to tend the forests, satyr scouts prefer hand-to-hand combat, striking by surprise, and dominating nature for their demonic masters. Satyr scouts use wild healing selfishly, not bothering to aid another unless they get something out of it.\r\n===Named===\r\n* Anduin Lothar\r\n* Baelgun Flamebeard\r\n* Cairne Bloodhoof\r\n* Ilius\r\n* Dermid \r\n* Kril'fon\r\n* Malfurion Stormrage\r\n* Magistrate Randalvarr\r\n* Marshal Dughan\r\n* Marijah\r\n* Helvas Grange\r\n* Hona Stonefall\r\n* Yshmeel",},
			["Scouts"] = { content = "The scout excels in wilderness survival and is skilled in combat. They can track a day-old trail and snipe from the treetops with equal facility. Scouts often serve as guides for adventurers, if they are not out adventuring themselves. Though the scout is at home in the wild, they are more a guerilla fighter than a defender of nature. Scouts are found in any race. No matter their region, from forests to mountains to swamps, all races need and train scouts as guilds and specialized fighters. Scouts are solitary and have somewhat individualistic natures.",},
			["Scout balloon"] = { content = "Invented by the [[Alliance]] as they explored [[Kalimdor]], the '''scout balloon''' is a backpack containing a balloon inflated with hot air produced by a tiny phlogiston engine. A small propeller on the pack allows the “pilot” limited maneuverability, but scout balloons are usually tethered to a tree and used simply for an elevated view of the surrounding territory. Cheap and simple to operate, scout balloons are becoming increasingly popular.",},
			["Scout Navrin"] = { content = "'I have seen many dangers in these wastes. Who knows what creatures yet lurk in the dust to ambush the unwary?'\r\n <span style= \"font-variant:small-caps\">~ Scout Navrin - Sha'tari Base Camp, Terokkar Forest</span>\r\n'''Scout Navrin''' is a level 60 [[quest giver]] located at the [[Sha'tari Base Camp]] in the [[contested]] territory of [[Terokkar Forest]].\r\nHe starts the quest Taken in the Night.\r\nSee [[List of Terokkar Forest NPCs]].",},
			["Scrabblescrew's Camp"] = { content = "'''Scrabblescrew's Camp''' is located not far from the [[Kodo Graveyard]] in [[Desolace]]. It is the home of [[Smeed Scrabblescrew]], an enterprising [[goblin]] who maintains a [[kodo]] caravan.",},
			["Scraggy Leather collection"] = { content = "The '''Scraggy Leather Armor Set''' items are random [[drop]]s in the Blood Elf beginning area, Sunstrider Isle and Falthrien Academy. It is equivalent to the [[Ragged Leather Armor Set]] [[world drop]] for beginning areas, but lacks a cape in the set. This [[quality]] gear is actually very nice in the starting levels.",},
			["Scrapped Fel Reaver"] = { content = "'''Scrapped Fel Reaver''' can be found in [[Netherstorm]] .\r\n==Drops == \r\n \r\n0.04% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scrap Field"] = { content = "'''The Scrap Field''' is a hill covered with the remains of several destroyed [[Fel Reaver]]s. The [[Burning Legion]] occupy the scraps, dangerously near the [[Eco-Dome Midrealm]].",},
			["Screecher Spirits"] = { content = "==In-game text==\r\n===Objective===\r\nCapture the spirits of 3 screechers in [[Feralas]], then return to [[Yeh'kinya]] in [[Steamwheedle Port]].\r\n===Description===\r\n''I seek the spirits of the vale [[Vale Screecher|screechers]] of Feralas. They are the cousins of an old, old god, and their spirits are linked to him.''\r\n''Take this [[Yeh'kinya's Bramble|bramble wand]] and go to Feralas. Find and defeat [[Vale Screecher|vale screechers]] in southern and central Feralas, then wave my bramble over their fallen bodies. This will coax their spirit to reveal itself. Touch the spirit and collect its essence.''\r\n''Return to me with my bramble and with the collected essence, and I will tell you more of the old god of which I spoke.''\r\n===Progress===\r\n''Have you collected the essence of the screecher spirits, <name>?\r\n===Completion===\r\n''You have done well, <name>. Perhaps now it is time to reveal more...\r\n''There is an ancient prophecy among the trolls, where the dead god Hakkar, the Soulflayer, will one day return to this earth. Some say the coming of Hakkar will bring joy and glory to trollkind, while others believe his resurrection marks the end of all things.\r\n''I do not believe this myth, but I do know the essence of Hakkar holds great power, and this power should be kept from those who would abuse it...\r\n==Quest Progression==\r\n#Screecher Spirits\r\n#The Prophecy of Mosh'aru\r\n#The Ancient Egg\r\n#The God Hakkar\r\n#The Lost Tablets of Mosh'aru\r\n#The Final Tablets\r\n#Confront Yeh'kinya\r\n#The Hand of Rastakhan",},
			["Screeching Canyon"] = { content = "'''The Screeching Canyon''' is a zone in [[Thousand Needles]] canyon infested by aggressive Screeching [[harpies]]. The [[Roguefeather Den]] is located in the back of it.",},
			["Scroll"] = { content = "An [[item]] that must be [[read]] to be [[use]]d. Most '''scrolls''' have some sort of [[buff]] effect that applies to the selected target, but some just have a message.\r\nScroll buffs do not stack with player buffs that affect the same stat.\r\ninscribers in will be able to create [[blank parchment]], enabling enchants to be put on, this will eliminate the common scrolls from being obtained from just loot",},
			["Scrolls"] = { content = "#redirect [[Scroll]]", redirect = "Scroll",},
			["Scroll: Create Signet of Beckoning (Fire)"] = { content = "#REDIRECT [[Scroll: Create Signet of Beckoning (fire)]]", redirect = "Scroll: Create Signet of Beckoning (fire)",},
			["Scroll: Create Signet of Beckoning (Water)"] = { content = "#REDIRECT [[Scroll: Create Signet of Beckoning (water)]]", redirect = "Scroll: Create Signet of Beckoning (water)",},
			["Scroll of Atalor"] = { content = "==Source==\r\nFound within a [[Cabal Chest]] in the [[Shadow Tomb]] of [[Terokkar Forest]].\r\n== As a quest objective==\r\nThis item is an objective of The Shadow Tomb.",},
			["Scroll of Myzrael"] = { content = "==Source==\r\nThis item is provided for Summoning the Princess.",},
			["Scroll of Strength"] = { content = "==Source==\r\nThis item can be purchased for 2 silver copper from:\r\n* Dawn Brightstar in [[Elwynn Forest]]\r\n* Adair Gilroy in [[Stormwind City]]\r\n* Deneb Walker in [[Arathi Highlands]]\r\n* Salazar Bloch in [[Tirisfal Glades]]\r\n* Montarr in [[Thousand Needles]]\r\n* Balai Lok'Wein in [[Dustwallow Marsh]]\r\n* Professor Thaddeus Paleo in [[Mulgore]]\r\n* Rathis Tomber in [[Ghostlands]]\r\nThis item can be looted from most level 14-30 [[Humanoid]] monsters.",},
			["Scryer's Tier"] = { content = "'''Scryer's Tier''' is a terrace in [[Shattrath City]], and the base of operations for the [[Scryers]]. At the center of the Tier is the [[Seer's Library]], which serves as the [[faction]]'s headquarters. Scryer's Tier also boasts an [[inn]] run by [[Innkeeper Haelthol]]and a variety of [[vendor]]s, including [[reputation]] vendors and a [[reagent]] vendor behind the Seer's Library. \r\nOne who is favored by the [[Aldor]] will be attacked by Scryer guards and sent to the gates of [[Shattrath City]] with a three minute debuff if they attempt to visit the Scryer's Tier.\r\nScryer-favored players who wish to take the shortcut to [[Nagrand]] through the Aldor rise should be warned not to take the elevator between the Scryer's Tier and Aldor Rise, since [[Aggro|aggroing]] the guards and getting Banished from [[Shattrath City]] is very easy. Instead, take the main elevator from the Terrace of Light and dodge past the NPCs and the Inn to get to the tunnel.",},
			["Scryer"] = { content = "'''Scryer''' is a [[blue drake]] found in the [[Mazthoril]] cave in [[Winterspring (Classic)|Winterspring]] prior to the [[Cataclysm (event)|Shattering]]. [[Emberstrife]] wanted his skull for [[The Test of Skulls, Scryer]].\r\n==Abilities==\r\nScryer dealt frequent damage ranging from 500+ to 700+. One of his abilities was a magic debuff (Amplify Magic) that caused 100% extra magic damage which in combination with his Frost Breath could hit for up to 2000 damage. As his name implies, he could detect rogues and druids in stealth.\r\n==Drops==\r\n*[[The Skull of Scryer]]\r\n*[[Mature Blue Dragon Sinew]]",},
			["Scryers"] = { content = "''Were you looking for the [[blue drake]], [[Scryer]]?''\r\n----\r\nThe '''Scryers''' are a [[faction]] of [[blood elves]] led by [[Voren'thal the Seer]]. The group broke away from Prince [[Kael'thas Sunstrider]], heir to the throne of [[Quel'Thalas]] and ruler of the blood elven [[race]], and offered to assist the [[naaru]] in rebuilding [[Shattrath City]]. They are at odds with the [[Aldor]], and compete with them for power within Shattrath and for the naaru's favor. Characters may join the Scryers by completing the [[quest]] Allegiance to the Scryers, thereby becoming with the Scryers and with the Aldor.\r\n==Lore==\r\n''From the article \"\", found at the World of Warcraft website:\r\nThis time, the attack [on Shattrath City] came from the armies of [[Illidan Stormrage]]. A large regiment of blood elves had been sent by Illidan’s ally, Prince Kael'thas Sunstrider, to lay waste to the city. As the regiment of blood elves crossed the bridge, the Aldor’s exarchs and vindicators lined up to defend the [[Terrace of Light]]. Then the unexpected happened: the blood elves laid down their weapons in front of the city's defenders. Their leader, a blood elf elder known as Voren’thal, stormed into the Terrace of Light and demanded to speak to the naaru [[A'dal]]. As the naaru approached him, Voren’thal knelt and uttered the following words: “I’ve seen you in a vision, naaru. My race’s only hope for survival lies with you. My followers and I are here to serve you.”\r\nThe defection of Voren’thal and his followers was the largest loss ever incurred by Kael’thas’ forces. Nor were these just any blood elves. Many of the strongest and brightest amongst Kael’thas’ scholars and magisters had been swayed by Voren’thal's influence. The naaru accepted the defectors who became known as the Scryers.''\r\n==Services == \r\nThe Scryers offer a variety of services to those who swear allegiance to their cause, including an [[inn]], a [[bank]] and various [[vendors]]. Their most notable services, however, are their [[Master]] and a [[Grand Master]] Enchanter [[trainer]]s, the availability of whom allow aspiring enchanters to attain [[master]]y over the [[Enchanting]] [[profession]] without entering [[Uldaman]]. Of course, enchanters need not ally themselves with the Scryers simply to train as masters: the Scryer Enchanting trainers teach nothing that is not available through other trainers located in [[Outland]].\r\n==Reputation==\r\n''For help choosing between the Aldor and Scryer factions, see the article \"[[Comparison of Aldor and Scryer rewards|Comparison of Aldor and Scryer Rewards]].\"''\r\n[[Reputation]] gains with the Scryers correspond with a 10% greater loss of reputation with the Aldor, and often result in gains with the [[Sha'tar]]. Blood elves who have not yet pledged allegiance to either the Aldor and Scryers will automatically begin as with the Scryers and with the Aldor. However, blood elves may choose to side with the Aldor once the opportunity presents itself, and are not banned from doing so simply because of their race.\r\n====Until Honored====\r\nTurning in ten Firewing Signet to [[Magistrix Fyalenn]] in [[Scryer's Tier]] will grant +250 reputation with the Scryers. There is also a repeatable quest, Single Firewing Signet, which yields +25 reputation for each Signet ring turned in. These Signets drop from low-ranking [[Firewing]] members found at Firewing Point Northeast of Shattrath City. Once reaching status, however, the Single Firewing Signet quest becomes unavailable. If no other reputation quests are done, are required to go from Friendly to Honored, or signets from Neutral to Honored.\r\nIt is possible to submit Firewing Signets to gain rep more than is needed to obtain Honored. For example, if you are 25 rep points away from Honored, you can submit 10 signets and be 225 points into Honored. Once Honored, however, you can no longer submit Firewing Signets for rep.\r\n====Until Exalted====\r\nAt level 68, characters may start turning in Sunfury Signet. These drop from high-ranking members of the [[Sunfury|Sunfury Clan]] (i.e., blood elf [[mobs]] level 66 and higher). Although it is possible to turn in Sunfury Signets upon reaching status, it is recommended that one save these items until attaining status. For every ten Signets, characters will gain +250 reputation. Upon reaching it will take approximately to reach if reputation from no other source is earned.\r\n====Arcane Tomes====\r\nArcane Tome may be turned in at any time to Voren'thal the Seer inside the [[The Seer's Library]] on the [[Scryer's Tier]]. This yields +350 reputation per turn-in, plus Arcane Rune, a form of currency used to purchase shoulder enchants at the Scryer's bank. As with Sunfury Signets, it is possible to turn in the Arcane Tomes before reaching , but for the same reasons it is recommended that characters save them for until after attaining that status. Upon reaching it will take approximately 95 Arcane Tomes to go from to if reputation from no other source is earned. \r\n====Switching to Scryer====\r\nIt is possible to defect from the Aldor to the Scryers, though doing so destroys all reputation progress previously made with the Aldor. Players seeking to switch factions must find [[Arcanist Adyria]], a Scryer located in [[Lower City]]. She offers the repeatable quest Voren'thal's Visions, which requires characters to turn in eight Dampscale Basilisk Eye. This quest yields +250 reputation with the Scryers and -275 reputation with the Aldor per turn-in, and also provides +125 reputation with the Sha'tar if one is not yet with that faction. Voren'thal's Visions may be repeated until status is attained, at which time it becomes unavailable. \r\nAssuming one is with the Aldor and by the Scryers, it will take , or individual Dampscale Basilisk Eyes, to reach status with the Scryers. Once hitting status with the Scryers, one's reputation with the Aldor should have deteriorated almost halfway into .\r\n==Rewards==\r\n[[Arcanist Xorith]] and [[Haldor the Compulsive]] are reputation vendors who sell specialized [[Flasks]] only usable in [[raid]] zones to characters who are with the [[Cenarion Expedition]], the Sha'tar and the respective Scryer or Aldor faction. The flasks are only purchasable with [[Mark of the Illidari|Marks of the Illidari]], obtained from creatures in [[The Eye]] of [[Tempest Keep]], [[Serpentshrine Cavern]], [[Mount Hyjal]] and the [[Black Temple]].\r\nThe following Scryer reputation rewards can be purchased from [[Quartermaster Enuril]] in the Scryer Bank in southeast Shattrath City:\r\nThe following Scryer [[Augments|Inscription]] reputation rewards can be purchased from [[Inscriber Veredis]] in the Scryer Bank in southeast Shattrath City:\r\nAs of Patch 2.4, the epic pendants sold by Shattered Sun Offensive quartermaster Eldara Dawnrunner in Isle of Quel'danas have procs that only trigger when at exalted reputation with Aldor or Scryer. What procs exactly depends on the neckpiece and which faction you have chosen.\r\n==Quests==\r\nIf one has not yet chosen either the Aldor or the Scryers, complete A'dal and then City of Light. Completing these two quests will lead to two new quests, one to become with the Scryers, the other for the Aldor. Choose carefully! Even though characters can switch between factions as described above, it will take time.\r\n* A'dal\r\n** City of Light \r\nIf you are a blood elf you will not have A'dal quest available, do instead:\r\n* Haggard War Veteran\r\n===Netherstorm===\r\nThere are many quests for the Scryers concerning disrupting Sunfury operations and shutting down the [[manaforge]]s in [[Netherstorm]]. These quests can be obtained at [[Area 52]] upon achieving status. Also, on the Scryer Tier in Shattrath City characters can talk to Arcanist Savan who will provide the feeder quest Report to Spymaster Thalodien to talk to [[Spymaster Thalodien]] in Area 52.\r\n(Sum of reputation from below quests: +3995 with the Scryers/-4395 reputation with the Aldor)\r\n* Manaforge B'naar (+250/-275 reputation)\r\n** High Value Targets (+250/-275 reputation)\r\n** Shutting Down Manaforge B'naar (+250/-275 reputation)\r\n** Stealth Flight (+10/-11 reputation)\r\n** Behind Enemy Lines (+10/-11 reputation)\r\n** A Convincing Disguise (+250/-275 reputation)\r\n** Information Gathering (+150/-165 reputation)\r\n** Shutting Down Manaforge Coruu (+250/-275 reputation)\r\n** Return to Thalodien\r\n** Shutting Down Manaforge Duro (Scryers) (+250/-275 reputation)\r\n** Shutting Down Manaforge Ara (+250/-275 reputation)\r\n** Kick Them While They're Down (+250/-275 reputation)\r\n** A Defector (+75/-83 reputation)\r\n** Damning Evidence (+250/-275 reputation)\r\n** A Gift for Voren'thal (+350/-385 reputation)\r\n*** Bound for Glory (+150/-165 reputation)\r\n*** Turning Point (+1000/-1100 reputation)\r\n** Bloodgem Crystals (+250/-275 reputation)\r\n===Shadowmoon Valley===\r\nThere are also several Scryer quest chains (and a Scryer only Flight Path) at the [[Sanctum of the Stars]] in [[Shadowmoon Valley]]. These quests also require a reputation.\r\n(Sum of reputation from below quests: +2975 with the Scryers/-3272.5 reputation with the Aldor)\r\n* Tablets of Baa'ri (+250/-275 reputation)\r\n** Oronu the Elder (+250/-275 reputation)\r\n** The Ashtongue Corruptors (+250/-275 reputation)\r\n** The Warden's Cage (+75/-82.5 reputation)\r\n* The Ashtongue Broken (+250/-275 reputation)\r\n** The Great Retribution (+250/-275 reputation)\r\n* Karabor Training Grounds (+250/-275 reputation)\r\n** A Necessary Distraction (+250/-275 reputation)\r\n** Altruis (+75/-82 reputation)\r\n** Against All Odds \r\n** Against the Illidari \r\n** Against the Legion\r\n** Illidan's Pupil \r\n** The Book of Fel Names \r\n** Return to the Scryers (+75/-83 reputation)\r\n** Varedis Must Be Stopped (Scryer) (+1000/-1100 reputation)\r\n===Shattrath City===\r\nThere are four quests available in Shattrath City on the Scryer Tier for players to complete for reputation gains.\r\n* Report to Spymaster Thalodien (Feeds to the Area 52 Quest Line)\r\n* Firewing Signets (10 Signets, 250 reputation)\r\n** Single Firewing Signet (1 Signet, 25 reputation)\r\n** More Firewing Signets (10 Signets, 250 reputation)\r\n* Sunfury Signets (10 Signets, 250 reputation)\r\n** Single Sunfury Signet (1 Signet, 25 reputation)\r\n** More Sunfury Signets (10 Signets, 250 reputation)\r\n==Screenshots==",},
			["Scrying Orb (Magisters' Terrace)"] = { content = "The '''Scrying Orb''' is located in the [[Solar Virgil]] in [[Magisters' Terrace]].\r\n==Usage==\r\nUsing this device will give you a quick tour of [[Sunwell Plateau]]. It is the only device in-game that takes the camera off the player.\r\n<!--Doesn't exist in database sites",},
			["Scuttle Coast"] = { content = "The '''Scuttle Coast''' is a portion of the [[Great Sea]] off the east coast of [[Kalimdor]], mostly noted by travelers on the east coast of [[Durotar]] southeast of [[Razor Hill]] near [[Tiragarde Keep]]. The coast is littered with ships from [[Kul Tiras]], smashed upon the rocks as a result of the great battles fought between the [[orcs]] and Admiral [[Daelin Proudmoore]]'s fleet. The orcs are still salvaging bits and pieces of [[gnome]] technology from the stores of the ships.\r\nThe name may be in reference to either the large ships that have been scuttled just off shore, or to the [[crab]]s and [[makrura]]s that scuttle along the shore.",},
			["Scythetooth Raptor"] = { content = "'''Scythetooth Raptor''' can be found in [[Netherstorm]] in [[Eco-Dome Farfield]]. They can be tamed by hunters. If tamed by a hunter, they teach Bite 9 and Dash 3. At level 69, they are the highest leveled tameable raptors in the game.\r\n==Quests== \r\n==Drops == \r\n \r\n0.01% Chance of a [[rare]] drop.\r\n0.28% Chance of an [[Uncommon]] drop.\r\n0.08% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Scythe of Elune"] = { content = "The '''Scythe of Elune''' is an ancient thing, a twisted and gnarled branch of wood covered with runes that could be older than even the [[Kaldorei]]. [[Velinde Starsong]] was granted it from [[Elune]] (or maybe she only thought that it was a gift of Elune...), to fight against the [[demon]]s in [[Felwood]] and [[Ashenvale]]. By further channeling the energy of the Scythe, the barriers of time and space weakened, and she was able to draw the [[worgen]] into the world of [[Azeroth]]. First, they followed her into battle, and with their brutish strength at her command, they tore into the demons of Felwood. Later, she noticed, that though she had not summoned additional worgen, their numbers continued to increase. It was as though the Scythe no longer required her intervention for the summoning process. While searching for [[Arugal]] to ask him for help, she lost the Scythe within a cave in [[Duskwood]]. It is known, that the dark [[mage]] [[Morganth]] and [[Black Rider]]s from [[Deadwind Pass]] are now searching for it. The Scythe's current location remains unknown.\r\nsee also:\r\n* [[Jitters' Completed Journal]]\r\n* [[Velinde's Journal]]",},
			["Seaforium Booster"] = { content = "'''[Seaforium Booster]''' is a quest item only lootable by players on the quest Razzeric's Tweaking. It is also provided for the quest Safety First.\r\n==Source==\r\nThe '''[Seaforium Booster]''' is in a [[Gizmorium Shipping Crate|crate]] in a zeppelin crash site in [[Dustwallow Marsh]]. The crashed zeppelin is notoriously hard to find and get to. It is up against the mountains which lie on the eastern coast of [[Dustwallow Marsh]]. The section of mountains cradle the zeppelin crash like a backwards C. The area of the crash is called [[Beezil's Wreck]]. The seaforium booster can be found in a box near the crash. Coordinates (54,56).\r\n==As a Quest Objective==\r\n* Razzeric's Tweaking - this quest is available from Razzeric at [[Mirage Raceway]] in [[Thousand Needles]]. This quest is part of a chain that starts with Load Lightening.\r\n'''Objective:''' Retrieve the Seaforium Booster for [[Razzeric]] in the [[Shimmering Flats]].\r\n:Required for completion:\r\n:* Seaforium Booster\r\n* Safety First - this quest is available from Razzeric at [[Mirage Raceway]] in [[Thousand Needles]]. This quest is part of a chain that starts with Load Lightening.\r\n'''Objective:''' Bring the Seaforium Booster to [[Shreev]] in [[Gadgetzan]].\r\n:Required for completion:\r\n:* Seaforium Booster (provided)",},
			["Seaforium charge"] = { content = "An explosive created and used by an [[Engineer]] that will open [[Locked|locked]] [[door]]s, chests, and [[lockbox]]es depending on the level of [[Lockpicking]] skill required to open the lock. Only Engineers can use a Seaforium Charge.\r\nSeaforium Charges gained the ability to open chests and lockboxes in patch 2.1.0.\r\nIn general, a [[rogue]]'s lockpicking skill is more convenient, because seaforium charges are used up when a lock is opened.\r\nAn Engineer with some seaforium can be useful when there are no rogues around who can open the lock.\r\n==Background==\r\nSeaforium is a favorite of sappers everywhere. Dwarves developed this explosive as a safer alternative to the catastrophically dangerous fuels used by goblin sappers during the Third War. The material is putty-like in appearance and can be shaped or molded by anyone without risk of detonation. Seaforium only explodes if an external source (a detonator) provides a significant electrical surge. The detonator is typically attached to a length of copper wire so the operator can stand some distance away, preferably around a corner or behind some other sort of cover. The detonator can also be set to activate automatically, without the wire, after a preset delay period. Seaforium charges come in three basic sizes, small, medium, and powerful.\r\n===Seaforium Detonator===\r\nThis is a T-shaped plunger in a red box with lightning bolts on the side. Copper wires connect to the box to a seaforium charge. It is used to detonate a seaforium charge from a distance.\r\n==Types of charges==\r\n* Small Seaforium Charge (Engineering skill 100)\r\n* Opens items with a [[lockpicking]] skill of 150:\r\n** Workshop Door ([[Gnomeregan]])\r\n** Defias Gate ([[Deadmines]])\r\n** Strong Iron Lockbox\r\n** Sturdy Locked Chest\r\n** Battered Footlocker\r\n** Large Iron Bound Chest\r\n* Large Seaforium Charge (Engineering skill 200)\r\n* Opens items with a [[lockpicking]] skill of 250:\r\n** [[Scarlet Monastery]] Doors\r\n** [[Searing Gorge]] Gate\r\n** [[Blackrock Depths]] Doors\r\n** Eternium Lockbox\r\n** Reinforced Locked Chest\r\n* Powerful Seaforium Charge (Engineering skill 275)\r\n* Opens items with a [[lockpicking]] skill of 300:\r\n** [[Scholomance]] Door\r\n** [[Stratholme]] Gates\r\n** Crescent Door ([[Dire Maul]] North)\r\n** Wicker Chest\r\n** Large Mithril Bound Chest\r\n** Bound Fel Iron Chest\r\n* Elemental Seaforium Charge (Engineering skill 350)\r\n* Opens items with a [[lockpicking]] skill of 350:\r\n** [[Shattered Halls]] Door\r\n** [[Shadow Labyrinth]] Gate\r\n** [[The Arcatraz|Arcatraz]] Door\r\n** Khorium Lockbox\r\n** Bound Adamantite Chest",},
			["Seahorn"] = { content = "#redirect [[Fleet Master Seahorn]]", redirect = "Fleet Master Seahorn",},
			["Seal"] = { content = "A '''seal''' is an amphibious [[critter]] from [[Warcraft II]] and [[Warcraft III]]. They are usually seen frolicking in the waters or sunning on the coasts. They are also found in [[Northrend]].",},
			["Sealed Azure Bag"] = { content = "==Source==\r\n'''Sealed Azure Bag''' is [[pick pocket]]ed from Timbermaw Shamans in [[Azshara]].\r\n==Sealed Azure Bag as a quest objective==\r\nThis item is an objective of Sealed Azure Bag.",},
			["Sealed Letter (Dustwallow Marsh)"] = { content = "==Source==\r\nThis item drops from [[Apothecary Cylla]] in [[Dustwallow Marsh]].\r\nThis item is provided for\r\n* The Apothecary's Letter.\r\n* Signs of Treachery?\r\n==Sealed Letter as a quest objective==\r\nThis item is an objective of:\r\n* The Apothecary's Letter.\r\n* Signs of Treachery?",},
			["Sealed Tome"] = { content = "==Source==\r\nThis item is a container that can be found in the [[Guardian's Library]] in [[Karazhan]]. \r\n==Notes==\r\nLooting the object has one of two results:\r\n1) places one of four books in your inventory, which, when used, grant certain buffs for 60 minutes. Both the books and the buffs disappear when you leave Karazhan (and you of course lose the buff when you die).\r\n2) inflicts one of five debuffs.\r\n==Books (buffs)==\r\nOnly one book effect can be active on one player at the same time.\r\nThere are a bunch of them on a ledge right underneath the entrance (Private Library Door) to the [[Shade of Aran]] room.\r\nPossible buff books:\r\n*[[Torment of the Worgen]] - Chance to deal 85 additional shadow damage on ranged or melee attacks. Periodically turns you into a worgen.\r\n*[[Wrath of the Titans]] - Chance to deal additional damage on harmfull spells.\r\n*[[Redemption of the Fallen]] - Chance to summon a ghostly ally on healing spells.\r\n*[[Legacy of the Mountain King]] - Chance to increase your armor by 8000 and all magic resistances by 100 when struck in combat. Can stack.\r\nCurrently there is a bug with looting books that you have already in your inventory. The object appears as empty and then vanishes. A workaround is to let only people without any book loot the book objects, as the book items are tradeable.\r\n==Debuffs==\r\nAll five debuffs are called \"Curse of the Tampered Tome,\" but each is of a different debuff type and each affects a different stat.",},
			["Seals"] = { content = "#REDIRECT [[Seal (ability)]]", redirect = "Seal (ability)",},
			["Seals of the Pure"] = { content = "==Rank table==\r\n==Talent Overview==\r\n*The increase takes into account your +spell damage as of patch 2.1.",},
			["Seal (ability)"] = { content = "A '''seal''' is a short-term self-buff which boost the Paladin's power temporarily for two minutes. Additionally, Paladins can unleash these seals upon an enemy through the use of [[Judgement]]. Each type of seal will have a different effect when unleashed.\r\nSince patch 3.0.2 the Paladins seal does not disappear when unleashing the seals with a [[Judgement]]\r\nThe Seals provide the following buffs to the Paladin:\r\nSeal of Vengeance is available only to [[Alliance]] paladins; Seal of Blood is available only to [[Blood knight]]s.\r\nSee the to see what Seal produces the best results given your gear.\r\n==Seals and Judgements Hit/Crit mechanic==\r\nThe Seals and their Judgements have complex hit/crit mechanics, based on melee or spell type. After [[Patch 1.9.0| Patch 1.9.0]] Seals of Command, Justice, Light and Wisdom 'proc per minute' ([[PPM]]) and Judgements that place debuffs cannot be resisted.\r\n(*) It is unclear what are the exact PPM (proc per minute) for Seal of Light and Seal of Wisdom \r\n(**) This is a chance of the ability to trigger, not a chance to apply it. \r\n(***) [[Seal of Vengeance]] can crit only when the debuff is 5 times stacked in the target.",},
			["Seal Fate"] = { content = "''Never show weakness to a Rogue.''\r\n'''Seal Fate''' is a 25 point [[rogue]] talent located in the 6th tier of the [[Rogue_talents|Assassination Tree]].\r\n==Notes==\r\nThis ability is sought after mainly for fast Combo Point (CP) generation. It is great when used with [[Backstab]], [[Ambush]], or [[Mutilate]], as all of these moves have a high critical strike rate (through talents). It works well for both [[PvP]] and [[Raid]]ing. Also works well with [[dagger]]s, seeing as the above three combo point generators use daggers, which can lead to quick burst damage.",},
			["Seal of Ascension"] = { content = "'''The Seal of Ascension''' is a ring with several abilities that is obtained through a quest. Most importantly it allows access to the upper portion of [[Blackrock Spire]] (BRS). It also can be worn to protect you from one of [[Gyth]]'s special attacks as well as summon the spirit of [[Vaelastrasz]] to help you in the fight against [[Rend Blackhand]].\r\nThis item obtained from a short questline:\r\n*Seal of Ascension (1)\r\n**Seal of Ascension (2)\r\nIn order to begin the quest, one must acquire an Unadorned Seal of Ascension. The seal is a random drop off of mobs both inside and outside the BRS instace. The seal can be purchased and sold on the Auction House.\r\nOnce one has the Seal, enter [[Lower Blackrock Spire]] (LBRS). Go up the stairs, take a right. Jump down and through the passage on the left. There will be a wooden bridge ahead of you.\r\nLooking up on the left side, the group will see a single mob kneeling on a ledge. Walk to the end of the ledge, following it around and up an incline. What appears to be a regular mob is actually Vaelan in disguise. Upon coming into his aggro radius, he will cast a harmless spell on the group, allowing all to see Vaelan in his true human form. Any group member with an Unadorned Seal of Ascension in their inventory will gain access to the Seal of Ascension quest. \r\nNow collect the gems: The Gemstone of Bloodaxe drops from Overlord Wyrmthalak, the Gemstone of Smolderthorn drops from War Master Voone and the Gemstone of Spirestone drops from Highlord Omokk. The gems have a 100% drop rate, however ''keep in mind that these gems are of Uncommon quality and do NOT drop for all group members.'' \r\nReturn to Vaelan. Upon turning in Seal of Ascension, he will issue the quest Seal of Ascension (2) giving you the Unforged Seal of Ascension and an Orb of Draconic Energy.\r\nTravel to the [[Wyrmbog]] in [[Dustwallow Marsh]]. Once inside, locate Emberstrife. Place the unforged seal on the ground. Attack Emberstrife until the \"Emberstrife's will is starting to falter\" status message appears. Use the Orb of Draconic Energy on Emberstrife. Emberstrife is now under your command for a brief time. Cast his first spell to breathe frost on the seal. Loot the Forged Seal of Ascension from the seal.\r\nReturn to Vaelan in LBRS. Hand in the quest, and you will receive Seal of Ascension. \r\nCurrently, there is a bug with this quest, and you will be unable to turn it in unless you have a Unadorned Seal of Ascension on you. Either farm mobs until another one drops, or check the AH for one.\r\n==Summoning Vaelastrasz During Battle with Rend Blackhand==\r\nAt some point during the battle with the false warchief, [[Rend Blackhand]], you can use your Seal of Ascension to summon a shade of [[Vaelastrasz]] (looks like a ghostly red dragon), who will heal your entire group for 5000 HP as well as 'help' you in your fight against Rend. To do this, you just 'use' your Seal like you would any other item with a \"Use: do something\" tag on it, despite this not being obvious by looking at the ring's item description.\r\nThe tricky part is the timing of when you 'use' it. One tip is to add the ring to your action bar to keep fumbling to a minimum. As soon as Gyth dies use your ring and it should work properly.\r\nThree (3) minute cooldown on the 'use' of this item.\r\n==Theories On Summoning==\r\n* When [[Gyth]] does his 'nature' breath attack?\r\n* Right after [[Rend]] dismounts?\r\n* The summoning of Vael is slightly bugged, in that sometimes he will spawn and charge off into the following room (the one with Awbee). He won't aggro anything, but he can take up to 30 seconds to come back to the scene of the fight, by which stage it can be almost finished, thus rendering him largely useless. I tested it secretly during several UBRS PUGs, and it seems to bug the most when you cast it early, before Rend dismounts. I never had it bug if I used it just as Rend dismounted.\r\n==Other unknown info==\r\n* If multiple people have a Seal of Ascension, can the dragon be summoned twice?\r\n** No. Attempting to use the ring a second time, even by a different person, has no effect.\r\n* \"Chromatic resistance\" given to you when you \"use\" the ring? Does this only work when you summon Vaelastrasz or can you use it anywhere in the world? (Doesn't appear to do anything when used in Thunder Bluff)\r\n** Chromatic resistance is the name of several subtypes of buff you gain when wearing the ring, and get hit by one of Gyth's attacks. Depending on the type of the attack, you gain resistance to it for a brief period of time. You can have multiple buffs of CR, each one protecting against a different magic class, but the buff only lasts for 30 seconds.",},
			["Seal of Ascension (quest)"] = { content = "==Objectives==\r\nFind the three gemstones of command: The [[Gemstone of Smolderthorn]], [[Gemstone of Spirestone]], and [[Gemstone of Bloodaxe]]. Return them, along with the [[Unadorned Seal of Ascension]], to [[Vaelan]].\r\nThe Generals, as told to you by [[Vaelan]], are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe. \r\n* Unadorned Seal of Ascension\r\n* Gemstone of Smolderthorn\r\n* Gemstone of Spirestone\r\n* Gemstone of Bloodaxe\r\n== Description==\r\nAs you can see, the unadorned seal has three empty sockets. Each of those sockets must be filled with a gemstone representing the leadership's command. Finally, Overlord Wyrmthalak, master of the lower citadel, must forge the seal in the flames of the Black Dragonflight.\r\nUnderstand this, mortal: the chance that one of the three generals of the lower citadel would carry a gemstone at any given time is rare. You must be vigilant in your quest. Remain determined! \r\n== Progress==\r\nCourage and patience above all else, mortal! \r\n== Completion==\r\n<Vaelan's image blurs for a moment.>\r\n<The pieces that you had collected have disappeared.>\r\nThe Unforged Seal of Ascension is now ready. It is time for the final step. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*3300 [[XP]] (or 49 silver 50 copper at level 70)\r\n==Quest progression==\r\n#Seal of Ascension\r\n#Seal of Ascension (2)",},
			["Seal of Blood"] = { content = "''We Blood Knights; We whose lives are written in blood, both that of our enemies and of ourselves. We know great power comes to those willing to take it, and nothing comes without bloodshed. Thus do we always risk ourselves to wield our great strength.''\r\n==Alliance Paladin Counterpart==\r\nThis seal is '''''Horde only'''''. The Alliance's counterpart is [[Seal of the Martyr]].\r\n==Tips & Tricks==\r\n* Seal of Blood is the Horde's equivalent to [[Seal of the Martyr]], allowing the Paladin to deal a large amount of Holy damage with every hit. The downside to this, however, is that the Paladin also inflicts damage upon themselves. For PvE Retribution Paladins, this is actually beneficial because, with [[Spiritual Attunement]], the more that a paladin is healed the more mana they have available. However, in PvP, the backfire damage can be dangerous sometimes.\r\n* In numerous calculations from a retribution perspective, Seal of Blood has been proven to do significantly more damage than [[Seal of Command]] or [[Seal of Vengeance]]. The difference between Seal of Command and Seal of Blood is usually a margin of more than 15%.\r\n* This is '''NOT''' a good tanking seal. The main reason is that it depends on physical damage of the weapon to be effective but most of the other tankadin threat generating abilities need spell damage. If a Horde paladin stacks strength and attack power and uses a melee dps weapon in order to use this seal, either his threat from other abilities or his survivability suffers. Synergy effect with [[Spiritual Attunement]] is not a valid reason to use this seal, as there are many [[Paladins as tanks|proper ways to handle mana deficit situations]] for tankadins.\r\n==Notes==\r\n* The Seal is based on the melee mechanics for hit and crit.\r\n*The seal only scales with weapon damage, not spell damage. It therefore heavily favors melee-geared Paladins (mostly Retribution Paladins), rather than spelldamage-geared Paladins. Note that the Judgement does scale with spell damage.\r\n*This seal is counted as a second melee strike in terms of game mechanics, meaning that the damage it deals can [[miss]], be [[dodge]]d, be [[block]]ed, and be [[Parry|parried]]. Since it deals non-physical damage, it can also be partially resisted when used against mobs that are higher level than the player. It will NOT activate [[Judgement of Light]] and [[Judgement of Wisdom]] nor any other weapon proc (fiery, mongoose, life steal procs, etc). \r\n*When using a fast 2-hander, this seal deals more DPS than [[Seal of Command]]. Also, the fact that it can crit makes it shine in a raid situation since [[Vengeance (paladin talent)|Vengeance]] is similar to a fury warrior's [[Flurry (warrior talent)|Flurry]] in terms of how it increases the paladin's DPS.\r\n*[[Blessing of Sanctuary]] will not mitigate backlash damage caused by this seal. Neither will [[Divine Shield]] make you immune to this damage. The proc effect from [[Uther's Strength]] will absorb this damage, and it seems [[Improved Righteous Fury]] or [[Spell Warding (Paladin Talent)|Spell Warding]] might help mitigating this damage. Killing yourself with this damage counts as a [[suicide]].\r\n*Seal of Blood's damage inflicted to the user is not capable of causing a [[Reckoning]] proc.\r\n*The Paladin [[Paladin talent|Retribution]] talents [[Sanctity Aura]], [[Vengeance (paladin talent)|Vengeance]], and [[Crusade]] all affect the damage dealt by this seal (prior to patch 2.1.2 there was a bug that would cause it to doubly affect the returned damage component of this seal, making the returned damage more than the 10% stated on this seal's tooltip).\r\n* In parses, the % crit may sometimes seem off. This is normally because of the backlash (self-damage), which cannot crit. Generally, in these cases you can double the posted crit rate to determine the actual crit rate.",},
			["Seal of Command"] = { content = "==Overview==\r\nSeal of Command is a talent in the Retribution tree, that requires 10 talent points invested in the tree to take it. You can apply [[Judgement of Command]] to your target if you use the spell [[Judgement]] while Seal of Command is active on you to deal Holy damage, which is increased when the enemy is stunned or incapacitated.\r\nSeal of Command is considered a Magic buff, and can be dispelled by Priests or purged by Shamans.\r\nSince Patch 1.11, Seal of Command proc will have approximately 0.5 second delay before the animation begins and the Holy damage is incurred, instead of having the proc occur instantly with the swing of the attack. This is considered a good change, since if the normal swing is a critical strike and [[Vengeance]] is triggered, the Seal of Command proc will be affected by the buff.\r\nBefore Patch 1.9, Seal of Command had 5 procs per minute but dealt 100% of normal damage, and its judgment gave a debuff that incurred Holy damage on the enemy whenever they were stunned.\r\nAs of Patch 3.0.2, Seal of Command procs on abilities as well as melee on separate ppm charts, significantly increasing the dps of the ability. In addition Seal of Command now only has only 1 rank costing 14% of base mana. The damage of SoC was also reduced to 56% of main weapon damage.\r\n==Damage==\r\nSeal of Command procs \"per minute\" (ppm), rather than per hit - it will proc an average of 7 times per minute. So you get the same amount of procs no matter your weapon speed, but a slower, high damage-per-strike weapon will do more Seal of Command damage per hit, on average, than a faster, low damage-per-strike weapon rated at the same DPS.\r\nSeal of Command receives 20% coefficient from normal +spell damage stats, and 32% from Attack Power.\r\nSeal of Command can only proc from the first attack on a [[Reckoning]] bombing.\r\nThe actual attack made when Seal of Command procs is resolved as a separate melee special-attack that deals holy damage. It is resolved identically to any Instant Attack — it can miss, be dodged, be parried, be blocked, and will do double damage on a crit (rather than 1.5x damage as a normal spell crit would).\r\n==Usage==\r\nAlthough unreliable due to the fact that it is based on a chance to proc on every melee attack, Seal of Command is most Alliance Retribution Paladins' choice of seal to DPS with because it scales with melee DPS and crit chance.\r\nSeal of Command is typically used with slow, hard-hitting two-handers, although some uses with certain one-handers is not too uncommon, just slightly less reliable. As described below, slower weapons have a better chance of triggering a Seal of Command proc (a 3.8 speed weapon has a 44.3% chance and a 2.0 speed has 23.3% chance).\r\nA Retribution Paladin would be choosing gear with +strength (for DPS) and +agility/+critical strike (for increased crit chance).\r\n==Seal of Command and Seal of Blood comparison==\r\n[[Seal of Blood]] (SoB) for the Horde/ [[Seal of the Maytyr]] (SoM) for the Alliance are an alternative to SoC damage. It works very similar to Seal of Command except it procs on every hit and deals a small amount of damage back to the paladin equal to 10% of the damage done. The overall damage output of Seal of Blood is comparable to Seal of Command. The main difference is that SoB/SoM scales with Haste where SoC does not. SoB/SoM does a flat 28% damage on hit while SoC does an average of 36% (with a 3.8 speed weapon). With 12.86% haste these abilities become equal. Rather than gearing haste, since Windfury now gives a 20% increase to melee haste, its best just to change seals based on raid composition unless you can be 100% sure you will always have an enhancement Shaman. (Or possibly carry two sets of gear around)\r\n==Seal of Command and Seal of Righteousness comparison==\r\nAnother seal to consider is [[Seal of Righteousness]] which does not scale with melee DPS but is more reliable (procs on every attack).\r\nA quick way to compare the two is to record the Holy damage per hit for each and then adjust the damage for Seal of Command: damage = recorded damage * (1+crit chance) * proc rate. For example if Seal of Command hits for 650 average and the weapon speed is 3.5 (40.8% chance) and the melee crit chance is 20% then: damage = 650 * 0.408 * 1.2 = 318.24. If Seal of Righteousness also hits for around 320 then the two are quite similar (for your level, gear and build), with the added advantage that Seal of Righteousness will always proc.\r\n==Weapon speed and proc rate for Seal of Command==\r\n14 AP = 1 dps\r\nDamage Per Hit = dps * Weapon Speed\r\nTotal Damage = ( AP / 14 ) * Weapon Speed\r\nThis caused some weapons to be far better than intended ([[Arcanite Reaper]]) and others far worse ([[Destiny]]). They added a normalized weapon speed (1.7 for daggers, 2.4 for 1h weps, 3.3 for 2h weps) so that fast, high dps weapons weren't outdone by slow, low dps weapons merely because of speed. Seal of Command (and WindFury) were not normalized, and retain their weapon speed.\r\nSoC is normalized on proccing about 7 times per minute. This means that you get more out of it with a high top end damage weapon (each extra swing will mean more). As a side effect, is also makes it more reliable, as the slower the weapon, the higher the chance to proc (but still only about 7 times per minute). The formula for SoC proc rate is:\r\n[\r\n7 / ( 60 / Weapon Speed )\r\nSo a 2.0 speed weapon would proc 23.33% of the time [ 7 / (60 / 2) ]. A 3.0 speed weapon would proc 35% of the time [ 7 / (60 / 3) ]. The nice slow 3.8 speeds have a ~44% chance to proc [ 7 / (60 / 3.8) ].\r\nNote that the Weapon Speed used in this formula is the weapon's speed ''after'' modification for Haste Rating. If you are using a base 3.0 speed weapon and have enough Haste Rating to increase your attack speed by 5% then the Weapon Speed used in the formula will be 2.857.",},
			["Seal of Justice"] = { content = "''\"A Paladin's justice is a thing from which no foe can escape.\"''\r\n===Functionality===\r\nThe '''Seal of Justice''' will stun the enemy about 4-5 times a minute, although the stun is random and not controlled. There are diminishing returns with multiple uses of the stun, with the target becoming immune after the third.\r\n===Judgement===\r\nThis seal's [[judgement]], '''Judgement of Justice''', is very useful to stop runners, especially in tight areas such as in the [[Scarlet Monastery]]. Judging the first rank of this seal does not do anything in PvP. However, the second rank, obtained at level 48, limits the movement speed of the judged player and is not considered a movement impairing effect, meaning acts such as shape shifting and [[Blessing of Freedom]] will not remove it. This prevents a player from going above their normal run speed. Thus, for instance, a [[Druid]] who is affected by the Judgement will not go any faster than the normal run speed if they shift into [[Travel Form]], a [[Rogue]] who uses [[Sprint]] will receive no speed boost, and any player riding a [[mount]] will receive no speed bonus from doing so.",},
			["Seal of Light"] = { content = "The '''Seal of Light''' fills the Paladin with the spirit of light for 2 min. Only one Seal can be active on the Paladin at any one time.\r\nUnleashing this Seal's energy will judge an enemy instantly. Only one Judgement per Paladin can be active at any one time.\r\n===Tactics===\r\nThe Seal of Light will help keep a Paladin healed while attacking, but also is useful in raid situations when used as a [[Judgement]]. Having an enemy judged with Light will allow all classes to basically heal themselves while engaging in melee attacks, particularly useful for [[Rogue]]s and [[Warrior]]s (especially [[Main Tank]]s).\r\n===Proc rates===\r\n* For Seal of Light: The proc rate for the healing done by Seal of Light seems to be based on an average number of procs per minute, rather than a fixed proc rate per strike. Therefore, while under Seal of Light, each attack the paladin makes with a slow weapon has a greater chance for the healing effect to proc than if the paladin were attacking with a fast weapon. The average amount of healing per minute from the Seal of Light buff is therefore independent of weapon speed.\r\n* For Judgement of Light: The proc rate appears to be a fixed chance of around 50% per strike, regardless of the attacker's weapon speed. Therefore, attacking a target that has the Judgement of Light debuff in place with a ''slow'' weapon will generate less healing per minute than attacking with a fast weapon.",},
			["Seal of Righteousness"] = { content = "''\"If a Paladin knows his cause is just and potent, his weapon follows suit.\"\r\n==Additional Holy Damage==\r\nHoly damage is added per melee hit. This damage is constant, and does not have any critical effect. The additional damage from the Seal changes with every type of weapon, and the tooltip values are updated to reflect it. Total damage done by the Seal is moderately normalised to keep the damage on par over all weapon types. Generally, more damage from the Seal is added when using slower weapons than fast ones.\r\nAdded Holy damage for a one-handed weapon\r\n= 0.85 * (coeff * MWS / 100) + 0.03 * (MW + mw) / 2 - 1\r\nAdded Holy damage for a two-handed weapon\r\n= 1.2 * (coeff * MWS / 100) + 0.03 * (MW + mw) / 2 + 1\r\nWhere:\r\ncoeff = coefficient as per tooltip (depends on spell rank, see table above)\r\nMWS = main weapon speed\r\nMW = maximum weapon damage\r\nmw = minimum weapon damage\r\n==Judging==\r\nAs with all other [[Seal]]s, '''Seal of Righteousness''' can be [[Judgement|judged]] on a hostile target. When removed from the Paladin, the Judgement will do a certain amount of holy damage. See [[Judgement of Righteousness]] for more.\r\n==Talent improvements==\r\nThe damage done by the Seal can be increased by up to 15% with the talent [[Improved Seal of Righteousness]] (3% over 5 ranks). This damage is added after additional damage is calculated from +spell damage gear.\r\n==Tips and Tactics==\r\nApply [[Judgement of the Crusader]] to your target while using Seal of Righteousness for even more damage. Judging Seal of Righteousness will not remove the Judgement of the Crusader.\r\n[[Retribution]] Paladins: don't use Seal of Righteousness. Use [[Seal of Command]].\r\n===Spell damage coefficients===\r\n9.2% per 1.0 weapon speed, One-handed Seal of Righteousness\r\n10.8% per 1.0 weapon speed, Two-handed Seal of Righteousness\r\n===Attack Power===\r\nAttack Power does increase the damage done by a very small amount because the formula does use the final weapon damage not the base weapon damage. Using max rank Blessing of Might with a lvl 70 two-handed weapon you will get a difference of ~1-2 damage per hit.\r\n===Tooltip Mechanics===\r\nThe added Holy damage per hit as stated inside the tooltip, equals:\r\n cond( eq(HND,1), 0.85 * (2610.43 * MWS / 100) + 0.03 * (MW + mw) / 2 - 1,\r\n 1.2 * (2610.43 * MWS / 100) + 0.03 * (MW + mw) / 2 + 1)\r\n(This is from the tooltip for the highest rank of Seal of Righteousness. The constant 2610.43 differs with spell rank and can be seen in the table at the beginning of this page.)\r\nHND = weapon handedness (1 or 2)\r\nMWS = main weapon speed\r\nMW = maximum weapon damage\r\nmw = minimum weapon damage\r\ncond() and eq() are programming logic terms used inside the tooltip. eq() will check equality of HND (handedness of weapon) against the value 1, and returns a true or false value. cond() will then check this result, and if true, parses the first part of the formula. If false (HND = 2, which is not equal to 1), then it parses the second part of the formula.\r\nThe Formula above is only accurate at lvl 66, at lvl 70 the damage is slightly higher.\r\none-handed-weapon : +4.5 (estimated)\r\ntwo-handed-weapon : +9 (estimated)\r\nBecause the Spell increase with the level of the caster.",},
			["Seal of the Crusader"] = { content = "''\"A Crusader's judgement means death to his foes and strength unto his allies.\"\r\n'''Seal of the Crusader''' grants the Paladin a buff that increases his [[Attack Power]] and attack speed, but reduces damage done per swing. \r\n==Judgement==\r\nAs with other [[Seal]]s, '''Seal of the Crusader''' can be [[Judgement|judged]] on a target, afflicting them with '''Judgement of the Crusader''', a debuff that increases the holy damage done to that target.\r\n==Talent Improvements==\r\n[[Improved Seal of the Crusader]] (3 ranks) increases the critical strike chance of all attacks against a target afflicted by Judgment of the Crusader by 1% per rank. [[Sanctified Seals]] also increases the critical strike chance of all melee and spell attacks by 1% and decreases the chance for seals to be dispelled by 33% per point.\r\n==Tips and Tactics==\r\n*Using [[Seal of Command]] or [[Seal of Righteousness]] after applying '''Judgement of the Crusader''' to your target will yield consistently higher damage. Judging these two Seals will not remove the Judgement of the Crusader.\r\n*Seal of the Crusader is '''NOT''' a good seal for DPS or tanking paladins. Although it increases your attack speed, it makes each hit deals less damage. So its real benefit in damage output is the additional attack power it provided. Obviously, this means this seal don't scale with your gear, unlike [[Seal of Command]], [[Seal of Blood]] or [[Seal of Righteousness]]. Seal of the Crusader is only good if you have extremely low attack power. This is the reason why no experienced paladins with reasonable gear use Seal of the Crusader. \r\n*While Seal of the Crusader is mostly useful for its judgement, the seal itself can be helpful when levelling weapon skill, espescially on slow two-handed weapon types.\r\n*Using Seal of the Crusader after applying [[Judgement of Light]] or [[Judgement of Wisdom]] boosts the rate of health or mana generation of the judgements.\r\n==Improvements to Judgement of the Crusader==\r\nCertain pieces of gear can increase the power of this judgement, effectively allowing one paladin to use gear specialised in delivering the judgement and another to judge something else, but allowing both paladins (and even priests, with [[Smite]], [[Holy Nova]] and [[Holy Fire]]) to receive the benefit from the improvements to Judgement of the Crusader. These bonuses also receive bonuses from the talent [[Improved Seal of the Crusader]].\r\n===Gloves===",},
			["Seal of the Dawn"] = { content = "'''Seal of the Dawn''' is a [[trinket]] that serves as an [[Argent Dawn Commission]] and increases [[attack power]] against undead.\r\n==Source==\r\nSeal of the Dawn is a quest reward from the quest [[Quest:The Active Agent|The Active Agent]] which starts with [[Betina Bigglezink]] at [[Light's Hope Chapel]]. To complete the quest, you must turn the following item to Betina Bigglezink:\r\n*1 [[Scourge Data]]\r\n==Notes==\r\nIf you destroy the Seal of the Dawn, talk with Betina Bigglezink to choose again between '''Seal of the Dawn''' and [[Rune of the Dawn]].",},
			["Seal of Vengeance"] = { content = "''\"Remember, Arthas, we are paladins. Vengeance cannot be a part of what we must do. If we allow our passions to turn to bloodlust, then we will become as vile as the Orcs.'' &ndash; [[Uther the Lightbringer]]\r\n==Horde Paladin Counterpart==\r\nThis seal is '''''Alliance only'''''. The Horde's counterpart is [[Seal of Blood]].\r\n==Tips & Tricks==\r\nThis is the Alliance's equivalent to the Horde's [[Seal of Blood]]. Primarily, it is meant as a tanking seal. It allows the paladin to put stacking, Damage Over Time threat on a target.\r\nThis is very useful while tanking, as it allows the paladin to switch targets while still maintaining aggro, and it allows the paladin to generate instant threat in the event of a threat wipe. Note, however, that until many charges have built up, the amount of damage it deals is not enormously high and thus neither is its threat. As a result, a tanking paladin may prefer [[Seal of Righteousness]] (especially when coupled with a fast attack speed weapon) to build threat at the beginning of fights.\r\nIt can also be useful in PVP against [[rogues]] who use [[Vanish]], as the Damage Over Time component will unstealth them. It combines well with [[Reckoning]], as the extra attacks may also apply it.\r\nThe debuff will stack up to five times on the target and will last the full fifteen seconds, remaining even after a paladin (or multiple paladins) [[Judgement of Vengeance|judges]] the Seal. If multiple paladins attack the same target with this Seal, it will only stack up to five with no further debuffs being applied, however, doing so will keep the stacks up, allowing each of the paladins to each Judge for the full effect.\r\nThe debuff has a proc rate of 20 procs per minute, and will not crit (due to its damage over time nature). So it will always proc if you use a 3.00 or slower attack speed weapon (not counting misses/parries/dodges). This seal is listed as magic, not melee so it can not miss, but it can, however, be resisted.\r\n==Patch 2.2.0==\r\nAs of [[Patch 2.2.0]], Seal of Vengeance deals a small amount of Holy Damage if it strikes a target with 5 stacks of the debuff already applied. In addition, the DoT effect of the seal had its duration increased to 15 seconds.\r\n==Patch 2.3.0==\r\nAs of [[Patch 2.3]]: ''The bonus damage this ability dealt when the debuff is fully stacked on the target was incorrectly too low. It is now increased.'' <strike>Also, ''Vengeance (Retribution) duration increased from 15 to 30 seconds.''</strike> Coupled with the [[Precision (Paladin talent)|Precision talent change]] to increase spell hit as well, SoV may become part of an alliance prot/ret paladin's rotation.\r\nEditor's Note: The change to Vengeance in patch 2.3.0 applies not to the Paladin's Seal of Vengeance, but to the tier 6 Retribution Talent Vengeance, which gives a bonus to all damage dealt by spells and abilities for 30 sec after you deal a critical strike. The old duration of this buff was 15 seconds. The only change to the Seal of Vengeance in 2.3.0 was the change to the bonus damage it deals when the debuff is fully stacked on the target. The name of the debuff applied to the enemy by the Seal of Vengeance is not \"Vengeance\", but \"Holy Vengeance\".",},
			["Seal of Wisdom"] = { content = "==Rank table==\r\n==Tips & tricks==\r\nThe '''Seal of Wisdom''' will help keep a Paladin up on mana, but really shines in raid situations when used as a [[Judgement of Wisdom|Judgement]]. Having an enemy judged with Wisdom will allow all classes with mana pools to regen mana by simply wanding or auto-attacking the judged target.",},
			["Seal of Wrynn"] = { content = "==Source==\r\nThis item is a quest reward from An Audience with the King.",},
			["Searing Blade"] = { content = "'''Leaders:''' [[Bazzalan]] and [[Jergosh|Jergosh the Invoker]]\r\n'''Secondary Leaders:''' [[Taragaman the Hungerer]]\r\nThe '''Searing Blade''' is an organization that formed after the founding of [[Durotar]]. The Searing Blade is merely another branch of the [[Shadow Council]] attempting to usurp [[Thrall]]'s new [[Horde]]. They are led by the [[satyr]] [[Bazzalan]] and the [[warlock]] [[Jergosh]]. \r\nThe [[Burning Blade]] and [[Argus Wake]] are the Searing Blade's sister groups. \r\nThe Searing Blade has taken up residence in [[Ragefire Chasm]], a network of caverns beneath [[Orgrimmar]] secretly attempting to subvert innocent members of the Horde.",},
			["Searing Blade Clan"] = { content = "#REDIRECT [[Searing Blade]]", redirect = "Searing Blade",},
			["Searing Collar"] = { content = "==Source==\r\nThis item drops from:\r\n* [[Burning Blade Cultist]] in [[Durotar]]\r\n* [[Burning Blade Fanatic]] in [[Durotar]]\r\n* [[Burning Blade Thug]] in [[Durotar]]\r\n* [[Burning Blade Neophyte]] in [[Durotar]]\r\n* [[Burning Blade Apprentice]] in [[Durotar]]\r\n==Searing Collar as a quest objective==\r\nThis item is an objective of Skull Rock.",},
			["Searing Elemental"] = { content = "'''Searing Elemental''' can be found in [[Blade's Edge Mountains]].\r\n==Drops==\r\n \r\n0.00% Chance of a [[epic]] drop.\r\n0.00% Chance of a [[rare]] drop.\r\n0.03% Chance of an [[Uncommon]] drop.\r\n0.00% Chance of a [[common]] drop.\r\n0.01% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created.",},
			["Searing Golden Blade"] = { content = "'''Searing Golden Blade''' is a dagger that provides an increase to damage done by fire spells.\r\n==Source==\r\nSearing Golden Blade is crafted by [[Blacksmithing|Blacksmiths]] with a skill of 190.\r\nThe components are:\r\n*10 [[Steel Bar]]s\r\n*4 [[Gold Bar]]s\r\n*2 [[Elemental Fire]]\r\n*2 [[Heavy Leather]]s\r\nPlans: Searing Golden Blade are a [[world drop]].",},
			["Searing Gorge"] = { content = "The '''Searing Gorge''' is a [[contested]] [[zone|region]] in southern [[Khaz Modan]]. It is home to a group of exceptionally stout [[Dark Iron dwarf|Dark Iron dwarves]] called the [[Thorium Brotherhood]], who have split from the [[Dark Iron clan]].\r\n==History==\r\nJust as [[Blackrock clan|Blackrock]] [[orc]]s and their allies dominate [[Burning Steppes]] in modern day, so Dark Iron dwarves dominate this dark, mountainous area, alongside their [[war golem]]s and their [[elemental]] masters.\r\nThe Searing Gorge was presumably once a verdant valley, but the landscape was obliterated in a massive explosion over 200 years ago. In the [[War of the Three Hammers]], the leader of the Dark Iron dwarves, [[Sorcerer-Thane Thaurissan]], sought to summon a supernatural minion that would turn the tide of the war back to his favor. He and seven of his most trusted and powerful dwarves called upon the ancient powers sleeping beneath the world. To their surprise, the creature that emerged was more terrible than any nightmare they could have imagined: The ancient Firelord [[Ragnaros]].\r\nWith the Firelord's awakening a new volcano, [[Blackrock Mountain]], erupted out of the mountain ridge, forever blackening the surrounding lands and reducing the Dark Iron capital of [[Ruins of Thaurissan|Thaurissan]] to rubble. The steppes to the south came to be known as the [[Burning Steppes]], and the ravaged valley to the north the Searing Gorge.\r\nUpon completion of their new [[Shadowforge City|capital city]], the Dark Iron sought control of land for their filthy, industrious works. They looked directly to the gorge north of their mountain: The Bronzebeard clan's low military presence, scarce population, few settlements, and high vulnerability made the valley a clear choice. The Dark Iron army soon invaded the Searing Gorge, overrunning the Bronzebeard's garrisons and forcing them to retreat to Loch Modan and seal the [[Stonewrought Pass]] behind them. The Dark Iron turned their focus to a very large scale digging operation at the bottom of the blackened valley. The giant excavation site came to be known as [[the Cauldron]]. Within the Cauldron is the [[Slag Pit]], an underground mining site rich with multiple [[ore]]s. The labor is mainly done by slaves, who are for the most part of captured enemies.\r\nThe [[Stonewrought Pass]] remained locked down for many years, guarded by one [[Mountaineer Pebblebitty]] in recent days. The mountaineers turned away anyone seeking passage, so adventurers trying to enter the gorge could only come by way of either the [[Blackrock Spire]] or the [[Badlands]] trail south of [[Kargath]]. Records show that one adventurer was indirectly rewarded a [[Key to Searing Gorge]] by [[Curator Thorius]] of Ironforge for killing a kodo named [[Margol the Rager]], the bane of every archaeologist that ever set foot in the Searing Gorge.\r\nMore recently, the events of the [[Cataclysm (event)|Cataclysm]] prompted the mountaineers to unlock the passage and begin allowing adventurers to travel at their own risk... Mountaineer Pebblebitty remains, still trying to turn adventurers away.\r\nPrior to the start of the [[invasion of Outland]], the Searing Gorge was invaded by a group of [[Burning Legion]] [[demon]]s led by [[Highlord Kruul]].\r\n===Dungeons and raids===\r\nThere are actually no instances in the Searing Gorge. However, [[Blackrock Mountain]] lies between it and the [[Burning Steppes]]. It is home to [[Blackrock Depths]] (level 52-60 dungeon), [[Blackrock Spire]] (level 54-60 dungeon), [[Molten Core]] (level 60 raid), [[Blackwing Lair]] (level 60 raid), [[Blackrock Caverns]] (level 80-83 dungeon), and [[Blackwing Descent]] (level 85 raid).\r\n===== [[Flight path]]s from [[Thorium Point]]=====\r\n* [[Stormwind]], [[Elwynn Forest]]\r\n* [[Ironforge]], [[Dun Morogh]]\r\n* [[Thelsamar]], [[Loch Modan]]\r\n* [[New Kargath]], [[Badlands]]\r\n* [[Iron Summit]], Searing Gorge\r\n* [[Morgan's Vigil]], [[Burning Steppes]]\r\n* [[Flame Crest]], [[Burning Steppes]]\r\n===== [[Flight path]]s from [[Iron Summit]]=====\r\n* [[Thorium Point]], Searing Gorge\r\n* [[Flamestar Post]], [[Burning Steppes]]\r\n==Notable characters==\r\nSearing Gorge is home to several characters of note. At Thorium Point, [[Hansel Heavyhands]] seeks aid in the battle against the golems, spiders, and incendosaurs of the region. [[Master Smith Burninate]] attempts to create fiery flux with the help of trustworthy individuals. And from his guarded spot nearby, [[Velarok Windblade]] sends bold adventurers into the holdings of the Dark Irons in an attempt to burn down all of their sentry towers.\r\n==Resources==\r\n*[[Herb]]s\r\n**[[Firebloom]]\r\n**[[Sungrass]]\r\n*[[Ore]]\r\n**[[Gold Vein]]\r\n**[[Mithril Deposit]]\r\n**[[Truesilver Deposit]]\r\n==Wild creatures==\r\n*[[Fire elemental]]s\r\n*[[Golem]]s\r\n*[[Incendosaur]]s\r\n*[[Lava elemental]]s\r\n*[[Felsteed]]s\r\n*[[Spider]]s\r\n*[[Thunder lizard]]s\r\n==Before ''Cataclysm''==\r\nPrior to ''[[World of Warcraft: Cataclysm|Cataclysm]]'', the Alliance entrance to the Searing Gorge in Loch Modan was locked. Players had to obtain the [[Key to Searing Gorge]] via a questline culminating in [[At Last!]], although rogues with lockpicking of 225 could simply pick the doors, and players (especially Horde) could always enter through the Badlands. With the Cataclysm, the key and the quest to obtain it have been removed, and the entrance is now unlocked.\r\nThe zone was also changed from a level 43 - 52 zone to one suited to level 47 - 51 characters.\r\n===History===\r\n300 years ago when the [[Dark Iron clan|Dark Irons]] summoned [[Ragnaros]] it caused a volcanic explosion that devastated the surrounding land, including the Burning Steppes to the south. Since that time, the region has been the wasteland that it is today.\r\nNo people call the Searing Gorge home, though the land falls within Khaz Modan and therefore is under the purview of the [[Ironforge (kingdom)|Ironforge]] [[Dwarf|dwarves]]. The dwarves have many other worries at the moment, so odds are the Searing Gorge will remain untamed for years to come, especially since there is little to no reason to reclaim it.\r\nA group of [[Stonegullet]] [[ogre]]s barricades the road leading south to Blackrock Spire, demanding tribute from all wishing to pass — and the three [[black drake]]s with them ensure that all travelers pay the toll.\r\n===Geography===\r\nThe Searing Gorge is barren and hot. The ground is scarred with fissures and dotted with broken rock, the weather hot and dry. It lies south of [[Dun Morogh]], west of the [[Badlands]], and immediately north of [[Blackrock Spire]] and the [[Burning Steppes]]. Shattered crags and jagged chasms are the only features of note, and few landmarks exist off the road to guide a straying traveler. [[Rock golem]]s and [[Dark Iron dwarf|Dark Iron dwarves]] roam it.\r\nNo settlements stand here, and few important sites exist. The journey from Khaz Modan to Azeroth (and vice versa) is long and dangerous.\r\n==Notes and trivia==\r\n*Players taking the flight to Ironforge from Stormwind can observe many subzones of this area.\r\n*If you were to die in one of the Blackrock Mountain instances, it would take you to the Thorium Point graveyard. It is convenient as it is not far from the [[flight point]].\r\n*[[The Charred Oak]] was once located here, overlooking the [[Cauldron]].\r\n==See also==\r\n*[[Gadgetzan Times/Jetsett's Guide to Azeroth (2)]]",},
			["Searing Infernal"] = { content = "[[Searing Infernal]] is found in Ashenvale at Felfire Hill. It is immune to fire spells, but has no other abilities.\r\n==Quests==\r\n* Slaying 6 [[Searing Infernal|Searing Infernals]] is an objective of the quest Destroy the Legion.",},
			["Searing Pain"] = { content = "==Overview==\r\n \r\n'''''\"Pain! Pain! Pain!\"'''''\r\nSearing Pain is a [[Fire]]-based [[Direct Damage|direct damage]] spell for Warlocks. It is the main attack spell for Warlocks tanking end-game bosses due to the added threat, and for the same reason is not generally used for dps.\r\n==Functionality == \r\n===Use===\r\n*Cast Time: 1.5 sec.\r\n*Tree, School: Destruction, Fire\r\n*Type: Single Target Direct Damage\r\n*Range: 30 yards\r\n*Cooldown: N/A\r\n===Talents===\r\n*[[Improved Searing Pain]], [[Aftermath]], [[Cataclysm]], [[Demonic Sacrifice]] (Imp), [[Devastation]], [[Destructive Reach]], [[Emberstorm]], [[Master Demonologist]] (Succubus), [[Ruin]]\r\n===Notes===\r\n*It causes 100% extra [[threat]].\r\n===Description===\r\n*Spell description: \"''Inflict searing pain on the enemy target, causing X to Y Fire damage. Causes a high amount of threat.''\"\r\n==Tips and Tactics==\r\n*In [[PvP]], players may favor it over [[Shadow Bolt]] due to its low casting time and thus opportunistic nature against moving targets. It also doesn't leave a telltale trail that gives away the caster's location.\r\n*In [[PvE]], the spell has limited uses due to its extra threat. However, the ability to draw hate from a mob may be useful if you are trying to distract the mob from your pet or another player. Against certain fights (See: [[Shade of Aran]]) where DPS and survivability are needed, and there is no set threat table, this spell also works well.",},
			["Searing Totem"] = { content = "'' Summons a Searing Totem with 5 health at your feet for '''YY''' (see the [[Searing Totem|Duration]] by rank level) that attacks an enemy within 20.0 yards for '''XX''' Fire damage (see [[Searing Totem|Description]] by rank level) every 2 seconds.'' \r\n''The Power of Fire is great indeed, only in great times of need is the power of Fire called to the aid of the Shaman. The Totem spits fireballs at his/her enemies burning and causing destruction wherever the Shaman chooses.''\r\n==Functionality==\r\nThe Searing Totem is a reliable source of extra damage, and is useful in situations where the other two damage totems ([[Fire Nova Totem]] and [[Magma Totem]]) aren't.\r\nWhen dropped, the Searing Totem will randomly select an enemy within 20 yards of it and continuously attack that target until A.) the Searing Totem expires, B.) the target leaves its 20-yard radius, or C.) the target dies. If B or C occur, the totem will randomly choose another target in range and begin attacking it. If there are no targets within range, it will do nothing until an enemy comes in range. Also note that the totem will only engage hostile targets on its own; it will ignore neutral targets, unless you engage them first.\r\nIt is useful primarily in single-target, prolonged fights. You should avoid using it in situations where it could accidentally hit a target that shouldn't otherwise be hit (such as something that has been [[Crowd Control|CC'd]]).\r\n===Use===\r\n*Casting Time: Instant Cast\r\n*Range: 20 yards\r\n*Cooldown: Global Totem Cooldown\r\n*Scaling: Each shot gains 8% of your spell damage bonus.\r\n===Limitations===\r\n*The totem of any rank has only 5 hp; it is easily destroyed by mobs and players.\r\n*Useless against high [[element|Fire resistant]] players/[[mob|mobs]].\r\n*In certain situations, the totem might draw unwanted [[aggro]] from mobs who are not engaged in combat.\r\n*Dangerous to use when it can break a CC effect, or when it may pull an as-yet-unpulled group of creatures.\r\n===Talents===\r\nTalents that can improve the totem:\r\n===Tips===\r\n*Very useful in PvP for an extra bit of consistent damage. Most players will ignore the totem, knowing it will go away when you die and not wanting to take the time to target it.\r\n*Always useful in a boss fight, assuming the boss doesn't have adds which get CCed, the boss is not immune to fire, and you don't need to drop a [[Frost Resistance Totem]].\r\n*Most of the time, if you drop the totem while you are in melee, it will start out attacking the target you have selected. This may be a function of closeness, or may be a function of who you have selected at the time. I suspect that it simply picks the closest target when it doesn't have one.\r\n*It can be used to effectively disrupt spellcasting, especially in conjunction with melee attacks and a fast weapon. When combined with [[Earth Shock]], it can be difficult for an enemy caster to get out a spell.",},
			["Searinox"] = { content = "A black [[drake]], '''Searinox''', just prior to the [[demon]]ic invasion of the [[Burning Legion]], scoured the uninhabited lands south of [[Strahnbrad]], he had been feasting with the local farms and their inhabitants for weeks.\r\nSearinox and his brood of whelps came to the knowledge of [[Feranor Steeltoe]] and his band of [[dwarven]] Dragon Hunters; they wanted to claim the [[The Heart of Searinox|heart]] of the gargantuan beast. The heart of a black dragon could bestow fiery enchantments upon weapons, and they wanted those enchantments. They saw Searinox hide in his cave and were preparing to attack thinking that he may be vulnerable to a surprise attack.\r\nThen they met with prince [[Arthas]], with his help and of his warriors the Dragon Hunters manage to enter Searinox's lair, littered with the hundreds of corpses that he feasted on. Despite Searinox best efforts to defeat Arthas and the Dragon Hunters, he, his whelps, and the undead he summoned were defeated and with that put a stop to his rampage. Steeltoe reforged the heart into a magical [[Orb of Fire|orb]], which he gave to [[Arthas]].\r\n===Quotes===\r\n*''\"You dare challenge me? You mortals become more reckless with every generation!\"''\r\n'''Source:''' [[Warcraft III: Reign of Chaos]], Human Campaign, Mission 2.",},
			["Season 1"] = { content = "With the start of [[Season 4]], all [[Season 2]] rewards are now available for purchase using honor points instead of arena points. \r\n'''The Season 1 Gladiator armor can no longer be purchased with honor or arena points. However, it can still be obtained through the exchange of [[Tier 4]] armor tokens.'''\r\n----\r\n==Class Armor Sets==\r\nArena reward class sets are five piece quality armor sets. Some classes have more than one set, representing the different specialties of the classes' abilities.\r\nTo purchase Season 1 rewards, visit the vendors in the [[Hall of Legends]] in Orgrimmar or [[Champion's Hall]] in Stormwind.\r\n==Item Costs==\r\nThese costs are current as of the start of [[Season 3]]:\r\n===Armor===\r\nNote that head, shoulder, chest, hands, legs and shield are former Arena Season 1 items, whereas neck, wrist, waist, feet, finger and trinkets belong to Arena Season 3 and have a higher item level. The neck, wrist, waist, feet, finger armor and trinkets from arena season 1 are no longer available for purchase.",},
			["Season 2"] = { content = "'''Season 2''' started on June 19th 2007 in the North American and European realms.\r\nThe equivalent gear earned with [[honor point]]s is the non-class-specific [[Veteran's PvP rewards|Veteran's sets]].\r\nWith the start of [[Season 4]], all Season 2 rewards are now available for purchase using honor points instead of arena points.\r\n==Class armor sets==\r\n==See also==\r\n* [[Cost of Arena rewards by season]]\r\n* [[Veteran's PvP rewards]]",},
			["Season 3"] = { content = "'''Season 3''' started on November 27, 2007 in the North American realms and November 28, 2007 on the European realms.\r\nSeason 3 introduced the new [[personal rating]] system, which is a rating unique to each player in addition to their team rating. You must have a certain personal rating as well as team rating in order to purchase some of the Season 3 rewards. However, you do not have to maintain these ratings to continue use of the item.\r\nSeason 3 Weapons require a personal rating and team rating of 1850 to purchase, while shoulder slot items require 2000. The chest, legs, hands, and head slot items do not require a rating to purchase.\r\n[[Season 2]] items were made available at a 15% discount, while [[Season 1]] items were made available for Honor Points and Battleground Tokens.\r\n==Weapons & Accessories==\r\nWeapons require a personal rating of 1800. Also note that these prices are not correct anymore, all items are 15% cheaper.\r\n==See also==\r\n* [[Cost of Arena rewards by season]]\r\n* [[Vindicator's PvP rewards]]",},
			["Season 4"] = { content = "Season 4, began on the 24th of June 2008 for US servers, and on the 25th of June for EU servers, introducing the new Brutal Gladiator's arena sets. Season 4 is scheduled to end on October 14th.\r\nMost Season 4 rewards have a personal rating requirement for purchase.\r\nAt the start of Season 4, the following adjustments were made to previous seasons' rewards:\r\n*[[Season 3]] items were made available at a 15% [[Arena point]] discount and 50 point reduced rating requirement (Shoulders: 1950, Weapon: 1800)\r\n*[[Season 2]] items were made available for [[Honor point]]s and [[Battleground]] tokens\r\n*[[Season 1]] items are no longer be available for purchase with honor\r\nArena gear is additionally available with a cost of [[Tier 4]]/[[Tier 5|5]]/[[Tier 6|6]] loot tokens or Badge of Justice from the Exotic Gear Purveyors of the [[Sun's Reach Armory]]: Karynna, Olus, Soryn and Kayri.\r\n==Weapons & Accessories==\r\nSeason 4 weapons have a personal rating requirement of 2050 for purchase. Season 4 shoulders require 2200 PR to be purchased.\r\n==See also==\r\n* [[Cost of Arena rewards by season]]\r\n* [[Guardian's PvP rewards]]",},
			["Seat of the Naaru"] = { content = "The '''Seat of the Naaru''' is the central section of [[the Exodar]] where [[O'ros]] the [[naaru]] resides down on the lower levels. It is a circular area with purple flux shimmering in the center. The area contains entrances to the [[bank]], Alliance-linked [[auction house]], and hallways leading to three other wings. It should be noted that both the auction house and bank have [[mailbox|mailboxes]] by their entrances. The area also has small trading posts of General Goods and Bags.",},
			["Sea Elemental"] = { content = "'''Sea Elemental''' can be found in [[Feralas]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.06% Chance of a [[rare]] drop.\r\n0.66% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Sea giant"] = { content = "'''Sea giants''', also called '''skrogs''', are aggressive, aquatic [[giant]]s created by the [[titan]]s to help them dredge out the seas and lift the land from the sea floor of [[Azeroth]]. Few remain, and those that do are often hostile. The sea giants of [[Stranglethorn Vale]] are particularly malevolent: they are known for deliberately sinking ships and stealing their loot.\r\nA sea giant kingdom is located in the island region of [[Azsuna]] on the [[Broken Isles]]. These giants have allied with [[Queen Azshara]]'s [[naga]] minions. The [[Felrage Skrog]]s and [[fel]] naga at the [[Felrage Strand]] on the [[Broken Shore]] serve the [[Burning Legion]]. But sea giants and naga are not normally friends; outside the Broken Isles, such as in [[Azshara]], the sea giants used by naga are enslaved.\r\nA number of sea giants were located on [[Echo Isles]]. [[Rexxar]] killed them in order to evacuate the [[Jungle troll|trolls]].\r\nThe scientific community of [[Azeroth]] long pondered, often in taverns, what a baby sea giant looked like.\r\n==Types==\r\n*[[Sea Giant (Warcraft III)|Sea Giant]] \r\n*[[Sea Giant Hunter]] \r\n*[[Sea Giant Behemoth]] \r\n==Groups==\r\n*[[Trenchwalker]]\r\n==As a companion pet==\r\n[[Shell of Tide-Calling]] has a chance to drop from Morogrim Tidewalker in [[Serpentshrine Cavern]].\r\n===Culture===\r\nAzeroth's sea giants venerate [[Golganneth]] and hold small ceremonies several times a year in his honor. These ceremonies involve the crafting and sounding of musical horns and the feeding of small fish.\r\n==Notes==\r\n*NPCs using the old model will occasionally \"fart\" out bubbles of green gas, which will subsequently pop and be waved away by the giant.\r\n*The sea giant model used in ''Legion'', has [[Broken Isles]] [[vrykul]] symbols on their \"armor\".\r\n==See also==\r\n*[[Sea giant behemoth]]s",},
			["Sea Giants"] = { content = "#REDIRECT [[Sea giant]]", redirect = "Sea giant",},
			["Sea Lion"] = { content = "#REDIRECT [[Sea lion]]", redirect = "Sea lion",},
			["Sea of Cinders"] = { content = "'''The Sea of Cinders''' is a relatively flat stretch of land in the southern area of [[Searing Gorge]], just north of [[Blackrock Mountain]]. The flat lands have been ravaged by fire and wind and are now an uninhabitable wasteland. Cinders and ashes from the still smoldering ground are constantly flying through the air, making it an extremely unpleasant area to travel through.",},
			["Sea Spray"] = { content = "'''Sea Spray''' can be found in [[Feralas]] .\r\n==Drops == \r\n \r\n0.02% Chance of an [[epic]] drop.\r\n0.08% Chance of a [[rare]] drop.\r\n0.67% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Sea turtle"] = { content = "''' Sea turtles''' are [[turtle]]s found in waters of [[Azeroth]]. They were first added as part of the ''[[Cataclysm]]'' expansion. \r\nSea turtles are known to live in the [[Veiled Sea]].\r\n==Types==\r\n* Glasseye Turtle\r\n* Seabrush Terrapin\r\n* Softshell Sea Turtle\r\n* Speckled Sea Turtle\r\n* Siltwash Terrapin\r\n* Wandering Sea Hatchlet\r\n* Wandering Sea Turtle",},
			["Sebastian Crane"] = { content = "'''Sebastian Crane''' is a level 72 [[Horde Expedition]] faction rewards [[vendor]] located on the top floor of the [[Vengeance Landing]] inn in [[Howling Fjord]].\r\nSee [[Howling Fjord NPCs]].",},
			["Second invasion"] = { content = "The Second Invasion refers to the [[Burning Legion]]'s second attempt to destroy the world of [[Azeroth]]. [[Archimonde]] was a lead character in this invasion, and attempted to completely destroy [[Nordrassil]]. As he climbed the tree, a [[Kaldorei]] bugle was sounded, calling thousands of [[Wisp]]s to self-destruct simultaneously while attacking Archimonde. This failed with [[Archimonde]]'s death on [[Mount Hyjal]]. It is analogous to the [[Third War]].",},
			["Second Key Fragment"] = { content = "==Source==\r\nThis item drops from [[Second Fragment Guardian]] in [[The Steamvault]].\r\n==Second Key Fragment as a quest objective==\r\nThis item is an objective of The Second and Third Fragments.",},
			["Second War"] = { content = "The '''Second War''' was a conflict between the [[Alliance of Lordaeron]] and the [[History of the Horde|Old Horde]], engulfing all the lands of the [[Eastern Kingdoms]], and ending with the victory for the Alliance. Its events were chronicled in [[Warcraft II: Tides of Darkness]]. The [[Second War]] is also used to refer to events of [[Beyond the Dark Portal]] in some accounts as well.\r\nSee also [[Battles of the Second War]] and this [[Retcon|account]] of what events from the game campaigns were included in the lore.\r\n==Prelude to war==\r\nFollowing the events of the [[First War]], the survivors of Stormwind led by [[Anduin Lothar]] made their way to the northern kingdom of [[Lordaeron]] to beseech aid from King [[Terenas Menethil II]]. Following Lothar's impassioned speech, Terenas called for an emergency council of war to discuss the Orcish threat. Meanwhile, the Orcish Horde pillaged Stormwind city and the surrounding areas, effectively destroying all human holdings south of the [[Burning Steppes]]. \r\nIn the years between the defeat of the kingdom of Stormwind and the outbreak of the Second War, it can only be assumed that both the Horde and Alliance went through massive reformations and began huge military build-ups in preparation for war. \r\nKing Terenas, through skilled political maneuvering, enlisted the support of the human kingdoms of [[Gilneas]], [[Stromgarde]], [[Dalaran]], [[Alterac]], and [[Kul Tiras]]. They also managed to gain the allegiance of the [[Bronzebeard]] [[Dwarves]] of [[Ironforge]], the [[Wildhammer]] Dwarves of [[Aerie Peak]], and the [[Gnomes]] of [[Gnomeregan]]. Envoys led by Lord Lothar attempted to gain the allegiance of the [[High Elves]] of [[Quel'Thalas]], though initially they were uninterested in the coming conflict and sent merely a pittance of their forces. This resulted in the [[Alliance of Lordaeron]].\r\nIn the last days of the [[First War]], the leader of the [[Shadow Council]], the [[Warlock]] [[Gul'dan]] fell into a deep coma attempting to probe the mind of [[Medivh]]. Without the machinations of the Shadow Council, the Horde fell prey to infighting. In a coup d'état led by [[Orgrim Doomhammer]] to end what he saw as a corrupting influence over the Horde, the Shadow Council was destroyed as well as its puppet Warchief, [[Blackhand the Destroyer]]. Doomhammer successfully took control of the remaining Horde forces and began to bolster their devastated armies with orcs and ogres from beyond the Dark Portal. With trolls, ogres and orcs fighting side by side, it was not long before the enterprising goblins saw the potential profit in aiding them. The Horde gained support from [[Goblin]] machinists and mercenaries, and through use of the [[Demon Soul]] managed to enslave the Red Dragon [[Alexstrasza]] and the majority of her brood. It is unknown what relationship the Horde had with the [[Troll]] tribes of [[Stranglethorn Vale]], however they did not join forces with the Horde and stayed apart from the Second War. Upon awakening from his coma and finding himself without allies, Gul'dan \"swore\" allegiance to Doomhammer and began creation of the first [[Death knight (Second War)|death knight]]s in the service of the Warchief. This was the beginning of the so-called [[Horde]].\r\n==The Horde Offensive==\r\nIn the 6th year after the fall of Stormwind, the Horde began their northern offensive against the Alliance forces. The Horde simultaneously launched two primary assaults. The first was a land offensive launched out of [[Blackrock Mountain]] which moved north to the Dwarf holdings in [[Khaz Modan]]. The second was a naval assault launched from the ruins of Stormwind, which sailed north taking the islands of [[Zul'dare]], [[Tol Barad]], and [[Crestfall]] and establishing them as naval bases. From these launching points, the Horde landed troops along the coasts of the Wetlands, the Arathi Highlands, and most importantly the southern coast of Lordaeron. Southern outposts such as [[Southshore]], [[Tarren Mill]] and [[Hillsbrad]] were assaulted, and the Horde squeezed a large amount of troops into [[Lordaeron]] this way, assisted by the nation of Alterac who provided them with maps and secret routes. \r\nSoon after, [[Zul'Jin]] and some of his champions were discovered by Horde scouts in a makeshift prison near Tarren Mill. Upon hearing the news, Doomhammer immediately ordered his release from the 40-man raid party that captured him. Now in Doomhammer's debt, Zul'Jin agreed to form a pact with the orcish Horde: the plains and valleys of Lordaeron would belong to the Horde, while the trolls would take back their ancestral forests from their mortal enemies, the high elves.\r\nThe Horde's land assault proceeded to lay waste to [[Loch Modan]], pushing the outnumbered Dwarf and Gnome forces into the city of Ironforge, who sealed themselves from the outside threat. The [[Bleeding Hollow Clan]] attempted several raids on the mighty dwarven city, to no avail. For the most part, Dwarves and Gnomes were cut off from the rest of the Alliance, save through air support. Following the ravaging of Loch Modan, the Horde pushed farther north into the [[Wetlands]], taking [[Dun Algaz]], [[Dun Modr]], and [[Grim Batol]] and converting them into fortresses for the Horde. Grim Batol became the primary base for the land offensive, and was also converted into a hatchery for the enslaved [[Red Dragonflight]]. [[Thandol Span]] was a pivotal battleground in the Second War, constantly shifting in possession between the two factions.\r\nFinally, owing to a diversion of Lothar's main army at [[Aerie Peak]], the Horde succeeded in penetrating Quel'Thalas through the cliffs undetected. Together with the entirety of the [[Amani tribe]] under Zul'Jin, Doomhammer's troops slashed and burned their way through the elven forests, and made it as far as [[Eversong Woods]] before the Alliance reinforcements could arrive.\r\n==Brief counterattacks from the Alliance==\r\nOutraged at the attack on their borders, the Elves finally put forth their full strength in the war effort. This included the deployment of Elven Destroyers south to the Hinterlands and to the shores of Lordaeron. Lordaeron and Quel'Thalas managed to push back the majority of Horde forces to the shores of Hillsbrad, but not before Gul'dan was able to acquire High Elven [[runestones]] to use in his effort to create [[Ogre-magi]] for the war effort. With support from the Elves, the Alliance was able to launch an attack on Zul'dare and end the invasion of Lordaeron. Though Hillsbrad and Southshore were nearly obliterated, the Horde navies were driven back, presumably to the shores of the Wetlands, Crestfall, and the ruins of Stormwind.\r\nFollowing the victory in the north, the Alliance concentrated on pushing back the ground offensive on the edge of the [[Arathi Highlands]] on the great bridges of the Thandol Span. The first step was a bloody retaking of the Horde fortress on Tol Barad for use as a staging point for an invasion upon Dun Modr, the primary base of support for the attacks upon the Thandol Span. With naval support from Tol Barad, the Alliance ground forces were finally able to push across the Thandol Span and reclaim Dun Modr. The Alliance continued to push south, taking the base at Dun Algaz. Though they were unable to completely take the cursed fortress of Grim Batol, they effectively shattered the armies of the Horde and causing them to retreat from Khaz Modan.\r\nAfter the defeat of the Horde forces in Khaz Modan, a brief pause in open combat ensued. The Horde attempted to gather more troops from the south, including the newly completed Death Knights. The Alliance began to turn their sights northward to the remnants of the Horde forces in northern Lordaeron, and to that end they sent [[Uther Lightbringer]] and his newly formed [[Knights of the Silver Hand]] to lend aid to the victims of the war. However, a minor peasant riot in Tyr's Hand led to a discovery of a plot from [[Lord Perenolde]] of Alterac, who was attempting to destroy the Alliance from within. Learning of Alterac's plots, the Alliance forces obliterated the small, treacherous kingdom.\r\n==The Siege of Lordaeron==\r\nDespite the disruptions on the home front, the Alliance continued to move south toward [[Blackrock Spire]]. While the Alliance forces found themselves outnumbered, exhausted, and in the harsh territory, the Horde forces continued to gain fresh reinforcements through the magics of Gul'dan and from beyond the Dark Portal. Doomhammer used the lull in combat caused by Alterac's betrayal to prepare a massive assault that would tear through the assailing forces of the Alliance and push through all the way to Lordaeron. It was a daring plan, and by sheer force of numbers it surely would have succeeded.\r\nHowever, on the eve of Doomhammer's bold offensive, Gul'dan, finally learning the location of the [[Tomb of Sargeras]] took nearly half of the Horde's forces in an attempt to raise the Tomb from the sea and claim the demonic powers for his own. Doomhammer withdrew his forces to pursue Gul'dan instead, in an effort to terminate his treacherous [[Stormreaver Clan]] and allies. The alliance jumped on this opportunity and proceeded to mop up \r\nthe horde's remaining standing troops in Lordaeron, who were in shambles and without air support. The Stormreaver and [[Twilight's Hammer Clan]] were [[Battle at the Tomb of Sargeras|destroyed]] by Doomhammer's forces, which included his secret weapon: the red dragons.\r\n==The Alliance Takeover==\r\nWith the Horde forces thus weakened, the Alliance [[Assault on Blackrock Spire|laid siege]] to the fortress of Blackrock. In order to break the siege, Doomhammer and what followers he had left charged out of the Spire and attacked Lord Lothar and his [[Paladins]]. After a titanic duel, Doomhammer narrowly managed to kill Lord Lothar. Upon his death, Lothar's second-in-command, the Paladin [[Turalyon]] took command, made Doomhammer his prisoner, and chased the retreating Orcs to their last bastion of power, the Dark Portal.\r\nRagged and broken, the remaining Horde forces attempted a defense of the Dark Portal. In what has been described as the bloodiest [[Battle of the Dark Portal|battle]] of the Second War, the Orcs were eventually defeated, their leaders rounded up, and Doomhammer himself taken in chains. Shortly thereafter, the wizard [[Khadgar]], flanked by the brave warriors of the Alliance, destroyed the Dark Portal. With the destruction of the Dark Portal, the Second War was ended.\r\n*See the [[Aftermath of the Second War]]",},
			["Secrets of the Qiraji"] = { content = "==Objectives==\r\nTake the Ancient Qiraji Artifact to the dragons hiding near the entrance of the temple.\r\nYou will need:\r\n* Ancient Qiraji Artifact (provided)\r\n==Quest Text==\r\nYou have discovered an ancient [[Qiraji]] artifact! Perhaps one of the [[dragon]]s near the entrance of the [[Temple of Ahn'Qiraj|temple]] would have a use for this relic.\r\n==Progress==\r\nYou're glowing! I know what that means...\r\n==Completion==\r\nAn exceptional find, <name>. Simply marvelous! This will definitely give us some insight into our enemy's twisted minds.\r\n==Reward==\r\nYou will receive:\r\n*+1000 reputation with [[Brood of Nozdormu]]\r\n==Notes==\r\n*Ancient Qiraji Artifact can drop from all trash mobs in the [[Temple of Ahn'Qiraj]].\r\n*The dragon that accepts the quest item is behind the Prophet Skeram, inside the temple.\r\n*This quest is repeatable for additional Reputation points.\r\n*It is advised to save this quest item until the player is Neutral (2999/3000). At this point, trash mobs will no longer give Reputation points and the only way to earn more reputation is by turning in these artifacts and [[Qiraji Lord's Insignia]]s and defeating the Twin Emperors and C'Thun.",},
			["Secret Level Powerup"] = { content = "Unlocks a secret level!\r\n==Source==\r\n[[Kael]] and [[Lady Vashj]] can find this in [[The Dungeons of Dalaran]], chapter 3 of the [[Warcraft III: The Frozen Throne|Frozen Throne]] alliance campaign, [[Curse of the Blood Elves]].",},
			["Secret Strength of the Frenzyheart"] = { content = "==Source==\r\nThis item is created by combining Wolvar Berries with Thunderbrew's Hard Ale.\r\n==As a quest objective==\r\nThis item is an objective of Secret Strength of the Frenzyheart.\r\n==Notes==\r\nWhile under the effect of the drink you'll receive 50% less damage, your attacks cause a bonus 2775 to 3225 damage, and your attacks gives a 9 to 11 yards knockback.",},
			["Sect of the Dragons"] = { content = "Before the [[Titan]]s left [[Azeroth]], they invested the five [[dragon Aspects]] with tremendous power. The Aspects are [[Alexstrasza]] the Life-Binder, [[Malygos]] the Spell-Weaver, [[Neltharion]] the Earth-Warder (now known as Deathwing), [[Nozdormu]] the Timeless and [[Ysera]] the Dreamer. The Aspects have many worshipers among the [[night elves]] and other isolated groups such as [[dragonspawn]].\r\nDomains: Elements, Healing, War. (Priests of Deathwing substitute the Destruction domain for Healing.)",},
			["Security Chief Bilgewhizzle"] = { content = "'''Security Chief Bilgewhizzle''' is a level 51 [[quest giver]] located at [[Steamwheedle Port]] in the [[contested]] territory of [[Tanaris]].\r\nHe may be related to [[Chief Engineer Bilgewhizzle]].\r\nHe starts the quest Southsea Shakedown.\r\nSee [[List of Tanaris NPCs]].",},
			["Security Chief Bilgewhizzle"] = { content = "'''Security Chief Bilgewhizzle''' is a level 51 [[quest giver]] located at [[Steamwheedle Port]] in the [[contested]] territory of [[Tanaris]].\r\nHe may be related to [[Chief Engineer Bilgewhizzle]].\r\nHe starts the quest Southsea Shakedown.\r\nSee [[List of Tanaris NPCs]].",},
			["Security DELTA Data Access Card"] = { content = "'''Security DELTA Data Access Card''' is sought after by [[Engineer]]s to access the [[schematic]] for Discombobulator Ray from [[Matrix Punchograph 3005|Matrix Punchograph 3005-D]] in [[Gnomeregan]].\r\n==Source==\r\nThis item drops off [[mechanical]] [[mob]]s in [[Gnomeregan]]. It has a significantly higher drop rate from the [[Arcane Nullifier X-21]].",},
			["Seduce"] = { content = "#REDIRECT [[Seduction]]", redirect = "Seduction",},
			["Seduction"] = { content = "An ability of the Warlock's [[Succubus]] pet, '''Seduction''' mesmerizes a target and renders them unable to attack, cast, move, or use any other abilities. Any damage caused to the target will remove the effect. \r\n==Talent Improvement==\r\n[[Improved Succubus]] increases duration by 10 / 20 / 30%. \r\n==Tips and Tactics==\r\nSeduction has a 1.5-second casting time and is channeled, so the [[Succubus]] can't perform any other action while seducing and can be interrupted. This ability only works on [[humanoid]]s and lasts for 15 seconds, barring [[Diminishing Returns|diminishing returns]] or damage. Any damage inflicted on the target will break Seduction instantly.\r\nSeduction can be set to [[auto-cast]]; the AI does nothing when you're facing one opponent, but with more than one, it's fairly good at picking one enemy you're not fighting and seducing it.\r\nSeduction on other [[player]]s is controlled by the [[Diminishing Returns Rule]], which means that you can't seduce a player an unlimited number of times. Not only that, but '''Seduction''' and [[Fear]] are on the same [[Diminishing Returns Rule]], preventing alternating use for long times.",},
			["Seed of Corruption"] = { content = "''\"A shard of pure evil can be more deadly than the most devastating goblin explosives...\"''\r\n'''Seed of Corruption''', often abbreviated '''SoC''', is a [[warlock]] [[Schools_of_Magic|Shadow]]-based [[Damage over Time]] spell that does [[Area of Effect]] [[Direct Damage]] after doing a fixed amount of damage over time. This spell was introduced in [[The Burning Crusade]] expansion.\r\n==Notes==\r\nSeed of Corruption is a [[Formulas:Magical resistance|binary spell]], so it will either be completely resisted (no DoT and no explosion) or land for full damage. If the DoT lands, an explosion damaging everything around it is guaranteed.\r\nSeed of Corruption can not be used in combination with [[Corruption (spell)|Corruption]]. If SoC is cast on a target affected by Corruption, SoC replaces Corruption. If Corruption is cast on a target affected by SoC, it fails with the message \"A more powerful spell is already active\".\r\nIf a target afflicted by Seed of Corruption takes damage from another target's SoC detonation and survives, it will not have its own SoC detonate. The DoT will continue ticking until the required amount of damage has been done, or the target is killed. Only then does its own SoC explosion actually occur.\r\nSoC detonation can be set off by ''any'' damage, not necessarily from the Warlock. For example, casting SoC on a mob being attacked by other members of the group is likely to produce an instant explosion. SoC detonation consumes the effect (hence stops the damage-over-time). It does not damage the target itself, only those around it. The direct damage from the explosion can crit.\r\nIts damage is affected by talents and gear, but the detonation threshold is not. In other words, SoC will detonate as soon as target receives 1044 damage, even though it may only take 2-3 ticks of the DoT to deal this much damage. In essence, extra +dmg gear will \"shorten the fuse\" (make the fuse burn faster). The DoT part receives 150% bonus damage from +dmg gear (damage is spread out over 6 tics), the detonation part gets 16.6% bonus damage.\r\nUnlike Corruption, SoC casting time is not affected by talents. It is always 2 seconds.\r\n==Tips and tactics==\r\nDue to its overall damage limitation, which is around 13.500 to all affected mobs (before all modifieres like [[Spell critical strike|criticals]] and certain debuffs), Seed of Corruption is inferior to [[Hellfire]] when dealing with large groups (like around fifteen or even more mobs).\r\nSeed of Corruption is most useful in situations where you have to deal with multiple mobs at the same time and you have a tank with AOE taunt (such as [[Voidwalker]]). As soon as the tank grabs aggro, quickly cast SoC on as many mobs as you can. Try not to target mobs taking damage from the tank. If all goes well, detonations will wipe all mobs in no time. However, there have to be at least 3-4 mobs in the group, and they shouldn't have more than 10,000 hp each. If you can't kill everyone with the initial round of detonations, you'll have a pack of very angry mobs at half-health beating on you and you won't be able to do anything. \r\nIf you have a competent and well geared Paladin who is Aoe tanking, this spell can be used to quickly clear large groups of mobs, especially if there are other warlocks and/or mages in the group contributing AoE damage. This tactic can clear dungeons incredibly quickly (particularly with affliction warlocks, who bring low downtime and high shadow damage to the equation).\r\nSeed of Corruption is best used when you don't have aggro. It's hard to cast a 2-second spell while taking damage from multiple mobs. If you have mobs attacking you already, you're better off using [[Hellfire]] over SoC.\r\nIn PvP, it can be useful to steadily cast it at a target which constantly takes damage, as the previous SoC can trigger before the next one arrives; this can be used to deal immense amounts of damage in short time. It can also be cast on pets, and if you can get the pet close to the owner when it detonates, it can provide additional damage to its owner.",},
			["Seed of Life"] = { content = "==Source==\r\nThis item is provided for Seed of Life.\r\n==Seed of Life as a quest objective==\r\nThis item is an objective of Seed of Life.",},
			["Seek Out Ameer"] = { content = "'''Seek Out Ameer''' starts in [[Stormspire]] and kicks off a series of [[Consortium]] quests added with patch 2.1. The quest series ends in being able to summon an optional boss after the final boss of Heroic Mana-Tombs. You will need to be [[Honored]] or better with [[Consortium]] before starting this quest chain. \r\n==Objectives==\r\nSeek out Commander Ameer at the Protectorate Watch Post.\r\n==Details==\r\n[[Commander Ameer]] can be found at [[Protectorate Watch Post]] directly east of [[Stormspire]] in [[Netherstorm]].\r\n==Description==\r\nIt would seem that an outside force has taken an interest in the business practices of the Consortium. Five Consortium dealers have gone missing in the past two days. We have reason to believe the Ethereum are involved. If you are interested in assisting, seek out Commander Ameer at the Protectorate Watch Post.\r\nYou will find the Protectorate Watch Post directly east of here on the next island.\r\n==Reward==\r\n* s=44 gold \r\n* 10 [[Consortium]] Reputation\r\n==Completion==\r\nAye, it is true, but the Consortium are not the only group claiming losses.",},
			["Seer's Library"] = { content = "'''The Seer's Library''' is the base of leadership for the [[Scryers]] and the location of their leader, [[Voren'thal the Seer]]. It is located in the central part of the [[Scryer's Tier]], and has three floors, the top of which is located through ramps on the outside.",},
			["Seer"] = { content = "A '''seer''' (or '''seeress''' if female) is usually someone with the ability to predict the future or see things hidden from mundane eyes, like a clairvoyant or a [[prophet]].\r\n==Tauren==\r\nThe three most powerful [[healer]]s in a [[tauren]] tribe support the [[chief]], the most powerful of whom takes the title '''seer'''. A chief generally consults his seer and her two contemporaries before making a decision, but this consultation is not required.\r\n==Other types==\r\n*[[Windseer Grayhorn|Grayhorn]] is a windseer.\r\n*[[Saberon]] [[Boneseer Cold-Eye|Cold-Eye]] is a boneseer, who divines the future using the remains of the dead.\r\n*[[Skyseer Ghrent|Ghrent]] is a skyseer.\r\n*[[Grom'kar Cinderseer|Cinderseers]]\r\n*Runeseers\r\n*[[Sea Seer Crystal|Crystal]] is a sea seer\r\n*Voidseers\r\n*Stormseer\r\n*Flameseer\r\n==The Seers==\r\nAll [[priest]] trainers that are tauren (except [[Tahu Sagewind]], their leader) carry the title \"Seer\", and the level 20 class quest for tauren priests is called [[A Seer's Staff (tauren)]] - although the goblin one is called [[A Seer's Staff (goblin)|the same]] - and mentions that the player would \"become a full seer\" through this mission, implying that the seers and tauren priests are identical or have merged - or have been merged by Blizzard. They are associated with the [[Sunwalkers]] and share (re)founding members, but appear to be an independent order.\r\n===Named===\r\n* [[Akubar the Seer]]\r\n* [[Blindeye the Seer]]\r\n* [[Seer Graytongue]]\r\n* [[Seer Janidi]]\r\n* [[Seer Jovar]]\r\n* [[Seer Kanai]]\r\n* [[Seer Nakha]]\r\n* [[Seer Olum]]\r\n* [[Seer Ravenfeather]]\r\n* [[Ruuna the Blind]]\r\n* [[Takar the Seer]]\r\n* [[Seer Skaltesh]]\r\n* [[Udalo]]\r\n* [[Ul'Tomon]]\r\n* [[Voren'thal the Seer]]\r\n* [[Seer Wiserunner]]\r\n* [[Seer Yagnar]]\r\n* [[Warp-Scryer Kryv]]\r\n* [[Seeress Weng Wu]]\r\n*[[Velen]]\r\n*[[Drek'Thar]]\r\n===Units===\r\n*[[Unbound Seer]]\r\n*[[Smolderthorn Seer]]\r\n*[[Deepfin Seer]]\r\n*[[Frostmane Seer]]\r\n*[[Lost One Seer]]\r\n*[[Umbrafen Seer]]\r\n*[[Wrekt Seer]]\r\n*[[Blacksilt Seer]]\r\n*[[Greymist Seer]]\r\n*[[Grimscale Seer]]\r\n*[[Burning Blade Seer]]\r\n*[[Death's Head Seer]]\r\n*[[Razormane Seer]]\r\n*[[Stonesplinter Seer]]\r\n*[[Stonevault Seer]]\r\n*[[Dragonflayer Seer]]\r\n==See also==\r\n*[[Conjurer]]s\r\n*[[Arcanist]]s\r\n*[[Diviner]]s",},
			["Seer Graytongue"] = { content = "'''Seer Graytongue''' is a level 8 [[quest giver]] located at his hut in southwestern [[Red Cloud Mesa]] in the [[tauren]] starting zone of [[Mulgore]]. He is a tauren elder who lives away from others so he can meditate easier. \r\nHe starts the quest Rite of Strength.\r\nSee [[List of Mulgore NPCs]].",},
			["Seer Olum"] = { content = "'''Seer Olum''' is a level 70 [[Broken]] located in [[Serpentshrine Cavern]], located in the room with [[Fathom-Lord Karathress]]. He is a member of the [[Ashtongue Deathsworn]].\r\nOlum is one of the keepers of the Ashtongue's secret - their intent to overthrow Illidan. However, he has been captured by [[Lady Vashj]]'s naga and is being tortured to try to ascertain exactly how the Ashtongue plan on deposing the Betrayer.\r\nHe begins the quest The Secret Compromised, but only if you have completed Akama's Promise. Note that he \"despawns,\" within an hour after Fathom-Lord Karathress is defeated.\r\nSee [[Coilfang Reservoir NPCs]].\r\n===Conversation with [[Akama]]===\r\n* \"Akama, my friend. Have you been informed? I was found out by [[Vashj]]'s followers. Now our secret is in peril!\"\r\n* \"Illidan is looking for me. I'm not safe here; none of us are.\"\r\n* \"Illidan will find me. And when he does, he will pry the ashtongue secret from me. Such is the power of the Betrayer! Now, there is only one way. My usefulness to the cause has come to an end. I must venture into the spirit world.\"\r\n* \"My decision is final. I will not (Needs to be added). I have devoted my life to my plan. To jeopardize it now would betray all who have died for the cause long before me.\"\r\n* \"I thank you, Akama. You honor me by allowing me this moment, surrounded by my brothers. Farewell friend, guide our people well.\"",},
			["Seer Ravenfeather"] = { content = "'''Seer Ravenfeather''' is a level 10 [[quest giver]] located in [[Camp Narache]] in the [[tauren]] starting zone of [[Mulgore]]. \r\nShe starts the following quests:\r\n* Call of Earth\r\n* Call of Earth\r\nSee [[List of Mulgore NPCs]].",},
			["Seeth'rel"] = { content = "'''Seeth'rel''' can be found in [[Blackrock Depths]] .",},
			["Selendra"] = { content = "'''Selendra''' is a level 40 [[quest giver]] located on [[Sar'theris Strand]] just south of [[Shadowprey Village]] in the [[contested]] territory of [[Desolace]].\r\nShe starts the quest Corruption of Earth and Seed (Dungeon).",},
			["Self-Turning and Oscillating Utility Target"] = { content = "The '''Self-Turning and Oscillating Utility Target''' is a level 50 [[harvest golem]] found in the brewfest camps of [[Durotar]] and [[Dun Morogh]] during the [[Brewfest]] holiday.\r\n==Objective of==\r\n*Chug and Chuck! (Alliance)\r\n*Chug and Chuck! (Horde)",},
			["Self Turning and Oscillating Utility Target"] = { content = "#REDIRECT [[Self-Turning and Oscillating Utility Target]]", redirect = "Self-Turning and Oscillating Utility Target",},
			["Selina Dourman"] = { content = "'''Selina Dourman''' is a level 30 [[npc]] located in the [[Darkmoon Faire]] camp, which is only available during the monthly Darkmoon Faire event. It rotates each month to a different location. One month it will be south of [[Goldshire]] in the [[human]] starting zone of [[Elwynn Forest]]. Then, it is off to [[Kalimdor]] where it is southwest of [[Thunder Bluff]] in the [[tauren]] starting zone of [[Mulgore]]. Then it travels to [[Outland]] near [[Shattrath City]].\r\nShe gives out information about the faire to curious adventurers.\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Selin Fireheart"] = { content = "'''Selin Fireheart''' is the first boss in the [[Magisters' Terrace]] [[instance]]. \r\nYou are awarded 120 reputation with the Shattered Sun for killing him in normal. You are awarded 250 reputation with the Shattered Sun for killing him in heroic. \r\n==Abilities==\r\n*Mana Rage: Siphons mana from a nearby Fel Crystal, increasing Selin's mana pool by 10% per second. Will continue until either the crystal is destroyed or Selin's mana is full.\r\n*Fel Explosion: Area of effect fire damage spell (deals 900-1100 damage), cast continually until Selin is out of mana (cast after each round of crystal draining).\r\n*Drain Life: Randomly targeted channeled spell, deals shadow damage and heals Selin. Should be interrupted or dispelled (pally cleanse).\r\n*Drain Mana: Randomly targeted channeled spell, drains mana. Heroic Mode only.\r\n==Notes==\r\nThe first two mobs in the dead center of the room may be safely pulled without attracting the attention of the other two groups. Fight the next two six-pulls out in the hall if you can. Crowd control--sap, sheep, trap, mind control, whatever you have--is useful for these pulls.\r\nSelin Fireheart is superficially similar to [[Warlord Kalithresh]]. Periodically he will run to one of the large green crystals in his room and begin casting '''Siphon Fel Crystal''' which increases both his size and (melee ''and'' magic) damage dealt while restoring his mana. Once the crystal is completely drained or smashed (whichever happens first) Selin will resume combat while casting '''Fel Explosion''' continuously until he is again out of mana. The sooner you break the crystal the less mana he will have to pound your group with '''Fel Explosion'''.\r\nThe moment Selin begins draining a crystal, everyone not engaged in trying to regain aggro should immediately switch targets to the crystal and destroy it. Alternatively, with sufficient healing one may ignore the crystals and maintain damage on Selin; 1800 +heal should be sufficient for this.\r\nWhen combat with Selin begins, an orange barrier (similar to the one blocking the rear exit of the room) will appear and block the archway you came in through, so make sure that everyone and their pets are fully in Selin's room before the fight begins or they could possibly become stuck outside (or stuck in the barrier). Note that aggroing Selin will also aggro all remaining Wretched.\r\nOne might be able to break Selin's Drain Life by simply jumping off the stage and breaking his line of sight.\r\nA Badge/Kara geared team should have little difficulty with this boss as his aoe is able to be healed through on normal with medium difficulty.\r\n==Heroic Mode==\r\nSame fight, crystals have considerably more hp however and need to be taken down faster than in normal mode to avoid too much mana regain. He will also drain mana from players, however it is neglible. He will of course do his Fel Explosions after a Drain Mana. As with the Drain Life, the Drain Mana can be interrupted or dispelled.\r\n==Quotes==\r\nAggro:\r\n*You only waste my time!\r\nDraining from a crystal:\r\n*My hunger knows no bounds!\r\nEmpowered:\r\n*Yes! I am a god!\r\nComing down:\r\n*No! More... I must have more!\r\nKill (normal):\r\n*Enough distractions!\r\nKill (empowered):\r\n*I am invincible!",},
			["Sen'jin"] = { content = "==Biography==\r\nThe spiritual leader of the [[Darkspear Tribe]], '''Sen'jin''' was an enigmatic witch-doctor with a deep and profound link to the spirits and his eternally rain-swept island. Sen'jin lived a relatively peaceful life until new troubles began. [[Humans]] from [[Kul Tiras]] came to the island and made a settlement, pushing the trolls further into the island. Meanwhile, the once-docile [[murlocs]] had become fevered, prodded by the dark [[Sea Witch]] that lived in the ocean, who they offered sacrifices to.\r\nThen one night, Sen'jin received a vision...\r\nHe saw a young [[orc]] - a [[farseer|seer]], who would drive the humans away, and save his people, leading them from the island. \r\nThat soon came true. As Sen'jin's sentry wards reported, [[Thrall]] and his fleet were forced to moor on his island after the [[Maelstrom]] nearly destroyed his ships. Sen'jin approached the orcs, warning them of the humans nearby. Thrall promised to force the humans from his island. After defeating an archmage and forcing them into a retreat, they were suddenly attacked by murlocs, who captured Sen'jin's trolls, the witch-doctor himself, as well as Thrall and his people.\r\nThrall managed to escape the prison and rescued many orcs and trolls, but the murloc high sorcerer took Sen'jin into the deepest part of the underground lair, where he brutally attacked him just as Thrall arrived. Thrall battled through the murlocs, and finally destroyed the murloc high sorcerer, but Sen'jin's wounds were deep, and he was dying. \r\nIn his last breath, Sen'jin implored Thrall to take his people from the island and save them from destruction.\r\n==World of Warcraft==\r\nOne of the [[realm]]s in [[World of Warcraft]] is named after Sen'jin. In addition, the \"Troll town\" in [[Durotar]] where Trolls can purchase raptor mounts is called [[Sen'jin Village]].\r\n* See: [[Realm Name Lore|Realm Names and their place in Warcraft Lore]]\r\n==See also==\r\n* [[Thrall]]",},
			["Sen'jin Village"] = { content = "==History==\r\nAfter the [[Trolls]] of the [[Darkspear Tribe]] were forced to flee the [[Echo Isles]] because of [[Zalazane]], [[Vol'jin]] relocated his people to the southern coast of [[Durotar]]. Vol'jin named the village after his father and former master [[Sen'Jin]], who fell while saving his people from rampaging Murlocs long ago (during the [[Third Wars]]). Vol'jin now resides in [[Orgrimmar]] as an advisor to [[Thrall]]. In his stead, he has left the troll [[Master Gadrin]] in charge of seeing to the needs of the small village.\r\n==Overview==\r\nUsually the first town most [[orc]]s and [[troll]]s encounter on their adventures after around level 5. The road from the [[Valley of Trials]] leads east to a crossroads. The path to Sen'jin heads southeast, while the other path turns north toward [[Razor Hill]]. \r\nSen'jin Village consists of:\r\n* 3 very small huts\r\n* 2 small huts\r\n* 1 big hut\r\n==Inhabitants==\r\n* [[Lar Prowltusk]]\r\n* [[Master Gadrin]]\r\n* [[Master Vornal]]\r\n* [[Bom'bay]] - Witch Doctor in Training\r\n* [[Ula'elek]]\r\n* [[Kali Remik]]\r\n* [[Vel'rin Fang]]\r\n* Guards: [[Sen'jin Watcher]]\r\n===Vendors===\r\n* [[Tai'tasi]] - Trade Supplies\r\n* [[K'waii]] - General Goods\r\n* [[Zansoa]] - Fishing Supplies\r\n* [[Trayexir]] - Weapon Merchant\r\n* [[Zjolnir]] - Raptor Handler\r\n* [[Hai'zan]] - Butcher\r\n===Trainers===\r\n* [[Un'Thuwa]] - [[Mage]] Trainer\r\n* [[Miao'zan]] - [[Alchemy]] Trainer\r\n* [[Mishiki]] - [[Herbalism]] Trainer\r\n* [[Xar'Ti]] - [[Riding]] Trainer\r\n==Quests==\r\n*Report to Orgnil\r\n*A Solvent Spirit\r\n*Practical Prey\r\n*Thwarting Kolkar Aggression\r\n*Minshina's Skull\r\n*Zalazane",},
			["Senani Thunderheart"] = { content = "'''Senani Thunderheart''' is a level 30 [[named]] female [[Tauren]] stationed at [[Splintertree Post]] in [[Ashenvale]]. She may be related to [[Thunderheart]].\r\nShe ends the quest The Ashenvale Hunt, in which [[Horde]] adventurers are sent to her to take place in a great hunt in Ashenvale. In order to take part, you need to hunt three great beasts:\r\n*[[Ursangous]] the [[bear]]\r\n*[[Shadumbra]] the [[cat]]\r\n*[[Sharptalon]] the [[hippogryph]]\r\nSee [[List of Ashenvale NPCs]].",},
			["Senir Whitebeard"] = { content = "'''Senir Whitebeard''' is a level 9 quest giver located in [[Kharanos]] in the [[dwarven]] starting zone of [[Dun Morogh]].\r\nHe starts the following quests:\r\n* Frostmane Hold\r\n* The Reports\r\nSee [[List of Dun Morogh NPCs]].",},
			["Sense Demon"] = { content = "#REDIRECT [[Sense Demons]]", redirect = "Sense Demons",},
			["Sense Demons"] = { content = "Ability used by warlocks. When activated, you will see every enemy's demon in the minimap as a red dot ( ), friendly demon as a green dot ( ).",},
			["Sense Undead"] = { content = "''\"The unnatural living dead leave a stain upon the Light, and a Paladin is ever-aware of such blights.\"''\r\nThis [[Paladin ability]] tracks all [[undead]] targets on the [[minimap]] with red spots ( ). But can't track [[Forsaken]] undead players.\r\n(similar to [[Track Undead]], [[Hunter]] ability)\r\nIt can be acquired by completing the [[Paladin Quests|Tome of Valor]] quest chain after Level 20.\r\nIt is very useful in any area with plentiful undead, and gives the Paladin more awareness in instances such as [[Stratholme]], [[Scholomance]] and [[Naxxramas]], or zones like [[Raven Hill]] in [[Duskwood]].",},
			["Sentinels"] = { content = "The '''Sentinels''' (officially the '''Sentinel Army''') are the primary military arm of the [[night elf]] race. Founded in the years following the [[War of the Ancients]] and the destruction of the old [[Kaldorei Empire]], the Sentinels serve as [[Darnassus (faction)|Darnassus]]'s army in its engagements throughout [[Kalimdor]] and beyond.\r\nThe organization is composed of devout and well-trained warriors, often with strong ties to the [[Sisterhood of Elune]]. The Sentinels form the majority night elven component of the [[Darnassian Army]], which encompasses numerous other beings and unit types.\r\nIn the wake of its war with the [[Burning Legion]], High Priestess [[Tyrande Whisperwind]] led the night elf race, and particularly the Sisterhood, in rebuilding their ruined society. Her order was uniquely poised to fill a power vacuum as a result of their numbers and influence, and Tyrande soon took advantage of this. From the ranks of the Sisterhood of Elune, she forged the Sentinels, whose duty it was to protect their newly-emergent society. Quickly cementing itself in this role, the Sentinels became the fledgling night elf nation's primary agents and guardians.\r\nIn the millennia to come, the Sentinels would take part in many conflicts on behalf of Darnassus, most immediately in the [[War of the Satyr]]. Over time, the army's composition would begin to change, incorporating more male night elves into its ranks, and utilizing more military hardware. Today, Tyrande is recognized as their former general, and the Sentinel Army is led in battle by the distinguished [[Shandris Feathermoon|General Shandris Feathermoon]], with its largest base of operations (outside of Darnassus) at [[Feathermoon Stronghold]] in [[Feralas]].\r\n===Membership===\r\nThe Sentinels were established approximately 600 years after the [[War of the Ancients]], and until recently were entirely composed of night elf women. The immense casualties suffered in the [[Third War]] would eventually force the traditional gender roles of night elven society to be set aside in favor of a more practical approach. As a result, although the Sentinels remain mostly female, an increasing number of night elf men serve in their ranks.\r\nThe Sentinels are courageous and selfless soldiers whose only goal for the last ten millennia has been to defend the night elf people. New recruits undergo extensive training and, as time permits, the more experienced warriors take part in frequent combat drills. The Third War resulted in many losses for the Sentinels, but the army still boasts a number of battle-hardened veterans. Like High Priestess [[Tyrande Whisperwind]] and General [[Shandris Feathermoon]], there are still plenty of Sentinels in active service who fought in the War of the Ancients.\r\n===Early history and organization===\r\nBy the time of the [[Great Sundering]], military service in the night elf [[Kaldorei Empire]] had become more a matter of bloodline than ability. Almost all high-ranking officers were nobles, and the night elves had lived in peace for so long that very few of those officers, however privileged and well educated, possessed even a basic knowledge of tactics. Joining the army, once a selfless choice to defend the night elf people, had been reduced to a status symbol. At this time, the [[Windstrikers]] developed the gauntlets the Sentinels would wear.\r\nThe [[War of the Ancients]] against the [[Burning Legion]] made the army's deterioration all too clear. After the night elves and their allies had finally achieved victory, High Priestess [[Tyrande Whisperwind]] decreed sweeping changes throughout night elf society. The [[Sisterhood of Elune]] was one of the few major organizations to survive the war largely intact, and membership in its ranks had never been a matter of breeding. Furthermore, members of the order had trained extensively in combat, tactics, and healing. Yet in spite of all their knowledge and experience, the priestesses had become somewhat distant from the rest of night elf society.\r\nTyrande believed that this distance was partly to blame for the cataclysmic war, and she resolved that her order would take up the duty of directing the Sentinels. Never again would the Sisters of Elune fail to guide the night elves. To this day, the General of the Sentinel Army [[Shandris Feathermoon]] still reports to Tyrande, who is both the High Priestess of Elune and, until [[Malfurion Stormrage]] returned, sole ruler of the night elf government.\r\nThese warrior women practiced both the art of combat, as well as that of healing and life-giving in the name of [[Elune]]. The Sentinels quickly came to be considered the elite fighters among the night elves. In particular, they favored the [[moonglaive]] as a weapon of choice. They are led by the [[Priestess of the Moon|priestesses of the moon]] under the High Priestess, Tyrande Whisperwind; her lieutenant, and General of the Sentinel Army, is [[Shandris Feathermoon]]. The Sentinels are comprised of elite night elf archers, a cavalry division known as the [[huntress]]es who ride the feral [[nightsaber]] [[panther]]s, and the mighty [[hippogryph rider]]s, who assault enemies from the air. One of the most important functions of the Sentinels became guarding kaldorei towns and cities. Almost all such settlements possess a contingent of these warriors.\r\nIn addition to their defensive role, the Sentinels were also used to strike at the night elves' foes. 975 years [[BDP]], they, along with other units, rallied under [[Fandral Staghelm]] in [[Silithus]] in the [[War of the Shifting Sands]]. Though they suffered heavy casualties in pushing the [[qiraji]] and [[silithid]] back, the night elves were successful in temporarily ending this threat to [[Kalimdor]].\r\nThe Sentinel Army later fought in the [[Third War]], initially working with [[Cenarius]] against the [[orc]]s of the [[Warsong clan]]. Cenarius and his Sentinel force would ultimately be overrun by the orcish forces (empowered by demon blood), with the [[demi-god]] himself falling. Later, the Sentinels were called on to directly battle the [[demon]]ic [[Burning Legion]] as it pushed into Kalimdor during a wider invasion of [[Azeroth]]. Led directly by High Priestess Tyrande, they launched numerous attacks on both the demons and the [[Horde]] and [[Alliance]] in their forests. Even the Sentinels could not withstand the Legion's advance, however, and were gradually forced back to [[Mount Hyjal]].\r\nDuring the [[Battle of Mount Hyjal]], the Sentinels and the rest of the kaldorei fought heroically alongside the Alliance and Horde to halt the demons. The effort cost all sides dearly, but the elves and their allies were able to buy enough time for a plan devised by [[Malfurion Stormrage]]. Atop the [[World Tree]] [[Nordrassil]], the demon commander [[Archimonde]] would be decisively defeated when the tree's energies were intentionally ignited. The ensuing explosion decimated the demon forces and spelled victory for the night elves.\r\n===Terror of the Tides===\r\nSoon after the victory in the Third War, the Sentinels would accompany Maiev, and eventually Tyrande and Malfurion Stormrage, on a mission to the [[Broken Isles]] and [[Lordaeron]]. Arriving on the Broken Isles, those under Maiev engaged with the vast [[naga]] forces loyal to [[Illidan Stormrage]], and worked their way through the archipelago to the [[Tomb of Sargeras]]. As the conflict progressed, they were reinforced just in time by an expeditionary force from Kalimdor under Tyrande and Malfurion. Together, they shattered Illidan's remaining forces in the area, though the Betrayer escaped to the [[Eastern Kingdoms]].\r\nThe Sentinel expedition quickly pursued Illidan to Lordaeron, where they were attacked by the [[Undead Scourge]] running rampant across the fallen kingdom. Tyrande, Malfurion, and Maiev led the night elves through the onslaught and on to [[Dalaran]] where Illidan was performing a dangerous ritual. Along the way, Tyrande was separated from the other kaldorei, fortifying a small position with a handful of Sentinels downriver. After triumphing over Illidan's naga and more undead at Dalaran, the main night elf force rescued Tyrande and her soldiers just in time, even briefly fighting on the same side as the naga to do so. Their mission complete, Malfurion and Tyrande would return to Kalimdor with their Sentinels, while Maiev and the [[Watchers]] continued their hunt for Illidan.\r\nThe sub-faction called [[Shadowleaves]] existed during the Third War but its current status is unknown. It is possible that it was wiped out or decimated to a point of dissolution during the conflict between the night elves and orcs.\r\n===World of Warcraft===\r\nThe Sentinels and the night elves would find a new home in the form of the [[World Tree]] [[Teldrassil]], off Kalimdor's northern coast. The capital of [[Darnassus]] located here quickly became the center of kaldorei political, spiritual, and military power in the world. Over time, the calm of Teldrassil's enchanted forests would slowly fall into the shadow of a [[Emerald Nightmare|sinister presence]]. Crazed [[furbolg]]s and fouler beasts began to appear on Teldrassil, occupying all the attention of the ever-vigilant Sentinels and the wise [[druid]]s.\r\nFurther to the south, tensions with the [[Horde]] would further demand the presence of the Sentinel Army. Years after the [[Third War]], the night elves began a massive push to retake the forests of [[Ashenvale]]. focusing their efforts on ridding the land of the [[Warsong Outriders]] once and for all. The [[Silverwing Sentinels]] in particular would answer the call, swearing not to rest until every last [[orc]] was defeated and cast out of [[Warsong Gulch]]. To this day, the battle over the area remains fierce. The Sentinels also remained wary of more local threats, such as recent furbolg attacks into Ashenvale.\r\nIn [[Azshara]], the [[tauren]] [[Loh'atu]] promised the Sentinels that he would help them with [[ghost|spirit]]s of the [[Highborne]] in [[Shadowsong Shrine]].\r\nThe night elves also began deploying Sentinels to distant lands at this time, often in honoring their duties as part of the [[Grand Alliance]]. Several units were thus present in [[Alterac Valley]] assisting the [[dwarven]] [[Stormpike Guard]]. A [[Sentinel spies|group]] of Sentinels was likewise sent to pressure the Horde in [[Quel'Thalas]], where they established themselves on [[Shalandis Isle]] with the aim of spying on the [[Blood elf|blood elves]].\r\nThe Sentinels stood alongside their [[Alliance]] brethren during the [[invasion of Outland]], and were among the first Azerothians to push through the reopened [[Dark Portal]]. They would take part in the [[Invasion of Outland|Battle for the Dark Portal]], mostly as archers in support of the front line troops, and continued to hold the line as a foothold was established. Later in the campaign, Sentinel units were active in the region of [[Blade's Edge Mountain]], where they established the outpost of [[Sylvanaar]].\r\nDuring the [[war against the Lich King]] in [[Northrend]], Sentinels were among the multitude of [[Alliance]] forces that composed the [[Valiance Expedition]]. Similarly, many night elf soldiers were by this time members of the [[7th Legion]], which spearheaded the Alliance's advance against the [[Scourge]]. A predominantly Sentinel outpost in the form of [[Stars' Rest]] was established in the [[Dragonblight]], and served as a base for operations against the [[blue dragonflight]] in the area.\r\n===Stormrage===\r\nDuring the [[War Against the Nightmare]], Shandris commanded the Sentinels and the Sisters of Elune to help the inhabitants of the ruined Darnassus. After the [[Xavius|Nightmare Lord]] was defeated and [[Tyrande]] and [[Malfurion]] reunited, they attended the wedding of the night elven leaders, ensuring that no one would cause trouble as well as acting as honor guard during the ceremony.\r\n===The Shattering: Prelude to Cataclysm===\r\nShortly before the [[Cataclysm (event)|Cataclysm]], a dozen Sentinels guarding a crop caravan were attacked and killed by the [[Twilight's Hammer]] cult in [[Ashenvale]]. Blame for the act would, however, be manipulated to fall on the [[Horde]] and their new [[Warchief]] [[Garrosh Hellscream]]. Two soldiers arrived in [[Stormwind City]] to report the attack to High King [[Varian Wrynn]]. These events would result in a meeting between [[Hamuul Runetotem]], [[Elerethe Renferal]], and other [[druid]]s, as well as [[Cairne Bloodhoof]] challenging Garrosh to a [[mak'gora]] duel.\r\n===Wolfheart===\r\nSoon after the evacuation of [[Gilnean]]s, the Sentinels participated in the [[Ashenvale war]].\r\nFollowing Maiev's betrayal, Tyrande appointed Shandris to assist [[Jarod Shadowsong]] in choosing from among the Sentinels some possible candidates for his new security force.\r\n===Before the Storm===\r\nCaptain [[Cordressa Briarbow]]'s unit was sent to act as guards for the [[Explorers' League]] team that was sent to [[Silithus]]. They were ultimately killed by the [[goblin]]s of the [[Horde]].\r\n===Exploring Azeroth===\r\nAfter the Fourth War, Zekhan reported that forest roads in Darkshore were once highly patrolled, but now they're mostly left alone, with Tyrande and her remaining Sentinels focusing their wrath elsewhere. They were still active in Ashenvale and attacking [[Splintertree Post]] regularly and patroling the Ashenvale border with [[Huntress Jalin]]. According to Horde reports, they managed to destroy every siege weapon the Horde brought down from the [[Stonetalon Mountains]], leaving the broken machines and the bodies of engineers at the doorstep of Stardust Spire as a warning to their enemies.\r\n===Organizations===\r\n*[[Silverwing Sentinels]]\r\n*[[Sentinel spies]]\r\n*[[Shadowleaves]]\r\n*[[Moonhunters]]\r\n*[[Starseekers]]\r\n*[[Nightblades]]\r\n===Units===\r\nMembers of the Sentinel Army can be proficient in a wide variety of skills, from [[nightsaber]] and [[hippogryph]] riding to the use of siege weaponry. As such, the army is able to fill many unique roles on the battlefield. Primary examples of these include:\r\n*[[Archer]]s compose the first rank of the Sentinel army. These night elves are expert marksmen and use the concealing forests of [[Kalimdor]] to their advantage. Their lightning-quick ambushes are legendary, for few warriors can match the proud archers' speed and cunning. These are the basic sentinel type, and have formed a key part of kaldorei armies since the days of the [[War of the Ancients]].\r\n*[[Huntress]]es are the elite cadre of the Sentinel army. Drawing their strength from the moon goddess, [[Elune]], these warrior women ride the feral [[nightsaber]] panthers into battle. Huntresses are strong and swift, and merciless to those who would defile the sanctity of the forests. Huntresses also have a close bond with the [[owl]]s of the forest. These owls relay information and spy for the Sentinel army. They are the [[mounted warrior]] version of sentinels, and often act as heavy shock troops.\r\n*[[Hippogryph rider]]s provide aerial support in battle, as well as scouting and reconnaissance. Hippogryph-mounted sentinels usually act as airborne archers, and form an effective mobile rapid-response unit.\r\n*[[Glaive thrower]]s serve as the main siege weapon of the Sentinels, and can be operated by a single individual. Hurling imposing metal glaives across large distances, they can be used to punch through even the toughest of fortifications. Glaive throwers can also be turned to the skies as an effective anti-air deterrent.\r\n==Notes and trivia==\r\n*Many members of the Sentinel Army are themselves referred to as 'Sentinels', though this is not universal.\r\n*During the ''[[Battle for Azeroth]]'' beta, [[Long Away]] said that the Sentinels are divided into the Fourth and Fifth Fleets.\r\n*There was a garrison of the Sentinels in [[Auberdine]]. They and the druids remained as separate as possible from the towns-folk because they were considered misfits and outcasts.\r\n*The Sentinels revere the [[moonwell]]s as shrines to Elune.\r\n*At some point, the [[Night elf|night elves]] which included the Sentinels visited [[Orgrimmar]] as a part of a diplomatic entourage.\r\n*[[Marble Arrowhead]] mentions that it may have belonged to a [[Highborne]] sentinel.\r\n*The Sentinel was also a scrapped [[night elf]] unit in the ''[[Warcraft III: Reign of Chaos|Warcraft III]]'' beta. Its model was recycled for the [[Huntress]] base unit. Its original Battle.net description was the following: ''\"Sentinels are the leaders of the Sentinel army. These powerful warriors draw their strength from the moon goddess, [[Elune]], and show little compassion or mercy to those who would disrupt the natural harmony of the Night Elves' proud culture. Sentinels are fond of using owls as scouts and are able to maintain a primitive telepathic rapport with their owls. Through this link, the Sentinels are able to see far across any environment as if they were looking through their owl's eyes. Sentinels are strong and swift, but unlike most Night Elf warriors, they wear sturdy suits of light armor. Like all Night Elf women, Sentinels are able to [[:Shadowmeld]] at night.\"''\r\n*The [[Warrior's Terrace]] is a gathering spot for the Sentinels.\r\n*While not seen in the game but in World Editor, the faction the player controls in the night elven campaign is called the Sentinels even when controlling [[Illidan]].\r\n*Besides the Shadowleaves, the [[Moonhunters]], [[Starseekers]] and [[Nightblades]] also belonged to the Sentinels.\r\n*Most members of the Sentinels are females, even the [[worgen]] who joined them, but several all-male Sentinel units such as the [[Ashenvale Ambusher]]s, [[Ashenvale Assailant]]s and [[Ashenvale Skirmisher]]s also appear. [[Stormshield Sentinel]]s may also appear as males. Another male Sentinel was [[Xanon]].\r\n*Sentinel guards and [[wisp]]s can be found among the crews of night elven boats, the latter ones helping find the souls that were lost at sea.\r\n==See also==\r\n*[[Roar of the Seven Lions]]\r\n*[[Sentinel's Companion]]\r\n*[[Twiddle Twirler: Sentinel's Glaive]]",},
			["Sentinel Amarassan"] = { content = "'''Sentinel Amarassan''' is a level 27 [[elite]] [[rare mob]] [[night elf]] found in southern [[Stonetalon Peak]] in the [[Stonetalon Mountains]]. She can be found patroling the route between the ruins at the center of [[Stonetalon Peak]] and the entrance to [[Talon Den]]. She is friendly towards Alliance players.\r\n==Abilities==\r\n*[[Wrath]]",},
			["Sentinel Army"] = { content = "#REDIRECT [[Sentinels]]", redirect = "Sentinels",},
			["Sentinel Arynia Cloudsbreak"] = { content = "'''Sentinel Arynia Cloudsbreak''' is a level 10 [[quest giver]] located in [[the Oracle Glade]] in the [[night elf]] starting zone, [[Teldrassil]]. She may be related to [[Mavoris Cloudsbreak]].\r\nShe starts or ends the following quests:\r\n* The Enchanted Glade\r\n* Teldrassil\r\n* Mist\r\nSee [[List of Teldrassil NPCs]].",},
			["Sentinel Brightgrass"] = { content = "'''Sentinel Brightgrass''' is a [[night elf]] stationed onboard [[the Bravery|the ''Bravery'']], the boat that runs between [[Stormwind Harbor]] and [[Auberdine]]. She is one of the [[Sentinels]] from [[Darnassus]] placed on the ship to protect the passengers from harm. She, however, will not attack a [[Horde]] member unless they themselves attack her.\r\n==Notes==\r\n* Although not flagged for PvP, she will flag her attackers.",},
			["Sentinel Hill"] = { content = "'''Sentinel Hill''' is an Alliance outpost in [[Westfall]] and their last stronghold in the region. It is here that the men and women of [[The People's Militia]] make their final stand against the [[Defias]] in a desperate last attempt to reclaim their homes. It's current population is around 300. \r\nMost [[human]] characters visit during their adventures sometime after level 10. Sentinel Hill is located southwest of [[Stormwind]] and has only a few vendors. You can also find [[the Defias Traitor]] at the [[Sentinel Tower]].\r\nIt has a [[Flight Path]] ([[Gryphon]] roost), a barracks-like [[Inn]], a [[Mailbox]], and a [[forge]] and [[anvil]] next to the lumber mill down the hill from [[Sentinel Tower]]. In this area where you will receive missions for the [[Deadmines]], and it is closer to [[Raven Hill Cemetery]] than [[Darkshire]] is, if you are doing missions there.\r\nRaids on Sentinel Hill with the goal to kill [[Gryan Stoutmantle]] are common, mostly to provoke a response from nearby Stormwind and draw Alliance players away in preparations for attacks on the city. In addition, the farm just to the right of the road from Sentinel Tower seems to be a popular spot for [[gold farmer|gold farming]]; lower-level gold farmers are often seen remaining in that small area, killing the same boars and vultures over and over.\r\n==NPCs in S­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­entinel Hill==\r\n* [[Thor]] - <[[Flight Master|Gryphon Master]]>, see : [[Westfall|Westfall Travel Hubs]]\r\n* [[Quartermaster Lewis]] - <Quartermaster>\r\n* [[Kirk Maxwell]] - <Stable Master>\r\n* [[Innkeeper Heather]] - <Innkeeper>\r\n* [[Christopher Hewen]] - <General Trade Goods Vendor>\r\n* [[Mike Miller]] - <Bread Merchant>\r\n* [[William MacGregor]] - <Bowyer>\r\n* [[Gina MacGregor]] - <Trade Supplies>\r\n==Graveyard==\r\nThere is a graveyard just outside of Sentinel Hill. Blizzard refers to it as a \"default graveyard\" and so it will be your spawn point if you cannot spawn anywhere else (for example, if your 10-day trial of Burning Crusade expires but you are still in Outland and your hearthstone is bound to Shattrath City).\r\n==Flight Connections==\r\n [[Stormwind]]\r\n [[Lakeshire]]\r\n [[Darkshire]]\r\n [[Rebel Camp]]\r\n [[Booty Bay]]",},
			["Sentinel Leader"] = { content = "One of the leaders of the [[night elven]] expedition sent to spy on [[Quel'Thalas]]. She resides at [[An'daroth]], although the expedition's actual headquarters is on [[Shalandis Isle]].\r\n==Expedition info==\r\nThe expedition is using scrying orbs to attempt to gain information on Thalassian activities.\r\nThe expedition includes several ranks of [[Sentinels]] and [[Druids]] from [[Darnassus]]; namely:\r\n*[[Sentinel Infiltrator]]s\r\n*[[Sentinel Spy|Sentinel Spies]]\r\n*[[Darnassian Huntress]]es\r\n*[[Darnassian Druid]]s\r\n*[[Night Elf Ambusher]]s\r\n*[[Darnassian Scout]]s",},
			["Sentinel Luciel Starwhisper"] = { content = "'''Sentinel Luciel Starwhisper''' is a level 30 [[quest giver]] located at [[Forest Song]] in the [[contested]] territory of [[Ashenvale]]. She may be related to [[Jenai Starwhisper]].\r\nShe starts the following quests:\r\n* Report from the Northern Front\r\n* Agents of Destruction\r\nSee [[List of Ashenvale NPCs]].",},
			["Sentinel Melyria Frostshadow"] = { content = "'''Sentinel Melyria Frostshadow''' is a level 25 [[quest giver]] located at [[Forest Song]] in the [[contested]] territory of [[Ashenvale]]. She has been assigned to continue the work of [[Velinde Starsong]] clearing [[Ashenvale Forest]] and [[Felwood]] of [[demon]]s. She wants to find out more of the origin of \"wolf-men\" in Ashenvale near the border to Felwood. Before patch 2.01, she was located at the [[Shrine of Aessina]].\r\nShe gives the following quests:\r\n* The Howling Vale\r\n* Velinde Starsong\r\nSee [[List of Ashenvale NPCs]].",},
			["Sentinel Spy"] = { content = "'''Sentinel Spy''' can be found in [[Ghostlands]] . They are agents from [[night elven]] lands sent to [[Quel'Thalas]] to spy on the [[blood elves]]. The [[Sentinel Leader]] is one of the expedition's officers.\r\n==Quests== \r\n==Drops == \r\n \r\n0.12% Chance of an [[Uncommon]] drop.\r\n0.16% Chance of a [[common]] drop.\r\n0.14% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Sentinel Tower"] = { content = "'''Sentinel Tower''' is a prominent landmark in [[Westfall]]. It stands upon the apex of [[Sentinel Hill]] as a scout tower to watch over the surrounding farmscape. This is where one can find [[the People's Militia]]'s leaders, including [[Gryan Stoutmantle]], the group's commander.",},
			["Sentinel Tysha Moonblade"] = { content = "'''Sentinel Tysha Moonblade''' is a level 10 [[quest giver]] located on the road just west of [[Ameth'Aran]] in the [[night elven]] zone of [[Darkshore]]. She may be related to [[Mariner Moonblade]].\r\nShe starts the quest The Fall of Ameth'Aran.\r\nSee [[List of Darkshore NPCs]].",},
			["Sentinel Velene Starstrike"] = { content = "'''Sentinel Velene Starstrike''' is a level 25 [[quest giver]] located at [[Silverwind Refuge]] in the [[contested]] territory of [[Ashenvale]].\r\nShe gives the following quests:\r\n* Elemental Bracers\r\n* Mage Summoner\r\nSee [[List of Ashenvale NPCs]].\r\nShe might be related to [[Layo Starstrike]], who is currently in Silithus.",},
			["Sentinel Winterdew"] = { content = "'''Sentinel Winterdew''' is a [[night elf]] stationed onboard [[the Bravery|the ''Bravery'']], the boat that runs between [[Stormwind Harbor]] and [[Auberdine]]. She is one of the [[Sentinels]] from [[Darnassus]] placed on the ship to protect the crew. She, however, will not attack a [[Horde]] member unless they themselves attack her.\r\n==Notes==\r\n* Although not flagged for PvP, she will flag her attackers.",},
			["Sentry Point"] = { content = "'''Sentry Point''' is a tower built by the denizens of [[Theramore Isle]] located on the mainland of [[Dustwallow Marsh]] just across the bridge from the citadel itself. The tower acts as its name suggests, watching the comings and goings on the road to Theramore.",},
			["Separation Anxiety (quest)"] = { content = "==Objectives==\r\n[[Huntsman Markhor]] at [[Revantusk Village]] in the Hinterlands wants you to recover his twin brother's remains. Find and return [[Huntsman Malkhor's Skull]] and [[Huntsman Malkhor's Bones]] to [[Huntsman Markhor]].\r\nMarkhor mentioned that his brother's remains were fed to the [[ooze]]s and [[wolves]] of the [[Vilebranch]]. He also mentioned that there is a refuse pit filled with [[ooze]]s in [[Jintha'alor]] as well as a wolf den. Both of these places are near the top of the temple. \r\n*Huntsman Malkhor's Skull\r\n*Huntsman Malkhor's Bones\r\n== Description==\r\nLike many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch.\r\nSadly, he was not fated to live and was given a swift, brutal execution; his remains fed to the oozes and wolves of the Vilebranch.\r\nIt is too late to save his life but not too late to save his soul. Recover his remains, <name>.\r\n==Progress==\r\nWhen I have his remains, I shall take them to [[Mystic Yayo'jin|Yayo'jin]] and have them prepared for a proper burial. \r\n==Completion==\r\nMy dearest brother, how I will miss you...\r\nThank you for your assistance, <name>. You are truly a hero in my eyes. \r\n==Rewards==\r\nYou will also receive: 75 silver copper \r\n==Gains==\r\n*6800 [[XP]]\r\n==Details==\r\nThe bones are located in the middle of a sludge pit near the top tier, at (62,75). The skull is on the top tier at (59,65).",},
			["Sepethrea"] = { content = "#REDIRECT [[Nethermancer Sepethrea]]", redirect = "Nethermancer Sepethrea",},
			["Sepulcher"] = { content = "'''The Sepulcher''', also known as the '''Silverpine Sepulcher''', is a [[Forsaken]] base located in the western side of [[Silverpine Forest]]. The area itself lies above the [[Lordaeron]]ian coastline, nestled within the surrounding hills. It was nothing more than a large graveyard and string of expeditionary caravans and individuals.\r\n===World of Warcraft===\r\nAs its name suggests, the Sepulcher was once nothing more than a graveyard along the road crossing Silverpine. Since the end of the [[Third War]] however, the enterprising [[Forsaken]] converted the old [[crypt]] into their base of operations in the region. With the [[worgen]] to the south, the [[Scourge]] to the east, and the forces of [[Kirin Tor]] to the southeast, it was one of the only places of safety for [[Horde]] adventurers in the entire zone.\r\n==NPCs==\r\n*High Executor Hadrec\r\n*Advisor Sorrelon\r\n*Mura Runetotem\r\n*Apothecary Renferrel\r\n*Shadow Priest Allister\r\n*Dalar Dawnweaver\r\n*Astor Hadren\r\n*Sarah Goode\r\n*Karos Razok\r\nTrainers\r\n*Bee Bruxworthy\r\n*Angela Hipple\r\n*Dark Cleric Pordon\r\n*Eugene Daller\r\n*Johan Focht\r\n*Guillaume Sorouy\r\n*Matt Bruxworthy\r\n**Hobbes\r\n*Thom Denger\r\nMerchants\r\n*Innkeeper Bates\r\n*Andrew Hilbert\r\n*Sebastian Meloche\r\n*Patrice Dwyer\r\n*Edwin Harly\r\n*Gwyn Farrow\r\n*Nadia Vernon\r\n*Alexandre Lefevre\r\n*Andrea Boynton\r\n*Lilly\r\nGuards\r\n*Deathguard Podrig\r\n* Dreadguard (NPC)\r\n* Silverpine Deathguard",},
			["Sepulcher of the First Ones"] = { content = "''Not to be confused with the [[Sepulcher]] (a town in [[Silverpine Forest]]) or the [[Sepulcher of Knowledge]] (a library in [[Maldraxxus]]).''\r\nThe '''Sepulcher of the First Ones''' is the final [[raid]] instance of the ''[[World of Warcraft: Shadowlands|Shadowlands]]'' expansion, located east of [[Zereth Mortis]]. It is an ancient place of power, containing secrets of the eponymous [[First Ones]] that [[the Jailer]] seeks to use to rewrite the rules of the universe.\r\n==Background==\r\nThe Sepulcher is a place that should not be able to exist according to the laws of physics as they are known on [[Azeroth]]. Prior to the Jailer's attack, the Sepulcher's location was a closely guarded secret. The [[attendant]]s of [[Korthia]] were forbidden from discussing it, even with allies.\r\nLong ago, the Jailer sought to unmake the balance of the cosmos and tried to claim the [[sigil]]s of the other [[Eternal Ones]], believing that they were keys to forbidden knowledge locked within the Sepulcher that would allow him to unravel the cosmos. The [[Primus]] believed that if the Jailer obtained all five sigils, nothing would be able to stop him from reaching the Sepulcher. The Primus was eventually proven right, when the Jailer managed to collect all five sigils and opened a portal to Zereth Mortis from [[Oribos]].\r\nThe [[broker]]s of [[Cartel Ba]] and [[Cartel Al]] have also been looking for the Sepulcher. The Al outbid [[Cartel Ta]] on leading an expedition to search for the Sepulcher. The mission was believed to have ended in failure, but in reality, the seekers found Zereth Mortis and became the [[Enlightened]].\r\n===Dungeon Journal===\r\n''The Jailer has breached the Sepulcher, the mysterious heart of the Shadowlands. Should he control its primordial power, he will reshape the cosmos with Death at the fore. As Zovaal prepares to dominate reality, champions of [[Azeroth]] charge forth to stop him. Will their resolve outmatch his?''\r\n==Encounters==\r\nEphemeral Plains\r\n''The essence of creation is being devoured. If left unchecked, reality will collapse.''\r\n*Vigilant Guardian\r\n*Skolex\r\n*Artificer Xy'mox (Sepulcher of the First Ones)\r\n*Halondrus\r\nCornerstone of Creation\r\n''Lihuvim fights a losing battle against domination. Unless saved, the keeper's power will become the Jailer's.''\r\n*Dausegne\r\n* Prototype Pantheon\r\n*Lihuvim\r\nDomination's Grasp\r\n''The constellar has observed millions of civilations end. Will he now witness Zovaal unmake the universe?''\r\n*Anduin Wrynn (tactics)\r\n*Lords of Dread\r\n*Rygelon\r\nThe Grand Design\r\n''Zovaal sits on the cusp of ultimate victory. Unless stopped, the cosmos will succumb to his power.''\r\n*The Jailer (tactics)\r\n==Opening dates==\r\nTo queue for [[Raid Finder]] wings, an average item level of 220 is required.\r\n==Getting there==\r\nGaining full access to the [[Ancient Translocator]] is unlocked from [[The Pilgrimage Ends]], as part of the fourth chapter of [[Secrets of the First Ones]].\r\n==Achievements==\r\n<div style=\"columns:20em\">\r\n*[[Sepulcher of the First Ones (achievement)]]\r\n**[[Ephemeral Plains (achievement)]]\r\n**[[Cornerstone of Creation]]\r\n**[[Domination's Grasp]]\r\n**[[The Grand Design]]\r\n*[[Heroic: Sepulcher of the First Ones]]\r\n**[[Ahead of the Curve: The Jailer]]\r\n*[[Mythic: Sepulcher of the First Ones]]\r\n**[[Cutting Edge: The Jailer]]\r\n*#[[Mythic: Vigilant Guardian]]\r\n*#[[Mythic: Dausegne]]\r\n*#[[Mythic: Artificer Xy'mox (Sepulcher of the First Ones)]]\r\n*#[[Mythic: Prototype Pantheon]]\r\n*#[[Mythic: Skolex]]\r\n*#[[Mythic: Halondrus]]\r\n*#[[Mythic: Lihuvim]]\r\n*#[[Mythic: Anduin Wrynn]]\r\n*#[[Mythic: Lords of Dread]]\r\n*#[[Mythic: Rygelon]]\r\n*#[[Mythic: The Jailer]]\r\n*##[[Hall of Fame: The Jailer (Alliance)]]\r\n*##[[Hall of Fame: The Jailer (Horde)]]\r\n*[[Glory of the Sepulcher Raider]]\r\n**[[Amidst Ourselves]]\r\n**[[Coming to Terms]]\r\n**[[Damnation Aviation]]\r\n**[[Four Ring Circus]]\r\n**[[Power ON]]\r\n**[[Shimmering Secrets]]\r\n**[[The Protoform Matrix]]\r\n**[[We Are All Made of Stars]]\r\n**[[Where the Wild Corgis Are]]\r\n**[[Wisdom Comes From the Desert]]\r\n**[[Xy Never, Ever Marks the Spot.]]\r\n*[[Sepulcher of the First Ones Guild Run]]\r\n*[[Heroic Sepulcher of the First Ones Guild Run]]\r\n</div>\r\n==Loot==\r\nItems in the raid drop at two item levels per difficulty: the first eight bosses drop at one item level, and the last two (Kel'Thuzad and Sylvanas Windrunner) drop at a higher item level.\r\n===Notable drops===\r\nBeyond the normal item drops, there are a handful of unique items or item effects that are found in the raid.\r\n==Notes==\r\n*The Sepulcher of the First Ones marks the return of class-specific [[tier]] sets, being the first raid to feature them since [[Antorus, the Burning Throne]] in ''[[World of Warcraft: Legion|Legion]]''.",},
			["Seradane"] = { content = "'''Seradane''' is an area in northeastern part of [[The Hinterlands]] which houses one of the four entrances to the [[Emerald Dream]]. Many high-level [[elite]] green [[dragon]]s make their home here, including the [[drake]]s [[Rothos]] and [[Dreamtracker]].\r\nOne of the [[Dragons of Nightmare]] ([[Emeriss]], [[Lethon]], [[Taerar]], [[Ysondre]]) may also appear here.\r\nThe skull of an unknown dragon is also to be found lying on top of a hill slightly to the north of the portal.\r\nAnother point to note is that similar faced stones surrounding this skull can also be found making up a couple of the Circles of Binding in the [[Arathi Highlands]], namely the [[Circle of East Binding]], and [[Circle of Outer Binding]].",},
			["Serathil"] = { content = "'''Serathil''' is a one-handed axe. It is a [[world drop]], and one of few items to be in both [[Warcraft III]] and [[World of Warcraft]].\r\n==Background==\r\n[[Rexxar]] sought to join the [[Stonemaul]] [[clan]]. Their leader, the tyranical [[Kor'gall]], had discovered the ancient orcish axe Serathil and used the artifact to control the clan. He forced Rexxar to undergo the Trial of Strength, running a monster filled gauntlet, to join. Rexxar succeeded, but Kor'gall still refused to help the [[Horde]]. Rexxar sensed the corruption within Kor'gall and slew the ogre chieftain in the Trial of Blood, earning Serathil and assuming control of the clan to lead them against the [[Alliance]].",},
			["Serena Bloodfeather"] = { content = "'''Serena Bloodfeather''' is a level 20 [[named]] [[harpy]] in the northwest corner of the [[Dry Hills]] of [[The Barrens]]. She is the Witchwing harpies leader, and sister to the deceased [[Bloodfeather]].\r\nShe has been attacking [[Horde]] caravans out of revenge for [[Rexxar]]'s slaying of Bloodfeather. [[Darsok Swiftdagger]] at the [[Crossroads]] would like Serena to share her sister's fate.\r\n==Quests==\r\n*Serena Bloodfeather\r\n==Loot==\r\n*Serena's Head ''(Quest Item)''",},
			["Serena Bloodfeather (quest)"] = { content = "Serena Bloodfeather is the 3rd quest in the '''Harpy Raiders''' quest chain.\r\n==Objectives==\r\nSlay [[Serena Bloodfeather]] and return her head to [[Darsok Swiftdagger]] at the [[Crossroads]].\r\n*Serena's Head\r\n==Description==\r\nYou did so well with the lieutenants and underlings that I'd like you to do one last thing for me.\r\nSerena Bloodfeather is the sister of a harpy named [[Bloodfeather]] who was slain by [[Rexxar]] quite a while ago. Apparently, these attacks on the Horde caravans are revenge for her sister's death.\r\nI need you to slit her throat and bring me back her head. I want to place it on the next caravan we send out... Give those harpies something to think about.\r\n==Progress==\r\nYou're not getting anything until I see Serena's head.\r\n==Completion==\r\nHA! Well done, <name>! Very well done... I wasn't sure you were up to the task, but you've proved yourself quite the cut-throat. Thank you again for helping us suppress the Harpy epidemic. Here is your reward, use it well.\r\n==Gains==\r\n*1950 [[XP]] (or s=12 gold at level 70)\r\n*350 [[reputation]] with [[Orgrimmar]]\r\n==Quest chain== \r\n#Harpy Raiders\r\n#Harpy Lieutenants\r\n#Serena Bloodfeather\r\n==Notes==\r\nThis time I want you to assassinate some of the harpy lieutenants in the Dry Hills. Only Witchwing Slayers can be lieutenants, and you can tell them apart by the rings they carry. They are a nasty bunch, but they lead some of the underlings in that area. Taking out 6 of them will be a decisive strike against their matriarchy.",},
			["Serena Scarscale"] = { content = "'''Serena Scarscale''' is a [[Naga Sea Witch]] featured in the Warcraft III Frozen Throne Expansion mission [[Wrath of the Betrayer]].\r\n==Statistics from Warcraft III==\r\n* 625 HP\r\n* 450 MP\r\n* 32-38 hero damage\r\n* 3 hero armor\r\n* Attributes\r\n** 21 Strength\r\n** 17 Agiliity\r\n** 30 Intelligence '''Primary Attribute'''\r\n* Abilities\r\n** Frost Arrows (slows target and + damage)\r\n** Forked Lightning (multiple target damage)\r\n** Mana Shield (attackers damage mana instead of hit points)\r\n** Tornado (summons a tornado that incapacitates enemies)",},
			["Serenity (mace)"] = { content = "'''Serenity''' is a crafted mace that has a dispel proc.\r\n==Source==\r\nThis item is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 285. [[Hammersmith]] sub-specialization is not (or perhaps \"no longer\") required.\r\nMaterials required:\r\n* 6x Enchanted Thorium Bar\r\n* 2x Arcanite Bar\r\n* 4x Powerful Mojo\r\n* 2x Large Opal\r\n* 2x Blue Sapphire\r\n* 1x Huge Emerald\r\nPlans: Serenity can be found inside [[Stratholme]].\r\n==See also==\r\n* Sweet Serenity\r\n* [[Plans: Serenity]]\r\n* [[Blacksmithing Plans]]",},
			["Sergeant"] = { content = "Are you looking for the character named \"[[Sergeant (character)|Sergeant]]\"?\r\n&ndash;OR&ndash;\r\nThe [[PvP]] rank of [[Title|Sergeant]]?",},
			["Sergeant (Character)"] = { content = "#REDIRECT [[Sergeant (character)]]", redirect = "Sergeant (character)",},
			["Sergeant Amelyn"] = { content = "'''Sergeant Amelyn''' is a level 54 [[quest giver]] located on [[Theramore Isle]] in the [[contested]] territory of [[Dustwallow Marsh]]. She is in front of the defunct fountain near the docks.\r\nShe starts the following quests:\r\n* This Old Lighthouse\r\n* The Hermit of Swamplight Manor\r\nSee [[List of Dustwallow Marsh NPCs]].",},
			["Sergeant Bly"] = { content = "'''Sergeant Bly''' is a level 45 [[elite]] [[human]] found in [[Zul'Farrak]]. Bly is and assists during the Pyramid battle, but becomes when questioned about the [[Divino-matic Rod]].\r\nSee [[Zul'Farrak NPCs]].\r\n==Objective of==\r\n*Drops Divino-matic Rod for the quest Divino-matic Rod.",},
			["Sergeant Brashclaw"] = { content = "'''Sergeant Brashclaw''' is a level 18 [[rare mob]] [[gnoll]] found in a [[gnoll]] camp north of [[Gol'Bolar Quarry]] in [[Westfall]]. He is on a 2-3 hour respawn timer.\r\n==Loot==\r\n*Brashclaw's Chopper\r\n*Brashclaw's Skewer",},
			["Sergeant Chawni"] = { content = "'''Sergeant Chawni''' is a level 65 [[quest giver]] located at [[Stonebreaker Camp]] in the [[contested]] territory of [[Terokkar Forest]]. She is looking into rumors of a bomb created by the blood elves at [[Firewing Point]].\r\nShe starts the following quests:\r\n* Attack on Firewing Point\r\n* The Final Code\r\nSee [[List of Terokkar Forest NPCs]].",},
			["Sergeant Hartman"] = { content = "'''Sergeant Hartman''' is a level 60 [[quest giver]] located in [[Southshore]] in the [[contested]] territory of [[Hillsbrad Foothills]]. He is only available during the annual [[Hallow's End]] event.\r\nHis name appears to be a reference to Gunnery Sergeant Hartman, the sadistic drill instructor played by [[w:R. Lee Ermey|R. Lee Ermey]] in the film ''[[w:Full Metal Jacket|Full Metal Jacket]]''.\r\nHe starts the following quests:\r\n* Crashing the Wickerman Festival (PvP) ([[Hallow's End]])\r\n* The Power of Pine (PvP) ([[Hallow's End]])\r\nSee [[List of Hillsbrad Foothills NPCs]].",},
			["Sergeant Kan'ren"] = { content = "'''Sergeant Kan'ren''' is a level 7 [[quest ender]] located at [[Falconwing Square]] in the [[blood elf]] starting zone of [[Eversong Woods]]. He is harsh towards Wretched especially the captured one that stands (and kneels) in front of him. However, this is understandable considering the Wretched killed two of his men in the last month.\r\n==Quests==\r\n* ends Wanted: Thaelis the Hungerer\r\n==See Also==\r\n*[[List of Eversong Woods NPCs]]",},
			["Sergeant Kien"] = { content = "This NPC could be found in [[Hall of Legends]] between [[Patch 2.1]] and [[Patch 2.3]]. He may be related to [[Joshua Kien]].",},
			["Sergeant Major Clate"] = { content = "'''Sergeant Major Clate''' is a level 55 [[PvP]] [[armor]] [[vendor]] located in the [[Champions' Hall]] in the [[human]] city of [[Stormwind]].\r\nSee [[List of Stormwind NPCs]].",},
			["Sergeant Major Germaine"] = { content = "'''Sergeant Major Germaine''' is a level 60 quest giver located at [[the Military Ward]] within the [[dwarf]] city of [[Ironforge]]. She may be related to [[Ander Germaine]].\r\nShe is involved in the following quests:\r\n* The Alliance Needs Arthas' Tears! ([[Gates of Ahn'Qiraj|Ahn'Qiraj War Effort]])\r\n* The Alliance Needs More Arthas' Tears! (repeatable, [[Gates of Ahn'Qiraj|Ahn'Qiraj War Effort]])\r\n==NOTE==\r\nShe is only available during the [[Gates of Ahn'Qiraj|Ahn'Qiraj War Effort]] world event.\r\nSee [[List of Ironforge NPCs]].",},
			["Sergeant Major Skyshadow"] = { content = "'''Sergeant Major Skyshadow''' can be found in [[Champions' Hall]].",},
			["Sergeant Thunderhorn"] = { content = "'''Sergeant Thunderhorn''' is a level 65 [[PvP]] [[weapons]] [[vendor]] located in the [[Hall of Legends]] in the [[orcish]] city of [[Orgrimmar]].\r\nSee [[List of Orgrimmar NPCs]].",},
			["Sergra Darkthorn"] = { content = "'''Sergra Darkthorn''' is a level 60 [[quest giver]] located at the [[Crossroads]] in the [[Horde]]-aligned territory of the [[Barrens]]. After a [[patch]], Sergra was buffed from level 34 to level 60 [[elite]], and has since gained some fame for killing numerous [[Alliance]] characters during their frequent raids on [[Crossroads]].\r\n==Quests==\r\n* finishes Sergra Darkthorn\r\n* finishes Crossroads Conscription\r\n* Plainstrider Menace\r\n* The Zhevra\r\n* Prowlers of the Barrens\r\n* Echeyakee\r\n* The Angry Scytheclaws\r\n* starts Jorn Skyseer\r\n==See Also==\r\n* [[List of the Barrens NPCs]]",},
			["Seriadne"] = { content = "'''Seriadne''' is a level 55 [[Stable Master|stable master]] located in [[Dolanaar]] in the [[night elven]] starting zone of [[Teldrassil]].\r\nSee [[List of Teldrassil NPCs]].",},
			["Serinar"] = { content = "==Quests==\r\nHe ends the following quest(s):\r\n*The Obsidian Dragonshrine\r\nHe starts and ends the quests:\r\n# No Place to Run & No One to Save You\r\n# The Best of Intentions\r\n# Defiling the Defilers & Culling the Damned\r\n# Neltharion's Flame\r\nHe starts the quest(s):\r\n# Tales of Destruction\r\n==Quotes==\r\n*I've played my part in destroying entire civilizations... to have to lower myself to dealing with the wretched [[Cult of the Damned]] disgusts me.",},
			["Serpent's Coil"] = { content = "'''Serpent's Coil''' is a winding cave system that had been occupied by evil cultists worshipping [[Kirith the Damned]]. It is located in the eastern [[Blasted Lands]], in sight of [[Nethergarde Keep]]. Several burnt-out [[orcish]] structures stand here, remnants from the [[Second War]].\r\n[[Archmage Allistarj]] operates his [[Shadowsworn]] forces from within this small labyrinth. Many [[high elven]] cult members can be found here.",},
			["Serpent's Fangs"] = { content = "==Random enchantments==",},
			["Serpent"] = { content = "A cobra-like [[snake]] that comes in a variety of colors. They are good swimmers and attack with their fangs and [[Poison Spit]]. Serpents are found in the [[Wailing Caverns]], [[Zul'Gurub]], [[Zul'Farrak]], the [[Sunken Temple]], and [[Shadowmoon Valley]].\r\nSerpents were not normally tamable for a long time. The [[Sandfury Guardian]] was briefly tamable as a bug (classified as a [[wind serpent]]). However, the family was rendered tamable with [[Patch 2.0]]. \r\n==As a [[Hunter]] Pet==\r\nOnce popular shortly before the release of the Burning Crusade for their intimidating appearance and novelty. Their [[Poison Spit]], if not carefully managed, easily disrupts [[crowd control]].",},
			["Serpentshrine Cavern"] = { content = "'''Serpentshrine Cavern''' is the raid wing of [[Coilfang Reservoir]], where Lady Vashj has made her lair. It is a 25-man raid instance with six bosses, culminating with Lady Vashj herself. There is [[|no longer an attunement]] required to enter this instance.\r\nFor most raids, Serpentshrine Cavern will come only after the raid has been farming [[Karazhan]] as well as [[Gruul's Lair]]. \r\n==General==\r\n*Tokens for [[Tier 5]] gloves, legs, and helms drop in the '''Serpentshrine Cavern'''.\r\n*[[Lady Vashj (tactics)|Lady Vashj]], the last boss, drops the second quest item needed to be attuned to Mount Hyjal: Vashj's Vial Remnant. The quest can be found here: The Vials of Eternity\r\n*In an interesting twist The Lurker Below must be fished out of his pool rather than pulled.\r\n* There is no required boss order in this zone, as there are several paths from the zone-in to [[Lady Vashj (tactics)|Lady Vashj]]. The main 'cavern' is composed of a collection of large bridges and platforms above water. By using waterwalking you can start pretty much anywhere. Creative mechanics will be needed to begin waterwalking so you don't break the water when you jump down onto it (paladin bubbles, Slow Fall, etc...).\r\n===NPC Respawn Timer===\r\nRespawn timer for all trash groups is 2 hours. If their related boss is defeated, they will not respawn.\r\n==The water==\r\n*Coilfang Frenzy are fish that attack anyone who enters the water, to prevent skipping areas. The longer you are in the water, the more fish spawn. They will despawn once you are out of the water or dead. Once The Lurker Below is defeated, these will no longer spawn. Any forms of waterwalk (i.e. priest's Levitation) prevent the mobs from attacking. \r\n===Scalding Water===\r\nAs long as the 6 platform packs surrounding The Lurker Below are cleared, the water will be boiling, killing all of the Coilfang Frenzy in the water. Entering the water during this condition results in a [[Scalding Water]] debuff, which inflicts 500 damage every 3 seconds (avoidable by using any forms of waterwalk). This is considerably less damage than attacks from the Coilfang Frenzy. If the platform packs respawn, the water stops boiling and the Coilfang Frenzy return.\r\nDefeating The Lurker Below prevents both the [[Scalding Water]] and the Coilfang Frenzy, allowing more convenient navigation of the instance.\r\n==NPCs related to Hydross the Unstable==\r\nOnce Hydross the Unstable is killed these will no longer spawn.\r\n===Pack type 1===\r\nThis is the first type of pack you'll encounter as you enter. There are about 3 of these packs before Hydross the Unstable. 5 tanking classes of some sort can be used, although the Serpentshrine Sporebats can be CC'd when not enraged. Tank the Coilfang Hate-Screamers away from the group to prevent silence. Burn the Coilfang Beast-Tamer while his Serpentshrine Sporebats are tanked (they randomly charge). Once the Coilfang Beast-Tamer is dead, the Serpentshrine Sporebats will lose their enrage, at which time they can be [[Crowd Control]]led. Burn the Coilfang Hate-Screamers and then finish off the bats at your leisure. \r\nNote: If the Serpentshrine Sporebats are sheeped far enough away from the Coilfang Beast-Tamer, occasionally they do not become enraged and break sheep.\r\n*Coilfang Beast-Tamer x 1\r\n*Coilfang Hate-Screamer x 2\r\n*Serpentshrine Sporebat x 2\r\n===Underbog Colossus === \r\nUnderbog Colossus appear as single pulls between each of the Pack type 1's. Although their abilities can require some thought, they are relatively easy. Nature resist gear helps.\r\n===Platform around Hydross the Unstable === \r\nThese mobs move around Hydross the Unstable's platform Tainted Water Elementals come from the right and stop in front of Hydross the Unstable and become Purified Water Elemental then continue along the platform. They have relatively low hit points but a huge aggro range.\r\nTainted Water Elemental\r\nPurified Water Elemental\r\n===Hydross the Unstable encounter === \r\nDuring the encounter when Hydross the Unstable changes form he will spawn 4 adds. Tainted Spawn of Hydross for poison form or Pure Spawn of Hydross for water from.\r\nTainted Spawn of Hydross \r\nPure Spawn of Hydross\r\n==NPCs related to The Lurker Below==\r\nOnce The Lurker Below is killed these will no longer respawn. In addition, the [[Scalding Water]] and Coilfang Frenzy are removed.\r\n===Pack type 2===\r\nThese occur on the 6 platforms encircling the The Lurker Below's pool. Each pack consists of 1 Vashj'ir Honor Guard, 2 Coilfang Shatterers, 2 Coilfang Priestess and 4 Greyheart Technician. [[Crowd control]] the Greyheart Technicians and Coilfang Priestesses, then focus damage on the Coilfang Shatterers first, Vashj'ir Honor Guard next. The Greyheart Technicians are weak and can be killed very fast when lacking CC (a single Rogue can easily take one down).\r\n*Vashj'ir Honor Guard x 1\r\n*Coilfang Shatterer x 2 \r\n*Coilfang Priestess x 2 \r\n*Greyheart Technician x 4\r\n'''Note''': On the third group it is possible to accidentally pull the patrolling Underbog Colossus from the platform to the left by standing too far to the left hand side. Everyone should stay to the right hand side of the third platform.\r\n===The Lurker Below encounter === \r\nWhen The Lurker Below dives, he spawns a total of 9 adds: 6 ranged Coilfang Ambushers (2 on each platform), and 3 melee Coilfang Guardians. All these adds can be [[Crowd control]]led.\r\nCoilfang Ambusher x 6 \r\nCoilfang Guardian x 3\r\n==NPCs related to Morogrim Tidewalker==\r\nOnce Morogrim Tidewalker is killed these will no longer respawn.\r\n===Pack type 3 === \r\nThese packs occur on the bridge to Morogrim Tidewalker's room. [[Crowd control]] as many Greyhearts as you can, and keep an eye on the Greyheart Tidecaller's totems\r\n*Greyheart Tidecaller x 1 Has a magic buff that has a chance when hit to infect random raid members with a poison which ticks for a massive amount of damage, 2 ticks will kill most people; it can be spell stolen, mass dispelled etc. A felhunter with devour magic on auto cast can also remove this as soon as it is cast. The Tidecaller also summons totems linked to water elementals, kill these ASAP. (The Elementals can be banished.)\r\n*Coilfang Serpentguard x 2 Uses a spell reflect shield and an aura that reduces armour by 25%. However, the aura is not much of a problem, do not go out of your way to avoid it.\r\n*Greyheart Skulker x 1 Can interrupt casts next to them.\r\n*Greyheart Nether-Mage x 2 Preferably sheep these. They do a large AOE, have 3 different self buffs that increase spell damage done by 300~ or so, can be fun for mages to spell steal these buffs.\r\n===Pack type 4 === \r\nThere is 1 of these packs leading to the room where Morogrim Tidewalker resides. None can be CCed, the Coilfang Fathom-Witches mind control and AoE knockback. Using the convenient wall / platform to your left it's possible to train some of the mobs while you focus on the others. It is also a good idea to have dps hit the Coilfang Fathom-Witches quickly after the pull, they mind control people 2nd on their aggro table and if another tank is 2nd then you will have a loose mob\r\n* Coilfang Serpentguard x 2\r\n* Coilfang Fathom-Witch x 2\r\n===Tidewalker murloc pack === \r\nThese packs run around near Morogrim Tidewalker's room, generally they are packs of 5-6 random murlocs. Their damage is fairly weak, so tanks can tank 2 without much trouble, it is possible to have a Paladin tank multiple groups of these monsters at once, however it is wise to have additional tanks ready to taunt the Tidewalker Warriors if / when they drop aggro due to Righteous Defense being on a 15 second cooldown.\r\n*Tidewalker Depth-Seer\r\n** can't be stunned\r\n*Tidewalker Harpooner\r\n*Tidewalker Hydromancer\r\n*Tidewalker Shaman\r\n** can be stunned\r\n*Tidewalker Lurker\r\n*Tidewalker Warrior - Drop Aggro, [[Frenzy (Power)|Frenzy]]\r\n** can't be stunned, CAN be sheeped\r\n==Fathom-Lord Karathress encounter==\r\nThese are the adds during the Fathom-Lord Karathress encounter.\r\n*Fathom-Guard Caribdis\r\n*Fathom-Guard Sharkkis\r\n*Fathom-Guard Tidalvess\r\n==NPCs related to Leotheras the Blind==\r\nThis is the trash in the room with Leotheras the Blind leading from Karathress. Right and left of the room beyond Leotheras are two of these packs. This is leading from Morogrim's room.\r\n*Greyheart Spellbinder * 3 holding onto Leotheras the Blind they will aggro if you get to close. hang to the left while you clear the room.\r\nPacks: get away from the mushrooms that Serpentshrine Lurker spawn. they explode and release toxic green goo...\r\n*Greyheart Shield-Bearer\r\n*Greyheart Nether-Mage\r\n*Serpentshrine Lurker\r\n*Greyheart Tidecaller * 2\r\n*Greyheart Spellbinder\r\n*Greyheart Skulker\r\nin the middle of those \r\n*Greyheart Tidecaller * 2\r\n*Greyheart Skulker * 2\r\nbeyond that room there is a pack of \r\n*Greyheart Tidecaller * 2\r\n*Greyheart Nether-Mage\r\nNote: Not sure if this changes will check next week\r\n===Leotheras the Blind encounter===\r\n*Inner Demon\r\n==Other trash mobs==\r\n*Coilfang Elite\r\n*Coilfang Guardian\r\n*Coilfang Strider\r\n*Colossus Lurker\r\n*Colossus Rager\r\n*Enchanted Elemental\r\n*Fathom Lurker\r\n*Fathom Sporebat\r\n*Serpentshrine Lurker\r\n*Serpentshrine Parasite\r\n*Serpentshrine Tidecaller\r\n*Toxic Spore Bat\r\n*Underbog Mushroom\r\n*Water Walker Elemental\r\n==Friendly NPC==\r\nSeer Olum\r\n==Loot==\r\nSee [[Serpentshrine Cavern loot]]\r\n==Attunement == \r\n'''--- Not Required ---'''\r\nAs of June 19, 2007, Serpentshrine Cavern no longer has a required attunement to enter.\r\nThe attunement quest chain remains in-game, and must be completed (along with the Tempest Keep raid attunement) in order to obtain the title of [[Champion of the Naaru]].\r\n# Enter the Slave Pens in Heroic Mode.\r\n# Find Skar'this the Heretic captive in a cage before the second boss.\r\n# Complete his quest The Cudgel of Kar'desh.\r\n#* Retrieve the Earthen Signet from Gruul the Dragonkiller.\r\n#* Retrieve the Blazing Signet from Nightbane (boss) in [[Karazhan]].\r\n# Return to Skar'this and he will cast [[The Mark of Vashj]] on you which allows the wearer to enter Serpentshrine Cavern.\r\n==See also==\r\n* [[The Burning Crusade: Guild Progression]] for the world first kills",},
			["Serpentshrine Cavern loot"] = { content = "See [[Serpentshrine Cavern]].",},
			["Serpent Lake"] = { content = "'''Serpent Lake''' is a large lake in northern [[Zangarmarsh]], the largest in [[Outland]]. [[Coilfang Reservoir]] is located in its center.",},
			["Serpent Sting"] = { content = "'''Serpent Sting''' stings the target, causing nature damage over 15 seconds. Only one Sting per [[hunter]] can be active on any one target.\r\n==Notes==\r\nSerpent Sting is a fairly weak [[damage over time]] spell, in comparison to those of other classes. To get the most of out it, it should be used in fights that will last longer than 15 seconds. On short fights and trash mobs, the hunter may find it is not an efficient use of his or her mana.\r\nSerpent Sting can be cleansed by Druids, Paladins, and Shamans, as well as any [[mob]] that can cleanse poison. Rogues are also able to dispel it with [[Cloak of Shadows]]. Dwarves' racial [[Stoneform]] ability also dispels it.\r\nAs with most DoTs (and channelled spells) that don't have a direct initial-damage component, serpent sting cannot crit. So spell and ranged critical rating buffs do not affect this ability.\r\n==Related talents==\r\n*[[Efficiency (Hunter Talent)|Efficiency]] ([[Marksmanship]] [[Talent]]): Reduces the Mana cost of your Shots and Stings by 2% per rank (5 ranks total).\r\n*[[Hawk Eye]] (Survival Talent): Increases the range of your ranged weapon by 2 yards per rank (3 ranks total).\r\n*[[Improved Stings]] (Marksmanship Talent): Increases the damage done by your Serpent Sting and Wyvern Sting by 6% and the mana drained by your Viper Sting by 6%. In addition, reduces the chance your Stings will be dispelled by 30% (5 ranks total).\r\n==Tips and tactics==\r\n* Its greatest utility in PvP is against Rogues and Druids, to prevent them from entering stealth. (Druids can cleanse it, but will have to shift to caster form to do so.)\r\n* Be careful using this spell in situations where your group may use crowd control, as damage over time will break it. If you have used Serpent Sting on the wrong target, you can overwrite it quickly by casting [[Scorpid Sting]] on the same target, which does not break CC.",},
			["Serrated Blades"] = { content = "Serrated Blades is a 15 point [[talent]] in the Subtlety for [[Rogue]]s. It was introduced in Patch 1.10 as a replacement for improved [[Rupture]], and is a strict improvement over that talent. It is the pre-requisite for the 20 point talent [[Hemorrhage]].\r\n==Functionality==\r\nSerrated Blades is a passive ability that increases the rogue's damage output by allowing the rogue's attacks to ignore a small portion of the target's [[armor]]. Also, the talent keeps the functionality of it's predecessor by increasing the damage of [[Rupture]].\r\n==Notes==\r\n*At level 70, Serrated Blades rank 3 will ignore 560 of the target's armor. This amount may not seem significant, but this is factored into every single attack, the benefit will add up.",},
			["Servant of Allistarj"] = { content = "'''Servant of Allistarj''' can be found in [[Blasted Lands]].\r\n==Quests== \r\n==Drops == \r\n \r\n Quest items dropped by Servant of Allistarj\r\nAlso 2 random [[Uncommon]] and 5 random [[Common]] item drops.",},
			["Servant of Sevine"] = { content = "'''Servants of Sevine''' is are level 50-56 mobs found in the [[Blasted Lands]].",},
			["Servers"] = { content = "#REDIRECT [[Realm]]", redirect = "Realm",},
			["Server:Al'Akir Europe"] = { content = "IRC Channel: #alakir | Network: \r\n'''Al'Akir''' is a Player versus Player server for Blizzard's MMORPG, [[World of Warcraft]]. The '''Al'Akir''' server was one of the original servers included with the release of [[World of Warcraft]]. It is named after one of the [[Old Gods]]'s lieutenants, [[Al'Akir]] the Windlord. It's more commonly referred to as Lag'Akir by its playerbase though, because of its history of being very prone to lag and long queues. \r\n'''Al'Akir''' has a very active community -which contains some of the most recognizable names in [[World of Warcraft]]-, a wide variety of guilds ranging from casual to hardcore and a history filled with incidents, events and drama.\r\nMost importantly though, '''Al'Akir''' is full. Please do not roll new characters there!\r\n==Raid Progress==\r\n'''Al'Akir''' has, and always had, a strong raiding community. Outdoor raid bosses have always been heavily contested and competition for serverwide first kills shines every time a new instance is added to the game. The longstanding superpowers that emerged on both factions are [[Guild:DarkStorm (Al'Akir EU)|DarkStorm]] (DS) for the [[Horde]] and [[Guild:Stature of the Gods (Al'Akir EU)|Stature of the Gods]] (SotG) for the [[Alliance]]. Currently, other notable raiding guilds include , and (all Horde), , , and (all Alliance). \r\n===The Molten Core===\r\nAs Horde players leveled significantly faster on '''Al'Akir''', they were able to form the first raids to explore the depths of the [[Molten Core]]. The two dominant Horde guilds, [[Guild:DarkStorm (Al'Akir EU)|DarkStorm]] and The Forgotten Few (TFF), collaborated and raided together tackling encounter after encounter with no notable competition, whilst [[Guild:The Void (Al'Akir EU)|The Void]] followed closely behind snapping up all of the guild-only kills. The combined guild raid force, using noggenfogger pot spam, killed [[Ragnaros]] on May 18, 2005 (). It wouldn't be until 2 months later on July 22nd that their kill was followed by [[Guild:Stature of the Gods (Al'Akir EU)|Stature of the Gods]], closely followed by and [[Guild:The Void (Al'Akir EU)|The Void]].\r\n===Blackwing Lair===\r\nHungry for new content, [[Blackwing Lair]] was eagerly anticipated by both factions. A bugged [[Razorgore]] fell to [[Guild:The Void (Al'Akir EU)|The Void]] early on with a proper kill coming later on from DS, who had merged with TFF by this time. The first Alliance kill tells a more interesting story. \r\n====The Razorgore incident====\r\nMR, still bitter being beaten by SotG on Ragnaros by less then 24 hours, made it their mission to beat SotG on this occassion and they succeeded, but not without the use of the commonly known [[Divine Intervention]] paladin exploit. Their initial claims of the kill were received with sceptism and when definite word spread they exploited the encounter, the community was quick to burn down any MR member that had shown arrogance after the kill or denied what had happened. Not all MR members had supported the 'approach' to the encounter and this lead to internal guild troubles which resulted in many of their core members leaving to form Edge of Eternity (EoE). On top of that, many members rerolled on another server or quit the game following the community's reaction, leaving MR severely crippled, but alive.\r\n====A turning point====\r\nEventually, the first legit Alliance Razorgore kill came from SotG. Both DS and SotG were hammering on the next boss, [[Vaelastrasz]], night after night (for an hour tops, as that was how the Vaelastrasz fight worked in those days). This eventually resulted in a turning point in server history: the first time an alliance guild achieved a server first, as it was SotG that killed Vaelastrasz on August 29, 2005 (). DS was quick to follow though and killed Vaelastrasz soon after, followed by a server-first on [[Broodlord Lashlayer]] that same night. It would be their last achievement in Blackwing Lair, since SotG killed [[Firemaw]], then steamrolled over [[Ebonroc]], [[Flamegor]] and [[Chromaggus]] in one night and eventually downed the final boss [[Nefarian]]. It would take considerable time, due to various internal issues, for DS to follow.\r\nSotG's kill on Nefarian put them among the 10 best guilds in Europe. Their achievement was criticised though by, most notably, DS who accused SotG of using guides (which were unavailable at the time, but stemmed from the friendly relation SotG maintained with another EU top guild: [[Guild:Inner Sanctum (Al'Akir EU)|Inner Sanctum]] (IS)).\r\n===Ahn'Qiraj===\r\nThe opening of the [[Gates of Ahn'Qiraj]] was a well coordinated serverwide event on '''Al'Akir'''. The dedicated pages to view progress on the war supplies gathering and cross faction trading of materials resulted in '''Al'Akir''' being the 7th server in Europe to open the gates on February 17, 2006.\r\n====Restoring the Scepter====\r\nLylz (shaman, DS) completed the quest for the [[Scepter of the Shifting Sands]] first and was the player who triggered the world event. Other players that finished the scepter quest are: Astaren (DoV).\r\n====War supplies====\r\nHorde gathered the bulk of the supplies, including a notable portion of the Alliance supplies. This had several reasons. Besides being the bigger faction, in numbers, on '''Al'Akir''', certain Horde guilds (DS amongst others) and Alliance guild Solution put considerable effort into the farming process through supplies 'lotteries' that proved to be very popular. Also, a considerable amount of farming time was wasted because two guilds (DS and DoV) were completing the time-consuming scepter quest.\r\n====Temple of Ahn'Qiraj====\r\nWhen the gates eventually opened it was SotG that rushed in first and cleared up to [[Princess Huhuran]] that same night, claiming server-firsts on [[The Prophet Skeram]], [[Three Bugs]], [[Battleguard Sartura]] and [[Fankriss the Unyielding]]. [[Princess Huhuran]] died to them the next day. DS progressed quickly as well and both guilds were working on the [[Twin Emperors]] for 3 days before DS took it down first, followed by SotG just over an hour later. Both guilds were now stuck on a bugged [[C'Thun]] and a bugged [[Ouro]]. \r\nBeing stuck on bugged encounters, DS killed the optional boss [[Viscidus]], as did SotG (albeit the encounter was severely bugged for them at the time). The C'Thun and Ouro hotfixes provided two server-firsts for SotG, with a top 10 position for Europe once more on C'Thun. \r\nAt the time of writing 6 guilds cleared Ahn'Qiraj (DS, SotG, EC, Gifu, No Danger and DoV) and 11 guilds killed C'Thun.\r\n===Naxxramas===\r\nEvery guild knew that Naxxramas was the last new raid content to be released before [[The Burning Crusade]] and thus many were eager to perform well. With 4 different wings available guilds had a lot of possibilities for progression. \r\nSotG took a headstart by killing [[Anub'Rekhan]], [[Instructor Razuvious]], [[Noth The Plaguebringer]], [[Grand Widow Faerlina]] and [[Maexxna]]. Meanwhile DS had worked on [[Patchwerk]] for days, with no success. After clearing the Spider Wing, SotG continued their streak by killing Patchwerk and [[Grobbulus]], leaving DS stumped until they finally killed Patchwerk some days later. While DS and SotG worked on [[Gluth]], Kale and DoV were fighting for a server first on [[Heigan the Unclean]] in the Plague Wing. In the end, both Gluth and Heigan went to the Horde faction. Later it would become clear those 2 kills was all that Horde would get. \r\n[[Thaddius]] being the logical next step in progression posed severe problems. Known to be an incredibly lag sensitive and prone to disconnects encounter, it was deemed impossible on '''Al'Akir''' in its state at the time. Not having received any hardware upgrades since the game's original release, Thaddius of '''Al'Akir''' was undoable. Hope was on the horizon though, as hardware upgrades were announced and nearly there. After the arrival of the hardware upgrades the lag on '''Al'Akir''' was significantly decreased and playability increased. SotG could now continue their strong performance and did so by killing Thaddius, [[Loatheb]] and [[Gothik the Harvester]] within a week.\r\nDS slowly caught up to SotG by killing Thaddius, Loatheb and Gothik, while SotG was unable to form a raid with the proper setup for the [[The Four Horsemen]] (4HM). When SotG eventually did kill them, DS approached so close that they were able to kill 4HM the day after. With just [[Sapphiron]] and [[Kel'Thuzad]] alive, the race for the first Naxxramas clear was on. \r\nSotG killed Sapphiron first, on Sunday October 22, and proved to be more then ready to face Kel'Thuzad, as they downed the chief lieutenant of the powerful [[Lich King]] just 2 days later on Tuesday October 24 as the 15th guild in Europe. DS followed their footsteps by killing Sapphiron 1 week after SotG and killing Kel'Thuzad 3 weeks after SotG as the 25th guild in Europe.\r\nWith Christmas time (anno 2006) constantly getting closer both MR and DoV realised they couldn't gather the strengh anymore to kill [[Kel'Thuzad]] alone. The leadership of both guilds therefor agreed to create a raid alliance with the aim to kill [[Kel'Thuzad]] before The Burning Crusades arrival. Within the first week they managed to down [[The Four Horsemen]], Friday December 22, and just 4 days later [[Sapphiron]] shared the same faith, Tuesday December 26th.\r\nHappy about the impressive progression they kept the raid alliance going and suceeded their aim by killing [[Kel'Thuzad]] late night, Sunday January 7th (Even thou some think it was Monday January 8th). \r\nAt the time of writing 4 guilds cleared Naxxramas (SotG, DS, DoV and MR).\r\n====Atiesh, Greatstaff of the Guardian====\r\nThe following players have assembled the legendary caster staff Atiesh, Greatstaff of the Guardian (in order):\r\n* Leezah (Mage, SotG)\r\n* Vahu (Mage, DS)\r\n* Rapidload (Priest, DS)\r\n* Amoeba (Druid, EC)\r\n* Dynis (Mage, MR)\r\n* Scarebe (Warlock, DoV)\r\n* Goldnspirit (Druid, DoV)\r\nAs Explicit Content have not killed [[Kel'Thuzad]], Amoeba joined DarkStorm on one of their Kel'Thuzad kills to loot the headpiece, thus enabling him to finish his staff.\r\n==The Burning Crusade==\r\nDuring the first week of after [[The Burning Crusade]] went live on the servers Al'akir routinely went down during peak hours as the servers couldnt handle the 3 continents of Kalimdor, Eastern Kingdoms and Outland at the same time without severe lag or crashes.\r\n==Noted Guilds==\r\nKil'Jaeden has been killed by 5 guilds on Al'Akir. Them being Apex, East Dragon, DarkStorm, (Midnight Reveries & Stature of the Gods (co-op raid)).\r\n===Gruul's Lair / Magtheridon's Lair / Outdoor Raid Bosses===\r\nIf your guild is missing on the list or you killed a new boss, feel free to Update the list.\r\n==Player versus Player==\r\nThe PvP History in '''Al'Akir''' is rather colourful. During the virgin months of Al'Akir, when it already displayed foreboding signs of instability, unwary players experienced frequent moments of (Alliance) terror courtesy of SotG rogue Bladespinner, the once sinister <East Dragon> and the dubiously named <dragonkiller from forest>. At one point, one of the leading Horde guilds in the early days, Karma, hosted an in-guild skirmish on the Gurubashi Arena, eventually more or less unexpectedly featuring a bonusfight of sorts between Karma's Heimdal (undead priest) and the unflagging Bladespinner. The epic matchup resulted in victory, nay utterly crushing and humiliating domination by Heimdal who caused more than one eyebrow to rise with his nifty use of the underrated Cannibalize and furious wanding. With that fight, Bladespinner's heyday had come to a bitter end and he soon disappeared to realms unknown.\r\nLater outdoor pvp bloomed at Tarren Mill. With the introduction of Alterac Valley, Hillsbrad Foothills became nigh impossible for levelling due to intense outdoor facemelting. \r\nUpon the introduction of the honor system the first to gain the then much coveted fourteenth rank were Lylz of DarkStorm on Horde side and Lora of East Dragon (Rogue) representing Alliance, both achieving the feat on the same week.\r\nOn the release of crossrealm battlegrounds '''Al'Akir''' teams quickly made a name for themselves for being specialized in graveyard camping. Amongst the early teams the most notable was the Bad Karma team, followed by the twink league of <e peen> - both of which never received any losses during their one month existence. \r\n'''Al'Akir''' is also notable in housing some of the most famous PvP movie makers in WoW. Notable: Azgaz, Grim, Jungle, Marukoer, Mastatrigga, Zalgradis.\r\n* '''Azgaz'''\r\n** Class: Druid\r\n** Faction: Horde\r\n** Movies:\r\n*** - \r\n*** - \r\n*** - \r\n*** - \r\n*** - \r\n*** - (May 2008)\r\n*** - \r\n* '''Grim'''\r\n** Class: Rogue\r\n** Faction: Horde\r\n** Movies:\r\n*** - \r\n*** - \r\n* '''Marukoer'''\r\n** Class: Mage\r\n** Faction: Horde\r\n** Movies:\r\n*** - \r\n* '''Zalgradis'''\r\n** Class: Paladin\r\n** Faction: Alliance\r\n** Movies:\r\n*** - \r\n*** - \r\n*** - \r\n*** - \r\n=== Alliance Guilds===",},
			["Server:Auchindoun Europe"] = { content = "==About The Server==\r\nAuchindoun is a European PvP server released along with the others that arrived around the time that 'The Burning Crusade' expansion was released. It is a fairly small server with about a 60:40 horde majority, but anyone willing to try hard and find a good guild may prosper as either faction. The population on the realm is not very high, around 5000 characters according to WarcraftRealms and similar sites, but activity is high and you usually run into lot's of people, also when levelling, as it's still a relatively young and recommended server.\r\n===Pronunciation===\r\nOk-In-Doon\r\n(Small 'O' sound on first syllable).\r\n== Alliance guilds==\r\n* Apocalypse Dudes\r\n* Guardian Angels\r\n* Shine\r\n* Deimos\r\n* Onslaught\r\n* Devine Beings\r\n* Outcast\r\n* Ashes\r\n* Legion of Russian Bears\r\n* Sparta\r\n* Seekers of Virtue\r\n* Reflection\r\n* Eminence\r\n* Immortal Blades of Aiur\r\n* Elemental Spirits\r\n* Nullus Anxietas\r\n* DaKor\r\n* Fusion\r\n== Horde guilds==\r\n* \r\n* Sapped Girls can Twinket\r\n* The Tempted\r\n* Project Omega\r\n* Fools Gold\r\n* Ordo Draconis\r\n* Lycen Fel\r\n* Blame Us\r\n* Turkish Raiders\r\n* Frikandel Speciaal\r\n* Fuscus and Napalms guild\r\n* Random Heroes\r\n* Damage Incorporated\r\n* Manic Monday\r\n* Eradication\r\n* Outcast\r\n* Prima Nocta\r\n* Vanquished\r\n* Guild Name Got Nerfed\r\n==War Effort==\r\nThe War effort on Auchindoun was started on April 29th and finished on October 17th.\r\nThe gates were opened on October 30th by after having used Payed Character Transfer to arrive on the server that day, with the scepter. This sparked some controversy, as several people on the server were also trying to complete it.\r\n==A Pre-TBC Guild==\r\nFor some time a group of players have been struggling to push forward in a non-TBC orientated style. All the guild members have non-TBC enabled accounts and are capped at L60. While the guild is in its infacy at the time of writing (3/3/08) they have great expectations. Their name \"Reflection\" Their website:",},
			["Server:Auchindoun US"] = { content = "The North American '''Auchindoun''' server came online with the Burning Crusade on January 16, 2007 at 12:01 AM EST. It is a [[PvP]] server in the EST timezone. The server population ratio of [[Alliance]] to [[Horde]] is slightly unbalanced at 85 at about 1:1.5 overall. The vast majority of Horde being comprised of [[Blood elf|blood elves]], which account for more than half the entire server. Because of its low population, Auchindoun is free of server queues. Battleground queues for Horde, however, are another story and can be very long.\r\nBlack Temple cleared by Reckless Ambition 12/04/07, making it the 2nd most progressed in PvE (Retaliation Battlegroup)\r\nAuchindoun was also home of the \"\" and its guild. This podcast contained new contents being released consistently on a weekly basis. The guild has since disbanded, but the podcast is still active and contains news, commentary, wacky commercials for WoW addons and parodies of songs with an Outlandish twist.\r\nOn a whole, Auchindoun is rather notorious, with both factions' Trade chats being compared to /b/ by some, although it has toned down some. Conversations typically arise in Trade chat, oftentimes regarding sensitive subjects. Players from other realms that interject and voice their opinions on the matter are usually greeted by a sarcastic \"Welcome to Auchindoun.\" There is also a large amount of realm pride, especially among the Horde.\r\nThe troll hunter [] of the guild <> (recently transferred to Ysondre - as of Feb 2009) was the first player to reach Level 80 approximately 49 hours after the release of the WotLK expansion on November 13, 2008.\r\n==Server Information==\r\n* IRC – www.gamesurge.net , #auchindoun\r\n* Time Zone – EST\r\n* Alliance : Horde Ratio – 1:1.5 (More info available via WarcraftRealms: )\r\n <div style=\"clear:left;\" \"height:0.6ex;\"></div>\r\n'''See Also''': , [[Server:Auchindoun US/guild progression|Guild Progression]] and .\r\n==PvP on Auchindoun (Pre-Connected Realms)==\r\nAlthough the faction ratio on the server was imbalanced and favored the Horde there was a very active PvP scene to be found on Auchindoun. The Alliance on this server often enjoy fast queues in battlegrounds while the Horde wait can be very long depending on the player's level. Horde almost always controlled all world PvP objectives by default with the exception of the Terokkar towers. This is due to the towers being held for a set amount of time after capture by default. Both factions traded off holding Tol Barad with neither side having an edge over the other most of the time.\r\nWorld PvP was almost nonexistent on Auchindoun, but there were several players within both factions that try to make trouble for the opposing side whenever possible. This often included individuals or groups camping areas where enemy players duel or congregate in an attempt to score an easy kill. Since the player base on this server was very low, players who engaged in this type of behavior often gained a reputation and were targeted specifically in world or battleground PvP encounters.\r\n== Alliance Guilds==\r\n* PvE: Level 25 Guild\r\n* PVE/PVP: Level 25 Guild\r\n* PVE: Level 24 Guild\r\n* PVE/PVP: (Disbanded 2011)\r\n* PVE: Level 25 Guild\r\n* Illusions of Grandeur PVE: (Inactive 2011)\r\n* PVE/PVP: (Disbanded May 2010)\r\n* PVE/PVP: (Disbanded May 2009)\r\n* Reckoning PVP/PVE: \r\n* PVE/PVP: Level 25 Guild\r\n* Invictus PvE: Level 18 Guild\r\n* PVE: (Disbanded August 2009)\r\n* PvE/PvP: Level 25 Guild\r\n* Super Busy Hospital PvE: Level 25 Guild\r\n* PVE/PVP: Level 25 Guild (Inactive August 2016)\r\n== Horde Guilds==\r\n* PVE/PVP: Level 25 Guild \r\n* [And The Sunshine Band] PVP: \r\n* PVE/PVP: \r\n* PVE/PVP: \r\n* PVE/PVP: (Disbanded)\r\n* PVE/PVP: (Disbanded April/May 2009)\r\n* Pariah PVE/PVP: Level 25 Guild\r\n* PVE/PVP: Level 25 Guild\r\n* Prettier Than Thou PVE/PVP: Level 10 Guild\r\n* Grassroots PVE: Level 25 Guild\r\n* PvE/PvP: (Disbanded 2009)\r\n* Orginization XIII PVE/PVP: (Disbanded 2011)\r\n* Recurring Nightmare PvE/PvP: (Disbanded)\r\n* Reckless Ambition PVE/PVP: Level 11 Guild\r\n* PVE/PVP: (Disbanded) \r\n* PVE/PVP: Lino ''(For a time was called Twenty After Four)''\r\n* Sit N Spin PvP: Level 13 Guild\r\n* PVE/PVP: (Disbanded December 2008)\r\n* PVE/PVP: \r\n* PVE/PVP: Level 25 Guild\r\n==Realm Firsts with WotLK==\r\nBlizzard provided updates can be found at: \r\n'''Faction Achievements'''\r\nRealm 1st to Lvl80 - Kripparrian <Synergos> (H) 15-Nov-08\r\nRealm 1st Alliance to Lvl80 - Booi <Goombas> (A) 16-Nov-08\r\nRealm 1st Horde to Lvl80 - Kripparrian <Synergos> (H) 15-Nov-08\r\n'''Class Achievements'''\r\nRealm 1st Death Knight to Lvl80 - Mosdefknight <Insurrection> (H) 17-Nov-08\r\nRealm 1st Druid to Lvl80 - Androxius <Addiction> (H) 16-Nov-08\r\nRealm 1st Hunter to Lvl80 - Kripparrian <Synergos> (H) 15-Nov-08\r\nRealm 1st Mage to Lvl80 - Arcnova <Addiction> (H) 16-Nov-08\r\nRealm 1st Paladin to Lvl80 - Psyche <Addiction> (H) 16-Nov-08\r\nRealm 1st Priest to Lvl80 - Legate <Goombas> (A) 16-Nov-08\r\nRealm 1st Rogue to Lvl80 - Rougeh <Syngergos> (H) 15-Nov-08\r\nRealm 1st Shaman to Lvl80 - Coercionist <Addiction> (H) 15-Nov-08\r\nRealm 1st Warrior to Lvl80 - Benix <Addiction> (H) 16-Nov-08\r\nRealm 1st Warlock to Lvl80 - Simayi <Lord of the Blood Elves> (H) 16-Nov-08\r\n'''Race Achievements'''\r\nRealm 1st Draenei to Lvl80 - Druidd <Goombas> (A) 16-Nov-08\r\nRealm 1st Dwarf to Lvl80 - Legate <Goombas> (A) 16-Nov-08\r\nRealm 1st Gnome to Lvl80 - Booi <Goombas> (A) 16-Nov-08\r\nRealm 1st Human to Lvl80 - Avatarofhate <Simple> (A) 18-Nov-08\r\nRealm 1st Night Elf to Lvl80 - Aequinas <Goombas> (A) 17-Nov-08\r\nRealm 1st Blood Elf to Lvl80 - Althaea <Addiction> (H) 15-Nov-08\r\nRealm 1st Orc to Lvl80 - Benix <Addiction> (H) 16-Nov-08\r\nRealm 1st Tauren to Lvl80 - Androxius <Addiction> (H) 16-Nov-08\r\nRealm 1st Troll to Lvl80 - Kripparrian <Synergos> (H) 15-Nov-08\r\nRealm 1st Undead to Lvl80 - Arcnova <Addiction> (H) 16-Nov-08",},
			["Server:Auchindoun US/guild progression"] = { content = "-------------------\r\nGeneral Information\r\n-------------------\r\nRealm opened: 12:01 on January 16th, 2007\r\nTime Zone: Eastern\r\nIRC: Server IRC: irc.zirc.org #auchindoun\r\nServer Info: \r\nBattle Group: Cataclysm\r\nBattle Group IRC: irc.gamesurge.net #cataclysm\r\n <div style=\"clear:left;\" \"height:0.6ex;\"></div>\r\n'''See Also''': , [[Server:Auchindoun US| Server:Auchindoun US]].\r\n==The Black Temple==",},
			["Server:Azgalor US"] = { content = "One of the original release day servers, '''Azgalor''' is a PvP server with a strong PvP community. As such, the server is home to many veteran players, but has suffered in the past from Guild migrations such as the leaving of Brethren. Most of the migrations were due to the ageing server's performance before it was upgraded. It is known for the [[User:Banduril/Gospel of the Alliance Azgalor|Gospel of the Alliance]] and the .\r\nTimber has this to say to potential server-transfer participants.\r\n\"Welcome to Azgalor! We sincerely hope you enjoy your potential time on our server. \r\nWe have spent many years making sure that Azgalor is not only the place for us... but also the place for you! You will find caring individuals on both Alliance and Horde, AND I think that you will be able to find someone to lend a helping hand in any instance. Truth be told, we would like to be the shelter in which you fared whatever storm you are going through, my friend. \r\nSometimes our forums can get a little bit salty, but we all know a little salt makes the pretzel taste even better!! Sometimes in-game discussions can get a little heated, but we all know that cold pizza doesn't cut it!! And sometimes the progression situation gets a little bit stale, but we all know that stale crackers make your soup better!! \r\nPlease feel free to contact anyone that you see in these threads. For the most part (though there are some bad apples), you will find caring individuals devoted to assuring that Azgalor has a nurturing and positive influence on the young and old members of our community alike. Because you don't join a server... you join a family.\"\r\nKrytical has this to say about people who successfully defeat one of our AV premades\r\n\"As an Azgalor figurehead, please allow me to humbly congratulate you on your epic victory over one of our very intimidating and dominating trade channel premade groups. Our trade channel premades work for weeks on end to ensure each AV weekend will be met with ferocious and tactically brilliant strategies, and we assign class leaders and strike teams to execute our carefully laid plans when the leader gives the command over our trade-channel-premade-ventrilo. The command is, \"Trucks.\"\r\nPlease know that the Azgalor player base as a whole will take a valuable lesson away from this gut wrenching loss, and I assure you, efforts will be made to ensure that such a crushing defeat will not be suffered again without a furious and glorious battle.\r\nYou have our respect.\r\n-Krytical\" \r\n==Raid progression==\r\nFor information on Azgalor's guild progression through the raid instances, see the page.\r\n==Separate forums==",},
			["Server:Azshara US"] = { content = "Azshara is a North American PvP server.\r\n==Information==\r\n* Open Date: November, 2005\r\n* Type: Player vs. Player (PvP)\r\n* Populations: Low (Lowest North American Server as of 4-21-07)\r\n*Total Characters: 6,531\r\nTotal Alliance: 2,458 - 38%\r\nTotal Horde: 4,073 - 62%\r\nA to H Ratio: 1 : 1.7\r\nInformation from \r\n*Battlegroup: Shadowburn - (Realms within the Battlegroup: Agamaggan-PvP, Azshara-PvP, Dark Iron-PvP, Detheroc-PvP, Emerald Dream-RP-PvP, Greymane-Normal, Kalecgos-PvP, Lightninghoof-RP-PvP, Maelstrom-RP-PvP, Malfurion-Normal, Moonrunner-Normal, Sargeras-PvP, Staghelm-Normal, Twisting Nether-RP-PvP, Ursin-PvP, Wildhammer-PvP.)\r\nThe offical Shadowburn forums: \r\n \r\n*AZSHARA: A NEW DAWN\r\nThe server of Azshara was once home to some major horde guilds, most notably Blue Garter and Crucial, both of these guilds were major competitors in the old world working their way through instances such as AQ40 and Naxx. Post Burning Crusade they continued raiding, with Blue Garter managing to down Illidan. However these titans no longer remain leaving the throne of top guild on Azshara somewhat empty as they either left the server or were faced with inner drama. However, the landscape of the server has been changing once again. Death Minions, a guild that has been on Azshara from the beginning has continued its raiding goals and is quickly progressing, while at the same time two new major players have entered the battle scarred arena of Azshara. Fatal and Armistice have begun competing for the title of number one and quickly racing their way through Serpentshrine Cavern, Tempest Keep, and Mount Hyjal. Due to the lack of a population on the server, Blizzard has opened transfers to the realm twice thus far; sparking the interests of a variety of players on more crowded realms. While Azshara remains without any major change, the Alliance side has profitted from many skilled transfers and the now prominent guild Methods Of Mayhem is working its way to the top of the Azshara progression charts taking the title of the furthest progressed Alliance guild. At the same time the Horde guild Greyhand transferred and has successfully joined the race to experience Burning Crusade content. While progression continues in a fast paced environment, PvP has not been neglected. While the battlegroup is dominated by the Alliance, Azshara has formed many new Alliance and Horde PvP guilds, motivated and inspired by Blizzards' introduction of the Season gear, these guilds host a variety of benefits for those looking for a chance to face off against other real players. While the population of Azshara may be low, the server's inhabitants deeply love their home, and hold high respect for its host of players. All will be looking to see what changes and new dangers await when all must face The Wrath Of The Lich King.\r\n*Want to learn more about the Queen our server is named for? Follow the link: \r\n*Where can you find Azshara on every server? Follow the link: \r\n==Realm Transfer == \r\nBlizzard offered free character moves from selected high population realms to other, lower populated realms to assist in population dispersal. The ability to move a character on the selected source realms became available on Friday, December 21 at 12:01 PM PST, and ended Friday, December 28 at 12:01 PM PST. Azshara was chosen as a destination realm and recieved a number of individual transfers but only a few full guilds.\r\nBlizzard highly recommend that if you were planning to transfer that you had done so at your earliest convenience. \r\nThe realms chosen consist of source realms with the highest sustained queues, and destination realms with the lowest population. The numbers gathered are directly from Blizzards' data, and depict the realms in most need of these transfers. Blizzard will be continuing to monitor all realms and open additional free transfers in the future where necessary. \r\nSource Group: \r\nArthas, \r\nWarsong, \r\nMal'Ganis, \r\nIllidan \r\nDestination Realm: \r\nAzshara\r\n==== [[Alliance]]====\r\nThe Section On Alliance Guilds NEEDS updating - Alliance Guilds please feel free to do so just stick to the same format as used on the Horde ones\r\n''' In Memorian ''' \r\n(Active) \r\nFrom Gurubashi server to own Ashara hordies! Friends Guild, BR only. \r\n'''Suicidal'''\r\n(Active)\r\nSuicidal is a PvP and End Game Raiding Guild\r\n'''The Old School'''\r\n(active)\r\nThe Old School is one of the original guilds from the very first months of the servers beginning. It started as a breakoff guild from \"Flurry United\" a guild that came over from Star Wars Galaxies in response to the Combat Upgrade and ruination of the game itself. Started by \"WookieLuv\" it expanded from 15 players to over 375 in the summer of 2007. Wookieluv took a 3 month hiatus and came back to over 450 members. At that time it was decided to split the guild into 2 \"Old School\" guilds. Thus, \"The Old School Academy\" was born. (TOSA) TOSA was aimed at players under level 40 and needing help with quests etc. The Old School (TOS) was for 40+ onto level 70's. It's a very laid back, casual guild that emphasizes cooperation, mutual respect and having a life outside the game. Currently TOS has 130 very active members and TOSA is closing in on the 400 member mark.\r\n'''Kentucky Fried Troll'''\r\n(Inactive)\r\nKentucky Fried Troll (KFT) is fairly new and consists of a wide variety of players but contains and was formed by many long time Azshara residents. KFT was previously known as Naga Please and contains many former Dark Legion members. KFT is highly active in all forms of PVP and end-game raiding, but they are known to be laid back and emphasize having fun.\r\n'''Molten Core'''\r\n(Inactive)\r\nMolten Core was the first MC raiding guild on the server and the first to fall apart as well. Known for their highly unimaginative guild name.\r\n'''Letalis'''\r\n(Inactive)\r\nLetalis was the most progressed guild on the server, responsible for opening AQ on Azshara (e.g. Nerion's \"great cross-faction linen drive\") and driving PvE competition on both sides. Led by Nerion, Letalis is sorely missed by horde and alliance alike. It was the guild everyone loved to hate.\r\n'''Team GG'''\r\n(Inactive)\r\nTeam GG was Pjizzle's alliance PvP guild. Initially horde, Pjizzle found the twink bracket WSG matches too easy and rerolled alliance for a challenge. Team GG became a top performing PvP guild in short order, due to the sheer skill of its members (and despite Pjizzle's lack of social graces).\r\n'''Angry Mob'''\r\n(Active)\r\nAngry Mob has been around a long time and seems to still be going strong. Rumours abound that the current incarnation is not the same guild as it was, however.\r\n'''Muerte y Destrucción'''\r\n(Active)\r\nVery aggressive, these folks play like they're on a PvP server.\r\n'''ChannelFourNewsTeam'''\r\n(Inactive)\r\nAnother aggressive alliance guild, although not very skilled.\r\n'''Reflex'''\r\n(Inactive)\r\nReflex is a small PvP guild, only mentioned here because their guildmaster Mace is a cool guy. Footnoted in Azshara history, Mace had a hunter named Esekiel whom was once the subject of a rather scandalous tryst in the Southshore Inn. During an old-school world PvP battle in Hillsbrad, Two horde (Cong and Epoxy) discovered Esekiel in a room in the Southshore Inn, laying on the bed alongside a naked female nightelf. While not the first WoW player to be caught having cybersex by the opposite faction on a PvP server, Esekiel handled it quite sportingly.\r\n'''Je Me Souviens'''\r\n(Inactive)\r\nAn old-school guild made up of French-speaking Canadians, they were extremely aggressive in world PvP and were the nemesis of the horde guild ZERG. When a member was spotted by either faction in any zone, reinforcements were usually called in on both sides until a full-on war erupted.Disbanded recently proof that the old Azshara is gone\r\n''' Fallen Kings '''\r\n(Inactive)\r\nFallen Kings was a casual gaming guild that wasn't really into endgame but is mentioned here because at its height it had 462 members, making it the largest guild on Azshara at the time. It was disbanded when its guild master Anuschka left to start an endgame guild.\r\n''' Avenge '''\r\n(Active)\r\nAvenge is a newer guild on Azshara. They have begun 25 man content and are quite happy to PVP as well. Membership is continuing to grow and end game progression is the goal.\r\n''' Riven '''\r\n(Active)\r\nRiven is the returned Ascendancy to Azshara. They were a transfer guild originally from Blackrock and have since came back to Azshara for the remaining time in TBC and Wotlk. They're currently the farthest progressed Alliance Guild, having obtained the first Alliance Illidan Kill and the first alliance Archimonde kill as Ascendancy. PvE progression is their primary goal.\r\n* See the in the Realm Forums for more info.\r\n==== [[Horde]]====\r\n'''Fatal'''\r\n(Active)\r\nGuild Leader: Velton\r\nOfficers: Eyrthstone, Cyrk, Bakios, Kaylla, Worlam, Foos, Holyhorde\r\nFirst of the current active Azshara guilds to have fully cleared Serpentshrine Cavern, Tempest Keep, Mount Hyjal and Black Temple both on the Horde and Alliance. The guild of Fatal was formed in the Fall of 2007, when the older Azshara guilds of Invictus and Trilogy merged together to create a formidable raiding team. At the time Invictus was suffering from a lack of members, and Trilogy had multiple issues with its leadership, but the members and officers of both guilds were dedicated to the game and to progression, allowing for the merger to not only be succesful but to plant the seeds which allowed for Fatal to become the guild it has. Fatal prides itself on its small size where the only members in the guild are also the core raiders that it fields in progression every night it raids. While the focus of the guild is PvE, raiding only takes up three nights of the week allowing for its players to either delve into other aspects of the game or into real life. However the main reason for Fatal's success lies behind the teamwork and dedication of each and every member in the guild, and now, Illidan lies dead, and Sunwell lays on the horizon.\r\nOn August 19th 2008, Eliminatè made a deal with the guild leader Velton, that if Shawn Johnson won the gold medal in Gymnastic he would xfer out of the server in spite for China. and so he did.\r\nWebsite: \r\n'''Armistice'''\r\n(Active)\r\nGuild Leaders: Lottadots, Rajna\r\nOfficers: Reverend, Marlowe, Kelpso, and Bobdawarrior\r\nGuild History: Armistice was born from a merger of Lights Out (LO) and Grand Lethal (GL) on 9/30/2007. Both guilds had very different raiding backgrounds, and different leadership structures. While GL was consistently raiding, LO was not due to lack of participation from their raiders. LO also raided 2-3 hours earlier then GL. Opposites apparently attracted in this merger, and the guild has been successful from the start. While some people question a guild that has both casual and hardcore raiders, it has worked quite well. Armistice is PvE raiding guild and its current progression is in Sunwell Plateau, while having cleared TK, SSC, Mt Hyjal and Black Temple.\r\nWebsite: \r\n'''Death Minions'''\r\n(Active)\r\nGuild Leader: Bossform\r\nCurrently the oldest raiding guild on the server comprised of it's oldest(rl age) members. An adult raiding guild lead by Bossform. Founded in December of 2005 this guild is still going strong as a casual raiding guild. Oldest actively raiding guild on Azshara.\r\nWebsite: \r\n'''GreyHand'''\r\n(Active)\r\nGuild Leader: Zfellwar\r\nGreyHand originated on the Gurubashi server a couple of months after the WoW release. The guild has been through several mergers in the process of putting together a viable raiding force, but has always ended up back as 'GreyHand'. Zfellwar and Zuggi take turns leading the guild. GreyHand transfered to Azshara in April of 2008, and after a successful move, have downed Lady Vashj and are pursuing further progession.\r\nWebsite: \r\n'''Pandemônium'''\r\n(Active)\r\nGuild Leader: Shnygut\r\nOfficers: Chupacabras, Mclovein, Herkule, Reigner, Fozzie, Michira, Valkas, Benadryl, Mq\r\nCurrently progressing into the Tempest Keep and Serpentshrine Cavern, Pandemônium has rapidly made its way onto the raiding scene of Azshara. Starting on March 11, 2008, their Guild Leader Shnygut has truly created a worthy adversary for the instances of the Outland.\r\nWebsite: \r\n'''Like A fish'''\r\n(Active)\r\nGuild Leader: Yoya\r\nLike A Fish was formed by the players Easypk, Damaga, and Ayquefrio. The guild is a prominent PvP guild on Azshara, currently working to recruit the best PvP'ers that this server has to offer. Be it a battleground or in the Arena, Like A Fish will prove to be a formidable opponent for any Alliance seeking some easy honor.\r\nWebsite: None - as of 05/22/08\r\n'''That Just Happened'''\r\n(Active)\r\nGuild Leader: Gorish\r\nThe guild That Just Happened is a Horde PvP focused guild which is committed to the destruction of the Alliance whether they must work alone or band together with other guilds on the server. While PvP is the number one priority, every now and again for fun they band together for some casual PvE. They consist of a collection of guildies ranging back to some of the oldest guilds on Azshara, and are always looking out for a gifted PvP'er.\r\nWebsite: None - as of 05/22/08\r\n'''Blood Lords'''\r\n(Active)\r\nGuild Leader: Milane\r\nBlood Lords is a fun and relaxed guild, we have many real life friends and family. We enjoy raiding in a social environment and plan to soon enter into 25 man raids. We also have a Guild Day twice a month where the guild gets together to duel, play various games, and raid the Alliance.\r\nWebsite: \r\n'''Delusion'''\r\n(Inactive)\r\nGuild Leader: Erison\r\nCreated February 2007, Delusion provides a casual raiding environment to it's members. With Karazhan and Gruul on farm, they now pursue more of the 25 man content. Delusion is very active and plans on remaining a progressing part of the server. One of the lesser known raiding guilds, Delusion still remains on the server in a ghost sense, with many members transferring off to a higher population server waiting for the release of WLK. A handful remained on Azshara and now run in Leather Lace and Steel under the leadership of Angelkissed and Antonious. \r\nWebsite: \r\n'''ZERG'''\r\n(Active)\r\nGuild Leader: Cong\r\nUnknown Info - 05/22/06.\r\nWebsite: \r\n'''The Wet Bandits'''\r\n(Active)\r\nGuild Leader: Wilferal\r\nThe Wet Bandits have been a part of Azshara for quite some time, progressing through Karazhan only to then face the ominous preassure of progressing into 25 man raids. Despite opposition, and a break in raiding, many of its core members have pushed to bring back the guild, and under the leadership of Darthbrooks, The Wet Bandits are PvE focused and currently raiding Karazhan and Zul'Aman, with a desire to possibly push onwards.\r\nWebstie: None - as of 05/22/08\r\n'''Blue Garter'''\r\n(Inactive)\r\nBlue Garter was the most progressed guild on Azshara on either faction, and as of November 9, 2007, was the only guild to have downed Illidan. However, Blue Garter transferred to Mal'Ganis around Dec. 1, 2007. They disbanded as a raiding guild in 1-2008 and many prominent members joined a guild called Aurora if they chose to continue raiding and still some others returned to Final Fantasy Online for the time being. Quite a few simply retired from raiding and/or WoW but continue to keep BG alive on Mal'Ganis.\r\n'''Crucial'''\r\n(Inactive)\r\nBroke up in early 2008. Absorbed several other guilds, including many Alliance rerolls. Highly sucessful and respected raiding guild under the leadership of Fric, who is one of the most highly respected players on the server. Fric resigned for real life after leading the guild from MC all the way through TBC content finishing up in BT, just short of Illidan. Most of the guild has either left for Magtheridon to form the guild Run Out or went to Sargeeras to form the guild Parry Mechanic. Both factions are reported to be doing well in PVE progression.\r\n'''Spitfire'''\r\nSpitfire was one of the most progressed guild before TBC, notably being one of the only two horde raiding guild downing C'thun in AQ40(Blue Garter the other). The guild was sadly renamed Reforged and broke up in mid 2007 due to Enjin marrying a cow.\r\n* See the in the Realm Forums for more info.\r\n==Guild Progression==\r\nTo view the PvE progression of all guilds on the realm simply follow the link: [[Server:Azshara US/Guild Progression| Guild Progression]]\r\n==Crafting==\r\nSee [[Server:Azshara US/Crafting| Crafting]] for a detailed crafting list. (Current crafting list seems to be out of date and needs desperately to be updated. Should any inhabitants of Azshara desire to take this role upon themselves please do so. If you desire help please contact Haemonculi - currently working to update the server page but would be glad to assist with the crafting one as well)",},
			["Server:Azuremyst US"] = { content = "'''Azuremyst (US)''' is a [[PvE]] [[server]] located in the US [[:Category:Pacific Time Zone servers|Pacific time zone]]. It was brought online in November, 2006, in advance of the release of [[World of Warcraft: The Burning Crusade]]. After the release of The Burning Crusade in January, 2007, it accepted free [[character transfer]]s from a number of high population servers, including [[Server:Lightbringer US|Lightbringer]], [[Server:Proudmoore US|Proudmoore]], [[Server:Kilrogg US|Kilrogg]], [[Server:Uther US|Uther]], and [[Server:Hyjal US|Hyjal]]. The population of the server skews highly towards the [[Alliance]], approximately 2:1. It is a part of [[Battlegroup US Retaliation]]. Azuremyst is most known for its ridiculous forum community and lack of Horde.\r\n==Azuremyst Crafting List==\r\n** [[Server:Azuremyst_US/Crafting_list/Alchemy|Alchemy]]\r\n** [[Server:Azuremyst_US/Crafting_list/Blacksmithing|Blacksmithing]]\r\n** [[Server:Azuremyst_US/Crafting_list/Enchanting|Enchanting]]\r\n** [[Server:Azuremyst_US/Crafting_list/Engineering|Engineering]]\r\n** [[Server:Azuremyst_US/Crafting_list/Jewelcrafting|Jewelcrafting]]\r\n** [[Server:Azuremyst_US/Crafting_list/Leatherworking|Leatherworking]]\r\n** [[Server:Azuremyst_US/Crafting_list/Tailoring|Tailoring]]\r\n===Alliance===\r\n*BLAH \r\n*Epic \r\n*Forsaken Gods \r\n*Geriatric Gentlemen\r\n*Get To The Choppa \r\n*The Highborne \r\n*Letalis \r\n*OMEN \r\n*ONE PIECE \r\n*Ressurection \r\n*Sancity \r\n*Section 8 \r\n*Srz Bznz\r\n*The League of Majestic Goats\r\n*War Within a Breath\r\n===Horde===\r\n*Cult of El Pollo Grande\r\n*Fog of War \r\n*Fury of the Tza Zen \r\n*[[Guild:Rebellion (Azuremyst US) | Rebellion]] \r\n*Shotgun Bunnies \r\n==Unofficial Server Motto==\r\n*'''''We have more Night Elf Hunters than Horde!'''''\r\n==The 2007 Azuremyst Awards!==\r\nCreated by Marvelo on 11/18/2007. Copied from the original forum post.\r\n*Most @ Posts: Lif.\r\n*Longest Thread: Nukemdead (Now known as Playahata.) \"Ganking 101: A remedial course for the Horde\"\r\n*Biggest Loser: Dantebear.\r\n*Biggest Carebear : Contentious.\r\n*Best Display of Split Personalities: Elysium / Westender. \r\n*Longest Gnome Punt : Stern <punts> Neil 75 Yards.\r\n*Most Likely to Stop a Raid Due to Jumping Off Ledges: Kalgram.\r\n*Most Likely to Hault a Raid to PvP at the Entrance: One Piece.\r\n*Most Likely to Wait Until They Are Done With a BG Before Defending Their City: Fury of the Tza Zen.\r\n*Most Likely to Make People Cry in Forums: Yakut / Contentious.\r\n*Most Likey to Make Guildies Cry During a Raid: Diamondx / Kleptomaggs / Zeuz.\r\n*Most Likely to QQ About Alliance PvP in Undercity: Sutech.\r\n*Most Likely to Not Craft That Epic Item You Want: Brodnax / Marvelo.\r\n*Alliance Member With Most /target Macros Made for Them: Kyoshi / Marvelo / Pro(Now known as Ject.)\r\n*Horde Member With Most /target Macros Made for Them: Taurrak / Dasboot / Xesh / Rob / Sutech.\r\n*Most Likely to Write a Screen Play: Anked.\r\n*Person You are Most Likely Buying Your AH Items From [A]: Kristlyassa.\r\n*Most Likely to Have a Bad Day at Work and Organize a PvP Event to Make Others Suffer: Marvelo.\r\n*Most Likely to Rage Quit From a 5 Man While Drunk: Crimm.\r\n*Most Likely to Be Told Her Voice in Vent Sounds Like a Porn Star: Anteela.\r\n*Most Likely to Reroll to the Winning Team: Dasboot and his Wife. \r\n==The 2008 Azuremyst Awards!==\r\n*Coming 11/12/2008.\r\n==Server Progression == \r\nLast Updated: '''07/28/2008''' Updated to post ''#276'' on the old thread and post ''#124'' on the by '''Kintrok'''\r\n===Top Ten Guilds===\r\nOnly the top 10 guilds are shown here. Ranks are based on kills and time of kill. For a more up to date listing, please go to this on the Azuremyst realm forums.\r\n<div style=\"max-width:90em; margin-left:auto; margin-right:auto;\">\r\n===The Sunwell Plateau (T6.5 Content)===",},
			["Server:Azuremyst US/Crafting list/Alchemy"] = { content = "The following is a listing of '''High End Crafting''' in [[Alchemy]] for the server [[Server:Azuremyst_US|Azuremyst US]]. \r\nAll patterns which create Bind on Equip items from Burning Crusade have been listed.\r\nIf you wish to be added, or there is a craftable item missing, please post on the realm thread I have created.\r\n== [[Alchemy]]==\r\n<onlyinclude>\r\n===Flasks===\r\n===Protection Potions/Cauldrons===\r\n===Elixirs===\r\n===Potions===\r\n===Transmutes===",},
