			["Shattered Hand Guard"] = { content = "'''Shattered Hand Guard''' can be found in [[Hellfire Peninsula]] .\r\n==Quests== \r\n==Drops == \r\n \r\n0.01% Chance of a [[rare]] drop.\r\n0.24% Chance of an [[Uncommon]] drop.\r\n0.02% Chance of a [[common]] drop.\r\n0.07% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Shattered Hand Legionnaire"] = { content = "'''Shattered Hand Legionnaires''' are the objective of the quest Pride of the Fel Horde (Alliance) and Pride of the Fel Horde (Horde).\r\n==Quotes [voiced]==\r\n* ''Show them no quarter! Form up!''\r\n* ''Get ready! This shouldn't take long...''\r\n* ''Form up! Let's make quick work of them!''\r\n* ''Form ranks and make the intruders pay!''\r\n* ''Line up, and crush these fools!''\r\n* ''We must halt their advance! Take your positions!''\r\n* ''Lok-Narash! Defensive positions!''\r\n* ''Join the fight! Agrama-ka!''\r\n* ''Next warrior, step up!''\r\n* ''Fighter down!''\r\n* ''Where's my support?''\r\n* ''Get up!''\r\n* ''Sleep on your own time!''\r\n* ''Replacement, quickly!''",},
