			["Tailoring Patterns/grandmaster"] = { content = "#REDIRECT [[Northrend tailoring patterns]]", redirect = "Northrend tailoring patterns",},
			["Tailoring Patterns/journeyman"] = { content = "#REDIRECT [[Classic tailoring patterns]]", redirect = "Classic tailoring patterns",},
			["Tailoring Patterns/master"] = { content = "#REDIRECT [[Outland tailoring patterns]]", redirect = "Outland tailoring patterns",},
			["Tailoring quest"] = { content = "#REDIRECT [[Tailoring quests]]", redirect = "Tailoring quests",},
			["Tailoring trainer"] = { content = "#REDIRECT [[Tailoring trainers]]", redirect = "Tailoring trainers",},
			["Tailoring trainers"] = { content = "A '''tailoring trainer''' is an [[NPC]] that offers [[tailor]]s the opportunity to train and learn recipes.\r\nNote\r\nIn [[Patch 2.3]], Tailoring profession trainers were changed to train up to Artisan level (skill level 300), and any redundant trainers in capitals were changed into simple apprentices without practical function.\r\n</noinclude>\r\n</noinclude>",},
			["Tailors"] = { content = "#redirect [[Tailoring]]", redirect = "Tailoring",},
			["Taim Ragetotem"] = { content = "'''Taim Ragetotem''' is a level 61 [[Alterac Valley]] [[battlemaster]] located on [[Hunter Rise]] in the [[tauren]] city of [[Thunder Bluff]].\r\nSee [[List of Thunder Bluff NPCs]].",},
			["Tainted"] = { content = "Strong [[demon]]s — the heroes of their kind — can corrupt individuals, [[tribe]]s, or even whole [[Race|species]]. The victims must drink of the demon’s blood. This act begins a transformation, taking anywhere from years to generations to millennia, that converts the creatures and their descendants into demons. Those who have begun but not completed this process are '''tainted''' creatures. Tainted creatures typically serve the [[Burning Legion]] in one fashion or another. Tribes, nations, and species that accept a demon's pact become tools. Individuals worthy of personal recruitment often become the lieutenants to powerful demons, experience compensating for their innate inferiority. Tainted creatures have a demonic awareness of the physical world, giving it blindsight out to sixty feet. In addition, tainted creatures who have recently consumed the blood of a very strong demon gain the ability to cause fel damage: All of a tainted creature's attacks do fel damage, including attacks made with weapons.\r\nTainted is a template that can be used on many creatures. [[Tainted orc]]s are the most famous example of them.",},
			["Tainted Arcane Wraith"] = { content = "==Description==\r\n'''Tainted Arcane Wraiths''' are level 4 [[elementals]] found on [[Falthrien Academy]]. They serve under [[Felendren the Banished]]. \r\n==Quests==\r\nWindows to the Source.\r\nFelendren the Banished.\r\nTainted Arcane Sliver.",},
			["Tainted Ooze"] = { content = "'''Tainted Ooze''' can be found in [[Felwood]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.03% Chance of a [[rare]] drop.\r\n0.38% Chance of an [[Uncommon]] drop.\r\n0.01% Chance of a [[common]] drop.\r\n0.14% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Tainted Scar"] = { content = "'''The Tainted Scar''' is the large southwestern expanse of the [[Blasted Lands]] that serves as domain to many of the remaining forces of the [[Burning Legion]] that remained on [[Azeroth]] after the [[Third War]]. (Another such group of demons remains in the similarly scorched and twisted [[Darkwhisper Gorge]] in [[Winterspring]]). With their leaders gone and their forces diminished, they had no choice but to stand fast and wait for the [[Dark Portal]] to open once again.\r\nThis area is covered with a thick, vile mist that chokes mortals stupid enough to venture close. [[Demons]] dwell here and pervert the already taxed land with their energies. Before Lord [[Kazzak]] departed for Outland he took up residence here.\r\n==Forces==\r\n* '''[[Highlord Kruul]]'''\r\n* '''[[Felguard Elite]]'''\r\n* '''[[Manahound]]'''\r\n* '''[[Doomguard Commander]]'''\r\n* '''[[Dreadlord (mob)|Dreadlord]]'''",},
			["Tainted Vitriol"] = { content = "'''Tainted Vitriol''' is acquired while mining [[vein]]s in [[Felwood]] while in possession of a [[Cenarion Beacon]].\r\nIt is an objective of the quest [[Salve via Mining]]",},
			["Tajarri"] = { content = "'''Tajarri''' is a level 60 [[quest giver]] located at the [[Shrine of Remulos]] in the [[contested]] territory of [[Moonglade]].\r\nTajarri once trained a young beardless human to be a druid. When the young druid has successfully completed the \"trial of the lake\", she congratulated him. She knew it had been a privilege to test students that came to the Moonglade for further druidic training. He thanked her, and she told him he would become a valuable protector of nature. She thought to herself of how desperately the world needed more people like him.\r\nShe starts the following quests:\r\n* Trial of the Sea Lion\r\n* Trial of the Sea Lion\r\nSee [[List of Moonglade NPCs]].",},
			["Takata Steelblade"] = { content = "'''Takata Steelblade''' is a level 40 [[quest giver]] located in [[Ghost Walker Post]] in the [[contested]] territory of [[Desolace]]. He is the head of the regional effort to counter the general demonic threat wherever possible. Both Takata and [[Maurin Bonesplitter]] were sent to Desolace by [[Keldran]] to ensure that the [[Burning Blade]] is dealt with as swiftly as possible. Acting on the orders from Keldran, Takata is chiefly noted for the massacre of the [[satyr]] population of Desolace due to their affiliation with the Burning Blade. At the same time, Maurin Bonesplitter concentrated almost exclusively on dealing specifically with the Burning Blade, although his efforts have been largely unsuccessful.\r\nHe starts the following quests:\r\n* Alliance Relations\r\n* Alliance Relations\r\n* Befouled by Satyr\r\n* The Corrupter (Elite)\r\nSee [[List of Desolace NPCs]].",},
			["Take Down Tethyr!"] = { content = "==Objectives==\r\n[[Major Mills]] at the [[Theramore]] docks wants you to defeat [[Tethyr]].\r\n==Description==\r\nSea monster or not, we're not going to risk the safety of our shipping. I've ordered our best marksmen to prepare for a confrontation with this [[Tethyr]]. The artillerymen have augmented the dock's defenses with three mortars.\r\nI'm going to order the lighthouse's lamp illuminated. If Tethyr does attack, it will be your job to operate the mortars and take down the beast before it can kill all of the marksmen. I wouldn't stand in one place too long, though. Using the mortars is likely to draw it's attention.\r\n==Completion==\r\nWell done, <name>! I'll admit, when I caught my first glimpse of that beast, I had doubts about our ability to defend the docks, but you held together the defenders brilliantly!\r\n==Rewards==\r\nYou will also receive: 75 silver copper \r\n==Notes==\r\nUse the mortars on the docks nearest Tethyr to speed the process and successfully complete the quest. It is not necessary to tag Tethyr to complete the quest.\r\nFalling in the water or going too far away from the docks will fail you and you'll have to restart the quest. On rare occasions, if you restart a failed quest too quickly (while Tethyr is still alive and leaving the dock area), he will not come forwards for the new quest, and you'll have to intentionally fail and restart. \r\nThis author observed that a previous fail on the part of another player which involved the deaths of all the marksmen perhaps also caused the death of Major Mills. After approximately 5 minutes, Major Mills respawned and this author was able to start the quest. If Major Mills cannot be found, it's possible a previous player catastrophically failed moments ago; be patient, he'll show up where he should be.",},
			["Take Five Bases"] = { content = "==Objectives==\r\nHold five bases in [[Arathi Basin]] at the same time, then return to Deathmaster Dwire in [[Hammerfall]]. \r\n*Hold Five Bases.\r\n== Description==\r\nIt is difficult to see, so deep we are in the conflict, but our spies report a weakening in the League of Arathor's resolve. We must use this window and strike a brutal blow against them! Return to [[Arathi Basin]] and throw yourself against our foes. Curse them and kill them and control all five strategic bases! Send their soldiers screaming and bleeding from the front lines, with stories of your cruelty on their mewling lips.\r\nDo this, and score a great victory for the Defilers. \r\n== Reward==\r\nYou will also receive: 2 gold 70 silver copper \r\n== Completion==\r\nThe cries of the [[Alliance]] as you and your compatriots attacked them could be heard even from here, <name>. I can almost pity them for the pain and fear you delivered to their ranks. Almost, but not quite.\r\nYour value to the Defilers is without question. Your deeds in [[Arathi Basin]] have been most impressive, and have echoed among the chambers of Varimathras... and the Dark Lady herself. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*7950 [[XP]] (or 60 silver copper at level 70)\r\n==Notes==\r\nYou must be exalted with the [[Defilers]] and level 60 in order to obtain this quest.",},
			["Take Four Bases"] = { content = "==Objectives==\r\nHold four bases at the same time in [[Arathi Basin]], and then return to Deathmaster Dwire in [[Hammerfall]]. \r\n* Hold Four Bases.\r\n==Description==\r\n<name>, as the battles over Arathi Basin rage, news of your actions have reached many ears. You are highly regarded among us, which gives me confidence that you will accomplish the mission I now have for you.\r\nIt is time to send a message to the [[League of Arathor]]. We must show them that their holdings in Arathi Basin are tenuous and quickly lost. We will show them this by holding, all at once, four strategic points in Arathi Basin.\r\nSucceed in this, <name>, and earn great respect among the [[Defilers]]. \r\n==Completion==\r\nGood work, <name>! Your latest actions in [[Arathi Basin]] were quite difficult, and so their successes are quite praiseworthy. The League of Arathor must be reeling from the last skirmishes in the basin, licking their wounds and, let us hope, rethinking their choice to fight here. \r\n==Rewards==\r\nYou will receive: 2 gold 70 silver copper \r\n==Gains==\r\n*9950 [[XP]]\r\n*1000 Reputation with [[The Defilers]]",},
			["Taking Back Acherus"] = { content = "Though they are free from the Lich King's dominance, the death knights' battle has just begun...\r\n==Objectives==\r\nUse your [[Death Gate]] spell to return to [[Acherus: The Ebon Hold]]. Report to [[Highlord Darion Mograine]] once you arrive.\r\n==Description==\r\nThe haze has been lifted. I can see as clearly now as the day that I plunged the Ashbringer into my own heart to free [[Alexandros Mograine|my father's]] cursed soul: my last memory as a free man.\r\nWe must take back Acherus from the [[Scourge]] if our order is to survive in this new world. I have taught you how to call forth a death gate. The death gate will return you to Acherus when you call upon it, <name>. The first battle of the [[Knights of the Ebon Blade]] is underway! Death to the Scourge!\r\n==Completion==\r\nThe [[Lich King]] has returned to [[Northrend]], wounded by the Ashbringer, but the second floor still holds the last of his armies.",},
			["Takrin Pathseeker"] = { content = "'''Takrin Pathseeker''' is a level 30 [[quest giver]] located in [[Razor Hill]] in the [[orcish]] starting zone of [[Durotar]].\r\n==Quest==\r\n* starts Conscript of the Horde\r\n==See Also==\r\n*[[List of Durotar NPCs]]",},
			["Tal'kraa"] = { content = "'''Tal'kraa''' was once the Elder [[Shaman]] of the [[Frostwolf Clan]]. He passed away nearly a century prior to the creation of the [[Dark Portal]]. [[Mother Kashur]] was his great granddaughter. Though he was many generations removed from her, and she had never met him, she called him simply grandfather. He visited Mother Kashur, now the elder shaman of the Frostwolves, in her dreams and demanded she take the then-young [[Durotan]] to [[Oshu'gun]] so he could see him with his own \"eyes\". He sensed Durotan would never be a shaman, but knew he had a great destiny and from his line salvation would come.",},
			["Tal"] = { content = "'''Tal''' is a level 55 [[wind rider]] [[flight master]] located in the Wind Rider Roost in the [[tauren]] city of [[Thunder Bluff]].\r\nHe starts the quest 10 and ends the quest 10.\r\nSee [[List of Thunder Bluff NPCs]].",},
			["Talaara"] = { content = "'''Talaara''' is a level 63 [[weapon]] [[vendor]] located at [[Temple of Telhamat]] in the [[contested]] territory of [[Hellfire Peninsula]].\r\nSee [[List of Hellfire Peninsula NPCs]].",},
			["Talario"] = { content = "Talario is a human spellcaster. She is the sister of [[Renmar]]. She is a companion to [[Drann]].",},
			["Talasite"] = { content = "Talasite is a [[rare]] quality gem used in [[Jewelcrafting]] and [[Engineering]], the gems fit both and sockets.\r\n==Source==\r\nThis gem is mined from [[Fel Iron]], [[Adamantite]], [[Rich Adamantite]] and [[Khorium]] deposits. It is also a [[world drop]].\r\n==Talasite as an ingredient==\r\n'''Talasite''' is used in the following recipes:\r\n===[[Jewelcrafting]]===\r\n*Coronet of Verdant Flame\r\n*Figurine - Talasite Owl\r\n* Gems:\r\n===[[Engineering]]===\r\n*Gnomish Power Goggles\r\n*Magnified Moon Specs\r\n*Tankatronic Goggles",},
			["Talbuk"] = { content = "'''Talbuks''' are beautifully colored, striped, horned antelope-like creatures native to Draenor, residing primarily in the plains of [[Nagrand]]. They usually congregate underneath trees, but some groups of them are seen wandering with their respective Patriarchs. The strongest talbuk, Bach'lor, is sought after by game hunters as proof of their skill.\r\nThere is also a herd of talbuks living in the Stormspire's Eco-Dome consisting of Talbuk Doe and Talbuk Sire. Talbuk does are non-aggressive beasts that alert surrounding males when attacked, while the decidedly more aggressive sires use their large hooves to stun attackers. When weakened, these talbuk can be tagged for Aurine Moonblaze, a druid sent by the Cenarion Expedition to investigate the Ethereal technology's effects on wildlife. \r\nOne breed of talbuk is known for its twelve prongs that are sharp and dangerous. They were hunted for the orcish [[om'riggor]] ritual.\r\nTypes of Talbuks in-game:\r\n*Injured Talbuk\r\n*Talbuk Doe\r\n*Talbuk Patriarch\r\n*Talbuk Sire\r\n*Talbuk Stag\r\n*Talbuk Thorngrazer\r\n==Mount==\r\nThey are also a special [[mount]] available for [[Alliance]] players exalted with the [[Kurenai]] faction and to [[Horde]] players exalted with the [[Mag'har]] faction. The faction mounts are available in White, Tan, Silver, and Cobalt, with each color being available as a Riding Talbuk and War (armored) Talbuk.\r\nThere are also Dark Riding and Dark War Talbuks from the [[Halaa]] merchants which cost Halaa Battle Tokens and Halaa Research Tokens and require no [[reputation]].\r\nSee [[Talbuk (Mount)]] for more info.",},
			["Talent"] = { content = "A '''talent''' is an additional [[class]]-specific [[ability]] or [[power]] that requires [[talent point]]s to gain or improve. Each class has three [[Talent Tree]]s to choose from.\r\n==Basics==\r\nPersonalizing your character is what separates each character of the same class. During the early Beta Test, the character '''Talent''' system was very rough and Blizzard went back to the drawing board to make the system more intuitive by adding prerequisites to the Talent system. If you have played the Diablo series of games you'll be more than familiar with the idea of a skill tree and this is the new system Blizzard has employed for [[World of Warcraft]]'s Talent point assignment.\r\n==Why have Talents?==\r\nAs you play the game and your character levels up, starting at level 10, your character is given 1 [[talent point]] (TP) every level to assign to their [[Talent Tree]]. Each character has a different tree and different Talents. The reason talents are included is so that each player in the game of the same class will be slightly different as far as how their skills work and how effective they are in combat. Without this system each class character would be identical, which doesn't exactly add variety to the gamespace. It's up to you as the player how to make your character different by [[Specialization|specializing]] in the character's different Talents.\r\n==How does the Talent system work?==\r\nWith the maximum character level set at 70, a player can effectively assign a maximum of 61 talent points to their tree (leveling from 10 to 70 gives 61 points). Attaining a certain Talent's ability to augment your character is not as simple as just assigning 1 single point into a Talent.\r\nFor example, to activate and utilize a Talent in the second tier of the tree, you may have to assign 5 of your TPs into a Talent in the top tier prerequisites before it becomes active. Because the system is tiered, players have to think long and hard before assigning a point. Once you have allocated a TP, you cannot unallocate it. However, there will be [[NPC]]s available in some of the larger cities to allow players to reassign all their Talents, for a price, of course. This price will increase every time you reassign your Talents.\r\nWhile planning one's [[template]], take note that the ''ultimate talent'' in each of the Talent Trees require 40 Talent Points placed in that tree to unlock. This means that to learn the ultimate Talent in a tree, you need to place at least 41 points in that tree (attained at level 50). This prevents you from learning the ultimate Talent from either of the other 2 trees because you will only have a maximum of 61 Talent Points.\r\nEach character class features three Talent Trees, each unique to the class. You may want to specialize in one tree or spread your points over two or even three trees. Spreading your points will mean that it would be impossible for you to become efficient in one single Talent discipline - the choice is yours.\r\n* Often there are Talents in one tree that will provide useful benefits to another tree (such as the [[Elemental Precision (mage talent)|Elemental Precision]] talent in the Mage's Frost tree, which would benefit both a Mage speccing for Fire and a Mage speccing for Frost). It is often useful to place Talent Points in multiple trees in order to further enhance your desired spec.\r\n==Where do I assign Talent Points?==\r\nThere are a couple of ways to activate your Talent screen. One method is to click the Talent icon on the interface bar at the bottom of the screen (assuming you are using the default [[UI]] coded by Blizzard). This pops up the Talent interface which features the main Talent window showing the tree and Talents. It also features three tabs along the bottom which can be clicked to flip between each of the three trees. You can also activate the Talent interface by pressing the N key (if you haven't unbound it or bound the key to a different action).\r\n==What if I choose the wrong Talents?==\r\nDon't panic! Players have the ability to unlearn all their talents and start over. Your [[Class Trainers|Class Trainer]], for a modest fee (increases by 5 gold each use, to a maximum 50 gold , however the first time you do this you will only be charged 1 gold , a freebie of sorts), will let you recover all Talent Points spent up to this point. You can then reassign all your points. Keep in mind that all points are removed from '''ALL''' trees, and you'll also unlearn higher ranks of the spells achieved through a talent point expenditure. Fortunately, as of patch 2.4 you will automatically relearn the ranks of these spells as soon as you put talent points back into them.\r\nSince [[Patch 1.11 (Release Notes)|patch 1.11]] there is a decay in the cost of such talent respecs:\r\nThe cost to unlearn talents will now decay over time. This cost will be reduced by a rate of 5 gold per month to a minimum of 10 gold.\r\nNote: Although the official patch notes continue to say that the minimum is 10 gold , subsequent official posts on the WoW forums have confirmed that that is a mistake, and the cost will only be reduced to a minimum of 15 gold .\r\nOccasionally, Blizzard will restructure a class's talent tree. If the change is significant, they will reset that class's tree, allowing you to respec for free. Talent changes do not always give a free respec: for example, in patch 2.3.2, the mage spell [[Iceblock]] was made trainable, and the talent [[Cold Snap]] was moved to its place, and the new spell [[Icy Veins]] was put in Cold Snap's old spot. This change did not give mages a free respec, but it required those mages specced for Ice Block to go to a trainer and buy that spell.\r\n==Where can I find talent calculators?==\r\n* \r\n*",},
			["Talents"] = { content = "#REDIRECT [[Talent]]", redirect = "Talent",},
			["Talent Builds Guide"] = { content = "#REDIRECT [[Specialization]]", redirect = "Specialization",},
			["Talent point"] = { content = "#REDIRECT [[Talent]]", redirect = "Talent",},
			["Talent Points"] = { content = "#REDIRECT [[Talent]]", redirect = "Talent",},
			["Talent tree"] = { content = "This is one of the categories in which a [[class]]'s [[talent]]s are divided. So named because the talents branch out similar to a tree structure.",},
			["Talgath"] = { content = "'''Talgath''' was an old friend of [[Velen]], entrusted by the prophet to gather eredar who were wary of [[Sargeras]] and his tantalizing offer. Unfortunately, Talgath was seduced by those very promises, and betrayed Velen and his cohorts to [[Kil'jaeden]]. In spite of this, the [[naaru]] managed to spirit Velen's faction, the [[draenei]], away, bringing the Deceiver's wrath upon him. \r\nKil'jaeden was merciful, however, and Talgath was the agent he placed in charge of finding the draenei. Some twenty-five millennia later, Talgath remained unsuccessful in his search - he had found countless worlds that had been briefly touched by the draenei, but never their refuge. Talgath was eventually successful however, and located [[Draenor]].\r\nFollowing this, Kil'jaeden assumed full command of the operation, and Talgath was reassigned. His fate afterwards is unknown.\r\nTalgath is one of the high ranking leaders within the Burning Legion infrastructure, being close to even Kil'jaeden in rank.",},
			["Talionia"] = { content = "'''Talionia''' is a level 40 [[warlock trainer]] located in [[the Sanctum]] in [[Murder Row]] in the [[blood elf]] capital of [[Silvermoon City]].\r\nShe starts the quest The Stone.\r\nSee [[List of Silvermoon City NPCs]].",},
			["Talk"] = { content = "To communicate with a non-[[player]] character ([[NPC]]) by right-clicking on them. [[Player]] characters communicate with each other through [[chat]].\r\nAdditional notes:\r\n* You should see a speech bubble icon () with a small triangle (<font color=\"silver\">silver</font> or <font color=\"gold\">gold</font> ) when you move your pointer over the creature.\r\n* If your character is too far away to talk, the small triangle will be <font color=\"silver\">silver</font>.\r\n*: ''out of range''\r\n* If your character is close enough to talk, the small triangle will be <font color=\"gold\">gold</font>.\r\n*: ''in range to talk''\r\n''Note: You can speak to NPCs in [[druid]] [[form]]s as of [[Patch 2.0.3]].''",},
			["Talk:Airship"] = { content = "== Airships vs Gunships==\r\nThe gunship is an airship only if it uses gas. [[User:Rolandius|Rolandius]] <small>([[User talk:Rolandius|<span title=\"Rolandius's Talk\">talk</span>]] - [[Special:Contributions/Rolandius|<span title=\"Rolandius's Contributions\">contr</span>]])</small> 02:08, 21 August 2008 (UTC)\r\nThe Horde one does. The Alliance one uses rotors of all kinds. Are not also gunships attack helicopters? Regardless, I feel the page should affect Blizzard's usage (which likely has been abandoned for just 'gunship' so it is pointless anyway).-- 02:22, 21 August 2008 (UTC)\r\nIf the only difference between the two was gas, wouldn't it be called a Gasship... they are both terms meaning the same thing, its no different than calling it a flying machine, sky-engine... or even a zeppelin. 02:32, 21 August 2008 (UTC)\r\n:It seems to have been changed without a counterpoint to this. Oh well, I do not feel like opening a can of worms this late. Who knows? He may be right.-- 02:49, 21 August 2008 (UTC)\r\n::I listened to the gunship interview link. I never heard them say airship, just gunship. I don't know what they actually look like though, just that gnomish and goblin engineers worked on them. A flying machine covers both types. But under that category there are two types: gas types of aircraft and ones that don't need gas (not fuel gas but buoyant gas). A dirgible, zeppelin, and ballon are airships. A gyrocopter and biplane are not airships. [[User:Rolandius|Rolandius]] <small>([[User talk:Rolandius|<span title=\"Rolandius's Talk\">talk</span>]] - [[Special:Contributions/Rolandius|<span title=\"Rolandius's Contributions\">contr</span>]])</small> 02:58, 21 August 2008 (UTC)\r\n:I hope I don't have to bring up the warning about applying earth definitions to Warcraft Universe where definitions may not necessarily mean the same thing. However, if one wants to look at straightforward dictionary definitions airship just refers to a \"lighter-than-air aircraft with propulsion and steering mechanisms\"-Webster.com. It could more or less refer to several types of aircraft. Not all are zeppelins.[[User:Baggins|Baggins]] ([[User talk:Baggins|talk]]) 03:44, 21 August 2008 (UTC)\r\n::Well not really. Airships are \"lighter-than-air (buoyant) aircraft with propulsion and steering mechanisms\". Your forgetting the buoyant part. It fits with WoW. There are flying machines (aircraft) of which there are two kinds. The ones that use gas and the ones that don't. Are you really saying a zeppelin is just like a gyrocopter and a biplane is the same thing as a scout balloon? [[User:Rolandius|Rolandius]] <small>([[User talk:Rolandius|<span title=\"Rolandius's Talk\">talk</span>]] - [[Special:Contributions/Rolandius|<span title=\"Rolandius's Contributions\">contr</span>]])</small> 04:11, 21 August 2008 (UTC)\r\nActually, what I put was quote from Webster.com. Your quote is not the same as the one on Websters. But yes different dictionaries will give you different definitions.[[User:Baggins|Baggins]] ([[User talk:Baggins|talk]]) 04:15, 21 August 2008 (UTC)\r\nOk so are you saying that airships are just like biplanes? [[User:Rolandius|Rolandius]] <small>([[User talk:Rolandius|<span title=\"Rolandius's Talk\">talk</span>]] - [[Special:Contributions/Rolandius|<span title=\"Rolandius's Contributions\">contr</span>]])</small> 04:16, 21 August 2008 (UTC)\r\nBiplanes are a kind of airships if you use Princeton's definition;\r\nairship \r\nnoun \r\na steerable self-propelled aircraft \r\nWordNet® 3.0, © 2006 by Princeton University. \r\nLinguistics are fun ;). Everyone has their own definitions.[[User:Baggins|Baggins]] ([[User talk:Baggins|talk]]) 04:21, 21 August 2008 (UTC)\r\nLOL Ok well I don't know I am going by this, which makes sense to me and looks like it works with WoW too, on Wikipedia.\r\n\"Aircraft fall into two categories: lighter-than-air (aerostats), and heavier-than-air (aerodynes). Aerostats use buoyancy to float in the air in much the same way that ships float on the water. They are characterized by one or more large gasbags or canopies, filled with a relatively low density gas such as helium, hydrogen or hot air, which is less dense than the surrounding air. When the weight of this is added to the weight of the aircraft structure, it adds up to the same weight as the air that the craft displaces. Heavier-than-air aircraft must find some way to push air or gas downwards, so that a reaction occurs (by Newton's laws of motion) to push the aircraft upwards. This dynamic movement through the air is the origin of the term aerodyne. There are two ways to produce dynamic upthrust: aerodynamic lift, and powered lift in the form of engine thrust.\r\nSo to put it simply they both can use propulsion and steering mechanisms. One uses a gas bag type item though. The other doesn't. So you have your airship, blimp, zeppelin, balloon, and dirigibles. Then you have your gyrocopter, biplane, triplane, and monoplanes. Does no one see the difference between these two groups or is it just me? [[User:Rolandius|Rolandius]] <small>([[User talk:Rolandius|<span title=\"Rolandius's Talk\">talk</span>]] - [[Special:Contributions/Rolandius|<span title=\"Rolandius's Contributions\">contr</span>]])</small> 04:31, 21 August 2008 (UTC)\r\nYou might have missed the WoWWiki rule that states that Wowwiki is not Wikipedia, or any other encyclopedia or dictionary. \r\nBTW, dirigibles, blimps, and zeppelins are all just alternate names of the same type of craft, although the terms originate from seperate countries, languages, or brand names. A steerable lighter than air craft. A balloon is seperate in that it isn't normally steerable.[[User:Baggins|Baggins]] ([[User talk:Baggins|talk]]) 04:39, 21 August 2008 (UTC)\r\n:Well I know it isn't wikipedia but we have to get some definitions from somewhere. I just don't see where in lore it states that airships are not the buoyancy type of aircraft. It seems easy to me. Like the saying goes, \"which one of these doesn't belong\". You have airships, dirigibles, zeppelins, balloons, gyrocopters, biplanes, triplanes, and monoplanes. Don't you see some of these are different from some others? [[User:Rolandius|Rolandius]] <small>([[User talk:Rolandius|<span title=\"Rolandius's Talk\">talk</span>]] - [[Special:Contributions/Rolandius|<span title=\"Rolandius's Contributions\">contr</span>]])</small> 04:50, 21 August 2008 (UTC)\r\n::\"we have to get some definitions from somewhere.\"\r\n:Yes, WoWWiki policy is that definitions should come from official Warcraft sources or at least designer notes. Anything else would likely be speculation.\r\n:If you can't find any definitions in official sources, then the page is likely even less than a stub & probably should be merged into another related article as a sidenote. ...or probably shouldn't exist at all do to \"relevance\" issues (remember we are not a dictionary website, and we aren't trying to define every single word used in a warcraft source).\r\n:As I recall this word was merged into Zeppelin or Flying machine originally. Since it can relate to both.[[User:Baggins|Baggins]] ([[User talk:Baggins|talk]]) 04:58, 21 August 2008 (UTC)\r\n::Ya, I actually put a merge tag in the airship page about 2 days ago or something. I am not sure what happens after that though. The only thing the page has is two sentences. One about airships being flying machines which everyone knows already. Another about zeppelins being airships. A third sentence I removed because it said gunships are airships. I went to the interview link and I didn't hear them mention airships unless I missed it. Does someone review the merge suggestion now or vote on it? [[User:Rolandius|Rolandius]] <small>([[User talk:Rolandius|<span title=\"Rolandius's Talk\">talk</span>]] - [[Special:Contributions/Rolandius|<span title=\"Rolandius's Contributions\">contr</span>]])</small> 05:06, 21 August 2008 (UTC)\r\nDefinitions aside, I feel this is my fault. 'Airship' was indeed not used in the interview, 'Gunship' was. I added that they were airships based on an unofficial preview (they were wrong in that respect), so it is NOT a term used in this context at all. Therefore, this conversation about the definition is irrelevant (and Blizzard's is supreme anyway). For those who do not know what they look like, the Horde one is a big spiky boat with two long zeppelin balloons on top and a massive gun in front and the Alliance one is a roundish boat with rotors all over, a bomb bay, and eagle head motif in the front and on the bridge in the back (little pictures of them can be seem on the Icecrown map BTW). Also, this page was created because someone left a dead link to it on [[flying machine]].-- 17:38, 21 August 2008 (UTC)",},
			["Talk:Bloodmyst Isle questing guide"] = { content = "I've put up and actual quest guide, instead of the straight list of quests. However it badly needs editing, and formatting. I'm only manage to put in all the quest links before running out of enthusiasm to continue.\r\nI'm also quite sure that it's not an optimal quest guide. I'm hoping that a bad one is better than nothing.\r\n[[User:TruthNZ|TruthNZ]] 03:52, 3 March 2008 (UTC)\r\nMajor rewrite to something more efficient, although it has a strong Draenei bias. I did try to reuse as much of TruthNZ's text as possible. <span style=\"font-size: 0.85em; padding: .1em .1em; border: 1px #00aaff solid; background-color: #2C2C2C\">'''[[User:Dang Fool|<span style=\"cursor:help;color:]]''' ( [[User talk:Dang Fool|<span style=\"color:]] | [[Special:Contributions/Dang Fool|<span style=\"color:]] )</span> 16:50, 25 April 2008 (UTC)",},
			["Talk:Cleave/Analysis"] = { content = "An unfortunate habit in the analysis of [[Heroic Strike]] and [[Cleave]] is the incorrect usage of its [[Damage]]-per-[[Rage]] as a method of calculating its efficiency. As a [[Warrior]] improves the [[Quality]] of their [[Gear]], the speed at which they generate [[Rage]] improves as well. With [[Heroic Strike]] and [[Cleave]], however, the cost of the [[Ability]] will also increase with [[Gear]], due to the fact that they will also remove the [[Rage]] that would have been generated by one [[White [[Damage]]]] Swing.\r\nAlthough the total cost of a [[Heroic Strike]] or [[Cleave]] is often said to be \"[[Tooltip]] [[Rage]] + White [[Rage]],\" this is only partially true. Unlike [[Heroic Strike]], [[Cleave]] functions like two abilities being used simultaneously, one of which converts the [[Tooltip]] [[Rage]] cost into additional [[Damage]], and the other of which sacrifices White [[Rage]] for additional [[Weapon [[Damage]].\r\n==[[Heroic Strike]] as [[DPS]]:==\r\nA maxed [[rank]] of [[Heroic Strike]] converts 15 [[Rage]] into 176 [[Damage]] and 196 [[Threat]], or 11.73 [[Damage]] and 24.8 [[Threat]] per [[Rage]]. At the same time, however, it cancels the next source of White [[Rage]]. As the value of White [[Rage]] increases, both the rate at which [[Rage]] is generated and the total cost of the [[Heroic Strike]] will increase as well. For this reason, [[Heroic Strike]] has \"Diminishing [[Scalability]]\" (reduced benefit from [[Gear]] as [[Gear]] improves) when used for [[DPS]]. As your White [[Damage]] improves, more of your normal [[Weapon]] Swings may be converted into [[Heroic Strike]]s, but will never be able to reach 100%. On an imaginary speed 2.6 [[Weapon]], this would look like this: \r\n5 [[Rage]] per Swing: up to 1 out of every 4 Swings can be a [[Heroic Strike]], or 25.00% for 16.92 additional [[DPS]].\r\n6 [[Rage]] per Swing: up to 2 out of every 7 Swings can be a [[Heroic Strike]], or 28.57% for 19.34 additional [[DPS]].\r\n7 [[Rage]] per Swing: up to 7 out of every 22 Swings can be a [[Heroic Strike]], or 31.82% for 21.54 additional [[DPS]].\r\n8 [[Rage]] per Swing: up to 8 out of every 23 Swings can be a [[Heroic Strike]], or 34.78% for 23.55 additional [[DPS]].\r\n9 [[Rage]] per Swing: up to 3 out of every 8 Swings can be a [[Heroic Strike]], or 37.50% for 25.38 additional [[DPS]].\r\n==[[Heroic Strike]] as [[TPS]]:==\r\nWhile [[Tank]]ing, the vast majority of your [[Rage]] will be generated not by dealing [[Damage]], but by taking it. With an average [[Tank]]ing [[Weapon Speed]] of 1.6, this caps its [[Threat]] generation at 232.5 [[TPS]], when every normal White [[Swing]] is converted into a [[Heroic Strike]].\r\nUnfortunately, unlike [[DPS]] [[Warrior]]s who will produce more [[Rage]] as their [[Gear]] improves, A well-Geared [[Tank]] will take less [[Damage]] and therefore gain less [[Rage]] on [[Hit]]s. In this situation, [[Heroic Strike]] has \"Negative [[Scalability]]\" (reduced overall effectiveness as [[Gear]] improves), and becomes less effective the better your [[Gear]] becomes. Even if one assumes that a [[Tank]] will be entering higher [[Raid]]s as their [[Gear]] improves and therefore generate a similar amount of [[Rage]] from taking [[Damage]], [[Heroic Strike]] only retains a status of \"No [[Scalability]]\" (effectiveness remains the same as [[Gear]] improves) as a source of [[Threat]].\r\n==[[Cleave]] as [[DPS]]:==\r\nA maxed rank of [[Cleave]] used against two or more [[Target]]s will convert 20 [[Rage]] into 140 additional [[Damage]] and 130 [[Threat]], or 7 [[Damage]] and 13.5 [[Threat]] per [[Rage]], and like [[Heroic Strike]] will prevent the next White [[Swing]] from generating [[Rage]]. Unlike [[Heroic Strike]], however, the [[Warrior]]'s next White [[Swing]] will do twice it's normal [[Damage]], spread between the two [[Target]]s. As a level 70 [[Warrior]] will produce one point of [[Rage]] per approximately ever 75 [[Damage]] dealt, this can be viewed as a simple 75 [[Damage]] per [[Rage]] conversion, beating some of the most efficient [[Warrior]] abilities (Compare to a single use of Execute Rank 7, which gives 61.33 [[Damage]] per [[Rage]] for the first 15 [[Rage]], and 21 [[Damage]] for each remaining point of [[Rage]].) It is for this reason that [[Cleave]] will be more effective with a slower [[Weapon]], as the higher a [[Weapon]]'s single-stroke [[Damage]] is, the more [[Rage]] is focused into [[Cleave]]'s most efficient aspect.\r\nBecause it will always convert White [[Rage]] directly into [[Damage]] at a flat rate, but can be used more often the greater the [[Warrior]]'s White [[Rage]], [[Cleave]] has \"Diminishing Compound [[Scalability]]\" (benefit from [[Gear]] increases as [[Gear]] improves, but the increase in benefit gradually diminishes) when used as [[DPS]]. Filling the amount of White [[Damage]] required to generate the White [[Rage]] used in the [[Heroic Strike]] table and converting it into a [[Cleave]] Table looks like this:\r\n5 [[Rage]] per [[Swing]] (33 White [[Damage]]): up to 1 out of every 5 Swings can be a [[Cleave]], or 20.00% for 13.30 additional [[DPS]].\r\n6 [[Rage]] per [[Swing]] (106 White [[Damage]]): up to 3 out of every 13 Swings can be a [[Cleave]], or 23.08% for 21.85 additional [[DPS]].\r\n7 [[Rage]] per [[Swing]] (180 White [[Damage]]): up to 7 out of every 27 Swings can be a [[Cleave]], or 25.93% for 31.86 additional [[DPS]].\r\n8 [[Rage]] per [[Swing]] (253 White [[Damage]]): up to 2 out of every 7 Swings can be a [[Cleave]], or 28.57% for 43.16 additional [[DPS]].\r\n9 [[Rage]] per [[Swing]] (326 White [[Damage]]): up to 9 out of every 29 Swings can be a [[Cleave]], or 31.03% for 55.62 additional [[DPS]].\r\n==[[Cleave]] as [[TPS]]:==\r\nIf the same assumption is made about [[Cleave]] that was made about [[Heroic Strike]], in that [[Rage]] generation does not increase as a [[Tank]]'s [[Gear]] improves, then the [[Threat]] produced by [[Cleave]] will increase in direct proportion to the increase in [[Gear]] [[Quality]], due to the fact that there will be a steady increase in [[Threat]] generated from the extra [[Weapon]] [[Damage]]. In this case, [[Cleave]] will have \"Direct [[Scalability]]\" (maintains a steady benefit from [[Gear]]) when used as a [[Tank]]ing tool.\r\n==Comparison:==\r\nBy quick glance at the above table, it only takes approximately 100 White [[Damage]] to make [[Cleave]] more [[Rage]] efficient than [[Heroic Strike]] for [[Damage]]. Also, if you were to calculate the [[Threat]] generated by each [[Ability]] using the same tables above keyed for a speed 1.6 [[Tank]]ing [[Weapon]], approximately 250 White [[Damage]] will make [[Cleave]] more efficient for [[Threat]] as well. \r\nBottom Line: [[Cleave]] is more efficient than [[Heroic Strike]] in most all situations in which a [[Rage]] dump is needed while [[DPS]]ing two or more [[Mob]]s. It will, however, require fairly efficient [[Gear]] in order to be more effective for [[Tank]]ing as well.\r\n([[Rage]] Generation Calculated using the current WoWWiki .)\r\n[[User:Qlmmb2086|Qlmmb2086]] 05:52, 13 December 2007 (UTC)",},
			["Talk:Dungeon Set 2"] = { content = "Can anyone explain the usage of the ectoplasmic distiller, and explain how the 8 goblin rocket fuel you recieve originally can \"fuel\" it enough to collect 36 total ectoplasms?\r\nThe ectoplasmic distiller runs off one tank of goblin rocket fuel for several minutes, so you should pull the mobs into its radius. I should add that you will be very lucky if 8 loads of fuel are enough, especially in EPL where the mobs are more spread out.\r\nIs it possible to finish the second part (Belt",},
			["Talk:Hunter Tactics"] = { content = "#REDIRECT [[Talk:Hunter tactics]]", redirect = "Talk:Hunter tactics",},
			["Talk:Teldrassil questing guide"] = { content = "This guide is not meant for power-leveling purposes. Rather, it is meant to show a player the most efficient way to complete all quests available for a particular zone. If you know of a better order or method to accomplish this, your input is welcome (in fact, greatly desired). For major changes, feel free to edit, but make a note in the talk page as to your reasoning.\r\n==Guide created==\r\nThe initial draft of the Teldrassil questing guide is complete. I plan to test it out with my new night elf character and make changes as I go. Feel free to improve on what I have started. -- 23:29, 5 September 2007 (UTC)\r\nIsn't the point of powerleveling (for the early zones, not the later zones) to get all the quests. Up until about 15 or 20ish, taking quests is the fastest method of leveling, then it becomes taking the quests which require collection. Jw --[[User:Sky2042|Sky]] ([[User talk:Sky2042|t]] · [[Special:Contributions/Sky2042|c]] · ) 23:36, 5 September 2007 (UTC)\r\n:Ha, I have no idea. I know nothing about powerleveling, I just like getting all the quest, hence this guide. It may be this is the best way to power level, I put in the note simply to say it wasn't the point of the guide, getting the quests were. For example some quests may be harder to get/complete than they would be worth to a power leveler. However, if you feel they are close enough not to matter, go ahead and remove that part of the note. And honestly we could probably merge the Shadowglen power leveling guide with this, as they are almost identical. -- 00:07, 6 September 2007 (UTC)\r\nAwww, I liked the better. It does have 15 sections, can we have it back pretty please? -- 01:12, 6 September 2007 (UTC)",},
			["Tallonkai Swiftroot"] = { content = "'''Tallonkai Swiftroot''' is a level 11 [[quest giver]] located in [[Dolanaar]] in the [[night elf]] starting zone, [[Teldrassil]].\r\nHe starts the following quests:\r\n* The Emerald Dreamcatcher\r\n* Twisted Hatred\r\n* Ferocitas the Dream Eater\r\nSee [[List of Teldrassil NPCs]].",},
			["Tallstrider"] = { content = "A '''tallstrider''', or simply '''strider''', is an ostrich-like [[beast]] native to [[Kalimdor]].\r\nTallstriders are large, flightless birds of prey that look to kill anything they can outrun or overpower. They have a pair of muscular legs, and their vestigial wings flutter as they walk. Their thick hairless necks swing about a head ending in a heavy, sharp beak as they hunts for prey. Renowned for their speed, tallstriders are difficult to shake for those trying to flee them. They resemble 6-foot tall ostriches with strong, thick necks and heavy, sharp beaks. Tallstriders are common in [[Mulgore]], [[Darkshore]], the [[Barrens]], and [[Durotar]]. Young heroes in these regions hunt these beasts in tests of honor and valor. Tales tell of heroes who attempt to tame tallstriders as mounts or beasts of burden, but these tales are typically humorous ones. If it is possible to domesticate the flightless birds, no one has claimed success at the task.\r\nTallstriders are tenacious pack hunters. A tallstrider’s main mode of attack is with its beak and talons. It will smash its beak down upon a victim with ruthless efficiency. Tallstriders hunt instinctively in packs. Tallstriders attempt to isolate single members of a pack of prey and run them down. When facing stronger prey, they harry a single victim if possible until, after hours of running, the quarry is most likely exhausted and weak. Tallstriders will attack prey - which includes anything larger than a field mouse - on sight, always fighting to the death. They leap at their opponents while slashing with their claws and stabbing with their beak. If hungry, tallstriders will attack until they or their prey are dead. \r\n* The [[gnome]]s modelled their [[Mechanostrider]] [[mount]]s after striders.\r\n* The [[blood elf]] mount is called a [[Hawkstrider]], and looks similar to other striders. The main difference is color and the face. Its running and spacebar animation are also unique, but otherwise it animates very much like an ordinary strider.\r\nIn the 2.1 patch, a new breed of tallstrider named [[Lost Torranche]] became available on an island south of [[Terokkar Forest]] called [[Sorrow Wing Point]]. They are level 70 with a purple and green coloration, and are tamable as [[hunter]] [[pets]], making the first tallstrider pet available above level 20.\r\nThe inspiration for the tallstrider is probably some species of immense prehistoric birds like the moa, for instance, or the terrorbirds from South America.\r\n==Traits==\r\n* Tallstriders are [[skinnable]].\r\n* Tallstriders are [[tamable]] and become the generic \"tallstrider\" after [[taming]].\r\n* Most tallstriders are [[neutral]], but Ornery Striders and [[Mazzranache]] are [[hostile]], as are the Timberstriders of [[Azuremyst Isle]].\r\n* Most tallstriders are dull colored, with three exceptions: [[Mazzranache]] (pink), the [[Lost Torranche]] (purple) and [[Strider Clutchmother]] (teal).\r\n==Notable Talltriders==\r\n* [[Mazzranache]]\r\n* [[Strider Clutchmother]]\r\n==Types of Tallstriders==\r\n* [[Axe Beak]]\r\n* [[Bludgeonbeak]]\r\n* [[Clubnek]]\r\n* [[Geru Strider]]\r\n* [[Adult Plainstrider]]\r\n* [[Elder Plainstrider]]\r\n* [[Fleeting Plainstrider]]\r\n* [[Ornery Plainstrider]]\r\n* [[Plainstrider]] - found in the [[Barrens]] and [[Mulgore]]\r\n* [[Foreststrider]] - found in [[Darkshore]]\r\n* [[Timberstrider]] - found on [[Azuremyst Isle]]\r\n* [[Lost Torranche]] - found in [[Terokkar Forest]]\r\n==As A [[Hunter]] Pet==\r\n* Rarely seen as a Hunter pet due to their scarcity. [[Mazzranache]], due to his comical flamingo-like appearance, is the most popular of them all.",},
			["Tally Zapnabber"] = { content = "'''Tally Zapnabber''' is a level 68 [[quest giver]] located at [[Toshley's Station]] in the [[contested]] territory of [[Blade's Edge Mountains]]. He gives quests to [[Alliance]] players allowing them to test out his [[Zephyrium Capacitorium]]. He has made two clones of himself - [[Rally Zapnabber]], also at Toshley's Station, who he calls his \"twin\", and [[O'Mally Zapnabber]], at [[Evergrove]], who is known as Tally's \"other twin\".\r\nHe starts the following quests:\r\n* Test Flight: The Zephyrium Capacitorium\r\n** Test Flight: The Singing Ridge\r\n** Test Flight: Razaan's Landing\r\n*** Test Flight: Ruuan Weald\r\nSee [[List of Blade's Edge Mountains NPCs]].",},
			["Talnivarr the Sleeper"] = { content = "Talnivarr the Sleeper was a demonic gladiator, along two other demons, [[Sinstralis of the Pain]] and [[Destroyer Zardikar]]. He was accompanied by a group of undead archers. The trio resided in the [[Outland Arena]] waiting for challengers. After the third war the beastmaster [[Rexxar]], [[Cairne Bloodhoof]], [[Rokhan]] and [[Chen Stormstout]] came across a portal to the arena while traveling through [[Dustwallow Marsh]]. They fought '''Talnivarr the Sleeper''' in order to gain access to his library of intelligence tomes.\r\n'''Talnivarr''' is also the name of a World of Warcraft Realm. It is believed to have its name from this dreadlord.\r\n==Statistics in Warcraft III of <font color=blueviolet>'''Talnivarr the Sleeper'''</font> at Level 15==\r\n'''Talnivarr the Sleeper''' is an extremely powerful [[Nathrezim|Dreadlord]]\r\n* 3900 HP <font color=limegreen>(+239% more than a regular dreadlord)</font>\r\n* 1110 MP <font color=limegreen>(+83% more than a regular dreadlord)</font>\r\n* 278-288 hero melee damage <font color=limegreen>(+ 1055% more than a regular dreadlord)</font>\r\n* 12 hero armor <font color=limegreen>(+100% more than a regular dreadlord)</font>\r\n* Attributes\r\n** 76 Strength '''primary attribute''' <font color=limegreen> (+81% more than a regular dreadlord)</font>\r\n** 58 Agility <font color=limegreen>(+132% more than a regular dreadlord)</font>\r\n** 74 Intelligence <font color=limegreen>(+85% more than a regular dreadlord)</font>\r\n* Abilities\r\n** Carrion Swarm (multiple target damage in a line)\r\n** Sleep (puts target to sleep)\r\n** Trueshot Aura (aura that gives ranged units +X damage)\r\n** Rain of Chaos (Summons several infernals from the sky which are different than regular ones)\r\nNote:''Talnivarr the Sleeper is at level 15 whereas all other dreadlords' maximum level is 10.''\r\n==Statistics of Talnivarr the Sleeper's Infernal==\r\n* 2000 HP <font color=limegreen>(+33% more than a regular infernal)</font>\r\n* 45-55 chaos melee damage <font color=orange>(-9% less than a regular infernal)</font>\r\n* 6 heavy armor <font color=slategray>(same as a regular infernal)</font>",},
			["Talonbranch Glade"] = { content = "''For information on grinding Timbermaw reputation, see [[Timbermaw Hold reputation guide]].''\r\n'''Talonbranch Glade''' is a modest [[Alliance]] outpost located in the far northern parts of [[Felwood]]. It is populated by a handful of [[night elves]], and is not a place where players stay longer than needed. Talonbranch Glade is located a bit south of [[Timbermaw Hold]], which leads to [[Moonglade]] and [[Winterspring]]. The glade can be used as base camp while questing and improving your [[reputation]] with the [[Timbermaw Furbolg]] faction that is needed to safely enter their tunnel. \r\nExact coordinates for this town according to the addon coordinate system are (62,24).\r\n===Facilities===\r\n* Level 65 ([[Elite]]) [[Hippogryph]] master.\r\n* Level 60 [[Druid]] trainer.\r\n* Level 57 [[Hunter]] trainer (with level 56 cat)\r\n* Level 40 [[Pet]] trainer.\r\n* A General Goods Vendor and a Weapons Merchant, both level 55.\r\n===Flight===\r\n [[Auberdine]] (s=7 gold c=30 silver )\r\n [[Talrendis Point]] (s=7 gold c=30 silver )\r\n [[Moonglade]] (s=10 gold c=30 silver )\r\n [[Everlook]] (s=10 gold c=30 silver )\r\n [[Emerald Sanctuary]] (s=8 gold c=30 silver )\r\nFlight prices have the usual discounts according to the player's [[reputation]] with the [[Flight Master]] city ([[Darnassus]]).",},
			["Talonbranch Glade"] = { content = "''For information on grinding Timbermaw reputation, see [[Timbermaw Hold reputation guide]].''\r\n'''Talonbranch Glade''' is a modest [[Alliance]] outpost located in the far northern parts of [[Felwood]]. It is populated by a handful of [[night elves]], and is not a place where players stay longer than needed. Talonbranch Glade is located a bit south of [[Timbermaw Hold]], which leads to [[Moonglade]] and [[Winterspring]]. The glade can be used as base camp while questing and improving your [[reputation]] with the [[Timbermaw Furbolg]] faction that is needed to safely enter their tunnel. \r\nExact coordinates for this town according to the addon coordinate system are (62,24).\r\n===Facilities===\r\n* Level 65 ([[Elite]]) [[Hippogryph]] master.\r\n* Level 60 [[Druid]] trainer.\r\n* Level 57 [[Hunter]] trainer (with level 56 cat)\r\n* Level 40 [[Pet]] trainer.\r\n* A General Goods Vendor and a Weapons Merchant, both level 55.\r\n===Flight===\r\n [[Auberdine]] (s=7 gold c=30 silver )\r\n [[Talrendis Point]] (s=7 gold c=30 silver )\r\n [[Moonglade]] (s=10 gold c=30 silver )\r\n [[Everlook]] (s=10 gold c=30 silver )\r\n [[Emerald Sanctuary]] (s=8 gold c=30 silver )\r\nFlight prices have the usual discounts according to the player's [[reputation]] with the [[Flight Master]] city ([[Darnassus]]).",},
			["Talondeep Path"] = { content = "'''The Talondeep Path''' is a winding tunnel that connects [[Ashenvale]] with [[Stonetalon Mountains]]. Although it is riddled with small dead ends and interesting holes in the walls, there are no friendly [[npc]]s nor hostile mobs inside. The entrance on the Ashenvale side is found just west of [[Mystral Lake]], and the entrance on the Stonetalon side is found in the northwestern part of [[Windshear Crag]].",},
			["Taloned Swoop"] = { content = "'''Taloned Swoop''' can be found in [[Mulgore]] .\r\n'''Taloned Swoop''' can be tamed by a [[hunter]]. \r\n==Drops == \r\n \r\n0.56% Chance of an [[Uncommon]] drop.\r\n1.71% Chance of a [[common]] drop.\r\n0.12% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Talonpriest Ishaal"] = { content = "'''Talonpriest Ishaal''' can be found in [[Terokkar Forest]] .\r\nKilling '''Talonpriest Ishaal''' will result in +10 reputation with [[Sha'tari Skyguard]]\r\n==Quests== \r\n==Drops == \r\n \r\n0.03% Chance of an [[epic]] drop.\r\n0.12% Chance of a [[rare]] drop.\r\n1.35% Chance of an [[Uncommon]] drop.\r\n0.32% Chance of a [[common]] drop.\r\n0.85% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Talonpriest Skizzik"] = { content = "'''Talonpriest Skizzik''' can be found in [[Terokkar Forest]] .\r\nKilling '''Talonpriest Skizzik''' will result in +10 reputation with [[Sha'tari Skyguard]]\r\n==Quests== \r\n==Drops == \r\n \r\n0.04% Chance of an [[epic]] drop.\r\n0.08% Chance of a [[rare]] drop.\r\n1.34% Chance of an [[Uncommon]] drop.\r\n0.46% Chance of a [[common]] drop.\r\n1.47% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Talonpriest Zellek"] = { content = "'''Talonpriest Zellek''' can be found in [[Terokkar Forest]].\r\n==Abilities==\r\n \r\n==Quest==\r\n \r\n==Drops==\r\n \r\n0.00% Chance of a [[epic]] drop.\r\n0.04% Chance of a [[rare]] drop.\r\n1.56% Chance of an [[Uncommon]] drop.\r\n0.22% Chance of a [[common]] drop.\r\n0.83% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created.",},
			["Talon Den"] = { content = "A Barrow Den on [[Stonetalon Peak]] inhabited by night elf [[Druid]]s. \r\nIt is similar to an instance for Horde members. It is filled with Dryads, Night Elf Druids, and Keepers of the Grove. However the Alliance cannot kill the mobs in the Talon Den but the Horde can without getting flagged for PvP.\r\nAn elite npc, [[Rynthariel the Keymaster]], guards the entrance within and must be killed to continue inward.\r\n==Quests==\r\nThere are two Horde quests for the Talon Den:\r\n# Horde Presence - [[Kadrak]] ([[The Mor'shan Rampart]], [[Barrens]]), end of a questline\r\n# The Den - [[Braelyn Firehand]] ([[Sunrock Retreat]]), end of a questline",},
			["Talon King Ikiss"] = { content = "'''Talon King Ikiss''' ''(pronounced Eye-kiss)'', the level 69 [[boss]] of [[Sethekk Halls]] in [[Auchindoun]], is one of the leaders of the [[Sethekk]], along with [[Darkweaver Syth]].\r\nTogether, they led the exodus of the Sethekk from [[Skettis]] to the ruins of [[Auchindoun]]. Although a charismatic leader at the beginning, Ikiss has since descended into madness.\r\nHe now openly proclaims that he is [[Terokk]] reborn and expects the [[Arakkoa]] to bow down to him as their ruler.\r\n==Attacks and abilities==\r\n*'''Melee''': ~2k on cloth, 800&ndash;1000 on plate. Heroic: 1.5-1.9k on plate.\r\n* Arcane Volley - hits surrounding targets for around 1500 arcane. This effect has a very long range and ignores LoS.\r\n* Arcane Explosion - Massive and huge AoE (approx 40 yard range) 4.5 to 5k damage. Damage is only dealt to targets that are within line of sight.\r\n* Blink - often to someone (even if they are out of LoS) - right ''before'' he casts Arcane Explosion\r\n* Polymorph - turns someone into a sheep - lasts for 10 seconds, regenerates health but does not break on damage. Dispellable. Can be avoided with reflection.\r\n* Mana Shield - 10,000 points of physical damage hit drain mana instead of health. Dispellable.\r\n'''-Heroic Mode Only:'''\r\n*Slow - Movement speed reduced by 60%. Time between melee and ranged attacks increased by 60%. Casting time increased by 60% for 8 seconds. Magic debuff; Can be dispelled.\r\n==Strategy==\r\nIkiss has low armor and his [[melee]] attacks are fairly weak and can generally be healed through without any difficulty. He has three abilities that make the fight more than a typical [[Boss|Tank and Spank]]:\r\n*First, he casts a '''[[polymorph]]''' with a short duration of about 5 seconds. As a result, a secondary [[healer]] is helpful in the fight, as if the only healer is polymorphed, the fight becomes much more difficult, and an unlucky chain following a polymorph can lead to a [[wipe]]. The polymorph is [[dispel]]lable and has a cast time, but cannot be interrupted. He seems to cast it on the second person on his [[threat list]], and as such anything your party can do to help your healer reduce their [[threat]] generation will help with preventing a wipe.\r\n*Second are his periodic '''Arcane Bolt volleys'''. It hits all characters and has infinite range, but can be resisted. A healer that is on top of the situation can usually make this ability trivial, particularly a [[priest]] that casts [[Prayer of Healing]] immediately after the volley, if possible. Ikiss casts the first volley soon after being aggroed; it is recommended that this initial damage is not healed (except on the tank) until the tank has sufficiently established aggro; even if you have a good tank, it's still helpful to stick with no more than [[HoT]]s on DPS characters until aggro is well-established.\r\n*Last, and most deadly, is his '''blink-and-AoE combo'''. At various times throughout the fight, Ikiss will [[blink]] to a random character and begin casting a powerful, uninterruptible [[AoE]] blast (generally 4000&ndash;5000 damage), accompanied by an [[emote]], that has a range of approximately 30 yards. The damage of this attack can be completely avoided by breaking [[line of sight]], usually done by running around one of the four pillars in the room, and can also be resisted. The AoE has an animation and a fairly long casting time, which is crucial to watch for in order to avoid the damage from the attack - Ikiss's blink can be to a melee class character, and therefore very difficult to notice. Ikiss never casts his AoE without blinking immediately before it. The blink seems to have an threat reduction associated with it and it apparently possible that he may blink multiple times before settling into the AoE cast animation.\r\nIn a typical battle, your tank will run in and aggro Ikiss, pulling him next to a pillar. Ranged DPS and healers should position themselves near other pillars. Ikiss will soon cast his initial Arcane Bolt volley. Once sufficient threat has been established by the tank, DPS can begin. If possible, dispel polymorphs quickly. Watch for his blink and the AoE animation; as soon as this is seen, all characters must quickly run around a pillar near them, to a location where line of sight on Ikiss is broken. After the very noticeable blast, the tank should immediately move to re-establish aggro if another character has gained it. Another volley and polymorph will soon follow. Repeat until Ikiss is dead.\r\nMelee classes seem to be most prone to dying in this strategy, as they usually have the farthest to run when Ikiss begins his AoE; if your party includes several (or is otherwise unable to survive long enough to kill Ikiss using the above strategy) Arcane Resistance gear or Arcane Protection consumables may help.\r\nGenerally, the most difficult part of the Ikiss fight is learning to notice his AoE animation. Once everyone knows what to look for and is able to quickly move to avoid it, the fight becomes trivial. The only difficulty then comes from DPS not waiting until aggro is re-established after the blast, and pulling Ikiss off the tank and dying.\r\nOther effective strategies include using the stairs to the entrance/exit of the instance to break line of sight, having rogues use [[Cloak of Shadows]] to avoid the AoE blast entirely, and having healers equip PvP trinkets to dispel polymorph or using a [[Grounding Totem]] to avoid it. The volley may only be cast when there is at least one person out of melee range of Ikiss; moving everyone close to him may stop him from casting it, but can also make detecting his blink much more difficult. On the other hand, if entire groups knows well how blink/AoE animation sequence looks like or watches his emotes closely, staying together may actually help people to react on his preparations faster, as they won't have to check where exactly Ikiss blinked this time to decide where to run, because when everyone stay together Ikiss would practically blink to same place he was standing before casting his AOE.\r\nPicking one pillar in advance for the whole party to hide behind can be very helpful to the healer. Additionally, using a ping-pong strategy each time Ikiss uses his AOE, will make it easier for the tank to re-establish aggro. After running behind a pillar, simply wait for Ikiss to come to you after his AOE (as opposed to running back out into the middle). This strategy works especially well in Heroic mode, since Ikiss will also cast [[slow]] on the party.\r\n''Paladin Note: If your tank is an Alliance Paladin Tank, using [[Seal of Vengeance]] after getting initial aggro can help getting aggro after the blinks as it does [[DoT]] Holy damage.''\r\n'''At all times it is possible to reset this encounter by having your party members run out of his room to the middle of the chamber before his.''' Arcane Volley can still hit you, but as long as the primary aggro target is out of his room, he will reset.\r\n===Alternate Strategy===\r\nMany groups have trouble getting behind the pillars quickly enough. An easier method for handling the AoE, especially for melee-heavy groups, is to have the tank pull Ikiss to the hallway from which you entered and tank him right outside it, off to one side, in the room before Ikiss's chamber. When he blinks to begin his AoE, the party runs inside the hallway to either side of the doorway, and thus out of line of sight for the AoE. After the cast, Ikiss will run to the tank, and the tank moves him back to one side of the door. (Alternately, the tank can pull him to one side of the hallway, and the party run to either side of the door in the room before Ikiss's chamber. This tactic gives the party a significantly shorter distance to run to get out of Ikiss's range.\r\n''Note: The tank must be careful not to pull Ikiss too far into the other room, or it will reset the encounter.''\r\n===Heroic mode===\r\nTalon King Ikiss is somewhat more difficult now on Heroic Difficulty because he now will sheep the tank at random. When this happens, it is likely to cause a wipe because he will immediately aggro on the healer. Druid tanks are immune to his polymorph, and thus have a large advantage here. Healers could try to survive (paladin bubble, priest fade).\r\nHis damage output is about doubled on plate (1600&ndash;2000 a hit on a decently geared warrior) and all of his abilities have had their damage significantly upped. His arcane volley now hits for between 2000 and 4000 and he uses it fairly often, so it is advisable to bring arcane protection potions and/or two or three pieces of arcane resist gear to counter that. His blink/arcane explosion mechanics are the same - avoidable by line of sight, provided you have no lag problems. He is still very squishy, so concentrated damage can burn him down rather quickly.\r\nAnother problem in the fight is his arcane volley, so the healer has to be prepared to keep everyone close to topped off or they may end up dying from one of those. [[Healthstones]] and potions are invaluable in this fight at keeping people topped off, but the arcane resist makes it easier.\r\nAs of 2.1.0, he randomly casts [[Slow]] on the party, which lasts for around 10 seconds; this can be devastating before the arcane explosion. If a priest is healing, it's possible for the priest to mass dispel the group, so they have just enough time to run around the pillars. This can only be pulled off if the group is in the center, and everyone is paying attention to the Raid Warnings put up.\r\n===Another Technique for Heroic Mode===\r\nOne technique that has been proven to work involves placement of the two carpets in the hall. As you first enter the hall there is a green carpet at your feet. There is another carpet to your left, between the two pillars.\r\nIf the tank can keep Ikiss in the center until the blink, the rest of the party should stay on the carpet. Immediately following the blink, the tank should run directly to the other carpet, and the other four should run around the pillar to that same carpet. Do not heal or cast until the tank picks up aggro again. Repeat this procedure, alternating carpets.\r\n==Tips==\r\n* Bear tanks, which generate all their threat via physical damage, may have some difficulty holding aggro while Ikiss has Mana Shield up. He tends to use it when he is at low health, and it leads to agonizing wipes. Be ready to dispel or steal it.\r\n* On heroic mode, if all else fails, just focus on healing the tank and the healer. It can be hard to heal through the arcane bolt volleys, as they hit everyone. It can be especially difficult for paladins. It is a lot easier when the volley only hits two targets. It takes a long time for the tank to kill Ikiss on his own, but it works eventually.\r\n==Quests==\r\n*Terokk's Legacy\r\n==Quotes==\r\nEntering room\r\n*<squawk> Trinkets yes, pretty trinkets!.. <squawk> Power, great power!.. <squawk> Power in trinkets! <shriek>\r\nAggro\r\n* Mmmm you make war on Ikiss? <shrieking>\r\n* Ikiss cut you pretty <cawing>, slice you yes!\r\nKill\r\n* Mmmmmmmmmm!\r\n* You die! <squeak> Stay away from trinkets!\r\nDeath\r\n* Ikiss will not.. <weak shriek>.. die!",},
			["Talon Stand"] = { content = "'''Talon Stand''' is a hill in the middle of [[Wyrmscar Island]] northeast of [[Bloodmyst Isle]]. It is populated by [[dragon whelp]]s. Here, the undead black dragon [[Razormaw]] can be brought down to earth, where he can be defeated. The path up to his lair, begins at 71,26, which is in the south central section of the island.",},
			["Talo Thornhoof"] = { content = "'''Talo Thornhoof''' is a level 50 [[quest giver]] located at [[Camp Mojache]] in the [[contested]] territory of [[Feralas]]. He may be related to [[Zevrim Thornhoof]].\r\nHe starts the following quests:\r\n* Vengeance on the Northspring\r\n** Dark Heart\r\n* The Strength of Corruption\r\n* Lethtendris's Web (Dungeon)\r\nHe ends the quest [[Quest:Camp Mojache|Camp Mojache]].\r\nSee [[List of Feralas NPCs]].",},
			["Talramas"] = { content = "'''Talramas''' is a crashed [[Scourge]] [[necropolis]] near the [[Temple City of En'kilah]] in the [[Borean Tundra]]. Though the necropolis appears fully destroyed, the cultists inside are hard at work to get it back up in the air.",},
			["Talrendis Point"] = { content = "==Info==\r\n'''Talrendis Point''' is an [[Alliance]] outpost located in southwestern [[Azshara]]. It is populated mostly by [[night elves]], but also famously houses a [[friendly]] [[tauren]], [[Loh'atu]].\r\nLike [[Valormok]], Talrendis Point is a frontier town and offers only the barest of necessities.\r\nDue to its proximity to the bridge between [[Azshara]] and [[Ashenvale]], it is also a good starting place for players who need to quickly reach eastern Ashenvale, though the recent (patch 2.1) addition of a flight master in [[Forest Song]] makes this unneccesary.\r\n===Flight===\r\n [[Auberdine]]\r\n [[Talonbranch Glade]]\r\n [[Astranaar]]\r\n [[Forest Song]]\r\n [[Theramore Isle]]\r\n [[Everlook]]\r\n [[Ratchet]]",},
			["Talvash del Kissel"] = { content = "'''Talvash del Kissel''' is a level 50 quest giver located in [[the Mystic Ward]] in the [[dwarf]] city of [[Ironforge]].\r\nHe was a jeweler in [[Gnomeregan]], but after the city fell and some rumors started about him he fell into debt.\r\nHe is located at coordinates .\r\nHe starts the following quests:\r\n* Gnome Improvement\r\n* Lore for a Price\r\n* Back to Uldaman (Dungeon)\r\n* Replacement Phial\r\n* Incoming Gumdrop (Alliance) ([[Hallow's End]])\r\nSee [[List of Ironforge NPCs]].",},
			["Tamable"] = { content = "#REDIRECT [[Tame Beast]]", redirect = "Tame Beast",},
			["Tame"] = { content = "#redirect [[Tame Beast]]", redirect = "Tame Beast",},
			["Tameable"] = { content = "#REDIRECT [[Tame Beast]]", redirect = "Tame Beast",},
			["Tamed"] = { content = "#REDIRECT [[Tame Beast]]", redirect = "Tame Beast",},
			["Tame Beast"] = { content = "''I'll call him \"Fluffy\".''\r\n'''Tame Beast''' allows the [[Hunter]] to train the beasts of Azeroth and make it their life-long companions. The ability is essential for hunters to learn new abilities for their pets that which cannot be trained from [[pet trainers]].\r\nIt is rewarded from the quest [[Quest:Taming the Beast|Taming the Beast]], depending on race and faction.\r\n==Tips and tactics==\r\nTaming a beast can be made easier with some preparation. Some of the beasts you encounter have special attacks which will cause your attempt to tame them to fail. \r\n* Put down a [[Freezing Trap]] between you and your target. This will add up to 20 seconds of uninterrupted time for taming.\r\n* Activate [[Aspect of the Monkey]] to take fewer hits from the beast while you channel.\r\n* Have a mage friend [[Polymorph|sheep]] the beast and you can then tame it.\r\n* Have a druid friend [[Hibernate]] it. \r\n==Notes==\r\n* You cannot have another pet active if you want to tame a new one. Stable any pet you have active before attempting to tame a new one.\r\n* Interruptions will fail the attempt. This includes stuns, knock downs, and silence, but does not include the daze effect.\r\n* You can only tame beasts your level and lower.\r\n* Some beasts ''cannot'' be tamed. Only certain families of beasts are tamable, and even within those families not every member is tamable. To ensure the beast you want is tamable, you may want to cast [[Beast Lore]] on it for more information.\r\n* Families tamable by all hunter specs are : [[bat]], [[bear]], [[boar]], [[carrion bird]], [[cat]], [[crocolisk]], [[dragonhawk]], [[gorilla]], [[hyena]], [[moth]] (new in WOTLK), [[nether ray]], [[bird of prey]] (new family in WOTLK including the previous [[owl]] family), [[raptor]], [[Ravager_(beast)|ravager]], [[scorpid]], [[serpent]], [[spider]], [[spore bat]], [[tallstrider]], [[turtle]], [[warp stalker]], [[wasp]] (new in WOTLK), [[wind serpent]], and [[wolf]].\r\n* As of [[Patch 3.0.2]], [[Hunter_talents|Beast Mastery]] specced Hunters are able to tame additional 'exotic' pet families if they have learned the 51-point [[Beast Mastery]] talent. The exotic families added with this patch were [[chimaera]], [[core hound]], [[devilsaur]], [[silithid]] and [[worm]]. In [[Wrath of the Lich King]], at least two new 'exotic' pet families will be added : [[rhino]] and [[spirit beast]].\r\n==See also==\r\n* [[Taming a bat in Zul'Gurub without a raid group]]\r\n* [[:Category:Tamable beasts|List of all tamable beasts]]",},
			["Tame Kaliri"] = { content = "'''Tame Kaliri''' can be found in [[Skettis]].",},
			["Taming"] = { content = "#REDIRECT [[Tame Beast]]", redirect = "Tame Beast",},
			["Taming the Beast"] = { content = "Both the [[Alliance]] and the [[Horde]] have different three-quest chains with each named '''Taming the Beast'''. When a new [[Hunter]] is trying to acquire a [[pet]], they must complete the chain for their faction.\r\nAlliance:\r\n*Taming the Beast (Draenei 1)\r\n*Taming the Beast (Draenei 2)\r\n*Taming the Beast (Draenei 3)\r\n*Taming the Beast (Dwarf 1)\r\n*Taming the Beast (Dwarf 2)\r\n*Taming the Beast (Dwarf 3)\r\n*Taming the Beast (Night Elf 1)\r\n*Taming the Beast (Night Elf 2)\r\n*Taming the Beast (Night Elf 3)\r\nHorde:\r\n*Taming the Beast (Blood Elf 1)\r\n*Taming the Beast (Blood Elf 2)\r\n*Taming the Beast (Blood Elf 3)\r\n*Taming the Beast (Orc and Troll 1)\r\n*Taming the Beast (Orc and Troll 2)\r\n*Taming the Beast (Orc and Troll 3)\r\n*Taming the Beast (Tauren 1)\r\n*Taming the Beast (Tauren 2)\r\n*Taming the Beast (Tauren 3)",},
			["Tammis Foxton"] = { content = "'''Tammis Foxton''' was [[Aedelas Blackmoore]]'s personal servant. He was with Aedalas when they both discovered [[Thrall]], and was promoted when he forced his wife [[Clannia Foxton|Clannia]] to become the little baby [[orc]]'s wet nurse. He is also [[Taretha Foxton|Taretha]] and [[Faralyn Foxton|Faralyn]]'s father.",},
			["Tanaris"] = { content = "'''Tanaris''', or the '''Tanaris Desert''', (pronounced Tuh-NAYR-ihs or Tuh-NUHR-ihs) is a desert located in [[Southern Kalimdor]], east of [[Un'Goro Crater]] and south of [[Thousand Needles]]. It is an arid land, covered in sand dunes and frequently exposed to dangerous sandstorms. The [[Steamwheedle Cartel]] goblins have established [[Steamwheedle Port]] and [[Gadgetzan]] as their main centers of operation. The dock in Steamwheedle Port was presumably used for transport to the outer islands of the [[Undermine]], the goblin capital, but it was destroyed in the [[Cataclysm (event)|Cataclysm]], which also brought the ocean to Gadgetzan, where the goblins built a new dock for their shipping needs.\r\n==History==\r\nTanaris used to be a jungle and territory of the [[Gurubashi Empire]]. When the [[Great Sundering]] shattered the ancient [[Kalimdor (landmass)|landmass]], the area swiftly became the desert of Tanaris. The [[Farraki tribe]] of trolls were stranded here and eventually adapted to their harsh new environment, becoming [[sand troll]]s.\r\nTanaris is the ancestral home of the [[bronze dragonflight]] based out of the [[Caverns of Time]]. The [[titan]]s also have a holding here in the form of an entrance to the ancient land of [[Uldum]], found in the southern parts of the desert. It was here that [[Anachronos]] first discovered the full threat of the [[silithid]], who had been making hives in the remote regions of Tanaris. The [[War of the Shifting Sands]] was consequently unleashed upon the western land of [[Silithus]].\r\nDuring the [[Ahn'Qiraj War]], the area was invaded by the armies of [[C'Thun]].\r\nApproximately four years after the end of the [[Second War]], Cho'gall and his Twilight's Hammer clan followers arrived to Tanaris and entered its cave complex where they made a base. Not soon after, several of the members went missing or were found dead, killed by [[Garona Halforcen]]. The cultists thus left the cave complex. In the same year, the [[human]] brothers [[Greydon Thorne]] and [[Silverlaine Thorne|Silverlaine]] visited [[Gadgetzan]].\r\nThe area was [[Scourge Invasion|invaded]] twice by the [[Scourge]] in the years leading to the [[war against the Lich King]].\r\nWith the [[Cataclysm (event)|Cataclysm]], [[Steamwheedle Port]] and many parts of Tanaris were flooded, making Gadgetzan a port. Some Tanaris goblins wisely invested in desert real estate and reaped the benefits when it became beach-front property.\r\nAt some point, [[Grizzek Fizzwrench]] claimed a deserted beach in Tanaris where he constructed a small domicile and laboratory. Over the next years, he built a defense system using various robots and devices.\r\nThe [[Burning Legion]] targeted Tanaris as one of their [[Legion Invasions|invasion points]]. It was successfully defended by the [[Alliance]], [[Horde]], and [[Illidari]].\r\nAfter the [[Fourth War]], Tanaris was visited by [[Rexxar]] and [[Zekhan]]. Settlements and various areas of the desert remain mostly the same; the crushed [[Steamwheedle Port]] is now being used by the [[Southsea Freebooters]], and the Gaping Chasm remains one of the most active hives of the silithid. Now, Tanaris boasts with [[camel]]s. The traveling duo also found [[Dormus the Camel-Hoarder]] who had come to Tanaris to fill his personal stable of camels.\r\n==Getting there==\r\nWhile questing through [[Thousand Needles]] players will be sent from the [[Fizzle and Pozzik's Speedbarge]] south through the [[Shimmering Deep]] and through the mountain pass to the south. [[Gadgetzan]] will be soon after entering.\r\nThere are also portals in Dalaran ([[The Violet Citadel]]) and Shattrath ([[World's End Tavern]], by talking to [[Zephyr]] - requires with [[Keepers of Time]]) which take you to the entry of the Caverns of Time.\r\n==Geography==\r\nTanaris covers a vast expanse of [[Southern Kalimdor]], just south of [[Thousand Needles]]. It is a blazing hot expanse of rolling sand dunes under a cloudless sky. The southern region is more mountainous, with large cavern networks, with some extending deep beneath the surface. A vast realm, Tanaris holds many secrets. The land is mostly desert, and below ground are gigantic tunnel networks. They remain largely unexplored, for few have the fortitude to venture into such a harsh landscape. Still, rumors tell of all manner of creatures that hide within the tunnels and slaughter trespassers without hesitation. Although the sea of dunes does not look as if it would support a variety of wildlife, [[human]]s, [[Sandfury troll]]s, [[hyena]]s, [[scorpid]]s, [[basilisk]]s, and [[silithid]] bugs are quite common. Occasionally, [[drake]]s are also seen soaring on the thermals that swirl over the great desert.\r\nTanaris contains quite a few instances, including all the [[Caverns of Time]] instances, as well as [[Zul'Farrak]]. \r\n===Travel hubs===\r\n* [[Gadgetzan]]\r\n* [[Bootlegger Outpost]]\r\n* [[Gunstan's Dig]]\r\n* [[Dawnrise Expedition]]\r\n==Notable characters==\r\nTanaris is home to several characters of note such as [[Narain Soothfancy]] and [[Marin Noggenfogger]].\r\n==Quests==\r\n''For pre-cataclysm story line see [[Tanaris quests]].''\r\n==Resources==\r\n*[[Herb]]s\r\n**[[Firebloom]]\r\n**[[Sungrass]]\r\n*[[Leather]]\r\n**[[Heavy Leather]]\r\n**[[Thick Leather]]\r\n**[[Rugged Leather]]\r\n**[[Turtle Scale]] (Skinning level 38-53 [[turtle]]s)\r\n**[[Scorpid Scale]] (Skinning level 40-50 [[scorpid]]s)\r\n*[[Ore]]\r\n**[[Gold Vein]]\r\n**[[Mithril Deposit]]\r\n**[[Truesilver Deposit]]\r\n==Wild creatures==\r\n*[[Air elemental]]s\r\n*[[Basilisk]]s\r\n*[[Bronze dragon]]s\r\n*[[Camel]]s (lorewise)\r\n*[[Crab]]s\r\n*[[Earth elemental]]s\r\n*[[Hyena]]s\r\n*[[Lasher]]s\r\n*[[Sand worm]]s\r\n*[[Serpent]]s\r\n*[[Scorpid]]s\r\n*[[Silithid]]\r\n*[[Skeletal wind serpent]]s\r\n*[[Snake]]s\r\n*[[Stone golem]]s\r\n*[[Turtle]]s\r\n*[[Roc]]s\r\n===History===\r\nIt is said that Tanaris once housed a Titan city, a place known as Uldum. The city seems to be lost as no one has been able to find it. Perhaps the sands cover it, or maybe Uldum is just another name for the Caverns of Time.\r\nTanaris was also once part of the Gurubashi Empire, a troll nation that existed long before the Sundering and once covered a great part of the world. The Sundering smashed this empire, separating the trolls into tiny fragments of their former greatness. Zul'Farrak may not be a ruin of the Gurubashi, as it is too recent, although it may have been built atop such a ruin.\r\nLittle is known about the Caverns of Time. It seems it has always been there, a permanent landmark — surviving even changes as violent as the Sundering. Perhaps it exists outside of time itself, as a sage suggests.\r\nTanaris has been an endless sea of sand for aeons. [[Nozdormu]], the great dragon of time, was said to make this land his home since time immemorial, thriving in the solitude of oppressive heat and miles of sand.\r\nExplorers that venture into the desert are warned that it has little to no cover at all. If the bandits see you, and is highly probable they will even from a distance, they will be waiting over in the next sand dune. As there are almost never any clouds at night, the moonlight makes you stand out so moving only at night is as dangerous as in the day. The worst creatures come out at night, too, like scorpids and silithid. Moreover, it gets downright cold at night.\r\n===People and culture===\r\nThe two towns of Tanaris, Gadgetzan and Steamwheedle Port, were built and are manned mostly by goblins, with some gnomes helping out here and there. Almost all of them work for the Gadgetzan Waterworks Company. Outside the cities, the need for water is still key, but the means to get it differ. The Wastewander Bandits steal it, while the Dunemaul ogres and Sandfury trolls control the only natural wells in the region. The Southsea Pirates get theirs by raiding, or simply sailing further up the coast to resupply.\r\nAbout twice a year rain falls on Tanaris. When this happens, it's not just a drizzle, but an intense downpour that lasts for hours. The few scraggly plants that survive in the desert do so chiefly because of this tiny bit of moisture, but for the residents of Gadgetzan, it's a cause for celebration.\r\n===Geography===\r\nLike Thousand Needles, Tanaris is a desert; but unlike the barren rocks to the northwest, this desert is made up of sand dunes. From a distance it resembles an ocean, except the waves are brown and don't move. When the wind kicks up, though, intense storms result, causing the dunes to change position and shape. If you visit Tanaris one month, you might come back the next and find that everything has moved around.\r\nGadgetzan and Steamwheedle Port, as well as the troll city of Zul'Farrak, are located up near the edge of the northern mountains. Because the winds blow out in the plains, theses settlements are usually spared the shifting sands treatment. Still, everywhere you go there's going to be sand. Although there isn't a lot of life in the desert, what you find there is hardy as it is their only way to survive. You can find scorpids, buzzards, elementals and hyenas, all of which are masters at finding water. If they couldn't get it from a well, they would simply catch and kill something for its blood.\r\nThe northern edge of Tanaris is blocked by steep hills, running all the way to the edge of Un'Goro Crater to the west and the ocean to the east. A few scattered hills and mountains litter the landscape, but mostly it's just open dunes everywhere you look. In the southwest, near the Thistleshrub Valley, there is a sloping path into Un'Goro.\r\n==Notes and trivia==\r\n*According to the [[Gordunni]] [[ogre]]s, Tanaris is covered in [[Dunemaul clan|Dunemaul]] ogre poo.\r\n* describes a cave complex beneath Tanaris. Previously, [[Gadgetzan|Gadgetzan Gazette]] from [[Hearthstone (game)|Hearthstone canon]] mentioned underground ruins upon which a Gadgetzan manor was built and which predate the city of Gadgetzan.\r\n*Before [[patch 4.0.1]], [[Alliance]] players didn't have any travel hubs in [[Thousand Needles]], so [[Gadgetzan]] made a great alternative to get to [[Shimmering Flats]] since it was just a short run over the hill to get there. Even [[Horde]] players could benefit from this shortcut as it was even faster than running from [[Freewind Post]].\r\n*There is an alternative route to get to Tanaris that is much quicker for players in Dustwallow Marsh. By traveling to the Theramore Docks, on the eastern coast of Dustwallow, and swimming south around the mountains that surround the Shimmering Flats, you can easily get to Steamweedle Port, so long as you hug the shoreline; failure to do so will result in death by fatigue. This is made much easier using a Swim Speed Potion, a druid's Aquatic Form, a shaman's Water Walking or a similar ability.\r\n*Currently, Tanaris has the largest amount of dungeons in the game.\r\n*One of the names for [[oil]] is \"Tanaris Tea\".",},
			["Tanaris Desert"] = { content = "#REDIRECT [[Tanaris]]", redirect = "Tanaris",},
			["Tanaris quests"] = { content = "=== [[Alliance]]===\r\n==== To Other Zones====\r\n* Handle With Care - To [[Rut'theran Village]]\r\n==== From Other Zones====\r\n* Errand for Apothecary Zinge (1) - In [[Undercity]]\r\n** Errand for Apothecary Zinge (2)\r\n** Into the Field\r\n** Slake That Thirst\r\n=== [[Neutral]]===\r\n*The [[Rise of the Silithid quest chain]], starting with Gadgetzan Water Survey, leading eventually to [[Un'goro Crater]].\r\n*Nice Hat... (Old Hillsbrad, Normal or Heroic).\r\n==== In Zone====\r\n* Wastewander Justice\r\n** More Wastewander Justice\r\n* Water Pouch Bounty (Repeatable)\r\n* Clamlette Surprise - Artisan [[Cooking]]\r\n* Pirate Hats Ahoy!\r\n* Ship Schedules - Quest item from [[Pirate Footlocker]]\r\n* Southsea Shakedown\r\n* WANTED: Andre Firebeard\r\n* WANTED: Caliph Scorpidsting\r\n* Gadgetzan Water Survey\r\n** Noxious Lair Investigation\r\n* Find OOX-17/TN! - From random zonewide drop, [[OOX-17/TN Distress Beacon]]\r\n** Rescue OOX-17/TN!\r\n* Gahz'ridian\r\n* The Thirsty Goblin\r\n** In Good Taste\r\n** Sprinkle's Secret Ingredient - To [[The Hinterlands]]\r\n** Delivery for Marin\r\n** Noggenfogger Elixir\r\n* The Dunemaul Compound\r\n* Thistleshrub Valley\r\n* Tooga's Quest\r\n==== From Other Zones====\r\n* Stoley's Debt - From [[Booty Bay]] in [[Stranglethorn Vale]]\r\n** Stoley's Shipment - Retrieve Stoley's Shipment from the pirates in [[Lost Rigger Cove]]\r\n** Deliver to MacKinley - Return to [[Booty Bay]]\r\n==== To Other Zones====\r\n* Screecher Spirits - To [[Feralas]]\r\n** The Prophecy of Mosh'aru - To [[Zul'Farrak]]\r\n** The Ancient Egg - To [[The Hinterlands]]\r\n** The God Hakkar - To [[Sunken Temple]]\r\n** The Lost Tablets of Mosh'aru - To [[Eastern Plaguelands]]\r\n** The Final Tablets - To [[Blackrock Spire]]\r\n*** Confront Yeh'kinya\r\n*** The Hand of Rastakhan - Travel to [[Yojamba Isle]] in [[Stranglethorn Vale]]\r\n* Troll Temper - To [[Zul'Farrak]]\r\n* Scarab Shells - To [[Zul'Farrak]]\r\n* Divino-matic Rod - To [[Zul'Farrak]]\r\n* The Sunken Temple (Alliance) - The Sunken Temple (Horde) - From [[Feralas]]\r\n** The Stone Circle - To [[Ratchet]] in the [[Barrens]]\r\n** Into the Depths - To [[Sunken Temple]]\r\n** Secret of the Circle - To [[Sunken Temple]]\r\n* Yuka Screwspigot - To [[Blackrock Depths]]\r\n* Super Sticky - To [[Un'Goro Crater]]\r\n* Never Ask Me About My Business\r\n** The Isle of Dread! - To [[Feralas]]\r\n** Dirge's Kickin' Chimaerok Chops\r\n** Return to Narain",},
			["Tandred Proudmoore"] = { content = "'''Tandred Proudmoore''' is the son of the deceased Grand Admiral [[Daelin Proudmoore]] and brother of [[Alliance]] revolutionary and [[Theramore Isle]] sovereign [[Jaina Proudmoore]]. Following his father's demise he took the position of Lord Admiral of the [[Kul Tiras]] naval forces. He’s a good person, but he doesn’t have his father's courage. He is not the man his father was. He gets a lot of help from his lady friend, Captain [[Mishan Waycrest]]. Tandred does the best he can with the few men and fewer allies he has left.",},
			["Taneel Darkwood"] = { content = "'''Taneel Darkwood''' is a level 32 [[night elf]] [[ghost]] found in the [[Dor'Danil Barrow Den]] in [[Ashenvale]].\r\n[[Kayneth Stillwind]] would like Taneel put to rest.\r\n==Quests==\r\n*Insane Druids",},
			["Tangled Horror"] = { content = "'''Tangled Horror''' can be found in [[Swamp of Sorrows]] .\r\n==Drops == \r\n \r\n0.01% Chance of an [[epic]] drop.\r\n0.03% Chance of a [[rare]] drop.\r\n0.83% Chance of an [[Uncommon]] drop.\r\n0.19% Chance of a [[common]] drop.\r\n0.59% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Tangy Clam Meat"] = { content = "==Source==\r\n==Tangy Clam Meat as an ingredient==\r\nThis item is used to make: \r\n* Goblin Deviled Clams\r\nIt can be found inside [[Thick-shelled Clam]].",},
			["Tank"] = { content = "A '''tank''' is a character whose primary role is to absorb damage and prevent others from being attacked. Tanks are \"meatshields\", so to speak, putting themselves between the [[mob]]s and the more vulnerable party members. The tank assumes the [[aggro]] of the mobs and tries to keep them off other group mates. With everyone nuking the same target (directed by the [[main assist]]), the mobs go down faster and there is less damage done to the group.\r\nBecause of the constant abuse upon their armor and weapons, high repair costs are a fixture in a tank's life. An often-used abbreviation for tank is \"MT\" ([[main tank]]). The tank's role must not be confused with the MA ([[Main Assist]]). Also used to contrast from a [[damage dealer]] or a [[healer]].\r\nIn a classic [[tank and spank|tank-and-spank]] fight, the tank should be the only one taking damage, and therefore be the only one who needs healing. Even in more complex fights, the healer should be able to concentrate most of their healing on the tank with healing on the rest of the group being significantly lighter most of the time.\r\nIf the healer is healing everyone in the group, then either the tank is not generating enough threat or the other members in the group are generating too much threat by dealing too much DPS and pulling aggro off the tank. This has to be watched or the group will likely wipe.\r\n==Primary Tank Classes==\r\nThere are three combinations of class and spec which can truly be considered [[main tank]]s: Protection Warrior, Feral Druid, and Protection Paladin. Many other combinations of spec and class may substitute as tank in certain situations, but will never enable a group to perform at the limit of its ability. See \"Secondary Tank Classes\" below.\r\nThe following criteria define a tank's performance:\r\n#Health and Armor\r\n#Damage Mitigation\r\n#Threat Generation\r\nEach has its strengths and weaknesses; and, in end-game raids, each of the three types will find easy and difficult bosses. Generally Protection Warriors are considered the best single-target tanks, while Protection Paladins are easily the best mass-aggro AOE tanks. Feral Druids are best in situations where high amounts of melee damage are incoming. ''See also: [[Comparison of tank classes]].''\r\nNote that on certain Raid-level encounters, unusual classes may be required to tank (for example at [[High King Maulgar]] a [[Mage]] has to serve as tank on one of the adds).\r\n===Protection Warrior===\r\nProtection-specced [[Warriors]] with appropriate gear are the best boss-encounter tanks in the game. They have the best damage mitigation vs. single targets, and the largest and most versatile array of tools for tanking, which include: threat-generating tools such as Revenge, Shield Slam, and multiple taunts; many mitigation abilities; and finally a few panic buttons like [[Shield Wall]] and [[Last Stand]]. The only problem area for warrior tanks is aggro generation, particularly initially. In long fights, all three main tank types actually create comparable amounts of aggro. Finally, Warriors depend more on their gear than any other class (this can also be a boon, because a warrior can increase his abilities further than the other classes with better gear).\r\n===Feral Druid===\r\nFeral [[Druid]] tanks feature the highest armor and hit-point values of any class in the game. Besides the basic allotment of tanking skills (taunt, high-aggro moves, etc.), feral tanks are immune to [[Polymorph]] (shapeshifting makes a druid immune to polymorph) and [[Mind Control]] because they are considered beasts (not humanoid) while tanking in bear form. This makes them the tanks of choice for encounters like [[Jin'do the Hexxer|Jin'do]].\r\nFeral Druids also have the advantage that they can switch from tanking to damage dealing without changing their build. This makes them the best off-tanks in raid, as they can switch to Cat form after their tanking targets are dead and help DPS the main tanks' targets.\r\n===Protection Paladin===\r\n[[Paladins]] are tanks that use mana and build threat with spell damage. They can wear plate armor. They excel in pulls with many [[mob]]s, with abilities such as [[Consecration]], [[Holy Shield]], [[Retribution Aura]], [[Blessing of Sanctuary]] and [[Avenger's Shield]], enabling them to keep many mobs on themselves with far less trouble than a [[Warrior]] or [[Druid]]. Their 8-charges [[Holy Shield]] also gives them advantage against fast-attacking bosses over [[Warriors]]. Paladins are more difficult to gear than Druids and Warriors in the beginning, as Paladins need to ensure they are uncrushable with only 30% block from [[Holy Shield]], while warriors have 75% block from [[Shield Block]], and Druids are always crushable anyway. Another drawback is a large proportion of their threat generation is reactive ([[Holy Shield]], [[Retribution Aura]], [[Blessing of Sanctuary]]), making them poor secondary aggro tanks or tanks for casters. They are also vulnerable to mana-burn abilities and rely on magic-based threat, making it difficult to gain aggro on mobs that Silence.\r\n==Secondary Tank Classes==\r\nSeveral other classes have limited tanking abilities, mostly in the 5-man instances below the level cap. All other combinations of class and build except the three main tank types fall under this category. There are exceptions; Shamans and Moonkins have both tanked raid bosses and some heroic instances , and pets and minions have tanked pre-BC raid bosses. Secondary tank classes generally require specialized gear and/or [[Talent build|builds]] to tank effectively. \r\n===Shaman===\r\nThe [[Shaman]] is probably the best tank-replacement class. Wearing mail armor and being able to use a shield, they have access to the second-best type of gear. They have no problems at all with one half of tanking - aggro generation. Beyond the threat generated by melee attacks, Shamans can cast [[Frost Shock]] which creates extra threat, use self-heals to add healing aggro, and finally use [[Chain Lightning]] for AoE situations.\r\nHowever, the other half of a tanks job is damage mitigation, and in that department Shamans are severely lacking. They lack the good damage reduction abilities/talents of the other primary tanks, and their gear has no avoidance/mitigation stats. In comparison to the other main-tanking Classes in the table above, Shamans would be rated as follows:\r\nHP/Armor [70] Avoidance [80] Aggro [110]\r\nIf acting as healer or ranged damage dealer, a Shaman is in a good position to pull aggro from cloth wearers in an emergency. Even with caster gear, Shamans are not quite as \"squishy\" as most other caster classes (Shamans usually survive two or three hits when cloth wearers are one-hit kills), but they should still avoid melee combat as much as possible.\r\n===Moonkin Druid===\r\nWith [[Moonkin form]] granting an additional 400% armor, and significant threat through DPS, [[Balance]] Druids have recently gotten attention as alternative tanks. While they lack a taunt in Moonkin form and must temporarily lower their threat/DPS rate in long fights to regain mana, Moonkin Druids have successfully main-tanked heroic instances and some raid content.\r\n===Minions as Tanks===\r\nSome pets can actually serve as tanks. In the early game (prior to level ), pets can even sometimes replace a full tank. In such a situation, the healers should always remember to heal and buff the pet.\r\nPets usually can tank a single mob adequately. Theoretically it is possible to have several mobs on one pet by switching targets, but in practice the threat generation of pets will not be high enough to keep aggro off the healer for an extended period of time.\r\n====Hunter Pets====\r\n[[Hunter]]s can have an assortment of [[beast]]s as [[pet]]s, and some of them can actually serve as tanks quite well. All pets have a [[taunt]]-like ability [[Pet_Abilities|growl]], and hold aggro reasonably well.\r\nPets can also use the [[Cower (pet)|cower]] ability, which reduces threat, to shed aggro if needed; this sometimes makes life easier for [[Warrior]]s. A hunter can have a pet growl to draw aggro when the main tank is in trouble, then cower to let the MT return to duty after recovering.\r\nThe most popular pets for Tanking duties are [[Bear]]s, [[Boar]]s, and [[Turtle]]s. Boars and Turtles are the best tanking pets because of their superior damage mitigation and because of their special species-only abilities such as [[Charge]] (boars) and [[Shell Shield]] (turtles.) Bears also make good all around tanks because of their high health / medium armor but do not currently have any bear-specific abilities. [[Boar]]s are also popular due to the fact that they will eat almost any type of food.\r\nPets that can use [[Screech]]: [[Bat]]s, [[Carrion Bird]]s, and [[Owl]]s, can function as makeshift tanks due to the substantial AoE threat it generates, but this is not very effective and should be used only in low-risk situations; they require significant amounts of healing to do so.\r\n====Warlock Minions====\r\nThe [[Voidwalker (Warlock pet)|Voidwalker]] minion is designed as a tanking pet. Although the Voidwalker lacks a true Taunting ability, it does have two abilities which generate rather high amounts of threat: single-target, fast cool-down [[Torment]]; and [[Suffering]], which generates threat against all enemy targets within 10 yards, but has a relatively long cool-down and can be resisted.\r\n===Hunter===\r\nEven though Hunters can wear the same armor types as Shamans, they cannot use a shield and thus their damage mitigation is even worse. In a group, Hunters should only draw aggro when they are kiting, or as an emergency measure to ensure the survival of a healer. Similar to Shamans, Hunters have many abilities which help them create and hold aggro ([[Distracting Shot]] is a shot with very high threat,and [[Aimed Shot]] creates high threat by damage).\r\nDeterrence can be used to boost damage mitigation by 25%, however this ability only lasts for 10 seconds. With sufficient Agility, Aspect of the Monkey, and 5/5 Deflection, (which boosts parry chance) during Deterrence a Survival Hunter's overall damage mitigation can approach 100%. Survival Hunters with Readiness can also use Deterrence twice in rapid succession, effectively allowing for 20 seconds of Deterrence.\r\nIt should be emphasized that although emergency flash-tanking for wipe prevention can be a key element of the Survival role, such tanking can only be viably performed on an ''extremely'' temporary basis. Survivalist melee should be employed as part of a hybrid strategy which incorporates at least equal, and probably preferably greater, amounts of ranged combat. Attempting to rely primarily or exclusively on melee for extended periods can result in a dead Hunter.\r\n===Rogue===\r\nRogues can temporarily increase their damage mitigation greatly and survive tanking through abilities such as [[Evasion]] and [[Cheat Death]]. These have a short duration, however, and Rogue tanking should be very temporary. Rogues have no threat generation abilities, meaning aggro must be achieved through superior DPS. \r\nRogue tanking is very important in the first phase of the [[Reliquary of Souls]] encounter in the [[Black Temple]], due to the high dodge chance it can achieve with [[Evasion]].\r\nInteresting fact: it is possible to accumulate enough agility as a Rogue to become unhittable, but this can only be achieved with the help of a balance Druid who casts [[Insect Swarm]] and a Hunter who uses [[Scorpid Sting]] and is only possible to [[Night Elves]] because of their racial trait [[Quickness]]. Such combination allows a rogue to tank certain bosses (including raid bosses) who mainly deal melee damage. However, his threat generation will be much lower than that of a regular tank (as he is not specced and geared for DPS), and with the low health he has no hope to survive bosses that do significant spell damage. Therefore, it is generally not something worth trying except for the amusement.\r\nFor more information on rogue tanking, see \r\n==Learning to Tank==\r\nLearning to tank is an interesting challenge, particularly for Warriors and Paladins, because the excellent damage output abilities they've used for 70 levels of solo/small group play are so poor at generating [[threat]]. The WoWWiki article on [[threat]] has some basic numbers that can clue you in on which abilities to use to pump out the threat you need to hold [[aggro]]. That [[aggro]] article also has good information regarding how mob targeting works, and is a valuable resource for understanding how NPCs decide who to beat up.\r\nAs with most skills, there's no substitute for experience. However, it has been suggested that drilling yourself in solo PvE play could help you develop skills that will be useful in tanking in instances.\r\nWhile it might be true that you won't level as quickly as with other builds, if tanking is something you really want to do, you can start speccing Protection right from level 10, and leveling primarily within instances. The low-level instances are more of a challenge for a tank than most people think, and your primary challenge will actually be in learning to deal with other inexperienced players who tend to just want to DPS anything that moves, rather than actually help you.\r\n* For Warriors:\r\n*# Practice staying in Defensive Stance and using [[Shield Block]] and [[Revenge]] as much as possible.\r\n*# For low-level Warriors, practice throwing Sunders on each of 2, 3, or 4 targets in turn (be careful not to over-pull and kill yourself!) - at higher levels, substitute Shield Slam, Revenge, and/or Devastate for Sunder.\r\n*# Practice switching stances regularly to improve your reflex response to a need for an ability in another stance (e.g. [[Intercept]] or [[Berserker Rage]]).\r\n*# Practice keeping your global cool-down ticking.\r\n* For Druids:\r\n*# Practice Lacerating alternating targets with 2, 3, or 4 targets. (Be careful not to over-pull and kill yourself!)\r\n*# Practice keeping your global cool-down ticking. [[Mangle]] at every cool-down, [[Lacerate]] when you can't Mangle, Faerie Fire Feral when you can't Lacerate.\r\n*# Practice using [[Swipe]] without breaking CC. (You can [[Hibernate]] a beast yourself.)\r\n* For Paladins:\r\n*# Make sure you pull the mob/group; most of your threat is from blocking ([[Holy Shield]] and [[Blessing of Sanctuary]]).\r\n*# Make sure you have [[Righteous Fury]] up at all times!\r\n*# To tank multiple targets, use [[Consecration]].\r\n*# Use line of sight to pull casters\r\n*# Mobs don't attack you while bubbled; you can use a macro for bubble/unbubble to get rid of fear or other forms of crowd control.\r\nAlso, visit the [[Warriors as Tanks]], [[Druids as Tanks]], and [[Paladins as Tanks]] articles for additional detail for each of these classes.\r\n_____________________________________________________________________________________________________________________________________________________________________________________________________________________________________________\r\n\"\r\n==See also==\r\n*[[Attack Table]]\r\n*[[Combat rating system]]\r\n*[[Threat]]",},
			["Tanking"] = { content = "#REDIRECT [[Tank]]", redirect = "Tank",},
			["Tank and spank"] = { content = "'''Tank and Spank''' is the most common type of [[PvE]] fight. [[Tank]] holds [[aggro]], [[DPS]] nuke the mob(s), healers keep the tank alive. The only common complication in fights of this type is [[aggro]] - damage dealers must be careful not to generate more [[threat]] than the tank.\r\nThe expression is sometimes used derogatory, meaning that a [[boss]] is very easy to beat (or needs minimial tactics to beat). If such a boss is still tough (because he deals large amounts of damage), it's called a [[Gear Check]].\r\nExample: [[Attumen the Huntsman]]",},
			["Tanner Camp"] = { content = "A small encampment where [[Sarah Tanner]], the Master Elemental [[Leatherworker]] for the [[Alliance]] lives. In back of her tent is a long, sprawling passageway that leads to the Thunder Lizard, [[Margol the Rager]].",},
			["Tap"] = { content = "'''Tapped''' is a state that occurs when a player attacks a certain mob, leaving others unable to loot or get xp for this mob.\r\nThis is indicated with the health bar turning grey.\r\nDoes not apply to party members.\r\nOnly attacks and direct damage abilities are able to tap a mob; Damage over Time abilities and non-damaging debuffs will not prevent another player from tapping a mob.",},
			["Tapoke \"Slim\" Jahn"] = { content = "'''Tapoke \"Slim\" Jahn''' is a level 34 [[quest giver]] located in [[Deepwater Tavern]] in [[Menethil Harbor]], in the [[Alliance]]-aligned zone of [[Wetlands]].\r\nHe starts the quest The Missing Diplomat.\r\nSee [[List of Wetlands NPCs]].\r\n*Note that he must be fought for a quest, and the quest is receivable at a much lower level than 34, so if you walk out of the Deepwater and suddenly get invited to a group, just join, wait a few seconds, kill Slim, and say you're welcome.\r\n==World of Warcraft: The Comic==\r\nSlim makes a brief appearance in [[World of Warcraft: The Comic]]. He recognizes Varian Wrynn upon his return to Menethil.",},
			["Tapper Swindlekeg"] = { content = "'''Tapper Swindlekeg''' is in charge of the [[brewfest]] event outside of [[Orgrimmar]]. He'll explain anything you need to know about the event.\r\n==Quests==\r\n* Brewfest! (Horde) \r\n* The Best of Brews (Horde)",},
			["Taproom"] = { content = "#REDIRECT [[Inn]]", redirect = "Inn",},
			["Taragaman"] = { content = "#redirect [[Taragaman the Hungerer]]", redirect = "Taragaman the Hungerer",},
			["Taragaman the Hungerer"] = { content = "'''Taragaman the Hungerer''' is a level 16 [[elite]] [[humanoid]] [[felguard]] found in [[Ragefire Chasm]]. Despite being a felguard, he is classified as a humanoid, instead of a [[demon]] like most felguards. Thus, all spells that affect humanoids work on him, including [[Mind Control]].\r\n==General==\r\nThought to be the leader of the [[Searing Blade]], he hides within the fiery depths of Ragefire Chasm, using his demonic influence to corrupt the citizens of [[Orgrimmar]]. In reality, the leaders of the Searing Blade are [[Bazzalan]] and [[Jergosh]], this felguard is expendable bait to lure young [[Horde]] adventurers in to their death.\r\n==Abilities==\r\n'''Fire Nova''' - Inflicts Fire damage to nearby enemies.\r\n* School: [[Fire]]\r\n'''Uppercut''' - Inflicts normal damage plus 50 to an enemy, knocking it back.\r\n* School: [[Physical]]\r\n==Combat Info==\r\nTaragaman is not nearly as tough as he looks. Just make sure your tank keeps him away from the casters and he should present no problem for you. He has two abilities that he will use occasionally: [[Fire Nova]] and [[Uppercut]]. Fire Nova is a fairly strong [[AoE]] DD, and Uppercut is an attack that will knock you back a few feet. Just to be safe, make sure you clear all the mobs on the islands next to him before you pull him, in case someone gets knocked near them by the Uppercut. Be careful not to stand within 20 yards of the edge, otherwise you could be thrown into the lava. This could cause a wipe for your group, unless you have either a paladin, rogue, or shaman.\r\n==Objective Of==\r\n*Slaying the Beast",},
			["Taretha's Diversion"] = { content = "After arriving in Old Hillsbrad, create a diversion so that Thrall can escape from his cell in Durnholde.\r\n==Objectives==\r\nTravel to Durnholde Keep and set 5 incendiary charges at the barrels located inside each of the internment lodges using the Pack of Incendiary Bombs given to you by Erozion.\r\nSpeak to Thrall in the basement prison of Durnholde Keep when you have the Internment Lodges Set Ablaze.\r\n* 5/5 Internment Lodges Set Ablaze\r\nProvided Item:\r\n* Pack of Incendiary Bombs\r\n==Details==\r\nThe five lodges you need to destroy are in the lower area of Durnholde, visible below the bridge you cross when entering. Two of the lodges are to the west of the bridge and three are to the east, near the stairs leading into the area. Once you have set off all five incendiary bombs, enter the keep atop the hill and speak to Thrall in the basement. Note that if someone who has already completed this quest chain starts the actual escort phase, you will not be able to turn in this Diversion quest.\r\n'''NOTE: There is a known bug that when a group member not on the quest sets up the bombs, others who are on the quest will not get credit.'''\r\n==Description==\r\nTaretha was integral in Thrall's survival and upbringing and instrumental in shaping Thrall's life.\r\nIt was Taretha who created the original diversion at Durnholde, allowing Thrall to escape.\r\nNow the Infinite have captured Taretha and hold her at Tarren Mill. The diversion will not happen without our involvement. You must use the incendiary devices that I give you and burn down the internment lodges in Durnholde. When you have done this, speak with young Thrall in the basement prison of Durnholde.\r\n==Reward==\r\nUpon completion of this quest you will gain:\r\n* 17950 experience (or a 10 gold 77 silver compensation at level 70)\r\n* 1000 reputation with the [[Keepers of Time]]\r\n==Completion==\r\nYou are friends of Taretha? So this is her new plan? Very well then...",},
			["Taretha"] = { content = "#redirect [[Taretha Foxton]]", redirect = "Taretha Foxton",},
			["Taretha Foxton"] = { content = "'''Taretha Foxton''', or \"Tari\" to her friends, was a close personal friend of the future [[Warchief]] [[Thrall]], during his early life as a slave of [[Aedelas Blackmoore]]. She was instrumental in aiding Thrall in breaking free of his captivity and finding his destiny beyond the walls of [[Durnholde Keep|Durnholde]].\r\nHad Taretha been born in a major city, her life would have been different. As it was, Tari was the daughter of Blackmoore's personal secretary, [[Tammis Foxton]], and despite her intelligence, was not allowed to become the woman she might have been. \r\nDespite her minor role, a mere footnote in the annals of history, Taretha Foxton's actions forever changed the world.\r\n==Biography==\r\nTari, a child of five years, ensured Thrall's survival as an infant by being the only person in Durnholde to realize he was a baby- he simply couldn't eat the meat the guards gave him because he didn't have teeth. When she innocently posed this information, Thrall's diet was hastily changed to milk, and he thrived in the Foxton household. When Thrall was eventually weaned, he was taken away, and Tari wept bitter tears for the green-skinned child she regarded as her little brother.\r\nYears later, Tari, still in her preteens, helped Blackmoore's military advisor, [[Sergeant (Character)|Sergeant]], procure books on military strategy to train Thrall how to think, part of Blackmoore's plans for the orc. Tari used the books to keep up a correspondence with Thrall, still keeping her unusually sharp intelligence hidden. \r\nAt some point, about ten years ago, Blackmoore made Tari his mistress, a position she secretly despised (there are references to strange bruises on her wrists). After Thrall was savagely beaten for losing in the arena, Tari helped him escape Durnholde as both an act of friendship and revenge. Tari set fire to the barn after setting all the animals free, then helped her friend escape by leaving him a large cloak with which to sneak out the front gate while the guards were busy. When Thrall learned of her relationship with Blackmoore, he begged her to go with him, but Tari refused, for the sake of her family. Tari gave Thrall a necklace with the emblem of a cresent moon (interestingly, the symbol of [[Elune]]) as a means of contacting her should he ever need help.\r\nEventually, Thrall did need help. Tari was asked by her friend, now the Warchief of a new [[Horde]], to help them negotiate with Blackmoore. Tari insisted that it was useless and again declined to leave with Thrall. Unfortunately, Blackmoore had her followed and when she returned he questioned her and imprisoned her until he was drunk enough to order her execution.\r\nThe following day, a very drunk Blackmoore hurled Taretha's head at Thrall from the battlements. The sight of the dead woman was so shocking that Thrall cried emotional tears for the first time in life. Needless to say, the loss of the woman who for years had been his only friend did not sit well with the shaman Warchief, and he killed Blackmoore in a duel. After evacuating the keep of humans, he used his new shamanistic skills to destroy Durnholde Keep.\r\n===Tari's Necklace===\r\nYears later, after Thrall became the Warchief, he sent a number of orc volunteers to [[Durnholde Keep]] on a mission to investigate the Syndicate activity in the area as well as recover Taretha's necklace (the same she once gave to him), now worn by Elysa, a mistress of [[Lord Aliden Perenolde]], the leader of the [[Syndicate]] who believed in slavery and sought to subjugate orcs once again. The mission was initially a failure with the leader [[Gol'Dir]] and his companions [[Drull]] and [[Tog'Thar]] being captured by the Syndicate. [[Krusk]] escaped, however, and enlists the aid of Horde players to help rescue his comrades and recover the necklace, slaying Lord Aliden in the process.\r\n===Caverns of Time===\r\nTaretha was instrumental in allowing Thrall to escape from Durnholde. However, the [[Infinite Dragonflight]] has captured Taretha and is holding her prisoner in [[Tarren Mill]], west of Durnholde. Without Taretha's intervention, Thrall would not be able to escape Durnholde. Players must travel through the [[Caverns of Time]], aid Thrall in his escape from Durnholde, and then travel to Tarren Mill to free Taretha from the massive Infinite Dragon known as [[the Epoch Hunter]]. ''Taretha's model in-game is nearly identical to [[Jaina]]'s, corroborating the various sources that note their similarities.''\r\n==Her impact==\r\nBy helping Thrall escape, Taretha ensured the future of the Horde by giving them a new Warchief. Taretha was willing to trust other orcs she met in Thrall's company, showing Frostwolf and Warsong orcs that peace (or at least cooperation) between the two races was possible.\r\n[[Jaina Proudmoore]] somehow reminded Thrall of Taretha, and this may have helped Thrall overcome his distaste for humans and trust the Alliance. In any case, it was Tari who first showed Thrall that friendship between humans and orcs was possible, and this lesson enabled the [[Alliance]] and the [[Horde]] to ally with each other, and thus defeat [[Mannoroth]], and later join the [[Sentinels]] at [[Mount Hyjal]] to vanquish [[Archimonde]].\r\nThus, Taretha Foxton was indirectly responsible for freeing the orcs from their curse, and saving Azeroth from the Defiler. To date, Taretha Foxton is the only human who has had a ''[[lok'vadnod]]'' (\"Song of a Hero\") composed in her honor.",},
			["Targ"] = { content = "'''Targ''' is a level 41 [[ogre]] found in the [[Ruins of Alterac]] in the [[Alterac Mountains]].\r\nTarg is a loyal lieutenant of [[Mug'thol]]. [[Melisara]] wants Targ's head.\r\n==Objective Of==\r\n*The Crown of Will (3)\r\n==Loot==\r\n*Targ's Head ''(Quest Item)''",},
			["Target"] = { content = "In [[World of Warcraft]], a '''target''' can mean a few things:\r\n# Any selected [[mob]] or [[player]].\r\n# A point on the ground used as a center reference for an [[Area of Effect]] attack.\r\n# A type of [[target dummy]].\r\n# An in-game object that you usually can't interact with (but [[NPC]]s sometimes will) used for shooting at like a circular target for archery or a target dummy for melee combat practice.\r\nSome units, usually NPCs, cannot be targeted. Thus, they cannot be the object of any action that requires a target, even [[area of effect]] spells.",},
			["Target dummy"] = { content = "#REDIRECT [[Target Dummy]]", redirect = "Target Dummy",},
			["Targorr the Dread"] = { content = "'''Targorr the Dread''' is a level 24 [[elite]] [[orc]] [[mini-boss]] found in the [[Stormwind Stockade]]. He dual wields and combined with thrash (which grants two extra attacks) can do rather impressive damage quickly.\r\n==Background==\r\nTargorr the Dread served the [[Blackrock Clan|Blackrock]] orcs under [[Gath'Ilzogg]] as supreme Executioner. His methods were ruthless, even by orcish standards. Men who fought bravely to defend the Kingdom were tortured on his whim. Targorr was captured and sent to The Stockade, however due to the corrupt and inefficienct legal system was not executed as his actions so richly deserved. Upon the uprising in The Stockade the ruthless orc fell in line with the defias rioters. [[Guard Berton]] of [[Lakeshire]] wants you to bring him Targorr's head as fast as possible.\r\n==Quests==\r\n*What Comes Around...",},
			["Tarhus"] = { content = "'''Tarhus''' is a level 52 [[reagent]] [[vendor]] located in [[Camp Mojache]] in the [[contested]] territory of [[Feralas]].\r\nSee [[List of Feralas NPCs]].",},
			["Tarindrella"] = { content = "'''Tarindrella''' is a level 7 [[quest giver]] located in [[Shadowglen]] in the [[night elf]] starting zone, [[Teldrassil]]. She is located at 57.7, 45.1.\r\nShe starts the quest The Woodland Protector (2).\r\nSee [[List of Teldrassil NPCs]].",},
			["Tarren Mill"] = { content = "'''Tarren Mill''' is a Horde-allied town located in the northeast of the [[Hillsbrad Foothills]]. \r\n==History==\r\nThe township of Tarren Mill was originally a coastal town in the [[Tarren Mill region]] of Lordaeron (shown to be southwest of Alterac) during the [[Second War]]. King Terenas had ordered Alliance forces to the town in order to free elven archers that had been captured in the region, and were being held in a nearby prison camp. The elves had sent along a force of elven archers to assist the Alliance soldiers in the task, as well as plans for an [[lumber mill|elven lumber mill]].\r\nWhen the soldiers reached Tarren Mill the discovered that the elven archers had already prepared the village for war. They had located their captured bretheren, and were ready to seek revenge. The enemy camp was too far inland for Alliance warships to assist so they preperations to march the next day. The Alliance forces made several raids from the town, before attacking the Horde prison camp. The soldiers returned to Tarren Mill and immedietly sent world of their success. A day later an [[elven destroyer]] arrived at the town with orders for the force to board ship and sail to Southshore where the battles were becoming more common.\r\nWhile the reason is not clear, Tarren Mill was eventually moved inland northeast of [[Southshore]] (and southeast of Alterac). Humans once ran this mill, but it fell to the [[Scourge]], and later the [[Forsaken]]. The undead, led by [[High Executor Darthalia]], attacked Hillsbrad’s citizens mercilessly.\r\nTarren Mill was once a thriving [[Human]] town, but was destroyed and taken over by the Forsaken soon after the [[Battle of Mount Hyjal]]. The town was the site of a major battle between the Orcish Horde and the [[Alliance of Lordaeron]] during the days of the Second War.\r\n==Tarren Mill is under attack!==\r\nThis affectionate nickname is due to the unfortunate fact that, before the introduction of [[Battleground | Battlegrounds]], Tarren Mill was essentially inaccessible because of the 24-hour all-out war that took place right outside it, and oftentimes even '''in'''side it; this situation was created because [[Southshore]] is so close by. In its early days, it was not uncommon to find every single NPC — merchants, quest NPCs, and even the [[Flight Master | bat handler]] — to be killed immediately upon their spawning. The [[Honor System]] did eventually manage to curb this slaughter, but it didn't even put a dent in the real problem: [[ganking]] of low-level players, a problem that existed mainly because Horde players arrive there at 20-30, whilst many Alliance players go there 5-10 levels later.\r\nThe huge load of dozens of players fighting at once created massive zonewide slowdown, oftentimes leading to a condition known as 'lag death' simply because a network connection couldn't possibly handle the overload — more than once an entire server has crashed whenever '''hundreds''' were fighting simultaneously. If one were to be either foolish or masochistic enough to turn on the LocalDefense channel (or, alternately, the WorldDefense channel), the phrase that gave Tarren Mill its nickname would literally crowd out anything and everything else in the chatbox.\r\nA common sight (if one's hardware could manage to show it) was a veritable wall of [[Alliance]] charging the town, with another wall of [[Horde]] rushing forward to meet them. Common latency times were 5+ ''seconds'', with the highest values of 7+ seconds. Since the introduction of Battlegrounds, however, what was once a fool's dream is now a reality: sporadic peace in Tarren Mill. However, on PvP servers, it is still a favorite hunting ground for Alliance players to hunt lower-level Horde and vice versa.\r\n==Facilities==\r\n*[[Herbalism]] trainer\r\n*[[Alchemy]] trainer (expert)\r\n*[[Tailoring]] trainer (master)\r\n*Mushroom vendor\r\n*Trade Supplies vendor\r\n*Tailoring vendor\r\n*Weaponsmith (south of town - allows item repair)\r\n*[[Forge]] (behind Weaponsmith above)\r\n*Stable Master\r\n*[[Inn]]\r\n*[[Mailbox]]\r\n*[[Flight Master]]\r\n===Noteworthy trade items===\r\n* [[Recipe: Shadow Protection Potion]] at [[Cristoph Jeffcoat]], Tradesman (in the Inn)\r\nBuildings:\r\n1 Church\r\n1 Barn\r\n2 one storey houses\r\n1 two storey house (acts as Inn)\r\n===Flight===\r\n [[The Undercity]]\r\n [[The Sepulcher]]\r\n [[Revantusk Village]]\r\n [[Hammerfall]]\r\n===Starting===\r\n*Stone Tokens\r\n*Prison Break In\r\n**Dalaran Patrols\r\n*Blood of Innocents\r\n**Return to Thunder Bluff\r\n*Elixir of Suffering\r\n**Elixir of Suffering (2)\r\n*Elixir of Pain\r\n**Elixir of Pain (2)\r\n*The Hammer May Fall\r\n*The Crown of Will\r\n*The Rescue\r\n*Dangerous!\r\n*Humbert's Sword\r\n*Soothing Turtle Bisque (Horde)\r\n==Notes==\r\n*Newer players who aren't paying attention often call Tarren Mill \"Tauren Mill\". \"Terran Mill\" is also occasionally used.\r\n*Some Horde players also know Tarren Mill as \"Ganking Hell\".",},
			["Tarren Mill region"] = { content = "#REDIRECT [[Tarren Mill]]", redirect = "Tarren Mill",},
			["Tarshaw Jaggedscar"] = { content = "'''Tarshaw Jaggedscar''' is a level 43 [[warrior trainer]] located in the [[Razor Hill Barracks]] in [[Razor Hill]], in the [[orcish]] starting zone of [[Durotar]].\r\nHe starts the quest Veteran Uzzek.\r\nSee [[List of Durotar NPCs]].",},
			["Tarshesite"] = { content = "Tarshesite is the name for the [[doomguard]] race. Tarshesite, [[daemon]]s and [[fiend]]s may be sub-races within the [[ered'ruin]], or ered'ruin is the [[Eredun]] term for the race.",},
			["Tartek the Enraged"] = { content = "'''Tartek the Enraged''' can safely be considered one of the most powerful abominations the [[Scourge]] has ever created. He was assembled by [[Amnennar the Coldbringer]] in [[Razorfen Downs]]. Once created, he slew many [[quilboar]]s, though in the end he was destroyed. Unable to return him to full strength, Ammennar used his remains to create a lesser version named [[Glutton]]. \r\nTartek is mentioned in the [[Compendium of Fallen Heroes]] found in [[Acherus]], and is apparently considered a hero by the [[Scourge]].",},
			["Tar beast"] = { content = "A '''tar beast''' is an [[elemental conglomerate]] of earth and water. It is a black, viscous creature draped with trailing green moss as it oozes slowly across the ground. Its hide appears slick, taut, and rubbery, and the creature forms and retracts small pseudopods as it moves. Any face it might possess is hidden under the veil of moss.\r\nIn the steamy bowl of the [[Un'Goro Crater]], the enigmatic tar beasts rise from bubbling black pits to destroy those who cross them. Also found in warm swamps, tar beasts are primal elementals born of the land. Few travelers ever see a tar beast unless they somehow anger the monster - in which case they feel the unbridled wrath of the elemental. As tar beasts are quiet, reclusive, and unspeaking, no one quite knows what will anger one.\r\nSome scholars theorize that primal forces of nature inhabit and animate tar beasts. The fact that such creatures almost always form in extremely ancient, primitive locations bears this theory out, though it certainly proves little. Others claim that the spirits of deceased [[dinosaur]]s, trapped and drowned in the tar pits, animate the elementals. No one knows for sure. Tar creatures seem to understand Common and Kalimag (which seems to indicate that the creatures are not dinosaur spirits), but they don't speak.\r\nTar beasts begin combat by hurling blobs at their nearest foes. When an enemy closes in, the tar beast engages that enemy only until it becomes stuck in the tar creature's adhesive skin. Then the tar beast shifts its focus to the next-closest enemy.\r\n==Types==\r\n*[[Tar Beast]]\r\n*[[Tar Lord]]\r\n==Notes==\r\n* The plant creatures [[timberling]]s, and [[thistleshrub]]s, and conglomerate elemental creature [[tar beast]], while using the same model as bog beasts are each considered separate types of creatures.\r\n*These creatures are classified as [[Elemental]]s in WoW, this is a fact confirmed by lore, rather than merely being for gameplay reasons.",},
			["Tar Lord"] = { content = "==Drops==\r\n* Un'Goro Soil\r\n* Super Sticky Tar",},
			["Tasaldan"] = { content = "'''Tasaldan''' is a level 70 [[ammo vendor]] located at [[Halaa]] in the [[contested]] territory of [[Nagrand]]. He is only available when the [[Horde]] controls Halaa.\r\nSee [[List of Nagrand NPCs]].",},
			["Taskmaster Snivvle"] = { content = "==Information==\r\nTaskmaster Snivvle is a Kobold champion who claims the coldtooth mine at the beginning of every Alterac Valley battleground. He must be killed in order to claim the mine for your faction.\r\n==Quotes==\r\n ''Snivvle is here! Snivvle claims the Coldtooth mine!''\r\n==Rewards==\r\n'''Reputation ([[Frostwolf Clan]]) ([[Stormpike Guard]])''': ''+2''\r\n==Quests==",},
			["Taskmaster Whipfang"] = { content = "'''Taskmaster Whipfang''' is a level 22 [[elite]] [[rare mob]] [[gnoll]] found in [[Windshear Crag]] in the [[Stonetalon Mountains]].",},
			["Tatiana"] = { content = "'''Tatiana''' is a level 60 [[master]] [[jewelcrafting trainer]] and [[vendor]] located at [[Honor Hold]] in the [[contested]] territory of [[Hellfire Peninsula]].\r\n==Trainer==\r\nThis vender offers [[master]] [[jewelcrafting]] training, as well as [[recipe]]s up to Level 365\r\n==Merchant==\r\n*Design: Bold Blood Garnet \r\n*Design: Bright Blood Garnet \r\n*Design: Brilliant Golden Draenite \r\n*Design: Inscribed Flame Spessarite \r\n*Design: Glinting Flame Spessarite \r\n*Design: Glowing Shadow Draenite \r\n*Design: Jagged Deep Peridot \r\n*Design: Radiant Deep Peridot \r\n*Design: Rigid Golden Draenite \r\n*Design: Solid Azure Moonstone \r\n*Design: Sovereign Shadow Draenite \r\n*Design: Sparkling Azure Moonstone \r\n*Design: Teardrop Blood Garnet \r\n*Design: Smooth Golden Draenite \r\n*Jeweler's Kit \r\n*Simple Grinder\r\n==See also==\r\nSee [[List of Hellfire Peninsula NPCs]].",},
			["Tattered Chest"] = { content = "'''Tattered Chests''' are found throughout the zones [[Eversong Woods]], [[Bloodmyst Isle]], [[Azuremyst Isle]], [[Silverpine Forest]] and [[Ghostlands]].",},
			["Taunka'le"] = { content = "#REDIRECT [[Taunka'le Village]]", redirect = "Taunka'le Village",},
			["Taunka'le Village"] = { content = "'''Taunka'le Village''' is a [[Taunka]] settlement in the [[Borean Tundra]] of [[Northrend]].\r\n[[Chieftain Wintergale]] asks for aid in evacuating the village, as he fears the [[Scourge]] will attack them soon, in the quest chain The Fall of Taunka'le Village.",},
			["Taunka"] = { content = "The '''taunka''' (aka winter tauren) are an ancient offshoot of the [[tauren]]. They were thought to be lost until discovered by [[Garrosh Hellscream]] and his [[orc]] forces upon arriving in [[Northrend]]. . They have now allied with the Horde.\r\nLike the [[tauren]], they are involved with the spirits of the land, though after living for so long in such a harsh environment as Northrend they tend to bully the elements rather than ask them to keep their region inhabitable. \r\n''This tenacious, stoic race knows all too well the rigors of living in the harsh and often deadly wastes of Northrend. Over time, the taunka—whom many believe to be ancestral cousins of the tauren—have adapted, but only by forcing the land and the elements to yield to their will. The taunka's relationship with nature, unlike that of their tauren brethren, has been one of constant struggle and grim perseverance.''\r\n''Although the taunka may seem dour or even cold to outsiders, those who come to know them will soon recognize an embattled race of survivors characterized by colossal hearts and unshakable resolve.'' \r\n==Appearance==\r\nConcept art shows that though they appear similar to the tauren, they more resemble [[wikipedia:bison|bison]] than [[wikipedia:cattle|cattle]].\r\n===Factions===\r\n* [[The Taunka]]\r\n===Locations===\r\n* [[Taunka'le Village]] ([[Borean Tundra]])\r\n* [[Camp Winterhoof]] ([[Howling Fjord]])\r\n* [[Camp Oneqwah]] ([[Grizzly Hills]])\r\n* [[Icemist Village]] ([[Dragonblight]])\r\n* [[Westwind Refugee Camp]] ([[Dragonblight]])\r\n==Origin of the name==\r\nThe name \"taunka\" likely comes from the word \"tatanka\", the [[wikipedia:Lakota language|Lakota]] word for bison.",},
			["Taunt"] = { content = "'''Taunt''' Can mean several things in [[World of Warcraft]]. \r\n==Aggro Management==\r\nTaunt can refer to the class abilities that allow players to attract attention of a [[mob]]. They include the following:\r\n* [[Warrior]]'s [[Taunt (Warrior ability)|Taunt]], [[Mocking Blow]], [[Challenging Shout]].\r\n* [[Druid]]'s [[Growl (Druid)|Growl]], [[Challenging Roar]].\r\n* [[Paladin]]'s [[Righteous Defense]]. \r\nOther classes have high aggro abilities that generate set amount of threat. They include:\r\n* [[Hunter]] pet's [[Growl (pet)|Growl]].\r\n* [[Hunter]] pet's [[Intimidation]].\r\n* [[Hunter]]'s [[Distracting Shot]].\r\n* [[Warlock]] [[Voidwalker (Warlock pet)|Voidwalker]]'s [[Torment]].\r\n==Verbal Discourse==\r\n* Using /yell to call members of the enemy force Bad Names during PvP Raids. \r\n**Note: The enemy force only see gibberish when you do this, so it tends to be a bit lost on them, but they get the general idea.\r\n*Using the [[slash command]] /taunt to show an animation and play a sound that would be spiteful to an enemy player. /chicken and /rude are similar.",},
			["Taunt (Warrior)"] = { content = "#REDIRECT [[Taunt (warrior ability)]]", redirect = "Taunt (warrior ability)",},
			["Taunt (warrior ability)"] = { content = "==Overview==\r\n''Taunting is a more difficult art than one might think. This is partly because of the quite involved and detailed understanding of psychology necessary, partly because most battlefields are quite noisy and hectic places, but mostly because so few of Azeroth's denizens actually ''have'' a Mother in the conventional sense...''\r\n==Functionality==\r\n'''Taunt''' is a single target debuff that costs 0 [[Warrior|Rage]]. Unless the target is immune to taunt effects, generally bosses but also some other mobs are immune, it generates enough [[threat]] to equal that of the person that currently has [[aggro]] and forces the target to attack the taunting [[warrior]] for 3 seconds. It has a 10 second cooldown and can be resisted. It does not trigger a [[global cooldown]].\r\nAvailable in [[Defensive Stance]] only.\r\nThe ability is taught for free on completion of the level 10 [[Defensive_Stance|Defensive Stance quests]].\r\nTaunt may be enhanced with the Protection Tree [[Improved Taunt]] Talent.\r\n* Rank 1/2 = -1 Second Cooldown to 9 Seconds\r\n* Rank 2/2 = -2 Second Cooldown to 8 Seconds\r\n==Notes==\r\nTaunt is one of the most crucial tools a Main Tank Warrior has. It makes controlling aggro in group combat much more manageable, especially in difficult situations. Taunt will set the Warrior's threat level to equal the person who has [[aggro]] from the mob Taunted as well as forcing the mob to attack the Warrior for 3 seconds. After these 3 seconds, the Warrior must still continue increasing his threat on the mob to maintain aggro (as the healers and DPS will continue generating threat and eventually pull off of him).\r\nHere's a scenario:\r\nA character (1) has 1000 points of threat on a mob. A Warrior (2) taunts the mob, gaining 1000 points of threat and applies a debuff forcing the mob to attack (2) for three seconds. After those three seconds, threat works normally for the mob, and if no one is at 130%/110% (ranged/melee) of the tank's threat, (2) will still be the mob's target.\r\nIf the situation permits it, it may be more effective to use Taunt on a mob that is running toward an attacker or healer out of melee range, as characters out of melee range require 130% of the tank's threat to pull a mob's aggro.\r\nTaunt has no effect on enemy players in PvP and does not have any effect when the Warrior already has aggro on the mob (except the mob will still be forced to target the Warrior for 3 seconds). Taunt does not cost any rage.\r\n====Pulling====\r\nA note for the people [[pulling]] for raids:\r\nThe [[puller]], normally a [[Hunter]], should pull with high damage and high threat abilities such as [[Distracting Shot]], [[Arcane Shot]] with the [[Main Tank]] under the effects of [[Misdirection]] to generate threat on the tank instead of the hunter. Taunt could be used to set the tank's aggro to the same level as the hunter's and then [[Feign Death]] to set the hunter's to zero, but there is a chance for one or both abilites to fail and the other strategy is much simpler.\r\n===Past Changes===\r\nIn [[Patch 2.3]], the chance for this ability to land successfully on its target is now increased by hit rating. However, Taunt remained classified as a spell for the purposes of determining miss rate versus mobs. That means that against a mob 3 levels higher than the player, *Taunt has a base chance of 17% to be resisted (a miss)*. (*Needs reference) There is also a 1% chance to be resisted that cannot be overcome with gear.",},
			["Taur-ahe"] = { content = "'''Taur-ahe''', also known as \"Taurahe\", is the [[language]] of [[tauren]]. It is pronounced \"taur-AH-heh.\" The language of the tauren is often harsh and low sounding. Tauren do not have an alphabet as other races do; their written language is made of elaborate pictograms and pictoforms. While the tauren have a written language, based on pictoforms rather than alphabet, their nomadic ancestry discouraged writing. As such, written documentation usually falls to the tribe's shamans and is done on the sides of huts, clothing, tools, or even rocks and other natural formations. Most history and lessons are passed down orally from one generation to the next.\r\n==Taur-ahe Primer (official translations)==\r\nHere are a few common Taur-ahe phrases and words, for which the translations have been officially confirmed by [[Blizzard]]: \r\n*\"[[Shu'halo]]\" = \"The [[Tauren]]\"\r\n*\"[[An'she]]\" = \"The Sun\"\r\n*\"[[Mu'sha]]\" = \"The Moon\"\r\n*\"[[Apa'ro]]\" = \"[[Malorne]]\"\r\n*\"[[Echeyakee]]\" = \"Whitemist\" [[Quest:Echeyakee]]\r\n*\"[[Isha Awak]]\" = \"Deep Doom\" [[Quest:Isha Awak]]\r\n*\"[[Ishamuhale]]\" = \"Speartooth\" [[Quest:Ishamuhale]]\r\n*\"[[Lakota'mani]]\" = \"Earthshaker\" [[Quest:Lakota'mani]]\r\n*\"[[Owatanka]]\" = \"Bluebolt\" [[Quest:Owatanka]]\r\n*\"[[Washte Pawne]]\" = \"Spirit Biter\" [[Quest:Washte Pawne]]\r\n===Tauren Names===\r\nThe language of the tauren is often harsh and low sounding, which is reflected in the names of their children. The last name of a tauren is usually a family name, handed down through the generations. If the tauren has performed some act that has made an impression on the elders of his tribe, however, he may choose to take on his own last name to commemorate that act.\r\n* Male Names: Azok, Bron, Turok, Garaddon, Hruon, Jeddek.\r\n* Female Names: Argo, Serga, Grenda, Beruna, Halfa.\r\n* Family Names: Darkthorn, Thunderhoof, Stormhorn, Quillsplitter, Stonebreaker, Plainstalker, Spiritwalker.\r\n===Untranslated Names or Phrases===\r\n*\"[[Arikara]]\"\r\n*\"[[Arra'chea]]\"\r\n*\"[[Mazzranache]]\"\r\n* \"[[Camp Aparaje|Aparaje]]\"\r\n* \"[[Camp Mojache|Mojache]]\"\r\n* \"[[Camp Narache|Narache]]\" \r\n* \"[[Camp Taurajo|Taurajo]]\"\r\n* \"[[Tahonda Ruins|Tahonda]]\"\r\n* \"Ish-ne-alo por-ah\" (WC3) - Said by [[Cairne]] (Most likely a greeting).\r\n* \"[[Por-ah Stone|Por-ah]]\" - the name of a legendary stone.\r\n==Algorithmic Taur-ahe words==\r\nThis is the list of words created by the in-game language parser for the Taurahe language, and is listed as language number three (word range 315-422) in the Language text file. The parser is used to mask both NPC and players that speak \"Taurahe\" when encountered by other races.\r\nNote: The language algorithm used by the in-game \"translator\" merely makes the words ''look'' like Taur-ahe. It does not actually translate words. Therefore, translated in-game speech isn't true Taur-ahe.\r\nWhen translating text, the language algorithm will use the exact same number of letters for each word and the same order they were said in. Multiple things will turn out to be one word.\r\nIt should be noted, however, that some language algorithm translations, like \"Echeyakee\" and \"Isha Awak\", have been made official.\r\n'''Words said by players'''\r\n* Lol = Kee\r\n* Thanks = Owachi\r\n* Good = Awak\r\n* Bad = Aki\r\n* Hello = Nechi\r\n* Bye = Ish\r\n* Yes = Zhi\r\n* No = Wa\r\n* World of Warcraft = Ahmen Wa Ovaktalo\r\n* Hi = Mu\r\n* You = Chi\r\n'''NPC Translations'''\r\n*When the quest Call of Earth (Mulgore 3) is completed by a [[tauren]], the quest ender, [[Seer Ravenfeather]], says in Taurahe:\r\nPeace and patience be with you, <name>. Remain strong as always.\r\n*When the quest is completed by an [[orc]] or [[troll]], [[Seer Ravenfeather]] says in Taurahe:\r\nNechi ich towateke ki hale chi, <name>. Pawene ichnee pawene.",},
			["Taurahe"] = { content = "#REDIRECT [[Taur-ahe]]", redirect = "Taur-ahe",},
			["Tauren"] = { content = "The '''tauren''' ('''shu'halo''' in their native language of [[Taur-ahe]] and sometimes pluralized as '''taurens''') are a race of large, bovine [[humanoid]]s who dwell on the great plains of [[Central Kalimdor]]. For countless generations, they were constantly harassed by the violent [[centaur]], who forced the tauren into a nomadic lifestyle in the harsh [[Barrens]]. However, during the [[Third War]] and the [[Horde]]'s invasion of [[Kalimdor]], the tauren and the invading Horde became allies, and the Horde aided the tauren in driving off the centaur from the sacred lands of [[Mulgore]]. High Chieftain [[Cairne Bloodhoof]] established the capital city of [[Thunder Bluff]], and to this day the tauren remain one of the most stalwart allies of the Horde, even after Cairne's death and the ascension of his son, [[Baine Bloodhoof]].\r\nDespite their enormous size, the tauren are a peaceful and honorable people who nonetheless are fierce fighters when roused. Hunting and shamanism are held in high regard in their culture, as is their worship of the [[Earth Mother]] and respect for the land and nature.\r\n===Origins and early history===\r\nThe intrepid [[dwarf]] explorer [[Brann Bronzebeard]] believes that the tauren may ultimately be descended from an unknown bull [[Ancient Guardian|Ancient]], or some kind of animal spirit predating the [[Emerald Dream]].\r\nThe tauren are the descendants of a bovine race known as the [[yaungol]]. Several millennia before the [[First War]], the yaungol roamed central [[Kalimdor (landmass)|Kalimdor]] and lived in peace with the demigod [[Cenarius]], but were eventually driven south due to not wanting to share hunting grounds with the [[troll]]s. There, the yaungol were enslaved by the [[mogu empire]] and twisted by the mogu [[flesh-shaping|flesh-shapers]]. Though they eventually regained their freedom along with the other slave races during the [[pandaren revolution]], much of their ancient cultural heritage had been lost. Heated arguments led many yaungol to migrate back north. While one group traveled as far north as the [[Storm Peaks]], where they took up the name [[taunka]], the other group settled in the balmy areas surrounding the [[Well of Eternity]]. There, they reunited with Cenarius and rediscovered their ancient traditions. Those who studied with Cenarius learned the [[druid]]ic magic of the natural world, while others mastered the art of wielding [[shaman]]ic powers. The energies of the Well soon began to change these yaungol into a new race, who would later take up the name \"tauren\". The taunka, tauren, and yaungol retained some contact with one another for many years, but the [[Great Sundering]] finally shattered the connections between the tribes.\r\n===War of the Ancients===\r\nThe tauren of [[Highmountain]] were convinced to join an alliance with the [[Night elf|night elves]] and other races against the Burning Legion by the dragon-mage [[Korialstrasz]], and the tauren tribes were led by [[Huln Highmountain]], wielder of the [[Talonclaw|eagle spear]]. The xenophobic night elf commander, [[Desdel Stareye]], refused to use the tauren to their abilities, namely heavy melee fighters, on the grounds that they were apparently as likely to kill night elves and [[earthen]] as [[demon]]s. After the \"tragic\" loss of the commander, the tauren were re-deployed to extreme effectiveness by his replacement, [[Jarod Shadowsong]]. The tauren who survived the war maintained fairly good, or at least cordial, relations with the [[Sentinels]].\r\nDue to a blessing bestowed upon Huln by [[Cenarius]], the [[Highmountain tauren|tauren]] under Huln — the [[Rivermane tribe|Rivermane]], [[Bloodtotem tribe|Bloodtotem]], [[Skyhorn tribe|Skyhorn]], and [[Highmountain Tribe|Highmountain]] tribes — were given the [[Horns of Eche'ro]]: [[moose]]-like antlers. After the war, these tribes would rename their home region [[Highmountain]] in honor of Huln's heroism during the war.\r\n===The rise of the centaur===\r\n1,100 years before the opening of the [[Dark Portal]], the tauren wandered Kalimdor's forests and plains, living in harmony with nature. One region in particular was especially sacred: the verdant grassland of [[Desolace|Mashan'she]], or \"Loom of the [[Earth Mother]]\". Drawn by faint [[elemental]] whisperings, the tauren became convinced that somewhere beneath the meadows, the Earth Mother herself dwelled. After decades of attempting to rouse her from her slumber, the tauren [[shaman]] eventually succeeded, but to their horror they realized that what they had awakened was not the benevolent Earth Mother, but the enormous [[earth elemental]] [[Princess Theradras]], daughter of [[Therazane|Therazane the Stonemother]]. The newly awakened Theradras reached out to the verdant surroundings for sustenance and consumed their energies in order to regenerate her weakened form. The tauren would later name this now barren land \"Desolace\".\r\nThe sudden monumental loss of life sent ripples throughout all of [[Azeroth]] and even the [[Emerald Dream]]. [[Zaetar]], son of the forestlord [[Cenarius]], traveled to Desolace to investigate, but though he had decided to imprison Theradras, he instead fell in love with her. Theradras requited Zaetar's affection, and the two became mates. From this forbidden and unnatural union, the [[centaur]] were born. After having brutally murdered their father, the half-horse creatures quickly proliferated and spread out across Kalimdor, driving the tauren of Desolace from their homes and igniting a long and dark period of war that would come to last for many centuries.\r\nFor countless generations, the tauren roamed the plains of the [[Barrens]] hunting the mighty [[kodo]], and sought the wisdom of their eternal goddess, the [[Earth Mother]]. Their tent settlements were scattered across the landscape and changed with the seasons and the weather. The wandering tribes were united only by a common hatred for their sworn enemy, the marauding centaur. The centaur hunted the tauren for sport and launched intermittent attacks on their foes, taking a heavy toll on both sides. The tauren did not shy away from combat and made the centaur pay for every unprovoked attack, but they had no love for war and always opted to find a new home rather than throw their lives away whenever the horse men appeared. As such, the tauren lived in a constant state of upheaval, and a year of peace was always followed by a year of war. The shu'halo accepted this cycle of conflict as inescapable as it was the only life they knew, but that would eventually change.\r\nThe [[Earthen Ring]] was originally founded by tauren [[shaman]] some time before the [[War of the Three Hammers]] to lead their people with wisdom and maintain the harmony between the [[elemental spirit]]s.\r\n===The Third War and the Horde===\r\n''The mighty tauren of the Kalimdor plains have pledged their allegiance to the new Horde out of respect for their courage and honor. The bold Tauren seek only to safeguard their quiet culture from the deathly fires of the Burning Legion. When roused, tauren are fierce fighters and use their flails, horns and their mighty totems to smash their enemies into the dust of the plains.''\r\nAt the brink of extinction, the chieftain [[Cairne Bloodhoof]], desperate for help, turned to the strange green-skinned warriors from over the sea. Cairne quickly befriended [[Thrall|Warchief Thrall]] and the other [[orc]]s, and recognized that they shared a love for honor and battle. For their part, the orcs and the [[Darkspear|Darkspear trolls]] that composed the [[Horde]] found much in common with the tauren. Each of these races wanted to achieve a more [[shamanism|shamanistic]] culture, and the tauren, long versed in the lore of spirit and nature, were well-prepared to provide counsel and support to the budding [[shaman]]ism within the Horde.\r\nWith the orcs' help, [[Cairne Bloodhoof|Cairne]] and his [[Bloodhoof tribe]] were able to drive back the [[centaur]] and claim the grasslands of [[Mulgore]] for themselves. For the first time in millennia, the tauren had a land to call their own. For this alone they were forever indebted to their orcish allies. Upon the windswept mesa of [[Thunder Bluff]], Cairne built a refuge for his people, where tauren of [[Tauren|every tribe]] were welcome.\r\nOwing a blood-debt to the orcs for their assistance, the tauren joined Thrall on [[Mount Hyjal]] to defend [[Kalimdor]] from an invasion by the demonic [[Burning Legion]]. Following the Legion's defeat, the tauren who helped defend Hyjal returned to their new home in Mulgore.\r\nOver time the scattered tauren tribes united under Cairne's rule. There were but a few tribes who disagreed about the direction their new nation should take, but all agreed that Cairne was the wisest and best suited to lead them toward the future. Helping the mighty Cairne in the duties of ruling his race were the [[Hamuul Runetotem|Archdruid Hamuul Runetotem]] and the elder crone [[Magatha Grimtotem]].\r\nAlthough the tauren had reclaimed their lands and battled alongside the Horde, not all was peaceful. The [[Grimtotem tribe]] tried to usurp the rule of Cairne, plotting to overthrow his leadership. In Mulgore, they had problems with the [[Bristleback tribe|Bristleback]] [[quilboar]]. At the same time, the [[Emerald Dream]], realm of the [[green dragonflight]], was tainted with a strange evil. [[Malfurion Stormrage]] was trapped inside, and the green dragons acted strangely as they attacked all who passed near. Both [[night elf|elven]] and tauren druids were researching these events since the Emerald Dream, home of [[Ysera|Ysera the Dreamer]] ([[Dragon Aspects|the Green Aspect]]), had to be kept safe.\r\nSeveral tauren individuals have joined the organizations like the [[Twilight's Hammer cult]] and the [[Shadow Council]].\r\n==Culture==\r\nThe tauren are a noble race that embrace the natural world. They have shed their nomadic roots and united in their ancestral lands. Their race may be one of spirituality, reverence for nature, and respect for elders, but it also possesses powerful warriors that willingly fight when the situation demands it. A calm and steady people, the shu'halo strive to live honorable and dignified lives filled with respect for nature and the [[Earth Mother]]. Although strong and capable warriors when roused in battle, most tauren reserve combat for when all other options are exhausted. They prefer course of wise discussion and careful rumination before embarking on any great endeavor, and they have great respect for the wise, spiritual and elderly among their people. The tauren are not wrathful by nature, but sometimes a thirst for justice causes them to take up arms in anger.\r\nThough the noble tauren are peaceful in nature, the rites of the Great Hunt are venerated as the heart of their spiritual culture. Every tauren, warrior or otherwise, seeks identity as both a [[hunter]] and as a child of the Earthmother. Tauren, young or otherwise, seek to prove their bravery by setting themselves against the creatures of the wild. Hunting is a tauren's greatest honor; at times they hunt for food, at times for honor, and at times to earn the Earthmother's teachings. Hunters are important to the tribes as a strong part of tauren tradition and history, and are respected and revered if they serve their people well. Young [[gazelle]]s quickly learn to flee when they hear the war cries of tauren hunters in Mulgore. They don't hear the good hunters, unfortunately. While mighty [[warrior]]s defend the tauren's homes, [[shaman]]s show the ancestors' past and [[druid]]s discover the Earthmother's will, hunters learn many aspects of those roles and blend them together. They represent the heart of the tauren people, and are looked to for guidance and protection. Despite killing the animals, the tauren are taught never to waste anything given to them by nature and to give back what they can. They learn the fine balance that exists in nature and that if they honor the Earthmother, she will bless them in return.\r\nMany tribes claim that it is a gift to be blessed with the aptitude to use [[magic]] or to talk to the ancestors, but tauren [[warrior]]s are taught that they are just as gifted. They are a special breed also, not unlike the druids and shamans, and are just as important. They are the ones called upon to defend the borders, to hunt the [[centaur]], and to go to war. Every warrior plays a role in their tribe, and they must all go through the same rites.\r\nDespite their enormous size and brute strength, the remarkably peaceful tauren cultivate a quiet, tribal society. However, when roused by conflict, tauren are implacable enemies who will use every ounce of their strength to smash their enemies under hoof. They are noble and proud and have never, despite significant adversity in the past, succumbed to their enemies. Like the orcs, the tauren now struggle to retain their sense of tradition and noble identity.\r\nTheir buildings are called long houses and great tents.\r\n===Faith===\r\nThe tauren worship the [[Earth Mother]] as their creator. According to the tauren myth [[Sorrow of the Earthmother]], when the Earth Mother saw her children falling to the corrupting whispers from below the earth, (the work of the [[Old Gods]]) she tore out her eyes and set them spinning endlessly across the sky. Her left eye became [[Mu'sha]], the moon, and her right eye became [[An'she]], the sun. Neither of both is better than the other, and together they see with balanced vision - they are the tauren's own \"Light\".\r\nThe earliest history of the tauren is recorded in a series of [[tauren mythology|myths]]. These chronicle the period of time from the creation of the world to the appearance of the [[centaur]], speaking of the creation of the tauren by the Earthmother, their meeting with [[Cenarius]], and the coming of the centaur.\r\nDue to [[night elf|night elven]] influence, tauren [[druid]]s long revered only Mu'sha, as Mu'sha is considered to be the tauren equivalent of the kaldorei moon goddess, [[Elune]]. During the [[War against the Lich King]], the warrior [[Aponi Brightmane]] engaged in a theological discussion about this matter with [[Tahu Sagewind]]. Aponi pointed out that in all else, the tauren strived for balance, and she wondered if they had neglected a key aspect of balance in all things. As a result of these discussions, following the [[Cataclysm (event)|Cataclysm]], the [[Sunwalkers]], an order of tauren [[paladin]]s, arose, wielding the power of the [[Light]] through An'she.\r\nBesides the Earthmother and her two eyes, an entity known as the [[Sky Father]] is also worshipped.\r\n*The tauren are a simple people, and as a result, their rites tend to not be particularly complex. They have no need for elaborate words or rare items in their ceremonies. What the good earth provides is almost always sufficient.\r\n*Corn pollen is used in ceremonies that involve life, whereas the dust from cremated tauren is used in rituals of the dead.\r\n*The tauren believe that the Earth Mother weaves the strands of fate.\r\n*[[Void|Darkness]] is not considered evil by the tauren, for it is a naturally occurring thing, and therefore right.\r\n*Believed to be the ill omen of a coming age, white tauren are held in near reverence by their people, often becoming reclusive [[spirit walker|priests]] who wander the land in search of kindred spirits.\r\n*Tauren legends abound regarding the great horned [[kodo]]s of [[Kalimdor]]'s [[Barrens]]. Some myths tell of rare kodos that are bound to the spirits of the sky and storm, thus allowing the colossal beasts to harness the powers of lightning itself.\r\n*[[Sun roc]]s feature prominently in primitive tauren mythological cycles.\r\n*Shu'halo ancient myth tells of three powerful artifacts — [[the Rattle of Bones]], [[the Drums of War]] and [[the Writ of History]]. If the tales are to be believed, they were gifts from the Earth Mother herself.\r\n*The tauren chieftains hold such sacred bonds with their Earthmother that they can actually be [[reincarnate]]d after they die in combat. Though this ability is very rare, it makes the wise, benevolent chieftains a dangerous foe to threaten.\r\n====Last rites====\r\nThe tauren consider death to merely be the shadow of life and hold that the ending of things is as natural as the birth of them.\r\nDespite now having a permanent home in [[Thunder Bluff]], the tauren choose not bury their dead, as they keep many traditions they held during their travels across Kalimdor. Rather, they prepare the body for its return to the elements and place it at one of their sacred grave sites. Only the most valiant tauren are laid to rest at [[Red Rocks]], the tauren's sacred burial ground. It is an honor bestowed upon the great warriors who helped found and defend Thunder Bluff and those who have given their lives for the greater good of their tribes and chieftains.\r\nWhen a tauren is cremated, it is done with ceremony and ritual. The body of the deceased is ritually bathed and wrapped in a ceremonial blanket before being placed atop a pyre, after which a fire is lit beneath them. The ashes are offered to the winds and rivers, to become one with [[Earth Mother]] and [[Sky Father]]. As the ashes fall to the earth and the smoke rises to the sky, both the Earth Mother and Sky Father welcome the honored dead, and [[An'she]] and [[Elune|Mu'sha]] witness their passing. This death ritual speaks of the tauren's origins as nomads, and if their loved ones are freed to the wind and fire, they can wander in death as they did in life if they so choose.\r\nEach tauren tribe has its own rites to honor their dead, but nearly all perform their rituals at Red Rocks. The tribes differ in their sacred tinder for the funeral pyre. The [[Eagletalon tribe]] uses [[:earthroot]], the [[Bloodhoof tribe]] prefers [[:peacebloom]]. The ceremonies themselves are focused on the same thing: sending off beloved family and braves to be reunited with their gods, the Earth Mother and Sky Father.\r\nOnce the proper rites have been performed, the spirits of the deceased join the Earth Mother to find peace, and deceased tauren ancestors are welcomed at the \"hearth of the ancestors\". It is believed that the spirits of dead tauren walk in the shadow of the [[Spirit of Life]].\r\nThe [[Dawnchaser tribe]] believes that honored ancestors who gave their own lives to save, or create, other lives become ''yeena'e'' (\"those who herald the dawn\" in [[Taur-ahe]]) — spirits who aid An'she in announcing the coming of dawn.\r\n====The Feast of Winter Veil====\r\nThe tauren and their [[shaman]]istic understanding of winter, along with their recent emergence into [[druid]]ic endeavors, fit in well with the legend of [[Feast of Winter Veil|Winter Veil]]. They focus almost entirely on the renewing aspects of the lore however, leaving legend worship to those races (as they view it) less in tune with the nature of things. Many tauren choose this time as the right time to give thanks for the blessings of their new home in [[Mulgore]]. [[Furmund|Some tauren]] disapprove of the modern Winter Veil celebrations, claiming that the [[goblin]]s have \"polluted\" the true meaning of the holiday.\r\n===Customs===\r\n*The [[Tauren totem|totem poles]] of the tauren people represent a link to their past. The carvings provide a focus for shamanic arts or illustrate stories of famous events or heroic tales.\r\n*Tauren villages use smoke signals to coordinate hunts over great distances, or, occasionally, to signal distress.\r\n*One respectful greeting gesture of the tauren is to touch one's heart, then forehead. A tauren salute is carried out by placing their hand on their chest, over their heart, and stamping on the ground.\r\n*An ancient tauren custom at the beginning of peace talks is to share a ceremonial pipe among the participants. The pipe is filled with herbs, lit, and subsequently passed from person to person, with each individual being encouraged to think on what they hope to achieve with the meeting. During one meeting with fellow [[Horde]] members, [[Baine Bloodhoof]] advocated the use of a speaking stick — a branch with feathers, beads, and bits of bone tied around it. Only the person holding the stick was allowed to speak.\r\n*Young tauren perform the Rites of the Earthmother in order to become [[brave]]s and gain the respect of elders in [[Thunder Bluff]]. These Rites consist of the following:\r\n**[[Rite of Strength (Classic)|Rite of Strength]]: the first ceremony, proving physical strength.\r\n**[[Rite of Courage|Rite of Courage]]: to prove bravery in the face of the enemy.\r\n**[[Rite of Honor|Rite of Honor]]: to uphold the honor of your people.\r\n**[[Rite of the Winds|Rite of the Winds]]: willingness to seek the unknown.\r\n**[[Rite of Vision (5)|Rite of Vision]]: willingness to follow the guidance of the spirits.\r\n**[[Rite of Wisdom|Rite of Wisdom]]: to honor one's ancestors.\r\n**After completing the Rites, the brave must continue proving their worth in order to retain their status.\r\n*One ceremony apparently involves a tauren presenting themselves before the High Chieftain whilst wearing a special feathered headdress. At least one of their siblings is required to witness the ceremony.\r\nIt is likely that each tribe has their own unique traditions, as the [[Dawnchaser tribe]] is known to have customs rarely found in other tribes.\r\n===Cuisine===\r\nThe shu'halo use pine nuts in most dishes: meat, fish, vegetables, even baked into breads or sprinkled over sweet pastries. The very best pine nuts come from the trees upon the very mesas of [[Thunder Bluff]]. The fine and noble [[Mulgore Spice Bread|spice bread]] of Thunder Bluff is traded in countless settlements in the most far-away lands, even by the tauren's staunchest foes. One of Thunder Bluff's most important staples is cornmeal; bowls of corn may be found in nearly every home, and [[Cornmeal Biscuit|cornmeal biscuits]], once merely a staple food among the tauren tribes in Mulgore, have traveled along various trade routes and are now enjoyed in many regions across Azeroth. One of the great delicacies of [[Mulgore]] is the crayfish that dwell in lakes and streams. They are particularly popular during weddings or the celebration of a birth.\r\nWhen the [[Alliance]] allied with the [[Grimtotem tribe]] in [[Stonetalon Mountains]], [[Force Commander Valen]] asked [[\"Cookie\" McWeaksauce]] to cook up the finest of tauren cuisine; an offering no tauren, \"not even a grim tauren\", could refuse. It consisted of [[eagle]] eggs, [[ram]] meat and a special cheese kept by the local [[kobold]]s.\r\n[[Thunder Bluff Marzipan]] is a traditional tauren [[Hallow's End]] treat.\r\n===Mounts and pets===\r\nThe [[kodo]]s are the racial mount of the tauren. Swifter and slightly smaller than their wild cousins, kodo mounts nevertheless demonstrate the same resilience and fearlessness found in their untamed brethren, traits that serve them well when bearing their equally resolute riders. When the tauren settled in Mulgore, they also brought the kodos with them. Many kodos hold a special bond with the benevolent tauren race.\r\nLike rest of the Horde in Kalimdor, the tauren use [[wyvern]]s, which they consider sacred, as their flying mounts.\r\n[[Brown Prairie Dog]]s are their racial pets.\r\n===Equipment===\r\n[[Tauren halberd]]s are used by [[tauren chieftain]]s.\r\n===Languages and naming===\r\nTauren speak [[taur-ahe]] and [[Orcish (language)|orcish]].\r\nHere follows a sampling of tauren names taken from ''[[World of Warcraft]]'' and the ''[[World of Warcraft Trading Card Game]]''.\r\n*'''Sample male names''': Motah, Ahul, Varg, Dezco, Turak, Helaku, Hurnahet, Torwa, Huum\r\n*'''Sample female names''': Tamaala, Winnoa, Chepi, Hahrana, Kamu, Torra, Jyn, Isashi, Tawn\r\n*'''Sample last names''': Ragetotem, Huntsworn, Lighthoof, Hawkseye, Dawnchaser, Thunderhorn, Winterbluff\r\nThe [[Dawnchaser tribe]] have a rare tradition of giving their newborn \"weaning names\" until they are old enough to receive a true name.\r\n==Appearance==\r\nTauren are large bipedal ungulates, described as half-bovine beings. On average, tauren are towering, with females standing at 9 feet in height while males reach 10 feet. Tauren are roughly a foot shorter in-game, likely due to game limitations such as too small doorways. Females and males alike are known to have a very large bulk and weight, long tails, large hooves, and three fingers (two fingers, one thumb) per hand. Both males and females have horns of varying size and shape. Tauren are a mostly diurnal race.\r\nTauren are large, muscular humanoids and bovine in appearance, complete with hooves and horns. They weigh anywhere from 400 to 800 pounds. Their immense bodies are covered with fine, short fur that ranges in color from black to gray to white to red to brown to tan and any mottled combinations or variations thereof. When tauren grow old, their pelts start to become dotted with gray. During the summer months, tauren use their ears and tails to flick off [[Fly|flies]].\r\n[[Fleet Master Seahorn]] remarks that most non-tauren find them indistinguishable from one another. In fact, most non-tauren find them indistinguishable from [[Cow|a certain four-legged farm creature]].\r\nTauren can see in the dark better than [[human]]s.\r\n===Tribes/clans===\r\n*[[Bloodhoof tribe]] — Leading tauren tribe within the Horde. Led by [[Baine Bloodhoof]].\r\n*[[Dawnchaser tribe]] — Tribe who set out to find [[Pandaria]]. Led by [[Sunwalker Dezco]].\r\n*[[Dawnstrider tribe]]\r\n*[[Farwanderers tribe]] — Considered leaving the Horde due to disapproving of Garrosh's rule. Led by [[Greyhoof Farwanderer]].\r\n*[[Grimtotem tribe|Grimtotem tribe / clan]] — Renegade tribe, known for being much more aggressive than other tauren. Led by [[Magatha Grimtotem]].\r\n*[[Highmountain tribe (Legends)|Highmountain tribe]] — Led by [[Ornamm]] or [[Sulamm]]. It's unclear if this tribe has any relation to the [[Highmountain tauren]].\r\n*[[Ironhoof tribe]] - According to [[Durgan One-God]], the tauren of Old Ironhoof live in the [[Desolace]] area called the [[Last Forest]].\r\n*[[Ragetotem tribe]]\r\n*[[Skychaser tribe]] — Spiritual leaders of tauren [[shaman]]. Wiped out by the [[Grimtotem tribe|Grimtotem]].\r\n*[[Steelrage tribe]]\r\n*[[Stonehoof tribe]]\r\n*[[Thunderhorn clan|Thunderhorn clan / tribe]]\r\n*[[Wildmane clan]]\r\n*[[Winterhoof tribe]]\r\n*[[Tribemother Torra]]'s unnamed tribe whose members perished during the [[Siege of Orgrimmar]] and the [[Battle for Broken Shore]].\r\n''Note: These may not all represent tribes, but only special names given later in life or surnames.''\r\n*[[Clawhoof]]\r\n*[[Cliffwalker]]s — Dwell on top of [[Cliffwalker Post]] in [[Stonetalon Mountains]]. Led by [[High Chieftain Cliffwalker]].\r\n*[[Cloudsong tribe|Cloudsong]]s — Took on the role of spiritual leaders after the [[Skychaser tribe]] was wiped out by the [[Grimtotem tribe|Grimtotem]].\r\n*[[Darkmane]]\r\n*[[Eagletalon tribe]]\r\n*[[Hawkwind tribe]] - Chief Hawkwind's tribe from Camp Narache\r\n*[[Longstride]]\r\n*[[Mistrunner]]\r\n*[[Runetotem clan]] — Tonga Runetotem describes Mura Runetotem as a clanmate.\r\n*[[Skyseer]]\r\n*[[Stonespire tribe]] — Gann Stonespire was a member of a tribe that was mostly wiped out by the [[dwarf|dwarves]] of [[Bael'dun Keep]].\r\n*[[Wheathoof]]\r\n*[[Whitecloud]]\r\n*[[Wildrunner]]\r\n*[[Windtotem]]\r\n*[[Younghoof]]\r\n===Organizations===\r\n*[[Earthen Ring]] — A worldwide organization of the most powerful [[shaman]] on [[Azeroth]], originally founded by tauren shaman.\r\n**[[Elder Council]] — Ruling council of the Earthen Ring. Also functions as a governing council in [[Thunder Bluff]].\r\n*[[Longwalkers]] — Scouts and messengers who serve only [[Baine Bloodhoof|Baine]], and before him, [[Cairne Bloodhoof|Cairne]].\r\n*[[Outrunner|Outrunners]] — An organization dedicated to ensuring the safety of all who travel through [[Mulgore]]'s plains.\r\n*[[Seers]] — An order of tauren [[priest]]s formed in the wake of the [[Cataclysm (event)|Cataclysm]]. Led by [[Tahu Sagewind]].\r\n*[[Sunwalkers]] — An order of tauren [[paladin]]s formed in the wake of the Cataclysm. They are the most militant branch of the tauren armies within the Horde. Led by [[Aponi Brightmane]].\r\nTauren are found as members in a multitude of independent organizations, most notably the [[Cenarion Circle]] and the [[Twilight's Hammer]] cult. Some individuals are adventuring explorers such as [[Trag Highmountain]] (who was one of the first tauren to appear in [[Lordaeron]] and the [[Eastern Kingdoms]]) and the ancient Watcher [[Xarantaur]], who is assisting the [[bronze dragonflight]]. Over the years, some [[pirate]]s had journeyed to Kalimdor and recruited or impressed various tauren into their crews, and shu'halo pirates can be found as members of the [[Blackwater Raiders]], [[Bloodsail Buccaneers]], [[Northsea Freebooters]] and the [[Dread Crew]], just to name a few. As such, these criminal tauren were among the first to appear in the Eastern Kingdoms, and some even call [[Rustberg Village]] of [[Tol Barad]] home, becoming [[Rustberg Fisherman|fishermen]]. A [[Mr. Smite|sole tauren]] was also a member of the infamous [[Defias Brotherhood]].\r\n===The Horde===\r\n''\"The world is torn, and our Horde allies have turned down dark paths. We must guide them. Even in the darkest hour, we will bravely hold our heads high, and honor the Earth Mother in all we do.\"''\r\n— [[Baine Bloodhoof]]\r\nThe tauren remain stalwart allies of the [[Horde]], even after [[Cairne Bloodhoof|Cairne's]] death. The [[Grimtotem tribe]], is, in fact, the only tribe to have never formally joined the Horde. When a great drought struck Horde-controlled lands in [[Kalimdor]] and [[quilboar]] raids became frequent, [[Garrosh Hellscream|Garrosh]] demanded that the tauren deliver water from [[Mulgore]] to [[Durotar]]. The [[Farwanderers tribe]], who were not used to remaining static, disapproved of Garrosh's rule and [[Baine Bloodhoof|Baine's]] passive obedience at the Warchief's every command, and so considered leaving [[Mulgore]]. However, they were eventually convinced to remain in Mulgore, and the Horde, after Baine dealt with the [[quilboar]] problem.\r\nFollowing the destruction of [[Camp Taurajo]], a group of tauren were unsatisfied with Baine's rule, and so the High Chieftain banished them from [[Thunder Bluff]] but did not take further action. Despite this, the tauren tribes retain respect for their High Chieftain.\r\nThe Forsaken\r\nWhen [[Sylvanas Windrunner]] sent out emissaries to various factions in order to protect her budding nation, the [[Forsaken]], the kind-hearted tauren of Thunder Bluff proved to be the most promising contact. Specifically, Archdruid [[Hamuul Runetotem]] saw the potential for redemption in Sylvanas' people, even though he was fully aware of the Forsaken's sinister nature. Thus, the tauren convinced Warchief [[Thrall]], despite his misgivings, to forge an alliance of convenience between the Forsaken and the [[Horde]]. There are some tauren, such as the [[Elder Council]], that wish to cure the Forsaken, and [[Bena Winterhoof]], who wept when first seeing the undead, claims that she was given a mission by the [[Earth Mother]] herself to save their new undead allies from their curse. [[Magatha Grimtotem]] herself was one of the original proponents of the alliance between the tauren and the Forsaken, and she, more than anyone among the elders, felt the tauren and their ways could help the Forsaken find a path back to being human. She claimed that to heal the land, the tauren had to first remove the disease upon it. She pointed out that the Forsaken know much of disease, and claimed that by aiding one another, the trust between the two peoples would be strengthened.\r\n===The Alliance===\r\nThe tauren are not as hostile to the Alliance as some of the other races that comprise the Horde, though many Alliance members consider them to be little more than beasts. [[Varian Wrynn]] notes that the tauren are the only Horde race that do not make him want to immediately reach for his weapon, but they, too, have made themselves untrustworthy by siding with the [[orc]]s.\r\nTauren have poor relations with the [[dwarf|dwarves]] of [[Ironforge]], as the dwarves' constant digging in the earth has caused them to come into conflict with the tauren. The tauren see their digging as scarring the [[Earth Mother]], and that the dwarves are hollowing and defiling the land. The [[Stonespire tribe]] of tauren were nearly wiped out by the dwarves of [[Bael'dun Keep]], and as a result [[Gann Stonespire]], one of the few survivors, severed all ties with the Horde and went rogue to exact vengeance or die trying. The tauren don't seem to get along well with the [[Wildhammer clan]], either, as it was their [[gryphon rider]]s that firebombed [[Camp Taurajo]]. [[Roon Wildmane]] and [[Hemet Nesingwary]] is one of the few cases of friendship despite the enmity between the two races.\r\nOf all the [[Alliance]] races, the [[night elf|night elves]] are the ones with the best relations to the tauren, due to their shared druidic tradition and connection to nature. Arch Druid [[Hamuul Runetotem]] strives for diplomacy and willingly works side by side with the night elf druids in the [[Cenarion Circle]]. The tauren have shown an incredible propensity to the tenets of [[Cenarius]], and by their proxy the Horde is welcomed within the safety of [[Moonglade]]. The preservation of [[Azeroth]] is a common goal that the two races both share. One notable example of close friendship between shu'halo and kaldorei is that of [[Tholo Whitehoof]] and [[Anren Shadowseeker]]. However, despite the bond between the two races, there are some tauren who believe that the night elves' pride still limits their sight. Prior to the [[War of the Shifting Sands]], the night elves and the tauren had apparently been involved in a blood feud dating back centuries. Some of the kaldorei during the [[War of the Ancients]], such as [[Desdel Stareye]], also seemed to regard the tauren who came to their aid as barbaric and uncivilized in nature, although this attitude seems to have considerably lessened over the millennia.\r\nThe [[Grimtotem tribe]], after being driven from [[Mulgore]], briefly allied with the [[Alliance]] in the [[Stonetalon Mountains]], but the pact was broken shortly afterwards.\r\n===The Grimtotem===\r\n''\"Some see our people as gentle giants, or noble savages. They have never seen us fight against our own kind... against betrayers from within.\r\nThe Grimtotem were offered mercy in exile, and they have scarred their own home to spite us. They will no longer be tolerated in Mulgore.\"''\r\n— [[Baine Bloodhoof]]\r\nThe [[Grimtotem tribe]] stand as an aggressive extreme of the usually pacifistic tauren, wishing to eradicate the \"lesser races\" from [[Kalimdor]] and to retake the tauren's long lost ancestral holdings. Even before their exile, the Grimtotem showed open hostility towards the other tribes, going so far as to attack the settlement of [[Freewind Post]] and almost eradicate an entire village in [[Stonetalon Mountains|Stonetalon]].\r\nAfter the [[battle for Thunder Bluff]] and the exile of the treacherous Grimtotem, they sought to ruin [[Mulgore]] itself as they were driven out, sending a force led by [[Orno Grimtotem]] through the [[Stonetalon Pass (Mulgore)|Stonetalon Pass]] and poisoning several sacred tauren water wells throughout Mulgore.\r\n===Other===\r\nThe centaur\r\nTauren and [[centaur]] tribes have long feuded with each other over the lands that the two nomadic races shared. The centaur are known for their brutality and savagery, but support from the [[Horde]] has turned the conflict in the tauren's favor, allowing them not only to survive but also to prosper. The barbaric centaur over-hunted [[giraffe]]s for decades, but it was the tauren who saved them from extinction. The tauren claim that the centaur have always existed to scourge the land, even though the shu'halo were actually indirectly responsible for the centaur's creation by awakening [[Princess Theradras|Theradras]].\r\nDespite this, friendship between a tauren and a centaur can be made as seen with [[Ironhoof]] and [[Dorthar]].\r\nThe quilboar\r\nThe vicious, boar-like [[quilboar]] have long clashed with both the centaur and the tauren over land and food. One tauren group inhabited the southern parts of the [[Barrens]] for decades and considered the land to be holy, but they were driven off by the [[quilboar]]. While some tauren were able to forgive being driven from their ancestral lands, others, such as [[Auld Stonespire]], were not and considered the quilboar's actions to be a sin worthy of the most severe revenge.\r\nThe [[Bristleback tribe]] have long been at war with the tauren of [[Red Cloud Mesa]], ambushing hunting parties and stealing from the village by dark. For years they encroached on [[Camp Narache]], and the great [[Cataclysm (event)|Cataclysm]] finally drove them from their dens to spread like locusts across the land. [[Chief Squealer Thornmantle]] set upon [[Greatmother Hawkwind]] and took her life. The [[Bristleback Thorncaller|thorncallers]] began calling up great roots to choke out all other life in the mesa, and the Bristlebacks began training wild boars to be used against the tauren. A band of Bristleback quilboar also began ravaging the [[Red Rocks]], the holy burial ground of the tauren.\r\nDue to a drought that struck [[Central Kalimdor]] shortly after the Shattering, a group of quilboar began raiding Horde caravans and water shipments. Though [[Garrosh Hellscream|Warchief Garrosh]] and his [[Kor'kron]] tried to put an end to the quilboar with force, it was [[Baine Bloodhoof|Baine]] and [[Hamuul Runetotem|Hamuul]] who resolved the conflict by creating a new river for the quilboar to take their water from.\r\nAlthough centaur, tauren, and quilboar all hate each other, the three races come together to do trade at [[Flayers' Point]] in [[Desolace]]. But there is no love lost between them, and brawls erupt like clockwork every five minutes, earning the trading post the nickname \"Slayers' Point\".\r\nThe harpies\r\n[[Harpy|Harpies]] have clashed with the tauren on several occasions. During the [[Third War]], a group of harpies from the [[Stonetalon Mountains]] started poaching the tauren's precious [[kodo]] herds, slaughtering them mercilessly and leaving the beasts to rot in the sun. The threat was only dealt with once [[Rexxar]] set out to kill the witches. The [[Windfury harpies]] are one of the tauren's natural enemies in [[Mulgore]], and the shu'halo collect their feathers for ceremonial headdresses. The tauren take pride as the protector of the [[Stonetalon Mountains]], which unsurprisingly caused them to come into conflict with the nearby [[Bloodfury]] harpies.\r\nThe furbolgs\r\nThe [[furbolg]]s formed positive relations with the tauren after the [[War of the Ancients]].\r\n===Yaungol===\r\nThough previously indicated to be an ancient offshoot of the tauren race, the [[yaungol]] are actually the ancestors of both the tauren and the [[taunka]]. Unlike the two offshoot groups, the yaungol remained in the land later known as [[Pandaria]], even after the [[Great Sundering]] separated them from their northern cousins. As a result of living in the harsh [[Townlong Steppes]], a land they are forced to share with the dreaded [[mantid]], the yaungol are a much more violent people than their tauren or taunka descendants, using oil and fire to succeed in battle. They were introduced in ''[[World of Warcraft: Mists of Pandaria]]''.\r\n===Taunka===\r\nAn ancient offshoot of the yaungol race dwelling in [[Northrend]], the [[taunka]] were thought to have been lost forever but were rediscovered by [[orc]]ish forces based in [[Warsong Hold]]. Due to dwelling in the unforgiving frozen wastes of Northrend, the taunka have taken to commanding the [[elemental|elements]] by force rather than asking them for aid. However, much like the tauren, the taunka have chosen to ally themselves with the Horde. They were introduced in ''[[World of Warcraft: Wrath of the Lich King]]''.\r\n===Highmountain tauren===\r\nDirect descendants of the tauren led by [[Huln Highmountain]] who fought in the [[War of the Ancients]], the [[Highmountain tauren]] have lived in peace in the region of [[Highmountain]] on the [[Broken Isles]] for millennia, until the shamanistic [[drogbar]] rose up and stole the [[Hammer of Khaz'goroth]], shattering their unity. They were introduced in ''[[World of Warcraft: Legion]]''.\r\n===Introduction===\r\nThe plains of Kalimdor have long been a home to these tremendous nomads. The tauren are a race of [[shaman]]s, [[hunter]]s, and [[warrior]]s who long ago developed a complex culture and system of living without the aid of stonework, steel or conquest. This is not to say that the tauren are a race of pacifists, for when they are angered they are capable of retaliating with swift and decisive brutality. Tauren are, in a word, stoic, embodying the strong and silent type with their quiet contemplation. This introspective air combined with their immense size can lead a person to understand as to \"why\" many regard the tauren as a wise and dangerous race. Tauren rarely speak unless there is a true reason to, preferring to act instead of talk. However, once a tauren has learned to interact with a companion, there seems to be a more open and enthusiastic exchange of words. Since tauren warm slowly to non-tauren, they are usually silent and may sometimes appear brooding. If anything, a person could attribute the silence of the tauren on the strife of recent times. Tauren have no love for bloodshed, as their deep spiritual beliefs do not have a place for warfare. The elders of a tribe solve most issues, or two tauren might resolve a conflict with a ritual challenge resembling a duel. Having become members of the [[Horde]], the introspective race has been involved in more and more conflict, creating a demand for tauren warriors and healers. Many must spend time putting great thought into the actions they perform on the field of battle. Taking another life, whether it is man or beast, is an act filled with great significance and responsibility to the tauren.\r\nTauren ancestors dwell deep within the [[Emerald Dream]].\r\nTheir history is relatively short compared to Kalimdor's other races. Ancient accounts suggest they were the result of magical experiments that fused titan with beast, but details are lost to the ages.\r\n===Relations===\r\nWhen the tauren first encountered the orcs of Thrall's Horde, the tauren recognized the orcs as spiritual brethren. No other race shared such a similar outlook on the world, and the shamans of both races met frequently to discuss the matters of the spirit world. The tauren allied with the orcs out of a shared vision, one of a collective of allies keeping each other well guarded. While the tauren see the orcs and trolls as potential friends to welcome, they rarely trust the Forsaken with more than a nod and a place to set their withered feet.\r\nTauren also bear no ill will to the members of the Alliance unless threatened by them, although they do make an exception for high elves. The taint of magic on the high elven spirit is a poisonous air to the tauren, a stench of the soul that they cannot tolerate for long. Night elves are quite the opposite; tauren sometimes view them with awe and fear. Tauren and night elves have coexisted on Kalimdor for centuries, and tauren have long seen the Kaldorei as a mythic race of demigods, possessed of great magic and steeped in natural powers. Before the coming of the Horde to [[Kalimdor]], the nomadic tauren fought a virtually eternal war against the [[centaur]], living their humble lives from day to day and camp to camp. Deeply shamanistic, probably even more so than the early orcs, the tauren revered nature; this fact allowed them to maintain some level of peace with the night elves, whom they rarely encountered. The night elves and the tauren were well aware of the other's existence at this time and simply kept their distance without war or any major trade.\r\nTauren have an extremely close relationship with the orcs with whom they share a similar culture. Cairne is also extremely close friends with Thrall. They are less thrilled at the presence of the Forsaken at Thunder Bluff, who they grudgingly tolerate due to their alliance. The tauren place a strong emphasis on the value of life, and the unlife of the Forsaken stands as an affront to their beliefs.\r\nIn general, however, the tauren get along with the orcs well and the trolls almost as well; there's still a bit of distrust for the Darkspears, knowing that they only recently abandoned voodoo and cannibalism.\r\n===Faith===\r\nFor the tauren, nature is the mother of the world, and their faith holds a deep and resonant tone within their hearts. Tauren are connected to the ebb and flow of the world. They revere the spirits of the land and of their ancestors, and they turn to these spirits for wisdom and guidance. This connection manifests in their deeply animistic culture, where druids and shamans stand side by side with warriors and hunters. Tauren do not see a separation between the veneration of nature and the hunt; to hunt is to honor the spirits of nature.\r\n===Spiritual Hierarchy and Tauren Titles===\r\nThe tauren possess a structure of spiritual hierarchy. The most talented and powerful shaman traditionally hold positions of power, though rulership is not limited to spellcasters. Shaman interpret the voice of the Earth Mother and the wishes of the ancestors; sometimes these interpretations lead to the rise of hunters and warriors in the tribe. Such is the case with Cairne Bloodhoof, the former chieftain. The leader of a tribe uses the title \"chief\" and/or \"chieftain.\" The three most powerful healers in the tribe support the chief, the most powerful of whom takes the title \"seer.\" A chief generally consults his seer and her two contemporaries before making a decision, but this consultation is not required. The leader of the United Tauren Tribes — Baine Bloodhoof, these days — also uses the title \"chieftain.\" During council meetings, chiefs make recommendations to the chieftain, but again the final decision is the chieftain's alone to make. \"Chief,\" \"chieftain\", and \"seer\" are genderless titles. Aged female shaman sometimes take the title of \"crone\" or \"elder crone\", which others use as a sign of respect.\r\n===Languages===\r\nTauren tend to learn languages for trade or exchanging ideas.\r\n===Names===\r\nThe language of the tauren is often harsh and low sounding, which is reflected in the names of their children. The last name of a tauren is usually a family name, handed down through the generations. If the tauren has performed some act that has made an impression on the elders of his tribe, however, he may choose to take on his own last name to commemorate that act. Tauren have several names. They receive a name at birth and another during a ceremony to celebrate reaching adulthood. This adult name describes some event in their lives or some notable individual characteristic: for instance, Blackhide, Earthborn, Halfhorn, Hidemaker, Riverwatcher, Scar, Splithoof, Stormchaser, or Windrunner. A tauren may also acquire a third name that he uses when dealing with outsiders.\r\n* Male Names: Azok, Bron, Turok, Garaddon, Hruon, Jeddek.\r\n* Female Names: Argo, Serga, Bessey, Beruna, Halfa.\r\n* Family Names: Darkthorn, Thunderhoof, Stormhorn, Quillsplitter, Stonebreaker, Plainstalker, Spiritwalker.\r\n===Appearance===\r\nTauren are large, muscular humanoids with bull-like heads. Tauren are mostly muscle, having incredibly developed physiques and brawny frames most suitable for combat. Soft, downy fur (usually quite short) covers the tauren body, with manes growing along head and neck, the lengths of the arms, and the shins. Tauren men and women almost always wear their hair long, and the males prefer braids to any other style. Coloration can range from solid black to blond and even to white, or mottled pelts with a range of spots and different colors.\r\nHorns are most prominent on males, although all tauren have horns. Tauren wear natural clothing — leather or hide, and some cloth. They prize jewelry, designing fine trinkets of ivory, bone and amber. From these materials they make bracelets or necklaces, and sometimes adorn their horns or locks with such beautiful displays of artistry.\r\n===Tauren RPG classes===\r\n*[[Spirit champion]]\r\n*[[Wilderness stalker]]\r\n*[[Plagueshifter]]\r\n*[[Holy strider]]\r\n===See also===\r\n*[[Horde technology|Tauren technology]]\r\n==Notes and trivia==\r\n*Tauren were shown with four fingers on their hands in early art instead of with three fingers as they appeared in WoW. The [[:File:BTNSpiritLink.png|icon of the Spirit Link]] ability of the [[Spirit Walker (Warcraft III)|Spirit Walker]] unit shows a tauren hand with four fingers in ''[[Warcraft III: The Frozen Throne]]''.\r\n*[[Brann Bronzebeard]] once [[Flavor lore|theorized]] that the tauren predated the [[titan]]s' arrival on [[Azeroth]] and therefore also the creation of the first [[Well of Eternity]], just like the [[troll]]s. This was proven wrong in ''[[World of Warcraft: Chronicle Volume 1|Chronicle Volume 1]]'', as the tauren actually evolved from [[yaungol]] who were affected by energies emanating from the Well. However, Brann's theorized bull [[Ancient Guardian|Ancient]] may still have created the yaungol.\r\n*Tauren hooves are a secret ingredient used by confectioners.\r\n*Occasionally, some [[Darkspear tribe|Darkspear]] [[jungle troll|trolls]] travel to [[Thunder Bluff]] to live with the tauren and adopt their ways. [[Chen Stormstout]] refers to these trolls as \"blue tauren\".\r\n*The tauren were originally planned to be their own faction in ''Warcraft III'' but were later incorporated into the Horde.\r\n*While she was located at [[Light's Hope Chapel]] and arguing with [[Eligor Dawnbringer]], [[Scarlet Commander Marjhan]] disdainfully referred to the tauren as '''bull-men'''.\r\n*The word \"tauren\" is an of \"nature\", though whether this was intentional is unknown.\r\n*The origin of the tauren as a racial off-shoot of the [[yaungol]], who are based on Mongolian motifs, holds similarities to the \"ice bridge\" theory.\r\n==Inspirations==\r\n*The tauren are based upon the , a part man, part bull monster from Greek mythology, and the tauren were originally referred to as [[minotaur]]s during the early stages of development for ''[[Warcraft III: Reign of Chaos]]''. The name \"Minotaur\" is either derived from Ancient Greek ''ταῦρος/taûros'' or Latin ''taurus'', both meaning \"bull\". (See the article about [[myth|myth references]] for more information.)\r\n*The way their culture and architecture are depicted in-game is based on North American Natives. A few of these obvious connections are below:\r\n**the appears notably as the design of both Mulgore and Highmountain totems having the eagle at the top.\r\n**the use of , prominent for the among others\r\n**the direct lift of as a greeting, something that originates with the \r\n**how within the animal totems are used to correspond to tribes, such as the bear for the [[Bloodtotem tribe]].\r\n**the use of the of the , such as the and ; most notably depicted on Tauren Chieftains.\r\n**The role of [[spiritwalker]]s resembles the importance of the common to many peoples, in particular the Lakota. Spirit quests have been depicted several times amongst the tauren already, typically overseen by one of them.",},
			["Tauren chieftain"] = { content = "The '''tauren chieftains''', or '''tauren chief''', are elder [[Tauren]] [[warrior]]s that lead their Tribes in daily life as well as in battle. Ceremoniously decked with the ancient totems of their Tribes, Chiefs uphold the honor and simplicity of Tauren culture. When roused by battle, the gigantic Chiefs employ enormous warblades which are capable of tearing through solid trees with one mighty swipe. The Chiefs are fascinated by the [[Orc]]s, especially their young leader, [[Thrall]]. The Chiefs see an opportunity to help the Orcs return to their traditional roots by providing a strong example of honor and courage through all Tauren warriors. \r\nTauren chieftains possess impressive battle skills combined with a knowledge of tactics, geography and current affairs. A tauren chieftain knows where alliances are strongest and where they are likely to break down; he also knows where best to stage a mass battle and what location works for a small ambush. A tauren chieftain's competence and wisdom inspires his troops.\r\nIt is unknown if all chieftains practice [[shamanism]], but [[Cairne Bloodhoof]] is known to practice it.\r\n==Famous or named==\r\nMarn Thunderhorn, Tygore Dusthoof, Tam Windtotem, Durn Harpyslayer, Kam Ghoststeer, [[Kel Stonebull]], Mull Stormhoof, Grok Bloodhorn, Malaar Plainstrider, Taur Runetotem, [[Cairne Bloodhoof]], [[Baine Bloodhoof]], [[Osak]].",},
			["Tauren Commoner"] = { content = "'''Tauren Commoner''' can be found in [[Thunder Bluff]].\r\n==Quest==",},
			["Tauren Marine"] = { content = "The '''Tauren Marine''' was an April Fool's Day prank conducted by [[Blizzard]] in 2008. The website for ''[[StarCraft II]]'' was updated with an announcement that the Tauren Marines were the newest Terran Unit. \r\nAccording to the unit description page, ''StarCraft'''s Terran Confederacy discovered an obscure planet called [[Azeroth]], which was home to \"a dizzying selection of humans, mutants, and aliens in a state of perpetual superstition and conflict.\" The Confederacy decided that the [[Tauren]], one of the most physically imposing of Azeroth's species, would make excellent additions to their space marine corps., and equipped the large number of young bulls who were interested in their proposition with state-of-the-art armour and weaponry.\r\n==See also==\r\nThe other April Fool's Day pranks from 2008:\r\n*''[[World of Warcraft: The Molten Core]]''\r\n*[[Bard (hero class)]]",},
			["Tauren mythology"] = { content = "The [[tauren]] have a long history, much of which is recorded on banners hanging in the tent of the Archdruid on [[Thunder Bluff]]. These various myths recount important events from the history of the people, and illustrate the virtues they hold to be important.\r\n===[[Mists of Dawn]]===\r\nThe earliest of the tauren myths, the ''Mists of Dawn'', recounts the creation of the world and the tauren race by a deity called the [[Earthmother]]. Before the age of memory, the Earthmother breathed the world into existence from the golden mists, transforming the clouds into rich, endless fields of grain. She created day and night by alternately opening and closing her right and left eyes, [[An'she]] (the sun), and [[Mu'sha]] (the moon), respectively. The shadow of her hands caused the Tauren, the Shu'halo, the Children of the Earth, to rise up from the soil. They swore to follow their creator until the end of the world.\r\n===[[Sorrow of the Earthmother]]===\r\nThe next myth of the Shu'halo, chronologically, speaks of the falling away of the tauren from their initial state of grace. Whispers rose up from far beneath the world, where the [[Titan]]s had chained the Old Gods. The tauren fell under the sway of these whispers, and learned of malice and deceit. The Earthmother felt a great sorrow at this, and in her grief, tore out her eyes, the sun and moon, and sent them chasing one another across the stars. The Earthmother, now sightless, remained to listen to and guide her children.\r\n===[[The White Stag and the Moon]]===\r\nThis tale speaks of how the Earthmother gave the Shu'halo the love of the hunt. The tauren became great hunters, but one spirit eluded them, Apa'ro, the white stag (called [[Malorne]] by the [[night elves]].) The tauren hunted Apa'ro to the ends of Azeroth, and finally the stag fled into the heavens, where his great antlers became tangled in the stars. As the moon, Mu'sha, chased her brother across the skies, she saw the helpless stag, and immediately fell in love with him.\r\nMu'sha saved the great stag, and in return he loved her, and they conceived a child, [[Cenarius]], a demigod, union of the sky and the earth.\r\n===[[Forestlord and the First Druids]]===\r\nCenarius grew to be as proud as his father, and in time befriended the tauren. He taught them the [[druid]]ic ways, how to speak to the trees and animals. With this knowledge, the tauren aided the demigod in keeping the land safe.\r\n===[[Hatred of the Centaur]]===\r\nThe last of the traditional tauren stories takes place after the fading of the Mists of Dawn and the beginning of the Age of Memory. When Cenarius eventually left the tauren they were saddened by the loss, and over generations they forgot the bulk of his druidic teachings, though they always retained their respect for the earth.\r\nThough the tauren forgot how to speak to the forests, they lived in peace, no longer tempted by the dark whispers from beneath the world. In time, however, a great storm rode out from the west. The barbaric [[centaur]] swept into the tauren's lands. The tauren fought nobly, but the power of the centaur was too great. The Children of the Earth were then forced to wander the world as nomads for eons, staying in no place too long.",},
			["Tauren myths"] = { content = "#REDIRECT [[Tauren mythology]]", redirect = "Tauren mythology",},
			["Tauren rogue"] = { content = "They do exist. They are just so good you never see them. They're even so stealthy their class choice for the Tauren hides! And noone has ever seen the Tauren rogue trainers in Thunder Bluff.\r\n==Wannabes==\r\nTauren wish they could be [[Rogues]]!\r\nThere is one hiding in elite camouflage in this picture! You'll never find her... '''UNSEEN'''!\r\nIn a rare moment of visibility caught on camera, here is clear evidence of a tauren rogue in the act, along with his Murloc accomplice!\r\n==Tauren Rogue Herbalists==\r\nEven worse are Tauren Rogue Herbalists. When you try to farm Herbs for the next big Guild Raid and you can't find any - there must be a Tauren Rogue Herbalist nearby.\r\n==Known Tauren Rogues==\r\nTauren rogues are notoriously unseen. However, there was one historic sighting on Sunday, December 2, 2007, of what APPEARED to be the dead Tauren rogue Qoi of the Emerald Dream server, found in Warsong Gulch. However, the Horde denies all knowledge of Tauren Rogues and asserts that Qoi was an innocent Shaman who mysteriously disappeared on a previous occasion, and therefore could not have been in Warsong Gulch as a rogue. Furthermore, Cairne Bloodhoof has stated that,\"The notion of Tauren Rogues is as preposterous as getting Drek'Thar to go outside and get some fresh air. You are all insane.\" If YOU witness a Tauren Rogue or are victimized by their uncontrolled rampages (that we are sure happen) and live, please call the Society for Telling People That Tauren Rogues Do Exist.\r\n==Secret Tauren Model Info==\r\nBoth male and female Tauren models DO have Stealth animations, complete with the transparency effect. However this is probably because of the orb of desception.",},
			["Tauren totem"] = { content = "'''Tauren totem''' is a building for the Orcish Horde in [[Warcraft III]], where the [[tauren (WC3)|tauren]] are trained.",},
			["Taur Stonehoof"] = { content = "'''Taur Stonehoof''' is a level 30 [[blacksmithing]] [[vendor]] located on the [[Lower Rise]] in the [[tauren]] city of [[Thunder Bluff]].\r\nSee [[List of Thunder Bluff NPCs]].",},
			["Tavarok"] = { content = "'''Tavarok''' is the second boss of [[Mana Tombs]] in [[Auchindoun]]. He is a light-blue [[Colossus]].\r\n==Attacks and abilities==\r\n*'''Melee''': Does about 250-400 damage on each hit.\r\n*'''Earthquake''': Does 919 to 1181 every one second for three seconds to all targets within 35 yards of Tavarok. The ability also stuns the targets.\r\n*'''Crystal Prison''': Cast on a random target and stuns the target. The ability deals damage equal to 10% of the target's life every second for five seconds for a total of 50%.\r\n*'''Arcing Smash''': (heroic). Damages targets in a cone in front of Tavarok. The ability hits the target for 125% weapon damage.\r\n==Strategy==\r\nThis is a straightforward tank-and-spank encounter requiring little to no mobility from the party. No special positioning is required except for possibly ranged and healing classes; they should attack and heal from as far away as possible.\r\nTavarok will occasionally cast Earthquake. This ability stuns players in a 35 yard radius from it while also inflicting approximately 800 physical damage every 1 second for 3 seconds. Ranged classes are able to out-range the ability. If necessary, step further out of range from Tavarok to bandage.\r\nTavarok will also cast Crystal Prison, which immobilizes a single target while dealing damage equal to 10% of that target's health every 1 second for 5 seconds; it has a 60 yard range and players should not attempt to out-range it. Party members should keep their health above 50% in the off-chance they are unable to receive heals. If the main healer is affected, then any extra healers, if available, should be ready to heal.\r\nWhen Tavarok is killed, it can be [[mining|mined]]. It can yield 4-8 Adamantite Ore and various gems, as well as [[Lesser Planar Essence]].\r\n===Heroic strategy===\r\nTavarok retains the same abilities on Heroic mode as it does on Normal, but has Arcing Smash and deals more physical melee damage. Arcing Smash inflicts damage to players in a frontal cone in front of Tavarok. Excluding the tank, melee classes should attack from behind Tavarok to avoid the attack. Otherwise, the strategy is the same as on Normal.\r\nArcing Smash appears to have an extremely wide damage range; an appropriately-geared Warrior can take normal (non-crushing, non-critical) hits from it for over 11,000 damage! Be sure to keep the tank topped off as much as possible, and keep HOT effects up so that a sudden spike in damage does not cause them to die. Arcing Smash can be dodged and parried, and is mitigated by armor. If your tank does not have at least 12,000HP, you are at serious risk of being 1-shotted if you are unlucky.\r\n==Loot==\r\n*His corpse can be mined:\r\n**4-8 Adamantite Ore\r\n**1-2 Eternium Ore\r\n**3-6 Lesser Planar Essence",},
			["Tavern"] = { content = "#REDIRECT [[Inn]]", redirect = "Inn",},
			["Tavernkeeper"] = { content = "#REDIRECT [[Bartender]]", redirect = "Bartender",},
			["Tavern of Time"] = { content = "The '''Tavern of Time''' is a [[tavern]] located within the [[Caverns of Time]]. It is here that [[Alexston Chrome]] sells [[Bottle of Pinot Noir]], [[Flagon of Mead]], [[Flask of Port]], [[Jug of Bourbon]], and [[Skin of Dwarven Stout]].",},
			["Tazan's Logbook"] = { content = "==Source==\r\nContained in Tazan's Satchel.\r\n==Tazan's Logbook as a quest objective==\r\nThis item is an objective of The Shattered Hand.",},
			["Tazan's Satchel"] = { content = "==Source==\r\nThis item drops from [[Tazan]] in [[The Barrens]].\r\nThis item is provided for The Shattered Hand.\r\n==Tazan's Satchel as a quest objective==\r\nThis item is an objective of The Shattered Hand.",},
			["Tazz'Alaor"] = { content = "'''Tazz'Alaor''' is an area of [[Lower Blackrock Spire]], and the domain of the [[Smolderthorn]] [[forest troll]]s. It is ruled by [[Shadow Hunter Vosh'gajin]] and [[War Master Voone]]. Tazz'Alaor is spread over two levels connected by an extensive ramp system, the lowest of which form the very floor of the spire tunnels. The trapped goblin [[Bijou]] can also be found here, hiding behind a rock outcropping on the upper level.",},
			["TBC"] = { content = "#REDIRECT [[World of Warcraft: The Burning Crusade]]", redirect = "World of Warcraft: The Burning Crusade",},
			["Tbelle's RP Guide"] = { content = "#REDIRECT [[Guide to roleplaying]]", redirect = "Guide to roleplaying",},
			["TCG"] = { content = "#REDIRECT [[World of Warcraft Trading Card Game]]", redirect = "World of Warcraft Trading Card Game",},
			["TCG Burning Crusade Promo"] = { content = "A promo set released with the [[World of Warcraft: The Burning Crusade Collector's Edition|Burning Crusade Collector's Edition]].\r\n===Card Totals===\r\nTotal Cards: 3 \r\n* 0 <font color=#FFFFFF>commons</font>\r\n* 0 <font color=#00CC00>uncommons</font>\r\n* 3 <font color=#3333CC>Rares</font>\r\n* 0 <font color=#CC00CC>Epics</font>\r\n* 2 Heroes\r\n* 1 Quests\r\n* 0 <font color=#FF0000>Loot</font> Cards\r\n* 0 Oversized Heroes\r\n===Numbering===\r\nThe numbering is based on a priority of:\r\n# Heroes\r\n## Alliance\r\n## Horde\r\n# Quests\r\n===Heroes===",},
			["TCG Crafting Redemption"] = { content = "The Crafting Redemption Program that allows players to accumulate crafting materials from booster packs from the World of Warcraft TCG and turn them in for special cards.\r\n==Trade Goods==\r\n* Cobra Scales\r\n* Felsteel Bar\r\n* Heavy Knothide Leather\r\n* Nether Dragonscales\r\n* Primal Air\r\n* Primal Earth\r\n* Primal Fire\r\n* Primal Mana\r\n* Primal Nether\r\n* Primal Shadow\r\n* Primal Water\r\n* Shadowcloth\r\n==Items==\r\n* Black Felsteel Bracers\r\n* Cobrascale Hood\r\n* Girdle of Ruination\r\n* Netherdrake Gloves\r\n* Felsteel Reaper\r\n* Bracers of the Green Fortress\r\n* Spellstrike Hood\r\n* Eternium Runed Blade",},
			["Tcha'kaz"] = { content = "'''Tcha'kaz''' can be found in [[Hinterlands|The Hinterlands]] .\r\nTcha'kaz can be tamed by a [[hunter]]. \r\n==Drops == \r\n \r\n0.07% Chance of a [[rare]] drop.\r\n1.54% Chance of an [[Uncommon]] drop.\r\n0.28% Chance of a [[common]] drop.\r\n0.14% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["TeamSpeak"] = { content = "#REDIRECT [[Voice Chat]]", redirect = "Voice Chat",},
			["Teardrop Blood Garnet"] = { content = "==Source==\r\nThis item could be crafted using [[Jewelcrafting]] (300); taught by [[Design: Teardrop Blood Garnet]]. \r\nThis item can be purchased for 1 gold from Dealer Senzik in [[Netherstorm]].",},
			["Teardrop Living Ruby"] = { content = "==Source==\r\nTeardrop Living Ruby is crafted by [[Jewelcrafting|Jewelcrafters]] with a skill level of 350. \r\nThe components are:\r\n*1 [[Living Ruby]]\r\nThe [[design]] is a [[world drop]].\r\n*Design: Teardrop Living Ruby",},
			["Tears of the Goddess"] = { content = "==Source==\r\n'''Tears of the Goddess''' is obtained from [[Tyrande Whisperwind]] in the night elf encampment of [[Hyjal]] and is reusable. It has a 10 second cooldown and persists as long as you don't leave the instance. It will not disappear if you run back from the graveyard. Use this item on your descent after being affected by [[Archimonde]]'s Air Burst ability.",},
			["Tear of the Moons"] = { content = "==Source==\r\nContained in [[General Twinbraid's Strongbox]] in the [[Barrens]].\r\n==Tear of the Moons as a quest objective==\r\nThis item is an objective of The Tear of the Moons.",},
			["Tear of Tilloa"] = { content = "==Source==\r\n'''Tear of Tilloa''' is located in [[Stalvan Mistmantle]]'s garden just outside [[Darkshire]] in [[Duskwood]]. \r\n==As a quest objective==\r\nThis item is an objective of A Noble Brew.",},
			["Technician Zhanaa"] = { content = "'''Technician Zhanaa''' is a level 5 [[quest giver]] located at the [[Crash Site]] in the [[draenei]] starting zone of [[Azuremyst Isle]].\r\nShe starts the following quests:\r\n* Spare Parts\r\n* Travel to Azure Watch\r\nShe also finishes the following quests:\r\n* The Emitter\r\nSee [[List of Azuremyst Isle NPCs]].",},
			["Technological"] = { content = "#redirect [[technology]]", redirect = "technology",},
			["Technology"] = { content = "What is technology? In simplest terms, it is science applied to practical use. Thus, by this definition, a simple can opener is a technological device. A more accurate description is that technology is the system by which an entire society provides for the wants and needs of its population. Technology tends to improve as the demand for it increases. A society might go decades or even centuries without a major advancement before some bright inventor comes up with something that alters the fundamental way things are done. For example, wagon wheels help move heavy loads from place to place, while wheels of stone grind meal into flour. Put notches in a wheel, connect them together, and you have gears that can drive even more complicated devices. All too frequently, war is the primary driver of technological advancements. \r\n[[Technology]] is an art worth talking about! Historians may not always acknowledge the fact, but those who fought on the battlefield understand that the [[Third War]] could not have turned out as it did in the absence of technology. How were troops moved quickly across great distances? What blasted [[gargoyle]]s and [[dragon]]s alike from the skies? How were enemy buildings demolished? Technology relies upon ingenuity, know-how, craft, physical materials - and perhaps not a little disregard for one's safety. (Sudden explosions, unfortunately, are a hazard of the trade.) [[Magic]] messed up the world; technology will take it to grand, new heights.\r\n==Technology==\r\n*[[Alliance technology]]\r\n*[[Chaos energy]]\r\n*[[Clockwork]]\r\n*[[Explosive]]\r\n*[[Horde technology]]\r\n*[[Goblins versus gnomes|Goblins versus Gnomes]]\r\n*[[Gun]]\r\n*[[Mechanical]]\r\n*[[Steam armor]]\r\n*[[Vehicles]]\r\n*[[Phlogiston]]\r\n*[[Oil]]\r\n==Notable Technological weapons==\r\n*[[Dragon Gun]]\r\n*[[Acid Gun]]\r\n*[[Dwarven Reciprocator]]\r\n*[[Explosive Sheep]]\r\n*[[Goblin Fishing Pole]]\r\n*[[Dwarven Fishing Pole]]\r\n*[[Glue Mine]]\r\n*[[Glue Rifle]]\r\n*[[Gnomish Death Ray]]\r\n*[[Goblin Shredder Steamsaw]]\r\n*[[Heat Wand]]\r\n*[[Light Scope]]\r\n*[[Undead Dislocator]]\r\n==Users of Technology==\r\n*[[Ace]]\r\n*[[Bombardier]]\r\n*[[Dwarven Demolition Squad]]\r\n*[[Engineer]]\r\n*[[Gunman]]\r\n*[[Marksman]] ([[Epic marksman|Epic]])\r\n*[[Mortar Team]]\r\n*[[Sapper]] ([[Goblin sapper|Goblin]])\r\n*[[Steam warrior]]\r\n*[[Techno mage]]\r\n*[[Techslayer]]\r\n*[[Tinker]] ([[Epic tinker|Epic]])",},
			["Techno mage"] = { content = "'''Techno mages''' are [[tinker]]ing [[mage]]s that combine the benefits from both [[magic]] and [[technology]] to create wondrous magical devices.\r\nFor years, [[arcane]] [[magic]] users and tinkers looked on each other with disdain. Each group believed that its way of manipulating the world was superior. Mages have history on their side, with 10,000 or more years of practice, and clear proof of their power (both good and evil). Tinkers have the arrogance of the new kid on the block, showing how they can give the common man the power to fly through the skies or go under the sea, while previously only stuck-up mages were able to do those things.\r\nNot surprisingly, few enterprising [[arcanist]]s pick up a wrench and see what they can do with it. The time, energy, and money it takes to make wondrous items compounded with the time, energy and money it takes to make technological items makes imbuing technological items with magic highly impractical. Some do it, of course, and are considered eccentric and spendthrifts.\r\nThe techno mages rose as an answer to this problem. Instead of treating their inventions as mere items, they tended to view the objects as extensions of themselves, using their will to enhance the item temporarily. As they commonly do this in battle, some consider them valuable [[warrior]]s. Others consider them insane. Views of the techno mages are mixed, as tinkers and mages see the class as a perversion of the purity of their own respective paths. Yet no one can deny the power these people wield.\r\nTechno mages are wild-eyed folk, always looking for a shortcut to get what they want. Techno mages are solitary by design (though some gather together at [[the House of the Arcane Contraption]]), as there are few of them and many are put off by their odd pursuit of both technology and magic. They are, however, mind-hungry and have a keen interest to talk to mages or tinkers to see if they can learn new things. And if the tinker or mage is then interested in following the path of the techno mage, even better! They are used to derision, but often too caught up in their latest invention to really care. The life of the techno mage is not for the weak. Most techno mages come from a background of the mage path, although some [[warlock]]s have joined the ranks.\r\nThe techno mage has little patience when it comes to battle. She wishes to go in, hit the enemy with all she has, and have it done with. The techno mage knows how to connect with her technological weapons, channeling her magic through them. Her gun does not shoot bullets, but fireballs or dire rats. The techno mage can, by touch, place any spell she has prepared into a technological weapon. The weapon’s next attack does not consume ammunition or fuel (if applicable). Instead, the weapon attacks with the spell. Note that characters firing (or otherwise employing) a weapon so enhanced do not need to target creatures; one could fire a long rifle containing a frost nova at a spot on the ground, for instance. Wherever the weapon strikes, the spell occurs. If the attack misses, depending on the spell involved, the attack might be wasted or the spell effect might scatter, as a splash weapon. If the techno mage uses this ability on a melee weapon, the weapon can deliver the spell with a physical attack. Note that this ability is not necessarily aggressive. It can carry cure serious wounds and teleport just as easily as starfall.\r\nIf a techno mage has made it this far, she has likely endured many mishaps, both technological and magical. The result of these trials is that she is more likely to be able to withstand damage from some form of energy.\r\nAs the techno mage becomes more and more in tune with her inventions, she can feel them as if they were sentient beings. She can almost communicate with them, telling ammunition and even grenades where to go. When a device breaks, usually from a malfunction, most consider it lost forever, or until a skilled tinker has a good, long, expensive look at it. The techno mage can touch a device and coax it into one last use, putting some of her energy into it to keep it together. A skilled techno mage can truly feel the machines she touches. She can put her consciousness into a machine, [[vehicle]] or suit of [[steam armor]] and command it to move as if she were inside it. She controls the device completely. She is often able to force a device to do things of which it is otherwise incapable, since her mind controls it directly. While controlling a device in this manner, the techno mage’s body is in a trance-like state, and she is unaware of her surroundings.\r\n==Notable Techno Mages==\r\n*[[Allavan]]\r\n*Angus Sootbeard\r\n*Mogul Razdunk\r\n*Han'al\r\n*Neevil\r\n*Brymidaine Zecker (presumed)\r\n*[[Blamblaster]]\r\n*Grimm Onearm\r\n*Fanala Bridkind\r\n*Mememgem",},
			["Techslayer"] = { content = "Some nay-sayers do not appreciate the slow spread of [[technology]]. They see this new science as inherently destructive, and believe that left unchecked, technology will eventually lay waste to [[Azeroth]]. The actions of certain groups, such as the [[Venture Company]], are clear evidence of this. While some use [[magic]] or other means to halt the use of destructive technology, a chosen few use its own power against it. These '''techslayers''' study and learn what they can about technology, then use that knowledge to keep it in check.\r\nTechslayers are often misunderstood. They do not hate science, only science used for evil purposes. Techslayers are adept at the use of technology, but they use their abilities to build, nurture, and protect - and, of course, stamp out destructive tech wherever they find it.\r\nThe techslayer knows how to strike at constructs for maximum efficiency, to get around the defenses provided by armor, and to penetrate a construct’s inherent defenses. A skilled techslayer understands technological devices so well that he can shut them down with a single well-placed blow, the device cannot be reactivated until this damage is repaired. A higly skilled techslayer has achieved the pinnacle of his abilities, and is adept at destroying technological devices and constructs of all sorts.\r\n==Techslayers in the world==\r\nAll techslayers have first-hand experience with the destructive power of science. Perhaps they've seen a forest torn asunder by mechanical cutters, or been the victim of an avalanche caused by explosive mining techniques. Regardless of the reason, this event created a lasting impression - technology, like fire, must be properly harnessed lest it get out of control.\r\nTechslayers often come from backgrounds that take them close to nature. [[Druid]]s and [[shaman]], for example, sometimes take up the techslayer's path. The [[Horde]] employs far more techslayers than the [[Alliance]], primarily because technology has achieved a lower level of acceptance within the Horde's ranks.\r\nOne of the techslayer's primary motivations is to eliminate the chaos created by rampant, uncontrolled science.\r\n==Famous/Named==\r\n*[[Datein]]",},
			["Teg Dawnstrider"] = { content = "'''Teg Dawnstrider''' is a level 35 [[artisan]] [[enchanting trainer]] located on [[Middle Rise]] in the [[tauren]] city of [[Thunder Bluff]].\r\nSee [[List of Thunder Bluff NPCs]].",},
			["Tel'athion's Camp"] = { content = "'''Tel'athion's Camp''' is a small, abandoned camp in northwestern [[Bloodmyst Isle]].",},
			["Telaar"] = { content = "'''Telaar''' is the [[Kurenai]]-factioned [[Alliance]] town in southern [[Nagrand]]. The flight point is at 54,75, on top of the inn. It is accessed via exterior ramps on either side of the building.\r\nTelaar is full of [[draenei]], both of normal and [[Broken]] versions. There are plenty of quests to be had, goods to be bought, and things to see. The [[Kurenai]] quartermaster is here, as is a [[stable master]] and a mailbox, in addition to the [[flight master]] and [[inn]] mentioned above.\r\n===Flight===\r\n [[Telredor]]\r\n [[Allerian Stronghold]]\r\n [[Shattrath City]]\r\n==Telaar NPCs==\r\n* Furgu\r\n* Luftasia\r\n===Vendors===\r\n* Trader Narasu\r\n* Caregiver Isel\r\n* Borto\r\n* Sparik\r\n* Ogir\r\n* Nancila\r\n* Uriku\r\n===Quest Givers===\r\n* Huntress Bintook\r\n* Poli'lukluk the Wiser\r\n* Mo'mor the Breaker\r\n* Otonbu the Sage\r\n* Seer Jovar\r\n* Arechron\r\n* Elementalist Ioki\r\n* \"Shotgun\" Jones\r\n* Warden Moi'bff Jill\r\n* Nahuud\r\n* Consortium Recruiter\r\n* Interrogator Khan\r\nQuests are also available from the Telaar Bulletin Board, next to Warden Moi'bff Jill.\r\n==Flightpaths==\r\nPlayers can fly from here to:\r\n*[[Telredor]], [[Zangarmarsh]]\r\n*[[Shattrath City]], [[Terokkar Forest]]\r\n*[[Allerian Stronghold]], [[Terokkar Forest]]",},
			["Telaari Basin"] = { content = "'''Telaari Basin''' is a deep cleft located north of [[Telaar]] in southern central [[Nagrand]]. It is populated by [[earth elemental]]s and the occasional [[Windroc]].\r\n[[Telaari Frond]]s (used in the Horde Greatmother chain) can be found in this area.",},
			["Telaari Frond"] = { content = "==Source==\r\nThe '''Telaari Frond''' can be found in [[Nagrand]].",},
			["Teldrassil"] = { content = "'''Teldrassil''' (meaning \"Crown of the Earth\" in [[Darnassian]], and pronounced ''TELL-druh-sill'') was a [[World Tree]] situated on the eponymous island off [[Kalimdor]]'s northwestern coast. Created shortly after the [[Third War]] by the [[night elf|night elves]], Teldrassil served as their home and primary base of operations, its thick crown housing the capital city of [[Darnassus]]. Other major settlements on the tree included [[Rut'theran Village]], [[Dolanaar]] and [[Shadowglen]]. Owing to its size, Teldrassil possessed its own unique ecosystem with a various flora, fauna, and vast twilit forests.\r\nAccording to [[Broll Bearmantle]], as a World Tree, Teldrassil was linked to the very health of Azeroth, affecting not merely its immediate surroudings, but those lands beyond the island, and a Teldrassil that was not well could not properly maintain the balance between nature and decay. The new tree was not blessed by the [[Dragon Aspect]]s at its birth, unlike its predecessor [[Nordrassil]], which would ultimately leave it vulnerable to corruption from the [[Emerald Nightmare]]. However, just before the [[Cataclysm (event)|Cataclysm]], it would receive the blessings of [[Alexstrasza]] and [[Ysera]]. All known lingering corruption was finally purged during the Cataclysm.\r\nTeldrassil served as the largest bastion of [[Alliance]] power in [[Kalimdor]], and maintained naval connections to the mainland, the nearby [[Azuremyst Isles]], and the distant [[Eastern Kingdoms]]. Many young and ambitious night elves began their journey out into the world from the verdant shelter of the World Tree. During the [[War of the Thorns]]—roughly a decade after its creation—Teldrassil was burned down by the [[Horde]] under the orders of [[Warchief]] [[Sylvanas Windrunner]], killing many of the night elves dwelling in it.\r\n===Birth===\r\nAfter the cataclysmic events of the [[Third War|second invasion]] of the [[Burning Legion]], [[Malfurion Stormrage]] became trapped in the [[Emerald Dream]]. In Malfurion's absence, Archdruid [[Fandral Staghelm]] took over leadership of the night elven druids, and convinced the [[Circle of the Ancients]] in [[Darkshore]] that it was time for the night elves to create a new World Tree and regain their immortality.\r\nThe Circle of the Ancients and the wise [[druid]]s led by Fandral combined their powers to grow an immense tree in the [[Veiled Sea]]. They called the tree Teldrassil, meaning \"crown of the earth\" in [[Darnassian]]. The night elves made their new home of [[Darnassus]] in the boughs of Teldrassil, creating a forest of mighty trees and flowing rivers, bathed in the endless night that fell over the lands of the elves from the dawn of time. However, the tree did not restore the night elves' immortality; [[Nozdormu]], whose blessing on [[Nordrassil]] had been the source of their immortality, saw the night elves' wish as arrogant and refused to bless Teldrassil.\r\n===World of Warcraft===\r\nOver time, the land atop Teldrassil fell into the shadow of a sinister presence. Local creatures such as [[furbolg]]s and [[grell]] went mad, and [[satyr]]s appeared, intent on further corrupting the land. [[Giant turtle]]s and [[thresher]]s known to inhabit the waters surrounding Teldrassil began fleeing the tree to beach themselves and die on [[Darkshore]]. The source of this corruption remained a mystery for some time until the conflict of the [[Emerald Nightmare]] spilled into the waking world.\r\nDuring the [[Scourge Invasion]], Teldrassil was attacked by the [[Scourge]].\r\n===Stormrage===\r\nAfter Malfurion was freed from the Emerald Nightmare, he flew to Darnassus, and discovered that a remnant of a great evil had been grafted into Teldrassil by Fandral. By grafting [[Xavius]]' [[fel]]-tainted branch into Teldrassil, Fandral had given Xavius, as well as the evil behind his transformation into the Nightmare Lord, a tie to both [[Azeroth]] and the [[Emerald Dream]].\r\nMalfurion managed to remove the corrupt branch and eventually restore the tree to a state closer to what it originally should have been. [[Alexstrasza]], impressed that the tree could prosper alone without her influence or her kin's, blessed it belatedly. She later blessed it again, along with [[Ysera]] this time, during the wedding of Malfurion and [[Tyrande Whisperwind]]—a blessing which protected Teldrassil to its final day. The tree flourished even more under the gifts from the Life-Binder and the Dreamer, though it still cannot return the night elves' immortality without a blessing from [[Nozdormu]].\r\n==Geography==\r\nThe majority of Teldrassil's upper reaches resembles a mid-sized forested island. [[Darnassus]] occupies a large chunk on the western side of this tree-island, while the towns of [[Aldrassil]] and [[Dolanaar]] dot the remaining forest. All forms of terrain exist here, including streams, lakes, hills, and mountains. The waterways were created and continue to be fed by the dew collected by the massive World Tree, and the night elves manipulated the waterways around Darnassus to maintain the splendor of the [[Temple Gardens]].\r\nThe entire [[zone]] of Teldrassil is, in fact, one huge tree, grown on an island off the coast of [[Kalimdor]]. As such, there are no [[ore]] deposits here and the night elves are not known as crafty [[blacksmith]]s or [[miner]]s. However, because the tree is so full of life, [[herb]]s are numerous.\r\nTeldrassil contains no [[dungeon]]s, [[raid dungeon]]s, [[micro dungeon]]s, or [[battleground]]s. It is the starting area for the [[night elf|night elves]] and contains a very sheltered 1-5 leveling area, [[Shadowglen]]. The night elf [[capital city]] of [[Darnassus]] can also be found in this zone, though the travel hub is actually located at [[Rut'theran Village]] (accessible by portal from Darnassus).\r\nAt the tree's base, there are some pieces of wooded land between its roots, one of which has an abandoned furbolg house on it, as well as [[Rut'theran Village]].\r\nAlthough Teldrassil is only the size of a mid-sized island in width, its sheer height dwarfs many other islands.\r\n===Travel hubs===\r\n[[Rut'theran Village]] is connected to [[Darnassus]] by a [[portal]]. Players can also reach Rut'theran Village by [[Transportation|boat]] from [[Stormwind]] or [[Valaar's Berth]].\r\nThis is also the only way for Horde players below level 60 to get to the island by themselves. One can attempt swimming from Darkshore using [[Swim Speed Potion]]s and health potions, but this is not recommended.\r\n==== [[Flight path]]s from [[Dolanaar]]====\r\n*[[Darnassus]], Teldrassil\r\n==== [[Flight path]]s from [[Darnassus]]====\r\n*[[Dolanaar]], Teldrassil\r\n*[[Rut'theran Village]], Teldrassil\r\n==== [[Flight path]]s from [[Rut'theran Village]]====\r\n*[[Darnassus]], Teldrassil\r\n*[[Lor'danel]], [[Darkshore]]\r\n*[[The Exodar]], [[Azuremyst Isle]] \r\n==== [[boat|Boat destinations]] from [[Rut'theran Village]]====\r\n*[[Stormwind]], [[Elwynn Forest]]\r\n*[[Valaar's Berth]], [[Azuremyst Isle]] \r\n==Notable characters==\r\nTeldrassil is home to several night elves of status. From the top of the tree [[Aldrassil]], [[Tenaron Stormgrip]] sends promising young elves out into the outside world. In [[Dolanaar]], [[Tallonkai Swiftroot]] leads the effort to fight back the corrupted furbolgs and satyr of the Great Tree, while in his small tent near [[Lake Al'Ameth]], [[Denalan]] seeks to understand the nature of the strange affliction seeping into Teldrassil.\r\n===Chapter 1: Shadowglen===\r\nThe night elf hero began their quest in [[Shadowglen]]. The instructor [[Ilthalaine]] introduced himself and impressed upon the hero the importance of balance in nature. The spring rains led to an overpopulation of nightsabers in the surrounding area and Ilthalaine politely asked the hero to cull them a bit. Upon returning, the hero overheard Ilthalaine telling [[Huntress Sandrya Moonfall]] and [[Dentaria Silverglade]] that there were no new recruits ready yet. Without giving more details, Sandrya warned him that they were running out of time—a battle was fast approaching the roots of Teldrassil. Dentaria left Ilthalaine to his work and turned to the hero, telling them that their help in battle would be needed soon. Ilthalaine then sent the hero to collect fel moss from [[grell]]kin nearby, concerned that there is still lingering corruption within Teldrassil. The hero's return with the fel moss confirmed Ilthalaine's fears—there was still corruption within Teldrassil. Ilthalaine concluded that the hero was now ready to join the fight and sent them to their class trainer for further instruction.\r\nAfter learning a few new abilities, the hero's trainer directed them to assist Dentaria Silverglade to the north of [[Aldrassil]]. Dentaria was pleased to see the new hero had progressed so quickly through their training and was ready to get to work.\r\nDentaria asked the hero to gather rare flowers to help her cure their friend [[Iverron]] from the venom of the webwood spiders. While Iverron recuperated, Dentaria asked the hero to make contact with the dryad [[Tarindrella]] north of Aldrassil to investigate the spider threat. Tarindrella confirmed that the spiders still suffered from corruption—and further, were more susceptible to it than other wildlife on Teldrassil. She and the hero slew a great many of them and in doing this they discovered that the corruption was not the result of mind control or some other effect—it was due to the corruption of their broodmother [[Githyiss the Vile]]. Upon killing Githyiss, they discovered a furbolg totem—the [[Gnarlpine]] had installed a totem to corrupt the broodmother and her offspring that they would attack the nearby night elf settlements. Tarindrella brought the hero back to Dentaria to complete their training and departed to further investigate the source of the Gnarlpine corruption.\r\nDentaria sent the hero on a final mission to complete their training—learning some of the recent events in night elves' history. A ritual at the nearby moonwell helped the hero recall the recent events confronting their people—the [[Battle of Mount Hyjal]] in which the Burning Legion was defeated but night elves lost their immortality, the release of [[Illidan Stormrage]] from his prison and the disappearance of [[Malfurion Stormrage]] to the [[Emerald Dream]]. The ritual complete, Dentaria sent the hero to [[Tenaron Stormgrip]] with a vial of the waters of the moonwell—evidence that their training was completed. Tenaron agreed it was time for the hero to move on from basic training and begin addressing the issues of their people. Tenaron sent the hero on to [[Corithras Moonrage]] in [[Dolanaar]].\r\n===Chapter 2: Council of the Forest===\r\nOn the way to Dolanaar, the hero met the [[satyr]] [[Zenn Foulhoof]] who promised them \"things you never dreamed of having\" in return to a variety of \"reagents\" culled from the corpses of forest dwellers. When the hero returned with the items, Zenn revealed that they had been tricked and thanked the hero for being so gullible.\r\nUpon arriving in Dolanaar, the hero was admonished by [[Sentinel Kyra Starsong]], [[Syral Bladeleaf]] and [[Sentinel Shayla Nightbreeze]] who told them that their actions aiding Foulhoof had offended the [[Council of the Forest]] and demanded that the hero acquire some corrupted seeds to play a trick on Foulhoof to be redeemed. The hero collected the seeds and Zenn gobbled them up without hesitation. The ruse worked, and within moments Zenn was turned into a frog.\r\nThe success of the trick redeemed the hero in the eyes of the Council, which then asked the hero to attack [[Fel Rock]] which had been taken over by a small army of corrupted grellkin. Syral Bladeleaf asked the hero to purge the army while [[Tallonkai Swiftroot]] had a more specific target in mind—the satyr [[Lord Melenas]] who had marshalled them together. When the hero returned with Melenas' head the Council's agents thanked them and returned to their normal duties.\r\n===Sidestory: Reminders of Home===\r\nWhile in Dolanaar, a cooking supplies vendor [[Nyoma]] asked the hero to bring a recipe book to her friend [[Sister Aquinne]], who is studying to become a [[Priestess of the Moon]] in [[Darnassus]]. Nyoma told the hero the easiest route to the capital would be to fly by [[hippogryph]] which they could arrange via the local [[flight master]] [[Fidelio]]. Fidelio told the hero that everyone in Dolanaar is so proud of Aquinne's devotion to [[Elune]] and gives the hero a suggestion of where they might find her in the city before sending the hero on their way. When the hero delivered the book Aquinne was ecstatic and promised to use it that very evening. Aquinne wrote a thank-you note and asked the hero to deliver it back to Nyoma. [[Leora]], the flight master in Darnassus, explained to the hero the importance of meeting the flight master whenever they reach a new place so that they might arrange easy travel back there in the future. The hero then delivered the letter to Nyoma, who thanked the hero and lamented she hasn't had the opportunity yet to visit Aquinne in person yet.\r\n===Chapter 3: Starbreeze Village===\r\n[[Athridas Bearmantle]] in Dolanaar informed the hero of a troubling development. The warden of the nearby [[Ban'ethil Barrow Den]]--[[Gaerolas Talvethren]]—has not reported to him recently. Athridas asked the hero to investigate. Before the hero departed, Tallonkai asked the hero for another favor. He explained that he used to live in Starbreeze and when he left because of the increasing Gnarlpine activity, he left behind a good-luck charm, an emerald dreamcatcher which he had received from Gaerolas. The hero agreed to retrieve the amulet.\r\nThe hero arrived in Starbreeze to find the village ransacked by the Gnarlpine. Gaerolas was found mortally wounded by the furbolgs and pleaded with the hero to notify Athridas before the furbolgs could reach the barrow den as he would be unable to make it back. He identified their leader: [[Ursal the Mauler]]. The hero returned to Dolanaar after retrieving the Tallonkai's amulet and delivered the disturbing news to Athridas.\r\nWhen the hero presented the amulet to him, Tallonkai noticed immediately it was missing its emerald. He surmises that the Gnarlpine mystic [[Ferocitas the Dream Eater]] must have it, and asks the hero to slay the furbolg to retrieve the gem on their next trip to Starbreeze. The hero agreed and returned with the gem.\r\nAthridas warned the hero that the druids sleeping in the Ban'ethil Barrow Den would be forever trapped in the Emerald Dream if their physical bodies were to be killed while they are asleep. The hero set out to retrieve the tools necessary to peacefully break wake them so that they could flee safely. While collecting the items from the Barrow Den, the hero was attacked by the body of [[Oben Rageclaw]], which the Gnarlpine had found a way to animate and use to attack intruders. The hero assisted Oben's spirit in determining how the Gnarlpine had done this and ultimately at Oben's request the hero slew his physical body.\r\nWhen the hero returned to Athridas with the items, Athridas sent them to kill Ursal, the last remaining obstacle to saving the druids. With Ursal dead, Athridas was able to complete the ritual and the druids escaped safely.\r\n===Chapter 4: Lake Al'Ameth===\r\nSyral Bladeleaf notified the hero that package had arrived for [[Denalan]], an herbalist with a camp near [[Lake Al'Ameth]] to the south and asked them to deliver it. Denalan thanked the hero for the package and asked for the hero's help investigating why the [[timberling]]s were becoming so violent when the healing of the world tree should have pacified them. The champion set out to collect timberling seeds and sprouts for Denalan's experiment to find the cause.\r\nDenalan asked the hero to bring one of the specimens to his colleague [[Rellian Greenspyre]] to help the druid with his own efforts to purge the timberlings' corruption. Rellian thanked the hero for the seed but lamented that it was likely beyond his skill. The timberlings near [[Wellspring Lake]] to the north were the most corrupted in particular, and Rellian sent the hero to slay them and collect their mossy tumors so that they may be burned. Denalan suddenly arrived with important news: he had discovered that the corruption stemmed from [[Oakenscowl]], a large timberling who had the largest tumor of all. The hero slew Oakenscowl and returned the gargantuan tumor to Denalan and Rellian for study.\r\n===Chapter 5: The Vengeance of Elune===\r\nCorithas Moonrage, after observing the hero's growing power and understanding, instructed the hero to visit the moonwell under the [[Oracle Tree]] for another vision. At the moonwell, the hero learned of Archdruid [[Fandral Staghelm]], the leader of the [[Cenarion Circle]] and the most powerful druid in Azeroth after Malfurion and the reverence he is due in spite of his conflicts with [[Tyrande Whisperwind]]. After viewing this, Corithas sent the hero to a final moonwell to rendevous with Tarindrella for another attack against the corruption of Teldrassil. On approaching the moonwell, the hero saw a final vision about the most recent events—Archdruid Staghelm and his closest followers have left the Night Elf society without a word, but Malfurion has awoken from the Emerald Dream and reunited with Tyrande. [[Alexstrasza]] and [[Ysera]] have finally provided their blessings to Teldrassil, allowing the tree to begin to grow properly. Hope for a better future dawns anew for the Kaldorei.\r\nAfter the vision, Tarindrella informed the hero that she has located the source of the corruption near the tree's edge. She provided the hero with a blessing using the collected power of the moonwells that allowed the hero to destroy the [[Bough of Corruption]]. With the source of the corruption destroyed, Tarindrella sent the hero to return it to Corithas, who in turn directed the hero to bring it to Tyrande. Tyrande explained that the disappearance of Staghelm is worrisome but Malfurion's return has given her hope in spite of the dark days ahead.\r\n==Resources==\r\n*[[Cloth]]:\r\n**[[Linen Cloth]]\r\n*[[Herb]]s:\r\n**[[Peacebloom]]\r\n**[[Silverleaf]]\r\n**[[Earthroot]]\r\n**[[Mageroyal]]\r\n**[[Swiftthistle]]\r\n*[[Leather]]:\r\n**[[Ruined Leather Scraps]]\r\n**[[Light Leather]]\r\n==Wild creatures==\r\n*[[Beast]]s:\r\n**[[Boar]]s\r\n**[[Nightsaber]]s\r\n**[[Owl]]s\r\n**[[Tarantula]]s\r\n*[[Humanoid]]s:\r\n**[[Timberling]]s\r\n**[[Satyr]]s\r\n**[[Worgen]]\r\n**[[Furbolg]]s\r\n**[[Grell]]s\r\n**[[Harpy|Harpies]]\r\n==In Cataclysm==\r\nTeldrassil has been moved closer to Darkshore, and Rut'theran Village has been ripped from the side of the tree and is now an island.\r\nWith the [[Flight Master's License]] implemented, it is now trivial for any level 60 Horde and up to bypass both Rut'theran Village and Darnassus by flying up the side of Teldrassil. With Teldrassil's shifting of location, it is also possible to use a flying mount with [[Riding|Expert Riding]] to fly across the [[Fatigue|deep water]] separating Rut'theran Village and the mainland of Darkshore.\r\nAreas affected:\r\n*[[Dolanaar]] – flight path added\r\n*[[Gnarlpine Hold]] – filled with corrupted mobs that swarm down the hill towards the Pools to fight the ancients\r\n*[[Lake Al'Ameth]] – [[Strange Fruited Plant]] from Gnarlpine Hold has been moved here\r\n*[[Rut'theran Village]] – half destroyed; boat to [[Stormwind City]] sails from here\r\n*[[Shadowglen]] – target dummies and mailbox added\r\n*Other – both [[Denalan]] and [[Rellian Greenspyre]] appear to exist in two places at once – where the Skinning/LW trainers are there is a place where both of them are together - this is likely due to Blizzard's desire to cut down on some quests' travel time\r\n==Kalidar==\r\n'''Kalidar''' was the name [[Blizzard Entertainment|Blizzard]] had originally used on their preview website as well as on several concept maps and in the ''World of Warcraft DVD'' for the island off the northwestern coast of Kalimdor where Teldrassil was grown. The night elves moved their capital to this island. The [[Circle of the Ancients]] and the wise druids pooled their power to create a [[World Tree]] which eventually outgrew the island and the night elves built the city of [[Darnassus]] atop it. The island now takes the name of the tree as well, and a twilit forest covers it.\r\nAn unreleased quest by [[Sentinel Shayla Nightbreeze|Shayla Nightbreeze]] referenced Kalidar. Further, most of the objects seen on Teldrassil (trees, bridges, etc) are all labeled as \"kalidar\" in the game files.\r\n===Official website===\r\nTaken directly from the official site:\r\n''Kalidar, the new home of the reclusive [[Night elf|Night Elves]] and a stunning testament to the power of their magic and their connection with nature. After the cataclysmic events that followed the invasion of the [[Burning Legion]], the [[Circle of Ancients]] and powerful [[druid]]s combined their powers to grow an immense new world tree on Kalidar. They called the tree Teldrassil, meaning \"crown of the earth\" in their native tongue. The night elves made their new home in the boughs of Teldrassil, creating a forest of mighty trees and flowing rivers, bathed in the endless night that fell over the lands of the elves from the dawn of time. However, the calm of the enchanted forest has slowly fallen into the shadow of a sinister presence. Crazed [[furbolg]]s and fouler beasts have appeared in Kalidar, and it occupies all the attention of the vigilant [[Sentinels]] and the wise druids to ensure the safety of their new home.''\r\n''A sprawling city of moonstone and wood, the night elf capital of Darnassus stands as a shining beacon atop Kalidar. Within its mighty walls are housed countless druids, hunters, and warriors, led by the priestess of [[Elune]], [[Tyrande Whisperwind]]. A stunning marvel to the ability of night elven craftsmen, the ethereal [[Temple of the Moon]] rises above the tree line, balanced by the druids' meticulously cultivated meditative grove. Trade from the main continent bustles through the city's trade quarter, where night elves, [[Dwarf|dwarves]] and [[human]]s alike haggle for wares and services. Delicate bridges and pathways crisscross the serene waterways of the city, the pristine waters reflecting the glowing light from the moons above.''\r\n===Development=== \r\n*It is possible that the backstory of the island originally being called \"Kalidar\" was later dropped, since the European townhall was updated to have all references to \"Kalidar\" replaced with the word \"Teldrassil\", while the US townhall had been taken down.\r\n**Latter sources like the ''[[Wolfheart]]'' novel and the ''[[Ultimate Visual Guide]]'' refer to the island as Teldrassil.\r\n*There exists unused files for a \"[[Kalidar (battleground)|Kalidar]]\" [[battleground]] map.\r\n===History===\r\nEven though [[Nordrassil]] was healing, it would take another century or two for the World Tree to regain its former glory and power. Unreconciled with their loss of immortality, a splinter group of [[druid]]s led by [[Fandral Staghelm]] were planning to create a second World Tree.\r\n[[Malfurion Stormrage]] entered a deep coma, and sleeps in his base at [[Moonglade]]. No one knows why, and no one knows how to wake him. His absence leaves control of the druids to [[Fandral Staghelm]], who has become the new [[archdruid]]. Before his coma, Malfurion opposed Fandral's plan to grow a new World Tree. After Malfurion fell into his coma, Fandral met with the other druids and, without Malfurion to argue against him, convinced them of the wisdom of creating a new World Tree, and them, most believing that Fandral was right about the tree, created Teldrassil, and erected a new capital in its branches. Despite a widespread distrust of Teldrassil and Fandral, the city of Darnassus remains the focal point of night elf culture and life.\r\nRealizing they needed help to survive in this new world and to oppose the [[Horde]], which chose their continent as its new home, the night elves reluctantly joined the [[Alliance]]. Commerce began between [[Theramore]] and the night elves, as the two cultures shared values and ideas. The night elves remained withdrawn, however. There are still many places considered too sacred for dwarves or humans to venture into, and only when they’re drunk do they really loosen up around other Alliance races.\r\nIn Darnassus the atmosphere is a bit strange; there's a mix between carefree, joyful elves and grim citizens with suspicions similar to those of the [[druid]]s in [[Moonglade]]. The druids and [[priest]]s of [[Elune]] here are keenly aware that the tree is being corrupted, and both sides try their best to combat the effects with minimal success. More interestingly — and perhaps more dangerously — the druids and the priests are beginning to blame each other for the mess.\r\nA few of the non-elves here (a few [[human]] [[paladin]]s and two [[Dwarf|dwarves]] from the [[Explorer's Guild]]) can give you an outsider's perspective, and you can get a pretty blunt summary: Archdruid Fandral Staghelm hates [[Tyrande Whisperwind]]'s guts. At least, things certainly seem that way. The archdruid questions High Priestess Whisperwind's leadership abilities, and that causes strife in the community. Tyrande was the companion to Malfurion Stormrage, the greatest of all druids, and many elves see the rift between their orders as both shocking and appalling. The situation hasn't reached the point where people choose sides, but things could get there, and that could turn real ugly real fast. The dwarves there suggest someone needs to wake up Malfurion before circumstances get messy. With an unstable political climate and the growing corruption of the World Tree, danger lurks within Teldrassil.\r\nThe World Tree's decay begins to accelerate, and the [[Cenarion Circle]] is unable to find the source. Rather than continue to explore the slow destruction of the tree, the druids finally agreed with the priests of Elune that they need outside help. They sent champions to find the only beings who may be able to save the World Tree — the [[Dragon Aspects]]. If the champions could gain the blessing of even a single Aspect, the corruption could halt for a time — perhaps forever. With the blessing of more than one Aspect it could reverse the damage that had already been caused.\r\n===Geography===\r\nThe majority of Teldrassil's upper reaches is open forest, and it resembles a mid-sized forested island. Darnassus takes up a large chunk on the western side of this island, and smaller cities dot the remaining forest. All forms of terrain exist here, including streams, full-sized lakes, and a few hills that non-dwarves might consider mountains.\r\n===RPG notes===\r\n*It has been described in the RPG as a both an \"island continent\" and simply an island.\r\n==Notes and trivia==\r\n*The Horde version of the [[Darkshore Drilling (Horde)|Darkshore Drilling]] War Campaign mission mentions night elves \"streaming out of Darnassus\" and posing a threat to [[Shatterspear Vale]], despite it having been burned with Teldrassil. The mission is either supposed to take place during the [[War of the Thorns]] despite being unlocked later, or is a mistake since the [[Darkshore Drilling (Alliance)|Alliance version]] takes place after the war.\r\n*A [[:File:Teldrassil.jpeg|piece of concept art]] in ''[[The Art of World of Warcraft]]'' was originally labeled as '''ldrassil''', seemingly a typo for Teldrassil. The same picture was later properly labeled as Teldrassil in ''[[Ultimate Visual Guide]]''.\r\n*While Teldrassil looks like a stump in ''World of Warcraft'', this is due to engine limitations. Artwork such as ''[[World of Warcraft: The Comic|The Comic]]'' and [[:File:Teldrassilmovie.jpg|concept art for the ''Warcraft'' film]], as well as the tree's appearance after the Burning of Teldrassil, show that it's canonically a whole tree. [[Chris Metzen]] wanted this to be reflected in the zone in classic ''World of Warcraft'', but the developers were unable to make a gigantic 3-dimensional tree work with the technology at the time due to the game engine being based completely off height-mapping, which heavily limits terrain possibilities. This led to the zone's in-game state, which is essentially a flat area located atop a huge pillar with branches sticking out of the side. Metzen was greatly disappointed by this; as a compromise, a [[Aldrassil|smaller giant tree]] was included in the zone.\r\n*According to the ''[[World of Warcraft: Game Manual]]'', the corruption of Teldrassil was of Burning Legion origin, but other sources state that the tree was corrupted by both the Emerald Nightmare and the demons.\r\n*[[Pine Nut Bread]] is often formed into the shape of a leaf to honor Teldrassil.\r\n*Prior to ''[[World of Warcraft: Cataclysm|Cataclysm]]'', the only way for Horde players to get to Teldrassil was via ship from [[Auberdine]].\r\n*As is the case with all of the other [[World Tree]]s, the suffix \"-drassil\" comes from , the world tree, in Norse mythology.\r\n*After the Burning of Teldrassil, it was originally impossible to approach the tree's remains in-game due to an invisible wall. It is now possible to approach the stump far enough to get your stamina back after passing through [[Fatigue]] waters, but getting very near will cause the player to be teleported back to the beach next to [[Lor'danel]].\r\n===Kalidar===\r\nFrom the official site\r\nOthers",},
			["Teldrassil Pink Elekk"] = { content = "'''Teldrassil Pink Elekk''' are see-through, pink [[Elekk]] that can be found in [[Darnassus]] and [[Shattrath City]] during [[Brewfest]]. They can only be seen when you are drunk. They were previously part of the [[quest]]s Pink Elekks On Parade and Pink Elekks On Parade, but the [[quest]]s were removed from the game in [[Brewfest]] 2008.",},
			["Teldrassil questing guide"] = { content = "This '''questing guide for the zone of Teldrassil''' details the best method to obtain and complete quests in [[Teldrassil]].\r\nFor a list of all [[Teldrassil]] quests in table format (arranged by level), see [[Teldrassil quests]]\r\n '''Note''': This guide is not meant for power-leveling purposes. Rather, it is meant to show a player the most efficient way to complete all quests available for a particular zone. If you know of a better order or method to accomplish this, your input is welcome (in fact, greatly desired). For major changes, feel free to edit, but make a note in the '''[[Talk:Teldrassil questing guide|talk page]]''' as to your reasoning.\r\n== Shadowglen (LVL 1-5)==\r\n''See Also: [[Powerlevel Shadowglen]]\r\n[[Shadowglen]] is the starting zone for new [[night elves]], and is located in north eastern part of [[Teldrassil]]. Other races may choose to quest here, but not all quests are available to them. If you are new to the game, check out the [[Newbie Guide]] to get started, or just dive in - the game has in-game hints and the opening quests are very straight-forward, just relax and have fun!\r\n===First Steps===\r\n*Begin by talking to the first [[night elf]] you see, [[Conservator Ilthalaine]], to get the quest The Balance of Nature.\r\n*Kill 4 [[Young Thistle Boar]]s and 7 [[Young Nightsaber]]s, which should be wandering around you.\r\n*Return to Ilthalaine and turn in the quest. Then get The Balance of Nature (2) and your class quest.\r\n*Head to the tree and find your class trainer to receive your first training. Also pick up the following quests from in and around the tree:\r\n**The Woodland Protector from Melithar Staghelm\r\n**A Good Friend from Dirania Silvershine\r\n===Nature Tainted===\r\n*Head south of the tree to find the dryad [[Tarindrella]]. Turn in The Woodland Protector to her and get the next quest in that chain.\r\n*Begin killing [[Grell]] and [[Grellkin]] while moving towards the northwest corner of [[Shadowglen]]. Don't stop at the camps since there are plenty to kill along the way to our destination: [[Iverron]], the objective of A Good Friend.\r\n*Halfway to [[Iverron]], you will start encountering different mobs, [[Thistle Boar]]s, and [[Mangy Nightsaber]]s. Kill any you see for the quest The Balance of Nature (2).\r\n*When you arrive at [[Iverron]], turn in A Good Friend and accept A Friend in Need.\r\n*Run back the way you came. If you haven't, finish collecting Fel Moss from the Grell and Grellkin before you get to Tarindrella. Turn in The Woodland Protector (2) when you reach the dryad.\r\n*Head to [[Dirania Silvershine]] next to the Cauldron to the northeast, turn in A Friend in Need, and accept Iverron's Antidote.\r\n*Pick up the quest Webwood Venom from [[Gilshalan Windwalker]], near the base of the ramp going up to the tree.\r\n*If needed, seek training at a class trainer and sell and items you don't need.\r\n===Spiders and Plants===\r\n*Move northeast around the trees and hug [[Aldrassil]], the big center tree, as you collect [[Hyacinth Mushroom]]s near the bases of the other trees. Look around. The mushrooms are usually in the nooks made by the smaller trees and bushes.\r\n*Keep killing [[Thistle Boar]]s and [[Mangy Nightsaber]]s for the quest if necessary.\r\n*Once you have traveled as far as the lake, collect the [[Moonpetal Lily]] flowers that are all around.\r\n*Next head north and kill some [[Webwood Spider]]s until you have 1 [[Webwood Ichor]] and 10 [[Webwood Venom Sac]]s.\r\n*Return to the populated area of Aldrassil, and train/sell items as needed.\r\n*Turn in Iverron's Antidote and accept Iverron's Antidote (2). NOTE: You have a time limit for this quest, but it shouldn't be an issue if you don't log out.\r\n*Go to [[Gilshalan Windwalker]] at the ramp and turn in Webwood Venom. Pick up the follow-up Webwood Egg.\r\n*Return to Iverron at the mouth of the cave and turn in Iverron's Antidote (2).\r\n*Head into the cave and take the middle path at the first split. Continue straight again and then follow the path up and around to the right. You should find eggs here.\r\n*Return to Aldrassil, killing any [[Thistle Boar]]s and [[Mangy Nightsaber]]s you have left along the way - you will need 7 of each to complete the quest.\r\n*Turn in Webwood Egg and The Balance of Nature (2).\r\n===Moving On===\r\n*[[Gilshalan Windwalker]] will now offer the quest Tenaron's Summons.\r\n*Head up the tree to the top, and speak with [[Tenaron Stormgrip]] to receive Crown of the Earth.\r\n*The moonwell where you can fill the phial is on the northern side of the tree. Once it is filled, return to Tenaron and complete the quest, then get Crown of the Earth (2).\r\n== Teldrassil (LVL 5-10)==\r\n[[Teldrassil]] is the main zone for beginning night elves, once they graduate from [[Shadowglen]]. To get here, head through the pass on the south-east corner of Shadowglen.\r\n===The Trip to Dolanaar===\r\n*Before heading out, priests should pick up the quest In Favor of Elune from their trainer for a few extra XP.\r\n*In the pass between [[Shadowglen]] and the main part of [[Teldrassil]], you will encounter the night elf [[Porthannius]]. Get Dolanaar Delivery from him.\r\n*Continue along the road towards [[Dolanaar]]. You will come across the satyr [[Zenn Foulhoof]]. Get the quest Zenn's Bidding from him. For the rest of the trip, kill any [[Nightsaber]]s, [[Strigid Owl]]s, or [[Webwood Lurker]]s that you come across. Save any Small Spider Leg you find, as you can use them for a cooking quest later.\r\n*In Dolanaar, turn in Crown of the Earth (2) and Dolanaar Delivery.\r\n*Pick up the following quests:\r\n**A Troubling Breeze\r\n**The Emerald Dreamcatcher\r\n**Crown of the Earth (3)\r\n**[[Cooking]] only: \r\n**[[Alchemy]] only: \r\n**[[Priest]]s only: Garments of the Moon\r\n*Catch up on training and, if desired, train in a profession. The following profession trainers are available here:\r\n** Byancie\r\n** Cyndra Kindwhisper\r\n** Malorne Bladeleaf\r\n** Zarrin\r\n*Priests should complete Garments of the Moon before leaving for [[Starbreeze Village]]. The needed NPC is just south of Dolanaar.\r\n*Cooks doing the quest can collect spider legs as they travel for other quests, killing spiders as they go.\r\n*Alchemists doing the quest can collect the needed herbs as they travel for other quests.\r\n===Trouble at Starbreeze Village===\r\n*Go back down the road you came from and take the turn off heading east towards [[Starbreeze Village]]. Remember to kill any creatures you see along the way to collect the items for Zenn's Bidding.\r\n*In Starbreeze Village, head to the top floor of the largest building to find [[Gaerolas Talvethren]] and get the quest Gnarlpine Corruption.\r\n*In the smaller building, check in the dresser to locate the dreamcatcher for The Emerald Dreamcatcher.\r\n*Fill the vial for Crown of the Earth (3) at the moonwell in the village.\r\n*On the way back to [[Dolanaar]], be sure to get the rest of the items needed for Zenn's Bidding.\r\n*Turn in the following quests:\r\n**Zenn's Bidding\r\n**Gnarlpine Corruption\r\n**The Emerald Dreamcatcher\r\n*The following quests should now be available:\r\n**Ferocitas the Dream Eater\r\n**Seek Redemption!\r\n===Lake Al'Ameth===\r\n*If you haven't done so, pick up the quests Denalan's Earth and Seek Redemption! from [[Syral Bladeleaf]] in [[Dolanaar]].\r\n*Head down to the lake south of [[Dolanaar]]. Pick up any [[Fel Cone]]s you see along the way - they tend to be on the slope above the lake or near trees and can be a bit hard to find.\r\n*[[Denalan]] can be found at the northeastern side of the lake. Talk to him to get Timberling Seeds and Timberling Sprouts.\r\n*The [[timberling]]s who drop the seeds and the [[Timberling Sprout]]s are all along the northern half of the lake, and [[Fel Cone]]s can be found in the same area. Once you have the required number of each, return to [[Denalan]] and turn in the two Timberling quests. \r\n*Then head northeast of [[Dolanaar]] to give the satyr the [[Fel Cone]]s.\r\n===Running Errands===\r\nThe next two quests are not connected or even in the same area, but should be done at this time for leveling purposes. Both Twisted Hatred and Ferocitas the Dream Eater can be a pain, so bringing a friend along is helpful.\r\n*Twisted Hatred: The cave for this quest is in the hills just north of [[Dolanaar]]. Locate the satyr [[Lord Melenas]] and kill him, then return to [[Tallonkai Swiftroot]] in [[Dolanaar]] with his head.\r\n*Ferocitas the Dream Eater: The furbolgs for this quest, along with [[Ferocitas the Dream Eater]], are camped just north of [[Starbreeze Village]]. Right click the necklace looted from Ferocitas to get [[Tallonkai Swiftroot]]'s gem, and return it to him after killing the required number of mystics.\r\n===The Ban'ethil Barrow Den===\r\nThe barrow den is a difficult area for new players and is also rather large. It is much more enjoyable to do this quest with one or more other people.\r\n*Make sure you have the quest The Relics of Wakening from [[Athridas Bearmantle]] in [[Dolanaar]].\r\n*Walk along the road to the west of [[Dolanaar]] until you find [[Moon Priestess Amara]] and pick up The Road to Darnassus.\r\n*The [[Ban'ethil Barrow Den]] is in the hills of central [[Teldrassil]], accessible from the north. Along the way you should encounter the [[Gnarlpine Ambusher]]s you need for The Road to Darnassus.\r\n*Once inside, search for the chests containing the artifacts for The Relics of Wakening. Search also for the ghost of the night elf [[Oben Rageclaw]], who will give the quest The Sleeping Druid.\r\n*Once you have found a Shaman Voodoo Charm from one of the furbolg shamans, return to Oben Rageclaw to receive the next quest, Druid of the Claw. Note that some people skip this quest since it often takes a long time to find the voodoo charm.\r\n*Locate the druid's body at the bottom of the barrow den and kill it, then use the charm. Return to Oben for a reward.\r\n*Find any relics for the The Relics of Wakening you still have left, then return to [[Athridas Bearmantle]] in [[Dolanaar]].\r\n===The Pools of Arlithrien===\r\nHunters should do their pet quests around this time, as soon as they hit level 10. See the [[Taming the Beast (Night Elf) quest chain]] for details.\r\nWarriors should head to [[Darnassus]] to pick up their level 10 quest at this point as well. If you aren't level 10 yet, [[grind]] until you get there.\r\n*Get the following quests from [[Dolanaar]] before setting out:\r\n**Crown of the Earth (4)\r\n**Ursal the Mauler\r\n*Head along the road to the west past the hills where the [[Ban'ethil Barrow Den]] is. Just before the entrance to [[Darnassus]], turn left (south).\r\n*Just southeast of the big lake is the moonwell you need for Crown of the Earth (4). Right click your phial to fill it.\r\n*Go as far to the southwest as you can. Along the way you should see the [[Strange Fruited Plant]], which looks like a giant tree with a pink glow around it. Right click it to receive the quest The Glowing Fruit.\r\n*You will come upon a [[furbolg]] settlement. Search the settlement for [[Ursal the Mauler]] and defeat him.\r\n*Warriors on the quest Vorlus Vilehoof should now head towards the eastern side of the hills where the [[Ban'ethil Barrow Den]] is. You will find a path heading up into the hills, which will eventually lead to the moonwell and the satyr, [[Vorlus Vilehoof]], whom you are after. Defeat him to complete your quest.\r\n*Return to [[Dolanaar]] and turn in the quests (Warriors head to [[Darnassus]] to turn in yours).\r\n===The Oracle Glade===\r\nThere are a '''lot''' of quests in the Oracle glade, and it is most efficient to do them all at once. However, make sure you prepare properly, or you may need to make multiple trips back to civilization for supplies.\r\n*In [[Dolanaar]], gather the following quests:\r\n**Crown of the Earth (5)\r\n**The Apple Falls (rogues only)\r\n*Head down to [[Lake Al'Ameth]] and pick up Rellian Greenspyre from [[Denalan]].\r\n*Travel west to [[Darnassus]] and turn in Rellian Greenspyre and The Apple Falls. Pick up:\r\n**Tumors\r\n**Tears of the Moon\r\n**Destiny Calls (rogues only)\r\n*Once you have the quests, head out of [[Darnassus]] and hang a left (north). Follow the road straight up to the moonwell and fill up your phial for Crown of the Earth (5). Now talk to the night elf by the moonwell to get The Enchanted Glade.\r\n*Find [[Mist]], the nightsaber, in the farthest northwestern point of the island. Talk to her to receive Mist. You will need to escort her back to the Oracle Tree (where the Sentinel and moonwell are). Kill harpies for the The Enchanted Glade quest as you go.\r\n*Nearby (slightly to the northeast of where Mist was) you should find the [[Strange Fronded Plant]]. Right click it to receive the quest The Shimmering Frond.\r\n*Head back to the southwest and defeat any more harpies needed for The Enchanted Glade, then return to [[Sentinel Arynia Cloudsbreak]] to turn in the quest. She should now offer the quest Teldrassil.\r\n*In the river to the east are the [[timberling]]s needed for Tumors. Range up and down the river, looking for the [[rare mob]] [[Blackmoss the Fetid]]. If you find him, he will drop an item which starts the quest The Moss-twined Heart.\r\n*On either side of the farthest north point of the river roams [[Lady Sathrah]], the objective of Tears of the Moon. Defeat her and take her spinnerets.\r\n*West of this point (directly north of the Oracle Tree), rogues can find [[Sethir the Ancient]] for their quest Destiny Calls. Don't attack him: though you can get the item in this way, he spawns several minions which make him incredibly difficult to defeat for this level. Instead, pickpocket the journal from him to complete the quest.\r\n*Head back south, picking up any more tumors you need from the timberlings in the river. When you have completed everything, return to [[Darnassus]].\r\n*In Darnassus, turn in the following:\r\n**Tumors\r\n**Teldrassil\r\n**Tears of the Moon\r\n**Destiny Calls\r\n*Make sure to pick up Return to Denalan before you leave for [[Dolanaar]].\r\n===Back to the lake===\r\n*Head back to [[Dolanaar]] and turn in Crown of the Earth (5) to [[Corithras Moonrage]], and pick up the final quest in the series, Crown of the Earth (6).\r\n*Go down to the lake and talk to [[Denalan]]. You should have quite a few quests to turn in, but be sure to turn them in one at a time: each time you turn one in, Denalan will plant something in his planter and a mob will spawn.\r\n**Return to Denalan\r\n**The Glowing Fruit\r\n**The Shimmering Frond\r\n***The Sprouted Fronds\r\n**The Moss-twined Heart (if you found [[Blackmoss the Fetid]])\r\n***Planting the Heart\r\n*After all this [[Denalan]] should offer you Oakenscowl. This is a group quest to kill a named [[timberling]] in a cave just south of the lake. Grab a friend and head down there, defeat the creature, and return to [[Denalan]].\r\n*All that is left to do is return to [[Darnassus]] to turn in Crown of the Earth (6) to [[Arch Druid Fandral Staghelm]], who sits atop the main building in the [[Cenarion Enclave]].\r\n==Where to go from here==\r\nThe next step for most [[night elf|night elves]] is to head to [[Darkshore]]. See the [[Darkshore questing guide]] for details on preparation and questing in that area.\r\nOther zone options for this level include [[Redridge Mountains]], [[Loch Modan]], and [[Bloodmyst Isle]].",},
			["Teldrassil quests"] = { content = "This is a list of all [[Teldrassil]] quests in table format.\r\nFor a questing guide detailing the best order to obtain and complete quests in [[Teldrassil]], see [[Teldrassil questing guide]].\r\n=== Shadowglen quests===\r\n[[Shadowglen]] is the beginning area for [[night elf|night elves]]. New night elves will spend their first levels (usually 1-5) in this area before graduating to the main [[Teldrassil]] area outside this sheltering glen.\r\n''See also: [[Powerlevel Shadowglen]], [[Teldrassil_questing_guide|Shadowglen questing guide]]''\r\n==Quest Table==\r\nQuests which take place outside of [[Teldrassil]] are denoted by a . \r\nQuests which are part of a chain are denoted by .\r\n==Notable Quest Chains in Teldrassil==\r\nThe following quest chains occur in [[Teldrassil]]. Chains have been included if they are more than three quests long or are specially significant in some way.\r\n===Crown of the Earth Chain===\r\nThis chain involves traveling to different moonwells around [[Teldrassil]] and collecting their water.\r\n#Webwood Venom\r\n#Webwood Egg\r\n#Tenaron's Summons\r\n#Crown of the Earth\r\n#Crown of the Earth (2)\r\n#Crown of the Earth (3)\r\n#Crown of the Earth (4)\r\n#Crown of the Earth (5)\r\n#Crown of the Earth (6)\r\n===Timberlings Chain===\r\nIn this quest chain, players must perform many tasks for the night elf [[Denalan]] involving [[Timberling]]s.\r\n#Denalan's Earth\r\n#Both of the following:\r\n#*Timberling Sprouts\r\n#*Timberling Seeds\r\n#Rellian Greenspyre\r\n#Tumors\r\n#Return to Denalan\r\n#Oakenscowl\r\nCompleting the chain up to the Timberling Seeds and Timberling Sprouts quests opens up the following quests:\r\n*The Glowing Fruit\r\n*The Shimmering Frond\r\n**The Sprouted Fronds\r\n*The Moss-twined Heart\r\n**Planting the Heart\r\n===Furbolgs Chain===\r\nThis quest chain consists of many [[Teldrassil]] quests involving [[furbolg]]s.\r\n#A Troubling Breeze\r\n#Gnarlpine Corruption\r\n#The Relics of Wakening\r\n#Ursal the Mauler",},
			["Teleport"] = { content = "'''Teleport''' is a useful line of [[Mage]] [[utility]] spells that allows the caster to transport himself to a friendly capital city. Teleport requires a [[reagent]], Rune of Teleportation.\r\n==Non-mage teleport==\r\nThere are several non-mage teleportation spells that require a certain class, profession, and/or certain item to use.\r\n==Non-Player Teleport==\r\nThere are a few teleport spells in the game not available to players. Usually an NPC teleports a player to a different location\r\n==Notes==\r\nEach Teleport spell is trained at a portal trainer, who is usually located near the [[mage trainer]]s in a major city. In [[Shattrath]] the portal trainer is located in the center of the city, near the various city portals. In [[Darnassus]] the portal trainer is located in [[The Temple of the Moon]].\r\nThe [[reagent]] Rune of Teleportation stacks to 20 and can be purchased at any reagent vendor for s=10 gold , or down to s=8 gold with reputation discounts. Druids do not need a reagent to teleport to Moonglade.\r\nThis spell is not on the same [[cooldown]] timer as a [[Hearthstone]].\r\nYou will appear in the capital city near the portal trainer of that city. In [[Stormwind]], for example, you appear inside the mage tower at the center of the Mage Quarter.\r\nYou cannot learn the teleport spells of the opposing faction.\r\nTeleport cannot be cast in combat.\r\n==Tips and Tactics==\r\nA flight to [[Shattrath City]] from any point in [[Outland]] is always more expensive than the price of a Rune of Teleportation. Thus, from any place in Azeroth or Outland it is always faster ''and cheaper'' to teleport than fly.\r\nNever leave town without a stack of Rune of Teleportation!",},
			["Teleport: Moonglade"] = { content = "''The Druid sanctuary is in perfect harmony with Nature -- and the further you are from the caves, the more harmonious you are.''\r\nA [[Druid]]-only [[Teleport]] spell. Teleports the caster to the city of [[Nighthaven]], [[Moonglade]].\r\n==Notes==\r\n* This spell is given to you at the start of the [[Bear Form]] [[Druid Quests|quest chain]].\r\n* Useful for [[night elf]] [[druid]]s, it allows for a short trip to [[Rut'theran Village]], serving the function of a [[Hearthstone]] for their hometown. Not so much for [[Tauren]], since the trip from [[Moonglade]] to [[Thunder Bluff]], even if free, takes almost seven minutes. (It used to be a longer ride over [[Darkshore]] that took 10 minutes, but now you get the direct way through [[Felwood]]). If you have the adjacent flight points, it is best to leave from the non-druid flight-path, close to the bottom of the region, and take the shorter trip to [[Orgrimmar]].\r\n* Useful also if your [[Hearthstone]] is on [[cooldown]] and you need to leave a dangerous area, like [[Dungeon|dungeons]] or [[Battleground|battlegrounds]].\r\n* With the advent of [[The Burning Crusade]], this spell becomes slightly more useful, since it allows instant [[Azeroth]]. From Moonglade you can easily find a transport to a capital city.\r\n* This spell is extraordinarily useful during the leveling process. Every even-numbered level the druid is ready to learn new and better abilities. Set your [[Hearthstone]] at an [[inn]] in the area where you're leveling, teleport to Moonglade, use the Moonglade druid trainer, then hearth back. This potentially saves a signficant amount of travel time.\r\n* Although extremely painful and time-consuming, the location of Moonglade can also give Druids a 50-level head start into [[Winterspring]], via \"corpse hopping\". Once the Everlook flight path is discovered, interaction with the [[Timbermaw]] may be skipped entirely.\r\n==Tips and tactics==\r\n* This spell can not be cast in battle.",},
			["Teleport This!"] = { content = "==Objectives==\r\nNether-Stalker Nauthis wants you to use the [[Mental Interference Rod]] on the Mo'arg at Forge Base: Gehenna and use their Detonate Teleporter ability on the three teleporters in the forge camp. \r\n*Western Teleporter Destroyed\r\n*Mental Interference Rod (Provided)\r\n== Description==\r\nAs fun as killing demons might be, it does us little good when the Legion can keep using its teleporters to replace anything we kill.\r\nUnfortunately, I don't have any high-powered explosives handy... but the mo'arg that maintain the teleporters do.\r\nTake this rod... I've tuned its powers to interfere with mo'arg brain frequencies. Return to Forge Base: Gehenna and use it on any mo'arg you see. You won't have long, but you'll be able to use their demolition charges on the nearby teleporters. \r\n== Completion==\r\nThanks to you, <name>, I'll breathe a little easier. Figure of speech, of course!\r\nI suppose you'll want some form of reward now. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*15400 [[XP]] (or 9 gold 24 silver copper at level 70)\r\n*350 [[reputation]] with [[The Consortium]]",},
			["Teleport to Dalaran Crystal"] = { content = "The '''Teleport to Dalaran Crystal''' is located in [[Violet Stand]] on the western edge of [[Crystalsong Forest]] and teleports to the [[Teleport to Violet Stand Crystal]] in a portal room in eastern [[Dalaran]] just behind Archmage Celindra, but only if you have used the Dalaran crystal first.\r\nIt is involved in the following quest:\r\n*Learning to Leave and Return: the Magical Way",},
			["Teleport to Violet Stand Crystal"] = { content = "The '''Teleport to Violet Stand Crystal''' teleports to the [[Teleport to Dalaran Crystal]] at [[Violet Stand]] on the western edge of [[Crystalsong Forest]] and is used to safely leave [[Dalaran]] without having to jump down to the Crystalsong Forest. It is located in the mage portal room just behind Archmage Celindra on the east side in southeast central Dalaran, to the northwest and across from [[Krasus' Landing]] ([[flight path]]).\r\nIt is involved in the following quest:\r\n*Learning to Leave and Return: the Magical Way",},
			["Telhamat"] = { content = "#redirect [[Temple of Telhamat]]", redirect = "Temple of Telhamat",},
			["Telkar Doomhammer"] = { content = "'''Telkar Doomhammer''' was the father of Warchief [[Orgrim Doomhammer]], and one of the best warriors in the [[Blackrock Clan]]. He wielded the mighty [[Doomhammer]], considered by some to be a weapon of prophecy. Some years after Orgrim and his friend [[Durotan]] encountered the [[Velen|Prophet Velen]], Telkar was killed by an ogre, and the weapon passed on to his son, who would wield it until the day he died - when the prophecy of the Doomhammer was fulfilled, and it went to an orc not of the Doomhammer lineage who would free the orcs from their demonic chains...[[Thrall]], son of Durotan.",},
			["Telmor"] = { content = "'''Telmor''' was a hidden [[draenei]]-populated city in [[Terokkar Forest]]. The city was located in the middle of the ogre country and made invisible by a protective spell using the [[Ata'mal crystal]] shard [[Leafshadow]]. When [[Restalaan]] and his draenei party had rescued the young [[orc]]s [[Durotan]] and [[Orgrim]] who were under attack by an ogre they were escorted to Telmor, Durotan memorized the incantation that deactivated the spell. Later, when the orcs started a war against the draenei, Durotan used this knowledge to remove the invisibility spell from Telmor, leaving the nearly undefended city open to an attack. As a result, the city was taken over and completely destroyed, and Restalaan was killed.",},
			["Telredor"] = { content = "'''Telredor''' is an [[Alliance]]-aligned [[draenei]] town located on top of a giant mushroom in eastern [[Zangarmarsh]]. Originally a calm settlement of draenei [[anchorite]]s, many draenei refugees flocked to it when the orcs started attacking their villages. Telredor turned out to be an impregnable fortress, and a safe haven for many draenei. They followed [[Velen]] in joining the Alliance, and some members of allied races have come to the town to research the marshes and do business.\r\nIt is infamous for its particularly tricky floating elevator that transports players to and from the top of the mushroom. The elevator travels a long distance and doesn't have walls, making it easy to misjudge its landing and thus misstep and plummet to your death on the ground far below.\r\nTelredor does not have food vendors, and for a lore-based reason. Many of the quests relate to food gathering, and because they are close to starving, food is shared among their own people and they would not sell it to outsiders.\r\n==List of NPCs==\r\n* Anchorite Ahuurn\r\n* Caregiver Abidaar\r\n* Haalrun\r\n* Joraal\r\n* K. Lee Smallfry\r\n* Loolruna\r\n* Munci\r\n* Noraani\r\n* Prospector Conall\r\n* Ruam\r\n* Vindicator Idaar\r\n===Flight===\r\n [[Shattrath City]]\r\n [[Orebor Harborage]]\r\n [[Temple of Telhamat]]\r\n [[Sylvanaar]]\r\n [[Telaar]]\r\n==Notes==\r\nThere is a landing formed at the top of the two staircases leading to the elevator platform: it is here where [[Farseer Nobundo]] stood and introduced the path of shamanism to the draenei.",},
			["Temper"] = { content = "'''Temper''' is a level 70 [[quest giver]] located at [[Emberglade]] in the northeastern corner of the [[draenei]] starting zone of [[Azuremyst Isle]].\r\nHe ends the following quests:\r\n* Call of Fire (Draenei, 3)\r\n* Call of Fire (Draenei, 4)\r\n* Call of Fire (Draenei, 5)\r\nHe starts the following quests:\r\n* Call of Fire (Draenei, 4)\r\n* Call of Fire (Draenei, 5)\r\n* Call of Fire (Draenei, 6)\r\nSee [[List of Azuremyst Isle NPCs]].\r\n==Notes==\r\nInterestingly, he's also friendly to [[Horde]] players.",},
			["Tempest Keep"] = { content = ":''This is about the dungeon hub. For the raid known in-game as \"Tempest Keep\", see [[Eye (Tempest Keep)]].''\r\n'''Tempest Keep''' is a former [[naaru]] [[Dimensional Ship|fortress]] in the [[Netherstorm]] in [[Outland]]. This crystalline fortress is now ruled by [[Kael'thas Sunstrider]], the lord of the [[Blood elf|blood elves]], and dominated by scores of his brethren. The structure is divided into three wings - satellites of the gigantic structure - with the fourth wing, [[the Exodar]], now in the world of Azeroth as the [[Draenei]] capital.\r\nThe three remaining wings are differentiated by the different color themes:\r\n*[[Botanica]]: Light blue\r\n*[[Arcatraz]]: Red\r\n*[[Mechanar]]: Light purple\r\n''Tip'': One easy way to remember which is which is to look at their placement on the map. Starting at the top and working clockwise are '''B''' for [[Botanica]], '''A''' for [[Arcatraz]], and '''M''' for [[Mechanar]], spelling the mnemonic \"BAM\".\r\n==Summary==\r\n*'''Layout:''' Three 5-man wings, One 25-man raid\r\n**'''[[The Mechanar]]''' (Level 69-72 mobs). '''Bosses:''' \r\n***'''First Layer Bosses''': [[Gatewatcher Gyro-Kill]], [[Gatewatcher Iron-Hand]], [[Mechano-Lord Capacitus]]\r\n***'''Second Layer Bosses''': [[Nethermancer Sepethrea]], [[Pathaleon the Calculator]]\r\n**'''[[The Botanica]]''' (Level 70-72 mobs).\r\n***'''Bosses:''' [[Commander Sarannis]], [[High Botanist Freywinn]], [[Thorngrin the Tender]], [[Laj]], [[Warp Splinter]]\r\n**'''[[The Arcatraz]]''' (Level 70-72 mobs)\r\n***'''Bosses:''' [[Zereketh the Unbound]], [[Wrath-Scryer Soccothrates]], [[Dalliah the Doomsayer]], [[Warden Mellichar]] Event. The [[Warden Mellichar]] Event include the spawn of: random boss (70+) - [[Millhouse Manastorm]] (friendly gnome) - random boss (72+) - random boss (72+) - [[Harbinger Skyriss]]\r\n**'''[[Eye (Tempest Keep)|The Eye]]''' (25-man raid wing)\r\n***'''Bosses:''' [[Al'ar]], [[Void Reaver]], [[High Astromancer Solarian]], [[Kael'thas Sunstrider (tactics)|Kael'thas Sunstrider]]\r\n* You will need a [[flying mount]] (druids can use [[flight form]]) in order to access the Tempest Keep; it is not possible to summon someone to one of the satellite structures. With Patch 2.4, it is possible to summon someone inside of one of the satellite structures now.\r\n* Populated with [[blood elf|blood elves]].\r\n==Background==\r\nThe mighty Tempest Keep was created by the enigmatic [[Naaru]]: sapient beings of pure energy and the sworn enemies of the [[Burning Legion]]. As a base of operations for the Naaru, the structure itself possesses the technology to teleport through alternate dimensions, traveling from one location to another in the blink of an eye.\r\nWith [[Outland]] serving as the strategic battlefront in the ongoing Burning Crusade, the Naaru recently used Tempest Keep to reach the shattered land. However, when the Naaru set out from their stronghold, Prince Kael’thas and his blood elves quickly raided the dimensional fortress and assumed control over its satellite structures.\r\nNow, guided by some unknown purpose, Kael’thas manipulates the keep’s otherworldly technologies, using them to harness the chaotic energies of the Netherstorm itself.\r\nThough Kael’thas and his minions maintain a tight hold on the keep, a band of [[Draenei]] recently hijacked one of its satellite structures, the [[Exodar]], and used it to escape Outland. In seeking out other worlds, the Draenei, led by the ancient prophet, Velen, hoped to find allies who would stand with them against the Legion and its nihilistic Crusade.\r\n==How it works==\r\nTempest Keep can be accurately described as an enchanted fortress. It has the ability to Travel along the [[Twisting Nether]] - a realm of intense energy that links all the worlds of the [[Great Dark]] together. This is where the term \"inter-dimensional\" comes from. A \"space ship\" would simply traverse the distance of the great dark from point A to point B. Tempest keep uses the Twisting nether to travel almost instantaneously from place to place. In essence, it is a self-contained [[Dark Portal]] which operates on the same principle.\r\n==The Draenei 'ship'==\r\nIt has been revealed in a with Tom Chilton that Tempest Keep was the \"Dimensional Ship\" which the [[Naaru]] provided for the [[draenei]]'s flight from [[Argus]]. The Keep was imbued with powerful arcane energies that allowed it to move from world to world in a kind of mass teleport. When the orcs were corrupted by [[Kil'jaeden]], it was believed that many draenei hid away in the Keep for many decades, until Prince Kael'thas and the other blood elves and naga allied with Illidan Stormrage seized the Keep for themselves. The draenei were apparently able to escape from the blood elves into Azeroth using a wing of the Keep, landing roughly in the [[Azuremyst Isles]] of northwestern Kalimdor. The blood elves now use the technology inside the Tempest Keep to harness their vast amount of energy from the Netherstorm.\r\nMetzen: ''The draenei nether-ship you've been hearing about is far more than it seems. It's part of a larger dimension-traveling fortress called Tempest Keep that essentially teleports through alternate realities. It doesn't bank and roll or shoot photon torpedoes (not yet, anyway).'' \r\n===Contradictory evidence===\r\nIn a direct contradiction to Chilton's information about Tempest Keep, it was revealed in ''[[Rise of the Horde]]'' that [[Oshu'gun]], the gigantic crystal in [[Nagrand]] revered by the orcs as their \"Mountain of Spirits,\" was in fact the vessel that provided [[Velen]] and the draenei their escape from Argus, not Tempest Keep. It was also revealed in the Blizzard short \"[[Unbroken (Story)|Unbroken]]\" that Velen and the survivors did not flock to Tempest Keep to hide, but rather hid somewhere in the [[Zangarmarsh]] (possibly the hidden [[Telredor]], or the [[Orebor Harborage]] on the border with the [[Blade's Edge Mountains]]). The story regarding Tempest Keep was changed accordingly; in the Burning Crusade manual, Tempest Keep was described as a naaru dimensional fortress that did not arrive on Draenor until ''after'' its destruction/transformation into Outland. When the naaru dispersed to aid in the retaking of Outland from the forces of the Burning Legion as well as make war against the [[Illidari]], the blood elves attacked and conquered it. The portion referring to Velen and the draenei raid on the Exodar in order to escape Outland was only slightly modified to fit the changed situation.",},
			["Tempest Keep: The Eye"] = { content = "#REDIRECT [[Eye (Tempest Keep)|Tempest Keep: The Eye]]", redirect = "Eye (Tempest Keep)|Tempest Keep: The Eye",},
			["Tempest Keep NPCs"] = { content = "The following [[NPC]]s can be found in the instanced wings of [[Tempest Keep]].\r\n=== Neutral===\r\n* Udalo\r\n**[[A Mysterious Portent]]\r\n* [[Verdant Sphere]]\r\n**[[Kael'thas and the Verdant Sphere]]\r\n== Bosses==\r\n* Al'ar\r\n* Commander Sarannis\r\n* Dalliah the Doomsayer\r\n* Harbinger Skyriss\r\n* High Astromancer Solarian\r\n* High Botanist Freywinn\r\n* Kael'thas Sunstrider\r\n* Laj\r\n* Mechano-Lord Capacitus\r\n* Nethermancer Sepethrea\r\n* Pathaleon the Calculator\r\n* Thorngrin the Tender\r\n* Void Reaver\r\n* Warp Splinter\r\n* Wrath-Scryer Soccothrates\r\n* Zereketh the Unbound\r\n=== Neutral===\r\n* Millhouse Manastorm\r\n===Hostile===\r\n* Akkiris Lightning-Waker\r\n* Blackwing Drakonaar\r\n* Blazing Trickster\r\n* Gatewatcher Gyro-Kill\r\n* Gatewatcher Iron-Hand\r\n* Grand Astromancer Capernian\r\n* Lord Sanguinar\r\n* Master Engineer Telonicus\r\n* Phase-Hunter\r\n* Sulfuron Magma-Thrower\r\n* Thaladred the Darkener\r\n* Third Fragment Guardian\r\n* Twilight Drakonaar\r\n* Warden Mellichar",},
			["Tempest Key Guide"] = { content = "#REDIRECT [[The Tempest Key]]", redirect = "The Tempest Key",},
			["Tempest Regalia"] = { content = "'''Tempest Regalia''' is the [[tier 6]] [[mage]] set.\r\n==See also==\r\n* [[Set look alikes]]",},
			["Tempest Rift"] = { content = "'''The Tempest Rift''' is the part of the [[Twisting Nether]] that surrounds [[Tempest Keep]] on all sides. The dungeon's wings all float in the rift, attached to each other with unseen bonds of force.",},
			["Tempest Smith"] = { content = "#REDIRECT [[Tempest-Smith]]", redirect = "Tempest-Smith",},
			["Templar"] = { content = "'''Argent Dawn Templars''', often called simply templars, are devoted followers of the [[Holy Light]] who have chosen to cast away the traditions of the past to find the best ways possible to fight the growing forces of darkness in the world. Like [[paladin]]s, Argent Dawn Templars often oppose [[demon]]s and [[undead]], but templars learn to use the Holy Light to strike against other forms of evil with equal potency.\r\nTo aid in the seemingly impossible struggles against the [[Scourge]] and the [[Burning Legion]], the templars study all forms of combat, and they find powerful and unique uses for the Holy Light. These unique abilities carry a price, however. As an Argent Dawn Templar delves deeper into studies of the Light, they abandon their old teachings and connections to the world. Many templars sacrifice much of their wealth in their continuing battle against the forces of darkness in the world, but the greatest are more greatly transformed. Former paladins cast off their plate armor or even abandon their old powers in favor of the new secrets they uncover. Some observers claim that the eldest templars require such sacrifices from their disciples; others believe that the secrets these knights discover somehow drives them away from their former lives and powers.\r\nThese few who know of the [[Argent Dawn]] Templars speak of strange and mysterious rituals the knights perform in search of new and greater powers. While a few of the Church of the Holy Light's most traditional paladins and [[priest]]s condemn this unusual behavior, none can dispute the templar's effectiveness. Rumors abound of [[knight]]s powerful enough to shield themselves from any form of harm, or to banish a servant of the Burning Legion from [[Azeroth]] in a single strike.\r\nAll Argent Dawn Templars are members of the Argent Dawn, an unaffiliated organization that combats the Scourge, the Burning Legion, and the [[Twilight's Hammer]], as well as other sources of corruption. The majority of the Argent Dawn Templars are paladins, although some healers also take up the templar's mantle. While the Argent Dawn itself allows all races in its ranks (typically only humans), Ironforge dwarves and high elves have become templars.\r\nArgent Dawn Templars see their organization as a small silver light shining in the darkness of the world around them. Templars see corruption in their homes and many other organizations, including the [[Knights of the Silver Hand]]. While the templars see paladins as allies and vice versa, templars feel that the Silver Hand overemphasizes tradition and order over general goodness and other values of the Light. Templars are virtually unknown in the world as a whole, although the Argent Dawn itself is widespread. The few templars form a close-knit and elite group, often serving as leaders for groups of paladins and priests without revealing their unusual paths.\r\nHigh-ranking Argent Dawn Templars initiate all new members, typically after the aspirant completes a difficult quest or achieves a considerable goal. The Argent Dawn's leaders study and train potentials carefully before they accept them into the elite section of the Argent Dawn.\r\nThe Argent Dawn Templar gains the ability to change divine spell energy into holy lightning, manifesting it as a blast of silvery light.\r\n===Famous/Named===\r\n*[[Andarin Lightblade]]\r\n*[[Addar Lightbringer]]\r\n*[[Ashlam Valorfist]]\r\n*[[High Priestess MacDonnell]]\r\n*[[Saria Nightwatcher]]\r\n]",},
			["Temple"] = { content = "The unholy place where Orcs come to make sacrifices to their gods, and the Necromancers of the land gather to invoke the will of their dark masters. This is the only place where [[Necrolyte]]s can be recruited to assist you in purging the land of Human settlements. The need for a blood offering has only recently been replaced by one of gold, and no assistance will be sanctioned until it is made. The immense, sacrificial alters used in the Necrolytes’ rituals must be built of the mystic [[Blackroot]], hence a lumber mill must be used to locate and specially prepare the wood.",},
			["Temple City of En'kilah"] = { content = "The '''Temple City of En'kilah''' is a [[Scourge]] fortress in the eastern part of [[Borean Tundra]], south of the crashed [[necropolis]] of [[Talramas]]. Floating above the city is another Scourge necropolis, [[Naxxanar]], which serves as the command center of the Scourge in Borean Tundra.\r\nThe spires of [[Spire of Blood|Blood]], [[Spire of Decay|Decay]], and [[Spire of Pain|Pain]] are located within the city. Alliance players are given a task by the death knight [[Thassarian]] (in the quest Words of Power) to kill the city's three high priests, located in each of these spires: the [[darkfallen]] [[High Priest Andorath|Andorath]], the [[crypt lord]] [[High Priest Naferset|Naferset]], and the [[crypt fiend]] [[High Priest Talet-Kha|Talet-Kha]].",},
			["Temple Gardens"] = { content = "The '''Temple Gardens''' are a large open area in the center of the [[Night elf|night elven]] capital of [[Darnassus]]. The gardens themselves encompass the body of water, walkways, and small islands at the heart of the city, being named for the large [[Temple of the Moon]] located immediately to the south.\r\nA portal in the far west of the district provides the only non-flying method of traveling to [[Rut'theran Village]] at the base of the [[World Tree]], while Darnassus's [[bank]] can also be found on the largest island. The Temple Gardens are connected by bridges to the [[Cenarion Enclave]] to the north, the [[Craftsmen's Terrace|Craftsmen's]], [[Warrior's Terrace|Warrior's]], and [[Tradesmen's Terrace]]s to the east, and the Temple of the Moon to the south.\r\nDuring the [[Burning of Teldrassil]], the conflagration leaped to the Temple Gardens.\r\n==Notes==\r\n*The night elves manipulated the waters to maintain the splendor of the Temple Gardens.\r\n*It is described as the centerpiece — though geographically more west of the center — of Darnassus and composed of several islets of varying size filled with the most exquisite of flora. [[Tyrande]] used it at least once for meditation. Similarly, [[Velen]] once meditated here as well because of its tranquility.",},
			["Temple of Ahn'Qiraj"] = { content = "The '''Temple of Ahn'Qiraj''' is a 40-man raid dungeon located in southern [[Silithus]]. It was released with Patch 1.9 during a massive server-dependent event called the [[Gates of Ahn'Qiraj]].\r\nPlayers access this instance via the [[Gates of Ahn'Qiraj]], an area before the instances with portals to both Ruins of Ahn'Qiraj and Temple of Ahn'Qiraj.\r\nThe entrance to the [[Ruins of Ahn'Qiraj]], which is a 20-man raid instance intended to be the step before [[Blackwing Lair]], is via a separate portal following the left path from the Scarab Wall gate.\r\n==History==\r\nDark whispers ride on the winds of Silithus desert. An old god stirs in his wretched lair and the entire world shall soon be the target of his wrath.\r\nAfter thousands of years of slumber, the old god, C'thun has awakened and is quickly regenerating his power. Once he has reached full potential nothing will be able to stop him. The dragons that so humbly sacrificed themselves so long ago to imprison C'thun are weakened or enslaved in the temple, so the charge of protecting the land falls to other heroes.\r\nHeroes must enter the Temple of Ahn'Qiraj, challenge C'thun's most wicked servants, and slay a god. The road will not be easy and it is wrought with peril at every turn. Will the heroes turn back now, or face C'thun in his mighty lair and put an end to him once and for all?\r\nFor more history and lore details, see [[Ahn'Qiraj]].\r\n===Sub-Regions===\r\nNone listed, everywhere is just \"Ahn'Qiraj\"\r\n==Quests==\r\nQuests with item rewards should go in the loot section, below.\r\n*[[Quest:Secrets of the Qiraji|Secrets of the Qiraji]]\r\n==Preparation==\r\nThe Temple of Ahn'Qiraj scales more in difficulty than other instances. The first few bosses are on par with the harder bosses in [[Molten Core]] and the last bosses are harder than anything you find in [[Blackwing Lair]].\r\nNature resistance is particularly important in this instance for a few bosses. Equipment is important, but the earlier encounters will be possible to beat with sheer wits and strategy. Nature Protection potions are clearly of use here.\r\nThere is no key required to enter the Ahn'Qiraj temple instance. Upon going through the Scarab Wall gate in southern Silithus, follow the path to the right to the instance portal.\r\n==Dungeon Denizens==\r\n* [[Qiraji]]\r\n* [[Silithid]]s\r\n===Trash Mobs===\r\n* [[Anubisath Defender]]\r\n* [[Anubisath Sentinel]]\r\n* [[Anubisath Warder]]\r\n* [[Obsidian Eradicator]]\r\n* [[Obsidian Nullifier]]\r\n* [[Qiraji Brainwasher]]\r\n* [[Qiraji Champion]]\r\n* [[Qiraji Mindslayer]]\r\n* [[Qiraji Slayer]]\r\n* [[Vekniss Drone]]\r\n* [[Vekniss Guardian]]\r\n* [[Vekniss Hive Crawler]]\r\n* [[Vekniss Soldier Packs]]\r\n* [[Vekniss Warrior]] and [[Vekniss Borer]]\r\n* [[Vekniss Wasp Packs]]\r\n==Boss Encounters==\r\n*[[The Prophet Skeram]]\r\n*[[Three Bugs|Vem, Yauj, and Kri]] (optional)\r\n*[[Battleguard Sartura]]\r\n*[[Fankriss the Unyielding]]\r\n*[[Viscidus]] (optional)\r\n*[[Princess Huhuran]]\r\n*[[Twin Emperors|The Twin Emperors : Emperor Vek'lor & Emperor Vek'nilash]]\r\n*[[Ouro]] the Sandworm (optional)\r\n*[[C'Thun]]\r\n==Loot==\r\n''For more details see [[Temple of Ahn'Qiraj Loot]]''\r\nThe loot in AQ40 comes from:\r\n* Killing [[boss]]es\r\n* Killing [[mobs]]\r\n* Quest rewards. Good reputation with [[Brood of Nozdormu]] is required to complete these quests, in much the same way as [[Zandalar Tribe]] reputation is required for [[Zul'Gurub]] quest rewards. It's possible to access these quest NPC after having killed the Prophet Skeram.\r\n====Loot-quest System====\r\nThe '''Temple of Ahn'Qiraj''' uses a Loot-quest system like [[Zul'Gurub]] or the [[Ruins of Ahn'Qiraj]].\r\nPlayers must collect ten scarab items of a certain type, two stone idols of a certain type, and a single Qiraji item. When a player has the appropriate collection for a particular item and a certain level of reputation with the Brood of Nozdormu, they can turn them in for the item. \r\nThe idols and scarabs can be found on mobs within the instance and in Greater Scarab Coffers, which can be opened with Greater Scarab Coffer Keys, which are White quality, not soulbound and as of 1.10 no longer zone-bound.\r\nSee : [[Temple of Ahn'Qiraj Quest Loot]] for a full list.",},
			["Temple of Ahn'Qiraj Loot"] = { content = "#REDIRECT [[Temple of Ahn'Qiraj loot]]", redirect = "Temple of Ahn'Qiraj loot",},
			["Temple of Ahn'Qiraj NPCs"] = { content = "The following [[NPC]]s can be found in [[Temple of Ahn'Qiraj]].\r\n=== Neutral===\r\n* Andorgos\r\n** Avenger's Crown\r\n** Avenger's Pauldrons\r\n** Conqueror's Crown\r\n** Conqueror's Spaulders\r\n** Deathdealer's Helm\r\n** Deathdealer's Spaulders\r\n** Doomcaller's Circlet\r\n** Doomcaller's Mantle\r\n** Enigma Circlet\r\n** Enigma Shoulderpads\r\n** Genesis Helm\r\n** Genesis Shoulderpads\r\n** Mantle of the Oracle\r\n** Stormcaller's Diadem\r\n** Stormcaller's Pauldrons\r\n** Striker's Diadem\r\n** Striker's Pauldrons\r\n** Tiara of the Oracle\r\n* Arygos\r\n** Imperial Qiraji Armaments\r\n* Caelestrasz\r\n** The Savior of Kalimdor\r\n* Kandrostrasz\r\n** Avenger's Greaves\r\n** Avenger's Legguards\r\n** Conqueror's Greaves\r\n** Conqueror's Legguards\r\n** Deathdealer's Boots\r\n** Deathdealer's Leggings\r\n** Doomcaller's Footwraps\r\n** Doomcaller's Trousers\r\n** Enigma Boots\r\n** Enigma Leggings\r\n** Footwraps of the Oracle\r\n** Genesis Boots\r\n** Genesis Trousers\r\n** Stormcaller's Footguards\r\n** Stormcaller's Leggings\r\n** Striker's Footguards\r\n** Striker's Leggings\r\n** Trousers of the Oracle\r\n* Merithra of the Dream\r\n** Imperial Qiraji Regalia\r\n* Vethsera\r\n** Avenger's Breastplate\r\n** Conqueror's Breastplate\r\n** Deathdealer's Vest\r\n** Doomcaller's Robes\r\n** Enigma Robes\r\n** Genesis Vest\r\n** Stormcaller's Hauberk\r\n** Striker's Hauberk\r\n** Vestments of the Oracle",},
			["Temple of Ahn'Qiraj Quest Loot"] = { content = "#REDIRECT [[Temple of Ahn'Qiraj quest loot]]", redirect = "Temple of Ahn'Qiraj quest loot",},
			["Temple of Arkkoran"] = { content = "The '''Temple of Arkkoran''' is located on the northeastern shores of [[Azshara]] and is where [[Arkkoroc]], a [[sea giant]] deity, resides. He can be found at the top level and is not hostile; the temple, however, is guarded by [[murloc]]s and [[makrura]] that will attack you on sight. [[The Shattered Strand]], which the temple is located on, is also under watch by [[hydra]]s and aggressive [[sea giant]]s.\r\nThe temple is a popular farming spot because of the [[Stormshroud Armor]] patterns and [[Golden Pearl]]s that drop there.\r\nMobs Found Here:\r\n*[[Arkkoran Clacker]]\r\n*[[Arkkoran Muckdweller]]\r\n*[[Arkkoran Pincer]]",},
			["Temple of Atal'Hakkar"] = { content = "The '''Temple of Atal'Hakkar''' (also known as the '''Sunken Temple''' and more rarely, the '''Lost Temple''') is a shrine erected by the [[Atal'ai|Atal'ai trolls]], led by their master [[Jammal'an the Prophet]] to the nefarious Blood God - [[Hakkar the Soulflayer]]. Believing that this was the intended site for Hakkar's reentry into [[Azeroth]], the great [[dragon Aspect]] [[Ysera]] and her [[Green Dragonflight]] sunk the temple into the depths of the [[Swamp of Sorrows]]... but the dragons did not realize that it was the wrong location until it was too late.\r\nMany of the bosses in the instance have some kind of prerequisite in order to encounter them. [[Atal'alarion]] will appear after activation of statues, [[Jammal'an the Prophet]] can only be reached by killing the 6 [[Troll|troll]] mini-bosses, [[Avatar of Hakkar]] must be summoned and the [[Shade of Eranikus]] will only be killable after the death of the Prophet.\r\nThe Temple may be entered by level 35 and the [[Meeting Stone]] is operational from level 45-53. The mob level range is 45-49, with the final boss being 50 with the [[patch 2.3]] changes.\r\n==History==\r\n''Over a thousand years ago, the powerful [[Gurubashi Empire]] was torn apart by a massive civil war. An influential group of troll [[Priest|priests]], known as the Atal'ai, attempted to bring back an ancient blood god named Hakkar the Soulflayer. Though the priests were defeated and ultimately exiled, the great troll empire buckled in upon itself. The exiled priests fled far to the north, into the Swamp of Sorrows. There they erected a great temple to Hakkar - where they could prepare for his arrival into the physical world. The great dragon Aspect, Ysera, learned of the Atal'ai's plans and smashed the temple beneath the marshes. To this day, the temple's drowned ruins are guarded by the green dragons who prevent anyone from getting in or out. However, it is believed that some of the fanatical Atal'ai may have survived Ysera's wrath - and recommitted themselves to the dark service of Hakkar.''\r\nThe name Atal’Hakkar can mean either 'Devoted to Hakkar' or 'In Honor of Hakkar' in [[Zandali]], the language of the trolls. \r\n===The Hinterlands===\r\nFrom [[Atal'ai Exile]]:\r\n*Jammal'an the Prophet\r\n===Stormwind === \r\nFrom [[Brohann Caskbelly]]: \r\n===Swamp of Sorrows===\r\n*Pool of Tears (Quest is in [[Swamp of Sorrows]] outside the temple in the water)\r\n**The Atal'ai Exile (Quest is in the [[Hinterlands]])\r\n**Return to Fel'Zerul (Quest is in [[Stonard]], [[Swamp of Sorrows]])\r\n***Temple of Atal'hakkar\r\n===Tanaris===\r\nFrom [[Yeh'kinya]]:\r\n*Screecher Spirits (Quest is in [[Feralas]])\r\n**The Prophecy of Mosh'aru (Quest is in [[Zul'Farrak]])\r\n**The Ancient Egg (Quest is in [[The Hinterlands]])\r\n***The God Hakkar\r\n===Feralas===\r\nFrom [[Angelas Moonbreeze]] at [[Feathermoon Stronghold]] or [[Witch Doctor Uzer'i]] at [[Camp Mojache]]:\r\n*The Sunken Temple (Quest is in [[Tanaris]]):\r\n**The Stone Circle (Quest is in [[Ratchet]])\r\n**Into the Depths\r\n**Secret of the Circle (You can have both Into the Depths and Secret of the Circle at the same time)\r\n===Un'Goro Crater===\r\n* Muigin and Larion (Quest is in [[Un'Goro Crater]])\r\n** A Visit to Gregan (Quest is in [[Feralas]])\r\n** Haze of Evil\r\n*** Bloodpetal Sprouts (Quest is in [[Un'Goro Crater]])\r\n* Larion and Muigin (Quest is in [[Un'Goro Crater]])\r\n** Marvon's Workshop (Quest is in [[Ratchet]])\r\n** Zapper Fuel\r\n===Temple of Atal'Hakkar===\r\n*The Essence of Eranikus\r\n**The Essence of Eranikus (2)\r\n**In Eranikus' Own Words\r\n===Quest Log===\r\n'''Alliance'''\r\n* Class\r\n** [52] Class Quest (Dungeon)\r\n* Sunken Temple\r\n** [52] Into The Temple of Atal'Hakkar (Dungeon)\r\n** [51] Into the Depths (Complete)\r\n** [51] Secret of the Circle (Dungeon)\r\n** [53] Jammal'an the Prophet (Dungeon)\r\n** [53] The God Hakkar (Dungeon)\r\n* Un'Goro Crater\r\n** [52] Haze of Evil (Dungeon)\r\n'''Horde'''\r\n* Class\r\n** [52] Class Quest (Dungeon)\r\n* Sunken Temple\r\n** [50] Temple of Atal'hakkar (Dungeon)\r\n** [51] Into the Depths (Complete)\r\n** [51] Secret of the Circle (Dungeon)\r\n** [52] Zapper Fuel (Dungeon)\r\n** [53] Jammal'an the Prophet (Dungeon)\r\n** [53] The God Hakkar (Dungeon)\r\n===Class Quests===\r\nAll classes will have a class-specific quest chain that will lead them into the Temple of Atal'Hakkar. Each quest chain ends with a choice of 3 items. For an analysis of the item choices, see: [[Sunken Temple Rewards]] (work still in progress).\r\n====Druid Quest====\r\n*Torwa Pathfinder\r\n**Bloodpetal Poison\r\n**Toxic Test\r\n***A Better Ingredient\r\n====Hunter Quest====\r\nfrom [[Olmin Burningbeard]] in [[Ironforge]] or [[Ormak Grimshot]] in [[Orgrimmar]]\r\n*The Hunter's Charm\r\n**Courser Antlers\r\n**Wavethrashing\r\n***The Green Drake\r\n====Shaman Quest====\r\n*Elemental Mastery (Starts with Shaman trainer)\r\n**Spirit Totem (Quest is in the [[Western Plaguelands]])\r\n**Da Voodoo\r\n====Paladin Quest====\r\n* Chillwind Camp\r\n** Dispelling Evil\r\n** Inert Scourgestones\r\n*** Forging the Mightstone\r\n* To The Bulwark (Champion Bachi or Champion Cyssa Dawnrose)\r\n** Prove Your Hatred (Requires killing stuff in [[Western Plaguelands]])\r\n** Wisdom of the Banshee Queen \r\n*** Ancient Evil\r\n====Priest Quest====\r\nFrom [[Brother Joshua]] at [[Stormwind]] Cathedral\r\n*Cenarion Aid\r\n**Of Coursers We Know\r\n**The Ichor of Undeath\r\n***Blood of Morphaz\r\n====Rogue Quest====\r\n*A Simple Request\r\n**Sealed Azure Bag\r\n**Encoded Fragments\r\n***The Azure Key\r\n====Mage Quest====\r\nNote: You get this quest from Archmage Xylem in Azshera\r\n*Magic Dust\r\n**The Siren's Coral\r\n**Destroy Morphaz\r\n====Warrior Quest====\r\n*[[Quest:A Troubled Spirit|A Troubled Spirit]] (quest is in [[Swamp of Sorrows]])\r\n**[[Quest:Warrior Kinship|Warrior Kinship]] (quest is in [[Blasted Lands]])\r\n**[[Quest:War on the Shadowsworn|War on the Shadowsworn]] (quest is in [[Blasted Lands]])\r\n***Voodoo Feathers\r\n====Warlock Quest====\r\n*[[Quest:An Imp's Request|An Imp's Request]] (You get this quest from Warlock trainers in any major city)\r\nor\r\n*[[Quest:Hot and Itchy|Hot and Itchy]] (Impsy in [[Felwood]])\r\n**The Wrong Stuff (Impsy in [[Felwood]])\r\n**Trolls of a Feather\r\n==Group info==\r\nA good group to have for this instance would consist of a [[tank]], a [[healer]], preferably a [[Mage]] for [[AoE]], and two [[damage dealer]]s. AoE's are very helpful, as there are many packs with non-elites. The instance offers a lot of opportunity for [[crowd control]], and magic dispels make it a lot easier, as there a various negative effects (Fear and Sleep being the most dangerous). One of the two damage dealers should be able to tank, or have a pet that can tank, for the [[Shade of Eranikus]] fight.\r\nEach of the classes bring something useful to this instance, and as much depends on player skill and character levels as does group composition. That said, it's very nice to have reliable [[Crowd Control]] from a [[Mage]], good healing from a suitably geared and/or spec'd [[Paladin]], [[Priest]], [[Druid]] or possibly [[Shaman]], as well as some form of [[out of combat]] [[Resurrection]] and [[Wipe Recovery]] from a [[Paladin]], [[Priest]] or [[Shaman]] unless the group is overpowered for the instance, very competent or just plain ready to do a corpse run or two.\r\n==Walkthrough==\r\nThe temple is split up into two main sections, the first is mandatory for completing the main run of the dungeon (where you defeat the [[Shade of Eranikus]]), whereas the second section is the basement - a completely optional section, however there are two enemies there that have good drops ([[Spawn of Hakkar]] and [[Atal'alarion]]). Each of these two main sections contains a few floors - the main section has a top floor, a middle section (balconies), and a bottom (the dragon pit area). The basement also has a top and a bottom. In between the two main sections are staircases.\r\nIf you don't have a lot of time to spare, stick with the main section and focus on the related quests or loot you are looking for (for experience, just explore wherever). However, if you do have time to take on the basement, you'll want to go there first.\r\n===Optional: The Basement===\r\nFrom the start of the instance, head forward and to the left. Run down to the bottom of one of the stairwells (not the two spiral staircases available from the instance entrance). The hallway area you reach is a giant ring around the main basement floor; this hallway contains [[Murk Worm|Murk Worms]] (aggressive) and [[Maggot|maggots]] (neutral), however the maggots will aggro if you get in a fight so if there are any you can pick off, it's better to be safe than sorry. Note that there is sometimes a rare spawn that patrols this hallway, it looks like a wind serpent.\r\nInside the circular hallway there are tunnels that lead to balconies in the inner chamber. Each balcony contains a serpent statue - by activating the statues in a specific pattern (south, north, south west, south east, north west, north east) you will summon [[Atal'alarion]]. If you want to save time here, you'll have to try and minimize the number of groups you take on in the circular hallway (although the running distance to avoid mobs may be just as burdensome).\r\nAfter summoning [[Atal'alarion]], jump down to the left of the balcony you are standing on and clear the mob and any patrols around you. Heal up, and hop down into the shallow water. Wait for Atal'alarion to move away from the Murk Worms and try to pull them without aggroing him - fighting them together can be painful. He hits hard, so try to stun or CC him and keep your tank over healed (if you have someone with additional healing abilities you may want to use them; potions are also recommended).\r\nFrom the pit of water, head straight up the stairs, down the hall, and up the spiral staircase back to the entrance of the instance.\r\n===Main area===\r\nThe 6 Protectors\r\nIn the main section of the instance, you'll first want to head forward and to the left, and head up the stairwell to the top tier of the dungeon. This area is a giant circular hallway that goes around the pit in the center. Your goal is to kill the six Atal'ai trolls who protect Jammalan's area. You'll find each troll on a separate balcony around the center of the pit. To get to a balcony, follow the circular hallway and take each of the six hallways that lead out of it (three head inwards, and three head outwards and then have a hallway that leads back to the center).\r\nThroughout the hallway you'll encounter many mobs that come in groups of four to six. CC as many of them as you can (shackle, polymorph, sap, etc.) and have your tank keep aggro on all of them. Have your DPS characters take out the imps and trolls first, and finally take down the large troll.\r\nFor the hallways that extend outwards, you'll find a group of mobs at the bottom of the stairs, so don't go rushing down until your party is ready.\r\nThe six trolls are quite easy, but are all different. One is a [[Warlock]] that can summon up to three demons (imp, voidwalker, and succubus), and one is a warrior.\r\nJammalan\r\nThe Dreamer\r\nOptional - Hakkar\r\n----\r\n==Resources==\r\nSkinning\r\n* [[Heavy Leather]]\r\n* [[Thick Leather]]\r\n* [[Rugged Leather]]\r\n* [[Heavy Hide]]\r\n* [[Worn Dragonscale]]\r\n* [[Green Dragonscale]]\r\n==Dungeon Denizens==\r\n* [[Bog beast]]s\r\n* [[Dire troll]]s\r\n* [[Green dragonflight|Green]] [[dragon]]s (one, at least)\r\n* [[Green dragonflight|Green]] [[dragon whelp]]s\r\n* [[Green dragonflight|Green]] [[dragonspawn]]\r\n* [[Green dragonflight|Green]] [[drake]]s\r\n* [[Grell]]s\r\n* [[Maggot]]s\r\n* [[Ooze]]s\r\n* [[Serpent]]s\r\n* [[Skeleton]]s (one, at least)\r\n* [[Snake]]s\r\n* [[Troll]]s\r\n* [[Wind serpent]]s\r\n* [[Worm]]s\r\n* [[Zombie]]s\r\n==Loot==\r\nSee [[Temple of Atal'Hakkar loot]].",},
			["Temple of Atal'Hakkar loot"] = { content = "This is a page listing loot to be found in [[Temple of Atal'Hakkar]]. For information about the instance itself, see [[Temple of Atal'Hakkar]].\r\n==Trash Mobs (BoEs)==",},
			["Temple of Bethekk"] = { content = "'''Temple of Bethekk''' is a subregion of [[Zul'Gurub]], accessed by turning right at the first crossroads past the [[Naze of Shirvallah]]. It is where [[High Priestess Arlokk]] and her [[panther]] minions can be found. To get to her, the raid must first fight their way down through the interior of the temple, which has four levels including the basement where Arlokk is.",},
			["Temple of Karabor"] = { content = "#REDIRECT [[Black Temple]]", redirect = "Black Temple",},
			["Temple of Storms"] = { content = "The '''Temple of Storms''' is a mysterious temple located in [[The Storm Peaks]] of [[Northrend]]. It was [[Titan]]-made. It’s similar to the [[Wyrmrest Temple]] down in the [[Dragonblight]]. This temple sits on one of the tallest peaks, right along the western border, so just beyond it the cliffs drop to [[Icecrown Glacier]]. A wide path, one of the only straight channels in this region, leads to massive stone steps that stop at the temple’s front door. [[Crystal golem]]s stand guard at the perimeter, barring access. Shapes can be seen moving around within: massive shapes, too big to be anything but storm giants. The Titans must have built this, but its unknown if it was for themselves or for the giants.\r\nEither way, the Titans have long since vanished and the giants claim this temple as their own. Occasionally lightning can be seen flickering from the dome — not down to it but up from it — perhaps they’re doing something more than worship in there.\r\n==In World of Warcraft==\r\nLocated in west-central [[Storm Peaks]] atop the highest mountain in all of [[Northrend]], [[Thorim]] sits on its throne surrounded by circling [[proto-dragon]]s.",},
			["Temple of Telhamat"] = { content = "The '''Temple of Telhamat''' is a [[draenei]] stronghold and religious site on the northwestern frontier of the [[Hellfire Peninsula]]. The temple is an [[Alliance]] port of call and a good gateway for travelers venturing into [[Zangarmarsh]].\r\n===Flight===\r\n [[Honor Hold]]\r\n [[Telredor]]\r\n==Temple of Telhamat NPCs==\r\nLocated near the top of the hill, the Temple's inn features a mailbox and several NPC's:\r\n* '''[[Caregiver Ophera Windfury]]''' (a play on Oprah Winfrey), Innkeeper\r\n* '''[[Amaan the Wise]]''' (quest-giver)\r\n* '''[[Elsaana]]''' (quest-giver)\r\n* '''[[Anchorite Alendar]]''' (unknown NPC)\r\nThere is also a forge and an anvil, immediately outside the inn across the path, for use by miners and smiths.\r\nThe Temple features a selection of small buildings with various vendors and NPC's including:\r\n* [[Rumatu]] (unknown NPC, at top of hill)\r\n* [[Kuma]], Hippogryph Master\r\n* [[Burko]], Medic (located in medical tent)\r\n** Sells ''Master First Aid - Doctor in the House'' (teaches advanced first aid to 375, requires first aid 300); ''Manual: Netherweave Bandage'' (teaches to make netherweave bandage, which requires first aid 330; requires 1 netherweave cloth, heals 2800 dmg over 8 seconds); ''Manual: Heavy Netherweave Bandage'' (teaches heavy netherweave bandage, which requires first aid 325 to use and first aid 360 to make; requires 2 netherweave cloth, heals 3400 dmg over 8 seconds)\r\n* [[Vodesiin]], Reagent Vendor\r\n** Sells ''Formula: Runed Adamantite Rod'' (requires adamantite rod, 8 greater planar essence, 8 large prismatic shard, one primal might, runed fel iron rod; requires enchanting 350 to make/use; limited supply)\r\n* [[Yaluu]] (unknown NPC)\r\n* [[Provisioner Anir]], Food & Drink Vendor\r\n* [[Talaara]], Weapon Merchant\r\n* [[Anchorite Obadei]] (quest-giver)\r\n==Flight paths==\r\nThe Temple of Telhamat's gryphon flight paths connect to:\r\n* [[Honor Hold]], Hellfire Peninsula (main Alliance town in Hellfire Peninsula)\r\n* [[Telredor]], [[Zangarmarsh]] (Alliance town)\r\nSee also:\r\n* on the .",},
			["Temple of the Damned"] = { content = "The first '''Temple of the Damned''' was a dark [[temple]] constructed by the [[orc]]s in [[Azeroth]]. It was destroyed in the [[First War]] by the [[human]] forces. \r\nLater Temples of the Damned — called ''Grombolar'', or bowels of the giant in the Orcish tongue — are the cabalistic dwellings of the dead. Created by [[Gul'dan]] to house his blasphemous [[Death knight|Death Knight]]s, the Temples were formed from petrified carcasses of the race of [[Draenor giant|giant]]s that inhabited the [[Orc]]ish [[Draenor|homeworld]]. The subterranean labyrinth of the Temple contains the fetid halls where the Death Knights dwell and study their depraved necromancy on fallen warriors reaped from the battlefields above.\r\nIn the [[Third War]], the [[Scourge]] took over the structures. Once used by the orcish horde to channel demonic energies, the Scourge has now reclaimed this powerful edifice. From the Temple the insidious [[Necromancer|necromancers]] emerge to animate fallen corpses and the tormented spirits of the [[Banshee|banshees]] are called into service.\r\nIn World of Warcraft, the [[Undercity]]'s [[Magic Quarter]] has a Temple of the Damned in it.",},
			["Temple of the Moon"] = { content = "'''The Temple of the Moon''' is the dwelling of the [[Sisters of Elune]], and the center of all [[Night Elf]] spiritual life. It is said that [[Elune]] Herself resides here in spirit.\r\nThough every Night Elf religious building is technically a \"Temple of the Moon\" (the building now known as the [[Tomb of Sargeras]] was once a Temple of the Moon) the term now refers almost exclusively to the temple in Darnassus.\r\n[[Tyrande Whisperwind]], the religious leader of the Night Elves can be found on the second level.\r\nThe Temple of the Moon received new music in patch 2.3. The music inside now sounds more \"celestial\".",},
			["Temple of Tides"] = { content = "The '''Temple of Tides''' is a [[Naga]] unit building that trains [[Mur'gul Slave]]s and [[Mur'gul Reaver]]s. It is also a returning point for resources. It helped both [[Illidan]] and [[Vashj]] in their efforts. It is found on Warcraft III Frozen Throne Expansion Human and Night Elf Campaigns.\r\n==Statistics from Warcraft III==\r\n* 1500 HP\r\n* trains [[Mur'gul Slave]]s and [[Mur'gul Reaver]]s\r\n* returning point for resources\r\n* provides 15 food\r\n* 5 fortified armor",},
			["Temple of Wisdom"] = { content = "A temple southwest of the [[Halls of Stone]].",},
			["Temple of Zin-Malor"] = { content = "The '''Temple of Zin-Malor''', aka Elune's temple, is an ancient building situated near the [[ruins of Eldarath]]. It was once a prominent [[night elven]] temple devoted to the worship of their goddess [[Elune]]. Its similarity to the nearby [[Temple of Arkkoran]] is striking, and they both have a very similar build to the current [[Temple of the Moon]] in [[Darnassus]]. The temple is nowadays occupied by the [[Spitelash Naga|Spitelash]] [[naga]] under the leadership of [[Warlord Krellian]], who himself inhabits the temple in a place of honor.\r\nIt may have been the original temple as it is called \"Elune's temple\".",},
			["Temporal Parasite"] = { content = "'''Temporal Parasites''' are level 55-57 [[maggot]]s that feed on the strands of time's altered flow. Temporal parasites are a common malady present wherever the flow of time has been tampered with. They now infest the silos of [[Andorhal]] in the [[Western Plaguelands]]. A blue pulse of distortion is their only visual marker. \r\n==Quests==\r\n*A Matter of Time",},
			["Temporus"] = { content = "'''Temporus''' is the second [[mini-boss]] of [[Opening the Dark Portal]] in [[Caverns of Time]]. He is a [[drake]] of the [[Infinite Dragonflight]] that spawns upon the opening of the 12th portal.\r\n==Attacks & Abilities==\r\n*[[Hasten]]: Increases melee and movement speed by 200%. Self-buff, considered a magical effect. Can be dispelled/purged. \r\n*[[Mortal Wound]]: Used on the primary target; reduces healing taken by 10 % for each application; can stack up to 7 stacks. Failing to dispel '''Hasten''' buff will make this attack land in shorter intervals and when it stacks above 6-7 debuffs, healing is near impossible.\r\n*This boss is '''IMMUNE''' to taunt. It may be a good idea to let your warrior stack sunder 3-5 times or druid get in a few lacerates before your dps does much besides DoTing up the boss.\r\n'''Heroic Ability: Spell Reflection''' - A blue shield will appear around Temporus' head, and will reflect all spells back at their casters. As far as I can tell, it cannot be dispelled.\r\n==Strategy==\r\nThe main two aspects of this fight are his Mortal Wound and Hasten. \r\n*Mortal Wound is a stacking debuff which reduces the effect of healing by 10%. This attack stacks quickly and can only be mitigated with [[dodge]]/[[parry]]/[[block]]/miss. A priest's [[Power Word: Shield]] and trinkets with similar effects can also mitigate the effect.\r\n*Hasten is a self buff and increases his movement and attack speed by 200%. If you can dispel this, the dragon will put out much less DPS, and has a lower total chance of applying the Mortal Wound debuff to the tank. The Hasten buff can also be removed using [[Spellsteal]].\r\nMove the dragon off to one the side of the gate where he spawns, so that he will not stand between Medivh and the gate. This will prevent any of the small dragons accidentally aggroing on your group (healers and DPS should get out of the path to Medivh as well. If you still have a [[Chrono-beacon]], you can spawn a Time Keeper on the path of the small dragons to keep them away from Medivh for some time, but do not spawn your time keeper too close to the boss or else he will instantly despawn it. A well geared protection warrior (good pre-Karazhan level gear) should be able to survive even at high levels of debuff as long as Temporus is taken down quickly. Shield wall, block, last stand, and other abilities will help. It also helps to have a higher block rating because a successful complete block will prevent an additional stack of the debuff from being applied.\r\nIt is, however, extremely important to dispel his hasten effect when it appears. One effective strategy is to heal the tank with heal over time spells and spot heals as needed, while mashing Dispel throughout the fight. Doing this will usually result in almost no extra damage from the hasten effect, resulting in a very easy fight even with the Mortal Wound debuff.\r\nIf you have a mage throw up a detect magic early, that helps. Otherwise, be on the lookout for white rings to appear around his feet as an indicator that his hasten buff is up. The effect can be purged. As long as he is not hastened, your tank may be able to run out of the Mortal Wound debuff range once it stacks too high (usually around four debuffs), and Temporus will not be fast enough to keep up with him. Once the main tank is out of range the stack of debuffs on him will fade, and he can then return and resume hitting him. Make sure your tank does not move too far from the portal when waiting or Temporus will reset. \r\nAnother good option if the debuffs start stacking up too high is to position the tank on one side of the rift with a party member 20 to 25 yards from the tank directly opposite the boss on the other side of the rift, once the timer on the debuffs starts getting low have the warrior use the intervene ability on the party member and run ahead of the boss till the debuffs wear off. /fly \r\nThe use of [[Luffa]] trinket no longer clears the stack of the [[Mortal Wound]] as of patch 2.010.\r\n*Our group has found that the tank moving in small backwards circles will move him out of melee range frequently enough to wipe the buffs from him, allowing him to solo tank the boss for the duration of the fight.\r\n*For druid tanks, since we can't block or parry attacks, or intervene, the debuff will stack faster than on a warrior, having a paladin healer for the encounter is the best bet because he can cast Blessing of Protection on you until the stacks wear off, having a rogue evade tank Temporus for the short time it takes for the stack to wear off is a good idea to counter an otherwise unleashed hurt machine. A few lacerates should be enough to gain back aggro combined with a vanish.\r\n==Notes==\r\nDue to the stacking nature of his debuff, you may use another player to temporarily pull aggro from the main tank to allow the debuff to expire. However, it is important to note that this mob is NOT tauntable. \r\n*Suggestions for off-tanking:\r\n**Druid - Bear Form\r\n**Shaman -Off-tank with a shield, use Frost Shock and melee attacks to build threat.\r\n**Hunters - Distracting Shot to build threat, Aspect of the Monkey and Deterrence (if available) to mitigate damage. Hunters may also help another class build threat by using Misdirection.\r\n**Rogue - Evasion and Adrenaline Rush (if available).\r\n**Priest - Pain Suppression or Shadow Form to mitigate damage.\r\n**Warlock - Soul Link to mitigate damage, Searing Pain to build threat, Soul Shatter to drop threat.\r\n**Paladin - Righteous Fury and Judgement of Righteousness and Consecration to build threat. Use a shield to mitigate damage. Divine Shield and Blessing of Protection may be used to move threat to the second-highest aggro holder.\r\n==Quotes==\r\nSpawn\r\n*Why do you persist? Surely you can see the futility of it all. It is not too late! You may still leave with your lives ...\r\nAggro\r\n*So be it ... you have been warned.\r\nKill\r\n*You should have left when you had the chance.\r\n*Your days are done.\r\nDespawn Time Keeper\r\n*Keeper! Your sands have run out.\r\nDeath\r\n*My death means ... little.",},
			["Temuejin"] = { content = "'''Temuejin''', the Second Khan, was a [[khan]] of the [[Red Tribe]] of [[centaur]]s. He commanded from [[Spearhold]] in [[Desolace]]. Some have said that he had so great a supply of arrows in his armory that his archers could volley for three days before exhausting their ammunition.\r\n''Note: Temuejin shares the title \"Second Khan\" with [[Gelk]], the deceased founder of the [[Gelkis]] clan.''\r\n''The name Temuejin is obviously based on Temujin, the birth name of Mongol warlord Genghis Khan.''",},
			["Tenaron Stormgrip"] = { content = "'''Tenaron Stormgrip''' is a level 10 [[quest giver]] located in [[Aldrassil]] in the [[night elf]] starting zone, [[Teldrassil]].\r\nHe starts the following quests:\r\n* Crown of the Earth\r\n* Crown of the Earth (2)\r\nSee [[List of Teldrassil NPCs]].\r\n==Quote==\r\n\"''Much has changed with our people since the [[Battle of Mount Hyjal]]. \r\n[[Nordrassil]] lies a pale shadow of what it once was, its power used to defeat [[Archimonde]] and drive back the [[Burning Legion]]...''\"",},
			["Tender Wolf Steak"] = { content = "==Source==\r\nMade from [[Recipe: Tender Wolf Steak]].",},
			["Tendris Warpwood"] = { content = "'''Tendris Warpwood''' is a level 60 [[elite]] [[elemental]] corrupted [[Ancient of War]] that resides in [[Dire Maul]] West. He has taken the [[Ancient Equine Spirit]] prisoner.\r\n==Strategy==\r\nBefore you engage him, it is wise to kill all the [[Ironbark Protector]]s in the area around the entrance, as they are linked with Tendris and will [[aggro]] as soon as you attack. If these are cleared ahead of time, this should not be an especially difficult fight.\r\n==Quests==\r\n*Ancient Equine Spirit\r\n==Quotes==\r\n*You do not belong here! Ancients, rise up against these intruders!",},
			["Tenebron"] = { content = "'''Tenebron''' is a summoned black dragon in the [[Chamber of Aspects]], appearing in the fight with [[Sartharion the Onyx Guardian]].\r\n==Quotes==\r\nIntro: \r\n*It is amusing to watch you struggle. Very well, witness how it is done.\r\nAggro:\r\n*You have no place here. Your place is among the departed.\r\nBreath Attack:\r\n*To darkness I condemn you...\r\nSpecial:\r\n*Arrogant little creatures! To challenge powers you do not yet understand...\r\n*I am no mere dragon! You will find I am much, much, more...\r\nKill:\r\n*No contest.\r\n*Typical... Just as I was having fun.\r\nDeath:\r\n*I should not... have held back...",},
			["Tent"] = { content = "A '''Tent''' is a shelter consisting of sheets of fabric or other material.\r\nMany villages can be seen with tents. The [[Tauren]] and other races are known to use tents for their dwelling.",},
			["Tenth Level Tauren Chieftain"] = { content = "#REDIRECT [[Elite Tauren Chieftain]]", redirect = "Elite Tauren Chieftain",},
			["Ter'lij"] = { content = "'''Ter'lij''' was a lieutenant of [[Zul'jin]], caught in an ambush and killed by [[Halduron Brightwing]] during the invasion of [[Quel'thalas]] during the [[Second War]].",},
			["Terellia"] = { content = "'''Terellia''' is a level 19 trade goods and [[ammo vendor]] located at [[Tranquillien]] in the [[blood elf]] territory of [[Ghostlands]].\r\n==Vendor==\r\n==See Also==\r\n*[[List of Ghostlands NPCs]].",},
			["Terenas"] = { content = "#REDIRECT [[Terenas Menethil II]]", redirect = "Terenas Menethil II",},
			["Terenas Menethil"] = { content = "#redirect [[Terenas Menethil II]]", redirect = "Terenas Menethil II",},
			["Terenas Menethil II"] = { content = "'''Terenas Menethil II''' was the last King of [[Kingdom of Lordaeron|Lordaeron]] and the primary founder of the original [[Alliance of Lordaeron]]. Ruling for over seven decades, including the period of the [[Second War|Second]] and [[Third War]]s, Terenas was considered one of the most powerful human monarchs since the breaking of [[Arathor]]. His death at the hands of his own son ended the [[House of Menethil|Menethil dynasty]] and deprived the Alliance of its leadership at a critical moment in history.\r\n==Biography==\r\nTerenas Menethil II was born in court of the Kingdom of Lordaeron, one of the strongest human nations, as member of the royal Menethil family which had ruled the kingdom for generations. Terenas grew up to become a wise and just ruler, who was greatly loved by his people. His long years of reign saw peace and brought prosperity for Lordaeron, but all this changed with the outset of the [[Second War]].\r\n===The Second War===\r\nAfter the [[First War]], refugees from the Kingdom of [[Azeroth]] arrived on the shores of Lordaeron, giving warnings of the [[orc]]s and the invasion that was to come. Terenas called delegates from neighboring nations, and, after hearing the horror stories from [[Anduin Lothar]] and his people, they agreed to forge the [[Alliance of Lordaeron]]. \r\nTerenas led the forces of Lordaeron in valiant battle against the onslaught of [[Horde (pre-Thrall)|Horde]]. The [[Second War]] was taxing upon the Alliance and all in it. But in the end, their sacrifices were not in vain, and the Alliance won through, decimating the Horde and rounding up the surviving orcs into internment camps, headed by [[Aedelas Blackmoore]]. The orc Warchief [[Orgrim Doomhammer]] was kept as the personal prisoner of Terenas, but he eventually escaped captivity and fled into hiding.\r\n===End of the Second War===\r\nDespite the end of the Second War, peace did not last long. When the troubles began, Terenas immediately decreed, in conjunction with [[Varian Wrynn]], who had assumed his rightful place on the throne of Azeroth, that their best people should travel to [[Draenor]] to retrieve the artifacts stolen by the [[Shadow Moon Clan]].\r\nSome years later, the matter of what to do with the Kingdom of [[Alterac]] came up. [[Lord Prestor]], who appeared to be a relative to the late [[Lord Perenolde]], was one of Terenas' trusted advisors during this time, and Terenas began to arrange a marriage for Prestor to his young daughter [[Calia]]. Prestor was endorsed by most Alliance nations as the new king of Alterac, solving everyone’s and particularly Terenas’ political nightmare. This plan was scrapped, however, when Prestor suddenly disappeared.\r\n===The Reign of Chaos===\r\nAs time wore on, Terenas grew more and more infirm, and he struggled to hold together the collapsing Alliance, despite all his pleas with the dissident nations, [[Gilneas]], [[Stromgarde]] and [[Quel'Thalas]]. His son, [[Arthas]], became the prized protégé of [[Uther the Lightbringer]], and a Paladin of the [[Silver Hand]]. \r\nAs the troubles began with the orcish uprisings through [[Arathi]], as well as the [[Plague]] spreading from the North, many of the Alliance representatives, especially the ones from [[Dalaran]], were pleading for a quarantine. But Terenas refused, saying that the people of Lordaeron had suffered enough. The [[Medivh|mysterious prophet]] unexpectedly materialized during a council of the Alliance, and he pleaded with Terenas to make haste to [[Kalimdor]] or all would be lost. Terenas, however, paid no heed, thinking him little more than a madman. It was here that King Terenas sealed his fate.\r\nTerenas heard of Arthas' strange behavior, especially his excursion to [[Northrend]] and destruction of [[Stratholme]], and he immediately ordered the troops recalled. But still, no word was heard for some time.\r\n===Murder and burial===\r\nFinally, Prince Arthas returned, victorious over the evil he had faced in Northrend. All of Lordaeron Capital rejoiced in festival, celebrating the long-awaited return of their heroic Prince. But something was amiss. \r\nAs he knelt before his father, a dark voice flooded the thoughts of Arthas, and he rose up, drew his sword, and approached the throne, taking his father by the throat, and driving the dark runeblade, [[Frostmourne]], through his heart. Thus did Terenas of the House of Menethil, King of Lordaeron, die at the hands of his own son - bringing an end to not only his reign, which had lasted for seventy years, but also to the Kingdom of Lordaeron itself.\r\nTerenas' ashes were kept in a magical urn, guarded by Uther the Lightbringer himself. Arthas, desiring the urn for his own ends, slew the great paladin, and discarded his father's ashes. The king's remains were recovered and interred reverently, behind the throne room of Lordaeron:\r\nIt is unknown who interred the remains, though speculation would point to Forsaken who still feel some residual loyalty to Lordaeron.\r\n==Quotes==\r\n*\"Noble countrymen, evil is upon us. Darkness has befallen our shores. Rise and slay thy enemies… strike, strike so others shall live. The meek shall not fade into the night… live my brethren, live.\"\r\n*\"A people cannot survive because it can gather in a city - a city survives because it is where the people gather.\"\r\n*\"I will ''not'' institute quarantine without proof of your claims, Ambassador. The people of Lordaeron have suffered enough without becoming prisoners in their own lands.\" - ''Warcraft III: Reign of Chaos''\r\n*\"I don't know who you are or what you believe, but this is not the time for rambling prophets! Our lands ''are'' beset by conflict, but it shall be ''we'' who decide how best to protect our people, not ''you''!\" - to [[Medivh]], ''Warcraft III: Reign of Chaos''\r\n*\"I will summon my neighboring kings. These events concern us all.\" - to [[Anduin Lothar]], ''Tides of Darkness''",},
			["Terenthis"] = { content = "'''Terenthis''' is a level 15 [[quest giver]] located in [[Auberdine]] in the [[night elven]] zone of [[Darkshore]].\r\nHe starts the following quests:\r\n* The Hunter's Path\r\n* How Big a Threat?\r\n* How Big a Threat? (2)\r\n* Thundris Windweaver\r\n* A Lost Master\r\n* A Lost Master (2)\r\nSee [[List of Darkshore NPCs]].",},
			["Terestian Illhoof"] = { content = "'''Terestian Illhoof''' is a corrupted [[satyr]] located in [[The Repository]] of [[Karazhan]]. He hides in a secret passage behind a bookshelf in the library. Cleansing of his presence will halt the respawning of demons directly by the bookshelf. He is an optional boss, but his loot table makes his death profitable to most adventurers. \r\n==Overview==\r\nTerestian Illhoof, along with his minion Kil'rek, is an optional boss in the library section of Karazhan. Both have a low-aggro range - you can sneak around the side at the start, and rez everyone in the room with no difficulty.\r\n===Terestian===\r\n* '''Basic Melee''' - Illhoof hits for around ~1800 damage on a tank.\r\n* '''Shadow Bolt''' - Illhoof fires a ~4000 damage Shadow Bolt at the highest target on the aggro list.\r\n* '''Sacrifice''' - A random character is summoned to the center of the room and is paralyzed, suffering 1,500 unresistible (and unabsorbable) shadow damage per second until the chains (which count as a creature) are destroyed. While the chains are up, Illhoof is healed for 3,000 health per second. The chains have roughly 13,000 health. Can be removed with Ice Block or Divine Shield. Cannot be cast on the main tank (although it CAN be cast on someone tanking Kil'rek). A druid can use barkskin while chained up, which will ultimately reduce the damage while in the chains from 1500 to about 1300 damage per second.\r\n* '''Berserk''' - After 10 minutes, Illhoof goes berserk, spamming high-damage Shadow Bolt Volleys on the entire raid every few seconds.\r\n===Kil'rek===\r\n* '''Basic Melee''' - Hits for 2,000 on cloth.\r\n* '''''' - Undispellable debuff that increases fire damage taken by 500. This is applied to a random target.\r\n* '''Broken Pact''' - Debuffs Illhoof on death, making him take 25% more damage until Kil'rek respawns (~45 seconds after death).\r\n===Summoned Imps===\r\n* '''Basic Melee''' - Around 400, generally used if aggro target is fire immune or in close proximity.\r\n* '''Firebolt''' - Deals 200 fire damage, up to 700 if Amplify Flames is on the target. Quick casting.\r\n===Overview===\r\n* Illhoof and his imp aggro when you pull him. After around 10 seconds, he emotes and summons two portals from the back of the room. Imps continue to pour out of these portals at a steady rate throughout the entire fight.\r\n* If Kil'rek is killed, he respawns after roughly 45 seconds and rejoins the fight.\r\n* When Illhoof sacrifices anyone, they appear in the circle in the middle of his room.\r\n* Staying bunched close to Illhoof is a good idea. Illhoof and Kil'rek both should be tanked near the circle where the Sacrifice happens. This makes it easy to quickly switch from Illhoof/Kil'rek to the chains. Bunching also makes sure the warlock's [[Seed of Corruption]] hits a lot of imps.\r\n===Tanking===\r\n* Depending on the strategy used, one or two tanks should suffice for this fight.\r\n* Illhoof is not particularly hard to tank, although he needs to be kept near the imps he summons so that he receives AoE damage as well.\r\n* Kil'rek, his imp, can be problematic because he spawns in the middle of battle, which generally leads to him attacking an AoE class or a healer. A standard warrior, druid, or paladin tank works. Even moonkin druids, hunter pets, and voidwalkers work fine, so long as they get attention from the healers.\r\n* If steady AoE is used, imps should be on that class the entire fight. Note that if the imps are not immediately hit, they may aggro on the healers.\r\n* If only one tank is used to tank both Illhoof and Kil'rek, they should be kept out of the AoE to avoid Kil'rek aggroing on the AoE.\r\n* Note that a Paladin tank with [[Fire Resistance Aura]] can effectively tank Illhoof, Kil'rek, and many of the imps by spamming [[Consecrate]] with [[Righteous Fury]] active. The healing received will refill the Paladin's mana pool via [[Spiritual Attunement]].\r\n===Kill priority===\r\n* The most important thing in the fight is to destroy Demon Chains as soon as they appear. Demon Chains should go down REALLY fast, not just because the Sacrifice victim will die very quickly but also because Illhoof will heal a lot during it AND the designated Demon Chain healer will lose more mana spamming heals.\r\n* As of 2.3 [[Wound Poison]] does affect the healing from chains along with [[Mortal Strike]] and [[Aimed Shot]].\r\n* The Demon Chains may be vulnerable to some DoTs (e.g., poison) and AoE, although chains should be dying fast enough to make the former of little use. The Chains are not vulnerable to Blast Wave, Dragon's Breath, Arcane Explosion, or Consecration.\r\n* Kil'rek can be either slowly killed via AoE or rapidly killed as soon as he spawns. Killing him rapidly reduces the danger of losing your AoE to Amplify Flames, but can make tanking problematic for the off tank. Killing Kil'rek first will ensure that he has the Broken Pact debuff on longer. As long as you can kill Kil'rek in under roughly 10 seconds, you will do more damage by killing him and reaping the benefit of Broken Pact.\r\n* If it takes longer than 10 seconds to kill Kil'rek focus DPS on Illhoof and allow Kil'rek die from AoE/off-tank. This results in more damage to Illhoof.\r\n* The following macro is hugely useful in selecting targets for this chaotic fight:\r\n<pre>/cleartarget&#x000D;/target Demon Chains&#x000D;/stopmacro [nodead, harm]&#x000D;/target Kil'rek&#x000D;/stopmacro [nodead, harm]&#x000D;/target Terestian Illhoof</pre>\r\n===Dealing with Imps===\r\n* The easiest way to kill off the spawning imps is a pair of warlocks spamming [[Seed of Corruption]] on Illhoof or on the imps themselves. Hellfire also works. The imps rarely live long enough to hit the warlocks. One warlock also works fine. \r\n* Because the imps have an own aggro table it is most likely that at a certain point in the fight multiple imps will attack one of the healers or aoe caster, causing much spell pushback. Therefore it's wise to keep all healers and aoe casters in one group with Concentration aura. If there is a Shaman or second Paladin available it might be wise to also use Fire Resistance Totem or Aura in this group. Keeping up Earth Shield on the Warlock would be a wise choice. The [[Nether Protection]] talent, an [[Earthen Elixir]], [[Dampen Magic]], [[Blessing of Sanctuary]] and [[Power Word: Shield]] are also able to help.\r\n* If no warlocks are available, well geared mages may suffice.\r\n* If your AoE is not up to the task, designate one high-damage melee DPS (well-geared rogue or cat) to burn them down one at a time. The Kil'rek tank can help clean up any left-overs when Kil'rek is down.\r\n* To give warlocks and other AoEs a break, the imps can also be feared.\r\n* Another extremely effective way to deal with the imps without warlocks is to release shaman fire elementals. Chances for effective kill go up dependent on the spell damage of the shaman or shamans and the number of shaman. But the use of chain lightning and the elemental pretty much guarantee a downing of the imps. This fight is absolutely not dependent on locks alone as many have come to believe. Shaman are also extremely effective in this fight as well. The only class with an AOE pet which does not draw aggro to the player.\r\n===Dealing with Sacrifice===\r\nAt least one healer with a quick reaction time should be designated to heal sacrifice victims. A paladin works well here, since they can bubble out of it if they themselves become sacrificed.\r\n* If you have trouble keeping sacrifice victims alive, have each healer use one mid-level heal on the victim at the start of the effect, to provide a cushion of health for the main sacrifice healer to work with. At least one of these heals should land quickly enough to keep the victim alive while the other heals are cast.\r\n* Illhoof's Sacrifice has a three-second cast time and it's the only occasion for which he changes his target to someone other than the main tank. If Healers are using addons that supply them with a \"Main Tank Target's Target\" such as CT_Raid, or use Healer Bbuttons, Clique or [target=mouseover] macros for healing which allow them to heal while constantly keeping Illhoof targeted, it will give them some seconds of advance warning on who is about to be sacrificed.\r\n* Mages can use [[Ice Block]] and Paladins can use [[Divine Shield]] to get themselves out of a sacrifice. Druids can use [[Barkskin]] to reduce damage taken. [[Divine Intervention]] will also dispel a sacrifice if a soulstoned [[paladin]] who is low on mana opts to use it when Illhoof is close to death.\r\n* Healers need to be prepared for pushback when the person handling imp AoE is sacrificed, as they draw aggro from a rapidly increasing number of imps. [[Concentration Aura]] helps, as does a [[Challenging Shout]]/[[Challenging Roar]]/[[Holy Wrath]] from the tank. \r\n* Here is a useful healer macro that will help improve sacrifice response time tremendously - use your own spell of predilection in place of regrowth:\r\n<pre>/stopcasting&#x000D;/target Demon Chains&#x000D;/target targettarget&#x000D;/cast Regrowth</pre>\r\n*Keep Illhoof as close to the Sacrifice circle as possible so that Melee can make an easy switch to bring the chains down ASAP.\r\n*Hunters can drop a snake trap. Illhoof sometimes sacrifices a snake instead of a player character, making things much easier.\r\n*A bug exists where if a member moves in between getting teleported and getting bound by the chains, they will still take damage even after the chains go down. If Illhoof casts Sacrifice while targeting you, be sure to not move. Typically, this should not concern anyone but melee DPS that have to move for Kil'rek or the chains.\r\n==Quotes==\r\n'''Aggro''' ''Ah, you're just in time. The rituals are about to begin.''\r\n'''Sacrifice''' ''Please, accept this humble offering, oh great one.''\r\n'''Sacrifice''' ''Let the sacrifice serve his testament to my fealty.''\r\n'''Summon''' ''Come, you dwellers in the dark. Rally to my call!''\r\n'''Summon''' ''Gather, my pets. There is plenty for all.''\r\n'''Killing A Player''' ''Your blood will anoint my circle.''\r\n'''Killing A Player''' ''The great one will be pleased.''\r\n'''Death''' ''My life, is yours. Oh great one.''",},
			["Teribus the Cursed"] = { content = "'''Teribus the Cursed''' is a level 65 elite [[undead dragon]] soaring the skies over [[the Bone Wastes]] in [[Terokkar Forest]].\r\nHe probably was a member of the [[Black Dragonflight]] in life (the only flight present in outland), and may have been reanimated by the Auchenai Draenei or even by D'ore during his regeneration, but who actually reanimated him is unknown. \r\n==Quests==\r\nTeribus is the objective of Evil Draws Near.",},
			["Terms of Service"] = { content = "#REDIRECT [[Terms of Use Agreement]]", redirect = "Terms of Use Agreement",},
			["Terms of Use Agreement"] = { content = "The '''Terms of Use Agreement''' is a legally binding agreement which has to be ratified before one is able to play [[World of Warcraft]]. Players must accept this agreement when they install the game or a patch. It governs your use of and conduct on the [[World of Warcraft]] servers.\r\nThis is different from the \"[[End-User License Agreement]]\" ([[EULA]]) or \"[[License Agreement]]\". You must agree to the EULA before installing or patching World of Warcraft.",},
			["Terocone"] = { content = "'''Terocone''' is a [[Herb]] that can be gathered by [[Herbalist]]s.\r\n==Source==\r\n'''Terocone''' can be gathered from nodes in [[Terokkar Forest]], [[Arakkoa]]-based areas in [[Shadowmoon Valley]], and occasionally from harvesting the corpses of [[fungal giant]]s in [[Zangarmarsh]]. Terocone nodes are typically found underneath trees. Requires 325 Herbalism to gather.\r\n==Terocone as an Ingredient==\r\n'''Terocone ''' is used in the following recipes:\r\n===[[Alchemy]]===\r\n* [[Elixir of Draenic Wisdom]]\r\n* [[Elixir of Major Agility]]\r\n* [[Elixir of Major Defense]]\r\n* [[Elixir of Mastery]]\r\n* [[Elixir of the Searching Eye]]\r\n* [[Fel Strength Elixir]]\r\n* [[Flask of Relentless Assault]]\r\n* [[Haste Potion]]\r\n* [[Heroic Potion]]\r\n* [[Insane Strength Potion]]\r\n==Notes==\r\nGathering a Terocone will occasionally yield [[Mote of Life]] in addition to the herb.\r\nTerocone generally sells quite well, mostly likely because it is primarily found in only one region of the [[Outland]], as opposed to [[Felweed]] and [[Dreaming Glory]], which are found in almost all zones.",},
			["Terokk's Mask"] = { content = "==Source==\r\nThis item is a quest reward from Terokk's Legacy.",},
			["Terokk's Quill"] = { content = "</noinclude>\r\n''For the quest item, see [[Terokk's Quill (quest item)]].''\r\n==Source==\r\nThis item is a quest reward from Terokk's Legacy. It is considered one of the best hunter polearms from a non-raid instance, though some favor the Sonic Spear dropped by [[Murmur]] in the [[Shadow Labyrinth]].",},
			["Terokk's Quill (quest item)"] = { content = "==Source==\r\nThis item drops from [[Talon King Ikiss]] in the [[Sethekk Halls]] wing of [[Auchindoun]]. \r\n==As a quest objective==\r\nTerokk's Legacy\r\n==Notes==\r\nThis item can be looted by everyone in the party as long as the player has the quest.",},
			["Terokk's Rest"] = { content = "[[Terokk's Rest]] is an island in [[Blackwind Lake]] located in [[Skettis]] in southeastern [[Terokkar Forest]]. It is only available to those who have flight. As of Patch 2.1, there exists a questline to summon and slay [[Terokk]], the god of the arakkoa, at this location.",},
			["Terokk's Shadowstaff"] = { content = "'''Terokk's Shadowstaff''' is an epic two-handed staff for DPS casters.\r\n==Source==\r\nThis item drops from [[Talon King Ikiss]] in [[Sethekk Halls]] (heroic mode).",},
			["Terokk"] = { content = "'''Terokk''' was the greatest king of the [[arakkoa]]. Terokk was associated with the goddess [[Rukhmar]] and believed to be her incarnation, though this was not actually the case. Terokk was the arakkoa's greatest hero who was betrayed by his own allies and afflicted with the Curse of Sethe. Even in this state, however, he sought to aid his fellow refugees by building the city of [[Skettis]] with his own claws. However the curse soon began to drive him to madness, and he was sealed away by his Talonpriests in the hopes of rejuvenating him. He now waits in the shadows to be called back into the physical world and face the enemies of his people. \r\nThe heretical [[Talon King Ikiss]] claims he is Terokk returned. \r\nTerokk also has an avatar in the form of a gigantic [[kaliri]], unleashed on Shattrath when all of his plans are thwarted by adventurers at the behest of the Skettis refugees of the [[Lower City]]. \r\n===On Draenor===\r\nSix hundred years before the opening of the [[Dark Portal]], Talon King Terokk was an ancient king of the arakkoa of the [[spires of Arak]]. He was beloved by the people and would often wear a mask to walk among them in hiding. The closest individual to Terokk was his daughter [[Lithic]], who crafted a golden bangle for him that he always wore. He shared power with an order of priests called the Anhar.\r\nTerokk had many enemies, among them [[Warp Stalker|stalkers]], [[Wind Serpent|wind serpents]], [[Colossus|colossi]], and even fellow arakkoa. One enemy in particular was [[Pridelord Karash]] of the [[Bloodmane tribe|Bloodmane]] [[saberon]], who once declared war against the arakkoa. His torment of the arakkoa caused them to wonder why their sun goddess [[Rukhmar]] had seemingly withdrawn her favor. Rather than send his troops, Terokk arrived to the battlefield in person and slaughtered most of the saberon. Terokk's victory over [[Pridelord Karash]] caused the arakkoa to celebrate Terokk as a living legend. Indeed, they even claimed him to be Rukhmar's reincarnation. The Anhari priesthood began to grow nervous, for up until this point they alone had been allowed to speak in the sun goddess's name. Terokk used his widespread support to build a new city, [[Skyreach]], that called back to the accomplishments of the ancient [[Apexis]]. He created new laws restricting the authority of the Anhar order, declaring that high arakkoan society must be guided by a thirst for knowledge and wisdom, not by fear and superstition.\r\nBut however much his people loved and respected Terokk, the Anhari at Skyreach were jealous of him. Hungry for control, they conspired against Terokk and tossed both him and his daughter Lithic into the pools at [[Sethekk Hollow]], which were formed eons ago in the death of the primal god [[Sethe]]. While Terokk survived the fall, Lithic did not; in his despair, Terokk surrendered to the darkness as his body withered and contorted, transforming Terokk into a flightless shadow of his former self. From that day forward Skyreach would be ruled not by a king but by the Anhari, now calling themselves the [[Adherents of Rukhmar]]. \r\nA presence called Terokk from the brink of despair, however. [[Anzu]], the great [[dread raven]] god, urged Terokk forward. Now mutated and flightless but with powers of darkness, Terokk moved forward and rallied his fellow broken arakkoa who the Adherents had also tossed into the pools. They moved through the Sethekk Hollow until they came across [[The Eye of Anzu]] and met Anzu for the first time.\r\nAnzu gifted Terokk and his followers [[Void|dark]] powers and [[arcane]] sorcery. In time, they would come to be known as [[Talonpriest]]s. Together, Terokk, Anzu, and the Talonpriests would build the refuge city of [[Skettis]] among Apexis ruins and protect the unwanted children of Rukhmar: the [[Arakkoa Outcasts]]. The regions of [[Talador]] near to the Spires of Arak came under their control and became known as [[Terokkar Forest]].\r\nWhen the winged arakkoa learned of the results of Terokk's exile, rumors of his cursed state swept like wildfire through the arakkoa, giving rise to superstitious charms and cures. Eschewing traditional arakkoan weaponry, Terokk carried a cudgel as a symbol of his fall from king to outcast heretic. Rumors have persisted for centuries that rather than employing traditional wing-cutting as a punishment, Terokk simply shattered the beaks of those who dared to oppose him.\r\nAs the years went on Terokk's health declined, grief tore at his heart, and Sethe's curse chewed at his mind. He began to hate the world, abandoning Skettis and even sacrificing the lower castes of his own people to dark powers in search of a cure. The arakkoa did not seem to know the reason for this abandonment and attributed it to them turning away from the worship of Rukhmar. Hoping to rejuvenate their king, the Talonpriests sealed Terokk away in the shadows. All that was left of Terokk were several artifacts he left behind. But Terokk was foretold to return some day.\r\n===The Burning Crusade===\r\nTerokk seemingly surrendered completely to the madness of the Curse of Sethe during his long imprisonment in the shadows, and by the time of the War in Outland his minions worked in his name to commit evils throughout Terokkar Forest. At [[Veil Shienor]] and [[Veil Reskk]], the Eyes of Skettis allowed Terokk to spy on those areas. At [[Veil Skith]], the arakkoa used the [[Darkstone of Terokk]] as an altar of worship. At [[Veil Rhaze]], the spirits of arakkoa slain in the Auchindoun explosion remained with Terokk's influence remaining on them. At [[Veil Lithic]], his minions corrupted [[kaliri]] into his service. At [[Veil Shalas]], the closest colony to Skettis, the arakkoa [[sage]]s conducted wars against the Light.\r\nSome arakkoa, such as [[Kirrik the Awakened]] and [[Rilak the Redeemed]], believe that Terokk is a false prophet who will lead them to their doom. These [[Skettis Exiles]] moved to [[Shattrath City]] and face the forces of Terokk in the name of the [[Light]]. Meanwhile, the heretical [[Talon King Ikiss]] believes himself to be Terokk reborn and leads the [[Sethekk]] cult in the [[Sethekk Halls]].\r\nBut deep inside Skettis, the arakkoa continue their battles against all who oppose them. The [[Sha'tari Skyguard]], a group of Sha'tari flyers, have a base at Blackwind Landing, just outside of the Blackwind Valley where Skettis is located. On [[Terokk's Rest|an island in the middle of Blackwind Lake]], Terokk awaited the proper alignment of the stars to herald his return. Working with [[Hazzik]], adventurers summoned the maddened husk of the Talon King before he was ready and ended the once mighty arakkoa's life.\r\n==Objective of==\r\n* [[Terokk's Downfall]]\r\n==Quests==\r\n[[Terokk's Rest]], a massive summoning circle with an [[Ancient Skull Pile]] in the center, is located at the center of [[Blackwind Lake]] in the heart of [[Skettis]]. In Patch 2.1, a questline was introduced that in the end requires the player to summon Terokk himself at this location and destroy him once and for all. The final quest is [[Terokk's Downfall]].\r\n==Terokk's ancient enemies==\r\nTerokk, be he [[god]] or [[mortal]], is said to have had many enemies in the past. It is not certain if these enemies were groups led by the individuals (more likely as many were sacrificed to dark powers when Terokk sought a cure to the curse), or just the individuals, of the following races who were his enemies: an Arakkoa, a [[Colossus]], a [[Warp Stalker]], and a [[Wind Serpent]]. Their descendants are being held prisoner by Skettis talonpriests who are likely waiting to kill them at the right time since Terokk himself says, when defeated, \"The stars are not yet aligned...my powers fail me!\" due to being summoned prematurely. In the quest [[A Shabby Disguise|A Shabby Disguise]], it is prophesied that their demise will be followed by Terokk's return. Apparently, when his enemies and any of their descendants are finally gone, he has the power to return.\r\n==Defeating Terokk==\r\nTerokk has the following abilities:\r\n*'''Shadowbolt Volley''': Does about 1.8k Shadow damage to everyone in his vicinity. A paladin's shadow resistance aura or a priest's shadow protection can help to counter this.\r\n*'''Chosen One''': One person on his aggro list is made the chosen one for about 10 seconds, increasing his size, damage and healing while everyone else's damage and healing is decreased.\r\n*'''Immunity Shield''': At 25% health he raises a shield that makes him 100% immune to all physical and magical attacks. To shatter the shield you have to drag him to the \"blue smoke markers\" where the Sha'tari Skyguard will drop bombs. When his shield is down he will go into a '''Frenzy''', increasing his damage and the frequency of his shadowbolt volleys. Throw everything you got at him when his shield is down. After a few seconds he will raise his immunity shield again. Simply repeat until he is dead. The tank can already pull him towards another near marker while the shield is down, if present. It is rather tricky to lure him into the upcoming fire and not get the dot as well, so don't waste your time running around the marker, just go through.\r\n*'''Frenzy''': Increases the casters attack speed by 50% and the physical damage it deals by 100% for 10 min.\r\n==The relics of Terokk==\r\nTerokk was once revered by the arakkoa people, but one day mysteriously vanished, leaving his three artifacts behind: His spear, his mask and his writings. All were taken by the renegades of the Sethekk, led by the [[Talon King Ikiss]]. All three drop as quest items, but only one can be chosen as a quest reward.\r\n*[[The Relics of Terokk]]\r\n**Terokk's Quill: Terokk's spear. The stats of this weapon make it an ideal weapon for hunters. The spear is held by [[Talon King Ikiss]].\r\n**Terokk's Mask: The mask of Terokk provides increased attack power and dodge rating, ideal for rogues and feral druids. The mask is held by [[Darkweaver Syth]].\r\n**The Saga of Terokk (off-hand): Terokk's book is a powerful tome that increases spell damage and healing. It is located in some kind of ritual circle in the room before Talon King Ikiss.\r\n==Quotes==\r\nSummoned\r\nMakes a player the Chosen One\r\nUses Immunity Shield\r\n==Drops==\r\n*Terokk's Wisdom\r\n*Terokk's Might\r\n*Terokk's Gavel\r\n*Gift of the Talonpriests\r\n*Brooch of the Immortal King\r\n*Skystalker's Leggings\r\n*Slatesteel Leggings\r\n*Time-Lost Figurine\r\n==Time-Lost Figurine==\r\nA must-have drop from this mob is called the [[Time-Lost Figurine]], used to turn their character temporarily into a Arakkoa. While in this form going into combat does not change the player back, making this a fun and near must-have for many players. The difficulty, length, and rareness of obtaining the item however make it so players with it are scarce.",},
			["Terokkar"] = { content = "#REDIRECT [[Terokkar Forest]]", redirect = "Terokkar Forest",},
			["Terokkar Forest"] = { content = "'''Terokkar Forest''' is a zone in [[Outland]] located east of [[Nagrand]], west of [[Shadowmoon Valley]], southeast of [[Zangarmarsh]], and southwest of [[Hellfire Peninsula]]. This forest was most likely named after [[Terokk]], an [[arakkoa]] demigod of some sort.\r\nTerokkar was seen as the [[Bone Wastes]] in previous maps and lore sources, but the Bone Wastes themselves are now a sub-region within the Terokkar Forest zone (in fact probably not the same Bone Wastes, as the current one was created only two years ago, according to ingame lore). May be one of the \"[[Green Havens]]\" replanted by druids to be like it was before the Horde necromancy and fel magic corrupted the land.\r\n==History==\r\nTerokkar is most famous for the [[Bone Wastes]] and the ruined fortress of [[Auchindoun]].\r\nWorldofwarcraft.com says the following about the Terokkar Forest:\r\n''New hope has come to this ancient forest. Aided by the benevolent naaru, a group of draenei has rebuilt Shattrath City. The city has since thrown open its doors to welcome refugees of many different races from all over Outland. Yet the past has not left this area unmarked. To this day, only adventurers and graverobbers visit the haunted subterranean ruins of [[Auchindoun]].''\r\n==Geography==\r\nThe flora consists of mostly dark green forest vegetation of crystal pines known as olemba trees. [[Shattrath City]] lies in the northwestern portion of zone. Alliance and Horde each have a town.\r\nThe multi-winged instance [[Auchindoun]] can be found in this zone, containing four separate 5-man dungeons. There are no raid dungeons, micro dungeons, battlegrounds, or arenas in this zone. The spirit towers of the [[Bone Wastes]] provide a world PvP opportunity.\r\nEvery so often you can hear a roar while near Auchindoun - this is [[Teribus the Cursed]], flying in circles around Auchindoun.\r\n===World PvP===\r\n* [[Bone Wastes]]: In the Bone Wastes to the south, surrounding the ruins of [[Auchindoun]], there are five Spirit Towers. These spirit towers can be captured by players who are PvP flagged. If all five towers become captured by a single faction, that faction gets a zone-wide [[Blessing of Auchindoun]] aura ([[buff]]) which lasts for six hours. The aura gives +5% Damage, +5% Experience Gain, and the ability to create a Spirit Shard in the [[Auchindoun]] instance. Spirit Shards can be spent at Spirit Sage Gartok at [[Stonebreaker Hold]] or Spirit Sage Zran at [[Allerian Stronghold]].\r\n===Travel hubs===\r\n [[Allerian Stronghold]]\r\n [[Stonebreaker Hold]]\r\n [[Shattrath City]]\r\n==Notable characters==\r\nArchmage [[Khadgar]] resides in [[Shattrath City]] and can be found in its center.\r\n==Resources==\r\n* [[Herb]]s\r\n** [[Dreaming Glory]]\r\n** [[Terocone]]\r\n** [[Felweed]]\r\n* [[Leather]]\r\n** [[Knothide Leather Scraps]]\r\n** [[Knothide Leather]]\r\n** [[Fel Hide]]\r\n* [[Ore]]\r\n** [[Fel Iron Ore]]\r\n** [[Adamantite Ore]]\r\n** [[Khorium Ore]]\r\n** [[Eternium Ore]]\r\n==Wild creatures==",},
			["Terokkar Forest NPCs"] = { content = "The following [[NPC]]s can be found in [[Terokkar Forest]].\r\n=== Alliance===\r\n* Andarl\r\n** Magical Disturbances\r\n** A Handful of Magic Dust\r\n* Bertelm\r\n** Unruly Neighbors\r\n** Timber Worg Tails\r\n** The Elusive Ironjaw\r\n* Jenai Starwhisper\r\n** Report to the Allerian Post\r\n** Letting Earthbinder Tavgren Know\r\n* Lieutenant Gravelhammer\r\n** Thin the Flock\r\n** Speak with Private Weeks\r\n* Lieutenant Meridian\r\n** Attack on Firewing Point\r\n** The Final Code\r\n* Private Weeks\r\n** Who Are They?\r\n** Kill the Shadow Council!\r\n* Ros'eleth\r\n** Olemba Seeds\r\n** Vessels of Power\r\n* Taela Everstride\r\n** Torgos! (Group)\r\n* Thander\r\n** Stymying the Arakkoa\r\n* Theloria Shadecloak\r\n** The Firewing Liaison\r\n** Thinning the Ranks (Terokkar Forest)\r\n=== Horde===\r\n* Advisor Faila\r\n** Arakkoa War Path\r\n** Speak with Scout Neftis\r\n* Kilrath\r\n** Don't Kill the Fat One\r\n** Because Kilrath is a Coward\r\n* Kurgatok\r\n** A Handful of Magic Dust\r\n** Magical Disturbances\r\n** An Unwelcome Presence\r\n* Malukaz\r\n** Vestments of the Wolf Spirit\r\n** Patriarch Ironjaw\r\n** Welcoming the Wolf Spirit\r\n* Mawg Grimshot\r\n** Torgos! (Group)\r\n* Rakoria\r\n** Olemba Seed Oil\r\n** And Now, the Moment of Truth\r\n* Rokag\r\n** Stymying the Arakkoa\r\n* Scout Neftis\r\n** Who Are They?\r\n** Kill the Shadow Council!\r\n* Sergeant Chawni\r\n** Attack on Firewing Point\r\n** The Final Code\r\n* Shadowstalker Kaide\r\n** What Happens in Terokkar Stays in Terokkar\r\n** The Firewing Liaison\r\n* Tooki\r\n** Letting Earthbinder Tavgren Know\r\n** Report to Stonebreaker Camp\r\n* Unkor the Ruthless\r\n** Success! (Horde Quest)\r\n=== Neutral===\r\n* Akuno\r\n** Escaping the Tomb\r\n* Artificer Morphalius\r\n** Safety Is Job One (Dungeon)\r\n* Chief Archaeologist Letoll\r\n** Digging Through Bones\r\n* Commander Ra'vaj\r\n** An Improper Burial\r\n** A Hero Is Needed\r\n** The Fallen Exarch\r\n* David Wayne\r\n** The Hermit Smith\r\n** Additional Materials\r\n** Fresh From the Mechanar (Dungeon)\r\n** The Lexicon Demonica (Dungeon)\r\n** Tear of the Earthmother\r\n** Underworld Loam (Dungeon)\r\n** Bane of the Illidari\r\n** Quenching the Blade\r\n* Dwarfowitz\r\n** Fumping\r\n** The Big Bone Worm (Group)\r\n* Earthbinder Tavgren\r\n** Strange Energy\r\n** Clues in the Thicket\r\n** By Any Means Necessary\r\n** What Are These Things?\r\n** What Are These Things?\r\n* Empoor\r\n** Wind Trader Lathrai\r\n* Ethan\r\n** Missing Friends\r\n* Field Commander Mahfuun\r\n** The Codex of Blood (Group)\r\n* Greatfather Aldrimus\r\n** Everything Will Be Alright (Dungeon)\r\n* Ha'lei\r\n** I See Dead Draenei\r\n* Hazzik\r\n** Hazzik's Bargain\r\n** A Shabby Disguise\r\n** Adversarial Blood\r\n* High Priest Orglum\r\n** The Tomb of Lights\r\n** The Vengeful Harbinger (Group)\r\n* Isfar\r\n** Brother Against Brother (Dungeon)\r\n** Terokk's Legacy (Dungeon)\r\n* Isla Starmane\r\n** Escape from Firewing Point! (Group)\r\n** Escape from Firewing Point! (Group)\r\n* Kirrik the Awakened\r\n** Speak with Rilak the Redeemed\r\n** Veil Skith: Darkstone of Terokk\r\n** Veil Rhaze: Unliving Evil\r\n** Veil Lithic: Preemptive Strike\r\n** Veil Shalas: Signal Fires\r\n** Return to Shattrath\r\n* Lakotae\r\n** The Infested Protectors\r\n* Mekeda\r\n** Before Darkness Falls\r\n** The Shadow Tomb\r\n* Nexus-Prince Haramad\r\n** Undercutting the Competition (Dungeon)\r\n* Oakun\r\n** The Dread Relic\r\n** Evil Draws Near (Group)\r\n* Ramdor the Mad\r\n** Helping the Lost Find Their Way\r\n** Ezekiel\r\n* Scout Navrin\r\n** Taken in the Night\r\n* Severin\r\n** World of Shadows\r\n** More Shadow Dust (Repeatable)\r\n* Sky Commander Adaris\r\n** Secrets of the Talonpriests\r\n** An Ally in Lower City\r\n** Terokk's Downfall\r\n* Sky Sergeant Doryn\r\n** Fires Over Skettis (Daily)\r\n* Skyguard Handler Deesak\r\n** Hungry Nether Rays\r\n* Skyguard Prisoner\r\n** Escape from Skettis (Daily)\r\n* Skywing\r\n** Skywing (Group)\r\n* Soolaveen\r\n** Recover the Bones\r\n* Spy Grik'tha\r\n** Find Spy To'gun (Dungeon)\r\n* Vindicator Haylen\r\n** For the Fallen\r\n** Terokkarantula (Group)\r\n** Return to Sha'tari Base Camp\r\n* Warden Treelos\r\n** It's Watching You!\r\n==Class Trainers==\r\nNone\r\n=== Neutral===\r\n* Anchorite Ensham\r\n=== Alliance===\r\n* Cecil Meyers\r\n* Fabian Lanzonelli\r\n* Innkeeper Biribi\r\n* Leeli Longhaggle\r\n* Spirit Sage Zran (PvP Rewards)\r\n* Supply Officer Mills\r\n=== Horde===\r\n* Bar Talet\r\n* Dod'ss\r\n* Innkeeper Grilka\r\n* Rungor\r\n* Spirit Sage Gartok (PvP Rewards)\r\n=== Neutral===\r\n* \"Slim\"\r\n* Aundro\r\n* Dealer Tariq\r\n* Grella\r\n* Horvon the Armorer\r\n* Morula\r\n* Provisioner Tsaalt (General goods)\r\n* Ruogo\r\n* Sahaak\r\n* Siflaed Coldhammer\r\n* Skraa\r\n=== Alliance===\r\n* Furnan Skysoar\r\n* Innkeeper Biribi\r\n=== Horde===\r\n* Innkeeper Grilka\r\n* Kerna\r\n* Trag",},
			["Terokkar Forest PvP Rewards"] = { content = "#REDIRECT [[Terokkar Forest PvP rewards]]", redirect = "Terokkar Forest PvP rewards",},
			["Teronis' Corpse"] = { content = "'''Teronis' Corpse''' is a level 20 [[quest giver]] located on the island in [[Lake Falathim]], in the [[contested]] territory of [[Ashenvale]].\r\nIt gives the quest Raene's Cleansing (2).\r\nSee [[List of Ashenvale NPCs]].",},
			["Teronis"] = { content = "#redirect [[Teronis' Corpse]]", redirect = "Teronis' Corpse",},
			["Teron Gorefiend"] = { content = "''For information on how to defeat Teron Gorefiend in World of Warcraft, see [[Teron Gorefiend (tactics)]].''\r\nIn life, '''Teron Gorefiend''' was one of [[Gul'dan]]'s acolytes. In death, he became the first of the necromantic terrors that became known as [[death knight]]s — the warriors promised by Gul'dan to appease [[Orgrim Doomhammer]], and combat the human mages' powerful magic.\r\n==Biography==\r\nTeron Gorefiend was a member of the [[Shadow Council]], Gul'dan's clandestine conclave of warlocks and necromancers that had ruled the Horde through the puppet Warchief [[Blackhand]]. When the Horde assaulted the Temple of Karabor, many draenei clerics were taken prisoner and were told that they were being marched to Hellfire Citadel far to the north. Outside the walls of the temple, Gorefiend took the lives of every last one of them. The spirits of the clerics of Karabor remain outside the walls to this day.\r\nWhen Gul'dan was incapacitated as the result of being in [[Medivh]]'s mind when he was killed, the Shadow Council was discovered by Orgrim Doomhammer. Doomhammer had recently come to power through the assassination of Blackhand, and tortured [[Garona Halforcen]] to discover the Council's location. The majority of its members, including Gorefiend, were killed by the Doomhammer's furious surprise attack.\r\nWhen Gul'dan recovered from his catatonic state and was on the verge of joining the Shadow Council in death, he \"submitted\" to Doomhammer's authority and promised to create warriors to fight for the Horde and counter the powerful magic of the humans. Doomhammer allowed him to live, to carry out this promise. Gul'dan took the corpses of the fallen Knights of Stormwind, and intended to imbue the rotting corpses with the souls of the Shadow Council. Nothing worked until he decided to sacrifice the necrolytes and cut out their hearts, which were transmuted into powerful jewels, which were then affixed into truncheons. Upon making this stride, Gul'dan informed Doomhammer of his success. Placing the first truncheon into the hand of one of the corpses, the warlock and the Warchief watched as the energies of the necrolyte's heart that powered the weapon coursed through the corpse, until its eyes finally opened. Teron Gorefiend had returned.\r\nGorefiend, [[Gaz Soulripper]] and the other death knights swore allegiance to Doomhammer and fought for the Horde, where their powerful energies aided in many battles. When Gul'dan betrayed the Horde, Gorefiend remained in the service of the Warchief until he was defeated. Leading the death knights beyond the Dark Portal before its destruction, Gorefiend remained on Draenor until [[Ner'zhul]], Gul'dan's former master, came to the forefront and united the remaining clans into the [[Horde of Draenor]]. Ner'zhul intended to open new dimensional gateways to other worlds, and needed powerful items to stabilize them. To that end, Ner'zhul sent Gorefiend through a reconstructed Dark Portal to claim two powerful artifacts required for his spell: The [[Book of Medivh]] and the [[Eye of Dalaran]]. First, Gorefiend entered the [[Royal Library]] in [[Stormwind City|Stormwind]], only to find the Book gone and the guard slain with an [[Alterac]] blade.\r\nAfter failing to gain the support of the sons of Blackhand, Gorefiend encountered [[Deathwing]], the insane and scheming [[Dragon Aspects|Aspect]] of the [[Black Dragonflight]], who offered aid in exchange for being allowed to travel to [[Draenor]]. Gorefiend rode on Deathwing's back as they travelled to Alterac, where Gorefiend demanded the Book from its imprisoned king, [[Aiden Perenolde]]. Perenolde agreed to turn over the Book in exchange for the Horde slaying their Alliance wardens. Upon securing the Book of Medivh, Gorefiend - again, with Deathwing providing transport, his dragons carrying the warriors - flew to [[Dalaran]] where he was able to take the Eye from its secure vault. With his prize in tow, Gorefiend flew away, with the Eye in tow. Gorefiend rejoined the Horde and made the march with Ner'zhul to the [[Black Temple]] to perform the ritual. In the end, it was all for naught; Ner'zhul fled with his chosen followers in tow, leaving the Horde leaderless and stranded on Draenor as it tore itself apart from the unstable rifts he had created. Gorefiend himself fell in battle against Turalyon on that fateful day, but his spirit rose from his broken death knight corpse and escaped into the skies.\r\nAfter this defeat, the remaining death knights travelled to Shadowmoon Valley. The death knights, showing their allegiance, knelt before Gorefiend, or whatever was left of him after his physical demise; in response, Gorefiend beheaded them (they rose once more, as the [[Ghostriders of Karabor]]). His spirit, however, became trapped, and eagerly seeks a willing host to free him...\r\n==The Burning Crusade==\r\nAt the [[Altar of Shadows]] in [[Shadowmoon Valley]], there resides an [[Ancient Shadowmoon Spirit]], a ghostly orc who appears to be an expert on the history of Teron Gorefiend. After completing the early quests with the [[Spectrecles]] in [[Wildhammer Stronghold]] (Alliance) or [[Shadowmoon Village]] (Horde), you are sent to the Altar of Shadows to speak to this orc ghost, who does indeed know of Gorefiend.\r\nThe Ancient Shadowmoon Spirit sends you on a set of three quests to locate Gorefiend's regalia, items that he used in his \"life\", that may aid in locating him.\r\n===The Locations of Gorefiend's Regalia===\r\nTwo of the three items can be found at or near the walls of the [[Black Temple]].\r\n*Gorefiend's Cloak: The easiest item to obtain, Gorefiend's cloak drops from the spirits of the [[Cleric of Karabor|Clerics of Karabor]] that line the walls of the Black Temple. The drop rate is somewhat low, so you will have to kill many of the Clerics in order to obtain the cloak.\r\n*Gorefiend's Truncheon: The jeweled truncheon that was the source of Gorefiend's necromantic powers is held by the [[Ghostriders of Karabor]], who patrol the roads around the Black Temple. There are four riders present, so it is recommended that you have a friend to aid you in slaying them. However, you can also just kill one, loot the truncheon, and run away to safety (or die in the process).\r\n*Gorefiend's Armor: This item is the most difficult to obtain. The armor is in the possession of [[Vhel'kur]], an undead [[Black Dragonflight|spawn]] of [[Deathwing]], who flies in a circle around the floating island of [[Netherwing Ledge]]. Vhel'kur is a 70 elite, and it recommends a five-man group. In addition, flying mounts (or a warlock and two others with flying mounts) are required to reach Netherwing Ledge.\r\n===A Dark Secret Revealed===\r\nThe Ancient Shadowmoon Spirit claims to be using the items to divine Gorefiend's location. Upon returning the items to the spirit, you find out the truth: the spirit IS Gorefiend, and he managed to convince you to return his gear to him.\r\nAfter taking back his regalia, Gorefiend possesses your body, trapping your spirit in the Altar of Shadows. Upon being possessed, [[Karsius the Ancient Watcher]], Gorefiend's ethereal [[draenei]] jailor, spawns, and the battle begins once you attack him. While you are possessed by Gorefiend, a small bar appears with Gorefiend's spells - Unholy Armor, Death Coil, Death and Decay, and Haste, powers he is seen to wield in Warcraft II. It is recommended that in the battle with Karsius, you use Unholy Armor and Death Coil as often as you are able, and Death and Decay periodically as well; Death Coil will heal you significantly and drain Karsius' HP.\r\nAfter you defeat Karsius, you are freed, and Gorefiend mounts his undead steed (epic skeletal mount) and rides off towards the Black Temple, shouting that he has returned. With a heavy heart, you return to the quest giver in [[Wildhammer Stronghold]] or [[Shadowmoon Village]], and are tasked with destroying Gorefiend (seeing as it was your actions that unleashed him).\r\n===Changes in Patch 2.1===\r\nGorefiend appears to have found a place for himself within the [[Black Temple]], which opened in [[Patch 2.1.0|Patch 2.1]]. The reasons for Gorefiend's joining Illidan — if he has done so at all — is unclear, but he must be at least tolerated by Illidan to be allowed to remain in his fortress.\r\nPrior to this patch, when he possessed the bodies of players, Gorefiend appeared to be an orc wearing modified [[Corruptor Raiment]], the warlock [[Tier 5]] armor. When Patch 2.1 went live, his model in the Black Temple was changed to give him an appearance that better fit the lore — the spirit of an orc trapped in the body of a dead human knight. This model was accordingly used for the Altar of Shadows event.\r\n==Black Riders rumor==\r\nNOTE:Some most of these speculations are outdated, retained only for historical reasons.\r\nPrior to the introduction of the Black Temple, a theory was circulated that the [[Black Rider]]s of [[Deadwind Pass]] are the remaining death knights that Gul'dan created. Fans suspected that Teron Gorefiend was the leader of the Black Riders, and possibly had some connection to the [[Worgen]] infestation of [[Duskwood]].\r\n[[Ner'zhul]] had promised Gorefiend a world to rule over if he aided him in opening multiple portals on Draenor. So when Ner'zhul opened the portals and the massive energy began to tear Draenor apart, Gorefiend and his Knights may have decided to make good on Ner'zhul's promise and fled through one of the Portals. Some believed that the world Gorefiend arrived in was the world of the Worgen. According to popular theory, the Worgen's homeworld became compromised by the invading [[Burning Legion]], and Gorefiend laid out a plan to have himself and the Worgen moved to the only other intact world he knew of.\r\n[[Prince Malchezaar]] has since been revealed as the current ruler of Karazhan, casting much doubt on the supposed link between Gorefiend and the Black Riders. The link was further discredited when Gorefiend was discovered having been imprisoned in Outland.\r\n[[Brann Bronzebeard]] mentions this rumor in [[Horde Player's Guide]] while discussing several ideas about who is in control of the tower: one of the ideas he mentions is that Teron Gorefiend maybe leading the dark riders from the tower of Karazhan, but he adds that the dark riders are possibly being controlled by someone or something more sinister. Other ideas included Sargeras or a mysterious, hitherto-unseen being.\r\n",},
			["Teron Gorefiend (tactics)"] = { content = ":''This article is about the in-game raid boss. For character biography and other appearances, see [[Teron Gorefiend]].''\r\n'''Teron Gorefiend''' is a [[boss]] in the [[Black Temple]]. The fight is basically a [[DPS race]], with a twist. Killing Gorefiend is a prerequisite for opening the door leading to [[Mother Shahraz]]. He's usually killed fourth when clearing BT.\r\n===Teron Gorefiend===\r\n* '''Health''': 4,100,000\r\n* '''Mana''': 1,693,500\r\n* '''Melee''': ~6k normal hit on plate (can crush and crit)\r\n* '''Incinerate''': Cast on a random target and does 2,775 to 3,225 fire damage on impact. Also applies a debuff to the target which does an additional 8,325 fire damage over three seconds. Debuff can be dispelled by priests and paladins.\r\n* '''Doom Blossom''': A dark cloud appears for over two minutes which casts Shadow Bolts for approximately 1,500 shadow damage at random targets. More than one Doom Blossom can be active at once.\r\n* '''Crushing Shadows''': Cast on five random raid members and applies a fifteen second debuff which increases shadow damage taken by 60%.\r\n* '''Shadow of Death''': Cast every 30 seconds on a random target and applies a debuff which kills the target after 55 seconds. When the target dies (by the debuff or any other reason), four Shadowy Constructs spawn at the target's corpse and the target turns into a Ghost for 60 seconds.\r\n===Shadowy Constructs:===\r\n*'''Melee''': ~300 on cloth\r\n*'''Shadow Strike''': Melee attack doing roughly 2,500 shadow damage. Not resistible.\r\n*'''Atrophy''': 60 second debuff applied on melee hit which decreases attack speed by 5%, stacks up to 10 times. Not removable.\r\n*'''Immune''': Immune to all attacks by normal players, can only be harmed by players in the Ghost form\r\n*'''Aggro''': random aggro on normal raid members, attack Ghosts only after all other players are dead\r\n===Ghost form player===\r\n* '''Spirit Strike''' - key '1' - A melee attack which does 638 to 862 frost damage and reduces damage dealt by the target by 10% for 5 seconds. Ability can only be used on Teron Gorefiend.\r\n* '''Spirit Lance''' - key '3' - A ranged attack which does 6,175 to 6,825 damage and applies a debuff on the target which reduces its movement speed by 30% for 9 seconds. The debuff stacks up to the three times. Ability has a 30 yard range and can only be used on Shadowy Constructs.\r\n* '''Spirit Chains''' - key '4' - A short-range AoE shackle which does 1,900 to 2,100 frost damage to targets within 12 yards. Targets are held in place for 5 seconds. Ability has a 15 second cooldown and only affects Shadowy Constructs.\r\n* '''Spirit Volley''' - key '5' - A short range AoE which does 9,900 to 12,100 frost damage. Ability has a 15 second cooldown and only affects Shadowy Constructs.\r\n* '''Spirit Shield''' - key '7' - Applies a 30 second buff on a friendly target which absorbs 11,400 to 12,600 shadow damage. Ability has a 1.5 minute cooldown. Because Ghosts last for 60 seconds, this ability can only be used once per Ghost.\r\n==Preparation==\r\nOnly one single tank is needed, all other tanks should switch to DPS or Healing gear. The Gorefiend tank has to deal with solid melee damage. The usual mix of damage dealers and healers (6-8) is reasonable for this fight.\r\nThe whole raid needs the [[Shadow Protection]] buff. [[Cauldron of Major Shadow Protection]] is also really useful. It's possible to wear some extra [[shadow resistance]], but not much - it's a DPS race, not a battle for survival. [[Soulstones]] should be created pre-fight, but not pre-cast. They are needed for healers getting Shadow of Death.\r\nTeron can be tanked right where he stands, and ranged DPS should group behind the MT opposite to the entrance. This gives the whole length of the room for the Ghost form players to kill the Shadowy Constructs.\r\n==Teron Gorefiend==\r\nTeron himself has a relatively low amount of health and must be killed as quickly as possible. It's fairly standard [[tank and spank]], he's not tauntable, but a good tank can control him rather easily. As usual, melee DPS must stand behind him to avoid increasing his attack speed by parries. 3-4 healers should be able to keep the tank up, the other healers should take care of the massive damage the raid takes (this is another fight where [[Chain Heal]] and [[Circle of Healing]] are very effective).\r\nIncinerate (the fire dot) must be dispelled as soon as possible, two Priests or Paladin dispellers should be predesignated.\r\nAll damage enhancing, long-cooldown abilities like [[Bloodlust]] (or [[Heroism]]) should be used as early as possbile after the tank has settled into an initial threat lead.\r\n==Shadow of Death==\r\nEvery 30 seconds, a random raid member (not the person with aggro) receives this debuff. After 55 seconds, the debuff turns the player into a Ghost and spawns four Shadowy Constructs. The Constructs attack the raid, and usually cause a wipe if they succeed. Therefore, the Ghost player must kill them before they reach the raid, by kiting and nuking them with the Ghost abilities.\r\nAfter the 60 seconds ghost phase, the player simply dies. Healers (ex. Shamans with an available Ankh) should get a Soulstone when they receive the debuff, so that they can resurrect at this point.\r\nAbout 15-20 seconds before the debuff runs out, the affected raid member must move to the south end (as far away from the raid as possible). The first action after turning into a Ghost should be to AoE damage the Constructs with Spirit Volley (key '5'), move with the group and then AoE freeze them with Spirit Chains (key '4') as soon as the [[GCD]] allows. During the 15 sec cooldown, the Constructs must be nuked with Spirit Lance (key '3'), which damages and slows a single Construct.\r\nThis is the most difficult phase for the Ghost player - while slowly moving backwards towards the raid, all four constructs must be hit with Spirit Lance in turn to keep them all slowed and close together. Each Spirit Lance should hit a different target (either using the Tab key or mouse for targeting in a rotation). After 15 seconds, a second combination of Volley ('5') and Chains ('4') is available, after that the Constructs should have taken enough damage to die with 2-3 more Spirit Lances.\r\nAfter the four Constructs are dead, it is a good idea to look for Constructs from the next player, and help kill them. If no Constructs are up, it's possible to move to the raid and buff a healer with Spirit Shield ('7'), and then get within melee range of Teron and attack him with Spirit Strike ('1').\r\nSince learning the Kite'n'Nuke technique required for killing the Constructs may be difficult for classes which normally do not kite, and learning it under raid conditions is rather expensive (one wipe per try), it's a good idea if all raid members practice using the before attempting him. The simulator is not a replacement for the real thing, but it gives players the general idea what to expect.\r\nDo not try to exploit this encounter by disconnecting or hearthing out. Doing so immediately spawns the constructs with no friendly ghost to kill them. That is a wipe.\r\n===Notes===\r\n*Players with the debuff should not die by any other cause while still fighting Gorefiend, because in that case the Constructs spawn directly in the raid, and this frequently starts a wipe\r\n*If someone is slow in killing the constructs, the next person with the debuff may draw aggro from a construct while on the way to the back of the room. Healers must be aware of this possibility and keep the running player up\r\n*If there are any problems (like high latency or slow reaction time), it's better to skip the first Spirit Volley. The safest approach in that case is to spam '4' for the last seconds before the debuff runs out, to make sure the Constructs are frozen\r\n*For the tank it's tank & spank and because he hits fairly hard, Gorefiend is usually regarded as an excellent encounter to test threat techniques and maximizing it.\r\n===Ghost controls===\r\nSome UI mods can lead to the Ghost form ability controls to appear at an unexpected location (or even not at all). When preparing for this encounter and using an action bar mod, it's a good idea to test whether the ghost controls are visible. The cheapest method to test this is the [[Battered Steam Tonk Controller]], or a [[Steam Tonk Controller]] crafted by an engineer.\r\nBartender, Bongos3, Dominoes all have an extra action bar called 'posses' bar, which is used when the player takes direct control over another entity. Players should configure their mod so that this bar is visible.\r\n===Avoiding Shadow of Death===\r\nClasses which can remove themselves from combat can completely avoid Shadow of Death. By using [[Vanish]], [[Feign Death]], [[Divine Shield]] or [[Ice Block]] during the cast time of Shadow of Death, players avoid getting the debuff, and Teron does not cast it again until 30 seconds later.\r\nThe ability must be used during the 1 second cast time. Teron regularly targets random players to use one of his abilities, but Shadow of Death is his only ability with a cast time. The targeted player needs to react very quickly, to faciliate this a macro like\r\n /stopcasting\r\n /cast <ability name>\r\nmay be useful. \r\nIf players with these abilities are manage to avoid Shadow of Death, the raid in effect saves one entire Shadowy Construct cycle, which is a big boon.\r\n==Quotes==\r\n*\"I was the first, you know. For me, the wheel of death has spun many times. <laughs> So much time has passed. I have a lot of catching up to do...\"\r\nAggro:\r\n*\"Vengeance is mine!\"\r\nKills a player:\r\n*\"I have use for you!\"\r\n*\"It gets worse...\"\r\nDoom Blossom:\r\n*\"Death...<chuckles> Really isn't so bad.\"\r\n*\"I have something for you...\"\r\nIncinerate:\r\n*\"YOU WILL SHOW THE PROPER RESPECT!\"\r\n*\"What are you afraid of?\"\r\nCrushing Shadows:\r\n*\"Give in!\"\r\nDeath:\r\n*\"The wheel...spins...again....\"",},
			["Terrace of Light"] = { content = "The '''Terrace of Light''' is where the [[Sha'tar]], including [[A'dal]], and [[Khadgar]] reside. It was once heavily defended by the [[Aldor]], but now it is defended by the city's newest faction who has taken up residence in the Terrace of Light, the [[Shattered Sun Offensive]]. A [[naaru]] NPC here will take [[Heroic Mode]] instance tokens in exchange for [[epic]] items.\r\nArchmage [[Khadgar]] has created portals to the eight major cities in [[Azeroth]]: [[Darnassus]], the [[Exodar]], [[Ironforge]], [[Orgrimmar]], [[Silvermoon City]], [[Stormwind City]], [[Thunder Bluff]], and the [[Undercity]]. Any character can use any portal of their own [[faction]]. There is a [[Portal (spell)|portal]] trainer in the middle of the city, affiliated with the [[Sha'tar]] faction. Mages are able to learn a teleport spell to Shattrath at level 60 and a portal spell at level 65. Additionally, after completing the quest Intercepting the Mana Cells enough times, [[Exarch Nasuun]] creates a portal to the [[Isle of Quel'Danas]].\r\nThe [[Aldor]] and [[Scryers]] factions each have a [[bank]] that contains the faction's [[quartermaster]] and their shoulder slot enchant vendor in the Terrace of Light. Allegiance to one faction will result in the loss of access to the other's bank.\r\nThe [[flight point]] for the city is in the neutral section of the city. There is '''not''' an auction house for either faction in Shattrath City, nor are there any [[class trainer]]s.",},
			["Terrace of Repose"] = { content = "The '''Terrace of Repose''' is located on the grounds just north of the [[Scarlet Monastery]]. It is one of the very few places in northern [[Lordaeron]] where the [[Plague of Undeath]] not has reached, and the [[Scarlet Crusade]] have been able to grow green hedges and maintain a fountain with water that is fresh rather than stagnant like the rest of [[Tirisfal Glades]].",},
			["Terrace of the Makers"] = { content = "The '''Terrace of the Makers''' is located in north-central [[Storm Peaks]]. The [[Plain of Echoes]] is to its east while the [[Valley of Ancient Winters]] is to its south.\r\nThe [[Hall of the Shaper]] is situated on the eastern side of the mountain on the terrace and guarded by elite [[iron sentinel]]s.\r\n[[Iron dwarf|Iron dwarves]] are attacking the [[Earthen]] warders guarding the entirety of the terrace.\r\nHalefnir the Sibilant is situated on the stairs in the center of the terrace heading down to the north toward Duronn the Runewrought, who is at the northern edge of the mainland south of [[Ulduar]].\r\n[[The Inventor's Library]] is located to the west of Duronn, its entrance on the northern face of the cliff above a field of [[mechagnome]]s astride [[Mechanostrider]]s who are attacking [[Databank]]s.\r\nFurther to the west is [[Mimir's Workshop]], filled with friendly mechagnome attendants and [[Attendant Tock]].\r\nAtop the terrace is the [[Temple of Invention]], the [[Temple of Order]], and the [[Temple of Winter]], to the northwest, northeast ,and south respectively.",},
			["Terramok"] = { content = "'''Terramok''' is an ancient titan vault, hidden behind a series of spiked barriers in the center of a mesa, located in [[Maraudon]] in [[Desolace]]. Terramok appears to be part of inner Maraudon. There are in-game references to the subzone, namely just as ''Terramok'' or ''the crystal caverns of Terramok''; see the quest [[Quest:Twisted Evils|Twisted Evils]].",},
			["Terran"] = { content = "It is [[language]] spoken by [[earth elemental]]s from the [[Deephome]]. It is also known by conglomerates with the sub-type of earth. Perhaps a dialect of [[Kalimag]].\r\nThe term Terran shows up in the Kalimag phrase, \"Ter'ran\" in the Kalimag language parser.",},
			["Terran Up the Night"] = { content = "\"'''Terran Up the Night'''\" is the fourth song by [[Level 80 Elite Tauren Chieftain]], which made its live debut on August 4, 2007 at the year's annual [[BlizzCon]]. It was written about the glorification of the Terran race, of the [[StarCraft franchise|StarCraft universe]]. To promote the song, [[Blizzard Entertainment|Blizzard]] art director and L80ETC vocalist [[Samwise Didier]] created concept art for the fictional [[Tauren Marine]] StarCraft [[unit]], which depicted the Tauren seen in the band's logo, refitted with a Terran marine's uniform. T-shirts featuring this Tauren Marine, along with lyrics from the chorus of \"Terran Up the Night\" (\"Not protossin', not [[zerg]]in', / I'm terran up the night!\") were also sold at the event. The words \"Udder Chaos\" can also be seen in the Tauren Marine concept art, possibly hinting that this song \"appears\" on Level 80 Elite Tauren Chieftain's fictional 2007 album, Udder Chaos.\r\nIt is uncertain if the band will record a studio version of the song as they had done with \"[[Rogues Do it from Behind]],\" which made its live debut the same night as \"Terran Up the Night.\"\r\n==Cultural references==\r\n* [[Zerg]]\r\n* [[wikipedia:Dr._Evil|Friggin laser beams]]\r\n* [[w:c:starcraft:Siege tank|Siege tank]]\r\n* [[w:c:starcraft:Protoss|Protoss]]\r\n* [[w:c:starcraft:Terran|Terran]]\r\n* [[w:c:starcraft:Space construction vehicle|SCV]]\r\n* [[w:c:starcraft:Battlecruiser|Battlecruiser]]\r\n* [[wikipedia:Zeus|Zeus]]\r\n* [[wikipedia:Thor|Thor]]\r\n* [[wikipedia:Starscream|Starscream]]\r\n* [[Azeroth (world)|Azeroth]]\r\n* [[Horde]]",},
			["Terrordale"] = { content = "'''Terrordale''', nestled in the northwest corner of [[Eastern Plaguelands]], is now a ghost town due to being one of the first human settlements overrun by the [[Scourge]]. It lies west of [[Plaguewood]] and [[Stratholme]], near the entrance to a tunnel that leads to the banks of the [[Thondroril River]].\r\nMuch like the town of [[Darkshire]] may once have been called [[Sunnyglade]], Terrordale likely had a much less morbid name before the invasion of the Scourge. The game and its associated [[lore]] gives no clues as to the haunted town's previous name, however a likely candidate for the name is [[Cinderhome|Cinderhome]].\r\nNo facilities in Terrordale remain for players to use, aside from one delusional fungi merchant, but there are a few quests to be obtained or carried out here.\r\nThis area is some particular interest to those that are collecting [[Crypt Fiend Parts]], as [[Crypt Fiend]]s are very common in Terrordale and its nearby cave, [[Terrorweb Tunnel]]. Wandering the withered grounds of this area is also the neutral level 60 [[Plagued Swine]], considered a very good choice as a pet for Hunters.\r\nOne visiting Terrordale must be careful, as there have been sightings of a [[Nerubian Overseer]] that walks back and forth through the west end of Terror Web Tunnel to an unspecified location in the town itself, seeking a victim to sink it's venom-coated fangs into.\r\n==Quests==\r\n*;The Restless Souls (1)\r\n*:[[Caretaker Alen]] wants you to find his assistant [[Egan]]. Egan lives in a house in Terrordale.\r\n**;The Restless Souls (2) (Dungeon)\r\n**:Egan wants you to patrol [[Stratholme]] and free the souls of the dead.\r\n**:Reward: Testament of Hope\r\n*;Augustus' Receipt Book\r\n*:[[Augustus the Touched]] wants you to find [[Augustus' Receipt Book]] in a nearby building.\r\n*;Exorcising Terrordale\r\n*:Use the [[Exorcism Censer]] to drive out the spirits that torment Terrordale. When you have slain 25 [[Terrordale Spirit]]s, return to [[Lord Grayson Shadowbreaker]] in the Cathedral District of [[Stormwind]].",},
			["Terrordale Spirit"] = { content = "'''Terrordale Spirit''' can be found in [[Eastern Plaguelands]] .\r\nKilling '''Terrordale Spirit''' will result in +5 reputation with [[Argent Dawn]]\r\n==Quests== \r\n==Drops == \r\n \r\n0.02% Chance of an [[epic]] drop.\r\n0.07% Chance of a [[rare]] drop.\r\n0.89% Chance of an [[Uncommon]] drop.\r\n0.20% Chance of a [[common]] drop.\r\n0.89% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Terrorfiend"] = { content = "'''Terrorfiends''' are demons from the [[Burning Legion]] which can be found in [[Hellfire Peninsula]] .\r\n==Quests== \r\n==Drops == \r\n \r\n0.13% Chance of an [[Uncommon]] drop.\r\n0.01% Chance of a [[common]] drop.\r\n0.04% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Terrorguard"] = { content = ":''Were you looking for the [[Crypt Fiend]]?''\r\n----\r\nThe ''fiends'' are a demonic race that are notable for having a face on their chest, six horns coming out of their cylindrical head, a mouth full of large jagged teeth which almost completely circle their head, a small goatee, and a diamond shaped jewel lodged in their forehead. They also have spines coming out of the back part of their hooves and hands. They also have wings and cloven feet, with a general build to that of the [[tarshesite]] of the [[ered'ruin]] race — which may imply that they are a sub-species of the same race. Some fiends also hold the rank of [[doomguard]], such as the fiend known as doomguard [[Overmaster Grindgarr]], which may also prove to be a connection to the ered'ruin. \r\nFiends go by titles such as [[Fear Fiend]], [[Terrorfiend]], and others.",},
			["Terrorweb Tunnel"] = { content = "'''Terrorweb Tunnel''' is a long and winding tunnel into the mountain northwest of [[Terrordale]]. It is full of [[Crypt Fiend]]s ([[Nerubian]]s), and stretches through the mountain from [[Terrordale]] in the north and extends south to the spring of the [[Thondroril River]]. At the entrance from the river, you can find a level 61 ([[elite]]) [[quest giver]], [[Tirion Fordring]]. \r\nOne must be very careful when travelling this path, as not only is this path crowded with many Crypt Fiends, but occasionally a very powerful and elite member of its kind, the [[Nerubian Overseer]], stalks the tunnel.",},
			["Terror of the Tides"] = { content = "'''Terror of the Tides''' is the [[Sentinels]] Campaign in [[Warcraft III: The Frozen Throne]].\r\n==Missions==\r\n*Cinematic: The Awakening\r\n*Chapter One: [[Rise of the Naga]]\r\n*Chapter Two: [[The Broken Isles]]\r\n*Chapter Three: [[The Tomb of Sargeras (WC3)|The Tomb of Sargeras]]\r\n*Chapter Four: [[Wrath of the Betrayer]]\r\n*Interlude: Unfinished Business\r\n*Chapter Five: [[Balancing the Scales]]\r\n*Chapter Six: [[Shards of the Alliance]]\r\n*Interlude: Malfurion's Vision\r\n*Chapter Seven: [[The Ruins of Dalaran]]\r\n*Chapter Eight: [[The Brothers Stormrage]]\r\n*Finale: A Parting of Ways",},
			["Terror Run"] = { content = "Terror Run is the aptly-named area in the Southwestern quadrant of [[Un'goro Crater]]. The area is infested with giant dinosaurs of every type including [[Devilsaur]], [[Pterrordax]], [[Diemetradon]] and [[Stegodon]], some of which are [[elite]].",},
			["Terror Wing Path"] = { content = "'''Terror Wing Path''' is the valley located in the eastern region of the [[Burning Steppes]]. Terror Wing is home to many [[whelp]]s and [[dragonkin]] of the [[Black Dragonflight]]. There are also several black [[drake]]s patrolling the stretch of the valley. The [[Rare mob|rare]] [[Elite creature|elite]] magma giant [[Volchan]] can also occasionally be found wandering through the path. Only the highest level adventurers should journey through Terror Wing Path, and even so it is advised not to do so alone.\r\nThe dragonkin and drakes used to be elites until [[Patch 2.3.0]]",},
			["Terrowulf Packlord"] = { content = "'''Terrowulf Packlord''' is a level 32 [[rare mob]] [[worgen]] found in front of [[the Howling Vale]] shrine in [[Ashenvale]]. He is on a 21-32 hour respawn timer.\r\n==Loot==\r\n*Ruffled Chaplet\r\n*Wolfpack Medallion",},
			["Tervosh"] = { content = "#REDIRECT [[Archmage Tervosh]]", redirect = "Archmage Tervosh",},
			["Test of Faith quest chain"] = { content = "'''Test of Faith''' is a Horde quest chain which begins in [[Thousand Needles]] but will take players around the world, eventually even bringing them to the [[Scarlet Monastery]] library. This quest chain also serves to introduce newer players to the lore behind the World of Warcraft story: The player must collect two books and be prepared to answer questions about them in order to complete the chain. The first book is about the Dragon [[Aspect]]s, and the second is about the origins of the [[Scourge]].\r\nThe full text of the two books can be found:\r\n*[[Legacy of the Aspects]]\r\n*[[Beginnings of the Undead Threat]]\r\n__TOC__\r\n==Tests of Thousand Needles==\r\n[[Dorn Plainstalker]] of [[Thousand Needles]] has been testing young members of the Horde for years. The lessons he teaches are not those of academia: instead, he teaches Faith, Endurance, and Strength. Dorn awaits those who seek to test themselves in a cave known as the [[Weathered Nook]] on the northern cliff face of the [[Thousand Needles]] canyon.\r\n'''Test of Faith'''\r\nDorn Plainstalker presents you with your first test: a test of faith. Transporting you to a high perch above Thousand Needles, he instructs you to jump - if you have faith.\r\nWithout question, you leap from the planks on which you stand... and are teleported once more back to Dorn's cave.\r\n'''Test of Endurance'''\r\nNext Dorn wishes to test your endurance. He sends you to a cave on the south side of the canyon, full of harpies. After destroying their food supplies, you take their leader's claw as proof of your deed, and return to Dorn.\r\n'''Test of Strength'''\r\nFor this test, Dorn suggests you join with others to accomplish the task set before you. This time, Dorn wants you to seek out the powerful earth elemental who prowls Thousand Needles: [[Rok'Alim the Pounder]]. You locate the elemental and do battle with him, finally defeating him and returning to Dorn with the fragments of the once-proud construct. Your third test is complete.\r\n==Lore of the Dragon Aspects==\r\nDorn is not the only one who is tasked with testing young members of the Horde: his associate, [[Braug Dimspirit]], resides in the [[Stonetalon Mountains]] and gives a test of a different sort.\r\n'''Test of Lore'''\r\nYour time with Dorn is done: it is time for the Test of Lore, for which you must travel to Braug Dimspirit outside the [[Talondeep Path]] in [[Stonetalon Mountains]]. He will give you further instructions.\r\nAfter quite a journey, you manage to locate Braug. But you are not yet ready for the test he will give.\r\n'''Test of Lore (2)'''\r\nBefore you can take the Test of Lore, you must find and read the [[Legacy of the Aspects]], a book currently held in the [[Dor'Danil Barrow Den]] of [[Ashenvale]] forest to the north. The book is guarded by the spirits of the night elves, who do not wish to part with it. But you manage to fight your way through and gain access to the book. On your way back to Braug, you study the text as instructed, learning the history and legend behind the first of the great dragons.\r\n'''Test of Lore (3)'''\r\nOnce you are prepared, you give Braug the book and await his question. He asks it: which of the great aspects became the monster Deathwing? You easily answer: Neltharion. Braug nods, satisfied, but you are not yet finished with your test.\r\n==The Origin of the Scourge==\r\nIn addition to Dorn and Braug, there is another who gives tests to new adventurers: [[Parqual Fintallas]] in the [[Undercity]]. A historian in life, his now permanent state gives him plenty of time to study the triumphs and mistakes of the past. Like Braug, Parqual tests young members of the Horde in their knowledge of lore.\r\n'''Test of Lore (4)'''\r\nBraug wants you to learn yet more lore before your testing is complete. To that end, he sends you on to Parqual Fintallas in the Undercity for further instructions.\r\nUpon hearing your story, Parqual seems unimpressed. And it seems he, too, has a task for you before he will give his test.\r\n'''Test of Lore (5) (Dungeon)'''\r\nParqual wants you to collect a very special book held by the [[Scarlet Crusade]] in their library in the [[Scarlet Monastery]], called [[Beginnings of the Undead Threat]]. Gathering a group of other strong adventurers with you, you enter the Scarlet library and steal the book. When you return to Parqual, he seems pleased, and explains that though the [[Scarlet Crusade]] may once have had good intentions, they were now so crazed and zealous that they sought to destroy any who were not among their order.\r\nYou quickly study the book, learning about the origins of the undead. When you are ready, you give the book to Parqual and prepare for your question.\r\n'''Test of Lore (6)'''\r\nParqual asks: What was the name of the creature who became known as the Lich King? Instantly you answer: Ner'zhul. Parqual nods, seeming a bit surprised, and accepts your answer as correct.\r\n'''Final Passage'''\r\nYour tests finally complete, Parqual instructs you to return to Dorn in [[Thousand Needles]] to receive your reward. After your journey, Dorn grants you the choice between a fine hammer or powerful wand. In addition, he promises that all members of the Horde will have more respect for someone who could pass such difficult tests.\r\n==Rewards==\r\nIf the player follows the entire quest chain from beginning to end, he or she will receive:\r\n* Roughly (from quest turn-ins only):\r\n** 16,850 XP\r\n** [[Horde]] <font color=\"green\">+500</font>",},
			["Test of Honor Contest"] = { content = "To celebrate the launch of the Honor System, Blizzard issued a '''Test of Honor Contest'''. This took place in both WoW USA and Europe.\r\nThey gave away top-of-line NVIDIA® 6800 series graphics cards and other prizes to lucky participants that took part in player-versus-player combat; however these prizes where only applicable for the USA contestants.\r\n==How it worked==\r\nEveryone that participated in player-versus-player combat from the time it was patched into the game until the contest ended on May 24th 2005 had a chance to win prizes; ranging from NVIDIA graphics cards to free WoW gametime. The higher your ranking in the Honor System on May 24th, the better your chance of winning was - however anyone that participates has an opportunity to win something. \r\nRanks in the honor system equated to a number of 'virtual tickets' (each ticket was a chance to win) the higher your rank in the honor system, the more tickets you would receive.",},
			["Test of Lore"] = { content = "In '''Test of Lore''', [[Dorn Plainstalker]] sends you to [[Stonetalon Mountains]] to speak with [[Braug Dimspirit]] and continue your test. It is the fourth quest in the [[Test of Faith quest chain]], which is a chain of quest involving \"testing\" some part of the player character's being. The first quest is Test of Faith, which begins in [[The Weathered Nook]] in [[Thousand Needles]], from [[Dorn Plainstalker]].\r\n====To Get This Quest====\r\nAfter completing Test of Strength, talk to [[Dorn Plainstalker]] again in [[The Weathered Nook]] in [[Thousand Needles]].\r\n==Objectives==\r\nFind [[Braug Dimspirit]] near the entrance to [[Talondeep Path]] in [[Stonetalon Mountains]].\r\n==Details==\r\nTo find [[Braug Dimspirit]], head to the [[Stonetalon Mountains]] to [[Windshear Crag]]. At the back of the crag, there is a cave called the [[Talondeep Path]]. Near the entrance to the cave is a hut with the tauren [[Braug Dimspirit]]. Coordinates: (79,46)\r\n==Description==\r\n''Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over.\r\n''If you are prepared, then seek out [[Braug Dimspirit]]--he is a shaman of great wisdom. He will test you further, so heed his words, <name>.\r\n''When you are ready, find the tunnel that connects the [[Stonetalon Mountains]] with [[Ashenvale]]: Braug dwells near there. And be careful, <name>, the night elves may wish to impede your test.\r\n==Completion==\r\n''The days and nights grow colder throughout the world as goblins rape the land, and the night elves point fingers at the younger races. The Forsaken and orcs are not the only ones to blame for the hardships found throughout Kalimdor and Lordaeron. Many of the intelligent races have contributed to the world's pain. Dorn knows this, and he has sent you to me because you have shown the attributes necessary to realize it also.\r\n''Now you stand before Braug.",},
			["Tethis"] = { content = "'''Tethis''' is a level 43 [[named]] male [[raptor]] found in [[Stranglethorn Vale]]. [[Hemet Nesingwary Jr.]] wants Tethis' talon.\r\n==Quests==\r\n*Raptor Mastery (4)\r\n==Loot==\r\n*Talon of Tethis ''(Quest Item)''\r\n==Notes==\r\n*Tethis can be found north of [[Gurubashi Arena]], among other raptors.\r\n*Tethis used to be an [[elite]] mob, but was reduced to normal status along with many other outdoor elite mobs in [[Patch 2.3]].",},
			["Tethris'Aran"] = { content = "#redirect [[Tethris Aran]]", redirect = "Tethris Aran",},
			["Tethris Aran"] = { content = "'''Tethris Aran''' is a series of [[night elven]] ruins found in northern [[Desolace]] just north of [[Thunder Axe Fortress]]. The ruins are inhabited only by the wild creatures of Desolace. The night elven settlement that was here was presumably destroyed by the [[Great Sundering]].",},
			["Tethyr"] = { content = "'''Tethyr''' is a level ?? Elite (Boss), part of the Take Down Tethyr! questline.\r\nTethyr shares its model with The Lurker Below in [[Serpentshrine Cavern]].\r\n==Tactics==\r\nUse the three mortars on the docks to do massive amounts of damage to Tethyr. Using the mortars will cause Tethyr to Spout along that side of the dock. The Spout causes a knockback but otherwise does no damage. Getting knocked too far away from the dock will cause the quest to fail. Kill Tethyr before he kills all of the bowmen on the docks.\r\n==Objective of==\r\nTake Down Tethyr!",},
			["Thaddius"] = { content = "'''Thaddius''' is a [[Flesh titan]] that resides somewhere deep inside the cursed necropolis [[Naxxramas]]...\r\nYour raid cleared out the last group of monsters, and the only thing left are the two gates at the very end of the room. All of a sudden, the mighty gates fly open. A vast laboratory filled with all kinds of strange machinery lies before you, electric discharges and lightning painting the walls with jagged shadows. Even though you know you should be trying to rally your raid you can't help but stare at the monstrosity in the center of the room. At the last second you snap out of it and barely escape a fierce blow by of one of the two gruesome wights that descended from platforms higher up in the room. As your raid forms up and mounts a first organized attack on the creatures, you can't help but wonder what other nightmares lie in wait in the cursed depths of Naxxramas.\r\nYou get the feeling you'll find out soon enough.\r\n'''Thaddius''' is a [[boss]] in [[Naxxramas]]. The theme of this boss is similar to that of Dr. Frankenstein's Monster, creating something akin to an [[Abomination]] in that it is sewn together of human parts, but also part machinery.\r\n==General Information==\r\n*Adds: Feugen, Stalagg\r\n==Attacks and Abilities==\r\nThaddius has around 6.7 million HP according to SWStats taken of a kill.\r\n===Phase 1===\r\n*Stalagg has a war stomp ability that does around 1500 physical damage, and does not stun. In addition, he will randomly get a buff called Power Surge which increases his attack speed by 200% and lasts 8 seconds. As well, he breaks the normal rules for crushing blows. Everything that isn't dodged, parried, or blocked will be crushing, it is imperative that healers be on the ball and that tanks keep Shield Block up.\r\n*Feugen has an AoE mana drain ability and a War Stomp AoE that deals about 1500 physical damage to everyone in melee range.\r\n*Both sub-bosses initially stand near lightning rods. If a sub-boss is pulled away from these rods, they will chain-lightning the raid. Every 20.6 seconds both sub-bosses knock the current tank over to the other platform, forcing a tank transition. They are both vulnerable to taunt.\r\n===Phase 2===\r\n*Every 30 seconds he will give everyone in the raid either a positive or a negative charge (even distribution of charges), which appear as debuffs. Every 5 seconds charged players will deal 2000 nature damage to all opposite-charged (or uncharged) players within 10 yards. Additionally, the debuff will grant a 10% damage bonus to all same-charged players also within 10 yards. Hence, the raid will want to cluster up in 2 or more positions.\r\n*Thaddius also has a chain lightning attack that he will do throughout the fight. Because of the even distribution of the charges, assuming you have up to 40 alive, you will have up to 19 stacks of the damage buff (adding 190% more damage) until Thaddius charges the raid again.\r\n*If he has no one in melee range, he will start throwing [[Ball Lighting]]s for around 8000 Nature damage.\r\n*After 5 minutes in phase 2, he will enrage and kill the entire raid, similar to many other bosses.\r\n==Strategies==\r\n*Phase 1: Simply tank each sub-boss near where they start and DPS them down. Players with mana bars should fight Stalagg, while everyone else should fight Feugen. Mages and hunters can outrange the mana drain, so if the groups are too uneven then they can fill in for the missing spots. Note that they sub-bosses must be killed within a short time of each other, or they will resurrect each other (much like Thekal in Zul'Gurub).\r\n*Phase 2: All players head to Thaddius himself. There is roughly 20 seconds between killing both sub-bosses and getting charged. Before the raid, assign locations for positive and negatively charged people to stand; for example, negatively charged people could stand west of Thaddius, while positively charged players stand to the east. Thaddius will make a Polarity Switch roughly every 30 seconds. Players whose polarity changes have 5 seconds to run to the location for their new polarity. There is no need to avoid other players changing sides, and they should run straight to his new position, using the shortest path available (that is, running through Thaddius). It is important to stand in 2 positions because Thaddius must be killed within 5 minutes (to avoid the Enrage) and the damage bonus from stacking players on either side will allow him to be killed.\r\nNote: If you chronically miss the jump heading for Thaddius, use a Swiftness Potion and just run forward without jumping, you will land on the platform. Rogues can use Sprint instead.\r\nHealing: Thaddius doesn't deal very much melee damage to the main tank, so you can use only 3-4 healers for him. The rest of the healers can either heal the rest of the raid, or deal damage to Thaddius in this phase.\r\nTanking: Thaddius hits for about 2k normal, 3.3k crushing. The damage multiplier the rest of the raid has can make holding threat for a warrior tank a little bit iffy. (Bear tank threat generation benefits from the damage multiplier, unlike warrior abilities, and is advantageous for this fight.) \r\nIn order to have a prayer of holding threat, the MT has to move with others of his charge, if he's unstacked by the debuff, he will find himself making frequent use of his Taunt button (Thaddius is tauntable).\r\n==Assumed Strategy==\r\nBlizzard's release of the '''''' revealed some clues into the strategy of fighting this abomination.\r\nAt the start of the encounter, the players don't fight Thaddius himself; they battle two [[wight]]s that are in the same room on two separate platforms. These platforms are not directly connected, so to fight them the raid has to split up and attack both wights at the same time. But it gets worse... the wights have the ability to snatch a player from one platform and pull him to the other, which is a way to split up the raid and divide their forces.\r\nOne central part of the whole Frankenstein myth is the way the monster was brought to life using lightning and electricity. Voltage is created when electric charges are separated; when the charges are brought together, the stored energy is released in an electrostatic discharge - a basic electric shock. When players finally go up against Thaddius, he will \"polarize\" the raid group by making half the raid positive and the other half negative. When positive and negative raid members get too close to each other... Well, let's just say that you want to get as far away from players with an opposite charge as possible, which further plays into the idea of separating the raid.\r\n==Thaddius at lvl 70==\r\n*Tactical fight like at lvl 60. Don't let your own raid members kill you - MOVE!\r\n==Quotes==\r\n* ''You are too late... I... must... OBEY!''\r\n* ''KILL!''\r\n* ''EAT YOUR BONES!''\r\n* ''BREAK YOU!''\r\n* ''Now YOU feel pain!''\r\n* ''You die now!''\r\n* ''Thank... you...''\r\nThe following quotes (echoing screams would probably be more accurate) are heard echoing throughout Naxxramas in addition to during the fight with Thaddius. The screams sound like those of a child:\r\n* ''Pleeease!''\r\n* ''Stop, make it stop!''\r\n* ''Help me! Save me!''\r\n* ''Please, nooo!''",},
			["Thadius Grimshade"] = { content = "'''Thadius Grimshade''' is a level 50 [[quest giver]] located in [[Nethergarde Keep]] in the [[contested]] territory of [[Blasted Lands]].\r\nHe starts the following quests:\r\n*Nekrum's Medallion (Dungeon)\r\n**The Divination\r\n***Return to the Hinterlands\r\nSee [[List of Blasted Lands NPCs]].",},
			["Thadok"] = { content = "'''Thadok''' can be found in [[Stonebreaker Hold]], [[Terokkar Forest]] .",},
			["Thaelis the Hungerer"] = { content = "'''Thaelis the Hungerer''' is a named [[wretched]] in the [[Commons Hall]] in [[Eversong Woods]]. He's wanted for repeated crimes against the populace of [[Silvermoon City]] including the murder of two city guards. A bill was posted for his head by [[Sergeant Kan'ren]] at Falconwing Square in Eversong Woods.\r\n==Quests==\r\n* Wanted: Thaelis the Hungerer - from [[Wanted Poster]] in [[Falconwing Square]] in [[Eversong Woods]].\r\n:Objective: Retrieve Thaelis's Head\r\n==Drops==\r\n*Thaelis's Head",},
			["Thal'trak Proudtusk"] = { content = "'''Thal'trak Proudtusk''' is a level 55 [[quest giver]] located in [[Kargath]] in the [[contested]] territory of [[Badlands]]. His wife is [[Sha'ni Proudtusk]].\r\n==Quests==\r\n*Dreadmaul Rock \r\n*Krom'Grul \r\n==See also==\r\n*[[Kargath Expeditionary Force]]\r\n*[[List of Badlands NPCs]]",},
			["Thaladred the Darkener"] = { content = "'''Thaladred the Darkener''' is one of the four blood elf advisors that aid [[Kael'thas]] during the boss encounter in [[the Eye]]. He appears to be a [[Warrior]].\r\nSee [[Kael'thas Sunstrider (tactics)]] for details on the fight.\r\n===Encounter in The Eye===\r\n* \"Prepare yourselves!\"\r\n* \"Forgive me my prince. I have failed...\"",},
			["Thalanaar"] = { content = "'''Thalanaar''' is a tiny [[Alliance]] camp on the border of [[Feralas]] and [[Thousand Needles]]. It has a [[Hippogryph]] point and can be reached from [[Feathermoon Stronghold]], [[Theramore Isle]] and [[Gadgetzan]].\r\nThe outpost has very little to offer in the way of goods and services, although it is the location for the [[Tribal Leatherworking]] trainer [[Caryssia Moonhunter]].\r\nJudging by a toppled, seemingly ancient roadsign in Thousand Needles pointing to Thalanaar it's possible that Thalanaar was at one point a larger settlement or is at least a significantly old outpost.\r\n===Facilities===\r\n*Flight Master\r\n===Flight===\r\n [[Feathermoon Stronghold]]\r\n [[Theramore Isle]]\r\n [[Gadgetzan]]\r\n===Profession Trainers===\r\n*[[Caryssia Moonhunter]] <Tribal Leatherworking Trainer>\r\n===Merchants===\r\n*[[Rendow]] <Leather Armor Merchant>\r\n===Other Characters===\r\n*[[Thyssiana]] <Hippogryph Master>\r\n*[[Kristy Grant]]\r\n*[[Falfindel Waywarder]]",},
			["Thalassian"] = { content = "'''Thalassian''' is the language of the [[high elves]], [[half-elves]], [[half blood-elves]], and [[blood elves]] — a derivative of the [[Darnassian]] language of the [[Night Elves]]. It has both written and spoken equivalents. Individuals who are unfamiliar with the language's proper name may refer to it as ''High Elven'' (not to be confused with the language [[Elven (language)|Elven]]).\r\nLike [[Nazja]], Thalassian is derived from the Darnassian language. The elder tongue is almost forgotten. Hence, Thalassian is closely related to Darnassian and there is some overlap between the two languages. Further Darnassian utterances may therefore have been preserved in modern Thalassian.\r\nSo far, linguistic scholars have opted to err on the side of caution in documenting Darnassian terms and phrases that are also considered part of the Thalassian language. Certainly this issue, however delicate, merits further research. Nevertheless, addressing a high elf or blood elf with a Darnassian-specific word or phrase can be considered offensive or at the very least rather foolish, and so the speaker must handle the situation with care.\r\nThis is one of the four known elven dialects.\r\n==Thalassian Primer (official translations)==\r\nHere are a few common Thalassian phrases and words, for which the translations have been officially confirmed by [[Blizzard]]:\r\n*'''Al diel shala''' = Safe travels.\r\n*'''Anakh kyree!''' = Miserable insect!\r\n*'''Anar'alah belore''' = By the light of the sun.\r\n*'''Anaria shola''' = Speak your business.\r\n* '''Anar'endal dracon''' = By the spirit of the dragon.\r\n*'''Ann'da''' = Papa \r\n*'''Anu belore dela'na''' = The sun guides us.\r\n*'''Bal'a dash, malanore''' = Greetings, traveler.\r\n*'''Bash'a no falor talah!''' = Taste the chill of true death!, Sylvanas Windrunner (WC3)\r\n*'''[[Dalaran]]''' = Star City or City of the Stars (Aran might be a Darnassian/Thalassian name for city and Dal is Star in Thalassian)\r\n*'''Doral ana'diel?''' = How fare you?\r\n*'''Katra zil shukil!''' = Suffer and perish!\r\n*'''[[Kim'jael]]''' = \"Little Rat\" Kim'jael Indeed!\r\n*'''[[Medivh]]''' = \"Keeper of Secrets\" \r\n*'''Minn'da''' = Mama \r\n*'''[[Quel'dorei]]''' = \"high elves\", or \"the high elves\".\r\n*'''[[Quel'Thalas]]''' = \"High Kingdom\" or \"High Home\"\r\n*'''[[Quel'Zaram]]''' = High Blade.\r\n*'''[[Quel'Danil]]''' = High Peak.\r\n*'''Ronae''' = \"Peaceful\" used in [[Lordaeron]].\r\n*'''Selama ashal'anore''' = Justice for our people.\r\n*'''Shaza-kiel!''' = Surrender your soul!\r\n*'''Shindu fallah na!''' = They're breaking through!\r\n*'''Shorel'aran''' = Farewell.\r\n*'''[[Sin'dorei]]''' = Children of the blood. This could also be interpreted as \"people of the bloodline\", referring to the continuation of the line of the [[Highborne]].\r\n*'''Sinu a'manore''' = Well met.\r\n*'''Sunstrider''' = \"he who walks the day\"\r\n*'''Vendel'o eranu''' = \"Help me forget\". \r\n===High elven names===\r\nThe past is a burden to the high elves, yet they maintain naming rituals that are millennia old. Many of the names of elven priests and heroes have become the names used for elves in modern times. The high elves share a connection with the sun that is quite prevalent in their choice of family names.\r\n* Male Names: Mariel, Athaniar, Anandor, Tharama, Viridiel, Malanior.\r\n* Female Names: Anarial, Freja, Driana, Coria, Alanassori, Melanion, Azshara.\r\n* Family Names: Boughstrider, Dawnblade, Lightbringer, Morningray, Suntreader.\r\n===Untranslated words or phrases===\r\n* '''[[An'daroth]]''' — One of the three [[Ghostlands]] observatories.\r\n* '''[[An'owyn]]''' — One of the three [[Ghostlands]] observatories.\r\n* '''[[An'telas]]''' — One of the three [[Ghostlands]] observatories.\r\n* '''Anar'endal dracon''' — Nethermancer Sepethrea\r\n* '''Anara'nel belore''' — [[Kael'thas]]\r\n* '''Balamore shanal!''' — [[Kael'thas]]\r\n* '''Bandal!''' — High Nethermancer Zerevor\r\n* '''Band'or shorel'aran!''' — Commander Sarannis \r\n* '''Belesa Menoor!''' — High Nethermancer Zerevor\r\n* '''[[Elrendar]]''' — a [[Quel'Thalas]] river and a waterfall, both fed by a lake with the same name.\r\n* '''Endala finel endal!''' — Nethermancer Sepethrea\r\n* '''Endorel aluminor''' — High Botanist Freywinn\r\n* '''[[Falthrien]]''' — an arcane academy on [[Sunstrider Isle]].\r\n* '''[[Falithas]]''' — One of the runestones protecting [[Eversong]] from the plague.\r\n* '''Felomin ashal''' — Kael'thas in [[Magister's Terrace]]\r\n* '''[[Isle of Quel'Danas|Quel'Danas]]''' — Island home of the [[dragonhawk]]s and location of the [[Sunwell]].\r\n* '''[[Quel'Lithien]]''' — A quel'dorei lodge in [[Eastern Plaguelands]]. \r\n* '''Selama am'oronor!''' — Gathios the Shatterer\r\n* '''[[Shalandis]]''' — An island off the coast of the western [[Ghostlands]].\r\n* '''[[Shan'dor]]''' — One of the runestones protecting [[Eversong]] from the plague.\r\n* '''Tal anu'men no Sin'dorei!''' — High Astromancer Solarian\r\n===Thalassian word parser===\r\nThis is the list of words created by the in-game language parser for the Thalassian language, and is listed as language number ten (word range 800-901) in the Language text file. \r\nIn the in-game translator, the language parser for Thalassian shares similar words with the Darnassian parser. \r\nNote: The language algorithm used by the in-game \"translator\" merely makes the words look like Thalassian. It does not actually translate words. Therefore, translated in-game speech isn't truly Thalassian.\r\n===Translations speculation===\r\n* '''Anu...bala balore...alon''' = ''Greet the light of the sun'' - Nethermancer Sepethrea\r\n* '''Anar/Anu''' = ''Light'' — used in ''Anar'alah belore'' and ''Anu belore dela'na''.\r\n* '''Anore''' = ''People'' — used in ''Selama ashal'anore''.\r\n* '''Belore''' = ''(The) Sun'' — ''This translation has been all but confirmed. (-- implied as The Sun as it is the last words in the song book \"Lament of the Highborne)''\r\n* '''Danil''' = ''Peak''/''Vale'' — used in ''[[Quel'Danil]]''.\r\n* '''Dal''' = ''Star'' — used in ''[[Thori'dal, the Stars' Fury]]''.\r\n* '''Diel''' = ''Travel'' — used in ''Al diel shala'' and ''Doral ana'diel''.\r\n* '''Dorei''' = ''Born'', ''Children'', or ''Elves'' — used in ''[[Kaldorei]]'', ''[[Quel'dorei]]'' and ''[[Sin'dorei]]''. (This is also Darnassian.)\r\n* '''Nah''' = ''Enemies'' — used in ''Shindu fallah nah'' and in darnassian word for enemy, nal.\r\n* '''Malanore''' = ''Traveler'', plural '''Malanorei''' — used in ''Bal'a dash, malanore''.\r\n* '''Quel''' = ''High'' — used in ''[[Quel'Danil]]'', ''[[Quel'dorei]]'', ''[[Quel'Lithien]]'' ''[[Quel'Thalas]]'', and ''[[Quel'Zaram]]''. (This is also Darnassian.)\r\n* '''Quel'Lithian''' = '''Quel''' is ''high'', '''Lithien''' is unknown (It may mean Lodge, as that is both similar to the word and relevant).\r\n* '''Serrar''' = ''Blade''.\r\n* '''Shala''' = ''Safe'' — used in ''Al diel shala''.\r\n* '''[[Shan'dor]]''' — Note the similarity to the [[Darnassian]] word '''Shan'do''', which means ''honored teacher''.\r\n* '''Sin''' = Blood — used in ''[[Sin'dorei]]''.\r\n* '''Shindu''' = \"Failing\" or \"breaking\" — used in ''[[Shindu Sin'dorei]]'' and ''[[Shindu Fallah Na]]'' (Our enemies are breaking through).\r\n* '''Shindu Sin'dorei''' = \"Failing Children of the Blood\" \r\n* '''Thalas''' = ''Home'' or \"Kingdom\"— used in ''[[Quel'Thalas]]''.\r\n* '''Thalassian''' = the ''Home language''\r\n* '''[[Thondroril River|Thondroril]]''' = '''[[Greenrush River|Greenrush]]'''\r\n* '''Thori''' = ''Fury'' — used in ''[[Thori'dal, the Stars' Fury]]''.\r\n* '''Zaram''' = ''Blade'' — used in ''[[Quel'Zaram]]''.\r\n===Darnassian vs. Thalassian speculation===\r\nOf note, [[Kael'thas]] did not react hostily in the plaguelands when [[Tyrande]] greeted him with a Darnassian phrase, he even responded himself with an \"Ishnu'alah\". This may mean that some of the words still have the same meaning in both languages. ...or it means some phrases have not become offensive in its respective language.\r\n===History speculation===\r\nAfter the [[high elves]] were exiled from [[Kalimdor]] by the [[night elves]], they set up in the [[Eastern Kingdoms]]. There, they lived for millennia, cultivating their culture and their magic. Because of their long life spans, Thalassian, as they called their language, still retains parts of the old language. In fact, it is possible that Thalassian isn't a separate language, and is merely dialect of Darnassian. Even if this were the case, however, it would still be distinct enough to incur communication difficulty.\r\n==Thalassian Outside the Warcraft Universe==\r\nAn award-winning song from the 2007 Blizzcon Song Contest was \"Belore Shala Diel\", sung in Thalassian and English, by Phillip Presswood (Xalea).",},
			["Thalassian Base Camp"] = { content = "The '''Thalassian Base Camp''' is located in northern [[Azshara]], south of the [[Legash Encampment]] and east of [[Ursolan]]. It is a hill containing numerous small camps under control of hostile [[blood elves]]. They maybe or may not be affiliated with [[Kael'Thas]], however the leader of their camp, [[Magus Rimtori]] recently made, and reneged a deal with the Horde to offer a share of the findings in echange for funding of the expedition. Because of this betrayal, Horde players are being recruited to exact vengence upon [[Magus Rimtori]] and her followers.\r\nWhile Rimtori is off exploring Azshara under the protection of her bodyguards, [[Magister Hawkhelm]] watches over the camp. The [[Kaldorei Tome of Summoning]] lies on one of the ridges of the base camp, and can be used to summon in demons. This is indicative of the expedition's true intentions.",},
			["Thalassian Pass"] = { content = "The '''Thalassian Pass''' is located in the far southern [[Ghostlands]], and is the passage through the mountains south to the [[Eastern Plaguelands]]. It is marked with a large portal that hinders non-BC owners from entering [[Quel'Thalas]].\r\nThe large gatehouse near the portal is believed to be one of the Elfgates (probably the Outer Elfgate, judging by its proximity to the border) that sealed off Quel'Thalas from Lordaeron. The gates are flanked by Scourge banners - possibly placed when the Scourge snuck through Quel'Thalas' defenses, aided by the traitor [[Dar'Khan Drathir]].\r\nSeems to have been called [[Greenwood Pass]] in Warcraft III.",},
			["Thalia Amberhide"] = { content = "'''Thalia Amberhide''' is a female [[tauren]] residing in the inn of [[Freewind Post]] in [[Thousand Needles]]. She is a close friend of [[Lakota Windsong]], the tauren who was kidnapped by [[Arnak Grimtotem]].",},
			["Thalon"] = { content = "'''Thalon''' is a level 55 [[wind rider]] [[flight master]] located in [[Shadowprey Village]] in the [[contested]] territory of [[Desolace]]. He can be found at the end of the Dock.\r\nSee [[List of Desolace NPCs]].",},
			["Thammer"] = { content = "#REDIRECT [[Travis Thammer]]", redirect = "Travis Thammer",},
			["Thamner Pol"] = { content = "'''Thamner Pol''' is a level 11 [[first aid trainer]] located in [[Thunderbrew Distillery]] in [[Kharanos]], in the [[dwarven]] starting zone of [[Dun Morogh]].\r\nSee [[List of Dun Morogh NPCs]].",},
			["Thandol"] = { content = "'''Thandol''' may refer to several things:\r\n*[[Thandol Span]]\r\n*[[Thandol Valley]]\r\n*[[Thandol (WC2 demo)]]\r\n*[[The Thandol Span]]",},
			["Thandol Span"] = { content = "The '''Thandol Span''' was one of the greatest engineering projects ever completed by the [[dwarves]]. Built on the site of the original three land bridges, the stone bridges spanned the cliffs between the Southern continent containing [[Khaz Modan]] and the Kingdom of Azeroth, and the northern Continent of [[Lordaeron]] containing the human nation of [[Lordaeron]] and the elven nation of [[Quel'Thalas]]. It was located in an area once known as the [[Thandol Valley]]. The bridges were capable of supporting the weight of entire armies, and served as the main route of trade between the dwarves and [[humans]]. The mighty bridges survived the Second War against the [[orcs]], but recently suffered heavy damage due to a Dark Iron attack. Two of the three bridges have now been all but destroyed, and dwarven forces are fighting fiercely to defend the last remaining bridge and retake the nearby town of [[Dun Modr]].",},
			["Thandol Valley"] = { content = "'''Thandol Valley''' was a region between the ruins of the ancient dwarven city of [[Dun Modr]] in southern [[Arathi Highlands]] and [[Dun Algaz]] north of [[Grim Batol]] in the northern [[Wetlands]] during the [[Second War]]. The three narrow land bridges passed through a canyon in between the two outposts. Thandol Span would later be built across the canyon. The canyon may be the valley that gives the area its name.\r\nDuring the Second War, after their defeat at Dun Modr the orcs were forced to retreat south across the Thandol Valley to their secondary outpost at Dun Algaz. [[Anduin Lothar|Lord Lothar]] intended to push them further back into [[Khaz Modan]] and ordered an attack on their base in Dun Algaz having it destroyed.",},
			["Thane"] = { content = "'''Thane''' is an honorary title bestowed upon [[clan]] leaders, nobility, or royalty in [[dwarf|dwarvish]] and [[vrykul]] societies.\r\nIn [[Khaz Modan]], the Mountain Kings, or 'Thanes' as they are known, are the mightiest dwarven warriors under the mountain. Wielding both enchanted warhammers and hand axes, these fierce fighters live to test themselves against worthy opponents. Unconcerned with their race's preoccupation with mechanical devices and mining precious minerals, Mountain Kings live only for battle. They are dedicated to safeguarding the Alliance which saved their kingdom during the [[Second War]], the Mountain Kings can be counted upon to rally behind any banner that stands between freedom and the ever looming shadow of evil.\r\n==Known==\r\nIn ''[[Warcraft III: Reign of Chaos]]'', the [[mountain king]]s are honorary thanes, although not true kings.\r\n[[Kurdran Wildhammer]] and [[Falstad Wildhammer]] of the [[Wildhammer clan]] in [[Aerie Peak]] are known to be high thanes, succeeding one another.\r\n===Dwarven===\r\n*[[Dark Iron Thanes]]\r\n*[[Muradin Bronzebeard]]\r\n*[[Thane Korth'azz]]\r\n*[[Falstad Wildhammer]]\r\n*[[Iron Thane Argrum]]\r\n*[[Iron Thane Furyhammer]]\r\n*[[Thane Stonehearth]]\r\n*[[Thane Wildsky]]\r\n*[[Thane Yoregar]]\r\n*[[Kurdran Wildhammer]]\r\n*[[Madoran Bronzebeard]]\r\n*[[Khardros Wildhammer]]\r\n*[[Sorcerer-Thane Thaurissan]]\r\n*[[Anvil-Thane Thurgaden]]\r\n*[[Maz Drachrip]] \r\n===Vrykul===\r\nNamed\r\n*[[Blood-Thane Lucard]]\r\n*[[Halfdan the Ice-Hearted]]\r\n**[[Halfdan's Soul]]\r\n*[[High Thane Jorfus]]\r\n*[[Oktel Dragonblood]]\r\n*[[Overthane Balargarde]]\r\n*[[Thane Banahogg]]\r\n*[[Thane Illskar]]\r\n*[[Thane Irglov the Merciless]]\r\n*[[Thane Torvald Eriksson]]\r\n*[[Thane Ufrang the Mighty]]\r\nUnnamed\r\n*[[Dragonflayer Thane]]\r\n**[[Dragonflayer Thane Corpse]]\r\n*[[Felskorn Thane]]\r\n*[[Voldskar Thane]]",},
			["Thane Korth'azz"] = { content = "'''[[Thane]] Korth'azz''' is one of the [[Four Horsemen]] and most likely represents the Pale Rider of Death, based on his light green color scheme.\r\nIt has been noted that Korth'azz is a fallen dwarf paladin. There is speculation that he fell to the Scourge after Uther's death, as he might have been a leading member of the [[Knights of the Silver Hand]] .\r\n==Attacks and Abilities==\r\nPlease see Attacks and Abilities section in [[The Four Horsemen]].\r\n==Quotes==\r\n* Come out and fight, ye wee ninny!\r\n* To arms, ye roustabouts! We've got company!\r\n* I heard about enough of yer sniveling. Shut yer fly trap 'afore I shut it for ye!\r\n* I'm gonna enjoy killin' these slack-jawed daffodils!\r\n* Next time, bring more friends!\r\n* I like my meat extra crispy!\r\n* What a bloody waste this is!",},
			["Thane Yoregar"] = { content = "'''Thane Yoregar''' is a level 70 [[quest giver]] located at [[Wildhammer Stronghold]] in the [[contested]] territory of [[Shadowmoon Valley]].\r\nHe starts the following quests:\r\n* Put On Yer Kneepads...\r\n* The Path of Conquest (Group)\r\nSee [[List of Shadowmoon Valley NPCs]].",},
			["Thanthaldis Snowgleam"] = { content = "'''Thanthaldis Snowgleam''' is a level 58 [[PvP]] rewards [[vendor]] located outside the [[Alterac Valley]] entrance in the [[contested]] territory of [[Alterac Mountains]]. He is the [[Stormpike Guard|Stormpike Supply Officer]] for the [[Alliance]]. \r\nHe sells the following items:\r\n===Friendly Stormpike Guard Reputation===\r\n*[[Alterac Heavy Runecloth Bandage]]\r\n*[[Bottled Alterac Spring Water]]\r\n*[[Stormpike Battle Tabard]]\r\n*[[Superior Healing Draught]]\r\n*[[Superior Mana Draught]]\r\n===Honored Stormpike Guard Reputation===\r\n*[[Alterac Manna Biscuit]]\r\n*[[Ice Threaded Arrow]]\r\n*[[Ice Threaded Bullet]]\r\n*[[Major Healing Draught]]\r\n*[[Major Mana Draught]]\r\n*[[Stormpike Cloth Girdle]]\r\n*[[Stormpike Leather Girdle]]\r\n*[[Stormpike Mail Girdle]]\r\n*[[Stormpike Plate Girdle]]\r\n*[[Stormpike Sage's Cloak]]\r\n*[[Stormpike Sage's Pendant]]\r\n*[[Stormpike Soldier's Cloak]]\r\n*[[Stormpike Soldier's Pendant]]\r\n===Revered Stormpike Guard Reputation===\r\n*[[Crackling Staff]]\r\n*[[Electrified Dagger]]\r\n*[[Gnoll Skin Bandolier]]\r\n*[[Harpy Hide Quiver]]\r\n*[[Stormpike Battle Standard]]\r\n*[[Stormstrike Hammer]]\r\n===Exalted Stormpike Guard Reputation===\r\n*[[Don Julio's Band]]\r\n*[[Don Rodrigo's Band]]\r\n*[[Lei of the Lifegiver]]\r\n*[[Stormpike Battle Charger]]\r\n*[[The Immovable Object]]\r\n*[[The Lobotomizer]]\r\n*[[The Unstoppable Force]]\r\n*[[Therazane's Touch]]\r\n*[[Tome of Arcane Domination]]\r\n*[[Tome of Fiery Arcana]]\r\n*[[Tome of the Ice Lord]]\r\n*[[Tome of Shadow Force]]\r\nSee [[List of Alterac Mountains NPCs]].",},
			["Tharbek"] = { content = "'''Tharbek''' was a fierce [[orc]] warrior and [[Orgrim Doomhammer]]'s second in command during the [[Second War]].",},
			["Tharg"] = { content = "'''Tharg''' is a level 44 [[quest giver]] located in [[Brackenwall Village]] in the [[contested]] territory of [[Dustwallow Marsh]]. He is unhappy with [[Mok'Morokk]]'s decision to run instead of fight the black dragons. His wife was killed by the [[Black Dragonflight]], and he does not consider [[Brackenwall Village]] home and wants to reclaim his old home the [[Stonemaul]] ruins. With help from [[Draz'Zilb]], Mok'morokk was eventually chased out of town and Tharg became the new chief.\r\nHe starts the quest Army of the Black Dragon (Elite).",},
			["Thargas Anvilmar"] = { content = "'''Thargas Anvilmar''' is an [[Ironforge dwarf]] in service of king [[Magni Bronzebeard]].\r\n==Biography==\r\nRecently, Thargas Anvilmar was sent by King [[Magni Bronzebeard]] to meet [[Varian Wrynn]], [[Valeera Sanguinar]] and [[Broll Bearmantle]] at [[Menethil Harbor]] without knowing who they really were. After they landed Thargas followed them to an inn where he helped the three companions fight a band from the [[Defias Brotherhood]]. He then told Varian and his friends about the feigned \"king Varian\" who has returned to [[Stormwind]].\r\nHe recently inherited the [[Helm of the Anvilmars]] from his dying brother.\r\n==Action Figure==\r\nThargas Anvilmar is featured in DC Unlimited's ''World of Warcraft: Series 1'' action figure set.\r\nThargas appears to be wearing the [[Destroyer Armor]].\r\n==See also==\r\n[[Warcraft Action Figures]]",},
			["Tharil'zun"] = { content = "'''Tharil'zun''' is a level 24 [[elite]] [[named]] [[orc]] found in [[Stonewatch]] in the [[Redridge Mountains]]. Tharil'zun is the leader of the [[Blackrock Clan]] Outrunners and [[Gath'Ilzogg]]'s chief lieutenant. He is responsible for some of the attacks on [[Lakeshire]]. Recently, [[Marshal Marris]] of Lakeshire has enlisted the help of [[Alliance]] adventurers to hunt down and kill this dangerous orc.\r\n==Abilities==\r\n*Net\r\n*Enrage\r\n*Battle Fury\r\n==Lore==\r\nHe was killed by group of heroes which included a priest, and his friends Tielyn, and Anat, according to the short lore story [[Priestly Reckoning]].\r\n==Quests==\r\n*Tharil'zun\r\n==Loot==\r\n*Tharil'zun's Head ''(Quest Item)''",},
			["Tharlidun"] = { content = "'''Tharlidun''' is a level 30 [[stable master]] located in [[Hammerfall]] in the [[contested]] territory of [[Arathi Highlands]].\r\nSee [[List of Arathi Highlands NPCs]].",},
			["Tharynn Bouden"] = { content = "'''Tharynn Bouden''' is a level 10 trade goods [[vendor]] located in [[Goldshire]] in the [[human]] starting zone of [[Elwynn Forest]].\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Thassarian"] = { content = "'''Thassarian''' was the first [[death knight]] to rejoin the [[Alliance]]. He was first encountered in [[Acherus: The Ebon Hold]] as a level 55 standing next to [[Orbaz Bloodbane]] and [[Koltira Deathweaver]]. In phase two after completing Victory At Death's Breach!, he relocates to the [[Scarlet Tavern]] with Bloodbane, where he is involved in the following quests:\r\n#Brothers In Death\r\n#Bloody Breakout\r\n#A Cry For Vengeance!\r\n#A Sort Of Homecoming\r\nHe shows up at the [[Battle for Light's Hope Chapel]] as a level 60 elite taking part in The Light of Dawn.\r\nHe next appears for all classes at [[the Wailing Ziggurat]] in [[Borean Tundra]], where he is involved in the following quests:\r\n#Thassarian, the Death Knight\r\n#Finding the Phylactery\r\n#Buying Some Time\r\n#Words of Power\r\n#Last Rites\r\nThassarian can later be found aboard the Alliance airship ''[[The Skybreaker|Skybreaker]]'' above the skies of [[Icecrown]]. He is involved in quests that unfold [[The Shadow Vault]] among others.\r\n===General===\r\nGreetings:\r\n* \"Hmm.\"\r\n* \"You need something?\"\r\n* \"Get on with it.\"\r\n* \"Make it quick.\"\r\n* \"What?\"\r\nFarewell:\r\n* \"Another time.\"\r\n* \"Tomorrow is another day.\"\r\n* \"We are done here.\"\r\n* \"Leave me be.\"\r\n* \"Suffer well.\"\r\n* \"We will ravage this land!\"\r\nIrritated:\r\n* \"My torture continues.\"\r\n* \"No escape.\"\r\n* \"You will find it difficult to speak, without a head!\"\r\n* \"Just walk away.\"\r\n* \"You lost me at 'hello'.\"\r\n===Event in [[Borean Tundra]]===\r\n* \"Leryssa!\"\r\n* \"What have you done to my sister? You motherless elf scum!\"\r\n* \"I would sooner slit your throat. You will pay for what you did to your own men, officer; for what you did to me. I swear it!\"\r\n* \"Leryssa, you alright?\"\r\n* \"I can not return home with you just yet, Leryssa. I'm not quite done with the Scourge.\"\r\n* \"You might be right sister. My obligations to my land and king have been fulfilled. But there is something that I still owe to myself.\"\r\n* \"Do not worry, Leyssa. I will come back to you when I'm done. Nothing in the world will stop me from coming home to the only family that I have left.\"\r\nTo [[Tanathal]]:\r\nSpeak, [[Tanathal|Lich]]! [[Undead|Undeath]] won't save you from what I'll put you through!\r\nAll I ever wished was to serve my [[Varian Wrynn|king]] once again. For [[human]]ity, against a [[Lich King|common enemy]].\r\nInstead, I find that [[Valiance Expedition|our numbers]] have been infiltrated by [[Cult of the Damned|cultist]] scum.... and all of the signs point to [[Naxxanar]] as the origin of this rot.",},
			["That's Asking A Lot"] = { content = "==Prerequisites==\r\nNone\r\n==Quest Text==\r\nSmokey LaRue wants you to get 2 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs, and 8 Unstable Triggers.\r\nYou will have to find a blacksmith and an engineer for these items. \r\n*2 x [[Thorium Bar]]\r\n*1 x [[Golden Rod]]\r\n*8 x [[Hi-Explosive Bomb]]\r\n*8 x [[Unstable Trigger]]\r\nThese here Argent Dawn people commissioned ol' Smokey to do a little demolition work for 'em. Smokey's mammy ain't raised no dummy. When gold coin is slapped on the table, Smokey's services are available. That's my motto!\r\nNow I'd be willing to split the commission with you if you're willing to do a little legwork. Here's the deal: I'm going to head over to Plaguewood and mark the buildings we need destroyed. You gather the components for the bombs. Meet back here when you've got everything. Deal? \r\n==Details==\r\nThis is a very expensive quest to complete for little reward. The real rewards come with the followup quest.\r\n==Quest Progression==\r\n# '''That's Asking A Lot'''\r\n# [[Quest:When Smokey Sings, I Get Violent|When Smokey Sings, I Get Violent]]",},
			["Thathrell"] = { content = "'''Thathrell''' is a [[tothrezim]] [[sorcerer]], [[warlock]], and [[warmage]]. He is the group leader of tothrezim debt collectors used for particularly dangerous debt collections. His group is one of four specialized collection teams. Under his command are [[Kurzill]], [[Dweezel]], [[Mazgrek]], and five [[adamantine stalker]]s.",},
			["Thaurissan family"] = { content = "'''Thaurissan''' is a family of [[Dark Iron clan|Dark Iron]] [[dwarf|dwarves]].\r\n* [[Sorcerer-Thane Thaurissan]], leader of the Dark Iron during the [[War of the Three Hammers]]. Responsible for summoning [[Ragnaros]] into [[Azeroth]].\r\n** [[Spirit of Thaurissan]], a mob in [[Blackwing Descent]].\r\n* [[Dagran Thaurissan]], former emperor of the Dark Iron and final boss of [[Blackrock Depths]].\r\n* [[Moira Thaurissan]] (born Moira Bronzebeard), daughter of [[Magni Bronzebeard]], wife of Dagran Thaurissan, and Queen-Regent of the Dark Irons after her husband's death.\r\n* [[Dagran Thaurissan II]], the young son of Dagran and Moira, making him the heir to both [[Ironforge]] and the Dark Iron.",},
			["Thaurissan Family Jewels"] = { content = "'''The Thaurissan Family Jewels''' is a locked chest which contains various [[gem]]s that drops from [[Emperor Dagran Thaurissan]] in [[Blackrock Depths]].\r\n==Loot==\r\nThe Taurissan Family Jewels has a wide loot range which can contain a few of these items:\r\n*[[Star Ruby]]\r\n*[[Aquamarine]]\r\n*[[Citrine]]\r\n*[[Jade]]\r\n*[[Lesser Moonstone]]\r\n*[[Large Opal]]\r\n*[[Blue Sapphire]]\r\n*[[Moss Agate]]\r\n*[[Iridescent Pearl]]\r\n*[[Black Pearl]]",},
			["Thekal's Grasp"] = { content = "==Source==\r\nThis item drops from [[High Priest Thekal]] in [[Zul'Gurub]].",},
			["Thekal"] = { content = "#REDIRECT [[High_Priest_Thekal]]", redirect = "High_Priest_Thekal",},
			["Theka the Martyr"] = { content = "'''Theka the Martyr''' is a level 46 [[elite]] [[undead]] [[troll]] [[mini-boss]] found in [[Zul'Farrak]].\r\n==Background==\r\nA historical figure in [[sand troll]] society who sacrificed himself for the benefit of his people, those who persecuted him were forever cursed into the form of [[scarab]]s. [[Yeh'kinya]] wants the tablet that Theka possesses.\r\n==Strategy==\r\nHis fight is a simple one, same as fighting a standard trash [[mob]], but with a twist. At about 25% HP he becomes immune to [[physical]] and [[shadow]] damage. However, if you stunlock him from 25-0% he will NOT become immune. Also, as of [[patch 1.12]] the immunity is a buff that wears off after 30 seconds. [[AoE]] damage must be avoided as the numerous scarabs surrounding him can overwhelm a party. Note that Theka is an [[undead]] target and can be hit with spells such as [[Exorcism]], [[Shackle Undead]], [[Holy Wrath]], and [[Turn Undead]].\r\n==Quests==\r\n*The Prophecy of Mosh'aru\r\n==Loot==\r\n*First Mosh'aru Tablet ''(Quest Item)''",},
			["Theldren"] = { content = "'''Theldren''' is a level 60 [[elite]] [[Dark Iron Dwarf]] who hangs out at the Arena in [[Blackrock Depths]].\r\n==Background==\r\nNot concerned with honor and good sportsmanship, he tries to never fight in a fair fight. His idea of a good fight is where he already knows he will win before it even starts. He is a bit of a hot-head and will rush into a fight if his family's honor is being mocked.\r\nTheldren and his fellow gladiators can be summoned using a [[Banner of Provocation]]. The [[Arena Spoils]] will be lootable after their defeat.\r\nTheldren's team of gladiators includes:\r\n*[[Lefty]] - a Gnome Rogue\r\n*[[Malgen Longspear]] (with pet [[Gnashjaw]])\r\n*[[Rotfang]]\r\n*[[Va'jashni]] - a Troll Priest\r\n*[[Volida]] - an Undead Mage\r\n*[[Rezzick]] - A Goblin rogue who uses many engineering tools\r\n==Quests==\r\n*The Challenge\r\n==Loot==\r\n*Top Piece of Lord Valthalak's Amulet ''(Quest Item)''",},
			["Theldurin the Lost"] = { content = "'''Theldurin the Lost''' is a level 30 [[quest giver]] located in a small camp at [[Agmond's End]] in the [[contested]] territory of [[Badlands]]. Theldurin was once part of the [[Twilight Hammer]].\r\nSee [[List of Badlands NPCs]].\r\n==Quests==\r\n* Solution to Doom \r\n* Forbidden Knowledge \r\n* Theldurin the Lost \r\n* The Lost Fragments \r\n* To Ironforge for Yagyin's Digest \r\n* To the Undercity for Yagyin's Digest \r\n* Summoning the Princess",},
			["Thelgen Rock"] = { content = "'''Thelgen Rock''' is an area in the southern [[Wetlands]] that is crawling with poisonous spiders. The name refers to an extensive cavern that stretches deep into the [[Khaz Mountains]]. The caves hold deposits of a rare ore that miners sometimes come to dig up. Frustrated cartographers can also be seen roaming the area trying in vain to explore the last piece of their maps.",},
			["Theloria Shadecloak"] = { content = "'''Theloria Shadecloak''' is a level 64 [[high elf]] [[quest giver]] located at the [[Allerian Post]] in the [[contested]] territory of [[Terokkar Forest]]. She regrets the decisions made by her people while she was in [[Outland]].\r\nShe starts the following quests:\r\n* The Firewing Liaison (Alliance)\r\n* Thinning the Ranks (Terokkar Forest)\r\n==See also==\r\n*[[Terokkar Forest NPCs]].\r\n*[[List of high elves in Azeroth and Outland]]",},
			["Thelsamar"] = { content = "'''Thelsamar''' is a [[dwarven]] town on the west side of [[Loch Modan]], located north of [[Grizzlepaw Ridge]] and northeast of [[Stonesplinter Valley]]. The town has a [[Gryphon]] roost, an inn, and several vendors and profession trainers. A north-south road runs just west of town, leading to the passes into [[Dun Morogh]] and the [[Wetlands]].\r\n===Flight===\r\n [[Ironforge]]\r\n [[Menethil Harbor]]\r\n [[Refuge Pointe]]\r\n [[Thorium Point]]\r\n===Trainers===\r\n* [[Brock Stoneseeker]] - <Mining Trainer>\r\n* [[Ghak Healtouch]] - <Journeyman Alchemist>\r\n* [[Kali Healtouch]] - <Herbalist>\r\n* [[Warg Deepwater]] - <Fisherman> (just northeast of town on the shores of the loch)\r\n==Quests==\r\n* [[Quest:Rat Catching]]\r\n* [[Quest:Thelsamar Blood Sausages]]\r\n* [[Quest:Ironband's Excavation]]\r\n* [[Quest:Mercenaries]]\r\n* [[Quest:WANTED: Chok'sul]]\r\n==Other Features==\r\n* [[Forge]]: Across the road from the inn.\r\n* [[Anvil]]s: Across the road from the inn.\r\n* [[Gryphon|Gryphon Roost]]: Just south of town and east of the main road.",},
			["Theocritus"] = { content = "'''Theocritus''' is a level 24 [[quest giver]] located in the [[Tower of Azora]] in the [[human]] starting zone of [[Elwynn Forest]].\r\nHe starts the following quests:\r\n* A Watchful Eye\r\n* Morganth (Elite)\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Theradras"] = { content = "==Lore==\r\nDeep in Maraudon lives an evil creature of chaos. '''Princess Theradras''' is an elemental force of earth related to the [[Old Gods]], a daughter of [[Therazane the Stonemother]]. Ages ago, Theradras and [[Zaetar]], first son of [[Cenarius]], began a relationship. The offspring of their time together became known to the people of [[Kalimdor]] as [[centaur]]s, who promptly slew their father for his part in their misbegotten creation. Fearful of Cenarius' wrath, the grief-stricken Theradras sequestered her dead lover's body in her secret sanctuary, the Crystal Caverns of [[Terramok]], where she watches over him to this day. Travelers who come to [[Desolace]] have little trouble spotting Zaetar's tomb, for the blessing of nature that permeates his being transformed his resting place into a verdant paradise of flora and tranquil pools. Today, this tomb is now trodden by the hooves of Zaetar's children, who have claimed this great cavern as their sacred stronghold Maraudon. The subterranean tunnels are populated by the vicious, long-dead [[ghost]]s of the centaur [[Khan]]s, as well as Theradras' own raging, elemental minions.\r\n==Strategy==\r\nIt is definitely better to have two [[tank]]s for Princess Theradras herself. She fears and has a knockback which throws whoever has [[aggro]] roughly 20-30 yards. Also, she occasionally slams the ground which send out waves dealing about 150 damage (for each wave) and knocking everyone down for several seconds, so you must keep her away from casters or their spells will be [[interrupt]]ed during this [[AoE]] knockback. If you have a [[priest]], put [[Fear Ward]]s on your tanks. When she throws back one tank, everyone else stops what they are doing until the second tank establishes aggro. [[Rogue]]s will not cut it as off-tanks, she hits too hard, and your healer will have to spam heals. If you do only have one available tank, a common strategy is to have them back up into the water towards the walls. When she knocks the MT back, they should be positioned to rebound off the wall and come right back to her.\r\nWith the recent changes to PvE fear mechanics (in that mobs no longer de-aggro feared targets) this fight can now easily be done with one tank. When she fears, she will stay on the tank, provided someone else pulls aggro whilst they are feared (ie. they resist and continue attacking). The fight favours ranged classes, but is essentially a tank and spank. Anyone that does not need to be in melee should be at max range.\r\n==Quests==\r\n*Corruption of Earth and Seed (Alliance)\r\n*Corruption of Earth and Seed (Horde)\r\n==Loot==\r\nPrincess Theradras was the first of the instance progression final bosses to have a chance of dropping a non-world drop epic item.\r\nSince [[Patch 2.3.0]], The [[Deadman's Hand]] is now the first epic drop that is not a World Drop.",},
			["Theramore"] = { content = "#REDIRECT [[Theramore Isle]]", redirect = "Theramore Isle",},
			["Theramore Guard Badge"] = { content = "A '''Theramore Guard Badge''' can be found in the ruins of the [[Shady Rest Inn]] in [[Dustwallow Marsh]]. It displays the Theramore's insignia, a gold anchor on a white background. The name \"[[Paval Reethe|Lieutenant Paval Reethe]]\" is embossed below the insignia.\r\n==Quest==\r\n*[[Lieutenant Paval Reethe (Alliance 1)]] \r\n*[[Lieutenant Paval Reethe (Horde)]]",},
			["Theramore Infiltrator"] = { content = "'''Theramore Infiltrators''' are stealthing level 35-36 [[mob]]s located in a wide circle around [[Brackenwall Village]] in [[Dustwallow Marsh]]. They appear towards [[Alliance]] players and to [[Horde]]. \r\n==Objective of==\r\nNeed to be killed for the quest Theramore Spies.",},
			["Theramore Island"] = { content = "#REDIRECT [[Theramore Isle]]", redirect = "Theramore Isle",},
			["Theramore Isle"] = { content = "Not only is '''Theramore Isle''' the [[Alliance]]'s only heavily fortified stronghold in [[Kalimdor]] and capital of the [[Dustwallow Marsh]] with a population of 9,500 people, but also the official home of the new Alliance in Kalimdor. \r\nThe main human settlement on Kalimdor is not actually on Kalimdor. Theramore is a rocky island east of Dustwallow; the humans’ walled city bears the same name as the island. It was originally settled with the sole purpose of survival. Yet the time since the Third War has seen the city prosper, making for a natural progression from mere subsistence to a desire to restore the glory of old. This large island is the Alliance's stronghold upon Kalimdor. \r\nIt was built primarily as a military fortress, but has grown somewhat to serve as a trading port. Approach from the sea is extremely difficult due to the jagged rocks jutting out of Dustwallow Bay, leaving travelers to journey on foot through the marsh to one of the villages that run ferries out to the island. Fearful of pirates from [[Ratchet]] and elsewhere, the cannons of Theramore will fire without warning on any ship approaching the island unannounced. Also, possibly because of its importance to the alliance, mages with sufficient skill can [[teleport]] to or open a [[Portal (spell)|portal]] to here.\r\n==Within the walls==\r\nInside the thick walls of Theramore, the people have labored hard to recreate a piece of [[Lordaeron]]. Graceful towers rise high above clean, cobblestone streets lined with shops and homes. At the eastern part of the city lies the [[Foothold Citadel]], a squat keep housing the chambers of the Alliance Assembly. Though the streets recall the quiet serenity of the Alliance of Lordaeron, the meetings of the Assembly reveal the considerable strain among the city's residents. After years of near-paternal guidance of the humans of Lordaeron, the [[high elves]] resent being forced to rely on the hospitality of the younger race since arriving on Kalimdor. As humans hold five of the seven seats on the Alliance Assembly, both the elves (with two seats) and the [[dwarves]] (with none) feel under-represented in the leadership of both Theramore and the Alliance in general. As the dwarves continue to accumulate more evidence of their Titan heritage that they want to present to their King in [[Khaz Modan]], their protests that the Alliance does little to return across the sea grow louder and louder. Also, diplomatic relationship between the humans on Kalimdor and their brethren in the Eastern Kingdoms — especially the people of Stormwind, whose leadership wants to challenge Theramore on its new role as the Alliance's capital — have been getting worse in the past, with each side accusing the other of fatal mistakes during the last war. While the people of Theramore hold a grudge against their relatives for triggering the [[Horde]]'s counterattack on the city, the humans on the other side of the ocean feel they have a right to get more support from Theramore.\r\nDespite this internal debate, the Alliance places a high value on law and order in Theramore, and city guards make regular patrols to maintain the peace. When skirmishes break out between high elves and night elves or a dwarf gets too rowdy, the guards are quick to round up the offenders for a speedy trial at the Foothold Citadel and imprisonment in [[Ironclad Prison]], the dungeons of which are along tunnels dug deep into the rock of the island. Sentences for fighting and disturbing the peace tend to be light (usually only a few days' incarceration), but sentences for more serious violations of the Alliance's code of law, such as high robbery or murder, can be much more severe.\r\nSeveral [[Knights of the Silver Hand]], who travelled to Kalimdor together with Jaina Proudmoore, also have a small paladin lodge in the city.\r\nTheramore Isle is the Home of [[Jaina Proudmoore]] and the remaining Alliance forces who followed [[Medivh]]'s advice before the [[Burning Legion]]'s invasion and evacuated to [[Kalimdor]]. Theramore soldiers can also be found guarding [[Northwatch Hold]].\r\nIt appears that despite Jaina's efforts, some people in Theramore continue to desire ill upon the orcs. They have attacked Balandar Brightscar ships and stolen his cargo and his first mate. [[Lieutenant Caldwell]] also displays a hatred for Horde and executed [[Paval Reethe]] for alleged involvement with the Horde.\r\n==Theramore's banner==\r\nThe anchor device on Theramore's banner perhaps has a double meaning: most obviously that Theramore is a port city; and that Theramore is a kind of anchor for the Alliance in Kalimdor and will not waver. There is also a solar disk with rays, and three stars that appear below the anchor. The meaning for those are not certain. Some banners also display the \"L\"-like symbol of the [[Alliance of Lordaeron]], clearly indicating the city's roots. [[Jaina Proudmoore]] — the ruler of Theramore — is the daughter of Lord Admiral [[Daelin Proudmoore]], former leader of the merchant nation of [[Kul Tiras]]. The similarity between Theramore's banner and the flag of [[Kul Tiras]] stems from this relationship.\r\nThe tabards that Theramore guards wear bear the anchor device only. It appears only on the front, and instead of using blue, on the tabard it is gold.\r\n===Flight===\r\n [[Auberdine]]\r\n [[Talrendis Point]]\r\n [[Nijel's Point]]\r\n [[Thalanaar]]\r\n [[Ratchet]]\r\n [[Mudsprocket]]\r\n [[Gadgetzan]]\r\n===Boat===\r\n [[Menethil Harbor]]\r\n==Notable Characters == \r\n* [[Jaina Proudmoore]]\r\n* [[Aegwynn]]\r\n==Notable amenities of Theramore==\r\n* [[Mage trainer]]\r\n* [[Paladin trainer]]\r\n* [[Warrior trainer]]\r\n* [[Herbalism trainer]]\r\n* [[Expert]] [[alchemy trainer]]\r\n* [[Master]] [[tailoring trainer]]\r\n* [[Artisan]] [[first aid trainer]]",},
			["Theramore Marine"] = { content = "The '''Theramore Marine'''s are based of the [[Kul Tiras Marine]]s.",},
			["Theras"] = { content = "'''Theras''' is a level 70 elite [[demon hunter]] at the [[Ruins of Karabor]]. He is one of three [[night elf]] demon hunters in charge of training [[Blood Elf]] demon hunter recruits.\r\n==Attacks and Abilities==\r\n*Melees pre-heroic Warriors for about 300-450\r\n*Uses Mana Burn frequently\r\n*Turns into a demon at 49%",},
			["Therazane"] = { content = "The [[Old Gods]]' armies were led by the [[Elemental Lord]]s who were powerful elemental lieutenants in their own right: [[Ragnaros the Firelord]], '''Therazane''' the Stonemother, [[Al'Akir|Al'Akir the Windlord]], and [[Neptulon the Tidehunter]]. \r\n'''Therazane''' is a monstrous humanoid covered with stones, earth, and clinging plants. She has squat legs and four powerful arms, and the suggestion of large, saggy breasts and wide hips indicate that she is a female. Her unblinking eyes of gold-flecked agate look out into the world from her one head, but there are two other heads to be seen as well.\r\n'''Therazane''' the Stonemother is ruler over the earth, dirt, rock and mountains. She is revered by all earth elementals and creatures that dwell underneath the ground. Some druids of the wild see her as the embodiment of all that is peaceful and calm about the world. Some sages believe she feels pain whenever the ground is sundered and weeps at the destruction wrought by Deathwing and his ilk. If so, however, she has done nothing specific to oppose the great dragon. '''Therazane''' is the most peaceful of the [[Elemental Lord]]s. She is a patient, loving, motherly type who encourages growing things and loves simply to spend long periods of time relaxing with those creatures that make their homes upon her. She often feels as though she is always at war with the other [[Elemental Lord]]s: [[Al'Akir]] erodes her surface with winds, [[Neptulon]] beats his waves constantly upon her shores, and [[Ragnaros]] is a blazing furnace that churns at her fiery core. She would be perfectly happy if the three of them would just go away. '''Therazane''' is slow to anger and attempts to avoid combat whenever possible. If roused to battle, however, she can be a fearsome, powerful opponent. She typically drives toward the most dangerous foe, smashing her target into tiny red pieces before moving on to the next. Should she be seriously challenged, she simply sinks into the earth and retreats.\r\nIt is theorized by some that the kind and gentle Earthmother to which the Tauren refer to is this creature.\r\n==The War with the Titans==\r\nThe [[Old Gods]] chaotic forces raged across the face of the world and when the [[Titan]]s arrived on [[Azeroth]] they clashed. Though the elementals were powerful beyond mortal comprehension, their combined forces could not stop the mighty Titans. One by one, the elemental lords fell, and their forces dispersed. The [[Pantheon]] shattered the Old Gods' citadels and chained three of the five evil gods far beneath the surface of the world. Without the Old Gods' power to keep their raging spirits bound to the physical world, the elementals were banished to an abyssal plane, where they would contend with one another for all eternity. With the elementals' departure, nature calmed, and the world settled into a peaceful harmony.\r\nTherazane's name may be derived from [[wikipedia:Terra|''terra'']], a Latin word meaning ''Earth''.\r\n==Appearance==\r\n''As you watch, the earth ahead seems to rise up, forming into a monstrous humanoid covered with stones, earth and clinging plants. It has squat legs and four powerful arms, and the suggestion of large, saggy breasts and wide hips indicate that this creature is undeniably female. Unblinking eyes of gold-flecked agate stare at you from a face that seems curious, inquisitive… and you see what appear to be two other faces beside the one that regards you now, one of anger and fury, the other of perhaps sorrow and longing.''\r\n==In Game references==\r\nTwo items in game are a direct reference to her, Therazane's Link and Therazane's Touch.\r\nThe [[Princess Theradras]], who (along with [[Zaetar]]) was the progenitor of five clans of [[centaur]], is Therazane's daughter.\r\nThe Princess [[Myzrael]], having the in-game status of an elemental, might be related to her (though she appears more like a [[Titan]] than a servant of the Old Gods).\r\n[[Princess Theradras]]' model is called \"Tharazun\".",},
			["Therazane the Stonemother"] = { content = "#REDIRECT [[Therazane]]", redirect = "Therazane",},
			["Thero'shan"] = { content = "'''Thero'shan''' is a title of respect in the language of the [[night elf|night elves]] ([[Darnassian]]) meaning \"honored student.\"\r\nIt is the title by which Archdruid [[Malfurion Stormrage]] is addressed by the demi-god [[Cenarius]], and is used by Malfurion when referring to his [[druid (lore)|druid]]s.\r\nThe complementary honorific is [[shan'do]].",},
			["Thersa Windsong"] = { content = "Thersa Windsong is a female [[tauren]] located in the [[Apothecarium]] section of the [[Undercity]].\r\nAfter battling some [[naga]] in [[Azshara]], Thersa stopped to rest on the beach and drank some water from one of the tidepools there. Something in the water she drank has made her terribly ill, so much so that none of the healers among the tauren, [[orcs]], or [[trolls]] have been able to cure her condition. In desperation, Thersa has traveled to the Undercity to seek the help of the [[Royal Apothecary Society|Apothecaries]].\r\nShe is involved in the following quests given by [[Chemist Cuely]]:\r\n* Seeping Corruption\r\n** Seeping Corruption (2)\r\n*** Seeping Corruption (3)\r\nSee [[List of Undercity NPCs]].",},
			["Therum Deepforge"] = { content = "'''Therum Deepforge''' is a level 35 [[expert]] [[blacksmithing trainer]] located in [[the Dwarven District]] in the [[human]] city of [[Stormwind]].\r\nSee [[List of Stormwind NPCs]].",},
			["Thessala Hydra"] = { content = "'''Thessala Hydras''' are level 46-47 [[elite]] [[hydra]]s found near [[Earth Song Falls]] in [[Maraudon]].\r\nThey are [[skinnable]].",},
			["The 1 Ring"] = { content = "'''The 1 Ring''' can only be found by fishing, referencing the discovery of the One Ring by the hobbits Déagol and Sméagol while on a fishing trip (in Tolkien's ''Lord of the Rings'').\r\n==Source==\r\nThis item can be found by [[fishing]] in any low level fishing area, such as the canals in [[Stormwind]] and other fishing areas in Horde and Alliance main cities and secondary areas. However, it has an extremely low drop rate and even an avid fisherman is unlikely to ever see one.\r\nThe 1 Ring [[Bind on Equip|binds on equipping]], so can be sold, and does appear in the [[Auction House]] from time to time.\r\n==Notes==\r\nThe 1 Ring has very good stats for a level 10 ring (required level); rings of a comparable level buff one stat one point. Even so, it is not a great ring - by the time you really need the extra edge from items for battlegrounds or instances, there are other choices with as high a total stat bonus, and with focused bonuses that help specific classes. \r\nEven so, The 1 Ring is very popular because of its tie to the infamous object in Tolkien's ''LotR''.\r\nThe 2 Ring jokingly referred to in the item's tooltip has actually been implemented and can be found in game as of [[Patch 2.4.0]].",},
			["The Abyssal Shelf"] = { content = "#redirect [[Abyssal Shelf]]", redirect = "Abyssal Shelf",},
			["The Active Agent"] = { content = "'''The Active Agent''' is the 2nd quest in the [[Quest:The Flesh Does Not Lie|The Flesh Does Not Lie]] quest chain.\r\n==Objectives==\r\nTravel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.\r\n* Scourge Data\r\n==Description==\r\nYou will have to delve deeper into Stratholme, <name>.\r\nBeyond the first gates you will find the ziggurats. We know that the Scourge draws great power from these structures. Search the Ziggurats and return with any information that you may discover.\r\n==Progress==\r\nWe are on the verge of discovering what this new active plague agent may be!\r\n==Completion==\r\nAstonishing! This will take months to dissect and analyze. The Argent Dawn thanks you for your efforts, <name>.\r\nWith our blessing, take your pick between either this Seal of the Dawn or this Rune of the Dawn. You can use either of them instead of a standard Argent Dawn Commission to collect scourgestones on our behalf. Should you lose yours, speak with me and I'll get you a replacement.\r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*14300 [[XP]] (or 87 silver at level 70)\r\n*1000 reputation with [[Argent Dawn]]\r\n==Quest chain==\r\n*The Flesh Does Not Lie\r\n**The Active Agent\r\n==Notes==\r\nWho: [[Betina Bigglezink]]\r\nZone: [[Eastern Plaguelands]]\r\nRegion: [[Light's Hope Chapel]]\r\nKingdom: [[Eastern Kingdoms]]\r\n*The Scourge Data is found in a tiny box on the floor of one of the ziggurats.\r\n*This is a great reward, because it allows you to replace your [[Argent Dawn Commission]] with a trinket that gives combat bonuses against the [[Undead]] and still acquire [[Scourgestone]]s.\r\n*In addition to the normal rewards, this quest will increase your reputation with the [[Argent Dawn]].",},
			["The Aftermath of the Second War"] = { content = "#REDIRECT [[Warcraft II: Beyond the Dark Portal manual]]", redirect = "Warcraft II: Beyond the Dark Portal manual",},
			["The Air Strikes Must Continue"] = { content = "'''The Air Strikes Must Continue''' is part of the [[Shattered Sun Offensive]] storyline. Once players have recovered the [[Sun's Reach Armory]], this quest replaces Distraction at the Dead Scar.\r\n==Objectives==\r\n[[Battlemage Arynna]] wants you to speak to [[Ayren Cloudbreaker]] when you're ready to fly over the [[Dead Scar]]. Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers.\r\n* Arcane Charges (provided)\r\n* [[Pit Overlord]] slain x2\r\n* [[Eredar Sorcerer]] slain x3\r\n* [[Wrath Enforcer]] slain x12\r\n==Description==\r\nWe've taken the armory from the enemy thanks to our aerial attacks against the [[Burning Legion|Legion]]'s forces in the Dead Scar.\r\nAs a matter of fact, it's gone so well that we're going to continue our air strikes against them. Take these arcane charges and use them against their forces.\r\nTalk to Ayren Cloudbreaker at the [[Shattered Sun Staging Area]] when you're ready for flight.\r\n==Rewards==\r\nYou will receive: 3 gold 40 silver \r\n==Progress==\r\nHave you accomplished your mission, <name>?\r\n==Completion==\r\nAny demons we kill today are demons that we do not have to fight tomorrow. Keep it up.",},
			["The Aldor"] = { content = "#redirect",},
			["The Alliance"] = { content = "#REDIRECT [[Alliance]]", redirect = "Alliance",},
			["The Alliance Art Card Set"] = { content = "Within, you will find depictions of great deeds, battles not forgotten, and heroes old and new. Let these images be a testament to the champions of the Alliance.\r\nThe set includes:\r\n*35 different 8\"x10\" art cards displaying art from the World of Warcraft Trading Card Game.\r\n*Images by Kev Walker, James Zhang, Todd McFarland, Michael Komarck, Greg Staples and other and other top artists.\r\n*An exclusive game-playable foil version of Vindicator Enkallus.\r\n*A 1000 point value UDE Rewards card. Use these points to get enhancements for your online game or other exclusive prizes.",},
			["The Alliance Needs Thorium Bars!"] = { content = "==Objectives==\r\nBring 20 Thorium Bars to [[Dame Twinbraid]] at the Military Ward in [[Ironforge]]. \r\n* Thorium Bar (20)\r\n== Description==\r\nIt is very kind of you to inquire about the needs that the [[Alliance]] has. In addition to all of the other collection efforts underway, we are in need of a great quantity of thorium bars, which is the task that I am in charge of. The thorium will be used in the creation of many different things for the war, foremost of which is the construction of a battalion of steam tanks to be airlifted into [[Silithus]] as soon as they are completed. Can you aid us in this endeavor, <class>? \r\n== Progress==\r\nI do so hope that you have been successful in gathering the thorium bars that we spoke of earlier. \r\n== Completion==\r\nOh thank you, <class>! Thank you! That's twenty down and an incalculable amount to go. You have the gratitude of the [[Alliance]], and your efforts shall not go unrewarded. Speak to me again should you come across more thorium bars. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*0 [[XP]]",},
			["The Alliance of Lordaeron"] = { content = "'''\"The Alliance of Lordaeron\"''' is a section of the [[History of Warcraft]], Chapter IV. It is set during the timeframe of ''[[Warcraft II: Tides of Darkness]]''.\r\n'''''The History of the Alliance of Lordaeron''''' book was one of the military history books that [[Thrall]] studied while training as a gladiator for [[Aedelas Blackmoore]]. \r\nFound at:\r\n* [[Hall of Explorers]] in [[Ironforge]].\r\n* [[Stormwind Keep]] in [[Stormwind]].\r\n* [[Thunderbrew Distillery]] of [[Kharanos]] in [[Dun Morogh]].\r\n* [[Darkshire]] in [[Duskwood]].\r\n* [[Tarren Mill]] in [[Hillsbrad Foothills]].\r\nTimeline: \r\n* ← Previous book: [[The Dark Portal and the Fall of Stormwind]]\r\n* → Next book: [[The Invasion of Draenor]]",},
			["The Alliance Splinters"] = { content = "'''\"The Alliance Splinters\"''' is a section of the [[History of Warcraft]], Chapter IV. It is set shortly before ''[[Warcraft III: Reign of Chaos]]''. \r\nTimeline: \r\n* ← Previous book: [[Kel'Thuzad and the Forming of the Scourge]]\r\n* → Next book: [[The Scourge of Lordaeron (History of Warcraft)|The Scourge of Lordaeron]]",},
			["The Altar of Damnation"] = { content = "#redirect [[Altar of Damnation]]", redirect = "Altar of Damnation",},
			["The Altar of Shadows"] = { content = "#redirect [[Altar of Shadows]]", redirect = "Altar of Shadows",},
			["The Altar of Zul"] = { content = "#REDIRECT [[Altar of Zul]]", redirect = "Altar of Zul",},
			["The Ancient Egg"] = { content = "The Ancient Egg is the 3rd quest in the '''Screecher Spirits''' quest chain.\r\n==Objectives==\r\nBring the Ancient Egg to Yeh'kinya in Tanaris.\r\n* Ancient Egg\r\n==Description==\r\nThe Prophecy of Mosh'aru speaks of an ancient egg. It is a relic of a time when trolls ruled vast empires, and it has the power to hold the essence of Hakkar. It may be the only way to keep our world safe from his evil.\r\nBring me the ancient egg, <name>. It is said to lay hidden deep within Jintha'Alor in the Hinterlands, in a cave behind the amphitheater at the top of the city.\r\n==Progress==\r\nDo you have the ancient egg? I sense great forces stirring, and I fear that time grows short.\r\n==Completion==\r\nAh, you have the egg! I bow to you, <name>. Your strength and bravery will be long remembered.\r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*8500 [[XP]] (or s=51 gold at level 70)\r\n==Quest chain==\r\n#Screecher Spirits\r\n#The Prophecy of Mosh'aru\r\n#The Ancient Egg\r\n#The God Hakkar",},
			["The Angry Scytheclaws"] = { content = "'''The Angry Scytheclaws''' is the 6th quest in the [[Quest:Isha Awak|Isha Awak]] quest chain. It begins and ends with [[Sergra Darkthorn]].\r\n==Objectives==\r\nKill Sunscale raptors and collect their feathers. Use the feathers on the 3 Scytheclaw nests. Return to Sergra Darkthorn in the Crossroads.\r\n*Visit [[Blue Raptor Nest]]\r\n*Visit [[Yellow Raptor Nest]]\r\n*Visit [[Red Raptor Nest]]\r\n==Description==\r\nNow, <name>, the hunt deepens. Now you must defeat your prey, and then find your way to its lair.\r\nHunt the sunscale raptors to the south. Slay them and remove the feathers they wear. Place the feathers on the scytheclaw nests southwest of the Stagnant Oasis. Show their brethren you do not fear them!\r\n==Progress==\r\nHave you been to the nests, <name>?\r\n==Completion==\r\nSo you've been to the nests and placed the feathers of your prey within them. That took a fair portion of courage, no doubt about it.\r\nDo you feel a little tougher, <name>? Because you look tougher now then when you first came here. I guess the Barrens is doing its job.\r\n==Notes==\r\nHead south from [[The Crossroads]] until you get to the bridge at the small ditch. The nests will be off to the east, next to a small hill with kodo bones next to it. The Sunscale Feathers you need drop off the Scytheclaws in the area. Each of the nests contains a glowing egg corresponding to the nest's color (yellow, red, blue). You'll need 3 feathers for each of the 3 separate nests. If you need additional feathers, the [[Raptor Grounds]] contains many, and can be found by simply following the small ditch east to the mountains.\r\nThe three nests are not far from the Gold Road .",},
			["The Apothecarium"] = { content = "#REDIRECT [[Apothecarium]]", redirect = "Apothecarium",},
			["The Aquamarine Ward"] = { content = "==Source==\r\nThis item can be crafted using [[Jewelcrafting]] (245); taught by Design: The Aquamarine Ward. The [[recipe]] is dropped by level 47-54 creatures everywhere in [[Azeroth]].",},
			["The Arcatraz"] = { content = "#REDIRECT [[Arcatraz]]", redirect = "Arcatraz",},
			["The Archivist"] = { content = "==Objectives==\r\nTravel to [[Stratholme]] and find [[Archivist Galford]] of the [[Scarlet Crusade]]. Destroy him and burn down the Scarlet Archive.\r\n* Archivist Galford slain\r\n* Archive Burned\r\n==Description==\r\nAnything taken to an extreme is hazardous to our world, <name>. Take for example, the Scarlet Crusade. Do you believe that their blind zealotry serves a greater good? How many innocents have they destroyed in the name of the Light?\r\nBlasphemers, one and all!\r\nOne in particular interests me, though; the Archivist Galford of Stratholme: A man that watches over the Crusade's most valued documents. Destroy him and burn down his archives! Should you succeed, return to me and be rewarded. \r\n==Rewards==\r\nYou will receive: 1 gold 80 silver \r\n==Completion==\r\nOutstanding, <name>! Years of intelligence, lost! The Scarlet Crusade will surely feel this blow in the coming weeks.\r\n==Notes==\r\nCompleting this quest allows you to loot the Head of Balnazzar from [[Balnazzar]], which starts The Truth Comes Crashing Down.",},
			["The Argent Hold"] = { content = "'''The Argent Hold''' is located in [[Eastern Plaguelands]]. \r\n==Quests==\r\n*The Argent Hold",},
			["The Argent Stand"] = { content = "#REDIRECT [[Argent Stand]]", redirect = "Argent Stand",},
			["The Argent Vanguard"] = { content = "#REDIRECT [[Argent Vanguard]]", redirect = "Argent Vanguard",},
			["The Art of the Imbue"] = { content = "This quest is part of the quest chain, which allows [[blacksmith]]s to specialize in [[Armorsmithing]].\r\n==Objectives==\r\nBring forty [[Mithril Bar]]s and four [[Citrine]]s to [[Galvan the Ancient]] in [[Stranglethorn]].\r\n* Mithril Bar\r\n* Citrine\r\n==Quest text==\r\nThe harvesting of precious gems is of utmost importance to our craft,\r\n<name>. Few gems are more precious than the [[citrine]]. The magical\r\nproperties we imbue into our goods are amplified greatly by the\r\npresence of citrine.\r\nFor this lesson, we will fortify forty bars of [[Mithril Bar|mithril]]\r\nwith four citrines. The result will be a better understanding of magical\r\ngemology and the knowledge to create ornate mithril shoulders.\r\n==Progress==\r\nAfter such mining, your muscles bulge and your body aches!\r\n==Completion==\r\nOne can barely keep their eyes from leaving its splendor, <name>.\r\nAye, citrine is a glorious gem.\r\nPay attention and learn what such a discovery may teach us!\r\n==Reward==\r\n*390-3900 XP\r\n*Plans: Ornate Mithril Shoulder\r\n==Notes == \r\nThe [[Ornate Mithril Shoulder]]s are required to complete the quest A Good Head On Your Shoulders.",},
			["The Art of the Trading Card Game"] = { content = "''Upper Deck and Blizzard Entertainment® today announced the January 2008 release of a new hardcover book titled World of Warcraft®: The Art of the Trading Card Game, which will feature artwork created for the highly popular World of Warcraft Trading Card Game (TCG). Published by Chronicle Books, the 288-page, 11”x9” book will include more than 300 full-color iconic pieces of art featured during the first year of release of the World of Warcraft TCG.''\r\n''World of Warcraft: The Art of the Trading Card Game will feature a collection of sketches, paintings and finished artwork highlighting a selection of World of Warcraft’s most valiant heroes, devastating spellcasters and bloodthirsty creatures created by some of today’s top fantasy artists. These artists include Todd McFarlane (Spawn), Greg Staples (Judge Dredd), Zoltan Boros and Gabor Szikszai (InQuest Gamer magazine’s “Artists of the Year” recipients), Marcelo Vignali (Disney Animation), and Todd Lockwood (Forgotten Realms), among others.''<ref></ref>",},
			["The Art of Warcraft"] = { content = "'''''The Art of Warcraft''''' artbook was originally distributed in the ''[[Warcraft III: Reign of Chaos Collector's Edition|Warcraft III]]'' [[Collector's Edition]], which was sold for a limited time in 2002. The artbook was later offered for purchase as a single item with its own ISBN, but like the Collectors Edition of the game, has since gone out of print. However, both the Collector's Edition of Warcraft III and ''The Art of Warcraft'' book can still be found for sale at various book outlets and on auction sites like eBay, in used condition.\r\n==Description==\r\n''The Art of Warcraft features an inside look at the stunning art from the Warcraft series. Art from every stage of game development will be included, from early concepts to finished pieces, along with behind-the-scenes commentary from the Blizzard development team. Enoromous coverage including Warcraft III: Reign of Chaos, Warcraft II, and Warcraft, plus an exclusive glimpse at the upcoming World of Warcraft game. Anecdotal captions relevant to the story and events of the Warcraft series are also included. This timeless reference piece will give countless hours of enjoyment to avid Warcraft gamers everywhere!''\r\n==Artists==\r\n2D artists\r\nCinematics",},
			["The Art of World of Warcraft"] = { content = "'''The Art of World of Warcraft''', also '''The Art of World of Warcraft Coffee Table Book''', artbook was originally distributed in the [[World of Warcraft Collector's Edition]]. Currently, ''The Art of World of Warcraft'' is available as a reprint in its original hardcover form with ISBN 0744007259. (The artbook that was distributed with the World of Warcraft Collectors Edition does not have an ISBN.) \r\nUnlike ''[[The Art of Warcraft]]'' artbook, ''The Art of World of Warcraft'' contains no commentary.\r\n==Description==\r\nThe World of Warcraft is more than just a game, it's a work of art – and you can enjoy these unique creations outside of the game with The Art of World of Warcraft. This beautiful hardbound book contains sketches, concepts, and final colored art for the following:\r\n*All eight races — Dwarf, Gnome, Human, Night Elf, Orc, Tauren, Troll, and Undead\r\n*Monsters — from the Ancients to Magnataurs to Yeti\r\n*Environments — landscapes and flora, from the magnificent beauty of Emerald Paradise to the bleak wasteland of Desolace\r\n*Structures & Weapons — buildings, transports, arms, and armor\r\n*Cinematics — from storyboard to finished art\r\n*Promotional — full-page artwork, special drawings from Korea, and the Blizzard 2003 Christmas Card\r\n==Pages of the book==\r\n*An [[orc]] [[warrior]] captioned '''Veteran Warrior'''. He is missing half of one his arms, pg. 7.\r\n*An orc male captioned '''Ol' Scarface'''. He has obvious scars on his face, pg. 7.\r\n*An orc male captioned '''Holy Man''', pg. 11.\r\n*An orc female captioned '''Lady Tracker'''. She is holding a spear, pg. 12.\r\n*A [[human]] [[thief]] captioned '''Defias Thief''', pg. 20.\r\n*A human [[farmer]] captioned '''Westfall Farmer'''., pg. 21.\r\n*A human [[knight]] captioned '''Weathered Knight'''. He has arrows sticking out of his armor but is still ready to fight, pg. 21.\r\n*Two images depicting a human female captioned '''Hostess'''. She is holding a fan, pg. 21.\r\n*A [[dwarven]] female [[paladin]] captioned '''Lady Paladin''', pg. 28.\r\n*A piece of artwork, captioned '''[[Undersea Hills]]''', pg. 29.\r\n*Two images depicting a [[dwarf]] captioned '''Dwarven Merchant'''. He is holding a club and a lantern, pg. 29.\r\n*A dwarven female captioned '''Young Gryphon Rider'''. She is holding a [[Stormhammer]], pg. 29.\r\n*An [[undead]] captioned '''Groovy Goulie'''. He seems to be dancing, pg. 32.\r\n*An undead male is called '''Forsaken Lord''', pg. 32.\r\n*A [[centaur]] captioned '''Centaur Champion''', pg. 29.\r\n*A [[green dragon]] captioned '''Emerald Dragon''', pg 53.\r\n*An unknown race captioned '''Blade Warrior''', pg 65.\r\n*A [[half-orc]] female captioned '''Warrior Woman''', pg. 65.\r\n*An unknown male creature captioned '''[[Dragonman]]''', pg. 68.\r\n*A [[silithid]], captioned '''Silithid Beatle''', pg. 71.\r\n*A [[worm]] captioned '''Tunnel Worm''', pg. 76.\r\n*Three images depicting [[bog beast]]s, captioned '''Swampthing''' and '''Swamp Thing''', pg. 78-79.\r\n*An [[undead]], captioned '''Scourge Executioner''', pg. 85.\r\n*A [[darkhound]], captioned '''Darhound''', pg. 87.\r\n*An unknown male creature, captioned '''[[Jackal Man]]''', pg. 89.\r\n*Two images depicting unknown creatures, captioned '''[[Magma Beast]]''' and '''Magma Beasts''', pg. 89.\r\n*An [[ogre]] male, captioned '''Ogre Warlord''', pg. 90.\r\n*Two images depicting an unknown creature, captioned '''Were Wolves''', pg. 91.",},
			["The Art of World of Warcraft: The Burning Crusade"] = { content = "'''The Art of World of Warcraft: The Burning Crusade''' artbook was originally distributed in the [[World of Warcraft: The Burning Crusade Collector's Edition]]. \r\n''The Art of World of Warcraft: The Burning Crusade'' contains no commentary.",},
			["The Ashbringer"] = { content = "#redirect [[Alexandros Mograine]]", redirect = "Alexandros Mograine",},
			["The Badlands"] = { content = "#REDIRECT [[Badlands]]", redirect = "Badlands",},
			["The Banquet Hall"] = { content = "#REDIRECT [[Banquet Hall]]", redirect = "Banquet Hall",},
			["The Barrens"] = { content = "#REDIRECT [[Barrens]]", redirect = "Barrens",},
			["The Barrier Hills"] = { content = "#redirect [[Barrier Hills]]", redirect = "Barrier Hills",},
			["The Battle for Arathi Basin!"] = { content = "Were you looking for:\r\n* [[The Battle for Arathi Basin! (Alliance, 25)]]\r\n* [[The Battle for Arathi Basin! (Horde, 25)]]\r\n* [[The Battle for Arathi Basin! (Alliance, 35)]]\r\n* [[The Battle for Arathi Basin! (Horde, 35)]]\r\n* [[The Battle for Arathi Basin! (Alliance, 45)]]\r\n* [[The Battle for Arathi Basin! (Horde, 45)]]\r\n* [[The Battle for Arathi Basin! (Alliance, 55)]]\r\n* [[The Battle for Arathi Basin! (Horde, 55)]]",},
			["The Battle for Arathi Basin! (Alliance, 25)"] = { content = "==Objectives==\r\nAssault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in [[Refuge Pointe]]. \r\n* [[Gold Mine (Arathi Basin)|Mine]] Assaulted: 0/1\r\n* [[Lumber Mill (Arathi Basin)|Lumber Mill]] Assaulted: 0/1\r\n* [[Blacksmith (Arathi Basin)|Blacksmith]] Assaulted: 0/1\r\n* [[Farm (Arathi Basin)|Farm]] Assaulted: 0/1\r\n== Description==\r\n<name>, the battle for [[Arathi Basin]] is a battle for resources and territory. Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies. I charge you to assault the points farthest from our [[Arathi Basin]] base.\r\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy. Find the enemy's banner and rip it from its flag post!\r\nWhen you have done this to all four points, return to me. \r\n== Reward==\r\nYou will receive:35 silver copper \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*2000 [[XP]] \r\n*500 [[reputation]] with the [[League of Arathor]]",},
			["The Battle for Arathi Basin! (Alliance, 35)"] = { content = "==Objectives==\r\nAssault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in [[Refuge Pointe]]. \r\n* [[Gold Mine (Arathi Basin)|Mine]] Assaulted: 0/1\r\n* [[Lumber Mill (Arathi Basin)|Lumber Mill]] Assaulted: 0/1\r\n* [[Blacksmith (Arathi Basin)|Blacksmith]] Assaulted: 0/1\r\n* [[Farm (Arathi Basin)|Farm]] Assaulted: 0/1\r\n== Description==\r\n<name>, the battle for [[Arathi Basin]] is a battle for resources and territory. Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies. I charge you to assault the points farthest from our [[Arathi Basin]] base.\r\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy. Find the enemy's banner and rip it from its flag post!\r\nWhen you have done this to all four points, return to me. \r\n== Reward==\r\nYou will receive:75 silver copper \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\nUpon completion of this quest you will gain:\r\n*? [[XP]] \r\n*500 [[reputation]] with the [[League of Arathor]]",},
			["The Battle for Arathi Basin! (Alliance, 45)"] = { content = "==Objectives==\r\nAssault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in [[Refuge Pointe]]. \r\n* [[Gold Mine (Arathi Basin)|Mine]] Assaulted: 0/1\r\n* [[Lumber Mill (Arathi Basin)|Lumber Mill]] Assaulted: 0/1\r\n* [[Blacksmith (Arathi Basin)|Blacksmith]] Assaulted: 0/1\r\n* [[Farm (Arathi Basin)|Farm]] Assaulted: 0/1\r\n== Description==\r\n<name>, the battle for [[Arathi Basin]] is a battle for resources and territory. Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies. I charge you to assault the points farthest from our [[Arathi Basin]] base.\r\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy. Find the enemy's banner and rip it from its flag post!\r\nWhen you have done this to all four points, return to me. \r\n== Reward==\r\nYou will receive:1 gold 30 silver copper \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*500 [[reputation]] with the [[League of Arathor]]",},
			["The Battle for Arathi Basin! (Alliance, 55)"] = { content = "==Objectives==\r\nAssault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in [[Refuge Pointe]]. \r\n* [[Gold Mine (Arathi Basin)|Mine]] Assaulted: 0/1\r\n* [[Lumber Mill (Arathi Basin)|Lumber Mill]] Assaulted: 0/1\r\n* [[Blacksmith (Arathi Basin)|Blacksmith]] Assaulted: 0/1\r\n* [[Farm (Arathi Basin)|Farm]] Assaulted: 0/1\r\n== Description==\r\n<name>, the battle for [[Arathi Basin]] is a battle for resources and territory. Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies. I charge you to assault the points farthest from our [[Arathi Basin]] base.\r\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy. Find the enemy's banner and rip it from its flag post!\r\nWhen you have done this to all four points, return to me. \r\n== Reward==\r\nYou will receive:1 gold 65 silver copper \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*2000 [[XP]] (or 34 silver 50 copper at level 70)\r\n*500 [[reputation]] with the [[League of Arathor]]",},
			["The Battle for Arathi Basin! (Horde, 25)"] = { content = "==Objectives==\r\nAssault the [[Arathi Basin]] mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in [[Hammerfall]].\r\n* [[Gold Mine (Arathi Basin)|Mine]] Assaulted: 0/1\r\n* [[Lumber Mill (Arathi Basin)|Lumber Mill]] Assaulted: 0/1\r\n* [[Blacksmith (Arathi Basin)|Blacksmith]] Assaulted: 0/1\r\n* [[Stables (Arathi Basin)|Stables]] Assaulted: 0/1\r\n== Description==\r\nAs you no doubt have heard, the League of Arathor is sending large numbers of troops into [[Arathi Basin]]. Eager for food and supplies, these [[Alliance]] fools are intent to take and control the rich resources there. We must show them that Arathi will never again be a home for humans!\r\nGo to [[Arathi Basin]] and assault the mine, the lumber mill, the blacksmith and the stables. Pull down the enemies' banners, declaring those territories for the [[Horde]].\r\nGo, <name>. Report back to me when this task is complete. \r\n== Reward==\r\nYou will receive:35 silver copper \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*2000 [[XP]] \r\n*500 [[reputation]] with the [[Defilers]]",},
			["The Battle for Arathi Basin! (Horde, 35)"] = { content = "==Objectives==\r\nAssault the [[Arathi Basin]] mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in [[Hammerfall]].\r\n* [[Gold Mine (Arathi Basin)|Mine]] Assaulted: 0/1\r\n* [[Lumber Mill (Arathi Basin)|Lumber Mill]] Assaulted: 0/1\r\n* [[Blacksmith (Arathi Basin)|Blacksmith]] Assaulted: 0/1\r\n* [[Stables (Arathi Basin)|Stables]] Assaulted: 0/1\r\n== Description==\r\nAs you no doubt have heard, the League of Arathor is sending large numbers of troops into [[Arathi Basin]]. Eager for food and supplies, these [[Alliance]] fools are intent to take and control the rich resources there. We must show them that Arathi will never again be a home for humans!\r\nGo to [[Arathi Basin]] and assault the mine, the lumber mill, the blacksmith and the stables. Pull down the enemies' banners, declaring those territories for the [[Horde]].\r\nGo, <name>. Report back to me when this task is complete. \r\n== Reward==\r\nYou will receive:75 silver copper \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*2750 [[XP]] \r\n*500 [[reputation]] with the [[Defilers]]",},
			["The Battle for Arathi Basin! (Horde, 45)"] = { content = "==Objectives==\r\nAssault the [[Arathi Basin]] mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in [[Hammerfall]].\r\n* [[Gold Mine (Arathi Basin)|Mine]] Assaulted: 0/1\r\n* [[Lumber Mill (Arathi Basin)|Lumber Mill]] Assaulted: 0/1\r\n* [[Blacksmith (Arathi Basin)|Blacksmith]] Assaulted: 0/1\r\n* [[Stables (Arathi Basin)|Stables]] Assaulted: 0/1\r\n== Description==\r\nAs you no doubt have heard, the League of Arathor is sending large numbers of troops into [[Arathi Basin]]. Eager for food and supplies, these [[Alliance]] fools are intent to take and control the rich resources there. We must show them that Arathi will never again be a home for humans!\r\nGo to [[Arathi Basin]] and assault the mine, the lumber mill, the blacksmith and the stables. Pull down the enemies' banners, declaring those territories for the [[Horde]].\r\nGo, <name>. Report back to me when this task is complete. \r\n== Reward==\r\nYou will receive:1 gold 30 silver copper \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*500 [[reputation]] with the [[Defilers]]",},
			["The Battle for Arathi Basin! (Horde, 55)"] = { content = "==Objectives==\r\nAssault the [[Arathi Basin]] mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in [[Hammerfall]].\r\n* [[Gold Mine (Arathi Basin)|Mine]] Assaulted: 0/1\r\n* [[Lumber Mill (Arathi Basin)|Lumber Mill]] Assaulted: 0/1\r\n* [[Blacksmith (Arathi Basin)|Blacksmith]] Assaulted: 0/1\r\n* [[Stables (Arathi Basin)|Stables]] Assaulted: 0/1\r\n== Description==\r\nAs you no doubt have heard, the League of Arathor is sending large numbers of troops into [[Arathi Basin]]. Eager for food and supplies, these [[Alliance]] fools are intent to take and control the rich resources there. We must show them that Arathi will never again be a home for humans!\r\nGo to [[Arathi Basin]] and assault the mine, the lumber mill, the blacksmith and the stables. Pull down the enemies' banners, declaring those territories for the [[Horde]].\r\nGo, <name>. Report back to me when this task is complete. \r\n== Reward==\r\nYou will receive: 1 gold 65 silver copper \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*2750 [[XP]] (or 34 silver 50 copper at level 70)\r\n*500 [[reputation]] with the [[Defilers]]",},
			["The Battle for Mount Hyjal"] = { content = "#REDIRECT [[Battle of Mount Hyjal]]", redirect = "Battle of Mount Hyjal",},
			["The Battle For The Ebon Hold"] = { content = "==Objectives==\r\nSlay 10 [[Scourge]] and help kill Patchwerk. Return to [[Highlord Darion Mograine]] should you succeed.\r\n* Patchwerk slain\r\n* Scourge slain: (10)\r\n==Description==\r\nThe [[Hall of Command]] has been secured, but the [[Lich King]] has left us a little present in the [[Heart of Acherus]]. The stitched terror, Patchwerk, and a horde of abominations have taken over the second floor.\r\nUse the teleporter to get to the second floor and destroy the Scourge forces that remain. Do not engage Patchwerk alone! You must fight the monstrosity with other [[death knight]]s of [[Acherus: The Ebon Hold|Acherus]]!\r\nGo, <name>. You have my strength to carry you!\r\n==Rewards==\r\nYou will receive: 2 gold 50 silver \r\n==Progress==\r\nAcherus will be ours!\r\n==Completion==\r\nWell done, death knight. The remaining Scourge will be dealt with in short order and the rebuilding process will begin anew.\r\nI have but one last task for you.\r\n==Notes==\r\nDeath knights are still buffed with The Might of Mograine, drastically increasing health and damage done, and providing plenty of healing while attacking the elites on the second floor.",},
			["The Battle For The Undercity (Alliance)"] = { content = "==Objectives==\r\nAssist [[King Varian Wrynn]] and [[Lady Jaina Proudmoore]] in bringing [[Grand Apothecary Putress]] to justice! Report to King Varian Wrynn should you succeed.\r\n* Assist King Varian Wrynn\r\n==Description==\r\nDeep inside the bowels of the [[Undercity]] hides the assassin responsible for the deaths of [[Bolvar Fordragon|Bolvar]] and our brave soldiers at [[Angrathar the Wrath Gate|the Wrath Gate]].\r\nVarian has brought the full might of the [[Alliance]] with him to assist in the take down. Join him and Lady Proudmoore in the manhunt and earn your place among the greatest champions of the Alliance!\r\nSpeak to King Varian Wrynn when you are ready. \r\n==Completion==\r\nFor too long have the Horde been left unchecked. We allowed their territories to prosper and in return for our generosity they plotted and planned our demise.\r\nPeace? Useless... it's gotten us nowhere. We have lost some of our greatest heroes to \"peace.\" Let us see what battle brings.\r\nReturn to Northrend, <name>. Conquer it for your king - FOR THE ALLIANCE!\r\n==Notes==\r\nTalk to Varian to start the event:\r\n ''Reporting for duty, your majesty! Let the assault begin!''\r\n5 minutes until the manhunt begins:\r\nKing Varian Wrynn yells: Heroes of the Alliance, your King calls! Gather behind me at the entrance to the sewers of the Undercity!\r\nKing Varian Wrynn yells: Hidden inside this defiled city is the wretch responsible for murdering our brothers and sisters at the Wrath Gate! He must be brought to justice!\r\n3 minutes:\r\nKing Varian Wrynn yells: Soon we march upon this cursed place and cleanse it of its evil taint!\r\n2 minutes:\r\nKing Varian Wrynn yells: The hour of our redemption is close at hand! Prepare yourselves!\r\nThe manhunt begins:\r\nKing Varian Wrynn yells: The march upon the Undercity begins now! Be empowered by your King's strength! Follow me, heroes! FOR THE GLORY OF THE ALLIANCE!\r\n''Varian buffs all nearby allies with \"Strength of Wrynn\", adding 30,000 HP, and a 10k healing on damage taken buff.\r\nKing Varian Wrynn yells: Onward, brothers and sisters! Destiny awaits!\r\n''The party reaches the sewer entrance''\r\nKing Varian Wrynn says: Our descent into the depths of depravity begins! Be on guard! Jaina, lend us your strength!\r\nLady Jaina Proudmoore says: Right away, your majesty!\r\n''Jaina casts \"Improved Brilliance Aura\", which regenerates more mana/rage/energy/RP that can possibly be used and a runspeed buff. At the bottom of the tunnel, the party stops as waves upon waves of enemies are unleashed.''\r\nKing Varian Wrynn says: What is this?! Stand your ground! Do not give them an inch!\r\n''Eventually, Putress unleashes the [[Engorged Blight Worm]], which has 5 million HP. After the worm is defeated...''\r\nKing Varian Wrynn yells: Solders, fall in! Guard the halls!\r\nKing Varian Wrynn yells: Your abberrations are no match for the Alliance, Putress! We're coming for you!\r\n''The party reaches the canals and the corpse of [[Khanok the Impassable]]''\r\nLady Jaina Proudmoore says: What's happened here? There are corpses everywhere... the stench... overwhelming...\r\nKing Varian Wrynn says: Horde. By the looks of the struggle, they are here in force - somewhere.\r\nKing Varian Wrynn says: Stay alert and on guard. There's no telling what horrors await us.\r\nKing Varian Wrynn says: ONWARD!\r\nGrand Apothecary Putress yells: Do not let them pass, minions!\r\n''The party fights a large group of [[Treacherous Guardian]]s''\r\nGrand Apothecary Putress yells: KILL THEM! My work must not be interrupted!\r\nKing Varian Wrynn says: The main chamber is this way! Let's go!\r\n''The party fights their way through a large group of [[Perfidious Dreadlord]]s to get to the bottom of the Apothecarium''\r\nKing Varian Wrynn says: THERE!\r\nKing Varian Wrynn yells: There's nowhere to run, monster!\r\nGrand Apothecary Putress yells: Stare into the abyss and watch as it blackens your souls!\r\nGrand Apothecary Putress yells: You are no match for my creations!\r\n''Putress spawns untold numbers of failed experiments.''\r\nGrand Apothecary Putress yells: This cannot be happening!\r\nGrand Apothecary Putress yells: It will not end like this! I've worked too hard! So many years... I... I will consume more energy!\r\nGrand Apothecary Putress yells: The power washes through me! I see... EVERTHING!\r\nGrand Apothecary Putress yells: MORE SUFFERING AWAITS!\r\n''Putress joins the fight with a 7.4M HP pool. Melee hits on cloth are over a million, so let Varian tank him. He also throws blight barrels for 10k a tick as the failed experiments keep spawning, though not as quickly as before. Eventually he is defeated.''\r\nKing Varian Wrynn yells: And justice is served!\r\n''Varian loots Putress's corpse.''\r\nKing Varian Wrynn says: What say you now, Putress?\r\nKing Varian Wrynn says: Look around you, brothers and sisters. Open your eyes! Look at what they have done to our kingdom!\r\nKing Varian Wrynn says: How much longer will we allow these savages free reign in our world?\r\nKing Varian Wrynn says: I have seen the Horde's world. I have been inside their cities. Inside their minds...\r\nKing Varian Wrynn says: I know what evil lies in the hearts of orcs.\r\nThrall yells [Orcish] Mog Osh'kazil gul'rok il mog Ro'th zaga maza TOV'OSH (''The Undercity belongs to the Horde once more! LOK'TAR!'')\r\nKing Varian Wrynn says: THRALL! HERE?\r\nKing Varian Wrynn says: ONWARD! We end this now!\r\nLady Jaina Proudmoore says: Varian, stop! I won't help you do this!\r\n''Jaina stays behind as the party moves on. Varian and the remainder of the party reach the throne room, where Thrall, Sylavanas and a host of Warsong Battleguards await''\r\nKing Varian Wrynn says: The orcs have a battle cry: LOK'TAR OGAR! It means \"victory or death.\" Fitting...\r\nKing Varian Wrynn says: To the throne room!\r\n''The party walks in.''\r\nKing Varian Wrynn says: I was away for too long. My absence cost us the lives of some of our greatest heroes. Trash like you and this evil witch were allowed to roam free -- unchecked.\r\nKing Varian Wrynn says: The time has come to make things right. To disband your treacherous kingdom of murderers and thieves. Putress was the first strike. Many more will come.\r\nKing Varian Wrynn says: I've waited a long time for this, Thrall. For every time I was thrown into one of your damned arenas... for every time I killed a green-skinned abberation like you... I could only think of one thing.\r\nKing Varian Wrynn says: What our world could be without you and your twisted Horde... It ends now, Warchief.\r\nKing Varian Wrynn says: ATTACK! FOR STORMWIND! FOR BOLVAR! FOR THE ALLIANCE!\r\n''The fight is joined.''\r\nLady Jaina Proudmoore yells: VARIAN, NO! STOP!\r\n''Lady Jaina Proudmoore incapacitates all units with a freeze spell''\r\nLady Jaina Proudmoore says: It did not have to be like this...\r\n''Lady Jaina Proudmoore teleports all Alliance forces back to Stormwind''",},
			["The Battle For The Undercity (Horde)"] = { content = "==Objectives==\r\nAssist [[Thrall]] and [[Sylvanas]] in retaking the [[Undercity]] for the [[Horde]].\r\nReport to Thrall should you succeed. \r\n==Description==\r\nThe entirety of the [[Undercity]] is controlled by [[Varimathras]]. Our soldiers stand ready, waiting for the Warchief to give the attack orders.\r\nHelp the Horde take back the Undercity and earn your place among our greatest champions! Should you survive the assault, report to Thrall.\r\nCheck in with the Warchief when you are ready to begin.\r\n==Completion==\r\nTomorrow brings with it uncertainty. Gone are the days of Alliance and Horde battling alongside each other in pursuit of a common enemy. A new battle dawns, <name> - a battle which there can be no victor.\r\nBut we must continue our march towards [[Icecrown]]. We have no choice in that matter. Our salvation lies with heroes like you, <name>. The future of the Horde - of the world - depends on you.\r\nLet us return to [[Orgrimmar]]. You must return to [[Northrend]] at once.\r\n==Notes==\r\nTalk to Thrall to start the event:\r\n ''I am ready, Warchief.''\r\n5 minutes until the manhunt begins:\r\nThrall yells: HEROES OF THE HORDE, YOUR WARCHIEF CALLS!\r\nThrall yells: Gather behind me at the gates of the Undercity! Soon we march upon our fallen city and reclaim it - FOR THE HORDE!\r\n3 minutes:\r\nThrall yells: Blood and thunder, champions of the Horde! We fight on this day for our fallen brothers and sisters! Mourn them not for they all died with honor in their hearts!\r\nThrall yells: Though we face great conflict, our might combined shall obliterate those who would oppose us! The grave injustices committed against the Horde will be met by an unstoppable force of reckoning!\r\nThe manhunt begins:\r\nThrall yells: I call to you great spirits! Grant the Horde your blessing! For on this day our cause is righteous and just!\r\nThrall yells: Spirits of wind, carry to Saurfang the Younger the song of war! May ALL of our fallen brethren be vindicated by this battle!\r\nThrall yells: The battle for the Undercity begins now! Sound the horns of war! Champions of the Horde, be empowered by the might of your Warchief!\r\n''Thrall buffs all nearby allies with \"Warchief's Blessing\", adding 30,000 HP, and a 10k healing on damage taken buff.\r\nThrall yells: ONWARD!\r\n''The party reaches the ruins entrance''\r\nThrall says: Great wind brother, clear our path!\r\n''A wind clears away the blight from Thrall's path.''\r\n''Thrall enters the courtyard, and Varimathras appears.''\r\nThrall yells: You must answer to the elements, demon!\r\nVarimathras yells: Welcome to my kingdom of darkness!\r\nVarimathras yells: Did you enjoy my minion's terrible creation? Potent, is it not?\r\nVarimathras yells: But enough prattling! You wish to reclaim your city? Come then, heroes! Your souls will fuel the host! You will have this place back in pieces!\r\nThrall says: Great water spirit, wash away this corruption!\r\nThrall yells: ATTACK!!!!\r\nLady Sylvanas Windrunner begings to sing.\r\n''Sylvanas casts \"Song of Sylvanas\", which regenerates more mana/rage/energy/RP that can possibly be used and a runspeed buff. At the end of the courtyard, the party stops as waves upon waves of enemies are unleashed.''\r\n''Eventually, Varimathras unleashes the [[Blight Aberration]], which has 5 million HP. After the flesh giant is defeated...''\r\nThrall yells: The courtyard is ours! Onward to the inner sanctum!\r\n''The party reaches the elevators''\r\nThrall says: HOLD! They've destroyed the elevators!\r\nLady Sylvanas Windrunner says: The shaft is trapped, Warchief. A fall would mean certain death.\r\nThrall says: Great air spirit, hear my call once more!\r\nThrall says: The spirits of air have heard my call. Cyclones will lower us to safety. Now we jump!\r\nThrall yells: We have breached the inner sanctum, heroes! We press on!\r\n''The party reach the inner district''\r\nLady Sylvanas Windrunner says: What have they done to my beautiful city!\r\nLady Sylvanas Windrunner says: The only redemption for the traitors responsible for this will be an agonizing death. My vengeance will be swift and without mercy!\r\nThrall says: Lead the way, Dark Lady. We will follow.\r\nLady Sylvanas Windrunner says: Very well, Warchief. The Royal Quarter is this way. Stay on guard. There's no telling what Varimathras and Putress have in store for us.\r\n''The party reach the sewers''\r\nLady Sylvanas Windrunner says: HOLD! I sense dark magic. Demon magic... Stand ready!\r\nVarimathras yells: Clever girl...\r\nVarimathras yells: My brothers have grown hungry. Your souls will sate their appetites.\r\n''Eventually, Varimathras unleashes [[Khanok the Impassable]], which has 6 million HP. After the [[Ered'ruin]] demon is defeated...''\r\nThrall yells: Is that all, demon? Have you nothing left to throw at us?\r\nThrall yells: We come for you! Prepare yourself!\r\n''The party cross the bridge''\r\nLady Sylvanas Windrunner says: The Royal Quarter is just up ahead, Warchief.\r\nVarimathras yells: Bring down the halls! NOW!\r\n''Varimathras makes the halls shake, bringing down stones to block the hall to the [[Royal Quarter]].''\r\nThrall yells: COWARD! You think to stop the Warchief of the Horde with pebbles? I will show you the true power of the elements!\r\nThrall yells: Great spirit of the earth, help us in our hour of need!\r\n''Thrall brings down the stone blocks and clears the path''\r\nThrall yells: LET'S GO! QUICKLY!\r\n''The party arrives at the Royal Quarter, where Varimathras is opening a number of [[Burning Legion]] portals.''\r\nThrall yells: What is this?\r\nVarimathras yells: Welcome to your future -- what little there is left of it...\r\n''Varimathras spawns untold numbers of demons.''\r\nVarimathras yells: Too long... Tireless, endless planning... It will not end like this...\r\nVarimathras yells: Need more time... The Master is near...\r\nVarimathras yells: Such power! Can you not feel it, mortals? Cease this foolishness and join me!\r\nVarimathras yells: I will not fail! Not again!\r\nVarimathras yells: I cannot hold... Destabilizing...\r\nA distant voice yells: YOU HAVE FAILED ME, VARIMATHRAS!\r\nVarimathras yells: A thousand-thousand pardons, Master! I will deal with these intruders myself!\r\n''Varimathras joins the fight with a 7.7M HP pool. Melee hits on cloth are over a million, so let Thrall tank him. He also casts a knockback Shadow Nova, Drain Life and other attacks as the demons keep spawning, though not as quickly as before. Eventually he is defeated.''\r\nVarimathras yells: Years... wasted...\r\nThrall yells: WE ARE VICTORIOUS!\r\nThrall yells: The Undercity belongs to the Horde once more! LOK'TAR!\r\nThrall says: Dark Lady, join me! You have fought hard and spilled much blood for this right. The Royal Quarter belongs to you!\r\nLady Sylvanas Windrunner says: Such will be the fate of all enemies of the Horde, Warchief. Now we must deal with the wretch, Putress.\r\nThrall says: We shall, Sylvanas...\r\nThrall says: Alliance horns? Stay on guard!\r\n''The king and his group walks in.''\r\nKing Varian Wrynn says: I was away for too long. My absence cost us the lives of some of our greatest heroes. Trash like you and this evil witch were allowed to roam free -- unchecked.\r\nKing Varian Wrynn says: The time has come to make things right. To disband your treacherous kingdom of murderers and thieves. Putress was the first strike. Many more will come.\r\nKing Varian Wrynn says: I've waited a long time for this, Thrall. For every time I was thrown into one of your damned arenas... for every time I killed a green-skinned aberration like you... I could only think of one thing.\r\nKing Varian Wrynn says: What our world could be without you and your twisted Horde... It ends now, Warchief.\r\nKing Varian Wrynn says: ATTACK! FOR STORMWIND! FOR BOLVAR! FOR THE ALLIANCE!\r\n''The fight is joined.''\r\nLady Jaina Proudmoore yells: VARIAN, NO! STOP!\r\n''Lady Jaina Proudmoore incapacitates all units with a freeze spell''\r\nLady Jaina Proudmoore says: It did not have to be like this...\r\n''Lady Jaina Proudmoore teleports all Alliance forces back to Stormwind''\r\nThrall says: It ends like it began...\r\nThrall says: All that we have fought for in this world is lost. The hopes and dreams carried by [[Durotan|my father]] and [[Draka|mother]]... by [[Orgrim Doomhammer|Doomhammer]]... Gone...\r\nThrall says: If only you were here right now, old friend. You would know what to do.\r\nHigh Overlord Saurfang says: I know what he would do.\r\nHigh Overlord Saurfang says: He would say to you what I am about to say to you: Thrall. Lead your people.\r\nHigh Overlord Saurfang says: Let's go home, old friend.\r\nThrall nods.\r\nThrall says: It's good to have you back, Varok, old friend. I'm sorry about your boy.",},
			["The Battle of Darrowshire (quest)"] = { content = "This quest is part of the quest chain.\r\n==Objectives==\r\nPlace the [[Relic Bundle]] at the Darrowshire town square.\r\nPrevent [[Davil Crokford|Davil Lightfire]]'s death until the death of [[Horgus the Ravager|Horgus]].\r\nPrevent [[Joseph Redpath|Captain Redpath]]'s death until [[Redpath the Corrupted]] appears.\r\nDefeat Redpath the Corrupted.\r\nSpeak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home. \r\n*Accept Redpath's Forgiveness\r\n* Relic Bundle(Provided)\r\n== Description==\r\nNow, <name>, you will take part in [[battle of Darrowshire]], and you will save Joseph Redpath.\r\nPlace this relic bundle in the [[Darrowshire]] town square, and the spirits of Darrowshire will rise. Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.\r\nAfter defeating the corrupted Redpath, his spirit will be saved. Speak with him, then return to his daughter Pamela. \r\n==Progress==\r\nI think I heard ghosts outside. They whisper scary things to me...\r\n== Completion==\r\nThe fighting is over! I heard my daddy whisper to me. He scared away all the ghosts and he says he's coming home! I'm so happy!\r\nHe also said I should welcome you if came to our house, so I made some tea!\r\nI hope you like lots of sugar! \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*8300 [[XP]] (or 49 silver 50 copper at level 70)\r\n== Reward==\r\n* Tea with Sugar\r\n==Notes==\r\nDespite the fact that it is marked as a raid, this quest is doable with a regular five-man group at around level 60, provided the group is well-organized. It is also doable with the quester and one or two level 70s.",},
			["The Battle of Grim Batol"] = { content = "#REDIRECT [[Battle of Grim Batol]]", redirect = "Battle of Grim Batol",},
			["The Battle of Grim Batol (History of Warcraft)"] = { content = "'''\"The Battle of Grim Batol\"''' is a section of the [[History of Warcraft]], Chapter IV. It is set shortly after ''[[Warcraft II: Beyond the Dark Portal]]'', and recounts the events of the novel ''[[Day of the Dragon]]''.\r\nFound at:\r\n* [[Deepwater Tavern]] in [[Wetlands]].\r\n* [[Hall of Explorers]] in [[Ironforge]].\r\n* War Room of [[Stormwind Keep]] in [[Stormwind City]].\r\nTimeline: \r\n* ← Previous book: [[Icecrown and the Frozen Throne]]\r\n* → Next book: [[Lethargy of the Orcs]]",},
			["The Battle of Mount Hyjal"] = { content = "#REDIRECT [[Battle of Mount Hyjal]]", redirect = "Battle of Mount Hyjal",},
			["The Battle of Mount Hyjal (History of Warcraft)"] = { content = ": ''Were you looking for the [[Battle for Mount Hyjal]], the [[Caverns of Time]] instance?'''\r\n'''\"The Battle of Mount Hyjal\"''' is a section of the [[History of Warcraft]], Chapter V. It recounts events of ''[[Warcraft III: Reign of Chaos]]''. \r\nTimeline: \r\n* ← Previous book: [[Archimonde's Return and the Flight to Kalimdor]]\r\n* → Next book: [[The Betrayer Ascendant]]",},
			["The Bazaar"] = { content = "#REDIRECT [[Bazaar]]", redirect = "Bazaar",},
			["The Beast"] = { content = "'''The Beast''' is a [[boss]] found in [[UBRS|Upper Blackrock Spire]]. It appears to be a [[Core Hound]] that has been captured by the forces of [[Nefarian]] for use in his breeding experiments. (Experiments on other core hounds could account for the creation of [[Chromaggus]], a core hound-like dragonkin who is the second-to-last boss found in [[Blackwing Lair]].)\r\nAt some point before he is encountered by a party, the Beast had swallowed [[Finkle Einhorn]], a gnomish adventurer who has survived in the Beast's stomach for an unspecified period of time. Skinning The Beast will free Finkle.\r\n==Strategies==\r\nEssentially, a tank will need to keep aggro on The Beast at all times as he hits ''extremely'' hard and can kill a cloth wearer in 2 or 3 hits. The rest of the raid will want to DPS him. As long as the [[Main Tank]] can keep [[aggro]] (best to say the Main ''Tanks'', since it is unlikely that aggro can be consistently held, due to The Beast's oft-cast fears and random charges) and you have sufficient healing, this fight should be a simple one. He may drop Finkle's Skinner, which increases skinning by 10, so anyone in the group with a skinning skill of 300 should roll on this if they don't have it already, otherwise it can be greeded. It is ''vital'' to have a player in the raid who can skin The Beast, as they can receive the Pristine Hide of the Beast and also reveal [[Finkle Einhorn]], who is the start of a quest chain.\r\n'''NOTE:''' ''With the release of the [[Burning Crusade]] it is possible to raise your profession level to a maximum of 375, thus making it a simple task for any skinner who has been to Outland to skin The Beast.''",},
			["The Beast Within!"] = { content = "Written by Walter Simonson; Art by Ludo Lullabi and Sandra Hope; Covers by Jim Lee and Samwise Didier\r\nLo'Gosh and Broll continue their quest and encounter [[Harpy|harpies]] and [[furbolg]]s in [[Thistlefur]]. Will the duo succeed in freeing the furbolgs from the [[fel]] magic that curses them? Plus, Valeera continues tracking the mysterious figure who follows Lo'Gosh from the shadows.",},
			["The Beast Within"] = { content = "==Tips==\r\n*Sometimes known as the \"Hunter IWin Button\" – this is because it makes you immune to all types of [[crowd control]] for 18 seconds, and most classes rely on crowd control to win a fight to keep you in melee range during combat.",},
			["The Behemoth"] = { content = "'''The Behemoth''' is a level 50 [[elite]] [[rare mob]] [[dire troll]] found in [[Blackrock Mountain]]. He is in the [[Grinding Quarry]] near [[Overmaster Pyron]]'s tunnel and has an extremely long spawn time.\r\n==Loot==\r\n*Vilerend Slicer",},
			["The Best Defense"] = { content = "==Objectives==\r\nNether-Stalker Nauthis wants you to slay 12 Wrathbringers at [[Forge Base: Gehenna]], north of the [[Stormspire]]. \r\n*Wrathbringer slain (12)\r\n== Description==\r\nBrave acts of industrial sabotage will only get us so far, <name>. Just as [[Forge Base: Oblivion]] serves as an assembly site for Fel Reavers, Forge Base: Gehenna serves as a staging ground for their army as it is where the majority of the Legion's teleportation devices are located.\r\nI want you to go in there and put a dent in their numbers. They must have a full regiment of wrathbringers by now and we just can't allow that. \r\n== Completion==\r\nNice work, <name>. Keep it up and I'll put in a good word with the [[Nexus-Prince Haramad|Nexus-Prince]]. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*12300 [[XP]] (or 7 gold 38 silver copper at level 70)\r\n*250 [[reputation]] with [[The Consortium]]",},
			["The Betrayer Ascendant"] = { content = "'''\"The Betrayer Ascendant\"''' is a section of the [[History of Warcraft]], Chapter V. It recounts events of the night elf campaign of ''[[Warcraft III: The Frozen Throne]]''. \r\nFound at:\r\n* [[Darnassus]] - Tradesmen's Terrace \r\n* [[Silvermoon City]] - [[Walk of Elders]], Alchemy and Wand Vendors\r\nTimeline: \r\n* ← Previous book: [[The Battle of Mount Hyjal (History of Warcraft)|The Battle of Mount Hyjal]]\r\n* → Next book: [[Rise of the Blood Elves]]",},
			["The Bigger One"] = { content = "==Source==\r\nThis item is crafted by [[Engineers]] who have specialized in [[Goblin Engineering]], and have a minimum skill level of 325.\r\n3 of ''The Bigger One'' are constructed per combine.\r\nThe recipe for this item is taught by the [[Engineering Trainer|Goblin Engineering trainers]].\r\n===[[Goblin Engineering]]===\r\n* Dimensional Ripper - Area 52",},
			["The Biggest of Them All"] = { content = "==Objectives==\r\nSlay [[Mragesh]] and return to [[Zurjaya]] in [[Zabra'jin]]. \r\n*Mragesh slain\r\n* Potion of Water Breathing(Provided)\r\n== Description==\r\nYou've dealt with most of the little hydra, but I doubt [[Mragesh]] was impressed by your display. He's a cunning, ferocious beast and he's dogged many an angler in his time.\r\nI intend to be the last one he'll ever bother. He's bound to be hiding deep in the waters of Serpent Lake, to the northeast. He's a has-been; he just doesn't know it yet. \r\n== Reward==\r\nYou will also receive:3 gold 10 silver copper \r\n== Completion==\r\nI'm sure the old boy must've seen his days coming to an end. With all these new arrivals, the old order couldn't stand. It's just as well his spirit is at rest now. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*10750 [[XP]] (or 5 gold 16 silver copper at level 70)\r\n*250 [[reputation]] with [[Darkspear Trolls]]",},
			["The Big Bad Wolf"] = { content = "The '''Big Bad Wolf''' is a [[worgen]] boss in the Opera House in [[Karazhan]].\r\n==Attacks and Abilities==\r\n'''Terrifying Howl''' - Instant. Causes nearby enemies to flee in fear for 3 sec. Cast every 25-35 seconds.\r\n'''Little Red Riding Hood'''\r\n*Description: Changes the target into Little Red Riding Hood. This increases the likelihood that the Big Bad Wolf will chase them and try to gobble them up!\r\n*Effect: Reduces the target's armor and resistances to 0. Increases speed 50% to flee the Big Bad Wolf. Pacifies and Silences.\r\n'''Wide Swipe''' - Instant. Stuns the current target for 4 seconds. Casts about as often as Terrifying Howl. This '''''can''''' be used against a target with the Little Red Riding Hood debuff, possibly guaranteeing death.\r\n===Tanking===\r\n*Only one tank is usually needed. While a warrior, protection paladin or feral druid can fulfill the role, warriors have an advantage due to berserker rage.\r\n*Tank the wolf along one wall a medium distance away from the rest of the raid. If possible, switch to berserker stance to berserker rage just before a fear.\r\n*While someone has the Red Riding Hood debuff, you must continue tanking to generate aggro or risk the Big Bad Wolf attacking a DPS once the debuff has gone.\r\n*A [[Shaman]] can use a [[Tremor Totem]] to reduce the time spent under the influence of a fear. [[Enhancement]] shamans can keep the totem up for the duration of the fight. [[Elemental]] or [[Restoration]] Shaman will not be under the threat of constant fearing, and can instead drop the totem immediately after a fear, to more reliably break party members' fears.\r\n*If that is not possible, a [[Priest]]'s [[Fear Ward]] can counteract the fear. Note that this is now available to all races, and can be cast by a priest in [[Shadowform]].\r\n*Beside his fear, the wolf is not terribly difficult to tank and does not do a huge amount of damage.\r\n===Damage===\r\nRanged DPS classes can continuously damage the wolf provided that the tank does not lose aggro. They can continue damaging while the wolf is chasing Little Red Riding Hood. Melee DPS classes have to be more careful due to the fear. However, any damage caused while the Big Bad Wolf is chasing someone will add to his threat list, regardless of your inability to pull aggro during that time.\r\n===Little Red Riding Hood===\r\nAll non-melee players (ranged DPS and healing) should stand close together in a corner about a third to half the stage length from the wolf being tanked on the adjacent wall.\r\nWhen the wolf casts the Red Riding Hood debuff on you, you must run around the perimeter of the stage. Stay very close to the wall without touching or hugging it, as this will slow down your running speed. The wolf should be a short distance behind you at all times, but out of melee range. After running about 1.5 times around the stage, the debuff will wear off and the wolf will most likely run back to the tank as long as sufficient aggro was generated.\r\n*If you watch the Wolf's target carefully, he will briefly change targets to the upcoming Red Riding Hood then switch back to the tank, before he casts the debuff. This can give advance warning to the target, which is particularly useful to melee dps.\r\n*All healing should be focused on whomever has the debuff. The target can often survive one attack from the wolf as long as the target is healed as soon as they are hit. Healers should use preemptive heals, canceling at the last moment if the runner does not get attacked. A priest should use [[Power Word: Shield]]. [[Earth Shield]] and heal-over-time spells can also help.\r\n*The runner should follow a '''square''' path. The Wolf actually chases a spot 20 yards ahead of his target. The runner can imagine they're carrying a long fishing pole with a lure extended ahead of them. If Little Red Riding Hood runs in a circular or oval path, the Wolf will continuously cut them off and be in melee range. If Little Red Riding Hood runs in straight lines with tight corners, the Wolf will lose ground on the straightaways, cut off a little on the corners, but potentially stay out of melee range the entire time.\r\n*Be aware that while chasing Little Red Riding Hood, the wolf will continue to fear all nearby players, including the runner. [[Tremor Totem]] and [[Fear Ward]] on the runner can help.\r\n===Class-Specific Tricks===\r\n*General – The Wolf is immune to many, but not all (see below) slowing effects.\r\n*Rogues – [[Vanish]] prevents the Wolf from chasing you, but does not remove the debuff itself, so wait for it to run out before you come out of stealth.\r\n*Hunters – [[Feign Death]] works normally. Cast it when you get the Little Red Riding Hood debuff, and stay down until it wears off. In case of a resist, be prepared to get up again and run as fast as possible before the Wolf is too close. \r\n*Paladins – [[Blessing of Protection]] cast on Little Red Riding Hood will prevent the target from receiving any damage from the Wolf. Make sure to not use this buff too early to get the maximum benefit of this spell.\r\n*Mages – If you happen to have an arcane mage, [[Slow (Mage spell)]] is effective against the Big Bad Wolf (Confirmed 09/09/2008). [[Amplify Magic]] helps with healing as there is no magic damage during the fight.\r\n*Warriors – [[Thunderclap]] slows his damage output when chasing. You can [[Intervene]] to whomever receives the Riding Hood debuff to provide a bit of extra protection.\r\n*Druids with the [[Tree of Life Form]] should not use it or switch it off immediately if they receive the debuff, as it slows them even while under the effects of the Riding Hood debuff.\r\n==Quotes==\r\n* '''Combat start:''' In reply to dialog option \"What phat lewts you have grandmother\"? Grandmother turns into Big Bad Wolf and yells\r\n''\"All the better to own you with!\"''\r\n* '''Transforms:''' ''\"Run away little girl, run away!\"''\r\n* '''Killing A Player:''' ''\"Mmmm... delicious.\"''\r\n* '''Stagehand Barnes (prior to event starting):''' ''\"Good evening ladies and gentlemen, welcome to this evening's presentation! Tonight, things are not what they seem... for tonight your eyes may not be trusted! Take for instance this quiet elderly woman waiting for a visit from her granddaughter.... surely there is nothing to fear from this sweet, gray-haired old lady! But don't let me pull the wool over your eyes! See for yourself what lies beneath those covers! And now... on with the show!''\"\r\n===Databases===",},
			["The Big One"] = { content = "'''The Big One''' is probably the most cost effective grenade in the game (more powerful grenades, such as [[Thorium Grenade]] are extremely costly). It has enormous stun period, huge radius and good damage. \r\n==Source==\r\nThe Big One is crafted by [[Engineering|Engineers]] with a skill level of 235 who also have the Goblin Engineering specialty.\r\nThe components are:\r\n*6 [[Solid Dynamite]]s\r\n*1 [[Mithril Casing]]\r\n*1 [[Goblin Rocket Fuel]]\r\n*1 [[Unstable Trigger]]\r\nThe [[recipe]] for this item is taught by [[Engineering Trainer|Goblin Engineering trainers]].\r\n===[[Goblin Engineering]]===\r\n* [[Dimensional Ripper - Everlook]]\r\n==Notes==\r\nThe crafter will make two bombs at a time.",},
			["The Birth of the Lich King"] = { content = "'''\"The Birth of the Lich King\"''' is a section of the [[History of Warcraft]], Chapter IV. It is set immediately following the events of ''[[Warcraft II: Beyond the Dark Portal]]''.\r\nFound at:\r\n* Reliquary of [[Scholomance]] in the [[Western Plaguelands]]\r\n* [[Southshore]] Inn in the [[Hillsbrad Foothills]]\r\n* The Scarlet Bastion (live side) of [[Stratholme]]\r\nTimeline: \r\n* ← Previous book: [[The Invasion of Draenor]]\r\n* → Next book: [[Icecrown and the Frozen Throne]]",},
			["The Black Bride"] = { content = "'''The Black Bride''' is a level 61 [[Arathi Basin]] [[battlemaster]] located at [[Hammerfall]] in the [[contested]] territory of [[Arathi Highlands]].\r\nSee [[List of Arathi Highlands NPCs]].",},
			["The Black Morass"] = { content = "#REDIRECT [[Black Morass]]", redirect = "Black Morass",},
			["The Black Stalker"] = { content = "The '''Black Stalker''' is the final boss of [[The Underbog]] wing in [[Coilfang Reservoir]].\r\nThe Black Stalker is called \"Schattenmutter\" in the German client, which translates to Shadow Mother. Therefore it is assumed to be female. Also, the quest [[Quest:Stalk the Stalker|\"Stalk the Stalker\"]] refers to her as \"the great mother of the marsh walkers\".\r\n==Attacks and Abilities==\r\n*'''Static Charge''': This ability does 750 nature damage per second for 10 seconds and is not dispellable. This effect is similar to the Treacherous Aura placed on players by the Omor in ramparts. As long as the party spreads out you can minimize the damage that this debuff causes to the party as a whole and the healer can usually heal the debuffed player and the tank through it. (Vanity/noncombat pets should be dismissed before the fight, as she can place a static charge on them as well)\r\n*'''Chain Lightning''' This ability takes her three seconds to cast and hits the target for 2000. It then spreads to nearby players, with the damage falling by approximately half each time.\r\n*'''Levitate''': This effect brings a player in the air and when it wears off, a [[debuff]] will come on(Suspension)which lasts 20 seconds. However, it is dispellable. Players with ranged attacks can still attack the boss in mid air. Healers can be (but usually aren't) lifted high enough that the tank is out of range of heals.\r\n*'''Spore Strider Adds (Heroic only)''': Throughout the fight, the Black Stalker will spawn sets of three ~5000 HP adds every 10-15 seconds that will cast 1000 nature damage lightning bolts at targets. These adds are immune to fear.\r\n==Strategies==\r\nLike most other bosses in The Underbog, The Black Stalker does not have a lot of health, but hits hard. A good balanced group is advised, especially at lower levels. The chain lightning effect is similar to that of Venoxis in [[ZG]], so try to spread out to minimize this effect.\r\n'''Tank'''- Tank her in the center of the room with the rest of party at max range. Turn her either to the left or right, so melee can stand in her back to avoid the Chain Lightning, and be still in heal range.\r\n'''Healers'''- The Black Stalker hits hard. Keep the tank near full health. As mentioned above, the chain lightning effect can end up hitting the tank multiple times. This on top of the static charge effect can drop any where from a quarter to half of your tank's health. Try to stay at max healing range. You will also be trying to balance your time between healing and dispelling the levitate. It helps to have either a back up healer, or a back up \"cleanser\" (priest/paly) to worry about dispelling the levitate.\r\n'''Melee'''- Positioning yourself on the opposite site of the tank, you can avoid being hit by the Chain Lightning. Most important is keep an eye on the enemy cast bar. Chain lightning has a long casting time (approx 3 sec). There is time to run out of range during the Chain Lightning cast even if you are a bit laggy.\r\n===Levitate information===\r\n*[[Priests]], [[paladins]], or a warlock's [[felhunter]] can dispel this effect.\r\n*[[Mages]] can [[blink]] to escape.\r\n*Whilst traveling, only instant spells can be cast.\r\n*When fully levitated, all spells can be cast. \r\n*Healers will sometimes be out of range to heal some party members when fully levitated.\r\n*Ranged attackers will sometimes be out of range to hit the Black Stalker when fully levitated.\r\n*Standing under one of the small mushrooms near the walls can completely prevent the Levitation effect.\r\n*It is usually the second person on threat list that gets levitated. Some groups have tried a tactic where there is a second tank gaining threat to prevent healers and vulnerable cloth wearers from being affected.\r\n*Priests can try to use their ''Levitate'' spell and try to stay second on the threat list. The Levitate spell will keep them from taking fall damage and will only have to worry about dispelling the effect on themselves. \r\n*A suggested way to keep the healer from being levitated is to stand slightly around the corner out of sight from the Black Stalker, but still in line of sight of the party in order to heal.\r\n*After being dispelled/cleansed it is possible to be levitated again even before you hit the ground. This can happen 3 or 4 times in a row.\r\n*If the healer is levitated, it may be better to adjust everyone else within 40 yards of him/her, rather than dispelling it. Levitate by itself does no damage, and once the healer is levitated they are relatively safe from chain lightning, static charge, and melee attacks - while no other party members can be levitated until the effect ends. When the effect ends, priests can levitate, mages can Slow Fall, and druids can shift into cat form to avoid heavy fall damage.\r\n*As a Feral Druid you can trigger Feral charge as you start levitating, and it will bring you back to the boss and keep your aggro.\r\n===Heroic===\r\nSpawns several non-elite mobs with 5,000 health every 10 seconds which cast lightning bolts for about 600 - 800 nature damage. It is suggested you simply burn the boss as the adds despawn when the boss is downed.\r\nTanking the boss inside the alcove near the entrance to the Black Stalker's room will reduce the number of adds spawned during combat.\r\nIf healing is a problem, the adds can be killed by a single damage dealer at their spawn rate.\r\n'''Adds'''\r\nThe adds in heroic mode are the only things that seem to bring about a wipe on this boss. The spawn rate can sometimes seem like a lot faster than every 10 seconds and then in other encounters the adds hardly materialise at all. Generally there will be 3 or 4 adds at once and they can be burned very quickly with decent dps or ignored completely if they spawn towards the end of the encounter. Occasionally you will quickly seem surrounded by adds and have 8 or 9 in the room as well as the boss. This seems to be completely random. Their attacks generally do very limited damage on mail armour, between 500-750 damage every 3 or 4 seconds. As they only have around 5,000 health, they can be 2 or 3-shot killed by most dps at this level. When you have a room full of the adds it can become problematic as their attacks interrupt the casting time on abilities such as Aimed Shot and Steady Shot - this obviously makes burning them quickly more difficult. What would otherwise be an almost straight forward tank and spank encounter can quickly become a wipe. If the adds become overwhelming, run around the corner and reset the encounter - beware that unlike the Black Stalker, the adds will follow for a short distance beyond the reset point. (Netherstorm Pride [Sporeggar])\r\n===Resets and resurrecting group members===\r\nThis boss may be reset by running out of her room. While not in combat, she moves around the room, so be careful when trying to resurrect fallen comrades. If you do pull her while resurrecting, you can always run out to reset her and try again. It is also possible for the boss to reset in the middle of a fight unintentionally, restoring the boss to full health and dropping the threat list. This usually happens when all DPS is ranged and stands near the entrance to the room, and the tank gets levitated out of range. When this happens it is best to have the whole group run out of range, re-buff and get mana to full before trying again. \r\n==Quests==\r\n*Stalk the Stalker",},
			["The Black Temple"] = { content = "#redirect [[Black Temple]]", redirect = "Black Temple",},
			["The Black Vault"] = { content = "#REDIRECT [[Black Vault]]", redirect = "Black Vault",},
			["The Bloodcursed Reef"] = { content = "#redirect [[Bloodcursed Reef]]", redirect = "Bloodcursed Reef",},
			["The Bloodoath"] = { content = "'''The ''Bloodoath''''' is one of three [[blood elf]] [[destroyer]]s, in the waters north of the [[Sun's Reach Harbor]], [[Isle of Quel'Danas]]. She is the northwesternmost ship of the fleet. \r\nThis ship is one of three containing [[Dawnblade (blood elves)|Dawnblade]] blood elves, as reinforcements for Kael's forces on the Isle of Quel'Danas.\r\nAfter having set the sails ablaze, this ship is no longer able to continue to its destination.",},
			["The Bloodwash"] = { content = "#REDIRECT [[Bloodwash]]", redirect = "Bloodwash",},
			["The Blood Furnace"] = { content = "#REDIRECT [[Blood Furnace]]", redirect = "Blood Furnace",},
			["The Blue Recluse"] = { content = "#REDIRECT [[Blue Recluse]]", redirect = "Blue Recluse",},
			["The Bone Wastes"] = { content = "#REDIRECT [[Bone Wastes]]", redirect = "Bone Wastes",},
			["The Book of Ur"] = { content = "''The Book of Ur'' is a book written by the [[mage]] [[Ur]] of [[Dalaran]]. It came later into the hands of [[Archmage Arugal]] and is available as an in-game [[book]].\r\n==Objective of==\r\n*This item is required for the quest The Book of Ur.\r\n==As an object==\r\n'''The Book of Ur''' is located in [[Shadowfang Keep]] in [[Silverpine Forest]].\r\n==Contains==",},
			["The Borderlands"] = { content = "#REDIRECT [[Borderlands]]", redirect = "Borderlands",},
			["The Botanica"] = { content = "#REDIRECT [[Botanica]]", redirect = "Botanica",},
			["The Bough of the Eternals"] = { content = "==Objectives==\r\nTake the orphan to the bank of [[Darnassus]]. The bank itself is hollowed out of a tree known as the Bough of the [[Eternals]].\r\n*Go to the bank in Darnassus, otherwise known as the Bough of the Eternals.\r\n==Description==\r\nI've heard stories about how the night elves have their bank in a tree - one that looks like a bear! That's so cool! Night elves are neat how they like nature and stuff, but bears are just totally awesome!\r\nWould you take me to see the bear-tree in Darnassus, please? There's a boat that will take us close to there, and it shouldn't take very long. Please, please, please!\r\n==Completion == \r\nWow, it was cooler than I even imagined - the Bough of the Eternals! I didn't think it'd be so big, but it was! Did you see the bird on top of it too?! I wonder how they got the branches to look like that!\r\nThanks for taking me to Darnassus, <name>. You're awesome!\r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*650 [[XP]] (or 3 silver 90 copper at level 70)\r\n*75 [[reputation]] with [[Darnassus]]\r\n*75 reputation with [[Exodar]]\r\n*75 reputation with [[Gnomeregan Exiles]]\r\n*75 reputation with [[Ironforge]]\r\n*75 reputation with [[Stormwind]]\r\n==Quest Chain==\r\n*Children's Week (Alliance)\r\n**Spooky Lighthouse\r\n**The Stonewrought Dam\r\n**The Bough of the Eternals\r\n**You Scream, I Scream...\r\n**Jaina's Autograph\r\n***A Warden of the Alliance",},
			["The Bravery"] = { content = "'''''The Bravery''''' is a Alliance crewed [[boat|vessel]] that allows transportation between [[Stormwind Harbor]] and [[Auberdine]].\r\n==Crew==\r\n* [[Captain Angelina Soluna]]\r\n* [[First Mate Wavesinger]]\r\n* [[Navigator Landerson]]\r\n* [[Engineer Brightbuckle]]\r\n* [[Galley Chief Gathers]]\r\n* [[Sailor Fairfolk]]\r\n* [[Sailor Stoneheel]]\r\n* [[Sailor Wills]]\r\n* [[Sentinel Brightgrass]]\r\n* [[Sentinel Winterdew]]",},
			["The Broken"] = { content = "#redirect [[Broken draenei]]", redirect = "Broken draenei",},
			["The Broken Hall"] = { content = "#REDIRECT [[Broken Hall]]", redirect = "Broken Hall",},
			["The Bulwark"] = { content = "#REDIRECT [[Bulwark]]", redirect = "Bulwark",},
			["The Burning Crusade"] = { content = "#REDIRECT [[World of Warcraft: The Burning Crusade]]", redirect = "World of Warcraft: The Burning Crusade",},
			["The Burning Crusade: Guild Progression"] = { content = "#REDIRECT [[Guild progression (TBC)]]", redirect = "Guild progression (TBC)",},
			["The Burning Legion Returns"] = { content = "A narrator discusses how survivors of the Third War never truly believed that the war had put an end to the Burning Legion. Just that Kil'jaeden was cut off from Azeroth but not indefinitely. Yet with the threat of war between Horde and Alliance, and continuing danger of the scourge, they could not prepare for a war that could happen millenia in the future, when danger was already happening around them.\r\nWith the portal newly opened, people had to reevaluate their priorities. Draenor had not been destroyed, but had become outland, where Illidan Stormrage is fighting to solidify his power base. Many of the loved ones they had thought perished with Draenor were still alive. Tracts of land were left untouched by fel magic or Ner'zhul's reckless sorcery. Recently, horde and alliance have gained new allies in the blood elves and draenei.\r\nWith the reactivation of the portal, it has become a double-edged sword. Illidan and his forces are fighting to keep all the other portals in Outland closed, but his loyalties remain in question. Should even one of the portals open, the forces of the Legion would invade Outland. Their inevitable triumph over Illidan would set off a chain reaction, with countless more worlds falling to the legion, Azeroth would have little hope.\r\nTo prevent such a scenario, the people of Azeroth have sent out scouts to bring back information from outland. They now understand the current layout and disposition of the enemies in Outland. They have compiled maps, bestiaries, and strategies. Knowledge that is key to the conquest of Outland. \r\nUnfortunately tensions between Horde and Alliance remain, and they cannot be set aside lightly. The narrator thinks of the lives lost and grieves bitterly. He wishes to kill, but cannot afford to be blinded by bloodlust. He remembers that it was the Burning Legion that first set his people at one another's throats. He cannot permit the burning crusade to engulf other worlds. He must bring the war to an end, and find a way.",},
			["The Butcher"] = { content = "'''The Butcher''' is the second boss of [[Highmaul]] in .\r\n===Adventure Guide===\r\n''Born in the fetid Underbelly of Highmaul, this ogre may have once had a proper name, but it is long forgotten. Abused and beaten from his earliest days, the hardship only strengthened his body even as it broke his mind. Now there is not an ogre in Highmaul who will not give him a wide berth as he hacks away at slaughtered carcasses to pass his days.''\r\n==Overview==\r\nThe Butcher attacks relentlessly, hacking at his foes with his dual implements of destruction. His main abilities seek to target large clumps of enemies, and positioning is key to handling and overcoming his attacks.\r\n=== Damage Dealers===\r\n*Players in melee range must form clumps of varying sizes throughout the fight to manage the Butcher's '''Cleave''' and allow '''Gushing Wounds''' to fade.\r\n*Players at range must clump in order to survive the Butcher's '''Bounding Cleave''' sequence.\r\n=== Healers===\r\n*Groups that are struck by '''Cleave''' suffer periodic damage from '''Gushing Wounds''', which can stack.\r\n*All players in the raid suffer Physical damage when the Butcher begins his '''Bounding Cleave''' sequence.\r\n=== Tanks===\r\n*'''Heavy Handed''' causes the Butcher to attack the player closest to his current target with a copy of all of his melee attacks. These attacks can be mitigated and avoided as usual. If another player is not close enough, the second attack will trigger on the primary target.\r\n*'''The Tenderizer''' will always hit. It cannot be dodged or parried, but it can be blocked.\r\n*'''The Cleaver''' will only apply its damage over time effect if the attack successfully lands on its target.\r\n===The Butcher===\r\n*\r\n*\r\n*\r\n*\r\n======\r\nIn Mythic Difficulty, Night-Twisted Cadavers will spawn and walk towards The Butcher in a final, vain attempt to slay him. When the Cadaver reaches The Butcher or when they walk near a player, they will Explode, leaving a pool of Pale Vitriol behind for the duration of the encounter.\r\n*\r\n==Strategy==\r\nThe Butcher encounter is a very simple single-phase fight that is frequently compared with [[Patchwerk]]; it has very few mechanics and the main challenge of the encounter is an extremely tight [[enrage (mechanic)|enrage]] timer necessitating very high DPS from all members of the raid.\r\n====Preparation / Managing Cleave====\r\nPrior to the pull, the raid leader will generally assign three groups, two of which will stack separately in melee range to soak Cleave, the third will stack at range to bait in Bounding Cleave and the fourth will contain the two tanks.\r\nThe only major mechanic of the fight to be managed by the DPS is Cleave which applies the debuff Gushing Wounds. If any member of the raid reaches five stacks of this debuff they will instantly die. The normal strategy for the fight is to have two groups assigned to stack in melee, which will stack on the boss's backside behind each of his feet, one group on the side of the left foot and the other on the side of the right foot.\r\nCleave hits the largest clump of players near him so these groups must contain at least 3 players to ensure Cleave will not inadvertently hit the tanks. In order to control the flow of stacks onto the raid and ensure stacks will fall off, the raid leader must assign two \"trigger\" characters, one for each group, that will move in and out of their respective stack points to force the boss to either target their group or target the other group. For example, if Group 1's trigger is John and Group 2's trigger is Mary, when it's Group 1's turn to soak Cleave John will stack with his group and Mary will move out of her group, causing the Butcher to hit Group 1 with all of the Cleaves, then when it is Group 2's turn to soak Cleave John will move out of his group and Mary will move into hers, forcing the Butcher to use Cleave on Group 2 instead. Prior to the Frenzy, the groups should be alternating at 2 stacks, but after the Frenzy the Butcher's increased attack speed will require alternating on 3 stacks.\r\n[[Hunter]]s are particularly desired for their ability to act as triggers as moving into and out of their group is generally not a DPS loss, though other mobile ranged DPS or healers can be used as well if qualified hunters are not available. Melee DPS can act as triggers if the groups are far enough apart that it creates a gap that the trigger can move into without having to stop attacking the boss.\r\n====Ranged DPS / Healers====\r\nAny ranged DPS or healers not assigned to a melee group to soak cleave should stack up at a designated point far away from the boss to bait in Bounding Cleave. When he knocks the whole raid away, they should quickly move back to their stack point to ensure they get hit.\r\nHealers should have their strongest healing cooldowns for when the Butcher hits 30% and begins to Frenzy. This is also the point that the group should generally use [[Heroism]], [[Bloodlust]] or similar abilities.\r\n====Tanking====\r\nThe Butcher has three tank mechanics in addition to his fairly powerful melee attack. Heavy Handed will copy his attacks onto the nearest target within 5 yards of his primary aggro target; if there is no other target within 5 yards of his current tank he will instead hit the tank twice. This necessitates the two tanks stacking on top of each other for the entire fight, but also not with any of the melee DPS as Heavy Handed can hit a non-tank as well which will probably cause a death.\r\nHis second tank mechanic is the Cleaver, which applies a stacking DoT on the tank. While this ability will simply need to be healed through for some tanks, avoidance-oriented tanks like [[Monk abilities|Brewmaster]] [[Monk]]s and [[Druid abilities|Guardian]] [[Druid]]s should use their avoidance cooldowns (e.g. [[Elusive Brew]], [[Savage Defense]]) to attempt to dodge this ability, as it can be avoided and if avoided it does not apply its DoT.\r\nHis third tank mechanic is the Tenderizer, a single-target nuke which applies a debuff that increases damage of successive Tenderizers. The tanks should swap at 2 stacks of this ability and have a cooldown ready for reducing the damage of the second one.\r\nWhile not a tank mechanic per se, the Butcher's Frenzy is very remniscent of [[Patchwerk]] and the boss will start doing increased damage and start attacking quite a bit faster, so having major defensive cooldowns ready for the 30% mark is essential for surviving the last minute of the fight.\r\n==Related Achievements==\r\n*[[The Walled City]]\r\n*[[Highmaul Guild Run]]\r\n*[[Mythic: The Butcher]]\r\n*[[Hurry Up, Maggot!]]\r\n==Quotes==\r\nIntro\r\nAggro\r\nBounding Cleave\r\nFrenzy\r\nCleave\r\nBerserk\r\nKilling a player\r\n*\r\nWipe\r\nDeath\r\nUnused quotes\r\n*Lanky gave me a little runs!\r\n*Get off! You ain't worth eating!\r\n*Smash!\r\n==Objective of==\r\n*[[Highmaul Raid]]",},
			["The Butchery"] = { content = "'''The Butchery''' is located inside [[the Temple of Atal'Hakkar]]. It is where those captives who were unworthy of sacrifice were unceremoniously killed, their meat fed to the [[Atal'ai]]'s [[serpent]] pets. The Butchery is a dead-end room connected to the [[Hall of Masks]], the [[Den of the Caller]], and the [[Chamber of Blood]] via narrow passages.",},
			["The Cape of Stranglethorn"] = { content = "#REDIRECT [[Cape of Stranglethorn]]", redirect = "Cape of Stranglethorn",},
			["The Captain"] = { content = "#REDIRECT [[Falric]]", redirect = "Falric",},
			["The Caverns of Time"] = { content = "==Objectives==\r\nAndormu at the Caverns of Time has asked that you follow the Custodian of Time around the cavern.\r\n* Caverns of Time Explained\r\n==Description==\r\nGreetings, <name>. Please follow the custodian. She will make things a bit more... clear.\r\n==Rewards==\r\nUpon completion of this quest you will gain:\r\n* 1200 experience (or a s=72 gold compensation at level 70)\r\n* 250 reputation with [[Keepers of Time]]\r\n==Completion==\r\nHopefully you now have a better understanding of what is expected of you.",},
			["The centaur"] = { content = "'''The centaur''' was said to be the cursed bastard son of [[Cenarius]]. His brother was known as the \"the [[keeper of the grove]]\" (perhaps [[Zaetar]]) and his sister \"the [[dryad]]\". He grew to despise his siblings, and then all other creatures of the world, and challenged his father. He believed he was the strongest of the three children. He believed that his father didn't love him, and doted on his siblings. He embraced hatred and savagery and struck his father in blind rage, trying to force his father to love him more than all other creatures. Cenarius then cursed his son, stripping him of his beauty and powers, leaving him only with his hatred and anger. The centaur fled in rage and swore a blood feud on all the creatures of the world. His [[centaur|children]] carry his anger, and are destructive. They hate the tauren, and like their father, hate all of creatures of the world.\r\n==Children==\r\nHe is believed to be the father of at least the [[Krenka]] tribe. He may have also fathered the centaur in the eastern kingdoms, and possibly the [[Centaur Marauders]] and [[Stonetalon centaurs]]. Cenarius' son [[Zaetar]] is believed to be the father of five tribes (Kolkar, Magram, Mauradine, Gelkis, and Galak), although some of \"the centaur's\" offspring may have integrated into those tribes.",},
			["The Champion of the Horde"] = { content = "==Objectives (Pre-Burning Crusade)==\r\n''Seek out [[Rexxar]]. The Warchief has instructed you as to his whereabouts. Search the paths of [[Desolace]], between the [[Stonetalon Mountains]] and [[Feralas]].''\r\n==Objectives (Burning Crusade)==\r\n''Seek out [[Rokaro]] at [[Shadowprey Village]] in [[Desolace]].''\r\n==Details (Pre-Burning Crusade)==\r\nRexxar wanders the road from [[Feralas]] to [[Stonetalon Peak]], except he cuts north from the area with the demons and goes through the [[Kodo Graveyard]], before taking the road north out of there (or south into there). He also wanders slightly into Stonetalon Peak and Feralas (as far as [[The Twin Colossals]] in Feralas) so if you're having no luck finding him, search a little into both zones.\r\n==Details (Burning Crusade)==\r\nRexxar was moved from his patrol area to the [[Thunderlord Stronghold]] in the [[Blade's Edge Mountains]] of northern [[Outland]]. He has been replaced by an orc named [[Rokaro]], who resides at [[Shadowprey Village]]. He does not patrol as Rexxar did, and thus is easy to find.\r\n==Description (Pre-Burning Crusade)==\r\n''I have received word from one of my champions that a way into the lair of the dragon may exist. You are to seek him out.''\r\n''Rexxar wanders the desert wasteland of Desolace, traveling between Stonetalon and Feralas. He awaits your arrival.''\r\n==Description (Burning Crusade)==\r\n''Rexxar, one of my most loyal champions, has discovered a way into the lair of the dragon. However he has left Azeroth to join our expedition into Outland.''\r\n''However, he left his companion, Rokaro, in Shadowprey Village with this information. You are to seek him out.''\r\n==Progress==\r\nKeep at it, <name>.\r\n==Completion (Pre-Burning Crusade)==\r\nThere is but one way into the dragon's lair, <race>.\r\nYou see, only the strongest of the Black Dragonflight are allowed entry into the lair of the brood mother. Many trials must be passed and the key to enter ceremoniously enchanted by General Drakkisath himself!\r\nSince you are not of black dragonkin, you may have some difficulty in obtaining passage.\r\n<Rexxar grins.>\r\n==Completion (Post-Burning Crusade)==\r\nThere's only one way you'll be getting into the dragon's lair. Unless, of course, you happen to be an honored member of the Black Dragonflight.\r\nEven then, you'd have to pass many trials and then have the key enchanted by General Drakkisath himself.\r\nBut aren't you lucky? That's where I come in.\r\n==Quest Progression==\r\nThis quest is part of the quest line to obtain the [[Drakefire Amulet]], the key to [[Onyxia's Lair]].\r\n# Warlord's Command\r\n# Eitrigg's Wisdom\r\n# For The Horde!\r\n# What the Wind Carries\r\n# '''The Champion of the Horde'''\r\n# The Testament of Rexxar / Mistress of Deception\r\n# Oculus Illusions\r\n# Emberstrife\r\n# The Test of Skulls, Scryer\r\n# The Test of Skulls, Somnus\r\n# The Test of Skulls, Chronalis\r\n# The Test of Skulls, Axtroz\r\n# Ascension...\r\n# Blood of the Black Dragon Champion",},
			["The Charred Oak"] = { content = "'''The Charred Oak''' is located in [[Searing Gorge]]. \r\n==Objective of==\r\nContains Bundle of Charred Oak for the quest Sweet Amber.",},
			["The Charred Vale"] = { content = "#REDIRECT [[Charred Vale]]", redirect = "Charred Vale",},
			["The Cipher of Damnation"] = { content = "==Source==\r\nThis item is provided for The Cipher of Damnation.\r\n==The Cipher of Damnation as a quest objective==\r\nThis item is an objective of The Cipher of Damnation.",},
			["The Circle of Blood"] = { content = "#redirect [[Circle of Blood]]", redirect = "Circle of Blood",},
			["The Cleft"] = { content = "#REDIRECT [[Cleft]]", redirect = "Cleft",},
			["The Cleft of Shadow"] = { content = "#redirect [[Cleft of Shadow]]", redirect = "Cleft of Shadow",},
			["The Cloudkisser"] = { content = "'''The ''Cloudkisser''''' is a [[zeppelin]] that runs from a second [[zeppelin tower]] in [[Tirisfal Glades]] to [[Vengeance Landing]] in [[Howling Fjord]]. It has a new, somewhat more compact design when compared to the routes between the Eastern Kingdoms and Kalimdor. It will be added in ''[[World of Warcraft: Wrath of the Lich King]]''.\r\n==Crew==\r\n* [[Sky-Captain Cryaflight]]\r\n* [[Deathguard Barth]]\r\n* [[Deathguard Hicks]]\r\n* [[Crewman Coilspan]]",},
			["The Codex of Blood"] = { content = "The [[Shadow Council]] within the [[Shadow Labyrinth]] of [[Auchindoun]] uses a forbidden book of unholy summoning, known only as the '''Codex of Blood'''.\r\nThe musty pages of the codex seem to magically turn themselves, guiding attention to a specific chapter past horrors no mortal eyes should ever perceive.",},
			["The Commons"] = { content = "#REDIRECT [[Commons]]", redirect = "Commons",},
			["The Consortium"] = { content = "#REDIRECT [[Consortium]]", redirect = "Consortium",},
			["The Consortium Needs You!"] = { content = "==Objectives==\r\nReport to Gezhe at Aeris Landing in Nagrand.\r\n==Description==\r\nMy organization, the Consortium, is looking for a few resourceful individuals just like yourself. You'll be hard pressed to find ethereals more honest, hard-working or pleasant to be around than us.\r\nAll we require is loyalty, dedication and a reasonable amount of moral flexibility. If you're interested, speak to Gezhe, our ground operations leader. You will find him at Aeris Landing, north of Oshu'gun.\r\n==Completion==\r\nAre you ready to get to work, <race>? I think I've got the perfect task for you.",},
			["The Creeping Ruin"] = { content = "#REDIRECT [[Creeping Ruin]]", redirect = "Creeping Ruin",},
			["The Crimson Reach"] = { content = "#redirect [[Crimson Reach]]", redirect = "Crimson Reach",},
			["The Crimson Throne"] = { content = "#redirect [[Crimson Throne]]", redirect = "Crimson Throne",},
			["The Crimson Veil"] = { content = "The '''''Crimson Veil''''' is the middle of the three [[Bloodsail Buccaneers]] [[boat|ships]] docked at the [[Wild Shore]] islands in [[Stranglethorn Vale]].\r\n===Crew===\r\n* [[Fleet Master Firallon]]\r\n* [[Ironpatch]]",},
			["The Crone"] = { content = "'''The Crone''' is a [[troll]] boss in the Opera House in [[Karazhan]], who follows [[Dorothee]], [[Roar]], [[Strawman]], [[Tinhead]], and Dorothee's pet [[Tito]]. \r\n''She is a direct homage to the [[wikipedia:Wicked Witch of the West|Wicked Witch of the West]].'' Challe, in charge of Challe's Home for little Tykes, has the same model as her (not the same clothes though) and might also be a Wicked Witch.\r\n==Abilities==\r\nCyclone - Knocks the player up into the air. Take fall damage.\r\nChain Lightning - 45 yd range, 2 sec cast, Strikes an enemy with a lightning bolt that arcs to another nearby enemy. The spell affects up to 5 targets, inflicting greater Nature damage to each successive target. 2775-3225 damage.\r\n==Quotes==\r\nEnter:'Woe to each and every one of you my pretties! <cackles>'\r\n'It will all be over soon! <cackles>'\r\nKill:'Fixed you, didn't I? <cackles>'\r\nDeath: 'How could you? What a cruel, cruel world!'\r\n==Loot==\r\nThe Crone is the only loot source for the Wizard of Oz event.",},
			["The Crone of the Kraul"] = { content = "==Objectives==\r\nBring [[Razorflank's Medallion]] to [[Falfindel Waywarder]] in [[Thalanaar]].\r\n==Description==\r\n''Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was.''\r\n''We must not let their valiance go for naught. This crone... Charlga Razorflank ... must be stopped.''\r\n''Surely, infiltrating the Kraul will be perilous. There isn't time to send word to Darnassus. <name>, assemble a party to slay the crone.''\r\n''Bring me Razorflank's Medallion as proof of demise.''\r\n==Reward==\r\nYou will be allowed to choose one of the following:\r\n*Berylline Pads\r\n*Stonefist Girdle\r\n*Marbled Buckler\r\nYou will also receive:\r\n*Falfindel's Blaster\r\n==Progress==\r\n''So long as Charlga Razorflank is mustering a force in Razorfen Kraul, these lands are in great danger.''\r\n==Completion==\r\n''The crone has been laid to rest. This is fantastic news, <name>.''\r\n''In these times of peril, it is refreshing to see one as brave as yourself.''\r\n''With Razorflank's minions taken care of, our studies in the area can continue. Perhaps now we can gain further knowledge of exactly what happened to corrupt the resting place of Agamaggan.''\r\n''However, I fear the answer to that question lies in treachery as well...\r\nRewards''\r\n==Quest progression==\r\n* Lonebrow's Journal\r\n** The Crone of the Kraul",},
			["The Crossroads"] = { content = "#REDIRECT [[Crossroads]]", redirect = "Crossroads",},
			["The Crumbling Waste"] = { content = "#redirect [[Crumbling Waste]]", redirect = "Crumbling Waste",},
			["The Cryo-Core"] = { content = "#REDIRECT [[Cryo-Core]]", redirect = "Cryo-Core",},
			["The Crypts"] = { content = "#redirect [[Auchenai Crypts]]", redirect = "Auchenai Crypts",},
			["The Crystal Hall"] = { content = "#REDIRECT [[Crystal Hall]]", redirect = "Crystal Hall",},
			["The Crystal Shore"] = { content = "#REDIRECT [[Crystal Shore]]", redirect = "Crystal Shore",},
			["The Crystal Vale"] = { content = "#REDIRECT [[Crystal Vale]]", redirect = "Crystal Vale",},
			["The Cult of the Damned (WC3 Human)"] = { content = "((battle\r\n*[[Jaina Proudmoore]]\r\n*1 [[Archmage]]\r\n*[[Footmen]]\r\n*[[Rifleman]] (Riflemen)\r\n*[[Mortar Team]]s\r\n*[[Priest]]s\r\n*[[Ghoul]]s\r\n*[[Kel'Thuzad]]\r\nChapter 4 of the [[Warcraft III: Reign of Chaos|Warcraft III]] human campaign, [[The Scourge of Lordaeron]].",},
			["The Curator"] = { content = "'''The Curator''' is an [[Arcane Guardian]] boss in the Menagerie in [[Karazhan]]. It is not optional, raids wanting to kill the bosses behind it must first defeat The Curator. The encounter is not difficult to learn, but is (for new raids) a rather hard [[gear check]]. A raid able to defeat this boss is in principle equipped well enough to clear the whole instance, save perhaps [[Nightbane (boss)|Nightbane]] and [[Prince Malchezaar]].\r\n===The Curator===\r\n*'''Basic Melee''': Around 3000 on a tank\r\n*'''Summon Astral Flare''':Summon one [[Astral Flare]] every 10 seconds (Flare Phase)\r\n*'''Hateful Bolt''': An arcane bolt that hits a non-tank character for 4435-5999 Arcane damage.\r\n*'''Evocation''': Go completely inactive for 20 seconds while re-filling mana and increasing damage taken by 200% (Evocation Phase)\r\n*'''Soft Enrage''': At 15% health, increase melee attack speed and Hateful Bolt cast rate while ceasing new Evocations or Astral Flare summons\r\n*'''Hard Enrage''': Standard [[enrage (boss)|hard enrage]] after 10 minutes\r\n*Immune to [[arcane]], [[poison]] and mana drain spells and effects.\r\n===Astral Flare===\r\n*'''Health''': 17,000HP\r\n*Melee: none\r\n*Arcing Sear: Rapid-fire chained attack which hits up to three targets within ten yards for 675-825 arcane damage each\r\n*Immune to taunts, stuns, roots, and snares\r\n==Strategy==\r\nFor new raids first entering Karazahn, the Curator is rather hard to kill. It's not a coincidence that this boss drops the first class set tokens - they really want to be earned. There's not much strategy or room for fancy maneuvers - either the raid has the required DPS and the necessary mana endurance, or it does not.\r\nMost of the fight consists of two alternating phases: a 90 second Flare Phase followed by a 20 second Evocation Phase. Once the Curator's health drops below 15% it does a soft enrage, stops summoning Flares and Evocating, but instead increases melee attack speed and Hateful Bolt frequence. 10 minutes after the pull the Curator does a hard enrage and wipes the raid very quickly.\r\n===Flare phase===\r\nDuring the Flare Phase, The Curator summons ten Astral Flares, hits the tank with moderate melee damage, and casts Hateful Bolts.\r\nThe Curator summons one Astral Flare every 10 seconds, at a cost of 10% of its mana. Each Flare spawns with about 1000 threat from a random, non-tank player character and advances in that character's direction while hitting nearby enemies with Arcing Sear.\r\nEach Flare ''must'' be destroyed within 10 seconds, before the next one spawns. Failure to do so results in multiple Flares dealing damage at the same time - this situation usually means a wipe. It is not necessary to damage the Curator at all during this phase. Damaging the Curator ''is'' permissible, but only when no Flares are up (unless the raid has excess DPS: see Positioning below).\r\nThis cannot be over-emphasized: ''By far, the most important part of the fight is killing the Astral Flares as quickly as possible.'' Wipes usually happen because the healers run out of mana. They run out of mana because the Flares live too long. The solution is almost always to kill the Flares faster. The faster each Flare dies, the easier the healers' job becomes.\r\nWhile it is not necessary to tank the Flares, doing so gets them to hold still and makes them easier to kill. A hunter pet with attack power buffs and specced for arcane resistance and stamina is ideal for this task. Warriors, bear druids, paladins, and enhancement shamans can do the job, too. A decently-geared retribution paladin can rather easily hold the flares in place with [[Righteous Fury]] and burst Holy damage threat.\r\nThe Curator casts a Hateful Bolt every 10 to 15 seconds. The current best theory is that the Hateful Bolt hits the non-tank character that has generated the most threat on The Curator since the last Evocation and currently has enough health to survive the damage from the Bolt.\r\nIt is possible to assign one character - preferably a warlock or a shadow priest - as Hateful Bolt soaker. This character attracts most of the Hateful Bolts by steadily damaging The Curator. Equipping the soaker with arcane resistance gear negates a substantial amount of the damage from the Hateful Bolts. Note that using a soaker is reasonable only when the raid is still able to kill the Flares fast enough. It's typically done when using only two healers.\r\n===Evocation phase===\r\nImmediately after The Curator summons the tenth Astral Flare with the last of its mana, it enters a state of Evocation for 20 seconds while it refills its mana. While it does so, it goes completely inactive and all damage dealt against it is tripled.\r\nMost raids must first concentrate on killing the tenth and last Flare before switching damage over to the Curator. Otherwise, there may be two Flares up after the Evocation, which is bad (see above). Killing the Flare quickly also grants the healers a few seconds break for mana regeneration. Overgeared raids can attack The Curator immediately to speed up the fight, and clean up the extra Flares after Evocation.\r\nCooldown and single-use abilities that temporarily increase damage output should be saved up for this moment and be activated at the beginning of the phase to quickly kill the last Astral Flare and to make the most out of the Curator's temporary vulnerability.\r\nOnce the Curator has finished refilling mana, the fight continues with the next Flare Phase.\r\n===Enrage phase===\r\nWhen The Curator's health drops below 15%, it immediately switches to the Enrage Phase. It stops summoning Astral Flares, ceases Evocations, and increases melee damage output and Hateful Bolt frequency. This means that the healers have to give the main tank and Hateful Bolt victims more attention while everyone else just nukes The Curator. This phase is actually the easiest part of the fight.\r\n==Positioning==\r\nPositioning is a secondary concern, but it can help raids with marginal gear. A concentrated setup increases damage on the Flares by eliminating the need for melee damage-dealers to chase down Flares. A distributed setup reduces damage from the Flares by reducing the chaining of Arcing Sear.\r\n===Concentrated===\r\nIf melee damage dealers are needed on the Flares, everybody except the hunters sets up close together, with the hunters as close as possible, just at their minimum range. The main tank is on one side of The Curator, and everybody else is on top of each other on its back (within melee range). This makes it easy for the melee characters to damage the Flares and quickly switch to The Curator when no Flares are up. The drawback of this method is that the Flare damage is maximized. This is offset to some extent because multi-target heal spells like [[Chain Heal]] also have their maximum effect. More importantly, the Flares die more quickly in this formation, so they have less time to do damage.\r\n===Distributed===\r\nIf the raid's ranged DPS is high enough to kill the Flares quickly (in less than eight seconds) without support from the melee characters, the melee group sets up close to The Curator and stays put. The ranged damage dealers and healers spread out and each stays at least ten yards away from everybody else. This significantly reduces Flare damage, because Arcing Sear doesn't jump farther than ten yards. Also, the melee group is on the Curator all the time, which shortens the fight.\r\nIf melee characters have to help killing Flares, the distributed setup does not work well. Even a single melee damage dealer chasing Flares breaks the ten yard pattern, and thus the Flare damage is maximized anyways. Worse, that melee character loses a lot of damage output while running around. Because of this, a concentrated setup is best for most raids new to this encounter.\r\n==Miscellaneous Tips==\r\n* For most problems on The Curator, the solution is to kill the Flares faster. If that doesn't work, the best solution is usually to come back later with better gear, better specs, and more [[consumables]]. Underpowered raids simply cannot win this fight.\r\n* Mana is an issue in this fight. Make sure everyone has enough mana potions and mana regeneration [[consumable]]s.\r\n* Threat is not an issue in this fight. Use buffs or totems that facilitate quick Flare-killing. Don't use buffs like Salvation that reduce threat.\r\n* Multi-target heals are very effective, especially [[Chain Heal]] and [[Prayer of Mending]]. [[Circle of Healing]] can be good too, but requires very good priest gear to be really efficient.\r\n* The following simple macro is handy to help damage-dealers target live Astral Flares quickly:\r\n<pre>/cleartarget&#x000D;/target Astral Flare&#x000D;/stopmacro [nodead, harm]&#x000D;/target The Curator</pre>\r\n* While it's tempting to use arcane [[resistance]] gear, it slows down Flare-killing. It's somewhat useful on the tank, any Hateful Bolt soaker, and any Flare tank, but generally harmful on other characters.\r\n* Flares spawn to the left or right of The Curator in a pattern. Learn the pattern to pick them up faster.\r\n* When The Curator starts evocating, some DPS meter chasers are tempted to cheat by attacking The Curator before the last Flare is dead. This leads to wipes in marginal raids. Watch out for cheaters and stop them. On well-geared raids though this is actually useful.\r\n* The fight can be reset by running down the last stairs before the room.\r\n* Astral Flares do not live long enough for damage-over-time spells to be effective. Warlocks can use [[Searing Pain]] or [[Shadow Bolt]] instead.\r\n* If there are multiple hunters, they should spread out from each other. This avoids more than one being forced into melee combat when an Astral Flare comes their way. [[Feign death]] and (manually cast) Growl can keep the Flares at range.\r\n* A [[Cauldron of Major Arcane Protection]] gives the healers a break.\r\n* Warlocks can cast [[Curse of Doom]] on the Curator somewhere between the summoning of the fourth and sixth Astral Flares. It's best to time it such that it goes off right at the start of the Evocation, so that it can be replaced by [[Curse of the Elements]] or [[Curse of Recklessness]] when the rest of the raid starts to deal damage.\r\n* Priests should use their [[Shadowfiend]] during an Evocation phase. While dealing triple damage, the Shadowfiend can refill your whole mana bar.\r\n* Shamans should use their [[Bloodlust]] or [[Heroism]] during the eighth Flare.\r\n* If The Curator is mistakenly pulled while other players are elsewhere in the dungeon (i.e.: repairing in Midnights room), those player may be teleported up into The Menagerie. This causes certain death if the players cannot get to the stairs to reset the Curator.\r\n==Quotes==\r\nAggro\r\nThe Menagerie is for guests only.\r\nAdds Spawn\r\nThis curator is equipped for gallery protection.\r\nGallery rules will be strictly enforced.\r\nEvocate\r\nYour request cannot be processed.\r\nEnrage\r\nFailure to comply will result in offensive action.\r\nPlayer death\r\nYou are not a guest.\r\nDo not touch the displays.\r\nDeath\r\nCurator is no longer op... er... ation... al.\r\n==Loot==",},
			["The Dagger Hills"] = { content = "#REDIRECT [[Dagger Hills]]", redirect = "Dagger Hills",},
			["The Damsel's Luck"] = { content = "The '''''Damsel's Luck''''' is the easternmost of the three [[Bloodsail Buccaneers]] [[boat|ships]] docked at the [[Wild Shore]] islands in [[Stranglethorn Vale]].\r\n===Crew===\r\n* [[Captain Stillwater]]\r\n* [[Brutus]]",},
			["The Darkened Bank"] = { content = "#REDIRECT [[Darkened Bank]]", redirect = "Darkened Bank",},
			["The Darkmoon Faire"] = { content = "Were you looking for:\r\n* The Darkmoon Faire (Horde)\r\n* The Darkmoon Faire (Alliance)",},
			["The Darkstone Tablet"] = { content = "'''The Darkstone Tablet''' contains the secret recipes of a brilliant dwarf alchemist.\r\n==Objectives==\r\nBring the [[Darkstone Tablet]] to [[Shadowmage Vivian Lagrave]] in [[Kargath]]. \r\nItem Needed:\r\n*Darkstone Tablet\r\n==Description==\r\nThe Darkstone Tablet holds the writings of the long-dead dwarf Urheld Darkstone. An alchemist of great skill, he was thought insane by his contemporaries and, hence, did not share his research.\r\nBut he did etch it onto tablets, and I believe one such tablet lies in Blackrock Spire, in a chamber once named the Hall of Fortune. I know not what it is now called, for few enter Blackrock and return.\r\nBut if you are willing to brave its dangers and return to me with the tablet, your reward will be great. \r\n==Details==\r\nThe tablet is located in [[Upper Blackrock Spire]] so you'll need to have someone with the key let you in. After you defeat [[Pyroguard Emberseer]], the next room is the Rookery/Hatchery/Egg Room. You'll need to pull the dragonkin into Emberseers room to defeat them. During the fight, they'll try to run back into the hatchery to break open the eggs to release dragonwhelps. You must prevent them from running back.\r\nOnce the dragonkin are all defeated, you can make your way through the room. You must be careful to not get near any of the eggs. When standing in the doorway, the tablet is ahead on the left. The best way to get it is to go to the far end of the room (as if you were going up the ramp to continue the instance) and come at the tablet from behind. Once taken, the tablet will despawn and reappear after about 30 seconds.\r\n==Rewards==\r\nYou will receive one of the following:\r\nYou will also receive:\r\n*2 gold 70 silver \r\n==Progress==\r\nHave you found the Tablet, <name>? I yearn to delve into its secrets. \r\n==Completion==\r\nExcellent. The formulae etched into this tablet will consume days of research, but I am confident such research will bear sweet fruit.\r\nThank you, <name>. You have been invaluable to us. \r\n==Quest progression==\r\n* Vivian Lagrave and the Darkstone Tablet\r\n** The Darkstone Tablet",},
			["The Dark Portal"] = { content = "#REDIRECT [[Dark Portal]]", redirect = "Dark Portal",},
			["The Dark Portal and the Fall of Stormwind"] = { content = "'''\"The Dark Portal and the Fall of Stormwind\"''' is a section of the [[History of Warcraft]], Chapter IV.\r\nFound at:\r\n* [[Lakeshire Inn]] in [[Redridge Mountains]] - inn second floor [[Wiley the Black|Wiley's]] room.\r\n* Near [[Nina Lightbrew]] in [[Nethergarde Keep]].\r\n* Reliquary of [[Scholomance]] in the [[Western Plaguelands]].\r\n* [[Stonard]] in [[Swamp of Sorrows]] - building with trainers\r\n* The War Room of [[Stormwind Keep]] in [[Stormwind]].\r\nTimeline: \r\n* ← Previous book: [[Rise of the Horde (History of Warcraft)|Rise of the Horde]]\r\n* → Next book: [[The Alliance of Lordaeron]]\r\n==Further reading==\r\n*A part of the story can be read in the novel [[The Last Guardian]]. The Dark Portal and Durotan's exile is a part of the [[Rise of the Horde]]. The orc baby is found in the novel [[Lord of the Clans]]. The game [[Warcraft: Orcs & Humans]] deals with the events surrounding the war.",},
			["The Dawnchaser"] = { content = "'''The ''Dawnchaser''''' is one of the three [[blood elf]] [[destroyer]]s in the waters north of the [[Sun's Reach Harbor]], [[Isle of Quel'Danas]]. She is the northeasternmost ship of the fleet.\r\nThis ship is one of three containing [[Dawnblade (blood elves)|Dawnblade]] blood elves, as reinforcements for Kael's forces on the Isle of Quel'Danas.\r\nAfter having set the sails ablaze, this ship is no longer able to continue to its destination.",},
			["The Dawning Isles"] = { content = "#REDIRECT [[Dawning Isles]]", redirect = "Dawning Isles",},
			["The Dead"] = { content = "'''The Dead''' was a unit in [[Warcraft: Orcs & Humans]].\r\nWhen any unit is killed, it will begin to decompose and the remains will slowly seep into the ground. [[Necrolytes]] are trained in the black arts, and can raise these fallen warriors if they can reach the corpse before it disappears into the earth forever.",},
			["The Deadmines"] = { content = "#REDIRECT [[Deadmines]]", redirect = "Deadmines",},
			["The Dead Acre"] = { content = "#REDIRECT [[Dead Acre]]", redirect = "Dead Acre",},
			["The Dead Field"] = { content = "#REDIRECT [[Dead Field]]", redirect = "Dead Field",},
			["The Dead Mines"] = { content = "Were you looking for:\r\n* Information about [[the Deadmines]], largely underground [[subzone]] and [[instance]], in [[Moonbrook]], [[Westfall]]?\r\n* Information about the [[Warcraft I]] [[orc]] mission called [[The Dead Mines (WC1 Orc)|The Dead Mines]]?",},
			["The Dead Mire"] = { content = "#REDIRECT [[Dead Mire]]", redirect = "Dead Mire",},
			["The Dead Scar"] = { content = "#REDIRECT [[Dead Scar]]", redirect = "Dead Scar",},
			["The Deathforge"] = { content = "#REDIRECT [[Deathforge]]", redirect = "Deathforge",},
			["The Deathstalkers"] = { content = "==Objectives==\r\nGet [[Astor's Letter of Introduction]] and return it to [[Mennet Carkad]] in the Rogues' Quarter. \r\n* Astor's Letter of Introduction\r\n== Description==\r\nIf you wish to join the Deathstalkers, Lord Varimathras' elite guard, you will have to prove your worth.\r\nI will not lie to you, <name>, this task could mean your death.\r\nI have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the [[Undercity]]. I will leave the method of procurement to your discretion.\r\nIt will be better for you if you know less of the nature of this business. Succeed and I shall tell you more. \r\n== Progress==\r\nSuccess to report? \r\n== Completion==\r\nWell done, <name>. You've passed the first part of this test. Hopefully Andron will not have caught wind of your activities, and we will be able to convince him that you are, in fact, the messenger he is expecting. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*675 [[XP]] (or 4 silver 20 copper at level 70)",},
			["The Decree of the Scourge"] = { content = "The book '''''The Decree of the Scourge''''' can be found on the first floor of [[Acherus: The Ebon Hold]] near [[Highlord Darion Mograine]].",},
			["The Decrepit Ferry"] = { content = "#REDIRECT [[Decrepit Ferry]]", redirect = "Decrepit Ferry",},
			["The Defense of Grom'gol"] = { content = "==Objectives==\r\nCommander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors. \r\n*Lashtail Raptor slain (15)\r\n== Description==\r\nThrom'ka, <class>!\r\nYour arrival at Grom'gol is timely, indeed. As commander of the Warchief's base camp here in the jungle I am bound by honor to ensure the safety of all members of the [[Horde]]. Our mission to provide a safe chain of supply to [[Stonard]] is being hampered by some of the local inhabitants.\r\nI am putting you in charge of thinning out the raptor population outside of Grom'gol. Once you have made significant progress, report back to me for reassignment. \r\n== Reward==\r\nYou will receive:40 silver copper \r\n== Completion==\r\nYour duty was performed with honor, <class>. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*2800 [[XP]] (or 16 silver 80 copper at level 70)\r\n*250 [[reputation]] with [[Orgrimmar]]",},
			["The Defense of Grom'gol (2)"] = { content = "==Objectives==\r\nCommander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors. \r\n*Mosh'Ogg Brute slain (10)\r\n*Mosh'Ogg Witch Doctor slain (5)\r\n== Description==\r\nWhen we first arrived in this jungle we did not intend to wage war on the local tribes. Our mission to supply [[Stonard]] is of the highest priority. But complications have arisen. A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol. Despite warnings, they continue to ambush our supply caravans.\r\nI am putting you in charge of dealing with these uncooperative ogres.\r\nTravel to the ruins and attempt to drive them from the area. At the very least it will send a firm message. \r\n== Completion==\r\nWell done. You have served the Warchief with honor. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*2850 [[XP]] (or 17 silver 40 copper at level 70)\r\n*250 [[reputation]] with [[Orgrimmar]]",},
			["The Defias Traitor"] = { content = "'''The Defias Traitor''' is a level 15 [[quest giver]] located in [[Sentinel Hill]] in the [[human]] territory of [[Westfall]].\r\nHe starts the quest The Defias Brotherhood, which is part of the chain for the boss quest for the [[Deadmines]].\r\nBecause of his low level, attackable status, and [[Moonbrook]]'s proximity to [[Stranglethorn Vale]], the Horde griefing players on the escort quest by killing the traitor is common on some servers. Alliance players must look out for rogues, especially near the [[Deadmines]] entrance. \r\nSee [[List of Westfall NPCs]].",},
			["The Defilers"] = { content = "#REDIRECT [[Defilers]]", redirect = "Defilers",},
			["The Demon Forge"] = { content = "==Objectives==\r\nTravel to Blackrock Spire and find [[Goraluk Anvilcrack]]. Slay him and then use the [[Blood Stained Pike]] upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.\r\nYou must also find the [[Unforged Rune Covered Breastplate]].\r\nReturn both the [[Soul Stained Pike]] and the [[Unforged Rune Covered Breastplate]] to [[Lorax]] in [[Winterspring]]. \r\n*Unforged Rune Covered Breastplate\r\n*Soul Stained Pike\r\n== Quest text==\r\nLorax makes deals, he does not accept them from insignificant mortals.\r\nA deal I shall make with you, however... take this pike, it is imbued with powerful Fel energies. When you find Goraluk Anvilcrack, slay him and drive this pike through his dying heart. His soul he bartered, his soul I shall have. Return the pike and return the breastplate that the thief stole and I shall teach you what it is that he was to learn. \r\n*Blood Stained Pike(Provided)\r\n== Progress==\r\nTempt not... \r\n== Completion==\r\nOur pact you did not break. The soul I did take. The reward I shall make. \r\n== Reward==\r\nUpon completion of this quest you will gain:\r\n*8300 [[XP]] (or 49 silver 50 copper at level 70)\r\n* 5x Elixir of Demonslaying\r\n* Plans: Demon Forged Breastplate\r\n* Demon Kissed Sack",},
			["The Demon Seed"] = { content = "'''The Demon Seed''' can be found in [[The Barrens]]. \r\n==Background==\r\nThe Demon Seed is a powerful tool for the [[Burning Legion]], guarded by [[Rathorian]]. It rests in a cave on [[Dreadmist Peak]], above a demonic altar of fire. The [[Burning Blade]] rallies around this relic. For reasons unknown, [[Neeru Fireblade]] wishes to destroy this artifact, although it is a valuable asset of the [[Shadow Council]].\r\n==Objective of==\r\nDestroying this item is the objective for the quest The Demon Seed.",},
			["The Demon Soul"] = { content = "'''''The Demon Soul''''' is the second book of the [[War of the Ancients Trilogy]] [[novels]].\r\n==Description==\r\n'''THE [[Burning Legion|BURNING LEGION]] HAS COME.''' \r\nLed by the mighty [[Archimonde]], scores of demonic soldiers now march across the lands of [[Kalimdor]], leaving a trail of death and devastation in their wake. At the heart of the fiery invasion stands the mystic [[Well of Eternity]] -- once the source of the [[Night Elf|Night Elves']] arcane power. But now the Well's energies have been defiled and twisted, for [[Queen Azshara]] and her [[Highborne]] will stop at nothing to commune with their newfound god: the fiery Lord of the Burning Legion... ''[[Sargeras]]''.\r\nThe [[Kaldorei Resistance|night elf defenders]], led by the young druid, [[Malfurion Stormrage]], and the wizard, [[Krasus]], fight a desperate battle to hold back the Legion's terrible onslaught. Though only embers of hope remain, an ancient power has risen to aid the world in its darkest hour. The [[dragon]]s -- led by the powerful [[Dragon Aspects|Aspect]], ''[[Deathwing|Neltharion]]'' -- have forged a weapon of incalculable power: the [[Demon Soul|Dragon Soul]], an artifact capable of driving the Legion from the world forever. But its use may cost far more than any could have foreseen.\r\nThe second novel in an original trilogy of magic, warfare, and heroism based on the bestselling, award-winning electronic game series from [[Blizzard Entertainment]].\r\n==Locations==\r\n*[[Ara-Hinam]]\r\n*[[Chamber of Aspects]]\r\n*[[Dalaran]]\r\n*[[Dy-Jaru]]\r\n*[[Emerald Dream]]\r\n*[[G'Hanir]]\r\n*[[Halumar]]\r\n*[[Mount Hyjal]]\r\n*[[Suramar]]\r\n**[[Black Rook Hold]]\r\n**[[Tomb of Sargeras|Temple of the Moon]]\r\n*[[Urae]]\r\n*[[Zin-Azshari]]\r\n**[[Azshara's Palace]]\r\n**[[Well of Eternity]]\r\n==See also==\r\n*For more information, please see: [[War of the Ancients (novel account)]] and [[War of the Ancients (WC3 account)]].",},
			["The Den"] = { content = "'''The Den''' is the base of operations in the [[Valley of Trials]], and is the starting camp for young [[troll]] and [[orc]] adventurers. It is in the small southwest corner of [[Durotar]]. This is where nearly all the Valley of Trials quests are obtained. It contains basic class trainers and vendors, but no profession trainers. \r\n==Inhabitants==\r\n* [[Canaga Earthcaller]]\r\n* [[Foreman Thazz'ril]]\r\n* [[Galgar]]\r\n* [[Gornek]] (inside the cave)\r\n* [[Kaltunk]]\r\n* [[Magga]]\r\n* [[Ruzan]]\r\n* [[Zureetha Fargaze]]\r\n* Guards: [[Den Grunt|Den Grunts]]\r\n===Vendors===\r\n* [[Duokna]] <General Goods>\r\n* [[Huklah]] <Cloth & Leather Armor Merchant> (inside the cave)\r\n* [[Rarc]] <Armorer & Shieldcrafter> (inside the cave)\r\n* [[Kzan Thornslash]] <Weaponsmith> (inside the cave)\r\n* [[Zlagk]] <Butcher>\r\n===Trainers===\r\nOutside the cave:\r\n* [[Frang]] <Warrior Trainer>\r\n* [[Ken'jai]] <Priest Trainer>\r\n* [[Jen'shan]] <Hunter Trainer>\r\n* [[Mai'ah]] <Mage Trainer>\r\n* [[Shikrik]] <Shaman Trainer>\r\nInside the cave:\r\n* [[Hraug]] <Demon Trainer>\r\n** [[Imp Minion]] <Hraug’s Minion>\r\n* [[Nartok]] <Warlock Trainer>\r\n* [[Rwag]] <Rogue Trainer>",},
			["The Den of Flame"] = { content = "#REDIRECT [[Den of Flame]]", redirect = "Den of Flame",},
			["The Destiny of the Orcish Hordes"] = { content = "#REDIRECT [[Warcraft: Orcs & Humans manual]]", redirect = "Warcraft: Orcs & Humans manual",},
			["The Diary of High General Abbendis"] = { content = "'''The Diary of High General Abbendis''' is the updated version of The Path of Redemption, which was handed to disguised [[death knight]]s whilst accepting the quest The Scarlet Onslaught Emerges.\r\n==Source==\r\n...\r\n==The Diary of High General Abbendis as a quest objective==\r\nThis item is an objective of The Truth Will Out.",},
			["The Disruption Ends"] = { content = "==Task==\r\nKill 8 [[Razormane Geomancer]]s, 8 [[Razormane Defender]]s, and [[Kreenig Snarlsnout]].\r\nThen bring Kreenig Snarlsnout's Tusk to Thork at the Crossroads.\r\n==Notes==\r\nThe [[Razormane Quilboar]]s you need to kill are to the northeast of Crossroads. They will be in large numbers along the north and northeast side of the mountains east of Crossroads.\r\nKreenig Snarlsnout will be south southwest the Crossroads' Supply Crates northeast of the mountains east of Crossroads. There will be [[Razormane Mystic]]s, [[Razormane Defender]]s, and some [[Razormane Hunter]]s near this area, too.\r\nYou will need one inventory space free to retrieve from his corpse. This is a required item to complete the quest.\r\nYou may wish to complete this quest along with the Supplies for the Crossroads quest, as you will find the Crossroads' Supply Crates around the Razormane Defenders and the Razormane Geomancers.",},
			["The Domicile"] = { content = "#REDIRECT [[Domicile]]", redirect = "Domicile",},
			["The Dor'Danil Barrow Den"] = { content = "#REDIRECT [[Dor'Danil Barrow Den]]", redirect = "Dor'Danil Barrow Den",},
			["The Dragonblight"] = { content = "#redirect [[Dragonblight]]", redirect = "Dragonblight",},
			["The Dragonmurk"] = { content = "#REDIRECT [[Dragonmurk]]", redirect = "Dragonmurk",},
			["The Drowned Reef"] = { content = "#REDIRECT [[Drowned Reef]]", redirect = "Drowned Reef",},
			["The Druids Arise (WC3 NightElf)"] = { content = "The Druids Arise is Chapter 4 of the Night Elf campaign, [[Eternity's End]]. It begins with [[Tyrande Whisperwind]] and [[Furion Stormrage]] building a base. They soon run out of gold and attack a [[Human]] settlement. They destroy it and build a base over it. They soon encounter the [[Burning Legion]] and the [[Orcs]] fighting in the air. Tyrande and Furion also find a tribe of corrupted [[Furbolg]], whom they must kill.\r\nThe [[Night Elves]] find that the forest is corrupted and that they must slay the Reverant who is in the forest to cleanse it. They fight through the monsters and kill the Reverant. The forest then becomes purified. Then they find their way to the Druids of the Talon and Awaken them. Then Furion suggestes that they Awaken the Druids of the Claw.",},
			["The Dry Hills"] = { content = "#REDIRECT [[Dry Hills]]", redirect = "Dry Hills",},
			["The Duke of Fathoms"] = { content = "'''The Duke of Fathoms''' is a level 62 [[elite]] [[hydra]], and one of the Elemental Nobles of the [[Abyssal Council]]. The [[Cenarion Circle]] believe that he and and the other three Dukes are the primary force behind the organization of the [[Twilight's Hammer]] Cultists in [[Silithus]].\r\nThe Duke of Fathoms does not appear normally in the standard plane of existence but must be summoned. There are two ways of summoning the Duke:\r\n#Acquire a set of [[Twilight Trappings]] and a [[Twilight Cultist Medallion of Station]]. This will make you appear to be a middle-ranked leader of the Twilight's Hammer. Travel to a [[Wind stone]] and use it to summon a Duke. You have a 1 in 4 chance of summoning the Duke of Fathoms.\r\n#Turn in [[Encrypted Twilight Text]]s to [[Hermit Ortell]]. He will then mail you a random item. If you get a [[Scroll: Create Signet of Beckoning (Water)]], you can combine that with a [[Dark Rune]] and 5 [[Enchanted Water]] to create a [[Signet of Beckoning: Water]]. This signet can be used to specifically summon the Duke of Fathoms.\r\nThe Duke of Fathoms has a knockback attack that wipes aggro. The knockback is also quite strong and due to fast respawns of some mobs in the area, this might cause many adds to join the battle and quickly turn the tide against a party.\r\nRanged DPS is valuable, because all those in melee range will be affected by the knockback.\r\n==Quests==\r\n*The Four Dukes\r\n==Loot==\r\n*Abyssal Mail Legguards of ...\r\n*Abyssal Signet\r\n*Darkstone Claymore\r\n*Abyssal Leather Belt of ...\r\n*Essence of Water\r\n*Globe of Water\r\n*Elemental Water",},
			["The Dustbowl"] = { content = "#REDIRECT [[Dustbowl]]", redirect = "Dustbowl",},
			["The Dust Plains"] = { content = "#REDIRECT [[Dust Plains]]", redirect = "Dust Plains",},
			["The Dwarven District"] = { content = "#REDIRECT [[Dwarven District]]", redirect = "Dwarven District",},
			["The Earthen Ring"] = { content = "#REDIRECT[[Earthen Ring]]", redirect = "Earthen Ring",},
			["The Ectoplasmic Distiller"] = { content = "==Task==\r\n'''Return to [[Mux Manascrambler]] in [[Gadgetzan]] with:'''\r\n* 1x Delicate Arcanite Converter\r\n* 4x Greater Eternal Essence\r\n* 10x Stonescale Oil\r\n* 25x Volcanic Ash\r\n* 40 gold \r\n''Ah, you're in need of my latest project... the extra-dimensional ghost revealer! Unfortunately I've run out of funds and manpower.''\r\n''You're willing to help? Excellent! Our first task is to build a device to harvest the very fabric of death! Building an ectoplasmic distiller won't be an easy task, <name>.''\r\n''I'll need you to bring me an arcanite converter, some greater eternal essences and stonescale oil. I'll also need some volcanic ash from the lava pools in the Burning Steppes to build a filter.''\r\n==Reward==\r\n* 6600 XP\r\n* Mux's Quality Goods\r\n==Notes==\r\n* This is the second step in the quest chain to upgrade your [[Dungeon Set 1]] Belt and Gloves into [[Dungeon Set 2]].\r\n* Delicate Arcanite Converters are created by [[Engineering|Engineers]].\r\n* Greater Eternal Essences are created by [[Enchanting|Enchanters]] by [[disenchanting]] level 50-60 [[uncommon|uncommon/green]] weapons.\r\n* Stonescale Oil is created by [[Alchemy|Alchemists]].\r\n* Volcanic Ash can be found in the [[Burning Steppes]], mostly between [[Blackrock Mountain]] and [[Flame Crest]]. It looks like a pile of dirt and is generally near lava or dried lava channels.\r\n* When you complete the quest, you will be given Mux's Quality Goods, containing:\r\n** 1 Ectoplasmic Distiller\r\n** 8 Goblin Rocket Fuel\r\n** 6 Ez-Thro Dynamite II\r\n** 1 Discombobulator Ray",},
			["The Epoch Hunter"] = { content = "#REDIRECT [[Epoch Hunter]]", redirect = "Epoch Hunter",},
			["The Exodar"] = { content = "#REDIRECT [[Exodar]]", redirect = "Exodar",},
			["The Eye"] = { content = "#REDIRECT [[Eye]]", redirect = "Eye",},
			["The Eye of Eternity"] = { content = "#REDIRECT [[Eye of Eternity]]", redirect = "Eye of Eternity",},
			["The Fallen Hero of the Horde"] = { content = "#REDIRECT [[Fallen Hero of the Horde]]", redirect = "Fallen Hero of the Horde",},
			["The Fall of Gurubashi"] = { content = "#REDIRECT [[The Third Troll Legend]]", redirect = "The Third Troll Legend",},
			["The Fall of Kel'Thuzad"] = { content = "'''''The Fall of Kel'Thuzad''''' is a quest which begins from The Phylactery of Kel'Thuzad, dropped by [[Kel'Thuzad]] in [[Naxxramas]].\r\n==Intro==\r\n''The phylactery is all that remains of the master of Naxxramas. Your better judgment dictates that you destroy the phylactery, preventing the lich from ever reforming. Thankfully, you seldom listen to that internal voice of reason.''\r\n''Someone at Light's Hope will pay you hugely for this artifact. Who cares if Kel'Thuzad regenerates to full power?''\r\n==Objectives==\r\n''Take the Phylactery of Kel'Thuzad to [[Light's Hope Chapel]] in the [[Eastern Plaguelands]].''\r\n==Progress==\r\n''BLESSED LIGHT! What foulness do you hold, (boy/girl)?''\r\n==Completion==\r\n''In all my days of living I would never have expected to see this...''\r\n''<Father Montoy appears to be salivating.>''\r\n''Oh yes, you will be rewarded dear (boy/girl). You will be greatly rewarded. Give it here. Now!''\r\n==Rewards==\r\nYou will be able to choose one of the following:",},
			["The Fall of the Betrayer"] = { content = "The final showdown: Destroy [[Illidan Stormrage (tactics)|Illidan Stormrage]], and free Outland from his iron grip!\r\n==Objectives==\r\nSeer Kanai wants you to defeat Illidan inside the Black Temple.\r\n*Illidan Stormrage (tactics) slain\r\n*Medallion of Karabor\r\nThe Medallion is required to enter the Black Temple; this quest allows the bearer to upgrade it so that it can teleport the bearer to the Black Temple's gates from anywhere in the worlds (much like [[Atiesh, Greatstaff of the Guardian]] is used to teleport wielders - and their parties - to Karazhan).\r\n==Description==\r\nWith Illidan's lieutenants defeated, Akama will be able to force open the doors to Illidan's sanctum. Be ready to bring your force inside as soon as Akama does.\r\nWe still do not know what has become of Maiev, but we must make our move without her.\r\nI hope your force is up to the task. Illidan will not be pleased to see Akama. \r\n==Progression==\r\nYes, <name>? \r\n==Completion==\r\nIt is as it was foretold, <name>. One by one, Illidan's lieutenants have fallen... and now the Betrayer himself has met his demise!\r\nKnow this, <name>: every decision Akama made and every moment of his life since Illidan arrived, Akama planned for this moment. Illidan is finally dead and our people... are free! \r\n==Quest Progression==\r\n* The Secret Compromised\r\n**Ruse of the Ashtongue\r\n**An Artifact From the Past\r\n**The Hostage Soul\r\n**Entry Into the Black Temple\r\n**A Distraction for Akama\r\n***Seek Out the Ashtongue\r\n***Redemption of the Ashtongue\r\n***The Fall of the Betrayer",},
			["The Farstrider Lodge"] = { content = "#REDIRECT [[Farstrider Lodge]]", redirect = "Farstrider Lodge",},
			["The Fate of the Kingdom"] = { content = "==Objectives==\r\nReturn to [[Blackrock Depths]] and rescue [[Princess Moira Bronzebeard]] from the evil clutches of [[Emperor Dagran Thaurissan]].\r\n*Kill Emperor Dagran Thaurissan without killing Moira. If Moira dies, the quest cannot be turned in during that run.\r\n==Quest Text==\r\nIt would seem as if my old adversary, Dagran Thaurissan, has me and the [[kingdom of Ironforge]] at his mercy.\r\nYou may be my last hope, <name>. You must rescue my dear daughter, Moira!\r\nThere is only one way to make sure that the spell Thaurissan has cast on Moira is broken: Kill him.\r\nAnd <name>, do not harm her! Remember, she is being controlled by Thaurissan! The things she may do or say are a result of Thaurissan's evil spell!\r\n==Details==\r\nEmperor Dagran Thaurissan is the final boss of Blackrock Depths.",},
			["The Feast of Winter Veil"] = { content = "'''The Feast of Winter Veil''' is a book that summarizes the legends surrounding the [[Feast of Winter Veil]] seasonal [[event]].\r\n==Source==\r\nThis item is provided as an objective for [[The Feast of Winter Veil (quest)]].",},
			["The Feast of Winter Veil (In-Game Book)"] = { content = "#REDIRECT [[The Feast of Winter Veil]]", redirect = "The Feast of Winter Veil",},
			["The Fel Barrier"] = { content = "'''The Fel Barrier''' is an epic tanking shield with fire and shadow resistance bonuses.\r\n==Source==\r\nThis item drops from [[Nexus-Prince Shaffar]] in [[Mana Tombs]] on [[heroic]] mode.",},
			["The Fel Pits"] = { content = "#redirect [[Fel Pits]]", redirect = "Fel Pits",},
			["The Fetid Pool"] = { content = "#redirect [[Fetid Pool]]", redirect = "Fetid Pool",},
			["The Final Code"] = { content = "==Source==\r\nThis item drops from [[Sharth Voldoun]] in [[Terokkar Forest]].\r\n==The Final Code as a quest objective==\r\nThis item is an objective for the following quests:\r\n* The Final Code (Alliance)\r\n* The Final Code (Horde)",},
			["The Final Tablets"] = { content = "==Objectives==\r\nBring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.\r\nItems Needed:\r\n*1 x [[Fifth Mosh'aru Tablet]]\r\n*1 x [[Sixth Mosh'aru Tablet]]\r\n==Quest Text==\r\nWhile I look over the third and fourth tablets of Mosh'aru, you must find the fifth and sixth! It will not be easy, for they are held by the Smolderthorn trolls within Blackrock Spire. The spire is a dark mountain of fire between the Burning Steppes and the Searing Gorge.\r\nGood luck, <name>. Blackrock Spire is no place for decent folk...\r\n==Details==\r\nThe tablets are located in the troll-controlled section of the lower part of [[Blackrock Spire]]. One is in the room where [[War Master Voone]] sits; the other is behind [[Shadow Hunter Vosh'gajin]].\r\n==Reward==\r\nExperience Awarded 7750\r\n==Quest Progression==\r\n*Screecher Spirits\r\n**The Prophecy of Mosh'aru\r\n**The Ancient Egg\r\n**The God Hakkar\r\n**The Lost Tablets of Mosh'aru\r\n**The Final Tablets\r\n***Confront Yeh'kinya\r\n***The Hand of Rastakhan",},
			["The Flesh Lies..."] = { content = "==Objectives==\r\nUse the [[Protectorate Igniter]] on 12 Withered Corpses. Return the [[Protectorate Igniter]] to [[Agent Araxes]] outside of Access Shaft Zeon when the task is complete. \r\n*Withered Corpse (12)\r\n* Protectorate Igniter (Provided)\r\n== Description==\r\nYou see these corpses, <race>? Arconus is responsible for this slaughter. He's sucked them dry, leaving nothing more than a fleshy husk. But don't let the bodies fool you! Inside those corpses lie flesh beasts, waiting to pounce on the unsuspecting fool that gets too close.\r\nI've got my orders. I must remain here until backup arrives. That doesn't mean that you can't take my igniter and destroy the withered corpses that litter the mines. One way or another, the mission must be completed. \r\n== Progress==\r\nAny luck in finding Ya-six? \r\n== Completion==\r\nYou saved my wrappings, <name>. The Protectorate will know of what you've done on this day, friend. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*12650 [[XP]] (or 7 gold 59 silver copper at level 70)\r\n*250 [[reputation]] with [[The Consortium]]\r\n==Notes==\r\nIt is advisable to do Arconus the Insatiable before you turn in your Protectorate Igniter, as you can skip half the kills by simply charring the withered corpses instead of fighting them.",},
			["The Flight from Lordaeron (WC3 Undead)"] = { content = "Chapter 2 of the Undead Campaign, Act III \"[[Legacy of the Damned]]\" in [[Warcraft III: The Frozen Throne]]",},
			["The Forbidding Sea"] = { content = "#REDIRECT [[Forbidding Sea]]", redirect = "Forbidding Sea",},
			["The Forgotten Coast"] = { content = "#redirect [[Forgotten Coast]]", redirect = "Forgotten Coast",},
			["The Forgotten Pools"] = { content = "#REDIRECT [[Forgotten Pools]]", redirect = "Forgotten Pools",},
			["The Forgotten Pools (quest)"] = { content = "==Objectives==\r\nReport back to [[Tonga Runetotem]] with your findings.\r\n*Explore the waters of the [[Forgotten Pools]]\r\n==Description==\r\nLong ago, the [[Barrens]] was a lush place, teeming with life. But war and cataclysm raged across the land, scorching it and leaving a dry husk. Such is the way of things, and it saddens my heart.\r\nBut within the past few years, new oases have formed in the Barrens, and life stirs. And deep down, we druids sense a power leaking its way to the surface.\r\nWe must find its source. Travel to the Forgotten Pools, northwest of the [[Crossroads]]. Search its waters for a source of power, then return here.\r\n==Progress==\r\nHave you been to the Forgotten Pools, <name>? Did you find anything?\r\n==Completion==\r\nYou found a fissure in the earth, with gases bubbling from it? Strange. This may be an answer to our questions, but we cannot yet be sure.\r\nBut it is a clue. And I am grateful that you found it.\r\n==Gains==\r\n*675 [[XP]] (or 4 silver 20 copper at level 70)\r\n*150 [[reputation]] with [[Thunder Bluff]]\r\n==Notes==\r\nYou must dive into the oasis and go near the bubbling rock on the bottom to explore the waters of the Forgotten Pools before heading back to Tonga Runetotem.\r\n==Quest Progression==\r\n#The Barrens Oases\r\n#The Forgotten Pools\r\n#The Stagnant Oasis\r\n#Altered Beings\r\n#Hamuul Runetotem\r\n#Nara Wildmane\r\n#Leaders of the Fang",},
			["The Forlorn Cavern"] = { content = "#REDIRECT [[Forlorn Cavern]]", redirect = "Forlorn Cavern",},
			["The Foul Pool"] = { content = "#redirect [[Foul Pool]]", redirect = "Foul Pool",},
			["The Founding of Quel'Thalas"] = { content = "'''\"The Founding of Quel'Thalas\"''' is a section of the [[History of Warcraft]], Chapter II. It is set 6,800 years before Warcraft I.\r\nFound at:\r\n* [[Scarlet Raven Tavern]] in [[Duskwood]].\r\n* Viewing Room of [[Scholomance]] in the [[Western Plaguelands]].\r\nTimeline: \r\n* ← Previous book: [[The Sentinels and the Long Vigil]]\r\n* → Next book: [[Arathor and the Troll Wars]]",},
			["The Four Dragons"] = { content = "#REDIRECT [[Dragons of Nightmare]]", redirect = "Dragons of Nightmare",},
			["The Four Horsemen"] = { content = "#REDIRECT [[Four Horsemen (tactics)|Four Horsemen]]", redirect = "Four Horsemen (tactics)|Four Horsemen",},
			["The Frostborn"] = { content = "#REDIRECT [[Frostborn]]", redirect = "Frostborn",},
			["The Frostwolf Artichoke"] = { content = "'''The Frostwolf Artichoke''' is rewarded from the quest [[Proving Grounds (Alterac Valley) (Alliance)]].\r\n==See also==\r\n*[[Peeling the Onion]]",},
			["The Frostwolf Artichoke: Tales of Stormpike Glory"] = { content = "#REDIRECT [[The Frostwolf Artichoke]]", redirect = "The Frostwolf Artichoke",},
			["The Frozen Glade"] = { content = "#REDIRECT [[Frozen Glade]]", redirect = "Frozen Glade",},
			["The Frozen Throne"] = { content = "#REDIRECT [[Warcraft III: The Frozen Throne]]", redirect = "Warcraft III: The Frozen Throne",},
			["The Fungal Vale"] = { content = "#REDIRECT [[Fungal Vale]]", redirect = "Fungal Vale",},
			["The Furnace"] = { content = "#redirect [[Furnace]]", redirect = "Furnace",},
			["The Gaping Chasm"] = { content = "#REDIRECT [[Gaping Chasm]]", redirect = "Gaping Chasm",},
			["The Gauntlet"] = { content = "#redirect [[Gauntlet]]", redirect = "Gauntlet",},
			["The Glowing Shard"] = { content = "==Objectives==\r\nTravel to [[Ratchet]] to find someone that can tell you more about the glowing shard.\r\nThen, deliver the shard as you are directed. \r\n*Speak with someone in Ratchet about the Glowing Shard\r\n*Glowing Shard (Provided)\r\n== Description==\r\nThe shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.\r\nMaybe you should see if anyone in Ratchet can tell you more about this strange shard.\r\n==Notes==\r\nTalk to [[Sputtervalve]] in Ratchet. (The [[Goblin]] next to the Flightmaster.) He does not have a question mark over his head but he will have a conversation topic about the glowing shard which directs you back to [[Falla Sagewind]], who is camped at the top of mountain above the [[Wailing Caverns]].\r\n== Progress==\r\nHello, <race>. What can I do for you? \r\n== Completion==\r\nOh... I have never seen anything like this... \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*2650 [[XP]] (or 16 silver 20 copper at level 70)\r\n==Quest progression==\r\n*The Glowing Shard\r\n**In Nightmares (Horde)\r\n**In Nightmares (Alliance)",},
			["The God Hakkar"] = { content = "The God Hakkar is the 4th quest in the '''Screecher Spirits''' quest chain.\r\n==Objectives==\r\nBring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.\r\n* Filled Egg of Hakkar\r\nProvided Item:\r\n* Egg of Hakkar\r\n==Description==\r\nNow it is time to capture the essence of the avatar of Hakkar.\r\nTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth. Invoke the egg's power to stir the dead god.\r\nHe will send his minions against you. Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit. When all the flames go out, the avatar of Hakkar will enter our world.\r\nDefeat him, and place his essence within the egg of Hakkar.\r\n==Progress==\r\nHave you defeated the avatar of Hakkar, <name>? Has his essence yet empowered the egg I gave you?\r\n==Completion==\r\nThe essence of Hakkar has been collected! Even now the Egg stirs with life! Could the myths of Hakkar be true?\r\nThat must not be true, for it is then I fear what Hakkar may do if birthed again. I will keep this egg safe and be sure it does not fall into evil hands.\r\nYour labors with me are finished, <name>. You have touched a legend, and your actions may one day change the face of our world.\r\n==Rewards==\r\n \r\nYou will also receive: g=2 gold s=40 silver \r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*11400 [[XP]] (or s=69 gold at level 70)\r\n==Quest chain==\r\n#Screecher Spirits\r\n#The Prophecy of Mosh'aru\r\n#The Ancient Egg\r\n#The God Hakkar",},
			["The Golden Plains"] = { content = "#REDIRECT [[Golden Plains]]", redirect = "Golden Plains",},
			["The Good News and The Bad News"] = { content = "'''The Good News and The Bad News''' is a quest which begins the conclusion of the icon= fork of icon= quest chain to open the [[Gates of Ahn'Qiraj]]. Players must have completed all of the preceding quest forks, (icon=, icon= and icon=) before Narain Soothfancy will offer this quest.\r\n==Objectives==\r\nNarain Soothfancy in [[Tanaris]] wants you to bring him 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds, and 10 Blue Sapphires. \r\n*icon= (20)\r\n*icon= (10)\r\n*icon= (10)\r\n*icon= (10)\r\n==Description==\r\nWell that took a little longer than expected. Now let me see what this ledger says.\r\n<Narain silently reads the ledger, periodically mumbling under his breath.>\r\nThe good news is that I am 99% certain that I am capable of creating an Arcanite Buoy that will function to your specifications. This is, of course, wholly dependant on the bad news.\r\nThe bad news is that I'm going to need a lot of arcanite, elementium ore, and rare gemstones.\r\nBring me what I need and I will craft the buoy.\r\n==Progress==\r\nArcanite buoys don't just make themselves, <name>. And NO, you cannot borrow some money. \r\n==Completion==\r\nA deal is a deal. I sure hope you know what you are getting yourself into, <name>. This is an awful lot of trouble to go through to do some fishing. \r\n==Notes==\r\nAfter completing this quest, Narain sends the player a letter using in-game mail, along with 100 gold .",},
			["The Great Fissure"] = { content = "#REDIRECT [[Great Fissure]]", redirect = "Great Fissure",},
			["The Great Forge"] = { content = "#REDIRECT [[Great Forge]]", redirect = "Great Forge",},
			["The Great Lift"] = { content = "#REDIRECT [[Great Lift]]", redirect = "Great Lift",},
			["The Great Masquerade"] = { content = "This is part of the [[The Great Masquerade quest chain|Great Masquerade]] quest chain.\r\nThis quest is flashy - the dialog occurring during the quest is Zone-wide. Innocent\r\nbystanders in [[Stormwind Keep]] may be incidentally slain, so warnings to the ignorant may be called for.\r\n==Objectives==\r\nFollow [[Reginald Windsor]] through [[Stormwind]]. Protect him from harm! \r\n*Reginald's March\r\n== Quest text==\r\nIt has been quite the adventure, friend. I owe you a great debt of gratitude. Perhaps, when all is said and done...\r\nAs you have no doubt ascertained by now, [[Lady Prestor]] is [[Onyxia]]: Brood of [[Deathwing]], twin to the tyrant of the Spire, [[Nefarian]].\r\nFor too long she has held our kingdom in her captivating gaze. Even the\r\n[[Highlord Bolvar Fordragon|Highlord]] is controlled by her trickery - a puppet.\r\nIt all ends today... The spell will be broken.\r\nWorry not, for together, we shall be victorious!\r\nAre you ready? \r\n== Completion==\r\n<Bolvar holds the shattered medallion.>\r\nThe magic held within must be reignited. The dragon's eye must be attuned.\r\nWindsor's sacrifice has freed our Kingdom, but the threat of Onyxia and her\r\nkin is ever looming.\r\nThis medallion is what held my mind and body captive. It is also what gave\r\nme access to Onyxia's own mind - to her secrets. Albeit the visions are\r\nmuddled now, some things I do remember. \r\n== Rewards==\r\nUpon completion of this quest you will gain:\r\n*14300 [[XP]] (or 60 silver copper at level 70)\r\n*500 [[reputation]] with [[Stormwind]]\r\n==Notes==\r\nWhile this quest may be a lot more fun with a full raid group, and can be undertaken while in such a group, it need not be.\r\nEscort Windsor to the audience hall of Stormwind Keep, but if you stand back out of\r\naggro range, most of the combat should pass you by, with Bolvar defeating the entire\r\ndragonkin force by himself. ... Or nearly, anyway.\r\nIf you fail this quest (Bolvar can die), go back to [[Squire Rowe]] and talk to him again. ... or, exit the gates into [[Elwynn Forest]] and come back in. Windsor should reappear.\r\nAnd no, [[Marshal Windsor]] is doomed. Sorry.\r\n==NPC scripts==\r\n'''Lady Katrana Prestor yells:''' Seize him! Seize the worthless criminal and his allies!\r\n'''General Marcus Jonathan says:''' Reginald, you know that I cannot let you pass.\r\n'''Reginald Windsor says:''' You must do what you think is right, Marcus. We served together under Turalyon. He made us both the men that we are today. Did he err with me? Do you truly believe my intent is to cause harm to our alliance? Would I shame our heroes?\r\n'''Reginald Windsor says:''' Holding me here is not the right decision, Marcus.\r\n'''General Marcus Jonathan appears lost in contemplation.'''\r\n'''General Marcus Jonathan says:''' I am ashamed, old friend. I know not what I do anymore. It is not you that would dare bring shame to the heroes of legend - it is I. It is I and the rest of these corrupt politicians. They fill our lives with empty promises, unending lies.\r\n'''General Marcus Jonathan says:''' We shame our ancestors. We shame those lost to us... forgive me, Reginald.\r\n'''Reginald Windsor says:''' Dear friend, you honor them with your vigilant watch. You are steadfast in your allegiance. I do not doubt for a moment that you would not give as great a sacrifice for your people as any of the heroes you stand under.\r\n'''Reginald Windsor says:''' Now, it is time to bring her reign to and end, Marcus. Stand down, friend.\r\n'''General Marcus Jonathan says:''' Stand down! Can you not see that heroes walk among us?\r\n'''General Marcus Jonathan says:''' Move aside! Let them pass!\r\n'''General Marcus Jonathan yells:''' Reginald Windsor is not to be harmed! He shall pass through untouched!\r\n'''General Marcus Jonathan says:''' Go, Reginald. May the light guide your hand.\r\n'''Stormwind City Patroller says:''' Light be with you, sir.\r\n'''Stormwind City Patroller says:''' We are but dirt beneath your feet, sir.\r\n'''Stormwind City Patroller says:''' ...nerves of thorium.\r\n'''Stormwind City Patroller says:''' Make way!\r\n'''Stormwind City Patroller says:''' A living legend...\r\n'''Reginald Windsor says:''' Be brave, friends. The reptile will thrash wildly. It is an act of desperation. When you are ready, give me the word.\r\n The dragon hides behind a royal facade.\r\n The tablets will reveal her for what she\r\n is... If what I have seen holds true, I will\r\n not survive this battle, friend. It is you\r\n that must finish what I have started. Are\r\n you forces ready? Are you ready? We\r\n will begin on your command.\r\n \r\n <talk bubble> I am ready, as are my forces. Let us end\r\n this masquerade!\r\n'''Reginald Windsor says:''' Onward!\r\n'''Reginald Windsor says:''' Majesty, run while you still can. She is not what you think her to be...\r\n'''Highlord Bolvar Fordragon says:''' To the safe hall, your majesty.\r\n'''Reginald Windsor says:''' The masquerade is over, Lady Prestor. Or should I call you by your true name... Onyxia...\r\n'''Lady Katrana Prestor laughs.'''\r\n'''Lady Katrana Prestor says:''' You will be incarcerated and tried for treason, Windsor. I shall watch with glee as they hand down a guilty verdict and sentence you to death by hanging...\r\n'''Lady Katrana Prestor says:''' And as your limp body dangles from the rafters, I shall take pleasure in knowing that a mad man has been put to death. After all, what proof do you have? Did you expect to come in here and point your fingers at royalty and leave unscathed?\r\n'''Reginald Windsor says:''' You will not escape your fate, Onyxia. It has been prophesied - a vision resonating from the great halls of Karazhan. It ends now...\r\n'''Reginald Windsor says:''' The Dark Iron's thought these tablets to be encoded. This is not any form of coding, it is the tongue of ancient dragon.\r\n'''Reginald Windsor says:''' Listen, dragon. Let the truth resonate throughout these halls.\r\n'''Reginald Windsor reads from the tablets. Unknown, unheard sounds flow through your consciousness.'''\r\n'''Highlord Bolvar Fordragon gasps.'''\r\n'''Lady Onyxia says:''' Curious... Windsor, in this vision, did you survive? I only ask because one thing that I can and will assure is your death. Here and now.\r\n'''Highlord Bolvar Fordragon yells:''' Dragon filth! Guards! Guards! Seize this monster!\r\n'''Reginald Windsor says:''' DO NOT LET HER ESCAPE!\r\n'''Highlord Bolvar Fordragon says:''' Reginald... I... I am sorry.\r\n'''Reginald Windsor says:''' Bol... Bolvar... the medallion... use...\r\n'''Reginald Windsor dies.'''",},
			["The Great Masquerade quest chain"] = { content = "This is the alliance quest chain that leads to obtaining the [[Drakefire Amulet]],\r\nthe key to [[Onyxia's Lair]]. This is one of the most arduous quest chains in the game,\r\ninvolving multiple trips into [[Blackrock Depths]], a major event in [[Stormwind City]],\r\nand a raid in [[Upper Blackrock Spire]]. It may require several [[Lower Blackrock Spire]] runs\r\nas well, to acquire the key to the raid area.\r\n==The Great Masquerade==\r\nMonumental events, from such simple beginnings...\r\n===Prelude: The Dragonkin Menace===\r\n* '''Dragonkin Menace'''\r\n[[Morgan's Vigil]] struggles to survive against the pressure of the\r\n[[Black Dragonflight|Black Flight]]. [[Helendis Riverhorn]] asks you\r\nfor help pushing back their forces.\r\nShowing sympathy for the people of [[Morgan's Vigil]], you combat the\r\nBlack Flight's forces, slaying a great many of them, including a\r\nfearsome [[Black Drake]].\r\nAs have other people elsewhere on [[Azeroth]], Helendis has other problems,\r\nand used this task to see if you would be up to challenges greater yet...\r\n===Act 1: The True Masters===\r\n* '''The True Masters (1)'''\r\nHelendis tells you of the outpost's findings: that they believe the\r\n[[Blackrock Clan|Blackrock orcs]] are under the control of the\r\n[[Black Dragonflight|black dragonflight]]. Helendis has decided to\r\n\"kick the issue upstairs\", and wants you to take a letter to\r\n[[Magistrate Solomon]], in [[Lakeshire]], in the [[Redridge Mountains]].\r\n* '''The True Masters (2)'''\r\nSolomon opens the letter, and decides that [[Stormwind]] must respond, or\r\nall is lost. He directs you to [[Highlord Bolvar Fordragon]], in\r\n[[Stormwind Keep]].\r\n* '''The True Masters (3)'''\r\nBolvar, though, is reluctant to send troops without having undisputable proof.\r\n''(You may have learned earlier, that it's hard all over, troops are spread thin,\r\n''and nobody is getting enough military aid... See the\r\n'' quest chain.)\r\nBolvar asks you to speak to [[Lady Prestor]], who downplays the situation.\r\n* '''The True Masters (4)'''\r\nPolitician that he is, Bolvar determines to make you an acting deputy of\r\nStormwind, and sends you back to Magistrate Solomon.\r\nUnderstandably, Solomon is not overjoyed to find that instead of an army,\r\nhe only gets you...\r\n* '''The True Masters (5)'''\r\nAs deputy of Stormwind, Solomon says, you are required to report to\r\n[[Marshal Maxwell]], back at [[Morgan's Vigil]].\r\nWhen you get there, Maxwell just laughs.\r\n* '''The True Masters (6)'''\r\nIt seems you aren't the first to be so deputized. Brave men and true have\r\nbeen lost in this fight.\r\nThe former commander, [[Marshal Windsor]], had gathered a great amount of\r\ninformation before being ambushed and taken by the orcs. The only person\r\nto win free of the fight was [[Ragged John]], who has retreated to a cave\r\nto the north.\r\nYou travel north to [[Flame Crest]], and locate Ragged John, and tease the\r\nstory out of him. It seems that the orcs failed their assault, and instead the [[Dark Iron Dwarves]] captured Marshal Windsor alive!\r\n===Act 2: The Search for Marshal Windsor===\r\n* '''Marshal Windsor'''\r\n[[Marshal Maxwell]] directs you personally to go into the [[Blackrock Depths]]\r\nand find Windsor.\r\nYou gather a small group of adventurers, and venture into the depths.\r\nYou manage to defeat a number of the [[Anvilrage]] guards, including\r\nan [[High Interrogator Gerstahn|interrogator]] who has the key to Windsor's\r\nprison cell.\r\n* '''Abandoned Hope'''\r\nMarshal Windsor is furious with Bolvar. (Join the club, mate. They've got\r\ntruncheons and inscribed breastplates...) But without his notes, and\r\nwithout [[Ironfoe]] (his mace), Windsor is despondent. The situation\r\nappears hopeless.\r\nYou return to Maxwell, who believes that Windsor has simply gone around the\r\nbend. Still, he rewards you for your dangerous work.\r\n* '''A Crumpled Up Note'''\r\nUnwilling to completely abandon Marshal Winsor to his fate, you travel back\r\nto the depths, and go ... investigating.\r\nOn one of the bodies, you discover\r\nA Crumpled Up Note The note mentions\r\na couple of high ranking dwarves among the Anvilrage - [[General Angerforge]],\r\nand [[Golem Lord Argelmach]].\r\n* '''A Shred of Hope'''\r\nYou take the note to [[Marshal Windsor]], who believes that between them,\r\nthese two [[Dark Iron]] dwarven leaders hold the most of his notes. If you\r\nretrieve them, it will be enough to force the issue in Stormwind...\r\nYou and your friends venture into the dark places of [[Blackrock Depths]]\r\nand overcome both the general and the golem lord, retrieving Windsor's plans.\r\n* '''Jail Break!'''\r\nMarshal Windsor seems completely re-energized by the return of the tablets.\r\nHe insists on leaving the dungeon immediately, and asks your aid in escaping.\r\nFirst, however, there's some unfinished business that he has to attend to,\r\nother members of the patrol he was with, fellow prisoners.\r\nYou escort him to a supply closet, where he rearms himself. He may not have\r\n[[Ironfoe]] with him, but at least he's got good solid steel between him and\r\nthe world. He leads you across the prison compound to the other cells, where\r\ncertain people he sets free, and others - treacherous ones - he dispatches\r\nrough justice upon.\r\nEventually, though, you manage your way back out of the depths. Once in the\r\nclear, though, even you can't keep up with him. You make your way back to\r\n[[Morgan's Vigil]], and talk with [[Marshal Maxwell]]. By the time you get\r\nthere, Windsor has been there and gone again, off to [[Stormwind]].\r\n===Act 3: Revelation at Stormwind Keep===\r\n* '''Stormwind Rendezvous'''\r\nMaxwell tells you that Windsor's instructions are for you to meet him at the\r\ngates of [[Stormwind]], with as many people as you can gather.\r\n''(You do\r\n''recall that Windsor was the post's commander, right? Maxwell was merely\r\n''standing in for him in absence of direction from the Keep...)''\r\nYou gather such a force as you are able, and head to Stormwind.\r\n* '''The Great Masquerade'''\r\nYou meet up with Windsor at the gates of Stormwind, resplendent in polished\r\narmor, white charger and all. The guard at the gate challenges him, and\r\n[[Lady Katrana Prestor|Lady Prestor]] calls for his head.\r\n[[Bolvar Fordragon|Bolvar]] countermands her, though, commanding that none\r\nof the guards are to touch him.\r\nYou escort Windsor through the city to the keep, where he presents his\r\ninformation to the highlord. The highlord is stirred to action, yes, but\r\nit is too late for [[Reginald Windsor]] - [[Lady Prestor]] reveals her true\r\nidentity as the broodmother [[Onyxia]], slaying the hero and summoning\r\na good portion of the black dragonflight to wreak havoc.\r\nWindsor's act of defiance has broken Onyxia's hold on Bolvar, though, and\r\nhe makes up for lost time, slaying many of the black dragonflight (with\r\nyour aid), and forcing Onyxia to retreat.\r\n===Act 4: The [[Drakefire Amulet]]===\r\n* '''The Dragon's Eye'''\r\nBreaking [[Bolvar Fordragon|Bolvar]]'s Medallion freed him from [[Onyxia]]'s\r\ncontrol. The amulet also gave him some access to Onyxia's mind, though.\r\nWith the amulet, you could penetrate the defenses around [[Onyxia's Lair]],\r\nand perhaps put an end to her.\r\nBut the medallion is shattered, and must be mended if that is to be attempted.\r\nWhile he can't direct you to anyone specific, he can tell you that another\r\nof dragonkind might be able to help you rekindle its powers.\r\nYou search the world, and after much travail, find yourself in\r\n[[Winterspring]], in the presence\r\nof the Matron Protectorate of the [[Blue Dragonflight]], [[Haleh]].\r\n* '''Drakefire Amulet'''\r\n[[Haleh]] tells you that the amulet is one of Onyxia's scales, enchanted and\r\ntransformed. Useless now, she says, but repairable. To repair it, you have\r\nto get the blood of a black dragon champion. Haleh directs you to\r\none - [[General Drakkisath]], ruler of the dragonspawn army of [[Nefarian]].\r\nYou gather an army, and assault [[Blackrock Spire]], beating back the best\r\nthe black dragonflight can throw at you. You defeat [[Rend Blackhand]] and\r\nhis mount [[Gyth]], and the [[Chromatic Dragonflight]] that Gyth is part of.\r\nAnd finally, you face and slay the black dragonflight's general himself.\r\nYou return to Haleh with a vial of his blood, and watch while she repairs\r\nthe amulet, restoring its enchantment and effectiveness against Onyxia's\r\nwards.\r\nAs you leave with the amulet, she wishes you good luck on behalf of\r\nthe [[Blue Dragonflight]].\r\n==Rewards==\r\nThis permits entry into [[Onyxia's Lair]]. Don't lose it!\r\nReputation awards from this chain:\r\n* about 1085 [[Darnassus]]\r\n* 2850 [[Stormwind]]\r\n* about 685 with other [[Alliance]] factions\r\n==Notes==\r\nTypically this chain requires several trips into dungeons, and at least one raid...\r\n# BRD - to complete Marshal Windsor.\r\n# BRD - to acquire the crumpled note. With luck, combine this run with Jail Break!. Otherwise, a third [[BRD]] run\r\n# UBRS - presuming someone has access to a key to [[UBRS]], a raid to get the blood.\r\n==Summary==\r\n</noinclude>\r\n</noinclude>",},
			["The Great Ossuary"] = { content = "#redirect [[Great Ossuary]]", redirect = "Great Ossuary",},
			["The Great Silver Deceiver"] = { content = "This quest is part of the quest chain, which allows [[blacksmith]]s to specialize in [[Armorsmithing]].\r\n==Objectives==\r\nBring forty [[Mithril Bar]]s and five [[Truesilver Bar]]s to [[Galvan the Ancient]] in [[Stranglethorn]].\r\n* Mithril Bar (40)\r\n* Truesilver Bar (5)\r\n==Quest text==\r\nIt is said that truesilver is stronger and more durable than mithril. Galvan\r\ndoes not disagree with this assessment of the minerals, but contrary to its\r\nname, truesilver is not true! Mithril is a far nobler mineral! HAH!\r\nRegardless, for this lesson you will need to find the great silver\r\ndeceiver, <name>.\r\nBring me forty bars of [[Mithril Bar|mithril]] and five bars of\r\n[[Truesilver Bar|truesilver]]. In exchange, you will be taught\r\nthe secret of [[Ornate Mithril Gloves|ornate mithril gloves]] and more\r\nimportantly, learn that truesilver is a liar!\r\n==Reward==\r\n*3900 experience (or a 33 silver compensation at level 70)\r\n*Plans: Ornate Mithril Gloves\r\n==Notes==\r\nThis quest is part of the [[Mithril Order]] series of quests taken by [[Blacksmithing|Blacksmiths]] to become an Armorsmith.",},
			["The Green Belt"] = { content = "#REDIRECT [[Green Belt]]", redirect = "Green Belt",},
			["The Green Hills of Stranglethorn"] = { content = ":''Were you looking for information about the [[quest]] The Green Hills of Stranglethorn?''\r\n----\r\n'''The Green Hills of Stranglethorn''' can be found in [[Nagrand]]. \r\n==See also==\r\n* The Green Hills of Stranglethorn",},
			["The Greymane Wall"] = { content = "#REDIRECT [[Greymane Wall]]", redirect = "Greymane Wall",},
			["The Grim Guzzler"] = { content = "#REDIRECT [[Grim Guzzler]]", redirect = "Grim Guzzler",},
			["The Grinding Quarry"] = { content = "#REDIRECT [[Grinding Quarry]]", redirect = "Grinding Quarry",},
			["The Grizzled Den"] = { content = "#REDIRECT [[Grizzled Den]]", redirect = "Grizzled Den",},
			["The Guardian"] = { content = "'''The Guardian''' (of [[Frostmourne]]) was a [[revenant]] who warned [[Arthas]] to not draw the sword from the pedestal, but Arthas did regardless of the dire warning. \r\nAs the sword had been intentionally left for Arthas to find, and the elemental forces probably cared little for what happened to Lordaeron, the Guardian's motives are unknown. The Guardian, like all other revenants, has some sort of resistance to the Lich King's control over all undead, most likely explaining why he tried to warn Arthas instead of encourage him. Possibly, the Guardian saw the future Arthas would bring as the lich king and tried to prevent it.\r\n==Quotes==\r\n(Before fighting Arthas)\r\nThe Guardian: ''Turn back, mortals. Death and darkness are all that await you in this forsaken vault.''\r\n(After being defeated)\r\nThe Guardian: ''Turn away... before it's... too late.''\r\nArthas: ''Still trying to protect the sword, are you?''\r\nThe Guardian: ''No... trying to protect you... from it''.",},
			["The Guardians of Tirisfal"] = { content = "'''\"The Guardians of Tirisfal\"''' is a section of the [[History of Warcraft]], Chapter II. It is set 2,700 years before ''[[Warcraft: Orcs & Humans]]''.\r\nFound at:\r\n*[[Stormwind Keep]] in [[Stormwind City]]\r\n*[[Sunreaver's Sanctuary]] in [[Dalaran]] \r\n* The Guardian's Library in [[Karazhan]]\r\nTimeline:\r\n* ← Previous book: [[Arathor and the Troll Wars]]\r\n* → Next book: [[Ironforge - the Awakening of the Dwarves]]",},
			["The Hall of Lights"] = { content = "#redirect [[Hall of Lights]]", redirect = "Hall of Lights",},
			["The Hand of Gul'dan"] = { content = "#redirect [[Hand of Gul'dan]]", redirect = "Hand of Gul'dan",},
			["The Hand of Rastakhan"] = { content = "==Prerequisites==\r\nMust have completed [[Quest:Confront Yeh'kinya|Confront Yeh'kinya]].\r\n==Objectives==\r\nSpeak with Molthor in Stranglethorn.\r\n==Quest Text==\r\n<name>, our worst fears have come. Legend speaks of the Soulflayer ruling the ancient troll world through evil and terror, and his power was absolute. If he cannot be stopped now, then his new reign may spread across all of Azeroth!\r\nThere is a contingent of Zandalarian trolls who may help us stem this tide of darkness. They have camped on Yojamba Isle, off the coast of Stranglethorn, west of the ruins of Zul'Kunda. Speak with their leader, Molthor, and pray he knows how to defeat Hakkar.\r\n==Details==\r\n[[Molthor]] is located in [[Yojamba Isle]], [[Stranglethorn Vale]].\r\n==Reward==\r\nNone.\r\n==Quest Progression==\r\n*Screecher Spirits\r\n**The Prophecy of Mosh'aru\r\n**The Ancient Egg\r\n**The God Hakkar\r\n**The Lost Tablets of Mosh'aru\r\n**The Final Tablets\r\n***Confront Yeh'kinya\r\n***The Hand of Rastakhan\r\n==Additional Notes==\r\nNone.",},
			["The Hand of Vengeance"] = { content = "#REDIRECT [[Hand of Vengeance]]", redirect = "Hand of Vengeance",},
			["The Harborage"] = { content = "#redirect [[Harborage]]", redirect = "Harborage",},
			["The Hawk's Essence"] = { content = "==Objectives==\r\nDefeat the Guardian of the Hawk and bring the Essence of the Hawk to Arthorn Windsong at the Evergrove.\r\n*Essence of the Hawk\r\n*Arthorn's Sparrowhawk Whistle (Provided)\r\n==Description==\r\n<Arthorn's voice addresses you.>\r\nThe last, and strongest, of the spirits spoken of in the Book of the Raven is that of the hawk. It was imprisoned far from Skettis, in a shrine on a remote island southeast of Auchindoun.\r\nI believe this description best matches the island we know as [[Sorrow Wing Point]].\r\nThe tablet describes the hawk's guardian as nearly invulnerable to the bird's claws. Forsake physical attacks and call down the fury of the stars to defeat this foe. Do not repeat the hawk's mistake.\r\n==Progress==\r\nDid you overcome the hawk's guardian and win its essence?\r\n==Completion==\r\nNow that we have all the essences, Morthis Whisperwing must find a way to combine them into an amulet that you'll be able to use to challenge the raven god, draw him out of the Emerald Dream and defeat him. I'll be sending him my notes on the spirits with the hope that he'll realize the value of my insight.\r\nEach of the spirits has blessed a charm I've prepared for you.\r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*150 [[reputation]] with [[Cenarion Expedition]]",},
			["The Headland"] = { content = "#REDIRECT [[Headland]]", redirect = "Headland",},
			["The Headless Horseman"] = { content = "#REDIRECT [[Headless Horseman]]", redirect = "Headless Horseman",},
			["The Head of the High General"] = { content = "==Source==\r\nThis item drops from [[High General Abbendis (female)|High General Abbendis]] in [[New Hearthglen]], [[Dragonblight]].\r\n==The Head of the High General as a quest objective==\r\nThis item is an objective of My Old Enemy and Do Unto Others.",},
			["The Heap"] = { content = "#redirect [[Heap]]", redirect = "Heap",},
			["The Heart of Hakkar"] = { content = "To get this quest you first have to kill [[Hakkar the Soulflayer]] in [[Zul'Gurub]] and retrieve the Heart of Hakkar.\r\n==Objectives==\r\nBring the Heart of Hakkar to [[Molthor]] on [[Yojamba Isle]].\r\n* Heart of Hakkar (provided)\r\n==Description==\r\nThe Heart of Hakkar burns from within. Although the Soulflayer is defeated, the kernel of his power yet remains in this cursed organ.\r\n==Completion==\r\nAh, the Heart of Hakkar. So the Soulflayer has been slain! Our world is saved!\r\n<name>, your service to us cannot be overstated. You truly are a hero of this realm!",},
			["The Heart of Searinox"] = { content = "The still beating heart of [[Searinox]] can be used to imbue an Orb with the fiery powers of a Dragon.\r\n==Source==\r\nThis item is found in [[Blackrock & Roll]], the second chapter of the [[Human]] campaign in [[Warcraft III: Reign of Chaos]]. It is used in the quest Searinox.",},
			["The Hidden Grove"] = { content = "#REDIRECT [[Hidden Grove]]", redirect = "Hidden Grove",},
			["The Hidden Reef"] = { content = "#redirect [[Hidden Reef]]", redirect = "Hidden Reef",},
			["The High Path"] = { content = "#redirect [[High Path]]", redirect = "High Path",},
			["The High Seat"] = { content = "#REDIRECT [[High Seat]]", redirect = "High Seat",},
			["The Hinterlands"] = { content = "#REDIRECT [[Hinterlands]]", redirect = "Hinterlands",},
			["The History of Orcish Ascension"] = { content = "#REDIRECT [[Warcraft_II:_Tides_of_Darkness_manual]]", redirect = "Warcraft_II:_Tides_of_Darkness_manual",},
			["The Hoard"] = { content = "#redirect [[Hoard]]", redirect = "Hoard",},
			["The Horde's Hellscream"] = { content = "''The Horde's Hellscream'' is an in-game [[book]] given as a quest reward during the [[Harvest Festival]], found at Javnir Nashak, outside [[Orgrimmar]] in [[Durotar]].\r\n==Source==\r\nRewarded from the quest Honoring a Hero (Horde).",},
			["The Horde Art Card Set"] = { content = "Let these pieces of art stand as a testament to the glory of the [[Horde]], so that future generation may learn from our deeds.\r\nThe set includes:\r\n*35 different 8\"x10\" art cards displaying art from the World of Warcraft Trading Card Game\r\n*Images by Dan Scott, Justin Sweet, Todd Lockwood, Jonboy Meyers, Samwise and other top artists.\r\n*An exclusive game-playable foil version of Katsin Bloodoath.\r\n*A 1000 point value UDE Rewards card. Use these points to get enhancements for your online game or other exclusive prizes.",},
			["The Horde Needs More Mithril Bars!"] = { content = "==Objectives==\r\nYup, I be glad you're here, mon. You helped me before, and now I need your help again. We still lookin' ta bring in more mithril bars for the war effort; gonna build lots of armor and weapons and things to go squish them bugs at Ahn'Qiraj.\r\nSo if you be a true friend, you bring me back more stacks of mithril bars. I take all you got until we hit our quota. You have some for me now? \r\n* Mithril Bar (20)\r\n== Completion==\r\nThat be good work <name>! Another twenty bars get us that much closer to the goal, and get us more war materiel. I see to it they get put away. And if you get another stack of mithril bars mon, you make sure to be bringin' them here to me. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*0 [[XP]]",},
			["The Horde Needs More Tin Bars!"] = { content = "==Objectives==\r\nBring 20 tin bars to [[Grunt Maug]] in [[Durotar]]. \r\n* Tin Bar (20)\r\n== Description==\r\nVery good, I see that you are serious about the war. I'm a little edgy waiting for it to start though, which means I'm going to get angry if you don't start bringing in the goods faster. Maybe I can just practice on you instead.\r\nHar! Maybe not, 'cuz then who would bring me back the tin bars? \r\n== Progress==\r\nVery good, I see that you are serious about the war. I'm a little edgy waiting for it to start though, as I'm sure you are as well, <class>. It will be glorious when it begins. The [[Horde]] running over the sands of the [[Silithus]] desert, weapons in hand, charging headlong into the insect masses. Great honor will be had that day by all!\r\nHar! But first we need more tin bars. Funny how such a small thing may make such a huge difference, don't you think? \r\n== Completion==\r\nThrom'ka, <name>. You honor me and the [[Horde]] with your tin bars. I will put them on the stack and then they will come and make things from them. And then when that is all done we will go to war and show the puny [[Alliance]] how to fight the bugs.\r\nNow bring me back more tin bars! \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*0 [[XP]]",},
			["The Horde Needs Tin Bars!"] = { content = "==Objectives==\r\nBring 20 Tin Bars to [[Grunt Maug]] at the Valley of Spirits in [[Orgrimmar]]. \r\n* Tin Bar (20)\r\n== Description==\r\nLok'tar, <race>, I'm sure you already know that we're going to war at Ahn'Qiraj with the insects. But first the Warchief has decided that we're going to do something called 'prepare'. Though I'd rather be sharpening weapons and hammering armor into shape, I'm proud to have been chosen to be in charge of tin bar collection here. But I cannot do that without your help.\r\nSo I need you to go out and make tin bars and bring them back to me here. I think I'm going to need more than I can count. \r\n== Progress==\r\nHow many tin bars do you have there, <class>? After the war I think I'm going to need someone to teach me how to count. \r\n== Completion==\r\nWell, I guess that looks like the right number of tin bars. Don't try to fool me, <class>! Counting makes my skull hurt. Now I go and put these bars on the stack and you go out and bring me back more of the same. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*0 [[XP]]",},
			["The Horrors of Pollution"] = { content = "==Objectives==\r\nTake the [[Vial of Void Horror Ooze]] to [[Researcher Navuud]] at the Protectorate Watch Post in [[Netherstorm]]. \r\n*Vial of Void Horror Ooze (Provided)\r\n== Description==\r\nYou carefully fill a vial with the fallen void horror's ooze.\r\nResearcher Navuud at the Protectorate Watch Post would be quite interested in such a find! Take it to him at once! \r\n== Reward==\r\nYou will also receive:8 gold 80 silver copper \r\n== Progress==\r\nHrm, you look a bit dirty... What have you gotten yourself into? \r\n== Completion==\r\nWHAT!? You faced off against a void horror? And lived?! Incredible!\r\nThis sample is worth its weight in gold. A find like this deserves a reward. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*15800 [[XP]] (or 9 gold 48 silver copper at level 70)\r\n*250 [[reputation]] with [[The Consortium]]",},
			["The House of the Arcane Contraption"] = { content = "#REDIRECT [[House of the Arcane Contraption]]", redirect = "House of the Arcane Contraption",},
			["The Howling Vale"] = { content = "#REDIRECT [[Howling Vale]]", redirect = "Howling Vale",},
			["The Hungering Cold"] = { content = "'''The Hungering Cold''' is a tanking one-handed [[sword]] and also a great offhander for rogues. Fury warriors benefit from this item as well, as its fast speed makes them generate rage significantly faster than they would have with a slow weapon such as [[Gressil, Dawn of Ruin]]. \r\n==Source==\r\nThis item drops from [[Kel'Thuzad (tactics)| Kel'Thuzad]] in [[Naxxramas]].\r\n==Notes==\r\nThe Hungering Cold was used in the South Park Episode \"[[wikipedia:Make Love, Not Warcraft|Make Love, Not Warcraft]]\", where it was named The Sword of a Thousand Truths in where Stan's dad had to deliver it to Stan in order to defeat \"That which has no life,\" (implying that a person mush have absolutely no social life to obtain a high level) However, The [[Sword of a Thousand Truths (South Park)|Sword of a Thousand Truths]] is designed to cast a massive Mana Burn, draining an enemy's entire mana pool.",},
			["The Hunter and the Prince"] = { content = "==Objectives==\r\n[[Matthias Lehner]] in the [[Court of Bones]] wants you to look for a [[Bloodstained Stone]] and complete the Prince's Destiny.\r\n* The Prince's Destiny\r\n==Description==\r\nBefore the prince became a king, he fought many battles... but only where he came close to dying.\r\nIt was fought right here. After you let me show you what happened, you'll understand everything.\r\nFind a bloodstained stone and pick it up from the floor. You'll see what happened. \r\n==Progress==\r\nDid you see, <name>? Did you?\r\n==Completion==\r\nAfter that fight, the prince realized what was holding him back was that he was still human... he could still feel... he could still bleed. He still had a heart.\r\nThe first thing he did when he became king was to rid himself of it. He threw it down the pit where we first met. And you, <name>, were the first person to touch it since.\r\n==Notes==\r\nLook for the stone at , just west of the quest giver.\r\nWhen touching the stone the player becomes Arthas again with a different set of abilities. This time, it's a one on one with [[Illidan]]; the same duel seen after the Warcraft III mission [[A Symphony of Frost and Flame]].\r\nArthas has four abilities; #1 will make Arthas parry Illidan's next attack, giving him mana, as he starts with none. #2 will heroic strike for a mediocre amount of damage, #3 will knock Illidan back, giving Arthas the range he requires to use #4, a heroic leap attack that deals a substantial amount of damage to Illidan.\r\nParry until Arthas has enough mana to knock back and immediately follow up with heroic leap attack. Do that about 4 or 5 times to defeat Illidan and complete the quest.",},
			["The Hushed Bank"] = { content = "#REDIRECT [[Hushed Bank]]", redirect = "Hushed Bank",},
			["The Immovable Object"] = { content = "'''The Immovable Object''' is an epic-quality shield obtained from the [[Stormpike Guard]] faction, or the [[Frostwolf Clan]]. It is the counter to [[The Unstoppable Force]].\r\n==Vendors==\r\n '''Alliance'''\r\n*[[Gaelden Hammersmith]] in [[Alterac Valley]]\r\n*[[Thanthaldis Snowgleam]] in the [[Alterac Mountains]]\r\n '''Horde'''\r\n*[[Grunnda Wolfheart]] in [[Alterac Valley]]\r\n*[[Jekyll Flandring]] in [[Alterac Mountains]]\r\n==Notes==\r\n*The cost is - 7000 [[Honor]] - 25x [[Alterac Valley Mark of Honor]]\r\n*The 'object' resembles a carcass of an insect, perhaps a [[Silithid]].",},
			["The Imperial Seat"] = { content = "#redirect [[Imperial Seat]]", redirect = "Imperial Seat",},
			["The Infectis Scar"] = { content = "#REDIRECT [[Infectis Scar]]", redirect = "Infectis Scar",},
			["The Instigator's Enchantment"] = { content = "==Pre-Requisites==\r\n==Task==\r\n'''Bring the following to [[Falrin Treeshaper]] inside [[Dire Maul]]: 1 [[Jeering Spectre's Essence]], 4 [[Dark Rune]]s and 8 [[Large Brilliant Shard]]s.'''\r\n''I can place the enchantment you require on the banner quite easily, <name>. Unfortunately I don't have the materials I need as it is very rarely that someone asks for this sort of charm.''\r\n''I will require the essence of one of the Eldreth ghosts that haunt these halls, a handful of Scholomance dark runes and some large brilliant shards. Bring me these reagents and I shall perform this task for you.''\r\n==Quest Chain==\r\n*[[Quest:In Search of Anthion|In Search of Anthion]]: [[Quest:In Search of Anthion (Alliance)|Alliance]]/[[Quest:In Search of Anthion (Horde)|Horde]]\r\n**[[Quest:Dead Man's Plea|Dead Man's Plea]]\r\n**[[Quest:Proof of Life|Proof of Life]]\r\n**[[Quest:Anthion's Strange Request|Anthion's Strange Request]]\r\n**[[Quest:Anthion's Old Friend|Anthion's Old Friend]]\r\n**[[Quest:Falrin's Vendetta|Falrin's Vendetta]]\r\n***'''The Instigator's Enchantment'''\r\n***[[Quest:The Challenge|The Challenge]]\r\n***Anthion's Parting Words: [[Quest:Anthion's Parting Words (Alliance)|Alliance]]/[[Quest:Anthion's Parting Words (Horde)|Horde]]\r\n==Notes==\r\n*This is the seventh step in the quest chain to upgrade your [[Dungeon Set 1]] Boots, Shoulders, and Pants into [[Dungeon Set 2]].\r\n*The Jeering Spectre's Essence can be taken from the Eldreth ghosts (Spectres, Spirits, Seethers, Phantasms, Sorcerers, and Apparitions) in Dire Maul West.\r\n*Dark Runes can drop off enemies in [[Scholomance]].\r\n*Large Brilliant Shards can be found by [[disenchanting]] level 51-60 blue/rare items. You can also buy them in the [[Auction House]].\r\n----\r\nGo to [[Quests]]",},
			["The Invasion of Draenor"] = { content = "'''\"The Invasion of Draenor\"''' is a section of the [[History of Warcraft]], Chapter IV. It is recounts the events of ''[[Warcraft II: Beyond the Dark Portal]]''.\r\nFound at:\r\n* [[Scholomance]] - room before Viewing Room\r\nTimeline: \r\n* ← Previous book: [[The Alliance of Lordaeron]]\r\n* → Next book: [[The Birth of the Lich King]]",},
			["The Iron Eagle"] = { content = "'''''The Iron Eagle''''' is a [[zeppelin]], with a goblin crew and orc guards, whivh runs between the tower located outside of [[Orgrimmar]] in [[Durotar]] and within [[Grom'gol Base Camp]] in [[Stranglethorn Vale]]. The Captain claims it used to be a warship \"whose mere sight make armies rout\" but the crew remains doubtful of this fact.\r\n==Crew==\r\n* [[Sky-Captain Bomblast]]\r\n* [[Chief Officer Brassbolt]]\r\n* [[Navigator Sparksizzle]]\r\n* [[Grunt Umgor]]\r\n* [[Grunt Ounda]]\r\n* [[Crewman Crosswire]]\r\n* [[Crewman Fastwrench]]\r\n* [[Crewman Gazzlegear]]\r\n* [[Snack-O-Matic IV]]\r\n* [[Vendo-O-Tron D-Luxe]]\r\n==Inspiration==\r\nThe name might be a reference to the Iron Eagle films, a ''Top Gun'' ripoff usually containing unrealistic air combat.",},
			["The Island of Doctor Lapidis"] = { content = "#REDIRECT [[Island of Doctor Lapidis]]", redirect = "Island of Doctor Lapidis",},
			["The Ivar Patch"] = { content = "#REDIRECT [[Ivar Patch]]", redirect = "Ivar Patch",},
			["The Jade Eye"] = { content = "'''The Jade Eye''' is a mid-level [[uncommon]] ring designed for tanking. It would best be used by [[Warrior]]s, though the stamina would still get good use by a [[feral]] [[Druid]].\r\n==Source==\r\nThis item is crafted by [[jewelcrafter]]s with a skill level of 170. The components are:\r\n* 1 Jade\r\n* 2 Elemental Earth\r\nDesign: The Jade Eye is sold in limited quantity by [[Arred]] in [[Exodar]] or [[Burbik Gearspanner]] in [[Ironforge]] for [[Alliance]] players and by [[Gelanthis]] in [[Silvermoon City]] or [[Felicia Doan]] in [[Undercity]] for [[Horde]] players.",},
			["The Jansen Stead"] = { content = "#REDIRECT [[Jansen Stead]]", redirect = "Jansen Stead",},
			["The Kaldorei and the Well of Eternity"] = { content = "#Redirect [[Well of Eternity]]", redirect = "Well of Eternity",},
			["The Kalu'ak"] = { content = "#redirect [[Kalu'ak]]", redirect = "Kalu'ak",},
			["The Keeper's Favor"] = { content = "==Objectives==\r\n[[Highlord Tirion Fordring]] at [[Crusaders' Pinnacle]] has requested that you secure passage from [[Arch Druid Lilliandra]] and speak to [[Keeper Remulos]] in [[Moonglade]]. \r\n==Description==\r\nThere are those of this world that tap into power unrestricted by the bounds of our mortal frames - powers of restoration, powers of life, and powers of light. And [[Crusader Bridenbrad|Bridenbrad]], this is no ordinary man... his valor and devotion shine through. We can only hope that one of these beings will intervene and bring this hero back from a fate worse than death.\r\nGo now and speak to Archdruid Lilliandris in the [[Argent Vanguard]]... request passage to Moonglade and seek the aid of Keeper Remulos. \r\n==Completion==\r\nHello child.\r\nI understand Tirion's request and trust in his judgment, we will see what we can do for this Crusader Bidenbrad. What you ask is no simple task - the [[scourge]] are not of this world, and many have failed in attempting to strip their corruption over the years.\r\nIn a being of nobility and light, all is not without hope.\r\n==Notes==\r\nArchdruid Lilliandra can be found in the Vanguard Infirmary at .\r\nIt's always a pleasure to meet heroes such as yourself in this forsaken land. Is there some form of assistance that I can offer you?\r\n ''It's a pleasure to meet you as well, [[Arch Druid]]. I'm on a task from Tirion and time is short, might I trouble you for a portal to Moonglade?''\r\nOf course! Go with Elune's blessing.\r\nSimply walk into the green portal.",},
			["The Keystone"] = { content = "'''The Keystone''' is a quest item.\r\n==Source==\r\nThis item drops from [[Commander Sarannis]] in [[Botanica|The Botanica]] of [[Tempest Keep]].\r\n==As a quest objective==\r\nCapturing the Keystone",},
			["The Killing Time"] = { content = "==Objectives==\r\nUse the Portal to the Undercity inside [[Stormwind Keep]] to teleport to the [[Undercity]]. Report to [[Broll Bearmantle]] when you arrive at your destination. \r\n==Description==\r\nI sent Broll and [[Valeera Sanguinar|Valeera]] to the Undercity before you left for [[Orgrimmar]]. In fact, they're now stationed outside the sewer entrance to the ruins, awaiting orders.\r\n[[Jaina Proudmoore|Lady Proudmoore]] will open a portal to our forces outside the Undercity. Go there and report to Broll. Jaina and I will be close behind. \r\n==Completion==\r\nWho are you supposed to be? [[Varian Wrynn|Varian]] said he'd send heroes.\r\n==Notes==\r\nOutside of the sewer entrance to Undercity is an entire contingent of [[Stormwind Elite]]s, [[Alliance Siege Vehicle]]s and [[Alliance Flying Machine]]s!",},
			["The Kraken"] = { content = "'''The ''Kraken''''' (formerly ''Sword of Wrynn'') is the main sea-going transport that runs between [[Stormwind Harbor]] and the port of [[Valiance Keep]], in the [[Borean Tundra]] of western [[Northrend]]. Unlike other intercontinental sea-based transport, the ''Kraken'' is a steam-powered icebreaker, ideal for traversing the frozen seas of Northrend.\r\n==Crew==\r\n*Captain Constance\r\n*First Mate Fitzgerald\r\n*Navigator Meyer\r\n*Sailor Dawning\r\n*Sailor Phillips\r\n*Sailor Picardo",},
			["The Kurken"] = { content = "'''The Kurken''' is a [[hostile]] level 12 creature that can be found in [[Stillpine Hold]] on [[Azuremyst Isle]]. It is the objective of the quest [[Quest:The Kurken is Lurkin'|The Kurken is Lurkin']].\r\n==Drops == \r\n \r\n0.92% Chance of an [[Uncommon]] drop.\r\n0.73% Chance of a [[common]] drop.\r\n0.73% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.\r\n==Omen==\r\nDue to its identical appearance and close proximity (being in northern Kalimdor), it is possible that The Kurken is related to the demigod [[Omen]] in some way. Though it is possible they simply share the same model.",},
			["The Laboratory"] = { content = "#redirect [[Laboratory]]", redirect = "Laboratory",},
			["The Lady's Necklace"] = { content = "'''The Lady's Necklace''' is a necklace intended to be given by [[Alleria Windrunner]] to her sister, [[Sylvanas Windrunner|Sylvanas]], before Alleria left through the [[Dark Portal]] for the [[Alliance Expedition]] assault on [[Draenor]].[[Vereesa Windrunner]] was given an identical necklace. The three necklaces were once part of a larger one given to Alleria by their parents, which she had melted down and crafted into three lockets in [[Stormwind]]. The emerald she kept for herself, and she gave the ruby and the sapphire to her second, [[Verana]], to deliver to her sisters. \r\nThe Lady's Necklace drops from any of the [[Fallen Ranger]]s and [[Deatholme Acolyte]]s residing in [[Windrunner Spire]]. When you take it to Sylvanas in the [[Undercity]], she will begin singing the [[Lament of the Highborne]].\r\n==Quests==\r\nStarts the quest The Lady's Necklace",},
			["The Lady Mehley"] = { content = "'''''The Lady Mehley''''' is a human crewed [[boat|vessel]] that allows transportation between [[Menethil Harbor]] and [[Theramore]].\r\nAnother ship, ''[[The Bravery]]'', leaves from a different pier in Menethil Harbor.\r\n==Crew==\r\n* [[Captain \"Stash\" Torgoley]]\r\n* [[First Mate Kowalski]]\r\n* [[Navigator Mehran]]\r\n* [[Engineer Combs]]\r\n* [[Galley Chief Grace]]\r\n* [[Marine Anderson]]\r\n* [[Marine Halters]]\r\n* [[Sailor Henders]]\r\n* [[Sailor Vines]]\r\n* [[Sailor Wicks]]\r\n* [[Abe the Cabin Boy]]",},
			["The Lagoon"] = { content = "#redirect [[Lagoon]]", redirect = "Lagoon",},
			["The Largest Panda Ever"] = { content = "'''The Largest Panda Ever''' is an animal which can be encountered in the \"[[Brothers in Blood]]\" mission of Warcraft III. He drops a Necklace of Spell Immunity.\r\n==See also==\r\n* [[Pandaren]]\r\n* [[Panda Cub]]",},
			["The Last Guardian"] = { content = "'''''The Last Guardian''''' is a [[Novels|novel]] by [[Jeff Grubb]] taking place in the [[Warcraft universe]] during the beginning of the [[First War]].\r\nAn [[audiobook]] version read by [[wikipedia:Dick Hill (narrator)|Dick Hill]] was scheduled to be released in April, 2009. \r\n==Back-of-book description==\r\nIn the mist-shrouded haze of the past, long before the beginning of recorded time, there stood the world of [[Azeroth]]. Every kind of magical being strode the countryside among the tribes of man, and all was at peace — until the arrival of the demons and horrors of the [[Burning Legion]] and their baneful Lord [[Sargeras]], dark god of chaotic magic. Now [[Dragon]]s, [[Dwarf|Dwarves]], [[Elf|Elves]], [[Goblin]]s, [[Human]]s, and [[Orc]]s all vie for supremacy across the scattered kingdoms—part of a grand, malevolent scheme that will determine the fate of the world of\r\nWARCRAFT\r\nThe [[Guardians of Tirisfal]]: a line of champions imbued with godlike powers, each one through the ages charged with fighting a lonely secret war against the Burning Legion. [[Medivh]] was fated from birth to become the greatest and most powerful of this noble order. But from the beginning a darkness tainted his soul, corrupting his innocence and turning to evil the powers that should have fought for good. Torn by two destinies, Medivh's struggle against the malice within him became one with the fate of Azeroth itself...and changed the world forever. \r\nTHE LAST GUARDIAN \r\nAn original tale of magic, warfare, and heroism based on the bestselling, award-winning electronic game from [[Blizzard Entertainment]].\r\n==Characters==\r\n==Factions==\r\n*[[Stormwind (kingdom)|Stormwind]]\r\n*[[Black Tooth Grin clan]]\r\n*[[Blackrock clan]]\r\n*[[Bleeding Hollow clan]]\r\n*[[Burning Blade clan]]\r\n*[[Burning Legion]]\r\n*[[Court of Azeroth]]\r\n*[[Fourth Company]]\r\n*[[Fifth Company]]\r\n*[[Old Horde|Horde]]\r\n*[[King's Council]]\r\n*[[Kirin Tor]]\r\n*[[Order of Tirisfal]]\r\n*[[Shadow Council]]\r\n*[[Stormreaver clan]]\r\n*[[Twilight's Hammer|Twilight's Hammer clan]]\r\n==Locations==\r\n*[[Azeroth]]\r\n**[[Alterac Mountains|Alterac]]\r\n**[[Black Morass]]\r\n**[[Morass Road]]\r\n**[[Elwynn Forest]]\r\n**[[Stormwind City]]\r\n**[[Eastern Wall]]\r\n**[[Goldsmith's street]]\r\n**[[Merchant's District Wall]]\r\n**[[Stormwind Keep]]\r\n***[[King's Privy Quarters]]\r\n**[[Lower city (Stormwind)]]\r\n**[[Kalimdor (landmass)|Kalimdor]]\r\n**[[Well of Eternity]]\r\n**[[Karazhan]]\r\n**[[Karazhan Bailey]]\r\n**[[Lower Karazhan]]\r\n**[[Observatory]]\r\n**[[Khaz Modan]]\r\n**[[Ironforge]]\r\n**[[Kul Tiras]]\r\n**[[Lordaeron]]\r\n**[[Dalaran]]\r\n**[[Cross Island]]\r\n***[[Violet Citadel]]\r\n***[[Grand Library]]\r\n**[[Northshire Abbey]]\r\n**[[Quel'Thalas]]\r\n**[[Redridge Mountains]]\r\n**[[Stranglethorn Vale]]\r\n**[[Ulmat Thondr]]\r\n*[[Draenor]]\r\n**[[Hellfire Peninsula]]\r\n**[[Dark Portal]]\r\n*[[Great Dark Beyond]]\r\n*[[Twisting Nether]]\r\n*[[Infinite Abyss]]\r\n==Other==\r\n*[[Circle of Warding]]\r\n*[[Court of Azeroth]]\r\n**[[King's Council]]\r\n*[[Feast of Scribes]]\r\n*[[First Days]]\r\n*[[Gracious Breeze]]\r\n*[[Great Royal Sword]]\r\n*[[Hedge wizard]]\r\n*[[Of Trapes and Lockes]]\r\n*[[The Lineage of Azeroth's Kings]]\r\n*[[The Song of Aegwynn]]\r\n*[[Denbrawn's Treatise on the \"Song of Aegwynn\"]]\r\n*[[Celestial vault]]\r\n*[[Astrolabe]]\r\n*[[Flamewine]]\r\n*[[Golden whistle]]\r\n*[[Falconer]]\r\n**[[Falcon]]\r\n*[[Scholar]]\r\n*[[Emu]]\r\n*[[Farseeing]]\r\n*[[Phosphorescent crystal]]\r\n*[[Vrocka]]\r\n*[[Wain]]\r\n*[[Whirligig]]\r\n*[[Sky-engine]]\r\n*[[Bucket brigade]]",},
			["The Last Guardian (History of Warcraft)"] = { content = ":''[[The Last Guardian]] is also the name of a novel by [[Jeff Grubb]].\r\n'''\"The Last Guardian\"''' is a section of the [[History of Warcraft]], Chapter II. It is set 45 years before ''[[Warcraft: Orcs & Humans]]''.\r\nFound at:\r\n* [[Loch Modan]] and [[Westfall]]\r\n* The Guardian's Library in [[Karazhan]]\r\nTimeline: \r\n* ← Previous book: [[War of the Three Hammers (History of Warcraft)|War of the Three Hammers]]\r\n* → Next book: [[Kil'jaeden and the Shadow Pact]]",},
			["The League of Arathor"] = { content = "#REDIRECT [[League of Arathor]]", redirect = "League of Arathor",},
			["The Left Piece of Lord Valthalak's Amulet"] = { content = "During the quest chain to upgrade the [[Dungeon Set 1]] Helm and Chestpiece to [[Dungeon Set 2]], adventurers will have to complete a quest called '''The Left Piece of Lord Valthalak's Amulet'''. This quest could be one of four quests:\r\n*[[Quest:The Left Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]] - Use the Brazier of Beckoning in Scarlet Stratholem to summon forth [[Jarien and Sothos]] and slay them.\r\n**Preceeding Quest: [[Quest:Components of Importance (Tyr's Hand)|Components of Importance (Tyr's Hand)]]\r\n*[[Quest:The Left Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]] - Use the Brazier of Beckoning in Scholomance to summon forth the spirit of [[Kormok]] and slay him.\r\n**Preceeding Quest: [[Quest:Components of Importance (Purgation Isle)|Components of Importance (Purgation Isle)]]\r\n*[[Quest:The Left Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]] - Use the Brazier of Beckoning in Lower Blackrock Spire to summon forth the spirit of [[Mor Grayhoof]] and slay him.\r\n**Preceeding Quest: [[Quest:Components of Importance (Hive'Regal)|Components of Importance (Hive'Regal)]]\r\n*[[Quest:The Left Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]] - Use the Brazier of Beckoning in Dire Maul to summon forth the spirit of [[Isalien]] and slay her.\r\n**Preceeding Quest: [[Quest:Components of Importance (Frostwhisper Gorge)|Components of Importance (Frostwhisper Gorge)]]",},
			["The Legend of Stalvan"] = { content = "'''The Legend of Stalvan''' is a book provided and an objective of the quest [[The Fate of Stalvan Mistmantle]].",},
			["The Legion Front"] = { content = "#REDIRECT [[Legion Front]]", redirect = "Legion Front",},
			["The Library"] = { content = "#REDIRECT [[Library (Ironforge)]]", redirect = "Library (Ironforge)",},
			["The Lich, Ras Frostwhisper"] = { content = "The Lich, Ras Frostwhisper is the 6th quest in the '''The Human, Ras Frostwhisper''' quest chain.\r\n==Objectives==\r\nFind Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.\r\n* Human Head of Ras Frostwhisper\r\nProvided Item:\r\n* Soulbound Keepsake\r\n==Description==\r\nThere is but one task remaining, <name>. Confront the lich, [[Ras Frostwhisper]], in his lair.\r\nUse the power of the keepsake against the beast - be unrelenting in your actions! Weather the blows that the flailing beast will surely bring down upon you. Do not give in to the pain!\r\nWhen the ritual is complete, Ras will be mortal once more. It is at that point that he must be slain. Strike him down and take his human head.\r\n==Progress==\r\nYou carry the burden of ten thousand restless souls, <name>.\r\n==Completion==\r\nTen thousand souls cry out in unison, <name>! You have struck a mortal blow to the Scourge and their masters.\r\n==Rewards==\r\n \r\n \r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*7950 [[XP]] (or s=87 gold at level 70)\r\n==Quest chain==\r\n#The Human, Ras Frostwhisper\r\n#The Dying, Ras Frostwhisper\r\n#Menethil's Gift\r\n#Menethil's Gift (2)\r\n#Soulbound Keepsake\r\n#The Lich, Ras Frostwhisper",},
			["The Lich King's Command"] = { content = "==Objectives==\r\nReport to [[Scourge Commander Thalanor]] at [[Browman Mill]].\r\n==Description==\r\nThe Scarlet Enclave is no more. What remains of the [[Scarlet Crusade|Crusade]] will be dealt with in [[Northrend]].\r\nWe now turn all of our efforts to [[Light's Hope Chapel]]. No longer will this affront to your master be allowed to exist!\r\nI have issued my final command. Highlord Mograine awaits your arrival at the edge of Browman Mill. Go northwest, through the cave, into the [[Noxious Glade]] and take the path leading out of the glade to the mill.\r\nDo not fail me, <name>.\r\n==Completion==\r\nWe will crush the [[Argent Dawn]] just as we crushed the Scarlet Crusade.",},
			["The Lich King"] = { content = "#redirect [[Lich King]]", redirect = "Lich King",},
			["The Lich King Triumphant"] = { content = "'''\"The Lich King Triumphant\"''' is a section of the [[History of Warcraft]], Chapter V. It recounts events of the undead campaign of ''[[Warcraft III: The Frozen Throne]]''.\r\nFound at:\r\n* Reliquary of [[Scholomance]] in the [[Western Plaguelands]]\r\n* The Scarlet Bastion (live side) of [[Stratholme]]\r\nTimeline: \r\n* ← Previous book: [[Civil War in the Plaguelands]]\r\n* → Next book: [[Old Hatreds - The Colonization of Kalimdor]]",},
			["The Lifewarden's Wrath"] = { content = "==Objectives==\r\nThe [[Avatar of Freya]] at the [[Rainspeaker Rapids]] wants you to use Freya's Horn atop of the [[Glimmering Pillar]].\r\n* The Lifewarden's Wrath\r\nProvided Item:\r\n* Freya's Horn\r\n==Description==\r\nWe were not quick enough, <name>. The cultist scum have arrived at the [[Glimmering Pillar]] and are making preparations to destroy it, I can sense them.\r\nWe don't have much time. Blow upon this horn atop the Glimmering Pillar to channel my power through the crystal.\r\nWe shall show this scum to not trifle with the titan's creations. \r\n==Rewards==\r\nYou will receive: 5 gold 10 silver \r\n==Progress==\r\nHave you taken care of the cultists, <name>?\r\n==Completion==\r\nImpressive. I wasn't expecting a mere mortal to prove as worthy an ally as you.\r\nI fear our efforts have not been sufficient, however. The Scourge shows no signs of stopping.\r\n==Notes==\r\nBlowing the horn makes the floating device above the pillar to activate, sending energy beams to destroy the cultists.",},
			["The Lightning Capacitor"] = { content = "'''The Lightning Capacitor''' is an epic trinket for DPS casters. As its Equip: ability implies, it is crit-based and thus might be priorized to [[Mages]], [[Elemental]] [[Shamans]], [[Balance]] [[Druids]] and [[Destruction]] [[Warlocks]]. For some [[classes]] and [[spec]]s it is said to be the most powerful [[trinket]] in the game. \r\n==Source==\r\nThis item drops from [[Terestian Illhoof]] in [[Karazhan]] with an estimated drop rate of 7% - 13% (Armory: Low (15% -24%)).\r\n==Mechanic==\r\nThe way, this trinket works is quite complicated and on most sites fairly misunderstood. First of all, the bolt emitted by this trinket is '''not''' affected by +[[spell damage]] anymore (since [[Patch 2.1]]), it can however crit/be resisted and is affected by the characters [[Nature]] spell crit and hit chance, and any nature damage vulnerability debuffs (such as [[Stormstrike]]). The crits of the bolt do not produce a charge, but any spell-like critical hit inflicted by your character will produce a charge, e. g. [[Molten Armor]], [[Lightning Shield]], etc. and of course single target direct damaging spells and AoE spells.\r\nThe tooltip is somewhat misleading regarding the 2.5 second internal cooldown. Electrical charges CAN be gained on every critical strike except for the first 2.5 seconds after a bolt goes off. This means it's possible to get 3 crits at once (for example, from an AoE spell hitting multiple targets) and fire off a single bolt. However, any further crits will not produce charges until after 2.5 seconds. This effectively limits the bolts to one per 2.5 seconds. '''A more correct tooltip might read: \"Electrical Charge cannot be gained for 2.5 seconds ''after a Lightning Bolt is fired.'''''\"\r\nThe effect of this trinket is badly expressed as +[[Formulas:Plus damage and Plus healing|Spell damage]], but rather as a flat crit-damage bonus and can easily be calculated as [[dps]]-gain, as the calculations below will demonstrate.\r\nBecause it is direct [[nature]] damage it can be partially resisted, but this is not considered in the following calculations, as most PvE encounters are either completely nature immune or do not have noticeable resistances at all. These calculations refer to single target direct damage casting. The italic lines are examples with 30% [[nature]] crit, 94% hit chance and [[Scorch]] spamming (34% scorch crit, same hit, 1.5s casting time). It has to be noted, that [[Arcane Missiles]] have to be considered as 1s casting time, as every missile can crit and thus produce a charge, 5 missiles in 5 sec is 1 missile / sec.\r\nTerms used:\r\n-hit(n): [[Spell hit|hit chance]] against the current target with nature spells as factor (e. g. 0.83 as 83%)\r\n-hit(m): [[Spell hit|hit chance]] against the current target with your main spell school as factor\r\n-crit(n): [[Spell critical strike|crit chance]] with nature spells as factor\r\n-crit(m): [[Spell critical strike|crit chance]] with your main spell school as factor\r\n-crit(b): The critical damage bonus as factor, e. g. 0.5 for normal crits, 1.1 for [[ignite]] crits as a fire mage.\r\n-cast(t): time to cast your spell in seconds\r\nThe average bolt damage would be:\r\n( ( 694 + 806 ) / 2 * ( 1 + crit(n) * crit(b) ) ) * hit(n) = Bolt(d)\r\n''( ( 694 + 806 ) / 2 * ( 1 + 0.3 * 0.5 ) ) * 0.94 = 810.75''\r\n1/3 to Bolt(d) is a flat addition to your crit damage. ''270.25''\r\nThe average time it takes to produce 3 crits with your main spell school and consequently producing a bolt is:\r\nhit(m) * (cast(t) / crit(m)) * 3\r\n''(1.5 / 0.34) * 0.94 * 3 = 12.44''\r\nNote: Due to the internal cooldown the minimal time between two bolts is limited to 2.5 seconds. The subsequent effect, that a crit right after an emitted bolt is not counted for a charge is definitely affecting the damage output, but is quite difficult to calculate.\r\nThe [[dps]]-gain is now easily calculated by:\r\nBolt(d) / Bolt(t) = Bolt(dps)\r\n''810.75 / 12.44 = 65.17''\r\nYou can now calculate yourself, how much bare +[[Formulas:Plus damage and Plus healing|Spell damage]] you would need with your main spell(rotation) to gain an equivalent [[dps]] boost. For [[Scorch]] it would be 153 with the given hit/crit chance, as the following calculation states (assuming 800 [[Formulas:Plus damage and Plus healing|Spell damage]] and fully stacked [[Improved Scorch|Fire Vulnerability]]):\r\n( ( 305 + 361 ) / 2 + 800 * 1.5 / 3.5 ) * ( 1 + 0.34 * 1.1 ) * 0.94 * 1.15 / 1.5 = [[Scorch]]([[dps]]) = 669.231039428571\r\nIt has to be noted, that there are several talents and multiplicators missing in this calculation; they are left out for simplicity and because these calculations are exemplarious, they differ largely for every class and spec. An important corollary of this however, is that +damage will have a much larger effect than that given here.\r\nNow the same with [[Scorch]]([[dps]])', which is the result above plus the [[dps]] gained from [[The Lightning Capacitor]] and resolved to the unknown amount of [[Formulas:Plus damage and Plus healing|Spell damage]] (x):\r\n[[Scorch]]([[dps]])'= 669.231 + 65.17\r\n( ( 305 + 361 ) / 2 + '''x''' * 1.5 / 3.5 ) * ( 1 + 0.34 * 1.1 ) * 0.94 * 1.15 / 1.5 = 734.401\r\n( 333 + '''x''' * 0.4286 ) * ( 1 + 0.34 * 1.1 ) * 0.94 * 1.15 / 1.5 = 734.401\r\n( 333 + '''x''' * 0.4286 ) * 1.374 * 0.94 * 1.15 / 1.5 = 734.401\r\n( 333 + '''x''' * 0.4286 ) * 0.990196 = 734.401\r\n329.735268 + '''x''' * 0.4243980056 = 734.401\r\n'''x''' = (734.401 - 329.735268) / 0.4243980056\r\n'''x''' = 953.5053\r\nThe respective calculation with crit(m) as variable and constant [[Formulas:Plus damage and Plus healing|spell damage]]:\r\n( ( 305 + 361 ) / 2 + 800 * 1.5 / 3.5 ) * ( 1 + '''x''' * 1.1 ) * 0.94 * 1.15 / 1.5 = 734.401\r\n( 333 + 800 * 0.4286 ) * ( 1 + '''x''' * 1.1 ) * 0.94 * 1.15 / 1.5 = 734.401\r\n( 333 + 342.88 + 366.3 * '''x''' + 377.168 * '''x''' ) * 0.94 * 1.15 / 1.5 = 734.401\r\n( 675.88 + '''x''' * 743.468 ) * 0.7206¯ = 734.401\r\n492.26593¯ + '''x''' * 535.7926053¯ = 734.401\r\n'''x''' = 0.45191\r\nSo you would need 953.6 +[[Formulas:Plus damage and Plus healing|Spell damage]] or 45.191% spell crit to achieve the same +65.17 dps boost,\r\n* note: A math error using formulas above was corrected. The analysis below is wrong but was left as the author originally wrote. Formulas are also suspect, but were not altered.\r\nthus The Lightning Capacitor is theoretically adding 153 +[[Formulas:Plus damage and Plus healing|Spell damage]] or 11.191% spell crit (251.056 [[Combat rating system|Spell Crit Rating]]). This +[[Formulas:Plus damage and Plus healing|Spell damage]] or spell crit is unaffected by the base [[Formulas:Plus damage and Plus healing|Spell damage]] in the calculation, but it is scaling with base spell crit and nature critical strike chance, of course, the more crit, the more [[dps]]-gain and therefore more required [[Formulas:Plus damage and Plus healing|Spell damage]] or spell crit to compensate it. The [[dps]]-boost is largely affected by cast(t), the caststime of your main nuke spell, shorter casts will result in more frequent procs. The Lightning Capacitor is thus one of the rare trinkets that scale directly with the subsequent equipment of its wielder and the effective circumstances.\r\nFurthermore, a large portion of this trinket's DPS relies on a rapid cast time. In particular for Mages, Scorch-Spam quickly falls behind in DPS relative other conventional raiding builds, such as Deep-Fire, the value is quickly diminished in later content where the cast-time of staple nukes is substantially longer.\r\nAs an example, taking a Deep-fire Mage with a 3.0s cast Fireball, assuming a 37% Fire crit-rate buffed(28% Nature crit-rate) and hit-capped, we obtain the following numbers:\r\n ( ( 694 + 806 ) / 2 * ( 1 + 0.28 * 0.5 ) ) * 0.96 = 820.8 Bolt-Damage\r\nand\r\n 0.99 * (3 / 0.37) * 3 = 0.99 * (8.108) * 3 = 0.99 * 24.324 = 24.081 Bolt-Time\r\nGiving\r\n Bolt-DPS = 820.8 / 24.081 = 34.085 DPS\r\n==Dps Calculator for trinket==\r\nIt is difficult to evaluate this trinket. Generally there are better options for most builds at the point you first enter Kara. Later when your spell crit has increased, this trinket really shines.\r\nInput your stats into the following spreadsheet to see how much benefit this trinket gives you:\r\n[[Media:Lightning Capacitor dps calculator.ods]]\r\n(Spreadsheet contains no macros. If it does, it's been infected.)\r\n==Additional notes==\r\nYou do not need to face the mob, which is supposed to be hit by the bolt.\r\nThe caused damage by the Lightning Bolt is '''un'''affected by the characters [[Formulas:Plus damage and Plus healing|Spell damage]], which can be explained by the fact, that the Lightning Bolt might appear like an instant cast spell, but it does not trigger the [[Global Cooldown]] and hence it's damaging coefficient is 0 / 3.5 = 0. Firing a Lightning Bolt also does not interrupt channeled casts like [[Arcane Missiles]].\r\nThe Lightning Bolt does not have a max-[[range]], as long as you can crit the mob, the Bolt can reach it. The Bolt is also unaffected by [[LoS]]-mechanics. Think of the following situation: You have 2 charges and you cast a fireball on a mob, while the fireball is in mid-air, the mob runs behind a wall or some [[LoS]] blocking obstacle. The fireball crits, giving the 3rd charge and thus releases the bolt; even though the mob is not hittable by your spells, the bolt will fly right through the obstacle and hit the mob. The same applies to [[Silence|silencing effects]], [[stun]]s and other incapacitating effects, basically there is nothing that could prevent [[The Lightning Capacitor]] from firing it's Bolt when reaching 3 charges, by any available means, except the case that the mob died from the 3rd crit, then the charges are lost and no Bolt is fired.\r\nThe Lightning Bolt always hits the mob which received the last crit that stacked the 3rd charge and released the Bolt, even though you may not have targetted it, except it died from the crit, as mentioned above.\r\nThe [[Electrical Charge]]s are displayed as a stackable, [[typeless]] [[buff]] on you. This [[buff]] has an infinite duration and even persists if you unequip [[The Lightning Capacitor]] or logout. It does not persist through death, however, and like other buffs, it disappears upon entering an Arena match.\r\nIt can proc from any ability that is considered a spell, which includes [[Flametongue Weapon]], [[Frostbrand Weapon]], [[Lightning Overload]]-casts, [[Firestone]] attack and [[Molten Armor]]. Wand crits are not considered spell crits and hence do not produce charges.\r\nThis item was changed in [[Patch 2.3]]. It now has a 2.5 second cooldown after each lightning bolt. The tooltip is quite misleading. It is actually meant to be \"cannot be discharged more than once every 2.5 seconds\". This seriously damages the worth of the item for casters who were using this with a heavy AoE spell rotation. Specificaly [[Arcane]] [[Mages]]. But as this changes effect depends largely on critluck and the current situation, it is hardly possible to calculate the actual loss of DPS for single-target damage casting. In most cases, it just takes one or two more casts to produce the necessary 3 charges (because one or two crits might have been in vain because of the CD).\r\nThe damage of the Lightning Bolt is affected by [[debuff]]s (e.g. [[Stormstrike]], [[Misery]]) and [[talents]] (e.g. [[Arcane Instability]], [[Molten Fury]]) which improve all, or at least nature spells. However, talents which specifically mention their affected spells do not improve it. Furthermore, even the Shaman's talents which improve Lightning Bolt do not affect it, as these only affect the Shaman's spell; these include [[Concussion]], [[Elemental Mastery]] and [[Elemental Fury]]. Especially in raid environments, where many buffs and debuffs are in effect, the [[dps]] boost provided is slightly higher (~80 dps), especially with spell crit increasing auras, totems or buffs.\r\nAs the [[rank]] of your nuke spell is irrelevant, it is possible to spam [[rank]] 1 spells while beeing [[oom]] and still sustain quite a bit of [[dps]]. While normally it is probably better to stay out of the [[Formulas:Mana Regen|5 second rule]], in combination with specific abilities (e.g. [[Judgement of Wisdom]], [[Insightful Earthstorm Diamond]], [[Clearcasting]]), spamming a rank 1 spell (for example, [[Scorch]]) might increase your damage by more.\r\nThe proc of this trinkets appears in your combat log as \"Your Lightning Bolt hits/crits %t for %d.\", just like the Lightning Bolts fired by [[Shaman]]s.",},
			["The Light of Dawn (quest)"] = { content = "'''The Light of Dawn''' came after the [[Battle for Light's Hope Chapel]], the final battle for a [[death knight]] in service of the [[Lich King]]...\r\n==Objective==\r\nDefeat the forces of the [[Argent Dawn]] and uncover the Light of Dawn.\r\nReturn to [[Highlord Darion Mograine]] should you survive.\r\n* The Light of Dawn Uncovered\r\n==Description==\r\nThe Argent Dawn stands defiantly against us at [[Light's Hope Chapel]]. They dare oppose the [[Scourge]] and for that reason alone they must be destroyed!\r\nThe mighty armies of the [[Lich King]] stand at the ready as the final battle for the [[Plaguelands]] approaches. Today we ascend into the immortal realm of Scourge heroes!\r\nAre you prepared, death knight?\r\n==Rewards==\r\nYou will also learn: \r\nYou will also receive: 2 gold 50 silver and 6 Bonus talents\r\n==Progress==\r\n<Highlord Mograine nods.>\r\n==Completion==\r\nThere will be no atonement for us, <name>. We are forever damned to walk the earth as monsters. While the Lich King may have loosed his grip upon us, the specters of the past will forever haunt our memories.\r\nWe must make amends in the only way we know how: Death...\r\nI ask you now to join me in [[Acherus: The Ebon Hold|Acherus]] as a Knight of the Ebon Blade. Together we will destroy the Lich King and end the Scourge.\r\n==Notes==\r\nThis is what essentially amounts to a death knight [[wikipedia:Battle of Thermopylae|Battle of Thermopylae]]. 300 defenders of the Light, led by the Argent Dawn leaders Duke [[Nicholas Zverenhoff]] and Lord [[Maxwell Tyrosus]], face off against ten thousand Scourge, led by Highlord Mograine and the player (or players, if there is a group on the same quest).\r\nAt the start of the battle, death knights receive a buff called the Might of Mograine, which increases their damage, health and health regeneration - allowing them to combat the defenders of the Light (who are all elites).\r\n==Quest dialogue==\r\nDuring the battle, Mograine and others shout orders, and interact in the battle. The event lasts for approximately ten minutes.\r\nHighlord Darion Mograine yells: Soldiers of the Scourge, stand ready! You will soon be able to unleash your fury upon the Argent Dawn!\r\nHighlord Darion Mograine yells: The sky weeps at the devastation of sister earth! Soon, tears of blood will rain down upon us!\r\nHighlord Darion Mograine yells: Death knights of [[Acherus: The Ebon Hold|Acherus]], the death march begins!\r\nHighlord Darion Mograine yells: Soldiers of the Scourge, death knights of Acherus, minions of the darkness: hear the call of the Highlord!\r\nHighlord Darion Mograine yells: RISE!\r\n<Thousands of Scourge rise up at the Highlord's command.>\r\nHighlord Darion Mograine yells: The skies turn red with the blood of the fallen! The Lich King watches over us, minions! Onward! Leave only ashes and misery in your destructive wake!\r\n<The army marches towards Light's Hope Chapel.>\r\n[[Korfax, Champion of the Light]] yells: Scourge armies approach!\r\n[[Lord Maxwell Tyrosus]] yells: Stand fast, brothers and sisters! The Light will prevail!\r\nHighlord Darion Mograine says: Spare no one!\r\nHighlord Darion Mograine yells: Rise, minions! Destroy them!\r\nHighlord Darion Mograine says: Power...wanes...\r\nHighlord Darion Mograine says: Ashbringer defies me...\r\nHighlord Darion Mograine says: Minions, come to my aid!\r\nHighlord Darion Mograine says: You will do as I command! I am in control here!\r\nHighlord Darion Mograine says: What is this?! My... I cannot strike...\r\n<After over a hundred Defenders of the Light fall, [[Tirion Fordring|Highlord Tirion Fordring]] arrives.>\r\nHighlord Tirion Fordring yells: You cannot win, Darion!\r\n<[[Orbaz Bloodbane]] flees.>\r\nHighlord Tirion Fordring yells: Bring them before the chapel!\r\n<Highlord Darion Mograine kneels in defeat before Tirion Fordring.>\r\nHighlord Darion Mograine says: Stand down, death knights. We have lost... The Light... This place... No hope...\r\nHighlord Tirion Fordring says: Have you learned nothing, boy? You have become all that your father fought against! Like that coward, Arthas, you allowed yourself to be consumed by the darkness...the hate... Feeding upon the misery of those you tortured and killed!\r\nHighlord Tirion Fordring says: Your master knows what lies beneath the chapel. It is why he dares not show his face! He's sent you and your death knights to meet their doom, Darion.\r\nHighlord Tirion Fordring says: What you are feeling right now is the anguish of a thousand lost souls! Souls that you and your master brought here! The Light will tear you apart, Darion!\r\nHighlord Darion Mograine says: Save your breath, old man. It might be the last you ever draw.\r\n<[[Alexandros Mograine|Highlord Alexandros Mograine]] arrives.>\r\nHighlord Alexandros Mograine says: My son! My dear, beautiful boy!\r\nHighlord Darion Mograine says: Father!\r\nHighlord Darion Mograine says: Argh...what...is...\r\n<Highlord Darion Mograine becomes a shade of his past, and walks up to his father.>\r\nDarion Mograine says: Father, you have returned!\r\n<Darion Mograine hugs his father.>\r\nDarion Mograine says: You have been gone a long time, father. I thought...\r\nHighlord Alexandros Mograine says: Nothing could have kept me away from here, Darion. Not from my home and family.\r\nDarion Mograine says: Father, I wish to join you in the war against the undead. I want to fight! I can sit idle no longer!\r\nHighlord Alexandros Mograine says: Darion Mograine, you are barely of age to hold a sword, let alone battle the undead hordes of Lordaeron! I couldn't bear losing you. Even the thought...\r\nDarion Mograine says: If I die, father, I would rather it be on my feet, standing in defiance against the undead legions! If I die, father, I die with you!\r\nHighlord Alexandros Mograine says: My son, there will come a day when you will command the [[Ashbringer]] and, with it, mete justice across this land. I have no doubt that when that day finally comes, you will bring pride to our people and that Lordaeron will be a better place because of you. But, my son, that day is not today.\r\nHighlord Alexandros Mograine says: Do not forget...\r\n<Alexandros disappears, and the [[Lich King]] appears.>\r\nThe Lich King yells: Touching...\r\n<Highlord Darion Mograine becomes himself again...and is now angry.>\r\nHighlord Darion Mograine says: You have forsaken me, bastard! Face the might of Mograine!\r\nThe Lich King says: Pathetic...\r\nThe Lich King says: He's mine now...\r\nHighlord Tirion Fordring says: You're a damned monster, [[Arthas]]!\r\nThe Lich King says: You were right, Fordring. I did send them in to die. Their lives are meaningless, but yours...\r\nThe Lich King says: How simple it was to draw the great Tirion Fordring out of hiding. You've left yourself exposed, paladin. Nothing will save you...\r\n<The Lich King casts a spell on Tirion.>\r\n<Highlord Tirion Fordring gasps for air.>\r\nLord Maxwell Tyrosus yells: ATTACK!!!\r\nThe Lich King yells: APOCALYPSE!\r\n<The Lich King casts a powerful spell, killing the charging Defenders.>\r\nHighlord Darion Mograine says: That day is not today...\r\nHighlord Darion Mograine yells: Tirion!\r\n<Darion throws the Corrupted Ashbringer to Tirion, who catches it. Tirion becomes awash with Light, and the Ashbringer is cleansed.>\r\n<Highlord Darion Mograine collapses.>\r\nHighlord Tirion Fordring yells: ARTHAS!!!!\r\nThe Lich King yells: What is this?\r\nHighlord Tirion Fordring yells: Your end.\r\n<Tirion charges towards the Lich King, Ashbringer in hand. The Lich King turns and begins to run.>\r\nThe Lich King yells: Impossible...\r\nThe Lich King yells: This... isn't... over...\r\nThe Lich King yells: When next we meet it won't be on holy ground, paladin.\r\n<The Lich King disappears. Tirion walks over to where Darion lay.>\r\nHighlord Tirion Fordring says: Rise, Darion, and listen...\r\nHighlord Tirion Fordring says: We have all been witness to a terrible tragedy. The blood of good men has been shed upon this soil! Honorable knights, slain defending their lives - our lives!\r\nHighlord Tirion Fordring says: And while such things can never be forgotten, we must remain vigilant in our cause!\r\nHighlord Tirion Fordring says: The Lich King must answer for what he has done and must not be allowed to cause further destruction to our world.\r\nHighlord Tirion Fordring says: I make a promise to you now, brothers and sisters: The Lich King will be defeated! On this day, I call for a union.\r\nHighlord Tirion Fordring says: The [[Argent Dawn]] and the [[Order of the Silver Hand]] will come together as one! We will succeed where so many before us have failed!\r\nHighlord Tirion Fordring says: We will take the fight to Arthas and tear down the walls of [[Icecrown]]!\r\nHighlord Tirion Fordring yells: The [[Argent Crusade]] comes for you, Arthas!\r\nHighlord Darion Mograine says: So too do the [[Knights of the Ebon Blade]]... While our kind has no place in your world, we will fight to bring an end to the Lich King. This I vow!\r\n<Light washes over the chapel — the Light of Dawn is uncovered.>\r\n==Video==\r\n<youtube>72eZhqR7qgw</youtube>",},
			["The Light Stands Strong"] = { content = "Short story in the [[World of Warcraft Official Strategy Guide]].\r\nA paladin defends Darkshire from an attacking abomination. Warned by the town crier, while the city militia, the Night Watch rallied, the paladin, along with a warrior, priest, and night elf rogue began to battle the monster. The rogue had died during the battle, but the paladin was able to call him back to life. They had all stood up against one of the worst horrors they had ever encountered. He vowed to one day reclaim Duskwood, so that all its citizens could roam in its tranquil gardens and bright glades again.",},
			["The Lineage of Azeroth's Kings"] = { content = "'''The Lineage of Azeroth's Kings''' is a book that Garona studied to learn about [[humans]]. Later, it was thrown at a [[demon]] [[beast]] that attacked [[Khadgar]] and Garona.",},
			["The Living Grove"] = { content = "#redirect [[Living Grove]]", redirect = "Living Grove",},
			["The Living Wood"] = { content = "#redirect [[Living Wood]]", redirect = "Living Wood",},
			["The Loch"] = { content = "The '''Loch''' is the single most prominent feature of the [[dwarven]] territory of [[Loch Modan]]. It was once the largest body of water on the continent of [[Khaz Modan]], and third in size in the entire known world after the [[Lordamere]] and [[Darrowmere]] lakes. Fed by an underground source, the loch was originally much smaller, but more than doubled its size after the dwarves of Khaz Modan built the [[Stonewrought Dam]] at the loch's northern end.\r\nHowever, [[Deathwing]]'s emergence into [[Azeroth]] resulted in the destruction of the Stonewrought Dam, draining much of the lake into the [[Wetlands]]. The [[Twilight's Hammer]] has set up camp on two of the islands in the middle of the lakebed.\r\n==Notes and trivia==\r\n*The draining of the loch brought horrible ecological devastation. The fish disappeared, and there are now acres of dead [[threshadon]]s out there left to rot in the sun. The buzzards are after them, and they're spreading all manner of filth and disease. Some threshadons survived being washed away and ended up in the [[Wetlands]].\r\n*The fact that the Loch is inhabited by threshadons may be a reference to the Loch Ness Monster which is often described as plesiosaur-like (like threshadons). The [[Modan Monster]] appears to be a reference to the Loch Ness monster.",},
			["The Long Wash"] = { content = "#REDIRECT [[Long Wash]]", redirect = "Long Wash",},
			["The Lord of Blackrock"] = { content = "Did you want the Horde version or the Alliance version?\r\nThe Lord of Blackrock (Horde)\r\nThe Lord of Blackrock (Alliance)",},
			["The Lord of Blackrock (Alliance)"] = { content = "The Lord of Blackrock is the 1st quest in the '''The Lord of Blackrock''' quest chain.\r\n==Objectives==\r\nReturn the Head of Nefarian to King Varian Wrynn in Stormwind.\r\n* Head of Nefarian (Provided)\r\n==Description==\r\nThe old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian. Return it to your Highlord, champion.\r\n==Progress==\r\nInconceivable!\r\n==Completion==\r\nYou need not be told the meaning of what you have done, <name>. This day will be recorded in the annals of history. A victory the likes of which has not been known to the Alliance for years - if ever!\r\n==Quest chain==\r\n#The Lord of Blackrock (Alliance)\r\n#The Lord of Blackrock (Alliance) (2)",},
			["The Lost Fleet"] = { content = "#REDIRECT [[Lost Fleet]]", redirect = "Lost Fleet",},
			["The Lost Fold"] = { content = "#redirect [[Lost Fold]]", redirect = "Lost Fold",},
			["The Lost Fragments"] = { content = "==Objectives==\r\nBring the [[Torn Scroll Fragment]], the [[Crumpled Scroll Fragment]] and the [[Singed Scroll Fragment]] to [[Theldurin the Lost]]. \r\n*Torn Scroll Fragment\r\n*Crumpled Scroll Fragment\r\n*Singed Scroll Fragment\r\n==Description==\r\nThe Scroll of Myzrael...the [[Scroll of Myzrael]]?! You don't want that! Its magic can pull Myzrael to the surface world and if you do that, we are in trouble!\r\nOr...maybe it's too late. Maybe she already is free. Maybe she's just gathering strength before unleashing herself upon us. If so, then you'll NEED the scroll!\r\n...too bad it's destroyed. Enraged [[elemental]]s stole it and tore it up and now fight over the fragments.\r\nBut if you can gather those fragments, maybe we can fix it... \r\n==Progress==\r\nDid you find those fragments?!?! You'll need the Scroll of Myzrael if you want to trap her again, before it's too late! \r\n==Completion==\r\nAh, you found them! Good work, <name>! These might be the only chance we have against the evil of Myzrael!\r\nJust let me find my scrap-ratchet and see if I can re-attach these fragments... \r\n==Gains==\r\n*4600 [[XP]]\r\n==Notes==\r\nThe elementals to kill for these fragments are the [[Enraged Rock Elemental|Enraged Rock Elementals]] directly in the hills behind [[Theldurin the Lost|Theldurin]]. No other elementals will drop the scroll fragments. It is possible to have multiple fragments drop from one elemental.",},
			["The Lost Tablets of Mosh'aru"] = { content = "==Objectives==\r\nBring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris.\r\n*Third Mosh'aru Tablet\r\n*Fourth Mosh'aru Tablet\r\n==Description==\r\nThe troll with whom you spoke did not tell the truth. The two tablets you gained for him spoke of containing the essence of Hakkar, but there is more to that legend. I have studied long, and found that there are six Tablets of Mosh'aru, not two! Six!\r\nAnd I fear that we will not like what secrets the others hold..\r\nFind the third and fourth tablets of Mosh'aru. They're in the Eastern Plaguelands, held by the mossflayer trolls. Find them, and bring them to me.\r\n==Progress==\r\nDo you have the tablets? I fear their texts will reveal a great threat to our world.\r\n==Completion==\r\nYou found them! Great!\r\nThank you, <name>. I will pour over these texts and decipher their meaning.\r\nYou, however, have another task...\r\n==Notes==\r\nThe tablets are located in [[Zul'Mashar]], in the northeast [[Eastern Plaguelands]]. The third is at the top of the [[Mazra'Alor]] ziggurat at . The Fourth is on the bottom, east of the stairs at .\r\n==Quest progression==\r\n#Screecher Spirits\r\n#The Prophecy of Mosh'aru\r\n#The Ancient Egg\r\n#The God Hakkar\r\n#The Lost Tablets of Mosh'aru\r\n#The Final Tablets\r\n#Confront Yeh'kinya\r\n#The Hand of Rastakhan",},
			["The Low Path"] = { content = "#redirect [[Low Path]]", redirect = "Low Path",},
			["The Lurker Below"] = { content = "'''The Lurker Below''' is the second [[boss]] of [[Serpentshrine Cavern]] in [[Coilfang Reservoir]]. The creature is of a previously unknown type — its file name is listed as \"[[krakken]]\", although it shares its name with [[lurker below|lurkers below]]. It is widely considered to be the easiest fight in SSC, earning it the nicknames \"The Loot Below\" and \"The lolcats Below.\" The name itself may be derived from the Dungeons and Dragons monster, Lurker Above, which is also known for dwelling in dark caverns.\r\nIn order to start the fight, raid members must fish in the \"Strange Pool\" (needs +300 [[fishing]] skill). Each cast has a chance to make the Lurker come to the surface. The success rate of this ranges from 1-2 attempts up to fishing for 8 minutes straight. Some people claim that hitting the center of the pool has a higher chance to summon the Lurker, but this is not confirmed.\r\nPrior to patch [[2.3.0]] (aka The Gods of Zul'aman) The Lurker Below had a unique model, but [[Tethyr]], a second krakken with a new skin, was added to the game and killing it is the objective of the quest:[[Take Down Tethyr!]]\r\n==Phases==\r\nThis encounter alternates between two phases. The Lurker is only active for Phase 1, which lasts 120 seconds. At the start of Phase 2, Lurker submerges and the adds are spawned. After 60 seconds of Phase 2, the Lurker re-emerges and goes back to Phase 1.\r\n===Phase 1 Abilities===\r\n*Melee: Hits tanks for ~4k physical damage.\r\n*Stationary: The Lurker cannot move from his pool, and will never aggro players outside of melee range (As long as at least one melee is present).\r\n*'''Water Bolt''': 1-second cast, 9-11k damage, random target. Only used if no targets are in melee range, to prevent exploiting.\r\n*'''Whirl''': Physical damage to all characters in melee range. 3-4k damage, 5-yard knockback. Occurs every 18 seconds immediately after Spout completes.\r\n*'''Geyser''': Randomly attacks any player, causing 3-4k Frost damage to everyone within ~10 yards of the target, as well as a ~10-yard knockback to all affected.\r\n*'''Spout''': The Lurker shoots a spray from his mouth at his current target then slowly rotates 360+ degrees in a clockwise or counter-clockwise direction. Characters hit by Spout take repeated ~3.5k frost damage very quickly and are knocked back 60+ yards. Spout does not affect characters who are submerged under the water. Pets are not affected by Spout. Spout occurs every 45 seconds in Phase 1. Lurker also uses Spout immediately after re-emerging from Phase 2.\r\n===Phase 2 Adds===\r\nSix ambushers and three guardians spawn at the start of phase 2. All forms of [[crowd control]] except [[mind control]] work on all adds.\r\n'''Coilfang Guardian''': \r\n*70k Health\r\n*Melee: 6k-7k on cloth\r\n*Arcing Smash: 5k-9k damage in a frontal cone\r\n*Hamstring: Reduce movement speed by 70% for 10 sec\r\n'''Coilfang Ambusher''':\r\n*26k Health\r\n*Melee: 2k-3k on cloth\r\n*Multi-Shot: Ranged attack on up to 3 players for 2-3k damage on cloth\r\n*Seem to have no aggro table\r\n==Positioning==\r\nThe Lurker requires only one tank; having an off-tank makes it safer. The tank should stand in the inner ring with his back to the pillar to help prevent the knockbacks. Everybody else should spread out to minimize damage from Geyser. Melee damage dealers should stand as close to the inner edge of the platform as possible, so that the 5-yard Whirl knockback doesn't drop them into the water. Healers should stand at the outside limit of the ring to make it easy to step back into the water to avoid Spout. Ranged damage dealers can stand on the outer platforms.\r\n==Phase 1==\r\nThe combat starts with the Lurker on the surface. It's rather straightforward tank and spank, except for Spout and Whirl. Aggro is hardly an issue—as long as there are targets in melee range, the Lurker does not attack ranged targets except for a random Geyser now and then. The Lurker can also be taunted. After two minutes, the Lurker submerges (which also removes all debuffs from him), adds turn up and Phase 2 starts. The Lurker re-emerges 60 seconds later and Phase 1 starts again.\r\n===Spout===\r\nSpout is the main reason for wipes on this boss; the whole raid has to learn how to avoid it. Boss mods usually give a 3-second warning, and it's best to immediately jump in the water when the warning comes up. Ranged DPS and healers can continue to do their job while in the water by swimming a little deeper to gain line of sight. After the beam has passed, it's safe to return to the platforms. The tank and everybody close to him need to pay attention—the beam starts at the tank and rotates for a little more than 360°. Each spout is closely followed by a Whirl.\r\nAdvanced techniques have the melee group run in a circle around the platform to avoid the beam (while still dealing damage). It's also possible to blink through it, or to use [[Ice Block]] or [[Divine Shield]]. It should be noted, however, that melee can continue to DPS during a spout by jumping forward into the water immediately surrounding Lurker. This will allow them to maintain more consistent DPS than if they are running in a circle, and the damage they take is very minor provided that they jump back out of the water as soon as the spout passes.\r\nSpout does not affect pets.\r\n===Whirl===\r\nThe second problem during Phase 1 is Whirl. If the entire melee group is knocked away from the Lurker, he starts to deal severe ranged damage to the raid. Thus a tank needs to avoid the Whirl, and be back in melee range ASAP.\r\nBoss mods normally give a warning before a Whirl is incoming. The best solution is to have the MT jump into the water closer to the Lurker. In this case, the knockback brings him back onto the platform without ever leaving melee range. Alternatively, it's possible to back out of melee range before a Whirl and quickly move back in right after.\r\nTo make the fight safer, additional tanks can try to do the same as the MT. Since the Lurker can be taunted, it's rather easy to control him once a tank is in melee range.\r\nIt is possible to have a tank in the water the whole time. This makes him immune to Spout, and he doesn't have to be alert on Whirls. The water inflicts about 380 damage per tick, but the bigger problem is that there may be line-of-sight problems for the healers. To avoid the LOS issue, the MT healers can stay under water, too. One shadow priest in their group is enough to keep their health and mana up. When using this technique, everybody must be alert to exit the water during phase 2.\r\nWhirl deals only about 1k of damage to pets, and no knockback.\r\n===Geyser===\r\nSometimes the Lurker will randomly target someone in the raid for Geyser, which deals 2.5k-3.5k frost damage and knockback (10 yards) to the target and those nearby. Spread out to avoid having too many people hit by Geyser.\r\n==Phase 2==\r\nEach time the Lurker submerges, he spawns a total of nine adds: two ranged [[Coilfang Ambusher]]s on each outer platform, and three melee [[Coilfang Guardian]]s on the inner ring. All these adds can be [[Crowd Control]]led.\r\nUsually, each platform has one group of the raid assigned to clear the [[Coilfang Ambusher]]s, while the melee group deals with the [[Coilfang Guardian]]s. Each of the groups should use CC and kill their adds. Mages should note that these mobs cannot be polymorphed until they are standing in their place; trying to sheep them as they are nearing the islet results in an error message. When the platform groups are done with their packs, they need to help on the Guardians.\r\nThe Ambushers can basically be tanked by any class (the more armor the better). There is one dangerous effect to be aware of: If an Ambusher gains aggro on a healer (or damage dealer) on another platform, he starts to evade until the healer comes over onto their island. If the Lurker emerges while an Ambusher is still evading, the Lurker despawns.\r\nSimilarly, the Guardians can gain aggro on raid members on other platforms, but they simply teleport and attack in this case.\r\nOne minute after submerging, the Lurker comes back whether or not all adds are dead. After re-emerging, he starts out with a sequence of Whirl, Spout and another Whirl. It's very difficult to master this while there's an add around. The best bet is to keep the add CC'd until after the sequence (or even longer).\r\n===Alternate strategy #1 for phase 2===\r\nNew [[Coilfang Guardian]]s spawn on the transition to phase two only to replace dead Guardians from prior spawns. Thus it's possible to keep the Guardians sheeped (or otherwise CC'd) during the whole fight. Of course, Guardians breaking their CC can mean a one-shot death for the mage, followed by the healers in the raid, so it is important to refresh sheep every 15-20 seconds. The mages should also be [[soulstone]]d.\r\nOn top of that, hunters can put a freezing trap on the outer platforms, at the points where the [[Coilfang Ambusher]]s enter. This way the raid has to deal with at most three mobs at the same time, making the healers' job much easier.\r\n===Alternate strategy #2 for phase 2===\r\nThis strategy is similar to Alternate strategy #1. Our raid found that sheeping the Coilfang Guardians resulted in dead mages, so we took on the oppisite approach. We sheeped the Coilfang Ambushers instead and killed the Coilfang Guardians. That kept our mages alive and kept the dps going.\r\n==Rezzing==\r\nIt is possible to use [[Levitate]] or [[Water Walking]] while rezzing, but the rez targets may quickly die again from the [[Scalding Water]]. A second healer should be ready to immediately get the rezzed players health up again and/or have the priest cast [[Power Word: Shield]] on the newly rezzed target before healing them again.\r\n==Tips==\r\nAs the Scalding Water debuff deals Fire damage, Mages can use Fire Ward to lessen the damage they take during Spouts.\r\n==Bugs == \r\nThe Lurker can get into a state where he does a constant Spout even though there is no casting bar and he still uses his other abilities. It occurs when the last add dies during a Spout. To not have the bug happen ensure that the final add is killed before or after a Spout, NOT during. This is supposed to be fixed in an upcoming patch. See the blue posts in \r\nThere is also a current bug where the melee adds can spawn on the various islands and one- or two-shot the DPSers. This occurs when someone uses a consumable while the adds are moving into position. The aggro generated causes the melee adds to teleport to the island where the aggro originates as they're coming in, and it looks like they're spawning on that island. As long as no one uses any consumables (that includes bandages) until the tanks have aggro on melee they will not bug out.\r\nAt the start of the Burning Crusade a bug existed where if the Lurker Below was killed while casting spout, the boss could be looted, and after a [[Instance reset|Soft Reset]] it would respawn. Many guilds used/abused this bug to farm the boss repeatedly.\r\n==Notes==",},
			["The Lyceum"] = { content = "#redirect [[Lyceum]]", redirect = "Lyceum",},
			["The Maclure Vineyards"] = { content = "#REDIRECT [[Maclure Vineyards]]", redirect = "Maclure Vineyards",},
			["The Mag'har"] = { content = "#REDIRECT [[Mag'har (faction)]]", redirect = "Mag'har (faction)",},
			["The Mage Quarter"] = { content = "#REDIRECT [[Mage Quarter]]", redirect = "Mage Quarter",},
			["The Magic Quarter"] = { content = "#redirect [[Magic Quarter]]", redirect = "Magic Quarter",},
			["The Maiden's Fancy"] = { content = "'''The ''Maiden's Fancy''''' is a [[Blackwater Raiders]] [[boat|vessel]] with a mixed-race crew that runs between the [[Steamwheedle Cartel]] ports of [[Ratchet]] and [[Booty Bay]]. It has no problems with the [[Bloodsail Buccaneers|Bloodsail]] coming near them. The ship has a large amount of gunpowder in the hold...for insurance, you know.\r\n==Crew==\r\n* [[Captain Krick Wrenchnozzle]]\r\n* [[First Mate Masker]]\r\n* [[Bosun Thunderhorn]]\r\n* [[Navigator Tah're]]\r\n* [[Engineer Torquespindle]]\r\n* [[Galley Chief Steelbelly]]\r\n* [[Crewman Gearspinner]]\r\n* [[Crewman Springwidget]]\r\n* [[Crewman Hammertink]]\r\n* [[Treasure]]",},
			["The Maker's Terrace"] = { content = "#REDIRECT [[Maker's Terrace]]", redirect = "Maker's Terrace",},
			["The Maker"] = { content = "'''The Maker''' is the first boss of the [[Blood Furnace]] in [[Hellfire Citadel]]. The Maker is a fairly simple encounter; most groups of level 60ish characters should have no troubles with him.\r\n==Strategy==\r\nHe has four special abilities, which he will use randomly throughout the fight: \r\n* A melee knockup attack which will hit everyone in melee range and appears to have a threat reduction component\r\n*Domination ([[Mind Control]] on a target that increases the target's damage and healing by 100%. Domination is non dispellable)\r\n* Acid Spray (melee range [[AoE]] spray of acid)\r\n* Throw Beaker (throws a beaker at a target, dealing 1000-1200 [[nature]] damage and knocks target into the air)\r\nHe doesn't hit particularly hard and can generally be DPS burnt pretty quickly.\r\n==Quotes==\r\n*'''Aggro''' ''My work must not be interrupted.''\r\n*'''Aggro''' ''Perhaps I can find a use for you.''\r\n*'''Aggro''' ''Anger... Hate... These are tools I can use.''\r\n*'''Killing a Player''' ''Let's see what I can make of you.''\r\n*'''Killing a Player''' ''It is pointless to resist.''\r\n*'''Death''' ''Stay away from... me.''",},
			["The Manor, Ravenholdt"] = { content = "==Objectives==\r\nTake the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\r\nYour cunning will be tested along the way. Be prepared.\r\n*[[Rite of Cunning]]\r\n* (Provided)\r\n== Description==\r\n<name>,\r\nRavenholdt has taken an interest in you, young thief. We have been watching. Your style is a bit awkward but nothing we couldn't fix.\r\nShould you be prepared to embark on a career as a disciple of Master Ravenholdt and member of the Assassin's League, you have only to bring the Seal of Ravenholdt (attached to this letter) to Ravenholdt Manor.\r\nYour first task is to find the manor, hidden away in the hills of Hillsbrad and demonstrate your cunning.\r\nRegards,\r\nFahrad \r\n== Progress==\r\nDid you meet Milton?\r\n<Fahrad laughs.> \r\n== Completion==\r\nMost excellent, young thief.\r\nYou look a bit beaten down, but no worse for the wear.\r\nA long journey awaits you - long and rewarding. Are you prepared to finally embrace your destiny among the masters of Ravenholdt?\r\nSpeak with the guards outside. They will get you started. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*1950 [[XP]] (or 12 silver copper at level 70)\r\n*250 [[reputation]] with [[Ravenholdt]]",},
			["The Manufactory"] = { content = "#redirect [[Manufactory]]", redirect = "Manufactory",},
			["The Mark of Vashj"] = { content = ":''Were you looking for the [[quest]] The Mark of Vashj?''\r\n'''The Mark of Vashj''' is a spell cast on the player with the completion of The Cudgel of Kar'desh and returning to [[Skar'this the Heretic]]. With this spell cast on the player, they are allowed to enter [[Serpentshrine Cavern]], the lair of [[Lady Vashj]]. As of Patch 2.1.2 this is no longer needed to enter SSC.\r\nWith Patch 2.3, players who complete or have completed the attunement process for SSC/TK will receive the title [[Champion of the Naaru]].",},
			["The Marris Stead"] = { content = "#REDIRECT [[Marris Stead]]", redirect = "Marris Stead",},
			["The Marshlands"] = { content = "#REDIRECT [[Marshlands]]", redirect = "Marshlands",},
			["The Masonary"] = { content = "#REDIRECT [[Masonary]]", redirect = "Masonary",},
			["The Master's Cellar"] = { content = "#REDIRECT [[Master's Cellar]]", redirect = "Master's Cellar",},
			["The Master's Glaive"] = { content = "#REDIRECT [[Master's Glaive]]", redirect = "Master's Glaive",},
			["The Master's Key"] = { content = "In order for your raid to enter [[Karazhan]], only one person needs to possess '''The Master's Key'''. This page provides an in-depth, step-by-step description of the steps required to obtain the key.\r\nAs of [[Patch 2.4.0]], The Master's Key is not needed to enter Karazhan, but is still needed to open the Front and Side Gates.\r\n==Quest chain at a glance==\r\nThe key can be obtained by completing the following questline (Starts just outside [[Karazhan]], with [[Archmage Alturus]], an Archmage of the [[Violet Eye|The Violet Eye]] (46,75)):\r\n* Archmage Alturus: [[Lower City]]; optional talk to NPC, 5 rep with Violet Eye\r\n* Arcane Disturbances: [[Deadwind Pass]]; standard soloable exploration quest\r\n* Restless Activity: [[Deadwind Pass]]; standard soloable kill quest, can be done at the same time as above\r\n** Contact from Dalaran: [[Dalaran]]; talk to NPC\r\n** Khadgar: Talk with [[Khadgar]] in [[Shattrath City]]\r\n** Entry Into Karazhan: Dungeon; first key part to be found in the [[Shadow Labyrinth]], [[Auchindoun]]\r\n** The Second and Third Fragments: Two dungeons; the second key part is found in [[The Steamvault]] and the third key part is found in [[Arcatraz]]\r\n** The Master's Touch: Dungeon; Talk with [[Medivh]] in the [[Opening the Dark Portal]] ([[Black Morass]]) instance in [[Caverns of Time]]. He'll give you his own key.\r\n*** Return to Khadgar: Soloable; just return to [[Khadgar]]\r\nThe whole questline rewards 2100 reputation with the [[Violet Eye]]. Before [[patch 2.4]], that fact could be used to look up if someone has [[The Master's Key]] in the [[Armory]]. Now that a player can enter Karazhan without the key, it can't be used anymore.\r\nFor a description of the entire Karazhan Quest chain see: [[Karazhan Quest Progression]]\r\n==Access requirements==\r\nSome of the quests in this chain have access requirements that may sidetrack a player. These include access into:\r\n* The [[Arcatraz]], either with a key possessed by a party member, or a rogue with 350 lockpicking. (Note that, after a wipe or if a party member is killed and can not be resurrected, you will need the key again to enter the instance.) The key is obtained through a quest chain in [[Netherstorm]]. The Arcatraz can only be reached by flying mount or druid flight form.\r\n* [[Shadow Labyrinth]] in [[Auchindoun]] also requires that a party member have a key, or you have a rogue with 350 lockpicking. The key is in an easy-to-miss chest behind the last boss in [[Sethekk Halls]], also in [[Auchindoun]].\r\n* The [[Caverns of Time]] in [[Tanaris]]. This requires everyone in your party to have successfully completed [[Escape from Durnholde Keep]] in [[Old Hillsbrad Foothills]].\r\n'''Note:''' [[Escape from Durnholde Keep]] is part of a quest chain that starts with To The Master's Lair, which you obtain from [[Andormu]] outside of the [[Caverns of Time]] itself.\r\nDetailed descriptions are provided at the respective pages.\r\n==In-depth explanation==\r\n#Quests: Arcane Disturbances and Restless Activity\r\nTravel to [[Karazhan]] in [[Deadwind Pass]], where [[Archmage Alturus]] gives you two quests, Arcane Disturbances and Restless Activity, which you do in the immediate area. Upon completion, Alturus sends you to [[Dalaran]] with the quest Contact from Dalaran.\r\n#Quest: Contact from Dalaran\r\nAt [[Dalaran]], go to the north side of the bubble to speak to [[Archmage Cedric]]. He gives you the quest Khadgar, to return to [[Shattrath]].\r\n#Quest: Khadgar\r\nGo to the center of [[Shattrath]] and speak to [[Khadgar]], the one who you started the guided tour at and who asked you to decide which faction you wanted to align with. He gives you Entry Into Karazhan, which requires a trip to [[Shadow Labyrinth]] in [[Auchindoun]].\r\n#Quest: Entry Into Karazhan\r\nYour goal is to obtain the first key fragment, located near [[Murmur]], the last boss in [[Shadow Labyrinth]]. An elite guard spawns when you open the container; loot the fragment off of its corpse. Return to [[Shattrath]] with your fragment.\r\n#Quest: The Second and Third Fragments\r\nWhen you return to [[Shattrath]], [[Khadgar]] asks that you obtain the second and third key fragments.\r\n#*'''The second key fragment''' is in [[The Steamvault]] in [[Coilfang Reservoir]]. The container is in the corner at the bottom of a deep pool of water near the first boss.\r\n'''Note:''' The second key fragment was originally lootable from the box directly, and could be done solo by mages, druids and rogues. With patch 2.0.7, the key is now looted off of an elite guard that spawns when you open the container. For this reason, you may be more successful if you go with others. (Druids are still ok - he is a beast so hibernate will work when you need a rest)\r\n#*'''The third key fragment''' is in [[Arcatraz]] in [[Tempest Keep]] in [[Netherstorm]], accessible by a flying mount or flying form. Entry into the instance requires a key or a rogue with 350 lockpicking. See [[Key to the Arcatraz]] for details on obtaining the key.\r\nYou need not kill any bosses to get to the key shard, located up the \"glass\" ramp in the first room where you encounter voidwalkers. As you enter, the container is to your immediate right in the corner of the room.\r\n'''Note:''' As with the second key, this one requires a group to kill the guard. Two rogues can distract the patrolling voidwalker while a druid (feral) and another rogue kills the guard (with the first rogue distracting joins the fight) can make things easier. Still stealthable, just challenging.\r\nIt is possible to stealth through most of the path to the Arcatraz key. At one point the hallway narrows and you must pass a \"dead\" arcane guardian construct (a 70 elite that explodes when it dies), which has stealth detection even though it doesn't display a stealth-detection icon above its head. If you kill the arcane guardian you can stealth into the voidwalker room to wait in the corner by the quest container and loot it as noted above.\r\n#The Master's Touch\r\nReturn to [[Shattrath]] and hand your second and third key fragments to [[Khadgar]]. He then sends you to [[The Black Morass]] in the [[Caverns of Time]] to speak to [[Medivh]], who activates your key.\r\n'''Note:''' This step requires [[Opening the Dark Portal]], where you protect [[Medivh]] from waves of mobs (including elites) while he opens the Dark Portal. From every sixth portal a boss will spawn. After the 18th portal the Dark Portal will open and the task is complete. You can now speak to [[Medivh]] and claim your Master Key to Karazhan.\r\n'''Note:''' If you are not inside of the instance when [[Aeonus]] is killed, you will not be able to speak with [[Medivh]].\r\n'''Note:''' Keep in mind that you '''must''' first complete [[Escape from Durnholde Keep]] to access [[Opening the Dark Portal]].\r\n#Return to Khadgar\r\nReturn to [[Khadgar]] in [[Shattrath]], and he gives you The Master's Key. He then gives you the quest The Violet Eye. This sends you back to [[Karazhan]], where your Karazhan quests will begin.\r\nCongratulations, you can now enter Karazhan!\r\nAs of Patch 2.2 a Druid can be attuned to Kara before 70. The chain starts at 68 and can be completed at 68 as long as you have your flight form.\r\nAs of Patch 2.4, the Warlock \"Ritual of Summoning\" can now be used in Netherstorm and to summon players into any instance from outside.",},
			["The Master of Fenris Isle quest chain"] = { content = "A relatively short chain of quests explaining the presence of undead gnolls in Silverpine Forest.\r\n==Prequel: The Dead Fields==\r\n*'''The Dead Fields'''\r\nThe [[banshee]] [[Nightlash]] has established a base in [[The Dead Fields]]. When small expeditions have been sent in the past, some of the Rot Hide Gnolls have been slain, certainly. But each assault has been repulsed by Nightlash's magic, and the gnolls have been reinforced every time.\r\nOne of the things that [[High Executor Hadrec]] wants you to do is to go to the Dead Fields and dispatch Nightlash, returning with what dust remains of her corporeal shell.\r\n==The Master of Fenris Isle==\r\n*'''The Decrepit Ferry'''\r\n[[High Executor Hadrec]] tells you that the [[Scourge]] have been gathering at\r\n[[the Decrepit Ferry]], and he wants you to find out.\r\nYou journey there, and discover a boat, heaped with corpses! It is clearly\r\nevident that wherever these corpses came from, they are headed for\r\n[[Fenris Isle]].\r\n*'''Rot Hide Clues'''\r\nA bit of glitter in the boat attracts your attention. On the hand of the\r\nrecently deceased corpse of a woman, you find a gold ring, with the\r\ninscription \"For Deliah\".\r\nWhen you bring the ring to Hadrec, he tells you that the only nearby source\r\nfor such a body would be the mass graves of Tirsifal. The [[Rot Hide]]\r\ngnolls must be taking these bodies to Fenris Isle.\r\n*'''Rot Hide Ichor'''\r\nIt is evident that something on Fenris Isle needs to be taken out. But just\r\nwhat that is, and who is behind it, is still a mystery. More needs to be \r\ndiscovered before an assault is made. Hadrec directs you to gather ichor\r\nfrom the Rot Hides on Fenris Isle and bring it to [[Apothecary Renferrel]].\r\nIt takes a bit (you manage to destroy many of the rot hides too thoroughly to\r\ncollect ichor from them), but you collect the amount Renferrel needs and\r\nbring it to him.\r\n*'''Rot Hide Origins'''\r\nApothecary Renferrel reduces and analyzes the ichor as best he can, and does\r\ndiscover some of its properties. It is not entirely alchemical, though, and\r\nhe asks you to take a sample to [[Bethor Iceshard]] in [[Undercity]].\r\n*'''Thule Ravenclaw'''\r\nWith his knowledge of magic, Bethor is able to divine more about the spells\r\ninvolved in the Ichor... and who created them.\r\nIt turns out that the ichor was created by [[Thule Ravenclaw]], one of Bethor's\r\ncolleagues who sided with the [[Scourge]] when the [[Lich King]] rose to\r\npower. On the plus side, Bethor knows a lot about the magic that Thule uses,\r\nand gives you a scroll that Apothecary Renferrel can use to craft a potion that\r\nshould counter Thule's more powerful spells.\r\nYou return, then, to the Sepulcher, where Renferrel concocts the potion.\r\n*'''Report to Hadrec'''\r\nRenferrel refers you back to High Executor Hadrec, who has access to the\r\nSepulcher's arsenal. Hadrec concurs with Renferrel that Thule must be dealt\r\nwith, and offers you some items to improve your armor and weaponry.\r\n*'''Assault on Fenris Isle'''\r\nArmed and ready, you gather friends about you and set off. You have to\r\nbattle quite a number of Rot Hide gnolls as you work your way through the\r\ncastle, but finally you come face-to-face with [[Thule Ravenclaw]].\r\nVictorious in battle, you retrieve his head as proof that you have slain\r\nhim.\r\nReturning to High Executor Hadrec, you are praised, and told that fallout\r\nof your battle was felt as far away as the Sepulcher.\r\n==Rewards Summary==\r\n* +825 [[Undercity]] reputation\r\n* Medium Armor Kit\r\n* 5 of either Coarse Sharpening Stone or Coarse Weightstone",},
			["The Matron Protectorate"] = { content = "==Objectives==\r\nTravel to [[Winterspring]] and find [[Haleh]]. Give her Awbee's scale. \r\n*Awbee's Scale (Provided)\r\n== Description==\r\nTravel to Kalimdor, <race>. Our flight makes its home in the frigid landscape of [[Winterspring]]. Once you reach [[Winterspring]], find the caves of Mazthoril.\r\nUpon the icy floors of Mazthoril you will find cobalt runes. Hold one of my scales and stand upon a rune and you shall be transported to [[Haleh]], our matron protectorate.\r\nGive her the scale so that she may scry what it is I have seen and felt, here in this doomed place. \r\n== Progress==\r\nIt is good to see you, <name>. \r\n== Completion==\r\nThe Aspects insist that we stay out of the affairs of mortals. In this world, however, such a thing is not always possible - especially when one of our own contemptuously disregards such edicts. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*6600 [[XP]] (or 39 silver copper at level 70)",},
			["The Maul"] = { content = ":''Did you mean the bear form attack [[Maul]], or the weapon Maul (Weapon)?''\r\n'''The Mau'''l is a large pit located outside the three instance wings of [[Dire Maul]] in the middle of the [[Broken Commons]]. Like [[Gurubashi Arena]] in [[Stranglethorn Vale]], entering the Maul flags players for [[PVA]] and allows them to attack and kill other players in the Maul, regardless of faction. When a party is in the Maul, however, you cannot attack members of your party.\r\nSometimes the Maul will be empty, but sometimes there will be an opponent inside for brave gladiators to face: either [[The Razza]], [[Skarr the Unbreakable]] or [[Mushgog]]. When there is something in the Maul, an NPC named [[Griniblix the Spectator]] will enthusiastically yell that it has arrived. He can be heard by anybody inside any part of Dire Maul.\r\nPlayers can enter the Maul either by simply dropping into it or by entering a doorway on the west side of the commons that takes them into a tunnel leading past packs of sleeping Gordok [[hyena|hyenas]] and finally to the fighting area. The tunnel is the only exit from the Maul. It may be most prudent to enter through the tunnel, since dropping down causes the player to take damage from falling and their opponent may attack them before they have recovered their health.",},
			["The Mechanar"] = { content = "#REDIRECT [[Mechanar]]", redirect = "Mechanar",},
			["The Merchant Coast"] = { content = "#REDIRECT [[Merchant Coast]]", redirect = "Merchant Coast",},
			["The Mighty Wind"] = { content = "'''The ''Mighty Wind''''' is a [[zeppelin]] with a goblin crew and orc guards that runs between the western tower outside of [[Orgrimmar]] in [[Durotar]] and [[Warsong Hold]] in [[Borean Tundra]]. \r\n==Crew==\r\n* [[Sky-Captain LaFontaine]]\r\n* [[Grunt Gritch]]\r\n* [[Grunt Grikee]]\r\n* [[Crewman Barrowswizzle]]\r\n* [[Crewman Paltertop]]",},
			["The Might Of The Scourge"] = { content = "==Objectives==\r\n[[The Lich King (Ebon Hold)|The Lich King]] commands you to carry his orders to [[Highlord Darion Mograine]] at [[Acherus: The Ebon Hold|Ebon Hold]].\r\nUse the glowing transporter behind the Lich King to reach Highlord Darion Mograine in the Hall of Command.\r\n==Description==\r\nListen well, death knight, for I give to you the words that will start a war. My final judgment has been passed: Death. To. All. None shall stand so boldly against the might of the [[Scourge]] without reprisal!\r\nAs you have served me well in your first task, so too shall you serve me in your next task. Take my judgment to Highlord Mograine at the command post of Acherus, found on the first floor. Tell him to begin the assault.\r\nAnd when the [[Scarlet Crusade|Crusade]] has been dealt with, we will finish off the [[Argent Dawn]].\r\n==Rewards==\r\nThe following spell will be cast on you: [[Dominion Over Acherus]].\r\nYou will also receive: Bladed Ebon Amulet\r\n==Completion==\r\nThe horns of war will soon echo across this land, waking the dead and calling forth the Scourge war machine. Woe unto those that would stand in our way!\r\nYou and your brethren will lead the charge, <name>. When I next look upon the Scarlet lands, my sights will be obscured by the legions of Acherus. The march upon [[New Avalon]] begins now.\r\n==Notes==\r\nOn completion:\r\n''Highlord Darion Mograine'' calls upon the mighty armies of the Scourge!\r\nHighlord Darion Mograine yells: Armies of the Scourge, hear my call! The scarlet apocalypse has begun! Tear this land asunder and leave only death in your wake!",},
			["The Military Ward"] = { content = "#REDIRECT [[Military Ward]]", redirect = "Military Ward",},
			["The Mind's Eye (Horde)"] = { content = "In '''The Mind's Eye''', you must enter the [[Mosh'Ogg Ogre Mound]] and defeat [[Mai'Zoth]] to obtain the gem known as the Mind's Eye. Once this is complete, you can finally attempt to save [[Yenniku]], the [[Darkspear]] chief's son. This quest is part of a long chain, all available in [[Grom'gol Base Camp|Grom'gol]], the first being Hunt for Yenniku which can be obtained from [[Nimboya]] at the north exit to the camp.\r\n==Objectives==\r\nBring the Mind's Eye to [[Kin'weelay]] at the [[Grom'gol Base Camp]].\r\nYou will need:\r\n* Mind's Eye\r\n==Details==\r\n[[Mai'Zoth]] is at the very bottom of the ogre mound, and has two body guards. [[Mosh'Ogg Ogre Mound|Mosh'Ogg]] is in north-eastern [[Stranglethorn Vale]]. If you can sap/sheep/whatever the two bodyguards, [[Mai'Zoth]] isn't too difficult to take out.\r\n==Description==\r\nThe Mind's Eye is held by an ogre mage, east of here and deep within the Mosh'Ogg ogre mound. His name is Mai'Zoth. I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong.\r\nAnd if he has the Mind's Eye, then his magic will be stronger still.\r\nYou must face Mai'Zoth and wrest from him the Mind's Eye. It is a perilous task, but it is the only hope we have of saving Yenniku.\r\n==Reward==\r\nYou will be rewarded with the following:\r\n* 500-5050 XP\r\n* [[Darkspear Trolls]] +350 rep\r\n==Progress==\r\nGreetings, <name>. The spirits sing praise of your bravery, yet they tell me no tales of your quest against Mai'Zoth.\r\nDo you have the Eye?\r\n==Completion==\r\nYou retrieved the eye! Your might is the stuff of legends, <name>!\r\nAnd in getting the Eye, you must have defeated Mai'Zoth and sent him to the Nether. That is why the spirits would not mention him before.\r\nIt is good that he is gone from the world of flesh and bone, but now that he is in the realm of spirits...I fear he will begin a new reign.\r\nBut that is a worry for another time. Now, I must perform a ritual to bend the Mind's Eye to our needs...",},
			["The Minions of Culuthas"] = { content = "==Objectives==\r\nSlay 10 Hounds of Culuthas and 5 Eyes of Culuthas. Then return to [[Nether-Stalker Nauthis]] at the [[Stormspire]] in the [[Netherstorm]]. \r\n*Hound of Culuthas slain (10)\r\n*Eye of Culuthas slain (5)\r\n== Description==\r\nA few weeks ago, the Burning Legion moved into the [[Ruins of Farahlon]], thwarting our plans to excavate the site for its artifacts.\r\nThen earlier today, I learned that one of their dreadlords, Culuthas, somehow killed off all of the other Burning Legion. He has since summoned in demons that serve him.\r\n<class>, I want you to go up to those ruins to the northeast and rid them of their demon infestation.\r\n== Reward==\r\nYou will receive:4 gold 40 silver copper \r\n== Completion==\r\nTruly an exceptional job.\r\nWith the demons of Culuthas slain, Zephyrion will be able to safely take his excavation team into the Ruins of Farahlon.\r\nAccept this coin as a token of my gratitude. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*12650 [[XP]] (or 7 gold 59 silver copper at level 70)\r\n*250 [[reputation]] with [[The Consortium]]",},
			["The Missing Diplomat"] = { content = "This quest starts the quest chain .\r\n==Objectives==\r\nFind [[Bishop DeLavey]] in [[Stormwind Keep]].\r\n==Description==\r\nExcuse me, <sir/madam>. [[Bishop DeLavey]] asked me to approach adventurers that might be able to help him with a delicate matter.\r\nIf you could quietly head to [[Stormwind Keep]] and speak to him at your earliest convenience, I'm sure he would appreciate your help. Again, please be discreet. It is a matter of some importance.\r\n==Completion==\r\nHello, <name>. I am [[Bishop DeLavey]].\r\nNo doubt if you're asking me about my business here in the keep then young [[Thomas]] has succeeded in requisitioning you to help our kingdom. He has always been adept at following my requests.\r\nI'm afraid I don't have time to elaborate much, so allow me to be blunt... and please, try to keep this from becoming common knowledge.\r\n==Rewards==\r\nUpon completion of this quest you will gain:\r\n*230 [[XP]] (or 1 silver 50 copper at level 70)",},
			["The Missing Diplomat (17)"] = { content = "This quest completes the quest chain .\r\n==Quest text==\r\nLet me be first to thank you for all you've done, <name>. You have been an incredible blessing to my people and the people of [[Stormwind]]. I am sorry I couldn't make your acquaintance under better circumstances.\r\nUnderstand also that I cannot overtly thank you for your efforts, but I assure you again, it is appreciated.\r\nWhen you visit [[Theramore]] in the future, seek me out and I shall try to keep you appraised of the situation.\r\nThank you again, <name>.\r\n==Reward==\r\n* +500 reputation with the [[Alliance]] (all factions)\r\n* 430 [[XP]]\r\n* 1 gold 30 silver \r\n==Notes==\r\n*If Lady Proudmoore teleported away before you could talk to her (or if you were unable to accept her quest for some reason), she can be found in the tower in [[Theramore]].\r\n===After turning in the quest===\r\nIf you talk to Lady Proudmoore again, she says...\r\nHendel is in our custody now, <name>, thanks to you.\r\nAlthough the questioning goes slowly, I assure you, he will tell us everything he knows.\r\nFor now, please be patient. I will contact you immediately if we have need of your assistance.\r\nUntil then, please, enjoy Theramore and I invite you to stay for as long as you like within our city's walls as a friend of the Alliance.",},
			["The Missing Diplomat quest chain"] = { content = "One of our diplomats is missing! You set out to find out what happened to him.\r\nThis quest chain is started by [[Thomas]], an altar boy not far inside the\r\n[[Cathedral of Light]] in [[Stormwind]].\r\n==The Missing Diplomat==\r\n*'''The Missing Diplomat'''\r\nIn the [[Cathedral of Light]], in [[Stormwind City]], you are approached by\r\n[[Thomas]], the altar boy. He tells you that [[Bishop DeLavey]] is looking\r\nfor an adventurer with discretion. Intrigued, you go visiting.\r\nYou cross the city to arrive at [[Stormwind Keep]], where you have an audience\r\nwith the good bishop. \r\n*'''The Missing Diplomat (2)'''\r\nThe bishop tells you that a diplomat sent to [[Theramore]] to meet with\r\n[[Jaina Proudmoore]] never arrived at his destination. The king's agents\r\nare already looking for the diplomat, but the bishop has his own contacts\r\nthat he'd like to involve.\r\nThe bishop hands you a sealed letter, and asks that you deliver it to\r\na fisherman named [[Jorgen]], in the [[Valley of Heroes]], and follow any\r\ninstructions he may have.\r\n*'''The Missing Diplomat (3)'''\r\nJorgen is unhappy about it, but he's obligated to help you. He writes a\r\nletter (sealed) that he wants you to deliver to [[Elling Trias]]. He\r\nemphasizes that he is trusting you to keep this secret.\r\n*'''The Missing Diplomat (4)'''\r\n[[Elling Trias]] is a man with fingers in many cheeses. And to save on\r\ncoin, you are his latest courier. Or agent, or whatever. Elling hands\r\nyou another letter (sealed, of course) to take to [[Watcher Backus]] in\r\n[[Duskwood]]. Ask him about [[Defias]] activity, suggests Elling.\r\n*'''The Missing Diplomat (5)'''\r\n[[Watcher Backus]] greets you cordially enough. And when asked, he does\r\nremember some recent odd Defias activity around [[Addle's Stead]].\r\nIt is a long run to Addle's Stead, but you get there. Sure enough, there\r\nare defias all over the place. Over their objections, you retrieve a\r\ndocket of information from a chest at this hideout, and return with it to\r\nWatcher Backus.\r\nThe watcher verifies that they ''look'' authentic.\r\n*'''The Missing Diplomat (6)'''\r\nAfter looking at the documents only briefly, Watcher Backus hands the docket\r\nback to you, saying it's too complex to be just a red herring. Definitely\r\n\"above his pay grade\". He directs you to take it back to [[Elling Trias]]\r\nin Stormwind.\r\nElling, in turn, reads through the documents himself, and tells you that this\r\nis definitely his area of expertise.\r\n*'''The Missing Diplomat (7)'''\r\nOne of the names in the docket is familiar: [[Dashel Stonefist]], a resident\r\nof the [[Old Town]] district. Elling asks you to follow up on this lead by\r\ntalking to him.\r\n*'''The Missing Diplomat (8)'''\r\nWhen you do, though, [[Dashel Stonefist|Dashel]] takes exception to you prying\r\ninto his business. So much so that he sics his friends on you. You defeat him\r\n(without actually having to kill him), and he calls his friends off.\r\n*'''The Missing Diplomat (9)'''\r\nHis part in the plan was done when Plan A failed due to some adventurers.\r\nPlan B, though, was someone from [[Menethil Harbor|Menethil]] that they'd gotten\r\non the inside. Someone called [[Tapoke \"Slim\" Jahn|Slim]].\r\nNot much, but you take it back to [[Elling Trias|Elling]].\r\n*'''The Missing Diplomat (10)'''\r\nSuprise, suprise, Elling has a contact in [[Menethil Harbor]]. He's since\r\nbecome a bartender, a good profession for knowing things. Elling asks you\r\nto go to the [[Wetlands]] and talk to him.\r\n*'''The Missing Diplomat (11)'''\r\nYou find [[Mikhail]] in the inn in Menethil Harbor. He greets you warmly,\r\nand moreso once you reveal that Elling Trias sent you. As it happens,\r\n[[Tapoke \"Slim\" Jahn]] is in the inn with you, listening intently. As you\r\nnotice him, he decides that discretion is the better part of valor and\r\nattempts to slip out unnoticed.\r\nToo late for him, though. You give chase, and subdue him and an accomplice\r\nin front of the inn.\r\n*'''The Missing Diplomat (12)'''\r\nYou put the question to Slim, and he decides to turn state's evidence,\r\nconsidering the strength of your 'argument' outside.\r\nIt turns out that the diplomat you've been chasing after is none other\r\n[[Varian Wrynn]], the missing king of [[Stormwind]]! Slim's job was\r\nto slip someone named [[Private Hendel|Hendel]] onto the king's ship.\r\nMikhail says he'll pass word back to Elling, and that he has may be\r\nable to help you find this 'Hendel'.\r\n*'''The Missing Diplomat (13)'''\r\nMikhail tells you that he believes that this Hendel was one of the\r\n[[Kul Tiras]] marines who come to Menethil from [[Theramore]] for\r\nleave. [[Commander Samaul]], at [[Theramore]], is the one you need\r\nto talk to about them. While he is loyal to [[Jaina Proudmoore]],\r\nhe will still help you - discreetly - if you mention that\r\n[[Elling Trias]] sent you.\r\n*'''The Missing Diplomat (14)'''\r\n[[Commander Samaul]] is wary, concerned for his troops, but quickly\r\nopens up when you mention Elling. [[Private Hendel]] was stationed\r\nat the first tower out of [[Theramore]], [[Sentry Point]].\r\nYou proceed to Sentry point, then, and meet with [[Archmage Tervosh]].\r\nThe archmage informs you that [[Jaina Proudmoore|Lady Proudmoore]] has\r\nbeen informed of what is going on, and that she has instructed Tavosh\r\nto aid you.\r\n*'''The Missing Diplomat (15)'''\r\n[[Private Hendel]] is to the west, guarding some of Theramore's\r\ninfiltrators who have come back from trying to locate [[Brackenwall]], the local\r\nHorde base. Archmage Tervosh promises to catch up with you for the\r\nshowdown with Hendel, but has business to attend to first.\r\n*'''The Missing Diplomat (16)'''\r\nFinally, you meet the elusive [[Private Hendel]]. A proper soldier, he's\r\na bit busy with his duties. You confront him, and he is outraged.\r\nHe assaults you (and a couple of the nearby guards assist him), but you\r\nmanage to subdue him.\r\n[[Archmage Tervosh]] and [[Jaina Proudmoore|Lady Proudmoore]] arrive, and\r\nyou pass custody of Hendel into their hands.\r\n*'''The Missing Diplomat (17)'''\r\nLady Proudmoore thanks you for your services to the crown and country, offering\r\nyou her signet ring.\r\n==Rewards==\r\n* +1450 [[Stormwind]] reputation\r\n==The Missing Diplomat continuation==\r\nIn [[Patch 2.3]], [[Lieutenant Aden]] in [[Theramore]] continues the Missing Diplomat quest chain when he is informed of a Defias shipwreck off the coast.\r\n# A Disturbing Development\r\n# Defias in Dustwallow?\r\n# Renn McGill\r\n# Secondhand Diving Gear\r\n# Recover the Cargo!\r\n# Jaina Must Know\r\n# Survey Alcaz Island\r\nIn [[Patch 3.0.2]], these two quests (formerly the last two quests in the chain) were removed:\r\n# Warn Bolvar!\r\n# Return to Jaina",},
			["The Mithril Order"] = { content = "This quest unites the [[Horde]] and [[Alliance]] versions of the quest chains.\r\n==Pre-Requisites==\r\n*[[Alliance]] players ust have completed the quest [[Quest:In Search of Galvan|In Search of Galvan]]\r\n*[[Horde]] players ust have completed the quest [[Quest:Booty Bay or Bust!|Booty Bay or Bust!]]\r\n==Objectives==\r\nSpeak with [[Galvan the Ancient]] in [[Stranglethorn Vale]].\r\n* Mithril Pendant (provided)\r\n==Quest text==\r\nMost of our recruits never make it to Booty Bay, <name>. The shine\r\nof the insignia is enough to trigger the loot lust in even the staunchest\r\nof blacksmiths. Fools they be, as the insignia is a drop in the bucket\r\ncompared to the wealth of items you'll see!\r\nFind [[Galvan the Ancient]] and show him this pin. His residence is far\r\nto the north, between [[Zul Gurub]] and the [[Mosh'Ogg Ogre Mound|Mosh'Ogg ogre mound]].\r\n==Completion==\r\nAh, many years it has been since one has been worthy of the Mithril Order's initiation. We will start now!\r\n==Reward==\r\n*3150 experience (or a 26 40 compensation at level 70)\r\n==Notes==\r\nThe follow-up quests are independent of each other. They can be completed in any order.\r\nEach yields a reward needed to complete a later quest.\r\n \"Smelt On, Smelt Off\", The Great Silver Deceiver, The Art of the Imbue",},
			["The Molsen Farm"] = { content = "#REDIRECT [[Molsen Farm]]", redirect = "Molsen Farm",},
			["The Molten Bridge"] = { content = "#REDIRECT [[Molten Bridge]]", redirect = "Molten Bridge",},
			["The Molten Core (quest)"] = { content = "==Pre-requisites==\r\n* Poisoned Water\r\n* Stormers and Rumblers\r\n** Eye of the Emberseer\r\n==Task==\r\nKill 1 [[Firelord]], 1 [[Molten Giant]], 1 [[Ancient Core Hound]] and 1 [[Lava Surger]], then return to [[Duke Hydraxis]] in [[Azshara]].\r\n==Quest text==\r\n''<name>, perhaps it is time to give you a real test. Are you ready?''\r\n''At the bottom of Blackrock Depths is a passage to the Molten Core. This is a stronghold of our enemy, held by the most powerful servants of fire on this world.''\r\n''Go to the Molten Core, <name>. Show me you have the strength and the will to defeat what you find there.''\r\n''And if you have allies among your people, then rally them. Nothing short of an army can hope to enter the Molten Core and live.''\r\n==Reward == \r\nExperience and/or gold.\r\n==Notes== \r\nIf you have a fresh [[Molten Core]] instance this quest can be completed before you get to the first boss.\r\nThis quest is part of a chain.\r\n*Poisoned Water / Stormers and Rumblers\r\n**Eye of the Emberseer\r\n**The Molten Core\r\n**Agent of Hydraxis\r\n***Hands of the Enemy\r\n***A Hero's Reward",},
			["The Molten Span"] = { content = "#REDIRECT [[Molten Span]]", redirect = "Molten Span",},
			["The Mor'shan Rampart"] = { content = "#REDIRECT [[Mor'shan Rampart]]", redirect = "Mor'shan Rampart",},
			["The Mystic Ward"] = { content = "#REDIRECT [[Mystic Ward]]", redirect = "Mystic Ward",},
			["The Natural Ward"] = { content = "'''The Natural Ward''' is an epic ring that grants a stamina bonus as well as a significant amount of nature resistance.\r\n==Source==\r\nThis item is crafted by [[Jewelcrafting|Jewelcrafters]] with a skill level of 375.\r\nThe components are:\r\n*4 x Mercurial Adamantite\r\n*2 x Felsteel Bar\r\n*6 x Primal Life\r\n*6 x Primal Shadow\r\nDesign: The Natural Ward is sold by [[Fedryen Swiftspear]] in the [[Cenarion Refuge]] in [[Zangarmarsh]]. The design costs 12 gold . You must be with the [[Cenarion Expedition]] to purchase this design.\r\n==Notes==\r\nThis ring provides more nature resistance than any ring currently in the game.",},
			["The New Horde"] = { content = "'''\"The New Horde\"''' is a section of the [[History of Warcraft]], Chapter IV. It is set after ''[[Warcraft II: Beyond the Dark Portal]]'', and recounts the events of the novel ''[[Lord of the Clans]]''.\r\nFound at:\r\n* Tower of [[Northwatch Hold]] in [[Barrens|The Barrens]].\r\n* The [[Royal Library]] of [[Stormwind Keep]] in [[Stormwind]].\r\n* [[Stonard]] in [[Swamp of Sorrows]] - building with the trainers\r\nTimeline: \r\n* ← Previous book: [[Lethargy of the Orcs]]\r\n* → Next book: [[War of the Spider (History of Warcraft)|War of the Spider]]",},
			["The Nexus"] = { content = "#redirect [[Nexus (instance)]]", redirect = "Nexus (instance)",},
			["The Nightmare"] = { content = "#redirect [[Emerald Nightmare]]", redirect = "Emerald Nightmare",},
			["The Night Watch"] = { content = "#redirect [[Night Watch Militia]]", redirect = "Night Watch Militia",},
			["The North Coast"] = { content = "#REDIRECT [[North Coast]]", redirect = "North Coast",},
			["The North Sea"] = { content = "#redirect [[North Sea]]", redirect = "North Sea",},
			["The Noxious Glade"] = { content = "#REDIRECT [[Noxious Glade]]", redirect = "Noxious Glade",},
			["The Noxious Lair"] = { content = "#REDIRECT [[Noxious Lair]]", redirect = "Noxious Lair",},
			["The Oathkeeper"] = { content = "==Source==\r\nThis item is a world drop.\r\nThis item could be a reference to The Oathkeeper keyblade from the game Kingdom Hearts",},
			["The Oculus"] = { content = "#REDIRECT [[Oculus]]", redirect = "Oculus",},
			["The Old Gods and the Ordering of Azeroth"] = { content = "'''\"The Old Gods and the Ordering of Azeroth\"''' is a section of the [[History of Warcraft]], Chapter I.\r\nFound at:\r\n* The [[Apothecarium]] of [[Undercity]] - near Herbalism trainers\r\n* The Domicile section of [[Blackrock Depths]]\r\n* [[Darnassus]] - next to [[Argent Guard Manados]] \r\n* The [[Hall of Explorers]] in [[Ironforge]].\r\n* [[Menethil Harbor]] in the [[Wetlands]], inside Menethil Keep.\r\n* [[Scholomance]] in the [[Western Plaguelands]].\r\nTimeline: \r\n* ← Previous book: [[Sargeras and the Betrayal]]\r\n* → Next book: [[Charge of the Dragonflights]] \r\n==See also==\r\n* [[Old Gods]]\r\n* [[Elemental Lord]]\r\n* [[Earthen]]\r\n* [[Sea Giants]]\r\n* [[Well of Eternity]]",},
			["The Ongar"] = { content = "'''The Ongar''' is a level 51 [[rare mob]] [[ooze]] found in [[Felwood]].",},
			["The Opening of the Dark Portal"] = { content = "#redirect [[The Opening of the Dark Portal]]", redirect = "The Opening of the Dark Portal",},
			["The Oracles"] = { content = "#REDIRECT [[Oracles]]", redirect = "Oracles",},
			["The Oracle Glade"] = { content = "#REDIRECT [[Oracle Glade]]", redirect = "Oracle Glade",},
			["The Overlook"] = { content = "#REDIRECT [[Overlook]]", redirect = "Overlook",},
			["The Overlook Cliffs"] = { content = "#REDIRECT [[Overlook Cliffs]]", redirect = "Overlook Cliffs",},
			["The Pack Mistress"] = { content = "'''The Pack Mistress''' sends the players into [[Lower Blackrock Spire]] to find and defeat [[Halycon]], the den mistress of the worgs.\r\n==Objectives==\r\nSlay [[Halycon]], pack mistress of the Bloodaxe worg. \r\n==Description==\r\nSome say the worg controlled by the Blackrock orcs are the creation of a supernatural force. Others say they are not true worg but instead a breed of demon dog, granted to the orcs by a fallen pit lord.\r\nThe truth is far less contrived but every bit as frightening. The worg of Blackrock come from Halycon and her mate. Halycon is the gigantic den mother of the worg. Her mate? Nobody has ever lived to tell the tale of that one.\r\nStrike at the heart of the worg. Destroy Halycon... and <name>, watch your back.\r\n==Details==\r\nHalycon is surrounded by several non-elite pups which can be easily managed. When she dies, she will cry and and summon her mate, [[Gizrul the Slavener]]. He will arrive after a little while so a good plan is to run to the back of the room after Halycon dies. Gizrul will aggro if everyone is at the back of the room. Once everyone is healed up, you can take on Gizrul.\r\n==Reward==\r\nYou will be allowed to choose one of the following:",},
			["The Park"] = { content = "#REDIRECT [[Park]]", redirect = "Park",},
			["The Part-time Hunter"] = { content = "==Objectives==\r\nBring [[Razorpine]]'s Remains to [[Tamara Wobblesprocket]] at [[Lakeside Landing]].\r\n* Razorpine's Remains\r\n==Description==\r\nWhen [[Hemet Nesingwary|Hemet]] asked me to accompany [[Marvin Wobblesprocket|Marvin]] out here, I hoped that I might have the opportunity to work on my own hunting skills in between repairing the flying machines and setting up the camp.\r\nI wanted to take down a nasty bristlepine called Razorpine. He's said to make his home south of here, near where the [[Wildgrowth Mangal]] meets the northern face of the [[Skyreach Pillar]]. If you can find the beast, would you bring back his remains? If the rumors are true, they'd make a trophy even Hemet will respect! \r\n==Rewards==\r\nYou will receive: 6 gold 20 silver \r\n==Progress==\r\nDid you find Razorpine?\r\n==Completion==\r\nYou got it! Now all I have to do is make a trophy out of it. That'll be the hard part -- finding a way to preserve it so that Hemet doesn't have a good laugh at my expense.\r\n==Notes==\r\nWhen you find Razorpine you'll find it surrounded by three [[wolvar]] of the [[Frenzyheart Tribe]]. [[Tracker Gekgek]] will curse you for stealing the kill of the boar, and gives you the quest Playing Along.\r\nThe quest mob is currently bugged in beta as of build 8770, and the mob who drops the quest item is [[Pitch]].",},
			["The Path of Anguish"] = { content = "#REDIRECT [[Path of Anguish]]", redirect = "Path of Anguish",},
			["The Path of Conquest"] = { content = "#redirect [[Path of Conquest]]", redirect = "Path of Conquest",},
			["The People's Militia"] = { content = "#REDIRECT [[Westfall Brigade]]", redirect = "Westfall Brigade",},
			["The Perfect Poison"] = { content = "==Objectives==\r\nDirk Thunderwood at Cenarion Hold wants you to bring him Venoxis's Venom Sac and Kurinnaxx's Venom Sac.\r\nItems Needed:\r\n*[[Venoxis's Venom Sac]]\r\n*[[Kurinnaxx's Venom Sac]]\r\n==Quest Text==\r\nMy brother and I run the poison operations out of the manor Ravenholdt.\r\nLord Ravenholdt tasked me to track down a new and extremely effective poison compound that can be crafted from the venom sacs of the inhabitants of Zul'Gurub and the Ruins of Ahn'Qiraj.\r\nThere are two particularly venomous beasts residing in those blasted ruins that possess what it is that we might be looking for, <Class>. Bring me a venom sac from the beasts Kurinnaxx and Venoxis and we would be eternally grateful.\r\n==Details==\r\nThe venom sacs are obtained from [[Kurinnaxx]], the first boss in the [[Ruins of Ahn'Qiraj]] and [[Venoxis]], one of the easier bosses in [[Zul'gurub]].\r\n==Reward==\r\nYou will gain:\r\n*+250 reputation with [[Cenarion Circle]]",},
			["The Phylactery of Kel'Thuzad"] = { content = "'''The Phylactery of Kel'Thuzad''' is a quest item dropped each time [[Kel'Thuzad]] is killed in [[Naxxramas]] (similar to the [[Head of Onyxia]], [[Heart of Hakkar]], etc.). \r\n==Rewards==\r\nThere's a choice of two rewards from the quest The Fall of Kel'Thuzad, one trinket for physical damage and one for magic damage.",},
			["The Pillar of Ash"] = { content = "#redirect [[Pillar of Ash]]", redirect = "Pillar of Ash",},
			["The Platinum Discs (Alliance)"] = { content = "==Objectives==\r\nTake the miniature version of the Discs of Norgannon to the Explorers' League in [[Ironforge]]. \r\n*Miniature Platinum Discs (Provided)\r\n== Description==\r\nTouching the Discs of Norgannon once again makes your hand tingle. This time, however, a strange grinding noise is heard from inside the discs.\r\nYour backpack suddenly becomes heavier than it was before. Inside, you discover a miniature version of the discs!\r\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth. The Explorers' League in [[Ironforge]] is such a group, known throughout the Alliance; perhaps they can make good use of it. \r\n== Progress==\r\nYes, may I help you with something? I assure you I am a very busy right now. If it is grave importance to the Explorers' League, however, then I am all ears! \r\n== Completion==\r\nWhat do you have there... oh my. You found this where?\r\nNo, really?\r\nYou spoke to whom about what?\r\nNO, REALLY?!\r\nMy fine <class>, you may have just made the archaeological find of the year! By the Gods who am I kidding, the find of the century! If these discs are what I think them to be, then this could be the very key we have been looking for! This may well prove outright once and for all the legitimacy of the Dwarves' enchanted creation! \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*5250 [[XP]] (or 31 silver 50 copper at level 70)\r\n*350 [[reputation]] with [[Ironforge]]",},
			["The Platinum Discs (Horde) (1)"] = { content = "==Objectives==\r\nTake the miniature version of the Discs of Norgannon to the one of the sages in [[Thunder Bluff]]. \r\n* Miniature Platinum Discs (Provided)\r\n== Description==\r\nTouching the Discs of Norgannon once again makes your hand tingle. This time, however, a strange grinding noise is heard from inside the discs.\r\nYour backpack suddenly becomes heavier than it was before. Inside, you discover a miniature version of the discs!\r\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth. The sages of [[Thunder Bluff]] are such historians, known throughout the Horde; perhaps they can make good use of it. \r\n== Progress==\r\nYes young one, I see you marching into my tent with intensity in your stride... with determination in your purpose. You seek my counsel is some matter of grave importance to the Horde? Perhaps you wish a mystery of the universe revealed to you? \r\n== Completion==\r\nWhat are these here then?\r\nImpressive, young one! These discs, in them I sense secrets that the earth has held on to tightly for many years. You were very wise to bring them here to me. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*5250 [[XP]] (or 31 silver 50 copper at level 70)\r\n*350 [[reputation]] with [[Thunder Bluff]]",},
			["The Platinum Discs (neutral)"] = { content = "==Objectives==\r\nSpeak with stone watcher and learn what ancient lore it keeps. Once you have learned what lore it has to offer, activate the Discs of Norgannon. \r\n*[[Lore Keeper of Norgannon|Learn what lore that the stone watcher has to offer]]\r\n== Description==\r\nThe centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin. Touching them makes your hand tingle. Just after touching the discs, the visage of a large stone watcher springs forth.\r\n\"Salutations. I am a keeper of knowledge. The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"\r\nYou have uncovered a wealth of previously undiscovered worldly lore! \r\n== Completion==\r\nFollowing the instructions of the stone watcher, you once again access the Discs of Norgannon now that you have learned about the history of the Earthen, the troggs, and the dwarves. A faint, brief hum is heard from within the discs. The stone watcher then speaks:\r\n\"The discs have now been synthesized. Access the Discs of Norgannon once more to receive your personal copy.\" \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*4200 [[XP]] (or 25 silver 20 copper at level 70)",},
			["The Princess's Surprise"] = { content = "==Objectives==\r\nReturn to [[Ironforge]] and speak with [[King Magni Bronzebeard]]. \r\n== Description==\r\nThaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child!\r\n<You think that Princess Bronzebeard may still be suffering from the residual effect of the Emperor's spell.>\r\nReturn to [[Ironforge]] and tell my father that the heir to the Kingdom of [[Ironforge]] will be a Dark Iron dwarf.\r\nWhether he approves or not, it shall be. \r\n== Reward==\r\nYou will also receive:2 gold 65 silver copper \r\n== Completion==\r\n<King Magni Bronzebeard is visibly upset.>\r\nIt seems that even in death, Thaurissan has won.\r\nYou are dismissed, <name>. Before you leave, you may choose your reward from the royal vault.\r\n<King Bronzebeard slumps into his throne to mull over this bizarre change of events.> \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*9650 [[XP]] (or 58 silver 50 copper at level 70)",},
			["The Prison's Bindings"] = { content = "==Objectives==\r\nTravel to [[Dire Maul]] in [[Feralas]] and recover 15 [[Satyr Blood]] from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done. \r\n* Satyr Blood (15)\r\n== Description==\r\nYou must retrieve bindings for the prison of the Doomguard from lesser demons.\r\nThe blood of the Wildspawn satyr that occupy Warpwood Quarter inside Dire Maul should do nicely. The coagulated blood will bond the Hederine shards and power the crystal prison.\r\n== Progress==\r\nOnly the blood of Wildspawn satyr will suffice. \r\n== Completion==\r\nAh, a most excellent recovery. The blood will suppress the Doomguard's magical defenses. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*6600 [[XP]] (or 11 gold 40 silver copper at level 70)\r\n==Notes==\r\nAs Burning Crusade has obsoleted the higher-end Azeroth dungeons, current players may not know that although the quest text states to go to the [[Warpwood Quarter]] that said area can be found in Dire Maul East.",},
			["The Prison's Casing"] = { content = "==Objectives==\r\nTravel to Darkwhisper Gorge in [[Winterspring]] and recover 5 [[Tears of the Hederine]] from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task. \r\n* Tears of the Hederine (5)\r\n== Description==\r\nThe Hederine demons that occupy the foothills of Mount Hyjal secrete powerful fel poisons, which if left to mature, harden into a dense anti-magic crystal. These crystals have come to be known as [[Tears of the Hederine]].\r\nNot even the immense power of a Doomguard could break the walls of a prison constructed from this material.\r\nTravel to Darkwhisper Gorge in [[Winterspring]] and recover the Tears. \r\n== Progress==\r\nThe Hederine will not give up their precious gems without a fight, <name>. \r\n== Completion==\r\nI merely need to combine the blood of the Wildspawn with these crystals and the prison shall be ready for use. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*6600 [[XP]] (or 39 silver copper at level 70)",},
			["The Prophecy of C'Thun"] = { content = "'''The Prophecy of C'Thun''' written by the Qiraji Prophet [[Skeram]]. The player of [[World of Warcraft]] is introduced to this prophecy by Geologist Larksbane.\r\nBelow is an extract of this story as told by Geologist Larksbane.\r\n----\r\n\"It is history... A history of [[Silithus]]... of [[Ahn'Qiraj]]... of [[Titan]]s and [[Old God]]s... I read from the Prophecy of C'Thun as written by the Qiraji Prophet [[Skeram]]. A prophecy that portends a cataclysm... \r\nIn the time before time, when the world was still in its infancy, a battle between a Titan and a being of unimaginable evil and power raged on this very soil. The prophecy is unclear about whether or not the Titan was vanquished in this battle but it illustrates that a Titan fell. An Old God had also fallen - or so it was thought.\r\nThe land of eternal starlight, [[Kalimdor]], was a nurturing mother to all of its creatures. The magic of the [[Well of Eternity]] permeated the land and empowered the multitude of flora and fauna that would make the world their home. From this magical ether were born the [[Silithid]]. It was through the Silithid that the brooding Old God would reach and attempt to sunder the world that it once held in its unmerciful grasp.\r\nThe Old God would create avatars from the Silithid in its own image. These avatars were to be known as [[Qiraji]]. Sapient and with purpose, the Qiraji would name their creator: [[C'Thun]] was born... For many thousands of years the Qiraji worked feverishly to build a force capable of laying waste to the world that would betray their god. The great fortress city of Ahn'Qiraj was created to house their growing armies and prepare for the coming of C'Thun.\r\nThe moment that C'Thun had so patiently waited for had finally arrived. His children had spent thousands of years building an army capable of exacting revenge upon the whole of Kalimdor and now the prize was withing their grasp.\r\nThe Titans had long since vacated this world. Only the [[Night Elves]] that once inhabited this area were here to defend. A mighty Qiraji known as [[Rajaxx|General Rajaxx]] would command the initial incursion into Silithus. Only one would stand in his way: A Night Elf known as [[Fandral Staghelm|Staghelm]]. They refer to him as [[Kar'sis]] or 'hand of the earth' in the native Qiraji tongue.\r\nStaghelm and his armies were clearly overwhelmed as the endless flow of Rajaxx's troops poured into Silithus. It would seem as if Staghelm, however, was more than just a nuisance to the Qiraji. Under Staghelm, the whole of the Night Elf armies had come together to defend Kalimdor, greatly slowing the Qiraji forces.\r\nUnfortunately, the Night Elf defense was untenable and Rajaxx knew that they could not hold out much longer. Their tenacity, however, was causing great frustration to Rajaxx and causing even more frustration to his king.\r\n[[Vek'nilash]] and [[Vek'lor]], known as the [[Twin Emperors]] of Ahn'Qiraj, watched the war from the sanctuary of their temple. The clever brothers devised a plan to demoralize and divide Staghelm's forces.\r\n[[Valstann Staghelm]] served as the right hand of [[Fandral Staghelm|Fandral]]. A proud and noble warrior, his dedication and adoration for his father unyielding.. and the Twin Emperors sensed this as weakness. A weakness that could be exploited. The Qiraji forces were commanded to fall back and hide the bulk of their numbers beneath the sands of the desert. A small attack was ordered upon [[Southwind Village]] while the front lines of Staghelm's army were kept occupied.\r\nValstann, eager to please his father, convinced Fandral to allow him to take a small battalion to the defense of Southwind. Surely with the tide of battle turning their way, no harm could come to his beloved child. The trap was missed. Valstann was captured by the hiding Qiraji and Southwind Village obliterated. Rajaxx himself would take the captive Valstann to the front lines of the battle where - in front of Staghelm and the Night Elf forces - he would brutally execute the young Night Elf.\r\nThe war continued but the will of the great leader was sapped. The whole of Silithus was soon engulfed by the Silithid and their Qiraji hosts. The Night Elf army was pushed back through [[Un'Goro Crater|Un'Goro]], to the borders of the [[Tanaris]] desert. Something in Un'Goro prevented the Qiraji from being able to take the land. I do not quite understand this word but I believe it to mean 'God Lands.' It is stated that they could not 'take the God Lands.' This coincides with theories of Un'Goro being the home of the Titans when they inhabited Kalimdor. Perhaps [[Aman'Thul|Aman'thul]] himself watched over 'The God Lands.'\r\nHrm, curious.. This ends abruptly. In Tanaris the Qiraji document facing a [[bronze dragon]]. There is much missing from this... More information must be found! Surely they are planning to invade Kalimdor once more!\"\r\n----\r\nOnce Geologist Larksbane is done talking, the Night Elf Baristolth of the Shifting Sands shifts around before saying:\r\n\"When the time is right, my lady. All will be clear when the time is right. The master stirs even now. Look to the skies for the Brood of [[Nozdormu]] have returned.\"\r\n==Sources==\r\n''The Blizzplanet article misspells Geologist Larksbane as Geologist Laksbane.''",},
			["The Prophecy of Mosh'aru"] = { content = "The Prophecy of Mosh'aru is the 2nd quest in the '''Screecher Spirits''' quest chain.\r\n==Objectives==\r\nBring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.\r\n* First Mosh'aru Tablet\r\n* Second Mosh'aru Tablet\r\n==Description==\r\nThe ancient prophecy of Mosh'aru speaks of a way to contain the god Hakkar's essence. It was written on two tablets and taken to the troll city of [[Zul'Farrak]], west of [[Gadgetzan]].\r\nBring me the Mosh'aru tablets!\r\nThe first tablet is held by the long-dead troll Theka the Martyr. It is said his persecutors were cursed into scarabs and now scuttle about his shrine.\r\nThe second tablet is held by the hydromancer Velratha, near the sacred pool of Gahz'rilla.\r\nWhen you have the tablets, bring them to me.\r\n==Progress==\r\nDo you have the tablets of the Prophecy of Mosh'aru, <name>?\r\nWhen I gain the tablets, I will study them, and learn how to contain the essence of Hakkar!\r\n==Completion==\r\nAh, this is good. I can fuse these ancient tablets together, and then study their hidden secrets.\r\nMy debt to you grows, <name>. And it will grow further still.\r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*9050 [[XP]] (or s=54 gold at level 70)\r\n==Quest chain==\r\n#Screecher Spirits\r\n#The Prophecy of Mosh'aru\r\n#The Ancient Egg\r\n#The God Hakkar",},
			["The Prophet Skeram"] = { content = "'''The Prophet Skeram''' is an important religious leader in [[Ahn'Qiraj]]. He is the author of the [[Prophecy of C'Thun]]. He is the first boss found in the [[Temple of Ahn'Qiraj]].\r\n==Attacks and Abilities==\r\n*Basic Melee attack for about 700 - 1000 damage.\r\n*True Fulfillment, which [[Mind Control]]s a target, and gives them increased damage, higher resistances, faster movement and instant-cast spells. The target also grows to an immense size, so it is easy to see who is being controlled. The effect cannot be dispelled, but targets can be sheeped, feared, stunned, or put to sleep if a Druid is in an animal form. \r\n*Quartile Split. At 75%, 50%, and 25%, creates two images that have identical abilities to Skeram. The images spawn with the same percentage of life as Skeram, but they do not have as many hit points as the true Prophet, making them much easier to kill. As of patch 2.0.1, raid marks will be removed if they were put on the boss before, so the identity of the real boss will not be immediately given away.\r\n*[[Arcane Explosion]] (1.5K, large radius). It can be interrupted. He only casts it if there are more than four people in melee range of him. Casting speed can be slowed by [[Curse of Tongues]] and [[Mind-Numbing Poison]].\r\n*[[Earth Shock]] (2.5K), once every second until his aggro target is in melee range. This is generally lethal unless the target has NR. Skeram will start casting earth shock on the person that is highest on his aggro list ONLY, if this person is not in melee range AND MELEEING HIM. If he is tanked correctly and the current aggroholder stays within melee range, no earth shock will be fired. He does not do this randomly; Earth Shock spam is a sign that the tanks are not reacting fast enough.\r\n*[[Blink]]s to either platform beside him, clearing [[aggro]].\r\nAs of patch 1.12, aggro rules changed. As such, Arcane Explosion is not guaranteed for 4+ people, and it could happen for less people present as well.\r\n==Strategy==\r\nThe first boss encounter is a short jog from the entrance of the zone, five trash pulls away. The trash consists of three individual [[Obsidian Eradicator]] and two groups of [[Anubisath Sentinel]] x4. He was previously about as difficult as [[Majordomo Executus]] from the [[Molten Core]], but with the buff he received in 1.12 he is somewhat more difficult. Similar to Executus, the Prophet Skeram requires skill and strategy to beat over quality of gear. Most guilds that have considerable progress in [[Blackwing Lair]] can handle this boss. He has very little health; approximately 300,000.\r\n'''Raid Makeup''': 5 of each class would be recommended, and at least three Warriors geared as [[Main Tank]]s. Ideally, 6 Warriors and/or Feral Druids (two for each teleport spot) will allow all the Prophet's Images to be tanked, even if they all are using Mind Control on a tank. It is key that these tanks do not move from their assigned location, and if Mind Controlled, they return to their spot.\r\n'''Raid Placement''': When the Prophet splits into the three, they will initially all Blink to separate spots, and must be immediately tanked before he starts spamming Earth Shock. The easiest method to control this is to have two tanks at each of the three Blink point (Middle, and Left/Right stairs), so that if one is Mind Controlled, the other can still pick up the mob. Skeram and his images may Blink and group up in one of the three locations, so healers need to be alert and tanks must immediately pick up the new mob.\r\nThe Rogues should split up and put at the three Blink locations as well, but remember to keep a maximum of four players at each Blink location, to avoid the Arcane Explosion. The Healers should also be split into roughly 3 groups, to heal the three melee groups, and to spot heal the rest of the raid. All of the rest of the ranged DPS should head to the top of the steps and move back and forth as Skeram Blinks to a new location. \r\nMages have a specific role however, their main job is to [[Polymorph]] anyone that gets Mind Controlled. They should split up and take positions along both sides of the steps so they can have the best [[LoS]] possible. They may go on DPS as long as there are no players to sheep. One Warlock, on each side as backup, can help by fearing players as well.\r\n'''Alternate Strategy''': This strategy is a little more specific about placement. It requires a minimum of 6 warriors but is much more likely to be successful. \r\n''Tanks'': Tanking is a very important part of this fight, it requires quick thinking and response. Raid leaders, give each of the six tanks his/her own MT window in CT_RaidAssist. Tell everyone in the raid that MT1 and MT2 will be in the middle platform for the full duration of the fight. MT3 and MT4 will be on the left platform. Finally, MT5 and MT6 will be on the right platform. Designate MT1 to be the first to run in when the fight starts and begin tanking as usual. When Skeram is blinking regularly (not splitting), only MT1, MT3, and MT5 will taunt him when he comes to their platform. The secondary tanks (MT2, MT4, MT6) will ONLY autoattack when a single Skeram is on their platform. The main job of the secondary tanks at each platform is to watch carefully during a Skeram split for when a second image blinks on top of one while it's already being tanked. Have that secondary tank immediately identify the second image and taunt him as quickly as possible to avoid earth shocks, then drag him to another platform carefully, and have the main tank (MT1, MT3, MT5) of that platform pick it up. During a split, have the tanks call out if he is tanking an image or the real Skeram, call DPS to start immediately on the first identified as an image. \r\n''Rogues'': Split your rogues up through this fight to have as few on each platform as possible. The rogues should also stand inside Skeram in front of the tank. The rogues will always be mind controlled before the tank if this is done correctly. If you have 3 rogues in the raid, assign each one specifically to stay at either the middle, left, or right platform for the whole fight, they should not move between platforms. If you have more than 6 rogues, with the way this strategy is set up, it can be very dangerous due to Skeram's arcane explosion. At the very least, have them apply mind numbing poison to one of their weapons, and be ready to kick at all times as soon as they see him casting arcane explosion.\r\n''Healers'': There should be three groups made up of ''Tank, Tank, Priest, Druid, Shaman/Paladin''. This allows the healers to take a position relative to the tank that allows them to always be ready to heal the tanks in their group. All healers that are not in one of these 3 groups should be spread out, ready to spot heal when needed.\r\n''Other ranged dps'': Warlocks, hunters, etc should be split up on the staircases as well, even positioned above the middle platform where they could shoot down on the platform while still being able to move to another location quickly when he blinks.\r\nExample fight: Ready check (trash respawns fast, AFKs could mean a wipe); everyone mounts on a Qiraji Battletank if available; Skeram is engaged regularly, MT1 moves into position and begins tanking while the rest of the raid takes their position. After 30 seconds or so, Skeram blinks to the left platform, MT3 taunts and begins building aggro regularly. At this point, MT4 is only autoattacking, not sundering or taunting at all. Later into the fight, when he hits 75%, The three images split up and MT1, MT3, and MT5 taunt their images immediately, MT2, MT4, and MT6 begin autoattacking. MT5 calls out that he noticed his Skeram image taking more damage than normal, he calls that out, raid leader calls DPS on the right platform. Before that image is killed, it blinks to the middle, on top of the image that was already there. This is where MT2 comes in, he taunts the image that just blinked and begins moving it back to the right-side platform, where MT5 will taunt it and MT2 will move back to his position in the middle. Repeat this throughout the fight and it should be kept under control, and you'll get a nice, clean kill. Good luck everyone!\r\n===The Split===\r\nThe most important aspect of this encounter is the splitting that the Prophet will do at 75%, 50%, and 25%. Once he reaches each of these levels of health, he will disappear for a moment, and then three new Prophets will appear, only one of which is the real boss, and initially all in separate Blink locations. The illusions themselves can also Blink to the other locations, often stacking on one another. This is another reason why two tanks in each corner are essential, because if two Prophets are in a corner, a tank is almost guaranteed to become Mind Controlled. If this does happen, try to have an extra tank run in to take up the extra spot, or have one tank from the now vacant corner run over and try to pick up the slack.\r\nSince the 2.0.1 patch Raid Target markers on The Prophet Skeram will be removed when he splits, so the DPS will need to figure out which one is real from the amount of damage they are doing. While the raid kills the two illusions, mages must continue casting polymorph on anyone who is affected by Mind Control.\r\nSpeed is of the essence at these three points in the encounter. Everyone will be scrambling to do their job, and if players are slacking, tanks will die from the extra damage, or non-sheeped Mind Controlled players will start 1 or 2-shotting individuals in the raid.\r\n===Tips===\r\n*Healers and Ranged DPS can jump onto and stand on the railings up to the third level. This may cause some LoS issues when trying to sheep and/or fear the Mind Control targets, but allows them to attack the Prophet when he is in the center, as well as their corresponding side.\r\n*If you have difficulties finding out which one is the real Skeram when he splits, let an assigned [[Hunter]] send his [[Pet]] in at 77%, 52%, 27% to attack the boss. When Skeram splits into three, the pet will be attacking the real one. Also if you were targeting the real prophet he will remain targeted after a split.\r\n*Have your Warlocks use their [[Soulstone]] on one of the 6 tanks. They are the key to avoiding wipes, not DPS or healing.\r\n*The Mind Control affects the person nearest to Skeram, another way to ensure your tank never gets Mind Controlled is to have a weaponless [[Rogue]] stand underneath Skeram when he is being tanked. Be very careful when he teleports or splits as not to be the nearest to him until the tank picks him up as that will kill the rogue very quickly.\r\n===Wipe Warning===\r\nWhen you are learning the encounter, or having a particularly bad raid, and are wiping on the Prophet, be aware of the respawn time on the [[Obsidian Eradicator]] which patrols the area around Skeram. The respawn on all the trash up to the Prophet is 30 minutes, so unless you are extremely quick at killing the trash, and wiped really quick on the Prophet, it is best for the raid simply to wait for all the respawns before you start another attempt.\r\n==Quotes==\r\n* \"Are you so eager to die? I will be happy to accommodate you...\"\r\n* \"Let your death serve as an example!\"",},
			["The Prophet Tharon'ja"] = { content = "'''The Prophet Tharon'ja''' is the last boss of [[Drak'Tharon Keep]]. He is a large skeletal Windserpent, much like the [[Avatar of Hakkar]].\r\n==Tactics==\r\nHe begins the fight as a skeletal serpent with a few abilities: \r\n*Shadowbolt (2000 damage)\r\n*Curse of Life (Drains 50% of the enemy's health.) \r\nAt certain intervals he uses Decay Flesh, sucking the player's lives and turning him into a mortal Windserpent while turning the players into undead skeletons\r\nWhen in this form, the skeleton players have four spells: \r\n*Touch of Life: Instant cast, 20 yard range, steals 1900 to 2100 life from target enemy. 5 second cooldown. \r\n*Bone Armor: Instant cast, encases the caster in bone armor, absorbing 4163 to 4837 damage for 10 sec. While the armor holds, spellcasting cannot be interrupted by physical attacks. 10 second cooldown. \r\n*Taunt: Instant cast, 10 yard range, taunts the creature, increasing the chance that it will attack the caster. \r\n*Slaying Strike: Instant cast, 8 yard range, requires melee weapon, inflicts normal damage plus 602 to 698 to an enemy. 1 sec cooldown. \r\nAfter a certain percentage of damage is done in this form, everyone switches back. The cycle repeats until he is dead. \r\n==Quotes==\r\nUpon aggroing: \r\n* \"Tharon'ja sees all! The work of mortals shall not end the eternal dynasty!\"\r\nCasting Decay Flesh: \r\n* \"Your flesh serves Tharon'ja now!\"\r\n* \"Tharon'ja has a use for your mortal shell!\"\r\nUpon slaying a player:\r\n* \"As Tharon'ja predicted.\"\r\n* \"As it was written.\"\r\nWhen players turn into skeletons:\r\n* \"No! A taste... all too brief!\"\r\n* \"Tharon'ja will have more!\"\r\nUpon death: \r\n* \"Im... impossible! Tharon'ja is eternal! Tharon'ja... is...\"",},
			["The Proving Grounds"] = { content = "#redirect [[Proving Grounds]]", redirect = "Proving Grounds",},
			["The Purple Princess"] = { content = "'''''The Purple Princess''''' is a [[zeppelin]], with a goblin crew and troll guards, which runs between [[Brill]] in [[Tirisfal Glades]] and [[Grom'gol Base Camp]] in [[Stranglethorn Vale]].\r\n==Crew==\r\n* [[Sky-Captain Cableclamp]]\r\n* [[Chief Officer Hammerflange]]\r\n* [[Navigator Hatch]]\r\n* [[Watcher Du'una]]\r\n* [[Watcher Umjin]]\r\n* [[Crewman Boltshine]]\r\n* [[Crewman Cutpipe]]\r\n* [[Crewman Spinshaft]]\r\n* [[Snack-O-Matic IV]]\r\n* [[Vendo-O-Tron D-Luxe]]\r\n==Inspiration==\r\nThis is a possible reference to Pheonix Wright, in which a director comes up with a quick idea for a new television show: The Pink Princess.",},
			["The Quagmire"] = { content = "#REDIRECT [[Quagmire]]", redirect = "Quagmire",},
			["The Rake"] = { content = "'''The Rake''' is a level 10 [[rare mob]] [[cat]] found in [[Mulgore]], east of [[Thunder Bluff]] in the [[Golden Plains]]. He is not [[elite]]. He is on a one hour [[spawn]] timer. \r\n==Background==\r\nThe Rake was formerly one of the most commonly seen [[hunter]] [[pet]]s due to his [[attack speed]] of 1.2, the second-best attack speed available in a [[tame]]able pet. The only ones faster were [[Broken Tooth]] and the [[Bloodseeker Bat]] with a 1.0 attack speed, though there are a few other beasts that also had a 1.2 attack speed. Since pet attack-speed normalization in [[patch 2.0.1]], he has lost this significance. Numerous savannah cats in the [[Barrens]] are identical in appearance, and are easily available for taming.\r\n==Loot==\r\n*Lionfur Armor",},
			["The Reak"] = { content = "'''The Reak''' is a level 49 [[rare mob]] [[ooze]] found in the [[Hinterlands]].",},
			["The Red Crystal"] = { content = "==Objectives==\r\nTravel east of [[Auberdine]] and look for a large, red crystal along Darkshore's eastern mountain range. Report back what you find to [[Sentinel Glynda Nal'Shea]] in [[Auberdine]]. \r\n*Locate the large, red crystal on Darkshore's eastern mountain range\r\n== Description==\r\nHostile moonkin roam in ever increasing numbers to our east. They once were thought to be gentle, almost mystical creatures. While some continue to hold reverence for them, the safety of [[Auberdine]] forces me to keep a more realistic view.\r\nI've received reports that moonkin are being drawn to a large red crystal along Darkshore's eastern mountain range. No one has any idea what that crystal is, or even if it really exists. I want you to locate it over there and report back to me what you find. \r\n== Reward==\r\nYou will receive:6 silver copper \r\n== Completion==\r\nSo the crystal exists, <name>? Fascinating... anyway, your task has been well executed; good work!\r\nWhat exactly is this crystal? This is but a single question in a sea of questions. Another question that comes to mind is why the moonkin would be drawn to this object? Is the crystal benign in nature, or does it hold a more sinister purpose?\r\nI have many more questions, but we're going to need to examine that crystal closely to get some answers. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*490 [[XP]] (or 3 silver copper at level 70)\r\n*75 [[reputation]] with [[Darnassus]]",},
			["The Remains of Trey Lightforge"] = { content = "==Objectives==\r\nReturn the [[Remains of Trey Lightforge]] to [[Jessir Moonbow]] in [[Felwood]]. \r\n*Remains of Trey Lightforge (Provided)\r\n==Description==\r\nYou pick up the sack carefully and prepare to make your way back to Jessir Moonbow on the border of [[Felwood]] and [[Ashenvale]]. Hopefully the [[paladin]] will be given the proper respects once you've passed his remains on to his friends. \r\n==Progress==\r\nHow did things go in [[Jaedenar]], <name>? \r\n== Completion==\r\nYou've done it! Praise be to [[Elune]] and whichever powers you worship, <name>. You have done an honorable and noble thing this day. I am certain [[Arko'narin]] will be pleased that you not only took the time to save her, but to also slay the creature who tortured one of her best friends.\r\nI wish I could do more for you, but please, take this. \r\n==Rewards==\r\nYou will also receive: 22 silver copper \r\n==Gains==\r\n*10900 [[XP]]",},
			["The Return"] = { content = "Written by [[Walter Simonson]]; Art by [[Jon Landry]] and [[Jerome K. Moore]]; Covers by [[Samwise Didier]] and [[Ludo Lullabi]]\r\n'''''The Return''''' begins a new story arc set in the [[Warcraft universe|WORLD OF WARCRAFT]]. Upon learning he is in fact the missing king of [[Stormwind]], [[Lo'Gosh]] returns to reclaim his throne with his comrades-in-arms [[Valeera Sanguinar|Valeera]], and [[Broll Bearmantle|Broll]]. But all is not as it seems in the eastern kingdom, especially if one informed [[dwarf]] has anything to say about it. Enter [[Thargas Anvilmar]]!",},
			["The Right Piece of Lord Valthalak's Amulet"] = { content = "During the quest chain to upgrade the [[Dungeon Set 1]] Helm and Chestpiece to [[Dungeon Set 2]], adventurers will have to complete a quest called '''The Right Piece of Lord Valthalak's Amulet'''. This quest could be one of four quests:\r\n*[[Quest:The Right Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]] - Use the Brazier of Beckoning in Scarlet Stratholme to summon forth Jarien and Sothos and slay them.\r\n**Preceeding Quest: [[Quest:More Components of Importance (Tyr's Hand)|More Components of Importance (Tyr's Hand)]]\r\n*[[Quest:The Right Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]] - Use the Brazier of Beckoning in Scholomance to summon forth the spirit of Kormok and slay him.\r\n**Preceeding Quest: [[Quest:More Components of Importance (Purgation Isle)|More Components of Importance (Purgation Isle)]]\r\n*[[Quest:The Right Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]] - Use the Brazier of Beckoning in Lower Blackrock Spire to summon forth the spirit of Mor Grayhoof and slay him.\r\n**Preceeding Quest: [[Quest:More Components of Importance (Hive'Regal)|More Components of Importance (Hive'Regal)]]\r\n*[[Quest:The Right Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]] - Use the Brazier of Beckoning in Dire Maul to summon forth the spirit of Isalien and slay her.\r\n**Preceeding Quest: [[Quest:More Components of Importance (Frostwhisper Gorge)|More Components of Importance (Frostwhisper Gorge)]]",},
			["The Right Piece of Lord Valthalak's Amulet (Dire Maul)"] = { content = "==Task==\r\n'''Use the [[Brazier of Beckoning]] to summon forth the spirit of [[Isalien]] and slay her. Return to [[Bodley]] inside [[Blackrock Mountain]] with the recombined [[Lord Valthalak's Amulet]] and the [[Brazier of Beckoning]].'''\r\n''It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.''\r\n''She didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces.''\r\n==Reward==\r\n*[[Right Piece of Lord Valthalak's Amulet]]\r\n==Quest Chain==\r\n*[[Quest:Bodley's Unfortunate Fate|Bodley's Unfortunate Fate]]: [[Quest:Bodley's Unfortunate Fate (Alliance)|Alliance]]/[[Quest:Bodley's Unfortunate Fate (Horde)|Horde]]\r\n**[[Quest:Three Kings of Flame|Three Kings of Flame]]\r\n**[[Quest:Components of Importance|Components of Importance]]: [[Quest:Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Left Piece of Lord Valthalak's Amulet|The Left Piece of Lord Valthalak's Amulet]]: [[Quest:The Left Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:I See Alcaz Island In Your Future...|I See Alcaz Island In Your Future...]]\r\n**[[Quest:More Components of Importance|More Components of Importance]]: [[Quest:More Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:More Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:More Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:More Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Right Piece of Lord Valthalak's Amulet|The Right Piece of Lord Valthalak's Amulet]]: [[Quest:The Right Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:Final Preparations|Final Preparations]]\r\n**[[Quest:Mea Culpa, Lord Valthalak|Mea Culpa, Lord Valthalak]]\r\n***[[Quest:Return to Bodley|Return to Bodley]]\r\n***[[Quest:Back to the Beginning|Back to the Beginning]]: [[Quest:Back to the Beginning (Alliance)|Alliance]]/[[Quest:Back to the Beginning (Horde)|Horde]]\r\n***[[Quest:Saving the Best for Last|Saving the Best for Last]]: [[Quest:Saving the Best for Last (Alliance)|Alliance]]/[[Quest:Saving the Best for Last (Horde)|Horde]]\r\n==Notes==\r\n*This is the seventh step in the quest chain to upgrade your [[Dungeon Set 1]] Helm and Chestpiece into [[Dungeon Set 2]].\r\n*You will need to fight your way to the chamber of [[Alzzin the Wildshaper]] in [[Dire Maul]] East and use the brazier. That will summon [[Isalien]].\r\n*Isalien is a hunter/druid spirit. She can root, use an AoE Forstbolt, Moonfire, and Heal. About 10 seconds into the fight, she will summon a [[hippogryph]]. When she summons it, all but the main tank need to concentrate on it.\r\n*Her heal can restore 50% of her health so its important to interrupt her heals. Another alternative is to drain her mana. She has a large supply of mana so it will take a while but once she is drained, she will be much easier. \r\n----\r\nGo to [[Quests]]",},
			["The Right Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)"] = { content = "= Task =\r\n'''Use the [[Brazier of Beckoning]] to summon forth the spirit of [[Mor Grayhoof]] and slay him. Return to [[Bodley]] inside [[Blackrock Mountain]] with the recombined [[Lord Valthalak's Amulet]] and the [[Brazier of Beckoning]].'''\r\n''My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.''\r\n''Later, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front of Voone.''\r\n= Reward =\r\n*[[Right Piece of Lord Valthalak's Amulet]]\r\n= Quest Chain =\r\n*[[Quest:Bodley's Unfortunate Fate|Bodley's Unfortunate Fate]]: [[Quest:Bodley's Unfortunate Fate (Alliance)|Alliance]]/[[Quest:Bodley's Unfortunate Fate (Horde)|Horde]]\r\n**[[Quest:Three Kings of Flame|Three Kings of Flame]]\r\n**[[Quest:Components of Importance|Components of Importance]]: [[Quest:Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Left Piece of Lord Valthalak's Amulet|The Left Piece of Lord Valthalak's Amulet]]: [[Quest:The Left Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:I See Alcaz Island In Your Future...|I See Alcaz Island In Your Future...]]\r\n**[[Quest:More Components of Importance|More Components of Importance]]: [[Quest:More Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:More Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:More Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:More Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Right Piece of Lord Valthalak's Amulet|The Right Piece of Lord Valthalak's Amulet]]: [[Quest:The Right Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]]/'''Lower Blackrock Spire'''/[[Quest:The Right Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:Final Preparations|Final Preparations]]\r\n**[[Quest:Mea Culpa, Lord Valthalak|Mea Culpa, Lord Valthalak]]\r\n***[[Quest:Return to Bodley|Return to Bodley]]\r\n***[[Quest:Back to the Beginning|Back to the Beginning]]: [[Quest:Back to the Beginning (Alliance)|Alliance]]/[[Quest:Back to the Beginning (Horde)|Horde]]\r\n***[[Quest:Saving the Best for Last|Saving the Best for Last]]: [[Quest:Saving the Best for Last (Alliance)|Alliance]]/[[Quest:Saving the Best for Last (Horde)|Horde]]\r\n= Notes = \r\n*This is the seventh step in the quest chain to upgrade your [[Dungeon Set 1]] Helm and Chestpiece into [[Dungeon Set 2]].\r\n*You will need to fight your way to the chamber of [[War Master Voone]] in [[Lower Blackrock Spire]] and use the brazier. That will summon [[Mor Grayhoof]].\r\n*Mor Grayhoof is a druid who will shift to bear and cat form during the fight. He also uses an AoE Moonfire spell, a Hurricane spell, and healing spells.\r\n*When he starts to heal himself, you need to interrupt the spell quicklly or hit him with a [[Mortal Strike]] to lessen the healing power.\r\n----\r\nGo to [[Quests]]",},
			["The Right Piece of Lord Valthalak's Amulet (Scholomance)"] = { content = "==Task==\r\n'''Use the [[Brazier of Beckoning]] to summon forth the spirit of [[Kormok]] and slay him. Return to [[Bodley]] inside [[Blackrock Mountain]] with the recombined [[Lord Valthalak's Amulet]] and the [[Brazier of Beckoning]].'''\r\n''Now we have what we need, so it's time to discuss who it is that you'll be summoning.''\r\n''Kormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, [[Scholomance]].''\r\n''But even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.''\r\n==Reward==\r\n*[[Right Piece of Lord Valthalak's Amulet]]\r\n==Quest Chain==\r\n*[[Quest:Bodley's Unfortunate Fate|Bodley's Unfortunate Fate]]: [[Quest:Bodley's Unfortunate Fate (Alliance)|Alliance]]/[[Quest:Bodley's Unfortunate Fate (Horde)|Horde]]\r\n**[[Quest:Three Kings of Flame|Three Kings of Flame]]\r\n**[[Quest:Components of Importance|Components of Importance]]: [[Quest:Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Left Piece of Lord Valthalak's Amulet|The Left Piece of Lord Valthalak's Amulet]]: [[Quest:The Left Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:I See Alcaz Island In Your Future...|I See Alcaz Island In Your Future...]]\r\n**[[Quest:More Components of Importance|More Components of Importance]]: [[Quest:More Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:More Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:More Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:More Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Right Piece of Lord Valthalak's Amulet|The Right Piece of Lord Valthalak's Amulet]]: [[Quest:The Right Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]]/'''Scholomance'''/[[Quest:The Right Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:Final Preparations|Final Preparations]]\r\n**[[Quest:Mea Culpa, Lord Valthalak|Mea Culpa, Lord Valthalak]]\r\n***[[Quest:Return to Bodley|Return to Bodley]]\r\n***[[Quest:Back to the Beginning|Back to the Beginning]]: [[Quest:Back to the Beginning (Alliance)|Alliance]]/[[Quest:Back to the Beginning (Horde)|Horde]]\r\n***[[Quest:Saving the Best for Last|Saving the Best for Last]]: [[Quest:Saving the Best for Last (Alliance)|Alliance]]/[[Quest:Saving the Best for Last (Horde)|Horde]]\r\n==Notes==\r\n*This is the seventh step in the quest chain to upgrade your [[Dungeon Set 1]] Helm and Chestpiece into [[Dungeon Set 2]].\r\n*You will need to fight your way to the chamber of [[Ras Frostwhisper]] in [[Scholomance]] and use the brazier. That will summon [[Kormok]].\r\n*Kormok has a dispellable Bone Shield which will absorb damage and return Shadow damage. He also has an AoE Shadowbolt volley and will summon undead minions to help during the fight.\r\n*There are two possible strategies:\r\n#Have one tank stay on Kormok and then have the damage dealing classes take out the minions that appear. This is slower but safer. You do run the risk of running out of mana.\r\n#Concentrate all damage on Kormok and ignore the summoned minions. If you have several high damage classes, then this is a viable strategy. You do run the risk on getting overwhelmed by minions.\r\n*Healing should only be performed by priests with [[Holy Nova]] or [[Vampiric Embrace]] to avoid pulling the attention of the minions.\r\n----\r\nGo to [[Quests]]",},
			["The Right Piece of Lord Valthalak's Amulet (Stratholme)"] = { content = "==Task==\r\n'''Use the [[Brazier of Beckoning]] to summon forth [[Jarien and Sothos]] and slay them. Return to [[Bodley]] inside [[Blackrock Mountain]] with the recombined [[Lord Valthalak's Amulet]] and the [[Brazier of Beckoning]].'''\r\n''The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the Left Piece of Lord Valthalak's Amulet with them. Good riddance, I say, but we need that piece back.''\r\n''From what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.''\r\n''In any case, we... meaning you, are still going to need to retrieve that piece of the amulet.''\r\n==Reward==\r\nYou will receive one of the following: \r\n*[[Right Piece of Lord Valthalak's Amulet]]\r\n==Quest Chain==\r\n*[[Quest:Bodley's Unfortunate Fate|Bodley's Unfortunate Fate]]: [[Quest:Bodley's Unfortunate Fate (Alliance)|Alliance]]/[[Quest:Bodley's Unfortunate Fate (Horde)|Horde]]\r\n**[[Quest:Three Kings of Flame|Three Kings of Flame]]\r\n**[[Quest:Components of Importance|Components of Importance]]: [[Quest:Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Left Piece of Lord Valthalak's Amulet|The Left Piece of Lord Valthalak's Amulet]]: [[Quest:The Left Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:I See Alcaz Island In Your Future...|I See Alcaz Island In Your Future...]]\r\n**[[Quest:More Components of Importance|More Components of Importance]]: [[Quest:More Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:More Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:More Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:More Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Right Piece of Lord Valthalak's Amulet|The Right Piece of Lord Valthalak's Amulet]]: '''Stratholme'''/[[Quest:The Right Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:Final Preparations|Final Preparations]]\r\n**[[Quest:Mea Culpa, Lord Valthalak|Mea Culpa, Lord Valthalak]]\r\n***[[Quest:Return to Bodley|Return to Bodley]]\r\n***[[Quest:Back to the Beginning|Back to the Beginning]]: [[Quest:Back to the Beginning (Alliance)|Alliance]]/[[Quest:Back to the Beginning (Horde)|Horde]]\r\n***[[Quest:Saving the Best for Last|Saving the Best for Last]]: [[Quest:Saving the Best for Last (Alliance)|Alliance]]/[[Quest:Saving the Best for Last (Horde)|Horde]]\r\n==Notes==\r\n*This is the seventh step in the quest chain to upgrade your [[Dungeon Set 1]] Helm and Chestpiece into [[Dungeon Set 2]].\r\n*You will need to fight your way to the chamber of [[Saidan Dathrohan]]/[[Balnazzar]] in Scarlet/Live [[Stratholme]] and use the brazier. That will summon [[Jarien and Sothos]].\r\n*Jarien hits very hard and uses a nasty [[Cleave]] attack as well as [[Sinister Strike]].\r\n*Sothos is a caster with a shield. She uses an instant cast Shadowbolt Volley which does 700-800 damage, AoE fears and a shield charge which will knock people back and send them flying.\r\n*Due to the Shadowbolt Volley, shadow resistance is very helpful in this fight.\r\n*One possible strategy is to have one tank pull Jarien away from the rest of the group and keep him occupied. Everyone else concentrate on taking Sothos down as quickly as possible due to her nasty Shadowbolt Volley. Once she is gone, everyone finish off Jarien. If you don't have to get within melee range of him, stay back due to his Cleave.\r\n----\r\nGo to [[Quests]]",},
			["The Ring of Blood"] = { content = "#REDIRECT [[Ring of Blood]]", redirect = "Ring of Blood",},
			["The Ring of Blood: Skra'gath"] = { content = "==Objectives==\r\nDefeat Skra'gath.\r\n*Skra'gath Defeated\r\n*Suggested Players [5]\r\n==Details==\r\nRound four of [[The Ring of Blood]]. This time you will be facing [[Skra'gath]], a level 66 elite [[Demon]] ([[Voidcaller]]).Special abilities inlcude a AoE stun and a knockback that reduces aggro. As usual, let the tank start the event.\r\n==Description==\r\nYou're murderin' 'em out there, kid! They got a ringer for the next match. They say he's a void lord or something... No way do they want you up against their champion. Did you here that palooka, Mogor, yapping at you? The bets are through the roof!\r\nGet in that ring and take this one out fast!\r\n==Rewards==\r\n* 5x icon=\r\n* 5x icon=\r\n* 5x icon=\r\n* 11 gold 10 silver \r\n* 14600 [[XP]]\r\n* +10 [[Kurenai]] reputation for Alliance / +10 [[Mag'har]] reputation for Horde",},
			["The Ring of Trials"] = { content = "#REDIRECT [[Ring of Trials]]", redirect = "Ring of Trials",},
			["The Ring of Valor"] = { content = "#REDIRECT [[Ring of Valor]]", redirect = "Ring of Valor",},
			["The Riptide"] = { content = "The '''''Riptide''''' is the westmost of the three [[Bloodsail Buccaneers]] [[boat|ships]] docked at the [[Wild Shore]] islands in [[Stranglethorn Vale]].\r\n===Crew===\r\n* [[Captain Keelhaul]]\r\n* [[Garr Salthoof]]",},
			["The Rokk"] = { content = "The Rokk is a male [[goblin]] in the [[Lower City]] of [[Shattrath]], located between the netherdrakes and the arakkoa refugees.\r\nHis staff consists of:\r\n* Grisy Spicecrackle (female goblin)\r\n* Gargoth (male [[ogre]])\r\n==Daily cooking quests==\r\nEach day ''The Rokk'' offers one of four level 70 daily cooking quests. Each quest requires a minimum Cooking skill of 275, and two require flying:\r\n* Manalicious\r\n* Revenge is Tasty †\r\n* Soup for the Soul\r\n* Super Hot Stew †\r\n&dagger; Requires flying.\r\nCompleting all four quests grants the [[Professions achievements|Cooking Achievement]] \"Kickin' It Up A Notch\"\r\nEach quest gives as a reward a choice between:\r\n* Barrel of Fish\r\n* Crate of Meat\r\nEither reward contains random raw food (fish or meat respectively) and may also include one of the following recipes:\r\nA good tip is to always choose the Crate of Meat as your reward, until you have all recipes available from it, because it might contain items you need for your next daily cooking quest. When you have all of the recipes Crate of Meat has to offer, switch to Barrel of Fish in order to obtain the remaining recipes.\r\n==Background==\r\n''The Rokk'' is likely a reference to [[wikipedia:The Rock (entertainer)|Dwayne \"The Rock\" Johnson]], with some of ''The Rokk'''s comments (\"Do I smell something tasty?\" and \"What smells so good?\") alluding to Johnson's famous tagline of ''\"Do you smell what the Rock is cookin'?\"''.",},
			["The Rolling Plains"] = { content = "#REDIRECT [[Rolling Plains]]", redirect = "Rolling Plains",},
			["The Rot"] = { content = "'''The Rot''' is a level 40-43 [[rare mob]] [[ooze]] found in [[Dustwallow Marsh]].",},
			["The Rotting Orchard"] = { content = "#REDIRECT [[Rotting Orchard]]", redirect = "Rotting Orchard",},
			["The Royal Exchange"] = { content = "#REDIRECT [[Royal Exchange]]", redirect = "Royal Exchange",},
			["The Royal Quarter"] = { content = "#redirect [[Royal Quarter]]", redirect = "Royal Quarter",},
			["The Royal Rescue"] = { content = "The Royal Rescue is the 5th quest in the '''Commander Gor'shak''' quest chain.\r\n==Objectives==\r\nSlay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell.\r\n*[[Emperor Dagran Thaurissan]]s slain\r\n==Description==\r\nThis strike against the Dark Iron dwarves, if successful, will send a shockwave throughout their entire kingdom.\r\nPrincess Bronzebeard is under the control of Emperor Thaurissan. To free her, you must kill the Emperor. Be warned, your task is doubly dangerous, as Bronzebeard will attack you without question while under the control of the Emperor.\r\nDO NOT HARM HER!\r\n==Completion==\r\nWhat have you done!\r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*8050 [[XP]] (or s=84 gold at level 70)\r\n==Quest chain==\r\n#Commander Gor'shak\r\n#What Is Going On?\r\n#What Is Going On?\r\n#The Eastern Kingdoms\r\n#The Royal Rescue\r\n#The Princess Saved?",},
			["The Ruined Reaches"] = { content = "#REDIRECT [[Ruined Reaches]]", redirect = "Ruined Reaches",},
			["The Ruins of Kel'Theril"] = { content = "#redirect [[Ruins of Kel'Theril]]", redirect = "Ruins of Kel'Theril",},
			["The Ruins of Lordaeron"] = { content = "#redirect [[Ruins of Lordaeron]]", redirect = "Ruins of Lordaeron",},
			["The Ruins of Ordil'Aran"] = { content = "#REDIRECT [[Ruins of Ordil'Aran]]", redirect = "Ruins of Ordil'Aran",},
			["The Ruins of Stardust"] = { content = "#REDIRECT [[Ruins of Stardust]]", redirect = "Ruins of Stardust",},
			["The Rune of Summoning"] = { content = "==Objectives==\r\nUse the [[Voidstone]] to summon a [[Voidwalker]] in [[Goldenmist Village]], defeat it, and return to [[Talionia]] in [[Silvermoon City]]. \r\n*level=10 slain\r\n*Voidstone (quest) (Provided)\r\n== Description==\r\nThe voidstone reveals a vision of a multi-story building haunted by ghostly figures. As the scene sharpens and blurs, other buildings come into view, leading you to believe it is Goldenmist Village.\r\nRooftops and tree canopies suddenly flash by, revealing the way to Goldenmist by following the [[Elrendar River]] to the west.\r\nOnce there, use the voidstone near the rune of summoning atop the center building and defeat the summoned voidwalker. Only then can you return to your teacher.\r\n== Progress==\r\nHave you followed the path revealed by the voidstone? \r\n== Completion==\r\nI'm impressed you are standing here, <name>. Many an apprentice has perished to the voidwalker, or even the voidstone itself.\r\nThe voidwalker is now yours to command. Use your new servant well. \r\n== Gains==\r\n*850 [[XP]] (or 5 silver 10 copper at level 70)\r\n*Spell: [[Summon Voidwalker]]",},
			["The Rustmaul Dig Site"] = { content = "#REDIRECT [[Rustmaul Dig Site]]", redirect = "Rustmaul Dig Site",},
			["The Sacred Flame (quest)"] = { content = "In '''The Sacred Flame''', you will journey to [[Ashenvale]] to steal a vial of water from a [[moonwell]], which is needed to douse a sacred fire of the centaur in [[Thousand Needles]].\r\n====To Get This Quest====\r\nGo to upper rise in [[Thunder Bluff]] and talk to [[Zangen Stonehoof]], coordinates .\r\n==Objective==\r\nReturn a Filled Etched Phial to [[Zangen Stonehoof]] in [[Thunder Bluff]].\r\nYou will need:\r\n* Filled Etched Phial\r\n==Details==\r\nFrom [[Splintertree Post]] in [[Ashenvale]], head west along the road. When the road splits off to the south, continue on the western fork. When it splits again, this time to the north, take the northern fork. This should bring you to [[Raynewood Retreat]], where many dryads called [[Laughing Sister]]s are wandering - around coordinates . Kill the dryads until you find an Etched Phial.\r\nOnce you have the empty phial, you need to find the [[Moonwell]]. It can be found southwest of the bridge that crosses the [[Falfarren River]] - coordinates are . To fill the phial, right click it while standing in the moonwell.\r\nTake the Filled Etched Phial back to [[Zangen Stonehoof]] in [[Thunder Bluff]] to turn in the quest.\r\n==Description==\r\n''The Galak centaur in the [[Thousand Needles]] are protecting an artifact from the time of the centaurs' creation.\r\n''We would like to retrieve it, but we require a phial of water from one of the night elves' moonwells.\r\n''To collect the water, you will first need to obtain one of the phials carried by the dryads near the [[Raynewood Retreat]] in the heart of [[Ashenvale]] Forest. There is a [[moonwell]] near the western bank of the [[Falfarren River]], south of the main road, where you can fill the phial.\r\n==Progress == \r\n''Once we have the filled phial, we can send it along to my associate, Rau, in the [[Thousand Needles]]. He was the one who requested the phial of water, so he'll better know how we can make use of it.\r\n== Completion==\r\n''Very good. This should fill Rau's request just fine. Could you deliver this to him? You might enjoy spending some time out in the Needles.\r\n==Quest Progression==\r\n*The Sacred Flame\r\n**The Sacred Flame (2)\r\n***The Sacred Flame (3)",},
			["The Sacred Grove"] = { content = "#redirect [[Sacred Grove]]", redirect = "Sacred Grove",},
			["The Saga of Terokk"] = { content = "Were you looking for:\r\n*The [[quest item]] [[The Saga of Terokk (quest item)|The Saga of Terokk]]?\r\n*The [[object]] [[The Saga of Terokk (object)|The Saga of Terokk]]?\r\n*The [[off-hand]] item [[The Saga of Terokk (off-hand)|The Saga of Terokk]]?",},
			["The Saga of Terokk (object)"] = { content = "The '''The Saga of Terokk''' is located in [[Sethekk Halls]]. ([[Heroic mode]])\r\n==Objective of==\r\nContains The Saga of Terokk (quest item) for the quest Terokk's Legacy.",},
			["The Saga of Terokk (off-hand)"] = { content = "''For the quest item, see [[The Saga of Terokk (quest item)]].''\r\n==Source==\r\nThis item is a quest reward from Terokk's Legacy.",},
			["The Saga of Terokk (quest item)"] = { content = "==Source==\r\nThe [[The Saga of Terokk (object)|Saga of Terokk]] can be found in the [[Sethekk Halls]], in a runic circle just outside of the room where [[Talon King Ikiss]] resides.\r\n==As a quest objective==\r\nTerokk's Legacy\r\n==Notes==\r\nThis item can be looted by everyone in the party, however it takes about a minute for it to respawn.",},
			["The Savage Coast"] = { content = "#REDIRECT [[Savage Coast]]", redirect = "Savage Coast",},
			["The Scalding Pools"] = { content = "#redirect [[Scalding Pools]]", redirect = "Scalding Pools",},
			["The Scale of the Sands"] = { content = "#REDIRECT [[Scale of the Sands]]", redirect = "Scale of the Sands",},
			["The Scarab Dais"] = { content = "#redirect [[Scarab Dais]]", redirect = "Scarab Dais",},
			["The Scarab Gong"] = { content = "'''The Scarab Gong''' is a [[fixed device]] located at the [[Scarab Dais]] of [[Silithus]].\r\n==Quests==\r\nThe Scarab Gong starts and finishes the quest Bang a Gong!, part of [[The Scepter of the Shifting Sands quest chain]] to open the [[Gates of Ahn'Qiraj]]. This quest is available until 10 hours have passed after the first person on the server has rung the gong.",},
			["The Scarab Wall"] = { content = "#REDIRECT [[Scarab Wall]]", redirect = "Scarab Wall",},
			["The Scarlet Apocalypse"] = { content = "==Objectives==\r\nSeek out [[the Lich King (Ebon Hold)|the Lich King]] at [[Death's Breach]].\r\n==Description==\r\nThe trap has been sprung, [[death knight]]. The armies of [[Hearthglen]] and [[Tirisfal Glades|Tirisfal]] have arrived. Just in time to see their enclave in flames! If they turn their back now, they might fight us with their backs turned.\r\n<Mograine shakes his head.>\r\nNo, they have only one option, which has only one outcome: APOCALYPSE!\r\nAs we speak, they prepare to make one final stand.\r\nThe Lich King awaits your return, champion. He stands below us at Death's Breach.\r\n==Completion==\r\nYou have served me well, <name>. The mark of the [[Scourge]] has been burned into these [[Scarlet Crusade|Scarlet]] lands. You have reaped death and destruction for as far as the eye can see and delivered to me the last of the Scarlet armies.\r\n<The Lich King points to the ruins of [[Havenshire]] and the burning city of [[New Avalon]].>\r\nIt is now time to finish what you started.",},
			["The Scarlet Basilica"] = { content = "#redirect [[Scarlet Basilica]]", redirect = "Scarlet Basilica",},
			["The Scarlet Bastion"] = { content = "#redirect [[Scarlet Bastion]]", redirect = "Scarlet Bastion",},
			["The Scarlet Key"] = { content = "'''The Scarlet Key''' is the master key to the most heavily-guarded areas claimed by the [[Scarlet Crusade]] - the Armory and Cathedral wings of the [[Scarlet Monastery]].\r\nThe key was also once used to open the [[Scarlet Bastion]] in Western [[Stratholme]]; this requirement was removed during [[patch 3.2.0]].\r\n==Source==\r\nThis item drops from the static chest ([[Doan's Strongbox]]) behind the final boss, [[Arcanist Doan]], in the Library wing of the [[Scarlet Monastery]] in [[Tirisfal Glades]]. The chest is lootable by everyone, and the key is automatically placed in the keyring.\r\n==Criteria of==\r\nObtaining this key is a criterion for [[The Keymaster]].",},
			["The Scarlet Monastery"] = { content = "#redirect [[Scarlet Monastery]]", redirect = "Scarlet Monastery",},
			["The Scarlet Onslaught Emerges"] = { content = "==Objectives==\r\nDeliver The Path of Redemption to [[Orbaz Bloodbane]] at the [[Scarlet Tavern]] in [[New Avalon]].\r\n*The Path of Redemption (provided)\r\n==Description==\r\nListen well, courier. The [[Scarlet Crusade|Scarlet]] lands are lost. [[New Avalon]] and [[Havenshire]] are overrun by [[Scourge]]. The specter of death looms overhead and threatens to overtake us at any moment.\r\nReturn to Galvar with this message:\r\n\"Turn your armies around and prepare your ships for travel to the frozen wastes. When we next meet it will be in [[Northrend]].\"\r\nGive this to Galvar.\r\n<Abbendis hands you a journal.>\r\nIt will explain everything.\r\nThe [[Scarlet Crusade]] is no more. Long live the [[Scarlet Onslaught]]!\r\n==Rewards==\r\nYou will receive: 85 silver and 1 Bonus talent\r\n==Progress==\r\n<Orbaz laughs.>\r\nWhat is this? Some child's coloring book?\r\n==Completion==\r\n<Orbaz flips through the journal.>\r\nWhat rubbish! This is the \"Crimson Dawn?\"\r\nThey sail to their deaths! Let us turn our focus to the encroaching armies.",},
			["The Scarlet Oracle, Demetria"] = { content = "This is the final quest in a chain beginning after you complete To Kill With Purpose, Un-Life's Little Annoyances, and Ranger Lord's Behest.\r\n==Objectives==\r\n'''The Scarlet Crusade is on the move. Somewhere along the road from Tyr's Hand to Stratholme you will find the Oracle, Demetria, and her entourage. Hunt her down and slay her. Return to Nathanos Blightcaller should you succeed.'''\r\n==Details==\r\nDemetria will spawn at [[Tyr's Hand]], [[Eastern Plaguelands]], upon accepting the quest from [[Nathanos Blightcaller]], and will walk from there to [[Stratholme]]. She has many guards with her. These guards aren't elite, but there are 8 of them, and Demetria will rez any you kill. You will need a group to complete this quest - focus on taking down the oracle first.\r\nThe Alliance have a quest chain ending with the same rewards - Order Must Be Restored. However, their final step is killing [[Nathanos Blightcaller]].\r\n==Description==\r\n''Demetria is chief advisor to the Grand Crusader. She is called the Oracle due to her 'otherworldly' senses. She has successfully assisted the Crusade in several of their victories against the Scourge.''\r\n''While this ruse was successful in exposing her, if she truly does possess psychic powers, she will undoubtedly be expecting some sort of trouble. You are going to provide that 'trouble.'''\r\n''Track down the Oracle and terminate her. They should be moving out of Tyr's Hand as we speak. Make me proud, worm.''\r\n==Reward==\r\n8550 XP \r\n1 gold 80 silver \r\nYou will be allowed to choose one of the following:\r\n==Progress==\r\n''What is your status, <name>?''\r\n==Completion==\r\n''They will be reeling from this blow for years! Well done, <name>! You have earned not only my respect but also this reward.''\r\n==Quest Progression==\r\n* To Kill With Purpose\r\n* Un-Life's Little Annoyances\r\n* Ranger Lord's Behest \r\n** Duskwing, Oh How I Hate Thee... \r\n** The Corpulent One \r\n** The Call to Command\r\n** The Crimson Courier\r\n** Nathanos' Ruse\r\n** Return to Nathanos\r\n*** The Scarlet Oracle, Demetria",},
			["The Scepter of Celebras"] = { content = "#REDIRECT [[Scepter of Celebras]]", redirect = "Scepter of Celebras",},
			["The Scepter of the Shifting Sands"] = { content = "The '''Scepter of the Shifting Sands''' is an item created from an [[The Scepter of the Shifting Sands quest chain|extremely long quest chain]]. The beginning of this quest chain starts in [[Cenarion Hold]]. This scepter is required to ring the gong that opens the gates to [[Ahn'Qiraj]], thus allowing the entire server access to both the [[Ruins of Ahn'Qiraj]] and the [[Temple of Ahn'Qiraj]]. This quest is still accessible even if the gates are already open. A Raid group is required during some parts of the quest.\r\n==See also==\r\n*[[List of scepter holders by server]]\r\n*[[Gates of Ahn'Qiraj]]",},
			["The Scepter of the Shifting Sands quest chain"] = { content = "This article deals with the incredibly long and involved quest chain to create The Scepter of the Shifting Sands, used to open the [[Gates of Ahn'Qiraj]].\r\n==Walkthrough==\r\n# Accept the quest What Tomorrow Brings, offered by Baristolth of the Shifting Sands in [[Cenarion Hold]]. This quest requires you to find Anachronos at the [[Caverns of Time]] in [[Tanaris]] . There is no need to kill any of the elite dragons around Anachronos to complete this quest.\r\n# The follow-up quest Only One May Rise has players kill Broodlord Lashlayer in [[Blackwing Lair]] and loot the Head of the Broodlord Lashlayer.\r\n# Return to Baristolth to receive the group quest The Path of the Righteous. Even if the [[Gates of Ahn'Qiraj]] have already been opened on your server and you have gained or better reputation with the [[Brood of Nozdormu]] from the [[Ahn'Qiraj]] instances you will still need to complete this quest to proceed with the quest chain. Accepting this quest provides the Agent of Nozdormu badge, which enables players to loot Silithid Carapace Fragments from the elite [[silithid]] in the Hives of [[Silithus]]. 200 fragments are required for each turn-in and the reward is 500 reputation with the [[Brood of Nozdormu]].\r\n#* If you are not with the Brood, you can either gain reputation by killing creatures and bosses in the [[Temple of Ahn'Qiraj]] or completing the repeatable quest The Hand of the Righteous by looting or acquiring thousands of fragments. Each silithid drops at least one fragment, often two or more. This is most easily done in Hive Regal, where the silithid always have a chance to drop one extra fragment. Each turn-in also awards a Proxy of Nozdormu. This can be used on another player and allows that player to loot fragments as well. The fragments do not [[Bind on Pickup|bind on pickup]] so they can be sold or traded.\r\n# At reputation with the Brood of Nozdormu, Baristolth offers Anachronos. \r\n# Anachronos, now being neutral with you, offers the quest Long Forgotten Memories. This quest is completed in Silithus by locating the crystalline red tear just outside the [[Gates of Ahn'Qiraj]] . Completing this quest activates a small cutscene.\r\n# When the cutscene finishes, the follow-up quest A Pawn on the Eternal Board sends you back to Anachronos once again.\r\n===Charge of the Dragonflights===\r\nThe questline seemingly ends at Anachronos with the quest The Charge of the Dragonflights, but this is not the case. Anachronos wants you to locate the 3 dragon shards located somewhere in Azeroth, specifically the Green, Red and Blue shards. \r\nEranikus, Vaelastrasz and Azuregos hold the secret to these shards. Completing the previous quest chain enables you to begin these shard quests. Note that the blue shard chain is the most involved, while the red chain is the simplest.\r\n==Green Scepter Shard==\r\n# Enter the [[Temple of Atal'Hakkar]] to begin this quest. Approach the Shade of Eranikus and Malfurion Stormrage will appear, offering the quest Eranikus, Tyrant of the Dream. You do not need to kill the trolls or drakes surrounding Eranikus to activate Malfurion. Malfurion directs players to [[Teldrassil]] to find his agent.\r\n# In Teldrassil at is a Forest Wisp. It offers the next quest, Tyrande and Remulos, where players must find Keeper Remulos in [[Moonglade]].\r\n# Keeper Remulos offers The Nightmare's Corruption. To complete this quest players must farm the [[Dragonkin]] by the [[Four Dragons]] portals. This can take many many hours and requires a party. Additionally, the fragment in [[Duskwood]] is actually looted from a Twilight Corrupter, a 40-man raid satyr.\r\n# When returning the fragments to Remulos, he offers The Nightmare Manifests. Accepting this quest will summon Eranikus, Tyrant of the Dream who enters [[Nighthaven]] and brings a host of Shades. Players must defend Keeper Remulos from the Shades and not kill Eranikus until Tyrande Whisperwind can arrive and redeem Eranikus.\r\n# After Tyrande redeems him, Eranikus bids Remulos award players the icon= and the quest The Champion Returns, which sends players back to [[Anachronos]].\r\nThe reward for completing this fork of the chain is either Drake Tooth Necklace or Drudge Boots.\r\n==Red Scepter Shard==\r\nSpeak with Vaelastrasz in [[Blackwing Lair]] and he will offer players the quest Nefarius's Corruption, and explains that Nefarian (tactics) has the Red Scepter Shard. Defeat Nefarian within 5 hours of engaging Vaelastrasz and the Red Scepter Shard will be lootable off his corpse. '''Only one shard will drop per Nefarian kill'''. \r\nThe timer stops if EVERYONE leaves - if one person sits in there, the timer still runs. If you fail, you will need to abandon the quest and talk to Vaelastrasz again.\r\nIf someone happens to prematurely start the Vaelastrasz encounter before you can accept Nefarius's Corruption, there is a short period of time where he is friendly while doing his dialog in which you can still accept the quest.\r\nThe rewards for completing this quest are either Onyx Embedded Leggings or Amulet of Shadow Shielding.\r\n==Blue Scepter Shard==\r\n# Speak with Azuregos in [[Azshara]]. If [[Azuregos]] has already been killed, you can talk to the [[Spirit of Azuregos]] at any time. You don't need your signet ring with you to talk to him and if the spirit is not in the living world, you will need to die and speak with him while dead. After much explaining, Azuregos says that the blue shard is being held by a minnow, and to summon the minnow you need to read Azuregos's Magical Ledger. Unfortunately, you are unable to read this book and must talk to Narain Soothfancy in Tanaris.\r\n# Go to Tanaris, just north of Steamwheedle Port, and you will find Narain Soothfancy. He explains in Translating the Ledger that he cannot read the book you have given him. He requires 3 items: his scrying goggles, a 500 Pound Chicken, and Draconic For Dummies: Volume II. These 3 items involve 3 different quest lines.\r\n===Narain's Scrying Goggles===\r\n# Narian explains in Stewvul, Ex-B.F.F. his goggles were stolen by his ex-B.F.F. (ex-best friend forever), a gnome named Stewvul. Stewvul is located in southern [[Silverpine Forest]] next to [[Greymane Wall]].\r\n# Stewvul is inside a crate at location in Silverpine forest. He says the goggles were lost inside [[Molten Core]], and gives you the followup quest Scrying Goggles? No Problem! The Scrying Goggles have a chance to drop off any mob inside [[Molten Core]]. Return them to Narain to complete this quest, and receive 3 Major Rejuvenation Potion as a corollary reward.\r\n===500 Pound Chicken===\r\n# The first quest in this fork is Never Ask Me About My Business, which involves simply talking to Dirge Quikcleave in the [[Gadgetzan]] Inn.\r\n# Dirge offers The Isle of Dread!. Go to [[Feralas]] at and you will find Lord Lakmaeran, a large chimera. [[Lord Lakmaeran]] requires 7-10 people to kill. After killing him '''one''' person may loot his carcass for the quest. In addition, the surrounding Chimaerok need to be killed for the 20 required Chimaerok Tenderloin. Chimaeroks can be successfully 2-manned.\r\n# After gathering the meat, return to Dirge for the follow up quest Dirge's Kickin' Chimaerok Chops. This quest requires 20 Goblin Rocket Fuel and 20 Deeprock Salt. The reward is Recipe: Dirge's Kickin' Chimaerok Chops and 20 Dirge's Kickin' Chimaerok Chops.\r\n# Finally, Return to Narain with the \"500 Pound Chicken\".\r\n===Draconic for Dummies: Volume II===\r\n# The quest begins with Draconic for Dummies. Narain says he left his book on an island in far southern [[Tanaris]]. Getting to this island is somewhat unusual since it exists far past [[Fatigue]] waters and you cannot swim to it by conventional means.\r\n# Before you can reach the island you must first speak with the Meridith the Mermaiden, who is located at approximately . She is underwater, close to the shore. She does move around a bit so you may have to search for a while. When you speak with her she offers the quest Love Song for Narain, which simply requires you to return to Narain.\r\n# After completing Love Song for Narain, there is no followup quest. However, if you return to Meridith she will buff you with a large increase in swim speed. This will enable you to swim to the island in question. Look south and you will see the island. Swim directly toward it and you should reach it without the fatigue bar full draining. Note there are 2 islands, and the book is located on the southern island.\r\n# Upon reaching the southern island, an actionable 'Freshly Dug Dirt' exists. Inside is a note yielding the quest rAnS0m. The Book has been stolen and a ransom demand is made. Return to Narain again.\r\n# In Decoy!, Narain gives you a package containing a robe, a turban, a bag of fake gold, and a map. You have to go to [[Winterspring]] to the drop off point, and use the Turban which will turn you into Narain. The coordinates of the drop location are . After dropping off the gold, [[Dr. Weavil]] arrives, realizes the trap, and sends Number Two, his ape pet, to attack you. Weavil escapes. The ape pet hits tanks for about 600-700 damage and can be killed with a party of 3-5 fairly easily. Once No. 2 is dead, return the quest to Narain.\r\n# From here, you receive The Only Prescription. The book required to translate the Draconic text has been torn in 8 separate pieces, and all 8 pieces must be acquired to complete the quest. The locations are as follows:\r\n## Chapter I: Located on [[Alcaz Island]] in [[Dustwallow Marsh]]. You must defeat Dr. Weavil to receive the book. He is much harder than No. 2 and requires about 15 people to defeat.\r\n## Chapter II: Felguard Elite and Doomguard in the [[Blasted Lands]] have a chance to drop it. These require 4-5 people to farm effectively. (~4% drop rate)\r\n## Chapter III: Hederine Initiate & Hederine Slayer in [[Winterspring]] at [[Darkwhisper Gorge]] have a chance to drop it. These require 1-2 people to farm effectively. (~6% drop rate)\r\n## Chapter IV: Located in [[Undercity]] on a table in the Magic Quarter.\r\n## Chapter V: Located in the [[Stormwind Keep]] library (turn left as you walk in).\r\n## Chapter VI: Dropped by Onyxia (tactics).\r\n## Chapter VII: In [[Blackwing Lair]] in the room after Broodlord Lashlayer, along Firemaw's patrol path. It is on a table on the ramp in the corner to the left of the wyrmguard + 3 overseer pack.\r\n## Chapter VIII Dropped by Ragnaros (tactics).\r\n#* '''Note''': These pieces are '''white''' items thus they are in the round-robin loot table and cannot be master-looted. That means, for chapter 1, 6, 8 that require a raid, you have to ask the raid leader to change the loot rule to 'Free for all', or, to ask every member to check boss' corpse even they don't have this quest. In the later case, a single logged or HSed member may make your effort in vain.\r\n#* Completing the quest The Only Prescription rewards the icon=.\r\n'''Only one Chapter drops per kill'''. Assemble the text, get the chicken, get the goggles, and the quest line merges.\r\n===Good news and bad news===\r\nAfter all 3 components of the blue shard are done, Narain offers the quest The Good News and The Bad News. This quest requires 20 Arcanite Bar, 10 Elementium Ore, 10 Blue Sapphire, and 10 Azerothian Diamond. He will then give you an Arcanite Buoy and the next quest, The Wrath of Neptulos. Take the buoy deep off the coast of [[Azshara]] and spawn Maws, the \"minnow\" carrying the shard. The arcanite buoy is used up when you summon [[Maws]] but if you fail Narain will give you another one. When you kill the shark the blue shard drops. Return the Shard to Anachronos to complete the Blue Shard line.\r\nThe reward for completing this chain is either the Band of Icy Depths or Darkwater Robes.\r\n==Conclusion==\r\n# Immediately upon the completion of the third and final fork of the chain, Anachronos offers The Might of Kalimdor where he informs players that they must now wait until the rest of the server finishes the [[Gates of Ahn'Qiraj|War Effort]] collection quest.\r\n# Five days after the collection quest is complete, Bang a Gong! is offered. Completing this quest by ringing [[The Scarab Gong]] will start the [[Gates of Ahn'Qiraj|10 Hour War]] server event. This quest ceases to be available 10 hours it was first completed on the realm.\r\n# Once the 10 Hour War is complete, Jonathan the Revelator offers Treasure of the Timeless One, finishing the quest chain.\r\n==Rewards==",},
			["The Scorched Grove"] = { content = "#REDIRECT [[Scorched Grove]]", redirect = "Scorched Grove",},
			["The Scourge"] = { content = "#REDIRECT [[Scourge]]", redirect = "Scourge",},
			["The Scourge Invasion"] = { content = "#REDIRECT [[Scourge Invasion]]", redirect = "Scourge Invasion",},
			["The Scourge of Lordaeron (History of Warcraft)"] = { content = "'''\"The Scourge of Lordaeron\"''' is a section of the [[History of Warcraft]], Chapter IV. It recounts the events of the human campaign in ''[[Warcraft III: Reign of Chaos]]''.\r\nFound at:\r\n* [[Astranaar]] in [[Ashenvale]] \r\n* Athenaeum of [[The Scarlet Monastery]] in [[Tirisfal Glades]]\r\n* [[Booty Bay]] in [[Stranglethorn Vale]] - building near fishing vendor\r\n* Reliquary of [[Scholomance]] in the [[Western Plaguelands]]\r\n* * The Scarlet Bastion (live side) of [[Stratholme]]\r\nTimeline: \r\n* ← Previous book: [[The Alliance Splinters]]\r\n* → Next book: [[Sunwell - The Fall of Quel'Thalas]]",},
			["The Scrap Field"] = { content = "#redirect [[Scrap Field]]", redirect = "Scrap Field",},
			["The Screeching Canyon"] = { content = "#REDIRECT [[Screeching Canyon]]", redirect = "Screeching Canyon",},
			["The Scryer's Scryer"] = { content = "==Objectives==\r\n[[Tyrith]] wants you to use the orb on the balcony in [[Magisters' Terrace]].\r\n*[[Scrying Orb]] Activated\r\n==Description==\r\n<Tyrith winces in pain as he speaks.>\r\nGo to the terrace... use the orb.\r\n...They're...feeding the [[sunwell]]....\r\n<Tyrith gasps for breath.>\r\nHurry... They must be stopped... before they can....\r\n<Tyrith dies.>\r\n==Rewards==\r\nYou will receive: 4 gold 40 silver \r\n==Completion==\r\nI consider it to be no coincidence that our paths cross this day. I sense the tendrils of destiny...\r\n==Quest progresion==",},
			["The Scryers"] = { content = "#REDIRECT [[Scryers]]", redirect = "Scryers",},
			["The Seabreach Flow"] = { content = "#REDIRECT [[Seabreach Flow]]", redirect = "Seabreach Flow",},
			["The Sealed Hall"] = { content = "#REDIRECT [[Sealed Hall]]", redirect = "Sealed Hall",},
			["The Seat of the Naaru"] = { content = "==Objectives==\r\nTake your orphan, Dornaa, to stand before [[O'ros]] at the bottom of the Seat of the Naaru inside of the [[Exodar]], which is on [[Azuremyst Isle]]. Make sure to call for her if she is not present when you arrive.\r\nRemember that you can use your map inside the city. \r\n*Dornaa taken to the Seat of the Naaru\r\n== Description==\r\nDo you know anything about the naaru? They're these angelic beings that have been helping the draenei for a really long time. I've seen a bunch around [[Shattrath]].\r\nThey say that one naaru, [[O'ros]], was with the [[Exodar]] when it traveled to your homeworld. I should like to see for myself.\r\nCan you take me there? I bet we could get there fast by using one of the portals inside the Terrace of Light at [[Shattrath]] City! When we get there, if you get lost, we could always just look at your map. \r\n== Completion==\r\n<You feel, more than hear, the musical voice of [[O'ros]] chiming in your mind.>\r\nThank you for bringing this child to me, <name>. She is very special indeed, and will grow up one day to be an important figure amongst the draenei. This is in no small part due to the kindness that you have shown her, and the impression that you have made. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*6250 [[XP]] (or 3 gold 75 silver copper at level 70)\r\n*75 [[reputation]] with [[Lower City]]",},
			["The Sea of Cinders"] = { content = "#REDIRECT [[Sea of Cinders]]", redirect = "Sea of Cinders",},
			["The Second and Third Fragments"] = { content = "'''The Second and Third Fragments''' is part of [[the Master's Key]] questline for attunement to [[Karazhan]]. In this quest, the player retrieves the second and third key fragments.\r\n==Objectives==\r\nObtain the Second Key Fragment from an [[Arcane Container]] inside [[The Steamvault]] at [[Coilfang Reservoir]] and the Third Key Fragment from an [[Arcane Container]] inside [[Arcatraz]] at [[Tempest Keep]]. Return to [[Khadgar]] in [[Shattrath City]] after you've completed this task.\r\n==Strategy and Tips==\r\nThe [[Second Key Fragment]] is in the pool of water, to the right of the first boss [[Hydromancer Thespia]], just before getting to her room, in [[The Steamvault]].\r\nThis quest is now harder to solo (as of [[Patch 2.0.7]]), through [[Stealth]] or [[Invisibility]], due to the container no longer containing anything - it triggers an event which spawns an elite guardian which must be killed in order to obtain the fragment. The Guardian only drops the number of keys needed by the group. Upon leaving the instance, your copy of the key is deleted. This prevents you ungrouping and allowing others to join and loot the key. It should also be noted that if you spawn the Guardian Mob, and consequently wipe, then it is likely that you may not be able to loot the key fragment.\r\nIf you bring a party to obtain the key fragment and can defeat the Bog Overlords, getting to the key is a pretty quick process. Kill the two Bog Lords on the right side as you enter and skirt that edge. Following the Bog Lords, there is a pull of a 4-group of Naga, the 2-group at the front edge of the ramp (watch for the patrollers and pull them back) and then you can jump on to the \"ramp\" of rock-geometry just out of aggro range for the four group at the base of the ramp. Jump in the water and then get your key!\r\nIt is possible to get the fragment with 2 players and at least 2 Invisibility Potions each. This method requires the first group to be pulled and a melee/spellcaster patrol to be pulled. After the two groups are dead, careful timing is required where each party member takes turns to run into the room and drink the potion the moment before they may pull aggro. Making the run seperately can prevent a full-party wipe. Once Invisible, run straight to the pond and aim for the second column to hide on the backside directly against it, away from the \"ramp\". When the potion wears off, you should be standing evenly between a large Naga group and two Mermidon guards next to the ramp. Wait for your 10 minute cooldown on the potions to wear off. Afterward, drink and proceed to the pond. Priests can use their Mind Vision spell to locate the \"rest stop\" and guide party members. Avoid Bog Overlords at all costs, as they are able to detect you while Invisible.\r\nThe [[Third Key Fragment]] is a little more of a challenge. You first of all need to enter [[Arcatraz]] (which requires at least one party member with a lockpicking skill of 350, or the Key to the Arcatraz obtained from starting the Assisting the Consortium quest-chain) and work your way to the first boss, [[Zereketh the Unbound]]. If your group is only interested in obtaining the [[Third Key Fragment]] then you can skip [[Zereketh the Unbound]] and go to the stair case, which is located directly in front of you as you enter [[Zereketh the Unbound]]'s room. \r\nUpon arrival at the top of the staircase you'll need to remove a few guard mobs, until you reach the first room - the [[Third Key Fragment]] is located in the corner, on the right as you enter the room.\r\nMuch like the [[Second Key Fragment]], this too is now a little harder to solo through [[Stealth]] or [[Invisibility]] - as looting the container for the [[Third Key Fragment]] now spawns an elite Guardian mob that must be killed in order to obtain the fragment.\r\n==Description==\r\nI hid the second fragment at the bottom of [[Serpent Lake]], long before it was called that. The giant drain installed there after the naga took over has likely pulled the container into the depths of [[Coilfang Reservoir]].\r\nThe third fragment will prove the most trying, as I left it inside [[Tempest Keep]] back when it was controlled by the naaru. [[Kael'thas]] now rules it and the chamber where I left it has become a prison.\r\nBring me these remaining fragments, <Name>. Much depends on your success.\r\n==Reward==\r\nYou will receive: 9 gold 48 silver \r\n==Progress==\r\nHow goes your search for the key fragments, <name>?\r\n==Completion==\r\nYou have the fragments. This is most impressive, <name>. You're certainly worthy of holding the key to Karazhan.\r\nA small problem remains.",},
			["The Second War"] = { content = "#REDIRECT [[Second_War]]", redirect = "Second_War",},
			["The Secret Compromised"] = { content = "This quest is part of a chain that leads to obtaining the [[Medallion of Karabor]]. You must have completed the chain ending with Akama's Promise.\r\n==Objectives==\r\n'''Travel to the Warden's Cage in Shadowmoon Valley and speak to Akama.'''\r\n==Notes==\r\nSeer Olum spawns in [[Serpentshrine Cavern]] after slaying [[Fathom-Lord Karathress]].\r\n==Description==\r\n''Thanks again, <name>. I recognize your name. Akama has entrusted you with his plans and so I will trust you as well.''\r\n''The naga discovered I was working against Illidan and tried to get me to speak by torturing me. I did not tell them a thing - Akama himself taught me to master pain through meditation.''\r\n''Illidan asked the naga to bring me to him. He would have seen right through my flesh and into my soul's deepest secrets.''\r\n''Akama must be warned. Our plans are in jeopardy!''\r\n==Completion==\r\n''I thank you, <name>. Olum is one of my dearest friends and most trusted followers. His contributions have been of vital importance to our plans.''\r\n==Quest Progression==\r\n* The Secret Compromised\r\n**Ruse of the Ashtongue\r\n**An Artifact From the Past\r\n**The Hostage Soul\r\n**Entry Into the Black Temple\r\n**A Distraction for Akama\r\n***Seek Out the Ashtongue\r\n***Redemption of the Ashtongue\r\n***The Fall of the Betrayer",},
			["The Seer's Library"] = { content = "#redirect [[Seer's Library]]", redirect = "Seer's Library",},
			["The Seer's Relic"] = { content = "==Objectives==\r\nAmaan the Wise at the Temple of Telhamat in [[Hellfire Peninsula]] wants you to return to Sedai's Corpse, northeast of the Temple of Telhamat, and use the [[Seer's Relic]] at that location. Return to him after you've completed this task. \r\n*Vision Granted\r\n* Seer's Relic (Provided)\r\n== Description==\r\nThe stubborn close their mind and convince themselves of one truth. The wise keep an open mind to the different possibilities leading to and stemming from the present.\r\nTake this relic with you to where you found Sedai. See not with your eyes, <name>, but with your mind. \r\n== Progress==\r\nHave you seen the vision yet, <name>? \r\n== Completion==\r\nI hope the vision you witnessed helped you gain some perspective on Sedai's death. The relic showed you a likely series of events leading up to the present. The truth may have been different, we'll never know for sure.\r\nWould you act differently knowing what you know now?\r\nWho can say whether our conflict with the orcs will continue? What's important is to remain open to the possibilities. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*12950 [[XP]] (or 4 gold 65 silver copper at level 70)\r\n*350 [[reputation]] with [[Exodar]]",},
			["The Sentinels and the Long Vigil"] = { content = "'''\"The Sentinels and the Long Vigil\"''' is a section of the [[History of Warcraft]], Chapter I.\r\nFound at:\r\n* [[Booty Bay]] in [[Stranglethorn Vale]]\r\nTimeline: \r\n* ← Previous book: [[Exile of the High Elves]]\r\n* → Next book: [[The Founding of Quel'Thalas]]",},
			["The Seven"] = { content = "'''The Seven''' were dark iron dwarves of great knowledge and power. It is likely that they were the ones who, along with [[Sorcerer-thane Thaurissan|Emperor Thaurissan]], summoned [[Ragnaros]] the Fire Lord to Azeroth.\r\nIn Alphabetic order (not the order you fight them), they are:\r\n*[[Anger'rel]]: casts Strike (increases the caster's next melee attack), Shield Black, [[Sunder Armor]]\r\n*[[Doom'rel]]: casts Summon Voidwalkers (summons three [[Voidwalker]]s), [[Curse of Weakness]], [[Demon Armor]], [[Immolate]], Shadowbolt Volley(targets everyone within 30 yards in front of the caster)\r\n*[[Dope'rel]]: casts [[Sinister Strike]], [[Backstab]], [[Gouge]]\r\n*[[Gloom'rel]]: casts [[Cleave]], [[Hamstring]], [[Mortal Strike]]\r\n*[[Hate'rel]]: casts Strike, [[Shadowbolt]], [[Mana Burn]], Shadow Shield(shields a set amount of damage and deals shadow damage to melee attackers)\r\n*[[Seeth'rel]]:casts [[Blizzard]], [[Frostbolt]], [[Frost Nova]], [[Frost Ward]], [[Frost Armor]] \r\n*[[Vile'rel]]: casts [[Heal]], [[Prayer of Healing]], [[Power Word: Shield]], [[Mind Blast]]\r\nAll of the mobs in the encounter are immune to curses. Also the event is entirely on a timer. After a set amount of seconds, the next mob will release and aggro the first player it sees.\r\nUpon their defeat, the [[Chest of The Seven]] is lootable.",},
			["The Seven Kingdoms"] = { content = "'''\"The Seven Kingdoms\"''' is a section of the [[History of Warcraft]], Chapter II. It is set 1,200 years before ''[[Warcraft: Orcs & Humans]]''.\r\nFound at:\r\n* Reliquary of [[Scholomance]] in the [[Western Plaguelands]]\r\n* The Scarlet Bastion (live side) of [[Stratholme]]\r\nTimeline: \r\n* ← Previous book: [[Ironforge - the Awakening of the Dwarves]]\r\n* → Next book: [[Aegwynn and the Dragon Hunt]]",},
			["The Sha'tar"] = { content = "#REDIRECT [[Sha'tar]]", redirect = "Sha'tar",},
			["The Shadow Council"] = { content = "#REDIRECT [[Shadow Council]]", redirect = "Shadow Council",},
			["The Shadow Stair"] = { content = "#redirect [[Shadow Stair]]", redirect = "Shadow Stair",},
			["The Shadow Vault"] = { content = "#redirect [[Shadow Vault]]", redirect = "Shadow Vault",},
			["The Shady Nook"] = { content = "#REDIRECT [[Shady Nook]]", redirect = "Shady Nook",},
			["The Shaft of Tsol"] = { content = "==Source==\r\nThis item drops from [[Revelosh]] in [[Uldaman]].\r\n==The Shaft of Tsol as an ingredient==\r\nThis item is used to make: \r\n* Staff of Prehistoria",},
			["The Shattered Halls"] = { content = "#REDIRECT [[Shattered Halls]]", redirect = "Shattered Halls",},
			["The Shattered Salute"] = { content = "==Objectives==\r\nPerform the Shattered Salute on [[Shenthul]].\r\n*Shattered Salute Performed\r\n==Description==\r\nAs a rogue of the [[Shattered Hand]], it is imperative that you learn the Shattered Salute. It is the only way to truly identify another member of the Hand.\r\nWatch, learn, repeat.\r\n==Completion==\r\nWell done, <name>. You are now ready to proceed.\r\n==Gains==\r\n*160 [[XP]]\r\n*14 reputation with [[Darkspear Trolls]]\r\n==Details==\r\nThis is a simple quest, and its main purpose is to teach the player the /salute emote (which the player will be required to do in the next quest in the series). Begin the quest and wait a few moments. [[Shenthul]] will start talking (in the chat window, not a quest dialog window), and eventually instructs the player watch him carefully as he performs the Shattered Salute. Once he is finished, the player should target him and use the /salute emote. [[Shenthul]] should acknowledge the salute and the question mark above him should turn gold. The player may then speak to him again to finish the quest. If there are any problems, the player can abandon the quest and try it again.\r\n==Additional Notes==\r\nThis is the first quest in the series that results in the player learning the [[Poisons]] skill.",},
			["The Shattered Strand"] = { content = "#REDIRECT [[Shattered Strand]]", redirect = "Shattered Strand",},
			["The Shatterer"] = { content = "'''The Shatterer''' is main hand mace with a disarm proc.\r\n==Source==\r\n'''The Shatterer''' is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 235 who also have the Weaponsmith specialty.\r\nComponents:\r\n* 24x Mithril Bar\r\n* 4x Core of Earth\r\n* 6x Truesilver Bar\r\n* 5x Citrine\r\n* 5x Jade\r\n* 4x Solid Grinding Stone\r\n* 4x Thick Leather\r\nThis [[recipe]] is learned from the Weaponsmith trainer.",},
			["The Shield of the Aesirites"] = { content = "==Source==\r\nThis item is provided for the quest The Shield of the Aesirites.\r\n==Objective of==\r\nThis item is an objective of The Shield of the Aesirites.",},
			["The Shifting Mire"] = { content = "#REDIRECT [[Shifting Mire]]", redirect = "Shifting Mire",},
			["The Shimmering Flats"] = { content = "#REDIRECT [[Shimmering Flats]]", redirect = "Shimmering Flats",},
			["The Shining Strand"] = { content = "#REDIRECT [[Shining Strand]]", redirect = "Shining Strand",},
			["The Shrine of Aessina"] = { content = "#REDIRECT [[Shrine of Aessina]]", redirect = "Shrine of Aessina",},
			["The Siege of Dalaran"] = { content = "#REDIRECT [[Siege of Dalaran]]", redirect = "Siege of Dalaran",},
			["The Silithyst Must Flow"] = { content = "In faraway [[Silithus]], geysers of a strange red crystalline dust have started to appear in the desert. Both the [[Alliance]] and the [[Horde]] have taken an interest in this new substance, which is called Silithyst, and researchers on both sides have discovered unique and valuable properties in the dust. The Horde and Alliance camps in the region have both been outfitted with turn-in stations where adventurers can unload the Silithyst they collect.\r\n==Overview==\r\nTo pick up Silithyst, locate a geyser and pick it up. The geyser will despawn, and the player will be carrying the Silithyst. While carrying it, your movement speed is reduced (abilities like \"[[Sprint]]\" will not have any effect) and you will be unable to mount without dropping the Silithyst. The other way of getting Silithyst is locating a player of the opposing faction carrying some. Upon damaging that player, he will drop his/her Silithyst, creating a Silithyst Mound allowing any player to temporarily pick up the Silithyst.\r\nAfter collecting Silithyst, run to your faction's turn in point, displayed on the map. A player may only carry one Silithyst at any time, so after each pickup, you will have to run and turn it in. The first faction to collect 200 Silithyst wins the race.\r\n==Rewards==\r\nA single turn in of Silithyst awards the player with the following:\r\n* 20 [[Reputation]] with the [[Cenarion Circle]] faction.\r\n* 19 [[Honor]] points\r\n* [[Traces of Silithyst]], a 30 minute [[buff]] increasing Melee and Spell damage dealt by 5%.\r\nIn addition, the faction that completes the race to 200 Silithyst will receive a zone wide buff, increasing [[Cenarion Circle Reputation Guide|Cenarion Circle reputation]] gained from killing monsters by 25%. The buff will apply to any player within [[Silithus]] and the [[Ahn'Qiraj]] [[instance]]s, even to those who enter them at a later time. It will persist through death until the opposing faction has collected 200 Silithyst and therefore won the race. A server reboot will reset the battle, which means both sides start at 0/200 Silithyst and lose their buff.\r\nThis buff is most useful in instances because of the greater amount of reputation collected from each kill. Although non-instance kills only grant 2 points of reputation, while the buff is in effect, every fourth kill will reward 4 reputation points. This of course is not a large bonus, but it is still slightly faster than non-buffed reputation farming.\r\nUnfortunately, many may find that the honor and reputation bonus are not enough to reward their efforts. The reputation and honor given are both too low to make a day of Silithyst collecting worthwhile compared to the rewards given through the [[battlegrounds]] or the various methods of Cenarion Circle reputation farming. As a result, you will rarely find many people collecting any Silithyst. Most often, if at all, you will find players doing this activity while waiting for their turn to enter a [[battleground]], and sometimes raid groups while forming an instance run.",},
			["The Silver Covenant"] = { content = "#REDIRECT [[Silver Covenant]]", redirect = "Silver Covenant",},
			["The Sin'loren"] = { content = "'''The ''Sin'loren''''' is a [[blood elf]] [[destroyer]] in the waters north of the [[Sun's Reach Harbor]], [[Isle of Quel'Danas]]. She is the southernmost ship of the fleet.\r\nThis ship is one of three containing [[Dawnblade (blood elves)|Dawnblade]] blood elves, as reinforcements for Kael's forces on the Isle of Quel'Danas.\r\nThis is also the ship you land on with your [[Unrestrained Dragonhawk|dragonhawk]] to slay the elves, after having set the sails ablaze preventing them from getting to their destination.",},
			["The Singing Crystals"] = { content = "In '''The Singing Crystals''', you must collect Pulsing Blue Shard from [[Ironjaw Basilisk|Basilisks]] which [[Kin'weelay]] will use to control the powerful magic gem, [[The Mind's Eye]] in order to save [[Yenniku]]. This quest is in a long chain of quests originally starting at [[Nimboya]] in [[Grom'gol Base Camp]], the most recent quest being The Fate of Yenniku.\r\n==Objectives==\r\nBring 3 Pulsing Blue Shard to [[Kin'weelay]] in [[Grom'gol Base Camp]].\r\nYou will need:\r\n* Pulsing Blue Shard x3\r\n==Details==\r\nThe [[Ironjaw Basilisk| Ironjaw Basilisks]] can be found in the [[Crystalvein Mine]], which is in [[Stranglethorn Vale]] in the mountains east of the [[Gurubashi Arena]]. The critters are actually inside the cave, the Basilisks outside are a different type. The shards have an extremely high drop rate so this should take no time at all.\r\n==Description==\r\nLegends tell of a jewel, hidden deep in the heart of Stranglethorn. We call it the Mind's Eye, and it has great powers. If you gain this Eye then, perhaps, we can use it to bring lost Yenniku back from the darkness.\r\nI will consult with the spirits of the jungle to find the Mind's Eye. While I do this, you enter the Crystalvein Mine, southeast of here, and gather Pulsing Blue Shards from Ironjaw Basilisks. The shards are rare, but we will need their magic to bend the Mind's Eye to our will.\r\n==Reward==\r\nYou will be rewarded with the following:\r\n* 390-3900 XP\r\n==Progress==\r\nDo you have the shards, <name>? They are needed for my final ritual, after we have the Mind's Eye.\r\n==Completion==\r\nYou have done well, <name>. These shards are well formed. Already I hear them sing to me.\r\nAnd while you were gone, I spoke with the spirits of the jungle. I know where the Mind's Eye rests...\r\n...And who guards it.",},
			["The Six"] = { content = "#REDIRECT [[Council of Six]]", redirect = "Council of Six",},
			["The Skettis Offensive"] = { content = "==Objectives==\r\nHold off the attackers and speak with Rilak. \r\n* Attack thwarted\r\n* '''Suggested Players [2]'''\r\n==Description==\r\nSkettis has waged war on us! Have you gathered enough to help with Shattrath's defense?\r\nHold off the attackers! \r\n==Reward==\r\nYou will also receive: 9 gold 90 silver copper \r\n \r\n==Completion==\r\nI applaud your prowess in combat, <class>. You have proven yourself to be a true defender of the Light. May A'dal's blessing shine upon your darkest hours.\r\nBut look far into the horizon. Dark skies loom above Skettis. Terokk is undoubtedly plotting his next move. Shattrath is safe for now. But only tomorrow knows what terror will descend upon us. \r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*16500[[XP]] (or 9 gold 90 silver copper at level 70)\r\n*500 [[reputation]] with [[Lower City]]",},
			["The Skittering Dark"] = { content = "#REDIRECT [[Skittering Dark]]", redirect = "Skittering Dark",},
			["The Skull of Gul'dan"] = { content = "The '''Skull of Gul'dan''' was a powerful demonic artifact created from the skull of the orc sorcerer [[Gul'dan]]. Used for a plethora of demonic activity, from opening portals to corrupting the forests of Ashenvale, it was finally consumed by Illidan and may have been destroyed (see Current Status, below).\r\n==History==\r\nAfter the insidious warlock [[Gul'dan]] died, his skull was turned into a channeling totem for demonic energy. It was briefly held by a low-ranking [[Bonechewer]] officer. The skull was acquired by [[Ner'zhul]] for use in opening portals to other worlds, which also required the [[Book of Medivh]], the [[Eye of Dalaran]], and the [[Jeweled Scepter of Sargeras]].\r\n[[Alleria Windrunner]] and [[Danath Trollbane]] managed to steal the skull and the Book of Medivh from Ner'zhul well into the [[Alliance Expedition]]'s campaign. When [[Khadgar]] used the Skull and the Book to close the [[Dark Portal]] forever, he cast away the skull (as seen in the closing cinematic of [[Warcraft II: Beyond the Dark Portal]]). \r\nYears later it would appear again on [[Azeroth]], this time used by the [[Burning Legion]] to corrupt the forests of [[Felwood]]. The skull was eventually consumed by [[Illidan Stormrage]], who absorbed its power, becoming half [[night elf]] and half [[demon]]. In doing so, he struck a major blow to the Legion, killing [[Tichondrius]]. Illidan retained memories of the [[Tomb of Sargeras]] from Gul'dan, which he used in tandem with his own knowledge of [[Suramar]] to find the [[Eye of Sargeras]].\r\n''Exactly how the Legion regained the Skull is unknown. However, we do know that the Hellfire Pennisula, where the portal was located, is now the major landmass of [[Outland]], and that the legion ruled Outland for years through [[Magtheridon]]. The most likely theory is that Magtheridon located the Skull and returned it to the Eredar. On a different note, the full effects of the Skull of Gul'dan upon Illidan's psyche and magic are unknown.''\r\n==Current Status==\r\nWhether or not the skull still exists is not entirely clear. In [[Warcraft III]], Illidan appears to destroy the skull with his blades before morphing into demon form. Later it is stated that he \"consumed\" the skull (\"consumed\" = \"destroyed\"). However, the cutscenes in Warcraft III did not always employ the most precise unit animations, a limitation of the game engine. The skull's destruction could have been retconned.\r\nFurthermore, it is unclear what exactly was meant by \"consumed.\" He could have literally consumed the skull (i.e. ate it). There is precedent in Warcraft for digestion as a means of gaining magical powers (for example [[potions]], which are of course liquids), so it is possible he drank something from the skull. \r\n\"Consume\" may refer to draining the artifact of its magical energy and absorbing it himself. If this is the case, then it is quite possible the physical skull still exists, although it is likely no more significant than any other orc skull.\r\nThe opening cinematic of [[the Burning Crusade]] features Illidan holding a skull in his claws, and he can be seen in-game doing the same thing. It is possible that this is the Skull of Gul'dan, which Illidan kept in his possession for unknown reasons (possibly sentimental value, unless it is revealed that it still has magical properties). Though there is no other skull with a lore connection to Illidan, he is shown in what looks like a battlefield, so it could just be a random skull.",},
			["The Skull of Tyrannistrasz"] = { content = "'''The Skull of Tyrannistrasz''' is located in the [[Hall of Explorers]] in [[Ironforge]].",},
			["The Skybreaker"] = { content = "'''''The Skybreaker''''' is an [[Alliance]] [[gunship]] currently patrolling above [[Icecrown]] and serving as the mobile base of operations for the Alliance forces in the area.\r\n==Background==\r\nA marvelous feat of gnomish and dwarven engineering, the ''Skybreaker'' is driven by numerous powerful propeller engines, armed with over twenty cannons, and crewed by a full compliment of marines ready to fight at a moment's notice. Under the able command of [[High Captain Justin Bartlett]] the ''Skybreaker'' is the first line of attack for the Alliance war effort against the [[Lich King]]. There you may also find [[Thassarian]], the first human Death Knight.\r\nAll is not quiet in the skies above Icecrown however. The arrival of the [[Horde]]'s new airship, ''[[Orgrim's Hammer]]'', has sparked open hostilities. Only time will tell if the brave crew of the ''Skybreaker'' can stand up to the Horde's newest behemoth in addition to the ravenous Undead of the Lich King's Scourge.\r\n==Crew==\r\n* High Captain Justin Bartlett\r\n* Sky-Captain Mark Jackson\r\n* Knight-Captain Drosche\r\n* Chief Officer Leonards\r\n* Chief Engineer Boltwrench\r\n* Navigator Anderlain\r\n* Navigator Dobbs\r\n* Galley Chief Dolinger\r\n* Absalan the Pious\r\n* Vindicator Maraad\r\n* Thassarian\r\n* Skybreaker Shield-Mage\r\n* Skybreaker Marine\r\n* Skybreaker Cannoneer\r\n* Skybreaker Engineer\r\n* Skybreaker Deckhand",},
			["The Slag Pit"] = { content = "#REDIRECT [[Slag Pit]]", redirect = "Slag Pit",},
			["The Slaughtered Lamb"] = { content = "#REDIRECT [[Slaughtered Lamb]]", redirect = "Slaughtered Lamb",},
			["The Slave Pens"] = { content = "#REDIRECT [[Slave Pens]]", redirect = "Slave Pens",},
			["The Slithering Scar"] = { content = "#REDIRECT [[Slithering Scar]]", redirect = "Slithering Scar",},
			["The Sludge Fen"] = { content = "#REDIRECT [[Sludge Fen]]", redirect = "Sludge Fen",},
			["The Smoldering Ruins of Thaurissan"] = { content = "==Objectives==\r\nListen to [[Royal Historian Archesonus]] recant the history of [[Ruins of Thaurissan|Thaurissan]].\r\n== Description==\r\nWould you like to hear a brief history of the [[Dark Iron dwarves]]? \r\n==Progress==\r\nAllow me to finish telling you the story of Thaurissan.\r\n==Completion==\r\nShall we proceed?\r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*5450 [[XP]] (or 33 silver copper at level 70)\r\n*10 [[reputation]] with [[Ironforge]]\r\n==The history of Thaurissan==\r\n''I am ready, Historian Archesonus.''\r\nHundreds of years ago, the great city of Thaurissan stood proudly in a lush expanse of land that is now the dilapidated [[Burning Steppes]].\r\nThaurissan was home to the nation of Dark Iron dwarves and at the time, in the midst of a civil war among the dwarven nation at large.\r\nYou see, that area of the world was at one point in time part of the Redridge Mountains - until the day that Thaurissan was consumed by a gigantic explosion. The city lay in ruin, the surrounding areas reduced to an ashy wasteland.\r\n''That is tragic. How did this happen?''\r\nWe do not know.\r\nThe Dark Irons that did survive made their way into the mountain and began rebuilding their city.\r\nFrom the ashes of Thaurissan then rose [[Blackrock Spire]] and the new Dark Iron nation. Additional fortifications were made within the [[Searing Gorge]], in the area known as the [[Cauldron]].\r\nStories of an ancient evil that controlled the kingdom of Dark Irons began to circulate.\r\n''Interesting, continue please''\r\nRecently, the Dark Irons have been seen on the surface world with greater regularity. Fortresses have been built in the [[Badlands]]. Massive exploratory forces have been sent into the depths of [[Uldaman]] in search of ancient lore. They have even invaded our own homeland, striking at our [[Stonewrought Dam|dam]] near the loch.\r\n''Unbelievable! How dare they??''\r\nWe need adventurers to assist us, <name>. Will you help?\r\n''Of course I will help!''\r\n==Quest progression==\r\n# The Smoldering Ruins of Thaurissan\r\n# The Smoldering Ruins of Thaurissan (2)",},
			["The Smoldering Ruins of Thaurissan (2)"] = { content = "==Objectives==\r\nVenture to the [[Ruins of Thaurissan]] in the [[Burning Steppes]] and recover information from the [[Thaurissan Relic]]s. Return to [[Royal Historian Archesonus]] when you have recovered the information. \r\n*Information Recovered (12)\r\n== Description==\r\nVenture to the smoldering ruins of Thaurissan in the [[Burning Steppes]] and gather as much information as possible.\r\nIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, <name>. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected. \r\n== Completion==\r\nOh my! This information explains quite a lot about Thaurissan.\r\nThere is much more to learn! \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*5450 [[XP]] (or 33 silver copper at level 70)\r\n*250 [[reputation]] with [[Ironforge]]\r\n== Reward==\r\nYou receive\r\n*Ring of the Aristocrat\r\nYou will also receive:1 gold 65 silver copper \r\n==Notes==\r\nSome of the information received from the relics:\r\n* A tormented voice whispers: He cannot be defeated. <The relic burns to nothing. The memories it held are now your own. This city was destroyed by a being not of this world.>\r\n* A tormented voice whispers: Your existence is acknowledged. <The relic turns to dust. Your head throbs with newfound wisdom. Something evil lurks in the heart of the mountain.>\r\n* A tormented voice whispers: Help us, outsider. <The relic cumbles to dust. A vision of eight Dark Iron dwarves performing some sort of ritual fills your head.>\r\n* A tormented voice whispers: Leave this place. <The relic emits a white hot arc of flame. A memory has been gained: A lone Dark Iron dwarf is surrounded by seven corpses, kneeling before a monolith of flame.>\r\n* A tormented voice whispers: Defiler... you will be punished for this incursion. <A symbol of flame radiates from the relic before it crumbles to the earth.>\r\nThese clues refer to the [[Summoners' Tomb]], and presumably the Emperor himself, summoning ... any of several options apply: [[Bael'Gar]], [[Magmus]], possibly [[Lord Incendius]]. ... Or some presence that has since left the mountain.\r\n==Quest progression==\r\n# The Smoldering Ruins of Thaurissan\r\n# The Smoldering Ruins of Thaurissan (2)",},
			["The Song of Aegwynn"] = { content = "'''The Song of Aegwynn''' is a tale of [[Aegwynn]]'s fight against [[Sargeras]] (see [[Aegwynn and the Dragon Hunt]]).\r\n===The Song of Aegwynn===\r\nThe Song of Aegwynn was also the code for the [[Guardian of Tirisfal]], It was after Medivh murdered the Trisfalen council, that he brought the book back to his domain of Karazhan, Khadgar was believed to have found the Song, and before the tower was left abandoned, Khadgar took the most valuble books, including the Song of Aegwynn. The song of Aegwynn is written in a 'song' that tells the very story of how Aegwynn \"defeated\" Sargeras. but she only destroyed his avatar, letting his soul rest in her bonds, until Medivh was born.\r\n===The Song of Aegwynn===\r\nIn ages old,\r\nthe Guardians hold the power to end demonkind.\r\nTheir greatest shine,\r\nher powers divine\r\nthe first female Magna of all time.\r\nAegwynn was she named,\r\nand was credited her Fame \r\nfor her defeat of the demon god Sargeras.\r\nCold was the path she stood upon,\r\nwhen she took the demons head on.\r\nA dragon hunt the demons sought,\r\nbut a battle with Aegwynn did they fought.\r\nWith the sharpness of blades and bitterness of death,\r\nthe bolt she summoned charred them to ashes.\r\nFrantic and maddened the demons were,\r\nand they summoned forth the Legion.\r\nThey tried to charge forth to finish her,\r\nyet had no hold over her in this region.\r\nAn alliance with the dragons she had,\r\nand they ripped into the demons' ranks.\r\nChanting, both demons and Guardian were,\r\nto serve each's needs of destruction.\r\nA bright blast of energy converged,\r\nas Aegwynn finished her conjuration.\r\nDemons and dragons perished under the bright light,\r\nand was when Sargeras arrived!\r\nHis colossal body was made of bronze,\r\nand he wore a black obsidian armour.\r\nHe had burning hair and huge horns,\r\nhis eyes had the Infinite Abyss' colour.\r\nHe carried a runed spear with blood that fall,\r\nand its long tail ended in a great fireball.\r\nThe dragons fled, with two great powers left.\r\nAegwynn of Tirisfal, and Sargeras of Legion.\r\nAegwynn gathered within her all her powers,\r\nand with a blast let Sargeras witness her prowess.\r\nA rainbow strike thrusted into his chest,\r\nand he fell back as he's about to face death.\r\nThe Dark Lord sought to recover his strength,\r\nbut the Guardian stopped it with another flash.\r\nSargeras' avatar was now destroyed,\r\nas his powers left him into the void.\r\nAs the ice cracked, he sank to doom,\r\nand what lays beneath is now his tomb.",},
			["The Sons of Hodir"] = { content = "#REDIRECT [[Sons of Hodir]]", redirect = "Sons of Hodir",},
			["The Soul Cannon of Reth'hedron"] = { content = "'''The Soul Cannon of Reth'hedrons''' is a collection quest, having players collect several trade goods and a quest item from [[Sar'this]] in [[Lake Jorune]] above [[Stonebreaker Hold]] in [[Terokkar Forest]]. This quest is available at reputation with [[Netherwing]].\r\n==Objectives==\r\n[[Illidari Lord Balthas]] at the [[Dragonmaw Base Camp]] in [[Shadowmoon Valley]] wants you to bring him 2 Felsteel Bars, 1 Adamantite Frame, 1 Khorium Power Core and 1 Flawless Arcane Essence.\r\nYou will need:\r\n*Felsteel Bar (2)\r\n*Adamantite Frame \r\n*Khorium Power Core\r\n*Flawless Arcane Essence\r\nProvided Item:\r\n*Illidari Lord Balthas' Instructions\r\nRaw Materials Breakdown:\r\n*12 [[Fel Iron Ore]] \r\n*8 [[Adamantite Ore]]\r\n*8 [[Eternium Ore]]\r\n*6 [[Khorium Ore]]\r\n*1 [[Primal Fire]]\r\n*1 [[Primal Earth]]\r\n==Description==\r\nReth'hedron now lords over the Twilight Ridge of Nagrand. An eredar of such power being loosed upon this world does not bode well for the Illidari. Alas, we do not have the resources required to slay Reth'hedron. Not with the war the bastards have brought to the Black Temple. No... I have a better plan.\r\nYou will subdue Reth'hedron, banishing him back through the Twilight Portal. For this a soul cannon must be fashioned.\r\nReturn to me with the materials on this list.\r\n==Details==\r\nTo collect a Flawless Arcane Essence, players must travel to [[Lake Jorune]] above [[Stonebreaker Hold]] in [[Terokkar Forest]] and complete the task [[Sar'this]] asks. This entails killing five level 70 elementals.\r\n==Progress==\r\nHave you gathered the components required to fashion the soul cannon?\r\n==Completion==\r\n<Balthas deftly combines the components you brought him.>\r\nYou are now ready for the second phase of the plan, captain.\r\n==Quest Progression==\r\n* The Soul Cannon of Reth'hedron\r\n** Subdue the Subduer",},
			["The Spawning Glen"] = { content = "#REDIRECT [[Spawning Glen]]", redirect = "Spawning Glen",},
			["The Spectral Chalice"] = { content = "This quest teaches those with [[mining]] skill 230 how to smelt [[Dark Iron Ore]] into bars.\r\n==Objectives==\r\nThe spectral chalice floats in the air, slowing rising and falling... as if to the beat of a dying heart. \r\n* Gold Bar (20)\r\n* Truesilver Bar (10)\r\n* Star Ruby (2)\r\n== Completion==\r\nThe gems make no sound as they fall into depths of the chalice... \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*5650 [[XP]] (or 34 silver 50 copper at level 70)",},
			["The Stadium"] = { content = "#REDIRECT [[Stadium]]", redirect = "Stadium",},
			["The Stagnant Oasis"] = { content = "#REDIRECT [[Stagnant Oasis]]", redirect = "Stagnant Oasis",},
			["The Stagnant Oasis (quest)"] = { content = "The Stagnant Oasis is the 3rd quest in the '''The Barrens Oases''' quest chain.\r\n==Objectives==\r\nReturn to Tonga at The Crossroads, after investigating the Stagnant Oasis.\r\n*Test the Dried Seeds\r\nProvided Item:\r\n* Dried Seeds\r\n==Description==\r\nLike the one you found at the Forgotten Pools, there may be fissures at the other oases in the Barrens. If so, then perhaps the fissures are the oases' source of life.\r\nWe must test this.\r\nHere, take these seeds. They are dead and infertile, but take them to the Stagnant Oasis to the southeast. If there is a fissure there, then place the seeds within it...and observe.\r\n==Completion==\r\nYour findings are amazing! The seeds I gave you were dried, and dead. Whatever rests under these oases can create life from nothing!\r\nWe must study this more...\r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*1150 [[XP]] (or s=7 gold c=20 silver at level 70)\r\n*250 with [[Thunder Bluff]]\r\n==Quest chain==\r\n#The Barrens Oases\r\n#The Forgotten Pools\r\n#The Stagnant Oasis\r\n#Altered Beings\r\n#Hamuul Runetotem\r\n#Nara Wildmane\r\n#Leaders of the Fang",},
			["The Stair of Destiny"] = { content = "#REDIRECT [[Stair of Destiny]]", redirect = "Stair of Destiny",},
			["The Steamvault"] = { content = "#REDIRECT [[Steamvault]]", redirect = "Steamvault",},
			["The Stockade"] = { content = "#REDIRECT [[Stormwind Stockade]]", redirect = "Stormwind Stockade",},
			["The Stockpile"] = { content = "#REDIRECT [[Stockpile]]", redirect = "Stockpile",},
			["The Stone"] = { content = "==Objectives==\r\nObtain a [[Voidstone]] from the [[Dead Scar]]. \r\n== Description==\r\nWhile I'm certain your imp has proven a useful and sometimes entertaining servant, it is time you mastered a more powerful demon: the voidwalker.\r\nTravel down the Dead Scar until it is crossed by the [[Elrendar River]]. Just south of the river, locate one of the blue glowing stones and take it. Your path will be revealed there. \r\n== Completion==\r\nAs you gaze into the stone, your vision begins to swirl... \r\n== Gains==\r\n*850 [[XP]] (or 5 silver 10 copper at level 70)",},
			["The Stonefield Farm"] = { content = "#REDIRECT [[Stonefield Farm]]", redirect = "Stonefield Farm",},
			["The Stonewrought Dam"] = { content = "==Objectives==\r\nTake the orphan to the Stonewrought Dam in Loch Modan. You should take him to the middle of the dam so he can see out over the giant waterfall.\r\n*Go to the top of the Stonewrought Dam in Loch Modan.\r\n==Description==\r\nIronforge is where all the dwarves and gnomes live. Near there is a place called Loch Modan, and the dwarves built a HUGE dam there. They say it's one of the biggest things anyone's ever made. Wow!\r\nCould you take me to Loch Modan and see the dam there, please? I think it is the Stone... um... Stonewrench Dam? Stonewrought? It's big - that's for sure. I'd like to look out over the big waterfall. I promise I won't lean over too far!\r\n==Completion==\r\nWOW - the dam was WAY bigger than I thought! I could barely hear myself talk from the sound of all the rushing water! Hey, do you think it would ever run out of water? Man, what would happen if that dam ever broke! WOW, that would be scary!\r\nThanks for taking me to see the dam. That was very kind of you. I told you I wouldn't lean over too far!\r\n==Gains==\r\nUpon completion of this quest you will gain:\r\n*650 [[XP]]\r\n*75 with [[Darnassus]]\r\n*75 with [[Exodar]]\r\n*75 with [[Gnomeregan Exiles]]\r\n*75 with [[Ironforge]]\r\n*75 with [[Stormwind]]\r\n==Quest Chain==\r\n*Children's Week (Alliance)\r\n**Spooky Lighthouse\r\n**The Stonewrought Dam\r\n**The Bough of the Eternals\r\n**You Scream, I Scream...\r\n**Jaina's Autograph\r\n***A Warden of the Alliance",},
			["The Stone of the Tides"] = { content = "'''Legends of the Gurubashi, Volume 3'''\r\n''\"Stone of the Tides\"''\r\n==Text==\r\n* '''Introduction'''\r\nThe ancient [[Gurubashi Empire]] was a source of many fascinating and intriguing legends that can be no doubt traced to their environs, as examinations of their belief systems and societal practices have pointed to a great reverence for their natural surroundings. While I have delved into many aspects of their [[snake]]-worship in previous volumes of this study, I put forth here an examination of the [[troll]]s' interesting and unique relationship with the sea.\r\n* '''The Great Sea'''\r\nThe Gurubashi Empire was surrounded on three sides by the sea, so it comes as little surprise that water would figure prominently as an aspect of their society. While the trolls were able to roam and control the large areas of their jungle empire, the sea eluded them. It was vast and immeasurable, no doubt a disconcerting neighbor for the powerful trolls. It should be noted here that recent discoveries seem to suggest that the trolls had little interest in exploring the lands beyond the [[Great Sea]]. While the troll species have been encountered along the length and breadth of [[Azeroth]], [[Khaz Modan]] and [[Lordaeron]], little evidence of their civilization has been found in the newly discovered lands of Kalimdor or upon the islands in the [[South Seas]]. Whether this demonstrates an unwillingness of the trolls to venture away from their terrestrial holdings or a failure on their part to develop the technologies needed to make such a journey will take further research and analysis that is out of the scope of my writings here. But one can hardly ignore so large a presence, and new findings in the extensive troll ruins of [[Stranglethorn Vale]] show and aspect of their relationship with the sea previously unknown and undocumented.\r\n* '''The Stone of the Tides'''\r\nRecent discoveries during surveys of the troll ruins of Stranglethorn Vale have shown references to an object known as the \"Stone of the Tides\". Various fragments of the troll legends can be pieced together to paint a rather complete picture of the Stone and its importance to the ancient Gurubashi Empire. It appears that the Stone of the Tides allowed its bearer to control [[water]] in its many forms, rivers, rain, and the tides. Because of the stories related to use of the Stone of the Tides. I have conjectured that it is actually a physical manifestation of the powers of [[Neptulon the Tidehunter|the Waterlord]], a powerful elemental of the seas. How and why such an object would leave the Waterlord's control and fall into the hands of the trolls is another question that is beyond the scope of my knowledge.\r\n* '''The Tidebearer'''\r\nLike the movements of the eponymous tides, the Stone of the Tides entered the world of the trolls and departed, never constantly staying in the trolls' hands for longer than a generation at a time. In troll legends, it is said that the first time the Stone of the Tides came to the Gurubashi Empire, it was found by a troll [[warrior]] wandering along the coast of Stranglethorn. He came upon a mysterious blue stone within which milky white strands floated and flowed. Intrigued by the stone, the warrior took it with him and continued upon his journey. Over the weeks and months, the warrior discovered that the stone had given him control over water. He could summon forth water [[elementals]], creatures formed completely of water--duplicating a feat that only powerful [[mage]]s of the [[Kirin Tor]] are able to perform.\r\nThe warrior traveled to [[Zul'Gurub]], to the heart of the empire, to show his newfound abilities to the Emperor. He easily gained a court audience after demonstrating his powers in the center of the Imperial capital. His powers easily amazed the Gurubashi Emperor, who immediately gave him a place of honor at court, naming the warrior \"[[Tidebearer]]\", leaving his old name behind. For years, the Tidebearer served the Gurubashi Empire, summoning his thrall water elementals in battle and manipulating the flow of water in Stranglethorn Vale for the benefit of the Empire. But as the years went on, the Tidebearer became more reclusive, tending to stay for long periods of time away from court.\r\nThe Tidebearer was hiding a secret from the prying eyes of court. The abilities granted to him by the Stone of the Tides also came with a curse. As the years passed, the Tidebearer was fading away. With each coming and going of the tides, the Tidebearer became less of himself, losing his corporeal form--pulsing in and out of existence--until in his dying days he traveled to the beach where he had first found the Stone, and walked into the sea, disappearing for the last time. Generations later, the Stone of the Tides washed upon the shores of Stranglethorn, and another Tidebearer was chosen, as the troll brought the Stone to Zul'Gurub. So the process continued for generations, the Stone appearing with the tide, and the Tidebearer leaving into the tide. \r\nModern day accounts of the Stone of the Tides have appeared from place to place, but one must still wonder why an object of such power would appear with such regularity, and by whose design.",},
			["The Stormspire"] = { content = "#REDIRECT [[Stormspire]]", redirect = "Stormspire",},
			["The Storm Peaks"] = { content = "#REDIRECT [[Storm Peaks]]", redirect = "Storm Peaks",},
			["The Story of Morgan Ladimore"] = { content = "==Contains==\r\n==Source==\r\nThis item is a quest reward from the following quests:\r\n* Morgan Ladimore\r\n* Stormwind Library",},
			["The Sundering"] = { content = "'''''The Sundering''''' is the third book of the [[War of the Ancients Trilogy]] [[novels]].\r\nThis book describes the last events in the new timeline of the [[War of the Ancients]], and focuses specifically on the events leading up to the [[Great Sundering]] of [[Azeroth]]; the great explosion that ripped the continents of Azeroth apart and created the continents we see today.\r\n==Description==\r\nThe hour of wrath draws near&hellip;\r\nThe valiant [[Night elf|night elves]] have been shattered by the loss of [[Kur'talos Ravencrest|their beloved general]]. The [[black dragon]], [[Deathwing|Neltharion]], has claimed the [[Demon Soul]] and scattered the mighty [[dragonflight]]s to the winds. Above all, the demonlord, [[Archimonde]], has led the [[Burning Legion]] to the very brink of victory over [[Kalimdor]]. As the land and its denizens reel from this unstoppable evil, a terror beyond all reckoning draws ever nearer from the [[Well of Eternity]]'s depths...\r\nIn the final, apocalyptic chapter of this epic trilogy, the [[dragon]]-[[mage]] [[Krasus]] and the young [[druid]] [[Malfurion Stormrage|Malfurion]] must risk everything to save [[Azeroth]] from utter destruction. Banding together the [[Earthen|dwarves]], [[tauren]] and [[furbolg]] races, the heroes hope to spark an alliance to stand against the might of the Burning Legion. For if the Demon Soul should fall into the Legion's hands, all hope for the world will be lost. This then, is the hour... where past and future collide!\r\n==Characters==\r\n==Locations==\r\n*[[Aru-Talis]]\r\n*[[Emerald Dream]]\r\n*[[G'Hanir]]\r\n*[[Great Sea]]\r\n*[[Hajiri]]\r\n*[[Mount Hyjal]]\r\n**[[Nordrassil]]\r\n*[[Suramar]]\r\n*[[Zin-Azshari]]\r\n**[[Azshara's Palace]]\r\n**[[Well of Eternity]]\r\n==Other==\r\n*[[Limbo]]\r\n==See also==\r\n*For more information, please see: [[War of the Ancients (novel account)]] and [[War of the Ancients (WC3 account)]].",},
			["The Sundering of the World"] = { content = "'''\"The Sundering of the World\"''' is a section of the [[History of Warcraft]], Chapter I.\r\nTimeline: \r\n* ← Previous book: [[The War of the Ancients]]\r\n* → Next book: [[Mount Hyjal and Illidan's Gift]] \r\n==See also==\r\n* [[Well of Eternity]]\r\n* [[Maelstrom]]\r\n* [[Naga]]",},
			["The Sunreavers"] = { content = "#REDIRECT [[Sunreavers]]", redirect = "Sunreavers",},
			["The Sunspire"] = { content = "#REDIRECT [[Sunspire]]", redirect = "Sunspire",},
			["The Suntouched Pillar"] = { content = "#REDIRECT [[Suntouched Pillar]]", redirect = "Suntouched Pillar",},
			["The Sunwell Trilogy"] = { content = "==Editions==\r\n*'''Hardcover Collection''': [[Ultimate Edition]]\r\n*'''Volume 1:''' [[Dragon Hunt]]\r\n*'''Volume 2:''' [[Shadows of Ice]]\r\n*'''Volume 3:''' [[Ghostlands (book)|Ghostlands]]\r\n==Major Characters==\r\n*[[Kalecgos|Kalecgos (Kalec)]]\r\n*[[Anveena]]\r\n*[[Tyrygosa|Tyrygosa (Tyri)]]\r\n*[[Jorad Mace]]\r\n*[[Raac]]\r\n*[[Snee]]\r\n*[[Voll]]\r\n*[[Groth]]\r\n*[[Harkyn Grymstone]]\r\n*[[Dar'Khan Drathir]]\r\n*[[Valimar Mordis]]\r\n*[[Trag Highmountain]]\r\n*[[Ichor]]\r\n*[[Loggi Grymstone]]\r\n*[[Korialstrasz|Korialstrasz (Borel, Krasus)]]\r\n*[[Lor'themar Theron]]\r\n*[[Halduron Brightwing]]\r\n*[[Sylvanas Windrunner]]\r\n*[[Dath'Remar Sunstrider]]\r\n''Return to [[Sources]] page''\r\n==Notes==\r\nThe Sunwell Trilogy occurs concurrently with Brann's journey through the Eastern Kingdoms as chronicled in [[Lands of Conflict]]. Dragonhunt covers the fall of Tarren Mill, which occurs before Brann Bronzebeard's journey through Hillsbrad (after the Forsaken had taken over the town). Ghostlands occurs not long after Brann's journey through Quel'Thalas. Brann had reached Quel'Thalas before the blood elves had retaken Silvermoon, or any areas in Quel'Thalas.",},
			["The Sun Eater"] = { content = "'''The Sun Eater''' drops from [[Pathaleon the Calculator]] in [[Mechanar|The Mechanar]] of [[Tempest Keep]] on [[Heroic Mode|Heroic mode]].\r\n*Also see: [[Sun Eater vs. King's Defender]].",},
			["The Swarming Pillar"] = { content = "#REDIRECT [[Swarming Pillar]]", redirect = "Swarming Pillar",},
			["The Swarm Grows"] = { content = "'''The Swarm Grows''' is the first step to short series of quests involving silithid monsters in [[Thousand Needles]].\r\n====To Get This Quest====\r\nAt the [[Crossroads]] in the [[Barrens]], talk to [[Korran]] the troll, coordinates (51,29).\r\n==Objectives==\r\nDeliver Korran's Sealed Note to [[Belgrom Rockmaul]] in [[Orgrimmar]].\r\nYou will need:\r\n* Korran's Sealed Note (provided)\r\n==Details==\r\nHead to [[Orgrimmar]] to the [[Valley of Honor]]. [[Belgrom Rockmaul]] is outside the biggest building, pretty much as soon as you come in the valley. Coordinates (75,34).\r\n==Description==\r\n''Many travelers who've come through the [[Crossroads]] helped me gather eggs from the [[Field of Giants]], and many of them have tales of how deadly the creatures are. I've heard enough to consider them insects a much larger threat than my masters first thought.\r\n''I need a courier to travel to [[Orgrimmar]] to meet [[Belgrom Rockmaul]]. It be no simple matter, and someone who would take the task seriously should go.\r\n''Belgrom usually be found outside the warriors' guild house.\r\n==Progress==\r\n''I envy you, <class>. You have the look of someone who's been outside the walls of [[Orgrimmar]] for a while.\r\n''I myself would travel in the name of the Warchief if [[Thrall]] didn't have need of my skills here in the city. But he leads us well, and I trust his judgement--I remain here for as long as he needs me.\r\n==Completion==\r\n''Ah, a note from [[Korran]]. He has been a loyal servant for some time now. I was wondering how his duties were going in the [[Crossroads]].\r\n==Quest progression==\r\n* The Swarm Grows\r\n** The Swarm Grows (2)\r\n*** The Swarm Grows (3)",},
			["The Tainted Scar"] = { content = "#REDIRECT [[Tainted Scar]]", redirect = "Tainted Scar",},
			["The Talondeep Path"] = { content = "#REDIRECT [[Talondeep Path]]", redirect = "Talondeep Path",},
			["The Talon Den"] = { content = "#REDIRECT [[Talon Den]]", redirect = "Talon Den",},
			["The Talon King's Coffer"] = { content = "'''The Talon King's Coffer''' is located in the [[Halls of Mourning]] in [[Sethekk Halls]], after the last boss.\r\n==Contains==\r\n*Shadow Labyrinth Key",},
			["The Taunka"] = { content = "#REDIRECT [[Taunka]]", redirect = "Taunka",},
			["The Tauren Chieftains"] = { content = "#REDIRECT [[Elite Tauren Chieftain]]", redirect = "Elite Tauren Chieftain",},
			["The Tempest Key"] = { content = "The Tempest Key allows players to enter [[The Eye]] - the center palace of [[Tempest Keep]] - and defeat [[Kael'thas Sunstrider]]. This fight is required for several attunement quests. The Tempest Key is not used like an actual key, but rather, like the [[Drakefire Amulet]], it is a passive item that attunes you to the instance.\r\n==Obtaining the Tempest Key==\r\nThe Tempest Key is given after a long quest chain that begins after completing [[The Hand of Gul'dan quest chain]] (starts with The Hand of Gul'Dan) for The Cipher of Damnation in Shadowmoon Valley. Upon completing the Cipher quest, you will receive (immediately) a letter in the mail from [[Khadgar]], asking you to travel to [[Shattrath City]] to speak to him.\r\n*The Tempest Key: Khadgar instructs you to speak to [[A'dal]], who sends you on a series of trials.\r\n**Trial of the Naaru: Mercy: A'dal sends you to [[the Shattered Halls]] of [[Hellfire Citadel]] to retrieve the Unused Axe of the Executioner. You must kill all three of the bosses in the Halls. This MUST be done on [[Heroic]] difficulty.\r\n**Trial of the Naaru: Strength: This requires two instance runs, both on Heroic: You must kill [[Warlord Kalithresh]] in [[the Steamvault]] of [[Coilfang Reservoir]] and retrieve Kalithresh's Trident, then travel to the [[Shadow Labyrinth]] in [[Auchindoun]], destroy [[Murmur]], and take Murmur's Essence.\r\n**Trial of the Naaru: Tenacity: Enter [[the Arcatraz]] - a satellite of [[Tempest Keep]] - and rescue [[Millhouse Manastorm]]. This must be done on Heroic difficulty.\r\n**Trial of the Naaru: Magtheridon: Finally, you must enter [[Magtheridon's Lair]] and slay [[Magtheridon]], a 25-man raid boss.\r\nUpon completing all four quests, A'dal will grant you the Tempest Key (along with Phoenix-fire Band) and you will be allowed to enter [[The Eye]], Kael'thas' sanctum, for the final confrontation with the \"Sun King\".\r\n==Quest progression==\r\nEither read the letter from [[Khadgar]] or speak to him in [[Shattrath City]].\r\n==Keys required for quests==\r\nThe following Heroic entry keys are required, and you must be with a certain faction to obtain them:\r\n*[[Flamewrought Key]] ([[Honor Hold]]/[[Thrallmar]]): Unlocks [[Heroic]] mode in [[Hellfire Citadel]]. \r\n*[[Reservoir Key]] ([[Cenarion Expedition]]): Unlocks Heroic mode in [[Coilfang Reservoir]].\r\n*[[Auchenai Key]] ([[Lower City]]): Unlocks Heroic mode in [[Auchindoun]]. \r\n*[[Warpforged Key]] ([[Sha'tar]]): Unlocks Heroic mode in [[Tempest Keep]].\r\n*[[The Shattered Halls]], [[Shadow Labyrinth]], and [[The Arcatraz]] also have their own entry keys; however, only one person in the group with the key or a lockpicker is required to get past them.\r\n==Title: Champion of the Naaru==\r\nIn [[Patch 2.3.0]], players who complete (or have completed) this quest chain as well as The Cudgel of Kar'desh will be given the title \"Champion of the Naaru\" . Players who complete (or have completed) this quest but still do not obtain the title are advised to talk to A'dal once more and then reload the client.",},
			["The Tempest Rift"] = { content = "#redirect [[Tempest Rift]]", redirect = "Tempest Rift",},
			["The Temple Gardens"] = { content = "#REDIRECT [[Temple Gardens]]", redirect = "Temple Gardens",},
			["The Temple of Atal'Hakkar"] = { content = "#REDIRECT [[Temple of Atal'Hakkar]]", redirect = "Temple of Atal'Hakkar",},
			["The Temple of Karabor"] = { content = "#REDIRECT [[Black_Temple]]", redirect = "Black_Temple",},
			["The Temple of the Moon"] = { content = "#REDIRECT [[Temple of the Moon]]", redirect = "Temple of the Moon",},
			["The Third Troll Legend"] = { content = "The Third Troll Legend is a quest item only lootable by players on the quest Kurzen's Mystery.\r\n==Source==\r\nThe Third Troll Legend is looted from the large stone tablet called [[Fall of Gurubashi]], located in the south western part of the [[Ruins of Zul'Kunda]]. It is in the most south western \"room\" (meaning walls but no roof in these ruins), in the north western corner of the room. NOTE: The tablet is in the main compound on the plateau, NOT down on the beach. Coordinates: (22,12)\r\n==As a Quest Objective==\r\n* Kurzen's Mystery - from [[Brother Nimetz]] at the [[Rebel Camp]] in [[Stranglethorn Vale]]\r\n:Required:\r\n:* The First Troll Legend\r\n:* The Second Troll Legend\r\n:* The Third Troll Legend\r\n:* The Fourth Troll Legend",},
			["The Thundercaller"] = { content = "'''The ''Thundercaller''''' is a zeppelin with a goblin crew and Forsaken guards that runs between a tower outside [[Orgrimmar]] in [[Durotar]] and the tower outside of [[Brill]] in [[Tirisfal Glades]].\r\nThe crew is constantly making repairs to the craft. According to them, under the command of Sky-Captain Cloudkicker and the control of Navigator Fairweather the zeppelin has crashed repeatedly in a wide array of [[zones]]. The [[Forsaken|undead]] guards on the Thundercaller simply say \"don't ask\" when a player speaks to them, possibly hinting that they would still be alive in the traditional sense if they had not signed on with Cloudkicker.\r\nThe crew will return in the upcoming expansion [[Wrath of the Lich King]].\r\n==Crew==\r\n* [[Sky-Captain Cloudkicker]]\r\n* [[Chief Officer Coppernut]]\r\n* [[Navigator Fairweather]]\r\n* [[Deathguard Fowles]]\r\n* [[Deathguard Lawson]]\r\n* [[Crewman Quickfix]]\r\n* [[Crewman Rusthammer]]\r\n* [[Crewman Sparkfly]]\r\n* [[Snack-O-Matic IV]]\r\n* [[Vendo-O-Tron D-Luxe]]",},
			["The Tidus Stair"] = { content = "A half-days travel south of [[Ratchet]], near the small fishing village of [[Tidus]], lies an interesting rock formation on the coast of [[the Barrens]]. '''The Tidus Stairs''' has the form of several terraces forming a giant set of ancient stone stairs overlooking part of the [[Merchant Coast]]. The steps extend from the beach and vanish beneath the waves. Local legend says that they decend to a [[Kaldorei]] city that fell into the ocean after the collapse of the [[Well of Eternity]]. Adults and children of the village dive down as deep as they can manage, but thus far none have found anything but a continuing staircase.\r\nOn the Stairs, a pair of female [[tauren]] [[druid|druids]] of the small village of Tidus, sit and fish and converse with Water Elementals.\r\nIt is unknown who, or what, was Tidus - could be a local water diety, or a water elemental (name derived from the word \"Tide\").",},
			["The TOC Format"] = { content = "#REDIRECT [[TOC format]]", redirect = "TOC format",},
			["The Tomb of Sargeras (WC2 Orc)"] = { content = "'''The [[Tomb of Sargeras]]''' was a conflict that took place during the [[Second War]], though it was not a battle between the [[Alliance of Lordaeron]] and the [[Horde (pre-Thrall)|Horde]], but a battle within the Horde itself.\r\n==Briefing==\r\n''The [[Northlands]] have fallen, and now only the western regions of [[Lordaeron]] stand defiant before the ultimate supremacy of the [[History of the Horde|Horde]]. As the [[Orc]] [[clan]]s prepare for their final, massive campaign against the weakening [[Alliance of Lordaeron|Alliance]], the [[War Chief]] sends you ill tidings. . . [[Gul'dan]] and his [[Stormreaver clan]] have betrayed the Horde and coerced the [[Twilight's Hammer clan]] to set sail and search for an [[Tomb of Sargeras|ancient tomb]] said to be buried beneath the waves. An infiltrator under the direction of [[Orgrim Doomhammer|Doomhammer]] reports that Gul'dan has indeed raised volcanic islands from the ocean floor and thus has opened a hidden vault. While it is unknown what the great [[Warlock]] has released from this tomb, the War Chief has issued this command - Destroy the renegade clans and return with the head of Gul'dan.''\r\n===Objective===\r\n* ''Destroy the [[Stormreaver clan]]\r\n* ''Destroy the [[Twilight's Hammer clan]]\r\n==Background==\r\nThe battle was the result of the treachery of the [[Warlock]] [[Gul'dan]], [[Chieftain]] of the [[Stormreaver Clan]] and former leader of the then-defunct [[Shadow Council]]. Having discovered the location of the legendary [[Tomb of Sargeras]], which was the reason for him to create the [[Dark Portal]] in the first place, Gul'dan assembled the forces loyal to him, both the [[Stormreaver Clan]] and the [[Twilight's Hammer Clan]] which was leaded by his apprentice [[Cho'gall]] the [[Ogre-Mage]], and led them towards the [[Great Sea]]. Gul'dan cared little for the result of the [[Second War]] and sought only to find the tomb and take the power of Sargeras for himself.\r\nSome accounts tell that Orgrim Doomhammer had to postpone the assault on [[Lordaeron]]'s [[Capital City]] however he was in the middle of the [[The Fall of Lordaeron|battle]] when Gul'dan and his followers went to the Tomb of Sargeras, with the massive loss of forces the warchief was forced to withdraw his troops from Capital City to deal with the traitors, he sent a large contingent of the [[Blackrock]] troops alongside with [[Rend]], [[Maim]] and their [[Black Tooth Grin clan]] to slaughter Gul'dan and everyone of his followers.\r\nAfter arriving to the sumberged Tomb of Sargeras; Gul'dan, Cho'gall, some [[necromancer]]s, [[warlock]]s and [[Ogre-magi]]s started raising the Tomb from the floor of the ocean. Meanwhile, [[Torgus]] had already reported to Orgrim about Gul'dan treachery and Rend was going directly to battle Gul'dan. After hours of conjures Gul'dan and his followers succeded in raise the [[Broken Isles]], however after a few moments Rend Blackhand and his Black Tooth Grin warrior saw them and prepared for the battle.\r\nCho'gall detected the ships of Doomhammer's troops before they arrived the isles. The Ogre Mage and most of the troops of both clans stood there to fight, they promised to Gul'dan to make everything possible to stop the Horde, meanwhile Gul'dan with some shamans and warlocks went inside of the Tomb of Sargeras.\r\n==The Battle==\r\nFirst Urok's unit had to establish a city on the largest of the islands to the east and north. For this purpose, they sent their warships with a flier to clear the way. Two enemy ships and a submersible had to be sunk first, then a tower; finally, the inland catapult was drawn to shore with a fast destroyer and dissasembled. While the warships waited, the transports were loaded with all but sappers and peons to make a landing; soon the island was theirs. While the existing structures were removed, the transports went back for the rest of the units and brought them safely to shore. From that point it was a matter of building a city from scratch, starting with a hall as close to the mine as possible without being too close to shor. With the threat of enemy juggernaughts coming soon, all units were moved as far inland as possible and the ships were sent to anchor at the southern tip of the island.\r\nAs soon as a barracks, lumber mill, and a blacksmith had been built, they concentrated on producing catapults. These they used to sink any enemy ships foolish enough to wander too close to the shore by directing all of them to attack at once, then moving them safely back inland. Cannon towers helped somewhat, but their lack of mobility got them destroyed almost as fast as they could be built. Once they had a fair-sized group of catapults to fend off shps, construction of the shipyard and accompanying structures began on the southeast side of the island as far from enemy eyes as possible. To carry out their plan of invasion, they would need only two juggernaughts and three transports to make a landing on the main island. They loaded them with five trolls to give them a chance against flying daemons, a single worker, six ogres, and six catapults.\r\nThe flotilla was escorted by a zeppelin to spot enemy submersibles. It sailed west to the edge of the area before turning north and quietly passing the main island. Then it headed east to find a good landing spot south of a small barren island. The juggernaughts were sent in first to clear the shore of a tower and catapult before the troops were unloaded behind a small stand of trees. They were careful to unload the ogres first, with catapults behind, and trolls on the other side, since the enemies would come to them once the catapults started on the enemy barracks nearby. When things quieted down a bit, Urok's forces erected their own barracks and began pouring troops and catapults through it to slowly take over the island.\r\nThe battle continued, both sides suffered heavy casualities but the difference were the numbers, the Stormreaver clan was the smallest of all and the Black Tooth Grin clan was one of the largest clans within the Horde, Gul'dan forces were outnumbered and they knew it, however they were fanatically loyal and refused to surrender, they fought until the last orc, they took many of Doomhammer's warriors with them. Urok claims they later finished Gul'dan and Cho'gall by blowing a hole through the rock with sappers, and claimed both of their heads as a clear signal to all who would oppose the Horde, however the truth is that they could only kill Cho'gall, the massive two-headed ogre cut one of the arms of the strongest Black Tooth Grin warrior as he fell, but finally the beach was full of corpses with only Doomhammer's forces standing.\r\nEven though Cho'gall was killed, Gul'dan continued his journey inside the Tomb. He brought some shamans, necromancers, warlocks and ogre-magis with him, he frightened his warriors by killing [[Urluk Cloud-killer]] and they started to search for the powers. They found a hidden vault, protected against all Azerothian races by [[Aegwynn]], but Gul'dan was an orc of [[Draenor]] and opened it. He looked for the [[Eye of Sargeras]] but only found crazed [[daemon]]s that ambushed him, he wrote his story in runes with his own blood, he didn't found the power to become a living god, but death in the hands and claws of the mad demons locked within the halls of Sargeras's final resting place.\r\nRend Blackhand commanded the troops to made an attack against Gul'dan but when they found the tomb, the [[demon]]s attacked them, many were paralized by those horrible beast but others fought and they could win the battle He promised to any other clans that questioned his commander's military prowess the same destiny of Gul'dan.\r\nOnly a few Warlocks and Necrolytes of the Stormreaver Clan, such as [[Drak'thul]], survived.\r\n==Aftermath==\r\n* The Horde was left divided and weakened, thus preparing the way for the victory of the Alliance over the Horde, however now they hadn't to worry about traitors.\r\n* Gul'dan was killed, though his [[Skull of Gul'dan|Skull]] retained all the massive power once held by the Warlock, thus becoming an amulet of unparalleled power. The Skull was apparently taken by one of the surviving Blackrock warriors and found its way to [[Draenor]] and to the hands of a Captain of the [[Bonechewer Clan]], who ignored the power of the Skull and wore it simply as a sign of his power.\r\n* The corpses of the fallen Horde warriors were raised by the magics emanating from the Tomb. The undead skeletal orcs began to recreate the battle in which they fell; until [[Maiev Shadowsong]] came and wiped out the entire host of undead warriors.\r\n* Drak'thul becomes a hermit.\r\n* The few surviving Warlocks, Necrolytes scatter and, some hide in the [[Broken Isles]] while others reach the shores of [[Kalimdor]]. It is possible some of these survivors joined the new Shadow Council.\r\n* The few survivors from the Twilight's Hammer clan started serving the [[Old Gods]] and recruiting members of any race.",},
			["The Tower of Althalaxx (4)"] = { content = "This quest is part of quest chain .\r\n==Objectives==\r\nCollect a Glowing Soul Gem and return it to [[Delgren the Purifier]]\r\nat [[Maestra's Post]].\r\n*Glowing Soul Gem\r\n==Quest text==\r\n[[Balthule Shadowstrike|Balthule's]] letter is dire. This\r\n[[Cult of the Dark Strand]] is a thorn in my side that must be removed. I\r\nhave been dealing with some of the Dark Strand scum northeast of here\r\nat [[Ordil'Aran]]. One of their number possesses a soul gem that I believe\r\nholds the secret to the cult's power.\r\nBring it to me, and I will be able to decipher the secrets held within.\r\n==Progress==\r\nHave you acquired that soul gem?\r\n==Completion==\r\nHmm, some dark magic enchants this soulstone. Let's see what's trapped\r\ninside, shall we?\r\n==Cut Scene on completion: a freed soul==\r\n<font color=\"#FFFF9F\">Delgren the Purifier says: A simple enough task to break this soulstone!</font>\r\n<font color=orange>Glowing Soulgem bursts open!</font>\r\n''The ghost of Sargath appears before Delgren''\r\n<font color=\"#FFFF9F\">Sargath says: In the throes of the Sundering, Ameth'Aran was at the whim of the terror that gripped the land. There was little hope for survival.\r\nSargath says: Athrikus came to us. He told us that he could save us from harm. He cast a spell upon us to protect us from harm.\r\nSargath says: When the shaking stopped, his true motives were revealed. We were trapped, and he was slowly draining our powers.\r\nSargath says: There were hundreds imprisoned by his spell. Now only a few remain in their prisons. He would speak to us sometimes.\r\nSargath says: He worried that his power weakened, that soon even we last of his precious soulgems would fade and die.\r\nDelgren the Purifier says: Then we must put an end to Athrikus Narassin. Tell me, spirit, where might we find the other soulgems, to undo his magic?\r\nSargath says: His lieutenant, Ilkrud Magthrull possesses a tome which might indicate the location of the remaining soulgems.</font>\r\n<font color=\"orange\">Sargath fades into the mist...</font>\r\n==Rewards==\r\nUpon completion of this quest you will gain:\r\n*1650 [[XP]] (or 10 silver 20 copper at level 70)\r\n*250 [[reputation]] with [[Darnassus]]\r\n==Notes==\r\nThe soul gem drops only rarely. You may need to slay every Dark Strand\r\nAdept, Cultist, Excavator, Enforcer, or Assassin at [[Ordil'Aran]] several\r\ntimes in order to acquire it. (All of those varieties of Dark Strand follower\r\ndrop it. They just drop it rarely.)",},
			["The Tower of Althalaxx quest chain"] = { content = "This series of quests leads the character to discover the [[Cult of the Dark Strand]] and its leader, [[Athrikus Narassin]].\r\n==The Tower of Althalaxx==\r\n* '''The Tower of Althalaxx'''\r\nIn [[Auberdine]], [[Sentinel Elissa Starbreeze]] asks you to travel north\r\nto the [[Tower of Althalaxx]], to check up on [[Balthule Shadowstrike]],\r\nan agent she sent to check out the tower. Balthule is late checking in,\r\nand Elissa is concerned that he may have run afoul of something.\r\n* '''The Tower of Althalaxx (2)'''\r\nBalthule found something, alright, and it doesn't look good.\r\nIt seems that a cult of warlocks has moved into the tower. He doesn't know\r\nanything about them, really, but ... warlocks... cult... can't be good.\r\nHe has had some scraps of parchment fall into his hands, but needs more\r\nin order to assess the threat they pose. And he asks you to secure them for\r\nhim.\r\nYou relieve some of the fanatics of their parchments and return to Balthule,\r\nwho is able to put together something more about them. Specifically, they\r\nare part of the [[Cult of the Dark Strand]]. ... About which Balthule has\r\nno real information. However, he knows someone who might:\r\n[[Delgren the Purifier]].\r\n* '''The Tower of Althalaxx (3)'''\r\nIt turns out that Balthule is actually an agent of Delgren,\r\na [[human]] [[paladin]] who is assisting the [[Night Elves]] in destroying\r\ndemonic and undead forces. (Elissa was just 'borrowing' him...)\r\nBalthule asks you to carry a letter to Delgren, outlining the situation\r\nat the tower. You find that it's a long, long run, from the \r\n[[Tower of Althalaxx]] to [[Maestra's Post]] in [[Ashenvale Forest]].\r\n* '''The Tower of Althalaxx (4)'''\r\nDelgren takes the threat of the Dark Strand cultists seriously, as he\r\nhas already been battling them near [[Ordil'Aran]]. It seems that somewhere\r\namong the cultists is a [[Glowing Soul Gem|soul gem]] that he believes holds\r\nthe secret to the cult's power. You volunteer to go retrieve it for him.\r\nYou kill a LOT of cultists in the process of finding the gem, but find it\r\nyou do. Soul gems, as it sounds like, contain a trapped soul. Releasing\r\nthe soul is as easy as shattering the gem.\r\n* '''The Tower of Althalaxx (5)'''\r\nThe freed spirit gives you the name ''[[Ilkrud Magthrull]]''. Delgren knows\r\nthis name. He's a warlock in south-western Ashenvale, at [[Fire Scar Shrine]].\r\nHe's up to his little eyeballs in this Dark Strand cult. He's got to go.\r\nAnd you're just the person to do it.\r\nDespite his succubus, despite his voidwalkers, all his necromantic powers\r\navail him naught. You return to Delgren victorious, with his\r\n[[Ilkrud Magthrull's Tome|tome]] in hand.\r\n* '''The Tower of Althalaxx (6)'''\r\nDelgren reads through the tome and relates the results. It seems that\r\n[[Athrikus Narassin]] still has two soul gems, one in [[Night Run]], and\r\none in [[Satyrnaar]], both under the control of Satyrs. Two more souls\r\nto free.\r\nThose things one values, one protects. The Satyrs defend the soul gems\r\nquite stoutly, but you are still able to free the souls and thus weaken\r\nthe chief of the Dark Strand cultists, and do other Good in the process.\r\n* '''The Tower of Althalaxx (7)'''\r\nUpon returning to Delgren, he declares that it is time to confront\r\n[[Athrikus Narassin|Athrikus]] himself. But first, he says, you should\r\ntalk to [[Balthule Shadowstrike|Balthule]] and see if there have been any\r\ndevelopments.\r\nYou do, and you find that yes, your work has been ... noticed. Out of the\r\nblue, as it were, there was a blinding flash from the top of the tower,\r\nfollowed by a lot of lightning and screams.\r\nGood work, that.\r\n* '''The Tower of Althalaxx (8)'''\r\nYou relate what you've been up to since you last talked to him, and Balthule\r\nagrees that Athrikus will never be weaker. He cautions you, though, that\r\nthere are many warlocks surrounding him, more powerful than those you've\r\nfaced before.\r\nAnd he was right. You fight (or perhaps sneak) your way to the top\r\nof the tower and find a veritable cloud of warlocks guarding Athrikus.\r\nThe fighting is savage, but you prevail! For proof, you use the time\r\nhonored method of returning with the head of your foe.\r\n* '''The Tower of Althalaxx (9)'''\r\nBalthule directs you to return to [[Delgren the Purifier]] and tell him\r\nof your deeds: [[Athrikus Narassin]] lies dead, and the\r\n[[Cult of the Dark Strand]] is scattered!\r\nDelgren tells you he senses that you are destined for greatness, and that\r\nyou will right many wrongs plaguing the lands. He offers you a gift, as\r\nwell, in thanks for your courageous deeds.\r\n==Rewards==\r\n* 1750 [[Darnassus]] [[Reputation]], and 1/4 of that for all other alliance factions.\r\nFor bringing Ilkrud Magthrull's Tome to Delgren, you get your choice of\r\nFrom the final quest, your choice of",},
			["The Tower of Arathor"] = { content = "#REDIRECT [[Tower of Arathor]]", redirect = "Tower of Arathor",},
			["The Trade District"] = { content = "#REDIRECT [[Trade District]]", redirect = "Trade District",},
			["The Trade Quarter"] = { content = "#redirect [[Trade Quarter]]", redirect = "Trade Quarter",},
			["The Troll Wars"] = { content = "#REDIRECT [[Troll Wars]]", redirect = "Troll Wars",},
			["The True Threat"] = { content = "Short story in the [[World of Warcraft Official Strategy Guide]].\r\nAn undead mage and his party of Forsaken are attacked by human invaders of the Alliance on the field of battle. With the help of his warlock ally [[Ishnaron]], they defend their warriors. While Ishnaron distracts the humans with a void walker, the mage attacked with a cast of blizzard. The warriors were able to then take up full attack on the humans, while the warlock bombarded them with storms of fire. The mage laughed for the victory at hand, hoping that humans would perhaps learn not to underestimate the Forsaken.",},
			["The Truth Comes Crashing Down"] = { content = "==Objectives==\r\nTake the [[Head of Balnazzar]] to [[Duke Nicholas Zverenhoff]] in the [[Eastern Plaguelands]].\r\n* Head of Balnazzar (Provided)\r\n==Description==\r\nYou try and gather your thoughts as the dust settles across the chamber. You go over the events that just transpired and still cannot comprehend the gravity of the situation.\r\nThe [[Saidan Dathrohan|Grand Crusader]] of the [[Scarlet Crusade]] a demon? And not just any demon but brother to [[Varimathras]], arch lord of the [[Undercity]]?\r\nYou carefully stow the severed head of the [[dreadlord]] into your pack. Surely, none would believe the tale you would tell without proof.\r\nDuke Nicholas Zverenhoff must be told at once! \r\n==Progress==\r\nWhat have you got there, <name>?\r\n==Completion==\r\nWhat will this mean to the Crusade? Could it be possible that they have been under the control of this demon? Unwittingly serving as the pawns to a greater evil?\r\n==Notes==\r\nYou must complete the quest The Archivist before being able to loot the head.",},
			["The Tundrid Hills"] = { content = "#REDIRECT [[Tundrid Hills]]", redirect = "Tundrid Hills",},
			["The Twilight Ridge"] = { content = "#redirect [[Twilight Ridge]]", redirect = "Twilight Ridge",},
			["The Twin Colossals"] = { content = "#REDIRECT [[Twin Colossals]]", redirect = "Twin Colossals",},
			["The Twin Empires"] = { content = "'''The Twin Empires''' is an in-game [[book]].\r\nFound at:\r\n*[[Booty Bay]] in [[Stranglethorn Vale]] - building near fishing vendor\r\n*[[Gadgetzan]] in [[Tanaris]]",},
			["The Underbog"] = { content = "#redirect [[Underbog]]", redirect = "Underbog",},
			["The Undercity"] = { content = "#REDIRECT [[Undercity]]", redirect = "Undercity",},
			["The Undercroft"] = { content = "#REDIRECT [[Undercroft]]", redirect = "Undercroft",},
			["The Unforgiven"] = { content = "'''The Unforgiven''' is a level 57 [[elite]] [[wraith]] in [[Stratholme]]. Not much is known about The Unforgiven, but some have mentioned his [[Mask of the Unforgiven|mask]] is a truly powerful item. \r\n==Strategy==\r\nHe usually isn't alone, so be prepared to fight. It will spawn when you walk past an archway after you take right turn after the rat gate trap, near [[Hearthsinger Forresten]]. The Unforgiven spawn is scripted, so have your party members rest before going any closer to the archway. Some non-elites spawn too, but a [[mage]] can take care of them easily. The Unforgiven casts [[Frost Nova]] now and then. Very easy fight.",},
			["The Unstoppable Force"] = { content = "''\"What happens when . . . ?\"'' \r\n'''The Unstoppable Force''' is an epic two handed mace obtained from the [[Stormpike Guard]] faction, or the [[Frostwolf Clan]] faction. It is also the counter to The Immovable Object.\r\n[[World of Warcraft: The Burning Crusade|BC]] adds a gray level 64 mace, called The Stoppable Force, clearly in reference to this epic weapon.\r\n==Notes==\r\n*The cost is - 7000 [[Honor]] - 25x [[Alterac Valley Mark of Honor]]\r\n*The mace itself is shaped like a pig's head.\r\n*When The Unstoppable Force was originally released, it had a knockback proc instead of the stun. This was removed shortly after, in keeping with Blizzard's unwillingness to give players knockback.\r\n*Early on in WoW, a member of the WoW playing community asked a [[CM]] what would happen if the The Unstoppable Force was blocked by The Immovable Object. After a brief moment's speculation, the [[CM]] posted the response \"Chuck Norris Dies\".",},
			["The Unyielding"] = { content = "The Unyielding is a [[Cloth armor|cloth]] [[Non-class sets|set]] used by [[Damage per second|DPS]] [[Caster|casters]] for [[Player vs Player|PvP]] combat due to its [[resilience]] bonuses and reduction to [[melee]] [[damage]]. Its small set size, requiring only waist and wrist [[Equipment slot|equipment slots]], means that it can be easily worn along with other PvP [[equipment]].",},
			["The Uplands"] = { content = "#REDIRECT [[Uplands]]", redirect = "Uplands",},
			["The Valley of Heroes"] = { content = "#REDIRECT [[Valley of Heroes]]", redirect = "Valley of Heroes",},
			["The Vault"] = { content = "#REDIRECT [[Vault (Stormwind City)]]", redirect = "Vault (Stormwind City)",},
			["The Vault of Lights"] = { content = "#REDIRECT [[Vault of Lights]]", redirect = "Vault of Lights",},
			["The Vector Coil"] = { content = "#REDIRECT [[Vector Coil]]", redirect = "Vector Coil",},
			["The Veiled Blade"] = { content = "#redirect [[Veiled Blade]]", redirect = "Veiled Blade",},
			["The Veiled Sea"] = { content = "#REDIRECT [[Veiled Sea]]", redirect = "Veiled Sea",},
			["The Venture Co. Mine"] = { content = "#REDIRECT [[Venture Co. Mine]]", redirect = "Venture Co. Mine",},
			["The Vials of Eternity"] = { content = "==Objectives==\r\nSoridormi at [[Caverns of Time]] wants you to retrieve [[Vashj's Vial Remnant]] from [[Lady Vashj]] at [[Coilfang Reservoir]] and [[Kael's Vial Remnant]] from [[Kael'thas Sunstrider]] at [[Tempest Keep]]. \r\n* Kael's Vial Remnant\r\n* Vashj's Vial Remnant\r\n== Description==\r\nSeven vials were drawn from the Well of Eternity by Illidan. He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created. For years the rest were believed lost.\r\nWith the opening of the [[Dark Portal]], we've come to know that he gave one each to his lieutenants Kael'thas and Vashj. Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient. The outcome of the Battle of Mount Hyjal must be preserved. \r\n== Reward==\r\nYou will receive:13 gold 20 silver copper \r\n The Scale of the Sands +3000 Reputation\r\n== Progress==\r\nI've asked the impossible of you, yet I expect you to succeed. Much depends on it. \r\n== Completion==\r\nThe power contained even in this small amount of water from the Well of Eternity is incredible.\r\nI can see clearly into every moment in time linked to Hyjal... the creation of the second Well of Eternity, Illidan's imprisonment, the enchantment of the World Tree and... yes! The Battle of Mount Hyjal.\r\nWe must make haste, the timeline is not safe.",},
			["The Vice"] = { content = "#redirect [[Vice]]", redirect = "Vice",},
			["The Vile Reef"] = { content = "#REDIRECT [[Vile Reef]]", redirect = "Vile Reef",},
			["The Vile Reef (quest)"] = { content = "'''The Vile Reef''' is a [[Horde]]-only quest in [[Stranglethorn Vale]] in which players must dive off the coast near [[Grom'gol Base Camp]] to collect a piece of an ancient troll tablet, which the trolls of [[Orgrimmar]] wish to have for remembrance.\r\n====How to Get This Quest====\r\nAt [[Grom'gol Base Camp]] in [[Stranglethorn Vale]], talk to [[Kin'weelay]] the troll.\r\n====Other Quests in this Area====\r\nThe [[Vile Reef]], where this quest takes place, is the location of several quests. It is a good idea to do all of these quests at once. As of patch [[2.3]], area is no longer elite.\r\n*Encrusted Tail Fins - from [[Wizzle Brassbolts]] at the [[Mirage Raceway]] in [[Thousand Needles]]\r\n*Pearl Diving - from [[Rigglefuzz]] in the [[Valley of Fangs]] in the [[Badlands]]\r\n*The Vile Reef - from [[Kin'weelay]] at [[Grom'Gol]] in [[Stranglethorn Vale]]\r\n==Objectives==\r\nBring a Tablet Shard to [[Kin'weelay]] at the [[Grom'gol Base Camp]].\r\nRequired:\r\n* Tablet Shard\r\n==Details==\r\nIt is possible to do this quest without having to fight the [[murloc]]s swimming around the [[Vile Reef]], if you are careful. However, since many players will have Encrusted Tail Fins, which requires killing the [[murloc]]s, they may want to kill them anyway. The Tablet Shard can be looted by right clicking a tablet near a blue glowing area on the ocean floor. The tablet is called [[Gri'lek the Wanderer]]. \r\nCoordinates for the tablet [[Gri'lek the Wanderer]] are: (24,22)\r\nOnce you have the Tablet Shard, return to [[Grom'gol Base Camp]] and talk to [[Kin'weelay]] to complete the quest.\r\n==Description==\r\n''Long ago, a great shudder of the earth sunk an old troll city beneath the waters of the [[Savage Coast]] to the northwest. We call that place the [[Vile Reef]], for [[murloc]]s now reside in the ruins of the city, attacking any who draw close.\r\n''There is an old tablet among those ruins that tells the ancient tale of [[Gri'lek]], a hero of troll legends. The tale is sacred to the [[Darkspear]] tribe, and although the tablet is too large to move, I want a shard of it to enshrine in our new home in [[Orgrimmar]].\r\n==Progress==\r\n''I await the [[Tablet Shard]], <name>.\r\n==Completion==\r\n''This is good. When I return to [[Orgrimmar]] I will place this shard in a sacred place. It will remind us of the might and honor of [[Gri'lek]].\r\n''Thank you, <name>. Your deeds mark a growing friendship with the Darkspear tribe.",},
			["The Violet Eye"] = { content = "#REDIRECT [[Violet Eye]]", redirect = "Violet Eye",},
			["The Violet Hold"] = { content = "#redirect [[Violet Hold]]", redirect = "Violet Hold",},
			["The Violet Tower"] = { content = "#redirect [[Violet Tower]]", redirect = "Violet Tower",},
			["The Vortex Fields"] = { content = "#redirect [[Vortex Fields]]", redirect = "Vortex Fields",},
			["The Wailing Caverns"] = { content = "#REDIRECT [[Wailing Caverns]]", redirect = "Wailing Caverns",},
			["The Wailing Ziggurat"] = { content = "#REDIRECT [[Wailing Ziggurat]]", redirect = "Wailing Ziggurat",},
			["The Waking World and the Well of Eternity"] = { content = "'''\"The Waking World and the Well of Eternity\"''' is a section of the [[History of Warcraft]], Chapter I. It is also found as an [[in-game book]] in the [[Stormwind Keep]] [[Royal Library]] under the alternate title, '''\"The Kaldorei and the Well of Eternity\"'''.\r\nAlso found at:\r\n* [[Deepwater Tavern]] in [[Wetlands]].\r\nTimeline: \r\n* ← Previous book: [[Charge of the Dragonflights]]\r\n* → Next book: [[The War of the Ancients]] \r\n==See also==\r\n* [[Well of Eternity]]\r\n* [[Kaldorei]]\r\n* [[Azshara]]\r\n* [[Highborne]]\r\n* [[Malfurion Stormrage]]",},
			["The Warp Fields"] = { content = "#REDIRECT [[Warp Fields]]", redirect = "Warp Fields",},
			["The Warp Piston"] = { content = "#REDIRECT [[Warp Piston]]", redirect = "Warp Piston",},
			["The War of the Ancients"] = { content = "''For the novels by [[Richard A. Knaak]], see [[War of the Ancients Trilogy]]. For a general article on the event, see [[War of the Ancients (WC3 account)]] and [[War of the Ancients (novel account)]].\r\n'''\"The War of the Ancients\"''' is a section of the [[History of Warcraft]], Chapter I.\r\nFound at:\r\n* The Athenaeum of [[The Scarlet Monastery]] in [[Tirisfal Glades]]\r\n* [[Darnassus]] at [[Craftsmen's Terrace]] \r\n* An inn at [[The Park]] in [[Stormwind City]]\r\nTimeline: \r\n* ← Previous book: [[The Waking World and the Well of Eternity]]\r\n* → Next book: [[The Sundering of the World]] \r\n==See also==\r\n* [[Burning Legion]]\r\n* [[Azshara]]\r\n* [[Malfurion Stormrage]]\r\n* [[Illidan]]\r\n* [[Tyrande]]",},
			["The Weathered Nook"] = { content = "#REDIRECT [[Weathered Nook]]", redirect = "Weathered Nook",},
			["The Weeping Cave"] = { content = "#REDIRECT [[Weeping Cave]]", redirect = "Weeping Cave",},
			["The Well of Eternity"] = { content = "'''''The Well of Eternity''''' is the first book of the [[War of the Ancients Trilogy]] [[novels]].\r\n==Description==\r\nMany months have passed since the cataclysmic [[Battle of Mount Hyjal]], where the demonic [[Burning Legion]] was banished from [[Azeroth]] forever. But now, a mysterious energy rift within the mountains of [[Kalimdor]] propels three former warriors into the distant past -- a time long before orcs, humans or even high elves roamed the land. A time when the [[Dark titan|Dark Titan]] [[Sargeras]], and his [[demon]] pawns persuaded [[Queen Azshara]] and her [[Highborne]] to cleanse Azeroth of its lesser races. A time when the [[Dragon Aspects]] were at the height of their power -- unaware that [[Deathwing|one of their own]] would soon usher in an age of darkness that would engulf the world of...\r\n'''WARCRAFT'''\r\nIn the first chapter of this epic trilogy, the outcome of the historic [[War of the Ancients]] is forever altered by the arrival of three time-lost heroes: [[Krasus]], the [[dragon]] [[mage]] whose great power and memories of the ancient conflict have inexplicably diminished; the [[human]] wizard [[Rhonin]], whose thoughts are divided between his family and the seductive source of his now-growing power; and [[Broxigar]], a weathered [[orc]] veteran who seeks a glorious death in combat. But unless these unlikely allies can convince the [[demigod]], [[Cenarius]], and the untrusting [[Night elf|Night Elves]] of their queen's treachery, the Burning Legion's gateway into Azeroth will open anew. And this time -- the struggles of the past may well spill over into the future...\r\n==Locations==\r\n*[[Chamber of Aspects]]\r\n*[[Dalaran]]\r\n*[[Emerald Dream]]\r\n*[[Galhara]]\r\n*[[Grim Batol]]\r\n*[[Khaz Modan]]\r\n**[[Tol Barad]]\r\n*[[Lordaeron]]\r\n**[[Andorhal]]\r\n*[[Maelstrom]]\r\n*[[Quel'Thalas]]\r\n**[[Silvermoon City]]\r\n*[[Stonetalon Mountains]]\r\n*[[Suramar]]\r\n**[[Black Rook Hold]]\r\n**[[Temple of Elune]]\r\n***[[Chamber of the Moon]]\r\n*[[Zin-Azshari]]\r\n**[[Azshara's Palace]]\r\n**[[Well of Eternity]]\r\n==Other==\r\n*[[View globe]]\r\n==See also==\r\n*For more information, please see: [[War of the Ancients (novel account)]] and [[War of the Ancients (WC3 account)]].",},
			["The Will Of The Lich King"] = { content = "==Objectives==\r\nReturn to [[Death's Breach]] and report to [[Prince Valanar]].\r\n==Description==\r\nIt is the will of the [[Lich King]] that drives us onward, <name>. None are more aware of this than [[death knight]]s. Our very existence is intrinsically tied to his very consciousness. Surely you have heard him speak to you - invading your thoughts...\r\nCan you hear him now? Perhaps it is too early for you.\r\n<[[Highlord Darion Mograine|Mograine]] closes his eyes and nods to an unknown host.>\r\nYes, my lord. It will be done.\r\n<Name>, you are to return to Death's Breach and report to Prince Valanar. The Lich King commands it!\r\n==Completion==\r\n[[Havenshire]] is ours! A thousand corpses litter the ground, patiently awaiting rebirth. We now strike at our enemy with the awakened strength of the [[Scourge]]!\r\nThe [[ghoul]]s have already begun their assault upon [[New Avalon]]. Our forces have moved in behind them and taken the [[Crypt of Remembrance]].\r\n==Notes==\r\nCompleting \"Victory at Death's Breach!\" has advanced the instance to stage 2, with a reorganization of NPCs both at Death's Breach and Havenshire.",},
			["The World Tree and the Emerald Dream"] = { content = "'''\"The World Tree and the Emerald Dream\"''' is a section of the [[History of Warcraft]], Chapter I.\r\nFound at:\r\n* [[The Scarlet Monastery]] in [[Tirisfal Glades]].\r\nTimeline: \r\n* ← Previous book: [[Mount Hyjal and Illidan's Gift]]\r\n* → Next book: [[Exile of the High Elves]]",},
			["The Writhing Deep"] = { content = "#REDIRECT [[Writhing Deep]]", redirect = "Writhing Deep",},
			["The Writhing Haunt"] = { content = "#REDIRECT [[Writhing Haunt]]", redirect = "Writhing Haunt",},
			["The Wyrmrest Accord"] = { content = "#REDIRECT [[Wyrmrest Accord]]", redirect = "Wyrmrest Accord",},
			["The Yorgen Farmstead"] = { content = "#REDIRECT [[Yorgen Farmstead]]", redirect = "Yorgen Farmstead",},
			["The Zhevra"] = { content = "==Task==\r\nSlay Zhevra Runners to collect 4 Zhevra Hooves for [[Sergra Darkthorn]] in the Crossroads.\r\n==Reward==\r\n6 silver\r\n==Notes==\r\nYou will need one inventory spot free to retrieve the 4 from the corpses of the Zhevra you kill.",},
			["The Zoram Strand"] = { content = "#REDIRECT [[Zoram Strand]]", redirect = "Zoram Strand",},
			["Thiassi the Lightning Bringer"] = { content = "'''Thiassi the Lightning Bringer''' is the brother of the King of the Storm Giants, [[Gymer]]. After his conversion into an undead, he lured his brother into a trap.\r\n[[Grand Necrolord Antiok|Antiok]], Grand Necrolord of the Scourge, rides upon his shoulder.",},
			["Thick Armor Kit"] = { content = "==Source==\r\nThis item can be acquired through [[Leatherworking]].\r\nThis item drops from [[Olaf]] in [[Uldaman]].\r\nThis item is a quest reward from The Green Hills of Stranglethorn.\r\n==Thick Armor Kit as a quest objective==\r\nThis item is an objective for the following quests:\r\n* Wild Leather Shoulders\r\n* Wild Leather Shoulders",},
			["Thick Bronze Darts"] = { content = "==Source==\r\nThis item can be acquired through Blacksmithing.",},
			["Thick Bronze Necklace"] = { content = "==Source==\r\nThis item can be acquired through [[Jewelcrafting]] and requires skill 50.",},
			["Thick Clefthoof Leather"] = { content = "'''Thick Clefthoof Leather''' is [[Skinning|skinned]] from the [[Clefthoof|clefthooves]] in [[Nagrand]] and from [[Elekk|elekks]] at [[Ruins of Baa'ri|Ruins of Baa'ri]].\r\n==As a leatherworking ingredient==\r\n* Clefthide Leg Armor\r\n* Drums of Battle\r\n* Drums of War\r\n* Enchanted Clefthoof Boots\r\n* Enchanted Clefthoof Gloves\r\n* Enchanted Clefthoof Leggings\r\n* Heavy Clefthoof Boots\r\n* Heavy Clefthoof Leggings\r\n* Heavy Clefthoof Vest\r\n* Bag of Many Hides\r\n* Nethercleft Leg Armor",},
			["Thick Dawnstone"] = { content = "'''Thick Dawnstone''' is a gem crafted by [[Jewelcrafting]], requiring a minimum skill of 350.\r\nReagents:\r\n* 1x [[Dawnstone]]\r\nThe [[Design: Thick Dawnstone|recipe]] for this item is a [[world drop]].",},
			["Thick Felsteel Necklace"] = { content = "==Source==\r\nThis item is crafted by [[Jewelcrafting|Jewelcrafters]] with a skill level of 355.\r\nThe components are:\r\n*2xFelsteel Bar\r\n*3xMercurial Adamantite\r\nThe [[design]] is a random [[world drop]].",},
			["Thick Hide"] = { content = "''For the Hunter Talent, see [[Thick Hide (Hunter talent)]]. For the Druid talent, see [[Thick Hide (Druid talent)]].\r\n==Source==\r\nObtained with the [[Skinning]] skill on level 40-60 skinnable animals\r\n==Thick Hide as an ingredient==\r\nThis item is used to make: \r\n* Cured Thick Hide",},
			["Thick Hide (druid ability)"] = { content = "'''Thick Hide''' is a Tier 2 Druid talent in the Feral Combat tree. It increases the amount of armor received from gear by X%.\r\n==Notes==\r\nThick Hide gives an armor bonus to the Druid in any form. It is very useful for soloing at lower levels, and necessary for tanking later on. The armor bonus is multiplicative with the bonus from Bear and Dire Bear forms; in other words, Druids benefit from this talent even more while shifted into Bear or Dire Bear form.\r\n<center><pre>100% + 400% = 500%\r\n500% * 10% = 50%\r\n500% + 50% = 550%</pre>\r\n''Base armor plus Dire Bear bonus plus 10% Thick Hide bonus equals 550% base armor.''</center>",},
			["Thick Leather"] = { content = "==Source==\r\nThis item can be purchased for 12 silver copper from Lhara in [[Terokkar Forest]].\r\nThis item is a quest reward from Catch of the Day.\r\nThis item can be obtained through the [[Skinning]] profession on level 40-50 mobs. Reliable sources include:\r\n*'''Lvl. 48+:''' Southeast to east of [[Un'Goro Crater]]. The raptors range from levels 48-51.\r\n*'''Lvl. 49-50:''' Along the eastern shore in [[The Hinterlands]] are turtles from level 49-50. They drop thick leather roughly 60% of the time and rugged leather roughly 40% of the time. Be wary of [[Gammerita]], however, an aggressive turtle who will attack on sight. Read a full writeup on the Hinterland turtles [[Farming Hinterland turtles|here]].\r\n*'''Lvl. 50-51/60-61:''' Unbeknowest to most players the Alterac Rams and Frostwolf Howlers in [[Alterac Valley]] are skinnable once killed and looted. Most of the time they will drop Thick Leather.\r\n==Thick Leather as a quest objective==\r\nThis item is an objective for the following quests:\r\n* Wild Leather Armor (Horde)\r\n* The Horde Needs Thick Leather!\r\n* The Horde Needs More Thick Leather!\r\n* The Alliance Needs Thick Leather!\r\n* The Alliance Needs More Thick Leather!\r\n* Wild Leather Armor (Alliance)\r\n==Thick Leather as an ingredient==\r\nThis item is used to make: \r\n* Catseye Ultra Goggles\r\n* Gauntlets of the Sea\r\n* Wild Leather Shoulders\r\n* Runed Mithril Hammer\r\n* Truesilver Champion\r\n* Thick Leather Ammo Pouch\r\n* Wild Leather Cloak\r\n* Deadly Scope\r\n* Wild Leather Boots\r\n* Tough Scorpid Boots\r\n* Helm of Fire\r\n* Big Voodoo Mask\r\n* Rugged Leather\r\n* Turtle Scale Breastplate\r\n* Shadowskin Gloves\r\n* Shadoweave Boots\r\n* [[Blight (polearm)|Blight]]\r\n* Black Mageweave Boots\r\n* Spellpower Goggles Xtreme\r\n* Phantom Blade\r\n* Big Black Mace\r\n* Red Rocket Cluster\r\n* Tough Scorpid Bracers\r\n* Blue Rocket Cluster\r\n* The Shatterer\r\n* Green Lens\r\n* Crimson Silk Gloves\r\n* Feathered Breastplate\r\n* Heavy Mithril Boots\r\n* Nightscape Shoulders\r\n* Wicked Mithril Blade\r\n* Quickdraw Quiver\r\n* Tough Scorpid Leggings\r\n* Nightscape Headband\r\n* Dragonscale Breastplate\r\n* Blue Glittering Axe\r\n* Ornate Mithril Boots\r\n* Cindercloth Boots\r\n* Thick Armor Kit\r\n* Tough Scorpid Breastplate\r\n* Nightscape Tunic\r\n* Tough Scorpid Helm\r\n* Tough Scorpid Gloves\r\n* Turtle Scale Helm\r\n* Dragonscale Gauntlets\r\n* Turtle Scale Bracers\r\n* Nightscape Boots\r\n* Turtle Scale Leggings\r\n* Big Voodoo Robe\r\n* Ornate Mithril Shoulder\r\n* Wild Leather Leggings\r\n* Wild Leather Vest\r\n* Wild Leather Helmet\r\n* Wolfshead Helm\r\n* Tough Scorpid Shoulders\r\n* Big Voodoo Cloak\r\n* Big Voodoo Pants\r\n* Turtle Scale Gloves\r\n* Ebon Shiv\r\n* Green Rocket Cluster\r\n* Mithril Scale Shoulders\r\n* Rose Colored Goggles\r\n* Nightscape Pants",},
			["Thick Murloc Armor"] = { content = "</noinclude>",},
			["Thick Murloc Scale"] = { content = "'''Thick Murloc Scale''' is a [[murloc]] scale. It can be found on any number of mid-level murlocs throughout the land.\r\n==As a [[Leatherworking]] ingredient==\r\n*[[Murloc Scale Bracers]]\r\n*[[Thick Murloc Armor]]",},
			["Thick Netherscale Breastplate"] = { content = "==Source==\r\nThe recipe for this item is a [[world drop]]. It requires a [[Leatherworking|Leatherworker]] with a skill level of 365 to craft.\r\nIngredients:\r\n*8 [[Heavy Knothide Leather]]\r\n*32 [[Nether Dragonscales]]\r\n*20 [[Primal Earth]]\r\n*8 [[Primal Air]]\r\n*1 [[Primal Nether]]",},
			["Thick Obsidian Breastplate"] = { content = "==Source==\r\nThis item can be crafted using [[Blacksmithing]] (300); taught by Plans: Thick Obsidian Breastplate.",},
			["Thick War Axe"] = { content = "==Source==\r\n'''Thick War Axe''' can be made by [[Blacksmithing|blacksmith]]s with a skill of 70. The recipe is taught by a trainer.",},
			["Thick Yeti Fur"] = { content = "==Source==\r\nThis item drops from:\r\n* [[Rogue Ice Thistle]] in [[Winterspring]]\r\n* [[Ice Thistle Yeti]] in [[Winterspring]]\r\n==Thick Yeti Fur as a quest objective==\r\nThis item is an objective of Are We There, Yeti?.",},
			["Thieves' Tools"] = { content = "'''Thieves' Tools''' are required for [[rogue]]s to [[Lockpicking|pick locks]].\r\n==Source==\r\nThis item is sold by Shady Dealers, Poison Vendors, and many other goods vendors.\r\nIt is also a quest reward from the following quests:\r\n*Plundering the Plunderers\r\n*Greed\r\n*Alther's Mill",},
			["Thin Kodo Leather"] = { content = "'''Thin Kodo Leather''' is a leatherworking ingredient.\r\n==Source==\r\nThin Kodo Leather is dropped by any of the [[Kodo]]s found througout [[Mulgore]] and [[The Barrens]].\r\n==Thin Kodo Leather as an ingredient==\r\nThin Kodo Leather is used in the following recipe:\r\n===[[Leatherworking]]===\r\n* Kodo Hide Bag",},
			["Third War"] = { content = "The '''Third War''' was a conflict between the mortal races of [[Azeroth]] against the [[Burning Legion]]. Unlike the previous wars, the Third War took place in both the [[Eastern Kingdoms]], and [[Kalimdor]]. In the war, the ancient [[Night Elf|Night elves]] were reintroduced to the world. Its events were chronicled in [[Warcraft III: Reign of Chaos]].\r\n==Prelude==\r\nAfter their defeat in the [[Second War]], the [[History of the Horde|Old Horde]]'s [[warchief]], [[Ner'zhul]] was captured by [[Kil'jaeden]] for his failure. As punishment, the Deceiver destroyed Ner'zhuls body, and tortured his spirit until he agreed to serve the Legion once again. His soul encased in a suit of armor which was then bound to the [[Frozen Throne]], Kil'jaeden hurled his creation towards [[Azeroth]] where it smashed into [[Icecrown Glacier]]. Thus the first major player of the Third War, the [[Lich King]] was born. Once on Azeroth, the Lich King took control of [[Northrend]] as he had the [[Necromancer]] [[Kel'Thuzad]] take the [[Plague of Undeath]] to Lordaeron.\r\nBefore the start of the war, the prophet [[Medivh]] came to the young orcish warchief [[Thrall]] in a dream. Medivh told him that he must rally the newly-reformed shamanistic Horde and move them across the sea to [[Kalimdor]] in order to escape the shadow that was coming to consume the land. Trusting the prophets words, and wishing to find a new home for his people, Thrall listened to his call, fought his way through Lordaeron's troops and sailed west.\r\n===Disturbance in the North===\r\nA rumor had started to travel around Lordaeron telling how a mysterious plague had gripped the northern lands, as the majority of Lordaerons attention was focused on the Horde's flight and rebelling orc clans. When Medivh appeared before King [[Terenas]] telling him just as he told Thrall; to save his people, he must travel east, Terenas told him that he would defend his kingdom. To do so, he sent his own son [[Arthas Menethil]], who was dealing with the rebelling orcs with Sir [[Uther the Lightbringer]] north to investigate. [[Jaina Proudmoore]] from the [[Kirin Tor]] was sent from Dalaran to aid in the investigation. \r\n===Cult of the Damned===\r\nUpon reaching the north, Jaina and Arthas discovered that [[Andorhal]]s granary's were infected with a plague that kills all who are infected. By the time Jaina and Arthas reached [[Brill]], a undead army was created there. After defeating the undead army, they hunted down and attacked Kel'Thuzad. The necromancer told Arthas that he served a dreadlord named [[Mal'Ganis]], and that he was responsible for the Scourge. Enraged, Arthas vowed he would kill Mal'Ganis and they traveled to [[Stratholme]] to confront him. \r\n===Rise of the Scourge===\r\nWhile in [[Hearthglen]], Arthas and Jania's forces were attacked by legions of [[undead]]. Arthas had Jaina search for Uther while he and his forces remained to protect the town from the Scourge. It was then he learned the truth behind the plague. The plague didn't just kill those infected, it turned them into the undead, and thus, the [[Scourge]]. Before his army was defeated, Uther and his knights arrived and saved the town. Not long after this battle, Arthas was met by Medivh, who warned the prince to travel east to Kalimdor. Like his father, Arthas refused saying his place was with his people. Jaina believed the prophets words but Arthas would not be swayed to leave his kingdom. They continued to Stratholme to deal with the threat of the Scourge. \r\n===Culling of Stratholme===\r\nUpon arriving to Stratholme, they discovered that the grain had already been distributed amongts the town. Arthas not wanting to deal with an entire army of undead ordered Uther and his [[paladin]]s to destroy the town. Uther was appalled by this, saying he wouldn't follow the order even if Arthas was the king. For his defiance, Arthas disbanded the [[Knights of the Silver Hand]] and called all those still loyal to Lordaeron to come with him. Uther took his followers and left, and Jaina quickly followed. Abandoned by his teacher and friend, Arthas continued to Stratholme to slaughter the town.\r\nUpon arrival, Arthas met Mal'Ganis himself. The two had a race of sorts for the lives of the town, Arthas wished to destroy them, Mal'Ganis wished to corrupt them. When the town was in ruin, Arthas demanded a final showdown with Mal'Ganis. Mal'Ganis however slipped away vowing to meet him in Northrend.\r\nAfter the Culling, Jaina and Uther returned to Stratholme to bury the dead. Jaina was met by Medivh who told her Arthas would only die if he went to Northrend. The prophet then told Jaina, as he had told everyone else, that she must travel east to Kalimdor, a request she answered too.\r\n===Rise of the Death Knight===\r\nAfter arriving in Northrend, Arthas discovered the brother of the dwarven king [[Magni Bronzebeard]], [[Muradin Bronzebeard|Muradin]]. Upon arriving at Northrend, Muradin's expedition was attacked by the undead and was cut off from the rest of the world. He had come to Northrend to obtain the runeblade [[Frostmourne]]. When word from Lordaeron called Arthas's men back home, the prince used mercenaries to burn their ships before turning his forces on the mercenaries. With no way to get home, he told his men that their only way home was to get the Frostmourne. When he finally found the blade, he and Muradin learned that the blade was cursed. Arthas accepted this curse and took the blade, though Muradin was killed in the process. With the Frostmourne, Arthas lead an assault on the Scourge base where Mal'Ganis was stationed and killed the Dreadlord. With the cause of his madness dead, Arthas fled to the wilderness of Northrend leaving his men to fend for themselves. \r\nMonths later Arthas returned the Lordaeron to get his just rewards. When he greeted Teranas, he took up the cursed sword and, without a moment of consideration, slew his father. Arthas then named himself King of Lordaeron and gave the land to the Scourge. Weeks later, Arthas, now a [[Death Knight]] under the orders of the Lich King was given the task to bring the dead necromancer Kel'Thuzad back from the dead. To do so, Arthas had to take his remains to a place of powerful magical power. To do so, Arthas killed his former mentor Uther for the urn he was carrying. The urn carried the ashes of his father, to which Arthas simply disposed of and placed Kel'Thuzad remains inside. The only magical nexus with the necessary power was the [[Sunwell]]. Deep inside [[Silvermoon]], capital of the [[High Elf|High elves]]. To revive Kel'Thuzad, the Scourge would have to burn [[Quel'Thalas]].\r\n===Fall of Quel'Thalas===\r\nUpon reaching the borders of Quel'Thalas, the Ranger-General [[Sylvanas Windrunner]] became a quick thorn in the death knights plan. However despite the mighty elf gates, the destruction of a important bridge and many well trained rangers, the Scourge plowed their way through Quel'Thalas's defenses on their way to [[Silvermoon]], and from there the [[Isle of Quel'Danas]] and the Sunwell. Before Sylvanas could warn Silvermoon of the Scourge invasion, her camp was raided and she was taken prisoner. Arthas tortured her and before giving her the peace of death, used his power to turn her into the first [[banshee]] making her a slave to the Scourge. With Silvermoons defenses destroyed, the Scourge entered Silvermoon and slaughtered all the High elves in the city. When Arthas reached the Sunwell, he placed Kel'Thuzad's remains in the enchanted waters, thus turning him into a [[lich]] and corrupting the Sunwell. With his business in the area done, Arthas had the Scourge kill the remaining High elves of Quel'Thalas.\r\n===The Defiler===\r\nWith Kel'Thuzad revived, they had to do their job for the Dreadlords. The Scourge traveled south to [[Dalaran]] to obtain a the [[Book of Medivh]] and use it to summon [[Archimonde]] himself to Azeroth. The Kirin'Tor used their most powerful magics, but failed preventing the Scourge from stealing the spellbook. With it Kel'Thuzad summoned Archimonde and the Burning Legion to Azeroth. Archimonde's first order of business when entering the world was to destroy Dalaran with his great power. From this point and for the rest of the war, Archimode the Field Commander of the Legion , lead the invasion of Azeroth himself, and planned to destroy [[Nordrassil]], the World Tree at [[Mount Hyjal]]\r\n==Flight to Kalimdor==\r\nShortly after the culling, before Arthas had killed Terenas, Jaina Proudmoore brought thousands with her to Kalimdor following Medivh's request.\r\nHaving fled the Eastern Kingdoms, the Horde was scattered while sailing past the [[Maelstrom]]. Some of the ships landed in a chain of islands near the Maelstorm where they met the [[Darkspear Trolls]] and aided them escape to Kalimdor.\r\nIn Kalimdor, [[Grom Hellscream]], chieftain of the prominent Warsong Clan had landed with his clan. Before they could regroup with Thrall they ran into Jainas soldiers and battles soon began.\r\nWhen the rest of the Horde reached and regrouped on Kalimdor, Grom directly defied Thralls orders by attacking Jaina Proudmoores encampment. As a punishment he was sent north to the massive [[Ashenvale]] Forest where he would collect lumber to build a capital for the orcs.\r\nMeanwhile, Thrall began his search for the rest of the Horde, and eventually came across the [[Tauren]]s, and their leader [[Cairne Bloodhoof]]. After helping Cairne repel invading [[Centaur]]s, Cairne told Thrall of a prophet up in the Stonetalon Mountains that could aid the Horde in their journey.\r\nUpon reaching the Stonetalon Mountains, Thrall and Jaina met the prophet who called doom long before the Scourge of Lordaeron, Medivh. Medivh asked that the Horde, and the Alliance work together, forgetting their old hatreds to battle a new more powerful enemy.\r\n===Mannoroth===\r\nGrom Hellscream and his clan started collecting lumber as they had been ordered to. However by doing so, they enraged the [[Night Elf|Night elves]]. After battling the night elves, their demigod [[Cenarius]] stepped in personally to deal with the Warsong Clan. \r\nAfter fighting a lost battle, the orcs realized that they couldn't kill Cenarius my conventional means. Cenarius saw the orcs as demon spawn and therefore only their total eradication would satisfy him. To defeat them, Grom and the followers drank from a mysterious fountain that empowered them. Not knowing that it had been defiled by the [[Blood of Mannoroth|blood]], of the [[Pit lord|Pit Lord]] [[Mannoroth]]. Energized and turned into [[Fel Orcs]], the Warsong successfully attacked and killed Cenarius. With the Orcs once again doing the bidding of The Legion, Mannoroth stormed up to Grom and revealed it was his blood that empowered the orcs. Despite their victory, they were once again under demon control, and thus the control of the Burning Legion.\r\nTo help their new allies, Jaina created a magical [[Soul Gem]]. Thrall would need to capture the mighty Grom within it, and take the gem to a prepared magical circle to free his spirit of Corruption. Standing between The Humans and free orcs, however, was the entire [[Warsong Clan]], fortified with scores of demons that waited in ambush and mighty [[Infernal]]s that rained from the sky. Despite his woes of killing many of the Warsong clan, Thrall captured Grom and brought him back for a ritual of cleansing. Along with his [[shaman]], Jaina, and her best [[priest]]s and [[sorcerer]]s they managed to pull the demonic taint out of Grom. Thrall and Grom then challenged Mannortoh, and though Thrall was defeated, Grom managed to deliver a killing blow, destroying Mannorth and freeing the orcs at the cost of his own life. Thus Grom redeemed himself for bringing them into the legion.\r\n==Return of the Night Elves==\r\nWhen it became evident that the Burning Legion had returned, [[Tyrande]] lead her Sentinels into the trees, fleeing a wave of undead which had destroyed a human and orc camp. As they fled, they were cornered by dreadlords, and Archimonde. Tyrande believed that with the Defilers return the only way to defeat the Burning Legion was to use the forces of old, the sleeping [[druids]] and their leader, [[Malfurion Stormrage]] her old love. After waking Malfurion, the next order of business was to awaken the rest of the [[Druids of the Talon]] and the [[Druids of the Claw]].\r\nIn their quest to free the druids, they discovered the prison that held the old [[Demon Hunter]], [[Illidan Stormrage]]. Tyrande believed that the Betrayer, as the night elves grew to call him, could be a powerful ally against the Burning Legion and left Malfurion to awaken the druids while she freed Illidan. Furion continued on, to awaken the Druids, who had after almost ten millennia in the caves grown feral. Malfurion however used the [[Horn of Cenarius]] to free them of their madness.\r\n===The Betrayer===\r\nTyrande continued her quest to free Illidan. She fought her way through [[Maiev Shadowsong|the Warden]]'s guards and Illidan was free after Ten-thousand years. Tyrande placed her trust in Illidan, believing his power would help them against the Legion. Malfurion, however, was still distrusting of his reckless brother. Eager to prove himself, Illidan vowed he would show his brother the demons had no hold over him and led a portion of the Night Elf army to Felwood. Shortly after, the death knight Arthas found and battled with Illidan. The two were evenly matched, so there was no reason for Arthas to even engage Illidan, so he demanded that Arthas told him why he was really there. Arthas told of a powerful artifact: the [[Skull of Gul'dan]]. The Skull was responsible for corruption the night elves beloved forest. Arthas played to Illidans thirst for power, mentioning that the skull held immense power, and Illidan took the bait willingly.\r\nAfter fighting his way to the through the demons, Illidan reached and consumed the power of the skull. With it's power added to his own, he slew the leader of all Dreadlords, [[Tichondrius|Tichondrius]], and helped seal the legion's defeat. When Furion and Tyrande found the new demon-night elf hybrid Furion banished Illidan for his demonic corruption, claiming that he was no brother of his. A very resentful Illidan tore his way through the dead trees and was not heard of until the coming of the [[Naga|Naga]].\r\n==Battle of Mount Hyjal==\r\nAfter Illidans banishment, Medivh called Malfurion and Tyrande to a secret grove, where he had Thrall and Jaina meet them. Medivh revealed that he was the one who helped [[Burning Legion]] create the [[Dark Portal]] and allowed the Horde to invade Azeroth. And after he was slain, for his crimes he had to return to right his wrongs and protect Azeroth from the Legions return. Medivh asked that the mortal races unite to defeat the Legion, as it was the only way to defeat the demons.\r\nTo prepare for the demons attack, three camps were built around Mount Hyjal. Malfurion deviced a plan to use the power of the World Tree itself to destroy Archimonde. As he went back up the summit to make the necessary preparations for Archimonde. Jaina and Thrall used whatever night elves Tyrande could spare to fortify their bases. Archimonde first tore his way through the human base, and then through the orcs. Before Thrall escaped death, he managed to hurt Archimonde with a bolt of his shamanistic lightning, an incredible feat. With the two bases destroyed, Archimonde stormed through the night elf gate protecting the summit. \r\nWith Archimonde at the World Tree, Furion used the Horn to call on the ancient spirits in the area to attack the demon. In an instant, they detonated into a massive explosion that destroyed the Defiler, much of his demon army with him, and the World Tree. The price for this defeat was the night elves immortality, but the Third War was over.\r\n==Aftermath==\r\nThe Third War left Lordaeron destroyed, the night elves mortal, and brought the near extinction of the high elves. No large group of humans would ever regain control Lordaeron, though the [[Argent Dawn]] and the [[Scarlet Crusade]] has been fighting the Scourge. Prince [[Kael'thas Sunstrider]] of the high elves returned to his ruined city and renamed his people, [[blood elves]] in memory of their fallen comrades. The blood elves would eventually retake much of Quel'Thalas, and in time would even reactivate the power of the Sunwell. After the war, [[Sylvanas]] would break free of the [[Lich King]]'s control, and form the [[Forsaken]]. The Forsaken would then take over the city of Lordaeron, making their home its its sewers, calling it the [[Undercity]].\r\nThe political scene of the current Azeroth was greatly influenced by the Third War. Under the Warchief Thrall, the orcs, tauren, and darkspear trolls were brought together on Kalimdor to become the [[Horde|new Horde]], to which the Forsaken would later join. A peace agreement was made between between the Horde and the Alliance after the war, and Thrall has made it his job to ensure that nothing happens to break this already stressful pact.\r\nWithout Lordaeron, the rebuilt city of [[Stormwind]] would become the base of the [[Alliance]], with the [[Ironforge Dwarf|Ironforge dwarves]] becoming their closest geographical allies. The [[gnomes]] of [[Gnomeregan]] had been unable to help in the Third war as they were dealing with their own issues closer to home; a [[trogg]] invasion of their city. Because an invasion of troggs failed in comparison to the might of the Scourge, the gnomes decided they would fight their war alone. In the end they were forced to flee Gnomergan and their king [[Gelbin Mekkatorque]] settled in [[Ironforge]] with the dwarves. Due to the loss of their immortality, and having been exposed to the world outside their forests once more, the night elves decided they would have to make alliances with the wider world. Because of the animosity with the orcs for killing Cenarius the night elves in the end joined the Alliance.\r\n==More info==\r\n* [[Arthas|The history of Prince Arthas]]\r\n* [[Jaina Proudmoore|The history of Jaina Proudmoore]]\r\n* [[Thrall|The history of Thrall]]\r\n* [[Archimonde|The history of Archimonde]]",},
			["Third Wars"] = { content = "#REDIRECT [[Third War]]", redirect = "Third War",},
			["Thistlefur Hold"] = { content = "'''Thistlefur Hold''' is located in west-central [[Ashenvale]], which is in the northern part of [[Thistlefur Village]]. It is home to the bulk of the [[Thistlefur]] [[furbolg]]s, and contains two quests for [[Horde]] characters — collecting [[troll]] charms and rescuing [[Ruul Snowhoof]], who is trapped in a cage deep in the hold.\r\nThe furbolgs here also held the [[Idol of Remulos]] for a time, which is what corrupted them and turned them hostile to all outsiders.",},
			["Thistlefur Village"] = { content = "'''Thistlefur Village''' is located in west-central [[Ashenvale]], north of [[Astranaar]]. It is the homeland of the [[Thistlefur]] [[furbolg]]s, who aggressively attack anyone who wanders too close. The Thistlefur tribe is led by two extremely ferocious warriors: [[Dal Bloodclaw]] and [[Rorgish Jowl]].",},
			["Thistleshrub"] = { content = "A '''thistleshrub''' is a large plant or plant elemental found in Tanaris. These elementals protect the Thistleshrub Valley - these are creatures of living vines, attacking anything that comes near.\r\nIt looks like a patch of cactus-like briars that shudders and then begins to move. It forms massive, gnarled arms covered in wicked thorns. A typical thistleshrub stands 12 feet high and 8 feet wide. They weigh 800 pounds. Thistleshrubs are exceptionally hardy ambulatory plants that meander about the desert seeking sources of water close to the surface. Mindless, they seek out other living creatures in order to drain liquids and minerals from their bodies.\r\nThistleshrubs often hide among normal plants, so that they appear to be nothing more than a few twisted brambles or vines. They absorb all moisture from the ground, holding it within their bodies in special dew glands. Because they take all nearby sources of moisture for themselves, thereby killing other plants, most consider them ecological menaces to be destroyed on sight. Even druids tend to have little compunction about putting down these destructive creatures. \r\nThistleshrubs immobilize any moving foe with roots, then move in and pound their prey to death. A thistleshrub always attacks the foe with the most fluid -- i.e, usually the largest one. They ignore constructs and creatures with no water content unless such creatures attack them first.\r\n==Notes==\r\n*The plant creatures [[bog beast]], [[timberling]]s, and conglomerate elemental creature [[tar beast]], while using the same model as thistleshrubs are each treated as separate types of creatures. However thistleshrub is like a subcategory of overall bog beast category.\r\n*Brann calls them plant elementals.\r\n*Other lore describes Thistleshrubs as large plants and makes no connection to them being elementals. They are not given elemental sub-type in their game stats in Monster Guide.\r\n*They are listed as [[Elemental]]s in World of Warcraft, while this may be a game mechanic, it is supported by lore.",},
			["Thistleshrub Valley"] = { content = "'''Thistleshrub Valley''' is an area thick with giant cacti (very unusually alive for [[Tanaris]]) and desert-dwelling [[thistleshrub]]s. \r\n==Quests in Thistleshrub Valley==\r\n*Thistleshrub Valley\r\n*The Thirsty Goblin",},
			["Thistle Boar"] = { content = "These thistle boars live in the sheltering forest of [[Shadowglen]], on the great tree [[Teldrassil]]. Unfortunately, the thistle boar population in the area has recently skyrocketed to unhealthy numbers. The [[night elf|night elves]] of the area have begun culling the boars in an attempt to keep their population in check (see The Balance of Nature (2)).\r\n==Notable Drops==\r\n*Tough Jerky\r\n==Quests==\r\n* The Balance of Nature (2) - from Conservator Ilthalaine in [[Shadowglen]]\r\n:Objective: Kill 7 [[Mangy Nightsaber]]s and 7 [[Thistle Boar]]s.",},
			["Thistle Tea"] = { content = "==Source==\r\nThis item can be crafted using [[Cooking]] (60); taught by Recipe: Thistle Tea. \r\nThis item is a quest reward from the following quests:\r\n* Plundering the Plunderers",},
			["Thomas Yance"] = { content = "'''Thomas Yance''' can be found walking the road between [[Southshore]] and [[Tarren Mill]] in [[Old Hillsbrad Foothills]]. He can repair your armor and sells, of all things, most of the game's newbie costumes, as well as the valuable [[Pattern: Riding Crop]] recipe.\r\nHe may be related to [[Kelsey Yance]] and [[Micha Yance]]\r\nSee [[Caverns of Time NPCs]].",},
			["Thondroril"] = { content = "#redirect [[Thondroril River]]", redirect = "Thondroril River",},
			["Thondroril River"] = { content = "The '''Thondroril River''' makes up the border between the [[Western Plaguelands|Western]] and [[Eastern Plaguelands]]. It runs from near the [[Terrorweb Tunnel]] to the north and empties out into [[Darrowmere Lake]] to the south. Along the river on on both sides, you can find [[maggot]]s, [[Vampire Bat|vampire bat]]s, [[plaguebear]]s and [[spider]]s. You can also find [[Tirion Fordring]] (a level 61 elite quest giver) near a ruined farmhouse on the Eastern Plaguelands side of the river. \r\n==Notes==\r\n* Earlier maps show a river flowing from [[Lake Abassi]] south into [[Darrowmere Lake]] which may be the same river as this, called the [[Greenrush River]], but [[Quel'Thalas]] was attached too far east to show this in WoW. Thondroril may be [[Thallassian]] for \"Greenrush\".",},
			["Thor"] = { content = "'''Thor''' is a level 55 [[gryphon]] [[flight master]] located in [[Sentinel Hill]] in the [[human]] territory of [[Westfall]].\r\nHe starts the quest Continue to Stormwind.\r\nSee [[List of Westfall NPCs]].",},
			["Thoradin's Wall"] = { content = "'''Thoradin's Wall''' is a huge wall separating the [[Arathi Highlands]] from the [[Hillsbrad Foothills]]. The wall protected [[Stromgarde]] and the Arathi Highlands from the invading [[Scourge]]. \r\nIn World of Warcraft, the gigantic wall is heavily damaged. In the [[Old Hillsbrad Foothills]] instance of the [[Caverns of Time]], the wall is in considerably better condition, but still quite a bit damaged. \r\nThere is no evidence or lore explaining the origin of the great wall, but some have supposed that King [[Thoradin]] built it ages past, during the [[Troll Wars]], perhaps to protect his lands from the trolls' onslaught; note the ramps on the Hillsbrad side to give defenders access to the top of the wall.\r\nIt does, however, seem quite unlikely that a wall this massive was built in a single king's lifespan.\r\nIt is unclear why the wall is in ruins, however one can assume that possibly the local [[Ogre]] or [[Troll]] clans, or possibly the [[Syndicate]] may be responsible. Time may be responsible as well.\r\n==Additional Information==\r\nThe damaged Thoradin's Wall shares the same model as the current ingame model of the [[Greymane Wall]]. In the [[Escape from Durnholde Keep|Caverns of Time Durnholde Keep]] event behind the intact wall is still unfinished land, containing only discolored land and deformed mountains, as well as a huge ledge from which one can freely fall to their doom.",},
			["Thoradin"] = { content = "'''Thoradin''' was the leader of the [[Arathi]] tribe of humans. He led them to unify the various human tribes into the great nation of [[Arathor]], founded the capital of [[Strom]], and forged an alliance with the [[high elf|high elves]] in the [[Troll War]]s.\r\nA huge [[Thoradin's Wall|wall]] between [[Arathi Highlands]] and [[Hillsbrad]] has been either named in his memory or built by himself or one of his descendants bearing same name.",},
			["Thoras Trollbane"] = { content = "'''Lord Thoras Trollbane''' was king of the human Kingdom of [[Stromgarde]].\r\n==The Second War==\r\nThoras Trollbane was a natural born warrior. His people's lands were in the heart of troll-populated areas, and so being ready for battle was simply a way of life. He was a good friend of King [[Terenas]] of [[Lordaeron]]. He was one of the human leaders who met at the councils to form the [[Alliance of Lordaeron]]. Stromgarde was quick to join the Alliance, following the start of the [[Second War]], sending half of its standing army to the main Alliance forces, for Trollbane felt that glorious battle was to be had with the [[orcs]]. But Stromgarde had little chance to show its offensive capabilities, as its other half of the army was defending the Northlands from invasion through the dwarven realm of [[Khaz Modan]], which the [[Horde (pre-Thrall)|Horde]] led by the [[Blacktooth Grin]] had already expanded into. \r\nStromgarde came under heavy assault and losses, but continued to battle through with a resilience the Horde did not expect, its knights and warriors attacking at every turn. But the Horde did manage to destroy a good deal of Trollbane's kingdom, and to continued its march towards the elven kingdom of [[Quel'Thalas]].\r\nFollowing the destruction of [[Alterac]] after its deal with the Horde became known, Thoras Trollbane petitioned King Terenas to annex the eastern portion of [[Alterac]]'s territory to [[Stromgarde]] in recognition of the latter's sacrifices and valor during the Second War.\r\nAfter the defeat of the orcs in the Second War, much of the Horde was wiped out, and most surviving orcs were placed in concentration camps. Trollbane, however, fervently disagreed this policy, believing that the orcs were simply too dangerous to be kept alive. He argued with Terenas the hardest, an argument between friends. When [[Lordaeron]] refused to mass execute the orcs, Trollbane withdrew his support from the Alliance.\r\n==Death and legacy==\r\nThoras Trollbane met his end when he was assassinated under mysterious circumstances following the [[Third War]]. This was merely the beginning of Stromgarde's darkest hour, as the kingdom soon came under siege by forces of the [[Syndicate]] and [[Boulderfist]] [[ogres]]. The Syndicate and Boulderfist won several battles against the now weakened kingdom, and managed to occupy much of its terrain, including most of the capital city. Thoras was succeeded as Stromgarde's ruler by his son, Prince [[Galen Trollbane]].\r\nHad he not fallen, Stromgarde's fate could be different.\r\nThoras' nephew, [[Danath Trollbane|Danath]], was the tactical adviser to the [[Alliance Expedition]] to [[Outland|Draenor]] during the Second War, and was believed to have died after Draenor was destroyed and the [[Dark Portal]] sealed off; however, Danath has recently been discovered alive at [[Honor Hold]], in the region now known as Outland.",},
			["Thori'dal, the Stars' Fury"] = { content = "'''Thori'dal, the Stars' Fury''' is the name of a bow that drops from [[Kil'jaeden (tactics)|Kil'jaeden]], who is the last boss of the [[Sunwell Plateau]] 25-man raid instance. The name ''Thori'dal'' was first seen in the 2.4 PTR patch notes. This bow is currently the highest dps weapon in game, excluding wands.\r\nThe first bow was obtained by Stefang, a hunter from [[Guild:Last Resort (Boulderfist EU)|Last Resort]] on May 29th, 2008.\r\n==Notes==\r\nThori'dal generates magical arrows when the bow string is drawn, thus eliminating the need for the hunter to carry ammo. Attempting to add ammunition to the paper doll slot Thori'dal will not add extra DPS, and instead produces an error message \"Ammo slot full.\" The high DPS of this bow is most likely the result of this lack of need for arrows since there will be no +damage added from such. The current top arrow is Timeless Arrow with a +53.0 bonus and this gives Thori'dal a comparative DPS of 109.8 - presumably. However, due to the nature of [[Steady Shot]], this weapon vastly increases Hunter DPS, in spite of having comparable DPS to Golden Bow of Quel'Thalas with Timeless Arrow.\r\nThori'dal also has a +15% attack speed effect not stacking with ammo quivers or pouches, allowing the hunter to carry a fifth normal bag.",},
			["Thorim"] = { content = "'''Thorim''' is a [[frost vrykul]] [[giant]] seated on a throne within the [[Temple of Storms]], high above the [[Storm Peaks]] of [[Northrend]].\r\nHe is the brother of the giant betrayer, [[Loken]], and his wife was killed by the latter. He eventually faces Loken during the quest The Reckoning, but Loken uses his proximity to his [[Yogg-Saron|Dark Master]]'s seat of power to overcome and capture Thorim and his proto-dragon mount. Their fate is as of yet unknown.",},
			["Thorium"] = { content = "'''Thorium''' is a powerful [[metal]] [[Mining|mined]] on [[Azeroth]]. It borrows its name from the real-life radioactive metal , which in turn was named after the Norse god of thunder .\r\nThorium can be [[smelt]]ed into [[Thorium Bar]]s. In addition to its inherent strength, [[Alchemy|Alchemists]] and [[Enchanting|Enchanters]] can further improve on Thorium to allow for the creation of more powerful items.\r\nThis rare metal combines the weight of lead with the strength of steel. Orcs prize it for weapons because the extra weight allows a skilled user to strike with more force. Thorium armor is amazingly heavy and strong — only [[adamantite]] pierces it with any degree of reliability. Thorium is heavier than most metals. An item made from thorium weighs twice as much as the same item made from other metals.\r\nSmall Thorium Veins require mining skill 245, Rich Thorium Veins require mining skill 275.\r\nThe [[Thorium Brotherhood]] faction drew its name from the metal, as well.\r\nItems mined from Thorium Veins:\r\n* Thorium Ore\r\n* Dense Stone\r\n* Arcane Crystal\r\n* Blue Sapphire\r\n* Star Ruby\r\n* Azerothian Diamond\r\n* Huge Emerald\r\n* Large Opal\r\nThere are also '''Ooze Covered Rich Thorium Vein''' and '''Ooze Covered Thorium Vein''' found in [[Silithid]] hives. These are essentially the same as the others but contains slightly more gems.\r\n==See also==\r\n*[[Thorium Ore]]\r\n*[[Thorium Bar]]\r\nRelated\r\n* [[Arcanite Bar]]\r\n* [[Enchanted Thorium Bar]]",},
			["Thorium Armor"] = { content = "'''Thorium Armor''' is a [[Blacksmithing|Blacksmith]]-made chestplate. It's known for being resistant to many forms of magic. \r\n==Source==\r\nIt's made by a blacksmith with a skill level of 250.\r\nThe components are:\r\n*16 [[Thorium|Thorium Bars]] \r\n*1 [[Blue Sapphire]]\r\n*4 [[Yellow Power Crystal]]s.\r\n[[Plans: Thorium Armor]] are a [[world drop]] from (Azeroth) world bosses, and from creatures leveled about 49-59.",},
			["Thorium Bar"] = { content = "A '''thorium bar''' is a strong, hard metal [[smelting|smelted]] from [[Thorium Ore]]. Used in very many [[Artisan]]-level crafting recipes and as a basis for creation of [[Arcanite]] and [[Enchanted Thorium Bar]]s.\r\n==Source==\r\n'''Thorium Bar''' can be created by [[Miner]]s using\r\ntheir [[smelting]] ability at a [[forge]].\r\n==An ingredient==\r\n'''Thorium Bar''' is used in the following recipes:\r\n===Alchemy===\r\n*[[Transmute: Arcanite]]\r\n** Creates one [[Arcanite Bar]] from one Thorium Bar and one [[Arcane Crystal]]\r\n===Mining (Smelting)===\r\n*[[Enchanted Thorium Bar]]\r\n** Creates one [[Enchanted Thorium Bar]] from one Thorium Bar and 3 [[Dream Dust]]\r\n===Engineering===\r\n*[[Arcane Bomb]]\r\n*[[Field Repair Bot 74A]]\r\n*[[Gnomish Alarm-o-Bot]]\r\n*[[Salt Shaker]]\r\n*[[Thorium Grenade]]\r\n*[[Thorium Rifle]]\r\n*[[Thorium Tube]]\r\n*[[Thorium Widget]]\r\n===Jewelcrafting===\r\n*[[Emerald Crown of Destruction]]\r\n*[[Figurine - Black Diamond Crab]]\r\n*[[Figurine - Emerald Owl]]\r\n*[[Thorium Setting]]\r\n==As a quest objective==\r\n*[[Imperial Plate Belt (quest)]]\r\n*[[Imperial Plate Boots (quest)]]\r\n*[[Imperial Plate Bracer]]\r\n*[[Imperial Plate Chest (quest)]]\r\n*[[Imperial Plate Helm (quest)]]\r\n*[[Imperial Plate Leggings (quest)]]\r\n*[[Imperial Plate Shoulders (quest)]]\r\n*[[That's Asking A Lot]]\r\n*[[Icebane Bracers (quest)]]\r\n*[[Icebane Breastplate (quest)]]\r\n*[[Icebane Gauntlets (quest)]]\r\n*[[The Alliance Needs Thorium Bars!]]\r\n** Active only during the opening of the [[Gates of Ahn'Qiraj]].\r\n*[[Zinfizzlex's Portable Shredder Unit (quest)]]",},
			["Thorium Boots"] = { content = "'''Thorium Boots''' are plate boots that provide extra resistance to all magic types.\r\n==Source==\r\n'''Thorium Boots''' are crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 280.\r\nThe components are:\r\n*20 [[Thorium Bar]]\r\n*8 [[Rugged Leather]]\r\n*4 [[Green Power Crystal]]\r\nThe [[Plans: Thorium Boots|plans]] drop off creatures with their levels in the 50s and above.",},
			["Thorium Brotherhood"] = { content = "The [[Searing Gorge]] is home to a group of exceptionally stout [[dwarves]] who have split from the [[Dark Iron Clan]]. On the cliffs overlooking the region called the [[Cauldron]], in the far north of the Searing Gorge, the dwarves of the '''Thorium Brotherhood''' have established a base of operations, [[Thorium Point]]. From here, they keep a close eye on the Dark Iron dwarves' activities in the Searing Gorge and beyond. Adventurers seeking out Thorium Point will find that the dwarves of the Thorium Brotherhood hold great rewards for those who aid them in their never ending struggle against their former brethren.\r\nThe Thorium Brotherhood comprises many exceptionally talented craftsmen, and the blacksmiths of the Brotherhood are rumored to be among the finest Azeroth has ever seen. They possess the knowledge required to make the arms and armaments of [[Ragnaros]], the [[Fire Lord]], but lack the manpower to obtain the materials required for the crafting. It is rumored that one member of the Thorium Brotherhood has been empowered to trade the dwarves' fabled recipes and plans with those who can prove their loyalty to the Brotherhood. Of course, proving one's loyalty at some point may include venturing to the heart of the [[Molten Core]], the domain of Ragnaros, the Fire Lord himself, to supply the dwarves with the rare raw materials found there. A daunting task, no doubt, but gaining access to the Thorium Brotherhood's secrets should prove to be a reward well worth the effort.\r\n==History==\r\nThe Thorium Brotherhood predates the War of the Three Hammers. Originally, it was merely one of the numerous craft guilds operating in Ironforge. Though skilled craftsmen, the members of the Brotherhood were always worried that another guild possessed secrets that they didn’t. The Brotherhood would often acquire a competitor’s goods, and try to reverse engineer them. It was thus that they discovered the secrets of enchantment — absorbing the magic from an item as you destroy it, and channeling that magic into a new item.\r\nDuring the War of the Three Hammers, the Thorium Brotherhood naturally sided with the Dark Iron clan. When Ragnaros enslaved the Dark Irons, the Firelord sent what remained of the Thorium Brotherhood to work his forges along with many of their kin.\r\nWhile most Dark Iron dwarves were resigned to enslavement (after all, they were still doing what they were doing before, and now they had a powerful patron), not so the Thorium Brotherhood. To the members of this guild, their great talents were being wasted mass-producing weapons for the Firelord’s armies. Thus Oilfi st (former apprentice to Overseer Lokhtar) devised a plan of escape. With their knowledge of enchanting and their access to the forges, the dwarves crafted, under the noses of their taskmasters, weapons, armor and tools that allowed them to escape Blackrock Depths.\r\nEvery free Dark Iron dwarf gets as far away from Blackrock Spire they can.Thorium Brotherhood would have as well, except that the formulas they possessed all required components found only under or around Blackrock Mountain. Thus, they were compelled to set up shop across the Searing Gorge from their former home. Using the formulas they have created or acquired, they make enchanted weapons and armor for anyone who can meet their exorbitant prices.\r\n==Relationships==\r\nThe dwarves of the Thorium Brotherhood are skilled craftsmen with access to unique enchantments, and people from all affiliations come to buy their wares. The Brotherhood has no qualms about dealing with anyone who can meet their prices, going even so far as to arm both sides of the same conflict. However, just because the Thorium Brotherhood trades with anyone doesn’t mean they’re friendly. If the Brotherhood decides that you’re competition, there’s no trick to which they won’t stoop to maintain their market share.\r\n==Organization==\r\nThe leader of the Thorium Brotherhood is called the overseer. Other members of the guild are ranked as apprentices, journeymen, and master smiths as befi ts their skill. Members within each rank are nominally equal and all members are expected to contribute both in the workshops and in defense of Thorium Point.\r\n===Military===\r\nAs a craft guild the Thorium Brotherhood has no need for a permanent military arm. On the other hand the Searing Gorge is a dangerous region and the Brotherhood is well aware of the threat presented by wild beasts, elementals and even their fellow Dark Iron dwarves. All members of the guild are required to spend at least some time on the walls as lookouts. The skill-based ranking system of the guild extends even into defense of Thorium Point. Master smiths serve as watch commanders, while journeymen and apprentices do the actual patrolling of the walls.\r\nNearly all members of the Thorium Brotherhood start as experts, rogues or warriors. In order to rise above the level of apprentice, a guild member must have at least one level in the martial enchanter prestige class (see Chapter 2: Class Options). Dwarves of the Thorium Brotherhood maximize their ranks in one or more Craft skills, usually armor- or weaponsmithing. Though their focus is on making arms, members of the Thorium Brotherhood are no slouches when it comes to using them, either. Naturally, they have many quality weapons and armors on hand.\r\nIf the Thorium Brotherhood has need of additional troops — especially for missions outside their holdings — their solution is the same as for any other problem: They contract out. Like suppliers, most of these mercenaries work for fi nished goods rather than cash; indeed, many of them have previous experience as suppliers for the Brotherhood. Generally these missions are defensive in nature — culling a herd of salamanders in the Searing Gorge or routing bandits who interfere with trade. On occasion, though, these dwarves reveal their vindictive streaks and hire mercenaries to strike against their “competitors” through sabotage and even slaughter. At the moment this enmity is focused on the Dark Iron dwarves still in Blackrock Depths; but as their operations expand the Thorium Brotherhood is likely to find new competitors to torment, and this might bring their mercenaries in conflict with the heroes. The Brotherhood’s use of mercenaries allows them to distance themselves from such underhanded tactics, and victims may have a hard time linking the Brotherhood to these attacks.\r\n==Summary==\r\nThe Thorium Brotherhood are an elite group of craftsmen who can reveal a number of [[epic]] recipes if you gain enough faction [[reputation]] with them. They are former [[Dark Iron Dwarves]] who have left [[Blackrock Depths]] to explore (exploit) the world. All players start off at Neutral (0) reputation with them.\r\n* The Thorium Brotherhood have a base camp in [[Searing Gorge]], [[Thorium Point]] (added in Patch 1.5). There are several quests here (levels 48-52), including three repeatable reputation quests. \r\n* [[Master Smith Burninate]] at [[Thorium Point]] gives repeatable quests for Neutral to Friendly and Friendly to Honored reputation.\r\n* [[Derotain Mudsipper]] in [[Gadgetzan]] is also a member, and gives the [[Imperial Plate]] quests for Blacksmiths. \r\n* [[Lokhtos Darkbargainer]] , in the Grim Guzzler (tavern) in [[Blackrock Depths]], gives quests that raise faction by turning in drops from [[Molten Core]], and is also the vendor for the tradeskill recipes. \r\n* [[Malyfous Darkhammer]] in [[Everlook]].\r\nThere are recipes for [[Tailoring]] and [[Enchanting]], as well as each specialization of [[Leatherworking]] and [[Blacksmithing]]. Each of the recipes requires some components from the [[Molten Core]]. A minor [[Alchemy]] recipe, [[Transmute: Elemental Fire]], which is useful for raids that frequently visit the [[Molten Core]], is available as well.\r\n==Thorium Point==\r\nLocated near the northwest corner of [[Searing Gorge]]. There is an alliance flightpath here, which connects to both [[Ironforge]] and [[Morgan's Vigil]], [[Burning Steppes]], and a Horde flightpath which connects to [[Flame Crest]], [[Burning Steppes]] and [[Kargath]], [[Badlands]]. There is a wanted poster and 3 questgivers that assign 7 quests. As of patch 2.0.1 you get 250 Reputation Points for each of these 7 quests at any level. Note that 6 of these 7 quests can be handed in after reaching honored status with the brotherhood (\"What the Flux?\" has to be completed before reaching honored, this is explained below).\r\n*JOB OPPORTUNITY: Culling the Competition\r\n*STOLEN: Smithing Tuyere and Lookout's Spyglass\r\n*Curse These Fat Fingers\r\n*Fiery Menace!\r\n*Incendosaurs Whateverosaur is More Like It\r\n*WANTED: Overseer Maltorius\r\n*What the Flux\r\nAfter completing \"What the Flux?\", you may complete three repeatable reputation quests. Each of these requires 2 [[Incendosaur Scales]] and 1 Coal (purchasable from [[Master Smith Burninate]] for 5s), as well as the named item.\r\n* Restoring Fiery Flux Supplies via Heavy Leather requires 10 [[Heavy Leather]]\r\n* Restoring Fiery Flux Supplies via Iron requires 4 [[Iron Bar]]\r\n* Restoring Fiery Flux Supplies via Kingsblood requires 4 [[Kingsblood]]\r\nEach of these rewards 25 reputation and is repeatable until Friendly. \r\nAfter reaching Friendly, you may complete a single repeatable quest to reach Honored. It requires 4 Dark Iron Residue (a common drop from Blackrock Depths) per turn-in, and gives 25 reputation per turn-in.\r\n* Gaining Acceptance. \r\nThe following quest can only be done during the 10-hour Opening of the Gates of Ahn'Qiraj [[World Event]], and they require you to kill 3 huge bosses in Silithus that can (apparently) only be killed by a very long raid [[graveyard zerg]].\r\n*Secrets of the Colossus - Regal - 1000 reputation with Thorium Brotherhood\r\n==Reputation==\r\nPlayers start out neutral with [[Thorium Brotherhood]]\r\n===See also===\r\n*For Blacksmiths, there is also a series of quests in [[Tanaris]], see [[Derotain Mudsipper]] (''Requires at least level 50 and 265 [[Blacksmithing]])''\r\n====Guide for Herbalists, Miners, and Skinners====\r\nThis section emphasizes items found by herbalists, miners or skinners. The maximum reputation level with this method is . See the sections below for steps to follow if you want to focus on item drops from [[Blackrock Depths]], or if you expect to raid [[Molten Core]] on a regular basis and want to achieve or status.\r\n===== Phase 1: 0 / 3000 Neutral =====\r\n# Complete What the Flux. +250 rep. (250 / 3000)\r\n# Collect 220 Incendosaur Scale. These can be found at the bottom of [[The Cauldron]] (past where you found the quest item for step 1).\r\n# Collect 110 Coal. These can be found sporadically off of mobs, but can also be purchased from specific engineering or mining vendors at s=5 gold each (s=4 gold if ).\r\n# Collect either 1100 Heavy Leather, ''or'' 440 Iron Bar, ''or'' 440 Kingsblood. You can also collect any variation of these quantities.\r\n# Complete the appropriate turn-in quests until you are (3000 / 3000).\r\n===== Phase 2: 0 / 1500 Friendly =====\r\n# Complete the other six Thorium Brotherhood quests: +250 rep each.\r\n#* JOB OPPORTUNITY: Culling the Competition\r\n#* STOLEN: Smithing Tuyere and Lookout's Spyglass\r\n#* Curse These Fat Fingers\r\n#* Fiery Menace!\r\n#* Incendosaurs Whateverosaur is More Like It\r\n#* WANTED: Overseer Maltorius.\r\n===== Phase 3: 1500 / 6000 Friendly =====\r\n# Collect 720&times;Dark Iron Residue. These can be found on the mobs within [[Blackrock Depths]].\r\n# Complete the appropriate turn-in quests until you are (6000 / 6000).\r\n====Guide with Item Drops from Blackrock Depths====\r\nThis section emphasizes item drops from [[Blackrock Depths]]. The maximum reputation level with this method is . See the section below if you expect to raid [[Molten Core]] on a regular basis and want to achieve or status.\r\n===== Phase 1: 0 / 1750 Neutral =====\r\n# Complete the following seven quests. Each gives 250 reputation:\r\n#* What the Flux\r\n#* JOB OPPORTUNITY: Culling the Competition\r\n#* STOLEN: Smithing Tuyere and Lookout's Spyglass\r\n#* Curse These Fat Fingers\r\n#* Fiery Menace!\r\n#* Incendosaurs Whateverosaur is More Like It\r\n#* WANTED: Overseer Maltorius.\r\n===== Phase 2: 1750 / 3000 Neutral =====\r\n# Collect 100 Incendosaur Scale. These can be found at the bottom of [[The Cauldron]] (past where you found the quest item for step 1).\r\n# Collect 50 Coal. These can be found sporadically off of mobs, but can also be purchased from specific engineering or mining vendors at s=5 gold each (s=4 gold if ).\r\n# Collect either 500 Heavy Leather, ''or'' 200 Iron Bar, ''or'' 200 Kingsblood. You can also collect any variation of these quantities.\r\n# Complete the appropriate turn-in quests until you are (3000 / 3000).\r\n===== Phase 3: 0 / 6000 Friendly =====\r\n# Collect 960&times;Dark Iron Residue. These can be found on the mobs within [[Blackrock Depths]].\r\n# Complete the appropriate turn-in quests until you are (6000 / 6000).\r\n====Guide with Raids into Molten Core====\r\nThis section assumes frequent raids into [[Molten Core]] (or regular access to materials from the instance). If you do not expect to raid Molten Core very frequently, follow the sections above.\r\n===== Phase 1: 0 / 3000 Neutral =====\r\n# Complete What the Flux. +250 rep. (250 / 3000)\r\n# Collect 220 Incendosaur Scale. These can be found at the bottom of [[The Cauldron]] (past where you found the quest item for step 1).\r\n# Collect 110 Coal. These can be found sporadically off of mobs, but can also be purchased from specific engineering or mining vendors at s=5 gold each (s=4 gold if ).\r\n# Collect either 1100 Heavy Leather, ''or'' 440 Iron Bar, ''or'' 440 Kingsblood. Heavy Leather is connected to the Skinning profession; Iron Bars are connected to the Mining profession; Kingsblood is connected to the Herbalism profession. The cheapest will probably be Kingsblood, though it will depend on your server, regardless. (You can also collect any variation of these quantities, so long as you meet the specifics of the turn-in.)\r\n# Complete the appropriate turn-in quests until you are . +2750 rep total. (3000 / 3000)\r\n===== Phase 2: 0 / 6000 Friendly =====\r\n# Collect 960&times; Dark Iron Residue. These can be found on the mobs within [[Blackrock Depths]]; they drop from just about anything with an \"Anvilrage\" prefix, as well as from the Bloodhounds, the Blazing Fireguards, etc. These used to go for quite a bit, but after the release of [[World of Warcraft: The Burning Crusade]], their value has dropped tremendously.\r\n# Complete Gaining Acceptance all the way to , at +25 rep each. +6000 rep total. (6000 / 6000)\r\n===== Phase 3: 0 / 12000 Honored =====\r\n# Complete the other six Thorium Brotherhood quests: +250 rep each. (1500 / 12000)\r\n#* JOB OPPORTUNITY: Culling the Competition\r\n#* STOLEN: Smithing Tuyere and Lookout's Spyglass\r\n#* Curse These Fat Fingers\r\n#* Fiery Menace!\r\n#* Incendosaurs Whateverosaur is More Like It\r\n#* WANTED: Overseer Maltorius.\r\n# The rest of the turn-ins must be done to [[Lokhtos Darkbargainer]], at the [[Grim Guzzler]], within [[Blackrock Depths]]. You need to be level 60 to have access to the quests, however. He will take 10&times; Dark Iron Ore (+75 rep each), 2&times; Core Leather (+350 rep each), 1&times; Fiery Core (+500 rep each), 1&times; Lava Core (+500 rep each), and 1&times; Blood of the Mountain (+500 rep each). These are all repeatable, and can be done in any order. Dark Iron Ore can be Mined within Blackrock Depths, but are also sporadically found around Burning Steppes and Searing Gorge. Core Leather are Skinned from mobs in Molten Core. Both Fiery Cores and Lava Cores are drops within Molten Core. Blood of the Mountain can be Mined from nodes in the Blackrock Mountain vicinity.\r\nRinse and repeat to or , as desired.\r\n===Derotain Mudsipper===\r\n[[Derotain Mudsipper]] is located in [[Gadgetzan]]. If your level is high enough (50) and Blacksmithing skill is high enough (265), he will give you the seven recipes for in exchange for multiple stacks of [[Thorium Bar]]s.\r\n* [[Quest:Imperial Plate Belt|Imperial Plate Belt]] (10 bars)\r\n* [[Quest:Imperial Plate Boots|Imperial Plate Boots]] (20 bars)\r\n* [[Quest:Imperial Plate Bracer|Imperial Plate Bracer]] (10 bars)\r\n* [[Quest:Imperial Plate Chest|Imperial Plate Chest]] (30 bars)\r\n* [[Quest:Imperial Plate Helm|Imperial Plate Helm]] (25 bars)\r\n* [[Quest:Imperial Plate Leggings|Imperial Plate Leggings]] (30 bars)\r\n* [[Quest:Imperial Plate Shoulders|Imperial Plate Shoulders]] (10 bars)\r\nThe set gives these bonuses as more pieces are worn:\r\n* 2: +100 Armor.\r\n* 4: +28 Attack Power.\r\n* 6: +18 Stamina.\r\nTo complete all of the Imperial Plate quests, you will need a total of 135 Thorium bars, or 6.75 stacks. No other materials are required for the quests.\r\nYou get 250 Reputation points for agreeing to the exchanges and then 250-500 Reputation points for each plan for a total of 2850 Reputation points.\r\n===Lokhtos Darkbargainer===\r\n[[Lokhtos Darkbargainer]] is found in the [[Blackrock Depths]] bar. You can give him different items to receive faction with the Brotherhood.\r\n* Ten Dark Iron Ores for 75 Reputation Points.\r\n* Two Core Leather for 350 points.\r\n* One Fiery Core for 500 points.\r\n* One Lava Core for 500 points.\r\n* One Blood of the Mountain for 500 points.\r\nIt is recommended that you do the Thorium Point quests first to get to Honored and then the Imperial Plate Armor quests to get partway to Revered before starting these turnins to Lokhtos.\r\nOf the gifts, Dark Iron Ore can be mined in the [[Blackrock Depths]] and [[Molten Core]]. As of patch 1.7 Dark Iron Ore will also occasionally appear in the [[Searing Gorge]] and the [[Burning Steppes]]. The Blood of the Mountain is a rare gem from the same veins. Fiery Core and Lava Core drops in the [[Molten Core]]. Core Leather can be skinned from level 62 Ancient Core Hounds in the Molten Core or as of 1.8 patch [[Magmadar]]. These require [[Skinning]] of 310 or 315 respectively. Without the Burning Crusade expansion, skinning of over 300 is attained via Finkle's Skinner, a dagger which drops in [[Blackrock Spire]] from The Beast, or the Zulian Slicer, a sword which drops in [[Zul'Gurub]] from High Priest Thekal, the Tiger Aspect. Both give +10 skinning. Having the +5 skinning enchant on gloves helps reduce failed chances on Ancient Core Hounds or is required for skinning [[Magmadar]] if you do not have both skinning knives or the Burning Crusade expansion.\r\nAt each new level of faction, Lokhtos offers a new set of recipes. These recipes require some combination of the items you can offer him to gain faction.\r\n====Alchemy Recipes====\r\n* [[Transmute: Elemental Fire]] - Friendly Faction\r\n====Blacksmithing====\r\n* Dark Iron Bracers - Friendly Faction\r\n* Dark Iron Helm - Honored Faction\r\n* Dark Iron Destroyer - Honored Faction\r\n* Dark Iron Reaver - Honored Faction\r\n* Fiery Chain Girdle - Honored Faction\r\n* Black Amnesty - Revered Faction\r\n* Blackfury - Revered Faction\r\n* Fiery Chain Shoulders - Revered Faction\r\n* Dark Iron Gauntlets - Revered Faction\r\n* Dark Iron Leggings - Revered Faction\r\n* Blackguard - Exalted Faction\r\n* Dark Iron Boots - Exalted Faction\r\n* Ebon Hand - Exalted Faction\r\n* Nightfall (axe) - Exalted Faction\r\n* Sulfuron Hammer - Special\r\n====Enchanting Formulas====\r\n* Formula: Enchant Weapon - Strength - Friendly Faction\r\n* Formula: Enchant Weapon - Mighty Spirit - Honored Faction\r\n* Formula: Enchant Weapon - Mighty Intellect - Revered Faction\r\n====Leatherworking Patterns====\r\n* Molten Helm - Friendly Faction\r\n* Corehound Boots - Friendly Faction\r\n* Lava Belt - Honored Faction\r\n* Black Dragonscale Boots - Honored Faction\r\n* Molten Belt - Revered Faction\r\n* Corehound Belt - Revered Faction\r\n* Chromatic Gauntlets - Revered Faction\r\n====Tailoring Patterns====\r\n* Flarecore Gloves - Friendly Faction (8g)\r\n* Flarecore Mantle - Honored Faction (18g)\r\n* Flarecore Robe - Honored Faction (6g)\r\n* Flarecore Leggings - Revered Faction (8g)\r\n===Malyfous Darkhammer===\r\n[[Malyfous Darkhammer]] is another member of the Brotherhood, found in [[Winterspring]]. He gives the quest [[Quest:Fiery Plate Gauntlets|Fiery Plate Gauntlets]]. It isn't known whether more quests with him are unlocked with higher faction, but neither of these quests give Thorium Brotherhood faction [[reputation]].",},
			["Thorium Grenade"] = { content = "This is a [[grenade]]. Stronger than [[Iron Grenade]]s, one is still able to throw these while running.\r\n==Source==\r\nThorium Grenade is created by [[engineering|engineers]] with a minimum skill of 260.\r\nThe components are:\r\n*1 [[Thorium Widget]]\r\n*3 [[Thorium Bar]]s\r\n*3 [[Dense Blasting Powder]]s\r\n*3 [[Runecloth]]\r\n==Shopping List==\r\n*6 [[Thorium Bar]]s (6 [[Thorium Ore]])\r\n*4 [[Runecloth]]\r\n*6 [[Dense Stone]]\r\n==Notes==\r\nThis recipe is now taught by Engineering trainers.\r\nUntil patch 2.2 (estimated), this was a [[limited sale recipe]] sold by\r\n*Gearcutter Cogspinner in [[Ironforge]]\r\n*Sovik in [[Orgrimmar]].",},
			["Thorium Helm"] = { content = "The '''Thorium Helm''' is a plate helmet that provide extra resistance to all magic types.\r\n==Source==\r\nThe '''Thorium Helm''' is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 280.\r\nThe components are:\r\n*24 [[Thorium Bar]]s\r\n*1 [[Star Ruby]]\r\n*4 [[Yellow Power Crystal]]s\r\nThe [[Plans: Thorium Helm|plans]] are a [[World Drop]].",},
			["Thorium Ore"] = { content = "'''Thorium Ore''' is mined from various Thorium [[vein]]s, with a minimum [[mining]] skill of 200.\r\n===Small Thorium Veins===\r\n'''Small Thorium Veins''' can be mined at skill level 200, and produce 1 to 3 '''Thorium Ore'''. These appear in areas where the average mob level is between approximately 45 and 57.\r\nSmall Thorium veins are most commonly found in [[Swamp of Sorrows]], [[Un'Goro Crater]], and [[Winterspring]], but are found elsewhere as well.\r\n===Rich Thorium Veins===\r\n'''Rich Thorium Veins''' can be mined at skill level 200, and produce 3 to 5 '''Thorium Ore'''. These appear in areas of [[Azeroth]] where the average mob level is above approximately 55.\r\nRich Thorium Veins are most commonly found in [[Silithus]], [[Swamp of Sorrows]], [[Un'Goro Crater]] and [[Winterspring]].\r\n===Oozing Thorium Veins===\r\n'''Ooze Covered Rich Thorium Vein''' and '''Ooze Covered Thorium Vein''' are found in [[Silithid]] hives. These are essentially the same as Rich and Small Thorium Veins, respectively, but with a different appearance.\r\nThese veins are most commonly found in [[Silithus]] and [[Un'Goro Crater]].\r\n===Also found in Thorium Veins===\r\n* [[Dense Stone]]\r\n* [[Arcane Crystal]]\r\n* [[Blue Sapphire]]\r\n* [[Star Ruby]]\r\n* [[Azerothian Diamond]]\r\n* [[Huge Emerald]]\r\n* [[Large Opal]]\r\nThese items can be found in all varieties of Thorium Vein.\r\n===Smelting (Mining)===\r\n'''Thorium Ore''' is smelted into [[Thorium Bar]]s at a [[forge]],\r\nrequiring a [[mining]] skill of 200 or more.\r\n[[Thorium Bar]]s are used in the production of many items made by\r\n[[Alchemy]], [[Blacksmithing]], [[Enchanting]], [[Engineering]], and [[Jewelcrafting]].\r\n===Prospecting (Jewelcrafting)===\r\n'''Thorium Ore''' can be prospected (consuming 5 ore) with a [[Jewelcrafting]] skill\r\nof 200 or more, resulting in:\r\n* [[Star Ruby]] (36%)\r\n* [[Large Opal]] (17%)\r\n* [[Azerothian Diamond]] (16%)\r\n* [[Huge Emerald]] (15%)\r\n* [[Flame Spessarite]] (3%)\r\n* [[Blood Garnet]] (1.75%)\r\n* [[Shadow Draenite]] (1%)\r\n* [[Golden Draenite]] (1%)\r\n* [[Azure Moonstone]] (1%)\r\n===Alchemy===\r\n* [[Greater Stoneshield Potion]]\r\n==See also==\r\n*[[Thorium Bar]]",},
			["Thorium Point"] = { content = "'''Thorium Point''' is a small, neutral town in northern [[Searing Gorge]] inhabited by the [[Thorium Brotherhood]]. \r\nThorium Point is the center of operations for the Thorium Brotherhood's enterprise. Located on a mesa on the north side of the [[Searing Gorge]], it is part fortress and part workshop. Though ample resources exist just outside their gates, the Brotherhood keeps a constant vigil against attacks by Dark Iron dwarves, elementals and wild beasts. Despite the high security, Thorium Point is open for business to anyone who can brave the hostile landscape to reach it. The safest way to travel to it is by gryphon.\r\nIt has a flight path and the majority of the quests in the Searing Gorge as well as a couple of vendors. It is located northeast of [[Firewatch Ridge]] and is populated mostly by neutral [[Dark Iron Dwarves]]. It is a critical hub for farming [[Thorium Brotherhood]] reputation.\r\n===Flight===\r\n [[Ironforge]]\r\n [[Stormwind City]]\r\n [[Thelsamar]]\r\n [[Morgan's Vigil]]\r\n [[Kargath]]\r\n [[Flame Crest]]",},
			["Thorium Rifle"] = { content = "==Source==\r\nThe '''Thorium Rifle''' is crafted by [[Engineering|Engineers]] with a minimum skill level of 260.\r\nThe components are:\r\n*2 [[Mithril Tube]]\r\n*2 [[Mithril Casing]]\r\n*2 [[Thorium Widget]]\r\n*4 [[Thorium Bar]]\r\n*1 [[Deadly Scope]]\r\nThe recipe for this item is taught by Schematic: Thorium Rifle, a [[World Drop]] from creatures approximately levels 50-60.",},
			["Thorium Setting"] = { content = "==Source==\r\nRequires [[Jewelcrafting]] (225)\r\nThis item can be aquired through crafting or another combine-type effect.\r\n==Thorium Setting as an ingredient==\r\nThis item is used to make: \r\n* Diamond Focus Ring\r\n* The Aquamarine Ward\r\n* Ruby Pendant of Fire\r\n* Opal Necklace of Impact\r\n* Necklace of the Diamond Tower\r\n* Emerald Lion Ring\r\n* Glowing Thorium Band\r\n* Gem Studded Band\r\n* Red Ring of Destruction\r\n* Simple Opal Ring\r\n* Sapphire Signet\r\n* Sapphire Pendant of Winter Night\r\n* Onslaught Ring\r\n* Ruby Crown of Restoration",},
			["Thorium Shield Spike"] = { content = "The '''Thorium Shield Spike''' is an enhancement for a shield. Any time the user blocks an attack, the shield spike does some damage to the attacker.\r\n==Source==\r\nThe '''Thorium Shield Spike''' is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 275.\r\nThe components are:\r\n*4x Thorium Bar\r\n*4x Dense Grinding Stone\r\n*2x Essence of Earth\r\nPlans: Thorium Shield Spike are a [[World Drop]].\r\n==Notes==\r\n*The Thorium Shield Spike does 20-30 points of damage for every block.\r\nAs of [[Patch_2.4.2]], Blacksmithing is not required to apply the shield spike to a shield.",},
			["Thorium Tube"] = { content = "A '''Thorium Tube''' is created and mostly used by engineers.\r\n==Source==\r\nThe '''Thorium Tube''' is crafted by [[Engineering|Engineers]] with a skill level of 275.\r\nThe components are:\r\n*6 [[Thorium Bar]]s\r\nThe recipe for this item is taught by:\r\n* Buzzek Bracketswing (the [[Master Trainer|Master]] [[Engineering Trainer]] in [[Gadgetzan]], [[Tanaris]])\r\n* any of the [[Grand Master Trainer|Grand Master]] Engineering Trainers in [[Outland]]\r\n==Notes==\r\nHistorically, this recipe had been taught by [[Schematic: Thorium Tube]], a [[limited sale recipe]]. That schematic is no longer available for purchase.\r\n===[[Engineering]]===\r\n*[[Biznicks 247x128 Accurascope]]\r\n*[[Core Marksman Rifle]]\r\n*[[Dark Iron Rifle]]\r\n*[[Flawless Arcanite Rifle]]\r\n*[[Major Recombobulator]]\r\n*[[Masterwork Target Dummy]]\r\n*[[Adamantite Scope]] (as of patch 2.3 it doesn't require a thorium tube to craft)\r\n==Thorium Tube as a quest objective==\r\n*Craftsman's Writ - Thorium Tube",},
			["Thorium Vein"] = { content = "#REDIRECT [[Thorium Ore]]", redirect = "Thorium Ore",},
			["Thorium Widget"] = { content = "A '''Thorium Widget''' is a subcomponent crafted by [[Engineering|Engineers]]. The Widget is then used to create even bigger creations.\r\n==Source==\r\nThe '''Thorium Widget''' is crafted by [[Engineering|Engineers]] with a skill level of 260.\r\nThe components are:\r\n*3 [[Thorium Bar]]s\r\n*1 [[Runecloth]]\r\nThe recipe for this item is taught by:\r\n* Buzzek Bracketswing(the [[Master Trainer|Master]] [[Engineering Trainer]] in [[Gadgetzan]], [[Tanaris]])\r\n* any of the [[Grand Master Trainer|Grand Master]] Engineering Trainers in [[Outland]]\r\n===[[Engineering]]===\r\n*[[Alarm-O-Bot]]\r\n*[[Arcanite Dragonling]]\r\n*[[Dark Iron Bomb]]\r\n*[[Goblin Jumper Cables XL]]\r\n*[[Gyrofreeze Ice Reflector]]\r\n*[[Lifelike Mechanical Toad]]\r\n*[[Masterwork Target Dummy]]\r\n*[[Powerful Seaforium Charge]]\r\n*[[Thorium Grenade]]\r\n*[[Thorium Rifle]]\r\n*[[Tranquil Mechanical Yeti]]\r\n*[[Voice Amplification Modulator]]\r\n*[[World Enlarger]]\r\n==Item Name as a Quest Objective==\r\n*Thorium Widget ([[Darkmoon Faire]])\r\n==Notes==\r\nHistorically, the recipe for this item was taught by [[Schematic: Thorium Widget]], a [[limited sale recipe]].",},
			["Thorium Widget (quest)"] = { content = "==Quest text==\r\n[[Yebb Neblegear]], like me, is working on a future\r\nattraction. So amazing is this attraction, says\r\nNebb, that it will draw folks from across the world...\r\nand it will make us all very, very rich!\r\nHe says he needs thorium widgets for its construction,\r\nand wants me to collect them for him. So what do\r\nyou say, <name>? Do you know where to get Thorium\r\nwidgets? If you're an engineer, can you make them?\r\n Do you want to trade them for Darkmoon Faire tickets? \r\n* Thorium Widget (6)\r\n== Completion==\r\nAh, thank you, <name>! Yebb will enjoy these\r\nwidgets. I don't know what he has planned for them,\r\nbut Yebb's a clever little gnome. He's clever, and\r\nmaybe a little devious....\r\nIf only he liked the taste of humanoid flesh... he'd make\r\na great troll!\r\nHere, <name>. A deal's a deal, and these tickets are yours. \r\n== Reward==\r\n*20x Darkmoon Faire Prize Ticket\r\n*250 [[reputation]] with [[Darkmoon Faire]]\r\n==Notes==\r\nSee [[Darkmoon Faire|Darkmoon Faire Reputation]] for details of this quest's availability.",},
			["Thornby"] = { content = "'''Villager Thornby''' and [[Villager Garth]] offered to help [[Arthas]] fight for [[Lordaeron]] when the Prince passed by in [[Strahnbrad]].\r\n'''Thornby''' become a recruit of [[Kul Tiras]] and escaped the fall of Lordaeron, eventually becoming a Naval Royal Guard under [[Admiral Proudmoore|Proudmore]]. He was stationed outside of [[Vol'jin]]'s new base camp. He was killed by [[Rexxar]], [[Cairne Bloodhoof]], [[Chen Stormstout]] and [[Rokhan]].\r\n''\"We'll fight for Lordaeron! Get your swords!''\"\r\n==Statistics from Warcraft III==\r\n* 1500 HP\r\n* 154-158 normal melee\r\n* 36 heavy armor",},
			["Thornfang Hill"] = { content = "'''Thornfang Hill''' is a nesting ground for [[ravager]]s in [[Hellfire Peninsula]]. It is the pathway from Hellfire to [[Zangarmarsh]]; the [[Cenarion Refuge]] sits right on the edge of Zangarmarsh near this area.",},
			["Thorngrin the Tender"] = { content = "'''Thorngrin the Tender''' is the third [[boss]] of [[The Botanica]] wing of the [[Tempest Keep]] [[instance]] in [[Netherstorm]].\r\n==Summary==\r\n*'''Sacrifice''': Occasionally 'sacrifices' a party member, draining their health over time and healing himself. Can only hit players who are in line of sight, and Thorngrin will not use this ability on his current target (so, unless your tank loses aggro, they will never be Sacrificed). 0.5 sec cast. This ticks for about 750 per second (about 5K total; it is partially resistable via Shadow resistance). Since patch 2.1 this will also teleport the player to Thorngrin's original location and stuns them for the duration of the Sacrifice.\r\n*'''Hellfire''': Channels hellfire at his feet like Baron Geddon, causing 1.3k damage every second. Can be outranged by the tank. Thorngrin does not use his melee attack while channeling this ability.\r\n*'''Enrage''': Occasionally enrages, increasing attack speed by 75% and physical damage by 110%. Thorngrin hits *extremely* hard while Enraged.\r\n==Fight==\r\nBefore engaging Thorngrin, his room must be cleared. There are two pulls of four demons and a Channeler; although it seems like they pull together, you can actually pull the demons separately if you wait until the Channeler walks forward towards Thorngrin (just wait until the buff wears off of them, or you'll be in a world of hurt.)\r\nThere are also two stealthed satyrs who patrol in the next room (as you go towards Laj). They should be killed before fighting Thorngrin, as you can easily aggro them by mistake if they have patrolled close to the boss.\r\n===Abilities===\r\n*'''Sacrifice''': Thorngrin will occasionally 'sacrifice' a party member (very similar to [[Zevrim Thornhoof]] in DM East). This will not target the tank. This teleports the party member up onto the platform where Thorngrin is initially standing, stuns them for 6 seconds, and drains ~750 health per second (giving an equal amount of health to the boss). The stun/drain cannot be dispelled, but you can heal or shield them as normal. Healing range can be a problem; healers might want to stand close to the platform so they can heal anyone who is sacrificed while low on health. Party members should generally bandage themselves or drink a potion after being sacrificed, so the healers can concentrate on the tank. It may be possible to avoid having the healer be sacrificed by positioning them so they are out of LOS of the boss. Note that this ability does Shadow damage, so anything that increases Shadow resistance will help decrease the damage taken.\r\n*'''Hellfire''': Thorngrin will occasionally channel a \"Hellfire\" AoE (very similar to the Warlock spell). This deals ~1500 fire damage per tick in normal mode. It has a HUGE animation, but the actual range of it is not nearly as large, and it is fairly easy to get out of. Melee DPS should move out of range ASAP and bandage up. Your tank can stay in if he/she has lots of HP and/or FR gear and/or Fire Protection potions; it's only 4-5 ticks of damage. On Heroic the tank will probably need to back out as well, unless you have extremely good healing. It is '''VERY''' important for ranged DPS to stop attack as well during the Hellfire, otherwise you are very likely to pull aggro.\r\n*'''Enrage''': Thorngrin will periodically Enrage, becoming very large and glowing red. This increases his melee DPS '''substantially''', and he will probably one-shot any non-plate-wearing party member. Healers will need to spam fast heals, and/or things like Power Word: Shield to keep the tank alive. You will pretty much need maximum HPS (e.g. spammed Flash Heal) to keep the tank up unless you have good gear or multiple healers. Keeping HoTs up on the tank can help. The Enrage only lasts about 8-10 seconds.\r\n===Notes===\r\n*To keep healers out of LOS, place the tank in the middle of the room, and put the healer behind the boxes to the left of Thorngrin's starting position. The healer should be able to see the tank, but will not be in LoS of the boss. With a single healer this may help, since then (in theory) they will never be sacrificed. With multiple healers (even if one is not specced for it) this is rarely a problem.\r\n*Thorngrin is normally tanked in the middle of the room; healers (if not trying to stay out of LOS) should stand between Thorngrin and the raised platform where Sacrifice victims go. This way the healers can reach all party members (if you stand on the other side, Sacrificed members may be out of healing range). Ranged DPS can simply stand on the sides of the room.\r\n*Because Hellfire and Sacrifice both mess up melee DPS, ranged DPS makes the fight substantially easier. However, it is very doable with heavy melee DPS as long as they can avoid taking too much damage during Hellfire casts.\r\n*Hunters: (As of 09/05/08) On normal and heroic mode, Thorngrin is ''not'' immune to viper sting for mana draining. As you can imagine, this makes the fight immensely, immensely easier.\r\n*Aggro can be a problem if your tank does not have enough HP/FR (or your healer does not have enough mana) for the tank to keep meleeing during Hellfire casts. If this is the case, you may need to taunt after he casts Hellfire, or have your ranged DPS not attack while he channels.\r\n*Greater/Major Fire Protection Potions can be helpful for the tank if they intend to stay in for Hellfires. If you drink one and then start the fight when it has about 1m left on its timer, you should have the potion cooldown up in time for the second or third Hellfire.\r\n*Around 250 FR should be enough to let the tank easily stay in during Hellfire, even without extremely good healing. However, be careful not to sacrifice too much Defense/Armor, since Thorngrin hits *extremely* hard during his Enrage phase. Therefore, running out of Hellfire is prefered over staying in it with fire resist gear.\r\n*Another tactic for dealing with Enrage is to kite him -- Mages can Iceblock, or a Hunter can FD when he gets close. However, pulling aggro at the right time can be tricky.\r\n*Apparently, the snakes from a Hunter's Snake Trap can be hit by Sacrifice. Releasing the trap at the right time may enable you to avoid it most of the time (unverified as of patch 2.2.0).\r\n*Warlocks can use Enslave Demon on one of the elite Satyrs in Thorngrin's room, and then use that mob against Thorngrin. These demons deal extremely high damage and can make the fight much easier. This technique is usable in several of the boss fights in Botanica if you move quickly. Note however that in heroic mode they are immune to enslave.\r\n===Alternate LOS Strategy===\r\nThe goal of this strategy is to keep everyone in the party out of line of sight, so that Thorngrin never uses his Sacrifice. Tank should wear DPS and fire resist gear, hybrid classes should go heal mode. Rogues can take a nap. The party stands in the hallway outside the demons' room. The tank pulls Thorngrin up the ramp, positioning him just outside of line of sight, west of the doorway. The tank stands in the doorway, in line of sight of healers. Tank supplies almost all the DPS on this fight; ranged AoE classes can drop AoE in the doorway and hit Thorngrin with it. Just heal through the Hellfires and Enrages.\r\nIf the positioning is right, Thorngrin will occasionally turn to party members and try to cast Sacrifice, but will never be able to.\r\n===Straight Tanking (Heroic)===\r\nThis method works best with 3 ranged DPS. Tank the boss in the middle of the room so his AoE is out of the range of the first step of the stairs where the boss spawned. Have your DPS and healer standing on the step. During the fight the tank need to watch when the boss randomly chooses a party member to Sacrifice. After the sacrifice is started, the boss will randomly aggro on another DPS/healer; that is when the tank needs to use the taunt ability to bring the boss back to the middle of the room before he does his AoE (the tank stays inside the AoE). If the taunt is a bit late, DPS can move back up the boss' stairs a bit to avoid the AoE. Resume original position after AoE. Sacrifice is not a big problem with this method, but requires the tank to be precise on when to use his taunt.\r\n==Quotes==\r\n* Aggro: ''What aggravation is this? You will die!''\r\n* Casting Hellfire: ''Scream while you burn!'' OR ''I'll incinerate you!''\r\n* Some part of the fight: ''I revel in your pain!''\r\n* Some part of the fight: ''You seek a prize, eh? How about death?''\r\n* When casting Sacrifice: ''Your life will be mine!''\r\n* Killing a player: ''I hate to say I told you so...''\r\n* Death: ''You won't... get far.''",},
			["Thorns"] = { content = "'''Thorns''' is a spell that can be learned from druid trainers. It is part of the [[Balance]] line, and grants a buff to friendly targets that causes [[Nature]] damage to attackers. This [[buff]] only affects melee attackers.\r\n==Notes==\r\nThe Druid [[Tier 1]] armor set, [[Cenarion Raiment]], boosts the effectiveness of Thorns. The three piece bonus increases the damage caused by 4 and the duration by 50%.\r\n==Talent improvement==\r\nThe Druid talent [[Brambles]] increases the Nature damage caused by Thorns by X% (maximum 75%).\r\n==Tips and tactics==\r\n* Although this spell doesn't sound too useful, it doesn't cost much mana, and is instant cast. Sometimes, additional damage can help.\r\n* You should probably not cast this on non-melee classes (healer, mage), because the damage caused by thorns does increase aggro, making it harder to pull mobs off the caster. Conversely, you should cast this on melee classes so they can keep aggro and cause additional damage to mobs.\r\n* If cast last Thorns will act as a buffer against PvP anti-magic, e.g. [[Spellsteal]] and [[Purge]].\r\n* The damage caused by it can break skills like [[Hibernate]]. Do not use it if you want to [[crowd control]]. (Note that a Hibernated creature will not attack. However it can reduce [[Entangling Roots]] duration if enemy is able to shoot or someone is in melee.)\r\n* If you or someone in your party has latency of over 500, you may want to avoid using Thorns if you are using any in-combat crowd control such as Hibernate or Polymorph. This is because the mob can deal it's damage before it gets CCed but have the damage reflected after the CC, breaking it.\r\n* This can be useful when being attacked by an enemy that has one/low health (eg. summoned swarmers from a [[Silithid Swarmer]]) as it will kill itself.\r\n==Past changes==\r\n* Spell damage stats do not currently increase Thorns damage. According to Thottbot, +spellDam did have an effect around the BC release, but it was swiftly reduced to zero.",},
			["Thorn Hill"] = { content = "'''Thorn Hill''' is a sizable hill nestled on the north face of a mountain top between the [[Crossroads]] and [[Durotar]]. It is populated by a large number of [[Quilboar]] who have recently been raiding [[Horde]] caravans in the region, and thus have attracted the ire of the local security forces. Thorn Hill is led by the cunning quilboar raider named [[Kreenig Snarlsnout]].",},
			["Thorvald's Camp"] = { content = "'''Thorvald's Camp''' is a [[Vrykul]] camp in [[Howling Fjord]]. It's named after it's leader [[Thorvald]].",},
			["Thorvald"] = { content = "'''Thorvald''' is a level 70 [[Vrykul]] at [[Thorvald's Camp]] in the [[Howling Fjord]].\r\nHe drops Dragonflayer Patriarch's Blood for the quest A Tailor-Made Formula.",},
			["Thor Modan"] = { content = "'''Thor Modan''' is a ruined [[dwarven]] city located in the [[Grizzly Hills]] of [[Northrend]]. The ancient home of the [[iron dwarf|iron dwarves]], the architecture of the area is very similar to the Alliance Dwarven city of Ironforge; even down to the statue of [[Modimus Anvilmar]] at the end of the entrance hallway. Much of the main interior of Thor Modan is in ruins. Iron Dwarves work with severe determination to repair the constant damage that is being done by an army of nature giants who constantly barrage the area with huge boulders and entire trees which have been ripped from the ground. Adventurers who come upon Thor Modan first will see a fierce battle between the Earthen and the Iron Dwarves. The Iron Dwarves are defending the territory and sending powerful stone golems out to engage the marauding Earthen. \r\nThe Earthen are recognised as friendly towards a member of the Alliance and much of the questing that takes place here involves helping with the attack on Thor Modan. As the discerning adventurer delves deeper into Thor Modan, the trappings and belongings can be seen strewn across the landscape. Journal pages and in a few cases - corpses of unfortunate explorers can be seen laid out across the landscape.\r\nAlliance adventurers who quest in this region will assist the Explorer's League in retrieving excavation information from fallen League members who ventured in and never came out. In addition assistance can be given to the earth giant - Kurun - A towering figure of rocks and trees standing on the highest point that looks out over Thor Modan. Kurun and his army of giants is in desperate need of assistance to thwart the Iron Dwarves and their nefarious movements. His battle goes on in the [[Boulder Hills]] area which sits on the rise behind Thor Modan. As well as attacking the Iron from the roof of the structure he is overseeing a ferocious battle between his army and the Iron Dwarves army of [[Runed Giants]].\r\nThe purpose of the [[Ironforge dwarf]] [[Explorer's Guild]] excavations, is spurred by their search for more information on the [[titan]]s and the origin's of their race. \r\n==Excavation==\r\nThe ironforge dwarves once had a little town here used to excavate the site. It looked like it was thrown together (which it was). Mismatched tents stood between rough wooden shacks and the occasional stone hut, and streets veered wherever someone had settled in their path. The expedition leaders slowly corrected the settlement's haphazard construction, replacing the temporary buildings with permanent ones and straightening the paths, but they still had a ways to go. It isn't surprising, since they were more interested in digging for old dwarven relics than in setting up shop. Furbolgs attacked frequently, so the camp had walls put up and a guard in place. That at least gave it some shape.\r\nA small force of dwarves had settled in Thor Modan, midway up the east side of the Grizzly Hills and halfway between Grizzlemaw and Gundrak. They dislike the trolls, who constantly attack them, and hate the Scourge. Any hero from a typical Alliance race receives a warm welcome. Dwarves are greeted like long-lost family. The dwarves here are researchers and archaeologists rather than warriors. They offer\r\nwhatever aid they can, but do not fight unless their homes are threatened. They feed heroes and give them basic supplies, but have little else to share beyond local knowledge and experience fighting ice trolls. These dwarves were noncombative. They lived in Thor Modan and seek clues and artifacts from their own past. They do know shortcuts to Gundrak, however, and can guide the heroes there unseen. \r\n''In World of Warcraft the town is either not shown (world scale issues), or has been packed up recently, the Explorer's Guild presence shows there may have been a dig here at one point. It is likely that they uncovered the ancient dwarven city during their excavation.''",},
			["Thotar"] = { content = "'''Thotar''' is a level 16 [[hunter trainer]] located in [[Razor Hill]] in the [[orcish]] starting zone of [[Durotar]].\r\nHe starts the following quests:\r\n#Taming the Beast (Orc and Troll 1)\r\n#Taming the Beast (Orc and Troll 2)\r\n#Taming the Beast (Orc and Troll 3)\r\n#Training the Beast (Orc and Troll)\r\nSee [[List of Durotar NPCs]].",},
			["Thottbot"] = { content = "'''Thottbot''' was an [[addon]] which automatically saved data from the game — like monster drops, weapon stats, monster spawn locations, and character profile data. The collected data was later uploaded to the website of the same name, , either automatically or manually. The uploaded data available on the site was used for many applications such as finding [[NPC]]s that you need to complete a certain quest, items that you might have to retrieve, or even the drop rate of items from different monsters. Thottbot was owned by Affinity Media through the ZAM Network.\r\nThottbot was drastically changed in December 2010 when ZAM Network decided to \"merge\" it with [[Wowhead]], which is also owned by ZAM. The change consisted of deleting all data on Thottbot, having it load all data from Wowhead instead. This included the deletion of accounts, screenshots, comments, and forums so far posted on Thottbot. In order to post new comments, users will have to sign up an account on Wowhead. \r\nWhile ZAM explained that their goal was to \"improve the data available to the Thottbot community while retaining the Thottbot styling, navigation and community\", the merge has caused Wowhead and Thottbot to technically be the same page with two different names and layouts. Some former users of Thottbot have criticized the merge as having ruined Thottbot, along with general World of Warcraft history, as several years' data was lost in the process.\r\nOn November 16, 2016, Thottbot was discontinued, and for a while, the url would redirect to wowhead.com, before the redirect was taken down aswell.\r\n==In-Game Usage==\r\n/tloc:Toggles x,y coordinates under minimap.\r\n/gcinfo:Toggles AddOn garbage collection info under minimap.\r\n/tsize:Display size of collected Thottbot data.\r\n/tprofile:Collect Thottbot profile.\r\n/tstate:Display current Thottbot settings.\r\n/treset:Reset Thottbot data collection.\r\n/tver:Display Thottbot version.",},
			["Thousand Needles"] = { content = "'''Thousand Needles''' (aka '''The Thousand Needles''') is a huge dry canyon in Southern Kalimdor, filled with towering mesas. In the east, the canyon opens up to the [[Shimmering Flats]], a vast salt pan that is used by Goblin and Gnomish engineers for their races. Despite being relatively barren, the area has its own harsh beauty, and the sunrise seen from either [[Freewind Post]] or one of the mesas around [[Darkcloud Pinnacle]] can be spectacular. The [[Shimmering Flats]] and [[Mirage Raceway]] are also worth visiting for their surreal, lonely atmosphere.\r\nAlthough as a [[contested]] territory this area doesn't see anywhere near as much action as some, [[Darkcloud Pinnacle]] is a favorite stealth ganking spot for [[Alliance]] rogues due to the many Horde quests there as well as the relative difficulty of the mobs/remoteness of that location. The [[Alliance]] also tend to attack the [[Great Lift]] and [[Freewind Post]] fairly regularly. In addition, players questing on the [[Shimmering Flats]] near the Tanaris border are advised to look over their shoulder from time to time, as the unwary can occasionally find themselves being stabbed in the back by a passing member of the opposing faction.\r\n==History==\r\nBefore the great Sundering, the region of Thousand Needles was a river canyon, the spires of sandstone shaped from years of rushing water. Water flowed to the sea from a large lake to the east, fed by an underground tributary. Then came the demons and the destruction that threw the entire world into upheaval. The canyon was thrust above the water table; the eastern lake dried into a vast salt flat and Thousand Needles became a sandy gorge. Thousand Needles rises south of [[Dustwallow Marsh]] and serves as a channel to [[Desolace]] to the west or the [[Tanaris]] Desert to the South. It also connects to [[Feralas]]. The long canyon stands as a natural divide between central and southern [[Kalimdor]]. The realm gets its name from the dozens of giant, cylindrical columns of sandstone that rise from the bottom of the canyon like a forest. Bridges have been constructed atop many of the spires, connecting pathways across the canyon from one side of the surrounding mountains to the other. To the east of Thousand Needles, the canyon opens into a large, dry lakebed. This dried-out salt flat is actually below sea level. At its center stands an alkaline lake with ten times the salt of any ocean. The sere region is so hot, dry and salty that few creatures venture here. Lizards, scorpions, vultures, and birds of prey are not uncommon and neither are centaur war bands. A contingent of goblins mines for oil in the [[Scorched Basin]]. The spire bridges allow travelers to traverse the canyon without running into the barbaric centaur who patrol the canyon floor. The bridges are not entirely safe, however, as birds of prey will attack the unwary. Larger birds have even sabotaged the bridges from time to time. There is very little of interest in this land, unless someone has a passion for salt or sandstone... or oil.\r\nThe barren canyons of Thousand Needles have traditionally been the territory of several [[Tauren]] tribes. The Tauren were forced to live precariously on the tips of the high mesas in order to avoid the large tribes of [[Centaur]] that almost wiped them out. Now, with the help of the [[Horde]], the tauren are fighting back against their enemies, including the fanatical [[Grimtotem]] Tribe. The [[Shimmering Flats]] to the southeast are also the home of the world famous Mirage Racetrack, where [[gnome]]s and [[goblin]]s race their respective rocket cars in order to permanently settle the question of which race has better engineering.\r\nIt is suspected that ages ago Thousand Needles was once a small inland sea, or perhaps even an inlet of the Great Sea. This explains the salt flat as well as why there are so many \"needle\"-like mesas (once possibly islands). The cause for the sea's evaporation could be attributed to the sundering, which tore the ancient Kalimdor cleanly in two. A catastrophe such as this could easily have caused climate change.\r\nAnother theory states that a river with its source in [[Feralas|Feralas]], possibly [[Wildwind Lake]], flowed into the area that would become Thousand Needles. The river cut through the earth, carving the canyon and shaping the dramatic pinnacles that became the Thousand Needles. It was a verdant, forested land. The river emptied into a large inland sea in the east. When the [[Great Sundering]] occurred, the course of the river was altered and ceased to flow through what would become Thousand Needles. The forests died and the fertile soil became orange dust. The inland sea, without its source of water, evaporated, leaving behind a vast salt flat.\r\nIt has also been thought by [[Falfindel Waywarder]] of [[Thalanaar]] that dark magic of some kind blighted the land.\r\n==Getting there==\r\nAlliance:Alliance characters will first reach Thousand Needles from the north. The traveler can either take a boat to [[Theramore Isle]] in [[Dustwallow Marsh|Dustwallow Marsh]] or flying to [[Mudsprocket]], run west to the [[Barrens]], then south to the [[Great Lift]] (avoiding its Horde guards) and into Thousand Needles; or head south from [[Ratchet]] in the [[Barrens|Barrens]] (Ratchet can be reached either by boat from [[Booty Bay]] or by running south from [[Ashenvale|Ashenvale]]). The route from Theramore or Mudsprocket is faster but much more dangerous, as [[Dustwallow Marsh|Dustwallow Marsh]] is a 35-45 level zone.\r\nHorde:From [[Camp Taurajo]] in the [[Barrens|Barrens]], head south along the road to the [[Great Lift]] and down into Thousand Needles.\r\n==Geography==\r\nThousand Needles contains no dungeons, raid dungeons, micro dungeons, or battlegrounds.\r\n===Travel hubs===\r\nThere is only one flight path in Thousand Needles, and that is Horde-aligned [[Freewind Post]]. However, Alliance travelers can use the nearby [[Thalanaar]] flight path to the west, and the flight path in neutral [[Gadgetzan]] to the south to navigate the zone.\r\n==== [[Flight path]]s from [[Freewind Post]]====\r\n* [[Thunder Bluff]]\r\n* [[The Crossroads]], [[Barrens|The Barrens]]\r\n* [[Camp Taurajo]], [[Barrens|The Barrens]]\r\n* [[Camp Mojache]], [[Feralas|Feralas]]\r\n* [[Gadgetzan]], [[Tanaris|Tanaris]]\r\n==Notable characters==\r\nThe Thousand Needles are home to several characters of note. At Freewind Post, [[Cliffwatcher Longhorn]] seeks aid in the battle against the evil Grimtotem Clan. At the Weathered Nook, [[Dorn Plainstalker]] attempts to teach members of the Horde about Faith, Endurance, and Strength. And at the Mirage Raceway, [[Kravel Koalbeard]] sends bold adventurers around the world in search items that will give him personal gain in his bets at the gnome and goblin races.\r\n==Quests==\r\nHorde quests in Thousand Needles begin around level 25 and go through level 35. Neutral quests at the [[Shimmering Flats]] begin around level 30 and continue to level 35. Some of the neutral quests that send players out of the zone continue all the way up to level 45. Notable quest chains include and , both neutral and available at the [[Mirage Raceway]].\r\n==Resources==\r\n* [[Herb]]s\r\n** [[Bruiseweed]]\r\n** [[Wild Steelbloom]]\r\n** [[Kingsblood]]\r\n* [[Ore]]\r\n** [[Copper Vein]]\r\n** [[Tin Vein]]\r\n** [[Silver Vein]]\r\n** [[Iron Deposit]]\r\n** [[Gold Vein]]\r\n** [[Ooze Covered Gold Vein]]\r\n** [[Mithril Deposit]]\r\n** [[Ooze Covered Mithril Deposit]]\r\n** [[Truesilver Deposit]]\r\n==Wild creatures==\r\n* [[Air elemental]]s\r\n* [[Basilisk]]s\r\n* [[Carrion bird]]s\r\n* [[Centaur]]s\r\n* [[Cougar]]s\r\n* [[Dog]]s\r\n* [[Earth elemental]]s\r\n* [[Harpies]]\r\n* [[Hyena]]s\r\n* [[Kobold]]s\r\n* [[Scorpid]]s\r\n* [[Silithid]]\r\n* [[Turtle]]s\r\n* [[Water elemental]]s\r\n* [[Wind Serpent]]s\r\n* [[Wyvern]]s\r\n==Notes==\r\n*You can't race on the Mirage Raceway.\r\n*[[Shimmering Flats]] mobs have an oddly high rate of dropping blue BoE (lvl 20-27) gear, though this rate seems to only go as high as .5%.",},
			["Thrag Stonehoof"] = { content = "'''Thrag Stonehoof''' is a level 24 npc located on [[Lower Rise]] in the [[tauren]] city of [[Thunder Bluff]].\r\nBefore patch 2.3, he was a [[journeyman]] [[blacksmithing trainer]].",},
			["Thrall"] = { content = "'''Thrall''' (Birthname '''Go'el'''), son of [[Durotan]] (born 2 years [[Dark Portal|ADP]]), is the [[Warchief]] of the restored shamanistic [[Horde]], and ruler of the red land of [[Durotar]] in [[Kalimdor]]. In [[World of Warcraft]], he is a level ?? (Boss) faction leader located in [[Grommash Hold]] in the [[Valley of Wisdom]], in the [[orcish]] city of [[Orgrimmar]], and inside the dungeon of [[Durnholde Keep]] in the [[Old Hillsbrad Foothills]] instance. He can also occasionally be found at the [[Mag'har]] stronghold of [[Garadar]] in [[Nagrand]].\r\nHe is voiced by Harlan Hogan in Warcraft III.\r\nFrom his position in Orgrimmar, he starts the following quests:\r\n* Hidden Enemies\r\n* Hidden Enemies\r\n* Hidden Enemies (Dungeon)\r\n* Hidden Enemies\r\n* 21\r\n* The Eastern Kingdoms\r\n* What the Wind Carries\r\n* The Champion of the Horde\r\n* The Lord of Blackrock\r\n* For All To See\r\n* For the Horde! (Dungeon)\r\n* The Royal Rescue (Dungeon)\r\n* Hero of the Mag'har.\r\nIn the [[Old Hillsbrad Foothills]] instance, he starts the quest Escape from Durnholde (Dungeon).\r\nSee [[List of Orgrimmar NPCs]].\r\n===Youth===\r\nThrall is the son of Durotan, former chieftain of the [[Frostwolf Clan]], and [[Draka]]. Thrall was found amongst the bloody bodies of his murdered parents by [[Aedelas Blackmoore]], commander of the [[internment camp]]s which held orcs after the end of the [[Second War]]. Blackmoore returned to his fortress, [[Durnholde Keep]], with Thrall, and raised him as a gladiator — with all the savagery of an orc, but with the keen strategic intellect of a human. He was trained and taught by many, wet-nursed by [[Clannia|a human woman]], and grew to befriend her daughter, [[Taretha Foxton]]. Thrall proved to be an excellent student and a phenomenal fighter. He was clever, quick and enormous even by orc standards. However Blackmoore's abusive beatings both in and out of the ring began to take its toll. Taretha began to write him letters and secretly delivered them to him in his cage within books, and he wrote back to her. Eventually, he wrote to Taretha that he wished to escape.\r\nTaretha created a diversion inside Durnholde Keep which allowed Thrall to escape from his cell unnoticed. They met up outside the fortress by a cave, and Taretha gave him provisions and supplies. He then left Durnholde, hoping to never return.\r\nHowever, Thrall was captured and taken to an internment camp run by one Major [[Lorin Remka]]. It was here that he met an old orc with glowing red eyes named [[Kelgar]], who told him of the corruption of [[Gul'dan]], and how the old ways had been so much better for the [[Horde]]. He told him that the only one still thinking of embracing this was the undefeated [[Grom Hellscream]], Chieftain of the [[Warsong|Warsong Clan]]. When another orc told Thrall that Blackmoore had arrived at the camp looking for him, Thrall escaped again, and sought out Grom Hellscream.\r\n===The Orcs===\r\nAfter finding the chieftain and proving himself, Hellscream took Thrall under his wing, teaching him the Orcish tongue, and telling him that—based on the tattered swaddling cloth Thrall showed him — he was a part of the exiled [[Frostwolf Clan]]. After spending some time with Hellscream, Thrall decided to take his leave of them for a while in order to search out his roots in the [[Alterac Mountains]].\r\nAfter trekking to exhaustion, Thrall was rescued by the Frostwolves and taken to their camp. There he met [[Drek'Thar]], who told Thrall that he was the son of the chieftain of the Frostwolves. After finding his place among the Frostwolves, Drek'Thar taught Thrall the old ways of the Horde, before [[Gul'dan]]'s corruption, and soon Thrall was accepted as a member of the clan. A frost wolf named [[Snowsong]] eventually chose Thrall as her companion. It was some time after that choosing that he was called away by Drek'Thar, and came upon a quiet place where he had never been or seen before. Here he was to be initiated.\r\nIn one of the most spiritual experiences of his life, Thrall befriended the spirits of Earth, Air, Fire, Water, and the Wilds. He became the first new shaman since Gul'dan's vile corruption of the Horde. He returned to the camp a new orc and became fully immersed in the old ways of the shaman and his clan, embracing his role as son of the chieftain. This was a significant and symbolic event, since Thrall was the first shaman to be accepted by the spirits since Drek'Thar's time. Not only did this mean Thrall would be destined to be one of the greatest shamans in orcish history, but it also meant that the spirits finally forgave the orcish race for consorting with demonic powers, and deemed Thrall as the first of a brand new generation of shamans.\r\nThe camp was soon visited by a wandering stranger. At first, Thrall spoke pleasantly with him, but began to grow angry when the stranger accused the Frostwolves of hiding away in the mountains. His fury — and orcish pride — growing within him, Thrall informed the stranger that he would join with Hellscream and the Warsong and lay siege to the encampments. The stranger dismissed Hellscream as a \"demon-ridden dreamer\", and said that the humans were not worth fighting. Enraged, Thrall challenged the stranger to single combat. The stranger threw aside his cloak to reveal well-worn black plate armor and a massive warhammer. After a short but brutal contest, Thrall managed to disarm him, but was prevented from throttling the stranger by some of his clan. It was then that the stranger revealed himself as [[Orgrim Doomhammer]] — the Warchief of the Horde. Doomhammer had been contacted by Drek'Thar about the return of the son of Durotan. The Warchief decided to provoke Thrall into a fight to see if Drek'Thar's praise was deserved — and it was. Not only was Thrall able to challenge Doomhammer's strength, he also was able to best him — a feat only once before accomplished...by Thrall's father.\r\n===Liberation===\r\nDoomhammer named Thrall his second-in-command and explained his strategy for liberating the encampments. Per Doomhammer's plan, Thrall infiltrated the camps masquerading as one of the downtrodden, lethargic prisoners, and then riled the orcs up with shows of his shamanistic powers. With the downtrodden orcs revitalized by their restored heritage, they quickly overran the encampments. On the first three encampments, this proved to be an effective tactic. On the fourth, Thrall was too easily recognized, and thus they had to resort to the numbers of the new Horde — and the shamanistic powers wielded by Thrall — to liberate the encampment. At the fifth, however, they were even better prepared — knights from Durnholde had been stationed at the remaining encampments, so that whichever camp they attacked, there would be a greater resistance. During the liberation of this encampment—now the Horde outpost of [[Hammerfall]] in the [[Arathi Highlands]] — Doomhammer was killed, impaled from behind by a knight's lance. With his dying breath, he gave Thrall his black plate and warhammer, and named him Warchief of the Horde.\r\nThrall's first action as Warchief was to attack [[Durnholde]] in an effort to dismantle the entire internment camp system. He secretly met with Taretha, asking her to leave Durnholde with her family, but she refused, hoping that it would never come to battle and fearful of the consequences if Blackmoore noticed her missing (Blackmoore had taken her as his mistress, an arrangement she had never been happy with). When Thrall arrived at Durnholde with the Horde at his back, he confronted a drunken Blackmoore, and asked for a peaceful parlay in order to prevent useless bloodshed. Blackmoore went through a plethora of emotions — from amusement at Thrall's rise to power, anger at what the Warchief was demanding, and grief at how Thrall had supposedly betrayed him. Once again demanding that Blackmoore surrender or be killed, the master of Durnholde gave his response...by tossing the severed head of Taretha Foxton into the courtyard, screaming that this was what he would do with traitors.\r\nThrall screamed in rage and grief, the elements themselves echoing his fury, and he gave the command to attack. During the siege, Thrall cornered Blackmoore in his hidden tunnel, and tossed a sword at the traitorous man's feet. Blackmoore had sobered enough to hold his own against the Warchief — who had been holding back to allow Blackmoore a fighting chance — but when he tried to explain, and asked for Thrall's aid to help him subjugate the Alliance, the Warchief's rage at Taretha's fate broke all barriers, and he struck the mortal blow. As he lay dying, the master of Durnholde expressed pride in what Thrall had become — what Blackmoore had made him...or so he thought.\r\nThrall emerged shaken from the castle to find his orcs victorious. Thrall gave a message to Blackmoore's second-in-command, [[Karramyn Langston|Lord Karramyn Langston]], to take to his superiors: to free the remaining orcs, and to cede land for their use. If the Alliance would let them be, they would not trouble the Alliance and would be willing to engage in cooperation and trade. If the Alliance chose to fight them, they would have made an enemy the likes of which had never been seen before — making the old warlock-controlled Horde shrink to insignificance. He then left Durnholde after allowing [[Sergeant]] and the surviving humans to walk away unharmed. When they were gone he called upon the Spirit of the Earth to destroy the keep, before leading his people to freedom.\r\nThrall later composed a ''[[lok'vadnod]]'' (\"song of a hero\") to commemorate Taretha's sacrifice.\r\n===Flight to Kalimdor===\r\nThrall and Grom spent much time gathering together the dispersed forces of the Horde. But it was some time later, when Thrall was with a small force in the [[Arathi Highlands]], that he received a strange dream. He saw armies clashing, and fire raining from the sky, and a voice warning him of things to come.\r\nWhen he awoke, he realized that it was no dream, it was a vision, granted him by the [[Medivh|mysterious Prophet]], who enigmatically told him that he was not what he seemed, that he had abandoned his humanity long ago, and that the only hope for the orcs was to leave [[Lordaeron]]—sail west to [[Kalimdor]], and there, they would find their destiny.\r\nThrall obeyed, and gathering the Horde, prepared to make their way across the Great Sea. However, Grom turned out to have been captured by humans, and Thrall quickly stepped in to save him. Hellscream then got the idea to steal the human ships so that they could leave the human lands forever. With the Horde assembled, they stole the ships, and left across the Great Sea to Kalimdor.\r\n===Exodus of the Horde===\r\nHalfway along their journey to [[Kalimdor]], Thrall's ships were beset by a fierce storm near the [[Maelstrom]] and forced to take shelter on a small island. There the orcs met the troll leader [[Sen'jin]], who told them of a [[murloc]] tribe and a [[human]] outpost that attacked his tribe night and day on the island. Fearing for the Horde and the Darkspear Trolls' safety, Thrall and his warriors assaulted the human base, only to discover that the archmage in charge was stationed there to keep the murlocs at bay. While the orcish and human forces were occupied with one another, the piscine monsters sought out sacrifices for their rituals.\r\nThrall was then imprisoned within the murlocs' fiery dungeon. He learned from a troll head hunter, with whom he shared a cell, that the murlocs planned to sacrifice them both to a sea witch. Fortunately, though the murlocs were strangely advanced, they were unaware of Thrall's shamanistic abilities, and the warchief is able to escape and free his warriors. The Trolls, however, report that Sen'jin was not in the cells — he was taken as the first sacrifice. Thrall raced to the altar, but was forced to watch in horror as the murloc sorcerer killed Sen'jin. Thrall and his warriors were able to kill the three [[Murloc Guardian]]s maintaining the magic barrier which prevented their escape, but it was too late for the troll leader. The dying Sen'jin revealed a vision — that Thrall would lead the [[Darkspear]] tribe to greatness. Thrall then offered the remaining trolls a place in the [[Horde]] for the kindness they had shown the orcs.\r\nThrall emerged from the cave and was confronted by the [[Ghost Sea Witch]]. She threatened vengeance for the destruction of her altar and worshipers. She placed a curse upon the warchief; that he and all his forces would be swallowed up by the sea. Upon returning to his base camp, Thrall discovered that his ships, damaged by the storm, were not yet ready to sail. He also learned that the island was volcanic and that the dormant volcano was about to erupt. The Sea Witch, meanwhile, launched her murloc forces against the Horde, thirsty for vengeance. Nevertheless, aided by the trolls, the Horde was able to hold off their attackers long enough to repair their ships and managed to escape before the volcano erupted.\r\n''The sea witch's curse may have come true, depending on how close her island was to Kalimdor — we know that Thrall's force was shipwrecked. We assume that the other clans, such as [[Warsong Clan|Hellscream's]], were not among those caught by the storm and driven to the island.''\r\n===Kalimdor===\r\nThe ships had been scattered and many of those on board barely made it to the shores of Kalimdor alive. The clans were scattered, and Thrall slowly roamed the coast, collecting the orcs and trolls he came across as he did. But Grom could not be found. This new land held many strange new creatures, but the most brutal were the [[centaur]]s, particularly in their treatment of the [[tauren]].\r\nWhen Thrall battled a group of centaurs who were attacking tauren, he was unexpectedly greeted by [[Cairne Bloodhoof]], chieftain of the [[Bloodhoof Tribe]]. Impressed by their fierce but noble behaviour, Cairne offered to help him find the destiny of his people. Thrall told Cairne of the centaur army he had seen advancing to the north, and they quickly departed, as Cairne reported that his village was in danger. Thrall's forces followed Cairne back to their village, where they defended it from the centaurs.\r\nSince the centaurs had driven off all the game in the region, the Bloodhoof Tribe would need to abandon their home and travel to [[Mulgore]] if they hoped to avoid starving. Cairne agreed to tell the location of the Oracle, who would help the orcs with their quest for destiny, if they would help protect Cairne's caravan to Mulgore. Thrall agreed to these terms, and helped the tauren on their lengthy journey, protecting them and their lumbering [[kodo]] beasts from marauding centaurs.\r\nCairne told Thrall of the mystical Oracle of [[Stonetalon Peak]], who could help them find their destiny in these strange lands. Thrall, glad at having made a new friend in the foreign land, thanked Cairne gratefully, and they parted as allies.\r\nWhen Thrall arrived at the base of Stonetalon Peak, he was shocked to find Grom Hellscream and the Warsong Clan battling humans under the command of [[Jaina Proudmoore]]. Her forces had cordoned off much of the pass going up the mountain, and Thrall suspected that hiring some [[goblin]]s to ferry them up the mountain in zeppelins would allow them to bypass any defenses. However, as Thrall tried to make his way stealthily up to the goblins, an impatient Hellscream unexpectedly attacked the humans, who retaliated by attacking Thrall's forces. Thrall was forced to stay their wrath by attacking their bases. Finally, he managed to acquire the zeppelins. Thrall confronted Grom, but Hellscream argued that \"a true warrior\" would have fought the humans without question instead of trying to sneak past them and avoid a battle.\r\nThrall, worried that Grom's impetuous bloodlust would lead to nothing but trouble, ordered his friend and his clan to remain behind in [[Ashenvale]] as Thrall journeyed up the mountain. Grom reluctantly agreed.\r\nThrall made his way up the mountain, and was surprised to find his path crossing that of Cairne once again. However, Thrall would not be able to access the summit without any air support. So, Cairne suggested that they ally with the [[wyvern]]s of Stonetalon. The wyverns were under the control of vile [[harpies]], and after a short battle, they were defeated, and the wyverns, grateful, lent their services to Thrall and the Horde. With their help, Thrall [[Where Wyverns Dare|defeated]] the humans guarding the Peak, and entered the mountain.\r\nThrall and Cairne separated and searched the caverns themselves. After much time, they found the Oracle's chamber, but they also found Jaina Proudmoore, and were about to battle when the Oracle appeared, revealing himself to be the Prophet Thrall and Jaina had met in Lordaeron. He told Thrall of Grom's corruption, and that the orcs and humans must join forces or be destroyed. Reluctantly, Thrall agreed, desperate to save Grom.\r\n===Lifting of the Blood Curse===\r\nThey returned to [[the Barrens]] to find Grom in command of the corrupted [[Warsong Clan]], and he moved against them as the demonic invasion of Kalimdor began. An epic battle took place between the Warchief and Hellscream's forces, with many warriors being struck down in the ensuing clash. Thrall, with the help of Cairne, managed to fight his way through the corrupted orcs and stood before the Warsong Chieftain. Hellscream taunted Thrall, telling him that the demons didn't forcefully corrupt the orcs, but that the orc chieftains themselves chose to drink the demon's blood. Filled with rage and anger at this betrayal, Thrall charged at his old friend and the two had a fierce one on one duel. After a long and desperate struggle, Thrall managed to capture Grom's essence in a [[Soul Gem]] and returned it to a Ritual Circle, where with the combination of orc and human magic, the demons were purged from Grom's system. Grom, realizing what he had done, was instantly apologetic, and he and Thrall immediately set out to face Mannoroth in the canyon carved by the falling infernals.\r\nThrall put an initial assault against [[Mannoroth]], but was subdued quickly, and would have been killed, had Grom not gathered his strength and made a devastating blow against Mannoroth, shattering his plate and driving an axe deep into his belly. This was enough to kill the pit lord, but as Mannoroth died explosive energies burst forth from his body and hit Grom at point blank range. The chieftain of the Warsong Clan was mortally wounded. As the demonic, red haze lifted from the eyes of Grom Hellscream and his clan mates, .\r\n===Battle of Mount Hyjal===\r\nThrall and Jaina retreated back into Ashenvale, but found a new threat behind them as well as in front. The night elves, cursing them for the killing of [[Cenarius]], attacked them as they attempted to make a new settlement.\r\nThe demons and undead, orcs and humans, and night elves were all battling one another for survival, until finally, Thrall received a vision to bring Jaina to a grove at the base of [[Mount Hyjal]]. There, he met the leaders of the Sentinels, [[Tyrande Whisperwind]] and [[Malfurion Stormrage]]. They were surprised at finding each other there, until the Prophet appeared once more, and revealed himself to be Medivh, the Last Guardian. He convinced them that they must all ally against the Legion or they would surely and quickly be defeated.\r\nThough uneasy, Tyrande and Malfurion agreed, and they all allied against [[Archimonde]] and his plethora of demonic and undead followers.\r\nThe three races collectively defended [[Nordrassil]] and Mount Hyjal with three fortified settlements going up the mountain, doing their best to slow Archimonde's ascend until the night elves' trap was prepared. \r\nAs Archimonde made his way up the mountain towards Thrall's base, he told Thrall that his race wasn't worth bothering with. Thrall replied by saying that all that mattered now was that his people were free, and struck out, dealing damage to Archimonde, before Jaina spirited him away.\r\n===Founding of Orgrimmar===\r\nFollowing the victory at Mount Hyjal and the defeat of the Burning Legion, Thrall gathered his people and resolved to find a place for them in the rugged, beautiful lands of the Barrens. He founded [[Durotar]], named after his heroic father. Its capital city was [[Orgrimmar]], named for [[Orgrim Doomhammer]]. After many months, things began to pull together. The orcs were fleshing out Durotar, the tauren had gone into [[Mulgore]], and the [[troll]]s had settled on the [[Echo Isles]] off the coast, as well as a small village on the Durotar mainland, named Sen'Jin in honor of their lost leader.\r\nThrall was soon met by [[Rexxar]], a son of the [[Mok'Nathal]], who had tried to save his scout [[Mogrin]] from a group of [[quilboar]]s, and delivered a message. Thrall read it carefully, saddened by Mogrin's death, and welcomed Rexxar to the newly crowned land. Rexxar considered staying, but said that he would need to earn his keep. Thrall agreed, and sent Rexxar to speak to various citizens of Orgrimmar and see what he could do to assist them in their tasks. He also asked [[Rokhan]] the [[shadow hunter]] to assist Rexxar. The two were later joined by a wandering [[pandaren]] brewmaster named [[Chen Stormstout]], who had been searching the area for ingredients to use in his new concoction. After Rexxar helped him find those ingredients, Chen tagged along with the troll and the Mok'Nathal, eager for adventure. Thrall waited in Orgrimmar, helping build the city.\r\nRexxar performed his deeds successfully, and Thrall began to respect the beastmaster. But soon he brought ill news that humans were amassing on the shores of Durotar. Thrall was troubled. The treaty he had made with Jaina had hoped to keep such incursions from happening. After several more encounters with human hostiles, there was a summit arranged between Thrall and Jaina. Rexxar encouraged Thrall to send him in his place, sensing a trap. Thrall reluctantly agreed. Sure enough, the \"emissaries\" were uninterested in talk and unsuccessfully tried to kill Rexxar and his friends, after expressing disappointment that Thrall himself had not come to be slaughtered.\r\nRexxar returned and told Thrall that there had been a deception. Unable to believe that Jaina would order such a thing, Thrall prepared a note for Rexxar to secret into Theramore to arrange a parlay with Jaina herself. Only by meeting face to face could they ensure any sort of peace between the two races.\r\nAfter hearing Rexxar's report of [[Admiral Proudmoore]]'s arrival and intent against the orcs, Thrall realized that the only way to prevent yet another war was to assault Admiral Proudmoore's base and kill him. With Rexxar's help, Thrall enlisted the aid of his old friend Cairne and the tauren, as well as the [[Stonemaul]] ogres. While preparations were being made to storm Theramore, Thrall was informed that the island was surrounded by a blockade of ships that the assembled force had no way of breaching. Thrall was frustrated by this news. Then Jaina teleported onto the scene. She assured everybody that she came in peace. She had known nothing of her father's plans and didn't know what to do, she said. Thrall was sympathetic, but told her that her father's actions could destroy Durotar and that the only way to ensure the security of the new nation and his people was to kill Daelin.\r\nJaina understood and was willing to help, even if it meant the death of her father. She told Thrall the location of a nearby goblin shipyard which could supply him with ships to break through the admiral's blockade. He begged Thrall to spare as many of her men as possible in the coming battle; even though most of them were following her father, they were the only family she had left after the fall of Lordaeron. Thrall gave her his word that he would try to keep bloodshed on the human side to a minimum and advised Jaina to get to safety, since the battle was about to start.\r\nUsing the ships acquired from the goblins, Thrall's forces were able to fight their way onto the isle, where they proceeded to engage Daelin Proudmoore's troops. Rexxar, Rokhan, Chen and Cairne fought their way directly to Admiral Proudmoore himself and engaged him in combat. Before the battle was over Thrall tried to tell the admiral that this Horde was different from the one he had faced years ago, that they had no interest in conquest or murder. Proudmoore raged that Thrall's race was guilty of genocide, that they would never be able to atone for their rampage through Stormwind and Lordaeron that had left countless people dead. He grimly vowed that he would never stop fighting the orcs, and thus Rexxar was forced to kill him as Thrall had predicted.\r\nAs soon as Daelin Proudmoore fell, Rexxar shouted that the battle was over and ordered the human forces to stand down. They complied. Jaina fell to her knees near her father's body, asking him why he couldn't have listened. Rexxar tried to ease the sorceress' pain by telling her that her father was a proud warrior above all else, and that he should be remembered as such. Thrall proclaimed that the Horde had no quarrel with the surviving humans and that they would leave Theramore in peace. He then took his forces back to Durotar and left Jaina to her mourning.\r\nGrateful to Rexxar for all he had done, Thrall extended an invitation to the Mok'Nathal to stay and make a home for himself in Durotar. Rexxar politely declined, telling Thrall that he was a wanderer and his place was in the wilds. But he promised Thrall that he was part of the Horde, and that if his help was ever needed again he would be there. So Thrall said goodbye to Rexxar and resumed building Durotar. For the moment, all was well.\r\n===Cycle of Hatred===\r\nThree years passed, and Orgrimmar swelled. However, a series of minor incidents between the Durotar orcs and Theramore humans threatened the stability of the entire area. Thrall and Jaina desperately attempted to keep the peace, but the Horde grew out of his control when his chief warrior [[Burx]] took an army of orcs and trolls to [[Northwatch Hold]], the same keep Proudmoore used for his operations, and demanded they dismantle it. After the battle began, however, Jaina contacted Thrall with information that his Burx was working for the orcish end of the [[Burning Blade]] cult. Infuriated at the idea that an orc would once again serve the Legion (the demon [[Zmodlor]] was pulling the strings of the cult), Thrall immediately stopped the battle (with some impressive aid from the Spirits) and denounced Burx. When the warrior protested that he was acting within the Horde's interests, Thrall smashed his skull with the Doomhammer. \r\nThe events prompted Jaina and Thrall to pursue a more official Horde/Alliance treaty. Despite the rise of tensions in the last year or so, their actions have halted, though not completely broken, the cycle of hatred.\r\nThrall currently resides in his palace, located in the Valley of Wisdom in Orgrimmar. Despite the defeat of the Burning Legion and the elder Proudmoore, the Warchief's life is still far from dull. Threats to Durotar from outside and within force him to remain ever vigilant.\r\n===Return to Draenor===\r\nA faction of orcs exists in Outland, who remained untouched by demonic corruption. These orcs call themselves the [[Mag'har]], and are comprised of various orcish clans who chose not to join Magtheridon's legion of fel orcs, and appear to have been completely unaffected by the corruption wrought by Kil'jaeden. Upon hearing of them, Thrall immediately made plans to journey to Outland and make contact with the Mag'har. However his advisors urged Thrall to make the proper preparations, instead of leaving Orgrimmar and the rest of the orcs on Azeroth open to attack. \r\nLater on, Thrall makes a brief appearance in Outland for a quest chain to meet his grandmother [[Geyah]] and show [[Garrosh Hellscream]] his father Grom died a hero's death, and ended the [[Blood Curse]]. During this meeting, [[Greatmother Geyah]] reveals Thrall's birth name: Go'el, son of Durotan — rightful chieftain of the Frostwolves.\r\n==Personality==\r\nDespite Thrall’s open acceptance of visitors into his society, the orcs have not yet relinquished all of their old hatreds and preconceptions about other races. Still, they honor his leadership and will treat visitors to Durotar fairly, albeit somewhat roughly. He takes individuals at face value and treats them with respect until their actions prove that they should be dealt with otherwise. Even when crimes are committed, the harshest punishment that Thrall will mete out is exile — banishment into the almost lifeless wastelands of the Barrens, where the elements judge who lives and who dies.\r\nTo friends, Thrall is warm and generous, freely swapping stories and information. Hospitality is extended to everyone, but Thrall expects all visitors to contribute in some way to Orgrimmar’s survival. Visiting hunters often bring meat or fur in exchange for refuge from the elements, and human traders from Theramore Isle periodically bring casks of salt ale and seed for crops. While in Orgrimmar, visitors are under Thrall’s protection and he will not tolerate any threats or violence against them.\r\n==Combat==\r\nThrall is a natural-born leader. He is rarely alone, and in battle often spends much of his time directing his troops. In solo combat his tactics are subtle. He mixes a judicious amount of melee with powerful spellcasting.\r\n==Thrall's orcish name==\r\n\"Go'el\" was the name chosen by Durotan and Draka for their only son, but they could not give him that name until the Naming Day of that cycle; when Durotan and Draka were killed, his name remained unknown to him until he met his grandmother in Garadar over two decades later. \r\n''The name Go'el in Hebrew is derived from the verb gaal, \"to redeem\". A Go'el was a close Kinsman, whose duty was to perform any task a man could not perform by himself. Another duty of the Go'el was to redeem his kinsman from slavery — appropriate, considering Thrall's role in liberating and redeeming the orcs from generations of enslavement to fel magics, as well as being held in human internment camps.''\r\n==Relationship with Jaina Proudmoore==\r\nAfter Jaina and Thrall's forces were forced to work together after the meeting with Medivh, the two leaders soon became good friends. Thrall stated that Jaina reminds him strongly of [[Taretha Foxton]], but Jaina has stated no specific reason for her trust in Thrall. Their relationship is nonetheless strong, even having endured the battle of Durotar, which cost Jaina her father and Thrall many of his warriors. They still consider each other allies. Some fans have speculated that Thrall and Jaina were (or will be) romantically involved at some point, but lore usually denies this.\r\nThe [[White Punch Card]] that drops in [[Gnomeregan]] for the [[Quest:Data Rescue|Data Rescue]] Alliance quest has many lines of binary code printed on it. When decoded, it reads \"Thrall and Jaina sitting in a tree, K-I-S-S-I-N-G\", as in-joke for the fans.\r\n==Legacy==\r\nThe [[Thrallmar]] outpost on the [[Hellfire Peninsula]] in [[Outland]] is named after the Warchief. It is the Horde's staging area to recolonize the orcs' former native planet. Although few individuals will remember their planet before it exploded (Drek'Thar, for example, told the Mok'Nathal Rexxar that he fought alongside other Mok'Nathal on Draenor), all orcs will be shocked to see the state in which it lies now.\r\n==Strategy==\r\nThe most critical part of the strategy is to give the Horde as little warning as possible. Mainly since Horde players tend to feel more obligated and passionate about defending Thrall than any other WoW leader. The slightest mention of an attack on Thrall is enough to send a fair number of players to his side. Diverting attention can be done either by using a warlock to summon, or if you are careful, gathering across the bridge west of Orgrimmar, then riding to Thrall's room at full speed. Once there, use area effect spells to take care of the guards, then a simple tank and spank strategy on Thrall. Vol'jin may be offtanked at the same time, or Thrall can be taken down first by approaching from the left side of the room as you enter and Vol'jin may be optionally taken care of afterwards. Two raids (80 people) are recommended.\r\nHe can be done easily with a 40 man raid if done right. With a well geared 40 man raid group of 70s you can drop him easily if summoned in and done without alerting many Horde.\r\n===Quotes in lore===\r\n* \"We don't go do stupid things when somebody yells ‘For the Horde!’\"\r\n* \"The beginning of wisdom is the statement 'I do not know.' The person who cannot make that statement is one who will never learn anything. And I have prided myself on my ability to learn.\"\r\n* \"[[Blackmoore]] gave me the name so I would never forget that I was something he owned, that I belonged to him. I never will. I will keep the name, and one day, when I see him again, he will be the one who remembers what he did to me, and regret it with all his heart.\"\r\n* \"[[Blackmoore]]! Tonight you sleep in hell!\" — [[Warcraft Adventures: Lord of the Clans]] trailer\r\n* \"How easily the mind can be turned to hate from a place of fear - an instinctive, natural, protective response. Instead of focusing on the things that unite us, we focus on what divides us.\"\r\n* \"To pretend it [the demonic corruption] did not exist is to forget how dreadful the impact was. To make ourselves into victims, rather than claiming our participation in our own destruction. We chose this path, we orcs. We chose it right up until it was too late to turn back. And having made that choice, we can, with the knowledge that we have of the end of that dark and shameful road, choose ''not'' to take it.\"\r\n* \"I can only pray to the ancestors that I am never placed in the same position as [[Durotan|my father]]—torn between what I know in my heart is right and the defense of my people. It is why I continue to strive to uphold the tenuous peace between us and the [[Alliance]]. Because few offenses and insults in this or any other world are sufficient to warrant the slaughter of children.\"\r\n* \"I offer no judgment on anyone save a handful of individuals who knew full well what they were doing, knew that they were trading the lives and destiny of their people for gratification in the moment, and did so gleefully. For the others...I can only shake my head and be grateful that I was not forced to make the choices they did.\"\r\n* \"When I reached adulthood, I became [[Orgrim Doomhammer|Orgrim]]'s friend, as had [[Durotan|my father]] before; and it is I who have fulfilled the prophecy of the Doomhammer. In their honor, this land is named [[Durotar]], its greatest city, [[Orgrimmar]].\"\r\n* ''[After the battle with [[Mannoroth]], just before [[Grom Hellscream]]'s death.]''\r\n*:Grom: \"Thrall, the blood haze has lifted..., the demons fire has burned out in my veins. I have freed myself...\"\r\n*:Thrall: \"No, old friend. You have freed us all.\"\r\n* Our spirit is stronger than you know [[Archimonde|demon]]! If we are to fall, then so be it! At least now.. [[orcs|we]] are free!\r\n==See also==\r\n* Book ''Warcraft: [[Lord of the Clans]]'', by Christie Golden.\r\n* [[Warcraft III: Reign of Chaos]] demo, \"Exodus of the Horde.\"\r\n* [[Warcraft III: Reign of Chaos]]\r\n* [[Warcraft III: The Frozen Throne]]",},
			["Thrallmar"] = { content = "'''Thrallmar''' is an eponymous [[Horde]] town found in [[Hellfire Peninsula]], [[Outland]]. It was founded and now led by [[Nazgrel]], commander of [[Thrall]]'s security, as an opportunity to gain resources and to have a decent control over what's going on in this demon-infested area. The residents of the town form a faction of its own; reputation is raised by performing quests for them. These quests generally involve killing [[fel orc]]s in [[Hellfire Citadel]].\r\n===Flight===\r\n [[Falcon Watch]]\r\n [[Spinebreaker Post]]\r\n [[Stonebreaker Hold]]\r\n [[The Stair of Destiny]]\r\n==[[Reputation]]==\r\nReputation for Thrallmar up to Honored is relatively easy to earn. Even the easiest quests (those that take you from one quest giver to the next up the road, for example) can yield 75 reputation points, while those that require some effort to complete typically yield 250 reputation points or more. Some group quests that involve killing an elite can yield as much as 1000 reputation points.\r\nIf you do the bulk of the Thrallmar quests instead of quickly moving on to the next zone, you might expect to reach Honored after 1 or 2 levels of play. However, once you reach Honored, you hit an earnings barrier that you can only remove when you are level 68 and can start re-earning points in the [[Shattered Halls]] dungeon.\r\n===[[Neutral]] through [[Friendly]]===\r\nReputation from mobs in [[Hellfire Ramparts]] and [[Blood Furnace]] stops at 5999/6000 Friendly, one point shy of Honored. One option is to grind mob rep via Ramparts and Blood Furnace to 5999/6000, before doing any Thrallmar quests outside the instances, as those continue to yield reputation up to exalted.\r\nAlso, the lvl 63 mobs outside Hellfire Citadel (on the path) and the Bleeding Hollow Necrolytes at Zeth'gor give you 5 rep each, but not beyond Friendly.\r\n===[[Friendly]] through [[Honored]]===\r\nPlayers who enjoy PvP can gain faction halfway through Honored via the daily quest Hellfire Fortifications. It gives 150 reputation per completion and three [[Mark of Thrallmar|Marks of Thrallmar]], which can be used to purchase PvP gear from the quartermasters in Thrallmar and near [[Zabra'jin]] in [[Zangarmarsh]]. To start this quest you need to have done 2 prereq quests however. Also with patch 2.1 this quest can only be done once every 24 hours.\r\n===[[Honored]] to [[Revered]] and [[Exalted]]===\r\nFrom this point on, gaining reputation through Exalted requires one of two things: \r\n* Access to [[Shattered Halls]], one of the wings of [[Hellfire Citadel]], which requires level 68 and a at least one group member to have completed the key quest.\r\n* Doing [[Heroic]] versions of [[Hellfire Citadel]] dungeons, which typically require you to be well geared and level 70.\r\nBoth of these give reputation until you reach Exalted status. A full clear of [[Shattered Halls]] nets you about 1700 reputation points, trash mobs generally yield 6 or 12 each, with up to 150 points from bosses. Heroic trash yields 15-25 points, with bosses worth more.\r\nYou can also continue to do the daily quest Hellfire Fortifications for 150 reputation per completion. While at level 70 the quest giver in Thrallmar does not show the yellow exclamation mark and the quest appears gray, you can in fact continue doing it for reputation.\r\n===Maximizing Shattered Halls Runs===\r\nUsing [[Thrallmar Favor]], which are purchased with five [[Marks of Thrallmar]] PvP tokens can reduce the number of [[Shattered Halls]] runs required. Consuming one right when [[Grand Warlock Nethekurse]] is about to die will allow a decent speed group to go through to the end boss with the buff active. Doing this can net 3000 reputation points per run if you kill all of the trash without wiping.\r\n===Repeatable Quest===\r\nHellfire Fortifications (Horde) is a [[Daily quest|daily PvP quest]] given by Battlecryer Blackeye in Thrallmar:\r\n* Available at level 58 if you are at least Neutral with Thrallmar. You must complete the Felspark Ravine quest chain until you meet with Commander To'arch. After completing the quest where you meet with To'arch, you may see Battlecryer Blackeye and obtain the Hellfire Fortifications quest.\r\n* Yields 150 reputation points, repeatable every 24 hours 80 silver , 1650 XP (4950 XP @ 60), and 3x Mark of Thrallmar per turn-in.\r\n* Objective: Capture [[the Overlook]], [[the Stadium]] and [[Broken Hill]], three fortifications surrounding [[Hellfire Citadel]].\r\n===Reputation grinding===\r\nKilling the [[Shattered_Hand_Clan|Shattered Hand]] [[fel orc]]s around the Citadel yields 5 points of reputation per kill until 2999 of 3000 at Neutral status. After that, run the instances ([[Hellfire Ramparts]]/[[Blood Furnace]]) until 5999/6000 at Friendly status. Repeat Hellfire Fortifications until you are maxed at 6000/12000(576 turn-ins. *See Notes above) (this method is now deprecated due to the new patch) then turn in all the quests you've saved up to this point and complete the newly unlocked quests. All the quests for the Hellfire Peninsula region total about 10k in rep. \r\n* [[Hellfire Ramparts]]: elite mobs reward 5 points, non-elites reward 2 each, bosses each reward 50 points. Stops at 5999 of 6000 at friendly reputation status.\r\n* [[Blood Furnace]]: elite mobs reward 5 points, non-elites just 1, bosses each reward 50 reputation points. Stops at 5999 of 6000 at friendly reputation status.\r\n* Quartermaster Urgronn is a level 62 Thrallmar faction [[vendor]] located at [[Thrallmar]] in the [[contested]] territory of [[Hellfire Peninsula]]. He offers several valuable recipes for [[Thrallmar]] faction increases.\r\n==Rewards==\r\nSee [[List of Hellfire Peninsula NPCs]].\r\n===Thrallmar Inn===\r\nThe Thrallmar Inn features a mailbox outside; and a handful of vendors and profession trainers: \r\n* Floyd Pinkus\r\n* Baxter (Cooking Trainer) \r\n* Kalaen\r\n* Reagan Mancuso\r\n* Dalinna\r\n===Town Square===\r\n* Barley, on the left side of the inn\r\n* Barim Spilthoof, Right outside the inn in a tent – sells Leatherworking supplies\r\n* Moorutu, Right outside the inn in a tent\r\n* Battlecryer Blackeye Hellfire Peninsula PvP quest giver and PvP Rewards Vendor\r\n* Megzeg Nukklebust, quest giver, in the middle of the town\r\n* Zebig, somewhat in the middle of the town – sells engineering supplies\r\n* Far Seer Regulkut, stands near the Tauren totem\r\n* General Krakork, near the flight master, patrols in front of the line of grunts, purpose unknown\r\n* Martik Tor'seldori, in the middle of the town, seems to be leading the group of 6 Blood Elf pilgrims bound for Falcon Watch\r\n* Watch Commander Krunk , in the middle of the town, patrols in front of the catapults that the peons work on\r\n* Guard Captain Cragtar, in the middle of the town by the bonfire watching over the 4 injured grunts\r\n===Thrallmar Stronghold===\r\n* Quartermaster Urgronn, right outside the Stronghold\r\n* Krugosh, right outside the Stronghold\r\n* Nazgrel\r\n* Magister Bloodhawk\r\n* Caza'rez\r\n* Stone Guard Stok'ton\r\n* Shadow Hunter Ty'jin\r\n* Vurtok Axebreaker\r\n===Stables===\r\n* Huntsman Torf Angerhoof\r\n* Cookie One-Eye\r\n===Forge===\r\n* Rohok, Repairs equipment and sells Blacksmithing supplies\r\n===Alchemy Tower===\r\n* Apothecary Antonivich, sells Alchemy supplies as well as Reagents, ground floor\r\n* Ruak Stronghorn, ground floor\r\n* Felannia, second floor\r\n* Angela “The Claw” Kestrel, top floor\r\n* Jir'see, top floor\r\n===Thrallmar Mine===\r\n* Foreman Razelcraz\r\n===Outside the wall===\r\n* Sergeant Shatterskull\r\n* Arcanist Torseldori, leads the 5 Bloodmages that defend the town\r\nIn the town, there are 70 Thrallmar Grunts, Marksmen and Bat Rider Guards protecting the town.\r\nThere are also 12 Thrallmar Peons doing various tasks such as working at the blacksmith, repairing wagons and catapults or shifting through supplies.\r\n==Flight Paths==\r\nThrallmar's flight paths connect to: \r\n* [[The Stair of Destiny]] (flight point immediately inside Outland; a quest at this Flight Path brings traveler to Thrallmar for the first time) \r\n* [[Spinebreaker Ridge]], Hellfire Peninsula\r\n* [[Falcon Watch]], Hellfire Peninsula\r\n* [[Stonebreaker Hold]], Terokkar Forest\r\nIt should be noted that you have this flight path by default. You do not need to talk to the Flight Master to obtain it.\r\n==Quests==\r\n* Primed Key Mold (250 reputation)\r\n** Grand Master Rohok (25 reputation)\r\n** Rohok's Request (250 reputation)\r\n*** Hotter than Hell (350 reputation)",},
			["Thrallmar Favor"] = { content = "==Source==\r\nThis item can be purchased for mt=5 gold from Battlecryer Blackeye in [[Hellfire Peninsula]].",},
			["Thrashtail Basilisk"] = { content = "'''Thrashtail Basilisk''' can be found in [[Stranglethorn Vale]] .\r\n==Drops == \r\n \r\n0.10% Chance of a [[rare]] drop.\r\n1.56% Chance of an [[Uncommon]] drop.\r\n0.05% Chance of a [[common]] drop.\r\n0.05% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Threat"] = { content = "'''Threat''' is a measure of an NPC's aggression towards a player. Each NPC has a threat table, and the character at the top of the list is usually the target of its aggression. In-game, this is known as having [[Aggro]] from that particular NPC. The NPC will attack that character if possible, unless another character manages to change the NPC's target. See the [[Aggro]] page for more information on how this targeting behaves.\r\n==Changes to Threat Levels==\r\nSeveral abilities and effects increase a character's threat level against a mob. Note that the effective amount of threat generated can be modified by talents and spells. See the Threat Tables below for details.\r\nBasic NPC attacks do not modify threat; a character being attacked is neither gaining nor losing threat from it. However, some NPCs have special moves that affect threat.\r\nThreat measurements are normalized so that 1 point of damage generates 1 point of threat.\r\nMany abilities generate additional threat that is not tied to their effect (damage dealt, buffs, debuffs). The bonus threat values are listed below.\r\nThreat caused by beneficial effects is divided amongst all NPCs that are aware of the character. This global threat applies to heals, bonus threat from buffs (such as [[Battle Shout]] or [[Arcane Brilliance]]), and power gains (such as a [[Mana Potion]] or [[Rage Potion]]).\r\nHealing threat is global, and is normally .5x of the amount healed. Healing effects cause no threat if the target is already at full health.\r\nExample: Player 1 is involved in combat with 5 mobs. Player 2 (priest) heals Player 1 for 1000 health, and has no threat reduction talents. A 1000 heal generates 500 threat, however that 500 threat is split amongst the 5 mobs. Each of the 5 mobs now has 100 threat towards Player 2.\r\nIf a power gain (Rage/Mana increase) shows up in the combat log, the effect usually counts as a buff with bonus threat attached to the event. There are no Energy-increasing effects that appear to cause bonus threat. Normal power regen does not generate threat. Normal health regen also does not generate threat.\r\nFor debuffs and attacks, any bonus threat is divided amongst the affected targets. For example, the bonus threat of [[Cleave]] is divided between the 2 targets of the attack, while the bonus threat of [[Sunder Armor]] is applied directly to the target of the attack. Some attacks (such as [[Thunder Clap]] and [[Searing Pain]]) have a threat multiplier instead of a bonus threat value.\r\n==Threat Tables per Class==\r\nThreat auras persist, and affect the threat of abilities that are used while the auras are active. Threat Modifying Abilities directly change the level of threat. For abilities that generate both damage threat and bonus threat, only the bonus is shown.\r\n==Stacked Threat Auras==\r\nThreat Auras stack in a multiplicative fashion. A common but wrong assumption is that due to this mechanic, threat reduction effects provide less benefit the more a player has; in fact, threat reduction is always equally powerful, no matter how much a player has.\r\nExample: You are a Paladin casting a heal (.5x healing done). For healing, Paladins also have an innate threat reduction (.5x). Consider that Righteous Fury is active (1.9x threat generated on Holy spells), which also means the game considers you in tanking mode (1.43x on all actions):\r\nYour healing threat would be: .5 * .5 * 1.9 * 1.43 = .679x healing done.\r\n==Known bugs==\r\nSome threat reduction abilities are also affected by threat reducing auras.\r\nExample: Rogues have .71x threat as an innate ability. Feint reduces threat by -800. However, the innate threat reduction affects feint, which causes it to remove only 568 threat.\r\n==Additional notes==\r\n* Being noticed by an aggressive NPC does not generate any threat. This behavior places that character on the NPC's threat list, but with a threat value of 0.\r\n* Threat doesn't decay (passively degenerate over time) unless a specific encounter is designed that way.\r\n* A character's threat level is reset if the character leaves combat with the mob (dies, moves far enough away).\r\n* A character's threat level cannot be negative.",},
			["Threat Cap"] = { content = "#REDIRECT [[Threat cap]]", redirect = "Threat cap",},
			["Threat list"] = { content = "==Threat List==\r\nMobs have [[threat]] lists, also known as hate lists. This is a list of all the characters that have angered the mob, ordered from the one with the largest amount of threat down to the least. Generally speaking, if a mob kills the player with the most threat (at the top of the list), it will then move to attack the next on the list. \r\nThe person the mob attacks is the person with [[aggro]]. Though in theory we would say that the player with the most [[threat]] will also have [[aggro]], in practice it is a bit more fuzzy. \r\nIn groups, the actions each player takes with respect to the mob will move them up or down the threat list. However, the other members of the group are also moving up or down the threat list, so even if you perform no actions your relative position on the list may change.\r\nThings that move the player up the threat list:\r\n* Damage dealt \r\n* Aggro-gaining skills and abilities such as [[Sunder Armor]] and [[Warrior Taunt|Taunt]] \r\n* Healing a player on the threat list\r\nThings that move the player down the threat list:\r\n* [[Druid]] [[Druid:Cower|Cower]] ability\r\n* [[Rogue]] [[Feint]] ability\r\n* [[Priest]] [[Fade]] ability\r\n* [[Rogue]] [[Vanish]] ability\r\n* [[Hunter]] [[Disengage]] ability\r\n* [[Warlock]] [[Soulshatter]] ability\r\n* [[Mage]] [[Invisibility]] ability (during the 5-second fading)\r\n* Some Mobs spells or debuffs such as [[Onyxia]] Knock Away ability.\r\nThings that remove the player from the threat list completely:\r\n* Running far enough away (if not in an [[instance]])\r\n* [[Hunter]] [[Feign Death]] ability\r\n* [[Mage]] [[Invisibility]] ability (after the 5-second fading)\r\n* The [[Paladin]] ability [[Divine Intervention]]\r\n* The [[Night Elf]] [[Shadowmeld]] racial trait\r\nNOTE: [[Divine Shield]] and [[Blessing of Protection]] do not remove threat. They render you immune to attacks, causing NPCs to cease attacking you for the duration of the effect.\r\n* Some mob spells or debuffs such as [[Chromaggus|Chromaguss's]] Time Lapse debuff\r\n* Death\r\nFor more detailed insights and analysis, refer to [[Formulas:Aggro]].",},
			["Three Corners"] = { content = "'''Three Corners''' is a crossroads just inside [[Redridge Mountains]]. The crossroads is patrolled by a lone [[Stormwind]] guard, Guard Parks. The crossroads splits three ways and leads to the \"Three Shires\". It runs west into [[Elwynn Forest]] to [[Goldshire]], east to [[Lakeshire]], and south into [[Duskwood]] to [[Darkshire]].",},
			["Three Kings of Flame"] = { content = "==Task==\r\n'''Gather the [[Incendicite of Incendius]], the [[Ember of Emberseer]] and the [[Cinder of Cynders]], along with a [[Hallowed Brazier]], and return them to [[Bodley]] inside [[Blackrock Mountain]].'''\r\n''In order to summon Lord Valthalak we're first going to need to gather the other two-thirds of the amulet. To do that we need to get a brazier and some special coals to burn in it.''\r\n''There are three nobles of fire, [[Lord Incendius]] in [[Blackrock Depths]], [[Pyroguard Emberseer]] in [[Blackrock Spire]] and the [[Duke of Cynders]] in [[Silithus]], with what we need. Collect from each a piece of their remains, and then return to me with a Hallowed Brazier, which can be purchased from the [[Argent Dawn]] if you are honored by them.''\r\n==Quest Chain==\r\n*[[Quest:Bodley's Unfortunate Fate|Bodley's Unfortunate Fate]]: [[Quest:Bodley's Unfortunate Fate (Alliance)|Alliance]]/[[Quest:Bodley's Unfortunate Fate (Horde)|Horde]]\r\n**'''Three Kings of Flame'''\r\n**[[Quest:Components of Importance|Components of Importance]]: [[Quest:Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Left Piece of Lord Valthalak's Amulet|The Left Piece of Lord Valthalak's Amulet]]: [[Quest:The Left Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]]/[[Quest:The Left Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:I See Alcaz Island In Your Future...|I See Alcaz Island In Your Future...]]\r\n**[[Quest:More Components of Importance|More Components of Importance]]: [[Quest:More Components of Importance (Tyr's Hand)|Tyr's Hand]]/[[Quest:More Components of Importance (Purgation Isle)|Purgation Isle]]/[[Quest:More Components of Importance (Hive'Regal)|Hive'Regal]]/[[Quest:More Components of Importance (Frostwhisper Gorge)|Frostwhisper Gorge]]\r\n**[[Quest:The Right Piece of Lord Valthalak's Amulet|The Right Piece of Lord Valthalak's Amulet]]: [[Quest:The Right Piece of Lord Valthalak's Amulet (Stratholme)|Stratholme]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Scholomance)|Scholomance]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Lower Blackrock Spire)|Lower Blackrock Spire]]/[[Quest:The Right Piece of Lord Valthalak's Amulet (Dire Maul)|Dire Maul]]\r\n**[[Quest:Final Preparations|Final Preparations]]\r\n**[[Quest:Mea Culpa, Lord Valthalak|Mea Culpa, Lord Valthalak]]\r\n***[[Quest:Return to Bodley|Return to Bodley]]\r\n***[[Quest:Back to the Beginning|Back to the Beginning]]: [[Quest:Back to the Beginning (Alliance)|Alliance]]/[[Quest:Back to the Beginning (Horde)|Horde]]\r\n***[[Quest:Saving the Best for Last|Saving the Best for Last]]: [[Quest:Saving the Best for Last (Alliance)|Alliance]]/[[Quest:Saving the Best for Last (Horde)|Horde]]\r\n==Notes==\r\n*This is the second step in the quest chain to upgrade your [[Dungeon Set 1]] Helm and Chestpiece into [[Dungeon Set 2]].\r\n*Lord Incendius and Pyroguard Emberseer spawn in Blackrock Depths and Upper Blackrock Spire respectively.\r\n*The Duke of Cynders will be more difficult to find. You will need to be wearing a set of [[Twilight Trappings]], have a [[Twilight Cultist Medallion of Station]], and then touch a [[Wind stone]]. You will have a 1 in 4 chance of getting the [[Duke of Cynders]]. The Duke is a level 62 elite.\r\n*An alternative way of summoning the Duke is to combine a [[Scroll: Create Signet of Beckoning (Fire)]], 1 [[Dark Rune]], and 5 [[Firebloom]] to create a [[Signet of Beckoning: Fire]]. Use this item at a [[Wind stone]] to specifically summon the [[Duke of Cynders]]. In order to the scroll, you will need to turn in [[Encrypted Twilight Text]]s to [[Hermit Ortell]] who will send you something in the mail. The item he send could be the scroll.\r\n----\r\nGo to [[Quests]]",},
			["Three Virtues"] = { content = "#REDIRECT [[Church of the Holy Light]]", redirect = "Church of the Holy Light",},
			["Threggil"] = { content = "'''Threggil''' is a level 6 [[rare mob]] [[grell]] who runs around water in the western section of [[Fel Rock]] in [[Teldrassil]]. He is on a 1-2 hour respawn timer.\r\n==Loot==\r\n*Keen Machete",},
			["Threshadon"] = { content = "A '''Threshadon''' (aka Thresher) is a large, long-necked aquatic reptile that can only [[Swim|swim]]. Found in [[Darkshore]], the [[Wailing Caverns]], [[Loch Modan]], [[Lake Everstill]], and more. There is a threshadon [[boss]] named [[Nessy]] hiding in the underwater section of the [[Deeprun Tram]].\r\nIn [[Blackfathom Deeps]], there is a threshadon [[mini-boss]] named [[Old Serra'kis]] that you can defeat.\r\n==Notable threshadons==\r\n*[[Isha Awak]]\r\n*[[Old Serra'kis]]\r\n*[[Nessy]]\r\n==Common threshadons==\r\n*[[Darkshore Thresher]]\r\n*[[Deep Pool Threshfin]]\r\n*[[Deep Sea Threshadon]]\r\n*[[Deviate Lurker]]\r\n*[[Elder Darkshore Thresher]]\r\n*[[Elder Murk Thresher]]\r\n*[[Lake Thresher]]\r\n*[[Murk Thresher]]\r\n*[[Young Murk Thresher]]\r\n*[[Young Threshadon]]\r\nNote that [[Bloodpetal Thresher]]s are [[lasher]]s, not threshadons.\r\n==Threshadon-related items==\r\n*Bands of Serra'kis\r\n*Bite of Serra'kis\r\n*Glowing Thresher Cape\r\n*Piece of Threshadon Carcass\r\n*Preserved Threshadon Meat\r\n*Thresher Eye\r\n*Threshadon Ambergris\r\n*Threshadon Fang\r\n==Inspiration==\r\nThe Threshadon is similiar to the .",},
			["Thresher"] = { content = "#REDIRECT [[Threshadon]]", redirect = "Threshadon",},
			["Thresher Eye"] = { content = "==Source==\r\nThis item drops from:\r\n* [[Darkshore Thresher]] in [[Darkshore]]\r\n* [[Elder Darkshore Thresher]] in [[Darkshore]]",},
			["Throk'Feroth"] = { content = "'''Throk'Feroth''' was an [[Orc]] [[farseer]] of the [[Blackrock Clan]] and commander of the [[Blackrock Raiders]] who defended the demon gate which the lich [[Kel'Thuzad]] used to commune with the demon lord [[Archimonde]]. [[Arthas]] and [[Kel'Thuzad]] killed him along with four other Orcs guarding the demon gate.",},
			["Throne of Kil'jaeden"] = { content = "The '''Throne of Kil'jaeden''' is a massive mountain located north of the Horde outpost of [[Thrallmar]] on [[Outland]]'s [[Hellfire Peninsula]]. The mountain was so named by the warlock [[Gul'dan]]. Shortly before the opening of the [[Dark Portal]], Gul'dan called the [[orc]] clans to the mountain to drink the [[Blood of Mannoroth|blood]] of [[Mannoroth]], thus enslaving them to the [[Burning Legion]]'s will. Now that [[Kazzak the Supreme|Lord Kazzak]] has re-opened the [[Dark Portal]], he will be found at this location (as [[Doom Lord Kazzak (tactics)|Doom Lord Kazzak]]), and notably much stronger than before. The location is only accessible by flying mount, and it is not recommended for anyone without at least a small group to venture here, for the elite [[demon]]s roaming the area are almost as challenging as their leader, Doom Lord Kazzak. After the presumed defeat of [[Kael'thas Sunstrider]], his [[Blood Elf]] forces were led through a portal here to the [[Isle of Quel'Danas]]. The highest ranking of these forces were allowed to consume demon blood, becoming the first [[felblood elf|Felblood Elves]]. Some remain at the throne and continue to consume demonic energy.\r\n==2.4 Changes==\r\nThe Throne of Kil'jaeden became a daily quest location for the [[Shattered Sun Offensive]], and the mobs were changed. There are now many [[felblood elf|felblood elves]] siphoning the life forces of suspended [[Terrorguard]]s, as well as wandering [[Wrath Herald]]s and [[Incandescent Fel Spark]]s.",},
			["Throne of the Elements"] = { content = "The '''Throne of the Elements''' is a neutral quest hub in [[Nagrand]]. Quests are available from various [[Humanoid|humanoids]] and [[Elemental|elementals]], who are affiliated with the [[Earthen Ring]]. There are four [[Elemental|elementals]] there, [[Gordawg|Gordawg]], [[Incineratus|Incineratus]], [[Kalandrios|Kalandrios]] and [[Aborius|Aborius]].\r\nCurrently, only [[Gordawg|Gordawg]] is involved in any quests, though [[Incineratus]] is mentioned in two.\r\nIt should be noted that, although in Contested Territory, The Throne of the Elements is not a place that one would want to engage in PvP combat. Should you attack another player while there, the Elemental Lords will immediately engage and attack you. They have been known to deal over 500,000 damage with one hit.\r\nLocation 60,22.\r\n==Quests==\r\n* A Rare Bean\r\n** Agitated Spirits of Skysong\r\n** Blessing of Incineratus\r\n** The Spirit Polluted\r\n* Muck Diving\r\n* The Underneath\r\n** The Tortured Earth\r\n** Eating Damnation\r\n** Shattering the Veil\r\n*** Gurok the Usurper",},
			["Throne room"] = { content = "The '''Throne Room''' of [[Stormwind]] is located inside [[Stormwind Keep]]. It is the main hall of the keep and grants access to the [[War Room]] behind it, which contains all the [[battlemasters]] and Grand Admiral [[Jes-Tereth]]. The Throne Room itself is where the King of Stormwind, [[Anduin Wrynn]], resides. Because of his still very young age, he is assisted in his rule by [[Highlord Bolvar Fordragon]] and [[Lady Katrana Prestor]], who hold the actual power in Stormwind. \r\nIn ''[[World of Warcraft: Wrath of the Lich King|Wrath of the Lich King]]'', the physical throne now stands in Stormwind Keep, and as of build 8905 [[Varian Wrynn]], the missing King and father of Anduin, now stands before it.",},
			["Through the Dark Portal"] = { content = "The '''second''' normal World of Warcraft TCG set, named '''Through the Dark Portal'''.\r\nA storm rages in the Blasted Lands as evil stirs within the Dark Portal. Bloodshed in Azeroth intensifies as the Blood Elves and Draenei join the frey. Already, the great conflict spills over into the other world... the Burning Legion looks on and plots its next move. Grab your weapons and make ready, the darkness is upon us!\r\n===Card Totals===\r\nTotal Cards: 340 (319 + 3 + 18)\r\n* 319 Numbered Cards\r\n** 120 <font class=\"qc-common\">Commons</font>\r\n** 103 <font class=\"qc-uncommon\">Uncommons</font>\r\n*** Including 18 <font class=\"qc-uncommon\">Heroes</font>\r\n** 80 <font class=\"qc-rare\">Rares</font>\r\n** 16 <font class=\"qc-epic\">Epics</font>\r\n* 3 <font color=\"#FF0000\">'''Loot Cards'''</font>\r\n* 18 Oversized <font class=\"qc-uncommon\">Heroes</font>\r\n===Card Numbering===\r\nThe numbering is based on a priority of:\r\n# Heroes\r\n## Alliance\r\n## Horde\r\n# Abilities\r\n## Class Abilities (Alphabetically, Druid through to Warrior)\r\n## Alliance Abilities\r\n## Horde Abilities\r\n## Neutral Abilities\r\n# Allies\r\n## Alliance Allies\r\n## Horde Allies\r\n## Neutral Allies\r\n# Equipment\r\n## Armor\r\n## Items\r\n## Weapons\r\n# Quests\r\n## Alliance Quests\r\n## Horde Quests\r\n## Neutral Quests\r\nEach section is then ordered alphabetically. ''Note: Warlock and Hunter pets are numbered within their Class Abilities.''\r\n===Loot Cards===\r\n==Example Art==\r\n<imagelink>\r\n<imagelink>",},
			["Through the Mirror Darkly"] = { content = "Written by [[Walter Simonson]]; Art by [[Jon Landry]] and [[Jerome K. Moore]]; Covers by [[Samwise Didier]] and [[Ludo Lullabi]]\r\n==Description==\r\n[[Varian Wrynn|Lo’Gosh]], [[Valeera Sanginugar|Valeera]], [[Broll Bearmantle|Broll]], and [[Thargas Anvilmar|Thargas]] make their way to [[Ironforge]] via a circuitous route through the [[Wetlands]]. And back in [[Stormwind]], [[Anduin Wrynn|Prince Anduin]] suspects all is not as it seems with his father, King Varian.",},
			["Throw"] = { content = "''\"Hey, you! Catch!\"''\r\n==Overview==\r\nDescription: Hurl a thrown weapon at the target.\r\nClasses: [[Warrior]], [[Hunter]], [[Rogue]].\r\nRequire: [[Thrown]] weapon. \r\n==Proficiency==\r\nAll rogues and [[troll]] warriors have thrown [[Class proficiencies|weapon proficiency]] when they are created.\r\nHunters and all other warriors can learn to use thrown weapons from the [[weapon master]] who teaches it. \r\nThrown weapons are either ''throwing knives'' or ''throwing axes''. The thrown weapon proficiency covers both, and there is generally no difference, two identical items with different icons and names will be sold side by side. \r\nFor example:\r\n*Keen Throwing Knife\r\n*Sharp Throwing Axe\r\nSome of the more better thrown weapons will be either a knife or an axe, not both.\r\n==Use==\r\n''[[Thrown]] weapons'' are ''thrown'' using the ''throwing skill''. That is not merely a tautology, the ''throwing'' ranged weapon skill used is distinct from the skill for all other ranged weapons which are ''[[shoot|shot]]''. In the user interface, different icons are used for throwing and shooting. Abilities that work with shooting do not work with throwing, and abilities that work with throwing do not work with shooting. \r\nThis distinction is most important for hunters, because [[autoshot]] does not work with thrown weapons, all throws are manually initiated, and the many hunter abilities that work with shoot do not work with throw. Hunters do not often choose to throw. \r\nRogues and warriors do not have autoshot, and all their throws and shots are manually initiated. Rogues and warriors do not have abilities that require shooting. Rogues have a [[Deadly Throw]] [[finishing move]] ability that requires a thrown weapon. \r\nThrown weapons do less damage than shot weapons of the same level. Also weapons which are shot can be [[augment]]ed with scopes and get a damage bonus from their ammo. On the other hand, thrown weapons are generally faster than shot weapons, and a rogue or warrior player who has to manually shoot may find that a second throw is possible while a mob is closing. \r\nThrown weapons are adequate for [[Pull | pulling]], which is primarily for getting a mob's attention. Rogues and warriors do most of their damage through melee, not ranged attacks, lacking the shooting based mob control abilities, [[hunter pet|pet]], and [[trap]]s that enable a hunter to rely on ranged attacks. \r\nThrown weapons with stat bonuses are available at a lower level than other (non-[[wand]]) shot weapons with stat bonuses. Since rogues and warriors focus on melee, they will often favor a thrown weapon with a stat bonus in the ranged slot. \r\n==Tips==\r\nLevel 19 [[twink]] rogues and warriors will often carry either Throat Piercers or Thick Bronze Darts.\r\n----",},
			["Throwing Specialization"] = { content = "'''{{PAGENAME}}''' is a Troll racial trait that increases chance to critically hit with throwing weapons by 1%.",},
			["Throwing Weapon Specialization"] = { content = "'''Throwing Weapon Specialization''' is a tier 6 [[rogue talent]] that increases the range of [[thrown]] weapons by 3/6 yards.\r\n==Patch 1.12==\r\nThis talent was removed in [[Patch 1.12]].",},
			["Thrown"] = { content = "A type of [[ranged]] [[weapon]] that usually causes only physical [[damage]] and doesn't need [[ammo]] to use, instead the weapon loses 1 out of 200 durability per throw, and requires a repair once it reaches 0 durability.\r\n[[Darkspear|Trolls]] have a [[Darkspear|Throwing Weapon Specialization]] (+1 % crit bonus).\r\nAll [[Rogues]] start with the throw ability, and later gain the ability [[Deadly Throw]], which requires a thrown weapon to be equipped. [[Hunters]] and [[Warriors]] can learn the throw skill from some trainers (see [[Weapon master|weapon trainers]] for details).\r\n'Throwing' is not the same as 'shooting'. In particular, hunter skills that work with shooting (all of the ranged hunter skills?) do not work with a thrown weapon. So while a hunter can use a thrown weapon, it is a poor choice for a hunter. \r\nWarriors and rogues will not be relying on ranged attacks for damage. They will sometimes use a ranged attack to call a mob out of an area into melee to isolate it from other mobs. Warriors and rogues lack the skills that make shooting so preferable to a hunter, so for them, throwing is a good option. For them, a thrown weapon is a ranged weapon with intrinsic ammo, and they will not burn through the 'ammo' nearly as fast as a hunter would.\r\n==Burning Crusade==\r\nDrysc: \"The mechanic of thrown weapons is being changed in the expansion to be similar to a normal weapon. Once a stack is used it will remain in your inventory and can then be repaired to refill the stack, similar to repairing broken armor or weapons. This allows us to put stats on thrown weapons and itemize them as we would any other weapon.\" \r\nSome examples : \r\nThere is a bug currently in game that still causes throwing weapons to be used up even though the patch was implemented to stop this. Blizzard claims they are working on a fix for this bug.",},
			["Thrown Weapons"] = { content = "#REDIRECT [[Thrown]]", redirect = "Thrown",},
			["Thrum"] = { content = "'''Thrum''' is a [[dwarven]] explorer who found out, while on an adventure with a [[human]] and [[goblin]], that goblin technology sometimes does not work, and can backfire.",},
			["Thugrim Seven-Eyes"] = { content = "'''Thugrim Seven-Eyes''' is an [[ogre magus]] [[healer]]. He is a hero and commander of the [[Duskbelch]] tribe. He is intimidating but is a beloved commander (he is so well-loved by his troops that if he were to fall it would ignite them into a savage fury).",},
			["Thuk the Defiant"] = { content = "==Loot==\r\n*Evidence from Alpha",},
			["Thule Ravenclaw"] = { content = "'''Thule Ravenclaw''' was a young mage with great promise in the years before the Third War. He was once best friends with [[Bethor Iceshard]] and was also good friends with [[Gunther Arcanus]]; Bethor and Thule wove their apprentice's wands together as a symbol of their friendship. But their friendship was sundered when Ravenclaw willingly sold his soul to the [[Lich King]].\r\nAfter the Scourge of Lordaeron, Thule Ravenclaw along with legions of [[Rot Hide Gnoll]]s set up in [[Fenris Keep]], the fortress on [[Fenris Isle|the island]] at the center of [[Lordamere Lake]].\r\nSome followers of Thule namely Rot Hide gnolls in Tirisfal Glades (amongst others) have learnt to harness a form of shadow magic named the Curse of Thule. \r\n==Objective of==\r\n*Drops Thule's Head for the quest Assault on Fenris Isle.\r\n==See also==\r\n*[[The Master of Fenris Isle quest chain]]",},
			["Thultazor"] = { content = "'''Thultazor''' is a level 45 [[reagent]] [[vendor]] located in [[Stonard]] in the [[contested]] territory of [[Swamp of Sorrows]].\r\nSee [[List of Swamp of Sorrows NPCs]].",},
			["Thunderaan"] = { content = "In the battle against the [[Titan]]s, the [[Old Gods]]' armies were led by the powerful elemental lieutenants, Gods in their own right: [[Ragnaros the Firelord]], [[Therazane the Stonemother]], [[Al'Akir the Windlord]], and [[Neptulon the Tidehunter]]. Chaotic forces raged across the face of the world as they clashed with the colossal Titans. Though the elementals were powerful beyond mortal comprehension, their combined forces could not stop the mighty [[Titan]]s. One by one, the elemental lords fell, and their forces dispersed. \r\nThe [[Pantheon]] shattered the Old Gods' citadels and chained the remaining four evil gods far beneath the surface of the world. One was defeated in the battle; its remains can still be seen in Darkshore.\r\nThe corruption of the [[Titan Shaper]]s would permeate through the surface and befoul the Old Gods. It was then and there that the brothers did turn. For five millennia a battle was fought at the core of this world.\r\nIt was during the [[Elemental Sundering]] that the Firelord, [[Ragnaros]], would seek to consume Thunderaan, Prince of Air.\r\nIt was the lieutenants of Ragnaros, [[Baron Geddon]] and [[Garr]], who would perpetrate the betrayal against Thunderaan the Windseeker. Thunderaan was caught unaware.\r\nThe Firelord's advances were wholly unknown to Thunderaan. Before he could react [[Sulfuras]], the legendary hammer of Ragnaros, would strike an unmerciful blow. Thunderaan fell, utterly defeated. The Firelord feasted upon the essence of the Prince of Air, but was unable to consume him entirely.\r\nWhat little remained of Thunderaan's essence was stored within a talisman of elemental binding. Ragnaros then shattered the talisman in [[Bindings of the Windseeker|two flawless pieces]]. The pieces assigned to his Lieutenants.\r\nThe vessel of rebirth must be fortified with [[elementium]]. This mineral is only known to exist in the [[Elemental plane]]. There is one, an [[Earthshaper]], who may know more than I about the acquisition of such things.\r\nThunderaan wields Thunderfury, a [[legendary]] sword. Players can acquire this sword through a strenuously long chain of quests. But the final result of the quest reaps the Prince of Air's weapon itself.\r\n==Strategy==\r\n*Health: approx 330,000\r\nThunderaan has surprisingly little HP, so downing him should not be a problem for any 40-man raid with experience in the [[Molten Core]] or harder instances. Bring some friends to put the numbers over 40, and you're virtually guaranteed success. He can be killed with far fewer people if they're well-geared or patient - 7 or 8 have been confirmed, and a good 5-person group should be able to complete the fight given time.\r\nThunderaan has a knockback that wipes [[aggro]], but the radius for the knockback is less than the radius at which he's attackable. So long as the [[tank]] stays at maximum [[melee]] range the knockback should not be an issue. There is also a chain lightning effect that can hit melee attackers, and an area effect lightning attack that most [[ranged]] attackers and [[healer]]s can avoid by keeping their distance.\r\nA tank with high nature [[resistance]] will mitigate a great deal of Thunderaan's damage.\r\n==Quotes==\r\n*My power is discombobulatingly devastating! It is ludicrous that these mortals even attempt to enter my realm!\r\n**''Note: This is actually a Mike Tyson quote that has been slightly edited:'' \"My power is discombobulatingly devastating. I could feel his muscle tissues collapse under my force. It's ludicrous these mortals even attempt to enter my realm.\"",},
			["Thunderaan the Windseeker"] = { content = "#REDIRECT [[Thunderaan]]", redirect = "Thunderaan",},
			["Thunderbluff"] = { content = "#REDIRECT [[Thunder Bluff]]", redirect = "Thunder Bluff",},
			["Thunderbrew's Boot Flask"] = { content = "==Source==\r\nThis item is a quest reward from Sweet Amber.",},
			["Thunderbrew Apprentice"] = { content = "Thunderbrew Apprentices can be found during [[Brewfest]], wherever Alliance brew kegs are located.",},
			["Thunderbrew Distillery"] = { content = "The '''Thunderbrew Distillery''' is a dwarven tavern in [[Kharanos|Kharanos.]] It features trainers for [[warrior]]s, [[priest]]s, [[paladin]]s, [[mage]]s, [[rogue]]s, [[cooking]], and [[first aid]]. It also has several vendors, among them an innkeeper with the usual services. The distillery is known far and wide for its excellent ale.",},
			["Thunderbrew Distillery"] = { content = "The '''Thunderbrew Distillery''' is a dwarven tavern in [[Kharanos|Kharanos.]] It features trainers for [[warrior]]s, [[priest]]s, [[paladin]]s, [[mage]]s, [[rogue]]s, [[cooking]], and [[first aid]]. It also has several vendors, among them an innkeeper with the usual services. The distillery is known far and wide for its excellent ale.",},
			["Thunderbrew Lager"] = { content = "==Objectives==\r\nBring [[Grimbooze Thunderbrew]] 5 hops to complete his special brew. \r\n* Hops (5)\r\n== Description==\r\nHurry, my friend, move with haste \r\nIn order for our rich lager to taste \r\nMore like beer and less like stew, \r\nHops are needed to make the brew. \r\n== Progress==\r\nHurry, my friend, move with haste \r\nIn order for our rich lager to taste\r\nMore like beer and less like stew,\r\nHops are needed to make the brew. \r\n== Completion==\r\nHops and Barley, yeast and malt \r\nThe taste-buds feel a virtual assault, \r\nNo need to plead, no need to beg \r\nFor Thunderbrew Lager comes in a keg! \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*0 [[XP]] \r\n*1 [[reputation]] with [[Ironforge]]",},
			["Thunderbrew Lager Keg"] = { content = "The '''Thunderbrew Lager Keg''' is located in the [[Blackrock Depths]]. Breaking all of them will summon [[Hurley Blackbreath]].",},
			["Thunderclap"] = { content = "#redirect [[Thunder Clap]]", redirect = "Thunder Clap",},
			["Thunderfall"] = { content = "'''Thunderfall''' is located just to the north of [[Frostfield Lake]] in the eastern reaches of [[Storm Peaks]]. In it is a scene of frozen storm giants and attackers.\r\nDiscovering Thunderfall will light up the southeast portion of the map covering Frostfield and [[Fjorn's Anvil]].",},
			["Thunderfury, Blessed Blade of the Windseeker"] = { content = "'''Thunderfury, Blessed Blade of the Windseeker''', is the legendary sword once wielded by [[Thunderaan]], Prince of Air.\r\n==Background==\r\nRagnaros the Firelord, and his lieutenants Garr and Baron Geddon, defeated Thunderaan, Prince of Air, during the war following the First Age of Creation. Ragnaros was unable to fully destroy Thunderaan’s\r\nessence, so he forced what little remained into a talisman of elemental binding and shattered it. He gave the two halves to his lieutenants. Ages passed, and somehow the talisman halves found their way into the hands of Highlord Demitrian, a follower of Thunderaan. He recombined the talisman but was unable to release his master. Instead, he did the best he could: He crafted a blade to serve as a vessel for his master’s essence.\r\nThunderfury is a vicious sword, crafted from elementium and containing a crackling electrical core that might be all that remains of Prince Thunderaan. The hilt is unusually long, wrapped in black dragon hide, and studded with small spikes of black dragon bone.\r\n==Source==\r\nThunderfury, Blessed Blade of the Windseeker is the reward from the quest [[Quest:Rise, Thunderfury!|Rise, Thunderfury!]]. It is the culmination of a challenging and very expensive quest chain.\r\n# Examine the Vessel\r\n# Thunderaan the Windseeker\r\n# Rise, Thunderfury!\r\nThe quest can be started by a [[hunter]], [[paladin]], [[rogue]] or [[warrior]].\r\nThe quest chain begins when you loot the [[Bindings of the Windseeker (Left)|Left]] or the [[Bindings of the Windseeker (Right)|Right]] half of the Bindings of the Windseeker, which drop off [[Baron Geddon]] and [[Garr]] respectively, in [[Molten Core]]. Upon looting either of these, you must travel to [[Silithus]] and talk with [[Highlord Demitrian]]. He will give you the Vessel of Rebirth which starts the quest chain.\r\nThe next quest requires you to present the following items to Demitrian:\r\n* both [[Bindings of the Windseeker (Left)|left]] and [[Bindings of the Windseeker (Right)|right]] halves of the Bindings of the Windseeker\r\n* Essence of the Firelord - a 100% drop, assuming one has the quest, from [[Ragnaros]], final boss of [[Molten Core]]\r\n* 10x Elementium Bar - each bar requires 1 Elementium Ore (from [[Blackwing Lair]]), 1 Fiery Core, 10 Arcanite Bar, and 3 Elemental Flux.\r\nBring a raid with you when you return with the required items to Demitrian because he will summon [[Thunderaan]], who promptly attacks you. Upon defeating Thunderaan you receive a Dormant Wind Kissed Blade. Deliver this to (the now rather cowed) Highlord, and he will make Thunderfury for you.\r\n==Notes==\r\nThe proc effect has been observed to be approximately 20-25%. The slowing effect from the proc affects both mobs and players. It is important to note that the proc debuff does not stack with the debuff from the warrior ability [[Thunderclap]], and that the Thunderfury's proc will take priority over it. The warrior ability [[Improved Thunder Clap]] offers the same 20% slow and will overwrite the Thunderfury debuff. The secondary nature resistance reduction debuff that is applied to the targets does not break crowd control effects, and it is unconfirmed to whether it actually generates any threat(although it will register on a mob's threat table such as critters or the bugs in Twin Emperor's room in AQ40. The Thunderfury proc may also crit for approximately 450 Nature damage.\r\n===Patch 1.12.0===\r\nAs of patch [[1.12]], Thunderfury may be equipped in either hand.\r\n===Patch 2.0.10===\r\nAs of patch [[2.0.10]], the threat generated from the [[proc]] has been substantially reduced. The threat generation from a proc of Thunderfury was previously equivalent to that of approximately one application of sunder armor from a lvl 60 warrior.",},
			["Thunderfury"] = { content = "#REDIRECT [[Thunderfury, Blessed Blade of the Windseeker]]", redirect = "Thunderfury, Blessed Blade of the Windseeker",},
			["Thunderhead"] = { content = "'''Thunderhead''' can be found in [[The Barrens]] .\r\n==Drops == \r\n \r\n0.06% Chance of a [[rare]] drop.\r\n0.52% Chance of an [[Uncommon]] drop.\r\n0.09% Chance of a [[common]] drop.\r\n0.01% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Thunderheart"] = { content = "'''Thunderheart''' is a level 52 [[quest giver]] located in [[Kargath]] in the [[contested]] territory of [[Badlands]]. He may be related to [[Senani Thunderheart]].\r\n==Quests==\r\n* Disharmony of Flame \r\n* Disharmony of Fire \r\n==See also==\r\n*[[Kargath Expeditionary Force]]\r\n*[[List of Badlands NPCs]]",},
			["Thunderheart Harness"] = { content = "'''Thunderheart Harness''' is the [[Tier 6]] set for Feral Druids. \r\n==Notes==\r\nSee also: [[Set look alikes]]",},
			["Thunderhorn clan"] = { content = "''This article is about Thunderhorn (NPC), see also [[Server:Thunderhorn US|Thunderhorn (US PVE server)]].\r\n*Race: Tauren\r\n*Occupation: Strategist\r\n*Alignment: Orcish Hordes; Tauren Tribes\r\n*A wise and benevolent Chieftain of the Thunderhorn Tauren, Marn had become, in his life, a very experienced and seasoned warrior. He was also a valuable tactician and strategist, known for his extensive knowledge of the foes he faced.\r\n*Leaders of armies throughout the world flocked to Marn, to learn more of the art of Warcraft, and Marn was kind enough to allow them to pore over his extensive library. Near the end of his career, however, satisfied with his accomplishments, he passed the torch to his good friend, Mojo Stormstout. \r\n==Known Thunderhorns==\r\n*[[Bosun Thunderhorn]]\r\n*[[Elder Thunderhorn]]\r\n*[[Harutt Thunderhorn]] <Warrior Trainer>\r\n*[[Hesuwa Thunderhorn]] <Pet Trainer>\r\n*[[Holt Thunderhorn]] <Hunter Trainer>\r\n*[[Hunter Thunderhorn]]\r\n*[[Kary Thunderhorn]] <Hunter Trainer>\r\n*[[Kuna Thunderhorn]] <Bowyer & Fletching Goods>\r\n*[[Mull Thunderhorn]]\r\n*[[Omusa Thunderhorn]] <Wind Rider Master>\r\n*[[Sergeant Thunderhorn]] <Weapons Quartermaster>\r\n*[[Stamp Thunderhorn]] <Darkmoon Faire Food Vendor>\r\n*[[Urek Thunderhorn]] <Hunter Trainer>",},
			["Thunderhorn Water Well"] = { content = "The '''Thunderhorn Water Well''' is located in the midst of the grasslands in [[Mulgore]], by the north road between [[Thunder Bluff]] and [[Bloodhoof Village]], like most of the other water sources in Mulgore, it is under the control of the nefarious [[Venture Company]].",},
			["Thundering Skyfire Diamond"] = { content = "Thundering Skyfire Diamond is crafted by [[Jewelcrafting|Jewelcrafters]] with a skill level of 365.\r\nThe [[design]] is a [[world drop]].\r\n*Design: Thundering Skyfire Diamond\r\n==Effects==\r\nGrants 240 Haste rating for 10 seconds. 240 Haste is 15.23% speed increase.\r\n*Proc. chance is based on weapon speed, meaning faster weapons proc. less often per attack. Everyone should get about 1 proc. per minute.",},
			["Thunderlord Clan"] = { content = "#REDIRECT [[Thunderlord clan]]", redirect = "Thunderlord clan",},
			["Thunderlord Stronghold"] = { content = "'''Thunderlord Stronghold''' is a [[Horde]] town in [[Blade's Edge Mountains]]. \r\nIt was the stronghold of the [[Thunderlord Clan]] until the [[ogre]] tribes \r\nexterminated them. Now, new Horde forces hold it in honor of the original clan. \r\nAfter the opening of the Dark Portal, [[Rexxar]] traveled here in search of his \r\nown race.\r\n===Flight===\r\n [[Mok'Nathal Village]]\r\n [[Swamprat Post]]\r\n [[Zabra'jin]]\r\n [[Evergrove]]\r\n [[Area 52]]\r\n [[The Stormspire]]\r\n===Leaders===\r\n* Rexxar\r\n** Misha\r\n* Tor'chunk Twoclaws\r\n===Merchants===\r\n* Gholah\r\n* Old Orok\r\n* Lor\r\n* Pol Snowhoof\r\n* Threlc\r\n* Karnaze\r\n* Daga Ramba\r\n* Orgatha\r\n* Raiza\r\n===Other Characters===\r\n* Unoke Tenderhoof\r\n* Agadai\r\n* Fera Palerunner\r\n* Nekthar\r\n* Gor'drek\r\n* Rokgah Bloodgrip\r\n** Garm Wolfbrother\r\n** Thunderlord Clan Sub-Chief lvl 68\r\n** Thunderlord Clan Sub-Chief lvl 69\r\n===Guards===\r\n* Thunderlord Grunt",},
			["Thunder Axe Fortress"] = { content = "'''Thunder Axe Fortress''' is a stronghold occupied by the [[Burning Blade]] cult founded by [[Klass Metalfist]]. Within the fortress they store the artifact known as the [[Hand of Iruxos]], which is used to open demon portals at [[Mannoroc Coven]]. It is interesting to note that the red crystal containing the demon holding the Demon Box (which containts the Hand of Iruxos) may hypothetically be identical in its composition to [[bloodstone ore|bloodstone]] - material frequently used in summoning demons. Thunder Axe Fortress also houses the [[Sceptre of Light]] - an immensely powerful artifact that the Burning Blade stole from the naga. [[Azore Aldamort]] seeks to recover this artifact for the [[Argent Dawn]]. [[Tyranis Malem]] resides here, a traitor to his people, and a keen pioneer in demonic magics.",},
			["Thunder Bluff"] = { content = "'''Thunder Bluff''' is the [[Tauren]] capital [[city]] located in the northern part of the region of [[Mulgore]] on the continent of [[Kalimdor]]. The entire city is built on bluffs several hundred feet above the surrounding landscape, and is accessible by elevators on the southwestern and northeastern sides. \r\n==Description==\r\nThunder Bluff was settled fairly recently by the tauren, who successfully drove out the marauding [[Centaur]] from their lands. Thunder Bluff is the first city of its kind; for centuries, the tauren wandered the plains as nomads, unable to claim a permanent home. All [[Horde]] visitors are welcome here, and the expertise of the tauren in professions ranging from [[leatherworking]] to [[shamanism]], [[druidism]] to hunting are all practiced and taught here. Unfortunately, the central location of the Thunder Bluff also makes it easily accessible to members of the [[Alliance]].\r\nIn order to gain access to Thunder Bluff, visitors must either ride [[wyvern]]s to the top one of the four towering mesas or be lifted via rope and wood elevators, an invention unique to the tauren.\r\n===People and Culture===\r\nAlthough some of the historically nomadic tauren probably miss their itinerant lifestyle, they are intensely proud of their permanent home and spend much of their time trying to make it better. They gladly accept the help of the [[orc]]s and [[troll]]s that help them, but are somewhat less enthusiastic at the presence of the [[Forsaken]], whom they only grudgingly tolerate because of their membership in the Horde. Tauren place a strong emphasis on the value of life, and the unlife of the Forsaken stands as an affront to their beliefs.\r\n===Geography===\r\nThunder Bluff is composed of four towering mesas, or rises. The only entrances from the plains below are elevators leading to the central platform. The central rise is connected to the others through large wooden bridges.\r\nThunder Bluff is located in the far north of Mulgore, among the sprawling flatlands of the [[Golden Plains]]. The weather is almost always warm and sunny, with intermittent breezes carried in from the Barrens.\r\n===History===\r\nThe Centaur were driving the tauren out of their homeland around the time of the [[Third War]]. When [[Thrall]] and his Horde arrived on the [[continent]], an alliance was forged between the Horde and the tauren. Following the defeat of [[Archimonde]] and the end of the war, Thrall helped the tauren rout the Centaur and reclaim their land. Shortly thereafter the tauren founded the city of Thunder Bluff and began the process of settling into their old surroundings and repairing the ecological damage the centaur had wrought. Thunder Bluff grows and expands at a tremendous rate.\r\n===Rises===\r\nThe various rises in Thunder Bluff act a bit like neighborhoods or quarters in a human city , or the valleys and keeps of the orcish city[[Orgrimmar]].\r\nThunder Bluff has a central mesa divided into three rises, surrounded by three additional mesas with distinct names:\r\n* [[Central Rise]] (In-game is split in to the Lower Rise, Middle Rise and High Rise)\r\n** '''[[Lower Rise]]''' (southwestern lifts from main north road)\r\n** '''[[Middle Rise]]''' (northeastern lifts from plains)\r\n** '''[[High Rise]]''' (east from wind rider roost)\r\n* '''[[Elder Rise]]''' (rope bridges from middle and high rise)\r\n* '''[[Hunter Rise]]''' (rope bridges from lower and high rise)\r\n* '''[[Spirit Rise]]''' (rope bridges from lower and middle rise)\r\n** '''[[Pools of Vision]]''' (cave entrance from Spirit Rise)\r\n==Notable Characters==\r\nThe ancient Chief of the Bloodhoof clan, [[Cairne Bloodhoof]] has become the High Chieftain of the tauren race. He watches over Thunder Bluff, and over his people in an ever-darkening world. Many believe that he is training his son [[Baine Bloodhoof]], who can be found in [[Bloodhoof Village]], to take Cairne's place one fateful day. Cairne can be found in the Chieftain's Tent in the eastern Main City, and is accompanied by his Honor Guard. \r\n[[Magatha Grimtotem]] is the elder crone of the mighty [[Grimtotem Clan]]. Blessed with shamanic powers when she was just a young girl, Magatha has sought power and prestige nearly her whole life. The Grimtotems believe that Magatha will lead them in eradicating the lesser races from Kalimdor and retaking the tauren ancestral holdings abroad. Magatha constantly spars with Cairne Bloodhoof over the direction of the tauren's future and feels that only she is fit to rule her people.\r\n[[Hamuul Runetotem]] is the elder druid of Thunder Bluff, and a childhood friend of Cairne. It remains to be seen where Hamuul will stand in the possible conflict that may arise between his chieftain and Magatha.\r\n==Quests==\r\n''See also: [[Thunder Bluff questing guide]]\r\n==Points of Interest==\r\n* The [[Bank]] is on the southeastern side of the Lower Rise.\r\n* The [[Wind Rider]] Master [[Tal]] is located on the top of the wind rider roost in the central totempole.\r\n* The [[inn]] is on the southern part of the Lower Rise.\r\n* The [[Auction House]] is located on the Lower Rise, just west of the entrance to the wind rider roost.\r\n* The [[mailbox]] is located just outside the bank.\r\n* The [[Fishing hole]] is located on the lower rise smack dab in the middle.\r\n===Flight===\r\n [[Orgrimmar]]\r\n [[Valormok]]\r\n [[Sun Rock Retreat]]\r\n [[The Crossroads]]\r\n [[Camp Taurajo]]\r\n [[Shadowprey Village]]\r\n [[Brackenwall Village]]\r\n [[Camp Mojache]]\r\n [[Freewind Post]]\r\n [[Gadgetzan]]\r\n==Notes & Tips==\r\n* [[Rumstag Proudstrider]] has the Thunder Bluff repeatable [[Runecloth]] quest used by non-tauren [[Horde]] players to obtain the right to ride [[kodo]]s.\r\n*In Thunder Bluff, the [[Alterac Valley]], [[Warsong Gulch]] and [[Arathi Basin]] battlemasters are located on the Hunter Rise. One of the curious things in Thunder Bluff is the ability to enter a battleground mounted. Since the battlemasters are outside, if you are mounted when you queue for the battleground, and stay mounted until you enter it, you will enter the battleground already mounted and with a significant speed/time advantage.\r\n* It's a bad idea to jump from the top of one of the bluffs, as the fall is generally fatal without some sort of slowing effect. You can also reduce damage by landing on the small platform next to the elevators, also known as \"platform jumping\".",},
			["Thunder Bluff Marzipan"] = { content = "==Source==\r\nThis item is a quest reward from Dancing for Marzipan.\r\n==Thunder Bluff Marzipan as a quest objective==\r\nThis item is an objective of Hallow's End Treats for Spoops!.",},
			["Thunder Bluff NPCs"] = { content = "The following [[NPC]]s can be found in the city of [[Thunder Bluff]].\r\n=== Horde===\r\n* Ahanu\r\n** 10\r\n* Apothecary Zamah\r\n** Journey to Tarren Mill\r\n** Serpentbloom (Dungeon)\r\n** The Flying Machine Airport\r\n* [[Hamuul Runetotem|Arch Druid Hamuul Runetotem]]\r\n** The Barrens Oases\r\n** Nara Wildmane\r\n** Un'Goro Soil\r\n** Morrowgrain Research\r\n** Rabine Saturna (Horde)\r\n* Auld Stonespire\r\n** A Vengeful Fate (Dungeon)\r\n* Bashana Runetotem\r\n** Blackfathom Villainy (Dungeon)\r\n** Morrowgrain Research (2)\r\n** Morrowgrain to Thunder Bluff (Repeatable)\r\n* Bluff Runner Windstrider\r\n** The Ashenvale Hunt\r\n** A Call to Arms: The Plaguelands! (Horde)\r\n** The New Frontier\r\n** Camp Mojache\r\n* Cairne Bloodhoof\r\n** Rites of the Earthmother\r\n* Clarice Foster\r\n** Until Death Do Us Part\r\n* Eyahn Eagletalon\r\n** Preparation for Ceremony\r\n* Horde Warbringer\r\n** Call to Arms: Warsong Gulch (Horde) (PvP, Daily)\r\n** Call to Arms: Arathi Basin (Horde) (PvP, Daily)\r\n** Call to Arms: Alterac Valley (Horde) (PvP, Daily)\r\n** Call to Arms: Eye of the Storm (Horde) (PvP, Daily)\r\n* Innkeeper Pala\r\n** Assisting Arch Druid Runetotem\r\n** Dancing for Marzipan ([[Hallow's End]])\r\n* Kwee Q. Peddlefeet ([[Love is in the Air]])\r\n** Gift Giving ([[Love is in the Air]], Repeatable)\r\n* Lunar Festival Harbinger ([[Lunar Festival]])\r\n** Lunar Fireworks ([[Lunar Festival]])\r\n** Valadar Starsong ([[Lunar Festival]])\r\n* Lunar Festival Herald ([[Lunar Festival]])\r\n** The Lunar Festival ([[Lunar Festival]])\r\n* Magatha Grimtotem\r\n** Forsaken Aid\r\n** Arikara (Elite)\r\n** Magatha's Payment to Jediga\r\n* Melor Stonehoof\r\n** The Hunter's Way\r\n** Sergra Darkthorn\r\n** Steelsnap\r\n** Frostmaw\r\n** Deadmire\r\n* Nara Wildmane\r\n** Leaders of the Fang (Dungeon)\r\n** Seeing What Happens\r\n** A Future Task\r\n* Officer Thunderstrider\r\n** One Commendation Signet (Repeatable)\r\n** Ten Commendation Signets (Repeatable)\r\n* Orm Stonehoof\r\n** Chimaeric Horn\r\n** Brutal Helm\r\n* Rahauro\r\n** Testing an Enemy's Strength (Dungeon)\r\n** Searching for the Lost Satchel (Dungeon)\r\n* Rumstag Proudstrider\r\n** A Donation of Wool\r\n** A Donation of Silk\r\n** A Donation of Mageweave\r\n** A Donation of Runecloth\r\n** Additional Runecloth (Repeatable)\r\n* Sage Truthseeker\r\n** Compendium of the Fallen (Dungeon)\r\n** The Platinum Discs\r\n* Senior Sergeant Taiga ([[Gates of Ahn'Qiraj|Ahn'Qiraj War Effort]])\r\n** The Horde Needs Your Help! ([[Gates of Ahn'Qiraj|Ahn'Qiraj War Effort]])\r\n* Tal\r\n** 10\r\n* Temma of the Wells ([[Love is in the Air]])\r\n** Dearest Elenia, ([[Love is in the Air]])\r\n* Turak Runetotem\r\n** Moonglade\r\n** Body and Heart\r\n** Lessons Anew\r\n** A Lesson to Learn\r\n* Ursyn Ghull\r\n** Journey to the Marsh\r\n** Return to the Marsh\r\n* Veren Tallstrider\r\n** Gathering Leather (Skinning)\r\n** Kodo Hide Bag (Leatherworking)\r\n* Whulwert Copperpinch ([[Feast of Winter Veil]])\r\n** Great-father Winter is Here! ([[Feast of Winter Veil]])\r\n* Xanis Flameweaver\r\n** Call of Water\r\n** Call of Air\r\n* Zangen Stonehoof\r\n** The Sacred Flame\r\n** The Sacred Flame (2)\r\n=== Neutral===\r\n* Elder Proudhorn ([[Lunar Festival]])\r\n** Proudhorn the Elder ([[Lunar Festival]])\r\n=== Horde===\r\n* Archmage Shymm\r\n** Thurston Xane\r\n** Ursyn Ghull\r\n*** Birgitte Cranston\r\n* Beram Skychaser\r\n** Siln Skychaser\r\n** Tigor Skychaser\r\n* Father Cobb\r\n** Malakai Cross\r\n** Miles Welsh\r\n* Holt Thunderhorn\r\n** Kary Thunderhorn\r\n** Urek Thunderhorn\r\n*** Hesuwa Thunderhorn\r\n* Sark Ragetotem\r\n** Torm Ragetotem\r\n** Ker Ragetotem\r\n* Sheal Runetotem\r\n** Turak Runetotem\r\n** Kym Wildmane\r\n=== Horde===\r\n* Aska Mistrunner\r\n* Bena Winterhoof\r\n* Brek Stonehoof\r\n* Kah Mistrunner\r\n* Karn Stonehoof\r\n* Komin Winterhoof\r\n* Mooranta\r\n* Pand Stonebinder\r\n* Tepa\r\n* Teg Dawnstrider\r\n* Una\r\n=== Horde===\r\n* Ahanu\r\n* Chepi\r\n* Delgo Ragetotem\r\n* Elki\r\n* Etu Ragetotem\r\n* Fela\r\n* Fyr Mistrunner\r\n* Grod\r\n* Halpa\r\n* Hewa\r\n* Hogor Thunderhoof\r\n* Innkeeper Pala\r\n* Jyn Stonehoof\r\n* Kaga Mistrunner\r\n* Kard Ragetotem\r\n* Kuna Thunderhorn\r\n* Kurm Stonehoof\r\n* Kuruk\r\n* Lunar Festival Vendor ([[Lunar Festival]])\r\n* Mahu\r\n* Mani Winterhoof\r\n* Naal Mistrunner\r\n* Nan Mistrunner\r\n* Nata Dawnstrider\r\n* Nida Winterhoof\r\n* Ohanko\r\n* Pakwa\r\n* Seersa Copperpinch ([[Feast of Winter Veil]]) \r\n* Sewa Mistrunner\r\n* Shadi Mistrunner\r\n* Sunn Ragetotem\r\n* Sura Wildmane\r\n* Tagain\r\n* Tand\r\n* Taur Stonehoof\r\n* Thrumn\r\n* Whulwert Copperpinch ([[Feast of Winter Veil]])\r\n=== Horde===\r\n* Althallen Brightblade\r\n* Ansekhwa\r\n* Atepa\r\n* Auctioneer Gullem - (Auctioneer)\r\n* Auctioneer Stampi - (Auctioneer)\r\n* Bluffwatcher - (Directions)\r\n* Bulrug\r\n* Chesmu\r\n* Defilers Emissary - (Arathi Basin Recruiter) ([[Battlegrounds Holiday|Call to Arms: Arathi Basin]])\r\n* Eye of the Storm Envoy - (Eye of the Storm Recruiter) ([[Battlegrounds Holiday|Call to Arms: Eye of the Storm]])\r\n* Fizim Blastwrench\r\n* Frostwolf Emissary - (Alterac Valley Recruiter) ([[Battlegrounds Holiday|Call to Arms: Alterac Valley]])\r\n* Innkeeper Pala\r\n* Kergul Bloodaxe\r\n* Krumn\r\n* Martin Lindsey\r\n* Taim Ragetotem\r\n* Tal\r\n* Torn\r\n* Warsong Emissary - (Warsong Gulch Recruiter) ([[Battlegrounds Holiday|Call to Arms: Alterac Valley]])",},
			["Thunder Bluff quests"] = { content = "This is a list of all [[Thunder Bluff]] quests in table format (arranged by level).\r\nFor a questing guide detailing the best order to obtain and complete quests in [[Thunder Bluff]], see [[Thunder Bluff questing guide]].\r\nThe following quests can be found in [[Thunder Bluff]]:\r\n==Quest Tables==\r\nQuests which take place in [[Thunder Bluff]] are denoted by a . \r\nThe other quests listed either send the player out of the zone; or are in quest chains related to [[Thunder Bluff]], categorized as such, but take place out of the zone.\r\n==== Class Specific Quests====\r\nSince this is a starting zone, there are several class specific quests available here for each [[tauren]] class.\r\n==== Profession Specific Quests====\r\nA [[Cooking]] and an [[Alchemy]] quest are also available in [[Thunder Bluff]].\r\n==Notable Quest Chains in [[Thunder Bluff]]==\r\nThe following quest chains occur at least partly in [[Thunder Bluff]]. Chains have been included if they are more than three quests long or are specially significant in some way.\r\n=== Aquatic Form===\r\n#A Lesson to Learn\r\n#Trial of the Lake\r\n#Trial of the Sea Lion\r\n#Aquatic Form\r\n=== The Sacred Flame===\r\n#The Sacred Flame\r\n#The Sacred Flame (2)\r\n#The Sacred Flame (3)\r\n==Links==\r\n*",},
			["Thunder Clap"] = { content = "''\"This ain't no patty cake game!\"''\r\n'''Thunder Clap''' is a point blank [[Area of Effect]] ability that causes physical damage and slows up enemies' attacks (that is, negative [[Haste]]), This is the warriors main AOE tanking ability. \r\n==Tips and Tactics==\r\n*By slowing the enemies' attacks it effectively decreases the damage they inflict on you. This makes it especially useful when tanking.\r\n*Thunder Clap is useful for tanking when a warrior needs to multi-tank a large number of mobs. Other than [[Challenging Shout]] (which is on a 10-minute cooldown), the warrior has no other real abilities that cause threat on multiple enemies at once.\r\n*While it does cause more damage in Battle Stance than Defensive Stance, it doesn't create more threat in Battle Stance due to the threat modifiers in [[Battle Stance]] and [[Defensive Stance]].\r\n*At level 70, [[Sunder Armor]] will generate 391 threat in Defensive Stance (without factoring in any [[Defiance]] bonus or damage inflicted by [[Devastate]]). A Thunder Clap will generate a maximum of 251 in Defensive (123*90%*175%*130%=251) and 172 in Battle Stance (123*175%*80%=172), though probably less, since the damage of the Thunder Clap is mitigated by enemy armor. In this respect, an untalented Thunder Clap can be considered \"half a sunder\".\r\n*Spending talent points in 3/3 Improved Thunder Clap will double the damage it inflicts, which also doubles the threat generated. If specced for 3/3 [[Improved Thunder Clap]], you can generate more than Sunder-level threat (max. threat in Defensive Stance: 123*200%*90%*175%*130%=502) on up to an unlimited amount of NPCs for the cost of 16 rage (13 if you have Focused Rage) and a single global cooldown. It also slows the attacks of any opponents it affects even more than an untalented Thunder Clap, increasing your potential survivability against them.\r\n*Be careful using this ability around [[crowd control]]led mobs, as the damage it inflicts will likely break the crowd control effect. If possible it is best to apply Thunder Clap before crowd control, or to pull the [[mob]]s you wish to Thunder Clap away from the sheeped/sapped/trapped/etc. mobs. Also be careful of using this around a mob your group's [[Hunter]] is trying to draw into a [[Freezing Trap]], as it may make it more difficult for the Hunter to establish aggro on the mob.\r\n*Thunder Clap can be useful against melee PvP opponents, as it reduces their ability to inflict damage. Its AoE effect against up to unlimited opponents makes it especially useful in large battles.\r\n==Notes==\r\n*Thunder Clap creates [[threat]] equal to 1.75x damage done.\r\n*Thunder Clap's damage is physical and is mitigated by the armor of the opponent.\r\n*Thunder Clap cannot be cast while [[silence]]d.\r\n*Thunder Clap dealt Nature damage when the game was first released. This was quickly changed.",},
			["Thunder Falls"] = { content = "'''Thunder Falls''' is a waterfall in west [[Elwynn Forest]] that leads into [[Mirror Lake]]. A steep path to the right of the Mirror Lake Falls leads up to a small [[Defias]] camp that has level 8-10 [[Defias Bandit]]s. If you follow the river eventually you will come to a waterfall right next to the main entrance to Westfall, it is fun to jump down this waterfall but you will die instantly and the corpse run is a long walk. Or if you are careful you can walk down a small ramp of hill that ends up at the bottom of the Westfall waterfall\r\nUpon exploring for a little bit you'll realize that Thunder Falls quite unusual in the sense that it is a double-sided waterfall. The Falls are fed by another waterfall on some mountains on the north of this plateau but you cannot walk up the hill as it is very steep.",},
			["Thunder lizard"] = { content = "A '''thunder lizard''' is a heavyset, large lizard that is the distant relative of the [[kodo]]. They are aggressive beasts that prefer canyons and plains. When in combat, they shoot lightning from their mouth at distance and dole out harsh headbutts at close range. Thunder lizards come in a variety of colors, including blue, pink, and gray, and live in [[Durotar]], [[The Barrens]], the [[Stonetalon Mountains]], and [[Desolace]].\r\n==Fighting thunder lizards==\r\nAttacks which interrupt the spellcasting of NPCs such as the rogue's [[Kick]], the shaman's [[Earth Shock]], and the warrior's [[Shield Bash]] are also effective against these lizards. When you see the lightning building up in its mouth, hit it with the counter to casting used by your class and you won't have to worry about getting hit by any lightning bolts... you'll only have to worry about being trampled, gored, or crushed by a huge and irate reptile.\r\nThunder Lizards are hostile, whereas kodos are neutral, and will not aggro unless attacked.\r\n==WarCraft III==\r\nIn ''WarCraft III'', thunder lizards came in a variety of forms, including storm wyrms and lightning lizards. Rather than shooting lightning from their horns, they shot it from their mouths. The salamanders and thunder lizards looked very similar, as one or the other was a simple reskin of the first.\r\n==Thunder Ridge==\r\nThunder Ridge holds a massive amount of thunder lizards, and have already appeared in ''The Frozen Throne'' bonus campaign (starring [[Rexxar]]). In ''Warcraft III'', Thunder Ridge thunder lizards were green, but in ''World of Warcraft'' they are red-skinned.\r\n==Stegodon==\r\n\"Spikes\" in the back of thunder lizards are similar to [[Stegodon]] ones; but where the Stegodon spikes probably served to help regulate the body temperature, the use of the thunders lizard ones are unknown. They may be used to channel electricity.\r\n==Notable Lightning Lizards==\r\n*[[Margol the Rager]]\r\n*[[Skum]]\r\n==Related Species==\r\n* [[Kodo]]\r\n* [[Storm wyrm]]\r\n* [[Salamander]]\r\n* [[Lightning lizard]]",},
			["Thunder lizards"] = { content = "#REDIRECT [[Thunder lizard]]", redirect = "Thunder lizard",},
			["Thunder Ridge"] = { content = "'''Thunder Ridge''' is an area located in the land of [[Durotar]], just southwest of [[Orgrimmar]]. \r\nThis breathtaking gorge is untamed by humanoids as yet. [[Thunder lizards]] give the place its name, dominating the landscape for some distance. Tallstriders are also seen hanging out on the fringes with an eye out for an easy lunch. The ridge is home to behemoth lightning lizards, which help to obscure the presence of the Burning Blade here, led by the goblin warlock [[Fizzle Darkstorm]].\r\nShortly after the founding of Durotar, [[Rexxar]] and his companions journeyed to Thunder Ridge to obtain [[shimmerweed]] for [[Drek'Thar]], Thrall's [[Far Seer]]. Rexxar noticed a change in the lizard's behavior, and informed Drek'Thar upon his return to Orgrimmar. Drek'Thar and Rexxar later discovered a human lumber operation that was deforesting the ridge and driving the lizards mad. They were forced to put down the lizards to prevent disaster. \r\nNew thunder lizards named [[Lightning Hide]]s have moved into the ridge. Fizzle Darkstorm, has set up camp in the ridge along with a handful of his followers.",},
			["Thundris Windweaver"] = { content = "'''Thundris Windweaver''' is a level 15 [[quest giver]] located in [[Auberdine]] in the [[night elven]] zone of [[Darkshore]].\r\nHe starts the following quests:\r\n* Bashal'Aran\r\n* Tools of the Highborne\r\n* The Cliffspring River\r\n* The Blackwood Corrupted\r\n* Seeking the Kor Gem (Dungeon)\r\nSee [[List of Darkshore NPCs]].",},
			["Thurman Agamand"] = { content = "'''Thurman Agamand''' is a level 10 [[named]] [[zombie]] in the [[Agamand Mills]] section of [[Tirisfal Glades]]. His remains are sought by [[Coleman Farthing]] in the [[Gallows' End Tavern]] in [[Brill]], Tirisfal Glades.\r\n==Quests==\r\n*Deaths in the Family\r\n==Loot==\r\n*Thurman's Remains ''(Quest Item)''",},
			["Thuron's Livery"] = { content = "'''Thuron's Livery''' is located just east of the entrance to [[Silvermoon]] in [[Eversong Woods]]. It is where Horde players can buy [[hawkstrider]] mounts.",},
			["Thuzadin"] = { content = "The '''Thuzadin''' are a sect of mortal human necromancers led by [[Maleki the Pallid]]. They reside in the burning city of [[Stratholme]], headquarters of the [[Scourge]] in Lordaeron. Judging by the name of their order, it is believed that these men and women are acolytes of [[Kel'Thuzad]]. They are also part of the [[Cult of the Damned]].",},
			["Thuzadin Necromancer"] = { content = "'''Thuzadin Necromancer''' can be found in [[Stratholme]]. These necromancers are hardened graduates of the [[Scholomance]].\r\nKilling '''Thuzadin Necromancer''' will result in +1 reputation with [[Argent Dawn]]\r\n==Drops == \r\n \r\n0.17% Chance of a [[rare]] drop.\r\n0.88% Chance of an [[Uncommon]] drop.\r\n0.06% Chance of a [[common]] drop.\r\n0.34% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Thyssiana"] = { content = "'''Thyssiana''' is a level 65 [[hippogryph]] [[flight master]] located in [[Thalanaar]] in the [[contested]] territory of [[Feralas]].\r\nSee [[List of Feralas NPCs]].",},
			["Tichondrius"] = { content = "'''Tichondrius the Darkener''' was the leader of the [[nathrezim]] of the [[Burning Legion]], under the command of [[Kil'jaeden]]. He was a major character in the [[Warcraft III]] ''Path of the Damned'', ''The Invasion of Kalimdor'', and ''Eternity's End'' campaigns. While he appeared often, he was never available for the user to control. \r\n===War of the Ancients===\r\nTichondrius did not appear to have any part in the [[War of the Ancients]], though at times in WarCraft III, his comments implied firsthand experience. Since he is not mentioned in the War of the Ancients trilogy, he may not have played a significant or noteworthy role.\r\n===The Scourge of Lordaeron===\r\nPrior to the [[Third War]], Tichondrius was chosen by Kil'jaeden to personally police the newest agent of the Legion, [[Ner'zhul]], the malefic [[Lich King]]. Tichondrius was none too pleased with the appointment, but accepted it in the end. As befitting his status as the greatest of the Nathrezim, Tichondrius was placed in charge of a number of [[Scourge]] operations. Following the corruption of Prince [[Arthas Menethil]], Tichondrius introduced himself to the [[Death Knight]], providing him with orders from Ner'zhul, especially concerning the resurrection of [[Kel'Thuzad]]. \r\nTichondrius regularly discussed the Scourge's progress with his colleagues, [[Anetheron]] and [[Mephistroth]], who remained on a Legion planet in the Nether. The Darkener expressed (justified) concern that Ner'zhul had alternative plans for his new \"champion,\" but Mephistroth pointed out that he \"wouldn't dare undermine our efforts now.\"\r\nThe dreadlord continued his work, eventually overseeing the death of [[Uther Lightbringer]], the invasion and destruction of [[Quel'Thalas]], and the siege of [[Dalaran]]. Once [[Archimonde]] was summoned, he decreed that the Lich King was no longer needed, and gave Tichondrius control of the Scourge.\r\n===The Invasion of Kalimdor===\r\nThe [[human]]s, having lost their most powerful leaders and heroes, quickly fell before the might of the Legion, now joined by Mannoroth. Mannoroth was still sore over the [[orcs]] failure \r\nto conquer [[Azeroth]] years before, and was angrier still when Tichondrius smugly observed that the Scourge had done the job the orcs couldn't. Mannoroth became even more enraged when Tichondrius informed him that the orcs had left the continent. The pit lord was eager to take his frustrations out on the orcs, so at the first opportunity he and Tichondrius picked up the trail and followed the orcs to the ancient land of [[Kalimdor]].\r\nThe arrival at Kalimdor reminded the pair of demon lords only too well that the threat of the [[night elves]] still remained, as well as the demigod, [[Cenarius]]. Mannoroth suspected that unless weakened, they would still pose a considerable threat. Tichondrius, however, came up with a solution. He knew that the orcs had earned the wrath of Cenarius, and he believed that corrupting the orcs once again would give them the power to defeat Cenarius, leaving him defeated when the Legion began their invasion of Kalimdor in full. Encouraged by the Darkener's plot, Mannoroth spilt his burning blood into a sacred pool...\r\n===Death===\r\nIn spite of Mannoroth's death at the hands of [[Grom Hellscream]], Tichondrius proceeded with the invasion. The Scourge, more dangerous than ever thanks the demonic support of [[felhound]]s, [[doomguard]] and [[infernal]]s, was more than successful in penetrating [[Ashenvale]] without Cenarius's intervention. The combined forces of the orcs and the humans, coupled with the resistance of the night elf druids, eventually managed to halt their progress. \r\nAs the invasion of Kalimdor progressed, Tichondrius began corrupting the forests of [[Felwood]] using a powerful artifact, the [[Skull of Gul'dan]]. However, the skull was consumed by [[Illidan Stormrage]], who had been tipped off by none other than [[Arthas]]. Transformed by the skull into a [[demon]]-hybrid, Illidan used his newfound power to vanquish Tichondrius.\r\nAfter his death, [[Anetheron]] became the new lord of the nathrezim.\r\n===Reincarnation===\r\nAlthough it is not confirmed by Blizzard but a sheep in one of the undead levels is named Tichondrius. A possible reincarnation?\r\n==Quotes==\r\nTichondrius: \"''Calm yourself, Prince [[Arthas]]. I am Tichondrius. Like [[Mal'Ganis]], I am a dreadlord, but I am not your enemy. In truth, I've come to congratulate you.''\"\r\nArthas: \"''Congratulate me?''\"\r\nTichondrius: \"By killing your own father and delivering this land to the [[Scourge]], you have passed your first test. The [[Lich King]] is pleased with your... enthusiasm.''\"\r\n[[Arthas]]: \"''The circle of power has been prepared per your instructions, lich. Are you ready to begin the summoning?''\"\r\n[[Kel'thuzad]]: \"''Nearly. I've been reading through [[Medivh]]'s spellbook. His knowledge on demons alone is staggering. I suspect that he was far more powerful than anyone ever realized.''\"\r\nTichondrius: \"''Not powerful enough escape death, that is for certain. Suffice to say, the work he began, we will finish... today. Let the summoning commence!''\"",},
			["Tichondrius the Darkener"] = { content = "#REDIRECT [[Tichondrius]]", redirect = "Tichondrius",},
			["Tick"] = { content = "===In WoW:===\r\nIn [[World of Warcraft]]:\r\n# A time increment used for ''over time'' effects ([[Channeling]], [[DoT]], [[HoT]], etc.):\r\n#* 1 tick is every time the spell's overtime affect happens. Many effects tick once every two seconds, but not all.\r\n# The bronze [[drake]] '''[[Tick (drake)|Tick]]''' guarding the [[Caverns of Time]] together with [[Chronalis]] and [[Occulus]].\r\n===In Not-WoW (aka Real-Life):===\r\nNot specific to [[World of Warcraft]], but sometimes used to describe time increments, a '''tick''' can have a few meanings:\r\n# From : Interval of time; basic clock time on the computer. Typically 1/60 second. See \r\n# From : In , the duration of one tick of the system timer interrupt. Typically, this time is 0.01 seconds.\r\nNote: 1/60 = 0,01(6).",},
			["Ticket"] = { content = "In ''[[World of Warcraft]]'', a '''ticket''' usually refers to an active [[Help Request]] to a [[Game Master|GM]] for in-game support about a [[bug]], issue or problem in-game. Most tickets do not get resolved right away, unless it is a major [[bug]] newly discovered or an obvious and traceable [[harassment]] event.\r\nAn \"[[Ticket|Open Ticket]]\" is for an issue that has not been addressed or resolved.\r\nSee [[Help Request]] for issues that GMs should consider valid requests. \r\n==Open Ticket==\r\nYou will know when you have an open ticket because a small ticket icon will appear just to the left of your [[Mini-Map]] at the top of the screen.\r\n==Escalated Ticket==\r\nAn \"Escalated\" ticket is one which has been passed onto a Specialist Game Master team, and this is normally done when a more complicated or thorough investigation is required. The waiting time for escalations can vary, but it usually takes a couple of days to receive a response.",},
			["Tick (Dragon)"] = { content = "#REDIRECT [[Tick (drake)]]", redirect = "Tick (drake)",},
			["Tick (drake)"] = { content = "'''Tick''' is a level 52 [[elite]] [[named]] bronze [[drake]] that guards the [[Caverns of Time]] with [[Chronalis]] after you encounter [[Occulus]], in eastern [[Tanaris]].\r\n* He has 7,200 hp.\r\n* He is hostile.",},
			["Tidal Focus"] = { content = "Reduces the [[Mana]] cost of your healing spells by {1/2/3/4/5}%",},
			["Tidal Force"] = { content = "'''Tidal Force''' is a 11-point talent in the [[Shaman]] [[Shaman talents|Restoration]] tree.",},
			["Tidal Guardian"] = { content = "#REDIRECT [[Tidal guardian]]", redirect = "Tidal guardian",},
			["Tidal Mastery"] = { content = "'''Tidal Mastery''' is a passive talent that increases the critical effect chance of healing and lightning spells by {1/2/3/4/5}%",},
			["Tidefury Cove"] = { content = "'''Tidefury Cove''' is located at the end of [[Dustwallow Bay]], south of [[Theramore Isle]] and off the coast of the [[Wyrmbog]] in the [[contested]] territory of [[Dustwallow Marsh]]. It is dotted with small islands and reefs, and is a perilous place to steer one's ships. Two ships are currently found broken upon the shallows here, now riddled with roaming [[makrura]]. The famous fisherman [[Nat Pagle]] also makes his home on [[Nat's Landing]], one of the cove's many islets.\r\n==History==\r\nShortly after the [[Third War]], Grand Admiral [[Daelin Proudmoore]] decided that the [[new Horde]] is not to be trusted and constantly harassed them despite the peace treaty. With the strategic and diplomatic efforts of [[Rexxar]], the forces of the Horde retaliated against Proudmore's fleet here in Tidefury Cove. The horde offensive was able to decimate one-tenth of Proudmoore's fleet. Daelin Proudmoore himself was able to flee to his daughter's stronghold of [[Theramore Isle]] where he made his [[A Blaze of Glory|last stand]].",},
			["Tidefury Raiment"] = { content = "'''Tidefury Raiment''' is the third [[Armor Set|Dungeon set]] for Shamans. \r\n==Stats==\r\n==Items==\r\n \r\n==Notes==\r\nSee also: [[Set look alikes]]",},
			["Tidelord Rrurgaz"] = { content = "'''Tidelord Rrurgaz''' is a level 62 [[elite]] male [[naga]] found on [[Alcaz Island]] in [[Dustwallow Marsh]]. He has been introduced in [[Patch 1.10 (Release Notes)|Patch 1.10]] and replaced [[Varian Wrynn]] prior placed in this sewer.",},
			["Tides' Hollow"] = { content = "'''Tides' Hollow''' is a cave occupied by the [[Wrathscale]] [[naga]] who also occupy the nearby [[Wrathscale Point]] ruins. Their lord is said to be located deep within the hollow.",},
			["Tides of Darkness"] = { content = ":''Were you looking for the RTS game [[Warcraft II: Tides of Darkness]]?''\r\n'''Tides of Darkness''' is a novel by [[Aaron Rosenberg]] focusing on the events of [[Warcraft II: Tides of Darkness]].\r\n==Summary==\r\nThis novel covers the events of the [[Second War]]. It features [[Turalyon]], [[King Terenas]], [[Anduin Lothar]], [[Orgrim Doomhammer]], [[Gul'dan]], [[Khadgar]], and [[Alleria Windrunner]] as main characters.\r\nThe [[Horde (pre-Thrall)|Orcish Horde]], now led by Orgrim Doomhammer, has destroyed the nation of [[Stormwind|Azeroth]]. Anduin Lothar knows that land is lost, and so hatches a desperate plot; take the people away and enlist the aid of humanity's rivals, the [[Elves]] and [[Dwarves]].\r\nThe book begins with Anduin Lothar landing on the shores of [[Lordaeron]], and goes through the events occurring in [[Warcraft II]].\r\n==Back of Book Description==\r\nAfter killing the corrupt [[Warchief Blackhand]], Orgrim Doomhammer was quick to seize control over the Orcish Horde. Now he is determined to conquer the rest of [[Azeroth]] so that his people will once again have a home of their own in the... \r\nWORLD OF WARCRAFT \r\nAnduin Lothar, former Champion of Stormwind, has left his shattered homeland behind and led his people across the Great Sea to the shores of Lordaeron. There, with the aid of the noble King Terenas, he forges a mighty [[Alliance]] with the other human nations. But even that may not be enough to stop the Horde's merciless onslaught. \r\nElves, dwarves, and [[trolls]] enter the fray as the two emerging factions vie for dominance. Will the valiant Alliance prevail, or will the Horde's tide of darkness consume the last vestiges of freedom on Azeroth? \r\n==Characters==\r\nTides of Darkness has an astounding amount of Warcraft characters from lore, ranging from major characters to 1 page cameos. As such, it is best to separate them.\r\n===Major characters===\r\nOther\r\n*[[Alexstrasza]]",},
			["Tidewalker Warrior"] = { content = "'''Tidewalker Warrior''' can be found in [[Serpentshrine Cavern]].\r\n==General == \r\n* These mobs are vulnerable to Fear, Polymorph, tranq shot and Snares. They are, however, stun immune.\r\n* They are vulnerable to [[Disarm]]\r\n* Cleaves (frontal only)\r\n* Bloodthirst for 2600\r\n* Melee's on plate for 1000-2500\r\n* Gains frenzy from time to time for around 10 seconds (you'll know because they grow to about twice their size for the duration). This can be countered with a hunter's [[Tranquilizing Shot]].\r\n* Randomly drops aggro and jumps on someone else.",},
			["Tide Crawler"] = { content = "'''Tide Crawlers''' are blue [[crab]]s found along the coast of [[Darkshore|Darkshore]] prior to the [[Cataclysm (event)|Cataclysm]].",},
			["Tide Razor"] = { content = "The '''''Tide Razor''''' is a ship belonging to the [[Southsea Freebooters]], a legion of pirates who run their operations along the southeastern coast of [[Kalimdor]]. [[Rogue]]s of the [[Horde]] will have to enter the ''Tide Razor'' and battle a fierce parrot as part of one of their many class quests.",},
			["Tidus"] = { content = "A small fishing village on beach at the foot of the [[Tidus Stair]]. Currently two tauren shamans can be seen fishing in the village called [[Islen Waterseer]] and [[Mahren Skyseer]]. The adults and children of the village like to dive down as deep as they can and explore.\r\nThe coastal town of Tidus is also is known for its marketplace where the inventor of [[footcarts]] was once a poor tinker. The most popular of her products that she sold in the marketplace were miniature phlogiston-powered [[Steam Tonk|steam tanks]].\r\nIt somewhat exists in the game, not as a village, but with just a single hut and is also is not a named subzone.",},
			["Tier"] = { content = "==Armor==\r\nAll [[class]]es in the [[World of Warcraft]] have unique armor sets designed specifically for their own usage. \r\nThey include:\r\nFor more information about armor sets, including tiers, see [[Armor_set|armor sets]].\r\n==Talent Tree==\r\nThe talent tree is subdivided into tiers.",},
			["Tiers"] = { content = "#redirect [[Tier]]", redirect = "Tier",},
			["Tier 0.5"] = { content = "#redirect [[Dungeon Set 2]]", redirect = "Dungeon Set 2",},
			["Tier 0"] = { content = "#REDIRECT [[Dungeon Set 1]]", redirect = "Dungeon Set 1",},
			["Tier 1"] = { content = "'''Tier 1''' is a type of item set. Each set consist of 8 pieces.\r\n==Location==\r\nThe items that form those sets are found in the [[Molten Core]]. For details, refer to the set page.\r\n==Notes==\r\nEach set's Bracers and Belt are bind on equip, thus they can be traded.",},
			["Tier 2"] = { content = "'''Tier 2''' is a type of item set. Each set consist of 8 pieces.\r\n==Location==\r\nThe items that form those sets are found in the [[Molten Core]], in [[Onyxia's Lair]] and in the [[Blackwing Lair]]. For details, refer to the set page.\r\nMost pieces drop from various bosses in the [[Blackwing Lair]],\r\n* the bracers of each set drop from [[Razorgore the Untamed]],\r\n* the belt of each set drops from [[Vaelastrasz the Corrupt]],\r\n* the boots of each set drop from [[Broodlord Lashlayer]],\r\n* the gloves of each set drop from [[Firemaw]], [[Flamegor]] and [[Ebonroc]],\r\n* the shoulders of each set drop from [[Chromaggus]],\r\n* the chestpiece of each set drops from [[Nefarian]],\r\nbut:\r\n* the pants of each set drop from [[Ragnaros]] in the [[Molten Core]] and\r\n* the headpiece of each set drops from [[Onyxia]] in [[Onyxia's Lair]].",},
			["Tier 3"] = { content = "'''Tier 3''' is a type of item set. Each set consist of 9 pieces.\r\n==Location==\r\nThe items that form these sets are quest rewards. The quests require, among other things, token drops from bosses in [[Naxxramas (original)|Naxxramas]].\r\nThe only exception are the rings, which drop directly from [[Kel'Thuzad]] in Naxxramas.\r\nFor details, refer to the set page.\r\nThe tokens for the following items can be found on the first two bosses of a specific wing in [[Naxxramas]] as well as on [[Gluth]]:\r\n* The token for the belt of each set drops from bosses in the plague wing: [[Noth the Plaguebringer]] and [[Heigan the Unclean]],\r\n* the token for the wristpiece of each set drops from bosses in the spider wing: [[Anub'Rekhan]] and [[Grand Widow Faerlina]],\r\n* the token for the boots of each set drops from bosses in the deathknight wing: [[Instructor Razuvious]] and [[Gothik the Harvester]] and\r\n* the token for the shoulderpiece of each set drops from bosses in the abomination wing: [[Patchwerk]] and [[Grobbulus]].\r\nThe tokens for the following items can be found on the endboss of a specific wing in [[Naxxramas]]:\r\n* The token for the headpiece of each set drops from [[Thaddius]] in the abomination wing,\r\n* the token for the pants of each set drops from [[Loatheb]] in the plague wing,\r\n* the token for the gloves of each set drops from [[Maexxna]] in the spider wing and\r\n* the token for the chest piece of each set drops from [[The Four Horsemen]] in the deathknight wing,\r\nThe following classes share tokens:\r\n* Paladin, Hunter, Shaman, Druid\r\n* Priest, Mage, Warlock\r\n* Warrior, Rogue\r\n==Notes==\r\nAs of [[3.0|Patch 3.0.2]], Tier 3 will be no long be obtainable, as Naxxramas will be moved to [[Northrend]] as an entry level 10-/25-man raid dungeon for the [[Wrath of the Lich King]] expansion. Those that still have the armor will be able to wear it, however.",},
			["Tier 4"] = { content = "'''Tier 4''' is a type of item set. Each set consist of 5 pieces.\r\nEach piece is purchased by acquiring a \"Fallen\" [[Currency|armor token]] from defeating a ''[[World of Warcraft: The Burning Crusade|The Burning Crusade]]'' [[raid]] [[boss]]. Each token is good for one piece of armor (chest, head, etc.), and is valid for any of several particular classes. Note that as this was created before [[death knight]]s, [[monk]]s, and [[demon hunter]]s were available, there are no tier 4 armor sets for these classes.\r\n==Sets==\r\nSome classes have several sets, each designed for a different talent tree.\r\n==Location==\r\nThe items that form these sets are purchased with tokens. The tokens drop from various bosses in [[Karazhan]], [[Gruul's Lair]] and [[Magtheridon's Lair]].\r\nFor details, refer to the set page.\r\nTwo out of five tokens drop from bosses in [[Karazhan]]:\r\n* The token for the headpiece of each set drops from [[Prince Malchezaar]] and\r\n* the token for the gloves of each set drops from [[The Curator]].\r\nTwo out of five tokens frop from bosses in [[Gruul's Lair]]:\r\n* The token for the pants of each set drops from [[Gruul the Dragonkiller (tactics)|Gruul the Dragonkiller]] and\r\n* the token for the shoulders of each set drops from [[High King Maulgar]].\r\nOne out of five tokens drops in [[Magtheridon's Lair]]:\r\n* The token for the chest piece of each set drops from [[Magtheridon]].",},
			["Tier 5"] = { content = "'''Tier 5''' is a type of item set. Each set consist of 5 pieces.\r\n==Sets==\r\nSome classes have several sets, each designed for a different talent tree.\r\n==Location==\r\nThe items that form these sets are purchased with tokens. The tokens drop from various bosses in [[Serpentshrine Cavern]] and [[The Eye]].\r\nFor details, refer to the set page.\r\nThree out of five tokens drop from bosses in [[Serpentshrine Cavern]]:\r\n* The token for the headpiece of each set drops from [[Lady Vashj]],\r\n* the token for the gloves of each set drops from [[Leotheras the Blind]] and\r\n* the token for the pants of each set drops from [[Fathom-Lord Karathress]].\r\nTwo out of five tokens frop from bosses in [[The Eye]]:\r\n* The token for the chest piece of each set drops from [[Kael'thas Sunstrider]] and\r\n* the token for the shoulders of each set drops from [[Void Reaver]].\r\nThe following classes share tokens:\r\n* Druid, Priest and Warrior share tokens of the vanquished defender,\r\n* Hunter, Mage and Warlock share tokens of the vanquished hero and\r\n* Paladin, Rogue and Shaman share tokens of the vanquished champion.",},
			["Tier 6"] = { content = "'''Tier 6''' is a type of item set. Each set consists of 8 pieces.\r\n==Sets==\r\nSome classes have several sets, each designed for a different talent tree.\r\n==Location==\r\nThe items that form these sets are purchased with tokens which from various bosses in [[Hyjal Summit]], [[Black Temple]] and [[Sunwell Plateau]].\r\nFor details, refer to the set page.\r\nTwo out of eight tokens drop from bosses in [[Hyjal Summit]]:\r\n* The token for the gloves of each set drops from [[Azgalor]] and\r\n* the token for the headpiece of each set drops from [[Archimonde]].\r\nThree out of eight tokens drop from bosses in [[Black Temple]]:\r\n* The token for the shoulders of each set drops from [[Mother Shahraz]],\r\n* the token for the pants of each set drops from [[Illidari Council]] and\r\n* the token for the chest piece of each set drops from [[Illidan Stormrage]].\r\nThree out of eight tokens from from bosses in [[Sunwell Plateau]]:\r\n* The token for the bracers of each set drops from [[Kalecgos]] and from the [[Eredar Twins]],\r\n* the token for the belt of each set drops from [[Brutallus]] and from the [[Eredar Twins]] and\r\n* the token for the boots of each set drops from [[Felmyst]] and from the [[Eredar Twins]].\r\nThe following classes share tokens:\r\n* Paladin, Priest and Warlock share tokens of the Forgotten Conqueror,\r\n* Warrior, Hunter and Shaman share tokens of the Forgotten Protector and\r\n* Rogue, Mage and Druid share tokens of the Forgotten Vanquisher.",},
			["Tier 7"] = { content = "'''Tier 7''' is a type of item set. Each set consist of 5 pieces. There are seperate 10 and 25-man versions of each set.\r\n==Location==\r\nThere are seperate sub-tiers for the 10 and 25-man versions of [[Naxxramas]], with the 25-man versions being slightly better than the 10-man versions.\r\n==Notes==\r\nWith the removal of the 40-man version of Naxxramas in ''[[World of Warcraft: Wrath of the Lich King]]'', the ability to obtain [[Tier 3]] will be '''removed''' from the game, as Naxxramas will be moved to [[Northrend]] as an entry level raid dungeon with 10 and 25-man versions. As a result, the two version of Tier 7 are based on Tier 3, both in terms of visual design and name.",},
			["Tiger"] = { content = "A variety of [[cat]], '''tigers''' are found in the Echo Isles of [[Durotar]] and all over [[Stranglethorn Vale]]. Most tigers are orange with black stripes, but there are a few white tigers, the most famous being [[King Bangalash]].\r\nThese great cats stand more than 3 feet tall at the shoulder and are about 9 feet long. They typically weigh from 400 to 600 pounds.\r\n==Species==\r\n* [[Durotar Tiger]]\r\n* Dire Tiger",},
			["Tigerseye"] = { content = "'''Tigerseye''' is a [[mineral]].\r\n==Source==\r\nTigerseye is a mineral that [[Mining|miner]]s can extract from [[copper vein]]s. Other potential sources include [[mob]] [[drop]]s and [[chest (container)|chest]]s. Also can be prospected by [[Jewelcrafting|jewelcrafters]] from [[copper]] [[ore]]s.\r\n==Tigerseye as an ingredient==\r\n'''Tigerseye''' is used in the following recipes:\r\n===[[Blacksmithing]]===\r\n*Big Bronze Knife\r\n*Gemmed Copper Gauntlets\r\n*Heavy Copper Broadsword\r\n*Ironforge Breastplate\r\n===[[Engineering]]===\r\n*Deepdive Helmet\r\n*Flying Tiger Goggles\r\n*Gnomish Universal Remote\r\n===[[Jewelcrafting]]===\r\n*Tigerseye Band\r\n*Ornate Tigerseye Necklace\r\n*Bronze Band of Force",},
			["Tigole"] = { content = "#REDIRECT [[Jeffrey Kaplan]]", redirect = "Jeffrey Kaplan",},
			["Tigon"] = { content = "In [[World of Warcraft]], the '''tigon''' is not a true race or species, but rather a term to describe the form of three bosses in the game, two of which are in [[Zul'Gurub]], and the third in [[Karazhan]]. \r\n[[High Priestess Arlokk]] is a troll who transforms into the female panther form. [[High Priest Thekal]] transforms into the male tiger form, and [[Roar]] uses a male lion form.\r\nIf one equips the two fist weapons, [[Thekal's Grasp]] and [[Arlokk's Grasp]], to form the \"[[Primal Blessing]]\" [[:Category:World of Warcraft item sets|set]], it grants a small chance when ranged or melee damage is dealt to infuse the wielder with a blessing from the Primal Gods. Not only does the blessing transform your character into a tigon, but it increases ranged and melee attack power by 300 for 12 seconds.\r\nThe name 'tigon' comes from the model file of the three cat people.\r\n==Name==\r\nThe hybrid of a male [[tiger]] and a female [[lion]] is called a \"tigon\".",},
			["Tigor Skychaser"] = { content = "'''Tigor Skychaser''' is a level 40 [[shaman trainer]] located on [[Spirit Rise]] in the [[tauren]] city of [[Thunder Bluff]].\r\nSee [[List of Thunder Bluff NPCs]].",},
			["Tigule's Harpoon"] = { content = "'''Tigule's Harpoon''' is a [[rare]] [[polearm]] that is a decent weapon for [[hunter]]s and possibly some [[paladin]]s before getting [[Molten Core]] loot or an [[Ice Barbed Spear]]. It gives the user a [[stamina]] bonus, a hit rating increase, and an [[attack power]] increase when fighting [[beasts]].\r\n==Sources==\r\nTigule's Harpoon is dropped by [[Gahz'ranka]] in [[Zul'Gurub]].\r\n==Notes==\r\n\"Tigule\" is probably referring to the in game joke of [[Tigule]]. Something to be noted is that [[Foror's Eyepatch]] also drops in Zul'Gurub, which is probably referring to the ingame joke of [[Foror]] - both are mentioned in the item [[Tigule and Foror's Strawberry Ice Cream]].",},
			["Tigule"] = { content = "===Who is Tigule?===\r\nIn World of Warcraft, Tigule makes appearances as co-creator of \"the best tasting icecream in the whole world\" ([[Tigule and Foror's Strawberry Ice Cream]]), currently sold at the racetrack in Shimmering Flats, Thousand Needles. He also seems to have lost his harpoon ([[Tigule's Harpoon]]) which can now be found in the hands of [[Gahz'ranka]] in [[Zul'Gurub]].\r\nIn [[Old Hillsbrad]], [[Nat Pagle]] tells his friend [[Hal McAllister|Hal]] about his dream involving Tigule: \"You know those two loud-mouthed ruffians, [[Foror]] and Tigule? Well, in this dream, they somehow end up inventing something called ice-cream and flavoring it with strawberries... Well, long story short, they end up striking it rich! If that weren't crazy enough, they decide to quit the ice-cream business and become adventurers... They travel all over the place and finally disappear into some portal. I woke up in a cold sweat after that one...\"\r\n===The real Tigule .... Tigole===\r\nTigule is rumored to be an in-game representation of [[Tigole]] Bitties, once the guild leader of an Everquest guild famous amongst online gamers. Tigole, a.k.a. [[Jeff Kaplan]], is also World of Warcraft's Lead Designer responsible for world design.",},
			["Tikbalang"] = { content = "'''Tikbalangs''' are creatures mentioned only by the text of the amulet vendor [[Griftah|Griftah's]] [[Infallible Tikbalang Ward]]. It can be assumed from the text that one would want to avoid a Tikbalang.\r\nFrom [[User:VonKaiser|VonKaiser]], leading Tikbalang-ologist:\r\n''From an in-depth analysis of the Tikbalang warding amulet, it would appear that the Tikbalang have a tendency to take people of interest to them and relocate them to the tops of trees. This indicates a flying and/or bird-like origin, which could also mean they are relatives of the [[Arakkoa]]. The amulet also alludes to the Tikbalang finding you before being able to relocate you, thus insinuating that the Tikbalang may have trouble seeing or use some special process for discovering or searching for relocation targets. \r\n''The amulet has a parting statement:'' It Really Works!'' I see this as evidence to other non-working models of the Tikbalang ward or maybe it is just extremely difficult to ward off a Tikbalang.''\r\nFrom the :\r\n''[The Tikbalang] is a folkloric monster said to lurk in the mountains and forests of the Philippines. It is generally described as a tall, bony humanoid creature with disproportionately long limbs, to the point that its knees reach above its head when it squats down. It has the head and sometimes feet of an animal, most commonly a horse. It is sometimes believed to be a transformation of an aborted fetus which has been sent to earth from limbo.''\r\nIt is not certain how this applies to the Warcraft Tikbalang. The Wikipedia article does includes a few tips on how to ward off or tame this elusive beast:\r\n*Wear your shirt inside out\r\n*While traversing the forest, ask loudly for permission to pass through\r\n*Assure the beast that you will not be noisy and disturb it.\r\n*Craft an amulet out of one of the sharp spines found in the creature's mane, jump on it, and ride it like a bull until it submits to you.\r\nThese may or may not apply to the Warcraft incarnation of this creature.",},
			["Tilloa"] = { content = "'''Tilloa''' was a human female and a student of [[Stalvan Mistmantle]].\r\nTilloa was a daughter of a noble of [[Stormwind]]. \r\nA man named [[Stalvan Mistmantle]] once came and talked to Tilloa's father, and was later given the job to educate his two children, Tilloa and her little brother Giles. One day, she and her family went to their summer cottage near the [[Eastvale Logging Camp]], and they invited Stalvan to join them. \r\nStalvan couldn't help but notice the captivating beauty of Tilloa. Stalvan found her very attractive, and even though he knew that she was going to be married away, he wanted to give it a shot.\r\nLater, whilst Stalvan was teaching Giles, Tilloa was in the garden. After a few minutes she came in and placed a scarlet rose in his hand. Another time, as Stavlan was teaching Tilloa, she placed her hand on his.\r\n \r\nLater, when Tilloa entered the summer cottage with her new groom-to-be, she introduced Stalvan as \"a nice ''old'' man\". This, and the fact that she was going to be married away, eventually drove Stalvan to madness. \r\nTilloa, her family and her groom-to-be were later brutally murdered by the hands (or axe) of Stalvan.\r\nHer life before she met Stalvan is pretty much unknown.\r\n[[Tear of Tilloa]] can also be found at [[Manor Mistmantle]] in [[Duskwood]].",},
			["Timber"] = { content = "'''Timber''' is a level 10 [[rare mob]] white [[wolf]] found on the large island at the center of [[Iceflow Lake]] in [[Dun Morogh]]. It patrols the larger island accompanied by 2 [[Starving Winter Wolf]], and when brought into combat may bring other mobs if not carefully thinned out before hand. With its guards and level superiority, it could very well be the leader of Iceflow's wolf pack. It is on a 45 minute respawn timer.\r\n==Loot==\r\n*Silver-lined Bracers\r\n*White Wolf Gloves",},
			["Timberling"] = { content = "'''Timberlings''' are mobile plants that live in swamps or alongside rivers or lakes. They can be found in [[Teldrassil]] and the [[Swamp of Sorrows]]. The timberlings of Teldrassil are elementals of nature. In some ways they reflect the natural order of plants and animals on Teldrassil, but they have become corrupted and aggressive due to [[Fel Moss]]. Two notable timberlings of Teldrassil are [[Oakenscowl]] and [[Blackmoss the Fetid]].\r\nIn ''[[World of Warcraft]]'', these creatures are classified as [[elemental]]s.\r\n==Notable==\r\n*[[Oakenscowl]]\r\n*[[Blackmoss the Fetid]]\r\n*[[Molt Thorn]]\r\n*[[Mire Lord]]\r\n==Types==\r\n*Timberling\r\n*[[Swampwalker]]\r\n==Notes==\r\n*The plant creatures [[bog beast]] and [[thistleshrub]] and the elemental creature [[tar beast]], while using the same model as timberlings, are listed as separate types of creatures.\r\n===Bog beasts?===\r\nTimberlings may be a sub-category of bog beast, as it is said there are bog beasts on Teldrassil near Lake Al'Ameth.",},
			["Timberling Sprout"] = { content = "==Timberling Sprout as a quest objective==\r\nThis item is an objective of Timberling Sprouts.\r\n==As an object==\r\nThe '''Timberling Sprout''' can be found around [[Lake Al'Ameth]] in [[Teldrassil]].",},
			["Timbermaw"] = { content = "#redirect [[Timbermaw Hold reputation guide]]", redirect = "Timbermaw Hold reputation guide",},
			["Timbermaw Brawlers"] = { content = "'''Timbermaw Brawlers''' are a pair of [[Leatherworking]]-crafted gloves that give bonuses to [[Strength]] and [[Stamina]].\r\n==Source==\r\nTimbermaw Brawlers are crafted by [[Leatherworking|Leatherworkers]] with a skill level of 300.\r\nThe components are:\r\n*8 [[Enchanted Leather]]\r\n*6 [[Powerful Mojo]]\r\n*6 [[Living Essence]]\r\n*2 [[Cured Rugged Hide]]\r\n*2 [[Ironweb Spider Silk]]\r\nThe [[pattern]] is sold by [[Meilosh]] in the [[Timbermaw Hold]] in [[Felwood]]. You must have Revered reputation with the [[Timbermaw Furbolgs]] to purchase this pattern.",},
			["Timbermaw Furbolgs"] = { content = "#REDIRECT [[Timbermaw tribe]]", redirect = "Timbermaw tribe",},
			["Timbermaw Hold (faction)"] = { content = "The tunnel that connects [[Felwood]] with [[Moonglade]] and [[Winterspring]] is also part of the '''Timbermaw Hold'''. It is inhabited by [[Timbermaw Furbolg]]. Only if someone proves themselves by driving back the corrupted [[Deadwood]] and [[Winterfall]] tribes, may they one day consider them as an ally. And only such allies are allowed to pass through the tunnel. The tunnels also branch to Hyjal and Azshara as well, but they aren't available to everyone.\r\nThis tunnel which starts in [[Felwood]] is the only way for a player to initially get to Winterspring if they have never been there before (there exist two other ways to get to Moonglade; the Druids learn to teleport there early on, and for the other one, see the [[Moonglade|Moonglade article]]). In order to traverse the tunnel, you must either fight through, stealth or run through, or gain at least \"Unfriendly\" [[reputation]] with the Timbermaw Hold faction so they won't attack you. The last option is definitely the smartest, as the Timbermaw Hold faction also offers rewards as you gain standing with them.\r\nAnother section of Timbermaw Hold is found in the north-eastern mountain-side at the zone of [[Azshara]] (Kalimdor). The Hold is a stone structure built within the mountain, similar to Ironforge. The architecture of the human-built [[Greymane Wall]] in [[Silverpine Forest]] and [[Thoradin's Wall]] in [[Arathi Highlands]] look similar to the exterior of the Timbermaw Hold. \r\nSome have speculated that the Hold may become a future instance. Others also speculated that the Timbermaw Furbolgs might have been the new race playable to the Alliance based on their past relationship with the night elves and their pursuit to cleanse their brothers from the corruption which currently affects them. It is unknown what adventurers may find within the walls of Timbermaw Hold if the gates are ever opened. Currently the entrance is filled in with dirt and guarded by [[Gatekeeper Rageroar]], a Timbermaw Shaman furbolg, and two Timbermaw Den Watchers.\r\nThe structure could have been formerly made by primitive humans. Nevertheless, based on lore, dwarves are the race that build structures within mountains. According to [[War of the Ancients: The Sundering]], the [[Earthen]] joined the night elves in the War of the Ancients, fighting alongside with the [[Tauren]] and Furbolgs. Dwarves were revealed to be formerly from the Earthen race, created by the Titan Khaz'Goroth to dig the depths of the earth to rise and shape Mountains. The Timbermaw Hold could be the fortress of the Earthen that assisted the night elves during the War of the Ancients. After the Sundering, most Earthen hibernated within the halls of [[Uldum]], [[Ulduar]] and [[Uldaman]]. \r\nThe Timbermaw furbolgs of Azshara are the same faction as the Timbermaw in Felwood.\r\n==History==\r\nCenturies Ago, dragons abandoned the Timbermaw Hold when it was overrun by satyrs. Heroes waded the shallows and reclaimed the land.\r\nThis ancient furbolg fortress is located near Felwood's eastern border. It is a vast and rambling place, rumored to run deep into the slopes of Mount Hyjal. No one knows for sure how big it is, since the furbolgs abandoned it in ages past. Undead and satyrs may now wander the shadowed corridors...Along with whatever cursed furbologs still roam the depths. Wise travelers would bypass the site entirely if it were not the only passage through to Winterspring and Hyjal Summit.\r\n==Reputation and Rewards==\r\nAll players start off hostile to Timbermaw Hold (2500/3000 points). There are currently a scant handful of quests that improve this reputation. Most rep points must be earned by grinding. Building a high reputation with this faction allows access to a number of high-level recipes and other benefits. When you reach exalted, quests [[Quest:The Root of All Evil|The Root of All Evil]] and [[Quest:The Brokering of Peace|The Brokering of Peace]] become available to you. Completing [[Quest:The Root of All Evil|The Root of All Evil]] gives you Defender of the Timbermaw trinket. And [[Quest:The Brokering of Peace]] assigns you to give offering of peace to your factions capitals leader.\r\n In the Wrath of the Lich King expansion, players will be able to obtain [[achievements]] for becoming Exalted with Timbermaw Hold. The first, \"They Love Me In That Tunnel,\" for becoming exalted with Timerbmaw Hold. The second, \"The Diplomat,\" for becoming exalted with Timbermaw Hold, [[Sporeggar]], and either [[Mag'har]] or [[Kurenai]]. \r\nFollowing item recipes are sold by [[Meilosh]].\r\n==Notes==\r\nThe entire in-game Timbermaw Hold area is considered part of Felwood, all the way until the Moonglade and Winterspring entrances. Dying there will send the player to the [[Irontree Woods]] graveyard.",},
			["Timbermaw Post"] = { content = "'''Timbermaw Post''' is a small [[furbolg]] camp located southeast across the road from the [[Frostfire Hot Springs]], and west of [[Lake Kel'Theril]]. Although the name suggests that the camp was originally held by the [[Timbermaw]], it is now in complete control of furbolgs from the corrupted [[Winterfall]] tribe.",},
			["Timbermaw Shaman"] = { content = "'''Timbermaw Shaman''' can be found in [[Azshara]] .\r\nKilling '''Timbermaw Shaman''' will result in -25 reputation with [[Timbermaw Hold]].\r\n==Drops == \r\n \r\n0.04% Chance of a [[rare]] drop.\r\n1.03% Chance of an [[Uncommon]] drop.\r\n0.36% Chance of a [[common]] drop.\r\n1.89% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Timbermaw tribe"] = { content = "The '''Timbermaw tribe''' of [[furbolg]]s inhabit two areas: [[Azshara]] and [[Felwood]]. They are presumed to be the only furbolg tribe to escape demonic corruption, though this may not be true due to the existence of [[Krolg]], an uncorrupted furbolg who was once part of the [[Foulweald tribe]], and the [[Stillpine tribe]] on [[Azuremyst Isle]] from ''[[The Burning Crusade]]''. However, many other races kill furbolg blindly now without bothering to see if they are friend or foe. For this reason, the Timbermaw furbolgs trust very few.\r\n==History==\r\nWhen the corruption of the [[Burning Legion]] crept into the sacred forests of [[Kalimdor]], it was the creatures of the wild who first felt its monstrous power. Once gentle animals were transformed into abominable, rabid killers; their flesh rent and their spirits desecrated, they quickly succumbed to the demons' influence. Soon after, the furbolgs, the ursine children of the forest, suffered the same fate, as their entire species was driven mad by the surrounding corruption. However, amidst the chaos and the madness, one [[furbolg]] tribe escaped the darkness that had fallen on Kalimdor. In the safety of [[Timbermaw Hold]], the furbolgs of the Timbermaw tribe weathered the storm, yet they were forced to watch helplessly as the forest they had loved so much was slowly turned into a twisted, festering perversion of its former self. When the spirits of the forest spoke to them no more, the Timbermaw knew that their home was gone... possibly, forever. The corruption had sunk in deep, so that even long after [[Illidan]] the Betrayer had consumed the source of the corruption, a powerful [[warlock]] artifact called the [[Skull of Gul'dan]], and vanquished the [[demon]]s' leader [[Tichondrius]], the taint on the woods still remained. And so, the dead forest became known only as Felwood. \r\nWith the Burning Legion defeated, the Timbermaw furbolgs have recently taken their first, careful steps outside of the safety of Timbermaw Hold. They are wary of all strangers, fearing that they may mistake them for their corrupted brethren and attack. However, the Timbermaw are painfully aware that they will not last on their own; adventurers who seek out Timbermaw Hold in northern [[Felwood]] and prove themselves as friends of the Timbermaw will learn that the furbolgs value their friends above all else. Though they possess no fine jewels or any worldly riches, the Timbermaw's shamanistic tradition is still strong. They know much about the art of crafting armors from animal hides, and they are more than happy to share their healing talismans with friends of their tribe. The Timbermaw's main concerns are putting an end to their corrupted brethren's suffering and finding a cure to heal the wounds the corruption of Felwood has inflicted upon the land, so that one day, the ancient forests will once again resound with the peaceful chants and the soft laughter of the children of the forest.\r\n==Faction==\r\nThe Timbermaw furbolgs guard the [[Timbermaw Hold]] cave that connects [[Felwood]], [[Moonglade]], and [[Winterspring]]. You start out as with these furbolgs; you must attain at least an reputation to pass through their cave without them attacking you. If you choose to further build reputation with the Timbermaw, you may be able to access special items, exclusive tradeskill recipes and quests.\r\n===Named===\r\n* [[Burndl]]\r\n* [[Ferli]]\r\n* [[Grazle]]\r\n* [[Meilosh]]\r\n* [[Nafien]]\r\n* [[Gorn One Eye]]\r\n* [[Tur Ragepaw]]\r\n* [[Salfa]]\r\n* [[Tanrir]]\r\n===Unnamed===\r\n*[[Timbermaw Den Watcher]]\r\n*[[Timbermaw Pathfinder]]\r\n*[[Timbermaw Shaman]]\r\n*[[Timbermaw Totemic]]\r\n*[[Timbermaw Ursa]]\r\n*[[Timbermaw Warrior‎]]",},
			["Timberstrider"] = { content = "Timberstriders are [[hostile]] level 6-8 [[tallstrider]]s found on [[Azuremyst Isle]]. They are identical in appearance to the [[foreststrider]]s in [[Darkshore]] and the [[Greater Plainstrider]]s in the [[Barrens]].",},
			["Time-Lost Figurine"] = { content = "==Source==\r\nThis item drops from [[Terokk]] in the [[Skettis]], [[Terokkar Forest]].\r\n==Notes==\r\n*The drop chance is very low, around 1.5%.\r\n*Used to turn players into a random [[Arakkoa]] form.",},
			["Time-Lost Offering"] = { content = "'''Time-Lost Offering''' is a quest item.\r\n==Source==\r\nThis item is a quest reward from the [[Sha'tari Skyguard]] quest Adversarial Blood.\r\n==Notes==\r\n*This item is used at [[Terokk's Rest]] in the middle of [[Blackwind Lake]] to summon [[Terokk]].\r\n*The quest to obtain this item is repeatable.",},
			["Time-Lost Shadowmage"] = { content = "==Overview==\r\n*Level 69 Elite Undead\r\n*Found in [[Sethekk Halls]] of [[Auchindoun]]\r\n*Gives +9 [[Lower City]] Reputation when killed on Normal Mode.\r\n*Gives +15 Lower City Reputation when killed on Heroic Mode.\r\n===Abilities===\r\n*Curse of the Dark Talon (-50 stamina and +50 damage taken)\r\n*Shadow Bolt Volley: 1.2k Shadow Damage every second for 4 seconds. No casting bar is shown for this ability, but you can witness him casting it.\r\n===Notes===\r\n*Can be Shackled or Trapped.\r\n*This mob has a buff called \"Arcane Destruction\" which increases spell damage by 150. The magic is stealable by lvl 70 mage skill Spellsteal.",},
			["Timeline"] = { content = "This '''[[timeline]]''' provides an unofficial timeline of recorded important events in Warcraft history compiled from official timelines and all sources published by Blizzard.\r\nIt should not be considered as an official timeline, but should be as accurate as, and more complete than, what Blizzard have provided.\r\nNumbering is based on the opening of the [[Dark Portal]] as this is the method used by the latest sources. All dates are considered to be spans of time from one to the next as many events are only given vague ordering and estimated dates. Warcraft products are displayed in italics.\r\n==Beginning of Azeroth==\r\n-147,000\r\n*\r\n*[[The Titans and the Shaping of the Universe]]\r\n*[[Sargeras and the Betrayal]] (Minus Eredar related events)\r\n-65,000\r\n-64,001\r\n*[[Charge of the Dragonflights]]\r\n*[[The Waking World and the Well of Eternity]]\r\n-24,969\r\n==Age of the elves==\r\n-10,250\r\n*\r\n-10,000\r\n*Start of the War of the Ancients\r\n-9,999\r\n*\r\n*''[[The Demon Soul]]'' (Past)\r\n*[[The Sundering of the World]]\r\n-9,998\r\n*[[The World Tree and the Emerald Dream]]\r\n-7,300\r\n*[[The Sentinels and the Long Vigil]]\r\n-6,800\r\n-4,000\r\n==Age of the mortals==\r\n-2,800\r\n*[[Arathor and the Troll Wars]]\r\n-2,700\r\n*[[The Guardians of Tirisfal]]\r\n-2,500\r\n*The Ironforge Dwarves awaken in Uldaman\r\n*Khaz Modan is founded\r\n-1,200\r\n*[[The Seven Kingdoms]]\r\n-818\r\n*\r\n*[[Aegwynn and the Dragon Hunt]]\r\n-370\r\n*Last gnome royalty\r\n-230\r\n*[[War of the Three Hammers (History of Warcraft)|War of the Three Hammers]]\r\n-170\r\n*Dwarves meet gnomes\r\n*Gnomeregan is built\r\n==Rise of the Horde==\r\n-100\r\n-46\r\n-45\r\n*[[The Last Guardian (History of Warcraft)|The Last Guardian]]\r\n-40\r\n-19\r\n*\r\n==First War==\r\n0\r\n1\r\n*\r\n*''[[The Last Guardian]]''\r\n4\r\n5\r\n*[[The Alliance of Lordaeron]]\r\n==Second War==\r\n6\r\n*''[[Warcraft 2: Tides of Darkness]]''\r\n*''[[Tides of Darkness]]''\r\n7\r\n*''[[Warcraft 2: Beyond the Dark Portal]]''\r\n*''[[Beyond the Dark Portal]]''\r\n*''[[The Last Guardian]]'' (Future)\r\n*[[The Invasion of Draenor]]\r\n*[[The Birth of the Lich King]]\r\n*[[Icecrown and the Frozen Throne]]\r\n8\r\n*''[[Day of the Dragon]]''\r\n*[[The Battle of Grim Batol (History of Warcraft)|The Battle of Grim Batol]]\r\n*[[Lethargy of the Orcs]]\r\n10\r\n*''[[Warcraft Adventures: Lord of the Clans]]''\r\n*''[[Lord of the Clans]]''\r\n*[[The New Horde]]\r\n*[[War of the Spider (History of Warcraft)|War of the Spider]]\r\n*[[Kel'Thuzad and the Forming of the Scourge]]\r\n20\r\n*''[[Of Blood and Honor]]''\r\n*[[The Alliance Splinters]]\r\n==Third War and the Scourge==\r\n25\r\n*''[[Warcraft 3: Reign of Chaos]]''\r\n*[[The Scourge of Lordaeron (History of Warcraft)|The Scourge of Lordaeron]]\r\n*[[Sunwell - The Fall of Quel'Thalas]]\r\n*[[Archimonde's Return and the Flight to Kalimdor]]\r\n*[[The Battle of Mount Hyjal (History of Warcraft)|The Battle of Mount Hyjal]]\r\n*''[[Warcraft RPG]]''\r\n26\r\n*''[[The Well of Eternity]]''\r\n*''[[The Demon Soul]]''\r\n*''[[The Sundering (book)|The Sundering]]''\r\n*[[Rise of the Blood Elves]]\r\n*[[Civil War in the Plaguelands]] \r\n*[[The Lich King Triumphant]]\r\n*\r\n28\r\n*\r\n29\r\n*\r\n*''[[Cycle of Hatred]]''\r\n*''[[Manual of Monsters]]''\r\n*''[[Alliance & Horde Compendium]]''\r\n*''[[Magic & Mayhem]]''\r\n*''[[Dragon Hunt]]''\r\n*''[[Shadows of Ice]]''\r\n*''[[Ghostlands (book)|Ghostlands]]''\r\n==World of hostilities==\r\n30\r\n*''[[World of Warcraft RPG]]''\r\n*''[[Lands of Mystery]]''\r\n*\r\n*''[[Alliance Player's Guide]]''\r\n*''[[Horde Player's Guide]]''\r\n*''[[Monster Guide]]''\r\n*''[[Dark Factions]]''\r\n31\r\n*''[[Rise of the Horde]]''\r\n*''[[World of Warcraft (Wildstorm comic)]]''\r\n*''[[Dragons of Outland]]''\r\n32",},
			["Timeline (from official site)"] = { content = "#REDIRECT [[Timeline (from official site, 2004)]]", redirect = "Timeline (from official site, 2004)",},
			["Timeline (from official site, 2007)"] = { content = "This a compilation of the official World of Warcraft timeline and story as based on [[Timeline (from official site, 2004)]] and updated on WorldofWarcraft.com on January, 16, 2007.",},
			["Timeline (RPG Books Chronology)"] = { content = "Most of the books in the [[Warcraft RPG]] are set in a specific chronological order. In many cases the exact chronological order is mentioned in each released book's introduction, or it can be deduced by information within the book. This article discusses the timeline created by the chronological order of the books, along with citations when available. This article is not concerned with the published order of the books but when they are chronologically set (or the furthest extent of its information).\r\n==RPG Book Timeline==\r\n*[[Dungeons & Dragons Warcraft The Roleplaying Game]] — One year after the Battle of Mount Hyjal, mortal races explore and settle the wild continent of Kalimdor. Increasing encounters with demons and undead suggest that the long years of battle are not over.... At the time Kalimdor is fresh from the Third War and the defeat of Grand Admiral Daelin Proudmoore’s attempt to destroy the orcs in Durotar. The book set mostly before The Frozen Throne, though briefly mentions the events of Admiral Proudmoore's attacks on the Orcs in Kalimdor as an event that has just happened or will soon happen.\r\n*[[Manual of Monsters]] covers information concerning the period around the time of The Frozen Throne (especially Appendix II).\r\n*[[Shadows & Light]] covers material from War of the Ancients up to just after the The Frozen Throne.\r\n*[[Alliance & Horde Compendium]] is set not long after the events of The Frozen Throne. The Forsaken have not yet joined the Horde. Malfurion is still in charge of the night elves (not yet in a coma).\r\n*[[Magic & Mayhem]] — Written by [[Han'al]], Master Lorekeeper of the Kirin Tor, it contains material set after [[The Frozen Throne]] up to the founding of Undercity.\r\n*[[Lands of Conflict]] — Written by Brann Bronzebeard, it appears to be set after Magic and Mayhem, after the events of The Frozen Throne. Undercity is already established, and Forsaken have begun to join the Horde. It appears to be concurrent with [[The Sunwell Trilogy]] Brann reaches Hillsbrad Foothills after the Forsaken have taken over Tarren Mill (after the first book), but reaches Quel'Thalas before the Blood Elves have taken it back (apparently before the third book).\r\n*[[World of Warcraft The Roleplaying Game]] — The events in The World of Warcraft RPG take place after those in Lands of Conflict. It is set about one year after Admiral Proudmoore's death, at the start of the MMO.\r\n*[[More Magic and Mayhem]] is largely set after World of Warcraft: The Roleplaying game, while it contains information from across the timeline, it mentions information from the period of the MMO.\r\n*[[Lands of Mystery]] — it is set more or less directly after Lands of Conflict, around the same year as \"World of Warcraft: The Roleplaying Game\". Brann's book covers material set before World of Warcraft MMO, but was finished at the start of the MMO.\r\n*[[Alliance Player's Guide]] appears to take place during World of Warcraft, has material that leads into [[The Burning Crusade]]. [[Varian Wrynn]] has not yet escaped imprisonment on [[Alcaz Island]].\r\n*[[Horde Player's Guide]] appears to take place during World of Warcraft, has material that leads into [[The Burning Crusade]], as well as some references to events leading into [[Wrath of the Lich King]]. The gates of Ahn'Qiraj have not yet been opened, but C'thun is starting to awaken. Rumors of Forsaken beginning to speak to a new faction (blood elves).\r\n*[[Monster Guide]]'s \"present\" appears to be set just before the reopening of the Dark Portal, and contains info that leads into [[The Burning Crusade]]. The gates of Ahn Qiraj have not yet opened, though there are rumors of an impending invasion. Blood elves and forsaken are starting to see eye to eye and may share the same goals as the Forsaken.\r\n*[[Dark Factions]] is set before TBC before the blood elves join the Horde. The gates of Ahn Qiraj have just been opened, and events of Naxxrammas patch are beginning. Forsaken and blood elves are almost allied.\r\n==Misc. notes==\r\n*The position of [[World of Warcraft The Roleplaying Game]] and [[Lands of Mystery]] is unclear. While the corebook is specific that it takes place after Lands of Conflict, it is unclear on if Lands of Mystery takes place before or after the corebook or if they overlap.\r\n*The position of the Monster Guide is somewhat unclear. It could fit just before Horde Player's Guide, during or just after. The references are fairly vague. While it talks of a possible impending invasion of the Qiraji, there is no mention of if C'thun has awakened yet. The discussion of impending invasions of the qiraji occur as early as Lands of Mystery, with no mention of C'thun awakening at those times. Horde Player's Guide is specific that C'thun has just awakened at the time of that book.\r\n*Alliance Player's Guide, Horde Player's Guide and Dark Factions (\"Independent Player's Guide\") represent miscellanious notes for a single school book Brann is planning to publish. They may represent notes he had written over the course of a year. The books were written specifically after Lands of Conflict and Lands of Mystery. Brann mentions that he is done covering the lands and wants to return to cover the various cultures.The introduction to each book mentions that he is revisiting many of the places from his previous books to learn more information about the various cultures.\r\n*The Alliance Player's Guide is definitely set before Horde Player's Guide. In the Horde Player's Guide Brann states that he already covered the Alliance material in the previous book, and is starting on sections covering the Horde (he refers back to Alliance Player's Guide many times throughout the book). In his introductory note in Dark Factions he mentions having already previously covered material in both the Alliance and Horde Player's Guides. He mentions that Dark Factions is his chance to cover the independent races. So generally speaking each player's guide takes place chronologically after the previous \"player's guide\" in the series. \r\n*However, some of the material may have been written around the same time by Brann, and may chronologically overlap. This is however not clear in the books.",},
			["Time anomaly"] = { content = "Time anomalies are fluctations in time often caused by outside sources. Bronze dragons keep track of time in order to prevent temperoral incursions from happening.\r\nA strange '''time anomaly''' surfaced during the War of the Ancients and nearly unmade creation. It may have been influenced through the desires of sleeping [[Old Gods]] who desired to be free at any cost. \r\nSeveral tunnels in the [[Caverns of Time]] lead to time anomalies caused by the [[Infinite dragonflight]]",},
			["Time to Visit the Caverns"] = { content = "==Objectives==\r\nTake your orphan, Dornaa, to stand before Zaladormu, the dragon on the dais in the middle of the [[Caverns of Time]]. Make sure to call for her if she is not present when you arrive.\r\nThen, purchase a [[Toy Dragon]] for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel. \r\n*Dornaa taken to the Caverns of Time\r\n* Toy Dragon\r\n== Description==\r\nIn the orphanage, the old priest that comes by told us stories about the [[Caverns of Time]]. He said that it sits in the middle of time, and is really important for keeping things straight.\r\nI don't know what that means, but he said that there were dragons there that were helping to save the world! I want to see a dragon!\r\nDo you think that we could go there? He said that the entrance was on the eastern edge of a great desert named Tanaris.\r\nMaybe you could buy me a souvenir while we're there? \r\n== Reward==\r\nYou will receive:\r\n== Progress==\r\nYou think it's true what they say about the Caverns of Time? \r\n== Completion==\r\nNeato! A dragon of my very own! One day I hope that I'm lucky enough to have a dragon as a friend.\r\n<Dornaa bounces up and down with joy, fiercely hugging her new toy.>\r\nThis has been the best trip ever! I hope it never ends. \r\n== Gains==\r\nUpon completion of this quest you will gain:\r\n*12650 [[XP]] (or 7 gold 59 silver copper at level 70)\r\n*250 [[reputation]] with [[Lower City]]",},
			["Timmanrug"] = { content = "'''Timmanrug''' was a [[pit lord]]. He dueled with [[Fraweth Whiteshield]] in the [[Third War]]. He has a wing hung limp, scarred and useless, due to a wound inflicted by the [[dwarf]] who lost an eye in the process. They agreed to meet once again some years later in the [[Blasted Lands]]. The two fought again and the battle was a bloody one: the [[paladin]] attacked the pit lord at the belly with his greataxe and the demon's burning blood burned up the knight's skin. After that, Whiteshield hit at the demon's front knees and Timmanrug responded with his fel warblade. It is unknown if anybody won or if they both died.",},
			["Timmy"] = { content = "'''Timmy''' is a neutral [[ghoul]] encountered by [[Arthas|Prince Arthas]] and [[Jaina Proudmoore]] in [[Andorhal]] in ''[[Warcraft III: Reign of Chaos]]'' during Chapter Four of the Human Campaign called \"[[Cult of the Damned]]\". Timmy is kept in a cage at the center of Andorhal and can be freed by destroying it. He can be killed and drops the [[Ring of Superiority]].",},
			["Timmy the Cruel"] = { content = "'''Timmy the Cruel''' is a level 58 [[elite]] [[ghoul]] [[mini-boss]] found in [[Stratholme]].\r\n==Strategy==\r\nTimmy spawns in the courtyard outside the Scarlet Bastion in Stratholme after you kill all the [[Scarlet Crusade]] NPCs in front of the entrance. He spawns immediately after the last death, and appears from the far left of the courtyard, so be careful not to add him and stay in the middle of the courtyard when fighting the Scarlet Crusade. He is a easy boss, but be warned, as he hits like a truck and can quickly take out cloth wearers.\r\n==Quotes==\r\n*\"TIMMY!\" - Yelled by Timmy the Cruel when he spawns in [[Stratholme]]. This is a reference to the character [[wikipedia:Timmy (South Park)| Timmy]] from [[wikipedia:South Park|South Park]].\r\n==Little Timmy speculation==\r\nIn Warcraft III there is a ghoul named [[Timmy]]. They could be the same. Some speculate that Timmy-ghoul was infact [[Little Timmy]], though Timmy can be seen in Warcraft III later in Undead campaign selling Ice Shards, and later on Theramore.",},
			["Timolain's Phylactery (old)"] = { content = "==Source==\r\n'''Timolain's Phylactery''' was a drop from the Large Vile Slime in the [[Weeping Cave]] of [[Western Plaguelands]] until [[Patch 1.7]] when it was removed from the game.\r\nSpeculation on the official forums led to the premature yet popular conclusion that Timolain is the wizard mentioned by [[Bardu Sharpeye]] and [[Alexia Ironknife]], and therefore the crafter of Ashbringer. It has since been revealed that [[King Magni Bronzebeard]] crafted the blade.",},
			["Timolain the Accursed"] = { content = "'''Timolain''' was a [[human]] [[mage]] commissioned by the [[Scarlet Crusade]] to create weapons. After he attempted to create a dark \"counterpart\" to the [[Ashbringer]], [[Grand Inquisitor Isillien]] killed him. However, Timolain had created a [[phylactery]], which eventually allowed him to resurrect as a [[lich]].\r\n==History==\r\nThe mage Timolain took up residency in [[Hearthglen]] after he was commissioned by the [[Scarlet Crusade]] to create powerful bows and guns to fight the [[undead]]. He once visited [[Prince Tortheldrin]] in [[Dire Maul]] and gave him a copy of [[A Complete Copy of \"Nat Pagle's Guide to Extreme Anglin'.\"]]. While there, he beseeched the prince for help, saying that he needed to fight fire with fire. When Timolain left, Tortheldrin presumed he went back to his allies.\r\nRumor says that the Scarlet Crusade killed him either while he was working on a remarkable weapon or after he had completed it. Two possible reasons for his murder were speculated: either the Crusade was just that distrustful of the [[arcane]], or he was killed to cover up evidence of his work.\r\nIn truth, Timolain had turned to [[necromancy]] and created a [[Shard of Darkness|dark crystal]], a counterpart of the holy artifact that fuels the [[Ashbringer]]. Before he could put it into a blade, [[Grand Inquisitor Isillien|Isillien]] fed Timolain to a [[Large Vile Slime|vile slime]]. During his long and excruciating demise within the slime, Timolain used his necromantic powers to bind himself to a phylactery and threw the crystal into the [[Thondroril River]].\r\nDuring the [[Burning Legion]]'s [[Third invasion of the Burning Legion|third invasion]] of [[Azeroth]], the slime was killed by the new [[adventurer|Highlord]] of the [[Knights of the Silver Hand]], allowing Timolain to revive from his [[Timolain's Phylactery|phylactery]]. With Timolain's help, the Highlord found and reclaimed the crystal.\r\n==Quotes==\r\nYou will find no fight here, paladin. I can do you no harm, and bear no allegiance to the dark creatures you seek to destroy.\r\nI suspect you know. We would not be meeting otherwise.\r\nMy story is simple. The [[Alexandros Mograine|original wielder]] of your blade proved unable to stand against the endless throngs of undead that threatened our world.\r\nI sought a different approach... one that could not fail.\r\nI devised a way to fight the [[scourge]] using their own magic against them. It was a simple process, really - I had a veritable river of souls at my disposable from the [[Lich King]]'s rampage.\r\nIn the end, I created a counterpart to the holy relic that fuels the Ashbringer's strength, but before I could properly seat it within a suitable blade I was found out by Isillen and his dogs.\r\nThe rest, as they say, was excruciatingly painful.\r\nBefore I was devoured ever so slowly I did two things.\r\nThe first, as should be obvious, was putting my necromantic learnings to the test, sealing my soul within the phylactery you found. It did nothing for the pain of death... but it has served its purpose.\r\nAfterward, as I was already half-consumed by the creature, I hurled the crystal into the river beside you in hopes that someone might still put it to use against the forces of darkness.\r\n<The lich's face contorts into something of a smile.>\r\nIf you seek it, you will find it there.\r\n==Notes==\r\n*Prior to ''[[World of Warcraft: Legion|Legion]]'', the name \"Timolain\" existed only in the item name [[Timolain's Phylactery (old)]], an item on the loot table of [[Large Vile Slime]]s in vanilla. At the time, it was believed [[Ashbringer]] could be obtained by players, and rampant speculation led to the persistent belief that the bugged item and Timolain were somehow connected to the sword. Blizzard created a questline in ''Legion'' based on this player speculation.\r\n**Bardu and Alexia have referenced a \"wizard\" since [[World of Warcraft|vanilla]] but didn't mention Timolain by name.",},
			["Timothy Jones"] = { content = "'''Timothy Jones''' is a level 45 [[human]] [[jewelcrafting trainer]] and [[quest giver]] in [[Dalaran]].\r\nHe starts the following quests:\r\n* Finish the Shipment\r\n* Shipment: Blood Jade Amulet\r\n* Shipment: Intricate Bone Figurine\r\n* Shipment: Glowing Ivory Figurine\r\n* Shipment: Wicked Sun Brooch\r\n* Shipment: Shifting Sun Curio\r\n* Shipment: Bright Armor Relic\r\nSee [[Dalaran NPCs]].",},
			["Tin"] = { content = "[[Tin]] is the second-easiest [[metal]] to [[mining|mine]]. Tin [[vein]]s also produce [[gem]]s and, more frequently, [[Coarse Stone]]. Tin ore is smelted into [[Tin Bar]]s at the [[forge]]. In turn, one tin bar can be smelted with one [[copper]] bar to make two [[bronze]] bars.\r\n* Mined at [[Mining]] 65\r\n* Yellow to green at Mining 115\r\n===Gems Mined===\r\n* [[Coarse Stone]]\r\n* [[Blood Shard]]\r\n* [[Moss Agate]]\r\n* [[Shadowgem]]\r\n* [[Lesser Moonstone]]\r\n* [[Jade]]\r\n==See also==\r\n*[[Tin Ore]]\r\n*[[Tin Bar]]",},
			["Tinhead"] = { content = "'''Tinhead''' is a mechanical boss in the Opera House in [[Karazhan]], accompanied by Dorothee, Roar, Strawman, Dorothee's pet Tito, and followed by The Crone.\r\n==Abilities==\r\n*'''Basic Melee''' - 1500 to 2000 on plate.\r\n*'''Cleave''' - 5 yd range. Instant. Inflicts Physical damage to an enemy and its nearest allies, affecting up to 3 targets. Around 4000 damage to cloth.\r\n*'''Rust''' - Slow speed by 10%, stacking 8 times. It is considered a buff, so it can be purged. This is a purely scripted effect. A tank should hold aggro until Tinhead is sufficiently Rusted to kite.\r\n==Strategy==\r\nContrary to popular (and incorrect) belief, Frost spells and [[Sunder Armor]] have '''no''' effect on the rusting of Tinhead. \r\n'''Only time allows the stacking of more Rust on Tinhead. It is a time scripted buff.''' \r\n30 seconds after Dorothee spawns Tinhead will gain the first Rust, and will stack another every 6 seconds afterwards until 8 applications. He remains slowed forever.\r\n'''''Update''': Since patch 2.3, it is not possible to use Detect Magic on Tinhead, as the spell no longer exists. '''However''', enemy buffs appear without the Detect Magic being applied.''\r\nTanks: his [[Cleave]] can kill casters and melee, so either ask for space or run back and forth between the walls, using whatever threat generating abilities you have as you run past. ( [[Mangle]], [[judgment]], [[Sunder Armor]]) As more of the other adds go down, you'll find that you have more and more space to move him around.\r\n '''''Useful tip''': Kill Tinhead last, while kiting him. He's a good source to regen some mana as well. Tinhead can easily be wanded to death.''\r\n '''''Useful tip''': If you have a paladin in your group, he can judge [[Seal of Justice]] on Tinhead as soon as he spawns to slow him immediately to normal movement speed.''\r\n==Quotes==\r\n'''Aggro:''' ''I could really use a heart. Say, can I have yours?''\r\n'''Killing A Player:''' ''Guess I'm not so rusty, after all.''\r\n'''Death:''' ''Back to being an old rustbucket.''",},
			["Tinkee Steamboil"] = { content = "'''Tinkee Steamboil''' is a level 53 [[quest giver]] located at [[Flame Crest]] in the [[contested]] territory of [[Burning Steppes]].\r\nShe starts the following quests:\r\n* Broodling Essence\r\n* Felnok Steelspring\r\n* Egg Freezing (Raid)\r\n* Egg Collection (Raid)\r\n* Leonid Barthalomew\r\nSee [[List of Burning Steppes NPCs]].",},
			["Tinkee Steamboil (quest)"] = { content = "==Objectives==\r\nSpeak with Tinkee Steamboil.\r\n==Description==\r\nHi, <name>. Remember Tinkee Steamboil? Well, she remembers you! She sent me a message to keep an eye out for you, because... she needs your help again. I think it has something to do with her studies on dragons.\r\nYou should speak to her in the Burning Steppes, at the Flame Crest.\r\n==Completion==\r\nFelnok was right! I do need your help again, and this time... it's going to be really dangerous.\r\nAre you ready??",},
			["Tinker"] = { content = "'''Tinkers''' are among the smartest of the adventurers setting out to explore and conquer [[Azeroth]]. The creators of incredible inventions from crazy multipurpose knives, steam saws, to siege engines, their devices allow them to overcome nearly any situation - and if they don't have the device they need, they just might be able to design and create a new one on the spot. Tinkers have a reputation for being dangerous companions, born mainly of reckless goblins experimenting with explosives. However, tinkers are not usually danger-prone. The real problem arises when they mess with gunpowder or try to build a better steam engine, and even then mishaps and explosions do not occur as often as many believe. However, the true heart of the tinker profession can be found in the steady craftsmanship of the dwarves and the wild-eyed curiosity of the gnomes. As tinkers begin to spread to all the races of Azeroth, the idea of the \"typical tinker\" may continue to change, but inventiveness and intelligence will always be an important part. Tinkers are most commonly found among the [[dwarves]], [[gnome]]s and [[goblin]]s, as they produce [[rifle]]s, [[zeppelin]]s, and other technological innovations currently found on Azeroth. With their general disinterest in [[technology]], night elves, orcs and tauren are the least likely to be tinkers. \r\nTinkers tend to carry about packs and pouches full of heavy tools, spare parts and inventions both finished and incomplete. In doing so, they quickly develop the ability to shoulder casually otherwise crushing burdens.\r\nA tinker can put together devices out of random piles of spare parts or whatever wires and gears he happens to be carrying in his pockets at the time.\r\nTinkers prefer to spend days, weeks or even months constructing the devices they design. When adventuring, though, tinkers are often forced to throw together a device more quickly.\r\nA tinker learns an esoteric technique developed by mad goblin tinkers and passed along to their brethren — the art of bomb throwing.\r\nA tinker has employed his skills in dangerous situations often enough that he learns how to remain calm in combat even when operating complex controls or working to repair delicate machinery.\r\nTinkers are exposed to raw and powerful energies in the course of their work, and often develop a degree of resistance to one kind or another.\r\nThe most experienced tinkers become [[epic tinker]]s.\r\n===Gnome Tinker===\r\n[[Gnome]]s are the Alliance's consummate tinkers. When a member of the Alliance thinks of a tinker, he thinks of a gnome; and when he thinks of a gnome, he thinks of a tinker. Gnomes are in a competition with goblins to produce the best and deadliest technology - a competition that is friendly or fierce, depending on the individuals involved. Gnomish technology is not quite as prone to malfunction as goblin technology, and gnomes tend to produce devices that have more specialized and unusual effects. Goblins make goblin rockets and shredders - fairly straightforward - while gnomes create gnomish shrink rays and universal remotes. The iconic gnome tinker is a mad inventor, wearing goggles on her head as well as over her eyes, with a bandolier of equipment slung over each shoulder; she is covered with oil and scorch marks, looking forward to the next invention. Many find gnome tinkers amusing, but only a few do not also respect or fear them.\r\n===Goblin Tinker===\r\n[[Goblin]]s are known for their mechanical expertise and clever, though sometimes peculiar, inventions, and the Tinker is certainly no exception. With his Claw-Pack/Hammer-Tank combo, the Tinker's ingenuity is undeniable. Though his parts may sometimes fail and the occasional explosion does occur, the spirit and enthusiasm of this Hero are never diminished. There truly is more to the Goblin Tinker than meets the eye!\r\n==Famous/Named==\r\n*[[Alwys Cogspin]]\r\n*[[Blamblaster]]\r\n*[[Brightflame Masjenal]]\r\n*[[Brymidaine Zecker]]\r\n*[[Devonix]]\r\n*[[Director Riddlevox]]\r\n*[[Felya Waterfinder]]\r\n*[[Fleeto]]\r\n*[[Gelbin Mekkatorque]]\r\n*[[Hartargan Stark]]\r\n*[[Heffen Glitterbows]]\r\n*[[Irk Gaffestone]]\r\n*[[Izzik Threshbin]]\r\n*[[Jocas Irongear]]\r\n*[[Jode]]\r\n*[[Kem]]\r\n*[[Klink Pakkuri]]\r\n*[[Lenaeas]]\r\n*[[Makil]]\r\n*[[Mogul Razdunk]]\r\n*[[Neevil]]\r\n*[[Nuji Kodosbreath]]\r\n*[[Oirc Steeltoes]]\r\n*[[Pac Seecrek]]\r\n*[[Razz Wheeler]]\r\n*[[Rezlak]]\r\n*[[Ryona Blondbeard]]\r\n*[[Samuel Wrenchwright]]\r\n*[[Sari Stoneheart]]\r\n*[[Shanger]]\r\n*[[Sicco Thermaplugg]]\r\n*[[Siflaed Coldhammer]]\r\n*[[Sputtervalve]]\r\n*[[Tigore]]\r\n*[[Tinkerwiz]]\r\n*[[Tinkerer Gizlock]]\r\n*[[Tinkerer Sniggles]]\r\n*[[Wallace Boltscrew]]\r\n*[[Widge Whistlevalve]]\r\n*[[Wrench Blackboot]]\r\n*[[Ziggler]]\r\n*[[Zim the Mad]]\r\n*[[Ziz Fizziks]]\r\n===Others===\r\nGazz Stripbolt, Mekka Gobb, Riket Contraption, Plug Rattletrap, Ratso Steamwheedle,Tek Piecetinker\r\n''Note: Many of these names come from random goblin tinkers in The Frozen Throne.''\r\n==Tinkers in WoW==\r\n*[[Deathforge Tinkerer]]\r\n*[[Fel Tinkerer Zortan]]\r\n*[[Gan'arg Tinkerer]]\r\n*[[Gan'arg Warp-Tinker]]\r\n*[[Mechanar Tinkerer]]\r\n*[[Tinkers' Union]]\r\n*[[Venture Co. Tinkerer]]",},
			["Tinkerer Gizlock"] = { content = "'''Tinkerer Gizlock''' is a level 50 [[elite]] [[goblin]] [[mini-boss]] found in inner [[Maraudon]].\r\n==Abilities==\r\nHe can use a goblin dragon gun during the fight. This is a [[channel]]ed effect, so you can back away from him and he won't follow you while he's breathing fire.\r\nAs of patch [[1.11]], \"Tinkerer Gizlock can now throw Flash Bombs.\"\r\n==Quotes==\r\n*Mine! Mine! Mine! Gizlock is the ruler of this domain! You shall never reveal my presence!",},
			["Tinkerer Sniggles"] = { content = "'''Tinkerer Sniggles''' can be found in [[The Barrens]] .\r\n==Drops == \r\n \r\n1.61% Chance of an [[Uncommon]] drop.\r\n0.47% Chance of a [[common]] drop.\r\n1.52% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Tinkers' Union"] = { content = "The '''Tinkers' Union''' is a of of [[Goblin]] [[tinker]]s (also known as [[Engineers]]). It is assumed that the Tinkers' Union headquarters is a major portion of the goblin capital of Undermine. The current leader of the Tinkers' Union is Director Riddlevox of Undermine.\r\nThe Tinkers' Union is at war with the gnomes and dwarves, the Tinkers’ Union deals with technology and the construction of gizmos, weapons and mechanical monstrosities. Director [[Tek'zik Riddlevox]], overseer of the Undermine Tinkers’ Union, runs the union.\r\nNotable members:\r\n* [[Director Riddlevox]] (leader) in [[Undermine]]\r\n* [[Sputtervalve]] in [[Ratchet]]\r\n* [[Rezlak]] in [[Orgrimmar]]\r\n* [[Ziz Fizziks]] in [[Windshear Crag]]\r\n* [[Samuel Wrenchwright]]",},
			["Tinkerwiz"] = { content = "'''Tinkerwiz''' is a level 25 [[artisan]] [[engineering trainer]] located in [[Ratchet]] in the [[Horde]]-aligned territory of the [[Barrens]].\r\nHe starts the following quests:\r\n* Gnome Engineering (Engineering)\r\n* Goblin Engineering (Engineering)\r\nSee [[List of the Barrens NPCs]].",},
			["Tinker Town"] = { content = "Originally, '''Tinker Town''' was just a small quarter of the city for [[gnome]]s visiting from [[Gnomeregan]] to use. Since the fall of their clockwork city, it has become the center of the gnomish court in exile (the [[Gnomeregan Exiles]]). [[High Tinker Mekkatorque]] can be found here, along with his closest advisers. It is also home to a number of [[Alchemy]] and [[Engineering]] trainers, as well as the entrance to the famed [[Deeprun Tram]].\r\nTo get to '''Tinker Town''', you can head north from [[the Military Ward]], south from the [[Hall of Explorers]], or get off the [[Deeprun Tram]] at the Ironforge station.",},
			["Tinkmaster Overspark"] = { content = "'''Tinkmaster Overspark''' is a level 57 [[artisan]] [[gnomish engineering]] [[engineering trainer|trainer]] located in [[Tinker Town]] in the [[dwarf]] city of [[Ironforge]].\r\nHe starts the following quests:\r\n* Save Techbot's Brain! (Dungeon)\r\n* The Pledge of Secrecy (Ironforge) (Engineering)\r\n* Show Your Work (Gnome) (Engineering)\r\n==Recipes==\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\nSee [[List of Ironforge NPCs]].",},
			["Tiny Crimson Whelpling"] = { content = "The '''Tiny Crimson Whelpling''' item summons and dismisses a Tiny Crimson Whelping, a [[dragon whelp|dragon whelpling]] [[small pet]] that follows you around, meaning it is a non-combat pet and will not aid you in battle. \r\nPatch 2.4: Sound effects added.\r\n==Source==\r\nTiny Crimson Whelpling drops from [[Crimson Whelp]]s, [[Flamesnorting Whelp]]s, and [[Red Whelp]]s in the [[Wetlands]]. There are also [[Lost Whelp]]s in the general area but they do ''not'' drop this pet.\r\nThe level of these Whelps range in the mid-20s, so this is the first Whelpling pet new characters can have the chance of obtaining, and also the easiest for higher level characters to [[farming|farm]].\r\n==Notes==\r\nThe drop rate of this pet is roughly 0.1% (one in every thousand kills) and takes an incredible amount of patience and determination in order to get one. Due to the difficulty of obtaining one, and thus their rarity, they can sell for fairly large amounts of gold on the [[Auction House]], at least as far as pets are concerned.\r\nThe chances of getting at least one—at a 0.1% drop rate—are listed below:\r\n==See also==\r\n* Dark Whelpling\r\n* Tiny Emerald Whelpling\r\n* Azure Whelpling",},
			["Tin Bar"] = { content = "A '''Tin Bar''' is a solid bar of tin metal crafted by [[Mining|Miners]].\r\nIt is used in the creation of [[Bronze Bar]]s.\r\n==Source==\r\nThis item is crafted by [[Mining|Miners]] with a skill level of 65. Smelting Tin stops giving skillups to Mining at 75.\r\nThe miner must be at a [[forge]] to smelt the ore into bars.\r\n==As an ingredient==\r\nThe only known use for Tin Bars as an ingredient is in the production\r\nof [[Bronze Bar]]s.\r\n==As a quest objective==\r\nDuring the [[Gates of Ahn'Qiraj|Opening of the Gates of Ahn'Qiraj]] event Tin bars were required for the following quests as part of the war effort:\r\n* [[The Horde Needs Tin Bars!]]\r\n* [[The Horde Needs More Tin Bars!]]\r\n==See also==\r\n*[[Bronze]]",},
			["Tin Ore"] = { content = "'''Tin Ore''' is the second-easiest [[ore]] to [[mining|mine]]. It is mined from [[Tin Vein]]s. You need 65 [[mining]] skill to mine it. It's mostly used to create the metal alloy [[bronze|Bronze]].\r\n==XP Table==\r\nThe values between ( and ) are for Tauren.\r\n==Sources==\r\n[[Tin Vein]]s may be found in many starting areas where the typical creature level is between about 18 and 30. Tin stops giving skillups to Mining at 165.\r\nThe most common zones to have Tin are:\r\n* [[Ashenvale]]\r\n* [[Darkshore]]\r\n* [[Ghostlands]]\r\n* [[Hillsbrad Foothills]]\r\n* [[Loch Modan]] (In the Northeastern corner where all the Ogres are)\r\n* [[Northern Barrens]]\r\n* [[Northern Stranglethorn]]\r\n* [[Redridge Mountains]]\r\n* [[Silverpine Forest]]\r\n* [[Stonetalon Mountains]]\r\n* [[Westfall]]\r\n* [[Wetlands]]\r\n===Also found in Tin Veins===\r\n* [[Coarse Stone]]\r\n* [[Blood Shard]] - The Barrens Only\r\n* [[Moss Agate]]\r\n* [[Shadowgem]]\r\n* [[Lesser Moonstone]]\r\n* [[Jade]]\r\n==As an ingredient==\r\nTin Ore is smelted into [[Tin Bar]]s at a [[forge]], requiring a [[mining]] skill of at least 65.\r\nTin Bars are used in the production of [[Bronze Bar]]s.\r\nTin Ore can be [[prospecting|prospected]] (consuming 5 ore) with a [[Jewelcrafting]] skill of 65 or more, resulting in:\r\n* [[Shadowgem]] (57%)\r\n* [[Lesser Moonstone]] (50%)\r\n* [[Moss Agate]] (21%)\r\n* [[Citrine]] (3%)\r\n* [[Jade]] (3%)\r\n* [[Aquamarine]] (3%)\r\n==Notes==\r\n[[Silver Vein]]s may occasionally be found in place where Tin Veins usually occur.\r\n==See also==\r\n* [[Tin Bar]]",},
			["Tin Vein"] = { content = "'''Tin Veins''' can be found primarily in zones that have a minimum level of 10, 15, or 20.\r\n==Contents==\r\nWith [[Mining]] (1) in retail or Mining (65) in ''[[World of Warcraft: Classic|Classic]]'', these veins can be looted for:\r\n*[[Tin Ore]] (guaranteed)\r\n*[[Coarse Stone]] (common)\r\n*[[Lesser Moonstone]] (rare)\r\n*[[Moss Agate]] (rare)\r\n*[[Shadowgem]] (rare)\r\n*[[Jade]] (very rare)\r\n===Quest items===\r\nTin Veins in certain locations can also contain [[quest]]-related items:\r\n*[[Underlight Ore]] - [[Underlight Mines]], [[Ghostlands]]\r\n*[[Blood Shard]] - The [[Barrens]]\r\n*[[Rethban Ore]] - [[Rethban Caverns]], [[Redridge Mountains]]\r\n==Locations==\r\nKalimdor\r\n*[[Ashenvale]]\r\n*[[Talrendis Point]], [[Azshara]]\r\n*Northwestern [[Bloodmyst Isle]]\r\n*Southern [[Darkshore]]\r\n*[[Desolace]] (''Classic'' only)\r\n*Central and northern [[Dustwallow Marsh]]\r\n*The [[Dry Hills]], [[Northern Barrens]]\r\n*[[Stonetalon Mountains]]\r\n*[[Thousand Needles]]\r\nEastern Kingdoms\r\n*[[Arathi Highlands]]\r\n*[[Duskwood]]\r\n*Southern [[Ghostlands]]\r\n*[[Hillsbrad Foothills]]\r\n*Midwest and eastern [[Hinterlands]]\r\n*[[Loch Modan]]\r\n*[[Northern Stranglethorn]]\r\n*[[Redridge Mountains]]\r\n*Southern [[Silverpine Forest]]\r\n*[[Wetlands]]\r\n*The [[Deadmines]], [[Westfall]]\r\n**[[Jangolode Mine]]; [[Gold Coast Quarry]]; and [[Dagger Hills]], Westfall (''Classic'' only)",},
			["Tipsy"] = { content = "'''Tipsy''' is a condition that can affect players. You become tipsy when you [[drink]] an adult beverage like [[pinot noir]], [[dwarven stout]], or the mind-numbingly potent [[Darkmoon Special Reserve]]. The effect depends on the strength of the drink. Effects may include blurred vision and random turning when you try to move. In addition, being tipsy causes mobs to appear to be a lower level than they actually are (the apparent level reduction being greater the more drunk you are), impairing your judgment when choosing targets. \r\nContinuing to drink strong beverages after becoming tipsy can make a player [[drunk]].",},
			["Tiragarde Keep"] = { content = "The only [[Alliance]] outpost in [[Durotar]], '''Tiragarde Keep''' is manned by soldiers loyal to Admiral [[Daelin Proudmoore]]. Since Daelin’s death, they have continued their crusade against the [[Horde]]. While [[Jaina Proudmoore]] does not approve of their actions, the majority of the Alliance accepts the dangerous philosophy of these troops. They are almost as fanatical and determined as the [[Scarlet Crusade]]. It's believed that Thrall hasn’t sent troops to attack the outpost out of mercy, and that may prove a strategic mistake. The small fortress is home to about 200 Kul Tiras soldiers.\r\nDespite the peace agreement founded by [[Warchief]] [[Thrall]] representing the [[orcs]] and Lady Proudmoore representing the [[humans]], both races retained underlying suspicions of the other. There were even those who continued to hold onto old hatreds. One particular human, who also happened to be the father of Jaina, led his naval fleet from [[Kul Tiras]] to the shores of Durotar. There, Admiral Proudmoore hastily constructed Tiragarde in a glaring violation of the treaty. This one event is said to have started a domino effect that led to the breaking-down of relations between the Alliance and the Horde that we all struggle through today.\r\nThough Jaina was forced to sit back and watch the orcs slay her father in battle in order to reassure them of her intention to continue honoring the peace agreement, a set of special orders written by the Admiral before his departure from Kul Tiras has recently come into effect. With no word from Proudmoore's fleet since their arrival on [[Kalimdor]], [[Lieutenant Benedict]] and [[Watch Commander Zalaphil]] have been dispatched to retake the keep and guard it from the orcs who wish to finish tearing it down.\r\nThe damaged keep still stands today, a gleaming white structure distinctly out of place among the crimson rocks of Durotar. Benedict rules over this tiny parcel of land, and the [[Kul Tiras Marine]]s and [[Kul Tiras Sailor|Sailors]] patrolling the crumbling ramparts are well-trained and filled with contempt for the Horde. A letter in an early horde quest shows that the Kul Tiras are there to finish what Daelin started, that is invade Durotar and kill all the orcs. It is also said that [[Lieutenant Alverold]] is destined to return to finish what Daelin started.",},
			["Tirion"] = { content = "#REDIRECT [[Tirion Fordring]]", redirect = "Tirion Fordring",},
			["Tirion Fordring"] = { content = "'''Tirion Fordring''' was one of the first five [[Knights of the Silver Hand]] selected by Archbishop [[Alonsus Faol]], and was one of the heroes of the [[Second War]]. He later became Lord of [[Mardenholde Keep]] in [[Hearthglen]] before being stripped of his title and exiled for defending an orc, [[Eitrigg]]. Following the recent death of his son [[Taelan Fordring]], Tirion committed himself to refounding the order of the Silver Hand. He now leads the Argent Crusade, an organization consisting of the old Knights of the Silver Hand and the Argent Dawn, against the Lich King and the [[Scourge]]. To this day he remains good friends with the orc veteran Eitrigg.\r\n===Eitrigg incident===\r\nAs the governor of the Alliance principality of Hearthglen, Tirion lived a comfortable life, well-respected by subjects and loved by his wife [[Karandra Fordring|Karanda]] and son Taelan. Both a great warrior and a just ruler, Tirion was renowned throughout the Kingdom of Lordaeron. In spite of his acclaimed military prowess, Tirion's experience as a Paladin during the orcish invasions have taught him to value peace. After the wars were over, every night Tirion prayed that no conflict would ever bring harm to his subjects again. \r\nOne day, he encountered an old orc hermit living in an abandoned tower. The two immediately battled, and they traded blows until a piece of the ruined tower collapsed on Tirion, knocking him senseless. He awoke in his bed days later, and discovered that he had been found, badly beaten, tied to his saddle, and had been healed by his ambitious second, [[Barthilas]]. \r\nRealizing that the orc had saved him, Tirion set out and retraced his steps back to the tower. The orc, [[Eitrigg]], told Tirion that before the coming to [[Azeroth]], the orcs had been a noble society rooted in [[shaman]]ism. After the war, he had left the corrupt [[Horde (pre-Thrall)|Horde]]. Tirion, seeing great honor in Eitrigg, promised to keep his existence a secret, returning to his people and informing them that the orc had been dealt with and was not a threat. \r\nBarthilas was not so confident, and called [[Saidan Dathrohan]] to come and settle the matter himself. Dathrohan picked up the trail and led a group of hunters into the woods, where they found Eitrigg. During the orc's capture, Tirion fought against Dathrohan's men, prompting Barthilas to gleefully note that his actions were treasonous. Tirion was brought to [[Stratholme]] to stand trial.\r\nDespite Karandra's pleas to forget his honor and tell the jury what they wanted to hear, Tirion, hoping to be an example to his son, told the court exactly what had happened. Ultimately, the jury of Admiral [[Daelin Proudmoore]], Arch-Mage [[Antonidas]], Archbishop [[Alonsus Faol]] and Prince [[Arthas Menethil]] decided that since Tirion had assaulted [[Alliance of Lordaeron|Alliance]] soldiers, he could no longer be a member of the Silver Hand, and was doomed to exile. [[Uther Lightbringer|Uther the Lightbringer]] performed a ceremony to strip Tirion of his powers and sent him home to gather some supplies. \r\nDesperate to prevent Eitrigg from being executed for war crimes, Tirion rode back to Stratholme, where he attacked Eitrigg's guards. Surprised, they still managed to subdue him, until a group of orcs stormed into the city. Tirion used the distraction to free Eitrigg and flee the city.\r\nWhen they were in the wilds, Tirion saw that Eitrigg was near death, and did the only thing he could do, call upon the powers of the Light to heal the orc who had saved him. To his surprise, he still had the powers blessed by the [[Light]], and Eitrigg was saved.\r\nThey abruptly found themselves surrounded by orcs, and a new [[Warchief]], [[Thrall]] approached Eitrigg and invited him back into the [[Horde]], which had since reverted back to its shamanistic roots once more. Eitrigg was thrilled to accept.\r\nTirion remained in Lordaeron, to watch his son Taelan be inducted into the Silver Hand. His son later became the lord of Mardenholde. Tirion's wife told his son that Tirion had died, and even took him to a false grave at the [[Undercroft]], where Taelan buried the toy warhammer his father had given him in memory of his father.\r\n'''See also:''' [[Of Blood and Honor]]\r\n===Exile and Return===\r\nTirion lived out his exile in a small farmstead, in the northwest of what became the [[Eastern Plaguelands]], on the shores of the [[Thondroril River]] with his trusty horse, [[Mirador]]. During the [[Third War]] he often fought off the undead Scourge.\r\nHe was dismayed to find later that his son, [[Taelan]], joined the [[Scarlet Crusade]], and even became the highlord of that order. Nonetheless, he kept watching his son from afar, and even enlisted some adventurers to help him as he and a few Crusaders became trapped in the small village of [[Cinderhome]], surrounded by Scourge forces who were interrupting the Crusade's attempt to re-settle the area. Later, Tirion turned to adventurers yet again to have them collect mementos of his son's past, which finally enabled him to convince his son to leave the Crusade, only to see him killed in the attempt. Spurred by his son's death, Tirion resolved to reform the original Silver Hand as a force of good in the world.\r\n==World of Warcraft==\r\n'''Tirion Fordring''' is a level 61 [[elite]] [[quest giver]] located by a cottage near the southwestern end of the [[Terrorweb Tunnel]] in the [[contested]] territory of [[Eastern Plaguelands]]. He readily accepts help from both the [[Horde]] and Alliance in his quest line, in following his assertions that race does not dictate honor, and from what he learned from his encounter with Eitrigg.\r\nHe starts the following quests:\r\n*Blood Tinged Skies\r\n*Carrion Grubbage\r\n*Demon Dogs\r\n*Redemption\r\n**Of Forgotten Memories\r\n**Of Lost Honor\r\n**Of Love and Family\r\n***Find Myranda\r\n===The Burning Crusade===\r\nIn [[World of Warcraft: The Burning Crusade|The Burning Crusade]], '''Tirion Fordring''' can be found in the [[Old Hillsbrad Foothills]] via the [[Caverns of Time]] as a level 55 NPC. Tirion can be seen in the [[Southshore]] inn wearing the same plate chest he wears nowadays and discussing [[Ashbringer]] with several of his fellow members of the [[Silver Hand]]. He was the first to refer to the future weapon by its legendary name. Sadly, most of the friends assembled here would later turn to bitter enemies, as they embraced the zeal of the Crusade they would later create.\r\n====Death Knight quest chain involvement====\r\nIn The Light of Dawn, the last quest of the [[death knight]] starting area, the player joins [[Highlord Darion Mograine]] leading ten thousand Scourge against three hundred defenders of the Light at the [[Battle for Light's Hope Chapel]]. After a hundred or so defenders die, Tirion appears to confront Darion. [[Alexandros Mograine]], Darion's father, also makes an appearance.\r\nAfter an interaction between Darion and Tirion, then Darion and Alexandros, the Lich King will appear and cast a spell that incapacitates Tirion. Darion, wielding the [[Corrupted Ashbringer]] once held by his father, tosses the sword to Tirion where it is seemingly purified. Tirion then charges towards Arthas, who runs and eventually escapes. It is here that Tirion makes his vow to destroy Arthas, uniting the Argent Dawn and the Knights of the Silver Hand into the Argent Crusade. Darion also pledges his [[Knights of the Ebon Blade]] to the cause.\r\n==Personality==\r\nAs a paladin, Tirion Fordring was a man of honor — and his commitment to upholding his honor no matter the cost often brought him into conflict with his family and friends. His wife [[Karandra Fordring]] often lamented the sacrifices she had to make in order to adapt to her husband's tendency to place his personal honor above everything else - his family included. So, for instance, when Fordring attempted to explain to his wife and to his long-time friend [[Arden]] that his commitment to saving the life of Eitrigg was a matter of honor, he encountered, for the most part, a total lack of understanding, with both Arden and Karandra arguing that he also has a responsibility to his family and his subjects — a responsibility he should not neglect in the name of honor. Tirion's honor, therefore, was the ultimate cause of his downfall — during his trial, he was offered an opportunity to be restored to good standing within the Alliance if only he would renounce the vow he gave to Eitrigg. Tirion refused, saying that his honor precluded him from doing so.\r\nIn the end, Tirion Fordring paid heavily for the honor he held in high such esteem. Not only was he stripped of his office and estates, but his family — Karandra Fordring and [[Taelan]] — refused to accompany him into exile, stating that she would not let him ruin their lives as he had ruined his own. Thus, after his rescue of Eitrigg from the gallows in [[Stratholme]], honor was very much the only thing Tirion still had.\r\n==Memorable Quotes==\r\n* \"You are assuming that there are more orcs out there, [[Barthilas]]. I was there, and I saw none. I will not sound the call to arms before we've confirmed the facts. This is not the time to start jumping at shadows. We must remain calm and vigilant.\"\r\n* Taelan: \"Are you going to fight the green men, Poppa?\"\r\nTirion: \"I don't know yet, son. I just don't know.\"\r\n* \"I will remain committed to the [[Alliance]] until my dying day. Of that, have no doubt. But I cannot disavow the oath I took. To do so would be to betray everything I am and everything we, as honorable men, hold dear.\"\r\n* \"May your soul burn in anguish, [[Isillien]]! Light give me strength to battle this fiend. Face me, coward. Face the faith and strength that you once embodied.\"\r\n* \"Too long have I sat idle, gripped in this haze... this malaise, lamenting what could have been... what should have been. Your death will not have been in vain, [[Taelan]]. A new Order is born on this day...an Order which will dedicate itself to extinguishing the evil that plagues this world. An evil that cannot hide behind politics and pleasantries. This I promise...This I vow...\"\r\n* \"Say hello to my little friend.\" — When attacking a mob.\r\n===Tirion's Story in His Own Words===\r\nAfter completing his first three quests, this conversation opens with Tirion, as part of the next quest in his chain:\r\n''I must apologize for not being entirely truthful with you in regards to my identity. I had to be certain you could be trusted — few people would have selflessly lent assistance to an old and forgotten hermit.''\r\n''You have proven yourself as one of those people: A person of integrity and honor.''\r\n'''Thank you, Tirion. What of your identity?'''\r\n''My son, Taelan, was only a child when I was found guilty of treason and banished by the Alliance to live a life in exile. I chose to remain here so that I could watch over him; to somehow insure that he would grow up an honorable man.''\r\n''As I had hoped, he took my place as lord of Mardenholde; but in a cruel twist of fate, joined the ranks of the Scarlet Crusade. He is now their Highlord, <race>.''\r\n'''That is terrible.'''\r\n''Indeed. The Scarlet Crusade are an aberration of the Order of the Silver Hand.''\r\n''You must believe me, <race>; Taelan is a good man. He needs to remember...remember what it is to be noble and honorable. I know that in his heart, he knows what he does is wrong. Will you help him? Will you help him remember?''\r\n'''I will, Tirion.'''\r\n===Talking with Darion at the Argent Vanguard in Icecrown===\r\nHighlord Tirion Fordring says: The Lich King reacted swiftly to the breach. Faster than I anticipated.\r\nThe Ebon Watcher says: You are dealing with a being that holds within it the consciousness of the most cunning, intelligent, and ruthless individuals to ever live.\r\nThe Ebon Watcher says: The Lich King is like any foe that you have ever faced, Highlord. Though [[Battle for Light's Hope Chapel|you bested him]] upon the holy ground of [[Light's Hope Chapel]], you tread now upon his domain.\r\nThe Ebon Watcher says: You cannot win. Not like this...\r\nHighord Tirion Fordring says: What would you have me do, [[Darion Mograine|Darion]]?\r\nThe Ebon Watcher says: Nothing. There is nothing that you can do while the [[Light]] binds you. It controls you wholly, shackling you to the ground with its virtues.\r\nHighlord Tirion Fordring says: Choose your words wisely, [[death knight]]. You stand amidst the company of the devoted.\r\nThe Ebon Watcher shakes his head.\r\nThe Ebon Watcher says: Look upon the field, Highlord. The Lich King has halted your advance completely and won the upper hand!\r\nThe Ebon Watcher says: The breach you created was sealed with [[Nerubian]] webbing almost as quickly as it was opened.\r\nThe Ebon Watcher says: Your soldiers are being used as living shields to stave off artillery fire in the [[Valley of Echoes]], allowing the forces of the Lich King to assault your base without impediment.\r\nThe Ebon Watcher says: The Lich King knows your boundaries, Highlord. He knows that you will not fire on your own men. Do you not understand? He has no boundaries. No rules to abide.\r\nHighlord Tirion Fordring says: We will do this with honor, Darion. We will not sink to the levels of the [[Scourge]] to be victorious. TO do so would make us no better than the monster that we fight to destroy!\r\nThe Ebon Watcher says: Then you have lost, Highlord.",},
			["Tirisfal Glade"] = { content = "#redirect [[Tirisfal Glades]]", redirect = "Tirisfal Glades",},
			["Tirisfal Glades"] = { content = "'''Tirisfal Glades''' (also known as the '''Tirisfal Glade''' or simply '''Tirisfal''', pronounced TEER-ihs-fahl) is an eerie [[Zone|region]] found on the northern coast of [[Lordaeron]]. It was named after the [[Keeper|Titan Keeper]] [[Tyr]], as Tirisfal means \"Tyr's Fall\" in the [[vrykul]] tongue. The lands of the [[Forsaken]], the wooded hills are seeped through with the curse of the [[Lich King]]'s [[Plague of undeath|plague]]. The sky over Tirisfal is eternally gloomy and tinted a blighted green, and the trees and other flora desperately cling to their last shreds of life.\r\nThose who inhabit the area of Tirisfal used to feel two conflicting energies emanating from the earth: the remaining spiritual essence of [[Tyr|Keeper Tyr]], and that of his enemy [[Zakajz]]. Some tapped into Tyr's energy; others would become attuned with the [[C'Thrax]]'s dark aura. Although tainted and melancholy, Tirisfal still very much has its own unique, haunting beauty, particularly in such areas as the stony [[North Coast]], the town of [[Brill]], and the deep atmosphere of the ruined [[Agamand Mills]].\r\nTirisfal Glades is home not only to the Forsaken but to their enemies as well. The [[Scarlet Crusade]] has several outposts here, including the seat of their religious faith, the [[Scarlet Monastery]]. The minions of the [[Scourge]] are also ever-present, tainting the derelict farmsteads and dilapidated mills with their foul presence.\r\nIn the aftermath of the [[Battle for Lordaeron]], Tirisfal Glades became a contested territory between the [[Alliance]] and the [[Horde]], with the [[Ruins of Lordaeron|ruins of Capital City]] becoming heavily plagued and the central areas of Tirisfal itself being overrun with [[Blighted Soldier]]s risen by [[Sylvanas Windrunner]], who attack anyone on sight.\r\nTirisfal once again belongs to the Forsaken after the end of the fourth war, although the Undercity remains uninhabitable.\r\n===Rise of humanity===\r\nWhen [[Loken]], the Titanic Watcher left in charge of [[Ulduar]] fell to corruption, [[Tyr]] and his allies stole the [[Discs of Norgannon]] to investigate the extent of Loken's betrayal. Discovering the theft, Loken sent horrific monsters after Tyr's group, but Tyr sacrificed his life to fight the creatures while his comrades escaped with the discs. The [[C'Thrax]]xi [[General (rank)|generals]] [[Zakajz the Corruptor|Zakazj]] and [[Kith'ix]] engaged in combat with Tyr, [[arcane]] and [[Shadow (magic)|shadow]] [[magic]] ripping through the glade. The struggle lasted for six days. Ultimately, to protect his friends, Tyr unleashed all of his power, erupting in a crater. Tyr and Zakazj were dead while the wounded Kith'ix fled to the west. In honor of her fallen comrade, [[Ironaya]] named the glade surrounding the crater as \"[[Tyr's Fall]]\" which in the [[Vrykul (language)|vrykul tongue]] translated to \"Tirisfal\". She and her followers buried Tyr and his foe where they lay, and they placed Tyr's massive silver hand atop his final resting place as a memorial to his valiant sacrifice. In the end, Tyr's hammer became lost with him somewhere beneath the land now named in his honor. The peaceful [[vrykul]] that were accompanying the [[Keeper]]s wanted to further honor Tyr and decided to settle near the battlefield and protect the [[Tomb of Tyr]]. Ironaya and [[Archaedas]] honored the vrykul's wish to settle in Tirisfal. Among the vrykul that remained in Tirisfal was [[Yrgrim the Truthseeker]] but later left the place.\r\nOver time, the area became a place of legend for the vrykul people in [[Kalimdor (landmass)|northern Kalimdor]]. As a result of the [[Curse of Flesh]], the [[Dragonflayer clan|Dragonflayer]] vrykul began giving birth to deformed children, giving rise to fear. [[King Ymiron]] intended to unite all vrykul [[clan]]s and ordered the malformed infants killed. Some Dragonflayer vrykul couldn't do that and decided to find the legendary land of Tirisfal and give the children to the vrykul living there. In the ages that followed, the children and their offspring continued transforming into beings called [[human]]s. As such, humanity first emerged in Tirisfal Glades. The vrykul had formed [[Tyr's Guard]]. Knowing they would not live forever, they allowed the humans to join the order.\r\nTirisfal Glades were the landing place of the [[Highborne]] (later [[High elf|high elves]]) led by [[Dath'Remar Sunstrider]] after the [[Night elf|night elves]] exiled them from [[Kalimdor]]. Forging inland, the high elves founded a settlement within the tranquil Tirisfal Glades, co-living with the [[tribe]]s of primitive humans who told them legends about Tyr. Among known elves that were born in Tirisfal is [[Lorash Sunbeam]]. After a few years, many of them began to go mad due to shadowy powers. It was theorized that [[Zakajz the Corruptor|something evil]] slept beneath that particular part of the world, but the rumors were never proven to be true. The Highborne argued whether they should expel the humans from the land or even conquer them. Dath'Remar did not agree with this because he sensed dark magic. To avoid violence, the Highborne packed up their encampment and moved northward towards another land rich with ley energies, [[Quel'Thalas]].\r\nOver thousands of years, the Tirisfal vrykul died out, but humanity would flourish in the [[Eastern Kingdoms]]. Warlord [[Thoradin]] set to unite the human tribes, including that of Tirisfal Glades which was the only human [[Lordain's tribe|tribe]] powerful enough to end King Thoradin's dream of unity. This tribe was led by the native [[warrior]] [[Lordain]]. While Thoradin won the [[Alterac Mountains|Alteraci]] by show of strength, the Tirisfal humans would not submit to shows of force like the [[Alteraci tribe|Alteraci]]. To win their loyalty, Thoradin needed to appeal to their [[Religion|religious]] beliefs. Thus Thoradin and his personal guards made a pilgrimage to the region's shrines and sacred groves. At each site, the king performed rituals as was the custom of Lordain and his kin. Thoradin even wore a pendant of the silver hand, an image held sacred by Tirisfal's humans. At the end of the pilgrimage, Thoradin met with Lordain. The king pledged that if the tribe joined him, he would adopt their mystic ways and spread them among the [[Arathi tribe|Arathi]]. To seal his promise, Thoradin ran his palm along [[Strom'kar]]'s edge and mixed his blood with the earth of Tirisfal. And so it was, Lordain and his people bent the knee to King Thoradin, with the Tirisfal leader becoming Thoradin's general. With the human tribes united, the [[kingdom]] of [[Arathor]] arose.\r\nDuring the [[Troll Wars]], Tirisfal Glades were considered a territory of the [[Amani Empire]]. When the Troll Wars ended, Thoradin abdicated and spent some time in Tirisfal studying its ruins and becoming obsessed with the humanity's history as well as that of the vrykul. Using the [[High elf|elven]] enchantments of Strom'kar, he located Tyr's tomb. Thoradin led a retinue of guards and [[sorcerer]]s there and encountered Tyr's Guard. Thoradin's group forced themselves past them and entered the depths of darkness to which Thoradin heroically succumbed.\r\nBy the year -2,700, the area had the most coveted and fertile lands. The Arathi established a stronghold to protect their [[Farm|farmsteads]] from [[gnoll]]s, [[kobold]]s, and other dangerous wildlife. Many former [[soldier]]s settled in this region, which they renamed Lordaeron in honor of the late general Lordain.\r\n===Guardians of Tirisfal===\r\nTirisfal Glades was a place of power for centuries, being the seat of the [[Council of Tirisfal]], who secretly waged their war against the [[demon]]s of the [[Burning Legion]]. Among the places the Council members used was the [[Venomweb Vale]] protected by magically conjured [[spider]]s.\r\n2,600 years [[BDP]], fishermen reported a demon stalking the shore of [[Brightwater Lake]]. In fact, the [[dreadlord]] [[Kathra'natir]] corrupted the land around the lake, causing deaths, diseases, insects, and droughts of well waters. There were [[Eidre]]'s people to rule and protect, and she asked her lover [[Alodi]] to come home with her. As a member of the Council, Alodi refused to go with her love, but instead, the [[half-elf]] and [[Meryl Felstorm|Meryl Winterstorm]] devised a plan with his colleagues to defeat the dreadlord. The council members were to give him his powers, and as a [[Guardian of Tirisfal|Guardian]] he rode a [[phoenix]] from the Venomweb Vale to the lake where Eidre's keep was located. Noticing the dreadlord on an island in the lake, Alodi defeated the demon and banished him back to the Twisting Nether through a rift. Eidre understood now Alodi's true calling. Looking from her keep's window, she witnessed the lake's restoration.\r\n===The fracturing of Arathor===\r\nBy the year -1,200, the kingdom of Arathor began to split apart. As [[Strom]]'s power continued to wane due to the lack of nearby natural resources, the nobles of the capital decided to depart to the fertile valleys and pastures of the north. In Tirisfal they founded a city-state and named it after the surrounding region: [[Capital City|Lordaeron]]. The nobles used their wealth to buy up large plots of land, some of which had been developed by early settlers. These areas included the [[Agamand Mills]] and the farmsteads owned by the [[Balnir]] and [[Solliden Farmstead|Solliden]] families.\r\nOver 800 years BDP, Magna [[Scavell]] taught several members of the Council, including the young [[Aegwynn]], in the Glade.\r\n===Second War and aftermath===\r\nThe [[Old Horde|Horde]] led by [[Orgrim Doomhammer]] crossed the [[Alterac Mountains]] into the Glades and besieged [[Lordaeron (kingdom)|Lordaeron's]] [[Capital City]]. However, due to the [[Gul'dan|betrayals]] within the Horde and the arrival of the [[Alliance of Lordaeron]] led by [[Turalyon]] from behind, the isolated Horde army was certain to lose, so Warchief Orgrim sounded for retreat to [[Khaz Modan]], with the Alliance racing after them.\r\nBy the time of the [[Third War]], the [[Agamand]] family living at the Agamand Mills was the most prosperous family in Tirisfal Glades. [[Archbishop]] of the [[Church of the Holy Light]] [[Alonsus Faol]] died prior to the Third War and was buried at [[Faol's Rest]].\r\n===Third War and aftermath===\r\nUnder the rule of [[Terenas Menethil|King Terenas]], Tirisfal became a land of peaceful farms and small towns, its people living happily for generations. Unfortunately, it was one of the first places to fall to [[Arthas Menethil]]' armies after he ransacked Lordaeron, and its people were killed and risen as [[undead]] [[slave]]s to the [[Lich King]]. Tirisfal suffered a huge number of deaths when the [[Plague of Undeath]] swept through the region, and [[Mass Grave|mass graves]] were created to hold the bodies.\r\nAs Lordaeron fell, Arthas arrived to the ravaged [[Balnir Farmstead]] and raised his former horse, [[Invincible]], as a [[Skeletal horse|skeletal steed]]. The [[Scourge]] also raised Archbishop Faol from his grave. The Agamand Mills were taken by the undead as well and so were most of the settlements in the area.\r\nDuring the [[Scourging of Lordaeron]], [[Thomas Thomson]] was sent by the superior [[Knights of the Silver Hand]] to spent time with his family at the [[Thomson]] farm, located southwest of the [[Agamand Mills]] in Tirisfal Glades. As he was returning home, he encountered pockets of Scourge as the [[Capital City]] has fallen. Days later, a courier arrived at the farm and delivered a message about the death of Lord Uther. Ultimately, the farm was abandoned as Thomas sent his wife and children with Kul Tiran ships while he joined the remaining members of the paladin order. Like the other farms, the Thomas farm was growing pumpkins.\r\nJust after the Third War ended, the Lich King began losing power thanks to the spell of [[Illidan Stormrage]], and so was Arthas Menethil. After the [[Battle for Mount Hyjal]], the [[death knight]] returned home and scoured the surrounding of the Capital City of any human citizens he could find. They were trying to leave the area and get to [[Dalaran]], but Arthas, [[Kel'Thuzad]], and [[Sylvanas Windrunner]] defended the passes and killed the [[Human Refugees|fleeing refugees]] and their Silver Hand protectors.\r\nUpon the successful cleansing, Arthas was recalled to Northrend to aid the Lich King. However, the weakened death knight was betrayed and the [[Dreadlord Insurgents]] attempted to kill him. Arthas fled the ruins of Capital City, and accompanied by Sylvanas' [[banshee]]s, trekked through the Glades. Arriving to a field area near the Balnir Farmstead, the banshees attacked Arthas' last followers and Sylvanas shoot an arrow at the death knight, poisoning him. Kel'Thuzad and his [[skeleton]]s found soon after, defeated the banshees and forced Sylvanas to retreat. With that, the lich and the death knight continued to a [[Scourge harbor|landing site]] from which Arthas left Lordaeron.\r\nWhen Sylvanas and [[Garithos]]' [[Alliance resistance]] were besieging Capital City, the [[Ironforge Dwarves (Warcraft III)|group]] of [[Dwarf|dwarves]] serving the Alliance went astray and became lost in the wilderness near the Capital City, with some of them being captured by local [[kobold]]s.\r\nAfter a [[Plaguelands civil war|civil war in the Plaguelands]], Sylvanas and her free-willed undead took Capital City, forming the [[Forsaken]]. The rebel undead managed to take control of Tirisfal and establish it as their home territory.\r\nDuring that time, remnants of the [[Knights of the Silver Hand]] spied on the Forsaken moving into the Ruins of Lordaeron. To continue observing them, [[Alexandros Mograine]] and his team took the deserted Monastery in northern Tirisfal. With the subsequent splintering of the Silver Hand, the fanatical [[Scarlet Crusade]] established themselves and took the Monastery as their sanctuary. It was here that [[Balnazzar]], posing as [[Saidan Dathrohan]] later transformed the maddened Thomas Thomson into an undead monstrosity that haunts not only [[Brill]] but all of [[Azeroth]] during the [[Hallow's End]]. Over time, the Crusaders took several [[watch tower]]s in Tirisfal posing threats to the Forsaken.\r\nAnother threat that remained in the land was the [[Scourge]]. They led a [[Summertide Assaults|series of assaults]] against the Scarlet Monastery.\r\nAt some point, a farm near [[Brill]] was stalked by [[Captain (rank)|Captain]] [[Renee Lauer]] and her force of Scarlet Crusaders, executing [[Jillian Grell]] and [[Rinn Firecaster]] in the process of cleansing the world of non-humans. Soon after, the relatives of the deceased, [[Barnabas Grell]] and [[Reynah Firecaster]] began searching the woods of Tirisfal, killing the Crusaders they found. Renee's group had a camp on the outskirts of the western Glades. Reynah and Barnabas soon found it and worked their spells and abilities against the enemies. Although they managed to capture the captain, other crusaders bested them and eventually killed, but not before Reynah could use her fire magic against them. As soon as they died, Sylvanas and [[Varimathras]] discovered the camp as well and led their force to kill the Crusaders.\r\n===World of Warcraft===\r\nThe Forsaken, having joined the [[Horde]], battled against the [[Mindless Ones]], [[Rot Hide gnoll]]s, and the [[Scarlet Crusade]]rs to solidify their hold on the area. Various parts of the Glades are protected by the [[Deathguard]]s.\r\nPrior to the start of the [[invasion of Outland]], the gates of Lordaeron were invaded by a group of [[Burning Legion]] [[demon]]s led by [[Highlord Kruul]].\r\n===Battle for the Undercity===\r\nDuring the [[war against the Lich King]], members of the Horde and Alliance formed a temporary alliance at the siege of [[Angrathar the Wrathgate]]. [[Grand Apothecary Putress]]'s betrayal ended seven years of cold war between the two factions as their armies converged on the Undercity. Warchief [[Thrall]]'s forces stormed the front gates of the [[Ruins of Lordaeron]] while King [[Varian Wrynn]]'s army assaulted the Sewer entrance to the city. These two armies confronted Putress, [[Varimathras]], and finally each other at the [[Battle for the Undercity]].\r\n==Geography==\r\nThe instanced, winged dungeon known as the [[Scarlet Monastery]] can be found in Tirisfal Glades. There are no other dungeons or battlegrounds in the area.\r\nThe western end of Tirisfal contains a large, inaccessible area. There is a path leading to the area accessed via a small lake in the northwest by the coast, past the Solliden Farmstead. The path is currently blocked by large rocks.\r\n===Places to stay===\r\n*[[Undercity]] - As a racial capital, the Undercity offers a full range of amenities for travelers.\r\n*[[Brill]] - This quaint little town offers the recent dead a place of rest and respite from the horrors of Tirisfal. Be sure to check out the [[Gallows' End Tavern]] while in town.\r\n*[[Bulwark]] - Though possessing limited supplies, the Argent Dawn and Forsaken forces at the Bulwark do offer members of the Horde a place to repair armor.\r\n===== [[Zeppelin]] towers south of Brill=====\r\n*[[Grom'gol Base Camp]], [[Stranglethorn Vale]]\r\n*[[Orgrimmar]], [[Durotar]]\r\n*[[Vengeance Landing]], [[Howling Fjord]] \r\n===== [[Flight path]]s from [[Undercity]]=====\r\n*[[Brill]], Tirisfal Glades\r\n*[[The Bulwark]], Tirisfal Glades\r\n*[[Forsaken High Command]], [[Silverpine Forest]]\r\n*[[The Sepulcher]], [[Silverpine Forest]]\r\n*[[Tarren Mill]], [[Hillsbrad Foothills]]\r\n*[[Hammerfall]], [[Arathi Highlands]]\r\n*[[Revantusk Village]], [[The Hinterlands]]\r\n*[[Thondroril River]], [[Eastern Plaguelands]]\r\n*[[Lights Hope Chapel]], [[Eastern Plaguelands]]\r\n*[[New Kargath]], [[Badlands]]\r\n* [[Sandy Beach]], [[Vashj'ir]]\r\n===== [[Flight path]]s from [[Brill]]=====\r\n*[[Undercity]], Tirisfal Glades\r\n*[[The Bulwark]], Tirisfal Glades\r\n*[[Forsaken High Command]], [[Silverpine Forest]]\r\n===== [[Flight path]]s from [[The Bulwark]]=====\r\n*[[Undercity]], Tirisfal Glades\r\n*[[Brill]], Tirisfal Glades\r\n*[[Tarren Mill]], [[Hillsbrad Foothills]]\r\n*[[Strahnbrad]], [[Hillsbrad Foothills]]\r\n*[[Andorhal]] ([[Horde]] Side), [[Western Plaguelands]]\r\n*[[Thondroril River]], [[Eastern Plaguelands]]\r\n===Western Tirisfal Glades===\r\nTo the west of Deathknell is a blank area surrounded by mountains. For a long time, this was simply unincorporated terrain. In ''[[World of Warcraft: Cataclysm]]'', it now contains a small lake and some trees, as well as an interesting circle of white mushrooms. The southern half of the area is called the [[Whispering Forest]].\r\n==Notable characters==\r\nTirisfal Glades is home to several Forsaken of status. From the base camp in Deathknell, [[Executor Arren]] sends promising young Forsaken out into the world. In Brill, [[Executor Zygand]] leads the effort to reclaim Tirisfal from the Scarlet Crusade, and at the Bulwark, [[High Executor Derrington]] seeks to eradicate the foothold the Scourge has established in the Plaguelands.\r\n===Lunar Festival===\r\nDuring the Spring Lunar Festival, two elders appear in Tirisfal Glades.\r\n* - [[Elder Darkcore]], [[Undercity]], upstairs in the Throne Room\r\n* - [[Elder Graveborn]], [[Brill]], near the [[Gallows' End Tavern]]\r\n==Resources==\r\n*[[Cloth]]\r\n**[[Linen Cloth]]\r\n*[[Herb]]s\r\n**[[Peacebloom]]\r\n**[[Silverleaf]]\r\n**[[Earthroot]]\r\n*[[Leather]]\r\n**[[Ruined Leather Scraps]]\r\n**[[Light Leather]]\r\n*[[Ore]]\r\n**[[Copper Vein]]\r\n*[[Fish]] - Fishing skill 25 needed to fish open water without catching junk\r\n**[[Raw Brilliant Smallfish]]\r\n**[[Raw Longjaw Mud Snapper]]\r\n**[[Sickly Looking Fish]]\r\n**[[Old Teamster's Skull]]\r\n**[[Old Skull]]\r\n**[[Bloated Smallfish]]\r\n**[[15 Pound Mud Snapper]]\r\n==Battle pets==\r\n*[[Westfall Chicken]] - ''[[CLUCK!]]'' quest\r\n*[[Spring Rabbit]] - ''[[Noblegarden]]'' only\r\n*[[Rat]]\r\n*[[Bat]]\r\n*[[Lost of Lordaeron]]\r\n==Wild creatures==\r\n*[[Bat]]s\r\n*[[Bear]]s\r\n*[[Darkhound]]s\r\n*[[Ghost]]s\r\n*[[Ghoul]]s\r\n*[[Shark]]s\r\n*[[Skeleton]]s\r\n*[[Spider]]s\r\n*[[Stag]]s\r\n*[[Wolf|Wolves]]\r\n*[[Zombie]]s\r\n===Rare spawns===\r\n*[[Bayne]]\r\n*[[Deeb]]\r\n*[[Farmer Solliden]]\r\n*[[Fellicent's Shade]]\r\n*[[Lost Soul]]\r\n*[[Muad]]\r\n*[[Ressan the Needler]]\r\n*[[Sri'skulk]]\r\n*[[Tormented Spirit]]\r\n==Achievements==\r\n*[[Explore Tirisfal Glades]]\r\n*[[Scarlet Monastery (achievement)]]\r\n*Getting the exploration achievement [[Explore Tirisfal Glades]] at a low level can be difficult since as you approach [[Whispering Gardens]], the [[Scarlet Scout]]s will kill you unless you are somewhat close to their level (29-30) or above.\r\n*Lots of Books for [[Well Read]] can be found in the [[Scarlet Monastery]].\r\n===History===\r\nOnce a [[human]] land, Tirisfal's warriors served in the [[Second War|Second]] and [[Third War]]s. The Scourge ravaged the region in the Third War and its people fled. After the war, [[Sylvanas Windrunner]] bent the Lich King's yoke enough to free herself and many others from his dominance. She termed these free undead the Forsaken and took the ruins of Lordaeron's capital city as her own. Tirisfal Glades is their unofficial kingdom.\r\nThe Forsaken attempt to carve out a home and battle against gnolls and worse. Some factions send in agents to sabotage and curtail the Forsaken's efforts, seeing them as no better than the Scourge.\r\nWhile the Forsaken hunting and living in Tirisfal Glades consider [[darkhound]]s only a minor nuisance, occasionally a large enough pack poses a threat to alchemists exploring the woods for components.\r\nThe [[orc]] [[shaman]] [[Hakin]] was sent to Tirisfal to meet a Forsaken ambassador. He wasn't happy to be here because the spirits of the land — they cried in Lordaeron, painfully. When [[Brann Bronzebeard]] wandered through Tirisfal Glades, he met several undead members of the [[Cult of Forgotten Shadows]]. One of them was [[prophet]]. The fact that the Forsaken hold the Tirisfal Glades irritates the human nations.\r\n===Geography===\r\nThe most obvious feature of Tirisfal Glades is the sky — altered by magic, it is a swirling blue pane that bathes the land in a cerulean glow, adding to the land's already surreal aspect. Mists constantly waft through the trees, and with the constant, twisted sky above you would not tell the difference between night and day. The undead plague has worked its evil on the trees, though not to the same extent as in the [[Plaguelands]]. Instead of becoming giant toadstools, the trees' bark has withered to a sickly violet and they bleed infected green-yellow sap. Danger lurks everywhere and death floats beneath the mist.\r\nTo Tirisfal's south is Silverpine Forest; to its east are the [[Western Plaguelands]]. The land borders [[Lordamere Lake]] to the southeast, while to the north and west are Lordaeron's oceans.\r\nLike Silverpine Forest, Tirisfal Glades is an immense woodland with forbidding trees, threatening shadows and lurking mists. The animals in the woods are not as vicious as those in Silverpine, however. This haunting land, under the Forsaken's rule, may, in fact, be safer than Silverpine Forest.\r\nThe Forsaken control Tirisfal Glades and have several settlements throughout the area. This region is a place of mystery and adventure.\r\nMagic has twisted the land; the trees are grown a sickly purple and ooze orange sap, and the sky is a constant swirling blue, shedding a surreal light on the wafting mists and lurking creatures.\r\n==Notes and trivia==\r\n*Before its fall, the citizens of Tirisfal used to enjoy picnics among the hills of Tirisfal during the last days of late autumn.\r\n*When [[Aegwynn]] was little, her mother would take her to woods of Tirisfal Glades to a camping trip. The forests that lay just north of the capital of Lordaeron had always been a place of beauty and of quiet. She was surprised at the animals ranging freely, stunned by the incredible colors of the vegetation and amazed at how many stars she could see in the night sky away from the torchlight and lanterns of the city.\r\n*[[The Flight from Lordaeron (WC3 Undead)|The Flight from Lordaeron]] states there's a river in Tirisfal. No river is present in WoW.\r\n*The border between Tirisfal and the [[Western Plaguelands]] once had one of the highest level gaps in the game, with mobs and quests going from level 10 in Tirisfal to level 50 in the Plaguelands (see [[Welcome Bear]]). This effect has diminished somewhat with Cataclysm, and other areas have similar gaps these days (e.g. [[Mulgore]] and the [[Southern Barrens]]), making it less remarkable.\r\n*An ancient plague wiped out thousands of innocent victims. Later it was discovered that the deadly agent in the plague was preserved through the venom of [[Night Web Spider]]s from Tirisfal.\r\n*The farm of [[Thassarian]]'s family is said to be outside [[Capital City|Lordaeron]].\r\n*North of the Scarlet Monastery, there's a forested area. The area was used as a meeting place for [[Varimathras]], [[Balnazzar]], and [[Castillian]].\r\n**In the game, there are mountains north of the Monastery which are inaccessible due to the start of the [[northern Lordaeron]] and its invisible wall.\r\n*In ''[[Warcraft III: The Frozen Throne]]'', Sylvanas met with [[Balnazzar]], [[Varimathras]], and [[Detheroc]] in some ruins in the Tirisfal Glades. ''[[Arthas: Rise of the Lich King]]'' changed this to [[Silverpine Forest]].\r\n*It was long speculated by players that an [[Old God]] resided below Tirisfal Glades because of [[The Founding of Quel'Thalas]] chapter of [[History of Warcraft]], until [[Ask CDev]] refuted its existence. However, it also confirmed that there was indeed something underneath it. The nature of that being was revealed in ''[[Chronicle Volume 1]]'', which established that it was the [[C'Thrax]] [[Kith'ix]], who had been slain by the [[titan-forged|titan]] [[keeper]] [[Tyr]] long ago and buried by the [[vrykul]].\r\n*Despite the Battle for Lordaeron officially revamping the center of Tirisfal, the western and eastern portions of it remain untouched as of current.\r\n*When the name \"Tirisfal\" was first revealed in ''[[The Last Guardian]]'', it originally only referred to the secret Council and its Guardian, to the point that even [[Khadgar]] ignored its meaning despite living in [[Lordaeron]].\r\n===Battle for Lordaeron===",},
			["Tirisfal Regalia"] = { content = "'''Tirisfal Regalia''' is the [[Tier 5]] set for Mages.\r\n==Notes==\r\nIt should be noted that the Tirisfal Armor bears a striking similarity to Medivh's robes. Given the name, and that Guardians resided in Tirisfal, it could be assumed that this is the \"standard\" armor of either Guardians or perhaps the Council of Tirisfal.\r\nThis set is worn on the official mage avatar.\r\nSee also: [[Set look alikes]]",},
			["Titan"] = { content = "The '''titans''' (sometimes capitalized) are a [[race]] of colossal, [[planet]]-sized cosmic beings, composed of [[arcane]] [[magic]] and the primordial matter from which the universe was born. They roamed across the cosmos like walking worlds, imbued with the raw power of creation itself. The titans used this incredible force to find and awaken [[World-soul|others]] of their kind. Hailing from the far reaches of the cosmos, they shaped and brought life and order to countless worlds across the [[Great Dark Beyond]]. They were described as perfect and majestic beings who are akin to [[god]]s.\r\n==Description==\r\nThe titans are colossal godlike beings made up of the primordial matter from which the very universe was born. Imbued with the raw power of creation itself, they roam the cosmos like walking worlds. Titans are born from [[world-soul]]s, spirits who are formed within the fiery cores of a small number of worlds and who slumber for ages, suffusing the planets they inhabit with [[Spirit]] energy before finally awakening. Described as living worlds, their bodies are covered in mountain peaks and rivers, their forms wrapped in cloaks of stardust and their eyes shining like brilliant stars. Bastions of purity and good, the titans are unable to conceive of evil or wickedness in any form.\r\nTitans are heavily tied to the cosmic force known as [[arcane]]. In fact, arcane is their very lifeblood. The original [[Well of Eternity]], an enormous lake of volatile arcane energies, was literally the very lifeblood of [[Azeroth]]'s [[world-soul]]. They are also uniquely susceptible to [[fel]] magic, but full-grown titans are also immune to the corruptive influences of the [[void lords]].\r\nAccording to the cosmology chart, the titans, as the embodiments of Order, are most closely associated with the element of [[Earth]], as well as sharing an association with the element of [[Water]] with the [[Wild Gods]].\r\n==Mentions of titans==\r\n*[[Wrathion]] mentions a being called \"The Final Titan\" after eating the heart of [[Lei Shen]] during [[Heart of the Thunder King (quest)]]. He may or may not have been referring to Azeroth.\r\n*Some titanic creations were implied to be titans (as in [[Fate of the Titans]]), but this is not the case. Actual titans (albeit their spirits and avatars) were only introduced to the game with [[Patch 7.3.0]], almost 13 years after the release of ''World of Warcraft''.\r\n*In [[BlizzCast]] 12, [[Chris Metzen]] said \"''Will we see actual titans one day? Will we ever get to the truth and origin of the Old Gods? There's all sorts of meta-themes that's all rich fertile ground and we will get there''.\" These questions were ultimately answered in ''[[Chronicle Volume 1]]''.\r\n*According to a [[flavor lore|prophecy]] by [[Skeram]], a titan battled an unimaginable evil ([[C'Thun]]) in [[Silithus]]. The titan fell, but may not have been vanquished in the battle. ''Chronicle Volume 1'' states that this was not the case.\r\n*Some dwarves [[flavor lore|believe]] that [[Greatfather Winter]] is a titan, but this is not the case.\r\n*According to [[Magni Bronzebeard]], they built the [[Hall of Communion]].\r\n*The [[Core of an Unknown Titan]] item in [[Korthia]].\r\n==Notes and trivia==\r\n*It has been hinted that when titans die, their souls would return to their own Order plane.\r\n*Two in-game models are called \"titans\" in the files, but are used for [[titanic watcher]]s rather than actual titans.\r\n*The non-canon RPG described two races of titans: [[aesir]] and [[vanir]]. This categorization was used in-game to describe [[storm giant|storm]] and [[Mountain giant|earth giant]]s, but was later re-defined in ''[[Chronicle Volume 1]]'' to describe instead the two original types of [[titan-forged]].\r\n*Prior to the publication of ''Chronicle Volume 1'', the [[Pantheon]] were the leaders of all titans, implying there were more of them, and were described as metallic-skinned.\r\n*Though [[Chris Metzen]] said the titans were godlike and the [[Warcraft Encyclopedia]] states titans are not [[god]]s, the ''[[Ultimate Visual Guide]]'', the ''[[Sunwell Trilogy]]'', the ''[[World of Warcraft: The Magazine|Magazine]]'', and [[Loreology]] have stated that they are \"metallic-skinned gods\" as described in [[Mythology of the Titans]]. The Senior Historian later clarified that by \"gods\" he meant \"perfect specimen rather than an actual divine being\".\r\n**Reconciling the various sources, ''[[Chronicle Volume 1]]'' described them as godlike beings.\r\n*The titans do not transcend all realities like demons do. \r\n*The name \"titan\" is inspired from the eponymous giants or proto-gods from who inhabited the world during the First Era, and later ruled it during the Second Era. Their leader was Kronos. Notable titans include Rhea, Atlas, and Prometheus. Unlike their Warcraft counterparts, most of them were inherently malevolent. They were defeated by Zeus and the Olympians at the start of the Third Era.\r\n*The Æsir and Vanir come from . The Aesir are the rulers of Asgard and the more altruistic force in the universe, the greatest of them being Odin and Thor. The Vanir come from Vanaheim and are allied with the Æsir. They mostly live apart from each other, but a few Vanir have been taken into Asgard and are considered as \"one of the Æsir.\" Both have a common enemy in the Jotnar (giants). In an interesting contrast from Blizzard's direction, which places the dwarves close to the titans, the Vanir of Norse myth had stronger ties to the elves.\r\n*When the titans ultimately appeared in ''World of Warcraft'', they largely seemed to ignore the descriptions presented in ''Chronicle Volume 1'', being the metallic giants seen in the RPG books and ''[[Warcraft Saga]]'' or orbs of energy in their soul form.\r\n**In the artwork of the titans from ''Chronicle Volume 1'', the titans resemble constellar.\r\n*There was to be an in-game feature called [[Path of the Titans (feature)|Path of the Titans]] in ''Cataclysm'' but it was cut before release.",},
			["Titanic Leggings"] = { content = "'''Titanic Leggings''' are very good DPS leggings.\r\n==Source==\r\nTitanic Leggings is crafted by [[Blacksmithing|Blacksmiths]] with a skill level of 300.\r\nThe components are:\r\n*12 [[Arcanite Bar]]\r\n*20 [[Enchanted Thorium Bar]]\r\n*10 [[Essence of Earth]]\r\n*2 [[Flask of the Titans]]\r\nThe [[Plans: Titanic Leggings|plans]] drops off creatures with their levels in the high 50s to 60s.",},
			["Titans"] = { content = "#REDIRECT [[Titan]]", redirect = "Titan",},
			["Titan (language)"] = { content = "The language of the Titans and [[giant]]s is known as Titan. The written language is made up of glyphs (hieroglyphs) and runes, and is understood only by deduction. Scholars are trying to restore the language by matching the modern Dwarven tongue with rare evidence at excavations of Titan ruins. Linguists tear their hair out trying to parse the inhumanoid grammar and circular references of Titan. \r\n==Titan Primer==\r\nHere are a few common Titan phrases and words, for which the translations have been officially confirmed by Blizzard: \r\n*[[Kalimdor]] = \"Land of eternal starlight.\", Dragon Hunt\r\n*[[Gorshalach]] = \"Dark Render\".\r\n*[[Taeshalach]] = \"Flame Rend\".\r\n*[[Gorribal]] = \"Dark Seether\".\r\n*[[Aesir]] = \"Storm Giants\"\r\n*[[Vanir]] = \"Earth Giants\"\r\n===Untranslated Titan words or phrases===\r\n*[[Aggramar]]\r\n*[[Aman'Thul]]\r\n*[[Echomok]]\r\n*[[Eonar]]\r\n*[[Gni'Kiv]]\r\n*[[Golganneth]]\r\n*[[Khaz'goroth]]\r\n*[[Khaz'Mul]]\r\n*[[Norgannon]]\r\n*[[Orodur]]\r\n*[[Sargeras]]\r\n*[[Seschenal]]\r\n*[[Shargahn]]\r\n*[[Terramok]]\r\n*[[Tsol]]\r\n*[[Uldaman]]\r\n*[[Ulduar]]\r\n*[[Uldum]]\r\n*[[Vulraiis]]\r\n==Titan Words (speculation)==\r\nThis is the list of words created by the in-game language parser for the Titan language, and is listed as language number nine (word range 673-799) in the Language text file. \r\nIn the in-game translator, the language parser for Titan is similar to the ones for the Draconic, Demonic, and Draenei languages.\r\nNote: The language algorithm used by the in-game \"translator\" merely makes the words look like \"Titan\". It does not actually translate words. Therefore, translated in-game speech isn't true \"Titan\". \r\n*A\r\n*E\r\n*I\r\n*O\r\n*U\r\n*Y\r\n*G\r\n*X\r\n*L\r\n*No\r\n*Az\r\n*Te\r\n*Ur\r\n*Za\r\n*Ze\r\n*Re\r\n*Ul\r\n*Me\r\n*Xi\r\n*Tor\r\n*Gul\r\n*Lok\r\n*Asj\r\n*Kar\r\n*Lek\r\n*Daz\r\n*Maz\r\n*Ril\r\n*Ruk\r\n*Laz\r\n*Shi\r\n*Zar\r\n*Ashj\r\n*Alar\r\n*Orah\r\n*Amir\r\n*Aman\r\n*Ante\r\n*Kiel\r\n*Maez\r\n*Maev\r\n*Veni\r\n*Raka\r\n*Zila\r\n*Zenn\r\n*Parn\r\n*Rikk\r\n*Melar\r\n*Rakir\r\n*Tiros\r\n*Modas\r\n*Belan\r\n*Zekul\r\n*Soran\r\n*Gular\r\n*Enkil\r\n*Adare\r\n*Golad\r\n*Buras\r\n*Nagas\r\n*Revos\r\n*Refir\r\n*Kamil\r\n*Rethul\r\n*Rakkan\r\n*Rakkas\r\n*Tichar\r\n*Mannor\r\n*Archim\r\n*Azgala\r\n*Karkun\r\n*Revola\r\n*Mishun\r\n*Arakal\r\n*Kazile\r\n*Thorje\r\n*Belaros\r\n*Tiriosh\r\n*Faramos\r\n*Danashj\r\n*Amanare\r\n*Faralos\r\n*Kieldaz\r\n*Karaman\r\n*Gulamir\r\n*Toralar\r\n*Rethule\r\n*Zennshi\r\n*Maladath\r\n*Kirasath\r\n*Romathis\r\n*Amanare\r\n*Theramas\r\n*Azrathud\r\n*Mordanas\r\n*Amanalar\r\n*Ashjraka\r\n*Azgalada\r\n*Rukadare\r\n*Sorankar\r\n*Enkilzar\r\n*Naztheros\r\n*Zilthuras\r\n*Kanrethad\r\n*Matheredor\r\n*Ticharamir\r\n*Melarorah\r\n*Arakalada\r\n*Soranaman\r\n*Nagasraka\r\n*Belankar\r\n*Pathrebosh\r\n*Benthadoom\r\n*Amanemodas\r\n*Teamanare\r\n*Enkilgular\r\n*Burasadare\r\n*Melarnagas\r\n*Zennrakkan\r\n*Kamilgolad\r\n*Ashjrakamas\r\n*Zennshinagas\r\n*Mishunadare\r\n*Mannorgulan\r\n*Archimtiros\r\n*Zekulrakkas\r\n*Ashjrethul\r\n===Word Speculation===\r\n*Gor = Dark (speculation)\r\n*Shalach = Rend (speculation)\r\n*Tael = Flame (speculation)\r\n*Ribal = Seether (speculation)\r\n*Aes = Storm\r\n*Van = Earth\r\n*ir = Giant (suffix)",},
			["Titan Shaper"] = { content = "#REDIRECT [[Titan]]", redirect = "Titan",},
			["Title"] = { content = "'''Titles''' are displayed before or after the character's name, usually as an indication of the character's achievements. While a character may have earned multiple titles, only one can be displayed at a time — players can choose which title to display, if any, in the [[Paper doll|Character Info frame]]. Prior to [[Patch 2.0]], characters could only earn titles through the [[Honor System (pre-2.0)|Honor System]] and could not alter which title was displayed.\r\n===PvP Titles===\r\nAll arena titles are given out per bracket per battlegroup - teams in different battlegroups or brackets do not compete against each other. Arena titles are earned for one season only. All PVP titles are displayed in the format: ''title <name>''.\r\n====PvE Titles====\r\nThese titles are no longer attainable with the release of the 3.0.2 patch (on 14th of October, 2008)\r\n====Honor System Titles====\r\nPrior to 2.0, players could earn titles by participating in PvP; ranks would be assigned based on the number of contribution points acquired by killing opposite-faction players during a week. With the release of Patch 2.0 and the Burning Crusade, players can no longer obtain or improve their Honor System title, but can choose to display their highest lifetime title they've earned before the patch. All honor system titles are displayed in the format: ''title <name>''.\r\n==Future Titles==\r\nMore titles may be added into the game at a future point, including the reintroduction of the old honor system titles, but there's nothing concrete about either development in the foreseeable future.\r\n \r\n===Achievement Titles===\r\n[[Patch 3.0.2]] introduced new titles through the [[Achievements]] system.\r\n==See also==\r\n* [[Honor System]]\r\n* [[Title/International|World of Warcraft titles translated to other languages]]",},
			["Titles"] = { content = "#REDIRECT [[Title]]", redirect = "Title",},
			["Tito"] = { content = "'''Tito''' is a [[wolf]] pet summoned by [[Dorothee]], a boss in the Opera House in [[Karazhan]]. \r\n==Abilities==\r\nAnnoying Yipping: Instant, pacifies and silences an enemy, rendering it unable to attack or cast spells for 2 sec.\r\nImmune to scare beast and [[Hibernate]].",},
			["Tkashi"] = { content = "#redirect [[Tkashi Ruins]]", redirect = "Tkashi Ruins",},
			["Tkashi Ruins"] = { content = "The '''Takashi Ruins''' are ancient [[troll]] ruins found in Stranglethorn Vale. The [[Bloodscalp]] trolls live here.",},
			["Toad"] = { content = ":''This page is for the hunter pet family, for more information on the race, see [[Frog]].''\r\nToads are a family of Tenacity [[hunter pet]]s. The family includes three different models of [[frog]]s:\r\n*",},
			["Tobias the Filth Gorger"] = { content = "'''Tobias the Filth Gorger''' is a level 62 [[quest giver]] located in the [[Lower City]] of the [[neutral]] [[Shattrath City]]. \r\nHe starts the quest The Bundle of Bloodthistle.\r\nSee [[List of Shattrath City NPCs]].\r\n==Crisis at the Portal==\r\nIn Blizzard's newscast, \"Crisis at the Portal!\", Tobias was reported to be the source of the \"Silent and Deadly\" stench going about Shattrath. Strangely, his in-game voicing is of a normal broken compared to his unique voice acting done in \"Crisis at the Portal!\".",},
			["Toddrick"] = { content = "'''Toddrick''' is a level 10 [[meat vendor]] located in the [[Lion's Pride Inn]] in [[Goldshire]], in the [[human]] starting zone of [[Elwynn Forest]].\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Tog'Thar"] = { content = "#REDIRECT [[Tog'thar]]", redirect = "Tog'thar",},
			["Tognus Flintfire"] = { content = "'''Tognus Flintfire''' is a level 30 [[artisan]] [[blacksmithing trainer]] located in [[Kharanos]] in the [[dwarven]] starting zone of [[Dun Morogh]].\r\nSee [[List of Dun Morogh NPCs]].",},
			["Tojanida"] = { content = "'''Tojanida''' is a type of elemental creature found in the [[Abyssal Maw]] of the [[Elemental Plane]]. Their hierarchy includes juvenile, adult, and elder forms. Elder tojanidas can also be summoned by druids as nature's allies.",},
			["Token"] = { content = "A '''token''' can refer to one of several things in [[World of Warcraft]]:\r\n* A standard [[quest item]].\r\n** Examples: Token of Thievery, Worn Stone Token\r\n* A [[consumable]], [[quest item]] that increases your [[reputation]] with a particular [[faction]] when used.\r\n** Examples: Argent Dawn Valor Token, Zandalar Honor Token.\r\n* A type of non-[[money]] type of in-game [[currency]].\r\n** Examples: Halaa Battle Token, Halaa Research Token.\r\n* A type of [[reagent]].\r\n** Examples: Love Token\r\n* Also an alternative term for a [[Mark of Honor]].\r\n* Sometimes used to refer to Badge of Justice.\r\n==In Wrath of the Lich King==\r\nThe expansion will provide a new interface for tracking many different types of tokens.",},
			["Tol Barad"] = { content = "'''Tol Barad''' is a ravaged island kingdom between [[Hasic]] and the shores of [[Khaz Modan]]. It is in [[Baradin Bay]]. During the [[Second War]], it was an island citadel of [[Stromgarde]]. The island was also the site of a fierce battle between the [[Horde]] and [[Alliance]]. The [[Horde]], having already conquered most of the [[Dwarven]] lands were preparing to strike out into the Northern Kingdom of [[Lordaeron]]. At the time, the island was being used as a staging point to strike back at [[Orc]] raiders. In response, [[Orgrim Doomhammer]] launched an invasion of the island. Overwhelmed early in the war by the orcs, no life more complex than a few hardy weeds and insects survived the Horde's bloody victory. An aura of death seemed to radiate from the island., and the original fortress was razed to the ground. Tol Barad became a frightening symbol of the Horde's merciless tenacity and barbarity.\r\nYears later, after the Second War, the island nation of [[Kul Tiras]] claimed the former stronghold and established a prison over the ruins of the old fortress. The site of many historic battles in the Second War, Tol Barad is now home to a magic prison. Wizards from both [[Dalaran]] and [[Stormwind]] oversee the complex, and prisoners include enemy mages, lesser and greater demons, warlocks and undead war criminals. The wizards do not allow anyone near the island and keep the prison’s existence secret.",},
			["Tomas"] = { content = "'''Tomas''' is a level 10 [[cooking trainer]] located in [[Lion's Pride Inn]] in [[Goldshire]], in the [[human]] starting zone of [[Elwynn Forest]].\r\nHis name may be a reference to the British travel agency 'Thomas Cook'.\r\nSee [[List of Elwynn Forest NPCs]].",},
			["Tomber's Supplies"] = { content = "==Objective==\r\nRetrieve Rathis Tomber's Supplies and return it to him at [[Tranquillien]] in the [[Ghostlands]].\r\n* Rathis Tomber's Supplies\r\n==Quest Text==\r\nHow am I supposed to supply the war effort when I cannot even safely get my supplies here? I was promised an escort that never came. And then, I had to leave one of my carts behind to the west when I was attacked by a band of [[ghoul]]s!\r\nWant to help out, and get me open for business in the process? Go down the western road out of town and past the graveyard. On the other side of the [[Dead Scar]] is a fork in the road. The hill that my cart had to be left on lies just beyond.\r\n==In Progress==\r\nJust as soon as I get the rest of my supplies, I'll be open for business. The forces here aren't going to get very far if they can't purchase what they need to ply their trades.\r\nWar zones can be such profitable places, wouldn't you agree, <class>? Now, did you manage to fight your way to my cart through all those ghouls?\r\n==Upon Completion==\r\nWith the rest of my supplies here, I can finally open shop. I'm sure that the high executor will be most pleased to hear that the war on [[Dar'Khan]] and the [[Scourge]] can commence.\r\nAnd, of course, there's the small matter of your recompense. Very well, <class>, here is the coin that I alluded to. Do be sure to drop by should you find yourself in need of trade goods. \r\n==Reward==\r\nYou will receive 4 silver \r\n==Gains==\r\n*875 [[XP]]\r\n*1000 [[reputation]] with [[Tranquillien]]\r\n==Notes==\r\nThe cart is difficult to spot in the dim light. Go straight on from the fork just past the [[Dead Scar]], and it's at surrounded by [[Gangled Flesheater]]s.\r\nThis quest must be completed in order to purchase trade goods from [[Rathis Tomber]] in Tranquillien.",},
			["Tomb of Lights"] = { content = "'''Tomb of Lights''' is a crypt located northeast of [[Auchindoun]] in the [[Bone Wastes]] of [[Terokkar Forest]]. It is populated by aggressive [[ethereal]]s.",},
			["Tomb of Sargeras"] = { content = "The term '''Tomb of Sargeras''' refers to the remnants of the Temple of [[Elune]] in the ancient [[Kaldorei]] city of [[Suramar]] (coincidentally, the same city in which [[Tyrande Whisperwind|Tyrande]], [[Malfurion Stormrage|Malfurion]], and [[Illidan Stormrage|Illidan]] grew up) that was used by the [[Guardian]] [[Aegwynn]] to contain the body of [[Sargeras]] after she supposedly defeated the Dark [[Titan]] in mortal combat.\r\nThe Tomb was sent to the bottom of the Great Sea by the [[Dragons|Aspects]], but was much later raised by [[Gul'dan]], who believed that the body of Sargeras contained the power to make him a god (it was in fact the promise of the Tomb of Sargeras that led Gul'dan to first open the Dark Portal). The warlock led his entire army, formed by the [[Stormreaver Clan|Stormreaver]] and [[Twilight's Hammer Clan|Twilight's Hammer]] Clans, to the islands, thus taking away about a third of the Horde's entire standing forces. This action ultimately led to the Horde's defeat in Lordaeron. Gul'dan himself was later torn apart by the Tomb's Guardians, at the very threshold of the Eye Chamber (once the Courtyard of the Moon), and his armies [[The Tomb of Sargeras (WC2)|destroyed]] by the enraged legions of [[Orgrim Doomhammer]], who had been forced to break off their assault on Lordaeron in order to deal with Gul'dan's treachery.\r\nEventually, [[Teron Gorefiend]] sent one of his lieutenants, [[Ragnok]], to accompany [[Tagar_Spinebreaker | Tagar]], [[Fenris]] and their warriors to the Tomb of Sargeras. Their mission was to locate and retrieve the [[Jeweled Scepter of Sargeras]]. Once inside the tomb, they were confronted by a demon, whom they prompty slew. The demon held the scepter, and it was recovered. It was then that Ragnok, the death knight, threatened the orcs with death if they did not help him retrieve the Eye of Sargeras. Fenris was adamant, however, and Ragnok was forced to reconsider his decision to venture into the Chamber of the Eye.\r\nMany years later, the tomb was visited by Illidan, who was searching for the [[Eye of Sargeras]] to destroy Northrend on [[Kil'jaeden]]'s orders. [[Maiev Shadowsong]] tried to [[The Broken Isles|stop him]] from claiming the Eye, and Illidan collapsed the chamber on top of her, setting off a chain reaction that collapsed the entire building. Maiev escaped, and the Tomb of Sargeras and the evils it contained was at last destroyed, the tools of the Dark Titan never to be used again, his dark reign hopefully fading forever into memory. The tomb's ruins are located on an eastern island in the [[Broken Isles]] to the east of the [[Maelstrom]].\r\n==Locations==\r\n*[[Chamber of the Eye]]\r\n==See also==\r\n* [[The Tomb of Sargeras (WC2)]]\r\n* [[The Tomb of Sargeras (WC3)]]",},
			["Tome of Divinity"] = { content = ":''Were you looking for Tome of Divinity (quest starter) that is part of the The Tome of Divinity quest chain?''\r\n----\r\nThe '''Tome of Divinity''' is a book of great value to the [[Clerics of Northshire Abbey]]. It somehow ended up in the clutches of [[Turok]] and his band of [[Ogres]]. [[Anduin Lothar]] led an expedition into the [[Deadmines]] to recapture the tome, but the Ogres emerged victorious in the dark depths of the mines. Anduin and a few survivors were captured and made prisoners to be killed slowly.\r\nIn a vision Anduin Lothar was seen alive, and he was rescued by soldiers from [[Azeroth]]. The Tome of Divinity was taken out of the mine with Lothar, though Turok was not stopped. Finally the tome was returned to [[Northshire Abbey]].\r\nIt is currently used in the training of new [[Paladins]] in both [[Stormwind]] and [[Ironforge]].\r\nTomes of Divinity are common training tools for paladins, even the [[draenei]] keep copies to give out to their paladins as well.",},
			["Tome of Mel'Thandris"] = { content = "The '''Tome of Mel&#39;Thandris''' is located in [[Howling Vale]] of [[Ashenvale]]. It is involved in quest chain.\r\n==Objective of==\r\nNeeds to be viewed for the quest The Howling Vale.\r\n==Cut scene==\r\nWhen the book is viewed, the specter of [[Velinde Starsong]] appears, narrating relatively recent events:\r\n<font color=\"#FFFF9F\">Velinde Starsong says: The numbers of my companions dwindles, goddess, and my own power shall soon be insufficient to hold back the demons of Felwood.\r\nVelinde Starsong says: Goddess, grant me the power to overcome my enemies! Hear me, please, my need is desperate and my cause is just!\r\nVelinde Starsong says: What... what is this? Could this be the answer to my prayers? Elune has granted me a weapon -- this scythe -- to defeat the demons.\r\n</font>",},
			["Tome of Thomas Thomson"] = { content = "==Source==\r\nTome of Thomas Thomson is provided for the following quests:\r\n*Free at Last! (Alliance)\r\n*Free at Last! (Horde)\r\n==Tome of Thomas Thomson as a quest objective==\r\nThis item is an objective of the following quests:\r\n*Free at Last! (Alliance)\r\n*Free at Last! (Horde)",},
			["Tomli Magellas"] = { content = "A master archaeologist and well-known historian among the [[Dwarf|dwarves]], a family fortune based on gemstone mines allowed '''Magellas''' to pursue the life of a scholar and discover the clues hinting at his race's divine heritage. Magellas' contributions to the [[Explorers' Guild|Explorers' League]] helped build the [[Explorers' Guildhall|Guildhall]], and his wisdom earned him a place at the head of the Excursion Council. Officially, Magellas is High Explorer of the Guild, though is he often mistaken for a librarian as he spends nearly every day deep in the Guild Library searching for legends and myths that Guild explorers can be sent to investigate.\r\nTomli's held the position of High Explorer in the year or two leading up to ''World of Warcraft''. He held the position while [[Brann Bronzebeard]] was writing ''[[Lands of Conflict]]'' and ''[[Lands of Mystery]]'', both were sent to Tomli and the [[Excursion Council]].\r\n==Tomli, Muninn, and Magellan==\r\n*In the ''World of Warcraft'' manual, it talks about [[Muninn Magellas]]. In ''Lands of Conflict'', which is set sometime before the events of ''World of Warcraft'', it talks about a Tomli Magellas. ''Dark Factions'' mentions the founding of the guild and speaks of Muninn Magellas. Both \"characters\" have the title of [[High Explorer]], along with [[Brann Bronzebeard]]. It is unknown if they are intended to be relatives or the same character.\r\n*A character named High Explorer '''Magellan''' is mentioned in the next section, which is apparently a typo meaning Tomli Magellas.",},
			["Tom Chilton"] = { content = "'''Tom Chilton''' (aliases '''Kalgan''' and '''Evocare''') is a Lead Game Designer currently working on [[Blizzard Entertainment]]'s MMORPG [[World of Warcraft]], the world's largest MMORPG in terms of monthly subscribers. With [[Rob Pardo]] and [[Jeffrey Kaplan]], he was one of three lead designers on ''[[World of Warcraft: The Burning Crusade]]'', the fastest selling PC game of all time. He is currently working on the second expansion: ''[[World of Warcraft: Wrath of the Lich King]]''.\r\nHe previously worked as a lead designer for [[wikipedia:Origin Systems|Origin Systems]] on MMORPG Ultima Online. He is credited with three Ultima Online expansions: Ultima Online: Third Dawn, Ultima Online: Lord Blackthorn's Revenge and Ultima Online: Age of Shadows. He left Origin Systems in 2004 after Electronic Arts disbanded the studio. He joined Blizzard Entertainment to work on World of Warcraft and was on a team of six game designers.\r\nTom Chilton has made appearances at [[Blizzard Entertainment]]'s BlizzCon 2005 and BlizzCon 2007 events. At BlizzCon 2005, he was on the developer panels for discussions about character classes, dungeon creation, raids, and battlegrounds. At BlizzCon 2007, he was on the developer panels for discussions about classes, PvP, user interface and mods, and professions and items.\r\nAs one of the lead designers for World of Warcraft, he often bears the brunt of players' anger about perceived gameplay problems.\r\nDespise his efforts in balancing World of Warcraft, he's often being titled as one of the worst game developers of this century, next to Julio Torres.",},
			["Tonga Runetotem"] = { content = "'''Tonga Runetotem''' is a level 22 [[quest giver]] located at (52, 31) near the south entrance of [[the Crossroads]] in the [[Horde]]-aligned territory of [[the Barrens]].\r\n==Quests==\r\n* finishes The Barrens Oases\r\n* The Forgotten Pools\r\n* Gathering the Cure\r\n* finishes The Principal Source\r\n* starts Curing the Sick\r\n* starts Mura Runetotem\r\n* The Stagnant Oasis\r\n* Altered Beings\r\n* starts Hamuul Runetotem (Dungeon)\r\n==See Also==\r\n* [[List of the Barrens NPCs]]",},
			["Tony Jay"] = { content = "'''Tony Jay''' (February 2, 1933 - August 13, 2006) was an English voice actor. He passed away from complications incurred from a surgery to remove a tumor from his lung.\r\nHe narrated the opening cutscenes for every race in [[World of Warcraft]] as well as [[The Burning Crusade]]. He was also planned to voice Drek'thar in the cancelled [[Warcraft Adventures: Lord of the Clans]] game.",},
			["Tooga"] = { content = "'''Tooga''' is a talking [[turtle]], a level 45 [[quest giver]] located just southeast of [[Thistleshrub Valley]] in the [[contested]] territory of [[Tanaris]].\r\nHe starts the quest Tooga's Quest, which is timed and will send you &ndash; with him in tow &ndash; to his wife [[Torta]], who resides near [[Steamwheedle Port]]. It is very simple and easy, but all party members must stay close to Tooga en route. If you mount up and go on ahead of him long enough, you'll fail the quest even though he might survive. He is able to fight on his own, and will aid you to some extent in your adventures for a short period of time.\r\nIt should be noted that Tooga is a giant talking turtle found in the middle of a desert, making his existence somewhat suspect.\r\n==Notes==\r\nBoth Tooga and his wife, Tooga, are a split of the word \"Tortuga,\" which is the Spanish word for turtle.\r\nSee [[List of Tanaris NPCs]].",},
			["Tooki"] = { content = "'''Tooki''' is a [[quest giver]] located in [[Stonebreaker Hold]] in the [[contested]] territory of [[Terokkar Forest]].\r\nHe starts the following quests:\r\n* Letting Earthbinder Tavgren Know\r\n* Report to Stonebreaker Camp",},
			["Tool"] = { content = "An object that must be [[equip]]ped or carried in [[inventory]] to ply a [[profession]] or [[skill]].",},
			["Tooltip"] = { content = "When you hover your mouse over certain items (other characters, mobs, items, buttons, etc.) a small window will pop up displaying a description of the item. This also works in many other computer programs. For example, hold your mouse over the \"W\" logo image ( ← this one should show \"This is a tooltip\") in the upper-left, and a small box saying \"Portal: Main\" will appear.\r\nThis term comes from general computer [[UI]] tool tips from buttons or icons.\r\n==In WoWWiki==\r\nSee [[Help:Tooltips]] for information about how to make tooltips work on special links in WoWWiki.",},
			["Tool Bucket"] = { content = "The '''Tool Bucket''' is located around the [[Sludge Fen]] in the [[Barrens]].\r\n==Objective of==\r\nContains 1-3 Nugget Slug for the quest Nugget Slugs.",},
			["Toon"] = { content = "'''Toon''' is another word for a [[player character]] in-game.\r\n==Inspiration==\r\nThe word toon originates from the word ''cartoon'', in which a cartoon character is sometimes referred to as a toon.\r\n==See also==\r\n* [[Player character]]\r\n* [[Avatar]]",},
			["Toothgnasher's Skeleton"] = { content = "'''Toothgnasher&#39;s Skeleton''' is located in the [[Hall of Explorers]] in [[Ironforge]].",},
			["Top Piece of Lord Valthalak's Amulet"] = { content = "==Source==\r\nThis item drops from [[Theldren]] in [[Blackrock Depths]].\r\nThis item is provided for the following quests:\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n* Anthion's Parting Words\r\n==Top Piece of Lord Valthalak's Amulet as a quest objective==\r\nThis item is an objective of The Challenge.\r\n==Top Piece of Lord Valthalak's Amulet as an ingredient==\r\nThis item is used to make: \r\n* Lord Valthalak's Amulet",},
			["Tor'gan"] = { content = "'''Tor'gan''' is a level 40 [[Troll]] [[quest giver]] located in [[Hammerfall]] in the [[contested]] territory of [[Arathi Highlands]]. He mentions that \"once-cursed blood still runs through my veins\", indicating that Blizzard may have meant to make him an orc.\r\nHe starts the following quests:\r\n* Foul Magics\r\n** Foul Magics (2)\r\n* Raising Spirits (1)\r\n** Raising Spirits (2)\r\n** Guile of the Raptor (1)\r\n*** Guile of the Raptor (2)\r\n* Sigil of Thoradin\r\nSee [[List of Arathi Highlands NPCs]].",},
			["Tor'kren Farm"] = { content = "Located near [[Thunder Ridge]] in northwestern [[Durotar]], '''Tor'kren Farm''' hasn't seen as much profit as other [[pig farm]]s in the area. Previously run by [[Misha Tor'kren]] and her son, the fate of the farm is uncertain after the younger orc ventured out to hunt [[crocolisk]]s at the [[Southfury River]].",},
			["Tor'Watha"] = { content = "'''Tor'Watha''' is one of the two [[forest troll]] areas of [[Eversong Woods]]. It is much larger than the nearby [[Zeb'Watha]], and at the eastern ridge, there is a colossal fortress of some kind, with a massive set of gates. It is for now completely void of any inhabitants, and the forest trolls stay down in the camps below. It is possible this gate will lead into future forest troll lands, other than that of [[Zul'Aman]] which is now found in the [[Ghostlands]]. Currently there is a glowing instance portal behind the gate which can barely be seen between the gaps in the wooden slats. It is possible for a mage to blink through the gap in the gate, however, there is an invisible wall behind the gate which cannot be crossed. The antechamber of Tor'Watha appears identical to that of Zul'Aman.",},
			["Torchbelcher tribe"] = { content = "'''Torchbelcher''' is an [[ogre]] tribe allied with the [[Dragonmaw Clan|Dragonmaw]] orcs of the Wetlands. They provide the Dragonmaw with warriors and mages. Other than that, nothing more is known about the tribe.",},
			["Torch of Holy Flame"] = { content = "[[Sven Yorgen]] sent adventurers to forge a weapon capable of defeating [[Morbent Fel]]. [[Lightforge Ingot]]s salvaged from the sunken high elven [[Destroyer]], the [[Flying Osprey]], were used in its creation.\r\n[[Morbent's Bane]] is another name for it during the quest to kill Morbent Fel.\r\n==Source==\r\nThis item is a quest reward from Morbent Fel.",},
			["Torek"] = { content = "'''Torek''' is a level 24 [[quest giver]] located northwest of the [[Warsong Labor Camp]] in the [[contested]] territory of [[Ashenvale]].\r\nHe gives the quest Torek's Assault.\r\nSee [[List of Ashenvale NPCs]].",},
			["Torgos"] = { content = "'''Torgos''' is the lord of the [[Outland]] [[carrion bird]]s. He can be seen flying through the air high above the [[Bone Wastes]] in [[Terokkar Forest]]. \r\nThe quest Torgos! sends you to kill him and collect his tail feather.\r\n==Loot==\r\nTail Feather of Torgos (''Quest item'')",},
			["Torgus"] = { content = "'''Torgus''' is a well known Dragonrider of the [[Dragonmaw Clan]] during and after the Second War. He managed to get word of [[Gul'dan]]'s betrayal back to his chieftan, [[Zuluhed the Whacked]] and the rest of the Horde. After the war he was assigned to [[Grim Batol]] under [[Nekros Skullcrusher]] where the clan was keeping a large portion of the [[Red Dragonflight|red dragonflight]] enslaved. During one particular mission, he and his draconic mount encountered the black aspect [[Deathwing]]. Deathwing attacked Torgus and his fellow dragonriders, and Torgus narrowly managed to escape back to Grim Batol to warn his clan of the coming danger. Torgus' fate afterwards is unknown.",},
			["Torloth the Magnificent"] = { content = "'''Torloth the Magnificent''' can be found in [[Shadowmoon Valley]] . He is a powerful warrior of the [[Crimson Sigil]].\r\n==Drops == \r\n \r\n0.95% Chance of a [[rare]] drop.\r\n3.44% Chance of an [[Uncommon]] drop.\r\n1.34% Chance of a [[common]] drop.\r\n2.48% Chance of a [[poor]] drop.\r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Tormak"] = { content = "#REDIRECT [[Tormak the Scarred]]", redirect = "Tormak the Scarred",},
			["Tormak the Scarred"] = { content = "'''Tormak the Scarred''' is the Chieftain of the [[Camp Oneqwah]] Taunka. He starts and ends the quest The Unexpected 'Guest'. He also ends the quest Bringing Down the Iron Thane.\r\nSee [[Grizzly Hills NPCs]].",},
			["Torment"] = { content = "This is one of the four [[Warlock]]'s pet [[Voidwalker (Warlock pet)|Voidwalker]]'s spells, purchasable via grimoires at the various Demon [[trainer]]s throughout [[Azeroth]]. Torment generates threat on the Voidwalker's target so that it is more likely to attack the Voidwalker instead of the Warlock or his/her companions. It is instant-cast has a 5-second cooldown. \r\n==Talent Improvement==\r\n[[Improved Voidwalker]] increases threat generated.\r\n==Tips and Tactics== \r\nTorment is [[Shadow]]-based, so [[Curse of the Elements]] will help your Voidwalker land Torment more often. It can be resisted, and does not guarantee that your Voidwalker will get aggro in a snap. \r\nWhen set on [[auto-cast]], the game's AI merely uses this on the Voidwalker's current target whenever possible. The Voidwalker can cast Torment fairly consistently during combat, but prolonged periods of grinding will begin to eat into the Voidwalker's meager mana reserves.",},
			["Tormented Spirit"] = { content = "The '''Tormented Spirit''' is a level 9 [[rare mob]] [[banshee]] found patrolling the northwestern edge of the [[Agamand Mills]] in [[Tirisfal Glades]].\r\nShe is on a 1 to 2 hour respawn timer. Her and [[Lost Soul]]s' appearance may be connected.\r\n==Loot==\r\n*Ghostly Bracers",},
			["Torment of the Worgen"] = { content = "'''Torment of the Worgen''' is one of the books that can be found inside [[Sealed Tome]]s in the [[Guardian's Library]] in [[Karazhan]].\r\nUsing it grants you a 60 minute buff, giving your ranged and melee attacks a 3% chance to transform yourself into a [[Worgen]], dealing 200 additional shadow damage per hit, lasting 10 seconds. \r\n==Contains==\r\nUsing the book generates Singed Page (Torment of the Worgen) in your inventory.",},
			["Torm Ragetotem"] = { content = "'''Torm Ragetotem''' is a level 50 [[warrior trainer]] located on [[Hunter Rise]] in the [[tauren]] city of [[Thunder Bluff]].\r\nSee [[List of Thunder Bluff NPCs]].",},
			["Torn Bear Pelt"] = { content = "== As a quest objective==\r\nThis item is an objective of Torn Bear Pelts.\r\n==Dropped by==\r\nThis item is dropped by Gray Bear. Drop rate 21%.\r\nThis item is dropped by Vicious Gray Bear. Drop rate 22%.\r\nThis item is dropped by Elder Gray Bear. Drop rate 25%.\r\nThis item is dropped by Ashenvale Bear. Drop rate 21%.\r\nThis item is dropped by Elder Ashenvale Bear. Drop rate 25%.\r\nThis item is dropped by Giant Ashenvale Bear. Drop rate 29%.\r\nThis item is dropped by Ursol'lok. Drop rate 31%.\r\nThis item is dropped by Ursangous. Drop rate 25%.\r\nThis item is dropped by Big Samras. Drop rate 27%.",},
			["Torn Scroll Fragment"] = { content = "==Source==\r\nThis item drops from [[Enraged Rock Elemental]] in [[Badlands]].\r\n==Torn Scroll Fragment as a quest objective==\r\nThis item is an objective of The Lost Fragments.",},
			["Tortheldrin"] = { content = "#REDIRECT [[Prince Tortheldrin]]", redirect = "Prince Tortheldrin",},
			["Tortured Earth Spirit"] = { content = "'''Tortured Earth Spirit''' can be found in [[Nagrand]] .\r\nKilling the spirits will result in +10 reputation with [[Kurenai]], and are the objective of The Tortured Earth.\r\n==Drops == \r\n \r\nNote: % drop chance was correct at the time the page was generated/created. This will not be updated.",},
			["Torwa Pathfinder"] = { content = "'''Torwa Pathfinder''' is a level 51 [[quest giver]] located near the bottom of the ramp leading to [[Tanaris]] in the [[contested]] territory of [[Un'Goro Crater]].\r\n===Quests from Torwa Pathfinder===\r\n* Bloodpetal Poison\r\n** Toxic Test (Elite)\r\n*** A Better Ingredient (Dungeon)\r\n* The Fare of Lar'korwi\r\n** The Scent of Lar'korwi\r\n*** The Bait for Lar'korwi\r\n* The Apes of Un'Goro\r\n** The Mighty U'cha\r\nSee [[List of Un'Goro Crater NPCs]].",},
			["Toshley's Station"] = { content = "'''Toshley's Station''' is a [[gnome]]-run [[Alliance]] village found in [[Blade's Edge Mountains]]. Gnomes perform their craziest experiments here. It is managed by [[Toshley]], and was the only known gnome-only town until [[Fizzcrank Airstrip]] in the [[Borean Tundra]] was added later.\r\nApparently, the gnomes of Toshley's Station used to be in Sylvanaar until the Night Elves there sent them away since the gnomes' machines and experimentations interferes with their efforts in the grove.\r\nThere is an [[inn]] and flight point is available here, whilst players specialized in [[Gnome Engineering]] can teleport near this place with the [[Ultra-Safe Transporter: Toshley's Station]]. The teleport pad is some distance outside town, allowing Horde engineers to teleport here without suffering attacks from the town guards. \r\nThe [[Zephyrium Capacitorium]] is a device in Toshley's Station that players can repeatedly access after completing some quests from [[Tally Zapnabber]]. It throws the player into the air and allows them to glide to nearby locations including [[Evergrove]], [[Razaan's Landing]] and [[Singing Ridge]].\r\nHorde players are highly advised to stay away from the area. The guards are very powerful, fast, have a large aggro radius, and devastating ranged gun attacks (the guards all carry Core Marksman Rifles... an ominous sign). There are also flying machines that will blow you off your flying mount.\r\n===Flight===\r\n [[Sylvanaar]]\r\n [[Area 52]]\r\n==Toshley's Station [[NPC]]s==\r\n* Toshley\r\n* Nickwinkle the Metro-Gnome\r\n* Tally Zapnabber\r\n* Rally Zapnabber\r\n* Razak Ironsides\r\n* Dizzy Dina\r\n* Bossi Pentapiston\r\n* Sassa Weldwell\r\n* Bembil Knockhammer\r\n* Fizit \"Doc\" Clocktock\r\n* Rip Pedalslam\r\nJust outside the town:\r\n* Smiles O'Byron\r\n==Quests==\r\n* Test Flight: The Zephyrium Capacitorium\r\n* Test Flight: The Singing Ridge\r\n* Test Flight: Razaan's Landing\r\n* Test Flight: Ruuan Weald\r\n* Picking Up Some Power Converters\r\n** Ride the Lightning\r\n** Trapping the Light Fantastic\r\n*** Show Them Gnome Mercy!\r\n* Crystal Clear\r\n** Gauging the Resonant Frequency\r\n* What Came First, the Drake or the Egg?\r\n* Cutting Your Teeth\r\n* More than a Pound of Flesh\r\n* Ridgespine Menace\r\n==Popular culture references==\r\n* The name is a reference to Tosche Station, a settlement on Tatooine, from ''Star Wars''. One of the quests here is named [[Quest:Picking Up Some Power Converters|Picking Up Some Power Converters]], which is what Luke Skywalker claimed he was going to do at Tosche Station.\r\n* Every so often [[ravager]]s attack the outpost in a scene reminiscent of ''Starship Troopers''. The attack is repelled by an eyepatch-wearing gnome named Razak Ironsides and Razak's Roughriders, a group of [[mechanostrider]]-riding soldiers. This is a reference to \"Rasczak's Roughnecks\" and the character Lieutenant Rasczak, played by Michael Ironside in the movie ''Starship Troopers''. Also, quests are available from [[Dizzy Dina]], based on the character Dizzy Flores played by Dina Meyer.\r\n* The sentry before the trail to Toshley's Station is R-3DO, mix of R2-D2 and C-3PO from ''Star Wars''. His speech and behavior has also a little flavor of Marvin's speak from ''The Hitchhiker's Guide To The Galaxy'' (as well as referring to the now-defunct 3DO video game console).\r\n* The engineer running the transporter pad is named Smiles O'Byron, a reference to the character Miles O'Brien, engineer (and transporter operator) seen in ''Star Trek: The Next Generation'' and ''Star Trek: Deep Space Nine''.\r\n* The Station Sharpshooters quote: \"Somebody call for an exterminator?\" is a reference to the Ghost unit from the game Starcraft.",},
			["Toshley"] = { content = "'''Toshley''' is a level 69 [[quest giver]] who is in charge of [[Toshley's Station]] in the [[contested]] territory of [[Blade's Edge Mountains]].\r\nHe starts the following quests:\r\n* Picking Up Some Power Converters\r\n** Ride the Lightning\r\n** Trapping the Light Fantastic\r\n*** Show Them Gnome Mercy!\r\nToshley also ends the quest Follow the Breadcrumbs, which starts from [[R-3D0]].\r\nSee [[List of Blade's Edge Mountains NPCs]].",},
			["Totem"] = { content = "#REDIRECT [[Shaman totem]]", redirect = "Shaman totem",},
			["Totemic Druid"] = { content = "#REDIRECT [[Totemic druid]]", redirect = "Totemic druid",},
			["Totemic Focus"] = { content = "''Some shamans place emphasis on totems as a channel for the elemental spirits whose powers they call upon. With practice, creating these objects of focus comes with less effort.''\r\n'''Totemic Focus''' is a [[Shaman]] talent that decreases the mana cost of totems.",},
			["Totemic Mastery"] = { content = "''Totemic Mastery'' is a [[Shaman]] talent that increases the effect range of [[Totem|Totems]].",},
			["Totems"] = { content = "#redirect [[Totem]]", redirect = "Totem",},
			["Totem (spell)"] = { content = "#REDIRECT [[Shaman totem]]", redirect = "Shaman totem",},
			["Totem of Rebirth"] = { content = "'''Totem of Rebirth''' is a rare [[relic]] for [[shaman]]s that reduces the cooldown of [[Reincarnation]].\r\n==Source==\r\nThis item drops from [[Isalien]] in the East wing of [[Dire Maul]].",},
			["Totem of Wrath"] = { content = "'''Totem of Wrath''' is a [[Shaman]] [[Totem]] designed to help your [[caster]]s do more damage.\r\n==Talent enhancement==\r\n* [[Totemic Focus]] reduces the mana cost of your totems by 5-25%.\r\n* [[Totemic Mastery]] increases the radius of your totems that affect friendly targets to 30 yards.",},
			["Tothrezim"] = { content = "The [[demons|demonic]] '''Tothrezim''' are a secretive race hidden in the darkest corners of the Twisting Nether with an ability to tap into the swirling invisible eddies of power of the nether. They are the distant cousins of the dread [[nathrezim]]. They serve [[Sargeras]] as laborers, researchers, businessmen and debt collectors, particularly in constructing and selling infernals.\r\nThey have leering, demonic visages with deeply sunken eyes and smooth skin. Great, hooked wings extend from their backs, marked with elaborate symbols fashioned from acts of self-mutilation, including ornate stitching and a series of intricate cuts. They are a dark-skinned humanoid that would stand at least twice as tall as a normal man, were its form not unnaturally hunched over. Four abnormally large arms connect to bulbous shoulders, each clutching a glistening, black blade. A tothrezim’s claws drip with a fel poison that eats at the very sanity of a creature. The tothrezim are mystically linked to the Twisting Nether and can draw power directly from it. The tothrezims’ link to the Twisting Nether also allows them to focus its energy into constructs, giving sculpted rock a chaotic life born of the Nether.\r\nThe tothrezim share a common ancestry with the cruel nathrezim, but while the nathrezim serve Sargeras as lieutenants in his armies, the tothrezim serve as his laborers and craftsmen. They slave away with mining picks and in magical laboratories with a nearly single-minded common goal of filling the [[Burning Legion]]’s demand for [[infernal]]s.\r\nThe tothrezim were never expansionistic or military-minded, but they share a unique bond with the [[Twisting Nether]] and an unmatched greed for gold and magic items. The bond enables them to infuse fiery constructs with fel power, and they\r\nhave used their ability to establish themselves as a dominant force in Sargeras dire plan. \r\nA gray ore known as fel stone litters the physical spaces of the Nether. It functions as a conduit for the Nether’s entropic energies. The tothrezim mine the ore and shape it to create shells that channel the energy. The results are fiery infernals. The tothrezim craft them for the Burning Legion, but their greed drives them to sell their constructs to whoever will pay the price they demand. The tothrezim are organized, businesslike and undiscerning. They’ll offer a contract for infernal summoning to anyone who is capable of paying.\r\nThe tothrezim accept any form of payment. They take gold, gems, jewels and especially magic items. Clients are billed every few weeks and payment is expected immediately. One of the tothrezim's collectors teleports or plane shifts to the client's location. Those who dodge their obligations or attempt to hide from scrying attempts, through nondetection or similar magic, are dealt with harshly. The tothrezim have four specialized collection teams usually consisting of: one tracker who serves as scout and spy; one divine caster; 2 arcane casters, one of whom serves as group leader; and three adamantine stalkers. For particularly dangerous debt collections, the tothrezim maintain one group comprised of the individuals below and five adamantine stalkers.\r\n==Famous/Named==\r\n*[[Thathrell]] — Leader of a group of debt collectors. A [[sorcerer]], [[warlock]], and [[warmage]].\r\n*[[Kurzill]] — A [[barbarian]] and [[primal]].\r\n*[[Dweezel]] — A [[healer]].\r\n*[[Mazgrek]] — A [[rogue]].",},
			["Touarril"] = { content = "'''Touarril''' is a male human [[shade]]. He is a [[healer]] and a [[priest]]. The creature has skin of deepest black. Its head has no distinct features other than a pair of eyes that glow with an unnerving white light. Simple black velvet apparel with a vague resemblance to monastic robes shrouds its frame. He speaks [[Abyssal (language)|Abyssal]], [[Common]], and [[Orcish]].",},
			["Touch of Defeat"] = { content = "Which of the following were you looking for?",},
			["Touch of Weakness"] = { content = "'''Touch of Weakness''' is a [[Schools_of_Magic|Shadow]] spell/ability usable only by [[undead]] and [[Blood Elf|blood elven]] priests. This skill makes an attacker's attacks weaker. \r\n==Notes==\r\nCasting Touch of Weakness applies a 10 minute buff to the Priest. When an enemy target successfully hits the Priest in melee, the target is hit for a small amount of Shadow damage (which can be modified by Shadow/general spell +damage) and a 120-second (2 minutes) duration debuff is applied to the target that reduces melee damage. This debuff does not stack.\r\n==Tips and tactics==\r\nTouch of Weakness can be very useful for a Priest who has invested heavily in the [[Shadow]] talent tree. Although the amount of damage that is reduced at high levels is fairly insignificant, the true power of Touch of Weakness is the Shadow damage component. Since Shadow damage is dealt to the target, Touch of Weakness will apply a charge of [[Shadow Weaving]] to the target (if the Priest has fully invested in the [[Shadow Weaving]] talent), and it also has a chance to proc [[Blackout]], making it a useful tool against Rogues, Warriors, Enhancement Shamans, etc.",},
			["Touch of Zanzil"] = { content = "'''Touch of Zanzil''' is a [[poison]] [[debuff]] received when doing the quest Klaven's Tower or Mission: Possible But Not Probable.\r\nIt is cured by Eau de Mixilpixil or Hinott's Oil, but can also be cleared by anti-poison spells and [[Anti-Venom|anti-venom]] items.",},
			["Toughened Leather Armor"] = { content = "==Source==\r\nRequires [[Leatherworking]] (120)\r\nThis item can be aquired through crafting or another combine-type effect.\r\n==Toughened Leather Armor as a quest objective==\r\nThis item is an objective of Carnival Jerkins.",},
			["Tough Scorpid collection"] = { content = "An item collection. This is ''not'' a true [[set]]. There are no bonuses if you wear more than one or all of this set.\r\n==Details==\r\n Type: [[Mail]]\r\n Made by: [[Leatherworking]]\r\n Primary Materials Required\r\n* [[Scorpid Scale]]s\r\n* [[Thick Leather]]\r\n Primary Stats\r\n* [[Agility]]\r\n* [[Spirit]]\r\n Classes\r\n* Hunters from level 40\r\nA total of 80 [[Scorpid Scale]]s are required to make the entire set.\r\nReferences:",},
			["Tower"] = { content = "A '''tower''' is a defensive unit in [[Real Time Strategy|Real Time Strategies]] such as [[Warcraft I]], [[Warcraft II|II]] and [[Warcraft III|III]]. Using it offensively is called [[Offensive Towering]].",},
			["Tower of Althalaxx"] = { content = "In the time of the [[Great Sundering]], [[Queen Azshara]] brought her favored servitors, those of the [[Highborne]], to the twin towns of [[Ameth'Aran]] and [[Bashal'Aran]]. To govern these towns, Azshara placed [[Athrikus Narassin]], an elf of considerable magical power. Athrikus was at first loyal to his queen, but eventually he grew bored of his post, and would spend most of his days in the '''Tower of Althalaxx''', some ways removed of the towns.\r\n10,000 years later, a dark theory about the Tower of Althalaxx has proven true: A cult has gathered at the tower with many [[warlock]]s amongst their number, even including a foul [[satyr]]. They call themselves the [[Cult of the Dark Strand]], and it may be possible that Athrikus is indeed their leader, although why they are assembling now is a dark mystery.",},
			["Tower of Arathor"] = { content = "'''The Tower of Arathor''' is found inside [[Stromgarde Keep]] in [[Arathi Highlands]]. It was formerly a tower dedicated to the study of the wizards of [[Arathor]], but has since the fall of Stromgarde been taken over by the [[Boulderfist]] [[ogre]]s.",},
			["Tower of Azora"] = { content = "Population: 100\r\nThe Tower of Azora is a small [[mage tower]] in Eastern [[Elwynn Forest]]. The tower is run by a number of servants of Azora, who all appear to be [[Gnome|Gnomish]], and who are in turn presided over by the archmage of Azora, [[Theocritus]]. The denizens of the tower are in a constant feud with the inhabitants of the [[Tower of Ilgalar]] in [[Redridge Mountains]], ruled over by the evil sorcerer [[Morganth]]. The two towers are constantly spying on one another through magical means.\r\nInside the tower are several vendors, and most notably, the [[Artisan]] enchanter for [[Alliance]].\r\nAn interview with the servants of Azora in the [[Gadgetzan Times]] shows the servants to be unable to wield magic and somewhat resentful of the abilities of their masters. It also shows that many things straying too near the tower are adversely affected by the magical aura, so the servants often have to battle living buckets and mutant butterflies.\r\n==Eye of Azora==\r\nOn the table at the top floor of Tower of Azora, there is a magical artifact named [[Eye of Azora]], which allows anyone who touches it to see the surroundings of the Tower of Ilgalar. There is no such device in Tower of Ilgalar.\r\n==Tower Location==\r\nIn Eastern Kingdom, in Elwynn Forest.\r\nEast of Goldshire, Northwest of Brackwell Pumpkin Patch.\r\nThe coordinates are 63,70.\r\n==See Also==\r\n* [[Azora]]\r\n* [[Tower of Ilgalar]]\r\n* [[Theocritus]]\r\n* [[Gnomish]]",},
			["Tower of Eldara"] = { content = "The '''Tower of Eldara''' was once part of the extensive [[night elven]] civilization that stretched across most of what is now called [[Azshara]]. It is located on the very tip of land northeast of the [[Bay of Storms]], and the sandy beaches near the tower are heavily patrolled by [[murloc]]s, [[makrura]] and [[hydra]]s. The tower itself stands closed and abandoned.",},
			["Tower of Ilgalar"] = { content = "The '''Tower of Ilgalar''' is a [[mage tower]] in eastern [[Redridge Mountains]], controlled by [[Morganth]], a powerful sorcerer who controls the [[Shadowhide Gnolls]]. After being exiled from The Mage Quarter of Stormwind, he took up residence here where he continues his study of the dark arts. There are a few quests involving the tower and its occupant, including [[Quest:Solomon's Law|Solomon's Law]] and a quest obtained in the [[Tower of Azora]].\r\nBy using a magical artifact, the [[Eye of Azora]], in the Tower of Azora, you are able to see the Tower of Ilgalar and its surroundings. There is, however, no such device in the Tower of Ilgalar. Throughout the Tower of Ilgalar are dragon bones hung on display. On the top level, a small alchemy table also holds a human skull and a dragon skull. It is not known what interest Morganth has in these relics.",},
			["Tower of the Damned"] = { content = "The '''Tower of the Damned''' is located in the very center of [[Deatholme]] and serves as the headquarters of [[Dar'Khan Drathir]], master of the [[Scourge]] in [[Quel'Thalas]].\r\nThe Tower's every entrance is guarded by the dreaded [[shade|Eyes of Dar'Khan]], and its halls inhabited by [[necromancer|Deatholme Necromancers]] and their skeletal minions. Deep in the center is Dar'Khan himself. \r\n==Quests==\r\n* The Traitor's Destruction - from Magister Kaendris at the [[Sanctum of the Sun]]\r\n:Objective: Kill Dar'Khan Drathir and bring back his head (Dar'Khan is in the center of the tower)",},
			["Tower Point"] = { content = "'''Tower Point''' is a Tower for the Horde side in [[Alterac Valley]]. Numerous NPC patrols can be found around the tower, usually consisting of several guards and wolves. It is usually the second tower to be assaulted by Alliance players. It is found just south of [[Iceblood Graveyard]]. Like all towers and bunkers, it houses 4 [[Frostwolf Archers]].",},
			["Town"] = { content = "#REDIRECT [[Settlement]]", redirect = "Settlement",},
			["Towns"] = { content = "#REDIRECT [[Settlement]]", redirect = "Settlement",},
			["Town hall"] = { content = "'''Town Halls''' are the center of most [[human]] towns. As the size of the town increases, the town hall can be upgraded into a [[Keep]] or [[Castle]].\r\n==Human & Alliance Town Hall==\r\nThis is where the people of a settlement meet to discuss the issues of the day. The King’s servants, be they farmer, craftsman or peasant, will share their fears and hopes with the community in this building. It is also where the details of commerce are dealt with - the distribution of resources, and the spending of moneys. All shipments of gold and wood are routed through the Town Hall. The allocation of funds to build roads and walls are also addressed here. Additionally, it serves as a center where peasants can receive training in harvesting and mining, as to better serve the kingdom. Being the center of the settlement’s economy, there can only be one Town Hall. If it is destroyed, however, another can be built to take its place.\r\nThe Town Hall serves as a center for the community and commerce of the\r\nvarious towns and military outposts in Lordaeron. As the chief economic\r\nbuilding in any settlement, these sites are equipped to process vital resources\r\nsuch as lumber and gold. The steady stream of peasants, who laboriously\r\nharvest and transport resources, makes for constant activity near the Town\r\nHall. The training that Peasants require to assist in the growth of their community is also\r\ngiven here. In time the Town Hall may be improved and upgraded into a Keep.\r\nThe town hall is the nerve center of any human community and\r\nserves as the primary exchange for gold. It is also a center for training\r\nloyal peasants in their particular vocations, whether it be lumber\r\nharvesting, building construction, or gold mining. In time the town\r\nhall can be upgraded to stronger fortifications.\r\n===Undead Town Hall===\r\nAs was to be expected, the Undead creatures in former [[Lordaeron]] have inherited most buildings, including some Town Halls that are still standing. Some of these can be found at the following locations: [[Arathi Basin]] and [[Brill]].\r\n==Orc Town Hall==\r\nThis is where the denizens of an encampment came to meet and make their arguments heard during the First War. The constant bickering and backstabbing that occurs here is necessary, however, for it keeps them from killing each other in the street. The Town Hall is also where the encampment’s Overseer can keep a close eye on the resources and funds that are available, and use them as he sees fit. All shipments of wood and gold are brought here for his inspection. This is also where peons are given the training to do the simple tasks demanded of them by the Orcish empire. Blackhand has ordered that only one Town Hall be allowed to stand in each encampment, so that separate factions of Orcs will not arise. If the Town Hall is destroyed in battle, another can be built to replace it.\r\n==High Elven Town Hall==\r\nThe '''Town Hall''' helped the [[High Elf|High Elves]] fend off Arthas as he tried to attack their capital [[Silvermoon]] and [[Quel'thalas]] in Warcraft III by serving as a returning point for gold and training units. The [[Blood Elf|Blood Elves]] use a different Town Hall that produces different units in the Frozen Throne Expansion Campaign in Warcraft III. It cannot be built by the \"[[High Elf Worker|High Elf (Worker)]]\" probably due to the limited ability of the map editor prior to the Frozen Throne Expansion. With the Frozen Throne Expansion map editor, it is possible to make additional groups with building orders.\r\n==Blood Elf Town Hall==\r\nThe '''Town Hall''' helped the [[Blood Elf|Blood Elves]] and [[Kael'thas]] in Warcraft III Frozen Throne Human Expansion Campaign. \r\n==Town Halls in World of Warcraft==\r\nTown Halls can be found all around Azeroth, like [[Trollbane Hall]] in [[Arathi Basin]]. Many human towns, such as [[Darkshire]] and [[Southshore]] have them as well. You can usually find the mayor or magistrate of the town inside.\r\n===Statistics in Warcraft II===\r\n*1200 HP\r\n*Provides 1 food\r\n*Trains\r\n** [[Peasant]]\r\n===Statistics in Warcraft III(High Elf)===\r\n* 1200 HP\r\n* 5 fortified armor\r\n* Provides 12 food\r\n* Trains\r\n** [[High Elf Worker|High Elf (worker)]]\r\n===Statistics in Warcraft III(Blood Elves)===\r\n* 1500 HP\r\n* 5 fortified armor\r\n* provides 12 food\r\n* Trains\r\n** [[Blood Elf Engineer]]\r\n** [[Blood Elf Worker|Worker]]",},
			["Town Square"] = { content = "'''Town Square''' is the eastern part of the [[Kirin'Var Village]]. Numerous [[ghost]]s roam the area. There are four quests available: 3 from nearby questgivers, and one from a chain that begins in Area 52.",},
			["Traces of Silithyst"] = { content = "Acquired after turning in Silithyst dust at the player's respective collection site in [[Silithus]].",},
			["Trachela"] = { content = "'''Trachela''' is a quest related two-headed [[carrion bird]] living on [[Carrion Hill]] in the Bone Wastes of [[Terokkar Forest]]. She is the mate of [[Torgos]], and the player will require her carcass to lure him to the ground for the quest Torgos!.\r\nUnlike the other carrion birds in the area, Trachela has white plumage with black highlights, giving her a unique appearance. She is tameable by hunters, but does not come with any tamed skills. She is also immune to most crowd control and is immune to frost traps.\r\n==Loot==\r\nTrachela's Carcass (''Quest item'')",},
			["Tracker Gekgek"] = { content = "'''Tracker Gekgek''' is a [[wolvar]] [[quest giver]] found at [[The Skyreach Pillar]] in [[Sholazar Basin]]. He along with two other wolvar can be found cornering the [[bristlepine]] [[Razorpine]].\r\nHe starts the quest Playing Along.\r\nSee [[Sholazar Basin NPCs]].",},
			["Tracking"] = { content = "'''Tracking''' refers to any ability which allows the player to track [[resource]] nodes or [[mob]]s on the [[mini-map]]. Only one tracking ability can be active at a time. A control on the border of the mini-map allows the player to choose which type of tracking to enable (or none).\r\nThe ability to track the [[Mob | mobs]] in [[World of Warcraft]] is usually the sole bailiwick of the [[hunter]], although other classes have limited tracking capabilities as well. At advancing levels, the hunter can learn to track [[Beast]]s, [[Humanoid]]s, the [[Undead]], [[Track Hidden|Hidden]] foes, [[Elemental]]s, [[Demon]]s, [[Giant]]s, and [[Dragonkin]].\r\nWhen a mob-tracking ability is activated, every creature that fits the classification selected shows up on the mini-map as a labeled dot, color-coded to its friendliness (green) or hostility (red). Tracking can be used in a variety of ways to enhance the hunter's situational awareness. For instance, in an area populated by both beast and humanoid mobs, the hunter can switch between beast and humanoid tracking, and stay aware of where ~95% of the mobs are in his general vicinity. Tracking is also useful if one has to beat a hasty retreat to a rearward fortification for safety's sake. Just keep monitoring the mini-map while switching frequently between tracking modes to find the most aggro free escape route. You can also see the name of the mob (or player/pet) if you mouseover the dot on the minimap, which for instance makes finding one specific mob in a group of mobs easier.\r\nOther classes which have class-specific tracking abilities include:\r\n*[[Warlock]]s, who can sense Demons.\r\n*[[Paladin]]s, who can sense the Undead.\r\n*[[Druid]]s, who can track Humanoids while in [[Cat Form]].\r\nOther tracking abilities include\r\n*Any character who has the [[Mining]] profession can sense mineral veins.\r\n*Any character who has the [[Herbalism]] profession can sense herbs.\r\n*Characters with the [[Fishing]] profession may acquire [[Find Fish]], to track fish schools.\r\n*[[Dwarf|Dwarves]] have a racial ability which allows them to sense [[treasure]] [[chest]]s.\r\n*All characters can track useful types of NPCs, like [[flight master]]s or particular vendors, if any are nearby.\r\n*Engineers with Ultra-Spectropic Detection Goggles or one of the epic engineering helms automatically track mote clouds when they have them equipped. This is the only mode of tracking that will stack with other tracking modes.",},
			["Track Beasts"] = { content = "'''Track Beasts''' is a [[Hunter]] ability to track the Beasts that are in your immediate vicinity. This allows one to either follow a Beast with the intent of killing it, or finding a safe path through the local area [[mob]]s to minimize [[aggro]]; as in the case of having to escape from a fight turned sour. One may hover their mouse over a target on the minimap and get a minimal description.\r\nIt is useful when trying to track a rare beast with a specific name, to warn of incoming powerful beasts you don't want to meet like the [[Devilsaur]], or keep an eye out for any [[Druid]] trying to sneak up on you in [[Cat Form]] in a [[Battleground]].",},
			["Track Demons"] = { content = "Displays any nearby [[Demon|Demons]] on your minimap.\r\n===Uses===\r\n* This helps a [[Hunter]] locate [[Demon|Demons]]\r\n===Limitations===\r\n* Only one form of tracking can be activated at one time\r\n===Range===\r\n* ?\r\n===Cooldown===\r\n* None\r\n===Casting Time===\r\n* Instant\r\n===Upgrades===\r\n* N/A\r\n===Rank Table===\r\nN/A\r\n----",},
			["Track Dragonkin"] = { content = "Displays any nearby [[Dragonkin]] on your minimap.\r\n===Uses===\r\n* This helps a [[Hunter]] locate [[Dragonkin]]\r\n===Limitations===\r\n* Only one form of tracking can be activated at one time\r\n===Range===\r\n* ?\r\n===Cooldown===\r\n* None\r\n===Casting Time===\r\n* Instant\r\n===Upgrades===\r\n* N/A\r\n===Rank Table===\r\nN/A\r\n----",},
			["Track Elementals"] = { content = "Displays any nearby [[Elemental|Elementals]] on your minimap.\r\n===Uses===\r\n* This helps a [[Hunter]] locate [[Elemental|Elementals]]\r\n===Limitations===\r\n* Only one form of tracking can be activated at one time\r\n===Range===\r\n* ?\r\n===Cooldown===\r\n* None\r\n===Casting Time===\r\n* Instant\r\n===Upgrades===\r\n* N/A\r\n===Rank Table===\r\nN/A\r\n----",},
			["Track Giants"] = { content = "Displays any nearby [[Giant|Giants]] on your minimap.\r\n''\"It um... it really wasn't all that hard to find him...\"''\r\n===Uses===\r\n* This helps a [[Hunter]] locate [[Giant|Giants]]\r\n===Limitations===\r\n* Only one form of tracking can be activated at one time\r\n===Range===\r\n* ?\r\n===Cooldown===\r\n* None\r\n===Casting Time===\r\n* Instant\r\n===Upgrades===\r\n* N/A\r\n===Rank Table===\r\nN/A\r\n----",},
			["Track Hidden"] = { content = "'''Track Hidden''' is a [[Hunter]] ability that shows hidden units as points on the minimap.\r\n==Uses==\r\n* This helps when you're facing stealthed units such as [[Rogue|Rogues]].\r\n* The stealth detection increase is +30, which is the same as 6 levels. This means a level 64 hunter can detect a level 70 rogue at the same distance as a level 70 that doesn't have stealth detection increasing effects.\r\n*This is immensely useful in PvP. In a battleground, if you hear that a Rogue is nearby turn on Track Hidden to expose it as quickly as possible.\r\n==Limitations==\r\n* Only one form of tracking can be activated at one time\r\n* This only increases your stealth detection and places the [[mob|mobs]] YOU DETECT on your minimap. If a [[mob]] is much higher level than you and stealthed, it is likely you will fail to detect the [[mob]] before the mob has a chance to attack you.",},
			["Track Humanoids"] = { content = "Were you looking for...\r\n* ...the [[Track Humanoids (Hunter ability)|Hunter ability]]?\r\n* ...the [[Track Humanoids (Druid ability)|Druid ability]]?",},
			["Track Undead"] = { content = "Displays any nearby [[Undead]] on your minimap.\r\n===Uses===\r\n* When you need to find a particular type of [[Undead]] Track Undead allows you to find it much faster\r\n===Limitations===\r\n* Only one form of tracking can be activated at one time\r\n* Does not track [[Forsaken]] (Undead) '''Players''' - these register as 'Humanoid'.\r\n===Range===\r\n* ?\r\n===Cooldown===\r\n* None\r\n===Casting Time===\r\n* Instant\r\n===Upgrades===\r\n* N/A\r\n===Rank Table===\r\nN/A\r\n----",},
			["Tracy W. Bush"] = { content = "'''Tracy W. Bush''' served as a composer and sound designer for [[World of Warcraft]].\r\nHe also was a composer and senior sound designer for [[Warcraft III]] and Warcraft III expansion, as well as being a voice actor.\r\nThe only WoW character that he voiced was the [[murloc]].\r\nAs of mid-2007, he is Audio Director at NCsoft.",},
			["Trade"] = { content = "'''Trading''' is the way players exchange [[item]]s, [[money]] and some [[Professions|services]].\r\n==How to trade with other players==\r\n1. Click on the [[player]] character (or use a hotkey to select them), right-click on their portrait, and select '''Trade'''.\r\n2. A window will appear with several areas:\r\n* The left pane shows what you wish to trade, with [[item]] [[slot]]s and a place to enter any [[money]] (, , and/or copper ) you wish to pay.\r\n* The right pane shows what your target wishes to trade, with several [[item]] [[slot]]s.\r\n* A special \"no-trade\" slot at the bottom-left.\r\n3. Add the items you want to trade or expose and/or currency you want to trade on the left side:\r\n* Drag items you want to give to the other player in the upper slots.\r\n* Drag an item you want to expose to have some effect (an [[enchant]]ment usually) applied to it in the special \"no trade\" slot at the bottom.\r\nSome example effects that can be applied via the trade window:\r\n* [[Enchanting|Enchantment]]\r\n* [[Armor Kit]]\r\n* [[Sharpening Stone]] or [[Weightstone]]\r\n* [[Poison]]\r\n* [[Pick Lock]]\r\n4. Enter any money (, , and/or copper ) you want to give in the entry fields at the bottom.\r\n'''NOTE''': A warning alert will appear asking you to confirm the trade of money before the trade completes, if you decide to do that.\r\n5. Click the Trade button and your area (the left side) will become highlighted in <font color=\"lime\">green</font>. If the player you are trading with clicks their Trade button, their area (the right side) will become highlighted in <font color=\"lime\">green</font> also and the trade will complete.\r\n'''NOTE''': If anyone changes the items in their pane, their pane will un-highlight and the Trade button needs to be clicked again.\r\n==Additional Notes==\r\n* You ''can'' trade during [[combat]].\r\n* You must be in a certain range of the character you want to trade with to begin the trade.\r\n* The trade will automatically cancel if you move out of trade range.\r\n* You can trade an item by dragging it on the target character or their portrait and letting go the left-mouse button when over the character.\r\n* You can't trade with a character in process of [[Logout]].\r\n* You can choose to ignore all incoming trades via the options menu.\r\n* Players with a trial account cannot trade or be traded with.\r\n==See also==\r\n* [[Auction House|Auctions]]",},
			["Trader's Tier"] = { content = "The '''Trader's Tier''' is the area of the ''[[Exodar]]'' containing most of the [[trainer]]s and [[vendor]]s. This area houses various non-magic craftsmen and merchants, and also the [[Guild Master]] and [[tabard]] seller. Scattered around the floor are [[engineering]], [[mining]], [[blacksmith]], [[skinning]], [[leatherworking]], and [[tailoring]] trainers, as well as [[Dugiru]] the [[Alliance]] [[Cloth Quartermaster]]. Slightly up the stairs is the Hunter's Sanctum, with [[hunter]] trainers, and at the top of the ramp is a circular platform called the Ring of Arms with [[warrior]] and [[monk]] trainers and [[Handiir]] the [[weapon master]].\r\nThe [[naaru]] helped build the ''Exodar'', and [[M'iri]] designed the Trader's Tier, shaping it to attract talented tradesfolk. There's also a mural of M'iri, made from brightly colored glass. After the [[Fourth War]], the district was visited by [[Zekhan]] and [[Rexxar]]. Noticing the ''Exodar'''s system, the troll ambassador thought that some [[Horde]] [[engineer]]s would surely want to get their hands on the contraptions.\r\n==Facilities==\r\n*Blunt Weapons\r\n*Bladed Weapons\r\n*Plate Armor & Shields\r\n*Engineering\r\n*Mining & Smithing\r\n*Leatherworking & Skinning\r\n*Tailoring\r\n*Engineering\r\n*Hunters' Sanctum",},
			["Tradeskill"] = { content = "#REDIRECT [[Profession]]", redirect = "Profession",},
			["Tradeskills"] = { content = "#REDIRECT [[Profession]]", redirect = "Profession",},
			["Tradesman Portanuus"] = { content = "'''Tradesman Portanuus''' is a level 70 [[draenei]] [[quest giver]] and [[vendor]] located in the [[Sun's Reach Sanctum]] of the [[Isle of Quel'Danas]] once players have retaken the sanctum.\r\nHe is involved in the following quests:\r\n*Report to Nasuun†\r\n*Report to Nasuun (2)",},
			["Tradesmen's Terrace"] = { content = "'''The Tradesmen's Terrace''' is the area of [[Darnassus]] where most vendors keep their shops and the center of trade in the city. It is also the location of the Darnassus [[auction house]].\r\nTo access the Tradesmen's Terrace, you can head south from the Warrior's Terrace, east down a ramp from [[The Temple of the Moon]], or head southeast across some bridges from the Darnassus [[bank]].",},
			["Trade Coalition"] = { content = "The '''Trade Coalition''' is the [[goblin]]'s merchant empire, which is run by all five of [[Undermine]]'s goblin [[Trade Princes]]. It is huge, far-reaching and massively complicated. It commands the [[Trade Fleets]]. The Trade Coalition controls much of the commerce throughout the world. [[Trade Prince Steamwheedle]], the richest known goblin on [[Azeroth]], runs the shipping division practically on his own.\r\n==Other companies==\r\nSee [[Goblin organizations]].",},
			["Trade District"] = { content = "The '''Trade District''' (also referred to as the '''Bazaar District''') is just inside [[Stormwind City]] from the main gate. It is the place in the city where you can get most goods. The Guild Master is to the left in the [[Stormwind Visitor's Center|Visitor's Center]] when you come in and can help you make a guild or a guild tabard. The goods that are sold in the Trade District are cheese, arcane goods and reagents, general goods, flowers, cloth/leather/mail armor, bows, guns, and clothes. The [[bank]], [[mailbox]], and [[inn]] are on the southwest side of the Trade District. The [[Flight Master|Gryphon Master]] is up a ramp on the east side. [[Patch 1.9]] added the linked [[Auction House]] in the center of the Trade District.\r\nIn ''Cataclysm'', the Auction House and Bank are both redesigned, with the Auction House moved closer to the Inn. Also, a flight trainer and flying mount vendor have been added to the area that houses the flight master.\r\nTo get to the Trade District, you can head northeast from the [[Valley of Heroes]], southwest from [[Old Town]], southeast from the [[Cathedral Square]], or northeast from the [[Mage Quarter]].\r\n===Taverns===\r\n*[[Gilded Rose|The Gilded Rose]] ( Innkeeper)\r\n===Shops===\r\n*[[Empty Quiver|The Empty Quiver]]\r\n*[[Everyday Merchandise]]\r\n*[[Lionheart Armory]]\r\n*[[Pestle's Apothecary]]\r\n*[[Northshear Abbey]]\r\n*[[Trias' Cheese]]\r\n*[[Weller's Arsenal]]\r\n====Canals' shops====\r\n*[[Canal Tailor and Fit Shop]]\r\n*[[Denman Family Jewelers]]\r\n*[[Fragrant Flowers]]\r\n*[[Gallina Winery]]\r\n===Other===\r\n*[[Gryphon Roost]] ( Riding trainer; Flight master)\r\n*[[Stormwind Visitor's Center]] ( Guild needs: guild master, tabard design, and vendor)\r\n*[[Stormwind Counting House]] (Bank)\r\n*[[Trader's Hall]] ([[Auction House]])\r\n==Inhabitants==\r\n''Excludes the above areas.''\r\nOn the streets\r\n*Thomas Miller\r\n*Officer Brady\r\n*Officer Jaxon\r\n*Topper McNabb\r\n*Anastasia\r\n*Lancy Revshon\r\n*Ian Drake\r\n*Melris Malagan\r\n*Justine Demalier\r\n*Stephanie Turner\r\n*Renato Gallina\r\n*Alyn Black\r\n*Moni Widdlesprock\r\n*Miggi\r\n**Mangeclaw\r\n*Hero's Herald\r\n==Notes==\r\n*The [[Darnassus]] ambassador to Stormwind resides here at an inn.",},
			["Trade Fleets"] = { content = "Fleets of vessels (both merchant and military), the goblin '''Trade Fleets''' run goods all over Azeroth, and are the [[trade princes]]’ true power. Each fleet has its own captain, while Vice Admiral [[Grezzlik]] oversees all fleets.",},
			["Trade Good"] = { content = "An [[Ingredient|item]] that can be processed by a [[Trade Skill]] to be used in a [[Recipe|recipe]] for useful items.\r\nExample '''trade goods''':\r\n* [[Leather]], most can be processed into better leathers.\r\n* [[Cloth]], can be processed into [[Bolt]]s.\r\n* [[Ore]], can be processed into [[Bar]]s.\r\n* [[Dust]], [[Essence]] & [[Shards]], can be used for enchanting.\r\n* [[Primal]]s - [[TBC]]",},
			["Trade prince"] = { content = "'''Trade princes''' (aka '''merchant princes''') are the five (more or less) rulers of the [[goblin]] world, each of whom run their own private army (or armies), hold lands around [[Azeroth]], and collectively control the [[Trade Coalition]].\r\nA number of trade princes rule over the various goblin holdings around the world. Though the trade princes all live in the goblin island city of [[Undermine]] far from [[Kalimdor]], they each control their own private armies and trade fleets. In turn, each controls cast rings of trade, mining deforestation, slave rings, and poaching. The trade princes are the most cunning of their race and will stop at nothing to amass their fortunes and power, whether through legitimate means or via black markets and treachery. Goblins encountered on Kalimdor are either privateers or agents of the various trade princes of Undermine.\r\nOfficially, five trade princes exist, though one or two may be lurking about in the shadows. The goblins don’t elect their trade princes, nor are the positions hereditary; the trade princes killed, blackmailed and schemed their way to the top. Together, these five goblins make the mercantile machine run, organizing the extensive and complex Trade Fleets.\r\nAll of them together run the \"Trade Coalition\".\r\nOne Trade Prince thought the [[Horde]] was destined to win the war, and aligned with them. When the Horde lost, he left and went back to Kezan in dismay. From that point on, the Goblins decided to remain completely neutral, if only to better exploit both sides.\r\n==Subordinates==\r\nTheir hands are the [[mogul]]s. [[Baron]]s serve as magistrates for their land and holdings. Slavers run the slavery trade. Captains runs a single ship, and some run entire [[Trade Fleets]]. Admirals run more than one fleet. Traders and merchants work for the moguls and barons.\r\nAt the bottom are civilians and workers, and finally slaves.\r\n==Known Trade Princes==\r\n* [[Trade Prince Steamwheedle]] (May not run the cartel)\r\n* [[Nazz Steamboil]] (Disowned son of one)",},
			["Trade Princes"] = { content = "#REDIRECT [[Trade prince]]", redirect = "Trade prince",},
			["Trade Prince Steamwheedle"] = { content = "'''Trade Prince Steamwheedle''', one of the [[goblin]] [[Trade Princes]], is the richest known [[goblin]] on [[Azeroth]], and runs the shipping division of the [[Trade Coalition]] practically on his own. \r\nThe name \"Steamwheedle\" hints that he runs the [[Steamwheedle Cartel]], but is not specifically confirmed. It is implied that the [[Steamwheedle Cartel]] was the group of goblins that originally sided with the [[Horde]]. Currently the Horde is trying to improve relations with the cartel in order to get them to rejoin. If so then the Trade Prince would most likely have been Steamwheedle.\r\nPerhaps he is [[Ratso Steamwheedle]], or they are related.",},
			["Trade Quarter"] = { content = "The '''Trade Quarter''' is the central area and hub of trade of the [[Undercity]], located just beyond the lifts to the [[Ruins of Lordaeron]]. The center of the Quarter houses the bank, and most of the shops of the Undercity lie around the bank on a series of levels. All other parts of the city can be reached through this quarter via winding passages into the [[Canals]]. Under one of the bridges to the bank, you will find [[Jeremiah Payson]] the Cockroach Vendor.\r\nFacilities:\r\n* An [[Innkeeper]]*\r\n* A [[Bank]]\r\n* A Horde [[Auction House|auction house]] (outer ring)\r\n* A Bat Handler\r\n* [[Cooking]] trainer\r\n* [[Guildmaster]]\r\n*-There are no beds in this inn, only open wooden caskets (with no lining either.) Not recommended for the living.",},
			["Trading card game"] = { content = "#REDIRECT [[World of Warcraft Trading Card Game]]", redirect = "World of Warcraft Trading Card Game",},
			["Trading channel"] = { content = "= Tips for trading =\r\nMany new players get quite a surprise the first time they enter a capital city, when they see all of the colorful item names that pop up when clicked in the chat window. For the newbie, it can be more than confusing to figure out what's in-demand, what's cheap, and how to make money.\r\nThis guide isn't written completely [[NPOV]], because it contains a lot of firsthand experience on how [[World of Warcraft|WoW]] economy is used and misused. Most newcomers to this market can literally be harassed by other players, get ripped off, or even made the laughingstock of the trade channel.\r\nI will call buying/selling in the Trade channel \"the direct market\" because it is different from [[Auction House]] in that you can interact with others.\r\n==The basics in trading==\r\nWhen you first come into this world, you will notice that people are trying to sell all kinds of [[Item|items]] in the Trade channel. Mostly it's users offering their services, such as enchanting, leather-working, blacksmithing, etc., but you will notice a lot of [[rare|blue]] and even [[epic|purple]] item named too. The item names are clickable, so you can see the details on that specific item such as level requirements, stats, the [[DPS]], etc. \r\nIf you are new to [[World of Warcraft|WoW]], or just new to using the direct market, often you will find it difficult to evaluate a specific item's worth, and in many ways this is perhaps the beauty about it, as some would say. The reason is to make you buy quickly without a second thought, instead of having plenty of time to look up an item on the web. Another reason is if you have difficulties in selling a item on the [[Auction House]] and are tired of losing deposits every time, the trade channel is a good way to sell your items if you are in short supply of cash.\r\nThe trade channel can be a seller's as well as a buyer's market, depending solely on whether you know what price each item can be sold for!\r\n''Tip: start looking for the prices on Cloth (Linen Cloth, Wool Cloth, Silk Cloth, Mageweave Cloth, Runecloth and Felcloth) and if you have [[mining]], [[skinning]] or [[herbalism]] - look up what they get sold for, ex: Copper Ore, Light Leather or Earthroot''. Keep track of things you know from ordinary drops or gathering skills, items you are familiar with.\r\n==First things first==\r\nThere are 3 kinds of direct marketing in trade channel.\r\n'''Examples'''\r\n*WTS <the item link>\r\n*WTS <the item link> Cheap!\r\n*WTS <the item link> its good for a mid 40 lvl feral druid\r\n*WTS <the item link> only 1G!\r\nThere are many ways to mark your items on the trading channel and none of them are wrong - the question is how many [[Whisper|whispers]] can you handle? Most people will [[whisper]] you the [[Rare|rarer]] the item is, except if its [[Trade items|trade items]] and especially if you sell at a very low price and are announcing it.\r\nWord of advice is try not to use words like \"free\" or \"cheap\" or any other words that indicate \"salesmanship\", just \"WTS\" plus the link to the item. Cheap is relative so often you will attract Plzz'er, Goldfish and Sharks (see below) with too much salesmanship. It can though be a good idea to write if a given item has an enchant on it, not everyone notices if it does.\r\n*ex: WTS <the item link> with crusader\r\n==How to behave==\r\nYou are going to meet a lot of people in the Trade channel and have some odd and funny conversations, but you might also encounter mean or annoying people. These are words of advice for both sellers and buyers.\r\nWhen you are dealing in the Trade channel, be fair and helpful with any questions that buyers might ask you. Try not to brag about other sales or deals you've made; there is no reason to /flex your salesmanship, because it will only backfire and make people jealous.\r\nIt's a good idea to do a bit of research to get to know which items are used for which [[professions]]s or [[class]]es: Especially if you sell those items, so you can advise others on if it's an item they actually can use, or at least point them in the right direction. For example, if you are trying to sell a 2H weapon to a [[Warrior]] at [[level]] 55, and he isn't going to use it for his alt, tell him he might have a difficult time keeping aggro and that he should go with [[dual wield]]. You lose a potential customer if he's reasonable, but at least he knows whom to ask for items in the future and you will gain respect. If the customer wants it anyway, sell it, because it's not up to you to tell others how to play their [[character]]s.\r\nIf you sell an item and 5 minutes later that person's trying to sell it for a higher price than you sold it for, don't be angry and start harassing the person; it's part of the game. Be glad you got the money you wanted. There's always a chance that person won't be able to sell it for a profit anyway.\r\n==Trader personalities list==\r\nThis list is a stereotype of personalities you may encounter. It can help you understand more easily each type of person's intentions before you really get to know them. Many of these personalities come out in the light when you are selling [[Item|items]]\r\n'''The Plzz'er''' \r\n*This person often whines about having no money, and wants everything for free. They are easily recognized with their sudden whispers: \"plzzz i only have s=50 gold \", they are even willing to pay the next day or when they finally get their [[drop]] of Pristine Hide of the Beast. These are not serious and generally want everything for free. Don't trade with these people. They need to earn their items and gold instead of begging. \r\n'''The Goldfish''' \r\n*They start off by politely asking about an item's price, and when they find out it's too expensive for their wallet, they respond with: \"LOL nOOOb\" or \"stop playing wow\". They always try to bargain with \"i'll pay you g=10 gold \", even though you have evaluated [[item]] to g=300 gold . In many ways, they are like you, except they only want deals where they can make profit and they're rude about it. Do not answer them back when you get a \"LOL\" which is usually their second reply. Sometimes their first [[Whisper]] is a very low bid, even though they don't know what you actually are selling it for. Some of the goldfish can eventually become sharks. These guys can be really fun to run around in circles with, because they have a sense of item's value, but don't have salesmanship or think everyone is a [[noob]] or [[chinese farmer]].\r\n'''The Shark''' \r\n*Sharks are goldfish except that they have tried this tactic a lot, and with success. They are like goldfish, immature in their language, but it does not show off at first. They are often quite friendly at first and can switch [[character]]s fast, so you never know who you actually dealing with. In the end, they will become very rude and often begin harassing you. Some of these people actually remind you of an F16 Pilot in their persuasive personalities, but will fall back at immature language. Even though they have evolved from the goldfish stadium, they are still looking for the 400% profit, which often leads to their failure in this practice. However, sometimes they are quite good at jacking up prices for the entire community by making others believe their made-up prices. Their tactic can be to \"flush out\" your confidence and make fun of you in the Trade channel. Don't ever jump at that game, it lowers your standards as a seller and that is a part of tactic.\r\nWord of advise: Don't ever believe what they are saying and never deal with someone who is insulting you. If it becomes too much to handle, contact a GM for harassment.\r\n'''The Monkey Scratcher''' \r\n*This person wants the item but doesn't have the money-- however, they are often willing to trade with all kinds of random stuff. Sometimes the value of the items he wants to trade with actually make up for the price you have set, but more often than not it's far below. They are not rude in any way, they just want the item you got. Make it clear to them that you don't trade items for items unless they're worthwhile.\r\n'''Only got 1G''' \r\n*This personality resembles the Plzz'ers except that although they never have the money, they usually aren't rude but are sometimes sneaky. If you say a specific item costs g=215 gold they will constantly say: \"I want it!\" and then try to back down your price in the trade constantly no matter how often you tell them it's g=215 gold . When you meet up with this person, they insist on the price. It's like they ignore what you are telling them. They can take some of your time, but thats general the only thing they \"steal\".\r\n'''The Monkey''' \r\n*This is the fun guy, who is on the hunt for a good deal, expert humor is their weapon and it can be very charming and fun too. They are not always trying to scam other traders, but are looking for good deals. These are rare personalities and can be very funny to cut a deal with and sincerity goes a long way when dealing with these persons. Often you will find that they have added you on their friendslist and can wisecrack you on a daily basis for some time. These persons makes the trading worthwhile.\r\n'''The Kid''' \r\n*The kid is like the Plzz'er except the don't have a large vocabulary and often if they write a long sentence its doesn't make any sense. However they have no perception of prices but they can count to 100. They can be difficult to bargain with, often they deal never goes through. They talk often in oneletter words like \"k\",\"y\" or \"n\". If can easily spot them this way so don't be surprised if the deal does not go through. Often its actually difficult to find out whether they want a given item or not.\r\nThe Kid is not necessarily a child, but can also be someone who does not have a good level of English.\r\n \r\n'''The Thief''' \r\n*Always opens with \"how much\" and no matter how high a price you tell them, they say \"deal\" or \"I want it\". Great, you are thinking, until they say, \"can you C.O.D it too me?\". Usually this shouldn't be a problem, but these guys hope that you make a mistake and send the item in mail without C.O.D., perhaps even with money it. Often when you look up these persons up they use a alt at level 1 or 5. Sometimes they will want to meet in a major capital for the trading and hopes for you will bring up the trade window, lay the item in the window and hope you will push trade, without they put the money up. That way they have gotten your item for free. They thrive on human error to make a living, and they're yet another reason you should always pay careful attention while trading with others. \r\n'''Grand Theft Auto'''\r\n*These people should be called stalkers because they use many ways to get to you. They will target you. They switch characters fast, use the C.O.D. scam, and even the trade scam in hopes that you will eventually fall for it. They can stalk you for days and are very difficult too spot, only their misspelling and general behavior is the only indication of identity. If you're unlucky enough to find a talented stalker, they will even change the way they talk just to seem like different people.\r\n'''The F16 Pilot'''\r\n*These guys know everything about the market; they can list the curves on price inflation for any item. They have an information list on everything and can pinpoint at what times of the day prices will go up and down. They know what items cost down to the last copper and are more than difficult to trade with. They are very active and will often use their main character for dealing. They don't scam people, because they make a lot of money anyway and can be a good source of information if you are unsure of a specific item's worth.\r\n'''The Gamemaster'''\r\n*If you're into selling [[twink]] items for a very high price, sometimes you can run into a GM personality. They have a set price of what items should cost inside their heads and they hold that price to others. They generally want items to reflect the item level. If you are selling a rare level 20 item for about g=80 gold , they will try to reason with you, arguing that such item shouldn't be sold for such a high amount. Because [[Newbies|newbies]] don't have that amount of money, no one should have to pay that much for it. This type of thinking is wrong, of course, considering an item is worth what people will pay for it. However, be aware because some of these people can show characteristics of a shark if you talk to them long enough.\r\n'''Yourself''' \r\n*Also known as \"the mirror\". This is a person who has read this guide too. They are often open and willing to bargain and have fun with it. The conversation can rapidly turn into price discussion on the [[Auction House]] and tips giving good deals. It can be difficult to bargain with these persons, because they know the prices as well as you. Keep good relations with these people, and even if a deal isn't struck, at least you might have found a new friend.\r\n= How to price =\r\nThis is the difficult part of trading, unless you use outside sources. If you're still a newbie, and you haven't spent years memorizing your server's economy, you can always download an appropriate price [[addon]] (such as Auctioneer) or visit fansites that help you outline prices. Remember, every server has its own economy.\r\nIf you don't want to trust outside sources, here are some tips on learning how to price:\r\n*1: Spend a lot of time looking at the [[Auction House]], notice what sells, how long it's up and most importantly, what price it's listed at.\r\n*2: Memorize the prices on things you know from common drops, no matter what level you are on.\r\n*3: Start getting a sense of buyout prices\r\nWhen you are come this far, you will soon figure out that there are a lot of money too be made on auction hall, same goes for trading channel. The only problem is that often it is not white trading items that are sold in trading channel, but rather [[Rare|blue]] and [[Epic|purple]] [[item]]s and \"enchanter spammers\".\r\n==The \"right\" price==\r\nPlayers often don't know the value of their sellable [[item]]s, resulting in these items being either over- or under-priced. Indeed, a good deal of skill and knowledge is required in identifying unreasonable prices. \r\nIn the real world prices are controlled by different economic factors, including the value of a country's currency, wages and the buying power of the consumer. The WoW economy, however, is very similar to economies in the real world, particularly in that prices are determined by Supply and Demand. If an item is common, it is easier to find and therefore not likely to fetch a high price. If it is rare and in high demand, it is likely to fetch a higher price than a common item. This law of supply and demand is common to all economies, whether specific to MMORPGs or real-world. One difference, however, between WoW economics and real-world economics is that in [[World of Warcraft|WoW]] there is only one currency and therefore the factor of foreign exchange is irrelevant in WoW economics. Some factors that are perhaps unique to WoW are:\r\n# The proportion of different character types on the server compared to other servers\r\n# Population on the server\r\n# Vendor [[item]]s\r\n# Age of the realm\r\nWith regard to the first point, if Server A has more Paladins and Warriors than Server B, and both servers have the same overall population, then the price of Plate Armour on Server A will likely be higher than on Server B. This is because Plate Armour will drop just as often on each server, but on Server A more players will want those items. That is to say more players will be vying for a limited supply of Plate Armor, forcing the price on Plate Armor upwards. \r\nThere has been much speculation on how server population affects item prices, with such theories often yielding the equation:\r\n*''Low Population -> Low prices'' and thus ''High Population -> High Prices''\r\nSome argue that if the population is low then [[item]]s are dropped as [[Rare|rarer]] less often than on a fully populated server. Some argue that this makes items much more expensive, because high-quality items are dropped more rarely. On the other hand, if the server is sparsely populated then fewer players will be in demand for those few rare items, resulting in lower prices. \r\nTheoretically the server population should make little or no difference to the real value of any item. If the server population is high, then demand will be higher and prices will rise. In this case, however, rare items will drop more often, creating a greater supply to satisfy the increased demand. In the end the two forces should balance out and server population should be irrelevant in determining the price of rare items. \r\nOne thing thats is definitely true of low-population servers is that prices tend to fluctuate rapidly giving way to lots of trading. On highly populated server prices tend to be more stable, at least in theory, because players will notice underpriced items more quickly and resell them for a higher price, forcing the overall price of the item back up to \"normal\" levels.\r\nAnother factor that is interesting but very difficult to quantify is the effect of so-called \"chinese farmers\". Some say they have a enormous effect on the economy, while others claim the effect is minimal. This can be hard to monitor and there is really no way to figure out. \r\nYet another factor to account for is the age of the realm, on a newer realm prices tend to be fairer where and items are involved. While on older realms the prices for (low level) and items are usual very high because of the large number of [[twink]]s on the realm.\r\n'''Disclaimer: This theory and can vary from server to server and may not be accurate'''\r\n==Figuring out the right price==\r\nWhen you are looking for good deals, you have to not only know about the prices on many [[item]]s beforehand, but have to make proper estimations on buyout. \r\nFinding \"the right price\" these rules should be applied for sell price:\r\n*The sell should be reasonable and this means, it should be sold at a price that makes possible to resell the [[item]] with profit.\r\n*It is better to \"test\" the marked with a high price and then slowly go down in price over days or weeks, rather than the other way around.\r\n*Always make sure you can sell [[item]]s for g=5 gold -g=10 gold higher than you bought it for and [[item]]s g=2 gold -g=3 gold 's higher than the price you bought it for.\r\n*Always set two prices on items: one you tell others and one which is the minimum you want for the item (and is of course your secret).\r\n*Ex: if you want to sell a given item for g=50 gold (you bought it g=40 gold ), than perhaps g=43 gold is the minimum price you are willing to sell a given [[item]] too. This makes room for bargains and haggling which is essential for the trading.\r\nIf you are about to buy something and you aren't sure about the price, don't buy it no matter how much you crave it until you're sure it's a good price. Be careful about an item's worth.",},
			["Trag"] = { content = "''You may have been looking for the [[tauren]] [[Trag Highmountain]].''\r\n'''Trag''' is a level 64 [[stable master]] located in [[Stonebreaker Hold]] in the [[contested]] territory of [[Terokkar Forest]].",},
			["Trag Highmountain"] = { content = "'''Trag Highmountain''' is a [[tauren]] from the [[Highmountain tribe (Legends)|Highmountain tribe]] — which is known to have fierce warriors in the [[Horde]]. Trag was one of the first tauren to explore Lordaeron, where he befriended a human noble.\r\n===The Barony===\r\nTrag Highmountain chanced upon a small human [[Barony Mordis|barony]] in the [[Alterac Mountains]]. The barony was controlled by the kind and gentle Baron [[Valimar Mordis]]. The two soon became friends and Trag decided to stay. When the Scourge later came and slaughtered his friend and everybody else, Trag hid away...but not before killing some [[ghoul]]s.\r\n===Shadows of Ice===\r\nSometime later, a now undead Baron Valimar, running from the [[Scourge]], returned to his ruined fortress as a [[Forsaken]] and encountered Trag there, and together they worked to destroy the Scourge. They were after a particular Scourge leader, [[Ichor]], who wielded the [[Orb of Ner'zhul]] — which could revive [[ancient behemoth]]s or even [[frost wyrm]]s. The Baron wished to use it to raise a large army of undead but kept some of his plans secret from Highmountain.\r\nA young [[Sunwell|\"human\"]] woman, [[Anveena Teague]], arrived in the vicinity of the castle. She was \"rescued\" by Trag and the Baron. The Baron's intended to sacrifice the innocent Anveena &ndash; who held powerful magic within her — in order to utilize the Orb's power; this did not sit well with Trag. He soon awakened himself to the fact that the Baron he once knew was dead and gone, and that what stood in the Baron's place was no better than the Scourge. He tried to rescue Anveena but was defeated by Valimar.\r\nTrag awoke and confronted the Baron again as he raised his undead monstrosities. Trag closed his huge fist around the Orb in the Baron's hand, shattering it, and causing the [[frost wyrm]] that the Baron had summoned to come crashing down onto the castle, killing them both.\r\n===Fallen===\r\nThough killed by the fallen remains of the frost wyrm, Trag was raised in undeath by the Orb of Ner'Zhul's final magical act. Haunted by visions of [[Northrend]] and hearing the call of the [[Lich King]], Trag sought out the Highmountain tribe [[shaman]], [[Sulamm]], in hopes of reversing the curse and returning to life. Sulamm told him that it is not possible and claimed that he can remain with the Highmountains.\r\nAt the [[Henge of the Earth Mother]], Sulamm placed Trag in a trance state, promising to end his suffering; in truth, Sulamm had informed the tribe of Trag's fate, and led by [[Ornamm]], his kinsmen now attempted to burn him alive in a flaming pit. Within his mind, Trag began to stir. Trag felt something is wrong and awoke through what he assumed was the same power that returned him to life, he defeated his kin but didn't kill anyone, took the weapon of Ornamm, and left the shaman Sulamm in a trace state instead of killing him saying that he wouldn't kill a person that could not defend. He even ignored the [[Lich King]]'s whispers of killing his tribesmen.\r\n===Fear===\r\nFleeing towards Northrend, Trag avoided his kin and tried to slip past the [[orc]]s. The corruption caused Trag to suffer from fits of violent thought, and he felt he would eventually succumb to the power of the [[Lich King]].\r\nHowever, Trag encountered [[Thrall]], who became aware of his presence through his shamanic magic. Thrall offered to help, but Trag lost control of himself and the two battled. Even after calming down, Trag warned him to run before Trag lost control of himself again. However, Thrall outright refused to fight him, nor abandon him to fight against the voice of the Lich King alone. Thrall then told of how he had once feared becoming the animal [[Aedelas Blackmoore]] thought him to be, of falling into bloodlust to escape that fear; but the truth is, bloodlust would have only hidden his fear, leaving it to eat away at him forever. By bringing peace into his soul (possibly by facing his fear and accepting that his past is part of who he is), Thrall conquered his fear, survived, and found his redemption. If Thrall could do it, if [[Grom Hellscream]] could do it, so too could Trag if he would allow Thrall to help him. Trag denied that Thrall could do anything for him and warned him away once more. Thrall again refused, and when told that he would be struck down in accepting such a fate, he asked that Trag look him in the eyes \"as you do so I know my executioner\".\r\nTrag prepared to kill Thrall, only to see in his eyes that he truly does understand Trag's fear, a calm understanding that allowed Thrall to beat his own fear, and from which Trag now draws enough strength to deny the Lich King's demands to kill him. Thrall offered him shelter and safety with the orcs, which Trag turned down; he knew even better than Arthas that his fear would have turned him into a monster, but can't fully trust himself around others just yet. He decided to continue to Northrend and ensure for himself that he will never become one of the Scourge, even if that means self-destruction. Thrall told him that a Horde fleet of ships on the nearby shores of [[Durotar]] would be sailing north soon, and offered a small [[Frostwolf clan]] mark should he need to contact orcs. Trag turned down the mark but thanked Thrall for the offer; he was kind to someone who might have killed him. Thrall admitted with a smile that he wouldn't have just stood there if Trag had tried, but had judged the tauren correctly. Thrall said he would ask the spirits to watch over Trag and to his surprise bid him farewell by name, even though Trag had not mentioned it.\r\nTrag stowed away on one of the ships and reached Northrend. Even though he was almost sure that he would fail, more so that he would die, Trag was determined to meet his fate...without fear.\r\n===Fiend===\r\nTrag came to Northrend with only one purpose - to reach Icecrown and the Lich King. In the Borean Tundra Trag met the traveling taunka; [[Akiak]] when he was about to fall to a hole made by a Jormungar. Akiak took him to his village; [[Taunka'le]]. Trag was surprised by this action and by the taunka's hospitality, but he did not stay long. Having heard of the magic bones of the great dragons in the [[Dragonblight]] he, joined by Akiak whose mate, [[Buniq]], should be there, set out to find a piece for himself. They found the corpse of Buniq and a bone fragment belonging to the great [[proto-dragon]] [[Galakrond]]. Trag recognized its potential against the Lich King and brought it back to Taunka'le. When nearing the village, Trag and Akiak discovered that it was under attack by the [[Anub'ar]]. Trag successfully battled of the [[nerubian]] invasion, by jumping down the sinkhole from whence they had come and slaughtered their leader. Wandering though the nerubian-made caverns Trag finally reached daylight: at the foot of [[Icecrown Citadel]].\r\n===Fate===\r\nTrag made his way into [[Icecrown Citadel]] and confronted the [[Lich King]], but hesitated when he sensed that they shared some inner link. The Lich King explained that dark magic which reanimated Trag came from the Orb of Ner'zhul, and said, \"part of what I am comes from what was the spirit of its creator\". Trag cursed Ner'zhul's name, but the Lich King said, \"Ner'zhul is no more. He is consumed. There is only Arthas now... Arthas, whom you shall serve for all eternity.\" When Trag resisted, Arthas used his magic to dominate him. Trag was equipped as a death knight and ordered to slay a group of [[taunka]] he had assisted earlier in his journey as well as taunka's villages. With great difficulty, Trag managed to fight the Lich King's control. Turning on his new master, Trag struck Arthas's breastplate with his axe. Though the armor magically repaired itself, the Lich King was outraged by the tauren's audacity. As Trag was preparing to hit the Lich King with Galakrond's fragment, the Lich King blasted Trag out of the citadel and sent him flying through the air. Though Trag's body was broken by the fall, the essence of the orb soon reconstructed him, and he no longer heard the Lich King's voice in his mind. [[Akiak]] and his taunka defended him against anub'ar and invited him to live with them. Trag agreed and swore to protect his new family and home.",},
			["Train"] = { content = "'''Train''' has a few meanings in [[World of Warcraft]] and [[MMORPG]]s:\r\n# To improve some [[Ability|ability]], [[Power|power]], or [[Skill|skill]] by paying a [[Trainer]] or reading a training [[Book]].\r\n# To use [[Aggro|aggro]] to draw a bunch of [[Mob|mobs]] so they attack another group of [[Player]] characters.\r\n# To have several players use the auto-follow feature to travel in a long line.\r\n# The silly emote: /train\r\n==How Do I Train A Skill?==\r\nFind a [[trainer]] for the skill you want or want to improve and pay them the required [[money]] for the new [[ability]], [[power]], [[recipe]], [[spell]] or [[skill]].\r\nTrainers can usually be found in larger settlements, such as [[town]]s or [[city|cities]], but they are scattered throughout the world. The easiest way to find most trainers is to talk to a [[guard]] in a [[capital]] city.\r\n==Training Mobs==\r\nIn an [[MMORPG]], it is often possible to [[grief]] another player or party by [[aggro]]ing a number of nearby [[mob]]s that would ordinarily not be close enough to see the target party, then running toward the party so that the mobs chase you into them and attack them. If done at an inopportune moment, such as when the other player or party is currently fighting a close fight, this can turn their victory into a defeat and possibly a party [[wipe]], making \"training\" a way for a single player to use the environment to defeat an entire party of the opposite faction – or even of the same faction.\r\nThe developers of [[World of Warcraft]] seem to have realized that this is undesirable – even on a [[PvP]] server, the fact that one player could successfully and repeatedly grief an entire party of other players, even players of the same faction, could have a strong negative impact on a lot of people's gaming experiences. The WoW developers aren't against grieving behavior when there's a PvP remedy (if you can get together a group of allies to trounce the offending party or simply kill all the mobs quickly, the problem is solved), but when the griever is impossible to attack (is not set PvP, or is of the same faction as his targets), there is no such PvP remedy. There are, therefore, countermeasures against mob training in WoW:\r\n* Outside of [[instance]]s, a mob will break off pursuit of a player that stops attacking it, unless that player remains close to the mob [[spawn point]]. Once the mob is a sufficient distance from where it started, a player attempting to train it must continually attack it in some way, or else it will [[leash]] back to its spawn point in [[Evade]] mode, ignoring everything until it gets there. Inside instances things are different - mobs will typically chase players until they catch them.\r\n* A mob that is targeting a player will keep targeting that one until another player moves to the top of its [[Aggro|aggro list]] for some reason – the targeted player can die, [[Vanish]], use [[Feign Death]], etc., or another player can do enough damage to the mob to supplant the first player at the top of the mob's list. If there is no one else on its list, the mob leashes back to its spawn point, again meaning that it ignores everything on the way back.\r\n* Inside a normal (non-heroic/non-raid) instance, the only players present are all in the same [[party]], so there is no way for a player not in the party/group to train mobs on them.\r\n* It's possible to have multiple parties in the same heroic/raid instances, provided that all the party leaders have the same Raid ID. This can occurs under two circumstances: (1) the instance was not completed and more than one person decided to resume it, or (2) someone, having the Raid ID, decides to grief people and remain in the instance (which would take away an available spot in the instance so no one can get in). \r\nIt is therefore difficult to train mobs on anybody in WoW; they will only attack the target party if someone in the target party (although this does include [[hunter]] and [[warlock]] [[pet]]s) hits the mob as it goes by, and then only if the would-be mob trainer dies rather than getting away. If the mob trainer escapes, even if the mob has somebody else on its aggro list, the mob(s) will just leash back to their spawn points, ignoring the target party, and reset.\r\nTraining mobs on somebody has been made very difficult in WoW, although it is still not totally impossible. If done in such a way that there is no PvP remedy to the situation, it is a reportable offense.\r\nOne of the most famous examples of training occurred when a Horde guild successfully pulled Kazzak to [[Stormwind]].\r\n==Train Emote==\r\n* When a player types in '''/train''', they will start making train noises and movements. \"Woo wooooo! Chugga chugga chugga...\"",},
			["Trainer"] = { content = "A '''trainer''' is a special type of [[NPC]] that offers certain training or services, for a price. Guards in capitals can point players to the nearest trainer of any given type.\r\n ''interact with trainer '' ''trainer out of range''\r\n===Class trainers===\r\nClass trainers offer characters of the appropriate class the opportunity to reset their [[specialization]], [[talent]]s or [[glyph]]s, as well as selling the [[Dual Talent Specialization]] ability.\r\n* [[Death knight trainer]]\r\n* [[Druid trainer]]\r\n* [[Hunter trainer]] (with pet trainers)\r\n* [[Mage trainer]] (with portal trainers)\r\n* [[Paladin trainer]]\r\n* [[Priest trainer]]\r\n* [[Rogue trainer]]\r\n* [[Shaman trainer]]\r\n* [[Warrior trainer]]\r\n* [[Warlock trainer]]\r\n===Profession trainers===\r\nProfessions trainers give out [[Professions|profession]] [[skill]]s and [[recipe]]s, once the character has reached the appropriate level and proficiency.\r\n====Primary profession trainers====\r\n* [[Alchemy trainer]]\r\n* [[Blacksmithing trainer]]\r\n* [[Enchanting trainer]]\r\n* [[Engineering trainer]]\r\n* [[Inscription trainer]] \r\n* [[Jewelcrafting trainer]] \r\n* [[Leatherworking trainer]]\r\n* [[Tailoring trainer]]\r\n* [[Herbalism trainer]]\r\n* [[Mining trainer]]\r\n* [[Skinning trainer]]\r\n====Secondary profession trainers====\r\n* [[Cooking trainer]]\r\n* [[First Aid trainer]]\r\n* [[Fishing trainer]]\r\n* [[Archaeology trainer]] \r\n===Other trainers===\r\n* [[Riding trainer]]\r\n===Draenor Master===\r\n[[Draenor Master]] is the [[Warlords of Draenor]] stage of a [[Professions|profession]] where the player may create items upto and including skill of level 700 (requires ).\r\n===Zen Master===\r\n[[Zen Master]] is the [[Mists of Pandaria]] stage of a [[Professions|profession]] where the player may create items upto and including skill of level 600 (requires ).\r\n===Illustrious Grand Master===\r\n[[Illustrious Grand Master|Illustrious Grand Master]] is the [[Cataclysm]] stage of a [[Professions|profession]] where the player may create items upto and including skill of level 525 (requires ).\r\nSince the 4.x release patches all trainers will train to this level, except for the multi-profession trainers found in starting areas.\r\n===Grand Master===\r\nGrand Master is a title given to a [[trainer]] who can [[train]] a character to the [[Grand Master]] stage of a [[Professions|profession]] (requires ).\r\nGrand Master [[Trainers]] can be found in various far-flung locations for each [[faction]] in [[Northrend]], but most are found in the faction starting towns of ( [[Valgarde]] and [[Valiance Keep]] for the Alliance, [[Vengeance Landing]] and [[Warsong Hold]]) for the Horde, and [[Dalaran]] for both factions.\r\n===Master===\r\nBefore [[Patch 2.3]], Master was a title given to a [[trainer]] who could [[train]] a character to the [[Artisan]] stage of a [[Professions|profession]]. After Patch 2.3, most Master titles were removed from trainers, and all capital city trainers could train up to Artisan.\r\nIn the past, Master [[Trainers]] would be found in various far-flung locations for each [[faction]]. Some were even found inside dungeon [[instance]]s!\r\n===Other titles===\r\nPrevious to [[Patch 2.3]], profession trainers used to also have various levels of trainer titles from Journeyman to Expert to Artisan, such that they could only train to below the level of their title. Now in [[Azeroth]] (except [[Northrend]]), there is a main trainer and an occasional apprentice trainer (mostly in [[Silvermoon City]] and [[Undercity]] for some reason).\r\n==See also==\r\n*[[Pre-release weapon trainers]] for info on historical separate weapon skill trainers.",},
			["Trainers, Cooking"] = { content = "#REDIRECT [[Cooking trainers]]", redirect = "Cooking trainers",},
			["Trainers"] = { content = "#redirect [[Trainer]]", redirect = "Trainer",},
