			["Category:Games"] = { content = "'''Game''' related articles.",},
			["Category:Guilds"] = { content = "This category lists [[Help:Guild articles|guild pages]] created in WoWWiki for various [[World of Warcraft]] [[guild]]s.\r\n*For advice on making a guild page in WoWWiki, see '''[[WoWWiki:Policy/Writing/Guild pages|Guild article policy]]'''.\r\n*For a list of guilds organised alphabetically, see '''[[:Category:Guilds]]'''.\r\n*For a list of guilds organized by Realm, see the '''[[Realms list]]''' and choose a realm.\r\n*For information about utilities that may be useful for your guild website check out '''[[Guild website utilities]]'''.",},
