	["deDE"] = {
		data = {

			["A'dal"] = { content = "Der [[Naaru]] '''A'dal''' ist der Anführer der [[Sha'tar]] und befindet sich in der Mitte der Terasse des Lichts in [[Shattrath]]. Er ist der erfurchtsgebietendste Anblick, den viele je gesehen haben - ganz anders, als alles andere in diesem öden Land rund um [[Shattrath]]. Er ist vielleicht das mächtigste Wesen, das man je zu Gesicht bekommen wird und ist davon überzeugt, dass [[Kael'thas Sonnenwanderer]] aufgehalten werden muss.",},
			["A'lalai"] = { content = "A'lalai war eine alte Stadt der [[Dschungeltrolle]], die sich früher am Ufer des [[Schlingendorntal]]s befand und Teil des [[Gurubashi]]-Imperiums war. Es war Min'loth’s Sitz der Kraft, wo er seine mysteriösen Rituale durchführte. Nach dem Fall des Imperiums wurde es zu einer Unterwasserruine und ist jetzt vermutlich als [[Finsteres Riff]] bekannt.",},
			["A-Me 01"] = { content = "Um näher an die Affen des Kraters von [[Un'Goro]] heranzukommen, hat [[Karna Wirrbart]] eine mechanische Äffin geschaffen, die sich unbemerkt unter sie mischen kann - sie nennt sie '''A-Me 01'''. A-Me 01 hat Wahrsagesteine als Augen, so konnte Karna alles sehen, was auch sie sah.",},
			["Aaskralle"] = { content = "'''Aaskralle''' ist die Mutter aller [[Windroc]]s in [[Nagrand]]. Man findet sie bei den großen [[Roc]]s weit im Westen. [[Shado 'Fitz' Fernreiser]], ein Begleiter von [[Hemet Nesingwary]], der eine Expedition nach [[Nagrand]] leitet, möchte dass man einige der Windrocs jagt und ihm abschliessend das Auge von Aaskralle bringt.",},
			["Aasvogel"] = { content = "'''Aasvögel''' leben fast überall, wo sie Aas suchen, von dem sie sich ernähren. Doch sie sind gewitzte Vögel, die schwer zu finden und zu jagen sind. Man braucht sehr scharfe Augen und flinke Füße, um sie zu fangen. Ein Aasvogel ist ein schwieriger Gegner, aber als Verbündeter profitiert ein [[Jäger]] von seinen scharfen Angriffe und seiner bedrohlichen Präsenz. \r\nDiese Wildtiere unterstützen von Zeit zu Zeit die bösen [[Harpyien]] – da sie von der Aussicht auf frisches Fleisch und Blut angelockt werden und sind als Überträger von Krankheiten bekannt. Aber auch wegen ihrer Wehrhaftigkeit sagt man, dass der Tod tatsächlich Flügel besitzt. Auch auf [[Draenor]] hat sich eine ähnliche Art entwickelt - die [[Windroc]]s. Diese leben im Gebiet von [[Nagrand]] und unterteilen sich in agressivere und weniger agressive Arten.\r\n==Arten==\r\nZu den Aasvögeln zählen: \r\n* [[Geier]]\r\n* [[Bussard]]\r\n* [[Sturzflieger]]\r\n* [[Roc]]\r\n* [[Windroc]]\r\n==Persönlichkeiten==\r\nZu den namhaften Aasvögeln zählen:\r\n* [[Torgos]]\r\n* [[Trachela]]",},
			["Aasvögel"] = { content = "#REDIRECT [[Aasvogel]]", redirect = "Aasvogel",},
			["Aaswurm"] = { content = "Aaswürmer leben in den [[Östliche Pestländer|Östlichen Pestländern]] und sind die einzigen Tiere, die von den Verheerungen der [[Seuche]] unbeeinflusst blieben. Wenn sie auch ziemlich langweilig schmecken, kann das Fleisch der Würmer doch leicht monatelang aufbewahrt werden. \r\n==Besondere Tiere==\r\n* '''Blutschlinger''' - Hinter der [[Kapelle des Hoffnungsvollen Lichts]], dem Lager der [[Argentumdämmerung]], und westlich vom [[Nordtal]], findet man die wohlbeleibte Madenbestie Blutschlinger. Sein Leibesumfang ist gewaltig und je mehr er frisst, desto größer wird sein Appetit. Man weiß, dass Blutschlinger kleine Bataillone verschlungen hat, die töricht genug waren, ihn anzugreifen.",},
			["Abgesandter des Hasses"] = { content = "Die '''Abgesandten des Hasses''' sind Elitestoßtruppen der Brennenden Legion, die als Verstärkung für taktisch wichtige Stellungen eingesetzt werden. Wenn sie auf der Bildfläche erscheinen, scharen sich andere Dämonen um sie, denn die Abgesandten werden mehr gefürchtet als andere Gegner.",},
			["Abhandlung über Nethermagie"] = { content = "'''Vorabinformation'''\r\nFolgendes Buch ist vollständig in Thalassisch geschrieben und damit ist es ingame allen Nicht-Blutelfen nur über Umwege möglich an das Wissen des Buches zu kommen. Bitte auch nicht die folgenden Sachen als Gesetz nehmen, da sie weder offiziell bestätigt noch sonst irgendwie bewiesen sind. Und an alle die sich das antun wollen: viel Spaß beim Lesen.]\r\nEine Abhandlung über die Nethermagie\r\nVerfasst von Selian Flammenzorn (Blutelf-Hexer auf dem EU-Realm Die Aldor)\r\nInhaltsverzeichnis\r\nVorwort\r\nDie Nethermagie allgemein\r\nDie Beschwörung\r\nDas Auge von Killrog\r\nDer Wichtel\r\nDer Leerwandler\r\nDer Sukkubus\r\nDer Teufelsjäger\r\nAndere Dämonen\r\n= 1. Vorwort =\r\nWillkommen Brüder und Schwestern und all jene, welche mehr über die verworrenen Wege des Nethers erfahren wollen. Folgende Seiten beruhen auf den Erfahrungen, welche ich in den Studien der letzten 6 Jahre machen konnte. Ich distanziere mich hiermit von der allgemeinen Gültigkeit meiner Erkenntnisse, da sie allein aus meiner subjektiven Forschung und zum Teil nicht bewiesenen Erzählungen stammen.\r\n= 2. Die Nethermagie allgemein =\r\nUnter vielen Namen ist sie bekannt, die Form der Magie, welche ich im Folgenden nurnoch als „Nethermagie“ benenne. Allerdings sind sowohl Schattenmagie und dämonische Magie als auch verdorbene Magie und böse Magie gängige Namen.\r\nNachdem Prinz Kael’thas uns vor 6 Jahren durch einen Pakt mit Lord Illidan die Möglichkeit gab auf den Nether zuzugreifen, erkannten erst nur wenige das Potenzial, welches geschaffen wurde. Viele der Magister waren skeptisch, da mit der Nethermagie unweigerlich auch Dämonen zusammenhingen, welche nun schon zwei Mal kurz davor waren ganz Azeroth zu vernichten. Dennoch wagten einige den Schritt, unter ihnen auch meine Wenigkeit, um die neuen Mächte zu testen. Wir sollten nicht enttäuscht werden und auch wenn es sich anfangs schwierig gestaltete den Nether anzuzapfen, wurden wir mit der Zeit immer geschickter. Es war eine unbegrenzte Energiequelle, mit welcher es uns leicht möglich war, unseren Hunger nach Magie zu stillen. Das erkannten auch einige der vorher noch skeptischen Magister und so wählten auch sie den neuen Weg. Doch eine solche, unbegrenzte Machtquelle hatte auch ihren Preis. Man hörte immer wieder von „Unfällen“, bei denen einer oder mehrere Nethermagier zu Schaden kamen. Oftmals lag es daran, dass sie sich schlicht und einfach überschätzten oder sich zu tief in den Nether vorwagten und den Weg zurück nichtmehr fanden.\r\nDaraus lässt sich folgendes schließen:\r\n* Auch wenn es verlockend klingt die Mächte, welche tief im Nether lauern, anzuzapfen, sollte man sich doch vorsehen, da man leicht Mächte beschwört, welche man nicht mehr kontrollieren kann.\r\n* Nethermagier benötigen einen starken Willen, um sich von den Wesen im Nether nicht korrumpieren oder beeinflussen zu lassen.\r\n* Man darf sich selbst nicht überschätzen und sich vorsehen, wenn man in unbekannte Gebiete vordringt.\r\nAus diesen Gründen wurden Akademien eingeführt, an denen die Nethermagie von erfahrenen Nethermanten gelehrt werden sollte. Der zweite Grund für die Einrichtung war, dass die Lehrer nun den Fortschritt ihrer Schüler überblicken konnten und somit entscheiden konnten, wann der Schüler breit war tiefer in den Nether vorzudringen um neue Techniken der Beschwörung zu lernen.\r\nDie Akademien zahlten sich aus, die Rate der „Unfälle“ ging stark zurück.\r\nDes Weiteren ist über die Nethermagie zu sagen, dass sie in den Händen geschickter Nethermanten unterschiedlichste Formen annehmen kann. So ist es möglich sie sowohl defensiv als auch offensiv einzusetzen. Im Folgenden werden ein paar Beispiele aufgeführt:\r\nSo soll einigen Nethermanten folgender defensiver Gebrauch der Nethermagie bekannt sein:\r\n* Unterschiedliche Arten von magischen Schilden gegen verschiedene Arten von Angriffen.\r\n* Erkenntniszauber mit welchen es möglich ist verborgene Dinge oder Wesen wahrzunehmen.\r\n* Eine enorme Verlängerung der Zeit, in der man ohne Luft auskommen kann.\r\n* Das aufspüren von dämonischen Präsenzen über große Distanzen.\r\n* Das kurzfristige Zurückschicken von Dämonen und Elementaren in die Welten, aus denen sie stammen. Je mächtiger der Nethermant, desto länger kann er die Verbannung aufrechterhalten.\r\nFolgendes gilt im Gegensatz dazu zur offensiven Verwendung:\r\n* Das Formen von Geschossen aus reiner Netherenergie.\r\n* Eine Verbindung über den Nether mit deren Hilfe man anderen Wesen sowohl Leben als auch Mana abziehen kann.\r\n* Das Entziehen eines Teiles der Seele, bevor sie nach dem Tod des Opfers endgültig im Nether verschwindet. Diese Technik ist ein wichtiger Bestandteil der mächtigsten Fähigkeiten des Nethermanten.\r\n* Eine Verbindung des Ziels zum Nether aufbauen, durch die es den Schrecken aus den Tiefen möglich ist, dem Ziel die Lebenskraft zu rauben und es dauerhaft mit ihrer Verderbnis zu besudeln.\r\nNeben der offensiven und defensiven Verwendung gibt es noch weitere Vorteile, die eine Verbindung mit dem Nether mit sich bringt. So kann man durch gezieltes Aufnehmen von dämonischen Mächten seinen Körper und Geist stärken. Doch unter einer solchen Verbindung leidet der Widerstand des Betroffenen gegenüber den Schrecken, die nur darauf warten eine Seele verschlingen zu können.\r\nNeben den körperlichen Veränderungen kann durch die Verbindung auch die Fähigkeit andere Zauber zu wirken beeinflusst werden. So kann der Zaubernde durch gezielte Anzapfungen des Nethers die Macht seines Zaubers vervielfachen.\r\nDoch sollten solche Verbindungen mit bedacht geöffnet werden und anschließend unter Kontrolle gehalten werden, denn wenn sie sich zu weit öffnen, ist es für die Schrecken des Nethers ein leichtes den Nethermanten zu verderben und ihn in den Wahnsinn zu führen. Wer sich einmal dem Wahnsinn hingegeben hat, ist nur noch durch eine gewaltsame Trennung zum Nether zu retten und das kann auch nur helfen, wenn es kurz nach beginn der Verderbnis geschieht. Denn wenn der Einfluss des Nethers zu groß wird, ist es nichtmehr möglich die Verbindung zu unterbrechen.\r\n= 3. Die Beschwörung =\r\nNachdem wir nun die allgemeine Wirkung der Nethermagie auf den Nethermanten und seine Umgebung gezeigt haben, wollen wir uns nun einer etwas spezielleren Form widmen, der Beschwörung.\r\nAuch die Beschwörung ist ein weiträumiger Begriff für den Nethermanten. Ich habe den Begriff in die folgenden drei Themen unterteilt (nach Schwierigkeit geordnet von oben nach unten: Leicht bis Schwierig):\r\n* Die Beschwörung von Gegenständen\r\n* Die Beschwörung von Personen\r\n* Die Beschwörung von Dämonen\r\n'''\r\nDie Beschwörung von Gegenständen:'''\r\nFangen wir mit dem einfachsten an. Unter der Beschwörung von Gegenständen versteht man kleine Dinge aus reiner Netherenergie, welche oftmals die Form von Steinen haben.\r\nAuch hier gibt es unterschiedliche Formen, welche allerdings schnell durchschaut sind. Bei allen diesen Beschwörungen, wird im Tausch gegen die Energie aus dem Nether ein Splitter einer Seele, welchen man vorher einem Opfer entzogen hat, geopfert um die Dämonen lang genug zu beschäftigen um an die nötigen Essenzen zu kommen.\r\n'''\r\nDer Gesundheitsstein:'''\r\nIm Gesundheitsstein sind kleine Mengen an dämonischer Macht gebunden, welche beim Verzehr (üblicherweise durch aufsaugen der Materie durch die Hände, bei niederen Rasse allerdings durch bloßes „essen“) in den Körper übergeht und dort, sobald freigesetzt, kleinere Wunden heilt. Die Macht wird vom Nethermanten in eine feste Form gebunden und somit vom Nether abgeschnitten. Dadurch besteht keine weitere Gefahr von dem Gegenstand und er kann auch von Nicht-Nethermanten verwendet werden. Je mächtiger der Nethermant, desto größer mehr Macht kann er in die Materie kanalisieren.\r\n'''Der Feuerstein:'''\r\nDie Macht dieses Steines wird üblicherweise aus der einem winzigen Teil der Essenz von Höllenbestien, welche sich im Nether befinden, gewonnen. In den Händen eines Fähigen Nethermanten kann die Kraft des Steines sowohl auf die Waffe, wodurch sie den Gegner mit Leichtigkeit versengen kann, als auch direkt auf die Zauber, welche als Grundmaterie das Feuer verwenden, kanalisiert werden. Auch hier gilt, dass die Möglichkeit der Kontrolle über die Essenz mit der Macht des Nethermanten skaliert.\r\n'''Der Zauberstein:'''\r\nIm Zauberstein werden die Magien des Nethers so vereinigt, dass der Nethermant mit Leichtigkeit die Wirkung seiner Zauber verstärken kann. Andererseits kann man die Kraft aber auch freisetzen um jegliche Form der schädlichen Magie vom Nethermanten zu bannen. Der Zauberstein hat die Besonderheit, dass sich seine Macht mit der Zeit wieder aufladen kann.\r\n'''Der Seelenstein:'''\r\nZu guter Letzt der Seelenstein, welcher ein Meisterwerk der nethermantischen Kunst darstellt. Mit ihm ist es dem Nethermanten möglich einen Teil der Seele eines Verbündeten vom Körper zu trennen und für eine begrenzte Zeit in den Stein zu sperren. Sollte der Körper, aus welchem die Seele stammte, sterben, zerbricht der Stein und die Seele kehrt in den Körper zurück, wodurch es ihm möglich ist wieder aufzuerstehen. Mit ansteigender Macht, ist es dem Nethermanten möglich immer größere Teile der Seele einzufangen, wodurch die Kräfte des Wiederauferstandenen spürbar steigen.\r\nDamit wäre auch dieser Teil abgeschlossen und wir gehen zur nächsten Schwierigkeitsstufe über. \r\n'''Die Beschwörung von Personen:'''\r\nNachdem die Beschwörung von Gegenständen noch relativ einfach war, benötigt die Beschwörung von Personen schon deutlich mehr Erfahrung. Bei einer solchen Beschwörung ist ein relativ schlichtes Ritual nötig um das Portal zu öffnen durch welches der Nethermant seinen Geist in den Nether schickt, um die gesuchte Person aufzuspüren und anschließend durch den Nether hindurch zur aktuellen Position des Nethermanten zu begleiten. Während dieses Vorgangs müssen zwei weitere Personen anwesend sein, die während der Beschwörung das Portal, durch welches die Zielperson in die uns bekannte Welt zurückkehrt, offen halten. Bei einem solchen Ritual streckt der Nethermant seinen Geist nur oberflächlich in den Nether aus, weshalb für gewöhnlich keine schweren Fehler passieren können. Sollte die Kanalisierung der zwei Helfer abbrechen, hat der Nethermant genug Zeit seinen Geist zurückzuholen. Des Weiteren ist es nötig den Dämonen, welche den Eingang zum Nether bewachen einen Seelensplitter zu Opfern um die Zielperson unbeschadet hindurchzugeleiten. Doch auch wenn das Ritual zu den einfachen gehört, sollte man den Nether niemals unterschätzen und eine gewissen Erfahrung besitzen um es durchzuführen.\r\nDie wahre Macht des Nethermanten zeigt sich allerdings erst in der letzten Stufe der Beschwörung. Wenn sich ein Nethermant lang genug mit dem Nether beschäftigt hat, reizt es ihn für gewöhnlich irgendwann, etwas aus dem Nether heraus in unsere Welt zu bringen und seinem Willen zu unterwerfen. Doch um so etwas möglich zu machen, ist ein komplexes Ritual nötig, was schwieriger wird, je mächtiger das zu beschwörende Wesen ist. Außerdem werden für komplexere Rituale oftmals spezielle Ritualformeln und mehrere Personen benötigt. Mit der richtigen Formel und ausreichend kanalisierenden Personen ist es beinahe möglich jeden Dämonen zu beschwören. So hat damals auch der Lich Kel’thuzad, der Diener des Verräterprinzen Arthas, es geschafft den Dämonenlord Archimonde nach Azeroth zu bringen. Allerdings sind für eine solche Beschwörung ein mächtiger Beschwörer (was für einen Sterblichen kaum zu erreichen ist) und der Wille des Dämons in unsere Welt zu kommen erforderlich.\r\n{Im nachfolgenden wird das Grundritual dargestellt und gezeigt, was benötigt wird um es durchzuführen. Nach jeder der nachfolgenden Beschwörungen, wird außerdem die Anpassung der einzelnen Ritualschritte für jeden Dämon gezeigt. Zum Schutz dieser Formeln, wurden die Rituale selbst in dämonischer Sprache niedergeschrieben, wodurch nur andere Nethermanten und Wesen, die der dämonischen Sprache mächtig sind, sie entziffern können. Einzig und allein die Zeichnungen, welche für jedes Ritual beigefügt sind, können von anderen entziffert werden, was ihnen allerdings ohne die zugehörigen Formeln nichts bringen würde.}\r\nJe mächtiger der Nethermant wird, desto mehr Kraft kann er in die Rituale stecken, wodurch sich die Dämonen stärker in unserer Welt manifestieren können. Dadurch steigt auch die Macht des Dämons.\r\n= 4. Das Auge von Killrog: =\r\n'''Generelles:'''\r\nBenannt nach dem Orc-Hexenmeister, welcher es als erstes schaffte, dieses Wesen zu beschwören. Das Auge ist der am einfachsten zu beschwörende Dämon und benötigt als einziges kein Ritual. Daher ist es auch dementsprechend schwach und kann dem Nethermanten einzig und allein zum Kundschaften dienen. Diese Aufgabe erfüllt das Auge jedoch sehr gut und hat so Manchem schon die Haut gerettet, bevor er in eine Horde Untoter gestürmt ist.\r\n'''Gefahr für den Nethermanten:'''\r\nPraktisch nicht vorhanden. Es wird keine große Verbindung zum Nether hergestellt und das Auge besitzt keine Möglichkeit seinen Meister zu verletzen.\r\n= 5. Der Wichtel =\r\n'''Generelles:'''\r\nIm Gegensatz zum Auge von Killrog, benötigt der Wichtel ein, wenn auch nicht besonders komplexes, Ritual um nach Azeroth gebracht zu werden. Nachdem man den Wichtel zum ersten Mal beschwört hat, schließt der Nethermant einen Blutpakt mit ihm, wodurch es ihm möglich ist den Wichtel erneut zu rufen und seinem Willen zu beugen.\r\nDer Wichtel selbst ist eine etwa 30 Zentimeter große Gestalt, deren Körper vollständig mit Flammen bedeckt ist. Bevorzugt verwendet der Wichtel Feuerzauber, mit welchen er sowohl den Nethermanten stärken, als auch dem Gegner schaden kann. Außerdem ist es dem Wichtel nachdem genug seines Körpers in unserer Welt ist möglich, seine Fähigkeiten zu stärken und in Folge dessen seinen Körper zum Großteil dauerhaft in eine andere Dimension zu verschieben um Schaden zu vermeiden. Doch durch diese Verschiebung ist es ihm nichtmehr möglich den Nethermanten im Kampf zu unterstützen. Einzig und allein der Blutpakt bleibt weiterhin wirksam.\r\n'''Sonstiges zum Wichtel:'''\r\nWichtel gelten als äußerst intelligent und können vielseitig zum entschlüsseln von Rätseln oder als Assistenten bei der Forschung verwendet werden. Allerdings muss dem Wichtel ein klarer Befehl gegeben werden, da er sich ansonsten nicht verpflichtet fühlt etwas zu tun.\r\n'''Gefahr für den Nethermanten:'''\r\nGering. Auch wenn der Wichtel oftmals seinen Unmut etwas zu tun bekannt macht, ist er durch den Blutpakt verpflichtet den Befehlen des Nethermanten folge zu leisten. Man sollte allerdings davon absehen den Wichtel zu berühren oder sich in die Schussbahn seiner Zauber zu bewegen. Sollte man es doch tun, kann es schnell passieren, dass der Wichtel einen, auch wenn er versichert, dass es keine Absicht war, mit einer seiner Attacken treffen kann.\r\n= 6. Der Leerwandler =\r\n'''Generelles:'''\r\nDer Leerwandler verkörpert eine alles verschlingende Kraft, welche nicht zu unterschätzen ist. Es wird ein komplexeres Ritual als beim Wichtel benötigt um ihn in diese Welt zu holen. Und erst nachdem man ihn im Zweikampf besiegt hat, erkennt er den Nethermanten als Meister an. Um ihn anschließend wieder nach Azeroth zu holen, muss das Ritual wiederholt und dem Leerwandler eine Seele geopfert werden, damit er sich nicht die des Nethermanten nimmt.\r\nDurch seine Materie ist es äußerst schwierig dem Leerwandler ernsthaft zu schaden, da er beinahe sämtlichen physischen Schaden in sich aufnehmen kann. Gegen magische Attacken ist er allerdings anfällig, auch wenn er sie dennoch bis zu einem gewissen Grat abfangen kann.\r\nDie Existenz des Leerwandlers in dieser Welt begründet sich allein auf die Tatsache, dass es hier genug Seelen gibt, die er verschlingen kann. Deshalb sollte er nach Möglichkeit nicht unbeaufsichtigt gelassen werden. Denn allein der Nethermant ist in der Lage den Leerwandler unter Kontrolle zu halten.\r\n'''Sonstiges zum Leerwandler:'''\r\nBleibt der Leerwandler zu lang an einem Ort, beginnt er langsam den Ort selbst in sich aufzunehmen. Deshalb sollte man ihn, wenn man für eine Weile ausruhen will, besser zurück in den Nether schicken.\r\n'''Gefahr für den Nethermanten:'''\r\nKontrollierbar. Auch wenn der Leerwandler selbst gefährlich sein kann, ist er, solange er unter Kontrolle des Nethermanten steht, keine ernste Gefahr. Sollte die Kontrolle des Nethermanten allerdings abbrechen, sollte man besser aufpassen.\r\nDes Weiteren sollte Körperkontakt vermieden werden, da der Leerwandler sämtliche Materie in sich aufnehmen kann. Wenn diese Punkte beachtet werden, stellt der Leerwandler eine kontrollierbare Gefahr dar.\r\n= 7. Der Sukkubus: =\r\n'''Generelles:'''\r\nIm Gegensatz zum Leerwandler, welcher auf die Materie der Gegner aus ist, jagt der Sukkubus die Seelen seiner Feinde. Das Ritual zur Beschwörung ist weitaus komplizierter als das zur Beschwörung des Leerwandlers und erfordert ebenfalls eine Seele, welche dem Sukkubus geopfert werden muss. Außerdem muss auch der Sukkubus zuvor im Zweikampf besiegt werden um den Nethermanten als Meister anzuerkennen.\r\nDer Sukkubus stellt einen ernsthaften Gegner für seine Feinde dar. Er ist ein Meister der Schmerzen und kann optimal zum Foltern eingesetzt werden. Mit Hilfe seiner Peitsche ist er aber auch im offenen Kampf nicht zu unterschätzen. Sobald sich genug Macht des Sukkubus in unserer Welt manifestiert hat, ist es ihm möglich weitaus mächtigere Fähigkeiten einzusetzen um seine Gegner in die Irre zu führen oder sich sogar für eine begrenzte Zeit für einen Großteil Azeroths unsichtbar zu machen. Durch diese Unsichtbarkeit, welche nur von Nethermanten und einigen wenigen anderen durchschaut werden kann, eignet sich der Sukkubus sehr gut als Leibwächter, da er schnell und unbemerkt aus der Unsichtbarkeit heraus angreifen kann.\r\n'''Sonstiges zum Sukkubus:'''\r\nDer Sukkubus ist als Meister der Schmerzen auch selbst nicht ganz abgeneigt gegenüber Schmerzen. Wenn Ihr ihn also bestrafen wollt, solltet ihr nach einer anderen Möglichkeit als Schlägen suchen, denn diese werden ihn wohlmöglich weiter ermutigen.\r\n'''Gefahr für den Nethermanten:'''\r\nMittel. Durch seine starke Bindung zu Schmerzen, ist es einem unkontrollierten Sukkubus leicht möglich dem Nethermanten erheblichen Schaden zuzufügen. Daher sollte der Sukkubus möglichst bei Laune gehalten werden, indem man ihn die Seelen der gefallenen Feinde verschlingen lässt oder ihm, wenn er längere Zeit nicht kämpfen kann, hin und wieder eine Seele opfert, damit er auf keine dummen Gedanken kommt. Außerdem sollten sich besonders männliche Nethermanten in Acht nehmen, da der Sukkubus auch ein Meister der Verführung ist. Doch wer sich ihm hingibt, wird dafür den Preis seiner Seele zahlen müssen. Ansonsten ist ein kontrollierter Sukkubus eine gefährliche Waffe.\r\n= 8. Der Teufelsjäger =\r\n'''Generelles:'''\r\nDer Teufelsjäger ist die letzte für einen einzelnen Nethermanten durchzuführende Beschwörung und benötigt dementsprechend einen Beschwörungszirkel, welcher die bisherigen noch mal um einiges übersteigt. Um ihn anzulocken muss eine Seele geopfert werden und wenn man ihn zum ersten Mal ruft, ist noch ein weitaus größerer Aufwand erforderlich um ihn anschließend noch im Zweikampf zu besiegen.\r\nDer Teufelsjäger ist der Alptraum eines jeden magischen Wesens. Er verschlingt die Magie wo er sie auch finden kann und ist damit eine perfekte Waffe gegen jegliche Form von magieerfüllten Wesen. Besonders als Druckmittel gegen andere Blutelfen hat er seine Wirkung gezeigt, da er ihnen sämtliche Magie aus dem Körper saugen könnte, was auf Dauer den Tod zur Folge hätte. Und da der Teufelsjäger keine Gelegenheit auslässt um seinen Durst zu stillen, muss man ihn gut unter Kontrolle halten, besonders in magischen Metropolen wie Silbermond.\r\nZum Einsatz kommt er besonders in Situationen wo man unerwünschte Magie beseitigen muss wie beispielsweise im Kampf gegen einen magiebewanderten Gegner. Der Teufelsjäger macht keinen Unterschied aus welcher Quelle die Magie stammt, die er verschlingt. So würde er sich sogar an Mitgliedern seiner eigenen Art vergreifen, wenn sich die Gelegenheit bietet. Mit der Zeit wird seine Kontrolle über die Magie immer stärker, weshalb er besser im Auge behalten werden sollte.\r\n'''Sonstiges zum Teufelsjäger:'''\r\nSollte man dem Teufelsjäger gegenüberstehen und nur auf magische Angriffe zurückgreifen können gibt es nur zwei Möglichkeiten:\r\n- entweder rennen und jemanden suchen, der auch nahkampftauglich ist\r\n- oder irgendwie versuchen die beiden langen Tentakel an der Seite des Körpers abzutrennen. Dann ist es dem Teufelsjäger nichtmehr Möglich die Magie in sich aufzunehmen.\r\n'''Gefahr für den Nethermanten:'''\r\nHoch. Sollte der Teufelsjäger außer Kontrolle geraten sollte der Nethermant schnell versuchen das Weite zu suchen. Wie bereits erwähnt nutzt der Teufelsjäger jede Gelegenheit aus um seine Sucht zu stillen. Wenn der Nethermant ihn also nicht unter seiner Kontrolle hat, kann es schnell passieren das Verbündete angegriffen werden. Um den Teufelsjäger zu beruhigen, kann man ihm einen Seelensplitter opfern, welchen er ebenfalls als Energiequelle betrachtet.\r\n= 9. Andere Dämonen =\r\nEs gibt Berichte von Nethermanten die mächtig genug sind noch andere Dämonen in unsere Welt zu bringen, allerdings ist die Gefahr die von jenen ausgeht im schlimmsten Falle lebensbedrohlich, da es Keinem gelingt sie dauerhaft zu kontrollieren. Eine Ausnahme bildet da vielleicht die Teufelswache, auf die ich hier allerdings nicht näher eingehen will, da diese Geheimnisse nicht für die Öffentlichkeit gedacht sind.\r\nNeben jener Teufelswache soll es im Teufelswald jemanden geben, der in der Lage ist eine Höllenbestie zu beschwören. Allerdings sind diese Wesen seit jeher unter Kontrolle der brennenden Legion und nur schwer zu bändigen. Wenn sie gebändigt sind, hält diese Kontrolle meistens nur kurzfristig an.\r\nAls mächtigste bisher bekannte Beschwörung eines Dämons von einem sterblichen Nethermanten ist die Beschwörung der Verdammniswache bekannt, welche ein äußerst komplexes Ritual mit 5 Teilnehmern und einem Wirtskörper erfordert. Die genauen Geheimnisse dahinter sollen mit der Zeit verloren gegangen sein, allerdings gibt es Gerüchte, dass ein Hexenmeister in den verwüsteten Landen bereit wäre, sie mit lernwilligen Nethermanten zu teilen.\r\nAbgesehen von den zum Kämpfen beschworenen Dämonen ist es dem Nethermanten auch möglich sich Wesen heraufzubeschwören, auf denen er reiten kann. Während die erste Beschwörung der eines Wichtels gleich, ist die Zweite mit sehr viel mehr Aufwand versehen. Allerdings entziehen sich dieses Wissen meinen Kenntnissen und so kann ich nur jeden Nethermanten selbst auf den Weg schicken sie zu ergründen.\r\nZum Abschluss würde ich gern noch auf das bändigen von Dämonen eingehen, die bereits in unserer Welt sind. Denn auch wenn die Rituale welche für sie benötigt würden bei weitem zu groß wären, um von einem einfachen Sterblichen durchgeführt zu werden, ist es doch möglich ihnen für begrenzte Zeit den Willen des Nethermanten aufzuzwingen. Doch ist so etwas äußerst gefährlich und sollte nur von erfahrenen Individuen durchgeführt werden, denn der Dämon wird, nachdem er sich befreit hat, keineswegs erfreut über seinen kurzfristigen Meister sein.\r\nVon daher kann ich nur jedem raten äußerst vorsichtig zu sein, wenn man sich mit fremden Dämonen einlassen will.\r\nHiermit endet meine Abhandlung über den Nether...\r\n'''Information'''\r\nDas original der Abhandlung befindet sich im Besitz des Autors und die einzige Kopie soll Gerüchten zufolge derzeit im Besitz der Bibliothek von Silbermond sein. Allerdings darf sie nicht aus der Bibliothek entfernt werden, um unerwünschten Duplikationen oder Übersetzungen vorzubeugen. Wenn jemand eine private Kopie wünscht, kann er sich jederzeit an den mich wenden (IC versteht sich).\r\nAlso dann, danke fürs lesen\r\nSelian",},
			["Absturzstelle"] = { content = "Die Absturzstelle auf der [[Azurmythosinsel]] ist der Startort der [[Draenei]]. Es ist ein Teil der [[Exodar]], der in das [[Am'mental]] stürzte.\r\nDie dringlichste Sorge der [[Draenei]] hier ist die Erschöpfung ihrer Heilkristalle. Sie müssen sie so schnell wie möglich wieder aufladen. Unglücklicherweise können sie das derzeit nur, indem sie das Blut der einheimischen Talmotten abzapfen. Von dem Schiff hätte man einige Apparaturen sichern können, die geeignete Ersatzteile für einen holografischen Emitter geliefert hätten, aber die heimischen [[Eulenbestien]] haben sie verschleppt, bevor sie sie überhaupt erreichen konnten.\r\n==Personen==\r\n* '''Botanikerin Taerix''' - Botanikerin Taerix ist bei ihren Lehrlingen außerhalb der Westseite des Schiffes und möchte den See von der schädlichen Strahlung reinigen. Sie hat auch eine Immunisierungsmethode vorbereitet, mit der die [[Nisteleulkin]]s behandelt werden können. \r\n* '''Proenitus''' - Proenitus wartet außerhalb des Schiffes, südwestlich am Fuße des Hügels und kümmert sich um die Wiederaufladung der Heilkristalle. \r\n* '''Technikerin Zhanaa''' - Technikerin Zhanaa konnte einen beschädigten holografischen Emitter nach dem Absturz bergen. Sollte sie ihn reparieren können, besteht die Möglichkeit, dass sie noch andere Überlebende außerhalb des [[Am'mental]]s finden. Doch sie braucht Hilfe, um Teile aus der [[Exodar]] zu bergen. \r\n* '''Zalduun''' - Zalduun ist ein Priester, der sich um die Verwundeten innerhalb der zentralen Kammer des Schiffes kümmert.",},
			["Abtei von Nordhain"] = { content = "Vor dem [[Der Erste Krieg|Ersten Krieg]] lebten in der Abtei von [[Nordhain]] zahlreiche Geistliche, die dem Studium der alten Schriften und Magie nachgingen. Viele dieser [[Kleriker]] verloren während des großen Krieges ihr Leben, als sie die königlichen Armeen im Kampf gegen die Orcische [[Horde]] unterstützten. In dieser schweren Zeit stand der Heilige Orden der [[Kleriker von Nordhain]] unter der Führung von [[Erzbischof Alonsus Faol]]. Seit Anbeginn des Krieges versuchten die [[Orcs]], sich Wissen über die Magie der [[Menschen]] anzueignen. So gelang es den Geistlichen schließlich, die Spionin [[Garona]] in [[Nordhain]] gefangen zu nehmen. Als die Stadt von der [[Horde]] verwüstet wurde, wurde auch die Abtei völlig zerstört. \r\n'''Quelle''': \r\n==Personen==\r\n* '''[[Erzbischof Alonsus Faol]]'''\r\n* '''Bruder Neals''' ist verantwortlich für die Essens- und Getränkevorräte von [[Nordhain]] und er wird hoch erfreut sein wenn er frische Trauben bekommt. Man findet Bruder Neals im Glockenturm der Abtei, wo er gern seinen Wein probiert.\r\n* '''Bruder Paxton''' ist der Verwalter der Bibliothek der Abtei. Er stellt für die Bücher, die er abschreibt, seine Tinte selbst her. Es handelt sich um sein eigenes Rezept. Sie verläuft nicht, sie schmiert nicht und sie trocknet sehr schnell. Dummerweise trocknet sie ein wenig zu schnell. Um mehr herzustellen, benötige er Rethbaneisenerz aus dem [[Rotkammgebirge]]. Großknecht Oslow in [[Seenhain]] ist sein üblicher Lieferant. \r\n* '''Eagan Pelzschneider''' befindet sich neben der Abtei, auf der linken Seite und sucht nach jemandem, der für ihn Wölfe jagt. Er haßt diese grässlichen Waldwölfe. Aber Wolfsteaks ißt er für sein Leben gern. Zähes Wolfsfleisch bekommt man, wenn man die Waldwölfe und jungen Wölfe jagt, die in [[Nordhain]] durch das Land streifen.\r\n* '''Marschall McBride''' befindet sich in der Abtei und ist der Vorgesetzte von Stellvertreter Willem. Er kümmert sich um die Überprüfung der Echokammmine und die dortigen [[Kobold]]tagelöhner. \r\n* '''Milly Geltmark''' ist eine Freundin von Stellvertreter Willem und hat ein paar Probleme. Sie ist mit ihrem Wagen auf der anderen Seite der Abtei, in der Nähe des Stalls. Eine Bande von Briganten, die [[Defias]], sind in die Weinberge von Nordhain eingedrungen, als sie gerade bei der Weinlese war. Sie hat es den Wachen von [[Nordhain]] gemeldet und sie haben Ihr versprochen, dass sie sich darum kümmern würden, aber sie hat Angst um ihre Traubenernte. Selbst wenn die [[Defias]] sie nicht stehlen, befürchtet sie, dass ihre Wachen beim Vertreiben der Rohlinge alles zertrampeln. Die meisten Trauben sind schon in Eimern gesammelt, aber sie hat sie in den Weinbergen im Südosten zurückgelassen. \r\n* '''Stellvertreter Willem''' befindet sich in der Nähe der Abtei und kümmert sich um die Vertreibung der Bruderschaft der [[Defias]] und [[Garrick Padfoot]] aus [[Nordhain]].",},
			["Abyss"] = { content = "Als '''Abyss''' werden die in der [[Scherbenwelt]] vorkommenden Weiterentwicklungen der [[Höllenbestien]] bezeichnet, die sich in ihrem Aussehen und ihrer Stärke von den Höllenbestien unterscheiden, die auf [[Azeroth]] beschworen werden. Man erkennt sie an ihren raueren und gezackteren Kanten auf ihren Panzern. Es gibt sowohl Abysse, die im Dienst der [[Brennende Legion|Brennenden Legion]] stehen, als auch Abysse, die unter [[Illidan]] dienen. Die Abysse der Illidari unterscheiden sich von den Abyssen der Brennenden Legion dadurch, dass in ihnen ein blau-grünliches statt des glutroten Feuers brennt.\r\n==Persönlichkeiten==\r\n* [[Supremus]]",},
			["Abyssischer Rat"] = { content = "Der Abyssische Rat besteht aus namhaften [[Elementare]]n, die ein Teil der treibenden Kräfte hinter den [[Schattenhammer Kult|Kultisten der Schattenhammer]] sind. Diese [[Elementare]] sind bekannt als Abyssische Templer und Abyssische Fürsten. \r\n==Templer==\r\n* [[Azurblauer Templer]]\r\n* [[Irdener Templer]]\r\n* [[Purpurroter Templer]]\r\n* [[Weißgrauer Templer]]\r\n==Fürsten==\r\nDie Abyssischen Fürsten können mittels eines entsprechenden [[Siegel der Anrufung|Siegels der Anrufung]] bei den [[Windsteine]]n in [[Silithus]] beschworen werden können. \r\n* [[Fürst der Asche]]\r\n* [[Fürst der Tiefen]]\r\n* [[Fürst der Splitter]]\r\n* [[Fürst der Stürme]]\r\n==Siehe auch:==\r\n* [[Hoher abyssischer Rat]]",},
			["Acherus"] = { content = "'''Acherus''', die Schwarze Festung, ist eine [[Nekropole]] hoch über den [[Östlichen Pestländern]]. Seinesgleichen gibt es nur ein Mal auf dieser Welt. Acherus ist die große Zitadelle des Todes. Nicht einmal die mächtige [[Naxxramas]] könnte einem direkten Angriff der Schwarzen Festung Stand halten. Obwohl die Gedanken der neuen [[Todesritter]] hier vielleicht noch vernebelt sind, haben die Truppen der Geißel keine Zeit zu verlieren. Sie müssen die Herrschaft über Acherus und ihre Gedanken erlangen, denn die Hörner des Krieges erklingen. Es ist der Wille des [[Lichkönig]]s, der die Todesritter vorantreibt. Niemand ist sich dessen mehr bewusst, als die Todesritter. Ihre schiere Existenz ist mit seinem Bewusstsein verbunden. Diejenigen, die der dunklen Bruderschaft unwürdig sind, werden ans Herz von Acherus gekettet. Über dessen Fassade zeichnet sich drohend das allsehende Auge von Acherus ab. Von dort aus kann sein Meister über große Entfernungen sehen und die Gebiete seiner Feinde ausspionieren. Was das Auge sieht, sieht auch der Lichkönig. \r\nIn Acherus beginnen frisch gebackene [[Todesritter]] ihre Kariere in den Reihen der [[Geißel]]. Bewacht wird diese Stadt von den [[Kriegsmaid der Val'kyr|Kriegsmaiden der Val'kyr]] und den Todesritterchampions. Man findet hier bekannte Größen, wie z.B. [[Baron Totenschwur]] und unter der Anleitung von [[Hochlord Darion Mograine]] werden hier die neuen Todesritter Schritt für Schritt in ihre Aufgaben eingewiesen. Unterweisung in ihren Talenten finden sie hier bei den Jüngern des Unheiligen unter Führung von [[Lady Alistra]], den Jüngern des Blutes oder den Jüngern des Frosts unter Führung des Lichs [[Amal'thazad]]. \r\n==Persönlichkeiten==\r\n* [[Amal'thazad]]\r\n* [[Baron Totenschwur]]\r\n* Der [[Lichkönig]]\r\n* [[Geißelkommandant Thalanor]]\r\n* [[Hochlord Darion Mograine]]\r\n* [[Instrukteur Razuvious]]\r\n* [[Lady Alistra]]\r\n* [[Meisterbelagerungsschmied Corvus]]",},
			["Addles Siedlung"] = { content = "Addles Siedlung ist ein Bauernhof liegt südlich der Straße von [[Westfall]] direkt am Rand des [[Dämmerwald]]s. Es muss zwei Wochen her sein, da hatten sich einige der [[Defias]]-Agenten in Addles Siedlung versammelt. Den Berichten zufolge, ging dort etwas Großes vor sich.",},
			["Admiral Prachtmeers Befehle"] = { content = "'''Admiral Prachtmeers Befehle''' finden sich in der [[Burg Tiragarde]] in [[Durotar]]. Es handelt sich dabei um einen alten, verwitterten Umschlag mit einem offiziell aussehenden Dokument und dem Siegel von Admiral [[Daelin Prachtmeer]]. Es sind die Offiziellen Befehle für die Flotte von [[Kul Tiras]].\r\n==Inhalt==\r\nIch, Admiral Prachtmeer, führe die erste Landung an der Küste von Kalimdor an.\r\n[[Leutnant Benedict]] führt in meiner Abwesenheit das Kommando. Sämtliche militärischen Angelegenheiten hier vor Ort in [[Kul Tiras]] werden von ihm geregelt. Sollte ich binnen der nächsten zwölf Monate nichts aus [[Burg Tiragarde]] hören lassen, führt Leutnant Benedict die zweite Welle zur Eroberung der Stellung an.\r\nIn der Zwischenzeit schicke ich [[Leutnant Alverold]] auf eine Erkundungsmission rund um den Kontinent Kalimdor. Nach Abschluss der Mission sollen sich seine Truppen wieder den unseren bei Burg Tiragarde anschließen.\r\nEs ist allerdings davon auszugehen, dass Leutnant Alverolds Mission einige Zeit dauern wird. Das neue Land macht einen ebenso weiten wie gefährlichen Eindruck. Sollte Benedict oder mir etwas zustoßen, werden Alverolds Truppen die Burg zurückerobern.\r\nWir werden Welle auf Welle schicken, bis die Festung unser ist!\r\n- Admiral Prachtmeer",},
			["Aedelas Schwarzmoor"] = { content = "Aedelas Schwarzmoor war der oberste Aufseher der Internierungslager in [[Azeroth]] und wachte in seiner Gefängnisfestung [[Burg Durnholde]] über die gefangenen [[Orcs]]. \r\nAedelas war wegen seiner beinahe unglaublichen Fähigkeit, auf dem Schlachtfeld eine Schneise durch die Ränge der Orcs zu schneiden, rasch in den Rängen aufgestiegen. Seine Vorgesetzten dachten, das komme durch Können und Mut. Schwarzmoor hätte ihnen erzählen können, dass sein Mut von der Flüssigkeitsvielfalt kam, aber er sah nicht viel Sinn darin. Sein Ruf schadete ebenso nicht seinen Chancen bei den Damen. Und auch sein schneidiges gutes Aussehen tat das nicht. Groß und stattlich, mit schwarzem Haar dass über seine Schultern fiel, mit stahlblauen Augen und einem kleinen, sauber gestutzten Spitzbart war er der perfekte heroische Soldat. Wenn einige der Frauen sein Bett ein wenig trauriger aber weiser verließen und öfters auch mit einem blauen Fleck oder zweien, machte ihm das nichts. Wo sie herkamen, gab es immer im Überfluss mehr von. Seit Jahren hatte Schwarzmoor zweimal so hart gearbeitet, um nur halb so belohnt zu werden wie andere Menschen von gleicher Geburt und Rang. Er hatte sich unter dem Schandmal des Verrats seines Vaters bemüht und alles möglich getan, um an Macht und Position zu gewinnen und noch immer wurde er von Vielen nur mit Skepsis belohnt. “Blut eines Verräter” wurde oft gemurmelt wenn sie dachten, er würde nicht zuhören.\r\nEinem bestimmten [[Orcs|Orc]] galt sein besonderes Interesse: dem Waisenkind, das er fast achtzehn Jahre zuvor gefunden hatte. Schwarzmoor hatte den jungen [[Orcs|Orc]] als seinen Lieblingssklaven aufgezogen und ihm den Namen [[Thrall]] gegeben. Er brachte dem [[Orcs|Orc]] alles über Taktik, Philosophie und Kampf bei. [[Thrall]] wurde sogar zum Gladiator ausgebildet. Die ganze Zeit über versuchte der verderbte Aufseher aus dem [[Orcs|Orc]] eine lebende Waffe zu machen. Dem Alkohol nicht abgeneigt zeigte er in diesem Zustand sein sadistisches Wesen. [[Thrall]] erlöste seinen früheren Mentor und Lehrer letztendlich bei der Belagerung der [[Burg Durnholde]]. \r\nAedelas Grab findet man versteckt hinter den Ruinen der [[Burg Durnholde]]. Sein Pferd war Nachtlied, ein schlanker Wallach, so schwarz wie seine Name.",},
			["Aegwynn"] = { content = "Etwa tausend Jahre vor der Öffnung des dunklen Portals wurde Aegwynn als erste Frau ein [[Wächter von Tirisfal]]. Die ehrgeizige junge Dame schafft es, sich mit Schlagkraft und Verstand gegen ihre männlichen Mitbewerber durchzusetzen und wurde eine herausragende Dämonenjägerin. Ihr wohl außergewöhnlichster Kampf war der gegen den Hauptmann der [[Brennende Legion|Brennenden Legion]], den verdorbenen Titanen [[Sargeras]]. Im äußersten Norden [[Azeroth]]s, in [[Nordend]], jagte sie Dämonen, die es dort auf einen der letzten Großdrachenschwärme abgesehen hatten. Zusammen mit den [[Drachen]] vernichtete sie die Dämonen vollständig – bis durch einen riesenhaften Dimensionsriss [[Sargeras]] erschien. Selbstsicher griff Aegwynn den monströs großen Dämonen an, der nach einem viel zu kurzem Kampf umfiel. [[Sargeras]] nutzte nämlich die Gunst der Millisekunde, um in dem Augenblick, als seine körperliche Erscheinung in sich zusammen fiel, seine Seele in den Körper Aegwynns zu transportieren. \r\nIm Körper Aegwynns verborgen lauerte [[Sargeras]] rastloser Geist unentdeckt im dunkelsten Teil ihrer Seele und wartete auf eine Chance zur Rache. Diese bot sich erst gut 700 Jahre später, als Aeqwynn einen Sohn gebar, der nach ihrem Wunsch ihr Nachfolger als [[Wächter von Tirisfal]] werden sollte. Sein Name war [[Medivh]]. Aegwynn vollbrachte in den folgenden Jahren noch große Taten und schaffte es sogar, ihren Sohn nach dessen Tod wieder zu beleben, auf dass er die Führer der großen Nationen vor der [[Brennende Legion|Brennenden Legion]] warnte. Heute gilt die Heldin als verschollen, einige meinen aber, sie in [[Tabetha]] in den [[Düstermarschen]] wieder erkannt zu haben. \r\n'''Siehe auch:'''\r\n* [[Aegwynn und die Drachenjagd]]\r\n'''Quelle:'''",},
			["Aegwynn und die Drachenjagd"] = { content = "'''Quelle:''' \r\n==Inhalt==\r\nWährend politische Beziehungen und Rivalitäten unter den sieben Menschennationen wuchsen und schwanden, ließ die Reihe der Wächter in ihren Anstrengungen zum Schutz gegen das Chaos niemals nach. Im Lauf der Jahre gab es viele dieser Wächter, doch nur einer erhielt jeweils die Macht von Tirisfal. Eine der letzten Wächterinnen jener Zeit tat sich als besonders mächtige Kriegerin gegen die Schatten hervor.\r\n[[Aegwynn]], ein ehrgeiziges Menschenmädchen, errang die Approbation des Ordens und erhielt den Mantel der Wächterschaft. Aegwynn hetzte Dämonen, wo immer sie ihnen begegnete, und löschte sie aus, stellte aber oft die Autorität des von Männern dominierten Rates von Tirisfal in Frage.\r\nSie glaubte, dass die alten Elfen und älteren Menschen, die den Rat bildeten, zu sehr in ihren Denkweisen erstarrt und nicht weitsichtig genug wären, den Konflikt mit dem Chaos endgültig zu beenden. Sie war der endlosen Diskussionen und Debatten überdrüssig und wollte ihren Herren und Mitstreiter mit jeder Faser ihres Körpers von ihrer eigenen Tüchtigkeit überzeugen, daher schätzte sie in entscheidenden Situationen Tapferkeit manchmal höher ein als Weisheit.\r\nJe besser sie die kosmische Macht von Tirisfal meisterte, desto deutlicher wurde sich Aegwynn einer Anzahl mächtiger Dämonen bewusst, die den eisigen Kontinent Nordrend heimsuchten. Aegwynn zog in den fernen Norden und verfolgte die Dämonen bis in die Berge. Dort fand sie heraus, dass die Dämonen einen der letzten noch existierenden Drachenschwärme jagten und den alten Kreaturen die ihnen innewohnende Magie aussaugten.\r\nDie mächtigen Großdrachen, die vor den expansionistischen Gesellschaften der Sterblichen geflohen waren, übertrafen die dunkle Magie der Legion nicht an Stärke. Aegwynn griff die Dämonen an und machte ihnen mit Hilfe der edlen Großdrachen den Garaus. Doch als der letzte Dämon von der Welt verbannt wurde, brach im Norden ein gewaltiger Sturm aus.\r\nEine riesenhafte finstere Fratze erschien am Himmel über [[Nordend]]. [[Sargeras]], der Dämonenkönig und Lord der Brennenden Legion, erschien vor Aegwynn und loderte vor höllischer Energie. Er ließ die junge Wächterin wissen, dass die Zeit von Tirisfal zur Neige ginge und die ganze Welt sich bald der Macht der Legion beugen müsse.\r\nDie stolze Aegwynn fühlte sich dem drohenden Gott gewachsen und entfesselte ihre Macht gegen Sargeras' Avatar. Es fiel Aegwynn auffällig leicht, den Dämonenlord mit ihren Kräften anzugreifen und seine materielle Hülle zu töten. Da Aegwynn befürchtete, Sargeras' Geist könnte noch verweilen, schloss sie die zerschundene Hülle seines Körpers in einer der alten Hallen von Kalimdor ein, die nach der Zerstörung des Brunnens der Ewigkeit auf den Meeresgrund gesunken war.\r\nAegwynn sollte nie erfahren, dass sie genau nach Sargeras' Plänen gehandelt hatte. Unwissentlich hatte sie das Schicksal der Welt der Sterblichen besiegelt, denn als sein Leib starb, hatte Sargeras seinen Geist in Aegwynns geschwächten Körper transferiert. Sargeras hauste viele Jahre in den dunkelsten Winkeln ihrer Seele, ohne dass die junge Wächterin auch nur die geringste Ahnung davon hatte.",},
			["Aeonus"] = { content = "Der Endboss der [[Höhlen der Zeit: Der Schwarze Morast]] ist [[Aeonus]], ein Großdrache des [[Ewiger Drachenschwarm |Ewigen Drachenschwarms]]. Sein Stundenglas zu beschaffen ist Teil der täglich heroischen Aufhabe „Gesucht: Aeonus’ Stundenglas“ von [[Windhändler Zhareem]] im Unteren Viertel von [[Shattrath]]. Einige von Zhareems Kunden sind wirklich verrückt. Es gibt Dinge, denen man nachjagt und andere, über die man nicht einmal nachdenken sollte. Sein Kunde ist der Inbegriff von Größenwahn und verlangt nichts Geringeres als Aeonus’ Stundenglas, dessen Sand im Inneren tatsächlich aufwärts fließt. \r\n==Fähigkeiten==\r\nZu Aeonus' Fähigkeiten gehören:\r\n* '''Raserei''' - Raserei ist ein Stärkungszauber und verringert die Zeit zwischen den Nahkampf- und Distanzangriffen 8 Sek. lang um 50%.\r\n* '''Sandatem''' - Sandatem fügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden Arkanschaden zu, verlangsamt ihr Bewegungstempo und erhöht die Zeit zwischen ihren Angriffen. Hält 10 Sek. lang an.\r\n* '''Spalten''' - Spalten fügt einem Gegner und dessen nächsten Verbündeten 110% des normalen Nahkampfschadens zu. Wirkt auf bis zu 3 Ziele.\r\n* '''Zeit anhalten''' - Die Fähigkeit, die Zeit anzuhalten betäubt Gegner für 4 Sekunden.\r\n'''Quelle'''\r\nAeonus ist der Drache, der dass tor zur Vergangenheit beschützt und es um jeden preis beschützt",},
			["Aeranas"] = { content = "Der [[Luftelementar]] '''Aeranas''' regierte einst über die östlichen Winde, doch ein Magier der [[Arakkoa der Haal'eshi]], [[Avruu]], hat ihn in einer Kugel eingefangen.",},
			["Aerissteg"] = { content = "Der '''Aerissteg''' ist die Basis des [[Konsortium]]s in [[Nagrand]]. [[Nexusprinz Haramad]] hat den [[Astrale]]n hier verboten mit der Arbeit im [[Oshu'gun]] loszulegen, weil er einen bestimmten mächtigen [[Naaru]] nicht verärgern will. Das hält die ganze Operation auf. Und während sie darauf warten, dass sie endlich am [[Oshu'gun]] graben können, verlieren sie viel Gewinn. Die Anwesenheit von astralen Schurken in dieser Gegend mag Gezhe, der in allem eine Möglichkeit sieht, vielleicht erheitern, aber sie sind eine wirkliche Bedrohung für die Sicherheit ihrer Unternehmung.\r\n==Personen==\r\n* '''Gezhe''' – Gezhe ist der Anführer des [[Konsortium]]s in [[Nagrand]] und hat beschlossen, die Operation so nahe wie möglich am [[Oshu'gun]] zu postieren ... allerdings ohne dabei einen Gedanken an die Sicherheit der Gruppe zu verschwenden, weil er eine Erhöhung ihrer Produktivität um zehn Prozent vorausgesehen hat. Nebenbei spekuliert er auf den Verkauf von schweren Veldarit, doch während der Markt schon als zusammengebrochen galt, erfreut sich Gezhe nun am Gewinn aus siebzehn neuen Bestellungen aus dem Hara'samidsektor. \r\n* '''Shadrek''' - Shadrek vom [[Konsortium]] sucht einen ganzen Kopf voll Elfenbein, denn Elfenbein ist ein heißbegehrtes Material und er hat Kunden von weither, die Schlange stehen, um es zu kaufen. Die Stoßzähne der wilden Elekk in Nagrand haben genau die Qualität, die er braucht.\r\n* '''Zerid''' – Zerid ist hier der Sicherheitsoffizier und möchte, dass man die Ausgeburten der Leere in der Nähe des [[Oshu'gun]] tötet.",},
			["Aesir"] = { content = "#REDIRECT [[Aesir Titanen]]", redirect = "Aesir Titanen",},
			["Ag'tor Blutfaust"] = { content = "Der [[Orc]] '''Ag'tor Blutfaust''' befindet sich in [[Valormok]] in [[Azshara]] und kann mehr über die Blutelfe [[Magus Rimtori]] berichten. Doch bevor man ihr Lager sucht, soll man in seinem Auftrag ihre [[Blutelfen]]einteiber und [[Blutelfen]]feldmesser töten. Sobald man [[Magus Rimtori]]s Lager gefunden hat, wäre es gut, nach etwas zu suchen, das für sie von Bedeutung ist und das man ihr nehmen kann, um sie in einen Kampf zu locken. Vielleicht gibt es ja etwas, womit er sie provozieren könnte. Nachdem man den arkanen Fokussierkristall, der an [[Magus Rimtori]] gebunden ist, zerstört und sie danach getötet hat, soll man ihren Kopf zu Ag'tor nach [[Valormok]] bringen. Auch [[Belgrom Felshammer]] in [[Orgrimmar]] wird ihren Kopf höchstpersönlich sehen wollen, damit Ag'tor Blutfaust und seine Verteidiger danach in Kürze nach [[Orgrimmar]] zurückkehren können.",},
			["Agamands Mühlen"] = { content = "\r\n'''Agamands Mühlen''' sind eine Bedrohung für alle [[Verlassene]]n, denn die Gegend hat sich zu einem Außenposten der [[Geißel]] entwickelt. Um zu den Mühlen zu gelangen, folgt man der Straße von [[Brill]] aus westwärts. Nachdem man die Brücke überquert hat, nimmt man die erste Abzweigung nach Norden und folgt diesem Weg. Wenn man die Windmühlen sieht, beginnt die Schlacht. Die [[Geißel]] versucht derzeit, bei Agamands Mühlen einen Stützpunkt zu errichten und wenn ihnen das gelingt, können sie weitere Angriffe innerhalb von [[Tirisfal]] unternehmen. Deshalb wurden klare Befehle an die Todeswachen der [[Verlassene]]n erteilt: Die Diener der [[Geißel]] in den Mühlen müssen vernichtet werden. Am stärksten sind sie in der Gruft der Familie Agamand, wo ein örtlicher militärischer Anführer, ein Skelett namens [[Hauptmann Dargol]], sein Hauptquartier hat. \r\nZu Lebzeiten war die Familie Agamand Arbeitgeber von [[Coleman Heller]] in [[Brill]] und sie war die Ursache für seinen Tod. Er findet es nur recht und billig, dass die Agamands jetzt hirnlose Diener des [[Lichkönig]]s sind. In ihrer Familiengruft liegen noch ihre Familienerbstücke: ein Schwert, eine Axt, einen Dolch und einen Streitkolben. Die Gruft der Familie Agamand liegt am nördlichen Ende von Agamands Mühlen, doch der Ort wird durch lauernde Angehörige der Geißel und tote Agamands bewacht. \r\n==Hintergrund==\r\nDie Familie Agamand war die wohlhabendste in [[Tirisfal]]. Als die [[Geißel]] das erste Mal auftauchte, befestigten die Agamands ihre Heimstatt und überredeten ihre Angestellten zu bleiben und bei der Verteidigung zu helfen. Diese waren Narren, aber sie waren loyale Narren. Die Agamands haben sie in ihrem Stolz zum Untod verdammt, und heute sind sie Diener der [[Geißel]]. Als die Geißel in Tirisfal einmarkschierte, verzweifelte [[Devlin Agamand]] und suchte nach einem Ausweg aus ihrer schlimmen Lage. In dieser seiner Verzeiflung ging er einen Pakt mit der Geißel ein. Niemand weiß, was ihm als Belohnung für seinen Verrat versprochen worden war, aber sein Bruder [[Thurman Agamand]] ist sich ohnehin sicher, dass nicht ein Wort davon wahr war. Devlin wurde zu einem Scheusal und führte eine kleine Gruppe der Geißel durch die Bresche an den Ort, wo viele andere der Agamands ihr Nachtlager aufgeschlagen hatten. \r\nDer Hinterhalt war brutal. Ein Drittel der Familie fiel, ehe sie die Geißel besiegt hatten. Danach hatten sie kaum genug Männer zur Bewachung ihrer Grenzen. Es war nur eine Frage der Zeit, bis ihre erschöpfte Wache fiel und die Geißel angriff. Und obwohl Thurman in dieser verfluchten Nacht das Gesicht von Devlin unter den Fratzen der Geißel sah, war er ihm doch entkommen. Vielleicht war Devlin bereits untot, vielleicht noch immer ein Spion der Geißel. In jedem Fall war er ein Ungeheuer geworden. \r\nDevlin hatte seine Familie gewarnt, dass sie dem Untergang geweiht sein würden, wenn sie sich der Geißel entgegenzustellen wagten. Er sagte ihnen das bei ihrem ersten Einfall in Tirisfal, lange bevor die Agamands eingekesselt wurden. Vielleicht wollte er, dass sie flohen. Vielleicht wollte er aber auch nur angeben. Aber er hatte Recht. Sie waren dem Untergang geweiht. Die Familie Agamand gab es schon bald darauf nicht mehr. \r\n==Mitglieder==\r\n* '''Devlin Agamand''' - Devlin Agamand war der jüngere von zwei Söhnen der Familie Agamand und im Leben hätten sie unterschiedlicher nicht sein können. Devlin war schwach und scharfzüngig. Er war immer schon schwer zu durchschauen und gab seiner Familie schon als Kind Rätsel auf. Devlin war es der durch seinen Verrat den Untergang der Familie besiegelte. Als Agamands Mühlen der Seuche anheim fiel, war man nicht überrascht zu hören, dass Devlin ihr schnell erlag. Er wurde zu einem Scheusal und begann die Wachposten der Familie zu töten. Sein verrücktes Gebrabbel kann man heute noch nahe der Straße hören, die zu Agamands Mühlen führt.\r\n* '''Gregor Agamand''' - Gregor Agamand war der Vater von Thurman und Devlin Agamand.\r\n* '''Hauptmann Dargol''' - Hauptmann Dargol ist der örtliche militärische Anführer der Geißel. Er hat die Vorfahren der Agamands durch Nekromantie wiedererweckt und hat vor, sie gegen die Verlassenen einzusetzen.\r\n* '''Nissa Agamand''' - Nissa Agamand war die Frau von Gregor Agamand und die Mutter von Thurman und Devlin.\r\n* '''Thurman Agamand''' - Thurman Agamand war groß und sanft und der älteste Sohn von Gregor Agamand. Ein alter Brief aus seiner Feder ist an [[Yvette Heller]] adressiert, in dem er sie wissen lassen wollte, dass sein Bruder Devlin Agamand ein Verräter sei. Er vertraute diesen Brief seinem schnellsten Läufer an und betete, dass er einen Weg durch die sie umgebenden feindlichen Reihen findet. Und er betete, dass Yvette seine Worte zu lesen bekommt, denn es sollten die letzten an sie sein. Sein einziger Trost in jenen dunklen Tagen war es zu wissen, dass Yvette sein Schicksal erspart bleibt. Thurman fürchtete, dass sein Vater einen großen Fehler begangen hatte, als er beschloss zu bleiben und die Heimat der Agamands zu verteidigen. Die Geißel wütete durch Tirisfal, und obwohl die Agamands gut aufgestellt und versorgt waren, fehlte es der Familie nach dem Verrat seine Bruders [[Devlin Agamand]] doch an Kräften, um dem ständigen Ansturm standzuhalten. Er mahnte Yvette vor seinem Bruder Devlin zu fliehen, wenn sie auf ihn treffen sollte. Er schrieb auch, dass er keine Angst hatte und nicht bereute, bei seiner Familie geblieben zu sein. Aber seine letzten Gedanken gehörten Yvette. Er wünschte, dass sie weiterlebt, damit er Frieden finden könne .... aber der Brief kam nie bei ihr an.\r\n'''Quellen'''",},
			["Agentin Bijou"] = { content = "'''Agentin Bijou''' ist eine der unzuverlässigsten Agentinnen des Expeditionskorps von Kargath. Sie hat auch für den zwielichtigen Tierhändler namens Kibler beim [[Flammenkamm]] in der [[Brennende Steppe|Brennenden Steppe]] gearbeitet und das Expeditionskorps schlicht und ergreifend hintergangen. Außerdem hat sie Gelder der [[Horde]] veruntreut, um ihre Machenschaften zu finanzieren. Sie brauchte das Geld, so sagt sie, und Kibler bezahlt sie sehr, sehr gut - viel besser als es das [[KEK]] je könnte. Aber man sollte nicht an Ihrer Loyalität zweifeln. \r\nIhre Sachen hat sie auf der untersten Ebene der Stadt in der Unteren [[Schwarzfelsspitze]] versteckt. Nachts, wenn dieser Ort hier nur leicht bewacht ist, schleicht sie durch die Stadt, macht sich Notizen und schreibt alles auf, was für das [[KEK]] strategisch nützlich sein könnte. Letzte Nacht ist allerdings etwas fürchterlich schief gegangen. Sie ist über einen Stolperdraht getappt und hat einen Alarm ausgelöst. Also hat sie ihr Spionagezeug versteckt und ist auf Tauchstation gegangen. Bijous Aufklärungsbericht, der an Großmeister Lexlort in [[Kargath]] adressiert ist, wird Ihren Namen reinwaschen und dem [[KEK]] bestimmt einen strategischen Vorteil gegenüber diesen [[Orcs]] in der Unteren [[Schwarzfelsspitze]] verschaffen.",},
			["Aggonar"] = { content = "Die [[Teiche von Aggonar]] auf der [[Höllenfeuerhalbinsel]] waren ein Heiligtum der [[Draenei]], doch fielen sie der Verderbnis anheim, als das Blut des Dämonen Aggonar in die heiligen Wasser vergossen wurde. Obwohl es alt und verwässert ist, ist das Blut noch immer von einer enormen Macht erfüllt. Man kann die Knochen des Dämonen am nördlichen Ende der Teiche finden. Seine Essenz ist immer noch nicht ganz aus dieser Welt verschwunden.",},
			["Aggramar"] = { content = "'''Aggramar''' ist ein bronzehäutiger [[Vanir Titan]], der in eine goldene Toga gewickelt ist. Er diente als früherer Leutnant unter [[Sargeras]] und wurde später mit der Aufgabe als Champion des Pantheons betraut, indem er die Position von Sargeras nach dessem Weggang einnahm. Aggramar's Aufgabe ist der Kampf gegen die [[Brennende Legion]] und dämonische Makel. Aggramar’s Waffe ist Taeshalach, eine zerbrochene Hälfte der [[Hoheklinge des Pantheons]].",},
			["Ahn'Qiraj"] = { content = "Jenseits der [[Tore von Ahn'Qiraj]] liegen 2 gewaltige Dungeons – die [[Ruinen von Ahn'Qiraj]], ein Dungeon für 20-Mann Gruppen, und der [[Tempel von Ahn'Qiraj]], ein Schlachtzugsdungeon für 40 Spieler. In Ahn’Qiraj werden die Spieler die dunklen Geheimnisse der Vergangenheit aufdecken und die Hintergründe des jüngsten Vorstoßes der [[Silithiden]] erfahren... und den schattenhaften Meistern der [[Silithiden]] entgegentreten, den [[Qiraji]]. Um auf den jeweiligen Realms die [[Tore von Ahn'Qiraj]] zu öffnen müssen die Spieler ein gewaltiges World-Event abschließen.\r\n==Hintergrund==\r\nAhn'Qiraj ist [[C'Thun]]s Reich ... das Reich des eingesperrten [[Alte Götter|Alten Gottes]], der tief aus dem im Inneren der Erde seine [[Qiraji]]-Armeen gegen die Sterblichen hetzt. Das nördliche Gegenstück zu '''Ahn'Qiraj''' ist [[Azjol-Nerub]], das durch die [[Neruber]] bewohnt wurde. \r\n==Geschichte==\r\nAuf dem antiken Kontinent [[Kalimdor]] befand sich im Zentrum der [[Brunnen der Ewigkeit]]. Aus diesem magischen Äther wurden die [[Silithiden]] geboren und als der gefallene [[Alte Götter|Alte Gott]] [[C'Thun]] ihr Erscheinen erkannte, erschuf er aus den [[Silithiden]] Avatare nach seinem Bild. Diese Avatare wurden die Azi [[Aqir]] genannt, die sich später in die [[Qiraji]] und die [[Neruber]] aufspalteten. Die [[Qiraji]] arbeiteten fieberhaft daran, eine Streitmacht aufzubauen, die mit den [[Silithiden]] als ihren Günstlingen, fähig war die Welt, die ihren Gott verraten wollte, in Schutt und Asche zu legen. Die große Festungsstadt '''Ahn'Qiraj''' wurde im südlichen [[Silithus]] erschaffen, um ihre wachsenden Armeen zu beherbergen und sie auf die Ankunft von [[C'Thun]] vorzubereiten. Die [[Qiraji]] verbrachten tausende von Jahren damit, ein Armee aufzubauen, die fähig war, in ganz Kalimdor methodisch Rache zu üben. Nur die [[Nachtelfen]], die einst Silithus bewohnten, standen in ihrem Weg.\r\n===Der [[Krieg der Sandstürme]]===\r\nDer [[Krieg der Sandstürme]] wütete lange, quälende Monate und die [[Nachtelfen]] waren immer auf der Defensive, immer zahlenmäßig unterlegen, und wurden immer wieder zurückgetrieben. ... und bald wurde ganz [[Silithus]] von den [[Silithiden]] und ihren [[Qiraji]] Heerscharen überflutet ... Aus Verzweiflung suchte der [[Nachtelfen]]-Führer [[Fandral]] Hirschhaupt die Hilfe des unbestimmbaren [[Bronzener Drachenschwarm|Bronzen Drachenschwarms]]. Und ihre anfängliche Ablehnung wurde umgekehrt, als die [[Qiraji]] die [[Höhlen der Zeit]], die Heimat und Provinz von [[Nozdormu]], dem Zeitlosen, attackierten. [[Nozdormu]]s Erbe, [[Anachronos]], willigte ein den [[Bronzener Drachenschwarm|Bronzen Drachenschwarm]] gegen die plündernden [[Qiraji]] zu schicken. \r\n... Jeder fähige Nachtelf beteiligte sich daran und zusammen schmiedeten sie einen Feldzug, um [[Silithus]] wiederzuholen ... Aber sogar mit der Macht der [[Drachen]], erwies sich die reine Anzahl der [[Qiraji]] und [[Silithiden]] als überwältigend. So ersannen die [[Drachen]] und [[Fandral]] ihren letzten, verzweifelten Plan: die [[Qiraji]] in der Stadt einzuschließen, eine Mauer zu errichten, die sie einsperren würde, bis eine hoffnungsvollere Kriegslist ausgedacht werden konnte. \r\n... und so trugen die [[Nachtelfen]] und die vier [[Drachen]]schwärme in den letzten Stunden des [[Krieg der Sandstürme|Krieges der Sandstürme]] gegen die [[Silithiden]] die Schlacht in das Herz des [[Qiraji]]-Imperiums zurück: in die Festung von '''Ahn'Qiraj''' und schlossen die [[Silithiden]] und ihre [[Qiraji]]-Herren innerhalb einer magischen und undurchdringbaren Barriere ein. ... Der Krieg hinterließ die verfluchte Stadt in Ruinen ...\r\n===Heute===\r\nTausend Jahre sind nun vergangen und tief im Süden des Wüstenlandes [[Silithus]] hat sich ein Tor geöffnet, das die Welt seit dem Ende des [[Krieg der Sandstürme|Krieges der Sandstürme]] vor dem Übel der [[Qiraji]] bewahrte. ... Und der erbitterte Kampf gegen [[Silithiden]] und allerlei anderes Gezücht beginnt aufs Neue.",},
			["Ahnengrund"] = { content = "Der '''Ahnengrund''' ist eine zeremonielle Begräbnisstätte der Orcs der [[Mag'har]] im Südwesten von [[Nagrand]]. Der Ahnengrund ist normalerweise sehr ruhig und friedlich. Doch in letzter Zeit haben sich die Geister der Ahnen erhoben und sind sehr aufgebracht. Etwas muss sie sehr stören. Die Geister sind nicht wirklich die Ahnen, sondern ein Abbild ihrer gegenwärtigen Lage. Die einzige Möglichkeit besteht darin, die Geister von Nagrand zu vernichten, bevor sie sich in Wesen der Leere verwandeln. Deswegen müssen die aufgebrachten Orcgeister zur Sicherheit zerstört werden. \r\n[[Mutter Kashur]] befindet sich ein gutes Stück im Südwesten beim Ahnengrund. Sie kümmert sich um die aufgebrachten Geister dort und möchte, dass man den [[Sonnenwindposten]], die [[Ruinen des Lachenden Schädels]], [[Garadar]] und die [[Ruinen des Blutenden Auges]] besucht. Denn sie braucht jemanden, der schaut, ob die Vorfahren noch da sind. Nachdem die Geister zu ihr gesprochen haben, möchte Mutter Kashur ihrer Vision auf den Grund zu gehen und [[K'ure]] in [[Oshu'gun]] finden. Wenn sie Erfolg hatte, die aufgebrachten Geister im Ahnengrund zu beruhigen, sollte man [[Großmutter Geyah]] in [[Garadar]] von Mutter Kashurs Sieg berichten. Das wird den Mag'har sicher neuen Mut geben. Vielleicht erwacht dann sogar der junge Höllschrei aus seiner Melancholie.",},
			["Akademie von Falthrien"] = { content = "Diese [[Insel der Sonnenwanderer]] ist von einem Makel behaftet, der mächtiger als die Überbleibsel der ist. Man glaubt, dass auf der [[Insel der Sonnenwanderer]] eine wirklich dämonische Präsenz vorherrscht. Westlich liegen die Türme der Akademie von Falthrien. Die Arkangespenster, die dort hausen, sind der Schlüssel zu der dämonischen Machtquelle. [[Felendren der Verbannte]] haust hier. \r\nAkademie von Falthrien\r\nDiese Insel ist von einem Makel behaftet, der mächtiger als die Überbleibsel der Geißel ist. Man glaubt, dass auf der Insel eine wirklich dämonische Präsenz vorherrscht. Westlich liegen die Türme der Akademie von Falthrien. Die Arkangespenster, die dort hausen, sind der Schlüssel zu der dämonischen Machtquelle.\r\n* Felendren der Verbannte – Getriebener. Felendren der Verräter haust oben in der Akademie von Falthrien. Er wurde aus dem Reich der Blutelfen verbannt, da er die Warnungen der Lehrer und Ältesten missachtet hat. Er ist der Schlimmste ihrer Art, da er nur nach der Befriedigung seines unstillbaren Magieverlangens strebt. Er hat sich der Kontrolle verweigert und ist nur noch ein Schatten seines einstigen Selbsts - einer der Getriebenen - und er stellt eine Bedrohung für den Sonnenturm dar.",},
			["Akama"] = { content = "==Allgemeines==\r\nAkama befindet derzeit sich in der verborgenen Kammer im Kerker des Wächters und ist der Anführer der [[Todeshörige]]n. Nicht viele Leute verstehen Akamas Entscheidungen. Nur seine engsten Mitarbeiter wissen von den bösen Omen, die er sieht, und den Zeichen, auf die er wartet. Als er sich mit [[Illidan]] zusammenschloss, geschah dies, weil er vorausgesehen hatte, dass sein Volk sonst vernichtet würde. Er hat geduldig auf die anderen Zeichen und Visionen gewartet... Velens Auszug... die Öffnung des dunklen Portals... und nun... die Ankunft von Abenteurern. Er ist nicht mehr so stark wie einst. All die Jahre, die er so nahe am Bösen verbracht hat... Er weiß nicht, ob er sich selbst mit einem so mächtigen Artefakt wie dem [[Medaillon von Karabor]] trauen würde. Deshalb lässt er es zu dem Wesen bringen, dem sie seine Macht anvertrauen können: A'dal in [[Shattrath]].\r\n==Geschichte==\r\nAkama gehörte sicherlich nicht zu den größten Persönlichkeiten von Draenor. Doch als der Tempel von Karabor auf grausame Weise von Orks überrannt wurde, schlug die Stunde des Helden. Nach dem gescheiterten Versuch, das Heiligtum vor dem Untergang zu bewahren, versammelte Akama den zerstreuten Rest seines Volkes und rettete es schließlich an den Rand der Zangarmarschen. Während indes [[Magtheridon]] den Tempel in Besitz nam, gründete Akama die Gemeinschaft der [[Aschenzungen]] und wurde deren Anführer. Nach dem archaischen Gesetz \"Der Feind meines Feindes ist mein Freund\" schloss sich Akama jedoch auch - wie viele andere - dem mächtigen [[Illidan]] an und half ihm, seinerseits die Herrschaft über die einst heilige Stätte zu übernehmen. Nun wartet Akama umgeben von Bestien und [[Dämonen]] im Kerker des Wächters, nahe des Schwarzen Tempels, auf eine Gruppe von Helden, die sich seinem einstigen Verbündeten [[Illidan]] entgegenzustellen vermögen.",},
			["Akil'zon"] = { content = "Akil'zon ist ein Boss in [[Zul'Aman]] und verkörpert den Avatar des Adlers. Als solcher beherrscht er im Kampf nicht nur das Element der Luft und ist fähig, mächtige Kettenblitze zu schleudern oder einen Sturm zu beschwören, der einen zufälligen Gegner hoch in die Luft wirbelt, sondern er kann auch Adler als Unterstützung im Gefecht herbeirufen.",},
			["Aku'mai"] = { content = "Legenden erzählen, dass die uralte [[Hydra]] Aku'mai, ihren Sitz in die [[Tiefschwarze Grotte]] verlegt hat, die einst ein ruhmvoller Tempel der [[Nachtelfen]] zu Ehren der Mondgöttin [[Elune]] war. Aku'mai ist ein bevorzugtes Tier der [[Alte Götter|Alten Götter]] und jagte schon immer in diesem Gebiet. Angezogen von Aku'mais Präsenz kam ebenso der [[Schattenhammer Kult]] an diesen Ort, um zu sich in der bösen Präsenz der [[Alte Götter|Alten Götter]] sonnen. Eines Tages hoffen sie genug Macht haben, um Aku'mai zurückzuholen. Dann wird die Welt wieder zur Ära ihrer einstigen Größe zurückkehren. Eine Ära, in der die [[Alte Götter|Alten Götter]] herrschen...",},
			["Al'Akir"] = { content = "==Allgemeines==\r\nAl'Akir der Windfürst ist einer der vier Elementaren Leutnants der [[Alte Götter|Alten Götter]]. [[Prinz Donneraan]], der Prinz der Luft, ist eines von Al'Akirs Kindern.\r\n==Aussehen==\r\nDer Windlord gleicht einen riesigen Wirbelsturm mit einen Gesicht und zwei Armen. Er ist von gigantischen Ausmaß genau, wie die anderen Elementarlords. \r\n==Geschichte==\r\nNachdem die [[Titanen]] versucht hatten, die Welt zum blühen zu bringen, reagierten die alten Götter, indem sie ihre Elementararmeen, geführt von den vier Lords, auf die Titanen hetzten. Ihre Chaotischen Kräfte wüteten über das Gesicht der Welt und obwohl die Elementare jenseits eines sterblichen Verstandes mächtig waren, konnten ihre vereinten Kräfte die mächtigen Titanen nicht stoppen. Einer nach dem anderen der Elementarfürsten fiel und ihre Kräfte verstreuten sich. Das Pantheon zerschmetterte die Zitadellen der [[Alte Götter|Alten Götter]] und kettete die fünf bösen Götter weit unter der Oberfläche der Welt an. Ohne die Kraft der [[Alte Götter|Alten Götter]], ihre tobende Geister an die physikalische Welt gebunden zu halten, wurden die Elementare auf eine abyssische Ebene verbannt, wo sie für all Ewigkeit miteinander streiten würden. Mit dem Weggang der Elementare beruhigte sich die Natur und in eine friedliche Harmonie kam die Welt.",},
			["Al'Amethsee"] = { content = "Die [[Bäumlinge]] von [[Teldrassil]] sind [[Naturelementare]]. In ihnen spiegelt sich in gewisser Weise die natürliche Ordnung von Flora und Fauna ihres großen Baums wider. Auch kleine [[Bäumlinge]] sprießen rund um das Wasser des Al'Amethsees und es ist höchst beunruhigend zu sehen, dass die [[Bäumlinge]] so wütend geworden sind. Der Druide [[Denalan]] glaubt, es etwas mit dem Erdboden zu tun hat.\r\n==Personen==\r\n* '''Denalan''' - Der [[Nachtelfen]] [[Druide]] Denalan hat am Ostende des Sees ein Lager aufgeschlagen, in dem er die Pflanzenwelt [[Teldrassil]]s studiert und Experimente betreibt. Er hat in Darnassus ein Gebinde rarer Erde bestellt, und die Lieferung kam erst kürzlich mit Verspätung in [[Dolanaar]] an. Er hat sich viel mit verschiedenen Düngemethoden für Pflanzen beschäftigt und würde sie gern an Bäumlingssamenkörnern ausprobieren. Doch er fürchtet, dass man diesen Schösslingen nicht mehr helfen kann - sie sollten versuchen, sie auszureißen, bevor sie groß genug sind, um Probleme zu bereiten. Er möchte auch das moosumschlungene Herz von [[Schwarzmoos der Stinker|Schwarzmoos dem Stinker]] haben. Das besudelte Herz pflanzt man in Denalans Blumentopf ein. Dieser ist mit einer nährstoffreichen Krume gefüllt, die das Herz säubern und heilen kann.\r\n* '''Grimmeiche''' - Der [[Bäumling]] [[Grimmeiche]] wohnt in einer Höhle am Südufer des Sees und überträgt die Verderbnis auf alle Wesen, die am Al'Amethsee leben. [[Grimmeiche]] wird von dem größten Tumor vergiftet, den man je gesehen hat.",},
			["Al'ar"] = { content = "Al'ar, der [[Phönix]], ist ein Halbgott, welcher mit den [[Blutelfen]] verbündet ist. Zu finden ist er in der [[Festung der Stürme]].",},
			["Alarm Bot"] = { content = "Ein [[Alarm Bot]] ist eine gnomische Erfindung, die zu den mechanischen [[Konstrukt]]en zählt. Der Alarm Bot sollte nicht mit einem [[Alarm-O-Bot]] verwechselt werden, der zwar einen ähnlichen Namen hat, aber eine andere Bauart aufweist. \r\n==Aufbau==\r\nEin Alarm Bot ist an der Vorderseite mit einem Scheinwerfer ausgestattet und besitzt an den Seiten jeweils ein drei-gliedriges Greifgelenk. In den Stellgliedern der Handgelenke befinden sich die sog. ''Servos''. Aus seinen Schultern ragen 4 Auspuffrohre nach hinten weg (je 2 große und darunter 2 kleinere). Seine Schultern, Füße und Bauchpartie sind jeweils mit einem Schutzschild gepanzert. Weitere wichtige Bestandteile dieser Bots sind u.a. auch die verbrennungspneumatischen Beulensauger und der Hirnkondensator, der für die künstlich Inteligent der Bots sorgt. \r\n==Arten==\r\n* [[Arkaner Nullifizierer X-21]]\r\n==Persönlichkeiten==\r\n* [[Maxx E. Million Nr. V]]\r\n* [[Techbot]]",},
			["Albrecks Befund"] = { content = "'''Albrecks Befund''' erhält man von [[Apotheker Albreck]] im [[Rückenbrecherposten]] auf der [[Höllenfeuerhalbinsel]]. Albreck studierte die [[Orcs des Blutenden Auges]] und ihr Blut. Sein Befund über das Blut des Blutenden Auges schickte er im Anschluss an seine Untersuchungen an [[Apotheker Antonivich]] in [[Thrallmar]]. \r\n==Inhalt==\r\nWeiser Antonivich:\r\nIch hoffe dieser Brief erreicht Euch in [[Thrallmar]]. Meine Ausstattung hier beim [[Rückenbrecherposten]] ist zwar angemessen für meine Experimente, doch manchmal sehne ich mich dennoch nach [[Unterstadt]], nach meinen Gerätschaften und meiner Dienerschaft... Spaß beiseite, ich habe einige Neuigkeiten. Das Blut, das man von den [[Höllenorc]]s eingesammelt hat, weist eine Konzentration von dämonischer Energie auf, die fast identisch mit der der ursprünglichen Höllenorcs von [[Azeroth]] ist... der Macht von [[Mannoroth]].\r\nEs ist unmöglich, dass Mannoroths Einfluss sich bis in die [[Scherbenwelt]] erstreckt haben kann, er ist seit Jahren tot. Ich vermute, dass ein anderer [[Grubenlord]] hinter der ganzen Sache steckt, einer mit der Macht Mannoroths... fähig, die heimischen Orcs zu verderben.\r\nIch werde meine Untersuchungen mit dem Blut fortsetzen, rate Euch jedoch, der Spur nachzugehen. Ich fürchte, sie wird Euch tief ins Innere der [[Höllenfeuerzitadelle]] führen.\r\nGrüße,\r\nApotheker Albreck",},
			["Alchemie"] = { content = "== Allgemeines==\r\nAlchimisten mischen Kräuter und schaffen so Tränke mit einer ganzen Reihe von Wirkungen. Ein Alchimist kann Heil-, Unsichtbarkeits-, Elementarwiderstands-, oder Manatränke herstellen, spezielle Öle zum Benetzen von Waffen, und vieles mehr.\r\nAlchimie ist für alle [[:Kategorie:Klasse|Charakterklassen]] nützlich. Nahkämpfer können mit Alchimie Verstärkungs- und Heiltränke herstellen, Spruchzauberer Manatränke und verwandte Verstärkerzauber. Alchimie ist ein sehr spaßiges Handwerk mit dem man Tränke für sich selbst, für seine Freunde und Gruppenmitglieder oder auch bloß zum Verkauf herstellen kann. Alchimisten, die Tränke einfach verteilen, sind jedermanns bester Freund. \r\n'''Quelle:''' wow-europe.com\r\n==Spezialisierungen==\r\nMan kann nur eine Spezialisierung in der Alchimie erlernen. Wenn man sich spezialisieren möchte, muss man sich an jemanden wenden, der sich auf ein engeres Studiengebiet konzentriert.\r\n===Meister der Elixiere===\r\n* '''Ausbilder''': Lorokeem im Unteren Viertel in [[Shattrath]]\r\nWenn man sich auf die Herstellung von Elixieren spezialisieren möchte, empfiehlt es sich, den Arakkoa namens Lorokeem um Hilfe zu bitten. Sein Wissen über Elixiere sucht seinesgleichen, und doch verschwendet er sein Können darauf, ein Elixier des ewigen Lebens zu brauen. \r\n===Meister der Tränke===\r\n* '''Ausbilder''': Lauranna Thar’well in der Zuflucht des Cenarius in den [[Zangarmarschen]]\r\nDie Pflanzen verfügen über Eigenschaften, mit deren Hilfe Alchimisten über Tränke andere stärken und verjüngen können. Laurannas Wissen über die Pflanzen in der Scherbenwelt ermöglicht ihr, Alchimisten beizubringen, wie sie das Beste aus ihnen herausholen können. \r\n===Meister der Transmutation===\r\n* Ausbilder: Zarevhi in der Sturmsäule im [[Nethersturm]]\r\nJeder Alchimist kann erklären, dass Materie formbar ist und jede Substanz in eine andere verwandelt werden kann. Jedoch wird dabei nichts wirklich erschaffen oder zerstört. Ein wahrer Meister der Transmutation kann lernen, diese Grenzen zu überwinden. Als angehender Transmutierer ist man mit der Urmacht vertraut, der Verbindung der Materialien aller Urkräfte. Wenn man sich in der Kunst der Transmutation spezialisieren möchte, empfiehlt es sich, den Astralen namens Zarehvi um Hilfe zu bitten. Er wird Interessierten beibringen, wie man mit Hilfe der alchimistischen Transmutation Materie aus dem Nichts erschaffen kann.\r\n==Besondere Alchemistische Zutaten==\r\n* [[Disteltau]]\r\n* [[Dunst der Atal'ai]]\r\n* [[Faulendes Herz]]\r\n* [[Heimtückisches Nachtweberspinnengift]]\r\n* [[Lauerergift]]\r\n* [[Schattenhund]]blut\r\n* '''Traumstaub''' - Von den Großdrachenwelpen und Wyrmkin aus den [[Sümpfe des Elends|Sümpfen des Elends]]\r\n* '''Trolljuju''' - Es handelt sich dabei um leuchtende Objekte, denen eine unbekannte Macht innewohnt. Wahrscheinlich ist es das, was die untoten [[Trolle]] am Leben erhält.\r\n* '''Verfärbtes Worgherz''' - Die Apotheker können Heiltränke aus verfärbten Worgherzen herstellen.\r\n==Besondere Alchemistische Erzeugnisse==\r\n* [[Elixier der Pein]]\r\n* [[Elixier der Schmerzen]]\r\n* [[Elixier des Leidens]]\r\n* [[Frostöl]]\r\n* Lungensaftcocktail - Dieses Gebräu hat suchterzeugende Eigenschaften, denen, noch nicht einmal jemand mit äußerst starkem Willen widerstehen kann. \r\n* [[Noggenfoggers Elixier]]\r\n* '''R.O.I.D.S''' - Das ist eine Aufputsch-Droge. Zwar zeigt sich unmittelbar nach der Einnahme des Präparates ein gigantischer Stärkeschub, doch auf lange Sicht gesehen könnte das Mittel nachteilige Auswirkungen auf den Geist und die Intelligenz haben.\r\n* '''Videre-Elixier''' - Durch dieses Elixier kann man mit jemandem sprechen, den man normalerweise nicht einmal sehen würde.",},
			["Alchimie"] = { content = "#REDIRECT [[Alchemie]]", redirect = "Alchemie",},
			["Alchimist Arbington"] = { content = "Alchimist Arbington auf der [[Zugwindspitze]] in den [[Westliche Pestländer|Westlichen Pestländern]] weiß viel über die [[Scholomance]] und hat eine Idee, wie der [[Skelettschlüssel]] dafür zu erlangen ist. Sie benötigen Skelettfragmente für das Schmieden des Schlüssels, wobei die [[Skelette]] innerhalb von [[Andorhal]] den gewünschten Effekt bringen sollten. Die magieerfüllten Skelettfragmente sollte man dann zu [[Krinkle Goldstahl]] in [[Gadgetzan]] bringen, denn er dürfte der Einzige sein, der die Form herstellen kann, die sie benötigen, und seine Dienste werden nicht billig sein. Um den Schlüssel fertig zu stellen, benötigen sie den Skarabäus des [[Lich]]s aus [[Andorhal]], [[Araj der Beschwörer]] genannt. Es wird den Kopf des Schlüssels bilden.",},
			["Aldor"] = { content = "Die Aldor sind die Hüter des Lichts und die Diener der [[Naaru]]. Ihnen direkt gegenüber stehen die Agenten der [[Brennende Legion|Brennenden Legion]] - [[Dämonen]], die die Welten zerstören und die Unschuldigen verderben wollen. Als uralter Orden von [[Draenei]]-Priestern, einst geführt von [[Velen]], werden die Aldor nun von [[Hohepriesterin Ishanah]] geleitet. Sie dienen den [[Naaru]] in [[Shattrath]], auch bekannt als die [[Sha'tar]] und sind Rivalen der [[Seher]]. \r\n==Die [[Sha'tar]], die [[Seher]] und die Aldor.==\r\nEs gibt drei Völker, die ihr zu Hause in [[Shattrath]] gefunden haben. Obwohl alle drei Rassen für den gleichen Zweck kämpfen, sind die [[Seher]] und die Aldor Gegenparteien, die sich nicht leiden können. Wer sich bei einem der beiden Fraktionen beliebt macht, verliert automatisch sein Ansehen bei der anderen Fraktion. [[Khadgar]], der sich in der Mitte von [[Shattrath]] befindet, wird euch die Wahl zwischen einem der beiden Fraktionen entscheiden lassen. Beide Fraktionen haben eine Bank. Um diese nutzen zu können, ist es also ratsam, sich so früh wie möglich zu entscheiden. \r\n'''Quelle''': wow-europe.com",},
			["Aldorius"] = { content = "#REDIRECT [[Aldorius van Croyden]]", redirect = "Aldorius van Croyden",},
			["Aldorius van Croyden"] = { content = "= Lebenslauf =\r\nAldorius wuchs als erster Sohn eines Adligen aus [[Lordaeron]]s, Count Edward Croyden, in Croyden Manor, einer inzwischen zerstörten Villa in der Nähe von [[Andorhal]] auf. Er besuchte schon als Jugendlicher die Universität in [[Dalaran]] und stieg rasch in der Hierarchie der [[Kirin Tor]] auf. Schließlich war er der stellvertretende Leiter von [[Dalaran]]s Verstärkung für das zu dieser Zeit durch die [[Geißel]] angegriffene [[Quel'Thalas]]. Er musste den Fall dieses Landes mit ansehen und brach daraufhin mit der arkanen Magie, welche er als zu schwach ansah. \r\nEr widmete sich dunklen Studien der Dämonologie und Nekromantie, wofür man ihn aus [[Dalaran]] verbannte und ihm die Fähigkeit nahm, jemals wieder arkane Magie zu wirken. Er ging in die gerade gegründete [[Scholomance]] und studierte dort die dunklen Künste.\r\nSpäter dann verlies er den Norden und ging als Chirurg nach [[Sturmwind]]. Er träumte davon, aus dämonischen und sterblichen Körpern eine überlegene Spezies zu erschaffen, die mächtiger als [[Geißel]] und Legion zugleich wäre. Zu diesem Zweck unternahm er einige Ausflüge in den [[Nether]], wo er als Verbündeter aktzeptiert wurde.\r\nAldorius diente damit zwei Herren und unterwarf sich noch einem Dritten: Lord [[Kazot]] von der Dritten Macht. Als er in dieser Organisation von Ketzern hoch aufstieg, zerfiel diese. Aldorius und einige Mitstreiter gründeten daraufhin die sogenannte \"[[Exequien]]\", welche Aldorius jedoch bald aufgrund innerer Spannungen verlies. Doktor van Croyden saß inzwischen viermal im Kerker der [[Heilige Inquisition|Heiligen Inquisition]], einmal im Kerker der Stadtwache und war zweimal von der [[Magiergilde]] gefangengenommen worden, konnte jedoch jedesmal fliehen. Sein derzeitiger Aufenthaltsort ist unbekannt, zuletzt wurde er öffentlich wahrgenommen, als er im Keller einer Taverne [[Sturmwind]]s eine schwarze Messe abhielt.\r\n= Karriere =\r\n= Persönliches =\r\nAldorius ist ein sehr verbitterter, zynischer Mann, der voller Verachtung für alles in seinen Augen Schwache und Minderwertige ist. Er preist die dunklen Künste und alle Feinde des Lichts. Zwar ist er sowohl ein relativ hoher Diener von Arthas (seit einem Bündnis zwischen Geißel und Exequien) als auch der [[Brennende Legion|Brennenden Legion]], jedoch ist es wahrscheinlich, dass er nur seine eigenen Ziele verfolgt. \r\nBei seinem letzten Ausbruch aus der Zelle der Magiergilde verlor er den linken Arm, den er jedoch durch ein untotes Skelettimplantat ersetzte. Er war kurze Zeit mit Kiyan Maeve-Marga verheiratet, welche sich jedoch bald von ihm trennte. Er hat einen Neffen, [[Allistor]], der amtierender Lordmagistrat von Stormwind ist.",},
			["Aldrassil"] = { content = "Der große Baum Aldrassil liegt im [[Laubschattental]] von [[Teldrassil]] und ist das Startgebiet der [[Nachtelfen]]. \r\n==Personen==\r\n* '''Gilshalan Windwandler''' kam nach [[Laubschattental]], um hier die Waldweberspinnen zu beobachten, die in der [[Schattenweberhöhle]] leben. Er glaubt, der [[Weltenbaum]] hat einen nicht unerheblichen Effekt auf sie und er hätte gern ein paar Exemplare von ihnen, um dies zu belegen. Als Erstes hätte er gern etwas von ihrem Gift, dann kann er ihres und das Gift ihrer kleineren Verwandten auf Gemeinsamkeiten hin untersuchen. Wenn er das Spinnengift hat, hätte er gern auch ein paar lebende Exemplare, um sie zu studieren. Wenn man ihm ein unausgebrütetes Ei besorgen könnte, wäre es viel einfacher, lebende Exemplare zu bekommen, und er könnte dafür sorgen, dass die noch nicht ausgeschlüpften Exemplare ordentlich unter Verschluss gehalten werden. \r\n* '''Mardant Starkeiche''' ist [[Druiden]]lehrer und befindet sich im großen Baum Aldrassil im [[Laubschattental]].\r\n* '''Melithar Hirschhaupt''' ist ein weiser [[Druide]] und vom Wispern der Waldgeister wurden ihm seltsame Neuigkeiten zugetragen, dass die geheimnisvolle Beschützerin des Waldlandes, [[Tarindrella]], in das [[Laubschattental]] zurückgekehrt ist. Es ist nicht bekannt, inwieweit er mit [[Fandral Hirschhaupt]] verwand ist.\r\n* '''Orenthil Wisperwinds''' Verwandschaft zu [[Tyrande Wisperwind]] ist ebenfalls ungeklärt.\r\n* '''Tenaron Sturmgewalt''' befindet sich in dem am höchsten gelegenen Raum in Aldrassil und erzählt die Geschichte der [[Krone der Erde]].",},
			["Alexi Barov"] = { content = "Der ehemalige Adlige '''Alexi Barov''' ist einer der beiden letzten verbliebenen Erben des Hauses Barov. Sein Bruder [[Weldon Barov]] ist der andere. Alexi versteckt sich unter dem Schutz der [[Horde]] am [[Bollwerk]] in [[Tirisfal]] und beansprucht genau wie sein Bruder, [[Weldon Barov]], das Familienvermögen der [[Barovs]] aus der [[Scholomance]] für sich. Doch da sein Bruder noch am Leben ist, wird es möglicherweise einen Disput darüber geben, wer der Hauptbegünstigte des Familienvermögens des Hauses ist. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für [[Darrowehr]], die Besitzurkunde für [[Brill]], die Besitzurkunde für [[Tarrens Mühle]] und die Besitzurkunde für [[Süderstade]]. Alexi würde diese Urkunden alle sehr gern in seinen Händen wissen, ehe es sein Bruder tut. \r\n'''Quellen'''",},
			["Alexstons Bauernhof"] = { content = "'''Alexstons Bauernhof''' ist eines der großen Gehöfte in Westfall. Doch wie so viele [[Bauernhof|Bauernhöfe]] in diesem Gebiet, fiel auch dieser den Banditen zum Opfer, denn Eine Bande heimtückischer Plünderer der [[Defias]] ist dabei gesehen worden, wie sie Alexstons Bauernhof ausplünderten.",},
			["Alexstrasza"] = { content = "==Herrschaftsgebiet==\r\nDie rote Drachenkönigin '''Alexstrasza''' steht für Leben und Hoffnung, sie betrachtet sich selbst als Beschützerin aller Geschöpfe. Alexstrasza liebt alle lebende Wesen und beschützt sie, und sie ist bekannt für ein großes Mitgefühl. Nur jene, die die Drachenschwärme oder die Welt bedrohen, müssen sich ihrem Zorn stellen. Für jemanden von ihrer Kraft ist die Drachenkönigin erstaunlich mitleidsvoll. Während [[Ysera]] immer die träumenden Rassen und die Studenten von [[Cenarius]] bevorzugt hat, sind '''Alextrasza''' und ihr Schwarm dafür bekannt, dass sie Töten insgesamt vermeiden möglich (Sie sind die Verteidiger des Lebens).\r\n==Aufenhaltsort==\r\nNach allem ist Alexstrasza noch die Gefangene des [[Orcs|orcischen]] [[Drachenmal Klan]]s und es sind ihre Nachkommen, die jene [[Orcs]] für Jahre benutzt haben, um Blutvergießen zu verüben und die ganze [[Allianz]] zu verwüsten.\r\n==Verwandte==\r\n* [[Caelestrasz]] (Erbe)\r\n* [[Korialstrasz]] (gegenwärtiger 1. Gemahl)\r\n* [[Malygos]] (Mitaspekt)\r\n* [[Neltharion]] (Mitaspekt)\r\n* [[Nozdormu]] (Mitaspekt)\r\n* [[Tyranastrasz]] (früherer Hauptgemahl)\r\n* [[Ysera]] (Schwester) (Mitaspekt)\r\n* zahllose drakonische Nachkommen\r\n==Geschichte==\r\nAls sich die [[Titanen]] mit ihrer Schöpfung auf [[Azeroth]] zufrieden fühlten, reisten sie fort, um zu durchstreifen den Kosmos auf der Suche nach neuen Welten, um Ordnung in das Chaos zu bringen und auf einer von unzähligen Welten neues Leben zu erschaffen. Vor ihrem Weggang ernannten sie fünf Drachen zu den Drachenaspekten. Ihr Zweck war die Schöpfung der [[Titanen]] - [[Azeroth]] - zu bewachen und zu schützen. \r\n[[Eonar]], die Titanische Patronin allen Lebens, gab einen Teil ihrer Kraft an den Roten Leviathan, '''Alexstrasza'''. Seitdem war '''Alexstrasza''' bekannt als die Lebensbinderin und sie schützte alle lebenden Wesen in der Welt. Aufgrund ihrer überragenden Weisheit und grenzenlosen Mitgefühls für alle lebenden Dinge, wurde Alexstrasza zur Drachenkönigin gekrönt und ihr wurde die Herrschaft über ihre Art gegeben. \r\nAlexstrasza war einer der drei Drachenaspekte, die die [[Dämon]]en der [[Brennende Legion|Brennenden Legion]] während des Krieges der Uralten bekämpften. Um die Legion zu stoppen, legten die fünf Aspekte all ihre Kraft in ein uraltes Artefakt namens [[Drachenseele]]. [[Neltharion]] jedoch verriet seine Mitaspekte und benutzte die [[Dämonenseele]] (die die Drachenseele war) um einen Teil ihrer Kraft zu stehlen. Sie entließen ihn und der resultierende Krieg machte ihn zum letzten schwarzen Drachen. \r\nAls [[Illidan]], Bruder von [[Malfurion]] Sturmgrimm, drei Phiolen mit Wasser aus dem [[Brunnen der Ewigkeit]] über dem Fluss des Berges [[Hyjal]] leerte, beschloss '''Alexstrasza''' den neuen Brunnen als Werkzeug zur Heilung des Landes zu benutzen, indem sie eine magische Eichel aus G'Hanir dem Mutterbaum in dem neuen Brunnen am [[Hyjal]] platzierte. Sie nannte den neuen Weltenbaum [[Nordrassil]]. \r\n10.000 Jahre später, während des zweiten Krieges, fingen die [[Orcs]] des Drachenmaul Klans '''Alexstrasza'''. Nekros, einem Krieger und früheren Hexenmeister, wurde die [[Dämonenseele]] von seinem Kriegshäuptling gegeben. Damit teleportierten sich Nekros und die [[Orcs]] zum Hort des Roten Drachenschwarms und fingen '''Alexstrasza''' und ihren ältesten Gemahl Tyranastrasz, um sich mit ihr zu paaren und mehr Eier zu erzeugen. Die neue Brut der roten Drachen wurde von den [[Orcs]] als Kriegsreittiere benutzt. Doch '''Alexstrasza''' hatte keine Wahl als Nekros drohte ihre ungeborenen Brutlinge zu töten.\r\nNach dem Zweiten Krieg wurde '''Alexstrasza''' wertvoller als jemals zuvor, da sie jetzt das einzig reale As lieferte, dass die [[Horde]] noch im Ärmel hatte. Somit mußte sie um jeden Preis beschützt werden. Doch [[Todesschwinge]] - ihr verhasstester Feind, der ihre fortgesetzte Unterwerfung während des Zweiten Krieges teilweise arrangiert hatte - arrangierte einen sorgfältig ausgearbeiteten Plan, um sie in die Öffnung zu ziehen und ihre Kinder zu stehlen, in der Hoffnung seine eigenen Nachkommen zu erzeugen. Jedoch erleichterte er unwissentlich ihre Flucht. Obwohl [[Tyranastrasz]] von dem schwarzen Drachen getötet wurde, versammelte '''Alexstraszas''' früherer Partner [[Korialstrasz]] die anderen drei Aspekte, die noch der Kraft des Lichtes folgten: [[Nozdormu]], [[Malygos]] und [[Ysera]]. Zusammen mit der Hilfe des Zauberers [[Rhonin]] wurde die [[Dämonenseele]] zerstört und so konnten die Aspekte [[Todesschwinge]] angemessen angreifen. Er floh ohne Ei, aber er hatte '''Alexstrasza''' unabsichtlich befreit. \r\n'''Alexstrasza''' tötete Nekros, forderte ihre Kinder zurück und flog mit Korialstrasz fort, um in Crestfall zu ruhen. Ihre feuerspuckenden Kinder kehrten zu ihren Posten als Beschützer allen Lebens zurück und arbeitete daran, ihre verwüstete Rasse wiederaufzubauen. \r\n==Aktuelles==\r\nKrasus und Alexstrasza leben jetzt in Grim Batol als ihren neuen Hort. Der Zwergische Führer war ein Agent von Krasus und zusammen sind es ca. 600 Zwerge, die jetzt den Drachenschwarm in Grim Batol bewachen. Unter '''Alexstraszas''' Fähigkeiten können sie die Wälder wieder zum wachsen bringen und das Land heilen. Sie können die Toten beleben und wiederbeleben.",},
			["Alfar"] = { content = "'''Alfar''' war der Erste Rudelführer, der Alphawolf, der [[Die einsamen Wölfe|einsamen Wölfe]]. Er war [[Amyrlin]]'s Gemahl und nach langer Abwesenheit aus der [[World of Warcraft]] ist er nun wieder auf [[Azeroth]] anzutreffen und nun Mitglied der Gilde [[Ruhm und Ehre]].\r\n==Geschichte==\r\nAls Sohn einer [[Ingenieure|Ingenierin]] und ein [[Bergbau]]ers wuchs ich in der Nähe von [[Dunkelküste|Auberdine]] in einer kleine Hütte auf.\r\nMeine [[Jäger]]geschichte begann an einem lauen Sommernachmittag. An diesem Nachmittag ging ich wie jeden Tag mit meinem Vater zu den Minen nähe [[Dunkelküste|Auberdine]], um wieder ein wenig Kupfer aus dem Harten Gestein zu brechen. Als wir uns schon fertig machten, um den Heimweg anzutreten, hörten wir ein Lautes aufschreien, der wohl aus der nähe des Mineneingangs herkam. Mein Vater lies alles fallen sagte mit bestimmender Stimme das ich hier bleiben solle und rannte raus um zu beobachten was dort geschehen ist. Als nach einer weile mein Vater nicht zurückkam rannte ich ebenfalls hinterher, doch als ich am Ausgang angelangt war sah ich schon mein Vater leblos am Boden liegen. Ich schaute hektisch umher um zu verstehen was passiert war, da sah ich schon das ein [[Jäger]] sich mit zwei [[Krieger]]n der [[Horde]] ein schweren Kampf lieferte. Ich war verzweifelt und schaute ziellos umher als ich am Boden ein Langbogen samt Köcher am Boden liegen sah.\r\nOhne lang zu überlegen schnappte ich mir den Bogen Spannte kräftig ein Pfeil an, zielte auf eines der beiden [[Krieger]], atmete zwei mal durch und lies los...der [[Krieger]] lag regungslos am Boden. Der zweite [[Krieger]] merke das geschehene, stieß den [[Jäger]] zu Boden und rannte mit gehobener Klinge auf mich zu. Ich überlegte nicht lange, spannte ein zweiten Pfeil schloss die Augen und schoss ohne lang zu warten den Pfeil ab...ich öffnete die Augen...Volltreffer!!\r\nDer [[Jäger]] stand schmerzerfüllt auf und rannte auf mich zu um zu sehen ob ich verletzt währe. Er lächelte als er sah das ich nicht einmal ein Kratzer abbekommen hatte.\r\nZuhause angekommen versorgte ich ihn seine Wunden und wir aßen was zusammen. Von diesen Tag an wusste ich das ich Jäger werden wollte. Der [[Jäger]] brachte mir alles wichtige bei was ein [[Jäger]] wissen muss um in [[Azeroth]] zu überleben.\r\nJetzt streifen ich und mein Begleiter Destructor in [[Azeroth]] umher um den Tod meines Vaters an der [[Horde]] zu rächen...",},
			["Algadar Hetius"] = { content = "'''Algadar Hetius''' ist ein [[mensch]]licher [[Magier|Arkanist]] hohen Alters. Er lebt im Sanktum zu [[Sturmwind]] und stellt dort arkane Forschungen an. Hetius dient derzeit der [[Die Magiergilde|Magiergilde]].\r\n==Persönliches==\r\nAlgadars Gesicht ist durchfurcht von Altersfalten. Hetius trägt einen kurzen Vollbart, seine Halbglatze bedeckt er meist durch Hüte.\r\nAlgadar Hetius wird von chronischem Husten geplagt, welcher nach seinen Aussagen von keinem Medizinmann [[Azeroth]]s geheilt werden kann. Gemeinsam mit dem gebrechlichen Auftreten Algadars (er stützt sich in der Regel auf einen Holzstab) komplettiert der Husten das Bild eines körperlich äußerst angeschlagenen Mannes. \r\nAlgadar hat oder hatte einen Bruder, über den jedoch nahezu keine Informationen bekannt sind.\r\n==Weblinks==\r\n<br \>\r\n<br \>",},
			["Aliden Perenolde"] = { content = "'''Lord Aliden Perenolde''' von [[Alterac]] ist der momentane Führer des [[Syndikat]]s und der selbsternannte Lord des [[Alterac]]gebirges. Er ist der Sohn von Lord [[Aiden Perenolde]] und hatte [[Aedelas Schwarzmoor]] als Mentor. Lord Aliden Perenolde gehörte früher zum königliches Adelshaus von [[Alterac]] und hat momentan Pläne, die [[Orcs]], die sich gegen ihn gewandt hatten, zu Sklaven zu machen, genau wie es einst auch sein Vater und Mentor, der geächtete [[Aedelas Schwarzmoor]], geplant hatte. Sein Herrenhaus liegt an den Ufern des [[Lordameresee]]s in [[Alterac]].\r\n==Verwandte==\r\n* [[Aiden Perenolde]] - Vater\r\n* [[Isolde Perenolde]] - Mutter\r\n* [[Beve Perenolde]] - Schwester\r\n* [[Elysa]] - Geliebte",},
			["Alleria"] = { content = "#REDIRECT [[Alleria Windläufer]]", redirect = "Alleria Windläufer",},
			["Allerias Feste"] = { content = "Allerias Feste ist ein Stützpunkt der [[Allianz]] im Gebiet der [[Wälder von Terokkar]]. Benannt nach [[Alleria Windläufer]], wird die Feste heute von den [[Söhne Lothars|Söhnen Lothars]] geführt. Nach der Ankunft der [[Höllenorcs]] in den [[Ruinen der Knochenmalmer]] haben die Bewohner von Allerias Feste keine Zeit verschwendet und sofort begonnen, Befestigungsanlagen zu bauen und die Gebäude zu reparieren. Die Bauarbeiten laufen Tag und Nacht. Hier an der Front müssen sie sich Tag für Tag mit den [[Arakkoa]] herumschlagen. Sie greifen die Feste an, wenn es ihnen gerade passt, plündern die Vorräte und erschlagen die Späher. Und doch wissen sie nur wenig über diese rätselhaften Kreaturen.",},
			["Allerias Posten"] = { content = "'''Allerias Posten''' liegt in den [[Wälder von Terokkar|Wäldern von Terokkar]] im Nordosten von [[Allerias Feste]] am südlichen Ufer des Flusses. Es ist ein kleines Lager der Allianz, welches zwischem den [[Posten der Feuerschwingen]] und den [[Ruinen der Knochenmalmer]] liegt.",},
			["Alleria Windläufer"] = { content = "==Allgemeines==\r\nWaldläuferhauptmann Alleria Windläufer war eine berühmte Trolljägerin aus Quel'Thalas. Sie war ebenso Hauptspäherin und Geheimagentin für die Expedition der Allianz, die in Draenor, der Heimat der Orcs, einmarschiert ist. Diese sehr erfahrene Hochelfe überlebte das zerstörerische Werk der [[Horde]] und suchte nach einer Spur zu ihrer Familie unter der Asche der ehemals glorreichen Stadt [[Quel'Thalas]]. Ihr grenzloser Hass auf die [[Orcs]] führte sie nach [[Azeroth]], wo sie ein Elite Corps befehligte, das beauftragt wurde, die [[Orcs]] des [[Klan des Blutenden Auges|Klans des Blutenden Auges]] zu verfolgen. Während des [[Der Dritte Krieg|Dritten Krieges]] wurde sie nach [[Draenor]] gesendet, wo sie wahrscheinlich bei der Explosion des Planeten ihren Tod fand. \r\n==Geschichte==\r\nAlleria Windläufer erntete ihre ersten Lorbeeren in den [[Trollkriege]]n durch die schier unglaubliche Anzahl von [[Trolle]]n, die sie tötete, um [[Quel'Thalas]], die Heimat ihres Volkes, zu verteidigen. Mit Hilfe der [[Menschen]] trugen die [[Hochelfen]] letztendlich den Sieg über die [[Trolle]] davon. Leider war das nicht der letzte Krieg, der die [[Hochelfen]] heimsuchen sollte. \r\nWährend des [[Der Zweite Krieg|Zweiten Krieges]] brannte die [[Horde]] die Grenzlande von [[Quel'Thalas]] nieder. Die tobenden [[Orcs]] töteten Allerias Eltern, doch sie selbst überlebte mit ihren beiden jüngeren Schwestern, [[Sylvanas Windläufer]] und [[Vereesa Windläufer]]. Getrieben von Trauer und Hass schwor Alleria allen [[Orcs]] Rache. Ihr Rachefeldzug trieb sie in die Länder der [[Menschen]], wo sie eine Elitegruppe von [[Waldläufer]]n anführte. Ihr Trupp jagte Orcische Renegaten des [[Klan des Blutenden Auges|Blutenden Auges]], die bei Ende des [[Der Zweite Krieg|Zweiten Krieges]] auf [[Azeroth]] vom Rückzug abgeschnitten worden waren. \r\nDie [[Allianz]] von [[Lordaeron]] hatte zwar das auf [[Azeroth]] geöffnete [[Dunkle Portal]] vernichtet, um die [[Orcs]] von ihren Verstärkungen von [[Draenor]] abzuschneiden. Doch [[Ner'zhul]] und andere Zauberer der [[Horde]] benutzten magische Artefakte am Gegenstück des Dunklen Portals auf [[Draenor]], das immer noch funktionsfähig war. Somit gelang es den mächtigen [[Magier]]n und Hexern, den Übergang von [[Draenor]] nach [[Azeroth]] wieder zu öffnen. \r\nDie [[Allianz]] reagierte schnell auf die neue Bedrohung und schickte ein Expeditionskorps durch das Portal nach [[Draenor]].\r\nDa sie inzwischen den Rang des Captain erreicht hatte, gehörte Alleria Windläufer mit zu diesem Trupp, der seinen gefährlichen Auftrag schließlich erfolgreich ausführen und das [[Dunkle Portal]] auf [[Draenor]] zerstören konnte. Wieder waren die Truppen der [[Horde]] auf [[Azeroth]] vom Nachschub und Verstärkungen abgeschnitten und wurden völlig aufgerieben. Zum guten Schluss zerstörte die [[Allianz]] auch noch das neue [[Dunkle Portal]] auf [[Azeroth]]. Alleria und die anderen Kämpfer des Allianz Expeditionskorps vernichteten das [[Dunkle Portal]] auf [[Draenor]] gerade in dem Augenblick, als [[Ner'zhul]] eine Reihe weiterer Portale von [[Draenor]] in andere Welten öffnete. \r\nDer Planet [[Draenor]] war schon zuvor durch den Missbrauch dunkler Magien der [[Orcs]] geschwächt. Doch nun, unter der zusätzlichen Belastung durch die anderen Portale, begann er buchstäblich, in Stücke zu reißen. Als der Planet unter ihren Füßen erzitterte, erkannten die Mitglieder des tapferen Expeditionskorps der [[Allianz]], dass es Selbstmord wäre, auf [[Draenor]] zu bleiben. So wählten sie auf gut Glück eines der neuen Portale aus und schritten hindurch. Seit jenem schicksalhaften Tag hat man nichts mehr von ihnen gehört. Da es unwahrscheinlich ist, dass sie irgendwo noch am Leben sein könnten, werden Alleria und ihre Kameraden als tot betrachtet, gefallen in Ausübung ihrer Pflicht. Bis zum heutigen Tage ehrt man sie für das Opfer, das sie gebracht haben. Im Tal der Helden, direkt hinter den Toren der Stadt [[Sturmwind]], wurde an markanter Stelle eine Statue von Alleria errichtet.\r\n'''Quellen'''",},
			["Allianz"] = { content = "Die '''Allianz''' ist eine von zwei spielbaren [[Fraktion]]en der [[World of Warcraft]].\r\nDie jetzige Allianz ist der Nachfolger der [[Allianz von Lordaeron]], welche zerbrach, als [[Arthas]] [[Lordaeron]] eroberte.Die Allianz besteht aus verschiedenen Nationen, die in [[Theramore]] ihren Beratungsplatz haben. Die eigentliche Hauptstadt ist [[Sturmwind]]. Alle Völker der Allianz teilen dan Glauben an das [[Heilige Licht]] oder an irdendein anderes Licht(mit Ausnahme der Gnome). Außerdem misstrauen alle Völker der [[Horde]]. Körperlich sind die [[Krieger]] der Allianz der Horde zwar unterlegen, doch ihr Mut, ihre Entschlossenheit und die Überzeugung, dass das Licht letztendlich siegen wird, trieben sie voran und führten letztendlich zum Sieg über die alte Horde. Viele Völker verließen die Allianz, viele schloßen sich ihr neu an. Alle Völker der Allianz haben in der Vergangenheit schwere Verluste erlitten, aber trotzdem führten sie ihre Ziele weiter. In punkto Technologie ist die Allianz der Horde überlegen, jedoch hat die Horde diesen Umstand durch ihre Magiekundigen Verbündeten, die Blutelfen, oft genug ausgleichen können.\r\nDie Champions der Allianz sind:\r\n* [[Hochlord Bolvar Fordragon]]\r\n* [[Tyrande Wisperwind]]\r\n* [[Hochtüftler Gelbin Mekkadrill]]\r\n* [[Weissager Nobundo]]\r\n'''Organisation'''\r\nDie Allianz ist keine homogene Regierungsform sondern eine Koalition bestehend aus gegenseitiger militärischer und wirtschaftlicher Unterstützung. Theramore könnte eigentlich als offizielle Heimat der neuen Allianz gesehen werden, doch sowohl das Volk als auch die Führungskräfte in [[Sturmwind]] haben Probleme, dies anzuerkennen. Nachdem Sturmwind nicht in der Lage war, zu handeln, sprangen [[Theramore]] und die Nachtelfen ein, was zu einer erweiterten Kluft die Kooperation betreffend zwischen beiden Kontinenten führte. Tatsächlich besteht die heutige Allianz eigentlich aus zwei Allianzen welche grösstenteils unabhängig voneinander arbeiten, und sich teilweise auch nicht mögen. \r\nIn der Vergangenheit hatten gewisse Regeln, Traditionen und Gebräuche schon zum Nachteil der Allianz geführt. Die Kooperation war beizeiten schlampig durchgeführt und erhöhte massgeblich die Zeit, in welcher die Allianz ihre Ländereien zurückerobern und zu altem Glanz erstrahlen lassen konnte. Doch nebst ihren Problemen und Intrigen an der Führungsspitze teilt die Allianz zwei Hauptanliegen: den Wiederaufbau und das Misstrauen gegenüber der [[Horde]]. Laut den Quellenbüchern[2] zählt die Allianz etwa 800.000 Seelen über zwei Kontinente[3] Im Grossen und Ganzen könnte man die Allianz als eher friedfertig bezeichnen, ihre Macht ist legendär, ihr Wunsch nach Frieden noch grösser. Während jedoch [[Jaina Prachtmeer]] und [[Tyrande Wisperwind]]so wie [[Velen]] ihre Unternehmungen auf [[Kalimdor]] koordinieren, arbeitet [[Lady Katrana Prestor]] in den [[Östlichen Königreichen]] am genauen Gegenteil.\r\nSelbst jetzt halten jedoch die [[Menschen]] aufgrund ihrer Anzahl die Allianz zusammen und sind wohl auch das diplomatischste Volk unter den fünf Rassen. Allerdings verschiebt sich die Antriebskraft der Allianz immer mehr in Richtung der [[Nachtelfen]], welche einen massgeblichen Anteil der militärischen Streitkräfte der Allianz stellen - während die Armeen in Sturmwind hinter den Mauern in einer Inaktivität gehalten werden.Eine Änderung der Lage ist durch die Rückkehr des Königs [[Varian Wrynn]] möglich. \r\n==Völker==\r\n* [[Draenei]], ([[Exodar]])\r\n* [[Gnome]], ([[Gnomeregan]])\r\n* [[Menschen]], ([[Sturmwind]])\r\n* [[Nachtelfen]], ([[Darnassus]])\r\n* [[Zwerge]], ([[Eisenschmiede]])\r\n==Siehe auch:==\r\n* [[Gilden der Allianz]]\r\n* [[Handwerksverzeichnis der Allianz]]\r\n* [[Schlachtzüge der Allianz]]",},
			["Allistor"] = { content = "#REDIRECT [[Allistor van Croyden]]", redirect = "Allistor van Croyden",},
			["Allistor van Croyden"] = { content = "Allistor van Croyden war zu Lebzeiten der mächtigste noch lebende Angehörige des [[Croyden-Clan]]s und hatte die Position des Ersten Magistraten der [[Stadt Stormwind]] inne.\r\n= Lebenslauf =\r\nAllistor wurde vor 27 Jahren in [[Tirisfal]] geboren als Sohn von William van Croyden dem Jüngeren, einem Adligen ohne Land, der sein Geld als Steuereintreiber des Königs verdiente.\r\nDank seines Onkels Dr. Johann [[Aldorius]] van Croydens, welcher damals den Titel eines [[Magier|Erzmagier]] in [[Dalaran]] hatte, bekam er eine Stelle als Student in der Stadt. Er überlebte die Vernichtung Dalarans und wurde zum Hexenjäger der [[Kirin Tor]] ausgebildet. (Vermutlich wollten die [[Magier]] einen Verwandten von [[Aldorius]] nach dessen Verrat aus der Stadt wissen.)\r\nAllistor arbeitete verdeckt im Auftrag [[Dalaran]]s in [[Sturmwind]], Familie besitzt er keine, seit ihm der Krieg beide Eltern nahm. In der Stadt stieß er auf eine blühende Szene von Schattenanhängern, jedoch bekam er keine Unterstützung des alten Stadtrates. Als er sich beim König lautstark über diese Diskrepanz beschwerte, zeigten sich diese und der Hochlord so beeindruckt, dass sie ihn in den Rang eines Magistraten erhoben.\r\nIm dritten Monat dieses Jahres wurde Allistor an seinem Schreibtisch im Rathaus von Kultisten unbekannter Herkunft ermordet.\r\nSein Grab liegt auf dem Friedhof von Goldhain.\r\n= Karriere =\r\nAllistor van Croyden nutze sein Engagement schnell für sich und erklärte sich für Aufgaben bereit, denen sich die anderen, älteren Magistraten nicht gewachsen sahen. Er schlug [[Sutech]] Noriah von der [[Die Scharlachrote Flamme|Scharlachroten Flamme]] zum Baron und kümmerte sich um die geringe Auslastung der Immobilien der Stadt. Bald darauf ernannte der König ihn zum \"Hohen Magistraten\" der Stadt und lies unter Allistors Leitung den neuen [[Stadtrat Sturmwind|Stadtrat]] gründen.\r\n= Persönliches =\r\nAllistor war nicht verheiratet, sondern lebte allein in einer Wohnung in Burg [[Sturmwind]]. Er hinterlies keine Kinder.",},
			["Altar der Dunkelheit"] = { content = "Ein '''Altar der Dunkelheit''' dient als kanalisierender [[Nexus]] für die dunklen Regenerierungskräfte der [[Geißel]]. Fällt ein Held im Kampf, so kann seine Essenz an diesen Ort gerufen werden, wo ihm neues, unheiliges Leben eingehaucht wird.",},
			["Altar der Schatten"] = { content = "Der '''Altar der Schatten''' befindet sich weit im Südosten des [[Schattenmondtal]]s, hinter den [[Netherschwingenfelder]]n und jenseits des [[Netherschwingenpass]]es. Hier haust der alte Geist von [[Teron Blutschatten]] und der Altar ist sein Gefängnis. Wenn er alle drei seiner alten Gegenstände in seinem Besitz hat, kann er einen Wirtskörper übernehmen und die, die ihn gefangen haben, vernichten und das Band für immer zerreißen. Um von seinem Bann loszukommen, muss man seinen Willen erfüllen und Karsius den uralten Wächter töten.",},
			["Altar der Sha'tar"] = { content = "[[Die Aldor]] stellen mit den östlich gelegenen Altar der Sha'tar im [[Schattenmondtal]] wichtige Flugpunkte für den Kampf gegen [[Illidan]]s Dämonen.\r\n==Personen==\r\n* '''Anachoret Ceyla''' - Sie möchte, dass man einige [[Schrifttafeln von Baa'ri]] in den [[Ruinen von Baa'ri]] sammelt.\r\n* '''Herold Saronen'''\r\n* '''Exarch Onaala'''\r\n* '''Verteidiger Aluumen''' - Er möchte, dass man die Mitglieder der [[Orcs des Schattenmondklans]] tötet, um den geheiligten Boden der Draenei zurückzufordern.",},
			["Altar der Stürme"] = { content = "Die '''Altäre der Stürme''' wurden ursprünglich von [[Gul'dan]], dem [[Hexenmeister]] erschaffen, um dämonische Energien in die Oger-Magi zu kanalisieren. Sie waren mit der verdorbenen Kraft von gestohlenen [[Runensteine]]n durchdrungen, wie z.B. dem aus [[Caer Darrow]]. Nach [[Thrall]]s Reformation der [[Horde]] wurden viele Altäre von trollischen Steinmetzen in ihrer Konstruktionen verändert, damit sie fähig waren, schamanistische Energien zu kanalisieren. Die Absicht dahinter war, gefallene Helden wiederzubeleben. Zwei der ursprünglich dämonischen Altäre sind noch heute unverändert zu bestaunen: Einer in der [[Brennende Steppe|Brennenden Steppe]] nahe dem [[Schwarzfels]] und einer in den [[Verwüstete Lande|Verwüsteten Landen.]]",},
			["Altar der Verdammnis"] = { content = "Der '''Altar der Verdammnis''' befindet sich im Osten des [[Schattenmondtal]]s, in der Nähe der [[Teufelsgruben]] und südlich der [[Todesschmiede]]. Dort sind Teile der Vergangenheit gefangen und das Echo von [[Gul'dan]]s Erinnerung hallt durch diesen verfluchten Ort. Hier durchtrenne Gul'dan die Verbindung zwischen den Orcs und den Elementargeistern. Sein unstillbarer Durst nach Macht konnte durch die Auslöschung der Draenei nicht gesättigt werden. Er mußte außerdem noch Draenor zerstören, das Land auslöschen und dessen Energien für seinen Krieg absaugen. Alles, was bleibt, sind Überreste seines Wahnsinns und das Land ist für immer verflucht.\r\nDie [[Elementare|Geister der Elemente]] an diesem Ort sind in Aufruhr und der [[Irdener Ring|Irdene Ring]] will herausfinden, ob sie etwas für das [[Schattenmondtal]] tun können. \r\nMit der vollständigen [[Litanei der Verdammnis]] kann man am Altar [[Cyrukh der Feuerlord|Cyrukh den Feuerlord]] rufen. Doch wie oft wurde dieser Zauber in der Geschichte der Welten benutzt? Seine zerstörerische Macht ist mit Sicherheit einzigartig. Sobald die Worte gesprochen werden, wird man die Erinnerungen, die in das Land eingebrannt wurden, sehen ... Dieses Land kann einer weiteren Zerschlagung nicht standhalten.",},
			["Altar von Zul"] = { content = "Der Altar von Zul befindet sich im [[Hinterland]] am Westrand des Territoriums der [[Trolle der Blutfratzen]].",},
			["Alten Götter"] = { content = "#REDIRECT [[Alte Götter]]", redirect = "Alte Götter",},
			["Alterac"] = { content = "==Allgemeines==\r\nEinst eines der ursprünglichen sieben Königreiche der [[Menschen]], ist Alterac heute ein zerrüttetes Reich, das versucht die Folgen der letzten Kriege zu überstehen. Eine Organisation namens \"Das [[Syndikat]]\" beherrscht den größten Teil der Region. Das [[Syndikat]] kämpft außerdem mit den Trümmergrat-[[Oger]]n um die Herrschaft über die Ruinen der alten Hauptstadt von Alterac. Im Süden des Alteracgebirges liegt das [[Vorgebirge des Hügellands]], im Osten das [[Hinterland]], im Westen der Lordameresee und im Norden die [[Pestländer]].\r\n==Geschichte==\r\nDie kleine Nation Alterac war das schwächste Volk der [[Menschen]], und während des Zweiten Krieges nur eine unbedeutende Quelle für Truppen der [[Allianz]]. Alterac und [[Stromgarde]] waren benachbarte Königreiche, die seit den ersten Tagen des Krieges im Streit waren. Alterac war, während es viel über Mut und Rechtschaffenheit sprach, nicht so bereitwillig gewesen seine Truppen zur Verfügung zu stellen. Es waren nur Gesten der Unterstützung. Umgeben vom Alteracgebirge und geschützt durch das mächtige Königreich Lordaeron, war die Nation vor den [[Orcs]]eigentlich relativ sicher. Trotzdem war Lord [[Perenolde]] von der Angst besessen, dass die [[Allianz]] der [[Horde]] nicht lange standhalten würde. Er sah die einzige Rettung für sein Volk in einer Verbrüderung mit den [[Orcs]], und machte von Beginn des Krieges an gemeinsame Sache mit ihnen. Die [[Horde]] betrieb bald Bergwerke in Alterac, von denen eine Revolte in Tyr's Hand ablenken sollte. Perenoldes Truppen unterstützten die [[Orcs]] sogar, und griffen [[Uther Lichtbringer]] auf einer Reise nach [[Caer Darrow]] an. Perenolde hatte die [[Allianz]] verraten, aber sein heimtückisches Handeln war kurzlebig. Die [[Allianz]] erklärte Alterac zum Kriegsgegner und [[Terenas]] hatte [[Lordaeron]]s Truppen schnell herbei geschafft, als er davon hörte, und erklärte das Kriegsrecht in Alterac. Die Armeen [[Lordaeron]]s zerstörten die Hauptstadt und riefen das Kriegsrecht aus. Nachdem König Terenas’ Truppen das Land gänzlich besetzt hatten, waren die [[Orcs]] gezwungen sich auch von dort zurückzuziehen. Nach dem Krieg stritten [[Stromgarde]] und [[Lordaeron]] um Alterac. \r\n===Die Alterac-Krise===\r\nNach dem Zweiten Krieg kam es unter den Mitgliedern der [[Allianz]] zu Streitigkeiten, was nun mit dem besetzten Alterac passieren sollte. Die Nachbarnation [[Stromgarde]] beansprucht den östlichen Teil des Reiches, und wollte es mit [[Lordaeron]] teilen. König [[Terenas]] hingegen plante Alterac vollständig zu annektieren oder einen neuen Herrscher einsetzen, der mit [[Lordaeron]] sympathisierte. Die Nation [[Gilneas]] wiederum wollte einen Neffen [[Perenolde]]s zum Herrscher machen, der Genn Graumähne hörig war. Die Alterac-Krise schien gelöst, als sich die [[Allianz]] auf Lord Prestor als zukünftigen Regenten einigen konnte. Kurz darauf verschwand der Adelige jedoch spurlos. Das Land blieb von den Truppen [[Lordaeron]]s besetzt und wurde schließlich ein Teil des Königreiches. \r\n'''Quelle''': \r\n==Orte==\r\n* [[Alteracgebirge]]\r\n* [[Strahnbrad]]\r\n===Dandreds Senke===\r\nIn Dandres Senke befindet sich [[Baron Vardus]].\r\n===Oberland===\r\nDas Oberland liegt nördlich von [[Strahnbrad]]. Hier ist das [[Syndikat]] am stärksten. Mit etwas Glück kann man die Abgesandten der [[Arguswacht]] dort finden.\r\n===Ruinen von Alterac===\r\nDas alte Königreich von Alterac ist nach dem großen Krieg gefallen und es besaß eine umfangreiche Büchersammlung. Es ist eine große Tragödie, dass die Stadt verfallen ist, aber es ist weitaus tragischer, dass all ihr Wissen verloren geht. In den Ruinen von Alterac liegt immer noch ein großer Wissenschatz, der möglicherweise für immer verloren geht. Jetzt leben hier die Oger, und die zeigen kein großes Interesse an höherer Bildung.\r\nMug'Thol und seine [[Oger des Trümmergratklan|Trümmergratoger]] haben einen Ogerhort im Alteracgebirge nahe der verfallenen Stadt Alterac gebaut und die Ruinen erobert. Falls sie sich dort zu sicher fühlen, werden sie bestimmt ins Vorgebirge eindringen und wären dann praktisch vor Süderstade. Mug'Thol und seine Ogerkriegsmeute wurde nach Alterac geschickt, um die [[Krone des Willens]] für Lady [[Sylvanas Windläufer]] zu holen. Doch anstatt sie zurückzubringen, hat Mug'Thol versucht, sie aufzusetzen. [[Oger]] können wohl einfach keinen Dingen widerstehen, die glitzern und schimmern. Seine stümperhaften Aktionen sind allerdings zu einem Problem geworden, denn die [[Krone des Willens]] hat ihm geholfen, der Besessenheit zu widerstehen, die ihm auferlegt wurde, damit er Lady [[Sylvanas Windläufer|Sylvanas]] dient.\r\n===Syndikatslager===\r\nDas [[Syndikat]] hat ein Lager nördlich von [[Tarrens Mühle]], das von der [[Horde]] besetzt ist. Die neuesten Hinweise zur Ermordung des vorherige Magistrat von [[Süderstade]] führen genau in dieses Lager. Die Führung, die hinter dem [[Syndikat]] steht, will [[Süderstade]] unbedingt ruinieren.",},
			["Alteracgebirge"] = { content = "Das '''Alteracgebirge''' sind ein verschneiter Gebirgszug im Süden [[Lordaeron]]s. Lange Zeit galten sie nur als unbedeutende Quelle für Ressourcen, aber während des [[Der Zweite Krieg|Zweiten Krieges]] betrieb die orcische [[Horde]] erfolgreich Bergwerke in der unzugänglichen Region. In den tiefen Tunneln und Höhlen der Berge hausen vereinzelte [[Kobolde]], aber auch das aggressive Volk der [[Gnolle]] ist im rauen Hochland [[Alterac]]s beheimatet. Selbst der [[Frostwolfklan]] siedelte sich im Alteracgebirge an, als [[Hexenmeister]] [[Gul'dan]] den Stamm verbannen ließ. Dort konnten sie an der schamanischen Kultur ihrer Ahnen festhalten und entzogen sich dem verderblichen Einfluss des [[Schattenrat]]s. \r\n==Personen == \r\n* [[Bath'rah der Windbehüter]] \r\n* '''Elysa''' - Auch [[Elysa]], die Geliebte von [[Aliden Perenolde]] befindet sich in dieser Gegend. Sie ist ein zartes Mädchen und trägt um ihren Hals den Anhänger von [[Taretha Foxton]], den der Kriegshäuptling [[Thrall]] als sein Eigen wünscht.",},
			["Alteractal"] = { content = "Tief im [[Alteracgebirge]] liegt das '''Alteractal''', das Zuhause von [[Thrall]]s Orkclan, den [[Frostwolfklan|Frostwölfe]]n. Die [[Zwerge der Sturmlanzen]] haben einen Stützpunkt im Tal errichtet und dringen auf der Suche nach Reichtümern tiefer in das Tal vor. Um diesen Treiben Einhalt zu gebieten, haben die Frostwölfe eine Armee errichtet, die sich in einer Schlacht um die gerechte Sache beweisen will. \r\nIn der Ferne kann man seitdem den Klang der Kriegstrommeln vernehmen. Auf der einen Seite wird die [[Allianz]] von den kannibalischen [[Trolle der Winteraxt|Winteraxtrollen]] angegriffen, auf der anderen bedrängt sie der grausame [[Frostwolfklan]]. Beide sollen im Namen des König [[Magni Bronzebart]] ausgelöscht werden, denn die Eroberung und Säuberung dieses Landes ist eine herrschende und territoriale Notwendigkeit für das Königreich von [[Eisenschmiede]]. Und egal, was auch immer man über die noch immer tobende Schlacht im Alteractal gehört hat, etwas davon ist wahr: Es war die Expeditionsarmee der [[Sturmlanzen]], die diesen Konflikt durch die Besetzung des Territoriums der [[Frostwolfklan|Frostwölfe]] entfachte, denn die [[Horde]] verkündet die Wahrheit, mit ihrer Behauptung, das Alteractal gehöre zum Territorium der [[Frostwolfklan|Frostwölfe]]. Und diese reagierten auf die Anwesenheit der [[Sturmlanzen]] mit einer, in der [[Allianz]], bis dato unbekannten Brutalität und Aggressivität. Niemals wird die [[Allianz]] all die Zwerge vergessen, die während des folgenden feigen und unangekündigten Angriffs zu Tode kamen.\r\n==Geschichte==\r\nVor langer Zeit schickte der Hexenmeister [[Gul'dan]] einen Klan der [[Orcs]] ins Exil, weil es dieser Klan gewagt hatte, sich der schleichenden Korruption der [[Orcs]] durch die [[Brennende Legion]] entgegenzustellen. Der [[Frostwolfklan]] zog sich in ein abgelegenes Tal des [[Alterac]]gebirges zurück, wo sie sich vor [[Gul'dan]]s Rache versteckten. Im unwirtlichen Alteractal fristeten die [[Orcs]] ein von der Welt abgeschiedenes, karges Dasein... bis [[Thrall]] kam. Nach [[Thrall]]s triumphaler Vereinigung der Klans entschlossen sich die [[Frostwolfklan|Frostwölfe]], unter der Führung des [[Schamanen]] [[Drek'Thar]], in dem Tal zu bleiben, das so lange ihre Heimat gewesen war. In jüngster Zeit wurde der Frieden des [[Frostwolfklan]]s jedoch durch die Ankunft der zwergischen Sturmlanzen-Expedition gestört. Die [[Sturmlanzen]] haben sich auf der Suche nach Rohstoffen und Relikten aus der [[Zwerge|zwergischen]] Vorgeschichte im Tal angesiedelt. Trotz ihrer friedlichen Absichten hat die Ankunft der [[Zwerge]] einen erbitterten Streit mit dem [[Frostwolfklan]] entfacht, in dem inzwischen beide Seiten um die alleinige Kontrolle über das Tal kämpfen. Die [[Forscherliga]] glaubt, dass es im [[Alteractal]] einige Artefakte von Interesse gibt. Allerdings werden die [[Orcs des Frostwolfklans]] die [[Zwerge]] wohl kaum danach forschen lassen. \r\n==Persönlichkeiten==\r\nVor Kurzem haben alle Kommandanten und Leutnants das Alteractal verlassen, um ihr Glück woanders zu suchen. Horde und Allianz verfügen seitdem nur noch über begrenzte Verstärkung. Jedes Mal wenn ein Spieler stirbt, ein Turm vom Gegner eingenommen und [[Hauptmann Galvangar]] oder [[Balinda Steinbruch]] getötet wird, verringert sich die Anzahl an Verstärkungseinheiten. Wenn General [[Drek'Thar]] oder [[Vanndar Sturmlanze]] stirbt, verliert die jeweilige Seite alle Verstärkungseinheiten. Wenn ein Team über keine Verstärkung mehr verfügt, gewinnt das gegnerische Team die Schlacht. \r\n* [[Ivus der Waldfürst]]\r\n* [[Lokholar der Eislord]]\r\n* [[Trolle der Winteraxt|Winteraxthöhlen]]\r\n==Burg Frostwolf==\r\nBurg Frostwolf ist der Hauptsitz der [[Horde]] und [[Drek'Thar]]s im Alteractal. Die Luftunterstützung der [[Horde]] musste einen schweren Schlag hinnehmen. Sämtliche Schwadronskommandanten wurden über feindlichem Gebiet abgeschossen.\r\n* [[Drek'Thar]]\r\n* [[Kommandant Louis Philips]]\r\n* [[Schwadronskommandant Mulverick]]\r\n'''Sonstige'''\r\n* '''Schwadronskommandant Guse''' - Schwadronskommandant Guse wurde das letzte Mal gesehen, als sie über den Eisschwingenbunker hinwegflog.\r\n* '''Schwadronskommandant Jeztor''' - Schwadronskommandant Jeztors Reittier wurde zuletzt am Sägewerk der Sturmlanzen gesichtet.\r\n* '''Najak Hexxen''' - Najak Hexxen wird für jeden [[Nachtelfen]], den man tötet und enthauptet, die Gunst der Dunkelspeere sichern, denn bevor die [[Nachtelfen]] waren, waren die [[Trolle]]. Erst von den [[Trolle]]n sind [[Nachtelfen]] gekommen. Ihre aufrührerischen Angriffe gegen sein Volk können nicht toleriert werden, doch [[Fandral Hirschhaupt]] will die [[Trolle]] auslöschen – sämtliche Spuren derer vernichten, die ihn und seines Gleichen ausgetragen haben. \r\n* '''Ravak Grimmtotem''' - Ravak Grimmtotem vom [[Tauren der Grimmtotem|Grimmtotemklan]] wurde von der Ältesten [[Magatha Grimmtotem]] in dieses Kriegsgebiet geschickt um die anderen Völker zu erforschen. Genau genommen ist er hier, um Proben von den [[Gnome]]n zu nehmen. Magatha interessiert sich insbesondere für ihre Überlebensfähigkeit. Die [[Gnome]] – obwohl erbärmlich schwach und winzig - scheinen sowohl im Kampf als auch körperlich äußerst widerstandsfähig zu sein.\r\n==Dun Baldar==\r\n* [[Schwadronskommandant Ichman]]\r\n'''Sonstige'''\r\n* '''Athramanis''' - Athramanis hat von [[Fandral Hirschhaupt]] Anweisung bekommen, alle [[Trolle]] auf dem Schlachtfeld auszulöschen. Ihrer lächerlichen Behauptung die [[Nachtelfen]] erschaffen zu haben, kann nur mit aller Macht und militärischen Mitteln entgegengewirkt werden.\r\n* '''Kommandant Karl Philips''' - Kommandant Karl Philips befindet sich im Gebiet der [[Sturmlanzen]]. Von allen vier Kommandanten stellt er zweifellos die größte Gefahr dar. Er bewegt sich zwischen dem Sägewerk und der Mine hin und her.\r\n* '''Zwergengeneral Vanndar Sturmlanze''' findet man in Dun Baldar, im Norden des Alteractals.\r\n==Friedhöfe==\r\nDie Frontlinien in diesem Tal sind in ständiger Bewegung. Die Gebietsgrenzen bewegen sich hin und her, während sie den Feinden in tödlichen Schlachten gegenüber treten. Doch um die Friedhöfe, wird am grimmigsten gekämpft. Die Friedhöfe im Alteractal sind äußerst wertvolle Gebiete und lebenswichtig für den Einfluß im Tal. Beide Seiten, die [[Horde]] und die [[Allianz]], kämpfen verbissen um diese geheiligten Stätten.\r\n===Eisschwingenhöhle===\r\nSüdwestlich von Dun Baldar befinden sich die Eisschwingenhöhlen. Tief in ihrem Inneren wird man ein Banner der Sturmlanzen finden.\r\n===Höhle der Wildpfoten===\r\nTief in der Höhle der Wildpfoten findet man ein Banner der Frostwölfe.\r\n===Eisbeißermine===\r\nIn den Minen des Alteractals ist noch weit mehr zu finden als bloßes Erz. So wie Kämpfe im Gebiet des Alteractals wüten, so wüten sie auch durch die Eisbeißer- und Eisenschachtminen. Beide bedeuten enorme Ressourcen an Mineralien und beide werden als Lager genutzt; daher ist es kein Wunder, dass sie so heiß begehrt sind. Die Eisbeißermine ist ein Vorratslager für die [[Horde]] und im entfernten Süden, tief in ihrem Territorium. Die Eisbeißermine war einst ein idealer Ort um zusätzliche Vorräte zu lagern, aber da die Kämpfe mit den [[Sturmlanzen]] nun härter werden, haben sie nicht immer die notwendigen Soldaten über, um sie an der Mine zu positionieren und diese zu bewachen. Daher fällt die Kontrolle über diese Mine oft an die [[Allianz]] oder an Untergrundvölker.\r\n===Eisenschachtmine===\r\nBevor die Schlacht begann, lagerten die [[Zwerge der Sturmlanzen]] ihre Vorräte für Dun Baldar in der Eisenschachtmine. Die [[Troggs]], die dort hausten, waren kein Problem solange sie Ersatztruppen hatten, die die Mine bewachen konnten, aber da sie nun gegen die [[Horde]] kämpfen, können sie sie nicht mehr kontrollieren. Die Eisenschachtmine liegt tief im Territorium der [[Allianz]], und die Kontrolle über die Mine ändert sich so oft wie neuer Schnee in Alterac fällt.\r\n===Eisblutgarnison===\r\nDie [[Frostwölfe]] haben ihre Frontlinien und Basen allesamt vermint. Der Sprengmeister der Frostwölfe weiß alles über Landminen. Immerhin hat er alle Minen an den Frontlinien selbst verlegt. Solange er ausfällt, fallen auch seine Minen aus. Vermutlich befindet er sich in einem Turm, nahe der Eisblutgarnison.\r\n===Westturmstellung===\r\nDie [[Horde]] konnte die Schwadronskommandanten der [[Allianz]] gefangen nehmen. Es war eine wilde Himmelsschlacht, doch letztendlich hat die [[Horde]] die Zwerge geschlagen. Sie fielen wie Steine vom Himmel. Leider hat es auch viele der besten Piloten erwischt, als Sie die Burg Frostwolf angriffen.",},
			["Alter Belagerungsturm"] = { content = "Der '''Alte Belagerungsturm''' der [[Allianz]] befindet sich im Osten der Ehrenfeste auf der [[Höllenfeuerhalbinsel]]. Vor langer Zeit haben bei diesem Turm viele Krieger der Allianz ihr Leben gelassen. Doch ihr Banner wurde von einem Orc-Kommandanten namens [[Urtrak]] gestohlen und jetzt suchen [[Höllenorc]] Plünderer dort nach alten Nägeln und Alteisen. Hier findet man auch den Hexer [[Grillok Finsterauge]].",},
			["Alter Gott"] = { content = "#REDIRECT [[Alte Götter]]", redirect = "Alte Götter",},
			["Alter Serra'kis"] = { content = "Der '''alte Serra'kis''' ist ein riesiger [[Dreschadon]] und gilt als der geheime Boss in der [[Tiefschwarze Grotte|Tiefschwarzen Grotte]]. Serra'kis zu finden ist härter als der eigentliche Kampf, denn um ihn zu erreichen, muss man in das Wasser um das [[Mondschrein Sanktum]] tauchen und unter die linke Seite der Ruinen schwimmen.",},
			["Alte Götter"] = { content = "Die '''Alten Götter''' herrschten über die junge Welt [[Azeroth]] bevor die [[Titanen]] diese Welt erreichten. Sie waren von unsagbarer Grausamkeit besessen, und kannten nichts als Tod und Zerstörung. Als die [[Titanen]] auf ihrer Mission, das Universum zu ordnen, diese junge Welt erreichten, kämpften sie gegen die Diener der Alten Götter: [[Ragnaros]], der Feuerlord; [[Therazane]], die Steinmutter; [[Al'Akir]], der Windlord; und [[Neptulon]] der Gezeitenjäger und zuletzt gegen die Alten Götter selbst. Nach einem langen Krieg gingen die [[Titanen]] schliesslich siegreich hervor, und begannen damit, die Welt von [[Azeroth]] neu zu formen. \r\n==Verbleib==\r\n* Einer wurde getötet. Seinen Leichnam kann man an der [[Dunkelküste]] bestaunen in der [[Meistergleve]]. \r\n* Drei der Alten Götter wurden von den [[Titanen]] tief unter die Erde verbannt, wo sie den Rest ihrer einstigen Macht behielten, allerdings scheinbar ohne Möglichkeit, das Leben auf der Oberfläche zu beeinflussen. Jedoch gelang es den Dreien den großen, ehrenwerten [[Drachen]]aspekt [[Neltharion]] zu korrumpieren, welcher die mächtige [[Drachenseele]], später auch [[Dämonenseele]], erschuf. Die Götter wollten diese verwenden, um ihre Freiheit wieder zu erlangen. Allerdings konnte [[Neltharion]] die [[Dämonenseele]] retten und an einen unbekannten Ort bringen. \r\n* Der fünfte Gott, [[C'Thun]], wurde in der Gegend besiegt, die heute als [[Silithus]] bekannt ist. In diesem Kampf fiel auch einer der [[Titanen]]. Es wurde lange Zeit angenommen, dass [[C'Thun]] tot sei, allerdings ist nun bekannt, dass er von den [[Qiraji]] am Leben gehalten wurde (über Tausende von Jahren) und sie ihn als ihren neuen und einzigen Gott verehrten, und sie ihm einen grossen Tempel in ihrer Hauptstadt errichteten. \r\n* Einer der Alten Götter mit Namen [[Yogg-Saron]] taucht in der Erweiterung [[Wrath of the Lichking]] auf, er befindet sich in [[Nordend]], tief unter den [[Grizzlyhügel]]n. \r\n==Die Anzahl der eingesperrten Alten Götter== \r\nEs gibt verschiedene Quellen zur Anzahl der eingesperrten Alten Götter: \r\n* Das Warcraft III Handbuch behauptet, dass '''fünf''' Alte Götter unter der Welt angekettet wurden. \r\n* Laut der „[[Krieg der Uralten]]“ Trilogy gibt es '''drei''' Alte Götter, die noch leben, eingesperrt und ankettet von den [[Titanen]] tief unter der Oberfläche von [[Azeroth]]. \r\n* Laut „Die Alten Götter und die [[Ordnung auf Azeroth]]“, wurden '''vier''' Alte Götter unter der Welt eingesperrt. Das könnte vielleicht mit der \"[[Krieg der Uralten]] - Trilogy“ abgestimmt werden, wenn es den gefallenen [[C'Thun]] in der Zahl der eingesperrten Götter beinhalten würde.\r\n===Tirisfal===\r\nEs ist möglich, dass einer der eingesperrten Alten Götter unter [[Tirisfal]] ist, denn als die [[Hochelfen]] erstmals auf dem [[Lordaeron]]er Kontinent landeten, begegneten sie einer fremden Kraft. Sie drangen weiter ins Inland und gründeten eine Siedlung im ruhigen [[Tirisfal]], doch nach ein wenigen Jahren, begannen viele von ihnen wahnsinnig zu werden. Es wurde die Theorie aufgestellt, dass etwass böses unter diesem besondere Teil der Welt schlief, aber die Gerüchte wurden nie bewiesen. \r\n===Mahlstrom===\r\nEin andere Theorie ist, dass einer der Alten Götter im [[Mahlstrom]] eingesperrt ist, wo er die [[Naga]] befehligt. Die [[Naga]] werden von der Monstrosität geführt, die einmal [[Königin Azshara]] war, und sie wurden bei der Entstehung des [[Mahlstrom]] während der Spaltung der Welt durch die Alten Götter aus ihren Nachtelfischen Formen mutiert. Der Warcraft-Roman „Tag des Drachen“ erwähnt eine Kreatur, die als „Der Manta“, Behemoth der Tiefe, bekannt ist. [[Krasus]] sagt, dieser wäre „zehn mal so groß und so stark wie ein Drache.“ Es wurde mindestens ein Jahrhundert vor den Ereignissen im „[[Tag des Drachen]]“ getötet. Es ist möglich, dass dieser Manta irgendwie mit den Alten Göttern und den [[Naga]] verbunden ist.\r\n===Teldrassil===\r\nEs ist möglich, dass einer der drei unter [[Teldrassil]] eingesperrt ist, aufgrund der rapiden Verseuchung des neuen Weltenbaums, die zu schnell ist, um nur die Tatsache zu sein, dass er nicht von den Drachen gesegnete wurde. \r\n===Smaragdgrünen Traum===\r\nEinige haben spekuliert, dass ein oder mehrere Alte Götter für den „Alptraum“ im [[Smaragdgrüner Traum|Smaragdgrünen Traum]] verantwortlich sein könnten. Da in der Questreihe für das [[Ahn'Qiraj]] Zepter [[Malfurion]] Sturmgrimm erzählt, dass ein Alter Gott „wie der Eine, den du zu bekämpfen versuchst “ (also so ein Alter Gott wie [[C'Thun]]) den [[Smaragdgrüner Traum|Smaragdgrünen Traum]] korrumpiert. Ebenso gibt [[Eranikus]] während der Begegnung mit ihm den Hinweis, dass der eine, dem er dient, ein Alter Gott ist. \r\n===Frostthron===\r\nEin anderer Streitpunkt ist, dass niemand mit Sicherheit weiß, wie viele der Alten Götter noch existieren. Aufgrund seiner starken Ähnlichkeit zu [[C'Thun]], glauben viele, dass der [[Vergessene]] aus „[[Warcraft III - The Frozen Thron]]“ ein Alter Gott war. Der Vergessene wurde von [[Arthas]] getötet und jetzt, wo [[C'Thun]] getötet wurde, würden nur zwei Alte Götter bleiben. Wenn einer durch bestätigtes Im-Spiel Wissen den [[Smaragdgrüner Traum|Smaragdgrünen Traum]] korrumpiert, bleibt nur ein Ort unbekannt. Wenn dem so ist, dann werden viele der anderen Gebieten, von denen spekuliert wird, dass sie von einem Alten Gott verdorben werden, tatsächlich durch eine andere, unbekannte Wesenheit korrumpiert.\r\n==Zusammenfassung==\r\nAus dem Wissen können wir dann annehmen dass: \r\n* 1: Einer ist tot in der [[Meistergleve]]. Gott Nr.1 ist im NW von [[Azeroth]] \r\n* 2: Einer ist noch eingesperrt in [[Tirisfal]]: der große leere Raum im Westen der Karte kennzeichnet den Ort einer zukünftigen Instanz. Gott Nr.2 ist im NO \r\n* 3: Einer ist [[C'Thun]]. Nr.3 im SW \r\n* 4: Einer ist [[Yogg-Saron]].\r\n* 5: Einer korrumpiert den [[Smaragdgrüner Traum|Smaragdgrünen Traum]]. (Seine körperliche Form kann im SO von [[Azeroth]] liegen, wenn er nicht der Eine unter dem [[Mahlstrom]] oder [[Tirisfal]] ist. Es würde Sinn machen, dass der Fünte im SO ist, obwohl das nur Spekulation ist)",},
			["Alte und mächtige Böse"] = { content = "Diese Wesen haben eine auffallende Ähnlichkeit zu [[C'Thun]]. Die [[Arakkoa der Sketh'lon]] versuchten im [[Schattenmondtal]] beim [[Basislager der Skethlon]], in der Nähe der [[Hand von Gul'dan]], eines dieser Wesen zu beschwören. Leider ist ansonsten nichts über sie bekannt.",},
			["Altstadt"] = { content = "Die '''Altstadt''' ist ''[[Sturmwind]]s'' historischstes Stadtviertel. Teile stammen noch aus Zeiten vor dem Wiederaufbau der Stadt, nachdem sie von den Orcs im [[ersten Krieg]] fast vollständig vernichtet wurde. \r\n==Beschreibung==\r\nKriminalität ist ein großes Problem der Altstadt. Hier lebt das einfache Volk. Dennoch lieben die Bürger Sturmwinds die Altstadt und dessen einzigartigen Charme, den sie versprüht. Die Altstadt grenzt im Südwesten an den [[Handelsdistrikt]], im Nordwesten an den [[Zwergendistrikt]] und im Norden an die [[Burg Sturmwind]]. Ein sehr markantes Merkmal sind die rot geschindelten Dächer der Häuser.\r\n===Zum Pfeifenden Schwein===\r\nDie Altstadt beherbergt die renommierte Taverne \"''[[Zum Pfeifenden Schwein]]''\". Das Ambiente ist rustikal.\r\n===Kasernen===\r\nAm Rande der Altstadt befinden sich die Kasernen, dazu gehören die [[Kommandozentrale]], die [[Halle der Champions]] und das Hauptquartier des [[SI:7]], Sturmwinds Assassinengilde. Hier werden Sturmwinds [[Krieger]] und [[Schurke]]n trainiert und ausgebildet.\r\n===Händler für Gerechtigkeitsmarken und Ehrenabzeichen===",},
			["Altvater Winter"] = { content = "'''Altvater Winter''' ist der Verkünder des [[Winterhauchfest]]es. Er besucht zur Winterzeit die Städte [[Eisenschmiede]] und [[Orgrimmar]] – dank der freundlichen Unterstützung von [[Kokelwälder]] – und bringt die Einwohner in Feierstimmung für das Winterhauchfest. Wenn man über das Jahr brav war, wird man am Tag dieses Festes vom Altvater wunderbare Leckereien erhalten. Man sollte außerdem darauf achten, sich mit Leckereien für die einzudecken, die ebenfalls in dem Jahr brav waren. Altvater Winter hat mit großzügiger Unterstützung von Kokelwälder für jeden auch Geschenke unter den Weihnachtsbaum von Eisenschmiede oder Orgrimmar gelegt. Allerdings macht ihn diese Aufgabe sehr hungrig und er verlässt sich auf Abenteurer, um ihn mit seiner täglichen Ration an Milch und Leckereien zu versorgen.",},
			["Alzzin der Wildformer"] = { content = "'''Alzzin der Wildformer''' ist ein [[Satyr]] im Wucherborkenviertel von [[Düsterbruch]].",},
			["Alzzin der Wildformer"] = { content = "'''Alzzin der Wildformer''' ist ein [[Satyr]] im Wucherborkenviertel von [[Düsterbruch]].",},
			["Am'jut"] = { content = "'''Interpretationsquelle:''' [[Anduri Stamm]] \r\n'''Am'jut – Der Totenfresser''' ist das Schicksal, welches den unehrenhaften und schlechten [[Troll]]en blüht, sollten sie vor dem Totengericht nicht bestehen. \r\nSein Kopf ist der eines Krokodils mit mehreren Zahnreihen, sein Rumpf der eines Tigers und sein Hinterteil das eines Flusspferds. Er frisst die Geister der Toten und verhindert damit, dass sie zur Mutter Schlange zur Insel [[Jah]] kommen. Gefressene Seelen werden zu bösen Rachegeistern, welche die Lebenden heimsuchen.",},
			["Am'mental"] = { content = "Die meisten Überlebenden des Absturzes der [[Exodar]] findet man im Westen und Nordwesten des Am'mentals auf der [[Azurmythosinsel]], aber der Absturz hat alle im gesamten Tal verstreut. Die überlebenden [[Draenei]] haben sehr unter der Strahlung der Kraftkerne der [[Exodar]] gelitten, doch die verstrahlten Kristalle haben auch der Umwelt verheerenden Schaden zugefügt. Die deutlichste Auswirkung ist das Auftauchen merkwürdiger Kreaturen, die anscheinend in ihrer Nähe wie Pilze aus dem Boden schießen. \r\nDie Am'menfelder im Westen des Am'mentals sind das wichtigste Vermehrungsgebiet der einheimischen [[Peitscher]]population. Doch man befürchtet, dass sich die [[Peitscher]] auf Grund des verseuchten Grundwasserspiegels nicht mehr fortpflanzen können\r\nDer Am'menfluss trennt das Am'mental von der restlichen [[Azurmythosinsel]]. Schnapperschwärme bewohnen den Fluss zahlreich.",},
			["Aman'Thul"] = { content = "'''Allgemeines'''\r\nAman'Thul ist der älteste und weiseste der [[Titanen]]. Er ist der Führer des [[Pantheon]], Bruder von [[Sargeras]] und Gemahl von [[Eonar]], der Lebensbinderin. Aman'Thul beherrscht das [[Pantheon]] - den Titanischen Hohen Rat. Er und seine Art erschaffen Leben und Ordnung auf zahllosen Welten über dem Großen Dunkel. Auf [[Azeroth]], gesegnete Aman'Thul [[Nozdormu]], den [[Drachen]]aspekt, mit der Kraft über die Zeit von [[Azeroth]]s unzähligen Zeitpfaden und das Schicksal zu wachen, das die Unversehrtheit seiner Zeitlinien schützt.\r\n'''Aussehen'''\r\nSeine metallische Haut ist Platinum und seine Augen glühen gelb. Seine Hand hält einen großen Stab mit einem Blitzsymbol darauf und Elektrizität fließt um den Stab.Der Name des Stabes ist [[Orodur]]. Er hat langes Haar und einen Bart, der bis zu seiner Taille reicht.",},
			["Amani"] = { content = "==Geschichte==\r\nLange vor der Großen Teilung entstand das Imperium der Amani, benannt nach dem mächtigsten Stamm der [[Waldtrolle]] dieser Zeit. Außerdem kann dieser Stamm mit Stolz [[Zul'jin]] zu seinen Mitgliedern zählen. Trotz seines Verschwindens nach dem Zweiten Krieg bleibt [[Zul'jin]] der berühmteste und am meisten respektierte Troll aller Zeiten. Nachdem das Imperium der Amani durch die [[Trollkriege]] zerschlagen wurde, siedelten die meisten [[Waldtrolle]] in einem komfortablen Abstand von [[Quel'Thalas]]. Die Amani betrachteten solche Sicherheitsvorkehrungen jedoch mit Hohn und bezeichneten sie als Feigheit. Bedrängt durch die Magie der [[Hochelfen]] verlor [[Zul Aman]] viel von seiner einstigen Größe, aber der Stamm der Amani blieb am östlichen Rand des verzauberten Königreiches verschanzt. \r\nAls [[Arthas]] während des Dritten Krieges die [[Geißel]] nach [[Quel'Thalas]] führte, betrachteten die Amani das daraus resultierende Gemetzel mit Wohlgefallen. Ohne zu Zögern begannen die [[Trolle]] eine Reihe von Angriffen gegen [[Hochelfen]]siedlungen im [[Immersangwald]]. Sie sahen überrascht, dass die wenigen überlebenden [[Hochelfen]] anscheinend stark geschwächt waren und den Trollen nur wenig Widerstand entgegensetzen konnten. Die Amani eroberten einen bedeutenden Teil des Waldes, bevor der Elfenprinz [[Kael'thas]] Sonnenwanderer [[Quel'Thalas]] erreichte. \r\nDer Prinz sammelte alle überlebenden [[Hochelfen]], die er finden konnte, und gab ihnen einen neuen Namen - die [[Blutelfen]]. Die [[Blutelfen]] entzogen den Wesen in ihrer Umgebung Magie und schienen dadurch neue Kraft zu gewinnen. Schlimmer noch, [[Kael'thas]] organisierte Streitkräfte, die sich als sehr effektiv gegen die Verbände der Amani erwiesen, selbst dann noch als [[Kael'thas]] und seine stärksten Krieger [[Quel'Thalas]] verließen, um anderswo gegen die [[Geißel]] zu kämpfen. \r\nIn letzter Zeit sind bei den [[Blutelfen]] Anzeichen von intensivem magischen Training und verstärkter Magieanwendung zu erkennen. Die Zauber der Elfen haben an Kraft gewonnen, und Teile von [[Quel'Thalas]] wurden wieder aufgebaut. Doch am ärgerlichsten für die [[Trolle]] ist, dass die [[Blutelfen]] begonnen haben, den [[Immersangwald]] zurückzuerobern. Trotzdem kämpft der Stamm der Amani weiterhin mit aller Macht gegen die [[Blutelfen]], da deren geringe Zahl nicht für lange Zeit sowohl gegen die Trolle im Osten als auch gegen die Geißel im Süden bestehen kann.\r\n==Hintergrund==\r\nRuinen und Stufen Pyramiden bleiben aus den Tagen des [[Zul Aman]]-Imperiums. Die [[Waldtrolle]] kontrollierten den Großteil von [[Lordaeron]] und nannten ihr Imperium [[Zul Aman]]. Was die anderen Rassen jetzt als [[Zul Aman]] ansehen, war in jener Zeit ihr Machtzentrum und ist der einzige Teil, der von dem einst so großen Imperium bleibt. Die [[Trolle]] hier sind extrem gewaltsam, wenn sie ihre Länder beschützen, da die [[Hochelfen]] und [[Menschen]] sie beinahe in den Untergang getrieben haben und es nicht viel gibt, was sie übrig gelassen haben. Interessant ist, dass die Trollischen Frauen hier ebenso als geschickte Jäger betrachtet werden.\r\n==Amani Imperium==\r\nEin großes Imperium der [[Waldtrolle]] mit unvorstellbarer Macht in der Vorzeit. Ihr Imperium wurde in den Trollkriegen zerschmettert und sollte nie wieder aufsteigen. Zusammen mit den [[Gurubashi]] war das Amani Imperium eines der herrschenden Imperien der [[Trolle]], vor dem Aufstieg der Kaldorei zu Macht. Anscheinend fiel es bereits vor dem Ansturm der [[Nachtelfen]] in den Niedergang. Anders als die [[Gurubashi]] [[Dschungeltrolle]] jedoch, schafften es ihre nördlichen \"Amani\"-Vettern, nach der Trennung der Welt die regionale Macht zu bleiben. Als die [[Hochelfen]] das erste Mal verbannt wurden und in [[Lordaeron]] landeten, gerieten sie in gewaltsame Konflikte mit den [[Waldtrolle]]n, die sie als Beschmutzung ihres Heimatlandes ansahen. \r\nIn den Zeiten der Gründung von [[Quel'Thalas]], war das Amani Imperium das mächtigste Imperium im Osten und sie hielten noch viel des nördlichen [[Lordaeron]]s in ihrem territorialen Griff. Schließlich schlossen sich die [[Hochelfen]] mit den [[Menschen]] von [[Arathi-Hochland|Arathor]] zusammen und besiegten die [[Waldtrolle]] in einer gewaltigen Schlacht, die das Ende des Imperiums signalisierte. Die Amani würden sich nie erholen, um ihr Land wieder jenseits ihrer Heimatprovinz [[Zul Aman]] auszudehnnen, aber sie sind weiterhin ein Feind der [[Menschen]] und Elfen seit tausenden von Jahren und weiterhin eine bedeutsame Bedrohung, sogar nach den Zeiten des Zweiten Krieges, als sie sich mit der Horde zusammen schlossen.\r\n==Riten und Religion==\r\nWie andere [[Trolle]] auch praktizieren die Amani [[Voodoo]] Magie sowie Schamanismus und Priestermagie. Sie verehren ebenso eine Schlangengöttin namens [[Ula'tek]], die von Venoxis in [[Zul Gurub]] angerufen wird. Eine kleine Minderheit von Waldtrollen verehrt ebenso [[Hakkar]], obwohl seine Kult nie die Vorherrschaft erlangte, die sie unter den [[Dschungeltrolle]]n genoss. Man hat gehört, dass die Amanitrolle die Herzen ihrer Feinde essen, um deren Stärke zu stehlen. \r\n==Dörfer==\r\nDie [[Blutelfen]] herrschen nicht über solch riesige Königreiche wie die [[Menschen]] oder die [[Orcs]]. Beinahe alles, was ihnen noch von ihren Ländereien in [[Azeroth]] geblieben ist, ist der [[Immersangwald]]. Bis die Elfen die [[Scherbenwelt]] erreichen können, um ein neues Zuhause zu finden, müssen sie das Wenige, das ihnen geblieben ist, um jeden Preis verteidigen. Doch ihre Nachbarn, die Amani[[trolle]], haben allerdings eine gänzlich andere Auffassung darüber, wem dieses Land gehört. Die Amani und die Sin'dorei pflegen seit langem eine gegenseitige Ablehnung und offenkundige Feindseligkeit. Das hält die Schmiede der Sin'dorei jedoch nicht von der Bewunderung der Arbeit eines Handwerkskollegen ab.\r\n* [[Agol'Watha]]\r\n* [[Dorf der Bleichborken]]\r\n* [[Dorf der Bruchhauer]]\r\n* [[Fels'gor]]\r\n* [[Hiri'Watha]]\r\n* [[Jintha'Alor]]\r\n* [[Shaol'Watha]]\r\n* [[Shadra'Alor]]\r\n* [[Tor'Watha]]\r\n* [[Zeb'Watha]]",},
			["Ambossar"] = { content = "Ambossar liegt im Nordosten des [[Eisklammtal]]s in [[Dun Morogh]] und ist mehr eine steinerne Festung als ein Ort. Es ist eine Siedlung, die in den Berg gebaut wurde. Neben Ambossar finden sich hier fast nur Lager von Holzfällern und Jägern. Benannt ist sie nach [[Modimus Ambossar]], dem ehemaligen Zwergenkönig vom [[Ambossar Klan]].\r\n==Personen==\r\n* '''Durnan Pelznaht''' geht nichts über ein heißes Morgengebräu an einem kalten Wintertag, um einem das Herz zu wärmen.\r\n* '''Felix Windenbolz''' hat in seiner Hast, der Strahlung von [[Gnomeregan]] zu entkommen, all sein ganzes Hab und Gut und auch seine Werkzeuge verloren. Die [[Trolle der Frostmähnen]] haben seine Truhe, seine Kiste, und seinen Bolzeneimer gestohlen und alles in ihre Lager südwestlich von Ambossar mitgenommen. Er ist nur leider kein Abenteurer, um seine Dinge zurückzuholen.",},
			["Ambossar Klan"] = { content = "Die [[Zwerge]] vom Klan Ambossar waren einer der drei alten Zwergen Klans: [[Bronzebart]], [[Wildhammer]] und Ambossar. Sie waren unter anderem für ihre Hammer- und Axt-Schmiedekunst berühmt.\r\nMit [[Gombrim Ambossar]] bestieg der erste König aller [[Zwerge]] den Thron von [[Eisenschmiede]] im Jahre —1,320. Der Letzte König aus dem Klan Ambossar war König [[Modimus Ambossar]]. Streiterien um seine Thronfolge brachen nach seinem Tod unter den drei Klans aus und gipfeln im Jahr —230 im [[Krieg der drei Hämmer]]. Seither stellt der [[Bronzebart Klan]] den König.\r\nHeutzutage findet man so gut wie keine lebenden Mitglieder dieses Klans mehr. Nur noch die alte Festung [[Ambossar]] in [[Dun Morogh]] erinnert daran.\r\n==Persönlichkeiten== \r\n* [[Gombrim Ambossar]]\r\n* [[Modimus Ambossar]]",},
			["Amnennar der Kältebringer"] = { content = "'''Amnennar der Kältebringer''' ist ein [[Lich]], der die [[Hügel der Klingenhauer]] beherrscht. Er war einst ein hoher ,orcischer [[Hexenmeister]] und folgte [[Ner'zhul]] durch die Dimensionsportale. [[Kil'jaeden]] zerriss ihn und Amnennar wurde als [[Lich]] wiedergeboren.Er verfügt über eine direkte telepathische Verbindung zu [[Ner'zhul]] und die Loyalität dieses [[Lich]] ist unerschütterlich.",},
			["An'chras"] = { content = "'''Interpretationsquelle''': [[Anduri Stamm]]\r\n* Ideale: Jagd, Krieg, Blut \r\n'''An'Chras – Der Raptor''' sieht es als Herausforderung, größere und stärkere Gegener anzugehen. Der Raptor ist der blutrünstigste und gerissenste Kämpfer im Dschungel, und deshalb gefürchtet. \r\nEr sucht nicht immer den offenen Zweikampf, sondern ist ein Meister der Taktik und pirscht sich gern an sein Opfer heran, um dann aber mit wildem Geschrei aus dem Hinterhalt loszustürmen. \r\nEinen heiligen Raptor zu erlegen ist in [[Dschungeltrolle|Dschungeltrollstämmen]] ein verbreiteter Ritus für Jungtrolle, der den Übergang vom [[Welpe]]ndasein zur Reife darstellt. \r\nDie Jagd hat für die Trollstämme schon immer eine große Bedeutung gehabt, da sie das Überleben des Stammes sichert. Die Jagd wurde aber von jeher nicht nur als Notwendigkeit, sondern auch als Kunst gesehen und die fähigsten Jäger genießen stets den Respekt ihres Stammes und gelten als vom Raptor gesegnet. \r\nDa aber auch Kriege gegen andere Trollstämme und viele andere Feinde zum Alltag wurden, erweiterte sich die Vorstellung des Raptorgottes zum Gott des Krieges. Daher wird An'Chras auch von vielen Trollen gehasst, die die negativen Folgen von Kriegen zu spüren bekamen. Er steht für Blut und Zerstörung, für Raubzüge und für Tod. \r\nNachwievor wird er verehrt und man bringt ihm (Tier-)Opfer dar, um von ihm den Segen für eine erfolgreiche Jagd oder Schlacht zu erbitten. Man muss stark sein und auch Qualen und Strapazen erleiden können, um von An'Chras anerkannt zu werden und man sollte in der Verehrung vorsichtig sein. Er ist jähzornig und schnell wütend. Man weiß nie, ob man ihn nicht doch erzürnt hat mit zu banalen Opfergaben. Es ist schwer, seine Gunst zu erringen, hat man sie aber, ist man nahezu unbesiegbar. \r\nEs werden keine Altäre oder Heiligtümer für ihn gebaut. Der Raptor hat kein Zuhause, er liegt immer auf der Lauer.",},
			["An'daroth"] = { content = "=== An'daroth===\r\nDie [[Blutelfen]] haben einige Schwierigkeiten mit einer Gruppe von [[Nachtelfen]], die erst kürzlich eine der naheliegenden Inseln besetzt hat. Sie haben ein kleines Lager an dem alten hochelfischen Leyliniennexus, An’daroth, im Nordwesten aufgeschlagen. Es gibt einen kleinen schlammigen Pfad, der hinter der Todesschneise dorthin führt. An'daroth liefert für die Spionage-Pläne der [[Nachtelfen]] nicht genügend Energie, um einen [[Mondkristall]] dort anzubringen. Keltus Dunkellaub hat vor, die Spione der Schildwache anzugreifen, möchte seine treue Begleiterin Tuschel aber als Vorhut vorausschicken. Sie braucht lediglich eine Fährte, die sie auf sie hetzt.",},
			["An'owyn"] = { content = "An'owyn ist ein alter hochelfischer Leyliniennexus in den Geisterlanden, auf den ein nachtelfischer [[Mondkristall]] gesetzt wurde. Die Mondkristalle der Nachtelfen sind nichts anderes als Seherartefakte und sie wollen damit die Blutelfen ausspionieren. Durch die Pläne der Nachelfen aber haben die Sin'dorei einen ungefähren Eindruck darüber gewonnen, wie diese Mondkristalle funktionieren und sie sollten in der Lage sein, sie zu deaktivieren. Allerdings sind sie gesichert, um eine ungewollte Abschaltung zu verhindern. Man muss sich die Kontrollkugel von einem der Nachtelfen beschaffen und sie mit den Mondkristallen benutzen, um die Durchführung der Pläne zu verhindern.",},
			["An'she"] = { content = "An'she bezeichnet in der Sprache der [[Tauren]], die Sonne, welches ein Auge der [[Erdenmutter]] ist.",},
			["An'telas"] = { content = "An'telas ist ein alter hochelfischer Leyliniennexus und liegt östlich von [[Tristessa]], auf dem südlichen Hang des Sonnenhügels, nordöstlich vom [[Sanktum der Sonne]]. Magister Sylastor führt dort diverse Experimente mit den Energien des Leyliniennexus durch, um potentielle Verwendungsmöglichkeiten im Kampf gegen die [[Geißel]] zu finden.",},
			["Anachoret"] = { content = "#REDIRECT [[Draeneipriester]]", redirect = "Draeneipriester",},
			["Anachronos"] = { content = "Anachronos der Uralte ist ein Bronzener Drache in den [[Höhlen der Zeit]] in [[Tanaris]]. Er ist [[Nozdormu]]s Kind und Erbe. Anachronos willigte im [[Krieg der Sandstürme]] ein, den [[Bronzener Drachenschwarm|Bronzen Drachenschwarm]] gegen die plündernden [[Qiraji]] zu beteiligen und [[Fandral Hirschhaupt]] zu unterstützen, nachdem die [[Qiraji]] die [[Höhlen der Zeit]] attackiert hatten.\r\nEs ist tausend Jahre her, seitdem man ihm den einen Splitter des [[Szepter der Sandstürme|Szepters der Sandstürme]] anvertraut hat. Jetzt, in seiner finstersten Stunde soll jemand erscheinen, um ihn davon zu entlasten... aber was wäre eine Tragödie ohne Grausamkeit? [[Nefarius]] besitzt nun den Szeptersplitter. Und er hat vor den Splitter zu zerstören.",},
			["Anasterian"] = { content = "#REDIRECT [[Anasterian Sonnenwanderer]]", redirect = "Anasterian Sonnenwanderer",},
			["Anasterian Sonnenwanderer"] = { content = "==Geschichte==\r\nAls Nachfahre von [[Dath'Remar]] Sonnenwanderer regierte König Anasterian die [[Hochelfen]] während der letzten Phase der [[Trollkriege]], als eine Niederlage allmählich unausweichlich schien. Die Elfen waren erheblich in der Unterzahl und verloren ständig an Boden, während die Verluste immer weiter stiegen. Selbst ihre mächtigsten Zauber halfen nur wenig.\r\n===Seltsames Bündnis===\r\nAnasterian verfiel auf einen verzweifelten Plan. Seine Kundschafter hatten ihm von einem [[Menschen]]reich namens [[Arathor]] berichtet, das vor kurzem im Süden gegründet worden war. Ein Stamm hatte sich zur Anführerschaft emporgeschwungen, und zwar auf eine neue, denkbar einfache Weise: Er bot all jenen Amnestie an, die er besiegte. Dass eine solche Strategie bei den [[Menschen]] als neu galt, bewies nicht nur, wie jung ihr Volk doch noch war, sondern auch, dass die [[Menschen]] gewillt waren, durch weitsichtigen Pragmatismus eine Position der Stärke aufzubauen. \r\nObwohl die [[Menschen]] keine [[Magier]] hatten, war Anasterian angesichts der zahlenmäßig starken Bevölkerung von [[Arathor]] doch sicher, dass sich darunter auch [[Menschen]] mit magischen Talenten finden lassen sollten. Sie bräuchten nur etwas Ausbildung, um im Kampf nützlich zu sein. Daher schickte er eiligst Botschafter in die Südlande aus. König Thoradin von [[Arathor]] begrüßte die Gesandten überrascht, doch mit vorsichtiger Höflichkeit. Er hatte schon seit Monaten Gerüchte über die Probleme der [[Hochelfen]] gehört, doch er hätte nie vermutet, dass die [[Trolle]] wirklich eine ernsthafte Bedrohung darstellen könnten. Die kriegsmüden Elfen warnten den König, dass die Trollarmeen gewaltig seien. Wenn [[Quel'Thalas]] fiele, würden die [[Trolle]] als nächstes mit Sicherheit [[Arathor]] belagern. \r\nDer König misstraute der [[Magie]], konnte aber nicht leugnen, dass die Elfen mit ihrer Warnung Recht hatten. Es folgten weitere Verhandlungen, bis Anasterian und Thoradin schließlich zu einer Übereinkunft kamen. Sofort danach trafen Elfenzauberer in [[Arathor]] ein und begannen, einer Gruppe von [[Menschen]] ihre Magie beizubringen. Einhundert [[Menschen]] lernten die Grundlagen der elfischen arkanen Geheimnisse; nicht mehr, als absolut nötig waren, um gegen die [[Trolle]] zu kämpfen. Neben diesen neuen Magiern sandte Thoradin auch seine Armeen an die Front. Zusammen errangen [[Menschen]] und [[Hochelfen]] schließlich den Sieg über die [[Trolle]], die sich von dieser Niederlage niemals völlig erholten. Als sie sahen, dass [[Quel'Thalas]] vor der Vernichtung bewahrt war, leisteten die Elfen dem Reich [[Arathor]] und dem Königshaus von Thoradin einen Loyalitäts- und Freundschaftsschwur. Fortan lebten Menschen und Elfen mehr als zweitausend Jahre lang in Frieden und Eintracht nebeneinander.\r\n===Konflikte an den Grenzen===\r\nAls die [[Horde]] im Zweiten Krieg die [[Menschen]] angriff, hatten die [[Hochelfen]] eigentlich wenig Interesse, in diesen Konflikt hineingezogen zu werden. Doch sie fühlten sich an ihren Schwur gebunden, die [[Allianz]] von [[Lordaeron]] zu unterstützen, und besonders ihren Kommandeur, Lord [[Anduin Lothar]], den letzten Nachkommen des Königshauses von Arathi. Lothars Familie hatte den [[Hochelfen]] in den Trollkriegen zur Seite gestanden, und so schickte König Anasterian widerstrebend einen Trupp Soldaten und Zauberer, die an der Seite der [[Allianz]] kämpfen sollte. \r\nDoch schon bald sahen sich der König und sein Volk viel direkter betroffen. Truppen der [[Horde]] kämpften sich nach Norden vor, brandschatzten die Grenzlande von [[Quel'Thalas]] und metzelten viele [[Hochelfen]] nieder. Angewidert von der wahllosen Vernichtung des Lebens durch die [[Horde]] schlossen sich die [[Hochelfen]] offiziell der [[Allianz]] an und gaben all ihre Ressourcen für den Krieg frei. Schließlich besiegte die [[Allianz]] die [[Orcs]]. Die meisten von ihnen wurden zusammengetrieben und in Lagern interniert.\r\n===Steil abwärts===\r\nIn den Jahren nach dem Krieg zweifelten immer mehr [[Hochelfen]] am Wert der [[Allianz]]. Die Menschheit schien die [[Hochelfen]] zu brauchen, hatte aber ihrerseits wenig zu bieten, besonders jetzt, da viele Ressourcen der [[Allianz]] für die Kosten der Internierungslager eingesetzt wurden. \r\nSchließlich sagten sich die [[Hochelfen]] von der [[Allianz]] los. Anasterian machte die schwache Führung der [[Menschen]] direkt verantwortlich für die niedergebrannten Wälder im Grenzland von [[Quel'Thalas]]. König [[Terenas]] Menethil hielt dagegen, dass überhaupt nichts in [[Quel'Thalas]] überlebt hätte ohne die Hunderte tapferer [[Menschen]], die ihr Leben geopfert hatten, um das Elfenland zu verteidigen. Doch trotz seiner Versuche, wieder diplomatische Beziehungen herzustellen, entschlossen sich die Elfen, sich von der zerbröckelnden [[Allianz]] loszusagen. Damit leiteten sie zugleich die nachfolgende Loslösung von den Reichen [[Gilneas]] und [[Stromgarde]] ein. \r\nAnasterian war auch Jahre später noch an der Macht, als der Todesritter [[Arthas]] Menethil mit Truppen der [[Geißel]] in [[Quel'Thalas]] einfiel und den [[Sonnenbrunnen]] entweihte. Der König und die meisten seines Volkes wurden in der Schlacht von den Untoten hingemetzelt. Sein Sohn, Prinz [[Kael'thas]] Sonnenwanderer, war zur Zeit der Invasion in [[Dalaran]] und ist somit der letzte Überlebende der Königsfamilie. Der Schädel Anasterians, welcher von den Blutelfen unter der Führung seines Sohns mit in die Scherbenwelt genommen wurde, soll ein mächtiges Artefakt sein, was den Drachenschwärmen erlauben würde, den Sonnenbrunnen wiederherzustellen. \r\n'''Quelle''':",},
			["Andorhal"] = { content = "Andorhal war ein blühender Umschlagsplatz für [[Lordaeron]]s landwirtschaftliche Produkte. Es war die Kornkammer des Königreichs. Doch heute sind nur noch verfallene Ruinen von dem einstmals florienden Handelszentrum übrig, die von Untoten Skeletten, Zombies und schlimmeren heimgesucht werden. Die westlichen und nördlichen Straßen in die Stadt von Andorhal sind gut befestigt und die [[Geißel]] nutzt die Wachtürme von Andorhal, um die Bewegungen ihrer Truppen zu kontrollieren.\r\n===Zeitlinien===\r\nDie Zeitlinie in Andorhal wurde durch eine finstere Kraft verfälscht - wahrscheinlich durch die [[Geißel]]. [[Chromie]] vom [[Bronzener Drachenschwarm|Bronzenen Drachenschwarm]] versucht, das Verstreichen der Zeit hier in den Griff zu bekommen und den Schaden zu beheben, aber dazu benötigt sie Hilfe. Temporale Parasiten - Aas, das sich von den Strängen des veränderten Zeitflusses ernährt, sucht die Silos von Andorhal heim. Man kann sie nur an der blau pulsierenden Verzerrung erkennen. Sie behindern [[Chromie]]s Weissagungen. Der Raum in dem sich [[Chromie]] aufhält ist anders als der Rest von Andorhal, denn der [[Bronzener Drachenschwarm|Bronzene Drachenschwarm]] agiert auf verschiedene Weise und in vielen verschiedenen Zeitlinien. Um den in Andorhal angerichteten Schaden zu beheben, handelt er jetzt von einer anderen Zeitlinie aus, um die anderen nicht allzu sehr zu kontaminieren.\r\n==Geschichte==\r\nUm die Seuche des Untodes unter den ahnungslosen Bürgern des Königreiches zu verbreiten, ließ Totenbeschwörer [[Kel'Thuzad]] das dortige Getreide verseuchen und vom [[Kult der Verdammten]] in den nördlichen Gemeinden verteilen. Sein Plan ging voll und ganz auf. Durch die vergifteten Kornkisten wurden viele Dörfer fast auf der Stelle infiziert. [[Menschen]], die sich mit der Seuche ansteckten, starben und erstanden als willige Sklaven des [[Lichkönig]]s wieder auf. Die verzweifelten Verteidiger Andorhals, die keine Hoffnung auf Rettung sahen, steckten die Stadt in Brand. Prinz [[Arthas]], der Gerüchten aus den Nordländern nachging, konnte [[Kel'Thuzad]] schließlich in Andorhal stellen und töten. Die [[Paladine]] verteidigten fortan die Stadt und kämpften gegen die untoten Krieger der [[Geißel]]. Doch auch [[Arthas]] wurde durch das subtile Ränkespiel des [[Lichkönig]]s verdorben und kehrte als [[Todesritter]] nach Andorhal zurück, um [[Kel'Thuzad]]s sterbliche Überreste zu bergen. Er tötete die Paladine und besiegte in einem letzten Kampf seinen ehemaligen Lehrmeister [[Uther Lichtbringer]]. \r\n'''Quelle''': \r\n==Personen==\r\n* [[Araj der Beschwörer]]\r\n* [[Chromie]]\r\n* '''Jeziba''' - Jeziba der 'Bildhauer' ist ein Sterblicher im Gasthaus von Andorhal, so weise wie die Uralten und so geduldig wie die unbewegliche Erde. Er weist Freiwillige an, das [[Verzeichnis der Abtrünnigen]] zu lesen, um erleuchtet zu werden. Er kann die [[Beinplatten des chromatischen Widersetzers]] und die [[Brustplatte des Chromatischen Drachenschwarms]] schmieden.",},
			["Andre Feuerbart"] = { content = "'''Andre Feuerbart''' ist ein niederträchtiger Pirat der [[Südmeerfreibeuter]] in [[Tanaris]]. [[Sicherheitschef Bilgenritzel]] beim [[Dampfdruckpier]] hat ein Kopfgeld auf ihn ausgesetzt und läßt ihn aufgrund seiner gegen die Einwohner des Dampfdruckpiers und Gadgetzan gerichteten Verbrechen suchen.",},
			["Andron Gant"] = { content = "'''Andron Gant''' ist ein [[Verlassene]]r und anscheinend nicht ganz helle Kopf. Normalerweise hält er sich in [[Unterstadt]] auf, ganz in der Nähe des Apothekariums. Man vermutet, dass Andron dem [[Syndikat]] Unterstützung zuteil werden ließ. Offenbar sind die Lords von [[Alterac]] in den Jahren seit ihrem Verrat tief gesunken, doch er war redselig, als das Gespräch darauf kam, warum er die [[Schrifttafel von Markri]] von [[Jediga]] in [[Azshara]] haben wollte. Anscheinend wollen einige der Magier von Unterstadt die Arkanzauber studieren, die die [[Hochgeborene]]n benutzt haben. Sie glauben, dass ihnen diese Schrifttafel dabei helfen würde. Markri war sehr bewandert im Beschwören von Kreaturen, besonders von Elementaren.",},
			["Anduin Lothar"] = { content = "'''Anduin Lothar''' war der Champion der Garde von [[Azeroth]] und Oberbefehlshaber der Truppen der [[Allianz]]. Ihm zu Ehren steht das Monument der Erinnerung in der Mitte der Ehrenfeste auf der [[Höllenfeuerhalbinsel]]:\r\n==Geschichte==\r\nAnduin Lothar hatte seit jeher guten Kontakt zur Königsfamilie von [[Azeroth]] und war seit seiner Kindheit eng mit dem zukünftigen König [[Llane Wrynn]], sowie und [[Medivh]] befreundet. Zusammen entdeckten sie im [[Schlingendorntal]] eine mächtige [[Runenklinge]], die Medivh [[Quel'Zaram]] nannte und Lothar schenkte. Außerdem wurde er in recht jungem Alter in die Königliche Ehrengarde von [[Azeroth]] aufgenommen. \r\nNach seinem Ritterschlag und die Aufnahme in die „[[Bruderschaft des Pferdes]]“ zog Lothar aus, um das „[[Buch der Offenbarung]]“ zu suchen. Nachdem er das Buch an die Geistlichen in [[Nordhain]] weitergegeben hatte gab es eine neue Bedrohung, die der Champion des Königs abzuwenden hatte. In den Gegenden um den Schwarzen Morast wurden immer häufiger grünhäutige Monster gesichtet, die man [[Orcs]] nennt. Lothar führte seine Truppen in den Kampf gegen die Orcs, doch ihre Anzahl war schier zu groß und somit wurde das Land immer mehr verwüstet. Erschwerend kam für Lothar auch noch der labile Zustand seines Jugendfreundes [[Medivh]], der immer mehr in den Wahnsinn zu fallen schien und die Anwesenheit der Orcs kaum beachtete. Als sich dann herausstellte, dass Medivh in Wirklichkeit von [[Sargeras]], dem Anführer der [[Brennende Legion|Brennenden Legion]] besessen war missachtete Lothar den Befehl des Königs, nichts zu unternehmen, und machte sich mit einigen Soldaten (unter ihnen auch Medivhs Schüler [[Khadgar]] und die Halborcin [[Garona]]) auf nach [[Karazhan]], dem Turm Medivhs. Der Stoßtrupp drang tief in Medivhs Turm ein und Lothar tötete seinen Freund mit seinem Schwert [[Ashkandi]]. \r\nDoch obwohl mit [[Medivh]] der Schöpfer des großen Portals gestorben war kamen immer noch Horden von ihnen durch das [[Dunkle Portal]] und drängten gegen die Hauptstadt von [[Lordaeron]]: [[Sturmwind]]. Die [[Orcs]] hatten seit dem ersten Angriff dazu gelernt und waren unter einem Kriegshäuptling vereint. Als Sturmwind fiel scharrte Lothar die letzten Überlebenden um sich und floh übers Meer nach Lordaeron um die anderen Menschennationen von der Gefahr durch die Orcs zu warnen.\r\nIn König [[Terenas Menethil]] II. von [[Lordaeron]] und Admiral [[Daelin Prachtmeer]] von [[Kul Tiras]] hatte er Verbündete, die eine [[Allianz]] befürworteten. Lothar wurde zum Oberbefehlshaber der Allianz von Lordaeron denen neben Lordaeron, Kul Tiras und den Überlebenden von [[Azeroth]] auch [[Stromgarde]], [[Alterac]] und [[Dalaran]], sowie die [[Hochelfen]] von [[Quel'Thalas]] und die [[Zwerge]] von [[Khaz Modan]] und dem [[Nistgipfel]] angehörten. Außerdem wurde ihm der Titel „Lordregent von Azeroth“ verliehen. Der Krieg mit den Orcs verlief zunächst nicht gut; Baron [[Aiden Perenolde]] von Alterac hatte die Allianz verraten und Bauernaufstände und Attentate auf wichtige Allianzgeneräle angezettelt. Als die Orcs vor den Toren Lordaerons standen war es die Horde, die nun mit inneren Streitigkeiten zu kämpfen hatte: Die [[Orcs des Stormreaverklans]] hatten das [[Grabmal des Sargeras]] gefunden und ihr Häuptling [[Gul'dan]] zog nun seine Truppen ab um sich die Macht, die in dem Grab vermutet wurde einzuverleiben. [[Orgrim Schicksalshammer]], der orcische Kriegshäuptling folge ihm mit seinen Truppen und vernichtete den verräterischen Clan. \r\nLothar konnte sich diese Unstimmigkeiten zunutze machen und die Truppen der [[Allianz]] neu formieren. Der Gegenangriff trieb Schicksalshammers Truppen zurück, das Kriegsglück hatte sich gewendet. Stück für Stück gelang es der Allianz die [[Orcs]] zurück zu drängen, die Orcs flohen daraufhin nach [[Azeroth]]. Lothar und seine Truppen drängten die Orcs zu ihrer Bergfestung bei der [[Schwarzfelsspitze]]. Am Fuße des schwarzen Berges trafen Lothar und Schicksalshammer aufeinander und lieferten sich einen erbitterten Zweikampf, den Lothar aber nicht für sich entscheiden konnte. Lothar starb bevor die Schlacht um die Schwarzfelsspitze richtig begann. Man nahm [[Orgrim Schicksalshammer]] gefangen und zerstörte auch das Dunkle Portal durch das die [[Horde]] gekommen war.",},
			["Anduri-Stamm"] = { content = "==Die Geschichte der Anduri == \r\nDer Stamm der ehrenwerten Anduri ist einer der jüngeren Trollstämme und seiner Zuordnung nach am ehesten als ein Unterstamm der Darkspear zu betrachten. Er wurde gegründet von der [[Voodoo]]-Priesterin [[Rakna`zan]], einer abtrünnigen Darkspear deren Glauben an den reinen und guten Voodoo sie dazu brachte ihr Volk zu verlassen und Ihren eigenen Weg zu suchen. Dabei schlossen sich ihr verstoßene, stammlose und ausgestoßene Trolle auch anderer Stämme an. Der Stamm der Anduri basierte also von seinem Gründungszeitpunkt an nicht auf Blutbanden.\r\nDas erste Dorf der Anduri wurde tief im Dschungel von Stranglethorn gegründet. Man schottete sich konsequent von anderen [[Trolle|Trollstämmen]] und deren Misstrauen sowie Kriegslüsternheit ab. Rakna`zan strebte ein Handelsbündnis mit dem nahe gelegenen [[Beutebucht|Booty Bay]] an. Der Stamm verfügte über weitreichendes Wissen im Bereich des [[Voodoo]]-Mixens. Dieses Können verschaffte Rakna`zans Stamm Ansehen, Respekt und Wohlstand. Die Goldenen Zeiten der Anduri währten mehr als 30 Jahre lang. Im 31sten Jahr ihrer Herrschaft brachte Rakna`zan ihren Sohn [[Vanaka'zin]] zur Welt. In seinen ersten Lebensjahren erblühte das Kind durch die Liebe und Macht seiner Mutter. \r\nEines Nachts jedoch kamen menschliche Wegelagerer auf der Suche nach dem inzwischen zu einer lokalen Legende gewordenen Reichtum der Anduri in das Dorf, wurden bei ihrer Spähaktion entdeckt und lösten einen wilden Kampf aus. Einige von ihnen fanden während dieser turbulenten Minuten das Kind Vanaka'zin, änderten ihren Plan und entführten den Sohn der Stammesherrin. Danach blieben sowohl die geflohenen Plünderer als auch Vanak'zin verschwunden, so dass selbst die Dschungelläufer der Anduri keine Spuren von ihnen fanden. Rakna`zan war nicht mehr dieselbe, sie brach alle Bündnisse und schottete den Stamm erneut ab, bis sie wenige Jahre später starb. \r\n10 Jahre nach dem Raub tauchte Vanaka'zin wieder auf, halb verhungert und entstellt, und taumelte in ein ihm fremdes Dorf, von dem man ihm gesagt hatte, es sei das Dorf seiner Mutter. \r\nDie Aufgabe, ihr Erbe weiter zu führen, nahm er beherzt auf sich. Vom Tag seiner Ernennung zum Boss der Anduri an trug er nun eine Gaduni-Maske, die sein entstelltes Äußeres verbarg. Kaum im Amt und Ehren nahm er Kontakt mit der unter [[Thrall]] gerade wieder erstarkenden Horde auf und bot unverhohlen das Können der Anduri als Krieger an. So kamen im Krieg gegen die Geißel unter anderem die Anduri-Fledermausreiter zum Einsatz, die bewandert im Umgang mit bösen Voodoo-Drinks und unter der harten Führung ihres Oberführers Vanaka'zin schonungslos gegen alle Feinde vorgingen.\r\nDoch Vanak'zin begann, sein wahres Gesicht zu zeigen. Mehr und mehr Welpen wurden verdorbenen Voodoo- Ritualen unterzogen, die ihre Stärke verfielfachten, ihre Geister aber abstumpfen und verdummen ließen. Der Sohn verriet alles, wofür seine Mutter stand und mit der Zeit korrumpierte der Stamm. \r\nUnd auch die Geißel reagierte. Die starken Männchen waren alle im Krieg gegen die brennende Legion, als die Attentäter der Geißel ihr nun ungeschütztes Dorf niedermetzelten. Jahre später sprach sich herum, dass Vanaka'zin während der Gefechte bereits Pakte mit der überlegenden Macht - Der Geissel - geschmiedet hatte. Er war zu opportunistisch gewesen, um wirklich so etwas wie Bündnistreue gegenüber der Horde zu empfinden. \r\nDie wenigen Überlebenden sprechen Vanaka'zins Namen nicht aus. Er ist gebrannt als Erzverräter. \r\nJahrzehnte später gründeten [[Zuul]] Jan'zin, ehemaliger Burnigwing-Fledermausreiter, und Futamaki Schleicht-im-Staub, Akolyth des Raptorgottes [[An'chras]] den Stamm der Ehrenwerten Anduri neu. Seine Grundsätze: Gegenseitiger Schutz und gegenseitige Hilfe für alle Stammesmitglieder, Bewahrung der trollischen Identität, Abkehr von dämonischen Kräften. Trolle, so die Ansicht der meisten Anduri, brauchen Gemeinschaft, wenn sie sich nicht selbst verlieren wollen. Der Stamm der Ehrenwerten Anduri bietet sie seinen Mitgliedern.\r\n==Die Ehrenwerten Anduri heute==\r\n<div class=\"thumb tright\" style=\"width:306px;\">\r\n<div class=\"thumbinner\">\r\n<div class=\"thumbcaption\">Video über den Anduristamm</div>\r\n<youtube width=\"300\" height=\"300\">lOvFXw0dlns</youtube>\r\n</div>\r\n</div>Sie sind ein Stamm für die Ausgestoßenen, die allein Reisenden, die in der Welt verlorenen Glücksritter, Abenteurer und Wanderer unter den Trollen. Die Welt ist hart und jeder Troll braucht andere seiner Art. Solange hier Trolle Freunde sein und einander beistehen können, ohne noch einmal ihrer Dunkelheit zu erliegen, erfüllen die Ehrenwerten Anduri ihren Zweck. Damit ist nicht gemeint, dass sich zwei Anduri nicht auch einmal die Nasen brechen, um Streitpunkte zu klären, oder dass der Stamm keine Blutopfer durchführen, im Krieg Herzen sammeln oder je nach Lust und Laune blutige Eskalation betreiben würde. Das ist trollisches Verhalten und hat nichts mit 'Dunkelheit' zu tun.\r\nAnduri sind, abgesehen von ihrer Treue zum Stamm und der Tatsache dass sie einander beistehen, sich unterstützen, ihre Feinde gemeinsam und gnadenlos bekämpfen, ein bunter Flickenteppich. Von halbwahnsinnigen Kriegsberserkern über mysteriöse Geistersprecher, freundliche Charaktere und gnadenlose Killeringenieure scheint unter den Ehrenwerten Anduri alles vertreten zu sein. Während manche von ihnen als fähige Händler tagelang zwischen Auktionshaus und Bank Geschäfte machen, sind andere bereits bis nach Lordaeron gekrault, haben Drachen erlegt oder 100-Tage-Alterac-Kriegsrekorde aufgestellt. Die Vielfalt der Anduri wird vom Stamm als große Stärke angesehen.\r\nDas bedeutet jedoch nicht, dass der Stamm jeden Troll aufnimmt, der irgendeine Heimat sucht. Vielmehr sind die Aufnahmekriterien in vielerlei Hinsicht undurchschaubar, das \"gewisse Mojo\" scheint oft der Grund für eine Aufnahme zu sein, wenn es ein Troll schafft, als Welpe der Anduri aufgenommen zu werden.\r\nVon einer 'politischen' Einstellung der Anduri kann nicht gesprochen werden. Der Stamm steht der Horde grundsätzlich positiv gegenüber, wobei die genaue Haltung gegenüber Thralls Bündnis von Anduri zu Anduri abweicht. Kriegszüge wie die Plünderung Nethergardes folgen keinem strategischen Kalkül, sondern entstehen scheinbar schlicht aus dem Bewegungsmoment das zum tragen kommt, wenn eine größere Gruppe der meist verstreuten Anduri etwas getrunken hat und sich langweilt. Ähnliches gilt für Kriegszüge gegen Zul'Gurub und die Überfälle auf Hochburgen der Brennenden Legion, der Arrakhoa und anderer Gegner der Horde. Der Stamm ist impulsiv und erinnert oft an eine Person, in deren Psyche das 'Es' das 'Ich' abgefüllt und das 'Über-Ich' gefesselt in den Schrank gesperrt hat.\r\nAnduri kann man theoretisch immer treffen. Überall. Ob man sich darüber freut, steht auf einem anderen Pergament.\r\n==Heimat == \r\nDer Dschungel von [[Stranglethorn]] ist unsere ureigene Heimat, es herrscht das Recht des Alteingessenen, das Recht des Stärkeren. Wir als Dschungeltrolle und Anduri vereinigen und nutzen den Dschungel als Zuflucht und als Treffpunkt. Das [[Basislager von Grom'Gol]] wird hierbei als Dreh- und Angelpunkt unserer Bemühungen verstanden, wir lassen uns in „unserem“ Dschungel von keinen Außenstehenden beleidigen oder zurechtweisen. Es werden gute Verbindungen zu der Stadt [[Booty Bay]] geführt. Der Häuptling bewegt sich nur noch selten außerhalb des Dschungels und kann, wenn nötig, in Booty Bay oder Grom Gol getroffen werden.\r\n==Voodoo == \r\nDer [[Voodoo]] ist die Verbindung zu unseren Ahnen und eine wichtige Stütze des Stammes, der Voodoo ist der Weg der Vorfahren und ist innerhalb des Stammes mit höchstem Respekt zu behandeln. Wir beschwören keine Dämonen, wir opfern keine anderen Trolle, allerdings ist es durchaus möglich, dass wir z.B. Elfen opfern falls es nötig sein sollte (SEHR nötig, keine Opferung findet einfach aus einer Laune heraus statt).\r\nWir nutzen Blut als spirituelles Zahlungsmittel, Blut ist von je her ein wichtiger Bestandteil des okkultischen Voodoo und wird als Selbstverständlichkeit angesehn.\r\nBlutrituale dienen der Stärkung der Gemeinschaft oder Einzelner, aber nie dem Selbstzweck. Die Opferung von Innereien, das Knochenlegen und andere dunkel anmutende Vorgänge sind für einen Troll gang und gäbe und er wird sie NICHT als verwerflich ansehen wenn er keine wirklich handfesten Gründe dazu hat.\r\n==Hackordnung == \r\nDas Ausspielen der Ränge, das Pochen auf Respekt und Einforderung von Gehorsam ist ein Muss. Respektlosigkeiten von niederen Rängen gegen Höhere werden entsprechend geahndet. Kein Troll greift den Häuptling öffentlich an oder zweifelt an ihm wenn Außenstehende es mitbekommen, gleiches gilt für Offiziere etc. Die Vorgesetzten sind dafür zuständig, dass es dem Stamm gut geht, wahrloses herumdiktieren oder eigennützige Befehle werden bestraft. Wir sind eine Familie und es wird sich nichts an der Wärme und dem Zusammenhalt ändern. Ein Troll zeigt Respekt vor denen im Stamm, die mehr erreicht haben und lehnt sich nicht gegen die Befehle von Ranghöheren auf.\r\n==Grundzüge der Anduri-Klassen == \r\n===Schamanen === \r\nSie sind naturverbunden und weise, handeln nicht überstürzt oder eigennützig (ausser der Char ist dunkel angelegt und die Story verlangt es). Sie sind sich ihrer Wichtigkeit bewusst, verhalten sich dennoch aber bescheiden und demütig. Schamanen haben KEINE Vorbehalte gegen das Nutzen von Voodoo. Sie sollten eine gewisse Waage innerhalb des Stammes sein. Eine neutrale Position zu der jeder gehen kann und Rat einholt.\r\n===Priester === \r\nVerstehen die Wege der Ahnen und die Wichtigkeit von Ordnung und Hütung der alten Traditionen (Respekt, Ehre, Loyalität, Gehorsam). Sie üben Rituale mit großer Selbstverständlichkeit aus. Anduri erzogene Priester haben immer eine besondere Bindung zu Kriegern, anders rum genauso. Priester haben großes Vertrauen zu den Kriegern und beide behandeln sich als ebenbürtig auf ihrem Fachgebiet. \r\n===Magier===\r\nMagier sind, im Vergleich zu den Schamanen oder Priestern des Stammes, auf eine andere Art mystisch veranlagt. Sie kontrollieren sowohl pure astrale Kraft, als auch die Mächte der Elemente. Der typische Trollmagier empfindet Stolz darauf, dass er die Kraft kontrolliert und nur mit seinem Geist formt, ohne den \"Umweg\" über Geister oder Götter, Dämonen oder Totems zu gehen.\r\nDie Magier sprechen nicht herabwürdigend über die mystischen Kräfte ihrer anderen Stammesbrüder, denn alle Anduri stehen Seite an Seite und sie kennen die Macht der Schamanen, Priester und Hexer. Sie haben in mancher Hinsicht eine direktere Herangehensweise an Probleme und Feinde, als dies bei den anderen mit der Kraft Gesegneten der Fall ist.\r\nDer Charakter der Magier kann dennoch höchst unterschiedlich sein: Viele Magier sind eher wissenschaftlich als spirituell veranlagt (für Trolle jedenfalls). Doch ob laut und befehlend, mystisch und verschlossen, intellektuell und verspielt, weltlich und handwerklich... sie lassen sich eben so wenig wie die anderen Anduri in eine feste Form pressen. Durch die Vielfältigkeit ihrer Magie sind sie unberechenbar und stets für eine Überraschung gut, wenn der Stamm in Not ist.\r\n===Schurken === \r\nSind immer zwillichtig oder verschlagen nach aussen, verhalten sich innerhalb des Stammes aber vertrauensvoll. Kein Schurke des Stammes würde seinen Stamm mit Absicht schaden (egal wie dunkel der Char ist, die Grenze wird bei der eigenen Familie gezogen). Sie neigen zur Geheimnisskrämerei und dazu sich alle Möglichkeiten freizuhalten. Kein Schurke würde seinen Stamm jemals in dunkle Geschäfte hineinziehen. Sie sind weniger Trolle der offenen Feindbekundung als viel mehr feige bzw. hinterhältige Mörder, ( das heisst hat der Char keinen trifftigen Grund sich wie ein Krieger im Blutrausch zuverhalten, verhält er sich immer etwas kühler und verschlagener).\r\n===Jäger === \r\nHaben für Trolle eine besondere Bedeutung, sie zeigen grossen Respekt vor der Beute und bewegen sich innerhalb der Natur unendlich selbstsicher und stark...einem Jäger sollte es immer unangenehm sein in grosse steinerne Städte zu gehen. Jäger sollten immer (wenn es nicht gegen die Charführung geht) ihr bestes für die Gemeinschaft tun. Sie verhalten sich Fremden gegenüber eher verschlossen, bekunden ihre Stammeszugehörigkeit jedoch voller Stolz. Ein trollischer Jäger neigt vielleicht dazu eigenbrötlerisch oder verschroben zu wirken, hat aber ein gutes und reines Herz. Wer einen Jäger als Freund hat kann sich seiner Treue gewiss sein. \r\n===Krieger===\r\nKrieger sind wild, brutal und kompromisslos. Kein Krieger MUSS dumm sein. Ein Krieger hat kein Problem damit das Herz von würdigen Gegnern zu fressen. Ein Krieger beschützt den Stamm bis zur letzten Möglichkeit und bekundet seine Loyalität. Er lässt es nicht zu das schlecht von seinem Stamm geredet wird und neigt zu vorschnellen reaktionen oder Blutlust. Männliche Anduri Krieger sind so erzogen, dass sie keine Priesterin umwerben. Krieger haben vor Priestern höchsten Respekt und würden ihr Leben für sie geben. Es herrscht eine Art von traditioneller verbundenheit von Krieger zu Priester. Krieger sind weniger Trolle der Worte sondern neigen dazu Dinge möglichst immer auf eine Art regeln zu wollen. Kein Krieger lehnt einen guten Kampf ab. Krieger vertrauen einem anderen Troll nur nach einem Kampf.\r\n==Gildenname == \r\nEs ist ein Trollstamm, wie sich aus der Geschichte ergibt, mit der Besonderheit, dass wir die Kampfkraft und den Mut der Orks durchaus zu schätzen wissen und deshalb auch eine begrenzte Anzahl dieser Rassen als Verstärkung unserer Schutztruppe aufnehmen Diese Anduri-Garde genannte Wachtruppe ist eine gesonderte und aus dem Kastensystem (siehe weiter unten: Ränge ) ausgliederte Rang-Einheit und untersteht direkt den Stammesältesten. Es wird einer als Anführer und Gardehauptman ausgewählt werden, der die Angehörigen der Garde wiederum unterstehen.\r\n==Charakternamen == \r\nDie Namen der Charaktere stehen euch frei, sollten jedoch so klingen, dass sie natürlich nicht gegen die Richtlinien Blizzards verstoßen, noch sonst wie nicht ins Rollenspiel passen.\r\n==Aktivität == \r\nEs soll Spaß machen, es wird niemand gezwungen jeden Tag oder jede Woche online zu sein. RealLife geht vor und da wird niemand was sagen. Längere Abwesenheiten von mehr als 3 Wochen sind jedoch bitte bekannt zugeben.\r\n===Anonymität === \r\nJedes Stammesmitglied muss eine Email-Adresse hinterlegen, über die man es erreichen kann. Dies dient dazu, Protokolle der Sitzungen, Ratsbeschlüsse und interne Bekanntmachungen etc weiter zu geben.\r\n===Forum===\r\nWichtige Bekanntmachungen, Entscheidungen werden im Forum angekündigt. Daher ist eine Anmeldung erforderlich, dies ist ein weiteres Muss. Hier zwingen wir niemanden jeden Tag ununterbrochen reinzuschauen. Aber einmal alle paar Tage oder so sich kurz blicken lassen, sollte für niemanden unmöglich sein.\r\n===Gildentreffen===\r\nJede 2 Woche findet ein Gildentreffen statt. Termine werden per Gildenmitteilung und per Email angekündigt. Es besteht keine Erscheinungspflicht. So auch die Themen falls bereits welche bekannt sind. Themen können von jedem Mitglied auf den Tagesplan gesetzt werden und damit auch jeder nachdenken kann, diese im Forum notiert werden.\r\n===Entscheidungen === \r\nEntscheidungen werden von den Stammesoberhäuptern getroffen. Gildenmitglieder haben ein Mitspracherecht, aber die letztendliche Entscheidung obliegt den Oberhäuptern alleine. Je höher der Rang desto schwerer wiegt natürlich das Wort des Einzelnen. Wer nicht anwesend ist, wird von der Entscheidungsfindung ausgeschlossen, es liegt also im Interesse des Einzelnen, bei wichtigen Sitzungen und Beratungen anwesend zu sein. Abstimmungen erfolgen nur auf Gilden-Treffen. Nur Anwesende können ihr Stimmrecht wahrnehmen. Alle anderen werden bei größeren Entscheidungen über die Ergebnisse informiert.\r\n===Verhalten === \r\nStreit unter den Stammesangehörigen wird nicht geduldet und sollte in einer sachlichen Diskussion beigelegt werden. Ist dies nicht möglich wird beim nächsten Gilden-Treffen ein Schiedsgericht einberufen. Respekt untereinander sollte selbstverständlich sein, wozu auch ein gewissen Gehorsam gegenüber höher gestellten Rängen gehört. In einer Kampfsituation ist unbedingt Gehorsam gegenüber dem jeweiligen Kommandanten gefordert Entsteht der Gilde Schande durch grobes Fehlverhalten einzelner so werden beim nächsten Gilden-Treffen geeigneten Maßnahmen gegen diese beschlossen. Dies kann bis zum unehrenhaften Ausschluss führen.\r\n===Mitgliedermaximum===\r\nDerzeit ist ein momentanes Mitgliedermaximum von 45 Spielern vorgesehen, doch behält sich der Stamm jederzeit vor eine andere Grenze einzuführen oder einen zeitweiligen Aufnahmestopp zu verhängen, um neue Mitglieder zu integrieren oder andere Sachen intern zu klären. Denn das wichtigste ist, alle sollen sich verstehen können und sich im Stamm wohlfühlen, was man am besten erreicht indem man bei der Auswahl behutsam vorgeht und nichts übereilt.\r\n===Aufnahme === \r\nSpieler die interessiert sind der Gilde beizutreten kontaktieren einfach unsere Mitglieder und registrieren sich im Forum. Bitte bedenkt uns ist das Rollenspiel wichtig und wir versuchen einen Eindruck von euch zu gewinnen. Der natürlich mit positiven Auftreten und einem gewissen Rollenspiel eurerseits gefördert wird. Wer sich im Forum vorstellen will und kann (OOC+RP), schafft natürlich eine weitere Möglichkeit einen Eindruck von sich zu vermitteln. Schön wäre eine kurze Geschichte zum Charakter oder eine Art Lebenslauf, es braucht nichts übermäßig Großes werden, ist aber kein Muss.\r\n===Sprache innerhalb der Chatkanäle === \r\nInnerhalb des Gildenchats ist ein gemischter Fluß von RP und OOC (Out of Charakter) Gang und Gebe, genau wie in dem Gruppenchat. Anzumerken sei hier dass OOC im Gildenchat durch ein vorangestelltes OOC bzw eine Doppelklammer am Satzanfang und Ende gekennzeichnet ist. Beispiel: /g (( Heute war ich im Kino und hab mir 300 angesehen. empfehlenswerter Film )).\r\nAnders dagegen sieht es bei Schreien (/y), Reden in der Umgebung (/s) aus. Dort wird mit dem Charakter gesprochen, diese Art des Redens steht natürlich im Vordergrund, da es das Rollenspiel fördert. Da wir Wert auf RP legen, sollten diese Kanäle möglichst nicht benutzt werden, besonders bei Gildentreffen und gildeninternen Quests.\r\n===Probezeit===\r\nEs gibt nach Eintritt in die Gilde eine 4 Wöchige Probezeit. Sinn und Zweck ist das man sich kennen lernt und wir einen Eindruck von demjenigen bekommen. Nach einer ersten Aufnahmeprüfung erhält man den Rang Anduri Welpe Nach der Probezeit wird man nach einer weiteren Prüfung zum Anduri Stammesmitglied ( oder für Nichttrolle : Anduri Garde ) und kann sich entscheiden, zu welcher Kaste man sich zugehörig fühlt.\r\n===Austritt === \r\nJedem steht es frei die Gilde jederzeit zu verlassen, ihr müsst dafür keine Gründe angeben. Doch wäre es natürlich schön, es zu erfahren. Entweder öffentlich oder via Privatnachricht an jemanden eures Vertrauens innerhalb des Stammes. Des Weiteren besteht die Möglichkeit Mitglieder bei groben Fehlverhalten per Beschluss unehrenhaft zu entlassen.\r\n==Ränge == \r\nRänge haben innerhalb des Zirkels den Sinn, jemanden zu belohnen, aber sie dienen auch dem Rollenspielaspekt.\r\n===Der Welpe===\r\nAls unterster Rang, ist der Welpe zugleich die Kraft, die die grösste körperliche Leistung erbringen muss und die Zukunft der Anduri. Dem Welpen fallen zumeist einfach Botengänge und das Überbringen von Nachrichten zu.\r\n===Das Stammesmitglied===\r\nHöchster der niederen Stammesränge, hat das Recht, den ihm Untergeordneten Befehle zu erteilen, die dem Stammesansehen dienen. Das Stammesmitglied ist das Rückgrad des Stammes, das sich um viele kleinere Probleme kümmert bevor sie zu grossen werden. z.B: ungebührliches Verhalten etc. Dem Stammesmitglied steht es frei einen Kasten weg zuwählen. Hat er eine Kaste gewählt wird ihm eine spezielle Aufgabe erteilt\r\n==Kasten == \r\n===Die Bluthunde === \r\n'' (lvl min. 23 klasse: egal) ''\r\nGeborene Kämpfer und Gnadenlose Jäger Trolle die den Weg des Bluthundes wählen sind dazu bestimmt den Weg der Vergeltung und des Kampfes zubeschreiten, sie sind die Klinge des Anduri.Die Aufgaben der Bluthunde erstrecken sich von einfachen Kopfjagden über Bestrafung von Verrätern bis zu offenem Krieg gegen die Allianz. Keine Kaste erfordert mehr Mut und Kraft als die der Bluthunde. Daher ist es ein grosser und entscheidender Schritt im Leben eines Anduri \r\n===Die Dschungelläufer === \r\n''(lvl min. 23 klasse: egal) ''\r\nDie Nase im Wind und die Waffe in der Hand ,sind die Dschungelläufer die Ressourcen beschaffer der Anduri.Sie bringen jede Beute zur Strecke, können tagelang in der Wildness überleben und kämpfen mit der Wut eines wilden Tieres. Sie versorgen den Stamm mit nötigen Dingen wie Fleisch, Leder, Stoffe und Ähnlichem. Ihr Einsatz gebiet ist die Wildnis dieser Welt. Die Aufgaben der Dschungelläufer erstrecken sich von normalen Jagden über Grosswild hetzen bis zu dem erlegen legendärer Bestien. Die Dschungelläufer sind naturverbunden und ausgeglichen aber auch leidenschaftlich im Kampf und dem Stamm treu bis in den Tod \r\n===Die Bokur===\r\n''(lvl min. 25 klasse: egal) ''\r\nDunkle Beschwörungen murmelnd und unaussprechliches Wissen hütend sind die Bokur die spirituelle Verbindung zu den Ahnen der Anduri. Ihr Bildungsstand ist dem eines gewöhnlichen Anduri weit überlegen, ihre Macht geht über das trollische Denken hinaus. Im Kampf und in der Unterstützung sind es die Bokur, die den vollen Schutz der Bluthunde geniessen. Ihre mächtigen Voodoo Künste machen sie unverzichtbar für den Stamm, und gefürchtet bei den Feinden. Ihre Aufgaben gehen von Aufnahmeritualen über Expeditionen ins Ungewisse bis zu gewaltigen Beschwörungen Sie sind die gefürchteste und geachtetste Kaste des Stammes. \r\n===Die Ratsmänner === \r\n''(lvl min. 35+ Klasse: egal) '' \r\nWenn ein Troll einer Kaste der Anduri lange und treu gedient hat wird er gefragt ob er sich den Ratsherren anschliessen will. Eine elitäre, beratende Gruppe, die neben den Ältesten den höchsten Einfluss haben, ihr Wort ist allen untergebenen Gesetz und ohne Murren auszuführen, demnach liegt ihnen auch eine grosse Verantwortung vor. Ihre Herzen sind rein und ihr Wissen gewaltig. Sie organisieren Veranstaltungen und ähnliches und hüten die Ordnung im Stamm.\r\n==Motivation der Gilde bezüglich PVP==\r\nWichtig ist natürlich auch die Verbindung von RP im PVP, man kann eine Schlacht auch im RP-Modus durchziehen, dazu muß es aber gut organisiert sein. Das Gilde soll bewußt irgendwo einen gewissen miltitärischen Touch haben, da durchaus in ferner Zukunft geplant ist, Schlachtzüge generalmaßstäblich durchzuführen. Natürlich zwingen wir niemanden und es steht auch jedem frei, mitzukommen, aber wer bei einer solchen Aktion mitgeht, von dem erwarten wir, dass er sich in die Struktur einfügt und die Kommandokette akzeptiert. Im Einzelnen heißt das, kein wildes Umhergerenne und kein unkontrolliertes Abschlachten von Gegnern usw. Die Rottenführer haben das Sagen über ihrer Gruppe, die Rottenführer unterstehen wieder dem nächst höheren Anführer usw. Natürlich bedeutet dieses Vorgehensweise eine gewisse Beschränkung seiner eigenen Freiheit und man muß hier vielleicht einmal zurückstecken. Wer das nicht kann oder will, den zwingt niemand daran teilzunehmen und keiner ist euch deswegen böse. Nur wenn ihr euch dafür entscheidet, einen solche Unternehmung mitzumachen, erwarten wir oben genannten Gehorsam. Das ist aber kein Kriterium, nicht in die Gilde aufgenommen zu werden, wie gesagt, es ist freiwillig und ganz unabhängig vom restlichen Stammesleben und kein Zwang. Nach unserer Auffassung kann man nur mit Disziplin und Strategie eine Schlacht gewinnen und das sollte im Vordergrund stehen, die Taktik und das Ausmanövrieren des vermutlich deutlich schlechter organisierten Feindes ist wichtig und spannend, nicht der PVP-Rang und die Ehrenpunkte, die man ergattern könnte.\r\n==Gildenqueste == \r\nUm eine dauerhafte Motivation und Zusammenhalt zu sichern werden pro Rang, Aufstieg oder ähnlichen gravierenden Ereignissen, Questen erteilt deren Erfüllung belohnt wird und den Spielern das Eintauchen in das RP erleichtern soll. Man unterscheidet bei den Questen Einzel- und Gruppenqueste. Es wird natürlich ein großer Teil Ehrlichkeit bei Einzelquesten vorausgesetzt, da eine Kontrolle nicht möglich ist, aber da es sich des Öfteren um Beschaffungsquesten handeln wird, ist die Vorlage des geforderten Gegenstandes Kontrolle genug. Die Besonderheit des Gruppenquest ist es, dass ein vorher nicht benannter Gruppenleiter das Verhalten und das allgemeine RP überwacht und so sicherstellt, dass der, der ein gutes RP an den Tag legt, am Ende der Aufgabe eine entsprechende Belohnung erhält. Dies läuft ähnlich wie ein Pen&Paper-Rollenspiel. Wobei der Gruppenleiter die Rolle des Spielleiters übernimmt. Der Inhalt der Queste wird in mühsamer Kleinarbeit von [[Zuul]], [[Futamaki]] oder Freiwilligen aus dem Stamm geplant und durchgeführt. \r\nAnmerkung: der Stand eines internen Gruppenleiters ist Level ungebunden. Jeder kann es werden, damit jeder eine gewisse Vorstellung von den Aufgaben eines Questgebers und Überwachers bekommt. Außerdem dient der Titel des Gruppenführers dazu, dass eben jener die anderen Mitspielenden motiviert und unterstützt. Der Gruppenleiter wird vor einem Quest von einem Häuptling angeflüstert und darf den anderen Spielern nicht mitteilen, dass er zum Gruppenleiter bestimmt wurde, um eventuelle Anbiederungen zu unterbinden.\r\n==Weblinks==\r\n*",},
			["Anduri Stamm"] = { content = "#REDIRECT [[Anduri-Stamm]]", redirect = "Anduri-Stamm",},
			["Anetheron"] = { content = "Der mächtige und furchteinflößende [[Schreckenslord]] Anetheron war der persönliche Leibwächter [[Archimonde]]s im Kampf um den Berg [[Hyjal]], doch fiel im Kampf gegen die [[Nachtelfen]]. Nun erwartet er Abenteurer in den [[Höhlen der Zeit]] beim [[Kampf um Hyjal]].\r\nAnetheron\r\nDer Trick im Kampf mit Anetheron liegt in der Verteilung der Spieler und deren Übersicht. Die Infernos dürfen nicht unkontrolliert durch die Schlachtgruppe laufen und müssen daher durch einen zweiten Tank beherrscht werden.\r\n \r\n==Fähigkeiten==\r\n* Vampirische Aura: Der Boss erhält Trefferpunkte zurück, welche abhängig von seinem Schaden sind. 300 Prozent des Schadens seiner Nahkampfattacken auf den Haupttank gewinnt er dabei wieder.\r\n* Einschlafen: Zufällige Spieler schlafen für zehn Sekunden ein und sind dadurch handlungsunfähig. Dieser Effekt kann vorzeitig nur durch ein Beben-Totem, die Untoten-Rassen-Fertigkeit oder erlittenen Schaden aufgehoben werden.\r\n* Aasschwarm: Dieser kegelförmige Atem trifft alle Spieler in einem 60 Grad Winkel innerhalb von 60 Metern, wobei die Zielrichtung Zufall ist. Alle Spieler unter dem Einfluss des Schwarms erleiden etwa 5.000 Schattenschaden sowie einen 20-Sekunden-Debuff, der deren ausgeteilte Heilung um 75 Prozent reduziert. Dies wirkt sich auch auf Bandagen, Tränke und Gesundheitssteine aus. Durch angemessene Verteilung über die Basis reduziert Ihr den Anteil der Betroffenen.\r\n* Inferno: Etwa jede Minute regnet ein Inferno auf einen zufälligen Spieler, richtet 2.500 Feuerschaden an und betäubt das Ziel für zwei Sekunden. Im Anschluss daran wütet es umher. Ein Tank nimmt sich direkt der Kreatur an und zieht sie nach hinten. Die Verbrennungs-Aura richtet alle drei Sekunden etwa 3.500 Feuerschaden an. Beachtet, dass das Inferno nicht spottbar ist.",},
			["Ango'rosh"] = { content = "#REDIRECT [[Oger der Ango'rosh]]", redirect = "Oger der Ango'rosh",},
			["Anhänger des Schattenhammerklans"] = { content = "Die Anhänger des Schattenhammerklans werden von den [[Akolyt]]en, [[Aquamant]]en, [[Bewahrer der Lehren|Bewahrern der Lehren]], Elementaristen, Häschern und [[Schattenmagier]]n des [[Schattenhammer Kult]]s in der [[Tiefschwarze Grotte|Tiefschwarzen Grotte]] im [[Eschental]] getragen.",},
			["Anhänger von Myzrael"] = { content = "Der Anhänger von Myzrael wird zufällig gefunden und führt den Finder auf die Spur zu dem \"Kristall in den Bergen\". Dieser Splitter pulsiert während man ihn hält. Man hat das Gefühl, als ob ein Bitten vom Splitter ausgeht, als ob jemand versucht zu kommunizieren, jemand, der verzweifelt Hilfe sucht. Vor dem inneren Auge erscheint eine Vision - die nördlichen Berge von [[Arathi]] und ein blitzender Kristall, der dort aus dem Boden ragt. Man spürt, wie es einen dorthin zieht. Man muss den Kristall aus der Vision finden.",},
			["Anhöhe des Entweihers"] = { content = "Die Anhöhe des Entweihers in den [[Verwüstete Lande|Verwüsteten Landen]] ist der Sitz von [[Razelikh]] dem Entweiher. Sein Unterschlupf befindet sich auf dem Gipfel des höchsten Berges in den [[Verwüstete Lande|Verwüsteten Landen]]. Einzig durch Einsatz der Teleportrunen in der Nähe des Berges kann man zu diesem Unterschlupf gelangen und auch nur solange man das [[Razelikh]]s Amulett hat, kann man den Unterschlupf erreichen.",},
			["Ankheg"] = { content = "Ankhegs sind gezüchtete Wesen der [[Neruber]]. Sie wurden als Wächter besonderer Orte eingesetzt oder auch in Gladiatorenkämpfen zu Ehren von [[Nerub]]. Sie lieben öde Gebiete , wo sie ihre Beute anfallen können.Die Neruber verehrten besonders große und starke Ankhegs als \"Geweihte Nerubs\".Viele dieser Wesen starben im [[Krieg der Spinne]], der das alte Volk der [[Neruber]] vernichtete.\r\nMehr ist über sie leider noch nicht bekannt.",},
			["Anleitung des Pariah"] = { content = "Die '''Anleitung des Pariah''' beschreibt, wie man das ''Amulett der Vereinigung'' aus den Höhlen von [[Maraudon]] bergen kann. Man erhält sie vom [[Zentauren]]pariah aus [[Desolace]].\r\n===Inhalt===\r\nGanz weit hinten im [[Tal der Speere]] steht der heilige Tempel von [[Maraudon]]. Als wäre das nicht schon eine Sünde an sich, werdet Ihr bald schon sehen, warum ich einen Nicht-Zentauren gebeten habe, mir aus meiner Notlage zu helfen.\r\nDort, gleich hinter den Türen, wo nur Geister und unsere heiligsten Priester und Priesterinnen wandeln dürfen, gibt es jemanden, der der 'namenlose Prophet' genannt wird. Er ist die höchste Instanz aller Stämme, was spirituelle Dinge angeht, und der Älteste aller Stämme. Der Prophet ist mächtig und kommuniziert mit den Geistern unserer Vorfahren. Er ist jedoch ein Narr! Er hat keine Ahnung, welche Macht er in Wirklichkeit besitzt. Er trägt das ''Amulett der Geister'', das ihm einen Großteil seiner Kraft verleiht.\r\nIch habe in Erfahrung gebracht, dass das Amulett zwar mächtig, aber unvollständig ist. An dem Amulett fehlen fünf Edelsteine. Falls man diese Edelsteine finden und wieder an dem Symbol anbringen könnte, würde dessen Macht noch weitaus größer sein als in der jetzigen Form. Ich habe herausgefunden, wo die fünf Edelsteine sind, brauche jedoch jemanden mit Euren Fertigkeiten, um sie zusammenzutragen. Den namenlosen Propheten zu töten wäre Ketzerei, wie es auch Ketzerei wäre, die Steine von seiner Leiche zu klauben. Worum ich Euch jedoch gleich bitten werde, würde jeden Zentauren verdammen, der auch nur den Gedanken in Erwägung zöge.\r\nIn den Höhlen von Maraudon gehen die Geister unserer ersten Khans um. Es sind die ersten Kinder unserer Mutter und unseres Vaters und es sind unsere größten Anführer - [[Gelk]], [[Kolk]], [[Magra]], [[Maraudos]] und [[Veng]]. Jeder dieser Geister besitzt einen der fehlenden Edelsteine. Nutzt die Macht des Amuletts der Geister, um sie zu zwingen, Gestalt anzunehmen, und nehmt ihnen dann die Edelsteine ab! Platziert die Edelsteine dann im Amulett der Geister und bringt es mir. Sobald ich das ''Amulett der Vereinigung'' habe, bin ich mächtig genug, um die Stämme zu reformieren, damit wir endlich so sind, wie unsere Vorfahren uns haben wollten!",},
			["Annalen von Darroheim"] = { content = "Das Buch '''Die Annalen von Darroheim''' wird im Rathaus von [[Andorhal]] aufbewahrt und erzählt die Geschichten der Helden und der [[Schlacht um Darroheim]] in den [[Östliche Pestländer|Östlichen Pestländern]]. \r\nEs berichtet u.a. von dem Paladin [[Davil Lichtschmied]] und davon, wie der Kreuzzug seinen Buchband zum Rathaus von [[Herdweiler]] brachte. Die \"Annalen von Darroheim\" berichten aber auch von den Bösewichten der Schlacht: Sie berichten, wie der Ghullord [[Horgus der Verheerer]] von Kräften der [[Allianz]] während der Schlacht vernichtet wurde. Seine Leiche wurde in einen See geworfen, nordwestlich von [[Corins Kreuzung]], und sein Schädel ist noch dort. [[Marduk der Schwarze]] wurde nie besiegt, aber sein sagenhaftes Schwert wurde zertrümmert und ging verloren. Es liegt auf dem Grund der Schlucht westlich von [[Corins Kreuzung]]. Einige Passagen handeln auch von [[Carlin Rotpfad]]s Bruder, [[Hauptmann Rotpfad]]. Nach seinem Verrat wurde sein Schild zerschmettert und weggeworfen und liegt nun am unwahrscheinlichsten aller Orte - in der Nähe von [[Gahrrons Trauerfeld]]. Die \"Annalen von Darroheim\" haben mit Hilfe von [[Chromie]]s Magie an ihrem Ende Seiten hinzugewonnen, und nun erstreckt sich die Geschichte auch über den Kampf hinaus. Eine der zusätzlichen Passagen berichtet von einem Mitglied der Familie Rotpfad, [[Carlin Rotpfad]], der Josephs Verrat überlebt hat. \r\n==Inhalt==\r\nDarroheim, benannt nach dem Darromersee im Westen, ist ein Dorf, das sich in das südliche Vorgebirge Lordaerons schmiegt. Bekannt für seine bescheidenden, aber hart arbeitenden Bewohner, führte Darroheim ein Schattendasein in der Geschichte Lordaerons, bis der Zweite Krieg ausbrach. In diesem Krieg wurden Helden geboren. Und viele Helden ließen ihr Leben.\r\n===Die Schlacht um Darroheim===\r\nDie Schlacht um Darroheim ereignete sich in der Mitte des Zweiten Krieges, als Streitkräfte der Geißel durch Lordaeron tobten. Darroheim wurde von der Hauptstreitmacht der Allianz abgeschnitten. Doch eine Kompanie Soldaten, ein Kontingent Paladine der Silberhand und eine standhafte Gruppe hiesiger Milizen unter ihrem Anführer Hauptmann Joseph Rotpfad hielt in der Stadt stand. Die ersten Angriffe der Geißel auf Darroheim waren eher harmlos. Kleine Gruppen plündernder Skelette und Kadaver durchstreiften die Außenbezirke des Dorfs und wurden mit Leichtigkeit besiegt.\r\nDie Geißel spürte die Hartnäckigkeit der Verteidiger und zahlte mit gleicher Münze zurück. Schon bald nach der ersten Welle von Angriffen, kündigte sich eine zweite an. Ghulchampions, Gefolgsleute des Ghullords Horgus, strömten mit wildem Geschrei von den Bergen herab und überrannten die belagerten Verteidiger Darroheims.\r\nDie Verteidiger waren geschwächt, wurden jedoch durch Paladine abgelöst, Jünger der Silberhand. Ihr Anführer David Crokford stammte aus Darroheim. Er brachte seine Anhänger ins Dorf, als er von dem bevorstehenden Angriff erfuhr, und zusammen mit den Verteidigern gelang es ihnen, die Diener von Horgus aufzuhalten.\r\nAls Horgus sich höchstpersönlich in die Schlacht stürzte, traf er auf Davil. Viele Minuten lang kämpften sie, und Davil ging am Ende siegreich hervor, erlitt jedoch eine tödliche Verletzung und starb kurz, nachdem er den Ghullord besiegt hatte. Die Schlacht ging weiter und Hauptmann Rotpfad führte seine Milizen mutig an. Der Kampf wäre vielleicht sogar gewonnen worden, wäre der Hauptmann nicht durch den Todesritter Marduk der Schwarze verderbt worden. Mitten im Getümmel ritt Marduk auf Rotpfad zu, entriss ihm durch schwarze Magie seinen Geist und verwandelte ihn in einen bösen Schatten des tapferen Hauptmanns. Durch den verderbten Hauptmann Rotpfad breitete sich danach dessen bösartige Besudelung unter den Verteidigern Darroheims aus, die prompt ihre Verbündeten verrieten und ermordeten. Dann wandten sie sich der Stadt Darroheim zu und töteten alle, die sich in ihren Häusern versteckten. Die verbliebene Armee der Geißel sowie der verderbte Geist Hauptmann Rotpfads verließen danach das verheerte Dorf Darroheim und drangen nach Lordaeron vor, um im Zweiten Krieg noch mehr Schmerz und Tod zu verbreiten.\r\n===Das Schicksal von Horgus dem Verheerer===\r\nHorgus der Verheerer fiel in der Schlacht um Darroheim. Aber das Böse in ihm war noch nicht versiegt. Die siegreichen Streitkräfte der Geißel bargen seinen Schädel vom Schlachtfeld bei Darroheim und nahmen ihn mit sich, um alles Leben, dem sie begegneten, in Angst und Schrecken zu versetzen. Tage später wurde die Kompanie der Geißel, in deren Händen sich der Kopf befand, von den Paladinen der Silberhand besiegt. Horgus' Kopf wurde im Faulholzsee versenkt. \r\n===Das Schicksal von Marduk dem Schwarzen===\r\nMarduk überlebte den Zweiten Krieg und sorgte durch sein elendes, runenübersätes Schwert für Tod und Leid. Marduk lebt zwar heute noch, sein Schwert jedoch ging während einer Schlacht in der Nähe von Corins Kreuzung verloren. Ein Zwergenhauptmann zerschmetterte das Schwert auf seinem verzauberten Schild und vertrieb Marduk vom Schlachtfeld, womit er den Kampf zu Gunsten der Allianz entschied. Marduks Schwert versank in der Erde und verderbte sie. Es fraß eine Schlucht in das Land, die heute als die 'Infektnarbe' bekannt ist.\r\n===Das Schicksal von Davil Lichtschmied===\r\nDavil Lichtschmied starb in der Schlacht um Darroheim, doch sein Mut gereichte der Allianz während des gesamten Krieges zum Vorbild. Sein Buch, genauer gesagt Paladinbuchband, wurde später von Truppen des Scharlachroten Kreuzzugs wiedergefunden. Es befindet sich jetzt im Rathaus im vom Scharlachroten Kreuzzug kontrollierten Herdweiler, wo es eifrig von Kreuzzüglern studiert wird, die von Davils Kraft profitieren wollen.\r\n===Das Schicksal von Joseph Rotpfad===\r\nJoseph Rotpfad wurde während der Schlacht um Darroheim getötet. Sein Geist wurde verderbt und nahm eine neue Gestalt an. Diese neue Kreatur brachte großes Übel über Lordaeron. Auf Gahrrons Trauerfeld, östlich von Andorhal, wurde der verderbte Rotpfad schließlich durch Streitkräfte der Allianz besiegt. Sein Schild liegt noch immer in der Nähe der Scheune des verseuchten Bauernhofs und Diener der Geißel werden noch immer von diesem Andenken an seine Bösartigkeit angezogen.\r\n===Das Schicksal von Carlin Rotpfad===\r\nCarlin, der Bruder Hauptmann Joseph Rotpfads, gehört zu den Opfern der Schlacht um Darroheim. Doch obwohl er schreckliche Wunden davongetragen hatte, starb er nicht. Tage nach der Schlacht griffen ihn Agenten der Argentumdämmerung auf, als er, geschwächt von Durst und Fieber, in der Nähe von Corins Kreuzung umherirrte. Sie pflegten seine Wunden und brachten ihn zur Kapelle des hoffnungsvollen Lichts. Dankbar für ihre Barmherzigkeit schloss sich Carlin den Reihen der Argentumdämmerung an und führt jetzt einen Rachefeldzug gegen die Geißel.",},
			["Anok'suten"] = { content = "'''Anok'suten''' ist eine [[Gruftbestie]] in den [[Geisterlande]]n. Sie ist das Oberinsekt der [[Neruber]] auf der [[Sonnenkuppe]] und man findet sie bei den anderen Nerubischen Wachen dort. Ein Kundschafter aus [[Tristessa]] wurde von [[Arkanist Vandril]] hierher entsandt, um die Neruber zu besiegen. Doch er konnte nicht ahnen, dass sie eine Anführerin haben. Sie wanderte in der Umgebung umher und überfiel den Kundschafter. Nun stirbt er und sein letzter Wille ist, dass Anok'suten ebenso getötet und Arkanist Vandril davon in Kenntnis gesetzt wird. Hätte Vandril vorher etwas von der Existenz dieser Anok'suten gewusst, hätte er den Kundschafter umgehend davon in Kenntnis gesetzt. Doch die Streitkräfte von Tristessa sind einfach zu weit verteilt und manche Dinge schlüpfen den Kundschaftern unter diesen Umständen einfach durchs Netz.",},
			["Anthion Harmon"] = { content = "'''Anthion Harmon''' war ein menschlicher [[Krieger]], der zu einer Abenteurergruppe gehörte, die [[Lord Valthalak]] in der [[Untere Schwarzfelsspitze|Unteren Schwarzfelsspitze]] ([[LBRS]]) bekämpfte. Valthalaks Seele wurde in einem Amulett verwahrt, doch in ihrer Gier haben es diese Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der sie heimsuchen würde. Die Abenteurer waren sich der Wichtigkeit von Valthalaks Amulett nicht bewusst, also wurde es zusammen mit der restlichen Beute aufgeteilt. Man sagt, dass Anthion später von den untoten Horden [[Stratholme]]s niedergemäht wurde, als er versuchte, durch die Tore zu schreiten. Doch sein Geist verweilt noch dort. \r\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett, in dem die teuflische Seele von Lord Valthalak pulsiert, wieder zusammenzusetzen. \r\nDas erste Stück bekam ein Zwerg namens [[Theldren]]. Anthion hat versucht, es sich von ihm zurückzuholen und er hätte ihn fast zu Tode geprügelt. Man wird ihm sein Stück gewaltsam entreißen müssen, doch das Letzte, was Anthion über ihn hörte, ist, dass er ein Gladiator für die [[Dunkeleisenzwerge]] geworden ist. Ihn zum offenen Kampf zu bewegen, dürfte sich jedoch schwierig gestalten.",},
			["Anthrazides"] = { content = "== Allgemeine Beschreibung==\r\n'''Rasse:''' [[Menschen|Mensch]] \r\n'''Klasse:''' [[Hexenmeister]] \r\n'''Alter:''' Zirka Mitte 40. \r\n'''Beruf:''' 3. Magistrat der [[Stadt Stormwind|Stadt Sturmwind]], [[Nether]]forscher\r\n'''Gesinnung:''' Selbstsüchtiges, egozentrisches Schlitzohr\r\nAnthrazides ist etwas kleiner (175 cm), wohl genährt, hat eine große Nase, buschige Augenbrauen, einen gepflegten Schnauzbart der sich kunstvoll nach innen rollt sowie glattes, nach hinten gekämmtes, schulterlanges, schwarzes Haar. Sein polterndes Lachen ist oft über dem Gerede der Leute auf dem Marktplatz in [[Sturmwind]] hinaus zu hören. Er grinst gerne und viel und offenbart dabei eine Reihe von goldenen Zähnen. Er kleidet sich gern über dem bürgerlichen Standard und hat eine Nase für guten Wein, Mode, Parfüm und Damen. Er schätzt Wohlstand und tut alles für dessen Erhalt. Sicherheit und Ordnung liegen ihm sehr am Herzen. Fremdlinge - insbesondere [[Nachtelfen]] - sind ihm mehr als suspekt. Er sieht sie als Bedrohung der Ordnung in [[Sturmwind]] und als die Ursache vieler Übel. Auch [[Hexenmeister]], die sich öffentlich zu Ihrer Kunst bekennen, sind ihm ein Dorn im Auge. Anthrazides sieht die Parallelen zwischen seiner Zunft und die der [[Hexenmeister]] und fürchtet die Repressalien der Inquisition, weshalb er in letzter Zeit durch seine Arbeit als Meßtechniker für netherische Strömungen versucht hat, sich gut mit ihren Vertretern zu stellen, indem er sich für diverse Dienste anbiedert. Leider ist er damit weniger erfolgreich, als er hofft, auch wenn er - nicht ganz eigennützig - der Inquisition bereits große Dienste erwiesen hat. In letzter Zeit allerdings hat sein Interesse in diesen Dingen stark nachgelassen.\r\n \r\nAnthrazides ist leicht cholerisch, spießig, neurotisch, dekadent und hat eine leichte sadomasochistische Ader. Er kann der größte Kotzbrocken sein, dem man begegnen kann. Andererseits ist er humorvoll, spendabel und großzügig und ein guter Trink- und Gesprächspartner. Seine Laune ist davon abhängig, wie die Geschäfte laufen, wie die letzte Nacht war und wie vielen [[Nachtelfen]] er bereits über den Weg gelaufen ist. Seine Neigungen für Tabak und Alkohol haben in den letzten Monaten krankhafte Züge angenommen. Seine Sucht wirkt sich stark schädigend auf seine (Selbst-)Wahrnehmung aus. Er gilt als Künstler, Forscher und Lebemann und hat sich als enfant terrible der [[Sturmwind]]er High Society unbeliebt gemacht.\r\nWürde man Anthrazides und seine gelegentlichen Hasstiraden den [[Nachtelfen]] gegenüber tatschlich ernst nehmen, müsste bereits ein hohes Preisgeld auf seinen Kopf ausgesetzt sein, das sich sicherlich eine(r) der vielen [[Kaldorei]]-Assasinen eingefordert hätte. Dass das beleibte, stadtbekannte Großmaul noch immer am Leben ist, liegt wohl daran, das Veröffentlichungen, wie zum Beispiel sein \"Essay über die [[Kaldorei]]\", eher Produkte unzähliger, Absint getränkter Nächte sind.\r\nAnthrazides war Logenbruder, Schriftführer, Kassenwart und Aussenvertreter des [[Circulus Virtuosus]] und ist kürzlich zum 3. Magistraten der Stadt Sturmwind ernannt worden - ein Posten, den er seit langer Zeit angestrebt hat. \r\nEinige Zeit lang war Anthrazides dem Stadtrat als Magistrat ein wertvoller Verbündeter, doch dauerte es nicht lange, bis er - der Patriot der er war - sich mit der Inquisition überwarf. Ausschlaggebend waren Befugnisse innerhalb der Stadt, welche die Heilige Inquisition - aus Sicht der Königsdiener und Magistraten - immer dreister an sich riss. Letztendlich führte dies beinahe zu einem Bruch innerhalb des Stadtrates, den der Großinquisitor als klerikale Institution beiwohnte. Nach der Einführung von Ausweisen, einigen geleiteten Stadtratssitzungen, einem Stadtratsfest zur Information für die Bürger Sturmwinds sowie einem bislang unaufgeklärten Brand in seinem Appartement am Marktplatz hat sich Anthrazides, der sich wohl mit seiner Arbeit doch etwas übernommen und von schlaflosen Nächten geplagt wurde, zur Erholung in das Kloster der \"Schwestern des Lichts\" zurückgezogen. Dort wurde er alsbald Opfer eines nächtlichen Giftattentates, wie aus einem Brief von ihm an den Stadtrat hervorging. Da er bereits den Brand als Anschlag auf Leib und Leben gewertet hatte - Anthrazides war stets von Brandstiftung ausgegangen, auch wenn öffentliche Berichte stets neutral gehalten waren – zog er sich aus dem Amt des Magistratentums zurück.\r\nMomentan hat er seinen Wohnsitz zu den Sehern nach Shattrath verlegt und verfolgt dort weiter die Erforschung des Nethers sowie die Erkundung der Scherbenwelt als leitende Funktion des [[Circulus Virtuosus]]. \r\nIn Sturmwind wurde er seither nicht mehr gesichtet.\r\n==Titel==\r\nAnthrazides (der \"Fabelhafte\"), 3. Magistrat der Stadt Sturmwind, dreifacher Träger der Ehrenbürgerschaft Stormwinds, Initiator der Stiftung \"Kriegsversehrte & Grabpflege Stormwind\", Ehrenmitglied des Spendenkreises \"Waisenhaus Stormwind\", Vereinsvorsitzender der \"Weinfreunde Gallina\" und des \"Zigarrenzirkel Stormwind\", Kassenwart des \"Kulturschutzkreises vor elfischen Einflüssen\", Abonnent des Gemeindeblatts \"Klingelbeutel der Kathedrale\"\r\n==Netherforschung==\r\nAnthrazides der Fabelhafte hat umfangreiche Forschungen über Struktur, Zusammensetzung und Auswirkungen des Nethers betrieben und diese in seinen Werken '''Netherforschung Band I-V''' zusammengefasst. Einzusehen ist der erste, allgemein gehaltene Band I in der Bibliothek Sturmwind. Das Werk ist öffentlich zugänglich, während die weiteren Werke lediglich Studienkollegen vorbehalten sind.\r\n= Veröffentlichungen =\r\n[[Netherwissenschaften Band I]]\r\n[[Kurzgeschichte: Im Nether]]\r\n[[Kurzgeschichte: In der Scherbenwelt]]\r\n[[Sturmwind, die Stadt die niemals schläft]]\r\n[[Essay: Die Nachtelfen]]\r\n= Manifesto =\r\nDieses Schreiben wurde von Anthrazides einmal im Suff verfasst und war seine ironische Antwort auf diverse Schreiben von Kultischen Verbrecherorganisationen, die mal wieder die Stadt Sturmwind zu erpressen versuchten. \r\n \r\nZum Seelenheil der Menschen Azeroths\r\nDies soll Euch gesagt sein, das ich euch in meiner Gnade dies Schreiben bringe um euch kund zu tun von den 10 Paragrafen, die es zu erfüllen gilt zu eurem Seelenheil. Auf das ihr nicht darben werdet und die Kreaturen des Nethers eurer Seelen nicht habhaft werden können am Ende eurer Tage.\r\nEs soll euch gesagt sein,\r\n§ 1. Das ihr danieder kniet und den Blick zu Boden senkt bis eure Stirn den Boden berührt wenn ihr mich kommen seht. Die geschehe aus Ehrfurcht vor meiner Person und zu eurem Seelenheil.\r\n§ 2. Das ihr mich \"Göttlicher\" nennet wenn ihr von mir oder meinen Wohltaten für euer Seelenheil sprechet. Dies geschehe aus Dankbarkeit und zu eurem Seelenheil.\r\n§ 3. Das ihr den zehnten Teil Eures Hab und Guts, Geld und Goldes, Tafelsilber oder Erbstücke auf den Markplatz bringen sollt und auf einen Haufen werfet, auf das ich mich daran bereichere zu Eurem Seelenheil.\r\n§ 4. Das ihr einen weiteren Zehnten Teil eures Goldes oder Silber zum Schmied bringet, auf das er es einschmelze und ihr mir zu Ehren eine Statue zu meinem Ebenbild schafft, das ihr während meiner Abwesenheit verehren und anbeten könnt zu Eurem Seelenheil.\r\n§ 5. Das ihr die Nachtelfen, die in dieser Stadt brüten, beim Schopf ihrer Haare packet, sie mit Pech oder Teer übergiesset, mit Gänsefedern bedecket und hernach mit Weidenruten auf die Fußsolen schlaget und aus der Stadt jaget auf dass sie nimmer wiederkehren. Dies geschehe zu eurem Seelenheil.\r\n§ 6. Das Eure Männer arbeiten auf dem Lande, am Wasser und in der Erde, um mir die Früchte des Feldes und des Meeres zu bringen. Aus dem Felsen sollen sie Gold und Silber schürfen und Eure geschicktesten Schmuckschmiede sollen mir Ketten, Armbänder, ein Szepter und eine mächtige, mit Juwelen verzierte Krone fertigen die mein erleuchtetes Haupt schmücken wird. Dies geschehe zu eurem Seelenheil.\r\n§ 7. Das ihr Eure Söhne in die Steinbrüche schicket und die Maurer unter Euch mir einen Palast erbauen mit sechs Burgfrieden und 29 Höfen und 67 Türmen, wovon der höchste mit der Spitze die Sonne berührt. Darin werde ich wohnen und über euch Wachen zu eurem Seelenheil.\r\n§ 8. Das eure Frauen mir die Speisen anrichten werden, die ich ihnen auftrage: Montags Lammbraten, Dienstags Pfefferspiesse vom Klippeneber, Mittwochs gefüllte Granatapfel, Donnerstags Krautrouladen, Freitags Loch-Scholle in sanfter Fenchel-Zitronensauce, Samstags eine gemischte Grillplatte und Sonntags einen festlichen Braten vom Spanferkel mit verschiedenen Gemüsen der Saison. Dazu eine Auswahl von Desserts und Aperitifs sowie etwas Obsttorte für meinen Assistenten, die er so gerne mag. Dies geschehe zur meiner Sättigung und zu eurem Seelenheil.\r\n§ 9. Das ihr Eure Töchter, sobald sie das sechzehnte Lebensjahr vollendet, gut gewachsen und in Lesen und Schreiben unterrichtet, auf den Marktplatz schicken sollt, auf das ich mir eine heraussuche, die meine Gespielin für diesen Tag sein wird. Dies geschehe jeden Tag aufs neue zu eurem Seelenheil.\r\n§ 10. Das ihr euch einmal in der Woche vor meinem Palast versammelt und meinen weisen Worten lauscht und ohne Widerrede ausführt, was ich euch auftrage zu eurem Seelenheil bis an euer Lebensende.",},
			["Antu'sul"] = { content = "'''Antu'sul''', der Vorarbeiter von Sul, ist ein [[Troll Schamane]] in [[Zul'Farrak]]. Dieser Boss ist ein [[Sandtroll]] mit bronzefarbenen Haaren vom Stamme der [[Sandwüter]], der über die Diener von Antu'sul herrscht. Als Waffe trägt er , die man auch von ihm erbeuten kann, und wacht über , eine Hälfte des berühmten Schwertes [[Sul'thraze]]. \r\n==Fähigkeiten==\r\nZu seinen Fähigkeiten gehören: \r\n* '''Blitzheilung''' - Blitzheilung heilt ein befreundetes Ziel um 518 bis 616.\r\n* '''Heilungszauberschutz''' - Heilungszauberschutz beschwört einen Zauberschutz, der 30 Sekunden lang anhält und regelmäßig alle Verbündeten in der nächsten Umgebung heilt. \r\n* '''Kettenblitzschlag''' - Kettenblitzschlag schleudert einen Blitzschlag auf den Feind, der 378 bis 424 Naturschaden verursacht und zu in der Nähe befindlichen Feinden weiterspringt. Jeder Sprung verringert den Schaden um 30%. Wirkt auf insgesamt 3 Ziele. \r\n* '''Totem der Feuernova''' - Totem der Feuernova beschwört ein Totem der Feuernova mit 5 Gesundheit, das 5 Sekunden lang anhält. Wenn es nicht innerhalb von 4 Sekunden zerstört wird, fügt das Totem Feinden in einem Umkreis von 10 Metern 281 bis 317 Feuerschaden zu. \r\n* '''Totem des Erdengriffs''' - Totem des Erdengriffs beschwört ein Totem des Erdengriffs, das 30 Sekunden lang bestehen bleibt und in der Nähe befindliche Feinde in regelmäßigen Abständen bewegungsunfähig macht. \r\n'''Quellen'''",},
			["Anub'arak"] = { content = "'''Anub'arak''' war als lebender der [[Neruber König]] von [[Azjol-Nerub]]. Er fiel im [[Krieg der Spinne]] und wurde, wie die anderen [[Neruber]], mumifiziert und vom [[Lichkönig]] [[Ner'zhul]] als Untoter [[Gruftlord]] wiedererweckt. Anub'arak war einer der Ersten, welcher unter dem Befehl des [[Lichkönig]]s diente und wurde so zum Herren der [[Gruftbestie]]n. \r\nAls [[Arthas]] am Fusse des Gletschers [[Eiskrone]] der Armee von [[Illidan]] gegenüberstand, wurde Anub'Arak gesendet um die Interessen seines Meisters, dem [[Lichkönig]], zu schützen und [[Arthas]] auf den Treppenstufen seines Schicksals zu begleiten. Seit der Niederlage von [[Illidan]] dienen die untoten [[Neruber]] [[Arthas]] als neuem Meister und gehören der untoten Armee an.\r\nZwischen [[Arthas]] und Anub'arak gibt es viele Parallelen:\r\n* Beide verrieten ihr Volk für ihre Dienste am [[Lichkönig]] (Oder wurden zumindestens als Verräter betrachtet)\r\n* Beide waren adelig (Prinz und König)",},
			["Anub'rekhan"] = { content = "#REDIRECT [[Anub'Rekhan]]", redirect = "Anub'Rekhan",},
			["Anubisath"] = { content = "==Hintergrund==\r\nDie [[Trolle]] waren das erste sterbliche Volk, das sich den uralten, hinterlistigen [[Aqir]] entgegenstellte und sich gegen ihre Macht behaupten konnte. Nach tausenden von Jahren schafften die [[Trolle]] es, das Reich der Insekten zu spalten und die [[Aqir]] in die nördlichen und südlichen Regionen von [[Kalimdor]] zu vertreiben. Doch das mächtige Reich der [[Trolle]] zerfiel mit der Zeit, während sich die [[Aqir]] in [[Silithus]] zu einem neuen, furchterregenden Volk weiterentwickelten: Den [[Qiraji]]. \r\n===Zweck===\r\nLegenden zufolge, beschlossen die [[Zwillingsimperatoren]] [[Vek'lor]] und [[Vek'nilash]] nach dem Krieg, dass loyale Soldaten von großer Macht benötigt würden, die sich jeglichen zukünftigen Feinden entgegenstellen könnten. Es wird behauptet, dass die [[Zwillingsimperatoren]] höchstpersönlich die Konstruktion der ersten Anubisaths in den ewig brennenden Feuern unter [[Ahn'Qiraj]] überwachten. Dennoch wurden die kolossalen Krieger über Jahrtausende hinweg nicht fertig gestellt. Nachdem der [[Brunnen der Ewigkeit]] im [[Krieg der Uralten]] zerstört wurde, gingen die wenigen verbleibenden Geschichten über die einst gefürchteten [[Aqir]] verloren. Und so warteten die [[Qiraji]] geduldig auf den richtigen Zeitpunkt, um auf eine unvorbereitete Welt losschlagen zu können. So geschah es also, dass die Imperatoren vor tausend Jahren einen erneuten Eroberungsfeldzug gegen [[Kalimdor]] starteten. Dieses Mal waren ihre neuesten Kriegsmaschinen bereit und die [[Qiraji]] demonstrierten der reichen Kultur der [[Nachtelfen]] ihre volle Macht. \r\n===Fähigkeiten===\r\nEin einzelner Anubisath konnte in den meisten Fällen mit Leichtigkeit eine ganze Einheit von [[Schildwache]]n vernichten. Obwohl sie nur über minimale Intelligenz verfügten, erwiesen sich die kolossalen Krieger als überaus effektive Vernichtungsmaschinen. Während die stärksten dieser Konstrukte die Rolle von Elite-Stoßtrupps erfüllten, platzierte [[General Rajaxx]] die meisten der Anubisaths an der vordersten Front, wo sie die Herzen der Elfen mit Furcht erfüllen sollten. \r\n==Untergang==\r\nAls die [[Nachtelfen]] den Krieg zu verlieren drohten, überredete der Erzdruide [[Fandral Hirschhaupt]] den [[Bronzener Drachenschwarm|Bronzenen Drachenschwarm]] dazu, ihnen im Kampf beizustehen. Die [[Drachen]] stürzten sich in das fieberhafte Kampfgetümmel außerhalb von [[Ahn'Qiraj]] und ließen die Anubisathkonstrukte ihren ganzen Zorn spüren. Die wenigen Anubisaths, die Zaubersprüche wirken konnten, waren weit von den vordersten Frontlinien entfernt, und so konnten die [[Drachen]] die riesenhaften Konstrukte aus der Sicherheit der Luft angreifen, ohne effektive Gegenwehr befürchten zu müssen. So gut wie alle Anubisaths wurden während der ersten Angriffswelle der [[Drachen]] ausgelöscht, allerdings bewies einer von ihnen mehr Einfallsreichtum, als alle anderen zusammen ... [[Ossirian]].\r\n==Persönlichkeiten==\r\n* [[Ossirian]]",},
			["Anveena"] = { content = "#REDIRECT [[Anveena Teague]]", redirect = "Anveena Teague",},
			["Anveena Teague"] = { content = "'''Anveena Teague''' ist die reinkarnierte Kraft des [[Sonnenbrunnen]]s. Sie wurde Von dem [[Magier]] [[Borel]], der in Wirklichkeit der [[Drache]] [[Korialstrasz]] war, geschaffen, kurz bevor [[Arthas]] die Macht des Sonnenbrunnens nutzte, um [[Kel'Thuzad]] zu erwecken. Allerdings sah der Drachenmagier nicht vorraus, das Anveena eine eigenständige Person werden würde. Ihre Geschichte ist in der \"[[Sunwell Trilogy]]\" niedergeschrieben.",},
			["Anzu"] = { content = "'''Anzu''' ist der Rabengott der [[Arakkoa]]. Man kann ihn in [[Auchindoun]] in den [[Sethekkhallen]] beschwören. Sein erwählter Champion war [[Terokk]] und sein Bruder [[Rukhmar]]. Wie man seinem Ruf in den Sethekkhallen bei seiner Beschwörung entnehmen kann, hat Anzu offensichtlich vor, die Herrschaft über den [[Smaragdgrüner Traum|Smaragdgrünen Traum]] an sich zu reißen. Nachdem [[Malfurion Sturmgrimm]] seine Essenz geteilt und sich damit geschwächt hat, hat er dem Rabengott die Tür zur Herrschaft über den Smaragdgrünen Traum geöffnet. Nun fordert ihn der Aspekt des Raben bei Sturmgrimms Grabhügel auf der [[Mondlichtung]] offen heraus.\r\n==Die Prophezeiung des Rabengottes==\r\nAus der dunkelsten Nacht wird wieder der Rabe, trifft Flug in den Schatten, so zeigen die Natur von ihrer Art. Bereitet Euch vor auf die Kommenden, für die Gläubigen wird erhöht, um den Flug mit Rabe, den Rest vergessen werden, zu Fuß auf den Boden, abgeschnittene Flügel und Scham. Stahl seien eure Seelen und Schützen Sie Ihre Gedanken. Die Flügel der Dunkelheit werden die Erdensklaven, die Schwachen, vernichten deren Füße können nie den Boden verlassen. Das alte Blut fließt wieder mit dem Kommen des Raben, die Rückkehr der Dunkelheit in den Himmel. Einmal flog der Rabe zu hoch. Die Äonen vorbereitet haben, das der Dunkle Beobachter für seinen Aufstieg, zu ziehen die dunklen Mantel über dem Horizont.",},
			["Apa'ro"] = { content = "Apa'ro ist der Name der [[Tauren]] für den Halbgott '''[[Malorne]]'''.",},
			["Apexis"] = { content = "#REDIRECT [[Arakkoa der Apexis]]", redirect = "Arakkoa der Apexis",},
			["Apexismonumente"] = { content = "Die kleineren [[Apexrelikte]] im westlichen Plateau im [[Schergrat]] umgeben noch größere Relikte. Diese großen Apexismonumente funktionieren auf die exakt gleiche Weise, allerdings werden wesentlich mehr [[Apexissplitter]] benötigt, um sie zu aktivieren und vier Personen um sie zu bedienen. Viel größere Sorgen bereiten die Wächter, die bei der Benutzung eines Relikts beschworen werden. Diese Kristallkonstrukte haben sich vor langer Zeit gegen ihre [[Arakkoa]]meister gewendet und gefährden nun [[Ogri'la]]. Man kann jederzeit mit einer Gruppe zurückkehren, um die großen Apexismonumente zu benutzen, wenn man genügend Apexissplitter mitbringt, um sie aktivieren zu können.",},
			["Apexisrelikt"] = { content = "#REDIRECT [[Apexisrelikte]]", redirect = "Apexisrelikte",},
			["Apexisrelikte"] = { content = "Vor langer Zeit lebte im westlichen Plateau im [[Schergrat]] eine Sekte der [[Arakkoa]], die [[Arakkoa der Apexis|Apexis]]. Überreste ihrer seit langem ausgestorbenen Zivilisation sind auch heute noch allgegenwärtig. Man nennt sie Apexisrelikte. \r\nDas Einzige, was man mit Sicherheit weiß, ist, dass sie bei richtiger Benutzung einen Segen gewähren. Jedes Relikt repräsentiert eine farbige Sequenz, welche, wenn man die Kristalle in der richtigen Reihenfolge drückt, zu einer Serie von Stufen führen, eine schwieriger als die andere. \r\nEs wird immer ein [[Apexissplitter]] benötigt, um das Relikt zu aktivieren. Nachdem man die erleuchtenden Schwingungen der Apexisrelikte am eigenen Leib erfahren hat, kann man ein tieferes Verständnis für die Funktionsweise der Relikte zu bekommen. Je mehr die Fähigkeiten wachsen, sich auf die Kräfte der Relikte einzustellen, desto mehr Wissen wird man über sie erlangen.",},
			["Apexissplitter"] = { content = "Beim richtigen Umgang mit den Kristallen der Berge im westlichen [[Schergrat]] weisen diese seltsame Kräfte auf, wie zum Beispiel die Klarheit des Geistes, die sie in [[Ogri'la]] entdeckt haben. Alle Kreaturen oben auf den Bergen begehren danach und benutzen die Apexissplitter, um ihre eigenen Ziele voranzutreiben. Der Wert dieser Kristalle hat sogar eine regelrechte Wirtschaft aufkommen lassen. Nicht nur die Kreaturen im [[Schergrat]] besitzen welche, gelegentlich findet man sie auch bei den großen Kristallen, dort, wo die Hetzer graben. Der Wert dieser Splitter liegt nicht in ihrem Verkaufspreis. Es ist nicht einmal das, was sie tun können, sobald sie ordnungsgemäß zusammengeschmiedet wurden... auch wenn sich darüber streiten lässt. Der wahre Wert liegt in dem Unterfangen, das es auf sich zu nehmen gilt, um in den Besitz dieser Splitter zu gelangen.",},
			["Apotheker"] = { content = "Ein Untoter '''Apotheker''' oder manchmal auch '''Dunkler Apotheker''', ist ein Mitglied der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] von [[Unterstadt]]. Alle Personen mit diesem Titel haben gemeinsam, dass sie zum Volk der [[Verlassene]]n gehören und über großes [[Alchimist|alchimistisches]] Wissen verfügen. Einige der Apotheker haben sich auch als sogenannte [[Seuchenbringer]] spezialisiert.",},
			["Apothekerin Zamah"] = { content = "'''Apothekerin Zamah''' ist ein Mitglied der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] bei den Teiche der Visionen in [[Donnerfels]]. Sie ist eine Gelehrte und Botschafterin der [[Verlassene]]n. Die Königliche Apothekervereinigung hat sie geschickt, um eine ganz besondere Aufgabe zu erledigen, denn sie studiert seit kurzem eine rare Pflanzenart namens [[Schlangenflaum]]. Sie denkt, dass Schlangenflaum in größeren Mengen außerordentliches Potenzial für eine neue Seuche besitzt. Leider findet man ihn nur in den dunkelsten Winkeln der [[Höhlen des Wehklagens]].",},
			["Apothekerin Zelana"] = { content = "'''Apothekerin Zelana''' von der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] hat ihr Lager auf der [[Höllenfeuerhalbinsel]] beim [[Häschersturz]] hinter den [[Flügeldrachen]] aufgeschlagen. Sie hat Untersuchungen bezüglich der Kreaturen auf der [[Höllenfeuerhalbinsel]] angestellt und ist sehr an einer Probe des Blutes eines [[Orcs der Knochenmalmer|Knochenmalmers]] interessiert. Mit ein wenig Glück wird sie herausfinden können, was die Haut des [[Knochenmalmer Klan]]s rot werden ließ und wie diese [[Orcs]] der Verderbnis der [[Dämonen]] anheim fallen konnten. Doch ihre Ausrüstung hier ist leider nicht für alle Tests, die sie durchführen möchte, geeignet.",},
			["Apothekerin Zinge"] = { content = "'''Apothekerin Zinge''' von der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] befindet sich im [[Apothekarium]] von [[Unterstadt]]. Sie hat eine Wolfherzprobe für [[Apotheker Helbrim]] im [[Brachland]] vorbereitet und wenn die ersten Berichte wahr sind, kann die Giftigkeit der Worgherzen ihnen weiteren Fortschritt im Wissen über Gifte bringen. Später schickt sie Freiwillige auf ins Feld zu [[Chefingenieur Bilgenritzel]] in [[Gadgetzan]]. Mit ihm sollen sie über eine Kraftquelle für das Testset sprechen, ehe sie sich in die [[Tanaris]]wüste begeben und die Gewebebeschaffenheit der Basilisken, Skorpiden und Hyänen testen, die dort heimisch sind. Die Goblins von Gadgetzan verfügen über eine Kraftquelle, die mit dem modifiziertem Set verwendet werden muss.",},
			["Apothekermeister Faranell"] = { content = "Apothekermeister Faranell ist der Leiter der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]].\r\nZu Lebzeiten war er ein bekannter [[Alchimist]] und studierte fast sein ganzes Leben lang bei den gelehrten Hexern von [[Dalaran]]. Nichts bereitete ihm mehr Vergnügen, als mit Gebräuen aller Art zu experimentieren, da er stets auf der Suche nach einem Serum für das ein oder andere Gegengift war. Nachdem er an der Seuche gestorben und als einer der [[Verlassene]]n wiederauferstanden war, entstellte ein unvorstellbarer Sadismus seine grenzenlose Neugier. Jetzt stellt Faranell seine Fertigkeiten Königin [[Sylvanas Windläufer]] zur Verfügung, erzeugt alchimistische [[Monstrosität]]en (er war der erste, der sie rein alchemistisch erzeugen konnte) und entwirft immer neue, noch verheerendere Seuchen und Toxine.",},
			["Apotheker Berard"] = { content = "Als [[Arugal]] seine elenden Zauber über den [[Silberwald]] gelegt hat, verfluchte er eines der viel versprechendsten Mitglieder der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]]: '''Apotheker Berard'''. Als hirnloser Diener von [[Arugal]] ist Berard jetzt für die [[Verlassene]]n nutzlos. Aber seine Erkenntnisse könnten sich als wertvoll erweisen, z.B. für [[Apotheker Renferrel]]. Er untersuchte eine längst vergessene Seuche, die vor Ewigkeiten einmal alles Leben im [[Lordameresee]] getötet hat. Berards Tagebuch liegt in seinem Studierzimmer im Gasthaus von [[Lohenscheit]] und laut diesem Tagebuch könnte sich das Moos von [[Bäumling|Seeschleicher]]n und [[Bäumling|Seekrabbler]]n bei der Suche nach einer neuen Seuche als nützlich erweisen.",},
			["Apotheker Faustin"] = { content = "Apotheker Faustin von der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] hat zusammen mit Todespirscher Zraedus ein Lager im [[Bettlerschlupfwinkel]] im [[Dämmerwald]]. Um den [[Orcs]] in [[Steinard]] beim Verhör eines im [[Bettlerschlupfwinkel]] gefaßten menschlichen Spitzels behilflich zu sein, schwebt ihm genau das richtige Serum vor. Es wird die Wahrheit genau so behandeln, wie die Wahrheit behandelt werden sollte. Für dieses Gebräu braucht er mehrere Schattenpantherherzen aus dem Sumpf. Außerdem braucht er den verzauberten Fungus des Morastlords, der dort haust. Die schwierigste Aufgabe wird sein, einen Tiefschreitertumor aus dem fernen [[Desolace]] zu beschaffen. Nur sehr selten werden die Riesen dort krank, sodass ein Tumor entsteht.",},
			["Apotheker Lydon"] = { content = "'''Apotheker Lydon''' ist ein angesehenes Mitglied der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] in [[Tarrens Mühle]]. \r\nIm [[Vorgebirge des Hügellands]] blühen die Blumen und die Luft ist so klar und rein ... und er muss in diesem ganzen Elend baden. Er sieht aus seinem verdreckten Fenster und sehnt den Tag herbei, an dem ihre neue Seuche dieser Welt ihren wohlverdienten Tod bringt. So gern er auch den ganzen Tag hier herumsitzen und mit Grübeln verbringen würde, seine Pflicht gegenüber der dunklen Fürstin ruft ihn. Wenn er was zu sagen hätte, würde er diese lächerlichen [[Menschen]] und die [[Geißel]] die Sache einfach unter sich ausmachen lassen. Sie scheinen ohnehin absolut darauf versessen zu sein, sich gegenseitig umzubringen. Aber leider hat es sich ihre dunkle Fürstin in den Kopf gesetzt, das Ganze ein wenig zu beschleunigen. Also warum diese düsteren Tage nicht dazu nutzen und hier ein wenig Tod und Krankheit verbreiten?\r\n==Forschungen == \r\nFür ihn gibt es nichts Schöneres in diesem elendiglichen [[Vorgebirge des Hügellands|Vorgebirge]], als ein wenig Leiden in die Welt zu bringen. \r\n* [[Elixier der Pein]]\r\n* [[Elixier der Schmerzen]]\r\n* [[Elixier des Leidens]]\r\n* Das [[Blut Unschuldiger]]\r\n===Gift für [[Unterstadt]]===\r\nDas Gift vom Spinnengott der [[Trolle der Bleichborken]]: [[Shadra]] ist ein großer Fund. Er konnte mit nur einem Tropfen von dem Zeug fast zwei Dutzend Hasen töten. Er würde gern eine Probe zu seinem Vorgesetzten, [[Apothekermeister Faranell]], in das Apothekarium von [[Unterstadt]] entsenden.",},
			["Apotheker Renferrel"] = { content = "'''Apotheker Renferrel''' ist ein [[Alchimist]] der [[Verlassene]]n beim [[Grabmal]] im [[Silberwald]], der dort für die [[Königliche Apothekervereinigung]] arbeitet. \r\nArthas hat Truppen von schier endloser Zahl. Doch mit einer neuen Seuche könnten die Apotheker sowohl die Armee der Geißel als auch das menschliche Ungeziefer ein für alle Mal auslöschen. Also forscht Renferrel an einem Rezept für den Tod. Seine Studien haben bewiesen, dass Spinnenblut, vermischt mit einem aus dem Herzen eines ergrauten Bären gewonnenen Toxin, zu einem tödlichen Elixier wird. \r\nIm Zuge dessen ist Renferrel nicht nur auf der Suche nach den Ursprüngen der [[Gnolle der Moderfelle]], sondern auch nach [[Apotheker Berard]]s Tagebuch aus [[Lohenscheit]], um vom Wissen des ehemals versprechendsten Mitglied der Apothekervereinigung noch zu profitieren. Seine Erkenntnisse könnten sich als wertvoll erweisen, denn er untersuchte eine längst vergessene Seuche, die vor Ewigkeiten einmal alles Leben im Lordameresee getötet hat. Laut Berards Tagebuch könnte sich das Moos von Seeschleichern und Seekrabblern bei der Suche nach einer neuen Seuche als nützlich erweisen. Diese Bestien leben auf den Inseln im [[Lordameresee]] im Osten. Er erwähnt außerdem einen sehr seltenen verhärteten Tumor, den er bei einem der [[Murlocs der Finsterflossen]] entdeckte. Anscheinend war der Tumor so selten, dass Berard nur einen einzigen auftreiben konnte und Apotheker Renferrel würde sowohl das Moos als auch diesen Tumor sehr gern untersuchen.",},
			["Aqir"] = { content = "Die Aqir waren raffinierte, expansionistische Insektoiden, die im antiken [[Kalimdor]] heimisch waren.\r\n16,000 Jahre vor der Orkischen Invasion auf [[Azeroth]] bestand die Welt noch aus einem großen Kontinent, umgeben vom Großen Meer. Die antiken [[Titanen]] hatten den Kontinent [[Kalimdor]] genannt und in seiner Mitte platzierten sie den [[Brunnen der Ewigkeit]]. Der Brunnen sollte die Quelle des Lebens für diese Welt sein. \r\nEs geschah in dieser Welt, dass die [[Trolle]] die östlichen Länder beherrschten. Sie waren nicht länger eine vereinte Rasse und hatten im Norden das [[Amani]] Imperium aufgebaut, während ihre Brüder im Süden das [[Gurubashi]] Imperium errichteten. Diese [[Trolle]] hatten es geschafft eine lockere Allianz zu bilden, die es ihnen erlaubte, ihre Länder gegen eine viel größere Bedrohung zu verteidigen, die die Kontrolle des Westlichen Teils von Kalimdor übernommen hatte. Diese Bedrohung kam aus einem dritten Imperium - der Zivilisation von Azi Aqir.\r\nDie Aqir waren intelligente Insektoiden, vom Alten Gott [[C'Thun]] nach dem Bild der [[Silithiden]] erschaffen, die die Länder des weiten Westens beherrschten. Diese raffinierte Insektoiden waren außerordentlich expansionistisch und unglaublich böse. Die Aqir rotteten alles nicht-insektoide Leben auf den Feldern von [[Kalimdor]] aus. \r\nDie [[Trolle]] bekämpften sie viele tausende Jahre, aber konnten nie einen wahren Sieg über die Aqir gewinnen. Schließlich, aufgrund der Hartnäckigkeit der [[Trolle]], spaltete sich das Aqiri Königreich, als seine Bewohner flohen, um die Kolonien in den weiten nördlichen und südlichen Regionen des Kontinents zu trennen. Zwei Aqiri Städte tauchten auf - [[Azjol-Nerub]] in den nördlichen Einöden und [[Ahn'Qiraj]] in der südlichen Wüste. \r\nObwohl die [[Trolle]] vermuteten, dass es weitere Aqiri Kolonien unter [[Kalimdor]] gab, wurde ihre Existenz nie bestätigt. Möglicherweise wurden aufgrund der Umgebung aus den zwei Gruppen schließlich vollständig verschiedene Wesen, obwohl es unbekannt bleibt, ob diese Trennung immer existiert hatte. Die Spinnen-ähnlichen [[Neruber]] bevölkern die nördliche Stadt [[Azjol-Nerub]], während die mehr humanoiden [[Qiraji]] ihren Sitz in [[Ahn'Qiraj]] haben.",},
			["Aquantion"] = { content = "Jedes Jahr haben die Einwohner von Sonnenkuppe in den [[Geisterlande]]n, an einem Ritual teilgenommen, um die verschiedenen Aspekte der Natur unter ihrer Kontrolle zu halten. Die Herrschaft über das Wasser wurde symbolisiert durch die Beschwörung und Versklavung eines [[Wasserelementar]]s namens Aquantion. Aber es gelang ihm, ihre Magie gegen sie zu wenden, seine Fesseln abzuwerfen und stattdessen die [[Blutelfen]] zu versklaven. Dieser eigenwillige [[Elementar]] hat viele Leben auf dem Gewissen. Indem er die [[Murlocs]] dazu brachte, ihre Rituale zu sabotieren, wendete er ihre Magie gegen die [[Blutelfen.]]",},
			["Aquementas"] = { content = "In der Mast- und Schotbucht in einen Kreis aus Steinen liegt das Geheimnis von Aquementas: Das [[Buch von Aquor]]. Es beschwört das einzige Wesen, das das Silbertotem von Aquementas herstellen kann, mit dem man das [[Feuerelementar]] [[Sturmflamme]] bekämpfen kann. Doch es wird Aquementas nicht gefallen, dass man ihn aufweckt...",},
			["Ar'tor"] = { content = "#REDIRECT [[Ar'tor Herzeleid]]", redirect = "Ar'tor Herzeleid",},
			["Ar'tor Herzeleid"] = { content = "'''Ar'tor Herzeleid''' ist ein Sohn des [[Oronok]], der sich bei der [[Stätte der Illidari]] im [[Schattenmondtal]] versteckt hielt, um nach der [[Litanei der Verdammnis]] zu suchen. Auch wenn Ar'tor ein ausgezeichneter [[Jäger]] und Fährtenleser ist, befürchtet sein Vater [[Oronok]], dass er sich dieses Mal übernommen hat. Und er soll Recht behalten, denn Ar'tors Körper hängt leblos in der Luft. Man weiß nicht, wie lange er schon tot ist. Der Einschätzung nach wird Ar'tors Körper von der Energie einiger Kristalle, die um eine Rune herum schweben, in der Luft gehalten, doch Ar'tor lässt sich nicht bewegen. Es fällt auf, dass die Kristalle im unteren Teil eine Vertiefung aufweisen, vielleicht für einen Schlüssel. Neben den Kristallen scheinen [[Sukkubi]] regelmäßig eine Art Ritual durchzuführen. \r\n''Lohn'goron'' - Ar'tors Bogen des Herzeleid ist ein Familienerbstück, das seit Generationen von Herzeleid zu Herzeleid weitergegeben wurde. Der Name Lohn'goron bedeutet in seiner Sprache 'Heldenruh'.",},
			["Arachnatid"] = { content = "Arachnatiden sind eine Art pelziger [[Skorpion]]e, die von den [[Neruber]]n gezähmt wurden.Sie haben ihre Nester in Höhlen und unter Steinen. Die [[Neruber]] setzten sie für niedere Wachdienste an z.B Schaltern ein.Obwohl Arachnatiden nicht intelligent sind, können sie doch planen und kommunizieren mit raspelnden Geräuschen mitanander.Sie überfallen einsame Wanderer und fressen ihr Fleisch.Sie schleudern ihre stacheligen Haare nach Feinden, um sie zu lähmen.\r\nDie [[Kirin Tor]] fingen einige dieser Wesen , um sie zu studieren.",},
			["Araj der Beschwörer"] = { content = "Der [[Lich]] - '''Araj der Beschwörer''' herrscht in den [[Westliche Pestländer|Westlichen Pestländern]] von dem ruinierten Herzen der Stadt aus über [[Andorhal]]. Er war der ehemalige Kopf der [[Scholomance]], bevor er die Stadt an sich riss. Er wird von zahlreichen Angehörigen der [[Geißel]] bewacht, die über die Überreste des Stadtzentrums wachen und auch sein Gefolge an Leibwächtern ist ausgezeichnet. Die Beschwörungskristalle in den Wachtürmen von [[Andorhal]] geben dem [[Lich]] die Kraft, die er zur Kontrolle der Stadt benötigt. Wenn man alle vier ausschaltet, dürfte der Lich selbst auftauchen, um das Herz der Stadt zu verteidigen.",},
			["Arakkoa-Krallenpriester"] = { content = "=== Krallenpriester===\r\nDie Krallenpriester halten die Geister der Ahnen gefangen und verehren dunkle Mächte. In ihren Ritualen opfern sie die Arakkoa der niederen Kasten. Die Krallenpriester sehnen Terokks Rückkehr herbei und möchten ihren Helden zurück aus dem Jenseits der Zeit holen.",},
			["Arakkoa"] = { content = "Das Volk der Vogelmenschen, die Arakkoa, verfügen über uraltes arkanes Wissen.Sie sind die Kinder von [[Anzu]] und [[Rukhmar]], den Rabengöttern. Sie sind hochintelligente Wesen ... gerissen wie ein Gnom. Nur, dass sie über ein ausgesprochen aggressives Gemüt und sehr mächtige Magie verfügen. Ihre Magie ist stark und sie schaffen es oft, ihren Verfolgern zu entkommen. Doch ihr Volk ist wütend, und niemand kann viel dagegen tun. Einige von ihnen wurden von der Macht der [[Naaru]] berührt und für alle Zeiten verändert. Doch diejenigen von ihnen, die in der Wildnis leben, sind noch immer so, wie sie damals waren. Und wenn die Berührung der gesegneten [[Naaru]] nicht ausreicht, um die Arakkoa zu erlösen, dann kann nichts auf der Welt das schaffen. Diejenigen, die ihre Seele nicht dem Licht ausgeliefert haben, sind nichts als Diener des Bösen und müssen vernichtet werden.\r\n==Kolonien==\r\n* [[Arakkoa der Apexis]]\r\n* [[Arakkoa der Ala'rak]]\r\n* [[Arakkoa der Grishna]]\r\n* [[Arakkoa der Haal'eshi]]\r\n* [[Arakkoa der Lashh'an]]\r\n* [[Arakkoa der Lithic]]\r\n* [[Arakkoa der Reskk]]\r\n* [[Arakkoa der Rhaze]]\r\n* [[Arakkoa der Ruuan'ok]]\r\n* [[Arakkoa der Sethekk]]\r\n* [[Arakkoa der Shalas]]\r\n* [[Arakkoa der Shi'lak]]\r\n* [[Arakkoa der Shienor]]\r\n* [[Arakkoa der Sketh'lon]]\r\n* [[Arakkoa der Skith]]\r\n* [[Arakkoa der Vekh'nir]]\r\n* [[Skettis]]\r\n==Religion==\r\n* [[Dunkler Rat]]\r\n* [[Krallenpriester]]\r\n* [[Schattenstaubelixier]]\r\n==Persönlichkeiten==\r\n* [[Dunkelwirker Syth]]\r\n* [[Kirrik der Erwachte]]\r\n* [[Klauenkönig Ikiss]]\r\n* [[Terokk]]",},
			["Arakkoa der Ala'rak"] = { content = "=== Arakkoa der Ala'rak===\r\n* '''Ort''': [[Wälder von Terokkar]]\r\n* '''Anführer''': Krallenpriester Ishaal, Skizzik und Zellek\r\nDas Ala'rakversteck findet am östlichen Ufer des Schattenwindsees. Schon seit geraumer Zeit versucht die [[Himmelswache der Sha'tari]] die Kommandokette der [[Skettis]] aufzudecken und sie zu zerschlagen. Sie wussten von der Existenz dreier Kleriker, den Krallenpriestern Ishaal, Skizzik und Zellek, jedoch haben sie niemals einen von ihnen zu Gesicht bekommen.",},
			["Arakkoa der Apexis"] = { content = "Vor langer Zeit lebte im [[Schergrat]] eine Sekte der [[Arakkoa]], die Apexis. Überreste ihrer seit langem ausgestorbenen Zivilisation sind auch heute noch allgegenwärtig. Man nennt sie [[Apexisrelikte]]. Doch das Einzige, was man mit Sicherheit weiß, ist, dass sie bei richtiger Benutzung einen Segen gewähren. Es wird ein [[Apexissplitter]] benötigt, um das Relikt zu aktivieren. Auch einige [[Apexismonumente]] sind erhalten aus den Hochzeiten dieser Zivilisation.",},
			["Arakkoa der Grishna"] = { content = "Grishnath ist ein Dorf der [[Arakkoa]] und liegt im [[Rabenwald]] im [[Schergrat]]. Hier können die [[Arakkoa]] der Grishna mit Hilfe der Totems, die die Orakel des Raben aufgestellt haben, die Worte des Rabengottes hören. Die Grishna sind dafür verantwortlich, dass die [[Treants]] der Laubbärte und Steinborken von bösen Koikoigeistern übernommen werden. Sie tragen außerdem merkwürdige magische Kugeln mit sich. Diese sind von einem unheimlichen violetten Leuchten umgeben und pulsieren zu einem unhörbaren Takt.",},
			["Arakkoa der Haal'eshi"] = { content = "Das Versteck der [[Arakkoa]] der Haal'eshi befindet sich im Westen der [[Höllenfeuerhalbinsel]] im Haaleshbau, hinter der großen Kluft. Die [[Arakkoa]] haben hier eine besonders prächtige Art von Vögeln, namens Kaliri domestiziert und gezüchtet und ihre Federn würden in den Handelsposten [[Azeroth]]s einen ganz schönen Batzen Gold einbringen. Einer Falknerin der [[Blutelfen]] ist es gelungen, ein junges Kaliri-Männchen einzufangen und sie scheinen zähmbar zu sein, die weiblichen Exemplare sind jedoch deutlich seltener.\r\n==Gebrüder Langbart==\r\nIn letzter Zeit haben [[Arakkoa]]-Banditen häufiger Patrouillen der [[Ehrenfeste]] und viele der Versorgungskarawanen überfallen. Deswegen hat die [[Allianz]] ein paar [[Zwerge]] angeheuert, die sich um sie kümmern sollten. Es waren Brüder, wobei Gremmi Langbart der Älteste von ihnen war. Sie sind losgezogen und nie zurückgekehrt. Sie haben mehr Bier als Essen oder Munition eingepackt, bauten ihr Lager auf und dachten sich hey, schön hier. Sie hatten keine Ahnung, dass sie so nahe bei den [[Felshetzer|Stachelklauenfelshetzern]] sind. Sie sind erbarmungslose Raubtiere und haben jegliche Arbeit der [[Zwerge]] zunichte gemacht. Gremni Langbart ist ein weltbekannter [[Scharfschütze]], doch Mirren und er sind eher auf Federvieh und Turniere spezialisiert, nicht auf Blitze schleudernden [[Arakkoa|Vogelmenschen]]. In diesen Zeiten vertraut Mirren nicht vielen Leuten und vor kurzer Zeit haben sie auch noch einen der ihren an die [[Arakkoa]] verloren. Das hat ihn etwas nervös gemacht. \r\n==Personen==\r\n* Avruu – Magier der Haal’eshi\r\n* Gremni Langbart\r\n* Mirren Langbart",},
			["Arakkoa der Lashh'an"] = { content = "Die Magie der [[Arakkoa]] der Lashh'an im [[Lashhversteck]] im [[Schergrat]] ist unnatürlich. Sie reißen sich ganze Hände voll - oder Klauen voll - ihrer eigenen Federn als Reagenz heraus. Ihre Zauberbücher befinden sich hoch oben in den Bäumen und die Piktogramme darin deuten darauf hin, dass ihre Federn für das Wirken der Zauber in den Zirkeln der Macht benutzt werden. Verwirrende Bilder scheinen einen [[Arakkoa]] zu zeigen, der vom Geist eines [[Kaliri]] eingehüllt wird. Dieser Zauber ist sehr merkwürdig, denn es handelt sich nicht um eine einfache Beschwörung oder Verzauberung, sondern eher um eine Art Vereinigungs- oder Kommunikationszauber.",},
			["Arakkoa der Lithic"] = { content = "In der verachtungswürdigen Kolonie der Arakkoa in den [[Wälder von Terokkar|Wäldern von Terokkar]], die als Lithicversteck bekannt ist, versuchen die Diener [[Terokk]]s ihre geflügelten Brüder schon vor dem Schlüpfen zu verderben. Die schwarzen Zauberhexer von Lithic belegen die Eier mit einem schattenhaften Fluch. Wenn die Küken schlüpfen, sind sie bereits willenlose Diener [[Terokk]]s. Die [[Oger]] sind ein uralter Feind der [[Arakkoa]] im Lithicversteck, und in letzter Zeit haben sie begonnen, vom Grasland in [[Nagrand]] zurück in ihre Wälder zu ziehen.",},
			["Arakkoa der Reskk"] = { content = "Die Arakkoa das Reskkverstecks in den [[Wälder von Terokkar|Wäldern von Terokkar]] haben immer wieder die [[Steinbrecherfeste]] angegriffen, dieses Mal bei Nacht. Sie haben ihre dunkle Magie eingesetzt um zu entkommen, bevor die [[Orcs]] der Feste losstürmen und ihnen Auge in Auge entgegentreten konnten. Die [[Arakkora]] benutzen ihre Beschwörungskreise, um ihre Krieger von dem sicheren Tod zu retten. [[Ashkaz]] ist einer der Anführer hier.",},
			["Arakkoa der Rhaze"] = { content = "Das Rhazeversteck in den [[Wälder von Terokkar|Wäldern von Terokkar]] war die bösartigste Kolonie der [[Arakkoa]] von [[Skettis]]. Trotz der Auslöschung seiner Bewohner durch die Katastrophe von [[Auchindoun]] hielt [[Terokk]] seinen Einfluss auf die bösartigen Geister dort aufrecht. Man findet die mörderischen Schufte westlich des [[Schattengrab]]s, an der Grenze zwischen der [[Knochenwüste]] und den [[Wälder von Terokkar|Wäldern von Terokkar]]. Die [[Arakkoa]] hier haben eine Vogelscheuche aufgestellt, die als 'Torgos' Fluch' bekannt ist und [[Torgos]] von hier fernhält.",},
			["Arakkoa der Ruuan'ok"] = { content = "Unter den [[Arakkoa]] des [[Ruuanwald]]es im [[Schergrat]] nehmen die Herolde des Raben innerhalb der Brut eine besondere Stellung ein, da sie die Boten ihres Gottes sind. Die [[Arakkoa]] glauben, dass die Herolde vom Himmel aus, wo sie den Lehren des Raben lauschen, über sie wachen und hinabsteigen, um sein Wort zu verbreiten. Die Herolde haben einen starken Einfluss auf die Seelen der [[Arakkoa]] und benutzen magische Anhänger.",},
			["Arakkoa der Sethekk"] = { content = "=== Sethekk===\r\n* Ort: [[Auchindoun]] / [[Sethekkhallen]]\r\n* Anführer: [[Klauenkönig Ikiss]], [[Dunkelwirker Syth]]\r\nDie Sethekk glauben, dass sie die wahren und treuesten Anhänger des Meisters aller Arakkoa sind. Die Sethekk haben die Zerstörung [[Auchindoun]]s als die Ankunft des Meisters auf [[Draenor]] gedeutet. Sie sind zu den Ruinen aufgebrochen und haben die Relikte ihres größtes Helden, Terokk, mit sich genommen. Sie suchen in den Ruinen noch immer nach ihrem Meister, aber er gehört nicht mehr zu ihnen.",},
			["Arakkoa der Shalas"] = { content = "=== Shalas===\r\n* Ort: [[Wälder von Terokkar]]\r\nÜber der Knochenwüste im Osten wirft [[Skettis]], der lange Arm Terokks, bedrohlich seine Schatten. Am Fuße von Skettis liegt das Shalasversteck, Terokks vortrefflichste Kolonie. Von diesem Stützpunkt aus führen Terokks Diener Krieg gegen das Licht. Die Unholde der Shalas kommunizieren über ein komplexes System aus magischen Signalfeuern mit ihrem Meister.",},
			["Arakkoa der Shi'lak"] = { content = "=== Shi'lak===\r\n* '''Ort''': Wälder von Terokkar\r\nDas Shi’lakversteck liegt im östlichen Skettis.",},
			["Arakkoa der Shienor"] = { content = "=== Shienor===\r\n* '''Ort''': [[Wälder von Terokkar]]\r\n* '''Anführer''': Ayit\r\nDas Shienorversteck liegt im Norden. Die Arakkoa haben erneut Allerias Feste angegriffen, dieses Mal bei Nacht. Sie haben ihre dunkle Magie eingesetzt um zu entkommen, bevor man Soldaten losschicken konnte.",},
			["Arakkoa der Sketh'lon"] = { content = "Von Sketh’lon im [[Schattenmondtal]] ist nur noch ein Wrack übrig, dass nordwestlich der [[Todesschmiede]] liegt. Während sich die orcische Horde unter [[Gul'dan]] sammelte, versuchten die [[Arakkoa]], diese Bedrohung abzuwenden, indem sie einen Angriff planten. [[Gul'dan]] erfuhr jedoch davon und wirkte einen mächtigen Zauber, der die Lager zerstörte und ihre Geister zerbrach. Heute hausen hier nur noch die ruhelosen Geister der [[Arakkoa]]. Auch die [[Dunkler Rat|Arakkoa des Dunklen Rats]] treiben sich beim Wrack der Sketh'lon herum. \r\nSpäher haben erschütternde Berichte aus den zerstörten Arakkoalagern in der Gegend geliefert. Die Geister der mächtigen Arakkoamagier verfügen über nie geahnte Kräfte und scheinen sich zu formieren, als ob sie etwas planten. Es ist nicht mehr möglich, die [[Arakkoa]] aus den Tiefen ihrer Verderbtheit zu erretten. [[Gul'dan]]s Magie hat die [[Arakkoa]] vernichtet und nur ihre Geister übrig gelassen, doch das war nicht alles. Die Magie hat sich an dem Zauber, den die Arakkoa vorbereiteten, genährt und eine ruchlose Macht erschaffen, die die Geister in ihren Bann gezogen hat. Es geht um eine fehlgeschlagene Vorbereitung eines Zaubers, Opfer und eine sich verschlechternde Situation.\r\nDas [[Basislager der Sketh'lon]] befindet sich im Süden, östlich der [[Wildhammerfeste]]. Dort herrschen die [[Dunkler Rat|Arakkoa des Dunklen Rats]].\r\n==Persönlichkeiten==\r\n* '''Asghars''' altes Kriegstotem der Sketh'lon hat seine Macht über die Jahre nicht eingebüßt.",},
			["Arakkoa der Skith"] = { content = "* Ort: [[Wälder von Terokkar]]\r\n* Anführer: Urdak\r\nDas Skithversteck liegt nordwestlich der Karawane und südlich von [[Shattrath]] in einem versteckten Hain im Wald. Man sagt, dass die Kolonie von Skettis dort einen bösartigen Altar der Verehrung errichtet hat, auf dem sich Terokks Dunkelstein befindet. Wenn die Arakkoa der Skith jemals erlöst werden wollen, muss Terokks Dunkelstein zuerst geläutert werden. Die Arakkoa der Skith - diese primitiven Zauberer - haben neulich eine große Schiffladung magischen Waren gestohlen. Auch befinden sich einige Kinder in ihren Käfigen.",},
			["Arakkoa der Vekh'nir"] = { content = "Die [[Arakkoa]] der Vekh'nir in [[Vekhaar]] im [[Schergrat]] sind den [[Mok'Nathal]] schon seit vielen Jahren ein Dorn im Auge. Sie praktizieren eine merkwürdige Religion, die sie in ständiger Betriebsamkeit hält. Sie tragen nun diese Kristalle bei sich, die sie für irgendwelche dunklen Zwecke einsetzen. Sie bringen die Kristalle zu ihren Zauberzirkeln, um sie dort aufzuladen. Bei [[Trogmas Besitz]] halten die Arakkoa der Vekh’nir außerdem [[Oger]] als Sklaven.",},
			["Arans Schemen"] = { content = "#REDIRECT [[Erzmagier Nielas Aran]]", redirect = "Erzmagier Nielas Aran",},
			["Arathi-Hochland"] = { content = "#REDIRECT [[Arathihochland]]", redirect = "Arathihochland",},
			["Arathi"] = { content = "#REDIRECT [[Arathihochland]]", redirect = "Arathihochland",},
			["Arathibecken"] = { content = "Das '''Arathibecken''' im [[Arathihochland]] ist einer der wichtigsten Schauplätze im Kampf zwischen den [[Menschen]] und den [[Verlassene]]n Azeroths. Der [[Bund von Arathor]] versucht Territorien zurückzuerobern, während [[Die Entweihten]] - Elitetruppen unter Varimathras Kommando - die Verbindung zwischen den Menschen und ihren Verbündeten, den Zwergen, zerstören wollen. Das Talbecken selbst verfügt über wertvolle Rohstoffe, um die die [[Allianz]] und die [[Horde]] erbitterte Schlachten austragen. [[Die Entweihten]] und der [[Bund von Arathor]] sind hier, um die Rohstoffe für ihre Seite zu sichern und ihrem Gegner eine empfindliche Niederlage beizubringen. (Quelle: \r\n==Hintergrund==\r\nDer Konflikt der [[Horde]] mit der [[Allianz]] hat sich zu einem richtigen Krieg entwickelt. Es ist nicht länger notwendig unter falschen Vorwänden in die Schlacht zu ziehen, keine Seite erwartet dies noch länger. In der Schlacht um das Arathibecken geht es nur um eines: Ressourcen. Nicht mehr und nicht weniger. Entweder die [[Allianz]] erobert diese Ressourcen und benutzt sie gegen die [[Entweihte]]n, oder sie kommen ihnen zuvor und verwenden die dortigen Ressourcenquellen für die Kriegspläne.\r\nEine Schlacht muss mit Soldaten gewonnen werden, das wird jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist. Deshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden. Die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um die Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Es ist schwer an Informationen zu gelangen, jetzt da sie so tief in diesem Konflikt stecken. Doch die Spione berichten, dass die Entschlossenheit des [[Bund von Arathor|Bundes von Arathor]] schwindet. Die [[Entweihte]]n wollen diesen Moment ausnutzen und eine große Offensive starten. \r\nEs gehört viel mehr dazu, einen Krieg zu gewinnen, als das bloße Überlisten des Gegners oder siegreiche Schlachten. Vielmehr erringt die Seite den Sieg, welche dauerhaft mehr Kriegsgüter als der Gegner produziert. Das Arathibecken, könnte sich als eine potentielle und äußerst ergiebige Ressourcenquelle für die Seite erweisen, die das Becken zuerst für sich beansprucht.",},
			["Arathihochland"] = { content = "Der geübte Wanderer, der einen Weg sucht um von den idyllischen Ebenen des [[Sumpfland]]es in die Gebiete von [[Tarrens Mühle]] und/oder nach [[Süderstade]] oder ins [[Alterac]]gebirge zu gelangen, den wird seine Reise auf jeden Fall durch das Arathihochland führen. Diese Gegend, deren Hauptmerkmal die leicht geschwungenen, mit saftigem Grün bewachsenen, Hügel sind, wird von allerlei Volk bewohnt. Der große Artenreichtum der dortigen Tierwelt hat schon so manchem Reisenden Freude und Kummer bereitet. Obwohl die [[Horde]], wie auch die [[Allianz]] ihre Außenposten dicht bei einander aufgebaut haben, kann man von Spannung oder Freindschaft nicht viel zu spüren. Diese gegenseitige Duldung ist sicherlich darin begründet, daß allerlei Gefahren rundherum zu meistern sind und für Plänkeleien zwischen den [[Fraktionen]] wenig Zeit bleibt. Für den streitsüchtigen Zeitgenossen bleibt dennoch genug zu tun um all die vielen [[Oger]], [[Trolle]] und alle möglichen Reptilien und [[Elementare]] zu erschlagen. Frei nach dem Motto: Viel Feind, viel Ehr.\r\n==Orte==\r\n* [[Arathibecken]]\r\n* [[Bauernhof der Dabyries]]\r\n* [[Burg Stromgarde]]\r\n* [[Faldirbucht]]\r\n* [[Fels'Gor]]\r\n* [[Go'Sheks Hof]]\r\n* [[Halle der Felsfäuste]]\r\n* [[Hammerfall]]\r\n* [[Kreise der Bindung]]\r\n* [[Lager der Bleichborken]]\r\n* [[Nordhof]]\r\n* [[Schlucht der Trockenstoppel]]\r\n* [[Tol Barad]]\r\n* [[Trollbanns Grabmal]]\r\n* [[Turm von Arathor]]\r\n* [[Zuflucht]]",},
			["Arathor"] = { content = "(siehe auch: [[Bund von Arathor]] )\r\nViele Jahre lang lebten die [[Menschen]] ein nomadisches Leben - bis zum Aufstieg der Arathi. Angesichts der wachsenden Bedrohung durch Kriegsmeuten der [[Waldtrolle]], sah dieser Stamm die Möglichkeit, die einzelnen Sippen zu vereinen. In den folgenden Jahren brachten die Arathi andere Stämme unter ihre Herrschaft und gründeten schließlich in den Hochländern von [[Lordaeron]] die Nation Arathor und dessen massiv befestigte Hauptstadt Strom. In seiner Blütezeit erstreckte sich das riesige Imperium fast über den gesamten östlichen Kontinent. Bald ging es ein Bündnis mit dem Elfenreich [[Quel'Thalas]] ein, das durch den langen Krieg gegen die [[Waldtrolle]] so weit geschwächt war, dass es kurz vor einer Niederlage standen. Im Gegenzug für die Hilfe der [[Menschen]], versprachen die [[Hochelfen]], sie in den geheimnisvollen Künsten der [[Magie]] zu unterrichten. Den gemeinsamen Armeen gelang es schließlich, die Vorherrschaft der [[Trolle]] in [[Quel'Thalas]] und [[Lordaeron]] zu brechen. Arathor bestand 1700 Jahre lang, zerbrach dann aber unter dem Druck der fortwährenden Expansion und interner Zwistigkeiten in sieben unabhängige Nationen. Diese Königreiche nannten sich fortan [[Azeroth]], [[Lordaeron]], [[Stromgarde]], [[Kul Tiras]], [[Gilneas]], [[Dalaran]] und [[Alterac]]. Trotz der wachsenden Spannungen herrschte auch weiterhin Frieden zwischen den Völkern.\r\n'''Quelle''':",},
			["Arathor und die Trollkriege"] = { content = "'''Quelle:'''\r\nWährend die Hochelfen unter dem brutalen Ansturm der Trolle ums Überleben kämpften, bemühten sich die versprengten nomadischen Menschen von Lordaeron, ihre eigenen Stammesländer zu konsolidieren. Die Stämme der frühen Menschen Überfielen gegenseitig ihre Siedlungen und gaben nichts auf Ehre oder Zusammenhalt des Volkes.\r\nDoch ein Stamm, Arathi genannt, erkannte, dass man die zunehmende Gefahr durch die Trolle nicht mehr ignorieren konnte. Die Arathi wollten alle Stämme unter ihrer Herrschaft vereinen, damit sie sich den Kriegsmeuten der Trolle mit einer Einheitsfront entgegenstellen konnten.\r\nIm Lauf von sechs Jahren gelang es den Arathi, die rivalisierenden Stämme zu überlisten und zu unterwerfen. Nach jedem Sieg boten die Arathi dem eroberten Volk Frieden und Gleichheit an. Auf diese Weise sicherten sie sich die Loyalität der Besiegten. Schließlich setzten sich die Arathi aus vielen verschiedenen Stämmen zusammen und verfügten Über ein riesiges Heer. \r\nDa die Kriegsherren der Arathi der festen Überzeugung waren, dass sie gegen die Kriegsmeuten der Trolle und, falls erforderlich, sogar gegen die einsiedlerischen Elfen bestehen konnten, beschlossen sie, in der südlichen Region von Lordaeron eine mächtige befestigte Stadt zu errichten. Dieser Stadtstaat namens Strom wurde zur Hauptstadt von Arathor, der Nation der Arathi. Je mehr Arathors Wohlstand wuchs, desto mehr Menschen reisten Über den riesigen Kontinent und suchten Schutz und Sicherheit in Strom. \r\nDie unter einem Banner vereinigten Stämme der Menschen begründeten eine starke, optimistische Kultur. Thoradin, der König von Arathor, wusste wohl, dass die geheimnisvollen Elfen in den Ländern des Nordens unablässig von den Trollen belagert wurden, wollte sein Volk aber keiner Gefahr aussetzen, indem er einsiedlerische Fremde verteidigen half. Viele Monate vergingen, bis Gerüchte Über eine angebliche Niederlage der Elfen von Norden eintrafen. Aber erst als erschöpfte Botschafter aus Quel'Thalas in Strom eintrafen, wurde Thoradin klar, wie groß die Gefahr, die von den Trollen ausging, wirklich war. \r\nDie Elfen ließen Thoradin wissen, dass die Armeen der Trolle riesig waren und die Trolle ganz gewiss die Südländer angreifen würden, wenn sie Quel'Thalas erst einmal zerstört hatten. Die verzweifelten Elfen, die dringend militärischer Unterstützung bedurften, willigten hastig ein, bestimmte auserwählte Menschen den Umgang mit der Magie zu lehren, falls diese ihnen gegen die Kriegsmeuten beistanden. \r\nThoradin, der jeder Form von Magie misstrauisch gegenüberstand, sagte den Elfen in Ermangelung von Alternativen seine Hilfe zu. Unmittelbar danach trafen Elfen-Zauberhexer in Arathor ein und unterwiesen eine Gruppe Menschen im Gebrauch der Magie. \r\nDie Elfen stellten fest, dass die Menschen im Umgang mit der Magie zwar ungeübt waren, aber eine erstaunliche natürliche Affinität dafür besaßen. Einhundert Menschen wurden in die Grundzüge der magischen Geheimnisse der Elfen eingeführt: nicht mehr, als unbedingt erforderlich waren, um gegen die Trolle zu kämpfen. Als die Elfen Überzeugt waren, dass ihre menschlichen Schüler im Kampf nützlich sein konnten, verließen sie Strom und reisten mit den mächtigen Armeen von König Thoradin nach Norden. \r\nDie vereinigten Armeen von Elfen und Menschen stießen am Fuß des Alteracgebirges auf die Überlegenen Kriegsmeuten der Trolle. Die Schlacht währte viele Tage, aber die unerschütterlichen Armeen von Arathor blieben unermüdlich und wichen keinen Schritt vor dem Ansturm der Trolle zurück. Den Elfenlords schien die Zeit reif, die Macht ihrer Magie gegen den Feind zu entfesseln. \r\nHundert Menschenmagi und eine Vielzahl von Zauberhexern der Elfen riefen die Wut des Himmels herab und ließen Feuer auf die Armee der Trolle regnen. Die Elementarfeuer verhinderten, dass die Trolle ihre Verletzungen heilen konnten, und verbrannten ihre geschundenen Leiber von innen heraus. \r\nDann endlich stoben die Armeen der Trolle auseinander und wollten fliehen, doch Thoradins Soldaten hetzten sie und metzelten sie bis auf den letzten Mann nieder. Von dieser Niederlage erholten sich die Trolle nie mehr; ihre Tage als starke Nation waren endgültig gezählt. In der Gewissheit, dass Quel'Thalas sicher war, schworen die Elfen der Nation Arathor und dem Geschlecht des Königs Thoradin ihre Treue. Menschen und Elfen lebten fortan Jahrhunderte lang in friedlicher Verbundenheit.",},
			["Arator der Erlöser"] = { content = "'''Arator der Erlöser''' ist derzeit der einzige namentlich bekannte [[Halbelf]] auf [[Azeroth]]. Er ist der Sohn von General [[Turalyon]] und [[Alleria Windläufer]]. Er folgte als Kind seinen Eltern nach [[Draenor]] und galt nach der Katastrophe als tot. Doch als [[Verdammnislord Kazzak]] das [[Dunkle Portal]] wieder öffnete und die [[Argentumdämmerung]] gegen die Legion kämpfte, kam Arator mit einer Hand voll Soldaten und kämpfte mit gegen die [[Dämonen]]. Nun wartet er in der [[Ehrenfeste]] auf seine beiden verschwundenen Eltern.\r\nEr war noch ein Kind, als sein Vater [[Turalyon]] in das Ödland der [[Scherbenwelt]] abkommandiert wurde. Alles, was Arator von ihm weiß, haben ihm andere berichtet. Doch seine Träume ändern sich nicht. Immer und immer wieder hat er den selben Traum: Ein roter Himmel umgibt alles, um ihn herum zahllose Soldaten, in der Ferne tobt eine Schlacht. Er kniet vor dem zerschundenen Körper eines Mannes, seinem Vater, und weint. Er ringt nach Luft, sein Lebenswille droht ihn zu verlassen und er flüstert seinem Sohn irgendetwas zu. Arator versucht zuzuhören, doch das Gesagte ist zu leise, als dass er es verstehen könnte.",},
			["Arazmodu"] = { content = "Arazmodu ist ein [[Bronzener Drachenschwarm|Bronzener Drache]] in den [[Höhlen der Zeit]] in [[Tanaris]]. Er gehört zur Fraktion der [[Wächter der Sande]] und erscheint in Form eines Kleinen Menschenjungen.",},
			["Arazzius der Grausame"] = { content = "Der [[Man'ari]] [[Eredar]] Arrazius der Grausame ist ein Leutnant von [[Verdammnislord Kazzak]] und hat den Befehl über die Bodentruppen der [[Brennende Legion|Brennenden Legion]] auf der [[Höllenfeuerhalbinsel]]. Wie es scheint hat dieser Bösewicht eine neue Streitmacht von höllischen [[Terrorbestien]] in der Nähe der [[Teiche von Aggonar]] aufgestellt. Arazzius der Grausame ist der mächtigste und bösartigste Feind, dem die [[Söhne Lothars]] sich je stellen mussten.",},
			["Arbeiter"] = { content = "#REDIRECT [[Menschenarbeiter]]", redirect = "Menschenarbeiter",},
			["Archimonde"] = { content = "==Herkunft==\r\nArchimonde entstammt der Rasse der [[Eredar]], einer Dämonenrasse, die schon seit Anbeginn der Zeit im [[Sog der Unterwelt]] zuhause war und andere Völker versklavt hatte und diese durch ihre chaotischen Magien selbst zu [[Dämonen]] machte. \r\n==Charakter==\r\nEr ist herzlos und brutal, aber überaus verschlagen und weitblickend. Dieser kolossale Dämon verfügte über große magische Kräfte, grenzenlose Mächte, Hexenmeister-Magie und die Urkraft, alles, was sich seinem feurigen Willen widersetzt, in Schutt und Asche zu legen. Tief in seinem Inneren träumte er davon, ein Gott zu werden und eine Macht zu besitzen, die es mit jener Sageras aufnehmen konnte.\r\n==Geschichte==\r\nArchimonde der Entweiher gehörte zu den ersten Dämonen, die sich [[Sargeras]] anschlossen, als die Brennende Legion gegründet wurde und war einer der obersten Anführer der [[Brennende Legion|Brennenden Legion]]. Er wurde von [[Sargeras]] auserwählt, seine riesigen Armeen in den Kampf zu führen. Archimonde gehört, genau wie [[Kil'jaeden]], zum Volk der [[Eredar]]. Zusammen mit Mannoroth führte Archimonde die [[Brennende Legion]] vor vielen Jahrtausenden das erste mal gegen die Welt von [[Azeroth]]. Nach zehntausend Jahren des Wartens war er bereit, erneut in die Welt von Azeroth einzudringen. Seine Aufgabe bestand darin, die Invasion in Sargeras Namen anzuführen, aber Archimonde wollte die Energien dieser Welt für seine eigenen Zwecke missbrauchen. Dies war sein eigener Untergang: Er näherte sich zu kühn [[Nordrassil]], dem Weltbaum und achtete nicht die Falle die man ihm gestellt hatte. Kaum hatte er den Fuß auf die Wurzeln des Baumes gestellt, wurde er durch den Wächter hinweggefegt.\r\n===Dritter Krieg===\r\nWährend des Dritten Krieges wurde Archimonde von [[Kel´Thuzad ]] mit Hilfe von [[Medivh]]s Zauberbuch herbeibeschworen. Als Demonstration seiner Macht zerstört er die Stadt [[Dalaran]]. Zusammen mit seinen Armeen versucht er den Berg [[Hyjal]] zu erreichen. Dort versuchte er Nordrassil, den Weltenbaum, zu erreichen, welcher mit dem magischen Wasser aus dem [[Brunnen der Ewigkeit]] getränkt ist. Die [[Orcs]] unter der Führung von [[Thrall]], die [[Menschen]] unter Jaina Prachtmeer, sowie die [[Nachtelfen]] versuchten gemeinsam den Vormarsch zu stoppen, jedoch gelang es Archimonde trotzdem den Weltenbaum zu erreichen. Letztendlich opferten die [[Nachtelfen]] ihre Unsterblichkeit und speisten den Weltenbaum mit den Geistern ihrer Ahnen. Der Weltenbaum gewann an Kraft und griff Archimonde mit einer Welle purer magischer Energie an, die den Dämon und alle seine Truppen zerstörte. Es heißt Archimondes Übereste würden immer noch am mittlerweile übel zugerichteten Weltbaum hängen.\r\n===Zweifel an der offiziellen Geschichtsschreibung===\r\nDie gnomischen Wissenschaftler [[Smirke|Smirke Rasselspross Junior]] und [[Hildegard Sprigglespruxx]] vom [[Institut für Pfuschkunde]] haben angekündigt die Fehler und Lügen der bisherigen Geschichtsschreibung in ihrem heißerwarteten Vortrag \"[[Archimonde - ein Rollenbild für Gnome ?]]\" aufzudecken.",},
			["Archivar Galford"] = { content = "'''Archivar Galford''' ist ein Mitglied des [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzuges]] in [[Stratholme]]. Dieser Boss wacht im Scharlachroten Archiv der Bastion über die wertvollsten Dokumente des Kreuzzugs. [[Fürst Nicholas Zverenhoff]] von der [[Argentumdämmerung]] ist wegen des fanatischen Inhalts dieser Schriften, an der Vernichtung des Archis und des Archivars interessiert. Zverenhoffs Meinung nach ist alles, was zum Extremen getrieben wird, für diese Welt gefährlich und der blinde Fanatismus der Anhänger des Scharlachroten Kreuzzuges dient nichts Gutem. Zuviele Unschuldige haben sie im Namen des Lichts vernichtet. Sie sind Gotteslästerer, alle zusammen und ihre Schriften gehören verbannt! \r\n==Fähigkeiten==\r\nArchivar Galford beherrscht drei Fähigkeiten aus dem Element des Feuers. Dazu gehören Brennende Winde, Feuernova und Pyroschlag. Die ''Brennenden Winde'' machen einen Feind bewegungsunfähig und fügen ihm im Verlauf von 8 Sek. insgesamt 1600 Feuerschaden zu. Die ''Feuernova'' verursacht 197 bis 227 Feuerschaden bei in der Nähe befindlichen Feinden. ''Pyroschlag'' fügt einem Feind erst Feuerschaden und dann 12 Sekunden lang alle 3 Sekunden zusätzlichen Schaden zu. \r\n'''Quests'''\r\n'''Quellen'''",},
			["Archäologe Magenbitter"] = { content = "Archäologe Magenbitter ist ein anerkanntes Mitglied der [[Forscherliga]] und brachte ein [[Geheimnisvolles Fossil]] zur jährlichen Konferenz der [[Forscherliga]] mit. Er dachte, das Fossil besäße eine besondere Macht, die man irgendwie freisetzen könnte. Das Letzte, was man von Magenbitter hörte war, dass er sich in der Tiefenwassertaverne im [[Hafen von Menethil]] verschanzt hatte und dort auf eine Eskorte zu [[Whelgars Ausgrabungsstätte]] wartete. Als er den [[Stein von Relu]] entdeckte, glaubte er, dass er der Schlüssel sei, mit dem das Rätsel des Fossils gelöst werden könne. Auf dem Weg zu [[Ausgrabungsleiter Whelgar]] wurde er dann von [[Raptoren]] angegriffen und das Relikt ging verloren.",},
			["Archäologe Magenbitter"] = { content = "Archäologe Magenbitter ist ein anerkanntes Mitglied der [[Forscherliga]] und brachte ein [[Geheimnisvolles Fossil]] zur jährlichen Konferenz der [[Forscherliga]] mit. Er dachte, das Fossil besäße eine besondere Macht, die man irgendwie freisetzen könnte. Das Letzte, was man von Magenbitter hörte war, dass er sich in der Tiefenwassertaverne im [[Hafen von Menethil]] verschanzt hatte und dort auf eine Eskorte zu [[Whelgars Ausgrabungsstätte]] wartete. Als er den [[Stein von Relu]] entdeckte, glaubte er, dass er der Schlüssel sei, mit dem das Rätsel des Fossils gelöst werden könne. Auf dem Weg zu [[Ausgrabungsleiter Whelgar]] wurde er dann von [[Raptoren]] angegriffen und das Relikt ging verloren.",},
			["Arconus"] = { content = "#REDIRECT [[Arconus der Unersättliche]]", redirect = "Arconus der Unersättliche",},
			["Arconus der Unersättliche"] = { content = "'''Arconus der Unersättliche''', ein [[Fürst der Leere]], ernährt sich von den Energien der Kreaturen im [[Nethersturm]] beim [[Zugangsschacht Zeon]]. Überall dort liegen Leichen und Arconus ist für diese Massaker verantwortlich. Er hat sie ausgesaugt, sodass nur noch eine Fleischhülle übrig geblieben ist. [[Araxes]] und [[Agent Sechs-Uhr]] wurden vor zwei Tagen vom [[Kommandant Ameer]] im [[Wachposten des Protektorats]] zur [[Manaschmiede Ultris]] geschickt. Ihr Auftrag: findet und vernichtet den Lord der Leere Arconus. Sie haben ihn bis zu seiner Mine verfolgt, doch konnten ihn nicht bezwingen.",},
			["Area 52"] = { content = "Das ummauerte und schwer bewachte '''Area 52''' liegt vom Eingang den Pfad zum [[Nethersturm]] hoch und bei der Weggabelung rechts. Es ist passend als Raketenbasis getarnt. Mitten durch Area 52 verläuft ein Riss, der von den [[Goblins]] von [[B.U.M.M.]] angelegt wurde. Im Riss befinden sich allerlei Schätze für das [[Raketenschiff X-52]]. Das einzige Problem ist nur, dass sie nicht genug Ausrüstung haben. Ab Patch 2.4.3 findet man hier auch ein [[Auktionshaus]].\r\n==Personen==\r\n* '''Blazzel''' - Blazzel bietet Gegenstände für den Schmiedekunstbedarf und Reparaturen an. Er steht neben der Schmiede und dem Amboss vor dem Gasthaus.\r\n* '''Chefingenieur Trep''' - Als Raketenchef Doppeldecker nach Freiwilligen für den Bau der X-52 Netherrakete gesucht hat, hat Trep sich als Wachmann beworben. Unglücklicherweise war nur noch die Stelle als Chefingenieur übrig. Zum Glück schaut Xyrol ihm hier ab und zu über die Schulter. Chefingenieur Trep arbeitet am [[Raketenschiff X-52]] und hat [[Xyrol]] einen Elementarenergieextraktor herstellen lassen. Er weiß nicht genau, was man mit dieser Energie anfangen kann, aber er wird schon einen Verwendungszweck für sie finden. Als Chefingenieur der X-52 ist es seine Pflicht dafür zu sorgen, dass die Hauptmotoren der Netherrakete tiptop in Schuss sind. Unglücklicherweise hat er sie noch nicht gebaut. \r\n* '''Kablamm Weitschleuder''' - Mit der Hilfe seines Bruders Zap in der Ewigen Warte hat er genau hier in Area 52 eine dimensionale Implosionsmatrix konstruiert. Wer braucht schon eine Rakte, wenn man sofortigen Transport mit Hilfe von Gobliningenieurwesen haben kann. Gutausgebildete Gobliningenieure können bei ihm erlernen, wie man einen Implosionssignalgeber herstellt.\r\n* '''Kalynna Lathred''' - Kalynna Lathred hat die [[Kirin Tor]] verlassen, weil sie nach Wissen strebte, das von dem Orden verboten wurde. Es ist mehr als ironisch, dass sie nun gebeten wird, sie mit genau diesem Wissen zu unterstützen, denn sie könnte die Überreste von [[Medivh]]s Essenz in einem kleinen verkohlten Knochenfragment wieder zum Leben zu erwecken. Sie sucht außerdem den [[Dämmerfoliant]]en vom [[Großhexenmeister Nethekurse]] in den [[Zerschmetterte Hallen|Zerschmetterten Hallen]] der [[Höllenfeuerzitadelle]] und das [[Buch der vergessenen Namen]] von [[Dunkelwirker Syth]] in den [[Sethekkhallen]] in [[Auchindoun]]. \r\n* '''Leitender Ingenieur Zischeldruck''' - Leitender Ingenieur Zischeldruck befindet sich beim östlichen Ende des Risses in Area 52. Er möchte, dass man [[Dr. Bumm]] tötet, Astraltechnologie sammelt und einen Vernichterservo aus der [[Manaschmiede B'Naar]] besorgt, um den kaputten in dem langhalsigen [[Spektrumanalysator]] zu ersetzen. Seine Partnerin [[Mama Mauschel]] da draußen im Feld in der [[Biokuppel Mittelreich]] könnte sicher etwas Hilfe gebrauchen. \r\n* '''Netheorologe Kupfernickel''' - Netheorologe Kupfernickel von B.U.M.M. studiert draußen den Nether die astralen Strömungen und so weiter. Dies ist ein idealer Platz, weit weg von den Lichtern und dem Getöse der Stadt. Er möchte, dass seine neusten Forschungsnotizen zu [[Raketenchef Doppeldecker]] gebracht werden. \r\n: '''Notizen des Netheorologen:'''\r\n: Nach zahlreichen Seiten todlangweiliger 'Wissenschaft', die absolut keinen Sinn zu ergeben scheint, entdeckt man in diesem Bericht ganz am Ende der letzten Seite eine hingekritzelte Notiz...:\r\n: ''Tschuldigung, Boss. Sieht aus, als würde der Nethersturm bald loswüten. Wahrscheinlich wird der Großteil der Scherbenwelt auch daran glauben müssen. Ich bin mir nicht 100% sicher, aber ich glaube, das Problem hat etwas mit den Aktivitäten der Blutelfen bei den Manaschmieden zu tun. Nur gut, dass Ihr diese Rakete baut!'' \r\n: ''P.S. - Ist vielleicht noch ein Platz in der Rakete für mich frei? Ihr werdet mit Sicherheit einen Netheorologen brauchen, wenn Ihr durch den wirbelnden Nether fliegt!\"'' \r\n* '''Raketenchef Doppeldecker''' - Raketenchef Doppeldecker möchte, dass man den ultrastarken [[Dekonsolidierungsstrahler]] benutzt, um unschätzbare Ausrüstung zurück nach Area 52 zu beamen. Dazu gehören der [[Hyperdreh-Grab-o-Matik]], die [[Servopneumatische Baggerklaue]], der [[Multispektrale Geländeabtaster]] und einen großen Wagen voller Sprengstoff.\r\n* '''Ravandwyr''' - Ravandwyr ist der Lehrling von [[Erzmagier Vargoth]] und möchte dessen Stab von [[Ekkorash]] der Inquisitorin wiederbesorgen. Danach soll der Stab mittels fehlerloser Kristallsplitter von den Geistern in den [[Ruinen von Enkaat]] wiederhergestellt werden, damit begonnen werden kann, den Fluch des violetten Turms zu brechen.\r\n* '''Stiefels''' - Stiefels verdient gut daran, den Trunkenbolden hier Getränke zu verkaufen. Aber er will mehr. Es fehlt ihm noch die eine Zutat, die dem Gebräu den entscheidenden kleine Extrakick geben sollte. Er ist sich sicher, dass die Ergebnisse explosiv sind.\r\n===Aldor===\r\nVor nicht allzu langer Zeit entsandte [[Hohepriesterin Ishanah]] im Auftrag der [[Sha'tar]] eine kleine Gruppe von [[Anachoret]]en unter dem Kommando von [[Exarch Orelis]] in den [[Nethersturm]]. Sie hatten den Auftrag, die Aktivitäten von [[Kael'thas]] und seinen Gefolgsleuten bei den [[Manaschmieden]]zu untersuchen, die [[Kael'thas]]' Armee hier betreibt. Doch bisher hat Ishanah keinerlei Nachricht von ihnen erhalten. Auch drohen die [[Seher]] damit, ihre Spionagearbeiten nicht durchzuführen, wenn die [[Aldor]] sie nicht militärisch unterstützen. Die [[Aldor]] können sich nicht erlauben, dass diese Mission wegen politischen Differenzen den Bach hinunter geht, daher haben sie sich einverstanden erklärt, die Verteidigung der [[Manaschmieden]] zu schwächen, damit die [[Seher]] ihre Arbeit verrichten können. Doch ihre Präsenz im Zielgebiet ist nicht stark genug, um diesen Auftrag erfolgreich abzuschließen. \r\n* '''Anachoret Karja''' - Anachoret Karja leitet Schwächung der [[Manaschmieden]].\r\n* '''Exarch Orelis''' - Exarch Orelis gehört zu den Aldor. Er sorgt für Ablenkung in den [[Manaschmieden]], indem die [[Arkanist]]en, [[Blutwärter des Sonnenzorns|Blutwärter]], [[Forscher des Sonnenzorns|Forscher]] und [[Magister des Sonnenzorns]] dezimiert werden sollen. Er möchte danach, dass man eine Warpmesskugel zur [[Manaschmiede B'naar]] bringt und sie in der Nähe der vier Rohrleitungen benutzt, um die Warpenergien zu messen. Auch für die Anweisungen des Sonnenzorns, bestehend aus den Truppenbefehlen und Arkanbefehlen der [[Manaschmiede Duro]] interessiert er sich brennend. Sind diese Aufgaben erledigt, schickt er Hilfe von außen zu [[Tulumans Landeplatz]], nördlich von Area 52 zu Kaylaan.\r\n===Konsortium===\r\nDie [[Naaru]] von [[Shattrath]] haben versucht, dem [[Konsortium]] beizubringen, die Dinge auf ihre Weise zu sehen. Das Glück wollte, dass die Geschäftsbeziehungen zwischen den [[Astrale]]n und den [[Blutelfen]] im [[Nethersturm]] sich in letzter Zeit drastisch verschlechtert haben. \r\n* '''Netherpirscher Khay'ji''' - Netherpirscher Khay'ji ist ein Mitarbeiter des [[Konsortium]]s, der vor Kurzem ein paar Probleme mit einer Truppe von abtrünnigen [[Astralen der Zaxxis]] hatte. [[Nexusprinz Haramad]] hat ihn außerdem gebeten, ein Kristallartefakt aus den [[Ruinen von Arklon]] im Südosten zu besorgen. \r\n===Seher===\r\nDie [[Seher]] wurden von den [[Sha'tar]] hierher geschickt, um die [[Manaschmieden]] zu erkunden. Vor einiger Zeit schickte [[Voren'thal]] ein kleine Einheit in den [[Nethersturm]], um [[Kael'thas]] Aktivitäten genauer zu beobachten. Er hat vollstes Vertrauen in die Fähigkeiten von [[Spionagemeister Thalodien]] und seinen Männern. Thalodiens Bericht fiel recht knapp aus, doch geht daraus eindeutig hervor, dass er eine Entdeckung von größter Wichtigkeit gemacht hat.\r\n* '''Magistrix Larynna''' möchte, dass man zur [[Manaschmiede B'Naar]] geht und einen Blutjuwelensplitter von einem [[Magister des Sonnenzorns]] besorgt. Man soll den Splitter in der Nähe von größeren [[Blutjuwelenkristall]]en benutzen, um Energie von jenem Kristall aufzunehmendenn sie möchte die Wirkung der Aura untersuchen. \r\n* '''Spionagemeister Thalodien''' - Spionagemeister Thalodien hat einige Hochrangige Ziele der [[Blutelfen des Sonnenzorns]] im Auge, wie z.B. ihre [[Warpmeister]], [[Warpingenieur]]e und [[Geologen des Sonnenzorns |Geologen]] bei der [[Manaschmiede B'naar]]. Außerdem interessiert er sich sehr für die Stammrolle von B'naar, die [[Hauptmann Arathyn]] mit sich herumträgt. Hat man diese besorgt, geht es daran eine [[Manaschmiede]] nach der nächsten im Nethersturm abzuschalten. Das geschieht, in dem man sich die Zugangskristalle vom jeweiligen Vorarbeiter besorgt und diese bei der Steuerungskonsole dort benutzt. Als Geschenk für [[Voren'thal]] möchte auch er die beiden Hälften von [[Socrethar]]s Stein aus der [[Konstruktionsbasis: Vergessenheit]] und der [[Konstruktionsbasis: Gehenna]] besorgt haben.\r\n* '''Veronia''' - Veronia bringt Agenten der [[Seher]] hinter feindliche Linien, wenn sie bereit sind, zur [[Manaschmiede Coruu]] aufzubrechen, um sich dort bei Caledis Morgenhell zu melden.",},
			["Arellas Feuerlaub"] = { content = "'''Arellas Feuerlaub''' war ein Hochhexer des [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzugs]]. Dieser Hochelf war einst ein Bürger von [[Quel'Thalas]] und ist im ewigen Kampf mit dem [[Totenbeschwörer]] [[Diesalven]] gefangen. Zu seinen Ehren wurde in der Waffenkammer des [[Scharlachrotes Kloster|Scharlachroten Klosters]] eine Statue errichtet.",},
			["Argentumdämmerung"] = { content = "Die Argentumdämmerung ist eine Fraktion, die sich der Bekämpfung der [[Geißel]] verschrieben haben. Manche sagen, dass auch die dunkelste Stunde von einer neuen Dämmerung gefolgt wird. Wo immer Dunkelheit heraufzieht, wird das Licht der Hoffnung die Schatten vertreiben; wo immer die Mächte des Bösen im Verborgenen wirken, sind die tapferen Männer und Frauen der Argentumdämmerung zur Stelle, um ihre finsteren Pläne zu vereiteln. Die Argentumdämmerung ist eine Organisation, die keinen Unterschied macht zwischen [[Allianz]] und [[Horde]], sondern statt dessen versucht, die [[:Kategorie:Volk|Völker]] [[Azeroth]]s im Kampf gegen das Böse zu vereinen.Dadurch jedoch kam es zur Abspaltung und zur Entstehung der [[Bruderschaft des Lichts]] .\r\n==Einsatzgebiete==\r\nZwar sind die Agenten der Argentumdämmerung immer wachsam und auf der Hut vor den Dienern der Finsternis in all ihren wechselhaften Gestalten, doch in jüngster Zeit konzentiert sich die Organisation auf ein Gebiet [[Azeroth]]s, in dem das Böse lange Zeit ungestört walten konnte: die [[Pestländer]] [[Lordaeron]]s. Spezialeinheiten der Argentumdämmerung bewachen die Eingänge der [[Pestländer]] beim [[Bollwerk]] zwischen [[Tirisfal]] und den [[Westliche Pestländer|westlichen Pestländern]] und bei der [[Zugwindspitze]], einem engen Gebirgspass der südlich von den [[Östliche Pestländer|Östlichen Pestländern]] ins [[Alteracgebirge]] führt. Die Argentumdämmerung hat auch einen Stützpunkt tief im Herzen der [[Pestländer]], bei der [[Kapelle des Hoffnungsvollen Lichts]], östlich von [[Corins Kreuzung]].\r\n==Rufsteigerung==\r\nDie Argentumdämmerung sucht ständig nach mehr Kämpfern, die ihre Sache unterstützen, und die Zahlen derjenigen, die die Anstecknadel der Argentumdämmerung tragen, nimmt täglich zu. Große Belohnungen warten auf Abenteurer, die helfen und die Verderbnis der [[Geißel]] in den [[Pestländer]]n bekämpfen, indem sie die mächtigen Diener des [[Lichkönig]]s in der [[Scholomance]] und [[Stratholme]] zur Strecke bringen. Die Organisation verfügt über viele mächtige [[Verzauberer]], die spezielle Verstärkungen herstellen können, welche dem Träger Schutz gegen alle Arten von [[Magie]] gewähren. Darüber hinaus verleiht die Argentumdämmerung all jenen Abenteurern Einsicht in die Pläne ihrer Handwerker, die sich als der Sache ganz und gar verschrieben erwiesen haben. Mit diesen Plänen und Mustern können Abenteurer selbst die Rüstungen herstellen, welche sich im langen Kampf der Argentumdämmerung gegen das Böse bewährt haben. \r\n'''Quelle:'''",},
			["Argus"] = { content = "'''Argus''' ist der Name der ursprünglichen Heimatwelt der [[Eredar]]. Die Erinnerung an Argus wird noch heute hauptsächlich von den unverdorbenen [[Draenei]] in großen Ehren gehalten. Dies spiegelt sich z.B. in Namensgebungen wie der \"[[Hand von Argus]]\" oder \"[[Arguswacht]]\" wieder. Viele Draenei vermuten, dass Argus zerstört wurde und sie trauern um ihre alte Heimat und ihre Hauptstadt [[Mac'Aree]], wie um so vieles andere, was sie dort an Wissen und Kunstwerken zurücklassen mussten.",},
			["Arguswacht"] = { content = "Die Arguswacht ist eine mit dem [[Syndikat]] in [[Alterac]] verbündete Splitterfraktion des [[Schattenrat]]es. Man weiß nicht, was die Arguswacht genau ist, aber wenn sie mit dem [[Syndikat]] zusammenarbeiten, dann sind sie eine Bedrohung für die [[Vorgebirge des Hügellands]] und das [[Alteracgebirge]].\r\n==Persönlichkeiten==\r\n* [[Nagaz]]",},
			["Arikara"] = { content = "Die [[Windnatter]] Arikara in [[Tausend Nadeln]] wird als tödliche Kreatur beschrieben.\r\n[[Magatha Grimmtotem]] in [[Donnerfels]] schickt Helden aus, um Arikara zu beschwören. Dafür müssen sie das hochheilige Feuer des Lebens mit geläutertem Brandpulver entzünden. Nach [[Magatha Grimmtotem|Magathas]] Worten soll Arikara eine Kreatur der Rache sein und [[Cairne Bluthuf]] bedrohen, da die Lehren der [[Tauren]] sich zu sehr verändert haben und Arikara darüber erzürnt ist. \r\nDiese Ansicht stößt bei anderen [[Tauren]] jedoch auf Unverständnis, da es keinen Sinn ergibt. Kurioserweise wird Arikara auf dem Friedhof im Dorf des feindlichen [[Tauren der Grimmtotem|Grimmtotem Klan]]s beschworen - Magathas eigenem Klan. Das läßt vermuten, dass die Rache der [[Windnatter]] sich nicht gegen [[Cairne Bluthuf]], sondern gegen den [[Tauren der Grimmtotem|Grimmtotem Klan]] wendet und sie deshalb zerstört werden soll. Oder aber, dass die Windschlange direkt vom [[Tauren der Grimmtotem|Grimmtotem Klan]] aufgehetzt wurde und Teil von Magathas Ränkespielen um die Macht im [[Tauren]]volk ist.",},
			["Arkanelementar"] = { content = "'''Arkanelementare''' sind keine wahren Elementare, so wie Feuer, Erde, Luft und Wasser-[[Elementare]], denn sie waren nie ein Teil der Armeen der [[Alte Götter|Alten Götter]] und existieren in [[Azeroth]] als physikalische Manifestationen von reiner [[Arkaner Magie]] oder sogar der Mana-Energie selbst. Die meisten kann man im [[Düsterbruch]], dem [[Immersangwald]] und in den [[Geisterlande]]n finden. Häufig hinterlassen sie Fragmente aus kristallisierten Mana.Eine Abart sind die [[Manawyrm]]s.\r\n==Arten==\r\n* [[Arkananomalie]]\r\n* [[Arkane Entartung]]\r\n* [[Arkanverschlinger]]\r\n* [[Arkangespenst]]",},
			["Arkanelementare"] = { content = "#REDIRECT [[Arkanelementar]]", redirect = "Arkanelementar",},
			["Arkaner Wachposten"] = { content = "Als '''Arkane Wachposten''' werden die [[Arkankonstrukt]]e auf der [[Insel von Quel'Danas]] bezeichnet. Die unkontrollierten Energien des [[Sonnenbrunnen]]s verursachten Fehlfunktionen bei den Wachposten, die auf dieser Insel patrouillieren. Die Kristallkerne, die ihr Verhalten steuern, sind irreparabel beschädigt. Doch [[Verteidigerin Xayann]] beim [[Sammelpunkt der Zerschmetterten Sonne]] hat neue Kristalle angefertigt, mit denen die [[Offensive der Zerschmetterten Sonne]] die Arkanen Wachposten unter ihre Kontrolle bringt. Dies geschieht, indem die abgestimmten Kristallkerne ins Innere von besiegten herumirrenden Wachposten gesteckt und sie so zu freundlichen Einheiten gemacht werden. Die Zerschmetterte Sonne wird die Arkankonstrukte dann an verschiedene Orte entsenden, um sie dort einzusetzen, sobald sie konvertiert sind.",},
			["Arkane Magie"] = { content = "'''Arkane Magie''' entstammt dem [[Nether]]. Ihr Gegenteil sit die rohe [[Nethermagie]]. Sie wird von [[Magier]]n genutzt und beinhaltet Portalzauber, Angriffszauber wie 'Arkanes Geschoss' und 'Arkane Explosion'und Unterstützungszauber, die die Intelligenz erhöhen. Arkane Magie hat jedoch den Nachteil, das sie [[Dämonen]] anlockt. Sie äußert sich durch blaue, knisternde Energie.\r\nDie [[Titanen]] brachten die Arkane Magie erstmals nach [[Azeroth]]\r\n'''Formen der arkanen Magie'''\r\n'''Sympathetische Magie'''\r\nJedes Wesen hinterlässt einen Teil seiner eigenen Aura an allem, was er berührt. Ein Gegenstand, mit dem man sich mehr beschäftigt, besitzt eine größere Sympathie als ein Gegenstand, mit dem man sich nicht mehr beschäftigt. Mann kann mit der Magie die Aura auf denjenigen zurückführen, der sich mit dem Gegenstand beschäftigt hat. So kann man in dem Geist der Person lesen, welche die Sympathie entgegen gebracht hat. Da diese [[Magie]] nicht kriegerisch ist, ist sie nicht für ingame-Magier erlernbar.",},
			["Arkangespenst"] = { content = "'''Arkangespenster''' sind eine Unterart der [[Arkanelementare]]. Sie ähneln im Aussehen dem [[Leergespenst]], unterscheiden sich aber in ihrer elementaren Zugehörigkeit und ihren Fähigkeiten von ihren dämonischen Doppelgängern, die im Gegensatz zu ihnen zu den [[Leerwandler]]n gehören.\r\n==Persönlichkeiten==\r\n* [[Anomalus]]\r\n* [[Arkanimus]]\r\n* [[Vexallus]] ([[Sonnenbrunnen: Terrasse der Magister]])",},
			["Arkanist"] = { content = "''\"Mach keinen Finger krumm, bevor du nicht weiß, was dabei für dich rausspringt.\"'' (Zitat eines Arkanisten)\r\nArkanisten sind [[Blutelfen Magier]]. Sie machen natürlich nur im äußersten Notfall von Nahkampftechniken Gebrauch, aber deshalb sollte man trotzdem nicht unvorbereitet sein. Arkanisten wollen für ihre Mühe belohnt werden, denn der Geist des [[Magier]]s ist seine stärkste Waffe.",},
			["Arkanist Doan"] = { content = "'''Arkanist Doan''' befindet sich in der Bibliothek des [[Scharlachrotes Kloster|Scharlachroten Klosters]]. Er ist der Bewahrer der Klosterbibliothek; ein Wächter des Arkanen, dem der [[Scharlachrote Kreuzzug]] angeblich mistrauen soll. Aber noch besitzt er das offizielle Vertrauen des Kreuzzuges und verwahrt dem [[Scharlachroter Schlüssel|Scharlachroten Schlüssel]] zu den anderen Sektionen des Klosters.\r\n==Fähigkeiten==\r\nArkanist Doan setzt vor allem auf Verwandlungs, Arkan- und Flächenzauber. Er hat einige mächtige Zaubersprüche in seinem Repertoire, die einem das Leben schwer machen können, bietet dafür aber auch eine 40%-Chance auf den Drop der beliebten Illusionären Rute. Unter anderem kann er eine acht Sekunden andauernde Stille wirken oder ein Gruppenmitglied für vierzig Sekunden in ein Schaf verwandeln (dieser Fluch kann von Priestern aufgehoben werden). Darüber hinaus arbeitet er mit arkanen Explosionen und benutzt, sobald man ihn auf die Hälfte seiner Lebenspunkte herunter gebracht hat, einen Flächeneffekt, der ca. 900 Punkte Feuerschaden verursacht und einen Schild, der ihn für zehn Sekunden immun macht. In seiner Truhe befindet sich der scharlachrote Schlüssel, der die beiden nächsten Abschnitte der Instanz, Waffenkammer und Kathedrale, aufschließt.",},
			["Arkanit"] = { content = "'''Arkanit''' ist ein Metall, dass [[Magie]] leitet. Mit einer speziellen [[Schmiede]]weise kann mann jedoch auch Magieresistente [[Artefakt]]e schmieden. Das Metall findet sich vor allem in [[Azshara]].",},
			["Arkanitboje"] = { content = "Eine Arkanitboje wird benötigt, um den [[Der weiße Riese|Weißen Riesen]] anzulocken - Den Zorn von [[Neptulon]]: Einhundert Meter Tod und Zerstörung pur, der einen Blauen Szeptersplitter vom [[Szepter der Sandstürme]] besitzt, den man in der Questreihe zur Öffnung der [[Tore von Ahn'Qiraj]] zu [[Anachronos]] bringen muss. \r\n[[Narain Pfauentraum]] aus [[Tanaris]] ist sich zu 99% sicher ist, eine solche Arkanitboje konstruieren zu können, aber er braucht eine gehörige Menge Materialien dafür. Wenn er also so einen Köder basteln soll, möchte er, dass man ihm 20 [[Arkanit]]barren, 10 [[Elementium]]erz, 10 Azerothianische Diamanten und 10 blaue Saphire bringt.\r\nDer beste Ort, um die Boje dann zu platzieren, befindet sich an der Küste [[Azshara]]s in der Bucht der Stürme. Man hält nach einem wirbelnden [[Mahlstrom]] Ausschau, und vermutlich ist die ganze Gegend mit Wrackteilen übersät.",},
			["Arkankonstrukt"] = { content = "'''Arkankonstrukte''' sind magische Automaten ([[Konstrukte]]) mit roher Kraft, die von wertvollen Arkankernen angetrieben werden. Sie sind dick gepanzert und können schwere Schläge austeilen. Deswegen werden sie oft zum Schutz von Städten oder bestimmten Orten eingesetzt. Bei ihren Überresten findet man kristallisierte Fragmente magischer Energie. Sie werden u.a. als ''Arkanwächter'' für den Schutz der Städte der [[Blutelfen]] eingesetzt.\r\n==Arten==\r\n* [[Arkanbeschützer]]\r\n* [[Arkanhäscher]]\r\n* [[Arkanpatrouille]]\r\n* [[Arkanwachmann]]\r\n* [[Arkanzerstörer]]\r\n* [[Arkaner Wachposten]]",},
			["Arkanomikon"] = { content = "Das Arkanomikon ist im BEsutz des [[Blauen Darchenschwarms]]. Es ist eine Karte sämtlicher [[Leylinien]] der Welt und wurde, seit [[Norgannon]] selbst sie an [[Malygos]] übergab, ständig aktualisert. Heute nutzt der [[Blaue Drachenschwarm]] das Arkanomikon, um mit der Hilfe der [[Sognadel]]n die[[ Magie]] in ihre Heimstatt zu leiten.",},
			["Arkanpatrouille"] = { content = "Die Arkanpatrouillen im [[Immersangwald]] gehören zu den [[Arkankonstrukt]]en und wurden einst von den Vorvätern der [[Blutelfen]] zum Schutze der Stadt [[Silbermond]] erschaffen. Sie befinden sich jedoch in einem gefährlichen Zustand des Verfalls, denn sie erkennen die [[Blutelfen]] nicht länger als ihre Herren und greifen sie ohne Vorwarnung an. Man findet die Patrouillen im zerstörten Teil von [[Silbermond]], im Nordwesten.",},
			["Arkantitan"] = { content = "'''Arkantitanen''' sind weiter verbesserte Formen von [[Arkankonstrukt]]en. Sie wurden von den [[Naaru]] konstruiert, um ihre Festungen zu verteidigen. Sie befinden sich haptsächlich in der [[Festung der Stürme]]. Sie sind aus gehärteter [[Nether]]energie geformt und gehorchen ihren Herren blind.\r\n'''Bekannte Arkantitanen'''\r\n* [[Mechanolord Capacitus]]",},
			["Arkatraz"] = { content = "#REDIRECT [[Festung der Stürme: Arkatraz]]", redirect = "Festung der Stürme: Arkatraz",},
			["Arkkoroc"] = { content = "Lord Arkkoroc ist eine geringere Gottheit, der in [[Azshara]] im Tempel von Arkkoran residiert.\r\nEr möchte, dass man die [[Hydra]] [[Hetaera]] erschlägt und ihm ihre drei Köpfe bringt, denn [[Hetaera]] tötet seine Kinder, die Meeresriesen in der [[Bucht der Stürme]]. Im Gegenzug wird Arkkoroc den Namen von [[Razelikh]], einem [[Dämonen]]lord enthüllen.",},
			["Armee der Verderbnis"] = { content = "Armee der Verderbnis (eigentlich Namenlose Armee Shezzar's, im Volksmund so betitelt) \r\n==Aufenthaltsort==\r\nNach dem Auszug aus [[Nethergarde]] wahrscheinlich Hillsbrad, Pyrewood, Ambermill oder Dun Garok. \r\n==Aufgaben: == \r\nDie Armee der Verderbnis dient Shezzar und seinem dunklen Rat. Sie sind nicht böse, aber skrupellos wenn es um das erreichen ihrer Ziele geht. Ihr jetziges Hauptunterfangen ist das friedliche, unentdeckte Ausnutzen der Nördlichen Menschensiedlungen, um ein geeignetes Versteck für ihre Schandtaten zu finden. Eigentlich sucht die Armee aber nach den \"Netherkugeln\", mysteriösen Schattenartefakten von denen fast nichts bekannt ist. (Fast alles ooc-wissen) \r\n==OOC-Aufgaben: == \r\nDie AdV ist eine Rollenspielgilde mit besonderem Fokus auf Events, aber auch mit genügendem Freien RP. \"Events\" können dabei ganz unterschiedlicher Art sein und verschiedene Ausmaße haben. Die Eroberung von Nethergarde beispielsweise war ein großes Event (nicht die Verteidigung, wo wir nur teilweise mitorganisator waren!), während manche Events eher kleine RP-Questreihen sind. \r\n(Mehr zur RP-Spielweise und Events hier: \r\n==Geschichte: == \r\nDie komplette Geschichte kann von den Spielern nach und nach im Spiel und in Events erfahren werden. Eine kurze Einstiegsgeschichte, um sich in das AdV-Feeling hineinzuversetzen findet ihr hier:",},
			["Arnak Grimmtotem"] = { content = "'''Arnak Grimmtotem''' ist der Anführer der [[Tauren der Grimmtotem]] auf dem [[Düsterwolkengipfel]] in [[Tausend Nadeln]]. Sein Lager auf den Klippen in der Nähe des Gipfels ist entweder über die Seilhängebrücken oder vom Brachland aus durch die „[[Hügel der Klingenhauer]]“ zu erreichen. Arnak der Ausgestoßene wird wegen ruchloser Verbrechen des Mordes und der Entführung der Taurin [[Lakota Windweise]] steckbrieflich gesucht. [[Klippenbehüter Langhorn]] im [[Freiwindposten]] hat deshalb ein Kopfgeld auf ihn ausgesetzt. Arnak wollte Lakota Windweise aus dem Freiwindposten zur Frau nehmen, aber nachdem sie seinen Antrag abgelehnt hatte, kehrte er in der Nacht zurück und entführte sie. Ihr Bruder wollte ihn aufhalten, aber Arnak war einfach zu stark. Er tötete Ihren Bruder, dann brachte er sie zum Düsterwolkengipfel.",},
			["Arrazius der Grausame"] = { content = "#REDIRECT [[Arazzius der Grausame]]", redirect = "Arazzius der Grausame",},
			["Artefakt"] = { content = "#Redirect",},
			["Arthas"] = { content = "==Allgemeines==\r\n'''Arthas''' war der einzige Sohn von König [[Terenas Menethil]] und Kronprinz von Lordaeron. Nun ist er die Inkarnation des [[Lichkönig]]s und schmiedet vom [[Frostthron]] in [[Nordend]] aus Pläne, um [[Horde]] und [[Allianz]] gegen ihre eigenen Völker zu wenden so wie er einst vom [[Lichkönig]] korrumpiert wurde, sich gegen seinen eigenen Vater zu stellen. \r\n===Charakter===\r\nArthas war einst ein idealistischer, wenn auch etwas unbedachter junger Mann, der davon träumte, eines Tages Nachfolger seines Vaters als König von [[Lordaeron]] zu werden. Er besaß große Ehrfurcht vor dem heiligen Licht und wünschte sich nichts sehnlicher, als Leid von seinem geliebten Volk abzuwenden. Prinz Arthas war einst ein heroischer und tugendhafter Verteidiger seiner Heimat. Aller Sturköpfigkeit und unterschwelligen Arroganz zum Trotz, konnte niemand seine Tapferkeit und Zähigkeit bestreiten. \r\n===Ausbildung zum Paladin===\r\nArthas wurde mit neunzehn Jahren [[Paladin]]-Lehrling und Lieblingsschüler von [[Uther Lichtbringer]]. Er liebte den gütigen Uther wie einen Onkel, sehnte sich aber danach, sein Schicksal selbst in die Hand zu nehmen und ein Held wie die tapferen Veteranen zu werden, die im [[Der Zweite Krieg|Zweiten Krieg]] gekämpft haben. Auch wenn ihn das Ende seiner kurzen Affäre mit der [[Zauberer|Zauberin]] [[Jaina Prachtmeer]] schmerzte, ging Arthas ganz in seinen Rollen als Prinz von [[Lordaeron]] und heiliger [[Paladin]] auf. Doch dann kam die Geißel und verheerte sein Königreich mit ihrer Seuche. Der Prinz zog gegen die Geißel, doch in Stratholme erhob er seinen Hammer gegen sein eigenes Volk. Danach war er nie mehr der glorreiche Prinz Lordaerons, der er einst gewesen war. Er schwor, den Schreckenslord [[Mal'Ganis]], den er für den Anführer der Geißel hielt, bis ans Ende der Welt zu folgen.\r\n===Verfolgung nach Nordend===\r\nNachdem [[Mal'Ganis]] ins arktische Land [[Nordend]] entkommen war, sammelte Arthas seine Streitkräfte und folgte ihm. Er gab zwar vor, die Bedrohung durch die untote [[Geißel]] ein für allemal beenden zu wollen, aber in Wirklichkeit wurde er von seiner Rachsucht getrieben. Um mit [[Mal'Ganis]] abzurechnen und sich Genugtuung zu verschaffen, hätte er den [[Schreckenslord]] bis ans Ende der Welt gejagt.\r\n===Die Runenklinge des Lichkönigs===\r\nIn den kargen Eiswüsten [[Nordend]]s traf er auf [[Muradin Bronzebart]] und eine Expedition seiner [[Forscherliga]]. Muradin war aufgebrochen, um die magische Runenklinge [[Frostgram]], eine durch [[Ner'zhul]] geschmiedete und verfluchte Waffe, zu finden, die sich in geheimen Gewölben unterhalb des Eises verbarg. Von der Macht des Schwertes überzeugt, die in der Lage wäre, [[Mal'Ganis]] zu vernichten, machte er sich gemeinsam mit Muradin auf die Suche. Er ließ sich weder von den Wächtern der Runenklinge, noch von der Inschrift im Sockel des Schwertes warnen, und war sogar bereit, das Leben seines Freundes zu opfern. Der junge Prinz unterlag den Einflüssen der Klinge: er irrte Tag um Tag in den erstarrten Stürmen von [[Nordend]] umher, um schließlich Eiskrone zu erreichen und Ner'zhul seine Seele anzubieten. Die vampirische Runenklinge verlieh ihm ungeahnte Macht, aber Arthas verlor seine Seele und wurde dem Willen des [[Lichkönig]]s unterworfen.\r\n===Wandel zum Todesritter===\r\n[[Ner'zhul]]s subtiles Ränkespiel hatte Arthas zu [[Frostgram]] geführt und ihn verdorben. Durch die Runenklinge, die der [[Lichkönig]] geschmiedet hatte, hörte Arthas nun die Stimme des dunklen Lords der Toten und wurde auf seine finsteren Pläne eingeschworen. Nachdem Arthas seine Rache an [[Mal'Ganis]] geübt hatte, wanderte er in die eisigen Einöden von [[Nordend]] hinaus. Von [[Frostgram]]s ständig bohrender Stimme gequält verlor er auch den letzten Rest seines Verstandes. Arthas wurde [[Ner'zhul]]s erster Todesritter und der mächtigste General der [[Geißel]]. Er war verantwortlich für die Zerstörung von [[Lordaeron]] sowie viele Morde. Arthas Liste an getöteten Gegner ist lang: Er tötete den Schwarzen Drachen [[Searinox]], bekämpfte [[Kel'Thuzad]], vernichtete [[Mal'Ganis]] und den Wächter von [[Frostgram]], später tötete er als [[Todesritter]] seinen ehemaligen Mentor [[Uther Lichtbringer]], seinen Vater König [[Terenas]], [[Sylvanas Windläufer]], [[Antonidas]], den Blauen Drachen [[Sapphiron]] und den [[Vergessene]]n unter [[Azjol-Nerub]]. \r\nNach dem Fall von [[Lordaeron]] und dem Mord seines Vaters ernannte sich Arthas schnell selbst zum König. Er herrschte mit eiserner Hand über der Asche des menschlichen Königreiches. Ein Riss in der [[Eiskrone]] ließ ihn nach und nach seine nekromantischen Kräfte verlieren und so musste er zu [[Ner'zhul]] zurückzugehen, der sich von den Armeen [[Illidan]]s und [[Kael'thas]]' bedroht sah. Arthas schaffte es trotz der Hilfe von [[Anub'arak]] nicht, sich einen Weg unter den alten Katakomben von [[Azjol-Nerub]] zu bahnen, um [[Illidan]] zuvorzukommen, indem er den [[Frostthron]] als erster erreichte. Arthas zerstörte [[Eiskrone]] mit der Schneide des mächtigen [[Frostgram]], und ließ sich durch den Geist von [[Ner'zhul]] übernehmen. Der ehemalige Hexer und der junge Prinz herrschen von nun an in nur einem Körper über die untote Nation.",},
			["Artorius der Verhängnisvolle"] = { content = "'''Artorius der Verhängnisvolle''' ist ein Dämonischer Verderber, der in Gestalt eines Tauren mit Namen Artorius der Liebenswürdige durch Winterquell wandert. Unter dem Fell verbirgt sich allerdings eine ausgewachsene Verdammniswache, die alles verdirbt, was ihm unterkommt. Die Natur welkt und siecht in der Gegenwart dieses Agenten der Brennenden Legion dahin.",},
			["Arugal"] = { content = "#REDIRECT [[Erzmagier Arugal]]", redirect = "Erzmagier Arugal",},
			["Arygos"] = { content = "Der uralte [[Blauer Drachenschwarm|blaue Drache]] Arygos war einer der drei Großdrachen, die sich in [[Silithus]] im [[Krieg der Sandstürme]] für den Kampf gegen die [[Qiraji]] opferten, damit [[Anachronos]] die magische Schutzbarriere, den [[Skarabäuswall]], errichten konnte. Obwohl er danach als verstorben galt, findet man ihn aktuell im [[Tempel von Ahn'Qiraj]] in der Gestalt eines [[Gnom]]s.",},
			["Arzeth der Erbarmungslose"] = { content = "'''Arzeth der Erbarmungslose''' ist eine [[Verdammniswache]] in den [[Ruinen von Sha'naar]] auf der [[Höllenfeuerhalbinsel]]. Er ist ein Diener des Verräters und ihm wurde von seinem dunklen Herrn große Macht verliehen. Mit dem Ältestenstab des [[Lumpenpack]]s jedoch kann man diesem Dämon seine Macht entziehen und ihn danach als Arzeth der Machtlosen töten.",},
			["Aschenbringer"] = { content = "Das jüngste Mitglied in der Familie der legendären Waffen verwandelt Feinde der Legende nach in Asche.\r\n==Geschichte==\r\nDer ursprüngliche Aschenbringer wurde einst von dem mächtigen [[Hochlord Mograine]], dem Begründer des [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzuges]], geführt. Der Name Aschenbringer bezieht sich sowohl auf das Schwert selbst, als auch auf dessen Besitzer. [[Hochlord Mograine]] bekam diesen Spitznamen von seinen Soldaten, nachdem sie im Kampf sahen, wie er mit heiligem Licht eine glühende Schneise der Vernichtung in seine Gegner schlug und so von seinen Feinden nichts als Asche zurückließ.\r\nMograines Sohn, erwies sich jedoch als nicht so standhaft und rein wie sein Vater. Er unterlag dem Einfluss des „Obersten Kreuzzüglers\", welcher einen Handel mit [[Kel'Thuzad]] abgeschlossen hatte, um Mograine in die Falle zu locken. Er half den [[Untote]]n einen Hinterhalt für seinen Vater den Hochlord zu legen, bei dem Mograine umkommen sollte. Lediglich Mograines treueste Begleiter, [[Hochinquisitor Schönufer]], und Mograines Sohn selbst begleiteten den legendären Helden in die verdorbene Stadt [[Stratholme]], wo die Falle zuschnappen sollte.\r\nKurz nach der Ankunft der kleinen Truppe materialisierten sich die [[Untote]]n, stürzten sich mit Inbrunst auf Mograine – und starben. Mehr als 1.000 Gegner wurden von dem mächtigen Hochlord und seinem legendären Schwert dahin gemetzelt. Jedoch hatte Mograine nicht mit der Niederträchtigkeit seines Sohnes gerechnet. Während der Hochlord seinen treuen Begleiter [[Hochinquisitor Schönufer]] unter den zahlreichen Leichen suchte, nahm Mograines verdorbener Sohn das Schwert seines Vaters an sich und rammte es ihm von hinten durchs Herz. Die einst reine Klinge, untrennbar mit seinem Besitzer verbunden, wurde durch diesen unglaublichen Akt des Verrats verdorben. Aber nicht nur das Schwert, auch der Hochlord wurde durch diese Tat korrumpiert und zu einem Vasallen von [[Kel'Thuzad]], einem [[Todesritter]].\r\nNachdem [[Hochinquisitor Schönufer|Schönufer]] sich befreiet hatte, eilte er ins [[Scharlachrotes Kloster|Scharlachrote Kloster]], um dort vom Verrat des Obersten Kreuzzüglers zu berichten. Nach kurzer Zeit ereilte auch den Hochinquisitor der Tod durch Verrat, doch gelang es ihm zuvor einigen Anhängern des Klosters von dem Hinterhalt zu berichten, die daraufhin die \"[[Argentumdämmerung]]\" als Gegenbewegung zum nun verdorbenen [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzug]] gründeten.\r\n==Neue Freundschaften==\r\nAuch heute noch ist der einst mächtige Hochlord ein Sklave. Er befindet sich im Todesflügel der Instanz [[Naxxramas]] und ist Teil der Begegnung mit den vier [[Todesritter]]n. Hier beginnt möglicherweise für euch der Weg zum Erwerb des legendären Aschenbringers.\r\nGelingt es jemanden die vier Todesritter zu vernichten, so besteht die Chance, dass man den nun verdorbenen Aschenbringer erbeutet – das berühmte Schwert von Mograine. Selbst nach so langer Zeit ist es noch sehr mächtig und belastet den Träger auf zweierlei Weise. Es verringert die Gesundheit und senkt den Ruf bei der Fraktion \"[[Argentumdämmerung]]\" temporär auf den Status „Hasserfüllt“. Betritt man jedoch mit dem angelegten Schwert das [[Scharlachrotes Kloster|Scharlachrote Kloster]], so wird das Schwert offensichtlich von den heimischen Kreuzzüglern wieder erkannt. Niemand greift den Träger an. Stattdessen verbeugen sich alle. Sobald man den [[Scharlachroter Kommandant Mograine|Kommandanten Mograine]] erreicht, erscheint der Geist des Hochlords und streckt seinen verräterischen Sohn nieder. In einer versteckten Kammer entdeckt man schließlich den Geist von [[Hochinquisitor Schönufer]]. Er erzählt nun noch einmal die Geschichte, die zum Fall seines Meisters führte und enthüllt eine weitere, nützliche Information: Es existiert noch ein weiterer Sohn Mograines. Im Gegensatz zu seinem Bruder ist dieser Sohn jedoch reinen Herzens und laut [[Hochinquisitor Schönufer|Schönufer]] der einzige Mensch, der über das Wissen verfügt, das verderbte Schwert zu reinigen. Nur mit seiner Hilfe kann man die ursprüngliche, legendäre Macht der Waffe wieder herstellen. Das ganze hat nur einen Haken: Dieser zweite Sohn Mograines befindet sich in der [[Scherbenwelt]]. \r\n==Entstehung==\r\nDie Geschichte der Entstehung von Aschenbringer wird in den [[Höhlen der Zeit: Das alte Hügelland]] im Gasthaus des alten [[Süderstade]] dargestellt. Das Event beginnt, sobald man sich den versammelten Menschen im Gasthaus um [[Hochlord Mograine]] nähert.",},
			["Aschenschwinge"] = { content = "Aschenschwinge ist ein uralter [[Schwarzer Drachenschwarm|Schwarzer Großdrache]] in den [[Düstermarschen]]. Er ist ein alter Torhüter [[Nefarian]]s, der die schwere Bürde auf seinen Schultern trägt, jene der [[Drachenbrut]] auf die Probe zu stellen, die in den Rang einer Elitewache [[Onyxia]]s aufsteigen wollen.\r\nDazu stellt er den Anwärtern die \"Prüfung der Schädel\" und zu dieser Prüfung gehört es, die Champions der anderen [[Drachen]]schwärme - [[Chronalis]], [[Scryer]], [[Somnus]] und [[Axtroz]] - zu töten. Seine Aufgaben zu meistern, ist die Voraussetzung, um [[Onyxias Hort]] betreten zu können.",},
			["Aschenschwinges Bau"] = { content = "'''Aschenschwinges Bau''' liegt südlich von [[Onyxias Hort]] in den [[Düstermarschen]], am Rande des [[Drachensumpf]]es. Hier lebt der [[Schwarzer Drachenschwarm|Schwarzer Großdrache]] ''[[Aschenschwinge]]''.",},
			["Aschenzungen"] = { content = "#REDIRECT [[Zerschlagene der Aschenzungen]]", redirect = "Zerschlagene der Aschenzungen",},
			["Ashkandi"] = { content = "'''Ashkandi, das Großschwert der Bruderschaft''' (auch bekannt als das Große Königliche Schwert) war eines der beiden Schwerter von [[Anduin Lothar]], dem Champion von [[Azeroth]]. Das Schwert zerbrach, als der [[Schicksalshammer]] gegen es antrat. [[Nefarian]] schmiedete die Waffe neu und machte sie zu seiner Klinge. Das Schwert kann von ihm im [[Pechschwingenhort]] erbeutet werden.\r\n===Aussehen===\r\nDas Schwert ist ein mächtiger Zweihänder, ideal für [[Krieger]] und [[Paladin]]e. Der Griff ähnelt den Hälsen und Köpfen zweier roter [[Drachen]].\r\n===Anmerkung===\r\nDie Waffe des [[Orc Krieger]]s im Trailer von [[World of Warcraft]]-[[The Burning Crusade]] hat auffallende Ähnlichkeit zu Ashkandi.",},
			["Asterion"] = { content = "'''Asterion''' ist der Geist eines [[Nachtelfen]], den man in [[Dunkelküste]] in den [[Ruinen von Bashal'Aran]] findet. Sollte er jemals gehalten sein, die Geschichte seines Lebens zu erzählen, würde dies zweifellos die Grenzen der Geduld überstrapazieren. Sein Leben war lang und schmerzvoll, und seine spektrale Gestalt ist die schlimmste Pein von allem. Doch er wird durch Magie in den Ruinen hier festgehalten. Mögen seine Worte auch unaufrichtig erscheinen, so versichert er doch, dass er über die Maßen dankbar wäre, würde man ihm helfen, den Grund für seine Gefangenschaft herauszufinden. Ein altes Mondsteinsiegel bindet ihn und vielleicht findet er einen Hinweis darauf, wenn er den Ohrschmuck der [[Grimmlinge]] und [[Grells]] nur näher betrachten könnte. Die [[Grells]] scheinen erst kürzlich mit dem Siegel in Berührung gekommen zu sein, das ihn an dieses ewige Gefängnis bindet, und er glaubt auch, den Grund dafür zu wissen. Zweifellos ist das Siegel in den Besitz des [[Satyrn]] gelangt, der sie anführt. Er ist sich sicher, dass es so ist. Es war die Kunst eines der mächtigsten [[Hochgeborene]]n, der das alte Mondsteinsiegel erschuf, das sein Gefängnis war, doch in der uralten Flamme in den [[Ruinen von Ameth'Aran]] könnte man dieses Siegel zerstören, um seinen Geist zu befreien.",},
			["Astrale"] = { content = "Die Astralen sind ätherische Wesen, sehr klug und aufmerksam.Seit der Zerstörung ihrer Heimatwelt [[K'aresh]] sind sie perfekt an das Durchwandern des Nethers angepasst und haben den Großteil ihrer physischen Gestalt verloren. In chaotischen Räumen zwischen den Welten wandelnd, sind die Astralen Reisende, die im Wirbelnden [[Nether]] verweilen. Sie sind als Sammler und Händler arkaner Gegenstände und [[:Kategorie:Artefakt|Artefakte]] bekannt. Zu der [[Scherbenwelt]] hingezogen, trachten die Astralen danach, die Schätze zu finden, sie zu stehlen und in den Wirbelnden [[Nether]] zu bringen. Sie sind Lügner und Halunken, die vor nichts Halt machen, um ihre verborgenen Ziele zu erreichen. Die Astralen kümmern sich nicht um die [[Brennende Legion]], sie würden nicht einmal davor Halt machen die verschiedenen Seiten des Konflikts gegeneinander aufzubringen, wenn dies ihren Zielen dienlich wäre.\r\n==Siehe auch == \r\n* [[Astraleum]]\r\n* [[Astrale der Razaani]]\r\n* [[Astrale der Zaxxis]]\r\n* [[Das Konsortium]]\r\n* [[Protektorat]]\r\n==Persönlichkeiten == \r\n* [[Nexuskönig Salhadaar]]\r\n* [[Nexusprinz Haramad]]\r\n* [[Nexusprinz Razaan]]\r\n* [[Nexusprinz Shaffar]]",},
			["Astraler Begleiter"] = { content = "Im Booster-Pack des Wow - Trading Card Game von Upper Deck „Jagd auf Illidan“, das ab dem 01. Juli 2008 im Handel erhältlich ist, wird eine besonders spektakuläre Karte zu finden sein - natürlich entsprechend selten und schwer zu bekommen - der [[AstralerBrandschatzer|Astrale Brandschatzer]]. \r\nWenn Ihr das Glück habt, diese Karte in Eurem Booster-Pack zu finden, löst Ihr sie beim NPC [[Landro Longshot]] in [[Beutebucht]] ein und erhaltet einen Astralen Begleiter. Dieser wird Euch wie ein Haustier folgen, aber er verhält sich alles andere als Passiv. \r\nJedesmal wenn Ihr einen Gegner bezwingt, der Euch Erfahrungspunkte gewährt, wird der Astrale Brandschatzer diesen mit einem Energieblitz seiner Seele berauben. Dafür erhaltet Ihr dann eine neue Astrale Energie, die Ihr bei dem Brandschatzer gegen Gegenstände eintauschen könnt. Sechs der Zehn Gegenstände sind ein Rüstungsset, das Euren Charakter das Aussehen eines astralen Wesens verleiht. Keine Bange – es handelt sich dabei um rein kosmetische Rüstungsteile, Eure Werte werden dadurch nicht modifiziert.",},
			["Astraleum"] = { content = "==Allgemeines==\r\nDas Astraleum war einst die führende Schicht von [[K'aresh]], der Heimatwelt der [[Astrale]]n. Tragischerweise mußten sie [[K'aresh]] verlassen, kurz bevor der Fürst der Leere, [[Dimensius]], seine Leerenarmeen auf die Welt losließ, um alles, was ihm im Weg stand, zu vernichten. Dafür schwor das Astraleum Rache. Seitdem sind sie auf der Jagd nach [[Dimensius]].\r\n===Zersplitterung===\r\nDoch das Astraleum ist finster geworden... wahnsinnig. Rache ist ihr einziges Ziel und alles, was ihnen im Weg steht oder sich ihnen nicht anschließen will, wird als Feind betrachtet. Viele sahen, dass das Astraleum sich direkt in den Wahnsinn stürzte und sind geflohen. Viele der Nexusprinzen des Rats des Astraleums haben das Astraleum verlassen, um andere Gruppen und Fraktionen mit anderen Zielen zu gründen. Ein Beispiel für so einen Ableger ist [[Das Konsortium]]. Ein weiteres das [[Protektorat]] ... \r\n===Aktuelles im Nethersturm===\r\nSeit tausend Jahren, vielleicht mehr, führt [[Nexuskönig Salhadaar]] nun seinen Kreuzzug, bei dem er alles vernichtet, was ihm im Weg steht und das Astraleum bereitet sich im [[Nethersturm]] auf irgendetwas vor. Vielleicht einen Angriff auf die [[Manaschmiede Ultris]]. \r\nDie [[Astrale]]n des Astraleums benutzen Melder, um die Informationen im Stützpunkt zu verteilen. Es gibt nur einem Weg, wie man die Melder sehen und ihre Informationen extrahieren kann. Unglücklicherweise kann man dadurch einen irreparablen Hirnschaden erlangen. Man muss man einige der Anhänger des Astraleums erschlagen und ihre Essenz nehmen. Wenn man eine Essenz hat, trinkt man sie. Mit ihrer Hilfe wird man für kurze Zeit in der Lage sein, die Melder des Astraleums zu sehen. Die Zeit reicht aus, um einen Melder zu zerstören und seine Informationen zu extrahieren.\r\nDer Existenzgrund des [[Protektorat]]s ist danach vollkommen bestätigt, denn das Astraleum ist nicht hier, um [[Dimensius]] zu jagen. Sie sind hier, um Leere zu werden. Sie manipulieren die Leerenergien bei der Manaschmiede Ultris um ihre eigenen Energien an eine Kreatur namens [[Dunkelpirscher]] zu binden. Sie benutzen sicherlich einen Protobeschleuniger um die Umwandlung zu vervollständigen.\r\n===Aktuelles im Schergrat===\r\nDas Astraleum hat eine kleine Kristallschmiede am nördlichsten Rand des [[Schergrat]]s, die als [[Landeplatz von Bash'ir]] bekannt ist. Sie sind Fremden gegenüber nicht gerade freundlich. In Bash'ir soll es größere Gefängnisse geben. Die Anhänger des Astraleums nennen sie Stasiskammern. Die Schlüsseltafel gewährt Zugang zu einer ganz bestimmten Stasiskammer am Landeplatz, die als Stasiskammer Alpha bekannt ist. Diese Kammern enthalten wilde Bestien und Kreaturen von vielen verschiedenen Welten. Das Astraleum hofft, eines Tages Kontrolle über diese Bestien zu gewinnen und sie ihrem Willen zu unterwerfen.",},
			["Astrale der Razaani"] = { content = "Die '''Astralen der Razaani''' bei [[Razaans Landeplatz]] im [[Schergrat]] spielen mit einer interessanten Technologie herum. Sie haben merkwürdige Geräte, aus denen kleine, rosafarbene schwebende Lichtkugeln herauskommen. Diese werden allgemeinhin für Dekoration gehalten, erinnern aber an Seelen. Man darf sie nicht mit den großen gelben Kugeln verwechseln, die sich aus den Astralen lösen, wenn sie sterben. Diese hier sind ganz anders. Diese Kugeln bestehen sowohl aus [[Netherenergie]] als auch aus Seelen. Sogar Gnomseelen sind dabei und die Razaani waren es auch, die die viele Reisende im östlichen Schergrat getötet haben. Ihr Anführer ist [[Nexusprinz Razaan]].",},
			["Astrale der Zaxxis"] = { content = "Eine Gruppe von [[Astrale]]n, die als''' Zaxxis''' bekannt sind, haben ihre Verbindungen zum [[Konsortium]] abgebrochen um ihre eigenen Geschäfte zu machen. Sie machen sogar Geschäfte mit den [[Blutelfen]] im [[Nethersturm]].",},
			["Astranaar"] = { content = "Astranaar befindet sich im [[Eschental]], einem großen Wald südlich der [[Dunkelküste]] auf dem Kontinent [[Kalimdor]]. Um nach Astranaar zu gelangen, folgt man der Straße von [[Maestras Posten]] gen Süden und dann gen Osten. Die [[Nachtelfen]] hier führen keinen offenen Krieg mit der [[Horde]], aber der Frieden ist brüchig und [[Horde]]n-Agenten gehen häufig gegen sie vor, aber stets heimlich.\r\n==Persönlichkeiten==\r\n* '''Faldreas Goeth'Shael''' möchte, dass man zum [[Steinkrallengipfel]] reist und mit [[Bewahrer Albagorm]] dort spricht.\r\n* '''Pelturas Weißmond''' ist der Vater eines kranken Kindes. Er hatte gehofft, [[Orendil]]s Heilmittel würde [[Relara]] retten, aber er fürchtet, es hat die Krankheit, die in seinem Kind wütet, nur gedämpft. Er muss also eine stärkere Medizin finden. Zum Glück hat ihm [[Orendil]] von weiteren Arzneien erzählt, sollte seine Erste versagen. Er sagte, eine [[Träne von Elune]] könne Verderbnis wegwaschen und er erzählte auch von einem gefrorenen Staub, den man in den [[Sternenstaubruinen]] findet. Vielleicht kann man damit [[Relara]]s Fieber senken. \r\n* '''Raene Wolfsläufer''' hat sich des Problems der verderbten [[Furbolgs]] des [[Eschental]]s angenommen.\r\n* '''Relara''' ist die kranke Tochter von [[Pelturas Weißmond]]. Die [[Träne von Elune]] hat einen Teil ihrer Erkrankung weggewaschen und auch ihre Alpträume haben nachgelassen. Aber immer noch wütet das Fieber in ihr, das nur durch eine Behandlung mit [[Sternenstaub]] nachläßt.\r\n* '''Shindrell Feuerflink''' möchte zur Verteidigung von Astranaar die Köpfe der [[Naga der Rächerflossen]] vom [[Zoramstrand]] und [[Prachtschwingen]]giftbeutel aus dem [[Steinkrallengebirge]].\r\n* '''Schildwache Tara Thenysil''' schickt Abenteurer zu [[Schildwache Kaela Schattenspeer]] zu Hilfe, die auf der [[Scherwindklippe]] im [[Steinkrallengebirge]] den Taleingang beobachtet.\r\n* '''Verteidigerin Palanaar''' möchte, dass man nach [[Waldeslied]] geht und dort mit [[Architekt Nemos]] spricht.",},
			["Astromant"] = { content = "Als '''Astromanten''' bezeichnet man [[Blutelfen Magier]] und man findet sie häufig in der [[Festung der Stürme]]. Sie gehören zu den Feuermagiern und haben sich auf mächtige Rüstungszauber genauso wie todbringende Feuerbälle und Feuerschläge spezialisiert. Man unterscheidet dabei je nach Rang unter Astromantennovize, Astromant und Astromantenlord.\r\n==Berühmtheiten==\r\n* [[Astromant Darnarian]]\r\n* [[Großastromantin Capernian]]\r\n* [[Hochastromant Solarian]]",},
			["Atal'ai"] = { content = "#REDIRECT [[Trolle der Atal'ai]]", redirect = "Trolle der Atal'ai",},
			["Atal'alarion"] = { content = "'''Atal'alarion''' ist ein monströser [[Troll]], tief im [[Versunkener Tempel|Versunkenen Tempel]] in den Sümpfen des Elends. Er ist der Wächter des Götzen, eine uralte böse Präsenz.",},
			["Atiesh"] = { content = "Der legendäre Stab '''Atiesh, der Hohestab des Wächters''', wurde ursprünglich vom \"[[Wächter von Tirisfal]]\" geführt. Der letzte bekannte Besitzer der Waffe ist [[Medivh]], ein [[Magier]] der mit dafür verantwortlich war, dass das [[Dunkle Portal]] geöffnet wurde und die [[Horde]] in [[Azeroth]] einfallen konnte. Der Hohestab des Wächters war der Ausgangspunkt seiner Macht und der Ausgangspunkt seiner Verderbnis. Die Verderbnis eines gefallenen Titanen. Die korrumpierte Macht des Zerstörers. Letzten Endes wurde der Stab aus der Saat des Hasses geformt. \r\n==Geschichte==\r\nNach [[Medivh]]s Tod und dem Niedergang von Karazhan entsandten die Kirin Tor eine Magierabordnung, um den Turm zu durchsuchen und alle Gegenstände von Wert mitzunehmen... um sie später \"erfoschen\" zu können. Eben diese Magier fanden auch den legendären Stab. Der Stab wurde nach [[Dalaran]] gebracht, um dort von mächtigen [[Magier]]n studiert und bewacht zu werden. Was folgte, war eine Serie tragischer Ereignisse, in deren Verlauf jeder der mit Atiesh in Kontakt kam, verstab. Der Stab hat sein eigenes Bewußtsein, welches ihm von [[Sargeras]] gegeben wurde. Nach all dem Tod beschlossen [[Die Sechs]], dass es das Beste wäre, wenn man den Stab hinter einer Barriere aus Magie versiegeln würde. Gleichzeitig ernannte man eine Hüterin: Eine Wächterin des Stabes - [[Erzmagierin Angela Dosantos]], die man heute an der [[Kapelle des Hoffnungsvollen Lichts]] findet. Kurz Zeit darauf aber wurde [[Dalaran]] durch [[Archimonde]] vollständig zerstört und der Stab ging verloren. Er wurde vermutlich durch den Schutzmechanismus der Barriere in tausend Stücke zerbrochen. Einige glauben bis heute, dass der Stab der eigentliche Grund für Archimondes Zerstörungswut war. [[Erzmagierin Angela Dosantos]] hat die Fundorte der verschiedenen Bruchstücke zurückverfolgt und ist dabei auf Kel'Thuzads Pläne gestoßen, den Stab wieder zusammenzusetzen. Er ist bereits im Besitz der meisten Teile des Stabes, die er allesamt von seinen treusten Untergebenen aufbewahren lässt. Angela kann nicht oft genug betonen, wie wichtig es ist, dass Kel'Thuzad den Stab niemals vollständig in seine Finger bekommt. Sie gesteht, dass ihr die genauen Folgen unbekannt wären, aber sie ist sich sicher, dass sie sich mit einer Katastrophe von epischen Ausmaßen konfrontiert sähen.\r\n==Erlangung des Stabes==\r\nDie Splitter von Atiesh findet man in [[Naxxramas]]. Bei jedem Untergebenen von [[Kel'Thuzad]] besteht eine geringe Chance eines der Bruchstücke von Atiesh zu erbeuten. Insgesamt 40 dieser Splitter sind nötig, um daraus den Grundstab von Atiesh wiederherzustellen. Hat man diese erste Aufgabe gemeistert und das Gerüst des Stabes in seinem Besitz, bekommt man nun die erste Aufgabe deren Ziel es ist jemanden zu finden, der dabei hilft den immer noch fehlenden Kopf und Fuß des Stabes zurück zu bekommen.\r\nDiese Hilfe findet man in dem [[Drachen]] [[Anachronos]], der im Osten von [[Tanaris]] die [[Höhlen der Zeit]] bewacht. Glücklicherweise kennt er die Fundorte von Kopf und Fuß des Stabes, jedoch handelt es sich bei den neuen Besitzern nicht gerade um zwei Waisenknaben. Niemandem geringeres als [[Kel'Thuzad]], dem Herr von [[Naxxramas]], und [[C'Thun]], dem [[Alte Götter|Alten Gott]] aus dem [[Tempel von Ahn'Qiraj]], gilt es die beiden nächsten Teile zu entreißen. \r\nDer Stab an sich ist nun vollständig. Allerdings ist Atiesh verdorben worden und ein mächtiger [[Dämon]] hat sich in deren Inneren eingenistet. Bevor man den Stab führen darf, ist es nun erforderlich den fiesen Höllenbewohner aus seinem neuen Zuhause zu vertreiben. Um dies zu bewerkstelligen führt der Weg nach [[Stratholme]], wo man die benötigte gesegnete Erde findet, mit deren Hilfe man den [[Dämon]] „Atiesh“ aus dem Stab vertreiben kann. Da man [[Stratholme]] lediglich zu fünft betreten kann, muss man der [[Höllenbestie]] auch mit solch einer kleinen Gruppe entgegentreten. Im Laufe des Kampfes lässt der Dämon eine legendäre Waffe fallen, die verwendet werden kann, um „Atiesh“ zu besiegen.\r\nNachdem man auch diese letzte Herausforderung gemeistert hat, heißt es nun noch einmal zurück zu [[Anachronos]] zu reisen, um die Aufgabe zu beenden. Daraufhin überreicht dieser nun endlich den legendären Atiesh, Hohestab des Wächters.\r\n'''Quelle''':",},
			["Attumen der Jäger"] = { content = "'''Attumen der Jäger''' ist ein [[Todesritter]] im Stall von [[Karazhan]], der auf seinem [[Feuriges Schlachtross|Feurigen Schlachtross]] Mittnacht reitet. Über Attumens Reittier hat der [[Nachtwächter Calliard]] noch einige Informationen parat.\r\n==Fähigkeiten==\r\nAttumen der Jäger ist ein sehr starker Nahkämpfer. Die Bossbegegnung ist in drei Phasen unterteilt und es werden zwei Tanks für den Kampf benötigt. Der Haupttank kommt allerdings erst ab der zweiten Phase zum Einsatz. In der ersten, sehr kurzen Phase, hat es der Schlachtzug allein mit dem Pferd zu tun. Der Nebentank zieht Mittnacht an eine beliebige Position, und kurz danach kann mit dem Schaden begonnen werden. Gelegentlich stürmt das Ross auf einen zufälligen Spieler der Schlachtgruppe, geht direkt danach aber zurück zum Tank. Habt man dem Schlachtross 5 Prozent seiner Lebenspunkte abgezogen, ruft es seinen Meister zu Hilfe. Der Jäger Attumen eilt sofort herbei, und muss direkt vom Haupttank beschäftigt werden. Nachdem Mittnacht's Trefferpunkte auf 25 Prozent dezimiert wurden, schwingt sich Attumen auf sein Ross, und man hat es nun mit der Kombination beider Gegner zu tun. Deren Fähigkeiten wurden entsprechend vereint. \r\n* '''Sturmangriff''' - Stürmt auf einen Gegner zu, wirft das Ziel um. \r\n* '''Körperlose Präsenz''' - Dieser Fluch verringert die Trefferchance eines Gegners um 50% und die Chance eines Gegners, mit Zaubern zu treffen, um 50%. \r\n* '''Niederschlagen''' - Fügt dem momentanen Ziel 1500 Schaden zu und schleudert es 3 Sek. lang zu Boden. \r\n* '''Schattenspalten''' - Schattenspalten fügt einem Gegner und seinen nächsten Verbündeten Waffenschaden minus 1500 Schattenschaden zu. Wirkt auf bis zu 3 Ziele.",},
			["Auberdine"] = { content = "'''Auberdine''' ist ein von [[Nachtelfen]] bewohntes Dorf an der [[Dunkelküste]] und stellt den Stützpunkt der [[Allianz]] in diesem Gebiet dar. Von [[Rut'theran]] aus gibt es zwei Reisemöglichkeiten nach Auberdine: mit der Fähre \"[[Mondgischt]]\" und mit einem [[Hippogryphen]]. Beide sind schnell und zuverlässig, aber wenn man noch nicht mit dem [[Hippogryphen]] nach Auberdine geflogen ist, sollte man das schleunigst nachholen. Es legt regelmäßig eine Fähre vom Dock im Nordwesten ab. In Auberdine liegt auch ein Schiff nach [[Sturmwind]].\r\nVor langer Zeit zerschellte ein Schiff auf den Felsen beim Leuchtturm von Auberdine. Viele Kisten [[Elunit]]erz sanken auf den Meeresgrund. [[Elura]]s Schemen war einst Kapitän des Schiffes und verfluchte sich selbst dazu, für alle Zeiten in der Tiefe zu verweilen und ihre Schiffsladung zu schützen. Sie ist der Wächter des [[Elunit]]s.\r\n==Personen==\r\n* [[Hexknall Kurbeldreh]]\r\n* '''Alanndarian Nachtweise''' - Alanndarian Nachtweise entwickelt eine Heilsalbe für das kranke Wild in der [[Dunkelküste]]. Für die Heilwirkung benötigt sie etwas [[Erdwurzel]] und der besseren Wirksamkeit wegen [[Lunarfungus]]. Die Salbe, die sie aus den Reagenzien herstellen konnte, reicht für zehn Dosen. Sie arbeitet weiter mit den Dorfbewohnern zusammen und versucht mehr Salbe herzustellen.\r\n* '''Archäologin Hollee''' - Archäologin Hollee von der zwergischen [[Forscherliga]] hat von [[Chefarchäologe Grauflaum]] in [[Darnassus]] den Auftrag bekommen, unter der Führung des großen [[Ausgrabungsleiter Wirrbart]] zu arbeiten. Doch geriet er in Schwierigkeiten als er ein rätselhaftes Fossil zu Tage förderte und so rannte sie nach Auberdine, um Hilfe zu holen. Nun möchte sie, dass man nach Süden reist und nach [[Ausgrabungsleiter Wirrbart]] sieht. Der Ausgrabungsleiter will das geheimnisvolle Fossil zur [[Forscherliga]] zu [[Chefarchäologe Grauflaum]] nach [[Darnassus]] schicken, aber Dunkelküste ohne ihn zu verlassen, schmeckt ihr gar nicht.\r\n* '''Barithras Mondschatten''' - Barithras Mondschatten entwickelt gerade einen Trank gegen die Verderbnis in der [[Dunkelküste]], für den so rare Pilze wie [[Schorfstängling]]e und [[Todeskappe]]n erforderlich sind.\r\n* '''Cerellean Weißklaue''' - Cerellean Weißklaue trauert um seine verlorene Liebe. Er hätte nie gedacht, dass ihn noch Tausende von Jahren später, die Erinnerungen an seine [[Anaya]] um den Schlaf bringen würden. Er wanderte wie in Trance durch die Wälder von [[Dunkelküste]] und fand sich schließlich in den [[Ruinen von Ameth'Aran]] wieder... wo er den gequälten Geist seiner Geliebten sah.\r\n* '''Gorbold Stahlhand''' - Gorbold Stahlhand ist ein Gemischt- und Handwerkswarenlieferant und möchte die Schließkassetten von den Wracks der \"[[Silbermorgen]]\" und der \"[[Nebelschleier]]\" bergen. Beide Gegenstände findet man an Bord der Schiffswracks nördlich des Dorfes. Es würde den Mannschaftsmitgliedern, die sich noch hier aufhalten, viel bedeuten.\r\n* '''Gershala Nachtraunen''' - Gershala Nachtraunen möchte die Hirnstämme der [[Satyrn]] und [[Naga]] untersuchen, damit sie daraus folgern kann, welches Schicksal die [[Blutelfen]] erwartet. \r\n* '''Gubber Blump''' - Gubber Blump ist ein [[Zwerg]] und liebt das Angeln. Die Blump-Familie ist berühmt dafür. Es gibt eine Fischart, die er in der Gegend gern fängt. Sie heißt Dunkelküstenbarsch. Früher fuhr er mit einem Boot hinaus, um Barsche zu angeln, aber seitdem die gemeinen [[Murlocs]] gekommen sind, fahren keine Boote mehr raus. Außerdem liebt er Krebse.\r\n* '''Gwennyth Bly'Leggonde''' - Gwennyth Bly'Leggonde wurde vom Tempel des Mondes zur Untersuchung der gestrandeten Meereskreaturen geschickt, aber die Anwesenheit der [[Murlocs]] entlang des Wassers hat ihre Forschungen schwierig gemacht. \r\n* '''Laird''' ist ein Fischverkäufer im Dorf Auberdine und muss [[Nessa Schattensang]] in [[Ru'theran]] eine Antwort schicken, denn Sie interessiert sich dafür, wie sehr sich die Fische hier von denen an der Küste [[Teldrassil]]s unterscheiden. Sie können nur vermuten, was die Ursache sein mag, er persönlich hegt jedoch die Befürchtung, dass der Weltbaum die Natur um sich herum beeinflusst.\r\n* '''Schildwache Elissa Sternenhauchs''' - Schildwache Elissa Sternenhauchs Aufgabe ist es, Auberdine vor Schaden zu schützen. Aus diesem Grund hat sie [[Balthule Schattenhieb]] ausgeschickt, um die seltsamen Vorkommnisse rund um den [[Turm von Althalaxx]] im Nordosten zu beobachten. Er hätte eigentlich schon längst wieder zurück sein sollen... \r\n* '''Schildwache Glynda Nal'Shea''' - Schildwache Glynda Nal'Shea sammelt Erkenntnisse über einen roten Kristall entlang der östlichen Bergkette von [[Dunkelküste]]. Außerdem macht sie Jagd auf einen [[Murloc]] namens [[Gurgelbacke]]. Sie nimmt an, dass diese Kreatur die Hütten der [[Murlocs]] am Strand südlich von Auberdine beschützt. \r\n* '''Schildwache Selarin''' - Schildwache Selarin sucht Unterstützung für ihre Herrin [[Raene Wolfsläufer]] in [[Astranaar]] im [[Eschental]], denn mit ihrer Hilfe könnten sie vielleicht wenigstens eines Teils der Verderbnis Herr werden, die sich dort breit gemacht hat. \r\n* '''Terenthis''' - Terenthis ist ein alter Druide. Einige seiner Brüder konnten in [[Teldrassil]] vor einem verderbten [[Furbolg]] gerettet werden und er hat geschworen, weitere Gräueltaten zu verhindern, bevor noch mehr verletzt werden... oder schlimmer. Er hat auch in [[Dunkelküste]] schon die ersten Anzeichen von Verderbnis entdeckt, jedoch noch nichts gefunden, was auf Ausbreitung hindeutet. Er denkt, es wäre logisch, wenn man die Untersuchungen bei den Furbolgs fortsetzen würde um herauszufinden, wie groß die Bedrohung ist.\r\n* '''Tharnariun Baumwahrer''' - Tharnariun Baumwahrer hat möglicherweise ein Heilmittel für das Leiden der Tiere, aber wie er befürchtete, wirkt das Heilmittel nicht. Es stimmt ihn traurig, Geschöpfe der Natur zum Tode zu verurteilen, aber die kranken und besudelten Distelbären müssen ausgerottet werden. \r\n* '''Thundris Windwirker''' - Thundris Windwirker fungiert umsichtig als der Älteste von Auberdine und kümmert sich weise und gerecht um die täglichen Angelegenheiten des Dorfs. Er ist ein alter Freund von [[Jägerin Kella Nachtbogen]] und genießt überall hohes Ansehen. Vor kurzem kam [[Raene Wolfsläufer]] aus [[Darnassus]] durch Auberdine. Sie war auf dem Weg ins [[Eschental]] nach [[Astranaar]] und murmelte etwas von [[Furbolgs]]. Thundris hatte keine Gelegenheit, sie genauer dazu zu befragen, aber vielleicht kann sich ja ein anderer auf die Suche nach ihr begeben.",},
			["Auchenaikrypta"] = { content = "#REDIRECT [[Auchindoun: Auchenaikrypta]]", redirect = "Auchindoun: Auchenaikrypta",},
			["Auchindoun"] = { content = "'''Auchindoun''' liegt in der Knochenwüste in den [[Wäldern von Terokkar|Wälder von Terokkar]] und ist die Ruine einer einstmals großen Festung. Die ursprünglichen Verbannten auf Dreanor hielten den Tod für eine beunruhigende und unglückliche Folge des Lebens, deshalb versteckten loyale [[Draenei Priester]] ihre Toten in der unterirdischen Gräberstadt Auchindoun, einem labyrinthartigen Wunderwerk. \r\nDoch seit mehreren Jahrhunderten schon verbinden sich die Geister von Auchindoun mit einer getrübten Essenz. Viele der Katastrophen, die diese Krypta heimgesucht haben, sind auf diesen geschwächten Zustand zurückzuführen. Unglücklicherweise kann nichts diesen Kreis aufhalten. Das gehört zur Natur der [[Naaru]] - ohne die Leere kann das Licht nicht existieren. Die Auchenai verfüttern die Seelen, die sie gestohlen haben, an einen Sarg, den sie aus der [[Auchenaikrypta]] entwendet haben. Einige glauben, dass sich der erste Exarch der Krypta in diesem Sarg befindet. Die Auchenai versuchen, ihn wieder zum Leben zu erwecken. Viele glauben, dass der [[Schattenrat]] die Explosion, die Auchindoun in tausend Stücke gerissen hat, verursacht hat. Gerüchten zufolge sollen sie im Inneren ein großes Übel erweckt hat. Wenn das stimmt, muss dieses Böse sich gegen sie gewandt haben. Laut diesen Befehlen flieht ein Teil des [[Schattenrat]]s aus Auchindoun.\r\n==Geschichte==\r\nAuchindoun war eine Festung des [[Klan des Blutenden Auges]] auf [[Draenor]]. Nach dem Zweiten Krieg stellte die [[Horde]] dort eine riesige Armee auf, die erneut in [[Azeroth]] einmarschieren sollte. \r\nDoch die Streitkräfte der [[Allianz]], die nach [[Draenor]] gekommen waren, zerstörten durch einen überraschenden Angriff die Festung und zwangen die [[Orcs]] zum Rückzug. Geheimnisvolle Zauberkräfte umgaben die Ruinen von Auchindoun und machten es erforderlich, den Erzmagier [[Khadgar]] herbeizurufen. Der mächtige Zauberer untersuchte die Überreste der großen Festung und erfuhr nicht nur, wo sich das [[Buch des Medivh]] befand, sondern auch, dass [[Ner'zhul]] noch den Schädel des [[Gul'dan]] zur Durchführung seiner Pläne benötigte.\r\n==NSC's==\r\n* '''Levixus''' steht auf den Ruinen von Auchindoun und liest aus dem Buch der Toten. Er ruft die Toten beim Namen und unterwirft die gequälten Seelen durch ein dämonisches Ritual seinem Willen. Wenn er kann, wird er ganz Auchindoun erwecken.\r\n* '''Ramdor der Wahnsinnige''' ist ein Totenpriester und befindet sich bei der westlichen Seite des Rings der Beobachtung in Auchindoun in der Mitte der Knochenwüste. Er sucht ein Buch. Ezekiel hatte es, doch es wurde von den Grobianen im unteren Viertel von Shattrath gestohlen.",},
			["Auchindoun: Auchenaikrypta"] = { content = "Die Auchenaikrypta ist ein Teilbereich von [[Auchindoun]] in den [[Wälder von Terokkar|Wäldern von Terokkar]].\r\nTief in der Auchenaikrypta befindet sich ein Grab: ein Grab, dass keinesgleichen in den zerschlagenen Weiten findet. Aus diesem Grab, dem ersten Grab, wurde das riesige Mausoleum von [[Auchindoun]] geboren. Seit mehreren Jahrhunderten verbinden sich die Geister von [[Auchindoun]] nun mit seiner getrübten Essenz. Viele der Katastrophen, die diese Krypta heimgesucht haben, sind auf seinen geschwächten Zustand zurückzuführen. Unglücklicherweise kann nichts diesen Kreis aufhalten. Das gehört zur Natur der [[Naaru]] - ohne die Leere kann das Licht nicht existieren. Die einzige Möglichkeit besteht darin, die Geister von [[Nagrand]] zu vernichten, bevor sie sich in Wesen der Leere verwandeln. Man muss zu der Auchenaikrypta reisen und dieses Grab finden. Man tötet den Grabwächter und befreit den Geist, der darin gefangen ist. [[D'ore]]s Geist ist der Schlüssel...\r\n==Personen==\r\n* [[D'ore]]\r\n* [[Levixus]]\r\n* '''Großvater Aldrimus''' - Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass man in die Auchenaikrypta geht und Exarch Maladaar vernichtet. Er ist einer der glücklichen Geister. Er war nie an [[Levixus]] gebunden oder Teil eines der bösartigen Experimente in der Nekromantie von Exarch Maladaar.\r\n==Bosse==\r\n* [[Exarch Maladaar]]\r\n* [[Shirrak der Totenwächter]]",},
			["Auchindoun: Managruft"] = { content = "Im Norden von [[Auchindoun]] in den [[Wälder von Terokkar|Wäldern von Terokkar]] liegt die Managruft. Hier haben sich die [[Astrale]]n unter [[Nexusprinz Shaffar]] niedergelassen.\r\n==Personen==\r\n* [[Konstrukteur Morphalius]] ([[Das Konsortium]]).\r\n* [[Mamdy, der Ologe]]\r\n* [[Nexusprinz Haramad]] ([[Das Konsortium]]).\r\n==Bosse==\r\n* [[Pandemonius]]\r\n* [[Tavarok]]\r\n* [[Nexusprinz Shaffar]]",},
			["Auchindoun: Schattenlabyrinth"] = { content = "Das '''Schattenlabyrinth''' ist ein Teilbereich von [[Auchindoun]], der vom [[Schattenrat]] beherrscht wird.\r\n===Das erste Schlüsselfragment===\r\nIn den Hallen des Schattenlabyrinths befindet sich das erste Schlüsselfragment für den Schlüssel für [[Karazhan]]. Es wurde von [[Khadgar]] in einem arkanen Behälter versteckt. Die Behälter sind mit einem mächtigen Zauber belegt, der sie vor unwürdigen Augen beschützt. Als klar wurde, dass er und die [[Söhne Lothars]] in der [[Scherbenwelt]] gestrandet sind, hat er den Schlüssel in drei Teile zerbrochen. Kadgar hat die Schlüsselfragmente in verzauberte Behälter gelegt, und diese dann an damals sicheren Plätzen versteckt. Wegen der dunklen Veränderungen, die die Scherbenwelt durchmachen musste, sind sie heute allerdings alles andere als sicher. \r\n==Bosse==\r\n* [[Botschafter Höllenschlund]]\r\n* [[Schwarzherz der Hetzer]]\r\n* [[Großmeister Vorpil]]\r\n* [[Murmur]]",},
			["Auchindoun: Sethekkhallen"] = { content = "Die '''Sethekkhallen''' von [[Auchindoun]] sind die Gefielde der [[Arakkoa der Sethekk]]. Diese glauben, dass sie die wahren und treuesten Anhänger des Meisters aller [[Arakkoa]] sind. Die Sethekk haben die Zerstörung [[Auchindoun]]s als die Ankunft des Meisters auf [[Draenor]] gedeutet. Sie sind zu den Ruinen aufgebrochen und haben die Relikte ihres größtes Helden, [[Terokk]], mit sich genommen. Sie suchen in den Ruinen noch immer nach ihrem Meister.\r\n===Personen===\r\n* [[Isfar]]\r\n===Bosse===\r\n* [[Dunkelwirker Syth]]\r\n* [[Klauenkönig Ikiss]]\r\n* ([[Anzu]] der Rabengott)",},
			["Auflistung allerlei nützlicher Rituale"] = { content = "==Ritual zur Reinigung eines Toten vor eventuellen Verunreinigungen durch die Religion des Lichts==\r\nSollte man einen Feind niedergestreckt haben, der große Macht durch das abscheuliche Licht erhalten hat, sollte man sich sofort an den nächsten Hexendoktor wenden. Wenn ein solcher nicht schnell erreichbar ist, gehe man folgendermaßen vor: Man löse dem Opfer vorsichtig die Augen heraus und gebe sie in einen Becher; man fange eine Fledermaus und drücke ihr die Augen in den Mund, wobei egal ist, ob die Fledermaus noch lebt oder nicht. Hierdurch werde das Licht von der dunklen Macht [[Hir'eek]]s verschlungen. Der verunreinigte Körper solle nach Möglichkeit verbrannt werden.\r\nUm sich selbst von den Verunreinigungen des Lichts rein zu waschen, koche man einen Sud an aus der Asche des getöteten Feindes und betupfe damit sorgfältig die Stellen, an denen man möglicherweise in Kontakt mit dem Wesen oder auch seiner Waffe/Rüstung gekommen ist. Dadurch wird den möglicherweise anhaftenden Spuren unheiliger Magie gezeigt, dass ihr Herr getötet wurde. Dies sollte den bösen Geist vertreiben.\r\nSollte man verpassen, sich so zu reinigen, sollte man in Kontakt mit unreiner Magie gekommen sein, können schwere Schäden des Geistes entstehen! Am Ende eines Tages, an dem man einen oder mehrere Licht-Kultisten getötet hat, sollte man mindestens ein Reinigungsritual durchführen, um bleibende Schäden zu vermeiden.\r\n==Ritual zum …==\r\n…",},
			["Aufseherin Belamoor"] = { content = "'''Aufseherin Belamoor''' ist eine menschliche Zauberin im [[Lordamere-Internierungslager]] im [[Vorgebirge des Hügellands]]. Sie untersuchte ein aus [[Unterstadt]] gestohlenes Artefakt aus [[Blutstein]], welches ihr von einem Verlassenen namens [[Kegan Dunkelmar]] anvertraut wurde. Über ihre Untersuchungen schrieb sie anschließend einen ausführlichen Bericht in ihr Forschungstagebuch. \r\n==Fähigkeiten==\r\nAls Zauberin beherrscht Aufseherin Belamoor die das Wirken eines Feuerballs und eines Kältekegels, der Feinden in einem kegelförmigen Bereich vor dem Zaubernden Frostschaden zufügt und ihr Bewegungstempo 8 Sek. lang verlangsamt.\r\n==Belamoors Forschungstagebuch==\r\nDas Forschungstagebuch von Aufseherin Belamoor kann man bei ihr finden, sobald sie besiegt wurde. Es handelt sich hierbei um einen Bericht über Experimente mit [[Blutstein]].\r\n'''Inhalt:'''\r\n[[Kegan Dunkelmar]], der Anführer jener kleinen Gruppe von [[Untote]]n, die auf der Suche nach Schutz vor ihren \"Brüdern\" zu uns kam, ist so gar nicht wie die anderen von seinem Schlag. Seine Haut mag verfaulen und Blut mag schon lange nicht mehr durch seine Adern fließen, aber seine Handlungen sind edel und er scheint sich mehr um das Wohl seiner Begleiter zu sorgen, als um sein eigenes Wohlergehen.\r\nIn der Tat zeichnet er sich durch eine Menschlichkeit aus, die ich, wie ich gestehe, gelegentlich an den Menschen um mich herum vermisse.\r\nAber warum erwähne ich das? Nun, ich möchte dem, was ich nun niederschreiben werde, auf diese Weise Glaubwürdigkeit verleihen, denn dies sind die Worte von Kegan. Ich hoffe, dass meine Kollegen, wenn sie dies Tagebuch lesen, verstehen werden, warum ich ihm Glauben geschenkt habe:\r\n''\"Überbleibsel der [[Alte Götter|Alten Götter]] liegen noch immer in den Tiefen der Welt verborgen. Nun wollen sich neue Kräfte diese uralte Macht zu Nutze machen, und wenn sie Erfolg haben, halten sie eine furchtbare Waffe gegen ihre Feinde in Händen.\"''\r\nMit diesen Worten hat mir Kegan seinen Blutsteinanhänger übergeben, und in seinen Augen lag dabei ein Ausdruck von Angst und vielleicht sogar so etwas wie Ehrfurcht. Und als er die Steine in meine Hand legte, blieben seine Augen darauf ruhen, als gebe er den Anhänger nur widerwillig ab. Ekel überkam mich, aber ich weiß bis heute nicht, ob das an der Berührung durch Kegans totes Fleisch lag oder am Anhänger selbst.\r\nDenn ich fühlte darin eine Kraft. Eine tiefe, verborgene, hungrige Kraft. Eine Kraft, die sich nach Freiheit sehnte. Auch wenn meine Kollegen in [[Dalaran]] arge Bedenken hatten, die von Kegan und seinen Begleitern mitgebrachten [[Blutstein]]e zu untersuchen, so fühlte ich mich durch Kegans Ehrlichkeit doch gezwungen, seinen [[Blutsteinanhänger]] zu untersuchen, statt ihn und die vier anderen einzusperren und die Steine zu lassen, wo sie waren. Ich hoffte, meinen Kollegen davon überzeugen zu können, dass diese Steine in der Tat magische Kräfte besäßen und dass, auch wenn wir Hexer von Dalaran die Macht der Blutsteine nicht nutzen wollten, wir wenigstens ihre Eigenschaften studieren sollten, da der Feind sie eines Tages gegen uns verwenden könnte.\r\nUnd so begann ich denn.\r\nIch begann meine Prüfungen zunächst in der Annahme, dass es sich bei Blutstein tatsächlich um Gestein wie Quarz oder [[Obsidian]] handelt. Also machte ich verschiedene Prüfungen zur Gesteinsbestimmung: welche Mineralien der [[Blutstein]] enthielt, wie seine Farbe und sein Härtegrad zustande kamen sowie einige andere für Gestein und Erz übliche Eigenschaften. Aber der Blutsteinanhänger reagierte frustrierenderweise auf keine der Prozeduren wie normales Erz.\r\nGenau genommen reagierte er sogar genau andersherum als erwartet. Fast schien es, als sabotiere der Anhänger meine Experimente absichtlich, als besäße er einen Verstand und sei lebendig. Verärgert, aber nicht entmutigt ging ich nun also davon aus, es handele sich um etwas Lebendiges. Vergeblich. Meine Experimente konnten die Herkunft des Blutsteins nicht enthüllen. Das einzige Rätsel, das ich lösen konnte, war, dass der Blutstein weder lebendig noch tot war!\r\nAusgerechnet dann gelang mir aber plötzlich der Durchbruch. Für mein jüngstes Experiment benötigte ich ein Becherglas, dessen Rand an einer Stelle etwas abgesplittert war. Das eigentliche Experiment erbrachte wieder kein Ergebnis, aber als ich danach den Arbeitstisch reinigte, schnitt ich mir mit dem Becherglas in den Finger. Die Wunde war nicht tief, blutete aber stark. Bevor ich meinen Finger verarzten konnte, war mein Schreibtisch schon voller Blut.\r\nIch wollte es wegwischen, aber da fiel mir etwas höchst Merkwürdiges auf...\r\nDas Blut, das neben dem Blutsteinanhänger auf den Tisch getropft war, bewegte sich langsam auf das Schmuckstück zu, als würde es davon angezogen. Die Blutstropfen, die mit dem Anhänger in Berührung kamen, schienen zu verschwinden, und das Rot des Steins wurde umso intensiver, je mehr von meinem Blut er in sich aufnahm.\r\nAls ich das sah, wurde mein Kopf ganz leicht, was vielleicht weniger an meiner Verletzung lag (denn so viel Blut hatte ich ja nicht verloren) als an der Tatsache, dass ich nach all dem Frust endlich eine der Eigenschaften des Blutsteins gefunden hatte. Ich griff nach einem Hocker hinter mir, setzte mich und dachte nach. Gedanken und Fragen rasten so schnell durch meinen Kopf, dass mir ganz schwindelig davon wurde.\r\nTrinkt der Blutstein Blut? Verlangt er nach Blut? Zieht er Blut an?\r\nOder besteht Blutstein gar aus Blut? Und wenn ja, wessen Blut? Mein Blut? Menschenblut? Blut von Tieren? \r\nVielleicht ist der Blutstein aber auch aus dem Blut eines unbekannten Dings - eines Dings, das Kegan sowohl fürchtete als auch verehrte, als er mir seinen Anhänger gab.\r\nDiese Frage gilt es zu beantworten. Sie ist der Schlüssel. Mein Ehrgeiz wurde angestachelt und ich stürzte mich wieder in meine Experimente. Dieses Mal hielt ich mich nicht lange mit Vermutungen auf, sondern machte jeden mir nur möglichen Test. Freilich war der Aufwand an Zeit und Mühe beträchtlich, aber es erhöhte auch die Wahrscheinlichkeit neuer Entdeckungen. \r\nUnd obwohl mein Labor sehr klein ist und ich niemanden habe, der mir hilft, ist es mir doch gelungen, eine weitere faszinierende Eigenschaft der Blutsteine zu finden...\r\nNeben Blut sind auch elementare Kräfte in dem Stein konzentriert. Feuer, Wasser, Donnern und Fels sind mit dem Blut vermischt (aber die Frage bleibt: wessen Blut eigentlich?). Und obwohl diese Mixtur äußerlich eher träge erscheint, scheinen doch all diese Kräfte innerlich miteinander zu ringen. Fragen über Fragen taten sich auf angesichts dieses ebenso faszinierenden wie beunruhigenden Materials.\r\nAber um diese Frage beantworten zu können, müssen weitere Studien und Experimente an dem Anhänger durchgeführt werden, und ich befürchte, dass es im Internierungslager von Lordamere weder genug Arbeitskräfte noch die erforderliche Ausrüstung dazu gibt. Also übergab ich den Blutsteinanhänger einem Kurier, der ihn nach Dalaran bringen sollte. Ich gab ihm auch genaue Anweisungen für die Experimente mit, auf dass meinen Kollegen die frustrierenden Erfahrungen erspart blieben, die ich gemacht hatte.\r\nWährend ich auf die Ergebnisse dieser Experimente wartete, sprach ich wieder öfter mit Kegan. Ich drängte ihn immer wieder, mir zu sagen, was er über die Blutsteine wusste. Aber nie verriet er mehr als das, was er mir schon gesagt hatte, als er mir den Anhänger gab, wie er überhaupt nicht oft über \"die Verlassenen\" sprach, wie er seinen Klan der Untoten nennt.\r\nAber Kegan war ganz erpicht darauf, über andere Themen zu reden, insbesondere seine Zeit in Lordaeron vor dessen Fall. Er liebt dieses untergegangene Königreich noch immer, obwohl es doch nicht mehr existiert. Meine wachsende Sympathie für Kegan verlieh mir Geduld, während ich auf die Untersuchungsergebnisse wartete.\r\nNach Wochen ohne Nachricht verlor ich die Geduld, forschte nach und erfuhr, dass der Blutstein nie in Dalaran bei meinen Kollegen angekommen war. Mein Kurier war verschollen und der [[Blutsteinanhänger]] mit ihm!\r\nDas sind schlechte Neuigkeiten, denn obschon Kegan und seine Begleiter noch einige andere Blutsteinexemplare haben mit denen wir experimentieren können, befürchte ich, der Anhänger könnte in die falschen Hände geraten.\r\nIch habe einen weiteren Boten nach Dalaran geschickt und gehört, dass sie dort immer noch nach dem Anhänger suchen, und zwar inzwischen auch in den Ruinen außerhalb unserer schützenden Sphäre.\r\nIch kann nur hoffen, dass es nicht zu spät ist.",},
			["Aufstieg der Blutelfen"] = { content = "==Inhalt==\r\nZu diesem Zeitpunkt hatte die [[Geißel]] der Untoten [[Lordaeron]] und [[Quel'Thalas]] schon weitgehend in die toxischen [[Pestländer]] verwandelt. Nur noch wenige Enklaven existierten, in denen die Allianz Widerstand leistete. Eine der Gruppen, die fast ausnahmslos aus Hochelfen bestand, wurde vom letzten Spross der Sonnenwandererdynastie angeführt: Prinz [[Kael'thas Sonnenwanderer]].\r\nKael, selbst ein fähiger Hexer, wurde der schwindenden Allianz überdrüssig. Die Hochelfen trauerten ob des Verlustes ihrer Heimat und beschlossen, sich ihrem gefallenen Volk zu Ehren [[Blutelfen]] zu nennen. Doch während sie sich versuchten, die Geißel in Schach zu halten, litten sie schwer darunter, vom [[Sonnenbrunnen]], der Quelle ihrer Macht, abgeschnitten zu sein.\r\nIm verzweifelten Bemühen, ein Heilmittel gegen die vererbte Magiesucht seines Volkes zu finden, wagte Kael das Undenkbare: Er bekannte sich zum hochgeborenen Erbe seiner Vorfahren und tat sich mit [[Illidan]] und seinen [[Naga]] zusammen, um eine neue Kraftquelle der Magie aufzutun. Die restlichen Befehlshaber der Allianz bezeichneten die Blutelfen als Verräter und schlossen sie auf ewig aus ihren Reihen aus.\r\nKael und seine Blutelfen sahen keinen anderen Ausweg mehr, als [[Lady Vashj]] in die Scherbenwelt zu folgen und dort gegen die Aufseherin [[Maiev Schattensang]] zu kämpfen, die Illidan wieder eingefangen hatte. Den vereinigten Naga- und Blutelfenheeren gelang es, Maiev zu besiegen und Illidan aus ihrem Griff zu befreien. In der Scherbenwelt scharte Illidan daraufhin seine Streitkräfte für einen zweiten Schlag gegen den Lichkönig und dessen Festung [[Eiskrone]] um sich.",},
			["Auftragsmörder"] = { content = "#REDIRECT [[Nachtelfenschurke]]", redirect = "Nachtelfenschurke",},
			["Aufziehraketenbot"] = { content = "Zum [[Winterhauchfest]] 2007 brachte [[Altvater Winter]] vielen braven Helden einen Aufziehraketenbot. Dieser kleine Gefährte läuft brav hinter einem her bis er auf andere seiner Art trifft. Sobald sich zwei oder mehrere dieser Raketenbots treffen beginnen sie sich gegenseitig mit Raketen zu beschießen. Gerüchten zufolge haben sich schon erste Fight Club's gebildet in denen die Aufziehraketenbot gegeneinander antreten.",},
			["Augen des Xavius"] = { content = "Diese Augen ließ sich [[Xavius]] einsetzten, um dadurch die magischen Ströme im [[Brunnen der Ewigkeit]] besser sehen zu können. Viele seiner Genossen betrachteten ihn ehrfürchtig, dass er seine eigenen Augen opferte. Die Augen bestanden aus tiefschwarzem Metall mit rubinroten Schlieren und verstärkten Xavius ohnehin gewaltige Kräfte. Auch gestatteten sie es ihm, Geister und andere unsichtbare Wesen zu sehen.\r\nWie Xavius Augen hergestellt wurden und ob es damals auch noch andere gab, ist nicht bekannt, aber diese Augen erinnern stark an die \" Spektralsicht\" der [[Dämonenjäger]].",},
			["Auge des Sargeras"] = { content = "#REDIRECT [[Auge von Sargeras]]", redirect = "Auge von Sargeras",},
			["Auge des Sturms"] = { content = "Hoch über der zerklüfteten Landschaft des [[Nethersturm]]s befindet sich die Insel, die als '''Auge des Sturms''' bekannt ist. Dieses Schlachtfeld ist bei den Blutelfen wegen seiner reichhaltigen Energiequellen sehr begehrt. Doch auch die Draenei erheben wegen der Nähe zu dem mysteriösen Gefährt der [[Naaru]] Anspruch darauf - der [[Festung der Stürme]].\r\n==Taktik==\r\nDie Startplätze der beiden Fraktionen liegen im Norden und im Süden von 2 Arealen zwischen denen eine Schlucht liegt, die ins Nichts führt und daher nur auf einer der drei Brücken überquert werden kann die über sie führen. Auf jeder Seite befinden sich zwei Stellungen die zu Beginn neutral sind und eingenommen werden müssen. Sobald man die Position eingenommen hat, wird dies durch die Fraktionsflaggen angezeigt, die dann an der Position erscheint. Hier gibt es Punkte für das Besetzthalten der Basen. Die Punkte werden im oberen mittleren Bereich des Bildschirms angezeigt. Hat eine Fraktion 2000 Punkte erreicht ist der Schlachtfeld zuende und die Fraktion hat gewonnen. Weiterhin gibt es ein besonderes Special, denn in der Mitte der zentralen Brücke gibt es einen Flaggenspawnpunkt, an dem in regelmäßigen Abständen eine Flagge erscheint, die man sich schnappen und zu einem der Stützpunkte bringen kann, die man eingenommen hat. Hierfür gibt es nocheinmal Zusatzpunkte.",},
			["Auge von Dalaran"] = { content = "Das sogenannte \"Auge von Dalaran\" war ein geheimnisvolles Artefakt, das magische Kräfte bündeln und verstärken konnte. Mächtige [[Magier]] hatten es einst geschaffen, um die Violette Zitadelle wieder in Stand zu setzen. Der [[Schamanen|Schamane]] [[Ner'zhul]] wollte es jedoch für seine eigenen Pläne nutzen, und durch das Artefakt seine Macht noch weiter vergrößern. Der [[Todesritter]] [[Teron Blutschatten]] griff die Festung in [[Dalaran]] an, stahl das Auge und flohen zurück ins sichere [[Draenor]]. In Verbindung mit dem [[Zepter des Sargeras]] war es [[Ner'zhul]] möglich, weitere Portale zu schaffen und der todgeweihten Welt [[Draenor]] zu entkommen.",},
			["Auge von Paleth"] = { content = "Das '''Auge von Paleth''' ist ein ''Artefakt'' mit großer und schrecklicher Macht, welches zusammen mit der [[Dritte Flotte von Kul Tiras|Dritten Flotte von Kul Tiras]] im [[Sumpfland]] unterging. Es war auf einem der Schiffe der Dritten Flotte, der [[Intrepid]], versteckt und wurde in der Geldkassette des Schiffs verwahrt. Zu dieser hatte nur [[Kapitän Halyndor]] den Schlüssel, der noch immer als Geist auf seinem untergegangenen Schiff herumläuft. Das Auge von Paleth ist eine geschwärzte Kugel, die in einem gruseligen Licht pulsiert und von [[Menschen Priester]]n hergestellt wurde. Der [[Erster Maat Fitzsimmons|Erste Maat Fitzsimmons]] im [[Hafen von Menethil]] ist das einzige Mitglied der Dritten Flotte, das noch atmet, auch wenn er nicht der einzige ist, der noch herumläuft. Denn die unheimliche Macht des Auges von Paleth hält die Seelen der Menschen in den verrottenden Wracks. Um den Fluch zu brechen und alle zu befreien, muss man das Auge von Paleth bergen und reinigen.",},
			["Auge von Sargeras"] = { content = "Viele Monate nach der Schlacht am Berg [[Hyjal]], die zur Niederlage der Brennenden Legion geführt hatte, wurde [[Illidan]] Sturmgrimm von [[Kil'jaeden]] aufgesucht. Der große Dämonenlord trachtete danach, den abtrünnigen [[Lichkönig]] [[Ner'zhul]] für seinen Verrat drakonisch zu bestrafen, und stellte [[Illidan]] unvorstellbare Kräfte in Aussicht. Sollte er [[Ner'zhul]] vernichten, dessen Seele noch im Frostthron gefangen war, würde ihm [[Kil'jaeden]] geben, was immer sein Herz begehrte. Um die elendige Welt von den Feinden seines neuen Meisters zu befreien, benötigte [[Illidan]] das '''Auge von Sargeras''', ein Artefakt ungeheurer dämonischer Energien. Die Erinnerungen des orkischen [[Hexenmeister]]s [[Gul'dan]], die [[Illidan]] geerbt hatte, führten ihn zum Grabmal des dunklen Gottes. Dort fand er das '''Auge von Sargeras''' und ließ das Grabmal über den Köpfen seiner Verfolger einstürzen. Der Wächterin [[Maiev Schattensang]] und ihren [[Behüter]], die geschworen hatten, den Verräter zu jagen, blieb nur die Möglichkeit, den Erzdruiden [[Malfurion]] Sturmgrimm wissen zu lassen, was sein Bruder plante. Doch [[Illidan]] und seine [[Naga]]-Streitkräfte verschanzten sich in den Ruinen der Stadt [[Dalaran]]. Seine Beschwörer begannen, einen mächtigen Zauber durch das Artefakt zu kanalisieren, der den Planeten zu zerreißen drohte. Um [[Ner'zhul]]s Festung in [[Nordend]] zu zerstören, versuchten sie, die polaren Eiskappen des arktischen Kontinents zu schmelzen und das eisige Land zu spalten. [[Illidan]] brachte vorsätzlich zahllose Leben in Gefahr und bedrohte das Gleichgewicht der Welt selbst. Doch [[Malfurion]] und die [[Nachtelfen]], die nicht begriffen hatten, dass der Zauber gegen ihren gemeinsamen Feind gerichtet war, durchkreuzten [[Illidan]]s üblen Plan und zerstörten das '''Auge von Sargeras'''. Nach seinem Scheitern floh [[Illidan]] in die [[Scherbenwelt]], zur verwüsteten Welt [[Draenor]], um an diesem einsamen Ort [[Kil'jaeden]]s Zorn zu entgehen. Trotz allem durchzog ein Riss das Gefängnis des [[Lichkönig]]s und seine Energien begannen durch ihn zu entschwinden.",},
			["Auktionshaus"] = { content = "In [[World of Warcraft]] gibt es vier '''Auktionshäuser''' für Horde: [[Orgrimmar]], [[Unterstadt]], [[Silbermond]] und [[Donnerfels]] und vier für Allianz, die sich in [[Eisenschmiede]], [[Sturmwind]], [[Darnassus]] und der [[Exodar]] befinden. Die Auktionator-[[NSC]]s stehen immer nur jeweils einer Fraktion zur Verfügung, also entweder der Allianz oder der Horde. Die vier Auktionshäuser der Horde und der Allianz sind jeweils untereinander verbunden, so dass dieselben Auktionen in Eisenschmiede und in Darnassus gefunden werden. \r\nEs gibt auch neutrale Auktionshäuser, die zu keiner Fraktion dazugehört. Diese Auktionshäuser befinden sich in [[Gadgetzan]] (Tanaris), [[Ewige Warte]] (Winterquell ) und [[Beutebucht]] (Schlingendorntal). Die Auktionatoren von dieser Auktionshäuer bieten die gleichen Dienste an wie alle anderen Auktionatoren in den Hauptständten, mit der Ausnahme dass dort auch Mitglieder unterschiedlicher Fraktionen an der selben Auktion teilnehmen können. Somit können hier Horde und Allianz miteinander Handeln. \r\nVerkäufer können Gegenstände für eine Auktion anbieten, einen Ausgangspreis und die Dauer der Auktion festlegen, und auf Wunsch auch einen Sofortkaufpreis angeben. Diese Einstellungen werden über den Dialog mit dem NSC-Auktionator vorgenommen. Für jede Auktion muss anfangs eine Kaution hinterlegt werden, die bei einem erfolgreichen Abschluss der Auktion zurückerstattet wird. Für alle erfolgreichen Auktionen muss eine Abschlussgebühr gezahlt werden, die direkt vom erzielten Verkaufspreis abgezogen wird. In Gadgetzan ist diese Gebühr höher als in allen anderen Auktionshäusern. Käufer können eine Liste mit laufenden Auktionen durchstöbern, Gebote abgeben, und Gegenstände mit einem Sofortkaufpreis kaufen. Auch diese Aktionen werden über den NSC-Auktionatordialog abgewickelt. Spieler können nicht für Gegenstände bieten, die von einem anderen Charakter ihres Accounts verkauft werden. Ersteigerte Gegenstände werden per Post an den Käufer verschickt.\r\n===Dauer der Auktion===\r\nJe länger eine Auktion dauern soll, desto höher ist die Kaution. Aus diesem Grund sollten Auktionen so kurz wie möglich sein, da ansonsten der zu hinterlegende Betrag enorm sein kann. Besonders ärgerlich wird das, wenn sich der Gegenstand nicht verkaufen läßt, weil dann die Kaution futsch ist.\r\n===Was sollte versteigert werden?===\r\nWenn es unwahrscheinlich ist, dass ein anderer Spieler einen Gegenstand kaufen will, sollte dieser Gegenstand nicht versteigert werden. Wenn der Gegenstand sich als Ladenhüter entpuppt verliert der Verkäufer seine Kaution. Schlaue Verkäufer schauen sich vorher andere Auktionen an, um einen Überblick über den Marktwert verschiedener Gegenstände zu erhalten.",},
			["Ausgrabungsleiter Darteus Eisenband"] = { content = "'''Ausgrabungsleiter Darteus Eisenband''' leitet die Ausgrabung einiger alter Ruinen östlich des Sees in [[Loch Modan]] bei [[Eisenbands Ausgrabungsstätte]]. Er hat zuletzt wenig Fortschritte gemacht, besonders, wenn man all den Nachschub bedenkt, den die Forscherliga ihm geschickt hat. Eigentlich ist er ein bodenständiger, ehrlicher Zwerg, der gern Resultate sieht, und daher macht man sich in [[Eisenschmiede]] Sorgen, dass da irgendwelche Kräfte gegen ihn arbeiten. Eisenband muss dringend einen Fortschrittsbericht zu Jern Hornhelm nach [[Thelsamar]] schicken - einen Fortschrittsbericht und eine Neufassung seiner Anfrage nach mehr Sprengpulver. Dafür braucht er jemanden, der das für ihn erledigt. \r\nDer Ausgrabungsleiter macht sich auch Sorgen um einen Kollegen, [[Ausgrabungsleiter Agmond]] von [[Hammerzehs Grabungsstätte]] im [[Ödland]]. Agmond hatte die Verantwortung über ihre Ausgrabungsstätten im [[Ödland]], im Südwesten. Aber Eisenband hat schon seit Wochen nichts mehr von ihm gehört. Wenn man Agmonds Schicksal geklärt und seinen Tod gerächt hat, möchte Darteus Eisenband, dass man ihm Bericht erstattet. \r\n==Eisenbands Fortschrittsbericht==\r\nEhrenwerte Kollegen und Wahrheitssucher,\r\ndie Ausgrabungen an dieser Stätte schreiten weiter voran, werden jedoch durch das Auftauchen der bereits in meinem letzten Bericht erwähnten [[Troggs]] behindert. Ich bin zuversichtlich, dass wir mit diesem Problem fertig werden, auch wenn einige dieser Troggs aggressiver sind als gewöhnlich. Es wurden jüngst weitere Artefakte gefunden, aber mit einer Ausnahme (zu der ich später noch Stellung nehmen werde) fallen sie alle in dieselbe Kategorie wie die anderen zuvor: interessant, aber keinesfalls eine Sensation. Eine Ausnahme gab es jedoch. Diese kürzlich entdeckten merkwürdig geschnitzten Götzen (die ich in meinem letzten Bericht bereits einmal kurz beschrieben habe) scheinen eine gewisse Wirkung auf die Troggs an der Ausgrabungsstätte zu haben. Sie werden von den Steinschnitzereien wie magisch angezogen und mancher Trogg ist danach schon Amok gelaufen! Um Rückschlüsse auf diese Götzen ziehen zu können, sind weitere Untersuchungen notwendig, aber ich habe die Hoffnung, dass wir etwas über die Verbindung zwischen Troggs und Titanen erfahren können.\r\nZum Schluss muss ich noch einmal meine Bitte um Sprengpulver wiederholen. Meine Bestände gehen bedrohlich zur Neide und das beeinträchtigt den Erfolg der Ausgrabung nachhaltig. Mir wurde gesagt, eine Ladung Sprengpulver sei auf dem Weg, aber sie ist bislang noch nicht angekommen. Darf ich den Grund für diese Verzögerung erfahren?\r\nHochachtungsvoll\r\nAusgrabungsleiter Darteus Eisenband",},
			["Ausgrabungsleiter Eisenband"] = { content = "#REDIRECT [[Ausgrabungsleiter Darteus Eisenband]]", redirect = "Ausgrabungsleiter Darteus Eisenband",},
			["Ausgrabungsleiter Khazgorm"] = { content = "'''Ausgrabungsleiter Khazgorm''' ist ein [[Zwerg]] der [[Forscherliga]] und leitet die [[Bael Modan Ausgrabung]] im südlichen [[Brachland]]. Er beaufsichtigt die Ausgräber und trägt ein Tagebuch bei sich.\r\n==Khazgorms Tagebuch==\r\n'''Die Ausgrabung bei Bael Modan'''\r\nDie Feldmessergruppe, die ursprünglich von der [[Forscherliga]] geschickt wurde, hatte tatsächlich Recht, was ihre Funde betraf. Der Boden hier ist reich an Artefakten von unschätzbarem Wert für unser Volk. Wir werden zweifellos viele Antworten in unserem Bestreben nach Wissen unter dem Sand und den Felsen Bael Modans finden.\r\nDie geologische Beschaffenheit der Region erfordert jedoch extreme Maßnahmen. Viele der Sandablagerungen haben sich unter den rauen Bedingungen und dem veränderlichen Klima verfestigt. Die Lösung ist jedoch recht einfach. Indem wir Holzbrei als Absorptionsmittel nutzen, können wir Spuren von Nitroglyzerin mit Natriumnitrat kombinieren, um eine kräftige Sprengladung zu erhalten, die sogar dichteste Materie aufbrechen kann.\r\nDie Arbeit wird mit viel Lärm und Unannehmlichkeiten verbunden sein, aber unsere Suche ist wichtiger als der Komfort der hiesigen Einwohner. Wir mussten sogar schon eine Gruppe von Bullenmenschen aus dem Gebiet vertreiben, die langsam lästig wurde. Die Tatsache, dass wir es mit verschiedenen schurkischen Elementen zu tun haben, lässt mich ahnen, dass wir bald Unterstützung durch die Armee des Königs benötigen. Wir werden nicht nur bei den Ausgrabungen militärische Unterstützung benötigen, sondern für mich als Laien scheint der Standort Bael Modan für die [[Allianz]] auch von strategischem Wert zu sein, wenn man die instabile Lage der Weltpolitik zurzeit bedenkt.\r\nWie dem auch sei, ich schweife ab. Unter dem Fels wartet noch viel Arbeit auf uns. Ich habe schon zu viel Zeit mit Schreiberei vergeudet, anstatt zu graben...",},
			["Ausgrabungsleiter Sturmlanze"] = { content = "'''Ausgrabungsleiter Sturmlanze''' ist ein [[Zwerg]] der [[Forscherliga]] und studiert im Moment ihn in der Bibliothek bzw. im Ausgrabungsleiterquartier in der Halle der Forscher in [[Eisenschmiede]]. Sturmlanze gilt als Hitzkopf, ist jedoch ein Meister der Dechiffrierung und Entschlüsselung. \r\nSturmlanze unterstützt [[Ausgrabungsleiter Eisenband]] in [[Loch Modan]] und sorgt für die Sprengstofflieferung zu [[Eisenbands Ausgrabungsstätte]]. Er hat die Bewilligung für den Nachschub bereits mit einem Boten nach [[Thelsamar]] zu [[Jern Hornhelm]] vorausgeschickt. Dieser wird das Pulver und andere Vorräte zum Transport zu Eisenband bereitstellen. Allerdings braucht er jemanden, der dafür Sorge trägt, dass diese Pulverlieferung ihren Bestimmungsort erreicht, denn die letzte kam nicht an. Da er Berichte von Ausgrabungsleiter Eisenband von der Ausgrabungsstätte am Loch Modan erhalten hat, erhalten hat, dass dieser jemanden braucht, der ihm die Rennerei auf einer der anderen Ausgrabungen abnimmt, sucht Sturmlanze desweiteren einen Freiwilligen, der sich ein bisschen die Füße vertreten will und mit Eisenband spricht. \r\nSturmlanze kann auch helfen, einen Brief zu dechiffrieren, der unter Dieben des [[Syndikat]]s im Vorgebirge von [[Alterac]] gefunden wurde. Dieser soll, nachdem der Ausgrabungsleiter das Schriftstück entschlüsselt hat, zu [[Magistrat Henry Maleb]] nach [[Süderstade]] gebracht werden. Denn auch wenn dieser Brief geheimnisvoll klingt, Malebs Stadt liegt Alterac am nächsten, wenn eine Bedrohung sich zusammenbraut, dann sollte gerade er davon erfahren.",},
			["Ausgrabungsleiter Whelgar"] = { content = "'''Ausgrabungsleiter Whelgar''' und sein Archäologenteam von der [[Forscherliga]] halten sich in seiner [[Whelgars Ausgrabungsstätte|Ausgrabungsstätte]] im [[Sumpfland]] auf. Er gelangte dort in den Besitz eines wichtigen Fundstückes, dem [[Goazstein]]. Doch er ist zu alt, um zur Ausgrabung, die von Raptoren überrant wurde, hinunterzugehen und diesen Bestien zu trotzen, um die Funde zu sichern. Nun wünscht er sich, dass jemand die Ausgrabungsstätte nach den 4 fehlenden Tafel-Fragmenten durchkämmt: Ados, Modr, Golm und Neru.",},
			["Ausgrabungsleiter Wirrbart"] = { content = "#REDIRECT [[Wirrbarts Ausgrabungsstätte]]", redirect = "Wirrbarts Ausgrabungsstätte",},
			["Außenposten der Blutschläger"] = { content = "Der '''Außenposten der Blutschläger''' liegt südlich des Speerspießerstamms im Schergrat. Die [[Oger der Blutschläger]] hier sind nicht die stärksten in den Bergen. Da sie nicht in der Gunst des [[Gronn]] namens Gruul der Drachentöter stehen, kommen sie nur an zweiter Stelle.\r\n==Personen==\r\n* '''Gurn Grubnosh'''\r\n* '''Grimnok Schlachttaufe''' - Man findet Grimnok auf dem Südschlägerturm im Außenposten der Blutschläger.",},
			["Außenposten der Forscherliga"] = { content = "Der '''Außenposten der Forscherliga''' liegt nahe von [[Baelguns Ausgrabungsstätte]] an den südöstlichen Klippen des [[Der heulende Fjord|Heulenden Fjords]]. Einer der Kryptografen der [[Forscherliga]], Stanwad nahm ein Team aus zwanzig Wissenschaftlern mit zur Ausgrabungsstätte, doch seitdem hat man nichts mehr von ihm gehört.",},
			["Außenposten der Himmelswache"] = { content = "Der '''Außenposten der Himmelswache''' der Sha'tari liegt hoch oben im [[Schergrat]] und ist nur über die Lüfte zu erreichen. Sie benötigen dringend mehr Reittiere, denn die Missionen und Bombenangriffe auf den [[Landeplatz von Bash'ir]] haben sie so manches Reittier gekostet. Die [[Ätherrochen]] sollten für die Zwecke genügen. Durch das Bändigen dieser Rochen kriegen die Streiter der [[Himmelswache der Sha'tari]] nicht nur frische Reittiere, sondern es hilft ihnen auch noch [[Ogri'la]] zu beschützen. [[Himmelskommandant Keller]] und seine Himmelswache führen zum Schutz diverse Unternehmungen durch und erst kürzlich bat er die [[Oger]], jeden vorbeizuschicken, der Willens ist, sie bei Ihrer Arbeit zu unterstützen.\r\nAlle paar Stunden starten die Äthertechniker vom Außenposten der Himmelswache einen Angriff auf den [[Landeplatz von Bash'ir]]. Sie bestehen darauf, dass sie Bash'irs Kristallschmiede nur 'erforschen', aber egal wie man es dreht, es ist eigentlich nichts anderes, als ein Überfall. Sie benutzen die Kristallschmiede, um die Himmelswache mit neuer Ausrüstung zu versorgen und meistens bleibt noch genug übrig, um einen guten Gewinn herauszuschlagen. Sie beschaffen dort Vorräte für die Himmelswache, wenn sie lange genug dort bleiben können.\r\n==Personen==\r\n* '''Himmelskommandant Keller''' - Himmelskommandant Keller hat den gesamten Posten mit seinen eigenen Händen errichtet. \r\n* '''Himmelsoffizier Vanderlip''' - Himmelsoffizier Vanderlip leitet die Bombardierungen der Munitionslager der Legion. Man sollte sich nicht an ihrem Gebaren stören, denn ihre Zunge ist womöglich schärfer als das Breitschwert, das sie bei sich trägt.\r\n* '''Himmelswache Kathie''' - Himmelswache Kathie möchte, dass man einige [[Ätherrochen]] bändigt.",},
			["Außenposten der Sha'tari"] = { content = "Der kleine Außenposten der [[Sha'tar]]i im Gebiet der [[Wälder von Terokkar]] wird ständig angegriffen. Vor ein paar Nächten haben die Spinnen des [[Netherweberkamm]]s das Lager überfallen und viele der [[Sha'tar]] dort vergiftet, in ihre Netze gewickelt und fort getragen. Einige der Krieger haben zu den Waffen gegriffen und sind den Spinnen todesmutig in die finstere Nacht gefolgt. Sie haben weder die Gefangenen noch die Krieger seit diesem Tag wieder gesehen. Die Soldaten kämpfen auch schon seit Tagen gegen die [[Auchenai]] und ein Ende ist nicht in Sicht, denn jeder Gefallene, ob [[Sha'tar]] oder [[Auchenai]], wird sofort vom Schlachtfeld gezerrt. Ihre Seelen werden geraubt und an unbekannte Orte gebracht. Die Streitkräfte können der immer wachsenden Zahl der [[Auchenai]] nicht mehr Herr werden.",},
			["Außenposten der Silberschwingen"] = { content = "Der '''Außenposten der Silberschwingen''' ist ein Stützpunkt der [[Silberschwingen]] im zentralen [[Eschental]]. Er wird durch [[Schildwache]]n und Krieger stark verteidigt. Ihr Anführer ist [[Duriel Mondfeuer]].\r\n===Kundschafter des Eschentals===\r\nVor nicht langer Zeit verließen einige nachtelfische Kundschafter diesen Außenposten und trieben sich nun in der Nähe der Territorien der [[Horde]] im Wald herum. Doch die [[Horde]] wollte natürlich nicht, dass die Elfen ihre Verteidigung ausspionierten und so begann [[Kuray'bin]] aus dem [[Splitterholzposten]], einen Gegenangriff auf die Kundschafter zu organisieren. \r\n===Toreks Angriff===\r\nDoch es gab noch andere, die einen Angriff auf den Außenposten der Silberschwingen planten. So z.B. auch [[Torek]] und seine orcischen Räuber - die im Auftrag von [[Ertog Zornhauer]] im [[Splitterholzposten]] agierten. Die Nachtelfen hier im Posten waren angemessene Feinde für sie - ein bisschen mager zwar, aber stark und wild. Die Orcs hofften deshalb auf einen ruhmreichen Kampf, wo sich jeder ein paar Narben verdienen konnte.",},
			["Außenposten der Speerspießer"] = { content = "Der '''Außenposten der Speerspießer''' befindet sich im [[Schergrat]] am südwestlichen Rand des [[Messergrat]]s, im Westen vom [[Dorf der Mok'Nathal]]. Schon seit sie denken können haben die [[Mok'Nathal]] gegen die [[Oger der Speerspießer]] gekämpft, doch sie haben es geschafft, die Oger so weit zurück zu drängen, dass sie nun nur noch in einem Außenposten vertreten sind. Diese [[Oger]] haben die Stromwandler von [[Toshlys Station]] gestohlen.",},
			["Aviana"] = { content = "Aviana, der weibliche Rabe, war eine Halbgöttin im [[Krieg der Uralten]] und Patronin der Geheimnisse und Mysterien der wilden Erde.Sie war die Wächterin von Ga'Han, dem Mutterbaum und Herrin aller geflügelter Wesen. Nach deren Tod geleitete sie ihre Kinder in ihr Reich, jedes Wesen, dass den Rausch der Lüfte kannte, konnte nach seinem Tod dort einkehren. Sie wurde während des Krieges von den [[Verdammniswache]]n Archimondes getötet. Auch von den Segnungen der Vogelgöttin beziehen die [[Druiden]] ihre totemartigen Kräfte.\r\nSie zeigte sich oft in Gestalt eines riesigen Falken oder in einer Mischgestalt aus Vogel und Mensch.\r\n'''Quelle''':",},
			["Axtroz"] = { content = "Axtroz ist ein [[Roter Drachenschwarm|Roter Drache]] vor [[Grim Batol]] im [[Sumpfland]]. Er ist der Leutnant und Drachenchampion des [[Roter Drachenschwarm|Roten Drachenschwarms]] und für die Aufgabe: \"[]\" soll man seinen Schädel zu [[Aschenschwinge]] bringen.",},
			["Axt des Brox"] = { content = "Die '''Axt des Brox''' wurde von dem ersten [[Druiden]] der [[Nachtelfen]], [[Malfurion Sturmgrimm]], und dem Halbgott [[Cenarius]] für den [[Orc]] [[Broxigar]] im [[Krieg der Urtume]] geschaffen. Obwohl die Axt ganz aus Holz bestand, durchdrang sie Fleisch und Rüstungen besser als Metall und vermochte es sogar, [[Sargeras]] leicht zu verwunden. Die Axt wurde von [[Krasus]] an [[Thrall]] weitergegeben und befindet sich nun ihm Besitz des [[Kriegshäuptling]]s.",},
			["Axxarien"] = { content = "Die Feste '''Axxarien''' ist das Revier der [[Satyre der Axxarien]] im Nordwesten der [[Blutmythosinsel]].",},
			["Azeroth"] = { content = "'''Fetter Text'''\r\n==Allgemeines==\r\nAuch wenn Azeroth nur einer der zahllosen Planeten im [[Großes Dunkles Jenseits|Großen Dunklen Jenseits]] ist, haben sich hier doch die meisten Ereignisse des Warcraft-Universums abgespielt. Es ist zudem die einzige Welt, die sich je erfolgreich gegen eine Invasion durch die [[Brennende Legion]] wehren konnte, und das, so unwahrscheinlich es auch klingen mag, sogar zwei Mal.\r\n===Bevölkerung===\r\nAzeroth hat eine Vielzahl von Völkern und Rassen hervorgebracht: [[Blutelfen]], [[Zwerge]], [[Gnome]], [[Hochelfen]], [[Menschen]], [[Naga]], [[Nachtelfen]], [[Tauren]] und [[Trolle]]. Außerdem gibt es noch einen ansehnlichen Anteil von [[Orcs]], aber dieses Volk stammt vom Planeten [[Draenor]]. Zudem gibt es noch die [[Untote]]n auf Azeroth; auch wenn man sie selbst bei größzügiger Auslegung des Wortes nicht als \"Volk\" bezeichnen kann. In den letzten Jahren ist ihre Zahl stark angestiegen.\r\n===Geographie===\r\nAzeroth besteht aus mehreren großen, separaten Gebieten. Dies sind hauptsächlich die [[Östliche Königreiche|Östlichen Königreiche]], [[Kalimdor]], [[Nordend]] und die [[Südmeer|Südlichen Meere]]. Zutiefst verwoben mit Azeroth und doch davon getrennt ist der [[Smaragdgrüner Traum|Smaragdgrüne Traum]], der ursprüngliche Bauplan des Planeten, so, wie ihn die [[Titanen]] ursprünglich angelegt hatten. Der Traum ist ein wilder, dichter Urwald: die Welt, die Azeroth ohne die Einwirkung der intelligenten Rassen heute wäre, also ohne Städte, Landwirtschaft, Technologie und [[Krieg]]e.\r\n'''Quelle:''' \r\n==Azeroth das Königreich==\r\nVor dem chaotischen Zeitalter der orcischen Kriege, als das [[Dunkle Portal]] zum ersten Mal geöffnet wurde, galt Azeroth als das mächtigste aller [[Menschen]]völker. Seit mehreren Generationen herrschte Frieden im Königreich, und unter der gerechten Regentschaft von König [[Adamant Wrynn III]] lebten die [[Menschen]] in Wohlstand. Überall im Land war Azeroth als ein Hort des Lichts und der Wahrheit bekannt.\r\n===Die Ankunft der Orkischen Horde===\r\nDoch die Ankunft der Orcischen [[Horde]] markierte den Beginn eines Konfliktes, der das Königreich fast fünfzehn Jahre lang verheeren sollte. Viele Clans hatten ihre Heimatwelt [[Draenor]] verlassen und im Osten, im [[Schwarzer Morast|Schwarzen Morast]], erste Feldlager aufgeschlagen. Nachdem sie Azeroth vorsichtig erkundet hatten, befahlen die gierigen Häuptlinge einen Angriff auf Burg [[Sturmwind]] und rechneten mit einem schnellen Sieg über die schwachen Menschen. Diese überstürzte Handlung führte zu einer schmählichen Niederlage und zwang die [[Orcs]] zum Rückzug in das Sumpfgebiet, in dem sich das [[Dunkle Portal]] befand - nur mit Mühe konnten sie ihre Verfolger im Gewirr der modrigen Pfade abschütteln. Der schmerzlichste Verlust für das Volk von Azeroth war jedoch, dass König [[Adamant Wrynn III]] sein Leben lassen musste, als [[Sturmwind]] von der Orcischen [[Horde]] überfallen wurde. \r\nIm Alter von 20 Jahren wurde Prinz [[Llane Wrynn]] zum König gekrönt und schwor, das Land von diesen grausamen Geschöpfen zu befreien. Er hatte erkannt, dass die [[Orcs]] zwar unglaublich stark und bösartig waren, aber selten wirksame Kampftaktiken anwendeten. Ihre zerstreuten Einzelangriffe waren äußerst unorganisiert. Durch Strategie und List konnten seine Soldaten selbst zahlenmäßig überlegene Marodeure besiegen und die [[Horde]] in Schach halten. Fast zehn Jahre der Überfälle und Raubzüge hatten die Bewohner Azeroths sehr vorsichtig gemacht. Doch als [[Rend Schwarzfaust]] die einst ungeordneten Angriffe der [[Orcs]] führte, hielt König [[Llane]] es für nötig, weitere [[Soldat]]en und Bogenschützen zum Schutz des Grenzgebietes auszusenden. Mit [[Rend Schwarzfaust]]s Aufstieg zum Kriegsherrn der [[Horde]] und dem Kampf für die Verteidigung des Königreiches brachen die dunklen Tage des Ersten Krieges an.\r\n===Der Erste Krieg und seine Folgen===\r\nDie Kriegswirren sollten Azeroth fast fünf Jahre lang verwüsten und die reichen Ländereien als tote Erde zurücklassen. Diesmal hatte [[Llane]] die erbarmungslosen Klans unterschätzt - sie richteten schreckliche Massaker an und erschlugen jeden, der ihnen in die Hände fiel. Die [[Orcs]] machten keinen Unterschied zwischen Soldaten und Kindern, Kriegern und Frauen. Das stolze Königreich und seine Verteidiger wurden in die Knie gezwungen. Als König [[Llane]] heimtückisch ermordet wurde, nahm sich Sir [[Anduin Lothar]] der geschlagenen Armeen von Azeroth an und schart seine Landsleute um sich. Der tapfere Ritter führte die Überlebenden aus ihrem verwüsteten Heimatland bis an die Gestade [[Lordaeron]]s. König [[Terenas]], der Herrscher dieses Landes, zeigte sich bereit, die Heimatlosen zu unterstützen. Die Flüchtlinge siedelte daraufhin an der Südküste von [[Lordaeron]] und beschworen ihre Bündnistreue zur [[Allianz]]. In Anerkennung seiner Verdienste wurde [[Anduin Lothar]] der Titel Lordregent von Azeroth verliehen. Er gelobte, seine gefallenen Mitstreiter zu rächen und das Königreich aus den Klauen der Orcischen [[Horde]] zu befreien. Mutig und kampfgestählt sinnten die letzen der großen Armeen nun auf Vergeltung für den Verlust ihrer Heimat.\r\n===Das Ende der orkischen Besatzung===\r\nNur sechs Jahre später begannen die Klans mit einer Großoffensive an den Küsten [[Lordaeron]]s. Auch an der Nordgrenze [[Khaz Modan]]s konnten die Streitkräfte der [[Allianz]] einen Vormarsch der [[Orcs]] nicht lange aufhalten. Viele der wichtigsten Provinzen wurden völlig zerstört und eine erneute Niederlager der [[Menschen]] schien schon fast sicher. Lediglich die kleingeistigen Rivalitäten und Kämpfe innerhalb der [[Horde]] zwangen die [[Orcs]] wieder zum Rückzug. Lord [[Anduin Lothar]] begriff schnell, das Unstimmigkeiten die Klans entzweiten und scharte seine letzten Truppen um sich. Die Armeen der [[Allianz]] drängten die [[Orcs]] nach Süden, zurück ins verwüstete Land Azeroth. Das Königreich, das ihrem gnadenlosen Ansturm als erstes zum Opfer gefallen war, war nun die letzte Bastion der orkischen Macht. Zwar fiel Lord Lothar am Fuße des [[Schwarzfels]]es im Kampf, doch seine getreuen Mitstreiter [[Turalyon]] und [[Uther Lichtbringer]] führte die Kräfte der [[Allianz]] zu einem erbitterten Gegenangriff. In einer ruhmreichen, aber schrecklichen Schlacht schlugen ihre Streitkräfte das Gross der Orkischen [[Horde]]. Es gelang dem [[Erzmagier]] [[Khadgar]], das [[Dunkle Portal]] zu zerstören und die [[Orcs]] damit von Verstärkung aus [[Draenor]] abgeschneiden. Die verstreuten Stämme wurden innerhalb weniger Monate zusammengetrieben und in [[Internierungslager]] gesperrt.\r\n===Die letzte Bastion der Menschheit===\r\nKaum waren die lodernden Feuer des Zweiten Krieges erloschen, erlebte Azeroth eine neuerliche Blüte. [[Terenas]] hatte die Führer der [[Allianz]] dazu gebracht, Geld und Arbeitskräfte für den Wiederaufbau der Stadt [[Sturmwind]] bereitzustellen. Der junge, dynamische [[Varian Wrynn]] bestieg den Thron von Azeroth und konnte durch seine weitblickende Herrschaft das Königreich wieder als militärische Großmacht etablieren. In den folgenden Jahren begann unter den Nationen der [[Allianz]] ein kleinmütiger Zank und Streit, der das große Bündnis langsam zerrüttete. Die [[Hochelfen]] sowie das Volk von [[Stromgarde]] und [[Gilneas]] entzogen König [[Terenas]] ihre Unterstützung. [[Varian Wrynn]] erkannte jedoch, dass sein Königreich für immer in der Schuld der [[Allianz]] stehen würde, und blieb dem Bündnis treu ergeben. Seit der Invasion der [[Brennende Legion|Brennenden Legion]], die [[Lordaeron]] in Schutt und Asche legte, ist Azeroth die letzte Bastion menschlicher Zivilisation. Den heldenhaften Beispielen des legendären Lord [[Anduin Lothar]] und König [[Llane Wrynn]] folgend, werden die Verteidiger des Königreiches zu den am erbittertsten kämpfenden Kriegern im Land gezählt. Resolut walten sie ihres Amtes, die Ehre und die Macht der Menschheit in einer immer dunkler werdenden Welt zu erhalten.",},
			["Azgalor"] = { content = "'''Azgalor''' ist ein gewaltiger [[Grubenlord]] im [[Hyjalgipfel]].\r\n==Kampf==\r\n* '''Geheul des Azgalor''' - Das Geheul des Azgalor bringt in der Nähe befindliche Feinde 5 Sekunden lang zum Schweigen. \r\n* '''Spalten''' - Spalten fügt einem Feind und seinen nächsten Verbündeten Waffenschaden plus 1750 zu und stößt sie zurück. Wirkt auf bis zu 5 Ziele. \r\n* '''Verdammnis''' - Verdammnis verflucht ein Ziel, sodass es nach 20 Sekunden stirbt und eine geringe [[Teufelswache]] an seine Stelle tritt.",},
			["Azjol-Nerub"] = { content = "Die [[Neruber]], ein Volk humanoider Spinnen, gründeten vor ewigen Zeiten in [[Nordend]] das schattenhafte Reich '''Azjol-Nerub'''. Sein unterirdisches Netzwerk von Tempeln und Tunneln erstreckte sich fast über die Hälfte des gesamten arktischen Kontinents. Als der Einfluss des [[Lichkönig]]s in [[Nordend]] weiter zunahm, stellten sich die Spinnenlords der [[Neruber]] gegen seine irren Machtbestrebungen. Ihre unermesslichen Streitkräfte griffen immer wieder [[Ner'zhul]]s Festungen an. Mit Unterstützung der [[Schreckenslord]]s und seiner zahllosen untoten Krieger fiel der [[Lichkönig]] aber schließlich in Azjol-Nerub ein und ließ die unterirdischen Tempel über den Köpfen der Spinnenlords einstürzen. Das dunkle Imperium der [[Neruber]] war zerstört, und [[Ner'zhul]] jagte sie in die Eiswüsten [[Nordend]]s hinaus. \r\n==Teilbereiche==\r\n* [[Azjol-Nerub: Ahn'kahet]] - Die [[Naga]] haben die [[Neruber]] aus den Ruinen vertrieben und sich selbst im alten Reich [[Ahn'kahet]] eingenistet.\r\n* [[Azjol-Nerub: Unteres Viertel]] \r\n==Kreaturen==\r\n* '''Gesichtslose''' - Nicht nur die [[Untote]]n stellen hier eine Gefahr dar: Ein neuer, bisher unbekannter Schrecken streift durch die uralten Gänge: die [[Gesichtslose]]n. \r\n* '''Neruber''' - Es gibt nur noch wenige Enklaven, in denen Nerubenkrieger leben, aber sie trachten noch immer nach Rache. Diese nerubischen Rebellen haben ihren Kampf gegen die [[Geißel]] immer noch nicht aufgegeben und nehmen jede Hilfe dankbar an.\r\n* '''Zwerge''' - Es gibt auch andere Verbündete in Azjol-Nerub, z.B. die Zwerge, welche König [[Muradin Bronzebart]] bei seiner Expedition begleiteten. Sie halten ein kleines Lager am einzigen bekannten Zugang zu Azjol-Nerub und haben sich geschworen, keinen [[Gesichtslose]]n jemals das Tageslicht erblicken zu lassen. \r\n==5er-Instanz==\r\nDas mächtige Spinnenreich der Neruber, Azjol-Nerub, war einst eine Metropole des Wissens. Doch im [[Krieg der Spinne]] gegen den [[Lichkönig]], bezwang dieser das stolze Volk und unterwarf es. Wer ins Innere der Spinnenstadt will, muss nun erst an [[Krik'thir]] dem Torwächter vorbei. \r\n===Bosse===\r\n* [[Anub'arak]]\r\n* [[Hadronox]] (Brut von [[Maexxna]])\r\n* [[Krik'thir]]",},
			["Azrethoc"] = { content = "Lord Azrethoc ist eine Verdammniswache in Desolace, der versucht, Einfluss über die Brennende Klinge zu bekommen, um seine Ziele voranzutreiben.",},
			["Azshara"] = { content = "'''Azshara''' war einst ein wunderschöner Landstrich, den die [[Nachtelfen]] ihr Zuhause nannten. Die hochheiligen Länder sind nach der nachtelfischen [[Königin Azshara]] benannt und wurden einst von [[Cenarius]] bereist. \r\nDas war damals, als sie noch Magie praktizierten, jetzt ist es dort eher gefährlich als schön. Doch man wäre überrascht darüber, wie viele wertvolle Gegenstände hier einfach so herumliegen. Es ist der Traum eines jeden Arkanen-Schülers.\r\n==WoW: Cataclysm==\r\nIn ''[[WoW: Cataclysm]]'' wurde Azshara grundlegend verändert. Die [[Hydraxianer]] verlassen das Gebiet. [[Azuregos]] wird vermisst und niemand scheint zu wissen, wohin er geflogen ist. Es gibt jedoch Gerüchte über jemanden im [[Bilgewasserhafen]], der jede Information über den Verbleib des Drachen großzügig entlohnt. [[Erzmagier Xylem]]s Turm steht noch, doch Xylem scheint etwas über den Weg gelaufen zu sein, dass ihn in kurzer Zeit in den Wahnsinn getrieben hat. Während unbeholfene Entdecker weiterhin von den ansässigen Riesen verspeist werden, haben die Goblins eine Methode entwickelt, die solche unglücklichen Umstände praktisch machen und – natürlich – profitabel.\r\n==='''Aufstieg des Bilgewasserkartells'''===\r\nSo wird Azshara zu einer Hochburg der [[Goblins]] und Schauplatz des Aufstiegs des [[Bilgewasserkartell]]s mit seiner Hauptstadt, dem ''[[Bilgewasserhafen]]''. Nachdem er gerade den Posten des Kriegshäuptlings übernommen hat, bereitet [[Garrosh Höllschrei]] einen Krieg vor, um das gesamte Kalimdor für die Horde zu beanspruchen. Die Goblins des Bilgewasserkartells tragen ihren Teil dazu bei, indem sie Kriegsmaschinen bauen, Waffen entwickeln und einen gewaltigen Überseehafen in Sichtweite von Orgrimmar errichten.\r\n===Nachtelfen===\r\nDerweil wollen die Nachtelfen dem nicht untätig zuschauen, sondern sind fest entschlossen, gegen diese unerwünschte Besetzung Azsharas anzugehen und einen Konflikt möglichst zu verhindern, der sich sonst tief in ihre Wälder erstrecken könnte.\r\n===Terraforming===\r\nMitten in all diesen Spannungen ist das Bilgewasserkartell zudem dabei, sich nach bester Goblinart einen Namen zu machen. Wie zeigt man am besten Solidarität? Indem man die [[Bucht der Stürme]] in eine gigantisches Hordensymbol umbaut! Von da aus sind ein geheimes Labor, eine ausgedehnte Raketenbahn und ein „Lustschloss“ mit eigenem Golfplatz logische Schritte für Goblins. Ob es darum geht, das Terrain für Hordenpropaganda umzumodeln oder einen ganzen Berg umzusetzen, um an die Mineralien darunter zu gelangen, oder auch das Gesicht des Handelsprinzen in einen nahegelegenen Felsen zu meißeln – es gibt keinen Zweifel, wer jetzt das Sagen in Azshara hat. \r\n==Wissenswertes (OOC)==\r\n Rocky Balboa\r\n Willkommen im Rocky Balboa Land. Rocky I war 1976 nicht nur ein Film, der drei Oscars gewonnen hat, sondern auch Vorlage für unzählige Szenen in Filmen und Spielen. In WoW gibt es bereits eine Menge Rambo-Referenzen, der Felselementar (Rock) Balboa in Azshara ist jedoch das erste Easter Egg von dem Boxer Rocky Balboa.",},
			["Azshir der Schlaflose"] = { content = "'''Azshir der Schlaflose''' ist ein seltener ruheloser [[Geist]] auf dem Friedhof des [[Scharlachrotes Kloster|Scharlachroten Klosters]]. Er leidet an chronischer Schlaflosigkeit, aber ist sonst ein ziemlich netter Zeitgenosse.",},
			["Azuregos' magisches Buch"] = { content = "'''Azuregos' magisches Buch''' wird von [[Azuregos]] den Helden zur Verfügung gestellt, die das [[Szepter der Sandstürme]] wieder zusammensetzen wollen. Jedoch ist dieses Buch für normale Sterbliche nicht lesbar, denn sie können kein einziges Wort verstehen. Sie wissen nicht einmal in welcher Sprache es geschrieben wurde. Doch [[Narain Pfauentraum]] in [[Tanaris]], in einem Haus nördlich vom [[Dampfdruckpier]], könnte es vielleicht mit Hilfe des Buches: \"[[Drachisch für Dummies]]: Band 2\" übersetzen. Leider zerstörte [[Doktor Weavil]] das Original dieses Buches und die einzig bekannte Kopie wurde in 8 Teile zerrissen und im Wind zerstreut. Die Übersetzung dieses Buch wird benötigt, um das Geheimnis zu enthüllen, wie man an den Blauen Szeptersplitter gelangen kann.",},
			["Azuregos"] = { content = "Vor der Spaltung der Welt blühte die elfische Stadt Eldarath in den Landen, die nunmehr [[Azshara]] genannt werden. Manche sagen, dass unter den Ruinen der Stadt immer noch zahllose Artefakte der [[Hochgeborene]]n schlummern, denn seit ungezählten Generationen wacht der [[Blauer Drachenschwarm|blaue Drachenschwarm]] über mächtige Artefakte und magisches Wissen, damit nichts davon in die falschen Hände fällt. Die Anwesenheit von Azuregos, dem blauen Drachen, scheint darauf hinzuweisen, dass in der Wildnis von [[Azshara]] extrem seltene Gegenstände schlummern, vielleicht sogar die [[Phiolen der Ewigkeit]]. Doch egal was der Drache sucht, eins ist sicher – er wird bis zum Letzten kämpfen, um diese Schätze zu verteidigen. \r\n==Schätze==\r\n* [[Azuregos' magisches Buch]]",},
			["Azurmythosinsel"] = { content = "== Allgemeines==\r\nDie Azurmythosinsel liegt im Norden von [[Kalimdor]] etwas unterhalb von [[Teldrassil]].\r\nSchon aus vielen Meilen Entfernung kann man die prächtige [[Exodar]] an der Seite eines Berges erkennen. Auf der Flucht vor der [[Brennende Legion|Brennenden Legion]] ist dieses Raumschiff der [[Draenei]] über [[Azeroth]] abgestürzt und in viele Trümmer zerbrochen. Viele ließen dabei ihr Leben. Eines der Anliegen der [[Draenei]] auf der Azurmythosinsel beschäftigt sich nun mit dem Knüpfen eines Bandes mit der [[Allianz]] und den [[Furbolgs der Tannenruhfeste]]. Aber es scheint, dass die [[Draenei]] nicht die einzigen sind, die sich auf diesen Inseln aufhalten: denn die [[Blutelfen]] sind ihnen hierher gefolgt. \r\n===Fauna===\r\nAls das Schiff abstürzte, wurde die Menagerie an den nordöstlichen Stränden dieser Insel zerstreut. Im Körper verschiedener Tiere, vor allem von Nachtpirschern hat man nun Kristalle gefunden, die ein Teil der [[Exodar]] waren und nun ungewöhnliches Aufkommen und Verhalten einiger Tiere dieser Gegend verursachen. Es wurde auch von zertrümmerten Kristallfragmenten im östlich gelegenen Fluss berichtet, aber die [[Draenei]] hatten beschlossen, diese Implikationen zu ignorieren. Sie können jetzt also entweder auf dieser Insel herumsitzen und diese Tragödie beweinen, oder etwas tun, um eine Ausbreitung zu vermeiden.\r\n==Merkmale==\r\n* [[Absturzstelle]]\r\n* [[Am'mental]]\r\n* [[Azurwacht]]\r\n* [[Nistelhügel]]\r\n* [[Odesyus' Ankerplatz]] \r\n* [[Schattenkamm]]\r\n* [[Silbermythosinsel]]\r\n* [[Silberwellensee]]\r\n* [[Tannenruhfeste]]\r\n===Anlegestelle===\r\nDie Docks liegen westlich der [[Exodar]] und sind Landestelle eines Schiffes aus [[Auberdine]] von der [[Dunkelküste]]. \r\n===Geezles Lager===\r\nAn der Küste im Südosten findet man in Geezles Lager bei den Zelten die gestohlene nautische Karte von [[Admiral Odesyus]]. Der Kompass liegt auf einer Kiste nahe an der Tempelruine. \r\n===Glutgrund===\r\nIm Nordosten entlang der Küste gibt es einen heiligen Ort des Feuers, den Glutgrund. Inmitten der verbrannten Bäume wacht [[Glutos]], ein besonders mächtiger und weiser [[Feuerelementar]]. Einer seiner Brüder, [[Hauteur]], ist verrückt geworden. Zweifellos ist der Absturz der [[Exodar]] daran schuld. Er verlangt jetzt, dass ihn die heimischen [[Eulenbestien]] verehren, doch keiner von ihnen würde jemals einen Gott verkörpern.\r\n===Kristallfluss===\r\nMan hat festgestellt, dass es in diesen Gewässern von [[Schnapper]]n nur so wimmelt. Das ist ein sehr leckerer Fisch. Mit einem Fischernetz kann man genug fangen, um dutzende von Draenei satt zu bekommen. [[Diktynna]] wurde erst kürzlich von einer Kreatur angegriffen, die man [[Murloc]] nennt, als sie im Fluss fischte. Sie wurde dabei verletzt und kann deshalb ihre Arbeit nicht mehr verrichten. \r\n===Nachtelfenruinen===\r\nDie Ruinen im Westen sind die Überreste einer [[Nachtelfen]]kultur. Darin befinden sich uralte [[Nachtelfen]]relikte.\r\n===Wildwindgipfel===\r\nDen Wildwindgipfel erreicht man über den Wildwindpfad im Norden. Es ist dem Berg zugewandt, an dem die [[Exodar]] zerschellt ist. Auf seinem Gipfel wird man eine Höhle finden. Am nördlichen Ende der Felsklippe erwartet [[Susurrus]] wissenshungrige junge Schamanen.",},
			["Azurous"] = { content = "'''Azurous''' ist ein seltener [[Blauer Drachenschwarm|Blauer Großdrache]] in [[Mazthoril]] in [[Winterquell]]. Seine einzige Fähigkeit ist der für Blaue Drachen typische ''Frostatem'', der Feinden in einem kegelförmigen Bereich vor dem Zaubernden Frostschaden zufügt, ihnen Mana stiehlt und ihr Bewegungstempo 10 Sek. lang verlangsamt.",},
			["Azurschachtmine"] = { content = "Der Azurschacht im Vorgebirge des Hügellands steht unter der Kontrolle der [[Allianz]] und ist eine erstklassige Quelle für Eisenerz für die Waffenkammern der [[Allianz]]. Auch wenn die [[Verlassene]]n dem [[Hügellandhof]] einen entscheidenden Schlag versetzen konnten, unterstützt und beschützt die [[Allianz]] den Azurschacht immer noch aufs Äußerste. Die Mine liegt genau im Süden der Stadt Hügellandhof. Bei der letzten Lieferung aus dem Schacht war eine Kiste mit seltenen Kristallen dabei, die man sehr gerne untersucht hätte. Plünderer der [[Verlassene]]n aber haben den Wagen abgefangen und ihn nach Nordosten zu einem Turm gebracht, den sie wiederaufbauen wollen. Geleitet wird die Mine von [[Großknecht Bonds]]. [[Minenarbeiter Hackett]] befindet sich innerhalb der Mine in der großen Höhle am Nordostrand der Mine und wird wegen Mordes an [[Todespirscher Fry]] gesucht.",},
			["Azurwacht"] = { content = "Die Azurwacht ist ein [[Draenei]]-Stützpunkt der [[Allianz]] auf der [[Azurmythosinsel]]. Es gibt einen Pfad, der westlich vom [[Am'mental]] über den Kristallfluss führt. Wenn man ihm folgt, gelangt man auf den größeren Teil der Insel und zur Azurwacht. \r\n[[Anachoret Fateema]] hat herausgefunden, dass die Ranken der Pflanzenkreaturen, den sogenannten [[Peitscher]]n, auf dieser Insel eine regenerierende Eigenschaft besitzen und wenn man die [[Lauerwurzranke]]n richtig verarbeitet, kann man aus ihnen eine hochwirksame Heilsalbe herstellen. Durch die vielen verletzten [[Draenei]], die ständig in der Azurwacht eintreffen, sind die Vorräte an Heilmitteln beinahe erschöpft und es besteht eine \"Medizinische Notwendigkeit\"\r\nan Nachschub. Nun wurde auch noch eine [[Nachtelfe]] schwer verletzt und bewusstlos am Kristallfluss gefunden und [[Anachoret]] Fateema kann sie möglicherweise retten, wenn man ihr die Wurzeln bringt. \r\nDie [[Lauerwurzranke]]n heilen die Verletzten nicht so wie gedacht und der Zustand des [[Nachtelfe]]nmädchens ist bereits zu kritisch, als dass einfache Salben sie noch retten könnten. Aber [[Daedal]] weiß möglicherweise noch einen anderen Weg... Der Wald der Insel birgt viele Geheimnisse, eines davon ist eine seltene Pflanze, das [[Azurlöwenmäulchen]], die viele als Allheilmittel ansehen. Vielleicht kann sie helfen.\r\n==Personen==\r\n* [[Acteon]]\r\n* [[Anachoret Fateema]] \r\n* [[Daedal]]\r\n* [[Dulvi]]\r\n* [[Exarch Menelaous]]\r\n* [[Kryptograph Auren]]",},
			["Azzinoth"] = { content = "'''Azzinoth''' war eine [[Verdammniswache]], die im [[Krieg der Urtume]] als Luftkommandant kämpfte. Doch sie begegnete dem großen Dämonenjäger [[Illidan]] und das besiegelte ihr Ende. Illidan machte kurzen Prozess mit Azzinoth und nahm die verderbten Klingen des [[Dämon]]s. Er schmiedete sie um und machte die Dämonenwaffen zu seinen Waffen, die fortan als [[Zwillingsgleven von Azzinoth]] bekannt waren. Auch andere Artefakte fertigte [[Illidan]] aus Azzinoths Rüstteilen an, die er samt und sonders mit in sein Hügelgefängnis mitnahm (unter strenger Bewachung der misstrauischen [[Nachtelfen]]).",},
			["Babykrokolisk"] = { content = "Die großen Augen und das niedliche Gesicht werden dieses Pet sicher zu einem Renner unter den Haustier-Sammlern machen. Allerdings solltet Ihr Euren Angelsskill dafür ein wenig trainieren, denn die Eimer können wohl nur aus dem Wasser gezogen werden. \r\n==Arten==\r\n* Knurris Eimer\r\n* Matschbrabbels Eimer\r\n* Schnapps Eimer\r\n* Zähnchens Eimer\r\n'''Quelle:'''",},
			["Bach'lor"] = { content = "#REDIRECT [[Talbuk]]", redirect = "Talbuk",},
			["Bael'Gar"] = { content = "Bael'Gar ist ein [[Geschmolzener Riese]], der in den Schwarzfelstiefen haust.Er ist ein Wesen aus reinstem Feuer, geboren aus den Flammen des [[Ragnaros]].",},
			["Baelguns Ausgrabungsstätte"] = { content = "'''Baelguns Ausgrabungsstätte''' liegt unterhalb der südöstlichen Klippen des [[Der heulende Fjord|Heulenden Fjords]] und war eine große Hoffnung der [[Forscherliga]]. Doch als die Ausgrabungen begann fanden die Zwerge hier vor allem Ärger am hohen Kliff. Denn die [[Eisenzwerge]] sind überall wie Pilze aus dem Boden geschossen und versuchen nun die Ausgrabungsstätten zuzuschütten. Sie wollen die Funde unter einem Haufen Erde begraben. Wann die Zwerge der Forscherliga jemals wieder in die Nähe der Ausgrabung kommen, ist ungewiß.",},
			["Bael Modan"] = { content = "'''Bael Modan''' ist eine Ausgrabungsstätte der [[Zwerge]] im südlichen [[Brachland]]. Die [[Tauren]] des [[Brachland]]es meinen, die [[Zwerge]] von Bael Modan haben keinen Respekt vor dem Land, denn entsetzliche Schläge reißen tiefe Wunden in den Boden und brüllende Maschinen zerfetzen die Hügel. Land, das den [[Tauren]] einst als Heimat und Versorger diente, ist jetzt von zerstörerischen [[Zwerge]]n durchfurcht. Alle Versuche, zu einer diplomatischen Einigung zu kommen, sind fehlgeschlagen. Ihr zwergischer Flugapparat ist nicht nur ein wichtiger Bestandteil der Infrastruktur der Grabungsstätte, sondern auch eine Kriegswaffe. Vor allem ist sie aber ein Symbol der Macht und eine Beleidigung des Andenkens an die [[Tauren]]stämme.\r\n==Schätze==\r\n* [[Träne der Monde]]\r\n==Persönlichkeiten==\r\n* [[Ausgrabungsleiter Khazgorm]]\r\n'''Sonstige'''\r\n* '''Captain Gerogg Hammerzeh''' - Gerogg Hammerzeh ist der Captain der Wache.\r\n* '''Feegly der Verbannte''' - Feegly hatte die Macht der [[Träne der Monde]] in diesen seinen Händen und er möchte sie wiederhaben.\r\n* '''General Doppelzopf''' - General Doppelzopf war eifersüchtig auf die Macht, die die [[Träne der Monde]] Feegly verlieh. Er sperrte sie weg, in der Burg in seine Geldkassette und sagte, sie sei verflucht.\r\n* '''Heggin Steinbart''' - Heggin Steinbart ist Bael’duns Chefingenieur\r\n* '''Lord Cyrik Schwarzschmied'''.\r\n* '''Malgin Gerstenbräu''' - Malgin Gerstenbräu ist Bael’duns Vertrauensoffizier.\r\n===Gann Steinkeil===\r\nDer Taure Gann Steinkeil wandert in Einsamkeit auf den Straßen des südlichen Brachlandes. Er möchte, dass man die Ausgräber und Großknechte von Bael'dun tötet und ihm dann [[Ausgrabungsleiter Khazgorm]]s Tagebuch bringt. Denn er denkt, dass jetzt die Zeit für entschlossenes Handeln gekommen ist. \r\nEs ist ihm klar, dass ein Ausgrabungsleiter von Sprengstoff und diesen lärmenden Fahrzeugen abhängig ist, um den Boden aufzureißen und er muss damit rechnen, dass auch nachdem er [[Ausgrabungsleiter Khazgorm]] töten ließ, schon bald ein neuer Großknecht die Sache übernimmt.\r\nEr plant, die Zwerge mit Gewalt von der Bael Modan-Ausgrabung vertreiben und braucht dafür Nitroglyzerin, Holzbrei und Natriumnitrat. Laut [[Ausgrabungsleiter Khazgorm]]s Tagebuch erhält man daraus eine Sprengladung, mit der er die Ausgrabung sabotieren kann und es ist bekannt, dass die [[Zwergen Scharfschütze]]n, Soldaten und Offiziere in der Burg diese Dinge besitzen. Er möchte den [[Zwerge]]n ihre eigene Medizin zu schmecken geben, denn er wird daraus eine Sprengladung basteln, die die Zwerge so schnell nicht vergessen werden. Und sein Ziel wird der Flugapparat bei Beal Modan sein.",},
			["Baine Bluthuf"] = { content = "'''Baine Bluthuf''' ist der Sohn des großen Häuptlings der [[Tauren]], [[Cairne Bluthuf]]. Cairne hat seinen Sohn immer geliebt wie sich selbst und immer versucht, ihn von Gefahren fernzuhalten, darum war Baine nicht der stärkste Taure und bei einem Angriff der Zentauren wurde der junge Taure gekidnappt. Zu seinem Glück erschienen [[Rexxar]] und [[Rokhan]], die Botschafter der [[Horde]] und retteten den Jungen mit der Hilfe einiger [[Schamane]]n. Seitdem bewundert Baine Rexxar um seine Kraft und Rokhan um seine List und möchte so werden wie sie.Seitdem ist aus dem jungen Tauren ein großer [[Jäger]] zu Ehren der Stämme geworden und viele glauben, dass er eines schicksalhaften Tages die Nachfolge seines Vaters antritt.\r\nDerzeit führt Baine die [[Tauren der Bluthufe]] an und lebt im [[Dorf der Bluthufe]] in [[Mulgore]]. Er hofft, dass andere nicht so viel wie er ertragen müssen, denn es gibt viele Dinge, um die er sich sorgt. Ebenso führt er die heranwachsenden Tauren in den [[Riten der Erdenmutter]] voran.",},
			["Balnazzar"] = { content = "Balnazzar ist ein mächtiger [[Schreckenslord]] und der oberste Kreuzzügler des [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzugs]]. Und er ist nicht nur irgendein [[Dämon]], sondern der Bruder von [[Varimathras]], dem Erzlord der [[Unterstadt]]. Die Mitglieder des [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzugs]] befinden sich unter seiner Kontrolle und dienten unwissentlich als Bauern für ein größeres Übel. Er befindet sich als Endboss der Scharlachroten Bastion in [[Stratholme]].",},
			["Balnirs Bauernhof"] = { content = "Balnirs Bauernhof in [[Tirisfal]] hat sich zu einem Zufluchtsort für eindringende [[Untote]] entwickelt. Doch auch der [[Scharlachroter Kreuzzug|Scharlachrote Kreuzzug]] gewinnt dort an Stärke, denn die Kreuzzügler haben ihre Überfälle von dem verfallenen Turm im südöstlichen [[Tirisfal]], nahe Balnirs Bauernhof, unter dem Kommando von [[Hauptmann Vachon]] ausgeführt.",},
			["Balzaphon"] = { content = "[[Balzaphon]] ist ein [[Lich]] in [[Stratholme]], der während der [[Invasion der Geißel]] dort auftaucht.",},
			["Bananas"] = { content = "'''Bananas''' ist ein kleiner Babygorilla, den man durch eine Beutekarte aus dem [[World of Warcraft TCG]] erhalten kann. Die Karte heißt \"King Mukla\", ist also im Spiel sonst nicht zu bekommen.",},
			["Bank"] = { content = "Jeder Held braucht einen Ort, an dem er all seine Schätze und Trophäen horten kann. In World of Warcraft kann jeder Spieler seine Gegenstände auf der Bank so lange einmotten, bis er sie gebrauchen kann. Die Bank kann alle möglichen Gegenstände aufnehmen: Questgegenstände, Waffen, Rüstungen, Handwerksgegenstände, Dinge die der Spieler später vielleicht verkaufen will, und noch vieles mehr. Die sechs Städte verfügen alle über ihre eigene Bank, doch es gibt auch außerhalb der Städte an ein paar entlegenen Orten Banken, auf die reisende Abenteurer zurückgreifen können. Die meisten Dörfer und Außenposten haben allerdings keine eigene Bank.\r\nDie Banken sind eigentlich sehr zentral gelegen und nicht schwer zu finden, aber trotzdem brauchen manche Spieler vor allem anfangs eine Weile, bis sie die Bank gefunden haben. In so einem Fall findet sich meistens immer irgendein Spieler, der gerne weiterhilft. Die Banken haben in der Regel ein großes Schild in Form eines Stapels Münzen vor der Tür, an dem man sie erkennen kann. In der Bank warten Banker auf Kundschaft, erkennbar an der Bezeichnung <Banker> in ihrem Namen.\r\nDie Bank verkauft zusätzlich zu den normalen Plätzen auch solche Plätze, auf denen ganze Taschen samt Inhalt gelagert werden können. Größere Taschen eignen sich deutlich besser zum Einlagern von Gegenständen. Ein Taschenplatz in der Bank kann mit einer 6er Tasche belegt werden, doch sobald eine größere Tasche (zum Beispiel eine 10er Tasche) verfügbar ist, sollte sie auch eingesetzt werden. Weitere Taschenplätze in der Bank kosten mehr, und die letzten Plätze sind äußerst teuer.\r\nZusatzinformationen\r\nDas Bankdepot ist geschützt, so dass wirklich nur der Inhaber zugriff darauf hat. Spieler können sich kein Depot teilen. Jeder Charakter eines Spielers hat sein eigenes Depot, das er nicht mit anderen Charakteren teilen kann.\r\nDie Bank lagert kein Geld ein, da Spieler immer all ihr Geld bei sich tragen. Da Geld weder etwas wiegt noch Platz im Inventar wegnimmt gibt es keinen Vernünftigen Grund, warum man sein Geld auf die Bank bringen sollte. Es gibt ja noch nicht einmal Zinsen! Banken sind Fraktionsspezifisch, das heißt dass Spieler auf Seiten der Allianz nur auf Banken der Allianz und Spieler auf Seiten der Horde nur auf Banken der Horde zugreifen können.\r\nDank eines fortschrittlichen Netzwerks miteinander verbundener Automatischer Teleportationsmaschinen ([[ATM]]s) können Bankkunden von jeder beliebigen Bank auf ihr persönliches Depot zugreifen. Man muss sich also keine Sorgen darum machen, in welcher Bank man welche Gegenstände liegen hat – es ist immer dasselbe Depot. Solange der Bankdialog geöffnet ist, können Gegenstände nicht versehentlich fallengelassen und zerstört werden. Die Angestellten stehen Kunden der Bank bei ihren Geschäften immer mit einem Lächeln (oder einem Zischen, Knurren, oder Fauchen, je nachdem auf wessen Seite man ist) zur Seite.",},
			["Bannzauberer"] = { content = "#REDIRECT [[Blutelfen-Hexenmeister]]", redirect = "Blutelfen-Hexenmeister",},
			["Banshee"] = { content = "Banshees waren einst wunderschöne [[Elfen]]frauen, die der Macht der [[Geißel]] zum Opfer fielen. Ihre rastlosen Seelen streiften in stummer, gequälter Verzweiflung durch die Welt. Dann scharte der [[Lichkönig]] sie um sich und gab ihnen schreckliche Stimmen, sodass die Lebenden ihr verbittertes Klagelied endlich hören konnten. Aus diesem Grund haben sich die Banshees auf [[Ner'zhul]]s Seite geschlagen und dienen jetzt als geschätzte Agenten der [[Geißel]]. In bestimmten Vollmondnächten kann man ihre schrecklichen unheiligen Schreie in den eisigen Winden hören, die von Norden wehen. \r\nWenn die Banshees ihre unheiligen Schreie kanalisieren, kann es geschehen, dass Feinde vorübergehend ihre erlernten Kampffertigkeiten verlieren. Als Folge dieses schrecklichen Fluchs können die Opfer dieses Zaubers ihre Ziele nicht mehr treffen. Indem Banshees die Macht der Nekromantie und die schrille Musik ihrer Schreie vereinen, können sie schützende Hüllen um jede Kreatur herum bilden. Diese unheimliche „Schale“ macht die Kreaturen für eine kurze Zeit unempfindlich gegen jede Form von Magie. Banshees besitzen auch die beängstigende Fähigkeit, sich in die Körper lebender Kreaturen zu versetzen und dadurch die Seele der Kreatur mit ihrer eigenen zu verdrängen. Durch Einsatz dieser Fähigkeit löst sich der Körper der Banshee zwar auf, aber sie erhält dauerhaft Kontrolle über ihre neue Gestalt.\r\nMächtige Banshees sollen sogar in ihre alten Körper zurückkehren können.Häufig werden sie dann [[Dunkle Waldläufer]],[[Jäger]] der Lebenden und der Toten, die nur die Treue zu [[Sylvanas Windläufer]], dem ersten [[Dunklen Waldläufer]] etwas gilt.",},
			["Baron Aquanis"] = { content = "'''Baron Aquanis''' ist ein [[Wasserelementar]] in der [[Tiefschwarze Grotte|Tiefschwarzen Grotte]]. Der besiegte Wasserelementar läßt eine ''Seltsame Wasserkugel'' zurück. Man vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgte. In der Kugel schwappt eine faulig aussehende Wassergestalt herum. Die Kugel selbst zeigt sich unbeeindruckt von jeder äußerlichen Krafteinwirkung. Wenn irgendwer aus diesem Gegenstand schlau wird, wäre das wohl [[Je'neu Sancrea]] vom [[Irdener Ring|Irdenen Ring]]. Er befindet sich beim [[Zoram'gar-Außenposten]] der Horde im [[Eschental]].",},
			["Baron Geddon"] = { content = "Baron Geddon ist zusammen mit [[Garr]] einer der zwei höchsten Offiziere des Feuerfürsten [[Ragnaros]]. Er ist, nach [[Ragnaros]], wahrscheinlich das stärkste [[Feuerelementar]] auf [[Azeroth]]. Seine Macht ist so groß, dass es ihn möglich ist ein Lebewesen in eine wandelnde Bombe zu verwandeln. Baron Geddon war immer ein hilfreicher Verbündeter des Feuerfürsten und während des Elementaren Krieges maßgeblich am Verrat an [[Prinz Donneraan]] dem Windsucher, einem der Söhne [[Al'Akir]]s beteiligt. Geddon lockte den Prinzen in eine Falle, damit sein Meister die Macht des riesigen [[Luftelementare|Luftelementars]] in sich aufnehmen konnte. Doch den Feuerfürsten war es nicht möglich die gesamte Essenz von [[Prinz Donneraan|Donneran]] zu verzehren. Daher schmiedete er diese in einen Talisman ein, den er daraufhin in zwei Teile teilte. Die rechte Hälft gab er in die Obhut von [[Garr]] und die Linke bekam Baron Geddon.",},
			["Baron Glutarr"] = { content = "Baron Glutarr ist ein [[Feuerelementar]] und führt die Lodernden Eindringlinge bei den [[Elementare Invasion|Elementaren Invasionen]] im [[Un'Goro]] Krater an.",},
			["Baron Kazum"] = { content = "'''Baron Kazum''' ist ein mächtiger [[Bergriese]] und Mitglied des [[Hoher abyssischer Rat|Hohen abyssischen Rates]]. Er kann an den Großen [[Windsteine]]n in [[Silithus]] mit Hilfe eines [[Szepter der Anrufung]] (Erde) beschworen werden.",},
			["Baron Kazum"] = { content = "'''Baron Kazum''' ist ein mächtiger [[Bergriese]] und Mitglied des [[Hoher abyssischer Rat|Hohen abyssischen Rates]]. Er kann an den Großen [[Windsteine]]n in [[Silithus]] mit Hilfe eines [[Szepter der Anrufung]] (Erde) beschworen werden.",},
			["Baron Revilgaz"] = { content = "'''Baron Revilgaz''' ist der momentane Machthaber von [[Beutebucht]] im [[Schlingendorntal]] und gehört zu den Piraten der [[Schwarzmeerräuber]]. Seine Statue auf einer kleinen Insel vor der Stadt ist ein für alle weithin sichtbares Zeichen, wem diese Stadt gehört und wem sie ihren Wohlstand verdankt. Man findet ihn in [[Beutebucht]] in der Taverne jenseits des Hafens im Obergeschoss. \r\n===Goblinsponsoring===\r\nSeine Interessen gelten momentan dem Goblinsponsoring für das Rennwagenteam auf der [[Illusionenrennbahn]], indem er [[Pozzik]] die gestohlenen Blaupausen für seine Treibstoffeinspritzpumpe wiederbesorgt.\r\n===Stein der Gezeiten===\r\nAuf der anderen Seite ist Baron Revilgaz daran interessiert, den [[Stein der Gezeiten]], das legendäre Troll-Artefakt, in seine Sammlung alter Relikte einzureihen. Dafür schickt er Freiwillige los, um die [[Spukinsel]] für ihn zu finden. Denn wenn es wirklich einen [[Goblin]]magier und [[Wasserelementare]] gibt, die auf dieser Insel ihr Unwesen treiben, dann heißt das, dass der [[Stein der Gezeiten]] gefunden werden kann. Vielleicht kann er auch einen Weg finden, dem Fluch entgegenzuwirken, der auf dem Stein liegt, denn [[Erzmagier Ansirem Runenweber]], ein [[Magier]] von [[Dalaran]] kann die magischen Überreste einer der Armschienen eines [[Wasserelementar]]s von der Spukinsel analysieren. Denn wenn Revilgaz etwas über [[Magier]] weiß, dann, dass sie einem magischen Rätsel einfach nicht widerstehen können.",},
			["Baron Silberlein"] = { content = "'''Baron Silberlein''' ist der ehemalige Besitzer der [[Burg Schattenfang]] im [[Silberwald]]. Als die [[Worgen]] sich gegen die Magier der [[Kirin Tor]] wendeten, denen sie eigentlich dienen sollten, fiel auch Silberleins Familienbesitz, der jenseits des unscheinbaren Dörfchens [[Lohenscheit]] lag, den unaufhaltsamen Werwölfen zum Opfer. Von Schuldgefühlen halb wahnsinnig adoptierte der Erzmagier [[Arugal]] die später Worgen, als seine Kinder und zog sich in die inzwischen verfallene Burgruine der Silberleins zurück. Doch der Geist des Barons fand keine Ruhe und spuckt noch immer durch die Gemäuer.",},
			["Baron Totenschwur"] = { content = "'''Baron Totenschwur''' ist ein [[Todesritter]] in [[Stratholme]], der [[Kel'Thuzad]] treu ergeben ist. Er regiert dort über die Streitkräfte der [[Geißel]]. Sein Reittier ist das [[Todesstreitross]], welches mit viel Glück bei ihm gefunden werden kann.\r\nTotenschwur verfügt über die Fähigkeiten Schattenblitz, Spalten und Tödlicher Stoß.",},
			["Baron Vardus"] = { content = "'''Baron Vardus''' befindet sich in [[Alterac]] in der Nähe von [[Dandreds Senke]] und ist bekannt als hochrangiges Mitglied des [[Syndikat]]s. Zuletzt wurde er im Oberland des [[Alteracgebirge]]s im Norden von [[Tarrens Mühle]] gesehen. Er ist ein Edler aus dem ehemaligen Königreich von [[Alterac]], und jemand der bekannt ist für seine Kaltherzigkeit und brutale Vorgehensweisen. Er hat seinen Hauptsitz sicherlich irgendwo in den Schlupfwinkeln des [[Syndikat]]s - vielleicht in den Ruinen von [[Strahnbrad]] oder irgendwo in dem Tal im Norden davon.",},
			["Baron Zobelmähne"] = { content = "'''Baron Zobelmähne''' befindet sich vor dem [[Zirkel des Blutes]] im [[Schergrat]]. \r\nEr ist ein Meister der Alchimie und in allen möglichen Arten exotischer Magie bewandert; außerdem ist er ein Freund von [[Rexxar]]. Er hat einen Eber namens Grummel als Haustier und es gibt nichts, was er auf der Welt mehr haßt, als die Söhne des [[Gruul]] und ihren Vater, denn sie haben sein Volk und seine Kinder abgeschlachtet, und nun will er seine Rache dafür. Deshalb hat er eine Falle aus Drachenfeuer gebaut und wenn man gewitzt genug ist, kann man damit einen Gronn töten. Es ist an der Zeit, dass er sich in die Geschehnisse einmischt und dem [[Gronn]] in seiner Todesstunde beiwohnt.",},
			["Barovs"] = { content = "#REDIRECT [[Haus Barov]]", redirect = "Haus Barov",},
			["Basilisk"] = { content = "==Allgemeines==\r\nEin Basilisk ähnelt einem [[Krokolisk]] und ist ein amphibisches Wildtier. Sie sind mit einem Panzer aus nur schwer durchdringbaren Schuppen bedeckt und außerdem noch magisch begabt, was sie besonders gefährlich macht. Basiliske verstecken sich im Unterholz und greifen dann an, wenn man es am wenigsten erwartet. Diese mächtigen, verzauberten Kreaturen sind eine Anomalie in der gesamten Welt von [[Azeroth]]. Sie sind eigentlich nicht für ihre launischen Temperamente bekannt, werden sie aber provoziert, verteidigen die klobigen Kreaturen sich und ihre Nistplätze mit wilder Grausamkeit. Basilisken haben die Fähigkeit, sich an ihre Umgebung anzupassen und in ihr zu gedeihen. Diese Wildtiere zeigen Denkprozesse, die komplexer sind als die mancher Humanoiden. Das Blut eines sehr alten Basilisken ist ein traditionelles Heilmittel der [[Draenei]] gegen Blindheit, aber unglücklicherweise leben die Basilisken der [[Wälder von Terokkar]] wegen der Wilderei verschiedener Lager in der Regel nicht sehr lange. Die Augen der Dunstschuppenbasilisken dienen auch als Zutat für Hellsichtstränke.\r\n'''Siehe auch:'''\r\n* [[Pulsierende blaue Splitter]]\r\n* [[Singender Kristallsplitter]]\r\n==Arten==\r\nZu den häufigsten Arten zählen die Eisenkiefer- u. Kaltaugenbasilisken im [[Schlingendorntal]], die Rotsteinbasilisken in den [[Verwüstete Lande|Verwüsteten Landen]] und die Salzsteinbasilisken auf der [[Schimmernde Ebene|Schimmernden Ebene]] in [[Tausend Nadeln]].\r\nIm verbrannten Tal tief im [[Steinkrallengebirge]] gab es mal eine Basiliskenart, deren Schuppen, wenn man sie zu Staub zermahlte, ein wunderbares Reagenz für einige der Zauber ergab, die [[Collin Mauren]] in [[Sturmwind]] ersonnen hat.\r\n==Vorkommen==\r\n \r\nAuf diese Ungeheuer kann man zum einen leicht in bewaldeten Regionen wie dem Dschungel des [[Schlingendorntal]]s oder den [[Wälder von Terokkar|Wäldern von Terokkar]] stoßen. Zum anderen können sie aber auch in wüsten Einöden wie [[Tanaris]], [[Tausend Nadeln]] oder [[Desolace]] überleben und selbst in den [[Verwüstete Lande|Verwüsteten Landen]] wimmelt es nur so von ihnen. \r\n==Persönlichkeiten==\r\n* '''Steinstarrer''' - Steinstarrer ist der älteste Basilisk in den [[Wälder von Terokkar|Wäldern von Terokkar]]. Die Basilisken von Terokkar leben wegen der Wilderei verschiedener Lager unglücklicherweise in der Regel nicht sehr lange. Es gibt jedoch einen Basilisken, dessen Name viele schon als Kind kannten. Er ist als Steinstarrer bekannt und soll östlich von [[Shattrath]] leben, in der Nähe der Landesgrenze. Steinstarrers Blut wird für ein traditionelles Heilmittel der [[Draenei]] gegen Blindheit benötigt.",},
			["Basislager der Schattenhammer"] = { content = "Das Basislager der Schattenhammer liegt genau im Norden der [[Burg Cenarius]] in [[Silithus]].\r\nDer [[Schattenhammer Kult]], ein dämonischer Kult, der sich den Kräften der Zerstörung verschrieben hat, errichtet seit längerem Lager in [[Silithus]] und hält dort Tag und Nacht bizarre Rituale ab. Bisher weiß man noch nichts über ihre Pläne, allerdings vermutet man, dass sie in irgendeiner Verbindung zu den pulsierenden roten Kristallen stehen, die man überall in der Wüste findet. Die Wachposten in des [[Zirkel des Cenarius]] haben gesehen, dass Gruppen aus dem Basislager der Schattenhammer westlich von [[Burg Cenarius]] [[Sandwürmer]] jagten. Das Rezept für die Zubereitung von [[Sandwürmer]]n ist findet sich ebenfalls im Basislager. Es ist zwar lesbar, enthält aber Hinweise auf Kräuter und Gewürze, von denen man noch nie gehört hat. Der Ork [[Schattenbewahrer Havunth]] ist der Führer des Basislager der Schattenhammer und bewacht das dritte Kapitel des [[Lexikon der Schattenhammer]]. Er ist ebenso Verfasser einiger [[Texte des wahren Glaubens]], die als [[Verschlüsselte Schattenhammertexte]] zu finden sind. Auch der [[Lord der Schattenhammer Everun]] kann bei jedem der drei Lager der Schattenhammer auftauchen und wandert um das Lager. Wenn er nicht bei einem Lager ist, untersuche ein anderes.\r\n==Personen==\r\n* [[Lord der Schattenhammer Everun]]\r\n* [[Schattenbewahrer Havunth]]",},
			["Basislager der Sketh'lon"] = { content = "Das '''Basislager der Sketh'lon''' befindet sich im Süden des [[Schattenmondtal]]s, östlich der [[Wildhammerfestung]]. Dort herrschen die [[Arakkoa]] des [[Dunkler Rat|Dunklen Rates]]. Die Geister des Dunklen Rats versuchen ein [[Alte und mächtige Böse|altes und mächtiges Übel]] durch ein Ritual in diese Welt zu beschwören, das bei den Lavabecken südlich des Lagers durchgeführt werden soll. [[Gul'dan]]s Magie vermischt mit ihrer eigenen und damit wollen sie diese Kreatur in die Welt rufen. Der Tod und die Zerstörung, die dieses Wesen in die Welt bringen würde, sind unvorstellbar.",},
			["Basislager des Drachenmals"] = { content = "Das '''Basislager des Drachenmals''' liegt auf der [[Netherschwingenscherbe]] im [[Schattenmondtal]]. \r\nDie [[Orcs des Drachenmals]] wollen mit einem Bataillon von [[Himmelsteiler]]n losziehen und den Außenposten der [[Aldor]] nordwestlich des geliebten [[Schwarzer Tempel|Schwarzen Tempels]] ausradieren. Ist der [[Altar der Sha'tar]] erst einmal zerstört, stehen ihnen die Verbindungswege zu den Posten bei der [[Echsennarbe]] erneut wieder offen. Ebenso soll der Außenposten der [[Seher]] am Fuße der [[Netherschwingenfelder]] ausradiert werden, denn das [[Sanktum der Sterne]] steht ihrem Verbindungsweg zum Posten bei der [[Stätte der Mondfinsternis]] und bei der [[Stätte der Illidari]] im Weg. Doch der [[Drachenmal Klan]] wagt es nur dann, anzugreifen, wenn die Abwehr geschwächt ist.\r\n===Drachenmalrennen===\r\nDurch dieses Rennen kann man im Ansehen des [[Drachenmal Klan]]s steigen. Der Sieger erhält den Rang eines [[Toporc]]s, doch wenn man der Toporc werden will, muss man die anderen erst einmal schlagen.\r\n==Persönlichkeiten==\r\n* [[Illidarifürst Balthas]]\r\n* [[Oberanführer Mor'ghor]]\r\n* [[Schwadronskommandant Ichman]]\r\n* [[Schwadronskommandant Mulverick]]\r\n'''Sonstige'''\r\n* '''Chefvorarbeiter Lehmklump''' - Chefvorarbeiter Lehmklump meint, es gibt eine Sache, die jeder gute Aufseher braucht: die richtige Ordnungswaffe. Bevor man den Peons etwas Verstand einprügeln kann, braucht man eine Waffe und jeder Aufseher muss die Materialien zur Herstellung seiner eigenen Waffe sammeln. Man benötigt Knotenhautleder und den gehärteten Balg von Tyrantus.\r\n* '''Corlok der Veteran''' - Corlok der Veteran reitet auf einem Netherdrachen und ist ein Gegner im Drachenmalrennen. \r\n* '''Hauptmann Himmelsdonner''' - Hauptmann Himmelsdonner droht, die Welt um einen herum würde in Dunkelheit versinken, wenn seine Meteore den Horizont zerreißen und man es wagt, ihm zum Drachenmalrennen herauszufordern. Man hätte keine Chance. Doch er wird bei dem morbiden Vorhaben mitspielen. Vielleicht kann er anderen Narren, die nach der gleichen Verrücktheit streben, zumindest eine Lehre erteilen. \r\n* '''Ja'y Nosliw''' - Ja'y Nosliw bietet auf seinem gepanzerten [[Netherdrachen]] einen imposanten Eindruck und leitet das Drachenmalrennen. \r\n* '''Murg \"Grufti\" Moorbiss''' - Murg \"Grufti\" Moorbiss ist ein Gegner im Drachenmalrennen. Man sollte sich von seinem grauen Haar nicht täuschen lassen. Er ist trotz allem ein sehr guter Reiter auf seinem [[Flügeldrachen]] und man soll bloß nicht glauben, dass dieser Totgesagte keine Tricks mehr im Ärmel hat. \r\n* '''Trope der Rußhuster''' - Trope der Rußhuster ist ein Gegner im Drachenmalrennen. \r\n* '''Yarzill der Söldner''' - Yarzill der Söldner ist ein Goblin und arbeitet für [[Neltheraku]] und die [[Netherschwingen]]. Er stellt unter anderem Relikte und Eier der Netherschwingen sicher. \r\n* '''Zuchtmeister Varkule Drachenodem''' - Zuchtmeister Varkule Drachenodem steht in der Mitte des Lagers. Er hat auch einmal mit Bergbau angefangen und sucht [[Netheriterz]], Kristalle der Netherschwingen sowie [[Netherstaubpollen]].",},
			["Basislager von Grom'Gol"] = { content = "Das Basislager von Grom'Gol ist der [[Horde]]n-Stützpunkt im [[Schlingendorntal]]. Hier befindet sich auch eine Zeppelin-Station nach [[Unterstadt]] und [[Durotar]]. Kommandant Aggro'gosh versucht, eine sichere Versorgungskette nach Steinard zu gewährleisten, wird jedoch durch einige der örtlichen Einwohner schwer behindert. \r\n==Persönlichkeiten==\r\n* '''[[Kin'weelay]]'''\r\n* '''[[Nimboya]]'''\r\n* '''Kommandant Aggro'gosh''' ist als Kommandant des Kriegshäuptlingsstützpunkts durch seine Ehre gebunden und verpflichtet, die Sicherheit aller Mitglieder der [[Horde]] zu gewährleisten. \r\n* '''Nemeth Falkenauge''' hat auf seinen Reisen die Kampftechniken der verschiedenen Trollstämme untersucht. Ihre Magie scheint sich in eine interessante Richtung entwickelt zu haben, und sie haben sie benutzt, um der mächtigste Stamm in der Gegend zu werden. Sie könnte der Kern einer Waffe gegen die Amani sein. \r\n* '''[[Scharfseher Mok'thardin]]'''",},
			["Bath'rah der Windbehüter"] = { content = "'''Bath'rah der Windbehüter''' ist ein [[Troll Schamane]] im südöstlichen [[Alterac]]. Um Bath'rah zu finden, begibt man sich zu dem Fluss östlich von [[Tarrens Mühle]] und folgt seinem Verlauf Richtung Norden. Irgendwann trifft man dann auf die Troll-Ruinen, in denen sich Bath'rah niedergelassen hat. Er beobachtet diesen Ort seit schon Ewigkeiten. Er beobachtet, damit er eines Tages den großen [[Cyclonian]] fallen sehen kann. Doch Bath'rah fand noch keinen [[Krieger]], der den Windlord besiegen konnte. Um Cyclonian zu beschwören, braucht er einige Gegenstände, die in Bath'rahs Pergament verzeichnet sind. \r\nBath'rah der Windbehüter sucht auch nach [[Schamane]]n mit großer Weisheit, denn die Elementare an diesem Ort haben sich gegen ihn gewendet und so braucht Bath'rah jetzt ein Geistertotem zu seinem Schutz. Er hat bereits die Elemente dafür, aber er braucht etwas mit noch mehr Natur. Etwas noch Wilderes, wie z.B. die Bärenklauen und Spinnenaugen aus den [[Westlichen Pestländern]], auch wenn er danach merkt, dass das Geistertotem alleine nicht stark genug ist. Um erfolgreich zu sein, benötigt er also noch etwas Voodoomagie. Die Trolle im [[Versunkener Tempel|Versunkenen Tempel]] besitzen Federn, die von mächtiger Voodoomagie erfüllt sind; und mit diesen Federn hat er genug Macht, um ein starkes Geistertotem zu formen. \r\n==Bath'rahs Pergament==\r\nFolgende Dinge brauche ich für meinen Zauber zur Beschwörung des großen Cyclonian. Möge das Glück mit Euch sein.\r\n- Bath'rah der Windbehüter\r\n'''Lebenswurz:'''\r\nMan findet [[Lebenswurz]] in freier Natur oder bei den Moderrankenbestien aus den [[Düstermarschen]]. Ihr braucht die Wurzel, um damit die Lebensessenz von Cyclonian in unsere Welt zu ziehen.\r\n'''Blutskalphauer''':\r\nDie Hauer der [[Trolle der Blutskalpe|Blutskalptrolle]] im [[Schlingendorntal]] sind von seltener Güte. Die Bosheit der Blutskalpe ist in ihren Hauern konzentriert. Indem man diese zu Pulver zerstößt, kann man ihre widerwärtigen Kräfte befreien.\r\n'''Essenz der Verbannung''':\r\nDiese Essenz erhält man durch Verschmelzung der drei Glücksbringer der verbannten Elementare in den Bergen des [[Arathihochland]]s. Sammelt donnernde Glücksbringer, brennende Glücksbringer und schäumende Glücksbringer von den Elementaren und legt je acht davon in meinen Kessel. Aus den Glücksbringern bildet sich dann die Essenz der Verbannung.",},
			["Bathrans Schlupfwinkel"] = { content = "Bathrans Schlupfwinkel liegt im [[Eschental]] nördlich von [[Maestras Posten]] und gleich südlich der Grenze zu [[Dunkelküste]]. Die [[Nachtelfen]] wissen von einer Pflanze, die dort früher einmal in den alten Ruinen wuchs: [[Bathranshaar]]. Diese Pflanze war als Heilmittel für Krankheiten des Geistes bekannt.",},
			["Bauernhof"] = { content = "Der '''Bauernhof''' ist für jedes [[Menschen]]dorf von entscheidender Bedeutung, liefert er doch Nahrung für Truppen und Bürger. Die erstaunliche Fähigkeit dieser geschickten Bauern, in jedem Landstrich selbst unter härtesten Bedingungen Nahrungsmittel zu ernten, genießt in den Ländern [[Lordaeron]]s höchsten Respekt. Die Anzahl der Truppen, die ein Dorf unterhalten kann, hängt von der Landfläche ab, die von den kleinen Höfen abgeerntet wird.",},
			["Bauernhof der Dabyries"] = { content = "Der Bauernhof der Dabyries liegt im [[Arathihochland]], nordöstlich der [[Zuflucht]]. Dort lebt Kenata und ihre Familie blüht und gedeiht. Ihre Kinder Marcel und Fardel bestahlen die [[Verlassene]] [[Genavie Kahler]] aus [[Unterstadt]].",},
			["Baumelfenshausen"] = { content = "'''Baumelfenshausen''' ist eine allgemeine Bezeichnung für [[Darnassus]].",},
			["Baumfrosch"] = { content = "#REDIRECT [[Frosch]]", redirect = "Frosch",},
			["Bau der Wildfedern"] = { content = "#REDIRECT [[Harpyien der Wildfedern]]", redirect = "Harpyien der Wildfedern",},
			["Bau des Ashischwarms"] = { content = "Der '''Bau des Ashischwarms''' liegt tief in [[Silithus]]. Es ist das Revier der [[Silithiden des Ashischwarms]]. Nach den ersten Streifzügen einer Zwergen-Expedition in die Schwarmbauten der [[Silithiden]] dieser Region und dem darauf folgenden Wahnsinn der Herrin [[Natalia Mar'alith]], haben die drei Schwarmbauten in Silithus - der Bau des Ashischwarms, der [[Bau des Regalschwarms]] und der [[Bau des Zoramschwarms]] - damit begonnen hunderte von Insektenkriegern auszuspucken. Die erhöhte Aktivität könnte mit den Glyphen in Zusammenhang stehen, die die Kristalle in den drei Bauten der Schwärme bedecken. Der [[Zirkel des Cenarius]] hat nun die besten Späher bis weit in die Schwarmbauten der Silithiden ausgesendet. So hat die Cenarische [[Späherin Jalia]] die Aktivitäten der Silithiden im Ashischwarm nun schon seit Tagen beobachtet und möchte, dass ihr Späherbericht zu [[Windruferin Prachthorn]] auf [[Burg Cenarius]] gebracht wird. Man benötigt dafür den taktischen Einsatz VIII.",},
			["Bau des Regalschwarms"] = { content = "#REDIRECT [[Silithiden des Regalschwarms]]", redirect = "Silithiden des Regalschwarms",},
			["Bau des Zoramschwarms"] = { content = "Der '''Bau des Zoramschwarms''' befindet sich im südwestlichen [[Silithus]]. Um die Silithiden hier im Auge zu behalten wurde die [[Eisenschmiedebrigade]] in der Nähe stationiert. Die Druiden vom [[Zirkel des Cenarius]] haben diese Gegend überwacht und erwarten hier etwas bedeutendes. Genau aus diesem Grund wurde auch [[Späherin Azenel]] diesem Gebiet zugewiesen. Sie hat die Aktivitäten der [[Silithiden des Zoraschwarms]] nun schon seit Tagen beobachtet und nun wartet ihr Späherbericht darauf, zu [[Windruferin Prachthorn]] auf [[Burg Cenarius]] gebracht zu werden. Man benötigt dafür den taktischen Einsatz VI.",},
			["Bazil Thredd"] = { content = "'''Bazil Thredd''' ist ein menschlicher [[Schurke]] der [[Defias]]-Bruderschaft, der im [[Das Verlies|Verlies]] von [[Sturmwind]] gefangen gehalten wird. Er war der Helfer von [[Edwin Van Cleef]], aber in den ersten Jahren seiner Gefangenschaft bekam er niemals Besuch. Die Wärter gingen davon aus, dass er für die Bruderschaft keinen Nutzen mehr hatte und sie ihn daher fallen ließ. Aber vor einigen Monaten hat sich das alles geändert; er bekam regelmäßig Besuch... einmal, manchmal sogar zweimal pro Woche. Es war ein seltsamer Mann, so ein ruhiger Typ... \r\n==Fähigkeiten==\r\nBazil Thredd verfügt über die beiden Fähigkeiten, eine Rauchbombe zu werfen, die in der Nähe befindliche Feinde 4 Sek. lang betäubt. Zum anderen beherrscht er einen Schlachtruf, der die Nahkampfangriffskraft der in der Nähe befindlichen Gruppenmitglieder 2 Min. lang um 4 erhöht. \r\n'''Quellennachweise'''",},
			["Bazzalan"] = { content = "Der [[Satyr]] Bazzalan ist einer der Anführer der [[Sengende Klinge|Sengenden Klinge]] im [[Flammenschlund]] unter [[Orgrimmar]].",},
			["Befrager Vishas"] = { content = "'''Befrager Vishas''' ist ein Bossgegner auf dem Friedhof des [[Das Scharlachrote Kloster|Scharlachroten Klosters]]. Hier foltert dieser [[Menschen Priester]] die Gefangenen im Namen des [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzugs]] mit seinem flammenden , welches man auch von ihm erbeuten kann. Seine einzige Fähigkeit ist das Schattenwort: Schmerz, welches 18 Sekunden lang insgesamt 366 Schattenschaden zufügt. \r\nEines seiner Opfer ist der [[Verlassene]] [[Vorrel Sengutz]]. Wochenlang wurde er von Befrager Vishas gequält. Nun kann er trotz seines freien Willens der dunklen Fürstin nicht mehr dienen. Er fühlt, dass seine Zeit in Azeroth zu Ende geht, denn seine Lebenskraft ist zerschmettert. Vishas nahm Vorrel sogar den Ehering ab und gab ihn stattdessen seiner Frau Nancy, die am [[Lordameresee]] lebte. Vishas prahlte immer mit seiner ach so kostbaren Frau. Nun will Vorrel Rache und deswegen soll Nancy aufgespürt und erschlagen werden, damit sein Ehering zu seiner Frau [[Monika Sengutz]] in [[Tarrens Mühle]] gebracht werden kann. Dies ist Vorrels letzter Wille... \r\n'''Quests'''\r\n'''Quellen'''",},
			["Behüter"] = { content = "Die Behüter waren die Gefangenenwärter der [[Nachtelfen]]gesellschaft bis kurz nach dem Dritten Krieg.\r\n==Die Mitglieder==\r\nZuerst rekrutierten sich die Behüter nur aus freiwilligen [[Schwestern von Elune]], so dass sie ausschließlich aus diesen [[Nachtelfen|Nachtelfinnen]] bestand. Als ihre Pflichten aber ausgeweitet wurden, akzeptierten die Behüter auch [[Nachtelfen|Nachtelfinnen]] aus anderen Berufen. Es wurde eine Mischung aus Freiwilligen und militärischen Dienstgraden, die sich zwar als Organisation leicht vergrößerte, aber immer noch in einem überschaubaren Rahmen blieb. [[Illidan|Illidan Sturmgrimm]] tötete fast alle Behüter nach dem Dritten Krieg. Zu diesem Zeitpunkt hörte die Gruppe auf, als Einheit zu existieren.\r\n==Geschichte und Organisation==\r\nKurz nach der Großen Teilung verurteilte [[Malfurion|Malfurion Sturmgrimm]] seinen Bruder [[Illidan]] zu ewig währender Haft, weil dieser einen zweiten Brunnen der Ewigkeit erschaffen hatte. Mit dieser Bestrafung hoffte [[Malfurion]], [[Illidan]] davon abhalten zu können, sich rücksichtslos immer mehr arkane Macht anzueignen. Doch zu diesem Zeitpunkt war [[Illidan]] bereits ein außergewöhnlich mächtiger [[Magier]], und [[Malfurion]] wagte es nicht, ihn unter der Aufsicht von nur ein oder zwei Wachen zurückzulassen.\r\nEine der [[Schwestern von Elune]] namens [[Maiev Schattensang]] hatte vor seinem Prozeß bereits bewiesen, dass sie fähig war, [[Illidan]] zu bewachen. Malfurion bat sie daher, mit weiteren Freiwilligen aus den Reihen der [[Schwestern von Elune|Schwesternschaft]] eine Wachtruppe aufzustellen. [[Maiev Schattensang|Maiev]] gehorchte und [[Malfurion]] nannte diese neue Einheit die Behüter, denn sie sollten dafür Sorge tragen, dass [[Illidan]] nie wieder aus seinem Gefängnis entkommen konnte. [[Maiev Schattensang|Maiev]] als Anführerin der Behüter unterstand direkt der Spitze der [[Nachtelfen]]regierung, also der Hohe[[priester]]in [[Tyrande Wisperwind]]\r\nDie Behüter wurden also eigens nur zu dem Zweck gegründet, [[Illidan]] zu bewachen. Doch im Laufe der Zeit ergaben sich neue Gefahren, und [[Tyrande]] weitete den Aufgabenbereich der Behüter auch auf die Bewachung anderer Gefangener aus. [[Maiev Schattensang|Maiev]] übernahm diese zusätzlichen Aufgaben mit grimmiger Freude. Die Behüter wurden Spezialistinnen nicht nur für die Bewachung von Gefangenen in ihren Hügelgefängnissen, sondern auch für die Jagd auf gefährliche Kriminelle.\r\nAußerhalb der Hügelgefängnisse arbeiteten die Angehörigen der Behütertruppe alleine. Diese tödlichen Frauen waren weder eine Miliz, noch wurden sie als Teil der [[Schwestern von Elune|Schwesternschaft von Elune]] oder der [[Schildwache]]n angesehen. Als Anführerin der Behüter erhielt [[Maiev Schattensang|Maiev]] den Rang einer Aufseherin, den sie später an einige wenige Behüterinnen weiter verlieh, die sich durch außergewöhnliche Kampffertigkeiten, Spurensuchertalente und Hartnäckigkeit ausgezeichnet hatten.\r\nWährend des Dritten Krieg machte sich [[Tyrande]] klar, dass [[Illidan]] inzwischen über zehntausend Jahre in seinem Kerker schmachtete. Sie fand nicht nur, dass er seine Schuld der Gesellschaft gegenüber damit mehr als beglichen habe, sondern auch, dass er ein wertvoller Verbündeter gegen die [[Brennende Legion]] sein könnte. So stürmte sie mit einem Trupp Soldaten [[Illidan]]s Gefängnis. Als [[Illidan]]s Wächterinnen ihren Gefangenen nicht herausgeben wollten, griffen [[Tyrande]] und die [[Schildwache]]n sie an und töteten einige der Behüter. Kaum war er befreit, stahl und verschlang [[Illidan]] den Schädel von [[Gul'dan]] und verwandelte sich dadurch in einen [[Dämon]].\r\nWütend über [[Tyrande]]s Taten schwor [[Maiev Schattensang|Maiev]], sie würde [[Illidan]] finden und ins Gefängnis zurückbringen. In Anbetracht der nicht zu leugnenden Macht des [[Dämon]]en nahm [[Maiev Schattensang|Maiev]] die meisten der Behüter mit auf ihre Jagd. Sie verfolgten [[Illidan]] über das Meer von [[Lordaeron]] und weiter bis zu den Zerbrochenen Inseln. Als er das Grabmal von [[Sargeras]] betrat, fürchtete [[Maiev Schattensang|Maiev]], er wolle sich ein magisches Artefakt beschaffen, mit dem er noch viel schwerer zu fangen wäre.\r\nDoch sie und die anderen Behüter erreichten [[Illidan]] zu spät. Er hatte sich bereits das Auge von [[Sargeras]] angeeignet. Er benutze die Macht des Auges und beschwor die Steinwände des Grabmals, so dass die Behüter in einem Abschnitt des Grabes gefangen waren, den er dann mit Meerwasser flutete. Allein [[Maiev Schattensang|Maiev]] konnte der Falle entkommen, all ihre Schwestern ertranken. Mit einem einzigen, hinterhältigen Schlag hatte [[Illidan]] die Behüter fast völlig ausgelöscht.\r\n[[Maiev Schattensang|Maiev]] schwor Rache, um jeden Preis. Sie verließ ihren Dienst und jagte weiter hinter [[Illidan]] her, bis sie ihm schließlich in die [[Scherbenwelt]] folgte. Doch ihre nun schon sehr lange Abwesenheit von [[Azeroth]] und die Tatsache, dass [[Illidan]] weiterhin frei und bei bester Gesundheit war, lassen die [[Nachtelfen]] vermuten, dass sie auf ihrem Rachefeldzug umgekommen ist.\r\n'''Quelle:'''",},
			["Behüter Biggs"] = { content = "Seine Karawane aus [[Dunkelhain]], wurde von [[Verirrte]]n angegriffen, die Wachen getötet und die Vorräte verstreut. Behüter Biggs ist der einzige Überlebende. Er wurde während des Angriffs der [[Verirrte]]n betäubt, aber bevor ihm schwarz vor Augen wurde, sah er einen der Wagen, der zur [[Zuflucht der Verirrten]] gezerrt wurde. Eine Karawanentruhe mit wertvollen Reagenzien war in diesem Wagen, Reagenzien, die unabdingbar für die Studien der Hexer der [[Burg Nethergarde]] sind. Seine Karawane sollte zur östlichen Küste ziehen, aber sie erreichten ihr Ziel nicht. Er hat geschworen, die verbliebenen Vorräte zu schützen, aber wilde Kreaturen schleichen in der Nähe herum. Er hat die wichtigsten Vorräte eingepackt, die er vor den Angriffen retten konnte, doch wenn er [[Burg Nethergarde]] erreichen soll, dann muss er diesen Wagen reparieren. Und dafür braucht er Holz. Starkes, trockenes Holz.",},
			["Beinplatten des chromatischen Widersetzers"] = { content = "Die '''Beinplatten des chromatischen Widersetzers''' sind ein episches Schweres Rüstungsteil. Um diese Beinplatten zu schmieden, muss man die folgenden Gegenstände zu [[Jeziba]] nach [[Andorhal]] bringen: \r\n* 1 chromatischer Knochenpanzer. \r\n* 10 glänzende chromatische Schuppen. \r\n* 10 Einheiten Blut von Helden. \r\n* 5 Häute des Schattens.\r\nJeziba benötigt den Knochenpanzer eines erwachsenen chromatischen Drachen, um die Grundlage der Gamaschen zu fertigen. Die Glänzenden chromatischen Schuppen bringt er dann auf das Grundgerüst auf und verzaubert sie im Blut der Helden. Schließlich muss Jeziba noch die geschmeidige Haut des Schattens auf die inneren Schienbeinschützer aufbringen.",},
			["Belagerungsmaschine"] = { content = "Die '''Belagerungsmaschine''' (engl. The Siege Engine) ist eine Belagerungswaffe in Schlachtfeldern wie dem Tausendwintersee oder den [[Sande von Ulduran|Sanden von Ulduran]]. Diese Waffe hat die größte Reichweite. Ein Kanonier sitzt im Geschützturm und hat die komplette Kontrolle darüber. Der Fahrer macht nichts anderes außer die Belagerungsmaschine zu bewegen. Die Passagiere dieser Belagerungsmaschine sind komplett geschützt, können dafür aber keine Feinde angreifen. Auch die Belagerungsmaschine hat einen starken Rammbock.",},
			["Belgrom Felshammer"] = { content = "'''Belgrom Felshammer''' ist für gewöhnlich vor der Halle der Kriegerhelden zu finden. Belgrom interessiert sich u.a. für die [[Tauren der Grimmtotem]] und hat sogar ein Kopfgeld auf sie ausgesetzt. Er hält auch die [[Silithiden]] in [[Tausend Nadeln]] für eine Bedrohung und möchte sie in die Tiefen zurückgedrängt haben, aus denen sie gekommen sind. Deswegen soll man seine versiegelte Notiz [[Moktar Krin]] in [[Tausend Nadeln]] bringen. Eine weitere Bedrohung gibt es in [[Feralas]] und so schickt Belgrom Abenteuer zu [[Rok Orhan]] im [[Camp Mojache]]. Ein Stamm von Ogern, die sich Gordunni nennen, ist die vorherrschende Militärmacht dort, und ihre Zahl wächst. Sie müssen aufgehalten werden, bevor sie die Anwesenheit der [[Horde]] in [[Feralas]] bedrohen. Eine [[Blutelf]]e behauptete vor kurzem, in [[Azshara]] lägen große Reichtümer, mächtige Gegenstände. Er sollte ihr nur ein paar Krieger zu ihrem Schutz schicken und dafür würde er belohnt. Doch sie hat sie alle umgebracht. Nun hat er [[Ag'tor Blutfaust]] nach [[Valormok]] / [[Azshara]], um den Verrat von [[Magus Rimtori]] zu vergelten.",},
			["Belmaras Geschichtsbuch"] = { content = "[[Bannzauberin Belmara]] in [[Kirin'Var]] im [[Nethersturm]] hatte ein altes Buch mit Geschichten in ihrer Wohnung in der Zaubergasse von [[Kirin'Var]]. Der abgenutzte, dicke Foliant ist kein Zauberbuch, wie man es vielleicht von einem [[Magier]] der [[Kirin Tor]] erwartet hättet. Die Seiten dieses Bandes sind voll von handgeschriebenen Geschichten mit bunten Zeichnungen. Der Foliant scheint viel älter zu sein, als seine Besitzerin und stammt vielleicht aus ihrem Familienerbe. Möglicherweise war das starke Band zu diesem Buch das, was Belmaras Geist an die Ruinen von [[Kirin'Var]] gefesselt hat.",},
			["Belnistrasz"] = { content = "Belnistrasz befindet sich in Gestalt eines Menschen im [[Hügel der Klingenhauer]]. Er hatte sich schon tot gewähnt... oder schlimmer, als Mahlzeit für die von der [[Geißel]] befallenen [[Stacheleber]]. In der Nähe des Eingangs befindet sich ein Götze, der als makabrer Ofen für die [[Stacheleber]] fungiert; die Bestien verzehren die aus dem [[Brachland]] Entführten. Belnistrasz kann den Götzen außer Funktion setzen und verhindern, dass sie ihn erneut nutzen, aber er benötige dabei Hilfe. Er möchte, dass man ihn zum Götzen der [[Stacheleber]] in den [[Hügeln der Klingenhauer]] begleitet und ihn beschützt, während er das Ritual durchführt, um den Götzen auszuschalten. Belnistrasz' plötzlicher Abgang danach hinterläßt eine brennende Kohlenpfanne und während man in die Flammen starrt, erfüllt das Bild eines roten Großdrachen mit riesigen Flügeln den Geist. Eine rauere Version von Belnistrasz' Stimme spricht.",},
			["Berens List"] = { content = "'''Berens List''' ist eine versteckte Höhle in den Hügels des südlichen [[Silberwald]]s, nahe einem Nest der Hexer von [[Dalaran]]. Man hat Berichte erhalten, dass eine Gruppe [[Untote]]r sich hier zusammenrottet, um einen Angriff gegen die [[Verlassene]]n vorzubereiten.",},
			["Bergbau"] = { content = "== Allgemeines==\r\nBergbau ist ein sehr praktisches Handwerk, mit deren Hilfe man sich Rohmaterial für [[Schmied]]ekunst, dem [[Juwelenschleifer|Juwelenschleifen]] oder [[Ingenieur]]skunst beschaffen kann. Man muss diese Berufe jedoch nicht gelernt haben, um Bergmann werden zu können. Es ist auch sehr profitabel, einfach Rohstoffe zu sammeln und sie an [[Schmied]]e, [[Juwelenschleifer]] und [[Ingenieur]]e zu verkaufen. In [[Azeroth]] gibt es viele Stellen, an denen Erze abgebaut werden können, insofern zahlen sich Bergbaufertigkeiten auf jeden Fall aus.\r\n'''Quelle:''' wow-europe.com\r\n==Besondere Bergbau-Fundstücke==\r\nIn [[Azeroth]] gibt es neben den bekannten Metallen und Gesteinen auch eine Vielzahl von besonderen Bodenschätzen, die nur durch bergmännischen Abbau geborgen werden können oder bereits geborgen wurden.\r\n===Besondere Metalle===\r\n* [[Arkanit]]\r\n* [[Blutsteinerz]] \r\n* [[Indirium]]\r\n* [[Echtsilber]]\r\n* [[Mithril]]\r\n===Besondere Kristalle===\r\n* [[Blutjuwelenkristall]]\r\n* [[Citrin]]\r\n* [[Draenethyst]]\r\n* [[Elementarsplitter]]\r\n* [[Fehlerlose Draenethystsphäre]]\r\n* [[Frosthagelsplitter]]\r\n* [[Kristallträne]]\r\n* [[Machtkristalle]]\r\n* [[Pulsierende blaue Splitter]]\r\n* [[Singende Kristallsplitter]]\r\n===Besondere Steine===\r\n* [[Gahz'ridian]]\r\n* [[Gordunnikobalt]]\r\n* [[Suntarasteine]]\r\n* [[Träne von Elune]]\r\n* [[Träne der Monde]]",},
			["Bergkönig"] = { content = "Die '''Bergkönige''' oder \"[[Than]]es\", wie sie in [[Eisenschmiede]] genannt werden, sind die mächtigsten [[Zwergen Krieger]] in [[Khaz Modan]]. Die tapferen [[Krieger]] tragen verzauberte Kriegshämmer und Streitäxte und messen sich für ihr Leben gern mit ebenbürtigen Widersachern. Bergkönige interessieren sich nicht für die für ihr Volk typische Beschäftigung mit mechanischen Geräten und den Abbau kostbarer Minerale, sondern leben nur für den Kampf. Man kann sich darauf verlassen, dass die Bergkönige, deren einziges Ziel der Schutz der [[Allianz]] ist, die ihr Königreich im [[Der Zweite Krieg|Zweiten Krieg]] gerettet hat, unter jeder Flagge kämpfen, wenn es darum geht, die Freiheit gegen den allgegenwärtigen Schatten des Bösen zu verteidigen. \r\n==Fähigkeiten==\r\n* '''Sturmschlag''' - Die Zwerge der [[Nistgipfel]] üben den Hammerwurf als sportlichen Wettkampf und Training für den Krieg. Aber nur die Bergkönige von Eisenschmiede können einen Hammer so fest werfen, dass ihre Gegner die Besinnung verlieren. Daher ist der Sturmschlag einer der gefährlichsten und wirkungsvollsten Angriffe der mächtigen Bergkönige.\r\n* '''Donnerschlag''' - Diese mächtige Fähigkeit wurde erstmals von Murgen Hammerfall benutzt, um eine Schar angreifender [[Gnolle]] im [[Alteracgebirge]] zu bekämpfen. Sie ermöglicht den Bergkönigen, den Erdboden zu erschüttern und verheerende Schockwellen aus purer Energie auszuschicken, die in der Nähe befindlichen Feinden erheblichen Schaden zufügen.\r\n* '''Hieb''' - Bergkönige, die die Hieb-Technik erlernen, schlagen mit solcher Wut zu, dass ihre normalen Angriffe einen Feind nicht selten lähmen und zerschmettern können.\r\n* '''Avatar''' - Wenn Bergkönige die Energien des von den Zwergen „neu entdeckten verzauberten Erbes“ bündeln, nehmen sie an Kraft und Größe zu – und sie nehmen die physikalischen Eigenschaften von bearbeitetem Stein an. In dieser Form sind sie unempfindlich gegen magische Angriffe und genießen eine deutlich verbesserte Widerstandskraft.",},
			["Bergriese"] = { content = "#REDIRECT [[Bergriesen]]", redirect = "Bergriesen",},
			["Bergriesen"] = { content = "==Allgemeines==\r\nBergriesen sind mildtätig und von Natur aus Einzelgänger, doch als sie erwachten, fanden sie heraus, dass ihre ruhige Welt plötzlich zur Hälfte ein hektisches Schlachtfeld aus Feuer und Leid ist. Als die [[Brennende Legion]] in der Welt erschien, haben die Bergriesen ihre Berge verlassen, um den [[Nachtelfen]] zu helfen. Auch heute noch verfügen die Riesen über ein extrem angriffslustiges Naturell, denn die eigentlich sanften Bergriesen sind gar nicht mehr so sanft, wenn sie versuchen einen zu zerschmettern. Jetzt die Bergriesen haben ihren Mut und ihre Stärke den Gebieten der [[Nachtelfen]] gewidmet - und stehen bereit, um den letzten Rest der [[Brennende Legion|Brennenden Legion]] aus der Welt zu verbannen. \r\n===Aussehen===\r\nMan erkennt Bergriesen an ihrer enormen Größe und daran, wie der Boden erzittert, wenn man durch man felsiges Gelände reist. Sie sind ca. 6 Meter hoch und wiegen beinahe 6 Tonnen. Diese gewaltigen Nahkampf-Einheiten können unvorstellbare Mengen an Strapazen von Angreifern auf sich nehmen. Sie sind hart wie Stein - im wahrsten Sinne des Wortes. Ihre Ernährung besteht aus Stein, Felsen und selbst vor Gebäuden machen sie keinen Halt. Ihre natürliche Lebensspanne beträgt mehrere tausend Jahre.\r\n===Herkunft===\r\nDiese monströsen Wesen wurden von den [[Titanen]] erschaffen, als die Welt noch jung war und bestehen aus lebenden Stein und robuster Flora. Doch auch wenn Bergriesen Schöpfungen der [[Titanen]] sind, dienen einige, wie [[Golemagg der Verbrenner]] und [[Baron Kazum]] den Elementar-Leutnants der [[Alte Götter|Alten Götter]].\r\n==Arten==\r\nEs gibt viele verschiedene Arten von Bergriesen, z.B. aus Stein, Eis ([[Frostriese]]), Erde und sogar Lava ([[Geschmolzener Riese]]). Die Bergriesen aus Stein haben im nordwestlichen [[Feralas]] und in [[Azshara]] ihr Hauptgebiet, wo sie unter dem Namen [[Klippengänger|Klippen-]] u. [[Landgänger]] auftauchen. Die Bergriesen in der [[Scherbenwelt]] werden auch als [[Koloss]] bezeichnet.\r\n* [[Frostriese]]\r\n* [[Geschmolzener Riese]]\r\n* [[Klippengänger]]\r\n* [[Koloss]]\r\n* [[Landgänger]]\r\n==Persönlichkeiten==\r\n* [[Baron Kazum‎]]\r\n* [[Fürst der Splitter]]\r\n* [[Steinbehüter Fozruk]]",},
			["Berg Hyjal und Illidans Geschenk"] = { content = "Nach der durch die Implosion des Brunnens erzeugten Schockwelle, die die ganze Welt bis ins Innerste erschütterte, strömte das Meer in die klaffende Wunde der Welt und füllte sie. Fast achtzig Prozent der Landmasse von Kalimdor waren zerstört worden – zurück blieben eine Hand voll separater Kontinente, die von einem neuen, tosenden Meer umgeben waren. In der Mitte des neuen Meeres, wo sich einst der Brunnen der Ewigkeit befunden hatte, herrschte ein tobender Sturm wütender Gezeiten und chaotischer Energien. Der Wirbel der schrecklichen Narbe, die Mahlstrom genannt wurde, sollte nie wieder zum Stillstand kommen. Der Mahlstrom blieb eine ständige Erinnerung an die furchtbare Katastrophe und das utopische Zeitalter, das für immer dahin war ...\r\nDie wenigen Nachtelfen, die die entsetzliche Explosion überlebt hatten, drängten sich auf behelfsmäßigen Flößen zusammen und ruderten langsam der einzigen sichtbaren Landmasse entgegen. Irgendwie überlebten Furion, Tyrande und Cenarius dank der Gnade Elunes die Große Teilung. Die erschöpften Helden waren sich einig, dass sie die Überlebenden führen und ihrem Volk eine neue Heimat finden mussten. Im Laufe ihrer schweigsamen Fahrt betrachteten sie die Trümmer ihrer Welt und gelangten zu der Einsicht, dass ihr Ehrgeiz für die Verwüstungen ringsum verantwortlich war. Sargeras und seine Legion waren zwar durch die Zerstörung des Brunnens aus der Welt verschwunden, doch Furion und seine Kameraden quälte der Gedanke, welch schrecklichen Preis der Sieg gekostet hatte. Zweifellos waren Azshara und ihre Elite der Hochwohlgeborenen auf dem Grund des brodelnden Meeres zerschmettert worden. Nichtsdestotrotz befanden sich unter den Überlebenden, die es zur Küste des neuen Landes schafften, viele Hochwohlgeborene. Furion misstraute zwar ihren Motiven, war aber überzeugt, dass sie keinen Unfug mehr mit den Energien des Brunnens anstellen konnten.\r\nAls die erschöpften Nachtelfen an der Küste des neuen Kontinents landeten, stellten sie fest, dass der heilige Berg Hyjal die Katastrophe überlebt hatte. In dem Trachten, sich eine neue Heimat zu schaffen, erklommen Furion und die Nachtelfen die Hänge des Hyjal und gelangten auf den windumtosten Gipfel. Als sie in das bewaldete Tal zwischen den hohen Berggipfeln hinabstiegen, fanden sie einen kleinen, friedlichen See. Doch zu ihrem Entsetzen mussten sie feststellen, dass das Wasser dieses Sees verdorben war – durch Magie.\r\nIllidan, der die Teilung ebenfalls überlebt hatte, hatte den Gipfel des Hyjal lange vor Furion und den Nachtelfen erreicht. In seinem wahnsinnigen Begehren, die Ströme der Magie in der Welt zu erhalten, hatte Illidan die Phiolen mit dem kostbaren Wasser des Brunnens der Ewigkeit in den Bergsee geschüttet. Die kraftvollen Energien zündeten umgehend und verschmolzen zu einem neuen Brunnen der Ewigkeit. Der überschwängliche Illidan war überzeugt, dass der neue Brunnen ein Geschenk für künftige Generationen darstellte, und konnte nicht fassen, als der wütende Furion ihn jagte. Furion erklärte seinem Bruder, dass Magie an sich chaotisch sei und unweigerlich zu Verderbnis und Unfrieden führen musste. Dennoch wollte Illidan seinen magischen Kräften nicht abschwören.\r\nFurion wusste genau, wohin Illidans verräterische Ränke führen würden, und beschloss, ein für alle Mal mit seinem machtgierigen Bruder abzurechnen. Mit Hilfe von Cenarius sperrte Furion Illidan in eine große unterirdische Kammer – auf dass er bis ans Ende der Zeit angekettet und machtlos bleiben sollte. Die Nachtelfen befürchteten, die Zerstörung des neuen Brunnens könnte eine noch größere Katastrophe auslösen, daher beschlossen sie, ihn in Ruhe zu lassen. Furion verkündete jedoch, dass nie wieder Magie praktiziert werden sollte. Unter den Augen des wachsamen Cenarius begannen die Nachtelfen das Studium der uralten Druidenkünste, mit denen sie die verwüstete Erde heilen und ihre geliebten Wälder am Fuße des Berges Hyjal wieder aufforsten konnten.",},
			["Bericht über die Bruderschaft der Defias"] = { content = "Der '''Bericht über die Bruderschaft der Defias''' stammt aus der Feder von [[Baros Alexston]] im Büro des Stadtarchitekten von [[Sturmwind]]. Er soll in einer Audienz beim König bei König [[Varian Wrynn]] in der Burg Sturmwind abgeliefert werden. \r\n \r\n==Inhalt==\r\nEure Majestät!\r\nEs gibt der Gründe viele, warum ich glaube, hinsichtlich der \"Bruderschaft der Defias\" und ihrer jüngsten Aktivitäten im ganzen Königreich sollte ein Bericht abgefasst und vorgelegt werden.\r\nLasst mich der Klarheit halber mit einem kleinen Exkurs in die Vergangenheit beginnen. Wie Euch vielleicht bekannt ist, begann ich meine Arbeit in Diensten der Stadt Sturmwind als Mitglied der Steinmetzgilde. Nach Jahren der Arbeit beendeten wir schließlich den Wiederaufbau von Sturmwind, aber niemand wollte die Steinmetzgilde bezahlen oder für die Bezahlung bürgen.\r\nZu dieser Zeit war Edwin van Cleef der gewählte Gildenmeister der Steinmetze. Als solcher ergriff er das Wort und forderte das Entgelt für unsere Arbeit ein. Als Reaktion darauf ordnete das Oberhaus von Sturmwind die Auflösung der Steinmetzgilde an, was van Cleef verständlicherweise sehr erzürnte. Unter seiner Führung kam es zum Aufstand und van Cleef führte die Steinmetze aus der Stadt.\r\nDoch ehe ich nun fortfahre, muss ich auf einige andere Ereignisse zu sprechen kommen, die sich zu jener Zeit ereignet haben.\r\nZunächst einmal wurde mir der Posten des Stadtarchitekten angetragen, wenn ich mich van Cleef nicht anschlösse. Wegen gewisser ideologischer Differenzen entschied ich mich für den Verbleib in Sturmwind.\r\nWährend des Aufstands wurde Bazil Thredd, van Cleefs Helfer und Vertrauter, gefangen genommen und eingesperrt. Thredd sollte verhört und vor Gericht gestellt werden, wurde dann aber fast im Verlies vergessen.\r\nEr kehrte zu van Cleef zurück, nachdem er den Rest der Steinmetze aus Sturmwind geführt hatte. Danach machte er sich die relative Schutzlosigkeit von Westfall zunutze, vertrieb dank zahlenmäßiger Überlegenheit viele der Bauern und übernahm eine Hand voll der Goldminen.\r\nMit diesen Rohstoffen in der Hinterhand fasste van Cleef schließlich einen Racheplan gegen die Regierung von Sturmwind.\r\nDiese Erkenntnis erlangten wir unter Mithilfe des Inhabers des vorliegenden Dokuments, der uns bei der Aufdeckung der weit reichenden Verschwörung geholfen hat.",},
			["Berserker"] = { content = "#REDIRECT [[Trollberserker]]", redirect = "Trollberserker",},
			["Beschwörer"] = { content = "#REDIRECT [[Blutelfen-Hexenmeister]]", redirect = "Blutelfen-Hexenmeister",},
			["Beschützer der Azurwacht"] = { content = "#REDIRECT [[Draeneipriester]]", redirect = "Draeneipriester",},
			["Bespielte Tavernen"] = { content = "#REDIRECT [[:Kategorie:Taverne]]", redirect = ":Kategorie:Taverne",},
			["Bespielte Territorien und Reviere"] = { content = "#REDIRECT [[:Kategorie:Nachtliga: Reviere]]", redirect = ":Kategorie:Nachtliga: Reviere",},
			["Besudelter Wassergeist"] = { content = "Die meisten der Kreaturen, die von der Energie der [[Exodar]]-Kristalle berührt wurden, wurden auf die gleiche Art verdorben: seltsame Male auf ihrer Haut, aggressiveres Verhalten und kleine Kristallsplitter in ihren Körpern. Die besudelten Wassergeister auf der [[Blutmythosinsel]] aber scheinen sich vollständig in Kristall zu verwandeln. Man hat bis jetzt noch nichts gesehen, was derart auf die Kristalle reagiert hat, doch als man den besudelten Teich untersucht hat, haben sie sich als besonders gefährlich herausgestellt.",},
			["Bethekk"] = { content = "Bethekk ist einer der trollischen Hauptgötter und [[Arlokk]] war ihre Hohepriesterin.\r\n==Gildenspezifische Beschreibungen==\r\nSiehe auch:\r\n* [[Bethekk, der Panther]]",},
			["Bethor Eismacht"] = { content = "'''Bethor Eismacht''' ist ein hochrangiger und mächtiger [[Untoter Magier]] im Magieviertel von [[Unterstadt]]. Vor langer Zeit waren [[Gunther Arkanus]] und Bethor Eismacht, wie auch der jetzt der Geißel dienende [[Totenbeschwörer]] [[Thule Rabenklaue]], Freunde und Schüler beim [[Kirin Tor]], einer Magiergesellschaft in [[Dalaran]]. Gunther und Bethor fielen beide der Seuche anheim, aber Bethor dachte, Gunther wäre entweder tot geblieben oder für die Armee des Lichkönigs erweckt worden. Doch nun will Bethor Gunther für die Verlassenen gewinnen und hat einen Zauber auf ein Buch gelegt, der Gunther, sobald er ihn sieht, zeigen wird, dass Bethor ebenfalls frei vom Einfluss des Lichkönigs ist. Bethor kennt auch viele der Zauber von Thule Rabenklaue und kann [[Apotheker Renferrel]] auf dem [[Grabmal]] im [[Silberwald]] dabei helfen, einen Trank zu brauen, der ihnen entgegenwirkt.",},
			["Betrachter"] = { content = "Betrachter zählen zu den [[Dämonen]] aus der [[Scherbenwelt]]. Es sind magisch hoch begabte schwebende Kugeln mit einem großen zentralen Auge, welches von 6 kleineres Augen umsäumt wird. \r\n==Persönlichkeiten==\r\n* [[Broggok]]\r\n* [[Shirrak der Totenwächter]]\r\n* [[Veneratus]]\r\n* [[Xelet]]\r\n==Gefährte==\r\n* [[Schläfriger Willy]]",},
			["Bettlerschlupfwinkel"] = { content = "Auf Befehl von [[Varimathras]] wurde die Expeditionsstreitmacht ausgeschickt, um das untere [[Azeroth]] zu vermessen. Beim Spähen bemerkte [[Todespirscher]] Zraedus einen Spitzel der Menschen, der den Bettlerschlupfwinkel im [[Dämmerwald]] ausspionierte. Ehe Zraedus ihn festnehmen konnte, schnappten ihn einige [[Orcs]] und brachten ihn nach [[Steinard]], ihrer Festung in den [[Sümpfe des Elends|Sümpfen des Elends]]. Todespirscher Zraedus möchte den Orcverbündeten helfen. Die [[Orcs]] sahen das Lager von [[Apotheker Faustin]] und Todespirscher Zraedus im Bettlerschlupfwinkel nicht, dennoch wollen sie sie unterstützen. \r\nZraedus arbeitetet hier mit [[Apotheker Faustin]], um ein ... Wahrheitsserum für ihren Freund in [[Steinard]] zu entwickeln. Er ist wirklich ein Problem. Ein Naseweis, der im Bettlerschlupfwinkel herumschnüffelt, hat ihnen gerade noch gefehlt. [[Apotheker Faustin]] ist sich sicher, die [[Orcs]] in [[Steinard]] können es kaum erwarten, zu hören, was ihr Freund zu sagen hat. \r\nDoch sie müssen mit einer gewissen Diskretion vorgehen. Immerhin wird man nicht da reinspazieren und Spitzel Marksen überzeugen, Faustins Gebräu zu trinken. Aber wenn es eines gibt, zu dem die [[Menschen]] nicht nein sagen können, dann ist es Fusel. Todespirscher Zraedus mischt also Faustins Serum in Bier. Der arme Kerl wird garantiert keine Hemmungen haben, wenn es darum geht, ein Gebräu zu kippen.",},
			["Beutebucht"] = { content = "Beutebucht liegt an der Südspitze des [[Schlingendorntal]]s. In dieser blühenden Küstenstadt, die Teil des [[Dampfdruckkartell]]s ist, hat [[Baron Revilgaz]] von den [[Schwarzmeerräuber]]n das Sagen, den erklärten Todfeinden der [[Blutsegelbukaniere]]. Im Hafen legt auch ein Schiff an, mit dem man in kurzer Zeit die Stadt [[Brachland|Ratschet]] in [[Kalimdor]] erreichen kann. \r\n===Lebensart===\r\nEs ist teuer und anstrengend, genug Tiger zu töten, um damit den Bedarf an Tigerzähnen für den Export auf die Inseln in den südlichen Meeren decken zu können. Glücklicherweise haben die [[Goblins]] eine gewisse Technik entwickelt, mit deren Hilfe sie aus einfachem hornähnlichen Material nicht nachweisbare Fälschungen herstellen können. Erstaunlicherweise eignen sich die Hauer von Schädelspaltertrollen dafür am besten. Im Übrigen sind Omeletts aus Spinneneiern der letzte Schrei in Beutebucht. \r\n==Geschichte==\r\nVor ungefähr 60 Jahren von [[Baron Revilgaz]] befreit und umbenannt entwickelte sich Beutebucht zur Müllkippe der ungezähmten Küste. Die Stadt wanderte vor den [[Goblins]] in die Hände von Käpt Batholom Kanuis dem Oberanführer der [[Blutsegelbukaniere]] dieser Zeit. Unter Käpt Kanuis wuchs und gedieh die Stadt und wurde zu einem Umschlagplatz für Drogen und Waren aller Art. Die Stadt wurde streng Rassen getrennt geführt, Käpt Kanuis war ein gefürchteter verachter aller anderen Wesen [[Azeroth]]s und dieser Umstand brachte auch die Stimmung gegen ihn und am Ende [[Baron Revilgaz]] seinen Sieg gegen die [[Blutsegelbukaniere]]. Der genaue Vorgang, nämlich der Einmarsch von [[Baron Revilgaz]] und seiner [[Goblin]]horde, sowie die Errichtung der [[Baron Revilgaz]] Statue in der Bucht und der Verpflichtung aller [[Goblins]], die ihm folgten zu Beutebucht Haudraufs, ist nirgendwo schriftlich hinterlegt und lebt nur noch von Mund zu Mund Propaganda.\r\nBooty Bay wurde vor einigen Monaten in Beutebucht umbenannt um den Listen einiger [[Azeroth]]anischer Schmugglern entgegen zukommen, es hatte sich von[[Sturmwind]] aus eine Neubeschreibung der Städte ergeben und dies führte zu Chaos innerhalb der Transportlisten. Eingeborene und alteingesessene Anwohner meiden diesen Bürokratischen Fauxpas allerdings, Ein Aussenwelter gibt sich schnell zu erkennen wenn er den Terminus Beutebucht verwendet.\r\n==Persönlichkeiten==\r\n* [[Baron Revilgaz]] \r\n* [[Catelyn die Klinge]] \r\n* [[Chefingenieur Scooty]]\r\n* [[Crank Zischelbub]] \r\n* '''Deeg''' nennt das Leben auf See sein Leben. Wenn er in den Hafen kommt, sucht er sich eine gute Flasche Grog und sehr guten Schnupftabak. Er war sehr niedergeschlagen, als er herausfand, dass der Kräuterkundige nichts davon hatte. Seine Lieferung ist von den Räubern der [[Blutsegelbukaniere]] geklaut worden.\r\n* [[Drizzlik]]\r\n* [[Erster Maat Krazz]]\r\n* '''Fin Fizrackett''' hat sich mit Schlingendornfieber angesteckt, Einem tödlichen Virus. Das einzige Heilmittel wäre das Herz von Mokk dem Wilden zu essen. \r\n* [[Flottenmeister Seehorn]] \r\n* [[Glotz Widrikus]] \r\n* [[Kapitän Hecklebury Smotts]] \r\n* [[Kebok]]\r\n* '''Knirpsens''' war Smutje auf der \"[[Smotts' Revenge]]\" und hat den letzten Angriff überlebt. \r\n* [[Krazek]]\r\n* '''Landro Longshot''' - Landro Longshot in Beutebucht ist ein [[Goblin Zocker]], der u.a. die [[Reitschildkröte]] und den [[Astraler Begleiter|Astralen Begleiter]] verkauft. Es gibt Gerüchte - teils düster, teils freundlich - dass Landros Einfluss sich weit über die Arena des Spielens hinaus erstreckt. \r\n* '''Ruzzgot''' ist Karawanenführer aus Beutebucht und besitzt eine schmutzige alte - aber alle Transportwünsche erfüllende Karawane. \r\n* [[Seewolf MacKinley]] \r\n* '''Torkel Einauge''' hat seine Augen im Kampf verloren. Aber zum Glück haben sie in [[Menethil]] angelegt und ein reisender Hexer hat ein Spezialglasauge verzaubert, mit dem er wieder was sehen kann. Gestern Nacht hatten ihm aber [[Blutsegelbukaniere]] auf dem Weg nach Haus aufgelauert. Sie haben ihm sein Auge geklaut und er ist so gut wie nutzlos ohne sein verzaubertes Spezialauge.\r\n* '''Zitterhand Phillipe''' ist unten bei den Docks. Er schuldet [[Seewolf MacKinley]] eine Menge Geld aus Spielen. Er hat nur ein bisschen viel getrunken und sich verlaufen. \r\n \r\n'''Quellen'''",},
			["Beutebucht - Dein Alltag"] = { content = "''geschrieben von [[Zuul]]''\r\nDein Alltag. \r\nUnter deinen Füßen knirscht das morsche Holz der Planken wie ein jammernder Balg. Deine Rüstung klebt feucht und unangenehm an deiner Haut. Dein Streitkolben, bedeckt mit Blut,Rotz und Haar, hängt locker in der Schlaufe an deinem Gürtel. Ein Nachtelfe spricht dich an und beschwert sich über eine tote Käufliche in seiner Unterkunft. Du nickst , sagst ihm das du dich drum kümmerst und vergisst ihn. \r\nDeine Aufgabe ist es den Abfall zu beseitigen. Deine Aufgabe ist der Stumpfsinn einer Stadt der Scherben. \r\nDiese Stadt macht dich fett, sie macht dich träge. Diese Stadt tötet dich. \r\nIn der Gasse neben deinem Posten bedroht ein Gnoll eine Gnomin mit einer schartigen Klinge. Im Wasser vor dir treibt etwas das einer Hand verdächtig ähnlich sieht. Ein Weib schlägt ihren Balg mit solcher Gewalt das seine Wange sofort in Rot zu explodieren scheint Ein Traumstaubverrückter erbricht sich zwischen ein paar Schmugglerkisten, du brichst ihm die Beine und wirfst ihn vom Steg, die Schmuggler zahlen gut und haben Respekt vor der Tradition. \r\nDu bist das Recht. Du bist das Gesetz. Du bist ein Booty Bay Haudrauf . \r\nWillkommen in Booty Bay. \r\n----\r\nDein Alltag. \r\nDeine Welt ist ein schwammiges Gebilde aus Tönen und Farben. Deine Crew wurde zum verkac.kt vierten mal von einem Riesen gefre.ssen dessen Namen du nicht aussprechen kannst. Du kamst hierher als reicher Mann, du kamst als ein Mann mit Visionen und Hoffnungen. Deine Männer verrotten auf dem Grund des Meeres, deine Beute hast du in Schnaps und Fleisch aufgeweicht. Du hast keine Freunde , du hast Geschäftspartner, deine Freundschaften dauern solange wie ein Handschlag. Jeden Tag gehst du an der Kirche vorbei und denkst über einen Neuanfang nach, über die Erlösung. Du gehst weiter bis zu deiner Kirche, wo das Weihwasser deine Welt verblassen lässt und der Priester das Glas putzt. \r\nDu bist der Bodensatz der Welt. Du bist der Abschaum der Gesellschaft. Du bist ein Schmuggler ohne Gut. \r\nWillkommen in Booty Bay. \r\n----\r\nDein Alltag. \r\nDu lebst in dieser Stadt und im Dschungel. Du bist ein Angehöriger der ältesten Rasse dieser Welt und Anführer einer Armee von Verrückten und Monstern. Dein Wort kann dafür sorgen das ein Dutzend blutgieriger Irrer über einen Unschuldigen herfallen. Du hast mehr Kreaturen getötet als dein Leben Jahre zählt. Du hast alles gesehen, glaubst du. Du hast alles erlebt, glaubst du. \r\nDein Fleisch wurde von Mördern und Attentätern gejagt. Dein Schwert ist dir Bruder und Gott. Deine Rüstung ist deine Haut. Diese Stadt liegt dir weil sie dir ähnlich ist. Wären Orte Raubtiere, diese Stadt wäre eine Hyäne. \r\nDu bist ein Kriegermeister der Andere ausbildet und fördert. An diesem Ort bist du soviel wie jeder andere. Alles was zählt ist der Respekt. \r\nDu bist ein Häuptling. Du bist nur ein Troll. \r\nWillkommen in Booty Bay. \r\n----\r\nDein Alltag. \r\nDu hast die H.ure nicht umgebracht. Du hast das Kind nicht erwürgt. Du erzählst diese Lüge jedem der sie hören will und doch schauen sie dich mit diesem Blick an der dir verrät das sie es wissen, wissen was du bist. \r\nDu bist ein Mörder. Du bist in dieser Stadt weil sie zu jederzeit dunkel ist,egal wie hell die Sonne scheint. Deine Haut ist blaß weil du dich nur im Schatten bewegst, du gehst den Haudraufs aus dem Weg und überfällst nur wenn es unbedingt sein muss, Du überfällst jede Nacht ein Wesen, manchmal verlierst du etwas Blut, manchmal verliert das Wesen sein Leben. Dir ist es egal geworden, du bist hier um zu bleiben. Diese Stadt besitzt dich und das weisst du. \r\nDu bist abscheulich. Du bist ein Ausgestossener. \r\nWillkommen in Booty Bay. \r\n----\r\nDein Alltag. \r\nDu verkaufst dein Fleisch an jeden der genug bezahlt. Dein Leib ist der Tempel der Verlorenen. Du gibts ihnen Wärme bis das Gold nicht mehr reicht. Deine Liebe ist geborgte Zeit. Deine Zuneigung ist eine süße Lüge die man glaubt weil sie teuer war. Dein Gesicht ist durch Schnitte verunstaltet, du kennst eine Unzahl verschiedener Klingen. Das drückt den Preis, das ruiniert den Markt. \r\nDu hängst in Kneipen herum deren Kundschaft dich nur als Ware sehen. Deine Seele landet im Goldbeutel des nächsten Halunken. \r\nDu bist die Liebe. Du bist die Reinheit. \r\nWillkommen in Booty Bay. \r\n----\r\nBooty Bay lächelt dich mit ihren ockergelben Zähnen an wenn sie morgens die Leichen aus den Zahn zwischenräumen puhlt. Sie winkt dir zu mit blutigen Händen. Sie singt bezaubernd über den Schmutz und das Leid. Ihre Stimme betört dich. Ihre Erscheinung faziniert dich. Ihre Klauen kriegen dich. \r\nWillkommen in Booty Bay ,Wanderer. Richte dich ein du wirst diesen Ort nie mehr verlassen.",},
			["Bewahrer Bel'dugur"] = { content = "'''Bewahrer Bel'dugur''' ist ein Mitglied des [[Schattenhammerkult]]s und hält sich im Apothekarium von [[Unterstadt]] auf. Er ist auf der Suche nach dem [[Buch von Ur]], das man für ihn beschaffen soll, denn diese Studien anderer Welten sind von großem Wert für die Mitglieder des Schattenhammerkults unter den Verlassenen. Als einer der Höchstgebildeten des Kultes bewahrt und sucht er nach verbotenem Wissen. Und so studiert er wertvolle Bücher, wie z.B. ein Exemplar von [[Yagyins Zusammenstellung]], das [[Theldurin der Verirrte|Theldurin dem Verirrten]] im [[Ödland]] gern in die Finger bekommen würde. Aber wer an Bel'dugurs Wissen teilhaben möchte, sollte ihm helfen, drei weitere mächtige Gegenstände zu beschaffen, die er braucht. Er darf die Namen dieser Gegenstände nicht aussprechen, aber er wird sie aufschreiben. Wenn man das schafft, ist man wahrlich würdig, ein eigenes Kapitel über den Orden zu beginnen. Bei den gewünschten Artefakten handelt es sich um den [[Stern von Xil'yeh]], die [[Hand von Dagun]] und Das [[Herz des Vermächtnisses]].",},
			["Bewahrer der Lehren von Norgannon"] = { content = "Der Bewahrer der Lehren von Norgannon ist ein [[Steinwächter]], der in der Halle der Handwerker in [[Uldaman]] anzutreffen ist. Seine Aufgabe besteht darin, Abenteurern Zugang und, falls erlaubt, auch Einblick in das Werk der Schöpfer zu gewähren, die für die Welt [[Azeroth]] die [[Irdene]]n geschaffen haben. Er kann Wissensdurstigen diese Dinge anvertrauen, wenn sie bereit dafür sind. Die Schöpfer sind sich der Fülle der in seinem Speicher enthaltenen Angaben bewußt. Folglich wird dem Wissensdurstigen eine tragbare Ausgabe der in ihm gespeicherten Daten zur Verfügung gestellt, sobald man sich mit dem [[Scheiben von Norgannon]] vertraut gemacht hat. Man kann bei Bedarf nach seinem Vortrag auf die [[Scheiben von Norgannon]] zugreifen, um mit der Synthese zu beginnen.",},
			["Bewahrer des Heiligen Lichts"] = { content = "In [[Khaz Modan]] und [[Azeroth]] verkünden selbstlose [[Priester]] die Botschaft vom [[Heilige Licht]], um ihren Anhängern Hoffnung und Glauben zuteil werden zu lassen. Besessen von dem Gedanken, dass das Böse in jedem sterblichen Geschöpf lauert, sind sie ausgezogen, die Seelen der [[Menschen]] von Korruption und Dunkelheit zu reinigen. Als Bewahrer des [[Heiliges Licht|Heiligen Licht]] können sie die positiven Energien dieser göttlichen Macht kanalisieren, die Verletzungen ihrer Kameraden heilen oder sogar die Wahrnehmung anderer beeinflussen. Sie nutzen ihre vom Licht verliehenden Kräfte, um den Völkern der [[Allianz]] in den schweren Zeiten des Krieges beizustehen. \r\nDer Einsatz körperlicher Gewalt gehört nicht zum Auftrag des heiligen Ordens. Doch endlose Jahre des Krieges und des Leides haben die Geistlichen gelehrt, dass die Horde durch Glauben allein nicht besiegen kann. Wohlwissend, dass der Krieg mit diesen barbarischen Völkern kein baldiges Ende nehmen wird, haben sich die [[Priester]] mit den Werkzeugen des Krieges gerüstet. Obgleich sie gezwungen waren, sich auf ihre Verteidigung zu besinnen, ist die Heilung der menschlichen Seele doch ihre eigentliche Berufung. \r\nEs ist das Hauptanliegen eines jeden [[Priester]]s, seinen Brüdern und Schwestern Trost und Halt zu geben. Die geistige Führung des Ordens sorgt dafür, dass die Soldaten der [[Allianz]] das Ziel eines dauerhaften Friedens nicht aus den Augen verlieren.",},
			["Bewahrer Ordanus"] = { content = "Ordanus ist ein [[Hüter des Hains]], ein Halbgott der [[Nachtelfen]] und einer der ältesten Söhne des Waldgottes [[Cenarius]]. Die [[Nachtelfen]] haben ihn aus dem Wipfel von [[Rajenbaum]] in [[Eschental]] geschleust und versteckten ihn, bevor der [[Schattenrat]] ihn finden konnte, aber ihm läuft langsam die Zeit davon.",},
			["Bewahrer Remulos"] = { content = "Bewahrer Remulos ist ein [[Hüter des Hains]] und als einer der Söhne von [[Cenarius]] ein Druide von großer Macht und der Bruder von [[Zaetar]]. Zu seinen Kindern zählen [[Celebras]], [[Cavindra]] und mehrere [[Dryade]]n.\r\nEr befindet sich im Schrein von Remulos in der Nähe von [[Nachthafen]] und wacht über die [[Mondlichtung]], das geheiligte Zentrum der druidischen Studien. Er ist ebenso ein wichtiges Mitglied des [[Zirkel des Cenarius]], doch befindet er sich in einem anwachsenden Konflikt mit dem Erzdruiden [[Fandral]] Hirschhaupt. Denn entgegen Hirschhaupts Wünschen, hieß Remulos die [[Tauren]] im [[Zirkel des Cenarius]] willkommen und lehrte sie viele streng gehütete Geheimnisse. Remulos stellte sich ebenso vehement gegen die Erschaffung des neuen Weltenbaumes [[Teldrassil]], den er lediglich als selbstsüchtige Geste der [[Nachtelfen]] sah, die begierig darauf waren, ihre Unsterblichkeit zurückzugewinnen.",},
			["Bibbers"] = { content = "'''Bibbers''' ist ein Mensch, der sich auf dem [[Friedhof von Rabenflucht]] im [[Dämmerwald]] versteckt hält. Er ist eine nervöse, hektische Person, die [[Dunkelhain]] verließ und nach Westen ging. Nun versteckt er sich seit Wochen in dieser Geisterstadt, und die ganze Zeit hat er nichts gegessen außer Maden und Unkraut. \r\n==Bibbers vollendetes Tagebuch==\r\nBibbers vollendetes Tagebuch beschreibt sehr genau, was auf [[Svens Hof]] passierte. Es beschreibt wie Bibbers in [[Rolands Verdammnis]] die [[Sense von Elune]] fand und damit unwissentlich die [[Worgen]] nach Dämmerwald beschwor. Das Buch erklärt damit die Hintergrundgeschichte, warum sich Dämmerwald in seinem verfluchten Zustand befindet. \r\n===Inhalt===\r\nMein Tagebuch \r\nDer Schrecken der vergangenen Wochen ist so schlimm, dass ich daran zu zerbrechen fürchte. Vielleicht hilft es mir, nicht dem Wahn zu verfallen, indem ich das unsähliche niederschreibe. Vielleicht ist es so etwas wie eine Beichte gegenüber einem stillen Gefährten oder eine Befreiung meiner Seele von dieser Gedankenpein, indem ich sie auf Papier banne. Ich habe zuvor bereits einmal ein Tagebuch geführt. Doch befindet es sich jetzt an einem Ort, an den ich nicht zurückkehren kann. Also beginne ich von Vorn. Aber dieses Mal beginne ich ganz am Anfang. \r\nAlles begann mit dem Fund dieser verfluchten Sense in der Mine mit dem bezeichnenden Namen [[Rolands Verdammnis]]. Ja, damit fing alles an. Davor war die Bruderschaft der [[Defias]] mit unserem Vorankommen im Dämmerwald ganz zufrieden. In der Zeit vor der Sense war dies hier ein ebenso friedlicher Ort wie etwa das [[Nordhain]]tal. Aber seit ich den Griff dieser verdammten Sense aus dem Schutthaufen in der Mine ragen sah und es prompt nicht lassen konnte, sie - verflucht sei ich! - auch noch herauszuziehen, ist Rolands Verdammnis ein Ort des Todes! Hätte ich geahnt, was passieren würde, ich hätte mir lieber die rechte Hand abgehackt, als dieses runenverzierte Holz anzufassen! So viel Gejammer! Bislang hielt ich das immer für ein Vorrecht der Alten. Jetzt weiss ich, dass es nicht die Alten sind - die Hoffnungslosen sind es, die den Mantel des Bedauerns tragen müssen, weil sie ihn nicht von ihren gramgebeugten Schultern streifen können oder wollen. Aber Schluss jetzt mit diesem traurig triefenden Tiefsinn! Ich muss mit der Chronik weitermachen... \r\nNachdem ich die Sense herausgezogen hatte, lief ein kleines Beben der Veränderung durch die Mine. Das Licht unserer flackernden Fackeln verzerrte sich und wir schienen unsere Stimmen nicht mehr unter Kontrolle zu haben. Manchmal donnerte das Flüsterm eines Mannes so laut durch die Gänge, dass wir uns die Ohren zuhalten mussten. Und dann wieder hörte man laute Rufe keine zwei Schritte weit. Das raubte uns die Nerven. Aber wir hatten ohnehin nicht viel Zeit uns darüber aufzuregen. Denn das Schlimmste stand uns ja noch bevor; die Worgs. \r\nSie stürtzen sich von allen Seiten auf uns, kamen aus versteckten Löchern zu unseren Füssen oder liessen sich von Oben lautlos auf uns herabfallen. Die Hälfte der Männer fiel schon in diesen ersten panikerfüllten Minuten. Der Rest - darunter auch ich - versuchte zu fliehen. Ich rannte und hörte von allen Seiten, wie meine Brüder von Klauen und Zähnen zerrisen wurden. Ich hörte unzählige Schreie, die abrupt verstummten oder in einem Gurgeln erstarben. Nach Allem, was ich weiss, bin ich der einzige Mensch, dem die Flucht von diesem Ort gelang. Ich kann nur raten, warum ich diese Nacht überlebt habe. Ich war immer schon vorsichtig, bin Schlägen ausgewichen und habe einen Bogen um Fallgruben gemacht. Daher kommt auch mein Spitzname Bibbers. Vielleicht war es also dieser Hang zur Vorsicht der mich gerettet hat.... \r\nOder es war tatsächlich diese Sense, die ich aus dem Geröll gezogen habe. An der Sense selbst kann es indes nicht liegen, denn die habe ich während meiner panischen Flucht verloren. Aber wenn ich es war, der die Worgs in den Dämmerwald führte, so haben sie mir vielleicht einen seltenen Gefallen getan. Verflucht sollen sie sein. Aber vielleicht bin ich auch dazu verurteilt zuzusehen, was durch mich aus dem Dämmerwald werden wird. Vielleicht ist es mein Schicksal zuzusehen, wie die Worgs in dieses Land strömen, um es noch finsterer zu machen als es ohnehin schon ist. Sollte dies so sein, so ist es doppelt schlimm. Denn die Worgs sind nicht die einzige Macht, die nach dem Dämmerwald greift - auch die Satanskreaturen vom [[Gebirgspass der Totenwinde]] wollen das Land. Dies ist das nächste Kapitel meiner Geschichte und ich bete, dass es das letzte ist.... \r\nNach meiner glücklichen Flucht aus Rolands Verdammnis versteckte ich mich im Heuschrober eines Mannes mit Namen Sven. Ich verbrachte dort mehrere Tage und war dabei noch so voller Furcht, dass ich mich Sven und seiner Familie nicht ein einziges Mal zeigte. Aber aus dem, was ich von meinem Versteck aus sah, konnte ich schliessen, dass es sich bei diesen einfachen Bauern um anständige Leute handelte. Hätte ich meinen Unterschlupf verlassen, wäre ich von diesen Leuten sicher mit offenen Armen aufgenommen worden. Aber Vertrauen zu fassen fällt mir schwer - und seit dem Schreck in der Mine umso mehr. Also hielt ich mich weiter verborgen. Das rettete mir das Leben. Einige Tage nach meiner Ankunft an der Scheune verliess Sven seinen Hof mit Ziel Dunkelhain. Er küsste seine Frau, lächelte seine Kinder an und versprach, bald mit Spielsachen und Süssigkeiten zurück zu sein. Der Arme Mann. Es sollte das letzte Mal sein, dass er seine Familie lebend sah. Wenigstens haben sie glücklich voneinander Abschied genommen. Und wenigstens starb seine Frau als Erste und musste den Tod ihrer Kinder nicht mit ansehen. Aber mir ist das kein Trost. Ich habe gesehen, was geschah. Und es wird mich mein Leben lang verfolgen. \r\nMeine Hand zittert, wenn ich mich an jene Nacht erinnere, als Sven fort und seine Familie allein den schwarzen Reitern ausgeliefert war. Wieder mache ich mir Vorwürfe, denn ich war dort und hätte mich gegen jene Satanskreaturen vom Gebirgspass der Totenwinde erheben können. Aber Bedauern ist nicht wahrhaftig. Es ist das Bedauern, wie es jeden plagt, der eine Tragödie überlebt hat. Ich weiss, hätte ich mein Versteck verlassen, so wäre ich auch getötet und meine Leiche bis zur Unkenntlichkeit verstümmelt und in alle Himmelsrichtungen verstreut worden. \r\nAber auch wenn ich weiss, dasss ich diesen schändlichen Mord nicht hätte verhindern können, einen Vorwurf kann ich mir nicht ersparen: Ich habe die schwarzen Reiter zu [[Svens Hof]] geführt. Meine Entdeckung der Sense hat nicht allein die Worgs auf den Dämmerwald losgelassen, sondern auch die Reiter vom [[Gebirgspass der Totenwinde]] herangelockt. Das weiss ich genau, denn unmittelbar vor dem Mord stellten sie Svens Frau eine Frage, während sie ihre Kinder umklammert hielt und ihnen im Angesicht des nahen Todes wenigstens ein wenig Trost spendete. Die [[Sense von Elune]], schrie einer der Reiter laut und schrill. Seine Stimme klang, als würde eine Axt an einem Stein geschliffen. Und das letzte Wort - Elune - krächzte er, als würde er daran ersticken. Furcht ergriss mich, als ich diese Stimme hörte. Aber nicht allein ob ihres Klangs, nein ... ich wüsste, von welcher Sense der Reiter sprach. Es musste sich um das verfluchte Ding handeln, dass ich ein paar Tage zuvor unter den Steinen in Rolands Verdammnis hervorgezogen hatte. Danach suchten die schwarzen Reiter! Und deswegen musste Svens Familie sterben... \r\nIch habe nie erfahren, wie Svens Frau eigentlich hiess. Ihr Mann und ihre Kinder nannten sie stets nur „Liebste“. „meine Liebe“ oder „Mami“. Aber ich wünschte, ich wüsste ihren Namen. Denn ich bin der Einzige, der ihre Tat an jenem Tag noch bezeugen kann. Und obschon sie nur eine Bauersfrau war, habe ich nie einen Mann oder eine Frau so mutig und beherzt handeln sehen. Natürlich wusste sie nichts von der Sense, aber als sie begriff, dass die Reiter danach suchten, fasste sie spontan einen Entschluss. Einen kühnen und klugen noch dazu. Nur aufgegangen ist er nicht. „Die Sense?“ Fragte sie ganz ruhig. „Natürlich weiss ich, wo sie ist. Wer hier wüsste das nicht?“ Sie blickte die Reiter vollkommen ruhig an und, hätte ich nicht genau gewusst, dass sie von der Sense nichts ahnen konnte, ich hätte geschworen, sie sagte die Wahrheit. Ihr Wagnis schien sich auch auszuzahlen. Derselbe Reiter, der eben schon die Frage gestellt hatte, neigte den Kopf leicht zu ihr herunter und kreischte: „Wo?“ \r\n„Ich werde euch führen. Euch alle“. Erwiderte sie und ich konnte einen kleinen Hoffnungsschimmer in ihren Augen sehen. „Aber es ist ein weiter Weg und meine Kinder wären uns nur hinderlich. Wir müssen sie hier lassen“. Ihr Trick war einfach. Aber sind es nicht die einfachen Tricks, die die grösste Aussicht auf Erfolg haben? Wenn alles gut ging, würde sie die Reiter vom Hof weglocken. Sie selbst wäre verloren, aber ihre Kinder gerettet. Und es würde klappen, solange nur die Reiter ihren Lügen Glauben schenkten. Ich war nie ein grosser Anhänger des Lichts. Aber in diesem Augenblick betete ich inbrünstig für Svens Frau, die sich so tapfer gegen die schrecklichen Reiter stellte. „Bitte!“, betete ich. „Lass sie darauf hereinfallen!“ \r\nDie Reiter standen still, wie versteinert. Und sie begegnete ihren Blicken mit aller Ruhe. Dann sah einer der Reiter auf, als höre er einen Ruf aus der Ferne. Er nahm einen kleinen Edelstein aus der Satteltasche. Damit machte er eine Geste in Richtung der Frau. Ein Licht kroch von dem Reiter aus auf die Frau zu und verformte sich zu einer unerbittlichen weissen Hand. Sie starrte scheinbar unberührt in das Licht. Aber ich sah die Unsicherheit hinter der Fassade des Selbstvertrauens. Als die Hand sie erreicht hatte, griff sie mit langen Fingern nach dem Kopf der Frau. Und drückte zu. Svens Frau stand steif wie ein Brett da und ihre Augen weiteten sich. Sie öffnete den Mund zu einem Schrei, brachte aber keinen Ton heraus. Nach einigen Augenblocken grausamer Folter liess die Hand sie los und sie fiel auf die Knie. Der Reiter mit dem Schmuckstück sass aufrecht im Sattel und liess dröhnen vernehmen: „Diese Frau lügt“. Er sagte das mit einer Stimme, von der ich noch heute Alpträume bekomme. „Sie hat die Sense nie gesehen.“ \r\nDanach ließ der Reiter die Schultern sinken, als sei ein Geist aus ihm entwichen. Und dann sagte er mit der alten, schrillen Stimme von zuvor die todbringenden Worte: „Der Lord hat gesprochen. Tötet sie.“ Ich kann nicht beschreiben, was danach geschah. Ich habe es deutlich vor Augen. Aber meiner elenden Seele ist es immer noch nicht möglich niederzuschreiben, was sich in den folgenden, grausigen Minuten ereignete. Ich kann nur schreiben, dass Svens Familie getötet wurde. Kurz darauf kehrte Sven an den Schauplatz des Schreckens zurück. Er war derart von Trauer übermannt, dass ich Angst hatte, mich ihm zu zeigen. Und ich fürchtete mich sogar davor, dass er mich finden würde, und floh aus meinem Versteck in der Scheune. Ich weiss nicht, wo Sven jetzt ist. Aber ich bete, dass er eines Tages Frieden findet. \r\nIn den darauf folgenden Wochen blieb ich aus Angst vor den Reitern nie allzu lange an einem Ort. Augenblicklich befinde ich mich in der verlassenen Stadt Rabenflucht und wie immer verstecke ich mich. Ich weiss nicht, welche Kräfte sie gegen Svens Frau eingesetzt haben. Aber ich weiss, dass ich gegen diese Kräfte nichts ausrichten kann und dass sie den Dämmerwald auch weiterhin nach der Sense absuchen. Ich habe die Sense nicht mehr und ich danke dem Licht dafür, denn hätte ich sie noch, hätten sie mich längst gefunden. Aber auch so weiss ich tief in meinem Herzen, dass sie mich finden werden. Ich bin so müde...",},
			["Biokuppel"] = { content = "Die gigantischen Biokuppeln im [[Nethersturm]] auf der [[Scherbenwelt]] wurden von den [[Astrale]]n des [[Konsortium]]s errichtet, um das öde Land fruchtbar zu machen.\r\nDoch die bösartigen Bedingungen und Kreaturen des [[Nethersturm]]s haben begonnen, die Ausrüstung, die die Biokuppeln aufrecht erhält, zu zerstören. [[Das Konsortium]] muss die Funktionalität der Kuppelgeneratoren genau im Auge behalten. Wenn die Felder immer instabiler werden, können sie ihre Auswirkungen auch immer schwerer kontrollieren. Das könnte ein Desaster für die Expedition und alles, was sich in den Kuppeln befindet, bedeuten. \r\nEine Gruppe von \"[[Druide]]n\" aus [[Azeroth]] interessiert sich für die Wirkung der Biokuppeltechnologie: Der [[Zirkel des Cenarius]] ... und natürlich wittert das Konsortium großen Profit.\r\nIn den Biokupppeln gedeihen auch Manabeeren aus denen der [[Goblin]][[Der Rok]] im unteren Viertel [[Shattrath]]s eine seiner Delikatessen zubereitet. Bringt ihm 15 Stück und er wird euch belohnen.\r\n==Bekannte Biokuppeln==\r\n* [[Biokuppel Fernfeld]] \r\n* [[Biokuppel Mittelreich]]\r\n* [[Biokuppel Sutheron]]\r\n* [[Sturmsäule]]",},
			["Biokuppeln"] = { content = "#REDIRECT [[Biokuppel]]", redirect = "Biokuppel",},
			["Biokuppel Fernfeld"] = { content = "Die Biokuppel Fernfeld ist eine abgelegene Gegend nordöstlich der Sturmsäule, in der Nähe des [[Netherstein]]s. Die [[Astrale]]n des [[Konsortium]]s haben ein Muster in den Schäden an den Schildgeneratoren hier entdeckt. Wichtige Teile der Generatoreinheiten sind an verschiedenen Orten verschwunden. Das ist kein Zufall, kein technischer Fehler. Sie werden bestohlen. Man hat hier schon viele merkwürdige Dinge gesehen, darunter auch ein paar Mutationen, die einst ganz normale Tiere waren, z.B. den Raptor [[Tyrantus]] - diese übergroße Echse war schon das Leid vieler [[Orcs]]. \r\n==Personen==\r\n* '''Tashar''' ist Techniker und möchte für seine Reparaturen Freie Bahn haben. Er will deshalb, dass man die Sichelzahnraptoren tötet.",},
			["Biokuppel Mittelreich"] = { content = "Sie '''Biokuppel Mittelreich''' ist eine der vom [[Konsortium]] gebauten [[Biokuppeln]] im [[Nethersturm]]. Wie auch in anderen Biokuppeln, haben die bösartigen Bedingungen und Kreaturen des [[Nethersturm]]s begonnen, die Ausrüstung, die diese Biokuppel aufrecht erhält, zu zerstören, besonders den Generator im Osten. Das Konsortium muss die Funktionalität der Kuppelgeneratoren genau im Auge behalten, denn wenn die Felder immer instabiler werden, können sie ihre Auswirkungen auch immer schwerer kontrollieren. Und das könnte ein Desaster für die Expedition und alles, was sich in den Kuppeln befindet, bedeuten. Man hat Teile der Schildgeneratoren der Biokuppel auf dem Grund des kleinen Sees im Norden gesehen und man ist sich auch nicht sicher, warum sich die Krokilisken für die Ausrüstung interessieren. Aber [[Das Konsortium]] ist sich in dieser Sache einig: Wenn es zu einer Entscheidung zwischen der Ausrüstung und Krokilisken kommt, müssen die Tiere gehen. \r\n==Personen==\r\n* '''Gahruj''' - Gahruj vom [[Konsortium]] hat einige \"Probleme\" damit, Waren von den [[Blutelfen]] zurückzufordern, die sie nicht bezahlen wollen. Die [[Blutelfen]] weigern sich, die Waren, die ihnen schon geliefert wurden, zu bezahlen. [[Nexusprinz Haramad]] hat zu verstehen gegeben, dass er seinen Besitz unverzüglich und persönlich zurückerhalten möchte. \r\n* '''Mama Mauschel''' - Mama Mauschel möchte den Müll eines [[Dämonen]] sammeln und [[Verdammnisklaue]] die Krallen stutzen. Außerdem muss [[Raketenchef Doppeldecker]] in [[Area 52]] gewarnt werden, dass die [[Brennende Legion]] hinter ihnen her ist.\r\n* '''Mehrdad''' - Mehrdad vom [[Konsortium]] braucht die Untersuchungsergebnisse der Diagnose der Biokuppel, denn [[Meisteringenieur Ghabar]] in der [[Sturmsäule]] möchte sicher die Ergebnisse der Diagnose erfahren. Danach muss er nur noch die Saboteure ausschalten. Er hat auch gehört, dass eine Gruppe von ‘Druiden’ aus Azeroth, der [[Zirkel des Cenarius]], sich für die Wirkung der Biokuppeltechnologie interessiert. Er teilt den Gewinn, wenn man ihm ein paar der Kräuter für seine erste Lieferung sammelt. Er bekommt eine Menge Geld für [[Elfenbeinglocke]]n, die eine der unspektakulärsten Blumen in den Kuppeln ist.\r\n* '''Shauly Pore''' - Shauly Pore wurde von [[Area 52]] hierher geschickt, um die Technologie, die die [[Astrale]]n in ihren Biokuppeln einsetzen, zu bewerten. Sie wurden darum gebeten, wo es nur geht andere Völker als [[Goblins]] als Spione einzusetzen. Zusammen mit Audi der Nadel bei der Sturmsäule bildet er das dynamische Duo und kümmert sich darum, einige Waren zurückzuholen, z.B. Reißzahnpelze.",},
			["Black Tooth Grin Klan"] = { content = "#REDIRECT [[Orcs der Black Tooth Grin]]", redirect = "Orcs der Black Tooth Grin",},
			["Blastenheimer 5000 Ultrakanone"] = { content = "Die '''Blastenheimer 5000 Ultrakanone''' ist eine Attraktion auf [[Dunkelmonds Jahrmarkt]]. Es handelt sich hierbei um eine hochmoderne Abschussanlage für Einzelpersonenprojektile. Die von dieser Kanone abgefeuerte Ladung erreicht beinahe die Geschwindigkeit eines Drachen und sie ist der ganze Stolz der gesamten Blastenheimerfamilie, die auf der ganzen Welt für ihre Leistungen in den Bereichen der Luftfahrt und Brennstoffe berühmt ist. Wenn man auch einmal frei wie ein Vogel durch die Lüfte gleiten will, sollte man Maxima Blastenheimer aufsuchen. \r\n'''Quellen'''",},
			["Blauer Drachenscharm"] = { content = "#REDIRECT [[Blauer Drachenschwarm]]", redirect = "Blauer Drachenschwarm",},
			["Blauer Drachenschwarm"] = { content = "Der blaue Drachenklan, der von [[Malygos]], dem Lord der Magie, angeführt wird, wurde von dem bösen [[Todesschwinge]] und seinem [[Schwarzer Drachenschwarm|schwarzen Drachenklan]] fast ausgerottet. Doch auch wenn es nur noch wenige große Blaue [[Drachen]] auf der Welt gibt, sind ihre Kräfte Ehrfurcht gebietend. Aus [[Nordend]] stammend bleiben die wenigen blauen [[Drachen]] vergleichsweise nah bei der großen [[Drachenfäulnis]], wo sie mit den uralten Drachengeistern kommunizieren, die in vergangenen Zeiten starben. Ihr eiskalter Atem und die riesigen Klauen wurden manch unglücklichem Reisenden in Nordend zum Verhängnis.\r\n==Berühmte Blaue Drachen==\r\n* [[Arcanagos]]\r\n* [[Arygos]]\r\n* [[Azuregos]]\r\n* [[Azurous]]\r\n* [[Kalecgos]]\r\n* [[Tyrigosa]]\r\n* [[Zaubermaul]]\r\n==[[Malygos]]==\r\n[[Malygos]], der älteste unter den Aspekten, gebietet über die Kräfte der Magie und hat sich mit seinen blauen [[Drachen]] nach [[Nordend]] zurückgezogen. [[Norgannon]], der [[Titanen]] Meistermagier und Bewahrer des Wissens, gewährte dem Blauen [[Drachen]] [[Malygos]] einen Teil seiner ausgedehnten Kraft. Danach wurde [[Malygos]] als Der Zauberbinder, der Wächter der [[Magie]] und verborgenen Arkanums bekannt... [[Malygos|(mehr)]]",},
			["Blaue Drachenschwarm"] = { content = "#REDIRECT [[Blauer Drachenschwarm]]", redirect = "Blauer Drachenschwarm",},
			["Blaulaubknollen"] = { content = "Blaulaubknollen gelten auf der ganzen Welt als Delikatesse. Aber sie sind rar, sehr rar. Man findet sie nur im Brachland, tief in der Erde im [[Kral der Klingenhauer]]. Und selbst dann sind sie fast nicht zu finden, wenn man nicht weiß, wo man suchen muss. Darum hat [[Mebok Mizzyrix]] in [[Ratschet]] einen Schnüffelnasenziesel abgerichtet, damit sie sie für ihn aufstöbern. Sie haben unheimlich empfindliche Nasen und riechen eine Knolle aus fünfzig Schritt Entfernung.",},
			["Bleichborken"] = { content = "#REDIRECT [[Trolle der Bleichborken]]", redirect = "Trolle der Bleichborken",},
			["Blizzard Entertainment"] = { content = "'''Blizzard Entertainment''' ist ein bedeutender Entwickler und Vertreiber von Unterhaltungssoftware. Nach ihrer Gründung im Jahr 1994 wurde die Firma schnell zu einem der bekanntesten und angesehensten Hersteller von Computerspielen. Durch die Konzentration auf gut entworfene und höchst unterhaltsame Softwareerlebnisse hat Blizzard sich seit seiner Gründung einen beispiellosen Ruf für die hohe Qualität seiner Produkte erworben. Blizzards Arsenal an aufeinanderfolgenden, die Verkaufscharts stürmenden Nummer-1-Hits umfasst mehr als ein Jahrzehnt und Welterfolge wie [[World of Warcraft]], [[Warcraft III - Reign of Chaos|Warcraft III: Reign of Chaos]], Diablo II, und StarCraft bescherten ihren Entwicklern unzählige Auszeichnungen für das Spiel des Jahres. Zusätzlich ist Blizzards Online-Spiele-Dienst, das Battle.net, einer der weltweit größten kostenlosen Dienste und wird von Millionen aktiven Spielern genutzt.\r\n'''Quelle:'''",},
			["Blutaugenklan"] = { content = "==Allgemeines==\r\nDer '''Klan des Blutenden Auges''' war vor dem Übergang der [[Orcs]] einer der größten Stämme auf [[Draenor]] gewesen. Wegen seiner Kämpfe gegen die Streitkräfte [[Azeroth]]s und der [[Allianz]] während der beiden Kriege erlangte der Klan einen legendären Ruf. Für seine schlachterprobten Krieger, die vor allem dem [[Schwarzfels Klan]] eng verbunden waren, hatten die Interessen der [[Horde]] immer Vorrang vor allem anderen. Doch der Klan des Blutenden Auges auf [[Draenor]] hat seine noble Herkunft verraten. Die [[Orcs]] des Klans aus [[Azeroth]]s, die gekämpft haben und gestorben sind, um den Stamm vor der Verderbtheit [[Mannoroth]]s zu schützen, sehen in ihren bösen Vettern nur Schwäche und Unwürdigkeit. \r\nIn den Schlachten mit den [[Höllenorcs]] des Blutenden Auges haben die [[Menschen]] der Ehrenfeste Schmuckstücke mit magischen Kräften bei ihnen gefunden. Diese [[Orcs]] haben die Insignien der gefallenen Soldaten der Ehrenfeste gesammelt und verfluchte Talismane aus ihnen gemacht. Sie befürchten, dass die schwarze Magie des Blutenden Auges die Insignien in böse Amulette verwandelt hat, die sie gegen sie einsetzen können. Ihre Hexenmeister benutzten einen Verfluchten Kessel bei [[Zeth'Gor]], um das Blut des Blutenden Auges in gekochtes Blut zu verwandeln. \r\n==Persönlichkeiten==\r\n* [[Grillok Finsterauge]] ([[Höllenorcs]])\r\n* [[Jorin Totauge]] ([[Horde]]) \r\n* [[Kilrogg Totauge]]\r\n* [[Worgmeister Kruush]]\r\n==Geschichte==\r\n===Die Kriege der Orcische Horde === \r\n[[Kilrogg Totauge]] führte seinen Klan als ersten durch das [[Dunkle Portal]] nach [[Azeroth]], und sollte die [[Horde]] zu einem schnellen Sieg über die [[Menschen]] leiten. Der Angriff auf Burg Sturmwind wurde jedoch zu einer Katastrophe, und sein Stamm und der Schattenhammer Klan wurden in das Sumpfgebiet, in dem sich das Portal befand, zurückgedrängt. Weitere Klans folgten den beiden Stämmen nach [[Azeroth]] und bereiteten sich auf einen Krieg gegen das Königreich der [[Menschen]] vor. Im folgenden [[Der Erste Krieg|Ersten Krieg]] entfesselte der Klan die ganze erbarmungslose Wildheit, die es den Orcs möglich machte, über fünf Jahre lang siegreich Krieg zu führen. Während des Zweiten Krieges leitete der Stamm den Betrieb der Raffinerien im besetzten [[Khaz Modan]], die für den Aufbau der mächtigen orcischen Seestreitmacht von großer Bedeutung waren.\r\n===Unter Ner’zhuls Banner===\r\nNach der Niederlage der [[Horde]] im Zweiten Krieg konnte Kilrogg einer Gefangennahme durch die [[Allianz]] entgehen und - dank der Unterstützung des Schamanen [[Ner'zhul]] - seinen Klan in Sicherheit bringen. Der Stamm setzte nach [[Draenor]] über und verbündete sich wieder mit den ursprünglichen Klans, die noch nie die Gegend um [[Azeroth]] gesehen hatten. Viele Mitglieder der alten Stämme verehrten die Krieger des Blutenden Auges als bedeutende Helden, da sich diese über dreißig Jahre im Land der [[Menschen]] aufgehalten hatten. Der Klan des Blutenden Auges half [[Ner'zhul]] einige magische Gegenstände aus [[Azeroth]] zu holen, und den Übergang in andere Welten zu ermöglichen. Die [[Horde]] überraschte die Verteidiger der [[Allianz]] und zog plündernd durch das Land. Die [[Orcs]] sammelten in kurzer Zeit die benötigten Artefakte ein und flohen zurück ins sichere [[Draenor]], aber die Streitkräfte der [[Allianz]] folgten ihnen. Mit den magischen Artefakten gelang es [[Ner'zhul]] tatsächlich, Portale zu anderen Welten zu öffnen. Jedoch begann die riesige Energie der Portale die Heimatwelt der [[Orcs]] bis in den innersten Kern zu erschüttern und auseinander zu reißen.\r\n===Ein neues Schicksal === \r\nAls [[Kilrogg Totauge]] und [[Grom Höllschrei]] vom [[Kriegshymnenklan]] erkannten, dass [[Ner'zhul]]s größenwahnsinnige Pläne ihr ganzes Volk dem Untergang preisgegeben hatten, scharten sie die verbliebenen [[Orcs]] um sich und flohen nach [[Azeroth]], wo sie vor der Zerstörung [[Draenor]]s sicher waren. Nachdem die Kriegshäuptlinge sich mit der Macht der Verzweiflung einen Weg durch die Reihen der [[Menschen]] erkämpft hatten, explodierte plötzlich das [[Dunkle Portal]] hinter ihnen. Für sie und die anderen [[Orcs]] auf [[Azeroth]] gab es nun kein Zurück mehr. Zwar konnten [[Grom Höllschrei]] und der [[Kriegshymnenklan]] sich einer Gefangennahme durch die [[Menschen]] entziehen, aber der Klan des Blutenden Auges wurden eingekesselt und in die Internierungslager von [[Lordaeron]] gebracht. Viele Jahre später, als [[Thrall]] die bewachten Lager zerstörte, wurde auch der Klan des Blutenden Auges wieder befreit und schlossen sich der neuen [[Horde]] an.",},
			["Blutbeere"] = { content = "Die '''Blutbeere''' ist in vielen Regionen Azeroths ein wildes Gewächs und wurde sehr lange als lästig empfunden. [[Mar'nah]] im Hafen der Sonnenweiten auf der [[Insel von Quel'Danas]] hat jedoch herausgefunden, dass die Pflanze, wenn sie den Kräften des [[Sonnenbrunnen]]s ausgesetzt wird, besondere Eigenschaften annimmt, die destilliert und anschließend als [[Blutbeerenelixier]] getrunken werden können, um die eigenen Fähigkeiten zu verstärken.",},
			["Blutbeeren"] = { content = "#REDIRECT [[Blutbeere]]", redirect = "Blutbeere",},
			["Blutbeerenelixier"] = { content = "Das '''Blutbeerenelixier''' ist ein einzigartiges Elixier aus [[Blutbeeren]]. [[Mar'nah]] im Hafen der Sonnenweiten auf der [[Insel von Quel'Danas]] hat vor kurzem das Rezept dafür entdeckt. Wenn die Blutbeeren destilliert und anschließend getrunken werden, können sie die eigenen Fähigkeiten verstärken.",},
			["Blutelf"] = { content = "#Redirct[[Blutelfen]]",},
			["Blutelfe"] = { content = "#REDIRECT [[Blutelfen]]", redirect = "Blutelfen",},
			["Blutelfen-Hexenmeister"] = { content = "'''Blutelfen Hexenmeister''' haben sich aus den [[Magister]]n entwickelt. Während sie mächtiger werden, geraten sie in Versuchungen und sie müssen stets daran denken die Kontrolle zu bewahren. Verderbnis kann jeden Ausübenden der arkanen Künste ereilen, besonders diejenigen, die sich mit den Kreaturen des wirbelnden [[Nether]]s beschäftigen. Sie müssen Geduld haben und vorsichtig sein ... aber sich in ihren Ambitionen nicht zu stark zurück nehmen. Wenn sie nicht allein bestehen, werden sie gewiss untergehen, denn zu einem Blutelfen Hexenmeister gehört viel mehr als den Fluss der Magie zu meistern. Ein guter Meister der Dämonen kann Tieren einen Grund zum Töten geben und die Angst, als Versager zurückzukehren.\r\n==Geschichte==\r\nSeit [[Quel'Thalas]] und [[Dalaran]] von der [[Brennende Legion|Brennenden Legion]] zerstört wurden, gibt es eine große Anzahl von abtrünnigen [[Blutelfen]] [[Magister]]n, die die Geheimnisse der Magie auf sich allein gestellt erforschen. Durch ihren Machthunger getrieben, begaben sich einige zu tief in die Fänge dämonischer Kräfte. Sie strebten danach, ihr Wissen über die Grenzen dessen hinaus zu erweitern, was die meisten anderen Zauberer für sicher oder moralisch akzeptabel halten. Sie waren besessen von dem Wunsch, alles über die Welt der Magie und ihre dunklen Wunder zu erfahren. Mit der Zeit verloren die [[Hexenmeister]] ihre Seelen an die Sucht nach den chaotischen Energien und wurden von einem unstillbaren Verlangen verzehrt. Sie gerieten in einen Sog schattenhafter Mächte, die außerhalb der Welt existieren. Die [[Brennende Legion]] nährt sie nun mit ihren Kräften, wodurch sie die zerstörerischen Energien der [[Dämonen]] kanalisieren können. Die Kunst, die mächtigen Abgesandten ihrer dunklen Meister herbeizurufen, war seit langem in Vergessenheit geraten, doch die Blutelfen Hexenmeister haben dieses Geheimnis erneut gelüftet. \r\n==Arten==\r\nBlutelfen Hexenmeister tragen je nach Ausrichtung und Zugehörigkeit folgende Bezeichnungen:\r\n===Bannzauberer===\r\nDie Bezeichnung Bannzauberer trugen hauptsächlich [[Hochelfen]] bei den [[Kirin Tor]]. Im Unterschied zu [[Magier]]n wiesen sie bereits einige Fähigkeiten der [[Hexenmeister]] auf, ohne dem dämonischen Einfluß verfallen zu sein. Bannzauberer wurden von den [[Kirin Tor]] oft im Kampf gegen dämonische Kräfte eingesetzt.\r\n===Beschwörer===\r\nAls Beschwörer oder auch ''Dämonenbeschwörer'' werden die [[Hexenmeister]] der [[Blutelfen]] bezeichnet. Ihr Hintergrund überschneidet sich zum Großteil mit der Entwicklung der [[Hexenmeister der Menschen]].\r\n===Nethermant===\r\nAls Nethermanten werden meistens [[Blutelfen Hexenmeister]] bezeichnet, die im [[Nethersturm]] in der [[Scherbenwelt]] unter dem Befehl von [[Kael'thas Sonnenwanderer]] bei den [[Manaschmieden]] arbeiten. Sie kanalisieren die Energie der [[Blutjuwelenkristall]]e in der Nähe der [[Manaschmieden]], um den Energiefluss der Schmieden zu stabilisieren. [[Blutelfen]] Nethermanten beschwören häufig [[Magie-Elementare]] als Begleiter zu ihrer Hilfe. Weitere Nethermanten findet man unter den [[Astrale]]n in den [[Wälder von Terokkar|Wäldern von Terokkar]] in der [[Knochenwüste]]. Diese werden als [[Astraler Nethermant]] bezeichnet. Zu den berühmten Nethermanten gehören u.a. [[Hochnethermant Zerevor]] und [[Nethermantin Sepethrea]].",},
			["Blutelfen"] = { content = "==Allgemeines==\r\n* '''auch bekannt als:''' [[Sin'dorei]]\r\n* '''Einzahl:''' Blutelf, [[Sin'dorei]]\r\n* '''Muttersprache:''' [[Thalassisch]]\r\nFür beinahe siebentausend Jahre pflegten die [[Hochelfen]] ihr strahlendes magisches Königreich, tief in den Wäldern des nördlichen [[Lordaeron]]. Vor fünf Jahren jedoch fiel die [[Geißel]] in [[Quel'Thalas]] ein und vernichtete die elfische Zivilisation beinahe völlig. Angeführt vom bösartigen Todesritter [[Arthas]], zerstörte die [[Geißel]] den geheimnisvollen [[Sonnenbrunnen]] und schnitt so die Elfen von ihrer Quelle arkaner Energie ab. Obwohl die Narben dieses Kampfes noch spürbar sind, haben sich die verbliebenen Elfen zusammengeschlossen und große Teile ihrer Heimat wieder eingenommen. Diese verbitterten Überlebenden, die sich \"Blutelfen\" nennen, haben sich der Wiedererlangung ihrer einst mächtigen Kräfte verschrieben. Inspiriert durch die Führung ihres geliebten Prinzen, [[Kael'thas Sonnenwanderer]], streben die Blutelfen nun nach neuen Quellen arkaner Magie und der Verteidigung ihrer Länder gegen die untoten Schrecken der Geißel. Aus ihnen entwickelten sich die [[Getriebenen]] und die [[Teufelsblutelfen]].\r\n==Geschichte==\r\n* Siehe auch: [[Aufstieg der Blutelfen]].\r\nDie [[Hochelfen]] sagten sich nach dem Zweiten Krieg von der [[Allianz]] los, und ihre Abspaltung löste den weiteren Zerfall der ohnehin brüchigen Allianz aus. Während des [[Der Dritte Krieg|Dritten Kriegs]] nahm die Allianz die [[Nachtelfen]] als Verbündete auf, die es als ihre Pflicht ansahen, ihre neuen Alliierten vor den [[Hochelfen]] zu warnen. Die zentrale Rolle, die die Hochgeborenen beim Ausbruch des [[Krieg der Urtume|Krieges der Urtume]] gespielt hatten, bildete in der Erzählung der [[Nachtelfen]] einen wesentlichen Teil der Hochelfengeschichte. Daher ist es wenig verwunderlich, dass die [[Menschen]] inzwischen den Hochelfen (und den Blutelfen, die sie mit ihnen in einen Topf werfen) mit Misstrauen und Feindseligkeit begegnen.\r\nUnter der Führung von [[Arthas]] Menethil fiel die [[Geißel]] vor kurzem in das Königreich [[Quel'Thalas]] ein und schuf den Lich [[Kel'Thuzad]], sie verunreinigte den [[Sonnenbrunnen]] und entzog ihm dabei seine gesamte Energie. Ein Großteil aller Hochelfen wurde von den untoten Scharen niedergemetzelt und [[Sylvanas Windläufer]]s rechte Hand, [[Lor'themar Theron]], übernahm vorübergehend die Herrschaft über die [[Hochelfen]]. Die wenigen Hochelfen, die die Invasion der [[Geißel]] überlebt hatten, überkam schnell Krankheit und sie wurden teilnahmslos. Prinz [[Kael'thas Sonnenwanderer]] war der letzte Überlebende des Königshauses und ein Mitglied der [[Kirin Tor]]. Zur Zeit der Invasion der Geißel betrieb er seine magischen Studien in [[Dalaran]]. Als er von der Katastrophe hörte, eilte er nach [[Quel'Thalas]] und fand sein Heimatland in Ruinen. Er erkannte, dass die Überlebenden der Elfen alle von derselben Art von Krankheit und Lethargie betroffen waren, die mit dem Erlöschen der magischen Energien des Sonnenbrunnens begonnen hatte. Fest entschlossen zu retten, was noch zu retten war, sammelte Kael'thas die Überlebenden und nannte sie Sin'dorei oder \"Volk der Blutslinie\", zu Ehren ihrer Gefallenen.\r\n===Reise zur Scherbenwelt===\r\nDie Blutelfen, die nicht so stark von der Krankheit getroffen waren, einschließlich Kael'thas, trachteten nach Rache und brachen aus ihrem verwüsteten Land auf, sich dem Feldzug gegen die Geißel in [[Lordaeron]] anzuschließen. In Abwesenheit des Prinzen wurde Lor'themar zum Herrscher von Quel'Thalas ernannt und [[Halduron Wolkenglanz]] wurde [[Waldläufer]]general von Silbermond. Bis heute ist Lor'themar der Anführer der Blutelfen Azeroths. Er und Halduron sichern das Land, während sie nach einem Heilmittel für den scheinbar unstillbaren Hunger ihres Volkes suchen. Kael'thas und sein angeschlagenes Volk boten den Widerstandstruppen der [[ Allianz]] an, mit ihnen gemeinsam gegen die Geißel zu kämpfen. Sie wurden jedoch nur mit Argwohn und offener Feindseligkeit begrüßt, vor allem von einem voreingenommenen Menschen, dem Großmarschall [[Garithos]]. [[Garithos]] beauftragte die Blutelfen mit immer härteren Missionen, bis [[Kael'thas]] gezwungen war, die Hilfe von [[Lady Vashj]] und ihrer [[Naga]] anzunehmen. Als [[Garithos]] erkannte, dass die Blutelfen mit den [[Naga]] zusammen arbeiteten, fühlte er sich in seinem Misstrauen bestätigt. Er nahm die unglücklichen Soldaten der Blutelfen im Verlies von [[Dalaran]] gefangen und verurteilte sie zum Tode.\r\nGlücklicherweise könnte Vashj die Blutelfen, die mittlerweise furchtbar unter ihrem Hunger nach [[Magie]] litten, rechtzeitig befreien. Vashj erklärte, dass auch die [[Naga]] abhängig von der [[Magie]] sind und dass [[Illidan]] den Blutelfen helfen könnte. Sie führte sie zum versprochenen Verfahren bei. Diese Lehren verbreiteten sich auch bei den anderen Blutelfen der [[Scherbenwelt]], die ihren schmerzhaften Hunger nach arkaner Magie stillen konnten. Durch das Portal, welches [[Kel'Thuzad]] im Dritten Krieg geöffnet hatte, um [[Archimonde]] den Weg nach Azeroth zu ermöglichen. Ohne bessere Optionen zur Wahl, folgten Kael'thas und seine Kämpfer den Naga durch das Portal in die verwüsteten Länder der Scherbenwelt. Dort angekommen befreiten die Elfen den abtrünnigen Dämon [[Illidan Sturmgrimm]], der Gefangener von Aufseherin [[Maiev Schattensang]] war. Nach der Rettung flehte Kael'thas Illidan an, ihm ein Heilmittel für die Magiesucht der Blutelfen zu beschaffen. [[Illidan]] hatte allerdings einen anderen Vorschlag: Im Austausch für die Treue der Blutelfen würde er ihnen beibringen, die [[Magie]] von anderen mächtigen Quellen zu ziehen, unter anderem von den Dämonen. Dies war ein Angebot, bei dem [[Kael'thas]] fühlte, dass er es annehmen sollte. Er war sich sicher, dass sein Volk sterben würde, wenn er kein Heilmittel oder eine neue Quelle der Magie finden würde. Kael'thas schwor Illidan seine Treue und eroberte an seiner Seite die [[Scherbenwelt]].\r\n===Wiederaufbau von Quel'Thalas===\r\nVon ihrer schnellen Genesung angespornt, entschlossen sich die meisten von Kael'thas Gruppe in der Scherbenwelt zu bleiben und ihre Studien dort fortzusetzen. Der [[Großmagister Rommath]] wurde mit der Nachricht der Hoffnung zurück nach [[Azeroth]] zu den Blutelfen in [[Quel'Thalas]] geschickt. Er erzählte von dem glorreichen versprochenen Land und gab die Lehren Illidans weiter. Lehren, die Rommath Prinz Kael'thas zuschrieb und somit die Auffassung begann, [[Kael'thas]] würde eines Tages zurückkehren und sein Volk ins Paradies führen. Großmagister Rommath blieb in Quel'Thalas und half, es wieder aufzubauen und auf die Rückkehr des Prinzen vorzubereiten. Dank [[Großmagister Rommath]] lernten die Blutelfen Azeroths, wie die arkane Magie gewonnen werden konnte, um ihre Sucht zu nähren. Ihre Gesundheit kehrte zurück und sie lobpriesen den Prinzen in seiner Abwesenheit und widmeten sich ganz dem Studium. Rommath und der neue Orden elfischer Magier machten große Fortschritte, ihren Brüdern die Manipulation der arkanen Energien zu lehren. Schon sehr bald ragten die Türme [[Silbermond]]s in den Himmel, angetrieben von flüchtiger [[Magie]]. Die Blutelfen haben sogar einige Gebiete der [[Immersangwald|Immersangwälder]] wieder zurückgeholt. Von dem Versprechen auf die Rückkehr Kael'thas angespornt, konzentrierten sich das müde Volk darauf ihre Stärke zurück zu gewinnen und einen neuen Weg in eine ungewisse Zukunft zu finden.\r\n===Die Sucht und ihre Folgen===\r\nDie Blutelfen bezeichnen sich nicht mehr wahrhaft als Hochelfen. Sie haben andere Prioritäten und Verhalten als ihre Verwandten. Im Gegensatz zu den Hochelfen haben die Blutelfen sich dazu entschlossen, in Abwesenheit des Sonnenbrunnens ihren Hunger für arkane Magie zu stillen, indem sie diese [[Magie]] von anderen Quellen beziehen. Dennoch gibt es einige grundlegende Ähnlichkeiten zwischen Blutelfen und Hochelfen, denn beide Gruppen gehören demselben Volk an. Wie bei den Hochelfen sind die meisten Blutelfen keine [[Magier]]. Blutelfen nutzen die Magie nicht, um zu zaubern, sie wollen damit nur ihre Sucht nach arkaner Magie stillen. Die Magie regelmäßig zu erlangen, hat den Blutelfen nicht die Unsterblichkeit beschert; sie sind anfällig für Krankheiten, Verletzungen und Alter wie ihre Hochelfenbrüder. Bis heute gibt es keine bedeutenden Unterschiede zwischen der Lebensdauer von Blutelfen und [[Hochelfen]].\r\nNach der Verschmutzung des Sonnenbrunnens hat Kael'thas zu mehreren Anlässen öffentlich beteuert, sein Volk werde sterben, wenn keine neue Quelle der [[Magie]] gefunden würde. Zweifellos ist der Entzug nach einer längeren Gewöhnung an die arkane Magie ein sehr unangenehmer Vorgang: bis heute ist es nicht unmöglich, dass sich ein Hochelf dazu entschließt sich dieser Sucht hinzugeben und ein Blutelf zu werden. Grundsätzlich hat sich der Prinz allerdings geirrt. Gemäß den höchsten [[Priester]]m und Heilern in Azeroth waren die einzigen Hochelfen, die aufgrund des zerstörten [[Sonnenbrunnen]]s gestorben waren, die sehr alten, die sehr jungen und diejenigen, die eher kränklich waren. Dies bedeutet nicht, dass der Entzug von der Magie die Blutelfen unbeschädigt lassen würde. Im Gegenteil, ständige mentaler und physischer Schaden ist möglich.\r\nDennoch war das sehr schnelle Ergreifen der düsteren Methoden (zum Beispiel das Gewinnen der Magie von [[Dämonen]]) keinesfalls charakteristisch für Blutelfen im Allgemeinen. Blutelfen der [[Scherbenwelt]] haben nun [[Kael'thas]] Abmachung mit Illidan aufgedeckt und haben zum größten Teil seine Notwendigkeit eingesehen. Die meisten Blutelfen leben allerdings noch in Azeroth. Nur wenige dieser Elfen wissen von Kael'thas' Bündnis mit [[Illidan]] und viele wären entsetzt, wenn sie es entdecken würden. [[Magie]] von kleinem manatragenden Ungeziefer zu ziehen ist immerhin sehr weit entfernt davon, die Magie von Dämonen zu gewinnen. Dennoch, je mehr ihr Hunger wächst, desto mehr gewöhnen sich die Blutelfen, vor allem die der Scherbenwelt, an die Dinge, die sie tun müssen, um noch mehr [[Magie]] zu beschaffen.\r\nNach neuesten Erkenntnissen ist der [[Sonnenbrunnen]] von [[Anveena Teague]] fast wieder aufgeladen.\r\n==Blutelfen und die Horde==\r\nZirka 85% der Blutelfen befinden sich noch in [[Azeroth]] und nicht in der Scherbenwelt. Die meisten Blutelfen Azeroths leben in Quel'Thalas. Die Weltenwanderer zum Beispiel, eine kleine, aber elitäre Gruppe von Blutelfen-[[Waldläufer]]n, kämpfen, um die letzten der [[Geißel]] aus Quel'Thalas zu vertreiben. Im Allgemeinen haben die Blutelfen einen negativen Eindruck von der [[Horde]]. Die Feindseligkeit der Blutelfen gegenüber den [[Trolle]]n etwa ist seit der Gründung von Quel'Thalas bestens dokumentiert, und diese Feindschaft wurde in den Trollkriegen nochmals untermauert. Auch für die Orcs haben die [[Weltenwanderer]] nicht viel übrig, denn es waren Orctruppen, die im Zweiten Krieg die Grenzlande von [[Quel'Thalas]] überfielen, verwüsteten und niederbrannten. Gegen die [[Tauren]] haben die[[ Weltenwanderer]] eigentlich nichts, sehen sie aber meist als ungeschlachte tierische Monster an.\r\nDoch die Blutelfen haben inzwischen gute Beziehungen zu den Verlassenen, was sie größtenteils Königin [[Sylvanas Windläufer]] verdanken, die einst eine Hochelfe war und den Rang eines [[Waldläufer]]generals von [[Silbermond]] inne hatte, bevor [[Arthas]] sie gegen ihren Willen in eine Untote verwandelte. Die Königin behauptet, sie fühle sich immer noch als eine der glühendsten Verteidigerinnen von [[Quel'Thalas]]. Sie hat wiederholt ihre Hilfe in Form von Nachschub und Truppen angeboten.\r\nBislang haben die Blutelfen, die offenbar eine Falle fürchten, die meisten ihrer Offerten ausgeschlagen, insbesondere solche, bei denen Soldaten der [[Verlassene]]n in Blutelfengebieten stationiert worden wären. Doch es ist den eingekesselten Elfen schmerzlich bewusst, dass sie der Geißel zahlenmäßig erheblich unterlegen sind, und dass offenbar niemand sonst für das kämpfen will, was von Quel'Thalas noch übrig ist. Besonders die [[Allianz]] hat keinerlei Interesse daran gezeigt, den Blutelfen in Azeroth zu helfen, weder dabei, zur [[Scherbenwelt]] zu gelangen, noch bei der Vertreibung der Geißel aus Quel'Thalas. Die Allianz, die schon den paar verstreuten Hochelfen, die es noch gibt, mit Misstrauen begegnet, hält die Blutelfen für noch weniger vertrauenswürdig. Besonders die [[Nachtelfen]] stehen den Blutelfen feindselig gegenüber, denn für die [[Nachtelfen]] stinken die Sin'dorei nach Verzweiflung und arkaner Magie. Angesichts der prekären Lage, in der sich die Blutelfen in [[Azeroth]] befinden, wird es immer wahrscheinlicher, dass sie in absehbarer Zeit ein Zweckbündnis mit der [[Horde]] eingehen werden. \r\n \r\n==Heraldische Deutung des Wappens==\r\nDas neue Wappen des Blutes, welches die Blutelfen gewählt haben, zeigt tiefere Symbolik und Hinweise auf die Geschichte dieses Volkes. Im Zentrum ist ein goldener Falke zu sehen, der die Flügel ausbreitet. Der Falke könnte jedoch auch ein Phönix sein. Dafür spricht, dass der Vogel keine Beine hat und Flammen ihn umgeben. Der Phönix wäre das Symbol für die Blutelfen, die sich aus der Asche erhoben haben, ebenso für die Stadt Silbermond. Oben ist ein großer, stilisierter Tropfen zu sehen, vielleicht eine Träne, vielleicht ein Blutstropfen. Beides zeigt etwas an, der Blutstropfen auf die Gefallenen, die Träne die Trauer. Unten sind Mistelzweige angeordnet. Misteln stechen in der Hand und sind ein Symbol des Schmerzes, welchen die Blutelfen erlitten. Die vorherrschenden Farben sind rot und gold.\r\n==Religion==\r\nDie Blutelfen verehren nicht mehr das [[Heilige Licht]], sondern wandten sich der Sonne zu, der Quelle des Lichts. Unter ihren wärmenden Strahlen wird das Volk der Blutelfen gedeihen, die Untoten der Geißel in ihrem Feuer vernichtet werden und das Paradies der Blutelfen, [[Ley]] genannt, sich ihnen öffnen. Dann wird den Blutelfen eine neue Dimension der Macht und das Glücks bewusst werden.\r\n'''Architektur'''\r\nBlutelfische Architektur zeichet sich durch elegante Formen und reichhaltige Verzierungen aus. Auch hier werden durchgehend warme Farben wie Rot oder Gold eingesetzt. Das Wappentier der Blutelfen ist der [[Phönix]], mit dem sich das Volk der Blutelfen verbunden fühlt, möglicherweise weil Phönixe nach ihrem Tod wiedergeboren wurden, wie auch die Blutelfen als Hochelfen \"starben\" und als Blutelfen wieder auferstanden.\r\n'''Der Durst'''\r\nSeit der Zerstörung des Sonnenbrunnens haben die Blutelfen erneut mit dem Manaentzug zu kämpfen, wie als vor zehntausend Jahren der Brunnen der Ewigkeit zerstört wurde. Blutelfen kämpfen permanent mit dem magischen Entzug. Diejenigen, die von ihrer Sucht übermannt werden werden zu Getriebenen Die Blutelfen stillen ihren Durst hauptsächlich durch Chaos-Energie, die durch ein Verteilernetzwerk in ganz Quel'thalas verteilt wird, teilweise wird ihr Durst aber auch durch arkane oder heilige Quellen. Der Konsum der Chaos-Energie hat ihre physiologische Erscheinung bereits leicht verändert, es ist quasi eine sanfte Evolution im Gange, der Entwicklung von Nachtelfen zu [[Satyr]]n nicht unähnlich. Chaos-Energie hat außerdem negative Auswirkungen auf den Charakter, was die meisten Blutelfen arrogant und verachtend gegenüber anderen macht. Allerdings wehren sich einige der Blutelfen mit Erfolg gegen diesen mentalen Einfluss.\r\n==Gruppierungen==\r\n* [[Blutelfen der Dämmerklingen]]\r\n* [[Blutelfen der Feuerschwingen]]\r\n* [[Blutelfen der Mondfinsternis]]\r\n* [[Blutelfen der Sonnenfalken]]\r\n* [[Blutelfen der Sonnenklingen]]\r\n* [[Blutelfen des Sonnenzorns]]\r\n* [[Seher]]\r\n* [[Tristessa]]\r\n* [[Weltenwanderer]]\r\n'''Anmerkung:''' Anfangs existierte ein weiterer Klan: Die \"Blutelfen der Blutschwingen\". Dieser Klan wurde jedoch umbenannt in die \"[[Blutelfen der Feuerschwingen]]\".\r\n==Persönlichkeiten==\r\n* [[Lor'themar Theron]]\r\n* [[Großmagister Rommath]]\r\n* [[Halduron Wolkenglanz]]\r\n* [[Magus Rimtoris]]\r\n* [[Voren'thal der Seher]]\r\n==Ränge==\r\n* [[Arkanist]]\r\n* [[Beschwörer]]\r\n* [[Blutmagier]]\r\n* [[Blutritter]]\r\n* [[Blutwärter]]\r\n* [[Feldmesser]]\r\n* [[Kundschafter der Blutelfen|Kundschafter]]\r\n* [[Magister]] / [[Magistrix]]\r\n* [[Nethermant]]\r\n* [[Pfadpirscher]]\r\n* [[Priester der Blutelfen|Priester]]\r\n* [[Waldläufer]]\r\n* [[Warpmeister]]\r\n* [[Wiederbeschaffer]]\r\n'''Quellen'''",},
			["Blutelfenpriester"] = { content = "Die Hälfte der [[Hochelfen Priester]] wehrte [[Arthas]] ab, als er versuchte ihre Hauptstadt [[Silbermond]] und [[Quel'Thalas]] anzugreifen. Heutzutage werden die überlebenden [[Blutelfen Priester]] der in den [[Sanktum|Arkanen Sankten]] ausgebildet und das Licht ermöglicht ihnen, anderen zu helfen ... aber erst, wenn sie sich selbst geholfen haben. Sie glauben fest daran, dass die finsteren Zeiten vorübergehen werden.\r\n==Ausrichtungen==\r\n* [[Solarispriester]]",},
			["Blutelfenschurke"] = { content = "Die '''Blutelfen Schurken''' werden im allgemeinen als ''Pfadpirscher'' bezeichnet. Ihr Volk ist mit dem Arkanen verbunden, selbst jene die die Künste selbst nicht ausüben.\r\n==Bezeichnungen==\r\nJe nach Aufgabe und Ausrichtung tragen die [[Schurke]]n der [[Blutelfen]] verschiedene Bezeichungen. Dazu gehören u.a.:\r\n* '''Pfadpirscher''' - Eine allgemeine Bezeichnung für einen Blutelfen Schurken. \r\n* '''Kundschafter''' - Die Kundschafter der Blutelfen kümmern sich im [[Immersangwald]] um den Warenverkehr zwischen der [[Insel der Sonnenwanderer]] und dem Landesinneren. Es ist ein hartes Stück Arbeit, ein Kundschafter zwischen der Insel und dem [[Inneres Elfentor|Inneren Elfentor]] zu sein. Knappe Zeitvorgaben, viele Stunden und noch schlimmer... die [[Getriebene]]n. Der Tod eines Kundschafters ist eine wahre Tragödie, aber es ist ein Risiko, das sie alle in Kauf nehmen, wenn sie einen Auftrag annehmen.",},
			["Blutelfen der Dämmerklingen"] = { content = "Die Armee der '''Blutelfen der Dämmerklingen''' gehört zu Kael'thas Elitestreitkräften und folgte ihm auf die [[Insel von Quel'Danas]]. Sie wurden im [[Hafen der Sonnenweiten]] und in [[Morgenstern]] stationiert ... und besiegelten damit ihr Schicksal, eines der Hauptangriffsziele der [[Offensive der Zerschmetterten Sonne]] zu werden. \r\nVor der Küste des Hafens der Sonnenweiten liegt ihre Flotte mit Verstärkungstruppen der Dämmerklingen vor Anker. Sie besteht aus den drei elfsichen Zerstörern: der '[[Sin'loren]]', der '[[Blutschwur]]' und der '[[Morgensturm]]'. Diese drei Schiffe befinden sich unter dem Dauerfeuer der [[Drachenfalkenreiter]] der [[Offensive der Zerschmetterten Sonne]], die die Segel der Flotte mit Flammenden Öl in Brand setzen.\r\n==Arten==\r\n* [[Beschwörer]] der Dämmerklingen\r\n* [[Blutritter]] der Dämmerklingen\r\n* [[Reservist]] der Dämmerklingen\r\n* [[Schütze]]n der Dämmerklingen",},
			["Blutelfen der Feuerschwingen"] = { content = "Die [[Blutelfen der Feuerschwingen]] leben im [[Posten der Feuerschwingen]] im Nordosten der [[Wälder von Terokkar]]. Sie arbeiten für [[Illidan]] und benutzen die [[Zerschlagene]]n von [[Tuurem]] als Schmuggler für die Bombenteile, um eine furchtbare Waffe herzustellen. Sie bauen eine zweite [[Manabombe]] im Hof und [[Sharth Voldoun]], der Zuständige des Projekts im Posten der Feuerschwingen, hat den finalen Code der Bombe. Er hält sich auf der Spitze der höchsten Säule auf. [[Isla Sternenmähne]] von der [[Expedition des Cenarius]] hat Informationen, die für die Sicherheit vielleicht der ganzen [[Scherbenwelt]] von äußerster Wichtigkeit sind. Sie ist von der Expedition mit einem diplomatischen Auftrag zum Posten der Feuerschwingen geschickt worden, aber die [[Blutelfen]] waren ihr nicht sehr freundlich gesonnen.",},
			["Blutelfen der Mondfinsternis"] = { content = "Die '''Blutelfen der Mondfinsternis''' leben im [[Schattenmondtal]] in der Nähe der [[Felder der Mondfinsternis]] und der [[Stätte der Mondfinsternis]]. Dieser [[:Kategorie:Klan|Blutelfenklan]] gehört zu den Dienern von [[Illidan]] und führt etwas Großes im Schilde, denn sie haben begonnen, ihre Armeen beim [[Pfad der Eroberung]] zusammenzuziehen.",},
			["Blutelfen der Sonnenfalken"] = { content = "Die [[Blutelfen]], die auf der [[Blutmythosinsel]] gelandet sind und einen Krieg gegen die [[Draenei]] vorbereiten, nennen sich die \"'''Sonnenfalken'''\". Sie erhalten durch das [[Sonnentor]] Verstärkung aus der [[Scherbenwelt]] und haben einen Spion unter den [[Draenei]] bei der [[Exodar]]. Die Aktivitäten der [[Blutelfen]] haben sich in der letzten Woche fast verdoppelt und Agenten der [[Blutwacht]] haben mitgeteilt, dass die Sonnenfalken einen baldigen Angriff auf die [[Azurmythosinsel]] planen. Letztendlich wollen sie den [[Naaru]] [[O'ros]] versklaven und wieder die Kontrolle über die [[Exodar]] gewinnen. Geführt werden sie von eiener [[Eredar]] namens [[Sironas]]. Ihr Herold [[Matis der Grausame]] patrouilliert auf dem Weg von der [[Vektorspule]] zum [[Messerwinkel]].\r\n==Schreiben der Sonnenfalken==\r\nIn einem Schreiben an die Sonnenfalken wendet sich [[Kael'thas Sonnenwanderer]] an seine Ergebenen:\r\n'''Bekanntgabe des Sonnenkönigs'''\r\nSonnenfalken - meine teuren, ergebenen Kinder - erhört Euren König. Eure Präsenz in Azeroth ist von höchster Wichtigkeit für mich und den Meister.\r\nSchon bald wird das Sonnenportal Verstärkung direkt von der Festung der Stürme zur [[Blutmythosinsel]] transportieren. \r\nWir werden die [[Exodar]] zurückgewinnen. Wir werden die blauhäutigen Bastarde an Ort und Stelle vernichten. Velen wird für seine Verbrechen bezahlen.\r\n-König Kael'thas Sonnenwanderer",},
			["Blutelfen der Sonnenklingen"] = { content = "Die '''Blutelfen der Sonnenklingen''' befinden sich im Bereich des [[Sonnenbrunnenplateau]]s sowie auf der [[Terrasse der Magister]]. Aber auch auf der [[Insel von Quel'Danas]] selbst haben sie ihre Aufklärer. Diese [[Blutelfen]] stehen unter dem Befehl von [[Kael'thas Sonnenwanderer]].\r\n==Klassen==\r\n* [[Abendpriester]] der Sonnenklingen\r\n* [[Beschützer]] der Sonnenklingen\r\n* [[Bewahrer]] der Sonnenklingen\r\n* [[Blutritter]] der Sonnenklingen\r\n* [[Erzmagier]] der Sonnenklingen\r\n* [[Heiler]] der Sonnenklingen\r\n* [[Hexenmeister]] der Sonnenklingen\r\n* [[Kabalist]] der Sonnenklingen\r\n* [[Magierwache]] der Sonnenklingen\r\n* [[Magister]] der Sonnenklingen\r\n* [[Morgenpriester]] der Sonnenklingen\r\n* [[Schildwache]] der Sonnenklingen\r\n* [[Späher]] der Sonnenklingen\r\n* [[Töter]] der Sonnenklingen\r\n* [[Verteidiger]] der Sonnenklingen",},
			["Blutelfen des Sonnenzorns"] = { content = "Die '''Blutelfen des Sonnenzorns''' sind die hochrangigsten Soldaten von [[Kael'thas Sonnenwanderer]]. Sie tragen die , die ihren Rang angeben und man findet sie überall im [[Nethersturm]] und im [[Schattenmondtal]]. Ihre Befehlspapiere bestätigen den Verdacht, dass Kael'thas bei dem Bau und dem Betrieb der [[Manaschmiede]]n Hilfe von außen bekommen hat. Diese Befehle bestehen zum einen aus den , die für die [[Dämonenbeschwörer]] des Sonnenzorns bestimmt sind, und zum anderen aus den , die an die Bogenschützen, Jagdschützen und Zenturios des Sonnenzorns im [[Nethersturm]] verteilt wurden.\r\n==Klassen==\r\n* [[Arkanist]] des Sonnenzorns\r\n* [[Astromant]] des Sonnenzorns\r\n* Beschützer des Sonnenzorns\r\n* [[Beschwörer]] des Sonnenzorns\r\n* [[Blutlord]] des Sonnenzorns\r\n* [[Blutritter]] des Sonnenzorns\r\n* [[Blutwärter des Sonnenzorns]]\r\n* [[Bogenschütze]] des Sonnenzorns\r\n* [[Dämonenbeschwörer]] des Sonnenzorns\r\n* [[Erzmagier]] des Sonnenzorns\r\n* [[Flammenbewahrer]] des Sonnenzorns\r\n* Forscher des Sonnenzorns\r\n* Gardist des Sonnenzorns\r\n* [[Geologe des Sonnenzorns]]\r\n* Hauptmann des Sonnenzorns\r\n* [[Hexenmeister]] des Sonnenzorns\r\n* [[Jagdschütze]] des Sonnenzorns\r\n* [[Magister des Sonnenzorns]]\r\n* [[Nethermant]] des Sonnenzorns\r\n* Techniker des Sonnenzorns\r\n* Vernichter des Sonnenzorns\r\n* [[Warpingenieur]] des Sonnenzorns\r\n* [[Warpmeister]] des Sonnenzorns\r\n* [[Zenturio]] des Sonnenzorns",},
			["Blutelfen Kundschafter"] = { content = "#REDIRECT [[Blutelfenschurke]]", redirect = "Blutelfenschurke",},
			["Blutelfen Paladin"] = { content = "#REDIRECT [[Blutritter]]", redirect = "Blutritter",},
			["Blutelfen Waldläufer"] = { content = "#REDIRECT [[Waldläufer]]", redirect = "Waldläufer",},
			["Blutfratzen"] = { content = "#REDIRECT [[Trolle der Blutfratzen]]", redirect = "Trolle der Blutfratzen",},
			["Blutfürst Mandokir"] = { content = "Der Blutfürst Mandokir ist einer der optionalen Bosse in [[Zul'Gurub]], der kein Aspekt von [[Hakkar]] ist. Vor Mandokir befinden sich einige [[Raptor]]enrudel. Wenn man den Sprecher am Ende der Treppe getötet hat, kommt Mandokir automatisch von oben herunter geritten und der Kampf beginnt.\r\nMit viel Glück kann man von Mandokir den [[Raptor|Schneller Razzashiraptor]] als besonderes Reittier erbeuten.",},
			["Blutgiftfälle"] = { content = "===Blutgiftfälle===\r\nIm Norden von Jaedenar befinden sich die Blutgiftfälle an. Das von den östlichen Bergen sich in einem See sammelnden Wasser, ebenfalls verseucht, fließt nach Westen und überwindet dabei ein Gefälle. Noch ist es unbekannt, ob natürliche oder magische Kräfte in den Bergklüften die Wasser dann reinigen, denn sie bilden schließlich an der [[Dunkelküste]] den Wildbend. Die Auswirkungen der Verderbnis sind allerdings auch - in einem geringeren Maße - in diesem elfischen Gebiet zu spüren.",},
			["Blutgiftposten"] = { content = "Der Blutgiftposten ist ein kleines Lager der [[Horde]] mit Flugpunkt am Ende der [[Blutgiftfälle]] im [[Teufelswald]].\r\n==Personen==\r\n* '''Dreka'Sur''' - Dreka'Sur ist eine Orkin und möchte die Klaue von [[Oberanführer Ror]]. Ihr Gatte reiste dem Klan zu Ehren durch den [[Teufelswald]] und kämpfte gegen den [[Schattenrat]] und andere verderbte Monstrositäten. Als er dem Tod viele Male entronnen war, erhielt sie einen Brief von ihm, in dem stand, dass ein [[Druide]] ihn um Beistand gegen einen großen beschmutzten [[Furbolg]] namens [[Oberanführer Ror]] gebeten hatte - man hörte nie wieder etwas von ihnen.\r\n* '''Trull Scheiterbann''' - Trull Scheiterbann verfügt über sehr großes Wissen über die [[Wildekin]]. Er will herausfinden, was in [[Winterquell]] verborgen liegt, denn die [[Wildekin]] in den nördlichen Bereichen von [[Winterquell]] werden immer aggressiver und es scheint, als hätte genau das, was diese Kreaturen beschützen wollen, sie in den Wahnsinn getrieben. Doch auch wenn er viel über die [[Eulenbestien]] weiß, ist er in der Magie, die sie wirken, nicht wirklich bewandert.\r\n* '''Winna Hazzard''' - Winna Hazzard ist eine [[Verlassene]]. Manche Leute sagen, sie sei außergewöhnlich grausam. Aber in Wirklichkeit ist sie nur von dem Wunsch beseelt zu sehen, wie die [[Horde]] einen Vorteil gegenüber der [[Allianz]] erringt, und zwar auf jede nur mögliche Weise. Seit kurzem interessiert sie sich für einen [[Mondbrunnen]] in den [[Ruinen von Constellas]] und das verderbte Wasser könnte sie zum Vorteil verwenden. Mit nur einer kleinen Menge Wasser kann man eine Kreatur verändern ... Sie hat das Wasser an einem kleinen Kätzchen ausprobiert und dieses wurde doppelt so groß und scheint irgendwie stärker als vorher zu sein. Solche Katzen könnten sich noch als nützlich erweisen.",},
			["Blutjuwelenkristall"] = { content = "[[Magister des Sonnenzorns|Kael'thas' Magister]] im [[Nethersturm]] haben den Gebrauch von Manakristallen so weit perfektioniert, dass sie innerhalb von Sekunden große Mengen von Energie aufnehmen können. Das tun sie, indem sie kleinere Kristallsplitter von Blutjuwelen an größeren und vollen Kristallen aufladen. Nebenwirkungen sollten nur temporär sein.",},
			["Blutkessel"] = { content = "#REDIRECT [[Höllenfeuerzitadelle: Blutkessel]]", redirect = "Höllenfeuerzitadelle: Blutkessel",},
			["Blutkristall"] = { content = "#REDIRECT [[Blutjuwelenkristall]]", redirect = "Blutjuwelenkristall",},
			["Blutmagier"] = { content = "Viele der stoischen [[Hochelfen]], geführt vom Schmerz über des Verlust ihrer Heimat [[Quel'Thalas]], haben sich ihrem Hass auf die [[Geißel]] ergeben und studieren nun die allverzehrende Kraft des Feuers in all ihren Formen - die dämonische inbegriffen. Die Blutmagier tauchten mit der Umbenennung der [[Hochelfen]] in [[Blutelfen]] zum ersten Mal auf. Sie sind magiesüchtig und machthungrig! Die heutigen Blutmagier dienen allesamt ihrem Prinzen [[Kael'thas]], welcher ebenfalls ein Blutmagier war. Sie sind eng mit dem Feuer verbunden,setzten unter anderem [[Verdanische Sphärenkugel]]n und können [[Phönix]]e beschwören.\r\nEs gibt auch Blutmagier unter den [[Orcs des Schattenmondklans]]. Diese findet man im [[Der Schwarze Tempel|Schwarzen Tempel]] und sie verfügen über die Fähigkeit des Blutfeuers und Bluttrinkers.\r\n==Bekannte Blutmagier==\r\n* [[Blutmagier Drazial]]\r\n* [[Blutmagier Thalnos]]\r\n* [[Blutmagierin Lynnore]]",},
			["Blutmythosinsel"] = { content = "== Allgemeines==\r\nDie Blutmythosinsel liegt vor der nordwestlichen Küste [[Kalimdor]]s. Die Ankunft der [[Draenei]] hat diese Insel für alle Zeit verändert, denn sie wurde vom Absturz der [[Exodar]] am schlimmsten betroffen. Die Wrackteile des Schiffes liegen überall auf der Insel verstreut und die mutagene Verseuchung ist hier stärker ausgeprägt als auf den anderen Inseln. Der Absturz der [[Exodar]] hat auf der Blutmythosinsel überall Stücke schädlicher Kristalle verstreut, die das Wasser und den Rest des Landes verderben. Doch man hat einen Weg gefunden, wie man die Splitter reinigen und somit in zweckmäßige Kristalle verwandeln kann. Als die [[Draenei]] hier zu Beginn ankamen, war das Land genauso wunderschön und unberührt wie auf der [[Azurmythosinsel]]. Sie nannten es sogar Silberbrise, doch nun breitet sich die Seuche über das Land aus. Was noch schlimmer ist, die [[Blutelfen]], die sie auf der [[Exodar]] bekämpften, haben den Absturz überlebt.\r\n===Flora===\r\nDie Kristalle scheinen die Bäume als erstes beeinträchtigt zu haben und die [[Treants]] weisen am ehesten die Symptome der Verseuchung auf. \r\n===Fauna===\r\nDie Draenei haben Stücke der Kristalle auch im Fleisch von Tieren gefunden, die den [[Draenei]] normalerweise als Nahrungsquelle dienen. Bislang konnte man die Splitter in den Körpern von [[Bär]]en, [[Felshetzer]]n, [[Falter]]n und [[Treants]] finden, die den verderbten Teil der Insel bewohnen. Aber auch das Element des Wassers ist aus dem Gleichgewicht geraten, denn etwas verunreinigt das Wasser auf und um die Blutmythosinsel herum. Nicht einmal einem Blinden würde der Effekt entgehen, den diese Störung auf die Kreaturen hat. Die Verunreinigung ist hartnäckig und könnte, wenn man nicht rechtzeitig handelt, ungehindert in die Ströme des Meeres fließen und sich somit in ganz [[Azeroth]] ausbreiten.\r\n===Tagespolitik===\r\nDie [[Draenei]] in dieser Gegend beschäftigen sich mit der Erforschung und Einschränkung der Verschmutzung, doch das Augenmerk gilt auch der Bedrohung durch die [[Blutelfen]]. Der [[Hand von Argus]] ist es gelungen, einen der [[Blutelfen]] zu fangen, doch ihre Vernehmungsversuche sind kläglich gescheitert. Folter kommt natürlich nicht in Frage. Was sie brauchen, ist ein [[Draenei]], der an ihn herankommen kann. Eine erfolgreiche Befragung führt ans Licht, dass die [[Blutelfen]] von einem Verräter unter den [[Draenei]] angeführt werden; einer mächtigen [[Eredar]] namens Sironas, die die Reihen der [[Draenei]] unterwandert und sich lange Zeit als eine von ihnen ausgegeben hat.\r\n==Orte==\r\n* [[Axxarien]]\r\n* [[Blutwacht]]\r\n* [[Goldweberpass]]\r\n* [[Hasspranken Zuflucht]]\r\n* [[Insel Drachenfels]]\r\n* [[Kessels Wegelager]]\r\n* [[Lager der Sichelklauen]]\r\n* [[Nazzivian]]\r\n* [[Rachfederkamm]]\r\n* [[Ruinen von Loreth'Aran]]\r\n* [[Schwarzschlammküste]]\r\n* [[Verteidigers Ruh]]\r\n===Absturzstelle===\r\nDie Absturzstelle liegt nordwestlich von [[Kessels Wegelager]]. [[Felshetzer]] haben hier die Schiffstrümmer besetzt, die südlich der [[Blutwacht]] auf der anderen Seite der Brücke liegen.\r\n===Besudelter Teich === \r\nIm Südwesten liegt ein verderbtes Gewässer, welches mittlerweile als besudelter Teich bekannt ist. Der Ursprung der Verunreinigung des Wassers hier ist das Nebenprodukt eines wahnsinnigen Experiments. Südwestlich des besudelten Teichs liegt ein kleines Lager, wo man auf das 'Experiment' von [[Tel'athion der Unreine|Tel'athion dem Unreinen]] stößt. An diesem Ort erzeugt er den Unrat und lässt ihn in die Gewässer der Insel sickern. In einem versteckten Riff unter den Wogen vor der Küste im Norden der Blutmythosinsel findet man den [[Wasserelementar]] [[Aqueous]]. \r\n===Kloppers Schildkrötenhaus===\r\nKlopper Knacksklug ist losgezogen und hat sich in einem alten Schildkrötenpanzer an der nördlichen Küste der Insel eingerichtet Er ist besonders von Murlocs fasziniert, doch wenn die Murlocs seiner Anwesenheit gewahr werden, ist es mit dem Experiment vorbei. Er war schon sehr nahe daran, seine Arbeit zu gefährden. Als er am Herumkramen war, muss einer von ihnen zu nahe gekommen sein und sein Lager entdeckt haben. Er kam noch rechtzeitig, um zwei von ihnen eine seiner Ausrüstungskisten fortschleppen zu sehen. Sie müssen in einer ihrer Siedlungen zu finden sein, aber er kann es nicht riskieren, seine Deckung aufzugeben. Seine Beobachtungen und Aufzeichnungen über die Murlocs der Schwarzschlammküste sind recht aufschlussreich, aber er hat gerade erst damit angefangen. \r\n===Kryokern===\r\nMan erhielt Berichte über eine neue Absturzstelle. Die Draenei haben herausgefunden, dass es sich bei dieser Absturzstelle eigentlich um den Kryokern der Exodar handelt. Eine Transportkammer, in der genau solche Kapseln untergebracht sind, wie die aus dem Am’mental. In diesem Bereich werden auch Heilvorräte aufbewahrt.\r\n===Messerwinkel===\r\nDer Messerwinkel befindet sich nordwestlich der Blutwacht. Die Kristalle hier werden von den [[Blutelfen]] kontrolliert. Berichten zufolge verändern und ernten sie die Kristalle, um sie in einer Art magischer Apparatur zu verwenden.\r\n===Sonnentor===\r\nDiese findet man im Südwesten am kleinen See. Die [[Blutelfen]] erhalten Verstärkung aus der [[Scherbenwelt]] und sie haben einen Spion unter den [[Draenei]] bei der [[Exodar]]. Die Aktivitäten der [[Blutelfen]] haben sich in der letzten Woche fast verdoppelt. Agenten haben mitgeteilt, dass die [[Blutelfen]], die sich selbst Sonnenfalken nennen, einen baldigen Angriff auf die [[Azurmythosinsel]] planen. Letztendlich wollen sie noch O'ros versklaven und wieder die Kontrolle über die [[Exodar]] gewinnen.\r\n===Vektorspule===\r\nEin gigantischer Kraftkern ragt aus der Seite eines Bergs hervor. Manche der Anomalien, die hier vorkommen, sind Kreaturen aus der Leere selbst. Wer auch immer diese Last auf sich nehmen möchte, muss sich seinen Weg durch den Berg kämpfen und eine Armee der Sonnenfalken abwehren. Matis der Grausame patrouilliert auf dem Weg von der Vektorspule zum Messerwinkel.",},
			["Blutrippe"] = { content = "'''Blutrippe''' (engl. Rattlegore) ist ein [[Knochengolem]] im Kellergewölbe der [[Scholomance]].",},
			["Blutritter"] = { content = "==Allgemeines==\r\n'''Blutritter''' sind Angehörige eines Ordens, die sich der Verteidigung von [[Silbermond]] oder der Interessen der [[Blutelfen]] in anderen Gebieten verschrieben haben. Blutritter sind Ausschließlich bei den Blutelfen zu finden. Sie sind Vergleichbar mit dem [[Paladin]] der [[Allianz]]. Allerdings beten sie nicht das [[Heilige Licht]] an, sondern eher wie alle [[Blutelfen]] die Sonne. Rache für ihr Volk beherrscht all ihre Gedanken und niemand sollte denken, dass man sie davon abhalten kann, ihre Ziele zu erreichen. Die Schlacht, die sie für ihr Volk kämpfen, hat gerade erst begonnen.\r\nDie Blutritter sind zwar eine Ordensgemeinschaft, doch müssen sie sicherstellen, dass die Brüder und Schwestern stets wachsam und vorbereitet sind. Deswegen werden schon in der ersten Prüfung unfähige Initianden durch den entgültigen Tod aussortiert. Die Loyalität eines Blutritters endet nicht an der Spitze seiner Klinge. Der Orden verlangt mehr von seinen Mitgliedern, als schiere Ausbildung und Kampf. Ein wahrer Ritter trägt zu allen Aktivitäten des Ordens etwas bei, selbst zu denen, die nicht offensichtlich Ruhm verheißen. Sie haben geschworen, [[Quel'Thalas]] zu verteidigen. Dies ist ein zentraler Teil der Ausbildung. Ihre Feinde sind wild und unbeugsam und einzig die Anstrengungen und die Unterstützung der Verbündeten sind der Garant für die Freiheit eines jeden Bürgers von [[Silbermond]]. \r\n===Eine Fremde Machtquelle===\r\nDie Blutritter beziehen ihre Kräfte von einem Wesen mit immenser Macht. Der gefangene [[Naaru]] M'uru in der geheimen Kammer unter dem Hauptquartier der [[Blutelfen]] ist ein Geschenk von ihrem geliebten Prinz [[Kael'thas]] und seine Kraft ist die Grundlage für die Beherrschung des Lichts. Ursprünglich missgönnte der [[Naaru]] den Blutrittern seine Macht, also haben sie einen eigenen Weg gefunden, um sie dennoch zu nutzen. Die Blutritter würden niemals auf natürlichem Wege über die Kräfte des Lichts gebieten, doch haben sie sich nicht durch den Willen eines einzelnen, wenn auch mächtigen Wesens, aufhalten lassen. Die Beherrschung der arkanen Mächte hat ihnen diesen Pfad und diese Fähigkeiten eröffnet, doch nur wenige sind mutig genug, oder verfügen über die Begabung, diese Kräfte auch einzusetzen. Durch die Erweckung der Magie des Naaru M'uru wird ein Blutritter fähig, die Macht des Wesens für sich zu nutzen. Ausgestattet mit dieser Kraft wird es ein Leichtes sein, z.B. gefallene Ordensbrüder ins Leben zurückzuholen. Es gibt Stimmen, die behaupten, dass die Blutritter einen falschen und ungerechten Weg eingeschlagen haben, doch vieles, was ihnen widerfahren ist, war ebenfalls ungerecht. Sollten sie eine solche Gabe einfach wegwerfen? Nie hat sich jemand beschwert, wenn sie die Kräfte zum Schutze [[Silbermond]]s vor seiner weiteren Zerstörung eingesetzt haben. Nein, sie erheben erst Einspruch, wenn sie vor jeglichem Leid sicher sind und sie sich gänzlich ihrer Magieabhängigkeit hingeben können.\r\n==Bezeichnungen==\r\nJe nach Ausrichtung und Aufgabe tragen die Blutritter verschiedene Bezeichnungen. dazu gehören u.a.:\r\n* '''Blutwärter''' - Die Blutwärter des Sonnenzorns bewachen die [[Manaschmiede]]n im [[Nethersturm]] in der [[Scherbenwelt]] und arbeiten unter dem Befehl von [[Kael'thas Sonnenwanderer]].\r\n==Ränge==\r\nMit der Zeit wird ein aufstrebender Blutritter sich einen Platz in den Reihen verdienen. Als Erstes muss man jedoch den Umgang und das Meistern des mächtigen Lichts erlernen. Man muss gut vorbereitet sein, um den Spott, die Angst und den Abscheu derer ertragen zu können, die man zu beschützen geschworen hat. So ergeht es denjenigen, die nicht verstehen, welchen Preis es für die große Macht zu zahlen gilt, die sie beschützt. Doch sie gehen mit erhobenem Haupt und gezückter Klinge voran. \r\n===Initiand (Ab Stufe 10)===\r\nInitianten haben schon viel über das Kämpfen und Vergießen von Blut gelernt, doch in ihrem Orden geht es um viel mehr. Die Beherrschung des Lichts erfordert einen klaren Geist und enorme Willenskraft. Ohne diese Eigenschaften ist man nicht mehr wert als ein räudiger Streuner. Als Initiand hat man hart an sich gearbeitet, um die Macht des Lichts zu beherrschen, über die sie Dank der Magister verfügen. Man weiß von der Quelle der Fähigkeiten und alles über die Pflichten eines Blutritters.\r\n===Adept (Ab Stufe 20)===\r\nMit der zweiten Prüfung wird man um diesen Rang kämpfen. Diese findet unter der Aufsicht von Meister Kelerun Blutpein im nördlichen Teil von [[Silbermond]] statt. Sie unterscheidet sich vor allem dadurch von der Ersten, dass den Prüfling keine unliebsamen Überraschungen mehr erwarten. Die Aufgabe ist einfach; man muss sich gegen die vier besten Champions der '''Blutritter''' im Kampf beweisen. Viele versuchen sich an dieser Prüfung, doch nur die Wenigsten kehren zurück, um von ihrem Erfolg zu berichten. Die verbleibenden Pflichten sind größtenteils zeremonieller Natur und doch sind sie nicht weniger gefährlich, als der Versuch, mit bloßen Fäusten gegen einen der Champions zu bestehen. Bevor ein frischgebackener Adept in die Ränge der Blutritter aufgenommen wird, muss er die Materialien beschaffen, die zum Schmieden der besonderen Waffe des Ordens benötigt werden: dem blutgehärteten Ranseur. Man muss sich außerdem das Recht verdienen, die Insignie des Ordens zu tragen. Bei der Gründung des Ordens wurde eine begrenzte Zahl dieser Insignien geschmiedet und verteilt, jeder Adept erbt seine Insignie von einem Veteran. Mit dem Stand eines Adepten der Blutritter ist man dann ein vollwertiges Mitglied des Ordens. Adepten verhalten sich weiterhin vorbildlich, zeigen keine Gnade oder Schwäche, verteidigen unermüdlich ihr Volk und ihre Brüder und verfeinern ihre Beherrschung des Lichts. \r\n===Champion (Ab Stufe 50)===\r\nChampions erinnern sich an Vergangenes, das nicht vergessen werden sollte... das Abschlachten ihres Volkes durch [[Arthas]] und seine Armeen der [[Geißel]]. Rache an der [[Geißel]] ist der einzige Weg, ihren Schmerz zu lindern. Es ist bedauerlich, dass sie keine Angst und keinen Schmerz empfinden können. Nur ihre Vernichtung kann dem Champion einen Hauch von Genugtuung bringen. Sie führen die Waffe „Geißelbann“, doch sie müssen Acht geben, wenn sie es benutzten, denn es dient ihnen gegen seinen Willen. In Geißelbann ist eine Fäulnsiranke von Atal'alarion aus dem [[Versunkener Tempel|Versunkenen Tempel]] eingewebt.\r\n===Meister (Ab Stufe 60)===\r\nInnerhalb des Ordens existiert ein eingeschworener Zirkel von Eliterittern. Die Mitglieder des Zirkels repräsentieren die Hingebungsvollsten, Fähigsten und Vertrauenswürdigsten aller Blutritter, allesamt handverlesen und vereidigt durch die Ordensführung. Diese Meister sind leicht an ihrem [[Thalassisches Streitross|thalassischen Schlachtross]] zu erkennen. Jeder Kandidat, der sich um die Aufnahme in diese erlesene Gemeinschaft bewirbt, benötigt einen Fürsprecher aus den Reihen des Zirkels und muss seine Hingabe für die zentralen Grundsätze des Ordens unter Beweis stellen. Ein Meister der Blutritter besitzt unglaubliche Fähigkeiten, das Licht auf eine Art zu nutzen und zu formen, wie es die so genannten anderen '[[Paladin]]e' nie verstehen werden. Das hält die menschlichen [[Paladin]]e jedoch nicht davon ab, die Blutritter dafür zu ächten, wie sie das wahre Potential des Lichts entfesseln. Doch mit Blutrittern spielt man keine Spielchen...\r\n===Ritterfürst===\r\nDer Ritterfürst ist der Rang eines Truppenkommandanten. \r\n'''Quellenangabe'''",},
			["Blutritter Morgenstern"] = { content = "'''Blutritter Morgenstern''' war der Anführer des fehlgeschlagenen Angriffs auf die [[Todesfestung]] in den [[Geisterlande]]n. Seine Leiche findet man noch dort.",},
			["Blutschläger"] = { content = "#REDIRECT [[Blutschlägeroger]]", redirect = "Blutschlägeroger",},
			["Blutschlägerklamm"] = { content = "Die '''Blutschlägerklamm''' liegt im südlichen [[Schergrat]]. Hier leben die [[Oger der Blutschläger]], die sich ein Rudel [[Terrorwölfe]] als Wachhunde halten. Sie sind zwar nicht der einzige Stamm, der die [[Allianz]] bedroht, aber sie sind am nächsten. \r\nHier findet man auch einen Troll namens [[T'chali der Hexendoktor]]. T'chali war immer ein gediegener Troll. Er kam hierher, um seinen Freunden von den Blutschlägern beizubringen, wie man Bier braut. Aber T'chali hat ihnen nicht gesagt, warum. Die Blutschläger stecken ziemlich in der Klemme und da die [[Speerspießer]] drohen, sie zu zermalmen, brauchten die Blutschläger eine neue Waffe, um sie im Kampf zu unterstützen. Da kam T’chali auf eine tolle Idee. Warum nicht das perfekte Getränk brauen, das einen selbst stärkt und die Feinde schwächt? Der Haken ist nur, dass T’chali nicht weiß, ob es geklappt hat. Deswegen würde er das gern in einem Saufgelage ausprobieren und die Oger der Speerspießer betrunken zu machen.\r\nDoch dann haben die Blutschläger ihn hier begraben und lassen ihn hier verrotten. Das Schlimmste ist, dass sie seine Wasserpfeife und sein Hauweggebräu geklaut haben. Nun hat er beschlossen, dass er Rache an allen Ogern will. Also sollen seine Quäler, [[Grimnok Schlachttaufe]] und [[Korgaah]] sterben. Doch letztendlich verflucht er beide Klans ... Er war in seinem Leben ein mächtiger Hexendoktor und wenn man in sein Grab fasst, findet man dort einen verdammt mächtigen Fetisch mit dem man die Hütten beider Ogerstämme verlfluchen kann.",},
			["Blutschrei"] = { content = "'''Blutschrei''' ist die mächtige Zweihand-Axt von [[Grom Höllschrei]], einem der größten Helden der [[Orcs]]. Sie wurde von einem Anführer des [[Kriegshymnenklan]]s an den nächsten weitergegeben. Diese Waffe hat für Entsetzen auf hunderten von Schlachtfeldern gesorgt. Blutschrei kann in [[Karazhan]] von [[Prinz Malchezaar]] erbeutet werden.",},
			["Blutsegelbukaniere"] = { content = "==Allgemeines==\r\nDiese blutdürstigen Korsaren sind der Schrecken aller Handelsschiffe und Erzrivalen von [[Beutebucht]], die sich im gesamten Süden des [[Schlingendorntal]]s herumtreiben. Der Kampf zwischen den Blutseglern und den [[Schwarzmeerräuber]]n von [[Beutebucht]] tobt erbittert, denn wegen den Machthabern in [[Beutebucht]] können die Blutsegler nicht hinsegeln, wo sie wollen, und sich nicht das nehmen, was sie als Beute haben wollen.\r\n===Aktuelles===\r\nDie Blutsegelbukaniere planten ursprünglich einen Angriff auf [[Beutebucht]], doch die [[Schwarzmeerräuber]] erfuhren von ihren Angriffsplänen. Nun werden die Korsaren für ihre Sorglosigkeit teuer bezahlen, denn [[Beutebucht]] wird einen Gegenschlag starten, bevor sie überhaupt merken, was los ist. \r\n==Orte==\r\nBei Firallons Ankerplatz im [[Schlingendorntal]] liegt die Flotte der Blutsegelbukaniere und man findet ihre Führungskräfte. Am Wilden Ufer ist der südliche Kommandoposten der Blutsegelbukaniere.\r\n==Persönlichkeiten==\r\n* [[Flottenmeister Firallon]]\r\n* [[Kapitän Kielhol]]\r\n* [[Kapitän Stillwasser]]\r\n* [[Schönling Duncan]] stahl den Dolch von [[Catelyn die Klinge]].",},
			["Blutsegel Truppenlager"] = { content = "#REDIRECT [[Blutsegelbukaniere]]", redirect = "Blutsegelbukaniere",},
			["Blutskalp"] = { content = "#REDIRECT [[Trolle der Blutskalpe]]", redirect = "Trolle der Blutskalpe",},
			["Blutskalpe"] = { content = "#REDIRECT [[Trolle der Blutskalpe]]", redirect = "Trolle der Blutskalpe",},
			["Blutskalpstamm"] = { content = "#REDIRECT [[Trolle der Blutskalpe]]", redirect = "Trolle der Blutskalpe",},
			["Blutstein"] = { content = "Es gibt eine Berghöhle in der [[Schlucht der Trockenstoppel]], weit im Norden des [[Arathihochland]]s. In dieser Höhle findet sich ein seltenes Erz: Blutstein. Der Blutstein in dieser Höhle ist zwar nicht von höchster Qualität, aber auch Blutstein von minderer Qualität ist wertvoll für diejenigen, die wissen, wie er zu nutzen ist.",},
			["Blutsteinerz"] = { content = "#REDIRECT [[Blutstein]]", redirect = "Blutstein",},
			["Blutwacht"] = { content = "Die Blutwacht ist ein Stützpunkt der [[Allianz]] auf der [[Blutmythosinsel]]\r\nMan findet die Blutwacht die Straße entlang, in Richtung Norden. Die Blutwacht ist einer von zwei Vorposten, die der [[Hand von Argus]] als Operationsbasen dienen, denn die [[Draenei]] brauchen unbedingt einen Ort, an dem Verwundete versorgt und Reisende empfangen werden können. Sie konnten dieses Wrackteil bergen und für das Gebäude verwenden, allerdings ist das Gasthaus lediglich ein besseres Zelt, ohne die entsprechende Einrichtung und die Notvorräte. Mit so wenigen Ressourcen müssen sie sich auf ihren Einfallsreichtum verlassen, um versorgt zu sein. Sie haben ihre Läden mit Fleisch ausgestattet, das von Bären stammt, die auf dieser Insel umherstreifen. Wenn man es richtig zubereitet, kann es bedenkenlos verzehrt werden. Ein guter Förster findet für jede der vorhandenen Ressourcen eine Verwendung. Auch die skurrilsten Kreaturen besitzen Eigenschaften, die sie zum Vorteil nutzen können. Da die Blutwacht ständig von den [[Blutelfen der Sonnenfalken]] angegriffen wird, suchen sie nach einer Vielzahl natürlicher Verteidigungsmechanismen, die auch als Fallen dienen können.\r\n==Persönlichkeiten==\r\n* '''Anachoret Paetheus''' - Anachoret Paetheus hat eine Sammlung verschiedenster Artefakte, die die [[Draenei]] während ihrer Reisen entdeckten und kann bei der Entzifferung von alten Büchern und Schriften helfen.\r\n* '''Ausgrabungsleiter Nachlan''' - Ausgrabungsleiter Nachlan ist Mitglied der [[Forscherliga]]. Diese hat ihn von einer vielversprechenden Grabung abgezogen und mit [[Odesyus' Ankerplatz|Odesyus' Expedition]] losgeschickt, um das Kindermädchen für den kleinen Gnom [[Klopper Knacksklug]] zu spielen. Er hat noch nie von einem [[Gnom]] gehört, der Ausgrabungsleiter werden wollte, aber scheinbar nehmen sie jetzt auch [[Gnome]].\r\n* '''Exarch Admetius''' - Exarch Admetius koordiniert die Verteidigung der Blutwacht.\r\n* '''Herold Mikolaas''' - Herold Mikolaas' hauptsächliche Sorge gilt der Verteidigung des Außenpostens, aber ihre Anführer bei der [[Exodar]] haben ihm auch zahlreiche andere Pflichten überantwortet. Das Problem ist nur, dass es eigentlich zu unsicher ist, eine große Anzahl von Forschern auszusenden, wenn die Insel so gefährlich ist. Herold Mikolaas hat bei der Sicherung der Blutwacht eine äußerst löbliche Arbeit geleistet, allerdings sind die Feinde zahlreich und die Ressourcen gering. Die Gegner kennen ihre Schwäche nur zu gut, aber sie haben dabei nicht an die Verbindung zu den Streitkräften der [[Allianz]] gedacht. \r\n* '''Morae''' - Morae verfolgt ein paar Theorien über die [[Murlocs]] im Westen an der Küste. Bis vor kurzem konnte er das Ganze jedoch noch nicht untersuchen. Er hat eine Methode entwickelt, die es ihm ermöglichen wird, die für ihn interessanten [[Murlocs]] im Auge zu behalten, ohne ihnen dadurch längerfristig zu schaden oder man natürliches Verhalten zu stören. \r\n* '''Vernehmungsbeauftragte Elysia''' - Vernehmungsbeauftragte Elysia ist die hochrangigste Vernehmungsbeauftragte der Blutwacht.",},
			["Blutwärter"] = { content = "#REDIRECT [[Blutritter]]", redirect = "Blutritter",},
			["Blutwärter des Sonnenzorns"] = { content = "#REDIRECT [[Blutritter]]", redirect = "Blutritter",},
			["Blut Unschuldiger"] = { content = "[[Apotheker Lydon]] von der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] hilft der [[Horde]] in [[Kalimdor]], ihr Problem mit der [[Venture Company]] im [[Steinkrallengebirge]] zu lösen. Dafür wird er ein Toxin herstellen, mit dem sie der [[Venture Company]] die Gewalt entziehen und sie schwach und sanftmütig werden lassen. Um das Toxin herzustellen, benötigt er jedoch das Blut Unschuldiger. Wenn man das Toxin gegen die [[Venture Company]] einsetzt, sollte es positive, vielleicht sogar ansteckende Ergebnisse erzielen. [[Apothekerin Zamah]] in [[Donnerfels]] muss jedoch noch eine Anwendungsmethode für das Toxin entwickeln, um einen größtmöglichen Effekt zu erzielen.",},
			["Bogenschützin"] = { content = "#REDIRECT [[Nachtelfenjäger]]", redirect = "Nachtelfenjäger",},
			["Bogens Kante"] = { content = "'''Bogens Kante''' ist eine bewaldete Gegend im [[Hinterland]], westlich von [[Shadra'Alor]]. Sie zählt zum Territorium der [[Trolle der Bleichborken]] und [[Hexendoktor Mai'jin]], einer ihrer Anführer, befindet sich hier in einer Höhle. Er steckt hinter den Raubzügen der Bleichborken auf die [[Greif]]en im Gebiet des [[Wildhammerklan]]s.",},
			["Bollwerk"] = { content = "\r\nDas '''Bollwerk''' ist ein Außenposten der [[Horde]] am östlichen Rand von [[Tirisfal]], wo die [[Verlassene]]n zusammen mit der [[Argentumdämmerung]] gegen die [[Geißel]] aus den [[Pestländer]]n kämpfen. Die Verteidiger auf dem Bollwerk, die [[Tirisfal]] vor den [[Pestländer]]n schützen, sind immer wachsam, aber manchmal schafft es die [[Geißel]], an ihnen vorbeizuschlüpfen. Ihr Erfolg am Bollwerk hängt an einer Ein-Fronten-Schlacht - sie können keinen Angriff von hinten zulassen, und noch weniger können sie zulassen, dass die Versorgungslinie ihrer Verteidiger unterbrochen wird.\r\n==Personen==\r\n* [[Alexi Barov]]\r\n* '''Apotheker Zitters''' - Apotheker Zitters weiß viel über die [[Scholomance]] und hat eine Idee, wie der [[Skelettschlüssel]] dafür zu erlangen ist. \r\n* '''Argentumrüstmeister Hasana''' - Argentumrüstmeister Hasana wurde ermächtigt, denen die sich als würdig erwiesen haben, einige der wertvollsten Gegenstände der Dämmerung anzubieten.\r\n* '''Bardu Scharfblick''' - Bardu Scharfblick ist ein Taure und hat hier am Bollwerk sein Lager aufgeschlagen, um sich auf seine Reise in die [[Pestländer]] vorzubereiten. Er hat Gerüchte gehört, denen zufolge sich vor nicht allzu langer Zeit ein großer Hexer, ein Mensch übrigens, in [[Herdweiler]] niedergelassen haben soll. Er sei vom [[Scharlachroten Kreuzzug]] beauftragt worden, für deren Krieger und Jäger neue Bögen und Schußwaffen herzustellen. Es heißt, dass er eine erstaunliche Waffe konstruiert habe. ehe der Kreuzzug ihn tötete. Bardu vermutet mal, ihr Misstrauen gegenüber dem Arkanen ist gewachsen.\r\n* '''Hochexekutor Derrington''' - Hochexekutor Derrington leitet den Stützpunk der [[Horde]] am Bollwerk und koordiniert ihr Vorgehen.\r\n* '''Mehlar Dämmerklinge''' - Mehlar Dämmerklinge war einst war er ein Schüler von [[Uther Lichtbringer]], dem Gründervater des Ritter-[[Orden der Silbernen Hand]]. Er sah Uthers Versagen bei der Ausbildung von Prinz [[Arthas]]. Es führte zu der Zerstörung seines Heimatlandes, [[Quel'Thalas]], und er gibt Uther die alleinige Schuld daran. Und nun ruht er in einem Grabmal, das zu seinen Ehren erbaut wurde. Mehlar will das Mal des Lichtbringers haben, dem er etwas dämonische Magie hinzugefügt hat, und Uthers Grabmal damit entweiht sehen. \r\n* '''Mickey Levine''' - Mickey Levine möchte Schmerz und Unfrieden über den [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzug]] bringen und ihnen ihr wertvolles [[Sägewerk]] wegnehmen. Er ist sich sicher, der Verlust einer solchen Ressource ihnen ziemlichen Schaden in Bezug auf Verteidigung und Wiederaufbau der Stadt für ihre Zwecke zufügen wird. \r\n* '''Schattenpriesterin Vandis''' - Schattenpriesterin Vandis leitet die Schlacht um die Geißelkessel in den [[Westliche Pestländer|Westlichen Pestländern]]",},
			["Booty Bay"] = { content = "#REDIRECT [[Beutebucht]]", redirect = "Beutebucht",},
			["Borak"] = { content = "#REDIRECT [[Borak Herzeleid]]", redirect = "Borak Herzeleid",},
			["Boreanische Tundra"] = { content = "Die weite '''Boreanische Tundra''' erstreckt sich vom Westufer des [[Lake Wintergrasp]] bis zur südwestlichsten Spitze von [[Nordend]], dem eisigen Kontinent, der als Dach der Welt bekannt ist. Die stets verschneite und vereiste Landschaft wird nur durch ein paar wenige Bäume durchbrochen. Im Westen und Osten brandet das Meer gegen scharfkantige Felsen und kein Schiff könnte hier vor Anker gehen. [[Allianz]] und [[Horde]] bereiten sich auf einen Schlag gegen den [[Lichkönig]] und seine untoten Armeen vor. Sie sind weit gereist, um nach [[Nordend]] zu gelangen und doch stehen den unerschütterlichen Pionieren die wahren Herausforderungen erst noch bevor. (Quelle: \r\n==Fraktionen==\r\n* '''Allianz''' - Die [[Allianz]] ist hier mit einem kleineren Posten vertreten. \r\n* '''Horde''' - In den letzten Monaten hat die [[Horde]] hier die Vorherrschaft errungen.\r\n* '''Naga''' - Das hinterlistige Schlangenvolk der [[Naga]] benutzt riesige Generatoren, um die umliegenden Gletscher und Eiskappen zu schmelzen, und droht, dadurch das gesamte Gebiet zu überfluten. \r\n* '''Taunka''' - [[Garrosh Höllschrei]] und seine orcischen Streitkräfte trafen auf die rätselhaften [[Taunka]], eine uralte Blutlinie der [[Tauren]], die man bis heute für ausgestorben hielt. \r\n* '''Tuskarr''' - Kurz nach ihrer Ankunft traf die [[Horde]] auf die [[Tuskarr]], ein Volk von walrossähnlichen nomadischen Fischern. Seitdem sind die beiden Gruppen ein Bündnis eingegangen, und die [[Horde]] hat geschworen, ihre neuen Verbündeten auf jede erdenkliche Weise zu unterstützen. \r\n==Orte==\r\n* Der [[Nexus]] (Dungeon)\r\n* [[Echoküste]]\r\n* [[Kaltarra]]\r\n* [[Kaskala]]\r\n* [[Kriegshymnenfeste]]\r\n* [[Ruinen der Peitschennarbe]]\r\n* [[Tal der Westklamm]]\r\n* [[Valianzfeste]]",},
			["Borel"] = { content = "Borel hat viele Namen. In den Warcraft-Romanen taucht er häufig unter dem Namen [[Krasus]] auf, wenn er sich als Elf bei den [[Kirin Tor]] tummelt. In Wirklichkeit heißt er [[Korialstrasz]] und ist der Gefährte von [[Alexstrasza]], der Königin des [[Roter Drachenschwarm|Roten Drachenschwarms]] und Aspekt des Lebens auf [[Azeroth]]. In der Comic-Trilogie \"Warcraft: The [[Sunwell Trilogy]]\" ist er der Uhrheber des Schicksals um [[Anveena]], denn sie entstand ursprünglich als Gefäß für die Macht des [[Sonnenbrunnen]]s, um diese vor dem [[Lichkönig]] zu verstecken. Borel rechnete nicht damit, dass [[Anveena]] einmal ein eigenes Leben führen würde, das das Schicksal des [[Sonnenbrunnen]]s fast besiegelt hätte.\r\n'''Quelle:'''",},
			["Borklinge"] = { content = "Die '''Borklinge''' sind [[Treants]] im [[Immersangwald]]. Seit Jahrzehnten sind sie die Verbündeten der [[Blutelfen]] und versuchen den niedergebrannten Wald am [[Versengter Hain|Versengten Hain]] wieder aufzuforsten. Einst halfen die Borklinge die Pflanzenwelt der [[Insel der Sonnenwanderer]] zu erhalten, aber jetzt sind sie außer Kontrolle geraten und werden als Bestien angesehen, die vernichtet werden müssen. \r\n==Persönlichkeiten==\r\n* [[Weißborke]]",},
			["Borondil Wolfsaxt"] = { content = "Borondil ist ein [[Die einsamen Wölfe|einsamer Wolf]] und zieht oft alleine, nur von seiner begleitet, durch die Lande. Doch in letzter Zeit hält er sich vermehrt in der Nähe der jungen [[Priester]]in [[Belaná]] auf.",},
			["Botanika"] = { content = "#REDIRECT [[Festung der Stürme: Botanika]]", redirect = "Festung der Stürme: Botanika",},
			["Botschafter Höllenschlund"] = { content = "Botschafter Höllenschlund \r\n'''Botschafter Höllenschlund''' ist eine [[Verdammniswache]] und der erste Bossgegner im [[Schattenlabyrinth]]. \r\n==Fähigkeiten==\r\n* '''Ätzende Säure''' - Botschafter Höllenschlund verspeit eine ätzende Säure, die alle 3 Sekunden 1094 bis 1406 Naturschaden verursacht und die Rüstung um 3938 bis 5062 verringert. Dieser Effekt hält 15 Sekunden lang an.\r\n* '''Furcht''' - Botschafter Höllenschlund erfüllt regelmäßig alle Gegner im Umkreis von 45 Metern mit Furcht, woraufhin sie bis zu 6 Sekunden lang voller Schrecken flüchten.",},
			["Botschafter Infernus"] = { content = "Botschafter Infernus ist ein Feuerelemantar im [[Ödland]]. [[Ragnaros]] persönlich schickte den Gesandten Infernus zur Festung Angor, damit er dort die Suche der Zwerge der Schattenschmiede nach verschollenen Artefakten in [[Uldaman]] organisiert.",},
			["Botschafter Malcin"] = { content = "'''Botschafter Malcin''' ist ein Diplomat der [[Geißel]] bei den [[Hügel der Klingenhauer|Hügeln der Klingenhauer]]. Dieser [[Verlassene]] ist einer der von der Geißel verseucht wurde. Einst war Malcin ein menschlicher Diplomat des Königreichs [[Lordaeron]], bevor sich alles verändert hat. Dieser Diplomat scheint Untote als Möchtegernanhänger zu betrachten. Tag für Tag kriechen die [[Stacheleber der Klingenhauer]] aus den Schatten und betteln ihn nahezu um mehr Macht an. Die Gelegenheit, das [[Brachland]] und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten. Er wird sich bis auf weiteres abseits der Hügel der Klingenhauer aufhalten. Seine Anwesenheit dort erklärt vieles von dem, was die Verlassenen über diese Gegend herausgefunden haben - einige der Stacheleber sind beängstigend stark geworden und zeigen erste Symptome der Seuche. Das muss in der Tat ein Anzeichen dafür sein, dass sie irgendeine Übereinkunft getroffen haben.",},
			["Brachland"] = { content = "== Allgemeines==\r\nDas Brachland von [[Kalimdor]] ist eine trockene, einsame Einöde - entlang der Karawanenstraßen finden sich jedoch vereinzelte Oasen. Trotz der harten Lebensbedingungen, haben sich auf den weiten Ebenen viele unterschiedliche Völker angesiedelt. Die barbarischen [[Zentauren]] terrorisieren und überfallen unablässig Dörfer und Städte der eingeborenen Landbevölkerung. Die [[Tauren]] behaupten sogar, sie hätten schon immer als [[Geißel]] des Brachlandes existiert. Arglose Karawanen und unbedachte Reisende laufen aber auch Gefahr, in einen Hinterhalt der bösartigen [[Harpyie]]n gelockt zu werden. \r\n===Fauna===\r\nDas Brachland hält für die Unvorbereiteten und Unachtsamen große Gefahren bereit, denn die Wildtiere im Brachland sind willensstark und unglaublich wild. Die [[Ebenenschreiter]] im Osten fallen immer wieder über [[Wegekreuz]] Lebensmittelvorräte her und sind zu einer Plage geworden.\r\n===Flora===\r\nDie Kräuter des Brachlandes sind anders als Kräuter anderer Länder. Ihre Eigenschaften sind zwar fast dieselben, aber das Wasser der [[Brachland Oasen]] hier verändert sie.\r\n==Instanzen==\r\n* [[Höhlen des Wehklagens]] (Dungeon)\r\n* [[Hügel der Klingenhauer]] (Dungeon)\r\n* [[Kral der Klingenhauer]] (Dungeon)\r\n==Orte==\r\n* [[Bael Modan Ausgrabung]]\r\n* [[Brachland Oasen]]\r\n* [[Camp Taurajo]]\r\n* [[Feld der Riesen]]\r\n* [[Felsadermine]]\r\n* [[Mor'shan-Stützpunkt]]\r\n* [[Ratschet]]\r\n* [[Wegekreuz]]\r\n===Fernwacht===\r\nDie Fernwacht ist eine Orcgarnison an der Grenze von Brachland und [[Durotar]].\r\n===Feste Nordwacht===\r\nDie Fanatiker aus [[Theramore]] in der Feste Nordwacht sind verrückt. Ihr Verfolgungswahn hat sie in eine Art Raserei versetzt. Diese schießwütigen, rücksichtslosen Rüpel schießen auf alles, was sich bewegt. Der Hochelf '''Gilthares Feuerzweig''' war Decksmann auf einem Fuseltransporter zwischen [[Ratschet]] und [[Beutebucht]]. Die Fanatiker aus [[Theramore]] haben sein Schiff versenkt und ihn, den einzigen Überlebenden, eingesperrt. Sie nannten ihn ihren Feind und eine Gefahr für die [[Allianz]].\r\n===Glutnebelgipfel===\r\nDer Glutnebelgipfel nordwestlich des Wegekreuzes ist höchstwahrscheinlich die Quelle, von wo aus sich ein Gift auf das Land verbreitet. Auf seinen luftigen Höhen gibt es Teiche, die das Wetter beeinflussen. Dieses Wasser wurde vermutlich durch [[Dämonen]] anbetende Kultisten der [[Brennende Klinge|Brennenden Klinge]] verunreinigt. Die Dämonensaat ist ein mächtiges Werkzeug der Brennenden Legion. Es befindet sich in einer Höhle des Glutnebelgipfels, oberhalb eines dämonischen Altars des Feuers. \r\n===Händlerküste===\r\nDie Küste des Brachlandes ist in den Händen der [[Menschen]]. An der Küste im Süden findet man die Tide Razor, das Schiff der [[Südmeerfreibeuter]]. Unten im Laderaum findet man den Schatz der [[Südmeerfreibeuter]]. Auf dem zweiten Deck des Schiffes findet man die Piratenhöhle, dort bilden sie ihre Diebe aus.\r\n* Die Taurin '''Islen Wasserdeuter''' findet man südlich von Ratschet, versteckt entlang des Ufers in einem kleinen Lager direkt am Wasser. Sie ist eine mächtige Schamanin und ihre Verbindung zu den Geistern des Wassers war immer stark. \r\n* Der Troll '''Tazan''' treibt Handel mit den Piraten bei Ratschet. Er wandert die Händlerküste entlang. Er hatte einen Assistenten namens Gamon in Orgrimmar.\r\n===Mondkinstein===\r\nAuf Land westlich von Taurajo im Brachland - kurz bevor es in [[Mulgore]] übergeht - liegt ein [[Eulenbestien|Mondkinstein]]. [[Eulenbestien|Mondkin]] sind besondere Tiere, die nicht in diesen Breiten heimisch sind. Mondklaue, der Verteidiger des Steins, stellt sich, wenn Lunarstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die man als [[Druide]] der Klaue benutzen muss.\r\n===Prügelinsel===\r\nVor der Küste des Brachlandes, südlich von [[Ratschet]], liegt das Prügeleiland - ein Treffpunkt für [[Krieger]]. Um es zu erreichen, muss man nach den Sandbankuntiefen entlang der Händlerküste suchen und wenn man hier lernen will, muss man zuerst den Ringkampf absolvieren. Das ist eine Herausforderung, an der sie aufstrebende [[Krieger]] teilnehmen lassen, die sich für gut genug halten. Klannoc Macleod ist der oberste [[Krieger]] der Insel. \r\n===Raptorgründe===\r\nMan hat Berichte darüber, dass die [[Raptoren]] eine große Ansammlung von Nestern südlich von Ratschet haben, Raptorgründe genannt. Es ist sehr wahrscheinlich, dass sie das gestohlene Silber vom [[Wegekreuz]] dorthin gebracht haben.\r\n===Schlickermoor===\r\nEin Jahr lang hat die [[Zerschmetterte Hand]] daran gearbeitet, Zuchtmeister Fitzel als Agenten in die Reihen der [[Venture Company]] einzuschleusen. Endlich hatten sie - dank harter Arbeit und präziser Planung - Erfolg. Vor kurzem haben sie jetzt gehört, dass die [[Venture Company]] irgendetwas Großes plant. Zuchtmeister Fitzel überwacht diesen Turm jetzt schon seit Wochen. Kürzlich kam eine größere Lieferung aus dem [[Dämmerwald]] an und mit dieser Lieferung kamen auch diese Wachen. Menschen sind das nicht. Es handelt sich um mutierte Drohnen, Patrouillen und Ausgucker von den [[Defias]]. Bei der Lieferung war eine Truhe dabei und das ist es, was diese Monstrositäten bewachen. Die Kreatur mit den Stacheln hat einen Schlüssel. \r\n===Trockene Hügel===\r\nDie [[Harpyien der Hexenschwingen]] haben die Karawanen vom [[Wegekreuz]] lange geplündert. Die [[Harpyien]] stammen nicht aus dem Brachland. Sie kommen aus dem [[Steinkrallengebirge]].",},
			["Brachland Oasen"] = { content = "Vor langer Zeit war das [[Brachland]] ein üppiger Ort voller Leben. Aber Krieg und Katastrophen verheerten das Land, verbrannten es und jetzt ist es nur noch eine ausgedörrte Hülse. In den letzten Jahren jedoch sind Oasen im [[Brachland]] entstanden und das Leben blüht wieder auf. Und die [[Druiden]] spüren eine Macht von ganz tief unten an die Oberfläche dringen. Sie müssen ihre Quelle finden, deshalb suchen sie in den dortigen Gewässern nach einer Quelle der Macht. Die Oasen des Brachlandes verbergen ein Mysterium, denn in ihren Wassern fließt Lebensenergie, die alle Pflanzen und Wildtiere erquickt, die davon trinken. Erquickt und verändert. Diese Oasen haben Eigenschaften, die von einer Quelle außerhalb stammen müssen. Oder vielleicht von einer inwärtigen. Und die [[Druiden]] wollen wissen, auf welche Weise diese Felsspalten die Wildtiere beeinflussen, die vom Wasser der Oasen trinken. Die [[Druiden]] spüren aber auch die Verwirrung, die sie über das Land bringen. Es ist, als würde das Land träumen und nicht erwachen können ... Die [[Höhlen des Wehklagens]] müssen die Quelle dieser Besudelung sein.\r\n===Blühende Oase===\r\nEs gibt einen Pilz, der in der Nähe dieser Oasen wächst. Seine Sporen besitzen Eigenschaften, die die [[Apotheker]] [[Lordaeron]]s, sehr nützlich finden.\r\n===Brackige Oase===\r\nDie Schalen der [[Oasenschnappkiefer]] in der blühenden Oase haben eine Besudelung, die man nie zuvor gesehen hat. Man ist sich sicher, dass das Wasser der Oasen der Grund dafür ist. \r\n===Vergessene Teiche===\r\nErdrisse wie jene, die man bei den vergessenen Teichen gefunden hat, könnte es auch bei anderen Oasen im Brachland geben. Wenn es so ist, sind diese Risse vielleicht die Lebensquelle dieser Oasen.\r\n* '''Regthar Totenfurt''' - Regthar Totenfurt lebt in einer Reihe von Bunkern westlich des [[Wegekreuz]]es bei den Oasen. Er ist ein Krieger der [[Horde]] und rekrutiert Agenten für einen Einsatz im Land [[Desolace]]. Außerdem kümmert er sich um die [[Zentauren]]-Bedrohung.",},
			["Brackbrunns Kürbisbeet"] = { content = "Brackbrunns Kürbisbeet ist eine große Farm im östlichen [[Wald von Elwynn]] und wird derzeit von den [[Defias]] kontrolliert.\r\nDie Brackbrunns haben ein Schwein, eine Sau namens Prinzessin, die schon viele Preise gewonnen hat. Dass dieses Tier so riesig geworden ist, kommt nur daher, dass es immer auf den [[Wald von Elwynn|Hof der Steinfelds]] herübergeschlichen kommt und das Gemüse frisst. Man findet Prinzessin normalerweise bei Brackbrunns Kürbisbeet, noch hinter dem [[Wald von Elwynn|Hof der Maclures]] und von dort aus im Osten gesehen.\r\n==Personen==\r\n* '''Der \"Sammler\"''' wird von Marschall Dughan in [[Goldhain]] gesucht. Er entnimmt Gold aus den Minen und bestiehlt damit das Königreich. Im Abholplan steht, dass der Sammler sich bei Brackbrunns Kürbisbeet versteckt hält. Bei dem Zeitplan des Sammlers handelt es sich um eine Tabelle mit Daten und Zeiten, zu denen jemand, der in der Notiz nur als \"der Sammler\" bezeichnet wird, je eine Lieferung Gold aus den Minen des [[Wald von Elwynn|Waldes von Elwynn]] erhalten soll. \r\n* '''Erlan Tragmehr''' gehört zur [[Defias]]-Bruderschaft und ist der Geliebte der Hexerin Surena Caledon.\r\n* '''Surena Caledon''' ist eine Studentin von Gakin dem Dunkelbinder in [[Sturmwind]]. Sie brannte darauf, die [[Hexenmeister]]magie zu lernen, und ihr Talent war nicht von schlechten Eltern. Mehr als das, sie war jung und eine wahre Augenweide. Doch das diebische Weib brannte mit einem der [[Defias]] durch, Erlan Tragmehr. Gakin der Dunkelbinder schenkte ihr einen Blutsteinhalsschmuck. Surena war begabt, aber nicht so sehr, dass sie die [[Hexenmeister]]magie selbst gemeistert hätte.",},
			["Brackenwall"] = { content = "Brackenwall ist der Stützpunkt der [[Horde]] in den [[Düstermarschen]]. Die [[Oger der Steinbrecher]] hier sind aus ihrem Dorf geflohen. Manche meinen sie seien für nichts außer dreckige Witze, bitteres Bier und Wettkämpfe im Köpfe-aneinander-Schlagen zu gebrauchen. Doch die Anwesenheit der Spitzel von [[Theramore]] werden sie auf keinen Fall dulden.\r\n==Personen==\r\n* '''Baladar Sternenlicht''' - Baladar Sternenlicht ist ein [[Blutelf]]. Als sein Schiff, die [[Morgenbö]], untergegangen ist, haben sich die Leute von [[Theramore]] mit seiner Ladung und dem letzten überlebenden Crewmitglied aus dem Staub gemacht. Er hat sich auf der Suche nach Hilfe hierher begeben, aber die [[Oger]] haben ihn nur dumm angeschaut, als er ihnen erzählt hat, was passiert ist. Er möchte deshalb, dass man die Fracht der [[Morgenbö]] wiederholt und seinen Ersten Maat [[Ithania]] von den Streitkräften von [[Theramore]] in der [[Nordwacht]] befreit.\r\n* '''Balai Lok'Wein''' - Balai Lok'Wein verkauft Schriftrollen und Tränke. \r\n* '''Draz'Zilb''' - Draz'Zilb scheint der Einzige zu sein, der die Ursache der Aggression in ihrer alten Heimat herausfinden möchte. Nebenbei möchte er auch noch Oberanführer Mok'Morokk verjagen.\r\n* '''Krog''' - Krog wurde vom Kriegshäuptling [[Thrall]] beauftragt, den Brand im [[Gasthaus \"Zur süßen Ruh\"]] aufzuklären.\r\n* '''Nazeer Blutlanze''' - Nazeer Blutlanze ist ein orcischer Spionagemeister, der die Umstände von Margs Tod erfahren will. \r\n* [[Oberanführer Mok'Morokk]]\r\n* '''Ogron''' - Ogron ist ein Oger, der von [[Krog]] in [[Brackenwall]] losgeschickt wurde, um [[Leutnant Paval Reethe]] ausfindig zu machen. Er brach von Brackenwall aus nach Südosten in Richtung der Hauptstraße durch die Marschen auf. Es hat lange gedauert, aber Ogron fand Reethe schließlich. Für einen Menschen hatte dieser sich gut versteckt. Doch Ogron hat Angst, nach der langen Zeit im Sumpf könnte Reethe verrückt sein. Er möchte, dass jemand mit ihm kommt, denn er braucht Antworten von ihm.\r\n* '''Tharg''' - Tharg ist ein Oger und [[Schwarzer Drachenschwarm|Schwarze Großdrachen]] haben seine Frau getötet. Nun ringt er mit den [[Dämonen]] des Kummers und der Rache und buhlt um die Führerschaft des Klans. Er will Rache. Er will nach Hause.",},
			["Brann Bronzebart"] = { content = "Brann Bronzebart ist der Bruder von König [[Magni Bronzebart]] und dem vor einigen Jahren von [[Arthas]] getöteten [[Muradin Bronzebart]]. Brann war ein aktives Mitglied der [[Forscherliga]] und trat damit in die Fußstapfen seines großen Bruders [[Muradin|Muradin Bronzebart]], der eines der Gründungsmitglieder der [[Forscherliga]] war. \r\nAls einer der größten Forscher, die je durch die Länder von [[Azeroth]] zogen, war Brann Bronzebart auf der ganzen Welt ein bekannter und gern gesehener Gast. Der warmherzige, tapfere [[Zwerg]] hatte Freunde in fast jedem erforschten Land – und in den unerforschten vermutlich auch. Brann kartografierte viele Jahre lang die entlegenen Ecken und Winkel der östlichen Königreiche für seine geliebte [[Forscherliga]]. Nach der Entdeckung [[Kalimdor]]s gehörte Brann zu den ersten [[Zwerge]]n, die auf den unbekannten Pfaden der Vorfahren wandelten. \r\nÜber Branns jüngstes Verschwinden weiß man wenig, abgesehen von der Tatsache, dass er zum Kontinent [[Nordend]] unterwegs war, um den Tod seines Bruders [[Muradin Bronzebart]] aufzuklären. Es ist unbekannt, ob er die eisige Küste dieses Landes jemals erreichte.\r\n==Brann Bronzebarts verlorener Brief==\r\nIn [[Silithus]] findet man Brann Bronzebarts verlorenen Brief. Darin steht, dass die meisten seiner Männer schon tot sind und Brann Informationen über einen [[Titanen]] entdeckt hat, über eine große Schlacht zwischen ihm und einem [[Alte Götter|alten Gott]]. Die Forscher seines Trupps haben einen uralten Tunnel nach [[Ahn'Qiraj]] entdeckt, dem er jetzt folgt.\r\n==Stab von Atiesh == \r\nDer Stabfuß von [[Atiesh]] wurde von Brann Bronzebart, gehalten, als er [[Ahn'Qiraj]] betrat. Er hat [[Ahn'Qiraj]] zwar inzwischen wieder verlassen, den Stabfuß von [[Atiesh]] jedoch zurückgelassen.",},
			["Brauenwirbels Kürbishof"] = { content = "''\"Das ganze Feld war voller Rowdys.\"'' (Bauer Brauenwirbel)\r\nBrauenwirbels Kürbishof im Osten von [[Westfall]] an der Grenze zum [[Wald von Elwynn]] gehört zu den vielen verlassenen Gehöften in dieser Gegend. Neuerdings wurden dort jedoch Fallensteller der [[Defias]] gesichtet ... Genaugenommen wimmelt es in den Feldern nur so von Dieben und es ist hier viel zu gefährlich geworden. Sobald Bauer Theodore Brauenwirbel den Wagen repariert hat, machen sich die verbleibenden Bewohner auf den Weg, zuvor möchte er jedoch, dass man seine Taschenuhr holt. Sie befindet sich im Kleiderschrank des Bauernhauses auf der Kürbisfarm im Westen. Die Bauern sind in großer Eile aufgebrochen und da hat er vergessen, seine Taschenuhr einzupacken. Die Uhr hat ihm Vernas Vater an ihrem Hochzeitstag geschenkt und es wird ihm fast schlecht, wenn er daran denkt, dass diese Diebe sie jetzt haben.",},
			["Braufest"] = { content = "* '''Typ''': Braufest \r\n* '''Datum''': 20. September - 04. Oktober 2008\r\n* '''Ort''': Hauptveranstaltung in [[Orgrimmar]] und [[Eisenschmiede]]. Es werden außerdem Biergärten außerhalb von [[Silbermond]], [[Darnassus]], [[Unterstadt]], [[Sturmwind]], [[Donnerfels]], der [[Exodar]] und [[Shattrath]] aufgebaut. \r\nSowohl von [[Horde]] als auch [[Allianz]] gefeiert, ist das Braufest die richtige Zeit, die gegorenen Früchte der letzten Ernte zu feiern: Brezeln, Käse und Alkohol! Die Brauereien Donnerbräu, Gerstenbräu, sowie auch die [[Oger]], alle kommen sie außerhalb der Hauptstädte zusammen, um sich mit ihren besonderen Bieren und Honigweinen gegenseitig die Kundschaft wegzuschnappen. Tapfere Abenteuer sind eingeladen, sich in Ruhe zurückzulehnen, einen gemütlichen Schluck zu nehmen und die besten Waren zu genießen, die die Brauereien anzubieten haben!\r\n==Den Gerstensaft genießen == \r\nGratiskrüge mit frischem, schäumendem Bier warten auf Tischen außerhalb aller großer Städte. Wenn ihr einen davon in der Nähe einer der Brauereistände außerhalb von Orgrimmar und Eisenschmiede austrinkt, wird euch ein Brauereiassistent sofort einen neuen Krug reichen. Die leeren Krüge könnt ihr außerdem an den Fässern neben den Brauereiständen wieder auffüllen. Auf dem Braufest werdet ihr euch nie Gedanken machen müssen, wie ihr euren Durst loswerdet! \r\n==Was ihr tun könnt==\r\nBeim Braufest geht es um mehr als nur das Probetrinken der feinsten Biere aus ganz Azeroth und der Scherbenwelt. Hier erfahrt ihr, welche Großtaten ihr beim Durstlöschen nebenbei vollbringen könnt.\r\n===Widderrennen===\r\nAbenteurer können ihre Widderreitkünste beweisen, indem sie Neill Ramstein oder Widdermeister Ray ansprechen. Bevor diese euch einen ihrer wertvollen Widder anvertrauen, müsst ihr jedoch beweisen, dass ihr ihn auch kontrollieren könnt! Nachdem ihr sie überzeugt habt, könnt ihr euch einige Gewinnlose des Braufests verdienen, indem ihr Krüge aus Kharanos oder den Klingenhügeln zurückholt. \r\n===Marktschreier gesucht===\r\nRepräsentanten der großen Brauereien suchen Verstärkung in Form von Marktschreiern, die ihre Produkte in Orgrimmar und Eisenschmiede anpreisen - sprecht sie einfach an. Die Mitarbeiter von Gerstenbräu und Sonnerbräu findet ihr außerhalb von Eisenschmiede, die von T'chalis Voodoobräu und der Brauerei Drohn außerhalb von Orgrimmar. Ihr werdet einen Widder erhalten, der euch auf eurem Weg durch Orgrimmar oder Eisenschmiede unterstützt, wo ihr Kunde verbreitet, wer denn hier wirklich das beste Bier braut. \r\n===Schnitzeljagd===\r\nFür alle, die einer kleinen Schnitzeljagd nicht abgeneigt sind, haben Goldark Spatzenjäger und Glodrak Jägerspatz einige Aufgaben vorbereitet, in denen ihr es mit Wolpertingern und pinken Elekks zu tun bekommen werdet. Wir raten dringend zum Aufheben eines Konterbieres. \r\n===Verteidigt das Fest===\r\nVon Zeit zu Zeit versuchen die neidischen [[Dunkeleisenzwerge]], die Festlichkeiten mit einer Invasion zu stören. Festgelegte Trinker müssen sich hier messen, um das Bier zu beschützen und den Dunkeleisenzwergen eine Lektion zu verpassen, sofern sie nicht vom Alkohol ablassen. \r\nZu guter Letzt vergesst nicht, bei Belbi Blitzknips und Blix Fixtand vorbeizuschauen, um eure Braufest-Gewinnlose einzulösen! \r\n'''Quelle''':",},
			["Braumanns Mühle"] = { content = "'''Braumanns Mühle''' liegt nördlich der [[Kapelle des hoffnungsvollen Lichts]] in den [[Östlichen Pestländern]]. Die mächtigen Armeen des Lichkönigs werden sich hier für die letzte Schlacht um die Pestländer versammeln, sobald die Scharlachrote Enklave ausgelöscht wurde. Unter Führung von [[Hochlord Darion Mograine]] wollen sie dann den Dienern der [[Argentumdämmerung]] in der Kapelle des hoffnungsvollen Lichts gegenübertreten. Diese wagen es, sich noch immer der Geißel entgegenzustellen und allein aus diesem Grund sollen sie vernichtet werden. Man erreicht Braumanns Mühle, indem man von der [[Die Scharlachrote Enklave|Scharlachroten Enklave]] aus nach nach Nordwesten und dann durch die Höhle geht. So erreicht man das [[Giftiges Tal|Giftige Tal]]. Folgt man nun dem Pfad aus dem Tal heraus und wird man zur Mühle gelangen.",},
			["Brauner Präriehund"] = { content = "#REDIRECT [[Präriehund]]", redirect = "Präriehund",},
			["Brendolos"] = { content = "Ein bereits ergrauter Paladin, der oft mit einer Angel auf dem Rücken und einem seiner Haustiere an seiner Seite auf Reisen ist.\r\nVoll ausgebildeter Juwelenschleifer mit einem sehr großen Angebot an Vorlagen incl. aller epischen kaufbaren Vorlagen des Sonnenzorns.\r\nZuverlässige Bearbeitung und Lieferung auch bei Postversand. Standardlohn für Schleifarbeiten 5 Goldstücke, wird aber flexibel gehandhabt.",},
			["Brennende Klinge"] = { content = "#REDIRECT [[Orcs der Brennenden Klinge]]", redirect = "Orcs der Brennenden Klinge",},
			["Brennende Legion"] = { content = "Die Brennende Legion ist eine riesige [[Dämonen]]armee, die seit Jahrtausenden im ganzen Universum Schrecken und Vernichtung sät.\r\n===Die Mitglieder===\r\nOb aus freien Stücken oder durch magische Verzauberung - viele Wesen haben sich [[Sargeras]]' Willen unterworfen und ihm die Treue geschworen als Gegenleistung für das, was er zu bieten hatte: Unsterblichkeit und Macht jenseits aller Vorstellungskraft. Ganze Rassen haben sich der Legion dieser Verlockungen wegen angeschlossen. Doch nicht alle [[Dämon]]en sind intelligente Wesen. Manche sind einfach nur Tiere, die das Pech hatten, die Aufmerksamkeit von [[Sargeras]] zu erregen. Andere sind gar keine wahren [[Dämonen]], wie etwa die [[Höllenbestien]]. Ob nun willig oder nicht, wenn ein Wesen in einen [[Dämon]] verwandelt wird, ist sein Körper von der [[Teufelsenergie]] durchtränkt. Nicht alle [[Dämonen]] sind ein Teil der Legion, wie man am Beispiel [[Illidan Sturmgrimm]]s sehen kann, aber [[Sargeras]] hat über die Jahrtausende zahllose [[Dämon]]en erschaffen, um die Reihen seiner zerstörerischen Legion zu verstärken.\r\n===Geschichte und Organisation===\r\nEinst ein edler Verfechter der Ordnung und des Friedens, glaubte [[Sargeras]], dass das Universum einen grundlegenden Fehler hatte, der es unmöglich machte, seine Bestimmung zu erreichen. Er kam zu dem Schluß, die anderen [[Titanen]] wären zutiefst fehlgeleitet, da sie versuchten die Ordnung in der Schöpfung wiederherzustellen. Die aktuelle Lage war jedoch trotz aller Bemühungen aussichtslos. Das Universum musste vollständig zerstört und ohne grundlegende Fehler neu erschaffen werden. Nur dann konnte die wahre Ordnung erreicht werden. Somit begann [[Sargeras]] seine weitreichende Kampagne, das Ende aller Dinge herbeizuführen: die Burning Crusade.\r\nUm diesen Plan durchführen zu können, schuf er die Legion, deren Ränge er mit [[Dämonen]] füllte: Unsterbliche Wesen, deren Hunger, Macht und Bosheit sie zu perfekten Werkzeugen der Zerstörung machte. Das Ergebnis war eine gewaltige Legion, die bereits zahllose Welten zerstört hatte. Bis heute ist [[Azeroth]] der einzige Planet, der es geschafft hat, der Macht der Legion zu trotzen. Dies erzürnte [[Sargeras]] und er war entschlossener denn je, [[Azeroth]] auf die Knie zu zwingen. \r\nDie [[Eredar]] waren das erste empfindsame Volk, welches [[Sargeras]] gegenüber Loyalität schwor und bis heute sind sie die Kommandanten der Legion. Mit dem Wissen, dass auch andere empfindende Wesen sich unweigerlich der Legion anschließen würden, erklärten sie Eredun zur Sprache der Legion.\r\n[[Sargeras]] war der Schöpfer und der ursprüngliche Anführer der Brennenden Legion. Seit dem Tod des [[Menschen|menschlichen]] [[Magier|Zauberers]] [[Medivh]], der von [[Sargeras]]' Geist besessen war, wurden allerdings keine Berichte über das Auftauchen des [[Titanen]] bekannt. In Abwesenheit [[Sargeras]]' hatte der [[Dämon]] [[Kil'jaeden]] die Führung der Legion übernommen.\r\nEinige [[Dämon]]en in [[Azeroth]] haben die Niederlage der Legion in der Schlacht am Berg [[Hyjal]] überlebt. Sie sammeln sich in kleinen Gruppen in [[Azeroth]] und kommunizieren offensichtlich miteinander, denn sie handeln von Zeit zu Zeit aufeinander abgestimmt. Bestimmte [[Dämonen]] verbreiten Verderbtheit oder bewachen die Stätten der Macht. Andere versammeln sich aus bisher unbekannten Gründen an bestimmten Orten.\r\nDie bemerkenswerteste Handlung der Legion seit [[Der Dritte Krieg|dem Dritten Krieg]] fand in den [[Verwüstete Lande|Verwüsteten Landen]] statt. [[Dämonen]] unter der Führung von [[Lord Kazzak]] haben in [[Azeroth]] das [[Dunkle Portal]] an seiner ursprünglichen Stelle wiederauferbaut. Bisher haben die [[Dämonen]] nur die physische Struktur des [[Dunkle Portal|Portals]] erbaut, sie haben es bisher noch nicht aktivieren können.\r\n===Glaube und Ziele===\r\nDie [[Dämonen]] fürchteten [[Sargeras]]' weitreichende Macht und seinen Zorn. Dennoch dienten ihm die meisten [[Dämonen]] der Legion, da sie daran Gefallen gefunden hatten. Die [[Dämonen]] der höchsten Dienstgrade und die Intelligentesten unter ihnen waren über das Ziel ihres Schöpfers informiert. Selbst heute fürchten diese [[Dämonen]] die Verheerung, auf die sie hinarbeiten, nicht, denn ihnen wurde versprochen, dass sie im neu geschaffenen Universum regieren werden.\r\nIn der Vergangenheit hat die Legion vor allem die Welten angegriffen, die von den [[Titanen]] besucht wurden. Letztendlich war jedoch keine Welt sicher: die Legion arbeitet daran alles Leben und alle [[Magie]] zu verschlingen oder zu zerstören. Sie wird dieses schrecklichen Ziele unweigerlich erreichen, sollte sie nicht besiegt werden. Ein solcher Sieg würde eine Armee von vergleichbarer Größe und Macht benötigen. Eine Armee, die für das Licht kämpft, für Hoffnung und Frieden, für die Grundideen der Schöpfung...\r\nEine Armee, die es nicht gibt.\r\n'''Quelle:''' \r\nSiehe auch:\r\n* [[Titanen und die Entstehung der Ordnung]]\r\n* [[Sargeras und der Verrat]]\r\n* [[Ordnung auf Azeroth]]",},
			["Brennende Legion"] = { content = "Die Brennende Legion ist eine riesige [[Dämonen]]armee, die seit Jahrtausenden im ganzen Universum Schrecken und Vernichtung sät.\r\n===Die Mitglieder===\r\nOb aus freien Stücken oder durch magische Verzauberung - viele Wesen haben sich [[Sargeras]]' Willen unterworfen und ihm die Treue geschworen als Gegenleistung für das, was er zu bieten hatte: Unsterblichkeit und Macht jenseits aller Vorstellungskraft. Ganze Rassen haben sich der Legion dieser Verlockungen wegen angeschlossen. Doch nicht alle [[Dämon]]en sind intelligente Wesen. Manche sind einfach nur Tiere, die das Pech hatten, die Aufmerksamkeit von [[Sargeras]] zu erregen. Andere sind gar keine wahren [[Dämonen]], wie etwa die [[Höllenbestien]]. Ob nun willig oder nicht, wenn ein Wesen in einen [[Dämon]] verwandelt wird, ist sein Körper von der [[Teufelsenergie]] durchtränkt. Nicht alle [[Dämonen]] sind ein Teil der Legion, wie man am Beispiel [[Illidan Sturmgrimm]]s sehen kann, aber [[Sargeras]] hat über die Jahrtausende zahllose [[Dämon]]en erschaffen, um die Reihen seiner zerstörerischen Legion zu verstärken.\r\n===Geschichte und Organisation===\r\nEinst ein edler Verfechter der Ordnung und des Friedens, glaubte [[Sargeras]], dass das Universum einen grundlegenden Fehler hatte, der es unmöglich machte, seine Bestimmung zu erreichen. Er kam zu dem Schluß, die anderen [[Titanen]] wären zutiefst fehlgeleitet, da sie versuchten die Ordnung in der Schöpfung wiederherzustellen. Die aktuelle Lage war jedoch trotz aller Bemühungen aussichtslos. Das Universum musste vollständig zerstört und ohne grundlegende Fehler neu erschaffen werden. Nur dann konnte die wahre Ordnung erreicht werden. Somit begann [[Sargeras]] seine weitreichende Kampagne, das Ende aller Dinge herbeizuführen: die Burning Crusade.\r\nUm diesen Plan durchführen zu können, schuf er die Legion, deren Ränge er mit [[Dämonen]] füllte: Unsterbliche Wesen, deren Hunger, Macht und Bosheit sie zu perfekten Werkzeugen der Zerstörung machte. Das Ergebnis war eine gewaltige Legion, die bereits zahllose Welten zerstört hatte. Bis heute ist [[Azeroth]] der einzige Planet, der es geschafft hat, der Macht der Legion zu trotzen. Dies erzürnte [[Sargeras]] und er war entschlossener denn je, [[Azeroth]] auf die Knie zu zwingen. \r\nDie [[Eredar]] waren das erste empfindsame Volk, welches [[Sargeras]] gegenüber Loyalität schwor und bis heute sind sie die Kommandanten der Legion. Mit dem Wissen, dass auch andere empfindende Wesen sich unweigerlich der Legion anschließen würden, erklärten sie Eredun zur Sprache der Legion.\r\n[[Sargeras]] war der Schöpfer und der ursprüngliche Anführer der Brennenden Legion. Seit dem Tod des [[Menschen|menschlichen]] [[Magier|Zauberers]] [[Medivh]], der von [[Sargeras]]' Geist besessen war, wurden allerdings keine Berichte über das Auftauchen des [[Titanen]] bekannt. In Abwesenheit [[Sargeras]]' hatte der [[Dämon]] [[Kil'jaeden]] die Führung der Legion übernommen.\r\nEinige [[Dämon]]en in [[Azeroth]] haben die Niederlage der Legion in der Schlacht am Berg [[Hyjal]] überlebt. Sie sammeln sich in kleinen Gruppen in [[Azeroth]] und kommunizieren offensichtlich miteinander, denn sie handeln von Zeit zu Zeit aufeinander abgestimmt. Bestimmte [[Dämonen]] verbreiten Verderbtheit oder bewachen die Stätten der Macht. Andere versammeln sich aus bisher unbekannten Gründen an bestimmten Orten.\r\nDie bemerkenswerteste Handlung der Legion seit [[Der Dritte Krieg|dem Dritten Krieg]] fand in den [[Verwüstete Lande|Verwüsteten Landen]] statt. [[Dämonen]] unter der Führung von [[Lord Kazzak]] haben in [[Azeroth]] das [[Dunkle Portal]] an seiner ursprünglichen Stelle wiederauferbaut. Bisher haben die [[Dämonen]] nur die physische Struktur des [[Dunkle Portal|Portals]] erbaut, sie haben es bisher noch nicht aktivieren können.\r\n===Glaube und Ziele===\r\nDie [[Dämonen]] fürchteten [[Sargeras]]' weitreichende Macht und seinen Zorn. Dennoch dienten ihm die meisten [[Dämonen]] der Legion, da sie daran Gefallen gefunden hatten. Die [[Dämonen]] der höchsten Dienstgrade und die Intelligentesten unter ihnen waren über das Ziel ihres Schöpfers informiert. Selbst heute fürchten diese [[Dämonen]] die Verheerung, auf die sie hinarbeiten, nicht, denn ihnen wurde versprochen, dass sie im neu geschaffenen Universum regieren werden.\r\nIn der Vergangenheit hat die Legion vor allem die Welten angegriffen, die von den [[Titanen]] besucht wurden. Letztendlich war jedoch keine Welt sicher: die Legion arbeitet daran alles Leben und alle [[Magie]] zu verschlingen oder zu zerstören. Sie wird dieses schrecklichen Ziele unweigerlich erreichen, sollte sie nicht besiegt werden. Ein solcher Sieg würde eine Armee von vergleichbarer Größe und Macht benötigen. Eine Armee, die für das Licht kämpft, für Hoffnung und Frieden, für die Grundideen der Schöpfung...\r\nEine Armee, die es nicht gibt.\r\n'''Quelle:''' \r\nSiehe auch:\r\n* [[Titanen und die Entstehung der Ordnung]]\r\n* [[Sargeras und der Verrat]]\r\n* [[Ordnung auf Azeroth]]",},
			["Brennende Steppe"] = { content = "Die Brennende Steppe befindet sich im Herzen [[Azeroth]]s. Das Land ist mit vielen Vulkanen und Kratern bestückt. Hier leben [[Oger]], [[Orcs]] und vor allem: [[Drachen]]. Im Norden befindet sich der [[Schwarzfels]], ein großer schwarzer Berg, welcher ebenfalls von [[Oger]]n, [[Drachen]] und [[Orcs]] besiedelt ist. Ein Expeditionskorps von [[Kargath]] stieß bereits bei den ersten Streifzügen in der [[Sengende Schlucht|Sengenden Schlucht]] auf Maschinen, von denen weitere Nachforschungen ergaben, dass sie aus der Brennenden Steppe, eventuell auch aus den [[Schwarzfelstiefen]], stammen. \r\nInsgesamt ist das Leben in der Brennenden Steppe voller Konflikte, denn der [[Schwarzer Drachenschwarm|Schwarze Drachenschwarm]] ist es, der die [[Orcs]] des [[Schwarzfels]] beherrscht. Man vermutet, dass es auch der [[Schwarzer Drachenschwarm|Schwarze Drachenschwarm]] ist, der ihre Wut und Feindseligkeit schürt.\r\n==Orte==\r\n* [[Cyrus' Höhle]]\r\n* [[Flammenkamm]]\r\n* [[Morgans Wacht]]\r\n* [[Ruinen von Thaurissan]]\r\n* [[Schreckensfels]]\r\n===Altar der Stürme===\r\nDie [[Hexenmeister]] Mor'zul Bloodbringer und Gorzeeki Wildeyes haben ihr Lager nahe des [[Altar der Stürme|Altars der Stürme]] in der Brennenden Steppe aufgeschlagen.",},
			["Brigant"] = { content = "#REDIRECT [[Menschenschurke]]", redirect = "Menschenschurke",},
			["Brill"] = { content = "\r\nVor den Toren [[Lordaeron]]s liegt inmitten der Region [[Tirisfal]] dieser kleine idyllische Ort mit Namen Brill. Wie viele andere Ortschaften entlang der Königsstraße wurde auch Brill von der Seuche des Untodes infiziert. Die Zauberer der [[Kirin Tor]] hegten den Verdacht, die Seuche würde aus den nördlichen Dörfern stammen. Aber [[Priester]] der Elfen entdeckten eine infizierte Kornkammer und Kisten mit verseuchtem Getreide aus [[Andorhal]].\r\nBrill ist ein netter kleiner Ort, wo lauter Opfer der Seuche wohnen, die versuchen, sich irgendwie durchs Leben zu schlagen. Und es wäre ein toller Ort, an dem man sich ausruhen kann, falls das mal nötig wird. Dort kann man auch lernen, Skelettrosse zu reiten und sie kaufen. \r\n===Friedhof von Brill===\r\nAls die [[Geißel]] durch [[Tirisfal]] zog, konnten die [[Verlassene]]n einen ihrer Angehörigen einfangen, um ihn zu studieren. Er hatte einen freien Geist und nannte sich [[Ulag der Spalter]]. Doch obwohl er einen freien Willen besaß, stand er noch immer unter dem Bann des [[Lichkönig]]s. Die Verlassenen hofften, sie könnten den Einfluss des Königs auf Ulag brechen, doch es gelang ihnen nicht. Nun ist er auf dem Friedhof in bei [[Brill]] in einer Gruft eingesperrt.\r\n===Gasthaus \"Zur Galgenschlinge\" === \r\nDie Todeswächter benutzen gern den Keller der Taverne \"Zur Galgenschlinge\" als Übergangszelle, bis man sich \"richtig\" um die Gefangenen kümmern kann. Im Keller wird zur Zeit ein Scharlachroter Zelot gefangen gehalten, der den Experimenten der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] wehrlos ausgeliefert ist. Berichten der Todeswachen zufolge wurde jetzt auch noch ein Zwergengebirgsjäger festgenommen. \r\n==Personen==\r\n* '''Apotheker Johaan''' ist von der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] und sammelt Zutaten für eine neue Seuche. \r\n* '''Coleman Heller''' hat früher vor der Seuche in der [[Agamands Mühlen|Mühle der Familie Agamand]] gearbeitet und möchte nun seinen Rachedurst stillen.\r\n* '''Exekutor Zygand''' und leitet den Krieg gegen den [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzug]]. \r\n* '''Gretchen Dedmar''' spürt die Kälte des Todes. Ihr ist jetzt so kalt. Die Seuche des Untodes kriecht durch ihre Adern wie eine eisige Schlange. Sie wird bald den Hirnlosen Zustand erreichen. Doch auch ein besiegeltes Schicksal wird sie nicht davon abhalten, ihrer [[Sylvanas Windläufer|Dunklen Fürstin]] zu dienen. Als der Ruf ertönte, nähte sie Leichensäcke für die gefallenen Soldaten von [[Sylvanas Windläufer|Sylvanas]]' mächtiger Armee. Jetzt zittern ihre Hände vor lauter Kälte. Wenn man ihr Nachtsaugerpelze und etwas groben Faden bringen würde, könnte sie sich eine Decke nähen.\r\n* '''Jungapotheker Holland''' ist der Meister von Gordo und lässt seine Monstrosität Kraut suchen. Aber Gordo da draußen sammelt die falschen Kräuter. Er befindet sich in einer Zwickmühle. \r\n* '''Magistrat Sevren''' hat alle Dokumente über die jüngsten Todesfälle. Er braucht einen aktuellen Bericht von ihrem Außenposten der Todeswache im Osten, denn er muss wissen, ob mehr Streitkräfte der [[Geißel]] am Bollwerk vorbei und nach Tirisfal herein geschlichen sind. \r\n* '''Todeswache Burgess''' möchte Beweise des Ablebens von Scharlachroten Kreuzzüglern.",},
			["Broggok"] = { content = "'''Broggok''' ist ein [[Betrachter]] im [[Blutkessel]] der [[Höllenfeuerzitadelle]].\r\n==Fähigkeiten==\r\n* '''Giftblitz''' - Giftblitz schießt Gift auf den Feind, fügt ihm Naturschaden und dann 9 Sekunden lang alle 3 Sekunden 320 bis 380 zusätzlichen Schaden zu.\r\n* '''Schleimnebel''' - Verursacht bis 700 bis 900 Naturschaden und hinterlässt eine Giftwolke, die ebenfalls Natürschaden verursacht.",},
			["Bronzebart"] = { content = "#Redirect[[Bronzebart Klan]]", redirect = "Bronzebart Klan",},
			["Bronzebarts Lager"] = { content = "'''Bronzebarts Lager''' befindet sich südlich von [[Burg Cenarius]] in [[Silithus]]. Die [[Zwerge]] in dort sollten einige Tipps geben können, wie man mit den [[Silithiden]] fertig wird, die die Schwarmbauten in diesem Land bewohnen. Den Vorsitz dort hatte bis zu seinem Verschwinden [[Brann Bronzebart]]. Doch die meisten seiner Männer sind schon tot und er hatte Informationen über einen [[Titanen]] entdeckt und über eine große Schlacht zwischen ihm und einem alten Gott. Die [[Zwerge]] der [[Forscherliga]] haben einen uralten Tunnel nach [[Ahn'Qiraj]] entdeckt, dem [[Brann Bronzebart]] jetzt folgt. In dem Lager halten nun [[Rutgar Glyphenschnitzer]] und [[Frankal Steinsteg ]] die Stellung.\r\n==Personen==\r\n* [[Brann Bronzebart]]\r\n* '''Frankal Steinsteg''' - Frankal Steinsteg möchte gern den Kode der [[Silithiden]] knacken. Er kann hierzu ein Elixier entwickeln, welches die Entschlüsselung der Glyphen und der Sprachen der [[Silithiden]] und [[Qiraji]] sehr erleichtern wird. Dafür benötigt er die Gehirne eines [[Silithiden]] aus jedem einzelnen [[Silithiden]]schwarm, welche die Schwarmbauten bewohnen und deswegen soll man ihm jeweils ein [[Silithiden]]gehirn des [[Zoraschwarm]]s, [[Ashischwarm]]s und des [[Regalschwarm]]s bringen.\r\n* '''Rutgar Glyphenschnitzer''' - Rutgar Glyphenschnitzer möchte, dass man in den [[Bau des Ashischwarms]], [[Bau des Zoraschwarms]] und [[Bau des Regalschwarms]] eindringt und dort Abpausbilder von den glyphenverzierten Kristallen anfertigt, indem man das [[Abschriftenset für Geologen]] benutzt. Dank der Abpausbilder ist es gelungen, die Glyphen auf diesem Kristallprisma nachzubilden und es sieht so aus, als würden sie den [[Qiraji]] und anderen unbekannten Wesen dazu dienen, mit den [[Silithiden]] zu kommunizieren. Leider ist das alles, was er aus diesen Glyphen herauskriegen konnte und er muss eine Möglichkeit finden, wie man die in den Kristallen versteckten Botschaften freilegen kann. Aber [[Geologin Lerchenbann]] auf [[Burg Cenarius]] müsste weiterhelfen können. Der Grund, warum die [[Zwerge]] die Glyphen nicht entschlüsseln konnten ist ganz einfach, es gibt nichts zum Entschlüsseln. Die äußere Schicht des Prismas muss exakt nach den Markierungen innerhalb des Kristalls ausgerichtet werden, damit eine Nachricht übertragen werden kann.",},
			["Bronzedrachen"] = { content = "#REDIRECT [[Bronzener Drachenschwarm]]", redirect = "Bronzener Drachenschwarm",},
			["Bronzener Drachenschwarm"] = { content = "Bronze Drachen sind kleiner und behender als [[Drachen]] anderer Schwärme und sie scheinen eher für Schnelligkeit als Ausdauer gebaut zu sein. Ihre Körper sind dünn und geschickt, mit Schuppen die beinahe metallisch erscheinen. Bronze Drachen sind, ähnlich wie [[Blauer Drachenschwarm|Blaue]], sehr schlau und schätzen Weisheit und Geduld über alle sonst. Sie existieren, um den Zeitfluss unversehrt zu halten, damit die Abfolge der Ereignisse so fortschreiten kann, wie es vom Schicksal beabsichtigt ist. Um das zu erleichtern, werden die Bronzenen oft nahe humanoider Zivilisation gesehen. Sie halten Wache über bevölkerte Regionen und beabachten die Entwicklung andere Rassen. Auch überwachen sie, wie die Ereignisse den Lauf des Schicksals beeinflussen. Kürzlich ist der Bronzene Drachenschwarm seit zehntausend Jahren zum ersten Mal wieder in die Wüste von [[Silithus]] zurückgekehrt. \r\nDie Abkömmlinge des Bronzenen Drachenschwarms sind die [[Hüter der Zeit]] und scheren sich wenig um die Angelegenheiten der sterblichen Rassen. Als die [[Titanen]] das erste Mal Fuß auf [[Azeroth]] setzten, die [[Alte Götter|Alten Götter]] bezwangen und der Welt Ordnung brachten, verlieh der Hochvater des Pantheons dem Drachen [[Nozdormu]] einen Teil seiner eigenen kosmischen Macht. Fortan bewachte der Drache die Zeit und kontrollierte die ewig wirbelnden Pfade des Schicksals und der Vorsehung. Und so wurde der stoische und ehrenwerte Nozdormu als der Zeitlose bekannt. Seit jener Zeit beschützt [[Nozdormu]]s Brut, stets geleitet vom Rat des Zeitlosen, den Strom der Zeit vor jenen, die diesen zu unterbrechen versuchen.\r\nIm Leben der meisten Sterblichen ist Zeit nicht viel mehr als ein einfaches Stundenglass: Lautlos und beständig rieselt der Sand hindurch. Nur die wenigsten wissen um die Wahrheit - dass die Zeit wütet wie ein entfesselter Sturm, ungezähmt und chaotisch.\r\n===Namensgebung===\r\nBronzene Drachen benennen sich manchmal am Ende mit „ormu“ oder beinhalten „dorm,“ aber haben häufiger Namen, die sich auf Elemente der Zeit beziehen.\r\n==Aktuelles==\r\nWie ihr Lord [[Nozdormu]] haben sich die bronzenen Drachen weitgehend aus dieser Welt auf ihre eigene Astralebene zurückgezogen. Die namenlose Dimension ist eine unendliche, zeitlose Wüste mit den gesammelten Artefakten längst vergangener Zeitalter. Nur selten kann man sie noch im öden Brachland von [[Kalimdor]] beobachten.\r\nDoch jetzt ist der bronzene Drache [[Anachronos]] zu den [[Höhlen der Zeit]] in die Wüste [[Tanaris]] zurückgekehrt, der angestammten Heimat des bronzenen Drachenschwarms. Ereignisse sind in Bewegung geraten, die die Zukunft [[Azeroth]]s verändern werden, während die Aufmerksamkeit von [[Nozdormu]]s Brut auf [[Ahn'Qiraj]], die Festung der [[Qiraji]], gerichtet ist. Jene, die tapfer genug sind, dem Ruf der [[Drachen]] zu folgen, werden an diesem Ort vor neue Herausforderungen gestellt, denn eine schreckliche Dunkelheit braut sich hinter dem [[Skarabäuswall]] zusammen, bedrohlich genug, selbst den Zeitlosen innehalten zu lassen. Die [[Drachen]] haben damit begonnen, die Helden des Landes zusammenzurufen, um in die alptraumhaften Bauten in den Tiefen [[Ahn'Qiraj]]s hinabzusteigen und zu beenden, was sie einst begonnen haben. Die schicksalhafte Stunde rückt unaufhaltsam näher.\r\n==Untergruppen==\r\n* [[Brut Nozdormus]]\r\n* [[Hüter der Zeit]]\r\n* [[Wächter der Sande]]\r\n==Namhafte Bronzedrachen==\r\n* '''[[Nozdormu]]'''\r\n* [[Anachronos]]\r\n* [[Andormu]]\r\n* [[Arazmodu]]\r\n* [[Chromie]]\r\n* [[Chronalis]]\r\n* [[Grakkarond]]\r\n* [[Sa'at]]\r\n* [[Soridormi]]\r\n* [[Tydormu]]\r\n* [[Zaladormu]]",},
			["Broxigar"] = { content = "Broxigar (oft auch nur Brox genannt), die Rote Axt, ist ein legendärer Orkheld aus dem Krieg gegen die [[Brennende Legion]] und verschwand eines Tages, als er von [[Thrall]] losgeschickt wurde, ein magisches Phänomen zu untersuchen. Nur wenige wissen, dass er dabei in die Vergangenheit reiste und die Legion erneut zur Zeit des [[Nachtelfen]]imperiums bekämpfte.\r\n'''Biographie'''\r\nBrox wurde, wie alle anderen Orcs, von den [[Menschen]] gefangen und in die Internierungslager gesteckt. Thrall befreite ihn und führte die Orcs nach [[Kalimdor]]. Dort, in der Schlacht von [[Hyjal]] überlebte Brox als einziger einer Kriegertruppe, die einen wichtigen Pass verteidigte. Sein Leben lang fühlte er sich schuldig, weil er überlebt, seine Freunde aber alle gestorben waren. Als Thrall ihn losschickte, sah er das als Zeichen der Geister, sich von seinem Leben erlösen zu können. Doch er wurde von der Anomalie zurück geschleudert und befand sich daraufhin in der Zeit vor dem [[Krieg der Urtume]]. Die [[Nachtelfen]] fingen ihn ein und steckten ihn in einen Käfig und stellten ihn öffentlich aus. Dort traf er die junge Priesterin [[Tyrande Wisperwind]], welche ihm etwas zu Essen brachte und seine durch den Magier [[Illidan Sturmgrimm]] zugefügten Wunden heilte. Tyrande versprach, ihn zu befreien.\r\nIn der nächsten Nacht kam ihr Freund [[Malfurion Sturmgrimm]] mit [[Nachtsäbler]]n, auf denen sie aus der Stadt in die Wälder flohen. Dort traf Brox auf die ersten, wiederkehrenden Dämonen und tötete einen von ihnen. Mallfurion brachte ihn zur heiligen Lichtung des [[Cenarius]], wo sie den ebenfalls in die Zeit zurückversetzten Magier [[Rhonin]] trafen. Bald jedoch wurde die Lichtung von Dämonen attackiert. Der Halbgott und Malfurion erschufen Brox eine hölzerne Axt, die jedoch jeder Metallwaffe weit überlegen war. So konnten sie die Dämonen besiegen. Doch schon bald begann der [[Krieg der Urtume]], Dämonenheere unter dem mächtigen [[Eredar]]-Kommandanten [[Archimonde]] rückten aus, um die Welt zu vernichten. Brox kämpfte stets in vorderster Front, kein Dämon wiederstand seiner Axt und er erlebte auch den Verrat [[Todesschwinge]]s mit. Danach schloss er sich der von dem Drachenmagier [[Krasus]] geführten Expedition an, um die [[Dämonenseele]] von Todesschwinge zu rauben. Die Expedition scheiterte, denn Illidan hatte sich auf die Seite der Dämonen geschlagen und nahm ihnen die Seele ab. In dem darauffolgenden letzten Kampf flog Brox auf einem Bronzedrachen , um den letzten Portalzauber zu verhindern, welcher [[Sargeras]] selbst in diese Welt bringen sollte. Er kämpfte so gut es ging und sprang letztendlich sebst in das Poratl, um Sargeras aufzuhalten. Die [[Axt des Brox]] verwundete Sargeras zwar leicht, doch gegen die Macht des gefallenen [[Titanen]] konnte der Orc nichts ausrichten. Er starb, als Sargeras Klinge Gorribal ihn durchbohrte. Nur seine Axt überstand es und wurde von [[Krasus]] an Thrall weitergereicht, mitsamt der Geschichte dessen, was geschehen war.",},
			["Bruchhauer"] = { content = "#REDIRECT [[Trolle der Bruchhauer]]", redirect = "Trolle der Bruchhauer",},
			["Bruchstücke aus Uldaman"] = { content = "Diese geätzten Reliefs stellen vermutlich den bedeutsamsten Fund in den ersten Kammern von [[Uldaman]] dar. Die Stiche deuten unverkennbar auf eine Verbindung zwischen den golemähnlichen [[Irdene]]n und dem [[Zwerge]]nvolk hin. Sollten weitere Beweise ans Licht kommen, könnte sich die Theorie, wonach die [[Zwerge]] von den mythischen [[Titanen]] erschaffen wurden, als wahr erweisen. Die Bruchstücke werden in der Halle der Forscher in [[Eisenschmiede]] aufbewahrt und sind dort für alle Interessierten zu besichtigen.",},
			["Bruchwald"] = { content = "Der '''Bruchwald''' liegt im Nordwesten des [[Der heulende Fjord|Heulenden Fjords]] und wrid hauptsächlich von [[Spinne]]n und [[Worg]]s bewohnt. Ihr ehemaliger Anführer, der Worg [[Ulfang]] befindet sich in einer Höhle am schneebedeckten nordwestlichen Ende des Bruchwalds. Bis zum letzten Vollmond war er der Alphaworg des Rudels, doch dann kam der weiße Worg [[Garwal]] aus dem Norden und mit Hilfe der einstigen Brüder von Ulfang, Bjomolf und Varg, stieg er sehr schnell zum Alphaworg auf. Er hat irgendetwas unnatürliches an sich. Der Worg [[Bjomolf]] jagt nordwestlich eines Ortes, den man das Stählerne Tor nennt und [[Varg]] befindet sich im Südosten, in der Nähe des Westspeerturms. Garwal selbst verbirgt sich hinter einem Schleier unnatürlicher Magie. Niemand kann ihn sehen oder riechen, außer er wünscht es. Nun hat [[Ulfang]] seinen Widersacher zu töten und selbst wieder zum Alphaworg des Rudels aufzusteigen.",},
			["Bruderschaft des Lichts"] = { content = "Die [[Bruderschaft des Lichts]] ist eine Splittergruppe der [[Argentumdämmerung]]. Es ist eine relativ kleine, jedoch extreme Gruppierung, welche einen geheimen Hauptsitz haben. Die wahren Motive und Anführer der Bruderschaft sind nicht bekannt, doch sind Verteter der Bruderschaft an der [[Kapelle des Hoffnungsvollen Lichts]], dem Hauptsitz der Argentumdämmerung, zu finden. Dort beraten sie gemeinsam mit den Argentumern und Vertetern des [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzuges]] über [[Naxxramas]] und den [[Aschenbringer]]. Es ist bekannt, dass einige Mitglieder der Bruderschaft bereits in der Festung waren, jedoch bei ihrer Mission fehlgeschlagen sind. \r\nIm Grunde sind sie alle Mitglieder der Argentumdämmerung - jedoch lassen sie sich weder von der sogenannten Moral, Schuldgefühlen oder nutzlosen menschlichen Emotionen einschränken. Sie wollen, dass man sie einfach als den Scharlachroten Kreuzzug betrachtet ohne der dort vorherrschenden Blauäugigkeit, deren Mengel an Führungsqualitäten und der dort üblichen, blinden Gefolgschaft. \r\n==Geschichte==\r\nAls die Argentumdämmerung gegründet wurde, waren sich die Argentumer noch über die Stellung der [[Horde]] gegenüber uneinig. Viele sahen nach wie vor in den [[Verlassene]]n nichts anderes als Diener der [[Geißel]] und in der Horde keinen potentiellen Verbündeten. Als dann [[Lord Maxwell Tyrosus]] beschloss, die Horde als Verbündeten zu betrachten und sogar so weit ging, einen Verlassenen zu rekrutieren, [[Leonidas Bartholomäus der Geachtete]], spaltetetn sich einige Argentumer ab und gründeten die Bruderschaft des Lichts. \r\n==Persönlichkeiten==\r\n* [[Erzmagierin Angela Dosantos]]\r\n* [[Vater Inigo Montoy]]\r\n* '''Kommandant Eligor Morgenbringer''' - Kommandant Eligor Morgenbringer ist der offizielle Vetreter der Bruderschaft des Lichts bei der Argentumdämmerung. \r\n* '''Korfax''' - Korfax ist der Champion der Bruderschaft des Lichtes. \r\n* '''Meisterhandwerker Omarion''' - Meisterhandwerker Omarion ist der einzige Überlebende des Angriffs auf [[Naxxramas]]. \r\n* '''Wache Didier''' - Wache Didier ist ein Offizier der Bruderschaft des Lichtes.",},
			["Bruderschaft des Pferdes"] = { content = "Bruderschaft des Pferdes/ Ritter von Sturmwind \r\nGeschichte: \r\nDie Bruderschaft des Pferdes war die Elite-Kavallerie [[Sturmwind]]s. Ihre Basis war der alte Turm von [[Karazhan]], bevor sie ihn verließen, um nach Sturmwind zu ziehen. Sie waren große Kämpfer und meist auch Adelige und Politiker. So wurde der zwanzigste Kavallerist Anduin Lothar sogar Champion von [[Sturmwind]]. Nachdem die alte [[Horde]] durch das dunkle Portal nach [[Azeroth]] kam, trafen sie zuallererst auf die Soldaten und Ritter Sturmwind. Im Laufe des Krieges fiel das Reich und die Ritter von Sturmwind starben für ihre Heimat. \r\nGeschichte: \r\nDie Ritter kämpften tapfer,doch waren zahlenmäßig vollkommen unterlegen. Kein einziger von ihnen überlebte den Krieg. \r\nWichtige Personen: \r\n[[Anduin Lothar]]: Ehemaliger zwanzigster Kavallerist und Champion von Sturmwind.",},
			["Bruderschaft von Nordhain"] = { content = "#REDIRECT [[Kleriker von Nordhain]]", redirect = "Kleriker von Nordhain",},
			["Brunnen der Ewigkeit"] = { content = "Zehntausend Jahre bevor die [[Menschen]] und die [[Orcs]] ihren Ersten Krieg führten, gab es auf der Welt Azeroth nur einen einzigen, von einem unendlichen, tosenden Meer umgebenen Kontinent. Diese [[Kalimdor]] genannte Landmasse war die Heimat einer ganzen Anzahl unterschiedlicher Völker und Kreaturen, die alle versuchten, sich gegen die wilden Elemente der erwachenden Welt zu behaupten. Im Herzen des dunklen Kontinents lag ein geheimnisvoller See glühender Energien. Der See, der später die Bezeichnung Brunnen der Ewigkeit tragen sollte, war das wahre Herz der magischen und natürlichen Macht dieser Welt. Der Brunnen bezog seine Energien aus dem unendlichen Großen Dunkel jenseits der Welt und diente als mystischer Quell – er sandte seine starken Energien über die ganze Welt aus und nährte so das Leben in all seinen wundersamen Gestalten.\r\nIm Laufe der Zeit bahnte sich ein primitiver Stamm nachtaktiver Humanoider vorsichtig einen Weg zum Ufer dieses hypnotischen verzauberten Sees. Die wilden nomadischen Humanoiden wurden von den seltsamen Energien des Brunnens angezogen und errichteten primitive Behausungen an seinen friedlichen Ufern. Mit der Zeit beeinflussten die kosmischen Energien des Brunnens den seltsamen Stamm und machten ihn stark, weise und so gut wie unsterblich. Der Stamm gab sich selbst den Namen [[Nachtelfen|Kaldorei]], was in seiner Sprache so viel wie „Kinder der Sterne“ bedeutete. Um ihre aufstrebende Gesellschaft zu feiern, errichteten sie gewaltige Bauwerke und Tempel um den See herum.\r\nDie [[Nachtelfen|Kaldorei]] oder [[Nachtelfen]], wie sie später genannt werden sollten, beteten die Mondgöttin Elune an und glaubten, dass sie tagsüber in den schimmernden Tiefen des Brunnens schliefe. Die frühen [[Priester]] und Seher der [[Nachtelfen]] studierten den Brunnen mit unstillbarer Neugier, von dem Wunsch getrieben, seine unbekannten Geheimnisse und Kräfte zu enträtseln. Als ihre Gemeinschaft wuchs, erforschten die [[Nachtelfen]] ganz [[Kalimdor]] und begegneten seinen zahllosen Lebensformen. Die einzigen Kreaturen, die sie beeindruckten, waren die uralten und mächtigen [[Drachen]]. Die riesigen, schlangengleichen Bestien lebten zwar häufig sehr zurückgezogen, trugen aber viel dazu bei, das bekannte Land vor potenziellen Gefahren zu beschützen. Die [[Nachtelfen]] glaubten, dass die [[Drachen]] sich selbst als Beschützer der Welt betrachteten, und sie waren sich einig, dass man sie und ihre Geheimnisse am Besten in Ruhe ließ. Mit der Zeit führte die Neugier der [[Nachtelfen]] dazu, dass sie sich mit einer Reihe mächtiger Wesenheiten anfreundeten, nicht zuletzt mit [[Cenarius]], einem Halbgott aus den unberührten Urwaldgebieten.\r\nDer großherzige [[Cenarius]] fand Gefallen am Forscherdrang der [[Nachtelfen]] und lehrte sie vieles über die natürliche Welt. Die abgeklärten [[Nachtelfen|Kaldorei]] entwickelten eine starke Verbundenheit mit den lebenden Wäldern von [[Kalimdor]] und lebten in einem harmonischen Gleichgewicht mit der Natur.\r\nDoch im Laufe scheinbar endloser Zeitalter expandierte die Zivilisation der [[Nachtelfen]] territorial und kulturell. Ihre Tempel, Straßen und Wohnorte erstreckten sich über den gesamten dunklen Kontinent. [[Azshara]], die begabte und wunderschöne Königin der [[Nachtelfen]], erbaute einen riesigen, Ehrfurcht gebietenden Palast am Ufer des Sees, in dessen juwelengeschmückten Sälen ihre bevorzugten Untertanen lebten. Diese Untertanen, die sie [[[[Hochgeborene|Quel’dorei]] oder „[[Hochgeborene]]“ nannte, lasen ihr jeden Wunsch von den Augen ab und hielten sich für etwas Besseres als ihre weniger privilegierten Brüder. Königin [[Azshara]] wurde zwar von ihrem Volk geliebt, doch die [[Hochgeborene]]n waren bei den eifersüchtigen Massen insgeheim verhasst.\r\n[[Azshara]] teilte die Neugier der [[Priester]], was den Brunnen betraf, und befahl den gebildeten [[Hochgeborene]]n, seine Geheimnisse zu enträtseln und herauszufinden, welchen Zweck er auf der Welt hatte. Die [[Hochgeborene]]n machten sich an die Arbeit und studierten den Brunnen ohne Unterlass. Mit der Zeit fanden sie eine Möglichkeit, die kosmischen Energien des Brunnens zu manipulieren und zu kontrollieren.\r\nIn zunehmend riskanteren Experimenten entdeckten die [[Hochgeborene]]n, dass sie ihre neu erlangte Macht nutzen konnten, um ganz nach Gutdünken zu erschaffen oder zu zerstören. Die unglückseligen [[Hochgeborene]]n waren auf eine primitive Magie gestoßen und fest entschlossen, es darin zur Meisterschaft zu bringen. Obschon sich alle darin einig waren, wie gefährlich [[Magie]] sein konnte, wenn man verantwortungslosen Umgang damit pflegte, praktizierten [[Azshara]] und ihre [[Hochgeborene]]n ihre Zauberei immer tollkühner. [[Cenarius]] und viele der weisen Gelehrten der [[Nachtelfen]] mahnten unablässig, dass es nur zur Katastrophe führen konnte, mit den deutlich gefährlichen Künsten der [[Magie]] herumzuspielen. Doch [[Azshara]] und ihre Anhänger erforschten ihre aufblühenden Fähigkeiten unbekümmert weiter. Je größer ihre Macht wurde, desto deutlicher wurden Veränderungen an [[Azshara]] und den [[Hochgeborene]]n. Die hochmütige und selbstverliebte Oberschicht wurde zunehmend geringschätziger und grausamer zu den anderen [[Nachtelfen]]. Ein finsterer, düsterer Schleier umwölkte [[Azshara]]s einst atemberaubende Schönheit. Sie zog sich von ihren Untertanen zurück und pflegte nur noch Umgang mit den [[Priester]]n der [[Hochgeborene]]n, die ihr Vertrauen besaßen.\r\nEin junger, mutiger Gelehrter namens [[Malfurion|Malfurion Sturmgrimm]], der die Wirkung des Brunnens ausgiebig studiert hatte, kam zu der Überzeugung, dass eine schreckliche Macht die [[Hochgeborene]]n und seine geliebte Königin verdarb. Er konnte das Ausmaß des Bösen zwar nicht ahnen, das über sie kommen sollte, spürte aber, dass das Leben der [[Nachtelfen]] bald nie mehr so sein würde wie früher ...",},
			["Brustplatte des Blutdurstes"] = { content = "Die '''Brustplatte des Blutdurstes''' ist eine Lederrüstung, die [[Malyfous Düsterhammer]] von der [[Thoriumbruderschaft]] in der [[Ewige Warte|Ewigen Warte]] in [[Winterquell]] anfertigen kann. Es heißt, dass nur eine einzige Brustplatte des Blutdurstes jemals geschaffen wurde und zwar für die legendäre Auftragsmörderin [[Garona]]. Ob diese Welt jemals eine weitere sehen wird, ist zu bezweifeln. Doch wie dem auch sei; die meisterlichen Handwerker der [[Thoriumbruderschaft]] können den Gegenstand reproduzieren, wenn die notwendigen Komponenten vorhanden sind.\r\nUm die Brustplatte des Blutdurstes herzustellen, muss man die folgenden Dinge zu Malyfous Düsterhammer bringen: \r\n* 1x \r\n* 10x \r\n* 5x [[Arkanit]]barren\r\n* 5x \r\nMan muss außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.",},
			["Brutwächter Dreschbringer"] = { content = "'''Brutwächter Dreschbringer''' ist ein [[Drakonid]] im [[Pechschwingenhort]]. Diese äußerst grausame Bestie befindet sich im Hort des Herrschers des Schwarzfels, wo Dreschbringer die Hallen des Zwists bewacht und den Wegblockiert , der in [[Nefarian]]s inneres Sanktum führt. Ihn zu töten ist Teil der Aufgabe \"Nur einer kann sich erheben\", die man vom [[Baristolth der Sandstürme]] in [[Silithus]] erhält. \r\n==Fähigkeiten==\r\nDreschbringer verfügt über folgende Fähigkeiten: \r\n* '''Druckwelle''' - Die Druckwelle entfesselt eine Flammenwelle, die in der Nähe befindlichen Feinden in einem Radius von 20 Meter 2600 bis 3400 Feuerschaden zufügt und ihr Bewegungstempo 8 Sek. lang verringert. \r\n* '''Spalten''' - Spalten fügt einem Feind und seinen nächsten Verbündeten 110% des normalen Nahkampfschadens zu, wirkt auf bis zu 3 Ziele. \r\n* '''Tödlicher Stoß''' - Der Tödliche Stoß verursacht 500% Waffenschaden und verwundet das Ziel, verringert außerdem die Wirksamkeit jeglicher Heilung 5 Sek. lang um 50%. \r\n* '''Wegschlagen''' - Wegschlagen fügt einem Feind normalen Schaden plus 30 zu und stößt ihn zurück.",},
			["Brut Nozdormus"] = { content = "Im Leben der meisten Sterblichen ist Zeit nicht viel mehr als ein einfaches Stundenglass: Lautlos und beständig rieselt der Sand hindurch. Nur die wenigsten wissen um die Wahrheit - dass die Zeit wütet wie ein entfesselter Sturm, ungezähmt und chaotisch. \r\nAls die [[Titanen]] das erste Mal Fuß auf [[Azeroth]] setzten, die [[Alten Götter]] bezwangen und der Welt Ordnung brachten, verlieh der Hochvater des Pantheons dem Drachen [[Nozdormu]] einen Teil seiner eigenen kosmischen Macht. Fortan bewachte der Drache die Zeit und kontrollierte die ewig wirbelnden Pfade des Schicksals und der Vorsehung. \r\nUnd so wurde der stoische und ehrenwerte [[Nozdormu]] als der Zeitlose bekannt. Seit jener Zeit beschützt Nozdormus Brut, stets geleitet vom Rat des Zeitlosen, den Strom der Zeit vor jenen, die diesen zu unterbrechen versuchen. \r\nJetzt ist der [[Bronzener Drachenschwarm|bronzene Drache]] [[Anachronos]] zu den [[Höhlen der Zeit]] in die Wüste [[Tanaris]] zurückgekehrt, der angestammten Heimat des bronzenen Drachenschwarms. Ereignisse sind in Bewegung geraten, die die Zukunft [[Azeroth]]s verändern werden, während die Aufmerksamkeit von [[Nozdormu]]s Brut auf [[Ahn'Qiraj]], die Festung der Qiraji, gerichtet ist. Jene, die tapfer genug sind, dem Ruf der [[Drachen]] zu folgen, werden an diesem Ort vor neue Herausforderungen gestellt. \r\nEine schreckliche Dunkelheit braut sich hinter dem Skarabäuswall zusammen, bedrohlich genug, selbst den Zeitlosen innehalten zu lassen. Die [[Drachen]] haben damit begonnen, die Helden des Landes zusammenzurufen, um in die alptraumhaften Bauten in den Tiefen [[Ahn'Qiraj]]s hinabzusteigen und zu beenden, was sie einst begonnen haben. Die schicksalhafte Stunde rückt unaufhaltsam näher...\r\nDie Brut Nozdormus misstraut den niederen Völkern für gewöhnlich.",},
			["Bräuhall"] = { content = "Man nimmt den Weg durch das Haupttor der [[Eisenschmiede]] nach Süden oder die Straße nach Norden, raus aus [[Kharanos]]. Sobald man an der kleinen Brücke (von [[Kharanos]] herkommend) ankommt, folgt man dem zugefrorenen Fluss westwärts, bis man den Eiswellensee erreicht. Am linken Ufer wird man \"Bräuhall\" (Brewnall) vorfinden. \r\nBräuhall ist ein Zeltlager von Jägern, Holzfällern und anderen Glücksjägern. Es gibt weder einen Weg direkt zur nördlichen Straße vor Gnomeregan, noch kann man den südlich aus Bräuhall heraus führenden Weg bis zur südlichen Straße zwischen [[Ambossar]] und [[Kharanos]] nutzen, da diese seit einigen Jahren nicht mehr gepflegt wird und Wildnis sie überdeckt.\r\nBräuhall könnte ein wenig Hilfe gebrauchen gegen die wilden Tiere, die die nahegelegenen Schneefelder durchstreifen. Manchmal kommen sie sehr nah. Die [[Zwerge]] hier haben keine Angst vor diesen Bären und Katzen und Ebern - kein Zwerg, der etwas auf sich hält, hätte das - aber wenn man sich für sie um diese Tiere kümmern könnte, hätten sie mehr Zeit für ihr Handwerk und ihre Braukunst.\r\n==Personen==\r\n* '''Marleth Gerstenbräu''' ist eine bittere Rivalin der Donnerbräu-Braufamilie. Doch sie muss zugeben: diese Donnerbräus stellen ein paar gute Getränke her. Aber sie müssen noch lernen, dass ihres nicht das einzige ordentliche Gebräu ist. Vielleicht kannt man ihr helfen, ihnen diese Lehre zu erteilen...\r\n* '''Rejold Gerstenbräu''' experimentiert mit seinen Gebräuen. Ein paar davon schmecken gut, einige schlecht, und einige hauen selbst den stärksten [[Zwerg]] um. Immerschimmer ist eines seiner Getränke. Er ist von einem Vorhaben besessen, dem Vorhaben, das perfekte Starkbier herzustellen. Er weiß, dass er es schaffen kann - das Brauen liegt ihm im Blut. Er muss nur das richtige Rezept finden.",},
			["Brühschlammer"] = { content = "'''Brühschlammer''' sind seltsame Kreaturen, die von Elementargeistern abstammen, aber von den Mächten des Chaos verdorben wurden. Heute sind sie eine gequälte Masse halbintelligenten Schleims und niemand kennt ihre Motivation oder weiß, ob eine bestimmte Ökologie für ihre Existenz verantwortlich ist. Die Brühschlammer scheinen sich aber anzupassen und die Eigenschaften der Gegend anzunehmen, in der sie sich befinden. \r\nDoch nicht alle der eitrigen und glitschigen Schleime sind lediglich widerlich, denn einige stellen auch eine große Gefahr dar. Obwohl Brühschlammer keine Intelligenz besitzen, werden sie von der Körperwärme anderer Lebewesen angezogen und ziehen buchstäblich das Leben aus ihren Opfern, da Brühschlammer die Wärme als Nahrung nutzen. Bisher wurden keine magischen Eigenschaften in den Brühschlammern gefunden, aber einige [[Orc]] [[Nekrolyt]]en glauben, dass die Schleime in bestimmten Gebieten versuchen das Blut der [[Orcs]] zu verschlingen. Keine bekannte Magie hat diese kriechende Massen erschaffen, aber sie existieren dennoch und dieser Schleim kann sogar durch straff sitzende Rüstung sickern, um sein Opfer zu umhüllen und ihm sein Leben zu entziehen.\r\n==Persönlichkeiten==\r\n* [[Viscidus]]",},
			["Buchband der Gier"] = { content = "Dunkle Runen huschen über die Oberfläche des '''Buchbandes der Gier'''. Die Seiten sind mit alten Elfenrunen bedeckt. Auf diesen Seiten finden sich Erinnerungen an Ereignisse, die sich bei der Sammlung und Herstellung der zur Anfertigung geringen Arkanums erforderlichen Reagenzien zutrugen. Es sind die Energien der unendlichen Weiten, die das Universum ausmachen ... \r\nUm ein \"Geringes Arkanum der Gier\" zu erlangen, muss man folgende Materialien zu Mathredis Feuerstern am [[Flammenkamm]] in der [[Brennende Steppe|Brennenden Steppe]] bringen:",},
			["Bucht der Stürme"] = { content = "Kurz vor der südlichen Halbinsel von Azshara liegt eine kleine Insel, auf der die Zwerge eine Landungsplattform gebaut haben. Die Ruinen und Strände sind buchstäblich von den [[Naga der Grollflossen]] überrannt worden. Unlängst haben sie sich soweit mit dem Land vertraut gemacht, dass sie die seltensten und wertvollsten Elemente entdeckt haben, die in Azshara heimisch sind. Genau genommen die verzauberten Koralle -- sie werden davon angezogen. In der Bucht gibt es nur noch sehr wenige Exemplare, die für Forschungen jedoch unverzichtbar sind.\r\nIn der Bucht der Stürme findet man Fürst [[Hydraxis]], einen [[Wasserelementare|Wasserelementar]], der als Botschafter der Fraktion der[[Hydraxianer]] auf Abenteurer wartet. \r\nAuch der nachtelfische [[Dämonenjäger]] Loramus Thalipedes hilft Abenteurern mit verschiedenen Aufgaben eine Waffe zu fertigen, die den Zauberschutz, der auf den Untergebenen des [[Dämonen]] Razelikh in den [[Verwüstete Lande|Verwüsteten Landen]] liegt, zu brechen. Das kostet allerdings Zeit und macht es nötig, rare Artefakte zu erwerben. Die Waffe benötigt z.B. einen Härter, den man aus den Köpfen der [[Hydra]] [[Hetaera]] gewinnt.",},
			["Buch: Die Macht in der Tiefe"] = { content = "#REDIRECT [[Die Macht in der Tiefe]]", redirect = "Die Macht in der Tiefe",},
			["Buch der teuflischen Namen"] = { content = "Das '''Buch der teuflischen Namen''' befindet sich in Besitz von [[Schwarzherz der Hetzer|Schwarzherz dem Hetzer]] im [[Schattenlabyrinth]] von [[Auchindoun]]. Es ist ein machtvolles Relikt des [[Schattenrat]]s und Viele würden für das Buch einen hohen Preis bezahlen. Gerüchte besagen, dass man ein gewisses Maß an Macht über Dämonen erhält, wenn man deren wahren Namen kennt. Das Buch der teuflischen Namen soll angeblich die wahren Namen von jedem Dämon enthalten, der jemals existierte. Dieses Buch war es auch, das dem Blutelfen Dämonenjäger [[Varedis]] seine Macht verliehen hat und es ist ebenfalls die einzige Hoffnung, Varedis besiegen zu können. \r\n \r\n'''Quellen'''",},
			["Buch der Uralten"] = { content = "Das '''Buch der Uralten''' birgt die Geheimnisse der [[Naga]]. Geheimnisse, die seit Jahrhunderten gewahrt werden. Es liegt in der Hand eines Bewahrers der [[Naga]], [[Lord Kragaru]], in [[Desolace]]. Wenn man den Edelstein der Schlange in die Hand der Schlangenstatue auf der Insel Ranazjar in [[Desolace]] legt, wird jener gerufen, der das \"Buch der Uralten\" beschützt. Dieses Buch wird von [[Azore Aldamort]] von der [[Argentumdämmerung]] bei [[Ethel Rethor]] gesucht.",},
			["Buch des Medivh"] = { content = "Durch seinen Machthunger getrieben vertiefte sich [[Medivh]] in die unergründlichen Lehren der Magie und begann, die Mysterien dieser chaotischen Kräfte zu enträtseln. Selbst die verbotenen Geheimisse von Leben und Tod offenbarten sich ihm und der gefallen [[Wächter von Tirisfal]] durchstreifte die Weiten des [[Großes Dunkles Jenseits|Großen Dunklen Jenseits]]. Medivh zeichnete die Experimente mit den Mächten der Magie in seinem legendären Zauberbuch auf und versteckte es im Turm von [[Karazhan]]. Als man von Medivhs bösen Machenschaften erfuhr, stürmten Soldaten seinen mystischen Turm und töteten ihn. Sir [[Anduin Lothar]] nahm das \"'''Buch des Medivh'''\" an sich und ließ Teile der umfangreichen Büchersammlung nach [[Dalaran]] bringen. Nach dem Zweiten Krieg wurde das mächtige Artefakt in der königlichen Bibliothek von Neu [[Sturmwind]] aufbewahrt und durch König [[Anduin Wrynn]]s treue Soldaten bewacht. \r\n===Kampf um Medivhs Vermächtnis === \r\nAber nach der Schlacht von [[Burg Nethergarde]] drangen der Ork Schamane [[Ner'zhul]] und seine [[Todesritter]] in die Festung ein und stahlen das Buch des Medivh. Sie wollten daraus lernen, wie der große Magier die Pforte zwischen [[Azeroth]] und [[Draenor]] geöffnet hatte. In der Überzeugung, dass die [[Horde]] eine neue Offensive gegen die [[Allianz]] plante, schickte König [[Terenas]] seine Armeen nach [[Draenor]], um die Bedrohung durch die [[Orcs]] ein für alle Mal zu beenden. Unter der Führung von [[Khadgar]] und General [[Turalyon]] kam es überall in der brennenden Landschaft zu schweren Zusammenstößen zwischen den Streitkräften der [[Allianz]] und den [[Orcs]]. Der [[Schattenmondklan]] und der Orden der Todesritter stellten sich den Armeen der [[Menschen]] entgegen, aber Ner'zhuls [[Festung Schattenmond]] wurde von ihnen zerstört. Der Schamane konnte zwar mit einigen magischen Artefakten entkommen, aber das Buch des Medivh fiel dem [[Klan des Lachenden Schädels]] in die Hände. Der verräterische Klan war nach dem Tod seines Häuptlings [[Mogor]] nicht mehr daran interessiert, sich Wissen über die Errichtung eines Portals anzueignen. Vielmehr versuchten die [[Orcs]] einen Vorteil aus den Unruhen des Krieges zu schlagen und ihre Machtstellung auszubauen. Im Austausch gegen das Buch des Medivh sollte die Allianz ihnen die Dominanz über den [[Schergrat]] sichern und zerstörte die dortigen Festungen anderer Stämme. \r\n===Der Schlüssel zu anderen Welten === \r\nDas mächtige Zauberbuch war wieder im Besitz der [[Menschen]], aber [[Ner'zhul]] hatte genug daraus gelernt, um Portale zu anderen Welten zu öffnen. Mit dem [[Zepter des Sargeras]] und dem [[Auge von Dalaran]] konnte er der sterbenden Welt [[Draenor]] entkommen, und überließ die orkischen Klans ihrem Schicksal. [[Khadgar]] und seine Kameraden fassten den selbstlosen Entschluss, das [[Dunkle Portal]] mit dem Buch des Medivh zu zerstören, damit Azeroth durch die brutale Vernichtung [[Draenor]]s keinen Schaden nehmen konnte.",},
			["Buch von Aquor"] = { content = "Das Buch von Aquor befindet sich im Besitz von [[Eridan Blauwind]] vom [[Smaragdkreis]] im [[Smaragdrefugium]] des [[Teufelswald]]es und wird benötigt, um in der [[Mast- und Schotbucht]] in [[Tanaris]] den [[Wasserelementar]] [[Aquementas]] zu beschwören. Dazu braucht man ebenfalls Silbrige Klauen und ein [[Eisenstammherz]] aus dem [[Teufelswald]].",},
			["Buch von Ur"] = { content = "Zum Thema [[Worgen]], hat [[Ur]], ein [[Magier]] aus [[Dalaran]] eine Abhandlung geschrieben, welche als wertvollste Quelle für [[Worgen]]studien angesehen wird. Man findet dieses Buch in der [[Burg Schattenfang]]. \r\n===Einleitung===\r\n\"Das Land [[Azeroth]] beherbergt unendlich viele Wunder. Flora, Fauna, Kulturen und Magie erblühen dort im gleichen Maße. Ja, der Neugierige findet in dieser Welt eine grenzenlose Vielfalt vor. Man braucht sich bloß einmal umzuschauen. Und wenn man genau hinsieht, dann findet man eine Vielzahl von Fenstern zu anderen Welten und jede davon birgt ihre eigenen Wunder. Aber auch ihre Schrecken. Der Zweck meines Buches: Ich wille jene Wesen und jene andersweltlichen Satanskreaturen katalogisieren, die unsere Lande zerstören, auf dass Forscher, die zufällig auf sie treffen, wissen, womit sie es zu tun haben. Wenn Ihr Euch also als Wächter von [[Azeroth]] betrachtet, so lest weiter, lest und erkennt eure Feinde.\r\n===Mythos===\r\nDie Satanskreaturen, die ich meine, sind die '''Worgen'''. Fast jede Kultur kennt solche Wesen und welches Bauernkind hätte noch nicht die Geschichten von den Wolfsmenschen gehört, die nachts durch die Wälder und Marschen außerhalb des Dorfes streichen? In diesen Geschichten mag ein Körnchen Wahrheit stecken. Vielleicht sind es Warnungen vor den Worgen, als Sagen getarnt, um uns zu ängstigen. Doch bevor ihr es nun als Ammenmärchen abtut, laßt mich euch versichern: Die Worgen gibt es wirklich. \r\n===Beschwörungen===\r\nSie mögen nicht von unserer Welt sein, aber es existieren Wege zwischen ihrer Welt und unserer und mit mächtiger Magie kann man sie herholen. Doch sollten solche Beschwörungen lieber nicht angestimmt werden, denn wo immer Worgen auch auftauchen, bringen sie Angst und Schrecken. \r\n===Aussehen===\r\nIhr werdet einen Worgen daran erkennen, dass er den Wölfen unserer Welt ähnlich sieht. Ihr werdet feststellen, dass die Worgen mit ihrem krausen Haar, den spitzen Ohren und der langen Schnauze den uns bekannten Wölfen ähneln. Aber die Unterschiede werden ebenso schnell deutlich werden. Denn das dichte Fell umgibt einen kräftigen Körper auf zwei Beinen, mit großen Fangzähnen und dolchartigen Klauen. Auch sind die Worgen von einer Bösartigkeit besessen wie man sie von keinem natürlichen Wildtier kennt. \r\n===Herkunft===\r\nDie Heimat der Worgen ist ein dunkler Ort, ein Ort des Schreckens. Falls es in dieser Welt Orte gibt, die vor den verfluchten Worgen sicher sind, so habe ich sie bei meinem Forschungen nicht gefunden. Und bedenkt man die Wildheit und Bosheit der Worgen, dann gibt es sie auch nicht. Es ist davon auszugehen, dass die Worgs in ihrer Welt bleiben wollen, denn obschon einige über durchaus mächtige Magier verfügen, haben sie von sich aus nie den Versuch unternommen, Azeroth zu erreichen. Und darüber sollten wir froh sein.\r\n===Magische Begabung===\r\nWie bereits erwähnt, sind einige [[Worgen]] durchaus magiebegabt und ihre Magie ist verderbt und dunkel. Flüche und übernatürliche Gifte sind häufig, also seid gewarnt: Wer Worg-Magici gegenübertritt, sollte gegen Schatten gewappnet sein.\"\r\nGeschrieben von [[Ur]] - Magier von [[Dalaran]]",},
			["Budd Winterhäldler"] = { content = "'''Budd Winterhäldler''' steht vor den Toren von [[Zul'Aman]] und pocht auf seine Erfolge, die er in der Vergangenheit erzielte. Er hat sich schon immer dazu berufen gefühlt, die größten Geheimnisse dieser Erde zu enthüllen, denn wenn er es nicht tut, wer dann ... Laut seiner Aussage, trifft er momentan noch die letzten Vorbereitungen, ehe die Schätze und Geheimnisse Zul'Amans ihm gehören ... Es liegt eine Menge Arbeit vor ihm, bis jetzt wurde viel erzählt, aber noch ist nichts getan und er braucht tüchtige Leute, die ihm zur Hand gehen. Es gibt Tausende, die für diese Gelegenheit bereit wären zu töten. Das kann er versichern.\r\n==Entdecker des Versunkener Tempels==\r\nTief enttäuscht, wenn man ihn nicht sofort erkennt, erzählt er, er sei der einzig wahre Budd Winterhändler. Er habe dieses Land vom Gipfel des Berges [[Hyjal]] bis hin zu den Tiefen des [[Versunkener Tempel|Versunkenen Tempels]] erforscht. Und eigentlich sei er es gewesen, der auf den Namen \"[[Versunkener Tempel]]\" gekommen ist. Er sei älter, als er aussieht, so sagt er, und weiser als jeder Abenteurer, der ihn anspricht, je sein könnte. Man würde gut daran tun, ihn nicht in Frage zu stellen. Man muss ihm ja nicht glauben. Man könne jedes örtliche schwarze Brett lesen. Man spräche überall von ihm. Aber man solle sich selbst einen Gefallen tun und die mit 'GESUCHT' im Betreff ignorieren, so rät er einem. Er versichert, dass es sich dabei lediglich um Missverständnisse handelt.\r\n==Budds Mannschaft==\r\nBudd hat Gesindel aus den unterschiedlichsten Schichten zusammengewürfelt. Scheinbar sieht so mancher über die Verschiedenheiten hinweg, solange es nur genug zu bechern gibt. Viele seiner Leute sind über die Jahre gekommen und wieder gegangen - wollten sich stets am Ruhmdes legendären Budd Winterhäldler laben. Doch man kann ihm glauben, die meisten sind reich geworden und haben sich bereits zur Ruhe gesetzt. Allerdings hat er nie diesen Weg eingeschlagen. Was mit seiner letzten Mannschaft wurde - das ist eine traurige Geschichte. Sie verschwanden hinter den Mauern [[Zul'Aman]]s und Budd hat seit Tagen nichts mehr von ihnen gehört. Dieses übereifrige Verlangen nach Ruhm und Reichtum. Er wollte sie aufhalten, sagte ihnen, dass sie nicht vorbereitet seien, aber sie entschieden sich am Ende doch für ihr Schicksal. Doch gibt es denn überhaupt noch Überlebende, die Budds Aussagen bestätigen können?",},
			["Budd Winterhändler"] = { content = "#REDIRECT [[Budd Winterhäldler]]", redirect = "Budd Winterhäldler",},
			["Bund von Arathor"] = { content = "Der Bund von [[Arathor]] will verlorene Ländereien des [[Arathibecken]]s wieder für ihre Gönner in [[Sturmwind]] zurückgewinnen. Es ist ein blutiges Unterfangen um die Ressourcen von [[Arathor]] zu kämpfen, aber der Bund von Arathor scheut keine Mühen, um [[Arathi]] sein Eigen zu nennen. Die Menschen und all die anderen Völker der [[Allianz]] strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der [[Zuflucht]] im [[Arathihochland]] aus zu erweitern.",},
			["Burg Cenarius"] = { content = "'''Burg Cenarius''' ist ein Stützpunkt des [[Zirkel des Cenarius]] in [[Silithus]], der sowohl für die [[Allianz]] als auch für die [[Horde]] zugänglich ist.\r\nBurg Cenarius ist von außerordentlicher strategischer Bedeutung. Man ist davon überzeugt, dass der Sieg über die [[Silithiden]] feststeht, solange die [[Druiden]] die Burg halten können. Natürlich unter der Bedingung, dass sie die Versorgung mit Nachschubgütern aufrecht erhalten können. Seitdem ständig neue Rekruten auf Burg Cenarius eintreffen, stehen sie vor dem Problem, sie in der Wüste am Leben zu erhalten. Der ständige Wasserentzug und die zahlreichen giftigen Kreaturen in dieser Gegend sind eine ernstzunehmende Gefahr für die unerfahren Soldaten.\r\n==Personen==\r\n* '''Aurel Goldblatt''' - Aurel Goldblatt befindet sich im östlichen Teil von Burg Cenarius und glaubt einen Weg gefunden zu haben, eines der führenden Mitglieder des abyssischen Rates zu beschwören und zu besiegen. Sie kann Anleitung geben, wie man mit Hilfe der Windsteine, einen der Fürsten des abyssischen Rates in eine Falle zu lockt. Für den Täuschungsversuch wird man ein [[Standesmedaillon eines Schattenhammerkultisten]] benötigen, doch Aurel kann ein solches Medallion nachbilden. Um einen der Steine ohne Gefahr benutzen zu können, wird sie auch versuchen, die Robe eines Abgesandten des Schattenhammers bis ins kleinste Detail nachzubilden.\r\n* '''Baristolth der Sandstürme''' - Baristolth der Sandstürme wurde vom [[Bronzener Drachenschwarm|Bronzenen Drachenschwarm]] als Wächter auserwählt. Der Tod umarmte ihn bereits als [[Anachronos]] erschien und seine Macht auf ihn anwandte. Der Drache ließ seinen Atem nur einmal über seinen versehrten Körper streichen und wartete daraufhin geduldig bis die Zeit seine Wunden geheilt hatte. \"Wenn es sein muss, wirst du für immer existieren\", sagte [[Anachronos]], und mit diesen Worten sollte Baristolth auf ewige Zeiten als Wächter gebunden sein. Er muss sich dafür entschuldigen, so viel geheim zu halten, doch die Feinde sind überall, selbst unter ihnen. Wenn er die [[Prophezeiung von C'Thun]] hört, beginnt er ungemütlich hin und her zu rutschen. Er sagt: \"Wenn die Zeit reif ist, Euer Gnaden. Wenn es soweit ist, wird alles klar vor uns liegen. Selbst jetzt regt sich der Meister. Seht zum Himmel, denn die Brut Nozdormus ist zurückgekehrt.\"\r\n* '''Beetix Wankelhupf''' ist ein Goblin. Sie hat es geschafft die Wirkung des Gifts von Noggle zu verlangsamen, aber um es vollständig neutralisieren zu können, benötigt sie Giftproben von was auch immer ihn gestochen haben mag. Noggle kam aus dem Norden, daher verwettet sie man letztes Hemd darauf, dass es Steinpanzerskorpide oder Sandhuscher waren. Doch das Gegengift hat nicht gewirkt. Der Haken ist allerdings, dass in der südlichen Gegend mehrere Arten giftiger Kreaturen herumfleuchen und man daher verschiedene Proben besorgen müsst.\r\n* '''Bor Wildmähne''' führt den Kampf gegen den [[Schattenhammer Kult]]. Wenn man sich als ein führendes Mitglied des Kults ausgeben kann, möchte Bor gerne mit einem sprechen. Noch weiß man nicht, ob das die Wesen sind, die die Kultisten verehren, oder ob diese Wesen nur Botschafter einer weit größeren Macht sind, doch nichts stürzt eine Organisation so sehr ins Chaos, wie eine Unterbrechung der Befehlskette. \r\n* '''Calandrath''' ist die Gastwirtin und weiß viel über die Pflanzen, die in der Wüste wachsen. Momentan braucht sie einen Küchengehilfen.\r\n* '''Dirk Donnerholz''' gehört zu den [[Rabenholdt]]. Sein Bruder und er sind im Rabenholdtanwesen für den Giftbedarf zuständig. Lord Rabenholdt hat ihn damit beauftragt, eine neue und extrem effektive Giftmischung zusammenzustellen, die aus den Giftbeuteln der Bewohner von [[Zul Gurub]] und den [[Ruinen von Ahn'Qiraj]] gewonnen werden kann. Es gibt in diesen verfluchten Ruinen zwei ganz besonders giftige Bestien, die vielleicht genau das haben, wonach sie suchen.\r\n* '''Geologin Lerchenbann''' - Geologin Lerchenbann interessiert sich für die Schrifttafelfragmente des Schattenhammerklans bringt. Vielleicht können sie so etwas Licht in die Sache bringen und herausfinden, was die Anhänger des Schattenhammerklans in [[Silithus]] gesucht haben. Und vielleicht kann man auch [[Ortell der Einsiedl|Ortell den Einsiedler]] davon überzeugen, bei der Entschlüsselung der Schrifttafel behilflich zu sein. Geologin Lerchenbanns Studien haben sich für die Operationen in [[Silithus]] als sehr wertvoll erwiesen, denn sie hat u.a. die [[Prophezeiung von C'Thun]] entziffert, so wie einst vom [[Prophet Skeram|Qirajipropheten Skerram]] verfaßt wurde. Vor kurzem hat sie eine Ladung magischer Materialien angefordert, die sie für ihre weiteren Forschungen dringend benötigt. \r\n* '''Huum Wildmähne''' schickt Freiwillige gegen den Abyssischen Rat ins Feld. \r\n* '''Kolossforscher Nestor''' verschickt Fragmente vom Koloss der einzelnen [[Silithiden]]-Schwärme in die ganze Welt. Er geht davon aus, dass die Geheimnisse dieser Kolosse z.B. im Kampf gegen die Geißel sehr von Nutzen sein werden.\r\n* '''Kommandant Mar'alith''' ist der Anführer vom [[Zirkel des Cenarius]] in [[Silithus]]. Der Kommandant war in letzter Zeit nicht er selbst, denn seine geliebte [[Natalia Mar'alith]] verschwand während einer archäologischen Ausgrabung in der südlichen Wüste - spurlos. Der Kommandant möchte nun, dass man sie wiederfindet. Man muss dafür in den Bau des [[Regalschwarm]]s eindringen und herausfinden, was aus Natalia geworden ist. \r\n* '''Noggle Wankelhupf''' ist ein [[Goblin]] und der Cousin von Beetix Wankelhupf. Er hat es sich zum Lebensinhalt gemacht, seltene Kräuter für die [[Alchimist]]en der Burg Cenarius zu sammeln, doch er kam von seinem letzten Ausflug mit einer starken Vergiftung zurück. Noggle muss von einer der stärkeren Kreaturen im fernen Süden gestochen worden sein. Er hat ebenso seine Tasche verloren haben, als er vor Totenstachel, dem Riesenskorpid, geflohen ist und bei seiner überstürzten Flucht ist er geradewegs in ein Nest von Steinpanzerschindern gerannt. In dem Ranzen befanden sich allerlei seltene Reagenzien. Beetix und er werden ohne sie nicht die Tränke herstellen können, die von der Burg Cenarius benötigt werden.\r\n* '''Vish Kozus''' ist der Hauptmann der Wache ganz oben auf dem Wachturm der Burg Cenarius. Er rekrutiert Freiwillige Helfer für logistische Einsätze, denn die berittene Einheit der Wache von Burg Cenarius hat kaum noch Vorräte an verschnörkelten Mithrilstiefeln oder Schleifsteinen.\r\n* '''Windrufer Kaldon''' ist ein Taure und schickt Abenteurer zum Felddienst zu [[Krug Schädelspalt]] von der [[Orgrimmarlegion]] bzw. [[Hauptmann Rußschmied]] von der [[Eisenschmiedebrigade]].\r\n* '''Windruferin Prachthorn''' ist eine Taurin und kümmert sich um die Sicherung der Versorgungslinien. Die Sandwürmer in dieser Gegend stellen für die Nachschubkarawanen eine noch größere Gefahr dar als die Silithiden selbst. Erst heute Morgen verloren sie eine ganze Morgenkornlieferung an eine Gruppe Baggerschläger. In Abwesenheit der Baggerschläger, werden ihre südlichen Artgenossen nach Norden drängen, um ihren Platz einzunehmen. Es wurden auch mehrfach berittene Gruppen des Schattenhammerklans gesichtet, die außerhalb der Reichweite der Truppen in Burg Cenarius, kleinere Patrouillen und Karawanen angreifen.",},
			["Burg Durnholde"] = { content = "'''Burg Durnholde''' befindet sich nicht weit südöstlich von [[Tarrens Mühle]], nur über den Fluss, im [[Vorgebirge des Hügellands]]. Diese Ruine war eine alte Gefängnisfestung, die für die Sicherheit der [[Internierungslager]] in [[Lordaeron]] verantwortlich war. \r\n==Geschichte==\r\nDie Lager wurden von [[Aedelas Schwarzmoor]] verwaltet, der Söldnerhauptmann [[Danath Trollbann]] als leitenden Offizier abgelöst hatte. [[Thrall]], der später sein Volk aus den Internierungslagern befreien sollte, wurde hier von [[Aedelas Schwarzmoor|Schwarzmoor]] zu einem furchtlosen Krieger erzogen und unterrichtet. Er wollte mit [[Thrall]]s Hilfe die [[Horde]] übernehmen und sich damit zum Herrscher über seine Mitmenschen aufschwingen. Nach einem Feuer in der Festung, konnte der junge Orc jedoch fliehen und Seinesgleichen suchen. Als die neue [[Horde]] begann, die Internierungslager zu erstürmen und die [[Orcs]] aus der Gefangenschaft zu befreien, wurde auch Durnholde zerstört. Kriegshäuptling [[Thrall]] war als Symbol der Wiedergeburt seines Volkes in Schwarzmeers Festung zurückgekehrt und vereitelte die Pläne seines einstigen Herrn, indem er ihn im Zweikampf tötete. \r\n==Neue Besitzer==\r\nDas [[Syndikat]] sammelt sich in den Ruinen der Burg Durnholde im Südosten von [[Tarrens Mühle]] im [[Vorgebirge des Hügellands]]. Es beschäftigt eine Gruppe menschlicher Briganten in dieser Region, die Schattenmagier. Diese Magier beschaffen sich das [[Blut Unschuldiger]] für ihre unappetitlichen Machenschaften. In Lady [[Sylvanas Windläufer]]s Namen sollen alle Mitglieder dieser Organisation getötet werden und diejenigen, die bereits gefangen genommen wurden, werden gemeinschaftlich hingerichtet. \r\n==Personen==\r\nDie [[Orcs]] Drull und Tog'thar werden dort gefangen gehalten. \r\n* [[Aedelas Schwarzmoor]]\r\n'''Quellen''':",},
			["Burg Nethergarde"] = { content = "Die Burg Nethergarde schmiegt sich an die nördlichen Hügel der [[Verwüstete Lande|Verwüsteten Lande]] und wacht über das [[Dunkle Portal]]. Um die Burg zu erreichen, muss man im [[Dämmerwald]] nach Osten über den [[Gebirgspass der Totenwinde]], dann nach Osten durch die [[Sümpfe des Elends]] und dann nach Süden durch die verwüsteten Lande. \r\nDer Erzmagier [[Khadgar]] hatte das [[Dunkle Portal]] zwar zerstört, aber die Pforte, die [[Medivh]] einst geöffnet hatte, blieb bestehen. Die [[Kirin Tor]] aus [[Dalaran]] errichteten Burg Nethergarde, um die Pforte zu untersuchen und als Schutz zu dienen, falls sie sich wieder öffnen sollte. Nur wenige Monate später gelang es den [[Orcs]] tatsächlich das [[Dunkle Portal]] wieder zu errichten, und die Burg wurde von ihnen belagert. Aber dank der Truppe aus Neu [[Sturmwind]], die unter dem Kommando von Sölderhauptmann [[Danath]] standen, konnte die [[Horde]] durch das Tor zurückgedrängt werden. \r\nHeute führen die [[Magier]] von [[Sturmwind]] Forschungen in der Burg Nethergarde durch, die entscheidend für ihr Verständnis der dunklen Portale sind. Sie benötigen fast ununterbrochen Nachschub, doch ihre Nachschubwege nach Nethergarde sind dürftig.\r\n==Personen==\r\n* '''Botschafter Ardalan''' glaubt, dass sie den falschen Feind bekämpfen. Die wahre Macht in diesem Land wird zahlen- und kräftemäßig immer stärker, während sie sie mit den [[Orcs]] über verbrannte Erde zanken. Sollen sie wirklich in diesem Land einen Krieg gegen die [[Horde]] führen, nur um eines Tages von den Armeen der [[Brennende Legion|Brennenden Legion]] hinweggefegt zu werden? \r\n* '''Thadius Grimmschatten''' befindet sich im Magierturm der Burg Nethergarde. Er verließ vor Jahren den [[Nistgipfel]] im Hinterland, um sich dunklerem Wissen zuzuwenden, aber in seinem Herzen ist er immer noch ein [[Wildhammer]].",},
			["Burg Schattenfang"] = { content = "Während des Dritten Krieges kämpften die Hexer der [[Kirin Tor]] gegen die untoten Armeen der [[Geißel]]. Mit jedem Hexer, der im Kampf fiel, stand kurze Zeit später bereits ein weiterer [[Untote]]r auf Seiten der Geißel seinen einstmaligen Mitstreitern als Feind gegenüber. Frustriert über den aussichtslosen Kampf beschloss der [[Erzmagier Arugal]] gegen den Willen seiner Kollegen, Wesen aus einer fremden Dimension zu Hilfe zu rufen um die schwindenden Reihen der Hexer zu stärken. Arugals Beschwörung brachte die gefräßigen [[Worgen]] nach [[Azeroth]]. Zwar machten die unaufhaltsamen Werwölfe kurzen Prozess mit allem, was die Geißel ihnen entgegenstellte, doch nach kurzer Zeit wandten sie sich auch gegen die [[Magier]], denen sie eigentlich dienen sollten. So kam es, dass die Worgen die Burg des adligen [[Baron Silberlein]] jenseits des unscheinbaren Dörfchens [[Lohenscheit]] angriffen. Von Schuldgefühlen halb wahnsinnig adoptierte Arugal die Worgen als seine Kinder und zog sich in die inzwischen verfallene Burgruine zurück. Dort soll er immer noch hausen, unter dem immer wachsamen Auge seines gewaltigen Schoßhundes [[Fenrus]], heimgesucht von dem rastlosen Geist von [[Baron Silberlein]]. \r\n'''Quelle:''' \r\n==Schätze==\r\n* [[Buch von Ur]]\r\n==Personen==\r\nAls Vorbereitung auf einen Überfall auf Schattenfang wurden von den [[Verlassene]]n die beiden [[Todespirscher]] Adamant und Vincent in die Burg geschickt, um Informationen zu sammeln. Das war vor mehreren Tagen und sie sind noch nicht wieder zurück. Vincents Körper liegt zerschmettert und leblos im Hof der Burg. Todespirscher Adamant wird Hadrec zwar seinen Bericht schicken, aber was immer Vincent zusätzlich noch wusste, wird für immer sein Geheimnis bleiben. Seine Hand jedoch umklammert ein kleines Stück Plunder...\r\n* [[Erzmagier Arugal]]\r\n* [[Baron Silberlein]]\r\n* [[Fenrus der Verschlinger]]\r\n* [[Klingenklaue der Metzger]]\r\n* [[Kommandant Grüntal]]\r\n* [[Odo der Blindseher]]\r\n* [[Rotkralle]]\r\n* [[Ur]]\r\n* [[Wolfmeister Nandos]]\r\n* [[Sever]] - Ein [[Flickwerkschrecken]] in der Burg Schattenfang während der [[Invasion der Geißel]].",},
			["Burg Steinwacht"] = { content = "Die [[Orcs des [[Schwarzfels]]-Klans haben die [[Brennende Steppe]] verlassen und Burg Steinwacht im Norden des [[Rotkammgebirge]]s besetzt. Von dort aus ziehen sie marodierend durch das Gebiet nördlich von [[Seenhain]], so dass dessen Bewohner sich nicht mehr aus der Stadt wagen und dort eingesperrt sind wie Vieh in einem zu engen Pferch. Und obwohl der [[Schwarzfelsklan]] die Menschen vor allem aus dem Norden bedroht, hat man auch gehört, dass sich noch weitere Schwarzfelsorcs in der südöstlichen Ecke des [[Rotkammgebirge]]s aufhalten. Zwischen [[Seenhain]] und Burg Steinwacht legen Kundschafter und Renegaten des Schwarzfels ständig Hinterhalte. Der Anführer der Kundschafter heißt Tharil'zun. Von den [[Orcs des Schwarzfels]]klans wurden zur Unterstützung ihrer Angriffe auf das Rotkammgebirge Schattenzauberer rekrutiert, die von einer dunklen Macht erfüllte Vorrichtungen mit sich führten - Mitternachtskugeln. Diese Kugeln haben den Verteidigern vom Rotkammgebirge schwere Verluste zugefügt. \r\nGath'llzogg ist der Rädelsführer hinter den Angriffen des Schwarzfelsklans auf Burg Steinwacht und den Überfällen auf die Ortschaft [[Seenhain]]. Er ist äußerst gefährlich. Berichten zufolge hat er sich in der kürzlich eroberten Burg eingenistet und plant dort die weiteren Verbrechen des Schwarzfelsklans gegen die menschliche Bevölkerung.",},
			["Burg Stromgarde"] = { content = "Die [[Menschen]] der [[Zuflucht]] kämpfen einen Kampf um Burg Stromgarde und sie verlieren ihn. Die [[Oger]], das [[Syndikat]] und sie haben die einst große Stadt geteilt und jede Fraktion bekämpft die andere bis zu einem blutigen Unentschieden. Aber die Streitkräfte schwinden, während die Feinde immer stärker werden. Die [[Menschen]] brauchen Hilfe aus der Stadt [[Süderstade]], aber Vorräte sind nur schwer zu bekommen, solange das [[Syndikat]] das Gebiet zwischen ihnen kontrolliert. \r\nDas [[Syndikat]] in Stromgarde bekämpft das Kontingent der Miliz dort. Um diesen Pöbel dazu zu bringen, sich mit den disziplinierteren Streitkräften zu schlagen, haben die Syndikatsanführer ein Kopfgeld auf die Soldaten ausgesetzt und belohnen jedes Abzeichen von [[Stromgarde]], das toten Milizleuten abgenommen wurde, mit Gold. \r\nDie Anführer der Angriffe der [[Oger der Felsfäuste]] im [[Arathihochland]] haben ihren Unterschlupf innerhalb der Ruinen von [[Stromgarde]] gewählt.\r\n==Personen==\r\n* '''Leutnant Heldenruf''' - Leutnant Heldenruf ist der Anführer der Kavallerie von Stromgarde und bewacht das Siegelzeichen von Arathor.\r\n* '''[[Marez Schattenkutte]]'''\r\n* '''Or'Kalar''' - Or'Kalar ist [[Mugh'thol]]s Helfer in [[Stromgarde]]. \r\n* '''Prinz [[Galen Trollbann]]'''\r\n* '''Deneb Wandler''' - Deneb Wandler ist Händler für Schriftrollen und Tränke, sowie unverzichtbarer Ansprechpartner für alle sie sich mit [[Heilkunst]] beschäftigen.",},
			["Burg Sturmwind"] = { content = "Die majestätische '''Burg Sturmwind''' befindet sich im östlichen Teil von [[Sturmwind]]. Hier resideren die Regenten und der Adel von Sturmwind.\r\n===Königliche Bibliothek===\r\nDie königliche Bibliothek von Sturmwind besitzt eine ansehnliche Größe, doch der oberste Bibliothekar, [[Milton Garbenbund]], kennt jedes Regal, als wäre es sein eigenes Kind. Hier findet man u.a. mehr Informationen über den [[Stein der Gezeiten]].\r\n==Personen==\r\n'''Lehrer für einen Beruf'''\r\n'''Händler'''\r\n'''Weitere Persönlichkeiten'''\r\n'''nicht mehr anwesende Persönlichkeiten'''",},
			["Burg Tiragarde"] = { content = "Angeführt von Admiral [[Daelin Prachtmeer]] drangen die Menschen von [[Kul Tiras]] nach [[Durotar]] vor und brachen damit den Pakt, den der Kriegshäuptling [[Thrall]] vor Jahren mit [[Jaina Prachtmeer]] geschlossen hatte, um [[Archimonde]] zu besiegen. Die menschlichen Aggressoren wurden zurückgeschlagen und Burg Tiragarde fiel. \r\nKürzlich jedoch hat die Reserve des Admirals unter der Führung von [[Leutnant Benedict]] die Burg zurückerobert und stellt erneut eine Bedrohung für das Heimatland der [[Orcs]] dar. Diese [[Menschen]] haben keinen Respekt vor Diplomatie. Die [[Orcs]] haben immer mit wachsamen Augen an ihrer Seite gekämpft, weil sie wussten, dass die [[Menschen]] sie eines Tages verraten würden. Leider war [[Daelin Prachtmeer|Admiral Prachtmeers]] Tod nicht genug, um sein Vermächtnis des Betrugs aufzuhalten. Der Menschenabschaum hatte vor seinem Ableben alles gut durchgeplant und seine Herrschaft würde, wie es scheint, nicht einmal mit [[Leutnant Benedict]] enden. Wer weiß, wann die nächste Welle von Prachtmeers Männern an den Küsten [[Durotar]]s landen wird. \r\n[[Admiral Prachtmeers Befehle]] liegen noch in der Burg. Es handelt sich um einen alten, verwitterten Umschlag mit einem offiziell aussehenden Dokument und dem Siegel von Admiral Prachtmeer. Ein aufmerksamer Späher hat auch die Kunde gebracht, dass die Trümmer von Prachtmeers Flotte immer noch an der Küste [[Durotar]]s liegen, gleich östlich von Burg Tiragarde. Es ist kein Geheimnis, dass die [[Menschen]], die sich mit diesen elenden kleinen, als [[Gnome]] bekannte Kreaturen verbündet haben, über reichliches Wissen auf dem Gebiet der Mechanik verfügen und dass Teile dieser Erfindungen noch immer dort bei den Wracks liegen.",},
			["Burg Utgarde"] = { content = "Inmitten der Klippen der [[Dolchbucht]] im [[Heulender Fjord|heulenden Fjord]] steht '''Burg Utgarde''', eine uneinnehmbare Festung, in der die wilden und geheimnisvollen [[Vrykul]] hausen. Das alte Bollwerk erstreckt sich weit in die Erde, doch bisher überlebte kein Späher der [[Allianz]] oder [[Horde]] lang genug, um seine Tiefen zu ergründen. Lang als verlassen geglaubt, ist Utgarde nach Jahrtausenden der Leere erst seit Kurzem wieder bewohnt. Nun strömen die Halbriesen der [[Vrykul]] schier endlos aus den Tiefen der kampferprobten Mauern, um die nahen Siedlungen anzugreifen.\r\nFanatisch loyal zu ihrem noch immer schlafenden [[König Ymiron]], scheinen die [[Vrykul der Drachenschinder]] für den Rausch des Kampfes zu leben. Allen von [[Ingvar der Brandschatzer|Ingvars]] Räubern wohnt eine ungeheure Kraft und Ausdauer inne und die Vrykul Runensprecher beherrschen auch die arkanen Künste. Obwohl sich Gerüchte halten, dass sich die Gefolgschaft von Ymiron mit der [[Geißel]] verbündet hat, haben alle Bewohner des [[Heulender Fjord|Heulenden Fjords]] bereits die üblichen Verbündeten der Drachenschinder gesehen: [[Protodrachen]]. Die Vrykul Drachenreiter haben die furchterregenden [[Protodrachen]] zu Reittieren gezähmt. Da die Diener von Ymiron eigener Hände Arbeit als zu niedere Beschäftigung ansehen, befürchten die mutigen Abenteurer des [[Heulender Fjord|Heulenden Fjords]], dass die [[Vrykul]] eine fremde Quelle angezapft haben, um die Arbeiten zu verrichten...\r\nMit mysteriösen, verdorbenen Magien und [[Protodrachen]] unter ihrem Kommando stellen die [[Vrykul]] von Burg Utgarde eine unmittelbare Bedrohung sowohl für die [[Allianz]] als auch die [[Horde]] dar. Nur die Mutigsten werden es wagen, einen Schlag gegen [[König Ymiron]]s Getreue zu führen und in das Herz des urzeitlichen Heims der Vrykul vorzustoßen. \r\n==Teilbereiche==\r\n* Burg Utgarde (siehe unten)\r\n* [[Turm Utgarde]] \r\n* Burg Utgarde Schlachtzug\r\n==Burg Utgarde -Instanz==\r\n* '''Die Schmiede''' - Die Schmiede ist der allererste Raum in Utgarde. Dort erbauen die Vrykul gewaltige Kriegsmaschinen in ewig glühenden Schmieden. \r\n* '''Die Drachenställe''' - Die Drachenställe beherbergen die [[Protodrachen]]reittiere der [[Vrykul]].\r\n* '''Der Balkon''' - Der Balkon ist hoch über der Burg mit Blick auf die [[Dolchbucht]], [[Valgarde]] und den nahen Wasserfall. Man kann sogar [[Drachen]], die gerade Angriffe auf ihre Ziele unten am Boden starten, sehen. \r\n==Bosse==\r\n* [[Skarvald der Konstrukteur]] / [[Dalronn der Aufseher]]\r\n* [[Ingvar der Brandschatzer]]\r\n* [[Prinz Keleseth]]",},
			["Buru der Verschlinger"] = { content = "'''Buru der Verschlinger''' ist ein [[Silithiden Koloss]] in den [[Ruinen von Ahn'Qiraj]]. Er befindet sich in einem Raum mit 6 im Kreis arrangierten Eiern und einer von einer Sandfläche umrandeten Wasserfläche.",},
			["Bär"] = { content = "== Arten==\r\n \r\n==Persönlichkeiten==\r\n* '''Alte Rußtatze''' - Alte Rußtatze, der Bär, hält sich irgendwo in der Nähe seines Baus in den Hügeln über [[Thelsamar]] auf. Vor einem Jahr war dieser große Bär das Ziel der [[Jagdhütte der Weltenwanderer]] in [[Loch Modan]], aber keiner der Jäger hatte Glück mit ihm. Also dachte sich [[Daryl der Jüngling ]], er könnte sich mal an ihm versuchen, aber das einzige, was er nach seinem Versuch vorweisen konnte, war eine hässliche Narbe über seinem Auge. \r\n* '''Eisbart der Alte''' - Dun Morogh.\r\n* '''Höhlenmutter''' - Dunkelküste.\r\n* '''Marterklaue''' - Marterklaue in [[Dun Morogh]] ist ein gewaltiget Eisklauenbär.\r\n* '''Mongress''' - Teufelswald. \r\n* '''Samras''' - Vorgebirge des Hügellands.\r\n* '''Silbergrimm der Weise''' - Feralas.\r\n* '''Todespranke''' - Blutmythosinsel. Der Bär lungert westlich von Kloppers Schildkrötenhaus herum. Todespranke wird als besonders gefährlich eingestuft und ist für den Tod eines Vermessungsteams an der Küste im Nordwesten der Blutwacht verantwortlich. Reisende werden angehalten, diese Gegend zu meiden.\r\n* '''Ursangus''' - Eschental. Die Tatze des mächtigen Bären Ursangus stellt die Trophäe der Jagd im Eschental dar. Auf der Tatze befindet sich ein kleines Halbmond-Emblem; die Bedeutung dieses Emblems bleibt jedoch ein Geheimnis. \r\n* '''Ursius''' - Winterquell. In den schneebedeckten Bergen von Winterquell pirscht sich ein geschickter Jäger an seine Beute an: der Splitterzahnbär Ursius, eine flinken und schlauen Bestie. Er zieht durch die wogenden Hügel im Nordwesten der Ewigen Warte. Alle, die bisher gegen Ursius gezogen sind, haben schnell herausgefunden, dass sie die Beute waren und er der Jäger. \r\n* '''Ursol'lok''' - Eschental. \r\n* '''Zwingenkiefer''' - Silberwald.",},
			["Bären"] = { content = "#REDIRECT [[Bär]]", redirect = "Bär",},
			["Bäumling"] = { content = "#REDIRECT [[Bäumlinge]]", redirect = "Bäumlinge",},
			["Bäumlinge"] = { content = "Bäumlinge sind [[Naturelementare]], die wie Sumpfmonster aussehen. Diese seltsamen Kreaturen stammen von Elementargeistern ab, wurden aber von den Mächten des Chaos verdorben. Heute sind sie eine gequälte Masse halbintelligenten Schleims und niemand kennt ihre Motivation oder weiß, ob eine bestimmte Ökologie für ihre Existenz verantwortlich ist. Von den [[Nachtelfen]] werden Bäumlinge als Naturgeister angesehen, in denen sich in gewisser Weise die natürliche Ordnung von Flora und Fauna des großen [[Weltenbaum]]es widerspiegelt. Manche Arten von Bäumlingen, die in der Wüste von [[Tanaris]] überleben gelernt haben, können in speziellen Drüsen Wasser speichern und genau das wollen sich die [[Goblins]] in [[Gadgetzan]] bei ihrer Suche nach alternativen Wasserquellen zunutze machen. Die [[Königliche Apothekervereinigung]] derweil denkt, dass sich das Moos dieser verderbten [[Naturelementare]], die auf den Inseln im [[Lordameresee]] leben, bei der Suche nach einer neuen [[Seuche]] als nützlich erweisen könnte.\r\n==Arten==\r\n* [[Schattendickichtbäumlinge]]\r\n* [[Wucherborkenelementare]]\r\n==Besondere Bäumlinge==\r\n* [[Grimmeiche]]\r\n* [[Schattendickichtorakel]]\r\n* [[Schwarzmoos der Stinker]]\r\n* [[Verdan der Ewiglebende]]",},
			["C'Thun"] = { content = "==Allgemeines==\r\nC'Thun war einst ein mächtiger Alter Gott. Doch durch den Kampf gegen die [[Titanen]] wurde er stark geschwächt. C'Thun, wurde in [[Silithus]] in einer Schlacht besiegt, welche ebenso in der Niederlage eines [[Titanen]] endete. C'Thun wurde angeblich permanent besiegt, aber tauchte als die treibende Kraft hinter den [[Qiraji]] wieder auf. Er ist der einzige der Alten Götter, dessen Name bislang bekannt ist, und diesen erhielt er von seinen [[Qiraji]]-Dienern. Er ist tief unter dem zerstörten Tempel von [[Ahn'Qiraj]] eingesperrt, wo er für tausende von Jahren seinen Willen über die [[Qiraji]] ausgeübt hat, die wiederum die [[Silithiden]] befehligen. \r\nGerüchte kreisen, dass C'Thun mit seinem großen, entsetzlichen lidlosen Auge, umgeben von einem Meer aus Tentakeln, angekommen ist und jeden unwissenden Sterblichen verdammen wird, der denkt die Herausforderung an seine überragende Kraft und dem Recht zur Welt von [[Azeroth]] zu wagen. \r\n==Herkunft==\r\n[[Alte Götter]] gehören zu den mächtigsten Wesen, die jemals auf [[Azeroth]] wandelten. Keiner kennt ihre wahren Namen oder ihre Natur. Alles, wass darüber bekannt ist, ist dass es fünf von ihnen gab. Die junge Welt war ihre und sie beherrschten sie zufrieden. Als die [[Titanen]] kamen, vergingen Äonen während der Kämpfe gegen die fünf Alten Götter. Einer der alten Götter wurde getötet; aber auch die anderen wurden besiegt. Drei wurden geschwächt, während C'Thun in den unfruchtbaren Ländern von [[Silithus]] fiel .. \r\n... Fiel, aber nicht starb. Über zahllose Zeitalter schlief C'Thun und beobachtete wie die Rassen sich entwickelten und einander bekämpften, sah die Invasion der Legion und mehr noch ... Er erschuf Pläne für die Zukunft - seine Zukunft. \r\nIn der Wüste in welcher er fiel, fand C'Thun primitive Lebenformen, die [[Silithiden]]. Der Alte Gott erschuf Avatare aus den Silithiden nach seinem eigenen Bild. Diese Avatare wurden bekannt als die [[Aqir]], eine empfindungsfähige Rasse, die [[Silithus]] besetzen würde. Die große Festungsstadt [[Ahn'Qiraj]] wurde erschaffen, um ihre wachsenden Armeen zu beherbergen und um sie auf die Ankunft von C'Thun vorzubereiten. \r\nJahrhunderte später führten die [[Qiraji]] einen Krieg gegen die [[Nachtelfen]] und die [[Drachen]], um Gebiet für die ruhmvolle und umwälzende Ankunft von C’Thun zu beanspruchen. Um die Invasion zu verhindern, wurde [[Ahn'Qiraj]] mit dem Skarabäuswall versiegelt, wofür die vereinte Magie von [[Drachen]] und [[Nachtelfen]] gebraucht wurde. Tausende Jahre lang arbeiteten die [[Qiraji]] unermüdlich, um C'Thun in seiner wahren physikalischen Form wiederzubeleben.\r\n==Anmerkungen==\r\n* C'Thun trägt eine auffallende Ähnlichkeit zu dem Vergessenen unter [[Azjol-Nerub]] in Warcraft III:Der Eisthron. \r\n* Auch das [[Alte und mächtige Böse]]-Wesen, welches die [[Arakkoa]] im [[Schattenmondtal]] auf der [[Scherbenwelt]], gleich im Süden der Wildhammerfeste beschwören wollen, ähnelt C'Thun bzw. einem alten Gott.",},
			["Caelestrasz"] = { content = "Caelestrasz war ein [[Roter Drachenschwarm|Roter Drache]] und Erbe von [[Alexstrasza]], der am [[Krieg der Sandstürme]] in [[Silithus]] teilnahm. Während des Krieges opferte er sich zusammen mit den beiden anderen großen Drachen, [[Arygos]] und dem [[Merithra des Traums]], um beim Aufbau des [[Skarabäuswall]]s zu helfen.",},
			["Caer Darrow"] = { content = "#REDIRECT [[Darrowehr]]", redirect = "Darrowehr",},
			["Cairne Bluthuf"] = { content = "==Allgemeines==\r\nCairne Bluthuf ist ein mächtiger [[Tauren Häuptling]] und ein weiser Führer für sein Volk. Er ist ein herausragender Krieger und gilt als eines der gefährlichsten lebenden Geschöpfe überhaupt. Obwohl er etwas durch sein Alter geschwächt ist, ist Cairne immer tapfer und besitzt den Wert von 20 Männern. \r\n==Charakter==\r\nCairne ist fest entschlossen, in einer Welt zunehmender Finsternis für die Sicherheit seines Volkes zu sorgen und ihm zu dienen. Doch ungeachtet seiner Kraft und Tapferkeit ist er eine sanfte Seele, deren ganze Sehnsucht dem Frieden und der Ruhe der weiten Ebenen gilt. \r\n===Häuptlingsbürde===\r\nHinter vorgehaltener Hand wird gemutmaßt, dass Cairne [[Donnerfels]] sofort verlassen und sich in die Wildnis zurückziehen würde, wenn er die Häuptlingsbürde einem anderen übergeben könnte. Viele sind überzeugt, dass er seinen Sohn [[Baine Bluthuf]] ausbildet, damit er eines schicksalsschweren Tages seine Stelle als Häuptling einnehmen kann.\r\n==Geschichte==\r\nDieser Riese mit großem Herz wusste, dass sein Volk die Ausrottung durch die herumreisenden [[Zentauren]] droht. Aber er hat nie die Hoffnung verloren, eines Tages einen Weg zu finden, seine Brüder und Schwestern an einen Ort zu führen wo, sie in Frieden leben können. Dank der Hilfe [[Thrall]]s und der neuen [[Horde]] konnte er sein Volk schützen. Als Gegenleistung hat dieser edle Krieger dem jungen Kriegsherrn die Existenz des Orakels von [[Kalimdor]] und dessen Heiligtum auf der Spitze des [[Steinkrallengebirge]]s enthüllt.\r\n===Zitate:===\r\n\"Höre auf die Geister, junger Grunzer. Denn nur von ihnen erfährt der wahre Held seine Berufung.\"",},
			["Camp Aparaje"] = { content = "Der [[Tauren der Grimmtotem|Grimmtotemklan]] hat Camp Aparaje, ein [[Tauren]]dorf überfallen und fast alle getötet. Kaya, die Tochter von Makaba Flachhuf, hatte man nach dem brutalen Angriff schon verloren geglaubt. Nun ist sie eine Gefangene des [[Tauren der Grimmtotem|Grimmtotem-Stammes]].",},
			["Camp E'thok"] = { content = "Camp E'thok ist ein Lager der [[Zentauren]] in [[Tausend Nadeln]]. Eine große [[Zentauren]]streitmacht aus dem Camp E'thok hat eine Nachschubkarawane der [[Tauren]] überfallen und alle Mitglieder der Karawane sind verloren, ebenso die Vorräte. Dies war ein beispiellos dreister Angriff der [[Zentauren]], aber wohl nicht der letzte.",},
			["Camp Mojache"] = { content = "Camp Mojache ist der Posten der [[Horde]] in [[Feralas]]. Die [[Gnoll]]angriffe auf das Lager wurden in letzter Zeit heftiger und der Plan von [[Hadoken Flinkschreiter]] besteht nun darin, verschiedene Anführer der [[Gnolle]] in schneller Folge auszuschalten. Wenn sie einen solch schnellen und präzisen Schlag gegen sie erzielen können, würde es in den Rängen der [[Gnolle]] zu Chaos führen. \r\n==Personen==\r\n* '''Hadoken Flinkschreiter''' - Hadoken Flinkschreiter führt den Krieg gegen die [[Gnolle der Waldpfoten]] und sucht ihre Schlachtpläne, die irgendwo in den [[Gnoll]]-Lagern südlich vom Camp Mojache liegen. \r\n* '''Hexendoktor Uzer'I''' - [[Hexendoktor]] Uzer'I hat [[Neeru Feuerklinge]] in [[Orgrimmar]] im Tausch für Kräuter ein Schrumpfkopf versprochen. Es ist der Kopf eines armen Zwergs, der ihm im Wald über den Weg gelaufen ist. Uzer'I sucht ebenso verschiedene [[Muisek]]s von [[Feendrachen]], [[Wildekin]], [[Hippogryphen]], [[Treants]] und [[Bergriesen]]. Er will die Essenzen dieser Kreaturen einfangen, damit auch die [[Horde]] von ihrer Geisteskraft profitieren kann. Er benötigt obendrein bestimmte natürliche Materialien, um sein Vorhaben zu vervollständigen. Es ist ein äußerst komplizierter Vorgang, die Waffen mit dem Muisek zu erfüllen. Er hat von einem Ort gehört, der tief unter der Oberfläche der Erde liegt - dorthin verbannt durch größere Mächte, als er jemals gesehen hat - Der [[Versunkener Tempel|Versunkene Tempel]]. Und genau diese Macht will er erschließen.\r\n* '''Jangdor Flinkschreiter''' - Jangdor Flinkschreiter ist stolz auf seine Lederarbeiten und er glaubt, das sieht man ihnen an. Qualität sollte niemals zweitrangig sein. Auf seiner jüngsten Suche nach hochwertigem Material hat er dicke Yetibälge entdeckt.\r\n* '''Korrin''' - Korrin ist die Lebensgefährtin von [[Krueg Schädelspalter]] und Sie liebt neue Kleider.\r\n* '''Krueg Schädelspalter''' - Krueg Schädelspalter ist mit den Gefährten auf einer Mission für die Meister aus [[Orgrimmar]] hinunter nach [[Feralas]] gereist. Er hat vor, seiner Lebensgefährtin einen neuen Umhang zu fertigen, der mit den hauchzarten Flügeln von [[Feendrachen]] geschmückt ist. \r\n* '''Orwin Gizzmick''' - Orwin Gizzmick ist gerade erst in [[Feralas]] angekommen und sucht den [[Gordunnikobalt]] der [[Oger der Gordunni]].\r\n* '''Rok Orhan''' - Rok Orhan ist eine bekannte Orc Kriegerin und kümmert sich um die [[Oger]] von [[Feralas]]. Die Kugel eines Magierlords der Oger enthält große Macht und wird ihr dabei helfen, mehr über die Zeremonie und die Magie, die die [[Oger der Gordunni]] beherrschen, herauszufinden. Doch sie kann nicht sagen, über welche Fähigkeiten diese Kugel verfügt, also läßt sie die [[Gordunnikugel]] zu [[Uthel'nay]] in die [[Dunkeldornenlodge]] in [[Orgrimmar]] bringen. \r\n* '''Talo Dornhuf''' - Talo Dornhuf ist ein [[Tauren]]ältester und eine Berühmtheit im Camp Mojache. Zu seiner Zeit war er ein erfahrener Jäger und es gab keine Kreatur, die er fürchtete. Als Jäger strebt er danach, die Stärken nachzuahmen, die er bei den Gegnern sieht. Man kann den Kampf zu seinen Gunsten wenden, indem man einfach seinen Feind gut kennt. Doch dann wendete sich sein Glück: Er war draußen im Wald, um nach einem heftigen Kampf seine Klinge zu schärfen, als er in einen Hinterhalt geriet. [[Harpyien der Nordschwingen]] umzingelten ihn, und er schaffte es kaum, sich in Sicherheit zu bringen. Selbst heute noch kann er das Echo ihrer Schreie vernehmen. Danach war er nicht mehr derselbe. Aber der Hass kocht in dem Inneren - er will Rache, auch noch nach all diesen Jahren. Er will das dunkle Herz ihrer Anführerin [[Edana Hasskralle]].",},
			["Camp Narache"] = { content = "Camp Narache auf der [[Hochwolkenebene]] ist der Startpunkt der [[Tauren]] in [[Mulgore]] und wird von [[Häuptling Falkenwind]] geführt. Die [[Tauren]] hier haben mit einigen Problemen zu kämpfen, denn ihre Fleischvorräte gehen zur Neige und sie brauchen neue Federn, um Kleidung für ihre Kinder herzustellen. Das Fleisch jagen sie von den [[Ebenenschreiter]]n und Kampfebern der [[Stacheleber]] in der [[Hochwolkenebene]]. Für die Reparatur ihrer Zelte verwenden sie das Leder und die Pelze, der in der Nähe herumwandernden [[Ebenenschreiter]] und [[Bergpuma]]s.\r\n==Personen==\r\n* '''Gart Nebelläufer''' - Gart Nebelläufer ist der [[Druiden]]lehrer.\r\n* '''Großmutter Falkenwind''' - Großmutter Falkenwind steht beim Brunnen südöstlich vom Camp. Sie ist die Mutter von [[Häuptling Falkenwind]] und ist morgens fortgegangen, um Wasser zu holen. Doch das ist jetzt schon eine Weile her. Sie hat in ihrem Leben so viele Pfade beschritten und ihren alten Beinen mangelt es nun an der Energie, die sie einst hatten. Sie kann aber immer noch ihre Pflichten innerhalb des Stammes erfüllen, nur manchmal braucht eine alte Frau eben nur etwas länger dafür und so hat sie die bescheidene Bitte, ihr zu helfen, eine Wasserkanne vom Wasserbrunnen zu holen und sie anschließend zu Häuptling Falkenwind zu bringen.\r\n* '''Grull Falkenwind''' - Grull Falkenwind ist der Sohn von [[Häuptling Falkenwind]] und kümmert sich um den Nachschub an Fleisch und anderen benötigten Dingen, wie Ebenenschreiterfedern oder Bergpumapelze. Auch für Kampfeberschnauzen und Kampfeberflanken hat er Verwendung.\r\n* '''Häuptling Falkenwind''' - Häuptling Falkenwind kümmert sich um die Bedrohung durch die [[Stacheleber der Borstennacken]]. Nachdem er die Angriffspläne der [[Stacheleber der Borstennacken|Borstennacken]] sorgfältig studiert hat, erkennt er, dass es die geheimen Pläne des Kriegshäuptlings der Stacheleber für eine ausgedehnte Belagerung des Camp Narache sind. Er schickt die jungen [[Tauren]] ebenfalls auf den Weg der [[Riten der Erdenmutter]] zu [[Seher Grauzunge]].\r\n* '''Seher Grauzunge''' - Seher Grauzunge lebt in den Hügeln direkt südlich von Camp Narache und nimmt die erste Prüfung der [[Riten der Erdenmutter]] ab.\r\n* '''Seherin Rabenfeder''' - Seherin Rabenfeder gehört zu den Ältesten im Lager und unterrichtet junge Tauren über die [[Erdenmutter]], so dass sie niemals die Geheimnisse vergessen, die die Göttin mit ihnen teilt.\r\n* '''Vorn Himmelsdeuter'''",},
			["Camp Taurajo"] = { content = "Camp Taurajo ist ein Stützpunkt der [[Horde]] im südlichen [[Brachland]], der von den [[Tauren]] bewohnt wird.\r\n==Personen==\r\n* '''Doan Karhan''' - Doan Karhan ist ein [[Menschen Hexenmeister]], der zusammen mit [[Takar der Seher|Takar dem Seher]] in der Nähe von Taurajo ein kleines Lager aufgeschlagen hat. Er hat sein Leben dem Studium der Kugeln der [[Brennende Legion|Brennenden Legion]] und ihrer Neugestaltung gewidmet und kann aufgrund seines Wissens die [[Kugel von Soran'ruk]] für angehende [[Hexenmeister]] wieder zusammenfügen.\r\n* '''Jorn Himmelsdeuter''' ist ein [[Tauren Jäger]] und prüft angehende [[Jäger]] in ihren Fähigkeiten [[Ishamuhale]], [[Donnerechsen]], [[Donnerfalken]], [[Lakota'mani]], [[Owatanka]] und [[Washte Pawne]] zu jagen.\r\n* '''Kirge Sternhorn''' ist ein Tauren Seher.\r\n* '''Quetschzahn''' - Quetschzahn ist ein gefangener [[Stacheleber der Klingenmähnen]] in einem Käfig neben dem Windreiter und wenn man ihm viele [[Blutsplitter]] bringt, wird er Abenteurer als Belohnung mit Stachelebermagie segnen - der Magie von [[Agamaggan]]. Da die [[Stacheleber]]stämme im Krieg sind, möchte Quetschzahn, dass man ihm und dem [[Stacheleber der Klingenmähnen|Klingenmähnenstamm]] hilft, indem man die [[Stacheleber der Borstennacken]] schwächt. So wird man herausfinden können, wer [[Thork]] im [[Wegekreuz]] und der [[Horde]] wirklich solche Angst bereitet. Man soll für ihn die spirituellen Anführer der [[Stacheleber der Borstennacken]] im Norden angreifen und schwächen, so dass die [[Stacheleber der Klingenmähnen]] sie besiegen und das [[Brachland]] beherrschen können. Außerdem will er, dass man die Anführer [[Nak]], [[Kuz]] und [[Lok Orcfluch]] tötet. Loks Kopf soll dann zu [[Thork]] am [[Wegekreuz]] gebracht werden, denn er sollte ohne Worte wissen, was seinem Stamm zugestoßen ist - nicht dass [[Thork]] denken würde, Quetschzahn hätte bei solchen Dingen geholfen. \r\n* '''Takar der Seher''' - Takar der Seher ist ein [[Menschen Hexenmeister]], den man zusammen mit [[Doan Karhan]] nahe dem Camp Taurajo findet.\r\n* '''Tatternack Stahlformer''' - Tatternack Stahlformer ist ein [[Schmied]] und glaubt, er könnte aus dem [[Bluterz]] der [[Stacheleber]], die sich auf der anderen Seite des ausgetrockneten Flussbetts befinden, eine neue Legierung herstellen, wenn er genug davon hätte. Er hätte außerdem gern ein paar ausgewählte Waffen der [[Stacheleber der Klingenhauer]], um etwas über ihre Techniken zu erfahren, so möglich, denn der Kriegshäuptling ist mit Tatternacks bisherigen Leistungen zufrieden und bittet ihn nun, mit neuer Entschlossenheit fortzufahren und seine Ehre gebietet, dass er den Kriegshäuptling wissen läßt, was er alles vollbracht hat. Jüngst kamen auch Reisende aus dem Süden von einem Ort namens [[Tausend Nadeln]] zu ihm. Dort töteten sie einen der [[Kobolde der Bruchschnauzen]], der eine außergewöhnliche Erzprobe bei sich hatte, wollten sie aber nicht verkaufen, doch Tatternack möchte eine Probe dieses Erzes untersuchen.",},
			["Carra Sprigglespruxx"] = { content = "Carra ist die Cousine von [[Hildegard]] und liiert mit dem Menschenpaladin [[Wilfried Lathor]]. Sie ist eine geübte Arenakämpferin und Meisterin der goblinschen Ingenieurskunst.",},
			["Cenarius"] = { content = "Als Sohn von [[Elune]], der Göttin des Mondes, und dem [[Halbgott]] [[Malorne]] erbte Cenarius eine innige Verbindung zu der Welt [[Azeroth]] und ihren Lebewesen. Bei den [[Tauren]] gibt es eine Sage, die angeblich die Geschichte der Empfängnis von Cenarius erzählt.\r\nAls die Geburt von Cenarius ihre Wellen durch den [[Smaragdgrünen Traum]] sandte, interessierte sich [[Ysera]] sofort für ihn. Sie leitete ihn in den Traum, lehrte ihn viele seiner Geheimnisse und wurde im Laufe der Zeit seine Ziehmutter, und auf Grund ihres liebevollen Verständnisses hielten sie viele der älteren [[:kategorie:Volk|Völker]] von [[Azeroth]] für Mutter und Sohn.\r\nEr empfand eine tiefe Liebe zu den üppigen Wäldern in [[Ysera]]s Traumreich. Oft sah sie ihn auf den unendlichen Traumpfaden wandeln, wo er über die Welt [[Azeroth]] und ihre Wesen wachte oder einfach nur auf all das wartete, was noch aus ihnen werden konnte.\r\n===Die Nachtelfen===\r\nAls die [[Nachtelfen]] sich rund um den [[Brunnen der Ewigkeit]] entwickelten, brachte ihre Neugier sie dazu, einige mächtige Wesen kennenzulernen und sich mit ihnen anzufreunden, darunter auch Cenarius. Der [[Halbgott]] mochte die [[Nachtelfen]], und er verbrachte einen Großteil seiner Zeit damit, sie sein Wissen über die Welt der Natur zu lehren. Unter seiner Anleitung entwickelten die [[Nachtelfen]] eine starke Empathie zu den lebendigen Wäldern des alten [[Kalimdor]] und erfreuten sich an der harmonischen Balance der Natur.\r\nIm Laufe der Zeit aber fühlten sich die [[Nachtelfen]] immer stärker von den kosmischen Energien des Brunnens angezogen. Zudem führte das schnelle Wachstum der Nachtelfen-Zivilisation unweigerlich zum Bau neuer Gebäude und Straßen. Große Waldflächen verschwanden. Ruhiger Forst verwandelte sich in ausufernde Städte, und gewaltige Bäume wurden verdreht und verbogen, bis ihre Form den [[Nachtelfen]] als Wohnung dienen konnte. Die [[Nachtelfen]] verloren ihren Bezug zur Natur.\r\nDie Zahl der [[Nachtelfen]], die von dem Halbgott lernen wollten, nahm ab, und Cenarius erkannte voller Trauer, dass all seine Arbeit umsonst gewesen war. Widerstrebend verließ er das Land der [[Nachtelfen]]. Er entschloss sich, ihre Entscheidung zu respektieren, so sehr sie ihn auch betrübte. Von diesem Tag an zog sich Cenarius in die Wildnis zurück und vermied jeden Kontakt zu den intelligenten Völkern, bis diese schließlich an seiner Existenz zu zweifeln begannen.\r\n===Der Erste der Druiden===\r\nJahrtausende nachdem das Interesse der [[Nachtelfen]] an arkaner Magie zu der großen Teilung führte, fand [[Malfurion|Malfurion Sturmgrimm]] mehrere Legenden, die sich um den geheimnisvollen Cenarius rankten. [[Malfurion]] hatte die Natur schon immer zutiefst verehrt, obwohl die [[Nachtelfen]] als Volk längst das Interesse an solchen Sachen verloren hatten. Er berichtete seinem Zwillingsbruder [[Illidan]] von diesen Legenden, außerdem ihrer gemeinsamen Freundin [[Tyrande|Tyrande Wisperwind]]. Die drei [[Nachtelfen]] fanden, es sei ein aufregendes Abenteuer, nach Cenarius zu suchen, auch wenn sie in Wirklichkeit nicht mehr an den Halbgott glaubten als der Rest ihres Volkes.\r\nEs dauerte nicht lange, bis vereinzelte Pflanzen und Tiere auf [[Azeroth]] Cenarius von diesen drei Nachtelfen berichteten. Cenarius war überrascht und wurde neugierig. Er fand diese [[Nachtelfen]] und schaute in ihre Herzen. Er entdeckte ein großes Potenzial in [[Malfurion]], und es war diese Entdeckung, die seinen Entschluss besiegelte.\r\nDas lachende Trio war zunächst geschockt, als Cenarius aus einem schattigen Dickicht hervortrat. Er stellte sich vor und bot ihnen an, sie in der [[Druiden]]kunst zu unterrichten. Begierig nahmen sie an. [[Malfurion]] erwies sich als begabter Schüler, der schnell lernte. Sein Bruder jedoch war ungeschickt und verlor schnell die Geduld. Tyrande war bereits Novizin in der Schwesternschaft von [[Elune]] und hatte sich also bereits ihrer Göttin gewidmet. Cenarius wusste, dass allein [[Malfurion]] die Ausbildung zum [[Druiden]] beenden würde.\r\n===Die Invasion der Brennenden Legion===\r\n[[Malfurion]] machte gute Fortschritte bei seinen Studien, doch dann wurde er von einer verstörenden Vision heimgesucht. Er sah hilflos zu, wie die [[Hochgeborene]]n des Palastes die Magie des Brunnens der Ewigkeit immer stärker missbrauchten. Die Vision erfüllte ihn mit der Gewissheit, dass Königin Azshara und ihre obersten Magier eine Katastrophe auslösen würden, wenn sie niemand aufhielte. Der Nachtelf teilte seine Besorgnis Cenarius mit, der sich ebenfalls große Sorgen machte.\r\nTrotzdem merkten die [[Nachtelfen]] zu spät, was vor sich ging. Dämonen strömten aus dem Königspalast und begannen, jeden abzuschlachten, der ihnen in den Weg kam. Der Krieg der Urtume hatte begonnen.\r\nWährend die Krise sich zuspitze brachte Cenarius [[Malfurion]] alles bei, was er konnte, und dann suchte er die anderen Halbgötter von [[Azeroth]] auf. Sie waren es nicht gewöhnt, zusammenzuarbeiten, und so kostete es Cenarius eine Menge Überredungskraft, sie auf ein gemeinsames Vorgehen einzuschwören. Sie begaben sich zur Front und sahen, dass der Krieg schon in vollem Gange war.\r\nSchnell überblickte Cenarius die Situation und führte die anderen Halbgötter zum Anführer der [[Nachtelfen]]armee, Captain [[Jarod Schattensang]]. Der verblüffte Captain nahm die Unterstützung der Halbgötter dankend an, und das Schlachtenglück schien sich zu wenden.\r\n===Verluste===\r\nAls Reaktion auf diese neue Bedrohung konzentrierten die dämonischen Armeen ihre Angriffe auf die Halbgötter, die schon bald überrannt wurden. Cenarius wurde schwer verwundet und war völlig umzingelt, als Malorne plötzlich vorpreschte und mit mächtigen Stößen seines gewaltigen Geweihs die Gegner seines Sohnes zurücktrieb.\r\nDie Nachtelfen reagierten schnell und zogen den bewusstlosen Cenarius aus der Gefahrenzone. Malorne hielt die Dämonen eine Zeitlang auf Distanz. Dann kam Archimonde an die Front, forderte den riesigen Hirschen zum Zweikampf heraus und brach schließlich Malorne das Genick. Malfurion war wütend und betrübt; er beschwor Wurzeln aus dem Boden herbei und griff damit den Dämonenlord an. Als die Pflanzen den Dämonen immer fester in ihrem Würgegriff packten, war Archimonde gezwungen zu fliehen und sich in Sicherheit zu teleportieren.\r\nYsera war traurig, als sie von Malornes Tod erfuhr. Ihre Drachen halfen Cenarius vorsichtig, in den Smaragdgrünen Traum zu wechseln. Dort konnten die grünen Drachen seine Verletzungen behandeln. Trotz seiner Sorgen und der Nachwirkungen seiner Verletzungen verließ Cenarius den Traum schon wieder kurz nach der Große Teilung, denn er konnte spüren, wie das Land nach Heilung schrie.\r\nZu seinem Entsetzen entdeckte er, dass [[Illidan]] Sturmgrimm einen zweiten [[Brunnen der Ewigkeit]] erschaffen hatte. [[Jarod Schattensang]] überließ es [[Malfurion]], [[Illidan]] zu bestrafen. Malfurion hielt es für eine unverzeihliche Dummheit, [[Illidan]] seine Freiheit zu lassen, so dass er seinen rücksichtslosen Machthunger weiter ausleben könnte. Daher sperrte [[Malfurion]] mit Cenarius' Hilfe seinen Bruder [[Illidan]] in einem riesigen unterirdischen Hügelgefängnis ein, wo er in Ketten und hilflos bis ans Ende der Zeit gefangen bleiben sollte.\r\n===Die Abspaltung der [[Nachtelfen]]===\r\n[[Tyrande]] Wisperwind, inzwischen Hohepriesterin der [[Elune]], setzte durchgreifende Veränderungen in der Nachtelfengesellschaft durch. Sie organisierte eine neue, nur aus Frauen bestehende Armee, die [[Schildwache]]n, und ordnete an, dass sie von der Schwesternschaft von Elune geleitet werden sollte. Adel und Zauberei wurden als Relikte einer dekadenten Vergangenheit angesehen, deren man sich schämte.\r\nDoch eine Gruppe [[Hochgeborene]]r unter [[Dath'Remar Sonnenwanderer]] weigerte sich, den Gebrauch arkaner Magie aufzugeben. Nachdem sie die Angelegenheit gründlich ausdiskutiert hatten, fassten [[Tyrande]] und [[Malfurion]] den schweren Entschluss, ihre unbelehrbaren Verwandten ins Exil zu schicken. Nachdem die Hochgeborenen sie verlassen hatten, zogen sich die verbleibenden Nachtelfen immer mehr vom Rest der Welt zurück. Eine Nebelbank senkte sich über ihren ganzen Kontinent herab und verbarg ihn vor den Augen vorbeifahrender Seeleute.\r\nWährenddessen blieb Cenarius auf der nahegelegenen Mondlichtung am Berg Hyjal zurück. Seine Söhne, die Wächter der Lichtung, wachten über die Nachtelfen und halfen den Schildwachen regelmäßig, den Frieden im Land zu erhalten. Selbst die scheuen Töchter des Cenarius, die Dryaden, ließen sich immer öfter im Freien sehen.\r\n===Neue Völker kommen nach Kalimdor===\r\nDie Zeit verging, und ein neues Volk kam nach Azeroth: Die Orcs, die ursprünglich vom Planeten Draenor stammten. Unter dem Einfluss der Dämonen hatten sich die Orcs von einer friedlichen Schamanengesellschaft in die blutrünstige Horde verwandelt. Sie führten Krieg gegen die Menschen der Östlichen Königreiche und töteten im Ersten und Zweiten Krieg zahllose Lebewesen. Cenarius und die Nachtelfen blieben in ihrem Exil, denn sie wussten nichts von irgendwelchen Geschehnissen außerhalb Kalimdors.\r\nDer Zweite Krieg lief schlecht für die Orcs, und die Horde wurde zerschlagen. Kurz vor dem Dritten Krieg etablierte sich ein neuer Kriegshäuptling: Thrall. Er reformierte die Horde und führte sein Volk über das Meer nach Kalimdor, wo es eine neue Heimat fand. Diese neue Horde hatte kein Interesse an weiteren Kriegen. Die Orcs wollten nur die Länder der Menschen verlassen und sich ein neues Zuhause aufbauen.\r\n===Der Tod eines Halbgotts===\r\nDie Orcs wurden auf Kalimdor nicht mit offenen Armen empfangen. Die Nachtelfen schickten sogleich eine Reihe Kundschafter aus, und diese brachten erschreckende Geschichten mit zurück über die Grausamkeiten der Orcs im Ersten und Zweiten Krieg. In der Zwischenzeit fällten die Orcs viele Bäume in Kalimdor, in der deutlichen Absicht, dort eine Siedlung zu gründen. Cenarius hingegen war sich sicher, dass die Orcs wieder zu ihrer Kriegslust zurückgefunden hatten. Er führte eine Gruppe von [[Nachtelfen]] und [[Treants]] gegen die Hauptmacht der orcischen Eindringlinge.\r\nDie neugeborene Horde hätte mit Sicherheit dort ihr Ende gefunden, wären nicht kurz zuvor mehrere Agenten der Brennenden Legion auf Azeroth eingetroffen. Die Legion hatte den Heldenmut und die Macht, die Cenarius im Krieg der Urtume zeigte, nicht vergessen und war entschlossen, ihn zu vernichten. Auf Vorschlag des Schreckenslords Tichondrius vergoss der Grubenlord Mannoroth sein Blut in einen Teich. Schon bald entdeckten die Hexendoktoren der Horde diese Verderbnis.\r\nAngeführt von [[Grom Höllschrei]] tranken die [[Orcs]] von den verderbten Wassern des Teiches und genossen die Rückkehr ihrer dämonischen Kräfte. Übermannt von übernatürlichem Hass und Zorn schlugen Grom und seine Krieger gegen Cenarius und seine Verbündeten zurück. Schließlich gelang es den [[Orcs]], den Halbgott zu töten. Die [[Nachtelfen]] und viele andere Wesen, darunter auch [[Ysera]], betrauern den tragischen Tod von Cenarius bis auf den heutigen Tag.\r\n'''Quelle:''' wow-europe.com",},
			["Cenariusdickicht"] = { content = "== Allgemeines==\r\nDer Cenariusdickicht war ein Posten der [[Expedition des Cenarius]] in den [[Wälder von Terokkar|Wäldern von Terokkar]]. Doch man hat schon eine Weile nichts mehr von den Druiden des Dickichts gehört, was sehr merkwürdig ist, da sie sich normalerweise alle paar Tage beim Posten in den [[Zangarmarschen]] melden. \r\nErdbinder Tavgren von der [[Expedition des Cenarius]] war ein paar Tage unterwegs, um die Knochenwüste im Süden zu untersuchen. Als er zurückkam, fand er die Leichen der [[Druiden]] überall im Dickicht. Eine furchtbare Tragödie musste geschehen sein und was auch immer es war, es passierte schnell und fühlt sich unnatürlich an. \r\n===Bösartige Motten===\r\nDer Nachtelfische [[Druide]] Baumlas ist durch die Geschehnisse verrückt geworden, aber er ist harmlos. Er traut sich nicht, auf die Spitze des Turms zu gehen, um mit der Terrormotte Naphthal'ar zu sprechen, von der er sich beobachtet fühlt. Wo einst eine Vielfalt von Arten herrschte, sind jetzt nur noch die Teromotten übrig. Und während sie früher friedlich waren, sind sie jetzt sehr aufgeregt und greifen alles an, was ihnen zu nahe kommt. Die Proben der bösartigen Teromotten enthalten etwas, das sich wie reines Mana anfühlt. Wie es scheint hinterließ das, was all die Tode verursacht hat, ein starkes Energiefeld. Aber aus irgendeinem Grund hat es die Teromotten nicht umgebracht, sondern nur aufgewühlt. Es scheint, als wäre diese merkwürdige Energie ein Nebenprodukt dessen, was das Dickicht angegriffen hat.\r\n===Die Manabombe===\r\nNeben einem toten Zerschlagenen liegen die Überreste einer Manabombe, wie sie von den [[Blutelfen]] im Posten der Feuerschwingen gebaut wird. Erdbinder Tavgren ist sich sicher, dass sie all die Tode verursacht und die Teromotten des Cenarius Dickichts verändert hat. Hinter dem Angriff steckt niemand anderes als die [[Blutelfen]], die [[Kael'thas]] Ruf gefolgt sind.\r\nEmpoor ist ein Händler der [[Zerschlagene]]n, der mit allen Arten von Waren und Informationen handelt. Er reist auf der Straße zwischen Tuurem und [[Shattrath]] hin und her. Er wurde vor etwa einem Monat gebeten, ein paar Kästen mit merkwürdigen und fremdartigen Bauteilen für eine Manabombe bei dem Astralen Windhändler Lathrai in [[Shattrath]] abzuholen. Sie wurden nach Tuurem geliefert und [[Blutelfen]] brachten die Kästen mit den Bombenteilen von dort zum Posten der Feuerschwingen.",},
			["Charaktere der Allianz"] = { content = "#REDIRECT [[:Kategorie:Charakter Allianz]]", redirect = ":Kategorie:Charakter Allianz",},
			["Charaktere der Horde"] = { content = "#REDIRECT [[:Kategorie:Charakter Horde]]", redirect = ":Kategorie:Charakter Horde",},
			["Charlga Klingenflanke"] = { content = "Die Ältestengreisin '''Charlga Klingenflanke''' kontrolliert den größten Teil vom [[Kral der Klingenhauer]] und regiert dort ihren Stamm der [[Stacheleber der Klingenhauer]]. Unter ihrer Führung greifen die schamanistischen Stacheleber regelmäßig sowohl die feindlichen Stämme als auch nahegelegene Siedlungen der [[Orcs]] und [[Tauren]] im Brachland an. Charlga zieht eine abscheuliche Armee zusammen und die Geißel möchte, dass Charlga ihnen die Freiheit zugesteht, in dem Gebiet aktiv zu werden. Sie haben große Macht und sind gewillt, sie mit jenen zu teilen, die weise genug sind, sich ihnen anzuschließen.",},
			["Chefingenieur Bilgenritzel"] = { content = "Chefingenieur Bilgenritzel von der [[Gadgetzan Water Company]] in [[Gadgetzan]] ist auch gleichzeitig der Sicherheitschef im [[Dampfdruckpier]]. Er muss aus diesem Grunde gegen die [[Wüstenläufernomaden]] vorgehen und sucht nebenbei noch die Wasserbeutel der Wüstenläufer, da er etwas zu Trinken möchte. Für mehrere dieser Wasserbeutel stellt er auf Anfrage auch eine [[Kraftquelle Modell 4711-FTZ]] zur Verfügung, denn die Zeiten hier sind schwer und Kraftquellen wachsen nicht auf Bäumen.",},
			["Chemiker Brenner"] = { content = "'''Chemiker Brenner''' befindet sich im Apothekarium von [[Unterstadt]]. Er und sein Bruder haben sich der Fürstin [[Sylvanas Windläufer]] verschrieben. Sie war ihr Licht in finstersten Zeiten und die beiden Brüder opfern sich Tag für Tag, damit ihre Art das ihr zugedachte Schicksal überwinden kann. Sie werden nicht schwach bleiben. Und sie werden sich nehmen, was ihnen gehört. Den Schmerz, der ihnen zugefügt wurde, werden sie zehnfach vergelten. Und sie werden es mit einem Lächeln tun. Wenn man ihnen helfen möchte, sollte man ihnen [[Brühschlammer]]proben aus dem [[Teufelswald]] und dem Krater von [[Un'Goro]] bringen, um dann mit der Testausrüstung überprüfen, welche der Proben am Verderbtesten bzw. reinsten sind. Brenner muss sich aber noch eingehender mit den Umweltbedingungen auseinander setzen, die diese Veränderungen in den Kreaturen auslösen. Also wird er seine Forschungen jetzt fortsetzen und einen verderbten Brühschlammer mit einem Urzeitbrühschlammer verschmelzen, um die Einflüsse ihres Lebensraumen zu vereinigen.",},
			["Cho'gall"] = { content = "Cho'gall war ein zweiköpfiger [[Oger]] und der erste und mächtigste Ogermagier. Er wurde zu einem der meist gefürchteten und respektierten Mitglieder der [[Horde]] während des Ersten und Zweiten Krieges und hatte unter [[Gul'dan]] selbst Magie studiert. Cho’gall führte die orkische Truppe beim ersten Angriff auf [[Sturmwind]]. Obwohl Cho’gall extrem mächtig war, war er ebenso gefährlich wahnsinnig. Cho’gall erschuf und führte seinen eigenen Klan bekannt als [[Schattenhammer Klan]]. Die Schattenhammer waren weniger ein Stamm, sondern mehr einer religiöser Kult und widmeten sich die Apokalypse zu bringen. \r\nCho’gall und die Schattenhammer folgten [[Gul'dan]] und dem [[Stormreaver Klan]], als der [[Hexenmeister]] ging, um das [[Grabmal des Sargeras]] zu entdecken. Obwohl er das Grabmal selbst nicht betrat, wurde Cho’gall später von den Streitkräften [[Orgrim Schicksalshammer]]s getötet, der geschickten worden war, um die verräterischen Klans zu zerstören, die den Krieg gegen die [[Allianz]] verlassen hatten. Irgendwie war der [[Schattenhammer Klan]] fähig, den Tod seines Meister zu überleben, und schafft es, nun unter dem Namen [[Schattenhammer Kult]], in der Umzingelung von [[Allianz]] und [[Horde]] fortzudauern.",},
			["Cho'war der Plünderer"] = { content = "'''Cho'war der Plünderer''' ist der [[Oger]], der die [[Gronn]] vertrieben hat, die über die Oger geherrscht hatten. Er ist mächtig und wohnt in der großen Höhle tief im [[Totschlägerhügel]] in den nordwestlichen Bergen von [[Nagrand]].",},
			["Chromaggus"] = { content = "'''Chromaggus''' ist ein [[Drakeoden]] des [[Chromatischer Drachenschwarm|chromatischen Drachenschwarms]], den man im [[Pechschwingenhort]] findet. Er ist der Schoßhund von [[Nefarius]] und befindet sich in einem Käfig oberhalb des Raumes, in dem zuvor [[Meisterelementarformer Krixix]] und die Wyrmwachen der [[Todeskrallen]] standen. \r\n==Taktik==\r\nDer Kampf gegen Chromaggus ist geprägt durch seine Atem-Arten, denen der Raid durch eine Sichtlinien-Taktik entgeht. Besonders wichtig ist außerdem das Entfernen der Brutgebrechen, die er an den Raid verteilt, und seiner Raserei. Sein Atem Zeitraffer erfordert eine besondere Taktik. Wird er aus seinem Käfig befreit, greift er sofort an. Der Raid hat sich vorher bereits wie folgt aufgestellt: In der Chromaggus’ Käfig nächstgelegenen Nische, nahe der Rampe nach oben, stellen sich die Fernkämpfer auf. Die nächste Nische bleibt frei, in der folgenden Nische stehen die Nahkämpfer. An der Rampe nach unten stehen die Maintank-Heiler und der Magier, der zum Entfluchen abgestellt wurde. Diese postieren sich so, dass sie nur den Maintank sehen, aber nicht in Chromaggus’ Sichtlinie stehen. Ab 20 % HP, wenn Chromaggus wütend wird, nutzen die Maintank-Heiler Stundenglassand, um ununterbrochen heilen zu können. (Quelle: \r\n==Fähigkeiten==\r\nChromaggus verfügt über folgende Fähigkeiten:\r\n* '''Brutgebrechen''' - Chromaggus verteilt 5 Brutgebrechen an alle Spieler des Raids. Dies sind verschiedene Debuffs, die 10 Minuten andauern und so schnell wie möglich entfernt werden müssen. \r\n** Brutgebrechen Blau - Zieht jede Sekunde 50 Mana ab, verringert das Zaubertempo um 50 % und die Bewegungsgeschwindigkeit um 70 %. Magieeffekt, kann von Paladinen und Priestern entfernt werden. \r\n** Brutgebrechen Bronze - Betäubt in regelmäßigen Abständen 4 Sekunden lang. Kann nur mit Stundenglassand entfernt werden.\r\n** Brutgebrechen Grün - Fügt alle 5 Sekunden 250 Schaden zu, verringert Heileffekte um 50 %. Gift, kann von Schamanen, Paladinen und Druiden entfernt werden. \r\n** Brutgebrechen Rot - Fügt alle 3 Sekunden 50 Schaden zu. Krankheit, kann von Schamanen, Priestern und Paladinen entfernt werden. \r\n** Brutgebrechen Schwarz - Erhöht den Feuerschaden um 100 %. Fluch, kann von Magiern und Druiden entfernt werden. Muss vor allem bei Verbrennen oder Fleisch entzünden schnellstmöglich entfernt werden. \r\n Ist ein Spieler mit allen 5 Brutgebrechen gleichzeitig belegt, verwandelt er sich in einen Drachen, was gewöhnlich einen Wipe zur Folge hat.\r\n* '''Atem''' - Alle 30 Sekunden wirkt Chromaggus einen Atem, von dem jeder in seinem Sichtfeld betroffen wird. Er verfügt über 5 Atem-Arten, von denen / Instanz-ID 2 zufällig ausgewählt werden\r\n** '''Ätzende Säure''' - DoT, der alle 3 Sekunden etwa 800 Naturschaden zufügt. Reduziert die Rüstung um bis zu 5000.\r\n** '''Fleisch entzünden''' - DoT, der alle 3 Sekunden rund 800 Feuerschaden zufügt und 60 Sekunden anhält.\r\n** '''Frostbeulen''' - 1400 Frostschaden, außerdem wird die Angriffsgeschwindigkeit um 80 % reduziert. Verbrennt rund 2000 Mana.\r\n** '''Verbrennen''' - Rund 4500 Feuerschaden.\r\n** '''Zeitraffer''' - Betroffene Ziele sind für 8 Sekunden bewegungsunfähig. Halbiert die HP. Reduziert die Aggro erheblich.\r\n* '''Schimmernde Haut''' - Regelmäßig wird Chromaggus für eine andere Zauberschule verwundbar. Der Schaden durch alle anderen Zauberschulen ist in dieser Zeit stark reduziert.\r\n* Raserei - Alle 15 Sekunden verfällt Chromaggus in Raserei. Dabei erhöht sich sein Angriffstempo um 100 %. Wie bei Flammenmaul ist es die Aufgabe der Jäger, Chromaggus mit dem Einlullenden Schuss aus der Raserei zu schießen. Da der Einlullende Schuss nur alle 30 Sekunden eingesetzt werden kann, müssen die Jäger eine Rotation absprechen.\r\n* Wütend - Sinkt Chromaggus’ HP unter 20% Gesundheit, wird er wütend Sein Angriffstempo steigt, er fügt mehr Schaden zu.",},
			["Chromatischer Drachenschwarm"] = { content = "[[Nefarian]], der Sohn von [[Todesschwinge]], ersann einen dunklen Plan, seinem Schwarm zu alter Stärke zurück zu helfen. Aus den wenigen Eiern der [[Schwarzer Drachenschwarm|Schwarzen Drachen]] und geraubten Eiern der [[Roter Drachenschwarm|Roten Drachen]] schuf Nefarian mit dunkler [[Magie]] entsetzliche Zwitterkreaturen, die schon verderbt zur Welt kamen. Die Resultate dieser widernatürlichen Vereinigung heißen '''chromatische Drachen'''. Nefarian schuf genügend, um sie zu einem neuen [[Drachen]]schwarm heran wachsen zu lassen, der nur ihm hörig war und die jüngeren Völker vernichten sollte.Ihre Schuppen sind violett, ändern jedoch je nach Lichteinfall die Farbe.Ebenfalls Mitglieder des Chromatischen Drachenschwarms sind die [[Drakeoden]].\r\n==Persönlichkeiten==\r\n* [[Brutwächter Dreschbringer]]\r\n* [[Chromaggus]]\r\n* [[Gyth]]",},
			["Chromatischer Mantel der Dämmerung"] = { content = "Der '''Chromatische Mantel der Dämmerung''' ist eine Verzauberung der [[Argentumdämmerung]]. Diese fügt einem Gegenstand, der sich an einem Schulterplatz befindet, dauerhaft 5 Punkte Widerstand gegen alle Magiearten hinzu. Man kann sie für 25 ''Ehrenmarken der Argentumdämmerung'' von Rüstmeisterin Miranda Knackschloss an der [[Kapelle des hoffnungsvollen Lichts]] in den [[Östlichen Pestländern]] erwerben. Dafür benöntigt man allerdings einen ehrfürchtigen Ruf bei der Argentumdämmerung''. \r\nNur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung, denn er ist der feinste ihrer Mäntel. Erst wenn die Taten eines Helden im Namen der Argentumdämmerung zu zahlreich sind, um sie noch aufzuzählen, wird sich Rüstmeisterin Miranda Knackschloss von einem dieser wertvollen chromatischen Mäntel trennen. Er schützt den Träger gleichzeitig gegen alle Formen der Magie.",},
			["Chromie"] = { content = "Chromie ist eine merkwürdige Gnomin mit sehr merkwürdigen Kräften im Gasthaus des zerstörten [[Andorhal]]s in den [[Westliche Pestländer|Westlichen Pestländern]].\r\nChromie heißt eigentlich Chronormu und ist ein [[Bronzener Drachenschwarm|Bronzedrache]], der sich nur als [[Gnom]]in verkleidet hat.\r\nMan sieht, dass der Raum in dem sie steht, anders ist als der Rest von [[Andorhal]]. Der [[Bronzener Drachenschwarm|Bronzene Drachenschwarm]] agiert auf verschiedene Weise und in vielen verschiedenen Zeitlinien und um den in [[Andorhal]] angerichteten Schaden zu beheben, handelt sie jetzt von einer anderen Zeitlinie aus, um sie nicht allzu sehr zu kontaminieren. Um diese Arbeit fortzusetzen, benötigt sie Zeitobjekte, die aus einer Zeit stammen, bevor die Seuche auftrat. Man findet sie in Schließkassetten in den Ruinen der Gebäude, die einst diese stolze Stadt waren.\r\nChromie hilft auch bei der [[Schlacht von Darroheim]] und läßt die Geister von [[Darroheim]] sich erheben. Um Joseph Rotpfads Seele zu retten, muss man zuerst seine Vergangenheit enthüllen und dabei kann Chromie durch die Wiederbeschafftung der [[Annalen von Darroheim]] dienlich sein, die sie um einige Seiten erweitert. Sie wird Abenteurer schließlich an der Schlacht von [[Darroheim]] teilnehmen lassen, um Joseph Rotpfad retten. Diese müssen dann dafür sorgen, dass die folgenden zwei Dinge eintreten: Davil muss den Tod von Horgus überleben und Rotpfad muss überleben, um erst verdorben und dann besiegt zu werden. Nachdem man den verderbten Rotpfad besiegt hat, wird seine Seele gerettet sein.",},
			["Chronalis"] = { content = "Chronalis ist ein [[Bronzener Drachenschwarm|Bronzener Drache]] in [[Tanaris]] in den [[Höhlen der Zeit]] und gehört zur Fraktion der [[Hüter der Zeit]]. Der Zeitverschieber oder Lord der Jahrhunderte, wie er auch genannt wird, ist ein bevorzugtes Kind von [[Nozdormu]], der die [[Höhlen der Zeit]] in der [[Tanaris]]wüste bewacht. Es sind derer drei, die die Höhlen der Zeit bewachen, aber nur einer, an dem der [[Schwarzer Drachenschwarm|schwarze Drachenschwarm]] interessiert ist: Chronalis.",},
			["Chronolord Deja"] = { content = "'''Chronolord Deja''' ist der erste Boss in den [[Höhlen der Zeit: Der Schwarze Morast]] in [[Tanaris]]. Er erscheint im sechsten Tor und zählt zu den [[Drakonid]]en des [[Ewiger Drachenschwarm|Ewigen Drachenschwarms]]. \r\n==Fähigkeiten==\r\nChronolord Deja hat vor allem Arkane Fähigkeiten. Dazu gehören:\r\n* '''Anziehung''' \r\n* '''Arkane Entladung''' - Arkane Entladung ist ein Kettenblitz und verursacht bei allen Gegnern in einem Bereich um den Zaubernden 2313 bis 2687 Arkanschaden, im heroischen Modus 3700 bis 4300 Arkanschaden. \r\n* '''Arkanschlag''' - Der Arkanschlag überzieht einen Feind mit Arkanmagie, fügt 3063 bis 3937 Arkanschaden zu und stößt den Feind zurück. Im heroischen Modus fügt diese Fähigkeit 4500 bis 5500 Arkanschaden zu.\r\n* '''Zeitraffer''' - Zeitraffer ist ein Stärkungszauber, der die Zeit zwischen Angriffen eines Gegners um 60% erhöht und sein Bewegungstempo um 60% verlangsamt. Hält 10 Sek. lang an.",},
			["Chu'kay"] = { content = "'''Interpretationsquelle''': [[Anduri Stamm]] \r\n'''Ideale:''' List, Täuschung, Narretei \r\nChu'kay ist ein Schalk. Nichts liebt er mehr als andere hinters Licht zu führen und sich auf deren Kosten zu amüsieren. Er spiegelt wie kein anderer die Durchtriebenheit und gleichzeitige Fröhlichkeit der Dschungeltrolle wider. \r\nDer Kult des grinsenden Hundes ist erstaunlich lebendig geblieben, viele Statuen zeugen von seiner Verehrung. Auch findet sich häufig das Grinsen, also die Zähne, auf Tempelreliefs eingeritzt, meistens versteckt in einer Ecke, wo es nicht sofort auffällt. An Bäumen oder Hütten im Dschungel sieht man manchmal ein einzelnes Gebiss hängen, auch das sind Zeichen des Chu'kay-Kultes. \r\nDie offensichtliche Fröhlichkeit dieses Gottes sollte man keinesfalls mit Gutmütigkeit verwechseln. Der Grinsende Hund ist hinterhältig und gemein. Er amüsiert sich köstlich über das Leid derer, die er in seine Fallen gelockt hat. Nicht jeder seiner Streiche ist tödlich, doch diejenigen, denen besonders durchtriebene und schädliche Betrügereien gelingen, werden vom Grinsenden Hund zu Hohepriestern erwählt. \r\nDie Legende berichtet von einem Trollwelpen der Skullsplitter namens Van'djee. Er war etwas schwächlicher als seine Altersgenossen und wurde ständig von ihnen deswegen schikaniert und schlimm verprügelt. Doch eines Tages dachte sich Van'djee eine List aus, er wollte seine Stammesgenossen in eine Falle locken und ihnen heimzahlen, was sie ihm Tag für Tag angetan hatten. \r\nAm Abend ging er zu den Trollen, die ihn immer schlugen und begann vor ihnen zu tanzen und sie mit wildem Gekreische zu verhöhnen. Als diese sich auf ihn stürzen wollten, rannte er so schnell er konnte aus dem Dorf in den Dschungel, während ihm seine Häscher johlend folgten. Als sie weit genug vom Dorf entfernt waren, verließ Van'djee den Weg und rannte querfeldein zu einer betimmten Lichtung. Seine Verfolger waren so angeheizt, dass sie nicht darauf achteten, wohin sie ihm folgten. \r\nAls sie an der Lichtung ankamen, war von Van'djee nichts mehr zu sehen. Sie wollten sich enttäuscht zurückwenden, doch dann hörten sie sein wahnsinniges Lachen durch die Bäume hallen. Er kreischte lautstark wie ein Affe und tatsächlich stürzte plötzlich eine Schar von Blutaffen aus den Baumwipfeln auf die Trolle herab. Jeder Einzelne von ihnen wurde grausam zerfleischt. Niemand gelang die Flucht. Blutaffen sind klein, doch ihre messerscharfen Zähne sind gnadenlos. Nur Van'djee rührten sie nicht an. \r\nAls der Welpe über den kaum noch auszumachenden Überresten seiner Stammesgenossen stand, grinste er breit, seine Augen wahren erfüllt von Wahnsinn. Da erschien ihm das Grinsen von Chu'kay direkt vor seinen Augen und der Gott machte ihm ein heiliges Geschenk. Den übrigen seines Stammes erzählte er nichts, doch niemand der anderen Trolle wagte es je wieder, Van'djee zu verhöhnen, denn sie spürten, dass er göttlichen Segen in sich trug.\r\n--------\r\n\"Chu'kay entspringt dem Kaschtazuu, einer der UrHoodoo formen und begann seine Existenz als Fetisch der Verfluchung, durch die rapide ansteigende Macht seiner Kräfte durch ungeklärte Umstände , man spricht von Blutorgien, erlangte er den Stand eines hohen und von dort zu einem Gott. Seine Anhänger waren damals babarischer und wilder aber vor allem ungebildeter als Anhänger anderer Götter. Niedere Charaktere. Chu'kay ist im engsten Sinne ein versinnlichter Gott. ein Gott des Geistes in diesem Fall des Wahnsinns. Das Avatar Ritual wird vollzogen um seine Macht zu dämmen. Man beschwört eine Fleischliche Hülle um seinen Einfluss grenzen zusetzen. Diese Hüllen scheinen äusserst anfällig und schwach zusein. Beim Ritual sind ein Bokur und ein Bluthund zugegen. Der Bluthund beschützt die Bokur oder tötet sie falls sie anheimfällt. Diese Rituale liefen immer Problemlos bis auf eines in welcher die Bokur den grinsenden Hund als Kackfressenden Drecksköter ohne Hirn betitelte. Chu'kays einflüsterungen liessen den Bluthund durchdrehen und die Bokur töten. Der Bluthund starb in Schande durch sein eigenes Schwert.\"",},
			["Circulus Virtuosus"] = { content = "'''Circulus Virtuosus''' ist eine [[Gilde]] der [[Allianz]]. \r\n==Anmerkungen==\r\nAuch wenn die wenigsten Mitglieder des Circulus Virtuosus Aktives oder „Plot“-Rollenspiel betreiben, so hat sich doch jedes Mitglied der Einhaltung der RP-Richtlinien verpflichtet. Gildeninternes Rollenspiel sowie in Instanzen findet – abhängig von den jeweiligen Mitgliedern – statt. \r\nDie vom Circulus Virtuosus ausgerichteten [[Raid]]s sind -unterstützt. Die Gewichtung des Rollenspiels, unabhängig von der Verpflichtung zur Einhaltung der Offiziellen RP-Richtlinien, ist allen Mitgliedern freigestellt.",},
			["Citrin"] = { content = "Citrin ist ein herrlicher Edelstein, der in Metallvorkommen gefunden werden kann. Nur wenige Edelsteine sind wertvoller als er. Die magischen Eigenschaften, mit denen [[Schmied]]e ihre Waren ausstatten, werden deutlich verstärkt, wenn Citrine im Spiel sind.",},
			["Coatl"] = { content = "Coatl leben auf [[Azeroth]] und Im [[Smaragdgrünen Traum]]. Sie sind große Kreaturen, die an [[Windnatter]]n erinnern, jedoch flacher und größer und farbenprächtiger sind. Sie nisten an den Küsten Azeroths. Einige sind giftig, andere können, ähnlich den [[Dryade]]n, [[Magie]] brechen. Sie verstehen [[Nazjar]], jedoch nur so wie die [[Vampirfledermäuse]] [[Gossensprache]] verstehen.\r\n[[Naga]] Sirenen sind in der Lage, diese Wesen mit ihrer [[Magie]] anzulocken und sie in ihre Armee einzugliedern. Dort dienen sie als Luftaufklärer und speien ihren giftigen Magensaft gegen die Feinde ihrer Herren.\r\nDie Coatl stammen ursprünglich von [[Zandalar]], wo die [[Trolle]] sie verehrten.\r\nAnmerkung:Das Wort Coatl stammt aus dem Aztekischen und bedeutet \"Schlange\".",},
			["Coiren Bayvanar"] = { content = "Coiren Bayvanar ist eine strenge und von eiserner Disziplin erfüllte Priesterin. \r\n===Kapitel 1===\r\nDer Morgen graute und eine kühle, feuchte Brise fegte durchs offene Fenster der kleinen Stube in der Festung Theramores, wo Coiren Bayvanar vor einem einfachen Waschtisch saß und sich sorgfältig ihr graues, schulterlanges Haar kämmte bis es glänzte. Die Kammer war einfach und funktionell, mehr wie die einer Novizin als einer ausgebildeten Priesterin. Ein kleiner Läufer mit typischem Gilneasmuster in blau und braun zierte den Steinfußboden vor dem schmalen Bett, das immerhin Federkissen hatte, ein kleines Zugeständnis an die nötige gesunde Nachtruhe. Auf dem Sekretär am anderen Ende des Raums stapelten sich einige Folianten neben Schriftrollen und dem sorgfältig platzierten Schreibgerät und auf dem Fensterbrett in einer kleinen blauen Vase blühte eine violette Aster trotz des zwar milden aber noch anhaltenden Winters an der Küste Kalimdors. \r\nSeufzend ließ Coiren die perlmuttbesetzte Bürste sinken, schaute müde in den matten Spiegel und straffte die Haut um ihre Augen, die täglich mehr Falten zu zeigen schien. An Tagen wie diesem wog es schwerer als normal. \r\nJahre zuvor stürmt eine Frau mit geraffter Robe aus dem großen Lazarettzelt des Rückzugkommandos aus Lordaeron. Die lang erwartete und längst überfällige Spähgruppe schleppte sich ins Lager. Schnell zählte sie die Kämpfer durch, zwanzig waren vor zwei Tagen aufgebrochen, um Verletzte einzusammeln. Es standen noch acht und auf einer Bahre, von Pferden gezogen, lag noch ein Verletzter. Schnell zog die junge Priesterin die schmutzige Decke des Liegenden fort und unterdrückte ein Stöhnen. Etwas hatte große Stücke aus dem Fleisch des rechten Arms gerissen und der Lederharnisch war schmierig blutverkrustet. Das schmerzverzerrte Gesicht eines jungen, dunkelhaarigen Kämpfers blickte sie aus trüben Augen anklagend an. Die Hände über der Brust des Verletzten kreuzend bewegte sie stumm die Lippen und Licht flutete tastend aus ihren Fingerspitzen über den geschundenen Körper. „Gebt ihm etwas zum Schlafen und verbrennt seine Leiche“, wies sie einen der Lagerhelfer gepresst an und erhob sich seufzend. Die Bisswunden am Arm waren schon ein klares Zeichen aber sie wollte keinen Fehler machen und prüfte jeden Infizierten zunächst noch einmal, immer in der Hoffnung, dass es nicht die Seuche war, die den Körper deformierte und versklavte. Bisher war diese Hoffnung immer enttäuscht worden. \r\nTraurig lächelnd trat sie zum Fenster, schaute aufs Meer und ließ wie beiläufig eine helle Sphäre in ihrer rechten Handfläche erscheinen, die in die Aster einsank. Jeden Tag ein wenig davon und die Blüte würde sie auch noch bis zum Frühjahr begleiten. Leider war dieser kleine Trick nicht auf sie selbst anwendbar. Menschen alterten und heute wurde sie zweiunddreißig Jahre alt. Natürlich wusste das nahezu niemand und recht war es. Sie straffte sich und zog ihr weißes Kleid glatt. Glückwünsche waren nicht angebracht und im schlimmsten Falle Zeitverschwendung. \r\nEinen Umhang vom Haken nehmend wandte sich die Priesterin zur Tür, verharrte kurz und nickte. Zum Frühstück würde sie sich einen gefüllten Kirschkuchen gönnen.\r\n===Kapitel 2===\r\nDas Feuer prasselte im Backsteinkamin des Wohnraums und hielt die feuchte Winterkälte im Schach. Geoff Bayvanar kraulte die rote Katze, die Melissa letzte Woche irgendwo aus den Straßen Lordaerons aufgesammelt hatte. Halb erfroren und zerrupft war die Kreatur, die seine Tochter mit großen Augen im Arm gehalten hatte als wäre sie der größte Schatz der Welt. Jetzt lag sie schnurrend auf seinem Schoß und blickte träge mit halbgeschlossenen Augen ins Feuer. \r\nEin markerschütterndes Kreischen von oben kündigte es an, ein schwarzhaariges Bündel stürzte brüllend mit wehenden Zöpfen und einem Holzschwert in der Hand die Treppe in die Stube hinab, gefüllt von einem wutentbrannten Jungen. Mit einem Kampfschrei aus voller Kehle rannte das Mädchen zu ihrem Vater und rutschte unter seinen Stuhl, sich hinter seinen Beinen verschanzend: \"Papa, Danvil will mich hauen.\" Seufzend stand Geoff auf, was die Katze mit einem Sprung und einem vernichtenden Blick quittierte. \"Immer spottet sie, nur weil ich übe. Nächste Woche sind die Aufnahmeprüfungen bei der Silberhand\". Danvil funkelte seine Schwester an, die unter dem Stuhl hervorgekommen war und nun das Schwert in gespielter Pose zur Decke streckte: \"Koste die Macht des Lichts, Elender\". Geoff packte seine Tochter unter den Armen und setzte sie auf seine Schultern, wo sie kichernd das Schwert nach ihrem Bruder schwang. Mit leisen Tritten kam eine zierliche üppige Frau die Treppe hinab und hob spielerisch mahnend einen Finger: \"Und du, Melissa Coiren Bayvanar, kommst bald in die Schwesternschule, wenn du nicht Ruhe gibst. Und jetzt zu Tisch.\"\r\n===Kapitel 3===\r\nEin kalter Wind blies Melissa Coiren Bayvanar ins Gesicht, als sie aus der Kutsche stieg, im kleinen Hafen der Süderstade. Ganz in Grau und Blau gekleidet, die Haare hochgesteckt und eine kleine Ledermappe unter dem Arm schlenderte sie zum Dock. In der Tat, sie schlenderte, wie sie es wahrscheinlich seit Jahren nicht getan hatte. Nun lag alles in der Hand des Lichts. Kurz drückte sie die Mappe mit den Notizen vergangener Jahre an sich. Sie würden noch wichtig werden, das wusste sie. \r\nHinter ihr entluden Dienstboden emsig ihre Koffer vom Gefährt. Die Habseligkeiten, einige Kleider, warme und festliche, wenige Bücher und etwas Geschmeide, das noch übrig geblieben war. Der Rest war das, was vor ihr lag. Ein Schiff und eine Mannschaft. Jahrelang hatte sie gespart und nun war der Augenblick gekommen, in dem sie ihr Wissen, ihren Glauben und ihr Ziel umsetzen konnte. \r\n\"Mistress Bayvanar, willkommen an Bord\", kam ihr der junge Kapitän freundlich entgegen und hielt ihr seine starke Hand hin. Coiren lächelte nur und nickte würdevoll, nahm seine Hand und trat aufs Schiff. Eines der kleineren aber robusten Art, nicht schnell aber den Witterungen trotzend. Sanft drehte sie sich um, sie merkte selbst, wie alle Strenge aus ihr wich. Jetzt am vorläufigen Ende ihres Weges. Nichtsdestotrotz hob sie kritisch eine Braue, als einer ihrer Koffer polternd auf die Planken fiel. Nein, sie würde dem Jungen keine Lektion erteilen. \r\nEs war finster und der Mond schien fahl und kalt auf ein ruhiges, großes, weites Meer. Ein kleines Schiff verließ langsam den Kontinent, wandte sich immer stärker nach Norden. Dorthin, wo wohl niemand folgte. Zu Danvil. Zur letzten Mission der Coiren Bayvanar.\r\n===Kapitel 4===\r\nA'dal verströmte seinen Singsang in leise auf- und abschwellender Melodie durch die Halle des Lichts. Sein Gebet wirkte stärker, je mehr Streiter sich in Shattrath aufhielten. Einem lichten Schleier gleich legte es sich wie Balsam auf jedwedes Gemüt und reinigte jeden, ob die Verlassene in ihrer abgerissen Robe oder den Zwergenkrieger, sie alle würden sich kaum zu Blutvergießen hinreißen lassen. Die Friedensstadt sollte bleiben was sie war, ein Refugium für die Tapferen mit hehren Zielen und für die geschundenen Seelen, die zu viel Krankheit, Gedärm und Boshaftigkeit gesehen hatten. \r\nEine wild bezopfte Gnomenfrau eilte in die Halle und rannte, sich fast überschlagend, zum Händler der Sha'tar und reckte ihm stolz einen Stapel gesammelter Artefakte entgegen, woraufhin sich an ihrem Torso umgehend ein neuer Brustschutz materialisierte. Jubelnd und stolpernd entschwand sie ins Untere Viertel, auf der Suche nach einem Zauberkundigen. \r\nNacht legte sich über die Hauptstadt der Scherbenwelt und Ruhe kehrte ein. Aus weiter Ferne röhrte nur ein Talbuk, sogar das Gezeter und Gepreise der Kaufleute nahm ab. A'dal sang leiser, Schlafende erforderten ein weniger starkes Friedensgebet und Kraft war es, die in diesen Zeiten nicht zu verschwenden, sondern zu bündeln war. Die Kraft aller, der elfischen Seher und der Priesterschaft der Aldor und selbstredend der Streiter aus Azeroth. Alle mussten sie ruhen. Ruhe für den Kampf um das Plateau. \r\nA'dal war es zufrieden und sein tiefer Geist setzte zu einer Prüfung des Kontinuums an, wie jede Atomstunde. Wie lange würden die Scherben halten, wie lange noch, bis die Schmieden des Nethersturms, besonders die beschädigten, auch auf die anderen Gebiete übergriffen und ihnen die innerste Essenz, die Realität entzogen? Über das Bewusstsein des alten Naaru huschte eine Wahrnehmung, ein Blinzeln, doch im nächsten Augenblick war es fort. Ein Trick? Dämonen nutzten Geisteskräfte, sogar um die Naaru zu verwirren, auch wenn ein solches Vorhaben an A'dal selbst eine Tollkühnheit voraussetzte, die die feige Legion der Netherbewohner selten an den Tag legte. Da, wieder. Er versuchte es zu schauen, zu erspüren, zu ertasten und Fasern seines lichten Ichs streckten sich dem Phänomen entgegen. Wo war es? Fort. Da, wieder. Not. Ein Schrei? In der Halle selbst! A'dal glühte auf, als er die Macht des Lichts stärker in sich sog und sich auf einen Angriff ins Herz Shattraths bereitete. Sie würden brennen und weinen in der Agonie der Wahrhaftigkeit. A'dal pulsierte. \r\nEin Riss brach ins Kontinuum, mikroskopisch klein, doch auch der Riss pulsierte. Er pulsierte und nährte sich, wuchs und riss stärker, etwas wölbte sich hindurch. A'dal sah nun auch die verzerrten, gebrochenen Lichtstrahlen, die an seinem Fuß gleich um eine schillernde Blase geleitet wurden. Das war Magie. Banale Magie. Grob und profan, wie sie sich durchschnitt, durchhackte durch den zähen Schleim der Realität. Ein Pfeifen, ein Sturm, ein Schwall von Licht brach aus der Blase und zu allen Seiten sich faserig fortpflanzend ein Loch in der Welt, ein instabiles Portal. Der Naaru ließ seinen Geist wandern, konfigurierte ihn in einen Schutzschild um und begann einer Haube gleich das Phänomen abzudecken. Solch profane Magie konnte in einer schrecklichen Explosion enden, die von der Stadt nicht viel mehr als Ruinen ähnlich dem Auchindoun hinterlassen würden. \r\nDas Portal stülpte sich nach außen, schien sich regelrecht zu übergeben und heraus flogen ein brennendes Menschensubjekt und ein brüllendes Weibchen. Kaum kamen sie krachend auf dem Boden der Halle auf, implodierte das Portal in einem Funkenstieben, gleich einer Kraftnova. A'dals Geist pufferte die Wellen der rohen Magie. Nichts passiert. Bedächtig richtete er sein Bewusstsein auf die beiden Menschen. Das grauhaarige weibliche Subjekt drehte sich schluchzend auf den Rücken. Das Männchen war verkohlt, unrettbar. Aus dem Innersten der Menschenfrau fühlte er eine sachte Resonanz. Eine Lichtsprecherin, Priesterin wie sie es hier nannten. Sie würde heilen. Rettbar.\r\n===Kapitel 5===\r\n\"Schwester Coiren, die Kassen sind leer. Sturmwind und die Kirche sind am Rande des Bankrotts. Der Krieg lässt uns keinen Spielraum für eure Spielereien. Das ist nun die zweite Expedition, die Ihr anführtet und wer glaubte, dass das Desaster des schon fast sprichwörtlichen Gilneasunternehmens nicht zu überbieten gewesen sei, wurde in den letzten Tagen eines Besseren belehrt. Euer Rückzug nach Theramore damals war offenbar nicht weit genug.\" Der junge Buchhalter funkelte sie düster an und begann schon die Papiere in einem schwarzen Ledereinband zusammenzustecken. Coiren strich sich eine Strähne aus der Stirn und suchte fieberhaft nach Argumenten und Erklärungen. Sie mussten doch verstehen, dass diese Mission Priorität genießen musste, wenn sie nicht überrascht werden wollten. Von neuen Nekropolen, die sich diesmal vielleicht nicht mehr abwehren ließen. \r\n\"Ich verlange eine aktuelle Fragestunde vor dem inneren Plenum, Meister Thomas. Ich habe Euch alles Wichtige notiert. Euch muss klar sein, dass wir meine Erkenntnisse über Nordrend nicht ignorieren können.\", führte sie äußerlich gelassen aus. Der Junge würde sich durch Disziplin nicht beeindrucken lassen. Er kannte den Habitus der Priesterschaft, aber immer noch besser als ihre tatsächliche Aufgewühltheit zu offenbaren: \"Im Übrigen habe ich alle Mittel diesmal selbst aufgebracht. Wir brauchen jetzt eine Armee im Norden. Sturmwind hat Macht, noch hören die Helden auf den Ruf der Kirche und des Königs.\" Seufzend erhob sich ihr Gegenüber von seinem Stuhl. \"Euer persönlicher Rachefeldzug, und nichts anderes ist es doch, ist unfinanzierbar. Von all den verschenkten Leben tapferer Streiter ganz zu schweigen. Ihr wisst, wo es hinausgeht\". Wie betäubt erhob sich Coiren. Was erdreistete sich dieser ignorante Bürokrat. Zitternd strich sie ihre blaue Robe glatt und wandte sich grußlos ab. Noch im Gehen hielt sie inne. \"Das Licht behüte und beschütze Euch, junger Mann. Der Untod ist kalt.\" Erhobenen Hauptes trat sie auf den Gang hinaus und ließ die Tür zufallen.\r\n===Kapitel 6===\r\nCoiren ließ ihren Blick über die ohrenbetäubend aufgewühlte Klasse schweifen. Auch Theramore bildete ein kleines Kontingent Priester aus. Sie schätzte diese Unterrichte nicht und mit mehr als Schildkunde belästigte man sie selten. Hin und wieder eine Vertretung in Neuerer Geschichte, aber ihre militärische Sicht war den Aufsehern des Curriculums meist zu eng gefasst. Die Arme hinter dem Rücken verschränkend blickte Coiren aus dem Fenster zum Hafen und schüttelte leicht den Kopf. Eine Garnison in Kalimdor, der ihre Inhalte zu militärisch waren. Noch einige Augenblicke, dann würde sie dem Treiben der Klasse ein Ende bereiten. Die Sonne brannte heute schön, das Meer glitzerte und trotz des Hitzeflimmerns auf dem Pflaster draußen wehte eine erfrischende Brise salziger Luft in den Raum und spielte mit einem hübschen Mobilé, das einen Kraken, einen Wal und darüber Seemöwen umeinander tanzen ließ. \r\nMit herrischem Ausdruck schnitt plötzlich die Stimme der Priesterin durch den Tumult: \"Tinea Barrel, fünnef und siebzig Kniebeugen und dazu die Verse zehn bis vierzehn aus der Disciplinica!\" Ihre Anweisung zeigte sofortige Wirkung. \"Und wenn in meinem Unterricht noch einmal so ein Geschrei herrscht, lasse ich einen gnomischen Zauberbinder eure schnatterhaften Sprechapparate lähmen.\" Handtellergroße Augen starrten sie an und jeder einzelne der jungen Schüler rückte so schnell und so leise wie möglich auf seinen Platz. Das mit den Zauberbindern funktionierte immer. Still in sich hineinlächelnd wendete sich Coiren wieder zum Fenster und ließ die atemlose Rezitation der turnenden Novizin über sich waschen. \r\nNicht, dass sie zu ihrer Zeit ruhiger oder gar emsiger als diese Novizen gewesen war. Im Gegenteil, zunächst gegen ihren Willen in der kleinen Abtei im Dunkelhain, musste sie die Erkenntnisse des Lichts erst mühsam und zuweilen schmerzhaft studieren bis sie sieben Jahre später zur Priesterprüfung zugelassen worden war. Im damaligen Hordekrieg war die Ausbildung gestrafft und auf notwendigstes Kriegs- und Heilungshandwerk reduziert worden. Von Kunst konnte dabei keine Rede sein. In der Schlacht zählten Schockheilungen, keine filigranen Gewebe, die keine Narben hinterließen. \r\nCoiren legte den Kopf schief als würde sie etwas lauschen, das niemand sonst vernahm. Irgendwie hatte sich seit damals die Notwendigkeit von Schockheilungen nicht entschärft. Wenn ihre Mission eines Tages endete, bestand vielleicht Hoffnung zu lernen, keine Narben zu hinterlassen. \r\nDie Novizin war fertig. \"Schilde, die Kunst, Kraft der Seele des Rezipienten, Wunden präventiv entgegenzutreten\", Coiren griff nach dem Zeigestock und beschrieb Kreise und Formen in der Luft, während sie erklärte.",},
			["Colonel Kurzen"] = { content = "'''Colonel Kurzen''' war einst ein großer, ein edler Mann, doch er unterlag im [[Schlingendorntal]] dem Einfluss von Trollmagie. Noch immer aber ist er ein brillanter Taktiker und seine Männer sind den [[Rebellenlager|Rebellen in ihrem Lager]], die sich gegen ihn stellen, zahlenmäßig mindestens 10 zu 1 überlegen. Er erteilt die Befehle an seine Männer von tief aus dem [[Kurzens Lager|Vorratslager]] heraus.",},
			["Coren Düsterbräu"] = { content = "'''Coren Düsterbräu''' ist ein [[Dunkeleisenzwerg,]] der während des [[Braufest]]es in der Taverne der [[Schwarzfelstiefen]] zu finden ist.",},
			["Corins Kreuzung"] = { content = "Corins Kreuzung war der zentrale Verkehrsknotenpunkt in den [[Östliche Pestländer|Östlichen Pestländern]]. Heute findet man hier Mitglieder der [[Geißel]] in recht großer Anzahl. Viele der Untoten Scheusale hier waren einst gute Leute aus [[Darroheim]].",},
			["Crimson Veil"] = { content = "Die \"'''Crimson Veil'''\" ist ein Schiff aus der Flotte der Blutsegelbukaniere, das bei Firallons Ankerplatz im Schlingendorntal vertaut ist. Hier findet man die Führungskräfte der Blutsegler unter dem Kommando von Flottenmeister Firallon.",},
			["Cyclonian"] = { content = "=== Cyclonian===\r\n* [[Alterac]]\r\nCyclonian ist ein mächtiges Luftelementar, für dessen Untergang Bath'rah der Windbehüter sorgen will.",},
			["Cyrukh der Feuerlord"] = { content = "Cyrukh der Feuerlord ist ein mächtiges [[Elementa]]r, dass [[Gul'dan]] einst am [[Altar der Verdammnis]] beschwor.Er trägt denselben Titel wie [[Ragnaro]]s, dem Herrscher der azerothanischen [[Feuerelementare]].Ob ein Zusammenhang zwischen den beiden besteht, ist allerdings noch unklar.Doch Cyrukhs Feuer ist grün, also verderbt.",},
			["Cyrus' Höhle"] = { content = "'''Cyrus' Höhle''' befindet sich im Nordosten der [[Brennenden Steppe]]. Es ist der Unterschlupf des schwarzen Großdrachen [[Cyrus Therepentous]].",},
			["Cyrus Therepentous"] = { content = "Der schwarze Großdrache '''Cyrus Therepentous''' bewohnt Cyrus' Höhle in der [[Brennende Steppe|Brennenden Steppe]]. Er würde gern die sengenden Flammen des Feuerberges schmecken, die flüssigen Feuer des [[Schwarzfels]] über sich strömen lassen, denn diese Essenz, diese sengende Hitze ist es, nach der er sich sehnt. Man kann Cyrus seinen Wert beweisen, indem man ihm eine abgestreifte Haut des schwarzen Drachenschwarms bringt und anschließend eine Kostprobe der Flamme von [[Bael'Gar]] in den [[Schwarzfelstiefen]] besorgt, indem man die feurige Essenz mittels der abgestreiften Haut aus Bael'Gars Überresten einfängt.\r\n... Man hat jedoch so ein Gefühl, dass Cyrus bereits weiß, dass die meisten Freiwilligen unwürdig sind ...\r\n'''Anmerkung:''' Die abgestreifte Haut des schwarzen Drachenschwarms erhält man, wenn man die Questreihe von [[Kalaran Windklinge]] in der [[Sengende Schlucht|Sengenden Schlucht]] beendet hat.",},
			["D'ore"] = { content = "'''D'ore''' ist ein [[Naaru]] in der [[Auchenaikrypta]] von [[Auchindoun]].\r\nTief in der [[Auchenaikrypta]] befindet sich ein Grab: ein Grab, dass keinesgleichen in den zerschlagenen Weiten findet. Aus diesem Grab, dem ersten Grab, wurde das riesige Mausoleum von [[Auchindoun]] geboren. Darin wird der Geist von D'ore gefangen gehalten. Seit mehreren Jahrhunderten verbinden sich die Geister von Auchindoun nun mit D'ores getrübter Essenz. Viele der Katastrophen, die diese Krypta heimgesucht haben, sind auf den geschwächten Zustand dieses Naaru zurückzuführen. Unglücklicherweise kann nichts diesen Kreis aufhalten. Das gehört zur Natur der Naaru - ohne die Leere kann das Licht nicht existieren. Seine Erinnerung jedoch ist noch immer sehr lebendig. D'ores Energien wurden bei dem Aufprall vollkommen ausgelaugt. Er war nichts als ein kleiner Fleck von Leerenergien, als [[Prophet Velen]] und seine [[Draenei]]freunde seine Überreste geborgen und in die Auchenaikrypta gebracht haben. Nach einer Zeremonie wurde seine geschwächte Form in einem Sarkophag zur Ruhe gebettet. D'ore hat sich nun für fast tausend Jahre regeneriert. Der Kreis ist fast geschlossen...",},
			["Daelin Prachtmeer"] = { content = "Lord Admiral Daelin Prachtmeer verlor seinen ältesten Sohn in der Tragödie der [[Dritte Flotte von Kul Tiras|Dritten Flotte von Kul Tiras]] und jeden sonst an Bord jener sechs großen Schiffe als rote Drachen über sie herfielen. Von den mächtigen Fahrzeugen, waren nur Holzsplitter und einige wenige zerrissene Leichen übrig, um dise äußerste Zerstörung zu zeigen. Es war Lord Admiral Prachtmeers Verdienst, dass er nicht stockte in seiner Entschlossenheit und sofortden Bau neuer Kriegsschiffe befahl, um jene zerstörte zu ersetzen und damit den Krieg voranzutreiben.\r\nAdmiral Dealin Prachtmeer trat das erste Mal in Erscheinung als die [[Allianz]] gegründet wurde. Als treuer Freund von [[Anduin Lothar]] sprach er sich für die Gründung der [[Allianz]] aus und bildete mit [[Lordaeron]] und den Überlebenden von [[Azeroth]] den Grundstein der [[Allianz]], bevor sich [[Stromgarde]], die Elfen und die [[Zwerge]] der [[Allianz]] anschlossen. \r\nWährend des zweiten Krieges unterstützte er die [[Allianz]] hauptsächlich durch seine Seestreitmacht. Als Inselnation hatte [[Kul Tiras]] die größte Flotte aller Menschennationen gehabt und die Seewege kontrolliert, nun setzte Prachtmeer diese Schiffe gegen die [[Horde]] ein. Dabei handelte er bedingungslos treu zur [[Allianz]]. Als sein ältester Sohn zusammen mit seinen Schiffen von einigen [[Drachen]] unter dem Kommando der [[Orcs]] getötet wurde, sendete Prachtmeer trotz seines Verlustes sofort neue Schiffe aus um die [[Allianz]] zu unterstützen.\r\nNach dem Ende des Krieges zerbröckelte die [[Allianz]]. Streitfragen wie die Zukunft der Verräternation [[Alterac]] hatte die Politischen Ziele der einzelnen Nationen wieder in den Vordergrund gestellt, zumal [[Lordaeron]] noch Abgaben zum Wiederaufbau verlangte. Prachtmeer allerdings blieb der [[Allianz]] auch hier treu und bildete nun mit [[Lordaeron]], [[Azeroth]], [[Dalaran]] und den [[Zwerge]]n von [[Eisenschmiede]] den Rest der [[Allianz]], während [[Stromgarde]], [[Gilneas]] und [[Quel'Thalas]] ihrer Wege gingen.\r\nDer Admiral gab seine Jüngste Tochter [[Jaina Prachtmeer]] zu den [[Kirin Tor]], wo sie als Magierin ausgebildet wurde und kümmerte sich im weiteren um die Sicherung der Seewege vor Piraten. Als [[Jaina Prachtmeer|Jaina]] eine Expeditionstruppe nach [[Kalimdor]] zusammenstellte gab Daelin ihr auch einige seiner Truppen (sogar von [[Gilneas]] und [[Stromgarde]] hatte sie Unterstützung erhalten). \r\nKurz darauf wurde [[Lordaeron]] von der [[Geißel]] überrollt und [[Quel'Thalas]] und [[Dalaran]] zerstört. Da Jaina in der Zeit keine Nachricht von sich geben ließ machte er sich auf nach [[Kalimdor]], um seine Tochter zu suchen. Als er sie in der von ihren Leuten errichteten Stadt Theramore fand, unterhielt sie sich gerade mit einem [[Mok'Nathal]], einer Kreuzung aus Orc und [[Oger]]. Durch die Verluste, die er im zweiten Krieg hatte erleiden müssen, hatte er einen großen Hass auf die Völker der [[Horde]] insbesondere die [[Orcs]], daher ließ der den [[Mok'Nathal]] [[Rexxar]] quer durch die Stadt jagen. Als er von ihrer neuen Siedlung unweit Theramore erfuhr bereitete er einen Angriff vor, so sehr Jaina auch versuchte ihren Vater umzustimmen, er wollte nichts davon hören. \r\nDie [[Orcs]] wahren ihrerseits von [[Rexxar]] gewarnt worden und schlugen den Angriff des Admirals zurück, so dass dieser sich nach Theramore zurückziehen musste (er hatte seiner Tochter die Kontrolle über Theramore entzogen). Als die [[Horde]] Theramore angriff achteten diese darauf, nur jene [[Menschen]] zu töten, die auch die Hand gegen sie erhoben. Prachtmeer kämpfte trotz seiner sicheren Niederlage gegen die [[Horde]] und stellte sich weiterhin taub gegen die Worte seiner Tochter, die besagten, dass die Horde sich gebessert hat und im Frieden leben will. Er wurde letztendlich von [[Rexxar]] im Zweikampf getötet und starb in den Armen seiner Tochter. Die [[Orcs]] beendeten daraufhin ihren Angriff auf [[Theramore]].",},
			["Dalaran"] = { content = "Obwohl '''Dalaran''' die kleinste Nation der [[Menschen]] war, war sie in allen Ländern als Zentrum der [[Magie]] bekannt. Die Staatsgewalt über das magische Reich ging von einem Rat mächtiger Zauberer aus, dem [[Rat von Dalaran]]. Während des dritten Krieges wurde der ehemalige Stadtstaat von [[Arthas]] und [[Kel'Thuzad]] gestürmt, um [[Archimonde]], den Feldherrn der brennenden Legion, zu beschwören. Ihr Vorhaben gelang und der Dämon legte die gesamte Stadt in Schutt und Asche. Die [[Kirin Tor]] beschlossen daraufhin, über dem Zentrum der Stadt eine mächtige, magische Kuppel zu errichten, durch die man weder gehen noch sehen kann. Was sie dort genau vorhaben, kann niemand genau sagen. Einige glauben, dass es zum Schutz gegen die Gewalt ihrer Zeit gemacht wurde, andere wiederum sagen, dass sie einfach Ruhe zum Studieren und Pläneschmieden haben wollen. Doch es ist sicher, dass die Magier von Dalaran sehr damit beschäftigt sind, ihre zerstörte Stadt und die [[Violette Zitadelle]], den Hauptsitz der [[Kirin Tor]], wieder aufzubauen. Die verfallenen Vororte der Stadt, die außerhalb der Kuppel liegen, beherbergen möglicherweise wertvolle magische Schätze, aber dieses Gebiet wird von den Hexern und ihren Elementarsklaven patrouilliert, denn ein bemerkenswertes Talent der Hexer von Dalaran ist ihre Vertrautheit mit den Elementaren. Die Hexer benutzen magische Marken als Mittel, diese Elementare zu kontrollieren und jeder Einwohner von Dalaran hat solche Marken.\r\n==Dalaran in Nordend==\r\nAngeführt von [[Rhonin]] haben die [[Kirin Tor]] mit [[Wrath of the Lich King]] Dalaran als letzte Front im Krieg gegen den [[Blauer Drachenschwarm|Blauen Drachenschwarm]] nach [[Nordend]] gebracht. Einem gestärkten [[Malygos]] folgend, versucht der Blaue Drachenschwarm nun [[Azeroth]] von allen Magie-Nutzern zu säubern. Das über Nordend schwebende Dalaran wird als neutrale Stadt agieren – eine Art [[Shattrath]] des Nordens.\r\n==Personen==\r\n* [[Rhonin]]\r\n==Dungeons== \r\n* [[Violette Festung]]",},
			["Dalliah die Verdammnisverkünderin"] = { content = "'''Dalliah die Verdammnisverkünderin''' ist eine Shivarra in der [[Arkatraz]], einem Teilkomplex der [[Festung der Stürme]].\r\n==Taktik==\r\nDem Tank sollte genügend Zeit gelassen werden, um Bedrohung aufzubauen, denn Dalliah ist immun gegen SPOTT. Sobald sie ihren WIRBELWIND loslässt, müssen alle Nahkämpfer (auch der Tank) zurücktreten, danach aber wieder sofort zu Dalliah, um ihren Selbstheilungszauber zu unterbrechen. Ihr Fluch: GABE DER VERDAMMNISVERKÜNDERIN kann nicht entfernt werden. Dalliah schreit förmlich nach Prügel und das ist auch die beste Taktik – bringt sie also schnell zu Fall.\r\n'''Quelle:''' www.buffed.de\r\n==Fähigkeiten==\r\n* Gabe der Verdammnisverkünderin - Fluch, der Dalliah um den dreifachen Wert heilt, mit dem der Betroffene geheilt wird. Dauert acht Sekunden an und kann nicht entfernt (decursed) werden.\r\n* Wirbelwind - Flächenschaden, der alle Nahkämpfer mit bis zu 4.000 Punkten pro Treffer erwischt. Danach setzt Dalliah zur Heilung an, die Ihr unterbrechen könnt.",},
			["Dalsons Tränenfeld"] = { content = "'''Dalsons Tränenfeld''' ist ein ehemaliger Bauernhof in den [[Westliche Pestländer|Westlichen Pestländern]], der der Geißel anheim gefallen ist. Es befindet sich ziemlich genau nördlich von [[Andorhal]] und ist der Standort eines [[Seuchenkessel]]s.",},
			["Dampfdruckkartell"] = { content = "Das Dampfdruckkartell ist die Gemeinschaft der [[Goblins]] und unterteilt sich nach den vier großen Siedlungen:\r\n* [[Beutebucht]] im [[Schlingendorntal]]\r\n* [[Ewige Warte]] in [[Winterquell]]\r\n* [[Gadgetzan]] in [[Tanaris]]\r\n* [[Ratschet]] im [[Brachland]]",},
			["Dampfdruckpier"] = { content = "Das Dampfdruckpier ist ein kleiner Hafen der [[Goblins]] vom [[Dampfdruckkartell]] an der Ostküste von [[Tanaris]].\r\n==Personen==\r\n* '''Ausgrabungsleiter Eisenschuh''' - Ausgrabungsleiter Eisenschuh sucht die verlorenen [[Schrifttafel von Mosh'aru]]. Die Schrifttafeln sprachen davon, die Essenz von [[Hakkar]] zu bewahren, aber an dieser Legende ist noch mehr. Er hat sie lange studiert und herausgefunden, dass es sechs Schrifttafeln gibt. \r\n* '''Eingebildete Modeschöpferin''' - Eine eingebildete Modeschöpferin ist die Lieferantin für modische Kleidung, die in den höchsten Kreisen der Gesellschaft Azeroths gefragt ist und sucht [[Südmeerpiraten]]hüte. Sie verkauft ab Patch 2.4.3 neue Schnittmuster für ein Haliscanjakett und die Haliscanpantalons.\r\n* '''Gikkix''' - Gikkix ist ein Angler\r\n* '''Jabbey''' - Jabbey handelt mit Gemischtwaren\r\n* [[Narain Pfauentraum]]\r\n* '''Sicherheitschef Bilgenritzel''' - Sicherheitschef Bilgenritzel erhielt vom [[Dampfdruckkartell]] die Aufgabe, dass er den [[Südmeerpiraten]] eine Lektion erteilt. Er kann aber nicht an zwei Orten gleichzeitig sein. Seit neuestem hält nicht mal mehr das Schutzgeld, dass das Kartell regelmäßig auszahlt, die Piraten auf. Trotzdem kämpft Bilgenritzel gegen die \"Gaunerei und Erpressung im Südmeer\" und beauftragt Freiwillige, die Piraten der [[Südmeerfreibeuter]] zu töten. Auch der niederträchtige Pirat [[Andre Feuerbart]] wird von Bilgenritzel aufgrund seiner gegen die Einwohner des Dampfdruckpiers und [[Gadgetzan]] gerichteten Verbrechen gesucht. \r\n* '''Stoley''' - Stoley schmeißt die Bar am Dampfdruckpier. Er schuldet [[Seewolf MacKinley]] in [[Beutebucht]] etwas Rum, um eine Wette zu begleichen, aber ihm ist der Rum ausgegangen. [[Kapitän Cuergo]] hat seine letzte Lieferung gestohlen und lagert sie in der ummauerten Piratenstadt im Süden. Wenn man seine Rumlieferung finden und zurückbringen kann, dann kann er MacKinley beweisen, dass [[Kalimdor]]s Drinks die aus [[Beutebucht]] um Längen schlagen und MacKinley wird endlich seine verrückten Ansichten über Drinks aus [[Beutebucht]] über Bord werfen können.\r\n* [[Yeh'kinya]]",},
			["Dampfkammer"] = { content = "#REDIRECT [[Echsenkessel: Dampfkammer]]", redirect = "Echsenkessel: Dampfkammer",},
			["Dampfpanzer"] = { content = "'''Dampfpanzer''' sind schwerfällige und schwer gepanzerte Fahrzeuge, die als bewegliche Belagerungswaffen dienen und von mutigen, manchmal schon verwegenen [[Zwerge]]n gesteuert werden. Ihre schweren Waffen sind zu unbeweglich, um gegen feindliche Einheiten gerichtet zu werden, und lassen sich nur gegen Gebäude einsetzen. \r\n[[Ingenieur]]e können die für eine Mini-Ausgabe der Dampfpanzer bauen, wobei es zusätzlich noch Gnomische und Goblinsche Varianten gibt. Auch auf [[Dunkelmonds Jahrmarkt]] erfreuen sich diese Mini-Dampfpanzer großer Beliebtheit.\r\n==Goblindampfpanzer==\r\nDer Goblindampfpanzer (engl. The Demolisher) ist eine Belagerungswaffe im [[Tausendwintersee]] und den [[Sandes von Ulduran|Sande von Ulduran]]. Er hat sowohl Kurz-, als auch Fernangriffe. Mit diesem sollen Spieler und Gebäude aus der Entfernung bombardiert werden. Er ist aber auch mit einem Rammbock ausgestattet. Er kann bis zu 3 Personen mitnehmen. Alle Personen können einzeln angegriffen werden. Sie können aber auch Zauber wirken.",},
			["Damsel's Luck"] = { content = "Die \"'''Damsel's Luck'''\" ist ein Schiff aus der Flotte der [[Blutsegelbukaniere]], das bei [[Firallons Ankerplatz]] im [[Schlingendorntal]] vertaut ist. Hier findet man die Führungskräfte der Blutsegler unter dem Kommando von [[Flottenmeister Firallon]].",},
			["Danath Trollbann"] = { content = "#REDIRECT [[Truppenkommandant Danath Trollbann]]", redirect = "Truppenkommandant Danath Trollbann",},
			["Dar'Khan Drathir"] = { content = "==Allgemeines==\r\nDer verhasste Verräter, Dar'Khan Drathir, hat innerhalb der [[Geißel]] große Macht erlangt. Seine Gefolgschaft steht an der Spitze gigantischer Heere, die gegen die schwindenden Streitkräfte der [[Blutelfen]] zu Felde ziehen. Masophet der Schwarze, Jurion der Betrüger, Borgoth der Blutvergießer, Mirdoran der Gefallene. Diese Männer sind einzig Dar'Khan gegenüber verantwortlich. Die Magister der [[Blutelfen]] und die [[Weltenwanderer]] mögen nicht immer einer Meinung sein, doch wenn es um Dar'Khan geht, stimmen alle überein, dass sie gemeinsam einen Weg finden müssen, um ihn und seine Legionen zu besiegen. \r\n==Charakter==\r\nDar'Khans Seele scheint erfüllt von Hass und Verachtung für sein eigenes Volk. Das ganze Ausmaß seiner Machenschaften und Intrigen wird in seinem Tagebuch ausführlich beschrieben. Er ist ein geschickter Gegner und er beobachtet jeden einzelnen der Schritte der [[Blutelfen]]. \r\n==Geschichte==\r\nMan sagt, Dar'Khan Drathir sei von den Toten wiederauferstanden, um über die Armeen der [[Geißel]] in den [[Geisterlande]]n zu herrschen. Schon vor langer Zeit hatte er sich mit der Geißel eingelassen... damals war er noch ein lebender, atmender Elf. \r\nDar'Khan versprach der [[Geißel]] zwei mächtige elfische Artefakte: Den Stein des Lichts und den Stein der Flamme. Beide waren durchdrungen von den magischen Energien des [[Sonnenbrunnen]]s und verfügten über mächtige Schutzkräfte gegen die [[Geißel]]. Man plante, die Kristalle zu den heutigen Standorten des heulenden und des blutenden [[Ziggurat]]s, inmitten der [[Todesschneise]], zu transportieren.",},
			["Darnassisch"] = { content = "'''Darnassisch''' ist die Muttersprache der [[Nachtelfen]]. Sie existiert sowohl in geschriebener als auch in gesprochener Form. Wie auch die [[Naga]] stammen die [[Hochelfen]] und [[Blutelfen]] von den Nachtelfen ab und somit ähnelt die Sprache Darnassisch den Sprachen [[Nazjar]] und [[Thalassisch]]. Es gibt allerdings starke ideologische Unterschiede zwischen den Nachtelfen und ihren entfernten Verwandten. Ein Linguist muss also sehr vorsichtig beim Vergleich von Darnassisch und seinen zwei verwandten Sprachen sein. Nachtelfen neigen dazu, solche Vergleiche als Beleidigung aufzufassen.",},
			["Darnassus"] = { content = "Hoch über den Zweigen des großen [[Weltenbaum]]es [[Teldrassil]] liegt die wundersame Stadt '''Darnassus''', die neue Heimat der scheuen [[Nachtelfen]]. [[Druiden]], [[Jäger]], und [[Krieger]] haben sich hier zwischen den kunstvollen Holzbauten und sorgfältig gepflegten Hainen gleichermaßen niedergelassen. Der Tempel des Mondes erhebt sich wie ein leuchtendes Signalfeuer über die Kronen der Bäume, flankiert von den Kolonnaden der Hallen der Gerechtigkeit, wo die immer wachsamen Sentinels sich sammeln um das Land zu beschützen. Unter [[Tyrande|Tyrande Wisperwinds]] weiser Führung hat sich Darnassus als ruhiges Zeugnis all dessen hervorgetan, was den [[Nachtelfen]] heilig ist. Die fallenden Blätter, die in der Stille der ewigen Schatten unter dem fernen Laubdach zu Boden segeln, dämpfen die Schritte der Bewohner von Darnassus, während sie über die eleganten, typisch [[Nachtelfen|nachtelfischen]] Brücken ihrer Stadt wandeln. \r\n===Enklave des Cenarius===\r\n* [[Fandral Hirschhaupt]]\r\n===Tempel des Mondes===\r\nDer himmlische Tempel des Mondes, ein erstaunliches Wunder nachtelfischer Handwerkskunst, erhebt sich über die Baumgrenzen und wird von einem Meditationshain ergänzt, den die [[Druiden]] sorgfältigst angelegt haben. Er überstrahlt die Wipfel der Bäume und wird von den Kolonnaden der Halle der Gerechtigkeit eingerahmt, in der sich die wachsamen [[Jäger]] versammeln, um für die Sicherheit des Landes zu sorgen. Hier findet man auch den Portalpunkt. Am zentralen Brunnen im Tempel kann man Opfergaben niederlegen. Die heiligen Wasser werden auch Verderbnis läutern und säubern.\r\n* [[Tyrande Wisperwind]]\r\n===Tempelgärten===\r\nHier befinden sich die Bank und der Briefkasten. Die dortige Bank ist in einen Baum gebaut, welcher als der Baum der Ewigen bekannt ist, der aber wie ein Bär aussieht. \r\n===Terrasse der Handwerker===\r\nHier befindet sich das Auktionshaus. Auf den Terassen der Handwerker findet man Lehrer für alle Berufe, Verkäufer der entsprechenden Handwerkswaren und das Gasthaus von Darnassus. Das Handelsviertel, in dem die Völker der [[Allianz]] um Waren und Dienste feilschen, wird durch geschäftiges Treiben belebt.",},
			["Darroheim"] = { content = "Darroheim ist ein Dorf in den östlichen Königreichen, eingebettet in die südlichen Hügel dessen, was heutzutage [[Östliche Pestländer]] genannt wird. Darroheim liegt im Osten, hinter [[Gahrrons Trauerfeld]]. Viele der Verteidiger fielen in der [[Schlacht von Darroheim]] und viele ziehen erneut umher als grässliche Diener der [[Geißel]]. Die Zerstörung ihrer Formen wird ihre Seelen befreien.\r\n==Personen==\r\n* '''Hauptmann Joseph Rotpfad''' - Die Seele von Hauptmann Joseph Rotpfad wurde von der [[Geißel]] verdreht und er wurde zu einem Monster. Sein Körper ist nicht dort, da er vor Jahren zertrampelt und zerschmettert wurde, aber unter dem Denkmal auf dem Friedhof bei [[Uthers Grabmal]] liegt sein Ehering. Nach seinem Verrat wurde sein Schild zerschmettert und weggeworfen und liegt nun am unwahrscheinlichsten aller Orte - in der Nähe von [[Gahrrons Trauerfeld]].\r\n* '''Horgus der Verheerer''' - Der [[Ghul]]lord Horgus der Verheerer wurde von Kräften der [[Allianz]] während der [[Schlacht um Darroheim]] vernichtet. Seine Leiche wurde in einen See geworfen, nordwestlich von [[Corins Kreuzung]], und sein Schädel ist noch dort.\r\n* '''[[Pamela Rotpfad]]'''",},
			["Darrowehr"] = { content = "Die Insel '''Caer Darrow''' liegt inmitten des [[Darrowmeresee]]s in den [[Westliche Pestländer|Westlichen Pestländern]]. Hier befindet sich der Eingang zur [[Scholomance]].\r\nEinst war diese Insel ein entlegener Außenposten des Elfenreiches [[Quel'Thalas]]. Der sogenannte „Runenfels von Caer Darrow“ befand sich dort - ein aus alter Zeit stammender Monolith, der von einigen [[Druiden]] erschaffen und mit Inschriften mächtiger Zaubersprüche versehen worden war. Er gehörte zu den [[Runensteine]]n, die [[Quel'Thalas]] durch eine magische Barriere maskierten. Dieser unsichtbare Schutzwall sollte die [[Brennende Legion]] daran hindern, Magie innerhalb der Grenzen des Elfenreiches aufzuspüren. Bevor die [[Orcs]] während des Zweiten Krieges [[Quel'Thalas]] verwüsteten, zerstörten sie die Zitadelle von Caer Darrow und entwendeten den heiligen Runenfels. \r\nAls [[Uther Lichtbringer]] nach Caer Darrow gelangte, wurden seine Truppen von [[Orcs]] und abtrünnigen [[Alterac]]-Soldaten angegriffen. Einige Soldaten konnten festgenommen und nach [[Stratholme]] gebracht werden, um sie später in [[Lordaeron]] zu verhören. Es stellte sich heraus, dass Lord [[Perenolde]], der Herrscher der Nation [[Alterac]], seit Anbeginn des Krieges gemeinsame Sache mit der Orkischen Horde gemacht hatte.\r\n==Personen==\r\n* '''Grafiker Renfray''' malte ein Porträt von [[Tirion Fordring]] und seiner Familie.\r\n* '''Magistrat Marduk''' benötigt, um ein Artefakt zu erschaffen, das den Lich [[Ras Frostraunen]] wieder in einen Sterblichen zurückverwandeln kann, ein Andenken aus seinen Jahren unter den Lebenden. \r\n* '''Magnus Frostwake''' ist ein Anbieter spezieller Waren. Das Problem ist, daß er unter normalen Umständen nicht sichtbar ist. Um ihn ansprechen zu können, muß man die \"Spektrale Essenz\" verwenden.",},
			["Darrowmeresee"] = { content = "Der '''Darrowmeresee''' ist ein von der Seuche verpestetes Gewässer im Südosten der [[Westlichen Pestländer]]. In seiner Mitte befindet sich die Insel [[Darrowehr]] mit der [[Scholomance]].",},
			["Das Konsortium"] = { content = "Angeführt von [[Nexusprinz Hamarad]], ist das Konsortium ein lose verbundenes Kartell von Schmugglern, Händlern und Dieben, die in die [[Scherbenwelt]] gekommen sind, um von ihren Reichtümern zu profitieren. \r\n==Stützpunkte==\r\nInzwischen existieren mehrere Stützpunkte in der ganzen [[Scherbenwelt]]. \r\n===Nagrand===\r\nIhr Camp in [[Nagrand]], südlich des Sonnenwindpostens, hat den Auftrag erhalten, die arkanen Schätze von [[Oshu'gun]] auszubeuten und dabei auch die Hilfe freier Abenteurer in Anspruch zu nehmen - selbstverständlich gegen Bezahlung. \r\n===Auchindoun===\r\nWeiterhin plant das Konsortium, die Ruinen des uralten [[Auchindoun]] in der Knochenwüste südlich des [[Wälder von Terrokar|Terrorkarwaldes]] zu erforschen, dieser Plan wurde jedoch von unvorhergesehenen Problemen aufgehalten. Abenteurer, die vorhaben, sich in die [[Managruft]] von [[Auchindoun]] zu wagen, tun gut daran, vorher mit den Repräsentanten des Konsortiums vor dem Eingang zu sprechen. \r\n===Nethersturm===\r\nDie wichtigste Niederlassung des Konsortiums aber befindet sich in den zerstörten Gebieten des [[Nethersturms]]. Das Konsortium ist zu Recht stolz auf seine Technologie der [[Biokuppeln]], deren schützende Energiefelder den ätherischen Arbeitern eine kontrollierte und lebenserhaltende Atmosphäre bieten. Letztlich traten jedoch vermehrt technische Probleme in Zusammenhang mit den [[Biokuppeln]] im [[Nethersturm]] auf und das Konsortium wartet auf Hilfe von außerhalb, um die Situation zu stabilisieren.\r\n==Feinde==\r\nZusätzlich hat eine feindliche Gruppe von Ätherischen, das [[Astraleum]], einen Stützpunkt nahe der [[Sturmsäule]], der Basis des Konsortiums, errichtet. Das Konsortium sowie das [[Protektorat]], eine dritte Gruppe von Ätherischen, sehen im destruktiven Verhalten des [[Astraleum]]s eine Bedrohung. Außerdem bedeutet die Anwesenheit von [[Nexuskönig Salhadaar]], dass [[Dimensius]], der urzeitliche Feind der Ätherischen, nah sein muss. \r\n==Schätze==\r\nDas Konsortium verfügt über Zugang zu einigen exotischen Schätzen und Artefakten. So können sie wohl jedem Abenteurer eine geeignete Belohnung für seine Mühen anbieten. Helden, die von [[Nexusprinz Haramad]] für würdig empfunden werden, erhalten ihren Anteil am Reichtum des Konsortiums... für einen gewissen Preis. Nethersplitter sind für [[Allianz]] und [[Horde]] gegen Einlösung von Ehrenpunkten verfügbar. \r\n'''Quelle''':",},
			["Das Mondfest"] = { content = "* '''Typ''': Festtagsereignis\r\n* '''Datum''': 05. Februar - 23. Februar\r\n* '''Örtlichkeiten''': Mondlichtung, Hauptstädte und ausgewählte Orte auf ganz Azeroth \r\n==Kurzinformation==\r\nJedes Jahr veranstalten die Druiden von Mondlichtung im Andenken an den Sieg über ein uraltes Übel ein beeindruckendes Fest. Während des Mondfestes haben die Bewohner Azeroths die Gelegenheit, auf vielerlei Weise ihre Ahnen zu ehren – indem sie ihrer Weisheit huldigen, indem sie den Vorfahren zu Ehren großartige Festmale veranstalten, und natürlich... Feuerwerk! \r\n===Besucht die Ahnen===\r\nWährend des Mondfestes haben Abenteurer die Gelegenheit, ihre Ahnen zu ehren, und somit natürlich auch ihre Kultur und ihr eigenes Volk. Mit den mysteriösen Münzen der Urahnen können Abenteurer beweisen, dass sie dem ehrwürdigen Weg des Respekts folgen. An 50 Orten in ganz Azeroth halten sich diese Urahnen auf - teils in den Hauptstädten wie Orgrimmar oder Stormwind, teils in kleinerern Dörfern wie dem Wegkreuz und neutralen Ortschaften wie Ratschet, aber auch in Gebieten die ihr nur gemeinsam mit tapferen Gefährten erreichen könnnt. Diejenigen, die sich dadurch auszeichnen, dass sie viele dieser Münzen sammeln konnten, werden für ihre Tugendhaftigkeit mit vielen verschiedenen Gegenständen - etwa besonderen Festagsanzügen und -kleidern, aber auch leckeren Spezialitäten wie den Festagsklössen, belohnt.\r\n===Besiegt Omen===\r\nAuch wenn der einst edle und starke Omen, der von der brennenden Legion korumpiert wurde, einst von wackeren Helden - und dem Mondlicht in die Flucht geschlagen wurde und seither am Grund des Elune’arasees verweilt, findet er keine Ruhe. Einmal, wenn das Licht des Mondes unheilvolle Schatten am Grunde des Sees tanzen lässt, erwacht Omen erneut - und nun liegt es an euch wackeren Streitern aller Völker, seinem Rasen Einhalt zu gebieten und ihn in erneut in die Tiefen des Sees zu verbannen.\r\n===Besorgt euch festliche Kleidung===\r\nPutzt euch heraus, ihr Völker Azeroths! Erweitert eure Garderobe mit besonderen Anzügen und Kleidern! Zeigt euch in den Traditionellen Gewändern des Mondfestes! Nur die feinsten Stoffe und erlesensten Materialien sind gut genug für diesen festlichen Anlass!\r\n===Benutzt Feuerwerk===\r\nDie Goblins haben an vielen der Orte an denen auch die Urahnen stehen, Abschussgelegenheiten für Feuerwerk installiert, auf dass mit ihren besonderen Kreationen - und denen von findigen Ingenieuren - der Nachthimmel in bunten Farben erleuchtet werde. Jeder der möchte, kann diese Abschussrampen nützen und sich an dem Farbenspiel erfreuen. Man munkelt dass die Goblins selbst sich etwas ganz besonderes für den Höhepunkt der Feier überlegt haben.\r\n==Geschichte==\r\nDas Mondfest ist in ganz Azeroth eine Zeit des Feierns und des Gedenkens. Die Völker Azeroths feiern während des Mondfestes ein schon Jahrtausende zurückliegendes Ereignis. Vor langer, langer Zeit schlossen sich die Völker der [[Nachtelfen]], [[Tauren]] und der [[Irdenen]] (ein vorzwergisches Volk) zusammen, um gemeinsam die Welt vor einem grausamen Untier zu retten. Das Fest soll auch allen die Tugendhaftigkeit und Weisheit jener fernen Tage in Erinnerung rufen.\r\nDer Halbgott namens Omen war einst ein Wesen von außergewöhnlicher Stärke und Weisheit. Omen durchstreifte von Elune gesegnet das urzeitliche Kalimdor, hielt seine schützende Hand über die ersten Jäger und Sammler und bedachte alle, die ihm auf seinen Reisen begegneten, mit Glück und weisen Ratschlägen. Als die Brennende Legion zum ersten Mal in Azeroth einfiel, kämpfte Omen zusammen mit den Verteidigern Azeroths gegen die Dämonen. Doch obwohl er sich den Eindringlingen tapfer entgegenstellte, versank der einst edle Omen von seinen vielen Wunden geschwächt in einen tiefen, von finsteren Träumen geplagten Schlaf... dessen teuflische Alpträume ihn schließlich verschlangen. Als er jahrhunderte später wieder erwachte, war er vollständig dem Wahnsinn verfallen.\r\nOmen stürzte sich in blinder Wut auf alles und jeden, der sich ihm entgegenstellte. Seine Weisheit hatte ihn verlassen, doch die Stärke von Elunes Segen war ihm erhalten geblieben, und so verwüstete er das Land, mordend und unaufhaltsam. Angst und Schrecken waren seine Vorboten, Tod und Verwüstung sein Gefolge.\r\nOmens schrecklicher Amoklauf fand ein Ende, als sich eine Gruppe furchtloser Helden in Nachthafen zusammenfand und sich der Bestie entgegenstellte. Gemeinsam beschworen sie den Zorn des Mondes, und Omen, geblendet von der Macht der Mondgöttin, floh in die Tiefen des Elune’arasees. Jener Tag war das Ende von Omens Schreckensherrschaft und der Beginn eines neuen Zeitalters für die Völker Azeroths und die Anhänger von Elune.\r\nHeute wird das Mondfest der Druiden Nachthafens gefeiert. Sowohl die Allianz als auch die Horde feiern diesen Tag mit ausgiebigen Feuerwerken als Symbol der Macht von Elune. Uralte Helden der Vergangenheit erscheinen im ganzen Land und bieten all jenen Geschenke, die sie aufsuchen und ihnen Ehre erweisen.\r\nEs ist eine Zeit der Freude, des Glücks und ausgelassenen Feierns, doch es gibt auch einen anderen, wenig bekannten Grund für das Fest...\r\nZwar wurde Omen damals besiegt, doch vernichtet wurde er nicht. Auch wenn er von den Alpträumen der Brennenden Legion in den Wahnsinn getrieben wurde, besitzt der Halbgott immer noch den Segen von Elune und ist daher unsterblich. Während des Mondfestes erwacht Omen... und es liegt erneut an den Helden aller Völker, das Monster in seine Schranken zu weisen. \r\n'''Quelle''':",},
			["Das Scharlachrote Kloster"] = { content = "Das '''Scharlachrote Kloster''' befindet sich im Norden von [[Tirisfal]] und ist für Angehörige der [[Horde]] leicht von [[Unterstadt]] aus zu erreichen. Abenteurer der [[Allianz]] müssen sich auf einen langen Weg von [[Süderstade]] aus gefasst machen.\r\n==Allgemeines==\r\nDas Kloster war einst der ganze Stolz der Priesterschaft von [[Lordaeron]], ein Ort der Studien und der Erleuchtung. Doch seit dem Auftauchen der untoten [[Geißel]] während des Dritten Krieges wurde das friedliche Kloster in eine Festung des fanatischen [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzuges]] verwandelt. Die Kreuzritter zeigen gegenüber allen nichtmenschlichen Völkern nicht den geringsten Funken von Toleranz oder Achtung, egal auf welcher Seite sie stehen mögen. Sie glauben, dass alle Außenseiter potentielle Überträger der Seuche des Untodes sind und deswegen vernichtet werden müssen. Berichten Überlebender zufolge müssen sich Eindringlinge darauf gefasst machen, dem [[Scharlachroter Kommandant Mograine|Scharlachroten Kommandanten Mograine]] entgegenzutreten, der zudem über eine große Streitmacht ihm fanatisch ergebener Krieger gebietet. Der wahre Herr über das Scharlachrote Kloster ist jedoch [[Hochinquisitorin Weißsträhne]] – eine furchteinflößende Priesterin, die über die einzigartige Gabe verfügt, gefallene Kämpfer in ihrem Namen ins Kampfgeschehen zurückholen zu können. \r\n==Teilbereiche==\r\nDas Kloster besteht aus vier kleinen Bereichen, die sich wie folgt aufteilen: Der Friedhof, Die Bibliothek, Die Waffenkammer und Die Kapelle.\r\n===Bibliothek===\r\nBevor [[Lordaeron]] von all diesen schrecklichen Dingen heimgesucht wurde, war die Bibliothek des Klosters eine Bastion des Wissens, die in [[Tirisfal]] versteckt lag. Hier steht ein Buch mit dem Titel \"[[Die Anfänge der Bedrohung durch die Untoten]]\". Es wurde von den jetzt verderbten Paladinen benutzt, um sie in seiner Art des Kampfes auszubilden. Tief im Inneren des Scharlachroten Klosters liegt auch das \"[[Kompendium der Gefallenen]]\" und ein Buch mit dem Titel \"[[Mythologie der Titanen]]\" verborgen, das von irren menschlichen Zeloten bewacht wird. \r\n* [[Arkanist Doan]]\r\n* [[Hundemeister Loksey]]\r\n===Friedhof===\r\nIm unglückseligen Kreuzgang des Friedhofes treiben sich viele Geister herum. \r\n* [[Azshir der Schlaflose]]\r\n* [[Befrager Vishas]]\r\n* [[Blutmagier Thalnos]]\r\n* [[Der kopflose Reiter]] (nur während der [[Schlotternächte]])\r\n* [[Eisenrücken]]\r\n* [[Gestürzter Held]]\r\n* [[Scorn]] - Ein Lich auf dem Friedhof des Klosters während der [[Invasion der Geißel]].\r\n* [[Vorrel Sengutz]]\r\n===Kathedrale===\r\n* [[Hochinquisitorin Weißsträhne]]\r\n* [[Hochinquisitor Schönufer]]\r\n* [[Scharlachroter Kommandant Mograine]]\r\n===Waffenkammer===\r\n* [[Herod]], der scharlachrote Held",},
			["Das Verlies"] = { content = "Lange Zeit war es ruhig im Verlies von [[Sturmwind]], doch nun ist der Terror hinter den Gittern ausgebrochen. Die Gefangenen haben sich befreit und das Kommando über die Gewölbe übernommen. \r\nDas Verlies ist ein politisches Hochsicherheitsgefängnis der Menschen, das unter dem Kanalbezirk von [[Sturmwind]] verborgen liegt. Mitten in der Hauptstadt gelegen, sind fast ausschließlich Verbrecher der [[Defias]]-Organisation einquartiert. Unter der Führung von Wärter Thelwater sammelten sich im Verlies mit der Zeit ein bunter Haufen simpler Gauner, politischer Aufrührer, Mörder, Diebe, Halsabschneider und einiger der gefährlichsten Kriminellen des Landes an. Vor kurzem gab es einen Aufstand der Gefangenen, der im Verlies für Chaos sorgte – die Wachen sind geflohen und die Gefangenen haben das Gefängnis übernommen. Thelwater konnte knapp entkommen und sucht momentan nach tapferen Abenteurern, um den Anführer der Revolte auszuschalten, den gerissenen Meisterverbrecher [[Bazil Thredd]].\r\nWenn jemand mitbekommt, dass das Gefängnis überrannt wurde, verliert Aufseher Thelwasser seinen Job. \r\nDie Verstrickungen in allerlei Verbrechen haben [[Menschen]] in vielen Regionen gegen bestimmte, nun einsitzende Täter so aufgebracht, daß sie mehr wollen, nämlich den jeweiligen Kopf: So eine Ortswache in [[Seenhain]], einen Rat in [[Dunkelhain]] und einen Gardisten bei [[Dun Modr]]. \r\n==Personen==\r\n* [[Bazil Thredd]]\r\n* [[Dextren Ward]]\r\n* Hamhock ist ein eingesperrter ein Oger. Wieso er hier sitzt, ist unbekannt.\r\n* [[Kam Tiefenzorn]] \r\n* Mac war gerade mal 14 Jahre alt. Als die Armee an die Front geschickt wurde, griff Mac zu den Waffen, um die Stadt zu verteidigen. Er war eine Wache im Verlies, wo die [[Defias]] eingesperrt sind. Mac wies ein paar der Gefangenen dafür zurecht, dass sie ihre Wolldecken zerrissen, um Schals daraus zu machen, die ein Symbol ihrer Bande darstellen. Dafür wurde Mac hinterhältig erstochen.\r\n* [[Targorr der Schreckliche]]",},
			["Dath'Remar"] = { content = "#REDIRECT [[Dath'Remar Sonnenwanderer]]", redirect = "Dath'Remar Sonnenwanderer",},
			["Dath'Remar Sonnenwanderer"] = { content = "==Allgemeines==\r\nDer Hochgeborene Dath'Remar Sonnenwanderer gehörte zu den wenigen Elfen am Hofe [[Königin Azshara]]s, die es wagten, gegen die Beschwörung der Legion zu protestieren. Mit Gleichgesinnten versuchte er sogar, die Arbeit der Hochgeborenen und der Legion zu sabotieren. Er verhalf sogar [[Tyrande Wisperwind]] zur Flucht aus dem Kerker Azsharas. Dath'remar wurde nach dem Krieg für sein Engagement geehrt und wurde einer der Führer der neuen Nachtelfen. Dass sie aller arkaner Magie entsagten und sich stattdessen dem Druidentum zuwandten erzürnte Death'ramar jedoch. Sein Versuch, die Druiden von ihrem Fehler zu überzeugen gipfelte in dem schon erwähnten magischen Sturm über dem Eschental und der folgenden Verbannung der Hochgeborenen.Er trug das Runenschwert [[Feuerstreich]].\r\nEr führte sein Volk im Exodus durch den Mahlstrom von [[Kalimdor]] nach [[Quel'Thalas]]. Unter seiner Führung erblühte Quel'Thalas und die Hauptstadt Silbermond und er wurde der erste König von [[Quel'Thalas]]. \r\nEr gehörte zu den reichen und mächtigen [[Hochgeborene]]n. Sein Familienname war alt und angesehen, wurde jedoch immer als etwas merkwürdig betrachtet. Immerhin bedeutete er „Der durch den Tag streift“, und die [[Nachtelfen]] waren von Natur aus ein nachtaktives Volk, das die Mondgöttin [[Elune]] verehrte. Selbst sein Aussehen war merkwürdig, denn sein kastanienbraunes Haar war von goldenen Strähnen durchzogen. Sein berüchtigter weil aktuell sehr böser Nachfahre ist [[Kael'thas]]. Dath'remar lebte sehr lange und erlebte die Zerstörung Silbermonds durch die untote Geißel mit, obwohl er nicht mehr König war. Laut dem Schrein auf der Insel der Sonnenwanderer „opferte“ sich Dath'remar in diesem Krieg für das Elfenreich. \r\n==Schrein von Dath'Remar==\r\nBei einer genaueren Untersuchung des Schreins von Dath'Remar auf der [[Insel der Sonnenwanderer]] im [[Immersangwald]] verspürt man eine starke Präsenz der seltsamen Kraft, welche die gesamte Insel in ihrem eiskalten Griff hält. So nahe am Schrein beginnt man sich unwohl zu fühlen ... ein Gefühl der Unsicherheit beschleicht einen. Auf der bronzenen Platte an Rande des Schreins sieht man eine Inschrift: \r\n''\"Dies ist der Schrein von Dath'Remar, ein würdiger Tribut für einen noblen Elfen. Mögen alle, die dieses Monument erblicken sich daran erinnern, mit welcher Hingabe er sein Leben im Kampf gegen die [[Geißel]] opferte, um unser aller Überleben zu sichern. Alles, was in [[Quel'Thalas]] lebt und gedeiht verdankt seine Existenz diesem Mann.\"''",},
			["Definition des Voodoo aus der Sicht eines Menschen"] = { content = "… ist es somit von unerlässlicher Bedeutung, dass jegliche schwarzmagischen Aktivitäten im Keime erstickt und mit der Flamme der Rechtschaffenheit ausgelöscht werden. \r\nInsbesondere der als sogenannter „[[Voodoo]]“ verschriene finstere Zauber der Schamanen und Scharlatane der heimtückischen [[Darkspear]]-[[Trolle]] soll im folgenden kurz erläutert werden, um den aufrechten Gläubigen aufzuklären und gegen mögliche Gefahren zu wappnen. \r\nDas Götterverständnis der Trolle ist von vielerlei Mysterien und absonderlicher, recht bizarr anmutender Rituale gekennzeichnet. Zudem erscheinen dem aufgeklärten Forscher jederlei Gottheit der Trolle als geradezu lächerliche Nachbildung all jener Kreaturen, vor denen sich kulturschaffende Rassen seit alters her fürchten. \r\nBeispielsweise verehren jene Heiden die wilden Tiere und Bestien des Dschungels, darunter den Raptor, Tiger, Panther und vielerlei mehr. Diese werden von verschiedenen Stämmen und Fraktionen unter allerlei Pseudonymen angebetet und mit Blut-Opfern gehuldigt. \r\nDas „Voodoo“ der Trolle ist eine verruchte Mischung aus Blut-Ritualen, Kannibalismus, schwarzer Magie und einfacher Scharlatanerie. Soweit bekannt dient sie vor allem dazu, andere Stämme oder einzelne Personen mit Flüchen und böser Magie zu belegen, um diese zu schwächen oder zu töten. Selten auch, um mit den primitiven Göttern und Geistern zu reden, oder die Vorfahren der Trolle zu kontaktieren. \r\nDie sich ständig in gegenseitiger Blutfehde und Bürgerkrieg befindlichen Stämme nutzen jedoch meist den schädlichen Einfluss des Voodoo, um sich anderen Stammesoberhäuptern zu entledigen, lästige eigene Mitglieder loszuwerden, oder einfach, um den eigenen Einfluss zu stärken und ihre Macht zu demonstrieren. \r\nFür die verschiedenen Rituale benötigen sie jedoch immer allerlei Ingredienzen und Paraphernalia, um die Macht des Zaubers zu verstärken. Es scheint unumlässlich für den Zauberer, über ein persönliches Besitzstück des zu Verfluchenden zu verfügen. Noch besser scheinen sich jedoch die Körperteile des Fluchopfers für den Zauber zu eignen (z.B. ein Finger, einige Haarbüschel, etwas von dem Blut des Opfers, oder im Notfall auch ein Zehennagel). Die archaisch anmutenden Ritual-Techniken sind trotz ihrer offenkundigen Lächerlichkeit zum Teil von großer Macht und dementsprechend gefährlich für jeden, der in sie verwickelt oder gar von ihnen betroffen ist. \r\nIm Folgenden wird darauf hingewiesen, was im Falle einer Begegnung oder Entdeckung eines solchen Rituals, Zaubers oder Fluchs zu unternehmen ist: \r\nAd primo: Wird ein Gläubiger Zeuge eines heidnischen Rituals ist er in jedem Fall verpflichtet, dies zu verhindern versuchen. Sei es, dass er selbst und sofort einschreitet, oder aber rasche Hilfe durch die heilige Inquisition anfordert. \r\nAd secundo: Ein jeder Teilnehmer von Voodoo-Aktivitäten ist umgehend zu töten und seine körperlichen Überbleibsel sind dem reinigenden Feuer der Gerechtigkeit zu übergeben. Der Staub wiederum ist in alle Himmelsrichtungen zu zerstreuen, im Meer zu versenken oder in einem versiegelten Gefäß aufbewahrt zu werden. \r\nAd tertio: Es sind immer und überall folgende Vorsichtsmaßnahmen zu wahren, um nicht selbst dem finsteren Zauber anheim zu fallen. \r\nDer Gläubige hat Handschuhe zu tragen und ist in jedem Fall aufgefordert, niemals direkten Körperkontakt zu einem der Delinquenten – ob tot oder lebendig – aufzunehmen. \r\nDer Gläubige soll sich durch fortwährendes geistiges Training dazu in die Lage versetzen, den Heiden in einem Zustand der gesegneten Trance zu begegnen, um nicht durch finstere Hexerei korrumpiert zu werden. \r\nDer Gläubige soll folgende Gegenstände zur Reinigung des entweihten Bodens und zum eigenen Schutze bei sich führen: \r\n* Heiliges Wasser aus den Kirchen, um den Boden und evtl. infizierte Körperteile zu reinigen \r\n* gesegnete Kerzen, um das heilige Licht des Lebens am Ort des Bösen zu entzünden \r\n* ein vom Inquisitor oder Priester geweihtes Schwert, um die Ritualteilnehmer ihrer gerechten Strafe zu übergeben \r\nDesweiteren wird jeder Gläubige angehalten, im Falle einer Verfluchung eines Kameraden und Glaubensbruders, diesen trotz möglicherweise aufwallender persönlicher Emotionen, in jedem Fall und auf der Stelle zu töten, um eine Ausbreitung des… \r\n''Auszug aus dem „Edikt zu den unheiligen Ritualen fremder Kulturen“, vierte Auflage, [[Sturmwind]], verfasst von Hochinquisitor [[Reimund von Darnassus]]''",},
			["Dejahna"] = { content = "'''Hohepriesterin Dejahna''' war eine [[Nachtelfen Mondpriester]]in und gehörte zum Kaldorei Widerstand. Als Hohepriesterin von [[Elune]] war sie die erste religiöse Führerin der [[Schwestern von Elune]] vor dem [[Krieg der Uralten]]. Als [[Mannoroth]] und [[Xavius]] den [[Brunnen der Ewigkeit]] gegen äußeres Eingreifen verschlossen, machte die Hohepriesterin die Schwesternschaft schnell zur hauptsächlichen Basis der Kommunikation, da ihre Telepathie von der Göttin und nicht aus dem Brunnen kam. Die Hohepriesterin war eine zuverlässige Unterstützerin von Fürst [[Kur'talos Rabenkrone]]. Sie kämpfte an der Seite der anderen Nachtelfen, als der Dämon [[Hakkar der Hundemeister]] auf dem Schlachtfeld ihr eine Lanze in den Bauch stieß und ein [[Teufelshund]] den größten Teil ihrer Magie absorbierte. So starb sie trotz ihrer gewaltigen Heilkräfte an ihrer Verletzung. Ihre letzte Handlung war es, ihre Nachfolgerin zu ernennen, eine die mit dem Licht der Göttin erfüllt war: [[Tyrande Wisperwind]].",},
			["Dentarg"] = { content = "Dentarg war ein zweiköpfiger [[Oger]]magier und tapferer Diener von [[Ner'zhul]] und des [[Schattenmond Klan]]s. Man nahm ihn für das zusammentreiben der ungehorsamen Klans im Krieg in Anspruch. Er wurde ebenfalls beauftragt die Klans von der absoluten Autorität [[Ner'zhul]]s zu überzeugen. Vielleicht hatte er es geschafft seinem Meister am ende des [[Der Dritte Krieg|Dritten Krieges]] durch das Tor zu folgen, niemand weiß es.",},
			["Der aufstrebende Verräter"] = { content = "'''Quelle:'''\r\n==Inhalt==\r\nAls die Legion Eschental erstürmte, wurde [[Illidan]] von Tyrande aus seinem Gefängnis im Grabhügel befreit, wo er zehntausend Jahre in Gefangenschaft verbracht hatte. Zunächst versuchte er zwar, den Wünschen seiner Begleiter zu entsprechen, nahm jedoch alsbald seine wahre Gestalt wieder an und verleibte sich die Energie eines mächtigen Hexenmeisterartefakts ein, dem „[[Schädel des Gul'dan]]“. Damit entwickelte Illidan dämonische Eigenschaften und eine dramatisch höhere Macht. Überdies wurden ihm ein Teil von Gul'dans alten Erinnerungen zuteil – speziell die an das [[Grabmal von Sargeras]], dem Insel-Dungeon, wo sich Gerüchten zufolge die Überreste des dunklen Titanen [[Sargeras]] befinden sollten. Illidan, der vor Macht brodelte und wieder frei durch die Welt streifen konnte, suchte nach seinem eigenen Platz im Plan des Lebens. \r\nDoch dann wandte sich [[Kil'jaeden]] an Illidan und machte ihm ein Angebot, das er nicht ausschlagen konnte. Kil'jaeden war zwar wütend über [[Archimonde]]s Niederlage am Berg [[Hyjal]], doch stand sein Rachdurst hinter wichtigeren Dingen an. Kil'jaeden spürte, dass der [[Lichkönig]], seine eigene Schöpfung, so mächtig wurde, dass er ihn nicht mehr kontrollieren konnte, und befahl Illidan, [[Ner'zhul]] zu vernichten und der [[Geißel]] der Untoten ein für alle Male ein Ende zu machen. Als Gegenleistung sollte Illidan unerhörte Macht und einen gleichberechtigten Platz unter den verbliebenen Lords der Brennenden Legion erhalten.\r\nIllidan willigte ein und machte sich unverzüglich daran, den [[Frostthron]] zu zerstören, jenen eisigen Kristallsarg, in dem der Geist des Lichkönigs residierte. Illidan wusste, er würde ein mächtiges Artefakt benötigen, um den Frost-Thron zu vernichten. So nutzte er das Wissen, das ihm aus Gul'dans Erinnerungen zuteil geworden war, um das Grabmal von Sargeras zu suchen und sich die Überreste des dunklen Titanen zu sichern. Er forderte einige alte Schulden bei den [[Hochgeborene]]n ein und rief die Naga aus ihren dunklen unterseeischen Unterschlupfen. Angeführt von der verschlagenen Meerhexe [[Lady Vashj]] halfen die Naga Illidan, zu den verheerten Inseln vorzustoßen, wo sich das Grabmal von Sargeras angeblich befinden sollte. \r\nAls Illidan mit den Naga aufbrach, eröffnete Aufseherin [[Maiev Schattensang]] die Jagd auf ihn. Maiev war zehntausend Jahre lang Illidans Kerkermeisterin gewesen und berauschte sich an der Aussicht, ihn wieder zu fassen zu bekommen. Doch Illidan überlistete Maiev und ihre Behüter und konnte das [[Auge von Sargeras]] all ihren Bemühungen zum Trotz erobern. \r\nNachdem er das mächtige Auge in seinem Besitz hatte, begab sich Illidan zur einstigen Hexerstadt [[Dalaran]]. Illidan, dem die [[Ley]]-Energielinien der Stadt zusätzliche Kraft spendeten, benutzte das Auge für einen zerstörerischen Zauber gegen [[Eiskrone]], die Zitadelle des Lichkönigs im fernen [[Nordend]]. Illidans Angriff zerschmetterte die Verteidigung des Lich-Königs und riss das Dach der Welt entzwei. Erst im letzten Augenblick wurde Illidans zerstörerischer Zauber gestoppt, als sein Bruder [[Malfurion Sturmgrimm]] und Priesterin [[Tyrande Wisperwind]] eintrafen und Maiev unterstützten.\r\nIllidan wusste wohl, dass Kil’jaeden höchst unzufrieden sein würde ob seines Versagens, und floh in die öde Dimension, die als das [[Scherbenwelt]] bekannt ist: die letzten Überreste von Draenor, der einstigen Heimat der Orcs. Er hatte die Absicht, Kil’jaedens Zorn auf diese Weise zu entgehen und sein weiteres Vorgehen zu planen. Nachdem Tyrande und Malfurion Illidan erfolgreich aufgehalten hatten, kehrten sie nach [[Eschental]] zurück, um über ihr Volk zu wachen. Maiev indessen wollte nicht so einfach aufgeben und folgte Illidan in die Scherbenwelt, fest entschlossen, ihn der Gerechtigkeit zu übergeben.",},
			["Der Blaue Eremit"] = { content = "Der \"Der Blaue Eremit\" ist eine Taverne im Magierviertel von [[Sturmwind]].\r\n==Bewirtschaftung==\r\n* Am 06.09.07 hat [[Rumpell]] vom [[Institut für Pfuschkunde]] sporadisch die Bewirtschaftung übernommen\r\n* Am 29.07.07 hat [[Sherane]] Ilhandra la Faye von [[Necessitudo]] die Wiedereröffnung übernommen\r\n* Am 22.02.08 hat [[Xestai]] Sparkcutter von [[Necessitudo]] die Wiedereröffnung übernommen\r\n===Magierstammtisch===\r\nDer Magierstammtisch wird hier von der [[Die Magiergilde|Magiergilde]] organisiert. Einige dezente Aushänge und Flugblätter bei Händlern geben folgendes bekannt: \r\nMagierkollegen ganz Azeroths! Ihr seid hiermit zum Magierstammtisch Sturmwinds eingeladen. Jeder Wirker oder Lehrling von Arkaner oder Elementarer Magie ist willkommen, egal ob er in einer Gilde, Gruppierung oder Streitmacht ist. In gelassener Atmosphäre können wir trinken, plaudern, neue Theorien austauschen und dem harten Dasein eines Magiers für kurze Zeit eine Pause gönnen. Seid auch ihr dabei! \r\nDie Magiergilde. \r\n===Wiedereröffnung des Eremiten===\r\nBürger und Gäste Sturmwinds, Ihr seid alle zur Wiedereröffnung des Eremiten eingeladen! Am Freitag dem 22ten Februar werden wir ab der 8ten Abendstunde unsere Tür nach den vielen Wochen wieder für jeden öffnen. Alle trinkfreudigen werden sich über ein großes Sortiment an Getränken mit und ohne Alkohol freuen können. Und wenn Euch dass nicht genug ist, ruft das Motto des Eremitens beim Schlag zur 9ten Abendstunde in den Nachthimmel hinaus sodass es jeder hört, dann werden wir Euer Glas und Krug eine viertel Stunde kostenlos wieder auffüllen! Wir suchen für diesen Abend noch Türsteher und Kellnerinnen. Wollt Ihr Euch pro Stunde zwei Goldmünzen verdienen und denkt Ihr seid fähig dazu? Dann meldet Euch im Eremiten persönlich oder per Brief! Und alle die das Motto des Eremitens nicht kennen, sollten sich dieses gut einprägen ... Hey Ho, trinkt und seid froh. Hebt Euren Wein und stimmt alle mit ein!\r\n==NSC's==\r\n* '''Angus Stern''' – Angus ist der Chefkoch des Blauen Eremiten und entwickelt ein neues Menü für das Restaurant. Es soll aus regionalen Gerichten mit einem Hauch von \"Bayou\" bestehen und er glaubt, seine Kunden im Blauen Eremiten werden es lieben. Er schickte deshalb seinen Neffen [[Morgan Stern]] nach [[Theramore]], der die Rezepte der Einheimischen sammelt und Angus muss wissen, was er bisher gefunden hat. Eines seiner berühmtesten Gerichte ist gekühlter Basilisk an Limonenvinaigrette.\r\n* '''Connor Bach''' – Connor ist Kochlehrling und bevor er hier im Blauen Eremiten arbeitete, wurde er von einem der besten Küchenchefs und Gastwirte ausgebildet. Sein Name war [[James Hyal]]. Alles, was er besitzt und im Leben erreicht hat, verdankt er ihm.",},
			["Der Dritte Krieg"] = { content = "Der Dritte Krieg umfasst die Ereignisse während des zweiten Einfalls der [[Brennende Legion|Brennenden Legion]], die weitestgehende Zerstörung von Allianzterritorium durch die [[Seuche]], die Übersiedlung nach [[Kalimdor]] und die abschließende Schlacht am Berg [[Hyjal]], bei der die Brennende Legion besiegt wurde.\r\n==Chronologie des Krieges auf Kalimdor==\r\n* [[Medivh]]s Geist sieht den unvermeidlichen Untergang [[Lordaeron]]s voraus und beginnt, Maßnahmen zu ergreifen, eine Allianz zwischen den sterblichen Völkern [[Kalimdor]]s zu schmieden. Mysteriöse Visionen, entsendet von Medivh, veranlassen [[Jaina Prachtmeer]] dazu, Schiffe durch den [[Mahlstrom]] zum entfernt gelegenen Kontinent Kalimdor zu entsenden. Auch die [[Horde]] macht sich mit gekaperten Kriegsschiffen auf zu dem westlichen Kontinent.\r\n* [[Kel'Thuzad]] bringt Medivhs Zauberbuch in seinen Besitz und beschwört damit die Brennende Legion. [[Archimonde]] und seine Heerscharen an [[Dämonen]] erscheinen in [[Dalaran]].\r\n* [[Thrall]]s Truppen legen an einer unbekannten Inselkette im Mahlstrom an und begegnen einem friedlichen Stamm von [[Dschungeltrolle]]n. Thrall hilft den Trollen bei der Flucht von ihrer sinkenden Insel. Zum Dank schließen sich die Trolle der Horde an.\r\n* Nachdem der Mahlstrom hinter sich gelassen und Kalimdor erreicht wurde, beginnt die Horde sich neu zu formieren. Die [[Orcs]] stoßen auf ein Volk riesenhafter, weiser Wesen, genannt die [[Tauren]]. Thrall entsendet [[Grom Höllschrei]] mit einer Gruppe von Orcs nach Norden, um Holz zu fällen und zu sammeln.\r\n* Die Tauren führen Thrall zu einem mysteriösen Orakel, welches sich als der Geist Medivhs herausstellt. Medivh macht Thrall mit Jaina Prachtmeer, welche ebenfalls bereits dort ist, bekannt und warnt beide vor der Ankunft der [[Brennende Legion|Brennenden Legion]].\r\n* [[Schildwache]]n der [[Nachtelfen]] reagieren gewaltsam auf das Eindringen und Waldschänden der Orcs in das [[Eschental]]. Die Orcs, geführt von Grom Hollschrei, liefern sich mehrere Kämpfe mit den Nachtelfen. [[Cenarius]] schreitet ein und gebietet dem Vormarsch der Orcs Einhalt.\r\n* [[Mannoroth]] verführt Grom dazu, Dämonenblut aus einem korrumpierten Brunnen zu trinken. Grom und seine Gefolgsleute erhalten dadurch schier unglaubliche Stärke und werden nahezu unverwundbar. Die Orcs schlagen zurück und töten Cenarius.\r\n* Die Nachtelfen erwecken [[Malfurion]] und den Rest der schlafenden [[Druiden]].\r\n* Die Brennende Legion erreicht Eschental und schreitet zum [[Weltenbaum]] und dem von ihm geschützten [[Brunnen der Ewigkeit]].\r\n* [[Tyrande Wisperwind]] befreit [[Illidan]] aus seinem Gefängnis. Illidan verzehrt die Kraft eines dämonischen Artefakts, bekannt als [[Gul’dans Schädel]] und verfolgt und tötet schließlich [[Tichondrius]]. Doch das Artefakt ruft eine irreversible Veränderung in Illidan hervor, welche ihn schließlich in einen Dämonen verwandelt. Er wird daraufhin von Malfurion verstoßen.\r\n* Thralls Orcs und Jainas Menschen schließend schließlich ein gemeinsames Bündnis mit der Absicht, den Berg [[Hyjal]] vor [[Archimonde]]s Vorstößen zu schützen. Doch der Dämonenführer erweist sich als zu mächtig und vernichtet ihre Streitkräfte.\r\n* Die Nachtelfen opfern ihre Unsterblichkeit um die den Weltenbaum mit den Geistern ihrer Vorfahren zu durchtränken. Der Weltenbaum, gestärkt durch diese Opfergabe, entsendet eine Welle purer magischer Energie, welche Archimonde und seine Streitkräfte schließlich auslöscht.\r\n===Die Geißel von Lordaeron===\r\nNach langen Monaten der Vorbereitung riskierten [[Kel'Thuzad]] und sein [[Kult der Verdammten]] den ersten Schlag, indem sie die [[Seuche]] des Untodes in [[Lordaeron]] freisetzten. [[Uther Lichtbringer|Uther]] und die anderen [[Paladine]] untersuchten die infizierten Regionen in der Hoffnung, sie könnten eine Möglichkeit finden, die Seuche einzudämmen. Doch die Seuche breitete sich allen Anstrengungen zum Trotz weiter aus und wurde zur Zerreißprobe für die [[Allianz]]. \r\nWährend die Reihen der [[Untote]]n [[Lordaeron]] heimsuchten, nahm Prinz [[Arthas]], der einzige Sohn von [[Terenas]], den Kampf gegen die [[Geißel]] auf. [[Arthas]] gelang es zwar, [[Kel'Thuzad]] zu töten, aber die Reihen der [[Untote]]n schwollen dennoch mit jedem Soldaten an, der bei der Verteidigung seines Landes fiel. In seiner ohnmächtigen Wut auf diesen scheinbar unaufhaltbaren Feind griff [[Arthas]] zu immer extremeren Maßnahmen, um ihn zu besiegen. Schließlich warnten seine Kameraden ihn, dass er im Begriff wäre, seine Menschlichkeit aufzugeben. \r\n[[Arthas]]' Furcht und Entschlossenheit wurden ihm zuletzt zum Verhängnis. Er spürte dem Ursprung der Seuche bis nach [[Nordend]] nach, um der Gefahr für immer ein Ende zu machen. Doch stattdessen wurde Prinz [[Arthas]] schließlich selbst ein Opfer der schier unermesslichen Macht des [[Lichkönig]]s. In dem Glauben, sein Volk damit retten zu können, ergriff [[Arthas]] die verfluchte Runenklinge [[Frostgram]]. Das Schwert gewährte ihm zwar unauslotbare Macht, aber es stahl ihm seine Seele und verwandelte ihn in den größten der [[Todesritter]] des [[Lichkönig]]s. Nach dem Verlust seiner Seele und nicht mehr bei Sinnen führte [[Arthas]] die [[Geißel]] gegen sein eigenes Königreich. Am Ende schließlich ermordete [[Arthas]] gar seinen eigenen Vater, König[[ Terenas]], und zertrat [[Lordaeron]] unter den eisernen Absätzen des [[Lichkönig]]s.\r\n===Sonnenbrunnen – Der Fall von Quel’Thalas===\r\nObwohl [[Arthas]] nunmehr alle [[Menschen]] getötet hatte, die er jetzt als seine Feinde betrachtete, quälte ihn immer noch der Geist von [[Kel'Thuzad]]. Der Geist flüsterte Arthas ein, dass er für die nächste Phase der Pläne des [[Lichkönig]]s wiederbelebt werden müsse. Zu diesem Zweck müsse Arthas Kel'Thuzads Überreste zum mystischen [[Sonnenbrunnen]] bringen, der im ewigen Königreich der [[Hochelfen]] [[Quel'Thalas]] verborgen lag. \r\nArthas und seine [[Geißel]] erstürmten Quel'Thalas und belagerten die Elfen, deren Verteidigung immer schwächer wurde. [[Sylvanas Windläufer]], Waldläufer-General von [[Silbermond]], kämpfte tapfer, aber Arthas löschte die Armee der Hochelfen letztlich dennoch aus und kämpfte sich bis zum Sonnenbrunnen durch. Als grausame Geste seiner Überlegenheit erweckte er sogar Sylvanas' besiegten Leichnam wieder als [[Banshee]], verflucht, im endlosen Untod in den Diensten der Eroberer von Quel'Thalas zu stehen. \r\nZuletzt tauchte Arthas Kel'Thuzads Überreste in die magischen Wasser des Sonnenbrunnens. Die starken Wasser der Ewigkeit wurden zwar durch diese Tat verunreinigt, Kel'Thuzad jedoch als zauberkundiger [[Lich]] wiedergeboren. Nachdem er als Wesen mit jetzt weitaus größerer Macht wiederauferstanden war, erläuterte Kel'Thuzad die nächste Phase der Pläne des Lichkönigs. Als Arthas und seine Armee der Toten endlich südwärts zogen, war kein einziger Elf in Quel'Thalas mehr am Leben. Das ruhmreiche Heimatland der Hochelfen, das mehr als neuntausend Jahre überdauert hatte, existierte nicht mehr.\r\n===Archimondes Rückkehr und die Flucht nach Kalimdor===\r\nAls [[Kel'Thuzad]] wieder geheilt war, führte [[Arthas]] die [[Geißel]] südwärts nach [[Dalaran]]. Dort fiel dem [[Lich]] das mächtige Zauberbuch von [[Medivh]] in die Hände, mit dessen Hilfe er [[Archimonde]] zurück in die Welt holte. Von diesem Moment an begann Archimonde höchstselbst die letzte Invasion der [[Brennende Legion|Legion]]. Nicht einmal die Zauberer der [[Kirin Tor]] konnten verhindern, dass Arthas' Streitkräfte Medivhs Buch stahlen, und so hatte Kel'Thuzad bald alles, was er brauchte, um seinen Zauber auszuführen. Nach zehntausend Jahren erschien der mächtige Dämon Archimonde erneut in seinem Wirtskörper auf der Welt [[Azeroth]]. Doch Dalaran war nicht ihr letztes Ziel. Auf persönliches Geheiß von [[Kil'jaeden]] folgten Archimonde und seine [[Dämonen]] der untoten Geißel nach [[Kalimdor]], um den Weltbaum [[Nordrassil]] zu vernichten. \r\nInmitten dieses Chaos erschien ein einsamer, mysteriöser Prophet auf der Bildfläche und bot den sterblichen Völkern seine Unterstützung an. Dieser Prophet war kein anderer als [[Medivh]], der letzte Wächter, der auf wundersame Weise aus dem Jenseits zurückgekehrt war, um sich von früheren Sünden reinzuwaschen. Medivh erzählte der [[Horde]] und der [[Allianz]] von den drohenden Gefahren und beschwor sie zur Zusammenarbeit. Nach Generationen voller Hass wollten die [[Orcs]] und [[Menschen]] davon nichts wissen. Medivh musste sich um jedes Volk einzeln kümmern und es mit Prophezeiungen und Tricks über das Meer ins legendäre Land Kalimdor locken. Bald stießen Orcs und Menschen auf die lange verborgene Zivilisation der [[Kaldorei]]. \r\nUnter Führung von [[Thrall]] mussten die Orcs auf der Reise durch das Ödland von Kalimdor eine Reihe von Rückschlägen hinnehmen. Sie schlossen zwar Freundschaft mit [[Cairne Bluthuf]] und seinen mächtigen [[Tauren]]kriegern, aber viele Orcs erlagen dem dämonischen Kampfrausch, der sie schon seit Jahren verseuchte. [[Grom Höllschrei]], Thralls größter Offizier, verriet die Horde sogar, indem er seinen niederen Instinkten gehorchte. Als Höllschrei und seine loyalen [[Orcs_des_Kriegshymnenklan|Kriegshymnen]]-Krieger durch die Wälder von [[Eschental]] schlichen, stießen sie auf die alten [[Schildwache]]n der [[Nachtelfen]]. In der Überzeugung, dass die Orcs zu ihrer kriegerischen Lebensweise zurückgekehrt waren, kam der Halbgott [[Cenarius]] herbei, um Höllschrei und seine Orcs zu vertreiben. Doch im Banne von übernatürlichem Hass und Wut konnten Höllschrei und seine Orcs Cenarius töten und den alten Wald verderben. Zu guter Letzt stellte Höllschrei seine Ehre wieder her, indem er Thrall half, [[Mannoroth]] zu besiegen, jenen Dämonenfürsten, der die Orcs ursprünglich mit dem Fluch seines Hasses und seiner Wut belegt hatte. Durch Mannoroths Tod wurde der Blutfluch der Orcs schließlich beendet. \r\nWährend Medivh noch die Orcs und Menschen von der Notwendigkeit einer Allianz zu überzeugen versuchte, kämpften die Nachtelfen auf ihre eigene heimliche Weise gegen die Legion. [[Tyrande Wisperwind]], die unsterbliche Hohepriesterin der Nachtelfen-Schildwachen, kämpfte verzweifelt, um zu verhindern, dass die Dämonen und Untoten die Wälder von Eschental überrannten. Tyrande wurde klar, dass sie Hilfe brauchte, daher zog sie aus, die [[Druiden]] der Nachtelfen aus ihrem tausendjährigen Schlummer zu wecken. Tyrande rief ihren einstigen Geliebten [[Malfurion Sturmgrimm]] und schaffte es, ihre Verteidigung zu stärken und die Legion zurückzuschlagen. Mit Malfurions Hilfe erhob sich die Natur selbst und wehrte sich gegen die Legion und die verbündete Geißel. \r\nAuf der Suche nach weiteren Druiden im Großen Schlaf fand Malfurion das alte Gefängnis im Grabhügel, wo er seinen Bruder [[Illidan]] angekettet hatte. Überzeugt, dass Illidan ihnen gegen die Legion beistehen würde, befreite Tyrande den Bruder ihres Geliebten. Tatsächlich unterstützte Illidan sie eine Zeit lang, doch dann floh er, um seine eigenen Pläne zu verfolgen. \r\nDie Nachtelfen wappneten sich und kämpften voll grimmiger Entschlossenheit gegen die Brennende Legion. Die Legion suchte noch immer nach dem Brunnen der Ewigkeit, seit langem Quell der Stärke des [[Weltbaum]]s und Herz des Königreichs der Nachtelfen. Sollte ihr geplanter Angriff auf den Weltbaum von Erfolg gekrönt sein, würden die Dämonen die Welt buchstäblich in Stücke reißen.\r\n===Die Schlacht am Berg Hyjal===\r\nUnter [[Medivh]]s Führung begriffen [[Thrall]] und [[Jaina Prachtmeer]], die Anführerin der menschlichen Streitkräfte in [[Kalimdor]], dass sie ihre Differenzen beilegen mussten. Ebenso stimmten die von [[Malfurion]] und [[Tyrande]] geführten [[Nachtelfen]] darin überein, dass sie sich zusammentun mussten, wenn sie den [[Weltbaum]] verteidigen wollten. Mit dem gemeinsamen Ziel vor Augen arbeiteten die Völker von Azeroth Hand in Hand, um die Energien des Weltbaums aufs Äußerste zu stärken. Es gelang dem mit der ureigenen Kraft der Welt ausgestatteten Malfurion, die Urgewalt von [[Nordrassil]]s Wut zu entfesseln, damit [[Archimonde]] zu vernichten und die Verbindung der Legion zum [[Brunnen der Ewigkeit]] zu durchtrennen. Die letzte Schlacht erschütterte den Kontinent Kalimdor bis ins Mark. Da die [[Brennende Legion]] keine Macht mehr aus dem Brunnen beziehen konnte, zerbrach sie unter den vereinten Kräften der Armeen der Sterblichen.\r\n==Siehe auch==\r\n* [[Der Erste Krieg]]\r\n* [[Der Zweite Krieg]]\r\nDer Dritte Krieg wird in dem PC-Spiel „[[Warcraft III - Reign of Chaos]]“ abgehandelt.\r\n'''Quelle:''' teilweise wow-europe.com",},
			["Der ermordete Gnom"] = { content = "== Einleitung==\r\nUnter dem \"Ermodeten Gnom\" versteht man die Ermittlung und die Lösung eines Kriminalfalls, der sich auf Burg Nethergarde vor etwa acht Jahre nach dem Fall von Gnomeregan zugetragen hat. Zu dieser Zeit war die Burg von der Dritten Macht und der Armee der Verderbnis besetzt.\r\nDer folgende Beitrag ist der Versuch die Geschehnisse chronologisch aufbauend wiederzugeben. \r\n===Neunter Mai. Schriftliche Wiedergabe von Hildegards Erzählung.===\r\nJinsei, Acorias und Hildegard waren auf Alunais Einladung vor zwei Wochen zu Besuch auf Burg Nethergarde. Hildegard hat alte Weggefährten wie Ankh getroffen und gehört, dass der Enkel ihres jetzt den Turm in Nethergarde bewohnt. \r\nVon Neugier getrieben kehrte sie bald darauf zurück und lernte Delgudar kennen. Die genauen familiären Verhältnisse ließen sich allerdings nicht klären. \r\nDas trat in den Hintergrund. Denn ein Mensch namens Aldwin kam in die Burg. Er wollte den Tod eines Gnoms untersuchen, der vermutlich von Dämonen getötet und gefoltert wurde. Als Hildegard das hört fordert sie Aldwin auf alles zu tun um das aufzuklären und fällt in Trauer, da sie jeden Gnom liebt. \r\nAls Hildegard später allein ist offenbart Aldwin ihr, dass er keineswegs Dämonen, sondern die Bewohner der Burg Nethergarde im Verdacht hat. Er hat keine Beweise, aber einen Zeugen: Ûdwin, der gemeinsam mit dem Gnom gefangengehalten wurde. Ûdwin soll sich in Stormwind aufhalten. Als Hilde das erfährt macht sie sich auf Ûdwin zu finden, aber sie kennt sein Aussehen nicht und da für Gnome alle Menschen gleich aussehen schafft sie es nicht ihn zu entdecken. \r\nAlso beschließt sie andere Gnome einzuweihen und es kommt zu einem Treffen in Ironforge. Die Gnome sind entrüstet und beschließen zu handeln. Andrejdelany und Hildegard werden mit den Nachforschungen beauftragt. Die beiden beschliessen sich als offizielle Botschafter der Gnome auszugeben, um das ganze aufzuklären. Was natürlich sehr riskant ist, wenn es auffliegt. \r\nDort angekommen, kam es zum Treffen mit Alunai, die genau wie Hilde, nun in dem Konflikt zwischen Freundschaft und Solidarität steckt. Die beiden beginnen nun verschiedene Personen in der Burg zu befragen und entfachen damit einigen Streit innerhalb der Bewohner. Letztendlich wollen sie eine Konfrontation riskieren und fordern ein Gespräch mit Kazot persönlich. \r\nDas Gespräch wird unterbrochen, als ein massiver Angriff auf die Burg hereinbricht. Die \"Diplomaten\" werden aufgefordert die Burg zu verlassen. \r\nHilde macht sich erneut auf die Suche nach Ûdwin, aber sie kann ihn nicht finden. Alles scheint schon verloren, und Hilde sitzt mit ihren Freunden vor der Burg Wildhammer am Lagerfeuer, als eine Botschaft von Aldwin sie erreicht, der sich bereit erklärt zu einem weiteren Treffen. Hildegard schleicht sich also in die Burg und spricht Aldwin an. Als Exomen an ihr verbeiläuft zuckt sie sichtlich zusammen, aber scheinbar wird sie als Freundin von Alunai hier toleriert. \r\nDas Gespräch mit Aldwin bringt neue Details, zum weiss Hilde nun, wo der Gnom begraben ist und zum zweiten, dass Nala, eine Elfe, eine weitere Zeugin ist. Leider kann Aldwin nicht sagen, wo Nala zu finden ist. \r\nMittlerweile ist Ûdwin maskiert in die Burg zurückgekehrt und hört, wie Hilde zu Aldwin sagt, dass sie dringend mit Ûdwin sprechen müsse. Daraufhin gibt Ûdwin, sobald es ihm möglich ist, Aldwin ein Zeichen und die drei treffen sich in einer verborgenen Ecke. \r\nÛdwin gibt weitere entscheidende Hinweise, aber leider keine Beweise. Hilde weiss nun, dass der Gnom schwarz/graues Haar hatte, dass er in der Burg der Armee der Verderbnis gemeinsam mit Ûdwin gefangengehalten und wurde und erfährt zu ihrer Bestürzung, dass ein Gnom den Befehl zum foltern eines Gnoms gegeben hat. \r\nDer Gnom scheint ein Zivilist gewesen zu sein, der nur zur falschen Zeit am falschen Ort war. Außerdem soll er nur aus purem Sadismus gefoltert worden sein. \r\nHilde beschließt zu handeln und jemanden innerhalb der Burg um Informationen zu erleichtern. Sie sucht sich Gilly aus, da sie eine Gnomin ist. Der Versuch Gilly zu bedrohen scheitert allerdings zweimal, Gilly reagiert nicht auf die Bedrohungen und sieht Hildegard als Geist und ihren Dolch als Mückenstich. Beinahe wird Hilde enttarnt, aber sie entkommt ungesehen. \r\nDa sie mit verstellter Stimme gesprochen hat versucht sie nun in grenzenlosem Übermut ein Spiel zu spielen. Sie kehrt in die Burg zurück, aber nun wieder als Diplomatin und fordert ein Gespräch. Exomen und Gilly begrüßen sie und bringen sie schließlich in den Saal in dem Obergeschoß der Burg. \r\nHilde erklärt das letzte Gespräch und gibt vor, dass sie glaubt der Mord an dem Gnom wäre eine kriminelle Tat. Gilly verplappert sich. Hilde weiss jetzt von den Folterungen. \r\nSie setzt alles auf eine Karte und spielt den \"guten Cop\". Sie erklärt, dass Mekkartorque persönlich den Fall aufgeklärt haben will, dass er Bronzebeard aufforden will sich mit der ganzen Allianz diesem Problem anzunehmen, sie erzählt Todesstrahlen und Dampfkampfpanzern. Sie erwähnt, dass sie wegen der Freundschaft zu Alunai keinen Kriege will und Mekkartorque ihr 48 Stunden gegeben hat. Bis dahin muss der Mörder ausgeliefert werden. Außerdem gibt sie vor Beweise zu haben. \r\nExomen durchschaut das Spiel. Er fragt sie, ob sie es bei der Freundschaft zu Alunai beschwören will, dass diese Informationen korrekt sind und Hilde kann sich nicht herauswinden. Sagt nichts aber verrät sich, was sie allerdings nicht bemerkt. \r\nExomen hat dadurch scheinbar genug Informationen bekommen. Und obwohl Gilly und er erst zögern lassen sie Hildegard gehen. \r\nEin weiteres Treffen ist für den heutigen Abend geplant. \r\nWas werden die Gnome unternehmen, um doch noch an Beweise zu kommen ? \r\nWird Nala zu finden sein ? \r\nUnd was wird passieren, wenn Hilde auf ihren Sandkastenfreund Dairon trifft, der immer ihre mechanischen Würmer kaputt gemacht hat ? \r\n===Neunter Mai. Tagebucheintrag von Exomem===\r\nEs war einer dieser verdammt heißen Abende zu Beginn des Sommers, dutzende gefährliche Aufträge würden Exomem an diesem Abend ins kochend heiße und trockene Tanaris oder in die schwülen und stinkenden Pestländer führen. \r\nEin leises Summen in seiner Reisetasche weckt seine Aufmerksamkeit, es ist der Machtkristall, den Anduriél ihm vor sehr langer Zeit gab, zu einer Zeit, als er sich noch im Rang eines Diener beweisen musste und von seiner Herrin mit diesem Kristall gerufen wurde. \r\nInzwischen hat sich der Hexer über den Rang eines Akolythen, dann Geweihten bis hin zum Fürst des Bundes empor gearbeitet. Der Kristall ist heute das sichere Zeichen dafür, dass Mächte am Werke sind, den Bund ‚die dritte Macht’, anzugreifen. \r\nSchnell ist sein Entschluss gefasst und er läuft hinüber zur Greifenstation direkt vor den Bootsstegen der Hafenstadt Menethil. Seine Anweisungen sind klar und er sitzt gleich darauf auf einem kräftigen Greifen, der ihn ohne Unterbrechung bis in die verwüsteten Lande fliegt. \r\nDort landet er oben auf dem Podest des Greifenmeisters der Festung Nethergarde, dem kürzlich eroberten Sitz seines Bundes und weiterer Verbündeter. \r\nExomem bemerkt einen Mann, der sich später als Tim Pattel vorstellt, ein heruntergekommener Vagabund, wie Exomem scheint, doch er ist keiner weiteren Betrachtung wert. Auf seiner Weg in die Burg und, wie er hofft, an die Seite seines Lords, trifft er mit Gilly zusammen, der Anführerin des Gillytrupps und somit der magiebegabten Verteidiger der Festung Nethergarde. Gilly schildert ihm kurz die Lage, es scheint alles ruhig, außer ungewöhnlich vieler Besucher. Einige davon spricht Gilly an, doch es hat zu Exomems Ärger jeder irgendeinen Vorwand, warum er hier herumlungern darf. \r\nVertieft in einen Zwist mit einem unwürdigen Wurm namens Aldwin, der angeblich auf Einladung des Lords in der Burg ist, fährt Exomem von einem ohrenbetäubenden Ruf zusammen. Am Tor der Festung hat sich eine Gnomin aufgebaut, die mit schier unbegrenzter Lautstärke von sich aufmerksam macht. Ein Blick auf Gilly verrät dem Fürsten, dass es für Gnome wohl nichts Ungewöhnliches ist und er denkt sich seinen Teil mit Wissen um die verrückten Erfindungen des Gnomenvolkes. \r\nGefolgt von Gilly geht Exomem auf die Gnomin zu und fragt nach deren Begehr. Sie gibt sich als Abgesandte eines schier unaussprechlichen Gnomen aus und bittet darum, einen der Herren dieser Festung sprechen zu dürfen. Ihr Name ist Hildegard, wie Exomem scheint, eine Blumenverkäuferin, die von ihrem Herrn hergeschickt wurde, um einen Stand zu eröffnen. Wer sonst, außer einer Floristin würde den Namen Hildegard tragen. Amüsiert bittet Exomem sie hinein und auf dem Platz in der Burg stellt er der kleinen Pflanzenkundigen die Hexe Gilly vor. Während der Abwesenheit der Burgherren ist Gilly die Ansprechpartnerin, wenn auch im Rang weit unter Exomem und weit weniger begabt im Umgang mit Gnomen, Zwergen, Menschen und Elfen… eigentlich im Umgang mit allem, was Lebt. \r\nHildegard kommt sehr schnell zu ihrem Anliegen, sie spricht über Tot und Folter, über ein Verbrechen, welches sich hier zugetragen haben soll und um dessen Aufklärung sie bemüht ist. \r\nDer Fürst erkennt schnell, wohin dieses Gespräch führen wird und lotst die kleine Runde in die südliche Burg, hinauf in den Saal des Lords. Hier beginnt die Gnomin nun, eine gar abenteuerliche Geschichte zu erzählen. Alles, was Hildegard sagt beruht auf Quellen, die ein Gnomischer Geheimdienst angeblich hat, alles beruht auf Gerüchten und Behauptungen… ein Wirrwarr an zusammengesponnenen Vermutungen und Schlussfolgerungen. \r\nExomem erkennt schnell, dass hier etwas nicht stimmt. Niemand, selbst ein Gnom mit Stormwind-Brie im Gehirn würde eine Abgesandte in die Festung Nethergarde schicken und ihr auftragen, den Führern der drei mächtigsten und gefährlichsten Bündnisse ganz Azeroths die Folter und den Mord an einem Gnom zu unterstellen und Aufklärung zu fordern. Nun, beschuldigen wäre ja ok, aber darauf trinkt man dann ein Fläschchen Pinot und fordert keine Aufklärung. \r\nExomem überlegt kurz, es wäre gut Möglich, dass dieser Gnom, dessen Namen so unaussprechlich ist, diese Hildegard nicht mehr ertragen konnte und sich sicher war, sie auf diese Weise los zu werden. Schnell ist sein Entschluss gefasst, ihm einen Strich durch die Rechnung zu machen… Gobblins, Murlocs oder auch mal nen Zwerg zu foltern ist ja ok, aber Gnome… hmm, nicht im Sommer! \r\nDer Hexer spielt weiter mit, vor allem weil er bemerkt, dass Gilly die Gnomin sehr Ernst zu nehmen scheint. Mit gespieltem Zorn versucht Exomem, die Abgesandte aus der Reserve zu locken, will mehr ihrer angeblichen Geheimnisse aus ihr herauskitzeln und erfährt, dass sie auf eigenen Wunsch herkam um zu vermitteln… als eine gute Freundin Alunais befürchtet sie einen militärischen Konflikt zwischen den beiden Lagern und möchte diesen verhindern. \r\nGeradezu lachhafte Szenarien malt die Gnomin den beiden Mächtlern aus, Belagerungsmaschinen, ganze Heere von Gnomen und Zwerge… als ob auch nur eine Belagerungsmaschine durch die Sümpfe hinunter in die verwüsteten Lande gebracht werden könnten. Hildegard ist so unbedarft, dass es dem Hexer schon fast leid tut, sie in diese Intrigen verstrickt zu sehen. \r\nDen Beteuerungen Gillys, dass in den letzten Tagen keine Gnome gefangen gehalten und gefoltert wurden folgte eine folgenschwere Erklärung Hildegards… es ist über eine Woche her… über eine Woche. Bei diesen Worten erschaudert Exomem. \r\nEine Gewissheit beginnt in ihm aufzusteigen, eine tödliche Gewissheit um das Geschehene und die Richtigkeit der Anschuldigungen. Ein Name geistert in seinen Gedanken umher… Dairon. \r\nMürrisch verabschiedet er Hildegard. Sie wird wiederkommen, dessen ist er sich gewiss. Ob als Lamm oder Löwe, das wird sich nun herausstellen müssen. \r\nAuch Gilly scheint den unachtsam fallen gelassenen Satz der Abgesandten richtig verstanden zu haben. Niemand stand Dairon so nahe, niemand hat seinen abgrundtiefen Hass und seinen Wahnsinn so nah erlebt wie sie… und nur wenige wussten, wozu er im Stande war. \r\nDoch hier erkennen auch beide die Gefahr für die dritte Macht. Dairon ist gegangen, doch wenn seine Taten noch in die Zeit fallen, in denen er zum Bund gehörte, so sind alle dafür mitverantwortlich. \r\nZu Gilly gewandt gibt Exomem die Anweisung, alle Informationen über Gäste in den letzten zwei Wochen zusammen zu suchen. Die Bücher sollten Aufschluss geben, doch auch die Wachen müssen gefragt werden. \r\nNicht sicher, ob es gut war, Hildegard laufen zu lassen schreibt Exomem zwei Briefe, verlässt die Burg und wirft sie in den Briefkasten. Inständig hofft er, dass die Empfänger die Nachricht noch rechtzeitig erhalten und ihm antworten können. \r\nEiner Sache ist er sich bewusst, jede negative Aufmerksamkeit zu diesem Zeitpunkt ist Gift für den noch jungen Bund auf Nethergarde. Sollte jemand oder etwas seinen Rang oder seine Macht missbraucht haben, um seine Verbündeten hier in Misskredit zu bringen, so wird dieser mit mehr als seinem Leben bezahlen!\r\n===Zehnter Mai. Schriftliche Wiedergabe von Hildegards Erzählung.===\r\nHildegard nutzte den gestrigen Tag um endlich das Grab des Gnoms aufzuspüren. Zu Ihrer großen Enttäuschung stand da lediglich \"Der kleine Gnom\" und kein Name. \r\nAllerdings, gelang es Ihr mit der Hilfe einiger Gnome, an die Kleidung des Gnoms zu kommen, die er trug als er starb. Diese wurde an das Institut für Pfuschkunde gesandt. \r\nDann begab sich Hilde in die Burg Nethergarde, wo sie sehr viel freundlich, als am Tag begrüßt wurde. Ihre Freundin Alunai war da und geleitete sie in die Burg. \r\nDort angekommen unterbreitete Hilde der dritten Macht den Vorschlag dies vom Institut für Pfuschkunde untersuchen zu lassen. Nach einiger Beratung akzeptieren das die Vertreter der dritten Macht und Hilde sendet ihre mechanische Eule Gudrun nach Stormwind zum Institut. \r\nNuggle Spannerspan, der Komiker, und Mickie Mux erhalten die Nachricht und kommen zur Burg um alles zu untersuchen. \r\nDort bricht Trubel aus. Violetita, eine begnadete Schneiderin steht mitten in der Burg und Miró, der Kräuterhändler vor dem Tor. Beide werden offen empfangen und niemand ahnt, dass sie da sind um Hildegard für den Fall der Fälle zu helfen. \r\nDie ganze Menge an Personen werden nun in Kazots Saal geführt und während Nuggle Spannerspan dort wilde Theorien über den Mordfall entwirft versucht Mickie Steinspuren an dem Stoff mit dem der Burg zu vergleichen. \r\nDa Hilde sich in Sicherheit wiegt gibt sie Violetita und Miró ein Zeichen, dass sie gehen sollen, um die Tarnung nicht auffliegen zu lassen. Allerdings befürchtet sie, dass es zu spät ist und die dritte Macht nur besseres zu tun hat, als sich um die beiden zu kümmern. \r\nMickie findet heraus, dass die Steinspuren eindeutig von der Burg stammen. Die dritte Macht fühlt sich zu unrecht beschuldigt und erwähnt, dass auch die Armee der Verderbnis einen Kerker hat. \r\nAlunai lädt Hilde und Mickie ein zur Burg der Armee der Verderbnis zu gehen und....\r\n===Zehnter Mai. Tagebucheintrag von Exomem===\r\nAm frühen Abend betritt Fürst Exomem die Burg der dritten Macht. Schon unten in der Halle trifft er auf eine kleine Gruppe sich unterhaldender Frauen. Auf den ersten Blick erkennt er Augustine und Alunai, vor ihnen steht wie zu dieser Stunde angekündigt Hildegard und auch Gilly zählt zu der Gruppe. \r\nDer Gruß fällt eher frostig aus, nicht nur, dass die Nachforschungen des Hexers gänzlich andere Informationen gaben als die Vermutungen der Abgesandten, hinzu kam noch, dass sie hier mitten in der Burg, zwischen den Türen zum Ausgang, der zum Kerker und der Treppe zum Herrschaftssaal standen und jeder in dem verdammten Gemäuer die Worte belauschen könnte. Was er von Gillys Wachen halten konnte hatte Exomem am Abend zuvor erfahren müssen, als seine Höllenbestie, freigelassen durch den Meister, drei Wachen fast zu Tode prügelte und diese Jammerlappen ihr nutzloses Leben nur behielten, weil sich eine ungeladene Elfe einmischte. \r\nAuf diese Wachen ist also kein Verlass, weiß der Fürst seitdem, und entsprechend Schroff fährt er Gilly an, als er eine leichtbekleidete Elfin in einem der Torbögen stehen sieht. \r\nDie Gnomin Hildegard zeigt sich vom Zorn des Hexers unbeeindruckt und beginnt anscheinend von neuem, die Neuigkeiten zu erzählen, die Grund für ihr frühes Erscheinen sind. Es wurde das Grab des Gnomen entdeckt und zur offensichtlichen Freude der kleinen Frau auch ein Teil seiner Kleidung. \r\nAbgelenkt von Streitereien zwischen Gilly und der Nacktelfe und von einigen Blickwechseln mit der, mit den Jahren immer aufreizender werdenden Augustine, bekommt Exomem nur Bruchstücke der hektischen Erzählungen Hildegards mit. Sie trägt also einen Stofffetzen bei sich, dieser Fetzen enthält Spuren, Spuren, die sie nicht kennt, die aber Aufschluss über das Verbrechen geben könnten. \r\nInzwischen hat sich die Elfe etwas über die Beine gezogen, einen lang fallenden Rock, wie Exomem missmutig bemerkt, doch interessanter wird das rosafarbige Geschöpf als Hildegard es als ihre persönliche Schneiderin vorstellt und sie mitgekommen sei, weil es in der Eile des Aufbruchs wohl nicht möglich war, Maß zu nehmen an ihr. \r\nNur kurz überlegt sich Exomem, warum die Elfe nicht einfach Maß an einer [Alterac-Kartoffel] genommen hat, die Proportionen hätten doch gestimmt… doch er verwirft den Gedanken schnell wieder, weil der Anblick der zwei langen und so sanft schimmernden Elfenbeine die Burg für wenige Minuten in ein warmes Heim verwandelt hatten. Seine Gedanken wieder aus der Robe holend wendet sich Exomem Hildegard zu und erfährt zu seinem Entsetzen, dass die Gnomin vorschnell einen anderen Teil der Kleidung an das Institut für Pfuschkunde gegeben hat und von dort in Bälde erste Ergebnisse erwartet. \r\nAusgerechnet diese Korinthenkacker sollen nun ein Stück Stoff auf Spuren untersuchen… und das in einem so heiklen Fall wie diesem, wo ganz offensichtlich sehr mächtige Leute ihre Hände im Spiel haben. Der Gedanke, seinem Lord berichten zu müssen, dass das Institut ein Beweisstück in Händen hält, welches vielleicht ein Verbrechen der dritten Macht beweisen könnte… nein, das darf einfach nicht sein. Die Tage, wo Vertreter der Macht unvorsichtigerweise kleinere Dörfer oder Stadtteile von Stormwind in Schutt und Asche gelegt haben sind vorbei. Seit diesen Zeiten der großen, wenn auch leider etwas extrovertierten Hexer agiert die dritte Macht doch weit gewiefter, das letzte Verbrechen welches man uns überführte war der Raub einer unbedeutenden Seele vor langer Zeit in Goldshire… doch alle Zeugen und der Ankläger verloren nach ihrem Gedächtnis auch ihren freien Willen … eine gute Lösung, wie Fürst Exomem fand. \r\nAber hier wird es schwieriger werden, wenn auch noch immer nichts bewiesen ist, ja nicht einmal eine ordentliche Beschuldigung überbracht wurde, die man mit der Enthauptung des Boten schön hätte beantworten können. \r\nEine solche Enthauptung stand aber kurz bevor, wenn auch es schade wäre, die lästige Zeugin, deren Name wohl Violetita war, unsanft verschwinden zu lassen. Andererseits, in einem der Türme stand noch ein uralter Webstuhl, und wenn man ihr einen sich ewig erneuernden Fluch der Sprache auferlegen würde, käme außer Gesang auch nicht viel aus deren Fenster nach draußen. \r\nIn diesem Moment kam die Gnomin auf die dumme Idee, Burg Nethergarde zu verlassen und die Ergebnisse der Untersuchung persönlich in Stormwind abzuholen. \r\nNatürlich war es Exomem bewusst, dass niemand außer ihr das tun könnte, die dritte Macht würde sich wohl kaum ungehindert durch die Stadt bewegen können, doch es musste doch eine andere Lösung geben. \r\nUnd die gab es. Gudrun, die mechanische Eule Hildegards, wird die Pfuschforscher informieren und um eine Antwort bitten. Als er den Namen des Tieres hört ist Exomem gleich klar, dass Hildegard diese Kreatur nur mit einem solchen Namen gestraft hat, weil sie selbst die Lebenslange Folter, angezettelt durch ihre Eltern nicht länger erträgt und den Frust irgendwie übertragen musste. \r\nAus dem gleichen Grund sprengen Gnome so gerne sich und andere in die Luft… es ist der Frust über den Verlust ihrer Heimat und der erbärmlichen Niederlagen gegen Schlamm und stinkende Goblins, die sie nie verknusen konnten. \r\nErkenntnis ist eines der Schwerpunkte in Exomems Studium der dunklen Magie und ihrer Zusammenhänge mit dem Nether, und darin war er schon immer ein ganz großer, denkt er sich. \r\nEs vergehen nur wenige Minuten, Exomem steht vor der Burg und belehrt einen windigen Kräuterhändler über realistische Preise für Sonnengras und Winterbiss, als er den Schatten seines ehrwürdigen Lords auf der Brücke erblickt. Dem Kräutersammler keine weitere Beachtung mehr widmend geht der Fürst schnell hinein in die Burg und hält Ausschau nach Lord Kazot. \r\nOben im Saal trifft er ihn an, Augustine kniet vor ihrem Lord und informiert ihn gerade darüber, dass Arger in der Luft liegt. \r\nIn knappen Worten schildern Exomem und Augustine, was vorgefallen ist. Der Lord entscheidet sich nach einiger Überlegung, der Abgesandten Hildegard eine Audienz zu gewähren, was Augustine nach Exomems Aufforderung auch an diese Übermittelt. \r\nNach schier endlosen Minuten des Wartens kommt eine ganze Gruppe von Leuten in den Saal hinauf. Neben Hildegard, Alunai und Gilly treten auch Violetita sowie der Kräuterhändler ein. \r\nEs stellt sich heraus, dass es Freunde und Vertraute von Hildegard sind, natürlich rein zufällig hier und auch nur auf Hildegards freundliche Einladung mit hochgekommen. \r\nExomem überblickt die Lage und stellt zu seiner Erleichterung fest, dass die dritte Macht mit sehr erfahrenen Hexern vertreten ist, ein Übergriff durch die Fremden ist nicht zu befürchten, wobei eine schnelle Liquidierung der Besucher jedoch auf Probleme treffen könnte. \r\nWeitere Stimmen hallen durch das Gemäuer und nachdem Exomem Gilly losschickt, diese ausfindig zu machen und herzubringen betreten zwei weitere Gnome den Saal. \r\nVon Hildegard werden diese als Mickie Mux und Nuggle vorgestellt, Mitarbeiter des Institutes. \r\nLord Kazot gewährt es Hildegard, zu sprechen, worauf diese die Geschehnisse der letzten Tage, beginnend bei dem Gerücht beginnt, dass vor etwas über eine Woche ein Gnom hier in der Festung Nethergarde gefoltert worden sei. \r\nDie Handlungen überschlagen sich nun. Sichtlich genervt von der unkoordinierten Vorgehensweise der Pfuscher lässt sich der Lord ein paar Indizien und die Schlussfolgerungen der Mitarbeiter des Institutes vorlegen. Seine Reaktion wird aber gar nicht erst abgewartet, denn schon wieder schwärmen die Gnome aus und durchforsten den Thronsaal um Gesteinsproben zu sammeln und irrwitzige Behauptungen in die Luft zu blasen. \r\nEine gänzlich unbeteiligte Person tritt plötzlich in Erscheinung. Die Anmutige Frau mit wellendem, schwarzen Haar geht scheinbar unbeeindruckt vom Geschehen auf Lord Kazot zu und beginnt ein Gespräch mit diesem. Die Frau stellt sich bei näherem Betrachten heraus als ein früheres Mitglied der dritten Macht, ihr Name ist Tatiyana. \r\nEntnervt von dieser Störung und den immer abwegigeren Schlussfolgerungen der beiden Gnome verlässt Hildegard den Saal, gefolgt von den Pfuschern Mickie und Nuggle. \r\nDa das Geschehen oben im Saal inzwischen völlig zum Erliegen gebracht wurde beschließt auch Exomem, den Saal zu verlassen und geht gemeinsam mit Gilly hinaus vor die Burg, wo sie auf die anderen Gnome treffen. \r\nEin neuer Plan schien im Kopf von Hildegard gereift zu sein. Nachdem die dritte Macht ihre Unschuld beteuert hat und keine weiteren Nachforschungen in der Burg mehr möglich waren, sollte nun die nördlich gelegene Burg inspiziert werden. Gilly erklärt sich bereit, die Gnome dorthin zu geleiten und für sie beim Burgherrn vorzusprechen. Dieses Unternehmen scheitert an der Abwesenheit hochrangiger Mitglieder der Burgherren, welche sich aus der Armee der Verderbnis zusammensetzen. \r\nSehr enttäuscht wird die weitere Befragung möglicher Zeugen auf einen späteren Zeitpunkt verschoben. Schon am nächsten Abend soll um Einlass in die Burg ersucht werden und den dortigen Streitern die Situation erläutert werden. \r\n===Vierzehnter Mai. Schriftliche Wiedergabe von Hildegards Erzählung.===\r\nZu Hildes völliger Verwirrung ist nun gestern eine unbekannte Menschenfrau von Miró und Violetitia gefunden worden. Sie trug einen roten Gildenwams mit einem Spinnennetz bei sich. \r\nHilde reagierte schnell und vielleicht etwas unüberlegt und sande Gudrun, ihre mechanische Eule, zu Alunai um Informationen über den Gildenwams zu erhalten. \r\nAls Antwort erhielt sie, dass es sich bei der Gilde um den Blutkult Enkilzar handelt. Eine Sekte, die im Krieg mit der dritten Macht steht. Sie sind wohl schwer anzutreffen, aber versammeln sich regelmäßig um Rituale für Blutgeister durchzuführen. \r\nDaraufhin träufelt Hilde ein Gift des traumlosen Schlafs in eine Milch für die Menschenfrau und überlässt sie Umbas Obhut. \r\nWer ist diese Menschenfrau und hat sie etwas mit der Gefangenen der dritten Macht zu tun, mit falschen Friedensverträgen.... \r\n===Vierzehnter Mai. Schriftliche Wiedergabe von Umbas und Mirós Erzählung.===\r\nAls Miró aufgeregt zu Umba kam um ihm zu sagen seine fähigkeiten werden gebraucht wuste er noch nicht was ihn dort erwartet \r\nalso flog er zum haus von Miró und Violetitia die sich auch rührend um die frau kümmerte , er erkannte sie sofort , wuste wen sie da gefunden haben , wuste auch das darf niemand erfahren wenn sich nicht ein krieg entfesseln soll , er wuste Sarah Olsen muss leben sonst hat die dritte macht schon wieder eine front frei , eine gegner weniger .. \r\nAber er wuste auch sie muss geheim bleiben ihre identität , und die muste so lange wie möglich , nicht mal Miró seinen bruder weihte er ein den selbst er , würde sie töten .... \r\nUmba gab Hildegard ein paar hinweise die sie erstmal auf eine falsche spur locken sollte um ein bischen zeit zu gewinnen den Miró fand schon beinah zu viel über Sarah heraus den wenn es bekannt ist wer hier liegt \r\nsteht die dritte macht .. die inqusition und wer weiss noch alles vor der tür und würden versuchen sie zu töten .. oder schlimmeres \r\nUnd nun versucht er das leben der Hexe zu retten ..... \r\nzu viel hatte Ashalmawia der welt schon angetan als das sie nun so einfach von ihr verschwinden darf \r\nzu klären gilt \r\nIst Umba einfach nur gefangen worden .. sein geist von der hexe ein wenig manipuliert den er kennt sie wenn auch nicht lang aber er ist in der nähe der Hexe anders als sonst \r\nschafft hilde den zusammen hang zu finden zwischen dem wappen und der Verschwundenen anführerin Enkilzars",},
			["Der Erste Krieg"] = { content = "Der Erste Krieg zwischen den [[Orcs]] und den [[Menschen]] wurde nach der Ankunft der orcischen Klans auf [[Azeroth]] ausgetragen. Das Menschen-Königreich Azeroth wurde dabei vollständig vernichtet. Die Überlebenden waren gezwungen, nach [[Lordaeron]] zu fliehen.\r\n==Chronologie==\r\n* Die ersten Schlachten verlaufen nicht gut für die [[Horde]]. In der Annahme, einen leichten Sieg gegen einen schwachen Gegner einzufahren, stürmt die Horde mit all ihrer Kraft gen [[Sturmwind]] und erleidet dort eine Niederlage katastrophalen Ausmaßes. Nur wenige [[Orc]]s überleben den Auftakt des Krieges.\r\n* [[Gul'dan]] verwendet seine Schatten[[magie]] um den [[Der schwarze Morast|Schwarzen Morast]] in undurchdringlichen Nebel zu hüllen. Der Nebel verhindert, dass die letzten verbleibenden [[Orc]]s von den Rache sinnenden [[Menschen]] gefasst werden.\r\n* Beschämt durch die unerwartete Niederlage entstehen langsam Aufstände in den Reihen der Klans. Chaos bricht aus, es gibt zahllose Beschuldigungen für die verlorene Schlacht der [[Horde]].\r\n* [[Gul'dan]] sorgt dafür, dass ein neuer, erbarmungsloser Dikatator den Thron des Kriegshäuptlings besteigt. [[Schwarzfaust der Zerstörer]], dem neuen [[Kriegshäuptling]], gelingt es, die Stämme wiederzuvereinen und sie für einen neuen Angriff auf [[Azeroth]] vorzubereiten. Die [[Horde]] beginnt vereinzelte Raubzüge auf nahe des [[Der schwarze Morast|Morastes]] gelegene Außenposten der [[Menschen]].\r\n* [[Medivh]] sendet [[Gul'dan]] eine weitere Vision, welche das Grab von [[Sargeras]] und seine enthaltende Macht zeigt.\r\n* Die [[Horde]] überfällt erneut [[Azeroth]], vernichtet dabei Städte und Dörfer und plündert alles, was auf ihrem Weg liegt. Die Städte [[Grand Hamlet]], [[Sunnyglade]], [[Goldhain]] und [[Mondbruch]] werden vollständig vernichtet.\r\n* [[Durotan]], Häuptling des [[Frostwolfklan]]s, wird von verfeindeten [[Orcs]] überfallen und getötet. Die Mörder lassen Durotans Sohn, im Glauben er sei tot, zurück. Doch schon bald wird der junge Orc von einer Gruppe [[Menschen]] unter dem Kommando von [[Aedelas Schwarzmoor]] gefunden. Das Waisenkind wird als Sklave gehalten und erhält den Namen [[Thrall]].\r\n* Lord [[Anduin Lothar]] bemerkt [[Medivh]]s Verrat und führt ein kleines Bündnis von Kriegern zu [[Karazhan|Medivhs Turm]] und konfrontiert den Magier. Lothar erschlägt Medivhs Körper und vernichtet damit den Geist [[Sargeras]]. Medivhs Geist jedoch entkommt.\r\n* [[Schwarzfaust der Zerstörer]] wird von [[Orgrim Schicksalshammer]], einem vertrauten General und engem Freund, verraten und ermordet. Schicksalshammer ersetzt Schwarzfaust als Kriegshäuptling der [[Horde]].\r\n* [[Sturmwind|Burg Sturmwind]] wird durch die geballte Macht der [[Horde]] bezwungen und erobert. Während des Kampfes wird [[König Llane]] von einem von [[Gul'dan]]s Auftragsmördern, der Halborc-Frau [[Garona]], getötet.\r\n* [[Orgrim Schicksalshammer]]s loyal ergebene Spione fassen und foltern [[Garona]]. Unter Qualen enthüllt sie die Existenz des [[Schattenrat]]es und führt ihre Peiniger zum Aufenthaltsort von [[Gul'dan]]s [[Hexenmeister]] nahe der Festung [[Sturmwind]].\r\n* [[Orgrim Schicksalshammer|Schicksalshammer]] entsendet seine [[Wolfsreiter]] zu den Ruinen [[Sturmwind]]s. Sie töten und exekutieren die meisten von [[Gul'dan]]s [[Hexenmeister]]n und vertreiben die verbleibenden Mitglieder des [[Schattenrat]]es. Gul'dan fleht um Gnade und bietet vollständige Kapitulation. Schicksalshammer akzeptiert und lässt Gnade walten.\r\n* [[Anduin Lothar]] gesteht, dass das Königreich [[Azeroth]] verloren ist. Er versammelt seine Gefolgsleute und führt sie in ein fernes, abgeschiedenes Land jenseits des Großen Meeres, an die Küste von [[Lordaeron]].\r\n==Siehe auch==\r\n* [[Der Zweite Krieg]]\r\n* [[Der Dritte Krieg]]\r\nDer Erste Krieg wird im PC-Spiel \"Warcraft: Orcs and Humans\" abgehandelt.",},
			["Der heulende Fjord"] = { content = "'''Der Heulende Fjord''' liegt hoch über dem großen Meer und an der südöstlichen Spitze von [[Nordend]]. Legenden besagen, dass das Land vor langer Zeit von den [[Vrykul]], einem Volk kriegerischer Halbriesen, bewohnt wurde, die eine große und wohlhabende Zivilisation errichteten. Doch eines Tages verschwanden die [[Vrykul]] ohne Vorwarnung und ohne Erklärung und hinterließen nur leere Dörfer und verlassene Tempel. Nun sind die [[Allianz]] und die [[Horde]] gekommen, um dem boshaften [[Lichkönig]] entgegen zu treten und der [[Geißel]] ein Ende zu setzen. Doch die ausgezeichneten Krieger der [[Vrykul]] haben begonnen, die Siedlungen der [[Allianz]] und der [[Horde]] anzugreifen. Bevor die Schlacht gegen den [[Lichkönig]] beginnen kann, müssen die [[Allianz]] und die [[Horde]] die Bedrohung durch die [[Vrykul]] ausmerzen und die Fragen beantworten, die ihre Rückkehr aufgeworfen hat. Wo waren die [[Vrykul]] so lange? Was wollen sie? Und die beunruhigendste Frage: stehen sie mit dem [[Lichkönig]] im Bunde? Vielleicht kann nur die Zeit diese Fragen beantworten. Die Schlacht hat gerade erst begonnen.\r\n'''Quelle:''' \r\n==Fraktionen==\r\n* '''Allianz''' - Die [[Allianz]] hat an der [[Dolchbucht]] einen Stützpunkt in der Siedlung [[Valgarde]] errichtet.\r\n* '''Eisenzwerge''' - Zwergische Ausgrabungsleiter haben mysteriöse Verwandte entdeckt, deren Haut mit sonderbaren Runen geschmückt ist. Diese [[Eisenzwerge]] könnten vielleicht das fehlende Bindeglied sein, um das Geheimnis um die Entstehung der [[Zwerge]] zu entschlüsseln. \r\n* '''Verlassene''' - Die [[Verlassene]]n haben sich im [[Hafen der Vergeltung]] und [[Neu Agamand]] niedergelassen.\r\n* '''Vrykul''' - Viele Krieger der [[Vrykul]] strömen nun aus ihrer Festung [[Burg Utgarde]], die nicht weit von [[Valgarde]] entfernt liegt. Was die [[Vrykul]] dazu treibt und wo sie in den letzten paar tausend Jahren waren, bleibt ein Rätsel. Dennoch gibt es keinen Zweifel, dass die plötzliche Rückkehr der [[Vrykul]] eine tobende Schlacht um die Kontrolle über die Gegend ausgelöst hat.\r\n==Orte==\r\n* [[Apothekerlager]]\r\n* [[Außenposten der Forscherliga]]\r\n* [[Baelguns Ausgrabungsstätte]]\r\n* [[Blutklamm]]\r\n* [[Bruchwald]]\r\n* [[Burg Utgarde]]\r\n* [[Dolchbucht]]\r\n* [[Flüsterschlucht]]\r\n* [[Fort Wildervar]]\r\n* [[Frostklingengipfel]]\r\n* [[Frostmaarküste]]\r\n* [[Gefrorene Lichtung]]\r\n* [[Geisterklingenposten]]\r\n* [[Gjalerbron]]\r\n* [[Glutspeerturm]]\r\n* [[Glutstätte]]\r\n* [[Hafen der Vergeltung]]\r\n* [[Halgrind]]\r\n* [[Halunkeneck]]\r\n* [[Insel der Speere]]\r\n* [[Iskaal]]\r\n* [[Ivalds Ruine]]\r\n* [[Kamagua]]\r\n* [[Katakomben von Utgarde]]\r\n* [[Lager der Winterhufe]]\r\n* [[Lebendiger Hain]]\r\n* [[Neu Agamand]]\r\n* [[Niffelvar]]\r\n* [[Plateau der Riesen]]\r\n* [[Quälheim]]\r\n* [[Schildhügel]]\r\n* [[Siechender Hain]]\r\n* [[Skorn]]\r\n* [[Stählernes Tor]]\r\n* [[Valgarde]]\r\n* [[Verlassener Strand]]\r\n* [[Westwacht]]\r\n* [[Wyrmskol]]",},
			["Der Hügel"] = { content = "'''Der Hügel''' befindet sich im [[Nethersturm]], südlich von [[Area 52]]. Eine Gruppe von [[Astrale]]n, die als [[Astrale der Zaxxis]] bekannt sind, haben ihre Verbindungen zum [[Konsortium]] abgebrochen, um hier ihre eigenen Geschäfte zu machen. Sie machen sogar Geschäfte mit den [[Blutelfen]]. Die [[Zaxxis]] sind eine ziemlich verschlagene Truppe und sehr opportunistisch. Aber der Hügel gehört den [[Goblins]] von [[B.U.M.M]]. Und da die Astralen von den Goblins stehlen, ist es nur gerecht, wenn sie es ihnen mit gleicher Münze heimzahlen. [[Sphärenräuber Nesaad]] hat ein kleines Lager des [[Astraleum]]s im südwestlichen Teil des Hügels. Auch [[N. D. Mieskamp]] hat hier ein kleines Lager und sucht das Herz eines [[Teufelshäscher]]s.",},
			["Der Kessel"] = { content = "Große Minenarbeiten werden von den [[Dunkeleisenzwerge]]n in einem Teil des Gebietes der [[Sengende Schlucht|Sengenden Schlucht]] durchgeführt, welches die [[Zwerge]] den Kessel nennen. Die Arbeit in den Minen wird hauptsächlich von Sklavenarbeitern durchgeführt, welche von den [[Dunkeleisenzwerge]]n gefangengehalten werden und ihr Anführer, [[Lathoric der Schwarze]], benutzte die Kraft der [[Suntarasteine]], um ein zwergisches Ausgrabungsteam zu versklaven. Sie wurden zum Kessel gebracht und ihre Gedanken wurden verdreht. Nun arbeiten sie Tag und Nacht, um etwas, das [[Obsidion]] heißt, zu vollenden. Selbst nachdem ihre Körper aufgegeben haben, zwingt die Macht der Suntarasteine sie, ihre Aufgaben weiter zu erfüllen, denn der [[Sengende Schlucht|Altar von Suntara]] ist der Schlüssel für die Erweckung [[Obsidion]]s.\r\nObgleich die vier Türme um den Kessel niemals zerstört werden können, kann man dennoch die Fackel der Vergeltung benutzen, um sie für lange Zeit in Brand zu setzen. Ein Feuer, das kein Element und keine Macht löschen kann. Während sie in Flammen stehen, kann keine Wache oder Wachposteneinheit die Posten besetzen, und so ist ihre erste Verteidigungslinie außer Kraft gesetzt. Man muss in jeden Turm eindringen und die Fackel der Vergeltung innerhalb ihrer Befestigung verwenden. Die Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge des Kessels in der Sengenden Schlucht benutzen Waffen aus verzaubertem Thorium, eine besonders stabile Legierung.\r\n==NSC's==\r\n* '''Kalaran Windklinge''' - Kalaran Windklinge hält sich in der Nähe des Kessels auf. Er erzählt, dass sein Vater von dem Abschaum im Kessel niedergemetzelt wurde. Sein Flehen um Beistand stieß beim Magistrat von Sturmwind auf taube Ohren. Sie wollten nicht einmal zugeben, dass es diesen Teil der Welt überhaupt gibt, geschweige denn ihr tolles Militär hinschicken, um dort für Recht und Ordnung zu sorgen. Er will Rache, ganz einfach ... Wie man sieht, ist er nur ein einzelner Mann und sein Knappe ist ein einfältiger Blödian. Gegen die Macht der Zwerge aus Dunkeleisen und der Bestien, die sich in Ragnaros' eisernen Griff befinden, hätte er sicherlich keine Chance. Aber mit einem mutigen und ehrgeizigen Abendteurer könnten sie der bewohner des Kessels Herr werden. Wenn man ihm hilft, wird er seine Helfer reich machen, reicher als sie sich das je hätten träumen lassen.",},
			["Der Kurator"] = { content = "Der Kurator ist der Beschützer der Menargie und wird deshalb niemanden kampflos durch die Bilbliothek marschieren lassen. Er hat eine harte Schale und das stellt er oft unter Beweiß. Zudem hat er noch überall in der Bilbiothek Wächter , die ihm ähnlich sind und arkane Wesen verteilt.",},
			["Der scharlachrote Ansturm"] = { content = "#REDIRECT [[Scharlachroter Ansturm]]", redirect = "Scharlachroter Ansturm",},
			["Der schwarze Morast"] = { content = "Der Schwarze Morast ist das weitläufiges Sumpfgebiet [[Azeroth]]s. Oberhalb der ausgedörrten [[Sümpfe des Elends]] befand sich einst das [[Dunkle Portal]] - der Durchlaß nach [[Azeroth]], der vor Beginn des 1. Krieges von [[Medivh]] der Orcischen Horde zugänglich gemacht wurde. Schnell hatten die Orcs dort einen Vorposten errichtet und innerhalb weniger Jahre die Kontrolle über den Schwarzen Morast erlangt. Im verwüsteten Aschenland trugen die dezimierte Horde und die unerbitterliche [[Allianz]] die letzte und blutigste Schlacht des 2. Krieges aus. Den Streitkräften um General Turalyon gelang es, das Portal zu zerstören und die Horde somit von Verstärkung aus Draenor abzuschneiden. Monatelang versuchten die Streitkräfte der Allianz, die abtrünnigen Orks ausfindig zu machen, die nach der Zerstörung des Dunklen Portals untergetaucht waren. Im Schwarzen Morast wurden Elfen-Kundschafter zur ständigen Patrouille abgestellt, die nach Hinweisen auf die flüchtigen Stämme suchen sollten. Es schien zwar, als wäre die Horde endgültig besiegt, aber die Kirin Tor blieben skeptisch, ob der Frieden von Dauer sein würde. Über den verpesteten Sümpfen des Elends schwebte noch immer ein unheilverkündender Riß im Gefüge der Wirklichkeit - dieser Spalt war noch übriggeblieben von der Pforte nach Draenor. Das Oberkommando der Allianz ließ die Festung Nethergarde bauen, um die Ruinen des Portals zu bewachen und zu gewährleisten, dass keine weitere Invasion erfolgte. Unmittelbar vor Sommeranbruch im Jahre 606 fegte eine grauenerregende Dunkelheit über den Schwarzen Morast. Alle Bemühungen der Magier von Nethergarde, diese Dunkelheit zu erkunden, waren vergeblich, aber sie konnten spüren, dass sich der Spalt wieder vergrößerte. Als die Dunkelheit vorübergezogen war, ließen die Spuren im Schlamm erahnen, dass der Klan des Blutenden Auges nach Draenor übergesetzt hatte. Auf dem Höllenplaneten Draenor bereitete die Orks wieder einen Feldzug gegen die ahnungslose Allianz vor. Zwar konnten sie einige magische Artefakte in ihren Besitz bringen, aber die Belagerung der Zitadelle von Nethergarde wurde gebrochen. König Terenas schickte seine Armeen nach Draenor, um die Bedrohung durch die Orks ein für alle Mal zu beenden. \r\n'''Quelle:'''",},
			["Der Schwarze Tempel"] = { content = "Der Schwarze Tempel ist ein Schlachtzugdungeon für 25 Spieler im [[Schattenmondtal]]. \r\n==Geschichte==\r\nDer Schwarze Tempel war ursprünglich der [[Tempel von Karabor]] - das heiligste Religionszentrum der [[Draenei]] auf Dreanor. Seine Intention wurde in der turbulenten und blutigen Geschichte der Scherbenwelt mehrfach überworfen und der Tempel seinem eigentlichen Zweck beraubt, wodurch jegliche spirituelle Anmut, die dieser Ort einst aufweisen konnte, verloren ging. Die hingebungsvollen Priester, die einst in seinen Hallen beteten, sind schon lange tot, hingemetzelt von räuberischen, dämonisch korrumpierten Orcs. \r\nAls das Schlachten geendet hatte, besetzten die Hexenmeister des [[Schattenrat]]es das Gebäude und belegten es mit seinem neuen, unheilverkündenden Namen: der Schwarze Tempel. Es war die Bühne des Blutfluches der Orcs der Horde, eine Zitadelle für den damals sterblichen [[Ner'zhul]] und der Hauptschauplatz des Feldzuges der Zerstörung der Brennenden Legion. Jahrelang besudelte der [[Schattenrat]] mit schändlichen, dämonischen Ritualen den Schwarzen Tempel. \r\nIm zweiten Krieg verloren die dunklen Zauberer der zerstörerischen Invasion Dreanors jedoch gegen die Invasion der [[Allianz]]. Ner'zhul, öffnete in seiner Not mehrere Dimensionsportale, um einen Rückzug zu inszenieren, wobei jedoch die resultierende magische Rückkopplung die Welt zerriss und magische Kräfte freisetze. Aus diesen Toren drangen die Armeen des Dämonengenerals [[Magtheridon]] und übernahmen den Schwarzen Tempel, den der General zu seinem Sitz als Herrscher über die zersplitterte [[Scherbenwelt]] machte. Magtheridon befehligte viele der in der Scherbenwelt verbliebenen [[Orcs]] und verstärkte seine Armee mit Streitkräften der Legion, die durch die Portale strömten. \r\nDer [[Grubenlord]] herrschte unangefochten, bis er nach einigen Jahren von [[Illidan]] dem Verräter herausgefordert wurde und unterlag. Illidan der Verräter entschied, den Schwarzen Tempel für sich selbst zu beanspruchen. Illidan und Magtheridon fochten einen verzweifelten Kampf auf den Mauern des Tempels, doch am Ende erwies sich der [[Grubenlord]] als ungleicher Gegner für den Träger der [[Zwillingsklingen von Azzinoth]]. Illidans Attacken brachten Magtheridon eine beinahe tödliche Niederlage ein, doch die Siegesfreude sollte nur von kurzer Dauer sein... Der Himmel über der [[Scherbenwelt]] verdunkelte sich abermals, als [[Kil'jaeden]] selbst vor Illidan erschien, zornerfüllt über dessen Versagen, den [[Lichkönig]] zu vernichten. Der Verräter wurde zurück nach [[Azeroth]] gezwungen, um einen verheerenden Angriff auf den [[Eiskronegletscher]] zu führen. Vom Todesritter [[Arthas]] übel zugerichtet, aber nicht endgültig besiegt, kehrte Illidan in die [[Scherbenwelt]] zurück und etablierte seinen Thronsitz im Schwarzen Tempel. Und doch, trotz Illidans Anstrengungen, Ner'zhuls Portale zu versiegeln, wird [[Kil'jaeden]]s Zorn sein Ziel finden. Selbst jetzt noch hämmern die unbarmherzigen [[Verdammniswandler]] an die Tore des Tempels. Entschlossen, seinen Griff um die Scherbenwelt nicht zu lockern, wartet Illidan auf alle und jeden, der es wagt, seine Herrschaft in Frage zu stellen. \r\n==Einlass==\r\nDas [[Medaillon von Karabor]] - einst von einem Kleriker von Karabor getragen, gewährt dem Träger Einlass in den Schwarzen Tempel.\r\n==Bosse==\r\n* [[Oberster Kriegsfürst Naj'entus]]\r\n* [[Supremus]]\r\n* [[Akama]]s Schemen \r\n* [[Teron Blutschatten]]\r\n* [[Gurtogg Siedeblut]]\r\n* [[Reliquiar der Seelen]]\r\n* [[Mutter Shahraz]]\r\n* Rat der [[Illidari]] - ([[Lady Malande]], [[Gathios der Zerschmetterer]], [[Hochnethermant Zerevor]], [[Veras Schwarzschatten]])\r\n* [[Illidan Sturmgrimm]]",},
			["Der Silberbund"] = { content = "'''Der Silberbund''' (engl. The Silver Covenant) ist ein militanter Kern von [[Hochelfen]], die den Eintritt der [[Blutelfen]] in die [[Kirin Tor]] ablehnen. Sie haben sich unter dem Banner von [[Vereesa Windläufer]] versammelt und sich den Streitkräften der [[Allianz]] in [[Nordend]] angeschlossen.",},
			["Der Weg der Erlösung"] = { content = "Der '''Der Weg der Erlösung''' ist ein Buch, welches beim Scharlachroten Kurier im [[Hafen des Königs]] von [[Neu Avalon]] gefunden werden kann. Es wurde von [[Hochgeneral Abbendis]] verfaßt und beschreibt die Entstehung des [[Scharlachroter Ansturm|Scharlachroten Ansturms]] in [[Nordend]] aus dem [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzug]].\r\n==Inhalt==\r\nDie Stimme flüsterte: \"Komm zu mir.\" \r\nVon Anfang an wusste ich, dass es das [[Heilige Licht]] war, das in meinen Träumen zu mir sprach. Endlich! Nach all den Jahren der Gebete und guten Taten, Jahre, in denen die Seuche der Untoten vom Angesicht Azeroths getilgt wurde; nach all den Misserfolgen, all den Auferstehungen. \r\nEndlich!\r\nUnd wieder geschah es. \"Komm zu mir...\", befahl das Licht.\r\nDieses Mal schlotterte ich vor Kälte, als ich aufwachte, doch die Luft in meinen Gemächern war nicht kalt. Ich werde mich noch mehr bemühen! Ich werde dem Hohen Abt morgen sagen, dass mir noch mehr Gebete auferlegt werden sollen. Schluss mit Halbherzigkeiten!\r\nDas Heilige Licht hat bemerkt, wie gut wir arbeiten. Ich kann es spüren! \r\nDieses Mal war ich wach! Es schien sehr wirklich: für eine Minute oder länger, mitten an einem warmen sonnigen Tag, war mein Atem sichtbar, als wäre es tiefster Winter. Einer der Priester bemerkte es, fiel auf die Knie und fing an zu beten.\r\nNiemand sonst konnte die Stimme hören; doch zumindest kann der Priester bezeugen, dass ich nicht dem Wahnsinn verfallen bin. Sollte ich womöglich Landgren darum bitten, die Angelegenheit in ein Gebet aufzunehmen?\r\nIch werde Jordan und Strass morgen sagen, dass sie neue Bewerber besser unter die Lupe nehmen sollen. Unter uns wimmelt es nur so von Ungläubigen, denen es nur nach Vernichtung der Untoten verlangt. Doch das ist nicht genug!\r\nDer Kommandant und der Bischof waren beide dafür zugänglich. Nicht, dass sie irgendeine Wahl hatten - insbesondere Bischof Strass schien sehr begeistert zu sein. Er sprach von einer Wiedergeburt des Kreuzzuges und schwor, diejenigen unter uns ausfindig zu machen, die schwach im Glauben seien.\r\nIch meinte zu ihm, dass er nicht übertreiben solle. Ich habe nicht vor, den Kreuzzug zu zerstören, doch mir gefällt die Idee eines Elitekaders der Gläubigsten, um auf des Lichtes Geheiß in [[Nordend]] zu handeln. Ich fürchte, dass seine Freundschaft zu LeCraft auf die Dauer schlechte Auswirkungen auf ihn haben wird. Beide haben sie jedoch ihren Nutzen.\r\nStrass' Gerede von einem neuen Kreuzzug hat mich zum Denken gebracht. Ich glaube, dass ich uns einen neuen Namen geben werde, sobald die neuen Streitkräfte bereitstehen. Er müßte sinngemäß an unsere neue Mission erinnern, gleichzeitig jedoch an die Vergangenheit. Ich werde mit dem Hochabt darüber reden.\r\nUnsere Gebete wurden erhört. Insbesondere der Hochabt war davon bewegt, welch Stärke, welch Klarheit und Unbeirrbarkeit in des Lichtes Stimme lag.\r\nDiejenigen unter uns, die nach Norden unterwegs sind, die Gläubigsten, sollen der [[Scharlachroter Ansturm|Scharlachrote Ansturm]] genannt werden. \r\nUnd ein Ansturm auf Nordend sollen wir sein! Das Geschwür der Geißel droht, das Haupt der Welt zu überwuchern und den Rest von uns zu ersticken. Die Zeit ist gekommen, die Schlacht zum [[Lichkönig]] selbst zu tragen.",},
			["Der weiße Hirsch und der Mond"] = { content = "-- ''(übernommen von den Schriftbannern im Zelt von [[Hamuul Runentotem]], oben auf der Anhöhre der Ältesten in [[Donnerfels]])'' --\r\nDie Erdenmutter erfüllte die mutigen Herzen ihrer reinen Kinder mit der Liebe zur Jagd. Denn die Kreaturen der ersten Dämmerung waren wild und gefährlich. Sie verbargen sich vor der Erdenmutter, suchten Zuflucht in den Schatten und an den rauen Orten des Landes. Die Shu'halo jagten diese Bestien, wo immer sie sich auch versteckten, und zähmten sie mit dem Segen der Erdenmutter.\r\nEiner der großen Geister entzog sich ihnen jedoch. [[Apa'ro]] (unter den [[Nachtelfen]] als [[Malorne]] bekannt) war ein stattlicher Hirsch mit schneeweißem Fell. Sein Geweih stieß bis ans Himmelszelt und das Stampfen seiner mächtigen Hufe war selbst bis in die tiefsten Tiefen der Erde zu vernehmen. Die Shu'halo trieben [[Apa'ro]] in einen Winkel der erwachenden Welt - und zogen die Schlinge enger, um den stolzen Hirsch zu fangen.\r\nDer große Hirsch versuchte zu entkommen und sprang hinauf in den Himmel. Doch als seine Flucht schon geglückt schien, verfing sich sein mächtiges Geweih in den Sternen und kam nicht mehr los. So sehr er auch kämpfte und um sich trat, konnte [[Apa'ro]] sich doch nicht aus dem Firmament befreien. Dort fand ihn [[Mu'sha]], als sie ihrem Bruder [[An'she]] zur Dämmerung folgte. [[Mu'sha]] sah den mächtigen Hirsch kämpfen und verliebte sich auf der Stelle in ihn.\r\n[[Mu'sha]] schloss einen Handel mit dem großen Hirsch ab - sie würde ihn aus den Fesseln der Sterne befreien, wenn er sie lieben und ihre Einsamkeit beenden würde.\r\n[[Mu'sha]] liebte [[Apa'ro]] und empfing ein Kind von ihm. Das Kind, ein Halbgott, wie manche behaupteten, wurde in den schattigen Wäldern der Nacht geboren. Sie nannten es [[Cenarius]], und er wandelte auf dem Sternenpfad zwischen der erwachenden Welt und dem Königreich des Himmels.",},
			["Der weiße Riese"] = { content = "#REDIRECT [[Weißer Riese]]", redirect = "Weißer Riese",},
			["Der Zweite Krieg"] = { content = "==Allianz und Sezession==\r\nAls die [[Horde]] im Zweiten Krieg die [[Menschen]] angriff, hatten die [[Hochelfen]] eigentlich wenig Interesse, in diesen Konflikt hineingezogen zu werden. Doch sie fühlten sich an ihren Schwur gebunden, die [[Allianz]] von [[Lordaeron]] zu unterstützen, und besonders ihren Kommandeur, Lord [[Anduin Lothar]], den letzten Nachkommen von König [[Thoradin]]. Lothars Familie hatte den [[Hochelfen]] in den [[Trollkriege]]n zur Seite gestanden, und so schickte König [[Anasterian]] widerstrebend einen Trupp Soldaten und Zauberer, die an der Seite der [[Allianz]] kämpfen sollte.\r\nDie [[Horde]] rekrutierte die [[Trolle]] der Amani und kurz darauf steckte die [[Horde]] die Grenzgebiete zu [[Quel'Thalas]] in Brand und metzelte viele Zivilisten der [[Hochelfen]] nieder. Voller Zorn über diese mutwillige Vernichtung von Leben haben sich die [[Elfen]] offiziell der [[Allianz]] angeschlossen und alle ihre Ressourcen dem Krieg gewidmet.\r\nMittlerweile wurde die [[Horde]] zurückgeschlagen. Die [[Orcs]] und [[Trolle]] jedoch haben ihr wahres Ziel bereits erreicht: so viele Runensteine des Verteidigungsschildes der [[Elfen]] zu stehlen und zu entweihen wie nötig. Der [[Hexenmeister]] [[Gul'dan]] setzte dann diese entwendeten Steine ein, um seinen verschlagenen [[Altar der Stürme]] anzutreiben.\r\nTrotzdem gewann die [[Allianz]] letzendlich den Zweiten Krieg und ein Großteil der besiegten [[Orcs]] wurden zusammentrieben und in Internierungslager eingeschlossen. In der Zeit nach dem Krieg waren die Kosten für den Wiederaufbau sehr hoch, vor allem, da der Betrieb der Internierungslager finanziert werden musste. Ohne einen gemeinsamen Feind stritten die Nationen der [[Menschen]] sich über Gebiete und die [[Hochelfen]] zweifelten an dem Wert dieser [[Allianz]]. Die [[Menschen|Menschheit]] schien die [[Hochelfen]] zu brauchen, sie hatten allerdings keinen Gegenwert zu bieten, da viele der Ressourcen der [[Allianz]] in den Betrieb der Internierungslager gesteckt werden musste.\r\nSchließlich sagte sich [[Anasterian]] von der [[Allianz]] los. Er machte die schwache Führung der [[Menschen]] direkt verantwortlich für die niedergebrannten Wälder im Grenzland von [[Quel'Thalas]]. König [[Terenas Menethil]] hielt dagegen, dass überhaupt nichts in Quel'Thalas überlebt hätte ohne die Hunderte tapferer Menschen, die ihr Leben geopfert hatten, um das [[Elfen]]land zu verteidigen. Doch trotz seiner Versucht, wieder diplomatische Beziehungen herzustellen, entschlossen sich die [[Elfen]], sich von der zerbröckelnden [[Allianz]] zu lösen. Damit lösten sie zugleich die nachfolgende Trennung von den Reichen [[Gilneas]] und [[Stromgarde]] aus.\r\n'''Quelle:''' wow-europe.com",},
			["Desdel Sternauge"] = { content = "Lord Desdel Sternauge war ein Adliger, der als Stellvertretender Kommandeur der Nachtelfenarmee unter Lord [[Kur'talos Rabenkrone]] diente, ihrem ersten Befehlshaber, als sie die erste Invasion der [[Brennende Legion|Brennenden Legion]] zurückschlug. Er fühlte sich in seiner adeligen Blutlinie sicher und war sehr stolz auf seinen hohen Rang. Ohne Erfahungen in bewaffneten Konflikten hatte er eine sehr hohe Meinung seiner Fähigkeiten im Kampf geformt als der [[Krieg der Uralten]] begann. Als [[Kur'talos Rabenkrone]] während des Krieges durch einen Agenten der [[Königin Azshara]] ermordet wurde, übernahm Desdel hastig den Oberbefehl. Sehr zu seiner Betroffenheit waren die eindringenden [[Dämonen]] sehr viel schwierigere Feinde als er erwartet hatte. Desdel hatte schon bald den Eindruck, dass seine Armee seinen Taktiken nicht vertraute. Er verzichtete auf seine höflichen Versuche diplomatisch zu sein und versuchte klarzustellen, dass er sowohl Respekt und Gehorsam erwartete. \r\nAls sich die Truppen der [[Brennende Legion|Brennenden Legion]] zurückzogen, ordnete Desdel thriumphierend seinen [[Nachtelfen]] an, sie zu verfolgen. Er war sich sicher, dass die Legion dank seiner Strategie geflohen war. Stattdessen aber hatten die [[Dämonen]] eine tödliche Falle gelegt und griffen die ahnungslosen [[Nachtelfen]] aus der Luft an. Desdel schaute hilfslos zu, als die [[Dämonen]] begannen große Behälter voller kochender roter Flüssigkeit über die [[Nachtelfen]]armee auszugießen. Innerhalb von Sekunden waren hunderte der Truppen verletzt, einige tödlich. \r\nKapitän [[Jarod Schattensang]] ritt zu Desdel und bat ihn um seine Befehle, aber der Adlige war in Panik geraten und konnte keine geben. Jarod erblickte eine weitere Gruppe [[Dämonen]] über Desdel und versuchte ihn aus dem Weg zu ziehen. Wütend über den Magel and Respekt des neuen Kapitäns seinem Vorgesetzen in Rang und Blutlinie gegenüber, befahl Desdel Jarod hinweg oder er würde in Haft genommen werden. Dies war Desdels letzter Fehler. Jarod riss sein Reittier gerade noch rechtzeitig zur Seite und entkam damit den qualvollen Tod. Die [[Dämonen]] drehten den Behälter um und die kochende Flüssigkeit ergoss sich auf Desdel und alle Begleiter in seiner Nähe. Desdel war innerhalb weniger Augenblicke verbrannt, sein Gesicht unkenntlich versehrt. Kurz nach Desdels Tod wurde [[Jarod Schattensang]] der neue Anführer der [[Nachtelfen]]armee.",},
			["Desolace"] = { content = "==Allgemeines==\r\nWeit im Westen von [[Kalimdor]] liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren. Desolace ist vom Rest des Kontinents recht abgeschirmt, einerseits durch das mächtige [[Steinkrallengebirge]] im Norden, andererseits durch [[Tausend Nadeln]] im Süden. Im Westen befindet sich die stürmische Küste und im Osten schließlich [[Mulgore]]. Desolace scheint unter einem natürlichen Fluch zu liegen, denn hier wächst nahezu nichts und ständig toben Stürme und schwarze Wolken verdunkeln den Himmel, erhellt durch grelle Blitze. Inmitten dieses mit Knochen gezierten Ödlandes hausen die fünf brutalen Stämme der [[Zentauren]]. Wer hier durchreist, wird keine anderen Lebewesen als die Zentauren antreffen, also sollte er sich besser gut ausrüsten. \r\n===Goliath-Skelette===\r\nHier liegen auch die massiven Goliath-Skelette zweier Kämpfer, die einander für immer anstarren, auf zwei Seiten eines großen Tals. Es wurde spekuliert, dass diese Knochen entweder [[Alte Götter]] oder [[Gesichtslose]] sind, obwohl sie trotz ihrer riesigen Ausdehnung am meisten den [[Naga]]s ähneln. \r\n==Orte==\r\n* [[Festung Donneraxt]]\r\n* [[Geistwandlerposten]]\r\n* [[Gelkis Dorf]]\r\n* [[Insel Ranazjar]]\r\n* [[Kodofriedhof]]\r\n* [[Kormeks Hütte]]\r\n* [[Magram Dorf]]\r\n* [[Nijelspitze]]\r\n* [[Sargeron]]\r\n* [[Schattenflucht]]\r\n* [[Schraubenbuddels Lager]]\r\n* [[Tal der Knochen]]\r\n* [[Tal der Speere]]",},
			["Detheroc"] = { content = "Der Schreckenslord '''Detheroc''' wurde von [[Kil'jaeden]] nach Azeroth geschickt wurde, um den Lichkönig [[Ner'zhul]] zu überwachen. Detheroc und seine zwei Brüder [[Balnazzar]] und [[Varimathras]] sollten über die Standorte der [[Brennende Legion|Brennenden Legion]] in Lordaeron wachen, als [[Archimonde]] und die Hauptstreitmacht der Legion nach Kalimdor zogen, um sich mit den geflohenen Orcs und Menschen, sowie den Nachtelfen zu beschäftigen, die sie in vergangenen Zeitaltern besiegt hatten. \r\nDetheroc begann jedoch zu bemerken, dass viel Zeit vergangen war, ohne dass sie ein Wort von Archimonde hörten. Schließlich stürmte [[Arthas]] in den Palast und informierte sie darüber, dass ihre Legion besiegt war und dass der Tod ihr Schicksal besiegeln würde. Aber die drei Brüder flohen ehe er zuschlagen konnte und versteckten sich in [[Tirisfal]]. Sie überzeugten [[Sylvanas Windläufer]] ihnen zu helfen, um Lordaeron zurück zu erobern und über die neu entstandenen [[Pestländer]] zu herrschen. Detheroc und seine Brüder übernahmen die Kontrolle der Hauptstadt und überfielen Arthas, aber der unverwüstliche [[Todesritter]] kämpfte sich durch ihre Streitkräfte und floh über das Meer zu seinem Meister in [[Nordend]]. \r\nAls Arthas fort war, konnten Detheroc und die anderen [[Schreckenslord]]s ihre Kraft auf Lordaeron konzentrieren. Aber als Varimathras Sylvanas fragte, sich an ihrer neuen Herrschaftsordnung zu beteiligen, weigerte sie sich, besiegte seine Streitkräfte und brachte [[Varimathras]] auf ihre Seite. Doch Detheroc war nicht so leicht zu besiegen. Er benutzt seine Macht der geistigen Beeinflussung, um den menschlichen General [[Garithos]] zu kontrollieren und auf seine Seite zu ziehen. Und als Sylvanas ihren nächsten Angriff gegen Detheroc einleitete, schickte er Garithos und seine Streitkräfte auf die ihren. Aber mit Varimathras an ihrer Seite, schaffte es Sylvanas Garithos zu besiegen und in Detheroc's Basis zu stürmen, wo sie ihn entzwei riss. Es ist aber auch möglich, dass sein Tod eine Illusion war, denn unter all den Schreckenslords, die in Lordaeron zur Überwachung zurückgelassen wurden, schien Detheroc die größten psychischen Kräfte zu haben, da er allein mit seiner Telepathie war fähig, Garithos’ gesamte Streitkräfte zu versklaven.",},
			["Dextren Ward"] = { content = "'''Dextren Ward''' wurde dabei erwischt, wie er Leichen aus dem [[Friedhof von Rabenflucht]] an [[Morbent Teufel]] verkaufte, ein Verbrechen, auf das der Tod steht. Und dennoch fordert [[Sturmwind]] nur seine Gefangensetzung. Man findet ihn derzeit im [[Das Verlies|Verlies]] von Sturmwind.\r\n==Fähigkeiten==\r\nDextren Ward beherrscht einen Furchterregenden Schrei, der in der Nähe befindliche Feinde 6 Sek. lang voller Furcht fliehen läßt. Desweiteren trifft sein Schlag einen Feind und fügt Waffenschaden plus 5 zu. \r\n'''Quellenangaben'''",},
			["Diathorus"] = { content = "Diathorus der Sucher ist ein Schreckenslord und führt die Dämonen im Dämonensturz in Eschental an. Er lebt irgendwo im Grabhügel auf dem Dämonensturz und um dort hinaufzugelangen, muss man nach einem Stieg in der Nähe des Denkmals der [[Horde]] für [[Grom Höllschrei]] suchen.",},
			["Die Aldor"] = { content = "#REDIRECT [[Aldor]]", redirect = "Aldor",},
			["Die Allianz zerbricht"] = { content = "=== Geschichte der Allianz===\r\n'''Die Allianz zerbricht'''\r\nIn den Jahren nach der Niederlage der Horde begann unter den Führern verschiedener Nationen der [[Allianz]] ein kleinmütiger Zank und Streit um Territorialansprüche und schwindenden politischen Einfluss. König [[Terenas Menethil]] von [[Lordaeron]], der Schutzherr der Allianz, hegte die Befürchtung, dass der Pakt, den sie in ihrer finstersten Stunde geschmiedet hatten, nicht mehr lange halten würde.\r\nTerenas hatte die Führer der Allianz dazu gebracht, dass sie Geld und Arbeitskräfte für den Wiederaufbau der Stadt [[Sturmwind]] bereitstellten, die während der Besatzung [[Azeroth]]s durch die Orcs zerstört worden war. In Verbindung mit den enormen Kosten für den Unterhalt der zahlreichen Orc-[[Internierungslager]] brachten speziell diese Abgaben viele Anführer – und hier besonders [[Genn Greymane]] von [[Gilneas]] – zu der Überzeugung, dass für ihre Königreiche eine Abwendung von der Allianz von Vorteil wäre. Erschwerend kam hinzu, dass die überheblichen [[Hochelfen]] von [[Silbermond]] der Allianz den Beistand aufkündigten und behaupteten, die schlechte Strategie der Menschen habe dazu geführt, dass ihre Wälder im [[Der Zweite Krieg|Zweiten Krieg]] niedergebrannt worden seien. Zwar rief Terenas den Elfen taktvoll ins Gedächtnis zurück, dass [[Quel'Thalas]] ohne die zahlreichen tapferen Menschen, die ihr Leben für seine Verteidigung gegeben hatten, vom Antlitz der Erde verschwunden wäre, doch die Elfen beharrten störrisch darauf, ihrer eigenen Wege zu gehen. Nach dem Abgang der Elfen entschieden sich auch [[Gilneas]] und [[Stromgarde]] für die Unabhängigkeit.\r\nDie Allianz zerfiel, doch noch hatte König Terenas Verbündete, auf die er sich verlassen konnte. Admiral [[Daelin Prachtmeer]] von [[Kul Tiras]] und der junge König [[Varian Wrynn]] von Azeroth blieben der Allianz treu ergeben. Außerdem versicherten die Zauberer des [[Kirin Tor]] unter dem Erzmagier [[Antonidas]] Terenas der unerschütterlichen Unterstützung durch [[Dalaran]]. Am erfreulichsten war vermutlich der Schwur des mächtigen Zwergenkönigs [[Magni Bronzebart]], der gelobte, dass die [[Zwerge]] von [[Eisenschmiede]] für immer in der Schuld der Allianz stehen würden, da sie [[Khaz Modan]] von der Herrschaft der [[Horde]] befreit hatte.",},
			["Die Arkatraz"] = { content = "#REDIRECT [[Festung der Stürme: Arkatraz]]", redirect = "Festung der Stürme: Arkatraz",},
			["Die Bestie"] = { content = "'''Die Bestie''' ist ein [[Kernhund]] in [[Obere Schwarzfelsspitze|Oberen Schwarzfelsspitze]] (UBRS).\r\nBei ihr kann man das beliebte Kürschnermesser \"\" finden und mit viel Glück erhält man den , wenn man ihr das Fell über die Ohren zieht. Dieser Balg wird für die Herstellung von exquisiten Rüstungen benötigt, wie z.B. der [[Brustplatte des Blutdurstes]], [[Kappe des scharlachroten Wissenden]] und die [[Gamaschen von Arcana]].",},
			["Die Botanika"] = { content = "#REDIRECT [[Festung der Stürme: Botanika]]", redirect = "Festung der Stürme: Botanika",},
			["Die einsamen Wölfe"] = { content = "'''Die einsamen Wölfe''' sind eine [[Gilde]] der [[Allianz]]. \r\nObwohl wir als einsame Wölfe durch die Lande ziehen, brauchen wir doch manchmal Hilfe, und es ist gut zu wissen, dass dort andere sind, die bereit sind, einem zu helfen und jederzeit gerne mit Rat und Tat zur Seite stehen. Ohne die Verpflichtung zu haben immer und überall teilzunehmen. Wir wollen unser [[Rollenspiel]], mit netten Leuten durchziehen und jeder möge dies tun wie er es will. Das oberste Ziel ist der gemeinsame Spaß am Spiel und ein freies [[Azeroth]].\r\n==weitere Eckdaten==\r\n* '''Rudelführer:''' [[Gibin]].\r\n* '''Rudeloffiziere:''' [[Amyrlin]] ([[XO]]), [[Lulea]], [[Moritas]], [[Maxvansash]]\r\n* '''Bewerbungen:''' über die Empfangshalle im Forum oder einfach mal Fragen.\r\n* '''Befreundete Gilden:''' [[Silberwölfe]], [[Amicus fidus]].\r\n==Geschichte==\r\nEs begab sich im Fruhjahr des Jahres 2006 das die Gilde <Blutrote Adler> vor die Hunde ging und wenn überhaupt nurnoch zwei Mitglieder ([[Alfar]] und [[Gibin]]) online waren. Von den Offizieren hatte man schon seit Monaten niemand mehr gesehen. So zogen wir beiden schon damals als einsame Wölfe durch die Lande, zusammen mit Minérva die die Adler schon verlassen hatte und Iskimya, die eigentlich wegen uns zu den Adlern stoßen wollte, entschieden wir uns eine eigene [[Gilde]] zu Gründen und der Name <Die einsamen Wölfe> erschien uns äußerst passend. Denn das wahren wir. Schnell wahren noch weitere gefunden die sich uns anschlossen. Leider sind viele inzwischen aus unterschiedlichen Gründen nicht mehr in der [[World of Warcraft]] anzutreffen. Aber aus den einsamen Wölfen von damals sind Freunde geworden und das Rudel hat Höhen und Tiefen erlebt. Wir haben in der [[Gilde]] stets ein äußerst freundschaftliches Verhältnis und sind zu der Erkenntnis gekommen das eine gut funktionierende [[Gilde]] nichts mit Größe zu tun hat sondern mit dem Verhalten ihrer Mitglieder. Wer nicht ins Rudel passt hat auch bei uns nichts zu suchen, aber diejenigen die sich im Rudel einbringen, erhalten die volle Unterstützung in allen Lebenslagen. Ein Wolf weiß das er sich auf sein Rudel verlassen kann. Rollenspiel wird bei uns betrieben aber auf eine recht freie und lockere Art und jeder so wie er mag. Der gemeinsame Spass am Spiel stand bei uns immer in Vordergrund und auch ehemalige Wölfe haben oft noch ein gutes Verhältnis zum Rudel. \r\n==Das Wappen==\r\nDas Wappen der einsamen Wölfe zeigt zwei (einsame) Wölfe die sich gefunden haben und nun gemeinsam herum tollen und sich zu einem starken Rudel zusammen tun. Zu den Farben ist nichts überliefert doch wird gemutmaßt das die Wölfe rot seinen da die ersten einsamen Wölfe ehemals <Blutrote Adler> wahren. Ihr Wappenrock wird von den einsamen Wölfen mit Stolz getragen.",},
			["Die Entweihten"] = { content = "Die [[Verlassene]]n der '''Entweihten''' wollen die wertvollen Resourcen des [[Arathibecken]]s für die [[Horde]] gewinnen.",},
			["Die Geißel von Lordaeron"] = { content = "==Inhalt==\r\nNach langen Monaten der Vorbereitung riskierten Kel'Thuzad und sein Kult der Verdammten schließlich den ersten Schlag, indem sie die Seuche des Untodes in Lordaeron freisetzten. Uther und die anderen Paladine untersuchten die infizierten Regionen in der Hoffnung, sie könnten eine Möglichkeit finden, die Seuche einzudämmen. Doch die Seuche breitete sich allen Anstrengungen zum Trotz weiter aus und wurde zur Zerreißprobe für die Allianz.\r\nWährend die Reihen der Untoten Lordaeron heimsuchten, nahm Prinz Arthas, der einzige Sohn von Terenas, den Kampf gegen die Geißel auf. Arthas gelang es zwar, Kel'Thuzad zu töten, aber die Reihen der Untoten schwollen dennoch mit jedem Soldaten an, der bei der Verteidigung seines Landes fiel. In seiner ohnmächtigen Wut auf diesen scheinbar unaufhaltbaren Feind griff Arthas zu immer extremeren Maßnahmen, um ihn zu besiegen. Schließlich warnten seine Kameraden ihn, dass er im Begriff wäre, seine Menschlichkeit aufzugeben.\r\nArthas' Furcht und Entschlossenheit wurden ihm zuletzt zum Verhängnis. Er spürte dem Ursprung der Seuche bis nach Nordrend nach, um der Gefahr für immer ein Ende zu machen. Doch stattdessen wurde Prinz Arthas schließlich selbst ein Opfer der schier unermesslichen Macht des Lichkönigs. In dem Glauben, sein Volk damit retten zu könnte, ergriff Arthas die verfluchte Runenklinge Frostgram.\r\nDas Schwert gewährte ihm zwar unauslotbare Macht, aber es stahl ihm seine Seele und verwandelte ihn in den größten der Todesritter des Lichkönigs. Nach dem Verlust seiner Seele und nicht mehr bei Sinnen führte Arthas die Geißel gegen sein eigenes Königreich. Am Ende schließlich ermordete Arthas gar seinen eigenen Vater, König Terenas, und zertrat Lordaeron unter den eisernen Absätzen des Lichkönigs.",},
			["Die Grünen Hügel des Schlingendorntals"] = { content = "Meister [[Hemet Nesingwary]] bei [[Nesingwarys Expedition]] im [[Schlingendorntal]] vertraute Barnil Steinkrug das Manuskript für seinen Roman, „Die Grünen Hügel des Schlingendorntals“, zum Korrekturlesen an. Dann wehte ein großer Windstoß durch das Lager und hat die Seiten überall verteilt. Er konnte die meisten Seiten wieder zusammensuchen, aber viele sind noch über den halben Dschungel verstreut. \r\n* '''Kapitel I''' war ziemlich fesselnd. Meister Nesingwary baut den Hintergrund der Geschichte auf und erwähnt seine Jagdgefährten, Barnil eingeschlossen. \r\n* '''Kapitel II''' war voll gestopft mit aufregenden Geschichten von der Panther- und Tigerjagd. \r\n* '''Kapitel III''' handelt von Sire Erlgadins und Lady Rouacks erstem Blattschuss mit einem Zwergengewehr. \r\n* '''Kapitel IV''' ist das große Finale.\r\n==Inhalt==\r\n'''Seite 1:''' Dafür, dass es unser erster Tag war, lief es heute eigentlich erstaunlich gut. Wir verbrachten einen Großteil der Zeit mit den Vorbereitungen für den Bau eines Stützpunkts. Ich hatte den idealen Ort dafür am Frischwasserzulauf eines Flussen ausgemacht. Den alten verlassenen Docks nach zu urteilen war dieser Ort sogar einmal bewohnt gewesen. Doch die ursprünglichen Bewohner sind längst Geschichte.\r\n'''Seite 2:''' Für diese Expedition habe ich Ajeck Rouack und Sire S.J. Erlgadin um mich geschart. Zudem steht mir mein getreuer Diener Barnil Stonepot zur Seite. Ich habe an der Seite Ajecks Vaters gar manche Schlacht zur Verteidigung der Allianz gefochten. Sie jetzt erwachsen zu sehen, berührt mich eigentümlich. Ihr Vater hat sie gut in der Waffenkunst unterrichtet. Sie geht so geschickt mit dem Bogen um, dass ich mich frage, ob Elfenblut in ihren Adern fließt. Sire S.J. Erlgadin entstammt dem menschlichen Adel. Sein Vater war der für seine Großzügigkeit bekannte Graf Erlgadin. Der Graf war es, der sich während des Wiederaufbaus von Sturmwind nach dem zweiten großen Krieg für bessere Arbeitsbedingungen für die Steinmetzgilde einsetzte. \r\n'''Seite 3:''' In den Jahren nach dem Verrat Sturmwinds an der Steinmetzgilde erfüllte die Rolle, die der Adel im Königreich spielte, Sire Erlgadin zunehmend mit Gram. Er wollte die Stellung, die er von seinem Vater im Oberhaus geerbt hatte, nicht länger wahrnehmen. \r\n'''Seite 4:''' Aber ich schweife ab. Dies hier soll ja keine politische Abhandlung oder Biografie werden. Vielmehr geht es hier um meine Erfahrungen mit der Großwildjagd in den grünen Hügeln des Schlingendorntals. Wir standen beim ersten Sonnenstrahl auf. Barnil machte das Frühstück. \r\n'''Seite 5:''' Mir fiel auf, dass Ajeck irgendwie irritiert wirkte. Wir hatten einen langen Weg vor uns und unsere Jagd versprach ziemlich gefährlich zu werden. Eine einzige Unachtsamkeit konnte schlimme Folgen haben. Doch Ajeck konnte ihren Blick anscheinend nicht von Barnil wenden, der am Flussufer ein paar Sachen auswusch. \r\n'''Seite 6:''' Gerade als ich fragen wollte, ob Ajeck denn nicht an der heutigen Jagdstrategie interessiert sei, griff sie nach ihrem Köcher, zog einen Pfeil heraus und schoss ihn just auf unseren armen Barnil ab. Aber der Schuss galt gar nicht Barnil. Denn als der offenen Mundes einen Schritt zu Seite machte, trieb ein großer Flusskrokilisk an die Oberfläche. Ajecks Pfeil steckte genau zwischen seinen großen Augen. \r\n'''Seite 7:''' Wir gingen Richtung Westen durch das Dickicht des Urwaldes. Langsam und vorsichtig bahnten wir uns den Weg durch das Unterholz. Der Morgen verging und nichts passierte. Nicht einmal ein Lufthauch regte sich im Tal. Bis zum Nachmittag hatte sich Unruhe in unserer Expedition breit gemacht. Barnil ließ es an der für einen Jäger so wichtigen Vorsicht mangeln. Er stapfte ziemlich ungeschickt vor sich hin und trat oft auf trockenes Laub oder herabgefallene Zweige. \r\n'''Seite 8:''' Nach einem solchen Fehltritt legte Erlgadin Barnil die Hand schwer auf die Schulter, Ajeck und ich schauten beiläufig. Wir dachten, Erlgadin würde Barnil ob seiner Unvorsichtigkeit endlich einmal die Leviten lesen. Aber Erlgadin wies mit einer langsamen Kopfbewegung in Richtung eines umgestürzten Baumes ganz in der Nähe. Zwei stechend schwarze Augen über einem Maul voller rasiermesserscharfer Zähne starrten uns an. \r\n'''Seite 9:''' Es handelte sich um eine männlichen Schlingendorntiger. Ehe ich auch nur nach meiner Büchse greifen konnte, hatte Erlgadin schon einen Armbrustbolzen abgefeuert. Der Bolzen verfehlte sein Ziel und traf den Tiger nur in der linken Flanke. Er versuchte zu fliehen, aber die Wunde war zu schwer. Das Wildtier taumelte noch eine Sekunden angeschlagen herum, ehe Barnil ihm mit seiner Wurfaxt den Gnadenstoß versetzte. \r\n'''Seite 10:''' Danach waren wir alle in Hochstimmung. Barnin gab eine Runde Met für alle aus. Aber die Freude sollte nicht lange währen, denn als wir den Kadaver für den Rücktransport zum Stützpunkt fertig machten, hörten wir unvermittelt ein fürchterliches Heulen. In all den Jahren habe ich noch nie etwas so Schreckliches gehört. \r\n'''Seite 11:''' Auf einer felsigen Anhöhe über uns hob sich gegen das Licht der untergehenden Sonne die Silhouette der größten Raubkatze ab, die ich je gesehen habe. Ich gab einen Schuss in Richtung des Tiers ab, das sich davon aber unbeeindruckt zeigte. Die Raubkatze ließ erneut ein Knurren ertönen, lauter noch als beim ersten Mal, und verschwand. Wir packten unsere Sachen und kehrten gut gelaunt ins Lager zurück. \r\n'''Seite 12:''' Ich hatte meinen Begleitern versprochen, dass wir am nächsten Tag Panther jagen würden, da deren Felle in Azeroth sehr gefragt sind. Diese Nachfrage lässt sich nur damit erklären, dass all die fähigen Jäger, Fallensteller und Pelzhändler fort sind und ihr Leben im Namen der Allianz lassen. \r\n'''Seite 13:''' Ajeck und Sire Erlgadin waren ganz erpicht darauf zu lernen, wie man Zwergengewehre einsetzt. Daher hatte ich die beiden Menschen angewiesen, ihre primitiven Distanzwaffen im Stützpunkt zu lassen. Barnil und ich statteten sie also mit den besten Feuerwaffen aus Eisenschmiede aus. \r\n'''Seite 14:''' Wir hielten uns nach Süden und folgten einigen frischen Pantherspuren. Kurz darauf kamen wir an eine Klamm, die von einer phantastischen Hängebrücke überspannt wurde. Ich musste sofort an Branns eindrucksvolle Beschreibungen des Gebiets denken, als ich diese technische Wunderwerk sah. Es wurde oft behauptet, die einheimischen Trolle seien primitiv und ungebildet, doch als ich auf dieses handwerkliche Meisterwerk blickte, erkannte ich mit einem Mal das außerordentliche Können, mit dem die Erbauer der Trolle das schier unüberwindliche Hindernis überwunden hatten. \r\n'''Seite 15:''' Bald darauf spürte Ajeck im Südwesten den Panther auf. Leise schlichen wird weiter, die Flinten im Anschlag. Das Knacken von den Zweigen im Unterholz ließ uns aufhorchen. Da war etwas. Ein Blick genügte, um mich mit Barnil zu verständigen. Er nahm langsam die Flinte herunter. Dieser Abschuss war nicht für uns bestimmt. Er sollte unseren menschlichen Freunden gehören. Unzählige Panther waren schon von unseren Flinten zur Strecke gebracht worden. Dieser hier würde von den Menschen erlegt. \r\n'''Seite 16:''' Ajeck und Sire Erlgadin standen unbeweglich und hielten ihre Flinten auf das dichte Buschwerk unter den sanft schwingenden Bäumen gerichtet. Die Mittagssonne brannte auf uns nieder. Ein kleiner Scheißtropfen rann an Erlgadins Schläfe herab, als er den Hahn spannte. In dem Moment, als der Hahn einrastete, teilte sich mit einem Mal das Dickicht und ein großer schwarzer Panther - ein schönes Exemplar - preschte hervor. \r\n'''Seite 17:''' Die Menschen nahmen den Panther aufs Korn, während dieser am Waldrand entlanglief. Die Läufe ihrer Flinten bewegten sich absolut synchron. Barnil warf mir einen drängenden Blick zu, aber ich schüttelte verneinend den Kopf. Diese Jagd war für die Menschen und nicht für Barnil und mich. Erlgadin feuerte, doch er verfehlte den Panther. Auf den starken Rückstoß des Gewehrs war er nicht gefasst. \r\n'''Seite 18:''' Die Büchse ruckte heftig zurück. Er verriss den Schuss seitwärts und geriet mit dem Lauf just unter Ajecks Flinte. Ajeck ihrerseits hatte genau diesen Moment abgepasst, um abzurücken. Der Schuss verirrte sich irgendwo in die Bäume. Ein Schwarm Vögel flog kreischend aus dem Blätterdach auf und flatterte aufgeregt in alle Himmelsrichtungen davon. Eine Wolke Pulverdampf stieg über einem Baum auf, fassungslos sahen wir mit an, wie ein gewaltiger Ast geradewegs auf den flüchtenden Panther fiel und ihm das Rückgrat brach. \r\n'''Seite 19:''' Im Laufe der Wochen vergrößerte sich unser Bestand an Panther- und Tigerfellen immens. Daher entschied ich, dass wir uns einem neuen Ziel zuwenden sollten: Raptoren. So dankbar die Menschen auch für die Schießübungen waren, die Barnil und ich mit ihnen machten, sie wollten doch von der Benutzung der Feuerwaffen Abstand nehmen. Ajeck kam mit ihrem fein gearbeiteten Bogen weit besser zurecht und Sire Erlgadin verließ das Lager ohnehin nie ohne seine stabile Armbrust. \r\n'''Seite 20:''' Wir machten uns beim ersten Tageslicht in Richtung Süden zu den Tkashi-Ruinen auf. Barnil äußerte sich zwar besorgt, dass wir auf Mitglieder des Blutskalpstamms treffen könnten. Ich erinnerte ihn dran, dass die Blutskalpe mehr mit der Vernichtung des verfeindeten Schädelspalterstamms beschäftigt waren. Ich brauche wohl nicht zu betonen, dass Barnil alles andere als beruhigt war. Ich für meinen Teil vertraute jedoch auf meine geladene Flinte, einen Ranzen Schießpulver und die drei versierten Jäger neben mir und machte mir keine Gedanken über einen möglichen Hinterhalt. \r\n'''Seite 21:''' Ich stand vor einer riesigen Höllenbestie auf dem Schlachtfeld und die Armee der brennenden Legion näherte sich von allen Seiten. Dagegen wirkt eine Bande Trolle so harmlos wie ein Kaninchen in den Hügeln von Dun Morogh. Wir passierten die Tkashi-Ruinen ohne Zwischenfall, worüber insbesondere Barnil sehr erleichtert war. Die Gruppe ging weiter westwärts Richtung großes Meer und streifte die Ruinen von Zul'Kunda im Süden. \r\n'''Seite 22:''' Als wir die Steilküste erklommen, sahen wir ihn: unseren ersten Raptor. Das Tier nahm uns noch nicht einmal wahr. Das einzige, was es von der Expedition mitbekam, war eine Kugel zwischen seinen Augen. Sire Erlgadin ließ ein herzlichen \"Hurra!\" ertönen und Ajeck nickte mir anerkennend zu. Ich kramte in meiner Tasche, weil ich mir zur Feier des Tages ein Pfeifchen gönnen wollte. Barnil kletterte auf die Anhöhe hinauf, um den Kadaver des Raptors zu holen. Außerst zufrieden betrachtete ich das tote Vieh. \r\n'''Seite 23:''' Die Freude über den Erfolg währte jedoch nicht lange. Denn als ich zum Horizont blickte, sah ich auf dem Hügel genau über dem armen Barnil gleich mehrere Silhouetten. \"Lauf, Barnil!\", schrie ich. Ajeck, Sire Erlgadin und ich feuerten aus allen Rohren auf die heranstürmenden Raptoren und deckten sie mit Kugeln, Pfeilen und Bolzen ein. Einer der Raptoren ging tödlich getroffen zu Boden. \r\n'''Seite 24:''' Unsere hastig abgefeuerten Schüsse ermöglichten Barnil die Flucht. Barnil stolperte den Hügel wieder hinunter und schloss sich uns erneut an. Wir schlugen uns in den Urwald, wobei das Rudel Schmetterschwanzraptoren jede unserer Bewegungen genau verfolgte. Aus Jägern waren Gejagte geworden. \r\n'''Seite 25:''' Ich führte die Gruppe in Richtung Meer und hoffte, dass wir an der Küste Schutz vor den Raptoren finden würden. Doch in unserer Hast waren wir zu weit nach Norden abgekommen und befanden uns auf einer gefährlich hohen Erhebung. Das war ein Fehler und ich war schuld. Plötzlich standen wir vor steil abfallenden Klippe, die Raptoren nur noch ein paar Schritte hinter uns. \r\n'''Seite 26:''' Ich trat langsam mit erhobener Flinte vor. Ich hatte diese mutigen Jäger ins Verderben geführt. Also wollte ich auch bei ihrer Verteidigung sterben. Schmetterschwanzraptoren sind besonders angriffslustig und bekannt für ihren unstillbaren Blutdurst. Zudem waren sie uns zahlenmäßig weit überlegen. Doch ich wollte verdammt sein, wenn sie mich und meine Kameraden töten könnten, ohne dabei selbst Verluste zu erleiden. \r\n'''Seite 27:''' Ajeck und Sire Erlgadin machten ihre Waffen bereit und gaben mir seitlich Deckung, während wir mit dem Rücken zum Wasser standen. Barnil seufzte ergeben und zog seine Axt. Die Schmetterschwanzraptoren waren schon ganz nah. Sie wurden langsamer, sie pirschten sich an ihre Beute heran. Wussten sie doch, dass wir ihnen nicht mehr entkommen konnten. \r\n'''Seite 28:''' Da geschah das Unglaubliche: neben uns hörten wir plötzlich das erschreckende Gebrüll des großen weißen Tigers. Augenblicklich drehten die Raptoren ab und stoben in alle Richtungen davon. Wir sahen nur einen weißen Blitz, als der Tiger an uns vorbeischoss und sich auf einen der Raptoren stürzte, Befehle waren unnötig. Wir alle vier wussten, dass es galt, die Beine in die Hand zu nehmen. \r\n'''Seite 29:''' Wir rannten so schnell es ging und ohne Pause zurück zum Basislager. Abends saßen wir noch lange still ums Lagerfeuer herum, wussten wir doch nur zu gut, dass wir unser Leben allein einer merkwürdigen Wendung des Schicksals zu verdanken hatten. Das sind die Risiken eines Großwildjägers. Man spielt mit dem Schicksal, wenn man es herausfordert. Und doch bekommt jeder von uns irgendwann die messerscharfen Zähne seines Schicksals zur spüren. Dieser Zwerg hier ist einfach nur froh, dass dieser Augenblick ihn nicht auf den grünen Hügeln des Schlingendorntals ereilt hat.",},
			["Die Kalu'ak"] = { content = "'''Die Kalu'ak''' (engl. The Kalu'ak) sind eine neutrale Fraktion der [[Tuskarr]] in [[Nordend]]. Die Tuskarr sind ein zähes, jedoch friedliches Volk, das seinen Lebensunterhalt mit Fischerei und Wahlfang bestreitet. Ihre Siedlungen sind kürzlich Opfer heftiger Angriffe geworden und sie heißen alle Veründeten willkommen, die ihnen zu Hilfe kommen.",},
			["Die Macht in der Tiefe"] = { content = "Das einzigartige Buch: '''‘Die Macht in der Tiefe’''' findet man bei einem Mitglied des [[Schattenhammerkult]]s in der [[Dunkelküste]]. \r\nObwohl das Buch ziemlich abgenutzt und zerfleddert ist, ist der Titel auf dem Buchdeckel noch gut lesbar. In diesem Buch findet sich eine Auflistung unaussprechlicher Namen mit viel sagenden Betitelungen, Verehrungsmethoden und bevorzugten Opferritualen bei denen sehr oft lebende, humanoide Kreaturen verwendet werden. Auf der Innenseite des Einbands stehen die Worte: ‘Knochengriffs Runen und Verhängnisse, Düsteres Viertel, [[Eisenschmiede]]. Inhaber: [[Gerrig Knochengriff]].’",},
			["Die Magiergilde"] = { content = "Bürger der Allianz! \r\nHattet ihr schon immer ein Interesse an den Geheimnissen der Magie? Beeindruckten euch schon von klein an die Ausstrahlung und Fähigkeiten eines Magiers? \r\nOder besitzt ihr bereits arkane Kenntnisse und wollt sie vertiefen? Oder euer Wissen weitergeben? Eure Magie in den Dienst des Gemeinwohles stellen? \r\nDie Magiergilde der Allianz stellt derzeit wieder Lehrlinge, Magier und Dozenten ein! Kommt für eine einschätzende Prüfung vorbei im Stormwinder Sanktum, im Magierviertel! \r\n(Vorherige briefliche Anmeldung bei Arkanistin Hecuba erforderlich.) \r\nWir bieten euch: \r\n* eine Unterkunft im Sanktum. \r\n* eine kostenlose Ausbildung zu höheren Kreisen der Magie. \r\n* die Möglichkeit selbst Forschungen auf einem oder mehreren Gebieten der Zauberei. \r\n* die Mitgliedschaft einer Organisation, die von den Häuptern der Allianz selbst Aufträge erhält. \r\nDie Magie mit euch allen! Lang lebe die Allianz!",},
			["Die Mechanar"] = { content = "#REDIRECT [[Festung der Stürme: Mechanar]]", redirect = "Festung der Stürme: Mechanar",},
			["Die Orakel"] = { content = "'''Die Orakel''' (engl. The Oracles) sind eine neutrale Fraktion in [[Nordend]]. Die [[Gorloc]]s vom [[Sholazarbecken]] sind eine Rasse reptilienartiger Kreaturen, die sich selbst als Hüter der Titanen Technologie sehen. Sie befinden sich im Kampf mit den [[Wolvar]] vom Stamm der Gollherzen.",},
			["Die Regeln des Instituts für Pfuschkunde"] = { content = "==Aufnahmevoraussetzungen und Verhaltensregeln==\r\nUm im Institut aufgenommen zu werden, muss man zu allererst ein Gnom oder eine Gnomin sein. Für alle anderen Vökler gibt es keine Chance, Pfuschkundler zu werden! Die Klasse, Ausrüstung, Stufe oder ähnliches spielen keine Rolle. Wichtig ist, dass man in den öffentlichen Channels (/s, /y) '''immer''' inCharakter bleibt. Weiterhin ist wichtig, dass man sich darüber im klaren ist, dass man mit jeder Aktion, die man im Spiel tut, das Institut repräsentiert. Das heißt: Beleidigungen, Belästigungen, Spam oder ähnliches werden nicht toleriert und können zu einem Rauswurf führen. Ein Streit oder eine Beleidigung inCharakter ist natürlich etwas anderes.\r\nDer Grundsatz lautet: '''Ihr seid Gnome, also verhaltet euch auch so!'''\r\n===Besucher===\r\n...sind Gnome, die noch nicht fest am Institut aufgenommen wurden. Sie dürfen den Institutskittel (Gildenwams) nicht tragen und repräsentieren offiziell noch nicht das Institut. Vielmehr ist dieser Rang dazu da, sich ein wenig bei uns umzusehen, die Leute kennenzulernen und kennengelernt zu werden. Wenn beide Seiten einverstanden sind, kann der Besucher schließlich als Praktikant aufgenommen werden.\r\n===Praktikanten===\r\n...sind diejenigen, die neu am Institut aufgenommen wurden. Ab diesem Rang darf der Kittel getragen werden und man kann die Berufe der anderen Mitglieder einsehen, indem man auf die Namen in der Gildenliste klickt. Praktikanten sind sozusagen \"probehalber\" im Institut und müssen zunächst eine Prüfung in Form eines öffentlich vorzutragenden Referats absolvieren, das auf eigenen Forschungen beruht, bevor sie zu Studenten werden können. Diese Prüfung sollte spätestens zwei Monate nach Aufnahme abgeschlossen werden.\r\n===Studenten===\r\n...gehören fest zum Institut und ''müssen'' keine Prüfung mehr absolvieren. Es wäre jedoch gern gesehen und eine Bereicherung, wenn sie dennoch hin und wieder ihre Forschungen der Öffentlichkeit präsentieren, denn das ist eine der wichtigsten Aufgaben des Instituts. Studenten können zu Wissenschaftlern aufsteigen, allerdings frühestens zwei Monate nach der Ernennung zum Studenten, indem sie eine wissenschaftliche Arbeit erstellen.\r\n===Wissenschaftler===\r\n...haben wesentlich mehr Rechte als Studenten. Sie haben mehr Einfluss auf Entscheidungen und können z.B. auch Vorträge halten. Allerdings haben Wissenschaftler auch die Pflicht, ihr Wissen durch Exkursionen und Forschungen ständig zu erweitern, das ist für sie noch wichtiger als für Studenten. Sie können mit einer Doktorarbeit zu Dozenten aufsteigen, jedoch wieder erst frühestens zwei Monate nach Bestehen der Wissenschaftler-Prüfung.\r\n===Dozenten===\r\n...sind die einflussreichsten Mitglieder des Instituts. Sie haben beinahe so viele Rechte wie die Institutsleitung, entscheiden bei allen wichtigen Dingen mit und können unterrichten. Sie sind Ansprechpartner für alle und die wichtigsten Personen des Instituts. Wenn ein Dozent das Institut verlassen will, muss er zunächst 76 Abmeldeformulare, bestehend aus jeweils 467 Seiten, ausfüllen, unterschreiben und in dreifacher Ausführung an die Regentinnen Gnomwinds, die Institutsleitung und sich selbst einreichen und bewilligen lassen. Dozenten können rekrutieren, Ränge verändern und all solche Dinge. Eine weitere Aufstiegsmöglichkeit gibt es nicht.\r\n===Institutsleitung===\r\n...hat nur geringfügig mehr Rechte als die Dozenten. Die Leitung ist für Organisationsfragen innerhalb des Instituts zuständig, kümmert sich um Rechte und Ränge und bespricht wichtige Entscheidungen mit den Dozenten.\r\n===Praktikant -> Student: Das Referat===\r\nWill ein Praktikant fest im Institut aufgenommen werden, muss er ein Referat schreiben. Das Thema kann frei gewählt werden, sollte aber dem ausgesuchten Spezialgebiet entsprechen und von den Dozenten freigegeben werden. Die Hintergründe und Informationen müssen selbst erforscht und belegt werden, z.B. durch Umfragen, Recherchen, Tests, Interviews oder Experimente. Das Referat selbst soll öffentlich vorgestellt sowie in schriftlicher Form abgegeben werden, sodass jedergnom Zugriff auf die Forschungsergebnisse hat. Der Vortrag des Referats sollte zwischen fünf und zwanzig Minuten dauern und sollte allgemein verständlich sein.\r\n===Student -> Wissenschaftler: Die wissenschaftliche Arbeit===\r\nUm vom Studenten zum Wissenschaftler aufzusteigen, muss eine wissenschaftliche Arbeit erstellt werden. Im Grunde ist sie dem Referat ähnlich, nur etwas umfassender, anspruchsvoller und länger. Das Thema muss wieder freigegeben werden und zum Spezialbereich passen. Der Vortrag sollte zwischen zehn und dreißig Minuten dauern, der Inhalt ins Detail gehen und zumindest für Gnome verständlich sein.\r\n===Wissenschaftler -> Dozent: Die Doktorarbeit===\r\nDie letzte Prüfung, die im Institut absolviert werden kann, ist sehr anspruchsvoll. Es wird ein Thema ausgewählt und freigegeben, das genau dem Spezialgebiet entspricht und stark ins Detail und auf die Ursprünge des Themas eingeht. Die Doktorarbeit sollte mehrere Seiten (ca. 3 oder mehr) umfassen. Der Vortrag kann dabei zwischen 15 und 45 Minuten dauern, in Sonderfällen auch länger. Er sollte für Gnome, zumindest aber für Pfuschkundler verständlich sein und muss, wie alle Prüfungen, öffentlich gehalten werden. \r\n==Das Rauswurfverfahren==\r\nGründe für den Rauswurf aus dem Institut sind:\r\n* Beleidigungen, Beschimpfungen, Belästigungen anderer\r\n* ooc-Verhalten innerhalb und/oder ausserhalb des Instituts\r\n* unentschuldigtes Fernbleiben über 3 Monate\r\n* andere, spezielle Gründe, die Fallweise entschieden werden\r\nDer Rauswurf erfolgt so:\r\n* zunächst gibt es eine Abmahnung\r\n* danach erfolgt (besonders beim Fernbleiben) evtl. eine Rückstufung in den Rängen\r\n* daraus folgt: wer lange fehlt ist irgendwann Praktikant\r\n* nach einer gewissen Zeit werden Praktikanten schlicht aus dem Institut entfernt\r\n* Bei Beschwerden / Anschuldigungen bekommt der Beschuldigte und der Kläger Gelegenheit, sich zu äussern und ein Gespräch mit der Institutsleitung zu führen\r\nEs gibt die Möglichkeit, sich nach einem Rauswurf wieder beim Institut zu bewerben. Jeder hat eine zweite Chance verdient. Ob diese aktzeptiert wird, entscheiden die Dozenten gemeinsam mit der Leitung und den Wissenschaftlern für jeden Fall einzeln.\r\n===Die Institutsstipendiumskasse===\r\nEs gibt eine Institutsstipendienkasse, in die jedes Mitglied monatlich einen ihm angemessen erscheinenden Betrag einzahlen sollte. Ausserdem können dort Gegenstände hinterlegt werden, die man selbst nicht braucht und anderen Mitgliedern des Instituts zur Verfügung stellen möchte. Von dem Vermögen werden Kredite an die Mitglieder ausgegeben, wenn beispielsweise ein Schreiter angeschafft werden soll oder etwas Gold zum lernen fehlt. Ausserdem können damit Institutsfeiern oder andere Aktionen finanziert werden, zum Eigengebrauch Einzelner ist es jedoch nicht gedacht.\r\nWas die Institutskasse als Vermögen verwaltet kann jederzeit bei der Leitung erfragt werden.\r\n'''''Mickie Mux,\r\nLeiterin des Instituts für Pfuschkunde,\r\nam 15. Juli 2007'''''",},
			["Die Scharlachrote Enklave"] = { content = "Die '''Scharlachrote Enklave''' liegt ganz im Osten der [[Östlichen Pestländer]] und ist im Besitz des [[Scharlachrote Kreuzzug|Scharlachroten Kreuzzuges]]. Vor kurzem jedoch wurde diese scheinbare Idylle gestört, denn [[Acherus]], die schwarze Zitadelle, erschien hoch am Himmel über der Enklave. Die meisten Menschen wären geflohen, sobald eine [[Nekropole]] der [[Geißel]] über ihren Köpfen erschienen wäre. Doch nicht so der [[Scharlachrote Kreuzzug]]. Im Laufe der Jahre haben Schlachten zwischen ihnen und der Geißel zu einigen der tragischsten Ereignissen in der Geschichte der Menschheit geführt. Und trotzdem stehen die Armeen der Geißel schon wieder hier und kämpfen gegen den Kreuzzug. ... Und die Falle der Geißel hat zugeschnappt. Die scharlachroten Armeen von [[Herdweiler]] und [[Tirisfal]] sind hierher gekommen um ihre Truppen zu unterstützen ... gerade rechtzeitig, um noch zu sehen, wie ihre Enklave in Flammen steht. Falls sie jetzt umkehren sollten, werden sie mit dem Rücken zur Geißel in Acherus kämpfen müssen. Ihnen bleibt nur eine Wahl: IHR ENDE. Und so bereiten sich die Scharlachroten Streiter auf ihr letztes Gefecht vor.\r\n==Orte==\r\nZur Scharlachroten Enklave gehören:\r\n* [[Hafen des Königs]]\r\n* [[Havenau]]\r\n* [[Kapelle der scharlachroten Flamme]]\r\n* [[Krypta der Erinnerung]]\r\n* [[Neu Ava]]lon\r\n* [[Scharlachrote Wache]]",},
			["Die Schatten"] = { content = "==Die Schatten==\r\nDie Schatten verstehen sich als ooc-Schlachtgruppe, die die Mehrzahl ihrer Charaktere aus den Reihen der Gilde Exodus beheimatet. Darüberhinaus finden zahlreiche andere Raidwillige ihren Platz bei den Schatten ohne sich dem Zwang einer Gilde zu beugen. Die Schatten versuchen sich harmonisch in das Bild der Forscherliga einzufügen und auch auf Anspielung angemessen zu reagieren.\r\n==Einleitung==\r\nTrommeln erklingen. Dumpf der Schlag. Asche schwebt in der Luft. Nur das knistern eines Feuers ist zuhören. In seinem Schein sieht man fünfundzwanzig Wesen. Elfen, Zwerge, Menschen auch einige Gnome erheben sich nun langsam. Sie alle schauen auf die Gestalt zu ihren Füßen…\r\n„Ist er tot?“ – „Tot?!“ – „Er ist tot. Er ist tot! Illidan ist tot!“\r\nSo geschah es vor wenigen Tagen. Der Tempel wurde von den Schatten zurück erobert. Es war ein schwerer Weg und viele sind dabei zurück geblieben. Nun öffnet sich für die Helden ein neues Tor: Sunwell!\r\nWollt ihr dabei sein? Wollt ihr die Schatten auf ihrer ruhmreichen Schlacht begleiten? Ergreift eure Chance auf unvergessliche Abenteuer....\r\n==Bewerbung==\r\nZur Zeit suchen wir nicht nach Verstärkungen, bzw. Ergänzungen unseres Spielerpools.\r\n==Raidzeiten==\r\n* Sonntags: 18:30 - 21:00 Uhr\r\n* Montags: 19:30 - 23:00 Uhr\r\n* Dienstags: 19:30 - 23:00 Uhr\r\n* Mittwochs: 19:30 - 23:00 Uhr",},
			["Die Schatten kehren zurück"] = { content = "Nach fast dreizehn Jahren Frieden machten plötzlich wieder Gerüchte über einen Krieg die Runde. Die Agenten des Königs meldeten, dass ein junger, ehrgeiziger Kriegshäuptling aufgetaucht war, der die wenigen verbliebenen Orc-Klans zu einer Elitetruppe vereinte. Erklärtes Ziel des jungen Kriegshäuptlings war es, die Internierungslager zu erstürmen und sein Volk aus der Gefangenschaft zu befreien. Im Versuch, einen ihrer gefangenen Krieger zu befreien, hatte die „neue Horde“, wie sie genannt wurde, unverfroren die im Norden gelegene Stadt Stratholme angegriffen. Die Horde zerstörte sogar Durnholde – die Festung, die für die Sicherheit der Internierungslager verantwortlich war – und ermordete die leitenden Offiziere. König Terenas schickte Uther und seine Paladine aus, um den Aufstand des Kriegshäuptlings niederzuschlagen, doch die listigen Orcs blieben unauffindbar. Der junge Kriegshäuptling entpuppte sich als taktisches Genie – nicht einmal mit größter Anstrengung konnte Uther seine unerwarteten Angriffe verhindern. Während der neuerliche Aufstand der Orcs in vollem Gange war, erhielt König Terenas noch von anderer Seite schlechte Nachrichten. Gerüchten zufolge waren in einigen nördlichen Provinzen eine ganze Anzahl so genannter „Totenkulte“ entstanden. Die Kulte lockten die entrechteten und niedergeschlagenen Bürger von Lordaeron an und boten ihnen „ewiges Leben“ auf Erden als Alternative zur Knechtschaft unter dem König. König Terenas wusste, dass sich nach vielen Jahren des Friedens und der Ruhe Unheil über seinem Land zusammenbraute. Einen gewissen Trost spendete ihm die Tatsache, dass Lordaeron noch jede Prüfung erduldet und überlebt hatte, die ihm auferlegt worden war – und dass seine Verteidiger, neue wie alte, es wohlbehalten in eine neue Morgendämmerung geleiten würden.",},
			["Die Schlacht von Grim Batol"] = { content = "=== Die Schlacht von Grim Batol===\r\nNach der Zerstörung des zweiten [[Dunkles Portal|Dunklen Portals]] konnte die Allianz erfolgreich den größten Teil der in Azeroth verbliebenen abtrünnigen Orc-Klans aufspüren. Die kurz nach dem Zweiten Krieg erbauten [[Internierungslager]] für die Orcs waren zum Bersten überfüllt und wurden rund um die Uhr bewacht. Der neu eingetroffene [[Kriegshymnenklan]] hatte sich zwar dem Zorn der Allianz bislang entziehen können, doch gab es nur eine Gruppe – den [[Drachenmalklan]] –, die stark genug war, den unsicheren Frieden in [[Lordaeron]] zu stören. Dem Drachenmal-Klan unter Führung des heimtückischen Hexenmeisters [[Nekros]] war es mit seinen Drachen sowie kleinen Infanterie-Einheiten gelungen, einen großen Teil des nördlichen [[Khaz Modan]] zu erobern und zu besetzen. Mit Hilfe eines mächtigen, [[Dämonenseele]] genannten Artefakts hielt Nekros die Drachenkönigin [[Alexstrasza]] und ihren roten Drachenschwarm unter seiner Kontrolle. In der uralten Zwergenfestung [[Grim Batol]] stellte Nekros eine stattliche Armee auf und schmiedete Pläne, die besiegte Horde wieder zu vereinen. Doch so groß die Macht des Hexenmeisters auch war, die Intervention des tollkühnen Magiers [[Rhonin]] vereitelte Nekros‘ Pläne. Ronin und seine Gefährten zerstörten zusammen mit Widerstandskämpfern der [[Zwerge]] die Dämonenseele und befreiten Alexstraza aus dem Banne der Orcs. Die rachsüchtigen roten Drachen löschten den Drachenmal-Klan aus und zerstörten damit die letzte Bastion der Orcs auf dieser Welt. Nach dem Tode von Nekros, dem letzten Hexenmeister ihres Volkes, verfielen die Orcs in den überfüllten Internierungslagern in eine lähmende Lethargie. Nachdem ihr Kampfgeist und ihre Bereitschaft zu sterben gebrochen waren, sahen sich die Orcs nicht mehr als Krieger und legten damit das letzte Erbe der stolzen Kultur ab, die sie hervorgebracht hatte.",},
			["Die Situation von Seenhain"] = { content = "Die '''Situation von Seenhain''' ist ein Bericht, verfasst von [[Magistrat Solomon]], der ausführlich die Ereignisse beschreibt, die sich im [[Rotkammgebirge]] zugetragen haben. [[Seenhain]] ist einer ständigen Belagerung ausgesetzt und wenn die Bewohner keine Verstärkung bekommen, ist ihre Niederlage so gut wie besiegelt. Diese Botschaft ist deshalb von äußerster Wichtigkeit und muss unverzüglich bei [[General Marcus Jonathan]] in [[Sturmwind]] abgeliefert werden. \r\n \r\n==Inhalt==\r\nMein Lord,\r\nEs herrscht Krieg. Uns droht die Verdammnis.\r\nAls Magistrat der Stadt Seenhain ist es meine Pflicht, Eurer Majestät von den jüngsten militärischen Aktivitäten in Eurer östlichsten Kolonie zu berichten. Auf den folgenden Seiten wird Euch Bericht erstattet, wie die Situation von Seenhain, hoch oben im Rotkammgebirge, ist.\r\nDer Verlust von Burg Steinwacht wiegt schwer. Von der Allianz zwischen den Orcs des Schwarzfelsklans und dem Hexenmeister namens Morganth habe ich Euch ja bereits berichttet. Der Schwarzfelsklan hat fürchterlich gewütet. Sie standen zweifellos unter dem Einfluss von böser Magie von Morganth. Viele der besten Soldaten Seiner Majestät haben bei der Verteidigung der Burg ihr Leben gelassen. Aber letztlich war alles umsonst.\r\nMerkwürdigerweise ließ Morganth seine Orctruppen jedoch kurz nach dem brutalen Sieg umkehren. Der Hexenmeister ließ im Nordosten einen arkanen Turm errichten. Mit Hilfe seiner Macht schuf er sich eine kleine Armee aus Schattenfellgnollen, die jeden seiner bösartigen Befehle ohne zögern ausführen. Sowohl Orcs als auch Menschen sind der teuflischen Brut des Hexenmeisters schon zum Opfer gefallen. Was den Verrat zwischen Morganth und Gath'Ilzogg, dem Kriegsherrn des Schwarzfelsklans angeht, so können wir zurzeit nur Vermutungen anstellen.\r\nZu allem Übel scheinen die Orcs alles daran zu setzen, die guten Untertanen seiner Majestät abzuschlachten. In den vergangenen zwei Wochen hat der Schwarzfelsklan eine ruchlose Offensive gegen Seenhain geführt. Viele tapfere Männer haben ihr Leben gelassen. Die Orcs rückten mit solcher Geschwindigkeit und Gewalt vor, dass die Immerruhbrücke einstürzte. Unsere Kriegsbestände gehen bedrohlich zu Neige. Es fehlt uns an Verbänden für die Verwundeten.\r\nIch bitte ihre Majestät hiermit um Unterstützung der guten Menschen von Seenhain in dieser Zeit der Not. Wir brauchen nicht nur Soldaten, sondern auch neues Kriegsgerät als Ersatz fpr das, was wir in der Schlacht verloren haben. Auch Essen und Baumaterial werden knapp. Ich bitte mein Lord, helft uns die letzte Bastion zwischen Mensch und Orc zu halten. Der Feind darf nicht im Königreich Sturmwind einfallen.\r\nDoch ich befürchte, dass im Kessel der Verderbnis, den die Nordlande inzwischen darstellen, noch viel größeres und dunkleres Übel gärt. Es ist daher unbedingt notwendig, dass das Königreich Sturmwind Maßnahmen ergreift, wollen wir nicht bald schon relikte der Vergangenheit oder Sklaven des Feindes sein.\r\nGezeichnet\r\nMagistrat Solomon\r\nStadt Seenhain\r\nKönigreich Sturmwind",},
			["Die Wanderer"] = { content = "'''''W'''ir sind dort, wohin es uns treibt.'' \r\n'''''W'''ir wandern dorthin, wo wir gebraucht werden.'' \r\n'''''W'''ir gehen hin, wohin wir wollen.'' \r\nDie Entstehung der Wanderer ist nichts was man in viele Worte fassen braucht. Die Sehnsucht nach fremden Orten, Kulturen, wie der Wunsch diesen Traum nach Wissen nicht alleine zu träumen führte einst einige Wesen zueinander. \r\nDie Zeit schien bereit für eine kleine Gilde, bereit für eine kleine Familie die sich zusammenschloss um sich in ihrem gemeinsamen bestreben zu unterstützen. Miteinander und füreinander ging und geht die Gilde ihren Weg und ihre stärkste Kraft dabei war und ist ihre Freundschaft zueinander. \r\nUnd die Familie wuchs…\r\n----\r\nWurde Euer Interesse geweckt?\r\nDann wandert einmal zu unserem Gildenhaus und werft einen Blick auf die in der Eingangshalle.\r\nIhr seid herzlich Willkommen!\r\nNatürlich könnt Ihr Euch bei offenen Fragen auch an die Mitglieder des Rates wenden:\r\n'''Ratsvorsitzende:'''\r\n*[[Graanzíìs Oaksplint]]\r\n*[[Kolarniis Anvilstone]]\r\n*[[Tilgalia Mohnblume]]\r\n'''Ratsmitglieder:'''\r\n*[[Dianora Bärenfels]]\r\n*[[Lanmara]]\r\n*[[Merkinn Wyvernspear]]\r\n*[[Nithrade Mondtänzer]]\r\n*[[Sorcloom]]\r\n*[[Thea]]",},
			["Die Wandersleute"] = { content = "'''Die Wandersleute''' sind eine Allianz-Gilde unterschiedlicher Rassen und Klassen. Vom Anfänger bis zum Experten ist alles vertreten. Der Hauptfokus der Gemeinschaft liegt auf dem PVE-Teil des Spiels. Dabei gilt jedoch stets das [[Rollenspiel]]gebot, wonach jedes Gildenmitglied angehalten ist, Rollenspiel zu fördern und seinen Charakter glaubhaft zu vertreten. Im Vordergrund steht für die Wandersleute das Erkunden neuer Welten und Erforschen dunkler Geheimnisse. Die Wandersleute gehören zu den ältesten Gilden der Forscherliga.\r\n==Das Miteinander==\r\nEin Wanderer pflegt einen kameradschaftlichen Zusammenhalt zu anderen Gildenmitgliedern und unterstützt diese nach seinen Möglichkeiten. Der Wanderer ist gut informiert, kennt die Gepflogenheiten und Geschichte seiner Welt und weiß diese in seinem Alltag einzubauen. Es ist jedem Wanderer eine Freude, seine Rasse und Klasse in einem rollengetreuen Verhalten zu präsentieren. Die Begriffe Zusammenhalt, Hilfsbereitschaft und das Einstehen für die Gemeinschaft sind einem Wanderer in Fleisch und Blut übergegangen. Es ist jedem Wanderer eine natürliche Ehre, den Namen der Gilde nach außen in rechtem Licht erscheinen zu lassen.\r\nDie Gilde der Wandersleute zeichnet sich durch ein enges Gemeinschaftsgefühl ihrer Spieler aus. Mehrmals im Jahr finden mittlerweile unregelmäßig Treffen zu unterschiedlichen Anlässen wie Mittelaltermärkten, Brettspielabenden oder auch einfach nur so statt. Man kennt sich, man schätzt sich, man vertraut einander.\r\n==Struktur==\r\nNeue Mitglieder erhalten den Status eines Spaziergängers. Nach einiger Zeit, in der Anwärter selbst und auch die Gilde abwägen, ob man zueinander passt, wird der Spaziergänger feierlich zum Wanderer ernannt und bekommt seinen Gildenwappenrock überreicht.\r\nWeltenwanderer ist der Rang für etablierte Mitglieder, welche sich dadurch ausgezeichnet haben, der Gilde hilfsbereit zur Seite zu stehen und ihrem Namen alle Ehre zu machen. Der Weltenwanderer begleitet neue Mitglieder, um sie in die Gemeinschaft einzuführen und stellt diese der Gemeinschaft vor.\r\nDie Pioniere der Wandersleute zeichnen sich dadurch aus, dass sie Ansprechpartner und Seelentröster für Anliegen aller Art sind. In ihren Händen liegt das Geschick das Gilde; sie unterstützen den Gildenmeister mit allen ihnen zur Verfügung stehenden Mitteln.\r\nDie Pioniere der Wandersleute sind aktuell: [[Andruin]] Namenlos, [[Boal Kromsson]], [[Esrin Vothan]], [[Fayt]] Leingod, [[Linly Bergvist]], [[Mondran Bludklippe]], [[Mortarius Pi]], [[Nighower]] und [[Sensa]] Tundaban. Der Gildenmeister ist [[Elrud der Besonnene]].\r\n==Aktivitäten==\r\nDie Gilde veranstaltet unregelmäßig Gildentreffen, bei denen Geschichten erzählt, weiteres Vorgehen der Gilde besprochen und Wanderer geehrt und befördert werden. Der Ort für ein Treffen wird meist kurzfristig bekannt gegeben. Die Teilnahme an den Gildentreffen ist freiwillig, aber wird jedem Gildenmitglied sehr ans Herz gelegt.\r\nIst ein Gildenmitglied mehr als drei Monate inaktiv, wird es aus dem Kreis der Gilde in die Halle der Ehemaligen verschoben. Jedoch ist es kein Problem, wieder in den Kreis der Gilde erhoben zu werden, falls die Inaktivität des Spielers beendet ist.\r\n===Gildenkasse===\r\nDie Gilde besitzt außerdem ein Gildenkonto. Jedes Mitglied der Gemeinschaft kann dort Goldbeträge spenden. Diese Goldbeträge werden ausschließlich für spezielle Anliegen der Gesamtgilde verwendet. Zudem darf jedes Vollmitglied dort Gold ausleihen. Über größere Ausgaben entscheidet die Gildenversammlung.\r\n==Kommunikation==\r\nUm ihre Mitglieder ständig auf dem Laufenden zu halten und eine Kommunikation mit nicht anwesenden Freunden zu ermöglichen, unterhält die Gilde ein . Wichtige Hinweise und Planungen sind dort hinterlegt. Dort können Gildenangehörige sich in verschiedenen Rubriken austauschen und einige wichtige Informationen zu allen Mitgliedern der [[Gilde]] ansehen. Die Gildenpioniere informieren dort auch regelmäßig über Veranstaltungen und ein jeder kann dort selbst nach Hilfe für Abenteuer suchen, Gefundenes anpreisen oder Gesuchtes erfragen. Auch wenn man mal Probleme rund um unsere Welt hat, gibt es dort viele hilfreiche Hände. Unser Gildenkartograph [[Rambalar]] hilft gerne bei den ersten Schritten und dem Geheimwort für den Zugang.\r\n===Stimme der Wanderer===\r\nZusätzlich existiert die “Stimme der Wanderer”. Über die Stimme ist es den [[Wandersleute]]n möglich, sich an fingerfaulen Tagen sowie an geselligen Ereignissen in gruppenbezogene Räume zurückzuziehen, um dort mit der Stimme des Spielers und nicht mit der Tastatur zu kommunizieren.",},
			["Dimensius"] = { content = "'''Dimensus''' ist ein mächtiger [[Fürst der Leere]], der seine Leerenarmeen auf [[K'aresh]], die Heimatwelt der [[Astrale]]n, losließ, um alles, was ihm im Weg stand, zu vernichten. [[Das Konsortium]] jagt Dimensius schon seit tausend Jahren. \r\n==Aktuelles==\r\nAuf der [[Manaschmiede Ultris]] im [[Nethersturm]] befindet sich der Riss im [[Nether]], durch den Dimensius, der Fürst der Leere, auch in die [[Scherbenwelt]] gekommen ist. Dieser Riss bildet eine Verbindung zwischen Dimensius und der Leere und macht ihn unverwundbar. \r\nWenn es gelingt, diese Energieleitung, mit der Dimensius sich aus dieser Existenzebene zurückziehen kann, zu verschließen, kann man sie und Dimensius vernichten. Doch dazu muss man zunächst Fragmente von Dimensius von den Leerkreaturen, die für ihn die Drecksarbeit erledigen, sammeln. Mit diesen Fragmenten kann man die Bombe einstellen, die die Leerenergieversorgung auf der [[Manaschmiede Ultris]] zerstören kann. Dann wird Dimensius’ Verbindung zur Leere unterbrochen und er kann sich nicht mehr verteidigen. Wenn der Riss durch den Phasenstörer vernichtet wurde, kann Dimensius mit Kraft und Magie angegriffen werden. \r\nUm die zerstörte [[Manaschmiede Ultris]] herum findet man die Überbleibsel von Dimensius’ Taten. Sickernder Schlamm verschmutzt die Teiche um Ultris herum. Direkt unter diesen Teichen, wo sich nun der Stützpunkt des [[Astraleum]]s befindet, findet man noch mehr Müll in Form von Leerabschaum. Der beste Weg, ihn zu entsorgen, ist, den Schleim mit Hilfe von Elektroschocks in Kugeln zu verwandeln. Die Entladung, die dabei entsteht, löst den Schleim in seine Urform auf.",},
			["Dimetrodon"] = { content = "Eigentlich galten '''Dimetrodons''' genau wie [[Stegodon]]s und [[Pteradon]]s als ausgestorben, bis eine Expedition der [[Forschergilde]] in den [[Un'Goro]] Krater von lebenden Exemplaren überrascht wurde. \r\nAuch in der Scherbenwelt hat sich diese Art entwickelt.\r\n==Bekannte Arten==\r\nIm Krater von [[Un'Goro]] finden sich neben den normalen Dimetrodons auch alte Dimetrodons, die grösser und agressiver sind. Der [[Goblin]] [[Sappalot]] ist besessen von der Idee aus den Schuppen der Dimtetrodons und [[Pterrordax]] einen Flieger zu bauen. Falls man ihm dabei hilft diese zu sammeln, findet man auch gelegentlich Knochen, die man bei [[Funks Nilminer]] abgeben kann.\r\n===Teufelsfeuerdimetrodon===\r\nTeufelsfeuerdimetrodons gehören gedeihen in der glühenden Hitze des [[Schattenmondtal]]s auf der [[Scherbenwelt]] in der Nähe der Lavaseen. Sie haben die leckersten Milzen aller Zeiten und das Beste ist, dass sie schon vorgekocht sind. \r\n==Besondere Tiere == \r\n* '''Teufelsbuckel der Große''' - Teufelsbuckel der Große ist ein GIGANTISCHER Dimetrodon und führt die Teufelsfeuerdimetrodons im [[Schattenmondtal]].",},
			["Disharmonische Woge"] = { content = "Disharmonische Wogen sind [[Wasserelementare]] in den [[Östliche Pestländer|Östlichen Pestländern]]. Sie wurden als eine Truppe von Elementarspähern wurde in diese Gebiete von [[Lordaeron]] entsandt. Doch die Krankheit dieses Orts verdrehte und infizierte sie.",},
			["Disteltal"] = { content = "Das Disteltal im Südwesten von Tanaris ist ein sehr gefährlicher Ort mit merkwürdigen Bestien. Diese Kreaturen gehören zur Rasse der [[Bäumlinge]] und werden '[[Tausammler]]' genannt. Sie können in speziellen Drüsen Wasser speichern. Die [[Schildkröte]] [[Tooga]] hat sich hierhin vollkommen verirrt und braucht einen Begleiter zurück zur Küste.",},
			["Disteltau"] = { content = "Disteltau, der von den [[Bäumlinge]]n in [[Tanaris]] gewonnen wird, war der Hoffnungsträger der [[Goblins]] in [[Gadgetzan]] für eine alternative Flüssigkeitsquelle in der Wüste. Heraus kam ein eklig schmeckendes Sekret, durch welches [[Marin Noggenfogger]] in dem Versuch den Geschmack mit [[Violetter Tragan|Violetten Tragan]] zu neutralisieren, [[Noggenfoggers Elixier]] erfand.",},
			["Doktor Bumm"] = { content = "Der [[Goblin]]-Techniker Sparky Überschub hat sich geweigert, während seiner Arbeit am [[Raketenschiff X-52]] in [[Area 52]] seinen Helm zu tragen, und hat sich in den berüchtigten Dr. Bumm verwandelt. Danach hat er sich mit einem Großteil der Pionierausrüstung nach Nordosten aufgemacht. Seitdem sind er und seine Bummbots in Dr. Bumms Lager eine große Bedrohung für [[Area 52]].",},
			["Doktor Theolen Krastinov"] = { content = "'''Doktor Theolen Krastinov''', der Schlächter, befindet sich in der [[Scholomance]]. Er ist für den Tod von Tausenden verantwortlich. \r\n==Fähigkeiten==\r\n* '''Rückhand''' - Schlägt einen Feind mit dem Handrücken ins Gesicht und betäubt ihn 2 Sek. lang. \r\n \r\n* '''Verwunden''' - Verwunden fügt einem Feind 15 Sek. lang alle 3 Sek. Sek. körperlichen Schaden zu. \r\n \r\n* '''Wutanfall''' - Wutanfall erhöht 2 Min. lang das Angriffstempo des Zaubernden um 60% und den von ihm zugefügten körperlichen Schaden um 50.",},
			["Dokumente des Scharlachroten Kreuzzugs"] = { content = "Die '''Dokumente des Scharlachroten Kreuzzugs''' werden von [[Meven Korgal]], dem Roten Boten, im [[Lager der Kreuzzügler]] in [[Tirisfal]] verwahrt. Die Entscheidenden Informationen, die darin enthalten sind, müssen zum Vorgesetzten von [[Exekutor Arren]], [[Exekutor Zygand]], nach [[Brill]] gebracht werden, denn mit diesen Informationen können die [[Verlassene]]n dem [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzug]] einen entscheidenden Schlag versetzen. Die Dokumente, die [[Exekutor Arren]] damit der Stadt [[Brill]] zur Verfügung stellt, verschaffen den [[Verlasse]]nen dort genau die Atempause, die sie in ihrem Kampf gegen den [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzug]] benötigen. Sie kennen jetzt dessen genaue Aufenthaltsorte überall in [[Tirisfal]]. Aber leider haben die [[Todeswache]]n noch ganz andere Sorgen, denn die Armee des [[Lichkönig]]s wächst jede Nacht an. \r\n==Inhalt==\r\nEs steht Euch frei, diese Informationen weiterzugeben.\r\nRegionalkommandantur Tirisfal\r\nHauptmann Melrose\r\nHauptmann Vachon\r\nHauptmann Perrine\r\n'''Anweisungen auf Befehl des Hochlords'''\r\nHauptmann Perrine, baut Eure Position am Euch zugewiesenen Südwestturm weiter aus. Weiterer Nachschub wird zu einem späteren Zeitpunkt entsandt. Bis dahin versorgt Euch auf den umliegenden Gehöften mit allem Nötigen. Zudem benötigen wir weitere Informationen über die Organisation der Untoten in Brill.\r\nHauptmann Vachon, es scheint eine erhöhte Truppenbewegung der Untoten nahe dem nördlichen Turm zu geben. Dieser Aufruhr sollte schleunigst und entscheidend untersucht werden.\r\nHauptmann Melrose, es gibt Sorgen über die Organisation der Untoten nahe der Grenzen der [[Pestländer]]. Eine frische Gruppe mit Männern wird in den kommenden Wochen zu eurer Position entsendet werden.\r\nEhre unter dem Licht!",},
			["Dolanaar"] = { content = "Dolanaar ist ein von [[Nachtelfen]] bewohnter Stützpunkt der [[Allianz]] in [[Teldrassil]]. Wenn man der Straße südlich von [[Aldrassil]] folgt, die aus dem [[Laubschattental]] hinausführt und dann weiter auf dem Kopfsteinpflaster in Richtung Westen geht, gelangt man zu diesem Dorf. Jeden Tag gelangen auf diesem Weg wichtige Nachrichten und auch Waren von und nach [[Darnassus]]. Doch in letzter Zeit haben Reisende, die von Dolanaar nach [[Darnassus]] fuhren, von ruchlosen Angriffen der verderbten [[Furbolgs der Knarzklauen]] berichtet. \r\n==Personen==\r\n* '''Athridas Bärenpelz''' - Athridas Bärenpelz sucht die [[Relikte des Erwachens]]. Er sagt, es sei die Zeit gekommen, die [[Krallendruiden]] zu retten und sollten sie jetzt versagen, sind sie für immer im Schlaf verloren. Er wird die [[Relikte des Erwachens]] vorbereiten und das Ritual durchführen. Doch damit seine Arbeit Wirkung zeigen kann, muss die verfluchte Bestie, die für diese schreckliche Situation verantwortlich ist, getötet werden: [[Ursal der Raufer]]. Erst dann ist das Ritual vollkommen.\r\n* '''Corithras Mondzorn''' - Corithras Mondzorn befindet sich am [[Mondbrunnen]]. Die [[Druiden]] in [[Darnassus]] verbrauchen das Wasser der [[Mondbrunnen]] [[Teldrassil]]s, und deshalb muss ihr [[Mondbrunnen]] von Zeit zu Zeit wieder aufgefüllt werden. Man kann mit speziell gefertigten Phiolen Wasser aus den [[Mondbrunnen]] schöpfen und Corithras möchte eine Phiole aus jedem [[Mondbrunnen]] in [[Teldrassil]] gefüllt haben. Danach wird er alles Wasser der Phiolen in ein Gefäß schütten, damit es nach [[Darnassus]] gebracht werden kann. \r\n* '''Gastwirt Keldamyr''' - Gastwirt Keldamyr führt die hiesige Herberge. Sein Gasthaus ist angenehm und eine perfekte Oase der Ruhe auf langen Reisen.\r\n* '''Schildwache Amara Nightwalker''' - Schildwache Amara Nightwalker reitet mit zwei Wachen Streife und befindet sich auf dem Weg zwischen Dolanaar und [[Darnassus]]. Dabei erschlägt sie die Wegelagerer der [[Furbolgs der Knarzklauen]].\r\n* '''Syral Messerblatt''' - Syral Messerblatt ist eine Kollegin von [[Denalan]] am [[Al'Amethsee]]. Ihr Kräuter- und Alchimieladen floriert, aber ihr Mann verbringt so viel Zeit damit, Tränke zu mischen, dass sie nie Zeit füreinander haben. Sie besitzt gewisse rare Kräuter, die nützlich sein könnten. \r\n* '''Tallonkai Flinkwurzel''' - Tallonkai Flinkwurzel erhielt einst von [[Gaerolas Talvethen]], dem Bewacher der [[Druiden]] im [[Grabhügel von Ban'ethil]], einen smaragdgrünen Traumfänger. Dieses mächtige Amulett ist in der Lage, Energie aus dem [[Smaragdgrüner Traum|Smaragdgrünen Traum]] abzuziehen und damit denen, die es tragen, Glück zu bringen. Leider hat er den Traumfänger nicht mehr aus seiner Kommode in [[Sternenhauch]] holen können. Nun ist sein Traumfänger von den Mystikern der [[Furbolgs der Knarzklauen|Knarzklauen]] beschädigt und ein Juwel gestohlen worden. Darüber ist Tallonkai wütend geworden und fordert nun den Kopf des [[Satyrn]] [[Lord Melenas]].\r\n* [[Zenn Faulhuf]].",},
			["Dolchbucht"] = { content = "Die '''Dolchbucht''' im [[Heulender Fjord|Heulenden Fjord]] auf [[Nordend]] ist der einzige Ort, an dem man sicher mit einem Schiff anlanden kann. [[Menschen]] und [[Zwerge]] erbauten hier die gut befestigte Hafenstadt [[Valgarde]], der wohl einzige wirklich sichere Ort des ganzen Kontinents.",},
			["Dolchfenn"] = { content = "#REDIRECT [[Verirrte der Dolchfenn]]", redirect = "Verirrte der Dolchfenn",},
			["Dolchfennstamm"] = { content = "#REDIRECT [[Verirrte der Dolchfenn]]", redirect = "Verirrte der Dolchfenn",},
			["Dolchrachen"] = { content = "'''Dolchrachen''' sind [[Raptor]]en, die im [[Messergrat]] im [[Schergrat]] leben. Die besonders scharfen Zähne der [[Dolchrachen]]schmetterschwänze werden von den [[Gnom]]en in [[Toshleys Station]] auch als Waffen benutzt, denn sie geben tolle Vibroklingen ab.",},
			["Donnerechse"] = { content = "Donnerechsen sind gigantische Grasfresser, die mit dem [[Kodo]] verwandt sind. Jedoch verfügen sie im Gegensatz zum [[Kodo]] über die Fähigkeit, durch ein Horn auf der Stirn, oder bei einigen Arten auch durch ihre Augen, Elektrische Ladungen auf ihr Gegenüber loszulassen. Diese Bestien sind so groß, dass der Boden erbebt, wenn sie über die Ebenen stampfen. Ein einziger falscher Schritt, und schon findet man sich unter ihren Füßen wieder.\r\n==Vorkommen==\r\nMan findet viele Donnerechsen im südlichen [[Brachland]]. Doch auch im Krater von [[Un'Goro]], der [[Sengende Schlucht|Sengenden Schlucht]], und sogar im [[Schattenmondtal]] der [[Scherbenwelt]] gibt es sie.\r\n==Bekannte Arten==\r\n* Donnerkopf\r\n* Donnerstampfer\r\n* Stegodon\r\n* Sturmechse\r\n* Sturmschnauze\r\n==Besondere Tiere==\r\n* [[Owatanka]]\r\n* [[Skum]]\r\n'''Sonstige'''\r\n* '''Margol die Wütende''' - [[Sengende Schlucht]]. Das gigantische Horn von Margol hat viele Kratzer und Risse. Ein ungewöhnliches Metallobjekt klemmt in der rauen Oberfläche fest. Beim näheren Hinschauen entdeckt man, dass das Metall in Wirklichkeit ein zerbrochener Axtkopf ist. In das Metall wurden diese Wörter eingeätzt: Eigentum von [[Gebirgsjägerin Feinkiesel]]. Wenn man jedoch versucht, den zerbrochenen Axtkopf herauszuziehen, zerfällt er in unzählige Teile.",},
			["Donnerechsen"] = { content = "#REDIRECT [[Donnerechse]]", redirect = "Donnerechse",},
			["Donnerfalke"] = { content = "#REDIRECT [[Windnatter]]", redirect = "Windnatter",},
			["Donnerfalken"] = { content = "#REDIRECT [[Windnatter]]", redirect = "Windnatter",},
			["Donnerfels"] = { content = "Donnerfels, die [[:Kategorie:Hauptstadt|Hauptstadt]] der [[Tauren]], wurde auf einer Gruppe von vier Plateaus erbaut, von wo aus die [[Tauren]] die weiten Graslande von [[Mulgore]] überschauen können. Entgegen ihrer eigentlich nomadischen Natur gründeten die [[Tauren]] die Stadt mit dem Ziel, einen Knotenpunkt für Handelskarawanen, reisende Handwerksmeister und auch Künstler aller Art in ihrem eigenen Land einzurichten. In dieser Stadt suchen regelmäßig [[Jäger]] Unterkunft, wenn sie von einer [[Jäger|Jagd]] beladen mit wertvollem Leder und anderen Schätzen zurückkehren, und die selben [[Jäger]] decken sich hier auch mit Proviant ein, bevor sie wieder in die Wildnis aufbrechen. Weite Brücken aus Seilen und Holz verbinden die einzelnen Plateaus untereinander, und die einzelnen Anhöhen sind bedeckt mit den urtümlichen Bauten der [[Tauren]]: Tipis, Langhäuser, farbenprächtige Totempfähle, und natürlich die Medizinhütten der [[Tauren|taurischen]] [[Druiden]] und [[Schamanen]]. Von seinem Sitz auf dem höchsten Plateau aus lenkt [[Cairne Bluthuf]] seine Stadt mit stoischer Ruhe, immer darauf bedacht das friedliche Zusammenleben der Stämme und die Sicherheit von Donnerfels zu wahren. (''Quelle: wow-europe.com'' )\r\n= Persönlichkeiten aus Donnerfels =\r\n* '''Ahanu''' ist Lederrüstungshändler in Hewas Waffenkammer am Fundament des Windreiterturms und hat Lederwaren für Jahan zum Verkauf in der Siedlung des Wegekreuzes vorbereitet. \r\n* '''Auld Steinkeil''' kann jenen nicht vergeben, die die [[Tauren]] so leicht aus dem Land der Vorfahren vertrieben haben und sucht Rache an den [[Stacheleber]]n. \r\n* '''[[Cairne Bluthuf]]''' ist der Oberhäuptling und edler Anführer der [[Tauren]]. Er befindet sich auf der höchsten Mesa und ist einer der größten Helden, die die [[Horde]] je gesehen hat. \r\n* '''Eyahn Adlerklaue’s''' Bruder wird schon bald vor Häuptling Bluthuf treten und es ist ihm eine Ehre, einen Kopfputz für ihn anfertigen zu dürfen. Man kann Federn in der richtigen Größe bei den [[Harpyien]] finden, die ganz weit im Norden und nordwestlich von Donnerfels leben.\r\n* '''Orm Steinhuf''' wird ob seiner [[Schmied]]e-Fertigkeiten hoch geachtet. Er befindet sich beim Teich nahe dem großen, zentralen Totem der Stadt. \r\n==Anhöhe der Ältesten==\r\nDie Anhöhe der Ältesten befindet sich auf dem Steilhang im Nordosten der Stadt. Die [[Druiden]] von Donnerfels residieren hier und spüren eine große Macht, die östlich von [[Mulgore]] ins [[Brachland]] sickert.\r\n* [[Hamuul Runentotem]]\r\n* [[Magatha Grimmtotem]]\r\n* [[Turak Runentotem]]\r\n'''Sonstige'''\r\n* '''Bashana Runentotem''' - Bashana Runentotem ist die Tochter von [[Hamuul Runentotem]] und arbeitet an der Morgenkornforschung. \r\n* '''Ghede''' - Um Ghede zu finden, sucht man einfach nach einigen Erdhaufen auf der Anhöhe der Ältesten und dem Tauren, der Befehle brüllt. Er ist kein schlechter Kerl, aber man verärgert ihn lieber nicht. Ihm ist nicht nach Kommentaren zumute, die andere witzig oder komisch finden. Ghede ist hier, um darauf zu achten, dass die Forschungsarbeit des Erzdruiden [[Hamuul Runentotem]] wie geplant vorankommt. Er wird alle aussondern, die nicht das Zeug haben, um seinem geliebten [[Zirkel des Cenarius]] zu dienen.\r\n* '''Nara Wildmähne''' - Nara Wildmähne ist jung und starken Willens und eine Expertin auf dem Gebiet der Magie der [[Eulenbestien]]. Sie weiß auch von den [[Druiden des Giftzahns]] in den [[Höhlen des Wehklagens]]. Sie hat ihre verzerrten schuppigen Gesichter gesehen und kennt ihre Verbrechen ebenso wie ihre Pläne.\r\n* '''Rahauro''' - Rahauro ist ein Diener von [[Magatha Grimmtotem]].\r\n==Anhöhe der Jäger==\r\n* '''Holt Donnerhorn''' ist einer der angesehensten '''[[Jäger]]'''. Er hat die mächtigsten und gefürchtetsten Bestien von [[Azeroth]] bezwungen und befehligt selbst viele starke Kreaturen. Seine Verbundenheit mit der [[Erdenmutter]] ist stark.\r\n* '''Melor Steinhuf''' ist [[Jäger]] und war einst wanderlustig. Wollte wandern und jagen. Wenn man ernsthaft das Leben eines [[Jäger]]s führen will, dann wird Melor Steinhuf den Weg weisen. Angehende Jäger bringen ihm die Klauen der Flachlandstreuner von [[Mulgore]], um ihm ihre Fertigkeit und ihre Entschlossenheit zu beweisen. \r\n* Mosarn ist ein angesehener [[Schmied]] in Donnerfels.\r\n==Anhöhe der Geister==\r\nDie Anhöhe der Geister ist denen vorbehalten die sich mit den Elementen und den zugehörigen Totems, sowie der Geisterwelt beschäftigen: Den [[Schamanen]].\r\nAngeleitet von '''Tigor Himmelstürmer''' vertiefen diese [[Tauren]] ihre Kenntnisse der Elemente.\r\n* '''Pand Steibinder''' versteht sich auf das Anfertigen von Verbänden und teilt sein Wissen über [[Heilkunst]] gerne mit denen, die zu ihm kommen und ihn danach fragen.\r\n==Teiche der Visionen==\r\nDie Teiche der Visionen sind eine Höhle unter den [[Schamanen]] von Donnerfels. Der Pfad zu dieser Höhle ist gut versteckt, aber man kann ihn am Steilhang der Anhöhe der Geister finden.\r\n* [[Apothekerin Zamah]]\r\n* '''Clarice Foster''' gehört zu den Verlassenen und ihr Mann hat sie wegen dem Kreuzzug sitzen lassen. Nacht für Nacht hat sie hier gesessen und geduldig auf ihn gewartet. Sie hat immer den zweiten Platz hinter seiner Pflicht eingenommen. Er ist tot, und sie erträgt genau das, was sie aufzuhalten versuchte. Sie will nichts mehr mit ihm zu tun haben.",},
			["Donnerfeste"] = { content = "Die [[Orcs der Donnerfürsten]] lebten einst in der '''Donnerfeste''' im [[Schergrat]], bevor sie zu [[Höllenorcs]] wurden. Dann wohnten eine zeitlang die [[Oger der Speerspießer]] in der Feste und vor Kurzem haben die [[Orcs]] der [[Horde]] diesen Stützpunkt von den [[Oger]]n, die sich in der [[Blutschlägerklamm]] unter der Donnerfeste breit gemacht haben, zurückgefordert. Und sie möchten diesen Ort behalten, doch es gibt eine Bedrohung für die Feste, die weitaus tödlicher ist, als die [[Allianz]] in [[Sylvanaar]]: Die einheimischen Oger in diesen Bergen. In der Donnerfeste findet man den berühmten [[Mok'Nathal]] Bestienmeister [[Rexxar]].\r\n==Persönlichkeiten==\r\n* '''Garm Wolfsbruder'''\r\n* '''Gor'drek''' - Gor'drek übt zu Ehren seiner Vorfahren die alte Tradition der Schamanen aus. Die Orcs dürfen niemals die Opfer vergessen, die ihre Vorfahren gebracht haben, damit sie heute hier sein können. Im Gegenzug müssen sie die notwendigen Opfer bringen, damit ihre Nachfahren eine Zukunft haben. Gor'drek will deshalb die Eigenen schützen und hat eine Salbe hergestellt, die ihnen bei der Verteidigung des [[Zackengrat]]s helfen wird, denn sie macht die [[Terrorwölfe]] der Donnerfürsten stärker. Doch auch die nahende Wildnis und [[Sylvanaar]] bereitet ihm Sorgen und möchte zur Sicherheit lieber die [[Messerschwingenblutvergießer]] und [[Siechdrachen]] dezimiert wissen.\r\n* '''Nekthar'''\r\n* '''Rokgah Blutgriff''' - Rokgah Blutgriff sucht die Artefakte der [[Donnerfürsten]], bestehend aus der [[Trommel der Donnerfürsten]], dem [[Pfeil der Donnerfürsten]] und die [[Schrifttafel der Donnerfürsten]]. Durch eine wegweisende Visionen mithilfe eines feurigen Seelenfragmentes, kam er auch dem letzten Artefakt, der [[Donnerlanze]], auf die Spur.\r\n* '''Rexxar''' - Kurz nach seiner Ankunft in den Bergen wurde er von einer Gruppe [[Oger der Speerspießer]] angegriffen. Er konnte sich zwar freikämpfen, doch sie haben es geschafft, seinen [[Flügeldrachen]] Leokk zu entführen. Nun will Rexxar die Oger vergiften und dann ihren [[Gronn]]meister vernichten. Die Verwendung von Giften ist ein dreckiges Geschäft. Aber so werden sie die Ziele erreichen. Das erreicht er mithilfe der kleinsten Wesen, von Murmeltieren, die unter seiner Kontrolle die Fässer im [[Lager der Blutschläger]] vergiften. Am Altar von [[Goc]] wird Rexxars Kampfhorn den Gronn rufen ... und den Tod finden. Außerdem ist er auf auf der Suche nach seinem Volk und seinem Vater, [[Leoroxx]] im [[Dorf der Mok'Nathal]].\r\n* '''Tor'chunk Zweiklaue''' - Tor'chunk Zweiklaue leitet den [[Oger der Blutschläger]] beim [[Außenposten der Blutschläger]] und auch den Kampf gegen die [[Speerspießer]] in der [[Wehr der Speerspießer]] und im [[Grund der Speerspießer]]. Eine weitere Bedrohung sieht er in dem [[Urtum]]beschützer [[Starkast Tiefenwurz]] und so schickt er Freiwillige aus, um einen uralten Baum zu fällen. Auch für das Gemetzel in [[Fels'mok]] ist Tor'chunk verantwortlich.",},
			["Donnerfürsten"] = { content = "#REDIRECT [[Donnerfürstenklan]]", redirect = "Donnerfürstenklan",},
			["Donnerfürstenklan"] = { content = "==Allgemeines==\r\nDie '''Donnerfürsten''' waren einst ein stolzer Orcklan. Doch dann wurden sie durch [[Mannoroth]]s Blut in [[Höllenorcs]] verwandelt. Diese [[Orcs]] lebten einst in der [[Donnerfeste]] im [[Schergrat]], bevor sie zu [[Höllenorcs]] wurden.\r\n==Geschichte==\r\nDie Donnerfürsten zeichneten sich durch ihre starke Verbindung zum [[Schwarzfels Klan]] aus. [[Orgrim Schicksalshammer]] hatte jedoch andere Motive, als er dem Kriegsherrn der Orcischen Horde nach [[Azeroth]] folgte. Sein Stamm blieb in [[Draenor]] zurück, und Fenris der Jäger trat Schicksalshammers Nachfolge an. \r\nAls Schicksalshammer kurz vor dem [[Der Zweite Krieg|Zweiten Krieg]] die vielköpfige Truppe der [[Wolfsreiter]] auflöste, blieben nur die Räubereinheiten des Donnerfürsten Klans bestehen. Der Stamm sicherte sich einen Platz unter den stärksten Klans auf [[Draenor]] und sein Einflussbereich erstreckte sich bald bis zu den Schergrat. Kurz nach dem Ende des Zweiten Krieges drang die Kunde von der Niederlage der [[Horde]] zu den Orcs. \r\nDer [[Schattenmond Klan]] beabsichtigte eine Anzahl mystischer Portale zu öffnen, mit denen die verbliebenen Stämme der todgeweihten Welt Draenor für immer entfliehen konnten. Fenris brannte jedoch darauf, seinen Klan zu einer glorreichen Schlacht gegen die [[Menschen]] zu führen. \r\nDie Donnerfürsten wollten um jeden Preis nach Azeroth, um das zu erreichen, woran Orgrim Schicksalshammer gescheitert war. Die Pläne des [[Schamane]]n [[Ner'zhul]] stießen bei ihnen und dem [[Knochenmalmer Klan]] auf heftigsten Widerstand. Hatte der Stamm zuvor noch [[Dentarg]] - einem [[Oger]]magi des [[Schattenmond Klan]]s - beigestanden, die eigensinnigen Knochenmalmer „zurechtzuweisen“, so stellten sie sich nun ebenfalls gegen Ner'zhul. Weil der Donnerfürsten Klan es gewagt hatte, sich der absoluter Herrschaft des Schamanen zu widersetzen, wurden sie durch die mächtigen Streitkräfte des Schattenmond Klans vernichtet und die Überlebenden in Höllenorcs verwandelt. \r\n==Artefakte==\r\nMan hat von Artefakten der [[Donnerfeste]] gehört, die vermisst werden. Man weiß, dass sich unter den Objekten, nach denen gesucht wird, eine Trommel, ein Pfeil und eine Schrifttafel befinden. Der, der es schafft, die Artefakte wiederzubeschaffen verdient sich das Recht, die Heimat der Vorfahren der Donnerfürsten zu bewohnen. Durch die Wiederbeschaffung der Artefakte des Klans, durch den Kampf gegen ihren Feind, die [[Oger der Speerspießer]] und deren Meister, die [[Gronn]], und durch die Rückbringung der Donnerlanze, sichert man sich den Segen der Donnerfürsten.\r\n==Persönlichkeiten==\r\n* [[Fenris der Jäger]]\r\n* [[Orgrim Schicksalshammer]]\r\n* '''Garm Wolfsbruder''' war der letzte Häuptling der Donnerfürsten.",},
			["Donnerfürsten Klan"] = { content = "#REDIRECT [[Donnerfürstenklan]]", redirect = "Donnerfürstenklan",},
			["Donnergrat"] = { content = "Der Donnergrat liegt im Nordwesten von Durotar und wird von großen [[Donnerechsen]] bewohnt. Doch [[Orgnil Narbenseele]] hat herausgefunden, dass auch ein [[Hexenmeister]] der [[Brennende Klinge|Brennenden Klinge]], der [[Goblin]] [[Zischel Düstersturm ]], nahe dem Donnergrat im Nordwesten von [[Klingenhügel]] in [[Durotar]] kampiert. Er und seine Kultdiener verbreiten dort Chaos. In der Nähe vom Donnergrat wurde Rhinag von einem [[Siechstachelskorpid]] heftig gestochen, da er während eines Kampfes unvorsichtig war. Er spürt, wie das Gift ihn schwächt und es bleibt ihm vielleicht noch eine Stunde zu leben. Er braucht Hilfe.\r\n==Personen==\r\n* [[Rhinag]]\r\n* [[Zischel Düstersturm]]",},
			["Donnerzorn"] = { content = "Ähnlich wie [[Sulfuras]] ist auch Donnerzorn die Waffe eines Elementarfürsten. [[Donneraan]] heißt der Prinz des Windes, der die Waffe ursprünglich sein Eigen nannte. Nach der Niederlage der [[Alte Götter|Alten Götter]] im Krieg gegen die [[Titanen]] wurden die Befehlshaber der unterlegenen Armee, vier mächtige Elementare, darunter [[Ragnaros]] der Feuerlord, zurück auf die Elementarebene verbannt. Hier wendeten sich die einst Verbündeten gegeneinander und ergingen sie sich in einem jahrtausendelangen Krieg.\r\nWährend dieses Krieges plante [[Ragnaros]] einen Komplott gegen [[Donneraan]] mit dem Ziel ihn zu vernichten. Seine beiden Leutnants [[Baron Geddon]] und [[Garr]] sollten ihn bei diesem Plan unterstützen. Die Verschwörung [[Ragnaros]]’ blieb von [[Donneraan]] unentdeckt und so wurde er unvorbereitet von [[Ragnaros]]’ legendärem Hammer \"[[Sulfuras]]\" niedergestreckt.\r\nDer Feuerlord labte sich an der Essenz des Windfürsten, war aber nicht in der Lage diesen vollständig zu verzehren. Also schloss er den kläglichen Rest [[Donneraan]]s in ein legendäres Artefakt ein und zerbrach dieses in zwei makellose Teile. [[Baron Geddon]] und [[Garr]] erhielten je eines der beiden Teile zur Aufbewahrung und bewachen diese auch heute noch.\r\nSo ergibt es sich, dass mit dem Fund eines dieser Bruchstücke der lange Weg zum Erwerb von Donnerzorn beginnt. Sobald man entweder die rechte oder die linke Hälfte des Artefaktes von [[Baron Geddon]] und [[Garr]] aus dem [[Geschmolzener Kern|Geschmolzenen Kern]] erbeutet habt, führt der Weg nach Silithus. Im äußersten Nordwesten des Areals findet man [[Hochlord Demitrian]], der nachdem man ihn mit dem Bruchstück im Gepäck angesprochen hat, das \"Gefäß der Wiedergeburt\" überreicht.\r\nZur Wiedererweckung des Windfürsten benötigt [[Hochlord Demitrian]] beide Bruchstücke des Artefaktes, die Essenz von [[Ragnaros]] sowie zehn Elementiumbarren. Die Essenz des Feuerfürsten ist das wohl am leichtesten zu beschaffende Teil. Die beiden Bruchstücke findet man wie erwähnt bei den beiden Bossen [[Baron Geddon]] und [[Garr]] im [[Geschmolzener Kern|Geschmolzenen Kern]]. Die Beschaffung der zehn Elementiumbarren stellt das wahrscheinlich größte Problem dar. Elementium ist ein legendäres Metall dessen Hauptbestandteil Elementiumerz ist, welches sich nur im [[Pechschwingenhort]] findet. Techniker, die dort als Handlanger für [[Nefarian]]s kranke Experimente dienen, tragen das Erz bei sich. Gott sei Dank treten diese meist in großen Gruppen auf, so dass man nach einiger Übung oft mehrerer Elementiumerz pro Besuch erbeuten kann.\r\nDer zweite Hauptbestandteil von Elementium ist Arkanit. Pro Elementiumbarren benötigt man zehn Barren Arkanit, welche leider ebenfalls schwer oder zumindest teuer zu beschaffen sind. Arkanit wird von [[Alchimist]]en aus einem Arkankristall und einem Thoriumbarren hergestellt, welches beides in Reichen Thoriumvorkommen zu finden ist. Neben diesen beiden Hauptbestandteilen benötigt man pro Elementiumbarren außerdem noch einen Feuerkern, den man bei zahlreichen Monstern im [[Geschmolzener Kern|Geschmolzenen Kern]] findet und drei Elementarfluxus, die man bei jedem Schmiedebedarfshändler (teuer) erwerben kann.\r\nHat man alle notwendigen Materialien gesammelt, heißt es nun noch die einzelnen Bestandteile des Elementiums in Barren zu verhütten. Dazu führt der Weg erneut tief in den [[Pechschwingenhort]]. Zwischen den [[Drachen]] [[Feuerschwinge]] und [[Schattenschwinge]] befindet sich der [[Elementarformer Krixix]], der als einziger über das Wissen verfügt Elementium in Barren zu verhütten. Da [[Elementarformer Krixix|Krixix]] sich als wenig hilfsbereit erweist und sein Wissen nicht freiwillig preisgeben will, muss ein [[Priester]] Krixix per Gedankenkontrolle übernehmen. Jetzt kann er einem beliebigen Mitglied der Gruppe mit der Fähigkeit Bergbau auf Stufe 300 das Verhütten von Elementium beibringen. Wenn man auch diesen letzten Schritt gemeistert hat muss man nur noch zur nächsten Schmiede gehen und die gesammelten Materialien in Elementiumbarren umwandeln.\r\nDanach kehrt man zu [[Hochlord Demitrian]] in [[Silithus]] zurück und überreicht ihm die geforderten Materialien. Dieser wird daraufhin [[Donneraan]] beschwören. Leider ist der Windfürst recht undankbar und wendet sich trotz der Tatsache, dass man ihn aus seinem Gefängnis befreit hat gegen seine Befreier. Nachdem man ihn besiegt hat, muss man nur noch seine Leiche durchsuchen und die \"Schlummernde vom Wind berührte Klinge\" an sich nehmen und diese zu Demitrian bringen. Der Hochlord ist recht eingeschüchtert aufgrund des Sieges und überreicht nun endlich das legendäre Schwert „Donnerzorn, Gesegnete Klinge des Windsuchers“.",},
			["Dorf der Bluthufe"] = { content = "Das '''Dorf der Bluthufe''' liegt im südlichen [[Mulgore]] am idyllischen [[Steinbullensee]] und ist ein von [[Tauren]] geführter Stützpunkt der [[Horde]]. Die [[Tauren]] hier haben Probleme mit den [[Stacheleber der Bleichmähnen|Stachelebern der Bleichmähnen]], die das Land gemeinsam mit den ihnen nutzen; und auch die [[Zwerge]] buddeln zum Missfallen der [[Tauren]] in der Erde des Landes. Zu allem Überfluss hat nun auch noch die [[Venture Company]] unter Führung von [[Vorsteher Zischelspross]] in den Bergen am Rand der Ebenen Einzug gehalten. \r\n==Personen==\r\n* [[Baine Bluthuf]]\r\n'''Sonstige'''",},
			["Dorf der Bruchhauer"] = { content = "Das Dorf der Bruchhauer an der südöstlichen Küste des [[Hinterland]]es ist der Stützpunkt der [[Horde]] in diesem Gebiet und wird von [[Waldtrolle]]n des [[Trolle der Bruchhauer|Bruchhauer]]-Stammes bewohnt.\r\nDiese verehren und glauben an die Rückkehr von [[Zul'jin]]. Doch [[Zul'jin]] ist noch immer nicht zurückgekehrt und sie sind ihren eigenen Mitteln überlassen. Viele mutige [[Trolle]] haben sie in der rauen Wildnis der [[Hinterland]]s verloren. \r\nDie Silbermähnen[[wölfe]] stellen eine der größten Bedrohungen für ihre [[Jäger]] dar. Sie lauern versteckt in den Büschen und schlagen zu, sobald sie eine Möglichkeit dazu sehen. Unter all den bösartigen Tieren der Wildnis des [[Hinterland]]es, sind auch die [[Eulenbestien]] zu finden. Schon so manche gute Krieger verloren sie an die grausamen Krallen und die Schnäbel der Biester. \r\nUnd ihre Feinde, die Wildhämmer fangen Geschäfte mit den Feinden der [[Trolle]] an. Sie schmieden neue Bündnisse. Diesmal sind es die [[Hochelfen]]. Sie werden diesen [[Wildhammerklan|Wildhammerzwergen]] wohl einne Botschaft überbringen müssen. Eine Botschaft geschrieben mit dem Blut der Feinde. \r\n==Persönlichkeiten==\r\n* '''Jäger Malkor''' ist der ehemaliger Wachbefehlshaber der [[Trolle der Bruchhauer|Bruchhauer]] und der Zwillingsbruder von Markhor. Er wurde beim selben Überfall wie Stumpfhauers Gefährte von den [[Trolle der Blutfratzen|Blutfratzen]] verschleppt. Das Schicksal sollte ihn traurigerweise nicht vom Tod verschonen und er wurde schnell und brutal hingerichtet. Seine Überreste wurden an die Brühschlammer und Wölfe der [[Trolle der Blutfratzen|Blutfratzen]] in [[Jintha'Alor]] verfüttert.\r\n* '''Jäger Markhor''' hat wie viele in ihrem Dorf, einen Nahestehenden verloren. Es war sein Zwillingsbruder Malkhor. Jäger Markhor möchte deswegen, dass man einen Klingenschnabelhimmelsfürsten tötet und dessen Federbusch an sich nimmt. Ebenso geht er auf die Pirsch auf die Pirscher und möchte, dass man die Silbermähnenwölfe tötet. Er will auch die Überreste seines Zwillingsbruders bergen, denn es ist noch nicht zu spät, um seine Seele zu befreien.\r\n* Katoom ist Angler und möchte, dass man Gammerita tötet und Katooms besten Köder aus ihrem Kadaver holt, denn sie hat ihm seinen besten Köder geklaut. Er kann nicht mal für fünf Minuten angeln, ohne dass einer von diesen überdimensionalen Fisch-Staubsaugern ihm seinen Köder klaut.\r\n* '''Lard''' ist ein Oger und der Gastwirt des Dorfes. Lard hat ein Picknick gemacht, an einem geheimen Platz, als ein Blutfratzentroll ihn mit einem großem Stock schlug. Lard ist zurück ins Dorf der Bruchhauer gerannt, aber hat seine Brotzeit vergessen. Lard ist hungrig und hat Angst, nach Norden zu gehen. Denn die Insel dort ist ein geheimer Platz.\r\n* '''Mystikerin Yayo'jin''' möchte, dass man die [[Trolle der Blutfratzen]] tötet.\r\n* '''Otho Moji'ko''' möchte eine Botschaft an die Wildhämmer überbringen. \r\n* '''Schmied Aschenbaum''' möchte, dass man seine verlorenen Werkzeuge ausfindig macht. Der Blutfratzenabschaum ist in ihr Dorf eingedrungen und hat sein Werkzeug gestohlen. Er hat zwar Ersatz, aber das Set, das sie ihm geraubt haben, war das Geschenk eines gutherzigen Gnoms, der ihm als junger [[Orc]] das Leben gerettet hat. Es bedeutet ihm ungeheuer viel. Markhor berichtete, dass die Werkzeuge nahe der Tempel von Agol'watha und Shaol'watha gesichtet wurden.\r\n* '''Ura Stumpfhauer''' möchte, dass man sich Gefäße mit besudeltem Blut aus [[Jintha'Alor]] beschafft und ihren Gefährten, den Ältesten Stumpfhauer, aus Jintha'Alor befreit. Das Dorf könnte einen so großen Verlust nicht verschmerzen.",},
			["Dorf der Mok'Nathal"] = { content = "Das '''Dorf der Mok'Nathal''' liegt im Osten des [[Schergrat]]s, hinter dem [[Messergrat]], und dient auch als Stützpunkt der [[Horde]].\r\n==Persönlichkeiten==\r\n* [[Leoroxx]]\r\n* '''Geistrufer Dohgar''' - Geistrufer Dohgar interessiert sich für die Totems seiner Feinde, der [[Oger der Speerspießer]]. Er möchte die Totems sammeln, um die Geister der geringen [[Netherdrachen]] befreien. Ebenso untersucht er die Lichtkugeln der [[Astrale der Razaani]], die er mittels eines Kugelfängertotems fangen kann und hält es für dringend notwenig, [[Leoroxx]] über die Taten der Astralen der Razaani zu informieren.\r\n* '''Dertrok''' - Dertrok hat vier Zauberstäbe hergestellt, die die Macht der [[Arakkoa]]kristalle verstärken sollten. Er sagt sich: Probieren geht über Studieren und möchte die Zauberstäbe nun an einem [[Oger]]sklaven der [[Arakkoa]] ausprobieren.\r\n* '''Matrone Varah'''\r\n* '''Silmara''' - Silmara braucht die weichen, schillernden Flügel der [[Seidenflügelmotten]], da diese von den Mok'Nathal vielseitig eingesetzt werden. \r\n* '''Taerek''' - Taerek möchte, dass man für ihn die Seidenflügelkokons von [[Seidenflügellarven]] besorgt. Sie zu jagen ist eine schwierige Aufgabe für die jungen Jäger der Mok'Nathal. Der große Geist hilft denen, die sich selbst helfen und die Seide der Kokons der Seidenflügel wird im Dorf der Mok'Nathal für alle möglichen Zwecke eingesetzt.",},
			["Dorf der Schwarzhufe"] = { content = "Das '''Dorf der Schwarzhufe''' im Nordosten der [[Düstermarschen]], in der Nähe des Blaumoors, ist eine große neue Siedlung der [[Tauren der Grimmtotem]]. Nachdem die Aktivitäten der Grimmtotem in [[Tausend Nadeln]] ans Licht gekommen sind, werden sie von mehr und mehr Tauren mit Argwohn betrachtet. Hochrangige Vertreter der Grimmtotem hießen bereits Morde und Entführungen gut, um ihre eigenen Interessen voranzutreiben. Ihre Anführer, die Ältesten, tragen alle Anordnungen von [[Donnerfels]] in Form von Notizen bei sich. Setzt man diese zusammen, kann man mehr über die Verschwörung der Grimmtotem erfahren.",},
			["Dorf Sen'jin"] = { content = "Das Dorf Sen'jin liegt östlich hinter dem [[Tal der Prüfungen]] im Süden von [[Durotar]]. Dort kann man [[Raptoren]] kaufen und lernen Sie zu reiten. Das Dorf ist benannt nach [[Sen'jin]], einem ehemaligen Anführer der [[Trolle der Dunkelspeere]]. Die [[Trolle]] in Sen'jin sind nicht ohne eigene Probleme, aber die Neuigkeiten über die [[Brennende Klinge]] in [[Durotar]] können Probleme für jedermann bedeuten. \r\nDie [[Dunkelspeere]] hier sind geborene Jäger und viele der Bälge, die sie benutzen, stammen von den [[Tiger|Durotartigern]]. Decken, Rüstungen, Zelte: Es gibt viele Gründe, warum die [[Trolle]] Jagd auf die [[Wildtier]]e machen, und ebenso viele Gründe, warum sie sie leben lassen. Doch die Zeit ist gekommen, dass sie den Bestand der Tiger dezimieren, denn diese Raubtiere werden auf den [[Echo Inseln]] immer mehr und der Bedarf der [[Tiger]] an Beute übersteigt bald die Bestände der [[Wildtiere]]. \r\n==Personen==\r\n* '''Lar Lauerzahn''' - Lar Lauerzahn schlich sich während eines Angriffs auf die [[Zentauren der Kolkar]] letzte Nacht in das Dorf der [[Zentauren]] und fand heraus, dass diese dreckigen Bestien einen dreistufigen Angriff auf die [[Trolle]] und [[Orcs]] von [[Durotar]] geplant hatten. Um die Kolkaraggression zu vereiteln, müssen die Sets der Angriffspläne zerstört werden, die innerhalb der [[Kolkarklippe]] verwahrt werden.\r\n* '''Meister Gadrin''' - Meister Gadrin möchte, dass man [[Zalazane]] und seine Anhänger auf den [[Echo Inseln]] besiegt. Außerdem kennt er die [[Trolle der Bleichborken]] gut und weiß dass man von der [[Schrifttafel des Theka]] den Namen des Spinnengottes der [[Trolle der Bleichborken]] erfahren kann: [[Shadra]].\r\n* '''Meister Vornal''' - Meister Vornal ist [[Alchimist]]. Seine Augen sind zwar nicht mehr so scharf, aber er kann immer noch gut genug sehen. Doch immer öfter muss er sich auf seine [[Alchimie]]-Fertigkeiten verlassen, um sich bei Dingen, die ihm früher leicht fielen, nun mit Magie zu helfen. Er weigert sich jedoch, einen Lehrling einzustellen - bislang ist ihm noch kein [[Troll]] oder [[Orc]] begegnet, der sich als würdig genug erwiesen hätte. Um ein geistvolles Getränk herzustellen, benötigt er intakte [[Makrura]]augen und Phiolen mit Kriechersekret.\r\n* '''Ula'elek''' - Der Troll Ula'elek ist ein [[Schmied]] wohnt mit seinen Dunkelspeerbrüdern im Dorf Sen'jin. Er wird für Krieger die brutalen Stulpen anfertigen, denen große Magie innewohnen wird, doch dafür benötigt er ungespaltene [[Satyr]]hufe. \r\n* '''Un'Thuwa''' - Un'Thuwa ist Magielehrer und möchte, dass man die [[Jujuhaufen]] auf den [[Echo Inseln]] zerstört.\r\n* '''Vel'rin Fang''' - Vel'rin Fang ist ein [[Troll Jäger]] und braucht mehr Bälge von den [[Tiger|Durotartigern]], wenn er geeignete Dinge für sein Volk anfertigen möchte.",},
			["Dorngrin der Hüter"] = { content = "Der [[Satyr]] Dorngrin der Hüter ist ein Boss in der [[Botanika]], einer Teilinstanz der [[Festung der Stürme]].\r\n==Fähigkeiten==\r\n* '''Höllenfeuer:''' Verursacht jede Sekunde ca. 1000 Punkte Schaden um den Boss herum\r\n* '''Opferung:''' Ein zufälliger Spieler wird auf das Plateau teleportiert und erhält sechs Sekunden lang ca. 750 Punkte Schaden pro Sekunde\r\n* '''Wutanfall:''' Erhöht Angriffsgeschwindigkeit um 75% und Nahkampfschaden um 110",},
			["Dornnebelhügel"] = { content = "Die '''Dornnebelhügel''' liegen im Westen der [[Höllenfeuerhalbinsel]] an der Grenze zu den [[Zangarmarschen]]. Sie werden von [[Felshetzer]]n und [[Felsklaue]]n bewohnt. Der [[Posten des Cenarius]] kämpft schon die ganze Zeit, um den Pass durch den Dornnebelhügel von den [[Felsklauen]]verheerern freizuhalten. Es wäre schlecht, wenn sie ganz von der Zuflucht in den [[Zangarmarschen]] abgeschnitten wären. Sie möchten die Tiere nicht vertreiben, aber sie haben kaum einen andere Wahl, sie werden Reisenden in dieser Gegend gegenüber immer aggressiver.",},
			["Dornrankenklamm"] = { content = "Die [[Tauren]] haben in Mulgore ihre Heimstatt geschaffen, aber nicht, ohne teuer dafür zu bezahlen, denn die [[Stacheleber der Borstennacken]] aus der Dornrankenklamm, östlich von [[Camp Narache]], machen ihnen mit ihrem ständigen Krieg das Leben schwer. Sie überfallen die Jägergruppen der [[Tauren]] und rauben in der Dunkelheit ihre Dörfer aus. Ihr Anführer ist [[Häuptling Spitzhauer Dornenmantel]], den man in der Klamm in dem heruntergekommenen Dorf finden kann.",},
			["Dr. Bumm"] = { content = "#REDIRECT [[Doktor Bumm]]", redirect = "Doktor Bumm",},
			["Dr. Bumms Lager"] = { content = "#REDIRECT [[Doktor Bumm]]", redirect = "Doktor Bumm",},
			["Drache"] = { content = "#REDIRECT [[Drachen]]", redirect = "Drachen",},
			["Drachen"] = { content = "Die Welt von [[Azeroth]] ist in viele Parteien geteilt. Durch die Geschichte sind viele Bedrohungen wie die Plage, Kämpfe oder Zwiste entstanden. Einige Kreaturen habe jedoch in diesem Land ihre Heimat gefunden. Sie sind so mächtig das sie die ganze Armee jeden Königs umstürzen könnten. Diese gewaltigen Kreaturen werden nicht Tiere genannt, stattdessen gaben sie sich eigene Titel. Ihre Namen werden geflüstert, ihre Jungen streunen jedoch durch das Land und suchen nach Nahrung und garantieren dass niemand vergisst wer die wahren Meister in der Tiefen Wildnis sind: Die Drachen von [[Azeroth]].\r\n==Geschichte==\r\nDie Drachen waren das erste Volk, das nicht von den [[Titanen]] erschaffen wurde und in [[Azeroth]] zum Leben erwachte. Während der ersten Zeitalter herrschten sie uneingeschränkt über die junge Welt und entwickelten eine starke Verbundenheit zu den Kräften der Schöpfung. Lange vor den [[Nachtelfen]] studierten sie die [[Magie]] und entfesselten sie in ihrer alten Heimat. Diese unsterblichen Wesen verfügen nicht nur über ein hohes Maß an Intelligenz, sondern können zudem auf ein gewaltiges Potenzial an Erfahrungen zurückgreifen. Anstatt mit zunehmenden Alter an Stärke zu verlieren, sammeln sie im Laufe der Jahrhunderte unglaubliche Kräfte, magisches Wissen und Macht. Einige haben sogar die Fähigkeit erlangt, das Aussehen von Menschen anzunehmen und sich fortan frei unter ihnen zu bewegen. Die furchteinflößenden Flammen, die aus dem Schlund ausgewachsener Drachen lodern können, verschlingen Feinde ohne Zahl, und ihre starken Flügel tragen sie unermüdlich durch die Lüfte.\r\nAlle Drachen sprechen die [[Gemeinsprache]] und [[Orkisch]], jedoch haben sie ihre eigene Sprache, das [[Drakonisch]] und sprechen auch die Sprache der [[Titanen]].\r\n'''Siehe auch'''\r\n* [[Angriff der Drachenschwärme]]\r\n* [[Kammer der Aspekte]]\r\n==Drachenschwärme==\r\nDie Drachen sind in fünf Schwärme geteilt wo jeder eine eigene Abstammung hat. Jede Farbe ist stolz auf seine Erbschaft und Abstammung, und erinnert sich an Namen von all denen die vor Zeiten gegangen sind. Die Spitzengruppen sind darüber hinaus in kleine Familiengruppen geteilt die auch als Brut genannt werden. Jede davon besetzt und hält ihr Territorium in [[Azeroth]]`s weniger bevölkerten Gebieten. Einige sind gewöhnlich zu sehen, andere sind in Kriegen dazu getrieben worden gegen ihre eigene Arte zu Kämpfen. Die fünf bedeutsamsten Drachengruppen können durch ihre Farbe identifiziert werden.: schwarz, blau, bronze, grün, und rot. Andere Drachen existieren nicht in [[Azeroth]]. Jede von diesen fünf Gruppen behält ein Geheimnis für sich und trennt diese Ideologien vom Rest. \r\nIm [[Wyrmkult]] und der [[Drachensekte]] werden die Drachen von Sterblichen verehrt.\r\n'''Bekannte Schwärme''':\r\n* [[Blauer Drachenschwarm]]\r\n* [[Bronzener Drachenschwarm]]\r\n* [[Chromatischer Drachenschwarm]]\r\n* [[Ewiger Drachenschwarm]]\r\n* [[Grüner Drachenschwarm]]\r\n* [[Netherdrachen]]\r\n* [[Roter Drachenschwarm]]\r\n* [[Schwarzer Drachenschwarm]]\r\n* ([[Schattendrachenschwarm]])\r\n* [[Protodrachen]]\r\n==Arten==\r\nWährend mit dem Begriff \"Drachen\" an sich meistens die typischen Großdrachen betitelt werden, tragen die verschiedenen Unterarten auch die Bezeichnung \"Drachkin\". Zu ihnen gehören u.a.:\r\n* [[Brutling]] ([[Welpling]])\r\n* [[Drachenaspekt]]\r\n* [[Drachenbrut]] ([[Wyrmkin]])\r\n* [[Drakonid]]\r\n* [[Knochendrache]] ([[Frostwyrm]])\r\n* [[Teufelsdrache]]",},
			["Drachenaspekt"] = { content = "#REDIRECT [[Drachenaspekte]]", redirect = "Drachenaspekte",},
			["Drachenaspekte"] = { content = "Die [[Drachen]]schwärme werden geführt von Wesenheiten auch bekannt als Aspekte, jeder für eine Farbe, der über eine Gruppe wie ein mächtiger Gott herrscht und auf seine Nachkommen herunter schaut. Die Mitglieder des Pantheons (die [[Titanen]]) spendeten einen Teil ihrer großen Macht den fünf großen [[Drachen]]:\r\n* [[Alexstrasza]] die Lebensbinderin ([[Roter Drachenschwarm]]) - Aspekt des Lebens. Die rote Drachenkönigin [[Alexstrasza]] steht für Leben und Hoffnung, sie betrachtet sich selbst als Beschützerin aller Geschöpfe. \r\n* [[Malygos]] der Zauberwirker ([[Blauer Drachenscharm]]) - Aspekt der Magie. [[Malygos]], der älteste unter den Aspekten, gebietet über die Kräfte der Magie und hat sich mit seinen [[Blauer Drachenscharm|Blauen Drachen]] nach [[Nordend]] zurückgezogen. \r\n* [[Neltharion]] der Erdwächter ([[Schwarzer Drachenschwarm]]) - Aspekt der Erde. [[Neltharion]] der Erdwächter gab sich den Kräften des Bösen hin und ist nun ein Bote von Tod und Chaos - viele Völker kennen den schwarzen Drachen nur noch unter dem Namen [[Todesschwinge]].\r\n* [[Nozdormu]] der Zeitlose ([[Bronzener Drachenschwarm]]) - Aspekt der Zeit. Der bronzene Drache [[Nozdormu]] herrscht über den Sand der Zeit und konnte über die Jahrtausende den Aufstieg der „niederen“ Völker beobachten.\r\n* [[Ysera]] die Träumerin ([[Grüner Drachenschwarm]]) - Aspekt der Natur. Die grüne Drachenkönigin [[Ysera]] ist die Göttin der Träume und lebt in einer astralen Dimension, dem [[Smaragdgrüner Traum|Smaragdgrünen Traum]], aus der heraus sie über das Gleichgewicht der Welt wacht. \r\nSie alle wurden der unermesslichen Macht der [[Titanen]] teilhaftig und mit der Aufgabe betraut, die Welt zu verteidigen.\r\n* [[Draco´Ur]] der Schatten ([[Schattendrachenschwarm]]) - Kein Aspekt. Wurde von den Titanen verbannt wegen der anhaltenden Kämpfe mit den [[Protodrachen]]. ('''Inoffiziell''')\r\n* [[Neltheraku]] der Patriarch, kein berührter Aspekt, aber Anführer der [[Netherdrachen]] in der [[Scherbenwelt]].",},
			["Drachenbrut"] = { content = "Die Drachenbrut der [[Drachen]]schwärme zählt zu den [[Drachkin]] und sind eine Mischung aus Mensch und Drache, denn während ihr Oberkörper humanoid ist, gleicht ihr Unterkörper dem ihrer geflügelten Artgenossen.\r\n==Persönlichkeiten==\r\nZu den berühmten Vertretern der Drachenbrut zählen u.a.:\r\n* [[General Drakkisath]]\r\n* [[Oberanführer Wyrmthalak]]\r\n* [[Solakar Feuerkrone]]",},
			["Drachenend"] = { content = "Das '''Drachenend''' bezeichnet eine Gegend im [[Schergrat]], die sich rund um den Zirkel des Blutes erstreckt. Am östlichen Rand des Drachenend befindet sich ein Ort namens verfluchtes Dunkel. Dort lebt der [[Gronn]] [[Grulloc]], ein Sohn des [[Gruul]], der an diesem Ort seine dümmlichen Pläne schmiedet. Sein wertvollster Besitz ist ein Drachenschädel, den er als Erinnerung an das Gemetzel seines Vaters am Schwarzen Drachenschwarm bewahrt.",},
			["Drachenfalke"] = { content = "Ein Drachenfalke ist ein recht gefügiger Vogel, den man als [[Wildtier]] außerhalb der [[Zuflucht der Weltenwanderer]] im [[Immersangwald]] finden kann. Sie stammen ursprünglich von [[Quel'Danas]]. Von den [[Blutelfen]] wird er als Begleiter für [[Jäger]] hoch geschätzt und ein [[Drachenfalkenjunges]] ist ein beliebtes [[:Kategorie:Gefährte|Haustier]].\r\n==Wildlebende Arten==\r\n* '''Wahnsinniger Drachenfalke''' - [[Immersangwald]]\r\n* '''Wildes Drachenfalkenjunges''' - [[Immersangwald]]\r\n==Begleiter==\r\n* '''Bluthabicht''' - [[Festung der Stürme: Botanika]]\r\n* '''Drachenfalke der Mondfinsternis''' - Begleiter der [[Blutelfen der Mondfinsternis]] im [[Schattenmondtal]].\r\n* '''Drachenfalke der Seher''' - Begleiter der [[Blutelfen]] der [[Seher]] in [[Shattrath]].\r\n==Haustiere==\r\n* Siehe [[Drachenfalkenjunges]]",},
			["Drachenfalken"] = { content = "#REDIRECT [[Drachenfalke]]", redirect = "Drachenfalke",},
			["Drachenfalkenjunges"] = { content = "#REDIRECT [[Drachenfalke]]", redirect = "Drachenfalke",},
			["Drachenfeueramulett"] = { content = "Das '''Drachenfeueramulett''' ist ein Medaillon, das aus den Schädeln der Feinde des [[Schwarzer Drachenschwarm|Schwarzen Drachenschwarms]] gefertigt wurde. Es wird von den Elitewachen [[Onyxia]]s als Ehrenabzeichen getragen, als Symbol für den Aufstieg in die am höchsten geschätzten Reihen: Wächter der Brutmutter. Das ruhende Amulett benötigt nur das Blut von [[General Drakkisath]], um wieder aktiv zu sein. Das ist einer ihrer primitiven, ausfallsicheren Mechanismen. Das Drachenfeueramulett ist außerdem der Schlüssel zu [[Onyxias Hort]].",},
			["Drachenmalklan"] = { content = "Der '''Drachenmal Klan''', ein hochangesehener Stamm innerhalb der Orcischen [[Horde]], war schon vor den Zeiten der [[Hexenmeister]] gegründet worden. Während des [[Der Erste Krieg|Ersten Krieges]] wurden die Drachenmals zu einer starken Stütze des [[Schwarzfels Klan]]s und waren ihrem Kriegsherrn [[Rend Schwarzfaust|Schwarzfaust]] treu ergeben. Nach dessen Ableben hielt der Stamm an seinem Treueschur fest und stellte sich in die Dienste von [[Rend Schwarzfaust|Schwarzfausts]] Söhnen, den Anführern des [[Black Tooth Grin Klan]]s. Der Drachenmal Klan hatte seine Stellung auf Khaz Modan gehalten bis [[Alexstrasza]] befreit wurde und so lange wie die [[Orcs]] dort die Arbeit der [[Horde]] fortsetzten, blieben sie ein möglicher Sammelpunkt für jene in den geschützten Enklaven. Wenn man der teuren Armee des Drachenmals beitreten will, dann muss man arbeiten. Das Drachenmal behandelt Neulinge aufrichtig, denn selbst ein ausgelaugtes und gezeichnetes Wesen bekommt seine Chance.\r\n(Quelle: \r\n==Ränge==\r\n* [[Himmelsteiler|Himmelsteiler des Drachenmals]]\r\n* '''Aufseher des Drachenmals''' - Es gibt eine Sache, die jeder gute Aufseher braucht: die richtige Ordnungswaffe. Bevor man dort hinausgehen und diesen Peons etwas Verstand einprügeln kann, braucht man eine Waffe. Jeder Aufseher muss die Materialien zur Herstellung seiner eigenen Waffe sammeln. Man benötigt Knotenhautleder und den gehärteten Balg von [[Tyrantus]]. \r\n* '''Peon des Drachenmals''' - Ein Aufseher wird einen [[Schuhmerang]] verwenden, um Furcht in die Herzen aufsässiger Peons zu pflanzen. Der richtige Einsatz des Schuhmerangs wird für Gehorsam und Unterwürfigkeit sorgen. Es ist selten, dass ein Peon lange überlebt. Es ist allerdings noch seltener, dass sich ein Peon vom Abschaum abhebt und in einen neuen Rang aufsteigt. \r\n==Orte==\r\n* [[Tore des Drachenmals]] ([[Sumpfland]])\r\n* [[Basislager des Drachenmals]] ([[Schattenmondtal]])\r\n* [[Festung des Drachenmals]] ([[Schattenmondtal]])\r\n==Persönlichkeiten==\r\n* [[Häuptling Nek'rosh]]\r\n* [[Illidarifürst Balthas]] - [[Schattenmondtal]] / [[Basislager des Drachenmals]] \r\n* [[Ma'ruk Wyrmschuppe]] - Kriegsherr des Drachenmals\r\n* [[Oberanführer Mor'ghor]] - [[Schattenmondtal]] / [[Basislager des Drachenmals]] \r\n* [[Zuchtmeister Varkule Drachenodem ]] - [[Schattenmondtal]] / [[Basislager des Drachenmals]] \r\n* [[Zuluhed]]\r\n==Geschichte==\r\n* '''Siehe auch:''' [[Die Schlacht von Grim Batol]]\r\n'''Die Macht der Dämonenseele'''\r\nDie Drachenmals bedienten sich vor allem der Magie, mit denen [[Zuluhed]] sie ausgestattet hatte. Als ihm die [[Dämonenseele]] in die Hände fiel, heckten [[Rend Schwarzfaust]] und Maim eine Plan aus, um die Drachenkönigin [[Alexstrasza]] gefangen zu nehmen. [[Zuluhed]] überließ das mächtige Artefakt dem loyalen [[Hexenmeister]] [[Nekros Schädelberster]], da es nicht auf die Magie des [[Schamanen]] ansprach. Durch die [[Dämonenseele]] wurde [[Alexstrasza]] in einem dauerhaften Zustand der Schwäche und des Schmerzes gehalten. Man brachte die [[Drachen]]königin nach [[Grim Batol]] und legte sie in mächtige Ketten aus diamantenhartem Stahl. [[Nekros]] zog ihre Jungen auf und richtete sie dazu ab, die Feinde der [[Horde]] zu vernichten. Zwar hatte man sich die [[Drachen]] vorerst gefügig gemacht, aber sobald sie zu stark wurden, um sie problemslos kontrollieren zu können, mussten sie getötet werden.\r\n'''Der letzte Widerstand'''\r\nAuch nach dem Zweiten Krieg stellten die [[Drachen]] noch die mächtigste Waffe des Drachenmal Klans dar. Während die meisten [[Orcs]] ein Dasein in Gefangenschaft führten, kontrollierte [[Zuluhed]]s Stamm auch weiterhin das nördliche [[Khaz Modan.]] Die Bergfestungen [[Dun Algaz]] und [[Grim Batol]] leisteten der [[Allianz]] von [[Lordaeron]] erfolgreich Widerstand. Obwohl die [[Horde]] eine verheerende Niederlage erlitten hatte, sandte [[Nekros]] seine [[Drachen]] aus, um die Küsten [[Lordaeron]]s zu terrorisieren. Auch die [[Greifenreiter]] der [[Zwerge]] konnten nicht verhindern, dass unzählige Unschuldige getötet wurden.\r\n'''Die letzte Bastion der Horde'''\r\nIm nördlichen [[Khaz Modan]] hatten die Drachenmals eine stattliche Armee aufgestellt, ihre mächtigste Waffe waren jedoch die gewaltigen [[Drachen]] aus [[Grim Batol]]. Der [[Schamane]] [[Zuluhed]] setzte die gefürchteten Bestien ein, um [[Dun Algaz]] auch weiterhin gegen die Armeen der [[Allianz]] zu verteidigen. Nahe der Ruinen von [[Dun Modr]] bezogen die freien Völker [[Lordaeron]]s Stellung, um die Bedrohung durch die [[Horde]] ein für alle Mal zu beenden. Nur dank der [[Drachen]], die von [[Hexenmeister]] [[Nekros Schädelberster]] gezüchtet und abgerichtet wurden, konnte die Bergfestung den beständigen Angriffen standhalten. In den folgenden Monaten wurden immer mehr [[Drachen]] nach Norden geschickt, und die Brutstätten blieben schließlich fast schutzlos zurück. Die große Schlacht von [[Grim Batol]], in der die [[Drachen]]königin [[Alexstrasza]] befreit wurde, besiegelte das Schicksal der [[Orcs]]. Ohne Verstärkung war es nur eine Frage der Zeit, bis auch [[Dun Algaz]] dem gnadenlosen Ansturm der [[Allianz]] zum Opfer fiel.",},
			["Drachenmal Klan"] = { content = "#REDIRECT [[Drachenmalklan]]", redirect = "Drachenmalklan",},
			["Drachenseele"] = { content = "Die '''Dämonenseele''', auch ''Drachenseele'' genannt, war eine unscheinbare goldene Scheibe und diente [[Neltharion]], dem Herr des [[Schwarzer Drachenschwarm|Schwarzen Drachenschwarms]], als Fokus, um die Kräfte der anderen Drachen zu stehlen und zu bündeln.\r\n==Geschichte==\r\nAls die [[Brennende Legion]], das gewaltige Heer des dunklen Titanen [[Sargeras]], die ahnungslose Welt [[Azeroth]] überfiel, kam es zu einem titanischen Kampf zwischen [[Drachen]] und [[Dämonen]]. Die Drachen waren von den [[Titanen]] ermächtigt worden, über ihre Schöpfung zu wachen und den Frieden dieser Welt zu verteidigen. Obwohl sie über unermessliche Kräfte verfügten, wurde ihnen schnell klar, dass sie die Legion nicht allein durch ihre Stärke besiegen konnten. Während ihrer katastrophalen Invasion waren die Dämonen über ganz [[Kalimdor]] ausgeschwärmt und hatten nur Asche und Elend hinter sich zurückgelassen. Um den Ansturm der Brennenden Legion aufzuhalten, erschuff [[Neltharion]], der auch [[Todesschwinge]] genannt wurde, und die Dämonenseele - ein magisches Artefakt, das die Dämonen aus [[Azeroth]] vertreiben sollte. \r\n===Der Verrat===\r\nEr überzeugte die [[Drachen]], allem voran die machtvollen [[Drachenaspekte|Aspekte]], ihre Lebensenergien an die Dämonenseele zu binden. Der schwarze Leviathan vermied es jedoch, selbst einen Teil seiner Macht auf das [[Artefakt]] zu übertragen. Bis auf ihn waren nun alle [[Drachen]] geschwächt und durch die Kräfte der Dämonenseele verwundbar. Mit Mühe gelang es den [[Drachen]] und ihren Verbündeten, die [[Brennende Legion|Legion]] und ihre infernalischen Meister aus [[Azeroth]] zu verbannen. Doch [[Todesschwinge]] hinterging seine Artgenossen und setzte das mächtige Artefakt nun gegen alle [[Drachen]] ein, die nicht zu seiner Sippe zählten. Er hatte entschieden, dass die schwarzen Drachen die Zukunft seines Volkes darstellten. Sein Verrat und die schrecklichen Kämpfe zwischen den Drachen forderten viele Opfer - er trieb nicht nur die eigene Brut, sondern auch viele andere bis an den Rand der Vernichtung. Trotzdem stand er kurz davor, als Sieger aus dem verheerenden Bürgerkrieg hervorzugehen. Schließlich verbündeten sich die verbliebenen Drachen gegen [[Todesschwinge]] und belegten ihn mit einem Bann, so dass er die Dämonenseele nicht mehr gegen sie einsetzten konnte. Da es ihnen aber unmöglich war, das mächtige Artefakt zu berühren oder gar zu zerstören, verbargen sie es in den Tiefen der Erde. Für viele Jahrtausende galt die Dämonenseele als verloren. \r\n===Gleichgewicht der Kräfte===\r\nVor den Zeiten des Zweiten Krieges stellte [[Todesschwinge]] sicher, dass die Dämonenseele ihren Weg in die Hände der [[Orcs]] fand. Obwohl er die Kräfte des uralten Artefakts nicht mehr nutzen konnte, manipulierte er andere, sie in seinem Sinne zu gebrauchen. [[Hexenmeister]] [[Nekros Schädelberster]] nahm Drachenkönigin [[Alexstrasza]] gefangen und hielt sie durch die Dämonenseele in einem dauerhaften Zustand der Schwäche und des Schmerzes. [[Alexstrasza]] wurde in mächtige Ketten aus diamantenhartem Stahl gelegt und [[Nekros]] erschuff einen Feuergolem, der ihr Verlies in [[Grim Batol]] ständig bewachte. Als widerwillige Sklavin des [[Drachenmal Klan]]s legte die Drachenkönigin ihre kostbaren Eier. Durch ihre Gefangennahme waren die [[Roter Drachenschwarm|roten Drachen]] gezwungen, sich den [[Orcs]] zu fügen - die [[Alexstrasza]]s Abkömmlinge dazu abrichteten, die Feinde der [[Orc]]ischen Horde zu vernichten. Erst der tollkühne [[Magier]] [[Rhonin]] konnte die majestätischen Geschöpfe aus dem Bann der Dämonenseele befreien. Während der großen Schlacht von [[Grim Batol]] zerstörte er das [[Artefakt]] mit einem magischen Kristall, den [[Todesschwinge]] einst erschaffen hatte. Die mächtigen Energien, die in der Dämonenseele gefangen waren, wurden freigesetzt und kehrten zu ihren rechtmäßigen Besitzern zurück.",},
			["Drachensekte"] = { content = "Die '''Drachensekte''' verehrt die [[Drachen]]schwärme und deren Aspekte wie Götter. Sie werden vor allen Dingen von den [[Nachtelfen]] verehrt, besonders [[Ysera]] und [[Alexstrasza]]. Auch in den Mythen der [[Tauren]] werden die Drachen als Lieblinge der [[Erdenmutter]] dargestellt. Die Drachenkultisten zeigen sich selten in der Öffentlichkeit und halten sich aus dem Geschehen der Welt großteils heraus.\r\n==Bekannte Drachensekten==\r\n* [[Wyrmkult]]\r\n==Fürs Rollenspiel==\r\nFolgende [[:Kategorie:Gemeinschaften|Gemeinschaften]] oder [[:Kategorie:Gilde|Gilden]] der Forscherliga folgen dem Vorbild einer Drachensekte:\r\n* [[Orden der Malygos-Magier]]",},
			["Drachenwelpling"] = { content = "Ja als Welplinge sind sie noch süß, aber als ausgewachsene [[Drache]]n möchten wir ihnen nicht mehr begegnen. Aber selber macht man ja alles besser und wenn man den Welpen nur gut erzieht wird aus ihm nie ein großer gemeiner [[Drache]].\r\n==Arten==\r\nFolgende Drachenwelplinge kann man in [[Azeroth]] finden.\r\n* '''Azurblaue Welplinge''' findet man bei den [[Drache]]n des [[Blauer Drachenschwarm|Blauen Drachenschwarms]] in [[Azshara]].\r\n* '''Dunkelwelplinge''' findet man unter brühenden Welpen im [[Ödland]] oder bei sengenden Welpen in den [[Düstermarschen]].\r\n* '''Netherwelpe''' erhält man nur beim Kauf der Collectors Edition.\r\n* '''Purpurrote Welplinge''' können bei den [[Roter Drachenschwarm|Roten Drachen]] im Nordosten des [[Sumpfland]]es erbeutet werden.\r\n* '''Smaragdgrüne Welplinge''' findet Ihr ausschließlich in den [[Sümpfe des Elends|Sümpfen des Elends]] bei träumenden Welpen.",},
			["Drachisch für Dummies"] = { content = "==Drachisch für Dummies: Band 1==\r\nBand 1 von Drachisch für Dummies finden man in der Unterstadt.\r\n''Ashj Zek Ulrakkas Naztheros re sorankar ante rethule, Mannorgulan. Ril karaman tichar Maz Ashjrethul azgala, rakir rethul Faralos re sorankar? Te lek Asj zennshinagas.''\r\n==Drachisch für Dummies: Band 2==\r\n[[Narain Pfauentraum]] besaß das Orginal des Buches: \"Drachisch für Dummies, Teil 2\". Er wusste, dass dieses Buch eines Tages nützlich sein würde und deshalb hatte er es an einem sicheren Ort verstaut, d.h. auf einer Insel der südlichen Meere vergraben. Er brauchte einen Gyrokopter, um dorthin zu gelangen, doch bedauerlicherweise musste er auf dem Rückweg am Strand bruchlanden. Sein verunglückter Gyrokopter liegt noch irgendwo am Landendestrand. Zu allem Überfluss wurde sein kostbares Buch von \"[[Nummer Zwei]]\" aus dem [[Gyrokopter]] gestohlen und nur eine \"lÖsEGeLd\"-Forderung hinterlassen. Nun braucht er einen \"Lockvogel\", der nach [[Winterquell]] reist und die Tasche voller Gold, so wie es die Buchnapper angegeben haben, am Übergabepunkt platziert. Er wird einen Sack mit Steinen füllen. Der Lockvogel nimmt Narains Turban, Robe und den Sack voller Steine. Alles, was er benötigen wird, befindet sich in einem Spezialset. Sobald die Räuber auftauchen, um die Ware abzuholen, macht man sie fertig. ... So der Plan ... Doch letzten Ende ist \"Der einzige Weg\", die 8 verlorenen Kapitel von Drachisch für Dummies zu finden und sie mit dem magischen Bucheinband zu vereinen, denn die einzig bekannte Kopie wurde in 8 Teile zerrissen und im Wind zerstreut.",},
			["Drachkin"] = { content = "#REDIRECT [[Drachen]]", redirect = "Drachen",},
			["Draco-Incarcinatrix 900"] = { content = "Der '''Draco-Incarcinatrix 900''' ist ein Gerät, mit dem man die Essenz von Großdrachenwelpenbrutlingen einfangen kann. Gebaut wurde der Incarcinatrix von [[Tinkee Kesseldampf]] in der [[Brennende Steppe|Brennenden Steppe]].",},
			["Draco-Incarcinatrix 900"] = { content = "Der '''Draco-Incarcinatrix 900''' ist ein Gerät, mit dem man die Essenz von Großdrachenwelpenbrutlingen einfangen kann. Gebaut wurde der Incarcinatrix von [[Tinkee Kesseldampf]] in der [[Brennende Steppe|Brennenden Steppe]].",},
			["Draenei"] = { content = "* Sprache: [[Draenisch]]\r\n* Auch bekannt als '''[[Eredar]]'''\r\nVor einem Monat zerriss eine furchtbare Explosion die Wolken über dem nördlichen [[Kalimdor]]. Im selben Augeblick stürzte das große Schiff [[Exodar]] vom Himmel herab auf die Weiten [[Azeroth]]s. Die noblen Draenei, aus der verwüsteten [[Scherbenwelt]] geflohen, hatten die durch Dimensionen reisende [[Exodar]] benutzt, um einen sicheren Zufluchtsort zu finden. Angeregt von [[:Kategorie: Geschichte|Geschichten]] über die tapfere [[Allianz]], die sich der Macht der [[Brennende Legion|Brennenden Legion]] entgegenstellte, sind die Draenei gekommen, um Hilfe bei der Rückeroberung ihrer zerstörten Heimat zu erhalten. Der Erhaltung von Leben und der Bewahrung der Lehren des Heiligen Lichts gewidmet, hoffen die Draenei, ein neues Bündnis von [[Krieger|Kämpfern]] aufbieten zu können, um der [[Brennende Legion|Brennenden Legion]] entgegenzutreten und ihrem schrecklichen [[Brennende Legion|Brennenden Kreuzzug]] ein Ende zu setzen. Allein mit Mut und ihrem unerschütterlichen Glauben an das Licht bewaffnet, warten sie auf ein Zusammentreffen mit der [[Allianz]], um sie zu ihrem Schicksal hinter den Himmeln von [[Azeroth]] zu führen.\r\n==Klassen==\r\n* [[Draenei Jäger]] \r\n* [[Draenei Krieger]] - (Friedensbewahrer, [[Hand von Argus]]) \r\n* [[Draenei Magier]] \r\n* [[Draenei Paladin]]\r\n* [[Draenei Priester]] - ([[Anachoret]], [[Beschützer der Azurwacht]]) \r\n* [[Draenei Schamane]] \r\n==Geschichte der Draenei==\r\nVor fast 25.000 Jahren entstand auf der Welt [[Argus]] das Volk der [[Eredar]]. Sie waren äußerst intelligent und hatten eine natürliche Begabung für den Umgang mit sämtlichen Formen von [[Magie]]. Sie benutzten ihre angeborenen Gaben, um eine gewaltige und wundersame Gesellschaft zu gründen.\r\nUnglücklicherweise zogen die Errungenschaften der [[Eredar]] die Aufmerksamkeit von [[Sargeras]], dem Verwüster der Welten, auf sich, der bereits seinen brennenden Kreuzzug begonnen hatte, mittels dem er alles Leben im Kosmos auslöschen wollte. Er war der Ansicht, dass die brillanten [[Eredar]] die perfekten Anführer für die riesigen [[dämon]]ischen Armeen abgeben würden, die er versammelte. Also setzte er sich mit den drei bedeutendsten Oberhäuptern der Eredar in Verbindung: [[Kil'jaeden]], [[Archimonde]] und [[Velen]]. Er bot ihnen als Gegenleistung für die Loyalität des Volkes der Eredar unermessliche Macht und Wissen an.\r\n[[Sargeras]]’ Angebot hörte sich äußerst verführerisch an, aber [[Velen]] hatte eine Vision der Zukunft, die ihn mit kaltem Grauen erfüllte. [[Sargeras]] hatte die Wahrheit gesprochen, die [[Eredar]], die sich dem dunklen [[Titanen]] anschließen würden, würden in der Tat enorme Macht und großes Wissen erlangen. Allerdings würde sich ihr Volk auch in [[Dämon]]en verwandeln.\r\nIn seiner Vision sah [[Velen]] das volle Ausmaß der schrecklichen Macht der [[brennende Legion|Legion]] und die Zerstörung, die sie der ganzen Schöpfung bringen würde. Also eilte er zu [[Kil'jaeden]] und [[Archimonde]], um sie zu warnen. Die beiden nahmen seine Befürchtungen allerdings nicht ernst, da [[Sargeras]] sie bereits mit seinen Versprechungen in seinen Bann gezogen hatte. Sie schworen [[Sargeras]] die Treue und wurden in kolossale Wesen von abgrundtiefer Bosheit verwandelt.\r\nDie überwältigende Macht von [[Sargeras]] machte direkten Widerstand geradezu undenkbar. Velen war am Rande der Verzweiflung, aber seine Gebete um Hilfe wurden erhört. Ein Wesen besuchte [[Velen]] und erklärte ihm, dass es zu den [[Naaru]] gehörte, einem über ein Bewusstsein verfügendes Volk von Energiewesen, deren Ziel es war die [[Brennende Legion]] aufzuhalten. Die [[Naaru]] boten [[Velen]] und allen gleich gesinnten Eredar an, sie in Sicherheit zu bringen.\r\n[[Velen]] war tief erleichtert und begann die anderen [[Eredar]] um sich zu sammeln, die es abgelehnt hatten [[Sargeras]] die Treue zu schwören. Sie nannten sich die Draenei, was in der Sprache der Eredar '''„die Heimatlosen“''' bedeutete. Die abtrünnigen Eredar schafften es gerade so von Argus zu fliehen - mit der [[Brennende Legion|Legion]] dicht auf ihren Fersen. [[Kil'jaeden]] war erzürnt über [[Velen]]s Taten, die er als Verrat ansah, und der [[Dämon]] schwor sich, [[Velen]] und die anderen Draenei bis zum Ende des Kosmos zu jagen, wenn es nötig sein sollte.\r\nDie [[Brennende Legion|Legion]] verfolgte die Draenei viele Jahrtausende lang. Auf ihrer Suche nach einem sicheren Hafen besuchten die Draenei viele Welten und erforschten einen Großteil des bekannten Kosmos. Aber die [[brennende Legion|Legion]] gab ihre Verfolgung nicht auf. In der Zwischenzeit segneten die rätselhaften [[Naaru]] die Draenei mit der Macht und dem Wissen des heiligen Lichts. Die [[Naaru]] erklärten, dass es noch andere Mächte im Kosmos gab, die sich der [[Brennende Legion|Brennenden Legion]] entgegenstellen würden. Eines Tages würden die [[Naaru]] all diese Mächte zu einer einzigen, unaufhaltsamen Armee des heiligen Lichts zusammenschließen. Tief beeindruckt von den Worten der [[Naaru]] schworen die Draenei das heilige Licht zu ehren und die selbstlosen Ideale der [[Naaru]] aufrechtzuerhalten.\r\nDann ließen sich [[Velen]] und seine Draenei endlich auf einer abgelegenen Welt nieder, die eine ideale Zuflucht zu sein schien. Deshalb nannten sie sie [[Draenor]], oder auch „die Zuflucht“. Dort kultivierten sie im Stillen erneut ihre Gesellschaft. Immer darauf bedacht, nicht wieder von der Legion entdeckt zu werden, verbargen Velen und seine Mystiker ihre [[Magie]] über Generationen hinweg.\r\nMit der Zeit trafen die Draenei die [[Schamanen|schamanistischen]] [[Orcs]], die schon in dem friedlichen Grünland im Süden von [[Nagrand]] lebten, und freundeten sich mit ihnen an. Die Draenei und [[Orcs]] respektierten sich gegenseitig, hielten sich aber abgesehen von begrenztem Handel voneinander fern.\r\nDer Vorsicht der Draenei zum Trotz entdeckte [[Kil'jaeden]] jedoch schließlich ihre geheime Zuflucht auf [[Draenor]]. Er studierte die Welt und ihre Einwohner und war von den mächtigen [[Orcs]] fasziniert. Der [[Dämon]]enlord begann zu lachen, denn ein Plan begann sich in seinen Gedanken zu entfalten. Er konnte sich genau vorstellen, wie er die [[Orcs]] zu Werkzeugen seines Zorns machen konnte. Es war nur eine Frage von Zeit und der Ausübung von genügend Druck.\r\nUnd so begann [[Kil'jaeden]] mit der Korruption der [[Orcs]]. Zuerst mittels des alten [[Schamanen]] [[Ner'zhul]] und dann durch seinen Lehrling [[Gul'dan]]. Die [[Orcs]] widmeten sich völlig der Kriegskunst und schlossen sich zu einer einzelnen, mordlustigen [[Horde]] zusammen. Selbst die weisesten [[Schamanen]] wandten sich von den Lehren ab, die sie einst geehrt hatten, und lernten stattdessen die dunkle [[Magie]] von [[Hexenmeister]]n.\r\n[[Kil'jaeden]] hatte die [[Orcs]], die die Draenei zunächst wachsam gebilligt hatten, kunstvoll zu mordlustigen Bestien manipuliert, die die Draenei voll von blindem Hass angriffen. Dieser blutige Konflikt dauerte acht Jahre lang an, aber der Sieg der [[Orcs]] war unausweichlich. Trotz der den Draenei vom heiligen Licht verliehenen Mächte konnten sie dem [[dämon]]ischen Wahn der [[Orcs]] nicht standhalten. Die [[Orcs]] löschten über 80% der Draeneibevölkerung aus und vertrieben die Überlebenden in die entlegensten Winkel der Welt.\r\nEinige der Draenei, die den Kampf gegen die [[Horde]] überlebt hatten, mutierten später in missgebildete Formen, was zu einer Reihe von Unterarten ihres Volkes führte. Der Grund für diese Mutationen war die Energie der teuflischen Verderbnis, die die [[Hexenmeister]] der [[Orcs]] gegen sie angewendet hatten. Die Zerschlagenen und die Verirrten sind zwei solcher Unterarten. Ihre verformten Körper sehen den stolzen Draenei, die sie einst waren, nur noch entfernt ähnlich und viele von ihnen sind dem Wahnsinn verfallen.\r\n'''Quelle:''' wow-europe.com\r\n==Aussehen==\r\n \r\nDraenei unterscheiden sich physisch von den Eredar der Brennenden Legion. Die Hautfarbe der Draenei kann variieren, von elfenbeinfarben, azurblau, dunkelblau, violett bis hin zu ebenholzfarben. Die rötliche Färbung der Haut bei den dämonischen Eredar tritt bei den Draenei nicht auf. Ebenso haben sie nicht die Hörner, die die Gesichter der Eredar aufweisen (Diese sind bei ingame-models nicht erkennbar, nur auf den existierenden Zeichnungen zu sehen). Sie haben Reißzähne. Im Buch „Aufstieg der Horde“ werden die Draenei als über und über blau beschrieben (mit Ausnahme von Velen, dessen Haut im Alter als weißlich beschrieben wird). In WoW: The Burning Crusade, reichen die Farbtöne der Draenei-Haut von einem blassrosa-weiß über hellblau, bis hin zu einem dunklen Violett. Ihr Blut ist dunkelblau. Die Draenei, die ihre „Gabe der Naaru“ nutzen, haben für die Dauer des Effekts ein glühendes Sigil-Zeichen über ihrer Stirn schweben. Männliche Draenei wachsen oft Tentakel aus ihrem Kinn und sie haben eine fächerförmige Stirnplatte, die ihre vordere Kopfhälfte überlagert. Männliche Draenei haben lange Schwänze, deren Bewegungen sie durch Muskeln steuern können. Die weiblichen Draenei sehen ganz anders aus: Statt Stirnplatten haben sie Erweiterungen der Schädeldecke, die oft an Hörner erinnern. Ihre Tentakel wachsen hinter den Ohren und sind in der Regel lang genug, um auf ihre Schultern herab zu reichen. Sie sind dünner als die der männlichen Draenei. Die Schwänze der weiblichen Draenei sind dünner und haben eine geringere Muskeldichte. Bei beiden Geschlechtern sind die Hufe sehr groß und stabil geraten, im Gegensatz zu ihren dämonischen Verwandten. Länge der Tentakel und die Farbe der Haare variieren von Draenei zu Draenei.\r\n==Kultur==\r\n \r\nIm Mittelpunkt der Draenei-Kultur stehen zwei Dinge: Das Heilige Licht der Schöpfung und die Magie. Ersteres ist ein Resultat ihrer einzigartigen Beziehung zu den Naaru, letzteres ein Traditionsgut, das die Eredar schon immer verehrt hatten. Als ein Resultat wählen die Draenei überwiegend religiöse Professionen, wie die des Priesters oder des Paladins, oder auch magische, wie die des Magiers. Ein paar unter ihnen begannen auch, den Pfad des Schamanen zu beschreiten unter der Führung des Weissagers Nobundo. In ihrem Alltag haben sich die Draenei gänzlich der Aufgabe gewandt, sich auf den Tag vorzubereiten, an dem sie von den Naaru in die „Armee des Lichts“ berufen werden und den finalen Kampf gegen die Brennende Legion aufnehmen, um für die Sünden ihrer Man’ari-Bruderschaft Buße zu tun. Wegen diesem übergeordneten Ziel leben die Draenei zum Teil sehr für sich und verfolgen ihre eigenen Interessen, so wie es andere Rassen auch tun. \r\nWas die rassenübergreifenden Beziehungen betrifft, misstraut die Mehrzahl der Draenei noch immer den Orcs oder hasst sie sogar, nach dem großen Leid, das die Grünhäuter ihnen in Draenor angetan haben. Einige Aspekte, wie ihre noch immer grüne Haut und die Tatsache, dass noch immer einige von ihnen die Hexenkunst praktizieren (obgleich sich die Gnome und die Menschen, ihre neuen Alliierten, auch dieses Vergehens schuldig machen), sowie ein privater Groll zwischen ihnen, machen den Weg zur Vergebung bestenfalls schwer begehbar, ganz gleich, welche Friedensinitiativen Velen und Thrall bereit sind, einzuleiten. Trotz allem gibt es Übereinkünfte zwischen ihnen; zum Beispiel hat der Schamanenzirkel „Der Irdene Ring“, der eigentlich Anhänger der Horde war, die Draenei-Schamanen, sowie die Schamanen der Zerschlagenen in ihren Reihen aufgenommen, um die Scherbenwelt zu heilen. Die Draenei hegen ebenfalls eine Abscheu gegen die Blutelfen, seit diese unter Prinz Kael'thas' Führung in ihrem Magiedurst die Festung der Stürme in der Scherbenwelt übernommen hatten, ohne dass die Draenei einen Angriff provoziert hatten. Die jüngsten Angebote an die Allianz fanden nur begrenzt Anklang. Viele Mitglieder der Allianz-Rassen haben Probleme damit, die Draenei von ihren korrumpierten einstigen Eredar-Verwandten, den Man'ari, abzugrenzen, denen auch beinahe die Zerstörung Azeroths gelungen wäre. Die Nachtelfen hatten ja sogar zweimal unter den Händen Archimondes leiden müssen. Trotz allem gab auch viele, die die Draenei schnell in ihren Reihen akzeptierten und Repräsentanten der Exodar wurden in den Herrschafts-Hallen der Allianz wilkommen geheißen, sogar bei den Nachtelfen, wo die Hohepriesterin Tyrande eine Botschafterin der Exodar direkt in ihrem Tempel verweilen lässt.",},
			["Draeneipriester"] = { content = "== Bezeichnungen==\r\nJe nach Ausrichtung und Aufgabe tragen Draenei Priester verschiedene Bezeichnungen, dazu gehören u.a.:\r\n* '''Beschützer der Azurwacht''' - Angehende [[Draenei]] [[Priester]] werden auch Beschützer der [[Azurwacht]] genannt und zeichnen sich als gläubige Anhänger des Lichts aus.",},
			["Draenethyst"] = { content = "Draenethyst ist neu auf [[Azeroth]] und stammt von der [[Scherbenwelt]], wo Berge fliegen und [[Dämonen]] herrschen. Ein Splitter aus Draenethyst befindet sich an einem Ort namens [[Sümpfe des Elends]] und ist im Besitz von Ongeku, dem [[Verirrte]]n. Draenethyst-Kristalle sind den [[Verirrte]]n heilig. Ohne sie, könnten sie vom rechten Weg abkommen. Doch es wird auch von den [[Zentauren der Gelkis]] benutzt, um ihre Magie zu verstärken.",},
			["Draenethystmine"] = { content = "Die Draenethystmine findet man im Schergrat am südlichen Ende der Blutschlägerklamm. Dort bauen die [[Oger der Blutschläger]] die [[Draenethyst]]kristalle ab und verwahren auch die Donnerlanze, ein Artefakt des [[Donnerfürsten Klan]].",},
			["Draenisch"] = { content = "'''Draenisch''' ist die Sprache der Draenei. Hier einige Übersetzungsbeispiele:",},
			["Draenor"] = { content = "Unter den glutroten Himmeln der finsteren Welt Draenor erstreckte sich nun eine öde Wildnis mit weitläufigen Wüsten und unzugänglichen Sumpfgebieten. Nur die Stärksten konnten unter diesen lebensfeindlichen Bedingungen überleben. Trotz allem versuchte eine ganze Zahl unterschiedlicher Völker und Kreaturen sich gegen die wilden Elemente zu behaupten. \r\n==Allgemeines==\r\nDraenor ist der Heimatplanet der [[Orcs]] und die einstige Zuflucht der [[Draenei]] vor der [[brennende Legion|Brennenden Legion]]. Die [[Orcs]] kamen, von der [[brennende Legion|Brennenden Legion]] verführt und in die ruchlosen und barbarischen Kampfmaschinen verwandelt, als blutdurstige Eroberer durch das [[Dunkle Portal]] nach [[Azeroth]]. Nach ihrem Sieg im Zweiten Krieg beschloss die [[Allianz]], den Krieg zurück zur Heimatwelt der [[Orcs]] zu führen. So kam es, dass eine Invasion zurück durch das [[Dunkle Portal]] nach [[Draenor]] entsand wurde, um die Bedrohung durch die [[Orcs]] ein für alle mal zu bannen. [[Ner'zhul]], der dunkle Kriegsfürst der [[Horde]], erzeugten in einem Akt der Verzweiflung eine gigantische Explosion, die ganz [[Draenor]] auseinander riss. Die verwüstete Einöde der [[Scherbenwelt]] ist alles, was von der einstmals blühenden Welt Draenor geblieben ist. Die [[Draenei]] flohen mit der [[Exodar]] von der zerstörten [[Scherbenwelt]] und überließen Draenor seinem Schicksal.\r\n===Die Verheerungen der Horde===\r\nDie [[Orcs]] waren Jahrtausende lang durch eine edle schamanische Kultur an die rauhe Welt gebunden. Doch die finsteren Agenten der [[Brennende Legion|Brennenden Legion]] trachteten danach, sie in eine unaufhaltsame Armee zu verwandeln. Der verschlagene [[Dämon]]enlord [[Kil'jaeden]] machte sich daran, ihre gefestigte Gesellschaft und ihren uralten Glauben von innen heraus zu verderben. Der machtgierige [[Hexenmeister]] Gul'dan vereinte die Stämme schließlich zu der willfährigen wilden [[Horde]], die [[Kil'jaeden]] erwartet hatte. Wie eine Naturgewalt donnerten die [[Orcs]] über Draenor und vernichteten alles, was sich ihrem Aufstieg zur unangefochtenen Herrschaft entgegenstellte. Der chaotischen Kräfte ihrer Hexenmeister und dem zunehmenden Ansturm der Clans konnte nicht einmal der mächtigste Feind lange standhalten. Auch das Volk der [[Oger]] wurde unterworfen und die monströsen Kreaturen schlugen im Namen des Schattenrates die Streitigkeiten innerhalb der [[orcs|orkischen]] Reihen nieder. \r\n===Flucht von der sterbenden Welt===\r\n[[Medivh]] machte der [[Horde]] das [[Dunkle Portal]] zugänglich, und viele der Clans strömten durch das Tor nach Azeroth, um das Volk der [[Menschen]] zu unterwerfen und Anspruch auf ihre Lande zu erheben. In den folgenden Jahren zogen die erbarmungslosen Krieger eine breite Schneise der Verwüstung durch die Königreiche - sie ließen nur Elend und verbrannte Erde zurück. Doch schließlich konnten die Waffenbrüder der [[Allianz]] ihren grausamen Amoklauf aufhalten. Es gelang dem Erzmagier Khadgar, das [[Dunkle Portal]] zu zerstören, und damit die [[Orcs]] von Verstärkung aus ihrer Heimatwelt abzuschneiden. Sie hatten den mächtigen Streitkräften der [[Allianz]] nichts mehr entgegenzusetzen. Kurz nach dem Ende des Zweiten Krieges drang die Kunde von der Niederlage der [[Horde]] nach Draenor. Der [[Schamanen|Schamane]] [[Ner'zhul]] befürchtete, dass [[Kil'jaeden]] und die [[Brennende Legion]] sein Volk drakonische bestrafen würden. Die verbliebenen Clans vereinigten sich unter Ner'zhuls Banner und ein neuer Feldzug gegen die ahnungslose [[Allianz]] wurde vorbereitet. Als sich die Energien des [[Dunkle Portal|Dunklen Portals]] wieder zusammenfügten, stürmten sie abermals nach [[Azeroth]]. Ner'zhul hatte die Absicht, weitere Portale in Draenor zu öffnen und der todgeweihten Welt für immer zu entfliehen. Die [[Horde]] zog plündernd durch das Land und sammelte in kurzer Zeit die benötigten Artefakte ein. König Terenas schickte seine Armeen nach Draenor, um die [[Orcs]] endgültig zu vernichten. Überall auf der roten Welt kam es zu zahlreichen Gefechten zwischen General Turalyons Truppen und den orkischen Clans. Doch Ner'zhul ließ sich nicht an der Umsetzung seiner perfiden Pläne hindern und öffnete tosende magische Pforten zu anderen Welten. Er konnte nicht ahnen, welchen schrecklichen Preis er dafür bezahlen sollte. \r\n===Die gepeinigte Welt am Abgrund===\r\nDie riesigen Energien der Portale begannen, Draenor bis in den innersten Kern zu erschüttern. Ungeheure Vulkanausbrüche und verheerende Erdbeben rissen die sterbende Welt auseinander. Magische Stürme fegten über das brennende Aschenland hinweg. Das kochende Meer strömte in die klaffenden Wunden Draenors und Sturmfluten begruben die Trümmer der verwüsteten Kontinente unter sich. Ner'zhul wurde klar, dass die kämpfenden Clans es nie und nimmer rechtzeitig zu den Portalen schaffen würden. Ihm gelang in Begleitung seiner treuen Anhänger die Flucht, während er die Stämme egoistisch ihrem Schicksal überließ. Nur der Kriegshymnenklan und die [[Orcs des Blutenden Auges]] erkannten, dass [[Ner'zhul]]s größenwahnsinnige Pläne ihr ganzes Volk dem Untergang preisgaben. Mit der Macht der Verzweifelung erkämpften sie sich einen Weg durch die Reihen der Menschen und flohen durch das [[Dunkle Portal]] nach [[Azeroth]]. [[Turalyon]]s Truppen hingegen fassten den selbstlosen Entschluss, das Portal - den einzigen Weg zurück in ihre Heimat - zu zerstören. Obschon ihnen klar war, dass sie auf der sterbenden Welt gefangen sein würden, sollte [[Azeroth]] durch die brutale Vernichtung Draenors keinen Schaden nehmen. Es bleibt abzuwarten, ob [[Khadgar]] und seine Kameraden dem Todeskampf entkommen konnten oder nicht. Schließlich wurde die gepeinigte Welt durch eine Explosion apokalyptischen Ausmaßes zerstört. Die Trümmer Draenors trieben noch immer durch das [[Großes Dunkles Jenseits|Große Dunkle Jenseits]] und boten den Überlebende eine Heimat, doch die orkische Chaosmagie hatte ihre Welt verzehrt. Die rote Wüstenlandschaft mit ihren weitläufigen Ebenen wurde von nun an nur noch '''\"Scherbenwelt\"''' genannt.",},
			["Draka"] = { content = "'''Draka''' war die Tochter von Kelkar und Rhakish. Sie wurde krank geboren, schaffte es jedooch, die Krankheit zu überwinden und verliebte sich in [[Durotan]], welcher ihre Liebe erwiderte. Während der zunehmenden Korrumpierung ihres Volkes, gegen die sie nichts tun konnte, wurde sie resignierend und bitter, doch blieb sich selbst und ihren Idealen stets treu. \r\nSie war eine Kriegerin, ihrem Ehemann [[Durotan]] gleich im Mut und listig. Sie hatte ein schönes Gesicht, einen starken Kiefer und braune Augen. Ihre Fingernägel waren rasiermesserscharf zurechtgefeilt und Draka trug Stolz in ihrer Stimme. Besonders kam ihre Stärke im Schein des Feuers zur Geltung, denn das Licht des Feuers spielte mit ihrer grünen Haut, warf ihre mächtigen Muskeln in ein scharfes Relief und ließ ihre Stoßzähne scheinen. \r\n'''Quelle'''",},
			["Drakeoden"] = { content = "Drakeadon \r\n[[Nefarian]]s kranke Experimente schufen auch andere Wesen als nur den [[Chromatischen Drachenschwarm]]: Die Drakeoden.Er vermengte die noch ungeborenen Embryonen zweier ,verschiedener [[Drachen]]schwärme und gab sein Blut dazu. Die Kreatur , die er damit erschuf, war monströser als alles andere, was er hervorgebracht hatte:Die bedauernswerten Wesen hatten zwei Köpfe,riesige Dornen am Rücken und [[Nefarian]]s Hass im Herzen, der sie gegen die Feinde ihres Herren treibt.\r\nBemerkenswerte Drakeaoden \r\n[[Chromaggus]]",},
			["Drakkari"] = { content = "#REDIRECT [[Trolle der Drakkari]]", redirect = "Trolle der Drakkari",},
			["Drakonid"] = { content = "'''Drakoniden''' zählen zu den [[Drachkin]] und sind ebenso wie die [[Drachenbrut]] halb Humanoid und halb drachisch. Im Unterschied zur [[Drachenbrut]] aber gehen sie aufrecht auf zwei Beinen. Drakoniden dienen oft als Fußsoldaten oder Patrouillen der Drachenschwärme.\r\n==Persönlichkeiten==\r\nZu den berühmten Drakoniden zählen u.a.:\r\n* [[Brutwächter Dreschbringer]]\r\n* [[Chronolord Deja]]\r\n* [[Lord Valthalak]]",},
			["Drek'Thar"] = { content = "==Allgemeines==\r\nDrek'Thar ist seit seiner Geburt blind, aber dennoch ein starker und mächtiger Scharfseher. Er wurde früher stets von Pelkar, einem Kind, und einem Frostwolf namens Weißohr begleitet.\r\n==Geschichte== \r\nDer [[Schamanen]]älteste des [[Frostwolfklan]]s diente vor vielen Jahren als [[Thrall]]s Tutor und musste seinen Wert in der dunkelsten Ära der [[Horde]] unter Beweis stellen. Er stellte fest, dass die Geister der Elemente enge Gefährten waren und so wurde der Schamanismus für ihn der Weg zur Macht. Obwohl Drek'Thar über die Elemente gebietet, blieb er doch stets bescheiden und weise. Er unterrichtet die jüngeren [[Schamanen]] der [[Horde]] in den alten Traditionen seines Volkes. Drek'Thar ist einer der letzten Schamanen, der alten Generation. Er übernahm den [[Frostwolfklan]], nachdem [[Durotan]] und [[Draka]] nicht von ihrer Reise zu [[Orgrim Schicksalshammer]] zurückkehrten. Er holte [[Thrall]] in den Klan und unterzog ihn mehreren Prüfungen. [[Thrall]] bestand die Aufgaben und der Alte begann alsbald seinen Unterricht. Er führte [[Thrall]] auf den Pfad der [[Schamanen]]. Überraschenderweise nahmen ihn die Geister auf und [[Thrall]] wurde mächtiger als Drek'Thar es sich hatte träumen lassen. Weißohr kam bald mit [[Orgrim Schicksalshammer]] zurück. Orgrim mochte den jungen [[Thrall]] und er plante sein Volk aus den Lagern zu befreien. Drek'Thar stand ihm als Heiler zur Verfügung doch konnte er wegen des großen Risikos nicht am Kampf teilnehmen, denn nur er und Schicksalshammer hatten die Macht, [[Thrall]] zu unterrichten.\r\nWeißohr und [[Orgrim Schicksalshammer]] fielen beide in der Schlacht um das fünfte Lager. Nun war es an Drek'Thar, aus Thrall einen guten [[Krieger]] und [[Schamanen]], aber vor allem Anführer, zu machen. Gewitzt wie der Alte war, reiste er in die alten Ruinen, auf Schlachtfelder und zu verschiedenen Leuten und stellte aus verschiedenen Buchseiten aus magischen Bänden sein eigenes zusammen. Drek'Thar war es auch, der mit [[Thrall]] nach [[Kalimdor]] reiste und er ist der Einzige der alten Generation, welcher die neue Heimat von [[Orgrimmar]] gesehen hat. Der alte Mann lebt immer noch im [[Alteractal]] und steht [[Thrall]] mit Rat und Tat zur Seite...",},
			["Dreschadon"] = { content = "Die urtümlichen '''Dreschadon''' leben in den Tiefen der Meere und lassen sich nur selten in den seichteren Gewässern an den Küsten der blicken. Man weiß von großen Populationen dieser Wildtiere in der [[Dunkelküste]] und dem [[Brachland]].\r\n==Arten==\r\n* '''Dunkelküstendrescher'''\r\n* '''Riesendrescher''' - Die Überreste eines riesigen '''Dreschers''' - viel größer als alles, was man in [[Dunkelküste]] zu finden erwartet hätte – liegen gestrandet an der Küste des [[Nebelrand]]es. Wo immer die Kreatur auch hergekommen sein mag, es scheint nicht so, als sei sie in Dunkelküste heimisch. Wie es diese Kreatur hierher verschlagen hat, ist nicht zu sagen - die Murlocs, die sich jetzt an dem Gerippe gütlich tun, sehen viel zu schwach aus, als hätten sie, selbst in großer Anzahl, die Bestie erlegen können.\r\n==Persönlichkeiten==\r\n* [[Alter Serra'kis]]\r\n* [[Isha Awak]]",},
			["Dritte Flotte von Kul Tiras"] = { content = "Die [[Dritte Flotte von Kul Tiras]] wird auch die Verlorene Flotte genannt. Vor vielen Jahren während des letzten großen Krieges wurde die dritte Flotte von [[Kul Tiras]] vor der Küste des [[Sumpfland]]es, von [[Roter Drachenschwarm|Roten Drachen]] verbrannt und versenkt. Großdrachen, die von [[Orcs]] beherrscht wurden. Die Besatzungen hatten keine Chance gegen das Drachenfeuer und ihre Flotte ging vor der Küste brennend unter. Lord Admiral [[Daelin Prachtmeer]] verlor in dieser Tragödie damals seinen ältesten Sohn und jeden sonst an Bord jener sechs großen Schiffe als die [[Drachen]] über sie herfielen. Von den mächtigen Fahrzeugen waren nur Holzsplitter und einige wenige zerrissene Leichen übrig, um das ganze Ausmaß der Zerstörung zu zeigen. Es war Lord Admiral [[Daelin Prachtmeer|Prachtmeers]] Verdienst, dass er in seiner Entschlossenheit nicht stockte und sofort den Bau neuer Kriegsschiffe befahl, um die zerstörten zu ersetzen und damit den Krieg voranzutreiben. Doch die Schiffswracks der Verlorenen Flotte liegen noch heute nördlich des [[Hafen von Menethil]] im [[Sumpfland]] vor der Küste. \r\n==Schiffe==\r\nVon den Schiffen, die damals untergingen sind heute nur noch drei bekannt.\r\n* Die [[Fischadler]]\r\n* Die [[Herrin der Meere]]\r\n* Die [[Intrepid]]",},
			["Druide"] = { content = "#REDIRECT [[Druiden]]", redirect = "Druiden",},
			["Druiden"] = { content = "== Allgemeines==\r\nDruiden sind die Wächter der Welt und Herren der Natur, ausgestattet mit einer Vielzahl an verschiedenen Fähigkeiten. Sie sind machtvolle Heiler, fähig, Gifte zu heilen, und gefallene Kameraden auch mitten im Kampfgetümmel ins Leben zurückzurufen. Ebenso können sie jedoch auf die zerstörerischen Kräfte der Natur zurückgreifen und gleißende, energiegeladene Blitze auf ihre Feinde herabfahren lassen, Schwärme von gemeinen Insekten auf sie hetzen oder Wurzelgeflechte nach ihren Beinen greifen lassen. Aber Druiden sind auch Meister der Wildnis - sie können sich je nach Belieben in einen großen Bären, eine Wildkatze oder sogar einen Seelöwen verwandeln, um sich im Kampf und auf Reisen Vorteile zu verschaffen. Der Druide ist eine vielseitige Klasse mit vielen möglichen Spielweisen, fähig, in jeder Situation seinen Kameraden eine Hilfe zu sein.\r\n===Stärken, Fähigkeiten und innere Motivation===\r\n \r\nDurch ihre tiefgreifende Verbindung zum Leben und zur Natur können Druiden eine ungewöhnliche Vielzahl von Rollen übernehmen. Am besten bekannt ist der Druide wohl als Heiler, denn er ist berühmt dafür, Leben zu spenden, giftige Wunden zu heilen und Flüche zu entfernen. Die Heilung und der Schutz des Planeten sind eine der wichtigsten Aufgaben jedes Druiden. Aber den Druiden nur als Heiler zu sehen ist eine gefährliche Vereinfachung, die schon manchen unachtsamen Gegner ins Verderben geführt hat. Denn die Empathie eines Druiden gegenüber den Geschöpfen der Wildnis ermöglicht es ihm, seine Gestalt in die verschiedener Tiere zu verwandeln. Ein verwundeter Druide etwa, dessen magische Energie zur Neige geht, könnte plötzlich die Gestalt eines [[Bären]] annehmen, um weiteren Verletzungen besser widerstehen zu können. Oder er könnte sich in eine Großkatze verwandeln, sich an seinen Gegner anschleichen, ihn dann anspringen und mit einem rasenden Hagel krallenbewehrter Schläge eindecken. Selbst die tiefsten Ozeane vermag ein Druide zu erforschen, da er sich einfach in einen Meeresbewohner verwandeln und beliebig lange unter Wasser bleiben kann.\r\nBis Ende des [[Der Dritte Krieg|Dritten Krieges]] besuchten die Druiden regelmäßig den [[Smaragdgrünen Traum]], um die Gezeiten des Lebens auf [[Azeroth]] zu überwachen. Diese Besuche sind jedoch aufgrund der angeschlagenen Gesundheit Nordrassils schwieriger geworden. Druiden verfügen über ein tiefgreifendes Verständnis darüber, wie alle lebenden Kreaturen voneinander abhängig sind. Wenn dieses prekäre Gleichgewicht gestört wird, ist es die selbstgewählte Aufgabe der Druiden, die Balance wieder herzustellen. Dazu kann der Druide seine Verbindung zum [[Smaragdgrünen Traum]] einsetzen, um einen beruhigenden Einfluss auf Tiere auszuüben oder sie notfalls sogar eine Zeit lang in Winterschlaf zu versetzen. Doch ebenso gut, wie ein Druide Frieden und Behaglichkeit verbreiten kann, vermag er den [[Zorn der Natur]] selbst herbeizurufen. Fürchterliche Orkane und Gewitter gehorchen dem Ruf des Druiden, Dornen sprießen aus seiner Haut, um Angreifer zu verletzen, und selbst bislang harmlose Wurzeln wachsen plötzlich mit unglaublicher Geschwindigkeit aus dem Boden, um einen Feind zu fesseln.\r\n===Die Grenzen ihrer Fähigkeiten===\r\nAus offensichtlichen Gründen fühlt sich der Druide in der freien Wildbahn am wohlsten. Doch genauso unausweichlich verliert er einen Teil seiner Effektivität, wenn er zu lange von der Natur getrennt ist. Was nützt ein reinigender Regenschauer, wenn der Druide den Himmel nicht sehen kann? Wie sollen Wurzeln gegen einen Feind helfen, der auf einem hohen Turm steht? In solchen Fällen ist die Phantasie des Druiden gefragt, um neue Strategien zu finden, und seine Flexibilität, um sie umzusetzen.\r\n===Gleichgewicht===\r\nZu den Talenten des Gleichgewicht gehören u.a. die einschlingenden ''Würgerwurzeln'' bzw. ''Wucherwurzeln''. Diese Wurzeln packen nicht nur zu wie Stahl, sie schneiden auch genauso. Die Ranken wachsen verärgert, so als ob jedes Kraut in Azeroth Rache an denen sucht, die ihre fruchtbare Heimat zerstören wollen. Zu den Fähigkeiten des Gleichgewichts gehört auch das ''Sternenfeuer''. Der Himmel selbst antwortet dabei der Wut der Druiden mit seinem Echo und öffnet sich auf ihr Geheiß. \r\n===Wiederherstellung===\r\nDruiden verstehen die Wechselwirkung aller lebenden Dinge und wenn dieses empfindliche Gleichgewicht gestört wird, setzen die Druiden alles daran, die Balance wiederherzustellen. Die Ehrfurcht vor der Natur erlaubt den ihnen, ihren Verbündeten durch die ''Heilende Berührung'' oder ''Belebende Berührung'' wundersame Geschenke zu bescheren. Doch wie auch das Land, brauchen auch die Narben der Schlacht Zeit zum Heilen. Druiden die sich dem Pfad der Widerherstellung gewidmet haben, verfügen über die ''Gabe der Wildnis''. Sie fühlen dabei wie ihre Muskeln stärker, ihre Haut härter und ihre Sinne schärfer werden. Ebenso ist es ihnen möglich sie Cenarius' Segen durch sich und anderen das ''Mal der Wildnis'' zu geben, auf das der Waldgott auf sie herablächeln möge. \r\n===Flugform des Druiden===\r\nEin Druide ist niemals außerhalb seines Elements und so verfügen sie auch über ihre eigene spezielle Flugform. Die Grundform hiervon ist erlernbar, während die epische Variante das Absolvieren einer speziellen Quest erfordert. Die Flugformen von Allianz und Horde unterscheiden sich. Die normale Flugform benötigt Stufe 68 und die Fertigkeit Geübter Reiter (150). Sie erhöht das Flugtempo um 60% und kostet 7g beim Druidenlehrer. Die schnelle Flugform benötigt Stufe 70 und die Fertigkeit Gekonnter Reiter (300). Sie erhöht das Flugtempo um 280%, jedoch muss hierfür eine Druidenquest abgeschlossen werden. Hinweis: Gebt \"/reittierspezial\" (oder \"/mountspecial\") ein, um einen Überschlag in euren Flug einzubauen. \r\n===Katzengestalt===\r\nDruiden in der Katzengestalt erhören den ''Ruf der Wildnis''. Einem solchen Ruf zu folgen, bedeutet von Menschen gemachte Waffen zugunsten einer wilden Antwort aufzugeben. \r\n==Rassen==\r\n* [[Nachtelfen Druide]]\r\n* [[Tauren Druide]]\r\n==Gruppierungen==\r\n* [[Druide der Klaue]] ([[Klauendruide]])\r\n* [[Druide der Kralle]] ([[Krallendruide]])\r\n* [[Druide des Giftzahns]]\r\n* [[Druide des Geweihs]]\r\n* [[Druide der Wildnis]]\r\n==Organisationen==\r\n* [[Zirkel des Cenarius]]\r\n* [[Smaragdkreis]]",},
			["Druiden des Giftzahns"] = { content = "#REDIRECT [[Druide des Giftzahns]]", redirect = "Druide des Giftzahns",},
			["Druide der Klaue"] = { content = "Die geheimnisumwobenen Klauendruiden haben das Totem der Sturmkrähe angenommen. Ihre primäre Rolle in der Gesellschaft besteht im Sammeln von allgemeinen und geheimen Informationen. Sie besitzen die Fähigkeit, sich in Sturmkrähen zu verwandeln und können dann über das Schlachtfeld fliegen, um als Aufklärer zu fungieren und weiter entfernten Truppen Befehle zu übermitteln. Mit ihren magischen Fähigkeiten können sie sogar den Winden befehlen, gegen die Feinde von [[Kalimdor]] vorzugehen. \r\nUnmittelbar östlich von [[Auberdine]] liegen viele Mondkinhöhlen. In der [[Auberdine]] am nächsten gelegenen Höhle befindet sich ein Mondkinstein. Mondklaue, der Verteidiger des Steins, stellt sich nur, wenn Mondstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die man als Druide der Klaue benutzen muss.",},
			["Druide der Kralle"] = { content = "* Siehe auch [[Krallendruide]]\r\nDie uralten Krallendruiden haben sich das Totem des Bären zugelegt und nutzen die Kräfte ihres Totems, um ihre Gesellschaft vor allem von außen drohenden Gefahren zu beschützen. Die Wildheit dieser Bestien im Kampf ist legendär. \r\nWenn sie nicht gerade im Großen Schlaf sind, nehmen sie gern die Gestalt von Bären an und streifen einsam durch die Wildnis von [[Kalimdor]]. Werden sie gereizt, legen die Krallendruiden wilde Kraft und Ausdauer an den Tag. Ihre magischen Zauber verstärken auch Kampf-Fertigkeiten und Tapferkeit ihrer Verbündeten. Wenn er z.B. die Urkräfte der Natur und die ungezügelte Macht seines Totems anzapft, kann der Krallendruide im Kampf laut brüllen und so seine Verbündeten ermutigen, damit sie dem Feind erhöhten Schaden zufügen.",},
			["Druide der Wildnis"] = { content = "Nach der Invasion der brennenden Legion schlossen sich die Druidenorden zusammen, um ihre Kräfte zu bündeln und an Stärke zu gewinnen. Als Druiden der Wildnis vermischen sie die verschiedenen druidischen Aspekte und üben sich in allen Tierformen und Fähigkeiten. Seither sind sie noch vielseitiger einsetzbar und treten als Krieger, Zauberkundige oder Späher in Erscheinung. Die meisten Druiden bezeichnen sich heute als Druiden der Wildnis. Sie können sich u.a. in eine Katzengestalt verwandeln und niemand will der Kratzbaum eines Druiden werden.",},
			["Druide des Geweihs"] = { content = "Angeblich existiert neben den Druiden der Kralle, Klaue und des Giftzahns noch eine vierte Gruppierung: Die Druiden des Geweihs. Bisher wurde deren Existenz nie bestätigt. \r\nGerüchten zufolge sollen deren Anhänger versuchen den Aspekt des [[Malorne]] wiederherzustellen, um von seinen einstigen Naturmagien und Heilkräften Gebrauch zu machen. Diese Tatsache lässt vermuten, dass es sich bei den Druiden des Geweihs um mächtige Heil- und Zauberkundige handelt, die wohlmöglich die GEstalt eines Hirsches annehmen können.\r\nDer Fakt, dass derartige Druiden niemals öffentlich gesichtet wurden, spricht dafür, dass diese Gruppierung - sofern sie existiert - nur sehr wenige Anhänger hat, die wahre Meister um Versteckspiel sind.",},
			["Druide des Giftzahns"] = { content = "Die '''Druiden des Giftzahns''' haben sich von den übrigen [[Druide]]narten abgesplittert. Sie leben zurückgezogen in den [[Höhlen des Wehklagens]] im [[Brachland]] und verfolgen eigene Ziele. Ihr Wesen gilt als wahnsinnig, verdorben und korrupt.\r\nDie Druiden des Giftzahns gehörten sie einem Orden edler Druiden an, deren Plan es war, das [[Brachland]] zu heilen. Aber sie kamen jedoch vom rechten Weg ab und sind jetzt Diener der Besudelung, die das Land befallen hat. Sie sind eine Verirrung der Natur trachten jetzt danach, das Land ihren eigenen verderbten Träumen gleichzumachen. Sie haben vier Anführer. Diese halten sich tief in den [[Höhlen des Wehklagens]] verborgen und jeder besitzt einen Traumedelstein. \r\n==Persönlichkeiten==\r\nDie Anführer der Druiden des Giftzahns werden auch ''Giftzahnlords'' genannt. Zu ihnen gehören:\r\n* [[Lady Anacondra]]\r\n* [[Lord Kobrahn]]\r\n* [[Lord Pythas]]\r\n* [[Lord Serpentis]]\r\nAnsonsten ist nur ein Druide des Giftzahns namentlich bekannt: [[Boahn]], ein Nachtelf der selten in den [[Höhlen des Wehklagens]] zu finden ist.",},
			["Dryade"] = { content = "#REDIRECT [[Dryaden]]", redirect = "Dryaden",},
			["Dryaden"] = { content = "Die verzauberten Dryaden sind die Töchter des Halbgottes [[Cenarius]]. Diese verspielten, ausgelassenen Geschöpfe haben vage Ähnlichkeit mit [[Zentauren]] (ihren verfluchten Vettern), doch gleichen ihre Körper mehr denen der Waldfaune. Die Dryaden sind schnell und sicher und leben in Frieden mit allen Kindern des Waldes. Zwar verabscheuen sie unnötige Gewalt, verteidigen die Wälder von [[Kalimdor]] aber wenn es sein muss mit ihrem Leben. Die Töchter des Cenarius können die Fähigkeit erwerben, jede schadenzufügende Magie aufzuheben und das Wirken feindlicher Zauberer, deren Kräfte ein Verbrechen an der Natur sind, ungeschehen zu machen. Dryaden selbst sind gegen alle Formen von Magie immun. Hierbei handelt es sich um eine natürliche Fähigkeit, die nicht auf Mana-Vorräte angewiesen ist und mit der Zeit auch nicht nachlässt.",},
			["Dröhnkiste"] = { content = "Eine [[Dröhnkiste]] ist ein Meisterwerk [[Gnome|gnomischer]] [[Ingenieur]]skunst. Sie ermöglicht es Geräusche über einige Entfernung zu übermitteln. Als kleine tragbare Taschen [[Dröhnkiste]] ist sie leicht am Gürtel tragbar, so das man jederzeit erreichbar ist. Die Reichweite ist allerdings begrenzt und es kommt von Zeit zu Zeit schonmal zu Störungen. Als die [[Exodar]] in unsere Dimension eintrat, kam es zum Beispiel zu massiven Störungen. Weiterhin stellen Dimensionsübergreifende Verbindungen immernoch ein Problem dar. So das man von [[Azeroth]] jemanden in der [[Scherbenwelt]] nur schwer erreichen kann.\r\n==Geschichte==\r\nDer Erfinder der ersten Prototypen der Dröhnkiste ist [[Hexknall Kurbeldreh]] in [[Auberdine]], der ebenfalls an propellerbetriebenen explodierenden Entenattrappen forscht. Er erfand als erstes diese kleine Kästchen mit Hebeln daran, über die man mit Leuten sprechen kann, die weit weg sind. Sein einziges Problem ist, dass sie ständig gewartet werden müssen. Jede hat ein anderes Problem, aber er hat sich etwas ziemlich Schlaues ausgedacht und alle in der Nähe von Kreaturen platziert, die über die passenden Teile verfügen, um die jeweilige Maschine zu reparieren.\r\n===Dröhnkiste 323===\r\nDröhnkiste 323 steht nördlich von [[Auberdine]] und gibt statische Geräusche von sich, wenn Hexknall zu sprechen beginnt. Man benötigt für ihre Reparatur die Fangzähne von Mondpirschern.\r\n===Dröhnkiste 411===\r\nDröhnkiste 411 befindet sich nördlich von [[Auberdine]], am Strand. Aus dem Inneren der Maschine ist eine leise Stimme zu hören. Es werden Drescheraugen von den Dunkelküstendreschern im tiefen Meer benötigt, um sie zu reparieren, die sich direkt vor der Küste befinden. \r\n===Dröhnkiste 525===\r\nDröhnkiste 525 steht südlich von [[Auberdine]] und benötigt die Skalps von ergrauten Distelbären für ihre Reparatur.\r\n===Dröhnkiste 827===\r\nDröhnkiste 827 steht südlich von [[Auberdine]] und hat den Geist aufgegeben. Es werden Kriecherbeine benötigt, um sie zu reparieren.",},
			["Dschungeltrolle"] = { content = "* '''Historische Hauptstadt''': [[Zul Gurub]]\r\n* '''Bekannte Stämme''': [[Blutskalpe]], [[Dunkelspeere]], [[Gurubashi]], [[Shatterspear]], [[Schädelspalter]], [[Anduri-Stamm]]\r\n===Charakter===\r\nDie hinterhältigen Dschungeltrolle sind berüchtigt für ihre Grausamkeit und ihre Verehrung dunkler Mysterien. Anders als die [[Dunkelspeere]] werden die meisten [[Trolle]] Außenseiter und sogar [[Trolle]] von anderen Stämmen auf Sichtweite angreifen. Das barbarische und abergläubische Volk ist erfüllt von einem verzehrenden Hass auf alle anderen Völker. Dschungeltrolle werden von Geburt an zu besonders listenreichen Jägern und Fallenstellern ausgebildet. In den Wirren der Dschungelgebiete von [[Schlingendorntal]] locken sie ihre Beute in ihre Fallen und schleudern Speere aus dem schattigen Gebüsch auf ihre vermeintlichen Feinde. Ihre [[Kopfjäger]] spüren selbst die gefährlichsten Bestien auf. Viele Dschungeltrolle haben keine Loyalität außer zu ihren eigenen Stämme, mit der Ausnahme des Dunkelspeer-Stammes, die mit der [[Horde]] verbündet sind. \r\n===Gebräuche===\r\nEinige hängen noch an ihrem Erbe von [[Kannibalismus]] und [[Voodoo]]. Die meisten [[Trolle]] scheinen [[Kannibalismus]] zu praktizieren. Mehrere spezifische Trollstämme wurden als Kannibalen bestätigt, einschließlich der [[Moosschinder]] und [[Blutfratzen]]-Stämme der [[Waldtrolle]]. Weiterhin praktizieren alle gegenwärtig bekannten Stämme von [[Eistrolle]]n Kannibalismus. [[Sandtrolle]], [[Waldtrolle]] und Dschungeltrolle sind ebenso häufig Kannibalen, obwohl nicht immer. Sogar die mysteriösen [[Dunkeltrolle]] sollen zum größten Teil Kannibalen sein. Doch gibt es mehrere beachtenswerte Ausnahmen. Zum Beispiel verschlingen die [[Stamm der Zandalar|Zandalar]] und [[Bruchhauer]]-Stämme kein Trollfleisch. Auch der Dunkelspeer-Stamm war kannibalisch bis er sich mit der [[Horde]] zusammenschloss, woraufhin die Dunkelspeere den Kannibalismus offiziell aufgaben. \r\nNicht alle Trolle praktizieren [[Voodoo]], aber es ist sicherlich mindesten so weit verbreitet wie Kannibalismus. Wenig ist über das Entstehen von [[Voodoo]] unter den Trollen bekannt, da die meisten Stämme, die solches Wissen besitzen nicht willens sind, es Außenseitern mitzuteilen. Doch mit der jüngsten Ankunft der [[Trolle der Zandalar]] auf der [[Insel Yojamba]] , spekulieren mehrere beachtenswerte Forscher, dass [[Voodoo]] von den Zandalari ausgehen kann.\r\n===Hautfarbe===\r\nDie Körper der Dschungeltrolle sind von einem kurzen, weichen Fell bedeckt, das sie violett oder grau erscheinen lässt. Ihre moosähnliche Hautfarbe reicht von hellgrün zu blau und purpur. Die Hautfarbe der Dschungel- und [[Waldtrolle]] ist typisch grün während die Haut der Küstentrolle gewöhnlich blau oder bleich ist. \r\n===Körperbau===\r\nTrolle sind groß, schlaksig und muskulös. Sie sind durchschnittlich sieben Fuß hoch und wiegen 100 kg, außer zwei Stämmen, die Drakkari und die Zandalari, die dazu neigen etwas größer zu sein als ihre Verwandten. Wie bei anderen Rassen auch, gibt es ebenso verstreute Trolle, die die normale Größe weit übertreffen. Sie haben elfische und orkische Eigenschaften mit ihren grimmigen Hauern und langen Ohren. Ihre langen Arme, starken Beine und schnelle Reflexe sind perfekt für die Jagd. Dschungeltrolle sind auch ungewöhnlich gewandt im Vergleich mit anderen Trollen.\r\n===Regeneration===\r\nTrolle können verlorene Gliedmaßen regenerieren und schwere physische Verletzungen schneller heilen, was sie zu beachtlichen Gegnern auf dem Schlachtfeld macht.\r\n===Sprache===\r\nTrolle haben eine charakteristische Art zu sprechen. Worte wie \"yo\" (allgemeiner Gruß) und \"maan\" (man) sind allgemeine Ausdrücke. Sie sprechen mit variierten Jamaikanischen und Kubanischen-Klang Akzenten, obwohl das Kubanische unter Waldtrollen dominanter zu sein scheint.\r\n===Stamm===\r\nTrolle sind sehr isolierte Wesen. Die meisten Trolle, ausgenommen einige wenige Stämme sowie die [[Dunkelspeere]], sprechen nicht einmal eine gemeinsame Sprache. Wilde Dschungeltrolle und Küstentrolle sind eher aggressiv und feindlich gegenüber Trollen von anderen Stämme. Wenn sie jedoch einen Stammesgeist entwickeln, sind sie unschlagbar. Das Zentrum des Stammesgeistes ist der Stammes[[schamane]] oder beste Jäger.\r\n===Verbreitung===\r\nUnzivilisierte Trolle leben auf allen Hauptkontinenten, aber die Mehrheit der Trolle mag es im Süden zu leben. Der Dschungel nahe [[Beutebucht]] im Gebiet von [[Azeroth]] ist gefüllt mit blutdurstigen Dschungeltrollen. Es gibt Legenden, die die Möglichkeit vermuten, dass die ersten [[Nachtelfen]] wegbereitende Waldtrolle aus dem Norden waren, die an den Ufern des [[Brunnen der Ewigkeit|Brunnens der Ewigkeit]] siedelten.\r\n==Geschichte==\r\nWährend die [[Waldtrolle]] sich in [[Lordaeron]] ausbreiteten, etablierten die Dschungeltrolle ihre Herrschaft über die südöstlichen Dschungel des ursprünglichen [[Kalimdor]]. Das Imperium der Dschungeltrolle benannte sich nach ihrem mächtigsten Stamm: [[Gurubashi]]. In der heutigen Zeit kann sich das Wort Gurubashi entweder auf das alte Imperium beziehen, und damit auf die Dschungeltrolle als Ganzes, oder auch nur den Stamm der Gurubashi meinen. Die Imperien der Gurubashi und [[Amani]] führten gemeinsam Krieg gegen die unbarmherzigen Aqir, bis das Reich der Insekten in zwei Teile zerbrach, aber die Trolle konnten niemals einen endgültigen Sieg erringen. Nach der Großen Teilung breiteten sich Hunger und Gewalt unter den Dschungeltrollen aus, und sie flehten ihre Götter um Hilfe an. Ein Gott erhörte sie: [[Hakkar]] der Seelenschinder. Er verlieh den Dschungeltrollen große Macht, verlangte aber im Gegenzug, dass in seinem Namen Trolle geopfert werden. Als sein Blutdurst wuchs, verlangte er von seinen Priestern, dass sie ihn körperlich in die Welt von Azeroth bringen sollten, damit der sich seine Opfer selbst suchen konnte. Die meisten Hakkari waren entsetzt von dieser Idee, aber die Atal'ai, eine kleine extremistische Fraktion der Hakkari, waren bereit, Hakkars Wünsche zu erfüllen. Bevor die Atal’ai aber das Beschwörungsritual vollziehen konnten, erhoben sich die Hakkari und die anderen Dschungeltrolle in einer offenen Revolte. Selbst die Zandalar schlossen sich dem Kampf gegen Hakkar an, dessen Avatar schließlich zerstört wurde. Die Atal'ai wurden aus dem Dschungel vertrieben und fast bis zur Auslöschung gejagt. Einer kleinen Gruppe gelang es, in die [[Sümpfe des Elends]] zu fliehen und dort einen großen Tempel für ihren Gott zu errichten: den [[Versunkener Tempel|Tempel von Atal'Hakkar]].\r\nDie Hakkari wurden wegen der grausamen Dinge, die sie im Namen Hakkars getan hatten, ebenfalls vertrieben oder getötet. Verbittert und verzweifelt schlossen sie sich den Atal'ai in den Sümpfen an und versuchten gemeinsam, den blutdurstigen Gott nach Azeroth zu rufen. Der grüne [[Drachen]]aspekt, [[Ysera]] die Träumerin, erfuhr von den Plänen der Trolle und zerschmetterte den Tempel, der in den Sümpfen versank. Bis zum heutigen Tag werden die Ruinen des Tempels von mächtigen [[Grüner Drachenschwarm|grünen Drachen]] bewacht. Trotzdem gibt es unter den Trollen eine Prophezeiung, dass Hakkar eines Tages wiedergeboren wird. \r\nDie übrigen Trolle des Imperiums der Gurubashi gingen getrennte Wege. Die verstreuten Stämme beanspruchten eigene Gebiete in den weiten Dschungeln des [[Schlingendorntal]]s und begannen, untereinander zu kämpfen. Der Stamm der Dunkelspeer verließ den Kontinent gänzlich und ließ sich auf einer entfernten Wüsteninselgruppe nieder, wo sie lebten, bis sie sich der [[Horde]] im Dritten Krieg anschlossen. Heute leben die Dunkelspeer entlang der südöstlichen Küste von [[Durotar]].",},
			["Dunkeleisen"] = { content = "Dunkeleisen ist ein von der Macht der [[Alten Götter]] besudeltes Metall, dass sich nur in enormen Tiefen unter der Erde findet. Die [[Dunkeleisenzwerge]] haben ihren Namen von diesem Metall erhalten, welches sie letztenendes gegen ihre Vettern hetzte. Dunkeleisen kann nur in ihren Schmieden verarbeitet werden. Es erinnert von der Farbe eher an Kohle als an Metall. Das Metall leitet [[Magie]], ist jedoch auch sehr anfällig gegen zu starke Zauber.",},
			["Dunkeleisenklan"] = { content = "#REDIRECT [[Dunkeleisenzwerge]]", redirect = "Dunkeleisenzwerge",},
			["Dunkeleisenzwerg"] = { content = "#REDIRECT [[Dunkeleisenzwerge]]", redirect = "Dunkeleisenzwerge",},
			["Dunkeleisenzwerge"] = { content = "== Geschichte==\r\n===Das Erbe der Alten Götter===\r\nDie [[Titanen]] hatten die Zitadellen der [[Alte Götter|Alten Götter]] zerstört und ehemaligen Herrscher der Welt in das Innere der Erde verbannt, nun war es ein leichtes, die verbliebenen [[Elementare|Elemental-Lords]] zu zerschlagen und diese in eine weit entlegene Dimension zu sperren. Aus der Erde schufen die [[Titanen]] die [[Irdene]]n, welche Ihnen treue Dienste leisteten, die Welt nach Ihren Wünschen zu gestalten. Und als deren Dienst vollbracht war, legten sie sich in einen Schlaf der Jahrtausende währen sollte. Schließlich, lange nachdem der [[Brunnen der Ewigkeit]] zerstört und [[Kalimdor]] geteilt war, erwachten die [[Irdene]]n [[Uldaman]] aus Ihrem Schlummer als das [[Volk]] der [[Zwerge]]. Sie bereisten die Lande und schufen sich in einem mächtigen Gebirge Ihr Heim, das sie [[Eisenschmiede|Eisenschmiede]] nannten und viele Hunderte von Jahren gruben sie in den Bergen, fleißig und arbeitsam, wie es die [[Titanen]] sie gelehrt hatten. Mächtige Könige saßen auf dem Thron der aus dem Fels gehauenen Hallen von [[Eisenschmiede]], und immer tiefer gruben die [[Zwerge]] in den Berg, Kupfer, Silber, Zinn, Gold und andere wertvolle Erze fördernd, aus denen sie die prachtvollsten Waffen und Rüstungen der Welt schmiedeten. Die [[Zwerge]] waren und sind ein ehrgeiziges [[Volk]], und die Stollen und Schächte Ihrer Erzminen lockten sie Jahr für Jahr, tiefer und tiefer...\r\nUnd es war zu der Zeit, das der junge König [[Modimus Ambossar]] auf seinem Thron sass und das zwei große Klans unter seinem Namen vereint waren — der Klan der [[Bronzebart]]s unter Thane [[Madoran Bronzebart]], ein königsnaher und treuer Vasall König Modimus´und der [[Wildhammer_Klan|Klan]] von Thane Khardros [[Wildhammer_Klan|Wildhammer]], welcher die Ausläufer des Gebirges patroullierte und der Sicherheit des Reiches einen großen Dienst erwies — da stießen in [[Uldaman]], der Alten Stadt des [[Zwerge]]nreiches, die Minenarbeiter auf eine seltsame Entdeckung: Ein Erz, wie sie es noch nie gesehen hatten, trat unter dem grauen Fels zu Tage, in Form einer langen Vene zog es sich durch den Fels. Finster und matt war es und dennoch erkannten die Minenvorarbeiter schnell den Wert dieses Materials, denn sie ließen es abbauen und einschmelzen und siehe da: die Konsistenz des \"Dunklen Erzes\", wie sie es tauften, war vorzüglich. Es war leicht und hart und in ihm ruhte eine uralte Macht: Zu tief hatten die [[Zwerge]] in Ihrer Gier gegraben, und das Erz, das sie schürften, war verflucht von der Macht der [[Alte Götter|Alten Götter]], welche, durch die Barriere Ihres Gefängnisses hindurch gesickert, Fels und Erz in weitem Umkreis verseucht hatte. Doch davon ahnten die [[Zwerge]] nichts. Es hätte sich schnell herum gesprochen, welch großartige Entdeckung die Minenarbeiter gemacht hatten — doch die Minenvorarbeiter nahmen den Arbeitern ein Schweigegelübde ab: Sie sollten schwören das kein Wort von Ihrer Entdeckung über Ihre Lippen kommen würde. Das [[Dunkeleisen]] sollte ihnen später ihren Namen geben.\r\nTief unter der alten Stadt, welche die [[Titanen]] hinterlassen hatten, hinter dem Rücken des [[Zwerge|Zwergenvolkes]], ohne das Wissen von König [[Modimus Ambossar]], bauten sie das dunkle Erz ab, schmolzen es ein und schmiedeten daraus Waffen und Rüstungen, und mehr und mehr stellte sich heraus, das sie es hier mit etwas ganz Besonderem zu tun hatten.\r\nAnfangs glaubten sie an ein Wunder, doch einer der Minenvorarbeiter, ein [[Zwerg]] namens Thaurissan, erkannte die Gunst der Stunde. Er war einer der ersten gewesen, der die Macht, welche diesem seltsamen, fremden Erz innewohnte, gespürt hatte. Diese Macht befähigte ihn Dinge zu tun, die kein [[Zwerge|Zwerg]] vor ihm jemals getan hatte. In Berührung mit diesem Erz war er einer seltsamen, fremdartigen Beeinflussung ausgesetzt und Zauberei — wie sie in alten Sagen einst den [[Kaldorei]] vorbehalten war — floss durch seinen Körper. Er gründete einen geheimen Bund der [[Zwerge]] und stachelte die Minenarbeiter auf gegen König Modimus und die beiden anderen Klans. Indem er den Minenarbeitern einredete, sie würden hier für den Wohlstand der [[Wildhammer_Klan|Wildhammers]], der [[Bronzebart]]s und des Königs schuften, gewann er Ihre Gunst. Er versprach Ihnen selbst Wohlstand und Reichtum durch die aus dem dunklen Erz gewonnenen Waffen und Rüstungen, die er nicht an den König weitergab, sondern seine Männer damit rüstete. Schließlich ernannte er sich selbst zum Thane des Dunkeleisen-Klan. Die Dekaden flogen dahin und es kam der Zeitpunkt, an dem der Bund Thaurissans nicht mehr geheim gehalten werden konnte. Schließlich offenbarte er sich dem König, welcher — mittlerweile in die Jahre gekommen — dem Wunsch Thaurissans nachkam, das der Klan der Dunkeleisens offiziell anerkannt wurde und gleiche Rechte genoss wie der [[Wildhammer_Klan|Klan der Wildhammers]] oder [[Bronzebart]]s.\r\nDoch dies war nur der Anfang einer Tragödie, wie sie schlimmere Ausmaße nirgends anderswo hätte annehmen könnten. Denn das Erbe der [[Alte Götter|Alten Götter]] hatte Fuß gefasst in dem Bund, der Thaurissan mit seinen [[Zwerge|Zwergen]] geschlossen hatte. Und je tiefer sie gruben, desto gieriger wurden sie nach den dunklen Erz. Denn sie schmückten sich mit Geschmeide, Rüstungen und Waffen, geschmiedet aus dem Erz, das den Fluch der [[Alte Götter|Alten Götter]] trug. Und so nahm der Fluch seinen Lauf, das die Gier der [[Zwerge]] den Anfang vom Ende der Welt besiegeln würde. Die [[Titanen]] waren sich der langanhaltenden Macht der [[Alte Götter|Alten Götter]] nicht bewusst gewesen. Über mehr als hunderttausend Jahre hatten die gefangenen [[Alte Götter|Alten Götter]] warten müssen. Endlich hatten sie die von den [[Titanen]] erschaffenen Wesen in Ihren Bann ziehen können. Die Alten Götter hatten zwar verloren, doch Ihr Ruf wurde erhört, als die [[Titanen]] längst hinfort waren, um sich mit der Erschaffung anderer Welten zu befassen.\r\n===Der [[Krieg der drei Hämmer]]===\r\nEs folgte des Ableben des König [[Modimus Ambossar]] und der Streit um sein Erbe. Der [[Krieg der drei Hämmer]] war ausgebrochen, in dessen Folge die Dunkeleisenzwerge aus dem Volk der [[Zwerge]] verbannt wurden. Doch Thaurissan ließ sich nicht einschüchtern. Er führte seinen Klan nach Süden in das [[Rotkammgebirge]], wo er seinem verstossenen Volk eine mächtige, nach ihm benannte Stadt erbauen ließ. Trotz der Jahre, in denen der Dunkeleisen-Klan sich vermehrte und prosperierte, verliess Thane Thaurissan nicht der Neid auf die beiden anderen großen Klans und den Anspruch auf den Königsthron, den nun Madoran vom Klan der [[Bronzebart]]s bekleidete.\r\nNach Dekaden des Friedens war es soweit: Thaurissan und seine Frau Modgud hatten ein mächtiges Heer einberufen, das die Armeen der [[Wildhammer_Klan|Wildhammers]] und [[Bronzebart]]s, welche bei [[Eisenschmiede]] und [[Grim Batol]] stationiert waren, in einem überraschenden Zweifronten-Krieg zerschlagen sollte. Über Nacht brachen die Dunkeleisenzwerge auf, nachdem sie Ihre todbringenden Schwüre mit ihrem eigenen Blut geleistet hatten. Und in einer kalten Winternacht war es dann soweit. Die Aussenposten bei [[Grim Batol]] und [[Eisenschmiede]] fielen in einer einzigen Blitzattacke, und das Heer der Dunkeleisenzwerge wälzte sich vorwärts, der Vernichtung des Feindes entgegen. Bei Morgengrauen standen sich Thaurissan mit einigen zehntausend Dunkeleisenzwerge und König Madoran mit seinen Getreuen vor den Toren von [[Eisenschmiede]] gegenüber. Während der dreiwöchigen Schlacht, die um [[Eisenschmiede]] tobte, war der Feldherr der Dunkeleisenzwerge im Unklaren darüber, das seine Frau Modgud eine bittere Niederlage bei [[Grim Batol]] erfahren hatte, welche sie selbst mit dem Leben bezahlen musste. Der Kampf um [[Eisenschmiede]] wendete sich zu Gunsten der Dunkeleisenzwerge, und die Reihen um König Madoran lichteten sich.\r\nAber schließlich auch wurde, nachdem der Schnee um [[Eisenschmiede]] meilenweit rot vom Blut der gefallenen [[Zwerge]] gefärbt worden war, in dieser Schlacht von den Dunkeleisenzwerge zum Rückzug geblasen. Späher Thaurissans hatten die Vorboten der [[Wildhammer_Klan|Wildhammer]]s aus [[Grim Batol]] am Horizont entdeckt, die dem König zur Hilfe eilen wollten. Dies war der Augenblick, an dem Thane Thaurissan, Anführer der Dunkeleisenzwerge, seine Niederlage eingestehen musste. Mit einigen hunderten [[Krieger]]n floh er vor der anrückenden Übermacht zurück in seine von ihm geschaffene Heimat, dem [[Rotkammgebirge]]. Dort verschanzte er sich hinter den Toren seiner Stadt vor den Armeen seiner Feinde, welche sich auf eine lange Belagerung einrichteten. Nocheinmals wollten sie die Dunkeleisenzwerge nicht davon kommen lassen. Diesmal sollte das endgültige Schicksal Ihrer einstigen Vettern besiegelt werden. Doch Thane Thaurissan würde es ihnen nicht einfach machen. Er hatte noch ein Ass im Ärmel...\r\n===Weiterführende geschichtliche Links===\r\n* [[Krieg der drei Hämmer]]\r\n* [[Die Schlacht von Grim Batol]]\r\n* [[Versklavung der Dunkeleisenzwerge]]\r\n==Zeitrechnung==\r\n* —147,000 Eine mysteriöse Rasse übermächtiger Wesen, von Ihren Schöpfungen die \"[[Titanen]]\" genannt, bekämpfen die Alten Götter, zerstören deren Zitadellen und sperren sie ins Innere der Erde. Die [[Titanen]] zerschlagen die Elemental-Lords, welche im Dienste der Alten Götter die urzeitliche Welt kontrollierten, und verbannen sie in eine andere Dimension. Sie erschaffen die Earthen (Irdenen), welche Ihnen bei der Erschaffung der Welt behilflich sind. Nach der Schöpfung\r\n* —65,000 Azeroth ist ein einziger Kontinent namens Kalimdor. Im Zentrum der Landmasse erschaffen die [[Titanen]] den Brunnen der Ewigkeit als Energiequelle. Die Irdenen werden nach vollbrachter Schöpfung in einen Iahrtausende währenden Schlaf geschickt.\r\n* —64,001 Bevor die [[Titanen]] Azeroth verlassen, übergeben sie die Vollmacht über Azeroth den Drachen,welche über das Werk der [[Titanen]] wachen sollen.\r\n* —14,000 Eine Rasse von nomadischen Humanoiden erreicht den Brunnen der Ewigkeit. Beeinflusst von dessen Macht, werden sie stark, weise und unsterblich — die Kaldorei erschaffen die erste Zivilisation. Unwissend, entsteht durch ihre Transformation im Zusammenhang mit dem Brunnen der Ewigkeit die Magie in Azeroth.\r\n* —10,250 Die [[Hochgeborene]]n der [[Kaldorei]] ziehen durch ihren masslosen Gebrauch von [[Magie]] die Aufmerksamkeit der [[Brennende Legion|Brennenden Legion]] auf sich.\r\n* —9,999 Im Krieg gegen [[Sargeras]] und die Brennende Legion wird durch [[Illidan]] Sturmgrim der [[Brunnen der Ewigkeit]] zerstört. Der Kontinent [[Kalimdor]] wird geteilt. Wo einst der [[Brunnen der Ewigkeit]] existierte, ensteht der [[Mahlstrom]], ein mächtiger Sog elementarer Energie.\r\n* —2,500 Aus den Tiefen der Erde erwachen die [[Irdene]]n in der von den [[Titanen]] erbauten Stadt [[Uldaman]] aus ihrem Schlaf. Sie begründen die Zivilisation der [[Zwerge]] und nennen sie [[Khaz Modan]].\r\n* —2,210 Auf ihrer Reise nach Norden erreichen die [[Zwerge]] den [[Loch Modan]] und gründen die Siedlung [[Thelsamar]].\r\n* —2,150 Die [[Zwerge]] bauen Straßen und beginnen, mit den [[Nachtelfen]] und den [[Menschen]] des Reiches [[Arathor]] Handel zu betreiben.\r\n* —1,930 Die [[Zwerge]] kämpfen gegen die [[Trolle]] und erschließen das Reich [[Dun Morogh]]. Sie gründen die Siedlung [[Kharanos]]. Der Bau von [[Eisenschmiede]] beginnt.\r\n* —1,750 Der Bau von [[Eisenschmiede]] ist abgeschlossen.\r\n* —1,630 Die [[Zwerge]] errichten die Feste [[Dun Modr]], nördlich des [[Sumpfland]]es\r\n* —1,570 Die [[Zwerge]] errichten die Feste [[Grim Batol]].\r\n* —1,350 [[Eisenschmiede]] wird Metropole der [[Zwerge]]. Die Klans aus dem ganzen Reich werden einberufen, um den König der [[Zwerge]] zu bestimmen. In den Machtbestrebungen der Klans, den König aus Ihren Reihen zu stellen, werden viele kleinere Klans einverleibt. Es bilden sich drei große Klans: Die [[Ambossar Klan|Ambossar]]s, die [[Bronzebart]]s und die [[Wildhammer]]s.\r\n* —1,320 Gombrim [[Ambossar Klan|Ambossar]] besteigt als erster König aller [[Zwerge]] den Thron von [[Eisenschmiede]].\r\n* —1,250 Die [[Zwerge]] errichten die Feste [[Dun Modr]], nördlich des [[Sumpfland]]es.\r\n* —1,020 Die [[Zwerge]] des [[Wildhammer]]-Klans errichten die Zitadelle [[Grim Batol]].\r\n* —380 Die Minenarbeiter in den Stollen unter [[Uldaman]] entdecken das \"Dunkle Erz\". Dieses wird unter höchster Geheimhaltung abgebaut.\r\n* —280 Der Dunkeleisen-Klan begründet sich.\r\n* —235 Der Dunkeleisen-Klan offenbahrt sich König Ambossar und verlangt Anerkennung und gleiche Ansprüche auf den Thron.\r\n* —232 König [[Modimus Ambossar]] stirbt. Streiterien um die Thronfolge brechen unter den drei Klans aus.\r\n* —230 Der [[Krieg der drei Hämmer]] bricht aus.\r\n* —225 Die Dunkeleisenzwerge werden offiziell aus dem Volk der [[Zwerge]] verbannt.\r\n* —220 Thane Thaurissan führt die Dunkeleisenzwerge ins [[Rotkammgebirge]]. Die Stadt Thaurissan wird erbaut.\r\n* —216 Der Klan der [[Wildhammer]]s unterliegt in der Schlacht dem Klan der [[Bronzebart]]s. Thane [[Madoran Bronzebart]] wird neuer König von [[Eisenschmiede]].\r\n* —208 [[Thaurissan]] sinnt auf Rache und führt einen Zweifrontenkrieg gegen [[Eisenschmiede]] und [[Grim Batol]]. Thaurissans Frau, die Hexerin Modgud, stirbt bei der Schlacht um [[Grim Batol]]. Thaurissans Armee wird vor den Toren von [[Eisenschmiede]] zum Rückzug gezwungen.\r\n* —202 König [[Madoran Bronzebart]] vereint die [[Wildhammer]]s und die [[Bronzebart]]s und belagert mit seiner Armee die Dunkeleisenzwerge vor den Toren Ihrer Stadt. Thane Thaurissan ruft [[Ragnaros]], die Stadt wird zerstört, die Dunkeleisenzwerge in die Versklavung geführt.\r\n* —190 König Madoran bekämpft die Dunkeleisenzwerge bei [[Uldaman]]. Diese jedoch stehen eine lange Belagerung durch. König Madoran zieht sich nach [[Eisenschmiede]] zurück.\r\n* —125 Die Dunkeleisenzwerge erobern die Feste [[Dun Modr]] unter der Führung von Balgeras dem Verderbten.\r\n* —82 Der Sohn König Madorans, Magni [[Bronzebart]], beerbt den Thron von [[Eisenschmiede]].\r\n* —1 [[Medivh]] öffnet das [[Dunkle Portal]].\r\n* 1 Ausbruch des [[Der Erste Krieg|ersten großen Krieges]].\r\n* 4 Ende des [[Der Erste Krieg|ersten großen Krieges]]\r\n* 6 Ausbruch des zweiten großen Krieges. Das dunkle Portal wird zerstört. Ende des zweiten großen Krieges.\r\n* 20 Ausbruch des [[Der Dritte Krieg|dritten großen Krieges]]. Angriff der [[Brennende Legion|Brennenden Legion]]. Ende des dritten großen Krieges.\r\n* 24 Die [[Zwerge]] erwecken bei Ausgrabungen die [[Troggs]] und stoßen auf weitere Anzeichen darauf, die Nachfahren der [[Titanen]] zu sein. Weitere Ausgrabungen folgen.\r\n* 25 Gegenwart: Die Dunkeleisenzwerge erfahren von den Ausgrabungsergebnissen Ihrer Vettern. Im Bestreben, mehr darüber zu erfahren, werden verdeckte Spione ausgeschickt.\r\n==Sprache==\r\n(written by Calâthomir)\r\nDie Entstehung der Sprache begann in einem Dialekt des [[Zwerge|Zwergischen]], den die Minenarbeiter über Jahrhunderte hinweg entwickelten. Wochen- bis monatelange unter Tage, von ihrem heimischen Öfen weit entfernt, setzten sich immer mehr sprachliche Wendungen bei den Kumpels durch, die sich stark auf ihre Arbeit bezogen. Als dann die ersten Funde dieses geheimnisvollen, dunklen Erzes mit einem Raunen durch die tiefsten Stollen ging und die Vorarbeiter die Verbreitung dieser Neuigkeit untersagten, sprach man unter Flüstern von dem ghim-lodir ghar, dem \"Schwarzen Gold\". Thaurissan, der die unglaublichen magischen Fähigkeiten dieses Erzes erkannte, scharrte die Minenarbeiter mittels verschwörerischer Reden hinter sich und liess das Dunkleeisenerz jahrelang unter strengster Geheimhaltung vor den Herrschern von [[Eisenschmiede]] abbauen und schmelzen. Gerade während dieser Zeitperiode veränderte sich der anfängliche Dialekt zu einer fast eigenständigen Sprache. Der Raubbau forderte von den Minenarbeitern sich in einer Kommunikationsform zu verständigen, ohne dass jene [[Zwerge]], die von den Vorgängen in den tiefen Stollen nichts wussten, Kenntnis von der Verschwörung erhielten. Nach und nach fanden sich eigenständige Wörter ein, deren Bedeutung nur den Eingeweihten des Bundes klar war. Als nun Thaurissan vor König Modimus [[Ambossar Klan|Ambossar]] trat und die Anerkennung der Dunkeleisenzwerge als eigenständigen Klan forderte, wurde auch deren Sprache von den Gelehrten des Zwergenreiches als \"Dark Iron\" anerkannt. Bis heute existiert diese eher als gesprochene Sprache, mehr ein Produkt der Geheimniskrämerei einer Gruppe von ärmlichen Minenarbeitern als eine jahrhundertelange Entwicklung in geschriebener Form.\r\n===Beispiele===\r\n* nibel = Feuer\r\n* tiora = Eisen\r\n* ryggr = Stein\r\n* soam = Fels\r\n* fryg = Berg\r\n* ghar = Gold\r\n* algash = Amboss\r\n* rune = Blut\r\n* gawnhi = Flamme\r\n* modus = Faust\r\n* grunholdd = Feuerberg\r\n* khaz-thaur = [[Schwarzfels]]\r\n* kharnos = Abgrund\r\n* imlut = [[Golem]]\r\n* ghael-baras = [[Steingolem]]\r\n* rok-whispar = [[Stahlgolem]]\r\n* dun-gar = Säure\r\n* gar-haras = Reinheit\r\n* dun-efrit = Blutberg\r\n'''Auszüge aus der Website der Blutberg-Dunkeleisenzwerge:'''",},
			["Dunkelhain"] = { content = "Dunkelhain liegt im Herzen des [[Dämmerwald]]s. Die Stadt bietet vereinzelt Gast- und Wohnhäuser, einem gemütlichen Stadtleben kann man aber nicht mehr nachgehen, auch wenn man hier ein wenig Schutz vor den in ganz [[Dämmerwald]] anzutreffenden übergroßen Gift[[spinnen]], Skeletten und anderen mystischen Monstern findet. Dennoch wird man zum Teil auch innerhalb der Stadtmauern auf Diebe und anderes Gesindel treffen. [[Sturmwind]] hat alle offiziell ernannten Wachen von ihren Posten hier abgezogen; damit sind sie sich selbst überlassen und die [[Menschen]] hier haben selbst mit Hilfe der [[Nachtwache]] einfach nicht genug Behüter, um die Sicherheit in der Stadt zu gewährleisten. Besonders auf den rund um Dunkelhain immer weiter anwachsenden Friedhöfen wird man auch auf unzählige Ghouls und andere Untote Geschöpfe treffen.\r\n==Personen==\r\n* '''Amtmann Daltry''' im Rathaus von Dunkelhain macht alle möglichen Aufzeichnungen. Er verwaltet das Stadtverzeichnis und ist ein wahrer Experte darin geworden, Handschriften zu identifizieren. \r\n* '''Behüter Backus''' patrouilliert meist auf der Nordstraße vor der Stadt. \r\n* '''Behüterin Sarah Ladimore''' ist die Tochter von Morgan Ladimore, kurz [[Mor'Ladim]]. Man dachte zwar, dass seine ganze Familie umgekommen sei, aber seine Tochter Sarah Ladimore lebt noch: Sie ist jetzt eine Behüterin. Die Umstände, unter denen ihr Vater zu Tode gekommen ist, haben sie immer sehr aufgewühlt. \r\n* '''Calor''' arbeitet für die Familie Treuwein. Die Selbstzufriedenheit der Wache hatte ihn seiner Illusionen beraubt und so schloss er sich Meister Treuwein an. Calor schwört, dass jemand - oder etwas - in den Gebäuden in Rabenflucht umgeht. Kürzlich kam Calor mit einer ganzen Reihe Köpfe von [[Worge|Wolfmenschen]] von den \"[[Worgs]] in den Wäldern\" in die Stadt zurück. \r\n* '''Elaine Treuwein''' möchte herausfinden, was in Rabenflucht umgeht. \r\n* '''Wachhauptmann Sorigal''' muss eine Kiste mit Kraftsteinen in die [[Burg Nethergarde]] in die [[Verwüstete Lande|verwüsteten Landen]] bringen. Die Kraftsteine werden ihre Macht nicht lange halten, daher kann er sie nicht mit der nächsten Karawane aufgeben. \r\n* '''Jonathan Treuwein''' ist der Haushaltsvorstand der Famile Treuwein. Sie jagen Dämonen, Untote und andere Monster. Er hat sich der Aufgabe verschrieben, das Böse und die Ketzerei zu vertreiben. Dank seiner Anstrengungen lebt das Volk von Dunkelhain in Sicherheit. \r\n* '''Kommandantin Althea Schwarzhaupt''' ist die Kommandantin der [[Nachtwache]] und hat geschworen, die Bürger von Dunkelhain zu beschützen. Außerdem beobachtet sie [[Stalvan Dunstmantel]] jetzt schon eine ganze Weile. \r\n* '''Küchenchef Grual''' befindet sich in der Taverne [[Zum roten Raben]] und macht ganz ausgezeichnete schwärzliche Krebsküchlein. Schwärzliche \"Krebs\"-Küchlein werden eigentlich aus Spinnenbeinen gemacht. Er weiß, das ist irgendwie eklig, aber die Küchlein schmecken lecker, ein bisschen scharf und eignen sich ganz ausgezeichnet zum Knabbern. Auch gewürzter Wolfskebab ist eine Spezialität des Hauses.\r\n* '''Lord Ello Schwarzhaupt''' ist der Bürgermeister von Dunkelhain. Wenn er seine [[Nachtwache]] jetzt nach [[Seenhain]] zu [[Magistrat Solomon]] zur Unterstützung schickt, dann würde diese Stadt vom Bösen überrannt werden, noch ehe die Wachen den Waldrand erreicht hätten. \r\n* '''Madame Eva''' befindet sich auf dem Dorfplatz von Dunkelhain. Letzte Nacht verspürte sie in ihrem Geist eine schreckliche Erschütterung. Sie wusste, dass sich ihre Enkelin Alyssa in großer Gefahr befand. Sie befragte die Karten und aus ihnen starrte sich die Fratze des Todes höhnisch an. Sie begab sich auf eine lange Reise durch eine dunkle Trance und schließlich gelang es ihr, einen Hinweis auf dieses schreckliche Geheimnis zu erhaschen. Ein Name erschloss sich ihr, der Name [[Stalvan Dunstmantel]].\r\n* '''Ratsherr Mühlenstein''' will, dass man ihm die Hand von [[Dextren Ward]] bringt. Er sagt, [[Sturmwind]] muss sich der Probleme der Leute aus dem [[Dämmerwald]] annehmen, oder sie werden sich von ihrer Tyrannei befreien. \r\n* '''Schankwart Smitts''' in der Taverne [[Zum roten Raben]] hat eine Flasche eines bestimmten Schnapses, und zwar Zombiesaft. Es ist stark genug, um die Toten zu erwecken und er kennt sich mit den örtlichen Lehren ziemlich gut aus. Wenn man ihm ein paar Faulblüten bringt, dann kann er einen Kessel Zombiesaft brauen. Er hat die Geschichten um [[Stalvan Dunstmantel]] jahrelang verfolgt. Als vor ein paar Jahren die Adligen, die hier zu Besuch waren, ermordet wurden, hat er Haggard bei seinen Nachforschungen begleitet. Er hat damals schlammverschmierten Seiten gefunden, aber es ist ihnen nie gelungen, die Handschrift mit diesem Verrückten in den Wäldern in Verbindung zu bringen.\r\n* '''Viktori Prism'Antras''' möchte nach einer Blaupause von Cogs einen Blick zu den Sternen werfen. Doch dazu braucht er einen Gegenstand mit reflektierender Oberfläche. Laut der Blaupause wird eine Linse oder etwas in der Art benötigt, doch die einzige Linse, die groß genug wäre, wird sehr schwierig zu beschaffen sein. Es ist das Monokel von Zzarc'Vul im südlichen Ogerhort des [[Dämmerwald]]s.",},
			["Dunkelküste"] = { content = "Die Dunkelküste ist ein Küstenstreifen im Nordwesten [[Kalimdor]]s. In dieser Region finden sich lange Sandstrände, die in einen dichten Wald übergehen. In der Dunkelküste sind meistens [[Nachtelfen]] anzutreffen, da das zentral gelegene Dorf [[Auberdine]] eine direkte Verbindung nach [[Teldrassil]] bietet. In den Wäldern finden sich unter anderem Geister, [[Mondpirscher]], [[Distelbären]] und [[Schreiter]]. An den Stränden trifft man auf [[Murlocs]] und anderes Meeresgetier, welches, wenn man sich zu weit aufs Meer hinauswagt, durchaus gefährlich werden kann. Am Anleger von [[Auberdine]] kann man Schiffe nach [[Teldrassil]] und zum [[Hafen von Menethil]] nehmen.\r\n'''Quelle:''' \r\n==Verderbnis==\r\nMan hat in Dunkelküste die ersten Anzeichen von Verderbnis entdeckt, jedoch noch nichts gefunden, was auf Ausbreitung hindeutet. Eine Erkrankung breitet sich hier aus und befällt Körper und Geist aller, die damit in Kontakt kommen. Die [[Distelbären]] wurden am schwersten von der Seuche getroffen. Die einst edlen Tiere sind jetzt ein Instrument der Zerstörung - tollwütig und rasend. Rund um Dunkelküste wimmelt es von krankem Wild. Es ist auch seltsam, dass sich [[Naga]] hier herumtreiben. Aber was noch seltsamer ist ist die Anwesenheit des [[Schattenhammerklan|Schattenhammerklans]].\r\n= Orte =\r\n* [[Auberdine]]\r\n* [[Hain der Uralten]]\r\n* [[Klippenquellfälle]]\r\n* [[Küste des Nebelrandes]]\r\n* [[Lager der Schwarzfelle]]\r\n* [[Meistergleve]]\r\n* [[Mondkinhöhlen]]\r\n* [[Ruinen von Ameth'Aran]]\r\n* [[Ruinen von Bashal'Aran]]\r\n* [[Ruinen von Mathystra]]\r\n* [[Turm von Althalaxx]]\r\n* [[Wirrbarts Ausgrabungsstätte]]\r\n* [[Zwielichtufer]]\r\n==Personen==\r\n* '''Feero Eisenhand''' - [[Delgren der Läuterer]] bei [[Maestras Posten]] in [[Eschental]] hat Feero gebeten, der [[Schildwache Sternenhauch]] in [[Auberdine]] Nachrichten und Nachschub zu bringen, aber es schmeckt ihm gar nicht, allein dorthin zu gehen. Im Wald sind gefährliche Feinde zugange und er möchte nicht riskieren, dass der Nachschub und die Informationen in die falschen Hände geraten. Wenn ein paar andere als Wachen mit ihm kämen, könnte er sofort gehen. Mit Schutz zweifelt er nicht daran, dass sie diese Dinge sicher nach [[Auberdine]] bringen können.\r\n* '''Kerlonian Schattenspiel''' - Kerlonian war auf dem Weg zu [[Maestras Posten]] in [[Eschental]], um sich mit [[Liladris Mondbach]] zu treffen, als er beschloss, kurz anzuhalten und ein kurzes Nickerchen zu machen. Seit er aus dem [[Smaragdgrüner Traum|Smaragdgrünen Traum]] aufgewacht ist, ist er ständig so müde. \r\n* '''Schildwache Aynasha''' - Schildwache Aynasha war mit einer wichtigen Nachricht auf dem Weg nach [[Auberdine]], als sie von dem [[Furbolg]] [[Marosh]] und seinen Fährtenlesern angegriffen wurde. Während des Angriffs wurde sie vergiftet, wodurch sie kaum noch stehen kann. Sie kann ein Gegengift herstellen, aber es wird eine Zeit dauern, bis es bereit ist.",},
			["Dunkelmeister Gandling"] = { content = "'''Dunkelmeister Gandling''' ist der Enboss in der [[Scholomance]]. Dieser [[Nekromant]] befindet sich dort in der Mitte des Arbeitszimmer des Direktors, welcher zum Unterricht ruft.\r\n==Kampf==\r\nGandling gehört eher zu den schwächeren Endbossen in den Instanzen dieses Stufenbereiches. Das einzige worauf man achten sollte ist der Fluch, der die Effekte von Heilzaubern verringert. Gandling hat allerdings noch eine andere Attacke die einen jeweiligen Spieler in einen der 6 Räume teleportiert, wo er gegen 3 sehr schwache Versionen von Untoden kämpfen muss, wodurch diese Attacke auch kein Problem sein sollte. \r\n* '''Arkane Geschosse''' - Schleudert magische Geschosse auf einen Feind und verursacht Arkanschaden \r\n* '''Fluch des Dunkelmeisters''' - Der Fluch des Dunkelmeisters verringert die Stärke eines Feindes um 50 und seine Ausdauer 1 Min. lang um 50. \r\n \r\n* '''Schattenportal''' - Das Schattenportal teleportiert einen Feind zu einem von 6 Orten innerhalb der Scholomance. \r\n* '''Schattenschild''' - Dieser Stärkungszauber umgibt den Zaubernden mit einem aus Schattenmagie gewobenen Schild. Der Schild hält 30 Sek. lang an, absorbiert bis zu 200 körperlichen oder magischen Schaden und fügt Nahkampfangreifern 10 Schaden zu.",},
			["Dunkelmond-Gewinnlose"] = { content = "Mit Hilfe der '''Gewinnlose des Dunkelmond-Jahrmarkts''' lassen die Betreiber von [[Dunkelmonds Jahrmarkt]] andere ihnen aushelfen und im Gegenzug können die Lose für besondere Preise eingelöst werden. Für den Anfang sollte man mit Chronos, Kerri Hicks, Ringling und Yebb Nabetand sprechen, um zu sehen wobei man am besten aushelfen kann. Sie wissen immer etwas, was zur Verbesserung oder Erweiterung ihrer Attraktionen gebraucht wird. Sollte man genug Lose haben, so spricht man mit Gelvas Rußgatter, er wird dann eine Liste zeigen aus der man unterschiedliche Preise wählen kann. \r\n'''Quellen'''",},
			["Dunkelmond-Karten"] = { content = "Niemand weiß gso wirklich, wer die '''Dunkelmond-Karten''' angefertigt hat oder welchem Zweck sie dienen, allerdings kann man sagen, dass sie in ganz Azeroth gefunden wurden, normalerweise in den Händen eines Bösewichts, der ihre Geheimnisse enthüllen wollte.",},
			["Dunkelmondjahrmarkt"] = { content = "#REDIRECT [[Dunkelmonds Jahrmarkt]]", redirect = "Dunkelmonds Jahrmarkt",},
			["Dunkelmonds Jahrmarkt"] = { content = "Silas '''Dunkelmonds Jahrmarkt''' feiert die Wunder und Mysterien [[Azeroth]]s. Zwar verbringt der Jahrmarkt die meiste Zeit an einem unbekannten Ort, doch von Zeit zu Zeit gastiert Silas’ Truppe in [[Mulgore]] oder dem [[Wald von Elwynn]]. Wenn der Jahrmarkt auf dem Weg ist, schickt Silas Marktschreier voraus nach [[Orgrimmar]] und [[Eisenschmiede]], um die Ankunft des Dunkelmond-Jahrmarkts anzukündigen. \r\nHier gibt es alles... leckeres Essen, schmackhafte Getränke, exotische Artefakte, Wahrsagerei, unglaubliche Preise und Spiel und Spaß pur! Vergesst nicht eure Dunkelmond-Gewinnlose bei Gelvas Grimegate einzulösen! Mit nur fünf Losen oder mehr seid ihr dabei und könnt zwischen den wunderbarsten Preisen in ganz [[Azeroth]] wählen. Bei uns ist jeder ein Gewinner! \r\n==Features==\r\n* Mit Silas Dunkelmond zusammen reisen viele exotische Händler, bei denen Abenteurer schwer zu findende Gegenstände aus den entlegensten Winkeln [[Azeroth]]s kaufen können. \r\n* Spieler können bei den Händlern auf Dunkelmonds Jahrmarkt bestimmte Handwerksgegenstände gegen Tickets eintauschen, die ihrerseits wiederum gegen Gegenstände und spezielle Ausrüstung eingetauscht werden können. \r\n* In ganz [[Azeroth]] sind vor kurzem seltsame [[Dunkelmond-Karten]] aufgetaucht, die anscheinend zu kompletten Kartensets gehören. Silas Dunkelmond hat wahrlich epische Belohnungen für all jene angekündigt, die es schaffen, ein komplettes Set auf dem Jahrmarkt abzugeben. \r\n* Außerdem auf dem Dunkelmondjahrmarkt: Kostenlose Stärkungszauber! Redet mit dem Wahrsagergnoll namens Sayge und erhalten, je nach Antworten, die ihr gebt, euren eigenen, auf euch zugeschnittenen Stärkungszauber! \r\n* Ein Flug mit der [[Blastenheimer 5000 Ultrakanone]].\r\n* Günstiger Fusel! \r\n(Quelle:",},
			["Dunkelspeer"] = { content = "#REDIRECT [[Dunkelspeertrolle]]", redirect = "Dunkelspeertrolle",},
			["Dunkelspeere"] = { content = "#REDIRECT [[Dunkelspeertrolle]]", redirect = "Dunkelspeertrolle",},
			["Dunkelspeerklan"] = { content = "#Redirect[[Trolle der Dunkelspeere]]", redirect = "Trolle der Dunkelspeere",},
			["Dunkelspeerstamm"] = { content = "#REDIRECT [[Dunkelspeertrolle]]", redirect = "Dunkelspeertrolle",},
			["Dunkelspeertrolle"] = { content = "Sprache:[[Zandali]]\r\n==Allgemeines==\r\n'''Die Trolle der Neuen Horde'''\r\nEine Besonderheit unter den [[Trolle]]n stellt der Stamm der Dunkelspeere da, der lange Zeit isoliert lebte und sich dann bei [[Thrall]]s Ankunft in [[Durotar]] den [[Orcs]] und der neuen [[Horde]] anschloss. Kulturell nicht weiter entwickelt als andere Trollvölker, näherten sich die Dunkelspeere erst misstrauisch den [[Orcs]] und dem bald ebenfalls auf der Bildfläche erscheinenden Volk der [[Tauren]] an. Erstaunlich ist, dass [[Tauren]] und Dunkelspeere allem Anschein nach eine Nähe zueinander verspüren, die im starken Kontrast zur ihren unterschiedlichen Mentalitäten und Kulturen steht.\r\nDie Kriege der vergangenen Jahre haben viele Dunkelspeere erkennen lassen, dass das Bündnis mit der [[Horde]] bemerkenswerte Vorteile bringt. Die Einflüsse des ersten Kontaktes mit anderen Völkern seit Jahrhunderten, der nicht sofort in Auslöschung einer Seite gipfelte, sind nicht von der Hand zu weisen. Noch weit entfernt davon, kulturell assimiliert zu werden, haben die Dunkelspeere im letzten halben Jahrzehnt eine gewisse Weltoffenheit und Aufgeschlossenheit entwickelt, die sie eklatant vom Großteil der anderen Trollstämme unterscheidet und traditionelle [[Trolle]] teilweise beunruhigt. \r\n===Charakter-Wandel===\r\nDie Annäherung an die Zivilisation hat verschiedene Begleiterscheinungen mit sich gebracht: Die Notwendigkeit der Entsendung von Botschaftern, verstärkten Handel, eine wachsende Kenntnis über strategische Zusammenhänge und die Bedrohung durch die [[Brennende Legion]], etc. Eine erstaunliche Anzahl junger Dunkelspeere zieht, anstatt der Tradition zu folgen und beim Stamm zu bleiben, im Auftrag der [[Horde]] in die Welt hinaus, kämpft an der Seite von [[Untote]]n, [[Orcs]], [[Tauren]] und [[Blutelfen]], bringt neue Geschichten, kostbare Beute und Wissen zurück in die Heimat. Der trollische Charakter bleibt den Dunkelspeere bisher erhalten, hat aber durch den engen Kontakt neue und zumindst ein wenig freundlichere Züge erhalten (so ist es etwa schwer, [[Untote]] dauerhaft zu hassen, wenn man mehrmals Seite an Seite mit ihnen [[Zentauren|Kolkar]], [[Drachen]] und [[Dämonen]] entgegengetreten ist). \r\n===Ehre===\r\nFür [[Trolle]] existiert kein Ehrbegriff im üblichen Sinne - der Sieger eines Kampfes braucht nicht zu rechtfertigen, wie er den Sieg errungen hat. Allerdings haben die Dunkelspeere inzwischen eine gewisse Vorstellung vom Konzept der \"Ehre\" entwickelt. Einige einzelne Dunkelspeere tendieren neuerdings dazu, den orcischen bzw. taurischen Begriff von \"Ehre\" teilweise zu übernehmen. Die meisten Trolle haben jedoch auch weiterhin kein ethisches Problem damit, einen Feind hinterrücks zu töten oder jegliches andere Mittel zu nutzen, um ihre Chancen zum Sieg zu maximieren.\r\n===Die Rolle der Weibchen===\r\nDie bis vor kurzem noch grundsätzlich den Männern untergeordnete Rolle der Dunkelspeere-Frauen hat sich angesichts der rasanten Veränderungen der vergangenen Jahre überraschend schnell gewandelt. Zwar konnten Frauen bzw. 'Weibchen' auch zuvor in Einzelfällen als Heilerinnen, Mojo-Mamas, Geistersprecherinnen etc. zu großem Ansehen kommen - jedoch hat gerade die annähernde Auslöschung der Dunkelspeere durch die [[Murlocs]] sowie die Kriege der vergangenen Jahre eine zunehmende Zahl von [[Jäger]]innen, [[Krieger]]innen, Späherinnen etc. auf den Plan treten lassen, die eben so tödlich und gnadenlos kämpfen wie ihre männlichen Gegenparts.",},
			["Dunkeltrolle"] = { content = "Vereinzelten Berichten zu Folge haben die Dunkeltrolle graue bis schwarze Haut und führen zumeist ein unterirdisches Leben. Bei angeblichen Sichtungen von Dunkeltrollen wird von titanischen, unzivilisierten Kreaturen gesprochen, die mit wenig taktischer Planung und ohne Zusammenhalt in der Gruppe angreifen. Deswegen wird vermutet, dass Dunkeltrolle wesentlich weniger intelligent sind als andere Trollarten. Dies ist das geheimnisvolle fünfte Volk der [[Trolle]], über welches bis heute fast nichts bekannt ist. Zusammen mit den [[Nachtelfen]] leben sie in den uralten Wäldern [[Kalimdor]]s und es geht sogar das Gerücht, sie hätten an der Schlacht um den Weltbaum teilgenommen. Es gibt keine Hinweise darauf, dass die Dunkeltrolle jemals eine Zivilisation oder eine Nation gegründet haben. Tatsächlich ist ihre geschätzte Anzahl so gering, dass die Berechtigung für eine eigene Trollkategorie ernsthaft in Frage gestellt wird. Deshalb ist es wahrscheinlich, dass die Dunkeltrolle, sollten sie wirklich existieren, von einem einzigen Stamm abstammen.",},
			["Dunkelwirker Syth"] = { content = "'''Dunkelwirker Syth''' ist ein [[Arakkoa]] in den [[Sethekkhallen]] von [[Auchindoun]]. Er ist der Bruder von [[Isfar]] am Eingang der [[Sethekkhallen]] und führte zusammen mit [[Klauenkönig Ikiss]] die Kolonie der [[Arakkoa der Sethekk]] während ihres Auszuges aus [[Skettis]]. Er trug wahrend der Rituale [[Terokks Maske]] und ist berühmt für seine Elementarbeherrschung. Dunkelwirker Syth bewacht außerdem das [[Buch der vergessenen Namen]]. \r\nDie [[Arakkoa der Sethekk]] haben [[Skettis]] mit Fanfaren verlassen, als [[Auchindoun]] explodiert ist und hielten die Katastrophe für einen Vorbote für die Ankunft ihres Meisters. Syth, war einer ihrer Anführer und sagte des Sethekk, dass es ihre Pflicht wäre, in die Tempelruinen zu gehen und Syths Bruder [[Isfar]] Zweifel an den Fähigkeiten seines Bruders und dessen Verbündeten [[Klauenkönig Ikiss]]. Nach einiger Zeit warf Syth seinen Bruder aus den Hallen und verbot ihm, seine Schwester [[Lakka]] mitzunehmen. \r\n==Fähigkeiten==\r\n* '''Arkaner Schock''' - Arkaner Schock schockt einen Gegner mit erschütternder Kraft, fügt 12 Sekunden lang alle 3 Sekunden zusätzlichen Arkanschaden zu. \r\n* '''Flammenschock''' - Flammenschock verbrennt sofort einen Feind und fügt ihm dann 12 Sekunden lang alle 3 Sekunden zusätzlichen Feuerschaden zu. \r\n* '''Frostschock''' - Frostschock fügt einem Feind Frostschaden zu und verringert 8 Sekunden lang sein Bewegungstempo. \r\n* '''Kettenblitzschlag''' - Kettenblitzschlag trifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 5 Ziele aus und verursacht bei jedem folgenden Ziel immer größeren Naturschaden. \r\n* '''Schattenschock''' - Schattenschock schockt einen Gegner mit erschütternder Kraft, fügt danach 12 Sekunden lang alle 3 Sekunden Schattenschaden zu.",},
			["Dunklen Horde"] = { content = "#REDIRECT [[Dunkle Horde]]", redirect = "Dunkle Horde",},
			["Dunkler Kleriker"] = { content = "#REDIRECT [[Untoter Priester]]", redirect = "Untoter Priester",},
			["Dunkler Rat"] = { content = "Die Geister des Dunklen Rats im [[Schattenmondtal]] versuchen, ein altes und mächtiges Übel durch ein Ritual, das bei den Lavabecken südlich des Basislagers der Sketh'lon durchgeführt werden soll, in diese Welt zu beschwören. Es braucht mächtige Artefakte, um der teuflischen Magie des Dunklen Rats entgegen zu wirken: [[Gul'dan]]s Magie vermischt mit ihrer eigenen. Und damit wollen sie diese Kreatur in die Welt rufen. Der Tod und die Zerstörung, die dieses Wesen in die Welt bringen würde, sind unvorstellbar.",},
			["Dunkler Waldläufer"] = { content = "Dunkle Waldläufer sind ehemalige [[Waldläufer]], die während der Eroberung von[[ Quel'thalas]] von der [[Geißel]] getötet und als [[Banshee]]s wiederbelebt wurden. Manche kehrten in ihre alten Körper zurück und dienten der Geißel mit ihren Waldläuferfähigkeiten.Als [[Sylvanas]], selbst ein Dunkler Waldläufer, rebellierte, schlossen sich ihr viele Waldläufer an. Nun dienen diese Untoten den [[Verlassenen]] mit ihren Fähigkeiten als Schützen und Kundschafter.All ihre Fähigkiten sin die einer [[Banshee]] , nur noch um ein vielfaches verstärkt. Sie sind in der Lage, mit ihren Pfeilen getötete als [[Skelet]]te widerauferstehen zu lassen, Feinden das Leben aus dem Körper zu kanalisieren, Zauber mit der Macht ihrer Schreie zu brechen und mit ihren Bansheefähigkeiten die Seelen ihrer Opfer zu vertreiben und sie in willige Diener zu verwandeln.",},
			["Dunkles Portal"] = { content = "Das Dunkle Portal war eine Pforte, die durch den [[Sog der Unterwelt]] und das [[Großes Dunkles Jenseits|Große Dunkle Jenseits]] führte. Im Jahr 583 - vor Beginn des Ersten Krieges - öffnete [[Medivh]] und die [[Hexenmeister]] des [[Schattenrat]]s unter gemeinsamer Aufbietung aller Kräfte dieses Dimensionstor zwischen dem Königreich [[Azeroth]] und der Welt [[Draenor]]. Dieses Portal war groß genug, dass ganze Armeen es passieren konnten. [[Gul'dan]] schickte Späher der [[Orcs]] durch das Portal, damit sie die Länder, die sie erobern sollten, ausspähen konnten. Als die Späher zurückkehrten, versicherten sie dem [[Schattenrat]], dass die Welt [[Azeroth]] reif für die Eroberung sei.\r\n==Aktuelles==\r\nZwanzig Jahre lang stand das Dunkle Portal still - ein Symbol für längst vergangene Zeiten. Aber nun ist es nicht mehr still. Hier stehen [[Horde]] und [[Allianz]] nun und schauen tief in den Abgrund. Nachdem der Angriff der [[Dämonen]] aufgehalten wurde, haben die Truppen das Portal durchschritten und sich den [[Dämonen]] auf ihrem eigenen Gebiet gestellt. Auf der anderen Seite des Portals sind sie in einem grausamen Krieg gefangen - ein Krieg, den sie nicht ohne Hilfe gewinnen können. Die Soldaten von [[Horde]] und [[Allianz]] halten bei den Stufen des Schicksals noch immer die Stellung. Allerdings sendet die [[Brennende Legion]] ihren Reihen immer wieder neue Angriffswellen entgegen. Die Truppen der [[Allianz]] und der [[Horde]] stehen zwar gemeinsam auf einer Seite, aber dennoch fürchten sie, dass die [[Brennende Legion]] die Verteidigung mit ihrer Überzahl überrennen wird. Sie bitten um so viel Unterstützung wie möglich, damit das Portal nicht fällt und sie nicht auf ewig in dieser alptraumhaften Welt gefangen sein werden. Die Kämpfe bei dem Portal nehmen kein Ende und die [[Argentumdämmerung]] kämpft in einer verzweifelten Schlacht - sollten sie verlieren, wird das Feuer der [[Dämonen]] niemals erlöschen. Für [[Kriegsherr Dar'toon]] ist es deshalb seine Pflicht und ein grausames Vergnügen, die Feinde der [[Horde]] in der Scherbenwelt zu bekämpfen und den Sieg zu sichern.\r\n===Kampf um das Dunkle Portal===\r\nDie Ankunft der [[Orcs]] markierte den Beginn des Ersten Krieges, der [[Azeroth]] fast 5 Jahre lang verheeren sollte. Die einst reichen Ländereien des Königreiches wurden von den erbarmungslosen Klans verwüstet und blieben als tote Erde zurück. Bis zum Ende des Zweiten Krieges sollte die Pforte beständig an Größe und Macht gewonnen. Nach der Belagerung der [[Schwarzfelsspitze]], blieb den [[Orcs]] jedoch nichts anderes übrig, als sich zum Dunklen Portal zurückzuziehen - der letzten Bastion ihrer Macht in [[Azeroth]]. Und dort, am Fuße des kolossalen Tors, trugen die dezimierte [[Horde]] und die unerbittliche [[Allianz]] die letzte und blutigste Schlacht des Zweiten Krieges aus. Die zahlenmäßig unterlegenen [[Orcs]] hatten den mächtigen Streitkräften unter General [[Turalyon]] und Sir [[Uther Lichtbringer]] nichts mehr entgegenzusetzen. Im letzten Kampf um das Dunkle Portal wurden die [[Orcs der Brennenden Klinge]] fast völlig ausgelöscht, und der [[Erzmagier]] [[Khadgar]] zerstörte das Portal. Aber die Pforte, die [[Medivh]] einst geöffnet hatte, blieb bestehen. Die [[Kirin Tor]] von [[Dalaran]] errichtete die Zitadelle von [[Burg Nethergarde|Nethergarde]], um sie zu untersuchen und als Schutz zu dienen, falls sie sich wieder öffnen sollte.\r\n===Jenseits des mystischen Tores===\r\nNur wenige Monate später - im Jahr 606 - verlieh der Schamane [[Ner'zhul]], der über die verbliebenen Klans in [[Draenor]] herrschte, dem Durchgang wieder magische Energie und vergrößerte ihn. Schließlich konnte er das Portal nach [[Azeroth]] wieder öffnen und das Dunkle Portal neu errichten. Abermals stürmten die orkischen Klans nach [[Azeroth]]. Sie stahlen einige magische [[:Kategorie:Artefakt|Artefakte]], um neue Portale in [[Draenor]] zu öffnen und den Übergang in andere Welten zu ermöglichen. [[Ner'zhul]] wollte der todgeweihten roten Welt [[Draenor]] für immer entfliehen, und die [[Horde]] zu neuen, unberührten Welten führen. Die aufgebrachten Streitkräfte der [[Allianz]] folgten dem Schamanen nach [[Draenor]], doch [[Ner'zhul]] ließ sich nicht an der Umsetzung seiner perfiden Pläne hindern. Als er die Portale öffnete, begannen ihre riesigen Energien die verwüstete Welt bis ins Innerste zu erschüttern und auseinander zu reißen. [[Ner'zhul]] gelang die Flucht durch eines der Portale, während der [[Erzmagier]] [[Khadgar]] das Dunkle Portal endgültig zerstörte, und [[Azeroth]] vor einem Schaden durch die brutale Verwüstung [[Draenor]]s bewahrte.",},
			["Dunkle Horde"] = { content = "Die Dunkle Horde ist ein Überbleibsel der Alten Horde. Ihr gehören die [[Orcs]] vom [[Schwarzfels Clan]], [[Oger]] und zwei [[Waldtroll]]stämme an.Die Dunkle Horde kämpft den [[Zweiten Krieg]] immer noch weiter, ungeachtet der Tatsache , dass der Krieg schon entschieden wurde.Sie verachten die neue Horde unter [[Thrall]] als schwach und zu feige, sich den [[Menschen]] zu stellen.Ihr Kriegshäuptling ist [[Rend Schwarzfaust]].\r\nDie Dunkle Horde hat sich mit [[Nefarian]] und seinen [[Drachen]] verbündet.Vom [[Schwarzfels]] aus, einer alten Festung der Horde, wo [[Orgrim Schicksalshammer]] seine vernichtende Niederlage erlitt, schmieden die Anhänger der Dunklen Horde Pläne, wie sie die Allianz vernichten können",},
			["Dunkle Portal"] = { content = "#REDIRECT [[Dunkles Portal]]", redirect = "Dunkles Portal",},
			["Dunst der Atal'ai"] = { content = "Der Dunst der Atal'ai ist ein Gift aus dem [[Versunkener Tempel|Versunkenen Tempel]] von Atal'Hakkar in den [[Sümpfe des Elends|Sümpfen des Elends]]. Es ist ein abscheuliches Zeug und sehr schwer zu sammeln. Den Dunst der Atal'ai bekommt man von Tieflauerern, Düsterwürmern oder Brühschlammern, die man dort findet.",},
			["Dun Algaz"] = { content = "Dun Algaz liegt von [[Loch Modan]] aus weiter die Straße entlang im Norden, hinter dem Wachturm. Die [[Orcs des Drachenmals]] haben im [[Sumpfland]] eine Zufluchtstätte und jetzt haben sie sich auch nach Dun Algaz ausgebreitet. Die [[Zwerge]] können nicht zulassen, dass sie ihren Einfluss auf dieses Gebiet behalten, sonst wird der [[Loch Modan]] vom [[Hafen von Menethil]], der Hafenfestung im [[Sumpfland]], abgeschnitten. Gebirgsjäger Felsgar sucht deswegen nach Freiwilligen für eine Mission durch Dun Algaz und in das [[Sumpfland]] hinein. Man hat auch gehört, dass im [[Sumpfland]] in einer Höhle nordwestlich vom Algaz-Tor ein seltenes Erz namens [[Pyrophor]] gefunden wurde. \r\n==Geschichte==\r\nWährend des [[Der Zweite Krieg|Zweiten Krieges]] gelang es der [[Allianz]], die antike [[Zwerge]]nstadt [[Dun Modr]] zu zerstören, und die Orcische [[Horde]] nach Dun Algaz zurückzudrängen. Viele Stämme flohen später aus [[Khaz Modan]], um das [[Dunkle Portal]] gegen den bevorstehenden Angriff der [[Menschen]] zu verteidigen. Nach einer blutigen Schlacht konnten General [[Turalyon]]s Streitkräfte das mystische Tor letztendlich vernichten und die verstreuten [[Orcs]] gefangen nehmen. Nur die [[Orcs des Drachenmals]] stellten noch eine Gefahr für den unsicheren Frieden in [[Lordaeron]] dar. \r\n'''Quelle''': \r\n===Die letzte Bastion der Horde===\r\nIm nördlichen [[Khaz Modan]] hatten die [[Orcs des Drachenmals]] eine stattliche Armee aufgestellt, ihre mächtigste Waffe waren jedoch die gewaltigen [[Drachen]] aus [[Grim Batol]]. Der [[Schamane]] [[Zuluhed]] setzte die gefürchteten Bestien ein, um Dun Algaz auch weiterhin gegen die Armeen der [[Allianz]] zu verteidigen. Nahe der Ruinen von [[Dun Modr]] bezogen die freien Völker [[Lordaeron]]s Stellung, um die Bedrohung durch die [[Horde]] ein für alle Mal zu beenden. Nur dank der [[Drachen]], die von Hexenmeister [[Nekros Schädelberster]] gezüchtet und abgerichtet wurden, konnte die Bergfestung den beständigen Angriffen standhalten. In den folgenden Monaten wurden immer mehr [[Drachen]] nach Norden geschickt, und die Brutstätten blieb schließlich fast schutzlos zurück. Die große Schlacht von [[Grim Batol]], in der die [[Drachen]]königin [[Alexstrasza]] befreit wurde, besiegelte das Schicksal der [[Orcs]]. Ohne Verstärkung war es nur eine Frage der Zeit, bis auch Dun Algaz dem gnadenlosen Ansturm der [[Allianz]] zum Opfer fiel.",},
			["Dun Garok"] = { content = "Dun Garok ist eine zwergische Kaserne im südöstlichen Vorgebirge des Hügellands. Sie wurde entlang des Thoradinwalls errichtet und wird von Hauptmann Eisenberg geführt.",},
			["Dun Modr"] = { content = "Dun Modr war eine antike [[Zwergen]]stadt im nördlichen [[Sumpfland]] von [[Khaz Modan]]. Bereits vor dem [[Der Zweite Krieg|Zweiten Krieg]] hatten die [[Orcs]] das Bergkönigreich der [[Zwerge]] angegriffen, und die Stadt an den Grenzen zu [[Stromgarde]] eingenommen. In einer letzten Schlacht um [[Khaz Modan]], war die [[Allianz]] gezwungen [[Dun Modr]] zu zerstören. Die [[Horde]] wurde zwar nach [[Dun Algaz]] zurückzudrängt, aber dank der [[Drachen]] des [[Drachenmal Klan]] blieb der Norden des Landes auch nach dem [[Der Zweite Krieg|Zweiten Krieg]] besetzt.\r\n'''Quelle''': \r\n==Aktuelles==\r\nDer Krieg tobt daheim ebenso wie in der Fremde. Doch während mächtige [[Zwergen]]krieger im Namen der [[Allianz]] in weit abgelegenen Gegenden ihr Leben lassen, fallen ihre eigenen Gebiete den bösen Taten der [[Dunkeleisenzwerge]] zum Opfer und Dun Modr ist an die [[Dunkeleisenzwerge]] gefallen. Viele der Soldaten fielen in dieser Schlacht und nun müssen sie Kräfte sammeln und die Front zurückdrängen. Sie erwarten die Reserven von [[Eisenschmiede]].\r\n==Personen==\r\n* '''Ashlan Schmunzelstein''' ist ein Sprengstoffexperte und wurde dem Regiment zugeteilt, das Dun Modr und den [[Thandolübergang]] bewachen soll. \r\n* '''Dunst MacKreel''' hat gestern gesoffen und ist während seiner Wache eingepennt ist. Er hat Braumeister Bilger in [[Süderstade]] versprochen, dass er seine Schulden mit ein wenig Fusel bei ihm bezahlen würde und er hat nur noch 15 Minuten.\r\n* '''Langzopf der Grimmige''' verlor seinen Bruder, als die Westbrücke über dem [[Thandolübergang]] zerstört wurde. Langzopf versprach, dass er einen Späher schicken würde, der sich bei [[Whelgars Ausgrabungsstätte]] umsieht, wenn sie nicht bald etwas vom Trupp dort hören. \r\n* '''Motley Garmason''' verlangt [[Kam Tiefenzorn]]s Kopf. \r\n* '''Roggo Harlborg''' ist ein Späher und hat von einem Lager der [[Allianz]] im Norden des [[Arathihochland]]s bei der [[Zuflucht]] erfahren.\r\n* '''Rhag Garmason''' will, dass man den alten Rostlocke findet und den den guten Hauptmann fragt, ob die [[Allianz]] einige Soldaten erübrigen kann, die den [[Zwerge]]n behilflich sein können, Dun Modr und den [[Thandolübergang]] zurückzuerobern.",},
			["Dun Morogh"] = { content = "== Allgemeines==\r\n[[Dun Morogh]] ist das schneeüberdeckte Mutterland der [[Zwerge]], schön, rauh und kalt. Kalt wäre wohl die Beschreibung eines verweichlichten [[Menschen]], oder der erste Eindruck eines [[Elfen]]. Ein [[Zwerg]] würde dieses Klima und die Region, mit Tränen in den Augen, als schönster und freundlichster Flecken Erde dieser gesamten Welt bezeichnen. Der beständige Winter dient auch als Erklärung für die Vorliebe der meisten [[Zwerge]] zu großen Bärten. Das Leben in den weiß verschneiten Bergen von Dun Morogh ist hart, aber was dem Volk der [[Zwerge]] an Größe fehlt, machen sie an Mut und Tapferkeit wett. Auch die [[Gnome]] - als Vertriebene aus ihrem Technikhort [[Gnomeregan]] - sind nun hier besonders heimisch. \r\n===Geographie===\r\nMitten in den Östlichen Reichen gelegen, profitiert Dun Morogh nicht vom milden Klima, da es sich als hochgelegene Ebene, umrandet von noch höheren Bergen, darstellt. Diese Lage ist eine natürliche Festung, was den Zwergen entgegen kommt. Die einzigen zwei Zugänge durch ein Tunnelsystem im Osten werden noch durch zahlreiche Wachtürme gesichert. Diese Wege führen ins Tal der Könige und unmittelbar an den [[Loch Modan]], von dem aus weitere zwergische Tunnelanlagen in das [[Sumpfland]] mit der wichtigen Hafenstadt [[Menethil]] leiten. Unerreichbar durch die steilen Felsenhänge bleibt das Große Meer zwischen den Kontinenten und auch die so gegensätzliche [[Sengende Schlucht]] im Süden. \r\nZwei Transportmittel haben sich als bedeutender als Schusters Rappen heraus gestellt, beide sind in [[Eisenschmiede]], der Hauptstadt der [[Zwerge]] im zentralen Norden Dun Moroghs, vorzufinden: zum einen die Flugverbindungen per [[Greif]] zu allen Hauptorten benachbarter Regionen, zum anderen die von Gnomen erfundene [[Tiefenbahn]], die sie durch teils natürliche, teils von erzschürfenden Zwergen Stollen weit unter die Berge bis in die Hauptstadt der [[Menschen]], [[Sturmwind]], bauten. Einige Stellflächen vor den Toren von [[Eisenschmiede]] werden als Plätze für fahrendes Volk oder sportliche Wettkämpfe genutzt. \r\n===Schätze===\r\nAnscheinend waren die stets auf Schätze gierigen [[Zwerge]] überaus gründlich, denn in ganz Dun Morogh wird der Suchende kaum etwas von besonderem Wert finden. Selbst lokal gefürchtete Wesen wie [[Vagash]] besitzen keine oder nur Plunder. Seltenst findet sich Schatztruhen, die aber nur ganz unten auf ihren Böden ein paar Kupferstücke enthalten.\r\nDoch die zerklüfteten, schneebedeckten Gipfel dieses Gebietes versorgen die [[Zwerge]] von [[Khaz Modan]] mit einem unendlichen Vorrat an Erzen und Steinen für ihre ehrgeizigen Konstruktionen. Von [[Eisenschmiede]], die tief in den Berg gegraben wurde, bis nach [[Ambossar]] im [[Eisklammtal]] verschönern die Wunder zwergischen Einfallsreichtums die Landschaft. \r\nIn ganz Dun Morogh finden sich auch recht harmlose bis sogar zwergen-scheuende Wildtiere wie [[Bär]]en, [[Schneeleopard]]en, [[Wölfe]], [[Kojote]]n und [[Hase]]n, die allesamt nur gelegentlich ein leichtes Leder einbringen. \r\nAn Kräutern darf man nichts Weltbewegendes erwarten. [[Friedensblume]]n, [[Silberblatt]] und gelegentlich [[Erdwurzel]]n.\r\n===Gefahren===\r\nDennoch ist nicht alles in Dun Morogh friedlich. Denn durch das unaufhörliche Graben im [[Steinbruch von Gol'Bolar]] haben die [[Zwerge]] die bedrohlichen [[Troggs der Felsenkiefer]] aus ihrem unterirdischen Gefängnis befreit. Während dem [[Bergkönig]]reich eine Invasion dieser bösartigen Kreaturen droht, nutzen auch die [[Eistrolle]] die Gunst der Stunde und schicken sich nun an, die Heimat ihrer Vorväter zurück zu erobern. Die [[Trolle der Frostmähnen]] mussten einst den Armeen der [[Zwerge]] weichen und sich sich in die Hügel zurückziehen - eine Schande für die kriegerische Natur der [[Trolle]]. \r\n==Orte==\r\n* [[Ambossar]]\r\n* [[Bräuhall]]\r\n* [[Eisenbands Lager]]\r\n* [[Eisklammpass]]\r\n* [[Eisklammtal]]\r\n* [[Flughafen]]\r\n* [[Gehöft Bernruh]] \r\n* [[Gnomeregan]]\r\n* [[Kharanos]]\r\n* [[Nordtorpass]]\r\n* [[Stahlrosts Depot]] \r\n* [[Steinbruch von Gol'Bolar]]\r\n==Personen==\r\n* [[Gebirgsjäger Wellart Gerstenbräu]]\r\n* [[Pilot Mori Hangflug]]\r\n* [[Vagash]]\r\n==Klans und Stämme==\r\n* [[Trolle der Frostmähnen]]\r\n* [[Troggs der Felsenkiefer]]",},
			["Durathror"] = { content = "==Charakter==\r\n'''Durathror''', von ihren Mitstreitern auch die \"Prügelkuh\" genannt, ist eine [[Tauren Schamane|Tauren Schamanin]], die sich dem Element der Luft gewidmet hat und sich als Sturmsucherin auf dem Pfade [[Al'Akir]]s bezeichnet. Durathror bedeutet soviel wie \"Der Stille folgend\" und so ist es nicht verwunderlich, wenn man von der weißen Taurenkuh als Antwort auf eine Frage oftmals kaum mehr als ein vieldeutiges \"Muh!\" zu hören bekommt. \r\n==Geschichte==\r\nWir schreiben den 3. Mond der Erdenmutter im 3. Jahr der großen Suche. \r\nFern liegen die weiten Ebenen [[Mulgore]]s unter einem unruhigen Himmel. \r\nUnser geliebtes Land wird von unzähligen Gefahren bedroht. \r\nDie Zeiten sind düster. \r\nDie Sturmgeister toben. \r\nUnser weiser [[Druide|Erzdruide]] Hamuel Runentotem hat Abgesandte meines Volkes mit dem [[Zirkel des Cenarius]] in die neue Welt geschickt. Um zu forschen. Um Verbündete zu suchen. Und ich werde dem Aufruf folgen, denn obgleich ich nicht dem [[Zirkel des Cenarius]] angehöre, hoffe ich etwas zu finden, was die Bedrohngen auf unserer Welt eindämmt, Verbündete, die uns mit ihrem Wissen beistehen und Wissen selbst .... um das Land von der siechenden Verderbnis zu heilen. \r\n-----------------------------------------------------------------------------------------------------------------\r\nVor nunmehr drei Jahren war es, dass Tonga der Blinde, auf dem alljährlichen großen Gestampfe die Knochen des Geistheulers, eines einstmals stattlichen Wolfes, eingewickelt in sein altes Fell, was noch immer die Größe und Kraft dieses Tieres erahnen ließ, in die Mitte des eingehaselten Platzfriedes legte. \r\nDie Totemstäbe auf seinen Schultern glichen kleinen Bäumen, die sich in einer aufkommenden Briese sogar zu bewegen schienen, als er seine Hände in den Himmel streckte, Gewitterwolken die Sonne verdeckten und der fröhlichen Feier eine ernste Wendung gaben. Stumm und die Augen voller Sorge blickten ihm die eben noch Feiernden entgegen, denn eine bedrohliche Stille senkte sich hernieder. \r\n\"Meine Brüder!\" rief der mit einer Festigkeit in der Stimme, die keinen daran zweifeln ließen, dass dieser alte Druide noch immer eine enorme Kraft besaß. \r\n\"Meine Brüder!\" erklang sein Ruf wieder bis er sich vergewissert hatte, die volle Aufmerksamkeit der Anwesenden zu haben. \r\n\"Ihr feiert die alten Feste wie es unsere Ahnen taten!\" \r\nEin zustimmendes Donnern von aufstampfenden Hufen und Waffen die auf Schilde geschlagen wurden ertönte aus dem Kreis. \r\n\"Ihr sprecht mit den Ahnen wie es Generationen vor uns taten!\" \r\nWieder folgte ein bespflichtendes Donnern. \r\n\"Ihr jagt im Einklang mit der Erdenmutter wie es unsere Vorväter taten!\" \r\nEin allgemeines stummes Nicken bejahte auch das und vereinzelt noch erklang das Geräusch wenn Waffen auf das Holz der Schilde trafen. \r\nTonga ließ wieder wieder völlige Stille einziehen, ehe er mit langsamer und gesenkter Stimme fortfuhr. \"Doch fürchte ich, meine Brüder, dass diese Zeiten gezählt sind.\" \r\nSofort unterbrach er die aufkommende Unruhe unter den Anwesenden mit einer einzelnen Bewegung seiner Hand. \r\n\"Nein, laßt mich ausreden.\" Langsam sprach er weiter. \"Ihr wißt tief in eurem Herzen, dass ich die Wahrheit sage, denn viel hat sich verändert. Seht diesen Wolf. Einst war er ein stattliches Tier und der Anführer eines großen Rudels hier in Mulgore. Unsere Jäger hatten Respekt vor ihm. Sie achteten seine Größe und die Kraft der Erdenmutter, die in ihm lebte.\" \r\nStumm nickten ihm viele Köpfe zu und Tonga spürte die Trauer, die in diesem stillen Nicken mitschwang. \r\n\"Er fiel im Kampf gegen die Brennende Legion. Ihr wißt das. Sein Geist fand keine Ruhe. Der Eintritt ins Reich der Ahnen, zurück in den Kreis der Erdenmutter wurde ihm verwehrt. Verwehrt durch die Verderbnis und die Störung des Kreislaufes, die die Brennende Legion mit sich brachte!\" \r\nLangsam wich die Trauer der Anwesende aufkommender Wut gegen diese Tatsache und der Blick der Tauren hob sich grimmig als sie ihre Waffen fester griffen. \r\n\"Er ist nicht das einzige Opfer und nicht das einzige Beispiel für die Bedrohung UNSERER Länder ... der Länder UNSERER Ahnen! Die Länder, für deren Frieden wir solange und so hart gegen die Zentauern gekämpft haben! Die Länder, die wir an noch unsere Kinder und Kindeskinder geben wollen!\" \r\nDie Wolken über dem Platz verfinsterten sich mehr und mehr und vereinzelt zucken Blitze herab, die sich in den wütenden Augen der Anwesenden wiederspiegelten. \r\n\"Die Goblins rauben in ihren Minen die Gaben der Erdenmutter, um sich an ihrem Gewinn ihre Wänste vollzustopfen. Sie wachsen schneller als es für sie gut ist und und scheren sich nicht um ein Gleichgewicht. Die Zwerge tun es ihnen gleich und treten die Grenzen UNSERER Länder mit Hufen! Harpien breiten sich aus und selbst die Zentauren scheinen ihre Stärke wiedergefunden zu haben!\" \r\nLautes Wutschnauben war zu vernehmen und grollend donnernde Hufe stampften auf den Boden. \r\n\"Sie begegnen dem Frieden der Mesa mit Verachtung!\" \r\n\"Sie stören das Gleichgewicht der Elemente!\" \r\n\"Sie treten die Gaben der Erdenmutter mit Hufen!\" \r\nEinige [[Tauren]] begannen laute Wutschreie auszustoßen und blickten Tonga schnaubend vor Zorn entgegen, bereit augenblicklich auf den nächst besten Gegner zu stürmen, der es wagen sollte, sich zu nähern. Doch Tonga breitete seine Arme aus und gebat Ruhe. \r\n\"Und es ist nicht nur hier in unseren Ländern. Auch die Länder unserer Verbündeten sind bedroht! Und wenn wir nicht all unsere Kraft aufbieten, dann wird es bald keine Ebenen mehr geben, auf denen die Kodoherden in Frieden ziehen und unsere Kinder in sorgloser Ruhe aufwachsen können!\" \r\nWohl kaum einer hätte es zu diesem Zeitpunkt noch geschafft, diese vor Wut rasende Herde ruhig halte zu können, doch genau das hatte Tonga bezweckt und so sprach er weiter: \r\n\"Geht hinaus meine Brüder und Schwestern! Lernt von den Kriegerhelden und Ältesten eure Kräfte zu stählen! Schließt euch unseren Kriegsverbänden und laßt euch von ihnen anleiten! Zieht hinaus und sucht nach Verbündeten! Sucht nach Heilmitteln gegen diese Verderbnis! Kämpft gegen die Bedrohung, die sich über den Leib der Erdenmutter legt! Kämpft mit unseren verbündeten Brüdern gegen die Verderbnis! Zieht hinaus, meine Brüder und kämpft, wie es unsere Vorväter getan haben! Zeigt ihnen, dass die Tauren kein schwaches Volk sind und bereit stehen, jedwedem Feind mit einer Entschlossenheit gegenüber zu treten, die ihre verdorbenen Festungen in den Grundfesten erschüttert und zermalmt! Und kehrt dereinst zurück, gestählt und weise und mit der Kraft, den Ebenen ihren Frieden zurückzugeben, damit auch morgen noch die Kodoherden ziehen und unsere Kinder ohne Furcht aufwachsen! Im Namen der [[Erdenmutter]]! Im Namen unserer Ahnen! Im Namen des Stammes und allem, was uns heilig ist!\" \r\nKaum einer konnte sich diesem Aufruf entziehen. Sie dürsteten danach, aufzubrechen und den Tongas Worten folge zu leisten. Sie dürsteten danach, die [[Goblins]] und [[Zwerge]] aus den Ebenen hinauszutreten und ... dem Geist eines alten Wolfes seine Ruhe zu geben, damit kein anderes Kind der [[Erdenmutter]], egal ob [[Taure]] oder Tier dieses qualvolle Schicksal mehr erleiden mußte. \r\nUnter den Anwesenden befand sich eine junge weiße Taurenkuh, die ihrem Jagdgenossen kampfeslustig zunickte und sich anschickte, sich auf eine lange Suche zu begeben.",},
			["Durnholde"] = { content = "#REDIRECT [[Burg Durnholde]]", redirect = "Burg Durnholde",},
			["Durn der Nimmersatte"] = { content = "Durn der Nimmersatte in [[Nagrand]] ist die Geißel der Geisterfelder und ein Sohn von [[Gruul]] dem Drachentöter. Er regiert über das Gebiet beim [[Oshu'gun]] und vernichtet alles, was ihm über den Weg läuft. Bis jetzt ist es noch niemandem gelungen, [[Nagrand]] von diesem blutrünstigen [[Gronn]] zu befreien.",},
			["Durotan"] = { content = "==Allgemeines==\r\nDurotan war [[Thrall]]s Vater und Häuptling des [[Frostwolfklan]]s. Seine Frau war [[Draka]] und sein Begleiter der [[Frostwolf]] Scharfzahn. Er war einer der weisesten, grimmigsten und edelsten Häuptlinge der orcischen Klans.Sein Vater war Garad, welcher im [[Wald von Terokkar]] von Ogern erschlagen wurde. Zusammen mit seinem Freund Orgrim schicksalshammer lernte er in seiner Jugend ,noch vor der verderbniss, Velen , den anführer der Draenei kennen. Später wurden er und sein clan zum Krieg gegen die Draenei gezwungen. Durotan nahm [[Velen]] zwei der Ata'Mal Kristalle der [[Naaru]] ab. Kurz bevor die orcs Mannoroths Blut tranken, erhielt er eine Nachricht des in Ungnade gefallenen [[Ner'zhul]], der ihn vor den Folgen warnte. So tranken Durotan und sein gesamter Clan nicht von dem Blut. \r\nAls er Gul'dans dämonische Macht und den Verrat an den Klans durch den Schattenrat öffentlich machte, wurde er und sein Klan verbannt. Durotan jedoch gab nicht auf und ersuchte [[Orgrim Schicksalshammer]] um Hilfe. Eine Wache Schicksalshammers verriet Durotan und [[Draka]] und führte die Auftragsmörder des [[Schattenrat]]s auf ihre Spur. Scharfzahn, Draka und Durotan fielen in diesem Kampf. Einzig ihr zu dem Zeitpunkt noch namenloses Kind - [[Thrall]] - überlebte.\r\n===Beschreibung===\r\nDurotan hatte eine tiefe Stimme, die aus seiner breite Brust donnerte.\r\n===Leben im Exil===\r\nEinst hatte Durotan, Häuptling des [[Frostwolfklan]]s, den Kuss von milderen Gegenden gekannt. Hatte seine Axt im Sonnenlicht geschwungen und seine Augen gegen den Schein der Sonne auf dem Metall verengt und gegen das Spritzen von rotem [[Menschen]]blut. Einst hatte er eine Verwandtschaft mit all seinen Leuten gefühlt, nicht nur mit jenen von seinem Klan. Seite an Seite hatten sie gestanden, eine grüne Flut des Todes, die über die Hänge wogte, um die [[Menschen]] zu verschlingen. Sie hatten zusammen an den Feuern gefeiert, in ihrem tiefen, donnernden Gelächter gelacht, die Geschichten von Blut und Eroberung erzählt, während ihre Kinder durch die sterbenden letzten Funken eindösten, ihr kleiner Verstand gefüllt mit Bildern von Schlachten. \r\nAber jetzt fröstelten die Handvoll [[Orcs]], die den [[Frostwolfklan]] umfassten, allein in ihrem Exil im eisigen [[Alterac]]gebirge dieser fremden Welt. Ihre einzigen Freunde hier waren die großen weißen [[Frostwolf|Frostwölfe]]. \r\n'''Quelle''': \"Lord of the Clans\"",},
			["Durotar"] = { content = "Durotar ist eine staubige Einöde im Osten von [[Kalimdor]], das als neue Heimat der [[Orcs]] und auch der [[Trolle]] der [[Dunkelspeere]] dient. Wenn man die Geshichte der Gründung von Durotar wissen möchte, sollte man sich mit der Geschichte von [[Rexxar]] befassen.\r\n==Orte==\r\n* [[Burg Tiragarde]]\r\n* [[Dorf Sen'jin]]\r\n* [[Echo-Inseln]]\r\n* [[Klingenhügel]]\r\n* [[Zentauren der Kolkar|Kolkarklippe]]\r\n* [[Tal der Prüfungen]]\r\n===Donnergrat === \r\nBluthuf hat herausgefunden, dass ein Hexenmeister der Brennenden Klinge, der Goblin Fizzle Dunkelsturm, nahe dem Donnergrat im Nordwesten kampiert. Er und seine Kultdiener verbreiten dort Chaos. \r\n===Knochenhöhle === \r\nEine große Gruppe von Kultisten der [[Brennende Klinge|Brennenden Klinge]] hat die Knochenhöhle in den Bergen östlich von [[Orgrimmar]] besetzt - gleich vor den Toren [[Orgrimmar]]s. Sie führen in dieser Höhle schlimme Rituale durch und fügen sich durch Senghalsbänder selbst Brandwunden zu. Manche glauben, indem sie diese Halsbänder tragen, bringen die Kultisten sich im Einklang mit dämonischen Mächten. Schrifttafel der Verga wurde ebenfalls von Hexenmeistern der [[Brennende Klinge|Brennenden Klinge]] gestohlen und nun in diesem Unterschlupf verwahrt. Sie enthält die Glyphen, die man für die Beschwörung eines [[Leerwandler]]s braucht. \r\n* '''Margoz''' ist ein alter Orc [[Schamane]] in der Nähe der Knochenhöhle. Er weiß viel über die Verderbnis der [[Brennende Klinge|Brennenden Klinge]]. Er ist weise und sein Rat wird geschätzt. Er lagert im Nordosten zwischen der Küste und der Staubwindklamm. \r\n===Schrein der ewigen Flamme===\r\nAm Südstromfluss in [[Durotar]], vor dem großen Meer, liegt ein verborgener Pfad zu einem der höchsten Gipfel des Landes. Dort wird man einen der heiligen Schreine finden, den Telf Joolam bewacht...den Schrein der schlafenden Flamme. Viele Abenteurer finden auf der Suche nach verlorenen Schätzen oder der Jagd auf mystische Kreaturen hierher und werden von einem scheinbar leeren Schrein abgewiesen. Dieser Schrein verbirgt jedoch ein größeres Geheimnis vor den einfachen Mitgliedern der [[Horde]]. Für [[Schamanen]] ist er heilig.",},
			["Dämmerklingen"] = { content = "#REDIRECT [[Blutelfen der Dämmerklingen]]", redirect = "Blutelfen der Dämmerklingen",},
			["Dämmerwald"] = { content = "Der Dämmerwald ist eine Region der [[östliche Königreiche|östlichen Königreiche]] und liegt südlich des [[Wald von Elwynn|Waldes von Elwynn]]. \r\nDieses Gebiet war einst eine einladende Gegend, die sich nun in ein dunkles, unheimliches Land verwandelt hat. Viele glauben, die Nähe zum mysteriösen [[Gebirgspass der Totenwinde]] lockt des Nachts monströse Schrecken hervor. Andere vermuten einen uralten Fluch, der auf dem Land liegen soll. Was immer der Grund sein mag, Dämmerwald ist zu einer Gegend des Horrors und des Aberglaubens geworden. Die menschlichen Farmer, die ehemals das fruchtbare Land bearbeiteten, sind düster und grüblerisch geworden – sie wollen die Heimat ihrer Väter nicht verlassen, können aber auch den furchtbaren Schleier, der sich über ihr Leben gelegt hat, nicht heben. Mit den brachliegenden Feldern von [[Westfall]] im Westen und dem dunklen, trügerischen [[Gebirgspass der Totenwinde]] im Osten ist aus Dämmerwald ein verdorbenes Reich geworden, in dem selbst in den hellsten Stunden des Tages das Böse die Atmosphäre durchdringt.\r\nDer Dämmerwald ist erfüllt vom bösen und niederträchtigen Gestank des Untodes. Es scheint, als würden dunkle Dinge unaufhaltsam in den Dämmerwald gezogen und sie haben ein [[Worg]]-Problem. In letzter Zeit gehen seltsame Dinge vor sich, und die Dunkelheit kennt keine Atempausen. Spinnen haben die Grenze im Westen des Waldes überrannt und es ist eine wahre Untotenplage ausgebrochen. Mit jeder verstreichenden Stunde verfinstern sich die Schatten über diesem Land mehr und mehr.\r\n==Orte==\r\n* [[Addles Siedlung]]\r\n* [[Stalvan Dunstmantel|Anwesen der Dunstmantels]]\r\n* [[Bettlerschlupfwinkel]]\r\n* [[Dunkelhain]]\r\n* [[Friedhof von Rabenflucht]]\r\n* [[Rolands Verdammnis]]\r\n* [[Schattenhain]]\r\n* [[Svens Hof]]\r\n* [[Svens Lager]]\r\n* [[Verlassener Obstgarten]]\r\n* [[Zwielichtshain]]\r\n==Wichtige Personen==\r\n* [[Blinde Mary]]\r\n* [[Nachtwache]]\r\n* [[Stalvan Dunstmantel]]\r\n* [[Sven Yorgen]]",},
			["Dämon"] = { content = "#REDIRECT [[Dämonen]]", redirect = "Dämonen",},
			["Dämonen"] = { content = "Dämonen sind böse unsterbliche Wesen, die sich von [[Magie]] und Lebensenergie ernähren. Sie lieben es, Leiden zu verursachen, Verderbnis zu verbreiten und natürlich alles zu vernichten, was gut ist. Die meisten Dämonen waren früher sterblich, aber nicht alle waren (oder sind) intelligente Lebensformen.\r\nUm ein Dämon zu werden, muss ein Wesen mit dämonischer Energie gesättigt werden. Wie die Existenz der Dämonen ohne Bewusstsein schon vermuten lässt, sind die Wünsche eines Wesens nicht von Belang in diesem Vorgang. Ob das Wesen dies möchte oder nicht, es kann in einen Dämon verwandelt werden. Eine solche Verwandlung ändert das Wesen grundlegend, es behält normalerweise nur wenig oder gar nichts von seiner ursprünglichen Persönlichkeit. Trotzdem gibt es wenigstens einen Dämon, der bisher sehr viel seiner Persönlichkeit behalten konnte: [[Illidan|Illidan Sturmgrimm]].\r\nKeine Abhandlung über Dämonen könnte vollständig sein, wenn sie nicht [[Sargeras]], den dunklen [[Titanen]] erwähnen würde. Über die Jahrtausende hat er unzählige Wesen in Dämonen verwandelt, damit sie sich seiner [[Brennende Legion|Brennenden Legion]] anschließen und auf sein Ziel hinarbeiten: die Zerstörung des Universums, welches er als grundlegend fehlerhaft bezeichnet. Die [[Brennende Legion|Legion]] hat unzählige Welten verwüstet, um seine düsteren Pläne durchzuführen. Allerdings war [[Sargeras]] nicht der einzige Schöpfer der Dämonen und es gibt auch Dämonen, die nicht mit der [[Brennende Legion|Legion]] zusammenarbeiten. Auch hier ist [[Illidan]] ein Bespiel dieser Ausnahmen.\r\nSeit dem Tod des [[Magier|Zauberers]] [[Medivh]], der zum Todeszeitpunkt von [[Sargeras]]' Geist besessen war, wurde dieser nicht mehr gesehen. Doch die Gier nach Leben und [[Magie]] kann nie lange gesättigt bleiben. Um es genau zu sagen, die angeborene Grausamkeit eines Dämons lässt seine vorübergehende Sättigung immer nur vorübergehend sein. Deshalb hinterlassen die Dämonen Zerstörung entlang ihres Weges, ob sie nun zur [[Brennende Legion|Legion]] gehören oder auch nicht.",},
			["Dämonenhügel"] = { content = "Im Süden von [[Eschental]] gibt es ein Gebiet im [[Nachtweisenwald]], das seit kurzer Zeit \"Dämonenhügel\" genannt wird. Es ist sehr traurig zu sehen, wie die [[Dämonen]] auf ihm herumkrabbeln und ihre Verderbnis verbreiten. Es ist ein Überbleibsel der [[Brennende Legion|Brennenden Legion]], in den Regionen, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind. Sie sind von der Macht, die einst in [[Azeroth]] eingedrungen ist, übriggeblieben. Diese Überreste der [[Brennende Legion|Brennenden Legion]] haben auch Überfälle auf das [[Holzfällerlager des Kriegshymnenklans]] durchgeführt, doch ohne Anführer ist der Rest der [[Dämonen]] nur ein Haufen geistloser Untiere. \r\nEiner der [[Dämonen]] trägt die Teuflische Pläne bei sich, welche überraschenderweise in der Allgemeinsprache verfasst wurde. Darin werden [[Diathorus]] und [[Gorgannon]] erwähnt, zwei berüchtigte [[Schreckenslords]], die die [[Dämonen]] in dieser Gegend anführen. Die Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf [[Waldeslied]] im Norden, wo gerade eine neue [[Draenei]]siedlung errichtet wird und auch auf den [[Splitterholzposten]] im Nordwesten.",},
			["Dämonenjäger"] = { content = "Dämonenjäger sind dunkle, schattenhafte [[Krieger]], die vom größten Teil der [[Nachtelfen]] gemieden werden. Vor langer Zeit schlossen sie einen Pakt, die Kräfte des Chaos mit dessen eigener schrecklicher Macht zu bekämpfen. In einem ihrer Rituale blenden sich diese geheimnisumwitterten [[Krieger]] selbst, um so ihre \"Spektralsicht\" zu entwickeln, durch die sie [[Dämonen]] und [[Untote]] besser erkennen können. Bei Kämpfen benutzen sie dämonisch aufgeladene Kriegsklingen und beschwören sogar dämonische Energien herauf, um ihre ungeheuren Kampffertigkeiten noch zu steigern. Doch obwohl man die Dämonenjäger zu den mächtigsten [[Krieger]]n der [[Nachtelfen]]-Gesellschaft zählt, werden sie wegen ihres selbstlosen Pakts mit der Dunkelheit doch stets verteufelt und missverstanden. Einer der berühmtesten Dämonenjäger war [[Illidan]].\r\n'''Hintergrund'''\r\nIllidan Sturmgrimm ist zweifelsohne der bekannteste Dämonenjäger und war auch der Erste ihrer Art. Selbst sein eigener Bruder erkannte sein Opfer nicht an und sperrte ihn für 10.000 Jahre lang ein, da er sich mit den dunklen Mächten eingelassen hatte. Illidans Fall ist jedoch einzigartig. Sargeras selbst, Herrscher über die Brennende Legion, brannte Illidan die Augen aus, und so erhielt Illidan die Sicht die ihm erlaubte, Dämonen sowie magisch begabte Sterbliche zu erkennen. Zusätzlich überzog Sargeras Illidans Körper mit Tätowierungen, welche seine arkanen Fähigkeiten stärken sollten. Später ging eine Gruppe von Nachtelfen, Illidans Beispiel folgend, einen Pakt ein, die Mächte der Legion gegen diese anzuwenden. Natürlich konnten sie ihre Macht nicht auf dieselbe Art und Weise erlangen, wie es Illidan getan hatte, doch sie fanden andere Lösungen. Seitdem haben auch andere Nachtelfen sowie einige wenige Mitglieder anderer Völker, diesen Weg eingeschlagen. Sie nahmen die dämonische Essenz in sich auf und nutzen diese, um die Diener der Legion zu zerstören. \r\n'''Entwicklung und Fähigkeiten'''\r\nDämonenjäger verfügen über eine Reihe von Fähigkeiten, welche ihnen dabei helfen, die Dämonen zu vernichten. Sie meiden die schwere Rüstung, da sie Beweglichkeit und Schnelligkeit im Kampf schätzen. Je mehr Macht ein Dämonenjäger erhält, desto mehr verändert er sich und sein Erscheinungsbild wird zunehmendst dämonischer. Die Veränderungen sind unterschiedlich, und reichen von glühenden Augen bis hin zu schwarzem Blut. Wenn ein Dämonenjäger seine Ausbildung vollendet hat, ist er nur mehr eine dunkle Vision seines früheren Selbst. Obschon die Veränderungen weder seine Persönlichkeit noch seine Zugehörigkeit verändern (laut den Dämonenjägern zumindest), sind die physischen Änderungen umso stärker ausgeprägt. Die vollendete Form eines Dämonenjägers ist, selbst zum Dämon zu werden. Diese dämonische Form ist natürlich auch unterschiedlich je nach Persönlichkeit, einige Merkmale sind glühende rote Augen, Hörner, Flügel, Hufe, ein spitzer Schwanz, eine dunkle Haut und ähnliche Äusserlichkeiten. Dämonenjäger vermögen die Energie der Dämonen abzusaugen, um ihre eigene wieder aufzufüllen und benutzen hauptsächlich Arkan- und Feuermagie. Schattenmagie ist eher selten. Andere Energien wurden nicht bestätigt. Zudem vermag der Dämonenjäger die chaotische Magie in seiner Waffe zu bündeln, um stärker zu werden. Von einigen Dämonenjägern ist zudem bekannt, dass sie die Fähigkeit besitzen, sich mit einem Feuerschild zu schützen. Bei der sogenannten „Metamorphose“ können sich die Dämonenjäger für eine gewisse Zeit in ihren inneren Dämonen verwandeln. \r\n'''Völker und Initiation'''\r\nDa die Tradition der Dämonenjäger eine nachtelfische ist, sind die meisten Dämonenjäger Nachtelfen. Einige Blutelfen haben sich ebenfalls für diesen Weg entschieden, aus Rache für ihr zerstörtes Reich. Obschon prinzipiell jedes Volk zum Dämonenjäger werden kann, gibt es über solche Ausnahmen keinerlei Berichte. Jedes Mitglied eines andern Volkes, welches sich zu diesem Weg berufen fühlt, muss einen nacht- oder blutelfischen Dämonenjäger aufsuchen, welche den zukünftigen Dämonenjäger bei der Initiation unterstützen. \r\nZu den Ritualen zählen einen Dämonen gefangennehmen und ihn zu opfern, um einen Teil seiner Macht in sich aufzunehmen. Als Teil der Zeremonie muss sich der Anwärter mittels einer magischen Klinge die Augen ausbrennen, damit der dämonische Geist nicht mehr aus seinem Körper entweichen kann. Die meisten Dämonenjäger verstecken ihre derart verstümmelten Augen anschliessend hinter einer Augenbinde. Im Gegenzug für dieses Opfer erhält der Dämonenjäger die Fähigkeit, die Welt ohne Augen zu sehen - Kreaturen sind nicht viel mehr als schimmernde Kugeln vor einem grauen Hintergrund. Dämonische Macht allerdings brennt lichterloh, so dass sie der Dämonenjäger sehr einfach erkennen kann. \r\n'''Ausrüstung und Waffen'''\r\n \r\nObschon die genaue Ausrüstung von Dämonenjäger zu Dämonenjäger unterschiedlich sein kann, so gibt es doch einige Gemeinsamkeiten. Die Augenbinde wird von quasi jedem Dämonenjäger dazu benutzt, seine verstümmelten Augen zu verbergen, und ist zumeist aus teurem Stoff hergestellt. Eine weitere Gemeinsamkeit ist die Angewohnheit der männlichen Dämonenjäger, mit nacktem Oberkörper zu kämpfen, um die Wichtigkeit der Beweglichkeit darzustellen. Generell lehnen sie daher schwere Rüstung ab. Die wenigen weiblichen Dämonenjäger halten es ähnlich, und tragen am Oberkörper gerademal das Nötigste. Zumeist bevorzugen die Dämonenjäger Stoff oder Leder, Platte tragen sie selten bis gar nicht. Als Kontrast zu ihrer kargen Rüstung benutzen die Dämonenjäger grosse mächtige Kriegsgleven, welche den Zwillingsklingen von Azzinoth, welche Illidan trägt, ähneln. Obschon diese Tendenz nirgends deutlich erklärt wird, so gibt es doch einige mögliche Erklärungsversuche. Zum einen könnte diese Art der Waffen einfach zur Tradition geworden sein, indem die späteren Dämonenjäger den Ersten ihrer Art imitierten. Eine weitere Erklärung wäre, dass diese Waffenart bevorzugt von jenen Dämonen getragen wurde, welche die Dämonenjäger bei ihrem Aufnahmeritual besiegen mussten. Die Grösse der Waffen und die Tatsache, dass sie gebogen sind, ermöglichen dem Dämonenjäger darüberhinaus einen leichten Umgang mit diesen schweren Waffen. Zudem ist es im Bereich des Möglichen, dass genau diese spezielle Form besonders geeignet ist, um von magischen Energien durchflossen zu werden.\r\n'''Fähigkeiten:''' \r\n \r\nDämonenjäger haben die Fähigkeit entwickelt, sich selbst in Flammen zu setzen, um Feinde in ihrer Nähe für eine gewisse Zeit zu verbrennen. Durch die Metamorphose kann sich der Dämonenjäger letztendlich selbst in einen Dämon verwandeln.",},
			["Dämonenkasten"] = { content = "Der '''Dämonenkasten''' ist ein Artefakt und befindet sich in Desolace in der [[Festung Donneraxt]]. Darin liegt die mächtige [[Hand von Iruxos]]. Zugang zum Kasten erlangt man nur über den roten Kristall in der Festung.",},
			["Dämonensaat"] = { content = "Die '''Dämonensaat''' wird im [[Brachland]] hoch über dem [[Glutnebelgipfel]] aufbewahrt und ist ein mächtiges Werkzeug der [[Brennenden Legion]], welches dort von den Anhängern der [[Brennende Klinge|Brennenden Klinge]] gehütet wird.",},
			["Dämonensturz"] = { content = "Im Süden von [[Eschental]] gibt es ein Gebiet im [[Nachtweisenwald]], das seit kurzer Zeit \"'''Dämonensturz'''\" genannt wird.",},
			["Dämonischer Seher"] = { content = "[[Apotheker Antonivich]] auf der [[Höllenfeuerhalbinsel]] erfand ein Gerät, mit dem man Teufelsmagie analysieren kann. Innerhalb des Sehers steckt ein Wesen von höchster Intelligenz, das einige, exzentrische Bedürfnisse hat. Um den Dämonischen Seher zu besänftigen, muss man [[Orcs]] töten, insbesondere die [[Orcs der Zerschmetterten Hand]], denn der Seher verlangt ihre Seelen.\r\n==Dämonische Seherauswertung==\r\nAntonivich,\r\nals Erstes möchte ich Euch wissen lassen, dass Euer letzter Agent, seine Pflichten sehr zu meiner Zufriedenheit erfüllt hat. Ich habe Besitz von seinem Körper ergriffen und schreibe dies hier mit seiner eigenen Hand. Es bereitet mir großes Vergnügen und ich hoffe, dass ich eines Tages das Glück haben werde, von Euch, mein mächtiger Apotheker, Besitz ergreifen zu können!\r\nSo, hier nun der von Euch angeforderte Bericht: die [[Höllenfeuerzitadelle]] wird von einem Dämon heimgesucht, der stärker als alles ist, dem ich je begegnet bin. Ich kann mir vorstellen, dass [[Mannoroth]], der ruhmreiche [[Grubenlord]] des Dritten Krieges, über die selbe Macht verfügte, es gibt jedoch nur Wenige. Ich spüre allerdings, dass diesen Dämon eine Art Zwang umgibt. Es würde mich nicht verwundern, wenn er gegen seinen Willen handelt, sich in Gefangenschaft befindet oder sogar noch einer größeren Macht unterliegt. Die Zeit wird es zeigen...\r\nKommt Zeit, kommt Rat... ich spüre bereits, wie sich das Schicksal der Höllenfeuerzitadelle wendet. Ihr, die Einwanderer von Azeroth, diesem grünen, üppigen, entsetzlichen Ort, an dem sich Wesen wie ich selbst in einer Hölle des Lichts und Lebens wiederfinden, werden das Gesicht des Dämonen sehen. Ihr werden noch erkennen, dass die Schrecken der Zitadelle nur die Spitze, wenn Ihr mir diese Metapher gestattet, eines gewaltigen Eisbergs sind. Oh, welch glorreiche Schlachten stehen uns bevor! Ich wünschte, ich könnte den dort gesäten Schmerz und die Angst selbst miterleben!\r\nNun gut, genug meiner Ausschweifungen, sinnt ein wenig über meine Worte nach, mein lieber Apotheker: Euer Körper mag vielleicht tot sein, Antonivich, Eure Seele ist jedoch unversehrt. Ich werde diese Seele an mich reißen und mich an dem Tag an ihr laben, an dem Eure Verteidigung versagt! Ich werde bis zum jüngsten Tag und länger warten, wenn es sein muss, aber... Ihr werdet mir gehören!\r\nGuten Abend,\r\n-D",},
			["Düsterbruch"] = { content = "Vor fast zwölftausend Jahren errichtete eine geheime Sekte [[Nachtelfen|nachtelfischer]] Zauberer die uralte Stadt [[Eldre'Thalas]], um die wertvollsten Geheimnisse von [[Königin Azshara]] zu schützen. Selbst die Ruinen der Stadt, die während der Spaltung der Welt verwüstet wurde, sind immer noch äußerst beeindruckend und ehrfurchtgebietend. In den drei Flügeln der Stadt, die heute nur noch als der Düsterbruch bekannt ist, haben sich inzwischen die seltsamsten Kreaturen niedergelassen – besonders die spektralen [[Hochgeborene]]n, die hinterhältigen [[Satyrn]] und die brutalen [[Oger]]. Nur die mutigsten Abenteurer sollten sich dieser verfluchten Ruine nähern und die unglaublichen Schrecken herausfordern, die hinter den verfallenen Mauern lauern.\r\n===Athenaeum===\r\nDas Athenaeum ist die Bücherei Düsterbruchs. Das Siegel des Athenaeums schützt die Folianten hier und verhindert, dass unerlaubt in ihnen gelesen wird. Verlorene Bücher des Athenaeums sind unter anderem: \r\n'''NSC's'''\r\n===Düsterbruch: Nord===\r\nDer Nordflügel ist der Regierungssitz des [[König Gordok|Ogerkönigs Gordok]]. Als Gegner trifft man hier überwiegend [[Oger]], die aber auch einige tierische und dämonische Begleiter haben können. [[Hauptmann Krombruch]] hat noch eine offene Rechnung und will die Stulpen der Gordokmacht wiedererlangen. Krombruch zufolge sagen die \"Alte Zeit Geschichten\", dass [[Prinz Tortheldrin]] sie hat.\r\n* [[König Gordok]]\r\n* [[Hauptmann Krombruch]]\r\n* [[Wache Fengus]]\r\n* [[Wache Mol'dar]]\r\n* [[Wache Slip'kik]]\r\n===Düsterbruch: Ost===\r\nIm Ostteil der zerstörten Stadt, in dem sich der Schrein von Eldretharr befindet, wird auch das Wucherborkenviertel genannt. Hier erstreckt sich das Herrschaftsgebiet von [[Alzzin der Wildformer |Alzzin dem Wildformer]], in dessen Nähe sich die korrumpierte Frucht des Gedeihens - die Teufelsranke - befindet. In diesem Teil erhält man auch den [[Mondsichelschlüssel]], den man zum Betreten der anderen beiden Flügel braucht. Bewohnt ist er hauptsächlich von Dämonen und Pflanzen-[[Elementare]]n. Das geronnene Blut der [[Satyre der Wildhufe]], die hier hausen, ist fähig die Splitter von [[Hederine]] zusammenhalten und das Kristallgefängnis mit Energie versorgen.\r\n* [[Alzzin der Wildformer]]\r\n* [[Hydrobrut]]\r\n* [[Immol'thar]]\r\n* [[Lethtendris]]\r\n* [[Lord Hel'nurath]]\r\n* [[Pusillin]]\r\n* [[Tendris Wucherborke]]\r\n===Düsterbruch: West===\r\n* [[Revanchion]] - Ein Geist im westlichen Abschnitt des Düsterbruchs während der [[Invasion der Geißel]].",},
			["Düstermarschen"] = { content = "Die '''Düstermarschen''' sind ein sumpfiges Gebiet im Südosten von [[Kalimdor]]. Eine Straße führt nach Westen in das [[Brachland]]. Die [[Horde]] und die [[Allianz]] wahren hier offiziell einen brüchigen Waffenstillstand, doch beide Seiten liefern sich Scharmützel und heimliche Angriffe. Die [[Horde]] will dafür sorgen, dass sie stets die Oberhand behält und jetzt haben sie die Chance, genau das zu tun. Doch Spitzel der [[Allianz]] haben unterdessen Stellungen östlich des Dorfes [[Brackenwall]] bezogen, spionieren das Dorf aus und melden die Bewegungen [[Theramore]], was die [[Orcs]] nicht dulden können. Es ist ein ständiger Kampf, in den Marschen präsent zu bleiben, aber durch die Kraft der Entschlossenheit konnte die [[Allianz]] mehrere Wachtürme in diesem Gebiet zur Verteidigung halten. Abgesehen von [[Oger]]n, [[Orcs]] und [[Murlocs]] wimmelt es im südlichen Teil des Sumpfs von [[Schwarzer Drachenschwarm|schwarzen Großdrachen]].\r\n==Orte==\r\n* [[Aschenschwinges Bau]]\r\n* [[Brackenwall]]\r\n* [[Dustwallow Bay]]\r\n* [[Gasthaus \"Zur süßen Ruh\"]]\r\n* [[Hexensumpf]]\r\n* [[Insel Alcaz]]\r\n* [[Morastwinkel]]\r\n* [[Ruinen der Steinbrecher]]\r\n* [[Späherwacht]]\r\n* [[Tabethas Hütte]]\r\n* [[Theramore]]\r\n* [[Verlassene Wacht]]\r\n===Drachensumpf===\r\n[[Onyxia]] hat im Drachensumpf einen Hort angelegt und ihre Brut wurde über das Drachendüster verstreut.\r\n===Flammenbau===\r\nDer Flammenbau befindet sich südöstlich des Übergangs zum [[Brachland]]. \r\n===Graunebelhöhlen===\r\nGraunebelspinnen leben westlich vom [[Hexensumpf]] in den Graunebelhöhlen.\r\n===Nordwacht===\r\nDer Turm befindet sich im Nordosten von [[Brackenwall]].",},
			["Düsterwolkengipfel"] = { content = "Der Düsterwolkengipfel ist eine isolierten Felsnadel in [[Tausend Nadeln]], wo die [[Tauren]] ihre Toten beerdigen. \r\nHier befindet sich auch das hochheilige Feuer des Lebens. Wirft man das aufbereitete und geläuterte Brandpulver in das hochheilige Feuer, erscheint die [[Windnatter]] [[Arikara]]. Die [[Tauren der Grimmtotem]] unter Führung von [[Arnak Grimmtotem]] planen hier jedoch etwas, das niemand wissen soll. Drei Agenten unbekannter Herkunft wurden gesehen, wie sie die [[Tauren der Grimmtotem|Grimmtotem]] in den vergangenen Wochen besuchten. Die [[Tauren]] aus dem [[Freiwindposten]] haben entdeckt, dass diese geheimnisvollen Botschaften im Düsterwolkengipfel in verschiedenen Truhen verwahrt werden.",},
			["Eber"] = { content = "Die bulligen '''Eber''' gehören zu den Wildtieren und sind sowohl in [[Azeroth]] als auch der [[Scherbenwelt]] weit verbreitet. Sie leben in bergigen oder felsigen Regionen und können dank ihrer Angewohntheit, so ziemlich alles zu fressen, auch in karger Wildnis überleben. Sie verfügen über ein aggressives und angriffslustiges Naturell, so dass man sie gar nicht mehr reizen muss. Das sind sie schon, auch ohne dass man nachhilft. \r\n==Eber als Begleiter==\r\nEber als Wildtiere sind zähmbar und so findet man sie ab und an als Gefährten der [[Jäger]]. Das hat durchaus Tradition, denn z.B. werden Kampfeber in [[Mulgore]] von den niederträchtigen [[Stacheleber der Borstennacken|Stachelebern der Borstennacken]] in der [[Dornrankenklamm]] abgerichtet.\r\n==Eber als Fleischlieferanten==\r\nEber dienen auch häufig als Fleichlieferanten für Köche. So brauchen die [[Zwerge]] in [[Loch Modan]] z.B. Ebergedärme für die Pelle der berühmten Thelsamar-Blutwurst und die [[Tauren]] in [[Mulgore]] bereiten aus den Schnauzen und Flanken der Kampfeber einen Eintopf für ihre Jungen zu.\r\n==Dämonische Eber==\r\nEinige Eber zählen nicht zu den Wildtieren, sondern zu den [[Dämonen]]. Hierzu gehören z.B. die [[Hölleneber]], die man auf der [[Höllenfeuerhalbinsel]] findet.",},
			["Echokammmine"] = { content = "===Echokammmine===\r\nDie koboldverseuchte Echokammmine liegt im Norden der [[Abtei von Nordhain]]. Je länger die [[Kobolde von Nordhain]] sich ungehindert in dieser Mine aufhalten können, umso festere Wurzeln fassen sie in [[Nordhain]] und das Koboldproblem ist größer als die [[Menschen]] dachten, denn eine Gruppe Koboldtagelöhner hat ihr Lager auch bereits vor der Mine aufgeschlagen.",},
			["Echsenkessel"] = { content = "Im [[Schlangensee]] im Norden der [[Zangarmarschen]] befindet sich ein riesiger Abflusstunnel, der zum Instanzenkomplex '''Echsenkessel''' führt. Wie die anderen Instanzgruppen der [[Scherbenwelt]] ist auch diese wieder in vier Instanzen mit unterschiedlichen Stufenanforderungen unterteilt.\r\n\"Wer auch immer das Wasser kontrolliert, kontrolliert die Scherbenwelt.\" Diese Regel wurde von Fürst [[Illidan Sturmgrimm]] an seinen getreusten Leutnant weitergegeben, [[Lady Vashj]]. Kurz nach dem Dritten Krieg rief Illidan die [[Naga]] zur Hilfe und eine Gruppe Naga unter dem Kommando von [[Lady Vashj]] folgte diesem Ruf. Seit dieser Zeit hat Lady Vashj bedingungslose Hingabe zu Illidan gezeigt. Jetzt überwacht die Nagahexe von ihrem Sitz in der [[Höhle des Schlangenschreins]] aus sorgsam die Operationen im Echsenkessel. Lady Vashj fühlt sich in der feuchten Umgebung des Staubeckens wesentlich wohler als hinter den kalten Steinwänden des [[Der Schwarze Tempel|Schwarzen Tempels]] und wirft ein wachsames Auge auf ihre Untergebenen, wobei sie persönlich die Aufsicht über die Entwässerung der [[Zangarmarschen]] führt.\r\n'''Quelle:''' \r\n==Teilbereiche==\r\n* [[Sklavenunterkünfte]] (62-64)\r\n* [[Tiefensumpf]] (63-65)\r\n* [[Dampfkammer]] (70-72)\r\n* [[Schlangenschrein]] (70 - Schlachtzug)",},
			["Echsenkessel: Dampfkammer"] = { content = "Die Dampfkammer ist ein Teil des [[Echsenkessel]]s in den [[Zangarmarschen]] und wird von [[Kriegsherr Kalithresch]] beherrscht.\r\nAusladende Pumpensysteme arbeiten Tag und Nacht im gesamten [[Echsenkessel]]. Sie wurden von den Naga und ihren Dienern erbaut, um die [[Zangarmarschen]] trocken zu legen. Im Zentrum dieses Industriekomplexes liegt die Dampfkammer, wo arkane Technologie die Maschinen antreibt, welche bei der Verarbeitung des Wassers zum Einsatz kommen. Um die Ingenieure zu leiten, die die Maschinen bedienen und warten, hat [[Lady Vashj]] den namhaften [[Robogenieur Dampfhammer]] angeheuert, einen begabten, gnomischen Techniker, dessen Krankheit seinen Geisteszustand in Mitleidenschaft gezogen hat, jedoch nicht seine verbissene Hingabe zu seinem Handwerk. Bei der strategischen Bedeutung der Dampfkammer ist es kein Wunder, dass das Nervenzentrum des [[Echsenkessel]]s von elitären Nagakriegern verteidigt wird. Deren Anführer, [[Kriegsherr Kalithresh]], verfügt über eine unbeirrbare Ergebenheit zu [[Lady Vashj]], die nur noch von seiner Tapferkeit im Kampf übertroffen wird. Er zeigt keine Gnade gegenüber jedem, der es wagt, die Sicherheit des Staubeckens zu gefährden. \r\n===Schlüsselfragment===\r\n[[Erzmagier]] [[Khadgar]] in [[Shattrath]] hat das zweite Fragment des Schlüssels nach [[Karazhan]] am Boden des [[Schlangensee]]s versteckt, noch lange bevor er so hieß. Der gigantische Ablauf, der dort installiert wurde, nachdem die [[Naga]] den Ort in Beschlag genommen hatten, hat den Behälter wahrscheinlich in die Tiefen des [[Echsenkessel]]s gesogen.\r\n==Bosse==\r\n* [[Wasserbeschwörerin Thespia]] \r\n* [[Robogenieur Dampfhammer]]\r\n* [[Kriegsherr Kalithresch]]",},
			["Echsenkessel: Schlangenschrein"] = { content = "Der Schlangenschrein ist ein Teil des [[Echsenkessel]]s in den [[Zangarmarschen]] und Sitz von [[Lady Vashj]].\r\n\"Wer auch immer das Wasser kontrolliert, kontrolliert die Scherbenwelt.\" Diese Regel wurde von Fürst [[Illidan Sturmgrimm]] an seinen getreusten Leutnant weitergegeben, [[Lady Vashj]]. Kurz nach dem Dritten Krieg rief Illidan die Naga zur Hilfe und eine Gruppe Naga unter dem Kommando von Lady Vashj folgte diesem Ruf. Seit dieser Zeit hat Lady Vashj bedingungslose Hingabe zu Illidan gezeigt. Jetzt überwacht die Nagahexe von ihrem Sitz in der Höhle des Schlangenschreins aus sorgsam die Operationen im Echsenkessel. Lady Vashj fühlt sich in der feuchten Umgebung des Staubeckens wesentlich wohler als hinter den kalten Steinwänden des Schwarzen Tempels und wirft ein wachsames Auge auf ihre Untergebenen, wobei sie persönlich die Aufsicht über die Entwässerung der [[Zangarmarschen]] führt. Ob ihre Pflichtergebenheit jedoch Illidan alleine gilt, bleibt abzuwarten.\r\n==Bosse==\r\n* [[Hydross der Unstete]]\r\n* [[Grauen aus der Tiefe]]\r\n* [[Morogrim Gezeitenwandler]]\r\n* [[Tiefenlord Karathress]]\r\n* [[Leotheras der Blinde]]\r\n* [[Lady Vashj]]",},
			["Echsenkessel: Sklavenunterkünfte"] = { content = "Die Instanz der '''Sklavenunterkünfte''' liegt in den [[Zangarmarschen]] und ist neben dem [[Tiefensumpf]] eine der zwei Fünf-Spieler-Instanzen des [[Echsenkessel]]s. Sie ist die leichtere von beiden und eignet sich bereits für Spieler ab Level 62. Doch unterschätzt die Herausforderung nicht: Die schiere Masse der Gegner und die Härte der Bosse wird euch einiges an Können und Durchhaltevermögen aberlangen.\r\n==Geschichte==\r\nDie teuflischen [[Naga]] haben vor kurzem damit begonnen, Stämme der [[Zerschlagene]]n zu versklaven, um die Arbeitsleistung der Naga zu verbessern und ihre Ziele in der [[Scherbenwelt]] voranzutreiben. Fast der komplette Stamm der [[Zerschlagene der Ödniswandler|Zerschlagenen der Ödniswandler]] wurde gefangen genommen und gezwungen, als Sklaven in den trostlosen Unterkünften des [[Echsenkessel]]s Tag und Nacht unter dem Joch ihrer ruchlosen Nagaherren zu schuften. Einige der [[Zerschlagene]]n haben sich scheinbar mit ihrem Schicksal abgefunden. Andere beten, dass eine außen stehende Partei eingreift und ihnen zu einer Fluchtmöglichkeit verhilft. Und wieder andere, respektlose Stammesangehörige, die keine Alternative sehen, haben einen Weg gefunden, die Situation zu ihrem Vorteil zu nutzen. [[Mennu der Verräter]] ist einer davon: ein ehemaliger Sklave, der seine [[Draenei]]brüder verriet und so die Gunst seiner Nagaherren erlangte. Trotz ihrer Differenzen gibt es eine Lektion, welche die geknechteten Mitglieder der [[Zerschlagene der Ödniswandler|Zerschlagenen der Ödniswandler]] nur allzu gut gelernt haben: Diejenigen, die das Pech hatten, sich in den Sklavenunterkünften des [[Echsenkessel]]s wiederzufinden, finden nicht immer einen Weg nach draußen. \r\n==NSC==\r\n* '''Nar'biss der Ketzer''' - Nar'biss der Ketzer ist ein [[Naga Myrmidone]], der in den Sklavenunterkünften eingesperrt wurde. Die anderen Naga fürchten seine Worte und wollen ein Exempel an ihm statuieren. Sie verhöhnen den einen wahren Gott, [[Neptulon]]. Doch Nar'biss glaubt, die Vergeltung ist nah. Die glohrreiche Hand des Gezeitenjägers wird einess Tages die Ungläubigen hinwegfegen, wie ein Herbststurm lose Blätter.\r\n==Bosse==\r\n* [[Mennu der Verräter]]\r\n* [[Rokmar der Zerquetscher]]\r\n* [[Quagmirran]]\r\n'''Quelle:'''",},
			["Echsenkessel: Tiefensumpf"] = { content = "Der Tiefensumpf ist die zweite 5er-Instanz im [[Echsenkessel]] in den [[Zangarmarschen]]. Im Gegensatz zu den [[Sklavenunterkünfte]]n hat man es hier nicht mit vielen einzelnen Gegnern zu tun, sondern mit kleinen Gruppen und entsprechend harten Kämpfen.\r\nDieses belebte Ökosystem tief im Inneren des [[Echsenkessel]]s zeigt die Höhlen, wie sie seit zahllosen Jahrtausenden existieren. Hier verbleiben die exotische Flora und Fauna größtenteils ungestört, selbst von den sich zunehmend ausbreitenden [[Naga]]. Viele der Bewohner der [[Zangarmarschen]] haben spekuliert, dass die Fülle gefährlicher Kreaturen in diesem Sumpfgebiet die Naga davon abhalte, langfristig Fuß zu fassen. Andere glauben, dass die gerissene [[Lady Vashj]] ganz spezielle Pläne für diese überraschend rege Gegend hat. Nur wenige Naga halten sich in diesem Sumpfgebiet auf, jedoch gedeihen andere Kreaturen wie Lauerer, [[Sumpfriesen]] und Tiefenfledermäuse in diesen Höhlen. Obwohl diese Kreaturen frei herumlaufen, haben die Naga anscheinend zumindest einen der tödlichsten Bewohner des Tiefensumpfes bezwungen: ein schreckliches, dreiköpfiges Monster namens [[Ghaz'an]]. \r\n==Personen==\r\n* '''Erdbinder Rayge''' gehört zur [[Expedition des Cenarius]] und ist ein [[Nachtelfen]] [[Druide]]. Klaue und er haben diesen Ort untersucht, als sie von [[Sumpffürst Musel'ek]] angegriffen wurden. Er wagt es nicht, sich in eine Katze zu verwandeln, da er fürchtet, auch dem Sumpffürsten in die Hände zu fallen.\r\n* '''Windrufer Klaue''' von der [[Expedition des Cenarius]] ist ein [[Tauren]] [[Druide]]. Unglücklicherweise war Klaue in der Form eines Bären, als [[Sumpffürst Musel'ek]] ihn und Erdbinder Rayge überfiel, und nun ist er das Tier des Sumpffürsten. Er findet es peinlich von einem [[Jäger]] als Tier benutzt zu werden.\r\n==Bosse==\r\n* [[Hungarfen]] \r\n* [[Ghaz'an]]\r\n* [[Sumpffürst Musel'ek]] \r\n* [[Schattenmutter]]",},
			["Echsennarbe"] = { content = "Die Echsennarbe befindet sich im [[Schattenmondtal]] direkt südwestlich von [[Dorf Schattenmond]] und nördlich vom [[Altar der Verdammnis]]. Die [[Naga]] der [[Illidari]] haben in dieser Gegend die Kontrolle über die einzige reine Wasserversorgung des [[Schattenmondtals]] an sich gerissen und verderben nun die Wasservorräte des Gebietes. Seitdem findet man um die Echsennarbe herum Ansammlungen von tosenden [[Wasserelementare]]n, die ihre Qual ins Land hinausschreien und wütend umherstreifen. Die größte Ansammlung dieser Geister findet man in der Nähe der Zisterne. \r\n==Personen==\r\n* '''Erdheilerin Wilda''' hat sich vor ein paar Tagen von den anderen Mitgliedern des [[Irdener Ring|Irdenen Rings]] getrennt und wollte der Quelle der Veränderung des Wassers, die sie spüren, auf den Grund gehen. Unglücklichweise hat man sie entdeckt und gefangen genommen.\r\n* '''Grom'tor''' ist [[Oronok]]s Erstgeborener Sohn und hat sich aufgemacht, um die Echsennarbe nach der [[Litanei der Verdammnis]] zu durchsuchen. Er ist der Krieger der Familie, jähzornig und blutdurstig... Das hat er von seiner Mutter.",},
			["Echtsilber"] = { content = "'''Echtsilber''' ist ein seltenes Erz, dem magische Eigenschaften nachgesagt werden. Es heißt auch, Echtsilber sei noch stärker und haltbarer als [[Mithril]]. Aber einige meinen, Echtsilber trage seinen Namen zu Unrecht. Echtsilber sei nicht echt.",},
			["Edwin van Cleef"] = { content = "'''Edwin van Cleef''' war ein unvergleichlicher [[Krieger]] in seinen jungen Jahren und die Jahre haben ihn offensichtlich kein bisschen verändert, denn noch immer ist er der alte Idealist und Romantiker. Doch heutzutage kümmert es ihn nicht mehr, wen er verletzt, denn die Rache hat ihn verzehrt.\r\n==Geschichte==\r\nEdwin Van Cleef war ein Meister der [[Ingenieure|Ingenieurskunst]] und maßgeblich am Wiederaufbau von [[Sturmwind]] nach dem Krieg gegen die [[Orcs]] beteiligt. Er war unter anderem der Architekt der Kathedrale in [[Sturmwind]], die noch heute den Mittelpunkt des Glaubens des Heiligen Lichtes darstellt. Der Wiederaufbau von [[Sturmwind]] war eine schier unlösbare Aufgabe, aber unter Van Cleefs Leitung wurde sie in Rekordzeit bewältigt. Viele kamen und halfen und andere sahen hier einen Neuanfang mit lukrativen Geschäftsmöglichkeiten. Dieser Wiederaufbau wurde allerdings lange Zeit von den Herrschaftshäusern übersehen. So kam es wie ein Schock über sie, als manche der Helfer nach Bezahlung und Lohn fragten. Wie gelähmt stellte man fest, dass all die Schmiede, Ingenieure und Arbeiter nicht bezahlt werden konnten. So verbannte man sie aus dem Königreich ... \r\nBetrogen und belogen von der [[Allianz]] suchten sie sich einen Anführer in Edwin Van Cleef. Er bildete dann die „Bruderschaft der [[Defias]]“. Ein Streben nach Freiheit und Gleichheit vorgebend, agieren sie jetzt von den [[Todesminen]] in [[Westfall]] aus.\r\n'''Siehe auch'''\r\n* [[Bericht über die Bruderschaft der Defias]]",},
			["Ehrenfeste"] = { content = "Direkt hinter dem [[Dunkles Portal|Dunklen Portal]] auf der [[Höllenfeuerhalbinsel]] der [[Scherbenwelt]] trifft die [[Allianz]] auf die '''Ehrenfeste'''. Es ist die erste Allianz Basis auf der [[Höllenfeuerhalbinsel]] und benötigt Hilfe im Kampf gegen die [[Horde]] und die [[Brennende Legion]]. \r\nDie Männer und Frauen der Ehrenfeste haben viel Blut vergossen aber nie aufgegeben. Dank des Nachschubs an Freiwilligen aber gibt es wieder die Hoffnung auf die Rückkehr in die Heimat. Doch auch wenn sie über die Ankunft der Neulinge glücklich sind, gibt es trotzdem Pflichten in der [[Scherbenwelt]], die zuerst erfüllt werden müssen. Die noch verbliebenen der [[Söhne Lothars]], Veteranen der [[Allianz]], die zuerst nach [[Draenor]] kamen, haben standhaft an diesem Außenposten der [[Höllenfeuerhalbinsel]] festgehalten. Die Armee von [[Sturmwind]] und [[Eisenschmiede]] haben sich ihnen jetzt angeschlossen.\r\nDer Anführer der Ehrenfeste ist Truppenkommandant [[Danath Trollbann]], einer der [[Söhne Lothars]]. Mit der Ankunft von [[Feldkommandeur Romus]] und seinen Streitmächten sind die [[Allianz]] und ihre [[Draenei]]-Freunde mutiger geworden und wandeln alle alten [[Draenei]]-Ruinen von der Ehrenfeste bis [[Shattrath]] in Heerlager um. \r\n==PVP==\r\nDie [[Höllenfeuerzitadelle]] steht im ständigen Kampf mit den Streitmächten der [[Allianz]]. Die Soldaten der [[Allianz]] halten sich wacker, aber sie können keinen richtigen Angriff gegen die [[Orcs]] starten. Um dies zu tun, müssen sie weiter vorrücken. Ihre Späher haben drei Befestigungsanlagen in der Nähe der [[Höllenfeuerzitadelle]] entdeckt, die es zu sichern gilt. Auch wenn das [[Dunkle Portal]] wieder offen ist, könnte der Kampf noch andauern und daher ist auch jede der Befestigungsanlagen wichtig. Nur wer die Kontrolle über den Rundblick, das Station und die Trümmerbastion hat, hat auch die Herrschaft über die [[Höllenfeuerhalbinsel]].\r\n==Persönlichkeiten==\r\n* [[Arator der Erlöser]]\r\n* [[Danath Trollbann]]\r\n* [[Turalyon]]\r\n* [[Vater Malgor Devidicus]]\r\n'''Sonstige'''\r\n* '''Anachoret Barada''' - Der [[Draenei]] Meister Anachoret Barada versucht verzweifelt, [[Oberst Jules]] zu exorzieren und braucht dafür einen Gehilfen. So ein Gehilfe muss allerdings gut vorbereitet sein. \r\n* '''Dumphry''' - Dumphry ist ein Großmeisterschmied und wird die Sicherheit der Ehrenfeste nicht dem Zufall überlassen, doch die Bäume sind hier knapp und die Minen voller Legionsabschaum. Zudem gehen ihm die Vorräte aus. \r\n* '''Klatu''' - Baradas Gehilfe Klatu befindet sich ein einem Raum über dem Gasthaus der Ehrenfeste und sucht seine Gebetsperlen. Er hat sie im Hof der Ehrenfeste verloren und glaubt, dass Fei-Fei der Hund sie gestohlen und verbuddelt hat. \r\n* '''Marschall Isildor''' - Marschall Isildor freut sich immer, einen weiteren Rekrut aus der Heimat zu sehen.\r\n* '''Oberst Jules''' - Oberst Jules ist [[Korporal Eisengrat]]s befehlshabender Offizier. Er wurde während des Kampfes beim [[Außenposten von Gol'gaz]] von einer dämonischen Verderbnis befallen und sein Zustand wird immer schlechter. Sein verwirrter Geist sucht nach Frieden und ein Teil des Weges dazu ist der Weg der Rache. Barada fürchtet, dass man ihm nicht mehr helfen kann, wenn man Ihn nicht bald von seiner Verderbnis heilt.\r\n* '''Sid Limbardi''' - Vor nicht allzu langer Zeit hatte Gastwirt Sid Limbardi einige Probleme mit [[Arakkoa]]banditen. Sie haben viele der Versorgungskarawanen überfallen, weswegen er ein paar Zwerge angeheuert hat, die sich um sie kümmern sollten. Es waren Brüder, wobei [[Gremni Langbart]] der Älteste von ihnen war. Sie sind losgezogen und nie zurückgekehrt. Die verrückten Zwerge haben mehr Bier als Essen oder Munition eingepackt.",},
			["Eine neue Generation"] = { content = "=== Geschichte der Allianz===\r\n'''Eine neue Generation'''\r\nJahre vergingen, in denen die Spannungen nachließen und Frieden in [[Lordaeron]] herrschte. König [[Terenas Menethil]] und [[Erzbischof Alonsus Faol]] arbeiteten unermüdlich daran, das Königreich neu aufzubauen und die verbliebenen Nationen der Allianz zu unterstützen. Das südliche Königreich Azeroth erlebte eine neuerliche Blüte und konnte sich unter der weitblickenden Herrschaft von [[König Wrynn]] wieder als militärische Großmacht etablieren. [[Uther Lichtbringer]], der oberste Herrscher des [[Paladin]]-Ordens, wahrte den Frieden in Lordaeron, indem er zivile Dispute schlichtete und Aufstände im ganzen Reich im Keim erstickte. Admiral [[Daelin Prachtmeer]], dessen mächtige Flotten die Handelswege beschützten und Piraten und Marodeure jagten, sorgte für Recht und Ordnung auf den Meeren. Doch es waren die Taten einer neuen Heldengeneration, die die Phantasie der Bevölkerung anspornten.\r\n[[Arthas]], der einzige Sohn von König Terenas, war zu einem starken, selbstbewussten jungen Mann herangewachsen. Der junge Prinz wurde von [[Muradin Bronzebart]] – dem Bruder des Königs [[Magni Bronzebart]] von [[Eisenschmiede]] – zum Krieger ausgebildet und trotz seiner Jugend als einer der besten Schwertkämpfer in ganz Lordaeron betrachtet. Bereits mit neunzehn Jahren wurde Arthas in den [[Orden der Silberhand]] unter dem Befehl von Lord Uther aufgenommen. Der gütige Uther, der jahrelang wie ein Bruder für König Terenas gewesen war, sah den Prinzen mehr als bevorzugten Neffen denn als Schüler. Aller Sturköpfigkeit und unterschwelligen Arroganz zum Trotz, konnte niemand Arthas‘ Tapferkeit und Zähigkeit bestreiten. Als Kriegsmeuten der Trolle von [[Zul'Aman]] die Siedlungen an der Grenze zu [[Quel'Thalas]] überfielen, brachte Arthas die Wilden rasch zur Strecke und machte ihrem wüsten Treiben ein Ende. \r\nDas Volk von [[Lordaeron]] jedoch war trotz dieser Heldentaten mehr am Privatleben des jungen Prinzen interessiert. Gerüchte über eine zarte Romanze zwischen Arthas und Lady [[Jaina Prachtmeer]] machten die Runde und versetzten das Königreich in helle Aufregung. Jaina war die jüngste Tochter von Admiral [[Daelin Prachtmeer]] und seit ihrer Kindheit mit Arthas befreundet. Doch die wunderschöne und schüchterne junge Frau war gleichzeitig auch die Vorzeigeschülerin des [[Kirin Tor]] – des Rates der Zauberer von Dalaran. Man betrachtete die von dem hoch angesehenen Erzmagier [[Antonidas]] ausgebildete Jaina als Wunderkind mit außergewöhnlichen Leistungen auf dem Gebiet der magischen Forschungen und Untersuchungen. Trotz ihrer zahlreichen Pflichten blieben Arthas und Jaina einander in enger Freundschaft zugetan. Im Hinblick auf das Alter und die schlechte gesundheitliche Verfassung von König Terenas waren die Bürger erfreut, dass ihr geliebter Prinz heiraten und den Fortbestand des königlichen Geschlechtes sichern würde. \r\nArthas und Jaina war die öffentliche Aufmerksamkeit peinlich, daher hielten sie ihre Beziehung so privat wie möglich. Doch Jaina, die ganz in ihrem Studium in [[Dalaran]] aufging, wusste genau, dass die Romanze nicht von Dauer sein konnte. Sie hatte ihr ganzes Leben lang das Wirken der Magie erforscht und war sich bewusst, dass es ihre wahre Berufung war, nach Wissen zu streben – und nicht, in einem Thronsaal zu sitzen. Sehr zum Missfallen der Bürger von Lordaeron gingen die beiden Liebenden widerstrebend getrennte Wege und konzentrierten sich wieder auf ihre Pflichten.",},
			["Einweihung"] = { content = "„Du fragst Dich wahrscheinlich, warum Du aufgewacht bist, eh? Ich kann es Dir sagen: Weil ich Dir die Kehle durchgeschnitten habe.“ \r\nBlut spritzte aus dem Hals der Priesterin und tränkte den weichen Waldboden mit dem wertvollen Lebenssaft. Fassungslos starrte diese den über ihr thronenden Troll an, der weiter mit leiser Stimme auf sie einredete. \r\n„Hast Du wirklich gedacht, dass das alles gewesen sei, eh? Die Lehre über den Körper, die Götter, das Leben und das [[Voodoo]]?“ \r\nEin fieses, gurrendes Kichern auf den Lippen, riss der Troll sein graues Halstuch herunter und deutete auf die lange Narbe von einem Ohr zum anderen. \r\n„Oh ja, auch ich habe diese Prüfung über mich ergehen lassen – und überlebt wie Du sehen kannst. Es liegt also an Dir, Deinen Fähigkeiten und Deiner Götterfürchtigkeit ob auch Du Dich in den kleinen Kreis der Eingeweihten einreihen wirst.“ \r\nDie Augen weit aufgerissen, versuchte die Priesterin zu sprechen, doch nur gurgelnde Geräusche entsprangen ihren Lippen. Schnell, sehr schnell verließen sie die Kräfte. Ihre Haut wurde von Sekunde zu Sekunde grauer. Das einst so satte Blau verlor immer mehr an Farbe. Doch unerbittlich und ohne den Hauch eines Mitgefühls sprach der alte Mann weiter auf sie ein. \r\n„Deine Ausbildung und Ausrichtung deiner Heilkünste ist hiermit beendet. Du hast Dich vielfach bewiesen und Deinen Mut und Deine Tapferkeit unter Beweis gestellt. Du hast dem Stamm große Dienste erwiesen und manch Bedrohung abgewehrt. Du hast Leben gerettet und anderen zum Leben verholfen. \r\nDoch Schwäche ist der Tod! Und nun entscheidet sich, ob Du es wert bist, der großen Schlange [[Ula-Tek]] ein würdiger Diener zu sein. Oder ob all die Jahre des Lehrens und Leidens vergebene Liebesmüh gewesen sind, eh. Versenke Dich in die Meditation. Suche die Nähe Deines Gottes und erflehe seine Gnade. Konzentriere Dich auf Deine heilenden Kräfte, um die tödliche Wunde zu verschliessen - oder die unendliche Leere des Raums wird Dich für immer verschlingen. \r\nUnd nun: Lebe oder stirb in Würde! Das ist ganz allein Dein Dingo!“ \r\nDer alte [[Troll]] erhob sich mühsam von der jungen [[Priester]]in. Beiläufig wischte er den blutigen Ritual-Dolch an seinem verschmutzten Gewand ab. Dann nahm er sein zuvor gepacktes Bündel und schlenderte gebückt in das Dunkel des umliegenden Waldes. \r\nHinter ihm die kleine Lichtung mit dem niedergebrannten Feuer und der sterbenden Priesterin. Schnell verschwammen seine Schemen mit den Schatten des Dschungels.",},
			["Ein Erbe …"] = { content = "== Geschichte der Untoten==\r\n'''- Teil 7 -''' \r\n===Ein Erbe===\r\nDie [[Schreckenslord]]s waren hocherfreut, dass [[Ner'zhul]]s wahre Mission endlich angefangen hatte, doch der [[Lichkönig]] selbst brütete düster im engen, düsteren Gefängnis des [[Frostthron]]es. Trotz seiner ungeheuren übersinnlichen Macht und der uneingeschränkten Herrschaft über die Untoten sehnte er sich danach, seinem Eisgefängnis zu entkommen. Er wusste aber, dass [[Kil'jaeden]] ihn niemals von dem Fluch befreien würde. Und aufgrund seiner großen Macht wusste er, dass die Dämonen ihn vernichten würden, sobald er seine Mission beendet hatte. Doch eine Chance auf Freiheit blieb ihm – eine Möglichkeit, dem schrecklichen Fluch zu entkommen. Wenn es ihm gelang, einen geeigneten Wirtskörper zu finden – einen arglosen Trottel, der zwischen Dunkelheit und Licht hin und her gerissen war –, würde er dessen Körper übernehmen und dem Frostthron für immer entkommen. Und so schickte der Lichkönig sein gigantisches Bewusstsein abermals auf die Reise und suchte den perfekten Wirtskörper. \r\n==Siehe auch==\r\n* [[Entstehung des Lichkönigs]]\r\n* [[Kil'jaeden und der neue Pakt]]\r\n* [[Eiskrone und Frostthron]]\r\n* [[Krieg der Spinne]]\r\n* [[Kel'Thuzad und der Kult der Verdammten]]\r\n* [[Entstehung der Geißel]]\r\n* [[Ein Erbe …]]",},
			["Eiselementar"] = { content = "'''Eiselementare''' sind [[Elementargemische]] aus [[Wasserelementare|Wasser]]- und [[Luftelementaren]], ähneln in ihrer Form aber [[Erdelementare]]n. Sie kommen aus dem [[Frostland]] des [[Abyssischer Rachen|Abyssischen Rachens]]. Derzeit gibt es in [[Azeroth]] nur ein einziges bekanntes Eiselementar: [[Lokholar der Eisfürst]].",},
			["Eisenbands Ausgrabungsstätte"] = { content = "Um zu '''Eisenbands Ausgrabungsstätte''' in [[Loch Modan]] zu gelangen, muss man um die Südspitze des Sees herum und dann nach Osten gehen. Vor einer Weile, kurz bevor die [[Troggs]] in der Stätte auftauchten, hatten die [[Zwerge]] eine große Anzahl seltsame, verzierte Götzen gefunden. Leider hatten sie keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben sie die [[Troggs]] aus den Ruinen verjagt.\r\nDie Ausgrabungen an dieser Stätte schreiten weiter voran, werden jedoch durch das Auftauchen der [[Troggs]] behindert. Aber Eisenband ist zuversichtlich, dass sie mit diesem Problem fertig werden, auch wenn einige der [[Troggs]] aggressiver sind als gewöhnlich. Es wurden jüngst weitere Artefakte gefunden, aber mit einer Ausnahme fallen alle in die selbe Kategorie wie die anderen zuvor: Interessant, aber keinesfalls eine Sensation. Eine Ausnahme gab es jedoch. Die kürzlich entdeckten merkwürdig geschnitzten Götzen scheinen eine gewisse Wirkung auf die [[Troggs]] an der Ausgrabungsstätte zu haben. Sie werden von den Schnitzereien wir magisch angezogen und mancher Trogg ist danach schon Amok gelaufen. Um Rückschlüsse auf diese Götzen ziehen zu können, sind weitere Untersuchungen notwendig, aber Eisenband hofft, dass sie etwas über die Verbindung zwischen Troggs und Titanen erfahren können.\r\nDie Zwerge Huldar, Miran und Saean transportierten von [[Thelsamar]] einige Pulverfässer in mehreren Fuhren zur Ausgrabungsstätte. Doch sie gerieten in einen Hinterhalt der [[Dunkeleisenzwerge]]. Sie nahmen die übliche Route zur Ausgrabungsstätte, südwärts aus der Stadt raus und dann an der Krümmung des Lochs entlang. Dann verlor sich ihre Spur. Sie können noch nicht sehr weit gekommen sein, denn so stark sie auch sein mögen, können sie dennoch nicht allzu schnell laufen, wenn sie mit diesen Fässern vollgepackt sind. \r\n==Personen==\r\n* '''Aldren Cordon''' - Tuchmacher.\r\n* '''Ausgrabungsleiter Darteus Eisenband''' - Ausgrabungsleiter Eisenband leitet die Ausgrabung einiger alter Ruinen östlich des Loch. Er hat zuletzt wenig Fortschritte gemacht, besonders, wenn man all den Nachschub bedenkt, den sie ihm geschickt haben. Er ist ein bodenständiger, ehrlicher Zwerg, der gern Resultate sieht, und daher macht man sich Sorgen, dass da irgendwelche Kräfte gegen ihn arbeiten. Eisenband muss einen Fortschrittsbericht zu Jern Hornhelm nach Thelsamar schicken - einen Fortschrittsbericht und eine Neufassung seiner Anfrage nach mehr Sprengpulver. Dafür braucht er jemanden, der das für ihn erledigt. Der Ausgrabungsleiter macht sich auch Sorgen um einen Kollegen, Ausgrabungsleiter Agmond. Dieser hatte die Verantwortung über ihre Ausgrabungsstätten im Ödland, im Südwesten. Aber Eisenband hat schon seit Wochen nichts mehr von ihm gehört. Wenn man Agmonds Schicksal geklärt und seinen Tod gerächt hat, möchte Darteus Eisenband, dass man ihm Bericht erstattet. \r\n* '''Magmar Todesstreich''' kümmert sich um die Einzelheiten an der Stätte und wird wissen, warum es so langsam voran geht. Er möchte die Götzen studieren, und er will sie nicht mehr in den Händen der [[Troggs]] sehen. \r\n'''Quellen'''",},
			["Eisenbands Lager"] = { content = "[[Sturgy Eisenband]] hatte ein Lager südlich des [[Helmsbettsee]]s im östlichen [[Dun Morogh]]. Dort lehrte er die [[Schmied]]ekunst und er war der Beste. Aber eines Tages brachte ihm einer seiner Schüler eine Ladung mit seltsamem Erz. Eisenband nannte es [[Schattenerz]] und konnte es kaum erwarten, damit zu arbeiten. Doch kurz nach der Lieferung griff eine Bande [[Dunkeleisenzwerge]] sein Lager an. Sie töteten alle.",},
			["Eisenhölle"] = { content = "'''Eisenhölle''' ist ein gewaltiger zwergischer Hammer, der nur von einem zwergischen Chefarchitekten getragen werden darf. In die Vorderseite des Hammers wurden die Buchstaben \"F.S.\" eingeätzt. Einst befand sich Eisenhölle im Besitz von [[Franclorn Schmiedevater]], jedoch geriet die Waffe nach dessen Tod in die Hände des neuen Chefarchitekten [[Fineous Dunkelader]], der den Hammer nun verwahrt. Fineous ist ein Mann mit fragwürdigen Motiven und wenig Talent. Er ist so unfähig, dass er die wahre Macht von Eisenhölle nicht begreift; sollte ihm jedoch jemand nachfolgen, der fähig ist, das ganze Potential des Hammers zu nutzen, könnten die Verheerungen, die dessen Schöpfung über die Welt bringen würden, katastrophal sein.",},
			["Eisenschmiede"] = { content = "Während des zweiten Krieges gegen die [[Orcs]] wurden die meisten [[Zwerge|zwergischen]] Festungen von der [[Horde]] erobert und zerstört, doch die mächtige Eisenschmiede in den winterlichen Gebirgslanden von [[Dun Morogh]] konnte sich bisher jedem Versuch es zu erobern erfolgreich widersetzen. Als ultimativer Beweis ihres meisterhaften Umgangs mit Stein und Fels errichteten die [[Zwerge]] ihre Hauptstadt im Herzen des Berges selbst. So entstand eine weitläufige unterirdische Stadt der Handwerker, Entdecker, Bergmänner und [[Krieger]]. Auch wenn die [[Allianz]] durch die Ereignisse der jüngsten Vergangenheit fast zerstört wurde sind die [[Zwerge]] unter der Führung ihres Königs [[Magni Bronzebart]] fleißig dabei, für ihr Volk einen neue Zukunft zu schmieden.\r\n'''Quelle:''' \r\n= Stadtteile =\r\nDer Grundriss von Eisenschmiede gründet auf zwei konzentrischen Kreisen um das zentrale Feuer der Großen Schmiede. Von den größeren Vierteln führen Wege nach innen zum kleineren Kreis, der von einem Weg von Südwest nach Nordost mitten längs des Amboß durchschnitten wird. Am Rand des Kreises residieren Schneider, Lederverarbeiter, Apotheker und die [[Bergbaugilde]]. \r\n==Bankenviertel==\r\nDurch die Tore von Eisenschmiede von Dun Morogh aus betritt man den äußeren Kreis im Südwesten. Hier liegt das Bankenviertel, das auf etwa drei Achteln des Kreisrunds neben Bank auch das Auktionshaus und allerlei Geschäfte enthält.\r\n* '''Gastwirt Feuerbräu'''\r\n* '''Tormek Stoneriver''' - Als er geschäftlich mit der Bank in [[Sturmwind]] zu tun hatte, traf er ein Mädchen. Sie hat ihm auf Anhieb sein Herz gestohlen und er kann einfach nicht mehr aufhören, an sie zu denken. Er würde Ihr gerne eine Nachricht schicken. Ganze Zwölfmal musste er sie neu schreiben! Jetzt möchte er sicherstellen, dass sie seinen Brief auch erhält.\r\n* '''Wulmort Klingeltaschen''' - Wulmort sucht die gestohlenen [[Winterhauchfest]]-Leckereien. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten des [[Alteracgebirge]]s befindet.\r\n==Düsteres Viertel==\r\nWährend die Achtel zwischen den großen Vierteln im Südwesten zum Bankenviertel gerechnet werden, sind die beiden anderen Achtel im Nordosten ganz besondere Areale: zwischen den Mystikern und Forschern findet sich das düstere Viertel, in denen nicht nur die Macher obskurerer Geschäfte ihre Bleibe haben, sondern auch die Schurkenlehrer und Hexenmeister.\r\n* [[Gerrig Knochengriff]]\r\n* '''Grimnur Stonebrand''' - Angellehrer. Zitat: \"Ich bin ein Zwerg, zum Donnerwetter nochmal! Ich hab mit Angeln nichts am Hut! Ich meine, seht mich doch mal an! Ich bestehe doch praktisch ganz aus Stein. Ich hab nichts mehr - Ihr habt mich ausgelaugt. Ich hab Euch alles beigebracht, was ich weiß! Kapiert Ihr’s nicht? Ah, gut. Jetzt verfatzt Euch!\"\r\n==Große Schmiede==\r\nAm Amboß stehen stets die erfahrendsten Schmiede. Vom kleineren Kreis aus nach Südwesten kann man auch in die Halle des Zwergenkönigs gelangen. Im Südosten hat der Kreis eine kleine Ausbuchtung mit einer Landefläche für Greifen - der dritte Zugangsweg.\r\n* '''Golnir Geröllzeh''' – [[Tiefenbergbaugilde]]. Golnir ist Bergbaugrundbedarflieferant. Er wird die Ehrenhacken für Bergbaustudenten mit vorzüglichen Abschlussprüfungen fertig machen. \r\n* '''Gryth Thurden''' – Greifenmeister. Für ein geringes Entgelt kann man einen Greifenritt buchen... \r\n==Halle der Forscher==\r\nIm Nordosten liegt die Halle der Forscher, wo sich allerlei Historiker, Botaniker und Archälogen tummeln. Hier liegt das Hauptquartier der [[Forscherliga]].\r\n* [[Ausgrabungsleiter Sturmlanze]]\r\n* [[Brann Bronzebart]]\r\n* [[Historiker Karnik]]\r\n* [[Hochforscher Muninn Magellas]]\r\n* [[Krom Starkarm]]\r\n* '''Berater Belgrum''' – Belgrum ist das Verbindungsglied zum offiziellen Eisenschmiede. Er soll im Auftrag des Königs schnell und entschlossen handeln und die Aktivitäten der [[Zwerge der Schattenschmiede]] im [[Ödland]] unterbinden. Sie haben den [[Zwerge der Schattenschmiede|Schattenschmiedeklan]] ausgebremst, indem sie ihn von der [[Schwarzfelsspitze]] abgeschnitten haben, doch [[Hammerzeh Grez]]'s Mission wurde noch nicht erfüllt, solange die verlorene [[Tafel des Willens]] nicht zurück gebracht wurde.\r\n* '''Laris Bummelritzel''' - Laris befindet sich im rechten Seitenarm der Halle der Forscher und beschäftigt sich momentan mit [[Brühschlammer]]n. Aber er braucht mehr Proben für seine Untersuchungen und es müssen reine Proben sein. Er hat herausgefunden, dass die Brühschlammer sich anzupassen scheinen und die Eigenschaften der Gegend anzunehmen, in der sie sich befinden. \r\n* '''Kurator Thorius''' – Thorius kann kaum glauben, dass [[Gebirgsjägerin Feinkiesel]] die Echtheit des Horns der [[Donnerechse]] Margol angezweifelt hat. Er ist auch der Bruder von [[Dorius Steinhüter]], doch wo sein Herz einst für seinen Bruder schlug, ist jetzt ein leeres Loch. Über den Verlust von Dorius wird er so schnell nicht hinwegkommen und er muss seinen letzten Wunsch erfüllt sehen - diejenigen, die diesen kaltblütigen Mord durchführten, müssen der Gerechtigkeit zugeführt werden.\r\n* '''Mae Bleichstaub''' - Mae ist Bibliothekarin und sucht die 'Mythologie der Titanen' aus dem [[Scharlachrotes Kloster|Scharlachroten Kloster]]. Die Zukunft ist unausweichlich. Sie stürzen ihr entgegen wie Regentropfen, die auf das große Meer prasseln. Aber vielleicht erfahren sie, indem sie die Vergangenheit studieren, was sie erwartet, und könnten sich besser auf das Unbekannte vorbereiten.\r\n* '''Roetten Steinhammer''' – Roetten ist Verantwortlicher der [[Wiederholer AG]] in Eisenschmiede und steht im Eingangsbereich der Halle der Forscher.\r\n==Militärviertel==\r\nIm Südosten findet man das Militärviertel mit seinen Kriegern und Jägern.\r\n* [[Großsteinmetz Marmorstein]]\r\n* [[Pilot Xiggs Luntenzünder]]\r\n* '''Pilot Langbart''' - Pilot Langbart gehört zur [[Belagerungsbrigade]] von Eisenschmiede und hat eine Kiste mit Schutzhelmen für [[Wizzle Kupferbolz]] in der [[Schimmernde Ebene|schimmernden Ebene]].\r\n* '''Sara Balloo''' - Der Verlust ihres Gemahls [[Sully Balloo]] lastet schwer auf ihrer Seele. Er ist bei der Tragödie am [[Thandolübergang]] gestorben. Sie hat ein Hilfegesuch für König [[Magni Bronzebart]], doch in ihrem von Trauer übermannten Zustand vor den König zu treten, wäre ihrem Anliegen nicht im Geringsten dienlich. Es wird nur einen Augenblick dauern, um diesen Brief zu überfliegen...\r\n==Mystikerviertel==\r\nIm Nordwesten schließt sich das Mystikerviertel an das Bankenviertel an. Es ist ein Platz für und von Magier, Priester und Paladine, wo sich die \"Halle der Mysterien\" befindet.\r\n* [[Talvash del Kissel]]\r\n* '''Bink''' - Bink ist eine gnomische Magierlehrerin. Sie verbringt ihre Zeit in Eisenschmiede in der Halle der Mysterien im mystischen Krieg und hat eine Aufgabe zu erledigen. Allerdings will sie sich dabei nur auf einen Magier verlassen, denn sie hat ihren [[Magitastischer Gizmonitor|Magitastische Gizmonitor]] verloren und möchte ihn gern wiederhaben.\r\n* '''Tymor''' - Er besitzt ein kleines Anwesen rechts neben der Halle der Mysterien und möchte Abpausbilder der Arkanen Runen in [[Azshara]]. Dazu gehören die [[Rune von Beth'Amara]], die [[Rune von Jin'yael]], die [[Rune von Markri]] und die [[Rune von Sael'hai]]. Dann soll man von der kleinen Insel vor der südlichen Halbinsel von [[Azshara]] aus dem [[Pilot Xiggs Luntenzünder]] signalisieren, dass er sie abholen kann. Tymor will diese Abpausbilder sofort in seinen Turm geliefert haben, aber man muss nicht den ganzen Weg selbst gehen. Er wird sie einfach per Luftfracht aus [[Azshara]] bringen lassen.\r\n==Thronsaal==\r\nIm Thronsaal befindet sich der hohe Sitz ist die Halle des Königs.\r\n* [[Magni Bronzebart]]\r\n* '''Deliana''' - Deliana muss einen Weg finden, mit [[Anthion Harmon]] zu sprechen... Oder genauer gesagt mit seinem Geist. Sie möchte deswegen, dass man einen versiegelten Blutbehälter zu [[Mux Manamix]] in [[Gadgetzan]] bringt. Das Blut war für [[Mux Manamix]] bestimmt als Bezahlung für seine Dienste, denn mithilfe seines [[Extradimensionaler Geisterdetektor|Extradimensionalen Geisterdetektors]] will sie am Eingang zu [[Stratholme]] mit dem Geist von [[Anthion Harmon]] sprechen und herausfinden, was dieser wusste.\r\n* '''Königliche Historikerin Archesonus''' – Historikerin Archesonus kennt die Geschichte von Thaurissan und möchte, dass man in den glimmenden [[Ruinen von Thaurissan]] in der [[Brennende Steppe|Brennenden Steppe]] und Informationen über die Relikte von Thaurissan sammelt.\r\n* '''Senator Barin Rotstein''' - Er ist ein missmutiger Geselle. Der Senat hat mit den [[Troggs]] bereits alle Hände voll zu tun, deswegen kann er keinen weiteren Ärger gebrauchen.\r\n==Tüftlerstadt==\r\nZwischen Forschern und Militär residieren die Gnome bis hin zum ihrem obersten Führer. Von dieser Tüftlerstadt aus zweigt ein Gang zur [[Tiefenbahn]], die bis nach [[Sturmwind]] führt und somit die zweite Eintrittsmöglichkeit in diese Hauptstadt darstellt.\r\n* [[Gnoarn]]\r\n* [[Hochtüftler Mekkadrill]]\r\n* [[Mechanikermeister Gussmuff]]\r\n* [[Tüftlermeister Oberfunks]]\r\n* '''Klockmort Spannsplint''' - Klockmort hegt Kontakt zu [[Wizzle Kupferbolz]] in der [[Schimmernde Ebene|schimmernden Ebene]] und Wizzle hat gesagt, dass er für sein nächstes Experiment noch eine sehr seltene Komponente benötigt. Klockmort braucht auch eine eine ganze Menge Grundlegende Artifixe für eine Arbeit, die er in Kürze in Angriff nehmen wird\r\n* '''Lomac Ritzeldreh''' - Lomac ist die einzige Person, die den Sprengstoff NG-5 herstellen kann. Das Zeug ist hochexplosiv, aber aus schwachen Manatränken und Elixieren der Seelenstärke mixt er unter Riesenspaß [[Nitromirglyceronium]]. Dieses möchte er zu Gaxim Rostknirsch im Steinkrallengebirge gebracht haben.",},
			["Eisenschmiedebrigade"] = { content = "Die '''Eisenschmiedebrigade''' befindet sich in einem Lager der Allianz in der Nähe des [[Zoraschwarm]]baus in [[Silithus]]. Diese tapferen Zwerge haben vor kurzem herausgefunden, dass die Horde die Wüste von Silithus nach Ressourcen abgesucht hat, schenkten dem Ganzen aber keine besondere Beachtung. Sie dachten, es wäre die Sache nicht wert, eine größere Anzahl von Soldaten in dieser Bruthitze zu stationieren. Nun aber haben sie die Wichtigkeit des [[Silithyst]] erkannt und versuchen nun, um jeden Preis aufzuholen. Die Eisenschmiedebrigade unter [[Marschall Himmelswand]] und [[Hauptmann Rußschmied]] hat sich in den Kämpfen von Silithus als ein würdiger Verbündeter von [[Burg Cenarius]] erwiesen. Unglücklicherweise hat sie auf dem Weg hierher die meisten ihrer Vorräte eingebüßt.\r\n==Personen==\r\n* '''Arkanist Sprinkelstaub''' - Arkanist Sprinkelstaub kümmert sich um den Sprengstoffbedarf der Brigade und sucht dafür Öle des Feuerbrandes, Goblinraketentreibstoff und Dichtes Sprengpulver. Ihm liegt eine Anforderung der Eisenschmiedebrigade vor, die eine Menge recht explosiver Komponenten umfasst. Mit dem Logistikeinsatz IV kann man Sprinkelstaub behilflich sein.\r\n* '''Hauptmann Rußschmied''' - Hauptmann Rußschmied leitet die Kampfeinsätze der Eisenschmiedebrigade.\r\n* '''Leutnant Janela Starkhammer''' – Leutnant Janela Starkhammer braucht Rüstungssets und Waffen für den Feldeinsatz. Zusammen mit dem Logistikeinsatz VII kann man ihr unverwüstliche Rüstungssets und schwere Rüstungsset bringen. Mit dem Logistikeinsatz VI stehen Mondstahlbreitschwerter auf der Wunschliste.\r\n* '''Marschall Himmelswand''' - Marschall Himmelswand hat das Kommando über die Eisenschmiedebrigade, wenn es um die Suche nach [[Silithyst]] für die Allianz geht. Er überwacht den Silithystextraktor.\r\n* '''Scharfschütze Torrig''' - Scharfschütze Torrig verweist Freiwillige, die sich an der Suche nach [[Silithyst]] beteiligen wollen, an Marschall Himmelswand.",},
			["Eisenschmiede - Das Erwachen der Zwerge"] = { content = "'''Quelle.'''\r\n{Zitat|Eisenschmiede - Das Erwachen der Zwerge|Geschichtsbuch|nachzulesen in den [[Schwarzfelstiefen]] und [[Tanaris]] - [[Uldum]].==Inhalt==\r\nIn alten Zeiten, als die Titanen Azeroth verlassen hatten, formten ihre Kinder, die Irdenen genannt, weiterhin die tiefen Abgründe der Welt. Die Irdenen kümmerten sich nicht weiter um die Belange der Völker an der Oberfläche, sondern wollten nur die dunklen Tiefen der Erde erforschen.\r\nAls die Welt nach der Implosion des Brunnens der Ewigkeit zerrissen wurde, waren die Folgen für die Irdenen immens. Die Irdenen, die sich unter den Schmerzen der Erde krümmten, verloren weitgehend ihre Identität und schlossen sich in den Kammern aus Stein ein, in denen sie erschaffen worden waren. Uldaman, Uldum, Ulduar ... das waren die Namen der alten titanischen Städte, wo die Irdenen Gestalt und Form angenommen hatten. Fast achttausend Jahre lang ruhten die Irdenen in Frieden tief unter der Welt.\r\nWas die Irdenen weckte, ist unklar, auf jeden Fall erwachten sie schließlich irgendwann aus ihrem selbst gewählten Schlummer. Nun mussten die Irdenen feststellen, dass sie sich im Laufe ihres Schlafs sichtlich verändert hatten. Ihr harter Felspanzer war zu glatter, weicher Haut geworden, ihre Macht über Steine und Erde war geschwunden. Sie waren sterbliche Wesen geworden.\r\nDie Letzten der Irdenen, die sich nun Zwerge nannte, verließen die Hallen von Uldaman und zogen hinaus in die erwachende Welt. Doch da die Sicherheit und Wunder tiefer Orte sie nach wie vor betörten, gründeten sie ein gewaltiges Königreich unter dem höchsten Berg des Landes.\r\nSie nannten ihr Land Khaz Modan oder \"Berg von Khaz\", dem titanischen Former Khaz'goroth zu Ehren. Als sie ihrem Titanenvater einen Altar errichteten, schufen die Zwerge eine mächtige Schmiede im Herzen des Berges. Von diesem Tage an trug die Stadt, die um diese Schmiede herum wuchs, den Namen Ironforge oder \"Eisenschmiede\".\r\nDie Zwerge, die für ihr Leben gern Edelsteine und Gestein formten, suchten in den umliegenden Bergen nach Reichtümern und kostbaren Mineralien. Da sie mit ihrer Arbeit unter Tage zufrieden waren, kümmerten sich die Zwerge nicht um die Angelegenheiten ihrer Nachbarn an der Oberfläche.",},
			["Eisenstammhöhlen"] = { content = "Nördlich des [[Blutgiftposten]]s im [[Teufelswald]] liegen die Eisenstammhöhlen. Für die verderbten [[Wucherborkenelementare]], die sich dort aufhalten, gibt es keine Hoffnung mehr auf Säuberung.",},
			["Eisenwald"] = { content = "Im Eisenwald findet man [[Hastat der Uralte |Hastat den Uralten]], ein [[Urtum des Wissens]]. Er bewahrt seit Ewigkeiten verlorenes Wissen. Richtig gebunden kann eines seiner Blätter als Köcher dienen, doch dergleichen wurde seit 10.000 Jahren nicht mehr gesehen. Ein Köcher, der - wenn er von einem Bogen der Uralten begleitet wird - ungeahnte Kräfte verleihen könnte. Doch dazu benötigt er die Sehne eines ausgewachsenen, blauen Drachens. \r\nNur [[Stoma der Uralte]] kann die benötigte Sehne verzaubern, die den Bogen vervollständigt. Er wiederum benötigt die Sehne eines ausgewachsenen, schwarzen Drachens. \r\n[[Vartrus der Uralte]] wird Jägern den Holzstab für die Erstellung eines Bogens der Uralten geben. Doch dazu muss man die vier dämonischen Verderber ausfindig machen und zerstören: \r\n* [[Artorius der Verhängnisvolle]]\r\n* [[Klinfran der Wahnsinnige]]\r\n* [[Simone die Verführerin]]\r\n* [[Solenor der Schlächter]]",},
			["Eisenzwerge"] = { content = "Bis in die entferntesten Winkel der Welt ist die [[Forscherliga]] vorgedrungen, um die Wahrheit um den Ursprung der [[Zwerg]]e zu enthüllen. Nun scheint es, als wären sie der Entschlüsselung der Geheimnisse ihrer Vergangenheit einen Schritt näher. Die neuesten Hinweise kommen aus alten Grabungsstätten im [[Heulender Fjord|Heulenden Fjord]], wo man das erste Mal auf die Eisenzwerge traf. Machtvolle Runen sind in ihre dicke, metallische Haut geätzt, unter der elektrische Ladungen entlangkriechen – es ist möglich, dass sie das fehlende Bindeglied zwischen den Zwergen und den legendären [[Titanen]] darstellen. Unglücklicherweise haben sich die bösartigen Eisenzwerge der [[Forscherliga]] offen widersetzt und scheinen darauf versessen, jegliche [[Artefakt]]e, die sie mit ihren sagenumwobenen Ursprüngen verbinden, zu zerstören.\r\n'''Quelle:'''",},
			["Eisklammpass"] = { content = "Als Eisklammpass wird der Höhlentunnel zwischen dem [[Eisklammtal]] und dem restlichen [[Dun Morogh]] genannt. Man muss z.B. diesen Tunnel nehmen, um nach [[Kharanos]] zu gelangen. Er ist mittlerweile vollständig von den böswilligen, aber nicht allzu bedrohlichen [[Troggs]] überrannt. Die Troggs im Tunnel sind extrem feindselig und scheinen nicht zu zögern, durch den Tunnel reisende Leute anzugreifen. Um zum Tunnel zu gelangen, folgt man der Straße von [[Ambossar]] und geht dann weiter nach Osten. Die Straße von [[Ambossar]] durch den Tunnel führt über über sanfte Hügel bis in den wichtigsten Ort der [[Zwerge]], [[Kharanos]], zentral in [[Dun Morogh]] gelegen.\r\n==Personen==\r\n* '''[[Gebirgsjäger]] Thalos''' ist ganz in der Nähe des Tunnels stationiert. \r\n* '''Hands Federspross''' kann nicht über den Pass und es dauert Tage, bis wieder eine [[Gebirgsjäger]]eskorte vorbeikommt. Er hat eine Kiste mit Gasthausvorräten, die zu Tannok Frosthammer in [[Kharanos]] gebracht werden muss.\r\n* '''Hegnar Schlingerschuss''' verkauft Gewehre an der Straße nach [[Ambossar]]. [[Scharfschütze]]n und [[Mörsertrupp]]s verbringen viel Zeit damit, in der Nähe seines Geschäfts zu üben, und er braucht ständig neue Munition. Aber die letzte Munitionskiste, die er ihm geschickt hat, ist unterwegs verloren gegangen. Sein Kurier sagte, er lagerte nahe des [[Graufelsbau]]s, als [[Wendigo]]s ihn davonjagten und der Dummkopf hat Schlingerschusss Munition zurückgelassen. Er wartet darauf und ihm gehen bestimmt bald die Vorräte aus.",},
			["Eisklammtal"] = { content = "Ganz im Südwesten gelegen, von [[Dun Morogh]] aus und nur von dort aus durch einen schmalen Tunnel erreichbar, liegt das '''Eisklammtal''' - Startgebiet von [[Zwerge]]n und [[Gnome]]n mit der steinernen Festung [[Ambossar]]. Im Eisklammtal gibt es so viele Eber, dass es fast schon keinen Spaß mehr macht, sie zu jagen. Man muss sie gar nicht mehr reizen. Sie sind schon aggressiv und angriffslustig, ohne dass man nachhilft. Um genau zu sein, streifen in letzter Zeit so viele Eber durch die Gegend, dass es gefährlich geworden ist, auf die Jagd zu gehen.\r\n==Personen==\r\n* [[Grelin Weißbart]]\r\n'''Sonstige'''\r\n* '''Grik'nir der Kalte''' ist ein [[Eistrolle|Eistroll]]. Ein großer Kerl mit seltsamen Zeichen auf der Haut und im Gesicht.\r\n* '''Nori Stolzmut''' sollte ein köstliches, kochend heißes Morgengebräu schon vor einer ganzen Weile zu Durnan Pelznaht in [[Ambossar]] bringen, aber er musste erst eine Ladung zu Grelin hier bringen. Er wird es niemals bis nach [[Ambossar]] schaffen, bevor das Gebräu kalt wird!\r\n* '''Sten Starkarm''' bekam ein Stapel Briefe durch den [[Eisklammpass]], aber er hat nicht die Zeit, sie weiterzuleiten. Sie sind alle an Talin Kühnauge adressiert. \r\n* '''Talin Kühnauge''' findet man ein Stück entlang der Straße im Westen. Er hat sein Lager am gefrorenen See aufgeschlagen. Und es geht ihm nichts über einen Tag auf der Eberjagd.",},
			["Eiskrone"] = { content = "#REDIRECT [[Eiskronengletscher]]", redirect = "Eiskronengletscher",},
			["Eiskronegletscher"] = { content = "#REDIRECT [[Eiskronengletscher]]", redirect = "Eiskronengletscher",},
			["Eiskronengletscher"] = { content = "Die '''Eiskrone''' ist der Name eines gewaltigen Gletschers in [[Nordend]], der das eisige Zentrum der [[Geißel]] darstellt.\r\nHoch im Norden des eisigen Kontinents [[Nordend]] schiebt sich der Eiskronengletscher weit in das Land hinein. Hier findet man kein Leben, nur ewiges, schier endloses Eis. Die trostlose Landschaft wird allein vom Eiskronenfluss durchbrochen, ein bitterkalter Strom, an vielen Stellen überfroren und eingebettet zwischen hohen, spiegelglatten Ufern aus Eis. Obwohl hier nichts leben kann, kann man ständig Gestalten sehen, die sich auf und in dem Gletscher bewegen, denn überall sind [[Untote]]. Unzählige Leichname von [[Menschen]], [[Trolle]]n, [[Zwerge]]n und sogar [[Neruber]]n und [[Furbolgs]] gehen ihrer finsteren Aufgabe nach: dem Willen [[Arthas]] zu Diensten sein. Diesen findet man tief im Inneren des Gletschers. Dort, in der [[Eiskronenzitadelle]], sitzt er auf dem [[Frostthron]] und plant die Unterwerfung aller Völker. \r\n==Geschichte==\r\nAls [[Kil'jaeden]] den Kristall, in dem sich [[Ner'zhul]]s rachsüchtige Seele regte, wieder in die Welt von [[Azeroth]] versetzte, landete er auf dem Kontinent [[Nordend]]. Bei dem brutalen Absturz drang der kristallene Sarg bis zum Grund des Eiskronengletschers ein. Anfangs nutzte [[Ner'zhul]] seine übersinnlichen Kräfte, um zahlreiche eingeborene Keaturen unter seinen Einfluss zu bringen. So konnte er bereits eine kleine Armee aufstellen, die er in den verschlungenen Labyrinthen des Gletschers verbarg. Zehn Jahre lang baute der [[Lichkönig]] das Zentrum seiner Macht in [[Nordend]] aus, und ließ eine große [[Eiskronenzitadelle]] über dem Gletscher errichten, um seine wachsende Legion der [[Untote]]n aufzunehmen. Einer der wenigen Menschen, die je zur Eiskrone gelangten, war der [[Erzmagier]] [[Kel'Thuzad]], der nach [[Nordend]] reiste um [[Ner'zhul]] seine Dienste anzubieten.",},
			["Eiskronenzitadelle"] = { content = "Die '''Eiskronenzitadelle''' ist eine riesige Festung auf dem [[Eiskronengletscher]] mit dicken Wänden, robusten Wachtürmen und massiven Eingangstoren. Die Eiskrone bekam ihren Namen als [[Kil'jaeden]] den [[Lichkönig]] zurück in die sterbliche Welt stürzte. Hier verweilte er, bis [[Arthas]] ihn befreite und sie zusammen in Arthas Körper verschmolzen. Die Vereinigung löste eine schwere Explosion aus, die den [[Frostthron]] freisetzte. Von hier aus befehligt der Lichkönig nun die [[Geißel]].Aus den Trümmern des einstigen Eisturms ist eine mächtige, bedrohliche, schwarze Festung geworden. Der Hauptteil der Zitadelle liegt oberhalb des gesplitterten Gletschers, die Gletscherteile selber werden durch Brücken und Wege überwunden. Beim Betreten der Zitadelle stellt man sofort die Kälte fest, die hier innewohnt, keine Dekoration und auch keine Teppiche oder Vorlagewerke schmücken diese Festung. Am Fuße der Gletscherspalte befindet sich der [[Frostthron]], das Herz der Geißel und des Lichkönigs privater Sitz.",},
			["Eiskrone und Frostthron"] = { content = "== Geschichte der Untoten==\r\n- Teil 3 - \r\n===Eiskrone und Frostthron===\r\nKil'jaeden beförderte Ner'zhuls Sarg aus Eis wieder in die Welt Azeroth. Der gehärtete Kristall schoss über den Nachthimmel und landete auf dem einsamen arktischen Kontinent Nordend, wo er sich tief in die düsteren Höhlen des Eiskronengletschers eingrub. Der durch den brutalen Absturz verformte und beschädigte gefrorene Kristall erinnerte an einen Thron, und Ner’zhuls rachsüchtige Seele regte sich in seinem Inneren. Aus der Enge seines Frostthrons sandte Ner’zhul sein riesiges Bewusstsein aus und berührte den Geist der Bewohner von Nordend. Überraschend leicht gelang es ihm, die Seelen der zahlreichen eingeborenen Kreaturen – darunter Eistrolle und die wilden Wendigo – zu versklaven und ihre bösen Brüder unter seinen wachsenden Einfluss zu bringen. Er stellte fest, dass seine übersinnlichen Kräfte fast grenzenlos waren, und nutzte sie, um eine kleine Armee aufzustellen, die er in den verschlungenen Labyrinthen des Eiskronengletschers verbarg. Während der Lichkönig unter ständiger Beobachtung durch die Schreckenslords seine wachsende Macht meisterte, entdeckte er eine entlegene Menschensiedlung am Rande der großen Drachenöde. Ner’zhul beschloss, seine Kräfte und die grauenhafte Seuche an den arglosen Menschen zu erproben. Er schickte die Seuche des Untodes, deren Ursprung tief in dem Frostthron lag, in die arktische Eiswüste. Allein Kraft seines Geistes kontrollierte er die Seuche und brachte sie mitten in das Menschendorf. Binnen drei Tagen war jede Menschenseele in der Siedlung tot. Doch schon nach überraschend kurzer Zeit standen die toten Dorfbewohner als Zombie-Kadaver wieder auf. Ner’zhul konnte ihre Seelen und Gedanken spüren wie seine eigenen. Durch die tosende Kakophonie in seinem Geist wurde Ner’zhul noch mächtiger – als würden ihn diese Seelen mit dringend benötigter Nahrung versorgen. Er stellte fest, dass es ein Kinderspiel war, die Aktionen der Zombies zu steuern und sie nach seinen Wünschen zu lenken. Während der nächsten Monate experimentierte Ner’zhul weiter mit seiner Seuche des Untodes, indem er jeden menschlichen Bewohner von Nordend damit infizierte. Da seine Armee der Untoten mit jedem Tag wuchs, wusste er, dass der Tag seiner wahren Prüfung näher rückte. \r\n==Siehe auch==\r\n* [[Entstehung des Lichkönigs]]\r\n* [[Kil'jaeden und der neue Pakt]]\r\n* [[Eiskrone und Frostthron]]\r\n* [[Krieg der Spinne]]\r\n* [[Kel'Thuzad und der Kult der Verdammten]]\r\n* [[Entstehung der Geißel]]\r\n* [[Ein Erbe …]]",},
			["Eistroll"] = { content = "#REDIRECT [[Eistrolle]]", redirect = "Eistrolle",},
			["Eistrolle"] = { content = "== Allgemeines==\r\n* Auch bekannt als: Frosttrolle \r\n* Historische Hauptstadt: Gundrak \r\n==Beschreibung==\r\nDie Haut der Eistrolle kommt in Schattierungen zwischen weiß und blau vor. Es wurden auch vereinzelt grünhäutige Eistrolle beobachtet. Diese sind aber selten, und die grüne Farbe ist eine Folge der Pigmentierung, nicht von Pflanzenbewuchs wie bei den [[Waldtrolle]]n. Eistrolle haben normalerweise dichte Haarmähnen. Eistrolle sind besonders gewalttätig und grausam, selbst im Vergleich mit anderen Trollen. Dieser unangenehme Charakter ist jedoch nicht die Folge der verschneiten Gebiete, in denen die Trolle leben; vielmehr ist es so, dass einige Trollstämme wegen ihres Verhaltens in den hohen Norden vertrieben wurden, und sich dort zu Eistrollen entwickelten \r\n==Geschichte==\r\nWie alle anderen Trolle stammen auch die Eistrolle von den [[Zandalar]] ab, trennten sich jedoch von diesen und gründeten einige eigene kleine Stämme. Diese neuen Stämme erwiesen sich als zu blutdurstig, um von anderen Völkern toleriert werden zu können. Sie wurden aus den bewohnten Gebieten vertrieben und waren gezwungen, sich weit im Norden des alten [[Kalimdor]] niederzulassen, in einer Region, die heute als [[Nordend]] bekannt ist. Lange vor der Großen Teilung gründeten die Eistrolle eine kleine Nation namens [[Zul'Drak]], die aber niemals die Größe oder den Wohlstand der beiden südlichen Trollimperien erreichen sollte. Für lange Zeit hatten die Eistrolle wenig mit der so genannten zivilisierten Welt zu schaffen, und viele von ihnen leben auch heute noch in [[Nordend]]. Seit Kurzem werden Eistrolle aber auch in größerer Zahl in den östlichen Königreichen gesichtet, wo die [[Trolle der Frostmähnen]] immer häufigere und aggressivere Angriffe durchführen. \r\n==Gebiete==\r\nDie Trolle, welche schon in alten Zeiten nach [[Nordend]] vertrieben worden waren, rotteten sich in [[Khaz Modan]] erneut zusammen. Aufgrund der unwirtlichen Bedingungen der Schneewüste konnten sie jedoch nur eine kümmerliche Gesellschaft aufbauen. Die [[Trolle der Frostmähnen]], die sich mit der Zeit in [[Dun Morogh]] bildeten, mussten schlussendlich den mächtigen Streitkräften des Zwergenkönigs [[Magni Bronzebart]] weichen. Mit dem Einfall der [[Troggs]] jedoch erkannten die Eistrolle ihre Chance und haben nun nur noch ein Ziel; die Heimat ihrer Vorväter zurückzuerobern und ein neues Reich zu gründen. \r\n==Charakter==\r\nEistrolle finden Gefallen an Gemetzel und Gemeinheit, genau wie ihre bösen Vettern, die [[Waldtrolle]]. Sie wurden in alten Zeiten in die einsamen Wüsten von [[Nordend]] vertrieben und haben zwischen dem kalten Felsgestein auf den lebensfeindlichen Ebenen eine kümmerliche Gesellschaft gebildet. Eistrolle sind von Natur aus Kannibalen und berüchtigt für ihre Neigung, gerade erlegte Feinde roh zu verschlingen. Ihre gesellschaftliche Struktur weist große Ähnlichkeit mit der ihrer im Wald lebenden Artverwandten auf.\r\n==Stämme der Eistrolle==\r\n* [[Trolle der Drakkari]]\r\n* [[Trolle der Frostmähnen]]\r\n* [[Trolle der Winteraxt]]\r\n(Quelle:",},
			["Ei von Hakkar"] = { content = "Wenn man das Ei von Hakkar auf Geheiß von [[Yeh'kinya]] in [[Tanaris]] in das Sanktum des Gefallenen Gottes im [[Versunkener Tempel|Versunkenen Tempel]] in [[Azeroth]] bringt, kann man die Macht des Eies anrufen, um den toten Gott aufzuwecken. Er wird seine Diener schicken, doch wenn man seine Bluttrinker besiegt und das Hakkariblut an sich nimmt; kann man das Blut benutzen, um die ewigen Flammen auszulöschen, die [[Hakkar]]s Geist halten. Wenn alle Flammen gelöscht sind, wird der Avatar von Hakkar die Welt betreten und wenn er besiegt wurde, kann man seine Essenz in das Ei von Hakkar geben. Wenn die Essenz von Hakkar eingefangen wurde, beginnt sich das Leben im Ei zu regen. \r\n[[Yeh'kinya]] sagt, er fürchtet sich vor dem, was Hakkar tun könnte, wenn er erneut geboren wird. Er will dieses Ei sicher aufbewahren und darauf achten, dass es niemals in böse Hände gerät. Doch die eingehende Beschäftigung mit der [[Schrifttafel von Mosh'aru]] bestätigt den Verdacht auf schlechte Neuigkeiten. [[Hakkar]]s wahre Gestalt, der Gott selbst, kann mit genau dem Ei wiedergeboren werden, in dem man ihn gefangen hat.",},
			["Ekelhafter Schlammling"] = { content = "Schleimige Angelegenheit: Um an dieses seltene Exemplar zu kommen, müsst Ihr unter Umständen sehr viele Schlammwesen ab Stufe 50 töten. Hierzu eignen sich die klebrigen Brühschlammer im Krater von [[Un'Goro]], sowie die besudelten Brühschlammer im [[Teufelswald]]. Aber Achtung: Der kleine Schlammling ist von einer Aura umgeben, die alle Eure Resistenz-Werte um 20 Punkte verringert.",},
			["Ektoplasmadestillierer"] = { content = "Der '''Ektoplasmadestillierer''' ist ein hervorragendes Stück [[Ingenieur]]sarbeit und Teil des [[Extradimensionaler Geisterdetektor|Extradimensionalen Geisterdetektors]]. [[Mux Manascrambler]] in [[Tanaris]] hat dieses Gerät gebaut und kann damit die Essenz des Todes absaugen.",},
			["Eldre'Thalas"] = { content = "'''Eldre'Thalas''' war bis vor vielen Jahren für die [[Nachtelfen]] eine Bastion magischer Kraft. Es lag im heutigen [[Feralas]] in dem Gebiet, das heute als [[Düsterbruch]] bekannt ist.",},
			["Elekk"] = { content = "Die starken und kräftigen Elekks sind die Reittiere der [[Draenei]]. Wegen den langen Hörnern und der gewaltigen Größe lassen sie so manchen Feind erzittern. Alle Rassen der [[Allianz]] können lernen ein solches Tier zureiten, allerdings geben die [[Draenei]] ihre liebsten Tiere nur an Leute, die bei ihnen einen ehrfürchtigen Ruf genießen. Zu kaufen gibt es die Elekks bei der [[Exodar]]. \r\nDas Elfenbein der wild-lebenden Elekk in [[Nagrand]] ist ein heißbegehrtes Material bei den [[Astrale]]n Händlern, aber die meisten der Stoßzähne sind minderwertig. \r\n==Besondere Tiere==\r\n* Zahna - Die Königin aller Tiere in [[Nagrand]] ist Zahna. Sie ist ein riesiger Elekk von der Sorte, wie man sie woanders nie zu sehen bekommen wird. [[Bach'lor]], [[Aaskralle]] und [[Banthar]] sind nichts im Vergleich zu ihr. Man sagt, dass sie sich auf einer riesigen Klippe weit im Südwesten in der Nähe des [[Oshu'gun]] aufhält.",},
			["Elekks"] = { content = "#REDIRECT [[Elekk]]", redirect = "Elekk",},
			["Elementar"] = { content = "#REDIRECT [[Elementare]]", redirect = "Elementare",},
			["Elementare"] = { content = "== Allgemeines==\r\nElementare sind chaotische Manifestationen der reinen Elementar-Energien.Sie sind nicht zu verwechseln mit den [[Geister des Schamanismus]], die ebenfalls die Elemente verkörpern. Sie waren die Wesen, die einst den [[Alte Götter|Alten Göttern]] dienten, als diese [[Azeroth]] beherrschten. Nachdem die [[Alte Götter|Alten Götter]] von den [[Titanen]] besiegt und eingesperrt wurden, wurden die Elementare in ihre Ebenen verbannt. Über die Jahrhunderte haben sie jedoch Wege gefunden, nach [[Azeroth]] zurückzukehren und laufen jetzt zügellos in vielen Gebieten umher, obwohl es für gewöhnlich nur die Schwächsten aus ihren Rängen sind, die durch diese \"Risse\" gleiten können.\r\n===Beherrschung===\r\nEinige intelligente Wesen aus [[Azeroth]] haben Wege gefunden, Elementare zu beschwören und sie an ihren Willen zu binden. So werden sie z.B. oft von [[Menschen|menschlichen]] [[Magier]]n und anderen mächtigen Wesen als Diener und Wächter benutzt. Um auf der physikalischen Ebene zu existieren, müssen die Elementare durch besonders verzaubere Armschienen gebunden werden, die sie unter Kontrolle und intakt halten. Wenn die [[Magie]] der Armschienen unterbrochen wird - gewöhnlich durch anhaltende physikalische oder magische Attacken -zerstreuen die Elementare sich sofort.\r\n===Hierarchie===\r\nElementare scheinen eine komplexe königliche Machthierarchie zu haben. Die mächtigsten Elementarwesen tragen solche Titel wie Baron, Fürst und Herzog. Die nahesten und mächtigsten Nachkommen der Elementaren Leutnants sind sogar als Prinzen und Prinzessinnen bekannt. \r\n==Bekannte Arten == \r\nEs gibt vier Hauptarten von Elementaren, jede entsprechend den Basis-Elementen der Welt: Erde, Feuer, Wind und Wasser. Jedes Elementar neigt dazu gegen Schaden aus seiner Elementar-Art immun zu sein. \r\n* [[Erdelementare]] \r\n* [[Feuerelementar]]\r\n* [[Luftelementare]] \r\n* [[Wasserelementare]]\r\nNeben diesen Hauptarten gibt es aber auch noch eine Reihe von Unterarten, die sich aus zwei oder mehreren Haupt-Elementar-Arten zusammensetzen:\r\n[[Mephit]]s\r\n==Elementare Leutnants==\r\nDie Elementare sind / waren die Günstlinge der [[Alte Götter|Alten Götter]] und wurden von vier Elementaren Leutnants befehligt, um die Welt in einem immerwährenden Zustand des Chaos zu halten: \r\n* [[Ragnaros]] der Feuerfürst\r\n* [[Therazane]] die Steinmutter\r\n* [[Al'Akir]] der Windfürst\r\n* [[Neptulon]] der Gezeitenjäger\r\nInteressanterweise scheinen die Alten Götter - anders als ihre Leutnants - selbst nicht aus einem einzelnen Element zu sein, obwohl sie die Quelle aller Elementarwesen sowie der Elementare und Abkömmlinge sind. Alle vier Elementarfürsten hassen einander, besonders [[Ragnaros]] und der mächtigste Elementarfürst [[Neptulon]]. Deshalb ist es nicht überraschend, dass viele von [[Neptulon]]s Diener in [[Azeroth]] sind und gegen die anderen drei Fürsten arbeiten. Doch die vier Leutnants sind scheinbar nicht länger unter der Kontrolle der [[Alte Götter|Alten Götter]] und finden neue Wege gegeneinander Krieg zu führen. Obwohl sie einander bekämpfen, bewahren sie noch einen [[Hoher abyssischer Rat|Abyssischen Hohen Rat]]. Alle außer den mächtigsten Elementaren sind geistlose Wesen, die Aufgaben ganz nach Laune ihrer Meister ausführen. Kürzlich jedoch haben mehr und mehr Elementare begonnen auf [[Azeroth]] zu erscheinen, die einem bis jetzt unbekannten Zweck dienen.\r\n==Siehe auch==\r\n* [[Abyssischer Rat]]\r\n* [[Hoher abyssischer Rat]]\r\n* [[Elementare Invasion]]",},
			["Elementare Ebene"] = { content = "Elementarebene\r\nDas [[Pantheon]] zerschmetterte die Zitadellen der [[Alten Götter]] und kettete die fünf bösen Götter weit unter der Oberfläche der Welt. Ohne die Macht der Alten Götter, die sie auf der Welt verankerte, wurden die Elementare auf eine abyssische Ebene verbannt, wo sie blieben bis in alle Ewigkeit. Diese Ebene wird als Elementarebene bezeichnet.\r\nDie [[Elementare]] haben sich an ihre Wahlheimat in den Jahrtausenden, die vergangen sind, angepasst. Sie können wieder für kürzere Zeitspannen nach [[Azeroth]] , aber die meisten sind gespannt auf Rückkehr in ihre Welt, wenn der Zauber beschworen, dass sie endet. Die Kommunikation mit [[Elementaren]] ist schwierig, und sie haben wenige Informationen über die Art ihres Reichs. Wissenschaftler glauben, dass Elementarebene erfolgt in Form einer einzigen Welt ausgesetzt, in Nichts, und dass jede Art Element dort enthalten ist, als ein Teil der Welt. Offenbar ist die Oberfläche oder den Bereich ist zu fast gleichen Teilen zwischen den Tiefen des Ozeans und ein gigantischer Kontinent übersät mit aktiven Vulkanen. Wenn die Lavaströme, Erdbeben, Stürme und Tsunamis sind so gewöhnlich wie die Wissenschaftler voraussagen, dann wird die Elementarebene ein sehr gefährlicher Ort zu besuchen. Nun haben die Elementargeister gelernt, Portale zu öffnen und beginnen [[Elementare Invasion]]en. Zu Beginn eines elementaren Invasionöffnen sich Portale auf die elementaren Ebenen und Invasoren sie zu durchschreiten. So wurden während einer Invasion finden Sie zwei bis drei Mal so viele [[Elementare]] in der Gegend, in der Regel etwas höheren Niveau als in den Standard gefunden werden.\r\n \r\nDie Elementarebene ist ein dreistufiges Reich, mit wie viel Schichten einer Zwiebel, um die Sonne auf den Kern des Planeten. Es würde aussehen wie ein gewöhnlicher sphärischer Planet zu einem Außenseiter, mit Reich der Luft ([[Himmelsmauer]]) das über den Ozeanen ([[Abyssischer Rachen]])schwebt und einheitliche Kontinent ([[Tiefenheim]]), mit den [[Feuerlande]]n alsdie tiefste und Außenring. Von innen heraus, die oberste Schicht ist die Domäne der Luft, die mittlere Schicht den Bereichen Wasser und Erde, und die niedrigste Ebene ist die Domäne des Feuers.",},
			["Elementare Invasion"] = { content = "Invasionen von Elementaren treten an verschiedenen Orten in [[Kalimdor]] alle paar Tage sporadisch auf. Besorgte Abenteurer sollten dann [[Silithus]], den [[Un'Goro]] Krater, [[Azshara]] und [[Winterquell]] erforschen, um diese Eindringlinge anzutreffen. Zu Beginn einer Elementaren Invasion werden sich Portale auf die [[Elementare Ebene]] öffnen und Eindringlinge werden beginnen hindurchzuströmen. Somit wird man während einer Invasion zwei bis drei Mal so viele [[Elementare]] in dem Gebiet finden, die auch etwas stärker sind als gewöhnlich. Zu einem bestimmten Zeitpunkt während der Invasion, wird der Elementare Führer erscheinen und beginnen Herausforderungen zu schreien, die im ganzen Gebiet gehört können werden. Während die Elementaren Führer auf [[Kalimdor]] weilen, werden mehr und mehr Eindringlinge auftauchen. Doch wenn der Führer einmal zerstört wurde, werden keine neuen mehr erscheinen, obwohl jene, die bereits da sind, auch bleiben bis sie getötet werden.",},
			["Elementargemische"] = { content = "Weil die Elementare Ebene ein einzelner Ort ist, der alle vier Elementarkräfte in einem einzelnen Gebiet umfaßt, haben sich einige der Wesen der Ebene mehr als einer Region angepaßt. Um das zu tun, haben sie die Aspekte von mehr als einem solcher Gebiete übernommen. Diese Wesen sind als \"Gemische\" bekannt. Jede Art teilt zwei oder mehr Aspekte der ursprünglichen Elementare Arten. \r\nWenn eine Kreatur zwei Elementare Aspekte teilt, ist sie als \"Duales Elementar\" bekannt. \r\nWenn ein Kreatur drei Elementare Aspekte teilt, es ist ein \"Triumvirat-Elementar\". \r\nWenn ein Kreatur alle vier Elementar-Aspekte teilt, ist es ein \"reines\" oder \"ursprüngliches\" Elementar\". \r\nZu den Elementargemischen zählen:\r\n* [[Arkanelementar]]e\r\n* [[Eis-Elementare]]\r\n* [[Lava-Elementare]]\r\n* [[Staubelementare]]",},
			["Elementarsplitter"] = { content = "G.L.A. Das sind die Buchstaben, die in die Elementarsplitter eingeprägt sind, die man im [[Ödland]] findet. Unter den Initialen findet sich eine Markierung für einen Rang oder etwas in der Art. Die Maschinen in der [[Brennende Steppe|Brennenden Steppe]] hatten den 'Rang IV', ein eher niedriger Rang.",},
			["Elfen"] = { content = "Das Wort '''Elfen''' bezeichnet\r\n* die [[Nachtelfen]] (Kaldorei), Bewohner [[Kalimdor]]s, dem ältesten Volk [[Azeroth]]s.\r\n* die [[Blutelfen]] (Sin'dorei), Bewohner der nördlichen Wälder [[Lordaeron]]s.\r\n* die [[Hochelfen]] (Quel'dorei), ehemals [[Hochgeborene]] der [[Nachtelfen]].",},
			["Elfenbeinglocke"] = { content = "Die '''Elfenbeinglocke''' ist eine Pflanze die in der [[Biokuppel Mittelreich]] im [[Nethersturm]] in kleinen Büschen um größere Pflanzen herum wächst. Die [[Expedition des Cenarius]] ist sehr begierig darauf, Zugang zu den Pflanzen in den [[Biokuppel]]n im [[Nethersturm]] zu erlangen, besonders zu dieser, denn sie ist für Ihre heilenden Kräfte bekannt und die heilende Wirkung der Pflanze muss überragend sein.",},
			["Elixier der Pein"] = { content = "Das Elixier der Pein besteht aus fein-gemischten Morastschnauzenkappen und dem Paste des Verfalls von [[Meisterapotheker Faranell]] in [[Unterstadt]]. Damit die verunreinigenden Agenzien in der Morastschnauzenmixtur aktiviert werden, benötigt man starken Trollbluttrank, sowie einige [[Naga der Säbelflossen|Säbelflossenschuppen]] und [[Murlocs der Fetzenflossen|Fetzenflossenaugen]] von der Südküste des [[Vorgebirge des Hügellands|Hügellands]].",},
			["Elixier der Schmerzen"] = { content = "Das '''Elixier der Schmerzen''' ist die neueste Kreation von [[Apotheker Lydon]] aus [[Tarrens Mühle]] und besteht aus frischem [[Löwe|Berglöwenblut]] aus dem [[Vorgebirge des Hügellands]]. Forschungen der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] führen zu der Annahme, dass sich aus Berglöwenblut ein vorzüglicher Todestrank herstellen lässt. Wenn die Berechnungen der [[Apotheker]] korrekt sind, sollte dieses Gebräu der Anfang von etwas Wunderbarem für Lady [[Sylvanas Windläufer]] sein. Doch er muss erst einen Testlauf machen. ... an Stanley, dem kleinen Hund von [[Bauer Ray]], im nördlichen Hof in den [[Felder des Hügelland|Feldern des Hügellands]].",},
			["Elixier des Leidens"] = { content = "[[Apotheker Lydon]] von der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] in [[Tarrens Mühle]] betreibt intensive Forschungen für ein \"Elixier des Leidens\", denn je schneller sie die [[Menschen]] im [[Vorgebirge des Hügellands]] erkranken lassen können, desto besser. Er hat intensive Studien über mögliche tödliche Zutaten für seine Gebräue durchgeführt, aber er hat nicht die Zeit, sie alle zu sammeln. Und so braucht er z.B. Graubärzungen und Krabblersekret. Es wird einen Moment dauern, die Komponenten zu vermengen, damit ein Elixier des Leidens entsteht. Die [[Dunkle Fürstin]] hat es sowohl für [[Menschen]] als auch für die [[Geißel]] geplant.",},
			["Elrendarsee"] = { content = "Der See im Norden wird seit langer Zeit von den Geistern der Ahnen heimgesucht. Die armen Seelen waren Opfer eines tragischen Unfalls, bei dem etliche von Ihnen am Grund des Sees ertranken. Die Ursache dieser Geschehnisse ist längst in Vergessenheit geraten, aber ihre quälenden Schreie erinnern noch heute an ihren Fluch. Jedes Jahr haben die Einwohner von Sonnenkuppe, an einem Ritual teilgenommen, um die verschiedenen Aspekte der Natur unter ihrer Kontrolle zu halten. Die Herrschaft über das Wasser wurde symbolisiert durch die Beschwörung und Versklavung eines [[Wasserelementar]]s namens [[Aquantion]]. Während des Rituals trugen sie wellenförmige Medaillons. Sie liegen nun auf dem Grund des Sees und man benötigt sie, um die Geister ihrer Kameraden zu befreien.",},
			["Elrud"] = { content = "Ich, [[Elrud]], wuchs im [[Eschental]] auf. Eine Hand voll [[Menschen]], Brüder des Opus Lux, hatten dort ein Kloster errichtet, das die Elfen Ordil'Aran nannten. Die Brüder dort zogen mich auf und lehrten mich Gut von Böse zu unterscheiden und die Lehre vom Gleichgewicht - meine Kräfte für Heilung einzusetzen, aber auch zum Schutz vor Angriffen dunkler Mächte.\r\nZum Gleichgewicht gehörte es, neben der Kontemplation auch einem ehrbaren Handwerk nachzugehen. So lernte ich den Umgang mit edlen Stoffen. Der Zauberei ging ich erst in \r\nspäteren Jahren nach, als sich gewisse Fähigkeiten bemerkbar machten.\r\nVon meiner Familie weiß ich nichts, auch nicht, wie ich ursprünglich nach [[Eschental]] gelangt bin - und Gerüchten schenke ich kein Ohr. Im Laufe der Zeit bildete sich aber eine tiefe Freundschaft zu einem [[Elfen]], dem ich in der Umgebung des Klosters begegnet war. Die Bindung zu [[Salix]] war so groß, dass er für mich wie ein Bruder war. Wir sprachen darüber und fortan nannten wir uns gegeseitig 'Cousin', da wir für Brüder doch offensichtlich zu unterschiedlich waren. Er war zum Schutze vor den [[Untote]]n aus dem [[Smaragdgrüner Traum|smaragdgrünen Traum]] geweckt worden.\r\nDoch es half alles nichts, die [[Brennende Legion|brennenden Legionen]] fielen über das Land her und wir entkamen nur mit knapper Not der Zerstörung. Auch das Kloster wurde zerstört - nunmehr sind nur noch die Ruinen ein mahnendes Zeichen alter Zeiten.\r\nMeiner 'Heimat' beraubt machte ich mich auf zu einer Pilgerreise durch die Welt, um denen, die mir begegneten Trost und Halt zu spenden. So kam ich eines Tages auch durch das [[Eisklammtal]], wo ich mich in einer kleinen Höhle für eine Weile einquartierte, um meine Fertigkeiten zu verbessern und Zeit dem Gebet zu widmen.\r\nDort begegnete ich einer kleinen Magierin, die mich mit lebensnotwendigen Dingen versorgte und der sich mein Herz schnell aufschloss. Sie heißt [[Drakeia]] und ich kann sie zu Recht meine Freundin nennen. Sie begleitete mich in die große Zwergenstadt [[Eisenschmiede]], wo ich [[Mondran]] traf. Drakeia war ihm schon bekannt und so \r\nkamen wir schnell ins Gespräch. Auch [[Andruin]] setzte sich später in der Schenke zu uns.\r\nWas diese beiden über [[die Wandersleute]] erzählten, interessierte mich brennend und ich \r\nwar so begeistert, dass ich mich ihnen sogleich anschloss.\r\nAchja, ich angele gern in meiner Freizeit und bereite daraus köstliche Mahlzeiten zu. Vielleicht ergibt sich ja mal die Gelegenheit ... \r\n'''Quelle:'''",},
			["Elune"] = { content = "Elune ist die Göttin des Mondes, eine der wenigen echten Gottheiten von [[Azeroth]].\r\n==Facetten einer Göttin==\r\nElune wurde von den [[Nachtelfen]] und anderen [[:Kategorie:Volk|Völkern]] seit uralten Zeiten als Patronin der Heilung, des Friedens und der Toleranz verehrt. Doch die Mondmutter ist keine Göttin, die Frieden um jeden Preis fordert oder fördert. Eine der Facetten dieser Göttin ist die Nachtkriegerin, die der Legende zufolge die tapferen Gefallenen vom Schlachtfeld aufnimmt und sie als Sterne über den Nachthimmel reiten lässt.\r\nLange vor der Großen Teilung hat sich ein [[Priester]]orden dem Dienst an Elune gewidmet. Der oberste Rang dieses Ordens nennt sich \"[[Schwestern von Elune]]\", und wie der Name schon anzeigt, gehören ihm nur Frauen an. Ihre Schlachtengesänge können Elunes Zorn auf den Feind herabrufen, und ihre Gebete heilen selbst die Schwerverletzten.\r\n==Jenseits der Göttlichkeit: Frau und Mutter==\r\nElune wurde niemals in körperlicher Form auf [[Azeroth]] gesehen. Sie ist ebenso sehr eine Sammlung von Idealen wie eine eigene Persönlichkeit. Als mächtige und geistige Göttin ist sie im Grunde ein körperloses Wesen. Trotzdem wird sie oft als bezaubernd schöne [[Nachtelfen|Nachtelfin]] dargestellt, mit einem einfachen Platinreif und umgeben von einem silbernen Leuchten. Künstler bilden sie auch fast immer mit langem weißem Haar, alabasterfarbener Haut und Augen aus reinstem Mondlicht ab.\r\nSoweit bekannt ist, hatte Elune nur einen einzigen Geliebten: den Halbgott [[Malorne]]. Ihr gemeinsames Kind, [[Cenarius]], erbte eine machtvolle Kombination aus der Liebe seiner Mutter zu allen Geschöpfen [[Azeroth]]s und der Verbindung seines Vaters zum Smaragdgrünen Traum. Bei den [[Tauren]] gibt es eine Sage, die angeblich die Geschichte der Empfängnis von [[Cenarius]] erzählt.\r\nEs gibt bis auf den heutigen Tag das Gerücht auf [[Azeroth]], dass [[Ysera]] die Träumerin in Wirklichkeit die Mutter von [[Cenarius]] sei. Diese Gerüchte sind nicht wahr, auch wenn es verständlich ist, dass die enge Beziehung zwischen Ysera und [[Cenarius]] zu einer gewissen Verwirrung führen konnte.\r\n'''Quelle:''' wow-europe.com",},
			["Elwynn"] = { content = "#REDIRECT [[Wald von Elwynn]]", redirect = "Wald von Elwynn",},
			["Enklave der Blutschuppen"] = { content = "#REDIRECT [[Naga der Blutschuppen]]", redirect = "Naga der Blutschuppen",},
			["Enklave der Weltenwanderer"] = { content = "Diese Enklave in den [[Geisterlande]]n ist der Sitz der [[Weltenwanderer]] in diesem Gebiet.\r\n==Personen==\r\n* '''[[Königliche Apothekervereinigung|Apotheker]] Venustus''' wurde von den [[Weltenwanderer]]n angeheuert, um ihnen bei der Lösung ihres Trollproblems behilflich zu sein. Er verfügt über eine Reihe hochwirksamer Gifte. Trolle sind lebende Wesen, und müssen daher regelmäßig Nahrung zu sich nehmen. Wenn sie also etwas Gift unter man Essen mischen... nun, das Resultat dürfte sehr unterhaltsam sein.\r\n* '''Hauptmann Helios''' möchte das Arsenal der Waldschattentrolle. Es wäre eine Verschwendung die Waffen zusammen mit den Trollen verrotten zu lassen und die Blutelfen könnten sie im Kampf gegen die Geißel einsetzen. \r\n* '''[[Waldläufer]] Krenn’an''' möchte, dass man beim nahegelegenen See rachsüchtige und ruhelose Erscheinungen tötet.\r\n* '''[[Waldläufer]]in Salissa''' wurde von Waldläuferin Valanna in die Enklave entsandt, um Verstärkung anzufordern.\r\n* '''[[Waldläufer]]in Vynna''' ist auf einige wichtige Informationen über [[Dar'Khan Drathir]] gestoßen und folgt nun dem Schatten des Verräters.\r\n* '''Weltenwanderin Solanna''' wurde vom Hauptmann damit beauftragt, die regelmäßigen Störangriffe auf die Lager der Waldschattentrolle zu überwachen. \r\n* '''Weltenwanderin Sedina''' möchte, dass man Geisterklauenluchse erschlägt und der Seuche Einhalt gebietet.",},
			["Entschlüsselter Schattenhammertext"] = { content = "Die '''Entschüsselten Schattenhammertexte''' erhält man, wenn man [[Ortell der Einsiedler|Ortell dem Einsiedler]] in [[Silithus]] 10 [[Verschlüsselte Schattenhammertexte]] bringt, denn nur er als ehemaliges Mitglied des [[Schattenhammer Kult]]es ist in der Lage diese zu übersetzen. Die Schattenhammertexte wurde zur umgehenden Verteilung an alle Mitglieder des Schattenhammerkultes verfaßt.\r\n===Ausgabe 1===\r\nWoher wissen wir, ob sie uns lieben? Einige von uns fragen sich sicher, wie kann es sein, dass diese alten Götter und ihre Diener uns lieben? Töten sie uns denn nicht? Bringen sie uns denn nichts anderes als Schmerz und Leid? Wie können Wesen, die sich so sehr von der Macht des Bösen einnehmen lassen, so etwas wie Liebe in ihren Herzen empfinden? Doch auf diese vermeintlich schwere Frage, gibt es eine einfache Antwort. So simpel, das wir sie nicht auszusprechen brauchen! Glaube. Der Glaube ist der Brunnen, welcher unsere Freude am Dienen speist. Der Glaube alleine vermag uns in diesen kalten Nächten, im Schoße [[Silithus]]', zu wärmen. Am Ende aller Tage, ist es dieser Glaube, welcher uns die Gunst unseres Herrn sichern wird. Der Glaube wird uns erretten.\r\n===Ausgabe 2===\r\nDer Text wurde vom [[Bewahrer des Schattenhammers Havanuth]] verfaßt und beschreibt die ordnungsgemäße Benutzung eines Windsteins, zur Kontaktaufnahme mit den Meistern im abyssischen Rat. Die leichtfertige und unerlaubte Benutzung eines Windsteins zieht eine harte und schmerzvolle Bestrafung nach sich!\r\n===Zur Lage des Kultes Ausgabe 92===\r\nFreudigen Herzens schreibe ich Euch diese Zeilen, meine Brüder und Schwestern, denn nie ging es dem Kult besser als heute! Die Zahl unserer Anhänger wächst stetig und schon bald werden wir unsere Ziele erreichen. Täglich verstärken neue Rekruten unsere Reihen. In [[Dunkelküste]] stimmen sie Lobeslieder auf unsere Meister an, in der [[Sengende Schlucht|Sengenden Schlucht]] feiern sie das Kommende in grenzenloser Begeisterung, und in der [[Tiefschwarze Grotte|Tiefschwarzen Grotte]] lobpreisen sie die Gesandte unseres Meisters, [[Aku'mai]]. Nicht mehr lange, und unsere Anhänger werden ganz Azeroth einnehmen!\r\n===Zur Lage des Kultes, Ausgabe 233===\r\nWieder einmal hat das Schicksal uns eine Prüfung auferlegt, meine Brüder und Schwestern! Der Zirkel des Cenarius, ein Kult übler Naturliebhaber, entsendet seine Agenten gegen uns. Offensichtlich will man uns daran hindern, weiterhin rote Magiesteine zu beschwören. Dies können und werden wir nicht zulassen!! Die roten Steine sind von äußerster Wichtigkeit für unsere neuen Verbündeten. Der Zirkel des Cenarius wird mit seinem Vorhaben scheitern. Bewahrt den Glauben, meine Freunde. Bewahrt den Glauben!",},
			["Entstehung der Geißel"] = { content = "== Entstehung der Geißel==\r\nNach [[Kel'Thuzad]]s Erfolg in [[Lordaeron]] traf der [[Lichkönig]] letzte Vorbereitungen für seinen Großangriff gegen die menschliche Zivilisation. Ner’zhul füllte seine Seuchen-Energien in eine Reihe tragbarer Artefakte, die [[Seuchenkessel]] genannt wurden, und befahl Kel’Thuzad, die Kessel nach Lordaeron zu bringen, wo sie in den zahlreichen vom [[Kult der Verdammten]] beherrschten Dörfern versteckt werden sollten. Die von den getreuen Kultisten beschützten Kessel sollten als Seuchengeneratoren fungieren und die [[Seuche]] unter den ahnungslosen Bürgern der Landstriche und Städte nördlich von Lordaeron verbreiten. Der Plan des Lichkönigs ging voll und ganz auf. Viele der nördlichen Dörfer von Lordaeron wurden fast auf der Stelle verseucht. Bürger, die sich mit der Seuche ansteckten, starben und erstanden als willige Sklaven des Lichkönigs wieder auf, genau wie in Nordend. Die Kultisten unter Kel’Thuzad waren begierig darauf zu sterben und in den Diensten ihres dunklen Herrn ihre Auferstehung zu erleben. Sie bejubelten die Aussicht auf Unsterblichkeit durch das Dasein als Untote. Und je mehr die Seuche sich ausbreitete, desto mehr wilde [[Zombie]]s erstanden in den Nordländern. Kel’Thuzad betrachtete die wachsende Armee des Lichkönigs und nannte sie die [[Geißel]] – denn bald schon sollte sie zu den Toren von Lordaeron marschieren ... und die Menschheit ausrotten.",},
			["Entstehung des Lichkönigs"] = { content = "== Entstehung des Lichkönigs==\r\nDie Klans der [[Orcs]], die Jahrtausende lang durch eine edle schamanistische Kultur an die Welt [[Draenor]] gebunden waren, kannten weder spirituelle Korruption noch Verderbnis. Doch die finsteren Agenten der [[Brennende Legion|Brennenden Legion]] trachteten danach, eine unersättliche, unaufhaltsame Armee aus ihnen zu machen. Der verschlagene Dämon [[Kil'jaeden]], zweiter Befehlshaber der Legion, erkannte gleich, dass die wilden Krieger ein enormes Potenzial für Mord und Blutvergießen hatten – und machte sich daran, ihre gefestigte Gesellschaft von innen heraus zu verderben. \r\nKil’Jaeden erschien dem angesehensten Führer der Orcs, dem Ahnenschamanen [[Ner'zhul]], und flüsterte ihm ein, dass er den Orcs große Macht geben und sie zu den unangefochtenen Herrschern ihrer Welt machen würde. Er bot dem alten [[Schamanen]] unermessliches mystisches Wissen an, wenn er einwilligte, sich und sein Volk dem Willen der Legion zu unterwerfen. Der von Natur aus berechnende und machtgierige Ner’zhul nahm Kil’jaedens Angebot an und schloss einen Blutpakt mit dem Dämon. \r\nDamit hatte Ner’zhul das Schicksal der Orcs besiegelt und sie dazu verdammt, geistlose Sklaven der Brennenden Legion zu werden. Mit der Zeit wurde Kil’jaeden jedoch klar, dass Ner’zhul weder den eisernen Willen noch die Kühnheit besaß, den Plan, aus den Orcs eine blutgierige Horde zu machen, in die Tat umzusetzen. Ner’zhul seinerseits erkannte, dass sein Pakt mit Kil’jaeden zur Auslöschung seines Volkes führen würde, und verweigerte dem Dämon jede weitere Zusammenarbeit. Erbost von der Weigerung des Schamanen, schwor Kil’jaeden Ner’zhul bittere Rache und gelobte, die Orcs dennoch in die Verderbnis zu führen. Kil’jaeden fand einen neuen und eifrigen Schüler, der die Orcs auf den Weg des Verderbens führen sollte – Ner’zhuls ruchlosen Protegé [[Gul'dan]]. Mit Kil’jaedens Hilfe gelang Gul’dan, was sein Lehrmeister nicht vermocht hatte. Der böse, machtgierige Orc schaffte nicht nur die uralte Praxis des Schamanismus ab, den er durch das Studium der dämonischen [[Hexenmeister]]-Magie ersetzte, sondern vereinigte die Orc-Klans auch zu der willfährigen wilden Horde, die Kil’jaeden erwartet hatte. Ner’zhul besaß nicht die Macht, seinen einstigen Schüler aufzuhalten, und musste tatenlos mit ansehen, wie Gul’dan die Orcs meisterlich zu geistlosen Lakaien der Zerstörung machte.\r\nJahre vergingen, in denen Ner’zhul stumm auf der glutroten Welt Draenor brütete. Er sah mit an, wie sein Volk die erste Invasion von [[Azeroth]] in Angriff nahm. Er hörte Geschichten über den Zweiten Krieg der Orcs gegen die Allianz von Lordaeron. Er wurde Zeuge von Verrat und Verderbnis, die sein Volk von innen heraus zu zerstören schienen. Auch wenn Gul’dan das finstere Schicksal der Horde gestaltete, so wusste Ner’zhul doch, dass er selbst die Verantwortung dafür trug, dass alles so gekommen war.\r\nKurz nach dem Ende des Zweiten Krieges drang die Kunde von der Niederlage der Horde zu den Orcs, die auf Draenor geblieben waren. Ner’zhul wusste, dass es der Horde nicht gelungen war, Azeroth zu erobern, und er befürchtete, dass Kil’jaeden und die Legion die restlichen Orcs drakonisch bestrafen würden. Um Kil’jaedens unmittelbarem Zorn zu entgehen, öffnete Ner’zhul eine Anzahl mystischer Portale, die zu neuen, unberührten Welten führten. Der alte Schamane scharte die verbliebenen Orcs um sich und hatte vor, sie durch eines der Portale in ein neues, anderes Schicksal zu führen.\r\nAber bevor er seinen Plan umsetzen konnte, war Ner’zhul gezwungen, sich mit dem Stoßtrupp der Allianz auseinander zu setzen, der nach Draenor geschickt worden war, um die Orcs für alle Zeiten zu vernichten. Ner’zhuls loyalen Klans gelang es, die Streitmacht der Allianz aufzuhalten, während der alte Schamane die tosenden magischen Portale öffnete. Zu seinem Entsetzen musste Ner’zhul dabei erkennen, dass die gewaltigen Energien der Portale Draenor im innersten Kern zerstörten. Während die Truppen der Allianz die Orcs weiter in die Höllenwelt zurücktrieben, wurde Draenor von Erdbeben erschüttert. Als Ner’zhul klar wurde, dass die kämpfenden Klans es nie und nimmer rechtzeitig zu den Portalen schaffen würden, überließ er sie egoistisch ihrem Schicksal und floh mit der Elite seiner Anhänger im Schlepptau. Die Gruppe der bösen Orcs durchquerte das gewählte Portal in dem Augenblick, als Draenor in einer apokalyptischen Explosion zerstört wurde. Der alte Schamane glaubte, er könne sich glücklich schätzen, dass er dem Tod entronnen war ... Ironie des Schicksals – er sollte überleben und seine Naivität bedauern.",},
			["Eonar"] = { content = "Eonar ist bronzehäutig, trägt einen Alabasterstab namens [[Seschenal]] und Blumenblüten an ihren Füßen. Sie ist die Darstellung des Lebens, der Natur und der Heilung im Universum. Sie ist die Gemahlin von [[Aman'Thul]], dem Hochvater und gewährte [[Alexstrasza]] den Schutz des Lebens und [[Ysera]] den [[Smaragdgrünen Traum]]. \r\n64.000 Jahre vor dem [[Dunkle Portal|Dunklen Portal]] / Ersten Krieg, gab Eonar ehe sie [[Azeroth]] verließ einen Teil ihres Geistes an [[Alexstrasza]] als mächtige lebensgebende Kraft in der Welt. \r\nVor 10.000 Jahren, als die [[Brennende Legion]] das erste Mal in [[Azeroth]] einfiel, bekämpfte Eonar die [[Dämonen]] indem sie die [[Drachen]]-Aspekte mit einem Teil ihrer Kraft erfüllte, um gegen die [[Dämon]]en zu kämpfen. \r\nEinige glauben, dass Eonar auch die [[Tauren|Taurische]] [[Erdenmutter]] ist, obwohl das reine Vermutung ist. Eonar verabscheut [[Untote]], da sie die Verkörperung des Lebens darstellt. \r\nUnter ihren Zaubern sind Massen-Heilung und Großes Böses [[Voodoo]], Flammenschlag, Blitz und Monsun, Klingenmauer, Erdbeben und Mauer aus Stein unter anderen ähnlichen Zaubern. Sie bevorzugt es, sich in der Schlacht auf Distanz zu halten und ist für ihre Verbündeten im [[Pantheon]] eher eine unterstützende Rolle. Wenn sie wütend ist und trotzdem zur Schlacht gezwungen wird, ist sie jedoch furchterregend. Sie wird alles tun, um ihre Feinde zu verwirren und verstreuen, ehe sie in den Kampf geht.",},
			["Epochenjäger"] = { content = "Der [[Epochenjäger]] ist ein Großdrache des [[Ewiger Drachenschwarm|Ewigen Drachenschwarm]], den man als Endboss in den [[Höhlen der Zeit im Vorgebirge des Alten Hügellands]] vorfindet.\r\nIhn zu töten ist Teil der täglich heroischen Aufgabe \"Gesucht: Der Kopf des Epochenjägers\" von [[Windhändler Zhareem]] in [[Shattrath]]. Die Geschmäcker von Zhareems Kunden variieren von banal zu sehr exotisch. Manchmal wollen sie mit den exotischen Gegenständen, die der Windhändler ihnen beschafft, sehr banale Dinge anstellen. Sein momentaner Kunde gehört zu dieser Sorte. Er, dessen Name hier unerwähnt bleiben soll, wünscht sich nichts sehnlicher, als den Kopf des Epochenjägers an seiner Wand aufzuhängen und solange der Kunde des Windhändlers genug Platz an seiner Wand hat, macht sich der Kopf des Epochenjägers dort sicher wunderbar. \r\n==Fähigkeiten==\r\nZu den Fähigkeiten des Epochenjägers gehören:\r\n* '''Drohender Tod''' - Drohender Tod ist ein Stärkungszauber, der alle 24 Sekunden lang 3 Sek. Sek. 750 Schattenschaden zugefügt.\r\n* '''Flügelstoß'''\r\n* '''Magiestörungsaura''' - Die Magiestörungsaura ist ein Stärkungszauber, der 15 Sekunden lang regelmäßig magische Effekte von nahen Gegnern entfernt.\r\n* '''Sandatem''' - Der Sandatem fügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden Arkanschaden zu und verlangsamt ihr Bewegungstempo um 50% und erhöht die Zeit zwischen ihren Angriffen um 100%. Hält 10 Sek. lang an.",},
			["Eranikus"] = { content = "Eranikus der Träumer ist ein [[Grüner Drachenschwarm|Grüner Drache]], der von den [[Alte Götter|alten Göttern]] besudelt wurde. Er ist der Hüter des verfluchten [[Tempel von Atal'Hakkar]] in den [[Sümpfe des Elends|Sümpfen des Elends]] und der Gefährte von [[Ysera]]. \r\nDie grünen Drachen haben die körperliche Manifestation des Gottes [[Hakkar]] vernichtet und seinen Tempel versenkt, aber der Gott war viel stärker, als sie es erwartet hatten. Die Saat der Verderbnis wurzelte tief in dem Tempel und befiel alles, was ihr in die Quere kam. Eranikus wurde damit betraut, den Versunkenen Tempel zu bewachen und aufzupassen, dass weder die einfachen Atal'ai noch ihr Gott wiederkehren. Doch seine Aufgabe schlug fehl und er wurde ein unschuldiges Opfer der Verderbtheit, deren Wirkung die grünen Drachen unterschätzt hatten.\r\nNun fühlt er, wie sich sein [[Smaragdgrüner Traum]] zum Chaos hinbewegt. Zurzeit befindet er sich in einem gefährlichen Zustand zwischen Schlaf und Tod, verstrickt in ein Gewebe aus Alpträumen. Er möchte, dass man einen Edelstein mit seiner magischen Essenz in den Essenzborn legt, der sich im [[Versunkener Tempel|Versunkenen Tempel]] in seinem Unterschlupf befindet, um sie zu reinigen. Aber die Verderbnis des verfluchten Gottes hat sogar die Reinheit seines Essenzborns des [[Grüner Drachenschwarm|grünen Drachenschwarms]] beschmutzt und Eranikus fühlt, wie ihn die Umklammerung eines ewigen Alptraums umschlingt ... Er ist in der Dunkelheit gebunden und nur die [[Druiden]] der [[Mondlichtung]] oder auf [[Burg Cenarius]] können weiterhelfen und das Wasser des Elune'ara Sees wird die Alpträume auflösen, die den Gegenstand mit seiner alptraumhaften Essenz umgeben.",},
			["Erdelementar"] = { content = "Der Himmel, das Wasser, sogar große Feuer - alle Elemente lasten auf den Schultern der Erde und während die anderen Elemente oft in wilden Stürmen toben, hält die Erde geduldig aus. Sie verleiht dem Inneren Stärke und Kraft. Erdelementare sind [[Elementare|Elementarwesen]] aus dem Felsen und der Energie der Erde selbst. Einige Angriffe der Erdelementare verursachen Naturschaden, aber die meisten sind physikalisch. Erdelementare haben ebenso die stärkste Rüstung der Elementare.\r\n==Besondere Elementare==\r\n* [[Fürst der Splitter]]\r\n* '''Gordawg''' – [[Nagrand]]. Zorn der Erde. Questgeber am Thron der Elemente.\r\n* '''Gurok der Thronräuber''' – [[Nagrand]]. Gurok wird von den [[Oger]]n im Totschlägerhügel verehrt. Man ruft ihn, indem man sieben Ogerschädel von Totschlägern auf Guroks irdenes Brandmal setzt.\r\n* '''Lavinius''' - [[Azshara]]. Lavius führt die Donnernden Eindringlinge in [[Azshara]] an. Obwohl er enorm mächtig ist, scheint er bedeutend weniger intelligent als Charr oder Tempestria zu sein. Er schreit Spotts wie: “Wo du verstecken? Mich finden du!” \r\n* '''[[Rok'Alim der Trommler]]'''\r\n* '''Prinzessin [[Theradras]]''' \r\n* '''Wächter der Fam'retor''' – [[Ödland]]. Wird von Lotwil Veriatus beschworen.",},
			["Erdelementare"] = { content = "#REDIRECT [[Erdelementar]]", redirect = "Erdelementar",},
			["Erdenmutter"] = { content = "Die '''Erdenmutter''' ist eine mildtätige Göttin der [[Tauren]]. Die edlen [[Tauren|Stier-Menschen]] glauben, dass diese Gottheit für alle natürliche Schönheit der Welt verantwortlich ist.Sie ist ein weiteres Element der azerothanischen [[Naturanbetung]]. Sie sehen ihr lächelndes Gesicht im Himmel, in Steinen, im Sand und in den Meeren. Die [[Tauren]]-Mythologie beschreibt sie als Erschafferin des Landes und der [[Tauren]]. Die Sonne ([[An'she]]) und der Mond ([[Mu'sha]]) waren ihre Augen. Die Erdenmutter gehört in die [[Tauren]]kultur wie [[Elune]] in die Kultur der [[Kaldorei]]. Beide sind der konstante Faktor im veränderlichen Leben ihres jeweiligen Volkes. Somit ist die Erdenmutter weit wertvoller als ein physikalisches Wesen. \r\n==Verehrung==\r\nVon allen Elementen repräsentiert die Erde das Fundament der Dinge. Sie ist die Kraft, die Ausdauer und die Geduld. Die Erdenmutter wird die Tauren schützen, aber nur, wenn man ihr den angemessenen Respekt erweist. Sie ist die Grundlage des Lebens und wenn man ihre Gesetze achtet, wird einem größeres Wissen zuteil. Mann sollte niemals die Geheimnisse vergessen, die sie mit einem teilt.\r\n===Spekulationen===\r\n'''Therazane'''\r\nViele haben spekuliert, dass die [[Tauren|taurische]] Erdenmutter mit verschiedenen anderen Wesen übereinstimmt. Eine Theorie meint, dass die Erdenmutter [[Therazane]] die Steinmutter ist, ein Elementarer Leutnant der [[Alte Götter|Alten Götter]]. Während die Güte der Erdenmutter und die unbegreifliche Bosheit der [[Alte Götter|Alten Götter]] und ihrer Diener diese Gleichsetzung scheinbar dürftig machen mögen, wird [[Therazane]] als die mildtätigste unter allen vier Elementar-Fürsten beschrieben. Doch die Ur-Rolle, die der Erdenmutter zugeschrieben wird, ist die Erschaffung der Welt selbst, der Sonne und des Mondes, und der [[Tauren]]. Das scheint weit größer als die Kraft, die ein Leutnant der [[Alte Götter|Alten Götter]] gehabt hätte. \r\n'''[[Alexstrasza]]'''\r\nEine andere Theorie behauptet, dass die Erdenmutter [[Alexstrasza]] die Lebensgeberin des [[Roter Drachenschwarm|Roten Drachen]]schwarmes ist. Jedoch wurden die [[Drachen]]aspekte von den [[Titanen]] befähigte, um über [[Azeroth]] zu wachen, und werden nicht als solch eine Hauptrolle in der Erschaffung von [[Azeroth]] beschrieben, wie die Erdenmutter in den [[Tauren|Taurischen]] Mythen. \r\n'''[[Eonar]]'''\r\nDoch auch ein anderes Wesen wird manchmal als die taurische Erdenmutter betrachtet: [[Eonar]], Mitglied des [[Titanen|Pantheon]] und Patronin allen Lebens. In der Formung [[Azeroth]]s durch das [[Titanen|Pantheon]] war sie wahrscheinlich für das Erschaffen der Felder, des Korns und der [[Tauren]] selbst verantwortlich, so wie die Mythen die Erdenmutter beschreiben. Sie war es, die [[Alexstrasza]] und [[Ysera]] befähigte, über ihre kreative Arbeite auf [[Azeroth]] zu wachen. Es könnte sein, dass die Erdenmutter alle [[Titanen]] verkörpert, da es alle [[Titanen]] waren, die [[Azeroth]] erschufen. \r\n'''Elementar-Geist'''\r\nEine andere Theorie ist, dass die Erdenmutter einer der Elementar-Geister ist (entweder der Geist der Erde oder der Geist der Wildnis), oder eine Darstellung von allem. Wahlweise kann die Erdenmutter auch ein unbegründeter Glaube sein - ein Konstrukt, um die Existenz [[Azeroth]]s zu erklären. Ihr Status in der [[Tauren]] Kultur ist ungefähr der selbe wie [[Elune]] in der [[Nachtelfen]]-Kultur. Deswegen ist es möglich, dass die Erdenmutter keines von diesen Dingen ist, sondern etwas ganz anderes.",},
			["Erde von Un'Goro"] = { content = "Die Erde des Kraters ist angeblich reich an starken magischen Eigenschaften. Die angereicherte Erde ist manchmal zu Haufen aufgeworfen und einige der Wildtiere könnten vielleicht nützliche Proben bei sich haben. Der [[Zirkel des Cenarius]] möchte diese Erde in großen Mengen untersuchen.",},
			["Ered'ruin"] = { content = "#REDIRECT [[Verdammniswache]]", redirect = "Verdammniswache",},
			["Eredar"] = { content = "Das Volk der '''Eredar''' entstand vor fast 25.000 Jahren auf der Welt [[Argus]]. Sie waren äußerst intelligent und hatten eine natürliche Begabung für den Umgang mit sämtlichen Formen von Magie. Sie benutzten ihre angeborenen Gaben, um eine gewaltige und wundersame Gesellschaft zu gründen. \r\nAus ihnen gingen die '''[[Draenei]]''' hervor, aber auch die verderbten '''[[Man'ari]]'''. \r\n==Allgemeines==\r\nEredar sind mächtige [[Dämonen]] und eines der ältesten Völker des Universums, aus dem [[Sog der Unterwelt]]. Einige der bekanntesten Mitglieder dieses Volkes sind [[Archimonde]] und [[Kil'jaeden]], beide gefürchtet und gehasst wegen ihrer Grausamkeit und Gerissenheit. Sie stellen die Spitze einer unaufhaltbaren dämonischen Armee dar, deren einziges Ziel die alles umfassende Vernichtung ist. Sie stellen die Befehlshaber und Strategen der [[Brennende Legion|Brennenden Legion]]. \r\n===Fähigkeiten===\r\nAußergewöhnlich begabt in allen Formen der Magie, sind die Eredar für ihre Beherrschung der arkanen Künste in den verstreuten Welten des [[Großes Dunkles Jenseits|Großen dunklen Jenseits]] bekannt. Ihre heimtückischen [[Hexenmeister]] entfesseln die chaotischen Kräfte von Entropie und Zerstörung, um die jenseitigen Reiche zu unterwerfen. \r\n===Charakter===\r\nDie Eredar sind ein Dämonenvolk, das danach trachtet, Macht und Vorherrschaft über das stoffliche Universum zu erlangen. Legenden zufolge zerstörten die Eredar ihre eigene Dimension und sind nun dazu verdammt, die magischen Energie des lebenden Universums zu verschlingen. Ganze Welten sind seither durch die Chaosmagie der Hexenmeister verbrannt worden und im Laufe von Äonen hat ihr unstillbarer Hunger zahllose Völker ausgerottet. Die gewaltigen Kräfte der teuflischen Zauberer ließen die versklavten Bewohner einiger Welten sogar mutieren und selbst zu Dämonen werden. \r\n===Die Verderbnis der Eredar===\r\nDer Titan [[Sargeras]] kämpfte gegen die dämonischen Wesenheiten und besiegte sie, doch die Verderbnis und das alles verschlingende Böse dieser Kreaturen beunruhigten ihn zutiefst. Da der große [[Titan]] außerstande war, dieses Maß an Verworfenheit und Bösartigkeit zu verstehen, verfiel er in eine tiefe Depression. Doch trotz seines zunehmenden Unbehagens wollte Sargeras das Universum für alle Zeiten von den [[Hexenmeister]]n befreien, indem er sie in einem Winkel des [[Sog der Unterwelt]] in einem Vakuum einsperrte. \r\n[[Sargeras]] wurde nicht mit den nagenden Zweifeln und der Verzweiflung fertig, die seine Sinne überwältigten, und verlor nicht nur den Glauben an seine Mission, sondern auch an die Vision der [[Titanen]] von einem geordneten Universum. Er kam zur Überzeugung, dass allein schon die Vorstellung von Ordnung töricht sei - und Chaos und Verderbnis die einzigen absoluten Konstanten im dunklen, einsamen Universum seien.\r\n===Die ersten Diener der Legion===\r\nAls der Wahnsinn den letzten Rest seiner edlen Gesinnung verdrängt hatte, befreite er die [[Nathrezim]] aus ihrem Gefängnis. Dieses Dämonenvolk schloss sich Sargeras Mission, alle Welten zu vernichten, mit Freuden an. Schon bald entdeckte Sargeras eine abgelegene Welt namens [[Argus]]. Dort existierte ein magisch hochbegabtes Volk namens Eredar, in welchen der Dunkle Titan großes Potenzial sah. Er bot den drei Anführern der Eredar an, sich mit ihm zu verbünden. Zwei namens [[Kil'jaeden]] und [[Archimonde]] nahmen an und Sargeras verwandelte alle, die diesen beiden folgten, in die ersten empfindungsfähigen Mitglieder seiner Armee. Bis heute ist die alte Sprache der Eredar([[Eredun]]) die Hochsprache der Brennenden Legion.",},
			["Eredun"] = { content = "'''Eredun''' ist die Sprache der [[Dämonen]] und der [[Brennende Legion|Brennenden Legion]]. Sie stammt von den [[Eredar]] und ist verwandt mit dem [[Draenisch]]en. Sie kann, einmal gehört oder gelesen, nicht vergessen werden und hat schon oft [[Magier]] in den Wahnsinn getrieben, da sie sie bis zur Bessessenheit an das Entschlüsseln der Worte bindet. In [[Eredun]] sind die mächtigsten Formeln und Zauber der [[Hexenmeister]] niedergeschrieben.\r\n==Worte==\r\n* A-Rul shach kigon = Ich werde dein Herz essen\r\n* Achor sie-kil = Fasst, meine Hunde \r\n* Azhir uval nutarus. Azhir Mudas ethanul. Dalektharu il dask daku. Riftuuz e thara samanaar utamus. Elas umanes azarathan rakas ibna = Aus dieser Narbe soll der erste Schlag gegen die sterbliche Welt aufsteigen. Lasst dieses Siegel den Untergang der Menschen bedeuten, welche in ihrer Torheit glaubten, Macht über unser Feuer zu besitzen und welche ihre Reiche blind auf geraubtem Wissen errichteten. Nun lasst sie von den Flammen verzehren, welche sie zu kontrollieren glaubten.\r\n* Belanora mordanus nenaar ila mornu farlos wann = Soll das Echo ihrer Schreie alle, die es hören, in Verzweiflung zurücklassen.\r\n* [[Ered'ruin]] = [[Verdammniswache]]\r\n* Galtak Ered'nash = Alle Macht der [[Sengende Klinge|Sengenden Klinge]]\r\n* Thal'kituun = Verborgener Gast",},
			["Erntedankfest"] = { content = "Das Erntedankfest ist die Zeit des Erntedankfests, die Zeit großer Gaben und die Zeit der Erinnerung. Eine Zeit, um den Helden der Geschichte [[Azeroth]]s zu gedenken. Die Allianz ehrt ihre Gefallenen, aber vor allem [[Uther Lichtbringer]], den Gründer der Ritter der [[Silberne Hand|Silberhand]]. Die [[Horde]] ehrt ihrerseits [[Grom Höllschrei]] für seine Taten. \r\n==Die Helden ehren==\r\nIn der Geschichte von [[Azeroth]] haben viele ihr Leben gelassen, um ihren Verbündeten zu helfen. Und so nehmen sich Hordler und Mitglieder der [[Allianz]] jedes Jahr die Zeit, diesen Helden zu gedenken. Dabei wird dieses Jahr im Zeichen zweier wichtiger Personen der Geschichte Azeroths stehen: [[Uther Lichtbringer]] für die [[Allianz]] und [[Grom Höllschrei]] für die [[Horde]]. Die Mitglieder der beiden Fraktionen sollten sich eine Ruhepause von ihren Abenteuern nehmen, um das Grab dieser Größen zu besuchen und ihnen an ihrem Grabmal einen Tribut darzubringen. So werden die Mitglieder der [[Allianz]] dazu aufgerufen, eine Kerze am Grab von [[Uther Lichtbringer]] in den westlichen Pestländern anzuzünden und die Mitglieder der [[Horde]] bringen einen Tribut zu Füßen des Höllschrei-Monumentes im Dämonensturz in [[Eschental]]. \r\nAbenteurer werden die Geister der Gefallenen vor [[Orgrimmar]] und [[Eisenschmiede]] sehen und können sich einen Augenblick Zeit nehmen, um mit einem Krug Erntedanknektar auf die Helden vergangener Zeiten anzustoßen. Es wird ein Festessen für alle vorbereitet sein, um die Abenteurer nach ihrer langen Reise zum Grab ihres Helden zu stärken. Sie können ihren Hunger mit Erntedankfisch stillen, mit Erntedankobst, Erntedankeber und ihren Durst mit Erntedanknektar löschen. \r\n==Belohnungen==\r\nNachdem ihr die Reise zum Grab eures Helden gewagt und ihn dort geehrt habt, kehrt zurück zu Javnir Nashak vor [[Orgrimmar]] oder Wagner Hammerstrike vor [[Eisenschmiede]], um eure Belohnung zu empfangen: \r\n* Höllschrei, Held der Horde\r\n* Für das Licht! \r\n==Festtagsessen==\r\nUm der gefallenen Helden zu gedenken, wird es vor Eisenschmiede und Orgrimmar ein Festessen geben. Abenteurer werden eingeladen, an den Feierlichkeiten teilzunehmen und sich für die kommenden Abenteuer zu stärken. \r\n'''Quelle''':",},
			["Erntegolem"] = { content = "'''Erntegolems''' wurden von den [[Goblin]]s für die [[Defias]] hergestellt. Drei Eigenschaften machen sie so gefährlich, wie sie sind: Ihr harmlosees Aussehen, ihre gnadenlose Kampftaktik und seine Schnelligkeit. Aus der Entfernung hält man diese Wesen häufig für harmlose Vogelscheuchen, bis die Klingen, die sie als Finger haben, denjenigen eines besseren belehren. \r\nDie ersten Erntegolems waren plump und zerfielen sehr schnell. Doch die [[Goblin]]s bewiesen wieder einmal, warum sie eines der erfindungsreichsten Völker [[Azeroth]]s sind und nun terrorisieren diese Gesellen ganz [[Westfall]].\r\nAngetrieben werden diese Konstrukte mit einer alchemistischen Lösung und [[Magie]].",},
			["Erzbischof Alonsus Faol"] = { content = "Der alte '''Erzbischof Alonsus Faol''' war der Anführer des Heiligen Ordens der [[Kleriker von Nordhain]], Gründer des [[Orden der Silbernen Hand|Ordns der Silbernen Hand]] \r\nVor dem [[Der Erste Krieg|Ersten Krieg]] brachte der Heilige Orden der [[Kleriker von Nordhain]] die Nachricht vom Heiligen Licht zum Königreich von [[Sturmwind]]. In der folgenden Invasion der [[Orcs]] führte Erzbischof Alonsus Faol die Kleriker in die Schlacht, um den Soldaten des Königreiches zu helfen. Doch die [[Kleriker]] waren auf die Gefahren des Kampfes nicht vorbereitet und erlitten schwere Verluste. Das bewegte Faol zusammen mit seinem Lehrling [[Uther Lichtbringer]] den alten Orden als [[Orden der Silbernen Hand]] neu zu gründen. Dieses Mal wurden Faols Anhänger auch in den Künsten des ehrvollen Kampfes unterrichtet. [[Uther Lichtbringer]] war der erste Schützling, der in diesem Zuge in der [[Alonsuskapelle]] in [[Stratholme]] zum [[Paladin]] ernannt wurde. Im folgenden [[Der Zweite Krieg|zweite Krieg]] kehrte Erzbischof Faol nach [[Sturmwind]] zurück, um beim Wiederaufbau von [[Sturmwind]] zu helfen. Eine große Statue samt Springbrunnen erinnert heute vor der [[Kathedrale des Lichts]] an Faols Taten. Erzbischof Alonsus Faol gründete in [[Nordhain]] einen neuen Orden: die [[Bruderschaft von Nordhain]]. Faol starb aus unbekannten Gründen (wahrscheinlich einfach aufgrund seines hohen Alters) kurz vor dem Ausbruch der [[Seuche]]. Seine Überreste wurden vermutlich in [[Faols Ruheplatz]], einem Friedhof nahe des [[Scharlachrotes Kloster|Scharlachroten Klosters]], beigesetzt.",},
			["Erzdruide Fandral Hirschhaupt"] = { content = "Der '''Erzdruide Fandral Hirschhaupt''' hält sich auf der obersten Etage des Turms des Cenarius in [[Darnassus]] auf. Er scheint immer in Eile zu sein, doch der Wald weiß, dass gut Ding Weile braucht. Shan'do Sturmgrimm hat das verstanden. Fandral ist der Meinung, dass ER die [[Nachtelfen]] aus der Dunkelheit geführt hat und NICHT der [[Zirkel des Cenarius]] auf der [[Mondlichtung]], als für sein Volk alles verloren war. [[Teldrassil]] gibt ihnen allen neues Leben. Fandral benutzt momentan den Namen des Zirkel des Cenarius sowie dessen Mittel, um große Mengen [[Morgenkorn]] zu beschaffen, denn er hat vor, dieses Geheimnis zu enthüllen. \r\n==Hintergrund==\r\nNachdem Erzdruide [[Malfurion|Malfurion Sturmgrimm]] in ein rätselhaftes Koma fiel, wurde Erzdruide Fandral Hirschhaupt der Anführer aller [[Druiden]] auf [[Azeroth]]. Seine erste Amtshandlung als Erzdruide war es, den restlichen [[Zirkel des Cenarius]] zu überreden, [[Teldrassil]] wachsen zu lassen, den zweiten Weltenbaum. Sein Hauptargument war, dass [[Teldrassil]] letztendlich den [[Nachtelfen]] ihre Unsterblichkeit zurückgeben würde, die sie während des Dritten Krieges geopfert hatten. Diese Hoffnung blieb allerdings bis heute unerfüllt.\r\nFandrals Frau starb im Kindbett bei der Geburt ihres Sohnes, [[Valstann Hirschhaupt]], was die Beziehung zwischen Fandral und Valstann sehr stark werden ließ. Als Valstann im Krieg der Sandstürme fiel, verzweifelte Fandral völlig. Er ist besessen von der Idee, seinen Sohn ins Leben zurückzurufen. Der Erzdruide schwor nie wieder mit den [[Qiraji]], den [[Drachen]] oder [[Silithus]] etwas gemein zu haben, da er ihnen allen die Schuld am Tod seines Sohnes gab.\r\n===Erfahrung und Zwiespalt===\r\nTrauer und Bitterkeit haben Fandrals Charakter sehr zu seinem Nachteil verändert. Er hat bei der rücksichtslosen Suche nach seinem verlorenen Sohn viele harte Entscheidungen getroffen, und jede fiel ihm etwas leichter als die vorherige. Schon vor einigen hundert Jahren hat er aufgehört, seine eigenen Entscheidungen jemals in Frage zu stellen. Für viele [[Nachtelfen]] ist diese Haltung ein Ausdruck berechtigten Selbstvertrauens, andere aber halten ihn einfach für arrogant. Fandral selbst kümmerte es nicht, was andere über ihn dachten, solange sie ihm aus dem Weg gingen.\r\nObwohl Fandral eigentlich nur dem kleinen [[Zirkel des Cenarius]] als politischer Anführer vorsteht, ist er überzeugt, dass nur er auch den besten Weg für die gesamte [[Nachtelfen]]gesellschaft kennt. Er hatte eine recht schlechte Meinung von der Hohe[[priester]]in [[Tyrande|Tyrande Wisperwind]], die seit dem Krieg der [[Urtume]] die alleinige Anführerin der [[Nachtelfen]]gesellschaft war. Fandrals Auseinandersetzungen mit [[Tyrande]] sind allerdings nicht allgemein bekannt, nur die höchsten [[Druiden]] und [[Priester]]innen der [[Elune]] wissen um den Zwiespalt zwischen [[Tyrande]] und Fandral.\r\n'''Quelle:'''",},
			["Erzdruide Hamuul Runentotem"] = { content = "Als Freund von [[Cairne Bluthuf]] seit Kindertagen fungiert '''Erzdruide Hamuul Runentotem''' als der Druidenälteste von [[Donnerfels]]. Er ist der stolze Anführer der [[Tauren der Runentotem]], doch er ist alt und seine Kraft verlässt ihn. Hamuul ist ein überzeugter Unterstützer von [[Cairne Bluthuf]] und weiht seine geehrten Brüder auf der Anhöhe der Ältesten in die Lehren der [[Druiden]] ein. Er steht an der Spitze eines wichtigen Forschungsprojekts des [[Zirkel des Cenarius]] und erforscht die Grenzgebiete von [[Kalimdor]]. Er kann auch Rat geben über die Besudelung der [[Brachland Oasen]], denn er betrat das [[Smaragdgrüner Traum|Land der Träume]] und träumte von einem Druidenkult, der in den [[Höhlen des Wehklagens]] haust. \r\n==Geschichte==\r\nHamuul schloss während der letzten Invasion der [[Brennende Legion|Brennenden Legion]] Freundschaft mit dem mächtigen [[Nachtelfen]] [[Malfurion]] Sturmgrimm. Der große [[Druide]] lehrte Hamuul viele Geheimnisse der Wildnis und segnete ihn mit der Berührung der Natur. Seit dieser Zeit ist Hamuul ein hoch geehrtes Mitglied des (vorwiegend von [[Nachtelfen]] beherrschten) [[Zirkel des Cenarius]] und gilt als der erste [[Tauren]] [[Druide]] seit fast zwanzig Generationen.",},
			["Erzmagier"] = { content = "Die '''Erzmagier''' stammen aus dem magischen Königreich [[Dalaran]] und verkörpern den Höhepunkt magischer Macht. Diese launischen alten Zauberer setzen all ihre Zauberkräfte ein, um die [[Menschen]] mit Hilfe ihrer komplexen Zaubersprüche zu verteidigen. Sie tragen magische Klingen und uralte Stäbe, die im Kampf ihre enormen Energien kanalisieren. Zwar sind diese erfahrenen Zauberer bärbeißig und etwas wunderlich, aber dennoch sind sie auf jedem Schlachtfeld gern gesehen, wo das Schicksal der Menschheit auf dem Spiel steht.\r\n==Persönlichkeiten==\r\nZu den berühmten Erzmagiern der Geschichte gehören u.a.:\r\n* [[Erzmagier Alturus]]\r\n* [[Erzmagier Ansirem Runenweber]]\r\n* [[Erzmagier Arugal]]\r\n* [[Erzmagier Vargoth]]\r\n* [[Erzmagier Xylem]]\r\n* [[Erzmagierin Angela Dosantos]]\r\n* [[Kelen der Sucher]]\r\n==Fähigkeiten==\r\nFolgende Fähigkeiten, die heutige [[Magier]] zu nutzen wissen, gehen in ihrer Entdeckung und ursprünglichen Anwendung auf die Erzmagier von [[Dalaran]] zurück:\r\n* '''Arkane Brillianz''': Einige Erzmagier sind so mächtig, dass schon allein ihre Anwesenheit die Energien der Zauberer um sie herum erhöht. Diese magischen Synergien manifestieren sich in einer gleißenden Aura, die den Energievorrat jüngerer Zauberer auffrischt, sodass sie Zauber häufiger wirken können.\r\n* '''Blizzard''': Einer der gefürchtetsten Zauber der [[Allianz]] ist der Blizzard, der seit seiner Erfindung im Ersten Krieg noch wirksamer und tödlicher gestaltet wurde. Es ist bekannt, dass Erzmagier mit diesem Zauber ganze Armeen ausgelöscht oder zum Rückzug gezwungen haben, indem sie Trümmer gefrorenen Eises herbeiriefen, die ihre Gegner zerfetzten.\r\n* '''Massen-Teleportation''': Dieser äußerst mächtige Zauber ermöglicht dem Erzmagier, sich und seine Armee zu jeder beliebigen befreundeten Einheit oder jedem befreundeten Gebäude auf der Welt zu teleportieren. Aufgrund der empfindlichen Natur des Zaubers Massen-Teleportation können Erzmagier aber nur an Orte teleportieren, an denen sich gerade jemand aufhält, den sie kennen.\r\n* '''[[Wasserelementar]] beschwören''': Durch Anwendung dieses Zaubers kann ein Erzmagier einen mächtigen, aus Wasser und Dunst bestehenden Elementargeist herbeirufen und steuern. Diese Kreaturen, die Sturzbäche steinharten Wassers auf ihre Gegner zu schleudern vermögen, können nicht lange in der stofflichen Welt verweilen. Daher verschwinden sie nach einer kurzen Zeitspanne und kehren in ihren flüssigen Urzustand zurück.",},
			["Erzmagierin Angela Dosantos"] = { content = "'''Erzmagierin Angela Dosantos''' ist eine Magierin in der [[Kapelle des Hoffnungsvollen Lichts]] in den [[Westlichen Pestländern]]. Sie schloß sich einst der [[Argentumdämmerung]] an, um [[Kel'Thuzad]] daran zu hindern, [[Atiesh]], den Stab des letzten Wächters zu bekommen. Später aber wechselte sie zur [[Bruderschaft des Lichts]], da sie die Argentumer zu liberal fand.\r\n==Geschichte==\r\nErzmagierin Angela Dosantos war, genau wie [[Kel'Thuzad]], einst ein [[Zauberer]] der [[Kirin Tor]]. Sie wurde zur Wächterin von [[Atiesh]], dem Hohestab des Wächters, ernannt. Nach der Zerstörung und dem Niedergang von [[Dalaran]] verließ sie die [[Kirin Tor]]. Wie Kel'Thuzad begab auch sie sich auf die Suche nach dem legendären [[Atiesh]], der bei der Zerstörung von [[Dalaran]] verloren ging. Ihre beider Schicksale sind miteinander verwoben. Sie hatte jahrelang über Atiesh gewacht, nur damit ihr auf einen Schlag ihr Platz und ihre Aufgabe unter den Kirin Tor genommen wurden. Sie wollte den Stab finden, auch wenn es ein Leben lang dauern würde. So kam es, dass sie der [[Argentumdämmerung]] beitrat und sie heute in der [[Kapelle des Hoffnungsvollen Lichts]] zu finden ist. Es ist eine Geschichte, sie ist Teil einer Legende. Doch nun hat sie weder genug Zeit, noch neigt sie dazu, sie in aller Ausführlichkeit zu erzählen. \r\n==Frostfeuer==\r\nAls Behüterin hatte sie Zugang zu Vielem von [[Medivh]]s persönlicher Habe und die Folianten waren für sie die aufschlussreichsten Gegenstände. Während die Mehrheit der Bücher aus - sie sagt es ganz offen - Schund bestand, gab es auch einige Schmuckstücke darunter. Einer dieser Folianten beschrieb die Herstellung eines Rüstungssets, passend für einen [[Erzmagier]]: [[Frostfeuer]]. Sie hat einen Weg gefunden, wie man sich mit Hilfe von arkaner Tarnung Zugang zu diesem Foliant verschaffen kann - einem leicht abgewandelten alten Zauber der [[Kirin Tor]].",},
			["Erzmagier Ansirem Runenweber"] = { content = "'''Erzmagier Ansirem Runenweber''' vor der Kuppel von [[Dalaran]] im [[Vorgebirge des Hügellands]] ist der Vater von [[Catelyn der Klinge]] in [[Beutebucht]]. Er schrieb vor vielen Jahren einen Folianten, der sich mit den [[Legenden der Gurubashi]] beschäftigte und weiß einiges über den [[Stein der Gezeiten]]. Er kann auch die magischen Überreste an den Armschienen der [[Wasserelementare]] aus dem [[Schlingendorntal]] analysieren. Er fand heraus, dass der Magier, der im Besitz des [[Stein der Gezeiten]] ist, seine Macht durch ein Zentrum, eine Art Altar verstärkt. Man sollte in der Lage sein, dies zu unterbrechen, indem man diesen Magier überwältigt und Erzmagier Ansirem Runenweber weiß auch womit: Ein alter Dolch, ein weiteres Trollrelikt, den er auf einer Forschungsreise im [[Schlingendorntal]] fand, aber er gab ihn seiner eigenwilligen Tochter, [[Catelyn der Klinge]].",},
			["Erzmagier Arugal"] = { content = "'''Arugal''' war einst ein [[Erzmagier]] der [[Kirin Tor]]. Frustriert über den aussichtslosen Kampf der Hexer von [[ Dalaran]] gegen die untoten Armeen der [[Geißel]] während des Dritten Krieges, beschloss der Arugal gegen den Willen seiner Kollegen, Wesen aus einer fremden Dimension zu Hilfe zu rufen um die schwindenden Reihen der Hexer zu stärken. Arugals Beschwörung brachte die gefräßigen [[Worgen]] nach Azeroth. Zwar machten die unaufhaltsamen Werwölfe kurzen Prozess mit allem, was die Geißel ihnen entgegenstellte, doch nach kurzer Zeit wandten sie sich auch gegen die Magier, denen sie eigentlich dienen sollten. Von Schuldgefühlen halb wahnsinnig adoptierte Arugal die Worgen als seine Kinder und zog sich in die inzwischen verfallene Ruine von [[Burg Schattenfang]] zurück. Dort soll er immer noch hausen, unter dem immer wachsamen Auge seines gewaltigen Schoßhundes [[Fenrus]], heimgesucht von dem rastlosen Geist von [[Baron Silberlein]]. (Quelle: \r\nArugal ist heutzutage in den Augen der Verlassenen nicht mehr als ein Scharlatan, eine verfluchte Kreatur. Wie Arugal in die [[Kirin Tor]] aufgenommen wurde, ist manchen von ihnen schleierhaft, denn seine Zauberkunst schien so billig wie schlecht nachgemachter Schmuck. Arugal hielt sich zuerst auf einer Weizenfarm im [[Silberwald]] etwas nördlich der Brücke auf. Bei der Untersuchung seiner Arbeit haben sich die schlimmsten Befürchtungen bestätigt. Der alte Taugenichts war nicht einmal qualifiziert genug, um die Nachttöpfe in [[Dalaran]] zu leeren, davon, die [[Kirin Tor]] in ihrer schwersten Stunde zu repräsentieren, ganz zu schweigen. Arugal benutzte verzauberte Gegenstände, um seine schwache Magie zu verstärken und je mehr die Verlassenen über seine Magie erfahren, umso mehr wächst ihre Verachtung für diesen jämmerlichen Narren. Arugal lebt immer noch in der [[Burg Schattenfang]] und die [[Verlassene]]n können den [[Silberwald]] erst dann als strategische Festung für die dunkle Fürstin beanspruchen, wenn Arugal erschlagen ist. \r\n==In Wrath of the Lich King==\r\nIn [[Wrath of the Lich King]] wird Arugal von der [[Geißel]] wieder zurückgerufen, damit er ihnen die [[Worge]] beschwören kann. Er hat nun seinen Sitz in den [[Grizzlyhügel]]n.",},
			["Erzmagier Nielas Aran"] = { content = "'''Nielas Aran''' war einer der mächtigsten [[Magier]] des alten Reichs von [[Sturmwind]]. Er war Hofmagier des Königs, Gerichtsvollzieher, Gesandter der [[Kirin Tor]], Mitglied im [[Orden von Tirisfal]] und Vater und Lehrmeister des [[Medivh]], des letzten Wächters. Die vormalige Wächterin [[Aegwynn]] verführte ihn und so wurde Nielas Aran zum Vater Medivhs. Doch als die Macht von Tirisfal in dem Jungen erwachte und er seinen Vater berührte, erstarrten beide in magischer Trance. Hundert [[Magier]] und [[Priester]] waren nötig, den Bann zu lösen. An dessen Ende starb Nielas an Erschöpfung. Jetzt ist sein [[Schemen]] als Vision in der Bibliothek von [[Karazhan]] gefangen.",},
			["Erzmagier Vargoth"] = { content = "Erzmagier Vargoth lebt in einem verfluchten Turm in [[Kirin'Var]] im [[Nethersturm]]. Der verfluchte Turm, der von einem magischen Konstrukt namens Arkelos der Wächter, bewacht wird, ist sowohl eine Zuflucht als auch ein Gefängnis für ihn. \r\nErzmagier Vargoth war schon immer ein talentierter [[Magier]], aber nie zuvor hat er etwas so Mächtiges gesehen, wie die Magie, die der Lich [[Naberius]] beim Angriff auf den Turm gewirkt hat. Er hat die Gefahr in [[Naberius]]' Interesse an der Nekromantie erkannt, aber er hätte niemals geglaubt, dass sein Lehrling den [[Kirin Tor]] so viel Schaden zufügen würde.\r\n==Befreiung==\r\nUm sich aus dem Turm zu befreien, möchte Erzmagier Vargoth, dass man das Siegel von [[Krasus]] von Zauberbinderin Maryana in der [[Manaschmiede Cooru]], sowie [[Krasus Kompendium]] wiederholt. Wenn auch das heliotrope Oculus von Zauberhäscherin Marathelle im [[Sonnenzornposten]] besorgt wurde, muss man den Vertrauten, Gletscharius, aus den Händen des [[Blutelfen]]beschwörers Kanthin in der [[Manaschmiede Duro]] befreien. Danach muss man den Schlüsselmeister finden. Dazu sucht man Apex und besorgt sich Apex' Kristallfokus. Dann benutzt man diesen Kristallfokus in der Nähe von Erzmagier Vargoths Kugel um herauszufinden, wer den Schlüssel zum Fluch des Turms hat. Am Ende muss man zur [[Botanika]] der [[Festung der Stürme]] reisen und sich den Schlüsselstein von [[Kommandant Sarannis]] besorgen.",},
			["Erzmagier Xylem"] = { content = "'''Erzmagier Xylem''' gilt als sehr gefährliche Person und lebt in einen Turm hoch über den Klippen [[Azshara]]s mit Ausblick auf das ganze Gebiet. Der einzige Weg, der dort hinaufführt, ist ein Teleportationszauber, der von seinem arroganten Diener, [[Sanath Lim-yo]], gewirkt wird. Um ihn zu finden, muss man zu der Stelle reisen, an der sich [[Azshara]]s Hauptstraße beim Eingang zu den [[Ruinen von Eldarath]] gabelt. Dann geht man von dort aus direkt nach Norden bis man zu den Klippen kommt.\r\nEr ist zwar ein Mensch, aber er benimmt sich nicht wie ein Mensch. Er strahlt Macht aus und gelangte durch [[Jediga]] in den Besitz der [[Schrifttafel von Sael'hai]]. Doch aus einem unbekannten Grund, kann er den Turm nicht verlassen. Erzmagier Xylem hat seit kurzer Zeit begonnen sich umzuhören... nach jemanden mit der Erfahrung.",},
			["Eschental"] = { content = "Der [[Nachtelfen]]wald liegt im Norden des [[Steinkrallengebirge]]s. Man erreicht ihn, indem man über die [[Scherwindklippe]] oder nördlich durchs [[Brachland]] reist. Der Wald von Eschental ist eine große, ungezähmte Wildnis, der die [[Horde]] ihren Willen aufzuzwingen trachtet, sowohl politisch wie auch spirituell. Die [[Horde]] hat eine starke Präsenz in den Ländern nördlich des Brachlandes aufgebaut und die beiden Außenposten - der [[Splitterholzposten]] und der [[Zoram'gar-Außenposten]] - wollen ihr zu Ruhm gereichen. \r\n==Geschichte==\r\nUnmittelbar nach der Großen Teilung begannen die [[Nachtelfen]] damit, die verwüsteten Wälder am Fuße des [[Hyjal]] wieder aufzuforsten. Bald waren die Ruinen der alten Tempel und Straßen von dichten Wäldern bedeckt, und neue Siedlungen wurden zwischen den schattigen Hügeln des Berges errichtet. Im Laufe der Jahrhunderte erlebte die Gesellschaft der [[Nachtelfen]] eine neue Blüte und expandierte über den gesamten Wald, den sie Eschental nannten. Die furchtlosen [[Krieger]]innen, die sich der Verteidigung [[Kalimdor]]s verschrieben hatten, streiften durch Eschental und zeigten sich umbarmherzig gegenüber allen, die die Ruhe ihrer Heimat störten. \r\n===Entweihung Eschentals===\r\nAuf der Suche nach dem Schicksal seines Volkes, führte [[Thrall]] die [[orcs|orkischen]] Clans an die Küsten des vergessenen Kontinents. In dem Trachten, eine neue Siedlung aufzubauen, holzte der Warsong-Clan einen Abschnitt des Waldes ab und zogen sich den Zorn der [[Nachtelfen]] zu. Der Halbgott [[Cenarius]] und eine große Zahl seiner [[Krieger]]innen setzten den [[Orcs]] schwer zu. Doch die [[Medizinmänner]] des Stammes spürten die Anwesenheit einer mysteriöse Macht, die den Untergang des Halbgottes besiegeln sollte. Der Grubenlord Mannoroth hatte sein brennendes Blut in eine nahe Quelle ergossen und sie dem Schutz der [[Satyrn]] überlassen. Das dunkle Wasser der Quelle entfachte die dämonischen Energien der [[Orcs]] von neuem und sie fanden einen Weg, [[Cenarius]] zu vernichten. Mit knapper Not gelang es den Clans, den Mächten der [[Brennende Legion|Brennenden Legion]] zu widerstehen und sich ihrer Verderbnis abermals zu entziehen. Durch das heroische Opfer von Grom Hellscream wurde dem [[dämon]]ischen Fluch, mit dem die [[Orcs]] geschlagen waren, ein Ende gesetzt. Aber die vereinten Streitkräfte der [[Menschen]] und [[Orcs]] drangen noch tiefer in die Wälder von Eschental ein.\r\n'''Quelle''': \r\n===Verderbnis der Legion===\r\n[[Tyrande Wisperwind]], die Anführerin der [[Wächterarmee]] der [[Nachtelfen]], war überzeugt, dass die Fremden nur Unheil bringen würden und schwor, die Eindringlinge zu vernichten. Aber nur kurze Zeit später fiel die [[Brennende Legion]] auch in Eschental ein, entweihte den Wald und überzog das Land mit ihrer Verderbnis. Mit vereinten Kräften konnte die [[Brennende Legion|Legion]] in der Schlacht am Berg [[Hyjal]] besiegt werden. Die treuen [[Nachtelfen]], angeführt vom Erzdruiden [[Malfurion Sturmgrimm]], zogen sich in die Schatten der Wälder zurück, um Eschental von den abscheulichen Verwüstungen der [[Dämon]]en zu heilen. Ihre gemeinschaftlichen Anstrengungen brachten den Nordländern einen brüchigen Frieden, doch dunkle Kreaturen lauern noch immer in den dunklen Wäldern.\r\n'''Quelle:''' \r\n==Orte==\r\n* [[Astranaar]]\r\n* [[Außenposten der Silberschwingen]]\r\n* [[Bathrans Schlupfwinkel]]\r\n* [[Dämonenhügel]]\r\n* [[Falathimsee]]\r\n* [[Grabhügel von Dor'Danil]]\r\n* [[Hain der Silberschwingen]]\r\n* [[Heulendes Tal]]\r\n* [[Himmelssturzsee]]\r\n* [[Holzfällerlager des Kriegshymnenklans]]\r\n* [[Irissee]]\r\n* [[Lager der Distelfelle]]\r\n* [[Lager der Fäulnisklauen]]\r\n* [[Maestras Posten]]\r\n* [[Mystralsee]]\r\n* [[Nachtflucht]]\r\n* [[Rajenbaum]]\r\n* [[Ruinen von Ordil'Aran]]\r\n* [[Satyrnaar]]\r\n* [[Schrein des sengenden Feuers]]\r\n* [[Splitterholzposten]]\r\n* [[Sternenstaubruinen]]\r\n* [[Waldeslied]]\r\n* [[Zoram'gar-Außenposten]]\r\n* [[Zoramstrand]]",},
			["Essay: Die Nachtelfen"] = { content = "[[Nachtelfen]]... die [[Kaldorei]]. Jene einst stolze, unsterbliche Rasse, die seit dem Fall Ihrer Unsterblichkeit den Sinn und ihren Platz in der Geschichte der Welt sucht. Die Helden ihres Volkes, [[Malfurion]], [[Tyrande]], verblichene Abbilder die mit den voranschreitenden Jahren in eine ungewisse Zukunft immer mehr und mehr in Vergessenheit geraten. Ihre Ideale, Ihre Lebensweise, Ihre Hochkultur spiegelt sich verzerrt wider in dem Bild, das die [[Kaldorei]] der Gegenwart uns alltäglich vor Augen führen: In blinder Arroganz klammern sie sich an den Status, den ihre Ahnen einst unter den [[:Kategorie:Volk|Völkern]] hatten und vergessen dabei, wie lächerlich sie gegenwärtig erscheinen. Hochmütig, als ob Stolz und Ehre vererbt werden könnten, verkommen sie zu einem toten Volk mit einer toten Sprache, die nichts mehr mit dem Glanz alter Tage gemein hat.\r\nDie Frauen der [[Kaldorei]] üben sich in eingeschlechtlicher Zweisamkeit und turteln wollüstig und freizügig durch die Straßen unserer Städte, während die einst hochgeschätzten [[Druiden]] sich der Wildheit ihrer Tierformen hingeben und unsere Gassen und Plätze verunreinigen. Anstatt das sie die Wildnis beherrschen, tragen sie die Wildnis in die Sicherheit unserer Städte, reiten ihre Raubtiere durch unsere Straßen. Es scheint, als ob es Neid ist, mit dem sie den Niedergang ihrer Kultur kompensieren möchten, indem sie - die Fremdlinge! - rücksichtslos die [[Menschen|menschlichen]] Werte übergehen. Sie verachten das [[Licht]] und ihre [[Priester]], die sind Landstreicher, Herumirrende, auf der Suche nach einem Sinn. Darauf angesprochen, höre ich immer nur wieder \"Krieg\". Ja, wenn dass das einzige ist, für das die [[Kaldorei]] geboren sind, nämlich Krieg zu führen, dann sind sie eine wirklich bemitleidenswerte Rasse.\r\nAnstatt Ihre Hauptstadt [[Darnassus]] zu bevölkern und zu beleben, streunern sie in [[Eisenschmiede]] und [[Sturmwind]] umher und stellen dort ihr \"Kulturgut\" zur Schau. Mit welchem Recht, frage ich mich immer wieder, verwandeln sie unsere schöne Stadt in eine verwilderte Barbarenhöhle? Mit welchem Recht führen sie sich auf wie die Herren der Welt? Der Hochmut und der Tadel, den sie uns [[Menschen]] entgegenbringen, die wir ja in ihren Augen eine minderwertige Rasse sind, ist Hohn und Spott angesichts der Tatsache, wie ihr Volk selbst sich dahingibt!\r\nNein, dieses Volk ist nicht stolz. Es ist lächerlich. Sie sind die Prachthengste in unserem Zoo, der momentan auf [[Sturmwind]]s Straßen tobt. Sie sind ein vergängliches Abbild, das sich in der Trauer um ihre Sterblichkeit und den Niedergang ihrer Kultur ersäuft. Sie sind der soziale Schwachpunkt in der [[:Kategorie:Hauptstadt|Hauptstadt]] der [[Menschen]].\r\nSie sind der [[Allianz]] nicht würdig.\r\nNur wenige traf ich, welche stillen Stolzes und in Gedenken der alten Zeit und der alten Helden das Wissen um die Größe ihres Volkes in ihren Herzen tragen und das verkörpern, was ich von den [[Kaldorei]] in den Geschichten gehört habe, die mir als Kind erzählt wurden. Ihnen wünsche ich, das sie die Schatten ihrer Zeit überkommen und zurückfinden, zu den Wurzeln Ihres Volkes. Möge [[Elune]] Ihnen die Kraft geben, ihre Brüder und Schwestern heimzuführen und ihnen ein Vorbild zu sein. Leider hege ich wenig Hoffnung auf die Zukunft dieses sterbenden Volkes.\r\n----\r\nVon [[Anthrazides]]",},
			["Ethel Rethor"] = { content = "'''Ethel Rethor''' ist ein hoher Turm an der Küste von [[Desolace]], der von einigen verstreuten Nachtelfischen Ruinen umgeben ist. [[Azore Aldamort]] von der [[Argentumdämmerung]] hat hier sein Lager aufgeschlagen, um das [[Szepter des Lichts]] von den [[Orcs der Brennenden Klinge]] aus der [[Festung Donneraxt]] zu bergen. Denn die Argentumdämmerung darf nicht zulassen, dass die Brennende Klinge solche Macht besitzt. Sobald das Szepter des Lichts geborgen wurde, soll möchte Azore Aldamortauch noch das [[Buch der Uralten]] von der [[Insel Ranazjar]] holen. An der Küste von Ethel Rethor befindet sich das Schiffswrack der \"[[Gallant]]\". Der Kapitän der \"Gallant\", [[Ulysses Rackmore]], hat sein Logbuch am Strand verborgen, welches den glücklichen Finder zu Rackmores Schatztruhe führt.",},
			["Etrigg"] = { content = "Der Orc '''Etrigg''' befindet sich in der Feste Grommash in [[Orgrimmar]]. Niemand kennt die [[Orcs des Schwarzfels]] besser als er, denn einst war er selbst Mitglied der Schwarzfelsorcs. In den Kämpfen des Schwarzfelsklans mit den [[Dunkeleisenzwerge]]n um die [[Schwarzfelsspitze]] fielen seine beiden Söhne, da wurde ihm klar, dass seine Zeit beim Schwarzfelsklan zu Ende ging. Er ging. Er wollte nicht bei den Schwarzfelsorcs bleiben. Der Tod seiner Kinder sollte nicht umsonst gewesen sein. Er wollte nicht unter einem unfähigen, machtgierigen Irren wie [[Rend Schwarzfaust]] dienen. Er fand Zuflucht in den Wäldern von [[Lordaeron]] und führte bei [[Herdweiler]] ein Einsiedlerleben. Die Welt war damals nicht so in Unordnung. Es gab eine Zeit, bevor die Geißel das Land verheert hatte. Bevor diese Teile von Lordaeron als [[Pestländer]] bezeichnet wurden. Dort rettete ihm [[Thrall]] das Leben und er schloss sich der neuen Horde an. Wenn es wahr ist, das [[Rend Schwarzfaust]] lebt, muss Etrigg davon in Kenntnis gesetzt werden. Niemandem sollte das Recht auf Vergeltung versagt werden.\r\n'''Quellen'''",},
			["Eule"] = { content = "'''Eulen''' zählen zu den [[Wildtier]]en und man findet sie in bewaldeten Regionen. Sie sind als Begleiter von [[Jäger]]n genauso beliebt wie als Haustiere und meinen es keineswegs böse, wenn sie einem die Sicht dabei versperren.\r\n==Eulen als Gefährten==\r\nShylenai in [[Darnassus]] verkauft die ''Falkeneule'' und die ''Große Ohreule'' für je 50 Silber. Diese Gefährten verwechselt man übrigens, trotz des geringeren Ausmaßes, schnell mal mit einem [[Jäger]]-Pet.",},
			["Eulenbestien"] = { content = "Eulenbestien werden auch Eulkin, Wildekin oder Mondkin genannt und sind unberechenbare [[:Kategorie:Kreaturen|Kreaturen]]. Sie sind zu einer außerordentlichen Zärtlichkeit fähig, aber diese Kreaturen können auch eine enorme Wildheit an den Tag legen, wenn etwas für sie sehr Wichtiges bedroht wird. Diese [[:Kategorie:Kreaturen|Kreaturen]] wurden angeblich von [[Elune]] geschaffen und waren einst die Tiere der [[Nachtelfen]][[Elune|göttin]].\r\nDiese schwerfälligen, ungeschlachten [[:Kategorie:Kreaturen|Kreaturen]] werden von den [[Druiden]] der [[Nachtelfen]] und den [[Treants]] gleichermaßen geschätzt. Sie sind von Natur aus gutartig, aber furchteinflößend, wenn sie gereizt oder geärgert werden. Von bewohnten Gegenden halten sie sich fern; man findet sie häufig in den friedlichen Tälern des Berges [[Hyjal]].\r\n==Bekannte Klans==\r\n* [[Eulenbestien der Mondkin]]\r\n* [[Eulenbestien der Rachfedern]]\r\n* [[Eulenbestien der Tannenruhfeste]]\r\n* [[Eulenbestien des Hinterlandes]]\r\n* [[Eulenbestien des Nisteldickicht]]\r\n* [[Eulenbestien von Winterquell]]",},
			["Eulenbestien der Rachfedern"] = { content = "Der Rachfederkamm liegt im Westen der [[Blutmythosinsel]], über die Purpurbrandung hinweg. Es ist noch nicht lange her, da kamen die einst so friedlichen [[Eulkin]] der Umgebung an die Ufer der [[Insel Drachenfels]]. Sie kamen einer nach dem anderen, um die Knochen der gefallenen [[Drachen]] zu stehlen. Man weiß nicht, was die Kreaturen in diese Verzweiflung getrieben hat oder warum sie die Knochen der Dahingeschiedenen wollen. Allerdings ruhen die Geister der Brut seit dieser Schändung nicht mehr.",},
			["Eulenbestien der Tannenruhfeste"] = { content = "Die Wildekin der Tannenruhfeste unter ihrem [[Häuptling Oomooroo]] sind dem Wahnsinn verfallen. Die Verteidiger der [[Furbolgs]] haben eine Todesfalle für die irren [[Eulenbestien]] aufgestellt, die von der Feste aus angreifen und die [[Furbolgs der Tannenruhfeste]] können sie zwar hier draußen abwehren, allerdings hat es noch kein Verteidiger geschafft, in die [[Tannenruhfeste]] vorzudringen.",},
			["Eulenflügeldickicht"] = { content = "Das '''Eulenflügeldickicht''' in [[Winterquell]] ist die Heimat von vielen [[Eulenbestien]]. [[Ranshalla]] reiste kürzlich nach Winterquell, um die [[Eulenbestien]] dort in ihrer heimischen Umgebung zu beobachten und fand dabei ganz oben auf dem Grat einen Altar der Göttin [[Elune]]. Sie fand heraus, dass man in jeder Höhle fünf Fackeln anzünden muss, und dann erst den eigentlichen Altar erreichen kann. In den Stein der alten Ruinen am [[Kel'Therilsee]] sind einige Zauberformeln geritzt, die der Schlüssel sind, mit dem man den Altar freigeben kann. \r\n==Der Altar von Elune==\r\nWieso die Wildekin diese Gegend bewachen, erklärt eine Priesterin von Elune:\r\nEnu thora'serador. Dies ist ein hochheiliger Ort.\r\nSehr nach oben, thara dormil dorah...\r\nDieser Edelstein ermöglichte einst die direkte Kommunikation mit Elune selbst. Durch diesen Edelstein kanalisierte Elune ihre unendliche Weisheit. Als die Nachtelfen erkannten, dass der Edelstein beschützt werden musste, wandten sie sich an die Göttin persönlich. Bald darauf begannen sie, Visionen von einer Kreatur zu haben. Einer Kreatur mit den Federn einer Eule, aber der Willenskraft und Stärke eines Bären. An jenem Tag wurden den Nachtelfen die Wildekin gegeben. Die Göttin berief die Wildekin, diese grimmigen Wächter, dazu, all ihre heiligen Orte zu beschützen. \r\nAnu'dorini Talah. Ru shallora enudoril.\r\nEines sollte man wissen: Ganz egal, wo auf der Welt man auf die Wildekin stößt, sie bewachen etwas Wichtiges, wie es ihnen vor so langer Zeit befohlen wurde.\r\n==Personen==\r\n* [[Ranshalla]]\r\n* '''Umbranse der Geistsprecher''' - Umbranse hält sich in der Nähe des Eulenflügeldickicht auf. Er ist ein einsiedlerisches Medium, der für die Toten spricht und hat der [[Argentumdämmerung]] das Buch: \"[[Studien über das Geistsprechen]]\" geschenkt.",},
			["Eulkin"] = { content = "#REDIRECT [[Eulenbestien]]", redirect = "Eulenbestien",},
			["Ewiger Drachenschwarm"] = { content = "Es ist nichts über den Ursprung des '''Ewigen Drachenschwarms''' bekannt. Allerdings hat dieser es sich zum Ziel gesetzt das Gefüge der Raum Zeit, welches [[Nozdormu]] bewacht, zu zerstören und somit eine auf sich zugeschnitte Welt zu bauen.\r\n==Berühmte Ewige Drachen==\r\n* [[Aeonus]]\r\n* [[Chronolord Deja]]\r\n* [[Epochenjäger]]\r\n* [[Temporus]]",},
			["Ewiger Drachenschwarm"] = { content = "Es ist nichts über den Ursprung des '''Ewigen Drachenschwarms''' bekannt. Allerdings hat dieser es sich zum Ziel gesetzt das Gefüge der Raum Zeit, welches [[Nozdormu]] bewacht, zu zerstören und somit eine auf sich zugeschnitte Welt zu bauen.\r\n==Berühmte Ewige Drachen==\r\n* [[Aeonus]]\r\n* [[Chronolord Deja]]\r\n* [[Epochenjäger]]\r\n* [[Temporus]]",},
			["Ewiger Hain"] = { content = "Der '''Ewige Hain''' liegt im nordwestlichen [[Schergrat]] inmitten des [[Ruuanwald]]s. Die Mitglieder der [[Expedition des Cenarius]] haben sich hier in einem Druidenhain niedergelassen und machen sich große Sorgen um die Pläne der [[Arakkoa]] im [[Schergrat]].\r\n==Persönlichkeiten==\r\n* [[Moosborke der Uralte]]\r\n* '''Baumhüter Chawn''' - Baumhüter Chawn meint, es wäre Zeit zu verhandeln und würde gern mit [[Aufseher Nuaar]] vom [[Wyrmkult]] reden. Nachdem das jedoch fehlgeschlagen ist, setzt er sich für ihre Bekämpfung ein und befiehlt, die Roder des Wyrmkults im Ruuanwald zu töten. Auch der Verantwortliche, [[Maxnar den Aschenmagen]], muss sterben. Chawn möchte, dass jemand am Treffen am Pechschwingenkoven teilnimmt. Dafür muss man genügend Gewandfetzen von verschiedenen Wyrmkultisten sammeln, um eine Aufseherverkleidung herzustellen. Diese benutzt man dann, um am Treffen mit [[Kolphis Dunkelschuppe]] teilzunehmen.\r\n* '''Kommandant Haephus Steinwall''' - Kommandant Haephus Steinwall möchte [[Dorgok]] im [[Lager der Blutschläger]] vernichten. \r\n* '''Leutnant Schönwetter''' - Leutnant Schönwetter kümmert sich um die [[Oger]] in [[Fels'mok]].\r\n* '''O'Mally Zapschnapper''' - Der Gnom O'Mally Zapschnapper ist ein Ingenieur und glaubt, die [[Druiden]] hier hätten eine enorme Kraftquelle erschlossen. Er will herausfinden, wie sie sich in Tiere verwandeln, Blitze und starkes Mondlicht erzeugen. Er glaubt, sie tragen Batterien unter ihren Roben. Er hat das [[Zephyriumkapazitorium]] aus [[Toshleys Station]] entdeckt, um mittels einer rotierenden Netherwetterfahne, die an dem Zephyriumkapazitorium angebracht wird, das Wetter in der Region zu untersuchen.\r\n* '''Samia Weißwas''' - Samia Weißwas stellt Nachforschungen über den [[Pechschwingenkoven]] des [[Wyrmkult]]s an und hilft den [[Druiden]], mit ihnen fertig zu werden und ist sehr daran interessiert, an ein paar ihrer Schwarzwelpen zu kommen. \r\n* '''Timeon''' – Timeon kümmert sich um die Bedrohung durch die [[Arakkoa der Ruuan'ok]]. Er würde gern an den Anhänger eines Herold des Raben gelangen. Dazu braucht er die Klauen der Ruuan'ok, mittels derer man im Orakelkreis der Ruuan’ok einen Herold des Raben herbeizurufen kann.\r\n* '''Wildfürst Antelarion''' - Wildfürst Antelarion leitet den Kampf gegen die Brennende Legion im Ewigen Hain und führt seine Druiden an die [[Schwelle des Todes]], um die dortigen Dämonen zu dezimieren.",},
			["Ewige Warte"] = { content = "Die Hauptstadt von [[Winterquell]] ist die Ewige Warte. Sie zählt zu den neutralen Städten und ist ein von den [[Goblins]] des [[Dampfdruckkartell]]s geführter Handelsposten, der sich im Zentrum der Haupthandelswege von [[Winterquell]] befindet.\r\n==Personen==\r\n* '''Gregor Graustein''' - Gregor Graustein ist hier als Vertreter der [[Argentumdämmerung]] und der Interessen in der Lokalverwaltung der Ewigen Warte. Er muss [[Argentumoffizier Garush]] einen Fortschrittsbericht zukommen lassen. \r\n* '''Harlo Wackelwert''' - Harlo Wackelwert ist gerade erst vom [[Teufelswald]] zurückgekehrt und hat unterwegs im [[Blutgiftposten]] Halt gemacht und eine wirklich eigenartige Bekanntschaft gemacht. \r\n* '''Hexendoktorin Mau'ari''' - Hexendoktorin Mau'ari ist eine exzentrische Trollin, die Glücksbringer aus Frosthagelsplittern anfertigt. Wenn man den Glücksbringer bei sich trägt, wird man feststellen, dass die Kreaturen, gegen die man kämpft, bestimmte Gegenstände fallen lassen. Sie werden [[E'ko]] genannt. Wenn man [[E'ko]] findet, bringt man sie einfach der alten Mau'ari.\r\n* '''Jessica Rotpfad''' - Jessica Rotpfad ist während des großen Krieges aus [[Lordaeron]] geflohen und hatte das Glück, entkommen zu können, bevor die [[Geißel]] durch ihre Heimat fegte und sie zu einem verseuchten Alptraum machte. Sie hatte Glück, aber ihre Familie nicht. Sie fürchtet, dass ihre Familie während der Schlacht von [[Darroheim]] getötet wurden und vermisst besonders ihre kleine Schwester [[Pamela]].\r\n* '''Meggi Frickelprotz''' - Meggi Frickelprotz hat einige Zeit draußen in der Wildnis zugebracht und weiß um die Probleme in [[Winterquell]]. Es macht sie immer ganz stolz, das zu sagen, aber für sie waren die Stunden, die sie draußen in den Hügeln verbrachte, etwas ganz Besonderes. Es hilft einem, blitzschnelle Reflexe zu entwickeln, einen kühlen Kopf und ein wachsames Auge zu bewahren. Man braucht Urteilsvermögen, Grips und Reife, um die Wildnis schätzen zu können. \r\n* '''Storm Schattenhuf''' - Storm Schattenhuf möchte, dass man [[Ursius]], [[Brumeran]] und [[Shy-Rotam]] besiegt. \r\n* '''Umi Rumpelkicher''' - Umi Rumpelkicher will einen mechanischen [[Yeti]] herstellen. Dafür benötigt sie dickes Yetifell von [[Eisdistelyeti]]s, um die mechanischen beweglichen Teile abzudecken und zwei Hörner.",},
			["Exarch Maladaar"] = { content = "'''Exarch Maladaar''' ist der Endboss in der [[Auchenaikrypta]] von Auchindoun. Dieser [[Draenei]] macht bösartige Experimente in der Nekromantie und ist der Grabwächter von [[D'ore]]s Geist. In dem Bestreben, seine nekromantischen Künste besser zu verstehen, werden in der Auchenaikrypta von Maladaar eine Unzahl von abscheulichen Experimenten durchgeführt. Zahlreich sind die Geister derer, die in den finsteren Hallen gefoltert und ermordet wurden. Doch Maladaar lebt immer noch weiter und quält die Geister in der Krypta. Im Besitz des Exarchen befindet sich ein Seelenedelstein, in dem gequälte Geister gefangen sind. Der ''Seelenedelstein des Exarchen'' enthält die Seelen vieler Opfer und man spürt ihre Unruhe ganz deutlich.",},
			["Exodar"] = { content = "Vor einem Monat zerriss eine furchtbare Explosion die Wolken über dem nördlichen [[Kalimdor]]. Im selben Augeblick stürzte das große Schiff Exodar vom Himmel herab auf die Weiten [[Azeroth]]s. Die noblen [[Draenei]], aus der verwüsteten [[Scherbenwelt]] geflohen, hatten die durch Dimensionen reisende Exodar benutzt, um einen sicheren Zufluchtsort zu finden. Nun dient die Exodar den [[Draenei]] als [[:Kategorie:Hauptstadt|Hauptstadt]] und sicherer Hafen in [[Azeroth]].\r\nDie Exodar ist ein Schiff der [[Naaru]], das die [[Draenei]] nach [[Azeroth]] brachte und einst ein Teil der [[Festung der Stürme]] war. Nach einem Absturz auf der [[Azurmythosinsel]], dient es diesem edlen Volk als Heimstätte.\r\n==Besonderheiten==\r\n* '''Stephanos''' – Hippogryphenmeister. Er hält sich beim Eingang der Exodar auf. \r\n* '''Torallius der Herdentreiber''' – Gruppenkommandant der [[Hand von Argus]]. Man findet ihn außerhalb der Exodar bei den Elekk. Er sagt, Elekk sind starker Tobak, wie kann man von ihm erwarten, dass er einen seiner wertvollen Lieblinge einem namenlosen, unerfahrenen überläßt.\r\n===Halle des Lichts===\r\nDas \"Sanktum der Verteidiger\" ist ein Raum innerhalb der Halle des Lichtes, der von einem pulsierenden Lichtschein umgeben ist. Hier findet man u.a. die [[Paladin]]-Lehrer.\r\n* [[Prophet Velen]] - Herrscher der Exodar. Velen bildete mit Archimonde und Kil'jaeden die Herrscher der Eredar, bevor Sargeras Archimonde und Kil'jaeden für seine Zwecke gewann und Velen mit einigen getreuen Eredar fliehen musste, welche Heute als Draenei bekannt sind.\r\n===Händlertreppe===\r\nAm höchsten Punkt der Händlertreppe befindet sich die \"Terrasse der Krieger\".\r\n===Sitz der Naaru===\r\nDer Sitz der Naaru befindet sich im Zentrum der Exodar.",},
			["Expeditionsposten"] = { content = "Man findet den Expeditionsposten auf der [[Höllenfeuerhalbinsel]] dort, wo einst ein Lager der [[Brennende Legion|Brennenden Legion]] war. Man geht von der [[Ehrenfeste]] aus etwa 400 Schritte nach Osten, durch das [[Tal der Knochen]], bis man auf einen zerstörten [[Teufelshäscher]] stoßt. Rohamus' Truppe dort ist sehr radikal und hat sich der vollständigen Auslöschung der [[Brennende Legion|Brennenden Legion]] verschrieben. \r\n==Personen==\r\n* '''Schwadronskommandant Dabir'ee''' beaufsichtigt die gepanzerten [[Greifenreiter]]. Sie sind bereit für einen kleinen Ausflug, aber sie brauchen jemanden, der vom Boden aus ihre Angriffe lenkt.\r\n* '''Vorpostenkommandant Wa'ppun''' besitzt einen Zünder, der in [[Area 52]] hergestellt wurde und die eigene Macht der [[Dämonen]] als Sprengstoff benutzt. Wa'ppun möchte, dass man die Kommunikation der dämonischen Portale unterbricht.",},
			["Expeditionsrüstlager"] = { content = "Am Ende der Invasion wurde das Expeditionsrüstlager der [[Allianz]] auf der [[Höllenfeuerhalbinsel]] von [[Orcs]] und [[Todesritter]]n angegriffen und zerstört. Diese bösartigen Schemen haben die Verteidiger des Rüstlagers verflucht und ihre Seelen zwischen dem Reich der Lebenden und dem der Toten gefangen. [[Die Unerschütterlichen]], diese einst stolzen Soldaten der [[Allianz]] spuken nun als rachedurstige Geister in den Ruinen. Sie sind blind vor Hass und in einer ewigen Schlacht gegen die Klans der [[Höllenorcs]] gefangen. Sie denken nur an Rache. Niemand weiß mit Sicherheit, was dort vor sich geht, was genau die Geister der gefallenen Soldaten an die Ruinen bindet. [[Erzmagier Xintor]] und [[Feldkommandant Thalvos]] standen ihren Männern besonders nahe. Vielleicht bringt die Vernichtung ihrer Geister die anderen zur Ruhe.\r\n==Personen==\r\n* [[Erzmagier Xintor]]\r\n* [[Feldkommandant Thalvos]]",},
			["Expedition des Cenarius"] = { content = "Die Expedition des [[Cenarius]] ist die Forschergruppe des [[Zirkel des Cenarius]] in die [[Scherbenwelt]]. Seitdem diese kleine Gruppe vom [[Zirkel des Cenarius]] hierher geschickt wurde, ist sie zu einer großen und recht unabhängigen Gesellschaft gewachsen. In den letzten 20 Jahren hat sich die Scherbenwelt immer wieder verändert und die Expedition des Cenarius hat daher beschlossen die Welt zu erkunden. Die [[Urtume]] Ashyen und Keleth haben sie auf diesen Weg begleitet um sie zu beschützen. Die Expedition wird von [[Ysiel Windsänger]] angeführt und verantwortlich für die Sicherheit ist [[Aufseher Hamuht]]. Die Expedition ist in der [[Zuflucht des Cenarius]] zuhause, im Osten der [[Zangarmarschen]] direkt westlich des Dornnebelhügels der [[Höllenfeuerhalbinsel]]. \r\n==Ziele==\r\nDas ursprüngliche Ziel der [[Druiden]] war es, die artenreiche Natur der [[Zangarmarschen]] zu erforschen, doch die Gruppe erfuhr schon sehr bald von den beunruhigenden Dingen, die sich in den [[Zangarmarschen|Marschen]] abspielten. Der Wasserstand in vielen Teilen der [[Zangarmarschen]] sinkt und einige Gegenden, wie zum Beispiel das Todesmoor, haben schon unter diesem seltsamen Phänomen gelitten. Die [[Druiden]] der Zuflucht des [[Cenarius]] vermuten, dass die [[Naga]] verantwortlich für diese Probleme sind, können die direkte Konfrontation mit den vielen [[Naga]] der [[Zangarmarschen]] und des [[Echsenkessel]]s jedoch nicht wagen. Die Expedition des [[Cenarius]] benötigt die Hilfe tapferer Abenteurer im Kampf gegen diejenigen, die das natürliche Gleichgewicht der [[Zangarmarschen|Marschen]] zerstören möchten. Jeder, der den Gefahren trotzt und sich dem Kampf gegen die [[Naga]] anschliesst, wird reich belohnt werden.",},
			["Extradimensionaler Geisterdetektor"] = { content = "Der '''Extradimensionale Geisterdetektor''' ist eine Maschine, die [[Mux Manamix]] in [[Gadgetzan]] in der Wüste [[Tanaris]] baute. Dieser Apparat erlaubt es ihm, mit den Toten zu kommunizieren. Als Energiequelle dient das Herz von [[Magmafürst Bokk]] und ein Teufelselementarer Brennstab dient als Brennstab, der diese Energie auch weiterleiten kann, ohne dabei zu schmelzen. Auch der [[Ektoplasmadestillierer]] ist Teil des Extradimensionalen Geisterdetektors.",},
			["Falathimsee"] = { content = "Der Falathimsee liegt am Fuße der Berge im Westen von [[Astranaar]] im [[Eschental]] und ist das Zuhause von [[Murlocs]]. Hier findet man auch die Überreste von [[Teronis]], einem alten Freund von [[Raene Wolfsläufer]] in [[Astranaar]].",},
			["Faldirbucht"] = { content = "Die [[Goblins]] der [[Schwarzmeerräuber]] unter [[Kapitän O'Breen]] wollten nur ein paar Stunden hier bleiben. Gerade lang genug, um einen verlorenen Elfenschatz einzusammeln und zurück nach [[Beutebucht]] zu segeln. Aber sie haben die anderen beiden Schiffe von der Formation verloren. Die \"[[Silbergeist]]\" und die \"[[Tolle Minna]]\", die jetzt auf dem Grund des Meeres ruhen. Die Crew hat ihr Bestes gegeben um die wunderschöne \"Tolle Minna\" zu retten und O'Breen hat es sicher ans Ufer geschafft, aber die anderen hatten nicht so viel Glück. Das Meer sank einfach auf sie herab und in der einen Sekunde lagen sie auf dem Wasser und in der nächsten stürmte das Wasser auf sie ein. Die [[Naga]]s haben alle Überlebenden getötet. O'Breen führte die Schiffe in die Bucht. Sie waren ziemlich sicher, dass der verlorene Elfenschatz dort zu finden sei. \r\nDie \"[[Harbringer]]\" konnte noch sicher andocken, aber als die \"Tolle Minna\" und die \"Silbergeist\" näher kamen, senkte sich der Meeresspiegel plötzlich ab. So was Seltsames hatten die Seeleute ihren Lebtag nicht gesehen. \r\nDiese beiden Schiffe sind auf irgendetwas aufgelaufen - eine Art Tempel im Riff. Sie sind sehr schnell gesunken, eine echte Tragödie. Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Es scheint, als ob sich die [[Naga der Säbelflossen]] zum Angriff sammeln und sie sind bekannt für ihre Ruchlosigkeit im Kampf.\r\n==Personen==\r\n* '''Doktor Drechselknacks''' ist ein [[Schwarzmeerräuber]] und hat eine Schutzbrille konstruiert, die dabei hilft, die Edelsteine des verlorenen Elfenschatzes im dunklen Meer zu finden. \r\n* '''Erster Maat Nilzlix''' will, dass man die Karten und Logbücher von der TOLLEN MINNA und der SILBERGEIST zurückholt. \r\n* '''Hauptmann Gutstahl''' wünscht sich in seinem nassen Grab zu liegen und nicht am Feuer zu sitzen und frische Luft zu atmen. Bei dem Überfall der [[Naga]] gingen ihm die Lichter aus und er kam oben in der Faldirbucht wieder zu sich, gerettet. Er will diese Biester tot sehen.",},
			["Falkenplatz"] = { content = "Der [[Falkenplatz]] ist ein Stützpunkt der [[Horde]] im [[Immersangwald]] vor den Toren von [[Silbermond]]. Von hier aus wird die Verteidigung gegen die [[Getriebene]]n koordiniert, die sich in den [[Ruinen von Silbermond]] eingenistet haben.\r\n==Personen==\r\n* '''Aeldon Sonnenmahl''' sucht die Instabilen Manakristalle, die in leuchtenden Tonnen überall im Gelände der Ruinen verteilt herumstehen, damit sie nicht in die Hände der [[Getriebene]]n fallen. \r\n* '''Magister Jaronis''' kümmert sich um Arkanpatrouillen in den Ruinen, die unter schweren Fehlfunktion leiden.\r\n* '''Unteroffizier Kan'ren''' jagt [[Thaelis der Manadurstige|Thaelis den Manadurstigen]] in den Ruinen von Silbermond.",},
			["Falkenschreiter"] = { content = "Die schnellen und bunten Falkenschreiter sind die Reittiere der [[Blutelfen]]. Wie auch ihre Herren legen sie viel wert auf ihre äußere Erscheinung und durch ihr buntes und fast leuchtendes Gefieder sind sie ein echter Blickfang. Wenn man sich bei den [[Blutelfen]] einen ehrfürchtigen Ruf erarbeitet hat, kann man als Orc, Troll oder Untoter auch in den Genuss kommen ein solches Tier zureiten. Zu kaufen gibt es die Falkenschreiter in [[Thurons Aufzucht]] im [[Immersangwald]]. Der Schwarze Schlachtenschreiter ist dagegen ein [[PvP]]-Reittier und kostet je 30 Abzeichen vom [[Alteractal]]s, [[Kriegshymnenschlucht]] und vom [[Arathibecken]].",},
			["Falkenwacht"] = { content = "== Allgemeines==\r\nDie Falkenwacht ist ein [[Blutelfen]]stützpunkt der [[Horde]] im Westen der [[Höllenfeuerhalbinsel]].\r\nDie [[Blutelfen]] haben die Falkenwacht erst kürzlich als Operationsbasis im Südwesten der [[Höllenfeuerhalbinsel]], hinter der [[Höllenfeuerzitadelle]], fertig gestellt. Mit dem Zustrom von Pilgern und dem Vordringen der [[Allianz]], war die Falkenwacht in letzter Zeit ein sehr geschäftiger Ort. Sie stehen kurz davor, vollständig von den Streitkräften der [[Allianz]] eingekesselt zu werden und mit dem ständigen Zustrom von [[Sin'dorei]]-Flüchtlingen aus [[Azeroth]], müssen sie einen Weg finden, der vor den neugierigen Blicken des Feindes sicher ist. \r\nDie [[Blutelfen]] verkörpern den unverantwortlichen Umgang mit den Mächten der Magie. Sie kontrollieren die Magie nicht nur, vielmehr sind sie ihre Sklaven und sie werden niemanden zwischen ihre Abhängigkeit und die magischen Energien kommen lassen, nach denen es ihnen dürstet. Die [[Blutelfen]] nutzen die Energien der [[Scherbenwelt]]-[[Leerwandler]], um ihre dämonische Magie zu wirken und diese Welt birgt viele weitere Geheimnisse. Es ist nur noch eine Frage der Zeit, bis die [[Blutelfen]] sie alle enträtselt haben.\r\n==Persönlichkeiten==\r\n* '''Arelion''' war seit der Ankunft in der [[Scherbenwelt]] von den Teichen von Aggonar fasziniert. Er verbrachte fast seine gesamte Zeit mit dem Studium der heimischen Schleimarten. Vor einigen Tagen verschwand er spurlos. Er bewahrte sein Tagebuch immer in einem braunen Wanderknappsack auf, doch es enthält keine wissenschaftlichen Studien. Vielmehr beschreibt er seine Eskapaden mit einer jungen Blutelfe. Bei all den wichtigen Dingen, die er zu tun hatte, fand Arelion immer noch genug Zeit seine Geliebte zu besuchen.\r\n* '''Arkanist Calesthris Morgenstern''' ist am Wissen der [[Arakkoa]] interessiert, denn dieses Volk verfügt über uraltes arkanes Wissen, welches sich als sehr nützlich für ihre Erforschung dieser Welt erweisen würde.\r\n* '''Magister Aeldis''' ist ein Kollege von Arelion und war sein bester Freund und Vertrauter. Aeldis wurde zuletzt auf einer Reise von der Falkenwacht zu den Zangarmarschen gesehen.\r\n* '''Ryathen der Düstere''' will das Vorhaben der Anachoreten der Draenei bei den Teichen von Aggonar stoppen, oder ihre Teufelsblutquelle wird für immer versiegen.\r\n* '''Waldläuferhauptmann Venn'ren''' will eine sichere Passage durch die große Kluft etablieren.",},
			["Falstad Dragonreaver"] = { content = "#REDIRECT [[Falstad Wildhammer]]", redirect = "Falstad Wildhammer",},
			["Falstad Wildhammer"] = { content = "'''Falstad Wildhammer''' ist der amtierende oberste [[Than]] der [[Zwerge des Wildhammerklan]]s. Er befindet sich auf dem [[Nistgipfel]] im [[Hinterland]], wo er das Kommando über die Hauptfestung seines Klans hält und sein Revier unnachgiebig gegen die rebellischen [[Waldtrolle]] verteidigt.",},
			["Fandral"] = { content = "#REDIRECT [[Erzdruide Fandral Hirschhaupt]]", redirect = "Erzdruide Fandral Hirschhaupt",},
			["Fankriss der Unnachgiebige"] = { content = "'''Fankriss der Unnachgiebige''' ist ein [[Silithiden]] [[Sandhäscher]] im [[Tempel von Ahn'Qiraj]].\r\n==Kampf == \r\nFür Fankriss selbst werden 2 Tanks benötigt, die sich abwechseln. Weiter gibt es 3 feste Punkte, an denen kleine Käfer spawnen. Dort wird auch je ein Tank postiert. Sollten dort mehr als 15 Käfer gespawned sein, werden diese durch die Magier weggebombt. Ab und zu beschwört Fankriss einen [[Sandwurm]], den es möglichst schnell zu beseitigen gilt, denn nach 15 Sek wird dieser wütend. Sobald ein Wurm beschworen wurde, ist sofort der Schaden auf Fankriss einzustellen, da in diesem Moment nach jedem HP-Prozentpunkt, das Fankriss verliert, ein weiterer Wurm beschworen wird. Um Fankriss zu töten, hat man genau 10 Minuten Zeit, danach vernichtet er die Schlachtgruppe mit einem Schlag.\r\n* '''Tödliche Wunden''' - Ein Debuff, der mit jeder Spaltungsattacke übermittelt wird und mehrere Spieler in Reichweite treffen kann. Jeder Debuff hält 15 Sek lang an, reduziert die Heilung auf das Ziel um 10% und stapelt bis zu 10 mal. \r\n* '''Käfer''' - In regelmäßigen Abständen spawnen Wellen von Käfern an 3 bestimmten Punkten. Diese sorgen für moderaten Schaden (ähnlich den Drohnen, denen man auf dem Weg zu Fankriss begegnet, nur etwas schlagkräftiger).\r\n* '''Fesslung''' - Jedes mal, wenn eine neue Welle Käfer erscheint, wird ein zufälliger Spieler zu einem der 3 Spawnpunkte geportet und dort für einige Sek gefesselt.\r\n* '''Würmer''' - Zusätzlich entsteht in unregelmäßigen Abständen ein [[Sandwurm]] an einer von 4 möglichen Positionen. Sobald er erschienen ist, muss der Schaden auf Fankriss sofort eingestellt werden, da mit jedem weiteren HP-Prozentpunkt, den Fankriss verliert, ein weiterer Wurm entsteht.\r\n* '''Wutanfall''' - Ab 20% HP wird Fankriss wütend und die Tanks brauchen verstärkte Heilung.",},
			["Faols Ruheplatz"] = { content = "Faols Ruheplatz liegt im nordöstlichen [[Tirisfal]], in der Nähe des [[Scharlachrotes Kloster|Scharlachroten Klosters]]. [[Scharlachroter Kreuzzug|Scharlachrote Kreuzzügler]] haben vom verfallenen Turm hinter Faols Ruheplatz, Überfälle ausgeführt. Nach den Informationen zufolge führt ein unbarmherziger Kommandant mit Namen [[Hauptmann Melrache]] diese bösartige Truppe an.",},
			["Faranell"] = { content = "#REDIRECT [[Apothekermeister Faranell]]", redirect = "Apothekermeister Faranell",},
			["Fasutha"] = { content = "'''Fasutha, Mama'''\r\n1. umgangssprachlich: äußerst beleidigender [[troll]]ischer Fluch.\r\n2. Eine der wenigen trollischen [[Mojo]]-Mamas, deren Name trotz der nahezu vollständigen Vernichtung der [[Gurubashi]]-Hochkultur seit Tausenden von Jahren weiter überliefert wird.\r\nGilt unter den noch traditionell ausgebildeten Mojo-Werfern sowie den wenigen anderen Trollen, die die Überlieferung kennen, als Inbegriff der Dummheit. Beinamen: Mutter des Verrats, Hakkars Schlampe, Die Ewige Kriecherin, Sie Ohne Rückgrat. \r\nFasutha warf sich der Legende nach, entgegen allen Lehren des Mojo, vor dem erschienenen [[Hakkar]] zu Boden und schwor ihm Treue. Ihr Ausruf \"Ich will glauben!\", den sie dabei getätigt haben soll, gilt als absolute Verneinung ihrer Herkunft und Ausbildung. Sie wurde eine der ersten Hohepriesterinnen [[Hakkar]]s in [[Zul Gurub]].\r\nÜber Fasuthas weiteres Schicksal ist nichts bekannt. Sie wird allerdings auf nach Hakkars Fall entstandenen Reliefs oft unbekleidet, sich mit Schlangen paarend, dargestellt.",},
			["Faulblüte"] = { content = "Vorkommen: [[Dämmerwald]]. \r\nAnwendung: Zutat von Zombiesaft. \r\nFaulblüten wachsen an seltsamen Orten. Vor allem, findet man sie in den Schädeln von Skelettschrecken und Skelettsatanskreaturen.",},
			["Faulendes Herz"] = { content = "Bereitet man sie richtig auf, kann man aus den faulenden Herzen der [[Untote]]n mächtige Elixiere gewinnen. Es wird die körperlichen Fähigkeiten im Kampf gegen die Untoten verstärken.",},
			["Federbarts Hütte"] = { content = "'''Federbarts Hütte''' befindet sich im [[Hinterland]] und gehört dem gleichnamigen Zwergischen [[Greifenreiter]]. Federbart genießt bei seinen Leuten hohes Ansehen, sei es wegen seiner legendären Ausbildungsmethoden für [[Greife]]n oder wegen seiner Weisheit. Wenn man den Gerüchten glauben kann, soll er sehr enge Beziehungen mit der [[Allianz]] pflegen. Doch seit einiger Zeit wird er vermißt. Die jüngsten Einträge in seinem Tagebuch beschreiben seine Sorge bezüglich der immer häufigeren Überfälle der [[Trolle der Bleichborken]] auf die [[Greife]]n im Gebiet der [[Zwerge des Wildhammerklan]]s und die sich mehrenden Diebstähle von Eiern. Am Ende des Eintrags steht, dass der [[Zwerg]] die Absicht hat, nach [[Shadra'Alor]] zu gehen und nach den Eiern zu suchen.",},
			["Fegefeuerinsel"] = { content = "Die Fegefeuerinsel liegt vor der südlichen Küste der Vorgebirge des Hügellands. Hier herrscht der Oger Nekromant Kormok, der es liebte, die Seelen der verbannten Toten von der Insel herbeizurufen. Daraufhin reiste Richter Thelgram hierhin, um sich des Problems anzunehmen.",},
			["Fehlerlose Draenethystsphäre"] = { content = "Eine Fehlerlose Draenethystsphäre ist einer der rarsten Edelsteine von ganz [[Azeroth]]. Viele [[Draenei]] suchten ein Leben lang nach einem dieser Kristalle, doch war ihnen kein Erfolg beschert und sie alle endeten auf tragische Weise.",},
			["Fel'dan"] = { content = "#REDIRECT [[Schattenlord Fel'dan]]", redirect = "Schattenlord Fel'dan",},
			["Felder der Mondfinsternis"] = { content = "Die '''Felder der Mondfinsternis''' liegen im [[Schattenmondtal]] südwestlich der [[Stätte der Mondfinsternis]]. Auf diesen Feldern streifen wahnsinnige [[Kolosse]] herum, die zu den [[Blutelfen der Mondfinsternis]] Beziehungen aufgebaut haben.",},
			["Felder des Hügellands"] = { content = "Die '''Felder des Hügellands''' im [[Vorgebirge des Hügellands]] sind fest in der Hand der Menschen. Aber Berichte von Angriffen auf die nördlichen Höfe haben die Stadtbevölkerung in Panik versetzt. Die [[Todespirscher]] melden, dass [[Menschen Arbeiter]] in die Felder ins südliche Hügelland flüchten. Sie glauben, dass sie sich in den Obsthainen verstecken und so ihrer Verdammnis entkommen können. \r\n==Personen==\r\n* '''Bauer Getz'''\r\n* '''Bauer Ray''' - Bauer Ray ist der Cousin von [[Phin Odelic]] und musste letztens seinen Hund Stanley einschläfern lassen, weil das Tier seltsamerweise auf eine immense Größe heranwuchs und jeden bösartig angegriffen hat, der ihm näher kam. Man glaubt, dass die Untoten darin verwickelt sind.\r\n* '''Bäuerin Kalaba''' - Bäuerin Kalaba wird wegen einem hinterhältigem Überfall auf Vorräte von [[Unterstadt]] gesucht.\r\n* '''Bürger Wilkes''' - Bürger Wilkes wird wegen Mordes an [[Apotheker Eli]] gesucht.\r\n* '''Schmied Verringtan'''",},
			["Feld der Riesen"] = { content = "Auf dem Feld der Riesen im [[Brachland]] findet man einen Schwarm [[Silithiden]]. [[Silithiden]] sind neu im [[Brachland]] und vielen gefällt nicht, was sie ankündigen. Doch diese insektenartigen Kreaturen sind ein beliebtes Studienobjekte, denn man weiß nur wenig über sie und sie scheinen intelligent zu sein, intelligenter als normale Tiere. Doch diese [[Silithiden]] scheinen eine größere Bedrohung zu sein, als man dachte, denn diese seltsamen, insektenartigen Kreaturen scheinen außerhalb der natürlichen Ordnung zu stehen, so als würde sie nicht ins [[Brachland]] gehören.",},
			["Felendren der Verbannte"] = { content = "'''Felendren der Verbannte''' ist ein [[Getriebene]]r und haust oben in der [[Akademie von Falthrien]] auf der [[Insel der Sonnenwanderer]] im [[Immersangwald]]. Er wurde aus dem Reich der [[Blutelfen]] verbannt, da er die Warnungen der Lehrer und Ältesten missachtet hat. Er ist der Schlimmste ihrer Art, da er nur nach der Befriedigung seines unstillbaren Magieverlangens strebt. Er hat sich der Kontrolle verweigert und ist nur noch ein Schatten seines einstigen Selbsts - einer der [[Getriebene]]n - und er stellt eine Bedrohung für den [[Sonnenturm]] dar.",},
			["Fels'Gor"] = { content = "Nordöstlich von [[Burg Stromgarde]] im [[Arathihochland]] befindet sich ein [[Oger]]hort, der vom Klan der [[Oger der Felsfäuste]] bewohnt wird.",},
			["Fels'mok"] = { content = "'''Fels'mok''' liegt im [[Schergrat]] im Westen des [[Ewiger Hain|Ewigen Hains]]. Die [[Oger der Blutschläger]] leben dort und hier steht auch der Altar von ''Gorgrom'' dem Drachenfresser, an dem der [[Gronn]] Gorgrom die Opfer der [[Oger]] entgegennimmt.",},
			["Felsadermine"] = { content = "In der Felsadermine im [[Brachland]], nordöstlich des Schlickermoores, arbeiten die [[Goblins]] der [[Venture Company]]. Die jüngste Neuigkeit besagt, dass einer der Minenarbeiter dort einen faustgroßen Katzenaugensmaragd gefunden hat.",},
			["Felsfäuste"] = { content = "#REDIRECT [[Oger der Felsfäuste]]", redirect = "Oger der Felsfäuste",},
			["Felshetzer"] = { content = "Felshetzer sind erbarmungslose Raubtiere, die in den Weiten der [[Scherbenwelt]] zu finden sind. Oftmals lauern sie hinter Steinhaufen und hoch aufragenden Klippen, bereit sich auf die Beute zu stürzen, die töricht genug ist sich in Reichweite ihrer blitzschnellen und messerscharfen Krallen zu begeben. Es ist ungewiss, ob diese Kreaturen durch die unberechenbaren Energien mutiert sind, die freigesetzt wurden, als [[Ner'zhul]] die [[Scherbenwelt]] durch seine Portale auseinandergerissen hat. Eines jedoch ist sicher: Mit diesen bösartigenraubtieren sollte man nicht leichtfertig umgehen.\r\nDiese Kreaturen sind zwar nur leicht gepanzert, widerstehen aber fast jeglicher Magie. Man muss sie mit der einfachen Kraft des Schwerts erlegen.\r\n==Vorkommen==\r\nFür diese wilden Tiere von [[Draenor]] ist [[Azeroth]] eine ganz neue Welt der Beute. Und eine Sache, die die [[Draenei]] auf ihren Reisen gelernt haben, ist, dass man bei der Einführung von Wildtieren aus einer anderen Welt besonders vorsichtig sein muss. Als die [[Exodar]] abstürzte, hatte sie Exemplare verschiedenster Tierarten aus der [[Scherbenwelt]] an Bord, einschließlich eines insektenartigen Raubtiers, dem Felshetzer. Bei dem Absturz starben einige der Tiere, aber viele andere überlebten und suchten in der Wildnis das Weite. Wenn sie sie nicht in Schach halten, werden sie hier auf den Inseln das natürliche Gleichgewicht von Jägern und Gejagten stören. Man findet die Hetzer auf der [[Blutmythosinsel]] westlich von Kessels Wegelager, in der Nähe der Küste.\r\nUrsprünglich stammen Felshetzer von der [[Scherbenwelt]] und es gibt große Vorkommen auf der [[Höllenfeuerhalbinsel]] und im [[Schergrat]].",},
			["Felsklaue"] = { content = "==Allgemeines==\r\nDie Felsklauen gehören zu den Ur-Spezies der [[Scherbenwelt]]. So manch unvorsichtiger Wanderer wurde von diesen primitiven Humanoiden, die auf den Abhängen und Spitzen des [[Schergrat]]s in mörderischen Rudeln umherstreifen, getötet. Obwohl sie in erster Linie kleinere Gebirgstiere jagen, fürchten sie nicht davor sich an potentielle Beute heranzupirschen, welche viel größer ist als sie selbst. Es gibt Berichte von Gruppen von Felsklauen, die selbst die mächtigen [[Elekk]] zu Fall gebracht haben, als diese in deren Gebiet eingedrungen sind. Ihre tückischen Sensenklauen und Hakenfänge sind scharf genug, um durch steile Felswände zu schneiden und es den Felsklauen so zu ermöglichen selbst die schwierigsten Überhänge mit Leichtigkeit zu erklimmen. Selbst für eine räuberische Spezies sind sie extrem schnell und sehr agressiv. \r\n==Besondere Exemplare==\r\n* '''Schwarzkralle die Wilde''' - Felsklauen sind bösartige, hinterhältige und grausame Kreaturen. Aber die normalen sind noch harmlose Schoßtierchen im Vergleich zu ihrer Matriarchin auf der Höllenfeuerhalbinsel. Man findet das Biest in einer Höhle in der großen Kluft.\r\n==Bekannte Arten==\r\n* '''Felsspitzenschinder''' leben in der Nähe der Kristalle auf den [[Netherschwingenfelder]]n im [[Schattenmondtal]] und sind die bevorzugte Beute der [[Netherschwingen]].\r\n* '''Steinsichel''' - Steinsichelalpha und Steinsichelwelpen findet man auf der [[Höllenfeuerhalbinsel]].\r\n* '''Netherminenschinder''' - Netherminenschinder findet man in der Nähe der Kristallformationen im südöstlichen [[Schattenmondtal]] auf der [[Scherbenwelt]].",},
			["Felsklauen"] = { content = "#REDIRECT [[Felsklaue]]", redirect = "Felsklaue",},
			["Felsnarbe"] = { content = "Felsnarbe ist ein [[Koloss]] im [[Nethersturm]]. Er ist der Patriarch der Riesen von [[Farahlon]] und aus seinem Rücken ragen große Farahlitstücke heraus.",},
			["Felsspitzenschinder"] = { content = "#REDIRECT [[Felsklaue]]", redirect = "Felsklaue",},
			["Fennklaue"] = { content = "Fennklauen gehören zu den [[Hydras]] und leben tief im [[Schlangensee]] der [[Zangarmarschen]]. Sie verscheuchen dort nicht nur die Fische, sondern sind auch noch frech genug, die Köder der Angler direkt vom Haken zu stehlen. Die dunklen, schuppigen Bälge der Fennklauen allerdings ergeben eine sehr gute Rüstung.\r\n==Bekannte Tiere==\r\n* [[Mragesh]]",},
			["Fennklauen"] = { content = "#REDIRECT [[Fennklaue]]", redirect = "Fennklaue",},
			["Fenrus"] = { content = "#REDIRECT [[Fenrus der Verschlinger]]", redirect = "Fenrus der Verschlinger",},
			["Fenrus der Verschlinger"] = { content = "'''Fenrus der Verschlinger''' ist [[Arugal]]s gewaltiger Schloßhund in [[Burg Schattenfang]]. Trotz seiner imensen Größe lassen sich die wenigsten Helden davon abbringen, den Kampf gegen diesen Schwarzworg zu suchen, denn sein Fell wird gern sowohl als hochwertiger Umhang () als auch als schützende Armschienen getragen ().\r\n===Fähigkeiten===\r\n* ''Toxinspeichel'' - Fenrus' Toxinspeichel fügt einem Feind alle 6 Sekunden 17 Naturschaden zu. Es entzieht außerdem alle 6 Sekunden 20 Mana und überträgt sie auf den Zaubernden. Hält 2 Min. lang an.",},
			["Feralas"] = { content = "'''Feralas''' ist ein stark bewaldetes Gebiet im westlichen [[Kalimdor]]. Ein Stamm von [[Oger]]n, die sich Gordunni nennen, ist die vorherrschende Militärmacht in Feralas, und ihre Zahl wächst. [[Horde]] und [[Allianz]] wollen sie aufhalten, bevor sie die Anwesenheit der beiden Fraktionen in diesem Gebiet bedrohen.\r\n==Personen==\r\n* [[Zorbin von Schiller]]\r\n==Orte==\r\n* [[Außenposten der Gordunni]]\r\n* [[Camp Mojache]]\r\n* [[Grimmtotem Posten]]\r\n* [[Insel des Schreckens]]\r\n* [[Insel Sardor]]\r\n* [[Lariss Pavillon]]\r\n* [[Mondfederfeste]]\r\n* [[Ruinen von Rabenwind]]\r\n* [[Thalanaar]]\r\n* [[Verwundene Tiefe]]\r\n* [[Wildschrammtal]]\r\n==Felsbeißers Lager==\r\nFelsbeißers Lager liegt nördlich der Zwillingsspitzen. Der Erdriese Felsbeißer sollte auf seine kleine Freundin, die [[Streunende Shay]], aufpassen, aber sie ist ihm verloren gegangen als sie durch die Ruinen direkt nördlich des Lagers liefen.\r\n==Obere Wildnis==\r\nIn der oberen Wildnis gibt es einige verlassene und zerstörte Gebäude auf dem Land, das einst den [[Nachtelfen]] gehörte. Die [[Oger der Gordunni]] haben dieses Gebiet besetzt und sie reagieren nicht sehr freundlich auf jemanden, der ihr Territorium betritt.\r\n==Wutschrammfeste==\r\nIm nördlichen Teil von Feralas, tief in der Wutschrammfeste gibt es noch andere [[Yetis]]. Diese Wesen sind noch um einiges stärker, als die Wildschrammyetis.\r\n==Zwillingskolosse==\r\n[[Gregan Hopfenspei]] hat ein Lager in der Wildnis von Feralas bei den Zwillingskolossen. Er ist ein Experte auf dem Gebiet von seltenen Pflanzen und kann helfen, das [[Videre-Elixier]] herzustellen.",},
			["Fernwacht"] = { content = "Die Fernwacht ist eine Garnison der Orcs an der Grenze vom [[Brachland]] und [[Durotar]].\r\n==Personen==\r\n* '''Ak'Zeloth''' - Orc. [[Brennende Klinge]]. Assistent von [[Neeru Feuerklinge]]. Er hat Kraftsteine vorbereitet, die, wenn sie am Altar des Feuers in der Nähe der [[Dämonensaat]] auf dem [[Glutnebelgipfel]] platziert werden, die Verbindung der dortigen Kultisten zur Legion unterbrechen sollen. \r\n* '''Kargal Schlachtnarbe''' - Kargal braucht ein paar neue Rekruten für den Dienst im [[Brachland]] und die [[Wegekreuz]]wehrpflicht. \r\n* '''Uzzek''' - Er ist ein Veteran zahlreicher Kämpfe und unterrichtet jetzt junge Krieger in der Gefechtskunst auf dem Weg der Verteidigung.",},
			["Feste der Legion"] = { content = "Die '''Feste der Legion''' im westlichen [[Schattenmondtal]] ist fast uneinnehmbar. \r\nDie beiden [[Grubenlord]]s in der Feste, [[Makazradon]] und [[Morgroron]], besitzen antidämonische Waffen und die meisten [[Mo'arg]] in der Feste scheinen Bruchstücke dieses Metalls zu bearbeiten. Doch die Splitter scheinen von einer noch größeren Waffe zu stammen. Ein bedrohliches Leuchten geht von den kantigen Runen, die in das Metall geätzt wurden, aus. Es ist nicht klar, welche Aufgabe die Waffe hatte, aber sie ist nur schwer zu verkennen. Die Waffe wurde aus einem sehr seltenen Erz geschmiedet, aber es handelt sich dabei nicht um eine gewöhnliche Klinge. Diese Runen erfüllen die Klinge mit der Macht, [[Dämonen]] zu vernichten. Wenn die Legion ihre eigenen Truppen mit [[Dämonen]] zerstörenden Waffen ausrüstet, muss ihr Hass auf [[Illidan]] unendlich groß sein. \r\nDie wenigen Informationen, die man sammeln konnte, weisen darauf hin, dass die Legion die [[Höllenbestien]] in der Feste lagert und vorbereitet. Man sagt ebenso, dass sie genügend [[Höllenbestien]] haben, um die Angriffe noch zu verstärken. Laut Razuuns Befehlen wird der riesige Stützpunkt der [[Höllenbestien]] [[Invasionspunkt: Katastrophe]] genannt und befindet sich in den nördlichen Bergen. Der einzige Weise, auf die man dorthin gelangen kann, ist ein Teleporter. Ausgewählte Mitglieder der Legion, wie z.B. die Waffenschmiede der [[Mo'arg]] tragen Geräte bei sich, mit denen sie die Teleporter aktivieren können.",},
			["Feste Nordwacht"] = { content = "Die Feste Nordwacht ist eine mächtige Burg im Süden von [[Ratschet]] im [[Brachland]]. Marinesoldaten aus [[Theramore]] halten sich in der Feste auf, doch sind verrückt geworden, denn ihr Verfolgungswahn hat sie in eine Art Raserei versetzt. Diese schießwütigen, rücksichtslosen Rüpel schießen auf alles, was sich bewegt. \r\n==Personen==\r\n* '''Gilthares Feuerzweig''' - Der [[Hochelf]] Gilthares Feuerzweig war Decksmann auf einem Fuseltransporter zwischen [[Ratschet]] und [[Beutebucht]], doch die Fanatiker aus [[Theramore]] haben sein Schiff versenkt und ihn, den einzigen Überlebenden, eingesperrt. Sie nannten ihn ihren Feind und eine Gefahr für die [[Allianz]]. Nun wartet Gilthares in einem Turm in der Feste auf seine Befreiung und braucht eine sichere Eskorte zurück zu [[Kapitän Thalo'thas Blendsonn]] in [[Ratschet]].",},
			["Festung Angor"] = { content = "Die '''Festung Angor''' ist eine Bastion der [[Zwerge der Schattenschmiede]] im [[Ödland]], in der Nähe von [[Uldaman]]. Hierhin bringen die [[Dunkeleisenzwerge]] die in Uldaman geborgenen Schätze und [[Ragnaros]] persönlich schickte den [[Botschafter Infernus]] als Gesandten zur Festung, damit er dort die Suche der Zwerge nach verschollenen Artefakten organisiert.",},
			["Festung der Ango'rosh"] = { content = "#REDIRECT [[Oger der Ango'rosh]]", redirect = "Oger der Ango'rosh",},
			["Festung der Stürme"] = { content = "Die fliegende '''Festung der Stürme''' befindet sich im Osten des [[Nethersturm]]s in der [[Scherbenwelt]] und ist nur durch die Luft zu erreichen. Diese ehemalige Basis der [[Naaru]] wurde von [[Blutelfen]] eingenommen und dient nun als Hauptquartier von [[Kael'thas Sonnenwanderer]]. \r\n==Geschichte==\r\nDie mächtige Festung der Stürme wurde von den mysteriösen [[Naaru]] erschaffen: empfindungsfähigen Wesen aus reiner Energie und die Erzfeinde der [[Brennende Legion|Brennenden Legion]]. Sie dient als Operationsbasis der Naaru, doch zusätzlich verfügt das Bauwerk selbst über die Technologie, sich durch alternative Dimensionen zu bewegen, wodurch sie augenblicklich von einem Ort zu einem anderen reisen kann. Mit der [[Scherbenwelt]] als strategische Front im fortwährenden Brennenden Kreuzzug sind die [[Naaru]] kürzlich mit der Festung der Stürme in dieses zerschlissene Land gereist. Als jedoch die Naaru aus ihrem Bollwerk zogen, stürmten Prinz [[Kael'thas Sonnenwanderer]] und seine [[Blutelfen]] die dimensionale Festung und übernahmen die Kontrolle über deren umliegende Anlagen. Nun manipuliert Kael'thas aus unbekannten Gründen die metaphysischen Technologien der Festung, um sich die chaotischen Energien des [[Nethersturm]]s zu Nutze zu machen. Obwohl Kael'thas und seine Gefolgsleute die Burg fest im Griff halten, hat es eine Gruppe [[Draenei]] kürzlich geschafft, eine der äußeren Anlagen, die [[Exodar]], zu übernehmen und mit ihr aus der Scherbenwelt zu entkommen. Indem sie andere Welten besuchten, erhofften sich die Draenei unter der Führung des alten Propheten [[Velen]], Verbündete zu finden, welche ihnen im Kampf gegen die Legion in ihrem alles vernichtenden Kreuzzug beistehen würden. \r\n==Teilbereiche==\r\nSie ist in drei kleinere Flügel unterteilt: \r\n* [[Festung der Stürme: Arkatraz]]\r\n* [[Festung der Stürme: Botanika]]\r\n* [[Festung der Stürme: Mechanar]]\r\n* [[Festung der Stürme: Das Auge]]\r\nDie [[Exodar]] auf [[Azeroth]] ist - oder war der ursprüngliche vierte Flügel dieses Komplexes. Im [[Festung der Stürme: Das Auge|Auge]] sitzt [[Kael'thas Sonnenwanderer]] selbst.",},
			["Festung der Stürme: Arkatraz"] = { content = "'''Die Arkatraz''' ist ein Teil der [[Festung der Stürme]] und im Osten des [[Nethersturm]]s in der [[Scherbenwelt]] zu finden. Ursprünglich gehörte dieses Schiff den [[Naaru]] und diese haben auf ihren Reisen viele gefährliche Wesen getroffen. Einige dieser Wesen wurden eingefangen und werden nun in der Arkatraz gefangen gehalten. Unglücklicherweise haben zuerst die [[Blutelfen]] unter [[Kael'thas]] und dann die [[Dämonen]] das Gefängnis überrannt.\r\n[[Aufseher Mellichar]] hat sich zum Eindämmungskern der Arkatraz begeben und die Schützhüllen deaktiviert. Er wußte, Prinz Kael'thas würde darüber wütend sein, aber Mellichar war nicht er selbst. Er mußte die Kreaturen freilassen, denn der Großmächtige spricht zu ihm. Allerdings sagt er einfach, dass Eindringlinge die Gefangenen freigelassen hätten.\r\n==NSC's==\r\n* [[Millhaus Manasturm]]\r\n==Bosse==\r\n* [[Dalliah die Verdammnisverkünderin]]\r\n* [[Drakonaar des Zwielichts]]\r\n* [[Herold Horizontiss]]\r\n* [[Zereketh der Unabhängige]]\r\n* [[Zornseher Soccothrates]]",},
			["Festung der Stürme: Botanika"] = { content = "Die Botanika ist ein Flügel der [[Festung der Stürme]] im Osten des [[Nethersturm]]s auf der [[Scherbenwelt]] und nur durch die Luft zu erreichen. Es ist die Residenz von [[Kommandant Sarannis|Sarannis]], einem Kommandanten von [[Kael'thas]].\r\n==Bosse==\r\n* [[Kommandant Sarannis]]\r\n* [[Hochbotaniker Freywinn]]\r\n* [[Dorngrin der Hüter]]\r\n* [[Laj]]\r\n* [[Warpzweig]]",},
			["Festung der Stürme: Das Auge"] = { content = "'''Das Auge''' ist ein 25-Mann Schlachtzug-Dungeon in der [[Festung der Stürme]] im [[Nethersturm]]. Es ist der Sitz von Prinz [[Kael'thas Sonnenwanderer]].",},
			["Festung der Stürme: Mechanar"] = { content = "Die Mechanar ist die erste von drei 5er-Instanzen die man in der [[Festung der Stürme]] im Osten von [[Nethersturm]] findet. Diese sind, da sie keine Verbindung mit dem Festland haben, nur mit Hilfe von Flugmounts oder in der Flugform zu erreichen. In der Mechanar werden Manazellen, in denen eine unglaubliche Menge an Energie gespeichert ist, hergestellt.\r\n==Bosse==\r\n* [[Torwächter Eisenhand]]\r\n* [[Mechanolord Kapazitus]]\r\n* [[Torwächter Gyrotod]]\r\n* [[Nethermant Sepethrea]]\r\n* [[Pathaleon der Kalkulator]]",},
			["Festung des Drachenmals"] = { content = "Die '''Festung des Drachenmals''' im [[Schattenmondtal]] ist der Hauptsitz der [[Orcs des Drachenmals]]. Sie liegt in den östlichen Ausläufern der [[Netherschwingenfelder]]. Dort findet man [[Ruul der Verfinsterer|Ruul den Verfinsterer]] mit dem dritten Teil der [[Litanei der Verdammnis]] irgendwo zwischen der Feste des Drachenmals und dem [[Sanktum der Sterne]]. \r\nIn der Festung selbst foltern die grausamen Orcs des Drachenmalklans gefangene [[Netherdrachen]], um sie ihrem Willen zu unterwerfen. Viele der Drachen haben die Hoffnung verloren und befolgen die Befehle der Drachenmalorcs. Die anderen weigern sich, zu landen, aus Angst, von den Orcs gefangen und in die Festung verschleppt zu werden. Die Drachen sind machtlos. Illidan fand und brachte den Drachenmalorcs ihren Anführer: [[Zuluhed]]. Dieser Orc war einst für die Gefangennahme und Einkerkerung von Alexstrasza verantwortlich. Er nahm einen Drachenaspekt gefangen! Wie könnten die Netherdrachen gegen solche Macht kämpfen. Und genauso leicht nahm Zuluhed [[Neltharaku]]s Gefährtin [[Karynaku]] gefangen. Nun wird sie auf der Feste des Drachenmals gefangen gehalten. Neltharaku hat viele Versuche unternommen, sie zu befreien. Aber alle sind fehlgeschlagen.",},
			["Festung Donneraxt"] = { content = "Die Festung Donneraxt im Osten von [[Ethel Rethor]] in [[Desolace]] ist ein Stützpunkt der [[Orcs der Brennenden Klinge]] und diese sind im Besitz eines wertvollen Artefakts, des [[Dämonenkasten]]s. Darin liegt die mächtige [[Hand von Iruxos]], die die Anhänger der [[Orcs der Brennenden Klinge|Brennenden Klinge]] verwenden, um dämonische Portale beim [[Zirkel des Mannoroc]] zu öffnen. Mittels einer Dämonenhacke kann man über den roten Kristall in der Festung Zugang zum [[Dämonenkasten]] erlangen. \r\nDie [[Orcs der Brennenden Klinge]] in der Festung sollen Gerüchten zufolge auch das [[Szepter des Lichts]] von den [[Naga]] erworben haben. Die Legenden besagen, dass das Szepter dazu fähig ist, ganze Städte unter den Ozeanen verschwinden zu lassen. Es ist im Besitz eines Sehers der [[Brennende Klinge|Brennenden Klinge]], der das Szepter in einem der Wachtürme der Feste studiert. \r\nHier in der Festung wird auch die Nachtelfe [[Dalinda Malem]] und ihr Bruder [[Tyranis Malem]] gefangen gehalten. Sie sind Adlige einer Kaufmannsfamilie aus [[Darnassus]] und kamen vor wenigen Wochen durch das [[Steinkrallengebirge]]. Nachdem die Orcs aus der Festung Donneraxt ihren Wagen überfallen und alle Wachen und Diener abgeschlachtet hatten, wurden die beiden Elfen in die Festung gebracht. Dalinda Malem hofft, dass sie von [[Vahlarriel Dämonenjäger]] oder einem seiner Helfen befreit wird, aber sie kann nicht weg, bevor sie weiß, was ihrem Bruder Tyranis zugestoßen ist. Dieser hat jedoch inzwischen die Seiten gewechselt und ist zum Verräter geworden. Er sollte gefesselt werden, ehe man ihn nach Hause bringt.",},
			["Festung Drak'Tharon"] = { content = "'''Drak'Tharon''' ist eine Festung der [[Eistrolle]] im Norden der [[Grizzlyhügel]] auf [[Nordend]]. Diese befand sich ursprünglich in den Händen der [[Drakkari]]. Doch wurden die Hauerträger, von der [[Geißel]] vertrieben. Nun ist Drak'Tharon eine unmittelbare Gefahr für die Region, da sich aus ihr Scharen untoter [[Eistrolle]], Fledermäuse, Raptoren und der [[Geißel]] wie eine Flut über das Land ergießen. , \r\nDie Geißel hat hier nun eine Basis errichtet und findet es gar nicht so lustig, das Eure Heldentruppe vorbei schaut. Die geradelinige Instanz erinnert ein wenig an ihre Vettern, die Outdoor-Troll-Dungeons Zul'Farrak, Zul'Gurub und Zul'Aman. Seit Ihr anfänglich noch im Inneren der Festung unterwegs, gelangt Ihr auch hier schließlich unter freien Himmel und könnt Euer Reittier benutzen. \r\n==Bosse==\r\n* [[König Dred]]\r\n* [[Novos der Beschwörer]]\r\n* [[Prophet Tharon'ja]]\r\n* [[Trollgrind]]",},
			["Festung Kil'sorge"] = { content = "Die '''Festung Kil'sorge''' liegt im Süden von [[Nagrand]] an der Grenze zu den [[Wälder von Terokkar|Wäldern von Terokkar]], etwas westlich von den [[Ruinen der Brennenden Klinge]]. [[Giselda die Alte]] von Kil'sorge und ihre Lakaien dort werden gesucht wegen Mordes, rituellen Opferungen, Verbrüderung mit der Legion, Entführung und Diebstahl.",},
			["Festung Schattenmond"] = { content = "Die Festung Schattenmond lag jenseits der [[Knochenwüste]] im [[Schattenmondtal]] und wurde von Hochburgen an der [[Skelettküste]] bewacht. Sie war einst der Sitz des Schamanen [[Ner'zhul]]. \r\nUm das [[Dunkle Portal]] für alle Zeiten zu versiegeln und die Bedrohung durch die [[Orcs]] zu beenden, schickte die [[Allianz]] ihre Truppen in die Welt [[Draenor]]. [[Ner'zhul]] und einige [[Todesritter]] waren in die königliche Bibliothek von Neu [[Sturmwind]] eingedrungen und hatten dort das [[Buch des Medivh]] gestohlen. Dieses magische Artefakt war notwendig, um neue Portale zu erschaffen oder das bestehende entgültig zu verschließen und [[Ner'zhul]] hielt das Buch in seiner Festung Schattenmond versteckt. Die [[Orcs des Schattenmondklans]] und die Todesritter stellten sich den Armeen der [[Allianz]] entgegen, aber [[Ner'zhul]]s dunkle Festung wurde von ihnen zerstört. Der Schamane konnte zwar mit einigen magischen Artefakten entkommen, aber das „[[Buch des Medivh]]“ fiel dem [[Klan des lachenden Schädels]] in die Hände.",},
			["Feuerbrandlegion"] = { content = "Die '''Trolle der Feuerbrandlegion''' sind einer von zwei Stämmen der [[Waldtrolle]], die der Dunklen Horde angehören, einer abtrünnigen Gruppe von Orks, Trollen und Ogern, die in der [[Schwarzfelsspitze]] leben. Die [[Dunkle Horde]] unter dem Kommando von [[Rend Schwarzfaust]] hat den Kampf um die Herrschaft von [[Azeroth]] noch nicht aufgegeben, auch wenn Rends Streitmacht deutlich kleiner ist als [[Thrall]]s Horde. Treibende Kraft der [[Dunklen Horde]] ist eine Gruppe von [[Hexenmeister]]n, die immer noch wie in der ursprünglichen Horde mit dämonischen Kräften im Bunde sind. Im Prinzip kämpft die [[Dunkle Horde]] weiterhin den Zweiten Krieg, aber Rend und seine Leute wissen, dass sie nur sehr geringe Chancen auf Erfolg haben, trotz ihres Bündnisses mit dem [[Schwarzer Drachenschwarm|schwarzen Drachenschwarm]]. Die Anzahl der Mitstreiter der Dunklen Horde schrumpft ständig, und es gibt keine Möglichkeit, neue Rekruten zu gewinnen. Die bösartigen Krieger sind sich bewusst, dass Ihre Tage gezählt sind, doch durch dieses Wissen wird ihre geistige Haltung nur noch düsterer - sie sind verzweifelt, verbittert und im Kampf absolut gnadenlos. Die Feuerbrand verehren die Erinnerung an [[Zul'jin]]. Sie betrachten die [[Trolle der Gluthauer]] als annehmbare Verbündete und verabscheuen alle anderen Trollstämme als Verräter, insbesondere die [[Trolle der Bruchhauer]] mit seinen Verbindungen zu Thralls Horde. Ironischerweise halten die Bruchhauer die Feuerbrand ebenfalls für Verräter, da sie Thrall und seine Gefolgschaft als die wahre Horde betrachten und den Feuerbrand vorwerfen, nicht die [[Schwarzfelsspitze]] verlassen und sich Thrall angeschlossen zu haben. Im Allgemeinen sind sich die Trolle außerhalb der Dunklen Horde schon lange einig, dass die Feuerbrand und Gluthauer verrückt sein müssen, sich mit dem schwarzen Drachenschwarm zu verbünden und einen verlorenen Krieg weiterzukämpfen, sofern dieser die Bezeichnung Krieg überhaupt noch verdient.\r\n==Klassen==\r\n* [[Dunkelwirker]] der Feuerbrand\r\n* [[Grunzer]] der Feuerbrand\r\n* [[Herbeirufer]] der Feuerbrand\r\n* [[Legionär]] der Feuerbrand\r\n* [[Pyromant]] der Feuerbrand\r\n* [[Schreckenswirker]] der Feuerbrand\r\n==Persönlichkeiten==\r\n* '''Bannok Grimmaxt''' - Bannok Grimmaxt ist der Champion der Feuerbrandlegion\r\n'''Quellen:'''",},
			["Feuerelementar"] = { content = "Feuerelementare sind [[Elementare|Elementarwesen]] aus dem Feuer der Elemente. Das Feuer ist ein chaotisches Element. Ein Feuer, dass niemals ausgeht, ist ein Symbol von Hochmut. Flammen verzehren, was sie selbst brennen lässt und sterben dann, um ein andermal wieder entfacht zu werden.\r\n==Arten==\r\n* [[Flammender Aspekt]]\r\n* [[Lodernde Eindringlinge]]\r\n•[[Salamander]]\r\n==Besondere Feuerelementare==\r\n* [[Baron Geddon]]\r\n* [[Baron Glutarr]]\r\n* [[Botschafter Infernus]]\r\n* [[Feuerwache Glutseher]]\r\n* [[Glutos]]\r\n* [[Lord Incendius]]\r\n* [[Sturmflamme]]\r\n* [[Übermeister Pyron]]",},
			["Feuerelementare"] = { content = "#REDIRECT [[Feuerelementar]]", redirect = "Feuerelementar",},
			["Feuerlande"] = { content = "Die '''Feuerlande''' sind eine der elementaren Ebenen von [[Azeroth]] und Heimat der [[Feuerelementare]]. Die Feuerlande werden von mächtigen Vulkanen dominiert, die wie Gebirge in den Himmel ragen. Kein anderes [[Elementar]] vermag die Feuerlande zu betreten, ohne verzehrt zu werden. In der Mitte der Feuerlande liegt ein See aus geschmolzenen Metallen, Schwefel und Lava. In ihr steht die [[Festung Sulfuron]], die Residenz von [[Ragnaros]]. Doch seit der Feuerfürst von den [[Dunkeleisenzwerge]]n nach Azeroth gerufen wurde, regieren die Feuerprinzen das Reich und sorgen dafür, dass der Wille ihres Meisters durchgesetzt wird.",},
			["Feuerstreich"] = { content = "#REDIRECT [[Felo'melorn]]", redirect = "Felo'melorn",},
			["Feuersäulengrat"] = { content = "Der Feuersäulengrat ist ein brodelnder Vulkan in der Mitte des [[Krater von Un'Goro]], auf dem [[Feuerelementare]] und ihr Anführer [[Sturmflamme]] ihr zu Hause haben. Der Lavasee an seiner Spitze ist heiß genug, um Thorium und Knochen miteinander zu verschmelzen. [[Ringo]] ist vor einer Weile aufgebrochen, um den Vulkan zu erforschen. Er war gerade dabei, die Gegend zu erkunden, als die Hitze plötzlich unerträglich wurde. Er muss wohl einen Hitzschlag haben und fühlt sich ziemlich schwach. Bis Hilfe kommt, wartet er auf dem Grat in einer Höhle.",},
			["Feuerwache Glutseher"] = { content = "Feuerwache Glutseher ist ein hochrangiges [[Feuerelementar]], dass in der [[Obere Schwarzfelsspitze|Oberen Schwarzfelsspitze]] von mehreren [[Hexenmeister]]n gefangen gehalten wird. Wenn jedoch die [[Hexenmeister]] aus ihrem Trance geholt und zerstört werden, wird Glutseher frei kommen und versuchen alles in seiner Nähe zu zerstören. \r\nAufgrund des gegenwärtigen Krieges zwischen [[Ragnaros]] und [[Nefarian]] kann man sicherlich annehmen, dass Glutseher von den [[Orcs des Schwarzfels]]klans gefangen genommen wurde. Er muss ziemlich mächtig gewesen sein, wenn man die Menge an [[Hexenmeister]]n berücksichtigt, die gebraucht werden, um ihn in Schach zu halten. Warum die [[Orcs des Schwarzfels|Schwarzfelsorcs]] ihn einsperrten, statt auf der Stelle zu töten, ist unbekannt.",},
			["Feuerwasser der Winterfelle"] = { content = "Das Feuerwasser der Winterfelle ist eine grünliche Flüssigkeit, die ein wenig an den Schleim erinnert, den man im [[Teufelswald]] sieht. Es enthält Spuren von toxischen Elementen. Wenn diese toxische Substanz mit dem Wasser aus den heißen Quellen in [[Winterquell]] gemischt wird, verliert sie ihre Toxizität und behält lediglich die Fähigkeit zurück, Kreaturen vorübergehend zu beeinflussen, die sie einnehmen. Darum verteidigen die [[Furbolgs der Winterfelle]] die heißen Quellen in [[Winterquell]] wohl so vehement - sie brauchen sie, um ihr Feuerwasser zu läutern. \r\nDas Feuerwasser der Winterfelle erhöht 20 Minuten lang die Angriffskraft um 35 sowie auch diee Größe.",},
			["Feuriges Schlachtross"] = { content = "Das '''Feurige Schlachtross''' ist das Reittier von [[Attumen der Jäger|Attumen dem Jäger]]. Die Zügel des feurigen Schlachtrosses können mit viel Glück in [[Karazhan]] bei Attumen gefunden werden. Um sie zu benutzen, benötigt es Stufe 70 und einen Fertigkeitswert von Reiten (150). Das Feurige Schlachtross ist ein sehr schnelles Reittier.",},
			["Fineous Dunkelader"] = { content = "'''Fineous Dunkelader''' ist der neue Chefarchitekt in den [[Schwarzfelstiefen]]. Er ist ein Zwerg mit fragwürdigen Motiven und wenig Talent im Vergleich zu seinem Vorgänger: [[Franclorn Schmiedevater]]. Fineous befindet sich jenseits des Rings des Gesetzes in der Halle des Handwerks und bewacht den Hammer \"[[Eisenhölle]]\". Fineous ist so unfähig, dass er die wahre Macht von Eisenhölle nicht begreift. Wenn man den Hammer erbeutet, kann man mit seiner Hilfe am „Schrein von Thaurissan“ gegen den [[Schlüssel zur Schattenschmiede]] erlangen.",},
			["Finsterblut"] = { content = "#REDIRECT [[Zerschlagene der Finsterblut]]", redirect = "Zerschlagene der Finsterblut",},
			["Finsterblutstamm"] = { content = "#REDIRECT [[Zerschlagene der Finsterblut]]", redirect = "Zerschlagene der Finsterblut",},
			["Finsteres Riff"] = { content = "Das finstere Riff liegt vor der Küste des [[Schlingendorntal]]s und ist die Heimat der Salzschuppenmurlocs. Dort liegt eine versunkene Trollstadt und der [[Altar der Gezeiten]]. Vor langer Zeit, als ein großes Beben die Welt erschütterte, versank eine alte Trollstadt in den Wassern der ungezähmten Küste im Nordwesten. Sie nennen diesen Ort das finstere Riff, denn [[Murlocs]] bewohnen jetzt die Ruinen der Stadt und greifen jeden an, der sich ihnen nähert. In diesen alten Ruinen liegt eine alte Schrifttafel, die zweite Schrifttafel der Troll-Legenden, die die uralte [[Gri’lek der Wanderer|Geschichte von Gri'lek]] erzählt, einem Helden der Trolllegenden. Die Geschichte ist dem [[Dunkelspeere|Dunkelspeerstamm]] heilig und auch wenn die Tafel zu groß ist, um sie zu bewegen, so möchte die Dunkelspeer doch einen Splitter davon, um ihn in [[Orgrimmar]] in einen Schrein legen kann.",},
			["Finsterflügelschimäre"] = { content = "#REDIRECT [[Schimäre]]", redirect = "Schimäre",},
			["Fischadler"] = { content = "Die '''Fischadler''' (engl. ''Flying Osprey'') war ein elfischer Zerstörer, der sich der [[Dritte Flotte von Kul Tiras]] aus [[Lordaeron]] angeschlossen hatte. Dieses Schiff liegt heute südlich vom [[Hafen von Menethil]] auf Grund und transportierte eine Ladung Lichtgeschmiedetes Eisen. Sie schloss sich der Dritten Flotte aus Sicherheitsgründen an. Welche Ironie, dass es von denselben [[Drachen]] versenkt wurde, mit deren Feuer man dieses Eisen geschmolzen hatte. Dieses Metall ist wertvoll für [[Sturmwind]], da Gegenstände, die daraus gefertigt werden, mit heiliger Wahrheit zuschlagen. Leider haben die [[Murlocs]] den Großteil der Lichtschmiedeblöcke gestohlen. Wenn das verlorene Lichtgeschmiedete Eisen überhaupt gefunden werden kann, dann weiß [[Glorin Stahlbraue]], wo man danach suchen muss. Der ehemalige Erste Maat der FISCHADLER war [[Snellig]] dessen Schnupftabakdose man heute noch im Wrack finden kann.",},
			["Fische"] = { content = "'''Fische''' tummeln sich in nahezu allen Gewässern auf [[Azeroth]] und der Scherbenwelt. Oftmals sind diese friedlichen Wildtiere das Ziel von Anglern, andere sind durchaus wehrhaft und können ganz schön zubeißen.\r\n==Arten==",},
			["Flammenkamm"] = { content = "Der '''Flammenkamm''' ist ein kleines neutrales Lager im Norden der [[Brennende Steppe|Brennenden Steppe]] mit einem Flugpunkt für die [[Horde]].\r\n==Personen==\r\n* [[Struppiger John]]\r\n* [[Tinkee Kesseldampf]]\r\n'''Sonstige'''\r\n* '''Kilber''' - Kilber liebt Tiere, aber er ist Händler von Beruf. Er spürt exotische Tiere für die Reichen und Berühmten auf und dann zähmt er die Bestien, damit sie sich auch wie brave Tiere verhalten. Es gibt da draußen Leute, die gutes Geld selbst für die übelsten der abgerichteten Bestien ausgeben würden. Auf der Suche nach Exotischen Tieren, würde er gern einen [[Worgwelpe]]n der [[Trolle der Blutäxte]] aus der [[Schwarzfelsspitze]].\r\n* '''Mathredis Feuerstern''' - Mathredis Feuerstern sucht von den Elfenmeistern geschriebene Buchbände. Doch sie gingen verloren und wurden in aller Welt verstreut als die Geißel über [[Quel'Thalas]] kam. Jetzt sucht er nach diesen Buchbänden, um ihre Geheimnisse zu bergen- und verlorene Macht zurückzugewinnen. Er sucht speziell die zehn Bücher, die Meister Karial Winthalus schrieb. Sollte man so einen Buchband finden, so kann Mathredis dessen magische Eigenschaften absorbieren, und mittels der entsprechenden Materialien ein entsprechendes Geringes Arkanum daraus herstellen. Zu den verlorenen Büchern gehören:\r\n** [[Buchband der Abhärtung]]\r\n** [[Buchband der Gier]]\r\n** [[Buchband der Hartnäckigkeit]]\r\n** [[Buchband der Konstitution]]\r\n** [[Buchband des Nachsinnens]]\r\n* '''Maxwort Funkelglanz''' - Maxwort Funkelglanz sucht die Abschrift der [[Schrifttafel der Sieben]], denn die Legenden der Sieben führten ihn in die [[Brennende Steppe]]. Wenn man über Wissen und Macht verfügt, so ist das der Schlüssel zum Reichtum. Und genau das ist es, was er will: Reichtum. Schon seit Jahren sucht er einen ganz bestimmten Edelstein. Er wird das '[[Herz des Berges]]' genannt und ist so groß wie eine Faust.",},
			["Flammenschlund"] = { content = "==Allgemeines==\r\nDer Flammenschlund besteht aus einer Reihe vulkanischer Höhlen, die unter [[Orgrimmar]] verlaufen, der neuen [[:Kategorie:Hauptstadt|Hauptstadt]] der [[Orcs]]. Vor nicht allzulanger Zeit soll sich in den feurigen Tiefen ein Kult eingenistet haben, der dem dämonischen [[Schattenrat]] nahe steht. Dieser Kult, der sich selbst die \"[[Brennende Klinge]]\" nennt, stellt eine direkte Bedrohung der Unabhängigkeit von [[Orgrimmar]] dar. Viele glauben, dass Kriegshäuptling [[Thrall]] die [[Brennende Klinge|Brennenden Klinge]] nur deshalb nicht sofort auslöscht, weil er sich erhofft, dass sie ihn direkt zu seinem wahren Feind führen werden, dem mysteriösen [[Schattenrat]] selbst. Dennoch könnten die dunklen Mächte, die sich im Flammenschlund sammeln, alles zerstören, was die [[Orcs]] mit so viel Blut und Leid erkämpft haben.\r\n'''Quelle:''' \r\n===[[Gadgetzan Gazette]]===\r\nIn der Kluft der Schatten in Orgrimmar findet man den Eingang zum [[Flammenschlund]]. [[Craven Drok]] dreht hier seine Runden. Für den geneigten Zuhörer hat er vielleicht sogar eine Aufgabe… Wer Hitze schlecht verträgt, wird es hier schwer haben. Den Frust kann man aber an den vielen Gegnern auslassen. Diese reagieren auf Besucher leider im Allgemeinen eher unfreundlich. Tiefer in den Höhlen trifft man auf [[Troggs]]. Das Verfolgen der schamanistischen Traditionen lässt zwar auf eine gewisse Grundintelligenz schließen, leider verliefen die Interviews mit ihnen aber eher einseitig. „Ein paar Steine in den Weg legen“ wird hier neu definiert. Diese Elementarwesen sind sehr gesellig - leider nur für Artgenossen. Eine Großaufnahme der Halle, könnte bei zukünftigen Besuchen helfen. Hier eröffnet sich ein wunderschöner Blick. Überwindet man die Gruppen der orkischen Fanatiker, so trifft man auf [[Taragaman der Hungerleider|Taragaman den Hungerleider]]. Eine Profilaufnahme von Taragaman, man beachte das ausgeprägte Anführerkinn. Diese Aufnahme wurde während des recht hasserfüllten Hinweises aufgenommen, dass „vom Hungerleider keine Bilder gemacht werden“. So gut sah er eh nicht aus. Dieser „nette“ Wachmann wollte mich daran hindern, Aufnahmen der im Hintergrund zu sehenden Persönlichkeiten zu schießen. Einfach den Arm gehoben und abgedrückt – ein Mitglied der KLicKIE lässt sich nicht einschüchtern! Der Wachmann ließ sich leider auch nicht einschüchtern - das letzte Bild der Reihe zeigt den Ausgang.\r\n'''Quelle:''' \r\n===Troggs===\r\nUnter der Stadt [[Orgrimmar]] haben auch die [[Troggs]] damit begonnen, sich aus den Tiefen unterhalb der lavagefüllten Tunnel an die Oberfläche zu wühlen. Wie es ihrer grundgütigen Art entspricht, hatte die [[Tauren]]älteste [[Magatha Grimmtotem]] Frieden mit diesen Kreaturen schließen wollen, doch die [[Troggs]] stürzten sich auf ihre Diplomaten und töteten sie. Magatha lässt sich eine solche Behandlung des [[Tauren]]volks nicht gefallen und betrachtet die Kreaturen jetzt als eine Gefahr für die gesamte [[Horde]].\r\n===[[Sengende Klinge]]===\r\nDie Kultisten der [[Brennende Klinge|Brennenden Klinge]] sind eine Gefahr, aber es gibt auch noch andere. Die Anhänger der [[Sengende Klinge|Sengenden Klinge]], eine Sekte des [[Schattenrat]]es, zum Beispiel, die sich im [[Flammenschlund]] niedergelassen haben, versuchen insgeheim unschuldige Mitglieder der [[Horde]] auf ihre Seite zu ziehen. Viele Angehörige der [[Brennende Legion|Brennenden Legion]] bedenken ihre Anhänger mit Geschenken. Manche dieser Geschenke wären nach Ansicht der Dunklen Fürstin [[Sylvanas Windläufer]] besser in der Hand von Leuten aufgehoben, die weniger Visionen haben. Die [[Sengende Klinge]] versteckt sich in den Höhlen unterhalb [[Orgrimmar]]s und ist ein Musterbeispiel dafür. Die Fürstin sagt, dass Mitglieder der [[Sengende Klinge|Sengenden Klinge]] in den Besitz zweier sehr mächtiger Zauberbücher gelangt seien und sie möchte sich diese Bücher von ihnen 'borgen'.\r\n==Perösnlichkeiten==\r\n* [[Bazzalan]]\r\n* [[Jergosh der Herbeirufer]]\r\n* [[Maur Grimmtotem]]\r\n* [[Taragaman der Hungerleider]]",},
			["Flammenwandler"] = { content = "Flammenwandler sind unbarmherzige Diener von [[Ragnaros]] und bilden eine feste Gemeinschaft innerhalb der [[Feuerelementare]]. Man findet sie auf [[Azeroth]] vor allem in den [[Schwarzfelstiefen]] oder dem [[Geschmolzener Kern|Geschmolzenen Kern]]. \r\nSie stehen im Ruf, intelligenter als andere Vertreter der feurigen Gebiete der Elementaren Ebene zu sein und übernehmen auf [[Azeroth]] häufig Botschafter- oder Wächter-Aufgaben im Namen des [[Ragnaros|Feuerfürsten]].\r\nFlammenwandler erkennt man an ihrem schlangenförmigen Unterkörper und dem geschuppten humanoiden Oberkörper, der mit großen Stacheln übersäht ist. Ihre Farben variieren von einer häufig vorkommenden feurigen Rot/Schwarz-Kombination bis zu einem selten vorkommenden Blau-Ton, wie z.B. bei [[Shazzrah]].\r\n==Persönlichkeiten==\r\nZu den berühmten Flammenwandlern zählen:\r\n* [[Botschafter Flammenschlag]]\r\n* [[Fürst der Asche]]\r\n* [[Gehennas]]\r\n* [[Lucifron]]\r\n* [[Majordomus Executus]]\r\n* [[Prinz Skaldrenox]]\r\n* [[Shazzrah]]\r\n* [[Sulfuronherold]]",},
			["Fleischbestie"] = { content = "Man sagt, dass durch den Schlaf der Vernunft Monster entstehen, dass Fantasie von Verstand verlassen alptraumhafte Kreaturen hervorbringt. In den meisten Fällen können die Horror der dunkelen Stunden nicht in den Tag folgen; einige jedoch verfolgen uns noch lange nachdem die Schleier des Schlafes verschwunden sind. Die hirnlosen Fleischbestien wurden von [[Medivh]] in diese Welt gebracht, aus unaussprechlichen Orten jenseits dieser Welt beschworen. Einst hat der Magier die Fleischbestien für seine verborgenen Experimente in den Laboren von [[Karazhan]] gebraucht. Nun ist [[Medivh]] verschwunden, aber die geifernden, hungrigen Kreaturen seiner verdrehten Alpträume bleiben, unaufhörlich durch die trüben Schatten [[Karazhan]]s pirschend.\r\n'''Quelle:'''",},
			["Fleischriese"] = { content = "'''Fleischriesen''' sind [[Untote]] Monstrositäten, die durch eine Schleimapparatur atmen und eine riesige Injektionsnadel anstelle einer Hand haben. Es sind aus Fleisch erschaffene Konstrukte der Geißel, die mit Metall-Implantaten ausgestattet wurden und Giftwolken hinterlassen.Eine verbesserte Form sind die [[Fleischtitan]]en.\r\nDie gleiche finstere Magie, mit der die mächtigen Monstrositäten kontrolliert werden, wird im harschen fernen [[Nordend]] noch viel effektiver angewandt. Hier fokussiert der Lichkönig seine bösartigen Kräfte auf die Fleischriesen: albtraumhafte Kreaturen, gegen die Monstrositäten zahm erscheinen. Diener der Geißel erbauen Fleischriesen und Monstrositäten auf die gleiche Weise - sie setzen sie aus Einzelteilen verschiedener Leichen zusammen. Anders als bei den Monstrositäten jedoch werden die “Ersatzteile”, aus denen die Fleischriesen bestehen, von verschiedenen Arten der Furcht erregenden Riesen Nordends verwendet. Die lebendigen Rammböcke sind nicht wirklich intelligent, bauen stattdessen auf schiere Gewalt und den unerbittlichen Willen ihres abscheulichen Meisters. Wer sich den Fleischriesen stellt riskiert nicht nur sein Leben... sondern auch ein Schicksal schlimmer als der Tod. \r\n==Persönlichkeiten==\r\n* [[Grobbulus]]\r\n'''Quellen'''",},
			["Fleischtitan"] = { content = "Fleischtitanen sind riesige, Künstlich erzeugte Wesen, die in [[Naxxramas]] zu finden sind. Ein Stromnetz fließt unter ihrer Haut und macht sie agiler und intelligenter als ihre plumperen Verwandten, die [[Fleischriese]]n.Sie sind sehr stark und ausdauernd und leben nur , um die Wünsche ihres Meisters zu erfüllen.",},
			["Fleischwagen"] = { content = "Eines der seltsamsten und grässlichsten Hilfsmittel der [[Geißel]] ist der gefürchtete '''Fleischwagen'''. Dieses wackelige Gefährt wird benutzt, um kürzlich Gefallene vom Schlachtfeld zu transportieren. Die Toten können jederzeit vom Fleischwagen geholt und zu untoten Kriegern erweckt werden. In der ausgebauten Form kann der Fleischwagen auch mittels eines primitiven [[Katapult]]es verseuchte Kadaver auf feindliche Einheiten schleudern. Er ist ein unschätzbar wertvolles Nachschubfahrzeug für die Geißel und erfüllt die Herzen selbst der resolutesten Verteidiger mit Furcht und Elend. Gebaut werden die Fleischwagen im [[Schlachthaus]].\r\n'''Quelle:''' [[Warcraft III - Reign of Chaos]]",},
			["Flickwerk"] = { content = "Das '''Flickwerk''' ist eine riesige [[Monstrosität]] im Monstrositätenflügel von [[Naxxramas]], die die übrigen Gegner dort um Längen überragt. Er schlägt mit seinen duzend Waffen wild um sich und versucht alles in seiner Nähe dem Erdboden gleichzumachen. \r\n==Taktik==\r\nFlickwerk kann im Kampf nicht viel, aber das was er kann, kann er sehr gut. Den Haupttank trifft er für ungefähr 2000-2200 Schaden. Die Abfangtanks trifft er mit einem Spezialangriff, der sich HASSERFÜLLTER STOSS nennt. Diese Attacke verursacht sehr viel Schaden und wird von ihm in Abständen von 2s ausgeführt. Sie trifft die Abfangtanks für 5000-8000 Schaden. Dieser Schaden hängt besonders stark vom Rüstungswert der Tanks ab. Der HASSERFÜLLTE STOSS trifft die nächsten 3 Ziele in Nahkampfreichweite, weshalb beim Pull selbst nur die 3 Abfangtanks dort stehen dürfen. Alle anderen Nahkampfklassen bleiben vorerst auf Distanz. Sobald Flickwerk den ersten HASSERFÜLLTEN STOSS ausgeführt hat, greifen die Schurken und Offensivkrieger an. Er verfällt bei 5% seiner Trefferpunkte in einen schwachen Tobsuchtsanfall und verursacht mehr Schaden. Nach 7 Min Kampfzeit wird er so wütend, dass er jeden Spieler mit einem Schlag tötet.\r\nEs ist wichtig, dass der Haupttank und die Abfangtanks so schnell wie möglich geheilt werden um den HASSERFÜLLTEN STOSS erneut abfangen zu können. Sind alle 3 Tanks nicht geheilt und haben sehr wenig TP, stirbt ein Tank, was dazu führt, dass Flickwerk die anderen beiden Tanks sehr schnell mit seiner Attacke beharkt und das Hochheilen nur noch sehr schwer bis gar nicht möglich ist. \r\n==Fähigkeiten==\r\n* '''HASSERFÜLLTER STOSS''' - Das Prinzip hinter der Fähigkeit HASSERFÜLLTER STOSS ist relativ simpel. Sie verursacht alle 2 Sekunden 5000-8000 Schaden und trifft den Abfangtank mit den aktuell meisten Gesundheitspunkten. Diese Fähigkeit kann den Haupttank, sofern er die höchste Bedrohung bei Flickwerk hat, nicht treffen.",},
			["Flucht von Burg Durnholde"] = { content = "#REDIRECT [[Höhlen der Zeit: Das alte Hügelland]]", redirect = "Höhlen der Zeit: Das alte Hügelland",},
			["Flughafen"] = { content = "Der im Osten von [[Eisenschmiede]] in den Bergen von [[Dun Morogh]] liegende Flugplatz steht normalen Besuchern noch nicht offen. Gerüchteweise soll es aber einen Verbindungsgang von [[Eisenschmiede]] aus geben, dessen Türen sich dereinst für alle öffnen werden, um dann mittels der neuen Technologie der Flugmaschine andere Kontinente schnell erreichen zu können. Bislang ist er ohne Funktion, auch der sichtbare Flugpunkt hat noch keine Funktionalität, die [[NSC]]s reden nur Unsinn, und - ja - man kann mit Mühe Bergwände so erklimmen, daß man hin kommt.",},
			["Flugmaschine"] = { content = "Ursprünglich von den [[Ingenieure]]n der [[Gnome]] erfunden und von den [[Ingenieure]]n der [[Zwerge]] zum [[Gyrokopter]] weiterentwickelt, ist der Bau einer solchen Flugmaschine heutzutage - unabhängig von ihrer Rasse - für alle erfahrenen [[Ingenieure]] erlernbar.\r\n==Flugmaschine==\r\nZum Bau einer Steuerung für eine Flugmaschine benötigt man Ingenieurskunst (350) und Stufe 70. Für die Benutzung wird die Fähigkeit 'Erfahrener Reiter' oder höher benötigt. Dieses Gefährt kann nur in der [[Scherbenwelt]] verwendet werden.\r\n==Turbogetriebene Flugmaschine==\r\nZum Ausbau einer Flugmaschine in eine Turbogetriebene Flugmaschine ist Ingenieurskunst (375) und Stufe 70 erforderlich. Für die Benutzung wird die Fähigkeit 'Gekonnter Reiter' oder höher benötigt. Dieses Gefährt kann nur in der [[Scherbenwelt]] verwendet werden.\r\n==Flugmaschine als Belagerungwaffe==\r\nDie [[Flugmaschine]]n kommen als Belagerungswaffe in Schlachtfeldern wie dem [[Tausendwintersee]] oder den [[Sande von Ulduran|Sanden von Ulduran]] zum Einsatz. Sie können Gegner bombardieren und sind sehr schnell, gleichzeitig aber sehr anfällig gegen Anti-Luftangriffe.",},
			["Flüchtlingskarawane"] = { content = "Die '''Flüchtlingskarawane''' liegt im Norden der [[Knochenwüste]] in den [[Wäldern von Terokkar]]. Nachdem die Karawane einem Angriff von Kultisten der [[Kabale]] des [[Schattenrat]]s zum Opfer gefallen ist, wurden Späher auf der Suche nach Hilfe nach [[Shattrath]] geschickt. Die Wachen denken, sie sind vorerst sicher, aber sie unterschätzen die [[Kabale]] und sie wissen nicht, wann sie weitergehen werden. Wie man am Zustand der Karawane sehen kann, gibt es dieser Tage viel Leid und Düsterkeit in den Wäldern von Terokkar. Auch [[Kirrik der Erwachte]] ist hier zu finden.",},
			["Flügeldrache"] = { content = "Die intelligenten Flügeldrachen von [[Kalimdor]] konnten es kaum erwarten, sich mit der schamanistischen [[Horde]] zu verbünden. Der Ehrenkodex und die Siege der [[Orcs]] beeindruckten die Flügeldrachen so sehr, dass sie den [[Orcs]] gestatteten, auf ihnen in den Kampf gegen all jene zu reiten, die die Ruhe von [[Kalimdor]] und seiner Bewohner störten. [[Schamanen]] und Flügeldrachen haben deshalb unter Ausnutzung ihrer Verbundenheit mit den Kreaturen der Wildnis eine nützliche Allianz geschmiedet. Die tödlichen Flügeldrachen schauen auf dieselben Vorfahren wie [[Drachen]] und [[Greife]] zurück und setzen ihre kräftigen Klauen und messerscharfen Fangzähne gegen Angreifer aus der Luft wie auch gegen Bodentruppen ein. So greifen sie Einheiten an Land und in der Luft gleichermaßen wirksam an. Flügeldrachen haben einen starken Beschützerinstinkt, was ihre Eier angeht, und schätzen keine Eindringlinge. Flügeldrachenpopulationen sind im [[Steinkrallengebirge]] und in [[Tausend Nadeln]] zu finden.\r\n==Flügeldrachen als Reittiere==\r\nMitglieder [[Horde]] nutzen gepanzerte Flügeldrachen auch als Reittiere. Weniger bekannt indessen ist, dass das Gift eines Flügeldrachen in manchen Kreisen höher geschätzt wird als die Bestie selbst. Doch die ursprünglichen Flügeldrachenreiter hatten oft Giftspeere bei sich, die mit dem tödlichen Gift der riesigen Dschungelschlangen von [[Schlingendorntal]] getränkt wurden. Treffen diese Speere Feinde, so werden die Verwundeten geschwächt und von dem Gift, das durch ihre Körper zirkuliert, bei lebendigem Leibe aufgefressen. Allianz-Spione behaupten, dass die [[Orcs]] Gift der Prachtschwingen beim [[Mirkfallonsee]] im [[Steinkrallengebirge]] sammeln. Auch die am Steilhang in [[Tausend Nadeln]] lebenden Steilhangflügeldrachen haben ein starkes Gift. Stark und kostbar.\r\n===Flügeldrachen auf der Scherbenwelt===\r\nVor weniger als 20 Jahren wurde [[Draenor]] von der brutalen Energie mehrerer Dimensionsportale auseinander gerissen, die das innerste des Planeten in Stücke sprengten. Dieses katastrophale Ereignis hinterließ [[Draenor]] als eine zerstörte Welt, die von ihren Überlebenden \"Scherbenwelt\" getauft wurde. Bis zum heutigen Tag sind Teile der [[Scherbenwelt]] zu Fuß oder Schiff unerreichbar, nur als unheimliche, den Horizont entlang gleitende Schemen wahrnehmbar; eine stille Erinnerung an das schreckliche Schicksal, dem [[Draenor]] zum Opfer fiel. Allerdings haben es die Einwohner der [[Scherbenwelt]] geschafft, einige der einheimischen Arten als fliegende Reittiere auszubilden, so dass mutige Abenteurer selbst bis in die entlegensten und gefährlichsten Regionen dieser wilden und ungezähmten Welt vordringen können.\r\nAuf der [[Scherbenwelt]] befindet sich eine Flügeldrachenzucht und Ausbildungsstelle für [[Windreiter]] im [[Dorf Schattenmond]] im [[Schattenmondtal]]. Dort kann man, sobald man Stufe 70 ist, diese stolzen [[Flügeldrachen]] auch käuflich erwerben.\r\n===Arten===\r\n* Gelbbrauner Windreiter\r\n* Blauer Windreiter\r\n* Grüner Windreiter\r\n* Schneller roter Windreiter\r\n* Schneller grüner Windreiter\r\n* Schneller gelber Windreiter\r\n* Schneller lila Windreiter",},
			["Flügeldrachen"] = { content = "#REDIRECT [[Flügeldrache]]", redirect = "Flügeldrache",},
			["Flüsterschlucht"] = { content = "Die '''Flüsterschlucht''' war eine Grabungsstätte der Zwerge der [[Forscherliga]] im Westen des [[Der heulende Fjord|Heulenden Fjords]]. Doch die Zwerge hier unter der Leitung von [[Squeeg Götzenjäger]] sind dem Wahnsinn verfallen und wenden sich nun gegen alle Eindringlinge. Sie griffen sogar eine Karawane der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] an, als die [[Verlassene]]n durch diese Gegend zogen, und attackieren außerdem ununterbrochen deren Jagdtrupps. Die Apotheker vermuten nun, dass was auch immer die Zwerge aus den Fässchen, die überall in der Schlucht verstreut herumliegen, trinken, zu ihrem Wahnsinn beiträgt.",},
			["Folgen des Zweiten Krieges"] = { content = "Nach dem verheerenden [[Der Zweite Krieg|Zweiten Krieg]] gegen die Orc-Horde hatten Schock und Demoralisierung die Allianz von Lordaeron fest im Griff. Die blutrünstigen Orcs hatten sich unter ihrem mächtigen Kriegshäuptling Orgrim Doomhammer nicht nur eine breite Schneise der Verwüstung hinterlassend durch die Zwergenländer von Khaz Modan gekämpft, sondern obendrein viele der wichtigsten Provinzen von Lordaeron völlig zerstört. Es gelang den grausam wütenden Orcs sogar, das entlegene Elfenkönigreich [[Quel'Thalas]] zu verheeren, bevor ihr Amoklauf endlich aufgehalten wurde. Die Armeen der Allianz unter Führung von Sire Anduin Lothar, Uther Lightbringer und Admiral Daelin Proudmoore drängten die Orcs nach Süden in das verwüstete Land Azeroth – das erste Königreich, das dem gnadenlosen Ansturm der Orcs zum Opfer fiel.\r\nDen Streitkräften der Allianz gelang es unter Sire Lothar, Doomhammers Clans aus [[Lordaeron]] zu vertreiben und in das von den Orcs beherrschte Land Azeroth zurückzudrängen. Lothars Streitkräfte umzingelten Blackrock Spire, die vulkanische Zitadelle der Orcs, und belagerten die Verteidiger. Als letzte Verzweiflungstat befahlen Doomhammer und seine Offiziere einen tollkühnen Ausbruch aus der Zitadelle. Mitten auf der Brennenden Steppe entflammte dann die Schlacht, als sie auf Lothars Paladine trafen. Doomhammer und Lothar lieferten sich einen titanischen Zweikampf, nach dem die beiden mächtigen Krieger erschöpft und verwundet darniedersanken. Ganz knapp gelang es Doomhammer, Lothar zu besiegen, doch der Tod des großen Helden hatte nicht die Wirkung, die sich der Kriegshäuptling erhofft hatte. [[Turalyon]], Lothars engster Vertrauter unter den Offizieren, hob Lothars blutbefleckten Schild auf und scharte seine von Trauer geschüttelten Brüder zu einem erbitterten Gegenangriff um sich. Unter den zerfetzten Standarten von Lordaeron und Azeroth schlugen Turalyons Truppen das Gros von Doomhammers verbliebener Streitmacht in einer ruhmreichen, aber schrecklichen Schlacht. Den verwundeten, versprengten Überlebenden der Orcs blieb nichts anderes übrig, als zur letzten Bastion der Orc-Macht zu fliehen – dem Dunklen Portal.\r\n[[Turalyon]] und seine Krieger jagten die verbliebenen Orcs durch die verpesteten [[Sümpfe des Elends]] in das verwüstete Aschenland, wo das Dunkle Portal stand. Und dort, am Fuße des kolossalen Portals, trugen die dezimierte Horde und die unerbittliche Allianz die letzte und blutigste Schlacht des Zweiten Krieges aus. Die zahlenmäßig unterlegenen Orcs, vom Fluch ihres Kampfrauschs zur Raserei angestachelt, fielen zwangsläufig der Wut der Allianz zum Opfer. Doomhammer wurde gefangen genommen und nach Lordaeron gebracht, derweil man seine versprengten Clans zusammentrieb und nach Norden jagte – zurück nach Lordaeron.",},
			["Foliant der Kabale"] = { content = "Der '''Foliant der Kabale''' wurde von der ersten Gruppe [[Hexenmeister]] geschrieben, die ohne Unterstützung einen [[Teufelsjäger]] beschworen und gilt seit geraumer Zeit als verschollen. Es ist einer der interessantesten Texte, der letzten Jahre, dessen Kopie angehende Hexenmeister für die Beschwörung eines Teufelsjägers benötigen. Einst befand sich der Foliant innerhalb der Mauern von [[Lordaeron]], aber er wurde beschädigt und fast die Hälfte der Seiten herausgerissen. Man munkelt, dass der Foliant irgendwie den [[Zentauren]] von [[Tausend Nadeln]] in die Hände gefallen sein soll. Der Rest ging an der Küste westlich von [[Süderstade]] verloren, als er per Schiff zum [[Hafen von Menethil]] hätte transportiert werden sollen. Er kam nie an. Nur eine Kopie wurde jemals angefertigt und selbst die wurde einst beschädigt.",},
			["Foliant der Unerschütterlichen"] = { content = "Der '''Foliant der Unerschütterlichen''' ist eine Art Geschichtsbuch, das in einer Geheimschrift der [[Allianz]] geschrieben wurde. [[Althen der Historiker]] im [[Rückenbrecherposten]] auf der [[Höllenfeuerhalbinsel]] hat [[Die Unerschütterlichen]] eine Zeit lang studiert. Vielleicht kann er die Geheimschrift der Allianz entziffern und das Buch lesen. Dieser Foliant sagt, dass das [[Rüstlager der Allianz]] vor langer Zeit von den Orcs und den [[Todesritter]]n zerstört wurde. Die Unerschütterlichen wurden dort als rachedurstige Geister in einer ewigen Schlacht gegen die Klans der [[Höllenorc]]s gefangen. Sie denken nur an Rache.",},
			["Forscherliga"] = { content = "Der Begriff '''Forscherliga''' bezeichnet zum einen den Realm, auf dem wir spielen und zum andern eine [[Fraktion]].\r\nDie [[Fraktion]] '''Forscherliga''' ist eine Gruppe von [[Zwerge]]n, die sich auf die Suche nach Spuren der Vergangenheit gemacht hat und auf ganz [[Azeroth]] verschüttete Städte untersucht. Siehe: [[Forschergilde]].",},
			["Forschungsbericht Dunkelküste"] = { content = "=== Forschungsergebnisse bezügl. Forschungsreise Auberdine===\r\n* von [[Kizzi]]\r\n* z.H. [[Institut für Pfuschkunde]], [[Eisenschmiede]]. \r\n* Betreff: [[Nachtelfen]]technologie. \r\nIm Zuge meiner Forschungsreise zu den ominösen Nachtelfen, stiess ich auf Spuren einer längst vergessenen Tatsache: \r\nVor hunderten von Jahren bildete dieses Volk einen höchst begabten Technologen (\"Der Irre Ishnuel\") aus! Beweise dafür sind überall vorhanden, seien es die Nachkommen ehmaliger oganischer Roboter, die man in Insiderkreisen als \"Mini-Treants\" bezeichnet, oder misteriöse organische Relokationsvorrichtungen auch Portale genannt ([[Ru'theran]] Anmk. d. Autors). Mich persönlich interessiert besonders ein Forschungsgebiet: \r\n'''Nachtelfen bauten Bomben!''' \r\nIn etwa zeitgleich mit dem Beginn der Gnom'schen Technologierechnung entwickelte besagter begabter Nachtelfeningenieur die erste organische Bombe, die natürlich größtenteils aus Holz bestand. Zeitzünder waren Ihm noch unbekannt, er verwendete Lunten aus Lianen, oder rief druidisches Mondfeuer zur Hilfe. Interessanterweise entwickelte sich aus eben diesen Spregsätzen der Begiff \"Splitterbombe\", das berstende Holz fragmentierte bei der Explosion in tausende kleine Splitter, die extremst beschleunigt Feuer fingen bevor sie Ihr Ziel in einer brennenden Wolke auslöschten. Sollte man das Holz zuvor in flüssigen Sprengstoffen gebadet haben, vervielfältigte sich dieses Phänomen. \r\nDie Technologie der metallischen Splitterbomben ist natürlich nicht mehr unbekannt, jedoch lässt dieser Ansatz einiges an Raum für Experimente. Ich fand übrigens heraus, dass das Sprichwort \"Klopf auf Holz!\" in dieser Zeit gesetzlich verboten wurde. Durch die Verwendung hohler Baumstämme, die mit Knallgras und Sprengstoffen gefüllt waren, waren die Sprengsätze bereits optimal getarnt, und konnten nur durch vorsichtiges Öffnen erkannt werden. Zu hefiges Klopfen führte meist zu einer Explosion und einem ziemlich unglücklichen Elf. \r\nSkurril wird dieses Thema ab seinem Versuch Zeitzünder zu entwickeln. \r\nZu diesem Stadium verlor sich der Wissenschaftel bereits in seiner eigenen Welt aus gezüchteten Bomben-Bäumen. Wie bereits bekannt ist, verwenden Nachtelfen zur Zeitzählung keine Uhrwerke sondern Blumenuhren, daraus resultierte die logische Idee, diese zu einem Zündungsmechanismus umzufunktionieren. Diese Entwicklung führte zum Ende der Nachtelfschen Sprengsatzforschung, da sämtliche nachfolgende Techniker auf meist sehr humoristische Weise Ihr Leben liessen, wie folgende überlieferte Zitate vermitteln: \r\n\"RENN! Die Lilie hat sich soeben geöffnet!\" \r\n\"Was soll ich pflücken, das blaue Veilchen oder die rote Rose?\" \r\nWeil man solche Sätze normalerweise nur periphär mit Gefahr und eher mit vollkommener Demens in Verbindung bringt, insbesondere wenn sie hektisch und/oder stark schwitzend gebrüllt werden, forderte diese Ära der Bombenforschung auch dutzende Ziviltote. Was offensichtlich der Hauptgrund ist, warum dieses Thema oft totgeschwiegen und/oder verleugnet wird. \r\nDer Ingenieur wurde seit seinem Aufbruch zum Berg Hyal nciht mehr gesehen, er war dem Wahnsinn verfallen und redete davon den Weltenbaum auszuhöhlen. \r\nIch bitte nun das Institut mir den Import organischer Explosionswaren zu gestatten um diesen interessanten Ansatz weiter verfolgen zu können. \r\nVielleicht gelang es dem Wahnsinnigen tatsächlich Bomben zu \"züchten\", ähnlich seinen Robotern. (Verm. Lauerwurz und ähnliches.) Sollte ein Vortrag über dieses Thema (natürlich mit Vorführung, Buffett und Alkohol) gewünscht werden, bin ich nach meiner Rückkehr dazu bereit. Bis dahin versuche ich den ein oder anderen organischen Roboter zu finden/fangen/sezieren, und werde euch darüber natürlich am Laufenden halten. \r\nHochachtungsvoll, Kizzi.\r\n===Forschungsergebnisse bezügl. Forschungsreise Auberdine===\r\n* z.H. [[Institut für Pfuschkunde]], Eisenschmiede. \r\n* '''Betreff: Nachtrag. DRINGEND!''' \r\nDank anonymer Hinweise ist es mir heute Nachmittag gelungen einige Dornendrescher und Lauerwurzeln auf den benachbarten Schwanzelf-Inseln zu finden. \r\nTrotz längerer Untersuchungen konnte ich keine, ich wiederhole keine technologischen Anzeichen erkennen. Merkwürdig, da im Bezug mit dem \"Irren Ishnuel\" diese immer genannt werden. Des weiteren wirkt diese Spezies auf mich relativ jung, wodurch die naheliegendste Lösung höchstwahrscheinlich ausgeschlossen ist: dass der besagte Wissenschaftler ein Aufscneider war. \r\nIch versuche nunmehr mehr über seine Person herauszufinden, und stoße bis auf den schon bekannten Klatsch nur auf einer Barriere des Schweigens. \r\nUnd das, obwohl ich bereits sehr \"diplomatisch\" meinen Schaubenzieher schwinge. \r\nIch fürchte an dieser ganzen Sache steckt mehr dran als ich zu erahnen vermag. \r\nWer baute Bomben in Baumform, die, ich wage es fast nicht zu schreiben, OFFENSICHTLICH dazu gedacht waren Baumkuschelnde Elfen zu erschrecken? \r\nIch vermute dass derartige Sprengsätze in jüngster Vergangenheit wieder aufgetaucht sind, da ich, als Nichtelf überhaupt Wind von der Sache bekam. \r\nIch versuche guten Mutes weiter zu Forschen, doch ich habe das Gefühl, die Schatten beobachten mich. \r\nHochachtungsvoll, Kizzi.",},
			["Fort Wildervar"] = { content = "'''Fort Wildervar''' ist ein Stützpunkt der [[Allianz]] im [[Der heulende Fjord|Heulenden Fjord]]. Es befindet sich weit im Nordosten, jenseits von [[Skorn]], in dem schneebedeckten Gebiet, das an die [[Grizzlyhügel]] grenzt. Hier werden alle Vorbereitungen getroffen, damit das Expeditionskorps der Allianz gen Norden ziehen kann.\r\n==Personen==\r\n* [[Gil Grisert]]",},
			["Fraktion"] = { content = "#REDIRECT [[:Kategorie:Fraktionen]]", redirect = ":Kategorie:Fraktionen",},
			["Fraktionen"] = { content = "'''Fraktionen''' sind [[:Kategorie:Organisation|Organisationen]], bei denen man Ruf sammeln kann. Es gibt zwei spielbare Fraktionen in [[World of Warcraft]]: [[Allianz]] und [[Horde]].\r\n==Beschreibung==\r\nAzeroth ist eine rauhe und kriegsgebeutelte Welt. Alleingänge können tödlich sein. Um zu überleben und zu gedeihen, sammeln sich Mitglieder aller Völker unter dem Banner kultureller und ideologischer Gemeinsamkeiten. Jede dieser Fraktionen besitzt eine einzigartige Philosophie und selbst innerhalb der Fraktionen können Meinungsverschiedenheiten herrschen, selbst gewalttätige. Und doch, die Zugehörigkeit zu einer Fraktion bleibt nie unbemerkt. Die Helden, die gewillt sind, eine Seite zu wählen, können attraktive Belohnungen erwarten. \r\n===Classic===\r\n* Siehe ''[[:Kategorie:Fraktionen]]''\r\n===The Burning Crusade===\r\n* Siehe ''[[:Kategorie:The Burning Crusade Fraktion]]'':\r\n===Wrath of the Lichking===\r\n* Siehe ''[[:Kategorie:Wrath of the Lichking Fraktion]]'': \r\n====Die Fraktionsverträge====\r\n* Vertrag: [[Stimme von Azeroth]]\r\n* Vertrag: [[Vulpera]]\r\n* Vertrag: [[Zandalariimperium]]\r\n* Vertrag: [[Nazmirexpedition]]\r\n* Vertrag: [[Tortollanische Sucher]]\r\n* Vertrag: [[Haus Prachtmeer]]\r\n* Vertrag: [[Haus Sturmsang]]\r\n* Vertrag: [[Haus Kronsteig]]\r\nOb jeweils nur ein Vertrag aktiv sein kann oder mehrere zeitgleich, ist bislang noch nicht bekannt.\r\n==Nichtspielbare parteiische Fraktionen==",},
			["Franclorn Schmiedevater"] = { content = "Der zwergische Meistersteinmetz '''Franclorn Schmiedevater''' ist für die Steinwerkmethode der Architektur der [[Zwerge]] verantwortlich. Jeder hat zweifellos während der Abenteuer in der vom Krieg zerrissenen Welt eines seiner Werke durchquert oder hat auf einem gestanden. \r\n==Geschichte==\r\nFranclorn hatte keine Wahl, das dachte er jedenfalls. Er würde die Zerstörung von [[Thaurissan]] ertragen und an der Seite seines Königs und seines Volkes stehen. Unter der Leitung von Ragnaros ließ König Dagran Thaurissan das [[Herz des Berges]] herausreißen und errichtete die [[Schwarzfelsspitze]]. Die Zwerge arbeiteten unermüdlich, um eine Zwergenstadt zu bauen, die mächtiger als jede Stadt ider Festung zuvor sein sollte ... oder danach. Franclorn mußte mit ansehen wie Ragnaros' Verderbnis die Herzen und Gedanken der Dunkeleisennation vergiftete. Das einst ehrwürdige Volk, dem Wahnsinn verfallen ... dem Bösen. Als der Bau der Spitze abgeschlossen war, schwand sein Wunsch, bei seinem Volk zu leben. Er verschied als Held der neuen Dunkeleisennation. Ein Grabmal wurde ihm zu Ehren in der Mitte des [[Schwarzfels]] errichtet - am Eingang zu der Stadt, die er geplant und erbaut hatte.\r\nSeine Waffe war ein gewaltiger Hammer namens \"[[Eisenhölle]]\", der nun vom neuen Chefarchitekten des [[Schwarzfels]], [[Fineous Dunkelader]], bewacht wird. Fineous jedoch ist ein Mann mit fragwürdigen Motiven und wenig Talent und Franclorns geist will, dass er aufgehalten wird. Fineous ist so unfähig, dass er die wahre Macht von Eisenhölle nicht begreift; sollte ihm jedoch jemand nachfolgen, der fähig ist, das ganze Potential des Hammers zu nutzen, könnten die Verheerungen, die dessen Schöpfung über die Welt bringen würden, katastrophal sein.\r\n==Schlüssel zur Schattenschmiede==\r\nMit Franclorn Schmiedevater sollte man auch sprechen, wenn man daran interessiert ist, einen Schlüssel für die Hauptstadt zu erhalten, den [[Schlüssel zur Schattenschmiede]] zu den [[Schwarzfelstiefen]]. Ihm zu Ehren wurde dort am Schrein von Thaurissan ein Denkmal aufgestellt. Seinen Geist selbst findet man im [[Schwarzfels]] auf einem Altar in der Mitte des Abstieges. Jedoch muss man selbst ein Geist sein, um Franclorn zu sehen und mit ihm sprechen zu können.",},
			["Freiwindposten"] = { content = "Der Freiwindposten ist ein Stützpunkt der [[Horde]] ganz im Stil der [[Tauren]] und liegt im Südosten von [[Tausend Nadeln]]. Der Stützpunkt unterhält eine eigene [[Flügeldrachen]]-Zucht und so wurde [[Elu]] aufgetragen, weitere Bewerber für die Meister[[windreiter]] zu rekrutieren. Sie können gar nicht genug [[Flügeldrachen]] auszubilden, um der Nachfrage gerecht zu werden. \r\n==Personen==\r\n* '''Elu''' - Elu hofft, selbst eines Tages ein [[Windreiter]] zu werden. \r\n* '''Hagar Blitzhuf''' - Hagar Blitzhuf möchte das fremdartige Ei der [[Windnatter]]n untersuchen und anschließend [[Motega Feuermähne]] von den Entdeckungen berichten. \r\n* '''Klippenbehüter Langhorn''' - Klippenbehüter Langhorn sorgt hier für die Sicherheit und kümmert sich um die Befriedung der [[Zentauren der Galak]]. Durch seine Grimmtotemspionage konnten die geheimen Notizen im [[Düsterwolkengipfel]] geborgen und [[Arnak Grimmtotem]] erschlagen werden. Sein Bruder [[Nataka]] ist beim [[Geistwandlerposten]] drüben in [[Desolace]] stationiert. Ein Jahr ist vergangen, seit er ihm das letzte Mal schrieb, und es gab seitdem ungewöhnliche [[Zentauren]]aktivitäten, über die er informiert werden sollte.\r\n* '''Magistrix Elosai''' - Magistrix Elosai forscht an der natürlichen Heilung der Abhängigkeit der [[Blutelfen]] und erzählt, dass ihre Brüder sie nicht mehr haben wollen. Jede Abschrift ihrer Abhandlung über die natürliche Heilung wurde verbrannt. Sie kann Ihre Forschungen hier sicher fortsetzen, aber sie hat keine Reagenzien. Deswegen sucht sie nach einer anderen Lösung und möchte die reinigende Erde von den [[Erdelementare|Donnernden Felskloppern]] ausprobieren, die dann von [[Wizlo Lagerputzer]] beim [[Weißgipfelposten]] weiterverarbeitet wird.\r\n* '''Rau Klippenläufer''' - Rau Klippenläufer ist auf der Suche nach einem alten [[Zentauren]]relikt: Dem gespaltenen Huf.",},
			["Friedhof"] = { content = "Der '''Friedhof''' ist ein Gebäude, welches sich die [[Geißel]] zunutze macht. Die Diener der Untoten studieren unermüdlich die Geheimwissenschaften, um Waffen und Rüstungen mit unheiliger Macht zu versehen. Genau wie die [[Nekropole]] kann auch der Friedhof Holz für den Bau von Waffen und Rüstungen verarbeiten. Dieses Gebäude holt außerdem frische Tote aus den Tiefen der Erde und exhumiert sie, damit die bösen [[Totenbeschwörer]] sie benutzen können.\r\n'''Quelle:''' [[Warcraft III - Reign of Chaos]]",},
			["Friedhof von Rabenflucht"] = { content = "Der Friedhof von Rabenflucht und die stillen Gärten im [[Dämmerwald]] sind voll von Skeletten. Auch die Lage in Rabenflucht selbst scheint sehr bedenklich. Irgendetwas stimmt dort nicht. Zwei Nächte in Folge hat man jetzt schon gesehen, wie sich die Schatten bewegten, und in der Nacht vorher hat man Licht in einem der Fenster gesehen.\r\n==Personen==\r\n* [[Bibbers]]\r\n* [[Calvinius]]\r\n* [[Einbalsamierer]]\r\n* [[Morbent Teufel]]\r\n* [[Morgan Ladimore]]",},
			["Front der Legion"] = { content = "Direkt im Osten der [[Höllenfeuerhalbinsel]] liegt die Front der Legion. Entlang der Front befinden sich die infernalen Portale und Tore, mit deren Hilfe die [[Brennende Legion]] Verstärkung auf die [[Höllenfeuerhalbinsel]] und in die ganze [[Scherbenwelt]] bringt. [[Allianz]] und [[Horde]] haben die Lager der Legion überwacht und haben guten Grund zur Annahme, dass die [[Dämonen]] in diesen so genannten \"[[Konstruktionslager]]n\" ihre [[Teufelshäscher]] herstellen. \r\n===Abyssische Untiefe===\r\nDie Abyssische Untiefe ist die Hauptproduktionsstätte der Legion hinter den [[Konstruktionslager]]n im Norden. \r\n===Invasionspunkt: Vernichter===\r\nDer Invasionspunkt: Vernichter liegt nördlich von [[Thrallmar]]. Dort befindet sich ein Warpportal, mit dessen Hilfe die Legion Verstärkung herbeiholt. Den Aktivierungsschlüssel trägt der Kommandant des Punkts, [[Kriegshetzer Arix'Amal]], bei sich.\r\n===Konstruktionslager: Mageddon===\r\nDas Konstruktionslager: Mageddon ist noch nicht fertig ist. Die [[Gan'arg]]sklaven der Legion arbeiten dort rund um die Uhr, um die Einrichtung zum Laufen zu bringen. Ihr Meister dort ist die [[Schmiedebestie Sägeklinge]].\r\n===Konstruktionslager: Zorn===\r\nDas Konstruktionslager: Zorn liegt direkt im Nordosten von [[Thrallmar]]. Die [[Dämonen]] haben eine Reihe von Teufelskanonen am Grat entlang aufgestellt und direkt auf den Außenposten der [[Horde]] in [[Thrallmar]] gerichtet. \r\n===Tor Murketh und Shaadraz===\r\nWestlich des [[Dunkles Portal|Dunklen Portals]] befinden sich zwei riesige Transporter: Tor Murketh und Tor Shaadraz. Wenn man den [[Pfad des Ruhmes]] nach Osten hinaufschaut, kann man sie an beiden Seiten der Straße erkennen. Sie sind die beiden Haupttransporter, mit denen die [[Brennende Legion]] ihre Verstärkung herbeiholt.",},
			["Frosch"] = { content = "===Achtung: Krötenwanderung===\r\n* '''Baumfrosch / Waldfrosch''' - Auf [[Dunkelmonds Jahrmarkt]] verkauft euch der kleine Flik für je 1 Gold einen Baumfrosch oder einen Waldfrosch.\r\n* '''Jubling''' - Ebenfalls auf [[Dunkelmonds Jahrmarkt]] könnt ihr einen Jubling bekommen. Besorgt Euch ein paar Dunkeleisenbier aus den [[Schwarzfelstiefen]] und besucht den [[Dunkelmonds Jahrmarkt]]. Dort findet Ihr ein Mädchen welches seinen Jubling vermisst. Stellt das Bier auf den Boden um ihn anzulocken und gebt ein weiteres Bier danach an das Mädchen. Danach erhaltet Ihr zum Dank ein Jublingei.\r\n* '''Lebensechte mechanische Kröte''' - Wem lebendige Frösche und Kröten zu glitschig sind der haut einfach den nächstbesten [[Ingenieur]] (Fertigkeit 265) an er möge einem eine Lebensechte Kröte bauen. Die benötigten Pläne findet ihr bei unterschiedlichen Bossen in Azeroth. \r\n* '''Mojo''' - Den seltenen Frosch Mojo erhaltet Ihr nur in [[Zul'Aman]]. Sammelt die Hexerstecken der [[Amani]] und befreit einige Urwaldfrösche. Mit etwas Glück springt Euch dabei ein Mojo in den Rucksack.",},
			["Frostgram"] = { content = "'''Frostgram''' ist die [[Runenklinge]] des [[Lichkönig]]s.\r\nIn den kargen Eiswüsten [[Nordend]]s traf [[Arthas]] auf [[Muradin Bronzebart]] und eine Expedition seiner [[Forscherliga]]. Muradin war aufgebrochen, um die magische Runenklinge Frostgram, eine durch [[Ner'zhul]] geschmiedete und verfluchte Waffe, zu finden, die sich in geheimen Gewölben unterhalb des Eises verbarg. Von der Macht des Schwertes überzeugt, die in der Lage wäre, [[Mal'Ganis]] zu vernichten, machte [[Arthas]] sich gemeinsam mit [[Muradin Bronzebart|Muradin]] auf die Suche. Er ließ sich weder von den Wächtern der Runenklinge, noch von der Inschrift im Sockel des Schwertes warnen, und war sogar bereit, das Leben seines Freundes zu opfern.\r\nDer junge Prinz unterlag den Einflüssen der Klinge: er irrte Tag um Tag in den erstarrten Stürmen von [[Nordend]] umher, um schließlich [[Eiskrone]] zu erreichen und [[Ner'zhul]] seine Seele anzubieten. Die vampirische Runenklinge verlieh ihm ungeahnte Macht, aber [[Arthas]] verlor seine Seele und wurde dem Willen des [[Lichkönig]]s unterworfen.\r\nFrostgram scheint wie alle Runenwaffen mit mächtigen Zaubern belegt worden sein. Die Klinge gab [[Arthas]] ungeahnte Käfte, die Toten zu beschwören, die Seelen seiner Feinde an sich zu ziehen, um seine Wunden zu heilen und zusätzlich noch das Arsenal der Zauber der [[Schamanen]] und [[Hexenmeister]], die [[Ner'zhul]] zu Lebzeiten in die Waffe wob. Wunden,die Frostgram schlug, heilten entweder sehr langsam oder oft auch gar nicht. Der Geist des Lichkönigs lebt in dieser Waffe weiter ebenso wie in der [[Krone des Lichkönigs]]. Solange beide Artefakte unbeschädigt bleiben, lebt der [[Lichkönig]] weiter auch, wenn sein Körper vernichtet wird.",},
			["Frosthagelsplitter"] = { content = "Im Süden von [[Winterquell]], findet man eine Schlucht und [[Riesen]], die komplett aus Eis bestehen. Die [[Riesen]] tragen die Frosthagelsplitter manchmal bei sich, aber man kann sie auch selbst in der Schlucht sammeln. Diese Splitter haben mächtige reflektierende Eigenschaften.",},
			["Frostklingengipfel"] = { content = "Der '''Frostklingengipfel''' befindet sich weit im Nordosten des [[Der heulende Fjord|Heulenden Fjords]]. Hier liegt auch der Frostklingenschrein zu dem vom westlichen Fuß des Berges aus ein einziger Pfad führt.",},
			["Frostmähnen"] = { content = "#REDIRECT [[Trolle der Frostmähnen]]", redirect = "Trolle der Frostmähnen",},
			["Frostriese"] = { content = "'''Frostriesen''' sind eine Unterart der [[Bergriesen]], die sich auf das Leben in kalten und schneebedeckten Regionen spezialisiert hat. Die bekanntesten Vertreter dieser Rasse sind die [[Frosthagelriesen]] unter Führung von [[Kashoch der Häscher|Kashoch dem Häscher]] in [[Winterquell]].",},
			["Frostsäbler"] = { content = "Im nördlichen [[Winterquell]] sammeln sich große Katzen rund um den Frostsäblerfelsen. Die Anführerin dieser Katzen ist unter dem Namen Shy-Rotam bekannt. Vor rund 4000 Jahren rettete [[Tyrande Wisperwind]] die Frostsäblerkönigin aus den Händen tobender [[Riesen]]. Seither sind die Frostsäbler Verbündete der [[Nachtelfen]]. \r\nIn [[Winterquell]] ist es für die [[Allianz]] möglich einen Winterquellfrostsäbler als Reittier vom Wintersäblerausbilder Rivern Frostwind zu kaufen. Bevor das möglich ist muss bei Rivern Frostwind mithilfe der wiederholbaren Quest \"Frostsäblerverpflegung\" Ruf aufgebaut werden. \r\n==Reittiere==\r\n* '''Winterquellfrostsäbler''' - Erhältlich für: [[Allianz]]. Benötigt: Stufe 60, Unerfahrener Reiter (75), Wintersäblerausbilder – Ehrfürchtig. Kosten: 90g.\r\n==Besondere Tiere==\r\n* '''Shy-Rotam''' - Shy-Rotam ist die Königin der Frostsäbler in [[Winterquell]]. Wenn man hochheiliges Fleisch von den Frostsäblern am Stein von Shy-Rotam platziert, ruft sie das herbei. \r\n* '''Sian-Rotam'''",},
			["Frostsäblerfelsen"] = { content = "Im nördlichen [[Winterquell]] sammeln sich große Katzen rund um einen großen Orientierungspunkt, dem Frostsäblerfelsen. Die Anführerin dieser Katzen ist unter dem Namen [[Shy-Rotam]] bekannt und wenn man hochheiliges Fleisch von den [[Frostsäbler]]n am Stein von [[Shy-Rotam]] platziert, ruft sie das herbei. Vor rund 4000 Jahren rettete [[Tyrande Wisperwind]] die Frostsäblerkönigin aus den Händen tobender [[Riesen]]. Seither sind die Frostsäbler Verbündete der [[Nachtelfen]]. Doch die [[Riesen]], die einst eine Gefahr für die Frostsäbler waren, gibt es noch immer, und das nicht allzu weit von hier entfernt. Man nennt sie [[Frosthagelriesen]] und sie haben das große Tal südlich von hier für sich beansprucht. Die Anwesenheit von [[Rivern Frostwind]] bleibt den meisten verborgen. Er hat beobachtete, wie die [[Furbolgs der Winterfelle]] zahllose Kreaturen erschlagen haben, die das Pech hatten, einfach zur falschen Zeit am falschen Ort zu sein und ist ein Verbündeter der [[Frostsäbler]]. \r\n==Persönlichkeiten==\r\n* [[Rivern Frostwind]]\r\n* [[Shy-Rotam]]",},
			["Frostvrykul"] = { content = "Die Frostvrykul sind das Pendant des [[Todesritter]]s unter den [[Vrykul]]. Sie dienen dem [[Lichkönig]], dem sie ihre Verwandlung verdanken und haben einen großen Teil ihrer alten Intelligenz und freiem willen behalten.",},
			["Frostwolf"] = { content = "Frostwölfe sind das bevorzugte Reittier der [[Orcs des Frostwolfklans]]. Mutigen und aufopfernden Streitern der [[Horde]], welche sich im [[Alteractal]] an die Seite des [[Frostwolfklan]]s stellen wird dieses Reittier gegen eine Anzahl von 50 Ehrenmarken des [[Alteractal]]s übergeben. Sein schneeweisses Fell und seine schönen Augen machen dieses epische Reittier zu etwas Besonderem.\r\nVor langer Zeit, noch vor dem Ersten Krieg, sandte der Hexenmeister Gul'dan einen Klan der Orcs, Frostwolfklan genannt, in ein Tal, tief im Herzen des Alteracgebirges. Diese Orcs zähmten viele der einheimischen Kreaturen, darunter auch die großen Frostwolf-Worgs. Diese Wölfe erwiesen sich bald als nicht nur sehr schnell sondern auch als tödlich, halfen sie doch den Orcs, zahllose Schlachten für sich zu entscheiden. Nachdem es Thrall gelungen war, alle Klans zu versöhnen, haben die Orcs des Frostwolfklans eingewilligt, ihre Reittiere mit allen Mitgliedern der Horde als Zeichen der Solidarität zu teilen. Die Worgs selbst sind dieser Entscheidung gefolgt, und viele Hordenreiter zählen inzwischen auf die Worgs als verlässliche Begleiter.\r\n==Geschichte==\r\nVor langer Zeit, noch vor dem Ersten Krieg, sandte der Hexenmeister Gul'dan einen Klan der Orcs, Frostwolfklan genannt, in ein Tal, tief im Herzen des Alteracgebirges. Diese Orcs zähmten viele der einheimischen Kreaturen, darunter auch die großen Frostwolf-Worgs. Diese Wölfe erwiesen sich bald als nicht nur sehr schnell sondern auch als tödlich, halfen sie doch den Orcs, zahllose Schlachten für sich zu entscheiden. \r\nDie großen weißen Wölfe, die der [[Frostwolfklan]] nach seiner Verbannung im [[Alteractal]] fand, waren völlig anders als die riesigen schwarzen Wölfe, die [[Durotan]]s Leute einst ritten. Aber ein Wolf war ein Wolf, egal welche Farbe sein Pelz hatte, und entschlossene Geduld kombiniert mit [[Drek'Thar]]s Kräften hatte die wilden Tiere für sie gewonnen. Jetzt jagten [[Orc]] und [[Wolf]] zusammen und hielten einander warm während der endlosen Schneenächte.\r\nNachdem es Thrall gelungen war, alle Klans zu versöhnen, haben die Orcs des Frostwolfklans eingewilligt, ihre Reittiere mit allen Mitgliedern der Horde als Zeichen der Solidarität zu teilen. Die Worgs selbst sind dieser Entscheidung gefolgt, und viele Hordenreiter zählen inzwischen auf die Worgs als verlässliche Begleiter.\r\n==Arten==\r\n* '''Frostwolfheuler''' - Erhältlich für: Horde. Benötigt: Stufe 60, Geübter Reiter (150). Kosten: 50 Abzeichen des [[Alteractal]]s.",},
			["Frostwolfklan"] = { content = "==Aktuelles==\r\nIn jüngster Zeit wurde der Frieden des Frostwolfklans im [[Alteractal]] durch die Ankunft der zwergischen [[Sturmlanzen]]-Expedition gestört. Die [[Sturmlanzen]] haben sich auf der Suche nach Rohstoffen und Relikten aus der zwergischen Vorgeschichte im Tal angesiedelt. Trotz ihrer friedlichen Absichten hat die Ankunft der [[Zwerge]] einen erbitterten Streit mit dem Frostwolfklan entfacht, in dem inzwischen beide Seiten um die alleinige Kontrolle über das Tal kämpfen, denn der Frostwolfklan will die Zwerge des Sturmlanzenklans aus dem Alterac Tal vertreiben. \r\n==Hintergrund==\r\nAls die gefestigte Gesellschaft der [[Orcs]] von innen heraus verdorben wurde, hielten nur wenige an der [[Schamanen|schamanischen]] Kultur ihrer Ahnen fest. Die Frostwölfe und ihr Häuptling [[Durotan]] hatten die wahren Ziele der [[Hexenmeister]] erkannt und stellten sich [[Gul'dan]]s irren Machtbestrebungen in den Weg. Sie versuchten auch andere von der Wahrheit zu überzeugen, doch die orcische Stämme ahnten nichts von den Ränken des [[Schattenrat]]s. Die einst ehrenhaften Krieger standen zunehmend unter dem verderblichen Einfluss der [[Dämonen]] und hatten sich bereitwillig der [[Brennende Legion|Brennenden Legion]] ausgeliefert. Nach [[Thrall]]s triumphaler Vereinigung der Klans entschlossen sich die Frostwölfe unter der Führung des Schamanen [[Drek'Thar]], im [[Alteractal]] zu bleiben, das so lange ihre Heimat gewesen war. \r\n==Persönlichkeiten==\r\nZu den Persönlichkeiten des Frostwolfklans zählen:\r\n* [[Durotan]] - Häuptling und Thralls Vater\r\n* [[Draka]] - Durotans Frau\r\n* [[Drek'Thar]] - Scharfseher. Letzter Führer des Frostwolfklans.\r\n* [[Kash'Drakor]] - Ein berühmter und legendärer Orc-Krieger.\r\n* [[Nazgrel]] - Der hervorstechendste Krieger des Frostwolfklans\r\n* [[Thrall]] - Sohn von Durotan und Kriegshäuptling der Horde.\r\n===Verbannung und Isolation===\r\nGul'dan nutzte während der finsteren Tage des ersten Krieges seinen Einfluss, um den Frostwolfklan in die Verbannung zu schicken. Der Stamm ließ sich im [[Alterac]]gebirge nieder und musste mit ansehen, wie die [[Orcs]] von einem wilden Kampfrausch erfasst wurden. Nur [[Orgrim Schicksalshammer]], der Häuptling des [[Donnerfürsten Klan]]s, war bereit, sich mit [[Durotan]] zu treffen und auf die Warnungen seines alten Freundes zu hören. Auf dem Rückweg geriet [[Durotan]]s Familie jedoch in einen Hinterhalt und wurde getötet. Die niederträchtigen Mörder ließen nur seinen Sohn am Leben, um ihn in den verschneiten Bergen sterben zu lassen. Aber ein Mensch namens [[Aedelas Schwarzmoor]] fand den jungen Orcling, den er [[Thrall]] nannte, und brachte ihn in die Gefängnisfestung [[Durnholde]]. \r\nNachdem die Frostwölfe vom Tod ihres Häuptlings erfahren hatten, übernahm der alte Schamane [[Drek'Thar]] die Führung des Stammes. Der Klan zog sich wieder ins [[Alterac]]gebirge zurück und mischten sich fortan nicht mehr in die Machtkämpfe der [[Horde]] ein.\r\n===Kriegshäuptling [[Thrall]]===\r\nNeunzehn Jahre vergingen, in denen die [[Orcs]] besiegt und ihre verstreuten Stämme in Internierungslager gesperrt wurden. [[Thrall]] war unterdessen zu einem furchtlosen Krieger herangewachsen. Er beschloss, aus Schwarmoores Festung zu fliehen und nach Seinesgleichen zu suchen. Auf der Suche nach der Wahrheit über seine eigene Herkunft reiste [[Thrall]] nach Norden, um den legendären Frostwolfklan zu finden. Unter den Augen des ehrwürdigen [[Drek'Thar]] studierte er die uralte [[Schamanen]]kultur seines Volkes und nahm seinen rechtmäßigen Platz als Häuptling der verbannten Frostwölfe ein. [[Thrall]] war von dem Wunsch beseelt, die Unterdrückung seines Volkes zu beenden und die [[Orcs]] von der [[Dämonen|dämonischen]] Verderbnis zu heilen. Die Frostwölfe und der [[Kriegshymnenklan]], der sich den wachsamen Blicken der [[Allianz]] entzogen hatte, vereinten sich zu einer Streitmacht unter [[Orgrim Schicksalshammer|Schicksalshammers]] Kommando. Gemeinsam erstürmten sie die Internierungslager und befreiten die Stämme aus der Gefangenschaft. Doch bei der Befreiung eines Lagers fiel [[Orgrim Schicksalshammer]] im Kampf und bestimmte [[Thrall]] zum neuen Kriegshäuptling der [[Horde]]. In den folgenden Monaten zerstörte die kleine, aber findige Armee die Internierungslager. Sogar [[Durnholde]] - die Festung, die für die Sicherheit der Lager verantwortlich war - wurde von den [[Orcs]] vernichtet.",},
			["Frostwyrm"] = { content = "Seit ewigen Zeiten fliegen die [[Drachen]] von Azeroth nach [[Nordend]], um dort zu sterben. Bis auf den heutigen Tag existieren ganze Drachenfriedhöfe mit riesigen versteinerten Knochen und Schädeln. Als [[Ner'zhul]] die Macht in [[Nordend]] an sich riss, nutzte er seine mächtige [[Magie]], um die uralten Drachenskelette in einem [[Knochenhof]] wiederzubeleben. Nun fliegen diese Frostwyrms im Namen des [[Lichkönig]]s über die Schlachtfelder Azeroths und speien ihren tödlichen Eisatem, welcher Feinde zu Boden wirft und schädigt, gegen die Lebenden. Außerdem sind sie ganz verrückt danach, ihre unglückseligen Feinde in einem Stück zu verschlingen. Um weitere Wyrms zu rufen, wurden Knochen in mächtigen Becken gesammelt und mit in den Süden genommen.\r\n==Fähigkeiten==\r\n* '''Eisatem''' - Ner'zhuls tückische Frostwyrms bergen die Eiseskälte von [[Nordend]] in ihren Skelettherzen. Wenn sie eine große Menge Luft inhalieren, können sie einen Schwall so extremer Kälte ausstoßen, dass sie der Luft um ein Gebäude herum alle Feuchtigkeit entziehen und es einfrieren.\r\n==Berühmte Frostwyrms==\r\n* [[Sapphiron]]",},
			["Frostöl"] = { content = "Frostöl besteht aus den Pflanzen [[Khadgars Schnurrbart]] und [[Winterbiss]] und kann von [[Alchimist]]en hergestellt werden. \r\n[[Goblins]] schwören auf seine hervorragenden Eigenschaften beim Einsatz im Ingenieurswesen, denn nichts kann einen Motor oder ein Getriebe besser vor Überhitzung schützen. Seine Kühleigenschaften sind außerordentlich und seine Langlebigkeit als Schmiermittel ist ohnegleichen. Und so findet es z.B. im [[Eisdeflektor]], dem [[Gyrofrosteisreflektor]] oder dem [[Schneemeister 9000]] Einsatz.\r\nEs trägt auch dazu bei, die Verzauberung magischer Gegenstände zu erhalten.\r\nDas Rezept für die Herstellung wird von Bro'kin im Alteracgebirge verkauft.",},
			["Funggorhöhle"] = { content = "Die '''Funggorhöhle''' ist liegt im Südosten der [[Zangarmarschen]]. Die [[Sporlok]]s leben in dieser Höhle, aber die [[Bäumlinge|Marschenbestien]] sind kürzlich dort eingefallen. Die [[Expedition des Cenarius]] musste die Wächter, die sich aufgemacht haben, um die Funggorhöhle zu erkunden, wegen Angriffen von [[Sumpfmonster]]n zurückrufen. [[Lord Klaq]] ist der Anführer der Sumpfmonster.",},
			["Fungusriese"] = { content = "#REDIRECT [[Fungusriesen]]", redirect = "Fungusriesen",},
			["Fungusriesen"] = { content = "==Allgemeines==\r\nDie einzigartigen Gase und die nährstoffreiche Erde der [[Zangarmarschen]] bilden einen idealen Lebensraum und haben die Entwicklung einer wundersamen und verschiedenartigen Feuchtlandökologie begünstigt. Die Fungusriesen der Marschen sind ein gutes Beispiel für die bemerkenswerte Fauna dieser Umgebung. Obwohl sie normalerweise sehr gutmütig und nicht angriffslustig sind, so können diese schwerfälligen Giganten Gegner mit Leichtigkeit überwältigen, wenn sie provoziert werden. Sie ernähren sich von den anderen Lebewesen der Marschen, wie auch von [[Verirrte]]n, die den Fehler begangen haben, sich den Verstecken der Giganten zu sehr zu nähern. Die Fungusriesen sind die größeren und zäheren Vettern der Sumpfriesen.\r\n===Austrocknung der [[Zangarmarschen]]===\r\nDurch die Austrocknung der Seen der [[Zangarmarschen]] beginnen die Fungusgiganten zu welken und zu sterben. Der Schmerz macht sie wahnsinnig, und bringt sie dazu, alles in ihrer Nähe anzugreifen. Diese Lebewesen haben nicht die leiseste Ahnung, was mit ihnen geschieht. Die Sumpflords, sollten der Degenerierung, die die [[Riesen]] befallen hat, gegenüber unempfindlicher sein. \r\nBei der genaueren Untersuchung des siechenden Basidiums eines Sumpflords, lassen sich eine Zahl von Einkerbungen erkennen, in denen vielleicht mal etwas drinsteckte. Die fremdartige Pilzmasse scheint so etwas wie ein großes Rätsel zu sein. Sie sieht alles andere als gesund aus, aber man hat keine Ahnung, wozu sie normalerweise dienen könnte.\r\n==Unterscheidungen==\r\n* '''Sumpfriesen'''\r\n* '''Sumpflords''' sind die größeren und zäheren Vettern der Sumpfriesen\r\n==Persönlichkeiten==\r\nBisher bekannte hochrangige Fungusriesen sind:\r\n* [[Hungarfen]]\r\n* [[Quagmirran]]",},
			["Funkelmat 5200"] = { content = "Der '''Funkelmat 5200''' ist ein Gerät zur Reinigung von Wertgegenständen und wurde in Gnomeregan aufgestellt. Dieser Apparat ist etwas ganz Besonderes unter den [[Gnome]]n in [[Gnomeregan]], denn er bietet dem Wahnsinn außerhalb des Raumes, in dem er steht, tapfer die Stirn. \r\nEine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text: \"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu. Gebt den Gegenstand hinein, den Man gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilá . Eure Wertgegenstände werden sauber und glänzend herauskommen.\" Der Funkelmat 5200 erwacht bei Benutzung hin und her schlingernd zum Leben. Innen wird dann der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomenlösungsmittel der Maschine pulverisiert. Der Funkelmat 5200 kommt nach getaner Arbeit zum Stillstand, angekündigt durch ein vertrautes \"Ding.\". Danach springt der Aufnahmebehälter der Maschine auf und offenbart eine ordentlich eingewickelte Schachtel.",},
			["Furbolg"] = { content = "#REDIRECT [[Furbolgs]]", redirect = "Furbolgs",},
			["Furbolgs"] = { content = "Furbolgs sind schwerfällige, einfältige Bärmenschen, die in den wilden Ecken der Wälder von [[Eschental]] leben.Die Halbgötter [[Ursoc&Ursol]] sollen die Furbolgs einst geschaffen haben. Früher waren die Furbolgs ein friedliches und naturverbundenes Volk. Die mächtigen Bärenmenschen zählten zu den ältesten Bewohnern [[Kalimdor]]s und existierten schon lange vor der Großen Teilung. Doch ihre Stämme hatten besonders unter der Invasion der [[Brennende Legion|Legion]] zu leiden und als sich die Verderbnis der [[Brennende Legion|Brennenden Legion]] in den uralten Wäldern ausbreitete, verließen viele Furbolgs ihre angestammte Heimat. Einige Stämme zogen sich weiter in ihre Reviere zurück und wurden im Laufe der Zeit zunehmend feindseliger. Obwohl sie keine spezielle Neigung zu Krieg und Mord verspüren, verfielen sie immer mehr in die Raserei, die ihr Volk übermannte. Die [[Nachtelfen]] waren besorgt über die Veränderung dieses einst friedlichen Volkes und versuchten, den Furbolgs bei der Beilegung ihrer Spannungen zu helfen, doch das einst friedliche Volk wurde beinahe vollständig von der Verderbnis verzehrt - nur ein Stamm entkam diesem Unglück ... die [[Furbolgs der Holzschlundfeste]].\r\nÜber eine Verwandschaft mit den [[Pandarene]]n wir noch diskutiert\r\n==Stämme==\r\n* [[Furbolgs der Distelfelle]]\r\n* [[Furbolgs der Fäulnisklauen]]\r\n* [[Furbolgs der Holzschlundfeste]]\r\n* [[Furbolgs der Knarzklauen]]\r\n* [[Furbolgs der Sichelklauen]]\r\n* [[Furbolgs der Schwarzfelle]]\r\n* [[Furbolgs der Tannenruhfeste]]\r\n* [[Furbolgs der Totenwaldfelle]]\r\n* [[Furbolgs der Winterfelle]]",},
			["Furbolgs der Distelfelle"] = { content = "Direkt im Norden von [[Astranaar]] im [[Eschental]] leben die [[Furbolgs]] vom Distelfellstamm. Ihre Höhle liegt am Ende des Lagers der Distelfelle und in den Kisten dort befinden sich Troll-Glücksbringer. Deswegen sind viele der Meinung, dass diese Furbolgs verflucht sind.\r\nIhre Zahl hat sich in den letzten Monaten erhöht und sollten es zu viele werden, könnten sie den Mut finden, [[Astranaar]] direkt anzugreifen. Doch die Distelfellfurbolgs bedrohen auch die Expansion der [[Horde]], denn das Lager der [[Furbolgs]] östlich vom [[Zoram'gar-Außenposten]] blockiert den Weg zwischen ihnen und dem [[Splitterholzposten]]. Dieser Weg würde das Dorf [[Astranaar]] umgehen; und ohne ihn überläßt die [[Horde]] der [[Allianz]] eine zusätzliche Möglichkeit der Ausbreitung. Sie dürfen keine Lücke in ihren Expansionspfaden erlauben. \r\nDort gefangen findet man den Tauren '''Ruul Schneehuf'''. Die Furbolgs hielten ihn für einen Bären und fingen ihn. Jetzt lassen sie ihn verhungern und seine Kraft schwindet.",},
			["Furbolgs der Fäulnisklauen"] = { content = "Entlang der Straße, die im [[Eschental]] von [[Astranaar]] nach Osten führt, haben [[Furbolgs]] kurz vor dem Falfarren Reisende angegriffen. Ihre gequälten Seelen nähren sich von Angst und sie stillen ihren Appetit mit dem Blut Unschuldiger. Man hilft den [[Schildwache]]n, das Land zu schützen, indem man diesen Monstern dieselbe Gnade zeigt, die sie anderen erwiesen haben. Es gibt zwar nicht so viele von ihnen wie das bei den [[Furbolgs der Distelfelle]]n der Fall ist, aber ihre Wildheit könnte sich in der Zukunft zu einem Problem auswachsen. Die Furbolgs sind trotz der Verderbnis noch zu jeder Menge Bösem fähig. Ran Blutreißer ist einer dieser Bösen. Er ist mchthungrig und gierig. Die Verderbnis hat ihn nur noch stärker gemacht.",},
			["Furbolgs der Holzschlundfeste"] = { content = "#REDIRECT [[Holzschlundfeste]]", redirect = "Holzschlundfeste",},
			["Furbolgs der Schwarzfelle"] = { content = "Die [[Furbolgs]] der Schwarzfelle leben in der [[Dunkelküste]]. Eines ihrer Lager befindet sich südlich von [[Auberdine]] und stellt momentan die größte Bedrohung für die [[Nachtelfen]] dieses Gebietes dar. Ein zweites Lager liegt flussaufwärts der Klippenquellfälle. Die Furbolgs des nördlichen Lagers hält man für den Auslöser der Besudelung der [[Dunkelküste]], aber man vermutet auch, dass sie nicht die wahre Ursache sind. Man fand heraus, dass sie [[Satyrn]] ein Grund für die Verderbnis der [[Furbolgs]] der Schwarzfelle sind, denn sie üben ihre Macht durch Talismane aus, mit denen sie ihre Magie kanalisieren können. Damit die [[Furbolgs]] Aussicht auf Rettung haben, muss man den Satyrverderber aus seinem Versteck locken und ihm diesen Talisman abnehmen.",},
			["Furbolgs der Sichelklauen"] = { content = "Die verdorbenen [[Furbolgs]] der Sichelklauen leben in einem Lager auf der [[Blutmythosinsel]].\r\nSie haben die Prinzessin der [[Furbolgs der Tannenruhfeste]] entführt und in ihr Lager verschleppt, wo sie in einem Käfig gefangen gehalten wird. Dort wollen die Sichelklauen sie ihren üblen Göttern opfern. Man muss den Oberhäuptling der Sichelklauen töten, um an den Schlüssel für den Käfig der Prinzessin zu gelangen. Damit dieser auftaucht, muss man jedoch zuvor die bösartigen [[Furbolgs]] der Sichelklauen töten, die in der Enklave auf der [[Blutmythosinsel]] hausen.",},
			["Furbolgs der Tannenruhfeste"] = { content = "Die Furbolgs der Tannenruhfeste sind ein friedlicher Stamm auf der [[Azurmythosinsel]], die sich mit den [[Draenei]] dort verbündet haben und mit ihnen ihr schamanistisches Wissen teilen. Ihre Feinde sind die [[Furbolgs der Sichelklauen]], die die Prinzessin der Tannenruhfeste gefangen genommen haben und sie ihren üblen Göttern opfern wollen. Der Botschafter der Tannenruhfeste Frasaboo hat sich deswegen zur [[Blutwacht]] auf der [[Blutmythosinsel]] aufgemacht, um die [[Draenei]] dort um Hilfe zu bitten.",},
			["Furbolgs der Totenwaldfelle"] = { content = "Es gibt ganz im Norden des [[Teufelswald]]es, direkt südwestlich hinter der [[Holzschlundfeste]], eine große Gruppe [[Furbolgs]], den genannten Stamm der Totenwaldfelle, die äußerst aggressiv auf alle Eindringlinge reagieren. Doch ihre Feindseligkeit ist keine angeborene Eigenschaft, sondern die Verderbnis ist es, die ihre Hirne verseucht. Angeführt werden sie von [[Häuptling Blutmagen]] und [[Oberanführer Ror]].\r\nIm hinteren Teil ihres Lagers befindet sich ein Kessel mit einer grünlichen Substanz. Diese Substanz scheint der zu ähneln, die man auch in den Fläschchen der [[Furbolgs der Winterfelle]] findet und enthält Spuren von toxischen Elementen. Man vermutet, dass es Beziehungen zwischen den [[Furbolgs der Winterfelle]] und den Totenwaldfellen gibt. Die [[Furbolgs]] der Totenwaldfelle holen sich diese Elemente möglicherweise von anderen verderbten Kreaturen im [[Teufelswald]], vor allem von den [[Elementare]]n, die im [[Eisenwald]] leben und Toxinschrecken genannt werden. \r\nEinige [[Furbolgs]] tragen auch ein Ritualtotem der Totenwaldfelle bei sich. Dieses Ritualtotem ist von unbestimmbarer Machart, aber es geht eine spürbare Verzweiflung davon aus. Gäbe es auch nur eine einzige Sache, die die Verderbnis der Totenwaldfelle veranschaulichen könnte, so wäre es mit Sicherheit dieses Totem.",},
			["Furbolgs der Winterfelle"] = { content = "Die '''Furbolgs der Winterfelle''' sind ein Stamm der in [[Winterquell]] beheimatet ist. Sie unterscheiden sich von anderen [[Furbolgs]] durch ihre weißes Fell, womit sie sich an die Lebensbedingungen im Schnee angepaßt haben. Ihr Lager liegt im Osten von Winterquell. In letzter Zeit ist den Furbolgs der [[Holzschlundfeste]] aufgefallen, dass der Winterfellstamm ihnen gegenüber immer größere Feindseligkeit zeigt. Sie scheinen in Rage zu sein, und ganz von ihrem Hass auf alles beseelt, das sie nicht verstehen. Die [[Furbolgs]] scheinen wahnsinnig zu sein, alles, was in ihrem Weg steht, scheint sie zu ängstigen. Man hat beobachtet, wie sie zahllose Kreaturen erschlagen haben, die das Pech hatten, einfach zur falschen Zeit am falschen Ort zu sein. Die Furbolgs der Winterfelle sind normalerweise kein aggressiver Stamm und diese Änderung ihres Verhaltens führt einige zu der Annahme, dass sie Befehle ihres Häuptlings ausführen. Die Furbolgs der Winterfelle scheinen von den Quellen in [[Winterquell]] angezogen zu werden. Mittlerweile wachen sie extrem eifersüchtig über das Wasser und lassen niemanden in die Nähe der beiden größeren Quellen. \r\nMan vermutet, dass es Beziehungen zwischen den [[Furbolgs der Winterfelle]] und den [[Furbolgs der Totenwaldfelle]] gibt, denn die grünliche Substanz in dem Kessel der Totenwaldfelle scheint der zu ähneln, die man in dem Fläschchen mit dem [[Feuerwasser der Winterfelle]] gefunden hat. Dieses merkwürdige zähflüssige Zeug könnte genauso verderbt sein wie die Furbolgs, die es geschaffen haben. Falls die Winterfellfurbolgs es verwenden, bedeutet das, dass sie bald genauso verderbt sein werden wie der Stamm der Totenwaldfelle. Deshalb muss man den Kontakt zwischen den Winterfellen und den Totenwaldfellen abschneiden und den Oberhäuptling der Winterfelle besiegen, denn wenn der Anführer erledigt ist, wird es zumindest nicht schlimmer werden.\r\n==Gegenstände==\r\n* [[Feuerwasser der Winterfelle]]\r\n* '''Ritualtotem der Winterfelle''' - Das Ritualtotem der Winterfelle ist von unbestimmbarer Machart, aber es geht eine beinahe greifbare Aura der Furcht und Verzweiflung von ihm aus. Sollten tatsächlich alle Furbolgs der Winterfelle ein solches Totem bei sich tragen, würde dies ihren momentanen Zustand sicherlich erklären.\r\n==Persönlichkeiten==\r\n* '''Grizzel Schneepfote'''\r\n* '''Oberhäuptling der Winterfelle'''- Der Oberhäuptling der Winterfelle trägt ein kunstlos geschriebenes Logbuch bei sich. Es scheint recht ausführlich zu sein, aber nachdem man einige Seiten durchgesehen hat, stellt man fest, dass man den Text nicht lesen kann. Die Zeichen sind so kunstlos und schlecht.\r\n* '''[[Xandivious]]'''",},
			["Furen Langbart"] = { content = "'''Furen Langbart''' ist ein zwergischer Rüstungsschmied im [[Zwergendistrikt]] von [[Sturmwind]], dessen Arbeit sehr bewundert wird. Seine Fertigkeit ist unübertroffen und er ist der beste Schildschmied, den man je gesehen hat. Er kennt auch das Geheimnis, wie man extrem harte Panzerrüstung herstellt. Das Verfahren für einen Feuergehärteten Panzer für Krieger beschreibt er in ''Furens Anleitung''. \r\n==Furens Anleitung==\r\nAuf den folgenden Seiten findet Ihr eine Liste der Materialien, die Ihr für eine feuergehärtete Rüstung benötigt. Viel Glück, Krieger.\r\n- Furen Langbart\r\n* '''Versengte Spinnenfangzähne''' - Das [[Pyrophor]]erz aus den Höhlen in der Nähe des [[Thelgenfelsen]]s hat die dort lebenden Spinnen versengt. Das Gift in ihren Fangzähnen kocht und reagiert mit den Fangzähnen und produziert dadurch eine sehr harte Substanz.\r\n* '''Verkohlte Hörner''' - Ebenso wie die versengten Spinnenfangzähne haben auch die verkohlten Hörner der im [[Verbranntes Tal|Verbrannten Tal]] lebenden [[Schimären]] aus dem [[Steinkrallengebirge]] auf Kalimdor wertvolle Eigenschaften. Flachgeklopft und in geeigneter Weise behandelt werden sie gegen mechanische Belastungen äußerst robust.\r\n* '''Galvanisiertes Horn''' - Das galvanisierte Horn gibt der gesamten Rüstung, die ich für Euch machen werde, erst ihre Härte. Daher brauchen wir das Horn unbedingt. Ihr bekommt es von der seltenen Schimärenmatriarchin im verbrannten Tal.\r\n* '''Phiole mit Phlogiston''' - In der letzten Phase brauche ich zur Herstellung der Rüstung eine äußerst heiße Schmiede. Damit die Schmiede heiß genug wird, brauche ich wiederum eine Phiole mit Phlogiston. Der einzige bekannte Hersteller dieser Substanz ist der berühmte Stacheleber [[Roogug]], und der wird sie nicht kampflos hergeben. Roogug lebt zurückgezogen im [[Kral der Klingenhauer]] im südlichen [[Brachland]].",},
			["Furor Winterfrost"] = { content = "'''Furor Winterfrost''' ist ein mächtiger [[Lich]] in den [[Höhlen der Zeit: Kampf um Hyjal]].\r\n==Kampf==\r\nDer Lich Furor Winterfrost greift Eure Schlachtgruppe hauptsächlich mit Eisblitzen an. Solange man nicht an diesen erfriert, ist die Bossbegegnung ein wahrer Klacks. Furor Winterfrost ist ein Lich, wie er im Buche steht – er benutzt daher dieselben Fähigkeiten wie die Heldenklasse aus [[Warcraft 3]]. \r\n* '''Frostnova''': Ein zufälliger Spieler wird das Opfer der Frostnova. Er und alle im 20-Meter-Radius stehenden Mitspieler erhalten rund 3.000 Frostschaden und werden für acht Sekunden gewurzelt. Dieser Zauber tritt nicht zeitgleich mit Tod und Verfall auf und kann widerstanden werden.\r\n* '''Eisblitz''': Furor Winterfrost beschießt in etwa Fünf-Sekunden-Abständen zufällige Spieler mit einem Frostblitz. Dieser richtet etwa 5.000 Initialschaden an und sperrt den Spieler für vier Sekunden in ein Frostgrab. In diesem Grab ist er handlungsunfähig und erleidet sekündlich 2.500 Frostschaden. \r\n* '''Tod und Verfall''': Dieser zehnsekündige Kanalisierungseffekt tritt irgendwo im Kampfgebiet auf. Spieler, die innerhalb des roten Flächeneffektes verharren, verlieren alle zwei Sekunden 15 Prozent ihrer maximalen Trefferpunkte. Während dieses Zaubers wirkt der Boss weder andere Zauber noch übt er Nahkampfschaden aus.",},
			["Futamaki"] = { content = "==Aussehen und Merkmale==\r\nGroß und durchtrainiert, aber eher drahtig und athletisch, als übermäßig muskelbepackt. Eine große Ausdauer zeichnet ihn aus und er kann stundenlang über die Ebenen laufen. Die Hautfarbe ist ein tiefes Grün wie bei Dschungeltrollen üblich.\r\n==Persönlichkeit==\r\nFutamaki ist ein lustiger und ehrlicher Troll, dem Intrigen und Falschheit zuwider sind und auch manchmal etwas einfältig erscheint, weil er solche Dinge meist nicht durchschaut. Gutmütig und großzügig ist er, solange bis man ihn zu sehr gereizt hat. Dann kann er bitterböse werden und auch hart, wenn man den Bogen überspannt, was dann endgültig ist. Im Umgang mit anderen Leuten, insbesondere mit Trollweibchen ist er oft unsicher und deshalb tollpatschig, neigt aber auch dazu, dieses mit offen zur Schau getragener Selbstsicherheit zu überspielen. Er ist nicht gerne in engen Räumen und liebt offene und weite Flächen\r\n==Geschichte==\r\nGeboren wurde Futamaki inmitten einer kleinen Siedlung der Anduri tief im Dschungel von Stranglethorn. Die kleine Familie lebte in einer geräumigen Hütte zusammen mit dem älteren Bruder Kenakkuris, Yokkaichi. Dieser hatte bei einem Kampf mit einem Raptor eine schlimme Beinwunde davon getragen und musste gepflegt werden. Zu Yokkaichis Verdruß, selber noch jung und unerfahren, musste er seine Ausbildung zum Schamanen derweil ruhen lassen, solange ihn das Fieber und die Schwäche ans Bett fesselte. Eines Nachts, noch viel zu früh um wieder aufzustehen und auf eigen Faust das Lager zu verlassen, was ihn selbstverständlich nicht davon abhielt es doch zu tun, kam Yokkaichi gerade vom Kräutersuchen zurück, als er Kampflärm hörte… Er ließ die Kräuter fallen und lief zurück so schnell er konnte… schon von Ferne hörte er fremde Stimmen in einer Sprache die er nicht verstand, ihm aber dennoch wohlbekannt war, die singende Sprache der Elfen. Hütten brannten lichterloh und überall liefen die Krämpfer der Nachtelfen und der Trolle kreuz und quer durchs Dorf, in dem ein wilder Kampf tobte.\r\nUnbemerkt schlüpfte er hindurch zu Hütte und fand dort Xurajiin mit dem kleinen Futamaki auf dem Arm, die aus zahlreichen Wunden blutet, die die spitzen Pfeile der Elfen geschlagen hatten. Kaum noch fähig zu sprechen, schob sie ihm das Kind in die Arme und ihre Augen brachen, nachdem sie ihm gesagt hatte, er solle den Kleinen wegbringen. Voller Panik und Trauer floh Yokkaichi in den Dschungel, doch er kam nicht weit. Ein paar der elfischen Krieger hatten ihn bemerkt und setzen auf ihrern Saäbelzahnpantern hinterher und griffen ihn samt dem Kind auf. So gelangte Yokkaichi nach Kalimdor und geriet in Kriegsgefangenschaft und wurde dort in ein Gefangenenlager gesteckt. Einige Zeit später gelang ihm die Flucht, und er erreicht die staubigen Ebenen Durotars, doch nicht ohne den Häschern an den Fersen. Er versteckte sich zwischen einigen Sandsteinfelsen, als er eine Orkfrau sah, die sich ebenfalls unweit von ihm und dem Jungen verborgen hatte. Die elfischen Reiter kamen direkt auf ihr Versteck zu, da zeigte Yokkaichi auf den Jungen, bedeutete Futamaki still zu sein und rannte aus seinem Versteck davon. Die Häscher entdeckten ihn sofort und griffen ihn abermals auf, dann ritten Sie zufrieden und vermeindlich erfolgreich von Dannen.\r\nDie Orkfrau Misha Tor’kren verließ ihr Versteck und nahm eher wiederwillig, aber sich an die Ehre gebunden fühlend, den kleinen Troll mit sich zu ihrem Bauernhof, wo sie anfing ihn aufzuziehen. Futamaki wuchs schnell heran und fand in Mishas Sohn Kron einen Freund. Doch sehr geliebt war er ansonsten nicht im Hause Tor’kren, wurde die Familie doch diskriminiert, weil sie einen Trolljungen bei sich aufzogen. Auch war die Arbeit auf den Feldern hart und schweißtreibend, und sooft es ging zogen Kron und er durch die Gegend, um Tiere zu jagen. Eines Tages kam Kron nicht zurück und Misha machte den mittlerweile halbwüchsigen Futamaki dafür verantwortlich und jagt ihn in einem anfall von Jähzorn aus ihrem Haus davon. Von dieser Zeit an, schlief Futamaki im Freien und schlich alleine in den Staubwolken der roten Ebene an den gefährlichen Raptoren vorbei, die er so sehr bewunderte wegen iher Stärke und Zähigkeit. Einige Wochen später, in einer engen Schlucht, stand ganz plötzlich einer der ach so tödlichen Tiere vor ihm… ganz starr wurde er, wusste er zu genau, dass jede Bewegung seine letzte sein könnte und schaute dem Raptor in die Augen… wie lange das Starren ging, vermag er heute nicht zu sagen, doch nach unendlich langer Zeit näherte sich Futamaki dem Raptor ohne Furcht und streichlte seine lederige Haut. Von diesem Tag an ist Rashuki bei Futamaki geblieben und ein Band aus tiefster Freundschaft verbindet die beiden. Er lernt zu jagen und entwickelte eine guten Instinkt für Tiere und andere Wesen.\r\nGerne laufen die Beiden über die weiten Steppen des Brachlandes auf der Jagd nach gutem Wild und fetter Beute\r\nAls er eines Tages einen anderen Jäger traf, erzählte der ihm vom Tal der Prüfungen und Futamaki machte sich auf, dort seine Ausbildung zu beginnen.\r\nJahre später, bei einem seiner ersten Besuche in Orgrimmar traf Futamaki Yokkaichi wieder, der ihm alles über seine Familie erzähle. Yokkaichi, der mittlerweile erfolgreich aus der Gefangenschaft befreit worden war, verlässt die Stadt nur noch selten, und wenn dann nur kurz um Kräuter zu sammeln. Manchmal kümmert er sich um die Geschäfte von Futamaki, wenn dieser ihn wieder einmal besuchen kommt, um ihm von den Abenteuern zu erzählen, die er so erlebt hat.",},
			["Fäulnisranke"] = { content = "Auf dem Grund des Tempels von Atal'Hakkar findet man die Fäulnisranke, aus der man ein sehr wirksames Gift herstellen kann.",},
			["Fürst der Asche"] = { content = "(engl. Duke of Cynders)\r\nDer Fürst der Asche ist einer der Elementaren Adligen des [[Abyssischer Rat|Abyssischen Rates]], der an einem der [[Windsteine]] in [[Silithus]] mit Hilfe des [[Siegel der Anrufung]] (Feuer) beschworen werden kann.",},
			["Fürst der Leere"] = { content = "Die furchteinflößenden '''Fürsten der Leere''' (engl. ''Void Lords'') sind mächtige [[Leerwandler]] und gehören zu den [[Dämonen]]. Sie sind dafür bekannt, gewaltige Leerenarmeen anzuführen und alles, was sich ihnen in den Weg stellt, zu vernichten. Opfer einer solchen Leereninvasion wurde z.B. [[K'aresh]], die Heimatwelt der [[Astrale]]n, als [[Dimensus]] seine Heerscharen auf diese Welt losließ.\r\n==Warcraft-Chroniken==\r\nLaut ''\"[[World of Warcraft: Chronik, Band 1]]\"'' traf der Titan [[Sargeras]] auf seinem Kreuzzug gegen das Chaos schließlich auf das ultimative Böse, das seit Anbeginn der Zeit darauf lauerte, das [[Große Dunkle Jenseits]] ganz und gar zu verschlingen: Die rätselhaften Leerenfürsten. \r\nDie Leerenfürsten herrschen über die Domäne der Leere und bilden die Kehrseite der Medaille zum gleißenden Licht und den Kristallwesen namens [[Naaru]]. Keiner weiß so genau, wie viele Leerenfürsten es wirklich gibt. \r\nAlles, was wir wissen, ist, dass sie keine physische Gestalt besitzen und eher einem gewaltigen Schwarzen Loch gleichen, das alles Licht verschlingt. Die Leerenfürsten können das [[Große Dunkle Jenseits]] zwar nicht selbst betreten, dafür schicken sie allerdings ihre Diener - die [[Alten Götter]] - aus, um die beseelten Welten zu verderben. Gespeist mit dunkler Energie sollte das schlummernde Wesen (im Kern der Welten) als Dunkler Titan erwachen und den hungernden Göttern der Leere einen Weg ins Universum bereiten. \r\nAls [[Sargeras]] eine dieser verdorbenen Welten erblickte, erkannte er, dass der Dunkle Titan und der unstillbare Hunger der Leerenfürsten eine weitaus größere Bedrohung für das Universum darstellten als die chaotischen Dämonen. Mit nur einem Schwertstreich zerstörte Sargeras den Planeten und vernichtete das Böse, das darauf hauste. Der Schock und die Erkenntnis löschten schließlich den letzten Funken von Sargeras' Güte aus und trieben den Titanen in die Verzweiflung. \r\n==Persönlichkeiten==\r\n* [[Arconus der Unersättliche]]\r\n* [[Dimensius]]\r\n* [[Galaxis]]\r\n* [[Leerjäger Yar]]\r\n* [[Pandemonius]]\r\n* [[Zuramat der Vernichter]]",},
			["Fürst der Splitter"] = { content = "Der Fürst der Splitter ist ein [[Erdelementar]] und einer der Elementaren Adligen des [[Abyssischer Rat|Abyssischen Rates]]. Er kann in [[Silithus]] an einem der normalen [[Windsteine]] mit Hilfe eines [[Zierratsset der Schattenhammer]], einem [[Standesmedaillon eines Schattenhammerkultisten]] und eines [[Siegel der Anrufung]] (Erde) beschworen werden.",},
			["Fürst der Stürme"] = { content = "Der '''Fürst der Stürme''' kann mittels eines [[Siegel der Anrufung]]: Donner bei den [[Windsteine]]n in [[Silithus]] beschworen werden können. Er erscheint in Form einer [[Windnatter]] und ist ein Abgesandter des [[Abyssischer Rat|Abyssischen Rates]]. Man sagt, dass die namhaften [[Elementare]], die als abyssischen Fürsten bekannt sind, ein Teil der treibenden Kräfte hinter den Kultisten des Schattenhammers darstellen. Um das Siegel der Siegel der Anrufung herzustellen, benötigt man die entsprechende Schriftrolle, eine Dunkelrune und 5x Elementarluft. Die Schriftrolle erhält man zufällig aus den Entschlüsselten Ausschnitten des \"Wahren Glaubens\" von [[Ortell der Einsiedler|Ortell dem Einsiedler]] in [[Silithus]]. \r\n==Fähigkeiten==\r\nDer Fürst der Stürme verfügt über folgende Fähigkeiten\r\n* '''Blitzschlagwolke''' - Dieser Zauber lässt eine Blitzschlagwolke entstehen, die 14 Sekunden anhält und allen Feinden im ausgewählten Gebiet 788 bis 1012 Naturschaden und alle 2 Sekunden 963 bis 1237 zusätzlichen Schaden zufügt. \r\n* '''Flügelschlag''' - Der Flügelschlag trifft Feinde in einem kegelförmigen Bereich vor dem Zaubernden und stößt sie zurück. \r\n* '''Gabelblitzschlag''' - Der Gabelblitzschlag fügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden Naturschaden zu.",},
			["Fürst der Tiefen"] = { content = "(engl. Duke of Fathoms)\r\nDer Fürst der Tiefen ist einer der Elementaren Adligen des [[Abyssischer Rat|Abyssischen Rates]], der an einem der [[Windsteine]] in [[Silithus]] mit Hilfe des [[Siegel der Anrufung]] (Wasser) beschworen werden kann.",},
			["Fürst Hydraxis"] = { content = "'''Fürst Hydraxis''' ist der Führer der [[Hydraxianer|Hydraxianischen Wasserlords]] und ein Diener von [[Neptulon]] dem Gezeitenjäger, der die Sterblichen anstiftet, andere Elementare zu töten. Er enthüllt, dass das \"reine\" Element des Wasser die Schlacht gegen die anderen Elemente sucht und willig ist, die Sterblichen gegen einen ihrer größten Feinde kämpfen zu lassen: [[Ragnaros]] den Feuerfürsten im [[Geschmolzener Kern|Geschmolzenen Kern]].",},
			["Fürst Incendius"] = { content = "#REDIRECT [[Lord Incendius]]", redirect = "Lord Incendius",},
			["Fürst Nicholas Zverenhoff"] = { content = "'''Fürst Nicholas Zverenhoff''' in der [[Kapelle des hoffnungsvollen Lichts]] in den [[östlichen Pestländern]] ist einer der angesehensten Anführer der [[Argentumdämmerung]] und ein brillanter Sprachwissenschaftler.",},
			["Für das Licht!"] = { content = "'''\"Für das Licht!\"''' ist der Titel eines Buches welches von [[Jennre Weisensänger]] an [[Uther Lichtbringer]] gewidmet wurde. Man erhält es von [[Wagner Hammerschlag]] außerhalb von [[Eisenschmiede]], wenn man zum [[Erntedankfest]] eine Opfergabe an [[Uthers Grabmal]] in den [[Westlichen Pestländern]] niederlegt. \r\n==Inhalt==\r\nSein Name brachte Licht ins dunkelste Azeroth. Sein Mut riss die Mauern des Elends ein. Die Silberhand hat niemals besser daran getan als der Welt den Ritter zu geben, der sich selbst aufopfern würde. Sein Ruhm war nicht der, den er erwünschte, auch nicht die Herrschaft über sein Volk wollte er. Stattdessen wählte er für Lordaeron zu kämpfen. Hoffend, dass sein Volk es nie wieder müsste. Die tragische Geschichte dieses so heiligen Ritters wird niemals mit seinem gottlosen Tod enden. Wir verehren ihn und danken ihm! Uther wird für immer Ruhm und Licht erfahren.",},
			["Gadem"] = { content = "#REDIRECT [[Gadem Rotstaub]]", redirect = "Gadem Rotstaub",},
			["Gadgetzan"] = { content = "Gadgetzan ist die Hauptstadt des [[Dampfdruckkartell]]s und die Heimat der besten [[Ingenieure]], [[Alchimist]]en, wie z.B. [[Alchimist Stößelbruch]] und Händler, die die [[Goblins]] zu bieten haben. Die Wasserknappheit ist hier ein großes Thema und da die [[Wüstenläufernomaden]] die Brunnen erobern, müssen die [[Goblins]] weitere freie Wasserquellen ausschöpfen. Darum kümmert sich die [[Gadgetzan Water Company]]. Wenn man den Friedhof außerhalb von Gadgetzan besucht besucht, findet man dort einen Grabstein. Dieser hebt sich von all den anderen ab. Geheimnisse liegen darin verborgen. \r\n==Persönlichkeiten==\r\n* [[Alchimist Stößelbruch]]\r\n* [[Chefingenieur Bilgenritzel]]\r\n* [[Marin Noggenfogger]]\r\n* [[Mux Manamix]]\r\n* [[Trenton Lichthammer]]\r\n* '''Andi Lynn''' - Andi Lynn möchte, dass man das Truppenlager der [[Oger der Dünenbrecher]] vernichtet und [[Gor'marok der Verheerer|Gor'marok den Verheerer]] tötet.\r\n* '''Curgle Kurbelhüpf''' - Die Goblindame Curgle Kurbelhüpf hat etwas erfunden, das Bilder einfangen kann: den [[Superschnapper FX]]. \r\n* '''Dirge Schnetzelhack''' - Dirge Schnetzelhack ist Metzger und ein hervorragender Koch. Muschelette ist sein neuestes kulinarisches Meisterwerk, aber er kennt viele ausgefallene Rezepte und weiß um eine Legende, wonach die [[Chimaerok]] von der [[Insel des Schreckens]] in [[Feralas]] das saftigste und zarteste Fleisch weit und breit haben und die [[Chimaerok]] haben ein Familienoberhaupt, das nach entsprechender Zubereitung wie ein 500 Pfund-Hühnchen aussehen könnte. Für Dirges Chimaerokkoteletts wird allerdings ebenso Goblinraketentreibstoff und Tiefsteinsalz gebraucht.\r\n* '''Krinkle Goldstahl''' - Krinkle Goldstahl erwartet eine Lieferung für seinen Schmiedekunstbedarf von [[Locheed]] aus der [[Sengende Schlucht|Sengenden Schlucht]]. Er geht mit seinen Fertigkeiten bei den höchsten Bietern in Gadgetzan, in der [[Tanaris]]wüste, hausieren und dürfte der Einzige sein, der die Form für denn [[Skelettschlüssel]] für die [[Scholomance]] herstellen kann ... und seine Dienste werden nicht billig sein.\r\n* '''Leitender Feldmesser Rutenwünschel''' - Der Leitende Feldmesser Rutenwünschel gehört zur [[Gadgetzan Water Company]] und hat einen offenen Posten im Rang eines temporären Unterfeldmessers in der [[Gadgetzan Water Company]]. Es gibt Wasser in der Wüste, aber nur für die, die klug genug sind, sie erst zu erforschen. Dafür nimmt man einen [[Wünschelrutenapparat]] und zapft damit eine Wasserprobe vom Teich in der Nähe der [[Sandmarterwache]]. Er hat seinen besten Gehilfen, [[Unterfeldmesser Kieselschliff]], in die Wüste südöstlich von Gadgetzan geschickt. Das ist ein Gebiet, das sie die [[Klaffende Schlucht]] nennen. \r\n* '''Leitungshahnmaschinist Lochbeutel''' - Leitungshahnmaschinist Lochbeutel gehört zur [[Gadgetzan Water Company]] und bietet ein offizielles Care-Paket Modell 103-XB für jeweils fünf Wasserbeutel eines [[Wüstenläufernomaden]], die man abliefert.\r\n* '''Sprinkle''' - Sprinkle ist eine tolle Küchenchefin, sowie eine Freundin von [[Marin Noggenfogger]] und [[Umi Rumpelkicher]]. Als sie noch ein kleines Mädchen war, hat ihre Schwester immer gekocht. Es war grauenhaft. Manche ihrer 'Gerichte' konnte sie kaum runterwürgen - bis sie irgendwann eine 'Geheimzutat' entdeckt hat - einen Pilz namens [[Violetter Tragan]]. Diesen Tragan empfiehlt sie [[Marin Noggenfogger]] für ihren [[Disteltau]].\r\n* '''Tran'rek''' ist immer auf der Suche nach neuen Methoden, um schnelles Gold zu verdienen. Die Skarabäen von [[Tanaris]] haben sehr harte Panzerschalen. Hart genug, um sie als Baumaterial für eine Menge Dinge zu verwenden. Er möchte in das [[Disteltal]] hinein, aber solange es dort von [[Distelwandler]]n wimmelt, kehrt er auf keinen Fall dorthin zurück.",},
			["Gaea-Samenkorn"] = { content = "Man findet die Gaea-Samenkörner nur im [[Steinkrallengebirge]], nördlich von [[Sonnenfels]] am [[Mirkfallonsee]], in der Nähe des Ufers. Sie werden u.a. von den [[Druiden]] dazu verwendet, um das [[Verbrannte Tal]] wieder zu begrünen.",},
			["Gahrrons Trauerfeld"] = { content = "'''Gahrrons Trauerfeld''' liegt von der [[Zugwindspitze]] aus im Nordosten der [[Westliche Pestländer|Westlichen Pestländern]], etwa dort, wo die [[Östliche Pestländer|Östlichen Pestländer]] beginnen. Es ist ein ehemaliger Hof, der von der Geißel überrannt und zum Standort für einen [[Geißelkessel]] wurde. Einige der stärkeren Diener der [[Geißel]] bewachen ihn nun, um genau zu sein [[Gespenst]]er und [[Geist]]erscheinungen.",},
			["Gahz'ranka"] = { content = "Die [[Hydra]] '''Gahz'ranka''' lebt in [[Zul Gurub]] und kann mit Hilfe der Köder von [[Nat Pagle]] gefangen werden. \r\n==Beschwörung==\r\nUnd so gehts:\r\nIn [[Zul'Gurub]], im Süden von [[Hohepriesterin Arlokk]] am Flußufer, ist ein verlassenes Lager mit einem Haufen umgekippter Gefäße und Stühle. Einer davon enthält ''Nat Pagle’s Maßband''. Nehmt dieses Band und bringt es zu [[Nat Pagle]] in den [[Düstermarschen]] zurück. Danach kann man einen Matschstinkerköder kaufen. Betretet Zul'Gurub mit einem Matschstinkerköder und schaut im Wasser nach einem „Schlammigen Aufgewühlten Wasser“. Angelt in diesem Teich mit einer Angeln-Fertigkeit von mindesten 350 und fangt 5 Zulianische Matschstinker. Schaut nach Osten von [[Hohepriester Thekal]] zu ''Nat Pagle's Angelpunkt'' im Wasser. Benutzt den Köder an diesem Ort und Gahz'ranka wird beschworen werden. Diese Stelle ist praktisch, da beim Schleudern alle sanft im Wasser landen. Dann wird Gahz’ranka „geangelt“. Nach kurzer Antankphase ist maximaler Schaden angesagt.",},
			["Gahz'ridian"] = { content = "'''Gahz'ridian''' findet man in [[Tanaris]]. Vor langer Zeit, als Trolle Tanaris besetzt hielten, schufen sie eine große Anzahl von Ornamenten nach dem Vorbild der [[Gahz'rilla]], einer [[Hydra]], die sie als Göttin verehrten. Diese Ornamente werden aus einem Element herausgeschnitzt, das nach der Hydragöttin \"Gahz’ridian\" genannt wird. Noch immer kann man diese Ornamente unter dem Wüstensand in ganz [[Tanaris]] finden.",},
			["Galaxis"] = { content = "Der [[Fürst der Leere]] '''Galaxis''' beherrscht den [[Leerengrat]] auf der [[Höllenfeuerhalbinsel]] im Osten hinter [[Zeth'Gor]]. Es ist ein schrecklicher Ort direkt am Abgrund, der von diesem [[Leerwandler]] beherrscht wird. Mittels eines [[Sphärenrissgenerator]]s kann man Galaxis in der Nähe der Steine der Leere rufen.",},
			["Galen Trollbann"] = { content = "'''Prinz Galen Trollbann''' ist der Sohn von [[Thoras Trollbann]] und hält sich tief innerhalb von [[Burg Stromgarde]] auf, in einer Kapelle in den von der Miliz bewachten Distrikten. Prinz Galen wird gut bewacht und ist selbst ein ausgezeichneter [[Krieger]].",},
			["Gallant"] = { content = "An der Küste von [[Desolace]], bei [[Ethel Rethor]] befindet sich das Schiffswrack der \"[[Gallant]]\". Der Kapitän [[Ulysses Rackmore]], hat sein Logbuch am Strand verborgen, welches den glücklichen Finder zu Rackmores Schatztruhe führt. Er schrieb es in der Hoffnung, dass jemand von seiner Not erfährt und eines Tages Rache an diesen Scheusalen aus dem Meer nehmen wird, die den Untergang von ihm, seiner Mannschaft und seinem Schiff bedeuteten. \r\n==Hintergrund==\r\nDie Gallant war mit einer Lieferung Vorräte unterwegs zur [[Mondfederfeste]], als [[Naga]] das Schiff angriffen. Die Besatzung konnte den Angriff abwehren, aber sie wußten, dass die Naga zurückkommen würden. Da Rackmore den Verlust seiner wertvollen Besitztümer fürchtete, segelte er die \"Gallant\" zur [[Insel Ranazjar]] und versteckte dort seine Schatztruhe. Nach dem Angriff wußte die Besatzung, dass die Gallant\" keinem weiteren Angriff standhalten würde. Und so gaben die wenigen überlebenden Matrosen und Rackmore das Schiff auf. Sie befinden sich nun am Strand und werden bald in Richtung Stadt [[Nijelspitze]] aufbrechen, doch sie wissen, dass große Gefahren zwischen ihnen und dieser Zuflucht liegen, und Rackmore fürchtet, dass Desolace sie verschlingen wird.",},
			["Gamaschen von Arcana"] = { content = "Die '''Gamaschen von Arcana''' sind neben der [[Brustplatte des Blutdurstes]] und der [[Kappe des scharlachroten Wissenden]] eines der Glanzstücke für [[Druiden]] aus Malyfous’ Katalog. Wenn die Herstellung eines solchen Gegenstandes auch noch nie erfolgreich bewerkstelligt wurde, so wird sie doch von [[Malyfous Düsterhammer]] in der [[Ewige Warte|Ewigen Warte]] von [[Winterquell]] für möglich erachtet - unter den richtigen Umständen. \r\n==Zutaten==\r\nSollte der Sucher des Arkanums wünschen, Gamaschen mit immenser Kraft magiezuerfüllen, so muss er die gewünschten Zutaten suchen und zu [[Malyfous Düsterhammer]] in der [[Ewige Warte|Ewigen Warte]] bringen: \r\nDer zukünftige Träger muss außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.\r\n==Links==\r\n* bei",},
			["Gan'arg"] = { content = "Die gewieften '''Gan'arg''' sind verkrüppelte [[Mo'arg]] und stehen genau wie ihre Vettern als Ingenieure im Dienste der [[Brennende Legion|Brennenden Legion]], wo sie mit ihrer schnellen Auffassungsgabe an ständig neuen Entwicklungen in den [[Konstruktionslager]]n arbeiten.",},
			["Garadar"] = { content = "'''Garadar''' ist das Zuhause der [[Mag'har]], im Süden von [[Nagrand]]. Sie haben ein paar Leute dort, aber es sind nur wenige, und die [[Mag'har]] werden von allen Seiten von Feinden angegriffen. Die Bevölkerung Garadars ist ein Teil der [[Horde]] und stolz, ihr Blut für ihre Verteidigung vergießen zu dürfen. Auch wenn sie ein friedvolles Leben suchen, haben sie doch viele Feinde und unter diesen Feinden gibt es keinen, der so viel rohe Macht besitzt, wie die [[Oger]]. \r\nSchon seit Jahrzehnten kämpfen sie gegen die anderen [[Orcs]] aus Nagrand, aber nun ist mit den [[Oger]]n eine neue Bedrohung aufgetaucht. Ohne Führung sind sie von allen Seiten angreifbar und sie haben in den letzten Wochen viele Freunde verloren. Obendrein haben sie vor ein paar Tagen einen Begräbniszug zum Ahnengrund geschickt, der noch nicht zurückgekehrt ist. Selbst jeder kräftige Blutelf, der eine Waffe führen oder einen Zauber wirken kann, ist hier willkommen. Doch diese [[Orcs]] haben noch nie zuvor einen Tauren gesehen und wenn [[Hauptmann Kroghan]] nicht wäre, würden sie [[Ohlorn Fernreiser]] wahrscheinlich zum Abendessen verschlingen.\r\n==Persönlichkeiten==\r\n* [[Garrosh Höllschrei]]\r\n* [[Großmutter Geyah]]\r\n'''Sonstige'''\r\n* '''Elementarist Yal'hah''' - Elementarist Yal'hah vom [[Irdener Ring|Irdenen Ring]] ist nach Garadar gekommen, um die [[Mag'har]] über den Status der Elemente zu informieren. \r\n* '''Jorin Totauge''' - Jorin Totauge zieht in den Kampf gegen die [[Oger der Felsfäuste]]. Garrosh ist vielleicht bereit dazu, die Hände in den Schoß zu legen und die [[Oger]] ihr Land übernehmen zu lassen, aber er ist es nicht. Er möchte, dass man Lantresor davon überzeugt, die Felsfäuste zurückzuziehen. \r\n* '''Kroghan''' - Kroghans ursprünglichen Befehle sahen vor, dass er für kurze Zeit in Garadar bleibt und er sich anschließend bei Blutwache Gulmok im Dorf Schattenmond im [[Schattenmondtal]] melden sollte. In seiner Zeit hier ist ihm klar geworden, dass Garadar von einer langfristigen Zusammenarbeit mit der [[Horde]] profitieren würde. \r\n* '''Matrone Drakia''' - Matrone Drakia muss sich um viele Dinge kümmern, besonders seit die Großmutter krank ist. \r\n* '''Mystiker Elakay'gan''' - Mystiker Elakay'gan möchte, dass man eine Schlachtstandarte der [[Mag'har]] an den Scheiterhaufen der [[Brennende Klinge|Brennenden Klinge]] aufstellt. Die Standarten werden einen bleibenden Eindruck bei den [[Oger der Totschläger|Ogern der Totschläger]] dort hinterlassen, die die Schlacht verpasst haben. \r\n* '''Ohlorn Fernreiser''' - Ohlorn Fernreiser ist ein herausragender [[Tauren Jäger]] und gehört zu [[Nesingwarys Expedition]]. \r\n* '''Seherin Nakha''' - Seherin Nakha hatte eine höchst ungewöhnliche Vision, auf die sie sich keinen Reim machen kann. Sie sah einen gigantischen Pfeil, der sich auf einem Feuerschweif gen Himmel erhob. Für einen geübten Magier wäre es ein Leichtes etwas derartiges zu erschaffen, doch ein Gefühl sagt ihr, dass dieses Objekt nicht das Produkt von [[Magie]] ist. Es wird anders sein, als alles, dass die Völker von [[Azeroth]] je erschaffen haben.\r\n* '''Weissager Corhuk''' - Weissager Corhuk sucht den verschollenen Kriegstrupp von Garadar und fragt sich wie die verschollenen jungen [[Orcs]] erwarten konnten, diese Wilden des [[Finsterblutstamm]]es besiegen zu können?\r\n* '''Weissager Kurkush''' - Weissager Kurkush möchte, dass man ihm Finsterblutgötzen bringt, denn die [[Mag'har]] müssen zurückschlagen und dem [[Finsterblutstamm]] zeigen, das sie ganz und gar nicht machtlos sind.\r\n* '''Weissager Margadesh''' - Weissager Margadesh ist davon überzeugt, dass man den Anführer der Finsterblut töten muss und will deshalb den Kopf von [[Ortor von Finsterblut]].",},
			["Gargoyle"] = { content = "Die furchteinflößenden '''Gargoyles''' von [[Nordrend]] sind gefräßige, fliegende Bestien, die das Gemetztel und Verwüstung lieben. Sie werden in einer [[Gruft]] belebt und folgten den untoten Armeen des [[Lichkönig]]s von Norden her, wie Geier einem verwundetem Tier. Diese seltsamen, drahtigen Flieger haben eine eiskalte, feste Haut, welche sie vor Angriffen beschützt. Wenn sie schwer verwundet sind, können Gargoyles landen und ihre eiskalte Haut zu einer felsartigen Masse kondensieren lassen. In dieser „Steingestalt“ sind sie zwar bewegungsunfähig sich zu bewegen, ihre Wunden heilen jedoch schneller. Ein mächtiger [[Zauberer]] kann einen Gargoyle an sich binden und ihn lenken.\r\nIn der Armee der Geißel dienen sie häufig als Wächter, in dem sie sich in ihre Steingestalt verwandeln und erst erwachen, wenn ein Lebender sich nähert. Auch werden sie oft gegen Späher oder Boten eingesetzt. Ansonsten sind sie recht wiederstandfähig und verfügen über verschiedene Angriffsstärken im Nah- und Fernkampf... Ob Gargoyles untot sind oder nicht, ist umstritten. Jedoch zeigen sie die gleiche Schwäche gegen Zauber wie \"Heiliges Licht\" auf, wie normale Untote.\r\n==Persönlichkeiten==\r\n* [[Kirtonos der Herold]]",},
			["Garithos"] = { content = "'''Garithos''' war ein [[Menschen Ritter]] und befehligte als General die Truppen der Allianz während der Invasion der [[Geißel]] in [[Lordaeron]]. Dieser Mensch besaß ein unumstrittenes militärisches Talent, aber er hatte auch einen autoritären und verachtenden Charakter. Diese Fehler ließ die letzten Hoffnungen der [[Allianz]] auf eine Wiedervereinigung mit den [[Blutelfen]] schwinden: nachdem er Prinz [[Kael'thas Sonnenwanderer]] für den Verrat mit den [[Naga]]s eingesperrt hatte, entkam dieser und flüchtete in Richtung [[Draenor]]. Danach geriet Garithos unter den Einfluß des Schreckenslords [[Detheroc]], um [[Sylvanas Windläufer]] und ihre Verlassenen zu bekämpfen. Das hinderte den General allerdings nicht daran, wiederum mit [[Sylvanas Windläufer]] und den [[Verlassene]]n einen Pakt einzugehen, als die dunkle Fürstin ihn mithilfe der geistigen Kräfte von [[Varimathras]] den General auf ihre Seite zog, um die Festung von [[Balnazzar]] zu belagern. Nach dem Sieg befahl die Dunkle Fürstin dem Dämon [[Varimathras]] allerdings, Garithos zu exekutieren ...",},
			["Garr"] = { content = "'''Garr''' ist gegenwärtig das mächtigste [[Lava-Elementar]] in [[Azeroth]] und einer von [[Ragnaros]]’ höchsten Offizieren. Er besteht aus extrem harten Lavagestein und seinen Augen glühen durch das heiße Feuer, das in ihm brodelt. Er wird von acht Wächtern umgeben.\r\n===Hintergrund===\r\nGarr war immer ein hilfreicher Verbündeter für [[Ragnaros]] den Feuerlord und er half ihm mit [[Baron Geddon]], der ebenfalls ein Offizier des [[Ragnaros]] ist, [[Prinz Donneraan]], den Sohn des [[Al'Akir]], in eine Falle zu locken und ihn zu besiegen. [[Ragnaros]] sog ein Teil der Energien des riesigen [[Luftelementare|Sturmelementars]] in sich hinein, doch es gelang ihm nicht, Donneraan vollends in sich aufzunehmen. Daher stellte [[Ragnaros]] einen Talisman her und zerteilte diesen danach, um dieses mächtige Artefakt in die Obhut seiner Vertrauten [[Baron Geddon]] und Garr zu geben.",},
			["Garrens Schlupfwinkel"] = { content = "'''Garrens Schlupfwinkel''' befindet sich in [[Tirisfal]] nördlich des Friedhofes von [[Brill]]. Die Massengräber südwestlich von Garrens Schlupfwinkel wurden geschaffen, um der eindrucksvollen Anzahl Todesfälle gerecht zu werden, die Tirisfal erlitt, als die Seuche zum ersten Mal über das Gebiet kam. Den Toten in diesen Gräbern blieb der Untod bisher erspart, aber die [[Geißel]] schickt jetzt die [[Gnolle der Moderfelle]], um die Leichen einzusammeln und sie zur Verstärkung ihrer Armeen einzusetzen. Die Flora in der Nähe des Massengrabs wird von [[Verdammniskraut]] verseucht.",},
			["Garrick Padfoot"] = { content = "#REDIRECT [[Garrick Schleichfuß]]", redirect = "Garrick Schleichfuß",},
			["Garrick Schleichfuß"] = { content = "'''Garrick Schleichfuß''' hält die Weinberge von [[Nordhain]] im [[Wald von Elwynn]] unter der Kontrolle der [[Defias]] Bruderschaft. Er ist ein Dieb und Halsabschneider, der schon seit Wochen den Bauern und Händlern im [[Wald von Elwynn]] das Leben schwer macht. Aktuell wurde er bei einem Schuppen in der Nähe der Weinberge in [[Nordhain]] gesehen. Garrick hat eine Bande von Rohlingen der [[Defias]] um sich versammelt, also wird man nicht leicht an ihn herankommen.",},
			["Garrosh Höllschrei"] = { content = "'''Garrosh Höllschrei''' ist der Sohn von [[Grom Höllschrei]]. Er lebt momentan in [[Garadar]] in [[Nagrand]], doch er ist in Melancholie verfallen und glaubt, dass die Zeit der [[Mag'har]] abgelaufen ist. Man hat ihm mehr als alles andere gezeigt, dass er nicht in der Lage ist, diese Leute anzuführen. Zu stark ist der Fluch seines Blutes und er kann nicht der nächste Höllschrei sein, der die Orcs in die Verdammnis führt. Erst die Worte des totgeglaubten Sohn von [[Durotan]], [[Thrall]], öffnen ihm die Augen und geben dem jungen Garrosh neuen Mut. Allerdings sieht er seine Zukunft nicht mehr in der zerschmetterten Welt. Sein Weg wird ihn weiterführen...\r\n==Vorschau==\r\nGarrosh Höllschrei und seine orcischen Streitkräfte brechen in [[Wrath of the Lich King]] nach [[Nordend]] auf und treffen dort in der [[Boreanische Tundra|Boreanischen Tundra]] auf die rätselhaften [[Taunka]]. Der wagemutige Garrosh errichtete in dieser verschneiten Landschaft die robuste orcische [[Kriegshymnenfeste]].",},
			["Gasthaus \"Zur süßen Ruh\""] = { content = "Die Menschen bauten einst ein Gasthaus am Übergang der [[Düstermarschen]] ins [[Brachland]], das '''Gasthaus „Zur süßen Ruh“''', so nannten sie es. Doch vor Wochen wurden es niedergebrannt. \r\nDer Kriegshäuptling [[Thrall]] sagte den stationierten Orcs in [[Brackenwall]], dass sie die Menschen in Ruhe lassen sollten, solange sie die Grenzen nicht überqueren, aber offenbahr handelte jemand seinem Wunsch zuwider. Nun hat Thrall [[Krog]] in Brackenwall den Auftrag gegeben, der Sache auf den Grund zu gehen. \r\nDas Gasthaus liegt nun abgebrannt in Trümmern. Reihen von Hufspuren führen von den noch rauchenden Überresten des Gebäudes weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen. Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus \"Zur süßen Ruh\" war. Der Schild lässt sich von den Mauersteinen des Kamins ablösen. Der Ledergurt an der Rückseite muss verbrannt sein, aber er war offenbar für eine große Person gemacht, z.B. für einen [[Tauren]]. Am Rand des Schildes steht etwas geschrieben, aber durch die Brandspuren kann man es kaum lesen. Es sieht aber wie der Name [[Mosarn]] aus.",},
			["Gazlowe"] = { content = "Gazlowe ist ein berühmter [[Goblin]]-Karawanenhändler und sponsort das Rennwagenteam der [[Goblins]] in der [[Schimmernde Ebene|Schimmernden Ebene]]. Er wünscht, Vize-Admiral [[Grezzlik]] würde bessere Arbeit bei der Sicherung der Meere für die Handelsschiffe leisten, denn bei all dem Gold, das die Handelsbarone in die Handelsflotten gesteckt haben, macht es ihn rasend zu sehen, wie viele Piraten unbehelligt unterwegs sind, seine Schiffe überfallen und seine Waren stehlen.",},
			["Gebirgsjäger"] = { content = "#REDIRECT [[Zwergenjäger]]", redirect = "Zwergenjäger",},
			["Gebirgsjäger Wellart Gerstenbräu"] = { content = "Gebirgsjäger Wellart Gerstenbräu ist [[Gebirgsjäger]] und im südlichen Wachturm am [[Südtorpass]] in [[Dun Morogh]] stationiert, einem von zwei Türmen an der Grenze zum [[Loch Modan]]. Er mag vielleicht kein Bierbrauer sein wie der Rest der Gerstenbräus, aber er trinkt gern mal einen, und er wird ein Fass mit Schimmerstarkbier mögen. Wenn er genug getrunken hat, will er auch [[Gebirgsjäger Kadrell]] diesen Genuß gönnen. [[Schimmerstarkbier]] ist großartiges Zeug!",},
			["Gebirgspass der Totenwinde"] = { content = "Zwischen den düsteren Waldgebieten des [[Dämmerwald]]es und den [[Sümpfe des Elends|Sümpfen des Elends]] liegt eine karge Felslandschaft. Wer auf dem Hauptweg bleibt und geradeaus schaut, wird keinen Gegner erblicken. Doch auf den Seitenwegen lauert die Gefahr ... Und wer den Fehler macht sich nach Süden zu wenden der erblickt dort [[Karazhan]], die einstige Heimat von [[Medivh]]. Schroffe Granitfelsen türmen sich in diesem versteinerten Gebiet auf. Es ist ein karges Land, gänzlich ohne Leben. Allerdings war dies nicht immer so...\r\n[[Medivh]], der letzte Wächter, hatte den Turm von [[Karazhan]] am Pass der Totenwinde zu seiner Heimat gemacht. Obwohl er der größte Magier seiner Zeit war, war er vom dunklen Geist [[Sargera]]s’ besessen. Mit Medivhs Hilfe öffnete [[Sargeras]] das [[Dunkle Portal]] und ermöglichte es den [[Orcs]] [[Azeroth]] anzugreifen. Im Laufe des Krieges setzte sich Medivh gegen [[Sargeras]] Kontrolle zur Wehr, doch der in ihm tobende Konflikt trieb den [[Magier]] schließlich unwiderruflich in den Wahnsinn. Sein einstiger Freund aus Kindheitstagen, [[Anduin Lothar]], ahnte, dass etwas mit Medivh nicht stimmte. Mit der Hilfe von [[Khadgar]], dem jungen Lehrling Medivhs, erstürmte [[Anduin Lothar]] den Turm von [[Karazhan]] und tötete seinen ehemaligen Freund. Seit diesem Tag lastet ein schrecklicher Fluch auf dem Turm und den umliegenden Ländern, gleich einem dunklen Mantel, der sich vom Gebirgspass der Totenwinde bis hin in die Lande zieht, die heute als [[Dämmerwald]] bekannt sind.\r\nDoch auch welch großartige Erkenntnisse mögen wohl unter der Asche des Gebirgspass der Totenwinde liegen, die nur darauf warten, entdeckt zu werden. \r\nAußerhalb von Karazhan wimmelt es nur so von Geistwesen. Der Grund ihrer Existenz ist unbekannt und auch die Aufzeichnungen von [[Erzmagier Alturus]] verheißen nichts Gutes. Karazhan sollte alle möglichen arkane Ströme ausstrahlen... stattdessen herrscht dort nun ein riesiges Energievakuum. Keine Signale. Nichts. Außer einem sehr schwachen dämonischen Echo. Die [[Kirin Tor]] dachten, es sei ein schlechtes Zeichen, als [[Karazhan]] sich von der Umwelt abgeschottet hat. Sie hatten dort Agenten, von denen sie nie wieder gehört haben. Und nun diese... dämonische Strömung. Sie müssen das untersuchen, doch die Einzigen, die [[Karazhan]] wieder öffnen könnten, hielt man für tot: [[Khadgar]] und Medivh. Während sie hoffen, das Letzterer tatsächlich tot ist, haben sie kürzlich in Erfahrung gebracht, dass sein Lehrling, [[Khadgar]], gesund und munter an einem Ort namens [[Shattrath]] lebt.\r\n==Keller des Meisters==\r\nMan hat sowohl von einem unterirdischen Teich als auch von einem Brunnen in einem Keller unter [[Karazhan]] gehört. Dieser ganze Ort ist jedoch voll von Geistern.\r\n==Personen==\r\n* Erzmagierin Leryda\r\n* [[Erzmagier Alturus]]",},
			["Gedankenauge"] = { content = "Die Legenden berichten von einem Juwel, das tief im Herzen des [[Schlingendorntal]]s versteckt liegt. Man nennt es das '''Gedankenauge''' und es verfügt über große Macht. Es ist ein Artefakt, mit dem man andere Wesen verderben kann. \r\nWenn man dieses Auge findet, dann könnten die [[Trolle der Dunkelspeere]] im [[Basislager von Grom'Gol]] es vielleicht nutzen, um den verlorenen [[Yenniku]] aus der Dunkelheit zurückzubringen. Man benötigt außerdem die Magie von [[Pulsierende blaue Splitter|Pulsierenden blauen Splittern]], um dieses Artefakt seinem Willen zu unterwerfen. \r\nDas Gedankenauge befindet sich bei einem [[Oger]]magier, in den Tiefen des [[Ogerhügel der Mosh'Ogg]]. Sein Name ist [[Mai'Zoth]]. Er ist bösartig und seine Magie ist stark und wenn er im Besitz des Gedankenauges ist, dann ist seine Magie noch stärker. Er war es auch, der [[Colonel Kurzen]] verderbt hat. Bleibt Mai'Zoth am Leben, dann beeinflusst er vielleicht noch andere und vielleicht würde dann sogar ein zweiter Kurzen entstehen.",},
			["Gefallener Priester"] = { content = "#REDIRECT [[Menschenpriester]]", redirect = "Menschenpriester",},
			["Gefrorene Lichtung"] = { content = "Die '''Gefrorene Lichtung''' liegt im Norden des [[Der heulende Fjord|Heulenden Fjords]] und ist eine Heimstätte der [[Frostnymphen]]. Seit Generationen erzählen sich die [[Taunka]] Geschichten über Nymphen, die sich auf verborgenen Lichtungen in der Wildnis tummeln. Heutzutage muss man jedoch nicht mehr die Wälder durchkämmen, um sie zu finden. Sie haben sich aus unerklärlichen Gründen dazu entschlossen, ans Licht zu treten.",},
			["Gefährte"] = { content = "Spieler können ihre eigenen '''Gefährten''', ''Haustiere'', besitzen. Die kleinen Kerlchen sind zwar nur Dekoration und deswegen im Kampf auch wenig hilfreich, aber wer jemals einen süßen kleinen [[Drachenwelpling]] gesehen hat weiß, warum jeder ein Haustier haben sollte. Verlorene Haustiere und Reittiere können durch einen Besuch bei einem Stallmeister wieder erworben werden. \r\n==Beschreibung==\r\nHaustiere lassen sich für [[Haustierkämpfe]] in folgende Klassen einteilen: \r\n* ''Aquatisch'' - z.B. [[Kriecher]], [[Schildkröte]]n und [[Fisch]]e.\r\n* ''Drachen'' - z.B. die vielen [[Drachenwelpling]]e.\r\n* ''Elementar'' - z.B. die [[Pandarengeist]]er oder Mini-Elementare wie [[Kieselchen]].\r\n* ''Fliegend'' - z.B. [[Vögel]] und [[Motte]]n\r\n* ''Humanoid'' - z.B. [[Murloc]]s.\r\n* ''Kleintier'' - z.B. [[Hase]]n.\r\n* ''Magisch'' - z.B. der [[Astraler Begleiter|Astrale Seelenfänger]], [[Ekelhafter Schlammling]]\r\n* ''Mechanisch'' - diverse [[Konstrukt]]e, wie z.B. die [[Winzige wandelnde Bombe]] oder [[Lil'Smoky]].\r\n* ''Untot'' - z.B. [[Eiskaltes Händchen]] oder [[Fetisch aus Sen'jin]]\r\n* ''Wildtier'' - z.B. [[Katze]]n oder [[Raptor]]enjungtiere\r\n===Aquatisch===\r\n* \r\n* [[Kraken|Blutroter Oktopus]] - [[Kraken|Oktopus]]. Zone: Tiragardesund, Zuldazar. Verkäufer: Kapitänin Klarisa, Kapitänin Zen'taga. Kosten: 100 Seefahrerdublonen. \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n===Drachen===\r\n* \r\n* \r\n* [[Drachenwelpling|Bronzewelpling]] - Drop: ([[Invasion der Eisernen Horde]], [[Verwüstete Lande]]). \r\n* \r\n* \r\n* \r\n* \r\n* [[Grimmlingflitzer|Junger Grimmlingflitzer]] - [[Feendrache]] ([[Drachenwelpling]]). Drop: [[Grimmlingsflitzer]] in [[Feralas]].\r\n* [[Feendrachen|Junger Sonnenflitzer]] - [[Feendrache]] ([[Drachenwelpling]]). Zone: [[Winterquell]] (Höhle der Verzehrung).\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n===Elementar===\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* [[Feuerelementar|Sengender Flämmling]] - [[Feuerelementar]]. Enthalten in ([[Zen'Vorka]], [[Geschmolzene Front]]).\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n===Fliegend===\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* [[Wespe|Feuerstachelbrummer]] - [[Wespe]]. Beute von: [[Inselexpeditionen]].\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* [[Hippogryphen]]junges - [[World of Warcraft TCG]]: [[TCG Helden von Azeroth|Helden von Azeroth]] - .\r\n* \r\n* \r\n* \r\n* [[Minischwing]] - [[Vogel]]. Questbelohung [65]: \"\" ([[Wälder von Terokkar]]). \r\n* [[Netherrochen]]larve - Benötigt [[Himmelswache der Sha'tari]] (Ehrfürchtig). \r\n* \r\n* \r\n* \r\n* [[Pterrordaxjunges]] - [[Pteradon]]. Beruf: [[Archäologie]] ([[Fossile Artefakte]])\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* [[Huhn|Westfallhuhn]] - Quest: GLUCK! ([[Westfall]]).\r\n* \r\n===Humanoid===\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n===Kleintier===\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n===Magisch===\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* [[Gesichtslose|Zur'aj der Erschöpfte]] - [[Gesichtslose]]r. Zone: [[Dunkelküste (Kriegsfront)]]. Beute: Zwielichtprophet Graeme.\r\n===Mechanisch===\r\n* \r\n* [[Mechagnom|Aufziehgnom]] - Beruf: [[Archäologie]] ([[Zwergen-Artefakte]]).\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* [[Uralter Nestwächter]] - Beruf: [[Archäologie]] ([[Arakkoa-Artefakte]])\r\n* \r\n* \r\n===Untot===\r\n* \r\n* \r\n* \r\n* [[Fossiles Jungtier]] - [[Raptor]]. Beruf: [[Archäologie]] ([[Fossile Artefakte]]).\r\n* [[Frostwolfgeisterwelpe]] - [[Frostwolf]]. Beruf: [[Archäologie]] ([[Klans von Draenor-Artefakte]]).\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* [[Voodoostatuette]] - Beruf: [[Archäologie]], [[Troll-Artefakte]].\r\n===Wildtier===\r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* [[Raptor|Fußschlitzer der Zandalari]] - [[Raptor]]. Beute: [[Insel der Riesen]] (Dinomant der Zandalari).\r\n* [[Glimmernetzjungtier]] - [[Spinne]]. Zone: [[Untere Schwarzfelsspitze]]. Erbeutet: [[Mutter Glimmernetz]]. \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* \r\n* [[Terrorhorn]]jungtier - Beruf: [[Archäologie]] ([[Zandalari-Artefakt]]). \r\n* \r\n* \r\n* \r\n* \r\n* [[Worgwelpe]] - [[Gefährte (Wildtier)]]. Zone: [[Untere Schwarzfelsspitze]]. Erbeutet: [[Rüstmeister Zigris]].\r\n==Zubehör==\r\n* \r\n* \r\n* \r\n* \r\n-----",},
			["Geheimnisvolles Fossil"] = { content = "Dieses Geheimnisvolles Fossil, welches [[Ausgrabungsleiter Wirrbart]] in der [[Dunkelküste]] aus dem Boden seiner Ausgrabungstätte geholt hat, hat eine auffallende Ähnlichkeit mit einem anderen Fossil, das man einst in [[Eisenschmiede]] sah. Ein Archäologe namens [[Archäologe Magenbitter |Magenbitter]] aus dem [[Hafen von Menethil]] brachte es damals zur jährlichen Konferenz der [[Forscherliga]] mit. Er dachte, das Fossil besäße eine besondere Macht, die man irgendwie mit Hilfe des [[Stein von Relu]] freisetzen könnte.\r\n[[Ausgrabungsleiter Wirrbart]] will das Geheimnisvolle Fossil zur [[Forscherliga]] nach [[Darnassus]] schicken, damit es von [[Chefarchäologe Grauflaum]] untersucht werden kann.",},
			["Gehennas"] = { content = "'''Gehennas''' ist ein [[Flammenwandler]] im [[Geschmolzener Kern|Geschmolzenen Kern]]. Er dient als einer der Hauptmänner des Feuerfürsten [[Ragnaros]] und Gehennas Hand wird von [[Fürst Hydraxis]] als Beweis seines Todes verlang. \r\n==Fähigkeiten==\r\n* '''Feuerregen''' - Dieser Massenschaden tritt relativ häufig auf und betrifft ein begrenztes Gebiet. Daher ist es wichtig, dass der Raid sich gut im Raum verteilt hat. Wird man vom AoE-Regen betroffen, so bricht man alle laufenden Aktionen ab und begibt sich so schnell wie möglich aus dem Regen heraus, da dieser sehr viel Schaden verursacht.\r\n* '''Gehennas Fluch''' - Gehennas Fluch verringert 5 Minuten lang die Heileffekte von in der Nähe befindlichen Feinden um 75%. \r\n* '''Schattenblitz''' - Gehennas Schattenblitz schleudert einen Blitz aus dunkler Magie auf einen Feind und verursacht 2250 bis 2750 Schattenschaden.",},
			["Gehöft Bernruh"] = { content = "Nördlich der Straße in den Bergen des mittleren [[Dun Morogh]] liegt das Gehöft Bernruh mit ihrer bedeutenden [[Widder]]zucht. Sie bietet Reit[[widder]] an und erhofft sich Hilfe gegen Überfälle von [[Vagash]].\r\n* Rudra Bernruh möchte, dass man [[Vagash]] erschlägt und einen seiner Fangzähne zu man auf den [[Widder]]hof bringt.\r\n* Yarlyn Bernruh ist ein Kind und rennt hinter einem Hasen her. Bei ihm kann man einen Schneehasen erwerben. Die Langohren bringen übrigens gutes Gold beim Verkauf im neutralen [[Auktionshaus]], denn auch die [[Horde]] mag die kuscheligen Hoppler.",},
			["Geier"] = { content = "Geier gehören zu den [[Aasvogel|Aasvögeln]] und man findet sie überall im [[Brachland]], wo sie Aas suchen, von dem sie sich ernähren. Die gescheckten Aasfresser unterstützen, wie man weiß, von Zeit zu Zeit die bösen [[Harpyien]] – da sie von der Aussicht auf frisches Fleisch und Blut angelockt werden.\r\n'''Quelle:''' [[Warcraft III - Reign of Chaos]]",},
			["Geist"] = { content = "'''Geister''' sind hasserfüllte [[untote]] Kreaturen, die nicht der Kontrolle [[Ner'zhul]]s unterstehen. Diese Phantomkreaturen, die an Elementargeister gebunden sind, leben einzig und allein für Tobsucht und Zerstörung.\r\n==Persönlichkeiten==\r\n* [[Azshir der Schlaflose]]",},
			["Geisterhaus"] = { content = "Das '''Geisterhaus''' ist ein Ort der Besinnung, wo [[Schamane]]n und [[Medizinmänner]] der Trolle meditieren und ihre Beherrschung der geheimnisvollen Magien verbessern. Die Magier der [[Horde]] haben jeglicher Ausübung der [[Nekromant]]ie abgeschworen und andere Methoden entwickelt, gegen ihre Feinde zu kämpfen. [[Medizinmänner]] manipulieren Chemikalien im Körper und in der Umwelt, wohingegen [[Schamanen]] über die Kräfte der Natur gebieten.",},
			["Geisterlande"] = { content = "== Allgemeines==\r\nDie Geisterlande sind der südlichste Teil des [[Immersangwald]]es und gehören zu [[Quel'Thalas]]. Es ist die Region, die vom Angriff der [[Geißel]] am meisten Verwüstet ist und diese Lande tragen immer noch den Hauch der Verderbnis, der von den [[Pestländer]]n herüberweht. In ihm lauern viele Diener der [[Geißel]] und bedrohen jeden der sich unbedarft in den Wald begiebt. Der südliche Rand ist von der zweitgrößten Burg der [[Geißel]] besetzt und in seiner Mitte wartet der Verräter [[Dar'Khan Drathir]]. Gleich neben der Niederlassung der [[Geißel]] führt ein Pfad in die [[Östliche Pestländer|Östlichen Pestländer]]. Im Süden der Geisterlande findet man das Portal nach [[Zul Aman]].\r\n===Bündnis===\r\nDie Geisterlande werden von einem seltsam erscheinenden Bündnis aus [[Blutelfen]] und [[Verlassene]]n kontrolliert, einem angespannten Bündnis, das aus dem gemeinsamen Hass auf die [[Geißel]] heraus geboren wurde. Aber alles, was die [[Blutelfen]] in den Geisterlanden getan haben hatte nur ein Ziel: Die Rückeroberung all dessen, was rechtmäßig ihr ist. Schon zu lange hielt die Geißel diese Region in ihrem Würgegriff. Die Zeit der Abrechnung ist gekommen.\r\n===Flora und Fauna===\r\nDas Blut der Tiere südlich des Flusses ist verseucht. Die gesamte Fauna wurde von der Seuche befallen und man muss ihre weitere Ausbreitung stoppen. Um ein Heilmittel gegen die Seuche finden zu können, müssen die Bewohner von [[Tristessa]] verstehen, wie sie sich auf verschiedene Kreaturen auswirkt: von den komplexesten Lebensformen bis hin zu niedrigen Untergattungen. \r\n==Orte==\r\n* [[Enklave der Weltenwanderer]]\r\n* [[Katakomben der Amani]]\r\n* [[Sanktum der Sonne]]\r\n* [[Todesfestung]]\r\n* [[Todesschneise]]\r\n* [[Tristessa]]\r\n* [[Zeb'Tela]]\r\n===An'daroth===\r\nDie [[Blutelfen]] haben einige Schwierigkeiten mit einer Gruppe von [[Nachtelfen]], die erst kürzlich eine der naheliegenden Inseln besetzt hat. Sie haben ein kleines Lager an dem alten hochelfischen Leyliniennexus, An’daroth, im Nordwesten aufgeschlagen. Es gibt einen kleinen schlammigen Pfad, der hinter der Todesschneise dorthin führt. An'daroth liefert für die Spionage-Pläne der [[Nachtelfen]] nicht genügend Energie, um einen [[Mondkristall]] dort anzubringen. Keltus Dunkellaub hat vor, die Spione der Schildwache anzugreifen, möchte seine treue Begleiterin Tuschel aber als Vorhut vorausschicken. Sie braucht lediglich eine Fährte, die sie auf sie hetzt.\r\n===Andiliens Grund===\r\nMagister Kaendris hat Lehrling Vor'el entsandt, um die Gegend von aggressiven Wildtieren zu säubern. Sobald die Gegend sicher ist, wollen die Magister hier einen Außenposten gegen die [[Geißel]] errichten. Doch wenn er als Lehrling eines gelernt hat, dann ist das, Verantwortung zu delegieren, besonders bei solch lebensgefährlichen Unternehmungen. \r\n===An'owyn===\r\nAn'owyn ist ein alter hochelfischer Leyliniennexus, auf den ein nachtelfischer [[Mondkristall]] gesetzt wurde. \r\n===An'telas===\r\nAn'telas ist ein alter hochelfischer Leyliniennexus und liegt östlich von [[Tristessa]], auf dem südlichen Hang des Sonnenhügels, nordöstlich vom [[Sanktum der Sonne]]. Magister Sylastor führt dort diverse Experimente mit den Energien des Leyliniennexus durch, um potentielle Verwendungsmöglichkeiten im Kampf gegen die [[Geißel]] zu finden. \r\n===Elrendarsee===\r\nDer See im Norden wird seit langer Zeit von den Geistern der Ahnen heimgesucht. Die armen Seelen waren Opfer eines tragischen Unfalls, bei dem etliche von Ihnen am Grund des Sees ertranken. Die Ursache dieser Geschehnisse ist längst in Vergessenheit geraten, aber ihre quälenden Schreie erinnern noch heute an ihren Fluch. Jedes Jahr haben die Einwohner von Sonnenkuppe, an einem Ritual teilgenommen, um die verschiedenen Aspekte der Natur unter ihrer Kontrolle zu halten. Die Herrschaft über das Wasser wurde symbolisiert durch die Beschwörung und Versklavung eines [[Wasserelementar]]s namens [[Aquantion]]. Während des Rituals trugen sie wellenförmige Medaillons. Sie liegen nun auf dem Grund des Sees und man benötigt sie, um die Geister ihrer Kameraden zu befreien.\r\n===Goldnebel===\r\n'''Goldnebel''' ist eine kleine Ortschaft im Norwesten der Geisterlande und wurde von den Geistern der [[Hochelfen]] besetzt, die dort einst lebten. Sie wurde beim Krieg gegen die [[Geißel]] zum größten Teil zerstört. Heute ist die Ortschaft verlassen... sie ist fest in Hand der [[Geißel]] und es scheint dies eine der bevorzugten Taktiken zu sein, derer sich die Geißel bedient. \r\n===Grubenlichtmine===\r\nDie Grubenlichtminen im Südwesten wurden von den [[Gnolle der Schwarzpfoten|Gnollen der Schwarzpfoten]] überrannt. Man nimmt die Straße, die nach Süden aus Tristessa heraus führt, und hält sich rechts an der Wegzweigung. Kurz nach dem Ziggurat zur Rechten kommt ein kurzer Trampelpfad Richtung Westen. Diese Minen sind wichtig in strategischer Hinsicht für den fortwährenden Schlachtzug in den Geisterlanden. Man findet Grubenlichterz in den Zinn- und Kupfervorkommen, aber auch die Gnolle tragen es mit sich herum. Vor den Minen trifft man auf die Lehrling Shatharia. Sie wurde vom [[Sanktum der Sonne]] hierher geschickt, um ein paar Erzproben zu sammeln, aber die Gnolle haben diesen Ort überrannt. Ihr Kopf wird noch auf dem Präsentierteller landen, wenn sie diese Proben nicht bald zum Magister bringt. \r\n===Insel Shalandis===\r\nMan nimmt die Straße nach Westen aus [[Tristessa]] heraus in Richtung der Insel Shalandis. Sie liegt recht nah an der Küste. Die Schildwachen der Nachtelfen sind auf dieser Insel gelandet. Die direkten Maßnahmen, für die sich die Blutelfen entschieden haben, um herauszubekommen, was die Nachtelfen vorhaben, sehen grob zusammengefasst folgenden Ablauf vor: Man landet auf ihrer Insel und nimmt alles mit, das für sie von Interesse sein könnte. \r\n===Morgensternturm===\r\nDer Morgensternturm lieg nordöstlich der [[Enklave der Weltenwanderer]]. [[Dar'Khan Drathir]] verbrachte viel Zeit in den Gemäuern des Morgensternturms, verbarg sich dort viele Nächte lang und ersann finstere Machenschaften gegen sein eigenes Volk. Sein Tagebuch ist dort noch zu finden. und als man durch die Einträge blättert, bekommt man das unbestimmte Gefühl, beobachtet zu werden. Das Geschriebene beunruhigt einen. Dar'Khans Seele scheint erfüllt von Hass und Verachtung für sein eigenes Volk. Das ganze Ausmaß seiner Machenschaften und Intrigen wird auf diesen Seiten ausführlich beschrieben.\r\n===Sanktum des Mondes===\r\nDas Sanktum des Mondes liegt westlich von [[Tristessa]] und wird auch Vergessenes Sanktum genannt. Alle haben es vergessen. Es ist auch nicht mehr viel davon übrig und seine Energien haben merkwürdige Kreaturen erweckt.\r\n===Sonnenkuppe===\r\nDas Dorf Sonnenkuppe wurde von [[Neruber]]n überrannt. Ihre Anführerin ist Anok'suten und sie wandert in der Umgebung von Sonnenkuppe umher. Arkanist Vandril in Tristessa entsandte einen Späher hierher, um die Neruber zu besiegen. Er konnte aber nicht ahnen, dass die Neruber auf der Sonnenkuppe eine Anführerin haben. \r\n===Verseuchte Küste===\r\nDie [[Murlocs]] der Verseuchten Küste haben ihren freien Willen auch im Untotendasein erhalten.\r\n===Windläuferdorf===\r\nWindläuferdorf im Südwesten wurde von einer großen Armee aus den besten Sturmtruppen der [[Geißel]], Schemengeister und [[Gargoyles]] überrannt.\r\n===Windläuferturm===\r\nDer Turm befindet sich im Westen an der Küste und ist die ursprüngliche Residenz von Lady [[Sylvanas Windläufer]], Königin der [[Verlassene]]n und ehemaliger Waldläufergeneral der Elfen. Aber jetzt wurde der Turm von der [[Geißel]] überrannt. Um daorthin zu gelangen, folgt man der Straße nach Süden, bis man zu einer Abzweigung kommt. Dann wendet mach sich nach rechts, und geht weiter nach Südwesten, wenn man die [[Todesschneise]] überquert hat, dann kann man den Ort nicht verfehlen.\r\nEiner der gefallenen Waldläufer trägt die Halskette der Lady bei sich. Diese Halskette funkelt und ist ein bemerkenswertes Schmuckstück, das nicht der Schwermut der Geisterlande zu unterliegen scheint. Auf Grund der Inschrift und des Ortes, an dem man sie gefunden hat, muss es sich dabei um Eigentum von Lady [[Sylvanas Windläufer]] selbst handeln. Vielleicht wäre es am besten, sie zuerst zu Hochexekutor Mavren nach Tristessa zu bringen. Er scheint der höchstrangige Verlassene in der Gegend zu sein und weiß sicher, was zu tun ist.\r\n===Zeb’Nova===\r\nZeb’Nowa liegt, südlich der [[Enklave der Weltenwanderer]] und beherbergt die mächtigsten Verhexer und Pantherlords der Waldschattentrolle unter Führung ihres Häutplings Kel'gash dem Boshaften.\r\n===Zeb'Sora===\r\nZeb’Sora ist ein Dorf der Waldschattentrolle im Nordosten jenseits des Elrendarsees. Eine Gruppe von Waldläufern hatte den Auftrag, sich um die Waldschattentrolle von Zeb'Sora zu kümmern. Doch ihr Leutnant Tomathren hat den Angriff falsch geplant und sie haben hohe Verluste erlitten. Leutnant Tomathren hat sie einfach angreifen lassen, ohne sich vorher ein Bild über die taktische Lage zu machen und die Trolle lauerten bereits jenseits des Sees auf die [[Blutelfen]]. Durch seine Unfähigkeit wurden sie einfach dahingemetzelt. Kurz nach der Attacke ist er dann zusammengebrochen. Jetzt lagert er am Ufer des Elrendarsees im Süden von Zeb'Sora und ist nur noch ein plapperndes Mündel, denn er hat seinen Verstand verloren. Waldläuferin Valana befindet sich bei ihm und ist schwer verletzt. Doch sie wird bei dem Leutnant Tomathren bleiben, denn sie will Rache an den [[Waldtrolle]]n - Trollohren, damit sie sich eine nette Halskette anfertigen kann. \r\n===Ziggurate===\r\nIn den Geisterlanden befinden sich das blutende und das heulende Ziggurat. [[Dar'Khan Drathir]] versprach der [[Geißel]] zwei mächtige elfische Artefakte: Den Stein des Lichts und den Stein der Flamme. Beide waren durchdrungen von den magischen Energien des [[Sonnenbrunnen]]s und verfügten über mächtige Schutzkräfte gegen die [[Geißel]]. Man plante, die Kristalle zu den heutigen Standorten des heulenden und des blutenden Ziggurats, inmitten der Todesschneise, zu transportieren.",},
			["Geisterturm"] = { content = "Der '''Geisterturm''' ist ein Gebäude der untoten [[Geißel]]. Sind sie erst einmal von den rastlosen [[Geist]]ern der rachsüchtigen Toten erfüllt, stellen Geistertürme eine exzellente Verteidigung dar. Die [[Gespenst]]er des Turms greifen mit übernatürlicher Treffsicherheit an und füllen die Reihen der Toten rasch mit feindlichen Soldaten. Sind mehrere Türme in einer Stadt der Untoten, lässt das selbst den beherztesten Widersacher verzagen.",},
			["Geister des Schamanismus"] = { content = "Die Geister des Schamanismus sind die Wesenheiten, die ein [[Schamane]] rufen muss und die er um hilfe bitten muss, wenn er Magie wirken will.Sie sind nicht zu verwechseln mit den [[Elementare]]n der [[Elementarebenen]]. Die Geister sind eigenwillige Wesen und lassen sich nicht kontrollieren oder manipulieren. Wenn sie die Bitte eines Schamanen unziemlich finden, können sie ihm auch ihre Kräfte verweigern.\r\nEs gibt 5 Elementargeister, die Schamanen anrufen:\r\n'''Der Geist der Erde'''\r\nDie Erde ist das Fundament allen Lebens, die nährende Kraft, die die Tiere und Pflanzen gedeihen lässt. Die Erde ist das Element der geistigen und körperlichen Stärke und der Milde. Doch ihr Zorn kann verheerend sein.\r\n'''Der Geist der Luft'''\r\nDer Geist der Luft ist die Essenz das Fluges und der Winde. Die Luft ist überall enthalten, im Wasser, in der Erde, im Feuer und im lebendigem Körper.Die Luft ist nicht auf das Zerstören fixiert, doch auch ihr Zorn kann verheeren sein.\r\n'''Der Geist des Feuers'''\r\nDer Geist des Feuers ist der wildeste und undisziplienerste Geist.Sein Zorn kommt rasch und erstirbt genauso schnell wieder.Er ist die Essenz des Blitzes, der Wärme und der Flammen.Doch ist der Geist des Feuers auch hilfreich und freundlich.\r\n'''Der Geist des Wassers'''\r\nDer Geist des Wassers ist die Essenz der lebensspendenen Feuchtigkeit und der Kälte.Er löscht und lindert Schmerzen und Wunden und erhält so mit das Leben.\r\n'''Der Geist der Wildnis'''\r\nDer Geist der Wildnis ist die Essenz aller lebenden Wesen.Der Geist der Wildnis enthält alle je Gestorbenen und jemals geborenen Wesen.Durch den Geist der Wildnis kann ein Schamane mit den Tieren und Pflanzen sprechen und sogar Tote auferstehen lassen.Doch verweigert der Geist der Wildnis seine gaben jenen, die nur Profit für sich selbst suchen.",},
			["Geistwandler"] = { content = "Die taurischen Geistwandler sind Albinos. [[Tauren]] mit weissem Fell werden seit jeher bewundert, aber auch gemieden. Keiner ist gerne bei ihnen, obwohl sie den [[Tauren]] und [[Cairne Bluthuf]] ergeben sind. Die Geistwandler leben in der Wildniss und nur im Krieg kommen sie heraus und wirken ihre schamanistische [[Magie]], welche sie unsichtbar machen, Tauren wiedererwecken und Schmerzen teilen lassen kann. \r\nQuelle: Warcraft 3",},
			["Geistwandlerposten"] = { content = "Der Geistwandlerposten ist ein kleiner Stützpunkt der Horde im zentralen [[Desolace]], in der Nähe des Kodofriedhofs. Wenn man vom [[Verbranntes Tal|Verbrannten Tal]] im [[Steinkrallengebirge]] aus südwärts geht, sollte man dort vorbeikommen. Einst wurden die [[Orcs]] und [[Tauren]] hier von den [[Trolle]]n der [[Schattenflucht]] aus versorgt, doch der Geruch von gekochtem Fisch ist im Geistwandlerposten schon längst verschwunden.\r\n==Personen==\r\n* '''Felgur Zweischneid''' - Felgur Zweischneid ist ein [[Orc]], dessen Aufgabe es war, Informationen über die [[Zentauren]] zu sammeln. Er sagt, wenn man ihre Zahl dezimiert, schwächt man ihre Entschlossenheit und macht alle Gedanken an Expansion zunichte. So möchte er auch [[Khan Dez'hepah]]s Kopf als Trophäe.\r\n* '''Maurin Knochenspalter''' - Maurin Knochenspalter gehört zu den [[Verlassene]]n und ist ein Agent von [[Keldran]]. Er ist hier auf Geheiß von [[Keldran]] und dem jungen Kriegshäuptling [[Thrall]], denn er kennt die [[Brennende Klinge]] und die Arglist ihrer [[Hexenmeister]] und leitet deswegen die Verschwörungen gegen die Klinge. Es ist sein Wunsch, dem jungen Anführer gegen das Böse beizustehen, das seine Regentschaft zu stören droht. Mit einen Schattenpirscherskalp der [[Satyre der Zornsäer]] kann er auch den Dämonenlord, den Verderber, finden, denn als Erstes muss er jeden Schutzzauber brechen, den den Verderber gegen Wahrsagen hat. Auch ein Orakelkristall wird von Maurin benötigt.\r\n* '''Nataka Langhorn''' - Der [[Taure]] Nataka Langhorn ist der Bruder von [[Klippenbehüter Langhorn]]. Leider hat er aufgrund all der [[Zentauren]]-Aktivitäten nicht genug Zeit, um eine Reise zu den [[Trolle]]n nach [[Schattenflucht]] zu unternehmen, um dort Blutbauchfische zu kaufen.\r\n* '''Takata Stahlklinge''' - Der Orc Takata Stahlklinge ist ein Schwertkämpfer und ebenfalls ein Agent von [[Keldran]]. Er kümmert sich um dämonische Bedrohungen in [[Desolace]] und arbeitet damit auch gegen die Bedrohung durch die [[Brennende Klinge]]. Sie zu vernichten ist die einzige Möglichkeit, ihnen Einhalt zu gebieten. Aber auch die [[Satyrn der Zornsäer]] sind sein Ziel, sowie der [[Schreckenslord]] [[Azrethoc]] und der [[Hexenmeister]] [[Jugkar Grimm'rod]].",},
			["Geist des Sommers"] = { content = "Zum [[Sonnenwendfest]] erwartet Euch unter anderem die Quest „Licht im Dunkeln“. Als Belohnung erhaltet Ihr vom Flammenbewahrer eine Eingefangene Flamme die den Geist des Sommers beschwört. \r\n'''Quelle:'''",},
			["Geißel"] = { content = "Die '''Geißel''' ist die Armee der Untoten, die [[Kel'Thuzad]] durch Verbreitung der Seuche im Norden von [[Lordaeron]] erschaffen hat. Sie kämpft sowohl gegen die [[Allianz]] als auch gegen die [[Horde]]\r\n==Geschichte==\r\n* [[Entstehung des Lichkönigs]]\r\n* [[Kil'jaeden und der neue Pakt]]\r\n* [[Eiskrone und Frostthron]]\r\n* [[Krieg der Spinne]]\r\n* [[Kel'Thuzad und der Kult der Verdammten]]\r\n* [[Die Geißel von Lordaeron]]\r\n* [[Entstehung der Geißel]]\r\n* [[Ein Erbe …]]\r\n==Die Armee der Geißel==\r\nDie untoten Horden der Geißel setzten sich aus [[Ghul]]en, [[Skelett]]en, [[Zombie]]s, [[Gruftbestie]]n, [[Sumpfbestie]]n, [[Monstrosität]]en, [[Geist]]ern, [[Schemen]], [[Frostwyrm]]s, [[Knochengolem]]s, [[Gruftkäfer]]n, [[Untote Bestie|Untoten Bestien]], [[Todesgeist]]ern, [[Fleischriese]]n, [[Banshee]]s, die [[Val'kyr]], die [[Sinistren]], [[Schatten der Verdammnis]], [[Nekromant]]en und [[Akolyt]]en zusammen. [[Gargoyle]]s sind zwar nicht untot, folgen der Geißel jedoch in der Hoffnung auf Nahrung. Die Heere der Geißel werden von [[Todesritter]]n, [[Lich]]s und den [[Gruftlord]]s kommandiert. Früher waren auch [[Nathrezim]] in der Geißel zu finden. Alle Untoten unterstehen dem [[Lichkönig]].\r\nAlliierte der Geißel, die jedoch nicht unbedingt untot sind, sind die [[Stacheleber]] unter [[Charlga Klingenflanke]] und die [[Vrykul]] unter [[König Ymiron]]. Auch eine stattliche Anzahl [[Menschen]] dient dem [[Lichkönig]], genährt von dem Versprechen ewigen Lebens.\r\n'''Organisation'''\r\nDie Geißel ist strikt organisiert. Alle Untoten leben, um den LIchkönig zu dienen, sein Wort ist ihr einziges Lebensziel. Doch gibt es selbst unter den Untoten einige, die sich dem Lichkönig freiwillig und im Vollbewusstsein ihrer geistigen Gesundheit angschlossen haben. Solche Inviiduen werden dann häufig mit großer Macht belohnt, denn wenn sie den Lichkönig verraten würden, würden sie getötet und einen Platz in den stumpfsinnigen Horden der Ghule oder Skelette einnehmen. Auch anderer Untote, die zu Lebzeiten herausragende, mächtige oder listige Wesen waren, werden oft Kommandanten.\r\nSo hat jede Untote Rasse der Geißel einen, speziell dem Lichkönig ergebenen Anführer, der oft noch zusätzlich mit Macht beschenkt wurde.\r\nEinige dieser Anführer sind bzw. waren:\r\n* [[Kel'Thuzad]], Erz-[[Lich]] und Herr des Kults der Verdammten\r\n* [[Anub'arak]], Herr der [[Gruftbestie]]n\r\n* [[Sindragosa]], Königin der [[Frostwyrm]]s\r\n* ehem. [[Hochlord Darion Mograine]], oberster [[Todesritter]] des Lichkönigs und Nachfolger von [[Arthas]]\r\n* ehem. [[Sylvanas Windläufer]], Königin der [[Banshee]]s und nun Herrin der [[Verlassenen]]\r\n* [[Erzmagier]] [[Arugal]], wieder auferstandener Herr der [[Worgen]] und der [[Geist]]erkommandant\r\nEnge Vertraute des Lichkönigs werden Botschafter bei anderen Völkern, so [[Amnennar der Kältebringer]] und [[Prinz Keleseth]] so wie der Kommandant in den [[Geisterlande]]n [[Dar'Khan Drathir]].\r\n==Gebäude der Geißel==\r\n* [[Altar der Dunkelheit]]\r\n* [[Friedhof]]\r\n* [[Geisterturm]]\r\n* [[Gruft]]\r\n* [[Halle der Toten]]\r\n* [[Knochenhof]]\r\n* [[Nekropole]]\r\n* [[Opfergrube]]\r\n* [[Schlachthaus]]\r\n* [[Schwarze Zitadelle]]\r\n* [[Tempel der Verdammten]]\r\n* [[Ziggurat]]",},
			["Geißelkessel"] = { content = "'''Geißelkessel''' sind große Gefäße, mit denen die [[Geißel]] die [[Seuche]] in den [[Pestländer]]n verbreitet. Sie sind mit starken Ketten im Boden verankert und werden von einem Kessellord bewacht, der den jeweiligen Schlüssel zu seinem Kesseln verwahrt.\r\nEs gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der östlichen Königreiche erheben. Sie lauern östlich von [[Unterstadt]], in den nördlichen Ausläufern der Länder, die als [[Pestländer]] bekannt sind. In den Ländern des ehemaligen [[Lordaeron]] befinden sich acht dieser Geißelkessel - vier in den [[Westliche Pestländer|Westlichen Pestländern]] und vier weitere versteckt in den [[Östliche Pestländer|Östlichen Pestländern]]. Diese Kessel speien Gifte in die Luft und verbreiten die Seuche für die [[Geißel]] im ganzen Land. Die nekromantische Macht von [[Kel'Thuzad]] ist zu stark, um diese Kessel gänzlich zu schließen. Jeder Kessel enthält ein jeweils für ihn einzigartiges Gebräu aus Toxinen.",},
			["Geißeltroll"] = { content = "Geißeltrolle\r\nGeißeltrolle sind untote [[Trolle]], die dem [[Lichkönig]] dienen. Die Augen sind milchig blassblau und ihre ist kränklich grün mit hellgrauen Flecken. Ein Geißeltroll schwankt, seine Hände schlurfen über den Boden und seine Knie biegen sich bei jedem Schritt durch. Seine kleinen Augen starren stur geradeaus und er weicht nicht aus, wenn er angegriffen wird, sondern stolpert einfach weiter. Wenn es ein lebendes Wesen sieht, wird er sofort versuchen, es zu töten. Diese Wesen sind sehr dumm, ohne Befehle sind sie orientierungslos und leicht zu töten. Die meisten Geißeltrolle sind [[Eistroll]]e, die der Seuche zum Opfer fielen, als [[Ner’zhul]] sie perfektionierte.\r\n \r\nEiner von ihnen ist [[Wushoolay]], der sich in [[Zul Gurub]] aufhält.",},
			["Gekrümmter Rücken"] = { content = "Im Nordosten der [[Knochenwüste]], hinter [[Auchindoun]] in den [[Wälder von Terokkar|Wäldern von Terokkar]], liegt der '''Gekrümmte Rücken'''. An diesem Ort versammeln sich die [[Nekromanten]] der Auchenai. Die [[Todessprecher]] und [[Verdammnisverkünder]] der [[Auchenai]] tragen Verdammnisschädel bei sich, die mit mächtigen nekromantischen Verzauberungen belegt sind. Wenn man genügend Schädel sammelt, kann man ihre Macht mit der des [[Schreckensrelikt]]s vereinen und Teribus so befehlen, sich zu stellen. [[Teribus der Verfluchte]] ist eine Kreatur, die über der Knochenwüste ihre Kreise zieht.",},
			["Gelkis Dorf"] = { content = "#REDIRECT [[Zentauren der Gelkis]]", redirect = "Zentauren der Gelkis",},
			["Gemeinsprache"] = { content = "Die '''Gemeinsprache''' ist die Lingua franca der [[Allianz]]. Doch fast jedes gebildete Wesen auf [[Azeroth]] kann zumindest ein paar Sätze Gemeinsprache. Eine ihrer Dialekte ist die [[Gossensprache]] und die Sprache von [[Arathor]].\r\nDie Schrift ist eine Mischung aus den germanischen Runen, kyrillisch und einer eigene Runenschrift.\r\nEinige Wörter der Gemeinsprache sind aus dem Lateinischen und dem Englischen abgeleitet.\r\n==Liste bekannter Worte==\r\n* '''[[Azeroth]]''' = Word aus den Namen der ältesten menschlichen Vorfahren, den Azotha.\r\n \r\n* '''[[Thrall]]''' = Sklave (auch Name des [[Orc]]anführers)\r\n* '''[[Trol'kalar]]''' = Trollschlächter (auch Name eines Schwertes)\r\n* '''Esarus thar no'Darador''' = Durch Blut und Ehre dienen wir\r\n* '''[[Lordaeron]]''' = Mischung aus dem [[zwergisch]]en Wort \"lorn\" (Land), dem Alt-Arathorischen Wort \"Daer\" ([[Menschen]]) und dem [[Thalassisch]]en Wort \"Ronae\" (Frieden).\r\n* '''Landowar''' = [[Allianz]]\r\n* '''Deo gracias''' = Danket Gott (das Wort ist Lateinisch)\r\n* '''Uden!''' = Hilfe!",},
			["Gemälde 'Von Liebe und Familie'"] = { content = "In der Scharlachroten Bastion von [[Stratholme]] findet man das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde der Welt abgebildet sind. Es hing jahrelang an der Wand der Werkstatt von [[Tirion Fordring]] - in der Kaserne des Ordens. Nachdem [[Tirion Fordring|Tirion]]s Prüfung vorüber war, wusste er, dass er das Gemälde nicht mehr dort für alle sichtbar hängen lassen konnte. So versteckte er es an einem Ort, an dem es niemand vermuten würde und wenn man die Farbe wegkratzt, kommt sein Meisterwerk ‚Von Liebe und Familie’ zum Vorschein.",},
			["General Drakkisath"] = { content = "Der Schwarze Großdrachenheld '''General Drakkisath''' ist eine [[Drachenbrut]] im Thronsaal der [[Obere Schwarzfelsspitze|Oberen Schwarzfelsspitze]] hinter den Hallen des Aufstiegs. Er ist der Herrscher über die Drachenbrutarmeen von [[Nefarian]]. \r\nDer General kann mit seinem Blut das Glanzlose [[Drachenfeueramulett]] mit der letzten Verzauberung versehen und das Schmuckstück auf den Geist einer Elitewache [[Onyxia]]s abstimmen, die Zugang zu [[Onyxia]]s Hort gewährt. Er bewacht auch ein Brandzeichen mittels dessen man das [[Mal von Drakkisath]] erlangen kann. Dieses braucht man, um die Befehlskugel im [[Schwarzfels]] zu aktivieren und sich direkt in den [[Pechschwingenhort]]zu teleportieren. Denn diese Befehlskugel besitzt einen eingebauten Sicherheitsmechanismus, die sicherstellt, dass nur diejenigen, denen das Mal von Drakkisath in die Handfläche eingebrannt wurde, die Kugel überhaupt benutzen können.",},
			["General Rajaxx"] = { content = "'''General Rajaxx''' ist ein mächtiger [[Qiraji]] Gladiator, der in den Ruinen von [[Ruinen von Ahn'Qiraj]] zu finden ist und die Krieger der Qiraji befehligt. Er war auch für den Tod von [[Valstann Hirschhaupt]] im [[Krieg der Sandstürme]] verantwortlich.\r\n==Taktik==\r\nVor dem finalen Kampf gegen General Rajaxx gilt es 7 Wellen seiner Untergebenen zu bekämpfen. Diese Wellen, bestehend aus einer variierenden Zusammensetzung von Qiraj Gladiatoren und Schwarmwachen und einem Anführer, kommen nacheinander. Abhängig vom Ausstattungsstand und dem Spielstil der Schlachtgruppe gibt es 2 Möglichkeiten, diesen Kampf zu bestreiten. Bei der aktiven Variante werden die Ereignisse durch das Überschreiten der Schwelle vom Haupttank ausgelöst. Dieser nimmt auch sogleich den herannahenden 1. Zwischenboss in Empfang. [[Andorov]] und seine Nahkämpfer werden von hinten angerannt kommen und sich an dem nun startenden Gefecht beteiligen. Bei der passiven Variante spricht jemand Andorov an, damit dieser den Kampf beginnt. Jeder Spieler, der die Rufstufe „freundlich“ beim [[Zirkel des Cenarius]] erreicht hat, wird in dem nun folgenden Kampf die „Aura des Kommandos“ von Andorov erhalten. Diese regeneriert alle 3 Sekunden 200 HP und stellt den Schlüssel zur einfachen Bewältigung dieses Kampfes dar, da sie die Grundheilung gewährleistet und die Sonderfähigkeit von General Rajaxx aushebelt - dazu aber später mehr.\r\nJeder Boss der 7 Wellen verfügt über eine bestimmte Spezialfähigkeit:\r\n* Hauptmann Qeez - flächendeckender Furchtzauber\r\n* Hauptmann Tuubid - bestimmt Aggro-Ziele für die Trashmobs (ähnlich [[Arlokk]] in [[Zul'Gurub]])\r\n* Hauptmann Drenn - stationärer Blitzschlag-Flächenzauber\r\n* Hauptmann Xurrem - Schockwelle\r\n* Major Yeggeth - Segen des Schutzes\r\n* Major Pakkon - Zurückschleudern\r\n* Oberst Zerran - schadenserhöhender Magie-Selbstbuff, entfernbar\r\nIn den Wellen sollten zuerst die Kommandanten, dann die Schwarmwachen und zuletzt die Gladiatoren getötet werden. Besondere Erwähnung verdient im Grunde nur der 3. Kommandant, da er auf jeden Fall aktiv von einem Krieger getankt und weg geführt werden muss, um die Blitzschlagwolke von der Schlachtgruppe fernzuhalten. Die Zielvergabe des 2. Bosses ist unwichtig, wenn man die Mobs mit Furcht eindeckt und durch konstantes Entfernen des Selbst-Buffs wird auch der letzte Kommandant zum Kinderspiel. Sind alle Wellen bekämpft, tritt General Rajaxx auf den Plan.",},
			["General Zornesschmied"] = { content = "General Zornesschmied in den [[Schwarzfelstiefen]] führt den Klan der [[Zwerge der Zorneshämmer]] und ist für seine Sorgfalt bekannt. Ohne ihn hätten die [[Dunkeleisenzwerge]] das Schema der Verschlüsselung von [[Marschall Windsor]] niemals herausgefunden. General Zornesschmied ist auch für die Koordination der Angriffe auf die 109. Division des KEK ([[Kargath Expeditions Korps]]) und für die massive Dezimierung der Truppen der verantwortlich.",},
			["Geologe des Sonnenzorns"] = { content = "Die Geologen des Sonnenzorns sind Spezialisten der [[Blutelfen]], die unter dem Befehl von [[Kael'thas Sonnenwanderer]] an den [[Manaschmieden]] im [[Nethersturm]] in der [[Scherbenwelt]] arbeiten. Genau wie die [[Warpmeister]] und Warp[[ingenieure]] sind sie weder Teil des Militärs noch der [[Magister des Sonnenzorns]] und deshalb nicht so leicht zu ersetzen.",},
			["Gerenzo Pfeifzang"] = { content = "Vor einiger Zeit stellte die Filiale der [[Venture Company]] im [[Steinkrallengebirge]] an der [[Scherwindklippe]] den [[Gnom]] namens Gerenzo Pfeifzang ein. Manche fanden das eine Ungeheuerlichkeit. Die Tatsache, dass die [[Venture Company]] diesen Gnom angestellt hat, hat in [[Undermine]] für einiges Aufsehen gesorgt. Die Handelsbarone finden es nicht gut, dass Razdunk mit Gerenzo gemeinsame Sache macht. Weit oberhalb des Felskesselsees in der Nähe des Wasserrades beaufsichtigt Gerenzo nun die gesamte [[Scherwindklippe]]. \r\n==Aussehen==\r\nEr ist nicht gerade eine Schönheit. Sein Fleisch sieht aus, als würde es faulen. Dazu hat er noch überall an seinem Körper Metallteile und Zeugs angeflanscht und sogar einige seiner Körperteile, wie z.B. einen Arm, durch mechanische ersetzt.",},
			["Gerrig Knochengriff"] = { content = "'''Gerrig Knochengriff''' ist ein [[Zwerg]] im Düsteren Viertel von [[Eisenschmiede]], der dem [[Schattenhammerkult]] angehört. Er steht meist dort in seinem Wohngeschäftshaus. \r\nDieser „Buchhändler“, sammelt seltene, obskure Schriften und hat seine Finger wohl noch in allerlei anderen Dingen. Er trägt Lehren zusammen ... Alte Lehren ... Mächtige Lehren ... und wenn man ihm das [[Siegelzeichen des Hammers]] zeigt, dann wird er den Träger für einen der Schattenhammerkultisten halten. Zu Gerrigs Besitz gehört auch '[[Yagyins Zusammenstellung]]' und das verbotene Wissen daraus. Wenn man ihm den [[Stern von Xil'yeh]], die [[Hand von Dagun]] und das [[Herz des Vermächtnisses]] bringt, leiht er sie Anhängern des Schattenhammers aus - aber man sollte diese Zusammenstellung nicht in unfreundliche Hände gelangen lassen. Dieses Buch enthält viele Wahrheiten...und die Wahrheit kann manchmal wehtun.\r\nEr sucht unter anderem das '[[Lorgalismanuskript]]' und das [[Buch: Die Macht in der Tiefe]]; und er weiß auch, wie man die Prinzessin [[Myzrael]] beschwören kann. Doch dazu braucht er die von [[Theldirun der Verirrte|Theldirun dem Verirrten]] gestohlene Rolle.",},
			["Geschichte der Todesritter"] = { content = "== Geschichte der Todesritter==\r\n===Schatten der Gerechtigkeit===\r\n[[Orgrim Schicksalshammer]]s erste Handlung als Kriegshäuptling der [[Horde]] war die Vernichtung aller [[Hexenmeister]] des [[Schattenrat]]es. Einzig [[Gul'dan]], den ehemaligen Meister des Rates, ließ er im Austausch gegen dessen Loyalität am Leben. Im Gegenzug dazu schwor [[Gul'dan]], ihm eine neue Gattung mächtiger Krieger für die [[Horde]] zu erschaffen. Nach einer langen Reihe von Experimenten mit den Seelen der getöteten Ratsmitglieder gelang es [[Gul'dan]] schließlich, den Leichnam eines gefallenen Ritters von [[Sturmwind]] mit dem Geist des Nekrolyten [[Teron Blutschatten]] zu verschmelzen. Der erste Todesritter war geboren. Schließlich begann [[Gul'dan]] auch weitere Ratsmitglieder in diese schrecklichen, finsteren Krieger zu verwandeln, die während des [[Der Zweite Krieg|Zweiten Krieges]] so viel Angst und Schrecken in ganz [[Azeroth]] verbreiten sollten. Nach [[Gul'dan]]s Verrat und anschließendem Tod zog sich ein Teil der [[Horde]], einschließlich der Todesritter, durch das [[Dunkle Portal]] nach [[Draenor]] zurück. Schließlich verlor sich die Spur der meisten Todesritter mit der Zerstörung [[Draenor]]s. Nur von [[Teron Blutschatten]] weiß man, dass sein rastloses, verbittertes Wesen in den Hallen des [[Schwarzer Tempel|Schwarzen Tempels]] residiert.\r\n===Kämpfer des Lichkönigs===\r\nJahre nach der Zerstörung von [[Draenor]] erschuf der finstere und mächtige [[Lichkönig]] eine neue Art von Todesrittern: gnadenlose, mit mächtigen Runenklingen bewaffnete Kämpfer der [[Geißel]]. Der erste und bekannteste von ihnen war Prinz [[Arthas]] Menethil, einst ein mächtiger [[Paladin]] der [[Silberne Hand|Silbernen Hand]], der in dem verzweifelten Versuch sein Volk zu retten, seine Seele opferte, um die Runenklinge [[Frostgram]] an sich zu bringen. Im Gegensatz zu [[Gul'dan]]s ursprünglichen Todesrittern rekrutieren sich die heutigen Todesritter aus den Reihen von [[Paladin]]en, die ihren Glauben verloren haben und die für das Versprechen der Unsterblichkeit ihre Seelen dem [[Lichkönig]] verpfänden. Todesritter, die in der Schlacht fallen, werden schon wenig später von ihrem Herrn und Meister wiederbelebt, um diesem auch weiter loyal zu dienen. Seit der Zeit, als [[Arthas]] den Frostthron zerschlug, um seine Seele mit dem [[Lichkönig]] zu verschmelzen, wuchsen die Macht und der Zorn der finsteren Todesritter beständig weiter. Nun warten diese unbeugsamen Kreuzritter der Verdammnis nur noch auf den Befehl ihres [[Lichkönig]]s, um erneut Tod und Zerstörung über [[Azeroth]] zu bringen. \r\n'''Quelle''':",},
			["Geschmolzener Kern"] = { content = "Der Geschmolzene Kern befindet sich am tiefsten Punkt des [[Schwarzfels]]. Genau hier, im Herzen des Berges, beschwor Imperator [[Thaurissan]] vor langer Zeit in einem Akt der Verzweiflung den elementaren Feuerfürsten [[Ragnaros]], um seinen gescheiterten Putsch gegen die [[Zwerge]] von [[Eisenschmiede]] doch noch in einen Sieg zu verwandeln. Obwohl der [[Ragnaros|Feuerfürst]] immer in der Nähe des feurigen Kerns bleiben muss, treiben seine Offiziere die [[Dunkeleisenzwerge]] gnadenlos dazu an, ihm eine Armee aus lebendem Gestein zu erschaffen. Der See aus Magma, in dem [[Ragnaros]] schläft, ist in Wirklichkeit ein interplanarer Riss, durch den bösartige [[Feuerelementare]] von der Ebene des Feuers nach [[Azeroth]] gelangen. Der höchstrangige von [[Ragnaros]]' Untergebenen ist [[Majordomus Executus]], der als einziger in der Lage ist, den schlafenden Feuerfürsten zu wecken.\r\n==Bosse==\r\n* [[Lucifron]]\r\n* [[Magmadar]]\r\n* [[Gehennas]]\r\n* [[Garr]]\r\n* [[Baron Geddon]]\r\n* [[Shazzrah]]\r\n* [[Golemagg der Verbrenner]]\r\n* [[Sulfuronherold]]\r\n* [[Majordomus Executus]]\r\n* [[Ragnaros]]",},
			["Geschmolzener Riese"] = { content = "'''Geschmolzenen Riesen''' sind gigantische elementare Wesen, die im [[Geschmolzener Kern|Geschmolzenen Kern]] zu finden sind. Sie ähneln im Aussehen den [[Bergriesen]], jedoch erscheint ihre steinerne Haut als schwarzrote geschmolzene Kruste.\r\n==Arten==\r\n* [[Geschmolzener Zerstörer]]\r\n==Persönlichkeiten==\r\nZu den berühmtesten Vertretern zählt:\r\n* [[Bael'Gar]]\r\n* [[Golemagg der Verbrenner]]\r\n* [[Magmus]]\r\n* [[Volchan]]",},
			["Geschmolzene Riesen"] = { content = "#REDIRECT [[Geschmolzener Riese]]", redirect = "Geschmolzener Riese",},
			["Gesichtslose"] = { content = "Über die nur selten in Erscheinung tretenden Gesichtslosen ist so gut wie nichts bekannt. Man weiß, dass es mächtige grob humanoide förmige Wesen sind, deren Kopf jedoch wie ein bizarrer, insektenhafter Oktopus anmutet. Einer ihrer beiden Arme ist übermäßig groß und unförmig.Sie hausen unter [[Azjol-Nerub]], der alten Stadt der [[Neruber]].Ob die [[Neruber]] Kenntniss von diesen Wesen hatten, oder ob sie sich erst später dort einnisteten, ist unklar. \r\n[[Hakkar]], der Blutgott ist [[Zul Gurub]] soll Gerüchten zufolge zu ihnen gehören. Andere Gerüchte sagen,dass die Gesichtslosen Diener der Alten Götter sind, da sie den Vergessenen unter Azjol-Nerub beschützten und der Kriegerkaste der [[Qiraji]], welche ebenfalls Diener der Alten Götter sind, sehr ähnlich sehen.",},
			["Gespenst"] = { content = "Gespenster sind gequälte Seelen, die sich in der Pein ihres untoten Daseins winden. Sie können nicht verstehen, dass sie nicht mehr am Leben sind, und ziehen endlos durch die unwegsamen Einöden zwischen dem [[Sog der Unterwelt]] und der stofflichen Welt – auf der Suche nach Erlösung von ihrem ewigen Leid. Zwar sind sie nicht zwangsläufig böse, verzehren sich aber nach Körperkontakt, was den Lebewesen, die sie berühren, nicht selten großen Schaden zufügt.",},
			["Getriebene"] = { content = "'''Getriebene''' sind ehemalige [[Blutelfen]], die der Sucht nach [[Magie]] erlegen sind.\r\nWenn es eine Lektion gibt, die man als [[Blutelf]] niemals vergessen darf, dann ist es diese: Verliert unter keinen Umständen die Kontrolle über das Verlangen nach Magie. Dieser Durst ist unstillbar. [[Blutelfen]] nutzen den Manadurst, um Energie zu absorbieren, und verwenden den arkanen Strom, um sie in der gewünschten Form wieder freizulassen. Begeht man dabei einen Fehler, wird man zu einem Getriebenen ... hoffnungslos abhängig und dem Wahnsinn verfallen.\r\n==Persönlichkeiten==\r\n* [[Felendren der Verbannte]]\r\n* [[Thaelis der Manadurstige]]",},
			["Getriebenen"] = { content = "#REDIRECT [[Getriebene]]", redirect = "Getriebene",},
			["Ghamoo-ra"] = { content = "'''Ghamoo-ra''' ist eine große [[Schildkröte]] in der [[Tiefschwarze Grotte|Tiefschwarzen Grotte]]. Sie lebt auf der kleinen Insel inmitten des Teiches von Ask'ar, in der zweiten Höhle der Instanz. Dort streift sie um das Zentrum der Landmasse. Dabei wird sie von mehreren anderen Schildkröten umgeben. Die zusätzlichen Schildkröten sind nicht aggressiv und Ghamoo-ra kann angegriffen werden, ohne die anderen Wildtiere zu stören. Der Kampf mit Ghamoo-ra ist ziemlich unkompliziert, obwohl Aufgrund von Ghamoo-ra's hohem Rüstungswert die Begegnung eine ganze Weile dauern kann.",},
			["Ghaz'an"] = { content = "Die [[Hydra]] Ghaz'an ist im [[Tiefensumpf]] des [[Echsenkessel]]s in den [[Zangarmarschen]] zu finden, wo sie auf einer gewaltigen Plattform thront.",},
			["Ghul"] = { content = "Ghule sind die einfachen Krieger der [[Untote]]n-Armee. Diese schwerfälligen, verfaulenden Leichen waren einst [[Zombie]]s und haben den finalen Schritt zum wahren \"[[Untote]]n\" getan. Ghule verfügen über großes Durchhaltevermögen und schwelgen im Kampf gegen lebende Wesen. Ghule sind heißhungrige Kannibalen, die ihre Wunden heilen können, indem sie das Fleisch gefallener Krieger essen. \r\nIn einer [[Gruft]] werden sie darin unterwiesen, ihre gefallenen Widersacher zu verspeisen.\r\n[[Todesritter]] sind in der Lage, Gefallene als Ghule wiederzuerwecken.\r\n'''Quelle:'''",},
			["Ghule"] = { content = "#REDIRECT [[Ghul]]", redirect = "Ghul",},
			["Gibin"] = { content = "'''Gibin''' war seit jeher der [[XO]] der [[Die einsamen Wölfe|einsamen Wölfe]] und hat nach [[Alfar]]s Rücktritt als Alphawolf, die Führung des Rudels Übernommen. Im weiteren ist er Großanleger bei der [[Nationalbank von Azeroth]].\r\n==Beschreibung == \r\n====In jungen Jahren====\r\nWenn man hinter der Maske oder unter seinem Tief ins Gesicht gezogenen Hut sein Gesicht und die leuchtend grünen Augen sehen kann, hat man das Gefühl das er immer verschmitzt grinst. Wenn nur die Bartspitzen hinter der Maske hervorschauen wird der Eindruck nur noch verstärkt. \r\n====Heute als erfahrener Veteran====\r\nDem Kampf gegen die [[brennende Legion]] hat er sein rechtes Auge geopfert und aus dem anderen blickt euch ein alter erfahrener [[Gnome|Gnom]] an. Aus dem verschmitzten Grinsen ist schon lange ein ernster Gesichtsausdruck geworden. Meist trägt er eine Augenklappe über der leeren Augenhöhle, doch im Kampf will er nicht verraten das er einen Toten Winkel hat und trägt dann meist ein Glasauge. \r\n====Allgemein====\r\nWer genau hinschaut wird feststellen das er ein wenig größer ist als normale [[Gnome]] und das seine Ohren scheinbar ein ganz klein wenig spitz zulaufen. Aber das wird nur dem wirklich aufmerksamen Beobachter auffallen.\r\n==Geschichte==\r\nEigentlich wollte Gibin [[Jäger]] werden, doch keiner wollte ihn ausbilden, egal wie viele [[Jäger|Jägerlehrer]] er ansprach alle schickten ihn mit den Worten '[[Gnome]] sind keine [[Jäger]]' wieder weg. Zufällig geriet er an einen Schurkenlehrer der sich ihm an nahm und ihm das Leben als [[Schurke]] schmackhaft machte. Gibin sah darin seine Chance sich vielleicht in eine Schule der [[Jäger]] einzuschleichen und vielleicht so an den Lektionen teilzunehmen. Es verwundert nicht das er sich der [[Kürschner]]ei und [[Lederer|Lederverarbeitung]] angenommen hat und begierig alles lernte was er lernen konnte. Die Neugier der [[Gnome]] ist bei ihm deutlich ausgeprägt doch das [[Gnome|gnomische]] Technikverständnis fehlt ihm völlig. Er hat sogar Probleme technische Erfindungen zu handhaben und das meiste geht in seinen Händen kaputt. So hat sich mit den Jahren ein leichte Technikphobie entwickelt. An [[Roboschreiter]] wagte er sich gar nicht und vertrat zwischenzeitlich die Meinung das [[Gnome]] überhaupt nicht reiten sollten, da die kurzen Beine dem nicht wirklich förderlich seien. Vielleicht lagt das aber auch daran das er beim Schreiterhändler Hausverbot hatte, da als er das letzte mal da war es doch zu einigem Schaden an den Schreitern gekommen ist. Greifen nutzte er nur für lange Strecken, wenn es nicht anders ging und eigentlich auch nur widerwillig. Er krallte sich mehr am Greifen fest als das er auf ihm ritt und wenn er ab stieg war er stets blass im Gesicht. Es war die [[Nachtelfen]] [[Jäger]]in Iskimya, die ihn mal auf ihrem [[Nachtsäbler]] mitnahm, und ihn auf den Gedanken brachte, das vielleicht diese geschmeidige Katze das richtige Reittier für ihn sei. Doch solange die Hochnäsigen [[Nachtelfen]] ihm keinen verkaufen wollten ging er weiterhin am liebsten zu Fuß.\r\nEinige Zeit verging und da die hochnäsigen [[Nachtelfen]] ihm immernoch keinen [[Nachtsäbler|Tiger]] verkauften ganz egal was er was er für das [[Volk]] von [[Darnassus]] geleistet hatte und ihm immerwieder vorgeworfen wurde das er mit seinen kurzen Beinen viel zu langsam währe, hat er sich dazu durchringen können sich einen [[Roboschreiter]] zu kaufen. Zwar gab es Anfangs etwas Probleme da er immernoch Hausverbot beim Schreiterhändler hatte. Doch es fanden sich ein fähiger [[Gnome|gnomscher]] [[Magier]], der in der [[Ingenieur]]skunst bewandert war und ein nicht minder fähigen [[Zwerge|zwergischer]] [[Priester]] die ihm einen [[Roboschreiter|Schreiter]] segneten und verzauberten, das er zumindest ein wenig funktionierte. Meist gab es zwar Probleme, mit quietschenden Teilen Aussetzern des Motors, dichten Rauchwolken die ihn weithin sichtbar machten und sein kommen ankündigten und teilweise vielen sogar einzelne Teile ab und mussten wieder an den [[Roboschreiter|Schreiter]] montiert werden. Doch alles in allem hat der [[Roboschreiter|Schreiter]] ganz gut gehalten. Die Segnungen und [[Verzauberer|Verzauberungen]] ließen zwar keine Farbe mehr halten, aber irgendwie ging es.\r\nNach langem hin und her hatte sich Gibin dann mit dem Stoffhändler in [[Darnassus]] geeinigt, wenn er ihn gut mit Runenstoff versorgen würde, würde er ein gutes Wort für Gibin bei Lelanai der Tigerhändlerin in [[Darnassus]] einlegen. Doch dieser wurde mit der Zeit unverschämt und verlangte immer mehr Runenstoff, viel mehr als ursprünglich ausgemacht. Selbst mit Hilfe seiner Freunde konnte Gibin nicht so viel Runenstoff wie verlangt heranbringen. Ein weiterer Fürsprecher für ihn war [[Mondfederfeste|Pratt McGrubben]] in [[Feralas]]. Der Händler für Lederverarbeitungsbedarf macht Luftsprünge bei jedem makellosen [[Yetis|Yetibalg]] den man ihm überlässt und war daher gerne Bereit ein gutes Wort für Gibin einzulegen als er ihn geradezu mit [[Yetis|Yetibalgen]] überhäuft hat.\r\nDann war es endlich soweit nachdem etliche Leute auf Lelanai eingeredet hatten, hatte sie ein einsehen und erklärte sich bereit Gibin einen gestreiften [[Nachtsäbler]] namens Schattenpfote zu verkaufen und Gibin hat ihn gleich in sein Herz geschlossen. Schattenpfote musste sich war erst daran gewöhnen einen [[Gnome|Gnom]] auf dem Rücken zu haben, doch inzwischen sind die Zwei ein eingespieltes Team.\r\nBald darauf zog es Gibin durch das [[Dunkle Portal|Portal]] in die [[Scherbenwelt]] um gegen die [[brennende Legion]] zu kämpfen. Schon bei den ersten Kämpfen verlor er sein rechtes Auge an einen [[Höllenorcs|Höllenorc]]. Oft trägt er ein Glasauge, welches allerdings nach einiger Zeit zu jucken und zu drücken beginnt so das er es wieder raus nimmt und eine Augenklappe über die leere Augenhöhle zieht.\r\nEin Schicksallsschlag bei den [[Die einsamen Wölfe|Wölfen]] sorgte dafür das er wenige Zeit später zum Rudelführer der [[Die einsamen Wölfe|Wölfe]] ernannt wurde und nun die Verantwortung für das [[Die einsamen Wölfe|Rudel]] trägt.\r\nDarüber sind seine eigenen Forschungen über sein merkwürdiges [[gnome]]nuntüpisches gestörtes Verhältnis zu Technik ein wenig in Vergessenheit geraten, aber eine Exkursion in die verschütteten Archive von [[Gnomeregan]] ergab das es da scheinbar mal zu einem 'Zwischenfall' zwischen einem doch so anständigen [[Hochelfen]] und einer frühen Vorfahrin von ihm gab. Dieser 'Zwischenfall' wurde aber weitestgehend Tod geschwiegen. Es erfordert weitere Exkursionen nach [[Gnomeregan]] um dem Rätsel auf den Grund zu gehen.\r\nIm Moment bemüht sich um eine Gasthörerstelle am [[Institut für Pfuschkunde]] um endlich seine Forschungen beenden zu können.\r\n'''wird fortgesetzt'''",},
			["Giftiger Unterschlupf"] = { content = "Der '''Giftige Unterschlupf''' in [[Tanaris]] ist ein Bau der [[Silithiden der Centipaar]]. Diese [[Silithiden]] legten die Teiche trocken, die sich einst dort an dieser Stelle befanden und die [[Goblins]] stehen dadurch einer großen und ernsten Bedrohung gegenüber, die nicht nur [[Tanaris]] und [[Gadgetzan]], sondern das ganze südliche [[Kalimdor]] betrifft, wenn sie nichts unternehmen. Möglicherweise ist sogar ganz [[Azeroth]] gefährdet.",},
			["Gilde"] = { content = "Auf einem Server können sich [[World of Warcraft|WoW]]-Spieler in '''Gilden''' zusammenschließen. \r\n==Gildengründung==\r\nMindestens 10 Mitglieder müssen dabei die jeweilige [[Gildencharta]] unterzeichnen um eine neue Gilde zu gründen. Beim Erwerb der leeren Charta beim [[NPC]] kann der Gildenname frei gewählt werden. Er muss nur auf dem entsprechenden Server einmalig sein. Der die Charta erwerbende [[Avatar]] ist nach erfolgreicher Gründung automatisch [[Gildenmeister]].\r\n==Siehe auch==\r\n* [[Gilden der Allianz]]\r\n* [[Gilden der Horde]]",},
			["Gilneas"] = { content = "== Allgemeines==\r\nGilneas wird auch das vergessene Königreich genannt. Die einst mächtige Nation der [[Menschen]] ist – abgetrennt von einer hohen Mauer, dem [[Graumarnwall]] - auf einer Halbinsel von [[Lordaeron]] südlich des [[Silberwald]]es zu Hause. Aktuelle Informationen sind bis dato nicht bekannt. \r\n==Geschichte==\r\nNoch bis vor wenigen Jahren war Gilneas ein mächtiges Königreich der [[Menschen]], das sich über die gesamte südliche Halbinsel [[Lordaeron]]s erstreckte. Die Hauptstadt dieser stolzen Nation war Gilneas Harbor. \r\n===Der Zweite Krieg===\r\nUngeachtet einer drohenden Invasion durch die [[Horde]], hatte sich Gilneas bis zum Beginn des Zweiten Krieges nicht der [[Allianz]] angeschlossen. Es hatte [[Lordaeron]] nur Gesten der Unterstützung bereitgestellt, aber war in keine festen Bindungen zu irgendeinem der Länder involviert, sondern von den anderen Nationen der westlichen Welt immer getrennt geblieben. Das Königreich hatte sich in der Vergangenheit immer von den übrigen Völkern ferngehalten, und verfolgte auch nun diese Politik weiter. Sein Herrscher Genn Graumarn war davon überzeugt, mit seinen eigenen Armeen allen Bedrohungen gewachsen zu sein. \r\nDie Nation schloss sich zwar später der [[Allianz]] an, strebte aber fortgesetzt nach einer Führungsrolle. Als die [[Orcs]] schließlich die Küsten [[Lordaeron]]s angriffen, hielt Graumarn seine Truppen so lange zurück, bis auch die eigenen Grenzen attackiert wurden. Nach dem Sieg über die [[Horde]], plädierte Gilneas dafür, alle [[Orcs]] töten zu lassen, statt sie in bewachten Lagern zusammenzupferchen. \r\nWeil König [[Terenas]] dazu aber nicht bereit war, entzog Graumarn der [[Allianz]] seine Unterstützung. Doch die [[Kirin Tor]] und König [[Terenas]] wussten, dass Genn Graumarn nicht nur versuchte einzugreifen, um sein eigenes Prestige zu heben, sondern um vielleicht seine Expansions-Träume zu fördern. \r\n===[[Alterac]]-Krise === \r\nWährend der [[Alterac]]-Krise spielte das Königreich wieder eine wichtige Rolle. Ein Neffe des Verräters [[Lord Perenolde]] war nach dem Verrat nach Gilneas geflohen, und es gab das Gerücht, dass Graumarn seinen Anspruch als Nachfolger unterstützte. Eine Basis in [[Alterac]] würde Gilneas Zugang zu Resourcen geben, die das südliche Königreich nicht hatte, und den Vorwand seine mächtigen Schiffe über das Große Meer zu schicken. Aber König [[Terenas]] lehnte Perenolds Neffen als Nachfolger ab, und annektierte das besetzte [[Alterac]].",},
			["Gizrul der Geifernde"] = { content = "'''Gizrul der Geifernde''' ist ein riesiger [[Worg]] mit silbergrauen Fell in der [[Untere Schwarzfelsspitze]]. Er ist der Partner von [[Halycon]] und erscheint sobald sie getötet wurde. Dabei geht er sofort zum Angriff über. Sein Infizierter Biss verursacht im Kampf regelmäßigen Naturschaden bei einem Feind und erhöht 3 Minuten lang seinen erlittenen körperlichen Schaden und Gizruls Wutanfall erhöht 2 Minuten lang sein Angriffstempo um 60% und den von ihm zugefügten körperlichen Schaden um 50.",},
			["Gjalerbron"] = { content = "'''Gjalerbron''' ist eine Heimstätte der [[Vrykul]] im Nordwesten des [[Der heulende Fjord|Heulenden Fjords]]. In ihren Plänen wird ein unmittelbar bevorstehender Angriff auf [[Westwacht]] und das [[Lager der Winterhufe]] bis ins Detail beschrieben. Es scheint, als würde der Frostwyrm [[Glacion]], der hoch am Himmel seine Bahnen zieht, für diese Offensive eingesetzt werden. Sein Meister ist [[Wyrmrufer Elend]]. Glacion wird gerufen, wenn man das Wyrmruferhorn auf seiner Plattform in der hinteren linken Ecke von Gjalerbron bläst.",},
			["Gleve der Aspekte"] = { content = "Die [[Gleve der Aspekte]] wurde von den [[Dämon]]en der [[Brennende Legion|Brennenden Legion]] während des [[Krieg der Uralten|Krieges der Urtume]] aus den Essenzen von Zeit, Leben, [[Magie]], Traum und Erde, den [[Drachenaspekte]]n, geschmiedet. Während des dritten Krieges wurde die Gleve mitgeführt, doch nach der Niederlage am [[Hyjal]] zerbrach die Waffe. Vor kurzem hat [[Verdammnislord Kazzak]] die Gleve neu geschmiedet und mit ihrer Macht das [[Dunkle Portal]] wieder geöffnet.",},
			["Glimmernetzjungtier"] = { content = "Der Auftrag \"Be-Öh-Es-Eh\" von [[Kilber]] führt euch zu den [[Spinnen]] in der Schwarzfelsspitze. Als Belohnung für diesen Auftrag winkt ein Glimmernetzjungtier.",},
			["Glotz Widrikus"] = { content = "'''Glotz Widrikus''' (engl. ''Oglethorpe Obnoticus'') ist ein gnomischer Meister[[ingenieur]] und Erfinder mehrerer [[Leitroboter]]. Doch einige seiner [[Leitroboter]] sind verloren gegangen und er würde Abenteurer belohnen, wenn sie sie aufspüren. Dafür muss man den zufällig gefundenen Notsignalgeber zum [[Leitroboter]] bringen, damit Glotz die Koordinaten berechnen kann. Danach muss der [[Leitroboter]] an seinen sicheren Ort eskortiert werden. Weitere seiner Erfindungen beinhalten den Optomatischen Deflektor, eine Thermotastischen Eieruhr, ein Maschendrahthandtuch, ein Fehlgeschlagenes Flugexperiment, sowie ein Gnomisches Wasserabsenkungsgerät, die er den Rettern seiner [[Leitroboter]] gern zur Verfügung stellt.",},
			["Gluthauer"] = { content = "#REDIRECT [[Trolle der Gluthauer]]", redirect = "Trolle der Gluthauer",},
			["Glutnebelgipfel"] = { content = "Der Glutnebelgipfel im [[Brachland]] nordwestlich des [[Wegekreuz]]es ist höchstwahrscheinlich die Quelle, von wo aus sich ein Gift auf das Land verbreitet. Auf seinen luftigen Höhen gibt es Teiche, die das Wetter beeinflussen und das Wasser dieser Teiche wurde vermutlich durch [[Dämonen]]-anbetende [[Brennende Klinge|Kultisten der Brennenden Klinge]] verunreinigt. Die [[Dämonensaat]] ist ein mächtiges Werkzeug der [[Brennende Legion|Brennenden Legion]] in den Händen der Kultisten hier und befindet sich in einer Höhle des Glutnebelgipfels, oberhalb eines dämonischen Altars des Feuers.",},
			["Glutstätte"] = { content = "Die [[Glutstätte]] ist eine verbrannte Gegend im Osten des [[Der heulende Fjord|Heulenden Fjords]], vor den Toren der [[Westwacht]], in der sich [[Protodrachen]] tummeln und dort ihre Eier ausbrüten. \r\nDie Jahre, durch welche diese Wälder hinweg brannten, sind ungezählt. Sie sind von alter Magie erfüllt und das Paarungsareal für die Brutmutter und ihre Protodrachenkonsorten. Aber nun ist ein lag vergessenes Übel wieder erwacht und versucht erneut, die Abkömmlinge der Brutmutter für seine Zwecke zu versklaven. Die [[Vrykul]] haben eine Störung verursacht, die weit über die Grenzen der Glutstätte hinausgeht und auch die Leute der Allianz in der [[Westwacht]] bedroht. Es muss irgendeine abartige Magie am Werk sein - und seit Kurzem scheint sie zu wachsen. Jedoch gibt es einige Urtume, die sich in dieser Gegend um die Ursachen kümmern.",},
			["Glühkappenpilz"] = { content = "'''Glühkappenpilze''' wachsen überall in den [[Zangarmarschen]]. Man muss nur wissen, wie man sie richtig sammelt ohne sie zu zerstören. Die [[Sporeggar]] benutzen diese glänzenden runden Pilze als Zahlungsmittel.",},
			["Glühwürmchen"] = { content = "Bei den Sumpflichtschwärmern in den [[Zangarmarschen]] fangt Ihr mit etwas Glück ein Glühwürmchen ein.",},
			["Gnoamsprenkelspross"] = { content = "Das '''Gnoamsprenkelspross''' ist die Energieversorgung eines [[Goblinschredder]]s. Man findet diesen Apparat bei [[Sneeds Schredder]] in den [[Todesminen]]. [[Shoni die Schtille]] aus [[Sturmwind]] will mittels dieses Gerätes die Energieversorgung der [[Gyrobohrmatischer Exkavationator|Gyrobohrmatischen Exkavationatoren]] sicherstellen, um durch die felsigen, unterirdischen Grenzen von [[Gnomeregan]] zu brechen und einem Gnomenangriff den Weg zu ebnen.",},
			["Gnoarn"] = { content = "'''Gnoarn''' ist ein kahlköpfiger Gnom in der Tüftlerstadt von [[Eisenschmiede]]. Aber das war nicht immer so. Das Strahlungsleck in [[Gnomeregan]] rief diesen tragischen Haarverlust hervor. Vor jenem Tag hatte er den einzigen Gnomenafro in ganz [[Azeroth]]. Er dachte, dass der Verlust dieses außergewöhnlichen Kopfhaares bestimmt sein Ende sein würde, aber er hat überlebt. Als Gnoarn von dem Strahlungsblitz getroffen wurde, fielen seine wunderschönen braunen Locken in Klumpen zu Boden. Büschelweise. Alles wurde noch schlimmer, als Gnoarn dann völlig ausgetickt ist. Gnoarn fasste sich ungläubig an seinen kahlen Kopf und in seinen Augen funkelte die reine Rache. Seit dem Unfall redet Gnoarn nur noch davon, Gnomeregan vom [[Trogg]]befall zu befreien und ein Heilmittel für die Erkrankung, die die Stadt verseucht, zu finden. Helfen kann da vielleicht [[Ozzie Wechselvolt]] in [[Kharanos]], denn er und sein Partner Razzle arbeiten an einer Lösung. Als Mitglied des Zentralkommandos der Untergrundkampftruppe von Gnomeregan, schickt Gnoarn Freiwillige zum Kommandant der Kampftruppe [[Shoni die Schtille|Shoni der Schtillen]] in Sturmwind, um sie im Kampf um [[Gnomeregan]] unterstützen. Desweiteren sucht er auch [[Bingles Blastenheimer]] am [[Loch Modan]], der zu einer Aufklärungsmission über Gnomeregan geschickt wurde und sich seit mehr als einer Woche nicht mehr gemeldet hat. Gnoarn fürchtet, er hat sich selbst in die Luft gejagt.",},
			["Gnoll"] = { content = "#REDIRECT [[Gnolle]]", redirect = "Gnolle",},
			["Gnolle"] = { content = "Die Gnolle zählen zu den jüngsten Völkern [[Azeroth]]s und sind im [[Rotkammgebirge]] und den [[Alterac]]-Bergen des östlichen Kontinents beheimatet. Im Vergleich zu vielen anderen Kreaturen sind diese hyänenartigen Humanoiden zwar vergleichsweise intelligent, aber nach menschlichen Maßstäben nicht besonders schlau. Sie verhalten sich äußerst aggressiv und geraten häufig untereinander in Streit. Es ist hinreichend bekannt, dass sie sich untereinander wegen lächerlicher Dinge in Streit verwickeln, wie zum Beispiel: „Wessen Schatten ist größer?“\r\nDer langläufigen Meinung zufolge könnten die Gnolle ein recht gefährliches Volk sein, wenn sie aufhören würden, sich gegenseitig zu zerfleischen, und eine organisierte Armee aufstellen würden. Trotz allem stellen sie eine notorische Plage für die Königreiche der [[Menschen]] und [[Zwerge]] dar. Waren bisher nur vereinzelte Gnolle in den Ausläufern des [[Wald von Elwynn|Waldes von Elwynn]] zu finden, so konnten in letzter Zeit wiederholt Überfälle auf Bauernhöfe und Dörfer in der ganzen Provinz beobachtet werden. Viele spekulieren, dass sich die bekanntermaßen launenhaften Kreaturen mit einer anderen Macht verbunden haben, die sie mit Waffen, taktischer Anleitung und Magie ausrüstet. Es ist allerdings nicht klar, worauf es die Gnolle anlegen.\r\n==Klans==\r\n* [[Gnolle der Flusspfoten]]\r\n* [[Gnolle der Moderfelle]]\r\n* [[Gnolle der Moosfelle]]\r\n* [[Gnolle der Morastschnauzen]]\r\n* [[Gnolle des Rotkammklans]]\r\n* [[Gnolle der Schattenfelle]]\r\n* [[Gnolle der Schwarzpfoten]]\r\n* [[Gnolle der Waldpfoten]]",},
			["Gnolle der Flusspfoten"] = { content = "Flusspfotengnolle sind brutale Wesen, die entlang der Grenzen des [[Wald von Elwynn|Waldes von Elwynn]] gesehen worden sind. Es ist ein großes Rudel unter Führung von [[Hogger]] und viel zu viele, als dass die [[Menschen]] dort allein mit ihnen fertig werden könnten. Die Gnolle haben sich in den Wäldern südlich des Wachturms eingenistet und eine weitere Gruppe lebt in dem Gebiet nahe des [[Steinhügelsee]]s im Osten. Die Armee von [[Sturmwind]] wird jeden belobigen, der dabei hilft, die [[Gnolle]] zu töten, denn die Marschalls haben erkannt, dass die listigen Gnolle des Flusspfotenpacks eine eindeutige Bedrohung für das Königreich [[Azeroth]] darstellen und gestoppt werden müssen. Zudem hat das Flusspfotenpack die [[Kobolde]], die in den steinigen Höhlen des [[Rotkammgebirge]]s leben, versklavt und in eine Existenz unermüdlicher Plackerei gezwungen.",},
			["Gnolle der Moderfelle"] = { content = "Die [[Gnolle]] der Moderfelle sind ein Gnollklan, der sich der [[Geißel]] angeschlossen hat und nun von dieser in [[Lordaeron]] eingesetzt wird.\r\nDie Massengräber südwestlich von Garrens Schlupfwinkel in [[Tirisfal]] wurden geschaffen, um der eindrucksvollen Anzahl Todesfälle gerecht zu werden, die [[Tirisfal]] erlitt, als die Seuche zum ersten Mal kam. Den Toten in diesen Gräbern blieb der Untod bisher erspart, aber die [[Geißel]] schickt jetzt die Moderfellgnolle dorthin, um die Leichen einzusammeln, um sie zur Verstärkung ihrer Armeen einzusetzen. \r\nDie ursprünglichen Spähberichte über den [[Silberwald]] zeigen, dass die [[Gnolle]] der Moderfelle auch auf einer alten Farm im Norden, nahe dem Todesfeld, einen Stützpunkt haben. \r\n==Moderfellsekret==\r\nDie [[Gnolle]] der Moderfelle besitzen ein Einbalsamierungssekret, das ihnen Leben verleiht. Die [[Apotheker]] glauben, dass der Ursprung der Moderfelle in dieser seltsamen Flüssigkeit, dem Moderfellsekret, liegt, das auch durch ihre Körper fließt. Man konnte ermitteln, dass [[Hexenmeister]]- und Totenbeschwörermagie zur Herstellung des Sekrets verwendet wurden. Dieses Sekret wurde von [[Thule Rabenklaue]] hergestellt. \r\n==Persönlichkeiten==\r\n* [[Madenauge]]",},
			["Gnolle der Moosfelle"] = { content = "Die Moosfellgnolle lebten viele Jahre friedlich im [[Sumpfland]], aber in letzter Zeit wächst ihre Anzahl. Ihre Füße trampeln die Büsche und Blumen des Moores platt, und ihre garstigen Äxte schlagen zu viel Holz für ihre Feuer. Sie befinden sich nicht mehr im Gleichgewicht mit dem Land. Die Moosfelle fällen die Bäume des Sumpflandes und verwenden das Fleisch der Bäume, um sich mit Feuer zu wärmen. Rethiel der Sumpfhüter wird diesen Schmerz nicht länger ertragen. Wenn das Sumpfland überleben soll, müssen diese Gnolle dezimiert werden. Die meisten Moosfelle tragen Feuersteine bei sich, ausgenommen die kleineren Gnolle der Moosfelle und Bastarde der Moosfelle.",},
			["Gnolle der Morastschnauzen"] = { content = "Vom Klan der Gnolle der Morastschnauzen ist nicht viel bekannt, außer dass sie sich auf den Feldern der Nethander-Siedlung im [[Vorgebirge des Hügellands]] herumtreiben.",},
			["Gnolle der Schattenfelle"] = { content = "Ein Feind [[Sturmwind]]s hat sich im östlichen Vorläufer des [[Rotkammgebirge]]s niedergelassen. Dieser verderbte Schurke bedient sich des Übernatürlichen, um die Stadt und ihre Einwohner in Angst und Schrecken zu versetzen. Er betreibt sein übles Geschäft unter dem Namen [[Morganth]]. Und [[Morganth]] kontrolliert auch den Schattenfellklan. Diese [[Gnolle]] tun alles, was er ihnen befiehlt. Leutnant Fangor ist der Anführer der Gnolle der Schattenfelle und arbeitet für [[Morganth]]. Der leuchtende [[Schattenfellanhänger]] ist ein Mittel zur Kommunikation zwischen den Schattenfellgnollen und ihrem Meister.",},
			["Gnolle der Schwarzpfoten"] = { content = "Die Grubenlichtminen im Südwesten von [[Tristessa]] in den [[Geisterlande]] wurden von einem [[Gnoll]]klan überrannt, der sich die Schwarzpfoten nennt. Man findet in den Zinn- und Kupfervorkommen dort [[Grubenlichterz]], aber auch die [[Gnolle]] tragen es mit sich herum.",},
			["Gnolle der Waldpfoten"] = { content = "Die Gnolle der Waldpfoten gehören zu den Eingebohrenen in [[Feralas]] und sie sind mehr als nur ein Ärgernis für die [[Horde]] hier. Sie sind eine konstante Bedrohung für die Existenz von [[Camp Mojache]]. Gnolle sind zwar nicht die Hellsten, aber sie haben die Strategie ihrer jüngsten Aktivitäten irgendwo dokumentiert. [[Gnolle]] behalten Gegenstände, die sie ergattern, und zanken um sie.",},
			["Gnolle des Rotkammklans"] = { content = "Die einheimischen Gnollstreitkräfte sammeln sich im [[Rotkammgebirge]]. Man findet das Lager dieser Gnolle entlang der südlichen Straße in diesem Gebiet. Als ob Orcangriffe nicht genug wären, schleichen jetzt auch noch Gnoll Schläger und Gnoll Mystiker auf dem Hügelkamm nördlich von [[Seenhain]] herum. Man kann sie bellen hören, wenn sie in den Hügeln oberhalb von [[Seenhain]] jagen. Und das Geheul eines Gnolls ist lauter als das aller anderen - das von Jauler, ihrem Anführer. Dieser Gnoll ist nicht umsonst der Anführer seines Rudels. Er ist kein einfacher Köter...",},
			["Gnom"] = { content = "#REDIRECT [[Gnome]]", redirect = "Gnome",},
			["Gnome"] = { content = "Die exzentrischen und äußerst erfinderischen '''Gnome''' sind eines der eigenartigsten Völker [[Azeroth]]s. Angesichts ihrer Technikversessenheit und dem scheinbaren Drang, ständig neue, explosive Wunderwerke der Technik zu entwickeln, erscheint es schon fast wie ein Wunder, dass die Gnome bis zum heutigen Tag überlebt haben. Ihre phantastische Technopolis, [[Gnomeregan]], teilte sich die winterlichen Lande von [[Dun Morogh]] mit den nächsten Verwandten der Gnome, den wackeren [[Zwerge]]n von [[Eisenschmiede]]. Zwar sind auch die Zwerge sehr gut darin, alle Arten von Maschinen zu bauen und zu entwerfen, doch die wahre Ehre für praktisch alle revolutionären Innovationen, die in der zwergischen Technik zu finden sind, gebührt den Gnomen. \r\nIm Zweiten Krieg gegen die orcische [[Horde]] waren die Gnome treue und verlässliche Mitstreiter der Allianz, jedoch verweigerten sie ihren Verbündeten überraschenderweise jegliche Hilfe während der Invasion der [[Brennende Legion|Brennenden Legion]]. Auch wenn die gnomischen Entwürfe dazu beitrugen, den Krieg gegen die Dämonen zu Gunsten der [[Allianz]] zu entscheiden, waren die [[Menschen]] und [[Zwerge]] dennoch schockiert. Die Gnome hatten nicht einen einzigen ihrer [[Gyrokopter]]piloten oder Mechaniker geschickt. \r\nNach dem Ende des Krieges erfuhr die [[Allianz]], welch schreckliches Schicksal die Gnome ereilt hatte. Eine uralte, finstere Macht hatte sich aus dem Schoß der Erde erhoben und [[Gnomeregan]] angegriffen. Anstatt ihre Verbündeten um Hilfe zu bitten und so den Sieg über den größeren Feind, die Dämonen der [[Brennende Legion|Brennenden Legion]], zu gefährden, entschlossen sich die Gnome, ihre Stadt alleine zu verteidigen. Doch obwohl sie erbittert um ihre geliebte Heimat kämpften und viele Gnome ihr Leben für die Verteidigung der Stadt opferten, war [[Gnomeregan]] unweigerlich verloren. Mehr als die Hälfte des Volks der Gnome kam beim Fall [[Gnomeregan]]s ums Leben und noch mehr erlitten ein schlimmeres Schicksal: Sie wurden zu [[Lepragnom]]en. Die wenigen, die entkommen konnten, flohen in die nahe gelegene [[Eisenschmiede]]. Nachdem sie nun wieder mit der [[Allianz]] vereint sind, schmieden die findigen Gnome bereits Pläne, ihre verlorene Heimat zurückzuerobern und ihr Volk in eine bessere Zukunft zu führen. \r\n==Arten==\r\nNeben den [[Lepragnom]]en gibt es eine weitere Abart der azerothanischen Gnome: Die [[Sandgnom]]e der Knochenwüste aus der [[Scherbenwelt]]. \r\n* [[Lepragnom]]\r\n* [[Sandgnom]]\r\n==Klassen==\r\n* [[Gnomen Hexenmeister]]\r\n* [[Gnomen Krieger]]\r\n* [[Gnomen Magier]]\r\n* [[Gnomen Schurke]]\r\n'''Quelle:'''",},
			["Gnomeregan"] = { content = "Das phantastische Technopolis '''Gnomeregan''' war seit ungezählten Generationen die [[:Kategorie: Hauptstadt|Hauptstadt]] der [[Gnome]], eine Stadt, wie es sie davor noch nie in [[Azeroth]] gegeben hatte, wo selbst die kühnsten Träume der gnomischen [[Ingenieur|Tüftler]] wahr wurden. Es war das erstaunlichste Wunder, welches die Gnome durch den grenzenlosen Einfallsreichtum ihrer Ingenieurskunst vollbracht hatten. Eingebettet zwischen den stürmischen Gipfeln von [[Dun Morogh]] zeugen jedoch nur noch die Ruinen der Hauptstadt von dieser stolzen Vergangenheit. \r\n==Geschichte==\r\nWährend sich die Invasion der Brennenden Legion wie ein dunkler Schatten über Azeroth legte, wurde auch Gnomeregan von einer uralten, barbarischen Bedrohung heimgesucht. Das chaotische Volk der Troggs, das die Titanen vor Jahrtausenden von der Erdoberfläche verbannt hatten, war aus seinem Gefängnis freigebrochen. Und die Wellen der jüngsten Invasion der mutierten [[Troggs]] in [[Dun Morogh]] erreichten schließlich auch die Wunderwelt der Gnome. \r\nDa die Gnome wussten, dass die Allianz schon selbst um ihr Überleben kämpfen musste, entschieden sie sich, diese Schlacht alleine auszufechten. Die Gnome kämpften hart und beherzt, um ihre geliebte Stadt zu retten. In einem Akt der Verzweiflung befahl [[Hochtüftler Gelbin Mekkadrill]], die Tanks für den radioaktiven Abfall der Stadt nach Gnomeregan zu entleeren und so die Troggs zu vernichten. Viele Gnome brachten sich vor den radioaktiven Dämpfen und dem Giftmüll in Sicherheit und warteten darauf, dass die Troggs entweder starben oder flohen. Doch statt zu sterben oder zu fliehen, verwandelten sich die mutierten, brutalen Troggs in mutierte, brutale und radioaktive Troggs, die nun obendrein noch wütender waren als zuvor (sofern das überhaupt möglich war). Weite Teile Gnomeregans wurden unbewohnbar, viele Unschuldige starben oder erlitten schwere Vergiftungen. Die Stadt war unwiederbringlich verloren und ein großer Teil der gnomischen Kultur wurde ausgelöscht. \r\nDie [[Gnome]], die nicht von der Radioaktivität oder den Toxinen getötet wurden, mussten fliehen und in der nahegelegenen Stadt [[Eisenschmiede]] Schutz suchen. Dort ist [[Hochtüftler Gelbin Mekkadrill]] momentan dabei, tapfere Helden für die Zurückeroberung der gnomischen Hauptstadt zu suchen. Die einstigen Bewohner von Gnomeregan leben nun in Eisenschmiede im Exil und sind Verbündete der [[Allianz]]. \r\nDie Aussätzigen jedoch, die gegenwärtig außerhalb von Gnomeregan leben, wurden durch ihre Leiden in den Wahnsinn getrieben und greifen jeden, dem sie begegnen, ohne Vorwarnung an. Nach genauerer Analyse der Situation in Gnomeregan sieht es so aus, als hätten die Gnome nicht nur dabei versagt, die Troggs auszulöschen, sondern als hätten sie dabei auch noch einen Großteil des Volkes der Gnome in schreckliche, hirnlose, bösartige [[Lepragnome]] verwandelt. In der Nähe von Gnomeregan wimmelt es von verseuchten und daher unberechenbaren Lepragnomen. Gerüchten zufolge soll Mekkadrills ehemaliger Berater, der [[Robogenieur Thermadraht]], sein Volk verraten haben, indem er die Invasion geschehen ließ. Der wahnsinnige [[Gnom]] ist in Gnomeregan zurückgeblieben, wo der Technofürst nun neue sinistre Pläne austüftelt.\r\nDes weiteren zog es einige [[Gnome]] nach [[Sturmwind]] das sie kurzer Hand okkupierten und zu ihrer neuen [[:Kategorie: Hauptstadt|Hauptstadt]] [[Gnomwind]] erklärten.\r\n==Die Instanz==\r\nGnomeregan ist vorwiegend für die Allianz gedacht, aber auch die Horde hat hier einige Quests. Die Instanz befindet sich in Dun Morogh am westlichen Rand der Karte. Der Eingang wird von einigen Wachen bewacht.Im Inneren führt ein großer, runder Fahrstuhl in die Tiefe. Vom Fahrstuhl aus muss man sich einen Weg durch die Belagerer zum eigentlichen Eingang der Instanz - Instanzportal bahnen. Am Ende des Ganges, der vom Fahrstuhl aus in die erste, große Halle führt gehts nach links und dann immer an der linken Wand entlang. Geht man am Ende des Ganges erst geradeaus und hinten rechts galangt man zur Werkstatttür - Hintereingang, durch die man mitten in die Instanz gelangt. Für die Werkstatttür ist ein entsprechender Schlüssel nötig, den man in der Instanz findet. Schurken können die Tür mit Schlösserknacken öffnen. \r\n==Technische Errungenschaften==\r\nEs heißt, dass in Gnomeregan Bots und Mechs herumlaufen wie Vieh auf der Weide. Vor zwei Jahren noch hat man sich jedesmal darüber lustig gemacht, wenn die Rede auf Gnomentechnologie kam. Diese Zeiten haben sich definitiv geändert. Jetzt haben die Gnome unter [[Robogenieur Thermadraht]] eine neue Maschine gebaut, die besser ist als alle Schreddermodelle der Goblins zusammen. Zu den technischen Errungenschaften zählen u.a.:\r\n* [[Funkelmat 5200]]\r\n* [[Grundlegendes Artifix]]\r\n* [[Matrix-Prägograph 3005-D]]\r\n* [[Techbot]]\r\n==NSC == \r\n* '''Kernobee''' - Kernobee ist ein verletzter Goblin in Gnomeregan. Das Letzte, an das er sich erinnert, ist, wie er von einer Gruppe [[Dunkeleisenzwerge]] gefangen, halb tot geprügelt und dann hier zu diesen schmutzigen Troggs geworfen wurde. Der Plan ist, dass man ihn zum Ausgang bringt. Wenn man es lebend aus Gnomeregan herausschaffen sollte, geht man nach [[Beutebucht]] und lasst [[Scooty]] wissen, dass Kernobee nach [[Ratschet]] gegangen ist, um [[Tüftelwiz]], einen Ingenieurslehrer dort, zu warnen, dass die Dunkeleisenzwerge in die Herstellung der Supermaschine verwickelt sind.\r\n* '''Onin MacHammar''' - Onin MacHammar ist ein listiger Zwerg und hat sich bei den [[Lepragnome]]n versteckt. Er sieht fast jeden Tag einen monströsen [[Dampfpanzer]] vorbeirollen. Seine Kontakte im Osten sagen ihm, dass der Panzer in [[Eisenschmiede]] startet, im [[Steinbruch von Gol'Bolar]] seine Ladung abholt, zum Auftanken in [[Kharanos]] hält und dann aus einem unerfindlichen Grund den langen Weg um Gnomeregan herum fährt, ehe er seine Ladung in Eisenschmiede ablädt.\r\n==Bosse==\r\n* [[Robogenieur Thermadraht]]",},
			["Gnomwind"] = { content = "Gnomwind ist vielen auch bekannt als [[Sturmwind]] und die neue Wahlheimat der [[Gnome]] nachdem ihre Stadt [[Gnomeregan]] von den [[Troggs]] heimgesucht wurde. Die [[Gnome]] sind die wahren Herrscher der Stadt. Auch wenn die [[Menschen]] immernoch meinen die Kontrolle über '[[Sturmwind]]' zu haben sind es die [[Regentinnen von Gnomwind]] die die Fäden ziehen.\r\nDie drei Regentinnen [[Liraxxa]], [[Dilia]] und [[Thalsia]] sind selbsternannte Königinnen. Derzeit ist die politische Lage unklar, denn in den letzten Tagen wurde politisch einiges bewegt. [[Thalsia]], Königin des Irrsinns ist neidergemeuchelt worden auf der Flucht vor der [[Heilige Inquisition|Heiligen Inquisition]]. Als es später zur Diskussion kam, ob und wie man die Königin wiederbeleben kann, spaltete sich die Meinung der zwei verbleibenen Königinnen und es kam zum Bruch. [[Liraxxa]] forderte, dass man keinesfalls versucht, [[Thalsia]] zu beleben, da vieles schiefgehen kann. [[Dilia]] hingegen war gradezu besessen von dem Gedanken und so bildeten sich zwei Lager. Als [[Dilia]] dann mit ein paar treuen Gnomen die Wiederbelebung vollzog kam es zu einem Zwischenfall der dazu führte, dass [[Thalsia]] scheinbar von einer falschen und bösartigen Seele in Besitz genommen wurde. [[Dilia]] versprach zwar, sie sofort wieder zurückzuschicken wenn etwas schiefgeht, jedoch hielt sie ihr Wort nicht und schleppte die nach Blut dürstende zum Marktplatz Gnomwinds, wo es erst nach mehreren Verletzten gelang, sie zu stoppen. Von [[Thalsia]] blieb nicht mehr viel übrig, da man recht gründlich war mit einem Kriegshammer. [[Dilia]] ist seitdem untergetaucht. Von [[Liraxxa]] hörte man ebenfalls nichts, jedoch dürfte sie die letzte Königin sein, die noch fähig ist, ihr Amt auszuüben. \r\nDunkle Zeiten für Gnomwind....\r\n'''Zitat Königin Dilia:'''\r\n\"So lange der Gnomwindsche Gnom an etwas glaubt, so lange wird es Gnomwind geben. Ihr könntet uns absetzen, einsperren, töten, doch wird das den Glauben an ein neues Zuhause für Gnome nicht versiegen lassen. Gnomwind ist ein Teil unserer selbst und liegt in den Herzen gnomwindscher Gnome. Dass nicht alle diesen Weg folgen, ist uns, den Königinnen, bewusst und wir akzeptieren es. Sie scheinen bessere Erfahrungen mit anderen Rassen gemacht zu haben, als wir. Wir jedoch sind die Gepeinigten, die Unterdrückten, die Ausgelachten und Heimatlosen. Mit Gnomwind setzen wir einen Maßstab. Wir rütteln euch wach. Zeigen, dass es uns gibt und dass wir nicht zu behandeln sind, wie eure Menschenkinder! Mit Gnomwind vermitteln wir den Einsamen unter uns ein Gefühl von heimatlicher Wärme. Ihr könnt es nicht nachvollziehen, weil ihr euer Sturmwind *abfällig* habt. Wir wollen gleichwohl respektiert werden. Auch wir sind Streiter der Allianz und tragen unseren Teil dazu bei. Gnomwind ist mehr als nur ein Wort. Für manche von uns ist es alles! !\"",},
			["Go'Sheks Hof"] = { content = "Die beiden [[Allianz]]-Späher [[Quae]] und [[Kinelory]], haben sich zur Go'Sheks Hof im [[Arathihochland]] aufgemacht und haben seit Tagen nichts von sich hören lassen. Sie beobachten den Hof und es ist noch gar nicht so lange her, dass sie einen Kurier aus dem kleinen Haus südlich haben kommen sehen. Sie glauben, dass der Kurier der [[Verlassene]]n Notizen nach [[Tarrens Mühle]] bringen könnte und sie werden deshalb hier noch ein Weilchen bleiben. [[Apotheker Jorell]] lebt u.a. auf diesem Hof und es scheint, als hat [[Apotheker Jorell]] an einigen tödlichen Experimenten hier gearbeitet. [[Kinelory]] erzählt viel, aber vielleicht sind ihre Beobachtungen ein Hinweis auf eine neue Seuche.",},
			["Goblin"] = { content = "#REDIRECT [[Goblins]]", redirect = "Goblins",},
			["Goblindampfpanzer"] = { content = "#REDIRECT [[Dampfpanzer]]", redirect = "Dampfpanzer",},
			["Goblins"] = { content = "Die genialen [[Alchimist]]en der Goblins sind wahre Meister im Umgang mit Chemikalien, explosiven Stoffen und eigentümlichen mechanischen Apparaten. Sie stammen aus dem [[Südmeer]] von der [[Insel Kezan]]. Als Konstukteure der [[Zeppelin]]e haben sie es geschafft, den Naturgesetzten zu trotzen. Die schwerfälligen Luftschiffe sind zwar nur mühsam zu manövrieren, können aber problemlos weite Strecken zurücklegen. Diese sinnreiche Erfindung ermöglicht es den Goblins, über die Lande zu gleiten und zahlende Passagiere an alle Enden der Welt zu bringen. \r\nEinige glauben, dass auch die erschreckenden [[Erntegolem]]s von den verrückten Goblins konstruiert wurden. Obwohl niemand Schlüsse über die Herkunft dieser mechanischen Monstrositäten ziehen kann, wird spekuliert, dass die [[Defias]]-Bruderschaft sie bauen ließ, um die heimischen Bewohner [[Westfall]]s zu vertreiben. Auch sind sie wahnsinnig genug, sich selbst in bizarren, alchemistischen Prozessen in abstrakte Monster zu verwandeln, die [[Hobgoblin]]s. \r\nDie Goblins dienten dem Aspekt der Erde, Neltharion, der später als [[Todesschwinge]] berühmt wurde.Sie schmiedeten die [[Dämonenseele]] und die magischen Panzerplatten aus [[Adamantium]] für den Dunklen.Noch während des zweiten Krieges waren die Goblins für ihre unglaubliche Zerstörungswut bekannt. Das aufsässige und unberechenbare Volk erwies sich als unverzichtbar für die orcische [[Horde]]. Aber ihre Gier veranlasste sie dazu, ihren eigenen Weg einzuschlagen. Bazare und Laboratorien der Goblins sind in der ganzen Welt zu finden. Die gerissenen Handelsprinzen landeten sogar an den Küsten [[Schlingendorntal]]s und begannen dort mit ihren Minen- und Abholzarbeiten. Die Goblins konnten eine angreifbare Position in diesen abgelegenen Gebieten halten, kommen aber immer mehr unter Druck von den [[Dschungeltrolle]]n, die ihr einstiges Heimatland von allen Eindringlingen befreien wollen. \r\n==Gebäude==\r\n* [[Goblin Bazar]]\r\n* [[Goblin Laboratorium]]\r\n* [[Goblin Werft]]\r\n==Klassen==\r\n* [[Goblin Dampfkrieger]]\r\n* [[Goblin Tüftler]]\r\n==Organisationen==\r\n* [[Dampfdruckkartell]]\r\n* [[Kokelwälder]]\r\n* [[Tüftlerverband]]\r\n* [[Venture Company]]\r\n'''Quelle:'''",},
			["Goblinschredder"] = { content = "'''Goblinschredder''' sind wahre Meisterwerke der [[Goblin]]ischen [[Ingenieur]]skunst. Sie sind große Maschinen, die mit einer Säge ausgestattet sind und so meisterhafte Holzfäller sind. Schredder können eine stattliche Anzahl Bäume fällen und das Holz ohne Probleme zu einem Sammelpunkt bringen. Im Krieg können sie auch als Kampfroboter eingesetzt werden und mit ihrer mächtigen Säge Feinde zerteilen. Auf ihnen sitzt immer ein [[Goblin]], der den Schredder steuert.\r\n==Goblinschredder als Belagerungswaffe==\r\nGoblinschredder kommen als Belagerungswaffe in Schlachtfeldern wie dem [[Tausendwintersee]] oder den [[Sande von Ulduran|Sanden von Ulduran]] zum Einsatz und dienen als Anti-Luft-Belagerungsmaschinen. Die Anti-Luft Raketen haben eine sehr hohe Reichweite. Goblinschredder fungieren wie eine persönliche Schutzrüstung. Sobald der Goblinschredder zerstört ist, springt der Spieler heraus und kämpf selbst weiter. Das Sägeblatt kann als Nahkampfwaffe benutzt werden. Der Goblinschredder kann wie mit Raketenschuhen in die Luft springen und somit Hindernisse überwinden. Doch er ist sehr verwundbar gegen Angriffe anderer Belagerungsmaschinen.",},
			["Goc"] = { content = "Der [[Gronn]] Goc im [[Schergrat]] ist der Herr der [[Oger der Speerspießer]] und einer der sieben Söhne von [[Gruul]] dem Drachentöter. Gocs Altar steht außerhalb von [[Gruuls Unterschlupf]].",},
			["Goggeroc"] = { content = "'''Goggeroc''' ist ein schlummernder [[Irdene]]r in einer Höhle im [[Steinkrallengebirge]].",},
			["Goldhain"] = { content = "Goldhain ist der zentrale Knotenpunkt im [[Wald von Elwynn]]. Es liegt an der Straße, hinter den Grenztoren von [[Nordhain]] an den Ufern des Kristallsees. Hier gastiert auch alle zwei Monate [[Dunkelmonds Jahrmarkt]], samt seiner zahlreichen Attraktionen. Es gibt keinen besseren Platz für Ruhe und Entspannung als das Gasthaus Zur Höhle des Löwen.\r\n==Geschichte==\r\nIn der Endphase des [[Der Erste Krieg|Ersten Krieges]] standen nur noch zwei Städte zwischen den vorrückenden orkischen Truppen und der Festung [[Sturmwind]]. Die beiden Partnerstädte Goldhain und [[Mondbruch]] wurden jedoch von der [[Horde]] zerstört. Nach dem [[Der Zweite Krieg|Zweiten Krieg]] wurde Goldhain wieder neu aufgebaut. \r\n==Personen==\r\n* '''Gastwirt Farley''' leitet das Gasthaus \"[[Zur Höhle des Löwen]]\". \r\n* '''Marschall Dughan''' kümmert sich um die Verteidigung von Goldhain.\r\n* '''Remy \"Zweifach\"''' hat Marschall Dughan bereits wegen der [[Murlocs]] gewarnt, aber der macht sich größere Sorgen wegen der [[Gnolle]] und der Banditen. Dughan ist nicht überzeugt davon, dass die [[Murlocs]] eine Gefahr darstellen, doch Remy will den Marschall dazu bringen, dass er Verstärkung in den Osten schickt. Im Tausch gegen Goldstaub macht er einem den besten Preis in der Stadt.\r\n* '''William Pestle''' wohnt im Gasthaus \"[[Zur Höhle des Löwen]]\". Sein Bruder und er führen in [[Sturmwind]] eine Apotheke und er ist hier, weil er große Kerzen sucht, ihres Wachses wegen. Große Kerzen kann man von [[Kobolde]]n bekommen - und er hat Gerüchte gehört, dass [[Kobolde]] sich in den Minen von Elwynn eingenistet haben. In [[Sturmwind]] wartet sein Bruder Morgan auf die Lieferung der Kerzen, doch er hat selbst nicht die Zeit, um sich auf die Reise zu begeben. Er könnte auch einen Unsichtbarkeitsschnaps für Maybell Steinfeld brauen, damit sie sich aus den Weinbergen der Maclures fortstehlen und Tommy Joe sehen kann. Aber um den Schnaps herzustellen, braucht er etwas Kristalltang. Die Wirkung sollte so lange anhalten, dass sie Tommy Joe besuchen kann.",},
			["Goldnebel"] = { content = "'''Goldnebel''' ist eine kleine Ortschaft im Nordwesten der [[Geisterlande]] und wurde von den Geistern der [[Hochelfen]] besetzt, die dort einst lebten. Sie wurde beim Krieg gegen die [[Geißel]] zum größten Teil zerstört. Heute ist die Ortschaft verlassen und fest in Hand der [[Geißel]]. Es scheint dies eine der bevorzugten Taktiken zu sein, derer sich die Geißel bedient. Um nach Goldnebel zu gelangen, folgt man der westlichen Straße, die aus [[Tristessa]] hinaus führt. Der Weg nach Goldnebel führt den [[Elrendar]] entlang nach Westen.",},
			["Goldweberpass"] = { content = "Im Nordwesten des Lagers \"[[Verteidigers Ruh]]\" auf der [[Blutmythosinsel]] liegt der Goldweberpass. Die Auswirkungen der Kristallverseuchung auf die Mythosfänger und Mythosspinnen, die der Absturz der [[Exodar]] auf dieses Gebiet brachte, sind unverkennbar, da die [[Spinnen]] im Goldweberpass extrem groß und aggressiv sind. \r\nVor kurzem ist hier ein Forschungsteam der [[Blutwacht]] verschollen. [[Achelus]] war vor etwa einer Woche mit seinem Forschungsteam auf einem Erkundungstrip im Westen der [[Blutmythosinsel]], im Goldweberpass, als sie plötzlich von blutdurstigen [[Spinnen]] angegriffen wurden. Er schaffte es zu fliehen, aber sein Team hatte nicht so viel Glück, denn seine Forschungskollegen wurden von einer ganzen Horde dieser [[Spinnen]] aus dem Hinterhalt überrascht. Es war ein blutiges Gemetzel. Ihre Anführerin fiel unglaublich schnell über sie her und spann sie in Kokons ein. Nachdem die Forscher eingesponnen waren, begannen die Spinnen neben ihnen Eier zu legen. Die gefangenen [[Draenei]] sollten als Futter für ihre Jungen dienen. Nur [[Forscher Cornelius]] schaffte es noch, sich aus dem Kokon freizuschneiden und floh.",},
			["Golem"] = { content = "Golems zählen zu den [[Elementare]]n und sind künstlich geschaffene [[Konstrukte]] aus verschiedenen Arten von Stein. Sie können an vielen Orten, meistens um Dunkeleisen-Lager herum gefunden werden. Aber die meisten Golems existieren in und um [[Dalaran]], denn die [[Magier]] dort haben sie geschaffen, damit sie manuelle Tätigkeiten ausführen und ihren mystischen Besitz bewachen. Gewisse abtrünnige Zauberer haben sich auch eigene Golems geschaffen, um ihre geheimen Verstecke zu beschützen. Wie die meisten [[Konstrukte]], sind auch Golems auf magische Weise gegen Zauber gefeit, damit feindliche [[Magier]] sie nicht gegen ihre Schöpfer einsetzen können. Im Allgemeinen betrachtet man Golems als dumm, allerdings sind auch Fälle belegt, wonach Golems frei herumwanderten, ohne dass ihre Meister sie kontrollierten. Wohin diese vagabundierenden [[Konstrukte]] gehen oder was sie suchen, ist allerdings ein Rätsel.\r\n==Arten==\r\nFolgende Arten von Golems sind bekannt:\r\n* [[Anubisath]]\r\n* [[Horusath]]\r\n* [[Obsidianstatue]]\r\n* [[Obsidianzerstörer]]\r\n* [[Steingolem]]\r\n==Persönlichkeiten==\r\nZu den berühmtesten Golems zählen:\r\n* [[Abgesandter Roman'khan]]\r\n* [[Moam]]\r\n* [[Ossirian der Narbenlose]]",},
			["Golemagg der Verbrenner"] = { content = "'''Golemagg der Verbrenner''' ist ein [[Geschmolzene Riesen|Geschmolzener Riese]] im [[Geschmolzener Kern|Geschmolzenen Kern]], der von zwei mächtigen [[Kernhund]]en begleitet wird.\r\n==Fähigkeiten==\r\n* '''Erdbeben''' - Sinken die Lebenspunkte von Golemagg unter 10%, so beginnt Golemagg auf den Boden zu stampfen, was bei in der Nähe befindlichen Feinden 1500 Schaden zufügt. \r\n* '''Magmaspritzer''' - Magmaspritzer fügen alle 3 Sekunden 50 Punkte Feuerschaden zu und verringern die Rüstung um 250. Dieser Debuff kann nicht entfernt werden und kann stacken, d.h. in großer Anzahl sehr unangenehm werden, vor allem für den Maintank.\r\n* '''Pyroblast''' - Pyroblast fügt sofort 1500 Schaden zu und weitere 800 über die 12 Sekunden verteilt.",},
			["Golems"] = { content = "#REDIRECT [[Golem]]", redirect = "Golem",},
			["Golganneth"] = { content = "Golganneth ist der neue Champion des [[Pantheon]]s, nachdem [[Sargeras]] sich von seinen Brüdern losgesagt hatte. Er kämpft täglich gegen zahlreiche ,nicht näher klassifizierte Unholde aus fernen Galaxien, die sich der beschränkte Geist der sterblichen nicht einmal im Ansatz vorstellen kann. Bewaffnet ist er mit der [[Hoheklinge des Pantheons]], das alte Schwert von Sargeras, welches bei seiner Lossagung in zwei Teile zerbrach. Sargeras führt die eine Hälfte gegen die Werke der [[Titanen]] ,während Golganneth den anderen Teil der heiligen Klinge gegen die Ausgeburten des Chaos schwingt.",},
			["Gombrim Ambossar"] = { content = "Mit '''Hochkönig Gombrim Ambossar''' bestieg der erste König aller [[Zwerge]] den Thron von [[Eisenschmiede]] im Jahre —1,320 und läutete damit die Ära des [[Ambossar Klan]]s und ihrer Hochkönige ein.",},
			["Gor'mul"] = { content = "Gor'mul ist ein alter deprimierter Orc in [[Hammerfall]] im [[Arathi-Hochland]]. \r\nDie anderen haben versucht, es ihm gemütlich zu machen, ihn aufzumuntern, haben ihm Geschichten erzählt von der mächtigen Stadt in [[Orgrimmar]] in [[Kalimdor]], aber nichts, gar nichts hat ihn berührt. Geschichten vom jungen Kriegshäuptling, [[Thrall]], der die Rüstung und den Hammer von [[Orgrim Schicksalshammer]] trägt aber vielleicht. \r\nEr erinnert sich, als wär es gestern gewesen. So viele Jahre ohne Hoffnung, mit Holz und Stahl, die ihn an diesen fürchterlichen Ort banden. Und dann endlich, endlich! \r\nDa war der Kriegshäuptling. [[Orgrim Schicksalshammer]] in seiner Mitternachtsrüstung, sein Kriegshammer hoch erhoben. Es war zu schrecklich. Dass der Schlag eines Feiglings den größten Helden niederschlagen konnte... Er kam von hinten angestürmt auf seinem Pferd und dann rammte er seine Lanze einfach durch ihn hindurch. Er fiel auf die Knie. \r\nWelche Hoffnung gab es noch? \r\nWelche Hoffnung gibt es noch... \r\nWarum Tor’gan ihm gegenüber Gnade empfindet, geht über seinen Verstand. \r\nGnade wurde ihm verweigert, als es ihm nicht vergönnt war, mit seinem Kriegshäuptling im Kampf zu sterben. \r\nDas Schicksal hat ihm wirklich einen harten Schlag versetzt ...",},
			["Gordunnikobalt"] = { content = "Gordunnikobalt findet man bei den [[Oger der Gordunni|Ogern der Gordunni]] in [[Feralas]]. Es ist ein sehr interessantes Mineral, doch keiner weiß, was die [[Oger]] damit so vorhaben. Aber sie passen höllisch gut auf dieses Zeug auf. Sie lassen es nicht einfach herumliegen. Sie vergraben es, damit andere es nicht in die Finger bekommen.",},
			["Gorgrom der Drachenfresser"] = { content = "Der [[Gronn]] Gorgrom der Drachenfresser im [[Schergrat]] ist Herr der [[Oger der Blutschläger]] und einer der sieben Söhne von [[Gruul]] dem Drachentöter. Gorgroms Altar steht in [[Felsmok]], wo er die Opfer der [[Oger]] entgegen nimmt.",},
			["Gorloc"] = { content = "'''Gorlocs''' sind eine Gruppe hochentwickelter [[Murlocs]], welche im [[Sholazarbecken]] auf [[Nordend]] hausen. Sie sehen sich als rechtmäßige Wächter der Technologie der Titanen und liegen mit den [[Wolvar]] vom Stamm der Grollherzen im Krieg. Sie stellen die Fraktion \"[[Die Orakel]]\".",},
			["Gossensprache"] = { content = "Gossensprache ist ein Dialekt der [[Gemeinsprache]]. Ursprünglich wurde er von den zwielichtigen Gestalten von [[Lordaeron]] entwickelt, doch von den [[Verlassenen]] als eigene Sprache adaptiert und so verändert, dass die sprache auch ohne Unterkiefer oder Kiefermuskeln gesprochen werden kann.\r\nDas Ergebnis war ein undefinierbarer Kauderwelsch, den auch wirklich nur [[Verlassene]] sprechen und verstehen können. Viel Verlassene haben ohnehin [[Orkisch]] gelernt, um sich mit ihren Verbündeten besser verstehen zu können.",},
			["Gothik der Ernter"] = { content = "'''Gothik der Ernter''', ehemals bekannt als [[Gothik der Seelenjäger]], ist mit der Nekropole [[Acherus]] in die [[Todesbresche]] im den [[Östlichen Pestländern]] gereist.",},
			["Gott"] = { content = "Es gibt keine einfachen, festgelegten Regeln, was man braucht, um in Warcraft ein Gott zu sein, außer der Tatsache, dass sie alle unsterblich sind. Götter können körperlos sein, wie [[Elune]], oder einen physischen Körper besitzen.\r\nGötter sind weder allwissend noch allmächtig. Der Seelenschinder ist ein gutes Beispiel dafür. Viele der [[Trolle]] im [[Gurubashi]]-Imperium erhoben sich gegen seine blutige Herrschaft. Es gelang ihnen, seinen Avatar zu vernichten und ihn von der Welt [[Azeroth]] zu verbannen. Auch die [[Titanen]], die ja selbst keine Götter waren, besiegten die [[Alten Götter]] und sperrten sie tief unter der Erde ein.\r\nEin Gott kann auf mehrere Orte zugleich Einfluss nehmen. Doch die Macht selbst eines Gottes ist begrenzt. Sonst wäre es ja zum Beispiel gar nicht möglich gewesen, die Alten Götter einzusperren. Trotzdem kann auch ein eingesperrter, schlafender oder auf andere Art geschwächter Gott noch immer einen Einfluss auf seine Umgebung nehmen, bewusst oder unbewusst. Die Entwicklung der [[Qiraji]] soll angeblich auf einen solchen zufälligen Einfluss zurückzuführen sein.\r\nKann man einen Gott jemals wirklich vernichten, seine Existenz auf Dauer beenden? Unglücklicherweise ist das keine rein philosophische Diskussion mehr, sondern eine Frage des Überlebens. Die Priester von [[Hakkar]] dem Seelenschinder haben es vor nicht allzulanger Zeit geschafft ihren hungrigen Gott auch physisch nach Azeroth zu beschwören. Doch noch schlimmer ist, dass [[C'Thun]] wieder erwacht ist, sich befreit hat und nun aus den Tiefen des Planeten aufgetaucht ist. Viele tapfere Helfen finden sich zusammen, in der Hoffnung diese zwei grausammen Götter zu besiegen.\r\nZu anderen verehrten Kräften zählen das [[Heilige Licht]],[[Vergessender Schatten]] und die [[Elementargeister]] der [[Naturanbetung]].\r\nBekannte Götter\r\n[[C'Thun]]\r\n[[[[Elune]]\r\n[[Sargeras]]\r\n[[Lichkönig]]\r\n[[Hakkar]]\r\n[[Alte Götter]]\r\n[[Loa]]\r\n[[Halbgötter]]\r\n[[Titanen]]",},
			["Gozer"] = { content = "== Gozer Britzelfuxx==\r\nGozer Britzelfuxx ist ein mehr oder weniger ooc-gespielter Charakter, der angespielt das Angespielte annimmt und auch zu spielen weiss. Leider fehlt der Person hinter Gozer die Zeit und die Muße sich tief ins RP abtauchen zu lassen.\r\nDie meiste Zeit verbringt Gozer in Instanzen und wenn sie sich mal eine kleine Auszeit gönnt, dann findet man sie entweder in Eisenschmiede vor dem Auktionshaus oder vor der Seherbank, wo sie ihre beruflichen Fähigkeiten gegen Honorar anbietet.\r\n==Erfahrung==\r\nGozer Britzelfuxx ist weit herumgekommen in ihrem Leben. Sie kennt jede Höhle und jedes Gemäuer von innen, auch wenn sie sich sehr oft verläuft. Sie hat Zul'Gurub und die Ruinen von Ahn'Qiraj gesäubert, den geschmolzenen Kern ein paar Grad kühler gemacht und Nefarian im Pechschwingenhort den Gar(r) ausgemacht. Des Weiteren hat sie Karazhan und Zul'Aman befreit und den Schlangenschrein, sowie das Auge des Sturms bezwungen. Gozer hat Gruul getötet und Magtheridon das Fürchten gelehrt. Archimonde gab ihr in Demut sein Schwert und Illidan war nach seiner Niederlage zu erschöpft um ihr den Schädel des Gul'Dan zu überreichen. Er versprach aber, das noch nachzuholen.\r\n===Ingenieurskunst===\r\nGozer Britzelfuxx ist eine hochbegabte Ingenieurin, die so ziemlich alles bauen kann was bisher erfunden wurde. Zur Zeit arbeitet sie an einer Weiterentwicklung dieser wirklich tollen Brillen für Hexenmeisterinnen...\r\n===Verzauberungskunst===\r\nNebenbei, was heisst eigentlich nebenbei, ist sie auch noch Verzauberungsgroßmeisterin in Perfektion. Gozer beherrscht so ziemlich jede Verzauberung die man sich nur vorstellen kann - lediglich Meister Aran und der fiese Siechhuf wollten ihre Geheimnisse nicht preisgeben.\r\n==Wesen==\r\nGozer Britzelfuxx ist ungeduldig, zielstrebig, energisch und weiss immer was sie will. Sie ist Hexenmeisterin mit Leib und Seele und sie weiss ihre Fähigkeiten in allen Lebenslagen zu ihren Gunsten zu nutzen. Auch besteht Gozer darauf eine HexenMEISTERIN zu sein, denn hier trennt sich die Spreu vom Weizen (wie ihr Opa immer zu sagen pflegte). Solltest du also mit Gozer nicht aneinander geraten wollen (und mal ehrlich, welches Wesen bei klarem Verstand würde das wirklich wollen?), dann solltest Du immer darauf achten sie als Hexenmeisterin anzusprechen.\r\nEingeweihte wissen allerdings auch, dass Gozer trotz ihrer schwarzen Seele ein gutes Herz hat und sie stets hilfsbereit gegenüber Wesen (besonders Gnomen) ist, die ihr am Herzen liegen.\r\n==Gruppenverhalten==\r\nGozer lebt relativ zurückgezogen und meidet nach Möglichkeit den Kontakt zu unbekannten Gruppierungen. Sie hat ihre festen Ansprechpartner für Unternehmungen aller Art und weicht nur selten von diesen Konstellationen ab. Die Mitstreiter ihrer Schlachtgruppe [[Die Schatten]] sind für sie immer erster Ansprechpartner.\r\nEinzige Ausnahmen bildet [[Hildegard Sprigglespruxx]], welche Gozer nicht zuletzt durch ihre tolle Forschungsarbeit für das [[Institut für Pfuschkunde]] in ihr Herz geschlossen hat.\r\n==Ziele==\r\nDie momentanen Ziele von Gozer sehen so aus, dass sie unbedingt Baron Totenschwurs Streitross seinen toten Fingern eintreissen , bei allen ihr möglichen Fraktionen den ehrfürchtigen Ruf erlangen möchte und [[Kil'Jaeden]] in die Flucht schlagen noch bevor die Evolution zuschlägt.\r\n===Arsenallink===",},
			["Grabhügel von Ban'ethil"] = { content = "Die Grabhügel von Ban'ethil sind eine verwinkelte Höhlenanlage in [[Teldrassil]], deren Umgebung von den [[Furbolgs der Knarzklauen]] in Besitz genommen wurde. \r\nWenn man den schlummernden [[Nachtelfen Druiden]] im Grabhügel nicht zur Hilfe kommt, werden sie auf ewig im [[Smaragdgrüner Traum|Smaragdgrünen Traum]] gefangen gehalten, vollkommen ahnungslos ihrem Schicksal ausgeliefert. Das empfindliche Ritual des Großen Schlafes kann ohne die [[Relikte des Erwachens]] nicht unterbrochen werden. Diese Relikte bestehen aus dem , dem schwarzen Federkiel, dem sowie der . Die [[Druiden]] bewahren sie dort in heiligen Truhen auf. \r\n==Personen==\r\n* '''Gaerolas Talvethen''' - Gaerolas Talvethen ist der Bewacher der [[Druiden]] im Grabhügel von Ban'ethil. Seine Pflicht als auserwählter Beschützer der Schlafenden ist es, deren Sicherheit zu gewährleisten, auf dass sie ihrem Pakt mit [[Ysera]] gerecht werden. Aber es gab länger keine Nachricht von Gaerolas. Die [[Furbolgs der Knarzklauen]] haben ihn hinterrücks überfallen, als er auf dem Weg zum Grabhügel von Ban’ethil war und liefen weiter, um [[Sternenhauch]] zu plündern. Seine Wunden sind zu schwer, er kann nicht zu [[Athridas Bärenpelz]] nach [[Dolanaar]] zurückkehren und ihm diese schlimme Nachricht überbringen. \r\n* '''Oben Zornklaue''' - Oben Zornklaue ist ein [[Druide der Klaue]]. Die [[Furbolgs]] haben seinen physischen Körper reanimiert und lassen ihn jeden angreifen, der versucht, den Grabhügel von Ban'ethil zu erforschen. Er selbst ist im [[Smaragdgrüner Traum|Smaragdgrünen Traum]] gefangen und kann diesem Treiben keinen Einhalt gebieten. In den tiefsten Tiefen des Grabhügels findet man seinen seelenlosen Körper. Damit er sich aus seinem Zustand befreien kann, muss man seinen physischen Körper töten. Sobald das getan ist, wendet man den dieser [[Furbolgs]] auf seinen gefallenen Körper an.\r\n* '''[[Vorlus Elendshuf]]'''",},
			["Grabhügel von Dor'Danil"] = { content = "Die Grabhügel von Dor'Danil im südlichen [[Eschental]] erreicht man, indem man der Straße folgt, die zum [[Brachland]] führt. \r\nDie [[Nachtelfen]] [[Druiden]] des Grabhügels von Dor'Danil suchten östlich dieser Straße Zuflucht, aber sie wurden vergiftet und ermordet von den [[Untote]]n. Sie sind jetzt Geister, die getrennt von ihren Körpern und in den Wahnsinn getrieben ziellos umherirren. Die [[Verlassene]]n, der untote Arm der Horde, haben sich ins [[Eschental]] eingeschlichen und treiben sich in den Ruinen und Grabhügeln herum. Die [[Nachtelfen]] glauben, dass sie die Krankheit in [[Eschental]] verbreiten wollen, denn die [[Verlassene]]n haben südlich von [[Waldeslied]], in der Nähe des Grabhügels von Dor'Danil, ein Lager, in dem sie Gifte und Krankheiten entwickeln und in Flaschen füllen. Das letzte Teil von [[Dartols Rute]] wurde in die Obhut der [[Druiden]] von Dor'Danil gegeben und auch das Buch: \"[[Vermächtnis der Aspekte]]\" findet man in den Tiefen des Grabhügels, wo es von den toten [[Druiden]] und deren Tötern bewacht wird. \r\n==Personen==\r\n* [[Mavoris Wolkenbruch]]\r\n* [[Taneel Finsterwald]]\r\n* [[Uthil Mondweise]]",},
			["Grabmal"] = { content = "Das Grabmal ist ein [[Verlassene]]n-Stützpunkt der [[Horde]] im [[Silberwald]]. Man folgt der Straße von [[Brill]] in [[Tirisfal]] aus nach Süden und geht dann nach [[Unterstadt]] südwestwärts. Das [[Grabmal]] selbst ist eine zerfallene Gruft.\r\n==Personen==\r\n* [[Apotheker Renferrel]]\r\n* [[Mura Runentotem]]\r\n'''Sonstige'''\r\n* '''Berater Sorrelon''' repräsentiert die [[Sin'dorei]] und berät die [[Verlassene]]n.\r\n* '''Dalar Morgenweber''' versucht die Quelle für die Zaubereien der Hexer von [[Dalaran]] zu finden. Er wird länger brauchen, als er gedacht hätte, die dunklen Geheimnisse hinter den Verzauberungen, die Arugal verwendete, zu entdecken. Er sucht auch nach den Spuren des Wirkens von [[Arugal]] und den [[Worge]]n. Bald wird er seine Studien zu seiner so genannten 'Arznei' beendet haben. Sein Wissen wird vollständig sein, sobald er herausgefunden hat, welche Verzauberung die seltsamen Zustände in [[Lohenscheit]] verursacht. \r\n* '''Hochexekutor Hadrec''' sucht zwei verlorene Todespirscher und sucht nach dem Grund, warum die Geißel an der verfallenen Fähre ist. Er leitet ebenso den Sturm auf die Insel Fenris. \r\n* '''Schattenpriester Allister''' möchte Licht in das Dunkel der Hexerpläne von [[Dalaran]] bringen und leitet Nachforschungen in Mühlenbern.\r\n* '''Todeswache Podrig''' soll Nachschub für das Grabmal besorgen. Hochexekutor Hadrec bat ihn, eine Inventur der Ausrüstung beim Grabmal durchzuführen. Da die [[Geißel]] und Schlimmeres in den Wäldern lauert, möchte man nicht, dass den Todeswachen Ausrüstung fehlt, die sie brauchen. Er hat festgestellt, dass sie im Großen und Ganzen gut bestückt sind, aber sie brauchen mehr Waffen als Ersatz für die, die sie auf dem Feld verloren haben.",},
			["Grabmal des Sargeras"] = { content = "Vor über 600 Jahren hatte [[Aegywnn]], die Wächterin des [[Orden von Tirisfal]], den dunklen Gott [[Sargeras]] in einem titanischen Zweikampf besiegt und sein Grabmal in den Tiefen der Großen See verborgen. Doch ihr Sohn [[Medivh]], dessen Seele durch [[Sargeras]]’ Geist verdorben worden war, strebte die Herrschaft über [[Azeroth]] an, und schloss einen Pakt mit dem [[orcs|orkischen]] [[Hexenmeister]] [[Gul'dan]]. [[Medivh]] stellte ihm unvorstellbare Macht in Aussicht, die sich im Grabmal des [[Sargeras]] verbergen sollte, wenn er das Königreich zerstören und ihn zum Herrn über dessen Volk machen würde. Als man von [[Medivh]]s Machenschaften erfuhr, stürmten Einheiten [[Azeroth]]s seinen Turm und töten ihn - er konnte [[Gul'dan]] die Lage des legendären Grabmals nicht mehr verraten. Fortan war der [[Hexenmeister]] von dem Gedanken besessen, das Grabmal des [[Sargeras]] zu entdecken, und hoffte noch immer uneingeschränkte Macht zu erlangen. Er baute eine mächtige Seestreitmacht auf, um die mystische Stätte zu finden. \r\nAls [[Orgrim Schicksalshammer]] schließlich während des zweiten Krieges das letzte Gefecht gegen die Hauptstadt von [[Lordaeron]] vorbereitete, verließen [[Gul'dan]] und seine abtrünnigen Klans ihre Posten und stachen in See. Mit Unterstützung der [[Orcs des Stormreaverklans|Stormreavers]] und des [[Schattenhammer Klan]]s gelang es ihm, das Grabmal zu finden und die [[Verheerte Inseln]] vom Meeresboden emporsteigen zu lassen. Als er jedoch die uralte, überflutete Gruft öffnete, warteten dort nur wahnsinnige [[Dämonen]] auf ihn, von denen er in Stücke gerissen wurde. Aber auch die abtrünnigen Klans wurden vernichtet, als Schicksalshammers Armee sie eingeholt hatte. \r\nAuch heute noch ist der Eingang zum Grabmal von den Überresten der damaligen Lager umgeben, und das Heulen gequälter Seelen erfüllt die Luft. Obwohl die orcischen Krieger schon seit langer Zeit tot sind, sind sie für alle Zeit auf dieser verfluchten Insel gefangen. Die Macht von [[Sargeras]] - der dunkle Preis, den [[Gul'dan]] begehrt hatte - war unerreichbar, aber die Geheimnisse, die seit lang vergessener Zeit im Grabmal lagerten, lockten viele Jahre später auch [[Illidan Sturmgrimm]] zur Gruft des dunklen [[Titanen]]. Die Suche nach dem [[Auge von Sargeras]], einem Artefakt ungeheurer dämonischer Energien, hatte ihn auf die [[Verheerte Inseln|Verheerten Inseln]] geführt. Er fand das [[Auge von Sargeras]] und ließ mit dessen Macht das Grabmal über den Köpfen seiner Verfolger einstürzen. Die [[Behüter]], die geschworen hatten, den Verräter wieder in Ketten zu legen, wurden bei lebendigem Leibe begraben. Einzig [[Maiev Schattensang]] fand einen Weg hinaus, bevor das Grabmal des [[Sargeras]] mit ihren Dienerinnen im Meer versank.",},
			["Grab des Lichts"] = { content = "Das '''Grab des Lichts''' befindet sich im Osten der [[Flüchtlingskarawane]] unter dem versengten Sand der [[Knochenwüste]] innerhalb der [[Wälder von Terokkar]]. Das Grab ist eine verlorene Ruhestätte der Toten. Doch noch immer plündern die [[Astrale]]n die Körper der Gefallenen, um an die Schmückstücke und Andenken zu kommen, die den Toten vor Jahrhunderten mit ins Jenseits gegeben wurden. Das Grab des Lichts wurde vom [[Schattenrat]] verderbt und die toten [[Draenei]] wurden zu verfluchten [[Geist]]ern, die von Zorn erfüllt sind und vor Hass auf die Lebenden brennen. Wenn man ein Grabrelikt der [[Draenei]] in der Nähe des uralten Draeneialtars tief im Grab des Lichts benutzt, wird ein Grabwächter gerufen. Dieses Wesen wird den Altar aktivieren und das Grab von den verderbten Geistern befreien, damit sie aufsteigen können.",},
			["Grakkarond"] = { content = "Grakkarond war ein gewaltiger [[Bronzener Drachenschwarm|Bronzener Drache]], dessen Knochen noch heute in [[Silithus]] zu finden sind. Er war einer der Anführer im [[Krieg der Sandstürme]]. Während eines Gefechtes zielte [[Ossirian]] der Narbenlose auf Grakkarond, und schleuderte sein Obsidianschwert durch eine seiner Schwingen. Der angeschlagene Drache fiel vom Himmel und zermalmte bei seinem Aufschlag die [[Qiraji]] mit seinem massigen Körper. Grakkarond zerfetzte [[Ossirian]] fast zu Tode, allerdings hatten die anderen [[Anubisath]]s und [[Qiraji]] jetzt ein erdgebundenes Ziel, auf das sie sich stürzen konnten, und so fielen sie in Scharen über den edlen [[Drachen]] her und überwältigten ihn. Die Knochen von Grakkarond liegen heute noch südlich von [[Burg Cenarius]]. \r\nDas Glyphenverzierte Kristallprisma, welches [[Geologin Lerchenbann]] auf [[Burg Cenarius]] entschlüsseln konnte, zeigt einen Abgesandten der [[Qiraji]], wie er sich mit drei [[Silithiden]], vor den Knochen eines großen [[Drachen]], trifft. Über den Glyphen steht eine Art Kode. Dieser Kode ist der Schlüssel zur Beschwörung des [[Abgesandter Roman'khan|Abgesandten Roman'khan]]. Dazu muss man den Glyphenkode der [[Silithiden]] vor den Knochen von Grakkarond in den Sand schreiben.",},
			["Grand Hamlet"] = { content = "* Wappenfarbe: dunkelbraunrot, silberner Rand, silberner Pokal (siehe Statue in der Rabenflucht)\r\n* '''Gildenrüstung:''' schwarz / silbernes \"Silberfaden-Set\" (8-teilig), optional Fackel oder Laterne im [[Dämmerwald]]\r\n==Gildentreffpunkte == \r\n* [[Dunkelhain]] (Haus der Familie Carevin gegenüber der Schmiede)\r\n* Rathaus in [[Dunkelhain]]\r\n* Taverne [[Zum roten Raben]] \r\nGrand Hamlet war einst kleiner Weiler im Königreich [[Sturmwind]] und befand sich im südlichen [[Wald von Elwynn]], vermutlich an der Stelle wo heute die Ruinen der [[Rabenflucht]] im [[Dämmerwald]] liegen. Im ersten Krieg wurde er bei einem Angriff der Orks zerstört. Die wenigen Überlebenden leben nun in [[Dunkelhain]] und suchen nach den Spuren ihrer Vergangenheit. Wanderer und Reisende werden in [[Dunkelhain]] bewirtet und finden Unterkunft.",},
			["Grangol'var"] = { content = "'''Grangol'var''' war einst eine umzäunte Festung der [[Orcs]] und liegt recht zentral innerhalb der [[Wälder von Terokkar]]. Doch eine schattenhafte Truppe ist nun in die Ruinen dort eingezogen. Diese Schattenhaften unter Führung von [[Schattenmeister Gram]] sind feindlich gesonnen und gehören zum [[Schattenrat]].\r\n==Personen==\r\n* '''Schattenmeister Gram''' - Schattenmeister Gram ist der Anführer des Schattenrates in Grangol'var.",},
			["Greif"] = { content = "#REDIRECT [[Greife]]", redirect = "Greife",},
			["Greife"] = { content = "Die mächtigen '''Greifen''' des [[Nistgipfel]]s standen der [[Allianz]] in ihrer Stunde der Not mit all ihrem Mut und ihrer Edelmütigkeit zur Seite. Die stolzen Kreaturen, die halb Adler und halb Löwe sind, gelten seither als Symbol für die Tapferkeit der Allianz. Zusätzlich zu ihrer ehrenvollen Aufgabe als Überbringer wichtiger Dokumente zwischen den Anführern der [[Menschen]], der [[Zwerge]] und der [[Gnome]] zu fungieren haben sich die Greifen dazu bereit erklärt, Reisende entlang einiger festgesetzter Routen durch die Länder der Allianz zu fliegen. \r\nIhre Unterkunft finden sie dabei in den eingerichteten [[Greifenhorst]]en, wo sie von [[Greifner]]n versorgt werden.\r\nGreife sind in [[Azeroth]] als Flugreittiere häufig verbreitet und erfreuen sich großer Beliebtheit, wenn es darum geht, weite Strecken in relativ kurzer Zeit zu überbrücken. Berühmt wurden Greife als Reittiere durch die [[Greifenreiter]] des [[Wildhammerklan]]. Bevorzugt trainierten die [[Zwerge]] des Wildhammerklans sogannte Klingenschnäbel, die meist in der Wildnis des [[Hinterland]]s nisten. Doch auch die recht seltenen und edlen Himmelsfürsten dieser Spezies wurden von Zwergen abgerichtet, um die [[Waldtrolle]] abzuschlachten.\r\n==Greife als Reittiere==\r\nAllianzspieler bekommen die Möglichkeit ab Stufe 70 einen gepanzerten Greifen als Reittier zu erwerben. Diese werden in der [[Wildhammerfestung]] im [[Schattenmondtal]] der [[Scherbenwelt]] verkauft. \r\n* Schwarzer Greif\r\n* Goldener Greif\r\n* Weißer Greif\r\n* Schneller blauer Greif\r\n* Schneller grüner Greif\r\n* Schneller lila Greif\r\n* Schneller roter Greif\r\n==Berühmte Greife==\r\n* [[Scharfkralle]]\r\n* [[Scharfschnabel]]\r\n'''Sonstige'''\r\n* Hori'zee - Hori'zee ist der Greif des Kommandanten der [[Wildhammerfeste]] im [[Schattenmondtal]]. Diese wahre Schönheit unter den Greifen wird von [[Eli Donnerschlag]] gepflegt. Sie ist ein Prachtexemplar, so stark und kämpferisch wie ein Greif nur sein kann. Sie würde für [[Kurdran Wildhammer]] in den Tod gehen. Noch nie gab es eine treuere Seeke als sie.\r\n* '''Sturmschwinge''' - Sturmschwing ist der mächtigste Greif im [[Hinterland]].\r\n==Siehe auch==\r\n* [[Greifenhorst]]\r\n* [[Greifenmeister]]\r\n* [[Greifenreiter]]\r\n* [[Greifner]]",},
			["Greifenhorst"] = { content = "Der '''Greifenhorst''' ist ein Gebäude der [[Allianz]]. Die größte Errungenschaft der Allianz zwischen [[Zwerge]]n und [[Menschen]] ist wahrscheinlich die Zähmung und Ausbildung der mächtigen, edlen [[Greifen]]. Nach jahrelangen vergeblichen Versuchen gelang es den zwergischen [[Greifenreiter]]n schließlich, das Vertrauen der misstrauischen Greife zu erringen. In Zusammenarbeit mit den Menschen verwendeten die Zwergenreiter höchste Sorgfalt darauf, Unterkünfte einzurichten, die größte Ähnlichkeit mit den Greifenhorsten auf [[Lordaeron]]s [[Nistgipfel]] aufwiesen.",},
			["Greifenreiter"] = { content = "'''Greifenreiter''' sind wagemutige [[Zwerge des Wildhammerklan]]s. Sie sind erneut dem Ruf gefolgt und haben die mächtigen [[Greife]] der [[Nistgipfel]] mitgebracht, um die [[Allianz]] in Zeiten der Not zu unterstützen. Die mit ihren getreuen, von Blitzen gespeisten Sturmhämmern bewaffneten furchtlosen [[Zwerge des Wildhammerklan|Wildhammerzwerge]] trachten danach, den Himmel von [[Lordaeron]]s Gegnern freizuhalten. Die stolzen [[Greife]] teilen die unerbittliche Entschlossenheit ihrer Reiter und gelten als edle Symbole der Macht der [[Allianz]].\r\n==Persönlichkeiten==\r\nZu den berühmtesten Greifenreitern zählen u.a.:\r\n* [[Kurdran Wildhammer]]",},
			["Greifner"] = { content = "'''Greifner''' ist eine Bezeichnung für eine Person, die sich bei einem [[Greifenhorst]] um die [[Greife]]n kümmert und sie beaufsichtigt. Entstanden ist dieser Beruf bei den [[Zwerge]]n der [[Wildhammer]].\r\n==Persönlichkeiten==\r\n* [[Greifner Laubbart]]\r\n* [[Greifnerin Heulwind]]",},
			["Grelin Weißbart"] = { content = "'''Grelin Weißbart''' ist der Bruder von [[Senir Weißbart]] und hat sein Lager im Südosten des [[Eisklammtal]]s, ein Stück die Straße hinunter. Sein Bruder Senir Weißbart und er wurden in unterschiedliche Ecken von [[Dun Morogh]] entsandt, um dort die von den [[Trolle]]n ausgehende Gefahr zu untersuchen. Der Senat hat mit den [[Troggs]] bereits alle Hände voll zu tun, deswegen kann er keinen weiteren Ärger gebrauchen. Nach allem, was Grelin gesehen hat, ist die Position der Trolle hier im Eisklammtal nicht sonderlich gut - sie sind vor allem in der südlichen Höhle zu finden. Er würde deswegen sagen, die Armee brauchen sie nicht. Einige starke Arme sollten mehr als ausreichend sein. \r\nKönig [[Magni Bronzebart]] hat ihm gestattet, nach Gutdünken mit den Trollen zu verfahren, um eine zufrieden stellende Lösung zu finden. Er hatte ursprünglich vor, seinen Lehrling mit seinem Bericht zu seinem Bruder Senir zu schicken, aber er würde sich viel besser fühlen, wenn er in etwas verlässlicheren Händen wäre.\r\n==Grelin Weißbarts Tagebuch==\r\nGrelin Weißbarts Tagebuch wurde von einem Eistroll mit Namen [[Grik'nir der Kalte]] gestohlen und in die Höhle der [[Trolle der Frostmähnen|Frostmähnentrolle]] gebracht. \r\n'''Inhalt'''\r\nTAG 1:\r\nDer Lehrling und ich sind heute im Eisklammtal angekommen. Die Reise durch die Höhle verlief ohne besondere Vorkommnisse. Wir schlugen unser Lager in sicherer Entfernung von der Höhle auf, in der sich die Trolle eingenistet haben sollen.\r\nTAG 2:\r\nDas verdammte Wolfsgeheul ließ mich fast die ganze Nacht kein Auge zutun. In ein paar Tagen werde ich wohl neue Kleider aus Wolfsbalg haben. Der Bursche hat sich heute ausgerechnet mit einem Trogg eingelassen. Es kam zum Kampf und er behielt tatsächlich die Oberhand gegen den hässlichen Kerl, aber dafür hat er jetzt auch eine unangenehme Verletzung am Arm. Also muss ich wohl in den nächsten Tagen die lästigen Pflichten erledigen.\r\nTAG 3:\r\nKalt. Um die Mittagszeit schneite es ein wenig.\r\nTAG 4:\r\nDer Bursche kam gut gelaunt zurück und wir haben uns die Trolle mal genauer angesehen. Nach den Zeichen auf ihrer Haut und dem Plunder an Schmuck zu urteilen, den sie an sich trugen, würde ich sagen: Frostmähnen.\r\nTag 5:\r\nLieß den Burschen das Lager bewachen und schlich mich in die Höhle, um mich umzusehen. Die Zahl der Trolle ist allmählich Besorgnis erregend. Vielleicht müssen wir noch Gebirgsjäger in großer Zahl anfordern, um die Höhle von den Trollen zu säubern. Mir fällt auf, dass ich zuletzt wenig über die Troggs geschrieben habe. Auch sie kommen in der Region in großer Zahl vor, aber sie sind so primitiv, dass sie wohl keine große Bedrohung darstellen. Es wird sich zeigen, ob das stimmt.\r\nUnd nicht ein Tropfen Bier seit fast einer Woche.\r\nTAG 6:\r\nWieder kalt. Schnee. Trolle. Und kein Bier.\r\nTAG 7:\r\nDer Schnee so weiß. Der Himmel so blau. Wolfsgeheul bei Nacht. Und noch immer kein Bier.\r\nTAG 8:\r\nDie Trolle sind vielleicht doch nicht so ein großes Problem, wie wir anfangs dachten.",},
			["Grell"] = { content = "#REDIRECT [[Wichtel]]", redirect = "Wichtel",},
			["Gri'lek"] = { content = "'''Gri'lek des Eisernen Blutes''' befindet sich in [[Zul'Gurub]]. Dieser untote [[Troll Berserker]] ist einer von mehreren Bossen, die im Schlund des Wahnsinns auftauchen können. Gri'lek ist in der trollischen Geschichte der Gurubashi kein Unbekannter. Es gibt einige berühmte Legenden, die sich um ihn drehen, wie z.B. \"[[Gri’lek der Wanderer]]\" und der verlorene \"[[Arm von Gri'lek]]\" gilt als mächtiges Artefakt. Ungeklärt ist wieso Gri'lek, so wie er in Zul'Gurub auftaucht, wieder zwei Arme hat.\r\n==Kampf==\r\nDie Hälfte der Zeit kann man Gri'lek wie jeden anderen Nahkampfmob bekämpfen (obwohl er gegen Spott immun ist). Die andere Hälfte der Zeit benutzt er seine einzigartige spezielle Fähigkeit: seine Größe verdoppelt sich und seine Angriffe erhöhen sich dramatisch im Schaden. (5000+ im Durchschnittlich). Das läßt ihn ebenso alle vorher angesammelte Bedrohung resetten. Jedoch ist während dieser Form seine Bewegung dramatisch verlangsamt. Er verkündet, welcher Spieler sein Ziel ist und so sollte jeder bereit sein zu laufen wenn sie sehen, dass ihr Name gesprochen wurde. Er hat ebenso eine Beben-Fähigkeit, die in einem Gebiet um ihn herum Stun-Effekte verursacht. Mindestens ein Priester oder Paladin sollte eingeteilt werden, um alle Wurzel-Effekte zu bannen, die Gri’lek’s gegenwärtiges Ziel treffen, um zu sichern, dass Gri’lek ihn nicht fängt und One-Hitted. Gri’lek zählt zu dem schwersten Boss im Schlund des Wahnsinns und besitzt die Fähigkeit zu wachsen und dadurch um die 10000 Schaden zu verursachen. In seiner kleinen Form ist er hingegen recht ungefährlich und fügt normalen Schaden zu. Wenn Gri’lek wächst, wird er sehr langsam und muss von dem Haupt-Tank herum geführt werden, während der Rest der Gruppe fleißig Schaden austeilt.",},
			["Grimmeiche"] = { content = "In einer Höhle am Südufer des [[Al'Amethsee]] in [[Teldrassil]] überträgt ein [[Bäumling]] namens Grimmeiche die Verderbnis auf alle Wesen, die dort leben. Er wird von dem größten Tumor vergiftet, den man je gesehen hat.",},
			["Grimmlinge"] = { content = "#REDIRECT [[Wichtel]]", redirect = "Wichtel",},
			["Grimmlingflitzer"] = { content = "#REDIRECT [[Feendrachen]]", redirect = "Feendrachen",},
			["Grimmlingsflitzer"] = { content = "#REDIRECT [[Feendrachen]]", redirect = "Feendrachen",},
			["Grimmtotemposten"] = { content = "Der '''Grimmtotemposten''' ist eine Siedlung der [[Tauren der Grimmtotem]] in [[Feralas]].",},
			["Grim Batol"] = { content = "Grim Batol ist eine mächtige Festung im östlichen Gebirge des [[Sumpfland]]es und wurde einst von den Zwergen des [[Wildhammer Klan]]s errichtet. Später wurde es von den [[Orcs des Drachenmals]] erobert. \r\nDie [[Orcs des Drachenmals]] konnten mit Hilfe der [[Dämonenseele]], einem uralten Artefakt aus dem [[Krieg der Uralten]], die Drachenkönigin [[Alexstrasza]] gefangen nehmen. In Grim Batol wurde sie in mächtige Ketten gelegt und in einem dauerhaften Zustand der Schwäche gehalten. Die [[Orcs]] zogen [[Alexstrasza]]s Jungen in der Bergfestung auf und richteten sie dazu ab, ihre Feinde zu vernichten. Selbst junge [[Drachen]] verfügten über eine unglaubliche Kraft als auch ein hohes Maß an Intelligenz. Obwohl sie die mächtigste Waffe der [[Horde]] darstellten, mussten die Jungtiere getötet werden, sobald sie ein bestimmtes Alter erreicht hatten. Denn je stärker die [[Drachen]] wurden, desto schwieriger wurde es, die Bestien zu kontrollieren. \r\nNach der Schlacht um das [[Dunkle Portal]] und dem Feldzug in [[Draenor]] schien es so, als wären die [[Orcs]] endgültig besiegt worden. Doch dank seiner [[Drachen]] kontrollierte der [[Drachenmal Klan]] auch weiterhin den Norden [[Khaz Modan]]s. \r\nNahe der Ruinen von [[Dun Modr]] bezogen die Streitkräfte der [[Allianz]] Stellung, um die Bedrohung durch die [[Horde]] ein für alle Mal zu beenden. [[Hexenmeister]] [[Nekros Schädelberster]] glaubte, eine großangelegte Invasion aus dem Westen würde bevorstehen und die [[Allianz]] könnte versuchen, die Drachenkönigin zu befreien. Um den beständigen Angriffen standzuhalten, versorgte Grim Batol die orkischen Truppen bei [[Dun Algaz]] mit Nachschub. Er sandte alle [[Drachen]] nach [[Dun Algaz]], befahl die Jungtiere zu töten und verließ mit seinen restlichen Truppen die Bergfestung in Richtung Norden. Doch eine kleine Schar von Widerstandskämpfern griff den Wagenzug an. Der Magier [[Rhonin]] zerstörte die [[Dämonenseele]] und befreite [[Alexstrasza]] aus dem Bann des [[Hexenmeister]]s. \r\nIn ihrer Wut zerstörten die [[Drachen]] Grim Batol bis auf die Grundmauern und äscherten den größten Teil des [[Drachenmal Klan]]s ein. Die überlebenden [[Orcs]] wurden zusammengetrieben und in die wartenden [[Internierungslager]] geworfen. Der [[Roter Drachenschwarm|Rote Drachenschwarm]] bewacht noch heute Grim Batol und die geheimen Mächte im Inneren der Festung, zu der sie niemanden in die Nähe lassen.\r\nDie Tore von Grim Batol sind heute verschlossen doch hinter einigen Fenstern erkennt man Licht und rote Drachen patrouillieren vor den Toren.",},
			["Grishnath"] = { content = "#REDIRECT [[Arakkoa der Grishna]]", redirect = "Arakkoa der Grishna",},
			["Grizzlyhügel"] = { content = "Die dicht bewachsene, uralte Landschaft der '''Grizzlyhügel''' in [[Nordend]] steht in direktem Gegensatz zu den verschneiten Gipfeln, die sie vom [[Heulender Fjord|Heulenden Fjord]] im Süden trennen. Die [[Allianz]] und [[Horde]] haben unlängst damit begonnen, eine Präsenz in den Grizzlyhügeln zu schaffen, was jedoch nichts daran ändert, dass dieses ungezähmte Grenzland auch heute noch dieselbe weite und gefährliche Wildnis ist, die sie schon vor Urzeiten war. \r\nDie Grizzlyhügel ist ein bisher naturbelassenes Gebiet, in dem die [[Furbolgs]] seid Generationen friedlich leben. Jedoch werden sie und ihr Lebensraum seit einiger Zeit von Goblins der [[Venture Company]] bedroht, die begonnen haben den Wald großflächig abzuholzen. Die weitaus größere Gefahr bilden jedoch die Eistrolle, die [[Drakkari]]. Diese untoten Trolle fallen von der [[Festung Drak'Tharon]] aus über die Furbolgs her und versuchen das Land unter ihre Kontrolle zu bringen. Allianzler wie Hordler sind dazu aufgerufen, die Furbolg bei Ihrer Verteidigung zu helfen und die Eistrolle zurückzuschlagen. \r\n==Fraktionen==\r\n* '''Drakkari''' - Die eigentliche unmittelbare Gefahr entspringt der im Norden gelegenen [[Festung Drak'Tharon]], von wo aus sich Scharen untoter [[Eistrolle]] der [[Drakkari]] wie eine Flut über das Land ergießen. Die Ursache der plötzlichen Invasion der [[Drakkari]] bleibt ein Mysterium. \r\n* '''Furbolgs''' - Seit Generationen verehren die in Stämmen organisierten Wesen, deren Hauptsitz der [[Gräuelschlund]] ist, einen gewaltigen urzeitlichen Bären, der durch die umliegende Wildnis streift. Die [[Furbolgs]] befinden sich in einem verzweifelten Kampf um ihr Land, das sie gegen die stetig wachsende Zahl untoter Trolle verteidigen müssen. \r\n* '''Venture Company''' - Die [[Venture Company]] der [[Goblins]] hat mit einer großangelegten Abholzungsoperation in der gesamten Region begonnen.\r\n==Orte==\r\n* [[Festung Drak'Tharon]]\r\n* [[Gräuelschlund]]\r\n* [[Thor Modan]]",},
			["Gri’lek der Wanderer"] = { content = "''Die Legende ist nur in Bruchstücken erhalten und die Ruinen von [[Alterac]] waren der letzte bekannte Ort, an dem es ein intaktes Exemplar des Buches geben soll, in dem diese Geschichte niedergeschrieben ist. Sie berichtet auch über den \"[[Arm von Gri'lek]]\". Die Geschichte von [[Gri'lek]] findet sich ebenso als Zweite Troll-Legende auf einer Schrifttafel im [[Finsteres Riff|Finsteren Riff]] im [[Schlingendorntal]].''\r\n==Die Geschichte von Gri'lek dem Wanderer==\r\nGri’lek stapfte durch den Urwald.\r\nSeine Augen brannten und sein Herz hämmerte, denn er war sehr zornig.\r\nVoller Wut hob er seinen Arm und brüllte gen Himmel.\r\nEs war sein linker Arm, den er hob, stark und sicher geworden von der Jagd ohne seinen Zwilling.\r\nDenn Gri’leks rechter Arm war auf immer fort.\r\nUnd so wanderte er denn umher und suchte.\r\nSein Arm jedoch blieb verloren.\r\nUnd so ging er fluchend und brüllend seines Weges.\r\nAber Gri’lek hatte sich vor langer Zeit von den Geistern abgewandt und sie so verärgert.\r\nNun hörten sie nicht mehr auf sein Fluchen.\r\nGri’lek war verdammt.\r\nVerdammt dazu, mit nur einem Arm umherzuwandern.",},
			["Grobbulus"] = { content = "'''Grobbulus''' ist ein [[Fleischriese]] im Monstrositätenflügel von [[Naxxramas]]. Er schießt mit Giftschleimen um sich und verseucht jeden Teil des Bodens, auf dem er entlang läuft.\r\n==Fähigkeiten==\r\nGrobbulus Hauptfähigkeit ist die MUTAGENINJEKTION, die er auf einen Spieler zaubert. Dieser Zauber löst sich nach 10s aus und hinterlässt an dem Ort, an dem der Zauber abgelaufen ist, eine Giftwolke. Zudem verbreitet Grobbulus eine Art Giftwolke unter sich, die sich genau wie die oben beschrieben kreisförmig ausdehnt. Zusätzlich beharkt Grobbulus alle Gegner, die sich vor ihm befinden mit einem Giftatem, weshalb der Haupttank Grobbulus immer leicht vom Schlachtzug wegdrehen muss. Dies ist notwendig, da der Atem durch jeden Spieler den er trifft, einen Brühschleimer hervorruft. Diese Attacke darf nur der Haupttank abbekommen, da sonst zu viele Gegner erscheinen. Die Verstrahlten Brühschleimer besitzen ungefähr 50000 TP und haben eine giftige Aura, die alle in einem Umkreis von 15 Metern trifft.",},
			["Grokhnaar Grimmklinge"] = { content = "== Herkunft / Wohnort==\r\nGrokhnaar, der von Freunden auch einfach nur \"Grok\" genannt wird, stammt aus Dun Morogh. Als letzten Spross seiner Familie hat es ihn von dort aus nach Eisenschmiede verschlagen, wo er zumeist im düsteren Viertel anzutreffen ist.\r\n==Berufung==\r\nGrok ist ein leidenschaftlicher Erfinder und passionierter Dolch-Kämpfer.",},
			["Grol'doms Hof"] = { content = "Grol'doms Hof ist, wie der Name schon sagt, ein kleiner Hof im [[Brachland]].\r\n==Personen==\r\n* [[Kranal Fiss]]\r\n* '''Thun'grim Brandblick''' - Thun'grim Brandblick ist ein berühmter orcischer Schmied und hat von den fortgesetzten Heldentaten im Dienst der [[Horde]] gehört. Wenn es einen Orc gibt, der hochwertige Waffen herstellen kann, dann ist er es. Er ist ein Einsiedler, der auf den Hügeln östlich des [[Wegekreuz]]es in der Nähe von Grol'doms Hof haust und um ihn zu finden reist man zuerst zum [[Wegekreuz]] und wendet sich dann nach Osten in die Berge. Sein Lager liegt hoch auf einem Berggipfel. Seine Augen sind schon lange ausgetrocknet, weil er ins Feuer der Schmiede schaute, aber manches kann er noch sehen ...",},
			["Grollhuf"] = { content = "'''Grollhufe''' sind riesige [[Wildtiere]], die mit den [[Kodos]] verwandt sind und in [[Nagrand]] leben. Man findet die friedfertigen Grasfresser in der direkten Umgebung von [[Nesingwarys Safari]] und in der Nähe im Süden. Die Grollhufbullen überall im Westen und Süden der mittleren Regionen Nagrands aber sind viel gefährlicher.\r\n==Persönlichkeiten==\r\n* '''Banthar''' – Banthar ist der meistgefürchtete und am schwersten zu fassende Grollhuf der gesamten [[Scherbenwelt]]. Er ist außerdem der behaarteste. Man sagt, er treibt sich auf den Geisterfeldern in der Nähe des [[Oshu'gun]] in [[Nagrand]] herum.\r\n* '''Schmetterzehe''' – Schmetterzehe ist ein grausamer Grollhuf in Nagrand.",},
			["Grom'tor"] = { content = "#REDIRECT [[Grom'tor Herzeleid]]", redirect = "Grom'tor Herzeleid",},
			["Grom'tor Herzeleid"] = { content = "'''Grom'tor Herzeleid''' ist [[Oronok]]s Erstgeborener Sohn. Er ist der Krieger der Familie, jähzornig und blutdurstig ... Das hat er von seiner Mutter ... und er hat sich aufgemacht, um die [[Echsennarbe]] im [[Schattenmondtal]] nach dem ersten Teil der [[Litanei der Verdammnis]] zu durchsuchen. Der [[Naga]]abschaum, der zu seinen Füßen liegt, ist schon der sechste, den er heute befragt hat. Wegen der schicken Rüstung dachte Grom'tor, dass der Naga sicher etwas weiß, denn die anderen waren völlig nutzlos. Er musste ihn nur einmal schlagen, da erzählte der [[Naga]] auch schon, dass sich der erste Teil der Litanei in einer Truhe in der [[Echsennarbe]] oder der Zisterne im Osten befindet und dass die [[Naga]] die Schlüssel dazu haben.",},
			["Grom Höllschrei"] = { content = "Als Führer des [[Kriegshymnenklan]]s war '''Grom Höllschrei''' der mächtigste Orc in [[Draenor]]. Er war ebenso der Träger von [[Blutschrei]]. In vielerlei Hinsicht begann und endete der Fluch, der auf dem orcischen Volk lastete, mit Grom. Sein Name bedeutete \"Riesenherz\" in der alten Sprache der Orcs und er hat sich diesen Namen hundertmal verdient, als er sich allein dem Dämon Mannoroth stellte - und die Freitheit der Orcs mit seinem Blut erkaufte. Die [[Horde]] kennt viele Helden, doch niemand verkörpert Stärke und Opferbereitschaft so sehr, wie Grom Höllschrei. Während des [[Erntedankfest]]s in [[Azeroth]] dankt die [[Horde]] ihren Helden für all die Opfer, die sie in ihrem Namen dargebracht haben. Für einige war es gar das höchste aller Opfer, ihr Leben. Das Denkmal für Grom Höllschrei findet man im [[Dämonensturz]] in [[Eschental]].\r\n==Geschichte==\r\nGrom Höllschrei war der letzte überlebende Orc-Häuptling von [[Draenor]]. Er nahm nicht an der ersten Invasion von [[Azeroth]] teil und stellte sich in die Dienste von [[Ner'zhul]], als die [[Menschen]] zum ersten Mal nach [[Draenor]] eindrangen. [[Ner'zhul]] hatte ihn bei Streitigkeiten mit dem [[Klan des Lachenden Schädels]] aus deren Gefangenschaft befreit, weswegen Grom ihm treu diente. Nach der Zerstörung seiner Welt fand sich Grom Höllschrei in [[Azeroth]] wieder, gefangen in einer feindseligen Welt die er verachtete. Er hatte seinen mächtigen [[Kriegshymnenklan]] zu zahlreichen Siegen über die [[Menschen]] geführt, verzweifelte aber an der Lethargie, die sein Volk nach dem Zweiten Krieg überkam. \r\n'''Dämonische Wut'''\r\nHöllschrei war einer der ersten [[Orcs]], die Opfer des dämonischen Fluchs seines Volkes wurden. Viele lange Jahre hatte er mit der Wut und dem Kampfrausch in seinem Herzen gekämpft. Unter [[Thrall]]s visionärer, idealistischer Führung glaubte Höllschrei, dass er und sein Volk den verderblichen Einfluss der [[Dämonen]] endlich abstreifen können.\r\n'''Eine neue Horde'''\r\nEr war einer der Ersten der Thrall unterstützte und die neue Horde wiedervereinigte, indem er sich bei der Schlacht von Durnholde zeigte. Grom brachte Thrall die Sprache der Orcs bei und ließ sich von ihm über den Zustand der Gefangenen Orcs in den Internierungslagern unterrichten. Als die Schlacht in Durnholde gewonnen war begleiteten Grom und der [[Kriegshymnenklan]] Thrall und den Rest der Horde nach [[Kalimdor]], wurden aber durch einen Sturm von ihnen getrennt. \r\n'''Krieg mit den Nachtelfen'''\r\nHöllschrei erreichte das Festland [[Kalimdor]]s und fand auch als erster heraus, dass die [[Menschen]] von [[Lordaeron]] ebenfalls dort waren. Während des Kampfes mit den menschlichen Truppen stieß Thrall wieder zu ihm und wollte ihn beschwichtigen, doch Höllschreis Wut ließ ihn immer wieder Angriffe auf die Menschendörfer starten, so dass Thrall ihm helfen musste. Daraufhin ließ Thrall Grom mit dem Auftrag Holz für eine große Siedlung zu beschaffen zurück, während er selbst nach einem Orakel suchte. Dieser simple Auftrag rief ein weiteres Volk in Kalimdor auf den Plan: die [[Nachtelfen]]... Die Kriegshymnenorcs hatten mit ihrer Holzfällerei die [[Nachtelfen]] erzürnt, die ohne Kompromisse das Lager der [[Orcs]] angriffen, aber zurückgeschlagen wurden. Dies blieb jedoch dem Halbgott [[Cenarius]] nicht verborgen und so griff er mit neuer Verstärkung die Lager der Kriegshymnenorcs an und drängte Grom und seinen Klan immer weiter zurück. \r\n'''Eine neue Wut'''\r\nIn dieser Notlage machte sich Grom zu einer Quelle dämonischer Energie auf, die im Wald versteckt war, [[Mannoroth]] war nach [[Azeroth]] gekommen und brachte Höllschrei erneut unter seine Kontrolle, als er und sein Klan wieder von dessen Blut tranken, das in dem Brunnen war. Durch Mannoroths Blut wieder in einen Kampfrausch versetzt stürmten die Orcs gegen die [[Nachtelfen]] und töteten [[Cenarius]]. Als [[Thrall]] davon erfuhr, dass Grom wieder unter dämonischem Einfluss machte er sich mit seinen neuen Verbündeten, den [[Tauren]] und den Überlebenden [[Menschen]] von [[Lordaeron]] auf und befreite Grom wieder aus Mannoroths Einfluss. Schließlich stellten sich Thrall und Grom [[Mannoroth]] im Kampf, bei dem Höllschrei dem [[Dämonen]] den Todesstoß versetzte, doch die Schockwelle, die Mannoroths Tod auslöste erwischte ihn tödlich, so dass auch er den Kampf nicht überlebte. Durch diese Tat hat Grom die Orcs entgültig aus der Gewalt der Dämonen befreit. \r\n'''Quelle:'''",},
			["Gronn"] = { content = "Gronn sind monströse Wesen mit nur einem Auge. Worte reichen nicht aus, um die schrecklichen Gronn der [[Scherbenwelt]] zu beschreiben, die unsterblichen Halbgötter des [[Oger]]volks. Manche sagen, die Gronn haben die niederen [[Oger]] erschaffen, aber wenn dies so sein sollte, so zeigen sie wenig Zuneigung ihren Geschöpfen gegenüber, da diese wilden, animalischen Fürsten mit eiserner Hand über die [[Oger]]klans herrschen. Man sagt, es existieren lediglich sieben Gronn ([[Gruul]] und seine Söhne), welche nicht für ihre Intelligenz bekannt sind. Dennoch sind solche Gerüchte nur wenig beruhigend, da die Gronn unbestreitbar über zerstörerische Mächte verfügen. \r\n==Persönlichkeiten==\r\n* [[Gruul der Drachenschlächter]] ist der Vater der existierenden Gronn.\r\n==Bekannte Söhne des Gruul==\r\n* [[Durn der Nimmersatte]]\r\n* [[Goc]]\r\n* [[Gorgrom der Drachenfresser]]\r\n* [[Grulloc]]\r\n* [[Maggoc]]\r\n* [[Skulloc Seelenschänder]]\r\n* [[Slaag]]",},
			["Großanachoret Almonen"] = { content = "'''Großanachoret Almonen''' ist ein erleuchteter [[Draenei Priester]] in [[Shattrath]], der auf der Terrasse des Lichts seine Predigen hält. [[A'dal]] hat seinen Geist für Wahrheiten geöffnet, die er heute mit den Gästen teilt.\r\n==Predigt==\r\n''Folgende Predigt hält Almonen regelmäßig vor anderen Klerikern in der Mitte der Terasse des Lichts:''\r\nIn Übereinstimmung mit meiner göttlichen Berufung muss ich diese offenbarten Wahrheiten mit allen teilen, die sie hören wollen.\r\nMit wurde mitgeteilt, dass in jedem von uns das Licht wohnt. Es ist ein Geschenk, das allen natürlich geborenen Wesen gemacht wird. Es manifestiert sich als Gefühl, zuerst klein und leicht zu übersehen; es bestätigt Wahrheiten und bringt einen unmerklich dazu, Gutes zu tun. Einfache Güte, wohltätige Gaben, Dienst an denen, die in Not sind. Das sind alles Früchte des Lichts. Es belohnt diejenigen, die seinem Weg folgen, mit Segen, sowohl sichtbar und unsichtbar. \r\nPersönliche Vorräte an Hoffnung und Glauben werden gestärkt, und die eigenen Aufnahmefähigkeit für das Licht erhöht. Mit der Zeit wird man durch Gehorsamkeit gegenüber der Führung des Lichts sensibler für seine Stimme und seine Macht. Groß ist die Kraft der Heilung und Segnung für die ergebensten Gefolgsleute des Lichts. \r\nLeider gibt es solche, die ihr sterbliches Leben in Missachtung des Lichts verbringen. Von denen zieht sich das Licht zurück, bis nur die Dunkelheit bleibt. Wo kein Licht ist, gedeihen Verzweiflung, Hass und Wut. Wir wurden in einem gefährlichen Zeitalter geboren, wo die Kräfte der Dunkelheit entschlossen sind, unsere Zerstörung herbeizuführen. Dies ist eine Zeit, in der wir uns in Einheit mit dem Licht finden. \r\nHört meine Worte, und lasst das Licht in Euch deren Wahrheit bestätigen.\r\nNehmt das Licht in Euch an, meine Freunde. Verweigert Euch der Dunkelheit.\r\nWir müssen diese herausfordernden Zeiten mit festem Glauben überdauern, und eines Tages werden wir siegreich sein.\r\nBei den Naaru, so möge es sein.",},
			["Großes Dunkles Jenseits"] = { content = "Das Universum mit seinen Myriaden von Welten und Dimensionen wird auch das '''Große Dunkle Jenseits''' genannt. Im ersten Zeitalter der Schöpfung brachten die [[Titanen]] Ordnung zu Millionen von Planeten, die über das gesamte Universum vertreut waren. So gewährleisteten sie dem Leben eine sichere Zukunft - heute tragen viele Welten eine wundersame und schreckliche Vielfalt von Lebewesen. Niemand weiß genau, wie das Universum seinen Anfang nahm. Einige haben die Theorie aufgestellt, dass die unendliche Vielzahl von Welten durch eine ungeheure kosmische Explosion in das Große Dunkle Jenseits geschleudert wurde. Andere glauben an eine einzige allmächtige Wesenheit, die das Universum, wie es heute existiert, erschaffen hat. Wie es auch sei, der exakte Ursprung des chaotischen Universums bleibt unklar.",},
			["Große Dunkle Jenseits"] = { content = "#REDIRECT [[Großes Dunkles Jenseits]]", redirect = "Großes Dunkles Jenseits",},
			["Große Kluft"] = { content = "Die '''Große Kluft''' liegt relativ zentral auf der [[Höllenfeuerhalbinsel]]. Es ist ein ausgedehntes Grabengebiet, das von tödlichen [[Felsklauen]] bewohnt wird. Es wimmelt dort nur so von diesen Raubtieren. Die [[Felsklauen]]matriarchin, [[Schwarzkralle die Wilde]], wurde zuletzt in einer Höhle in der großen Kluft gesichtet. In der Kluft befinden sich das südliche Leuchtsignal, westliche Leuchtsignal und das zentrale Leuchtsignal. Das Entzünden dieser Signale zieht unweigerlich die Felsklauen aus der Umgebung an, aber weisen ebenso den Pilgern den Weg. Die [[Zerschlagene]]n haben unendlich viel Grausamkeit ertragen müssen. Kein Wunder, dass sie sofort nach der Öffnung des Dunklen Portals scharenweise in der Hoffnung, diesem Land entfliehen zu können, dorthin gepilgert sind. Zum Pech für ihre verwirrten Brüder und Schwestern sind sie für die [[Felsklauen]], die in der großen Kluft leben, eine leichte Beute.",},
			["Großhexenmeister Nethekurse"] = { content = "'''Großhexenmeister Nethekurse''' ist ein Boss in den [[Zerschmetterte Hallen|Zerschmetterten Hallen]] der [[Höllenfeuerzitadelle]]. Er ist im Besitz des [[Dämmerfoliant]]en.",},
			["Großknecht"] = { content = "Als '''Großknecht''' bezeichnet man einen Aufseher, der das Kommando über eine Gruppe von [[Arbeitern]] bzw. [[Peon]]s inne hat. Häufig werden sie zur Leitung der Arbeit in Minen, Steinbrüchen oder Ausgrabungen eingesetzt. \r\n==Das richtige Werkzeug==\r\nEgal ob Orc, Mensch, Goblin oder Zwerg, es gibt eine Sache, die jeder gute Aufseher braucht: die richtige Ordnungswaffe, um Furcht in die Herzen fauler oder aufsässiger Arbeiter bzw. Peons zu pflanzen. Häufig sind das Knüppel. Großer Beliebtheit erfreut sich bei den Orcs z.B. der ''Großknechttotschläger'' oder aber sog. ''Schuhmerang'' (ein Schuh oder Stiefel, der geworfen wird und bei richtigen Wurfwinkel zum Werfer zurückkehrt). Der richtige Einsatz des Schuhmerangs sorgt für Gehorsam und Unterwürfigkeit. Er wurde von [[Chefvorarbeiter Lehmklump]] im [[Basislager des Drachenmals]] im [[Schattenmondtal]] entwickelt und aus Knotenhautleder und dem gehärteten Balg von [[Tyrantus]] gefertigt. \r\n==Persönlichkeiten==\r\nZu den berühmten Großknechten zählen:",},
			["Großknecht Razelcraz"] = { content = "'''Großknecht Razelcraz''' kann es kaum fassen, dass er [[Beutebucht]] verlassen hat, um in die [[Scherbenwelt]] zu kommen. Sein Vetter [[Quack Lufthans]] hat ihm versprochen, dass er hier ein Vermögen machen würde, aber stattdessen ist er in seinem [[Zeppelin]] auf und davon und hat ihn hier zurückgelassen. Nun versucht er, sich einen sehr bescheidenen Lebensunterhalt mit der Mine zu verdienen. Aber wie soll er denn überleben, wenn er dauernd von Höllenebern, [[Dämonen]] und [[Höllenorcs]] angegriffen wird? \r\nEr hält ein Rudel [[Teufelshunde]], die sein Lager bewachen. Sie machen ihre Sache nicht sehr gut und beißen ihn gerne. Sie mögen auch gerne glänzende Dinge. Sie mögen sogar sehr gerne glänzende Dinge. Nach der Reparatur seines [[Schredder]]s und der Wiederbeschaffung seiner Peons ist Großknecht Razelcraz fast wieder im Geschäft. Das Problem ist nur, dass die [[Gan'arg]] sich in seiner Mine herumtreiben und er kann seine [[Peon]]s dort nicht hineinschicken. Der Anführer der [[Gan'arg]], [[Urga'zz]], haust tief unten in der Mine.\r\n===Kaputter Schredder===\r\nSein Schredder hier ist gestern kaputt gegangen und die [[Höllenorcs]] haben seine Ersatzteile gestohlen. Sie haben die Teile in die [[Große Kluft]] im Südwesten gebracht und vielleicht dort fallenlassen. Wenn er den Schredder endlich zum Laufen bekommt, merkt er, dass er scheinbar die Schlüssel verloren hat. Er fürchtet, dass einer der [[Teufelshunde]] seine Schredderschlüssel gefressen hat. Und auch wenn er den Schredder repariert hat, möchte er nicht riskieren, dass er im Kampf schon wieder kaputt geht.\r\n===Entführte Peons===\r\nUnd vor ein paar Tagen haben die [[Höllenorcs]] auc drei der [[Peon]]s gestohlen. Jetzt sind alle anderen [[Peon]]s abgehauen, weil sie Angst hatten, von den [[Höllenorcs]] gefressen zu werden. Er kann seine Mine ohne [[Peon]]s nicht betreiben. Die [[Höllenorcs]] haben ihre Lager entlang des Walls im Südwesten.",},
			["Großmagister Rommath"] = { content = "'''Großmagister Rommath''' ist der Anführer der [[Blutelfen Magier]] auf [[Azeroth]], der [[Kael'thas Sonnenwanderer]] treu ergeben ist. Zu finden ist er in [[Silbermond]] im Sonnenzornturm.\r\nNachdem sich die meisten Elfen unter [[Kael'thas Sonnenwanderer]] entschlossen hatten, in der [[Scherbenwelt]] zu bleiben und ihre Studien dort fortzusetzen, wurde Großmagister Rommath mit der Nachricht der Hoffnung zurück nach Azeroth zu den [[Blutelfen]] in [[Quel'Thalas]] geschickt. Er erzählte von dem glorreichen versprochenen Land und gab die Lehren [[Illidan]]s weiter. Lehren, die Rommath Prinz Kael'thas zuschrieb und somit die Auffassung begann, Kael'thas würde eines Tages zurückkehren und sein Volk ins Paradies führen. \r\nRommath blieb in [[Quel'Thalas]] und half, es wieder aufzubauen und auf die Rückkehr des Prinzen vorzubereiten. Dank ihm lernten die [[Blutelfen]] Azeroths, wie die arkane Magie gewonnen werden konnte, um ihre Sucht zu nähren. Ihre Gesundheit kehrte zurück und sie lobpriesen den Prinzen in seiner Abwesenheit und widmeten sich ganz dem Studium. Rommath und der neue Orden elfischer Magier machten große Fortschritte, ihren Brüdern die Manipulation der arkanen Energien zu lehren und schon sehr bald ragten die Türme [[Silbermond]]s wieder in den Himmel, angetrieben von flüchtiger Magie.",},
			["Großmeister Vorpil"] = { content = "'''Großmeister Vorpil''' ist ein mächtiger [[Orc Hexenmeister]] des [[Schattenrat]]s im [[Schattenlabyrinth]] von [[Auchindoun]]. Er bewacht den [[Kodex des Blutes]]. In Vorpils Besitz befindet sich allerdings noch ein anderes Buch, das [[Encyclopaedia Daemonica]] genannt wird. Dieses wird tief im Labyrinth von ihm bewacht. Die Encyclopaedia Daemonica ist nichts, mit dem man spielen sollte, denn das Buch enthält Zaubersprüche auf Dämonisch. \r\n==Fähigkeiten==\r\n* '''Feuerregen''' - Vorpils Feuerregen lässt einen Schmelzregen niedergehen, der alle Feinde in einem ausgewählten Gebiet verbrennt und ihnen 6 Sekunden lang jede Sekunde 903 bis 997 Feuerschaden zufügt. Bzw. 1805 bis 1995 im heroischen Modus.\r\n* '''Schatten anziehen''' \r\n* '''Schattenblitzsalve''' - Die Schattenblitzsalve schleudert Geschosse von dunkler Magie auf in der Nähe befindliche Feinde und verursacht Schattenschaden. \r\n* '''Verbannen''' - Im heroischen Modus verbannt Vorpil einen Feind und verhindert damit jegliche Aktion, macht ihn aber bis zu 8 Sekunden lang unverwundbar. Es kann immer nur jeweils ein Ziel verbannt werden.",},
			["Großmutter Geyah"] = { content = "'''Großmutter Geyah''' ist die Mutter von [[Durotan]] und die Großmutter von [[Thrall]]. Man findet sie in der Haupthalle von [[Garadar]] in [[Nagrand]]. Sie sagt, dass die [[Mag'har]] hier durchhalten und dem Volk dienen müssen. Sie sagt, dass sie [[Garrosh Höllschrei]] als Beispiel dienen müssen, zeigen, dass das Leben weitergeht. Und wer sie verärgert, den wird Garrosh mit aller Kraft, die noch in ihm steckt, bestrafen. Geyah will auch, dass man nach ihrem Enkelsohn, [[Thrall]], den Sohn [[Durotan]]s, sucht und ihm sagt, dass sein Blut hier ist - in dieser zerschlagenen Welt. Dass man ihm sagt, dass das Erbe seines Vaters weiterlebt. \r\n==Großmutters Kräuterliste==\r\nGroßmutter Geyah kennt die Zutaten für einen Trank, der den Geist erweitert, damit sie mit den Geistern sprechen kann. Dazu braucht sie [[Olembabäume|Olembawurzeln]] aus [[Wälder von Terokkar|Terokkar]], Marschenbeeren aus den [[Zangarmarschen]], Telaarifarn aus [[Nagrand]] und Drachenwirbel aus dem [[Schergrat]]. Sie hat die Anleitung zum Anbau dieser Kräuter auf ein Pergament geschrieben. Die Olembawurzel ist eine ziemlich gewöhnliche Wurzel in den Wäldern von Terokkar in der Nähe der Olembabäume, die einen Großteil des Waldes einnehmen. Die Marschenbeere wächst ausschließlich in den [[Zangarmarschen]]. Man kann sie nur bei der [[Festung der Ango'rosh]] im Nordwesten der Marschen finden. Doch man sollte sich vor den Ogern hüten, die die wertvollen Beeren wie Schießhunde bewachen. Der Talaarifarn ist wohl von den Kräutern auf dieser Liste am leichtesten zu pflücken. Man findet ihn südlich von [[Garadar]] im [[Telaaribecken]]. Er wächst fürgewöhnlich am Wasser. Das letzte Kraut auf der Liste wächst ausschließlich im [[Schergrat]]. Drachenwirbel wächst am Ende der zerklüfteten Felsformationen, die die Schlucht des Schergrats begrenzen. Die Felsformationen sehen aus wie Reihen über Reihen von scharfen, spitzen Zähnen.",},
			["Grubenlichtmine"] = { content = "Die Grubenlichtmine befindet sich im Südwesten der [[Geisterlande]]. Man gelangt dorthin, wenn man die Straße, die nach Süden aus [[Tristessa]] herausführt nimmt und sich an der Wegzweigung rechts hält. Kurz nach dem [[Ziggurat]] zur Rechten kommt ein kurzer Trampelpfad Richtung Westen. Die Grubenlichtminen wurden von den [[Gnolle der Schwarzpfoten|Gnollen der Schwarzpfoten]] überrannt, doch sie sind wichtig in strategischer Hinsicht für den fortwährenden Schlachtzug in den [[Geisterlande]]n. Man findet hier [[Grubenlichterz]] in den Zinn- und Kupfervorkommen, aber auch die [[Gnolle]] tragen es mit sich herum. Vor den Minen trifft man auf Lehrling Shatharia. Sie wurde vom [[Sanktum der Sonne]] hierher geschickt, um ein paar Erzproben zu sammeln, aber die [[Gnolle]] haben diesen Ort überrannt und ihr Kopf wird noch auf dem Präsentierteller landen, wenn sie diese Proben nicht bald zum Magister bringt.",},
			["Grubenlord"] = { content = "Als der Hexenmeister [[Archimonde]] für [[Sargeras]] eine riesige Armee aufstellen sollte, um die Schöpfung allen Lebens vernichten zu können, wandte er sich an den abgrundtief bösen Dämonenkönig [[Mannoroth]]. Denn die Grubenlords, die unter [[Mannoroth]] dem Zerstörer dienen, gehören zu den grausamsten, barbarischsten Schlächtern, die je die unerforschten Einöden des [[Sog der Unterwelt|Sogs der Unterwelt]] durchstreift haben. Die riesigen Kampfmaschinen aus Hass und Tod lieben nichts mehr, als zu töten und alle Lebewesen ins Elend zu stürzen. Sie sind [[Mannoroth]] fanatisch treu ergeben und machen vor nichts Halt, um den Willen der [[Brennende Legion| Brennenden Legion]] auszuführen und alle Lebewesen ins Elend zu stürzen.\r\nGrubenlords benutzen [[Teufelshund]]e, um Quellen der Magie aufzuspüren, wo immer sie zu finden sind. [[Teufelshund]]e, die sich von Magie ernähren, saugen unglückseligen Zauberern gern alle Energie aus, ehe sie ihre Körper zerfetzen. \r\n'''Quelle''': \r\n==Arten==\r\n* [[Oberanführer der Grube]]\r\n==Persönlichkeiten==\r\n* [[Aggonar]]\r\n* [[Azaloth]]\r\n* [[Azgalor]]\r\n* [[Brutallus]]\r\n* [[Magtheridon]]\r\n* [[Makazradon]]\r\n* [[Mannoroth]]\r\n* [[Morgroron]]\r\n* [[Xaxion Drak'eem]]",},
			["Grubenlords"] = { content = "#REDIRECT [[Grubenlord]]", redirect = "Grubenlord",},
			["Gruft"] = { content = "Die '''Gruft''' ist ein vielgenutztes Gebäude der [[Geißel]]. An diesem Ort werden untote Helfershelfer in die Dienste der Geißel gerufen. Hier werden [[Gargoyle]]s belebt und erhalten ihre tödlichen Angriffsfähigkeiten. [[Ghul]]s werden hier darin unterwiesen, ihre gefallenen Widersacher zu verspeisen, um ihre Kraftreserven aufzufrischen und [[Gruftbestie]]n erhalten hier die Fähigkeit, ihre unentrinnbaren Netze auszuwerfen.\r\n'''Quelle:''' [[Warcraft III - Reign of Chaos]]",},
			["Gruftbestie"] = { content = "Die verschlagenen '''Gruftbestien''' waren einst nerubische Krieger, Diener der [[Gruftlords]], die [[Neruber]]-Herren des alten Spinnen-Königreichs [[Azjol-Nerub]], das in grauer Vorzeit über das arktische Land [[Nordend]] herrschte. Doch der [[Lichkönig]] zerstörte die Zivilisation der Gruftbestien und riss die Herrschaft über den Kontinent des ewigen Eises an sich. Nun befehligen die abscheulichen Bestien ihre Spinnenuntergebenen im Namen ihres Meisters [[Ner'zhul]]. Die widerlichen Kreaturen können Schwärme gefährlicher Insekten herbeirufen und netzartige Fäden ausstoßen, die ihre Gegner lähmen und verletzen. Die [[Neruber]] von [[Azjol-Nerub]] waren auch schon immer geschickt darin, fliegende Kreaturen in ihren zähen Netzen zu fangen. In diesen Gespinsten gefangene Kreaturen können sich irgendwann einmal zwar befreien und sich möglicherweise immer noch verteidigen, aber solange sie im Netz der Gruftbestien gefangen sind, sind sie bewegungsunfähig. Die Fähigkeit, ihre unentrinnbaren Netze auszuwerfen, erhalten Gruftbestien in einer [[Gruft]]. \r\n==Persönlichkeiten==\r\n* [[Anok'suten]]\r\n* [[Anub'arak]]\r\n* [[Anub'shiah]]",},
			["Gruftbestien"] = { content = "#REDIRECT [[Gruftbestie]]", redirect = "Gruftbestie",},
			["Gruftkäfer"] = { content = "'''Gruftkäfer''' sind kleine Insekten, die ein [[Gruftlord]] aus den Tiefen der Erde herbeirufen kann. Dazu benötigt er eine Leiche, denn nichts fressen Gruftkäfer lieber als vermoderndes Fleisch. Gruftkäfer sehen aus wie große Skarabäen mit mächtigen Kieferzangen, um Fleisch zu zerteilen. Sie werden so groß wie Katzen und gehorchen nur den Ranghöchsten [[Gruftlord]]s.",},
			["Gruftlord"] = { content = "'''Gruftlords''' sind untote [[Spinnenlord]]s, die über die untoten Krieger von [[Azjol-Nerub]] herrschen. Sie schlossen sich dem [[Lichkönig]] im Austausch für Macht und Unsterblichkeit an, ähnlich den menschlichen [[Todesritter]]n. Der bekannteste Gruftlord ist [[Anub'arak]].\r\n==Persönlichkeiten==\r\n* [[Anub'arak]]\r\n* [[Anub'rekhan]]",},
			["Gruftlords"] = { content = "#REDIRECT [[Gruftlord]]", redirect = "Gruftlord",},
			["Gruftscheusal"] = { content = "#REDIRECT [[Gruftbestie]]", redirect = "Gruftbestie",},
			["Grulloc"] = { content = "Der [[Gronn]] Grulloc, ein Sohn von [[Gruul]] dem Drachentöter, lebt an einem Ort namens Verfluchtes Dunkel im [[Schergrat]]. Das Dunkel befindet sich am östlichen Rand des Drachenend in der Nähe des [[Zirkel des Blutes]]. Dort schmiedet er seine dümmlichen Pläne. Sein wertvollster Besitz ist ein Drachenschädel, den er als Erinnerung an das Gemetzel seines Vaters am [[Schwarzer Drachenschwarm|schwarzen Drachenschwarm]] bewahrt.",},
			["Grundlegendes Artifix"] = { content = "Ein '''Grundlegendes Artifix''' ist ein beinahe universell einsetzbares mechanisches Bauteil, das den Tüftlern und Schmieden von [[Gnomeregan]] von großem Nutzen war. Doch während der panischen Flucht aus der Stadt hat niemand daran gedacht, einige von diesen Geräten mitzunehmen. Man wird sie in den tieferen Bereichen der Stadt finden, in \"Künstliche Extrapolatoren\" genannten Behältern.",},
			["Grund der Speerspießer"] = { content = "Der '''Grund der Speerspießer''' liegt in der [[Blutschlägerklamm]] im Schergrat. Dort lebt der Stamm der [[Speerspießer]]. Sie sind zwar nicht der einzige Stamm, der die Horde bedroht, aber sie sind am nächsten und die, die die Orcs besiegen mussten, um die Donnerfeste beziehen zu können.",},
			["Grunzer"] = { content = "Grunzer bilden die ersten und letzten Verteidigungslinien der [[Horde]]. Diese kräftigen Kämpfer bewaffnen sich mit mächtigen Streitäxten und sind Musterbeispiele für die Wildheit und Verschlagenheit ihres Volkes. In früheren Generationen waren Grunzer für ihre Verworfenheit und Brutalität bekannt. Doch heute, unter der visionären Führerschaft von [[Thrall]], haben sie mehr Ähnlichkeit mit ihren wilden, aber edlen [[Krieger]]-Vorfahren. Wann immer Grunzer feindliche Gebäude angreifen, plündern sie diese wenn sie können, um Rohstoffe zu gewinnen und damit mehr Truppen zu unterstützen oder Verteidigungen zu errichten.",},
			["Gruselkürbis"] = { content = "Nur zu den Schlotternächten kann man den Gruselkürbis erbeuten: Der kopflose Reiter, der zur Schlotternachts-Zeit sein Unwesen auf dem Friedhof des [[Scharlachrotes Kloster|Scharlachroten Klosters]] treibt, hat manchmal auch den Gruselkürbis als Beute dabei.",},
			["Gruul"] = { content = "#REDIRECT [[Gruul der Drachenschlächter]]", redirect = "Gruul der Drachenschlächter",},
			["Gruuls Unterschlupf"] = { content = "'''Gruuls Unterschlupf''' am Ende der [[Dolchrachenklamm]] im [[Schergrat]] ist der Sitz von [[Gruul]] dem Drachenschlächter, dem Vater der anderen [[Gronn]]s und er läßt seinen Unterschlupf nur von den Kräftigsten unter den [[Oger]]n bewachen. findet man Gruuls Unterschlupf.\r\n==Geschichte==\r\nDer Speerspießerklan zählte einst zu den schwächsten Ogerklans, da sie nicht so zahlreich wie die Blutschläger waren oder über die Stärke der Felsfäuste verfügten. Doch die Geburt Maulgars sollte ihr Schicksal für immer verändern. Maulgar war stärker und kühner als jeder andere Oger seines Alters und seine Fertigkeiten im Kampf zogen rasch die Aufmerksamkeit des vorherigen Hochkönigs auf sich. Der König verlangte, dass Maulgar seine Stärke demonstriere, und dieser kam der Bitte nach, indem er in Sekundenschnelle das Genick des Königs brach. Dieses Ereignis verlagerte das Gleichgewicht der Macht von den Felsfäusten zu den Speerspießern und zog auch die Aufmerksamkeit des mächtigen Gruul selbst auf sich. Mit fanatischer Ergebenheit zu den Gronn dient Maulgar nun als Gruuls rechte Hand und Wächter des Unterschlupfes des Gronnlords. Maulgar selbst umgibt sich nur mit den Mächtigsten seines Klans und führt diese erlesenen Wenigen in die Schlacht, um seine gewaltigen Kampffertigkeiten mit ihrer mächtigen Magie zu verstärken. Mit solch mächtigen Verbündeten an seiner Seite und dem Rest des Speerspießerklans unter seiner Befehlsgewalt ist Maulgar zum gefährlichsten Oger der ganzen Scherbenwelt geworden. \r\nIn Azeroth wurde der Schwarze Drachenschwarm lange Zeit sowohl von Sterblichen als auch von anderen Drachen gehasst und gejagt. Nicht jedoch auf Draenor. Tatsächlich sind Drachen nämlich keine auf Draenor einheimische Spezies. Doch als der berüchtigte Drachenaspekt Todesschwinge das Dunkle Portal und Draenor entdeckte, war er sich sicher, dass nur wenige der Bewohner Draenors es wagen würden, die Drachen herauszufordern, und so zog er während des Zweiten Krieges nach Draenor und versteckte dort auf der ganzen Welt seine Gelege. Dann kehrte er nach Azeroth zurück und hinterließ nur eine kleine Zahl Drachlinge, um die Eier zu bewachen. Jedoch hatte sich Todesschwinge gewaltig verrechnet, als er einige seiner Eier im Schergrat ließ. Den dort lebenden Gronn gefiel die Aussicht auf diese Bedrohung ihrer Herrschaft über das Gebiet gar nicht. Die Spannungen schlugen schnell in Gewalt um. Angeführt vom mächtigen Gruul erwiesen sich die Gronn und ihre Ogerdiener als zu viel für die zahlenmäßig unterlegenen Wächter der Schwarzen Drachen. Nahezu ein jeder Drache wurde von den diabolischen Beschwörungen des Speerspießerklans aus dem Himmel gerissen und dann von Gruul auf den steinernen Spitzen der Berge gepfählt. Die Knochen, die noch immer in Drachenend verstreut sind, erinnern kalt an die Niederlage der Drachen. \r\n==Bosse==\r\n* [[Gruul]]\r\n* [[Blindauge der Seher]]\r\n* [[Gicherer der Wahnsinnige]] \r\n* [[Krosh Feuerhand]] \r\n* [[Maulgar]] \r\n* [[Olm der Beschwörer]]",},
			["Gruul der Drachenschlächter"] = { content = "Gruul der Drachentöter ist der Vater der sieben [[Gronn]] und Herrscher über die [[Oger]] der [[Scherbenwelt]]. Seinen Sitz hat er in [[Gruuls Unterschlupf]] im [[Schergrat]]. Er wurde berühmt durch das abschlachten der [[Drache]]n des [[Schwarzer Drachenschwarm|Schwarzen Drachenschwarms]], der in die [[Scherbenwelt]] kam, um die alte [[Horde]] dort zu unterstützen.\r\nZu seinen Söhnen gehören:\r\n* [[Durn der Nimmersatte]]\r\n* [[Goc]] \r\n* [[Gorgrom der Drachenfresser]] \r\n* [[Grulloc]] \r\n* [[Maggoc]] \r\n* [[Skulloc Seelenschänder]]\r\n* [[Slaag]]",},
			["Grüner Drachenschwarm"] = { content = "==Allgemeines==\r\nDie verzauberten, ätherischen '''grünen Drachen''' dienen nur den Kräften der Natur und wahren das Gleichgewicht zwischen sterblichen Kreaturen und ihrer in ständiger Veränderung begriffenen Welt. Sie werden von dem träumenden Drachenaspekt [[Ysera]] regiert und hegen eine besondere Vorliebe für die [[Nachtelfen]] und ihre [[Druiden]]. Die Drachenbrut besetzt die Ränge der Bodentruppen innerhalb der fünf großen Drachenregimenter. \r\n==Lebensräume==\r\nÜberwiegend leben die grünen Drachen in einer mystischen Dimension, die als [[Smaragdgrüner Traum]] bezeichnet wird, doch ein paar der anmutigen Geschöpfe streifen noch durch die schattigen Wälder von [[Eschental]]. [[Ysera]] hat ihre treuen Diener vor einer lauernden Gefahr im Inneren des [[Versunkener Tempel|Versunkenen Tempels]] gewarnt. Die Bodentruppen des großen Drachenregiments setzen nun alles daran, das Land vor der kommenden Zerstörung zu bewahren. Auf Geheiß ihrer Königin, patrouilliert die grüne Drachenbrut mitten in den düsteren [[Sümpfe des Elends|Sümpfen des Elends]], um [[Azeroth]] vor dem wachenden Bösen zu schützen. \r\n===Der Alptraum===\r\nEin rauer Wind weht durch die Kronen der Großen Bäume. Etwas Unheimliches hat sich fernab der wachsamen Augen der Beschützer [[Azeroth]]s eingeschlichen und bedroht nun [[Eschental]], den [[Dämmerwald]], [[Feralas]] und das [[Hinterland]]. Vier der mächtigen Wächter des grünen Drachenschwarms sind aus dem [[Smaragdgrüner Traum|Smaragdgrünen Traum]] zurückgekehrt, doch die einstmals stolzen Beschützer verbreiten nun nichts als Tod und Zerstörung. [[Azeroth]] braucht tapfere Abenteurer mehr denn je, die das Land gegen diese düsteren Vorboten verteidigen. \r\n==Namhafte Grüne Drachen==\r\n* '''[[Ysera]]'''\r\n* [[Eranikus]]\r\n* [[Hazzas]]\r\n* [[Lethon]]\r\n* [[Merithra des Traums]]\r\n* [[Morphaz]]\r\n* [[Smariss]] (engl. Emeriss)\r\n* [[Somnus]]\r\n* [[Taerar]]\r\n* [[Traumsense]]\r\n* [[Wirker]]\r\n* [[Ysondre]]",},
			["Grünkiemen"] = { content = "#REDIRECT [[Murlocs der Grünkiemen]]", redirect = "Murlocs der Grünkiemen",},
			["Gul'dan"] = { content = "Gul'dan, Hexer des inneren Kreises und Vernichter der Träume(er selbst bezeichnete sich oft als\"Inkarnation alles Finsteren\") war nicht zufriedenen mit den Handlungen der [[Horde]], die ebenfalls dem mysteriösen [[Schattenrat]] zugrunde lag.Er ließ die [[Orcs]] aus dem [[Kelch der Einheit]] trinken und verdarb so das einst stolze Volk. Als ehemaliger Schüler von [[Ner'zhul]] wurde er durch den Dämon [[Kil'jaeden]] in die Geheimnisse der Wissenschaft eingeführt. Er war zweifellos der mächtigste Hexer und wurde von der Idee verfolgt, das legendäre Grab von [[Sargeras]] wieder zu finden. Er dachte in der Tat daran die eingravierten Inschriften zu entziffern, welche schon sehr lange auf dem Grabe waren, seit [[Aegwynn]] den Körper des [[Dämonen]] begrub. Seine geheimnisvolle Magie hat der [[Horde]] gute Diene erwiesen. Nekromanten, [[Oger]]magier und [[Todesritter]] sind in der Tat resultierend aus seiner Zusammenarbeit mit den Kräften des Jenseits. Er versuchte sich auch in der Kontrolle von [[Elementare]]n und beschwor im [[Schattenmondtal]] ein Wesen genannt [[Cyrukh der Feuerlord]] und erschuf dabei den Vulkan, der als [[Hand von Gul'dan]] bekannt ist.\r\nEs war Gul'dan, der die Klans zusammengeschlossen und so die Geburt der [[Horde]] eingeleitet hat, die zuerst durch [[ Schwarzfaust ]] regiert wurde, der gänzlich dem Hexer untergeben war, dann durch [[Orgrim Schicksalshammer]], welcher ihn betrog. Verdrängt von der Macht, schaffte es Gul'dan dank seinem Clan und dem treuem [[Cho'gall]] es dennoch, das legendäre Grab wieder zu finden. Aber er fand an der Stelle von phantastischer Macht nur den Tod.Sein verdebter Leib wurde verfetzt und nur sein Totenschädel, gesättigt von Gul'dans Macht, überstand das Gemetzel.\r\n'''Siehe auch''': \r\n* [[Schädel des Gul'dan]]",},
			["Gundrak"] = { content = "'''Gun'Drak''' ist die Hauptstadt der [[Eistrolle]] und fasst derzeit eine Einwohnerzahl von 13.000. Die unabhängigen Eistrolle kontrollieren von hier aus [[Zul'Drak]] und versuchen mit allen Mitteln die [[Geißel]] zu bekriegen. Gun’Drak befindet sich in der östlichen Region von [[Nordend]].\r\nGun'Drak ist die einzige Stadt im eisigen [[Zul'Drak]] und das zuhause des [[Drakkari]] Eiskönigs. Ein massiver Ort mit dicken Wänden, kleinen Wachtürmen und starken Toren. Hinter den Toren von Gun’Drak ist alles abgestuft und verdeckt gebaut worden, kleine Tiere werdet ihr hier ebenfalls antreffen. Die Architektur ist mit der von [[Zuldazar]], welches im Süden liegt, zu vergleichen. Die Eistrolle sind barbarisch und brutal, aber dennoch ist eine kleine Menge an Organisation unter den Trollen vorhanden. Frauen und Kinder kümmern sich um das Putzen, Essen machen und um die Kleider. Die Krieger hingegen kämpfen die meiste Zeit in Wrestler-Manier gegeneinander. Die Drakkari heißen ihre Gäste nicht gerne willkommen, zuerst müssen sie in einem Kampf besiegt werden um von ihnen angesehen zu werden. Die Trolle sind unberechenbar und so könnte es passieren, dass ein einsamer Wanderer die nächste Mahlzeit der Drakkari darstellt. Um nach Gun’Drak zu kommen, sollte man dies am besten unbeachtet tun, denn die meiste Zeit sind die Trolle damit beschäftigt, zu kämpfen oder zu trinken. \r\n \r\n==Bosse==\r\n* [[Slad'ran]]\r\n* [[Moorabi]]\r\n* [[Bloodstone Annihilator]]\r\n* [[Gal'darah]]",},
			["Gunthers Zufluchtsort"] = { content = "'''Gunthers Zufluchtsort''' ist eine kleine Insel in einem See im nordöstlichen [[Tirisfal]], wo der Lich Gunther Arkanus lebt.\r\nVor langer Zeit waren Gunther Arkanus und [[Bethor Eismacht]], wie auch der jetzt der [[Geißel]] dienende Totenbeschörer [[Thule Rabenklaue]], Freunde und Schüler bei den [[Kirin Tor]]. Gunther und Bethor fielen beide der Seuche anheim, aber Bethor dachte, Gunther wäre entweder tot geblieben oder für die Armee des [[Lichkönig]]s erweckt worden. Bethor will Gunther nun für die [[Verlassene]]n gewinnen. Dafür hat er einen Zauber auf ein Buch gelegt, der Gunther, sobald er es sieht, zeigen wird, dass Bethor ebenfalls frei vom Einfluss des [[Lichkönig]]s ist. Doch bevor Gunther Arkanus dem Boten von Bethor Eismacht Glauben schenkt, muss er den Beweis haben, dass der Bote der [[Geißel]] feindlich gegenübersteht. Dafür soll jener [[Lillith Nefara]] beschwören und töten. Denn es gibt einen alten, blutigen Altar kurz vor der Südküste seiner Insel. Er wird von einer mächtigen Dienerin der Geißel, [[Lillith Nefara]], verwendet. Wenn man eine Kerze des Heranlockens auf dem Altar entzündet, wird Lillith erwachen. Danach bringt man seinem alten Kameraden Bethor Eismacht einen Netheredelstein. Er wird ihnen ermöglichen, miteinander zu kommunizieren... und Gunther hat ihm eine Menge zu erzählen.",},
			["Gurok der Thronräuber"] = { content = "Gurok der Thronräuber in [[Nagrand]] wird von den [[Oger der Totschläger]] im Totschlägerhügel verehrt. Man ruft ihn, indem man sieben Ogerschädel von Totschlägern auf Guroks irdenes Brandmal setzt.",},
			["Gurtogg Siedeblut"] = { content = "Gurtogg Siedeblut ist ein [[Höllenorc]] im [[Schwarzer Tempel|Schwarzen Tempel]].\r\n==Taktik==\r\nGurtogg Siedeblut teilt immensen Schaden auf alle Spielern aus. Nehmt 10 Heiler mit. Zudem müssen sich die Tanks beim Tanken abwechseln, da der erlittene Schaden mit der Zeit steigt. Während der Teufelswut-Phase heilen die Heiler vorrangig den jeweilig betroffenen Spieler, während die Schadensausteiler wie gewohnt Ihr Werk verrichten.\r\n===Harte Aufgaben für jedermann===\r\nAlle zehn Sekunden wirkt Gurtogg die Fähigkeit SIEDEBLUT auf die fünf Spieler, die am weitesten vom Boss entfernt stehen. Dieser Debuff fügt den Betroffenen für 24 Sekunden sekündlich 600 Schadenspunkte zu und ist stapelbar. Um den Debuff gleichmäßig auf die Schlachtzugsmitglieder zu verteilen, müssen die drei Gruppen der Reihe nach die Positionen tauschen. Nach drei Durchgängen begibt sich die erste Gruppe erneut nach hinten, und so fort. Eine Gruppe erhält zusammen über 24 Sekunden 72.000 Schadenspunkte, welche Ihr natürlich gegenheilen müsst. Dies erfordert selbst mit Fläschchen und Schattenpriesterunterstützung oftmals zwei Heiler. Die verbleibenden vier Heiler kümmern sich um die drei Tanks, sind aber dennoch im Regelfall in die Rotation mit eingebunden. Die Tanks hingegen müssen soviel Bedrohung wie möglich aufbauen. Der Tank der momentan die Aufmerksamkeit von Siedeblut hat, erhält regelmäßig eine zusätzliche SÄUREWUNDE. Dieser Schwächungszauber dauert eine Minute an, solange er nicht durch einen weiteren Angriff erneuert wurde und setzt Eure Rüstung um 500 Punkte je gestapeltem Zauber herab. Ausserdem fügt er Euch alle drei Sekunden 300 Naturschaden pro gestapeltem Effekt zu. Die drei Tanks wechseln sich untereinander regelmäßig als Haupttank ab, da dieser Schwächungszauber irgendwann auch den stärksten Tank aus den Latschen haut. Siedeblut setzt DESORIENTIERUNG und RÜCKSCHLAG ein, die den Bedrohungwert des Tanks reduzieren - der ideale Moment, um den Tank zu wechseln. \r\n===Eine Menge Schaden===\r\nDurch den BOGENZERKRACHER und den TEUFELSSÄUREATEM erhalten die zwei Tanks mit der niedrigsten Bedrohung zusätzlichen Schaden, was den Wuterhalt bei Druiden und Kriegern fördert. Der TEUFELSSÄUREATEM zielt gelegentlich auch auf die Gruppe, was aufmerksame Heiler erfordert. Es ist immens wichtig, dass sich die Schadensausteiler in dieser Phase eher zurückhalten, und im Bedrohungsniveau hinter den zwei obersten Tanks bleiben, beziehungsweise den jeweils nicht tankenden Tanks die Gelegenheit geben, mehr Bedrohung aufzubauen. Etwa 90 Sekunden nach Kampfbeginn folgt die 30-sekündige TEUFELSWUT-Phase, die das Kampfprinzip gehörig auf den Kopf stellt. \r\n===Siedeblut wird wütend===\r\nWährend der TEUFELSWUT-Phase greift Siedeblut einen zufälligen Helden an, bis dieser entweder das Zeitliche segnet oder die 30 Sekunden vorüber sind und der Kampf mit Phase Eins wieder von vorne beginnt. Die Trefferpunkte und die Rüstung des betroffenen Spielers erhöhen sich stark, was auch nötig ist, da Gurtogg in dieser Phase noch härter zuschlägt. Siedebluts Opfer benötigt in dieser Phase extrem viel Heilung. Die Tanks und die letzte Gruppe mit dem SIEDEBLUT-Debuff erhalten weiterhin Schaden durch die DoT’s, was Eure Heiler sehr in Anspruch nimmt. Abhängig nach Klasse sollte das Opfer der TEUFELSWUT zusätzliche Schutzmaßnahmen in Betracht ziehen. Heilklassen heilen sich, Schurken nutzen Entrinnen, Krieger ziehen ein Schild an, Jäger nutzen den Aspekt des Affen, Hexer wirken Lebensentzug und Magier beten um Ihr Leben. Stirbt der Spieler mit der TEUFELSWUT, hat der Rest des Schlachtzugs wenig Chancen zu überleben. Eure Schadensausteiler geben in dieser Phase so richtig Gas, da sie in diesen 30 Sekunden keinerlei Bedrohung generieren. Danach beginnt das Spiel von vorne – Tanks wechseln sich ab, während sich die drei Gruppen hinten beim SIEDEBLUT-Debuff abwechseln. Der Kampf muss im Übrigen nach zehn Minuten erfolgreich absolviert sein, da der Boss ansonsten in einen WUTANFALL gerät und alles binnen Sekunden vernichtet. \r\n'''Quelle:''' www.buffed.de\r\n \r\n==Fähigkeiten==\r\n* '''Siedeblut:''' Bringt das Blut des Ziels zum Sieden und fügt 24 Sekunden lang alle 1 Sek. 600 Schaden zu. Tritt nur in Phase Eins auf. \r\n* '''Säurewunde:''' Fügt einem Gegner alle 3 Sek. Naturschaden zu und verringert seine Rüstung um 500. Bis zu 60-mal stapelbar. Hält 1 Minute lang an und tritt nur an Tanks in Phase Eins auf. \r\n* '''Desorientierung:''' Der Tank mit der höchsten Bedrohung wird für fünf Sekunden desorientiert und Siedeblut greift den nächsten Tank an. Tritt nur in Phase Eins auf.\r\n* '''Rückschlag:''' Der Tank mit der höchsten Bedrohung wird zurückgeschleudert und verliert einiges an Bedrohung. Tritt nur in Phase Eins auf.\r\n* '''Bogenzerkracher:''' Schlägt in einem Bogen wild um sich und fügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden normalen Schaden plus 125 zu. \r\n* '''Teufelssäureatem:''' Fügt allen Gegnern in einem kegelförmigen Bereich vor dem Boss 2850 bis 3150 Naturschaden und 20 Sekunden lang alle 5 Sek. 2750 zusätzlichen Schaden zu.\r\n* '''Bedeutungslosigkeit:''' Eure Aktionen erzeugen für 30 Sekunden keinerlei Bedrohung. Tritt nur in Phase Zwei auf.\r\n* '''Teufelswut:''' Eure Rüstung erhöht sich um 15.000 Punkte, Eure Trefferpunkte erhöhen sich um 30.000, Euer Schaden und Eure Heilung erhöhen sich ebenfalls, und Ihr seid das einzige Ziel von Gurtogg Siedeblut für 30 Sekunden.\r\n* '''Wutanfall:''' Nach zehn Minuten dreht Siedeblut richtig durch, und löscht den Schlachtzug innerhalb weniger Sekunden aus.",},
			["Gurubashi"] = { content = "Das Reich der '''Gurubashi''' ist das südliche der beiden [[Troll]]-Imperien. Die Haupstadt des Gurbuashi-Reiches (Kurz: das Gurubashi) war [[Zul Gurub]]. Der Zeitpunkt der Reichsgründung ist unklar. Den Impuls zur Gründung gab allem Anschein nach der [[Stamm der Zandalar]]. Das Reich dehnte sich als vermutlich erste von Sterblichen Wesen geschaffene Hochkultur [[Azeroth]]s, evtl. parallel mit dem Reich der [[Amani]] im Norden, aus. Seine Überrreste sind u.a. in [[Tanaris]] ([[Zul'Farrak]]), grundsätzlich aber im gesamten Süden [[Azeroth]]s zu finden. \r\nDie [[Trolle]] des Gurubashi hielten ihr eigenes Volk den Überlieferungen zufolge für das einzige vernunftbegabte Volk [[Azeroth]]s und im Vergleich mit den heutigen [[Troll]]stämmen war das Gurubashi eine Hochkultur mit erstaunlichem Wissen über kosmische Zusammenhänge, Architektur, Statik und Schriftkunde, allerdings schon damals mit starkem Hang zum Mystizismus. Doch seine Errungenschaften sind fast vollständig vergessen.\r\nDer Aufstieg der [[Nachtelfen]] und die daraus resultierenden Kriege führten zum Niedergang des Gurubashi, da die elfische [[Magie]] der trollischen weit überlegen war. Niederlage reihte sich an Niederlage, das Reich schrumpfte innerhalb kurzer Zeit erheblich. Als die Zerstörung des [[Brunnen der Ewigkeit]] Azeroth zerschmetterte, lag das Reich der Gurubashi bereits in den letzten Zügen. In der Folgezeit setzte eine langsame Erholung ein, auch wenn die trollische Hegemonie über den Kontinent verloren war. [[Hakkar]]s Anrufung führte zu einer letzten Blütezeit und sprunghaften Ausdehnung der Reichsgrenzen, der ein blutiger Bürgerkrieg folgte, als ein Teil der [[Trolle]] sich gegen den Blutgott auflehnte. Das Gurubashi zerbrach in Folge der gnadenlosen, lang andauernden Kämpfe endgültig. Der Hass, den die verschiedenen Stämme gegeneinander empfinden, wurde in dieser Zeit zementiert. \r\nDie heute im [[Schlingendorntal]] lebenden [[Trolle]], die [[Trolle der Sandwüter]] in [[Zul'Farrak]] sowie die zur [[Horde]] gehörenden [[Dunkelspeere]] sind Nachkommen der Stämme des Gurubashi-Reiches.",},
			["Gurubashis Untergang"] = { content = "=== Die dritte Trolllegende===\r\n''(Gefunden auf einer Steintafel im [[Schlingendorntal]])''\r\nUnd wie eine Wassersäule erhob sich [[Neptulon]] aus dem Ozean, um die großen Kraken zu der verdammten Stadt I'lalai zu schicken. So groß waren die Kraken, dass ganze Wälder von Tang zwischen ihren Tentakeln Platz fanden und Leviathane durch ihre Körper schwammen. \r\nDann hob der größte Kraken seine Arme und ließ sie donnernd ins Meer schlagen, so dass gewaltige Wellen sich auftürmten, Wellen, die geradewegs auf I'lalai zurasten. \r\nDie Krakken brüllten, und ihre Stimmen klagen wie das Brausen des Sturms über der See: \r\n\"Wir kommen.\" \r\nMin'loth stand unerschütterlich und beschwor seine magischen Kräfte. Die zu I'lalai geschickten Wellen teilten sich und ergossen sich nach beiden Seiten, den Dschungel dahinter unter sich begrabend. Alsdann hieß Min'loth seine Diener Bindungsgesänge anstimmen, und Dutzende von Trollstimmen erhoben sich tosend. \r\nUnd eine Stimme war lauter als alle anderen. \r\nMin'loth brülle auf und seine Magie sammelte die Macht der Zauber seiner Diener und er schleuderte sie den nahenden Kraken entgegen. \r\nDie See teilte sich und Min'loths Zauber raste auf die Diener des [[Neptulon]] zu. Blitze zerrissen den Himmel, als der Zauber sie traf. Tausende Blitze zuckten herab, brachten das Wasser zum Kochen und gruben Krater in die Erde. \r\nMin'loth stieß ein Triumphgeheult aus, glaubte er doch, sein Zauber werde die gigantischen Kraken fällen. \r\nAber die Kraken sind alt, sehr alt. Sie waren dabei, als das Meer das Land gebar. \r\nSie waren dabei, als die Altvorderen herrschten, und als die Reisenden kamen, um sie zu stürzen. Sie waren dabei, als die Magie noch neu war. \r\nSie sind alt und hüten viele Geheimnisse. [[Min'loth]]s Zauber war stark, aber nicht anders als der Troll war auch der Zauber sterblich. \r\nUnd so versagte er. \r\nZwar konnten die Kraken nicht gebunden werden, aber es machte sie wütend. Seit Ewigkeiten hatten Sterbliche ihnen keine Schmerzen mehr bereitet, und der Zauber der Trolle war wahrlich schmerzhaft. \r\nSie schüttelten den Bann von [[Min'loth]]s Zauber ab und schlugen dann zornig brüllend zurück. \r\nEin Rumpeln war zu vernehmen, als Grosse Wellen aus der Tiefe emporstiegen und auf das Land zurasten. Als sie [[I'lalai]] erreichten, warfen sie einen Schatten auf die Stadt. \r\nAber bevor die Wellen sie zerstörten konnten, hielten die Kraken plötzlich inne und verharrten unbeweglich. \r\nDie [[Troll Hexendoktor]]en erzitterten und wehklagten ihrem Meister. [[Min'loth]] starrte auf die Berge im Wasser, verloren und doch trotzig. Er drehte sich zu seinen Adepten um und flüsterte seine letzten Worte, welche die Trolle in Stein meißelten. Dann wandte sich [[Min'loth]] den drohenden Kraken zu. \r\nEr verzog das Gesicht zu einer Fratze und wirbelte in einem letzten kühnen Akt seinen Stab herum. \r\nDann richteten die Kraken all ihre Wut auf [[Min'loth]] und der Ozean stürzte auf [[I'lalai]]. \r\nUnd es war nicht mehr. \r\nUnd dann überspülte das Wasser den Urwald und riss alles mit sich fort. Trolle und Wildtiere heulten auf, bevor das Wasser sie erfasste und in die Tiefe zog. \r\nViele Gurubashi fragten sich noch, warum der Ozean sie verschlang, aber sie starben unwissend. \r\nErst als das Wasser die Berge erreichte, hielt es inne. Besänftigt zog sich das Wasser danach wieder zurück und hinterließ einen Schauplatz der Verwüstung. \r\nTrotz allem blieb [[I'Lalai]] eine auf ewig versunkene Stadt. \r\nUnd [[Häuptling Var'gazul]], hinter den Bergen in [[Zul Gurub]] in Sicherheit, ging in den Urwald und fand dort keine Spur seines Volkes mehr. \r\nDa verzweifelte er, denn seine Träume von der Eroberung waren geplatzt. \r\nUnd [[Min'loth]] die Schlange ward niemals gefunden.",},
			["Gyrobohrmatischer Exkavationator"] = { content = "Ein '''Gyrobohrmatischer Exkavationator''' ist ein gnomisches Kampfgefährt, das von der Untergrundkampftruppe der Gnomeregan-Verbannten entwickelt wurde, um die Heimat der Gnome zurückzuerobern. Momentan arbeiten sie unter Leitung ihrer Kommandantin [[Shoni die Schtille|Shoni der Schtillen]] an einer Stückzahl von 400 Mechs, die aber alle noch nicht fertiggestellt sind. \r\nShoni fürchtet, dass sie nicht genug Teile haben werden, um ihre Flotte aus gyrobohrmatischen Exkavationatoren nach [[Dun Morogh]] zu bringen. Die Untergrundkampftruppe braucht mehr Ersatzteile und es gibt wohl keinen besseren Ort als Gnomeregan, um Ersatzteile für ihre Fahrzeuge zu besorgen. Bots und Mechs laufen dort herum wie Vieh auf der Weide und zwei Dutzend Innereien der auseinandergenommenen Roboter sollten ausreichen, um einen der Exkavationatoren zu flicken. Fehlen dann nur noch 398. \r\nEin anderes Problem ist die Energieversorgung der Exkavationatoren. Dafür benötigt Shoni die intakte Energieversorgung einen funktionierenden [[Goblinschredder]]s, ein sogenanntens [[Gnoamsprenkelspross]]. [[Sneeds Schredder]] in den den [[Todesminen]] besitzt so ein Gerät. Mit der Energieversorgung des Schredders können die Gnome den gyrobohrmatischen Exkavationatoren die erforderliche Energie zuführen, um durch die felsigen, unterirdischen Grenzen von Gnomeregan zu brechen und einem Gnomenangriff den Weg zu ebnen! \r\n'''Quellen'''",},
			["Gyrokopter"] = { content = "Die genialen [[Ingenieure]] der [[Zwerge]] griffen eine Vorlage ihrer erfindungsreichen [[Gnom]]-Vettern auf und konstruierten dieses Meisterstück der Luftaufklärung. Gyrokopter sind kleine, aber vielseitige [[Flugmaschine]]n, die weite Strecken mit großer Geschwindigkeit zurücklegen und feindlichen Bodentruppen ausweichen können. Die Vehikel sind zwar nicht gerade sehr stabil, aber mit Kanonen und Bomben bestückt und werden von den tollkühnen – schon fast verrückt zu nennenden – [[Zwerge]]n des [[Pilot]]enkorps geflogen.\r\n* '''Siehe auch:''' [[Flugmaschine]]",},
			["Haal'eshi Bau"] = { content = "#REDIRECT [[Arakkoa der Haal'eshi]]", redirect = "Arakkoa der Haal'eshi",},
			["Hafen der Vergeltung"] = { content = "An der Ostküste des [[Der heulende Fjord|Heulenden Fjords]] sind die [[Verlassene]]n im [[Hafen der Vergeltung]] eingetroffen, die ihre ganz eigene Seuche für den [[Lichkönig]] mitgebracht haben. Viele Jahre lang hat Fürstin [[Sylvanas Windläufer]] systematisch und geduldig die Entwicklung dieser Krankheit beobachtet. Nun ist die Zeit gekommen, um ihre Wirkung gegenüber der Geißel zu testen.",},
			["Hafen des Königs"] = { content = "Der '''Hafen des Königs''' ist ein Teil der [[Scharlachroten Enklave]] in den [[Östlichen Pestländern]]. Nachdem [[Neu Avalon]] und [[Havenau]] von der Geißel überrannt wurden, ist die Fratze des Todes auch über die letzten Scharlachroten Streitkräfte am Hafen gelangt und droht damit, sie jeden Augenblick in ihre Gewalt zu bringen. Die Lande des Scharlachroten Kreuzzugs sind verloren, also lassen sie ihre Armeen umdrehen und bereiten ihre Schiffe darauf vor, in Richtung der gefrorenen Weiten zu segeln. Wenn sie das nächste Mal der Geißel gegenübertreten, wird es in [[Nordend]] sein. Den Scharlachroten Kreuzzug gibt es nicht mehr. Lang lebe [[Der scharlachrote Ansturm]]! Die genauen Beweggründe und wie es dazu kam, dass Der Scharlachrote Ansturm ausgerufen wurde, beschreibt [[Hochgeneral Abbendis]] in dem Buch „[[Der Weg der Erlösung]]“.",},
			["Hafen von Menethil"] = { content = "Nach Menethil kommt man, indem man vom [[Loch Modan]] aus [[Dun Algaz]] durchquert, anschließend nordwärts der Straße folgt und sich dann an der Biegung westwärts hält. Menethil ist ein guter Ort, um Waren zu kaufen oder etwas trinken zu gehen und sich auszuruhen. Am Anfang jedes Monats werden die Marinesoldaten von [[Kul Tiras]] bezahlt und verlassen [[Theramore]] meist mit anderen Zielen. Viele kommen hierher, um Frauen aufzureißen, zu zechen und ihren Spaß zu haben.\r\n==Personen==\r\n* [[Archäologe Magenbitter]]\r\n* '''Comar Villard''' \r\n Comar Villard ist ein Mann, der seiner verlorenen Liebsten treu blieb und im [[Sumpfland]] nach Spuren seiner Frau sucht. Er war gerade zwei Wochen verheiratet, als seine Frau aus der Sicherheit des Hafens von Menethil verschwand. Fünf und Fünf Jahre, und er sucht immer noch nach ihr, auch wenn sie keine Schönheit war und es viele Damen gegeben hat, die ihren Platz einnehmen wollten.\r\n* '''Erster Maat Fitzsimmons''' \r\n Fitzsimmons war einst erster Maat auf der HERRIN DER MEERE. Er ist der einzige Überlebende der unglückseligen [[Dritte Flotte von Kul Tiras|Dritten Flotte von Kul Tiras]], die vor der Küste im Norden vernichtet wurde. Sein alter Kapitän Kapitän Halyndor erscheint ihm immer noch in seinen Träumen. Er wird einen frischen Drink brauchen, wenn er mit diesem Kater klarkommen und seine Geschichte fortsetzen soll.\r\n* '''Glorin Stahlbraue''' \r\n Glorin Stahlbraue ist der Priester hier in der Stadt. Wenn das verlorene Lichtgeschmiedete Eisen überhaupt gefunden werden kann, dann weiß er, wo man danach suchen muss. Er kann den Fluch nicht von dem [[Auge von Paleth]] nehmen. Die Augen wurden von [[Menschen]]priestern hergestellt, daher wird man nach [[Sturmwind]] gehen müssen, um jemanden zu finden, der helfen kann.\r\n* '''Hauptmann Starkfaust''' \r\n Hauptmann Starkfaust wünscht mit denen zu sprechen, die Hilfe gegen die [[Orcs]] anbieten wollen. Er ist in der Burg, im Kriegsraum. \r\n* '''Harlo Barnabas''' \r\n Harlo Barnabas erlitt schwere Wunden als [[Dun Modr]] an die [[Dunkeleisenzwerge]] fiel. Als die [[Zwerge]] die Stadt verließen, wurde er von einer verirrten Axt in den Rücken getroffen und alles wurde schwarz um ihn. Er wachte in Menethil auf, aber er fürchtet um seine Kameraden. Er hegt allerdings noch Hoffnung. Vielleicht ist Langzopf noch am Leben. \r\n* '''James Halloran''' \r\n James Halloran ist Gerber und seine Frau ist in letzter Zeit ziemlich launisch. Seine gegerbten Krokiliskenhäute sind nah und fern begehrt, Lieferungen gehen per Schiff zu allen Häfen der Welt, doch ihm fehlen zurzeit weichere Häute, wie die von jungen Krokilisken. Da er bald keine mehr hat, ist er bereit, einen Spitzenpreis für einen Stapel der Häute zu bezahlen. Er hat seinen Lehrling in die Marschen geschickt, um einige der berühmten riesigen Sumpflandkrokilisken zu häuten. Als er nicht zurückkam, ist er losgezogen, um ihn zu suchen. Es war kein schöner Anblick. Die Schwester sagt, er könnte durchkommen, aber derweil braucht er immer noch seine Häute.\r\n* '''Jack 'Blutgeld' Flint''' \r\n Jack 'Blutgeld' Flint möchte wieder auf See sein. Den Kuss des Windes zu spüren und sich von den Wellen wiegen lassen wie vor langer Zeit von seiner gesegneten Mutter. Seine Aufgabe ist es, eifrige Seelen nach Kalimdor zu bringen, in das Land der unbegrenzten Möglichkeiten. \r\n* '''Karl Boran''' \r\n Karl Boran sucht die verlorene Menethil-Statuette.\r\n* '''Mikhail''' \r\n Mikhail verbringt seinen Ruhestand in Menethil. Bevor er [[Sturmwind]] vor ein paar Jahren verließ, erwähnte er, dass er Schankkellner werden wollte. \r\n* '''Raufbold Jahn''' \r\n Raufbold Jahn gehört zu den [[Defias]] und half bei der Entführung des Königs von [[Sturmwind]].\r\n* '''Sida''' \r\n Sida wurde bei ihrem wöchentlichen Besuch an Eisenbarts Grabmal von grässlichen, triefenden [[Brühschlammer]]n angegriffen. Natürlich geriet sie in Panik. Sie hat ihre Tasche nach einem geworfen, aber das zeigte keinerlei Wirkung. Der [[Brühschlammer]] saugte sie einfach auf. Glücklicherweise gab ihr das genug Zeit wegzulaufen. Die schlechte Nachricht ist, dass sie dringend den Inhalt ihrer Tasche benötigt. Sie weiß nicht, nach welchem Brühschlammer sie ihre Tasche geworfen hat.\r\n* '''Tarrel Felsweber''' \r\n Tarrel Felsweber möchte, dass man zu [[Whelgars Ausgrabungsstätte]] reist und dort Kontakt mit Merrin Felsweber aufnehmt. Seine Frau, Merrin, hat ihm im letzten Monat jede Woche Briefe geschickt. Aber es sind fast zwei Wochen seit dem letzten Briefwechsel vergangen.\r\n* '''Vincent Hyal''' \r\n Vincent Hyal hat einen Bruder namens James Hyal, der mit Lady Prachtmeer über das Meer fuhr. Als Letztes hörte er, dass die Kämpfe dort drüben beigelegt waren und James irgendwo auf dem Kontinent ein Gasthaus eröffnete. Wo immer er sein mag, er ist sicher, seine Geschäfte blühen. Er war ein verdammt guter Koch. Aber er hat eine Weile nichts mehr von ihm gehört - zu sehr mit seinem Gasthaus beschäftigt. Der Amtmann in [[Theramore]] könnte Sich vielleicht zu ihm führen.",},
			["Hain der Silberschwingen"] = { content = "Der '''Hain der Silberschwingen''' befindet sich im Eschental und ist ein schwer umkämpftes Gebiet.\r\n==Wissenswertes==\r\nDie Schlacht der [[Nachtelfen]] im [[Eschental]] gegen das [[Holzfällerlager des Kriegshymnenklans]] wurde nicht nur von [[Waldeslied]] aus geführt. Eine beträchtliche Anzahl von [[Schildwache]]n der [[Silberschwingen]] hatte sich auch im '''Hain der Silberschwingen''', in der Nähe der Grenze zum [[Brachland]], postiert, wo sich sich der Eingang zur [[Kriegshymnenschlucht]] befand. [[Schildwache Weltensang]] war hier für die Bemühungen der Nachtelfen gegen die, die ihr Land zerstören wollten, verantwortlich. Doch es schien, als wären ihre schlimmsten Befürchtungen wahr geworden. Mit jedem Fortschritt, den die Silberschwingen machten, schien die Horde nur umso entschlossener, so viel Schaden wie möglich anzurichten. Die Nachtelfen konnten es sich nicht leisten, klein beizugeben. Das Schicksal des Landes ihrer Vorfahren lag im Gleichgewicht der Natur. Wenn sie nur mehr Kämpfer an der Front der [[Kriegshymnenschlucht]] hätten, könnten sie sicher triumphieren. \r\n==Personen==\r\n* [[Illiyana Mondflamm]] <Versorgungsoffizier der Silberschwingen>\r\n* [[Schildwache Weltensang]]",},
			["Hain der Uralten"] = { content = "Der Hain der Uralten in [[Dunkelküste]] liegt südlich von [[Auberdine]], im Schatten der Berge. Onu, der Orakelbaum, ein [[Urtum der Lehren]], bewacht diesen Hain.",},
			["Hakkari"] = { content = "#REDIRECT [[Trolle der Hakkari]]", redirect = "Trolle der Hakkari",},
			["Hakkar der Hundemeister"] = { content = "''((Nicht zu verwechseln mit [[Hakkar]], dem Seelenschinder!))''\r\nAls einer der ersten Leutnants der Brennenden Legion während der Zeit des Krieges der Uralten, war Hakkar das erste Mitglied der [[Brennende Legion|Brennenden Legion]], das seinen Fuß auf [[Azeroth]] setzte. Er wurde durch das Portal, welches aus dem [[Brunnen der Ewigkeit]] erschaffen war, geschickt, um [[Xavius]] zu unterstützen, das Portal zu stärken und es für den Rest der Brennenden Legion vorzubereiten. Hakkars erste Waffe war eine Peitsche, die neben der herkömmlichen Benutzung, einen scheinbar grenzenlosen Nachschub von [[Teufelshund]]en beschwören konnte, die Hakkars Befehlen folgten. Hakkar versuchte [[Krasus]] und [[Malfurion]] aus dem Widerstand zu entfernen, aber das schnelle Eingreifen der [[Schwestern von Elune]] rettete das unberechenbare Paar. Hakkar verletzte die Hohepriesterin von Suramar schwer und wollte [[Tyrande]] ermorden, als ein begabter [[Malfurion]] Sturmgrimm einschritt, um zu verhindern dass seine Liebe zerstört wurde und ein grimmiges Gewitter herbei rief, um den Hundemeister zu bezwingen. In der ursprünglichen Zeitlinie überlebte Hakkar den [[Krieg der Uralten]] und wurde erst während des Dritten Krieges getötet, aber das Eingreifen der [[Alte Götter|Alten Götter]], [[Nozdormu]] und Krasus führte zu seinem Ableben in den Händen von [[Malfurion]] Sturmgrimm. \r\n''((Die Zeitlinie wo er tot ist, ist offiziell und korrekt, da Hakkar der Hundemeister in WarCraft III nicht erscheint.))''",},
			["Halaa"] = { content = "'''Halaa''' war die erste Forschungseinrichtung für die Untersuchung von [[Naaru]]kristallen. Sie haben eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, [[Oshu'gun]], gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von [[Oshu'gun]] enthalten. Wenn man während der Abenteuer in diesem Gebiet Kristallpulver findet, bringt es zu [[Forschungsleiter Kartos]] oder [[Forschungsleiterin Amereldine]], und er wird ein Zeichen seiner Wertschätzung geben, dass man bei den Rüstmeistern eintauschen kann.",},
			["Halaanibecken"] = { content = "Es gibt Berichte über eine große Ansammlung von '''[[Oger der Felsfäuste|Felsfäuste]]n''' in den zwei Zwillingsschluchten: Nordwind und Südwind. Die Schocktruppen der [[Oger der Felsfäuste]] benutzen die Schluchten, um ihre Ogerhorte zu verstecken. Auch die [[Oger der Totschläger]] haben die Vorräte, die sie aus dem Dorf der [[Mag'har]] gestohlen haben, hierher gebracht. Die [[Oger]] hier tragen Kriegsperlen aus Obsidian, ein Gestein, das in vielen anderen Welten sehr wertvoll ist. \r\nIm Halaanibecken befinden sich auch die am schwersten von der Verderbnis betroffenen '''[[Wasserelementare]]'''. Während einige der verzweifelten [[Elementare]] ohne Folgen für die Umwelt zerstört werden können, müssen die Überreste der Schlammkreaturen nach ihrer Zerstörung entfernt werden. Die Schlammkreaturen hinterlassen verseuchte Leichenteile, die der Umwelt schaden können, wenn man sie liegen lässt.\r\nAuch wenn man '''Corki''' bereits aus den Ruinen der Brennenden Klinge gerettet hat, so hat ihn doch seine Neugier wieder gepackt. Er sagte, er wolle die Felsfaustbedrohung für \"Onkel\" Mo'mor untersuchen, und ist zu den Ogerhügeln im Halaanibecken gerannt. Wenn man ihm hier raushilft, wird sein Vater einen fürstlich entlohnen.",},
			["Halazzi"] = { content = "'''Halazzi''' ist ein Boss in Zul'Aman und verkörpert den \"Avatar des Luchses\", der von seinen Fähigkeiten einem [[Schamanen]] ähnelt. \r\n==Fähigkeiten==\r\nHalazzi wechselt während des Kampfes öfters zwischen seiner normalen Kampfform (Phase 1)und seiner Schamanenform (Phase 2). Während in Phase 1 vor allem sein Säbelhieb gefährlich ist, beschwört er in Phase 2 u.a. zusätzlich einen Luchs, der an seiner Seite kämpft, und kann ein \"Verdorbenes Totem des Blitzes\" aufstellen, das einen mächtigen Kettenblitz verursacht. Als Schamane kann er auch noch einen Flammenschock sowie einen Erdschock wirken, der einen zufällig gewählten Gegner trifft. Halazzis Schamanenform endet wenn sein Luchs stirbt.",},
			["Halbdämon"] = { content = "Ein Halbdämon ist ein Wesen, dass nicht als Dämon geboren, sondern durch die Sättigung mit [[Teufelsenergie]] erst dazu gemacht wurde. Ganze Völker können erst zu Halbdämonen werden, ehe sie als vollwertige Dämonen gelten.[[Kil'jaeden]], der listigere der großen Eredarfürsten, war ein Meister darin , andere Wesen in [[Dämonen]] zu verwandeln. Er sättigte sie dermaßen mit [[Teufelsenergie]] , das sie nicht einmal mehr zu Halbdämonen wurden. Solche Wesen werden häufig ausgegrenzt, da sie von verderbten Kräften besudelt wurden und auch keine allzu willigen Diener der Legion sind. Doch sucht der in ihnen wohnende,dämonische Hass häufig Ventile, so dass Halbdämonen häufig sehr gewalttätig werden. Der berühmteste ( und im Moment einzigste) Halbdämon, der bekannt ist,trägt den Namen [[Illidan]], das halbdämonische Volk auf [[Azeroth]] sind die [[Satyr]]n.",},
			["Halbelf"] = { content = "#REDIRECT [[Halbelfen]]", redirect = "Halbelfen",},
			["Halbelfen"] = { content = "'''Halbelfen''' entstehen aus der Vermischung von [[Elfen]] (meistens [[Hochelfen]], es ist noch kein anderer Fall bekannt geworden) und [[Menschen]], wobei die Mutter häufig elfisch ist. Es gibt nur wenige Halbelfen und die meisten werden misstrauisch beäugt: Die Elfen sehen in ihnen eine Art Missgeburt, die Menschen fürchten sie als ihnen überlegen. Deswegen ziehen Halbelfen oft einsam durch die Natur und sind allen Völkern neutral, selbst denen der [[Horde]].\r\nEinige Halbelfen sind sogar magiebegabt und die meisten wurden mächtige [[Magier]].\r\nEs gibt nur einen einzigen namentlich bekannten Halbelfen: [[Arator der Erlöser]], der Sohn von [[Turalyon]] und [[Alleria]]. Zudem gibt es die Zwillinge von [[Rhonin]] und [[Vereesa Windläufer]], deren Namen jedoch nicht bekannt sind. Auch der Drache [[Kalecgos]] nahm oft die Gestalt eines Halbelfen an.",},
			["Halbgott"] = { content = "Halbgötter\r\nZu den Artikeln dieser KategorieDie Halbgötter Azeroths gebieten über große Macht und haben gelegentlich eine bedeutende Rolle in der Geschichte [[Azeroths]] gespielt. Doch im Gegensatz zu [[Göttern]] wurden die meisten Halbgötter nie angebetet. Niemand baute ihnen zu Ehren Tempel, es gab nur sehr wenige [[Priester]], die den Halbgöttern ihr Leben widmeten. Trotzdem hat man sie früher verehrt, und einige von ihnen werden noch heute respektiert.\r\nTeils Gott, teils Sterblicher\r\nDie Halbgötter in Warcraft sind unsterblich, aber sie sind nicht allwissend, allmächtig oder allgegenwärtig. Sonst hätten sie ja etwa sofort von der ersten Invasion der [[Brennenden Legion]] gewusst und hätten sie mit Leichtigkeit zurückschlagen können.\r\nLeider steht es auch außer Frage, dass man einen Halbgott umbringen kann. Mehrere Halbgötter wurden im [[[[Krieg]] der Urtume]] getötet; sie fielen unter dem Ansturm der dämonischen Legionen. Eine andere Tragödie ereignete sich in jüngerer Zeit, als [[Cenarius]] während des [[Dritten Krieges]] von Sterblichen unter der Einwirkung des dämonischen Blutes getötet wurde, nämlich einer Gruppe [[Orcs]] unter ihrem Anführer [[Grom Höllschrei]].\r\nBekannte Halbgötter\r\n[[Cenarius]]\r\n[[Aviana]]\r\n[[Aggamaggan]]\r\n[[Al'ar]][[Omen]]\r\nQuelle:wow-europe.encyclopedia",},
			["Halduron Wolkenglanz"] = { content = "'''Halduron Wolkenglanz''' (engl. Halduron Brightwing) befindet sich im [[Sonnenzornturm]] in [[Silbermond]] und hat die Position des Waldläufergenerals inne. Er befehligt dadurch die militärischen Streitkräfte der [[Blutelfen]] auf [[Azeroth]]. \r\n==Geschichte==\r\nEr begann seine Karriere als Mitglied des Waldläuferkorps von Silbermond noch zu Zeiten der [[Hochelfen]], als die [[Weltenwanderer]] noch [[Sylvanas Windläufer]] unterstanden vor dem Dritten Krieg. Er kämpfte im [[Zweiten Krieg]] gegen die [[Horde]] und nahm [[Zul'jin]] gefangen. Nach ihrem Tod übernahm kurzzeitig [[Lor'themar Theron]] das Kommando, bevor es an Halduron weitergereicht wurde. Zur gleichen Zeit als Halduron die Weltenwanderer übernahm, wurde [[Lor'themar Theron]] zum Lordregenten von [[Quel'Thalas]] ernannt. Gemeinsam mit Lor'themar war er aktiv an der Verteidigung gegen die [[Geißel]] sowie am Wiederaufbau Silbermonds beteiligt. Zudem weiß er über [[Anveena]]s wahre Identität Bescheid. \r\n'''Quelle:'''",},
			["Halgrind"] = { content = "[[Halgrind]] ist ein Vrykuldorf im Westen des [[Der heulende Fjord|Heulenden Fjords]]. Als die Verlassenen von der [[Königliche Apothekervereinigung|Königlichen Apothekervereinigung]] die Stadt einnahmen, flüchtete ihr Anführer Thorvald aus der Stadt. Doch der Fakt, dass er ein Patriarch des Drachenschinderklans ist, macht sein Blut ideal für die Zwecke der Verlassenen.",},
			["Halle der Felsfäuste"] = { content = "Die Halle der Felsfäuste ist ein Unterschlupf der [[Oger der Felsfäuste]] und liegt südlich von [[Hammerfall]] und östlich vom [[Thandolübergang]] im [[Arathihochland]]. Ihr Anführer [[Kor'gresh]] ist im Besitz von Trelanes Zauberstab der Herbeirufung. So wie er seinen Leuten die Hölle heiß gemacht hat, damit sie nicht aus der Reihe tanzen, muss er wohl kurz davor sein herauszufinden, wie man die gesamte Macht des Stabes nutzen kann.",},
			["Halle der Toten"] = { content = "Die '''Halle der Toten''' ist ein Gebäude der [[Geißel]], welches aus einer [[Nekropole]] entsteht. Wenn die Präsenz der [[Untote]]n in der Welt der Lebenden stärker wird, sind weitere Modifikationen der Befehlszentrale erforderlich. Wird eine Nekropole zur Halle der Toten ausgebaut, so gibt das der Geißel die Macht, mehr alte Gebäude zu rufen und deren grausame Effizienz zu steigern. Bei weiteren Fortschritten können die Hallen der Toten zu einer [[Schwarze Zitadelle|Schwarzen Zitadelle]] ausgebaut werden.\r\n'''Quelle:''' [[Warcraft III - Reign of Chaos]].",},
			["Halycon"] = { content = "'''Halycon''' ist die gewaltige Höhlenmutter der [[Worgs]] in der [[Untere Schwarzfelsspitze|Unteren Schwarzfelsspitze]]. Sie ist die Rudelführerin der Worgs der [[Blutaxtlegion]] und Partnerin von [[Gizrul der Geifernde|Gizrul dem Geifernden]], der nach ihrem Tod erscheint. Diese Hündin ist verderbt und ein Produkt dunkler Magie.",},
			["Hammerfall"] = { content = "'''Hammerfall''' ist der Außenposten der [[Horde]] im [[Arathihochland]]. Es ist ein ehemaliges Internierungslager, doch Dank des Kriegshäuptlings verbleibt selbst in den Ruinen des alten Gefängnisses der Orcs noch Hoffnung und die Horde erhebt sich erneut. aber der Posten wird ständig von [[Oger]]n angegriffen und wenn man der Besatzung nicht bald Hilfe schickt, steht ihr Ableben unmittelbar bevor.\r\n==Personen==\r\n* '''Doktor Gregory Victor''' - Doktor Gregory Victor ist Erste-Hilfe-Lehrer und Chefarzt der Traumachirurgen der [[Horde]].\r\n* '''Drum Teufel''' - Drum Teufel kümmert sich um die Sicherheit und jagt die [[Trolle der Bleichborken]] sowie die [[Oger der Felsfäuste]]. \r\n* '''[[Gor'mul]]'''\r\n* '''Korin Teufel''' - Korin Teufel ist die Frau von Drum Teufel und will, dass man den [[Oger]] [[Or'Kalar]] erschlägt und ihr seinen Kopf bringt.\r\n* '''Tor'gan''' - Tor'gan ist ein [[Troll Schamane]] und arbeitet an einem Mittel, um [[Gor'mul]] neue Hoffnung zu geben. Er hofft, eine kleine Demonstration der neu gefundenen Schamanen-Magie könnte Gor'mul neuen Mut machen. Mit ein paar weiteren Dingen möchte er einen Gegenstand schaffen, der [[Gor'mul]] mit der Magie der Arglist des Raptors erfüllt. Wenn ihn die Macht des Raptors durchströmt, wird [[Gor'mul]] die neue Macht erkennen und den [[Krieger]] neu entdecken, der in ihm schlummert, so hofft Tor'gan. Sobald er wieder normal ist, können sie ihn dann über die aktuelle Situation der [[Horde]] informieren und sie werden einen großen [[Krieger]] bei den unaufhörlichen Kämpfen an der Seite haben. \r\n* '''Zaruk''' - Zaruk gehörte dem [[Schattenhammer Kult]] an und weiß, wie [[Myzrael]] beschworen werden kann. Man muss die von [[Theldurin der Verirrte|Theldurin dem Verirrten]] gestohlene Rolle finden, denn nur so kann man die Fürstin [[Myzrael]] zurückbringen.\r\n* '''Zengu''' - Zengu ist einer der erfahrenen [[Jäger]] und wurde nach Hammerfall entsandt, um die Beschaffung des legendären Schwertes [[Trol'kalar]] zu leiten.",},
			["Hammerzehs Grabungsstätte"] = { content = "Die [[Dunkeleisenzwerge]] vom [[Zwerge der Schattenschmiede|Schattenschmiedeklan]] haben Hammerzehs Grabungsstätte im [[Ödland]] angegriffen. Sie haben fast alle dort umgebracht, darunter auch Boss Hammerzeh. Die [[Zwerge]] hatten es so eilig, die Ausgrabungsstätte von [[Uldaman]] zu verlassen, dass sie sich gezwungen sahen, unterwegs viele Wagen und Nachschubkisten zurückzulassen. Es wird ganz schön haarig werden, wenn es ihnen nicht gelingt, Material aufzutreiben, um ein paar Verteidigungslinien und andere Notwendigkeiten zu konstruieren. Die Ausgrabungsleiter der [[Forscherliga]] machen sich langsam Sorgen um die Lage in dem kleinen Lager.\r\n==Personen==\r\n* [[Hammerzeh Grez]]'''\r\n'''Sonstige'''\r\n* '''Ausgrabungsleiter Agmond''' hielt sich in der südlichsten Grabungsstätte im [[Ödland]] auf, einer winzigen Unternehmung hinter der [[Festung Angor]]. Er hatte die Verantwortung über die Ausgrabungsstätten im [[Ödland]] und seine Spuren führen nach dem Überfall der [[Dunkeleisenzwerge]] nach Westen. Anhand der Blutspuren auf den Felsen und im Sand ist unschwer zu erraten, dass sich der verletzte Zwerg ein ganzes Stück weit geschleppt haben muss. Bei näherer Betrachtung ist das Wort \"[[Murdaloc]]\" erkennbar, das grob aus Sandsteinen des [[Ödland]]s zusammengestückelt wurde, ... direkt neben Agmonds toter Hand. \r\n* '''Ausgrabungsleiter Roggendol''' in Hammerzehs Grabungsstätte sucht seine Glückshacke. Er ist gerade noch lebendig weggekommen und versucht nun, sich einen Plan auszudenken, wie sie einen Teil ihrer Vorräte zurückbekommen könnten.\r\n* '''Sigrun Eisenhieb''' ist der Lehrling von Feranor Steeltoe. Er hat eine Spezialtechnik erlernt, wie man mithilfe des Blutes eines noch schlagenden Herzens eines seltenen Schwarzdrachenwelpen feurige Verzauberungen auf Waffen wirkt.",},
			["Hammerzeh Grez"] = { content = "Der Zwerg '''Hammerzeh Grez''' suchte in [[Hammerzehs Grabungsstätte]] nahe [[Uldaman]] im [[Ödland]] nach den Wurzeln seines Volkes und es war seine Aufgabe, den [[Zwerge der Schattenschmiede|Schattenschmiedeklan]] aufzuhalten. \r\nHammerzeh Grez und [[Historiker Karnik]] in [[Eisenschmiede]] haben zusammengearbeitet, um in Uldaman nach den verschollenen Artefakten zu suchen, doch die Zwerge der Schattenschmiede haben herausgefunden, dass die beiden mehr wussten, als sie sagten. Wenn diese dreckigen [[Zwerge der Schattenschmiede]] ihn als Geisel genommen haben, um herauszubekommen, was er über die Titanenausgrabungen weiß, könnte ganz Eisenschmiede in großer Gefahr sein, denn seit langer Zeit schon trachten die [[Dunkeleisenzwerge]] nach Magie, um noch mächtigere [[Golems]] zu erschaffen. Hammerzeh hatte dasselbe vor, aber natürlich nur, um sie aufzuhalten. Er träumte davon, die [[Schrifttafel des Willens]] zu finden.",},
			["Hamuul Runentotem"] = { content = "#REDIRECT [[Erzdruide Hamuul Runentotem]]", redirect = "Erzdruide Hamuul Runentotem",},
			["Hana'zua"] = { content = "'''Hana´zua''' ist ein [[Troll Jäger]] von den Dunkelspeertrollen und lebt im [[Tal der Prüfungen]] in [[Durotar]]. Vor nicht allzu langer Zeit wurde er auf der Jagd nach den [[Skorpid]]en des Tals von einem besonders heimtückischen Exemplar namens [[Sarkoth]] vergiftet. Hana’zua stürzte sich auf ihn und konnte einer seiner Klauen einen ordentlichen Draufschlag versetzen, bevor sie sich um sein Bein schloss. Er hatte jedoch nicht mit seinem Stecher gerechnet, den Sarkoth tief in seine Brust trieb, mit dem er sein Fleisch zerschnitt und ihm einen großen Blutverlust verursachte. Er lag deshalb bis vor kurzem unter einem Baum, ganz in der Nähe von Sarkoths jetztigem Standort. Doch bald fand man ihn, denn ohne Hilfe hätte er den Weg zurück zum Höhlenbau nicht geschafft und gerade erst heilte man ihn mit [[Gornek]]s Hilfe. Es heißt, er soll wieder ausgezogen sein, um Sarkoth endlich zu töten, denn seine Ehre darf nicht besudelt werden. Hoffentlich wird er nicht wieder vergiftet...",},
			["Handelsdistrikt"] = { content = "Der geschäftige '''Handelsdistrikt''' ist ein Stadtviertel von ''[[Sturmwind]]''. Hier bieten Händler ihre Waren vom ganzen Kontinent und darüber hinaus, während Kämpfer jeder Couleur die Straßen der Altstadt durchwandeln. \r\n==Wissenswertes==\r\nIm Handelsdistrikt von Sturmwind findet man u.a. das Zählhaus in der Nähe der vorderen Tore. Und wer keine Lust mehr hat, sein Geld zu zählen, der sollte in der Taverne \"[[Zur güldenen Rose]]\" vorbeischauen und sich einen Schluck genehmigen. In \"Pestles Apotheke\" dagegen findet man sicherlich den einen oder anderen Trank oder sonst irgendetwas, dass einem Abenteurer von Nutzen ist. \r\n===Heldenaufruf===\r\nInmitten des Handelsdistrikts steht deutlich sichtbar der '''Heldenaufruf''', eine Sammlung von Verlautbarungen des Königs von Sturmwind, die Abenteurern Orte weisen, an denen sie ihre Talente zum allgemeinen Nutzen der Allianz einsetzen können. \r\n===Der mörderische Barbier===\r\nDie Kunden des Barbiers im Handelsdistrikt kommen und gehen, und halten höchstens für einen Blick in den Spiegel kurz inne. Über den fröhlichen Jelinek Scharfschur denken sie gar nicht weiter nach. Doch habt ihr euch schon einmal angesehen, was hinter der freundlichen und gemütlichen Fassade liegt? Habt ihr euch die Treppe am hinteren Ende des Raums hinaufgewagt? Wer dem Obergeschoss auch nur einen kurzen Besuch abstattet, stelt alles infrage. Ein Blick in das hintere Schlafzimmer, und ihr werdet euch fragen, ob das Rasiermesser auf dem Tisch wohl etwas mit den Überresten unter der Holzdiele zu tun hat. \r\nVor der Tür erwartet Euch Besitzerin [[Genevieve]], die Euch mit freundlichen Worten zum Eintritt auffordert. Drinnen erwartet Euch [[Jelinek Scharfschur]], der Euch Services rund um die heldenhafte Haarpracht, und sogar das Polieren der draeneischen Hörner und Tentakel verspricht. Doch seid auf der Hut, wenn Ihr Euch auf dem Barbiersessel niederlasst, denn so mancher Kunde hat seinen neuen Haarschnitt mit dem Leben bezahlt. \r\nWie wir darauf kommen? Steigt einmal die Treppe hinauf in den ersten Stock. Zwischen Bett und Tisch im Schlafzimmer seht Ihr einige lose Bretter, unter denen die Skelette von Gnomen liegen! Eine astreine Anspielung auf die Romanfigur Sweeney Todd, den teuflischen Barbier aus der Fleet Street. \r\n===Persönlichkeiten===\r\n* ''[[Bernard Gump]]'' - Blumenladen, Bernard ist Florist und verkauft in Sturmwind verschiedene Blumen und Blumensträusse. Sein Laden liegt in den Kanälen am östlichen Rand des Handelsdistrikts. \r\n* ''[[Erunak Steinsprecher]]'' - [[Der Irdene Ring]], Erunak kam zu Beginn der \"[[Cataclysm Pre-Event: Untergangsverkündungen in Sturmwind|Untergangsverkündungen in Sturmwind]]\" hierher, um sich um die [[Cataclysm Pre-Event/Elemente im Aufruhr|elementaren Störungen]] zu kümmern.\r\n* ''[[Justine Demalier‎‎]]'' - Anwerberin von Sturmwind, Justine Demalier bewacht gemeinsam mit [[Melris Malagan]] den großen Platz im Handelsdistrikt.\r\n* ''[[Leutnant Jocryn Heldric]]'' - [[Liebe liegt in der Luft|Herzklopfenfest]] \r\n* ''[[Melris Malagan]]'' - Hauptmann der Wache, Melris Malagan bewacht gemeinsam mit [[Justine Demalier]] den großen Platz im Handelsdistrikt.\r\n* ''[[Topper McNabb]]'' - Bettler, Topper verdient seinen Lebensunterhalt als Bettler im Handelsviertel. Während des letzten Krieges baute die Armee von Sturmwind einen Wachturm direkt hinter seine Farm, woraufhin diese von der Horde überrannt wurde. Die Orcs brannten seinen Hof bis auf die Grundmauern nieder. Nichts blieb ihm.\r\n===Handwerker, Händler und Lehrer===",},
			["Handwerksverzeichnis der Allianz"] = { content = "== Alchimisten==\r\nSiehe auch: [[Alchimist]] und [[Alchimist: Rezepte]]\r\n* '''Andere:''' [[Anthrazides]], , [[Typhix Baumkrone]], [[Maristara]], [[Rubinora Eljabar]], [[Lenard McCoy]]\r\n* '''Meister der Elixiere:''' [[Trine Trulla Trantüte]], [[Slyser]]\r\n* '''Meister der Tränke:''' \r\n* '''Meister der Transmutation:''' [[Dirilim]]\r\n==Bergbauer==\r\n* [[Borondil Wolfsaxt]], [[Grumbert Grollhammer]], [[Mickie_Mux|Mickie]], [[Ragnar Sturmfels]], [[Schnack]], [[Shandalie]], [[Unwucht]], [[Vedek]], [[Wulfgard Johanson]]\r\n==Ingenieure==\r\nSiehe auch: [[Ingenieur]] und [[Ingenieur: Rezepte]]\r\n* '''Andere:''' [[Borondil Wolfsaxt]], [[Grumbert Grollhammer]], [[Ketan]], [[Mickie_Mux|Mickie]], [[Schnack]], [[Unwucht]] \r\n* '''Gnomeningenieur:''' [[Aurium]], [[Gozer]], [[Hildegard|Hildegard Sprigglespruxx]], [[Lharos]], \r\n* '''Gobliningenieur:''' [[Grokhnaar Grimmklinge]]\r\n==Inschriftenkunde==\r\nSiehe auch: [[Inschriftenkunde]] und [[Inschriftenkunde: Rezepte]]\r\n* [[Gnixi]], [[Smirke]]\r\n==Juweliere==\r\nSiehe auch: [[Juwelenschleifer]] und [[Juwelenschleifer: Rezepte]]\r\n* [[Brendolos]], [[Elain]], [[Mitzy]], [[Shandalie]], [[Vedek]], \r\n==Kürschner==\r\n* [[Gibin]], [[Wulfgard Johanson]]\r\n==Kräutersammler==\r\n* [[Anthrazides]], [[Lenard McCoy]], [[Rubinora Eljabar]], [[Slyser]], [[Smirke]], [[Typhix Baumkrone]], [[Trine Trulla Trantüte]], \r\n==Lederverarbeiter==\r\nSiehe auch: [[Lederer]] und [[Lederer: Rezepte]]\r\n* '''Drachenlederer:''' \r\n* '''Elementarleder:''' [[Gibin]] (); [[Jasmir]]\r\n* '''Stammeslederer:''' \r\n* '''Ohne Spezialisierung:''' [[Marieth]]; [[Hildegard]]; [[Iluwen]]\r\n==Schlüsseldienst==\r\n* [[Gibin]]\r\n==Schmiede==\r\nSiehe auch: [[Schmied]] und [[Schmied: Rezepte]]\r\n* '''Axtschmiedemeister:''' [[Marbririon]]\r\n* '''Hammerschmiedemeister:''' [[Lagto]]\r\n* '''Rüstschmiedemeister:''' [[Pünktchén]]\r\n* '''Schwertschmiedemeister:''' \r\n* '''Sonstige:''' [[Ragnar Sturmfels]]\r\n==Schneider==\r\nSiehe auch: [[Schneider: Rezepte]]\r\n* '''Andere:''' [[Algadar Hetius]], [[Fermion]], [[Helba]], [[Ketan]], [[Larah Saldean]], [[Mireth]], [[Noviet]], [[Vlün Vladimir Flammenherz]] \r\n* '''Schattenstoffschneider:''' \r\n* '''Urmondstoffschneider:''' [[Eldirith]]\r\n* '''Zauberfeuerstoffschneider:''' [[Maigan]], Taliath\r\n==Verzauberer==\r\nSiehe auch: [[Verzauberer]] und [[Verzauberer: Rezepte]]\r\n* [[Algadar Hetius]], [[Asraela]], [[Eldirith]], [[Fennival]], [[Fermion]], [[Gozer]], [[Lanar]], [[Lharos]], [[Maigan]], [[Mireth]], [[Noviet]], [[Seranna]], [[Thaliath]],",},
			["Handwerksverzeichnis der Horde"] = { content = "== Alchimisten==\r\nSiehe auch: [[Alchimist]] und [[Alchimist: Rezepte]]\r\n* '''Andere:''' [[Kylane]], [[Takhpah]], [[Zuul]]\r\n* '''Meister der Elixiere:''' Abygail, , , Pyrocks, , Sorék \r\n* '''Meister der Tränke:''' Abraxys, Motaro, [[Nejasha]], [[Palinor]], [[Raislin]]\r\n* '''Meister der Transmutation:''' Cailik, , , Sturmweiser, Lyekka\r\n==Bergbauer==\r\n* [[Ekkaias]], [[Kalburon]], [[Khurn]], [[Teklahktran]], Darkmorning, Leroux, Rabbdoa, Linhir, Thoc, Shannon, Dolanaar, Solána, Gorefangh, Nagha, Thyron, Llananrion, Arakénayha, Kurtalos, Dolanai, Sherena \r\n==Ingenieure==\r\nSiehe auch: [[Ingenieur]] und [[Ingenieur: Rezepte]]\r\n* '''Andere:''' Dolanai, Kuscharo, [[Teklahktran]]\r\n* '''Gnomeningenieur:''' Cailix, Dolanaar, \r\n* '''Gobliningenieur:''' [[Jabscha]], [[Khurn]], [[Nejasha]], Shosa, Sherena \r\n==Inschriftenkunde==\r\nSiehe auch: [[Inschriftenkunde]] und [[Inschriftenkunde: Rezepte]] \r\n* Drunner\r\n==Juweliere==\r\nSiehe auch: [[Juwelenschleifer]] und [[Juwelenschleifer: Rezepte]]\r\n* [[Alynn]], Cailiz, Darkmorning, , , [[Jabscha]], [[Malanor]], Mama [[Jippa]], Pogun, [[Rhîw]], [[Rogarr]] Schattenaug, Solána, [[Torban]], Zarach,Chekani\r\n==Kürschner==\r\n* Bullrin, [[Calenhil]], [[Durathror]], Gorthag, [[Mokkda]], [[Migrim]], [[Quenzhal]], Rabbdoa, [[Randijin]], Sedjuhnak, [[Tamin]], \r\n==Kräutersammler==\r\n* Abraxys, [[Bacco]], Emilyeliza, Grashakk, [[Kylane]], Llananrion, Pyrocks, Raziella, [[Selca]], Sorék, [[Takhpah]], [[Urdolh]], [[Zuul]],Sunnivah\r\n==Lederverarbeiter==\r\nSiehe auch: [[Lederer]] und [[Lederer: Rezepte]]\r\n* '''Drachenlederer:''' Cailin, , [[Calenhil]], , , Hyrrockin, [[Jinoh]], , \r\n* '''Elementarleder:''' , , [[Migrim]], \r\n* '''Stammeslederer:''' [[Kataner]], Kelkara, Kuscharo\r\n* '''Ohne Spezialisierung:''' [[Enuhal]], [[Mokkda]], [[Randijin]], [[Selca]], [[Shálimar]],\r\n==Schmiede==\r\nSiehe auch: [[Schmied]] und [[Schmied: Rezepte]]\r\n* '''Axtschmiedemeister:''' \r\n* '''Hammerschmiedemeister:''' \r\n* '''Rüstschmiedemeister:''' [[Ekkaias]], Kurtalos, , , Thoc, \r\n* '''Schwertschmiedemeister:''' Linhir, , \r\n* '''Sonstige:''' [[Morkh]], [[Rukthór]]\r\n==Schneider==\r\nSiehe auch: [[Schneider]] und [[Schneider: Rezepte]]\r\n* '''Andere:''' [[Alynn]]\r\n* '''Schattenzwirnschneider:''' , , [[Zadirah]], Môrgenroth\r\n* '''Urmondstoffschneider:''' [[Akinahos]], Arakénayha, Aygail, [[Bokan]], Cailis, Emilyeliza, Jilaja, Quanchi, , Riya, , \r\n* '''Zauberfeuerstoffschneider:''' , [[Bacco]], Riya, \r\n==Verzauberer==\r\nSiehe auch: [[Verzauberer]] und [[Verzauberer: Rezepte]]\r\n* [[Akinahos]], [[Azmakadesh]], [[Bokan]], [[Danforth]], , Hyrrockin, , , , [[Tamin]], , , [[Zadirah]]",},
			["Hand von Argus"] = { content = "Die '''Hand von Argus''' ist eine militärische Einheit der [[Draenei]] und kämpft an der Front der [[Blutmythosinsel]]. Ein Soldat der Hand von Argus ist vielerlei: gehorsam, mutig, intelligent und vor allem ehrenhaft. Man erstattet [[Exarch Admetius]] bei der [[Blutwacht]] Bericht, wenn man der Hand beitreten möchte. Er und seine Untergebenen werden einen weiter auf dem Weg zum [[Draenei]]soldaten ausbilden. Aber ehrenhafte Personen handeln nicht immer ehrenhaft. Manchmal ist es ihnen nicht möglich. Viele [[Draenei]] kennen oder erinnern sich nicht an den Heimatplaneten [[Argus]]. Dort trennten die [[Draenei]] sich von den [[Man'ari]]: ihren verdorbenen dämonischen Abbildern, die von [[Sargeras]] 'bedacht' wurden. Sie selbst nennen sich die [[Eredar]]. [[Eredar]] ... dieses Wort hatte einst eine Bedeutung.",},
			["Hand von Dagun"] = { content = "'''Die Hand von Dagun'''\r\nIn den alten Schriften heißt es, die Krallen von [[Dagun]] sonderten ein Gift ab, das die Beute nicht tötet, sondern sie in etwas anderes verwandelt - etwas, das zu den alten Völkern gehört. Der Wert der Hand für den [[Schattenhammerkult]] steht außer Frage. Dagun lebt draußen im offenen Meer, wird aber regelmäßig von den [[Murlocs der Schlammflossen]]stamms in den [[Düstermarschen]] an die Oberfläche getrieben. Ihre Orakel beschwören ihn mit verzaubertem Seetang. Wenn man genügend Orakel tötet, findet man auch den Tang. Diesen legt man dann auf den Altar der Murlocs und Dagun wird erscheinen. Die Hand von Dagun wird von [[Bewahrer Bel'dugur]] in [[Unterstadt]] und [[Gerrig Knochengriff]] in [[Eisenschmiede]] gesucht.",},
			["Hand von Gul'dan"] = { content = "Die '''Hand von Gul'dan''' liegt im Herzen des [[Schattenmondtal]]s. Es ist eine von Lavaseen durchzogene Gegend, auf der viele verderbte [[Feuerelementar]]e und [[Teufelsbestie]]n leben. [[Uvuros]], die Geißel des Schattenmondtals, mit seiner feurigen Mähne wurde hier zuletzt gesehen.",},
			["Hand von Iruxos"] = { content = "Die '''Hand von Iruxos''' ist ein dämonisches Artefakt, welches im [[Dämonenkasten]] verborgen liegt. Die Hand ist ein wirklich grausiger Anblick und wurde in der [[Festung Donneraxt]] in [[Desolace]] aufbewahrt. Die Anhänger der [[Brennende Klinge|Brennenden Klinge]] verwenden sie nun, um dämonische Portale beim [[Zirkel der Mannoroc]] zu öffnen.",},
			["Haquu"] = { content = "'''Interpretationsquelle:''' [[Anduri Stamm]] \r\n'''Ideale:''' Kunst, Tanz, Musik, Balz, Feiern, Handel \r\nHaquu ist der Gott der Künste, sowohl der handwerklichen als auch des Tanzes und des Gesangs. Die Froschgesänge, die in manchen Nächten erklingen, gaben Anlaß, Haquu als musikliebenden Gott zu verehren. Haquu liebt Gelage mit Rankenwein und Tanz. Es ist üblich nach dem Anstoßen einen Schluck Wein für Haquu auf den Boden zu gießen bevor man selbst trinkt. \r\nEr ist jedoch nicht nur Patron aller Künstler sondern steht auch für das Werben um Weibchen. Ein Trollmännchen könnte zu ihm beten, wenn es um die Gunst eines Weibchens werben will. Vielleicht gibt er ihm dann eine Inspiration, um das Weibchen mit einem besonders schönen Kunstwerk zu beeindrucken (sei es eine Holzmaske oder ein Lied etc.), oder auch Kraft, um einen Rivalen auszustechen. \r\nJedoch ist Haquu kein Kämpfer, sein Weg ist eher Listenreichtum, Schläue und Kreativität. \r\nEbenfalls wird er oft mit dem Handel in Verbindung gebracht. Es soll fahrende Haquu-Priester geben, die Handel betreiben und stets von ihrem Gott begünstigt Profite herausschlagen, jedoch müssen sie ihm dafür auch einen Teil des Gewinns als Opfergabe darbringen. Haquu-Priester sind harte Verhandlungspartner, das Feilschen ist ihnen sozusagen gottgegeben. Sie haben aber die Fähigkeit, ihren Käufer stets glauben zu lassen, er habe ein gutes Geschäft gemacht.",},
			["Harbringer"] = { content = "Die \"'''Harbringer'''\" ist eines der Schiffe der [[Goblins]] der [[Schwarzmeerräuber]], die unter dem Kommando von [[Kapitän O'Breen]] zur [[Faldirbucht]] im [[Arathihochland]] segelten, um einen einen verlorenen Elfenschatz zu heben. Doch während die \"Harbringer\" noch sicher andocken konnte, sanken die \"[[Tolle Minna]]\" und die \"[[Silbergeist]]\" auf den Grund des Meeres.",},
			["Harpyie"] = { content = "#REDIRECT [[Harpyien]]", redirect = "Harpyien",},
			["Harpyien"] = { content = "Von '''Harpyien''' wird sich erzählt, dass sie die verfluchten Verräter der hochgeborenen [[Königin Azshara]] sein. Die bösartigen geflügelten Frauen nehmen Männer gefangen, um mit ihnen Nachkommen zu zeugen und sie anschließend an ihre geschlüpften Jungen zu verfüttern. Einst gaben sie sich damit zufrieden, in ihrer angestammten Heimat, dem stürmischen [[Steinkrallengebirge]], Übel und Elend zu verbreiten. Doch mittlerweile haben die Harpyien ihren Einfluss über den gesamten Kontinent [[Kalimdor]] ausgedehnt und verstehen es trefflich, arglose Karawanen und unbedachte Reisende in Hinterhalte zu locken. Die skrupellosen Frauen sind dazu übergegangen, jeden anzufallen, der es wagt, in ihr Territorium einzudringen. So sind ihre Nester, in denen die grausigen Überreste ihrer Opfer verstreut liegen, von den ausgetrockneten Tafelbergen von [[Durotar]] bis zu den üppigen Wäldern von [[Eschental]] kein seltener Anblick mehr. \r\n'''Quelle:''' \r\n==Klans == \r\n* [[Harpyien der Blutfedern]]\r\n* [[Harpyien der Blutfurien]]\r\n* [[Harpyien der Hexenschwingen]]\r\n* [[Harpyien der Nordschwingen]]\r\n* [[Harpyien der Staubschwingen]]\r\n* [[Harpyien der Wildfedern]]\r\n* [[Harpyien der Windfurien]]\r\n==Klassen==\r\n* [[Harpyien Töterin]] \r\n* [[Harpyien Wildfeder]] \r\n* [[Harpyien Windhexe]]\r\n* [[Harpyien Windruferin]]",},
			["Harpyien der Blutfedern"] = { content = "Harpyien der Blutfedern haben sich unter Führung von [[Furie Shelda]] auf [[Teldrassil]] bei der [[Lichtung des Orakels]] niedergelassen. Die [[Schildwache]]n der [[Nachtelfen]] versuchen den Orakelbaum vor den [[Harpyien]] zu beschützen, die überall im Tal Nester gebaut haben.",},
			["Harpyien der Blutfurien"] = { content = "==Harpyien der Blutfurien==\r\n* Heimat: [[Steinkrallengebirge]] / Verbranntes Tal\r\n* Anführerin: Zerfetzerin der Blutfurien. Man findet sie in den westlichen Hügeln. Sie wird nicht leicht zu bezwingen sein\r\nDie Blutfurien sind die Ursache für die zunehmende Zahl von Harpyien in [[Kalimdor]]. Sie bedrängen jede Lebensform und hindern Unschuldige daran, ihre Grenzen zu verlassen. Es genügt nicht, die Anzahl der Blutfurienharpyien zu verringern. Die einzig wahre Kur für ihre Krankheit wäre es, ihre Anführerin zu beseitigen, die Zerfetzerin der Blutfurien. Für diese dreckigen Kreaturen ist sie so etwas wie eine Königin. Tötet sie und ihre Zahl wird ganz gewiss abnehmen.",},
			["Harpyien der Hexenschwingen"] = { content = "==Harpyien der Hexenschwingen==\r\n* Heimat: [[Brachland]] - Trockene Hügel\r\n* Anführer: Serena Blutfeder\r\nDie Harpyien der Hexenschwingen haben die Karawanen vom Wegekreuz lange geplündert. Die Harpyien leben in einem Matriarchat und stammen nicht aus dem Brachland. Sie kommen aus einem Ort namens [[Steinkrallengebirge]], ganz weit nordwestlich von den Trockenen Hügeln.\r\n* Serena Blutfeder - Serena Blutfeder ist die Schwester einer Harpyie namens Blutfeder, die Rexxar vor einer ganzen Weile erschlug. Offensichtlich wurden die Karawanen der Horde angegriffen, um ihre Schwester zu rächen.\r\nNur Töter der Hexenschwingen können Offiziere werden und man erkennt sie an den Harpyienoffiziersringen, die sie tragen. Sie sind ein übler Haufen, aber sie führen ein paar der Unterlinge in diesem Gebiet an.",},
			["Harpyien der Nordschwingen"] = { content = "==Harpyien der Nordschwingen==\r\n* Heimat: [[Feralas]] / Ruinen von Rabenwind\r\n* Anführer: Edana Hasskralle\r\nEdana Hasskralle ist die Königin der Nordschwingen, die in den Ruinen von Rabenwind zu Hause sind. Sie ist das vollkommen Böse und hat ein Herz aus Kristall. Sie ist bar jeglicher Emotionen außer dem Hass, den sie für alle anderen fühlt. Die Harpyien tragen ein Horn - wenn es bei den Hasskrallensteinen, im nördlichen Teil der Ruinen, geblasen wird, wird die Königin beschworen.",},
			["Harpyien der Staubschwingen"] = { content = "==Harpyien der Staubschwingen==\r\n* Heimat: [[Durotar]] - Klingenschlucht / Staubwindenklamm",},
			["Harpyien der Wildfedern"] = { content = "==Harpyien der Wildfedern==\r\n* Heimat: [[Tausend Nadeln]] / Bau der Wildfedern\r\n* Anführer: Grenka Blutkreischer\r\nDer Bau der Wildfedern liegt westlich vom Freiwindposten. Wenn man ihre Nahrungsvorräte zerstört, sollte man deren Zorn angestachelt haben. Wenn man lange genug überlebt, wird Grenka Blutkreischer einen persönlich heimsuchen.",},
			["Harpyien der Windfurien"] = { content = "==Harpyien der Windfurien==\r\n* Heimat: Mulgore\r\nDie Harpyien der Windfurien im Südosten treiben sich an den Bergrändern fernab der Straße herum. Sie gehören mit zu den natürlichen Feinden der Tauren hier in Mulgore und sind gut geeignet, um die Fertigkeiten eines Jägers einzuschätzen.",},
			["Hase"] = { content = "'''Hasen''', das sind diese kleinen possierlichen Tierchen mit den langen Ohren die überall herum hoppeln. Wer gerne einen Hasen als Begleiter haben möchte muss ihn nicht selber fangen sondern kann ihn käuflich erwerben. Diese sind dann auch schon gezähmt und neigen nicht mehr zu Fluchtversuchen.\r\n===Arten und Händler===\r\n* '''Brauner Hase''' - Braune Hasen gibt es bei Händler [[Rashaad]] auf der [[Sturmsäule]] im [[Nethersturm]] für 10 Gold.\r\n* '''Schneehase''' - Schneehasen verkauft euch Yarlyn Bernruh auf dem [[Gehöft Bernruh]] in [[Dun Morogh]] für 20 Silber. \r\n* '''[[Wolpertinger]]''' - Der [[Wolpertinger]] scheint auch eine seltsame Hasenart zu sein doch das ist eine andere Geschichte.",},
			["Hassprankenzuflucht"] = { content = "Die '''Hassprankenzuflucht''' ist das Revier der Naga der Hasspranken auf der [[Blutmythosinsel]]. Diese Zuflucht liegt im Nordosten von [[Kessels Wegelager]], im Westen der [[Blutwacht]]. Sie ist auch der Sitz ihres Anführers, [[Lord Xiz]]. Die Naga sind auf der Insel für ihre Überfälle bekannt und haben es vor drei Nächten gewagt, im Schutze der Dunkelheit bis zu Kessels Wegelager vorzudringen.",},
			["Hass der Zentauren"] = { content = "-- ''(übernommen von den Schriftbannern im Zelt von [[Hamuul Runentotem]], oben auf der Anhöhre der Ältesten in [[Donnerfels]])'' --\r\nAls die [[Nebel der Dämmerung]] verflogen und das Zeitalter der Erinnerung voranschritt, zog der Halbgott [[Cenarius]] seiner eigenen Wege auf den Feldern der Welt. Die [[Shu'halo]] waren traurig, weil er fortging, und vergaßen viel von dem [[Druiden]]wissen, das er sie gelehrt hatte. Im Lauf der Generationen vergaßen sie auch die Sprache der Bäume und der wilden Kreaturen des Landes. Das dunkle Flüstern aus den Tiefen der Welt drang erneut an ihr Ohr.\r\nObwohl die Kinder der Erde nicht auf das böse Flüstern hörten, befiel ein schrecklicher Fluch die umherziehenden Stämme. Aus den schwarzen Landen im Westen kam eine [[Horde]] mörderischer Kreaturen - die [[Zentauren]]. Die [[Zentauren]], Kannibalen und Verheerer, fielen wie eine Seuche über die [[Shu'halo]] her. Die [[Krieger]]helden und die [[Jäger]] kämpften mit dem Segen der [[Erdenmutter]] in ihren Herzen, aber sie konnten die [[Zentauren]] nicht besiegen.\r\nDie [[Shu'halo]] waren gezwungen, das Land ihrer Vorfahren zu verlassen und von da an bis in alle Zeit als Nomaden durch die endlosen Ebenen zu ziehen. Mag sein, dass eines Tages die Hoffnung zurückkehrt - und dass die verstreuten Stämme der [[Shu'halo]] irgendwann eine neue Heimat in den liebenden Armen der [[Erdenmutter]] finden.",},
			["Hauptmann Krombruch"] = { content = "'''Hauptmann Krombruch''' ist ein [[Oger]] in [[Düsterbruch]] (Nord). Krombruch zufolge sagen die \"Geschichten aus Alter Zeit \", dass [[Prinz Tortheldrin|Tortheldrin]] - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- die Stulpen der Gordokmacht von einem der Gordokkönige gestohlen hat. Die Geschichten aus Alter Zeit sagen auch, nur der wahre König der Gordok sie zurückholen kann.",},
			["Hauptmann Tyralius"] = { content = "Hauptmann Tyralius vom [[Protektorat]] hat eine Truppe von Soldaten vor 10 Tagen in Richtung des [[Stützpunkt des Astraleum]] im [[Nethersturm]] geführt. Es ist sehr wahrscheinlich, dass sie überfallen und getötet wurden, doch wenn Tyralius noch am Leben ist, hält das Astraleum ihn sicher in einer ihrer Gefängniskugeln fest. \r\nTyralius hat schwere Wunden erlitten, aber die Mitglieder des [[Protektorat]]s denken, dass er es schaffen wird. Er hat ganze Felder voller Gefängnisse erwähnt, die so ähnlich sind wie das, aus dem man ihn errettet hat. Gefängnisse voller Kreaturen aus dem ganzen Universum. Das [[Konsortium]] hat schon angemeldet, dass sie planen, ein paar Teams dorthin zu schicken und das [[Protektorat]] arbeitet bereits an einer Technologie, mit der sie die Schlösser des [[Astraleum]]s aufbrechen können. Er konnte bisher herausfinden, dass sie nicht nur die Gefangenen katalogisieren, sondern auch Aussagen über ihre Aufenthaltsorte machen.",},
			["Hauptstadt"] = { content = "#Redirect[[:Kategorie:Hauptstadt]]", redirect = ":Kategorie:Hauptstadt",},
			["Haustier"] = { content = "#Redirect[[:Kategorie: Gefährte]]", redirect = ":Kategorie: Gefährte",},
			["Haus Barov"] = { content = "'''Haus Barov''' war eine alte Adelsfamilie aus [[Lordaeron]]. Zu ihren Besitztümern gehörten u.a. [[Brill]], [[Tarrens Mühle]], [[Süderstade]], [[Darrowehr]] bzw. [[Caer Darrow]] und die [[Scholomance]].\r\nEine gängige Methode, mit der [[Kel'Thuzad]] neue Anhänger für seinen [[Kult der Verdammten]] warb, war es, potentiellen Neuzugängen im Austausch gegen ihre Dienste für den [[Lichkönig]] die Unsterblichkeit zu versprechen. Die Barovs fielen auf [[Kel'Thuzad]]s charismatischen Schwindel herein und überließen die Burg und die dazugehörigen Krypten der [[Geißel]]. Im Gegenzug töteten die Kultisten die [[Barovs]] und machten aus den uralten Gewölben eine Schule der Nekromantie, die sie die [[Scholomance]] tauften. \r\n==Mitglieder==\r\n* [[Alexi Barov]]\r\n* [[Jandice Barov]]\r\n* [[Lady Illucia Barov]]\r\n* [[Lord Alexei Barov]]\r\n* [[Weldon Barov]]",},
			["Haus Wrynn"] = { content = "Die Mitglieder der menschlichen Dynastie des '''Hauses Wrynn''' stellten schon vor Beginn des [[Der Erste Krieg|Ersten Krieges]] die Könige [[Sturmwind]]s.\r\n==Mitglieder==\r\n* König [[Landen Wrynn]] \r\n* König [[Adamant Wrynn III]] - König von Sturmwind vor dem [[Der Erste Krieg|Ersten Krieg]]\r\n* Lady [[Varia Wrynn]] - Gattin von König Adamant Wrynn III\r\n* König [[Llane Wrynn]] I - König von Sturmwind im [[Der Erste Krieg|Ersten Krieg]]\r\n* König [[Varian Wrynn]] - Regierender König von Sturmwind\r\n* Prinz [[Anduin Wrynn]] - Thronerbe von König Varian Wrynn",},
			["Havenau"] = { content = "Das Dörfchen '''Havenau''' liegt direkt unterhalb der [[Todesbresche]] im Osten der [[Östlichen Pestländer]]. Es steht unter dem Schutz des [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzuges]] und ist das erste Angriffsziel der Truppen der [[Geißel]] von [[Acherus]]. Die Pferde aus den Ställen sind eine besondere Beute der [[Todesritter]] und so kommt es regelmäßig zu Diebstählen dieser Reittiere. \r\n==Minen von Havenau==\r\n[[Gothik der Ernter]] hat die Mine von Havenau zu seinem Ziel erklärt. Oder vielmehr die Scharlachroten Minenarbeiter, die dort drinnen arbeiten. Mithilfe der Gabe des Ernters, einem tragbaren Seuchenverbreiter, hat er die Arbeiter in Ghule verwandelt und so Streitkräfte des Scharlachroten Kreuzzugs ins Chaos gestürzt. \r\n==Lichtgipfel==\r\nNach dem Angriff der Geißel auf die Mine stellen nur die Streitkräfte des Scharlachroten Kreuzzugs bei [[Neu Avalon]] und dem Lichtgipfel noch eine Herausforderung dar. Die Zeit, die scharlachrote Flotte beim Lichtgipfel anzugreifen, ist gekommen, denn das Ablenkungsmanöver an der Mine hat sie ins Chaos gestürzt. Die Menschen versuchen verzweifelt, die Gegend freizuräumen und zu ihren Schiffen zurückzukehren. [[Prinz Valanar]] nutzt diese Gelegenheit, um ihrer Flotte den letzten Stoß zu versetzen. \r\n==Sieg der Geißel==\r\nNachdem Havenau von der Geißel überrannt wurde, wurde [[Noth der Seuchenfürst]] dazu beauftragt, einen [[Seuchenkessel]] zusammenzustellen und auf dem Kürbisbeet zu errichten. Doch dafür benötigt er Hilfe. Direkt hinter dem Tor von [[Neu Avalon]] befindet sich das Gasthaus. Dort soll ein leerer Kessel gestohlen werden, und aus der Schmiede, die sich in der Nähe des Tores befindet, besorgem ihm seine Helfen eine Eisenkette. Danach kann der Kessel seine faule Verderbnis ausspeien und über das Land verbreiten. Das Gas des Kessels ist für alles Lebendige tödlich, erfüllt die Diener der Geißel jedoch mit Macht. Wie mit allen Schöpfungen der Geißel, so nährt sich auch diese mit allem, was tot ist, und wird stärker, je länger sie sich nähren kann ... und dieser Kessel wird mit Kreuzfahrerschädel genährt. \r\n==Personen==\r\n* [[Noth der Seuchenfürst]]",},
			["Hazza'rah"] = { content = "'''Hazza'rah, der Traumweber''' befindet sich in [[Zul'Gurub]]. Dieser untote [[Troll]] ist einer von mehreren Bossen, die im Schlund des Wahnsinns auftauchen können. \r\n==Kampf==\r\nDie Sonderfähigkeit von Hazza’rah besteht darin, dass er die Schlachtgruppe in eine Tiefschlafphase versetzt und Alptraumkreaturen beschwört. Diese sind sehr langsam und haben recht wenig HP, jedoch verursachen sie beträchtlichen Schaden. Wichtig ist hier, dass alle Fernkämpfer auf maximale Distanz gehen. Dann wird konstant Schaden bei Hazza’rah verursacht. Wenn die Tiefschlafphase kommt und er die Kreaturen erschafft, müssen alle Fernkämpfer diese umgehend töten, sobald sie wieder aus ihrem Schläfchen erwacht sind. Sehr nützlich ist hierbei der Mehrfachschuss des Jägers.",},
			["Hazzas"] = { content = "[[Eranikus]] hat vier junge, aber geeignete und begierige Drachen unter seinem direkten Befehl: [[Traumsense]], [[Wirker]], [[Hazzas]] und [[Morphaz]] - die selbst eine riesige Armee aus Smaragdgrüner [[Drachenbrut]] und Welpen befehligen. Hazzas residiert gegenwärtig im [[Tempel von Atal'Hakkar]].",},
			["Hederine"] = { content = "Die '''Dämonen von Hederine''', die das Vorgebirge des Berges Hyjal in der flüsternden Schlucht von[[Winterquell]] bevölkern, sondern mächtige Gifte ab, die mit der Zeit hart und somit zu einem kompakten Anti-Magiekristall werden. Diese Kristalle sind auch als [[Tränen der Hederine]] bekannt. Nicht einmal die gewaltige Macht einer [[Verdammniswache]] könnte die Wände eines Gefängnisses durchbrechen, die aus diesem Material errichtet wurden. Hexenmeister benötigen so eine Träne, um das ''Ritual der Verdammnis'' zu erlernen. \r\n==Arten==\r\n* '''Initiand von Hederine''' - Initianten von Hederine sind [[Sukkubi]], die über die Fähigkeiten Feuerbrand und Schattenblitz verfügen.\r\n* '''Manapirscher von Hederine''' - Manapirscher von Hederine sind [[Teufelsjäger]], die über die Fähigkeiten Manabrand und Verwunden verfügen.\r\n* '''Töter von Hederine''' - Töter von Hederine sind [[Teufelswache]]n, die über die Fähigkeiten Spalten und Tödlicher Stoß verfügen.\r\n==Persönlichkeiten==\r\n* '''Lady Hederine''' - Lady Hederine ist eine seltene [[Sukkubi]] in [[Winterquell]].\r\n'''Quellen'''",},
			["Heigan der Unreine"] = { content = "'''Heigan der Unreine''' ist ein mächtiger [[Nekromant]] im Seuchenflügel von [[Naxxramas]].\r\n==Kampf==\r\nHeigan besitzt relativ wenige Fähigkeiten. Das Problem dieser Begegnung liegt in der Beschaffenheit des Raumes. Der Kampf gegen Heigan ist in zwei Phasen untergliedert. Die Bewegung durch den Raum ist der schwierigste Aspekt dieser Schlacht. Drei Spieler werden zufällig in den Nebenraum teleportiert, aus welchem sie so schnell wie möglich entfliehen müssen. Bei Heigan ist jeder Spieler für sich selbst verantwortlich. Während des Heigan-Tanzes kann man sich nicht an anderen Spielern orientieren, da jeder seinen eigenen Laufweg finden muss. Die Gifteruptionen sind auch das einzige Hindernis, das Euch vom Sieg über Heigan abhalten könnte. Wenn Heigan dann besiegt ist, öffnet sich das Tor im Nebenraum und Ihr gelangt direkt zu Loatheb, dem Endboss dieses Flügels. \r\n==Fähigkeiten==\r\n* '''MANABRAND:''' - Manabrand trifft einen Feind in 40 m Reichweite mit einem Antimanablitz. Für jeden vom Blitz verbrauchten Manapunkt erleidet das Ziel 1 Schaden. Jedem Spieler, der sich in der 1. Phase näher als 30 Meter an Heigan befindet, wird dann etwa 2.500 Mana und HP pro Tick abgezogen. \r\n* '''HEIGANS SEUCHE: Schwächefieber''' - Schwächefieber ist eine Krankheit, die die maximale Gesundheit um 50% reduziert und 21 Sekunden lang alle 3 Sek. Sek. 500 Naturschaden verursacht. In regelmäßigen Abständen wird jeder, der näher als 10 Meter an Heigan steht, von dieser Seuche befallen. Die Seuche muss daher von allen Spielern entfernt werden, wobei der Haupttank die höchste Priorität hat. \r\n'''Quellenangaben'''",},
			["Heiligen Lichts"] = { content = "#REDIRECT [[Heiliges Licht]]", redirect = "Heiliges Licht",},
			["Heiliges Licht"] = { content = "Das [[Heilige Licht]] ist eine nicht-theistische religiöse Form von Philosophie, deren Anhänger meistens [[Menschen]] oder [[Draenei]] auf Seiten der [[Allianz]] sind. \r\n==Allgemein==\r\nDie Anhänger des '''Heiligen Lichts''' beten keine Götter an, jedenfalls nicht direkt. Stattdessen ist das Licht eine Philosophie, deren Anhänger geistige Stärke und Führung erstreben. Für die, die das Licht verstehen, ist Glaube mehr eine Sache der praktischen Ausübung als Anbetung. Das [[Heilige Licht]] lehrt, dass man durch Gefühle und Emotionen seine Verbindung zum Universum erkennen kann. Wenn man etwas fühlt, dann weiß man, dass man existiert, dass in einem eine Macht ist, von der diese Emotionen kommen. Gleichzeitig weiß man auch, dass die Welt dadurch auch existiert, denn es gab einem diese Emotion und verändert einen. So kann man in der Welt etwas verändern, um damit jenes Gefühl auch in anderen hervorzurufen. Die Anhänger des Lichts versuchen, die Welt zu verbessern, indem sie zu ihren Gefühlen stehen.\r\nDer nächste Schritt zum Erkennen dieser Verbindung ist, dass, wenn man sich z.B. Glücklichkeit wünscht, es seine Aufgabe ist, die Welt so zu verbessern, dass andere glücklich sind. Wenn du die Schönheit der Welt erfährst, so entdeckst du auch deine eigene, innere Schönheit. Doch wenn du dich der Verzweiflung und Unzufriedenheit hingibst, verdüsterst du die Welt nur. Das Heilige Licht ist die Energie der Seele, die die Welt um einen herum erleuchtet und auf einen selbst zurückwirft. \r\nDie meisten Anhänger des Lichts sind [[Menschen]] und [[Draenei]]. Es gab früher auch viele [[Hochelfen]] und [[Zwerge]], die zum Licht beteten, doch ihre Zahl ist in den letzten Jahren zurückgegangen. Nachdem die [[Hochelfen]] weiter in die arkane Magie eingedrungen sind, verließen sie den Weg des Lichts. Die [[Zwerge]] hingegen ersetzen das '''Heilige Licht''' mit den Studien ihrer Vorfahren, den [[Irdene]]n. \r\n==Die drei Tugenden==\r\nDie Philosophie des Heiligen Lichts besteht hauptsächlich aus drei Lehren, den drei Tugenden - Respekt, Geduld und Mitgefühl. \r\n===Respekt===\r\nDie erste Lehre ist Respekt. Während das '''Heilige Licht''' lehrt, die Verbindung zwischen dem Einen und der Welt zu erkennen, muss man ebenso die Verbindung zu anderen Personen erkennen. Andere unglücklich machen, macht nicht die Welt glücklicher und somit auch nicht einen selbst. Die Anhänger des Lichts sind aber nicht naiv, und erkennen, dass Konflikte, Kriege und Leiden passieren; aber sie versuchen, die Welt auch mit diesen Hindernissen glücklicher zu machen. \r\n===Geduld===\r\nDie zweite Lehre, Geduld und Hartnäckigkeit, trennt die Gläubigen des Lichts von den Ungläubigen, da das richtige Beherrschen dieser Tugend Jahre dauert. Junge [[Akolyt]]en verlieren oft die Hoffnung und die wahre Bedeutung des Lichts, wenn sie erfahren, dass das Dienen dieser Philosophie ein ganzes Leben lang anhält. Die Welt ist viel größer als eine einzelne Person und während die Welt eine Person innerhalb eines Tages verändern kann, benötigt man weitaus länger, die Welt zu verändern. Nur durch Geduld und Hartnäckigkeit kann ein Diener des Lichts hoffen, die Welt zu verändern. Auch kann man sich Personen mit dem gleichen Ziel suchen, um vereint besser seine Aufgabe zu erfüllen. \r\n===Mitgefühl===\r\nNachdem die ersten beiden Lehren perfektioniert wurden, kann ein Lehrling die dritte Tugend erlernen: Mitgefühl. Die Verbindung zwischen sich selbst und der Welt ist stark, doch ist sie nur eine Verbindung. Wenn ein Anhänger des Lichts einer Person hilft, um deren Glücklichkeit zu erhöhen, wird seine Verbindung zur Welt stärker. Auch stärkt die Glücklichkeit, die er durch das Helfen selbst erhält, ihn selbst und die Welt. Infolgedessen kann er die Welt noch mehr beeinflussen. Mitgefühl ist wahrscheinlich die stärkste - und gefährlichste - Tugend. Wenn jemand zu mitfühlend ist, hilft er dort, wo eigentlich keine Hilfe nötig ist oder nicht erwünscht ist. Dies kann sein eigenes geistiges Wachstum und seine Glücklichkeit vermindern. Manche Helfer richten mehr Schaden an als sie Gutes tun. Dadurch vergrößern sie das Leiden in der Welt. Dies ist auch der Grund, warum Mitgefühl zuletzt gelehrt wird; nur der Weise und Mitfühlende kann wirklich herausfinden, wer Hilfe benötigt und wer sich selbst helfen kann. \r\n==Das Anbeten des Lichts==\r\n[[Lordaeron]] war lange Zeit die Heimat der [[Kirche des Lichts]], welche sowohl [[Lordaeron]] als auch [[Quel'Thalas]] mit ihren Lehren beeinflussen konnte. Aus der Kirche entstanden die Ritter des [[Orden der Silbernen Hand]]; doch als selbst diese nicht die untote [[Geißel]] stoppen konnte, bekam die Kirche einen neuen Position: [[Sturmwind]]. Über die Glaubensunterschiede der [[Draenei]], welche schon seit über 25.0000 Jahren das Heilige Licht verehren, ist wenig bekannt. \r\nViele [[Paladin]]e, welche früher dem [[Orden der Silbernen Hand]] dienten, versuchen nun, auf [[Kalimdor]] eine neue [[Kirche des Lichts]] zu bilden, doch dies schreitet nur langsam voran. Da die Lehren des Lichts mehr eine philosophische Lebensweise als ein Glauben sind, spiegelte die zerstörte Kirche von [[Lordaeron]] eher eine Bibliothek als eine Gebetsstelle wider. Doch die Texte wurden zusammen mit der Kirche zerstört, viele verbrannten, die meisten von ihnen liegen nun tief begraben unter Schutt. Durch den Krieg hatten die [[Priester]] nur wenig Zeit, die alten Texte in neue Bücher zu schreiben. Viele [[Jünger des Lichts]] lernen deshalb durch erfahrenere [[Priester]] anstelle durch Lesen von Büchern. \r\nEinige selbstbewusste Gelehrte versuchen, die Bücher des Lichts neu zu schreiben, doch wird dies nicht auf Richtigkeit überwacht. Es finden sich sowohl frische, neue Ideen als auch alte, Wort für Wort kopiert von den alten [[Priester]]n. Dies ist auch die Strömung innerhalb der Kirche: die meisten [[Jünger des Lichts]] meinen, dass [[Der Dritte Krieg]] der [[Kirche des Lichts]] eine Chance gab, sich selbst zu erneuern - dagegen fordern andere, die alten Traditionen zu behalten. Normale Bürger kümmern sich wenig um die Konversationen darüber, da sie einfache Rituale vorziehen. Während alles sich wandelt, bleibt nur der Glauben überhaupt stets gleich. \r\n'''Quellen:'''",},
			["Heilige Licht"] = { content = "#REDIRECT [[Heiliges Licht]]", redirect = "Heiliges Licht",},
			["Heiligpriester"] = { content = "#REDIRECT [[Lichtpriester]]", redirect = "Lichtpriester",},
			["Heimtückisches Nachtweberspinnengift"] = { content = "#REDIRECT [[Nachtweber]]", redirect = "Nachtweber",},
			["Heldenwache"] = { content = "=== Heldenwache===\r\nDie Heldenwache ist eine Insel im [[Steinhügelsee]]. Hier steht der Stein der Erinnerung mit folgender Inschrift:\r\n''\"Dieses Monument ist all denen gewidmet, die beim Schutz von [[Sturmwind]] gefallen sind. Unsere Leute haben Unglaubliches durchgemacht, um ihre Freiheit zu bewahren und ihr Schicksal in die eigenen Hände zu nehmen. Hier erinnern wir uns an jedes einzelne Opfer, das unsere Bürger während des [[Der Erste Krieg|Ersten Krieges]] gebracht haben, der unser Volk erschütterte.\"''",},
			["Heldenwacht"] = { content = "Die Heldenwacht am Eingang zu [[Silithus]] ist die letzte Ruhestätte der Gefallenen dieses Ödlandes. [[Layo Sternenschlag]], ein Agent vom [[Zirkel des Cenarius]] ist hier stationiert. Er möchte die Geister vom [[Südwindposten]] befreien und den Schwarmbau im Turm untersuchen. Dabei wird ein [[Verkrustetes Silithidenobjekt]] geborgen, welches zu [[Umber]], dem Archivar des [[Zirkel des Cenarius]], ins Dorf [[Nachthafen]] auf der [[Mondlichtung]] zur Analyse gebracht werden soll, denn wenn sich in diesem klebrigen Chitin ein Tagebuch befindet, hätte der Zirkel endlich ein Fenster zur Vergangenheit geöffnet und wenn diese Dokumente gerettet werden können, dann schafft Umber es. Desweiteren findet man auch Zannok Hidepiercer hier, einen Händler für Lederverarbeitungsbedarf, der u.a. das Muster: Schwere Skorpid-Armschienen verkauft.",},
			["Held der zerschmetterten Sonne"] = { content = "'''\"Held der zerschmetterten Sonne\"''' ist ein Titel, den man ab Patch 2.4. von der Fraktion \"[[Offensive der Zerschmetterten Sonne]]\" erwerben kann. Ein Held der Zerschmetterten Sonne hat viel für die Offensive der Zerschmetterten Sonne getan und genießt große Dankbarkeit. Für diesen Titel muss man einen ehrfürchtigen Ruf bei der [[Offensive der Zerschmetterten Sonne]] genießen und bei [[Anachoret Kairthos]] die Quest [70] \"Ein großmütiger Spender\" abschließen. Falls man [[Anachoretin Ayuri]] eine große Spende von 1.000 Gold machen würde, um ihre Sache zu unterstützen, wirde sich Anachoret Kairthos persönlich dafür stark machen, dass die Taten des Spenders Taten in diesem Krieg weit und breit bekannt sein werden. Sein Titel lautet dann: \"<Charaktername> der Zerschmetterten Sonne.\"\r\n'''Quelle:'''",},
			["Hematus"] = { content = "'''Hematus''' ist ein [[Schwarzer Großdrache]] in der [[Lethorklamm]] im [[Ödland]]. Zusammen mit [[Schattenbringer]] wird er in Lethlor festgehalten. Die schwarzen Großdrachen haben sich dort niedergelassen, und den Ogern ist es gelungen, das Zeichen der Erde zu stehlen. Das Gefängnis der Drachen wird von drei Runensteinen gebildet, die man nur mit Hilfe des Zeichens der Erde wegnehmen kann. Diese Runensteine aus den Säulen aus Diamant, Opal und Amethyst können dann dazu verwendet werden, das Siegel zu zerbrechen, das sie gefangen hält. \r\n==Fähigkeiten==\r\nHematus selbsts verfügt über die Fähigkeit des Flammenpuffers. Dieser Stärkungszauber verursacht bei einem Feind 28 bis 32 Feuerschaden und erhöht seinen erlittenen Feuerschaden 45 Sek. lang um 30. \r\n'''Quellen'''",},
			["Hemet Nesingwary"] = { content = "Hemet Nesingwary gehört zu den berühmtesten Großwildjägern in [[Azeroth]]. Bis vor einiger Zeit hatte er sein Lager im [[Schlingendorntal]], doch jetzt ist er zum Jagen in ferne Länder gegangen und sein Sohn hat seinen Platz im Dschungel eingenommen. [[Nesingwarys Safari]] hat sich von [[Azeroth]] aus auf die Jagd nach Großwild in die [[Scherbenwelt]] nach [[Nagrand]] begeben und kann nun dort angetroffen werden.\r\nHemet Nesingwary kam auch einst nach [[Desolace]], um große Wildtiere zu jagen. Sein Geschick mit Flinten war außergewöhnlich und er hat mit den [[Tauren]] viele Tage zusammen auf der Jagd verbracht. Sogar die Feindschaft zwischen den Völkern war vergessen.",},
			["Herdweiler"] = { content = "'''Herdweiler''' (engl. Hearthglen) war eine Provinz und Stadt [[Lordaeron]]s, die von Lord [[Tirion Fordring]] verwaltet wurde. Als sich die Seuche des Untodes im ganzen Königreich ausbreitete blieb auch Herdweiler nicht verschont. Verseuchtes Getreide aus [[Andorhal]] war unter den Bewohnern verteilt worden und hatte sie in willige Sklaven des [[Lichkönig]]s verwandelt. Eine Armee der Untoten, die sich über Nacht erhoben hatte, griff wahllos Dörfer an und maschierte auf die Stadt zu. Prinz [[Arthas]] verteidigte Herdweiler bis Lord [[Uther Lichtbringer]] mit Verstärkung eingetroffen war. Er konnte eine Karawane stoppen, die verseuchtes Getreide auch in benachbarten Ortschaften verteilen wollte. \r\n'''Quelle''': \r\n==Burg Mardenholde==\r\nDer [[Scharlachroter Kreuzzug|Scharlachrote Kreuzzug]] hat in Herdweiler sein Hauptquartier in den [[Westliche Pestländer|Westlichen Pestländern]] eingerichtet und rückt von da aus gegen die [[Geißel]] und die [[Verlassene]]n vor.\r\n==Personen==\r\n* '''Chevalier Durgen''' - Chevalier Durgen ist ein wichtiger Teil des Rückgrats der Streitkräfte des Kreuzzuges außerhalb von Herdweiler.\r\n* '''[[Hochlord Taelan Fordring]]'''\r\n* '''Jägerin Radley''' - Jägerin Radley ist ein wichtiger Teil des Rückgrats der Streitkräfte des Kreuzzuges außerhalb von Herdweiler.\r\n* '''Kirsta Grubenschatten''' - Kirsta Grubenschatten wurde als Späher ausgeschickt, um etwas Schaden anzurichten und die Kraft von Herdweilers Verteidigung auszukundschaften. Einige Leute der [[Allianz]] sind der Meinung, die kleine Stadt hat mehr als nur eine historische Bedeutung. Ihre Aufgabe ist es nicht, diese Bedeutung in Frage zu stellen, aber dennoch sollte sie sich in ihrer Verfassung erst erholen, bevor sie weitermacht. Ihre wahre Mission bestand darin, die äußeren Kräfte des Scharlachroten Kreuzzugs zu schwächen und dann Herdweiler zu infiltrieren, damit sie ihre Zahl abschätzen kann.",},
			["Herold Horizontiss"] = { content = "Der [[Qiraji]] Prophet '''Herold Horizontiss''' ist der Endboss in der [[Arkatraz]], einem Teilkomplex der [[Festung der Stürme]]. Er war es, der [[Aufseher Mellichar]] unter seine Kontrolle brachte und diesen zwang, die Kreaturen der Arkatraz freizulassen.\r\n==Taktik==\r\nHorizontiss übernimmt manchmal einen Mitspieler und schickt ihn gegen seine Kumpane. Darüber hinaus wirkt er Furcht und Gedankenwunde. Bei 66% und 33% seiner Lebensenergie erscheint eine Kopie des Bosses (ca. 20.000 Lebenspunkte), die auch die gleichen Fähigkeiten einsetzt. Die Kopie muss so schnell wie möglich zu Boden gebracht werden. (Quelle: \r\n'''Tipp:''' Setzt ein Schlachtzugsymbol auf den Boss, so könnt Ihr jederzeit zwischen beiden unterscheiden. \r\n==Fähigkeiten==\r\n* '''Beherrschung''' - Ein Spieler ist übernommen und greift seine Mitspieler an.\r\n* '''Furcht''' - Ein Spieler flüchtet handlungsunfähig durch den Raum.\r\n* '''Gedankenwunde''' - Ein Spieler ist betäubt und erleidet über 3 Sekunden pro Sekunde 1.800 Schattenschaden.\r\n* '''Klonen''' - Bei 66% und 33% der Lebensenergie erschafft der Herold eine Kopie von sich selbst, die über weniger Lebenspunkte, aber über die gleichen Fähigkeiten verfügt.",},
			["Herrin der Meere"] = { content = "Die '''Herrin der Meere''' war ein Linienschiff der [[Dritte Flotte von Kul Tiras|Dritten Flotte von Kul Tiras]], welches gemeinsam mit der Flotte unterging. Sie liegt heute südlich vom [[Hafen von Menethil]] im [[Sumpfland]] auf Grund.",},
			["Herrschaftsring des Schattenhammerklans"] = { content = "Ein Herrschaftsring des Schattenhammerklans ermöglicht die Benutzung von großen [[Windsteine]]n in [[Silithus]], wenn man die Verkleidung zusammen mit dem [[Zierratsset der Schattenhammer]] und dem [[Standesmedaillon eines Schattenhammerkultisten]] trägt. Dieser Ring wird nur von den höchsten Mitgliedern des Kultus, wie z.B. [[Lord des Schattenhammers Everun]] getragen.\r\nIn der [[Burg Cenarius]] in [[Silithus]] kann man drei [[Abyssische Siegel]] und fünf große glänzende Splitter gegen eine täuschend ähnliche Nachahmung der Herrschaftsringe eintauschen. Dazu benötigt man den Ruf Respektvoll beim [[Zirkel des Cenarius]].",},
			["Herzholz"] = { content = "Im [[Krieg der Uralten]] fielen in den [[Ruinen von Ordil'Aran]] im [[Eschental]] zwei Liebende gemeinsam im Kampf und wo sie ihren letzten Seufzer taten, wuchs ein als '''Herzholz''' bekannter Baum als Symbol ihrer unsterblichen Liebe. Dieses Holz benötigen [[Hexenmeister]], um einen Sukkubus herbei zu locken. \r\n==Geschichte==\r\nVor tausend Jahren kämpften die unsterblichen Elfen, die Halbgötter des Waldes und die [[Drachen]] an den Hängen des [[Hyjal]] gegen die [[Brennende Legion]]. ''Anathera'' und ''Latherion'' kämpften Rücken an Rücken dort, wo die Schlacht am blutigsten war. Zwei Liebende, die den Krieg gemeinsam überleben wollten. Aber es sollte nicht sein. Als ihre Feinde näher rückten, wurde Anatheras Rüstung von einer besudelten Klinge eines Dämonen durchbohrt. Im Schlachtgetümmel gab es nichts, was sie retten konnte. Latherion vergaß die Schlacht, die um ihn tobte, vernachlässigte seine Deckung, um seine Geliebte in ihren letzten Momenten in den Armen zu halten. Aber die Dämonen schonten ihn nicht und metzelten auch ihn schnell nieder. Ein Baum sproß an der Stelle, an der die beiden Liebenden fielen. Die Elfen nennen ihn Herzholz. \r\nDie letzten Worte der beiden waren:\r\n''Latherion: \"Anathera!\"'' \r\n''Anathera: \"So also ... so also endet es, mein Herz ...\" ''\r\n''Latherion: \"Anathera ... ich ertrage es nicht, der Ewigkeit ohne dich an meiner Seite entgegenzutreten... Wenn du mir genommen wirst, dann soll dies der Tag sein, an dem auch ich in den Schoß der Erde zurückkehre.\" ''\r\n'''Quests''' \r\n'''Quellen'''",},
			["Herz des Berges"] = { content = "Das '''Herz des Berges''' ist ein Edelstein so groß wie eine Faust. Die [[Dunkeleisenzwerge]] in den [[Schwarzfelstiefen]] haben es in ihrem Gewölbe weggeschlossen und wollen einfach nicht verkaufen. Dabei würde es [[Maxwort Funkelglanz]] am [[Flammenkamm]] so gern sein Eigen nennen.",},
			["Herz des Vermächtnisses"] = { content = "'''Das Herz des Vermächtnisses'''\r\n[[Mogh der Unsterbliche]] ist ein [[Troll Hexendoktor]] im [[Schlingendorntal]]. Er ist im Besitz des Herzens des Vermächtnisses, von dem es heißt, es hielte den Tod von jenen fern, die seine Geheimnisse lüften können. Man findet Mogh in den [[Ruinen von Zul'Mamwe]]. Besiegt man ihn, so soll man [[Bewahrer Bel'dugur]] in [[Unterstadt]] und [[Gerrig Knochengriff]] in [[Eisenschmiede]] das Herz des Vermächtnisses bringen.",},
			["Hetaera"] = { content = "Die [[Hydra]] Hetaera ist eine geringere Gottheit in [[Azshara]], die die Kinder von Lord [[Arkkoroc]] tötet. Sie nennt sich selbst die Herrscherin dieser Meere. Doch sie ist eine falsche Göttin, die in ihrem Gelege weilt.",},
			["Hethiss"] = { content = "Hethiss ist ein Kind von [[Ula'tek]]. Er ist der Fürst der Vipern und wird von den [[Dschungeltroll]]stämmen als mächtiger [[Loa]] verehrt.Sein oberster Diener ist [[Hohepriester Venoxis]], der jedoch von [[Hakkar]] verderbt wurde und die Macht des Viperfürsten dem Seelenschinder überträgt.",},
			["Heulenden Fjord"] = { content = "#REDIRECT [[Der heulende Fjord]]", redirect = "Der heulende Fjord",},
			["Heulender Fjord"] = { content = "#REDIRECT [[Der heulende Fjord]]", redirect = "Der heulende Fjord",},
			["Heulendes Tal"] = { content = "Das Heulende Tal liegt im Norden von [[Eschental]], nahe der Grenze zum [[Teufelswald]]. Dort wurde der verfallene [[Schrein von Mel'Thandris]] von rätselhaften [[Worgen]] übernommen. Ihre Schreie, die einem das Blut in den Adern gerinnen lassen, haben dem als \"Das heulende Tal\" bekannten Gebiet seinen Namen gegeben. Der [[Foliant von Mel'Thandris]], der im Schrein aufbewahrt wird, könnte etwas Licht darauf werfen, warum die [[Wolfmenschen]] hier sind. Denn obwohl die [[Nachtelfen]] viele Mittel und große Bemühungen investiert haben, um auch die letzten [[Dämonen]] aus dem [[Teufelswald]] im Norden zu vertreiben, hatten sie nur wenig Erfolg damit. Sie konnten jedoch einen Großteil der [[Dämonen]] vom [[Eschental]] fern halten.",},
			["Hexendoktor"] = { content = "Obwohl die '''trollischen Hexendoktoren''' extrem grausam und ruchlos sind, haben sie sich aus reiner Notwendigkeit mit der [[Horde]] verbündet. Diese hinterhältigen Magie-Anwender sind erfahren darin, die chemischen Prozesse in befreundeten Kriegern zu manipulieren, um deren Kampf Fähigkeiten zu erhöhen.",},
			["Hexendoktor Zum'rah"] = { content = "'''Hexendoktor Zum'rah''' ist ein hoher Troll des [[Trolle der Sandwüter|Sandwüterstammes]] in [[Zul'Farrak]]. Er wartet mit seiner Truhe und seinem Kochtopf inmitten der Gräber im Raum hinter [[Theka der Märtyrer|Theka dem Märtyrer]]. Dort steht Zum'rah in einer kleinen Hütte und ruft im Kampf mehrere Untote zu seiner Unterstützung herbei. Das gestaltet den Kampf ist nicht ganz einfach, da dadurch viele Gegner in den Kampf eingreifen können. Öffnet man die Gräber vor seinem Podest, finden sich einige interessante Dinge, jedoch können dem Grab genauso gut auch ein bis zwei untote Trolle entsteigen.",},
			["Hexenmeister"] = { content = "==Allgemeines==\r\nHexenmeister sind Meister der Schatten, des Feuers und der dämonischen Kräfte. Sie sind eine robentragende [[:Kategorie:Klasse|Klasse]], exzellent dazu fähig, ihre Feinde mit Krankheiten und Flüchen zu quälen, Feuer- oder Schattenblitze über das Schlachtfeld zu jagen und [[Dämon]]en zu ihrer Unterstützung zu beschwören. Während sie als mächtige Zauberer hauptsächlich aus der Ferne kämpfen, können sie ihre Verbündeten mit Hilfe ihrer [[dämon]]ischen Kräfte schützen oder sogar Spieler von beinahe überall auf der Welt mit Hilfe ihrer Portalzauber beschwören.\r\nHexenmeister besitzen sowohl mächtige (hauptsächlich über gewisse Zeitspannen wirkende) Schadenszauber als auch Schwächungszauber, die hervorragend miteinander sowie mit den Fähigkeiten ihrer Gruppenmitglieder harmonieren. Ihre Flüche passen auf viele verschiedene Situationen; tatsächlich kann man sie mit Recht als die stärksten Schwächungszauberer des Spiels bezeichnen. Ihre Helfer, aus finsteren Abgründen beschworene [[Dämonen]], helfen ihnen beim Austeilen von Schaden und verleihen dem Hexenmeister weitere Spezialfähigkeiten. Mit ihren Verführungs- und Verbannungszaubern können sie außerdem auch größere Gruppen von Feinden sehr gut kontrollieren. Des weiteren war schon so mancher Verbündete dankbar für die beschworenen Steine des Hexenmeisters. Hexenmeister benötigen oft jedoch [[Seelensplitter]], um ihre Zauber zu wirken.\r\n==Wissenswertes==\r\nObwohl viele, die sich mit [[Dämonen]] verbünden, der Dunkelheit anheim fallen, gelingt es dem Hexenmeister, die dämonischen Kräfte unter seinen Willen zu zwingen, ohne dass er dem reinen Bösen verfällt. Um sich der Verderbnis zu erwehren, die den Weg begleitet, bedarf es eines starken Willens und großer, innerer Stärke. Solange man Herr seines Willens ist, wird einem großer Erfolg beschieden sein. Dann werden sich die Feuer der Unterwelt gegen die Feinde der Hexenmeister erheben. Sie halten die Schlüssel zum Wesen des Bösen in ihren Händen, das sie gegen alle wenden, die sich ihren hinterhältigen Plänen in den Weg stellen. Die chaotischen Kräfte dieser teuflischen Magier und die Macht über die Schreckgestalten ihrer dämonischen Meister erfüllen jeden Gegner mit lähmender Furcht. Hexenmeister haben auch die Fähigkeit, Elementare oder Dämonen in den Nether zu verbannen und jene die den Nether betreten, kehren nur selten zurück.\r\n===Fähigkeiten===\r\n'''Dämonologie'''\r\nDie Macht der Dämonologie ermöglicht es Hexenmeistern Kreaturen aus dem [[Nether]] herbeizurufen und sie nutzen jedes Mittel, das ihnen zur Verfügung steht, einschließlich ihrer Freunde. Zu den Fähigkeiten der Dämonologie gehört z.B. auch das ''Auge von Kilrogg'', das zu Ehren von [[Kilrogg Totauge]], dem Häuptling der [[Orcs des Blutenden Auges]], benannt wurde. \r\n'''Gebrechen'''\r\nHexenmeister können durch die Macht der Gebrechen ihre Feinde die Bitternis ihrer eigenen Sterblichkeit kosten lassen. Doch diese Macht hat immer ihren Preis, man muss nur wissen, ob man sie sich leisten kann oder nicht. Sie stehlen die Essenz ihrer Feinde und trinken davon, auf dass deren Gesundheit den Hexenmeistern lange gehören. \r\n'''Zerstörung'''\r\nZu den Fähigkeiten der Zerstörung gehört z.B. der ''Feuerregen'', der im [[Nether|Wirbelnden Nether]] fällt, der ''Feuerbrand'' oder auch der Schattenblitz, auf dass die Dunkelheit ihre Feinde nehmen möge, denn wenn der Hexenmeister mit ihnen fertig ist, wird das Licht sie nicht wiedersehen. \r\n==Rassenspezifische Unterscheidungen==\r\n* Blutelfen: [[Blutelfen Hexenmeister]] ([[Bannzauberer]], [[Beschwörer]], [[Nethermant]])\r\n* Gnome: [[Gnomen Hexenmeister]] \r\n* Hochelfen: [[Hochelfen Hexenmeister]] ([[Hochhexer]])\r\n* Menschen: [[Menschen Hexenmeister]] ([[Nekromant]], [[Schattenmagier]])\r\n* Orcs: [[Orc Hexenmeister]] \r\n* Untote: [[Untoter Hexenmeister]] ([[Schattenmagier]])\r\n==Dämonenherbeirufung==\r\nWährend der Ausbildung zum Hexenmeister wird man lernen, Wesen vielerlei Arten herbeizurufen. Manchen sieht man es nicht an, aber alle sind nützliche Werkzeuge. Früher oder später werden sich selbst [[Höllenbestien]] und [[Schreckenslords]] vor den Hexern in den Staub werfen. Aber bis dahin muss man sich noch auf die Waffen verlassen, die von Sterblichen geschaffen wurden.\r\n* [[Höllenbestie]]\r\n* [[Leerwandler]]\r\n* [[Sukkubus]]\r\n* [[Teufelsjäger]]\r\n* [[Teufelswache]]\r\n* [[Wichtel]]\r\n==Rangsymbole==\r\nAlle magischen Rangsymbole eines Hexenmeisters müssen mit einem Gegenstand von hoher Qualität beginnen. Je mehr Mühe und Können man in einen Gegenstand legt, desto größere Magie kann er aufnehmen. Seltene und teurere Komponenten halten die Magie besser. Die Verzauberte Goldblutrobe z.B. besteht aus den Roben von Arcana, einem Goldfaden, der aus einem Goldbarren gesponnen wurde, Zornsäerblut von den [[Satyre der Zornsäer]] im Nordosten und einem Geringen Höllenstein von den geringen [[Höllenbestien]] beim [[Zirkel der Mannoroc]] in [[Desolace]], sowie glimmenden Kohlen von den [[Feuerelementare]]n im [[Arathihochland]] und einen Seelensplitter.\r\n==Rollenspiel-Hilfen==\r\n* [[Abhandlung über Nethermagie]] von Selian Flammenzorn\r\n* [[Netherwissenschaften Band I]] von [[Anthrazides]]\r\n'''Quellen'''",},
			["Hexenmeister der Menschen"] = { content = "#REDIRECT [[Menschen-Hexenmeister]]", redirect = "Menschen-Hexenmeister",},
			["Hexensumpf"] = { content = "Der '''Hexensumpf''' ist eine unwirtliche Gegend in den nördlichen [[Düstermarschen]]. Mordant Grimsby kam hierher, um Sumpfauge Jarl zu besuchen. Doch was fand er? Jarl, in einer leeren Hülle mitten im Nirgendwo, wie er über Frösche plappert. Mordant hat Jarl ein Einweihungsgeschenk mitgebracht, doch er findet, dass sein alter Freund wie verwandelt ist, seit er ihn das letzte Mal gesehen hat. \r\n==Personen==\r\n* '''Marg Nighteye''' - Ausgiebiges Graben förderte den Kopf eines männlichen [[Orcs]] zu Tage, der am Hals abgesägt worden war. Seine Lippen waren zu einer höhnischen Grimasse verzerrt, seine dunklen Augen blicken trotzig. Es waren die Überreste von [[Marg Nighteye]], einem orcischen Agenten, der einen wichtigen [[Spionbericht]] für den Spionagemeister in [[Brackenwall]] anfertigte. In der Nähe von [[Theramore]] sah Marg eine Gruppe Soldaten der [[Allianz]] am Ufer kampieren. Ein Soldat trug einen Anhänger... einen Anhänger mit mehr Edelsteinen, als ihn sich ein Soldat leisten könnte. In jener Nacht schlich [[Marg Nighteye]] in ihr Lager und stahl den Anhänger, aber nach seiner Rückkehr zum Stützpunkt tötete ihn ein Matschpanzerkrebsmann.\r\n* '''Mordant Grimsby''' - [[Mordant Grimsby]] ist ein alter Bekannter von Sumpfauge Jarl, der im Irrlichtanwesen zu Besuch ist. \r\n* '''Sumpfauge Jarl''' - [[Sumpfauge Jarl]] wohnt hier im Irrlichtanwesen. Er kocht gern Rezepte aus der leckeren Sumpfküche, vor allem frittierte grüne Froschschenkel und dergleichen. Auch Graunebelaugensaft aus unzerplatzten [[Spinnen]]augen ist nach seiner Meinung ein guter Saft zum Trinken und ziemlich lecker. Samtig und salzig.",},
			["Hexknall Kurbeldreh"] = { content = "Hexknall Kurbeldreh ist ein gnomischer Bastler und seine neueste Erfindung ist die [[Dröhnkiste]]. Er kam nach Auberdine wegen der Ruhe. Er möchte seine Erfindungen machen, wo es ruhig ist, denn nach einer durchzechten Nacht erträgt er den Lärm von Eisenschmiede nicht. Daher nahm er ein Schiff nach Auberdine, trank aber unterwegs ein bisschen viel. \r\n==Erfindungen==\r\n* [[Dröhnkiste]]\r\n===Propellerbetriebene explodierende Entenattrappen===\r\nEines Nachts schlenderte er durch die Straßen von [[Dunkelküste]] und suchte nach einem geeigneten Fluss oder See, um seine neuen propellerbetriebenen explodierenden Entenattrappen auszuprobieren. Er muss wohl etwas beschwipst gewesen sein, denn Stunden später wachte er in Auberdine auf. Sein Haar war versengt und meine Tasche mit den Elektropellern war weg. Sie müssen ihm ins Wasser gefallen sein und nun sucht er die Klemmmuffen.",},
			["Hexlord Malacrass"] = { content = "'''Hexlord Malacrass''' ist der vorletzte Boss in [[Zul'Aman]]. Er ist die rechte Hand von [[Zul'jin]] und hat die Geister der Tiergötter mit den besten Kämpfern der [[Amani]] verschmolzen. Er ist ein listiger, alter, verbitterter [[Troll]] und einer der besten Wirker von Magie, den die [[Trolle]] je hervorgebracht haben.\r\nMalacrass erwartet seine Herausforderer mitsamt vier Begleitern. Ihn zu töten ist das Ziel von [[Budd Winterhändler]] in den Axthügeln, damit seinem großen Auftritt in Zul'Aman nichts mehr im Weg steht. Budd meint, es ist nichts weiter dabei, den Hexlord zu besiegen. Er wird wahrscheinlich sofort kehrt machen und abhauen, denn gebrechlichere, ältere Trolle gleichen ihre Schwächen oft mit einem einschüchternden Titel aus. \r\n==Fähigkeiten==\r\n* '''Geistblitze''' - Geistblitze schleudern etwa alle 30 Sekunden Geschosse von dunkler Magie innerhalb von zehn Sekunden auf in der Nähe befindliche Feinde und verursachen etwa 9.000 Schattenschaden. \r\n* '''Kraft entziehen''' - Nach der zweiten Geistblitzsalve entzieht Malacrass nahen Gegnern die Macht. Er verringert dabei ihren zugefügten Schaden pro Stapel um 1% und erhöht seinen zugefügten Schaden pro Stapel um 1%. \r\n* '''Seele entziehen''' - Ab der zweiten Kampfminute nutzt Malacrass für 20 Sekunden die Klassenfähigkeiten eines zufälligen Spielers. Dieser Effekt tritt direkt nach den Geistblitzen auf.",},
			["Hi'reek (Anduri Stamm)"] = { content = "#REDIRECT [[Hi'reek]]", redirect = "Hi'reek",},
			["Hildegard"] = { content = "=Hildegard Sprigglespruxx= \r\n==Quartier/Einflussbereich/wahrscheinlichste Aufenthaltsorte:==\r\nWohnt direkt an der [[Seher]]treppe in [[Shattrath]]. Sofern Hilde nicht am arbeiten ist - also [[Oger]] und [[Untote]] bekriegt, die [[Horde]] ärgert oder mit mäßigem Erfolg versucht die gefährlichste aller Gladiatoren zu werden - dann findet man sie meist in [[Gnomwind]], am Marktplatz oder im [[Zwerge]]nviertel.\r\nDa Hildegard häufig knapp bei Kasse ist kann man sie auch häufig im Dienst der zerschmetterten Sonne auf der Insel Quel'Denas antreffen.\r\n==Beruf/Aufgabe:==\r\n[[Gnome]]n[[Ingenieur|ingenieuse]], bastelt immer wieder an Projekten wie dem mechanischen Großdrachen. Anhängerin der [[Regentinnen von Gnomwind|Regentinnen]] und [[Gnomwind]]. Sie ist Wissenschaftlerin am [[Institut für Pfuschkunde]] und außerdem eine Meuteverprüglerin in den Diensten der [[Schatzsucher]].\r\n==Grobe Beschreibung/Historie:==\r\n \r\nGenannt wird sie die wilde Hilde und ist die Cousine von [[Carra Sprigglespruxx]]. Zumeist trägt Hildegard eine ihrer vielen Brillen und nur zum [[Angeln]] in der [[Beutebucht]] oder zum faulenzen in [[Gnomwind]] trägt sie mal den wunderschönen Heldenhut von Toshleys Station. Sie hat strubbelige Haare, die sich jedem Kamm verweigern und Sommersproßen. \r\nSie ist sehr aufbrausend, aber auch gleichzeitig harmoniesüchtig. Deswegen kann sie äußerst wütend werden, aber fast nie länger als fünf Minuten. \r\nIhre Vorgeschichte ist nur teilweise bekannt und was bekannt ist kann man in dem Text [[Zwiegespräche in Schwarz und Weiss]] nachlesen.\r\nIn den Aufzeichnungen zu der Ermittlung um den [[Der ermordete Gnom|ermordeten Gnom]] finden sich viele Aufzeichnungen und Tagebucheinträge von Hildegard. Diese Ermittlungen prägten sie nach Berichten von Freunden sehr intensiv.\r\n==Eigenarten:==\r\n \r\nHilde ist die [[Gnome|gnomische]] Antwort auf die Frage, die nie gestellt wurde. Sie hat Angst vor Bäumen und vor großen Kriegern mit großen Waffen.\r\n==Vorträge und Forschungen:==\r\nDie erste Forschungsarbeit von Hildegard Sprigglespruxx war [[Wissenschaftliche Gedanken über Schwefel und Wackelpudding]]. Mit diesem Vortrag erreichte sie die Aufnahme in den Kreis der Wissenschaftler beim Insitut für Pfusckunde. Ihre Forschungsergebnisse werden von Forschern anderer Rassen häufig in Frage gestellt, aber Beweise für Fehler sind unbekannt.\r\nVor kurzem wurde die Arbeit zu \"[[Archimonde - ein Rollenbild für Gnome ?]]\" abgeschlossen. Der Vortrag wurde am zweiten Juni nur einer Hand voll eingeweiheter in der Tiefenbahn vorgestellt.\r\nThema der neuesten Forschung sind Druiden. Gemeinsam mit der Praktikantin Fanya werden zur Zeit die Grundlagen der intrakorporalen Techniken und Möglichkeiten mechanischer Gestaltwandlungen erforscht. Noch gibt es keinen geplanten Termin für die Veröffentlichung.\r\n==Operation \"Neues Gnomwind\"==\r\nZur Zeit arbeitet Hildegard an der [[Operation \"Neues Gnomwind\"]] mit dem Ziel eine neue Heimat für die [[Gnome]] zu finden.\r\n===Feuerwerke===\r\nHildegard ist eine Meisterin des gnomischen Feuerwerks. Ihre Künste können jeden Sommer bei dem [[Sommerfeuerwerk in der Wildhammerfeste]] bestaunt werden. Sie beherrscht die Herstellung jeder Feuerwerkskomponente, die jemals in den Himmel von Azeroth geschossen wurde.\r\n===Ingenieurskunst===\r\nHildegard ist Meisteringenieuse und besitzt die Pläne für fast jeder Produkt der Ingenieurskunst. Ausgenommen sind die Pläne für die Zielfernrohre aus Karazhan und dem Geschmolzenen Kern.\r\nEine genaue Liste findet sich im Handwerkerverzeichnis unter [[Ingenieur:_Rezepte]].\r\n===Lederverarbeitung === \r\nHildegard ist Meisterin der Lederverarbeitung und beherrscht als gängigen Rezepte der Fraktionen. Schattenschutz von den Aschenzungen, die Reitgerte, Trommeln oder Beinrüstungen.\r\nEine genaue Liste findet sich im Handwerkerverzeichnis unter [[Lederer:_Rezepte]].\r\n==Weitere Informationen==\r\nArsenallink: \r\n===Arenateams===\r\n2vs2 Die Dolchkrallbande mit [[Coiren Bayvanar]], [[Carra Sprigglespruxx]] und [[Seranna]] \r\n3vs3 Für Gnomwind ! (wird momentan neu formiert)\r\n5vs5 Portalkrabbler mit [[Tolpaná Barfuß]], [[Carra Sprigglespruxx]], [[Coiren Bayvanar]],[[Wilfried Lathor]], [[Tramezzini]] Kasterl, [[Seranna]] und [[Livya]]",},
			["Hildegard Sprigglespruxx"] = { content = "#REDIRECT [[Hildegard]]", redirect = "Hildegard",},
			["Himmelssturzgrat"] = { content = "Der riesige rote Kristall im Himmelssturzgrat auf der [[Höllenfeuerhalbinsel]] ist vor kurzem vom Himmel gefallen und hat dabei ein großes Erdbeben ausgelöst. Als der [[Zirkel des Cenarius]] hierher kam, um vom [[Posten des Cenarius]] aus den Grund für den Aufruhr zu erforschen, haben sie [[Kolosse]] dort gesehen, die zuvor noch nicht da waren. Es ist eindeutig etwas faul an dem Kristall und den Energien, die er ausstrahlt. Als einer der [[Kolosse]] einem Angriff zum Opfer fiel, bemerkte man, dass er ein rotes Kristallfragment in der Hand hielt. In der Hand des [[Riesen]] schien es sehr klein und unauffällig, aber für jemanden von normaler Größe war das Stück sehr schwer zu tragen. Es sah sehr verdächtig nach einem Stück des riesigen roten Kristalls in der Mitte des Grats aus. Das war ganz sicher ein Hinweis auf die merkwürdigen Dinge, die dort geschehen sind. Es müssen die bösen Strahlungen von dem riesigen roten Kristall sein, die die [[Bergriesen]] herbeiriefen und sie wahnsinnig machten. Der Kristall ist zu groß, um ihn weg zu bringen, und die Fertigkeiten des [[Zirkel des Cenarius]] reichen nicht aus, um ihn zu zerstören.",},
			["Himmelssturzsee"] = { content = "Beim Himmelssturzsee im Südosten von [[Eschental]] haben die [[Nachtelfen]] früher immer [[Mondsteine]] gesammelt ... bis die [[Schattendickichtbäumlinge]] kamen. Ihr Anführer, das [[Schattendickichtorakel]], hat alle gefallenen [[Mondsteine]] eingesammelt und hortet sie.",},
			["Himmelsteiler"] = { content = "Die '''Himmelsteiler''' sind die Flugeinheit der [[Orcs des Drachenmals]] im [[Schattenmondtal]] unter Leitung von [[Hauptmann Himmelsdonner]]. Sie haben ihren Hauptstützpunkt im [[Basislager des Drachenmals]] auf der [[Netherschwingenscherben]] und obwohl es ursprünglich eine rein orcische Einheit war, sind die Orcs des Drachenmals erstaunlich offen, wenn es darum geht, auch anderen Rassen die Chance zu geben, sich als Himmelsteiler zu beweisen. \r\nWenn man zu den Himmelsteilern gehören möchte, sollte man fliegen können; und auch wenn man sich als fähiger Anhänger des Drachenmals bewiesen hat, ist dies in den Lüften der [[Scherbenwelt]] bedeutungslos. Im [[Basislager des Drachenmals]] gibt es sechs Reiter. Besiegt man sie alle im [[Drachenmalrennen]], werden einem die Flügel der Himmelsteiler gegeben. Durch dieses Rennen kann man im Ansehen des Drachenmal Klans steigen und der Sieger erhält den Rang eines Toporcs. Ein verdienter Toporc der Himmelsteiler reitet für gewöhnlich auf einem Netherdrachen, während unter den Anwärtern auf den Titel auch andere Flugreittiere zu finden sind, wie z.B. [[Greife]] und [[Flügeldrachen]]. \r\n==Persönlichkeiten==\r\nZu den nennenswerten Himmelsteilern gehören u.a.\r\n* [[Corlok der Veteran]]\r\n* [[Hauptmann Himmelsdonner]]\r\n* [[Ja'y Nosliw]]\r\n* [[Murg \"Grufti\" Moorbiss]]\r\n* [[Schwadronskommandant Ichman]]\r\n* [[Schwadronskommandant Mulverick]]\r\n* [[Trope der Rußhuster]]",},
			["Himmelswache der Sha'tari"] = { content = "Die '''Himmelswache der Sha'tari''' ist eine von [[Shattrath]] aufgestellte Luftstreitmacht, die sich der Bedrohungen in den äußeren Regionen der [[Scherbenwelt]] annimmt.\r\n==Allgemeines==\r\nDie Himmelswache der Sha’tari ist eine [[Fraktion]], die den [[Sha'tar]] angehört und insbesondere für das epische fliegende Reittier, den Netherrochen, bekannt ist. Es gibt auch noch andere auf Ruf basierende Belohnungen, zum Beispiel epische Schmuckstücke. Sobald man einen wohlwollenden Ruf genießt, kann man von einer kostenlosen und direkten Flugroute zwischen den beiden Lagern der Himmelswache in den [[Wälder von Terokkar|Wäldern von Terokkar]] und dem [[Schergrat]] profitieren. Wählt man diese Flugroute, wird man von einem [[Netherrochen]] ans Ziel gebracht und bekommt somit einen ersten Vorgeschmack auf das vielleicht schon bald eigene außergewöhnliche [[:Kategorie:Reittier|Reittier]].\r\nEine Kombination von täglichen und einmaligen Quests ermöglicht es euch, euren Ruf von anfangs „neutral“ auf „ehrfürchtig“ zu verbessern. Um Quests für die Himmelswache abschließen oder einen [[Netherrochen]] bei „ehrfürchtigem“ Ruf erwerben zu können, ist eine Reitfertigkeit von 300 zwar nicht erforderlich, damit ihr den [[Netherrochen]] letztendlich reiten könnt, müsst ihr jedoch über diese Fertigkeit verfügen.\r\nWer sich mit der Himmelswache anfreunden möchte, sollte als Erstes mit [[Yuula]] sprechen, die sich in der Nähe des Flugmeisters in [[Shattrath]] aufhält. Verfügt man über die erforderliche Reitfertigkeit von 225, wird man entsandt, um [[Oger der Gordunni]] bei der Hügelwand zu töten, welche man lediglich ein paar Flugsekunden von [[Shattrath]] entfernt findet. Habt ihr die von [[Yuula]] gewünschte Anzahl [[Oger]] erledigt, wird sie von eurem Heldenmut beeindruckt sein und euch daraufhin zur Himmelswache beim [[Schattenwindlager]] schicken.\r\n'''Quelle:''' WoW-europe.com",},
			["Himmelsweisensee"] = { content = "Der '''Himmelsweisensee''' liegt im Westen von [[Nagrand]]. Die Unruhen in den Gezeiten der Gewässer in diesem Gebiet hat die Wassergeister des Himmelsweisensees sehr aufgebracht und sie haben im Gegenzug damit begonnen, Verwüstungen entlang der Wasserwege anzurichten. Ihr Anführer [[Watoosun]] hat den [[Elementarist]]en am [[Thron der Elemente]] erlaubt, das Problem zu lösen, solange sie auch die Ursache dafür beheben. Watoosun konnte zwar den Seuchengestank loswerden, aber gleichzeitig erschuf er eine irrsinnige Geisteressenz.",},
			["Hinterland"] = { content = "Das zerklüftete Gebiet des Hinterlands ist nicht nur das Zuhause der [[Zwerge des Wildhammerklan]]s und ihrer Greifen, sondern auch einiger Waldtrollstämme. Die [[Waldtrolle]] betrachten die [[Wildhämmer]] als Besatzer ihres Heimatlands und lassen keine Gelegenheit aus, um die [[Zwerge]] zu belästigen, indem sie die Greifennester angreifen. Drei verschiedene Trollstämme bewohnen das Hinterland: die [[Bleichborken]], die [[Blutfratzen]] und die [[Bruchhauer]]. Soviel zu den Gemeinsamkeiten der Stämme: Sie sind alle [[Trolle]] und sie leben im Hinterland.\r\n==Orte==\r\n* [[Altar von Zul]]\r\n* [[Bogens Kante]]\r\n* [[Dorf der Bruchhauer]]\r\n* [[Federbarts Hütte]]\r\n* [[Hiri'watha]]\r\n* [[Jagdhütte von Quel'Danil]]\r\n* [[Jintha'Alor]]\r\n* [[Lauerfels]]\r\n* [[Nistgipfel]]\r\n* [[Shadra'Alor]]\r\n* [[Shindiggers Lager]]\r\n===Dörfer===\r\n* '''Agol'watha''' ist ein Tempel der [[Bleichborken]] im Nordosten.\r\n* '''Shaol'watha''' ist ein Tempel der [[Blutfratzen]] im Nordosten des Hinterlands.\r\n* '''Zun'watha''' ist ein Dorf der [[Trolle der Bleichborken]].",},
			["Hippogryphe"] = { content = "#REDIRECT [[Hippogryphen]]", redirect = "Hippogryphen",},
			["Hippogryphen"] = { content = "Hippogryphen sind uralte magische Tiere, deren Körper sowohl [[Hirsch]]en als auch [[Rabe]]n gleichen und deren Geister loyal und unerschütterlich sind. Sie ziehen am Himmel über [[Kalimdor]] ihre Bahnen und greifen jeden Feind der Wildnis, dem sie begegnen, brutal an. Die intelligenten Hippogryphen haben sich zu Ehren des Halbgottes [[Cenarius]], der als Beschützer der Natur und all ihrer Geschöpfe gilt, mit den [[Nachtelfen]] verbündet und sind seit vielen Jahren die treuen Gefährten der [[Nachtelfen]]. Ein [[Hippogryphenjunges]] ist ein sehr wertvoller [[:Kategorie:Gefährte|Gefährte]].\r\n==Hippogryphen als Reittiere==\r\nUrsprünglich waren es nur die [[Nachtelfen Bogenschützin]]nen der, die in der Hitze des Gefechts während des Krieges gegen die [[Untote]]n die mächtigen Hippogryphen rufen und sich mit ihnen in die Lüfte schwingen konnten. Die [[Bogenschützin]]nen, die auf den fliegenden Tieren ritten, konnten ihre Pfeile vom Rücken der Hippogryphen abfeuern und die tapferen Geschöpfe reagieren auf die Reiterinnen, als wären sie durch ein empathisches Band mit ihnen verbunden. Heute bringen diese stolzen Tiere gegen eine geringe Gebühr auch die Verbündeten der [[Nachtelfen]] durch ganz [[Kalimdor]] und [[Azeroth]].\r\nReithippogryphen sind sehr schnelle Reittiere und benötigen Reiten (300), Stufe 70 und einen Ehrfürchtigen Ruf bei der [[Expedition des Cenarius]]. So ein Reittier kann nur in der [[Scherbenwelt]] beschworen werden und wird von [[Fedryen Flinkspeer]], dem Rüstmeister der [[Expedition des Cenarius]], im [[Posten des Cenarius]] in den [[Zangarmarschen]] verkauft.\r\n* '''Cenarischer Kriegshippogryph'''",},
			["Hippogryphenjunges"] = { content = "#REDIRECT [[Hippogryphen]]", redirect = "Hippogryphen",},
			["Hir'eek"] = { content = "Hir'eek ist ein von den [[Trolle]]n verehrter Fledermaus-Gott und gilt als einer der trollischen Hauptgötter. \r\n==Interpretationsmaterial==\r\n* [[Hi'reek (Anduri Stamm)]]",},
			["Hiri'watha"] = { content = "'''Hiri'watha''' ist ein Dorf der [[Trolle der Bleichborken]] im [[Hinterland]]. Hier finden sich auch einige Giftflaschen der Bleichborken, die ein übles grünes Gift enthalten und für die sich [[Apotheker Ly]]don in [[Tarrens Mühle]] interessiert.",},
			["Hirschhaupts Stätte"] = { content = "An '''Hirschhaupts Stätte''' in [[Silithus]] war es, vor fast 1000 Jahren, als die [[Qiraji]] ihren Marsch der Zerstörung, der sich über ganz [[Kalimdor]] erstrecken sollte, begannen. Tausende verloren ihr Leben in dem Krieg, aber hier, in dieser verfluchten Wüste, während der ersten Invasion, starben die meisten der tapferen Krieger. [[Ralo'shan die ewige Wächterin]] ist eine der wenigen Überlebenden, die ihr Dasein hier angekettet an die Vergangenheit und die Gegenwart gleichzeitig fristen muss. Sie weiß nicht warum sie hier noch stationiert ist, aber sie hält sich an ihre Anweisungen.\r\nRalo'shan wurde schon hunderte Male getötet. doch wacht sie immer wieder hier an dieser Stätte auf, lebendig. Einige behaupten, sie sei verflucht, andere jedoch sagen, sie sei gesegnet: Ein Herold, um eine neue Ära anzukündigen. \r\nUralte Mächte erwachen - Mächte die seit Tausenden von Jahren geschlafen haben. Die Welt wurde ins Angst und Schrecken versetzt. Eine neue Trennung ist zu befürchten, eine Seuche, die aus der Tiefe geboren werden wird... Das Verderben hat sich bereits in den Ländern von Kalimdor verbreitet. Des Nachts werden aus Träumen Alpträume, Alpträume, die die Sterblichen am Tage vergiften werden...",},
			["Historiker Karnik"] = { content = "Historiker Karnik aus [[Eisenschmiede]] ist der Leiter der historischen Abteilung in der Halle der Forscher. \r\nEr ist ein Freund von [[Hammerzeh Grez]] aus [[Hammerzehs Grabungsstätte]] im [[Ödland]] und glaubt nach dessen Entführung, dass [[Berater Belgrum]] etwas weiß, das helfen könnte, die Aktivitäten der [[Zwerge der Schattenschmiede]] im [[Ödland]] zu unterbinden. Die [[Zwerge]] der [[Forscherliga]] haben bereits einen enormen Verlust erlitten, aber in letzter Zeit hat sich die Lage offensichtlich noch verschlimmert. Deshalb will er, dass man [[Botschafter Infernus]] in der [[Festung Angor]] im [[Ödland]] tötet und [[Berater Belgrum]] in [[Eisenschmiede]] einen Beweis seines Todes bringt.\r\nVon den geborgenen Relikten aus [[Uldaman]] interessiert er sich besonders für die Mininaturausgaben der [[Scheiben von Norgannon]] und würde gerne sehen, was passiert ... Er möchte deshalb, dass man die Miniaturplatinscheiben zu den Toren von [[Uldum]] in [[Tanaris]] bringt und nach Hinweisen auf die Verbindung zwischen beidem sucht. Allerdings ist er sich nicht ganz sicher, was dann passieren wird. \r\nSie scheinen mit ihren Forschungen bezüglich des Erbes der [[Titanen]] derzeit in einer temporären Sackgasse zu stecken. Sie brauchen die [[Platten von Uldum]], aber sie haben keinen Schimmer, wo diese sein könnten. Sie müssen eine Menge Nachforschungen anstellen, um einen guten Einsatzplan zusammenzustellen. Er wird sich deshalb mit [[Hochforscher Magellas]] beraten und einen Teil seiner Bürde an [[Magier Tymor]] in [[Eisenschmiede]] weitergeben.",},
			["Hitah'ya die Bewahrerin"] = { content = "'''Hitah'ya die Bewahrerin''' ist die Schlüsselmeisterin der [[Trolle der Blutfratzen]] und hält sich in einer Höhle in [[Jintha'Alor]] im [[Hinterland]] auf. Sie wird äußerst gut bewacht.",},
			["Hochelf"] = { content = "#REDIRECT [[Hochelfen]]", redirect = "Hochelfen",},
			["Hochelfen"] = { content = "==== Hochelfen====\r\n* Auch bekannt als: Quel'dorei\r\n* Einzahl: Hochelf, Quel'dorei\r\n* Muttersprache: [[Thalassisch]]\r\nVor langer Zeit erhob sich eine Kaste des [[Nachtelfen]]adels über den Rest des Volkes; man kannte sie unter dem Namen [[Hochgeborene]]. Ihr rücksichtsloser Missbrauch der [[Magie]] in dem königlichen Palast von [[Azshara|Zin-Azshari]] erregte die Aufmerksamkeit von [[Sargeras]], der die arroganten [[Hochgeborene]]n mit Leichtigkeit korrumpieren konnte. Dem Willen des mächtigen dunklen [[Titanen]] unterworfen, halfen die [[Hochgeborene]]n des Palastes der [[Brennende Legion|Brennenden Legion]] bei ihrer Invasion von [[Azeroth]]. Zahllose [[Nachtelfen]] und andere Geschöpfe starben im daraus resultierenden Krieg der Urtume.\r\nEinige [[Hochgeborene]] des Palastes bereuten ihre Wahl, der [[Brennende Legion|Legion]] zu helfen und flohen, angeführt von [[Dath'Remar|Dath'Remar Sonnenwanderer]], aus [[Azshara|Zin-Azshari]] vor der Teilung. Später erreichten die Spannungen zwischen den Flüchtlingen und den anderen [[Nachtelfen]] ihren Höhepunkt, als [[Dath'Remar]] und seine Anhänger der arkanen Magie nicht abschwören wollten. Sie waren sich sicher, dass die arkane Magie gefahrlos genutzt werden konnte und waren der Meinung, dass die anderen [[Nachtelfen]] weder das Recht noch das Wissen hatten das Gegenteil zu behaupten. Dazu verurteilt im Exil zu leben, freuten sich die [[Hochgeborene]]n über das Meer nach [[Lordaeron]] reisen zu können, wo sie sich eine Heimat aufbauen wollten.\r\n===Die Gründung von [[Quel'Thalas]]===\r\nMit der Zeit entwickelten die [[Hochgeborene]]n markante Unterschiede zu den [[Nachtelfen]]. Von dem neuen [[Brunnen der Ewigkeit]] getrennt, wurden sie kleiner und ihre Haut verlor den charakteristischen lila Farbton. Außerdem verloren die Elfen ihren Widerstand gegen Verletzungen und Krankheit und wurden sterblich. Viele der Elfen starben durch die Belastungen oder verhungerten während der langen Reise. Zusätzlich waren die Elfen gezwungen aus ihrer ersten Siedlung wieder zu fliehen, da dort ein mysteriöser böser Einfluss viele von ihnen verrückt machte.\r\nAls sie weiter ins Landesinnere vordrangen, begannen sie eine Blutfehde mit den gerissenen [[Waldtrolle]] von [[Zul'Aman]], die einen Großteil des Nordens von [[Lordaeron]] hielten. Schließlich erreichten die vertriebenen Elfen eine Region deren Wälder sie an ihre ferne Heimat in [[Kalimdor]] erinnerte. Sie vertrieben die dort ansässigen [[Trolle]] der [[Amani]], gründeten das Königreich von [[Quel'Thalas]] und nannten sich fortan Hochelfen. Sie krönten mit [[Dath'Remar]] ihren ersten Monarchen.\r\nTrotz der Mühen, die sie erdulden mussten, waren die Hochelfen entschlossen mit ihrer Zauberei fortzufahren, denn sie betrachten die arkanen Mächte als ihr Geburtsrecht. Mit einer Phiole heiligen Wassers, welches sie aus dem ersten [[Brunnen der Ewigkeit]] gestohlenen hatten, erschufen sie eine Quelle mystischer Kraft nahe eines mächtigen Weidelandes der Energie in [[Quel'Thalas]]. Diesen Brunnen nannten sie: => '''[[Sonnenbrunnen]]'''. \r\n===Die Trollkriege: Verteidigung von [[Quel'Thalas]]===\r\nSchon bald merkten die Hochelfen, dass die [[Trolle]] sich nicht so schnell geschlagen geben würden. Immerhin hatten die Waldtrolle mehrere Jahrtausende einen Großteil von [[Lordaeron]] besetzt, bevor die Hochelfen auf den Kontinent kamen. Fast sofort nachdem die Hochelfen [[Quel'Thalas]] gründeten begannen massenhafte Angriffe der [[Trolle]] auf die Elfensiedlungen. Die dickköpfigen Elfen waren nicht bereit, ihr neues Land schon wieder aufzugeben. Sie kämpften hart und besiegten schließlich die [[Trolle]].\r\nDer Friede, der nun folgte, dauerte mehrere Jahrtausende. Dann tauchte eine gewaltige Trollarmee auf und belagerte [[Quel'Thalas]]. Die [[Trolle]] waren wieder zu Kräften gekommen, und sie wollten die elfischen Eindringlinge ein für alle Mal vernichten. Die [[Trolle]] waren in der Überzahl.\r\nIn seiner Verzweiflung wandte sich König Anasterian Sonnenwanderer an das [[Menschen]]reich [[Arathi-Hochland|Arathor]]. Die Hochelfen boten den [[Menschen]] an, einige von ihnen im Gebrauch der [[Magie]] zu unterweisen, wenn die [[Menschen]] dafür ihren neuen Kräfte zur Verteidigung von [[Quel'Thalas]] einsetzen würden. [[Arathi-Hochland|Arathor]]s König Thoradin misstraute der [[Magie]], doch die Hochelfen warnten den König: Wenn [[Quel'Thalas]] fiele, würden die [[Trolle]] als nächstes mit Sicherheit in den Südlanden einfallen.\r\nThoradin konnte nicht leugnen, dass die Elfen mit ihrer Warnung Recht hatten. Er nahm ihr Angebot an und schickte seine Armeen an die Front. Zusammen errangen [[Menschen]] und Hochelfen schließlich den Sieg über die [[Trolle]], die sich von dieser Niederlage niemals wieder völlig erholen sollten. Als sie sahen, dass [[Quel'Thalas]] vor der Vernichtung bewahrt war, leisteten die Elfen dem Reich [[Arathi-Hochland|Arathor]] und dem Königshaus von Thoradin einen Loyalitäts- und Freundschaftsschwur. Aufgrund der Allianz zwischen [[Arathi-Hochland|Arathor]] und [[Quel'Thalas]] wurde die Zauberernation [[Dalaran]] gegründet, wo [[Menschen]] und Elfen mehr als zweitausend Jahre lang in Frieden und Eintracht nebeneinander die Magie studierten.\r\n===Der Zweite Krieg: Allianz und Sezession===\r\nAls die [[Horde]] im Zweiten Krieg die [[Menschen]] angriff, hatten die Hochelfen eigentlich wenig Interesse, in diesen Konflikt hineingezogen zu werden. Doch sie fühlten sich an ihren Schwur gebunden, die [[Allianz]] von [[Lordaeron]] zu unterstützen, und besonders ihren Kommandeur, Lord Anduin Lothar, den letzten Nachkommen von König Thoradin. Lothars Familie hatte den Hochelfen in den Trollkriegen zur Seite gestanden, und so schickte König Anasterian widerstrebend einen Trupp Soldaten und Zauberer, die an der Seite der [[Allianz]] kämpfen sollte.\r\nDie [[Horde]] rekrutierte die [[Trolle]] der Amani und kurz darauf steckte die [[Horde]] die Grenzgebiete zu [[Quel'Thalas]] in Brand und metzelte viele Zivilisten der Hochelfen nieder. Voller Zorn über diese mutwillige Vernichtung von Leben haben sich die Elfen offiziell der [[Allianz]] angeschlossen und alle ihre Ressourcen dem Krieg gewidmet.\r\nMittlerweile wurde die [[Horde]] zurückgeschlagen. Die [[Orcs]] und [[Trolle]] jedoch haben ihr wahres Ziel bereits erreicht: so viele Runensteine des Verteidigungsschildes der Elfen zu stehlen und zu entweihen wie nötig. Der [[Hexenmeister]] Gul'dan setzte dann diese entwendeten Steine ein, um seinen verschlagenen Altar der Stürme anzutreiben.\r\nTrotzdem gewann die [[Allianz]] letzendlich den Zweiten Krieg und ein Großteil der besiegten [[Orcs]] wurden zusammentrieben und in Internierungslager eingeschlossen. In der Zeit nach dem Krieg waren die Kosten für den Wiederaufbau sehr hoch, vor allem, da der Betrieb der Internierungslager finanziert werden musste. Ohne einen gemeinsamen Feind stritten die Nationen der [[Menschen]] sich über Gebiete und die Hochelfen zweifelten an dem Wert dieser [[Allianz]]. Die [[Menschen|Menschheit]] schien die Hochelfen zu brauchen, sie hatten allerdings keinen Gegenwert zu bieten, da viele der Ressourcen der [[Allianz]] in den Betrieb der Internierungslager gesteckt werden musste.\r\nSchließlich sagte sich Anasterian von der [[Allianz]] los. Er machte die schwache Führung der [[Menschen]] direkt verantwortlich für die niedergebrannten Wälder im Grenzland von [[Quel'Thalas]]. König Terenas Menethil hielt dagegen, dass überhaupt nichts in [[Quel'Thalas]] überlebt hätte ohne die Hunderte tapferer [[Menschen]], die ihr Leben geopfert hatten, um das Elfenland zu verteidigen. Doch trotz seiner Versucht, wieder diplomatische Beziehungen herzustellen, entschlossen sich die Elfen, sich von der zerbröckelnden [[Allianz]] zu lösen. Damit lösten sie zugleich die nachfolgende Trennung von den Reichen [[Gilneas]] und [[Arathi-Hochland|Stromgarde]] aus.\r\n===Der Dritte Krieg: Der Verlust des Sonnenbrunnens===\r\nWährend des Dritten Krieges verwüsteten Prinz Arthas Menethil und die [[Geißel]] [[Quel'Thalas]], vernichteten dabei einen Großteil der Bevölkerung und legten in ihrem Streben, den Sonnenbrunnen zu erreichen, erhebliche Teile des mächtigen Königreichs in Schutt und Asche. Doch nicht alle, die vor Arthas fielen blieben tot: der gnadenlose Prinz erhob [[Quel'Thalas]]' ersten Verteidiger, Waldläufergeneral Sylvanas Windläufer, zu einer [[Untote]]n gegen ihren Willen, um der [[Geißel]] als mächtige gequälte Banshee zu dienen.\r\nAls die [[Untote]]narmeen sich dem Sonnenbrunnen näherten hielt ein Hochelf namens Dar'Khan Drathir Arthas an, indem er die Schilde um den Sonnenbrunnen deaktivierte. Dar'Khan verriet die Hochelfen und hoffte dadurch die Gunst des Lichkönigs zu erlangen. Das unmittelbare Ergebnis seines Verats war jedoch eine Explosion, die ihn bewusstlos schlug und einen Großteil der Macht des Sonnenbrunnens zerstreute.\r\nDer [[Magier|Zauberer]] Borel spührte eine mystische Energie freiwerden und es gelang ihm, einen Teil davon in einer Figur, die als junges [[Menschen|menschliches]] Mädchen namens Anveena verkleidet war, einzuschließen. Ohne Borels Taten bemerkt zu haben, nutzte Arthas die verbliebenen Energien des Sonnenbrunnens, um den Geist von Kel'Thuzad in Form eines schauerlichen Lichs wieder auferstehen zu lassen. Der Sonnenbrunnen blieb besudelt und seiner Energie entzogen zurück.\r\nKönig Anasterian fiel im Kampf und der einzige Tronerbe, Prinz Kael'thas Sonnenwanderer, war zur Zeit der Invasion in Dalaran beim Studium der Magie. Ohne einen Anführer übernahm Lor'themar Theron, Sylvanas Windläufers rechte Hand, vorübergehend die Führung der Hochelfen.\r\nDie wenigen Hochelfen, die die Invasion der [[Geißel]] überlebt hatten, wurden schnell krank und apathisch. Es wurde sehr schnell klar, dass sie süchtig nach den arkanen Energien des Sonnenbrunnens waren. Ständig von der [[Magie]] bedeckt zu sein hatte ihr [[:Kategorie:Volk|Volk]] grundlegend geändert und da die Quelle dieser [[Magie]] nun nicht mehr existierte, erlitten sie heftige Entzugserscheinungen.\r\nPrinz Kael'thas kehrte in seine Heimat zurück und sammelte die Überlebenden, die er finden konnte: 90% der hinterbliebenen Hochelfen. Er erklärte, dass diese Überlebenden nun einen neuen Namen tragen würden - die [[Blutelfen]] -, um die Gefallenen zu ehren. Die [[Blutelfen]] betrachten sich selbst nicht mehr als Hochelfen und sie haben andere Ziele und Verhaltensweisen als ihre Hochelfen-Verwandten.\r\nAls Folge dieser Ereignisse gibt es heute nur noch so wenige Hochelfen auf [[Azeroth]], dass man nicht mehr wirklich von einem [[:Kategorie:Volk|Volk]] sprechen kann, außer im rein biologischen Sinne. Hochelfen versammeln sich nirgends in größerer Zahl, noch handeln sie jemals koordiniert als [[:Kategorie:Volk|Volk]]. Sie sind nur noch eine kleine Gruppe von Individuen, die über die ganze Welt verstreut ist, ohne gemeinsames Ziel oder einheitliche Meinung. Man kann von den modernen Hochelfen nicht einmal mehr sagen, sie hätten eine Kultur - nur eine Vergangenheit, ruhmreich und voller Bedauern.\r\nWie auch die [[Blutelfen]], können die Hochelfen arkane Magie nutzen, allerdings sind viele Hochelfen keine Zauberer. Ob sie nun [[Magier]] sind oder nicht, alle Hochelfen leiden an akutem Entzug, wenn sie von den Energien des Sonnenbrunnens abgeschnitten sind. Einige Hochelfen haben den Grund für ihr Leiden erkannt, andere nicht. Der wichtige Unterschied zwischen Hoch- und [[Blutelfen]] ist, dass kein Hochelf jemals den tragischen Entschluss gefasst hat, seinen Hunger nach arkaner [[Magie]] dadurch zu stillen, dass er diese [[Magie]] Gegenständen und anderen Lebewesen entzieht (da der Sonnenbrunnen nun nutzlos ist). Bis heute können Hochelfen der Sucht verfallen und somit zu [[Blutelfen]] werden.\r\n===Ein Kampf ums Überleben===\r\nBei mehreren Gelegenheiten seit der Entweihung des Sonnenbrunnens hat Kael'thas öffentlich verkündet, sein [[:Kategorie:Volk|Volk]] werde sterben, wenn es keine neue [[Magie]]quelle fände. Rein technisch gesehen hat der Prinz da Unrecht. Den Berichten der obersten [[Priester]] und Heiler [[Azeroth]]s zu Folge waren die einzigen Hochelfen, die durch den Verlust des Sonnenbrunnens starben, schon sehr alt oder gebrechlich.\r\nDermaßen geringe Entzugserscheinungen könnten als Argument dafür dienen, auf die [[Magie]] völlig zu verzichten und die Konsequenzen zu ertragen. Man sagt, einige Hochelfen hätten diesen Weg auch wirklich gewählt und durch reine Willenskraft durchstanden. So unerfreulich der Vorgang auch war, sie haben ihn überlebt. Offenbar gibt es auch gewisse magische Artefakte, die diese Entzugserscheinungen lindern oder - bei ausreichender Macht - sogar völlig unterdrücken können.\r\nDas bedeutet aber nicht, dass der Entzug der [[Magie]] den [[Blutelfen]] nicht schadete. Im Gegenteil, wenn man von den Beobachtungen in der Vergangenheit ausgeht, ist ein gewisses Ausmaß an dauerhaften geistigen und körperlichen Schäden möglich.\r\nEine Handvoll [[Hochelfen]] hat sich in den letzten Jahren der [[Allianz]] angeschlossen, doch generell bleibt die [[Allianz]] den Hochelfen gegenüber bis heute eher misstrauisch. Die Sezession der Hochelfen von der [[Allianz]] während des Zweiten Krieges hat bittere Erinnerungen zurückgelassen. Außerdem sahen es die [[Nachtelfen]], die während des Dritten Krieges zur [[Allianz]] stießen, es als ihre Pflicht an, ihre neuen Alliierten vor den Hochelfen zu warnen. Die zentrale Rolle, die die Hochgeborenen beim Ausbruch des Krieges der Ahnen gespielt hatten, bildet in der Erzählung der [[Nachtelfen]] einen wesentlichen Teil der Hochelfengeschichte.\r\n'''Quelle:''' wow-europe.com",},
			["Hochexarch Turalyon"] = { content = "'''General Turalyon''' war Ehemaliger Leutnant von Lord [[Anduin Lothar]], Ritter der [[Silberhand]] und Hochgeneral in der Expedition der Allianz, die in [[Draenor]], der Heimat der [[Orcs]], einmarschiert ist. Er war der erste Ritter, der von [[Uther Lichtbringer]] zum [[Paladin]] für den Ordern der \"Ritter der [[Silberne Hand|Silbernen Hand]]“ ausgebildet wurde. Ihm zu Ehren wurde in [[Sturmwind]] eine Statue errichtet. \r\nTuralyon glaubte fest an die Notwendigkeit von Ordnung und Disziplin, und so war es auch nicht verwunderlich, dass er als General mit [[Uther Lichtbringer]] die Truppen anführen durfte. Durch eine sehr strikte militärische Disziplin erarbeitete er sich einen sowohl bei Freunden als auch bei seinen Feinden, respektablen Ruf. Turalyon kämpfte mit seinen Truppen in der Schlacht um den [[Schwarzfels]], wo der große Ritter [[Anduin Lothar]] sein Leben verlor. Dieser Verlust traf Turalyon sehr hart und er zeigte großes Bedauern, dass er Lothar nicht hat retten können. Auf [[Draenor]] half er [[Khadgar]] das [[Dunkle Portal]] zu zerstören, doch seine weitere Geschichte blieb im Dunklen und bis zur erneuten Öffnung des Dunklen Portals blieb seine Person spurlos verschwunden. Nach der Öffnung des Dunklen Portals fand man Turalyon kurzzeitig in der [[Ehrenfeste]] der [[Höllenfeuerhalbinsel]] wieder, nur um kurze Zeit später erneut zu verschwinden. \r\nTuralyon erhielt von [[Vater Malgor Devidicus]] das Buch \"[[Die Geheimnisse des Lichts]]\". Während des Feldzugs und den folgenden Jahren hat er nicht einen einzigen Tag vergessen, seinen Mannen einen Abschnitt daraus vorzulesen. Als er die anderen wieder verließ, gab er Vater Malgor das Buch zurück, damit er bis zu seiner Rückkehr darauf aufpasst. \r\nTuralyon hatte mit [[Alleria]] einen Sohn, den [[Halbelf]]en [[Arator der Erlöser|Arator den Erlöser]].\r\n'''Quellen'''",},
			["Hochexekutorin Darthalia"] = { content = "'''Hochexekutorin Darthalia''' ist eine [[Banshee]], die die Führung über das Städtchen [[Tarrens Mühle]] im [[Vorgebirge des Hügellands]] hält. Sie steht unter direktem Kommando von [[Varimathras]] und man sollte stramm stehen, wenn man mit ihr spricht. \r\nSie wurde beauftragt, den \"Kampf um das Hügelland\" zu führen und der menschlichen Plage Einhalt zu gebieten, bis ihre [[Apotheker]] eine neue Pest entwickeln können. Auf ihrer Kopfliste stehen dabei auch [[Bauer Ray]], [[Bauer Getz]] und [[Schmied Verringtan]], denn eine der ersten Aufgaben ist darauf gerichtet, die Nahrungsversorgung und Infrastruktur zu unterbrechen, sowie die Eisenlieferungen zu unterbinden. Dazu gehört auch der geplante Tod von [[Großknecht Bonds]] und seiner Minenarbeiter. Danach sollen [[Magistrat Uferbach]] und seine Ratsherren des Hügellands getötet, das [[Stadtverzeichnis von Hügellandhof]] gestohlen und die Proklamation von Hügellandhof zerstört werden. Hochexekutorin Darthalia hat außerdem ein Kopfgeld auf [[Amtmann Horatio Weißross]], [[Bürger Wilkes]], [[Minenarbeiter Hackett]] und [[Bäuerin Kalaba]] ausgesetzt. \r\nZum anderen kümmert sie sich um das [[Syndikat]]spersonal und zahlt gut für den Kopf von [[Baron Vardus]]. Doch nicht nur mit der menschlichen Plage muss sie sich befassen ... auch die Zwerge von [[Dun Garok]] könnten der Herrschaft der [[Verlassene]]n über die [[Vorgebirge des Hügellands]] gefährlich werden und deshalb sagt sie [[Hauptmann Eisenberg]] und seinen Soldaten dort den Kampf an.",},
			["Hochforscher Magellas"] = { content = "#REDIRECT [[Hochforscher Muninn Magellas]]", redirect = "Hochforscher Muninn Magellas",},
			["Hochforscher Muninn Magellas"] = { content = "Hochforscher Muninn Magellas kann in der Bibliothek der Halle der Forscher in [[Eisenschmiede]] gefunden werden. Magellas empfand seit seiner Kindheit eine unstillbare Neugier nach dem Historischen und Arkanen und als Patron der Forscherliga ging sein Kindheitswunsch in Erfüllung. Magellas kartografierte die Welt und katalogisierte die verschiedenen Spezies, Relikte und Schätze für künftige Generationen. Zusammen mit einer kleinen Armee von Ausgrabungsleitern schickte Magellas seine Leute in die weite Welt, auf dass sie Wissen und Erkenntnis für sein Volk mehren sollten. Magellas war, genau wie König [[Magni Bronzebart]], untröstlich, als er von [[Brann Bronzebart]]s Verschwinden erfuhr. Dennoch ist er fest entschlossen, die [[Forscherliga]] weiterhin zu leiten und wertvolle Einblicke in die Fehler der Vergangenheit zu erhalten.",},
			["Hochfürst Saurfang"] = { content = "'''Hochfürst Saurfang''' ist der Bruder von [[Broxigar]] und befindet sich im Tal der Stärke in [[Orgrimmar]]. Er ist einer von [[Thrall]]s loyalsten Verbündeten, sowie der Anführer der Streitkräfte der [[Orgrimmarlegion]]. Man kennt ihn auch als Generalkommandant der Streitmacht von [[Kalimdor]] bei der Öffnung des [[Skarabäuswall]]s in [[Silithus]]. Er ist ein Ork - ein wahrer [[Orc Krieger]] - der sich nur eine Sache wünscht: im Ruhm der Schlacht gegen einen gehassten Feind zu sterben. Er ist es, der alle Verräter beobachtet. Er ist die Faust der Vergeltung, die die Widerspenstigen bezwingt. Wagt man es, sich dem Kriegshäuptling zu widersetzen? Wer wagt es, sich seinem gnadenlosen Urteil zu stellen?\r\n'''Siehe auch:'''\r\n* [[Skarabäuswall|Rede zu Öffnung des Skarabäuswalls]]",},
			["Hochgeborene"] = { content = "Die Hochgeborenen gehörten zur höchsten Adelskaste der [[Nachtelfen]] vor dem [[Krieg der Urtume]].\r\n===Die Mitglieder===\r\nAuch wenn es heute noch überlebende Hochgeborene gibt, werden sie in der modernen [[Nachtelfen]]gesellschaft nicht mehr als Adlige angesehen und praktisch hat die Kaste als solche vor über zehn Jahrtausenden aufgehört zu existieren. Alle [[Nachtelfen]], die zu den Hochgeborenen zählten, sind entweder im Krieg der Urtume gefallen oder wurden inzwischen zu [[Hochelfen]], [[Blutelfen]], [[Naga]] oder [[Satyrn]].\r\n===Geschichte und Organisation===\r\nZunächst hatte diese Kaste keinen besonderen Namen und bestand lediglich aus [[Nachtelfen]], die über ungewöhnlich viel Intelligenz, Kraft, Geschick oder Reichtum verfügten. Doch im Laufe der Zeit wuchs die Kluft zwischen ihnen und den anderen [[Nachtelfen]], besonders, als diese privilegierten [[Elfen]] anfingen zu bestimmen, wer Zugang zum Brunnen der Ewigkeit bekam und wer nicht.\r\nFamilien, die zur höchsten Kaste gehörten, arrangierten schon bald Heiraten, um die magischen Fähigkeiten ihrer Nachkommen zu maximieren. Dieses selektive Zuchtprogramm, verbunden mit dem häufigen Zugang zum Brunnen der Ewigkeit, ergab [[Nachtelfen]] mit immer stärkeren magischen Fähigkeiten und immer größerem Wissen, wie man diese Talente einsetzen konnte. Zu der Zeit, als [[Königin Azshara]] den Thron bestieg, unterschied sich die Oberklasse der [[Nachtelfen]] in Aussehen und Benehmen deutlich von den unteren Kasten.\r\nIhre ungeheure Arroganz, ihr schamloser Reichtum, ihre schreiend bunte Kleidung und ihre dekadenten Gewohnheiten machten sie nicht gerade beliebt bei den anderen [[Nachtelfen]]. Diese mächtigen Familien waren nach einiger Zeit fest davon überzeugt, dem Rest ihres [[:Kategorie:Volk|Volkes]] überlegen zu sein, und so begannen sie, sich selbst als Hochgeborene zu bezeichnen. Als Mitglied dieser Kaste gefiel der Königin diese Bezeichnung, und sie machte den Namen offiziell.\r\nWährend des [[Krieg der Urtume|Kriegs der Urtume]] wurden viele Hochgeborene von der [[brennende Legion|Brennenden Legion]] korrumpiert und in [[Satyrn]] verwandelt. Als der Krieg endete, wurde [[Kalimdor]] von der Großen Teilung zerrissen und ein neuer Ozean geboren. [[Königin Azshara|Azshara]] und viele andere Hochgeborene wurden in die Tiefen des Ozeans gerissen, viele verwandelten sich in [[Naga]].\r\nEtliche Hochgeborene sind vor der Teilung aus dem königlichen Palast geflohen und haben sich der Hauptstreitmacht der [[Nachtelfen]]verteidiger angeschlossen, auf der Flucht vor der Katastrophe endeten sie auf dem Berg [[Hyjal]]. Obwohl die Hochgeborenen erkannten, dass ihre Dummheit der [[brennende Legion|Legion]] geholfen hatte, stimmten sie der Mehrheit der [[Nachtelfen]]gesellschaft nicht zu, die beschlossen hatten, dass die arkane [[Magie]] zu gefährlich ist. Diese Hochgeborenen wurden schließlich ins Exil geschickt, da sie ihre arkanen Zaubereien nicht aufgeben wollten. Sie sagten sich von ihrem früheren [[:Kategorie:Volk|Volk]] los, gründeten später das Reich [[Quel'Thalas]] und nannten sich fortan Hochelfen. Heute gibt es nur noch sehr wenige Hochelfen auf [[Azeroth]], denn die meisten von ihnen, die die Invasion der [[Geißel]] in [[Quel'Thalas]] überlebten, benannten sich um in [[Blutelfen]].\r\nTrotz ihrer Bessenheit mit dem [[Brunnen der Ewigkeit]] lebten nicht alle Hochgeborenen in [[Zin-Azshari]]. Für eine Vielfalt an politischen und persönlichen Gründen haben bestimmte Mitglieder des Adels beschlossen außerhalb der [[:Kategorie:Hauptstadt|Hauptstadt]] zu wohnen. Zudem haben sich nicht alle Nachtelfen (oder andere [[:Kategorie:Volk|Völker]] [[Kalimdor]]s) den Hauptstreitkräften der [[Nachtelfen]]verteidiger angeschlossen. Diese Verweigerer waren nicht unbedingt gegen die Idee ihre Landsmänner zu unterstützen. Tatsächlich war es wahrscheinlicher, dass diese Zurückhaltung daher kam, dass sie noch nie etwas von den Verteidigungskräften gehört hatten und unwissend der gewaltigen Ausmaße der [[dämon]]ischen Invasion waren.\r\nDie [[Shen'dralar]] gehörten zu diesen Gruppen. Diese Hochgeborenen verteidigten während des Krieges ihre Stadt, [[Eldre'Thalas]], so gut sie konnten. Nach der Teilung blieben die [[Shen'dralar]] in ihrer verwüsteten Stadt, die seither als [[Düsterbruch]] bekannt ist. In den folgenden Jahren lebten die Hochgeborenen immer abgeschiedener von der restlichen [[Nachtelfen]]gesellschaft und so blieben ihre gefährlichen Taten vor ihren entfernten Verwandten versteckt. Sie waren niemals aus [[Kalimdor]] verbannt worden und die Shen'dralar sind niemals [[Hochelfen]] oder [[Blutelfen]] geworden.",},
			["Hochinquisitorin Weißsträhne"] = { content = "Die '''Hochinquisitorin Sally Weißsträhne''' (engl. Whitemane) ist eine [[Priester]]in des Lichtes und führt die Aktivitäten in der Kathedrale des [[Scharlachrotes Kloster|Scharlachroten Klosters]]. Sie ist eine der vier Führer des Klosters. Nach und nach verlor sie den Bezug zur Realität und mit der Zeit vertrauten Weißsträhne und ihre Anhänger niemandem mehr, der nicht Teil ihres eigenen [[Scharlachroter Kreuzzug|Scharlachroten Kreuzzuges]] war, und betrachteten sie als verseucht. Viele unschuldige Männer und Frauen wurden deswegen gequält und schließlich getötet.\r\n==Kampf==\r\nWeißsträhne ist eine Level-42-Humanoidin und ist offensichtlich sehr aufgebracht über den Tod des [[Scharlachroter Kommandant Mograine|Scharlachroten Kommandanten Mograine]]. So aufgebracht, dass sie nach kurzer Zeit die gesamte Gruppe in Schlaf versetzt und Mograine wiederbelebt. Außerdem heilt sie sich selbst wieder voll, was bedeutet, dass man es nun mit beiden Gegnern gleichzeitig zu tun bekommt. Man sollte nun unbedingt zuerst Weißsträhne töten, da sie sonst Mograine erneut wiederbelebt. Daher widmet sich die gesamte Gruppe im Kampf zunächst Weißsträhne, während ein Krieger Mograine in Schach hält. \r\n'''Quellenangaben'''",},
			["Hochinquisitor Schönufer"] = { content = "'''Hochinquisitor Schönufer''' ist ein Untotes Wesen, das verborgen in einer kleinen Kammer der Kathedrale im [[Scharlachrotes Kloster|Scharlachroten Kloster]] liegt. Diese Kammer ist nur durch das Aktivieren eines geheimen Hebels zugänglich, der als Fackel im östlichen Seitenraum der Kathedrale getarnt ist. \r\nFrüher war Hochinquisitor Schönufer der treuste Berater von [[Hochlord Mograine]]. Er sah, wie der [[Scharlachroter Kommandant Mograine|Scharlachrote Kommandant Mograine]] seinen eigenen Vater in [[Stratholme]] in eine Falle lockte und tötete. Dabei infizierte sich der Hochinquisitor mit der Seuche des Untodes. Zurück im Kloster, erzählte er die Geschichte über den Tod von [[Hochlord Mograine]] seinen Gefährten, den Scharlachroten Kreuzzüglern. Schönufer wurde dafür ermordet und vom Scharlachroten Kommandanten und seinen Anhängern in einem der geheimsten Gebiete des Klosters verborgen. Doch der Priester war nicht tot - durch die Infektion mit der Seuche existiert er als [[Untoter]] fort. Jene Kreuzzügler, die seiner Geschichte vertrauten, gründeten die [[Argentumdämmerung]]. Es ist möglich, dass er der Hochinquisitor des Klosters war, ehe [[Hochinquisitorin Weißsträhne]] das Amt übernahm.\r\n==Fähigkeiten==\r\n* '''Blutfluch''' - Blutfluch ist ein Schattenzauber, der den erlittenen körperlichen Schaden eines Feindes 2 Min. lang um 1 erhöht.\r\n* '''Heilen''' - Schönufer kann durch diesen Heiligzauber heilige Magie herbeirufen, um sich oder einen Verbündeten zu heilen. \r\n* '''Machtwort: Schild''' - Umgibt den Zaubernden mit einem Schild, der bis zu 30 Sek. lang bestehen bleibt und maximal 781 körperlichen oder magischen Schaden absorbiert. Solange der Schild hält, werden Zauber nicht durch körperliche Angriffe unterbrochen. \r\n* '''Magiebannung''' - Magiebannung bannt auf dem Ziel liegende Magie und entfernt 1 schädlichen Zauber von einem Verbündeten oder 1 nützlichen Zauber von einem Feind.",},
			["Hochlord Bolvar Drachenwill"] = { content = "#REDIRECT [[Hochlord Bolvar Fordragon]]", redirect = "Hochlord Bolvar Fordragon",},
			["Hochlord Bolvar Fordragon"] = { content = "Hochlord Bolvar Fordragon befindet sich in Burg [[Sturmwind]] und ist der Leibwächter von König [[Anduin Wrynn]].Er ist derinoffizielle Regent der Stadt, da der junge Anduin noch nicht in der Lage ist zu regieren und [[Katrana Prestor]], die königliche Ratgeberin, sich als [[Onyxia]] erwies. Er ernennt zur Verteidigung der Länder des König ab und an einen kommissarischen Stellvertreter von [[Sturmwind]], z.B. um [[Magistrat Solomon]] in [[Seenhain]] zu helfen. Er ist auch bemüht, eine Armee aufzustellen und in den [[Östliche Pestländer|östlichen Pestländern]] einen gnadenlosen Angriff auf den Waldläuferlord [[Nathanos Pestrufer]] und jeden Abschaum der [[Horde]], der ihn beschützen mag, zu beginnen, um die Ordnung wiederherzustellen.",},
			["Hochlord Darion Mograine"] = { content = "'''Hochlord Darion Mograine''' befindet sich auf der ersten Etage des Kommandopostens von [[Acherus]], der Schwarzen Festung. Er führt den Willen des [[Lichkönig]]s aus und leitet von den Hallen des Befehls aus den Angriff auf den [[Scharlachroten Kreuzzug]] in der [[Die Scharlachrote Enklave|Scharlachroten Enklave]] der [[Östlichen Pestländer]]. Und wenn der Scharlachrote Kreuzzug dort erst einmal beseitigt ist, wird er sich um die [[Argentumdämmerung]] bei der [[Kapelle des hoffnungsvollen Lichts]] kümmern. Erst wenn es ihm gelungen ist, sich von der Knechtschaft durch den [[Lichkönig]] zu lösen, werden sich die einstigen [[Todesritter]] unter dem Banner der [[Ritter der Schwarzen Klinge]] um Mograine sammeln und unter seiner Führung gegen den [[Lichkönig]] ziehen.",},
			["Hochlord Omokk"] = { content = "'''Hochlord Omokk''' ist ein [[Oger]] in der [[Untere Schwarzfelsspitze|Unteren Schwarzfelsspitze]] ([[LBRS]]). Er ist der General der [[Felsspitzoger]] und die feigen Oger des [[Schwarzfels]] sind ohne seine Führungskraft machtlos. Hochlord Omokk herrscht über die Felsspitzoger, aber das gelingt ihm nur durch Uroks Magie. [[Urok Schreckensbote]] hat Omokk mit einem Zauber belegt, der jeden Oger niederstrecken kann, der sich ihm in den Weg stellt. Omokk hat diesen Zauber schon viele Male angewandt und bewahrt die Schädel seiner Opfer hoch aufgestapelt an einem Ort der Macht oberhalb Omokks Kammer auf. Omokks Kopf wird benötigt, wenn man [[Urok Schreckensbote]] rufen möchte. Dazu muss man den Kopf an Uroks Tributhaufen auf eine beschlagene Pike spießen.",},
			["Hochmarschall Wirbelgrat"] = { content = "'''Hochmarschall Wirbelgrat''' ist eine mächtige [[Windnatter]] und repräsentiert als Fürst des [[Hoher abyssischer Rat|Hohen abyssischen Rates]] das Element der Luft. Er wird bei den großen [[Windsteine]]n in [[Silithus]] beschworen. Für die Beschwörung benötigt man ein [[Szepter der Anrufung]]: Donner, welches man aus der , einer und 20 Einheiten herstellen kann.",},
			["Hochtüftler"] = { content = "Hochtüftler ist das höchste Amt der Gnome. Jeder volljährige Gnom kann einen besonderen Gnom vorschlagen, der sich um das Volk der Gnome verdient gemacht hat.Ein Gremium der ältesten und weisesten Gnome berät dann über den Antrag und bewilligt ihn entweder oder lehnt ihn ab.Der Hochtüftler kann jedoch nach einer bestimmten Zeitspanne wieder abgewählt werden. Der jetztige Hochtüftler ist Gelbin Mekkadrill, unter desssen Regentschaft Gnomeregan in die Hände der Troggs und Lepragnome fiel.",},
			["Hochtüftler Gelbin Mekkadrill"] = { content = "'''Hochtüftler Gelbin Mekkadrill''' (engl. Mekkatorque) ist der derzeitige Anführer der [[Gnome]]. Man kann ihn im Tüftlerviertel von [[Eisenschmiede]] finden. \r\nBei den Gnomen gibt es seit über vierhundert Jahren keinen König und auch keine Königin mehr. Sie ziehen es vor, ihre höchsten Staatsdiener für eine befristete Amtszeit zu wählen. Das höchste Amt in [[Gnomeregan]], [[Hochtüftler]], hat seit sieben Jahren der mit allen Wassern gewaschene Gelbin Mekkadrill inne. Gelbin zählt zu den berühmtesten Erfindern aller Zeiten und wird als gleichermaßen geschickter Anführer geehrt. Als jedoch die [[Troggs]] ihre Invasion von Gnomeregan begannen, war Gelbin auf eine solche Situation nicht vorbereitet. Auf Drängen von [[Robogenieur Thermadraht]], seinem obersten Ratgeber, ließ er die Stadt mit toxischer Strahlung fluten. Die Strahlung brachte das Vorrücken der Invasoren zwar zum Stillstand, tötete letztendlich aber mehr Gnome als Troggs. Nun trägt der [[Hochtüftler]] die Last der Toten auf den Schultern und sucht Rache für sein Volk, indem er die verlorene Stadt zurückerobern will.",},
			["Hochtüftler Mekkadrill"] = { content = "#REDIRECT [[Hochtüftler Gelbin Mekkadrill]]", redirect = "Hochtüftler Gelbin Mekkadrill",},
			["Hochwipfeltal"] = { content = "Um ins Hochwipfeltal zwischen dem [[Brachland]] und dem [[Steinkrallengebirge]] zu gelangen, folgt man einfach der Straße westlich aus der Siedlung des [[Wegekreuz]]es im [[Brachland]]. \r\nZwischen einigen stark verfallenen [[Nachtelfen]]-Ruinen findet man und .\r\n==Personen==\r\n* '''Makaba Flachhuf''' - Makaba Flachhuf ist die Mutter von [[Kaya]] und möchte, dass man [[Camp Aparaje]] rächt. Sie hat so viele der [[Tauren der Grimmtotem]] wie sie konnte dort niedergestreckt, ist aber nur um Haaresbreite lebend entkommen. Jetzt wünscht sie sich nichts mehr, als noch mehr von ihnen tot zu sehen. \r\n* '''Seereth Bruchstein''' - Seereth Bruchstein ist eine aufstrebende Schamanin der [[Horde]] und wurde in das [[Steinkrallengebirge]] geschickt. Sie berichtet von umfangreichen Rodungen durch die [[Goblins]] dort und bittet um Hilfe.",},
			["Hochwolkenebene"] = { content = "Die [[Tauren]] oben auf der Hochwolkenebene im südlichen [[Mulgore]] sind stolz auf ihre hervorragenden Jagdfertigkeiten. Deshalb haben die [[Tauren des Falkenwindklans]] hier in der Wildtier-reichen Mesa ihr Lager, das [[Camp Narache]], errichtet. \r\n==Personen==\r\n* '''Antur Falb''' - Antur Falb hat seine Aufgaben hier auf der Mesa noch nicht beendet – er ist mitten in seinem Ritual der Kraft - und sein Vater bat ihn, ein Bündel Felle im Gasthaus im [[Dorf der Bluthufe]] abzuliefern. Doch er ist längst nicht erholt genug, sein Ritual und diese Aufgabe für seinen Vater zu beenden und braucht Hilfe.",},
			["Hof der Steinfelds"] = { content = "Der Hof der Steinfelds liegt Hof östlich vom Waldrand im Wald von Elwynn. Hier lebt die Familie Steinfeld, welche mit der Familie Maclure in den [[Weinberge der Maclure|Weinbergen der Maclures]] verfeindet ist. \r\n==Personen==\r\nDie Familie Steinfeld besteht aus folgenden Mitgliedern:\r\n* '''Bernice Steinfeld''' - Bernice Steinfeld ist eine alte Witwe, die tolle Schweinebauchpasteten macht. Sie hat allerdings ihre Halskette verloren und glaubt, dieser Tunichtgut [[Billy Maclure]] in den Weinbergen der Maclures hat sie genommen.) \r\n* '''Homer Steinfeld''' - Homer Steinfeld ist Obstverkäufer.\r\n* '''Mutter Steinfeld''' - Mutter Steinfeld würde das preisgekrönte Schwein „Prinzessin“ auf [[Brackbrunns Kürbisbeet]] gerne tot sehen.\r\n* '''Oma Steinfeld''' - Oma Steinfeld ist für ihren Einfallsreichtum bekannt. Wenn irgendjemand einen Weg weiß, wie [[Tommy Joe Steinfeld]] mit [[Maybell Maclure]] zusammen sein kann, dann ist sie das.\r\n* '''Tommy Joe Steinfeld''' - Tommy Joe Steinfeld hält sich normalerweise hält er sich am Fluss im Westen des Hofs auf und würde gerne mit [[Maybell Maclure]] zusammenkommen.",},
			["Hogger"] = { content = "'''Hogger''' ist der Führer der [[Gnolle der Flusspfoten]] und wahrscheinlich der bekannteste Vertreter seiner Rasse auf [[Azeroth]]. Er ist ein riesiger Gnoll und streunt im Südwesten von [[Wald von Elwynn|Elwynn]] durch den Wald, direkt vor dem Fluss der [[Westfall]] von Elwynn trennt. Er hat bislang alle Versuche, ihn zu fangen, vereiteln können und die Armee von [[Sturmwind]] hat inzwischen ein großzügiges Kopfgeld auf den Gnoll ausgesetzt. Kopfgeldjäger, die sich die Belohnung verdienen möchten, sollten einen Beweis für Hoggers Tod bei [[Marschall Dughan]] in [[Goldhain]] vorlegen.",},
			["Hohepriesterin Arlokk"] = { content = "'''Hohepriesterin Arlokk''' befindet sich in [[Zul'Gurub]] und verkörpert [[Bethekk]], den Aspekt des Panther.\r\n==Kampf==\r\nSobald der Gong am Ende des Raumes geschlagen wird, ist der Eingang versiegelt und niemand kann mehr hinaus. Dabei ist es egal, wer den Gong schlägt. Die Gruppe steht neben dem Eingang, dicht an der Wand. Arlokk spawnt in der Nähe davon und geht sofort auf ein beliebiges Ziel los. Der Haupt-Tank sollte hier so schnell es geht spotten und sie in die Mitte des Raums ziehen. Bereits jetzt beginnt das spawnen der Panther. Sobald der erste Spieler markiert ist, geht dieser in die Mitte des Raums, so dass jeder Panther zu ihm rennt, statt zur Gruppe. Der markierte Spieler muss überleben, da sonst die Panther unkontrolliert herum laufen und Verwirrung in den Kampf bringen. Zusätzlich machen sie natürlich Schaden, der bei der Masse nicht unerheblich ist. Sobald ein zweiter Spieler markiert wird, muss beachtet werden, welche Klassen betroffen sind. Der zweite Markierte (mit den schlechteren Rüstungswerten) geht ganz nah an die Wand neben dem Eingang, so dass kein Panther auf ihn aufmerksam wird. Wenn Arlokk verschwindet, wird die Panthermasse weggebombt. Kurz bevor sie wieder auftaucht, sollten sich alle Priester ein Schild geben, da sie meist zuerst zu Vertretern dieser Klasse rennt. Wenn sie wieder da ist, wird bis zur nächsten Tarnung weiter Schaden verursacht. \r\n* '''Jägermal''' - Arlokk kennzeichnet 1-2 Spieler mit einem Jägermal, wobei hier nur Manaklassen betroffen sind. Wenn jemand mit einem Mal zu nahe an die Panther kommt, wird er automatisch von diesen angegriffen.\r\n* '''Panther''' - Während des gesamten Kampfes spawnen immer wieder Panther.\r\n* '''Tarnung''' - Arlokk geht bereits kurz nachdem die Gruppe angegriffen hat in die erste Tarnung. Sie ist dann für niemanden sichtbar und angreifbar.",},
			["Hohepriesterin Ishanah"] = { content = "'''Ishanah''' ist die Hohepriesterin der Aldor im Schrein des unendlichen Lichtes in [[Shattrath]].\r\n===Das Licht wiederherstellen===\r\nVor langer Zeit war ein Großteil des Gebiets um Shattrath von den Draenei bewohnt. Ishanah und die Aldor, hatten den Auftrag, ihre heiligen Stätten und Altare zu beschützen. Doch seitdem wurden viele davon zerstört oder von ihren Feinden eingenommen. Östlich von Shattrath gibt es einen Außenposten der [[Arakkoa]]. Die Vogelmenschen haben ihn mit voller Absicht auf dem Gebiet errichtet, auf dem drei der heiligen Altare stehen. Die Arakkoa haben ihre üble Magie benutzt, um die ureigene Macht der Schreine zu verändern und zu schänden. Doch die Aldor sind die Hüter des Lichts und können ihre Pflichten nicht vernachlässigen. Nicht einmal in den schwersten Zeiten. Ishanah möchte, dass man deshalb zum Arakkoaaußenposten östlich von Shattrath geht und die gesegnete Phiole benutzt, um den östlichen Altar, den westlichen Altar und den nördlichen Altar zu reinigen. \r\n===Ein reinigendes Licht===\r\nDer Schrein des unendlichen Lichtes ist eine der heiligsten Stätten der ganzen [[Scherbenwelt]]. Die Macht des Lichts ist hier so stark, dass es weltliche Gegenstände sogar von der schlimmsten teuflischen Verderbnis befreien kann. Falls man bei seinen Kämpfen mit den dämonischen Feinden teuflische Waffen finden sollte, kann man sie zu Ishanah bringen. Dann wird sie den Anhängern der Aldor die reinigende Kraft des Lichts beweisen. Sie können zuschauen, wie die verderbten Materialien sich auflösen. Sie können zuschauen, wie sich Metall in Staub verwandelt. Das Licht reinigt alles, und nur die reinsten Überreste bleiben. Ein reinigendes Licht.",},
			["Hohepriesterin Jeklik"] = { content = "'''Hohepriesterin Jeklik''' befindet sich in [[Zul'Gurub]] und verkörpert [[Hir'eek]], den Fledermaus-Aspekt.\r\n==Kampf==\r\nHohepriesterin Jeklik sorgt für das erste Boss-Gefecht in Zul'Gurub und ist recht einfach zu entsorgen. Der Kampf ist in zwei Phasen aufgeteilt. In Phase 1 befindet sich Jeklik in der Fledermausgestalt, in der sie auch gepullt wird. Dazu geht der Haupt-Tank an Jeklik heran und schießt sie von der Plattform. Nun muss er sich direkt umdrehen und an die gegenüberliegende Wand laufen. Wichtig ist, dass während des Pull-Vorgangs kein Schaden und keine Heilung getätigt wird, da Jeklik sich sonst dem Rest der Schlachtgruppe zuwenden könnte. \r\nDie anderen Spieler stehen an dem rechten Baum und warten, bis Jeklik an ihrer Position ist, damit der erste \"Stille\"-Zauber nicht direkt auf die Heiler geht. Sobald sie an der Tank-Position angekommen ist, bewegt sich die Schlachtgruppe Richtung Mitte und nach kurzer Antankpause wird Schaden verursacht. Sämtliche Fernkampfklassen sollten hier wegen der drohenden Stille Abstand halten. In Phase eins macht Jeklik außerdem einen willkürlichen Ansturm, kehrt dann aber im Normalfall direkt zum Haupt-Tank zurück. Sobald die Fledermäuse aus der Höhle hinter ihrem Podest kommen, müssen diese von einem Krieger kurz abgelenkt und dann von Magiern und Hexenmeistern magisch bebombt werden. Dies geschieht dreimal, bei einer guten Gruppe ein- bis zweimal. Wenn Jeklik 50 % ihrer Lebensenergie erreicht, verwandelt sie sich in einen Troll zurück und Phase zwei beginnt.\r\nIn Phase 2 bewegt sich die Schlachtgruppe um den Baum in der Mitte herum, um nicht von den Bomben getroffen zu werden. Sobald sich Jeklik heilen möchte, wird dies im Chat-Fenster angekündigt. Dann muss sie sofort unterbrochen werden, da sie sich sonst um bis zu 50 % ihrer Lebensenergie heilt. Ansonsten gilt es, hier konstant Schaden zu verursachen.",},
			["Hohepriesterin Mar'li"] = { content = "'''Hohepriesterin Mar'li''' befindet sich in [[Zul'Gurub]] und war die Hohepriesterin der Urgöttin [[Shadra]], des Spinnen-Aspektes.\r\n==Kampf==\r\nHohepriesterin Mar'li ist die erste Herausforderung, welche von allen Spielern hohe Konzentration erfordert. Sie hat die beiden Gestalten Troll und Spinne, wechselt jedoch mehrmals im Kampf. Die Gruppe stellt sich für den Kampf auf den Haufen vor Mar’li, sobald der gesamte Bereich von den Spinnengruppen befreit ist. Vor Mar’li selber ist nun noch ein Sprecher, der von einem Krieger getankt wird, während der Haupt-Tank Mar’li selber beschäftigt. Wenn die Tanks angreifen, spawnen rechts und links neben Mar’li Spinnen-Adds, die so schnell wie möglich getötet werden müssen. Sind diese erst einmal ausgewachsen, können sie sonst enormen Schaden verursachen. Hier ist es wichtig, dass die gesamte Gruppe sich erst die Spinnen-Adds vorknüpft, bevor sie zum Sprecher übergeht. Diese Spinnen-Adds kommen zwischenzeitlich immer wieder. \r\nEs empfiehlt sich dann die Pets der Jäger auf Aggressiv zu stellen, damit die Spinnen schnell abgelenkt werden, bevor sie auf die Heiler losgehen. Dann wie gehabt töten. Wenn der Sprecher erledigt wurde und der Main-Tank genug Aggro aufgebaut hat, kann Mar’li angegriffen werden. Wegen des Giftes, welches sie verteilt, sollte jeder Spieler (dessen Rolle dies erlaubt) möglichst weit weg stehen. Wer vergiftet wird, muss davon sofort befreit. Wenn Mar’li sich bei ca. 90 % Lebensenergie in eine Spinne verwandelt, werden alle um sie herum in ein Netz eingesponnen. Die Paladine auf Allianzseite müssen den Main-Tank dauerhaft mit dem Segen der Freiheit buffen, da er so die Chance hat, nicht von Mar’lis Netz betroffen zu werden. Dadurch behält er auch die Aggro bei sich und Mar’li rennt nicht in die Gruppe. Während der Gestaltwandlung gilt außerdem Schadensstop. Sollte der Haupt-Tank trotz alledem die Aggro verlieren, wird Mar’li in die Gruppe rennen und sich das nächste Ziel suchen. Hier gilt für die Priester \"verblassen\" und ein anderer Krieger muss spotten und sie wieder dem Haupt-Tank übergeben. Ab und an ist hier ein Seitenwechsel der Gruppe angebracht, je nachdem, wo Mar’li abgefangen werden konnte. Wenn der Haupt-Tank wieder die Aggro hat und alle in Reichweite stehen, kann weiter Schaden verursacht werden. Zu dem Einnetzen kommt der Lebensentzug, wenn sie in Trollgestalt ist. Das muss sofort dispellt werden, da sie sich dadurch schnell heilt.",},
			["Hohepriester Thekal"] = { content = "'''Hohepriester Thekal''' befindet sich in [[Zul'Gurub]] und verkörpert den Aspekt des Tigers, [[Shirvallah]]. Begleitet wird er von seinen beiden Zeloten Zath und Lor'Khan. Wie auch die anderen Hohepriester der Gurubashi unterlag er dem Blutgott [[Hakkar]] und fiel unter dessen Joch. Nun nährt er zusammen mit den anderen Aspekten der ursprünglichen Götter die ohnehin schon überwältigende Kraft des Seelenschinders. \r\nAnmerkung: Mit viel Glück kann man bei Hohepriester Thekal den [[Nachtsäbler|Schnellen zulianischen Tiger]] als seltenes Reittier finden.\r\n==Kampf==\r\nDer Kampf mit Hohepriester Thekal ist in zwei Phasen eingeteilt. Thekal selbst hat zwei Begleiter, [[Zelot Zath]] und Zelot [[Lor'Khan]]. \r\nIn Phase 1 müssen die drei Trolle so weit es geht auseinander gezogen werden, damit sie sich nicht gegenseitig heilen können. Dieses Heilen kann auch unterbrochen werden. Die Krieger gehen vor und ziehen sich ihren Add heraus. Während sie nun Aggro aufbauen, tötet der Rest der Gruppe die beiden Tiger. Wenn die Krieger angetankt haben, fängt die Schlachtgruppe damit an, Schaden bei Zelot Zath zu verursachen. Ist seine Lebensenergie auf ca. 10 % reduziert, muss ein Schadensstop erfolgen, da er nicht alleine sterben darf. Hier sollte auf DoT-Effekte geachtet werden, die vielleicht weiter laufen. Dann wendet sich die Schlachtgruppe Thekal zu. Auch dieser wird auf ca. 10 % Lebensenergie gebracht. Zu guter letzt noch Zelot Lor'Khan vorknöpfen. Wenn alle drei Gegner auf etwa 10 % ihrer Lebensenergie runter sind, werden sie in der Mitte zusammengezogen und gebombt. Wenn die drei Trolle nicht innerhalb einer Zeitspanne von 10 Sekunden sterben, stehen sie wieder auf. Nun verwandelt sich Thekal in einen Tiger. \r\nSobald Thekal zum Tiger geworden ist, beginnt Phase 2 und es wird ein Aggro-Reset durchgeführt. Die gesamte Gruppe sollte sich von der Leiche des Trolls entfernen, damit die Aufmerksamkeit direkt auf den Haupt-Tank übergeht. Außerdem ist es sinnvoll, sich mit dem Rücken an eine Wand zu stellen, damit man beim Rückstoß nicht allzu weit fliegt. Nach der Antankzeit beginnt die Schlachtgruppe mit Schaden auf Thekal. Hierbei sollten zwei Krieger Aggro aufbauen. Sobald die Tiger kommen, müssen diese getötet oder beschäftigt werden. Ganz wichtig ist es, dass kein Spieler mit dem Rücken zum offenen Torbogen steht, da dieses Gefecht neu gestartet wird, wenn man dort hinaus rennt. \r\n* '''Kampfrausch''' - Der Kampfrausch erhöht 30 Sekunden lang das Angriffstempo eines Verbündeten um 75%. \r\n* '''Machthieb''' - \r\n* '''Schnellstreich''' - Der Schnellstreich verursacht 6 Sekunden lang 438 bis 562 Schaden pro Sekunde.\r\n* '''Stille''' - Bringt einen in der Nähe befindlichen Feind zum Schweigen, sodass er 6 Sekunden lang keine Zauber wirken kann.\r\n* '''Sturmangriff''' - Stürmt auf einen Gegner zu, fügt dem Ziel normalen Schaden und betäubt den Gegner für 2 Sekunden. \r\n* '''Tödliches Spalten''' - Verursacht 150% Waffenschaden und verwundet das Ziel, verringert außerdem die Wirksamkeit jeglicher Heilung 5 Sekunden lang um 50%.\r\n* '''Wutanfall''' - Erhöht 2 Minuten lang das Angriffstempo des Zaubernden um 60% und den von ihm zugefügten körperlichen Schaden um 50.",},
			["Hohepriester Venoxis"] = { content = "'''Hohepriester Venoxis''' befindet sich in [[Zul'Gurub]] und verkörpert den Aspekt der Schlange, [[Ula'tek]]. An seinem Gift ist in neuster Zeit auch Lord Rabenholdt interessiert, der eine neue und extrem effektive Giftmischung zusammenzustellen will, die aus den Giftbeuteln der Bewohner von [[Zul'Gurub]] und den [[Ruinen von Ahn'Qiraj]] gewonnen werden kann. Dazu benötigt er Venoxis' Giftbeutel. \r\n==Kampf==\r\nHohepriester Venoxis ist die 2. Bossbegegnung in [[Zul'Gurub]] und selbst mit einer relativ schwachen Gruppe einfach zu erledigen. Auch hier ist der Kampf in 2 Phasen aufgeteilt. Venoxis kommt mit 4 Schlangen. Er bleibt anfänglich in Priesterform, wo er Heilige Nova, Heiliges Feuer und Erneuerung zaubert. Er kann ebenso Heiligen Zorn wirken. Das ist ein Zauber, der von Person zu Person springt und Schaden verursacht, der exponentiell zu den Treffern ist. 9000 Schaden pro Schlag ist dabei nicht ungewöhnlich. Später wechselt er in die Schlangenform, wo sein Nahkampfschaden dramatisch nach oben geht und er eine Gift Wolke freisetzt.",},
			["Hoher abyssischer Rat"] = { content = "Der Hohe Abyssische Rat führt den [[Abyssischer Rat|Abyssischen Rat]] und ist die treibende Kraft hinter dem [[Schattenhammer Kult]]. Einen Lord des Hohen abyssischen Rates kann nur durch einen großen [[Windsteine|Windstein]] in [[Silithus]] herbeigerufen werden und nur den höchstdekorierten Ratsmitgliedern der [[Schattenhammer Kult|Schattenhammer]] ist es erlaubt mit den Lords in Kontakt zu treten. Für die Anrufung der Lords des Hohen abyssischen Rates wird u.a. ein [[Szepter der Anrufung]] benötigt.\r\n==Persönlichkeiten==\r\n* [[Baron Kazum]] \r\n* [[Hochmarschall Wirbelgrat]] \r\n* [[Lord Skwol]]\r\n* [[Prinz Skaldrenox]]",},
			["Holzfällerlager des Kriegshymnenklans"] = { content = "Die [[Nachtelfen]] sagen, das Holzfällerlager der [[Orcs des Kriegshymnenklans]] in [[Eschental]] sei ein Schandfleck in der Landschaft. Doch wann immer die [[Nachtelfen]] Fortschritte dabei machen, die Arbeiten der [[Orcs]] zu stoppen, befiehlt [[Vorarbeiter Gorthak]] seinen Holzarbeitern, ihre Anstrengungen noch zu verdoppeln. Jetzt fällen die [[Orcs]] mehr Holz, als sie je verbrauchen können und lassen es verrotten, während ihre Klingen schon wieder in frisches Holz schlagen. Dies ist eine Beleidigung gegenüber allem, für das die [[Nachtelfen]] einstehen, und sie werden ihnen zeigen, dass sie sich eine weitere Zerstörung ihrres Landes nicht gefallen lassen.\r\nIm Holzfällerlager des [[Kriegshymnenklan]]s gehen langsam einige Dinge aus. Eine Lieferung Sägeblätter liegt noch immer bei [[Pixel]] im [[Splitterholzposten]] und jemand muss auch nach [[Beutebucht]] reisen, um eine Kiste mit Äxten bei [[Werftmeister Lozgil]] abzuholen.",},
			["Holzfällerlager des Osttals"] = { content = "Östlich des [[Steinhügelsee]]s liegt die zweitgrößte menschliche Siedlung im [[Wald von Elwynn]]. Man findet das Holzfällerlager des Osttals jenseits von Wache Thomas' Posten. Doch je weiter man sich von [[Goldhain]] entfernt, umso reizbarer sind die wilden Tiere. Das Holzfällerlager wird beinahe ständig von Wölfen und Bären angegriffen.\r\nKatie Hunter hat hier eine gut laufende [[Pferde]]zucht und verkauft: Schecke, Kastanienbraune Stute, Braunes Pferd, Schneller Brauner, Schnelles weißes Ross und Schnelles Palomino. Bei ihrem Mann Randal Hunter, kann man die entsprechende Fertigkeit im Reiten dazu erlernen.\r\n==Personen==\r\n* '''[[Marschall Haggard]]'''\r\n* '''Sara Roderwald''' rüstet die Soldaten im Dieste von [[Sturmwind]], die im [[Wald von Elwynn]] stationiert sind, mit Kleidung aus.\r\n* '''Vorsteherin Raelen''' hat hier ein echtes Problem. Sie hat einen Liefertermin für eine Bestellung Holz und ihr läuft die Zeit davon. Die Wölfe und Bären nördlich von hier haben ihre Arbeiter von den Holzbündeln verjagt, die sie bereits gefällt hatten. Sie hat bereits mit Stellvertreter Rainer darüber gesprochen, dass die Tiere entfernt werden müssen, aber sie braucht jemanden, der das Holz für sie holt.",},
			["Holzschlundfeste"] = { content = "==Allgemeines==\r\nDie Einwohner der Holzschlundfeste sind die einzigen [[Furbolgs]], die von der Verderbnis verschont blieben. Obwohl die Holzschlundfeste unterhalb der Berge von [[Mondlichtung]] im Nordwesten bis [[Azshara]] im Südosten von misstrauischen [[Furbolgs]] bewohnt wird, die jeden Fremden aggressiv angreifen, stellen die drei Tunnel mit einem zentralen Knotenpunkt die einzige Verbindung für zu Fuß reisende Abenteurer zur [[Mondlichtung]] und [[Winterquell]] dar. Um sie nutzen zu können, muss man sich zuvor den [[Furbolgs]] als vertrauenserweckend bewiesen haben. Die Verderbnis bedroht sie nicht nur in Form der [[Furbolgs der Totenwaldfelle]] vom Süden her, sondern auch durch die [[Furbolgs der Winterfelle]] im Osten. Deswegen bleiben die [[Furbolgs]] der Holzschlundfeste meist unter sich und meiden wenn möglich andere Furbolgstämme. Einen weiteren Stützpunkt besitzen sie in [[Azshara]]. \r\n===Ziele===\r\nAls der letzte unverderbte Stamm der [[Furbolgs]] möchten die Bewohner der Holzschlundfeste ihren spirituellen Lebensweg bewahren und das Leiden ihrer Artgenossen beenden. Viele andere Völker töten die [[Furbolgs]] jetzt blindwütig und scheren sich nicht darum, ob sie Freund oder Feind sind. Deswegen trauen die Furbolgs der Holzschlundfeste auch kaum jemandem. Trotz allem versuchen sie, die Wunden zu heilen, die die Verderbnis des [[Teufelswald]]s dem Land zugefügt hat, so dass die uralten Wälder eines Tages wieder von den friedvollen Gesängen und dem sanften Lachen der Kinder des Waldes erfüllt werden.\r\n===Verbündete===\r\nAbenteurer, die die Holzschlundfeste im Norden des [[Teufelswald]]s aufsuchen und sich als Freunde der dort lebenden [[Furbolgs]] erweisen, werden feststellen, dass die [[Furbolgs]] ihre Freunde mehr als alles andere schätzen. Zwar besitzen sie keine Edelsteine oder sonstige Reichtümer, doch die [[Schamanen|schamanistische]] Kultur der [[Furbolgs]] ist in der Holzschlundfeste ungebrochen. Sie wissen viel über die Kunst, wie man Rüstungen aus Tierfellen fertigt, und sie teilen gerne ihre heilenden Talismane mit Freunden des Stammes. Sie gewähren allen, die ihre Vertrauenswürdigkeit unter Beweis gestellt haben, freies Geleit. \r\n===Hochheiliger Stoff===\r\nDie Furbolgs in der Holzschlundfeste sind eigentlich ganz zufrieden und mögen keine Fremden. Das ist gut für sie, aber schlecht für das Geschäft. Es ist noch nicht lange her, da kam eine [[Nachtelfen]]freundin, die einen Runenumhang trug, auf die Holzschlundfeste. Runenstoff ist bei den Furbolgs selten, aber der Umhang war so edel, dass sie Furbolgs jetzt verlangen, mehr Runenstoffkleidung zu fertigen. Die Einwohner der Holzschlundfeste mögen das Gefühl von Runenstoff auf der Haut, aber er ist nichts Hochheiliges für sie. Mondstoff dagegen ist hochheilig. Dieser [[Mondstoff]] wird für Gewänder benutzt, die für ihr Volk hochheilig sind.\r\n==Geschichte==\r\nAls die schleichende Verderbnis der [[Brennende Legion|Brennenden Legion]] begann, die heiligen Wälder [[Kalimdor]]s zu verseuchen, waren die wilden Tiere die ersten, die von ihrer grausamen Macht ergriffen wurden. Einstmals sanfte Tiere wurden in missgestaltete, tollwütige Killer verwandelt; ihr Fleisch misshandelt und ihre Seelen entweiht, fielen sie innerhalb kürzester Zeit dem Einfluss der [[Dämonen]] anheim. Kurz darauf erlitten die [[Furbolgs]], die bärenhaften Kinder des Waldes, das selbe Schicksal, als ihr gesamtes Volk von der sie umgebenden Verderbnis in den Wahnsinn getrieben wurde. Doch inmitten des Chaos und des Wahnsinns entkam ein Stamm der Dunkelheit, die [[Kalimdor]] befallen hatte. In der sicheren Abgeschiedenheit der Holzschlundfeste überdauerten die [[Furbolgs]] des Holzschlundstammes den Sturm. Jedoch mussten sie hilflos mit ansehen, wie der Wald, den sie so sehr geliebt hatten, langsam in ein entstelltes, schwärendes Zerrbild seines früheren selbst verwandelt wurde. \r\nAls die Geister des Waldes schließlich nicht mehr auf ihre Rufe antworteten, wussten die [[Furbolgs]], dass ihre Heimat verloren war... vielleicht für immer. Die Verderbnis drang tief ein; sogar nachdem [[Illidan]] der Verräter ihre Quelle, den [[Schädel des Gul'dan]], verzehrt und den Anführer der [[Dämonen]], [[Tichondrius]] den [[Schreckenslord]], vernichtet hatte, wich der Makel nicht von den Wäldern. Nach dem Fall der [[Brennende Legion|Brennenden Legion]] haben die [[Furbolgs]] der Holzschlundfeste inzwischen ihre ersten vorsichtigen Schritte außerhalb des Schutzes ihrer Festung getan. Sie nehmen sich vor Fremden in Acht, da sie fürchten, für ihre verderbten Brüder gehalten und angegriffen zu werden. Doch die [[Furbolgs]] der Holzschlundfeste sind sich des Umstandes, dass sie auf sich alleine gestellt nicht überleben werden, schmerzhaft bewusst. \r\n==Persönlichkeiten==\r\n* [[Gorn Einauge]]\r\n* '''Grazle''' – Grazle befindet sich in der Nähe des [[Smaragdrefugium]]s im Süden des [[Teufelswald]]es und hält dort Ausschau nach neuen Verbündeten der Holzschlundfeste und wenn man den verderbten Stamm der Totenwaldfelle vom Teufelswald zurücktreibt, dann betrachten die Furbolgs der Holzschlkunfeste einen eines Tages vielleicht als Verbündeten. \r\n* [[Kernda]]\r\n* '''Meilosh''' - Meilosh kennt geheime Schneidertechniken und wenn man ihm Runenstoff bzw. Hochheiligen Mondstoff bringt, ist er bereit sein Wissen zu teilen. \r\n* '''Nafien''' - Nafien befindet sich im Norden des [[Teufelswald]]s nahe des Eingangs der Holzschlundfeste. Im ersten Augenblick mag er vielleicht wie ein ungezügeltes, wildes Tier wirken, doch man braucht ihn nicht zu fürchten. Er ist auf der Suche nach tapferen Abenteurern, die ihm im Kampf gegen die dunkle Verderbnis unterstützen, welche die Heimat bedroht. Er ist sich nicht sicher, was die [[Furbolgs der Totenwaldfelle]] vorhaben, aber er würde dem gern einen Riegel vorschieben, ehe es zum Problem wird. Es stimmt ihn jedoch zutiefst traurig, dass er gegen seine Geschwister bei den [[Furbolgs der Totenwaldfelle]], kämpfen muss.\r\n* '''Salfa''' - Man findet Salfa nahe des Eingangs nach [[Winterquell]], wo sie die Aktivität der [[Furbolgs der Winterfelle]] überwacht. In letzter Zeit ist ihr aufgefallen, dass die [[Furbolgs der Winterfelle]] ihnen gegenüber immer größere Feindseligkeit zeigt. Sie scheinen in Rage zu sein, und ganz von ihrem Hass auf alles beseelt, das sie nicht verstehen.",},
			["Hoodoo"] = { content = "'''Hoodoo, das'''\r\nBedeutung unklar.\r\nHoodoo ist im [[Trolle|Trollischen]] sowohl ein Wort für 'Abfall', als auch für eine von Aberglauben geprägte Form der vulgären Ritualmagie zur Abwehr bzw. Lenkung böser Geister oder der Seelen Verstorbener. \r\nHoodoo zeichnet sich durch uneinheitliche Symbolik und eine weite Verbreitung unter nicht-magiebegabten [[Trolle]]n aus, die Hoffnung in seine Kraft setzen. Symbole auf Türrahmen, Haufen verschiedenster Gegenstände, von Laien selbst gefertigte, angeblich zauberkräftige Schmuckstücke, fallen unter die Bezeichnung Hoodoo.",},
			["Horde"] = { content = "Die heutige '''Horde''', nicht zu verwechseln mit ihrer Vorgängerorganisation, die noch den Zielen der Brennenden Legion diente und von den unter dämonischem Einfluss stehenden Orks dominiert wurde, ist einer der zwei Machtblöcke, in die das heutige Azeroth aufgeteilt ist. Diplomatisch, militärisch und ökonomisch steht sie in einem ausgeprägten Antagonismus zur [[Allianz]]. \r\nDie heutige (neue) Horde entstand nach dem Auszug der Orks aus Lordaeron durch das Zusammentreffen von Thralls Exilantenzug mit den Trollen des Dunkelspeer-Stammes. Orks und Trollen besiegten gemeinsam die aus dem Meer aufgestiegenen Murlcos, welche das Trollvolk in seiner Existenz bedrohten. Nur kurze Zeit später leisteten Orks und Darkspear wiederum den nahezu vernichteten Tauren Hilfe gegen das Volk der Kolkar. Erst nach dem Krieg gegen die Untote Geißel stießen auch die Verlassenen - Untote, die ihren freien Willen zurück gewonnen hatten und sich durch Geißel und Allianz gleichermaßen bedroht sahen - zur Horde.\r\nInzwischen haben sich auch die Blutrelfen Silbermonds der Horde angeschlossen, deren militärische und ökonomische Stärke sie für das Überleben ihres eigenen Stadtstaates und zur Erreichung ihrer Ziele als dringend notwendig erachteten.\r\nBetrachtet man die Anfänge der Horde, dann wird schnell deutlich, dass ihr grundlegender Charakter in der Anfangszeit der eines Zufallsbündnisses war. Die Orks benötigten nach ihrer Ankunft in Kalimdor Unterstützung und Informationen, die Trolle schuldeten ihnen nach ihrer Rettung Hilfe. Ähnliches galt für die Tauren. Das Ende des Krieges beseitigte zwar die konkrete millitärische Bedrohung durch die Brennende Legion, doch die Geißel existierte weiter. Zudem zeigten sich Expansionsbestrebungen der Allianz nach Kalimdor. Speziell die Orks mussten fürchten, durch die vier Völker der Allianz eingekesselt und an einer dauerhaften Staatsgründung gehindert zu werden - der alte Antagonismus zwischen Menschen und Orks hatte selbstverständlich den Krieg überdauert.\r\nIn dieser Zeit wurde aus dem kurzfristigen millitärischen Bündnis, das die neue Horde zuerst gewesen war, ein protektives Schutzbündnis. Thralls Ziel war es, ein ebenbürtiges Gegengewicht zur Allianz zu schaffen, um nicht nach kurzer Zeit wieder der Gnade der Menschen ausgeliefert zu sein. Diese hätten, gestützt auf die von ihnen dominierte Allianz, das orkische Volk alleine leicht überwältigen können. \r\nDamit unterscheidet sich die neue Horde speziell in diesem einen Punkt von der Allianz: Sie ist ein junges Bündnis, dessen Völker vorher zueinander keine Beziehungen, ja nicht einmal Kenntnis voneinander hatten. Ihre Weiterexistenz ist ohne Zweifel auch dem großen Druck zuzuschreiben, den die augenblickliche Lage Azeroths auf die einzelnen Gruppierungen ausübt. Darüber hinaus sind allerdings auch Handels- und Verkehrswege, ökonomische und politische Verflechtungen entstanden, die immerhin die Wahrscheinlichkeit erhöhen, dass die Horde ein Bündnis sein könnte, das auch nach dem Wegfall konkreter Bedrohungen bestehen könnte.\r\nDie neue Horde hält heute Außenposten auf beiden bekannten Kontinenten Azeroths sowie in der Scherbenwelt. Seit der Gründung Ogrimmars sind verschiedene weitere Siedlungen entstanden und Landstriche urbar gemacht worden, so dass von einer Expansion der und einer Verdichtung ihres Einflussbereiches durch die Horde gesprochen werden kann. Nach wie vor ist sie ein dezentrales Staatengebilde, wobei jedoch gerade den Hauptstädten der Charakter bestimmender Zentren zufällt, in denen jeweils die wegweisenden Entscheidungen für ganze Landstriche getroffen werden.\r\nDie Ziele der Horde sind nicht klar definiert, wobei man noch am eindeutigsten von einem Schutzbündnis der Mitgliedsvölker sprechen kann. Die politische Linie der Horde wird von Kriegshäuptling Thrall bestimmt, der jedoch vor wichtigen Entscheidungen üblicherweise die anderen am Bündnis beteiligten Herrscher konsultiert, da er bei ihnen Mehrheiten und Unterstützung für politische Entscheidungen gewinnen muss.\r\n==Helden der Horde==\r\nTrotz der Jahre die sie in den Internierungslagern verbracht hat, hat die Horde ihren Kampfeswillen nie verloren. Zu den Helden der heutigen Horde zählen u.a.:\r\n* [[Baine Bluthuf]]\r\n* [[Etrigg]]\r\n* [[Halduron Wolkenglanz]]\r\n* [[Kriegsherr Bluthauer]]\r\n* [[Nathanos Marris]]\r\n* [[Rexxar]]\r\n* [[Rokhan]]\r\nVerstorbene Helden sind:\r\n* [[Broxigar]]\r\n* [[Grom Höllschrei]]\r\n* [[Orgrim Schicksalshammer]]\r\n* [[Sen'jin]]\r\n==Völker==\r\n* [[Blutelfen]], ([[Silbermond]])\r\n* [[Orcs]], ([[Orgrimmar]]) \r\n* [[Tauren]], ([[Donnerfels]]) \r\n* [[Trolle]] \r\n* [[Untote]], ([[Unterstadt]])\r\n==Gilden==\r\n* ''Siehe [[Gilden der Horde]].''",},
			["Horn des Cenarius"] = { content = "Das Horn des Cenarius ist ein uraltes[[ Artefakt]],dass aus dem Geweih des Halbgottes [[Malorne]] gefertigt wurde.Sein Ruf ist selbst im [[Smaragdgrünen Traum]] zu hören und vermag es so, die [[Druiden]] aus ihrem Schlummer zu wecken.Außerdem kann es die Geister aller je gestorbenen [[Nachtelfen]], im allgemeinen [[Irrwisch]] genannt,zusammenrufen.Der Träger des Horns ist gleichzeitig der Höchste Erzdruide Azeroths.[[Fandral Hirschhaupt]],der jetztige Erzdruide,trägt es jedoch nicht,darum ist anzunehmen,dass es[[ Malfurion]] es immer noch besitzt.",},
			["Horusath"] = { content = "Horusaths sind mächtige [[Golems]], die unter den [[Zwillingsimperatoren]] [[Vek'nilash]] und [[Vek'lor]] aus den [[Anubisath]] weiterentwickelt wurden. Sie gelten als Champion der Anubisath, die für ihre besonderen Dienste von den Zwillingsimperatoren umgebaut wurden und einen Falkenkopf anstelle des für die Anubisath typischen Hundekopfes erhielten.\r\n==Persönlichkeiten==\r\n* [[Ossirian der Narbenlose]]",},
			["Huhn"] = { content = "'''Hühner''' sind die beliebten Eierlieferanten, doch richtig abgerichtet gibt so ein Huhn auch einen ausgezeichneten Begleiter ab.\r\n===Hühnerarten===\r\n* '''Anconahuhn''' - Anconahühner verkauft Magus Tirth an der [[Illusionenrennbahn]] in [[Tausend Nadeln]] für 1 Gold das Stück.\r\n* '''Mechanisches Huhn''' - Ein Mechanisches Huhn erhält man wenn man alle [[Leitroboter]] von [[Glotz Widrikus]] gerettet hat, von ihm persönlich in [[Beutebucht]] überreicht.\r\n* '''Präriehuhn''' - Präriehühner kann man beeindrucken indem man sie in der [[Westfall]] erst mit Spezial Hühnerfutter von [[Bauer Saldean]] anfüttert und dann beweist das man ein viel besseres Huhn als es selbst ist.",},
			["Hurrikanus"] = { content = "Hurrikanus ist ein [[Luftelementar]] in [[Silithus]] und zählt zum Bund mit den [[Staubstürmer]]n und [[Wirbelnde Eindringlinge|Wirbelnden Eindringlingen]] während der [[Elementare Invasion|Elementaren Invasion]] in diesem Gebiet.",},
			["Hyazinthpilz"] = { content = "Hyazinthpilze wachsen unter Bäumen von [[Aldrassil]] auf der Insel [[Teldrassil]]. Man kann sie aber auch von den [[Grell]] südlich im [[Laubschattental]] sammeln; denn diese Wichtel scheinen sie sehr zu mögen. Man verwendet Hyazinthpilze zur Herstellung von Gegengiften.",},
			["Hydra"] = { content = "Hydras sind dreiköpfige, magisch begabte Echsen, die in größeren Seen oder Meeren leben. Sie haben dicke, schützende Schuppen, die der Feuchtigkeit ihrer Heimat optimal standhalten. Diese Wesen sind oftmals uralt, dienen häufig den [[Alte Götter|Alten Göttern]] und haben eine starke Verbindung mit den [[Wasserelementare]]n. Jedoch zählen sie häufig zu den [[Wildtiere]]n und nicht zu den [[Elementare]]n oder werden gar nicht klassifiziert.\r\n==Arten==\r\n* [[Fennklauen]] (zählen als Wildtiere)\r\n==Persönlichkeiten==\r\n* [[Aku'mai]]\r\n* [[Fürst der Tiefen]]\r\n* [[Gahz'ranka]]\r\n* [[Gahz'rilla]]\r\n* [[Ghaz'an]]\r\n* [[Hetaera]]\r\n* [[Lord Skwol]]\r\n* [[Mragesh]]\r\n* [[Vorsha die Peitscherin]]",},
			["Hydras"] = { content = "#REDIRECT [[Hydra]]", redirect = "Hydra",},
			["Hydraxianer"] = { content = "Die [[Hydraxianer]] sind [[Wasserelementare]], die eine große Insel im Südosten von [[Azshara]] zu ihrer Heimat gemacht haben. Diese [[Elementare]] mögen es abgeschieden und unter sich zu bleiben. Sie führen Krieg mit den Wesen der niederen Elemente und wenn man als Sterblicher in diesem Konflikt wirklich ihr Verbündeter sein möchte, dann sollte man [[Fürst Hydraxis]] seine Überzeugung beweisen. Sie sind die Erzrivalen der Armeen von [[Ragnaros]] und wenn man wirklich ein Bündnis mit ihnen wünscht, dann sollte man Krieg gegen ihre Feinde führen, die Diener von [[Luftelementare|Luft]] und [[Erdelementare|Erde]] und [[Feuerelementar|Feuer]]. Jede Niederlage, die man Ihnen beibringt, wird ihren Stand auf [[Azeroth]] schwächen.\r\n==Ansichten==\r\nAls historische Diener der [[Alte Götter|Alten Götter]] dienten die vier Elementarfürsten den Göttern mit unendlicher Loyalität. Die Günstlinge von [[Neptulon]] dem Gezeitenjäger waren zahlreich und geistlos. Es ist noch nicht bekannt, wie Fürst [[Hydraxis]] sich von der Kontrolle seines Herren befreite (wenn er sich überhaupt befreit hat), oder was seine grundlegenden Ziele sind sind, aber die [[Wasserelementare]] sind die einzigen [[Elementare]], die die sterblichen Rassen nicht mit bösartiger Wildheit angreifen, sondern für ihren Elementaren Krieg benutzen.",},
			["Hydraxis"] = { content = "#REDIRECT [[Fürst Hydraxis]]", redirect = "Fürst Hydraxis",},
			["Hydrobrut"] = { content = "'''Hydrobrut''' ist ein Wasserelementar, dass sich im östlichen Flügel von [[Düsterbruch]], im Wucherborkenviertel, niedergelassen hat. Es ist eine Anomalie in [[Eldre'Thalas]]. Sie wurde am Schrein von Eldretharr von [[Alzzin der Wildformer|Alzzin dem Wildformer]] und seinen Schergen in einen Hinterhalt gelockt.",},
			["Hyjal"] = { content = "'''Hyjal''' ist der heilige Berg der [[Nachtelfen]] und Heimat der [[Dunkeltrolle]].\r\n===Auszug aus der Geschichte nach der Spaltung der Welt===\r\nAls die erschöpften [[Nachtelfen]] an der Küste des neuen Kontinents landeten, stellten sie fest, dass der heilige Berg Hyjal die Katastrophe überlebt hatte. In dem Trachten, sich eine neue Heimat zu schaffen, erklommen [[Malfurion]] und die [[Nachtelfen]] die Hänge des Hyjal und gelangten auf den windumtosten Gipfel. Als sie in das bewaldete Tal zwischen den hohen Berggipfeln hinabstiegen, fanden sie einen kleinen, friedlichen See. Doch zu ihrem Entsetzen mussten sie feststellen, dass das Wasser dieses Sees durch [[Magie]] verdorben war.\r\n[[Illidan]], der die Teilung ebenfalls überlebt hatte, hatte den Gipfel des Hyjal lange vor [[Malfurion]] und den [[Nachtelfen]] erreicht. In seinem wahnsinnigen Begehren, die Ströme der [[Magie]] in der Welt zu erhalten, hatte [[Illidan]] die Phiolen mit dem kostbaren Wasser des Brunnens der Ewigkeit in den Bergsee geschüttet. Die kraftvollen Energien zündeten umgehend und verschmolzen zu einem neuen Brunnen der Ewigkeit. Der begeisterte [[Illidan]] war überzeugt, dass der neue Brunnen ein Geschenk für künftige Generationen darstellte, und konnte nicht fassen, als der wütende [[Malfurion]] ihn jagte. [[Malfurion]] erklärte seinem Bruder, dass [[Magie]] an sich chaotisch sei und unweigerlich zu Verderbnis und Unfrieden führen musste. Dennoch wollte [[Illidan]] seinen magischen Kräften nicht abschwören.\r\n[[Malfurion]] wusste genau, wohin [[Illidan]]s ruchlose Ränke führen würden, und beschloss, seinen machtgierigen Bruder ein für alle Male festzusetzen. Mit Hilfe von [[Cenarius]] sperrte [[Malfurion]] [[Illidan]] in eine große Kammer in einem Grabhügel, wo er bis ans Ende der Zeit angekettet und machtlos bleiben sollte. [[Malfurion]] wollte ganz sichergehen, dass sein Bruder in Gefangenschaft blieb, und ernannte die junge Aufseherin [[Maiev Schattensang]] zu [[Illidan]]s persönlicher Kerkermeisterin.\r\nDie [[Nachtelfen]] befürchteten, die Zerstörung des neuen Brunnens könnte eine noch größere Katastrophe auslösen, daher beschlossen sie, ihn in Ruhe zu lassen. [[Malfurion]] verkündete jedoch, dass nie wieder [[Magie]] praktiziert werden sollte. Unter den Augen des wachsamen [[Cenarius]] begannen die [[Nachtelfen]] das Studium der alten [[Druiden]]künste, mit denen sie die verwüstete Erde heilen und ihre geliebten Wälder am Fuße des Berges Hyjal wieder aufforsten konnten.",},
			["Hyjalgipfel"] = { content = "#REDIRECT [[Höhlen der Zeit: Kampf um Hyjal]]", redirect = "Höhlen der Zeit: Kampf um Hyjal",},
			["Händlerküste"] = { content = "Die Küste des [[Brachland]]es ist in den Händen der [[Menschen]]. An der Küste im Süden findet man die [[Tide Razor]], das Schiff der [[Südmeerfreibeuter]].\r\n==Personen==\r\n* '''Islen Wasserdeuter''' - Die Taurin Islen Wasserdeuter findet man südlich von [[Ratschet]], versteckt entlang des Ufers in einem kleinen Lager direkt am Wasser. Sie ist eine mächtige Schamanin und ihre Verbindung zu den Geistern des Wassers war immer stark. \r\n* '''Mahren Himmelsdeuter''' - Die Taurin Mahren Himmelsdeuter ist die Schwester von [[Jorn Himmelsdeuter]] und jagt die großen Wassertiere entlang der Küste. Sie wird Abenteurern etwas über die großen Wassertiere lehren, wenn man ihr das Herz von [[Isha Awak]] bringt.\r\n* '''Tazan''' - Der Troll Tazan treibt Handel mit den Piraten bei [[Ratschet]]. Er wandert die Händlerküste entlang und hat einen Assistenten namens [[Gamon]] in [[Orgrimmar]]. Wenn man ihn besiegt, erhält man „Tazans Ranzen“.",},
			["Häschersturz"] = { content = "Der Häschersturz befindet sich südöstlich von [[Thrallmar]] auf der [[Höllenfeuerhalbinsel]]. Wenn man einen kaputten, grünlich leuchtenden Haufen Metall sieht, wo einst ein alter Bauernhof stand, ist man angekommen. Stümmelfausts Truppe hier ist sehr radikal und sie haben sich der vollständigen Auslöschung der [[Brennende Legion|Brennenden Legion]] verschrieben.\r\n==Personen==\r\n* [[Apothekerin Zelana]]\r\n* '''Schwadronskommandant Brack''' befindet sich in der Nähe der Flügeldrachen und beaufsichtigt diese Tiere hier. \r\n* '''Vorpostenkommandant To’arch''' leitet den Kampf gegen die Legion hier.",},
			["Häuptling Ukorz Sandskalp"] = { content = "'''Häuptling Ukorz Sandskalp''' ist der Anführer der [[Trolle der Sandwüter]] in [[Zul'Farrak]]. In seinem Besitz befindet sich , eine Hälfte des berühmten Schwertes [[Sul'thraze]]. Ukorz ist ein [[Troll Berserker]] mit feuerroter Mähne, der im Kampf über die Fähigkeiten ''Spalten'' und ''Weiter Streich'' verfügt.",},
			["Häuptling Zul'Marosh"] = { content = "'''Häuptling Zul'Marosh''' ist ein bösartiger [[Waldtroll]] in [[Zeb'Watha]] im [[Immersangwald]]. Er befindet sich im obersten Stock des höchsten Gebäudes. Die [[Blutelfen]] verstehen zwar die Sprache seiner Schlachtpläne nicht, aber sie können klar eine Karte mit den eingetragenen Positionen der [[Zuflucht der Weltenwanderer]] und von [[Morgenluft]] ausmachen.",},
			["Höhlen der Zeit"] = { content = "Tief in den '''Höhlen der Zeit''' erwachte der Drache [[Nozdormu]]. Seit der Frühzeit der Welt hatte der [[Bronzener Drachenschwarm|Bronzene Drachenschwarm]] das verworrene Labyrinth bewacht und die sich wandelnden Zeitlinien beobachtet. All dies, um zu gewährleisten, dass das empfindliche Gleichgewicht der Zeit nicht gestört wird. Doch nun wurde der uralte [[Drachen]]aspekt [[Nozdormu]] von einer nicht greifbaren Bedrohung seiner geliebten Höhlen geweckt: Dunkle, finstere Agenten sind in die Zeitlinien eingedrungen mit der schattenhaften Mission, den Verlauf der Vergangenheit, der Gegenwart und der Zukunft zu ändern. Der [[Bronzener Drachenschwarm|Bronzene Drachenschwarm]] hat deshalb begonnen Helden um Hilfe zu bitten, die Struktur der Geschichte vor dem ewigen Zerfall zu bewahren. Die Flucht des jungen Thralls aus der Burg Durnholde, die bedeutsame Schlacht um den Berg Hyjal, und die Öffnung des ersten Dunklen Portals durch den wahnsinnigen Zauberer Medivh. Der Angriff auf die Pfade der Zeit hat begonnen. Das Gleichgewicht der Zeit steht auf dem Spiel und, wenn die Vergangenheit nicht gerettet werden kann... wird es keine Zukunft geben. \r\n==Teilbereiche==\r\nErstmalig werden Abenteurer in den Herrschaftsbereich von [[Nozdormu]], dem Zeitlosen, eintreten, um die wichtige Aufgabe zu bewältigen, die Sabotage der drei wichtigsten geschichtlichen Ereignisse zu verhindern: \r\n* '''Höhlen der Zeit: Das alte Hügelland''' - [[Höhlen der Zeit: Das alte Hügelland]] bezieht sich auf die Flucht des jungen [[Thrall]] aus der [[Burg Durnholde]], der erste Schritt seines Aufstiegs zum mächtigsten Kriegshäuptling der [[Orcs]]... \r\n* '''Höhlen der Zeit: Der Schwarze Morast''' - [[Höhlen der Zeit: Der Schwarze Morast]] zeigt die Öffnung des Dunklen Portals durch den verrückt gewordenen Zauberer [[Medivh]] - eine Handlung, die den Ersten Krieg zur Folge hatte und viele mächtige Orcs in die Welt von [[Azeroth]] brachte.\r\n* '''Höhlen der Zeit: Kampf um Hyjal''' - [[Höhlen der Zeit: Kampf um Hyjal]] ist die unvergessliche Schlacht am Berg [[Hyjal]], wo [[Jaina Prachtmeer]], [[Thrall]], [[Tyrande]] und [[Malfurion]] es schaffen den gefürchteten Dämon [[Archimonde]] zu besiegen... \r\n* '''Höhlen der Zeit: Stratholme''' - In den [[Höhlen der Zeit: Stratholme]] wird man in einiger Zukunft Zeuge eines entscheidenden Momentes in [[Arthas]] Geschichte – der Zerstörung von [[Stratholme]]. Diese Instanz soll mit einer zukünftigen Erweiterung implementiert werden.\r\n==Geschichte==\r\nDie [[Bronzener Drachenschwarm|Bronzenen Drachen]] wissen nicht, ob die Höhlen der Zeit schon immer für sterbliche zugänglich waren. Genau genommen ist dies nur schwer zu sagen, denn die Zeitlose ruht niemals, ständig verändert er den Fluss der Zeit nach seinem Ermessen. Was man heute hier sieht, ist womöglich morgen schon nicht mehr existent. Es ist nicht auszuschließen, dass man urplötzlich im Gestern aufwacht, ohne jegliche Erinnerungen an diesen Ort. Die meisten Sterblichen verstehen nicht, was sie hier erblicken, und genauso oft ist das was sie sehen, nicht mit Ihrer eigenen Wahrnehmung der Realität vereinbar. An diesem Ort gibt es nur zwei fundamentale Wahrheiten: Erstens, dass die Zeit chaotisch ist, beständig im Fluss und veränderbar. Zweitens, entspricht die Wahrnehmung eines Lebewesens nicht unbedingt immer der Realität. \r\nAls [[Hüter der Zeit]] wachen sie über [[Nozdormu]]s Reich. Der Meister ist momentan nicht zugegen, was bedeutet, dass momentan Bestrebungen im Gange sind, den Verlauf der Zeit massiv zu verändern. Niemals würde der Meister sich in die Angelegenheiten der Sterblichen einmischen, vielmehr korrigiert er, durch andere verursachte, Manipulationen der Zeit. Für die reguläre Überwachung der Zeit, sind die Hüter mehr als ausreichend qualifiziert. Sie sind in der Lage selbstständig mit den meisten der herkömmlichen Störungen fertig zu werden. D.h. mit kleinen Zwischenfällen, wie abtrünnigen Magiern, die versuchen ein Ereignis in der Vergangenheit zu ihren Gunsten zu verändern, um so ihren Reichtum oder gesellschaftlichen Stand in der Gegenwart zu verbessern. \r\nDie Tunnel die man sieht, sind die so genannten Pfade der Zeit. Ihre Zahl ist endlos. Diejenigen, welche momentan in der Realität existieren, erachtet der Meister als ‚Problemzonen’. Die verschiedenen Problemzonen unterscheiden sich in ihrer Problematik, aber sie alle entspringen derselben Ursache. Das heißt, sie verdanken ihre Existenz ein und derselben temporalen Störung. Sie haben die Pfade der Zeit nach ihrem Katastrophengrad, vom leichtesten bis zum schwersten, eingeteilt. Sie wurden alle als katastrophal für das Gefüge der Zeit eingestuft. Sollte nur ein einziger von ihnen kollabieren, würde dies das Ende der Welt bedeuten.\r\n==NSC==\r\n* [[Anachronos]]\r\n* [[Chronalis]]\r\n'''Sonstige'''\r\n* '''Arazmodu''' - Arazmodu ist ein [[Bronzener Drachenschwarm|Bronzener Drache]] in den Höhlen der Zeit. Er gehört zu den [[Wächter der Sande|Wächtern der Sande]] und erscheint in Form eines kleinen Menschen-Jungen.\r\n* '''Galgrom''' - Galgrom, ein Orc, ist der Versorger in den [[Höhlen der Zeit]]. Was er hier macht, ist eine andere Geschichte, die in eine andere Zeit gehört. Sein Bruder und er sind hier zwischen ihrer Zeit und der Gegenwart gefangen. Sie trauen sich nicht, zu gehen, weil sie befürchten, dadurch ein Zeitparadoxon auszulösen. Sie warten daher geduldig, bis die Drachen sie zu ihrer richtigen Zeitlinie zurückbringen. Wie lange das schon geht ... da ist er sich nicht sicher. In dieser Hinsicht sollte man seinen Bruder fragen.",},
			["Höhlen der Zeit: Das alte Hügelland"] = { content = "Die \"Höhlen der Zeit: Das alte Hügelland\" oder auch \"Höhlen der Zeit: Flucht aus [[Durnholde]]\" genannt, ist ein Pfad der Zeit in den [[Höhlen der Zeit]] in [[Tanaris]].\r\nDoch dieser Zeitpfad befindet sich in größter Unordnung und deshalb haben die [[Bronzener Drachenschwarm|Bronzedrachen]] einige Agenten, wie z.B. [[Erozion]] hineingeschickt, um die Ordnung dort wiederherzustellen. Die zur Verfügung stehenden Informationen weisen darauf hin, dass [[Thrall]]s Freiheit in Gefahr ist, denn eine finstere Vereinigung, bekannt als der [[Ewiger Drachenschwarm|Ewige Drachenschwarm]], versucht seine Flucht aus dem [[Internierungslager]] in [[Burg Durnholde]] zu verhindern.\r\nBesonders lohnend ist nach einer erfolgreichen Befreiung des zukünftigen Kriegshäuptlings der Aufenthalt im alten Städtchen [[Süderstade]], welches man in diesem Zeitpfad ebenfalls bereisen kann. Hier findet man Berühmtheiten, wie beispielsweise [[Hochinquisitor Weißsträhne]] aus dem [[Scharlachrotes Kloster|Scharlachroten Kloster]], [[Naxxramas]]-Endboss [[Kel'Thuzad]] in Menschengestalt oder Angelmeister [[Nat Pagle]], ein Stelldichein. Darüber hinaus findet man neben Verkäufern auch Gelegenheit seine Ausrüstung reparieren zu lassen und erfährt im Gasthaus die Geschichte von [[Aschenbringer]].\r\n==NSC's==\r\n* [[Erozion]] (Eingang)\r\n* [[Herod]] (Süderstade)\r\n* [[Hochinquisitorin Weißsträhne]] (Süderstade)\r\n* [[Kel'Thuzad]] (Süderstade)\r\n* [[Nat Pagle]] (Süderstade)\r\n* [[Thrall]] (Burg Durnhold)\r\n==Bosse==\r\n* [[Leutnant Drach]]\r\n* [[Kaptain Skarloc]]\r\n* [[Epochenjäger]]",},
			["Höhlen der Zeit: Der Schwarze Morast"] = { content = "Die \"Höhlen der Zeit: Der Schwarze Morast\" ist ein Pfad der Zeit in den [[Höhlen der Zeit]] in [[Tanaris]].\r\nÜber diesen Zeitpfad stehen dem [[Bronzener Drachenschwarm|Bronzenen Drachenschwarm]] nur wenige Informationen zur Verfügung, doch [[Sa'at]] kümmert sich momentan um diese Angelegenheit. Er befindet sich im Inneren des Pfades. Soweit die [[Bronzedrachen]] es seinen Botschaften entnehmen konnten, versucht der [[Ewiger Drachenschwarm|Ewige Drachenschwarm]] erneut den Verlauf der Zeit zu ändern und planen, die Öffnung des [[Dunkles Portal|Dunklen Portals]] zu verhindern.\r\n==NSC's==\r\n* [[Medivh]]\r\n* [[Sa'at]]\r\n==Bosse==\r\n* [[Chronolord Deja]]\r\n* [[Temporus]]\r\n* [[Aeonus]]",},
			["Höhlen der Zeit: Kampf um Hyjal"] = { content = "Die '''Höhlen der Zeit: Kampf um Hyjal''' ist ein Pfad der Zeit in den [[Höhlen der Zeit]] in [[Tanaris]]. Es ist die bedeutsame Schlacht um den Berg Hyjal, wo [[Jaina Prachtmeer]], [[Thrall]], [[Tyrande Wisperwind]] und [[Malfurion Sturmgrimm]] erfolgreich das Blatt im Kampf gegen den gefürchteten Dämon [[Archimonde]] wendeten... \r\nDoch dieser Pfad der Zeit befindet sich im Zustand der Zusammenbruchs. Was das für die Vergangenheit, Gegenwart und Zukunft bedeuten mag, ist unbekannt... . Die Bronzedrachen wissen nur, dass dieser Pfad der Zeit zum Berg [[Hyjal]] führt und dass der [[Ewiger Drachenschwarm|Ewige Drachenschwarm]] alles unternommen hat, um eine Einmischung der [[Bronzedrachen]] zu verhindern. Die Situation dort ist ihnen jedoch unbekannt. [[Soridormi]] versucht momentan die Verteidigungsmaßnahmen des Pfades zu durchdringen, bisher ohne Erfolg. Die Schlacht um den Berg [[Hyjal]] ist eines der bestgehüteten Geheimnisse dieser Zeitlinie. Sollte ein Eindringling ihren Ausgang ändern, hätte dies Auswirkungen auf alle folgenden Momente in der Geschichte. [[Soridormi]] spürte eine Welle in der Zeit, die von den Ereignissen bei der Schlacht um den Berg [[Hyjal]] herrührte. Jemand oder etwas versucht, diese Zeitlinie zu verändern. Das muss verhindert werden.\r\n==NSC's==\r\n* [[Jaina Prachtmeer]]\r\n* [[Tydormu]]\r\n==Bosse==\r\n* [[Archimonde]]\r\n* [[Azgalor]]\r\n* [[Anetheron]]\r\n* [[Furor Winterfrost]]\r\n* [[Kaz'Rogal]]",},
			["Höhlen des Wehklagens"] = { content = "''\"Es ist, als würde das Land träumen und nicht erwachen können.\"''\r\nDie Höhlen des Wehklagens sind ein gefährliches Höhlensystem im [[Brachland]] und die Quelle der Besudelung des Landes. Durch das Wasser der [[Brachland Oasen]] wird sie auf die Tiere übertragen und bringt Verwirrung über das Land.\r\nVor nicht allzu langer Zeit entdeckte ein nachtelfischer [[Druiden]] namens [[Naralex]] eine Reihe unterirdischer Höhlen im Herzen des [[Brachland]]s. Er gab den Höhlen des Wehklagens ihren Namen, da sich dort viele Risse im Boden befinden, durch die in regelmäßigen Abständen heißer Dampf entweicht, wobei ein lang gezogenes, wehleidig klingenendes Heulen ertönt. Naralex glaubte, die unterirdischen Quellen der Höhlen dazu nutzen zu können, das [[Brachland]] wieder grün und fruchtbar zu machen. Um seinen mutigen Plan in die Tat umzusetzen, musste er zuerst die Energien des sagenumwobenen [[Smaragdgrünen Traum|Smaragdgrünen Traums]] anzapfen. Sobald er sich in den Traum versetzte, geschah jedoch das Unfassbare: Seine Vision verwandelte sich in einen Alptraum! Kurz darauf fingen auch die Höhlen des Wehklagens an, sich zu verändern. Das einst reine Quellwasser wurde faulig, und die zahmen Kreaturen vollzogen eine perverse Metamorphose, aus der sie als blutrünstige Monster hervorgingen. Man sagt, [[Naralex]] hielte sich immer noch in den Höhlen auf, gefangen in seinem eigenen Smaragdgrünen Alptraum. Sogar die Gefolgsleute von [[Naralex]] wurden durch das Versagen ihres Meisters korrumpiert und in die grausamen [[Druide des Giftzahns|Druiden des Giftzahns]] verwandelt. \r\n'''Quelle:''' \r\n==Flora und Fauna==\r\nAls Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem [[Brachland]] in die Höhlen des Wehklagens vor. Diese '''Deviatkreaturen''' haben seltsame, überirdische Eigenschaften. Sie sind zwar von Natur aus böse, doch sind die [[Druiden]] der Meinung, dass ihre Existenz hier in [[Kalimdor]] auch etwas Gutes haben kann und ihre Bälge sind besonders gut für die Lederverarbeitung geeignet. In den Höhlen findet man auch einen Leuchtenden Splitter. Dieser ist von einem glänzenden Grün, und obwohl er massiv ist, scheint etwas wie Rauch knapp unterhalb der Oberfläche herumzuwirbeln. Man fühlt den Zwang, in die Tiefen des Kristalls zu schauen, aber gleichzeitig fühlt man auch, dass etwas sehr Beunruhigendes von ihm ausgeht. \r\n'''Siehe auch:'''\r\n* [[Klageessenz]]\r\n* [[Schlangenflaum]]\r\n==Bosse==\r\n* [[Kresh]]\r\n* [[Lady Anacondra]]\r\n* [[Lord Kobrahn]]\r\n* [[Lord Pythas]]\r\n* [[Lord Serpentis]]\r\n* [[Mutanus der Verschlinger]]\r\n* [[Skum]]\r\n* [[Trigore der Peitscher]]\r\n* [[Verdan der Ewiglebende]]\r\n* [[Zausel der Verrückte]]\r\n==NSC's==\r\n* [[Naralex]]\r\n'''Sonstige'''\r\n* '''Ebru''' - Während einige Jünger von Naralex versuchen, den Meister zu wecken, ist es sein Trachten, die Höhlen von den bösen Bestien zu befreien. \r\n* '''Falla Sagewind'''\r\n* '''Jünger von Naralex''' - Erst wenn [[Naralex]]'s verderbten Diener, die Fanglords, tot sind, kann er das Erweckungsritual durchführen.\r\n* '''Kalldan Felmoon''' - Speziallederverarbeitungsbedarf\r\n* '''Nalpak''' - Nalpak möchte 20 Deviatbälge.\r\n* '''Waldor''' - Lederverarbeitungsgeselle\r\n* '''Zausel der Verrückte''' - Goblin. Er ist mit einer Flasche 99-jährigem Portwein davon gerannt.",},
			["Höhle der Knarzklauen"] = { content = "Die '''Höhle der Knarzklauen''' befindet sich auf dem Weltenbaum [[Teldrassil]].\r\n==Wissenswertes==\r\nDie '''Höhle der Knarzklauen''' ist das Revier der [[Furbolgs der Knarzklauen]] in [[Teldrassil]].",},
			["Höhle des Schlangenschreins"] = { content = "#REDIRECT [[Echsenkessel: Schlangenschrein]]", redirect = "Echsenkessel: Schlangenschrein",},
			["Höllenbestie"] = { content = "Höllenbestien(oder Infernale)wurden einst von den [[Tothrezim]] konstruiert.Diese hirnlosen Riesen aus Flammen und Wut sind eigentlich keine wirklichen [[Dämonen]], sondern Kontrukte, die von [[Nathrezim]] oder durch den Inferno-Zauber der [[Hexenmeister]] herbeigerufen werden. Höllenbestien fallen als grüne, flüssige Meteoriten zur Erde und existieren nur, um alles Leben in ihrem Weg zu vernichten. Ihre Lebensspanne ist zwar begrenzt, doch man weiß, dass die mächtigen Höllenbestien ganze Städte vernichten können, bevor ihre Energien wieder in das [[Großes Dunkles Jenseits|Große Dunkle Jenseits]] zurückfließen. Sie sind schwächere Verwandten der [[Abyss]]e, die auf der [[Scherbenwelt]] vorkommen.\r\n==Persönlichkeiten==\r\n* [[Kroshius]]",},
			["Höllenfeuerbollwerk"] = { content = "#REDIRECT [[Höllenfeuerzitadelle: Höllenfeuerbollwerk]]", redirect = "Höllenfeuerzitadelle: Höllenfeuerbollwerk",},
			["Höllenfeuerhalbinsel"] = { content = "Die '''Höllenfeuerhalbinsel''' ist das erste Gebiet, das man bei dem durchqueren des [[Dunkles Portal|Dunklen Portals]] sehen wird. Der Boden hier erinnert an [[Durotar]] - ein staubiger roter Untergrund. Man findet viele Knochen und Ruinen, was auf einen der härtesten Kriege in der Geschichte zurückzuführen ist - Den Krieg zwischen [[Khadgar]] mit der [[Allianz]]-Expedition und [[Ner'zhul]] mit der [[Horde]]. Nach [[Illidan]]s Flucht durch das Dunkle Portal rüstet die [[Brennende Legion]] auf den Überresten [[Draenor]]s – der [[Scherbenwelt]] - für einen neuen Eroberungsfeldzug in [[Azeroth]]. Auf der anderen Seite des Dunklen Portals werfen alle Völker Azeroths gemeinsam ihre mächtigsten Kämpfer in die Schlacht, um die [[Dämonen]] an einer erneuten Invasion ihrer Heimat zu hindern.\r\n==Geschichte==\r\nDie öde Höllenfeuerhalbinsel war der Standort des [[Dunkles Portal|Dunklen Portals]] auf [[Draenor]], und wurde von der [[Höllenfeuerzitadelle]] gesichert. Als die Truppen der [[Allianz]] durch das Tor in die Heimatwelt der [[Orcs]] kamen, lieferten sie sich zahlreiche Gefechte mit den einheimischen Klans. Die [[Horde]] hatte nicht mit einem Angriff der Menschen gerechnet, und war im ersten Moment wie gelähmt. Während Teile der Streitkräfte die Stellungen auf der Halbinsel sicherten, zerstörten General [[Turalyon]]s Armeen die Hafenstadt Zeth'kur und drangen weiter ins Landesinnere vor. Die angreifenden Orc-Krieger waren zwar nicht gut ausgerüstet, aber ihre Überzahl hätte die [[Menschen]] fast in die Knie gezwungen und durch das [[Dunkle Portal]] zurückgedrängt. Nur dank ihrer Taktik, schnell und gezielt anzugreifen und sich sofort wieder zurückzuziehen, vereitelten sie immer wieder [[Ner'zhul]]s Bemühungen, sie auszuschalten. \r\n'''Quelle''': \r\n==Orte==\r\n* [[Alter Belagerungsturm]]\r\n* [[Dornnebelhügel]]\r\n* [[Ehrenfeste]]\r\n* [[Expeditionsposten]]\r\n* [[Expeditionsrüstlager]]\r\n* [[Falkenwacht]]\r\n* [[Front der Legion]]\r\n* [[Große Kluft]]\r\n* [[Haal'eshi Bau]]\r\n* [[Häschersturz]]\r\n* [[Himmelssturzgrat]]\r\n* [[Höllenfeuerzitadelle]]\r\n* [[Kil'jaedens Thron]]\r\n* [[Leerengrat]]\r\n* [[Messerdornpfad]]\r\n* [[Mine der Ehrenfeste]]\r\n* [[Mine von Thrallmar]]\r\n* [[Pfad des Ruhmes]]\r\n* [[Posten der Mag'har]]\r\n* [[Posten des Cenarius]]\r\n* [[Rückenbrecherposten]]\r\n* [[Ruinen von Sha'naar]]\r\n* [[Sphärenfelder]]\r\n* [[Teiche von Aggonar]]\r\n* [[Tempel von Telhamat]]\r\n* [[Thrallmar]]\r\n* [[Trümmerposten]]\r\n* [[Versorgungskarawane von Thrallmar]]\r\n* [[Zeppelinabsturzstelle]]\r\n* [[Zeth'Gor]]\r\n* [[Zeth'kur]]\r\n===Außenpostens von Gor'gaz===\r\nDer Außenpostens von Gor'gaz ist einer der Lieblingsorte der [[Höllenorcs]] der [[Klan der Zerschmetterten Hand|Zerschmetterten Hand]].\r\n===Ehrenpunkt===\r\nDer Ehrenpunkt ist ein kleiner Posten in der Nähe der Front der Legion unter Aufsicht von Feldmarschall Brock.\r\n===Östliche Versorgungskarawane===\r\nAls die [[Brennende Legion]] in [[Azeroth]] eingefallen ist, war sie auch in der Scherbenwelt nicht untätig. Allianz und Horde haben ihre Bewegungen über die Jahre verfolgt. Unteroffizier Altumus hat die Eindringlinge der Brennenden Legion beobachtet und weiß mehr über ihre Pläne. Da sie Kazzak nicht direkt angreifen können - noch nicht - müssen sie zunächst seine Leutnants, die die Truppen vom Boden aus kommandieren, auslöschen.\r\n===Staubstachelschlucht===\r\nDie Stachelklauenfelshetzer aus der Schlucht sind bekannt dafür, dass sie einsame Reisende angreifen. \r\n===Teufelsfunkenklamm===\r\nDie [[Brennende Legion]] hat [[Schreckenslord]]s in der Teufelsfunkenklamm östlich von [[Thrallmar]] postiert. Sie sind für diese höllischen Stürme, die herabprasseln, verantwortlich.",},
			["Höllenfeuerzitadelle"] = { content = "In der verwüsteten Weite der [[Scherbenwelt]], tief im Herzen der öden [[Höllenfeuerhalbinsel]], steht die Zitadelle des Höllenfeuers: Eine fast uneinnehmbare Festung, die der [[Horde]] als Ausgangspunkt für ihre Feldzüge während des Ersten und des Zweiten Krieges diente und das [[Dunkle Portal]] sicherte. Lange Jahre schien es, als sei diese gigantische Festung verlassen… Bis vor kurzem. \r\nAls die Truppen der Allianz durch das Tor in die Heimatwelt der [[Orcs]] kamen, lieferten sie sich zahlreiche Gefechte mit den einheimischen Klans. Die [[Horde]] hatte nicht mit einem Angriff der [[Menschen]] gerechnet, und war im ersten Moment wie gelähmt. Während Teile der Streitkräfte die Stellungen auf der Halbinsel sicherten, zerstörten General [[Turalyon]]s Armeen die Hafenstadt Zeth'kur und drangen weiter ins Landesinnere vor. Die angreifenden Orc-Krieger waren zwar nicht gut ausgerüstet, aber ihre Überzahl hätte die [[Menschen]] fast in die Knie gezwungen und durch das [[Dunkle Portal]] zurückgedrängt. Nur dank ihrer Taktik, schnell und gezielt anzugreifen und sich sofort wieder zurückzuziehen, vereitelten sie immer wieder [[Ner'zhul]]s Bemühungen, sie auszuschalten.\r\n==Teilbereiche==\r\nDie Höllenfeuerzitadelle untergliedert sich in 4 Bereiche:\r\n* [[Höllenfeuerbollwerk]]\r\n* [[Blutkessel]]\r\n* [[Zerschmetterte Hallen]]\r\n* [[Magtheridons Kammer]]\r\n==Höllenorcs==\r\nObwohl der rücksichtslose [[Ner'zhul]] große Bereiche [[Draenor]]s zerschmetterte, blieb die Zitadelle des Höllenfeuers intakt - und wird nun von marodierenden Banden roter, wütender [[Höllenorcs]] bewohnt. Obwohl die Anwesenheit dieser neuen, wilden Brut an sich bereits ein Rätsel darstellt, ist es noch weitaus beunruhigender, dass die Anzahl der [[Höllenorcs]] stetig zu wachsen scheint. Trotz [[Thrall]]s und [[Grom Höllschrei]]s erfolgreicher Bemühungen, der Korruption der [[Horde]] Einhalt zu gebieten indem sie [[Mannoroth]] töteten, scheint es, als hätten die barbarischen [[Orcs]] der Zitadelle des Höllenfeuers eine neue Quelle entdeckt, die ihre primitive Gier nach Blut stillt. \r\nAn der Basis der Zitadelle am Ende des Pfads des Ruhmes versucht '''Drillmeister Zurok''' unter dem Kommando von '''Truppenkommandant Gorax''' alle Eindringlinge aufzuhalten. Gorax trainiert die Hauptmänner am Fuß der Zitadelle und drillt sie, bis sie so scharf wie Rasierklingen sind. Er wird begleitet von seinem Kommandanten, der '''Hand von Kargath'''.\r\n==Die Macht im Hintergrund==\r\nWessen Befehl diese [[Orcs]] unterstehen, ist nicht bekannt, allerdings überwiegt die Meinung, dass sie nicht für die [[Brennende Legion]] arbeiten. Die vielleicht beunruhigendste Nachricht aus der [[Scherbenwelt]] sind allerdings die Berichte über erschütternde, wilde Schreie aus den Tiefen unterhalb der Zitadelle. Möglicherweise stehen diese unheimlichen Ausbrüche in Zusammenhang mit den [[Höllenorcs]] und ihrer wachsenden Zahl. Bedauerlicherweise müssen diese Fragen unbeantwortet bleiben. Zumindest für jetzt.",},
			["Höllenfeuerzitadelle: Blutkessel"] = { content = "In der Ritualstätte im Blutkessel in der [[Höllenfeuerzitadelle]] trinken die [[Orcs des Lachenden Schädels]] Dämonenblut, um über deren Kräfte zu verfügen. Die magische Überwachung besagt, dass dort etwas Unnatürliches vor sich geht. Jedoch werden die weiteren arkanen Untersuchungen von einer großen Macht im Inneren abgeblockt, also muss es sehr wichtig sein. Die [[Orcs]] hier müssen das Blut des [[Grubenlords]] [[Magtheridon]] verwenden, um neue [[Höllenorcs]], die aus irgendeinem Grund nicht zur [[Brennende Legion|Brennenden Legion]] gehören, zu erschaffen. Und wenn sie das mit den braunen [[Mag'har]] können, schaffen sie das auch mit grünen. Bei all den [[Orcs]], die durch das [[Dunkle Portal]] kommen, sind das alles andere als gute Nachrichten. Die [[Horde]] und die [[Allianz]] müssen diese [[Höllenorcs]] ins Herz ihrer Militärmacht treffen, und zwar bald.\r\n==Bosse==\r\n* [[Der Schöpfer]]\r\n* [[Broggok]]\r\n* [[Keli'dan der Zerstörer]]",},
			["Höllenfeuerzitadelle: Höllenfeuerbollwerk"] = { content = "Das '''Höllenfeuerbollwerk''' ist Teil der [[Höllenfeuerzitadelle]] auf der [[Höllenfeuerhalbinsel]] der [[Scherbenwelt]] und ist fest in der Hand der [[Orcs der Knochenmalmer]].\r\n==Bosse==\r\n* [[Wachhabender Gargolmar]]\r\n* [[Omor der Narbenlose]]\r\n* [[Vazruden und Nazan]]",},
			["Höllenfeuerzitadelle: Magtheridons Kammer"] = { content = "'''Magtheridons Kammer''' ist ein 25-Mann Schlachtzug-Dungeon in der [[Höllenfeuerzitadelle]].\r\nHier wird der [[Grubenlord]] [[Magtheridon]] von Kanalisierern im Schach gehalten, die sein Blut anzapfen und im Gleichen Maße wie sie ihm das Blut entziehen, wächst auch die Legion der [[Höllenorc]]s. \r\n==Geschichte==\r\nDie unheilvolle Drohung durch [[Magtheridon]] ist jedem bekannt, der sich in den [[Blutkessel]] gewagt hat. [[Magtheridon]], der frühere Herrscher dieser zerbrochenen Welt, wird gefangen gehalten und sein Blut wird abgezapft, um eine Armee von [[Höllenorcs]] zu erschaffen. Die Wut Magtheridons richtet sich gegen seinen Bewacher, [[Illidan]] den Verräter, und seine zornigen Rufe entstammen einem Ort in der [[Höllenfeuerzitadelle]]. \r\nKurz nach dem Zweiten Krieg stürmte eine Expedition der [[Allianz]] durch das [[Dunkle Portal]] nach [[Draenor]]. Ihre Mission war es, die [[Orcs]] ein für alle Mal zu besiegen. Als die Expedition sich näherte, öffnete der Orcschamane [[Ner'zhul]] verschiedene Portale in andere Welten. Durch die magische Belastung wurde [[Draenor]] in Stücke gerissen, und das zersplitterte Reich der Scherbenwelt entstand. Die [[Brennende Legion]] nutzte die geöffneten Portale zu ihrem Vorteil. Der mächtige Grubenlord [[Magtheridon]] wurde entsandt, um die zerbrochene Welt im Namen [[Kil'jaeden]]s in Besitz zu nehmen. [[Magtheridon]] sammelte die verbliebenen [[Orcs]] und formte eine Armee, die er gegen die letzten überlebenden [[Draenei]] schickte, um den Widerstand gegen seine Herrschaft auszulöschen. \r\nDer [[Tempel von Karabor]] war einst ein Heiligtum der [[Draenei]] und wurde später von [[Orc Hexenmeister]]n der besetzt, die ihn zum Schwarzen Tempel umbenannten. Als die Legion die [[Scherbenwelt]] in Besitz nahm, war es [[Magtheridon]], der von dieser düsteren Festung aus regierte. Er hatte die Kontrolle über fast die gesamte [[Scherbenwelt]] und verstärkte ständig seine Armeen, in dem er durch die Portale weitere [[Dämonen]] beschwor. Obwohl [[Magtheridon]] viele mächtige Feinde geschlagen hatte, war ihm seit sehr langer Zeit niemand mit vergleichbarer Macht entgegen getreten. Aus diesem Grund wurde er durch [[Illidan]] und dessen Verbündete überrascht, die durch Magtheridons Verteidigungslinien brachen und den Schwarzen Tempel belagerten. Bald darauf schlug [[Illidan]] die letzen Verteidiger des [[Grubenlord]]s und besiegte den General der Legion. \r\nViele glaubten, [[Magtheridon]] sei bei diesem Angriff getötet worden, aber wie bei [[Mannoroth]] stellte sich heraus, dass sein Blut geeignet war, die [[Orcs]] zu verderben. Besiegt und blutüberströmt wurde der [[Grubenlord]] zur [[Höllenfeuerzitadelle]] verschleppt und von Illidans mächtigsten Hexenmeistern unterworfen. Dort lebt er jetzt, gefesselt mit magischen und physischen Ketten, durch seine Wunden dem Tode nahe, und jeden Tag zapfen Illidans Diener sein Blut ab. Sein besudeltes Blut ist die Quelle einer neuen Armee barbarischer Höllenorcs. Sollte es dem [[Grubenlord]] aber jemals gelingen, sich zu befreien, wird die Scherbenwelt unter seinem schrecklichen Zorn erzittern. \r\n'''Quellen'''",},
			["Höllenhund"] = { content = "'''Höllenhunde''', oder auch [[Teufelsbestie]]n, sind seltene Kreaturen, die einem [[Kernhund]] ähneln. Jedoch entspringen sie grüner [[Teufelsenergie]]n statt der Lava. Die leben u.a. im [[Schattenmondtal]] in der Nähe der [[Hand von Gul'dan]].\r\n==Persönlichkeiten==\r\n* [[Uvuros]]",},
			["Höllenorc"] = { content = "#REDIRECT [[Höllenorcs]]", redirect = "Höllenorcs",},
			["Höllenorcs"] = { content = "Das kürzliche Erscheinen dieser korrumpierten [[Orc]]s in der [[Scherbenwelt]] löste eine Welle der Spekulationen aus, denn viele Geheimnisse ranken sich um die wilden Krieger, über die wenig bekannt ist. Sie sind größer, bösartiger und listiger als die Rüpel, mit denen die Allianz sich sonst herumschlagen muss. Und sie mögen vollkommene Barbaren sein, aber ihre Schmiedekunst ist nicht so primitiv, wie manche denken.\r\nEines ist aber besonders beunruhigend: Ihre ständig wachsende Zahl. \r\nUnd obwohl [[Mannoroth]] besiegt und die [[Horde]] vom Joch der [[Dämonen]] befreit wurde, scheinen diese [[Orcs]] einen neue Quelle gefunden zu haben, die ihre Blutgier stillt. Welchem Befehl die Höllenorcs unterstehen bleibt weitgehend unbekannt, allerdings überwiegt die Meinung, dass sie nicht im Sold der Brennenden Legion stehen.\r\nDie ersten Höllenorcs wurden nach [[Thrall]]s Reformierung der Horde von [[Jubei'thos]] in der Dunklen Horde zusammengefasst. Später schuf [[Mannoroth]]s Blut noch mehr in [[Eschental]].",},
			["Hügellandhof"] = { content = "Die [[Menschen]] in Hügellandhof im [[Vorgebirge des Hügellands]] leisten unerwarteten Widerstand gegen die Angriffe der [[Verlassene]]n. Das Problem scheint darin zu bestehen, dass die Bewohner durch den örtlichen Schmied mit Waffen versorgt werden. Die [[Verlassene]]n müssen deswegen alle Versorgungsmöglichkeiten abschneiden. Nach der Eroberung der Stadt Hügellandhof werden diese Vorräte den Verlassenen gelegen kommen, wenn sie mit der Verwüstung von [[Süderstade]] beginnen. Der Hügellandhof ist ein einziges Chaos und die Verlassenen sind der Meinung, dass die Stadt bald fallen wird. Nichtsdestotrotz müssen sie weiterhin an ihrer Ruchlosigkeit festhalten bis der menschliche Abschaum ein für alle Mal von diesem Vorgebirge verschwunden ist. Trotz ihrer überwältigenden Verluste sammeln die [[Menschen]] sich weiterhin um ihre Führungskraft und kämpfen weiter. Die Verlassenen wollen den Anführer dort, [[Magistrat Uferbach]] eliminieren und mit ihm den ganzen Stadtrat. Die Proklamation des Hügellandhofs ist ihr heißgeliebtes politisches Dokument. [[Amtmann Horatio Weißross]] lebt ebenfalls hier und wird wegen Mordes an [[Todeswache Toma]] gesucht.",},
			["Hügelwand"] = { content = "Die Hügelwand liegt ganz im Nordwesten der Wälder von Terokkar, gleich über Shattrath. Es ist eine der vielen Fronten, an denen die [[Himmelswache der Sha'tari]] eingesetzt werden, denn bei der Hügelwand lebenden [[Oger der Gordunni]] und diese stellen eine unmittelbare Bedrohung für [[Shattrath]] dar. Doch es erwies sich als sehr schwer für die Bodentruppen, die [[Oger]] zu erreichen.",},
			["Hügel der Klingenhauer"] = { content = "Hügel der Klingenhauer, die von den selben dornigen Ranken wie der [[Kral der Klingenhauer]] dominiert werden, beherbergen seit jeher die Hauptstadt des Volks der [[Stacheleber]]. In dem weitläufigen, dornenverseuchten Labyrinth hält sich eine riesige Armee wilder [[Stacheleber]]krieger auf, die ihr Leben darauf geschworen haben, ihre Hohepriester – die Mitglieder des Totenkopfstammes – um jeden Preis zu beschützen. Vor Kurzem hat sich jedoch ein unheilbringender Schatten über den kruden Bau gelegt. Abgesandte der untoten [[Geißel]] unter der Führung des Lichs [[Amnennar der Kältebringer]] haben die Kontrolle über das Volk der [[Stacheleber]] übernommen und das Labyrinth der Dornen in eine vorgeschobene Bastion untoter Macht verwandelt. Nun kämpfen die [[Stacheleber]] einen verzweifelten Kampf gegen die Zeit, denn Amnennars Einfluss dehnt sich jeden Tag weiter aus. Wenn er nicht aufgehalten wird, ist es nur eine Frage der Zeit, bis das Banner der [[Geißel]] über dem [[Brachland]] wehen wird. \r\n'''Quelle:''' wow-europe.com\r\nEinige der [[Stacheleber]] sind beängstigend stark geworden und zeigen erste Symptome der Seuche. Die [[Geißel]] hat anscheinend mit den [[Stacheleber]]n hier eine Art Vereinbarung getroffen, und dieser Alptraum ist das Ergebnis.\r\n==Personen==\r\n* [[Amnennar der Kältebringer]]\r\n* [[Belnistrasz]]\r\n* [[Botschafter Malcin]]\r\n* [[Lady Falther'ess]] - Eine Banshee in den Hügeln der Klingenhauer während der [[Invasion der Geißel]].",},
			["Hüter der Zeit"] = { content = "Im Herzen von [[Tanaris]] liegen die [[Höhlen der Zeit]], Heimat des [[Bronzener Drachenschwarm|bronzenen Drachenschwarms]]. [[Nozdormu]] und seine Brut schützen von hier aus den Fluss der Zeit gegen alle, die die sensible Struktur des Schicksals verändern könnten.\r\nSie sind die Zeitbehüter, Kinder [[Nozdormu]]s - dem Lord der Jahrhunderte. Und es sind derer drei, die die [[Höhlen der Zeit]] bewachen. Es sind von [[Nozdormu]] höchstpersönlich ausgesuchte bronzene Drachen, die über die [[Höhlen der Zeit]] wachen. Der Meister der Hüter ist [[Andormu]], der sich als kleiner Junge zeigt. Die Hauptaufgabe der Hüter ist es jede Veränderung der Geschichte zu vermeiden. Da dies in den Höhlen der Zeit möglich ist, sind sie hier auch stark vertreten.\r\n==Botschafter==\r\nEin Botschafter der Bewahrer der Zeit wurde in der [[Taverne Weltenend]] in [[Shattrath]] gesehen. Spieler mit einem guten Ruf bei dieser Fraktion können dort leichten Zugang zu den [[Höhlen der Zeit]] erhalten. \r\n==Negative Eingriffe in den Zeitfluss==\r\nIn jüngster Zeit jedoch wurde das Zeitgefüge von einer finsteren Macht befallen, die, sollte sie Erfolg haben, die Struktur der Welt und letztendlich der Zeit selbst zerstören könnte. Die Hüter der Zeit haben negative Eingriffe auf den Zeitfluss an verschiedenen Punkten der Vergangenheit [[Azeroth]]s festgestellt. [[Thrall]]s Flucht aus [[Durnholde]] wurde manipuliert, um den Sohn [[Durotan]]s am Erfüllen seines Schicksals zu hindern, ihn also davon abzuhalten, sein Volk zu befreien und zum größten Kriegsherrn zu werden, den die [[Orcs]] je kannten. Dieselben Mächte, die [[Thrall]] an seiner Flucht hindern wollen, versuchen auch, das Ereignis ungeschehen zu machen, das zum Ersten Krieg führte und [[Azeroth]] damit in ein Zeitalter des Chaos stürzte: [[Medivh]]s Öffnung des [[Dunkle Portal|Dunklen Portals]]. Aber auch der Ausgang der Schlacht um den Berg [[Hyjal]], wo [[Orcs]], [[Menschen]] und [[Nachtelfen]] Schulter an Schulter gegen die Streitkräfte der [[Brennende Legion|Brennenden Legion]] antraten, wurde verändert.",},
			["Hüter des Hains"] = { content = "Die verzauberten Hüter des Hains sind die Lieblingssöhne des Halbgottes [[Cenarius]]. Wie ihre Schwestern, die [[Dryaden]], erscheinen die Hüter in besonderer Gestalt: Sie sind halb [[Nachtelf]], halb Hirsch. Riesige Geweihe zieren ihre Köpfe, und über ihre Rücken wallen dicke Blättermähnen. Ihre rechten Hände sind verkrüppelt und verdreht, man könnte fast glauben, die knorrigen Wurzelklauen der [[Treants]] vor sich zu sehen. Die Hüter üben auf vielerlei Art eine seltsame Macht über Natur und Tiere aus. Obwohl sie nur äußerst selten außerhalb der heiligen Mondhaine des [[Eschental]]-Waldes angetroffen werden, so folgen sie doch stets dem Ruf zu den Waffen, wenn das Land von [[Kalimdor]] von Feinden bedroht wird. \r\n==Fähigkeiten==\r\nZu ihren Fähigkeiten zählt die druidische Dornen-Aura, die Verbündeten ein Schutzschild verleiht, welches bei Feinden, die die Verbündeten angreifen, Schaden verursacht. Die Kraft der Natur wiederum ermöglicht es den Hütern des Hains, mächtige kampffähige \"Treants\" zu kreieren, die Ihrer Armee für eine begrenzte Zeit beitreten können. Durch Gelassenheit können sie Ströme heilender Energie über ein großes Gebiet schicken und damit verbündete Einheiten heilen.\r\n==Persönlichkeiten==\r\n* [[Bewahrer Albagorm]]\r\n* [[Bewahrer Marandis]]\r\n* [[Bewahrer Ordanus]]\r\n* [[Bewahrer Remulos]]\r\n* [[Celebras]]\r\n* [[Torhüter Kordurus]]\r\n* [[Wildfürst Antelarion]]\r\n* [[Zaetar]]\r\n'''Verwandte'''\r\n* [[Dryaden]]",},
			["Ilifar"] = { content = "'''Ilifar''', der Bewahrer der Seelen, ist ein dämonischer [[Todesritter]] in den [[Verwüstete Lande|Verwüsteten Landen]], der von [[Razelikh]] beschworen wurde. Ilifar war einst ein ehrenwertes Mitglied der menschlichen Gesellschaft, bis er den dunklen Ruf des Lichköngs hörte. Doch nach dem Verrat des Lichkönigs verbündete er sich nicht mit der Geißel, wie die meisten anderen Todesritter, sondern mit der [[Brennende Legion|Brennenden Legion]] und trat in die Dienst des mächtigen Schreckenslords Razelikh.",},
			["Illidan"] = { content = "#REDIRECT [[Illidan Sturmgrimm]]", redirect = "Illidan Sturmgrimm",},
			["Illidan Sturmgrimm"] = { content = "'''Illidan Sturmgrimm''' ist auch bekannt als: der Verräter, Träger der [[Zwillingsgleven von Azzinoth]], Meister der [[Illidari]].\r\n==Geschichte==\r\n* Siehe auch: [[Der aufstrebende Verräter]]\r\nDieser [[Dämonenjäger]] ist der Zwillingsbruder von [[Malfurion Sturmgrimm]] und wuchs wie sein Bruder als Freund von [[Tyrande Wisperwind]] auf, Jahrtausende vor der Großen Teilung. Im Gegensatz zu Malfurion hatte Illidan nicht genug Geduld für die Feinheiten der [[Druiden]]kunst und erwies sich als schlechter Schüler, obwohl sein Lehrer der Halbgott [[Cenarius]] selbst war. Aber Illidan besaß ein Talent für die Hexerei, die zu dieser Zeit in der [[Nachtelfen]]gesellschaft hoch angesehen war. Seine magischen Fähigkeiten halfen ihm jedoch nicht viel weiter, denn er besaß von Geburt an goldene Augen. Diese waren vor der Großen Teilung nicht nur extrem selten bei [[Nachtelfen]], sie wurden auch als Zeichen für künftige Größe angesehen. Doch Illidan zeigte keinerlei Anzeichen dafür, dass er irgendetwas Außergewöhnliches erreichen könnte. Er hatte auch keine Ahnung, dass seine Augenfarbe in Wirklichkeit ein untrügliches Zeichen für ein starkes [[Druiden|druidisches]] Potenzial war.\r\nFasziniert von der arkanen [[Magie]] erlernte er immer schwierigere Zauber, doch zu seiner Enttäuschung wollte ihn die Mondgarde trotz seiner Forschritte nicht aufnehmen. Trotzdem war Illidan wild entschlossen, der Held zu werden, den sein Volk erwartete. Schon bald fand er einen weiteren Grund, nach Größe zu streben. Eines Tages während eines Festes beobachtete er [[Tyrande]], wie sie in der Menge tanzte, und ihm wurde klar, das er sie liebte. Irgendwann hatte er sich, ohne es zu merken, in ihre Güte, ihr Lachen, ihre Schönheit und ihren Glauben verliebt. Seine Freude wurde nur von der Tatsache überschattet, dass auch [[Malfurion]] Gefühle für [[Tyrande]] hegte, obwohl dieser sich darüber nicht so schnell klar wurde wie Illidan. Illidan sah, dass Tyrande zweifellos entweder [[Malfurion]] oder Illidan als ihren Partner wählen würde. Die einzige Frage war, welcher Zwilling sich in ihren Augen als der Würdigere erweisen würde.\r\nIllidan verstärkte seine Anstrengungen, die arkane Zauberei zu meistern, und seine große Chance kam, als er durch Glück und schnelle Reaktion das Leben von Lord Kur'talos Rabenkrone retten konnte. Der dankbare Adlige machte Illidan zu seinem persönlichen [[Hexenmeister]] und hatte großes Vertrauen in Mut und [[Magie]] seines jungen Schützlings. Unglücklicherweise war der [[Dämon]], der Rabenkrone fast umgebracht hatte, nur der erste von vielen, die überall in [[Kalimdor]] auftauchten. Die erste Invasion der [[Brennende Legion|Brennenden Legion]] hatte begonnen.\r\n===Der Krieg der Urtume===\r\n[[Kur'talos Rabenkrone]] formte aus den [[Nachtelfen]] eine Armee, um gegen die einfallenden [[Dämon]]en zu kämpfen. Als [[Latosius]], der Ranghöchste der [[Mondgarde]], im Kampf fiel, ergriff Illidan die Gelegenheit und riss die Führung der überlebenden [[Magier]] an sich. Er setzte ihre vereinten Kräfte mit spürbarer Wirkung ein und tötete viele [[Dämon]]en der [[Brennende Legion|Legion]]. Trotzdem sah der Krieg immer hoffnungsloser aus, da mehr und mehr Verstärkungen für die [[Brennende Legion|Legion]] aus dem wirbelnden [[Nether]] eintrafen.\r\nAn diesem kritischen Wendepunkt des Krieges ignorierte [[Malfurion]] einen direkten Befehl von [[Kur'talos Rabenkrone]] und verlies die [[Nachtelfen]]armee. Er begab sich auf eine gefährliche Reise: Er wollte die [[Drachen]] aufsuchen und sie um Hilfe bitten. Impulsiv nahm Illidan [[Tyrande]] beiseite und sagte, er könne nun nicht länger schweigen. Er gestand ihr seine Liebe und meinte, [[Malfurion]] sei durch seine Beschäftigung mit dem [[Druiden]]tum eindeutig dem Wahnsinn verfallen.\r\nDoch [[Tyrande]] machte sich Sorgen um [[Malfurion]] und wies Illidan zurück, der merkte, dass er zu spät gekommen war. Sie hatte ihre Wahl bereits getroffen, und ihr Erwählter hieß nicht Illidan. Wieder einmal hatte Malfurion problemlos ein Ziel erreicht, an dem Illidan gescheitert war. Dieses Mal war [[Malfurion]]s Sieg besonders bitter für seinen Zwilling, denn [[Malfurion]] selbst war sich seiner Gefühle für [[Tyrande]] noch nicht bewusst.\r\nDer Schmerz von Illidans unerwiderter Liebe verfolgte ihn, und er verfiel in finstere Grübeleien. Er konnte nicht wissen, dass er von Lord [[Xavius]] beeinflusst wurde, der inzwischen ein [[Satyr]] war, mit der Macht, Verderbnis zu säen. Schließlich verließ auch Illidan die [[Nachtelfen]]armee, aber er war auf einer anderen Mission. Er ging zu [[Sargeras]], dem Anführer der [[Brennende Legion|Brennenden Legion]].\r\nIllidan schwor dem düsteren [[Titanen]] die Gefolgschaft und erhielt von ihm im Gegenzug große Macht. [[Sargeras]] verbrannte Illidans Augen zu Asche und verlieh den verkohlten Augenhöhlen eine magisch verbesserte Sehfähigkeit. Außerdem versah [[Sargeras]] einen Großteil von Illidans Körper mit einem feinen eintätowierten Muster, das dem [[Nachtelfen|Nachtelf]] mächtige arkane Energie zur Verfügung stellte.\r\nFür diesen offensichtlichen Loyalitätswechsel nannte man Illidan später den Verräter. Doch auch wenn er der [[Brennende Legion|Brennenden Legion]] in gewissen Maße half, kämpfte er schließlich doch an der Seite von [[Malfurion]] und den anderen [[Nachtelfen]]. Er und [[Malfurion]] schlossen das Portal, das die [[Hochgeborene]]n des Palastes im [[Brunnen der Ewigkeit]] geöffnet hatten, und verhinderten so, dass [[Sargeras]] selbst [[Azeroth]] betreten konnte, welches das Ende der Welt bedeuten würde. Nur kurz bevor das Portal geschlossen wurde, rebellierte eine Gruppe [[Hochgeborene]]r gegen die [[Brennende Legion|Legion]] und schlossen sich, angeführt von [[Dath'Remar Sonnenwanderer]], der größten [[Nachtelfen]]armee an.\r\n===Ein Pfad in die Finsternis===\r\nDer Planet [[Azeroth]] war gerettet, aber die Magien des Brunnens waren zu schwer missbraucht worden, so dass er implodierte, wobei er den alten Kontinent [[Kalimdor]] in mehrere Stücke zerriss. Ein neuer Ozean entstand, und die verteidigenden Nachtelfen flohen vor den heranbrausenden Wassermassen. Erst am Berg [[Hyjal]] konnten die [[Nachtelfen]] schließlich anhalten; der Ozean war endlich zur Ruhe gekommen.\r\nKurz bevor der Brunnen aber implodierte, füllte Illidan noch mehrere Phiolen mit seinem mächtigen Wasser. Er war sicher, dass die [[Dämonen]] trotz des Sieges der [[Nachtelfen]] über die [[Brennende Legion]] eines Tages zurückkehren würden. Und trotz des gerade beendeten grausamen [[Krieg]]es war er sich sicher, dass nur die arkane Magie die [[Nachtelfen]] bei einer zweiten Invasion retten könnte. So suchte er einen abgelegenen See auf dem Berg [[Hyjal]] auf und schüttete drei der Phiolen hinein. So verwandelte er den See unwiderruflich in einen zweiten [[Brunnen der Ewigkeit]].\r\nEr dachte, sein Volk würde ihn als Helden feiern. Er irrte sich gewaltig.\r\nEine kleine Gruppe von [[Nachtelfen]], darunter auch einige reumütige [[Hochgeborene]], entdeckten, was Illidan getan hatte, und die meisten reagierten mit Entsetzen. Illidan fürchtete, die [[Hochgeborene]]n würden versuchen, die Macht des Brunnens für sich zu beanspruchen, wie sie es beim ersten [[Brunnen der Ewigkeit]] getan hatten, und so griff er die Gruppe an. Doch [[Malfurion]] tauchte wenige Augenblicke später auf und half, seinen heißblütigen Zwillingsbruder gefangenzunehmen.\r\nAls Illidans Bruder und geachtetem Kriegsheld gestattete man [[Malfurion]], über das Schicksal seines Bruders zu bestimmen. Bestürzt von Illidans Macht entschied [[Malfurion]], dass Illidan zu gefährlich und rücksichtslos sei, um in Freiheit zu bleiben. Doch [[Malfurion]] konnte seinen Bruder nicht einfach zum Tode verurteilen. Stattdessen erlegte er ihm eine Strafe auf, die Illidan wohl noch weitaus schlimmer erschien als der Tod: Illidan sollte den Rest seines unsterblichen Lebens in Gefangenschaft verbringen. Als Folge von Malfurions sogenannter Gnade schmachtete Illidan die nächsten zehntausend Jahre isoliert in einer Gefängniszelle tief unter der Erde, bewacht von den [[Behüter]]n.\r\n===Verlorene Seele: Der Dritte Krieg===\r\nIllidans Befürchtungen bewahrheiteten sich: Während des [[Der Dritte Krieg|Dritten Krieges]] fiel die [[Brennende Legion]] erneut in [[Azeroth]] ein. [[Tyrande]] erweckte als Oberhaupt der [[Nachtelfen]]regierung [[Malfurion]] aus seinem Traumschlaf, und zusammen gingen sie in das unterirdische Labyrinth, um die anderen [[Druiden]] zu wecken. Dabei stolperte [[Tyrande]] über den Eingang zu Illidans Gefängnis, und sie entschloss spontan, dass er ein starker Verbündeter sein könnte. Obwohl [[Malfurion]] versuchte sie aufzuhalten, führte sie ihre [[Schildwache]]n in den Kerker. Die Behüter weigerten sich, ihren Gefangenen kampflos zu übergeben, und so töteten [[Tyrande]] und ihre Soldatinnen die Wachen, die ihr den Weg zu Illidans Zelle versperrten. Sie sagte Illidan, dass sein Volk ihn erneut brauche im Kampf gegen die [[Brennende Legion]].\r\nIllidan stimmte zu, wieder gegen die Legion zu kämpfen. Doch er war durch seine lange und - wie er glaubte - ungerechtfertigte Einkerkerung verbittert. Er machte [[Tyrande]] klar, dass er nicht wegen irgendeiner noch vorhandenen Spur von Loyalität gegenüber seinem Volk kämpfen werde, sondern nur um ihretwillen. Er folgte [[Tyrande]] nach oben in den verderbten [[Teufelswald]]. [[Tyrande]] und ihre Soldaten machten sich auf die Suche nach [[Malfurion]], der die letzten schlafenden [[Druiden]] aufwecken wollte. Sie war sicher, wenn sie [[Malfurion]] erzählen würde, dass Illidan wieder frei war, würde er seinem Zwillingsbruder eine zweite Chance geben.\r\nKaum war Illidan alleine, tauchte der Todesritter [[Arthas]] Menethil bei ihm auf, der ihm von einem magischen Artefakt erzählte, mit dessen Hilfe die [[Dämon]]en die Verderbnis im [[Teufelswald]] verbreiteten: dem Schädel von Gul'dan. [[Arthas]]' Herr, der [[Lichkönig]], wäre dankbar, wenn Illidan den [[Dämon]]en dieses Artefakt stehlen würde. Außerdem deutete [[Arthas]] an, Illidan könne eventuell die Kräfte des Artefakts übernehmen. Illidan hungerte immer noch nach [[Magie]], und so tat er genau, was [[Arthas]] vorgeschlagen hatte. Er stahl das Artefakt und nahm seine Kräfte in sich auf. Da er seit dem [[Krieg der Urtume]] bereits das Mal von [[Sargeras]] trug, verwandelte sich Illidan augenblicklich in einen [[Dämon]]en, als er die finstere [[Magie]] des Schädels aufsog.\r\nMit seiner neugewonnenen Macht vernichtete er den Schreckenslord [[Tichondrius]], den Anführer der [[Dämon]]en, die den [[Teufelswald]] entstellt hatten. Kurz nach diesem Sieg kehrten [[Malfurion]] und [[Tyrande]] zurück und trafen auf Illidan. Zuerst erkannte keiner der beiden [[Nachtelfen]] den mächtigen [[Dämon]]en als Illidan. Als sie herausfanden, was geschehen war, verdammte [[Malfurion]] seinen zum Monstrum gewordenen Bruder. [[Malfurion]], auf dessen Schultern immer noch die Verantwortung für Illidans Bestrafung lastete, verurteilte ihn zum Exil, fernab von allen Ländern der [[Nachtelfen]].\r\nDiese erneute Bestrafung verwunderte Illidan nicht. [[Malfurion]] hatte sich noch nie mit anderen Mächten neben seiner oder der [[Tyrande]]s wohlgefühlt. Sollte sich Illidans selbstgerechter Zwilling mit diesen sogenannten \"sicheren\" [[Magie]]n zufriedengeben. Soll er in seinen kostbaren [[Smaragdgrünen Traum]] wandeln während das Leben [[Azeroth]]s an ihm vorbeiging. Illidan würde sich niemals mit einem solch lebenden Tod zufrieden geben. Selbst wenn Illidan alles andere verboten wurde, er würde Macht haben.\r\n===Das Bündnis mit den Naga===\r\nViele Monate nach der Niederlage der [[Brennende Legion|Legion]] am Berg [[Hyjal]] kam der [[Dämon]]enfürst [[Kil'jaeden]] zu Illidan. Der [[Dämon]] bot ihm alles, was er sich wünschte, als Gegenleistung für einen einzigen Dienst: Illidan sollte den [[Lichkönig]] vernichten, der die [[Brennende Legion]] betrogen hatte, als er Arthas zu seinem persönlichen Favoriten und Anführer der [[Geißel]] machte. Angesichts [[Kil'jaeden]]s überwältigender Macht hatte Illidan keine andere Wahl, als einzuwilligen. Er beschwor also eine große Gruppe [[Naga]] aus den Tiefen des Ozeans empor, darunter auch [[Vashj|Lady Vashj]]. Die [[Naga]], die einst [[Hochgeborene]] gewesen waren, erkannten Illidan wieder und respektierten seine magischen Kräfte, die inzwischen sogar größer waren, als sie sie in Erinnerung hatten. Sie waren einverstanden, sich mit ihm zu verbünden.\r\nIn der Zwischenzeit hatte Aufseherin [[Maiev Schattensang]] entdeckt, dass Illidan befreit worden war, und voller Zorn schwor sie, ihn wieder einzufangen. Mit ihren Behütern verfolgte sie ihn durch den Wald von [[Eschental]] und über das Meer zu den Zerbrochenen Inseln, wo Illidan und seine [[Naga]]verbündeten das Grabmal von [[Sargeras]] betraten. Maiev holte Illidan ein, gerade als er das Auge von [[Sargeras]] an sich nahm. Im Kampf gegen seine früheren Gefängniswärterinnen setzte Illidan die Macht des [[Dämon]]enartefakts ein. Er entkam, doch die Behüter waren in einem Abschnitt des Grabmals gefangen - einem Abschnitt, der sich schnell mit Meerwasser füllte. Von allen Behütern in dem Grabmal entkam nur [[Maiev Schattensang|Maiev]] dem Tod durch Ertrinken. Die mit Illidan verbündeten [[Naga]] griffen Maievs stark dezimierte Truppe wiederholt an, doch [[Maiev Schattensang|Maiev]] sandte einen Boten zu [[Malfurion]] und bat ihn um Hilfe. [[Malfurion]] und [[Tyrande]] kamen noch rechtzeitig, um die Aufseherin zu retten, doch Illidan entkam seiner Gefangennahme.\r\nDie drei [[Nachtelfen]] folgten Illidan nach [[Lordaeron]], wo Illidan und mehrere [[Naga]][[magier]] begannen, einen mächtigen Zauber mit Hilfe des Auges von [[Sargeras]] zu fokussieren. [[Malfurion]] und Maiev kamen rechtzeitig dazu, um den Zauber zu unterbrechen. Illidan erklärte ihnen, dass er versucht habe, den Frostthron zu zerstören, doch seinen Pakt mit [[Kil'jaeden]] erwähnte er mit keinem Wort. Was auch nichts geändert hätte, denn Illidan hatte auf jeden Fall versagt, und damit war seine Abmachung mit dem [[Dämon]]en hinfällig. Und die [[Brennende Legion]] kannte wenig Mitleid mit Versagern.\r\nBald darauf erfuhren [[Malfurion]] und Illidan, dass [[Tyrande]] und eine kleine Gruppe ihrer Schildwachen den Fluss Arevass hinunter getrieben und von der [[Geißel]] angegriffen worden waren. Illidan liebte [[Tyrande]] immer noch, und so bot er umgehend seine Unterstützung an. [[Tyrande]] zuliebe stimmte [[Malfurion]] zögernd zu, mit Illidan zusammenzuarbeiten. [[Malfurion]] errichtete und verteidigte einen [[Nachtelfen]]-Stützpunkt, während Illidan mit seinen [[Naga]] [[Tyrande]] und ihre Soldatinnen rettete. Als Gegenleistung für seine Hilfe bei [[Tyrande]]s Rettung begnadigte [[Malfurion]] seinen Bruder wieder. Doch er warnte Illidan, nie wieder den [[Nachtelfen]] zu schaden. Illidan versprach es und öffnete ein Portal in die [[Scherbenwelt]], wo er sich vor dem Zorn von [[Kil'jaeden]] verstecken wollte.\r\n===Fürst der Scherbenwelt===\r\nDoch [[Maiev]] war zerfressen von ihrem Verlangen nach Rache und konnte die Jagd nicht einfach aufgeben. Mit einer kleinen Gruppe von Kämpferinnen folgte sie Illidan durch das Portal. Illidan hatte nur wenige Krieger bei sich und wurde schließlich besiegt und gefangengenommen. Doch er war nur deswegen zahlenmäßig unterlegen, weil er [[Vashj|Lady Vashj]] und ihre [[Naga]] fortgeschickt hatte, um weitere Verbündete anzuwerben: Prinz [[Kael'thas]] Sonnenwanderer und die [[Blutelfen]]. Die [[Blutelfen]] folgten den [[Naga]] zur [[Scherbenwelt]] und befreiten Illidan, der dafür versprach, ihnen zu zeigen, wie sie ihre [[Magie]]sucht befriedigen konnten. Prinz [[Kael'thas]] schwor Illidan die Gefolgschaft und half seinem neuen Fürsten, alle Portale zur [[Scherbenwelt]] zu schließen. Dadurch hoffte Illidan, weitere dämonische Verstärkungen aus dem Wirbelnden [[Nether]] abzuschneiden und alle Versuche [[Kil'jaeden]]s zu vereiteln, ihn zu finden.\r\nDer damalige Herrscher der [[Scherbenwelt]], ein Grubenlord namens [[Magtheridon]], wurde sein nächstes Ziel. Unter der Führung von [[Akama]] schlossen sich viele der [[Draenei]] aus der [[Scherbenwelt]] Illidans Kampf gegen den [[Dämon]]en an. Mit einer gewaltigen Streitmacht aus [[Blutelfen]] und [[Naga]] zog Illidan gegen [[Magtheridon]], besiegte ihn und übernahm seine Festung, den [[Schwarzer Tempel|Schwarzen Tempel]]. Doch Illidan konnte seine Eroberung nicht lange feiern. In einem Gewitter aus [[Magie]] und Zorn stieg [[Kil'jaeden]] auf die [[Scherbenwelt]] herab, obwohl Illidan alle Portale auf dem Planeten hatte verschließen lassen. Illidan hatte die Macht des [[Dämon]]enfürsten kolossal unterschätzt.\r\nNicht lange um eine Ausrede verlegen, erzählte Illidan [[Kil'jaeden]], er habe sich nur in die [[Scherbenwelt]] zurückgezogen, um seine Truppen zu verstärken, bevor er den nächsten Angriff auf den [[Frostthron]] wagen wollte. [[Kil'jaeden]] ließ sich davon kaum beeindrucken, beschloss aber, Illidan noch eine letzte Chance zu geben. Er warnte Illidan jedoch, dass erneutes Versagen unweigerlich seinen Tod bedeuten würde. Illidan blieb keine andere Wahl, und so führte er die [[Naga]] und [[Blutelfen]] zurück nach [[Azeroth]]. Die [[Geißel]] hielt Illidans Armee in Schach, bis [[Arthas]] und der Gruftfürst [[Anub'arak]] erschienen. Schließlich kam es zum Zweikampf zwischen Illidan und dem Todesritter [[Arthas]] Menethil, und [[Frostgram]] prallte gegen die [[Zwillingsgleven von Azzinoth]]. [[Arthas]] gewann und warnte Illidan, er solle [[Azeroth]] verlassen und niemals zurückkehren. Seitdem ist Illidan zum [[Schwarzer Tempel|Schwarzen Tempel]] zurückgekehrt. Während seine Verbündeten in der [[Scherbenwelt]] darum kämpfen, die Portale verschlossen zu halten, bereitet sich Illidan auf den Tag vor, an dem [[Kil'jaeden]] kommen wird, ihn dafür zu bestrafen, den [[Lichkönig]] nicht zerstört zu haben.\r\n===Illidan der Dämon===\r\nWie bei einigen [[Dämon]]en bekannt, betrachtet sich auch Illidan nicht als Diener der [[Brennende Legion|Brennenden Legion]]. Vielmehr war Illidan ja in der Vergangenheit abwechselnd Verbündeter und Feind der [[Brennende Legion|Legion]]. Was allerdings bei [[Dämon]]en eher unüblich ist: Er behielt trotz seiner Verwandlung in einen Dämonen noch viele Wesenszüge seiner früheren Persönlichkeit. Als Dämon ist er zwar grundsätzlich böse und oft grausam, doch er hat es bislang geschafft, sich ein paar ehrenwerte Züge zu bewahren. Deren unvermeidlicher Konflikt mit seinem Ehrgeiz und seinem Machthunger machen ihn zu einem gefährlich unberechenbaren Gegner. Da Illidans Fall so einzigartig ist, hat es auch keinen Zweck, darüber zu spekulieren, wie lange sein für einen [[Dämon]]en untypisches Benehmen anhalten wird. Mit seiner riesigen Armee von Verbündeten wäre er eine tödliche Bedrohung für [[Azeroth]], falls er jemals ein gehorsamer Diener der [[Brennende Legion|Legion]] würde.\r\n'''Quelle:''' wow-europe.com",},
			["Illidari"] = { content = "'''Die Illidari''' sind die Anhänger [[Illidan]]s in der [[Scherbenwelt]]. Ihr Ziel ist es, die [[Scherbenwelt]] zu kontrollieren und ihren Meister Illidan an der Macht zu halten. Dabei gehen sie rabiat gegen alljene vor, die ihren Plänen gefährlich werden können. \r\n==Beschreibung==\r\nUm ihre Ziele zu erreichen, haben die Illidari sämtliche Dimensionsportale, die [[Ner'zhul]] einst mit dem [[Zepter des Sargeras]] öffnete, versiegelt, um die [[Brennende Legion]] fernzuhalten. Die Illidari sind mit den [[Sha'tar]] verfeindet, die sie als Bedrohung ihrer Macht empfinden. Doch auch mit der Legion stehen sie nicht gut. So mit ist es nicht verwunderlich, dass viele Illidari insgeheim eigene Pläne haben, die nicht immer mit denen Illidans übereinstimmen. \r\n===Armee der Illidari===\r\n* Siehe auch: [[Rat der Illidari]] im [[Der Schwarze Tempel|Schwarzen Tempel]]\r\n* Siehe auch: [[Purpursiegel]]\r\nDen Illidari dienen die [[Naga]], die [[Blutelfen]], diverse [[Dämonen]], die [[Zerschlagene]]n Akamas und die [[Orcs des Drachenmals]] unter [[Zuluhed]]. Ebenso stecken die Illidari hinter den neuen [[Höllenorcs]], welche ihnen ebenfalls dienen. Einer der prominentesten Verbündeten der Illidari ist [[Teron Blutschatten]].\r\n===Reittiere===\r\n* '''' - Art: [[Teufelsjäger]]. Promotion: [[World of Warcraft: Legion]] Collector's Edition. \"Die Illidari haben einige der niederen Dämonen gebrochen, um sie gegen deren Herren einzusetzen.\"\r\n==WoW: Legion==\r\nIn [[WoW: Legion]] kehren die Illidari als Fraktion der [[Dämonenjäger]] zurück und sind in der [[Teufelshammer]] zu finden. Diese Elfen haben sich dem Kampf gegen die Brennende Legion verschrieben – koste es, was es wolle. Sie kontrollieren die verbotenen Kräfte der Dämonen, die sie vernichten, um damit die Mächte des Chaos zu bekämpfen – und dabei scheuen sie vor nichts zurück. \r\nDie Adepten der Illidari können außerdem als Hilfstruppen der [[Teufelshammer]] rekrutiert werden. Um die Brennende Legion noch wirkungsvoller vernichten zu können, machen sich die Dämonenjäger der Illidari die Macht der Dämonen zu eigen, wobei sie ihr elfisches Aussehen opfern. \r\nAls einer der neuesten Rekruten der Illidari beginnt die Reise der ''[[Dämonenjäger]]'' auf Stufe 98 im dämonenverseuchten [[Mardum]]. Während ihr euch euren Weg durch dieses gefährliche Land bahnt, macht ihr euch mit den Fähigkeiten der Dämonenjäger und ihrer Geschichte vertraut. Ihr habt euch für diesen Pfad entschieden und werdet auch lernen, die damit verbundene Macht zu nutzen. Doch seid gewarnt – nicht jeder Illidari wird es schaffen. Stellt euch selbst die Frage: Welche Opfer seid ihr bereit zu bringen, um Azeroth vor der Brennenden Legion zu retten? \r\n* Lies mehr unter: '''' (06. August 2016)",},
			["Illidarifürst Balthas"] = { content = "'''Illidarifürst Balthas''' ist ein [[Man'ari]] [[Eredar]] im [[Basislager des Drachenmals]] im [[Schattenmondtal]]. Er ist der Bruder von [[Reth'hedron der Unterdrücker]], welcher auf der [[Zwielichthöhe]] in [[Nagrand]] herrscht.",},
			["Illusionenrennbahn"] = { content = "Die Illusionenrennbahn ist eine Rennstrecke auf der [[Schimmernde Ebene |Schimmernden Ebene]] in [[Tausend Nadeln]], auf der sich [[Goblins]] und [[Gnome]] tägliche Rennen liefern. \r\nBei den vielen Rennen, die hier stattfinden, ist es nicht verwunderlich, wenn dabei ein paar Unglücksfälle passieren. Wenn man sich in der schimmernden Ebene umschaut, sieht man ständig Spuren vergangener Unfälle - überall liegen Teile von Raketenwagen herum. Und diese Teile bedeuten für die [[Gnome]] und [[Goblins]] bares Geld. Sie suchen ständig nach weiteren neumodischen Apparaten, um sie an ihre Autos anzubauen.\r\n= Die Teams =\r\nDie Gebrüder Kupferbolz treten mit ihrem Gnomenteam in Raketenwagenrennen gegen die [[Goblins]] an. Normalerweise gewinnen sie, aber das ist keine große Überraschung - der Wagen der [[Goblins]] fliegt so oft in die Luft, dass er es kaum jemals über die Ziellinie schafft. \r\n===Gnomenteam===\r\nDie Kupferbolz-Brüder suchen ständig nach neuen Möglichkeiten, ihren Wagen noch schneller zu machen. Die [[Gnome]] möchten daher neue Teile bestellen. Diese Teile wurden vor einer Woche nach [[Ratschet]] geschickt, aber es war noch niemanden möglich, dorthin zu reisen und sie abzuholen. \r\n===Goblinteam===\r\nDas Rennfahrerteam ist der Stolz aller [[Goblins]]. [[Gazlowe]] treibt auf der ganzen Welt Ersatzteile für sie auf. Er kam sogar mal her, um an einer der Aufhängungen zu arbeiten. Vor ein paar Wochen wollte er den Prototyp einer neuen Treibstoffeinspritzpumpe schicken, aber sie ist noch nicht eingetroffen. Sonst ist er immer zuverlässig. Nach dem schweren Zusammenstoß des Red-Thunder-Rennwagen der [[Goblins]] und einem [[Basilisk]]en hat Kronkreiter Rennstreckenleiter Zherin angeheuert, um die Strecke zu warten.\r\n= Personen =\r\n==Die Kupferbolzbrüder==\r\nDa draußen sind [[Wizzle Kupferbolz]] und seine [[Gnome]]nbrüder, die ihren neuen Raketenwagen erproben, und soweit man gehört hat, ist er schnell. So schnell, dass die Fahrer immer verunglücken. Und Gehirnerschütterungen bekommen. Darum baten sie um ein paar Helme für Belagerungsmaschinen, denn wenn es um Rennen geht, zählt jede Kleinigkeit. Ob es sich nun um ein leises Quietschen der Kraftübertragung, eine geringfügige Schwäche der Stoßdämpfer oder ein leichteres Gewicht der Karosserie handelt, man muss alles berücksichtigen. Die Kupferbolzbrüder haben auch einen neuen Baustoff entdeckt. Ihre Rennwagen fahren schneller als vorher, aber Design und alle anderen Daten ihrer Probefahrten sind noch dieselben. \r\n===Rizzle Kupferbolz===\r\n[[Rizzle Kupferbolz]] befasst sich fast ununterbrochen mit den Plänen seiner neuen Entdeckung. Rizzles Baupläne beschreiben den Vorgang der Veredelung von [[Indurium]]erz. Man kann dem Gekritzel entnehmen, dass Induriumerz an der Ausgrabungsstätte [[Uldaman]] der [[Zwerge]] im Ödland zu finden ist. Die anderen Notizen behandeln fast ausschließlich seinen Hitzewiderstand. Als Briefbeschwerer der Pläne dient ein Klumpen, der wie unbearbeitetes [[Indurium]]erz aussieht.\r\n===Wizzel Kupferbolz===\r\nIhr Raketenwagen ist das schnellste, was es auf der Ebene gibt. So schnell, dass [[Wizzel Kupferbolz]] fürchtet, die Reibung reißt ihn auseinander. Um das zu verhindern, muss er einen Stoff entwickeln, der die beweglichen Teile des Wagens überzieht. Er muss hart sein, aber nicht spröde, und er muss resistent gegen Salzkorrosion sein, sonst wird der Wagen, während er sich in der schimmernden Ebene befindet, zerfressen. Sein Bruder [[Zischel Kupferbolz]] arbeitet an einem neuen Treibstoff für seinen Raketenwagen. Er ist brillant, ehrlich. So brillant, dass... Wizzel glaubt, der neue Treibstoff, den er da entwickelt, ist stark genug, um sich durch das Chassis des Wagens zu fressen. Wizzel würde deswegen gern die Treibstofftanks verstärken, bevor das passiert. Die [[Schildkröten]] draußen auf der Ebene haben sehr starke Panzer. Er möchte daraus neue Tanks für den Raketenwagen bauen. Tanks, die den neuen Treibstoff seines Bruders aushalten.\r\n===Zischel Kupferbolz===\r\n[[Zischel Kupferbolz]] hat so viele Pläne für den Raketenwagen. Und er muss sie alle ausprobieren. Er arbeitet gerade an einem neuen Treibstoff; an einem, der wirklich, wirklich, wirklich heiß ist. Die Mixtur stimmt zwar noch nicht ganz, aber er glaubt, er weiß, was noch fehlt. Er entwicklt ebenso einen neuen Motor, mit dem der Wagen so schnell wie der Wind wird. Schnell genug, um zu fliegen. Er muss nur ein paar Kolben herstellen, die sehr, sehr große Belastungen aushalten. All seine bisherigen Versuche sind fehlgeschlagen, weil er die Kolben einfach nicht robust genug herstellen kann. Deshalb bittet er einen berühmten Schmied, [[Martek der Verbannte|Martek den Verbannte]], im [[Ödland]] um Hilfe.\r\n==Kravel Kohlebart==\r\n[[Kravel Kohlebart]]s Job ist es, den Leuten zu beschaffen, was sie möchten. Er hat eine Sendung für einen alten Kunden, [[Hemet Nesingwary Jr.]]. Die Sendung war wochenlang unterwegs und Hemet ist schon längst wieder weg. Er fragt sich auch, weshalb [[Nazz Kesseldampf]] seinen Namen änderte. Ob es wohl ein Geheimnis ist und wie viel ihm dieses Geheimnis wert ist.\r\nKravel hat viel Zeit in der schimmernden Ebene verbracht, und sein geplantes Unternehmen befasst sich mit den Völkern auf dieser Ebene. Die über die Ebenen rasenden Raketenwagen benötigen aufgrund ihrer hochsensiblen Technik ständige Wartung. So ist es kein Wunder, dass die Mechaniker ständig vor Ort sind. Sie testen die Wagen permanent und nehmen nötigenfalls Veränderungen und Reparaturen daran vor. Anders lassen sich die Wagen nicht im Bestzustand halten. Sie brauchen daher ein Mittel, um eine der Boxencrews zu Fehlern zu zwingen. Dann wird ihr Wagen das Rennen nicht durchstehen.\r\nWenn sie bestimmen können, welcher Wagen gut fährt und welcher nicht, dann hätte das einige Vorteile bei den Wetten. Daher möchte Kravel von [[Crank Zischelbub]] in [[Beutebucht]] ein Mittel, um die Mechaniker zu Fehlern zu zwingen. Vielleicht gibt es im Schlingendorntal Pflanzen, Kräuter oder Getränke, mit denen sich die Gnome und Goblins benebeln ließen. \r\n==Pozzik==\r\n[[Pozzik]] ist ein toller Mechaniker, aber er hat Angst davor, einfach was mit viel Power einzubauen und dann loszudüsen. Sie benutzen [[Geier]]knochen für kleinere Modifikationen am Chassis der Rennwagen, die das perfekte Gleichgewicht zwischen Stärke und Gewicht haben. Und sie sind, was noch besser ist, leicht zu beschaffen, da es in der Salzwüste von [[Geier]]n wimmelt. \r\n==Razzeric==\r\n[[Razzeric]] ist der achtzehnte Fahrer des Goblinsteams und er nimmt selbst gern Veränderungen an den Rennwagen vor. Er ist ein wenig daneben. Er hat einen [[Zephyrium]]nachbrenner von [[Kainer]] im [[Gizmorium]] in [[Gadgetzan]] bestellt, aber offenbar musste der [[Zeppelin]], mit dem er geschickt wurde, in den [[Düstermarschen]] notlanden. [[Kainer]] hatte die Sicherung des Brenners aktiviert gelassen, doch das reduzier die Menge Energie, die man aus dem Nachbrenner rausholen kann. [[Razzeric]] sagte ihm, er wollte sie deaktiviert haben, also muss man den Brenner ins [[Gizmorium]] nach [[Gadgetzan]] in der Tanariswüste bringen und es von [[Kainer]] entfernen lassen.",},
			["Immerruhsee"] = { content = "Der Immerruhsee im [[Rotkammgebirge]] ist für seinen gefleckten Sonnenfisch berühmt. Die Nachfrage nach diesen Fischen ist enorm hoch. Doch Eltern möchten nicht, dass ihre Kinder im See schwimmen. Sie sagen, dass es unter Wasser ein paar garstige Dinge gibt - [[Murlocs]]. Und sie werden zu einem Problem, denn große Gruppen der Fischwesen werfen entlang der Ufer des Immerruhsees ankern und fischen, was das Zeug hält.\r\nWährend der letzten Invasion der [[Orcs]] waren die [[Menschen]] von [[Seenhain]] gezwungen, das Eisen der Brücke einzuschmelzen, um Kugeln, Schwerter und Rüstungen herzustellen. Sie haben [[Sturmwind]] benachrichtigt, dass sie eine neue Lieferung Materialien benötigen. Aber eine Bande von Rotkammgnollen hat die Karawane überfallen und sich dann in die Hügel hinter Seenhain zurückgezogen. Jetzt gehen ihnen langsam die Vorräte aus, die sie brauchen, um die Brücke wieder aufzubauen.",},
			["Immersangwald"] = { content = "Der '''Immersangwald''' mit der Hauptstadt der [[Blutelfen]] [[Silbermond]], befindet sich im Norden des Kontinents [[Lordaeron]] und gehört zu [[Quel'Thalas]]. \r\n==Allgemeines==\r\nDie Schönheit des Waldes bildet einen starken Kontrast zu den Schrecken der [[Todesschneise]]: einer entsetzlichen Wunde, die die Stadt [[Silbermond]] in zwei Hälften spaltet. Sie bildet ein ewig währendes Mahnmal für die Grausamkeit [[Arthas]]’ und der [[Geißel]]. Das Land und die Blutelfen sind gezeichnet von den Angriffen der [[Geißel]] und die siechende Fraktion braucht dringend neue Helden. Selbst [[Nachtelfen]]abschaum dringt in ihre Länder ein, um hier zu wildern und auch die andauernden Scharmützel mit den [[Amani]] haben die Versorgung der [[Blutelfen]] mit Ausrüstung stark strapaziert. Die Bachtatzen-Luchse in dieser Region sind für Ihre hochwertigen Pelze bekannt, leider finden die [[Waldläufer]] aufgrund der Probleme kaum Zeit für die Pelzjagd.\r\n===World of Warcraft: Cataclysm===\r\nSchon seit Jahrtausenden nennen die Blutelfen den prächtigen Immersangwald ihr Zuhause, doch die Aufsicht über dieses grüne Stück Land ist nicht ohne Gefahren. Versessen auf die Macht des mystischen Sonnenbrunnens der Elfen schlugen Prinz Arthas und die Geißel sich im Dritten Krieg einen Pfad mitten durch das Herz von Quel’Thalas und hinterließen eine verderbte Name im Immersangwald. Die Elfen haben bereits höchste Anstrengungen unternommen, um die lauernden Untoten aus ihrem Land zu vertreiben und die Wunden durch Arthas’ Angriff zu heilen, doch ihre Aufgabe ist noch lange nicht erfüllt. Die Sicherheit und Unversehrtheit des Immersangwalds ist ein wichtiger erster Schritt auf dem Weg in Quel’Thalas’ neue Zukunft.",},
			["Immol'thar"] = { content = "Immol'thar ist ein [[Schrecken der Leere]], ein verdorbener [[Dämonen]]hund, der in [[Düsterbruch]] gefangen gehalten wird. Man muss alle Wächter zerstören, die um die 5 [[Pylon]]en herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die [[Pylon]]en deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.",},
			["Imperator Dagran Thaurissan"] = { content = "'''Imperator Dagran Thaurissan''' ist der Anführer der [[Dunkeleisenzwerge]] in den [[Schwarzfelstiefen]]. Vor kurzem entführte er die Tochter des [[Magni Bronzebart|Zwergenkönigs]]: [[Moira Bronzebart]] und machte sie zu seiner Geliebten.\r\n==Geschichte==\r\nVor 300 Jahren begannen die [[Dunkeleisenzwerge]] den [[Krieg der drei Hämmer]] gegen seine zwergischen Brüder, den [[Bronzebart Klan]] und den [[Wildhammerklan]]. Imperator Dagran Thaurissan, der Führer der [[Dunkeleisenzwerge]], belagerte und zerstörte [[Grim Batol]], die Hauptstadt des [[Wildhammerklan]]s. Doch damit war der Kampf noch nicht vorbei, denn trotz dieses Sieges griffen nun die vereinten Wildhämmer und Bronzebärte den [[Dunkeleisenklan]] und Thaurissan an und drängten diesen bis zum [[Schwarzfels]] zurück. \r\nThaurissans einzige Möglichkeit war es, Hilfe zu finden, um die anderen Klans zu vertreiben. Er versuchte einen übernatürlichen Günstling zu beschwören, der das Kriegsgeschick zu seinen Gunsten wenden würde; und so rief er die uralten Kräfte herbei, die unter der Welt schliefen. Zu Thaurissans Überraschung und schließlich zu seinem Verderben, war die Kreatur, die auftauchte schrecklicher als jeder Alptraum, den er sich hätte vorstellen können: [[Ragnaros]]. \r\nUnd jetzt durch Thaurissans Ruf befreit, brach der Feuerlord wieder in die materielle Existenz. \r\n[[Ragnaros]]' apokalyptische Wiedergeburt auf [[Azeroth]] zerschmetterte den [[Schwarzfels]]berg und erschuf im Zentrum der Verwüstung einen tobenden Vulkan. Der Vulkan, bekannt als [[Schwarzfelsspitze]], wurde im Norden durch das, was jetzt als die [[Sengende Schlucht|Sengenden Schlucht]] bekannt ist, begrenzt und im Süden durch die [[Brennende Steppe]]. \r\nMan dachte lange, Thaurissan sei durch die Kräfte, die er entfesselt hatte, getötet worden. Doch er und seine überlebenden Klanbrüder wurden durch [[Ragnaros]] versklavt und blieben innerhalb der unteren Gebiete des Berges, besonders in den [[Schwarzfelstiefen]].",},
			["Incendius"] = { content = "#REDIRECT [[Lord Incendius]]", redirect = "Lord Incendius",},
			["Indirium"] = { content = "#REDIRECT [[Indurium]]", redirect = "Indurium",},
			["Indurium"] = { content = "Indirium ist ein seltenes Metall und soll angeblich sehr hohen Widerstand gegen Hitze und Belastung bieten. Echtes Induriumerz muss von einem [[Bergbau]]er tief in den Minen von [[Uldaman]] abgebaut werden, aber die Steingruft[[troggs]] des [[Ödland]]es tragen manchmal Späne davon mit sich herum.",},
			["Ingenieure"] = { content = "#REDIRECT [[Ingenieurskunst]]", redirect = "Ingenieurskunst",},
			["Ingenieurskunst"] = { content = "==Allgemeines==\r\nMit Ingenieurskunst können Metall und Stein zu Bauteilen weiterverarbeitet werden, aus denen dann Sprengstoffe, Feuerwaffen, Zielfernrohre, Kugeln, mechanische [[Drachen]], Tauchhelme, und vieles Andere hergestellt werden kann. In der Ingenieurskunst stehen zwischen den ursprünglichen Rohstoffen und dem fertigen Produkt noch viel mehr Schritte als bei den anderen Berufen. Bomben und Dynamit sind die meistbenutzten Erzeugnisse des Ingenieurs. Viele Anleitungen für Ingenieure benötigen einen Haufen verschiedener Bestandteile, bevor der ersehnte Gegenstand hergestellt werden kann. Die Ingenieurskunst ist ein sehr kreatives Handwerk: Man kann damit alle möglichen verrückten Sachen herstellen, die andere amüsieren oder auch erstaunen werden.\r\nEin [[:Kategorie:Charakter|Charakter]], der sich mit der Ingenieurskunst beschäftigen will, sollte vorher schon Erfahrung im [[Bergbau]] gesammelt haben. [[Bergbau|Bergmänner]] sammeln Erz und formen daraus Barren, die für die Herstellung der meisten Ingenieursgegenstände benötigt werden. Für Ingenieursanleitungen werden oft auch Juwelen benötigt, die man an einer Vielzahl von Orten finden kann. In der Regel werden Ingenieure diese seltenen Edelsteine entweder kaufen oder sie von wirklich guten Freunden geschenkt bekommen. Für andere Anleitungen benötigt man Leder, das man zum Beispiel bei einem [[Kürschner]] oder [[Lederer]] kaufen kann. Allerdings gibt es noch viele andere Arten von Materialien, die man nicht so leicht kaufen kann; in dem Fall heißt es entweder mit anderen Spielern tauschen, oder sich auf in die Wildnis machen und dort sein Glück versuchen. Manche Materialien kann man sogar aus dem Wasser fischen!\r\n'''Quelle:''' wow-europe.com\r\n===Wissenswertes===\r\nAuch [[Azeroth]] kann sich nicht vor dem technischen Fortschritt der Zeit retten. Teilweise verrückte [[Gnome]] und [[Goblins]] haben es sich zur Aufgabe gemacht, ständig irgendwelche neuen Dinge zu erfinden. Dabei rückt die praktische Wirkung manchmal in den Hintergrund, aber '''Hauptsache es zischt und knallt'''. Es ist keine Seltenheit das die Entwickler neuer Erfindungen bzw. die Nutzer von bekannten Werkzeugen sich die ein oder andere Falle bauen, selbst von Todesfällen unter der Ingenieurschaft ist die Rede. Doch wie so oft liegen Wahnsinn und Genie sehr nahe beieinander, ohne die Ingenieure von [[Azeroth]] wäre die U-Bahn zwischen [[Sturmwind]] und der [[Eisenschmiede]] wohl nie gebaut worden.\r\nSobald man den Wunsch hat Ingenieur zu werden, wendet man sich an die Wache seines Vertrauens und fragt, mit dem gebotenen Respekt, nach dem Weg zum nächsten qualifizierten Ausbilder welcher die Ingenieurskunst lehren kann. Ist man beim Lehrer angekommen, spricht man diesen an und bestätigt, dass man den aufgeführten Beruf auch wirklich ausüben möchte. Jetzt heißt es nur noch bei einem Handwerker-Händler (meist in der Nähe von Lehrern zu finden) einen Schmiedehammer kaufen und die Karriere kann beginnen.\r\nNun gilt es, entweder mit [[Bergbau]] die benötigten Metalle, Edelsteine und Steine zu besorgen, oder mit Hilfe Anderer an die benötigten Rohstoffe zukommen. Hat man seine Rohstoff-Besorgungsrunde abgeschlossen, sollte man üben und die ersten Dinge herstelle. Schon bald hat man seine Routine gefunden und kann neue Rezepte beim Lehrer erlernen.\r\n==Spezialisierungen==\r\nIngenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: [[Gnom]] und [[Goblin]]. \r\n===[[Gnome]]n-Ingenieur===\r\nDie [[Gnome]]n-Ingenieurskunst beruht auf der Ingenieurskunst-Theorie, die besagt, dass sie den Bedürfnissen zu dienen hat. Die Baupläne ermöglichen ihnen, Geräte hervorzubringen, die die Welt um sie kontrollieren. Es geht um die Konstruktion von wunderbaren Apparaten und Geräten, die das Leben schöner machen. Wenn man mehr über die Gnomeningenieurskunst erlernen will, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu [[Glotz Widrikus]] nach [[Beutebucht]]. Wenn man ein Gnomeningenieur werden will, dann muss man den Schwur der lebenslangen Geheimhaltung unterschreiben. Sobald man ein Gnomeningenieur geworden ist, war's das. Es gibt keinerlei Zugang zur Gobliningenieurskunst. \r\n===[[Goblin]]-Ingenieur===\r\nWenn man etwas über die Gobliningenieurskunst erlernen will, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu [[Nixx Sprossfeder]] nach [[Tanaris|Gadgetzan]]. Durch den klugen Einsatz von hochempfindlichen Sprengstoffen und phantastischen Ausrüstungsgegenständen lernt man, die Welt zu meistern. Es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern. Bei der Goblin-Ingenieurskunst geht es um praktische Anwendungen mit hohem Profit und noch höherer Explosionskraft. Die Baupläne ermöglichen ihnen, mächtige Bomben und gewaltige Waffen hervorzubringen. Es gibt auch ein uraltes Gelöbnis der Geheimhaltung der Baupläne. Man wird Zugang zu den mächtigsten Ingenieurskunst-Schemata in ganz [[Azeroth]] haben. Die Mitgliedskarte der Gobliningenieure ist notwendig, um Zugang zu allen Gobliningenieurskunstlehrern zu erhalten. Diese Karte wurde für vierzehn Tage im Voraus bezahlt; alle Karten laufen nach zwei Wochen Aktivität ab. Ist das geschehen, zahlt man den nächsten Beitrag bei einem beliebigen Gobliningenieurskunstlehrer ein, um eine weitere Karte zu erhalten. Ohne die Karte wird die Mitgliedschaft zeitweilig unterbrochen und man hat keinen Zugriff auf neue Baupläne. Das hat natürlich keinen Einfluss auf das, was man bereits weiß.\r\n==Herausragende Leistungen der Ingenieurskunst:==\r\n* [[A-Me 01]]\r\n* [[Dröhnkiste]]\r\n* [[Dämonischer Seher]]\r\n* [[Draco-Incarcinatrix 900]]\r\n* [[Ektoplasmadestillierer]] \r\n* [[Extradimensionaler Geisterdetektor]]\r\n* [[Kraftquelle Modell 4711-FTZ]]\r\n* [[Leitroboter]] \r\n* [[Magitastischer Gizmonitor]]\r\n* [[Raketenschiff X-52]]\r\n* [[Samophlang]]\r\n* [[Superschnapper FX]]\r\n* [[Turbogreif 8000]]\r\n* [[Ultraschrumpfer]]\r\n* [[Zephyrium]]\r\n* [[Zephyriumkapazitorium]]\r\n* [[Zephyriumsprengnethermodulator PU-36]]",},
			["Ingenieur: Rezepte"] = { content = "Hier können Charaktere eintragen werden und welche besonderen Rezepte sie in diesem Beruf beherrschen.\r\n==Beine==\r\n* ''' \r\n* Allianz: [[Hildegard]] \r\n* Horde: (-) \r\n* ''' \r\n* Allianz: [[Hildegard]] \r\n* Horde: (-) \r\n==Kopf==\r\n* ''' \r\n* Allianz: [[Hildegard]] \r\n* Horde: (-) \r\n* ''' \r\n* Allianz: [[Grokhnaar Grimmklinge]] \r\n* Horde: (-) \r\n==Gegenstandsverbesserungen==\r\n* ''' \r\n* Allianz: [[Grokhnaar Grimmklinge]], [[Gozer]]\r\n* Horde: (-) \r\n* ''' \r\n* Allianz: [[Grokhnaar Grimmklinge]], [[Hildegard]], [[Gozer]] \r\n* Horde: (-)\r\n==Schusswaffe==\r\n* ''' \r\n* Allianz: [[Hildegard]], [[Grokhnaar Grimmklinge]] \r\n* Horde: (-) \r\n* ''' \r\n* Allianz: [[Grokhnaar Grimmklinge]], [[Hildegard]] \r\n* Horde: (-) \r\n* ''' \r\n* Allianz: [[Hildegard]], [[Grokhnaar Grimmklinge]] \r\n* Horde: (-) \r\n----\r\n'''Siehe auch:''' \r\n* [[Ingenieur]]\r\n* [[Handwerksverzeichnis der Allianz]] \r\n* [[Handwerksverzeichnis der Horde]]",},
			["Ingvar der Brandschatzer"] = { content = "'''Ingvar der Brandschatzer''' ist der Kommandant von [[Burg Utgarde]] im [[Heulender Fjord|heulenden Fjord]]. Von seinem Balkon aus, hoch über der [[Dolchbucht]], gibt dieser Vrykul seinen Truppen aus Zeichen, die Ziele in den Regionen unterhalb der Burg anzugreifen. er wird von drachenreitenden [[Vrykul]] umringt, doch sobald er besiegt wurde, erfährt man mehr über das Geheimnis der Vrykul, und was getan werden muss, um [[Nordend]] von der Dunkelheit zu befreien, welche die gefrorene Ödnis umhüllt.",},
			["Inneres Elfentor"] = { content = "Das Herz der Waldländer von [[Quel'Thalas]] und die Stadt [[Silbermond]] wurden durch das [[Innere Elfentor]] geschützt. Das mächtige Portal konnte nur mit dem „[[Schlüssel der drei Monde]]“ geöffnet werden - einem speziellen Artefakt, das sich aus mehreren [[Mondkristalle]]n zusammensetzte. Jeder dieser Kristalle befand sich in einem Altar der [[Hochelfen]], die an den Waldgrenzen zum inneren Reich lagen. Der Smaragd „[[Auge von Jennala]]“ öffnete den Geist, der Amethyst „[[Stein von Hannalee]]“ das Herz und der Saphir „[[Körper von Enulaia]]“ die Seele des Torhüters. Der gefallene Prinz [[Arthas]] und seine Untotenarmee griffen das Elfenreich [[Quel'Thalas]] an und zerstörten das [[Äußeres Elfentor|Äußere Elfentor]]. Auch die [[Waldläufer]] unter General [[Sylvanas Windläufer]] konnten die untote Streitmacht nicht aufhalten. Der [[Todesritter]] brachte den „[[Schlüssel der drei Monde]]“ in seinen Besitz, setzte dessen Macht frei und öffnete das Innere Elfentor nach [[Silbermond]].",},
			["Inschriftenkunde"] = { content = "'''Inschriftenkunde''' ist ein Beruf, der mit dem Brückenpatch 3.02 bzw. mit der Erweiterung \"[[Wrath of the Lich King]]\" erlernbar sein wird und mit dessen Hilfe man lernt, wie man Zauber verstärken kann. Hauptprodukt des Schriftgelehrten sind so genannte Glyphen, eine Art Veredelung und Verstärkung bestimmter Fähigkeiten der jeweiligen Klasse -- ein wenig vergleichbar mit der Verbesserung von Gegenständen durch gesockelte Edelsteine. Dazu braucht er neben Papier und Tinte aus eigener Produktion auch eine ganze Menge Fleiß bis zur Pefektionierung seiner Kunst. (Quelle: www.buffed.de)\r\n==Tinten==\r\nMit verschiedenen Tinten aus Eigenherstellung und unterschiedlichsten Sorten Pergament erschafft der Schriftgelehrte Schriftrollen, die temporär Boni auf Werte geben wie z.B. „Rolle der Ausdauer. Außerdem können auch Medien erschaffen werden, welche Verzauberungen aufnehmen, so dass man diese im [[Auktionshaus]] verkaufen oder dem eigenen Twink zuschicken kann. Der Inschriftenkundige kann auch Runenwörter herstellen, um Rüstungen zu besprechen und ihnen so einen temporären Buff ähnlich Waffenölen zu gewähren, wie etwa das „Runenwort der geringen Macht . Vor allem anderen kann der Schriftgelehrte aber Glyphen herstellen, um direkt Fähigkeiten und Sprüche zu verstärken. \r\n==Glyphen und Glyphensockel==\r\nMit dem neuen Patch erhält jeder Spieler ein Glypheninterface. Hier haben ab Level 60 drei erhebliche und drei geringe Glyphen in den sogenannten Glyphensockeln Platz. Vorher könnt Ihr nur auf jeweils zwei zugreifen. Freigeschaltet wird das Glypheninterface vermutlich auf Stufe 10 zusammen mit den Talentpunkten. Schriftgelehrte erhalten als Berufsbonus einen weiteren erheblichen Glyphensockel und besondere Glyphen. Jede Glyphe ist einzigartig, kann also nur einmal gesockelt werden. Erhebliche Glyphen verändern die Mechanik von Sprüchen und Fähigkeiten, wie den Schaden, die Dauer, die Manakosten oder benötigte Reagenzien z.B. bei „Glyphe Schattenblitz . Geringe Glyphen nehmen meist optischen Einfluss. So verwandelt der Magier mit Hilfe einer geringen Glyphe etwa sein Ziel in einen Pinguin statt in ein Schaf. Rezepte für geringe Glyphen und weitere große Glyphen erhält man durch Forschung. Alle 20 Stunden setzt Ihr „Minor Inscription Research und „Northrend Inscription Research ein und hofft, dass Ihr dabei Neues entdeckt. \r\n==Highlights der Inschriftenkunde==\r\nGlyphen sind zwar das Hauptprodukt des Schriftgelehrten. Aber er hat noch noch ein paar andere Schmankerl in seinem Repertoire, so etwa:\r\n* „Behandeltes Velinpapier und „Gebleichtes Velinpapier, um Waffenverzauberungen bzw. Rüstungsverzauberungen aufzunehmen und ohne direkten Kontakt handelbar zu machen (Auktionshaus, Post). Weitere Velinpapiere sind auch für höherstufige Verzauberungen verfügbar.\r\n* „Rolle des Rückrufs, euer zweiter Ruhestein. Nur für Schriftgelehrte. Es gibt auch weitere Ausbaustufen für höhere Level. \r\n* Tarot – Kartensets. Man erhält eine zufällige Karte aus dem Set. Ein vollständiges Tarotset könnt Ihr beim Dunkelmond-Jahrmarkt gegen einen grünwertigen Gegenstand eintauschen. Beispiel: „Geheimnisvolles Tarotspiel. Ihr müsst den Weg aber gar nicht auf Euch nehmen, denn es erscheint sogar Euer persönlicher Wahrsager.\r\n* Ein „Besitzzertifikat ermöglicht es Euch endlich, als Jäger Euren tierischen Begleiter umzubenennen. \r\n* Schulterverzauberungen wie „Master’s Inscription of the Axe kann sich der Schriftgelehrte nur selbst gönnen. \r\n* Auch über Gegenstände für die Nebenhand, wie die „Gesichter der Verdammnis, können sich nur Spieler mit Inschriftenkunde freuen. \r\n==Mahlen==\r\nDer örtliche Schriftkundebedarf verkauft die Grundlage für die diversen Erzeugnisse. In seinem Sortiment hat er Schreibzeug und mehrere Arten Pergament. Damit man jedoch nicht lange vor einem leeren Blatt sitzt, muss man verschiedenste Tinten herstellen. Diese bestehen aus Pigmenten, welche man aus der Inschriftenkunde-Fähigkeit Mahlen gewinnt. Sie funktioniert genau wie das Sondieren des Juweliers. Man benötigt fünf Kräuter einer Sorte und erhält durch das Mahlen 1-3 Pigmente. Die Kräuter werden dabei zerstört. Dem Zufall überlassen bleibt dabei, ob man gewöhnliche oder seltene Pigmente erhaltet. \r\n==Zweitberuf: Kräuterkunde==\r\nFür die Inschriftenkunde benötigt man neben zahlreichen Pergamenten auch noch unterschiedliche Sorten Tinte. Deren Grundstoff sind Pigmente, die aus verschiedenen Pflanzen gewonnen werden. Wenn man die Masse an Kräutern im Auktionshaus erstehen muss, ist man schnell ein Vermögen los. Daher empfiehlt es sich, Kräuterkunde als Zweitberuf zu erlernen. Das bringt noch einen kleinen Bonus, nämlich den Zauber „Wildwuchs. Auch schon voll ausgebildeten Blumenpflückern bleibt natürlich der Weg in die Startgebiete nicht erspart. Niedrigstufige Pflanzen wie Friedensblume oder Silberblatt stehen am Anfang der Ausbildung zum Großmeister der Inschriftenkunde.",},
			["Inschriftenkunde: Rezepte"] = { content = "Hier können Charaktere eintragen werden und welche besonderen Rezepte sie in diesem Beruf beherrschen.\r\n==Foliant==\r\nFolianten werden in der Schildhand geführt.\r\n* '''Buch der cleveren Tricks ''' (Benötigt Inschriftenkunde 325)\r\n Allianz: \r\n Horde: \r\n----\r\n'''Siehe auch:''' \r\n* [[Inschriftenkunde]]\r\n* [[Handwerksverzeichnis der Allianz]] \r\n* [[Handwerksverzeichnis der Horde]]",},
			["Insel Alcaz"] = { content = "===Insel Alcaz===\r\nDie Insel Alcaz liegt vor der Küste der Düstermarschen und wird von den [[Naga der Strashaz]] bewohnt. Dort befindet sich auch [[Doktor Weavil]], der Erzfeind von [[Narain Pfauentraum]], der das Original von [[Drachisch für Dummies]]: Band 2 zerstörte.",},
			["Insel der Sonnenwanderer"] = { content = "Die '''Insel der Sonnenwanderer''' ist das Startgebiet der [[Blutelfen]]. Genau wie der [[Immersangwald]] und die [[Geisterlande]] steckt sie voller Möglichkeiten, die Geschichte dieses alten Volkes kennenzulernen. Als junger Blutelf beginnt man seine Reise in der Zuflucht der Insel der Sonnenwanderer. Vor der Zerstörung des [[Sonnenbrunnen]]s waren die [[Blutelfen]] so töricht zu denken, sie hätten den Gipfel ihrer Zivilisation errecht. Die [[Geißel]] brachte sie zu Fall ... und in gewisser Weise brachte sie sie zurück in die Realität. \r\nDie brennenden Kristalle - die grünen, schwebenden Objekte westlich des [[Sonnenturm]]s - wurden lange Zeit als Energiequelle für die Experimente der Insel verwendet. Die [[Manawyrm]]s waren ihre Wächter, aber der Einmarsch der [[Geißel]] in [[Quel'Thalas]] hat sie auf Grund der mangelnden magischen Kontrolle über sie fehlgeleitet. Die unkontrollierte Macht der brennenden Kristalle hat einen viel größeren Teil des natürlichen Gleichgewichts der Insel durcheinander gebracht, als man vermutet hat. Für viele ist es eine Schande, dass sie die Kontrolle über so viele Kreaturen hier auf der Insel verloren haben. Es war einst ein ruhiger Ort der Studien und Forschungsarbeiten. Jetzt können die [[Blutelfen]] sich nur noch hüten, damit sie von ihren eigenen Kreationen nicht angegriffen zu werden!",},
			["Insel des Schreckens"] = { content = "Die Insel des Schreckens liegt südlich der [[Insel Sardor]] und der [[Mondfederfeste]] in [[Feralas]].\r\nDer Legende nach haben die [[Chimaerok]] von dieser Insel das saftigste und zarteste Fleisch weit und breit und die [[Chimaerok]] haben ein Familienoberhaupt, [[Lord Lakmaeran]], das nach entsprechender Zubereitung wie ein aussehen könnte.\r\n[[Lord Shalzaru]], einer der Adligen der [[Naga der Hasskämme]], hat bei einer kürzlich durchgeführten [[Naga]]-Ausgrabung in einer Höhle südlich der eigentlichen [[Ruinen von Solarsal]], jenseits des Wassers, auf der Insel des Schreckens, ein seltsames Relikt gefunden.",},
			["Insel des Sonnenbrunnens"] = { content = "#REDIRECT [[Insel von Quel'Danas]]", redirect = "Insel von Quel'Danas",},
			["Insel Drachenfels"] = { content = "Die Bewohner der Insel Drachenfels mögen keine Besucher, denn die [[Drachen]]welpen, die man auf dieser Insel sieht, sind die ruhelosen Geister des [[Grüner Drachenschwarm|Grünen Drachenschwarms]]. Sie sind an das Land gebunden, außerstande ihre letzte Ruhestätte im Traum zu erreichen. Während der Angriffe wurden aber auch viele des [[Schwarzer Drachenschwarm|Schwarzen Drachenschwarms]] getötet. Einer von ihnen ist ein Offizier von [[Todesschwinge]] selbst und sucht noch immer diesen Ort heim. Blickt man in den Himmel, so kann man das spektrale Antlitz des [[Schwarzer Drachenschwarm|Schwarzen Drachen]] [[Messerrachen]] durch die Lüfte kreisen sehen. Sein Hass ist so groß, dass er sogar den Tod übersteht. Auf der Dracheninsel kreist auch der Geist von [[Prinz Toreth]] um den Berg.",},
			["Insel Fenris"] = { content = "Die '''Insel Fenris''' liegt vor der Küste des [[Silberwald]]es. Die Insel und die daraufstehende Burg wird von den [[Gnolle der Moderfelle|Gnollen der Moderfelle]] beherrscht und war einst der Sitz von [[Thule Rabenklaue]]. Bevor die [[Verlassene]]n einen Angriff auf die Insel starten kann, müssen sie erst herausfinden, wer hinter den [[Gnolle der Moderfelle|Gnollen der Moderfelle]] steht. Die [[Apotheker]] glauben, der Ursprung der Moderfelle liege in der seltsamen Flüssigkeit, die durch ihre Körper fließt.\r\n==Personen==\r\n* [[Thule Rabenklaue]]\r\n* '''Alaric''' - Alaric war einst der oberste Diener von [[Thule Rabenklaue]] und sein Leibwächter. Thule nutzte seine Magie, um ihn vor der Pest des Untodes zu \"schützen\", aber dieser Zauber bürdete Alaric ein Unleben auf, dem er nicht entrinnen kann und nachdem er die [[Gnolle der Moderfelle]] erschaffen hatte, hat Thule ihn geköpft und seinen Kopf den [[Gnolle]]n zum Spielen gegeben. Die Gnolle haben ihn in der Burg Fenris, nahe den Stallungen, in einem namenlosen Grab verscharrt. Doch Alaric kennt eine versteckte Nische in der Burg, die einen Gegenstand enthält, der für Thule und seine alten Kollegen sehr wichtig ist: einen gewebten Zauberstab. Die Nische ist im Südwestturm der Burg, hinter einem staubigen Regal.",},
			["Insel Jaguero"] = { content = "Die '''Insel Jaguero''' liegt vor der Westküste in den südlichen Meeren im [[Schlingendorntal]] und wird von Blaumähnengorillas bewohnt. Der große Blaumähnen[[könig Mukla]] hat die Tauren [[Prinzessin Poobah]] hier gefangen genommen und hält sie mit Hilfe einer Kette gegen ihren Willen hier fest. Sie hat ihn oft auf der südöstlichen Seite der Insel gehört. Die Sternbilder am Nachthimmel sind ihr nicht vertraut und von Dschungelbäumen verdeckt, aber an klaren Tagen kann sie die wilden Ufer im Nordwesten erkennen und im Südwesten etwas, das große Segelschiffe sein könnten.",},
			["Insel Ranazjar"] = { content = "Ranazjar ist der Name einer Insel im Verhüllten Meer von [[Desolace]]. Sie ist vor der Küste nordwestlich von [[Ethel Rethor]] gelagert und in der Gegend wimmelt es von weichschaligen Muscheln. Dort finden sich elfische Ruinen in einem Korallenriff auf dem Grund des Meeres, die die räuberischen [[Naga der Zackenkämme]] als ihre Heimat nutzen, da es so nahe am Ufer liegt. Diese [[Naga]] sind tödlich und reagieren ungnädig auf Eindringen. Durch die Schlangenstatue auf der Insel wird jener gerufen, der das \"[[Buch der Uralten]]\" beschützt. \r\nOben im Norden findet man ein Schiffswrack der GALLANT vor der Küste. Käpt'n [[Ulysses Rackmore]] segelte mit diesem Schiff zur [[Mondfederfeste]], als es von seefahrenden Kreaturen angegriffen wurde. Er versteckte seine Truhe auf der Insel Ranazjar, damit sein Schatz dem Feind nicht in die Hände fallen sollte. Zwei Schlüssel, ein silberner und ein goldener, sind erforderlich, um die Truhe zu öffnen. Diese Schlüssel gingen verloren, doch wenn Schlüssel und Truhe gefunden werden, winkt ein Schatz.\r\n==Personen == \r\n* [[Ulysses Rackmore]]\r\n==Schätze == \r\n* [[Buch der Uralten]]\r\n* '''Karnitols Truhe''' - Karnitols Truhe liegt aufgebrochen in einem Schiffwrack. Man überlegt eine Weile, was die Kiste aufgebrochen haben könnte, und bemerkt an den Seiten und am Deckel lange, tiefe Kratzer, die belegen, dass sich etwas anderes als ein Mensch oder Riese dafür interessierte. Solche Spuren scheinen nicht von einem Dolch oder Schwert verursacht worden zu sein. Man wirft einen Blick in die Truhe und stellt fest, dass sie leer ist.",},
			["Insel Sardor"] = { content = "Die '''Insel Sardor''' liegt vor der westlichen Küste in [[Feralas]]. Hier befinden sich die [[Ruinen von Solarsal]], sowie nördlich davon die [[Mondfederfeste]]. Es ist eine Gegend aus längst vergangener Zeit, doch vor kurzem haben die [[Naga der Hasskämme]] die [[Ruinen von Solarsal]] in alarmierender Anzahl besetzt. Im Herzen dieser steht nun ein seltsamer Pavillion, der sich deutlich von der Bauweise der anderen Gebäude dort abhebt und die [[Naga]] werden langfristig versuchen, die gesamte Insel für sich zu beanspruchen. In ihren Truppen gibt es viele Adlige und die sind es, die den Ton angeben. Eine Untersuchung des Pavillons in den Ruinen zeigt einige interessante und ungewöhnliche Dinge im Vergleich zu den umstehenden Ruinen auf. Esten ist der Pavillon eindeutig ein wesentlich jungeres Bauwerk als die anderen Ruinen. Zweitens dind eine Reihe von Glyphen in eine Seite eingraviert. Das Muster der Glyphen wiederholt sich, aber sein Ursprung oder seine Bedeutung sind ansonsten unklar. Drittens fühlt sich der Stein, aus dem der Pavillon besteht, warm an.",},
			["Insel von Quel'Danas"] = { content = "Die '''Insel des Sonnenbrunnens''' wird mit Patch 2.4. geöffnet. Die Insel von Quel'Danas, wie sie auch genannt wird, befindet sich nördlich von [[Quel'Thalas]]. Hier kann man sich auch der [[Offensive der Zerschmetterten Sonne]] anschließen, um [[Kael'thas]] ruchlose Pläne zu vereiteln, denn Kael'thas' finstere Pläne konnten den größten Anstrengungen zum Trotz ausgeführt werden. Der Sonnenbrunnen wurde wieder entfacht, um die Ankunft des Betrügers vorzubereiten. Die vereinten Streitkräfte von [[Shattrath]] haben nun einen Angriff auf die Insel von Quel'Danas gestartet, um sich Kael'thas und der Legion beim [[Sonnenbrunnen]] und im umliegenden Gebiet zu stellen. Es wurden riesige Barrieren errichtet, um die Angriffe auf die inneren Hallen zu behindern. Wenn Azeroth jemals Hilfe benötigen sollte, dann wäre es jetzt. Sprecht mit Flugmeistern in [[Eisenschmiede]] und [[Silbermond]], sie werden Euch dorthin bringen. \r\n===Hafen der Sonnenweiten===\r\nDer Hafen der Sonnenweiten ist von höchster strategischer Bedeutung für die Pläne der Offensive der Zerschmetterten Sonne. Doch hier wurde die Armee der [[Blutelfen der Dämmerklingen]] von [[Kael'thas Sonnenwanderer]] stationiert. Magister Ilastar kümmert sich um die Einnahme des Hafen der Sonnenweiten und je mehr Dämmerklingen also beseitigt werden, umso mehr hilf man damit der Zerschmetterten Sonne. Kael'thas wird den Tag bereuen, als er sich von seinem Volk abwandte und sich mit der Brennenden Legion einließ. Nachdem die Zerschmetterte Sonne die Armee der Dämmerklingen aus dem Hafen der Sonnenweiten vertrieben hat, gehören die Sonnenweiten nun ihnen; und ein elfischer Zerstörer der Flotte von [[Quel'Thalas]], die '[[Silbermonds Stolz]]' unter dem Kommando von Kapitän Valindria, hat dort nun angelegt, um die Offensive der Zerschmetterten Sonne in der Schlacht zu unterstützen.\r\n* '''Ayren Wolkenbrecher''' - Ayren Wolkenbrecher ist der Drachenfalkenmeister im westlichen Teil des Hafens. Er stellt die [[Drachenfalken]] für die Luftangriffe auf die [[Todesschneise]] und die Schiffe der Dämmerklingen bereit.\r\n* '''Kapitän Valindria''' - Kapitän Valindria kümmert sich um die Belästigung an der [[Küste der Grünkiemen]] und sorgt dafür, dass die [[Grünkiemen]]sklaven befreit werden. \r\n* [[Mar'nah]] - Mar'nah hat hier ihr Alchimie-Geschäft geöffnet und will den Kämpfern der Zerschmetterten Sonne behilflich sein. Leider kann sie nichts anbieten, solange sie keine Reagenzien auf Lager hat. Eines der benötigten Reagenzien ist [[Messerdornwurzel]] - eine Besonderheit und besonders schwierig zu sammeln. Sie hat vor kurzem auch das Rezept für [[Blutbeerenelixier]] entdeckt und wenn man für sie die [[Blutbeeren]] von den Büschen auf Quel'Danas sammelt, stellt sie ihr Elixier zur Verfügung. \r\n===Küste der Grünkiemen===\r\nDie [[Naga der Dunkelflossen]] haben die Küste der Grünkiemen im Südosten der Insel von Quel'Danas erobert. Ihre Frauen, die Sirenen, haben die [[Murlocs der Grünkiemen]] bezaubert und zu ihren Sklaven gemacht. Es ist die Pflicht von [[Kapitän Valindria]] auf der '[[Silbermonds Stolz]]', dafür zu sorgen, dass das, was auch immer die Naga dort treiben, gestört wird. Dazu müssen den weiblichen Naga die Kontrollkugeln abgenommen und in der Nähe der Grünkiemensklaven auf den Boden geworfen werden, damit die Kugel zerspringt und die Murlocs befreit werden. Allerdings werden die Murlocs danach erbost sein und sich gegen ihre Meister wenden werden. Die Naga bauen auch Erz ab und schicken es dann in Truhen an die Legion. \r\n===Morgenstern===\r\nDas Dörfchen Morgenstern liegt im westlichen Teil der Insel von Quel'Danas. Auch hier wurde die Armee der [[Blutelfen der Dämmerklingen]] von [[Kael'thas Sonnenwanderer]] stationiert. [[Magister Ilastar]] in der [[Waffenkammer der Sonnenweiten]] ist sehr unzufrieden darüber. Er sucht Freiwillige, die sich nach Morgenstern begeben und jeden überlebenden Anhänger der Dämmerklingen erschlagen, der ihnen über den Weg läuft. Die Blutelfen der Dämmerklingen besiegelten ihr Schicksal, als sie Kael an diesen Ort folgten.\r\n===Platz der Morgenröte===\r\n[[Herold Inuuro]] leitete die Schlacht um den Platz der Morgenröte. Und auch nachdem die [[Waffenkammer der Sonnenweiten]] eingenommen wurde, muss die Schlacht auf dem Platz der Morgenröte weitergehen. Die Krieger der Zerschmetterten Sonne müssen zusehen, dass sie die Armeen der Brennenden Legion hier besiegen und entmutigen. \r\n===Sammelpunkt der Zerschmetterten Sonne===\r\n* '''Hauptmann Theris Morgenheim''' - Hauptmann Theris Morgenheim kümmert sich um die Barrieren vom [[Sanktum der Sonnenweiten]]. Er will, dass man Manaüberreste von den getriebenen Unholden und getriebenen Verschlingern verschafft und sie benutzt, um eine der Kristallbarrieren aufzuladen. Die Sicherheit des Vorhabens hängt davon ab.\r\n===Sanktum der Sonnenweiten===\r\nDas Sanktum der Sonnenweiten wurde zuerst für die Offensive der Zerschmetterten Sonne eingenommen. Sobald es gesichert war, war die Offensive in der Lage, seine Energien für die Öffnung eines Portals nach [[Shattrath]] zu nutzen. Das Sanktum quoll über von [[Getriebene]]n. Die Verteidigungsanlangen hätten dieses Eindringen normalerweise verhindert, aber die Getriebenen haben die Energiequellen der Schutzbarrieren gestohlen. Das Sanktum wird im Osten von Kristallbarrieren umgeben, die es aufzuladen gilt, denn die Getriebenen sind dickköpfig und stehlen noch immer Energie von den Kristallbarrieren. Die Offensive hatte die Kristallbarrieren um das Sanktum erfolgreich reaktiviert, aber warum hier aufhören? Sie werden auch Verteidigungen um die anderen Gebäude herum aufbauen. \r\n* '''Astromant Darnarian''' - Astromant Darnarian möchte, dass man den Kristall des Astromanten am [[Blutkristall]], am Portal auf dem Platz der Morgenröte und in der Nähe des Nagaschreins an der Küste der Grünkiemen benutzt. Sein Ziel ist es, dass man die heiß geliebten Translokationen mehr schätzen weiß und sieht, wie viel Anstrengung selbst im einfachsten Portal steckt. Vielleicht wird etwas Aufklärung ein wenig mehr Dankbarkeit für seine unermüdlichen Anstrengungen beibringen.\r\n* '''Herold Inuuro''' - Herold Inuuro leitete die Schlacht um die [[Waffenkammer der Sonnenweiten]] und sorgte dafür, dass die Dämonen der Brennenden Legion und der [[Abgesandter des Hasses|Abgesandte des Hasses]] auf dem [[Platz der Morgenröte]] oder der Waffenkammer der Sonnenweiten niederstreckt wurden. \r\n* '''Kampfmagierin Arynna''' - Kampfmagierin Arynna kümmert sich um das Ablenkungsmanöver an der [[Todesschneise]] und sorgt dafür, dass frisch rekrutierte [[Drachenfalkenreiter]] dort mit Hilfe von arkanen Ladungen die [[Oberanführer der Grube]], die [[Zauberer der Eredar]] und die [[Rachevollstrecker]] dezimieren. \r\n===Sonnenweiten===\r\nDie Sonnenweiten befinden sich auf der Insel des Sonnenbrunnens. Die Offensive der Zerschmetterten Sonne hat die Sonnenweiten dem Feind entrissen und der endgültige Sieg steht kurz bevor. Doch der Preis war hoch und viele tapfere Kämpfer gaben dafür ihr Leben. Sie haben den Gefallenen zu Ehren ein Denkmal errichtet - ein kleiner Trost für die Familien, die ihre Angehörigen verloren haben. Anachoretin Ayuri wird damit beginnen, Spenden zu sammeln, um die Waisen und Ehepartner der Kriegshelden zu unterstützen. Falls man eine kleine Spende machen könnte, würde man viel dazu beitragen.\r\n* '''Anachoretin Ayuri''' - Anachoretin Ayuri hat ein großes Herz und ist sehr überzeugend, wenn es darum geht, eine milde Gabe von 10 Gold zu erlangen. Aber die Spenden kommen nicht gerade an das heran, was sie sich erhofft hatte. Ihr Ziel ist es, sicherzustellen, dass die Gefallenen nicht vergessen werden. Also bitte sie alle Vorbeikommenden, dass sie einen Moment innehalten, um über eine Spende für eine Gedenkstätte nachzudenken. Alles übrig gebliebene Gold wird an die Witwen und Waisen der Gefallenen gehen. \r\n===Teufelsportal===\r\nDas Teufelsportal befindet sich in der Mitte des im Süden gelegenen Platzes der Morgenröte. Die Offensive der Zerschmetterten Sonne hat eine der Agentinnen, Magistrix Seyla, ausgesandt, um das Portal zu untersuchen. Sie ist noch nicht zurückgekehrt. \r\n===Todesschneise===\r\nDie [[Brennende Legion]] wird die Offensive der Zerschmetterten Sonne angreifen, sobald ihre Truppen im Süden der Insel nicht mehr gebunden sind. Im Moment hält die [[Geißel]] in der Todesschneise ihre Streitkräfte beschäftigt. Jedoch nicht mehr lange. Kael'thas Lakaien bemerkten es dank der Luftangriffe der [[Drachenfalkenreiter]] unter dem Kommando von [[Kampfmagierin Arynna]] nicht einmal, dass die Zerschmetterte Sonne die Waffenkammer einnahm. Tatsächlich lief die Sache so gut, dass sie die Luftangriffe gegen sie weiterführen werden. \r\n===Waffenkammer der Sonnenweiten===\r\nDie Brennende Legion hielt die Waffenkammer der Sonnenweiten - doch sie ist von taktischer Wichtigkeit für den Einsatz der Offensive der Zerschmetterten Sonne. Solange die Moral der Dämonen dort hoch blieb, konnten sie das Gebäude ihrem dämonischen Griff nicht entziehen. Doch das wurde geändert. Auch dank der Luftangriffe gegen die Truppen der Legion in der [[Todesschneise]] konnten die Krieger der Zerschmetterten Sonne dem Feind die Waffenkammer abjagen. Versorgungsgüter wurden nach und nach angeliefert, aber trotzdem konnte es sich Schmiedin Hauthaa nicht leisten, hier zu warten und zu hoffen, dass Hilfe kommen wird, bevor die Offensive zum Stillstand kommt. \r\n* '''Magister Ilastar''' - Magister Ilastar kümmert sich um die Einnahme des Hafen der Sonnenweiten und möchte, dass man die [[Beschwörer]], [[Blutritter]] und Schützen der [[Dämmerklingen]] niederstreckt. Doch auch nachdem der Hafen erobert wurde, ist Ilastar nicht vollends zufrieden und möchte auch noch die überlebenden Anhänger der Dämmerklingen in [[Morgenstern]] vernichten.\r\n* '''Schmiedin Hauthaa''' - Schmiedin Hauthaa musste sich nach der Einnahme der Waffenkammer um die Vorbereitungen für ihre Schmiede kümmern und benötigte Erz, um daraus einen Amboss zu fertigen und anzufangen, die Rüstungen und Waffen aufzubessern. Sie wollte, dass man Myrmidonen der Dunkelflossen, die sich im Osten befinden, tötet und ihre Schlüssel dazu verwendet, das Erz aus ihren Truhen zu stehlen. Dass sie ihnen ihr Erz abnahm, kam ihrem Vorhaben in vielerlei Hinsicht zugute, denn als sie einen Amboss hatte, konnte sie so richtig anfangen zu arbeiten. Doch auch nachdem ihre Schmiede fertig gestellt ist, wird sie das Eisenerz der Dunkelflossen immer gut gebrauchen können, egal wie viele Versorgungsgüter sie bekommt, denn wenn die Zerschmetterte Sonne hier gewinnen will, dann benötigen die Kämpfer regelmäßige Waffen- und Rüstungslieferungen. Schmiedin Hauthaa braucht auch die Waffen von Ata'mal von der [[Terrasse von Ata'mal]], um eine Legierung mit Nagaerz herzustellen. Die [[Anachoret]]en haben ihren Amboss mit der Fähigkeit gesegnet, diese Waffen zu reinigen. \r\n==Personen==\r\n* '''Anachoret Kairthos''' - Anachoret Kairthos möchte, dass man 1.000 Gold spendet, um [[Anachoretin Ayuri]] in ihrem Vorhaben zu unterstützen. Wenn man die Aufgabe abschließen sollte, wird man den Namen \"[[Held der zerschmetterten Sonne]]\" tragen.\r\n* '''Erzmagier Ne'thul''' - Der Gegenstand, der vor Erzmagier Ne'thul steht und über dem [[A'dal]] schwebt, repräsentiert den derzeitigen Status der Verteidigungsanlagen des Sonnenbrunnens.",},
			["Insel Yojamba"] = { content = "Die Trolle vom [[Stamm der Zandalar]] kampieren auf der Insel Yojamba, fern der Küste des [[Schlingendorntal]]s, westlich der [[Ruinen von Zul'Kunda]]. Ihr Anführer dort ist Molthor und gemeinsam mit Freiwilligen von Horde und Allianz koordinieren sie hier den Kampf gegen den Blutgott Hakkar in Zul'Gurub.\r\n==Personen==\r\n* Al’tabim der Allsehende\r\n* Exzhal - Diener von Rastakhan\r\n* Jin'rokh der Zerstörer\r\n* Maywiki von Zuldazar\r\n* Molthor - Anführer. Hand von Rastakhan\r\n* Rin’wosho der Händler - Zandalar Waren & Reparaturen",},
			["Instanz"] = { content = "#redirect[[:Kategorie:Instanz]]", redirect = ":Kategorie:Instanz",},
			["Institut für Pfuschkunde"] = { content = "Das '''Institut für Pfuschkunde''' bekämpft [[Pfusch]] aller Art und forscht in allen Bereichen.\r\nDas Institut ist eine rein gnomische Einrichtung, in der auch nur [[Gnome]] arbeiten, studieren und forschen. Andere [[:Kategorie:Volk|Völker]] haben keine Chance, in das Institut aufgenommen zu werden… wie auch, die Stühle und Tische wären viel zu klein. Allerdings sind wir gern bereit, mit anderen Forschungsstätten zusammenzuarbeiten.\r\nWir setzen uns (zumindest einige von uns) sehr für die Gleichberechtigung der [[Gnome]] ein und dafür, dass diese ernst genommen werden. Wir veranstalten hin und wieder kleinere und auch mittelgroße „Events“, wie Vorträge über unsere Forschungen, Feiern, oder aktuell den [[Tag der offenen Tür am Institut für Pfuschkunde|Tag der offenen Tür]]. Klar mag das einigen nicht gefallen, aber es ist ja auch nicht Sinn und Zweck eines Instituts, von allen gemocht zu werden. Übrigens sind so gut wie alle \"Events\" für jeden Charakter auf [[Allianz]]seite zugänglich und auch ohne großes Hintergrundwissen offen.\r\nUnser eigentlicher Entstehungsgrund ist die Bekämpfung von [[Pfusch]] aller Art. Dazu ist natürlich eine Menge Forschung nötig, um andere Kulturen kennenzulernen oder andere Lebensweisen zu entdecken.\r\nDie Belegschaft (Studenten, Wissenschaftler, Praktikanten, Dozenten, Sicherheitsdienst, etc.) ist zwar relativ klein (unter 20), wächst aber ständig, wenn auch langsam.\r\nDas Institut ist in [[Gnomwind]]. Naja, die [[Menschen]]s nennen es [[Sturmwind]], aber wir stehen so ziemlich alle hinter der Gnomwind-Idee, da sie für die Gleichberechtigung der [[Gnome]] steht. Trotzdem werden auch Leute nicht schlechter behandelt, die nichts mit Gnomwind zu tun haben wollen. Wir haben keine wirklichen Feinde, auch wenn die [[Heilige Inquisition]] aufgrund unserer manchmal sehr radikalen Vorgehensweise (Stichwort Kathedralensprengung) nicht unbedingt grün mit uns ist.\r\nAls Einrichtung, die sich dem Gesamtwohl der Bevölkerung [[Azeroth]]s verschrieben hat, sind wir natürlich offen für jeden, der mit uns in Kontakt treten möchte. Außerdem sind wir eine neutrale Einrichtung und hegen daher auch keinen Hass auf irgendwelche anderen Völker dieser Welt (ausgenommen [[Troggs]]), auch nicht gegen [[Horde|Hordler]]. Diese Ansicht kann bei jedem Mitglied natürlich ein wenig abweichen.\r\n[[Die Regeln des Instituts für Pfuschkunde]]\r\n===Forschungarbeiten===\r\n* [[Leerenkörper]] - ein Studienvortrag von [[Smirke|Smirke Rasselspross Junior]].\r\n* [[Wissenschaftliche Gedanken über Schwefel und Wackelpudding]] - ein Studienvortrag von [[Hildegard|Hildegard Sprigglespruxx]]\r\n* [[Olog Oloran Chanski Seuche‎]] von [[Maigan]] Taliath\r\n* [[Forschungsbericht Dunkelküste]] von [[Kizzi]]\r\n* [[Archimonde - ein Rollenbild für Gnome ?]] - eine Forschungsarbeit von [[Smirke Rasselspross Junior]] und [[Hildegard Sprigglespruxx]]\r\n===Befreundete Gilden:===\r\n* [[Schraube und Hut]]",},
			["Internierungslager"] = { content = "==Geschichte==\r\nKaum waren die lodernden Feuer des Zweiten Krieges erloschen, wurden die verstreuten Klans der [[Orcs]] zusammengetrieben und in bewachte Lager im verwüsteten [[Azeroth]] gesperrt. Selbst der orkische Kriegsherr [[Orgrim Schicksalshammer]] wurde unter Arrest und als Ehrengefangener unter den persönlichen Schutz von König [[Terenas]] gestellt. Nur der [[Klan des Blutenden Auges]] befand sich noch immer auf der Flucht und war untergetaucht, während auch weiterhin große Teile des nördlichen [[Khaz Modan]] vom [[Drachenmal Klan]] besetzt waren. Um die Gefahr durch die [[Horde]] einzugrenzen, wurden im Süden [[Lordaeron]]s große Internierungslager gebaut, deren Basis sich in der alten Gefängnisfestung [[Burg Durnholde]] befand. Diese von den Paladinen und Soldatenveteranen der [[Allianz]] bewachten Lager erwiesen sich als großer Erfolg. Schon bald waren die Internierungslager bis zum Bersten überfüllt und wurden rund um die Uhr bewacht. Die gefangenen [[Orcs]] waren zwar nervös und brannten darauf, wieder zu kämpfen, doch den Lageraufsehern gelang es, Frieden und so etwas wie Ordnung zu erhalten.\r\n===Das Ende der Orkischen Horde===\r\nNach der Zerstörung des Zweiten [[Dunkles Portal|Dunklen Portals]] konnte die [[Allianz]] erfolgreich den größten Teil der in [[Azeroth]] verbliebenen Klans aus [[Draenor]] aufspüren. Zwar entzog sich der [[Kriegshymnenklan]] einer Gefangennahme, aber der [[Klan des Blutenden Auges]] wurden eingekesselt und in die Lager von [[Lordaeron]] gebracht. Die Niederlage des [[Drachenmal Klan]] in der Schlacht von [[Grim Batol]] bedeutete schließlich das Ende der [[Horde]] in [[Azeroth]], und die überlebenden Krieger wurden zusammengetrieben in die wartenden Internierungslager geworfen. Im Lauf der Monate wurden immer mehr [[Orcs]] gefangen genommen und in die bewachten Lager gesteckt. Die [[Allianz]] war gezwungen, neue Internierungslager auf den Ebenen südlich des [[Alterac]]gebirge zu erbauen. Zudem erhob König [[Terenas]] eine neue Steuer von den Nationen der [[Allianz]], um die ständig wachsende Anzahl der Lager ordentlich unterhalten und versorgen zu können.\r\n===Gebrochener Wille und Lethargie===\r\nZahlreiche Lagerwächter bemerkten eine beunruhigende Veränderung an den gefangenen [[Orcs]]. Im Laufe der Zeit hatten Fluchtversuche und selbst Kämpfe unter den Gefangenen deutlich nachgelassen. Nach dem Tode von [[Nekros Schädelberster]], dem letzten [[Hexenmeister]] ihres Volkes, verfielen die [[Orcs]] in den überfüllten Internierungslagern in eine lähmende Lethargie. Ihr Kampfgeist und ihre Bereitschaft zu sterben waren gebrochen, sie schienen ihren Kampfeswillen vollkommen eingebüßt zu haben. Diese seltsame Lethargie stellte die Führer der [[Allianz]] vor Rätsel und forderte zunehmend Tribut unter den immer schwächer werdenden Orcs. Der Erzmagier [[Antonidas]] von [[Dalaran]] erforschte das knappe Wissen über die Geschichte der [[Orcs]] und fand heraus, dass sie seit Generationen schon unter dem verderblichen Einfluss der [[Hexenmeister]]-Magie gestanden hatten. Die allgemeine Lethargie war eine Reaktion auf den Entzug jener vergänglichen Magie. Für den rätselhaften Zustand der [[Orcs]] kam nur eine spirituelle Heilung in Frage.\r\n===Der Weg in die Freiheit===\r\nViele Jahre später vereinte [[Orgrim Schicksalshammer]], der aus [[Lordaeron]] entkommen war, die wenigen verbliebenen freien Klans wieder unter seinem Kommando. Das erklärte Ziel des alten Kriegshäuptlings war es, die Internierungslager zu erstürmen und sein Volk aus der Gefangenschaft zu befreien. Mit der Unterstützung des [[Kriegshymnenklan|Kriegshymnen-]] und [[Frostwolfklan]]s gelang es [[Orgrim Schicksalshammer|Schicksalshammer]], die [[Horde]] neu zu beleben. Auch [[Thrall]], dessen Vater ein enger Freund Schicksalshammers gewesen war, schloss sich dem ehrgeizigen Kriegsherrn an und gab seinem Volk eine neue spirituelle Identität. Doch bei der Befreiung eines Lagers fiel [[Orgrim Schicksalshammer]] im Kampf. [[Thrall]] nahm Schicksalshammers legendären Kriegshammer an sich, legte seine schwarze Rüstung an und wurde der neue Kriegshäuptling der [[Horde]]. In den folgenden Monaten zerstörte [[Thrall]]s kleine, aber findige [[Horde]] die Internierungslager und vereitelte alle Anstrengungen der [[Allianz]], ihrer listenreichen Strategie etwas entgegenzusetzen. Sogar [[Burg Durnholde]] - die Festung, die für die Sicherheit der Internierungslager verantwortlich war - wurde von den [[Orcs]] vernichtet und [[Thrall]] tötete den leitenden Offizier [[Aedelas Schwarzmoor]]. König [[Terenas]] schickte [[Uther Lichtbringer]] und seine Paladine aus, um den Aufstand des Kriegshäuptlings niederzuschlagen, doch die listigen Orcs blieben unauffindbar.\r\n==Bekannte Internierungslager==\r\n* [[Lordamere-Internierungslager]]",},
			["Intrepid"] = { content = "Die '''Intrepid''' war ein Teil der [[Dritte Flotte von Kul Tiras|Dritten Flotte von Kul Tiras]] und ging gemeinsam mit den anderen Schiffen der Flotte unter. Sie liegt heute noch südlich vom [[Hafen von Menethil]] auf Grund. Obwohl der [[Erster Maat Fitzsimmons|Erste Maat Fitzsimmons]] im Hafen von Menethil das einzige Mitglied der Flotte ist, das noch atmet, ist er nicht der einzige, der noch herumläuft. Denn auf der Intrepid war ein großer und schrecklicher Schatz versteckt, das [[Auge von Paleth]], und dessen unheimliche Macht hält die Seelen der [[Menschen]] in den verrottenden Wracks. Um den Fluch zu brechen und alle zu befreien, muss man das [[Auge von Paleth]] bergen und reinigen. Es wurde in der Geldkassette des Schiffs verwahrt wurde, zu dem nur [[Kapitän Halyndor]] den Schlüssel hatte und dieser läuft auf seinem untergegangenen Schiff noch herum.",},
			["Invasionspunkt"] = { content = "Ein '''Invasionspunkt''' ist eine Stätte der [[Brennende Legion|Brennenden Legion]]. Das Hauptmerkmal eines jeden Invasionspunktes sind ein oder mehrere [[Warptor]]e, Transporter durch die die Truppen den Legion im Umland ihre Verstärkung erhalten.\r\n==Bekannte Invasionspunkte==\r\n* [[Invasionspunkt: Katastrophe]]\r\n* [[Invasionspunkt: Vernichter]]\r\n* [[Invasionspunkt: Zerstörer]]",},
			["Invasionspunkt: Katastrophe"] = { content = "Der '''Invasionspunkt: Katastrophe''' liegt im [[Schattenmondtal]].\r\nDie [[Allianz]] und die [[Horde]] haben je einen Vortrupp zu diesem [[Invasionspunkt]] geschickt, der einen Plan entwickeln soll, wie sie die Vorräte der Brennenden Legion dort zerstören können. Der beste Weg, um diese Vorräte zu zerstören, ist, ihre eigenen Waffen gegen sie zu verwenden. \r\nDie beiden Tüftler [[Plexi]] und [[Nakansi]] haben dafür eine Anlage gebaut, mit deren Hilfe man ein Schildwache der [[Teufelshäscher]] dort steuern kann. Es gibt jedoch noch einige Dinge, die sie zuerst herausfinden müssen. Dafür benötigen sie das Handbuch '[[Die Kunst der Teufelshäscherwartung]]', das [[Doktor Gutrick]] und [[Doktor Maleficus]] in einer Truhe verschlossen halten. Die Brennende Legion ist zwar nicht für Ihre Meisterwerke der Weltliteratur bekannt, aber es sollte seinen Zweck erfüllen. \r\nPlexi und Nakansi haben den Plan, mittels einer Teufelshäscherfernsteuerung, eine Schildwache der Teufelshäscher zu steuern und so viele todesgeschmiedete [[Höllenbestien]] zu zerstören wie möglich, bevor der Teufelshäscher versagt. Teufelshäscher sind nicht wirklich dafür konstruiert, ferngesteuert zu werden, aber sie können einen davon so umbauen, dass es für kurze Zeit funktioniert. Sie müssen schnell arbeiten. Sonst kann keiner die Folgen absehen. Es wäre auch nicht verwunderlich, wenn das kleines Kunststück mit dem Teufelshäscher die Aufmerksamkeit der Lakaien der Legion auf sich ziehen würde.",},
			["Invasionspunkt: Zerstörer"] = { content = "Der '''Invasionspunkts: Zerstörer''' liegt im Süden von [[Nagrand]]. Das [[Warptor]] hier liefert der [[Brennenden Legion]] beim Teufelshäscherhügel immer mehr Verstärkung. Und die Dämonen werden immer mutiger. Erst wenn dieses Warptor außer Gefecht ist, können die Dämonen in der Nähe keine Verstärkung mehr holen. [[Drijya]], ein der [[Astraler]] des [[Konsortium]]s, hat sich aufgemacht, um die Gegend zu erkunden und zu schauen, ob er etwas gegen die Warptore der Legion ausrichten kann. Doch er braucht Begleitschutz, wenn er die Sabotage am Warptor durchführt.",},
			["Invasion der Geißel"] = { content = "Die '''Invasion der Geißel''' begann am 23. Oktober 2008.\r\n==Verlauf==\r\n* '''23. Oktober''': Invasion startet in [[Beutebucht]] - Sonderbare Kisten stehen in der Beutebucht, die bei Berührung Krankheiten auslösen können. Argentumheiler erschienen in den Hauptstädten, und Zombies belagern den Hafenbereich von [[Beutebucht]] im [[Schlingendorntal]].\r\n* '''24. Oktober''': Seuchenquellen in den Hauptstädten - In den Hauptstädten wurden verseuchte Schaben und Kisten gesichtet.\r\n* '''25. Oktober''': Ankunft der Nekropolen - in ganz Azeroth sind Nekropolen aufgetaucht, die in verschiedenen Zonen für ordentlich Unruhe sorgen. In den betroffenen Gebieten gilt es dann, ganze Scharen untoter Schergen niederzustrecken. [[Tendris Mirkblood]] tauchte in [[Karazhan]] auf. Vor allen großen Städten befinden sich sonderbare Kreise, die von Geistern belagert werden.\r\n* '''26. Oktober''': Zombie-Tricks - Die Seuche breitet sich immer schneller aus und wird immer schwerer zu stoppen. Es wurde bekannt, dass die modrigen Gesellen zumindest auf Horden-Seite die Köpfe von [[Onyxia]] oder [[Nefarian]] stibitzen, wenn diese gerade ausgestellt sind. Außerdem können die Zombies mit den Hologramm-Projektoren in Shattrath herumspielen oder die Türen zur Halle der Champions schließen. \r\n* '''27. Oktober''': [[Großapotheker Putress]] und [[Bischöfin Lazaril]] in [[Shattrath]] - Der Chefapotheker steht samt Forschern und Monströsen Boten auf der Terrasse des Lichts in Shattrath und sucht Mitglieder der [[Horde]]. Gegenüber wartet Bischöfin Lazaril mit einem wichtigen Auftrag für Bürger der [[Allianz]]. Verschiedene neue Gegner warten in den alten Gemäuern von Kalimdor und den Östlichen Reichen: [[Sever]] (Burg Schattenfang), [[Scorn]] (Friedhof / Scharlachrotes Kloster), [[Lady Falther'ess]] (Hügel der Klingenhauer), [[Revanchion]] (Düsterbruch-West), [[Lord Blackwood]] (Scholomance), [[Balzaphon]] (Stratholme).",},
			["Irdene"] = { content = "Die Irdenen sind die erste Rasse, welche die [[Titanen]] nach dem Kampf gegen die [[Alte Götter|Alten Götter]] von [[Azeroth]] künstlich geschaffen hatten. Sie fungieren als eines der Stammvölker und sind eine Art von Wächtern für die Städte der [[Titanen]], welche in [[Tanaris]] unter dem Namen [[Uldum]], im [[Ödland]] unter dem Namen [[Uldaman]] und in [[Nordend]] unter dem Namen [[Uldur]] befinden. Die Irdenen dienten den Schöpfern auch als Helfer bei der Formung der Tiefen dieser Welt. \r\n==Synthesematrix==\r\nDer [[Bewahrer der Lehren von Norgannon]] in [[Uldaman]] erzählt, dass die Irdenen eine Abwandlung der Standardmatrix für unterirdische Lebewesen darstellen, wie sie die Schöpfer auf anderen Welten benutzt haben. Bei der Kontruktion dieses Prototyps entstanden diverse Anomalien, die allerdings erst später bemerkt wurden. Die Matrix für unterirdische Lebewesen ist eine der Synthesematrizen, die die Schöpfer beim Anlegen einer Welt verwenden. Jede Synthesematrix dient dabei einem Ziel der Schöpfer. Für Azeroth wurde die Matrix für unterirdische Lebewesen so modifiziert, dass ein andauerndes Wesen mit einer Vorliebe für die Formung tiefer Regionen entstand: Die Irdenen sind das Ergebnis dieser Modifikation. \r\n==Anomalien==\r\nNachdem die Irdenen den Dienst für die Schöpfer aufgenommen hatten, kam es zu unvorhergesehenen Problemen, wenn die Synthesematrix unter hohen Stressdruck geriet. Um diese Anomalien zu verstehen, muss man einiges zum Hintergrund der Irdenen wissen. Die Anomalien der Irdenen erklären sich aus dem Zweck, zu dem sie geschaffen wurden. Die Irdenen sind ein Versuch der Schöpfer, die Standardmatrix für unterirdische Lebewesen überlebensfähiger zu machen. Zu diesem Zweck wurde besagter Matrix ureigenstes widerstandsfähiges Material aus der Welt hinzugefügt. Das ist das Grundmaterial für die Schaffung ganzer Völker. \r\nDas einzige Problem bei den Irdenen besteht in ihrer tendenziellen Instabilität unter hohem Stressdruck. Addendum: Die neue Matrix war speziell für die Formung tiefer Erdschichten geschaffen worden und erfüllte folglich niemals Anforderungen zur Duplizierung einer Hochstressdruckumgebung. Doch diese Destabilisierung wurde erst lange nach dem Beginn des ersten Dienstleistungszyklus' für die Schöpfer festgestellt. Die Schöpfer nahmen nachträgliche Änderungen vor, statt noch einmal von vorn zu beginnen.\r\nEs gibt zwei mögliche Ergebnisse, wenn sich die Synthesematrix der Irdenen destabilisiert:\r\n* Die erste Matrixvariante ist ein degeneratives Syntheseprodukt, für gewöhnlich als \"'''[[Troggs]]'''\" bezeichnet.\r\n* Die zweite resultierende Abweichung von der Matrix für die Irdenen weist im Vergleich zur Standardmatrix der unterirdischen Lebewesen viele erwünschte Elemente auf. In der Regel wird diese Form als \"'''[[Zwerg]]'''\" bezeichnet.\r\n==Aufbau==\r\nFür die Schaffung der Irdenen wurde statt der üblichen Biomasse ein Querschnitt der Erdoberfläche [[Azeroth]]s verwendet. Eine Analyse der Zusammensetzung der Welt hatte die Schöpfer zu der Theorie geführt, dass sie daraus ein intensiviertes Lebewesen erschaffen könnten, das die Widerstandsfähigkeit der Essenz dieser Welt hat. Dies erreichten so durch eine Mischung des Gesteinsmaterials von [[Azeroth]] als Grundlage. Die Irdenen bestanden also aus Stein.\r\nRein äußerlich betrachtet gleichen die Irdenen klein gewachsenen Humanoiden, aber sie bestehen aus den diversen Komponenten des Gesteinsmaterials Azeroths. Dadurch wurden Kraft und Ausdauer maximiert, ohne dass dies zu Lasten ihrer kognitiven Fähigkeiten ging. Haut und Muskulatur sind praktisch nicht zu beschädigen, und mit nur sehr schwachen Modifikationen zeigen die Irdenen erstaunliche Widerstandsfähigkeit gegen Magie. \r\nMan muss unbedingt wissen, dass die Schöpfer ein Volk schaffen wollten, das lange nach ihrer Abreise noch integraler Bestandteil des Entwicklungszyklus' der Welt sein würde. Dieses Volk sollte die langfristigen Entwicklungsziele für Azeroth erfüllen. Der Name \"die Irdenen\" schien den Schöpfern angesichts der Zusammensetzung des neuen Volkes im Übrigen nur passend.\r\nIn [[Uldaman]] kann man die Irdenen noch antreffen, auch wenn sie einem feindlich gesinnt sind.\r\n==Persönlichkeiten==\r\n* [[Goggeroc]]",},
			["Irdenen"] = { content = "#REDIRECT [[Irdene]]", redirect = "Irdene",},
			["Irdener Ring"] = { content = "Der Irdene Ring ist eine schamanistische Gruppe, die sich dem Studium und dem Erhalt der Elemente widmet. Sie hat bereits mehr über verrückte alte Götter und uralte Legenden und Lehren vergessen, als die meisten Gelehrten jemals in Erfahrung bringen werden. Der Irdene Ring hatte nur die besten Absichten, was die geplagten Brüder der Kurenai betraf, aber wer weiß schon, welche Absichten jene verfolgen, die dem Ältestenrat des irdenen Ringes Dinge einflüstern? \r\n==Persönlichkeiten==\r\n* '''Arechron''' – Kurenai. Anführer der [[Kurenai]] und des „Irdenen Ringes“.\r\n* '''Elementarist Ioki''' ist nach [[Telaar]] in [[Nagrand]] gekommen, um die [[Kurenai]] über den Status der Elemente zu informieren.\r\n* '''Elementarist Lo’ap''' am Thron der Elemente in Nagrand möchte, dass man die besudelten Seegeister tötet. \r\n* '''Elementarist Morgh''' am Thron der Elemente in Nagrand spricht Kalimag und geht gegen den Finsterblutstamm vor. \r\n* '''Elementarist Untrag'''\r\n* '''Elementarist Yal’hah''' ist nach Garadar in [[Nagrand]] gekommen, um die [[Mag'har]] über den Status der Elemente zu informieren.\r\n* '''Elementaristin Sharvak''' befindet sich in [[Nagrand]] am Thron der Elemente.\r\n* '''Erdheiler Gorboto''' befindet sich im [[Schattenmondtal]] am Altar der Verdammnis\r\n \r\n* '''Erdheiler Griffelhuf''' befindet sich im [[Schattenmondtal]] im Dorf Schattenmond\r\n* '''Erdheiler Sophurus''' befindet sich im [[Schattenmondtal]] \r\n* '''Erdheiler Torlok''' befindet sich im [[Schattenmondtal]] \r\n* '''Erdheilerin Wilda''' befindet sich im [[Schattenmondtal]] \r\n* '''Je’neu Sancrea''' befindet sich in [[Eschental]] am Zoram'gar-Außenposten\r\n* '''Rimblat Erdspalter'''",},
			["Irdener Templer"] = { content = "'''Irdene Templer''' sind Stufe 60 Elite [[Erdelementare]] und gehören zum [[Abyssischer Rat|Abyssischer Rat]]. Sie können mittels eines [[Wappen der Anrufung]] an den geringen [[Windsteinen]] in [[Silithus]] beschworen werden. Um das Wappen der Anrufung herzustellen, braucht man die entsprechende Schriftrolle, Unverwüstliches Leder und Dichten Stein. Für die Benutzung des Geringeren Windsteins wird außerdem ein [[Zierratset der Schattenhammer]] benötigt.",},
			["Irissee"] = { content = "#REDIRECT [[Überreste des Irissees]]", redirect = "Überreste des Irissees",},
			["Irrwisch"] = { content = "Irrwische sind uralte Naturgeister, die die Wälder von Kalimdor bevölkern. Legenden besagen, dass Irrwische eigentlich die körperlosen Geister der Nachtelfen selbst sind, aber diese Gerüchte müssen erst noch bewiesen werden. Die Irrwische agieren im Einklang mit den Nachtelfen und stärken die halbgottähnlichen Bäume, die auch als die Alten bekannt sind. Herbeigerufen von den Nachtelfen können die Irrwische verschiedene Bäume beleben und sich selbst in grob-kantige Strukturen lebendigen Holzes oder Stein verwandeln.",},
			["Isfar"] = { content = "Isfar ist ein [[Arakkoa]] am Eingang der [[Sethekkhallen]] von [[Auchindoun]]. \r\nEs ist der jüngere Bruder von [[Dunkelwirker Syth]], der noch immer ihre gemeinsame Schwester [[Lakka]] in den [[Sethekkhallen]] gefangen hält und Isfar kann es nicht über sich bringen, ohne seine Schwester nach [[Shattrath]] in die Zuflucht der Ausgestoßenen der Skettis zurückzukehren. \r\n==Hintergrund==\r\nDie [[Arakkoa der Sethekk]] haben [[Skettis]] mit Fanfaren verlassen, als [[Auchindoun]] explodiert ist und sahen es als Vorbote für die Ankunft ihres Meisters. Isfars Bruder, [[Dunkelwirker Syth]], war einer ihrer Anführer und hat den [[Arakkoa der Sethekk]] gesagt, dass es ihre Pflicht wäre, in die Tempelruinen von [[Auchindoun]] zu gehen und ihrem Gott zu begegnen. Aber nachdem sie ihr Lager in den Ruinen aufgeschlagen und sie die [[Sethekkhallen]] getauft hatten, kamen Isfar Zweifel an den Fähigkeiten seines Bruders und seines Verbündeten, [[Klauenkönig Ikiss]]. Nach einiger Zeit hat ihn [[Dunkelwirker Syth]] dann aus den Hallen geworfen und ihm verboten, seine Schwester [[Lakka]] mitzunehmen. \r\nEr hat sich deshalb entschlossen, von der Zuflucht in [[Shattrath]] wieder auf eigene Faust nach [[Auchindoun]] zu gehen, um seine Schwester zu befreien. Doch ohne Hilfe wird er es nicht schaffen. Er hatte zwar das Glück, den [[Sethekkhallen]] einmal zu entkommen, aber wenn die [[Arakkoa]] ihn dort erwischen, wird es kein zweites Mal geben, denn er hat die Lügen der [[Arakkoa der Sethekk]] durchschaut und gehört nicht mehr zu ihnen. Zu wissen, dass [[Lakka]] frei ist, bedeutet, dass er endlich all seine Bande zu den [[Arakkoa der Sethekk]] abwerfen kann. Er denkt auch, dass der Geist seines Bruders zur Ruhe kommen kann, wenn er für die Irreführung ihres Volkes gebüßt hat und die Todesriten für ihn vollzogen wurden. Ein Teil von Isfar wird sich zwar [[Dunkelwirker Syth|Syths]] Tod niemals verzeihen können, aber es muss getan werden...",},
			["Ishaals Almanach"] = { content = "'''Ishaals Almanach''' ist ein geheimnisvoller Foliant, der von [[Krallenpriester Ishaal]] innerhalb der [[Wälder von Terokkar]] verwahrt wird. Die darin abgebildeten arkanen Symbole und Schaubilder von Himmelskörpern sind völlig fremd. Sämtliche Aufzeichnungen wurden in einer unverständlichen Sprache verfasst; vermutlich eine uralte Form der [[Arakkoa]]schriftsprache. Ishaals Almanach prophezeit die Rückkehr von [[Terokk]], dem mächtigsten und furchtbarsten [[Skettis]]könig der Arakkoageschichte. Man hat dies immer für eine Legende gehalten. Die Wiederkehr der [[Krallenpriester]] und die Entdeckung dieses Folianten belehren manche jedoch eines Besseren.\r\n[[Himmelskommandant Adaris]] im Norden von [[Skettis]], sowie danach [[Rilak der Erlöste]] im unteren Viertel in [[Shattrath]] werden sich für dieses Buch interessieren.",},
			["Ishamuhale"] = { content = "Ishamuhale bedeutet Speerzahn und er ist der wildeste [[Bluthornraptor]] des [[Brachland]]es. Er jagt weder zum Spaß noch für Nahrung. Er jagt, weil Jagen seine Leidenschaft ist. Er tötet, weil Töten seine Natur ist. Wenn man seine Lieblingsbeute erlegt, ein [[Zhevra]], und den Kadaver zum toten Baum im Nordwesten von [[Ratschet]] bringt, wird Ishamuhale den Kadaver riechen und von ihm angezogen werden.",},
			["Isha Awak"] = { content = "'''Isha Awak''' ist ein gewaltiger [[Dreschadon]] vor der [[Händlerküste]] im [[Brachland]]. Er, die Tiefste Verdammnis, ist der Herr über diese Gewässer. Groß ist seine Kraft und edel sein Stolz. Die Menschen an der [[Händlerküste]] fürchten ihn, denn er hat großen Schaden unter ihnen angerichtet. Er ist eine würdige Herausforderung und das Herz von Isha Awak eine ehrenhafte Beute für einen Jäger. Sein Geist wohnt in seinem Herzen, und dieses schlagen zu hören heißt, das Schicksal zu kennen.",},
			["Ivarfeld"] = { content = "Das '''Ivarfeld''' befindet sich nördlich des [[Grabmal]]s im [[Silberwald]]. Vor einigen Wochen wurden zwei der [[Todespirscher]], Rane und Quinn Yorick, auf eine Aufklärungsmission durch den nördlichen Silberwald geschickt und man hat seitdem nichts mehr von ihnen gehört. Rane Yorick und ihr Bruder Quinn wurden beauftragt, den Silberwald auszukundschaften und [[Hochexekutor Hadrec]] Bericht zu erstatten. Aber sie kamen nicht weit - denn als sie über diese Farm gingen, wurden sie von einem [[Ghul]] namens [[Ivar der Verfaulte]] angegriffen. Sie entkamen Ivar, aber er verletzte Quinn schwer und Rane glaubt nicht, dass er ohne magische Hilfe wieder vollständig genesen wird. Dank eines Tranks aus verfärbten Worgherzen , den [[Apotheker Renferrel]] auf dem [[Grabmal]] herstellen kann, werden die Verletztungen heilen, aber Rane fürchtet, Ivar könnte wiederkommen bevor Quinn sich erholt hat und Ivars abgetrennten Kopf zu sehen, würde sie deutlich beruhigen. Und auch wenn Quinns Wunden heilen, möchte Rane doch den Bericht so schnell wie möglich zu [[Hochexekutor Hadrec]] bringen, denn er enthält Informationen, die für die Besetzung des Silberwaldes durch die Verlassenen von höchster Wichtigkeit sind.\r\n==Personen==\r\n* '''Ivar der Verfaulte''' - Ivar der Verfaulte hält sich üblicherweise einem Schuppen auf und wartet darauf, dass die Wachsamkeit der Todespirscher nachlässt.\r\n* '''Todespirscher Quinn''' - Todespirscher Quinn ist der Bruder von [[Todespirscherin Rane Yorick]] und wurde von dem Ghul Ivar dem Verfaulten schwer verletzt. \r\n* '''Todespirscherin Rane Yorick''' - Todespirscherin Rane Yorick ist die Schwester von [[Todespirscher Quinn]].",},
			["Ivus der Waldfürst"] = { content = "'''Ivus der Waldfürst''' ist ein [[Urtum des Krieges]] im [[Alteractal]].",},
			["Jadefeuertal"] = { content = "#REDIRECT [[Satyre der Jadefeuer]]", redirect = "Satyre der Jadefeuer",},
			["Jaedenar"] = { content = "Jaedenar ist der Sitz des [[Schattenrat]]s und mit Recht nennt man den Höhlenteil von Jaedenar Schattenfeste, denn der gleichnamige Kult ist hier weiterbreitet und nutzt neben einem verderbten Mondbrunnen und anderen Ruinen auch zwei von ihnen bewohnte verderbte Grabhügel als Tempelanlage. Es ist die Hauptfestung der Verderbnis und des Bösen und der [[Schattenrat]] verfügt über Schutzzauber in Form von Kohlenpfannen, die seinen Unterschlupf umgeben.\r\nIn Jaedenar schmiedet der [[Schattenrat]] Pläne zusammen mit der [[Brennende Legion|Brennenden Legion]].\r\n==Personen==\r\n* '''Arko'narin''' ist eine Nachtelfe und wird in der Feste gefangen gehalten. Sie will, dass man Jessir Mondsichel im [[Smaragdrefugium]] aufsucht und erzählt, was mit ihren Freunden geschehen ist. Doch es gibt eine Sache, die zuerst erledigt werden muss. Sie muss Treys Schwert Lichtschmied finden und aus der Schattenfeste entkommen, um den Vorgesetzten zu berichten, was hier geschieht. Nachdem sie entkommen sind, wird sie nach Darnassus gehen.\r\n* '''Rakaiah''' ist eine [[Sukkubus]] und agiert als Folterknecht in der Feste.\r\n* '''Schattenlord [[Fel'dan]]''' ist der derzeitige Anführer des [[Schattenrat]]es. Zu ihm gehören seine beiden [[Sukkubi]] [[Moora]] und [[Salia]].\r\n* '''Trey Lichtschmied''' ist ein Paladin und Freund von Arko’narin, der in der Schattenfeste sein Leben verlor. \r\n* '''Ulathek''' ist ein Diener von [[Lord Schattenfluch]]s und treibt ein erbärmliches Spiel. Während er wie ein elender Wurm vor Schattenfluch kriecht, konspiriert er heimlich mit [[Lord Hel'nurath]] von [[Xoroth]]. [[Lord Hel'nurath]] trachtet danach die Macht an sich zu reißen und Ulathek ist sein Spion.",},
			["Jagdhütte der Weltenwanderer"] = { content = "Jagdhütte der [[Weltenwanderer]] steht inmitten der östlichen Berge von [[Loch Modan]]. So manchen Jäger zieht es an den Loch, um seine berühmten [[Krokolisk]]en zu erlegen und irgendein Händler sucht immer [[Krokilisk]]enhäute für seine Kleidungsstücke oder Rüstungen und es gibt auch einige Leute, denen das Fleisch mundet. Die [[Hochelfen]] der [[Weltenwanderer]] hier handeln ein wenig damit, aber nicht wirklich viel, denn die [[Krokilisk]]en sind wild und haben sich auf den Inseln im Loch verschanzt.\r\n==Personen==\r\n* '''Daryl der Jüngling''' - Vor einem Jahr war ein großer Bär das Ziel der Jagdhütte, aber keiner der [[Jäger]] hatte Glück mit ihm. Also dachte sich Daryl, er könnte sich mal an ihm versuchen. Doch das einzige, was er nach seinem Versuch vorweisen konnte, war die hässliche Narbe über seinem Auge. \r\n* '''Marek Eisenherz''' sucht immer Krokiliskenfleisch und Krokiliskenhäute für den Verkauf.\r\n* '''Vyrin Flinkwind''' will Rache an dem Bären [[Alte Rußtatze]].",},
			["Jagdhütte von Quel'Danil"] = { content = "Die '''Jagdhütte von Quel'Danil''' liegt im Nordwesten des [[Hinterland]]s und ist ein Stützpunkt der [[Hochtalelfen]]. Es ist ein Zentrum der Kommunikation für die [[Hochelfen]] des [[Hinterland]]s und ihre Botschafter sind damit beschäftigt, Beziehungen zu anderen Völkern zu knüpfen, mit denen sie ihr Wissen über die [[Trolle der Bleichborken]] teilen, die das Gebiet im südlichen [[Hinterland]] bewohnen. Alle Aufzeichnungen betreffs dieses Nachrichtenaustauschs werden in der Hütte aufbewahrt.\r\nDer Troll [[Rin'ji]] gehört zu den [[Bleichborken]]. Er lebt eigentlich im [[Hinterland]], wurde aber bei der Jagdhütte von Quel'Danil gefangen genommen. Nun steckt er hier in der Falle und braucht eine Eskorte hinaus. Rin'ji hat ein Geheimnis bei den Aussichtsklippen im Osten versteckt und wird es mit seinen Befreiern teilen.",},
			["Jagdhütte von Quel'Lithien"] = { content = "Die '''Jagdhütte von Quel'Lithien''' befindet sich an der nördlichsten Grenze der [[Östliche Pestländer|Östlichen Pestländer]]. Die [[Hochelfen]] der Jagdhütte werden von [[Waldläuferlord Falkenspeer]] angeführt.",},
			["Jaina Proudmoore"] = { content = "#REDIRECT [[Lady Jaina Prachtmeer]]", redirect = "Lady Jaina Prachtmeer",},
			["Jammal'an der Prophet"] = { content = "'''Jammal'an der Prophet''' ist ein Troll der [[Atal'ai]] im [[Versunkener Tempel|Versunkenen Tempel]] in den [[Sümpfe des Elends|Sümpfen des Elends]]. Er ist der spirituelle Anführer des großen Atal'ai-Stammes und glaubt, wenn Hakkar aus dem Nether nach Azeroth zurückkehrt, wird der Gott den Trollen der Atal'ai Unsterblichkeit gewähren. Jammal'ans blindes Vertrauen in falsche Visionen führte sein Volk in die ewige Verdammnis. Sein unerschütterlicher Glaube an seine Prophezeiung wird den Untergang der Atal'ai herbeiführen.",},
			["Jan'alai"] = { content = "'''Jan'alai''' ist der Avatar des [[Drachenfalke]]n in [[Zul'Aman]]. Er ist ein gefährlicher Gegener, mit der Macht, Feuer zu speien. Jan'alai ist einer der von den [[Amani]] am meistenverehrtester [[Loa]], direkt nach [[Ula'tek]]. Seine Anwesenheit spornt die [[Amani]] zu unglaublichen Heldentaten an.",},
			["Jandice Barov"] = { content = "'''Jandice Barov''' ist eine [[Untote]] aus dem [[Haus Barov]] in den versunkenen Katakomben der [[Scholomance]]. Zu Lebzeiten war sie die Tochter von [[Lord Alexei Barov]] und [[Lady Illucia Barov]]. Doch wie so viele ihrer Familie verfiel auch sie der [[Geißel]]. Es heißt, dass sie es nun ist, die das [[Blut Unschuldiger]] von [[Doktor Theolen Krastinov]] zu [[Kirtonos der Herold|Kirtonos den Herold]] bringt, damit er beschworen werden kann. \r\n==Tagebuch==\r\nDas Tagebuch von Jandice Barov ist voll von irrem Geschreibsel über Untote. Gegen Ende des Tagebuches aber ist etwas verzeichnet, was wie ein Muster für die Herstellung einer Art Tasche aussieht. Wenn man genug von der [[Schneider]]ei versteht, kann man dieses Muster entziffern. \r\n==Fähigkeiten==\r\n* '''Blutfluch''' - Der Blutfluch erhöht den erlittenen körperlichen Schaden von in der Nähe befindlichen Feinden 10 Minuten lang um 2. \r\n* '''Illusionen beschwören''' - Jandice Barov beschwört in regelmäßigen Abständen 15 Illusionen, um im Kampf zu helfen und den Feind abzulenken. Diese Illusionen bleiben 30 Sekunden lang bestehen.\r\n* '''Verbannen''' - Jandice Barov verbannt in regelmäßigen Abständen einen Feind und verhindert damit jegliche Aktion, macht ihn damit aber bis zu 15 Sekunden lang unverwundbar. Es kann immer nur jeweils ein Ziel verbannt werden.",},
			["Jarod"] = { content = "#REDIRECT [[Kommandant Jarod Schattensang]]", redirect = "Kommandant Jarod Schattensang",},
			["Jaspismine"] = { content = "=== Jaspismine===\r\nDie Jaspismine liegt etwas westlich des [[Steinhügelsee]]s und ist unter der Kontrolle von [[Kobolde von Elwynn]]n. Die Mine erreicht man, indem man der Straße nach Osten folgt, bis man zum [[Turm von Azora]] kommt. Wenn man sich am Turm nach Norden wendet, dann findet man die Mine im Vorgebirge. Manchmal haben die [[Kobolde]] in dieser Gegend Goldstaub dabei.",},
			["Jediga"] = { content = "'''Jediga''' wurde von [[Belgrom Felshammer]] in [[Orgrimmar]] nach [[Valormok]] in [[Azshara]] strafversetzt. Doch sie hat das Beste aus der Situation gemacht, denn [[Belgrom Felshammer|Belgrom]]s Bestrafung hatte seine Vorteile. Bevor dieser wegging, hat sie einige Nachforschungen angestellt und möchte nun Wissen aus den Ruinen von [[Zin-Azshari]] stehlen, um daraus Kapital zu schlagen.\r\n* Die [[Schrifttafel von Beth'Amara]] soll zu [[Magatha Grimmtotem]] in [[Donnerfels]] geliefert werden.\r\n* Die [[Schrifttafel von Jin'yael]] hat wurde [[Jes'rimon]] in [[Orgrimmar]] versprochen.\r\n* Die [[Schrifttafel von Markri]] wartet auf ihre Abgabe an [[Andron Gant]] nach [[Unterstadt]].\r\n* Die [[Schrifttafel von Sael'hai]] wird zu [[Erzmagier Xylem]] in [[Azshara]] gebracht.",},
			["Jenseits des Dunklen Portals"] = { content = "Nur wenige Monate nach der Vollendung von Nethergarde fügten sich die Energien des Dunklen Portals zusammen und öffneten ein neues Tor nach Draenor. Die verbliebenen Orc-Klans stürmten unter der Führung des großen alten Schamanen Ner’zhul abermals nach Azeroth. Sie wollten einige magische Artefakte stehlen, die Ner’zhuls Macht noch vergrößern sollten, und schmiedeten den Plan, neue Portale in Draenor zu öffnen, mit denen sie ihrer todgeweihten roten Welt für immer entfliehen konnten. König Terenas von Lordaeron schickte seine Armeen in der Überzeugung, dass Ner’zhul eine neue Offensive gegen die Allianz plante, nach Draenor, um die Bedrohung durch die Orcs ein für alle Mal zu beenden. Unter Führung von Khadgar und General Turalyon kam es überall in der brennenden Landschaft zu schweren Zusammenstößen zwischen den Streitkräften der Allianz und den Orcs. Doch nicht einmal mit Unterstützung der Elfen-Waldläuferin Alleria, des Zwergs Kurdran und des Soldatenveteranen Danath konnte Khadgar verhindern, dass Ner’zhul Portale zu anderen Welten öffnete. Die ungeheuren, von den konvergierenden Energien der Portale ausgelösten magischen Stürme begannen, die verwüstete Welt auseinander zu reißen. Ner’zhul gelang in Begleitung seiner treuesten Diener die Flucht durch eines der Portale, während Khadgar sich verzweifelt bemühte, seine Kameraden nach Azeroth zurückzubringen. Obschon ihnen klar bewusst war, dass sie dann auf der sterbenden Welt gefangen wären, fassten Khadgar und seine Kameraden den selbstlosen Entschluss, das Dunkle Portal zu zerstören, damit Azeroth durch die brutale Vernichtung von Draenor keinen Schaden nehmen sollte. Wie es scheint, konnten die Helden das Portal zerstören und Azeroth retten –doch bleibt abzuwarten, ob sie dem Todeskampf von Draenor zu entkommen vermochten oder nicht.",},
			["Jergosh der Herbeirufer"] = { content = "'''Jergosh der Herbeirufer''' ist ein [[Orc Hexenmeister]] im [[Flammenschlund]] unter [[Orgrimmar]]. Er fungiert neben [[Bazzalan]] als einer der Anführer der [[Sengende Klinge|Sengenden Klinge]].",},
			["Jerods Anlegestelle"] = { content = "=== Jerods Anlegestelle===\r\nDie Agenten des [[SI:7]] melden starke Aktivitäten der [[Defias]] südlich von [[Goldhain]] an Jerods Anlegestelle. Die Berichte deuten an, dass sie hier nun große Mengen Hehlerware vom [[Rotkammgebirge]] nach [[Westfall]] schmuggeln.",},
			["Jes'rimon"] = { content = "'''Jes'rimon''' ist ein [[Troll Schurke]] und Mitglied der [[Zerschmetterte Hand|Zerschmetterten Hand]]. Wenn man sich in [[Orgrimmar]] in der Gasse in einem der höchsten Gebäude umschaut, sollte man ihn ohne Probleme finden können. Er befindet sich ganz oben im Haus. Er verdient sein Geld als Hehler und machte u.a. einen vorteilhaften Handel mit [[Jediga]] in [[Azshara]]. Jes'rimon war ganz aufgeregt, als er vom Aufenthaltsort der [[Schrifttafel von Jin'yael]] erfahren hat. Er hat als Mitglied der Hand auch Kunden, denen Knochenklingenwaffen gefallen, die aus [[Ravasaurus]]klauen gefertigt wurden.",},
			["Jian'ky"] = { content = "'''Interpretationsquelle:''' [[Anduri Stamm]] \r\n'''Jian'Ky – Der Gorilla''' ist der Vater des Dschungels und Häuptling der anderen Götter. \r\nIn seiner großen Weisheit ist er gelassen und ein Ratgeber für alle, die nicht mehr weiter wissen. Der Gorilla redet nicht viel, seine Weisheiten sind von erstaunlicher Einfachheit. Wenn er jedoch erzürnt ist, ist er ein unerbittlicher Kämpfer, der jeden seiner Feinde durch pure Kraft niederringen kann. Sein Zorn kündigt sich im Dschungel durch Donner an, auf die heftige Gewitter folgen. \r\nJian'Ky spielt eine wichtige Rolle in den Mannbarkeitsriten mancher [[Dschungeltrolle|Dschungeltrollstämme]]. So werden ihm zu Ehren rituelle Ringkämpfe veranstaltet, bei denen die Jungtrolle ihre Kraft und ebenso ihre Klugheit unter Beweis stellen. Die Teilnehmer tragen hierzu den traditionellen Bananenrock und bemalen sich vor den Kämpfen gegenseitig mit Kriegszeichen, um ihren Respekt vor dem Gegner auszudrücken. \r\nManche Stammeshäuptlinge tragen die Haut eines Gorillas als Zeichen ihrer Identifikation mit dem Vater des Dschungels, ihrer Weisheit und Stärke.\r\n==Ideale == \r\nKraft, Weisheit, Donner/Gewitter",},
			["Jintha'Alor"] = { content = "Jintha'Alor ist die Hauptstadt der [[Trolle der Blutfratzen]] im Süden des [[Hinterland]]s und liegt tief im Herzen des [[Blutfratzen]]-Territoriums. In Jintha'Alor gibt es eine Grube mit [[Brühschlammer]]n, sowie einen Wolfsbau, in denen die Knochen von Gefangenen verfüttert werden. Beide liegen in der Nähe der Tempelspitze. Man wird in ganz Jintha'Alor auch dunkle Gefäße mit besudeltem Blut finden. Die Gefäße verstrahlen die elende Magie des gesichtslosen Blutgottes [[Hakkar]], verleihen den [[Blutfratzen]] Macht und treiben sie zusätzlich in den Wahnsinn.\r\n==Personen==\r\n* [[Ältester Stumpfhauer]]\r\n* [[Hitah'ya die Bewahrerin]] \r\n* [[Scharfschnabel]]\r\n* [[Üble Priesterin Hexx]]",},
			["Jippa"] = { content = "* '''Besonderheiten:''' Adrenalin-Junkie, Gefahrensucherin, extrem gelassen\r\n==Aussehen==\r\nEine schmale und fast zerbrechlich wirkende Trollin kurz vor der Lebensmitte. Attraktiv aber nicht schön, mit scharf geschnittenem Gesicht, markanter Nase und den Augen eines Scharfschützen. Raucht Zigarillos, welche sie meist mit einem herbeigeschnippten, schweißbrennerähnlichen Flämmchen entzündet. Bewegt sich oft träge und langsam, bis sie eine Situation einschätzen kann. Ist dann, zur Überraschung vieler heute toter und vergessener Idioten, in der Lage sehr schnell zu handeln.\r\n==Charakter in Stichworten==\r\nKultivierte Barbarin / zivilisierte Wilde. Lässig, annähernd gewissenlos, in politischen Dingen überraschend vernünftig, manchmal im Widerstreit mit ihren trollischen Instinkten und den Traditionen ihres Volkes, weitgehend frei von Vorurteilen in Bezug auf Rassen und Völker, selbstbewusst bis arrogant, jederzeit gewaltbereit, geschäftstüchtig, mit einer Scheißegal-Haltung ausgestattet die ihr schon viele Feinde eingebracht hat. Keine nette Frau.\r\n==Herkunft==\r\nGhinzan Jippa wurde als Kind einfacher Fischer des barbarischen Darkspear-Stammes geboren und erlebte eine verhältnismäßig normale, traditionelle Troll-Kindheit. Als ihr Vater ihre Mutter wegen einer anderen Frau zu verlassen drohte, war sie vier Jahre alt. Ihre Mutter gewann den traditionellen Zweikampf um den gemeinsamen Besitz und tötete ihren (Ex)Mann, der zum Angedenken von Freunden und Verwandten verspeist wurde (die kleine Ghinzan erhielt zwei Rippchen; siehe auch [[Kannibalismus]]). Ghinzan wuchs gemeinsam mit ihrer später und von einem anderen Mann gezeugten Halbschwester [[Semmi]]h als Kind einer gelassenen, alleinerziehenden Mutter auf.\r\nAls der örtliche [[Mojo]]-Werfer [[Papa Bango]] ihr Potenzial erkannte, wurde Ghinzan als Schülerin an ihn gegeben. Sie redet eher selten über diese Ausbildung. Gelegentlich lässt sie durchblicken, dass sie ihren Lehrer hasste und töten wollte, zeigt aber zugleich großen Respekt vor dem inzwischen am Alter verstorbenen Papa Bango. Sie hat auch bei verschiedenen Gelegenheiten erwähnt, dass der traditionelle Zweig, dem Bango angehörte, seine Schüler täuscht, erniedrigt, quält und zu brechen versucht, bis sie entweder vernichtet und geschlagen aufgeben oder zu Wahrer Macht kommen. Was diese 'Wahre Macht' im Detail ist, hat Jippa niemals erläutert.\r\nDurch Bango erhielt sie eine solide Bildung, eine gewisse Kenntnis des Geschichte ihres Volkes, etc. Unter durchschnittlichen Trollen gilt sie durchaus als gebildet. Da Troll-Magie aber mit der menschlichen oder gnomischen Variante nicht viel gemein hat, liest sie nur seltenst Bücher, verwendet keine 'Zauberformeln' und verzichtet auf jegliche Art von Fachsprache. Auch das scheinbar ein Überbleibsel ihrer Ausbildung und des Geheimnisses, das Bangos Weg zum Mojo umwittert. Worin die Abschlussprüfung bestand, die sie zu Mama Jippa werden ließ, liegt im Dunkeln.\r\n==Geschichte==\r\nDie junge Mama Jippa war eine herumreisende Abenteurerin, Söldnerin, Auftragsmörderin, Sklavenjägerin, ausschließlich an Gold und neuen Erfahrungen interessiert. Arbeitete mehr als ein Jahr lang für den äußerst intelligenten Doomlord Thickbelch, einen der gefährlichsten Verbrecherlords der Sümpfe des Elends. Früh zeigte sich eine beginnende Adrenalinsucht, der Drang sich mit immer härteren Gegnern zu messen, eine an Selbstzerstörung grenzende Lust auf den Tanz auf der Klinge. Dazu kam ein extremer Drogenkosum, den nur der trollische Stoffwechsel verkraften konnte und den sie nach einiger Zeit wieder unterband.\r\nDurch die Bekanntschaft mit [[Zuul]] Jan'zin kam Jippa zum gerade wiederbelebten [[Anduri-Stamm]]. Sie behielt viele alte Verhaltensweisen bei, begann aber gegen ihren Willen, sich zunehmend mit dem Stamm zu identifizieren und einen Beschützerinstinkt für seine Mitglieder zu entwickeln. Ebenso gegen ihren Willen wurde sie zur Ratsfrau erhoben - eine Funktion, die sie mit einem brauchbaren politischen Gespür und ihrer Begabung zur Ansammlung von 'Connections' überraschend zufrieden stellend erfüllt.\r\nIm Laufe der Jahre hatte Mama Jippa, soweit bekannt ist, eine kleine Anzahl von Liebhabern bzw. Kurzzeitbekanntschaften - ihr haftet der Ruf an, in Partnerschaftsfragen wählerisch zu sein. Eine mehrwöchige Beziehung trollischer Art führte sie dem Anschein nach mit dem Anduri-Boss Zuul. Wer von beiden diese Beziehung beendete und aus welchem Grund das geschah, ist unbekannt bzw. wird von beiden Beteiligten uneinheitlich wieder gegeben.\r\n==Jippa heute==\r\nMama Jippa hat gelernt. Sie weiß Freundschaft zu schätzen (auch wenn sie nicht schnell welche schließt) und erwartet Respekt – dafür erhält ihr Gegenüber auch Respekt von ihr. Sie schätzt gutes Essen, saubere Kleidung und weiche Betten und genießt auch heute noch das Gefühl einer gut gefüllten Geldbörse.\r\nIhre Loyalität zu den Ehrenwerten Anduri ist ungebrochen. Wer den Stamm bedroht, muss damit rechnen, dass Jippa in alte Gewohnheiten aus ihrer früheren Karriere zurück verfällt – ohne Warnung zu töten, zur Abschreckung Gegnern beide Arme zu brechen und auf dem Rücken zu verdrahten, aufgespießte Köpfe an Stadttore zu pflanzen, Personen in Gruben voller Snaash-Egel langsam und qualvoll sterben zu lassen, etc. Grundsätzlich ist sie aber ein wenig ‚weicher’ geworden, wenn man bei ihr von ‚weich’ sprechen kann. Jippa schreibt dies ihrer Stellung als Ratsfrau zu und flucht von Zeit zu Zeit ausgiebig darüber.\r\nIn erster Linie zeichnet sie ihre Gelassenheit aus. Mama Jippa grinst, schmunzelt, lacht zwar heute wieder öfter – aber typisch für sie ist eine stoische, undeutbare Mine, die bestenfalls vom erstaunten Heben einer Braue oder leicht geschürzten Lippen gestört wird. \r\nUngebrochen ist auch die Adrenalin-Sucht der Trollin: Abgesehen davon, dass sie sich – um neue, harte Gegner zu finden – dem [[Scherbenkreis]] angeschlossen hat, hat sie als Freischärlerin, Attentäterin und Frau fürs Grobe bereits für annährend jede nicht hordefeindliche Vereinigung Azeroths und der Scherbenwelt gekämpft. Mama Jippa sucht letztendlich immer noch den Kick, das Gefühl auf der Klinge zu tanzen, von der Explosion mit gerade genug Wucht weggedrückt zu werden, dass die Hitze sie nicht verglühen lässt. Sie ist überzeugt davon, dass sie eigentlich längst tot sein sollte und geht eben so fest davon aus, dass sie eines Tages irgendwo einmal zu langsam sein wird. Nur um eine Milisekunde vielleicht, aber zu langsam. Ein Teil von ihr brennt vor Neugier darauf, wer es ihr endlich zeigen wird.\r\n==Zitate==\r\n* \"Was glotzt du mich so an. Dachtest du ich wär' ne nette Frau? Sorry - ich bin keine nette Frau.\"\r\n* „Hehehe…. Fucko war das knapp.“ ''Grinsend, sich Blut aus dem Gesicht wischend, nach einem Kampf der die Hälfte der Einheit ausgelöscht hat''.\r\n* „Hey mann, ich zeig Res’pekt für dich. Zeig’ ich keinen Res’pekt? Aber du mann, du zeigst mir keinen. Wie soll ich reagieren, wenn ein Mann wie du zu mir kommt, und sich res’pektlos verhält. Was denkst du, sollte ich tun.“\r\n* „Yuu’kiip vaat yuu’kiil.“\r\n* „Und das ist wieder so’n Tag, Babys. Wo wir uns umseh’n und feststellen, dass wir genau so gut hätten draufgeh’n können. Aber wenn ihr heute Nacht besoffen in eure Betten fallt, vielleicht noch’n wenig fookah mit eurem Auserwählten macht, spürt wie das Blut durch euch pumpt – hey, dann könnt ihr euch sagen ‚Heute nicht. \r\n''Heute'' noch nicht.’“\r\n* „Man kriegt seine Karten. Man spielt das Spiel. Das ist alles was zählt, mann. Wer das nicht kann – wer abklopft, schlapp macht, aufgibt: Hey, keiner zwingt einen zu spielen.“\r\n==Hintergrundmaterial==\r\nFolgende Geschichten sind im Lauf der letzten Jahre entstanden und beschäftigen sich mit Mama Jippa bzw. ihrer Vergangenheit:\r\n* [[Tod eines Meisters]]\r\n* [[Busi'ness im Sumpf]]\r\n* [[Auch ein Anfang]]\r\n* [[Söldner]]\r\n* [[Ein anderes Land]]\r\n* [[Margreth Tiffen I: Miss Tiffen lacht]]\r\n* [[Qu'aath über Lanzenspitze]]",},
			["Jorad Knüpp"] = { content = "Der Paladin '''Jorad Knüpp''' ist [[Tyrigosa]]s Begleiter im [[Sternensturz]] im [[Nethersturm]].\r\n===Warcraft: The Sunwell Trilogy\"===\r\nJorad Knüpp stand in der Comic-Trilogie \"Warcraft: The [[Sunwell Trilogy]]\" als [[Paladin]] einst im Dienst des Prinzen von [[Lordaeron]], [[Arthas]]. Als dieser die [[Allianz]] verriet und das Land mit der [[Geißel]] überrannte, rettete sich Jorad nach [[Tarrens Mühle]] und erklärt sich dort bereit, [[Kalecgos]] und [[Anveena]] bei der Suche nach dem [[Sonnenbrunnen]] zu helfen. Auch der magisch begabte [[Borel]] ist Jorad ein Begriff - er half dem Paladin bereits einige Male. (Quelle:",},
			["Jormungar"] = { content = "Die wilden und aggressiven '''Jormungar''' sind ein Wunder der Evolution. Ihr von Reihen keilförmiger Zähne besetzter Schlund ist dazu fähig, sich durch massiven Fels zu bohren. Die muskulösen, flachen Körper sind der unterirdischen Fortbewegung gut angepasst. Sagen erzählen von Jormungar als Arbeitstieren der [[Neruber]], die sie zwangen mächtige Tunnel durch [[Nordend]]s unterirdisches Eis zu graben und somit die Grundsteine für die alte nerubische Zivilisation zu legen. Mit dem Sturz des nerubischen Reiches brachen Schwärme von Jormungar aus und bohrten sich durch das ewige Eis der Region, griffen die Oberflächenbewohner an und verschlangen alles in ihrem Weg. \r\n'''Quelle:'''",},
			["Jubei'thos"] = { content = "'''Jubei'thos''' war ein [[Klingenmeister]] und Anführer der Orcs des [[Schwarzfelsklan]]s nach der Niederlage der alten Horde. Er verehrte die [[Dämonen]] und bewahrte den Kampfrausch in sich. Doch all seine Ergebenheit zur Legion nützten nichts: Er starb, von den Armeen der [[Geißel]] überrannt, als sie das Dämonentor in ihren Besitz bringen wollten. Er legte jedoch den Keim für die [[Dunkle Horde]], welche jetzt die Welt vom [[Schwarzfels]] aus terrorisiert.",},
			["Juju"] = { content = "'''Juju, das'''\r\n[[Trolle|Trollisches]] Wort für körperliche [[Magie]], d.h. die übernatürliche Kraft von Berserkern, katzenhafte Schnelligkeit von Jägern und Meuchlern, etc. Juju wird von [[Trolle]]n als [[Magie]] verstanden, die sowohl in Gegenstände gebunden als auch einer Person zu eigen sein kann. Der Glaube an Juju wird oft mit der Anrufung von Göttern bzw. Loas verbunden, die dem Betreffenden Juju spenden sollen. Insofern besteht eine enge Beziehung zum [[Voodoo]].\r\n----\r\nJuJu bezeichnet das spirituelle Band von Leben zu Leben, Das Juju ist somit eine Art Seele/Energie die sich auch auf Gegenstände übertragen kann. Als Beispiel sei der Wanderpriester [[Zala'sh Silbermähne]], der Troll mit dem Zauberzopf genannt. Die Kraft seines legendären Zopfen entspringt aus dem einweben von Generationen und Generationen von Haaren seiner Vorfahren in seinen Zopf. Das Juju seiner Ahnen lebte als Echo ihrer Stärke und Seele in seinen Haaren und verlieh seinem Zauberzopf so diese sagenumwobene Macht. JuJu dient Geistsprechern als Leiter im Kontakt mit den Verstorbenen indem sie persönliche Gegenstände befühlen und das dort gespeicherte JuJu befragen erhalten sie einen nebelösen Einblick in die Psyche des Besitzers. Man spricht von der Klugheit des Blutes da sich der persönliche Fluss des JuJus eines Trolls mit dem eines anderen Vermischen kann, z.B bei einem Ritual bei dem Blut eines alten Stammesmitglied verabreicht wird, der trinkende wird durch das gesammelte JuJu eine dunkle,instinktive Ahnung von den Erfahrungen und Strapazen des Lebens des Spendenden erhalten. Sein Blut tritt also in Kontakt mit den Uralten Wurzeln seines Stammes, verbindet sich mit diesen und bildet eine Symbiose mit seinem JuJu. Man spricht von geerbtem Wissen oder dem Blutflüstern.",},
			["Juwelenschleifer"] = { content = "Juwelenschleifer erlernen die Kunst der Herstellung von Schmuckstücken und Kleinoden aus Metallen und seltenen Edelsteinen. Indem sie das rohe Erz, das aus den verschiedenen Erzvorkommen gewonnen wird, weiterverarbeiten, erhalten sie die Edelsteine, die sie für ihr Handwerk benötigen. Obwohl gelegentlich auch [[Bergbau]]er über Edelsteine stolpern, ist die Erfolgsaussicht für die speziell ausgebildeten Juwelenschleifer höher.\r\nJuwelenschleifer verfügen über mehrere Möglichkeiten, Edelsteine zu benutzen. Wenn ein Juwelenschleifer Schmuckstücke herstellt, benötigt er zumeist nur die rohen, ungeschliffenen Steine für seine Arbeit. Diese Ringe, Amulette und Kleinode funktionieren genau so, wie es bisher der Fall war. Allerdings gibt es Ausnahmen: Juwelenschleifer können mit Juwelen besetzte Figuren herstellen, die sie als Schmuck tragen können. Diese Figuren geben passive Boni, können den Charakter aber zusätzlich mit einem kurzen Stärkungszauber versehen, wie beispielsweise einem kleinen Schadensbonus oder zusätzlicher Heilkraft in kritischen Situationen. \r\nJuwelenschleifern bieten sich jedoch noch weitere Möglichkeiten, mit ihren Edelsteinen zu arbeiten. Nachdem sie die Edelsteine geschliffen haben, können diese in gesockelte Gegenstände eingesetzt werden. Die Edelsteine gibt es in verschiedenen Farben und Formen. Verschiedene Edelsteine haben unterschiedliche Eigenschaften und der Schliff eines Edelsteins hat ebenfalls Einfluss auf die Attribute des Steins. Juwelenschleifer können verschiedene Schliffe für die Edelsteine erlernen. So kann der Azurmondstein beispielsweise in einen irisierenden, einen sturmblauen, einen robusten oder einen funkelnden Azurmondstein verwandelt werden, und jeder dieser Schliffe bringt ganz spezielle Eigenschaften mit sich. Nachdem der Stein in einen Gegenstand eingesetzt wird, erhält der Gegenstand diese Eigenschaften und bietet dem Spieler die Möglichkeit, die Ausrüstung an die persönlichen Wünsche anzupassen.\r\n'''Quelle:''' wow-europe.com",},
			["Juwelenschleifer: Rezepte"] = { content = "Hier können Charaktere eintragen werden und welche besonderen Rezepte sie in diesem Beruf beherrschen.\r\n===Violett===\r\n----\r\n'''Siehe auch:''' \r\n* [[Juwelenschleifer]]\r\n* [[Handwerksverzeichnis der Allianz]] \r\n* [[Handwerksverzeichnis der Horde]]",},
			["Jäger"] = { content = "Im Allgemeinen gilt: Jäger sind tödliche Scharfschützen, die ihre Feinde aus der Ferne mit Bogen, Armbrust oder Gewehr erledigen. Als ausgebildete Überlebenskünstler können sie den Spuren ihrer Ziele folgen und ihnen Fallen in den Weg legen. Ihre natürliche Bindung zu allen lebenden Kreaturen erlaubt es ihnen, wilde Tiere für ihren persönlichen Gebrauch als Begleiter zu gewinnen und zu einem Helfer in allen Kämpfen auszubilden. Ausgestattet mit leichter bis mittelstarker Rüstung können sie im Kampf zwei Waffen gleichzeitig nutzen, um neben ihren Begleitern zu kämpfen.\r\n===Tierherrschaft===\r\nJäger die sich auf die Tierherrschaft spezialisiert haben, bilden durch die Geistbande eine geschlossene Einheit mit ihrem Begleiter. Sie rasten zusammen und fühlen zusammen, wie ihre Kräfte verstärkt werden. Manche von ihnen sind boshaft und gerissen. Wie der Jäger, so der Begleiter. \r\n===Treffsicherheit===\r\nDurch ihre enorme Treffsicherheit sind Jäger fähig, selbst die kleinsten und beweglichsten Ziele mit tödlicher Sicherheit zu treffen. Sie haben sowohl den besten Angriff als auch die beste Verteidigung zu ihrer Verfügung. Oftmals, bereiten sie ihren Gegner ein blutiges Willkommen, da sie ihren Angriff bereits erwarteten. Dabei hilft ihnen das ''Mal des Jägers'', in dem sie ihre Feinde zum Sterben markieren und einmal markiert gibt es kein Entkommen mehr. \r\n===Überleben===\r\nJäger sind Künstler darin, in der Wildnis zu überleben. Sie lernen dabei auch den Bau und das Aufstellen von verschiedenen Fallen und auch das Aufspüren von Lebewesen, wie z.B. Humanoiden, [[Riesen]], [[Wildtiere]]n und [[Untote]]n. \r\n==Rassenspezifische Ausrichtungen==\r\n* [[Blutelfen Jäger]]: [[Waldläufer]] \r\n* [[Draenei Jäger]]\r\n* [[Nachtelfen Jäger]]: [[Bogenschützin]], [[Jägerinnen]]\r\n* [[Orc Jäger]]: [[Wolfsreiter]] \r\n* [[Tauren Jäger]]\r\n* [[Troll Jäger]]: [[Axtwerfer]], [[Kopfjäger]]\r\n* [[Zwergen Jäger]]: [[Gebirgsjäger]], [[Greifenreiter]], [[Mörsertrupp]], [[Scharfschütze]] \r\n'''Quellen'''\r\n==Der Jäger - Eine Klasse im Wandel==\r\nIn diesem Beitrag soll der Jäger auf der Maximalstufe 70 vorgestellt werden. Die Sicht auf diese Klasse ist hierbei diejenige eines im wesentlichen auf Treffsicherheit ausgebildeten Jägers und natürlich die eines Schlachtzugleiters. Über andere Meinungen - vor allem bei einer anderen Skillung - würde ich mich natürlich freuen.\r\nEinst hatten die Jäger von [[Azeroth]] einen üblen Ruf. Zuviele schlechte Exemplare ihrer Art liefen durch diese Welt, unkundig ihrer wahren Fähigkeiten, schadensvernarrt, rüpelhaft, unkontrolliert. So galten die Jäger häufig als reine [[:Kategorie:Klasse|Schadensklasse]], waren sie von den Göttern doch auch so getrimmt worden. Hätte es nicht das Jägermal, den Einlullenden Schuss, den Naturwiderstand für Gruppen und die diversen Fallen gegeben - wahrscheinlich wäre diese [[:Kategorie:Klasse|Klasse]] in Gruppen und [[:Kategorie:Schlachtzug|Schlachtzügen]] längst aussortiert worden.\r\nHeute ist das anders. Der Jäger ist mehr als eine reine Schadensklasse mit einigen Bonusfähigkeiten geworden. Die meisten Jäger haben gelernt, dass Schaden nicht alles ist. - Auf Intelligenz und Führungskraft kommt es an! Die [[:Kategorie:Klasse|Klasse]] der Jäger musste einerseits also eine - umstrittene - Reduzierung des durchschnittlichen Schadens hinnehmen (vor allem im Vergleich mit [[Magier]]n), gewann allerdings zugleich auch einige Raffinessen hinzu:\r\nAuch Fernkampf-Jäger verfügen immernoch über ein sehr starkes Tier. Eine vollkommen ausgebildete Katze hat etwa einen Rüstungswert von 11.000. Ein Elite-Gegner kann damit einige Zeit aufgehalten werden. Bei ausreichender Heilung sogar bis zum Ende.\r\nJagdmeister sind neuerdings fähig, auch während eines Kampfes Fallen zu stellen. Ein Meister der Fallenkunst kann durch geschickte Zeiteinteilung auf diese Weise anfangs sogar zwei Gegner zugleich in dickes Eis packen oder frei laufende Gegner einfangen. Nicht nur in schwierigen Situationen, sondern auch im Schlachtfeld ist dies eine nützliche Eigenschaft. Die Sprengfalle hingegen macht einen mächtigen Flächen- und Langzeitschaden. Als besonderer Höhepunkt gilt die neue Schlangenfalle. Tappt ein Gegner dort hinein, erscheinen kleine Schlangen, die maximal fünffachen Langzeit-Naturschaden anrichten und fünfzig Prozent des Bewegungs- oder Zaubertempos verlangsamen.\r\nHat ein Jäger 46 Punkte in Treffsicherheit investiert, erhält er den \"Unterdrückenden Schuss\". Dieser hat eine Abklingzeit von 20 Sekunden und ist in der Lage, einen zaubernden Gegner für 3 Sekunden zum Schweigen zu bringen. Damit kann ein wachsamer Jäger harte Zauber des Gegners aufhalten, sondern jegliche Form von Beschwörung oder Heilung verhindern. Ergänzend steht dem Jäger hierfür noch der Streuschuss zur Verfügung (30 Sek. Abklingzeit).\r\nDie Krönung des Meisterjägers haben sich die Götter jedoch für den Schluss vorbehalten: Die Irreführung. Dieser Zauber kann vor dem Kampf oder im Kampf eingesetzt werden und ein ausgewähltes Ziel (innerhalb von 30 Sekunden) mit der Aggressionswirkung der nächsten drei Schüsse belegen. Zwei Beispiele:\r\na) Man hat einen Anführer oder eine komplizierte Gegnergruppe vor sich. Der Jäger markiert dann den [[Krieger]] mit dem Effekt Irreführung. Nun kann der Jäger eine gewaltige Erstschlagkombination ausführen (mit Glück insgesamt 5000-6000 Schaden), die Wirkung wird jedoch dem [[Krieger]] zugewiesen, wodurch der Gegner automatisch den [[Krieger]] anvisieren und angreifen wird.\r\nb) Ein Mitstreiter einer beliebigen Schadensklasse hat mal wieder im Kampf zu früh und zu heftig losgelegt oder der Gegner hat selbst aus Lust und Laune vom [[Krieger]] abgelassen und einen Mitstreiter, im schlimmsten Fall einen Heiler, angegriffen. Dann kann der Jäger auch im Kampf \"Irreführung\" einsetzen, den [[Krieger]] markieren und seine nächsten drei Schüsse auf den [[Krieger]] anrechnen lassen. Auf diese Weise wird die \"Aggro\" im Kampf reguliert und dem [[Krieger]] die Rückgewinnung der Aufmerksamkeit erleichtert.\r\nc) Die Technik, Irreführung in Kombination mit einer Salve einzusetzen, ist sohl unter Jagdmeistern als auch unter Göttern und Halbgöttern umstritten. Fest steht, dass eine Irreführung auch wirksam ist, wenn der Jäger zuerst eine Salve ausführt und erst dann die schweren Schüsse zum Einsatz bringt. Interessanterweise verliert der Jäger durch den ersten, als Salve ausgeführten Schuss keinen der drei irreführenden Schüsse. Ein derartiges Kampfmittel ist jedoch auf jeden Fall nur dann sinnvoll, wenn es sich um eine größere Gruppe leichterer Gegner handelt, da die Salve als Flächenschaden schnell die falschen Gegner in den Kampf miteinbeziehen könnte. \r\n==Fazit==\r\nDer Jäger der Version 7.0 ist definitiv mehr als ein reiner Schadenverursacher. Jäger, die sich auf das bloße Schießen beschränken, nutzen die neugewonnenen Fähigkeiten der [[:Kategorie:Klasse|Klasse]] nicht aus.\r\nEs scheint, als habe man das Potential des Jägers in der Führungs- und Kampfsteuerungsarbeit erkannt. Jäger haben den großen Vorteil, sich ohne größere Probleme auch in komplizierteren Kampfsituationen noch mitteilen zu können. Das erleichtert das Leiten der Gruppe ungemein. Mit Jägermal und Schlachtzugssymbolen, sowie Irreführung und Eisfalle sind Jäger die idealen Kampferöffner. Auch die Vorteile des Instant-Schusses sind beim Pullen in komplizierter Lage (Patrouillen) nicht zu verachten.\r\nIn der Kampfsituation selbst muss ein Jäger die Übersicht bewahren und das Kampfgeschehen steuern. Mit Eiskältefallen, Tier, Irreführung und Jägermal ausgerüstet, kann der Jäger dazu beitragen, das Chaos zu reduzieren, das beim Kampf einer Gruppe gegen 4-6 gleichzeitig heranstürmende Gegner entsteht. Darüber hinaus muss ein Jäger immer jene Gegner im Auge haben, die sich oder ihre Verbündeten heilen, weitere Gegner beschwören oder andere verheerende Zaubereffekte auslösen können. Mit den beiden zauberunterdrückenden Schüssen kann hier schnelle Abhilfe geschaffen werden (instant).\r\nDoch natürlich ist und bleibt ein Jäger immer auch für großen Schaden zuständig. Hinter den neuen Aufgaben und Möglichkeiten sollte der reine Schaden also nicht vergessen werden, sonst ist der Jäger trotz aller neuen Vorteile einer Gruppe keiner Hilfe. Schließlich ist die wichtigste Waffe des Jägers immer noch der \"Arkane Schuss\", dazu erschaffen, einem sterbenden Gegner den finalen Schlag zu verpassen.",},
			["Jägerinnen"] = { content = "#REDIRECT [[Nachtelfenjäger]]", redirect = "Nachtelfenjäger",},
			["Jünger des Lichts"] = { content = "#REDIRECT [[Menschenpriester]]", redirect = "Menschenpriester",},
			["K'aresh"] = { content = "K'aresh war die Heimatwelt der [[Astralen]], ehe [[Dimensius]] seine Leerenarmeen schickte und den Planeten vernichtete. K'aresh hatte zwei Sonnen, mehr ist über diese Welt nicht bekannt.",},
			["Kabale"] = { content = "Die Kabale ist eine Splittergruppe des [[Schattenrat]]s in den [[Wäldern von Terokkar]] und [[Auchindoun]]. Sie sind Mörder und Feiglinge und die Zurschaustellung von Mut wird sie einschüchtern. Die Befehle der Kabale, mit denen die Mitglieder untereinander Nachrichten austauschen, tragen ein dunkles Siegel. Auch wenn einem die Sprache bekannt vorkommt, scheint der Text verschlüsselt zu sein, denn dieser Text wurde in einer einfachen Form der Geheimschrift der Schatten geschrieben.",},
			["Kael'thas"] = { content = "#REDIRECT [[Kael'thas Sonnenwanderer]]", redirect = "Kael'thas Sonnenwanderer",},
			["Kael'thas Sonnenwanderer"] = { content = "Auch bekannt als: Kael (als vertraute Anrede)\r\n'''Prinz Kael'thas Sonnenwanderer''' ist der Sohn des verstorbenen Königs [[Anasterian Sonnenwanderer]] und damit ein Abkömmling des ersten [[Hochelfen]]königs, [[Dath'Remar Sonnenwanderer]]. Er wurde in ein Leben voller Reichtum und Privilegien hineingeboren.\r\n===Verlorene Liebesmüh === \r\nAls fähiger und mächtiger Zauberer nahm er früh einen hohen Rang bei den [[Kirin Tor]] ein. Seine magischen Studien führten ihn in die Violette Zitadelle, wo er [[Jaina Prachtmeer]] kennenlernte, die zu dieser Zeit gerade erst ihre Ausbildung begann. Er fühlte sich sofort zu der brillanten und hübschen jungen Frau hingezogen, wenn ihm auch der Altersunterschied Selbstzweifel und Schuldgefühle verursachte. Schließlich warb er um sie, doch mit wenig Erfolg. Sie widmete ihre ganze Kraft und Aufmerksamkeit ihrer Ausbildung. Als Gerüchte aufkamen, dass Jaina ihr Herz an Prinz [[Arthas]] Menethil verloren habe, war Kael'thas zutiefst niedergeschlagen. Zwar trennten sich nach einiger Zeit die Wege von Jaina und [[Arthas]], doch es war für Kael'thas nur allzu offensichtlich, dass sie immer noch Gefühle füreinander hegten. Zwischen Kael'thas und Jaina hingegen würde es nie mehr geben als eine ungelenke Freundschaft.\r\n===Der letzte Erbe der Sonnenwanderer-Dynastie === \r\nJahre später wurde [[Arthas]] ein [[Todesritter]] im Dienste des [[Lichkönig]]s und führte die [[Geißel]] nach [[Quel'Thalas]], wo er eine Schneise der Verwüstung schlug. Er entweihte den [[Sonnenbrunnen]], die Quelle der [[Magie]] der [[Hochelfen]], und entzog ihr auch den letzten Rest arkaner Energie. Die überlebenden [[Hochelfen]] wurden schnell krank und apathisch. König [[Anasterian Sonnenwanderer]] war im Kampf gegen die [[Untote]]n gefallen und nur wenige Widerstandkämpfer blieben zurück, um gegen die [[Geißel]] zu kämpfen. Prinz Kael'thas verfolgte seine magischen Studien in [[Dalaran]], als ihn die Nachricht der Invasion erreichte. Da sein Vater gestorben war, eilte der Prinz in seine Heimat und übernahm die Führung aller überlebenden [[Hochelfen]], die er finden konnte. Er erkannte, dass sein Volk vom [[Sonnenbrunnen]], der sie für Jahrtausende in arkaner [[Magie]] gebadet hatte, abhängig war.\r\n===Die Feindseligkeit seitens der [[Allianz]] === \r\nZu Ehren der gefallen Angehörigen beschloß Kael'thas sich selbst und die anderen überlebenden Elfen umzubenennen und fortan [[Sin'dorei]] oder [[Blutelfen]] zu heißen. Die [[Blutelfen]] schworen [[Arthas]] und der [[Geißel]] Rache. Trotz dieser gewagten Entschlossenheit litten Kael'thas und sein Volk stark unter dem Fehlen des [[Sonnenbrunnen]]s. Der Prinz führte eine Gruppe gesünderer Kämpfer an Front, wo sie hofften an der Seite der [[Allianz]] gegen die [[Geißel]] kämpfen zu können. Sie wurden jedoch nur mit Argwohn und offener Feindseligkeit begrüßt. Als Großmarschal Garithos Kael'thas und den [[Blutelfen]] befahl, in selbstmörderischen Aktionen gegen die Streitmächte der [[Geißel]] zu kämpfen, bot eine Gruppe [[Naga]], angeführt von Lady [[Vashj]], ihre Hilfe an und brachte somit die Wende im Kampf. Unglücklicherweise erfuhr die [[Allianz]] von Kael'thas Bund mit den [[Naga]] und verurteilte ihn und sein Volk als Verräter\r\n===Reise in die [[Scherbenwelt]] === \r\nGlücklicherweise konnte [[Vashj]] die [[Blutelfen]], die mittlerweise furchtbar unter ihrem Hunger nach [[Magie]] litten, rechtzeitig befreien. [[Vashj]] erklärte, dass auch die [[Naga]] abhängig von der Magie waren und [[Illidan]] den [[Blutelfen]] helfen könnte. Zu der Zeit litten die Elfen bereits stark und Kael'thas fühlte, dass er keine andere Wahl hatte und diese Chance wahrnehmen musste. Er und seine Anhänger folgten Vashj in die [[Scherbenwelt]]. Dort angekommen entdeckten sie, dass Illidan von Aufseherin [[Maiev Schattensang]] gefangen gehalten wurde. Vashj und Kael'thas befreiten Illidan und Kael'thas flehte Illidan nach einem Heilmittel für die [[Magie]]sucht der [[Blutelfen]] an. Illidan hatte allerdings einen anderen Vorschlag: Im Austausch für die Treue der [[Blutelfen]] würde er ihnen beibringen, [[Magie]] von anderen mächtigen Quellen zu ziehen, unter anderem von [[Dämonen]], um ihre schmerzhafte Sucht zu befriedigen.\r\nDies war ein Angebot, bei dem Kael'thas fühlte, dass er es annehmen sollte. Er war sich sicher, dass sein Volk sterben würde, wenn er kein Heilmittel oder eine neue Quelle der [[Magie]] finden würde. Kael'thas schwor [[Illidan]] seine Treue. Inzwischen haben die meisten [[Blutelfen]] der [[Scherbenwelt]] von dem Pakt mit Illidan erfahren. Nur wenige der Blutelfen in [[Azeroth]] wissen von Kael'thas'Bündnis mit Illidan und viele wären entsetzt, wenn sie es entdecken würden. Davon unbeeindruckt, was ihre azerothischen Brüder von ihnen denken würden, leben die Blutelfen der Scherbenwelt, um Illidan zu dienen. [[Großmagister Rommath]] wurde mit der Nachricht der Hoffnung zurück nach Azeroth zu den Blutelfen in [[Quel'Thalas]] geschickt. Er erzählte von dem glorreichen versprochenen Land und gab die Lehren Illidans weiter, Lehren, die Rommath Prinz Kael'thas zuschrieb, und begann somit die Auffassung, dass Kael'thas eines Tages zurückkehren und sein Volk ins Paradis führen würde.\r\n[[Großmagister Rommath]] blieb in [[Quel'Thalas]] und half es wieder aufzubauen und auf die Rückkehr des Prinzen vorzubereiten. Dank Rommath lernten die [[Blutelfen]] [[Azeroth]]s, wie die arkane [[Magie]] gewonnen werden konnte, um ihre Sucht zu nähren. Ihre Gesundheit kehrte zurück und sie lobpreisten den Prinzen in seiner Abwesenheit und widmeten sich ganz dem Studium. Rommath und der neue Orden elfischer [[Magier]] machten große Fortschritte, ihren Brüdern die Manipulation der arkanen Energien zu lehren. Schon sehr bald ragten die Türme [[Silbermond]]s in den Himmel, angetrieben von flüchtiger [[Magie]]. Die [[Blutelfen]] haben sogar einige Gebiete der [[Immersangwald|Immersangwälder]] wieder zurückgeholt. Von dem Versprechen auf die Rückkehr Kael'thas ermutigt, konzentriert sich das müde Volk darauf, seine Stärke zurück zu gewinnen und einen neuen Weg in eine ungewisse Zukunft zu finden.\r\n'''Neue Pläne'''\r\nKael'thas wurde nach seiner Niederlage in der [[Festung der Stürme]] gegen eine Gruppe tapferer Helden stark geschwächt und war dem Sterben nahe.Doch ein anderes Wesen mischte sich ein und heilte Kael'thas mit seiner schier unerschöpflichen Magie:Der Dämonenlord [[Kil'jaeden]].Kael'thas schwor [[Kil'jaeden]], ihn um jeden Preis nach [[Azeroth]] zu bringen, denn er glaubte, dass der Dämon den Magiehunger seines Volkes entgültig stillen könne. Er kam nach [[Azeroth]] zurück,raubte den [[Blutelfen]] den [[Naaru]] [[M'uru]], und zog sich zur [[Terrasse der Magister]] zurück.Dort bereitet er alles vor, um seinen neuen Meister in seine Welt zu rufen.Zu diesem Zweck will der Prinz den von [[Anveena Teague]] fast wieder aufgeladenen [[Sonnenbrunnen]] nutzen.Die [[Sha'tar]] haben die [[Offensive der Zerschmetterten Sonne]] ins Leben gerufen, um Kael'thas Pläne zu vereiteln.\r\n'''Veränderung'''\r\nKael'thas hat sich nicht nur innerlich verändert: Er ist blasser geworden, wirkt fast wie tot.Manche glauben, der exzessive Gebrauch von [[Magie]] hat Kael'thas zu einem [[Getriebenen]] gemacht ,andere glauben, es seien Nebenwirkungen der Berührung durch [[Teufelsenergie]].\r\n'''Quelle:''' wow-europe.com",},
			["Kakerlake"] = { content = "In Unterstadt verkauft euch Jeremiah Payson für 50 Silber das Haustier der Untoten, die Kakerlake. Jeremiah versteckt sich übrigens unter den Stufen, unterhalb der Bank im mittleren Bereich von Unterstadt.",},
			["Kaldorei"] = { content = "#REDIRECT [[Nachtelfen]]", redirect = "Nachtelfen",},
			["Kaldorei und der Brunnen der Ewigkeit"] = { content = "Zehntausend Jahre bevor die Menschen und die Orcs ihren Ersten Krieg führten, gab es auf der Welt Azeroth nur einen einzigen, von einem unendlichen, tosenden Meer umgebenen Kontinent. Diese Kalimdor genannte Landmasse war die Heimat einer ganzen Anzahl unterschiedlicher Völker und Kreaturen, die alle versuchten, sich gegen die wilden Elemente der erwachenden Welt zu behaupten. Im Herzen des dunklen Kontinents lag ein geheimnisvoller See glühender Energien. Der See, der später die Bezeichnung Brunnen der Ewigkeit tragen sollte, war das wahre Herz der magischen und natürlichen Macht dieser Welt. Der Brunnen bezog seine Energien aus dem unendlichen Großen Dunkel jenseits der Welt und diente als mystischer Quell – er sandte seine starken Energien über die ganze Welt aus und nährte so das Leben in all seinen wundersamen Gestalten.\r\nIm Laufe der Zeit bahnte sich ein primitiver Stamm nachtaktiver Humanoider vorsichtig einen Weg zum Ufer dieses hypnotischen verzauberten Sees. Die wilden nomadischen Humanoiden wurden von den seltsamen Energien des Brunnens angezogen und errichteten primitive Behausungen an seinen friedlichen Ufern. Mit der Zeit beeinflussten die kosmischen Energien des Brunnens den seltsamen Stamm und machten ihn stark, weise und so gut wie unsterblich. Der Stamm gab sich selbst den Namen Kaldorei, was in seiner Sprache so viel wie „Kinder der Sterne“ bedeutete. Um ihre aufstrebende Gesellschaft zu feiern, errichteten sie gewaltige Bauwerke und Tempel um den See herum.\r\nDie Kaldorei oder Nachtelfen, wie sie später genannt werden sollten, beteten die Mondgöttin Elune an und glaubten, dass sie tagsüber in den schimmernden Tiefen des Brunnens schliefe. Die frühen Priester und Seher der Nachtelfen studierten den Brunnen mit unstillbarer Neugier, von dem Wunsch getrieben, seine unbekannten Geheimnisse und Kräfte zu enträtseln. Als ihre Gemeinschaft wuchs, erforschten die Nachtelfen ganz Kalimdor und begegneten seinen zahllosen Lebensformen. Die einzigen Kreaturen, die sie beeindruckten, waren die uralten und mächtigen Drachen. Die riesigen, schlangengleichen Bestien lebten zwar häufig sehr zurückgezogen, trugen aber viel dazu bei, das bekannte Land vor potenziellen Gefahren zu beschützen. Die Nachtelfen glaubten, dass die Drachen sich selbst als Beschützer der Welt betrachteten, und sie waren sich einig, dass man sie und ihre Geheimnisse am besten in Ruhe ließ. Mit der Zeit führte die Neugier der Nachtelfen dazu, dass sie sich mit einer Reihe mächtiger Wesenheiten anfreundeten, nicht zuletzt mit Cenarius, einem Halbgott aus den unberührten Urwaldgebieten.\r\nDer großherzige Cenarius fand Gefallen am Forscherdrang der Nachtelfen und lehrte sie vieles über die natürliche Welt. Die abgeklärten Kaldorei entwickelteneine starke Verbundenheit mit den lebenden Wäldern von Kalimdor und lebten in einem harmonischen Gleichgewicht mit der Natur. Doch im Laufe scheinbar endloser Zeitalter expandierte die Zivilisation der Nachtelfen territorial und kulturell. Ihre Tempel, Straßen und Wohnorte erstreckten sich über den gesamten dunklen Kontinent. Azshara, die begabte und wunderschöne Königin der Nachtelfen, erbaute einen riesigen, Ehrfurcht gebietenden Palast am Ufer des Sees, in dessen juwelengeschmückten Sälen ihre bevorzugten Untertanen lebten. Diese Untertanen, die sie Quel’dorei oder „Hochwohlgeborene“ nannte, lasen ihr jeden Wunsch von den Augen ab und hielten sich für etwas Besseres als ihre weniger privilegierten Brüder. Königin Azshara wurde zwar von ihrem Volk geliebt, doch die Hochwohlgeborenen waren bei den eifersüchtigen Massen insgeheim verhasst.\r\nAzshara teilte die Neugier der Priester, was den Brunnen betraf, und befahl den gebildeten Hochwohlgeborenen, seine Geheimnisse zu enträtseln und herauszufinden, welchen Zweck er auf der Welt hatte. Die Hochwohlgeborenen machten sich an die Arbeit und studierten den Brunnen ohne Unterlass. Mit der Zeit fanden sie eine Möglichkeit, die kosmischen Energien des Brunnens zu manipulieren und zu kontrollieren. In zunehmend riskanteren Experimenten entdeckten die Hochwohlgeborenen, dass sie ihre neu erlangte Macht nutzen konnten, um ganz nach Gutdünken zu erschaffen oder zu zerstören. Die unglückseligen Hochwohlgeborenen waren auf eine primitive Magie gestoßen und fest entschlossen, es darin zur Meisterschaft zu bringen. Obschon sich alle darin einig waren, wie gefährlich Magie sein konnte, wenn man verantwortungslosen Umgang damit pflegte, praktizierten Azshara und ihre Hochwohlgeborenen ihre Zauberei immer tollkühner. Cenarius und viele der weisen Gelehrten der Nachtelfen mahnten unablässig, dass es nur zur Katastrophe führen konnte, mit den deutlich gefährlichen Künsten der Magie herumzuspielen. Doch Azshara und ihre Anhänger erforschten ihre aufblühenden Fähigkeiten unbekümmert weiter. Je größer ihre Macht wurde, desto deutlicher wurden Veränderungen an Azshara und den Hochwohlgeborenen. Die hochmütige und selbstverliebte Oberschicht wurde zunehmend geringschätziger und grausamer zu den anderen Nachtelfen. Ein finsterer, düsterer Schleier umwölkte Azsharas einst atemberaubende Schönheit. Sie zog sich von ihren Untertanen zurück und pflegte nur noch Umgang mit den Priestern der Hochwohlgeborenen, die ihr Vertrauen besaßen.\r\nEin junger, mutiger Gelehrter namens Furion Sturmgrimm, der die Wirkung des Brunnens ausgiebig studiert hatte, kam zu der Überzeugung, dass eine schreckliche Macht die Hochwohlgeborenen und seine geliebte Königin verdarb. Er konnte das Ausmaß des Bösen zwar nicht ahnen, das über sie kommen sollte, spürte aber, dass das Leben der Nachtelfen bald nie mehr so sein würde wie früher ...",},
			["Kalecgos"] = { content = "'''Kalecgos''' ist einer der wenigen noch verbliebenen Drachen des [[Blauer Drachenschwarm|Blauen Schwarms]]. Man findet ihn als [[NSC]] in der [[Terrasse der Magister]] und als Boss im 25-Mann-Schlachtzug des [[Sonnenbrunnenplateau]]s.\r\n==Hintergrund==\r\nSeit einiger Zeit wacht er schon über die sich regenden Kräfte des [[Sonnenbrunnen]]s, doch jetzt erkennt er, dass seine schreckliche Kraft das Ende der Welt bedeuten könnte, denn er wurde von [[Kil'jaeden]] versklavt. [[Kael'thas]] zu besiegen ist deshalb eine Aufgabe, die die ganz Aufmerksamkeit derer verdient, die ihm helfen wollen. Und wären diese Abenteurer noch imstande, eine Armee aufzustellen und sich in den Sonnenbrunnen zu begeben, dann fänden sie dort mehr als genug Unrecht vor, dessen man sich annehmen müßte.\r\nGemeinsam mit einem Freund ist Kalecgos zum [[Sonnenbrunnen]] gekommen, um eine junge Menschenfrau namens [[Anveena]] aus den Klauen des Legionsfürsten [[Kil'jaeden]] und seiner Diener zu befreien. Anveena ist keine bloße Sterbliche. Diejenigen, die ihre wahre Natur erkannt haben, schrecken vor nichts zurück, um sie in ihren Besitz zu bekommen. Eins wurde Kalecgos von ihr gerettet und nun möchte er sich dafür erkenntlich zeigen.\r\nWie man schon weiß, versucht [[Kael'thas]] den Legionslord Kil'jaeden aus den Tiefen des Sonnenbrunnens zu beschwören. Für das Heil dieser Welt - dies darf nicht geschehen! Und es ist Kalecgos' Aufgabe, sicherzustellen, dass es nicht geschieht.\r\n==Sunwell Trilogy==\r\nKalecgos ist der Hauptheld der der Comic-Trilogie \"Warcraft: The [[Sunwell Trilogy]]\", der zwischen der menschlichen und der Drachenform wechseln kann. Kalecgos sollte in \"Warcraft: The [[Sunwell Trilogy]]\" eine neue, große Machtquelle untersuchen, die sein Herr [[Malygos]] spürte. Leider hatte [[Dar'Khan Drathir]] ihn mit einem magischen Halsband in der Hand und der Drache, der sich in einen Menschen verwandelt hatte, konnte nicht einmal seine wahre Form annehmen. Am Ende halfen Kalecgos Freundin [[Tyrigosa]] und der Paladin [[Jorad Knüpp]] beim Endkampf gegen [[Dar'Khan Drathir]] und Untoten.",},
			["Kalimdor"] = { content = "Kalimdor war einst der Urkontinent auf [[Azeroth]], doch bei der Explosion des Brunnens der Ewigkeit wurden fast achtzig Prozent der Landmasse von Kalimdor zerstört. Zurück blieben eine Hand voll separater Kontinente, die von einem neuen, tosenden Meer umgeben waren. Einer dieser neuen Kontinente trägt Heute den Namen [[Östliche Königreiche]]. In der Mitte des neuen Meeres, wo sich einst der Brunnen der Ewigkeit befunden hatte, herrschte ein tobender Sturm wütender Gezeiten und chaotischer Energien. Der Wirbel der schrecklichen Narbe, die Mahlstrom genannt wurde, sollte nie wieder zum Stillstand kommen. Der Mahlstrom blieb eine ständige Erinnerung an die furchtbare Katastrophe ... und das utopische Zeitalter, das für immer dahin war.\r\nAuf dem heutigen Kalimdor leben heute noch die immer die [[Nachtelfen]]. Des weiteren [[Tauren]], [[Trolle]] und [[Orcs]].\r\nEinst, als die Welt noch jung und unbekümmert war, gab es nur einen riesigen Kontinent, den die Titanen Kalimdor nannten. In der Mitte dieses Kontinentes befand sich das wohl wundersamste und größte was die Magie der Titanen je erschaffen hatte: Der Brunnen der Ewigkeit. Alles was von seinem Wasser berührt wurde oder auch nur in der Nähe des Brunnens war, gedeihte und bekam ein unnatürlich langes Leben. Die Zeit verging, alte Völker starben und neue Völker entstanden. Unzählige Jahrhunderte vergingen und die Bauten der Nachtelfen, die in Frieden mit der Natur lebten, erstreckten sich über ganz Kalimdor. Doch [[Sargeras]], Lord der [[Brennende Legion|Brennenden Legion]], bemerkte die Quel'dorei und ihre unbekümmerte Anwendung ihrer mächtigen Magie und beschloss Kalimdor ein für alle Mal zu vernichten. Schnell gelang es Sargeras die Königin der [[Nachtelfen]], [[Azshara]], zu korrumpieren und sie dazu zu bringen ein Portal in ihre Welt für ihn zu öffnen. Doch kaum hatten die Nachtelfen das Portal in der Mitte des [[Brunnen der Ewigkeit]] geöffnet begannen die Krieger der Brennenden Legion in das Land einzufallen und verwüsteten alles und überall, wo sie hinkamen, hinterließen sie nur wüste Zerstörung. Die Nachtelfen jedoch, die diesem Treiben Einhalt gebieten wollten, schlossen sich mit dem Halbgott Cenarius zusammen und ebenfalls die mächtigen Drachen, Hüter des Brunnens, stellten sich gegen die Brennende Legion. Eine legendäre Schlacht entbrannte und während des Gegenschlags der [[Nachtelfen]] unter der Führung Furion Stormrages konnte [[Azshara]] gebrochen werden und das Portal, durch das die Krieger der Brennenden Legion gekommen waren, explodierte. Doch durch die Kraft der Explosion brach der [[Brunnen der Ewigkeit]] in sich zusammen und riss dabei Kalimdor auseinander. Zwar wurde [[Sargeras]] daran gehindert Kalimdor zu betreten und die [[Brennende Legion]] war vorerst besiegt, jedoch forderte dies einen hohen Preis: Fast ganz Kalimdor war verschwunden und der übrig gebliebene Teil des einst so mächtigen Kontinents spaltete sich in mehrere kleine Stücke. Die wenigen [[Nachtelfen]], die diese Schlacht überlebten, versammelten sich nunmehr auf einem dieser kleinen neuen Kontinente und nannten ihn seitdem: Kalimdor... \r\nDas Kalimdor von Heute ist das beste Beispiel für die riesige Vielfalt der Natur. Im Süden und Osten des Landes liegen die riesigen Steppenlandschaften und Einöden die [[Desolace]] und das [[Brachland]] gennant werden. In ihnen leben die im Einklang mit der Natur Lebenden [[Tauren]] und die mordenden und raubenden Truppen der [[Zentauren]] im ständigen Kampf miteinander. Im Nordwesten hingegen wachsen die monströsen Wälder des [[Eschental]]s welche die Heimat der restlichen [[Nachtelfen]] sind, die nun zurückgezogen und abgetrennt von der restlichen Welt in Frieden leben.",},
			["Kaltarra"] = { content = "Westlich der [[Boreanische Tundra|Boreanischen Tundra]], durch den Westrift vom Festland getrennt, liegt '''Kaltarra''', die Heimat des [[Blauer Drachenschwarm|blauen Drachenschwarms]]. Die einzige Landverbindung, über die Ihr die Insel erreichen könnt, ist die schmale und gefährliche Frostbridge, die stets von blauen [[Drachen]] bewacht wird. Kaltarra selbst besteht vollkommen aus blauem Eis und einzelne Spitzen ragen wie Fänge hoch in den Himmel. Das Zentrum der Insel ist der [[Nexus]]; ein labyrinthartiges Netz aus Höhlen, in dessen Zentrum [[Malygos]], der Aspekt der Magie selbst, lebt und forscht. Hierher zog sich der [[Blauer Drachenschwarm|Blaue Drachenschwarm]] zurück, nachdem [[Todesschwinge]] ihn fast vollständig ausgelöscht hatte. (Quelle: buffed.de)",},
			["Kammer der Luft"] = { content = "Die Kammer der Luft ist der Beratungsraum der [[Kirin Tor]], in dem sich die Höchsten der Hohen trafen. Diese Kammer wurde so genannt, weil sie wie ein Raum ohne Wände schien. Nur ein weiter, sich ständig verändernder Himmel mit Wolken, Licht und Dunkelheit, der an den Meister Zauberern vorbei raste, als ob die Zeit der Welt sich beschleunigt hätte. Nur der graue, Steinboden mit seinem glänzenden Diamant Symbol, welches die vier Elemente darstellte, gab der Szene irgendeine Festigkeit. Die Zauberer schienen mit den Bewegungen des Himmels zu schwanken, beinahe als ob auch sie nur Illusion wären. Die Nacht veränderte sich plötzlich in Tag. Ein Sturm begann zu wüten. Die Blitze und Regen fielen auf die Zauberer und berührten doch weder sie noch den Boden. Der Sturm verging mit dem Blinzeln eines Lidschlages und oben erschien einmal mehr eine lodernde Sonne. Nur ein mattes Licht ohne Quelle gab der Kammer eine Beleuchtung, nicht dass es viel zu sehen gab. \r\nAuf der dicken, Steimauer hing ein Wandteppich auf den ein kompliziertes, wissendes Auge aus Gold auf einem Feld aus violett genäht war. Unter dem Auge waren drei Dolche, ebenso Gold, mit der Spitze zur Erde. Die Fahne und die Symbole von [[Dalaran]] hatten während des Krieges hoch im Schutz der [[Allianz]] gestanden, sogar wenn nicht jedes Mitglied der [[Kirin Tor]] seine Pflichten mit allen Ehren erledigt hatte.",},
			["Kampfmagier"] = { content = "Der Begriff \"'''Kampfmagier'''\" ist eine Bezeichung, die bei den [[Kirin Tor]] gebräuchlich war für [[Magier]] der [[Menschen]] und [[Hochelfen]], die dieser Organisation angehörten. Diese [[Magier]] verstanden sich nicht nur im Umgang mit den arkanen Künsten, sondern waren im Gegensatz zu den üblichen [[Zauberer]]n auch fähig im Gebrauch des Schwertes.\r\n==Berühmte Kampfmagier==\r\n* [[Kampfmagier Dathric]]",},
			["Kampfmagier Dathric"] = { content = "'''Kampfmagier Dathric''' war ein menschlicher [[Magier]] der [[Kirin Tor]], der im [[Nethersturm]] in [[Kirin'Var]] wohnte. Er starb bei der Zerstörung [[Kirin'Var]]s, doch sein Geist wandelt noch heute durch die Ruinen und trägt das Stadtregister von Kirin'Var bei sich. \r\nAls [[Kampfmagier]] war für ihn sein Schwert eines der wertvollsten Dinge. Dathrics Klinge ist von außergewöhnlicher Qualität, fein geschmiedet und perfekt für einen Kampfmagier ausbalanciert. Auf dem Knauf der Waffe sind das Siegel der Kirin Tor und der Name \"Dathric\" eingraviert. Das Schwert fühlt sich an, als wäre es zwischen zwei Welten hin- und hergerissen. Dies ist der Gegenstand, der Kampfmagier Dathrics Geist an diese Welt bindet. Das Band zerbricht und befreit Dathrics Geist endgültig, wenn man die Waffe an seinen angestammten Platz in Dathrics Haus in der Zaubergasse zurückbringt.",},
			["Kampf um Hyjal"] = { content = "#REDIRECT [[Höhlen der Zeit: Kampf um Hyjal]]", redirect = "Höhlen der Zeit: Kampf um Hyjal",},
			["Kam Tiefenzorn"] = { content = "Kam Tiefenzorn steckt hinter dem eigentlichen Angriff auf den [[Thandolübergang]], der eine der beiden Brücken zerstörte, und hat dafür gesorgt, dass ein weiterer Behälter mit Sprengstoff hinter dem [[Thandolübergang]] im [[Arathihochland]] versteckt wurde. Wenn dieser Sprengstoff zur Brücke gelangt, wird die Hauptversorgungsverbindung der [[Zwerge]] in den Norden gänzlich gekapp. \r\nZur Zeit sitzt Kam Tiefenzorn jedoch im [[Das Verlies|Verließ]] in [[Sturmwind]].",},
			["Kannibalismus"] = { content = "Die meisten Trolle scheinen Kannibalismus zu praktizieren. Bei einigen Trollstämmen wurde der Kannibalismus definitiv bestätigt, einschließlich der [[Moosschinder]] und der [[Bleichborken]]. Außerdem sind auch alle momentan bekannten Stämme der [[Eistrolle]] Kannibalen. [[Sandtrolle]], [[Waldtrolle]] und [[Dschungeltrolle]] sind häufig, aber nicht immer kannibalistisch. Selbst von den geheimnisvollen [[Dunkeltrolle]]n glaubt man, dass sie Kannibalen sind. Es gibt aber auch beachtenswerte Ausnahmen. Die [[Zandalar]] und Bruchhauer nehmen zum Beispiel kein Trollfleisch zu sich. Die [[Dunkelspeere]] waren kannibalistisch bis sie sich der [[Horde]] anschlossen, dann gaben sie diesen Brauch offiziell auf.\r\nKannibalismus beinhaltet das Speisen von den Toten, entweder um einen würdigen Feind zu ehren und seine Kraft aufzunehmen, oder um Freunden, Verwandten, Lehrmeistern nach dem Tod eine Geste der Verbundenheit zu erweisen. Trollische Trauerfeiern stoßen wegen des teilweisen oder vollständigen Verzehrs des Verstorbenen bei anderen Völkern häufig auf Unverständnis und Ablehnung, da die Geste des Verspeisens falsch interpretiert wird.\r\nTrollischer Kannibalismus wurde durch [[Hakkar]] pervertiert - dem ursprünglichen Kannibalismus ist nicht zu eigen, Freunde, Ehegatten oder Kinder gegen ihren Willen zu opfern und zu verspeisen. Der Kannibalismus zeigt von Stamm zu Stamm unterschiedliche Ausprägungen und hat etwa bei einigen degenerierten Trollstämmen des Hinterlandes maßlose Züge erreicht, ohne dass hier eine Beeinflussung durch Hakkar vorliegt.",},
			["Kapelle der scharlachroten Flamme"] = { content = "Die '''Kapelle der scharlachroten Flamme''' befindet sich in [[Neu Avalon]], innerhalb der [[Scharlachroten Enklave]] in den [[Östlichen Pestländern]]. Die [[Todesritter]] der Geißel aus [[Acherus]] kamen unter Führung von [[Ritterkommandant Seuchenfaust]] hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Sie hatten nicht erwartet, was sie dort vorfanden, denn es scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der [[Argentumdämmerung]]. Die meisten von ihnen waren schon tot, als die Todesritter ankamen, doch ein paar atmeten noch. Ritterkommandant Seuchenfaust wollte schon hineingehen und den Rest von ihnen hinrichten, doch er dachte, dass lieber ein anderer vielversprechender Todesritter die Ehre haben sollte. Die Kapelle der scharlachroten Flamme wird sehr bald schon nur noch ein Haufen Asche sein. \r\n==Personen==\r\n* [[Ritterkommandant Seuchenfaust]]",},
			["Kapelle des Hoffnungsvollen Lichts"] = { content = "Die '''Kapelle des Hoffnungsvollen Lichts''' ist ein neutraler Ort in den [[Östlichen Pestländern]]. Sie befindet sich ganz im Osten und ihre Wachen gehören der [[Argentumdämmerung]] an. Von hier aus führen sowohl die Horde als auch die Allianz den Kampf gegen die [[Geißel]]. In der Vergangenheit haben die Kämpfer hier die Interessen der [[Argentumdämmerung]] nach bestem Gewissen und Können gewahrt und in einer Zeit der größten Not, ertönt wieder einmal der Ruf zu den Waffen. Sollte man sie unterstützen wollen, meldet man sich bei dem Bewahrer der Schriften an der Kapelle. Wer bei der [[Argentumdämmerung]] einen ehrfürchtigen Ruf genießt, erhält bei Käufen garantiert den besten Preisnachlass.\r\n==Personen==\r\nSeit die Nekropole von Naxxramas auftauchte, fanden sich verschiedene Gruppierungen an der Kapelle ein, um gemeinsam gegen die Bedrohung der Geißel zu kämpfen. Dazu gehören neben der Argentumdämmerung auch die [[Bruderschaft des Lichts]], der [[Scharlachrote Kreuzzug]] und der [[Zirkel des Cenarius]].\r\n===Argentumdämmerung===\r\n* [[Fürst Nicholas Zverenhoff]]\r\n* [[Leonidas Bartholomäus der Geachtete]]\r\n* [[Lord Maxwell Tyrosus]]\r\n* '''Betina Moppelzink''' - Die [[Apotheker]] der Verlassenen sind nicht die einzigen Wesen auf dieser Welt, die in den Wissenschaften bewandert sind. Betina erforscht die Seuche schon seit Jahren. Sie ist in Wissenschaft und Alchimie sehr bewandert und hat eine Waffe hergestellt, die sie gegen die Geißel einsetzen können.\r\n* '''Carlin Rotpfad''' - Carlin Rotpfad sucht Befreiung für die Geister von [[Darroheim]]. Die Zerstörung ihrer Formen wird ihre Seelen befreien. Er sammelt auch die Relikte der Helden von Darroheim (Davils Buchband und Rotpfads Schild), denn Verhängnis und Tragik umgeben sie. Sein Herz sehnt sich nach seinem Dorf, sehnt sich danach, es vor seinem Schicksal zu bewahren. [[Chromie]] behauptet, es wäre möglich.\r\n* '''Einsatzkommandant Metz''' - Einsatzkommandant Metz wird auch der \"Schleifer\" genannt. Handwerker aus der ganzen Welt bewerben sich um Aufträge an der Front. Wenn man eine Arbeitsanweisung will, muss man ihm zeigen, dass man gewillt ist, für die Sache zu bluten.\r\n* '''Smokey LaRue''' - Smokey LaRue wurde von den Leuten der Argentumdämmerung beauftragt, ein paar Abrissarbeiten im [[Pestwald]] für sie durchzuführen. Smokeys Mama hat keinen Trottel großgezogen. Wenn bares Gold auf den Tisch gelegt wird, ist Smokey stets zu Diensten. Doch er verlangt viel.\r\n* '''Verwalter Alen''' - Verwalter Alen hat einen Partner namens [[Egan]], der wunderbare Arbeit mit Geistern und Seelen geleistet hat.\r\n===Bruderschaft des Lichts===\r\n* [[Erzmagierin Angela Dosantos]]\r\n* '''Korfax''' - Korfax ist der Held des Lichts. Er braucht [[Dunkeleisen]]fragmente und ist bereit zu zahlen, um an so viele Stücke wie möglich zu kommen. Er benötigt die Fragmente für das Zusammensetzen der Schreckenspanzer für die Helden.\r\n* '''Wache Didier''' - Wache Didier hätte es ohne die Hilfe von Abenteurern mit seiner Karawane niemals geschafft. Die Geißelsoldaten, die ihnen im Unterholz aufgelauert haben, wollten wohl nicht, dass sie in einem Stück eintreffen. Jetzt werden sie erst einmal warten, bis [[Feldmarschall Kammerer]] eintrifft. Er wird die Verfügung für freies Geleit unterzeichnen, die man dann zu [[Einsatzkommandant Metz]] bringen kann.\r\n===Scharlachroter Kreuzzug===\r\n* '''Jäger Leopold''' - Jäger Leopold hat ein kleines Problem. Er fertigt Gruftpirscherrüstungen für diejenigen an, die dämlich genug sind, um sich nach [[Naxxramas]] zu wagen. Während sie ihn mit den wichtigsten Bestandteilen für die Rüstung versorgen, gehen ihm dennoch ständig die Teile von [[Gruftscheusal]]en aus.\r\n* '''Mataus der Zornwirker''' - Mataus der Zornwirker kennt die Herstellung des [[Eiswächter]]s und des [[Schattenwächter]]s.\r\n* '''Scharlachroter Kommandant Marjhan''' - Marjhan wurde als Bote des Scharlachroten Kreuzzuges zur Kapelle des Hoffnungsvollen Lichts entsandt. Als eine Art Botschafter, wenn man so will. Sie denkt nicht, dass sie die Armeen von Kel'Thuzad besiegen können, vereint oder nicht, aber sie sollten sie lange genug aufhalten können, bis irgendein Wunder geschieht. Was Marjhan selbst betrifft, sie glaubt in der Schlacht zu sterben.\r\n===Zirkel des Cenarius===\r\n* '''Rayne''' - Rayne fertigt für die mutigen Helden, die sich nach [[Naxxramas]] begeben, eine spezielle Rüstung an - die [[Gewandung des Traumwandlers]].",},
			["Kappe des scharlachroten Wissenden"] = { content = "Die '''Kappe des scharlachroten Wissenden''' ist neben der [[Brustplatte des Blutdurstes]] und den [[Gamaschen von Arcana]] eines der Glanzstücke aus Malyfous’ Katalog. Eine feinere Kappe wird man niemals sehen. Aus dem makellosen Balg der Bestie wird der Experte [[Malyfous Düsterhammer]] in der [[Ewige Warte|Ewigen Warte]] von [[Winterquell]] den phänomenalsten Hut schaffen, den ein Gaukler jemals zu tragen träumte. Diese epische Stoffkappe können Priester, Schamane, Magier, Hexenmeister und Druiden tragen. \r\n==Zutaten==\r\nUm die Kappe des scharlachroten Wissenden herzustellen, müssen die folgenden Dinge zu [[Malyfous Düsterhammer]] in der [[Ewige Warte|Ewigen Warte]] gebracht werden: \r\nDer zukünftige Träger muss außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.\r\n==Links==\r\n* [Kappe des scharlachroten Wissenden] bei",},
			["Karazhan"] = { content = "'''Karazhan''' ist eine 10-Mann Instanz im [[Gebirgspass der Totenwinde]].\r\n==Allgemeines==\r\nEinst beherbergte Karazhan eine der mächtigsten Gestalten der Geschichte [[Azeroth]]s: [[Medivh]], den Zauberer. In des Turmes weitläufigen Hallen und verwinkelten Gängen beschwor Medivh Wesen von jenseits des bekannten Universums und erforschte verbotene Magie, an die sich außer ihm niemand heranwagte. Inzwischen ist Karazhan verlassen und verfallen, und in der Abwesenheit des Meisters sind die unsagbaren Monstrositäten inzwischen außer Kontrolle geraten und reißen jeden in Stücke, der töricht genug ist, Karazhan zu betreten. \r\nIn den letzten Jahren sind vermehrt Adlige aus [[Dunkelhain]] in den [[Gebirgspass der Totenwinde]] ausgezogen, um die Fäule, die über dem Land liegt, zu untersuchen. Sie haben den dunklen Turm betreten - ihn aber nie wieder verlassen. Es wird sogar behauptet, dass die Geister der Adligen jetzt in den Mauern Karazhans umhergehen, dazu verflucht, auf ewig in dem verfallenen Opernhaus des Turms zu feiern. Doch es gibt noch weitaus gefährlichere Geister in Medivhs makabrem Forschungszimmer, da hier dämonische Geschöpfe von dem verstörten Zauberer beschworen wurden. Trotz der ungezählten Schrecken wagen sich noch immer Abenteurer nach Karazhan - angelockt durch Gerüchte über entsetzliche Geheimnisse, die sich in den modernden Bibliotheken des alten Gemäuers verbergen. Angeblich enthalten die magischen Hallen Zauberbücher, die so mächtig sind, wie einst Medivh selbst es war. \r\n==Geschichte von Karazhan==\r\nDer Turm Karazhan war ein beeindruckendes Bauwerk, das der [[Orden von Tirisfal]] vor langer Zeit in den [[Rotkammgebirge]] errichten ließ. Man hatte diesen abgeschiedenen Ort ausgewählt, weil dort die Kräfte der Magie außergewöhnlich stark waren. Die Hüter des Ordens wachten von hier aus über die Welt [[Azeroth]], um sie vor den geheimnisvollen Mächten des Großen Dunklen Jenseits zu schützen.\r\n===Der gefallene Wächter===\r\nMedivh - der letzte Hüter - wurde jedoch böswillig und gesinnungslos, da er durch den Geist des Dämonenlords [[Sargeras]] beeinflusst wurde. In den versteckten Räumen unterhalb des Turms ging er seinen verbotenen Experimenten mit den Mächten der Magie nach. Als Medivh eine Pforte zwischen dem Königreich [[Azeroth]] und der roten Welt [[Draenor]] öffnete, wurde er von der einstigen Hüterin und zugleich seiner Mutter [[Aegwyn]] zur Rede gestellt. Sie versuchte Medivh von seinem dunklen Vorhaben abzubringen und kämpfte schließlich in Karazhan gegen ihn. Aegwyn hatte aber bereits ihr Wissen und ihre Macht auf Medivh übertragen und konnte so von ihm mühelos besiegt und aus Azeroth verbannt werden.\r\n===Die Visionen Karazhans===\r\nDas gewaltige Wissen des Ordens wurde in der umfangreichen Bibliothek des Turms gesammelt und bewahrt. Medivhs Zauberlehrling [[Khadgar]] hatte die Aufgabe, die Aufzeichnungen des Ordens zu katalogisieren und zu verwalten. Er studierte die geheimen Schriften und fand bald einen Weg, die Visionen Karazhans gezielt herbeizurufen. Solche Schattenbilder der Zukunft oder Vergangenheit erschienen fortlaufend, weil an diesem magischen Ort die Grenze zwischen den Dimensionen nur sehr dünn war.\r\n===Medivhs Tod und Rückkehr===\r\nUm sich größeres Wissen über die Menschen anzueignen, schickte der orkische [[Hexenmeister]] [[Gul'dan]], der einen Pakt mit Medivh geschlossen hatte, seine Spionin [[Garona]] als Botschafterin nach Karazhan. Als Khadgar und Garona durch eine Vision von Medivhs wahren Machenschaften erfuhren, flüchteten sie aus dem mystischen Turm. Sie kehrten zusammen mit Sir Lothar und einigen Soldaten nach Karazhan zurück, um Medivh zu töten und seinem Treiben ein Ende zu setzen. Die Kellergewölbe des Turms wurden von [[Dämonen]] bewacht, die Medivh beschworen hatte, um die mächtigsten Magier des [[Orden von Tirisfal|Ordens von Tirisfal]] töten zu lassen. Trotz allem gelang es Khadgar und Sir Lothar den gefallenen Hüter zu vernichten. Nachdem Medivh von den Toten zurückgekehrt war, stellte er seine Kräfte wieder her, indem er die magischen Energien Karazhans auf sich selbst übertrug.\r\n==Bosse==\r\n* [[Arans Schemen]]\r\n* [[Attumen der Jäger]]\r\n* [[Der Kurator]]\r\n* [[Hyakiss der Lauerer]]\r\n* [[Moroes]]\r\n* [[Nethergroll]]\r\n* [[Prinz Malchezaar]]\r\n* [[Rokad der Verheerer]]\r\n* [[Schach-Event]]\r\n* [[Schrecken der Nacht]]\r\n* [[Shadikith der Gleiter]]\r\n* [[Tendris Mirkblut]] (Saisonal)\r\n* [[Terestian Siechhuf]]\r\n* Theater: [[Der große böse Wolf]]\r\n* Theater: [[Der Zauberer von Oz]] / [[Die böse Hexe]]\r\n* Theater: [[Romulo und Julianne]]\r\n* [[Tugendhafte Maid]]",},
			["Kargath"] = { content = "Der [[Horde]]nstützpunkt '''Kargath''' im [[Ödland]] ist das Hauptquartier des [[Kargather Expeditions Korps]] (KEK) und wurde nach [[Kriegshäuptling Kargath Messerfaust]] benannt. Dieser Ort entbehrt nicht eines gewissen rauen Charmes, aber es mangelt an Annehmlichkeiten. \r\n[[Neeka Blutnarbe]], die Hauptspäherin von Kargath, schreibt in ihrem Bericht, dass wer auch immer den Befehl gegeben hat, den Hordenstützpunkt von Kargath im [[Ödland]] zu stationieren, sich ein Kompliment verdient hat. Es ist der ideale Ort zum Ausbilden der Truppen. Das Wetter ist rau, die Wildnis heimtückisch, die Eingeborenen kriegerisch und der gesamte Ort von der Außenwelt abgeschnitten. Von dort werden nur die besten Krieger und Späher kommen. Unnötig zu sagen, dass die Belegschaft der Garnison von Kargath froh ist über ihren Auftrag. Hier bleiben sie hart, denn wenn sie verweichlichen, sterben sie. Anders würden sie es auch gar nicht wollen. \r\nDas Expeditionskorps stieß bereits bei den ersten Streifzügen in der [[Sengende Schlucht|Sengenden Schlucht]] auf Maschinen. Weitere Nachforschungen ergaben, dass sie aus der [[Brennende Steppe|Brennenden Steppe]], eventuell auch aus den [[Schwarzfelstiefen]], stammen.\r\n==Personen==\r\n* [[Kriegsherr Bluthauer]]\r\n'''Sonstige'''\r\n* '''Berater Sarophas''' ist ein Blutelf. Die [[Dunkeleisenzwerge]] haben ihn überfallen und sind dann in der [[Festung Angor]] verschwunden. Dabei haben sie seinen Beutel und sein Rapier mitgenommen.\r\n* '''Donnerherz''' erforscht die Disharmonien der Flamme und des Feuers im [[Schwarzfels]]. Im Zuge dessen möchte er, dass man [[Übermeister Pyron]], sowie [[Lord Incendius]] in den [[Schwarzfelstiefen]] tötet.\r\n* '''Galamav der Schütze''' gehört zum Expeditionskorps von Kargath und sucht [[Kommandant Gor'shak]] in den [[Schwarzfelstiefen]]. Falls er noch am Leben sein sollte, dort unten in den Tiefen, dann muss man ihn finden.\r\n* '''Gargal''' wurde von einem Pfeil völlig überrascht. Der Pfeil traf ihn genau oben an seinem Kopf. Er war vorher schon kein Genie, aber jetzt... Als die anderen den Pfeil herauszogen, sahen sie, dass eine zusammengerollte Notiz an seinem Schaft befestigt war. Die Notiz war ein primitiv gezeichnetes Bild eines [[Orcs]] hinter Gittern mit der Unterschrift von [[Kommandant Gor'shak]].\r\n* '''Gorn''' sorgt sich um die Zerbrochenen Allianzen mit dem [[Schwarzer Drachenschwarm|Schwarzen Drachenschwarm]]. Durch die Allianz der [[Horde]] mit dem Großdrachen [[Todesschwinge]] während des [[Der Zweite Krieg|zweiten Krieges]] weiß man, dass zwei ihrer Offiziere, [[Schattenbringer]] und [[Hematus]], in der [[Lethlorklamm]] weit im Osten eingesperrt sind. Die Horde muss ihre verderbten Verbündeten von damals zum Stillschweigen bringen, um die Ehre der [[Horde]] wiederherzustellen. Deshalb soll man nun [[Tho'grun]] töten und Gorn das Zeichen der Erde bringen. Dieses Zeichen soll danach benutzt werden, um die Säulen aus Diamant, Opal und Amethyst zu aktivieren und die Runensteine zu holen. Dann legt man die Runensteine auf das Siegel der Erde, um Schattenbringer und [[Hematus]] zu befreien.\r\n* '''Großmeister Lexlort''' ist der Leiter der Aufklärungseinheit des KEK - des Expeditionskorps von Kargath und auf der Suche nach seiner in der [[LBRS|Unteren Schwarzfelsspitze]] verschollenen [[Agentin Bijou]]. \r\n* '''Jarkal Mossblut''' ist ein angesehener Alchimist und auf Reagenziensuche im Ödland. Dafür möchte er unter anderen seine leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland füllen. Die dafür benötigte Schließkassette enthält drei leere thaumaturgische Gefäße; die mit einer Aura der Einstimmung erfüllt sind, die einem versengten Behütergroßdrachen das Blut aussaugt. Doch wenn man sie gegen die Bestien benutzt, wird sie höchst erbost reagieren. Er kann ebenso das Tagebuch des toten Paladins aus [[Uldaman]] übersetzen, doch dafür möchte er, dass man ihm die Halskette leiht, ehe man sie [[Dran Droffers]] in [[Orgrimmar]] bringt. [[Dran Droffers|Droffers]] sei nicht schlau genug, die Magie der Halskette wiederherzustellen, aber er kann es. Er muss nur die Halskette studieren, damit er lernt, wie er selbst solche Ketten herstellen kann. Um sie wiederherzustellen, braucht er alle drei ihrer ehemaligen Edelsteine sowie eine Kraftquelle. Jarkal glaubt, dass sich so eine Kraftquelle vielleicht im stärksten [[Konstrukt]] in [[Uldaman]] findet. Er wird die Edelsteine zur Verfügung stellen, die man für die Halskette benötigt, wenn die Kraftquelle einwandfrei funktioniert. Danach wirkt er einen Zauber, der die Menschensprache schnell in etwas übersetzt, das man das Tagebuch verstehen kann. Er ist ein Troll, der sein Wort hält - Man kann jeden in der Horde auf Jarkal Moosblut ansprechen.\r\n* '''Neeka Blutnarbe''' - Neeka Blutnarbe ist die Oberste Späherin des Kargath-Außenpostens und schrieb einen Bericht für Helgrum den Hurtigen in [[Steinard]]. \r\n* '''[[Schattenmagier]]in Vivian Lagrave''' ist eine [[Untote]]. Sie lebt im [[Ödland]], im orcischen Außenposten Kargath, wo sie dem Gerücht nachgeht, nach dem die [[Dunkeleisenzwerge]] der [[Schwarzfelstiefen]] angeblich ein bestimmtes Gebräu herstellen. Es geht das Gerücht umher, dass der Dunkeleisenzwerg [[Hurley Pestatem]] ein Rezept zum Brauen von Bier gestohlen hat. Dieses Bier, das Donnerbräu Lagerbier, soll angeblich jeden, der es trinkt, mit großer Kraft und Mut erfüllen. Das ist natürlich nicht ihr einziger Begehr. Sie hat ebenso einen Plan entwickelt, mithilfe der Essenz der Elemente die [[Monstrositäten]] zu verbessern und aufgrund ihrer Studien ist sie davon überzeugt, dass auch eine alte Niederschrift auf der [[Schwarzfelsspitze]], die Dunkelsteinschrifttafel, für ihre Forschung nützlich sein könnte.\r\n* '''Thal'trak Ehrenhauer''' ist der Mann von [[Sha'ni Ehrenhauer]] und sucht seine Frau, die in der [[Brennende Steppe|Brennenden Steppe]] am [[Schreckensfels]] verschollen ist.\r\n* '''Theodora Mulvadania''' gehört zum Expeditionskorps von Kargath und interessiert sich für die gerissenen Elementarsplitter der [[Golems]] und [[Elementare]] in der Gegend, um den Aufstieg der Maschinen zu erforschen.\r\n'''Quellen'''",},
			["Kargath Messerfaust"] = { content = "Kriegshäuptling '''Kargath Messerfaust''' ist der Häuptling der [[Orcs der Zerschmetterten Hand]] und [[Kriegshäuptling]] der [[Teufelshorde]]. Man findet ihn am Ende der [[Zerschmetterte Hallen|Zerschmetterten Hallen]] in der [[Höllenfeuerzitadelle]]. In diesen Gemäuern werden drei Leute von diesem erbarmungslosen Höllenorc gefangen gehalten und er hat vor, sie als Zeichen seiner Männlichkeit und Stärke hinzurichten. \r\nKargath, der eine messerscharfe Klinge anstelle seiner abgeschlagenen linken Hand trägt, ist jederzeit bereit, sich in ein wildes Gefecht zu stürzen. Seine umbarmherzige Taktik und Zielstrebigkeit brachten ihm die Befehlsgewalt über den allseits gefürchteten [[Klan der Zerschmetterten Hand]] ein. Ebenso wie Höllschrei wartet Kargath nur auf eine Gelegenheit, seinen Clan auf die ahnungslosen Menschen loszulassen, um unter ihnen ein Blutbad anzurichten. Er galt als verstorben während der Zerstörung seiner eigenen Welt, Draenor und kämpfte unter dem Willen [[Ner'zhul]]s, welcher damals noch ein Orc Schamane war.",},
			["Karna Wirrbart"] = { content = "Die Zwergin [[Karna Wirrbart]] bei [[Marschalls Zuflucht]] im [[Krater von Un'Goro]]. Sie sucht nach [[A-Me 01]], ihrer bislang besten Erfindung. Um näher an die [[Affen]] des Kraters heranzukommen, hat sie eine mechanische Äffin geschaffen, die sich unbemerkt unter sie mischen kann - A-Me 01. Sie hat Wahrsagesteine als Augen, so konnte Karna alles sehen, was auch A-Me sah. Den [[Fungusfels]] hat sie wohlbehalten erreicht, doch dort hat Karna dann den Kontakt zu man verloren. Das Letzte, was sie sah, war eines der Alphamännchen, das auf sie zugestürmt kam, um sie zu begrüßen.",},
			["Karynaku"] = { content = "Der Netherdrache '''Karynaku''' ist [[Neltheraku]]s Weibchen. Sie befindet sich im [[Schattenmondtal]], doch Ketten berauben sie ihrer Macht. Der einzige Ausweg ist, den Schlüssel von [[Zuluhed]] zu beschaffen und sie loszuketten.",},
			["Kastalan"] = { content = "==Quartier:==\r\nWohnte ehemals im Gasthaus in Menethil, doch verließ dieses nach Streitereien mit den Exequien. Wohnt jetzt wohnhaft in Mühlenbern, dem Heimatdorf von Pantheons Vermächtnis. Hält sich meistens in Sturmwind in den Tavernen auf, wenn er nicht gerade für Magiekunde lernt oder in den Ländereien von Azeroth trainiert \r\n==Beruf/Aufgabe: == \r\nKastalan ist Lehrling von Amut Ironhand, der ihn in der Kunst der Magie unterrichtet. Er ist ein guter Schüler, der schnell lernt und die Magie gut zu benutzen weiss. Allerdings hat er noch starke Rachegefühle und einen Hang zur dunklen Magie auf Grund seiner allen unbekannten Vergangenheit. Allerdings benutzt er seine Magie anscheinend im Augenblick nur für gute Zwecke. \r\n==Grobe Beschreibung/Historie: == \r\nKastalan Schattenherz trägt eine Blau,schwarz,gold Verzierte Robe, golden,schwarze Schulterstücke und je nach Anlass abundzu eine blaue Kaputze. Er trägt stets ein Schwert und eine Rote Rose bei sich. Die Rote Rose, war das letzte Geschenk seines Vaters, die ihn stets an sein Versprechen erinnern soll und die er benötigt um seine Magie unter Kontrolle zu haben. Abundzu sieht man Kastalan jedoch auch in einer Schwarzen Robe und mit schwarzer Kaputze...warum weiss niemand. Über seine Vergangenheit ist nicht allzuviel bekannt. \r\nSeine Eltern wurden von der Horde getötet und er wuchs danach bei einer Bauernfamilie in Westfall auf. Später spürte er etwas in sich, es war die Magie. Er wollte sich fortbilden und lernen sie zu kontrollieren und zu verwenden, also machte er sich auf den Weg nach Sturmwind. Dort lernte er Lillyane kennen, die ihn mitnahm nach Menethil, wo er seine ersten Schritte in die Welt der Magie tat. Seine Ansichten und Ziele haben sich seitdem geändert, sein Mentor aber nicht. \r\nKastalan Schattenherz ist eine sarkastische aber unergründliche Person, mit viel Humor und hat stets einen lockeren Spruch auf Lager. Er wird nie laut und flucht auch nicht, allerdings kann er sehr ernst reden und lässt seine Mitmenschen spüren, wenn sie ihn besser nicht weiter stören sollten, verliert dabei aber niemals seine Höflichkeit und den Respekt gegenüber anderen. Abundzu hat man den Eindruck er lebt in einer Art Traumwelt.",},
			["Kastalans Private Magieschule"] = { content = "==Beschreibung==\r\n''Ein elegant gekleideter Magister, mittleren Alters, schreitet leichten Schrittes auf dem Marktplatz von Sturmwind umher und verteilt Steckbriefe an junge Magiekundige und nichtmagische Bürger.''\r\n\"Kastalans kleines Institut für Magiekunde - Anfänger bis Fortgeschrittene\"\r\nGrüße magiekundiges und nicht magiekundiges Volk Azeroths,\r\nIhr habt eure magischen Talente entdeckt, wisst aber nicht wie Ihr sie ausbilden oder anwenden sollt?\r\nOder aber Ihr kennt Magie nur als böses und gefärhliches Element?\r\nDann möchte ich euch helfen eure Kräfte auszubilden oder aber euch lehren, dass Magie nicht zwangsläufig gefährlich oder schlecht ist, sondern das die Magie etwas wunderbares und schönes sein kann, WENN man sie richtig anwendet.\r\nIhr habt vielleicht Interesse bekommen?\r\nDann schaut vorbei bei Kastalans Institut für Magiekunde, im Magierviertel im Keller der Taverne \"Zum geschlachteten Lamm\"\r\nIch würde mich über zahlreiches Erscheinen freuen.\r\nMagische und aufrichtige Grüße,\r\nKastalan Schattenherz\r\n----\r\n==[[OOC]] 1:==\r\nErstmal kurz vorweg, das ist mein erstes \"RP-Projekt\", welches ich plane und durchführen möchte. Ich hatte die Idee, weil ich finde, wie auch viele andere feststellen vielleicht, dass es außer ein bisschen Getratsche nichtmehr soviel abwechslung gibt. Nun, vielleicht wird es euch auch nicht gefallen aber ich probiere es einfach mal. Seid bitte nicht zu hart.\r\n==[[OOC]] 2:==\r\n \r\nIch weiss, dass ist sicher noch ausarbeitungsbedürftig, aber niemand ist als der perfekte RPler geboren worden und ich würde mich freuen wenn ein paar Leute mich dabei unterstützen würden, den RP Tag wieder wenigstens etwas abwechslungsreicher zu gestalten. Bei Interesse bitte ingame melden und natürlich auch hier im Forum.\r\nIn game könnt ihr mir einen Brief schicken oder mich einfach anwhispern.\r\nMit freundlichen Grüßen,\r\nArne",},
			["Katakomben der Amani"] = { content = "Die Katakomben der Amani liegen im Sonnenhügel, direkt Richtung Osten von [[Tristessa]] in den [[Geisterlande]]n. Der einfachste Weg hinein an liegt der Nordwand des Hügels. \r\nDie Körper der [[Trolle]], die in diesen Katakomben innerhalb des Sonnenhügels begraben wurden, sind wieder von den Toten auferstanden. Manche dieser Trollmumien, sowie ihre lebendigen Artgenossen, tragen Juju bei sich und ein reicher Händler erzählte etwas über einen Ring von 'immenser archäologischer Bedeutung', der in einer der zahllosen Grabtruhen in den [[Amani]]katakomben eingeschlossen ist. Wenn er nicht über den Ring sprach, dann darüber, wie viel er dafür bezahlen würde. Sieht nicht sehr eindrucksvoll aus, aber man weiß, was man über elfischen Tand sagt.\r\nDie Dame Auriferous in Tristessa möchte, dass man die Katakomben untersucht und dass man alle leblosen Überreste, die man dort auffindet, verbrennt. Die Auferstehung weiterer Kreaturen soll dadurch verhindert werden. \r\n==Personen==\r\n* '''Waldläuferin Lilatha''' sitzt dort eingesperrt. Die [[Trolle]] haben sie aus dem Hinterhalt überfallen und in einem Käfig gefangen gehalten. Sie glaubt sie wollen sie opfern. Das Schloss des Käfigs ist nicht allzu kompliziert, doch sie kann es nicht erreichen.",},
			["Katakomben von Utgarde"] = { content = "Die '''Katakomben von Utgarde''' liegen unter Wyrmskol im [[Der heulende Fjord|Heulenden Fjord]]. Die Brücke über die Worgengrube in Wyrmskol führt direkt zum Tunnel und zum Eingang der Katakomben. Der Kampfring befindet sich am Ende dieses Korridors und dann ein paar Stufen hinunter. Die [[Vrykul der Drachenschinder]] lassen hier ihre Gefangen gegen ihre stärksten Gladiatoren kämpfen. Die Verlierer werden danach ins untere Geschoss geworfen, um dort von [[Nekromant]]en der [[Geißel]] in [[Ghul]]s verwandelt zu werden. Geheimnisvolle Schrifttafeln liegen überall im Dungeon verstreut. Oluf der Gewalttätige hat die Glyphen in seinem Besitz, um die Schrifttafeln zu entziffern. Er befindet sich im Ring des Richturteils, doch er wird erst dann rauskommen, wenn die anderen Gladiatoren besiegt sind. Das ist so gut wie die einzige Möglichkeit, an seine Glyphe heranzukommen.\r\n==Personen==\r\n* '''Daegarn''' - Daegarn ist ein Zwerg der [[Forscherliga]] und wird in einem Käfig im großen Kampfring fest hinter Gittern verschlossen gefangen gehalten.\r\n* '''Glorenfeld''' - Glorenfeld ist ein Zwerg der [[Forscherliga]].",},
			["Katapult"] = { content = "Das '''Katapult der Orcs''' war schon immer ein fester Bestandteil der [[Horde]]. Die Orc Katapulte, die in der Lage sind, brennende Geschosse über große Entfernungen abzufeuern, waren das Verhängnis vieler [[Allianz]] Regime. Obwohl immer eine kleine Gruppe von Orcs verfügbar sein muss, um diese zerstörerischen Maschinen zu bedienen, sind die zielsicheren Katapulte die stärkste Belagerungswaffe der Horde. \r\n==Belagerungswaffe==\r\nDas Katapult kommen als Belagerungswaffe in Schlachtfeldern wie dem [[Tausendwintersee]] oder den [[Sande von Ulduran|Sanden von Ulduran]] zum Einsatz. Es ist schneller als der [[Goblindampfpanzer]]. Die Reichweite und der Schaden sind dafür ein wenig niedriger. Das Katapult kann keine Personen aufnehmen.",},
			["Kathedralenplatz"] = { content = "'''Kathedralenplatz''' ist ein Viertel der Stadt [[Sturmwind]]. \r\n===[[Kathedrale des Lichts]]===\r\nAuf dem Kathedralenplatz befindet sich die ''[[Kathedrale des Lichts]]'', Sturmwinds Zentrum der spirituellen Erleuchtung. Sowohl Paladine als auch Priester üben hier ihre Fertigkeiten und erforschen die großen Wahrheiten hinter den Mauern der Kathedrale. \r\n===Kathedralenplatz===\r\nEbenfalls um den Brunnen ist das Waisenhaus und der Schmied Perfekte Platten zu finden. Am kleineren Brunnen in Richtung Hafen, bevor man den Innenbereich verlässt hat sich ein kleines Geschäft niedergelassen, das Nur Streitkolben genannt wird.\r\nDaneben steht das ''Rathaus'' von Sturmwind, wo Unterlagen über die Bevölkerung der Stadt aufbewahrt werden. Sie werden von den königlichen Disponenten des Volkszählungsbüros von Sturmwind verwaltet. Direkt angrenzend hat die Argentumdämmerung ihr Haus.\r\nZum Kanal hin weist das Haus der alten Emma und der Laden \"Die drei Winde\", in dem sich die Transmogrifizierer niedergelassen haben, die Rüstungen umschmieden können.\r\n==Personen==\r\n'''Lehrer für eine Klasse'''\r\n'''Ausrüstungshändler'''\r\n'''Ausrüstungsaufwertung und Transmogrifikation'''\r\n'''Weitere Persönlichkeiten'''",},
			["Kathedrale des Lichts"] = { content = "'''Die Kathedrale des Lichts''' befindet sich auf dem [[Kathedralenplatz]] der Stadt [[Sturmwind]].\r\n==Allgemeines==\r\nSie ist Sturmwinds Zentrum der spirituellen Erleuchtung. Sowohl Paladine als auch Priester üben hier ihre Fertigkeiten und erforschen die großen Wahrheiten hinter den Mauern der Kathedrale.\r\n===Wissenswertes===\r\nMitglieder des [[Schattenhammerkult]]es hatten den Plan verfolgt die Kathedrale des Lichts in die Luft zu sprengen. Es gelang [[Jack Bauden]] zum Glück diesen Plan des [[Der Schwarze Bischof|Schwarzen Bischofs]] zu vereiteln. Dies ist nicht der einzige Vorfall, der in der Priesterschaft aufgefallen war. Auch der [[Erzbischof Benedictus]] wurde ein Werkzeug der Finsternis. Er hat Sturmwind verlassen gegen jene anzutreten, die das [[Licht ]] verteidigen.\r\n==Personen==\r\n'''Lehrer für eine Klasse'''\r\n'''Lehrer für einen Beruf'''\r\n'''Weitere Persönlichkeiten'''",},
			["Katze"] = { content = "Katzen sind sehr beliebte Haustiere und überdies ist Katzenfell gut gegen Rheuma. Allerdings nur solange die Katze noch drin steckt.\r\n==Arten und Händler==\r\nDie verückte Katzenfrau Donni Anthania im [[Wald von Elwynn]] verkauft für je 40 Silber:\r\n* '''Bombay'''\r\n* '''Cornish Rex'''\r\n* '''Orangefarbene Tigerkatze''' \r\n* '''Silberne Tigerkatze'''\r\n===Weitere Arten===\r\n* '''Schwarze Tigerkatze''' - Schwarze Tigerkatzen können nur bei Bewohnern von [[Dalaran]] im [[Alteracgebirge]] und im [[Silberwald]] gefunden werden.\r\n* '''Siamkatze''' - Bei Händler Rashaad auf der [[Sturmsäule]] im [[Nethersturm]] kann man eine Siamkatze für 60 Silber erwerben. Manchmal hat auch [[Krümel]] der Koch in den [[Todesminen]] seine Siamkatze dabei.\r\n* '''Weißes Kätzchen''' - Klein Timmy in [[Sturmwind]] verkauft ab und an ein Weißes Kätzchen für 60 Silber. Timmy läuft stets den gleichen Weg, an den Kanälen entlang. Besonderheit: Timmy erscheint nur zu bestimmten Zeiten",},
			["Kavernen des Schattenhammers"] = { content = "Man konnte eine weitere Operationsbasis des [[Schattenhammer Kult]]s ausfindig machen. Es ist eine gut versteckte Höhle in der nordöstlichen Ecke von Silithus, bekannt als die Kavernen des Schattenhammers. Der örtliche Anführer des Kultes, Vyral der Üble, residiert dort. Die Kavernen des Schattenhammers beherbergen furchterregende Schrecken.",},
			["Kel'Therilsee"] = { content = "Die Geschichte hinter Kel'Theril in [[Winterquell]] ist die eines verfluchten Volkes, gebunden an den Ort, an dem es ein unglückliches Ritual versuchte ... Die [[Hochgeborene]]n, die man dort finden werdet, stahlen einst ein hochheiliges Artefakt in dem Glauben, dass sie seine Macht für sich selbst nutzen und so noch mächtiger werden könnten. Durch ihre Bemühungen zerbrach das Relikt in einer gewaltigen Explosion, bei der die Teile unter das Eis des Sees getrieben wurden. Die Geister der [[Hochgeborene]]n suchen den Kel'Therilsee heim. In seinen Tiefen liegen noch die Teile des alten Reliktes, des [[Kristall von Zin-Malor]] und die Geister der [[Hochgeborene]]n suchen immer noch nach Teilen dessen, was sie für immer nach Kel'Theril verdammte - das gestohlene Relikt. Es ist ein Artefakt aus dem [[Tempel von Zin-Malor]] in [[Azshara]], das starke arkane Kräfte fesseln und kontrollieren kann. Es hätte für das Gute genutzt werden können, aber die bösen Absichten derjenigen, die es stahlen, ließen es zersplittern. Der [[Kristall von Zin-Malor]] kann niemals in den Tempel zurückgebracht werden, der nur noch eine Ruine ist. Die [[Hochgeborene]]n hier sind durch ihr eigenes Elend verwirt, aber einige von ihnen sind auch betrübt und erkennen den Fehler dessen, was vor so langer Zeit geschah. Von den stärksten Magieanwendern sind nur eine Hand voll in der Lage, solch eine Macht zu kontrollieren.",},
			["Kel'Thuzad"] = { content = "'''Kel'Thuzad''', der Erz-[[Lich]] der [[Pestländer]], ist einer der wichtigsten Diener des [[Lichkönig]]s und war verantwortlich für die Verbreitung der [[Seuche]] in [[Lordaeron]]. Nachdem er im [[Der Dritte Krieg|Dritten Krieg]] von [[Arthas]] vernichtet wurde, kehrte er als Lich zurück. Er half schließlich Arthas bei der Beschwörung von [[Archimonde]], dem Kommandanten der [[Brennende Legion|Brennenden Legion]]. Kel'Thuzads ware Loyalität gehörte jedoch dem Lichkönig - nicht der Brennenden Legion. Nachdem Arthas weiter nach [[Nordend]] zog, blieb Kel'Thuzad als Kommandant in Lordaeron zurück. Aus seiner über [[Stratholme]] fliegenden [[Nekropole]] [[Naxxramas]] lenkte er das Geschehen der [[Geißel]]. Mittlerweile ist Kel'Thuzad samt Nekropole weiter nach Nordend gereist, um dort seinem Lichkönig beizustehen. \r\n==Geschichte==\r\nKel'Thuzad gehörte einst dem hohen Rat von [[Dalaran]] an und war ein guter Freund des obersten Magiers [[Antonidas]]. Er hatte allerdings immer ein großes Interesse an den verbotenen Lehren der Nekromantie. Trotz seiner hohen Stellung wurde er dadurch zum Außenseiter. \r\n===Ruf des Lichkönigs===\r\nAls er den Ruf des [[Lichkönig]]s hörte, willigte dieser nur zu gerne ein, da er wusste, die [[Kirin Tor]] würden ihm nicht lange gestatten, die verbotenen Lehren zu studieren. Er schwor den Kirin Tor ab, veräußerte seinen Besitz und lagerte sein Vermögen ein. Dann machte er sich auf den Weg nach [[Nordend]], die Stimme des Lichkönigs immer im Kopf. Er durchwanderte die Ruinen des einstigen Königreichs [[Azjol-Nerub]] und sah somit die Zerstörung, zu welcher der Lichkönig fähig war, aus erster Hand. Dieses Beispiel von [[Ner'zhul]]s Macht bekräftigte Kel'Thuzad nur in dem Glauben, das Bündnis mit Ner'zhul wäre das Richtige. Als er den [[Eiskronengletscher]] erreicht hatte, ließen ihn Ner'zuls Wächter überraschenderweise passieren und er gelangte zum [[Frostthron]], vor dem er sich warf und Ner'zhul seine Seele anbot.\r\n===Kult der Verdammten===\r\nDer [[Lichkönig]] akzeptierte seinen Vorschlag und versprach Kel'Thuzad Macht und Unsterblichkeit im Gegenzug zu Gehorsam und Loyalität. In seiner Gier nach Wissen und Macht nahm Kel'Thuzad die große Mission an, nach [[Lordaeron]] zurückzukehren und eine Religion zu gründen, die den Lichkönig anbeten sollte. Kel'Thuzad machte sich also verkleidet auf den Weg nach Lordaeron zurück und nutzte sein Vermögen, um diesen Kult aufzubauen. Es gelang ihm, viele der unzufriedenen Bürger Lordaerons vom Glauben an das [[Heiliges Licht|Heilige Licht]] zum Glauben an [[Ner'zhul]] zu konvertieren. In den Monaten wuchs seine Gemeinschaft, der [[Kult der Verdammten]], immer mehr, doch Kel'Thuzad achtete sorgfältig darauf, dass die Regierenden in Lordaeron seine Aktivitäten nicht bemerkten.\r\n===Verbreitung der Seuche===\r\nLetztendlich kam von [[Ner'zhul]] der Befehl, den Angriff auf die menschliche Zivilisation zu beginnen. Er schloss seine Seuchenenergien in Artefakte ein, die man die Seuchenkessel nannte, und ließ diese von Kel'Thuzad nach [[Lordaeron]] bringen, wo die [[Seuche]] auf die Dörfer übergriff. Die Angehörigen seines [[Kult der Verdammten|Kultes]] sahen mit Freuden die Auswirkungen der Seuche: Die infizierten [[Menschen]] starben und kehrten als [[Zombie]]s im Dienste [[Ner'zhul]]s zurück. Viele von ihnen waren schon begierig darauf, auch der Seuche anheim zu fallen und unsterblich zu werden. Doch die Aktionen des Nekromanten und seines Kultes blieben jetzt nicht mehr im Verborgenen. Die [[Silberne Hand]] und die [[Kirin Tor]] begannen damit, die Gründe für diese Seuche zu untersuchen. Auf der Straße der Könige kam es zum ersten Aufeinandertreffen mit [[Arthas]], dem Sohn von König [[Terenas]], und [[Jaina Prachtmeer]], Tochter von [[Daelin Prachtmeer]]. Die beiden fanden heraus, dass Kel'Thuzad das Getreide verseucht hatte und so die Seuche verbreitete.\r\n===Tod in Andorhal===\r\nNun entdeckt, machte sich Kel'Thuzad mit seinem [[Kult der Verdammten|Kult]] auf und verseuchte [[Andorhal]], die Kornkammer [[Lordaeron]]s. Von hier aus hätte das Getreide bis nach [[Stratholme]] geliefert werden sollen, wo die Armee der Untoten schließlich einfallen sollte. [[Arthas]] und [[Jaina Prachtmeer|Jaina]] hatten ihn allerdings verfolgt und stellten den Nekromanten. Im Kampf unterlegen, war sich Kel'Thuzad allerdings sicher, sein Tod würde nichts bedeuten. Er erzählte Arthas von dem Schreckenslord [[Mal'Ganis]], dem er diente. Letztendlich hatte sein wahrer Meister, der [[Lichkönig]], noch eigene Pläne mit dem Prinzen, doch vorerst starb Kel'Thuzad. Da seine Seele für immer an den [[Lichkönig]] gebunden war, versuchte Kel'Thuzad auch im Tode noch seinem Herrn zu dienen.\r\n===Wiederbelebung durch Arthas===\r\nEr wartete in der Krypta, bis [[Arthas]] lange Zeit später zurückkehrte, nur noch ein Schatten seiner selbst, bewaffnet mit dem Schwert [[Frostgram]], das der [[Lichkönig]] selbst erschaffen hatte. Nun hatte Arthas den Auftrag, Kel'Thuzad wieder beleben zu lassen und nahm sich des Leichnams des Nekromanten an. Kel'Thuzads Geist warnte den Prinzen vor den [[Schreckenslord]]s, sie sollten besser nicht erfahren, dass er ihm half, denn die Schreckenslords sollten darauf achten, dass der Lichkönig seinen Auftrag erledigte. Da Kel'Thuzad zu mächtig war, um auf herkömmliche Weise wiederbelebt zu werden, machte sich Arthas auf und eroberte mit Hilfe der [[Geißel]] (den Namen gab Kel'Thuzad der Armee aus [[Untote]]n) das Land [[Quel'Thalas]] und die Stadt [[Silbermond]]. Mit dem dort befindlichen [[Sonnenbrunnen]] gelang schließlich die Wiederbelebung Kel'Thuzads. Als [[Lich]] stellte er sich wieder in die Dienste [[Ner'zhul]]s und begleitete Arthas fortan auf seiner Mission, das Kommen der [[Brennende Legion|Brennenden Legion]] vorzubereiten.\r\n===Kampf um Dalaran===\r\nDurch das Dämonentor, das sie von einer Hand voll [[Orcs]] eroberten, ließ Lord [[Archimonde]] sie wissen, dass sie das [[Buch des Medivh]] brauchten, um damit die Beschwörung durchzuführen, welches die [[Dämonen]] wieder nach [[Azeroth]] lassen würde. Arthas führte den Angriff auf [[Dalaran]] an und eroberte zusammen mit Kel'Thuzad das erhoffte Buch. Während Kel'Thuzad die Beschwörung abhielt, probierten die [[Kirin Tor]] zwar einen verzweifelten Gegenangriff, doch sie wurden von [[Arthas]] zurückgeschlagen und Kel'Thuzad konnte die Beschwörung beenden. Als Archimonde das Portal durchschritten hatte, wies er die [[Schreckenslord]]s an, die Kontrolle über die [[Geißel]] zu nehmen, Arthas und Kel'Thuzad landeten auf einmal im Hintergrund.\r\n===Unabhängigkeit von der Legion===\r\nWährend [[Arthas]] der Legion später nach [[Kalimdor]] folgte, verweilte Kel'Thuzad in [[Lordaeron]] und versuchte so viele Loyalisten in der Kontrolle des [[Lichkönig]]s zu halten wie möglich. Als Arthas aus Kalimdor zurückkehrte und berichtete, dass die Legion besiegt wurde, schickte dieser die [[Schreckenslords]] fort aus seinem Land. Kel'Thuzad unterstützte Arthas dabei, die letzten Flüchtlinge der [[Menschen]] aufzuhalten und den [[Orden der Silbernen Hand]] entgültig zu vernichten. \r\nAls Arthas immer mehr von Anfällen geplagt wurde, in denen ihn der [[Lichkönig]] zu sich nach [[Nordend]] rief, stellten ihm die Schreckenslords eine Falle; sie hatten die Kontrolle über den Großteil der in der Hauptstadt befindlichen [[Geißel]] übernommen und Arthas von Kel'Thuzad getrennt. Kel'Thuzad ließ dem [[Todesritter]] alle Hilfe zukommen, die ihm möglich war und so gelang es Arthas, mithilfe einiger [[Banshee]]s in die umliegenden Wälder zu entkommen. Dieser bemerkte zu spät, dass dies noch zur Falle der Schreckenslords gehört und wurde von [[Sylvanas Windläufer]], der Bansheekönigin, die Arthas in [[Silbermond]] besiegt hatte, vergiftet. Doch Kel'Thuzad kam rechtzeitig zur Hilfe und vertrieb die Banshees. Arthas machte sich auf den Weg nach [[Nordend]], während Kel'Thuzad erneut die Stellung hielt.\r\n===Flucht nach Nordend===\r\nKel'Thuzads Festung, die schwebende Nekropole [[Naxxramas]], landete in den Ruinen des Reiches [[Lordaeron]]. Von dort versuchte der Erz-[[Lich]] des [[Lichkönig]]s nun, den legendären Stab des [[Medivh]], [[Atiesh]], in seine Hand zu bekommen. Doch er wurde von einer Gruppe Helden der [[Argentumdämmerung]] besiegt und sein [[Phylakterium]] erbeutet. Die Helden gaben es [[Vater Inigo Montoy]], der es vernichten sollte. Doch der Mann erlag Kel'Thuzads flüsternder Stimme und in einem schaurigen Ritual erhob sich Kel'Thuzad erneut. Inigo Montoy wurde zum Dank für seine Hilfe in einen Lich verwandelt. Kel'Thuzad floh mit Naxxramas nach [[Nordend]], um der Geißel im Kampf gegen [[Allianz]] und [[Horde]] beizustehen.",},
			["Kel'Thuzad und der Kult der Verdammten"] = { content = "== Entstehung des Lichkönigs==\r\n'''- Teil 5 -'''\r\n===Kel'Thuzad und der Kult der Verdammten===\r\nEs gab eine Hand voll mächtiger Individuen, die weit verstreut auf der ganzen Welt den mentalen Ruf des [[Lichkönig]]s hörten. Der Bedeutendste unter ihnen war der Erzmagier [[Kel'Thuzad]] von der magischen Nation [[Dalaran]]. Kel’Thuzad, eines der ältesten Mitglieder des [[Kirin Tor]] – des herrschenden [[Rat von Dalaran]] –, war aufgrund der Hartnäckigkeit, mit der er die verbotene Kunst der [[Nekromant]]ie studierte, schon immer als Sonderling betrachtet worden. Er war besessen von dem Wunsch, alles über die Welt der Magie und ihre dunklen Wunder zu wissen, und frustriert ob dessen, was er für die altmodischen und phantasielosen Denkweisen seiner Kollegen hielt. \r\nAls er den Ruf aus [[Nordend]] vernahm, setzte der [[Erzmagier]] seine gesamte nicht unerhebliche Willenskraft ein, um mit der geheimnisvollen Stimme in Kontakt zu treten. In der Überzeugung, dass der Kirin Tor zu zimperlich war, Macht und Wissen der dunklen Künste zu nutzen, gelobte er, von dem übermächtigen Lichkönig alles zu lernen, was er nur konnte. Kel’Thuzad verzichtete auf sein Vermögen und seine einflussreiche politische Position, schwor dem Kirin Tor ab und verließ Dalaran für immer. Von der beharrlichen Stimme des Lichkönigs in seinem Geist angetrieben, veräußerte er seinen gesamten riesigen Besitz und lagerte sein Vermögen ein. Allein reiste er zu Wasser und zu Lande viele Meilen, bis er schließlich die eisige Küste von Nordend erreichte. Der Erzmagier, fest entschlossen, den [[Eiskronengletscher]] zu erreichen und dem Lichkönig seine Dienste anzubieten, durchquerte die durch den Krieg verwüsteten Ruinen von [[Azjol-Nerub]]. Kel’Thuzad sah Ausmaß und Wucht von Ner’zhuls Macht aus erster Hand. Er begann zu glauben, dass es nicht nur weise wäre, sich mit dem geheimnisvollen Lichkönig zu verbünden, sondern obendrein wahrscheinlich höchst fruchtbar.\r\nNach monatelangen Reisen durch das lebensfeindliche arktische Ödland gelangte Kel’Thuzad schließlich zum dunklen Eiskronengletscher. Mutig näherte er sich Ner’zhuls finsterer Zitadelle ... und erschrak, als die stummen untoten Wächter ihn passieren ließen, als würde er erwartet. Kel’Thuzad stieg tief in das kalte Erdreich hinab und gelangte so zum Grund des Gletschers. Dort warf er sich in der endlosen, düsteren Eishöhle vor dem [[Frostthron]] auf den Boden und bot seine Seele dem dunklen Lord der Toten an.\r\nDer Lichkönig war zufrieden mit seinem jüngsten Diener. Er versprach Kel’Thuzad Unsterblichkeit und große Macht als Gegenleistung für Loyalität und Gehorsam. Kel’Thuzad dürstete nach Wissen und Macht, und so akzeptierte er seine erste große Mission – in die Menschenwelt zu ziehen und dort eine neue Religion zu gründen, die den Lichkönig als Gott verehren sollte. Damit der Erzmagier seine Mission besser erfüllen konnte, ließ Ner’zhul Kel’Thuzads Menschsein unangetastet. Der betagte, aber dennoch charismatische Zauberer sollte seine Kräfte der Illusion und Überzeugung nutzen, um die unterdrückten, geknechteten Massen von [[Lordaeron]] in seinen Bann zu ziehen. Sobald er ihre Aufmerksamkeit geweckt hatte, wollte er ihnen in einer neuen Vision zeigen, wie die Gesellschaft aussehen könnte – und eine neue Galionsfigur, die sie ihren König nennen konnten ... .\r\nKel’Thuzad kehrte verkleidet nach Lordaeron zurück und verwendete in den kommenden drei Jahren sein gesamtes Vermögen und seine Geisteskräfte darauf, eine geheime Bruderschaft gleich gesinnter Männer und Frauen ins Leben zu rufen. Diese Bruderschaft, die er \"[[Kult der Verdammten]]\" nannte, versprach ihren Jüngern gesellschaftliche Gleichstellung und ewiges Leben auf Azeroth als Gegenleistung für ihre Dienste und Gehorsam gegenüber Ner’zhul. Im Lauf der Monate fand Kel’Thuzad viele eifrige Freiwillige für seinen neuen Kult unter den erschöpften, überlasteten Arbeitern von Lordaeron. Überraschenderweise wurde Kel’Thuzads Ziel, den Glauben der Bürger an das [[Heilige Licht]] zum Glauben an Ner’zhuls dunklen Schatten zu pervertieren, mühelos erreicht. Während der Kult der Verdammten wuchs und sein Einfluss zunahm, achtete Kel’Thuzad akribisch darauf, seine Aktionen vor den Regierenden von Lordaeron verborgen zu halten.",},
			["Kelch der Einheit"] = { content = "Der Kelch der Einheit war das Gefäß , in dem [[Mannoroth]]s Blut verewahrt und den [[Orc]]s zum Trinken gegeben wurde.Der Kelch bestand aus dem Horn einer unbekannten Tierart und war eines der wenigen Dinge, die unter der enormen Macht des [[Dämonen]]blutes nicht zu Asche zerfielen. Was aus dem Kelch wurde , ist nicht bekannt, doch Dämonenblut dürfte er noch immer enthalten, da nicht alle Orcs daraus tranken.",},
			["Kelch von Elune"] = { content = "Der '''Kelch von Elune''' ist ein schimmerndes silbernes Gefäß, scheinbar ungetrübt vom anhaltenden Einfluss der Verderbnis. Der Kelch ist ein Relikt von unschätzbarem Wert und befand sich einst in einem bedeutenden Schrein der [[Nachtelfen]] im nordöstlichen [[Eschental]], westlich von [[Waldeslied]]. Heute befindet sich an dieser Stelle das Gebiet von [[Satyrn]], bekannt als [[Satyrnaar]]. Der Kelch von Elune war der den Hütern des Schreins von den [[Elune]]s Priestern anvertraut wurde. Einst reisten Pilger zu dem Schrein, um die heilenden Kräfte, die dem Kelch nachgesagt wurden, am eigenen Leib zu erfahren. Vielleicht sind diese Geschichten nur Ammenmärchen, aber wenn nur ein Körnchen Wahrheit in ihnen steckt, könnte der Kelch vielleicht der Schlüssel zur Wiederherstellung des leidenden Waldes sein.",},
			["Kelen der Sucher"] = { content = "'''Kelen der Sucher''' war einer der erleuchteten Gelehrten von [[Dalaran]] und den [[Kirin Tor]]. Er war ein unerschütterlicher Erzmagier, der die dämonische Invasion von [[Lordaeron]] und ganz [[Kalimdor]] erlebte. Kelen war ursprünglich ein gebildeter Forscher, der die [[Kul Tiras]] Marine zu einer fernen Insel führte, in der Hoffnung den entferntesten Außenposten der Allianz zu errichten. Sie erschufen einen kleinen Außenposten, aber wurden bald durch Angriffe der lokalen Inseltrolle und [[Murloc]]s überrollt. Die Trumpfkarte kam, als er mit [[Thrall]] konfrontiert wurde als seine Flotte dort verankert war. Kelen machte mit den Kul Tiras Streitkräften einen hastigen Rückzug nach Lordaeron und ging zurück nach Dalaran, wo er auf weniger Aufregung hoffte. Doch er erhielt sie nicht. Kelen der Sucher führte die Kirin Tor gegen die Untoten Eindringlinge von Dalaran als [[Arthas]] kam. Doch eine Armee fiel ihm in den Rücken, da Arthas dachte, dass er das [[Buch des Medivh]] besäße. Trotz der magischen Anschläge von Kelen und seinen Kollegen, brach Arthas zur [[Violette Zitadelle|Violetten Zitadelle]] durch, tötete [[Antonidas]] und nahm das Buch. Dann erhielt Kelen eine Warnung von [[Jaina Prachtmeer]], der Tochter des Lordadmirals der See-Flotten der Allianz und Lehrling des verstorbenen Antonidas. Sie vermutete, dass etwas kam, dessen sie nicht Herr werden konnten und empfahl nach Kalimdor zu fliehen. Kelen sah wie [[Kel'Thuzad]] dunkle Zauber auf die Berghänge um die Stadt webte und wusste dass etwas schlecht war. So beschloss er Jainas Instinkten zu folgen und unterstützte schließlich ihre Blockade im [[Steinkrallengipfel]]. Bei der Ankunft in Kalimdor kam Kelen und seine Menschen Expedition unter den Angriff der Orks von [[Grom Höllschrei]]s [[Kriegshymnenklan]]. Kelens Tod ist nicht deutlich nachgewiesen, aber weiß man nicht, ob er Höllschrei’s Überfall überlebte.\r\n'''Quelle:'''",},
			["Kel´Thuzad"] = { content = "#REDIRECT [[Kel'Thuzad]]", redirect = "Kel'Thuzad",},
			["Kel´Thuzad"] = { content = "#REDIRECT [[Kel'Thuzad]]", redirect = "Kel'Thuzad",},
			["Kerker des Wächters"] = { content = "Der Kerker des Wächters liegt im Schattenmondtal südlich der Ruinen von Baa'ri. [[Akama]] und die [[Todeshörige]]n der [[Aschenzungen]] dort gelten als die bösartigsten und grausamsten der [[Zerschlagene]]n und sollen irgendwo im Kerker des Wächters eine Folterkammer betreiben. \r\n* '''[[Akama]]''' befindet sich in der verborgenen Kammer im Kerker des Wächters. Er ist der Anführer der [[Todeshörige]]n und der Anführer der [[Aschenzungen]]. \r\n* '''[[Maiev Schattensang]]''' befindet sich eingesperrt im Kerker des Wächters direkt hinter [[Akama]]\r\n* '''Olum''' ist einer der engsten Freunde von [[Akama]] und seiner treuesten Anhänger. Sein Beitrag zu ihrem Werk ist für die Pläne unverzichtbar. Die [[Naga]]s haben herausgefunden, dass er gegen [[Illidan]] arbeitet und ihn grausamer Folter unterzogen. Sie haben jedoch nichts aus ihm herausbekommen. [[Akama]] selbst hat ihm beigebracht, wie man Schmerz mit Hilfe von Meditation überwindet. [[Illidan]] hat den [[Naga]]s aufgetragen, Olum zu ihm persönlich zu bringen. Er hätte ihn sofort durchschaut und die tiefsten Geheimnisse seiner Seele gesehen. \r\n* '''Sanoru''' ist [[Akama]]s Stellvertreter vor Ort.\r\n* '''Udalo''' ist [[Akama]]s verstorbener Bruder. Bevor er starb, hat er noch ein einzelnes Wort auf den Boden unter sich geschrieben. Die Schrift ist kaum lesbar, aber man erkennt das Wort '[[Ata'mal]]'. Vielleicht versteht [[Akama]] die Nachricht seines Bruders.\r\n* Ein [[Satyrn|Satyr]] namens '''Zandras''' überwacht die [[Todeshörige]]n in [[Illidan]]s Auftrag von den Zinnen der Gefängnismauer aus.",},
			["Kernhund"] = { content = "'''Kernhunde''' sind gewaltige Hunde-ähnliche Kreaturen mit zwei Köpfen, die der glühenden Lava entspringen. Sie zählen zu den Wildtieren und man findet sie vor allem im [[Geschmolzener Kern|Geschmolzenen Kern]].\r\n==Persönlichkeiten==\r\n* [[Die Bestie]]\r\n* [[Magmadar]]",},
			["Kessels Wegelager"] = { content = "Kessel, der [[Elekk]]lord, betreibt in Kessels Wegelager auf der [[Blutmythosinsel]] zusammen mit Vorkhan, dem [[Elekk]]treiber, eine Wegstation. [[Aonar]] kümmert sich um die Versorgung der [[Elekk]]s und hat eine wundervolle Entdeckung gemacht: Er hat [[Sandbirne]]n zum Kuchenbacken verwendet, aber wenn er nicht Acht gibt, kommen die [[Elekk]] angelaufen und stehlen ihm das Obst. Er hatte genug eingesammelt, um mit den Tieren teilen zu können, aber sein Vorrat ist aufgebraucht und nun herrscht wieder großes Verlangen nach Kuchen.",},
			["Khadgar"] = { content = "'''Khadgar''' ist der ehemalige Lehrling des gefallenen Wächters [[Medivh]]. Er war es, der entdeckte, dass Medivh von [[Sargeras]] besessen war, und dass er das [[Dunkle Portal]] geöffnet hatte. Obwohl er seinen Meister verehrte, war er gezwungen, ihn zu töten und seiner gemarterten Seele Ruhe zu bringen. Er kämpfte an der Seite von Lord [[Anduin Lothar]], als sie die [[Horde]] aus den Ländern auf [[Azeroth]] vertrieben. Als Erbe des Vermächtnisses Medivhs sah er das als seine Pflicht an. Als dazu aufgerufen wurde, in die Scherbenwelt einzudringen und dem Übel der [[Orcs]] ein für alle Mal ein Ende zu bereiten, meldete er sich freiwillig, zusammen mit seinen Freunden [[Turalyon]], [[Alleria Windläufer]], [[Danath Trollbann]] und [[Kurdran Wildhammer]]. \r\nSeine Kameraden und er nannten sich die [[Söhne Lothars]], zu Ehren des größten, selbstlosesten Helden aller Zeiten. Sie gaben alles, um [[Ner'zhul]] zu besiegen und seinem Wahnsinn ein Ende zu bereiten. Als [[Draenor]] in Trümmer fiel, zerschmetterten sie das dunkle Portal, um weiteren Schaden für Azeroth zu verhindern. Gefangen in der Scherbenwelt taten sie ihr Bestes, um zu überleben. \r\nMit der Zeit spürten sie eine neue böse Macht, die sich ihnen vom Wirbelnden [[Nether]] aus näherte. Schlimmer als die dunklen [[Orcs]]: Es war die [[Brennende Legion]] selbst, die die Macht über die [[Scherbenwelt]] zu erlangen suchte. Während seine Kameraden die Stellung gegen die sich nähernde Dunkelheit hielten, benutzte er [[Magie]], um in das [[Große Dunkle Jenseits]] zu gelangen. \r\nDort spürte er Wesen aus unglaublichem Licht, von großer Reinheit. Er waren [[A'dal]] und seine [[Naaru]], die er gefunden hatte. Es war nichts weniger als ein Wunder. Er überzeugte A'dal und seine Geschwister, mit ihm zurückzukehren. Er glaubt, nur mit ihrer Macht können sie die Legion aus diesem Universum zurückdrängen. Aber ihre Macht muss erst in den Herzen alle erwachen. Um die Dunkelheit zu bekämpfen, müssen sie Boten des ewigen Lichts werden.\r\n==Geschichte==\r\nKhadgar wurde im Alter von 17 Jahren als Lehrling für [[Medivh]] von den [[Kirin Tor]] nach [[Karazhan]] entsand, wo er für einzelne [[Kirin Tor]] Medivhs Fähigkeiten erkunden und ihnen einzelne Bücher beschaffen sollte. Zwischen Khadgar und Medivh entwickelte sich eine Freundschaft, die einzelne wohl mit Loyalität gleichtun würden. Von Medivh trainiert, entwickelte er eine mächtige Zauberkraft, die später im Kampf gegen die [[Orcs]] wirksam eingesetzt wurde. In einer Vision sah sich Khadgar jenseits des [[Dunkle Portal|Dunklen Portals]] gegen die Orcs kämpfen und hoffte, dass diese Vision niemals wahr würde. \r\nDurch seine Reisen mit seinem Meister lernte er auch den König [[Llane Wrynn]], den Helden [[Anduin Lothar]] und schließlich die Halborc [[Garona]] kennen. Nachdem [[Sargeras]] Kontrolle über Medivh gewann, kehrte er mit Lothar nach Karazhan zurück, wo er sich Medivh im Kampfe stellte. Durch einen Zauberspruch alterte der 17 jähigre Khadgar um etliche Jahre und er verließ den Kampf als alter Mann. Er war es, der Medivh mit einem Schwert erstach und somit verhinderte dass Sargeras in seinen Körper zurückkehren konnte. \r\nUm die ehrfurchtgebietende Macht, die zur Erschaffung des Dunklen Portals nötig ist, zu ergründen, reiste er nach zurück nach [[Dalaran]], dem Sitz der [[Kirin Tor]], die von den Ursprüngen der Spalte zu berichten wussten. Nach dem Zweiten Krieg kehrte Khadgar nach [[Azeroth]] zurück und leitete die weiteren Untersuchungen an dem zerstörten [[Dunkle Portal|Portal]]. Eine erneute Invasion befürchtend, ordnete er den Bau von [[Burg Nethergarde]], nahe dem schwarzen Sumpf an, damit er in Ruhe seinem Studium nachgehen konnte. \r\n==Schriften==\r\n* '''Abhandlungen über dimensionale Konvergenz''' - Dieser Essay von Khadgar befindet sich bei [[Behüter Mahar Ba]] in der [[Burg Nethergarde]].\r\n'''Quelle''':",},
			["Kharanos"] = { content = "Es gibt nicht viele Pfade und Wege in [[Dun Morogh]], doch der längste und best ausgebauteste ist die Nord-Süd-Achse. Eine Straße die vom südlichen Passtunnel direkt nach Norden zu den Toren der Hauptstadt [[Eisenschmiede]] führt. Auf cirka der halben Strecke ist ein kleiner Handelsposten angesiedelt, welcher den Namen '''Kharanos''' trägt. Wenn man nicht von der Schönheit der Landschaft geblendet wird und vom Weg abkommt und gefressen wird, sollte man Kharanos nicht verfehlen können. - Eigentlich nicht ...\r\n==Personen==\r\n* '''Gebirgsjäger Dolf'''\r\n* '''Jarven Donnerbräu''' bewacht den Keller der Brauerei Donnerbräu in Kharanos.\r\n* '''Leftwitch''' ist ein [[Gnome]]n [[Magier]] der [[Wiederholer AG]].\r\n* '''Ozzie Wechselvolt''' und sein Partner Razzle arbeiten an einer Lösung für ein Heilmittel für die Erkrankung, die die Stadt verseucht... oder vielleicht auch ein Rezept für wirklich starken Rum. Genau wissen sie das aber erst, wenn sie es ausprobiert haben. Sie benötigen sie zum Test der Theorie ein paar Dinge, vor allem radioaktive Ablagerungen von den bestrahlten [[Troggs]] in [[Gnomeregan]]. Sie sind der Überzeugung, dasss das einzige Heilmittel mehr grünes Leuchten ist ... die hoch konzentrierten radioaktiven Ablagerung von [[Gnomeregan]]. Doch diese Ablagerung ist instabil und wird ziemlich schnell zerfallen.\r\n* '''Ragnar Donnerbräu''' ist fuchsteufelswild, denn Hurley Pestatem hat ihn beraubt. Eines der Rezepte der Familie wurde gestohlen. Als hätte er nicht schon Grund genug, die [[Dunkeleisenzwerge]] zu hassen. Seine Tavernengäste mögen nichts so sehr wie seine Eberrippchen in Biersauce. Das einzige Problem dabei ist, dass der ortsansässige Fallensteller, der ihn bisher mit den Zutaten versorgt hat, in die Armee des Königs eingetreten ist, um im Krieg an der Allianzfront zu helfen. Das Geheimnis liegt im Malz. \r\n* '''Razzle Flinkspross''' und Ozzie Wechselvolt haben vor, den schrecklichen Lepraeffekt mit ihrer jüngsten Erfindung wieder rückgängig zu machen: dem [[Rekombobulator]]. Die Maschine ist beinahe fertig, aber sie brauchen dringend einige Restabilisationszahnräder und gyromechanische Getriebeteile.\r\n* '''Tundra MacGrann''' hatte einen Monatsvorrat Trockenfleisch gesalzen und für die kalte Jahreszeit weggeschlossen. Weggeschlossen deshalb, damit die Bären nicht rankommen. Aber während er unterwegs auf der Jagd war, hat sich diese Bestie, Eisbart der Alte, mit seiner Fleischtruhe davongemacht. Er wird allerdings nicht durch das Thorium kommen. Tundra wiederum wird verhungern, wenn er sein Fleisch nicht wiederbekommt. Er würde es mit seinem steifen Bein niemals schnell genug in die Höhle hinein und wieder heraus schaffen.",},
			["Khardros"] = { content = "#REDIRECT [[Khardros Wildhammer]]", redirect = "Khardros Wildhammer",},
			["Khardros Wildhammer"] = { content = "Khardros Wildhammer war ein bedeutender [[Than]] des [[Wildhammer Klan]]s, unter dessen Führung sich die [[Zwerge]] dieses Klans sich von ihren Verwandten in [[Eisenschmiede]] abspalteten und begannen, die Gegend um [[Eisenschmiede]] zu besiedeln und nach mehr Einfluss zu streben. Im [[Krieg der drei Hämmer]] führte Khardros seinen Klan durch die Barrierentore von [[Dun Algaz]] nach Norden, wo sie auf dem fernen Gipfel [[Grim Batol]] sein eigenes Reich gründeten. Nach dem Sieg über [[Modgud]]s Armee zog Khardros mit seinem Volk weiter nach Norden in die Länder von [[Lordaeron]], wo sie sich in den dichten Wäldern des [[Hinterland]]es niederließen und die Stadt [[Nistgipfel]] gründeten. Nach seinem Tod ließen ihre Söhne ihm und [[Madoran Bronzebart]] zu Ehren zwei große Statuen errichten. Die beiden Statuen wachen noch heute über den Pass in die Südländer.",},
			["Khaz'goroth"] = { content = "Der Weltenschmied '''Khaz'goroth''' ist ein weiser Architektur und Ingenieur. Er gilt mithilfe seiner Schöpfung, den [[Irdene]]n, als Erschaffer aller Berge und Täler. Die [[zwergisch]]e Bezeichnung [[Khaz Modan]] erinnert heute noch an ihn.Er erschuf die [[Bergriesen]] und [[Irdenen]] und alles andere was aus Stein und Fels besteht. Sein Symbol ist sein mächtiger Hammer [[Vulraiis]]. Kaz'goroth ist der Herr der Felsen, der Metalle, der Erde und der Höhlen. Er mag [[Magie]] nicht, sondern verlässt sich lieber auf Körperkraft,Ausdauer und Zähigkeit.",},
			["Khaz Modan"] = { content = "Khaz Modan liegt nördlich von Azeroth und ist das Bergkönigreich der Bronzebarts auf dem gleichnamigen Kontinent. Der Name ist zwergisch für ‚Der Berg Khaz’ und spielt auf den [[Titanen]] [[Khaz'goroth]] an, der die [[Zwerge]] erschaffen haben soll. \r\nIn den Spitzen der Schneeüberzogenen Berge von [[Dun Morogh]] liegt die Hauptstadt des Reiches: [[Eisenschmiede]]. Hier sitzt der König [[Magni Bronzebart]].\r\n==Geographie==\r\nUnter den zerklüfteten, schneebedeckten Bergen von Khaz Modan haben sich [[Zwerge]] und [[Gnome]] ein riesiges Reich aufgebaut. Das Bergkönigreich reicht von den öden Wüsten im Norden des Landes bis zu den majestätisch Gipfeln der [[Rotkammgebirge]].\r\nDoch es war kein Land, dass Außenseiter willkommen hieß, denn die Schädel von vielen mutigen Kriegern zierten die [[Orc]]-Zelte dort und [[Drachen]] patrouillierten ständig den Himmel. Nur wenige Schiffe sind dem Gedanken nicht abgeneigt nach Khaz Modan zu segeln. Darunter fallen sogar die aus [[Kul Tiras]]. Khaz Modan blieb eine Bedrohung wegen der [[Drachen]] und ihren [[Orc]]ischen Meistern dort, aber die [[Allianz]] hatte Beobachter in und um das Land.\r\nWichtige Merkmale in Khaz Modan sind [[Grim Batol]], der [[Schwarzfels]], und [[Eisenschmiede]]. In Khaz Modan liegen folgende Regionen:\r\n* [[Dun Morogh]]\r\n* [[Loch Modan]]\r\n* Das [[Sumpfland]]\r\n* Die [[Sengende Schlucht]]\r\n* Die [[Verwüstete Lande|verwüsteten Lande]]\r\n====[[Eisenschmiede]]====\r\n[[Eisenschmiede]] war eine der wenigen Festungen der [[Zwerge]], die während des [[Der Zweite Krieg|zweiten Krieges]] nicht fiel.\r\n====[[Grim Batol]]====\r\n[[Grim Batol]] ist eine mächtige Festung der [[Zwerge]], die allerdings während des [[Der Zweite Krieg|zweiten Krieges]] von den [[Orcs]] eingenommen wurde. Lange nachdem die [[Horde]] wieder aus Khaz Modan vertrieben wurde war [[Grim Batol]] noch in den Händen der [[Orcs]], was sich erst änderte, als die [[Allianz]] eine große Gruppe in die Festung schickte um [[Alexstrasza]] zu befreien.\r\n====[[Schwarzfels]]====\r\nDer [[Schwarzfels]] war die Zentrale der Angriffe der [[Horde]] während des [[Der Erste Krieg|ersten]] und [[Der Zweite Krieg|zweiten Krieges]], und wurde später von der [[Allianz]] eingenommen.\r\n==Geschichte==\r\nWährend des [[Der Zweite Krieg|zweiten Krieges]] wurden bis auf die [[Hauptstadt]] [[Eisenschmiede]] nahezu alle Gebiete von Khaz Modan von den [[Orcs]] eingenommen und auch mehrere Jahre gehalten. Vorteile konnte sich die [[Horde]] außerdem durch den Zugang zu den großen Mineral Ablagerungen erschaffen. \r\n===Die Invasion der Orkischen [[Horde]]===\r\nBereits vor dem [[Der Zweite Krieg|2. Krieg]] griffen die [[Orcs]] das Bergkönigreich Khaz Modan an und zogen eine breite Schneise der Verwüstung durch die [[Zwerge]]nländer. Der Einflussbereich der [[Horde]] reichte bald vom verwüsteten Königreich [[Azeroth]] bis an die Grenzen [[Lordaeron]]s. [[Zwerge]] und [[Gnome]] boten der [[Allianz]] von [[Lordaeron]] ihre Dienste an, um die [[Menschen]] bei der Befreiung ihrer Heimat zu unterstützen. [[Arathi-Hochland|Stromgarde]] diente der [[Allianz]] als ein Bollwerk gegen die Angriffe aus dem Grenzgebiet, konnte aber der [[orc]]ischen Invasion nicht lange standhalten. Nachdem sich das Kriegsglück zugunsten der [[Menschen]] gewendet hatte, wurde die antike Zwergenstadt [[Dun Modr]] zerstört.\r\n===Die letzte Schlacht um Khaz Modan===\r\nNach der Schlacht um das [[Dunkle Portal]] und dem Feldzug in [[Draenor]] schien es so, als wäre die [[Horde]] endgültig besiegt worden. Doch dank seiner [[Drachen]] kontrollierte der [[Drachenmal Klan]] auch weiterhin die Bergfestungen [[Dun Algaz]] und [[Grim Batol]]. Er war der einzige Stamm, der den unsicheren Frieden in Khaz Modan und [[Lordaeron]] noch stören konnte. Der tollkühnen [[Magier]] [[Rhonin]] und Widerstandskämpfer der [[Zwerge]] befreiten die [[Drachen]]königin [[Alexstrasza]] aus dem Bann der [[Orcs]]. In ihrer Wut zerstörten die [[Drachen]] [[Grim Batol]] bis auf die Grundmauern und äscherten den größten Teil des [[Drachenmal Klan]]s ein. Die Armeen der [[Allianz]] standen längst bereit und griffen nun [[Dun Algaz]] an - damit wurde auch die letzte Bastion der [[Orcs]] auf dieser Welt zerstört.\r\n===Bündnistreue und neue Gefahren===\r\nKönig [[Magni Bronzebart]] gelobte, dass die [[Zwerge]] für immer in der Schuld der [[Allianz]] stehen würden. Als neue Gefahren ihre schwer erkämpfte Freiheit bedrohten, stellten sie sich dem Bündnis wieder zur Verfügung. Aber viele der menschlichen Königreiche gingen unter, als die [[Brennende Legion]] mit ihrer [[dämon]]ischen Invasion begann. Nun steht Khaz Modan einer neuen Bedrohung gegenüber. Die [[Troggs]] wurden aus ihren unterirdischen Höhlen befreit und sind an die Oberfläche gelangt. Seit sie freigelassen wurden, wird das Bergkönigreich von einer Invasion bedroht, der sich König Magnis Armeen tapfer entgegenstellen.\r\n==Zwerge von Khaz Modan==\r\nDie genialen [[Ingenieur]]e der Zwerge von Khaz Modan beschäftigen sich mit der Konstruktion mechanischer Gerätschaften. Sie haben Vorlagen der erfinderischen [[Gnome]] aufgegriffen und konnten noch fortschrittlichere Maschinen oder Waffen entwickeln. Die standhaften [[Krieger]] sind Meister im Umgang mit Feuerwaffen und suchen immer wieder nach neuen Methoden, um ihr explosives Schwarzpulver noch effektiver einzusetzen. \r\nAls die [[Orc]]ische [[Horde]] eine Schneise der Verwüstung durch das Bergkönigreich der [[Zwerge]] zog, verbündeten sie sich mit den [[Menschen]], um die [[Orcs]] aus ihrem Reich zu vertreiben. Während der dunklen Zeit des [[Der Zweite Krieg||zweiten Krieges]] konnte niemand auch nur den geringsten Zweifel an ihrem Wert für die [[Allianz]] von [[Lordaeron]] hegen. \r\nNachdem Khaz Modan schließlich befreit wurde, gelobte König [[Magni Bronzebart]], dass sein [[Volk]] für immer in der Schuld des Bündnisses stehen würde. Obwohl die [[Allianz]] zerfiel, zählten die [[Zwerge]] noch zu den zuverlässigsten Verbündeten von König [[Terenas]]. Als die [[Brennende Legion]] und ihre [[untote]]n Lakaien den schwer erkämpften Frieden bedrohten, stellten sie den [[Menschen]] ihre meisterlichen Fähigkeiten erneut zur Verfügung. Aber auch die [[Zwerge]] konnten die Königreiche der [[Allianz]] nicht vor dem allgegenwärtigen Schatten des Bösen verteidigen.\r\n===Legendäre Fähigkeiten der [[Bergkönig]]e von Khaz Modan===\r\nDie [[Hinterland|Zwerge der Nistgipfel]] üben den Hammerwurf als sportlichen Wettkampf und Training für den Krieg. Aber nur die [[Bergkönig]]e von [[Eisenschmiede]] können einen Hammer so fest werfen, dass ihre Gegner die Besinnung verlieren. Daher ist der Sturmschlag einer der gefährlichsten und wirkungsvollsten Angriffe der mächtigen [[Bergkönig]]e.\r\nDie mächtige Fähigkeit des Donnerschlags wurde erstmals von Murgen Hammerfall benutzt, um eine Schar angreifender [[Gnolle]] in den [[Alterac]]-Bergen zu bekämpfen. Sie ermöglicht den [[Bergkönig]]en, den Erdboden zu erschüttern und verheerende Schockwellen aus purer Energie auszuschicken, die in der Nähe befindlichen Feinden erheblichen Schaden zufügen.\r\n[[Bergkönig]]e, die die Hieb-Technik erlernen, schlagen mit solcher Wut zu, dass ihre normalen Angriffe einen Feind nicht selten lähmen und zerschmettern können. Wenn [[Bergkönig]]e die Energien des von den [[Zwerge]]n „neu entdeckten verzauberten Erbes“ bündeln, nehmen sie an Kraft und Größe zu – und sie nehmen die physikalischen Eigenschaften von bearbeitetem Stein an. In dieser Form sind sie unempfindlich gegen magische Angriffe und genießen eine deutlich verbesserte Widerstandskraft.",},
			["Khyrinda"] = { content = "== Allgemein==\r\n'''Name:''' Khyrinda Schattenwind\r\n'''Alter:''' ca. 600 Jahre (in Menschenjahren ca. 20)\r\n'''Rasse:''' Kaldorei (Nachtelfen)\r\n'''Eltern:''' unbekannt\r\n'''Gesinnung:''' Chaotisch / neutral (Begründung weiter unten)\r\n==Aussehen:==\r\n'''Haare:''' lang (ca. bis zur Mitte des Rückens), glatt, violette Haare\r\n \r\n'''Körper:''' trainiert \r\n'''Tattoo:''' über beide Augen jeweils eine rote Zeichnung\r\n==Eine Beschreibung:== \r\nDurch ein einschneidendes Erlebnis ein/zwei Jahren vor dem 3. Krieg - in der ihre \"Seele\" stark in Mitleidenschaft gezogen wurde, wurde ihre Persönlichkeit extrem labil. In ihrer Brust leben 3 Versionen ihrerselbst. \r\nEine davon ist ist die Ursprüngliche Khyrinda Schattenwind, eine junge, schüchterne (sehr ungewöhnlich für weibliche Nachtelfen) Kaldorei, sie versteht es meisterlich aus Leder allerlei Sachen herzustellen. Ihre Gesinnung ist Neutral / Gut. \r\nDie zweite Persönlichkeit ist eine Art Draufgängerin. Im Prinzip das komplete Gegenteil von der eigentlichen Khyrinda. Diese Version von Khyrinda liebt es Männer zu verführen, mit deren Gefühlen zu spielen und ihnen das Herz zu brechen. Sie ist die Persönlichkeit die sich für das was man ihr angetan hat rächen will und zwar an allen. Sie macht sich Grundsätzlich aus niemanden etwas, vorallem dann wenn es sich um Männer handelt. Ihre Gesinnung ist Neutral. \r\nDie dritte und zugleich gefährlichste Version ist Blutklinge. Diese Version ist extrem Sadistisch und eine Art Beschützerpersönlichkeit der anderen Beiden. Sie liebt es mit ihren Opfern zu spielen und sie dann zu töte (ähnlich wie Katzen . Ihre Proffesion ist das Lautlose Töten. Sie wechselt sich sehr oft und auch spontan mit der Verführerversion ab, meist aus heiterem Himmel. Doch wann immer Khyrinda in Gefahr gerät bricht Blutklinge durch. Sie ist eine kaltblütige Mördern ohne die Fähigkeit Mitleid zu empfinden. Im Prinzip ist Blutklinge das Resultat von der Verletztlichkeit der Ursprünglichen Khyrinda, sie verspührt keine Gefühle und kann somit nicht mehr Verletzt werden. Blutklinge empfindet es als Beleidigung als \"Khyrinda\" angesprochen zu werden, da dies ein Beweiß für ihre Schwäche und Verwundbarkeit ist. Ihre Gesinngung ist Neutral / Böse. \r\nDie Beiden zuletzt genannten sind die Beiden die ständig um die Kontrolle kämpfen und sich stetig abwechseln. Die ursprüngliche Khyrinda tritt immer seltener in Erscheinung und taucht nur in seltenen sehr entspannten Momenten auf. Wichtig zu erwähnen ist noch, dass die Verführerpersönlichkeit und Blutklinge von einander wissen und auch von allem was ihr Angetan wurde (wodurch sie entstanden sind). Khyrinda selbst allerdings weiß von alldem nichts, sie kann sich - oder will sich ? - an nichts erinnern. \r\nDas ist der Grund warum der Gesammtcharakter \"Khyrinda Schattenwind\" die Gesinnung \"Chaotisch / neutral\" hat. \r\n==Eine Kurze Geschichte:==\r\nKhyrinda Schattenwind schlenderte über die Brücke vor der Bank von Ironforge. Gerade eben hatte sie ein paar Lederstücke erstanden und wollte sich diese beim Postkasten abholen. Mit schwingenden Hüften - so wie es ihre Art war - spazierte sie über den Marktplatz immerwieder den Männlichen Passanten verführerische Blicke zuwerfend. \r\nEinige erwiderten diese Blicke auf eine Art die ihre Gedanken unschwer erkennen liesen. Man konnte es ihnen nicht verdenken, in ihrem roten, eng geschnittenen Top und den langen dunkelvioletten Haaren hatte die Nachtelfe durchaus etwas exotisches, was insbesondere die männlichen Vertreter der Menschen anzog wie das Feuer die Motte und dies sogar Buchstäblich. \r\nVor langer Zeit hatte ein Dolchlehrer zu Khyrinda gesagt: \"Sich mit euch einzulassen ist wie mit Feuer zu hantieren. Es sieht wunderschön und sanft aus wenn es dich in einer kalten Nacht wärmt, doch kommst du ihm zu nahe verbrennt es dich und lässt nur deine Knochen übrig.\" \r\n\"Liebster Meister\", hatte sie fast schon beleidigt erwidert, während sie mit ihrer linken Hand zärtlich über seine Wange strich \"Ich bin doch kein Feuer, ich bin der Tanarisskorpid, der auf euch in eurem Bett wartet. Der um eure Beine streich, euch ein wohliges Kribeln unter der Haut beschert, bevor er euch sticht und ihr langsam und qualvoll zu Grunde geht.\" Dieser Moment war es, als sie ihm die vergiftete Klinge blitzartig in den Hals stach. \r\nKalt fügte sie hinzu: \"Ihr hattet doch gesagt, ihr könnt mir nichts mehr bei bringen, ich hätte euch übertroffen. Scheint als hattet ihr recht ...\" So verlies sie den Sterbenden. \r\nEtwas rempelte sie an und riss sie damit aus ihrer Erinnerung, sie sah nur wie ein laut lamentierender Zwerg an ihr vorbei stapfte. Sie lächelte kurz fröhlich und verdrängte die Erinnerung an den guten Dolchmeister Karon und öffnete ihren Postkasten. Neben den Lederstücken - die sie für ihre Arbeit benötigte - kamen auch tonnen an Briefstücken zum vorschein, alle mit dem selben Inhalt \"Wolle Gold kaufe?\" \r\nGold kaufen? Was für ein schwachsinn ... \r\nSie wandte sich an einen Menschen der neben ihr stand und den Papierberg verwundert ansah. \"Oh ist das viel .. ob ich das alleine tragen kann? Könnt ihr einer schwachen Elfe nicht vielleicht helfen? Es soll euer Schaden nicht sein!\" raunte sie dem Mann ins Ohr. \r\nKurze Zeit später sah man die Elfe wie sie aus dem Gasthaus kam, mit einem etwas größer, gewordenen Geldbeutel und einem Lächeln auf den Lippen.",},
			["Kil'jaeden"] = { content = "'''Kil'jaeden''' ist einer der letzten großen Dämonenlords der Brennenden Legion. Einst war zusammen mit [[Archimonde]] und [[Velen]], welchem er am nächsten stand, der Herrscher der [[Eredar]]. Als [[Sargeras]] den Eredar das Angebot der Macht machte, nahm Kil'jaeden zusammen mit Archimonde an. Als Velen mit den [[Naaru]] von ihrer alten Welt [[Argus]] floh, schwor Kil'jaeden, diejenigen, die Velen gefolgt waren, bis ans Ende des Kosmos zu jagen. Und das tat er auch, bis er die Exilanten, die sich die [[Draenei]] nannten, auf ruhigen Welt namens [[Draenor]] fand...\r\n==Aussehen==\r\nKil'jaeden sieht zwar aus wie ein normaler [[Eredar]], ist jedoch inzwischen weit mehr. Wie [[Archimonde]] ist er zu riesigem Ausmaßen gewachsen, doch hat sich seine Haut im Gegensatz zu Archimondes rot gefärbt. Narben überziehen sie, eine für jede zerstörte Welt. Seine Augen brennen vor ewigem Hass und als einziger [[Eredar]] hat Kil'jaeden Flügel. Seine Rüstung ist schwarz und ähnlich der von Archimonde beschaffen. Er versteht Sargeras innere Motivation besser als jeder andere der Brennenden Legion und wurde daher nach Sargeras verschwinden ihr Anführer.\r\n===Kil'Jaeden und der Schattenpakt===\r\nEtwa zu der Zeit von [[Medivh]]s Geburt auf [[Azeroth]] brütete Kil'jaeden der Betrüger in der [[Nether|Wirbelnden Nether]]-Welt inmitten seiner Anhänger düster vor sich hin. Der listenreiche [[Dämon]]enlord schmiedete auf Geheiß seines Meisters [[Sargeras]] Pläne für eine zweite Invasion der [[Brennende Legion|Brennenden Legion]] in [[Azeroth]].\r\nDiesmal würde er keine Fehler dulden. Kil'jaeden überlegte sich, dass er eine neue Streitmacht brauchte, um [[Azeroth]]s Verteidigung zu schwächen, bevor die [[Brennende Legion|Legion]] wieder einen Fuß in die Welt setzen konnte. Wenn die sterblichen Völker, wie zum Beispiel die [[Nachtelfen]] und Groß[[drachen]], gezwungen wären, dieser neuen Bedrohung zu begegnen, wären sie zu schwach, um ernsthaften Widerstand zu leisten, wenn die wahre Invasion der [[Brennende Legion|Legion]] begann.\r\nEtwa zu dieser Zeit entdeckte Kil'jaeden die fruchtbare Welt [[Draenor]], die friedlich inmitten des Großen dunklen Jenseits schwebte. [[Draenor]], Heimat der [[Schamanen|schamanistischen]], in Clans organisierten [[Orcs]] und der friedliebenden [[Draenei]], war ebenso idyllisch wie groß.\r\nDie edlen Clans der [[Orcs]] streiften durch die offenen Prärien und frönten dem [[Jäger|Jagdsport]],während die abtrünnigen Draenei in den Resten der uralten Eredarzivilisation lebten . Kil'jaeden wusste, dass [[Draenor]]s Bewohner ein gewaltiges Potenzial hatten, der [[Brennende Legion|Brennenden Legion]] zu dienen, wenn man sie entsprechend erziehen konnte.\r\nKil'jaeden sah, dass er die Orks auch für seinen persöhnlichen Rachefeldzug nutzten konnte . Er zog [[Ner'zhul]], den [[Schamanen]]ältesten der [[Orcs]], in seinen Bann, so wie [[Sargeras]] in früheren Zeiten Königin [[Azshara]] verblendet hatte. Der Dämon missbrauchte den listigen Schamanen als Überträger und verbreitete Kampflust und Blutrausch unter den Clans der Orcs.\r\nNicht lange, und aus dem spirituellen Volk waren blutrünstige Monster geworden. Kil'jaeden drängte [[Ner'zhul]] und sein Volk zum letzten Schritt: Sie sollten sich ganz auf Tod und Krieg konzentrieren. Doch der alte [[Schamanen|Schamane]], der spürte, dass sein Volk auf immer und ewig Sklaven des Hasses sein würde, widersetzte sich dem Befehl des [[Dämon]]s.\r\nDurch die Weigerung [[Ner'zhul]]s frustriert, suchte Kil'jaeden nach einem anderen [[Orcs|Orc]], der sein Volk der [[Brennende Legion|Legion]] in die Hände spielen würde. Schließlich fand der gerissene [[Dämon]]enlord den willigen Anhänger, den er gesucht hatte - [[Ner'zhul]]s ambitionierten Lehrling [[Gul'dan]]. Kil'jaeden versprach [[Gul'dan]] unaussprechliche Macht als Gegenleistung für seinen unbedingten Gehorsam.\r\nDer junge [[Orcs|Orc]] wurde zu einem fleißigen Schüler der [[Dämon]]en[[magie]] und wuchs zum mächtigsten sterblichen [[Hexenmeister]] aller Zeiten heran. Er unterrichtete andere junge [[Orcs]] in den arkanen Künsten und trachtete danach, die [[Schamanen|schamanistischen]] Traditionen der [[Orcs]] zu tilgen. [[Gul'dan]] zeigte seinen Brüdern eine neue Form der [[Magie]], eine schreckliche neue Macht, die nach Verdammnis roch.\r\nKil'jaeden, der seine Macht über die [[Orcs]] festigen wollte, half [[Gul'dan]] dabei, den Schattenrat zu gründen, eine geheime Sekte, die die Clans manipulierte und die Anwendung von [[Hexenmeister]][[magie]] in ganz [[Draenor]] förderte. Mehr und mehr [[Orcs]] bedienten sich der [[Hexenmeister]][[magie]], bis die blühenden Felder und klaren Bäche von [[Draenor]] schwarz wurden und abstarben. Nach und nach verwitterten die weiten Prärien, die einst über Generationen Heimat der [[Orcs]] gewesen waren; zurück blieb nur karger roter Boden. Die [[dämon]]ischen Energien töteten die Welt nach und nach. \r\nKil'jaeden ist auch der Schöpfer des [[Lichkönig]]s und seine Agenten, die [[Schreckenslord]]s überwachten ihn bis zur zweiten Niederlage der Legion. Danach wandte sich sein Werkzeug gegen ihn und er beauftragte Illidan ihn zu töten. Kil'jaeden hat einen neuen ,willigen Diener, nachdem sein Alter, der [[Halbdämon]] [[Illidan]], welchem er die [[Kugel des Kil'jaeden]] gab, ihn enttäuschte, als er es nicht schaffte, sein altes Werkzeug, den Lichkönig, zu töten: Den [[Blutelf]]prinzen [[Kael'thas Sonnenwanderer]]. Kael'thas ist abhängig von der dämonischen Energie, auch als [[Teufelsenergie]] bekannt, geworden und hat seinem Herren das Versprechen abgegeben, ihn nach Azeroth zu bringen. Zu diesem Zweck will der wiedergeborene Prinz den [[Sonnenbrunnen]] von Quel'thalas benutzten.",},
			["Kil'jaedens Thron"] = { content = "'''Kil'jaedens Thron''' ist der Name einer alten Kultstelle des [[Schattenrat]]s. Der Thron steht auf einem inakivem Vulkan in der [[Höllenfeuerhalbinsel]] und ist von [[Dämon]]en besetzt. Dort tranken die [[Orc]]s das Blut [[Mannoroth]]s und brachten den Blutrausch über sich. Auch zeigte sich hier [[Kil'jaeden]] den [[Orc]]s und gab den [[Hexenmeister]]n des Schattenrats einen Teil seines dunklen Wissens.\r\nHeute residiert [[Verdammnislord Kazzak]] am Thron. Am Thron von Kil'jaeden schwor [[Kael'thas]] auch Kil'jaeden die Treue und erschuf die [[Teufelsblutelfen]], welche ihm dann nach [[Quel'Danas]] folgten.",},
			["Kil'jaeden und der neue Pakt"] = { content = "=== Kil’jaeden und der neue Pakt===\r\nGerade als [[Ner'zhul]] und seine Anhänger den „[[Sog der Unterwelt]]“ betraten – die Astralebene, die alle Welten im [[Großen Dunklen Jenseits]] verbindet –, gerieten sie in einen Hinterhalt von [[Kil'jaeden]] und seinen dämonischen Handlangern. Kil’jaeden, der geschworen hatte, sich wegen seiner trotzigen Weigerung an Ner’zhul zu rächen, peinigte den alten Schamanen gnadenlos, indem er seinen Leib langsam in Stücke riss. Kil’jaeden ließ den Geist des Schamanen am Leben und unversehrt – damit Ner’zhul deutlich spüren sollte, wie sein Körper verstümmelt wurde. Zwar flehte Ner’zhul den Dämon an, seine Seele zu befreien und ihm den Tod zu gewähren, doch der Dämon erwiderte grimmig, dass der Blutpakt, den sie vor langer Zeit geschlossen hatten, nach wie vor Gültigkeit habe – und er seinen abtrünnigen Helfershelfer wieder einzusetzen gedachte. \r\nDa es den Orcs nicht gelungen war, Azeroth zu erobern, wie es die Legion beabsichtigt hatte, war Kil’jaeden gezwungen, eine neue Armee aufzustellen, um Chaos in die Königreiche der Allianz zu bringen. Diese neue Armee durfte nicht in dieselben kleingeistigen Rivalitäten und Kämpfe untereinander verfallen, die die [[Horde]] geplagt hatten. Sie musste verbissen und gnadenlos nur das eine Ziel ihrer Mission verfolgen. Diesmal konnte sich Kil’jaeden keinen Misserfolg mehr leisten. Kil’jaeden hielt Ner’zhuls gequälte, hilflose Seele in Stasis, gab ihm aber eine letzte Chance, der Legion zu dienen oder aber ewige Folterqualen zu erdulden. Abermals ließ sich Ner’zhul unbedacht auf einen Pakt mit dem Dämon ein.\r\nNer’zhuls Seele wurde in einen eigens geschaffenen Block aus Eis von der Härte eines Diamanten befördert, das aus den entlegensten Regionen des „Sogs der Unterwelt“ herbeigeschafft worden war. In seinem tiefgefrorenen Sarg spürte Ner’zhul, wie sein Bewusstsein sich zehntausendfach ausdehnte. Von der chaotischen Kraft des Dämons verdorben, wurde Ner’zhul zu einem Astralwesen von unauslotbarer Macht. In diesem Augenblick verschwand der Orc namens Ner’zhul für immer, und der [[Lichkönig]] war geboren. Ner’zhuls loyales Gefolge aus [[Todesritter]]n und [[Hexenmeister]]n wurde ebenfalls von der Chaosenergie des Dämons verwandelt. Die bösen Magier wurden in Stücke gerissen und als skelettartige [[Lich]]s wiedergeboren. Der Dämon hatte dafür gesorgt, dass Ner’zhuls Anhänger ihm selbst im Tode treulich dienen würden. \r\nAls der richtige Zeitpunkt gekommen war, erläuterte Kil’jaeden geduldig die Mission, für die er den Lichkönig geschaffen hatte: Ner’zhul sollte eine [[Seuche]] von Tod und Schrecken über [[Azeroth]] bringen, die die menschliche Zivilisation für alle Zeiten ausrotten würde. Alle, die an der grauenhaften Seuche starben, würden als Untote wieder auferstehen ... und ihre Seelen sollten für alle Zeiten Ner’zhuls Willen unterworfen sein. Kil’jaeden versprach, wenn Ner’zhul seine Aufgabe meistern und die Menschheit vom Antlitz der Welt tilgen könnte, dann würde er den Fluch von ihm nehmen und ihm einen neuen, gesunden Körper geben. Obwohl Ner’zhul einwilligte und offenbar darauf brannte, seine Rolle zu spielen, hegte Kil’jaeden Zweifel an der Loyalität seines Handlangers. Dass er dem Lichkönig keinen Körper gab und ihn in dem Kristallsarg gefangen hielt, sicherte vorerst sein gutes Benehmen, doch der Dämon wusste, dass er stets wachsam sein musste und den Lichkönig nicht aus den Augen lassen durfte. Aus diesem Grund rief Kil’jaeden die Elitegarde seiner Dämonen herbei, die vampirischen [[Schreckenslord]]s, damit sie Ner’zhul bewachen und gewährleisten sollten, dass er seine grauenhafte Aufgabe erledigte. [[Tichondrius]], der mächtigste und verschlagenste unter den Schreckenslords, stellte sich der Herausforderung – ihn faszinierte das Ausmaß der Seuche und das beispiellose Potenzial zum Völkermord des Lichkönigs.",},
			["Killerschredder"] = { content = "'''Killerschredder''' ist eine der beiden Äxte von [[Rexxar]]. Er erbeutete sie von einem König der [[Meeresriesen]], als er auf den [[Scheiterhaufeninseln]] die Leuchtfeuer entzündete. Der Legende nach fand einst ein [[Nachtelf]] namens Dethorin seine Frau Allurana in den Armen eines anderen. Er ging ins [[Brachland]] und schrie seine Pein heraus. Wie zur Antwort glitzerte eine Axt im Sand. Dethorin nahm sie, machte kurzen Prozess mit seiner untreuen Gattin und ihrem Liebhaber und warf die Axt mit aller Kraft ins Meer. Wahrscheinlich fand der Meeresriese sie und kämpfte sich mit ihr zum König hoch.",},
			["Kilrogg Totauge"] = { content = "Kilrogg Totauge führte einen der größten und mächtigsten Klans an, aber jahrelange Bürgerkriege auf [[Draenor]] nach der Vernichtung der [[Draenei]] reduzierte ihre Anzahl drastisch. Kilrogg war sehr loyal gegenüber dem [[Schwarzfels Klan]], folgte diesem unbeirrt nach [[Azeroth]] und wurde dazu erwählt die Festung [[Sturmwind]] mit [[Cho'gall]] anzugreifen. Die Attacke war katastrophal und Kilrogg warf [[Cho'gall]] Inkompetenz vor. Kurz bevor die [[Horde]] wieder einem Bürgerkrieg nahe waren, unterdrückte [[Schwarzfaust der Zerstörer]] die Aufstände. Er galt als Kriegsherr, der erste seit dem Krieg gegen die [[Draenei]]. Totauge gehorchte [[Schwarzfaust der Zerstörer|Schwarzfaust]] loyal während dem ersten Krieg und sogar [[Orgrim Schicksalshammer]] im zweiten Krieg. Kilrogg zog mit seinem Klan nach [[Eisenschmiede]] in [[Khaz Modan]], die frühere Festung der [[Zwerge]] und [[Gnome]], und begann die Minenarbeiten dort zu überwachen. Er wurde von den Streitmächten von [[Azeroth]] verjagt als der Krieg zu seinem blutigem Ende kam, aber er floh bevor sie ihn gefangen nehmen konnten. In den Jahren nach dem zweiten Krieg wurden die Scouts von [[Alleria Windläufer]] angewiesen den [[Klan des Blutenden Auges]] zu jagen. Totauge wusste das er in [[Azeroth]] nicht sicher war, und kontaktierte [[Ner'zhul]], welcher ihm half durch den Riss in [[Burg Nethergarde|Nethergarde]] zu flüchten. Kilroggs Männer wurden als Helden betrachtet als er nach [[Draenor]] kam und er erzählte [[Ner'zhul]] alles was er über [[Azeroth]] wusste und verpfändete seinen Clan an [[Ner'zhul]] als dank für die Genemigung der Rückkehr seiner Truppen nach [[Draenor]]. Er verteilte die [[Goblins]], [[Trolle]], [[Drachen]] und [[Todesritter]] unter den anderen Clans. \r\n'''Quelle''':",},
			["Kin'weelay"] = { content = "Kin'weelay ist der mächtigste [[Hexendoktor]] der [[Trolle der Dunkelspeere]]. Er wurde in das [[Basislager von Grom'Gol]] ins [[Schlingendorntal]] geschickt, um [[Nimboya]] auf ihrer Suche nach [[Yenniku]] zu begleiten. Doch um den verlorenen [[Yenniku]] aus der Dunkelheit zurückzubringen, müssen sie das [[Gedankenauge]] finden, es [[Mai'Zoth]] abzunehmen und mittels der Magie von pulsierenden blauen Splittern ihrem Willen unterwerfen. Danach formt Kin'weelay das [[Gedankenauge]] in einen gefüllten Seelenedelstein um, den man zu [[Nimboya]] bringen muss.\r\nAber er hat auch seine eigenen Gründe, hier zu sein, denn er sucht den Schrifttafelsplitter einer alten Troll-Legende aus dem [[Finsteres Riff|finsteren Riff]], die die uralte [[Gri’lek der Wanderer|Geschichte von Gri'lek]] erzählt.\r\nMan kann seinem Stamm auch behilflich sein, indem man die Feinde jagt, die im Norden leben und ihre blutigen Knochenhalsketten als Beweis vorbringt: die [[Trolle der Blutskalpe]]. Und obwohl keine Dunkelspeere mehr im [[Schlingendorntal]] leben, sind sie auch immer noch dem Konflikt mit den [[Schädelspalter]]n verpflichtet und auf die Spaltknochenhalsketten dieser Stammesmitglieder hat Kin'weelay ebenfalls ein Kopfgeld ausgesetzt.",},
			["Kinderwoche"] = { content = "Einmal im Jahr, zur Zeit der Kinderwoche, erinnern sich die Streiter der [[Allianz]] und der [[Horde]] daran dass auch sie einmal jung waren und mit grossen Augen die sie umgebende Welt erforscht haben. Diese Woche nehmen sie zum Anlass sich für ein paar Stunden um ein Waisenkind zu kümmern und ihm ein paar sehnliche Wünsche zu erfüllen.\r\nDie Streiter der [[Allianz]] können dieser ehrenvollen Aufgabe in [[Sturmwind]], Anhänger der [[Horde]] in [[Orgrimmar]] nachkommen. Auch die Kinder im Waisenhaus von [[Shattrath]] freuen sich über die Aufmerksamkeit von ein paar Helden, die sie ein Stück ihres Weges begleiten.\r\nZum Dank erhält man ein kleines Haustier, das einen auf seinem weiteren Weg begleitet. Von der Schweinezucht über eine kleine Schildkröte, bis hin zu einer Ratte, die sicher in der [[Tiefenbahn]] gezähmt wurde!",},
			["Kirche des Lichts"] = { content = "* '''Aufenthaltsorte:''' Dort wo das Licht gebraucht wird. Am wahrscheinlichsten Sturmwind / Umland\r\n* '''Ziele/Aufgaben:''' Das Licht (als Religion) verbreiten, den armen und Schwachen helfen, neue Paladine ausbilden, GUTES TUN!\r\n* '''Verbündet mit:''' [[Scharlachrote Flamme]]\r\n* '''Wappenfarben:''' Weisser Grund, Goldener Rand, Goldene Krone.\r\n==Beschreibung==\r\nDie Kirche des Lichts ist ein Paladinorden, der sich zum Ziel gesetzt hat, das [[Licht]] zu verbreiten. Dabei haben sie drei Prinzipien: Ehre, Frömmigkeit, Eifer. \r\nEin [[Paladin]] der Kirche \r\n* betet inständig und oft. \r\n* sieht das Licht als Religion (nicht als personifizierbaren \"Gott\").\r\n* setzt sich zum Ziel, Gutes zu tun. \r\n* sieht das Glück der anderen als wichtiger als sein eigenes an. \r\n* versucht seine Ziele durch Worte durchzusetzen. \r\n* achtet nicht auf Hofierungen und Einschleimerei, betreibt selbiges auch nicht. \r\n* lebt so bescheiden wie möglich, um anderen ein gutes Leben zu ermöglichen. \r\n* kämpft nur, um das Leben anderer zu verteidigen. \r\n* möchte die Sünden aller auf sich nehmen, um dann auszuziehen und Buße für alle Wesen zu tun. \r\n* kann seine Kraft nur vom Licht erhalten und vertraut auf selbiges.\r\nDabei benutzt der Paladin keine Gewalt oder Überredungskunst, er zeigt den Leuten viel eher, was das Licht ihnen bringt, wenn sie Gutes tun. Wer sich nicht bekehren lassen will, muss das nicht. Es geht eher um den Aspekt Gutes zu tun.\r\n==Aktivitäten==\r\nIm selben Kontext bemüht sich die Kirche auch Messen des Lichts durchzuführen und bietet Beichten und die Möglichkeit sich bei einem der [[Paladin]]e auszusprechen an. Sie hilft auch auf Anfrage jedem Bürger, der Hilfe in irgendeiner Art und Weise benötigt. Sogar [[Hexenmeister|Hexern]], wenn sie gewillt sind, nicht absichtlich Böses zu tun.",},
			["Kirin'Var"] = { content = "==Allgemeines==\r\nKirin'Var ist ein Dorf im [[Nethersturm]] in der [[Scherbenwelt]].\r\nDie häufigste Todesursache im [[Nethersturm]] ist das Heer der Untoten in Kirin'Var. Die meisten Geister im Dorf sind nicht mehr als blasse Überbleibsel der [[Magier]] der [[Kirin Tor]], die sie einst waren. Sie erinnern sich nicht mehr an ihr früheres Dasein und streunen blind vor Wut um die Ruinen herum. Das war jedoch nicht immer so. Direkt nach dem Angriff waren die Geister zwar rastlos, aber nicht bösartig. Mit der Zeit sind sie jedoch immer aggressiver geworden. Der Lich [[Naberius]], der hinter den Veränderungen der Geister steht, hat seine Ziele mit Bedacht ausgewählt, und darauf geachtet, dass er zuerst die mächtigsten [[Magier]] erwischt. Die Magie, die eingesetzt wird, um die Geister der getöteten [[Kirin Tor]] zu beeinflussen, ist sehr mächtig. Die aggressivsten und gefährlichsten Geister stimmen mit den mächtigsten und hochrangigsten [[Kirin Tor]], die in dem Dorf gelebt haben, überein. Dagegen scheint er die Dorfleute und Händler übersehen zu haben. \r\nNachdem Prinz [[Kael'thas]]’ Streitkräfte unter Führung von [[Meister Daellis Morgenschlag]] das Dorf zerstört und den [[Erzmagier Vargoth]] im Turm eingesperrt hatten, haben sie sich zum [[Sonnenzornposten]] im Nordosten zurückgezogen. Bevor die [[Kirin Tor]] sich vor so vielen Jahren nach [[Azeroth]] aufgemacht haben, haben die [[Kirin Tor]] der Expedition ein mächtiges Artefakt anvertraut, das [[Siegel von Krasus]]. Es hat ihnen im Kampf gegen die [[Orcs]] große Dienste erwiesen. Auch [[Krasus Kompendium]] befand sich in ihrem Besitz. Drei Schutzrunen befinden sich entlang der Verteidigung der Zaubergasse und des Ratsplatz von Kirin’Var. Die [[Kirin Tor]] sind dabei, eine Verteidigung um das Dorf herum zu errichten, die mit der Energiequelle der [[Blutelfen]] gespeist wird.\r\n==Persönlichkeiten==\r\n* [[Bannzauberin Belmara]] (siehe auch: [[Belmaras Geschichtsbuch]])\r\n* [[Beschwörer Luminrath]] \r\n* [[Cohlien Frostwirker]] \r\n* [[Erzmagier Vargoth]]\r\n* [[Kampfmagier Dathric]] \r\n* [[Naberius]]\r\n* '''Hüter Dierwert''' ist ein Bewahrer von Kirin'Var. und ist auf der Suche nach Beweisen. Er möchte, dann man die Häuser auf dem Kapellenhof nach Hinweisen darauf durchsucht, wer sich hinter der Beeinflussung der Geister verbirgt. Er glaubt, dass dies ein weiterer teuflischer Plan von [[Kael'thas]] ist. Sie müssen herausfinden, was hinter der Wut der Geister steckt. \r\n* '''Lehrling Andrethan''' hat einen Schmiedehammer mitgenommen, um ein paar Hufeisen für das Pferd des alten Amorlin fertigzustellen, aber er kann ihn nicht finden. Er möchte, dass man den Geist von Rhonsus, dem Meisterschmied des Dorfes, vernichtet. \r\n* '''Thadell''' hat nach dem Angriff er die Felder und den Kapellenhof nach sein er Kuh Bessy abgesucht, aber er konnte sie nicht finden. Alles, was er von ihr noch hat, ist diese alte Kuhglocke. Normalerweise kommt sie gleich gerannt, wenn sie sie hört, aber vielleicht können diese alten Hände sie nicht stark genug läuten.\r\n* '''Zauberhexerleutnant Morran''' möchte den Sonnenzornposten anzünden, der unendlichen Invasion der Manakreaturen in Kirin’Var auf den Grund gehen und mittels der Schutzrunen von Kirin’Var eine Verteidigung errichten . \r\n===Kapellenhof===\r\nEine leuchtende Kugel liegt auf einem quadratischen Sockel. Auf den ersten Blick scheint sie ein Behältnis für magische Energie zu sein, doch es ist ein nekromantischer Fokus. Das merkwürdige magische Gerät ähnelt nichts, was man je zuvor gesehen hat. Es wurde mit Sicherheit nicht von [[Blutelfen]] hergestellt. Wenn die Geister sich näher an das Haus bewegen, beginnt die Kugel stärker zu leuchten, und wird wieder schwächer, als die Geister sich entfernen. Es steht außer Frage, dass sie mit der Beeinflussung der Geister in Verbindung steht.\r\n===Rathausplatz===\r\nIm Rathaus im Süden von Kirin'Var gibt es ein Stadtregister, in dem alle Einwohner eingetragen sind. Zuletzt hatte es [[Kampfmagier Dathric]] und sein Geist trägt es noch mit sich herum. Auf dem Ratsplatz befindet sich auch die Schmiede.\r\n===Violetter Turm===\r\nDer Violette Turm befindet sich in der Mitte von Kirin'Var, auf einer \"Insel\" im Süden von [[Area 52]]. Erzmagier Vargoth lebt darin. Mitglieder und Verbündete der [[Kirin Tor]] können weder hinein noch hinaus. [[Erzmagier Vargoth]]s Stab kann die Verteidigung des Turms durchbrechen, jedoch nur, wenn er von jemandem, der nicht zu den [[Kirin Tor]] gehört, aktiviert wird. Das Schutzschild verhindert, dass er die Macht, die es aufrecht erhält, ausspionieren kann. Als [[Kael'thas]] den Violetten Turm versiegelt hat, hat er einen arkanen [[Golem]] namens Ar'kelos auf dem Grund des Turms platziert. \r\nWenn man den violetten Turm betritt, wird der Fluch einen treffen. Kommandant Sarannis in der [[Botanika]] der [[Festung der Stürme]] ist die Schlüsselmeisterin und besitzt den Schlüssel zum Fluch des Turms. Sie ist eine von [[Kael'thas]] Beratern. Sie mag den Fluch vielleicht nicht selbst aufrechterhalten, aber sie hat den Schlüssel zum Schild. Der verfluchte Turm ist sowohl eine Zuflucht als auch ein Gefängnis für [[Erzmagier Vargoth]]. \r\n===Zaubergasse===\r\n[[Kael'thas]] Angriff auf Kirin'Var begann mit einem donnernden Geräusch und einem hellen Lichtblitz im Offiziersquartier im Nordwesten. Die Zerstörung war dort am größten. Nach dem Rückzug der [[Blutelfen]] geschah etwas Merkwürdiges. Wesen aus reinem Mana begannen, von überall her in das Dort zu strömen. Das schiere Ausmaß der Explosion der [[Manabombe]] muss einen Riss im [[Nether]] geöffnet und diesen Kreaturen einen Zugang zu dem Land verschafft haben. Nachdem die [[Blutelfen]] Kirin'Var dem Erdboden gleich gemacht hatten, haben sie mit dem Bau eines großen Gebäudes im Nordwesten begonnen. Die Anwesenheit der [[Blutelfen]] hat eine Flut von gefräßigen Manaelementaren entfesselt. Sie scheinen von den Ruinen der Zaubergasse angelockt zu werden und verursachen noch weitere Zerstörung.",},
			["Kirin Tor"] = { content = "==Allgemeines==\r\nDie Kirin Tor herrschten über das magische Reich [[Dalaran]] und hatte ihren Sitz in der Violetten Zitadelle von Cross Island. Der ehrwürdige Erzmagier [[Antonidas]], einer der mächtigsten Magier der Welt, stand diesem Rat von Zauberern vor. Die Mitglieder des Rates wurden im Geheimen bestimmt, und ihr Aufstieg war oft nur den engsten Vertrauten der Kirin Tor bekannt. Für die Wahl waren mehrere Kriterien von Bedeutung, ihre magischen Fähigkeiten waren nur eines dieser wichtigen Merkmale. \r\nDie Identität der Ratsmitglieder wurde verheimlicht, und in der Öffentlichkeit traten sie oft nur unter falschen Namen auf. Im Allgemeinen beugten sich die menschlichen Zauberer der Oberhoheit von Dalaran und der Kirin Tor. Sie fungierten als die Augen und Ohren des Rates in den entlegenen Königreichen. \r\nNachdem sich die Seuche des Untodes bis zu den Grenzen Lordaerons ausgebreitet hatte, wurde auch Dalaran von den untoten Kriegern der [[Geißel]] angegriffen. Erzmagier [[Antonidas]] wurde getötet, als Prinz [[Arthas]] die magischen Barrieren durchbrach, die jeden Untoten vernichten sollten. Die meisten Ratsmitglieder kamen um, als der mächtige Dämonenlord [[Archimonde]] wenig später die Stadt zerstörte.\r\n==Renegaten==\r\nDie abtrünnigen Magier, die auf sich allein gestellt die Geheimnisse der Magie erforschten, wurden als '''Renegaten''' betrachtet. Sie strebten oft danach, ihr Wissen über die Grenzen dessen hinaus zu erweitern, was die Kirin Tor für sicher oder moralisch akzeptabel hielt. \r\n==Rat von Dalaran==\r\nDer '''Rat von Dalaran''' bildete während des zweiten Krieges eine starke Stütze der [[Allianz]] von [[Lordaeron]]. Auch als das Bündnis zerfiel, sicherte die Kirin Tor König [[Terenas]] seine unerschütterliche Unterstützung zu. \r\n==Einstellung==\r\nDie Kirin Tor heißen Zerstörung im Allgemeinen nicht gut, aber um den Feind zu vernichten überwinden sie jeden Skrupel. Sogar im Tod.\r\n==Ältestenrat der Kirin Tor==\r\nDie Ältesten waren in ihre dunklen Umhänge gekleidet, die nicht nur das Gesicht, sondern auch die Form bedeckten. Obwohl Männer und Frauen unter ihnen waren, war das einzige Zeichen der Unterscheidung, wann immer einer von ihnen sprach, da sein dann Gesicht teilweise sichtbar wurde, wenn auch ein wenig undeutlich im Detail. \r\nDie Führer der Kirin Tor wurden anhand mehrerer Mittel auserwählt, [[Magie]] aber war eines davon. Nichts brachte einen Zauberer in den Kirin Tor schneller voran als sein Ruf, obwohl keiner des Ältesten Konzils jemals diesen grundlegenden Fakt zugeben würde. Die Meister von [[Dalaran]] wurden im Geheimen gewählt, von ihrem Aufstieg wußten nur ihre Gefährten, nicht einmal ihre Geliebten.",},
			["Kirrik der Erwachte"] = { content = "Der [[Arakkoa]] Gelehrte Kirrik der Erwachte kam ursprünglich aus der Hauptkolonie der [[Arakkoa]] in [[Skettis]]. Er war an dem Verrat an [[Terokk]] beteiligt und erkannte in Terokk einen Scharlatan und keinen Propheten. Es war Kirrik, der vom Licht der [[Naaru]] berührt wurde und die Arakkoa mutig aus Skettis herausgeführt hat. Nach ihrer Pilgerreise nach [[Shattrath]] ging Kirrik in alle anderen Kolonien, um nach Gleichgesinnten zu suchen. Derzeit findet man ihn in der [[Knochenwüste]] der [[Wälder von Terokkar]] bei der [[Flüchtlingskarawane]].",},
			["Kirtonos der Herold"] = { content = "'''Kirtonos der Herold''' ist ein mächtiger [[Gargoyle]] in der [[Scholomance]]. Er ist der Meister von [[Doktor Theolen Krastinov]] und bevor man ihm gegenübertritt, muss man sich zuerst eine Methode besorgen, mit der man ihn beschwören kann. Dazu benötigt man das [[Blut Unschuldiger]], das reinste Blut... damit wird Krastinovs Meister besänftigt. Dieses muss man auf der Veranda in die Kohlenpfanne legen. Dann wird Kirtonos kommen, um sich von Eurer Seele zu nähren. Auf die Veranda gelangt man über die Kammer der Beschwörung.",},
			["Klageessenz"] = { content = "'''Klageessenz''' ist eine Substanz, die sich in [[Brühschlammer|Ektoplasmakreaturen]] in den [[Höhlen des Wehklagens]] anreichert. Man glaubt, dass sie die Ursache für die seltsamen Pflanzen und Tiere im Brachland ist.",},
			["Klanwacht"] = { content = "Die '''Klanwacht''' befindet sich im Süden von [[Nagrand]]. Dort findet man Jagdgesellschaften der [[Oger der Felsfäuste]], die Vorboten für einen Angriff auf [[Telaar]] sind. Gegenüber der Klanwacht befindet sich [[Wazdaz]], der umbedingt das geheimnisvolle Ei aus dem Nest in dem nahe gelegenen Baum stehlen möchte. Dazu hat er einen [[Spring-o-Mat 4000]] aufgestellt, doch schlechte Sprünge können in körperlichen Schäden oder dauerhaften schweren Wunden resultieren.",},
			["Klan der Zerschmetterten Hand"] = { content = "Die '''Zerschmetterte Hand''' bildet den Nachwuchs der [[Schurke]]n der [[Horde]] aus. \r\nSchatten gibt es selbst auf den höchsten Zinnen von Orgrimmar - dort muss sich etwas verbergen - und die Zerschmetterte Hand übernimmt diese Rolle freiwillig. Thrall stimmt trotz seines gütigen Herzens darin zu, dass die Hand notwenig ist, um die Sicherheit von Orcs und Trollen zu gewährleisten. \r\nDie Mitglieder der Zerschmetterten Hand denken, die Methoden des Kriegshäuptlings [[Thrall]] sind zu zimperlich. Thrall wagt nicht, die Macht der [[Horde]] zu entfesseln. Einst waren sie stärker, allesamt mächtige Eroberer. Diesen Stolz müssen sie zurückerlangen, und der Klan der Zerschmetterten Hand wird dies bewerkstelligen. Sie sammeln Kraft aus den Schatten und schlagen im Verborgenen gegen exponierte Feinde zu. Als ein Schurke der Zerschmetterten Hand muss man unbedingt den geheimen Gruß erlernen. Dies ist die einzige Methode, mit der man ein anderes Mitglied der Hand zweifelsfrei identifizieren kann. Die Zerschmetterte Hand in Orgrimmar kann Schurken zu Geheimnissen führen: z.B. der Kunst, tödliche Gifte zu brauen.\r\n==Geschichte==\r\nWie viele andere Stämme, die auf [[Draenor]] zurückgeblieben waren, wartete auch der Klan der Zerschmetterten Hand nur auf die Gelegenheit, die unbedachten [[Menschen]] der Welt [[Azeroth]] in einen verlustreichen Kampf zu verwickeln. Durch seine umbarmherzige Taktik und Zielstrebigkeit war [[Kargath Messerfaust]] zum Häuptling des allseits gefürchteten Klans aufgestiegen. \r\nDie Stammesmitglieder übten die Rituale der Selbstverstümmelung aus, um den Klan gegenüber ihre Loyalität zu beweisen. [[Orcs]], die in den Rang eines Kriegers erhoben wurden, ließen sich die linke Hand brechen oder sogar abschlagen. Die fehlende Hand ersetzten sie oftmals durch eine grobe Waffe oder einen Werkzeug. \r\nAls die Truppen der [[Allianz]] durch das [[Dunkle Portal]] in [[Draenor]] einmarschierten, lieferte sich der Klan der Zerschmetterten Hand zahlreiche Gefechte mit den [[Menschen]]. Doch der Schamane [[Ner'zhul]] ließ sich nicht an der Umsetzung seiner perfiden Pläne hindern und öffnete Portale zu anderen Welten. Die gewaltigen Energien dieser widernatürlichen Pforten zerstörten die sterbende Welt in einer Explosion apokalyptischen Ausmaßes. Einige Stämme konnten zwar entkommen, aber der Klan der Zerschmetterten Hand ging zum Großteil mit seiner Heimatwelt unter.\r\n===Neuanfang bei der Horde===\r\nEinige Mitglieder des Klans waren zusammen auf [[Azeroth]] gestrandet. Sie verbündeten sich später mit Thrall und bilden nun die führende [[Schurke]]n-Organisation der neuen Horde.\r\n==Persönlichkeiten==\r\n* '''Kriegshäuptling [[Kargath Messerfaust]]'''\r\n* '''Shenthul''' – Anführer der Zerschmetterten Hand\r\n* '''Therzok'''\r\n* '''Zando'zan''' - Zando'zan ist der Ansprechpartner, um eine Ausbildung als Agent der Zerschmetterten Hand zu beginnen. \"Zando'zan hat es gesehen. Ja, der Tag wird kommen. Thralls Tod... der Dolch in seinem Rücken, das Gift, das durch seine Adern fließt... Zando'zan hat schon zu viel gesagt.\"\r\n* '''Zuchtmeister Fitzel''' – Undercover-Agent bei der Venture Co. im Schlickermoor im Brachland. Fitzel greift jede Person, die er nicht erkennt, an und eliminiert sie.",},
			["Klan des Blutenden Auges"] = { content = "#REDIRECT [[Blutaugenklan]]", redirect = "Blutaugenklan",},
			["Klan des Lachenden Schädels"] = { content = "#REDIRECT [[Orcs des Lachenden Schädels]]", redirect = "Orcs des Lachenden Schädels",},
			["Klauendruide"] = { content = "#REDIRECT [[Druide der Klaue]]", redirect = "Druide der Klaue",},
			["Klauenkönig Ikiss"] = { content = "'''Klauenkönig Ikiss''' ist einer der Anführer der Sethekk. Zusammen mit [[Dunkelwirker Syth]] hat er den Auszug der [[Arakkoa]] der Sethekk-Kolonie aus [[Skettis]] zu den Ruinen von [[Auchindoun]] angeführt. Zu Anfang war Ikiss ein sehr charismatischer Führer, aber er ist dem Wahnsinn verfallen. Nun gibt er öffentlich bekannt, dass [[Terokk]] wiedergeboren wurde. Er denkt wirklich, dass die [[Arakkoa]] sich ihm als Führer unterwerfen. Ikiss trug [[Terokks Federkiel]] als Zeichen seiner Autorität mit sich herum. Vermutlich hat er ihn noch bei sich, um seine Anhänger zu überzeugen, dass er die Wiedergeburt [[Terokk]]s ist.",},
			["Kleriker"] = { content = "#REDIRECT [[Menschenpriester]]", redirect = "Menschenpriester",},
			["Kleriker von Nordhain"] = { content = "Die '''Kleriker von Nordhain''' waren menschliche [[Priester]], die dem Königreich [[Sturmwind]] während des [[Der Erste Krieg|Ersten Krieges]] dienten. Dieser Orden wurde weitgehend zerstört und im [[Der Zweite Krieg|Zweiten Krieg]] wurden fragile [[Priester]] auf dem Schlachtfeld durch gepanzerte [[Paladine]] ersetzt. Es folgte die Wiedereinnahme von [[Sturmwind]] und [[Erzbischof Alonsus Faol]] konnte den Heiligen Orden von [[Nordhain]] erneut zu gründen. Zusätzlich zum Wiederaufbau der [[Abtei von Nordhain]], wurde die Kathedrale des Lichtes in [[Sturmwind]] gebaut, um als Zentrum für die [[Kirche des Lichtes]] zu dienen. Viele [[Zwergen Priester]] folgen den selben Traditionen wie die Menschlichen [[Priester]] von [[Sturmwind]]. Im Brennenden Kreuzzug folgen die [[Draenei]] ebenso dem Heiligen Licht, weil 25,000 Jahre zuvor ihre Vorfahren damit gesegnet wurden.",},
			["Klingenhügel"] = { content = "Das Dorf Klingenhügel liegt im Norden des [[Tal der Prüfungen|Tals der Prüfungen]] in [[Durotar]]. Als die [[Orcs]] ankamen, war ein Großteil des Landes im Besitz der [[Stacheleber der Grimmhauer]], die sich als ein ziemlicher Dorn im Auge erwiesen. Durch ihre Anstrengungen konnten die Orcs einen großen Teil von ihnen vertreiben, aber es gibt doch noch welche, die sich in einigen Gebieten verschanzt haben.\r\n==Personen==\r\n* '''Furl Hohnbraue''' befindet sich im Wachturm von Klingenhügel. Das Alter hat ihn nutzlos für die Schlacht gemacht. Jetzt macht er sich auf andere Weise nützlich. Von diesem Aussichtspunkt aus achtet er auf Eindringlinge. Während ihre Kraft hier zunimmt, muss er sein Signalhorn immer seltener benutzen. Um sich die Zeit zu vertreiben, fertigt er Dinge an, die den jüngeren und fähigeren Kriegern bei der Verteidigung ihrer Heimat helfen können. \r\n* '''Gar’Thok''' ist der Kommandant von Klingenhügel. \r\n* '''Kron Tor’kren''' ist der Sohn von Misha Tor’kren auf dem Bauernhof nordwestlich von Klingenhügel. Kron ist vor Tagen auf die Jagd gegangen und immer noch nicht zurück. Er wollte nach Westen in Richtung des [[Brachland]]es, um dort am Ufer des Südstroms Krokilisken zu jagen. So stark wie er ist, hat ihn sein starrköpfiger Stolz doch immer wieder in Schwierigkeiten gebracht. Seine Mutter hatte ihn gewarnt, dass die Krokilisken mächtig und heimtückisch sind. Er wurde wütend und stürmte davon.\r\n* '''Misha Tor’kren''' lebt auf einem Bauernhof nordwestlich von Klingenhügel und ist die Mutter von Kron Tor’kren. \r\n* '''Orgnil Narbenseele''' ist in Klingenhügel stationiert und bewacht Durotar vor solch Bösem wie der [[Brennende Klinge|Brennenden Klinge]]. Er hat Nachforschungen unternommen und herausgefunden, dass ein [[Hexenmeister]] der [[Brennende Klinge|Brennenden Klinge]], der [[Goblin]] Zischel Düstersturm, nahe dem Donnergrat im Nordwesten kampiert. \r\n* '''Takrin Pfadsucher''' ist ein Freund von Kargal Schlachtnarbe im Fernwacht-Posten im Brachland. \r\n* '''Torka''' ist Koch und hätte beinahe vergessen, Frühstück zu machen. Er braucht mindestens drei Schwanzpeitschereier, wenn er genug für die morgige Mahlzeit haben möchte.",},
			["Klingenklaue der Metzger"] = { content = "'''Klingenklaue der Metzger''' ist ein [[Worgen]] in [[Burg Schattenfang]], der sich dort im Küchenbereich niedergelassen hat. Er verfügt über keine besonderen Fähigkeiten. Als Beute sind sowohl seine , als auch seine beiden \"Werkzeuge\", der und das , beliebt.",},
			["Klingenmeister"] = { content = "Die kampferprobten orcischen Klingenmeister sind nur wenige an der Zahl, dennoch bilden sie eine Elitetruppe innerhalb der [[Horde]]. Als geschickte Schwertkämpfer gehörten sie einst dem todgeweihten [[Orcs der Brennenden Klinge|Klan der Brennenden Klinge]] an, der sich im Banne dämonischer Verderbnis selbst zerstörte. Als ihr Klan in alle Winde zerstreut war, legten die stolzen Klingenmeister den feierlichen Eid ab, sich und ihre Brüder endgültig und unwiderruflich aus der Herrschaft der [[Dämonen]] zu befreien. Unter [[Thrall]]s Kommando haben sich die Klingenmeister wieder der [[Horde]] angeschlossen und fungieren als Leibwache des jungen Kriegshäuptlings. \r\nKlingenmeister sind Meister der Verstohlenheit und Arglist, schätzen die Ehre des Einzelnen jedoch mehr als alles andere. Indem sie ihre Kriegerenergien bündeln, können Klingenmeister lebende Wirbelstürme purer Kampfeswut werden. Sie schwingen ihre großen Klingen schneller als das Auge sehen kann und können so gleichzeitig bei allen feindlichen Truppen in ihrer Umgebung Schaden anrichten. Wenn Klingenmeister ihre enormen Kräfte zu einem Schlag bündeln, können sie bei ihren Feinden noch größeren Schaden anrichten. Zu den eher mystischen Fähigkeiten der Klingenmeister gehört, dass sie Gerüchten zufolge Phantombilder ihrer selbst erzeugen können. Man sagt ebenso, die Klingenmeister seien so agil und wendig, dass sie sich so schnell bewegen können, dass sie für das bloße Auge unsichtbar werden.\r\n==Persönlichkeiten==\r\nZu den berühmtesten Klingenmeistern zählte:\r\n* [[Grom Höllschrei]]\r\n* [[Jubei'thos]]\r\n* [[Lantresor von der Klinge]]\r\n* [[Vazruden der Herold]]",},
			["Klippengänger"] = { content = "=== Klippengänger===\r\n* [[Azshara]]. \r\nDie uralten Klippenriesen aus dem südlichen [[Azshara]] hinterlassen, bedingt durch ihre Ernährung, einen höchst formbarer und extrem starker Kristall, der als Azsharit bekannt ist. Der südliche Bogen ist übersät mit diesen Gebilden, aber es konnten nur wenige geborgen werden wegen der extrem gewaltsamen Natur der Riesen. Azsharit wird für die Schöpfung von mächtigen Waffenkörpern benötigt.",},
			["Klippenquellfälle"] = { content = "Die Klippenquellfälle in [[Dunkelküste]] dienen als wichtigste Trinkwasserquelle in der Region, doch der Klippenquell wird immer verderbter. Er mündet in die [[Küste des Nebelrandes]] und man fürchte, dass sich das verunreinigte Wasser bald auf [[Auberdine]] auswirken wird. Man fürchtet, dass es die primäre Ursache eines Gifts ist, das der dortigen Fauna schadet, besonders dem Wild. Inzwischen hausen gefährliche [[Naga]] in einer Höhle bei den Wasserfällen und die altehrwürdigen verbündeten [[Urtume]] der [[Nachtelfen]] spüren, dass die Höhle ein Versteck für etwas Neues, Böses in [[Dunkelküste]] ist.",},
			["Knarz Düsterpfote"] = { content = "\"Das ist zugegeben das hässlichste Ding das ich je gesehen habe\" \r\nMorg schnalzte anerkennend mit der Zunge. \r\n\"Allein diese Ohren, das eine scheint kürzer zu sein.Irgendwie falsch meinst du das wächst noch?\" \r\nSeine grossen Braunen Augen tasteten das kleine Bündel ab ,auf der Suche nach weiteren kuriösitäten die seinen Spott herausfordern. \r\n\"Was zum Bräggel? Sein Schweif ist jawohl ein Witz oder?\" \r\nEr verfiel in schrilles ,glucksendes gekicher. Ein äusserst unangenehmer und nervtötender Ton der entfernte ähnlichkeit mit einer rostigen Säge hat. \r\n\"Wie nennt man sowas? Ich meine *grunz* wie willst du diese kleine Missgeburt nennen?\" Morgs Ohren legten sich etwas an als warte er auf einen besonders unmöglichen Namen über den er sich lustig machen konnte. \r\n\"Ich werde ihn Knarz nennen\" Sagte Marao und lächelt, ein Mensch hätte es für ein Zähne fletschen gehalten das bestenfalls eine Warnung vor dem tödlichen Biss war. \r\n\"Knarz?\" Morg legt den Kopf schief und sah sie aus listigen Augen an. \r\n\"Das ist ein guter Name für einen Gnoll.\" \r\n----------------------------------------------------------------------------------------------------- \r\nKnarz Düsterpfote: \r\nGrösse: 1.65 \r\nGewicht: 63 kg (wobei Er beschwört das dies an seiner Keule liegt,die sei schliesslich aus Blei und überhaupt wozu müsste man wissen wie schwer ein Gnoll ist? Das ist doch alles Unsinn) \r\nAugenfarbe: Schiefergrau \r\nFellfarbe: Prächtiges Schwarz mit einigen Weißen Tupfern ( Schwarz ist selten bei Gnollen deshalb war er auf diese Farbe immer unverhohlen Stolz) \r\nBesonderheiten: Linken Ohr etwas kürzer als das Rechte (liegt am Blickwinkel) Schweif mit erbärmlich wenig Haaren gesegnet (liegt am Essen,würde sich ändern wenn er weniger Spinnen verdrücken würde) \r\n--------------------------------------------------------------------------------------------------------- \r\n\"WAS ZUM BRÄGGEL!?\" Das Geschoß fetzte Gnurz von den kurzen Beinen, schleuderte ihn einige Meter durch die Luft und hämmerte ihn dann gegen einen massiven Baum wo er ,mit einem dämlichen Gesichtsausdruck, sein Leben aushauchte. \r\nKnarz kratzte sich am Nacken und betrachtet die Überreste von Gnurz einen moment nachdenklich, bevor er geschwind zu diesen herüber eilte ,einen Brocken Fleisch aus Gnurz flanke riss und sich dieses lieblos in das Maul warf. Knarz hatte sich immer schwer damit getan Freunde zu essen, besonders wenn es ihm nicht möglich war sie wenigstens zu würzen. Knarz tänzelte wieder hinter seine Deckung und spannte seine Armbrust, legte einen Pfeil auf die Sehne und spähte auf die vor ihm liegende Lichtung. Er kniff seine Augen zusammen und versuchte gegen die Sonne etwas zu erkennen, neben ihm fingen zwei Gnolle an zu kichern. Knarz rollte mit den Augen, er war immer der Meinung gewessen das Spaß und Arbeit getrennt werden sollten. \r\n\"Schnauze ihr Bekloppten oder wollt ihr die Aufmerksamkeit auf euch richten mit diesem vergräbbelten Geki......\" \r\nDie zwei Gnolle in lockeren Kettenhemden sahen ungläubig zu Knarz, schauten danach einander an und begannen aus tiefster Kehle glucksend wie kleine Kinder zu lachen. \r\n\"Du bist schon ne Nummer Knarz\" rief der eine herrüber während er ohne hinzusehen einen Pfeil in die makellosigkeit der Lichtung schoß. \r\n\"Ne Nummer!\" gackerte der andere nach wobei seine Zunge herum wedelte wie ein toter Lurch. \r\nKnarz seufzte ,die üblichen Verwünschungen und Flüche verliessen seine Lippen. Er wandte sich nochmal zu den Beiden um ihnen zu erklären warum es wichtig ist das der Feind nicht weiss wo man sich versteckt, das sei schliesslich der Sinn eines Hinterhalts..Grade als er diesen Gedanke ausdrücken wollte flog in einer graden Linie ein gewaltiger Feuerball in Richtung der beiden Gnolle. Beide umklammerten sich in Panik und fingen an wie kleine Weiber zu kreischen. \r\n\"Ihr seid echt selbst Schuld.\"informierte Knarz die beiden zukünftig verstorbenen. \r\nDen Bruchteil einer Sekunde bevor der Feuerball die beiden Gnolle in einen haufen Asche in dem einige Zähne lagen verwandelte, sahen sie Knarz noch mit einem schuldbewussten Blick an, danach war die Luft erfüllt vom Geruch nach verbranntem Fell und brutzelnden Fleisch. \r\nKnarz legte an ,zielte und schoß seinen Pfeil ab. \r\nDieser verliess die Armbrust ,hinweg über den Baumstumpf der Knarz schützte, danach über das Gras der Lichtung das unter dem Wind Hauch tanze und schliesslich exakt in die Stirn des Magus der sich auf einem Felsen postiert hatte um so den Waldrand besser überblicken zukönnen. \r\nDer Magus schaute beinahe ungläubig in Richtung des Pfeiles der ihm aus der Stirn ragte, bevor er nach hinten umkippend noch eine Kaskade von zischenden lichtblitzen aus den Fingern schoß. Knarz schmatzte und kratzte sich einige Minuten geistesabwessend am hintern. \r\n\"wasauchimmer\" Knarz schlenderte zurück ins Lager ,aber nicht ohne sich noch ein kleines Stückchen von Gnurz zu genehmigen.",},
			["Knochengolem"] = { content = "'''Knochengolems''' sind Begleiter der [[Nekromant]]en in [[Scholomance]]. Es bedarf viel Macht, sie zu kontrollieren.Sie kämpfen mit den Klingen an ihren Händen, mit denen sie jede Rüstung durchschlagen.\r\n==Persönlichkeiten==\r\n* [[Blutrippe]]",},
			["Knochenhof"] = { content = "Der '''Knochenhof''' ist ein Gebäude der [[Geißel]]. Es ist die Heimat der [[Frostwyrm]]s, einst prachtvolle Drachen, von denen heute nur noch Skelette existieren und die von der dunklen Magie der Geißel in diesen Gebäuden manipuliert werden, damit sie dem [[Lichkönig]] dienen. [[Frostwyrm]]s besitzen die verderbliche Eigenschaft, dass sie feindliche Truppen und Gebäude mit ihrem eisigen Atem anhauchen können. In großer Zahl sind die Frostwyrms eine wahrhaft übermächtige Kraft.\r\n'''Quelle:''' [[Warcraft III - Reign of Chaos]]",},
			["Knochenmalmer Klan"] = { content = "#REDIRECT [[Orcs der Knochenmalmer]]", redirect = "Orcs der Knochenmalmer",},
			["Knochenpeitscher"] = { content = "Die '''Knochenpeitscher''' leben in der Knochenwüste in den [[Wäldern von Terokkar]] und gehören zu den [[Aasvögel]]n. Allianz und Horde haben ein Kopfgeld auf die Knochenpeitscher ausgesetzt, denn sie gelten als Überträger der Pest.",},
			["Knochenwurm"] = { content = "'''Knochenwürmer''' leben unterirdisch in der [[Knochenwüste]] in den [[Wäldern von Terokkar]]. Viele Kadaver in der Wüste stammen von Wurmkindern, doch da draußen gibt es irgendwo noch einen großen Knochenwurm. Wenn man ihm das richtige Futter anbietet, kann man ihn sicher hervorlocken.",},
			["Knochenwürmer"] = { content = "#REDIRECT [[Knochenwurm]]", redirect = "Knochenwurm",},
			["Knochenwüste"] = { content = "Die verderbte Magie, die in [[Auchindoun]] entfesselt wurde, hat dieses Land im Gebiet der [[Wälder von Terokkar]] in diese Wüste verwandelt, die man nun hier überall sehen kann. Viele Geister der [[Draenei]] wurden von der Explosion verderbt und wandeln nun voller Pein in der Wüste. Die Knochen der [[Draenei]], die bei der Explosion von [[Auchindoun]] gestorben sind, sind überall in der Knochenwüste verstreut. Viele ihrer Geister sind daher ruhelos und können nicht ins nächste Leben übertreten. Auch hausen hier die diebischen [[Sandgnom]]e.\r\n===Aashügel===\r\nDer Aashügel liegt im Norden der Knochenwüste und wird von Knochenpeitschern bevölkert. Diese Aasvögel sind in der gesamten Knochenwüste vertreten, doch ihre größte Ansammlung aber ist bekanntermaßen hier anzutreffen.",},
			["Knochen von Grakkarond"] = { content = "Die '''Knochen von Grakkarond''' liegen südlich von [[Burg Cenarius]] in [[Silithus]]. [[Grakkarond]] war ein gewaltiger Bronzener Drache und einer der Anführer im [[Krieg der Sandstürme]]. Während eines Gefechtes zielte [[Ossirian]] der Narbenlose auf Grakkarond, und schleuderte sein Obsidianschwert durch eine seiner Schwingen. Der angeschlagene [[Drache]] fiel vom Himmel und zermalmte bei seinem Aufschlag die [[Qiraji]] mit seinem massigen Körper. Grakkarond zerfetzte [[Ossirian]] fast zu Tode, doch starb schließlich unter dem Ansturm der anderen [[Anubisath]]s und [[Qiraji]]. \r\n==Glyphenverziertes Kristallprisma==\r\nDas Glyphenverzierte Kristallprisma, welches [[Geologin Lerchenbann]] auf [[Burg Cenarius]] entschlüsseln konnte, zeigt einen Abgesandten der [[Qiraji]], wie er sich mit drei [[Silithiden]], vor den Knochen eines großen [[Drachen]], trifft. Über den Glyphen steht eine Art Kode. Dieser Kode ist der Schlüssel zur Beschwörung des [[Abgesandter Roman'khan|Abgesandten Roman'khan]]. Dazu muss man den Glyphenkode der [[Silithiden]] vor den Knochen von Grakkarond in den Sand schreiben.\r\n==Personen==\r\n* [[Abgesandter Roman'khan]]",},
			["Kobold"] = { content = "#REDIRECT [[Kobolde]]", redirect = "Kobolde",},
			["Kobolde"] = { content = "Kobolde sind verschrumpelte, rattenähnliche Humanoide, jedoch von Natur aus ein scheunes und friedsames Volk, das in den tiefen Höhlen des [[Rotkammgebirge]]s und [[Alterac]] haust. Sie haben eine Vorliebe fürs Graben und sind bekannt für ihre unterirdischen Tunnel. Kobolde besitzen nur eine begrenzte Intelligenz und halten sich meist von besiedelten Gebieten fern, wo andere, größere Völker leben. Sie können aber über sich selbst hinauswachsen, wenn sie in eine Ecke gedrängt werden.\r\nIm [[Rotkammgebirge]] wurden sie vor kurzem von den [[Gnolle der Flusspfoten|Gnollen der Flußpfoten]] versklavt und in eine Existenz unermüdlicher Plackerei gezwungen. Seit ihrer Unterwerfung sind die eigentlich sanftmütigen Kobolde verbittert und gehen aggressiv gegen jeden vor, der sich in ihre unaufhörliche Arbeit einmischt.\r\n==Bekannte Klans==\r\n* [[Kobolde der Bruchschnauzen]]\r\n* [[Kobolde der Tunnelratten]]\r\n* [[Kobolde von Elwynn]]\r\n* [[Kobolde von Nordhain]]",},
			["Kobolde von Elwynn"] = { content = "==Du nicht nehmen Kerze!==\r\nDie [[Kobolde]] von Elwynn halten sich in der [[Tiefenschachtmine]] im Süden und im Bereich der Jaspismine im Nordosten des [[Wald von Elwynn]] auf. Ihr Anführer Goldzahn ist ein großer Kobold mit einem Goldzahn in der [[Tiefenschachtmine]]. Er hat Berenices Halskette aufgehoben und ist in die Mine gerannt. Wenn man diesen Kobold findet, dann findet man auch die Halskette.",},
			["Kodo"] = { content = "Die riesigen, behäbigen Kodos stellen eine der faszinierendsten Gattungen von [[Kalimdor]] dar. Diese mächtigen Bestien sind zwar von Natur aus sanft und gemütlich, werden jedoch zu erbitterten Gegnern, wenn sie bedroht oder angegriffen werden. Wenn sie gereizt werden, verschlingen Kodos ihre Feinde mit einem einzigen Biss. Viele Kodos sind eng mit dem gütigen Volk der [[Tauren]] verbunden und es heißt, dass einige wenige Kodos sich auch den Geistern von Himmel und Sturm verbunden fühlten. Daher existieren bei den [[Tauren]] Legenden über jene, die sie Blitzechsen,[[Salamander]], [[Donnerechsen]] und Sturmgänger nennen, doch niemand weiß jedoch, ob diese Giganten tatsächlich übernatürliche Kräfte besitzen oder nicht. Kodos, mit denen man fertig wird, streifen durch [[Mulgore]] und den nördlichen Teil des [[Brachland]]es. \r\n==Kodos als Reittiere==\r\nDie riesigen Kodobestien der Ebenen von [[Kalimdor]] sind geschätzte Verbündete der [[Orcs]] und [[Tauren]] und wurden durch schamanistische Beeinflussung in die Reihen der [[Horde]] aufgenommen, gezähmt und ausgebildet. Diese gewaltigen Bestien hatten die Aufgabe, die hallenden Kriegstrommeln der [[Orcs]] in die Schlacht zu tragen. Sie sind Symbole für Macht und Tapferkeit der Orcs und nutzen ihre enorme Größe und Stärke, um feindliche Streitkräfte zu vertreiben. Der aufpeitschende Rhythmus der Kriegstrommeln spornt die Krieger der Orc-Horde an, sodass sie mit größerer Stärke und Verbissenheit kämpfen. \r\nNur ein einziges Geschöpf in ganz Kalimdor besitzt die nötige Stärke und Ausdauer, um einen Tauren auf seinem Rücken tragen zu können: Die majestätischen Kodos. Ähnlich wie ihre Reiter sind auch die Reittiere der Tauren sanfte Riesen, allerdings sind sie nicht so groß wie ihre wahrhaft gigantischen Verwandten, die frei über die weiten Ebenen des Brachlandes ziehen. Dafür sind die kleineren Kodos schneller und gewandter als die wilden Kodos von Kalimdor. Man sagt, dass ein Kodo seinen Reiter wählt, und nicht umgekehrt. Die stolzen Tiere würden niemals einen Reiter akzeptieren, der keine Ehre und kein reines Herz hat. Im[[Dorf der Bluthufe]] in [[Mulgore]] kann man solche reitbaren Kodos erwerben.\r\n* '''Brauner Kodo''' - Benötigt: Stufe 40. Tempo um 60% erhöht. Kosten: 10g\r\n* '''Grauer Kodo''' - Benötigt: Stufe 40. Tempo um 60% erhöht. Kosten: 10g\r\n* '''Grüner Kodo''' - Benötigt: Stufe 40. Tempo um 60% erhöht. Kosten: 10g\r\n* '''Großer brauner Kodo''' - Benötigt: Stufe 60. Tempo um 100% erhöht. Kosten: 100g\r\n* '''Großer grauer Kodo''' - Benötigt: Stufe 60. Tempo um 100% erhöht. Kosten: 100g\r\n* '''Großer weißer Kodo''' - Benötigt: Stufe 60. Tempo um 100% erhöht. Kosten: 100g\r\n* '''Schwarzer Kriegskodo''' - PVP-Reittier. Erhältlich für: Horde. Benötigt: Stufe 60, Geübter Reiter (150). Das Kriegsreittier kostet je 30 Abzeichen vom [[Alteractal]]s, [[Kriegshymnenschlucht]] und vom [[Arathibecken]]. \r\n* '''Großer Braufestkodo''' - Benötigt: Stufe 60. Reiten 150. Gefunden bei [[Coren Düsterbräu]] in den [[Schwarzfelstiefen]] während des [[Braufest]]es.\r\n==Bekannte Tiere==\r\n* '''Arra'chea''' - Unten in [[Mulgore]] gibt es einen mächtigen Kodo namens Arra'chea.\r\n* '''Brontus''' - Den mächtigen Kodo Brontus kann man mit viel Glück im [[Brachland]] zu Gesicht bekommen.\r\n* [[Lakota'mani]]",},
			["Kodofriedhof"] = { content = "Dieser Friedhof ist sicherlich einer der bemerkenswertesten Orte in ganz [[Kalimdor]], wenn ein Kodo langsam alt wird und bald sterben muss, dann macht es sich meistens mit einigen Gefährten auf um in Desolace seine letzte Ruhe zu finden. Interessant ist dabei, dass die Tiere den Weg zum Friedhof jederzeit finden, auch wenn sie vorher noch nie in ihrem Leben auch nur in seine Nähe gekommen sind.",},
			["Kodos"] = { content = "#REDIRECT [[Kodo]]", redirect = "Kodo",},
			["Kokelwälder"] = { content = "Die Kokelwälder sind eine Gruppierung der [[Goblins]], die sich dem Mythos um [[Allvater Winter]] und der Vermarktung des [[Winterhauchfest]] verschrieben haben. Sie haben ein großes Angebot zur Auswahl - Frisch von ihrem Hof auf den Tisch: beste Kokelwälder Vollwertkost. Doch manche meinen, sie beschmutzen die wahre Bedeutung der Feiertage des [[Winterhauchfest]]s. Dies sei eine Zeit der Erneuerung. Das Land schlummert unter einer Schneedecke, die [[Altvater Winter]] gebracht hat, und das sei NICHT der Wichtigtuer in dem roten Aufzug.\r\nIm Winter gibt es überall frische Tannenzweige, aber die Zweige bleiben nicht lange frisch. Die Kokelwälder haben eine Maschine, die Tannenzweige konserviert - die bleiben dann für immer frisch. Sie benutzen sie um die Festtage etwas aufzupeppen... und ihre Profite im Sommer zu steigern. \r\n==Kokelwälder-Persönlichkeiten==\r\n* [[Altvater Winter]]\r\n'''Sonstige'''\r\n* '''Dillord Kupferzwick'''\r\n* '''Gapp Klingeltaschen'''\r\n* '''Hecht Kupferzwick'''\r\n* '''Kaymard Kupferzwick''' \r\n* '''Metzen das Rentier''' - Metzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. \r\n* '''Mirvyna Klingeltaschen'''\r\n* '''Targot Klingeltaschen'''",},
			["Kolkarklippe"] = { content = "Die '''Kolkarklippe''' ist das Revier der [[Zentauren der Kolkar]] in [[Durotar]]. Sie liegt gleich hinter einer Kuppe im Westen von [[Dorf Sen'jin]]. \r\n==Das Abenteuer==\r\n[[Lar Lauerzahn]], ein trollischer Späher aus dem Dorf, fand heraus, dass diese [[Zentauren der Kolkar]] einen dreistufigen Angriff auf die Trolle und Orcs von Durotar geplant hatten. Nun war es an ihm, diese Invasion zu verhindern. Jedoch musste er zuvor eine Streitmacht zusammenziehen, die nötig war, um die Kolkarklippe zu unterwandern und deren Angriffspläne zu vernichten. \r\nDie Horde würde einen Angriff der Kolkarzentauren sicherlich überstehen. Aber wenn die Trolle von Sen'jin einen solchen Angriff verhindern konnten, ersparten sie unnötiges Blutvergießen unter ihren mächtigen Kriegern. Und doch ... so sicher wie es Sand in der Wüste von [[Tanaris]] gab, wussten sie, dass Blut vergossen werden würde, bevor diese schwierigen Zeiten hinter ihnen lagen.",},
			["Koloss"] = { content = "'''Kolosse''' sind gewaltige, zu den [[Bergriesen]] gehörende, elementare Manifestationen, die man auf der [[Scherbenwelt]] findet.\r\n==Arten==\r\n* [[Kristallkoloss]]\r\n==Persönlichkeiten==\r\nBerühmte Vertreter sind z.B.:\r\n* [[Apex]]\r\n* [[Felsnarbe]]\r\n* [[Gurok der Thronräuber]]\r\n* [[Gordawg]] (Zorn der Erde)\r\n* [[Rokdar der Zerklüftete]]\r\n* [[Tavarok]]",},
			["Kolosse"] = { content = "#REDIRECT [[Koloss]]", redirect = "Koloss",},
			["Kolphis Dunkelschuppe"] = { content = "'''Kolphis Dunkelschuppe''' ist ein [[Orc Krieger]] und der stellvertretende Anführer des [[Wyrmkult]]s beim [[Pechschwingenkoven]] im [[Schergrat]]. Aus seinem Bericht geht hervor, dass der Wyrmkult plant, die [[Expedition des Cenarius]] am [[Ewiger Hain|Ewigen Hain]] anzugreifen und auszulöschen.",},
			["Kolumbus"] = { content = "'''Kolumbus''' ist ein kleiner [[Falkenschreiter]], der zur Kategorie der [[Gefährte (Kleintier)|Kleintier-Gefährten]] zählt. Die [[Sin'dorei]] benutzen Falkenschreiter als [[Reittiere]], aber dieses kleine Exemplar wurde für untauglich befunden, nachdem bei ihm eine Vielzahl an Angststörungen diagnostiziert wurde. \r\n==Herkunft==\r\nDas '''' ist eine der Belohnungen die man erhält, wenn man sich im Rahmen der [[Kinderwoche]] eines Waisenkindes aus dem Waisenhaus in [[Shattrath]] annimmt. Man erhält dieses für den Abschluss der Quest „“, die bei [[Waisenmatrone Gnädig]] in Shattrath ihren Anfang hat. \r\nDieses kleine süße [[Falkenschreiter]]baby, das nur mit dem Kopf und den Beinen aus seiner gesprenkelten Eierschale hervorgebrochen ist, ist ein äußerst aktives Kerlchen und flitzt in großem Bogen um seinen Besitzer rum.",},
			["Kommandant Ameer"] = { content = "Kommandant Ameer ist der Anführer des [[Protektorat]]s und befindet sich beim [[Wachposten des Protektorats]] im [[Nethersturm]]. \r\n===Gegen das Astraleum===\r\nEr kämpft vom [[Wachposten des Protektorats]] aus gegen das Astraleum und dessen Anführer [[Nexuskönig Salhadaar]]. Er möchte deshalb, dass man die Truppen des [[Astraleum]]s und [[Hauptmann Zovax]] tötet und dann den Transponder Zeta aktiviert. Das [[Protektorat]] muss alle Daten, die das [[Astraleum]] im Gebiet der [[Manaschmiede Ultris]] aufbewahrt, sammeln und da sich ganz in der Nähe des Transponders eine Datenzelle des Astraleums befinden soll, möchte Ameer, dass man diese sucht, öffnet und den Inhalt entnimmt. Nachdem er die Daten der Astralen auswerten konnte, hat sich der Existenzgrund des Protektorats vollkommen bestätigt. \r\n'''S-A-B-O-T-A-G-E'''\r\nSie müssen nun die Maschinen zerstören, die diese abnormalen Dunkelpirscher hervorbringen. Ihren Protobeschleuniger anzugreifen ist sinnlos, da es sich um eine astrale Erfindung handelt. Sie müssen stattdessen die Rohre der Manaschmiede, die sie als Energieleitung verwenden, zerstören. Ameer hat fast alles, was er braucht, um ein Gerät herzustellen, dass die Energieleitung überlasten kann. Er braucht nur noch die Bandagen eines Archon oder Oberanführers, der sich bald verwandeln wird, um das Gerät einzustellen.\r\n'''Die Nachricht überbringen'''\r\nDanach schickt Ameer einen seiner Demolierer los, um das Störgerät zu platzieren. Diesen Demolierer des [[Protektorat]]s soll man zur Energieleitung der [[Manaschmiede Ultris]] begleiten und ihn beschützen, während er die Leitung sabotiert. Er wird sich nicht wehren, wenn er von Feinden angegriffen wird, da er nur ein holografisches Bild ist, aber auch das kann zerstört werden.\r\n'''Nexuskönig Salhadaar'''\r\nAmeer hat aner noch einen weiteren Störer in seinem Besitz. Einer, der in der Lage ist, die drei Energieleitungen, die Salhadaar umgeben, zu zerstören. Wenn die Energieleitungen einmal vernichtet sind, werden sich Salhadaars schützende Kraftschilde senken. Für diese Tat wird er mit einer Wildheit angreifen, die man noch nie zuvor gesehen hat. Wenn man bereit ist, die Welt von Salhadaar zu befreien, gebt er einem den Störer des [[Protektorat]]s, um Salhadaar Kraftfelder zu senken und [[Nexuskönig Salhadaar]] zu vernichten.\r\n===Ein barmherziger Auftrag===\r\nKommandant Ameer und seine Soldaten haben eine Gefängniskugel auf ihrer letzten Spähermission im Gebiet des [[Astraleum]]s sichergestellt. Hätte sie nicht dieses schwache Störsignal gesendet, hätten sie sie vielleicht nie gefunden. Sie glauben, dass einer von ihnen darin eingesperrt ist, aber sie haben keine Möglichkeit die Kugel zu öffnen ohne den Inhalt zu verletzen. Sie wissen nur, dass praktisch jedes Mitglied des [[Astraleum]]s den Schlüssel dazu haben könnte, den es zu beschaffen gilt, damit sie das Geheimnis der Kugel entschlüsseln können. Es könnte aber auch eine Falle des [[Astraleum]]s sein. \r\n'''Geheimnisse des Astraleums'''\r\nEr hat eine Identifizierungsmarke eines Gefangenen bei den Überresten des gefallenen Vorpostens gefunden und geht davon aus, dass alle ihre Gefangenen auf diese Weise markiert werden. Er wird damit anfangen, alle Marken zu katalogisieren, denn vielleicht kann er so etwas über das System ihrer Gefangennahmen herausfinden. Falls man auf seinen Abenteuern noch mehr Gefängnisschlüssel des Astraleums finden sollte, kann man damit die Gefängnisse des Astraleums beim [[Stützpunkt des Astraleum]] direkt südlich des [[Wachposten des Protektorats]] aufschließen. Abenteurer sollen ihm alle Identifizierungsmarken bringen, die man finden kann. \r\n'''Tausend Welten'''\r\nKommandant Ameer kann den Code der Identifizierungsmarken entschlüsseln. Jede Marke ist in verschiedene Segmente geteilt. Die Vorderseite der Marke ist immer gleich. Darauf steht: \"Tausend Welten...\". Ameer ist sich nicht sicher, was das zu bedeuten hat, aber es klingt irgendwie heimtückisch. Auf der Rückseite der Marke stehen die wichtigen Angaben. Die erste Gruppe von Runen gibt den Aufenthaltsort an, die zweite die Art der Gefangenschaft. Des Weiteren sieht es aus, als ob die Schlüssel zu einem besonderen Schlüssel zusammengefügt werden können, mit dem man eine andere Art von Gefängnis öffnen kann. Jetzt braucht er noch mehr Schlüssel... Dann kann Ameer die Schlüssel geschickt zusammenfügen und die Markierungen auf der so hergestellten Schlüsseltafel betrachten.\r\n\"Tausend Welten zerschlagen, tausend weitere noch zu bezwingen... So lautet der Wille des Nexuskönigs.\" Als Ameer die Tafel umdreht, liest er auf der Rückseite den Namen der [[Landeplatz von Bash'ir|Stasiskammern von Bash'ir]] im [[Schergrat]].",},
			["Kommandant Grüntal"] = { content = "Obwohl die [[Burg Schattenfang]] im [[Silberwald]] schon lang verfallen ist und ihre ehemaligen Bewohner [[Arugal]]s Worgen zum Opfer fielen, findet der Geist von '''Kommandant Grüntal''' dort keine Ruhe. Noch immer führt dieser ehemals menschliche [[Paladin]] die geisterhaften Streitkräfte der Burg gegen unwillkommene Eindringlinge in den Kampf. \r\n==Fähigkeiten==\r\n* ''Hammer der Gerechtigkeit'' - Hammer der Gerechtigkeit betäubt das Ziel 4 Sek. lang. \r\n* ''Heiliges Licht'' - Heiliges Licht heilt ein befreundetes Ziel um 310 bis 356.",},
			["Kommandant Jarod Schattensang"] = { content = "==Geschichte==\r\nAls der Krieg der Urtume ausbrach, hatte Jarod Schattensang den Rang eines Captains in der Wache von Suramar erreicht, und seine Schwester [[Maiev Schattensang]] war eine der höheren [[Schwestern von Elune]]. Die Schattensangs waren keine Adelsfamilie, und so hatten sich beide Geschwister ihre Positionen durch Geschick und harte Arbeit verdienen müssen. Während er das Land der [[Nachtelfen]] vor möglichen Eindringlingen bewachte, entdeckte Jarod den in Menschengestalt verzauberten Drachen [[Krasus]] und nahm ihn gefangen. Ein merkwürdiges und extrem mächtiges Phänomen hatte [[Krasus]] in eine frühere Zeit zurückversetzt, in der es eine jüngere Version von ihm gab. Diese Überschneidung sorgte dafür, dass [[Krasus]] sich krank und schwach fühlte, so lange er nicht in unmittelbarer Nähe seines jüngeren Ichs war.\r\n===Vom Wärter zum Beschützer===\r\nMit etwas magischer Überredungskraft von [[Krasus]] machte sich der Captain Sorgen, dass sein Gefangener sterben könnte, bevor er verhört worden war. So suchte Jarod eine der Priesterinnen der [[Elune]] auf, in der Hoffnung, sie könnte [[Krasus]] vielleicht heilen. Er geriet an die Novizin [[Tyrande]] Wisperwind, und sie war einverstanden, ihm zu helfen. Sie konnte [[Krasus]] zwar nicht von seiner Schwäche heilen, aber schon bald half er ihr bei dem Versuch, ihren Freund [[Malfurion]] Sturmgrimm aus dem Koma zu befreien, in das er kurz vorher gefallen war. Dann erschien zu Jarods kaum verhülltem Erstaunen auch noch [[Cenarius]], der Halbgott der Wälder, und holte [[Malfurion]]s Geist aus dem [[Smaragdgrüner Traum|Smaragdgrünen Traum]] zurück. [[Malfurion]] wurde wieder in seinen Körper zurückversetzt und erholte sich schnell. Dann begleitete Jarod [[Krasus]], [[Malfurion]] und [[Tyrande]] zu einem Gespräch mit Lord [[Kur'talos Rabenkrone]], dem Befehlshaber der [[Nachtelfen]]armee, die gegen die [[Brennende Legion]] kämpfte. \r\n[[Kur'talos Rabenkrone]] war beeindruckt von Jarods Pflichtbewusstsein und unterstellte eine Gruppe kampferfahrener Soldaten seinem Befehl. Jarod und seine Truppe waren nun verantwortlich für den Schutz der vier stärksten Magier im Dienste der [[Nachtelfen]]armee: [[Malfurion]] und [[Illidan]] Sturmgrimm, den Menschenzauberer [[Rhonin]] und [[Krasus]]. [[Malfurion]] und [[Krasus]] verließen später die Truppe und suchten den Rest der [[Drachen]] auf, um sie zu bitten, den [[Nachtelfen]] im Kampf gegen die Legion zu helfen. Sie unternahmen diesen Versuch gegen Lord Rabenkrones ausdrücklichen Befehl und ohne Jarods Wissen. Trotzdem brachte es Kur'talos nicht übers Herz, Jarod Vorwürfe zu machen, weil dieser die Magier nicht aufgehalten hatte.\r\n===Die Ermordung von Lord Rabenkrone===\r\nSchließlich wurde Kur'talos’ starke Führung der Nachtelfenarmee der [[Königin Azshara]] ein Dorn im Auge, und sie wies Captain [[Varo'then]] an, den Adligen zu beseitigen. Der Mordanschlag glückte, und Lord [[Desdel Sternauge]] wurde der neue Anführer der [[Nachtelfen]]verteidiger. Bedauerlicherweise hatte Desdel nur wenig Kampferfahrung und keinerlei Begabung für Taktik oder Diplomatie. Als die eindringenden [[Dämonen]] kurz danach einen Rückzug vortäuschte und dann begann, die nachrückenden [[Nachtelfen]] aus der Luft anzugreifen, konnte Desdel nur hilflos zusehen, wie die [[Dämonen]] kesselweise eine kochende, rote Flüssigkeit über die [[Nachtelfen]]armee ausgossen. \r\nHunderte erlitten Verletzungen, viele davon tödlich. Jarod ritt zu [[Desdel Sternauge|Desdel]] und bat um neue Befehle, doch der Adlige konnte ihm vor lauter Panik keine geben. Dann erblickte Jarod eine Gruppe [[Dämonen]], die über [[Desdel Sternauge|Desdel]] schwebte. Jarod versuchte noch, seinen Kommandeur aus der Gefahrenzone zu zerren, doch Desdel fühlte sich durch Jarods Rettungsversuch körperlich bedroht und drohte ihm mit Kerker, wenn er ihn nicht sofort losließe. Jarod konnte gerade noch sein Pferd zur Seite reißen und entging so knapp einem qualvollen Tod, als die [[Dämonen]] ihre Kessel auskippten und kochende Flüssigkeit sich über Desdel und die in seiner Nähe stehenden Offiziere ergossen. Desdel starb innerhalb weniger Augenblicke, sein Gesicht bis zur Unkenntlichkeit verstümmelt.\r\n===Held wider Willen===\r\nNach Desdels Tod konnten sich die übrigen Adligen nicht auf eine neue Strategie für die Armee einigen. Jarod musste einspringen. Mit seinem intuitiven Strategieverständnis und seinen natürlichen Führungsqualitäten fand er sich bald auf dem Posten des Oberbefehlshabers der Nachtelfenarmee wieder. Erleichtert befolgten die Adligen seine Befehle. Jarod aber zweifelte weiter an seinem Wert für den Kriegsverlauf, doch schon bald hielt das Schicksal eine willkommene Überraschung für ihn parat. \r\n[[Cenarius]] führte eine Gruppe von Halbgöttern zur [[Nachtelfen]]armee und kniete vor dem verblüfften Captain nieder. Die Halbgötter waren bereit, unter Jarods Befehl zu kämpfen. Während der Captain die [[Nachtelfen]] sammelte und allmählich den Verlauf der Schlacht wendete, wurde der Dämonenfürst [[Archimonde]] auf ihn aufmerksam. [[Malfurion]]s Abwesenheit vom Schlachtfeld hatte den Erzdämonen frustriert, und so entschied er sich, seinen Zorn an Jarod auszulassen. [[Archimonde]] war sich sicher, dass der Sieg der Legion unausweichlich war, und so ließ er sich Zeit, spielte sadistisch mit Jarod, während er ihn langsam zu Tode quälte. Wahrscheinlich hätte es [[Archimonde]] noch größeres Vergnügen bereitet, Jarods eisernen Willen zu brechen. Doch bevor Jarod unheilbar schwer verwundet wurde, konzentrierten [[Malfurion]] und [[Illidan]] Sturmgrimm ihre vereinte Magie auf den [[Brunnen der Ewigkeit]]. Heulend vor Zorn wurden alle [[Dämonen]], unter ihnen auch [[Archimonde]], in den Brunnen gesogen und in den [[Nether|Wirbelnden Nether]] zurückgeschleudert.\r\n===Nach der Teilung===\r\nDurch die Große Teilung entstand ein neuer Ozean, und seine herantosenden Wasser trieben die [[Nachtelfen]] zurück bis zum Berg [[Hyjal]]. Schließlich kam das Meer zur Ruhe, und Jarod ging mit einer Gruppe [[Nachtelfen]] los, um die Gegend nach Trinkwasser zu durchforsten. Sie entdeckten, dass [[Illidan]] einen zweiten [[Brunnen der Ewigkeit]] erschaffen hatte, und mit [[Malfurion]]s Hilfe nahmen Jarod und die anderen [[Illidan]] gefangen. Jarod überließ [[Malfurion]] die Entscheidung über das weitere Schicksal seines rücksichtslosen Bruders, und so war es [[Malfurion]], der [[Illidan]] zu einer Kerkerstrafe verurteilte, die zehntausend Jahre dauern sollte. Jarod war nur widerwillig Kommandeur der Armee und freute sich auch aus diesem Grund, dass der Krieg endlich vorbei war. Er löste die zusammengewürfelte Truppe auf und stand noch kurze Zeit als Verwalter zur Verfügung, doch er wollte nie mehr Anführer sein. \r\nNach und nach leitete er immer mehr Antragsteller zur neuen Hohepriesterin der Elune weiter, zu [[Tyrande]] Wisperwind, deren Mitgefühl und Weisheit viel dazu beitrugen, die Spannungen der Nachkriegszeit zu lindern. Bis [[Tyrande]] die neue Armee der [[Nachtelfen]] aufgestellt hatte, die [[Schildwache]], hatte sich Jarod längst in die Anonymität zurückgezogen. Er sah sich selber nicht als Helden, und er wollte auch nicht, dass es andere taten. \r\nEines Tages ist er einfach verschwunden, mit nicht mehr als ein paar persönlichen Habseligkeiten. Er hat nicht gesagt, wo er hingeht, er hat sich noch nicht einmal von irgendwem verabschiedet. Seither hat ihn niemand mehr zu Gesicht bekommen.",},
			["Kommandant Louis Philips"] = { content = "'''Kommandant Louis Philips''' gilt bei der Allianz als willenlose Marionette der grausamen Bansheekönigin [[Sylvanas Windläufer]] in den Tiefen des Gebiets der [[Frostwolfklan|Frostwölfe]] im [[Alteractal]]. Er bewegt sich zwischen den Frontlinien und Burg Frostwolf hin und her. Louis findet [[Menschen]] schlichtweg verabscheuenswert. Zwar entspricht es den Tatsachen, dass er ein Soldat der [[Frostwolfklan|Frostwölfe]] ist, dennoch bleibt er ein Diener [[Sylvanas Windläufer]]. Neben der Ausübung seiner Pflichten, arbeitet er auch für die Dunklen Apotheker der [[Königliche Apothekervereinigung|Königliche Apothekervereinigung]] von [[Unterstadt]]. Er ist damit beauftragt worden menschliche Knochensplitter einzusammeln, die helfen sollen, sie von der menschlichen Existenz zu befreien. Sein Bruder [[Kommandant Karl Philips]], einer der Kommandanten der [[Sturmlanzen]], steht ihm auf dem Schlachtfeld gegenüber.",},
			["Kompendium der Gefallenen"] = { content = "Das '''Kompendium der Gefallenen''' ist ein wertvolles Buch tief im Inneren des Athenaeums im [[Scharlachrotes Kloster|Scharlachroten Kloster]], das die Entstehung der Geißel beschreibt.\r\n==Inhalt==\r\nNach [[Kel'Thuzad]]s Erfolg in [[Lordaeron]] traf der [[Lichkönig]] letzte Vorbereitungen für seinen Großangriff gegen die menschliche Zivilisation. [[Ner'zhul]] füllte seine Seuchenenergien in eine Reihe tragbarer Artefakte, die [[Seuchenkessel]] genannt wurden, und befahl Kel'Thuzad, die Kessel nach Lordaeron zu bringen, wo sie in den zahlreichen vom [[Kult der Verdammten]] beherrschten Dörfern versteckt werden sollten. Die von den getreuen Kultisten beschützten Kessel sollten als Seuchengeneratoren fungieren und die [[Seuche]] unter den ahnungslosen Bürgern der Landstriche und Städte nördlich von Lordaeron verbreiten. Der Plan des Lichkönigs ging auf und viele der nördlichen Dörfer von Lordaeron wurden fast auf der Stelle verseucht. Bürger, die sich mit der Seuche ansteckten, starben, um als willige Sklaven des [[Lichkönig]]s wieder aufzustehen, genau wie in [[Nordend]]. Die Kultisten unter Kel'Thuzad waren begierig darauf, zu sterben und in den Diensten ihres dunklen Lords ihre Auferstehung zu erleben. Sie bejubelten die Aussicht auf Unsterblicghkeit in einem Dasein als Untote. Und je mehr die Seuche sich ausbreitet, desto mehr wilde [[Zombie]]s erstanden in den Nordlanden. Kel'Thuzad betrachtete die wachsende Armee des Lichkönigs und nannte sie: Die Geißel - denn bald schon sollte sie zu den Toren von Lordaeron marschieren ... und die Menschheit vom Antlitz der Erde tilgen.",},
			["Konsortium"] = { content = "#REDIRECT [[Das Konsortium]]", redirect = "Das Konsortium",},
			["Konstrukt"] = { content = "Als '''Konstrukte''' werden magisch hergestellte Automaten aus verschiedenen Arten von Gestein oder Metall bezeichnet. Reine aus Stein bestehende Konstrukte nennt man auch [[Golems]], die zu den [[Elementare]]n zählen - obwohl auch einige metallische Automaten als [[Golems]] bezeichnet werden. Die meisten Konstrukte sind auf magische Weise gegen Zauber gefeit und im Allgemeinen betrachtet man sie als dumm. Allerdings sind auch Fälle belegt, wonach Konstrukte frei herumwanderten, ohne dass ihre Meister sie kontrollierten. Wohin diese vagabundierenden Konstrukte gehen oder was sie suchen, ist allerdings ein Rätsel.\r\n==Arten==\r\n* '''Siehe auch:''' [[Golems]]\r\nEs sind u.a. folgende Arten von metallischen Konstrukten sind bekannt:\r\n* [[Arkankonstrukt]]\r\n* [[Arkantitan]]\r\n* [[Erntegolem]]",},
			["Konstrukte"] = { content = "#REDIRECT [[Konstrukt]]", redirect = "Konstrukt",},
			["Konstruktionsbasis"] = { content = "Eine '''Konstruktionsbasis''' ist eine Stätte der [[Brennenden Legion]] auf der [[Scherbenwelt]]. Die Merkmale so einer Basis sind, dass sie sowohl ein Stützpunkt für die Armee der Brennenden Legion ist, als auch ein Ort, an dem sich Teleporter der Legion befinden. Sie vereint die Vorzüge eines [[Konstruktionslager]]s und eines [[Invasionspunkt]]es.\r\n==Bekannte Konstruktionsbasen==\r\n* [[Konstruktionsbasis: Gehenna]]\r\n* [[Konstruktionsbasis: Vergessenheit]]",},
			["Konstruktionsbasis: Gehenna"] = { content = "Die '''Konstruktionsbasis: Gehenna''' liegt nördlich der [[Sturmsäule]] im [[Nethersturm]]. Sie ist sowohl ein Stützpunkt für die Armee der Brennenden Legion, als auch der Ort, an dem sich die meisten Teleporter der Legion befinden. Bis heute müssen die Dämonen dort ein volles Regiment von [[Zornschaffer]]n angesammelt haben. [[Sathal]] überwacht die [[Zornpriesterin]]nen, die ihren Willen in der [[Konstruktionsbasis]] ausführen.",},
			["Konstruktionsbasis: Vergessenheit"] = { content = "Die '''Konstruktionsbasis: Vergessenheit''' liegt im [[Nethersturm]] und dient als Produktionsstätte für die [[Teufelshäscher]]. Der Anführer dieser [[Konstruktionsbasis]] ist [[Konstruktionsmeister Morug]], der die erste Hälfte eines Teleportationssteins in seinem Besitz hat.",},
			["Konstruktionslager"] = { content = "'''Konstruktionslager''' sind die mobile Bauwerke auf der [[Scherbenwelt]], die auf verbrannter, verderbter Erde stehen. Hier beschäftigt die [[Brennende Legion]] die [[Mo'arg]] und [[Gan'arg]], um Massenvernichtungswaffen, wie z.B. die mächtigen [[Teufelshäscher]] zu produzieren. Die gerissenen Mo'arg-Ingenieure treiben ihre Gan'arg-Arbeiter an, damit die Fertigstellung schneller voran geht. \r\nAlle Konstruktionslager haben einen sogenannten ''Meisterplaner''. Dieser bestimmt, welche Gebäude im Konstruktionslager vorhanden sein müssen, und wie sie platziert werden. Zudem werden diese Informationen auf Blaupausen festgehalten, die der Planer bei sich trägt. Er wird sich hinter den Konstruktionen aufhalten. Solange die [[Transporter der Legion]] stehen, ist nichts, was man gegen die Konstruktionslager unternimmt, von Dauer, da sie ständig neuen Nachschub über diese Portalvorrichtungen erhalten. Bewacht werden diese Lager von den [[Teufelskanonen]], zu denen die Vorarbeiter die Schlüssel haben, um sie zu drehen.\r\n==Bekannte Konstruktionslager==\r\n* [[Konstruktionslager: Furcht]] \r\n* [[Konstruktionslager: Groll]]\r\n* [[Konstruktionslager: Hass]]\r\n* [[Konstruktionslager: Mageddon]]\r\n* [[Konstruktionslager: Rache]]\r\n* [[Konstruktionslager: Terror]]\r\n* [[Konstruktionslager: Wut]]\r\n* [[Konstruktionslager: Zorn]]",},
			["Konstruktionslager: Groll"] = { content = "Das Konstruktionslager: Groll liegt im [[Schergrat]] und wird von einer [[Shivarra]] namens [[Schicksalsruferin]] geleitet. Ihre Wachen tragen die Schlüssel bei sich, mit denen sie ins Konstruktionslager gerufen werden kann und haben schon seit einer Weile versucht, ihre Autorität zu untergraben. Wenn man sich die fünf Schlüssel beschafft und und die fünf Obelisken der Legion aktiviert, erscheint die [[Schicksalsruferin]], dich die Obelisken schalten sich nach kurzer Zeit wieder ab, also sollte man zusehen, dass man sie alle gleichzeitig aktiviert.",},
			["Konstruktionslager: Rache"] = { content = "Die [[Dämonen]] des Konstruktionslagers: Rache im Norden von [[Ogri'la]] im [[Schergrat]]haben an ihrer südlichen Grenze einen besonderen Transporter errichtet. Sie verwenden dieses experimentelle Transporttor, um den Einfluss des Lagers weiter auszudehnen. Wenn man dort einen Zerrütter der [[Teufelwache]] kontrollieren will, muss man einen Hammer dazu benutzen, um die Schilde vom Warptor zu zerschlagen und den gefangenen [[Dämonen]] freizulassen. Danach muss man diesen Dämon zerschlagen und ihn beherrschen, bis neue [[Dämonen]] kommen, die man auch beherrschen muss ... Solange bis der Aufseher der [[Eredar]] auftaucht, der dann auch erschlagen wird ...",},
			["Konstruktionslager: Terror"] = { content = "Die '''Konstruktionslager: Terror''' liegt im Südwesten des [[Schergrat]]s. Das Problem mit [[Dämonen]] in diesem [[Konstruktionslager]] ist, hat man sie erst einmal getötet, tauchen sie wenig später in einem neuen Körper wieder auf. Wenn man allerdings ein Bannportal beschwört und ein [[Dämon]] in dessen Nähe stirbt, wird seine Essenz in das Portal gezogen und er in seine Heimatebene verbannt. Herauskommt dann eine [[Rune der Dunkelheit]]. Doch der Herstellungsprozess funktioniert nicht immer einwandfrei. Die Anführer der [[Dämonen]] haben Peitschen, um den mickrigen [[Dämonen]] Verstand einzuprügeln. Man findet sie bei den brennenden, grünen kristallinen Teufelsprisma und man braucht viele [[Apexissplitter]] um sie zu rufen. Sie hören auf Namen wie [[Galvanoth]], [[Braxxus]], [[Zarcsin]] und der Verbrenner der [[Mo'arg]]. Dieses Konstruktionslager ist der [[Himmelswache der Sha'tari]] schon seit langem ein Dorn im Auge und obendrein bedrohen sie [[Ogri'la]]. Doch mit all den [[Teufelskanone]]n, die die Himmelswache von rechts und links unter Beschuss nehmen, gibt es einfach kein Hindurchkommen und ihr Unterfangen ist zum Scheitern verurteilt.",},
			["Konstruktionslager: Wut"] = { content = "Die Konstruktionslager: Wut und Terror liegen hoch oben im [[Schergrat]]. Das Problem mit [[Dämonen]] da ist, hat man sie erst einmal getötet, tauchen sie wenig später in einem neuen Körper wieder auf. Wenn man allerdings ein Bannportal beschwört und ein [[Dämon]] in dessen Nähe stirbt, wird seine Essenz in das Portal gezogen und er in seine Heimatebene verbannt. Herauskommt dann eine [[Rune der Dunkelheit]]. Doch der Herstellungsprozess funktioniert nicht immer einwandfrei. Die Anführer der [[Dämonen]] haben Peitschen, um den mickrigen [[Dämonen]] Verstand einzuprügeln. Man findet sie bei den brennenden, grünen kristallinen Teufelsprisma und man braucht viele [[Apexissplitter]] um sie zu rufen. Sie hören auf Namen wie [[Galvanoth]], [[Braxxus]], [[Zarcsin]] und der Verbrenner der [[Mo'arg]]. Diese Konstruktionslager sind der [[Himmelswache der Sha'tari]] schon seit langem ein Dorn im Auge und obendrein bedrohen sie [[Ogri'la]]. Doch mit all den Teufelskanonen, die die Himmelswache von rechts und links unter Beschuss nehmen, gibt es einfach kein Hindurchkommen und ihr Unterfangen ist zum Scheitern verurteilt.",},
			["Konstruktionslager: Wut und Terror"] = { content = "#REDIRECT [[Konstruktionslager: Wut]]", redirect = "Konstruktionslager: Wut",},
			["Kopfjäger"] = { content = "#REDIRECT [[Trollkopfjäger]]", redirect = "Trollkopfjäger",},
			["Kor'kron-Elite"] = { content = "#REDIRECT [[Kor'kron]]", redirect = "Kor'kron",},
			["Kor'kron"] = { content = "Die kriegerischen Orcs der [[Kor'Kron-Elite]] sind die offizielle Wache und Leibgarde von [[Thrall]].",},
			["Korialstrasz"] = { content = "Der Drache Korialstrasz bekleidet als jüngster Gefährte der Drachenkönigin [[Alexstrasza]] eine hohe Position im Schwarm der [[Roter Drachenschwarm|Roten Drachen]]. Er ist von daher den anderen Aspekten [[Malygos]], [[Ysera]], [[Nozdormu]] und auch [[Neltharion]] bekannt, auch wenn er bei den Sterblichen keine Berühmtheit ist. \r\n==Geschichte==\r\nKorialstrasz ist zwar der Jüngste von [[Alexstrasza]]s Gefährten, doch ist er dennoch weit über 10.000 Jahre alt. Er kämpfte Seite an Seite mit den anderen Drachen und den Nachtelfen im [[Krieg der Uralten]] gegen die [[Brennende Legion]]. Er war auch Zeuge von [[Neltharion]]s Wandel zu [[Todesschwinge]] und dessen Verrat als er die [[Dämonenseele]] schuf. \r\n10.000 Jahre später wurde Korialstrasz erstmals wieder wichtig, nachdem [[Alexstrasza]] im Zweiten Krieg von den [[Orcs]] gefangen genommen wurde, die in Besitz der [[Dämonenseele]] gelangt waren. Die [[Orcs]] hatten zusammen mit [[Alexstrasza]] auch noch 3 andere von ihren Gefährten gefangen genommen, während Korialstrasz unter dem Pseudonym [[Krasus]], einem [[Hochelfen]] im Hohen Rat der [[Kirin Tor]] verweilte. \r\nIn der Endphase des Krieges beauftragte er seinen Schüler [[Rhonin]] mit der Befreiung [[Alexstrasza]]s und versuchte auch die anderen Aspekte für eine Hilfsaktion zu gewinnen, da er herausgefunden hatte, das [[Todesschwinge]] sich in die Angelegenheiten der [[Menschen]] einmischen wollte, indem er sich zum König von [[Alterac]] und später auch noch zum König von [[Lordaeron]] ernennen lassen wollte. \r\nAls Korialstrasz von dem bevorstehenden Abmarsch des [[Drachenmal Klan]]s, der [[Alexstrasza]] in der Bergfestung [[Grim Batol]] gefangen hielt, erfuhr, sah er seine Chance gekommen persönlich in die Rettungsmission einzugreifen. Doch Korialstrasz konnte sich gerade noch in Sicherheit bringen, bevor er der [[Dämonenseele]] erlag. Verzweifelt schickte er den letzten noch lebenden der Gefangenen Gefährten in den Kampf mit dem roten Leviathan [[Tyranastrasz]]. Der Kampf mit dem altersschwachen und kranken [[Tyranastrasz]] war für [[Todesschwinge]] allerdings keine große Herausforderung und während die [[Orcs]] [[Alexstrasza]] weiterhin gefangen hielten, stahl [[Todesschwinge]] ihnen die Eier der Drachenkönigin vor der Nase weg.\r\nLetztendlich tauchte auch [[Rhonin]] auf, den Korialstrasz mit letzter Kraft zu sich teleportierte. Er war gerade dabei [[Rhonin]] die Rolle der [[Dämonenseele]] zu erklären, als sich auch die restlichen drei Aspekte einschalteten. Während [[Ysera]], [[Malygos]] und [[Nozdormu]] den Kampf mit [[Todesschwinge]] aufnahmen, sollte der geheilte Korialstrasz Rhonin zu den [[Orcs]] bringen, die sich mittlerweile eine Schlacht mit den Zwergen lieferten. Rhonin sollte daraufhin die Dämonenseele erbeuten. Der Plan ging auch auf, Rhonin konnte dem Hexenmeister Nekros die Dämonenseele aus der Hand schlagen, woraufhin sich [[Alexstrasza]] ihres Kerkermeisters entledigte und sich den anderen Drachen im Kampf mit [[Todesschwinge]] anschloss. \r\nDoch durch die schiere Existenz der [[Dämonenseele]] geschwächt, hatten selbst die vier Aspekte keine realistische Chance den Schwarzen Drachen zu besiegen. Rhonin aber gelang es durch einen Fehler Todesschwinges, die Dämonenseele zu zerstören, woraufhin Todesschwinges Siegeschancen im Nichts verschwanden. Als die Schlacht geschlagen war kehrte Krasus den [[Kirin Tor]] den Rücken \"um sich um seine Frau zu kümmern\", es dauerte allerdings nur ein paar Jahre, bis er den Roten Drachenschwarm erneut verließ, um ein Auge auf die Menschen zu haben. \r\nIn dieser Position beobachtete er den Verrat von [[Arthas]] und die Invasion der [[Brennende Legion|Brennenden Legion]], sowie auch deren Niederlage, als er von [[Nozdormu]] gerufen wurde. Zusammen mit [[Rhonin]] brach Korialstrasz auf nach [[Kalimdor]] und fand auch sehr schnell den von [[Nozdormu]] in einer Vision gezeigten Berg – die Störung um diesen Berg konnte man bereits in [[Azeroth]] spüren. Die Störung selbst schien allerdings aus dem inneren des Berges zu kommen und genau dorthin machten sich die beiden auf. \r\nDa die Höhle nicht groß genug war nahm Korialstrasz wieder seine elfische Form als Krasus an. In der Höhle fanden sie die Störung in Form eines Energiefeldes, das die beiden verschlang – was sie nicht wussten war, dass die Orcs ebenfalls zwei Krieger losgeschickt haben um den Berg zu untersuchen. Als sie wieder zu sich kamen waren sie in einem unbekanntem Wald und sehr erschöpft. Krasus hatte es hierbei viel schlimmer erwischt als Rhonin, der sich im laufe des Tages wieder erholte. Krasus selbst konnte auch nicht mehr die Form eines Drachen annehmen. In der darauf folgenden Nacht wurden die beiden von einer Gruppe [[Nachtelfen]] überfallen, überwältigt und abtransportiert, doch bevor sie die Siedlung der [[Nachtelfen]] erreichten griff die Natur selbst die Nachtelfen an und der Halbgott [[Cenarius]] entführte die Gefangenen. Letztendlich bestätigte [[Cenarius]] aber nur, was Krasus schon zuvor befürchtet hatte: Sie waren in der Zeit zurückgereist und zwar über 10.000 Jahre in die Vergangenheit. Bei der Erwähnung der Nachtelfensiedlung [[Zin Ashanti]] und dem [[Brunnen der Ewigkeit]] klingelte es zwar bei Krasus, doch hatten seine Erinnerungen in den Jahrtausenden doch etwas gelitten, so dass ihm nur einfiel, dass beides in einer großen Katastrophe zerstört wurde, er aber nicht sofort wusste warum.\r\nIm Laufe des Tages bemerkte Krasus einen Beobachter, der nicht in Cenarius’ Auftrag handelte .. einen Drachen. Es gelang ihm den Drachen davon zu überzeugen, dass er einer von ihnen war, damit dieser ihm letztendlich zu [[Alexstrasza]] bringen könnte. Da er nicht mehr seine Drachengestalt annehmen konnte, war es schwer dem jungen Drachen seine Herkunft zu beweisen, doch letztendlich gelang es ihm, er trat allerdings zu nahe an die Grenze ihres „Gefängnisses“ so dass die Blumen ihn mit betäubenden Dämpfen außer Gefecht setzten. Als Krasus aufwachte befand er sich im Hort der [[Roter Drachenschwarm|Rotdrachen]], der Drache, der ihn hergebracht hatte, hatte Rhonin bei [[Cenarius]] zurückgelassen. \r\nWar dieser aber noch relativ leicht zu beeindrucken gewesen, verlangten der oberste von Alexstrazas Gefährten, dass Krasus ihn beim Namen nannte, den er als Drache kennen müsste, um zu [[Alexstrasza]] vorgelassen zu werden. Doch Krasus kannte [[Tyranastrasz]] und konnte daher passieren. Auch wenn er mittlerweile seinen echten Namen verraten hatte, wurde er nur Alexstrasza selbst mitgeteilt. Zusätzlich dazu, dass man ihr den Namen gesagt hatte erkannte sie ihn wieder und wusste von daher dass er nicht gelogen hatte. Krasus berichtete seiner Königin von seiner Notlage, ließ aber bewusst einige Teile weg. Alexstrasza entschied eine Sitzung unter den Aspekten einzuberufen und stellte Krasus einen anderen Drachen zur Seite, der ihn auf dem Weg zu dieser Sitzung tragen sollte: Korialstrasz. Krasus’ jüngeres Selbst schien ihn fast zu erkennen, allerdings verstand dieser das nicht. Auch er litt unter der Schwäche, unter der auch Krasus litt, doch je näher sich die beiden waren, desto stärker waren beide.\r\nAuf der Versammlung der Aspekte bemerkte Krasus, dass [[Neltharion]] zwar noch ein angesehener Drache war, aber in seinem inneren bereits dem Wahnsinn verfallen war. Dieser erkannte, dass Krasus ihn durchschaut hatte und sorgte mit einem Zauber dafür, dass Krasus nichts verraten konnte. Man wartete lange auf der Versammlung auf die Ankunft [[Nozdormu]]s, bis schließlich die Nachricht eintraf, dass er nicht kommen würde. Diese Nachricht beunruhigte Krasus noch mehr, da der Verlauf der Zeit offensichtlich stark gestört worden war und [[Nozdormu]] in all seinen zeitlichen Versionen daran arbeitete das zu beheben. \r\nKrasus entschloss sich, die Drachen vor der bevorstehenden Katastrophe zu warnen, doch da schlug [[Neltharion]]s Zauber zu und sorgte dafür, dass Krasus zusammenbrach. Er kam erst im Hort der Rotdrachen wieder zu sich, ohne den Drachen etwas vorgetragen zu haben. Ihn überkam daraufhin aber eine weitere von [[Nozdormu]] geschickte Vision von einem Nachtelfen, Krasus und Korialstrasz machten sich auf, ihn zu finden.\r\nWährend des Fluges nach [[Zin-Azshari]] bemerkten die beiden Drachen die Invasion der Dämonen und kämpften gegen die Legion, jedoch mussten sie den Kampf abbrechen und Krasus ging nach Suramar, um [[Malfurion]] zu suchen. Doch er wurde von Nachtelfen gefangen genommen und schaffte es nur dank seiner Magie, Kontakt zu Tyrande aufzubauen. Er schaffte es dann, Malfurion Kraft zu spenden und half indirekt , [[Xavius]] zu besiegen.",},
			["Kormeks Hütte"] = { content = "Kormeks Hütte ist ein kleiner Schuppen im Norden von Zentral-Desolace. Er wird gegenwärtig von Willow und Bibbly Futzbuckle bewohnt. \r\n* '''Bibbly F'utzbuckel''' genießt es außerordentlich außen um den Stall zu tanzen. Er glaubt, dass er der einzige [[Goblin]] in Desolace sei, der weiß, wie man Geld macht. Sie sitzen hier auf einer Goldmine. Kodoknochen werden die Welt für immer verändern. Er hat Kunden, die daraus Möbel, Musikinstrumente und sogar Sprengpulver herstellen. Eine Karawane kommt hier vorbei, die seine Kodoknochen mitnimmt und sie dann in [[Schattenflucht]] verkauft. \r\n* '''Kormek''' ist den meisten besser bekannt als der [[Zentauren]] Pariah und wandert jetzt heimatlos im südlichen Desolace umher. Willow jagte ihn weg, um die Hütte für sich zu sichern. \r\n* '''Willow''' gehörte früher zum Schattenhammer Kult und sammelt theradrische Kristallschnitzereien.",},
			["Kosmozang"] = { content = "'''Kosmozang''' ist ein kleiner Stützpunkt im Osten des [[Nethersturm]]s. Dieser Flugpunkt ist der Ausgangspunkt für Ausflüge in die [[Festung der Stürme]]. Hier findest sich neben einem Goblin, der die Ausrüstung der Abenteurer reparieren kann, auch der Reagenzienhändler [[Sab'aoth]]. Normalerweise zieht er mit seinem [[Wichtel]] Zeppit los, um das Blut von [[Sphärenhetzer]]n in dieser Gegend zu sammeln. Dieses Blut ist eine sehr mächtige Reagenz und sein großer Verkaufsschlager. Zeppits ist darin geübt, das Blut einzusammeln, aber seine Aufmerksamkeit neigt dazu abzuschweifen.",},
			["Koven der Brennenden Klinge"] = { content = "Der Koven der Brennenden Klinge ist eine Höhle im Norden vom [[Tal der Prüfungen]] in [[Durotar]]. Eine Gruppe, die sich die \"[[Brennende Klinge]]\" nennt, hat hier einen Koven für ihre Mitglieder errichtet. Sie lungern dort herum und ihre üblen Familiare kriechen daraus hervor, um Chaos anzurichten. Doch diese abscheulichen Bestien sind nur Schoßtierchen der dunkleren Mächte bei der [[Brennende Klinge|Brennenden Klinge]]. In diesem Koven ist auch ein Gegenstand der Macht verborgen, der durch Bestien und schwarze Magie bewacht wird. Er wird das genannt und ist im Besitz eines Agenten der Brennenden Klinge, [[Yarrog Schattenbann]]. Durch das Medaillon ist die Macht dieses Agenten weitaus stärker als die der Familiare.",},
			["Kraftquelle Modell 4711-FTZ"] = { content = "[[Chefingenieur Bilgenritzel]] in [[Tanaris]] baute diese Kraftquelle, um das [[Feldtestset]] zur Datensammlung über die heimische Fauna zu betreiben. Laut Bilgenritzel hat man zwei Stunden Zeit, um die benötigten Daten zu sammeln. Danach versiegt die Kraftquelle.",},
			["Kraken"] = { content = "'''Kraken''' sind uralte Wesen, die im [[Abyssischer Rachen|Abyssischen Rachen]] hausen. Sie sind die höchsten Diener [[Neptulon]]s und dementsprechend mächtig. Es heißt, dass Kraken uralt werden und sich selbst an den Aufstieg der [[Alten Götter]] erinnern können. Nur einmal traten sie bekannterweise auf [[Azeroth]] auf. Die Situation ist im \"[[Gurubashis Untergang]]\" geschildert.\r\nOb Kraken [[Elementare]] sind oder mit den [[Wasserelementare]]n in den [[Abyssischen Rachen]] verbannt wurden, ist unklar.",},
			["Krallenbau"] = { content = "Die [[Nachtelfen Druide]]n errichteten den Krallenbau auf dem [[Steinkrallengipfel]] im [[Steinkrallengebirge]], in dem sie viele mächtige Gegenstände aufbewahren. Sie haben sich ein komplexes Schema ausgedacht, damit sie nicht in die falschen Hände gelangen. Versteckt in einer kleinen Laterne am Eingang des Baus wird man den finden. Damit kann man die Behälter öffnen, die über den ganzen Bau verteilt sind. Mit den Gegenständen aus diesen Behältern wiederum kann man ihren Hort öffnen, der sich in einem der zentralen Bereiche befindet. [[Rynthariel die Schlüsselmeisterin]], eine ränkeschmiedende [[Dryade]], ist die Anführerin des Krallenbaus.",},
			["Krallendruide"] = { content = "#REDIRECT [[Druide der Kralle]]", redirect = "Druide der Kralle",},
			["Krallendruiden"] = { content = "#REDIRECT [[Druide der Kralle]]", redirect = "Druide der Kralle",},
			["Krallenpriester"] = { content = "#REDIRECT [[Arakkoa-Krallenpriester]]", redirect = "Arakkoa-Krallenpriester",},
			["Kral der Klingenhauer"] = { content = "Der Kral der Klingenhauer im südlichen [[Brachland]] ist die Ruhestätte [[Agammaggan]]s.\r\nVor zehntausend Jahren, zum Höhepunkt des Kriegs der Uralten, betrat der mächtige Halbgott [[Agamaggan]] das Schlachtfeld, um sich der [[Brennende Legion|Brennenden Legion]] entgegenzustellen. Seinen Beitrag zur Rettung [[Azeroth]]s vor dem sicheren Untergang musste der stolze Eber jedoch mit seinem Leben bezahlen. Im Lauf der Zeit sprossen dort, wo die Tropfen seines Blutes auf die Erde gefallen waren, gewaltige Dornenranken. Die [[Stacheleber]], die sterblichen Nachkommen des mächtigen Gottes, siedelten sich dort an und betrachten den Kral bis zum heutigen Tag als ihr höchstes Heiligtum, dessen Herz der Klingenhauer genannt wird. Heute wird der größte Teil des Krals von Razorfen von der alten Stammesfürstin Charlga Razorflank und ihrem Stamm kontrolliert. Unter ihrer Führung greifen die schamanistischen [[Stacheleber]] regelmäßig sowohl die feindlichen Stämme als auch nahegelegene Siedlungen der Orcs und [[Tauren]] an. In jüngster Zeit gab es Hinweise, die auf einen möglichen Pakt zwischen Charlga und den Agenten der untoten [[Geißel]] hindeuten. Kann es tatsächlich sein, dass die Uralte ihren nichtsahnenden Stamm zu irgendeinem finsteren Zweck direkt in die Arme der [[Untote]]n treibt? \r\nQuelle: wow-europe.com",},
			["Krasus"] = { content = "'''Krasus''' ist die menschliche Gestalt des roten Drachen [[Korialstrasz]]. In seiner Maskerade war er einer der Ältesten der [[Kirin Tor]] und Mitglied des Inneren Konzils. Der Titel war zweifellos ein Falscher, was jedoch keine ungewöhnliche Praxis unter jenen im herrschenden Konzil war. Es war zwar möglich die Identitäten von einigen aus dem inneren Kreis zu vermuten, aber Krasus blieb sogar für kluge Agenten ein Rätsel. \r\n==Erscheinung==\r\nEr tritt auf als hoch verhüllte und mit einer Kapuze bekleidete Figur, ähnlich einem dunklen Magier. Er ist schweigsam und wenn er spricht, ist seine Stimme ohne Modulation, ohne identifizierbares Geschlecht. Er ist eine schlanke, schlaksige Gestalt - wenig mehr als Schatten und seine schlanken Hände sind mit Handschuhen bekleidet.",},
			["Krasus Kompendium"] = { content = "Die [[Kirin Tor]] haben der Expedition, die sich in die [[Scherbenwelt]] aufmachte, einen Gegenstand aus [[Krasus]]' Besitz mitgegeben. Es handelt sich dabei um sein Zauberbuch, das [[Krasus Kompendium]] genannt wird. Da es alle Zauber enthält, die [[Krasus]] beherrschte, war es eine unersetzliche Hilfe im Krieg gegen die [[Orcs]]. \r\nBevor [[Kael'thas]] und seine Truppen [[Kirin'Var]] besetzt haben, wurde das Buch von einem rebellischen Schüler, der begierig darauf war, die Nekromantie zu erlernen, gestohlen. Der Lehrling und seine Anhänger haben sich aufgeteilt und das Buch heimlich studiert, wobei sie sich in ihren Häusern im Süden der Stadt eingeschlossen haben.\r\nAber ohne das [[Heliotropes Oculus|heliotrope Oculus]] ist [[Krasus]]' Kompendium nutzlos. Denn [[Krasus]] war sich der unermesslichen Macht des Buchs bewusst und hat Vorkehrungen getroffen, damit es vor gierigen Blicken geschützt bleibt. Nur ein Magier mit großem Wissen kann dem Kompendium mit Hilfe des Oculus' seine Geheimnisse entlocken.",},
			["Krater von Un'Goro"] = { content = "=Allgemeines=\r\nDer Krater von Un'Goro liegt im Süden von [[Kalimdor]] zwischen [[Tanaris]] und [[Silithus]]. Er ist eine grüne Oase inmitten der Wüstenlandschaften, der die Handschrift der [[Titanen]] trägt. \r\n===Kristalle===\r\nÜberall im Krater liegen Kristalle herum, die eine gewisse Macht besitzen.\r\n==Fauna==\r\nDieser Ort trägt die Handschrift der [[Erdenmutter]]. Im Krater von Un'Goro gibt es viele seltsame Kreaturen - sie scheinen edler zu sein als ihre Verwandten, die man überall in ihrem Heimatland und jenseits davon findet. \r\n* [[Affen]]\r\n* [[Raptoren]]\r\n* [[Saurier]]\r\n==Flora==\r\n* [[Erde von Un'Goro]]\r\n===Blutblüten===\r\nDie Blutblüten scheinen ein gewisses Maß an Intelligenz zu besitzen.\r\n=Orte=\r\n* [[Feuersäulengrat]]\r\n* [[Marshalls Zuflucht]]\r\n* [[Pylonen]]\r\n==Eingang zum Krater von Un'Goro==\r\nEs gibt einen Pfad, der den Krater von Un'Goro und die [[Tanaris]]wüste verbindet. Nahe dem Punkt, an dem der Pfad in den Krater hineinführt, wird man den [[Tauren Jäger]] [[Torwa Pfadfinder]] finden. Dieser hat die Hilfe eines [[Druiden]] angefordert. Denn nur ein [[Druide]] verfügt über den nötigen Respekt für die Natur und die Fähigkeiten, um ihm zu helfen. Einst, vor sehr langer Zeit, stahl einer von Torwas Brüdern ein Stück Fleisch aus [[Lar'korwi]]s Jagdbeute. Damals wusste er es nicht, aber [[Lar'korwi]] hat ihn vom Wald aus beobachtet. Er folgte Torwas Bruder tagelang und vernichtete alles, was er berührte. Sein Bruder, von Angst erfüllt, entschloss sich schließlich, aus dem Krater zu fliehen, um [[Lar'korwi]] zu entkommen, doch Lar'korwi tötete ihn, nicht weit von der Stelle entfernt, wo man [[Torwa Pfadfinder]] findet. Das Gift, das Torwa nun entwickelt, ist für einen bestimmten Zweck gedacht. Die mächtigen [[Teufelssaurier]] des Kraters erschweren ihm die Jagd und das Überleben. Selbst wenn er über die nötige Stärke verfügen würde, einen Teufelssaurier zu erlegen, würde einfach nur ein anderer sein Territorium beanspruchen. Das Gift sollte einen lebenden [[Teufelssaurier]] ruhigstellen, aber er ist sich nicht sicher, wie lange es dauern wird, bis es wirkt... Um ein Gift von ausreichender Potenz zu entwickeln, wird man sich auf den Grund des [[Tempels von Atal'Hakkar]] begeben müssen. \r\n==Fungusfels==\r\nDas Versteck der Affen, gleich nördlich von [[Marschalls Zuflucht]].\r\n==Heiße Quellen==\r\nDie heißen Quellen hier sind eine Quelle der Geheimnisse. Woher kommt die Hitze? Wenn man überlegt, wie nah diese Teiche beim Feuersäulengrat sind, fragt man sich wirklich, ob der Vulkan etwas damit zu tun hat. [[Krakle]] hat für die Messung der Hitze am Vulkan ein Thermometer entwickelt. Es zeigt die Messungen in Grad Kraklenheit an. \r\n==Lakkari -Teergruben==\r\nDie Teergruben liegen im Norden des Kraters . Die pflanzenartigen Kreaturen jedoch haben Chlorophyll in ihrer Haut, und wenn man das mit dem Teer mischt, dann wird das superklebrig.\r\n==Terrorflucht==\r\nIn der Terrorflucht treiben sich [[Stegodon]]s und [[Dimetrodon]]s herum.",},
			["Kreise der Bindung"] = { content = "Vier Kreise der Bindung sind im ganzen [[Arathihochland]] verteilt. Ihre zentralen Steine halten die elementare Prinzessin [[Myzrael]] unter der Erde fest und werden jeweils von verschiedenen [[Elementare]]n bewacht. Das Öffnen der ersten drei Steinkreise der Bindung löst den Großteil von [[Myzrael]]s Fesseln, aber ein letztes Schloss hält sie selbst dann noch immer gefangen. Es ist der Hauptstein und der Schlüssel wird von einem ihrer Häscher bewahrt, dem Steinbehüter Fozruk. Man muss diesen Schlüssel, den die Steinbehüter die Rute der Ordnung nennen, von Fozruk in Besitz nehmen und mit ihm den Hauptstein öffnen. \r\nAuf das Schicksal von [[Myzrael]] aufmerksam gemacht, wird man vom [[Anhänger von Myzrael]], dem man zufällig findet. \r\n===Kreis der Äußeren Bindung===\r\nDer Kreis der Äußeren Bindung liegt im zentralen Teil des [[Arathihochland]]es, nahe der [[Zuflucht]] und wird von [[Luftelementare]]n bewacht. \r\n===Kreis der Inneren Bindung===\r\nDer Kreis der Inneren Bindung ist der stärkste der Steinkreise. Um ihn zu öffnen, muss man Schlüssel von den drei Übrigen sammeln. \r\n===Kreis der östlichen Bindung===\r\nDer Kreis der östlichen Bindung liegt im Östlichen Teil der Region, nahe [[Hammerfall]], und wird durch [[Wasserelementare]] bewacht.",},
			["Kresh"] = { content = "'''Kresh''' ist eine große [[Schildkröte]] in den [[Höhlen des Wehklagens]]. Eigentlich tut diese neutrale [[Wildtier]] niemanden etwas zu leide, ist jedoch trotzdem ein beliebtes Jagdziel, da ihr bzw. einen beliebten Schild abgibt. [[Jäger]] können von ihr die Fähigkeiten Beißen (Rang 3) und Panzerschild (Rang 1) lernen.",},
			["Kriecher"] = { content = "Als '''Kriecher''' werden Krebse und Krabben bezeichnet - die Früchte des Meeres. Man kann sie backen, grillen, kochen und braten. Man kann sie in der Pfanne braten, frittieren und kurzbraten. Es gibt Krebssalat, Krebssuppe, Krebseintopf, Pfefferkrebs, Zitronenkrebs, Peitscherwurzelkrebs und Eisenschmiedekrebs Ã la Surprise. Ihre makellosen Kriecherbeine sind die Zutat zu einem Gericht namens \"Schlammpanzersuppe mit Käfern. Die Schale des Krebsbeins ist das wichtigste Element der Präsentation des Gerichts, daher braucht man makellose, unverletzte Beine. Aber auch als Begleiter von Jägern oder gar als Haustier, man erinnere an den [[Magischer Flusskrebs|Magischen Flusskrebs]], hat man diese Schalentiere schon gesehen.",},
			["Krieg"] = { content = "In der langen Vergangenheit [[Azeroth]]s gab es unzählige kleinerer und größerer Kriege. \r\n====Übersicht großer Kriege====\r\n* Der [[Krieg der Uralten]] (vor ca. 10.000 Jahren)\r\n* Die [[Trollkriege]] (vor ca. 2.800 Jahren)\r\n* Der [[Krieg der Sandstürme]] vor ca. 1000 Jahren\r\n* Der [[Krieg der drei Hämmer]] (vor ca. 275 Jahren)\r\n* [[Der Erste Krieg]] (vor ca. 25 Jahren)\r\n* [[Der Zweite Krieg]] (vor 20 Jahren)\r\n* [[Der Dritte Krieg]] (vor 6 Jahren)\r\n====Überlieferungen und Berichte====\r\n* Die [[Schwestern des Zorns|Geschichte der Kriege]] aus Sicht der [[Schwestern des Zorns]].",},
			["Krieger"] = { content = "'''Krieger''' können rasende [[Berserker]] oder in Stahl gehüllte Kampfmaschinen sein, fähig, enormen Schaden abzufangen und damit ihre Verbündeten vor Gefahren zu schützen. Sie haben Zugriff auf eine große Auswahl an Fähigkeiten, vom Verstümmeln ihrer Feinde bis zum Austeilen von enormen Mengen an Schaden in sehr kurzer Zeit, und können die Kampffähigkeiten ihrer Verbündeten mit ihren Schlachtrufen verbessern. Sie beschäftigen hervorragend mehrere Gegner gleichzeitig und gewinnen dabei Wut durch jeden ausgeteilten oder eingesteckten Treffer, die sie in ihren zahlreichen Spezialfähigkeiten wieder freisetzen. Krieger sind eine sehr flexible Klasse, die euch viele verschiedene Spielweisen bietet.\r\nDer Krieger kann als defensiver Brecher mit Schild, als Schaden verursachender Schlächter oder als Kombination aus beidem fungieren. Ihre Fähigkeiten prädestinieren sie für den Nahkampf und ihre Standhaltungen bieten ihnen verschiedene Spezialfähigkeiten für jede Situation oder Gruppenkombination. Alles in allem ist der Krieger einer der besten, wenn es darum geht, die Aufmerksamkeit von Monstern zu gewinnen und auch zu behalten, während diese den Schwertern und Zaubern der Verbündeten zum Opfer fallen. \r\n==Ausrichtungen==\r\nWenn man es in den Reihen der Krieger zu etwas bringen will, muss man zäh sein. Eine starke Verteidigung ist sehr wichtig für einen Krieger. Damit besteht er noch gegen Feinde, wenn andere schon niedergeschmettert wären. Krieger beherrschen auch den beidhändigen Kampf und zwei Schwerter sind schließlich noch mächtiger als die Feder. \r\n===Furor===\r\nZu den Fähigkeiten im Bereich des Furor gehört z.B. das ''Abfangen'' sowie der Siegesrausch, denn der Sieg eines Kriegers bedeutet Leid für einen anderen. Auch der ''Schmetterschlag'' ist dabei nützlich, denn selbst Metall ist der Wut eines Furor-Kriegers nicht gewachsen. Einem Krieger gegenüber Schwäche zu zeigen, ist dabei ein Todesurteil. Zu den Furor-Fertigkeiten gehört auch der ''Schlachtruf'': \"Für Lordaeron!\" \"Für Khaz Modan!\" \"Für die Horde!\" Azeroth hat sie alle gehört. \r\n===Schutz===\r\nZu den Schutz-Talenten des Kriegers gehört u.a. das ''Verwüsten'' und das ''Durchbohren'', denn Rüstungen und Menschen haben mindestens eines gemeinsam: Sie funktionieren nicht mehr, wenn man ein großes Loch hineinmacht. \r\n===Waffen===\r\nZu den Fähigkeiten im Bereich des Furor gehört z.B. der ''Donnerknall'' und das ''Verwunden''. Eines Kriegers Klinge findet ihr Ziel gleichermaßen durch Willen wie durch Fertigkeit. Ein Krieger überläßt dabei seinem Opfer oft die Wahl: Stückchen für Stückchen zu sterben, oder auf einen Schlag. \r\n==Rassen==\r\nJe nach Rasse oder Ausrichtung sind folgende \"Gruppierungen\" von Kriegern bekannt:\r\n* [[Draenei Krieger]]: [[Hand von Argus]]\r\n* [[Gnomen Krieger]] \r\n* [[Menschen Krieger]]: [[Arbeiter]], [[Ritter]], [[Menschen Krieger|Soldat]] \r\n* [[Nachtelfen Krieger]]: [[Schildwache]], [[Dämonenjäger]]\r\n* [[Orc Krieger]]: [[Grunzer]]\r\n* [[Tauren Krieger]]: [[Klippenläufer]]\r\n* [[Troll Krieger]]: [[Troll Berserker]], [[Bluttrinker]], [[Henker]] \r\n* [[Untoter Krieger]]: [[Todeswache]]\r\n* [[Zwergen Krieger]]: [[Bergkönig]], [[Pilot]]\r\n'''Quelle:'''\r\n==Rollenspieltechnisch==\r\n'''Ich bin der Krieger''' \r\nWenn ihr mich seht, bin ich wahrscheinlich nicht gekleidet wie es üblich ist. Ich bin eingeschlossen in kalten Stahl. Er wird schmutzig sein, blutig und zerbeult. Ich habe keine schnelle Zunge und führe keine gewandten Gespräche. Ich weiß nichts von den Manieren an des Königs Hof, oder über das Benehmen auf einem feierlichen Ball. \r\nIch bin bekannt unter vielen Namen: Panzer. Lebender Schild. Kämpfer. Rowdy. Leiche. \r\nIch bin der Krieger. \r\nIch habe weder die Fähigkeit noch die Neigung mich zu verstecken. Ich kann nicht heimlich zuschlagen mit verheerendem Stoß, um dann im Dunkel zu verschwinden. Ich kann keinen Gegner zu Asche verbrennen aus zwanzig Schritt Entfernung. Ich kann den Tod nicht aus der Ferne bringen, sicher vor dem Gegenangriff meines Feindes. Um zu töten, muss ich meinem Feind nahe sein. Ich sehe seine Augen. Ich rieche seinen Atem. Ich schmecke seine Furcht. Er schmeckt die meine. \r\nIch kann die Natur nicht zwingen meinem Geheiß zu folgen. Ich kann die Mächte des Nethers nicht kontrollieren damit sie tun, was ich befehle. Ich kann das Arkane nicht studieren um Macht darüber zu erlangen. Ich habe nichts als meine Seele, meinen Körper, meinen Willen. Damit, und damit allein, stehe oder falle ich. \r\nIch habe keinen Freund auf meiner Reise. Keinen Leerwandler, beschworen aus dem Nether als Diener und Leibwächter. Kein loyales Tier aus Ebenen oder Wäldern verteidigt mich, oder tröstet mich in meinem Leid. Mein einziger Gefährte ist meine Waffe. Ich muss für sie sorgen, besser als irgendein Jäger je für sein Tier gesorgt hat. Ich muss sie beherrschen, besser als jemals ein Hexer seine Dämonen beherrscht hat. Ohne mich ist sie nutzlos. Ohne sie bin ich nichts. \r\nIch kann nicht Heilen. Ich kenne keinen Schirm. Ich kann keine Götter anrufen die meine Gebete erhören. Ich rufe die Geister meiner Ahnen in der Hitze des Kampfs und sie schweigen. Alles was ich tun kann um andere zu schützen ist mich selbst hinzuhalten, mein Blut, meine Knochen, meine Sehnen zu opfern. Den Angriff der Gegner auf mich zu ziehen. Prügel einzustecken, die ein schwächeres Geschöpf töten würden, und weiter zu kämpfen. \r\nIch kann nicht töten mit der Geschwindigkeit und Eleganz eines Schurken, unvermittelt und überraschend wie ein Jäger, so auffällig und voll Energie wie ein Magier. Wenn ich töte, ist es ein langsames Geschäft. Langsam und blutig für alle, auch mich selbst. Ich kämpfe weiter, verletzt und zerschlagen, damit meine Gefährten den Ruhm des Tötens ernten, und den Siegeskranz erringen. Wenn ich falle, und sie leben, dann war das ein Opfer, das von mir erwartet wird. \r\nIch lebe in jeder Rasse, in jeder Größen. Ich kämpfe unter tausend Flaggen, auf Millionen von Schlachtfeldern. Ich werde fallengelassen von den Vornehmen und verachtet von den Edlen, höre Strafpredigten von den Priestern, und bin von den Bauern vergessen. Bis zu der Zeit zu der die Kriegstrompeten erschallen, und die mordenden Horden heranstürmen. Und dann erhebt sich der Schrei: „Wo, oh wo ist der Krieger?“ \r\nBetet zu euren Göttern, dass ich dann immer noch antworte auf diesen Ruf. \r\nWenige folgen dem Ruf. Noch weniger überleben. Der Weg des Kriegers ist eine lange und steinige Straße. An ihr liegen Schmerz und Angst und Tod. Knappe Entlohnung und noch knapperer Dank. An ihrem Ende liegt für die Meisten von uns ein einsames Grab oder stürmisches Schlachtfeld. Wenn wir Glück haben. \r\nUnd dennoch kämpfe ich weiter. Ich weiß nicht warum. Vielleicht für Ehre, vielleicht für Ruhm, vielleicht für Geld, vielleicht für mein Land, vielleicht für meine Familie. Vielleicht weil es alles ist, das ich kann. Aber ich werde kämpfen. Ob du es zu schätzen weißt oder nicht. Ob du es bemerkst oder nicht. Ich werde da draußen sein, an der Front. Kämpfend. Tötend. Sterbend. \r\nIch bin der Krieger. \r\nDer Tod ist mein Gewerbe. \r\nDeiner … oder meiner. \r\n'''Quelle:''' Aus dem Englischen Forum, Autor unbekannt.",},
			["Kriegsherr Bluthauer"] = { content = "'''Kriegsherr Bluthauer''' ist der Kommandant des [[Kargather Expeditions Korps]] im [[Ödland]]. Er ist ein einäugiger [[Orc Krieger]] der Horde und es macht ihn wütend, dass seine Feinde keinen Tagesritt von [[Kargath]] enfernt in der [[Schwarzfels]]festung sitzen und Pläne gegen die Horde schmieden. Er sehnt sich danach, die Bande der Pflicht abzustreifen und alle im Namen des Kriegshäuptlings zu vernichten. Aber sie alle haben nunmal ihren Platz und ihre Aufgabe hier in [[Kargath]] und müssen ihre Rollen erfüllen.\r\n==Hintergrund==\r\nWahrhaftig beneidet Kriegsherr Bluthauer die Abenteurer, die zu ihm kommen: Im Namen der Horde an vorderster Front zu kämpfen ... Er darf nur befehligen. Nun gut, in seiner Jugend lebte er seine Träume aus, was seinen Lebensabend jetzt erträglich macht. Heute erlebt er den Ruhm des Sieges und den bitteren Geschmack der Niederlange nur durch die Soldaten, die er befehligt. Doch er träumt. In seinen Träumen stirbt er tausend Mal auf unterschiedliche Weise. Manch einer würde seine Träume Alpträume nennen. Aber ER NICHT! In Träumen stirbt er im Kampfgetümmel. Für jeden seiner Tode fallen zehntausende Feinde der Horde vor ihm. Das ist glorreich! Die jungen Abenteurer erinnern ihn sehr stark an sich selbst, als er noch ein junger Krieger der Horde war. \r\n==Aufgaben==\r\nKriegsherr Bluthauer sucht nach Abenteurern, die bereit sind, die Festung der Schwarzfelsorcs zu betreten, zu verwüsten und die Fundamente der Bergzitadelle einzureißen bis ihre Körper kraftlos sind. Dabei möcht er, dass die wichtigen [[Schwarzfels]]dokumente gefunden werden und hat deshalb ein Kopfgeld auf die [[Dunkeleisenzwerge]], ihre hochrangigen Führungskräfte sowie [[General Zornesschmied]] in den [[Schwarzfelstiefen]] ausgesetzt. Und in der [[LBRS|Unteren Schwarzfelsspitze]] stehen [[Hochlord Omokk]], [[Kriegsmeister Voone]] und [[Oberanführer Wyrmthalak]] auf seiner Liste.",},
			["Kriegsherr Krellian"] = { content = "'''Kriegsherr Krellian''' ist der Anführer der [[Naga der Grollflossen]] in den [[Ruinen von Eldarath]] in [[Azshara]]. Er wacht über den [[Tempel von Zin-Malor]] und ist im Besitz der prismatischen Muschel, einer machtvollen Quelle der Magie. Diese Muschel wird von einer seltsamen chaotischen Aura umgeben. Doch Kriegsherr Krellian versteckt sich im Tempel hinter seinen Schlangenwachen der Grollflossen.",},
			["Kriegshetzer Arix'Amal"] = { content = "Kriegshetzer Arix'Amal steht im Dienst des heimlichen Legionslords [[Arrazius der Grausame|Arazzius des Grausamen]] und ist der Oberanführer des [[Invasionspunkt: Vernichter]] auf der [[Höllenfeuerhalbinsel]].",},
			["Kriegshymnenfeste"] = { content = "Der junge und wagemutige [[Garrosh Höllschrei]] errichtete die robuste orcische '''Kriegshymnenfeste''' in der [[Boreanische Tundra|Boreanischen Tundra]]. Man erreicht sie von Orgrimmar aus mit dem Zeppelin. Diese uneinnehmbare Feste ist ein Beweis für die Hartnäckigkeit der Horde. Die Orcs haben viele Schlachten schlagen müssen, um hier in [[Nordend]] Fuß zu fassen. Von hier aus wird die Reise zur [[Eiskrone]] beginnen und die Führungskraft von Höllschreis Sohn soll ihr zum Erfolg verhelfen.",},
			["Kriegshymnenklan"] = { content = "==Geschichte==\r\nDer Kriegshymnenklan zählte zu den ersten orcischen Stämmen, die sich der [[Brennende Legion|Brennenden Legion]] auslieferten. Seine Krieger wurden die Opfer des dämonischen Fluches, den ihr Häuptling [[Grom Höllschrei]] über sie gebracht hatte, und stürzten sich mit wüsten Heldenhymnen über Tod und Vernichtung in jede Schlacht. \r\nAls die [[Horde]] durch das [[Dunkle Portal]] nach [[Azeroth]] strömte, um das Volk der [[Menschen]] zu unterwerfen, blieb dieser Klan auf der orcischen Heimatwelt zurück. Voller Ungeduld warteten sie darauf, in den Landen jenseits des Tores einzufallen und auf dem Schlachtfeld die Überlegenheit ihres Klans beweisen zu können. \r\nJahre vergingen, doch die erbarmunglosen Krieger der Horde erlitten schließlich eine schmähliche Niederlage. Die Kunde ihrer Bezwingung drang bis nach [[Draenor]], und die verbliebenen Stämme bereiteten sich auf einen neuen Feldzug gegen die [[Allianz]] von [[Lordaeron]] vor. Auch [[Grom Höllschrei]] brannte darauf, den Kriegshymnenklan unter wüstem Kampfgeschrei auf die Felder des Todes zu führen.\r\nDoch der Schamane [[Ner'zhul]] verfolgte andere Ziele - er wollte einige magische Artefakte in seinen Besitz bringen, um weitere Portale zu öffnen und der todgeweihten Welt für immer zu entkommen. Seine Pläne stießen bei einigen Kriegsherren auf heftigsten Widerstand, und obwohl Höllschrei dem [[Schamanen]] mißtraute, beugte er sich zunächst seiner absoluten Herrschaft. Die orcischen Stämme, die sich unter [[Ner'zhul]]s dunklem Banner vereint hatten, überraschten die Verteidiger der [[Allianz]] und zogen plündernd durch das Land. \r\nDer Kriegshymnenklan folgte den exakten Anweisungen des alten [[Schamanen]], sammelte in kurzer Zeit die benötigten Reliqien ein und floh zurück ins sichere [[Draenor]]. In der Überzeugung, die [[Horde]] würde eine erneute Invasion planen, schickte König [[Terenas]] seine Armeen durch das [[Dunkle Portal]]. Sie sollten die [[Orcs]] endgültig vernichten und die unheilvolle Pforte für alle Zeiten zerstören. \r\nÜberall in der brennenden Landschaft kam es zu schweren Zusammenstößen zwischen den Streikräften der [[Allianz]] und [[Ner'zhul]]s loyalen Kriegern. [[Grom Höllschrei]] führte seinen mächtigen Klan zu zahlreichen Siegen über die [[Menschen]], doch er musste erkennen, dass [[Ner'zhul]]s Größenwahnsinn sein ganzes Volk dem Untergang preisgegeben hatte. Während der alte Schamane die tosenden Portale öffnete, wurde [[Draenor]] von ungeheuren Vulkanausbrüchen und verheerenden Erdbeben erschüttert. \r\nDie Kriegshymnenorcs erkämpften sich einen Weg zum Dunklen Portal und flohen nach [[Azeroth]], bevor ihre Heimatwelt zerstört wurde. Für sie und die anderen [[Orcs]] gab es nun kein Zurück mehr.\r\nErfolgreich konnte die [[Allianz]] den größten Teil der abtrünnigen Krieger aufspüren. Zwar entzog sich Höllschreis Stamm der Gefangennahme, aber der [[Klan des Blutenden Auges]] wurde eingekesselt und in die Internierungslager von [[Lordaeron]] gebracht. Obwohl die Kriegshymnenorcs ununterbrochen von den [[Menschen]] gejagt wurden, konnten sie sich den unbeugsamen Kampfeswillen der [[Horde]] bewahren und führten einen Guerillakrieg gegen die Unterdrückung ihres Volkes. \r\nViele Jahre vergingen, in denen der abtrünnige Stamm im Geheimen arbeitete und versuchte, sich den wachsamen Blicken der [[Allianz]] zu entziehen. Jedoch fanden sie nie eine Möglichkeit, die internierten [[Orcs]] aus der Lethargie zu reißen, die sie nach dem Zweiten Krieg überkommen hatte. [[Thrall]], der als Gladiator in der Gefängnisfestung [[Burg Durnholde]] aufgewachsen war und sein Volk nie kennen gelernt hatte, entwickelte unter Höllschreis Idealismus eine starke Verbundenheit zur [[Horde]] und den Traditionen der [[Orcs]]. Die Suche nach seiner eigene Herkunft fand aber erst ein Ende, als [[Thrall]] den legendären [[Frostwolfklan]] entdeckte und seinen rechtmäßigen Platz als Häuptling einnahm. \r\nDie [[Frostwolfklan|Frostwölfe]] und der Kriegshymnenklan vereinten sich unter dem Kommando ihres alten Kriegsherrn [[Orgrim Schicksalshammer]] wieder zu einer schlagkräftigen Armee. Gemeinsam erstürmten sie die Internierungslager und befreiten die Stämme aus der Gefangenschaft. Doch als [[Orgrim Schicksalshammer|Schicksalshammer]] im Kampf fiel, stieg [[Thrall]] zum neuen Kriegshäuptling der [[Horde]] auf. \r\nIn den folgenden Monaten konnte er alle Anstrengungen der [[Allianz]] vereiteln, den orcische Aufstand niederzuschlagen. [[Thrall]] versammelte die Klans, die sich der \"neuen [[Horde]]\" angeschlossen hatten, an der Küste [[Lordaeron]]s und segelte nach Westen, ins vergessene Land [[Kalimdor]]. [[Medivh]] hatte ihn vor einer bevorstehenden Invasion der [[Brennende Legion|Brennenden Legion]] gewarnt, und nur dort sollte die Rettung für sein Volkes gewiss sein.\r\nAuf der Suche nach ihrem Schicksal in diesem neuen Land, stießen die Kriegshymnenorcs im Vorgebirge des Steinkrallengipfels überraschend auf Streitkräfte der [[Allianz]]. Entgegen [[Thrall]]s direktem Befehl griff Höllschreis Stamm die [[Menschen]] an, sodass die [[Orcs]] keine andere Wahl hatten, als wieder einmal gegen ihre alten Feinde zu kämpfen. Viele lange Jahre hatte Höllschrei mit der Wut und dem Kampfrausch in seinem Herzen gekämpft, aber nun spürte er wieder die Gegenwart der [[Dämonen]]. \r\n[[Thrall]] konnte eine solche Entartung nicht dulden und schickte den Kriegshymnenklan ins Grenzgebiet der Wälder [[Eschental]]s. Unwissentlich entweihte der Stamm das alte Land und zog den Zorn der [[Nachtelfen]] auf sich. Der Halbgott [[Cenarius]] und seine Kriegerinnen setzten den [[Orcs]] schwer zu. Doch die Kriegshymnenorcs spürten die Anwesenheit einer mysteriösen Macht, die ihnen im Kampf gegen den Halbgott helfen konnte. Der Grubenlord [[Mannoroth]] hatte sein brennendes Blut in eine nahe Quelle ergossen und das dunkle Wasser entfachte die dämonischen Energien der orcischen Krieger von neuem. [[Thrall]] war stets von dem Wunsch beseelt, sein Volk von diesem Fluch zu befreien, doch nun unterlag der Kriegshymnenklan wieder dem verderblichen Einfluss der [[Dämonen]]. Mit der Vernichtung von Cenarius ebneten sie der [[Brennende Legion|Brennenden Legion]] den Weg für die Invasion [[Kalimdor]]s.",},
			["Kriegshymnenschlucht"] = { content = "Die Kriegshymnenschlucht im Süden [[Eschental]]s liegt nahe der Stelle, wo [[Grom Höllschrei]] und seine [[Orcs]] während dem Dritten Krieg ein großes Waldstück abholzten. Einige [[Orcs]] haben sich dort niedergelassen, um die Rodung voranzutreiben und die [[Horde]] mit frischen Rohstoffen zu unterstützen. Diese [[Orcs]] nennen sich die Vorhut des [[Kriegshymnenklan]]s. \r\nDie [[Nachtelfen]] haben jedoch einen gewaltigen Feldzug gestartet, den Wald von [[Eschental]] zurückzuerobern, und dieser Feldzug konzentriert sich in erster Linie darauf, die Vorhut ein für alle Mal aus der Gegend zu vertreiben. So haben sich die [[Schildwachen]] der [[Silberschwingen]] geschworen, nicht eher zu ruhen, bis der letzte Orc aus der Kriegshymnenschlucht verschwunden ist.\r\nDie [[Horde]] hört nicht auf, den heiligen Wald zu roden und benutzt das immergrüne Blattwerk, um ihre Maschinen anzutreiben. Die [[Schildwachen]] der [[Silberschwingen]] sind auf Grund der Zerstörung, die die [[Orcs]] im Wald anrichten, im Krieg mit der Vorhut des [[Kriegshymnenklan]]s. \r\nAllerdings gibt es noch andere Gründe, als die bloße Liebe zu der Natur, für die Verteidigung von ausgerechnet diesem Wald. Der Wald bildet eine strategische Barriere, die es einfach macht, das [[Eschental]] gegen jegliche Art von Großangriffen zu verteidigen. Ohne den Wald, würde Astranaar lediglich ein oder zwei Tage standhalten, bevor es vom [[Brachland]] einverleibt werden würde. \r\nUnter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die [[Allianz]] der [[Horde]] eines der größten Holzvorkommen streitig zu machen. Die Wildnis des [[Eschental]]s wird sich der Macht der [[Horde]] ergeben. Nichts, was die Silberschwingen tun oder sagen, wird sie daran hindern, den territorialen Herrschaftsanspruch durchzusetzen. [[Kalimdor]] gehört der [[Horde]]. Wie könnte die [[Allianz]] es wagen, die [[Horde]] davon abzuhalten, das zu ernten, was rechtens ihres ist.",},
			["Kriegshäuptling"] = { content = "Kriegshäuptling ist der oberte Rang der Horde.\r\nUrsprünglich war die Rolle des Kriegshäuptlings die eines Sprechrohrs des Schattenrats zum Rest der Horde. Der Krieegsäuptling wurde aus den Reihen der Clanoberhäupter gewählt. \r\nDer erste Kriegshäuptling war Schwarzfaust der Zerstörer. Er war die Marionette des Schattenrats und führte deren Befehle willig aus.\r\nDer ihm folgende war [[Orgrim Schicksalshammer]], einer der größten Kriegshelden der gesamten Horde. Unter Schicksalshammer wurde der Schattenrat vernichtet , doch dann wurde die Horde besiegt und der Kriegshäuptling gefangen genommen.\r\nDer Schicksalshammer folgende Kriegshäuptling ist [[Thrall]], der auch heute noch der Herr der Horde ist.Unter Thrall wurde der Schamanismus wiederbelebt und die Horde bekam viele, neue Verbündete, welche sich dem Kriegshäuptling unterordneten.\r\nZeichen der Macht des Kriegshäuptlings ist der [[Schicksalshammer]], die legendäre waffe von Orgrim Schicksalshammer.\r\nAuch andere Orcs verschiedener anderer Horden der Orcs haben den Titel Kriegshäuptling z.B [[Kargath Messerfaust]] und [[Rend schwarzfaust]].",},
			["Kriegsmeister Voone"] = { content = "'''Kriegsmeister Voone''' ist ein grausamer und erbarmungsloser [[Waldtroll]] in Tazz'Alaor, dem Gebiet der Gluthauer in der [[Untere Schwarzfelsspitze|Unteren Schwarzfelsspitze]] ([[LBRS]]). Er ist der General der [[Trolle der Gluthauer]] und ohne seine Kampfpläne werden die [[Orcs des Schwarzfels|Schwarzfelsorcs]] im Chaos versinken.",},
			["Kriegsrituale"] = { content = "„Wälkam in da Jungle, baby!“\r\nDer dürre [[Troll]] mit dem irren Blick schaut sich prüfend um. Seine Augen leuchten entrückt. Die schmalen Nüstern seiner langgezogenen Nase ziehen begierig die Luft um sich herum ein. \r\nDer Himmel hat aufgeklart, es riecht stark nach frisch gefallenem Regen, was die exotischen Aromen des Dschungels zumindest temporär unterdrückt. Die nassen Blätter der Bäume reflektieren die letzten Sonnenstrahlen des Abends und werfen einen unwirklichen Widerschein auf den Dschungel. Eine Horde knatschbunter Papageien krächzt ein regelrechtes Pfeifkonzert in den Wald hinein, als wollten sie den Ausklang des Tages nicht ohne Protest hinnehmen. Ein leichter Wind rauscht durch die Blätter und trägt allerlei alltägliche Geräusche des Waldes mit sich. \r\n„Zuhause“, denkt sich der Troll, „endlich wieder zuhause“, kratzt sich bedächtig am Gemächt und streicht mit seiner Hand vorsichtig über die fruchtbare Erde des Waldbodens. Beinahe zärtlich, wie ein Liebhaber die Wange seiner Geliebten berührt wenn sie im Schlaf ein Alptraum ereilt, fährt er mehrfach über die regennasse Erde. \r\nVorsichtig, als hebe er ein fragiles Knochenfragment auf, nimmt er schließlich eine Handvoll und lässt sie langsam in ein kleines tönernes Gefäß rieseln. Sorgsam verschließt er es mit einem Kork-Pfropfen und lässt es unauffällig in seine Gürteltasche gleiten. \r\nAls er sich erhebt, klart sein Blick auf. Mit einem zutiefst befriedigten Lächeln betrachtet er die kleine Gruppe von Trollen um sich herum. Da und dort ist ein nervöser Blick zu erahnen, die eine oder andere leise geführte Unterhaltung zu vernehmen. Doch zumeist erkennt er in seinen Stammesbrüdern und –schwestern genau jene wilde Entschlossenheit und leidenschaftliche Hingabe, die auch ihn kennzeichnet. \r\nDie Vorbereitungen auf die bevorstehenden Scharmützel laufen auf Hochtouren. Selbst während der Häuptling eine Rede hält, werden die Waffen geschärft, das rechte Totem ausgewählt, die letzten Vorräte verteilt und kurze Floskeln ausgetauscht. \r\nDer dürre Troll mit dem irren Blick lauscht den Worten seines Anführers still. Ab und an nickt er, ein schwer zu deutendes Grinsen auf dem Gesicht. \r\nEin Raunen geht durch die Menge, als der Stammesführer den Namen der Entität nennt, die sich den Dschungel mittlerweile untertan gemacht hat. IHREN Dschungel. \r\n„Unseren Dschungel“, denkt sich der Troll und rümpft die Nase zu einer missbilligenden Fratze. Selbst die jüngsten unter den Trollen haben Legenden gehört. Legenden vom Seelenschinder, der selbst die mächtigsten [[Voodoo]]-Priester des Dschungels korrumpiert hat. \r\nDie Nervosität des kleinen Kommandotrupps hält sich in Grenzen, jedoch scheint ein baldiger Aufbruch vonnöten, wenn nicht die Erregung der Trolle in Hektik umschlagen soll. \r\nFast unmerklich nickt der Häuptling dem dürren Troll kurz zu und verleiht ihm das Wort. Dessen Blick drückt beinahe fanatische Entschlossenheit aus, während er beginnt zu sprechen: \r\n„Wia seinz gekommen, zu beanspruchen dies geheiligtes Boden zurück im Namen der wahren un einzigen Troll-Göttas.“ \r\nDer Troll verbeugt sich tief, senkt sein Haupt bis auf den Boden herab, berührt in einer rituellen Geste den erdigen Boden des Dschungels und konzentriert sich kurz. Ruckartig erhebt er sich wieder und beginnt ein intensives Gebet zu sprechen. Seine Worte sprudeln aus ihm heraus, ohne dass er darüber nachzudenken scheint. \r\n „Möge [[Ula-Tek]], die launische Schlange unsere kraszen Voodoo-Priester mit iher Heil-Powa segnen und mögen ihre todbringenden Bisze nua unser ihr Feinde treffen. \r\n Möge [[Jian´Ky]], der allweise Affe unsan Häuptlingensboszen sein superschlauen, kraszomaten Segen der Schläue un diebischen Hintahältichkeit zuteil werden laszen und sein heftich mächtich Donner unsere Feinde Staub freszen laszen. \r\n Möge unsa alla Vadda of da Djungle, der krasz geile Raptorio [[An´Chras]], uns sein Blessing of War schenken, auf dasz seinä ultrrraphät scharfe Zähne unsa ihr sein Moschaboyos zur Seite stehen werden. \r\n Auch [[Hir´eek]], dat allsehende blinde Fledaviecho, möge unsere Rache gar schröööklich sein laszen, un möge unser Mojo-Schmeiszas seinz Feua vom Himmel regnen laszen. \r\n Möge [[Shadra]]s Gift all jenen in ihr sein Venen dringen, die unz zu bedrohen drohen und der Spinne List un Kraft sei mit unsern verschlagenen Troll-Brüdan un Schwestan.“ \r\nBeinahe tranceartig beendet er das Gebet. Seine Stimme schallt laut und deutlich durch den Wald und scheint jedes andere Geräusch zu übertönen. \r\n„Und zu guta Letzt: Möge unsa Weg von den Daimonas Bäääd´Luut und Log´Inn verschont bleiben.“ \r\nDer Troll nimmt etwas von der fruchtbaren Erde des Dschnungels in seine linke Klaue, schneidet sich kurz mit einem Dolch in selbige, spuckt in das Gemisch, und schmiert sich etwas davon auf die Stirn. \r\n„Sodele – kommts nu zu mia un holtz euch den Segen der Urgötta des Djungles ab, eh – auf dasz Ihre Stärke unz geleiten möge in diesem Wagnis gegen den falschen Blutgott.“ \r\nDer Reihe nach verfährt er mit den Anwesenden in gleicher Weise und verleiht ihnen den rituellen Segen des Dschungels. \r\nEin letztes Mal adressiert er mit hallender Stimme seine Mitstreiter. Seine Worte klingen fatalistisch und bedeutungsschwanger: \r\n„Jo, Compadres – seids bereit füa den Tod! Den eigenen oda den unsara Feinde! Tränkt den heiligen Boden dieses Landes mit dem abgefookten Blute der Dienan des falschen Gottes, auf dasz die Götta unz gewogen sein werden. Guten Krieg!“ \r\nDer dürre Troll mit dem irren Blick schaut sich prüfend um. Seine Augen leuchten entrückt. Die schmalen Nüstern seiner langgezogenen Nase ziehen begierig die Luft um sich herum ein. \r\n„Bueno - Blut und Krieg liegen in der Luft.“ \r\nUm ihn herum machen sich 20 Trolle bereit zu sterben. \r\n''„Geschichten des Dschungels – Erlebnisberichte aus 1001 Ausflügen nach Zul Gurub“''\r\n''Copyright: Kamuka - eingestellt von ??? mit dem Segen der Bokur''",},
			["Krieg der Ahnen"] = { content = "#REDIRECT [[Krieg der Uralten]]", redirect = "Krieg der Uralten",},
			["Krieg der drei Hämmer"] = { content = "(230 Jahre vor Warcraft I)\r\nDie [[Zwerge]] von [[Eisenschmiede]] lebten lange Jahre in Frieden. Aber ihre Gesellschaft wurde zu groß für die Enge ihrer Bergstädte. Der mächtige Hochkönig [[Modimus Ambossar]] regierte die [[Zwerge]] zwar gerecht und weise, doch in der Gesellschaft der [[Zwerge]] waren drei starke Fraktionen entstanden.\r\nDer '''[[Zwerge des Bronzebartklan|Bronzebart-Klan]]''', der von [[Than]] [[Madoran Bronzebart]] beherrscht wurde, stand treu zum Hochkönig und stellte die traditionellen Verteidiger von [[Eisenschmiede]]. Der '''[[Zwerge des Wildhammerklan|Wildhammer-Klan]]''' unter [[Than]] [[Khardros Wildhammer]] bewohnte die Vorgebirge und Felsspalten am Fuß des Berges und strebte nach mehr Einfluss in der Stadt. Die dritte Fraktion, der '''[[Zwerge des Dunkeleisenklan|Dunkeleisen-Klan]]''', wurde von dem Zauberhexer-Than [[Thaurissan]] beherrscht. Die [[Dunkeleisenzwerge]] verbargen sich in den dunkelsten Schatten unter dem Berg und schmiedeten Ränke gegen die [[Bronzebart]] und [[Wildhammer]].\r\nEine Zeit lang wahrten die drei Fraktionen einen brüchigen Frieden, doch als [[Hochkönig Ambossar]] in hohem Alter verschied, kam es zu offenen Spannungen. Die drei herrschenden Klans entfesselten einen Krieg um die Herrschaft über [[Eisenschmiede]]. Viele Jahre tobte der Bürgerkrieg der [[Zwerge]] unter der Erde. Schließlich trieben die [[Bronzebart]], die über das größte stehende Heer verfügten, die [[Dunkeleisenzwerge]] und [[Wildhammer]] in die Verbannung.\r\n[[Khardros Wildhammer]] und seine Krieger zogen durch die Barrierentore von [[Dun Algaz]] nach Norden und gründeten auf dem fernen Gipfel [[Grim Batol]] ihr eigenes Reich. Dort erlebten die [[Wildhammer]] eine Blütezeit und konnten ihre Schatzkammern wieder füllen. Mit [[Thaurissan]] und seinen [[Dunkeleisenzwerge]]n meinte es das Schicksal nicht so gut. In ihrer Verbitterung und Wut nach der Niederlage schworen sie [[Eisenschmiede]] Rache. [[Thaurissan]] führte sein Volk weit in den Süden, wo sie im malerischen [[Rotkammgebirge]] eine Stadt gründeten (der er seinen eigenen Namen gab). Der über viele Jahre hinweg angehäufte Wohlstand ließ die [[Dunkeleisenzwerge]] den Groll gegen ihre Vettern nicht vergessen. Auch die lange seit damals vergangene Zeit half nicht, die Herzen zu erweichen. [[Thaurissan]] und sein Zauberhexerweib [[Modgud]] begannen Feldzüge gegen [[Eisenschmiede]] und [[Grim Batol]]. Die [[Dunkeleisenzwerge]] wollten ganz [[Khaz Modan]] für sich beanspruchen.\r\nDie Armeen der [[Dunkeleisenzwerge]] rückten gegen ihre Vettern vor und hätten um ein Haar die Festungen beider Königreiche vernichtet. Schlussendlich jedoch führte [[Madoran Bronzebart]] seinen Klan zu einem entscheidenden Sieg über [[Thaurissan]]s Armee von Zauberern. [[Thaurissan]] und seine Diener flohen zurück in ihre sichere Stadt und ahnten nichts von den Geschehnissen in [[Grim Batol]], wo es [[Modgud]]s Armee nicht besser gegen [[Khardros Wildhammer]] und seine Krieger erging.\r\nAls [[Modgud]] gegen die feindlichen Krieger vorrückte, wandte sie ihre Kräfte an, um Furcht in ihren Herzen zu säen. Schatten folgten ihrem Gebot, dunkles Getier kroch aus den Tiefen der Erde empor und jagte die [[Wildhammer]] in ihren eigenen Hallen. Schließlich durchbrach [[Modgud]] die Tore und belagerte die Festung selbst. Die [[Wildhammer]] kämpften verzweifelt, [[Khardros Wildhammer|Khardros]] selbst schritt durch das Schlachtengetümmel, um die Zauberhexerin und Königin zu erschlagen. Als ihre Königin gefallen war, flohen die [[Dunkeleisenzwerge]] vor der Wut der [[Wildhammer]]. Sie eilten nach Süden zur Festung ihres Königs, trafen unterwegs jedoch auf die Armeen von [[Eisenschmiede]], die zur Unterstützung von [[Grim Batol]] gekommen waren. Die verbliebenen Streitkräfte der [[Dunkeleisenzwerge]] wurden zwischen den beiden Armeen aufgerieben und vollkommen vernichtet.\r\nDanach wandten sich die vereinten Armeen von [[Eisenschmiede]] und [[Grim Batol]] nach Süden, um [[Thaurissan]] und seinen [[Dunkeleisenzwerge]] endgültig den Todesstoß zu versetzen. Sie waren noch nicht weit gekommen, als sich [[Thaurissan]] in seinem Zorn zu einem Zauber von katastrophalen Ausmaßen hinreißen ließ. [[Thaurissan]] wollte einen übernatürlichen Diener beschwören, der seinen Sieg gewährleisten konnte, und rief die alten Mächte an, die unter der Welt schliefen. Zu seinem Entsetzen war die Kreatur, die erschien, weitaus schrecklicher, als er es sich in seinen kühnsten Alpträumen ausgemalt hätte, und sie führte letztlich seinen Untergang herbei.\r\n'''[[Ragnaros]]''' der Feuerfürst, der unsterbliche Herr und Meister aller [[Feuerelementar|Feuer-Elementargeister]], war von den [[Titanen]] verbannt worden, als die Welt noch jung war. Als Thaurissan [[Ragnaros]] durch seinen Ruf befreit hatte, begann dessen Existenz erneut... in einer feurigen Eruption. [[Ragnaros]]’ apokalyptische Wiedergeburt auf [[Azeroth]] zerschmetterte das [[Rotkammgebirge]] und ließ im Zentrum der Verheerung einen lodernden Vulkan entstehen. Der Vulkan, der den Namen [[Schwarzfels]]spitze erhielt, grenzte im Norden an die [[Sengende Schlucht]] und im Süden an die [[Brennende Steppe]]. Thaurissan wurde ein Opfer der Kräfte, die er entfesselt hatte, und seine überlebenden Brüder wurden von [[Ragnaros]] und seinen Elementargeistern versklavt. Sie hausen bis auf den heutigen Tag in der Spitze.\r\nAls König [[Madoran Bronzebart]] und König [[Khardros Wildhammer]] die schrecklichen Verwüstungen und Feuersbrünste sahen, die in den Bergen im Süden ausbrachen, ließen sie ihre Armeen anhalten und kehrten schnellstens in ihre Königreiche zurück, da sie nicht den furchtbaren Zorn von [[Ragnaros]] auf sich ziehen wollten.\r\nDie [[Bronzebart]]s kehrten nach [[Eisenschmiede]] zurück und bauten ihre prächtige Stadt wieder auf. Die [[Wildhammer]] kehrten nach [[Grim Batol]] zurück. Doch [[Modgud]]s Tod hatte den Ruch des Bösen in der Bergfestung hinterlassen und die [[Wildhammer]] fanden sie unbewohnbar vor. Verbitterten Herzens beklagten sie den Verlust ihrer geliebten Heimat. König [[Madoran Bronzebart]] bot den [[Wildhammer]]n ein Refugium in [[Eisenschmiede]] an, aber die [[Wildhammer]] weigerten sich standhaft. [[Khardros]] führte sein Volk nach Norden in die Länder von [[Lordaeron]]. Die Wildhammer ließen sich in den dichten Wäldern des [[Hinterland]]es nieder und gründeten die Stadt [[Nistgipfel]], wo die [[Wildhammer]] im Einklang mit der Natur lebten und sogar ein Bündnis mit den mächtigen [[Greife]]n der Gegend eingingen.\r\nDa sie Beziehungen und Handel mit ihren Vettern aufrechterhalten wollten, bauten die [[Zwerge]] von [[Eisenschmiede]] zwei gewaltige Brückenbögen, die so genannte [[Thandolübergang|Thandol-Spange]], um die Kluft zwischen [[Khaz Modan]] und [[Lordaeron]] zu überbrücken. Durch den beiderseitigen Handel brachten es beide Königreiche zu Wohlstand. Nach dem Tod von [[Madoran Bronzebart]] und [[Khardros Wildhammer]] ließen ihre Söhne gemeinsam zwei große Statuen zu Ehren ihrer Väter errichten. Die beiden Statuen wachten über den Pass in die Südländer, die im Kielwasser von [[Ragnaros]]’ versengender Präsenz vulkanisch geworden waren. Sie dienten als Warnung für alle, die Eroberungspläne gegen die Königreiche der [[Zwerge]] hegten, und als Mahnung, welch hohen Preis die [[Dunkeleisenzwerge]] für ihre Verbrechen zahlen mussten.\r\nDie beiden Königreiche blieben einander einige Jahre eng verbunden, doch die Schrecken, die sie in [[Grim Batol]] sahen, hatten die Wildhammer sehr verändert. Sie lebten jetzt oberirdisch an den Hängen des [[Nistgipfel]]s, anstatt ein gewaltiges Reich im Inneren des Berges zu schaffen. Die ideologischen Differenzen zwischen den beiden verbliebenen Zwergenklans ließen sie schließlich getrennte Wege gehen.\r\n'''Quelle:''' wow-europe.com",},
			["Krieg der Sandstürme"] = { content = "Als '''Krieg der Sandstürme''' wird der [[Krieg]] bezeichnet, den die [[Nachtelfen]] in [[Silithus]] gegen die [[Silithiden]] schlugen.\r\n[[Fandral Hirschhaupt]] führte den Sturm, sein Sohn Valstann an seiner Seite. Sie hatten die Schlucht bewusst als den Ort dieser Schlacht gewählt, damit ihre Flanken gegen die unendliche Flut der [[Silithiden]] geschützt sein würden. Shiromar ritt ein kurzes Stück hinter ihnen und fokussierte ihre gesamte Energie auf ihre Zauber, mit denen sie die Kämpfer an vorderster Front unterstützte. \r\nSie hatten sich bis zum Ausgang der Schlucht vorgekämpft. Fandral und Valstann drängten ihre Gegner Schlag um Schlag weiter zurück, dicht gefolgt von den mächtigsten und tapfersten Kriegerinnen, die die Armee der [[Schildwache]]n zu bieten hatte, sowie einer Vielzahl von [[Druide]]n und [[Mondpriester]]innen, die alle ihr bestes gaben, die Kämpfer an vorderster Stelle am Leben zu halten. Es schien fast, als ob auf jeden gewaltigen [[Silithiden]]schwarm, der vor den [[Nachtelfen]] fiel, hunderte mehr an seine Stelle traten. So hatten sie bereits die letzten Tage gekämpft, seit die Nachricht der Invasion der [[Silithiden]] eingetroffen war und Fandral die Armee zu den Waffen gerufen hatte. \r\nPriesterin Shiromar und ihre Gefährtinnen hatten alle genug Energie gesammelt, um gemeinsam den Segen [[Elune]]s herbeizurufen; eine Säule aus blendendem Licht stürzte auf den Ausgang der Schlucht herab und vernichtete innerhalb eines einzigen Augenblicks den gesamten Schwarm, der ihnen zuvor den Ausgang verwehrt hatte. \r\nAugenblicklich wurde die Luft erfüllt vom Sirren unzähliger Insektenflügel. Einer nach dem anderen erschienen am Rand der Schlucht die geflügelten [[Qiraji]] und stürzten sich nach kurzem Zögern unvermittelt mitten in die Reihen der [[Druide]]n unter ihnen. \r\nFandral führte die Front aus der Schlucht heraus und in die offene Wüste vor ihnen, über Berge von [[Silithiden]]kadavern. Hinter sich hörten sie das Summen der [[Qiraji]] und die Todesschreie ihrer Heiler, während die rasiermesserscharfen Klauen der [[Qiraji]] den Wüstenboden mit dem Blut der [[Nachtelfen]] tränkten. Fandral beschleunigte sein Vordringen, um den unterstützenden Rängen mehr Raum zum Ausweichen zu bieten. \r\nAls sich ihr Blick einer fernen Hügelkette zuwandte, sah Shiromar eine gewaltige Welle flügelloser [[Qiraji]] über den Hügel rollen, bis vom Boden unter ihnen nichts mehr zu sehen war. Inmitten der Fußsoldaten der [[Qiraji]] bewegte sich eine Monstrosität von gigantischen Ausmaßen auf sie zu, die unablässig mit ihren klauenbewehrten Gliedmaßen Zeichen gab und in der schrecklichen Sprache der Insektenvölker Befehle brüllte. \r\nUnter all dem Lärm und dem chaotischen Summen, das über dem Schlachtfeld ertönte, schien sich in der Gegenwart des Ungeheuers ein Wort herauszukristallisieren: [[Rajaxx]], Rajaxx, Rajaxx... Shiromar konnte zwar die Worte ihrer Gegner nicht verstehen, doch es schien ihr, als sei dies der Name der Kreatur. \r\nAls die Welle auf die [[Nachtelfen]] niederging, ertönte in der Ferne ein großes Horn. Von Ost und West stürmten zahllose [[Nachtelfen]] auf das Feld, um ihren bedrängten Gefährten zu Hilfe zu eilen. Mit einem markerschütterndem Schrei stürzten sich Fandral und Valstann mitten ins Herz des heranrückenden Schwarms, und beide Seiten prallten mit Wucht aufeinander, genau als die neu eingetroffenen Kämpfer auf beiden Flanken der [[Qiraji]] jeden gefallenen Elfen mit dem Leben hunderter [[Qiraji]] vergolten. \r\nShiromar war sich gewiss, dass die Schlacht gewonnen sei; doch selbst als die Schatten lang wurden und sich die Nacht über [[Silithus]] senkte, hörten die Kämpfe nicht auf. Inmitten der Schlacht trafen Fandral und Valstann schließlich auf den General der [[Qiraji]] selbst. \r\nEinigen Angriffen der geflügelten [[Qiraji]] knapp entkommen blickte Shiromar dorthin, wo Vater und Sohn verzweifelt gegen den Anführer der [[Qiraji]] kämpften. Die Reihen der [[Qiraji]] fingen endlich an, sich zu lichten, und ihr Anführer schien dies zu bemerken. Mit einem gewaltigen Sprung entzog sich die Kreatur dem Zugriff ihrer Gegner und verschwand jenseits des Hügels, wo Shiromar sie zum ersten Mal gesichtet hatte. Die verbleibenden Insektoiden fielen kurze Zeit später unter dem Ansturm der [[Nachtelfen]]. \r\nAn diesem Abend wurden Wachen aufgestellt, und die elfischen Streitkräfte rasteten. Fandral wusste, dass die Bedrohung durch die [[Qiraji]] noch nicht gebannt war; der nächste Tag würde mit Sicherheit eine weitere erbitterte Schlacht bereithalten. Shiromar konnte nur in kurzen Intervallen schlafen. Die Schreie der Toten hallten immer noch in ihren Ohren, doch die Wüste um sie herum schwieg. \r\nAls sich die Truppen am Morgen neu formierten und den Hügel erklommen, legte sich eine unheilvolle Stille über das Land. Shiromar suchte den Horizont ab, doch von den [[Qiraji]] und den [[Silithiden]] war weit und breit nichts zu sehen. Fandral hatte gerade den Befehl gegeben, auszurücken, als ein Bote mit einer dringenden Nachricht eintraf: der Südwindposten wurde angegriffen. \r\nFandral dachte darrüber nach, seine Truppen zurückzuziehen um den Posten zu verteidigen, doch er war sich der Tatsache bewusst, dass dieser Zug dem Feind die Tür für eine erneute Invasion weit öffnen würde. Sie wussten immer noch nicht, wie groß die Zahl der feindlichen Armee war, oder was dieses unbekannte Volk sonst noch an Einheiten auf das Feld führen konnte. Valstann erriet die Gedanken seines Vaters, und bot ihm an, eine Abteilung zu dem umkämpften Posten zu führen, so dass Fandral hier bleiben und die Qiraji weiter zurückhalten konnte. \r\nAus der Nähe konnte Shiromar den Rest des Gespräches belauschen: \r\n„Was, wenn es eine Falle ist?“ fragte Fandral. \r\n„Wir müssen dieses Risiko eingehen, Vater.“ entgegnete Valstann. „Ich werde gehen. Ich werde die Stadt verteidigen und siegreich heimkehren. Ich werde die Ehre deines Namens aufrechterhalten.“ \r\nFandral nickte, zögerlich. „Wenn du lebend zurückkommst, soll mir das Lohn genug sein.“ \r\nSo sammelte Valstann seine Abteilung, und Fandral ließ seinen Sohn nach Südwind ziehen. Shiromar machte sich Sorgen über die Teilung der Streitkräfte, doch sie verstand die Notwendigkeit der Entscheidung. \r\nWährend der nächsten Tage kämpften Shiromar und die anderen gegen Welle um Welle von Silithiden, die aus den umliegenden Insektenbauten hervorquollen. Doch von den Qiraji selbst fehlte weiterhin jegliche Spur. Langsam beschlich Shiromar ein äußerst ungutes Gefühl. Es war ein böses Omen, dass sich die Meister der Silithiden so lange nicht hatten blicken lassen. Sie hatte Angst um Valstann, und sie konnte oftmals während kurzen Pausen im Kampf sehen, wie Fandral voller Sorge zum Horizont blickte, wo er im Stillen hoffte, seinen Sohn zurückkehren zu sehen. \r\nAm dritten Tag, als die Sonne am höchsten Punkt stand, kehrten die Qiraji zurück. Das Summen der Insektenflügel erfüllte erneut die Luft; erneut verschlangen die zahllosen Soldaten der Insektenherrscher den Horizont. Sie reihten sich vor Fandrals Armee wie der Schatten einer gewaltigen Wolke auf, die die Sonne verdeckte... und hielten dann inne. \r\nUnd warteten. \r\nFandral lies seine Truppen aufmarschieren und bezog selbst an vorderster Front Stellung, während Sturmkrähen am Himmel ihre Kreise zogen und Druiden in Bärengestalt erwartungsvoll im Sand scharrten. Die Masse der Insekten teilte sich vor ihnen. Die riesenhafte Gestalt des Generals trat hervor, in seinen Klauen einen geschundenen und blutüberströmten Körper. [[Rajaxx]] baute sich vor den Reihen der Qiraji auf und hob [[Valstann Hirschhaupt]] hoch, so dass ihn alle sehen konnten. \r\nEine Welle des Schreckens lief durch die Armee der [[Nachtelfen]]. Shiromar fühlte, wie eine unglaubliche Leere von ihrem Innersten Besitz ergriff. Fandral stand in der Mittagssonne, stumm, und wusste in diesem Moment, dass Südwind gefallen war, und sein Sohn mit ihm. Er verfluchte sich selbst dafür, dass er den Jungen hatte ziehen lassen, und so stand er da, erstarrt vor Angst, Schuld und Verzweiflung. \r\nIn den Klauen des Generals rührte sich Valstann plötzlich und sprach zu seinem Peiniger, doch er war zu weit weg um gehört zu werden. \r\nMit einem Mal war der Bann gebrochen, unter dem Fandral gestanden hatte. Wie ein zürnender Sturm schoss der Vater nach vorne, und auf seinen Ruf hin beugte sich die gesamte Macht der [[Nachtelfen]] dieser einen abscheulichen Kreatur entgegen... doch der Weg war zu weit. Noch bevor der General sich bewegte wusste Shiromar, dass sie Valstann niemals rechtzeitig erreichen würden. \r\nDer [[Qiraji]] legte seine zweite Klaue um Valstanns mishandelten Körper, und drückte mit beiden einmal kräftig zu... und zog sie auseinander. Die beiden Hälften des jungen [[Nachtelfen]] fielen bewegungslos zu Boden. \r\nFandral wurde langsamer, stoppte, und fiel auf seine Knie. Die nachrückenden Nachtelfen teilten sich um ihn, umflossen ihn wie ein reißender Strom aus Zorn und Stahl. Als die beiden Fronten aufeinanderprallten, wehte von Osten her ein Sandsturm über das Schlachtfeld, der alles Licht auslöschte. Hustend, geblendet fühlte Shiromar, wie der Wind sie unnachgiebig zu Boden zwang. Sie versuchte, ihre Augen so gut es ging zu schützen, während der Wind ihre Ohren betäubte und die Schreie ihrer Gefährten sanft überdeckte. \r\nInmitten des Chaos erblickte sie verschwommen die Gestalt des Generals der Qiraji, nicht weit von ihr, wie er durch die Reihen der Nachtelfen pflügte und mit seinen gewaltigen Klauen eine Spur verstümmelter Körper hinter sich her zog. Dann sah sie Fandral, der mit letzter Kraft den Rückzug befahl. Sie hatten versagt; Silithus war verloren. \r\nViele der folgenden Ereignisse schmolzen in ihrer Erinnerung zu wenigen Augenblicken zusammen, obwohl sie tatsächlich Tage gebraucht hatten. Fandral führte den kläglichen Rest seiner Armee aus Silithus und über die schmalen Bergpässe hinab in den [[Un'Goro]] Krater. Die Silithiden und die Qiraji folgten ihnen dicht auf den Fersen und verschlangen all diejenigen, die hinter den Schutz der elfischen Hauptstreitmacht zurückfielen. \r\nSobald sie den [[Un'Goro]] Krater erreicht hatten, geschah jedoch etwas seltsames. Anscheinend hatten sich die Qiraji zurückgezogen, als die Streitmacht den Rand des Kraters erreicht hatte. Der Erzdruide sammelte seine verbleibenden Truppen im Herzen des Kraters und gab den Befehl, die Stellung zu halten. Vorerst war das ständige Kämpfen, Fliehen und Sterben vorbei. Doch die Nachtelfen hatten eine bittere Niederlage einstecken müssen, und das Verhalten von Fandral Hirschhaupt hatte sich von Grund auf geändert. \r\nShirmor sah, wie Fandral Wache stand. Er blickte vom Feuersäulengrat hinab auf die Ebenen unter ihnen, den Dampf aus dem vulkanischen Gestein im Rücken. Das orangene Leuchten der Lava erhellte sein Gesicht, eine steinerne Maske, die ungeahnten Schmerz verbarg – Schmerz, den nur Eltern kennen, die ihre Kinder überlebt haben. \r\nDer plötzliche Rückzug der Qiraji überraschte Shiromar. Je mehr sie darüber nachdachte, desto mehr erinnerte sie sich an die Legenden über den Krater, Gerüchte, dass er in vorgeschichtlichen Zeiten von den [[Titanen]] selbst geschaffen worden war. Vielleicht wachten sie immer noch über diese Gegend. Vielleicht lag auf dem Krater immer noch ihr Segen. Eines war auf jeden Fall sicher: Wenn sie nicht bald eine Möglichkeit finden würden, dem Vordringen der Insektenvölker Einhalt zu gebieten... \r\n...würde [[Kalimdor]] für immer verloren sein. \r\nDer Krieg dauerte noch lange, schmerzhafte Monate. Igrendwie schaffte es Shiromar, eine Schlacht nach der anderen zu überleben, doch die Nachtelfen waren von nun an stets in der Defensive, stets unterlegen, und immer zum Rückzug gezwungen. \r\nAus Verzweiflung flehte Fandral den [[Bronzener Drachenschwarm|Schwarm der bronzenen Drachen]] um Hilfe an. Ihre ursprüngliche Weigerung, sich in die Angelegenheiten der sterblichen einzumischen, wandelte sich in Unterstützung, nachdem die Qiraji die [[Höhlen der Zeit]] angegriffen hatten, die Heimat und Brutstätte von [[Nozdormu]], dem Zeitlosen. \r\nNozdormus Erbe, [[Anachronos]], gewährte den Elfen die Unterstützung des [[Bronzener Drachenschwarm|bronzenen Drachenschwarms]] in ihrem Krieg gegen die Qiraji. Jeder Nachtelf, der ein Schwert tragen oder einen Zauber wirken konnte, schloss sich der Armee an, und mit vereinten Kräften machten sich die Nachtelfen und die Drachen auf, Silithus zurückzuerobern. \r\nDoch selbst mit der Macht der Drachen auf ihrer Seite war die schiere Masse der Qiraji und Silithiden zu groß. Und so rief [[Anachronos]] die Nachkommen der übrigen Drachenschwärme zu sich: [[Merithra des Traums]], ein Kind [[Ysera]]s und Abgesandte des [[Grüner Drachenschwarm|grünen Drachenschwarms]]; [[Caelestrasz]], ein Kind [[Alexstrasza]]s und Abgesandter des [[Roter Drachenschwarm|roten Drachenschwarms]]; und schließlich [[Arygos]], ein Kind von [[Malygos]] und Abgesandter des [[Blauer Drachenschwarm|blauen Drachenschwarms]].\r\nDie Drachen und die geflügelten Qiraji stießen am wolkenlosen Himmel über [[Silithus]] aufeinander, als die gesamte nachtelfische Streitmacht Kalimdors durch die Wüste zog. Doch selbst in diesem Augenblick war der Fluss der Qiraji und Silithiden ungebrochen. \r\nSpäter hörte Shiromar Gerüchte, dass die Drachen bei einem Flug über die uralte Hauptstadt der Qiraji, aus der die Insekten herausströmten, etwas fürchterliches erblickt hatten, etwas, das auf eine noch viel ältere, schreckliche Präsenz hindeutete, die hinter dem Ansturm der Insekten lauerte. \r\nVielleicht war es diese Erkenntnis, welche die Drachen und Fandral zu ihrem endgültigen, verzweifelten Plan führte. Anstatt die Stadt einzunehmen würden sie die Qiraji dort hinter einer Barriere einsperren, die sie so lange festhalten würde, bis eine bessere Lösung gefunden werden konnte. \r\nUnd so begann mit der Hilfe der vier Drachenschwärme der letzte Marsch auf die Hauptstadt der Qiraji. Shiromar ritt hinter Fandral, während um sie herum die Leichen geflügelter Qiraji vom Himmel regneten. Hoch über ihren Häuptern dezimierten die Drachen die insektoiden Soldaten. Die Nachtelfen und die Drachen bildeten zusammen eine langsam vorrückende, unaufhaltsame Mauer, die die Qiraji immer weiter zu ihrer Hauptstadt [[Ahn'Qiraj]] zurückdrängte. \r\nDoch vor den Toren der Stadt wandte sich das Blatt. Sogar die vereinten Kräfte konnten nur mit knapper Not ihre Stellungen halten. Ein weiteres Vordringen war unmöglich. [[Merithra des Traums]], [[Caelestrasz]] und [[Arygos]] beschlossen, auf eigene Faust in die Stadt vorzustoßen und die [[Qiraji]] lange genug aufzuhalten, so dass [[Anachronos]], Fandral und die verbleibenden Druiden und Mondpriesterinnen die magische Barriere errichten konnten. \r\nSo stürzten sich die drei Drachen und ihre Gefährten in die Heerscharen der Qiraji, mitten in die Stadt, in der bangen Hoffnung, dass ihr Opfer nicht vergebens sein würde. \r\nAußerhalb der Tore rief Fandral die Druiden zu sich, und gemeinsam mit [[Anachronos]] konzentrierten sie ihre Energien, während der Drache die magische Barriere errichtete. Innerhalb der Mauern fielen die Drachen vor der überwältigenden Macht der heranstürmenden Qiraji. \r\nShiromar sammelte ihre Energien und sprach den Segen ihrer Göttin [[Elune]], als die Barriere vor den Augen der Nachtelfen Gestalt annahm. Fels, Stein und Wurzeln erhoben sich aus dem Sand und formten eine unüberwindbare Mauer. Sogar die geflügelten Soldaten, die versuchten über den Wall zu fliegen, wurden von einer unsichtbaren Barriere zurückgehalten, die sie nicht durchdringen konnten. Die Qiraji, die außerhalb der Barriere waren, fielen innerhalb kürzester Zeit. Die Leichen zahlloser Qiraji, Nachtelfen und Drachen waren über dem weiten Wüstensand verstreut. \r\n[[Anachronos]] deutete auf einen [[Skarabäus]], der zu seinen Füßen im Sand krabbelte. Die Kreatur erstarrte und wurde mit einem Mal flach; der Drache hatte sie in einen riesigen metallenen Gong verwandelt. Steine in der Nähe des Walls gerieten in Bewegung und formten einen Altar, auf dem der Gong platziert wurde.\r\nDer große Drache deutete auf ein Gliedmaß eines seiner gefallenen Gefährten. [[Anachronos]] stimmte einen stillen Singsang an, und kurz darauf verformte sich der Gegenstand zu einem Szepter. Der Drache erklärte Fandral, dass der Gong nur mit dem Szepter geschlagen werden müsse, wenn jemals ein Sterblicher die magische Barriere der uralten Stadt überschreiten wolle. Mit diesen Worten übergab [[Anachronos]] das Szepter dem Erzdruiden. \r\nFandral betrachtete den Gegenstand, sein Gesicht verzerrt von Schmerz und Verachtung. „Niemals werde ich mit den Qiraji, mit Silithus oder mit Euch je wieder etwas zu tun haben! NIEMALS!“ Er schleuderte das Szepter voller Zorn gegen die magischen Tore. Das Szepter zerbarst in tausend Stücke. Fandral wand sich ab. \r\n„Du würdest unseren Bund wegen deines Stolzes aufs Spiel setzen?“ fragte der Drache. \r\nFandral drehte sich [[Anachronos]] ein letztes Mal zu. „Die Seele meines Sohns wird in diesem leeren Sieg keinen Frieden finden, Drache. Aber ich werde ihn zurückholen. Auch wenn es mich Jahrtausende kosten wird... ich werde meinen Sohn zurückholen!“ Und so schritt Fandral an Shiromar vorbei... \r\n...so voller Hass und Scham, ein gebrochener, einsamer Mann. Sie konnte ihn immer noch vor ihren Augen sehen, fast so, als wäre er hier und jetzt bei ihr, als läge all dies nicht bereits eintausend Jahre zurück.\r\n'''Quelle:'''",},
			["Krieg der Spinne"] = { content = "==Entstehung des Lichkönigs==\r\n- Teil 4 -\r\n===Krieg der Spinne===\r\nZehn Jahre lang baute [[Ner'zhul]] das Zentrum seiner Macht in [[Nordend]] aus. Eine große Zitadelle wurde über dem [[Eiskrone]]gletscher errichtet, um die wachsenden Legionen der [[Untote]]n aufzunehmen. Doch ein einsames, schattenhaftes Reich stellte sich dem zunehmenden Einfluss des [[Lichkönig]]s entgegen. Das alte unterirdische Königreich [[Azjol-Nerub]], das von einem Volk böser humanoider Spinnen gegründet worden war, schickte Elitekrieger aus, um [[Eiskrone]] anzugreifen und dem irren Machtstreben des [[Lichkönig]]s ein Ende zu bereiten. Zu seinem großen Ärger musste [[Ner'zhul]] feststellen, dass die bösartigen [[Neruber]] nicht nur gegen die [[Seuche]] immun waren, sondern auch gegen seine telepathische Beeinflussung. Die Spinnen-Lords der [[Neruber]] befehligten unermessliche Streitkräfte und verfügten über ein unterirdisches Netzwerk, das sich fast über die halbe Breite von [[Nordend]] erstreckte. Mit ihrer Taktik, die Festungen des [[Lichkönig]]s anzugreifen und sich sofort wieder zurückzuziehen, vereitelten sie immer wieder seine Bemühungen, sie auszuschalten. Schließlich gewann [[Ner'zhul]] seinen Krieg gegen die [[Neruber]] durch schiere Erschöpfung. Mit Unterstützung der wütenden [[Schreckenslords]] und seiner zahllosen untoten Krieger fiel der [[Lichkönig]] in [[Azjol-Nerub]] ein und ließ die unterirdischen Tempel über den Köpfen der Spinnen-Lords einstürzen. Die [[Neruber]] waren zwar immun gegen seine [[Seuche]], doch [[Ner'zhul]]s zunehmende nekromantischen Kräfte ermöglichten ihm, die Kadaver der Spinnenkrieger wiederzuerwecken und seinem Willen zu unterwerfen. Als Anerkennung ihrer Zähigkeit und Furchtlosigkeit übernahm [[Ner'zhul]] die eigenwillige Architektur der [[Neruber]] für seine eigenen Festungen und Gebäude. Da er sein Königreich nun unangefochten beherrschte, begann der [[Lichkönig]] mit den Vorbereitungen für seine wahre Mission. Mit seinem grenzenlosen Bewusstsein drang der [[Lichkönig]] in die Länder der [[Menschen]] ein und rief jede dunkle Seele, die bereit war, ihm zuzuhören …\r\n==Siehe auch==\r\n* [[Entstehung des Lichkönigs]]\r\n* [[Kil'jaeden und der neue Pakt]]\r\n* [[Eiskrone und Frostthron]]\r\n* [[Krieg der Spinne]]\r\n* [[Kel'Thuzad und der Kult der Verdammten]]\r\n* [[Entstehung der Geißel]]\r\n* [[Ein Erbe …]]",},
			["Krieg der Uralten"] = { content = "(10.000 Jahre vor Warcraft I)\r\nDie unbekümmerte Anwendung der [[Magie]] seitens der [[Hochgeborene]]n sandte Schockwellen vom [[Brunnen der Ewigkeit]] durch das Große Dunkle Jenseits aus. Die herausströmenden Energiewellen wurden von schrecklichen fremden Wesen gespürt. [[Sargeras]] – der Großfeind allen Lebens, Verwüster der Welten – fühlte die mächtigen Wellen und wurde zu ihrem fernen Ursprung hingezogen. Als er die urzeitliche Welt [[Azeroth]] erkundete und die grenzenlose Energie des [[Brunnen der Ewigkeit|Brunnens der Ewigkeit]] spürte, wurde er von einem unstillbaren Hunger erfüllt. Der große, dunkle Gott der Namenlosen Leere beschloss, die aufstrebende Welt zu zerstören und ihre Energien für sich zu beanspruchen.\r\n[[Sargeras]] sammelte seine gewaltige [[Brennende Legion]] und machte sich zur ahnungslosen Welt [[Azeroth]] auf. Die [[Brennende Legion|Legion]] bestand aus einer Million kreischender [[Dämon]]en, samt und sonders aus den entlegensten Winkeln des Universums gerissen, und die [[Dämon]]en gierten nach Eroberungen. [[Sargeras]]’ Offiziere, [[Archimonde]] der Entweiher und [[Mannoroth]] der Zerstörer, bereiteten ihre höllischen Diener auf den entscheidenden Schlag vor.\r\n[[Königin Azshara]] erlag in der schrecklichen Ekstase ihrer [[Magie]] der unentrinnbaren Macht von [[Sargeras]] und willigte ein, ihm Zutritt zu ihrer Welt zu gewähren. Sogar ihre [[hochgeborene]]n Bediensteten ergaben sich der unausweichlichen Verderbnis der [[Magie]] und beteten [[Sargeras]] als ihren Gott an. Um ihre Verbundenheit mit der [[Brennende Legion|Legion]] zu beweisen, unterstützten die [[Hochgeborene]]n ihre [[Königin Azshara|Königin]] dabei, ein weites, wirbelndes Portal in den Tiefen des [[Brunnen der Ewigkeit|Brunnens der Ewigkeit]] zu öffnen.\r\nKaum waren alle Vorbereitungen abgeschlossen, begann [[Sargeras]] mit seiner katastrophalen Invasion von [[Azeroth]]. Die [[Krieger]]-[[Dämon]]en der [[Brennende Legion|Brennenden Legion]] stürmten durch den [[Brunnen der Ewigkeit]] in die Welt und belagerten die schlafenden Städte der [[Nachtelfen]]. Unter der Führung von [[Archimonde]] und [[Mannoroth]] schwärmte die [[Brennende Legion|Legion]] über ganz [[Kalimdor]] aus und ließ nur Asche und Elend hinter sich zurück. Die [[Dämon]]en-[[Hexenmeister]] riefen die sengenden Höllenbestien herbei, die wie Meteore in die anmutigen Türme der Tempel [[Kalimdor]]s krachten. Eine Bande brennender, blutrünstiger Killer, Verdammniswache genannt, marschierte über [[Kalimdor]]s Felder und schlachtete alles ab, was sich ihr in den Weg stellte. Meuten wilder, [[dämon]]ischer Teufelshunde zogen ungehindert durch das Land. Die tapferen [[Krieger]] der [[Kaldorei]] griffen zwar zu den Waffen, um ihre alte Heimat zu verteidigen, mussten aber Zoll für Zoll vor dem Ansturm der [[Brennende Legion|Legion]] zurückweichen.\r\n[[Malfurion|Malfurion Sturmgrimm]] blieb es überlassen, Hilfe für sein bedrängtes Volk zu finden. \r\n[[Malfurion|Sturmgrimm]], dessen Bruder [[Illidan]] selbst die [[Magie]] der [[Hochgeborene]]n praktizierte, war erbost über die zunehmende Verderbtheit der Oberschicht. [[Malfurion]] brachte [[Illidan]] dazu, von seiner gefährlichen Besessenheit abzulassen, und machte sich auf die Suche nach [[Cenarius]], um Widerstandskämpfer um sich zu scharen. Die wunderschöne junge [[Priester]]in [[Tyrande]] willigte ein, die Brüder im Namen von [[Elune]] zu begleiten. Insgeheim waren [[Malfurion]] und [[Illidan]] beide in die idealistische [[Priester]]in verliebt, doch [[Tyrande]]s Herz gehörte allein [[Malfurion]]. [[Illidan]] missfiel die zarte Romanze zwischen seinem Bruder und [[Tyrande]], doch er wusste, sein Herzeleid war nichts im Vergleich zu den Schmerzen seiner Sucht nach [[Magie]].\r\n[[Illidan]], der von den stärkenden Energien der [[Magie]] abhängig geworden war, unternahm jede Anstrengung, den fast überwältigenden Wunsch nach neuerlicher Nutzung der Energien des [[Brunnen der Ewigkeit|Brunnens]] in sich zu unterdrücken. Mit Hilfe von [[Tyrande]]s geduldiger Unterstützung konnte er sich beherrschen und seinem Bruder helfen, den einsiedlerischen Halbgott [[Cenarius]] zu finden. [[Cenarius]], der auf der hochheiligen [[Mondlichtung]] auf dem fernen Berg [[Hyjal]] lebte, willigte ein, den [[Nachtelfen]] zu helfen, indem er die alten Groß[[drachen]] suchte und ihre Hilfe erbat. Die Groß[[drachen]], die von dem großen roten Leviathan [[Alexstrasza]] angeführt wurden, willigten ein, ihre mächtigen Schwärme zu schicken und sich den [[Dämon]]en und deren infernalischen Meistern entgegenzustellen.\r\n[[Cenarius]] rief die Geister der verzauberten Wälder herbei, stellte eine Armee von alten Baummännern zusammen und führte sie als seine Infanterie in einen verwegenen Kampf gegen die [[Brennende Legion|Legion]]. Als die Verbündeten der [[Nachtelfen]] auf [[Azshara]] Tempel und den [[Brunnen der Ewigkeit]] marschierten, brach allumfassender Krieg aus. Trotz der Stärke der neuen Verbündeten wurde [[Malfurion]] und seinen Mitstreitern klar, dass die [[Brennende Legion|Legion]] nicht allein durch Kampfkraft besiegt werden konnte.\r\nWährend der titanische Kampf in [[Azshara]]s Hauptstadt tobte, wartete die getäuschte [[Königin Azshara|Königin]] nervös auf die Ankunft von [[Sargeras]]. Der Fürst der [[Brennende Legion|Legion]] bereitete sich darauf vor, die verwüstete Welt durch den [[Brunnen der Ewigkeit]] zu betreten. Als sich sein unvorstellbar riesiger Schatten der brodelnden Oberfläche des [[Brunnen der Ewigkeit|Brunnens]] näherte, rief [[Königin Azshara|Azshara]] ihre mächtigsten Anhänger unter den [[Hochgeborene]]n zu sich. Nur wenn sie ihre vereinte [[Magie]] zu einem einzigen Zauber bündelten, konnten sie ein Portal erschaffen, das groß genug für [[Sargeras]] sein würde.\r\nWährend der Kampf auf [[Kalimdor]]s brennenden Feldern wütete, nahmen die Ereignisse eine schreckliche Wendung. Einzelheiten des Vorfalls gingen im Lauf der Zeit verloren, aber man weiß, dass [[Neltharion]], der Groß[[drachenaspekt]] der Erde, während eines entscheidenden Gefechts gegen die [[Brennende Legion]] den Verstand verlor. Flammen und Wut loderten aus seiner dunklen Haut empor. Der brennende [[Drachen|Großdrache]] gab sich selbst den Namen [[Todesschwinge]], wandte sich gegen seine Brüder und vertrieb die restlichen [[Drachen]]schwärme vom Schlachtfeld.\r\n[[Todesschwinge]]s unerwarteter Verrat erwies sich als so verheerend, dass sich die fünf [[Drachen]]schwärme nie mehr davon erholten. [[Alexstrasza]] und die anderen verwundeten und bestürzten edlen Groß[[drachen]] mussten ihre sterblichen Verbündeten im Stich lassen. [[Malfurion]] und seine Gefährten überlebten den folgenden Ansturm der hoffnungslos überlegenen Gegner nur mit Mühe und Not.\r\n[[Malfurion]] war überzeugt, dass der [[Brunnen der Ewigkeit]] die einzige Verbindung der [[Dämon]]en mit der materiellen Welt darstellte, und plädierte für seine Zerstörung. Dieser unerwartete Vorschlag entsetzte seine Gefährten, die wussten, dass der [[Brunnen der Ewigkeit|Brunnen]] die Quelle ihrer Unsterblichkeit und Macht war. [[Tyrande]] indessen sah ein, wie weise [[Malfurion]]s Theorie war, und brachte [[Cenarius]] und seine Gefährten dazu, [[Azshara]]s Tempel zu stürmen, um eine Möglichkeit zu finden, den [[Brunnen der Ewigkeit|Brunnen]] zu verschließen. \r\n'''Quelle:''' wow-europe.com",},
			["Krieg der Urtume"] = { content = "#REDIRECT [[Krieg der Uralten]]", redirect = "Krieg der Uralten",},
			["Kristallsee"] = { content = "===Kristallsee===\r\nDer Kristallsee liegt ein kleines Stück östlich von [[Goldhain]]. [[Murlocs]] kommen die Bäche und Flüsse im östlichen Elwynn hinaufgeschwommen, vertreiben die Fische und greifen einfache Leute an. Der seltene Kristalltang wächst zwar normalerweise im Meer, aber manchmal wird er auch von den Murlocs hier am Kristallsee gesammelt.",},
			["Kristalltal"] = { content = "====\r\nIn Silithus, treiben sich die Diener der Luft und Erde in einer Felsenecke herum, die Kristalltal genannt wird. Sie schützen Gegenstände der Macht vor kleineren Wesen und Sterblichen.",},
			["Kristallträne"] = { content = "In der südlichen Wüste von [[Silithus]], nahe der heiligen Barriere, findet man eine einzelne Kristallträne. Sie ist ein Mahnmal für all die Verluste, die die [[Bronzener Drachenschwarm|Bronzenen Drachen]] während des Krieges der Sandstürme erlitten haben.",},
			["Kristall von Ata'mal"] = { content = "Es gibt einen Kristall aus einer alten [[Draenei]]-Legende, der sehr wichtig ist, den Kristall von Ata'mal. \r\nDer Kristall von Ata'mal wurde auf [[Argus]] den [[Eredar]] von den [[Naaru]] übergeben. [[Velen]] nutzte den Kristall, um das Schiff [[Oshu'gun]] herbeizurufen. Dabei zerbrach der Kristall, der ursprünglich weiß war, in sieben kleinere Kristalle, welche die sekundären Farben des Lichts hatten. Jeder Kristall hatte inviduelle Kräfte. Drei Ata'mal Kristalle erbeuteten die [[Orc]]s während ihres Feldzuges gegen die [[Draenei]]. Die restlichen vier sind im Besitz [[Velen]]s.\r\nMan sagt, dass solch ein Kristall seinem Träger gottgleiche Macht verleiht und man weiß, dass sich einer davon irgendwo östlich der [[Manaschmiede Ultris]] befinden muss. Vor ein paar Wochen hat die [[Brennende Legion]] in den [[Ruinen von Farahlon]] Einzug gehalten und damit all die Pläne des [[Konsortium]]s, die Artefakte dort auszugraben, zunichte gemacht. \r\nUnd die [[Brennende Legion]] hat den Kristall in den Ruinen bereits gefunden. Einer ihrer [[Schreckenslord]]s, [[Culuthas]], hat aus irgendeinem Grund alle anderen Mitglieder der [[Brennende Legion|Brennenden Legion]] dort getötet. Seitdem ruft er [[Dämonen]], die ihm dienen.",},
			["Kristall von Ata’mal"] = { content = "#REDIRECT [[Kristall von Ata'mal]]", redirect = "Kristall von Ata'mal",},
			["Kristall von Zin-Malor"] = { content = "Der '''Kristall von Zin-Malor''' war einst ein hochheiliges Relikt im [[Tempel von Zin-Malor]] in [[Azshara]], der starke arkane Kräfte fesseln und kontrollieren konnte. Der Benutzer des Kristalls wurde unglaublicher arkaner Macht fähig, aber nur, wenn er wirklich würdig war. Wie es aussieht, waren von den stärksten Magieanwendern nur eine Hand voll in der Lage, solch eine Macht zu kontrollieren. Man hätte ihn für das Gute nutzen können, aber die bösen Absichten der [[Hochgeborene]]n, die ihn stahlen, ließen ihn zersplittern. Und wie dieser Kristall wurden auch die Elfen als Volk zerschmettert. Seine Fragmente ruhen nun im [[Kel'Therilsee]] in [[Winterquell]]. \r\n[[Aurora Himmelsrufer]] am [[Nordpassturm]] in den [[Östlichen Pestländer]]n weiß über dieses gestohlene Relikt bescheid, aber sie weiß nicht, ob die Teile jemals wieder zu einem vereinigt werden können. Und selbst wenn, kann der Kristall niemals in seinen Tempel zurückgebracht werden, denn dieser ist nur noch eine Ruine. Aurora Himmelsrufer sammlte die hochheiligen Schriften der Hochgeborenen im Tempel von Zin-Malor und ersann eine Methode, um die Teile wieder zusammenzufügen und zu versiegeln. Dafür benötigt sie Gegenstände mit starken magischen Eigenschaften: verzauberte Thoriumbarren, Kristallflicker und eine Phiole mit Düsterwasser. \r\n[[Fandral]] Hirschhaupt in [[Darnassus]] hat von dem Kristall gehört und ist an ihm interessiert, um ihn sicher \"aufbewahren\".",},
			["Krokilisk"] = { content = "'''Krokolisken''' sind amphibische Wildtiere, die meist in der Nähe von Gewässern zu finden sind. Sie sind mit den [[Basilisk]]en verwand.\r\n==Arten==\r\n* '''Deviatkrokilisk''' - [[Höhlen des Wehklagens]].\r\n* '''Flusskrokilisk''' - [[Schlingendorntal]].\r\n* '''Incendosaurier''' - [[Sengende Schlucht]]. Incendosaurier sind eine Abart der Krokolisken, die nicht in der Nähe von Wasser, sondern in der Nähe von Lava beheimatet sind. Sie haben sich in den Lavabecken der [[Schlackengrube]] eingenistet.\r\n* '''Lochkrokilisk''' - [[Loch Modan]]. Die Krokiliskentränen der Lochkrokilisk findet man im gleichnamigen See.\r\n* '''Sägezahnkrokilisk''' - [[Sümpfe des Elends]]. Die Sägezahnschnapperklauen geben erstklassige Waffen ab, wenn sie richtig vorbereitet werden.\r\n* '''Salzwasserkrokilisk''' - [[Schlingendorntal]]. Die Alten kommen nur heraus, um die anderen Salzwasserkroks zu verteidigen.\r\n* '''Schaudermagenkrokilisk''' - [[Durotar]].\r\n* '''Schnappkieferkrokilisk''' - [[Schlingendorntal]].\r\n* '''Stachelschuppenkrokilisk''' - [[Nethersturm]].\r\n* '''Staubsuhlerkrokilisk''' - [[Düstermarschen]].\r\n* '''Sumpflandkrokilisk''' - [[Sumpfland]].\r\n==Gefährte==\r\n* [[Babykrokolisk]]\r\n==Persönlichkeiten==\r\n \r\n* '''Schlammwühler''' - [[Düstermarschen]]. Schlammwühler ist ein uralter Krokilisk in den Düstermarschen. Seine alten Knochen knirschen, wenn er seinen gewaltigen Leib durch den Sumpf schleppt, und auch wenn er sich noch mit der Kraft und dem Tempo der Jugend bewegt, martert sein alter Körper den großen innewohnenden Geist, ein Geist, dessen Flamme nicht erlischt. Heutzutage jedoch leidet er unablässig qualvolle Schmerzen.",},
			["Krone des Lichkönigs"] = { content = "Die Krone des Lichkönigs war einst ein Teil von [[Ner'zhul]]s Zeremonialrüstung. Als [[Ner'zhul]], die Dimensionsportale des sterbenden [[Draeno]]rs durchschritt und [[Kil'jaeden]] aus dem Ork den unbarmherzigen [[Lichkönig]] machte, floss der Geist des Lichkönigs in die Zeremonialrüstung. Von dem eisigen Sarg, in den [[Kil'jaeden]] ihn gesperrt hatte, meisterte der Lichkönig die letzten Geheimnisse des Untodes und hob mithilfe des [[Magier]]s [[Kel'Thuzad]] die [[Geißel]] aus . Dabei erkor er mit seinem Schwert [[Frostgram]] den [[Paladin]] Arthas zu seinem ersten Todesritter.Ner'zhul plante, den mächtigen Prinzen zu seinem neuen Körper zu machen. Als [[Illidan]] den[[ Frostthron]] angriff, rief seinen Champion herbei, der seinem Ruf folgte. Als [[Arthas]] zum Frostthron aufstieg und das diamantharte Eis mit [[Frostgram]] zerschlug,setzte er die Krone frei. Er setzte sie sich auf und der Geist des [[Todesritter]]s und der Geist des alten [[Schamanen]] wurden eins und gebaren den neuen Lichkönig,ein Wesen von unheiliger Stärke und Macht, das sich selbst vor einem [[Dämon]]en wie [[Kil'jaeden]] nicht mehr fürchten musste.\r\nAuf der Krone sitzt ein mattblauer Edelstein.In diesem Stein ist das Geistfragment des Lichkönigs. Wenn der [[Lichkönig]] die Augen schließt, kann er mit der Macht der Krone seinen Geist über ganz [[Azeroth]] ausdehnen und mit jedem sprechen ,der bereit ist ihm zuzuhören.Die Krone ist das zweite Gefäß, solange sie unbeschädigt bleibt, ist der Lichkönig nicht tot ,selbst wenn sein Körper vernichtet ist.",},
			["Kroshius"] = { content = "Kroshius ist eine [[Höllenbestie]], deren Überreste zusammengefallen im [[Narbengrund]] im [[Teufelswald]] zu finden sind. Mittels eines Teufelsfeuers kann sie jedoch ins Leben zurückgerufen werden. Ihr Höllenbestienkern wird von [[Hexenmeister]]n als Gabe für [[Niby der Allmächtige|Niby den Allmächtigen]] im [[Teufelswald]] benötigt.",},
			["Krypta der Erinnerung"] = { content = "Die '''Krypta der Erinnerung''' innerhalb der [[Scharlachroten Enklave]] wurde nach der Einnahme von [[Havenau]] von der Geißel besetzt. Von hier aus plant [[Prinz Keleseth]] die komplette Vernichtung von [[Neu Avalon]]. \r\n==Personen==\r\n* [[Prinz Keleseth]]",},
			["Kräuterkunde"] = { content = "Die Kräuterkunde ist eine fast unerlässliche Voraussetzung für die [[Alchimist|Alchimie]]. Kräuter sind überall in der Welt zu finden, warum sich also nicht diese Fähigkeit aneignen, um davon zu profitieren? Die [[Alchimist|Alchimie]] ist eine großartige Fertigkeit, mit deren Hilfe alle möglichen Arten von Tränken hergestellt werden können, die die Effektivität eines Charakters steigern.\r\n'''Quelle:''' wow-europe.com\r\n==Besondere Flora==\r\nNeben den zahlreichen bekannten Pflanzen, Blüten, Ranken und Pilzen, gibt es auch weniger bekannte Arten der azerothianischen Flora, die nur mit einem gekonnten Blick für Kräuter entdeckt werden können.\r\n===Blumen===\r\n* '''Azurlöwenmäulchen''' – Vorkommen: Azurmythosinsel. Anwendung: Heilmittel.\r\n* '''Blutblüte''' - Vorkommen: [[Un'Goro]] Krater. Blutblüten scheinen ein gewisses Maß an Intelligenz zu besitzen.\r\n* [[Faulblüte]]\r\n* [[Lunarfungusblüte]]\r\n* '''Mondblütenlilie''' - Vorkommen: [[Teldrassil]]. Anwendung: Gegengift. Mondblütenlilien wachsen nur an Wasserteichen.\r\n* [[Netherblüte]]\r\n===Früchte===\r\n* '''Caracolibohne''' - Vorkommen: [[Nagrand]]. Anwendung: Wasseratmen. Aus dieser Bohne kann man eine Tablette herstellen, die im Kampf gegen die ruhelosen Naturgewalten helfen wird. \r\n* [[Manabeere]]\r\n* [[Sandbirne]]\r\n===Moose===\r\n* '''Schlangenflaum''' - Vorkommen: [[Höhlen des Wehklagens]]. Anwendung: Seuche. Rare Pflanzenart. Die Königliche Apothekervereinigung denkt, dass dieses Kraut in größeren Mengen außerordentliches Potenzial besitzt. \r\n* '''Teufelsmoos''' - Vorkommen: [[Teldrassil]]. Anwendung: Verderbnis. Die Verderbtheit des bösartigen Teufelsmooses ließ die Wandlung der [[Furbolgs]] des Knarzklauenstamms geschehen. \r\n===Pflanzen===\r\n* '''Akirisschilfrohr''' - Vorkommen: [[Schlingendorntal]]. Wertvolles Meeresschilfrohr\r\n* '''Bathranshaar''' - Vorkommen: [[Eschental]]. Anwendung: Heilmittel gegen Psychosen. Bathranshaar wuchs früher in den alten Ruinen von Bathrans Schlupfwinkel im Norden von [[Eschental]] und war als Heilmittel für Krankheiten des Geistes bekannt.\r\n* '''Brandpulveragave''' - Vorkommen: [[Tausend Nadeln]]. Anwendung: Anrufung. Eine seltene Pflanze. Brandpulveragaven wachsen am Siedenden Teich. Man kann die Brandpulveragave verzaubern, um ein Pulver zu erzeugen, das ein Hochheiliges Feuer entzünden kann. \r\n* '''Giftfarnextrakt''' - Vorkommen: [[Schlingendorntal]]. Anwendung: Gift.\r\n* '''Höllenwirbelkraut''' - Vorkommen: [[Höllenfeuerhalbinsel]]. Anwendung: Schmerzlinderung. Wirbelkraut wächst in und um das Tal der Knochen im Norden herum. \r\n* [[Morgenkorn]]\r\n* '''Sengkoralle''' - Vorkommen: [[Sumpfland]]. Anwendung: Schmieden. Sie wächst nur an einem Ort - an der Küste südlich des Hafens von Menethil im [[Sumpfland]]. Rüstungen werden durch die Behandlung mit ihr sehr hart.\r\n===Pilze===\r\nEinige sagen, dass das Sammeln von Pilzen gefährlicher als der Verzehr von Pilzen ist. Pilzsammler begeben sich ins Unbekannte - dazu kommen noch die Gefahren, die in der Wildnis lauern.\r\n* '''Blutpilz''' - Vorkommen: [[Blutmythosinsel]]. Blutpilze findet man in Trümmerfall und im Mythoswald, östlich von Nazzivian. \r\n* '''Brachland-Pilzsporen''' - Vorkommen: [[Brachland]]. Die Oasen des [[Brachland]]es verbergen ein Mysterium. In ihren Wassern fließt Lebensenergie, die alle Pflanzen und Wildtiere erquickt, die davon trinken. Erquickt und verändert. Es gibt einen Pilz, der in der Nähe dieser Oasen wächst. Seine Sporen besitzen Eigenschaften, die die Apotheker [[Lordaeron]]s, sehr nützlich finden. \r\n* [[Hyazinthpilz]]\r\n* '''Lunarfungus''' – Vorkommen: [[Dunkelküste]]. Anwendung: Verbessert die Wirksamkeit von Heilsalben.\r\n* [[Ruinöser Birkensporling]]\r\n* [[Schorfstängling]]\r\n* [[Teufelszapfenfungus]]\r\n* [[Todeskappe]]\r\n* [[Träne von Ysera]]\r\n* [[Violetter Tragan]]\r\n* [[Wasserstinkmorchel]]\r\n===Ranken===\r\n* [[Fäulnisranke]]\r\n* [[Gaea-Samenkorn]]\r\n* [[Lauerwurzranke]]\r\n* [[Lebenswurz]]\r\n* [[Teufelszapfen]]\r\n* [[Tharlendrissamenkorn]]",},
			["Kugel des Kil'jaeden"] = { content = "Die Kugel des Kil'jaeden enthält einen Teil der Macht des Dämonenlords [[Kil'jaeden]] und befähigt den Träger SChüsse aus reiner [[Teufelsenergie]] gegen Feinde zu schleudern , selbst wenn sie sich in der Luft aufhielten.Der Träger dieser Kugel war [[Illidan]],im [[Schwarzen Te]]mpel jedoch trug Illidan diese Kugel jedoch nicht mehr(möglicherweise nahm [[Arthas]] sie ihm ab).",},
			["Kugel von Soran'ruk"] = { content = "Wenn [[Dämonen]] der Brennenden Legion in Ungnade fallen, wird ihr Geist in Kugeln gefangen und an ihre [[Magier]] und [[Hexenmeister]] verteilt. Viele solcher Artefakte wurden von den Bediensteten der Legion in [[Azeroth]] getragen und selbst als Bruchstücke besitzen sie die Macht der darin gefangenen Dämonen. Die '''Kugel von Soran'ruk''' wurde in zwei Teile zerbrochen. Eines davon wurde abermals in drei Fragmente zerbrochen und von den [[Akolyt]]en des [[Schattenhammerkult]] in der [[Tiefschwarze Grotte]] benutzt. Das andere, Großes Fragment von Soran'ruk besaß ein Hexer in der [[Burg Schattenfang]] und ist nun in Besitz einer [[Worgen der Schattenfänge|Dunkelseele der Schattenfänge]]. Die Kugel ist nicht allzu sehr fragmentiert und wenn alle Stücke da sind, ist es für [[Doan Karhan]] im südlichen [[Brachland]] einfach, sie zusammenzufügen und Soran'ruk wieder heil zu machen. Doan Karhan hat sein Leben dem Studium der Kugeln der Brennenden Legion und ihrer Neugestaltung gewidmet. Angehende Hexenmeister tun ihm einen Gefallen damit, diese Stücke zum Zweck des Studiums zu sammeln, und er wird sie ihnen zurückgeben - vollständig wiederhergestellt - in einer Gestalt ihrer Wahl. \r\n'''Quellen'''",},
			["Kult der Verdammten"] = { content = "Die von [[Kel'Thuzad]] gegründete Bruderschaft untersteht den Gewalten des [[Lichkönig]]s, in dessen Auftrag sie weiterhin versucht die freien Völker zu korrumpieren.\r\n==Geschichte==\r\nNachdem der [[Lichkönig]] den arktischen Kontinent [[Nordend]] unangefochten beherrschte, begann er mit den Vorbereitungen für seine wahre Mission - den Großangriff gegen die menschliche Zivilisation. Mit seinem grenzenlosen Bewusstsein drang [[Ner'zhul]] in die Länder der Menschen ein und rief jede dunkle Seele, die bereit war, ihm zuzuhören.\r\n'''Der erste Anhänger des Lichkönigs'''\r\nZu den wenigen mächtigen Individuen, die den mentalen Ruf des [[Lichkönig]]s vernahmen, gehörte der Erzmagier [[Kel'Thuzad]]. Er setzte seine gesamte Willenskraft ein, um mit der geheimnisvollen Stimme in Kontakt zu treten und alles über die Welt der Magie und ihre dunklen Wunder zu lernen. Von der beharrlichen Stimme in seinem Geist angetrieben, war der Erzmagier fest entschlossen [[Ner'zhul]] seine Dienste anzubieten. [[Kel'Thuzad]] verzichtete auf seine einflussreiche Position im herrschenden [[Rat von Dalaran]] und veräußerte seinen gesamten Besitz. Bevor er die magische Nation verließ und zu den eisige Küste von [[Nordend]] aufbrach, lagerte er sein Vermögen ein. Nach monatelangen Reisen gelangte der Erzmagier schließlich zum [[Eiskrone]]ngletscher und bot dem dunklen Lord der Toten seine Seele an. Der [[Lichkönig]]versprach [[Kel'Thuzad]] Unsterblichkeit und große Macht als Gegenleistung für Loyalität und Gehorsam. Der charismatische Zauberer sollte nach [[Lordaeron]] zurückkehren und seine Kräfte nutzen, um die unterdrückten Massen in seinen Bann zu ziehen.\r\n'''Der Kult und die Seuche des Untodes'''\r\n[[Kel'Thuzad]] verwendete in den drei kommenden Jahren sein gesamtes Vermögen darauf, ein geheime Bruderschaft ins Leben zu rufen, die [[Ner'zhul]] als Gott verehrte. Dieser „Kult der Verdammten“ versprach seinen Jüngern ewiges Leben auf [[Azeroth]] als Gegenleistung für ihren Gehorsam gegenüber dem [[Lichkönig]]. Die Kultisten waren begierig darauf zu sterben und in den Diensten ihres dunklen Herrn ihre Auferstehung zu erleben. Sie bejubelten die Aussicht auf Unsterblichkeit durch das Dasein als [[Untote]]. Obwohl im Laufe der Monate der Kult wuchs und sein Einfluss zunahm, hielt [[Kel'Thuzad]] seine Aktionen vor [[König Terenas]] verborgen. Der [[Lichkönig]] füllte seine [[Seuche]]n-Energien in eine reihe tragbarer Artefakte, die [[Seuchenkessel]] genannt wurden, und ließ sie nach [[Lordaeron]] bringen. [[Kel'Thuzad]] versteckte die Kessel in zahlreichen vom Kult beherrschten Dörfern und die [[Seuche]] des Untodes verbreitete sich unter den ahnungslosen Bürgern der nördlichen Provinzen. Sie starben und erstanden als [[Ner'zhul]]s willige Sklaven wieder auf. Die wachsende Armee nannte [[Kel'Thuzad]] \"Die [[Geißel]]\", denn bald sollte sie zu den Toren von [[Lordaeron]] marschieren und das Königreich in Schutt und Asche legen.\r\n===Siehe auch===\r\n* [[Kel'Thuzad und der Kult der Verdammten]]\r\n* [[Weg zur Verdammnis]]\r\n==Ränge==\r\n* [[Akolyt]]\r\n* [[Nekromant]]",},
			["Kult der Vergessenden Schatten"] = { content = "#REDIRECT [[Kult der Vergessenen Schatten]]", redirect = "Kult der Vergessenen Schatten",},
			["Kul Tiras"] = { content = "Auf der größten Insel vor der Küste [[Khaz Modan]]s lag das Königreich Kul Tiras, das von Lord Admiral [[Daelin Prachtmeer]] regiert wurde. Die Nation war vor dem [[Der Erste Krieg|ersten Krieg]] durch seine weitreichenden Handelsbeziehungen zum wohlhabendsten [[Volk]] der [[Menschen]] geworden, und hatte die unbestrittene Vorherrschaft auf der Großen See inne. Zu der Zeit, als die [[Orcs]] anfingen, die Küstenregionen von [[Lordaeron]] heimzusuchen, begann [[Prachtmeer]] seine Armada weiter auszubauen. Kul Tiras hatte immer enge Beziehungen zu [[Lordaeron]] und [[Azeroth]] gepflegt, und auf Geheiß von Lord [[Anduin Lothar]] schwor [[Prachtmeer]] der [[Allianz]] die Unterstützung seines [[Volk]]es zu. \r\nWährend des [[Der Zweite Krieg|zweiten Krieges]] drängten die Seestreitkräfte der [[Allianz]] unter der Führung von Admiral [[Prachtmeer]] die [[Orcs]] in das verwüstete Land [[Azeroth]] zurück. Auch nach dem [[Der Zweite Krieg|zweiten Krieg]] blieb Kul Tiras der [[Allianz]] von [[Lordaeron]] treu ergeben, und dessen mächtige Flotte beschützte die Handelswege vor Piraten und Marodeuren. Wie auch die anderen Königreiche, wurde Kul Tiras bei der Invasion der [[Brennende Legion|Brennenden Legion]] in Schutt und Asche gelegt. \r\nDie wohl berühmteste Tochter des Inselreichs, [[Jaina Prachtmeer]], Tochter von [[Daelin Prachtmeer|Daelin]] und Schülerin der [[Kirin Tor]], war maßgeblich an der Bekämpfung der Invasion der [[Brennende Legion|Brennenden Legion]] beteiligt. Sie leistete den Schergen der [[Dämon]]en auf [[Kalimdor]] erfolgreich Widerstand. Obwohl ihre [[Allianz]] mit den [[Orcs]] und den geheimnisvollen [[Nachtelfen]] unter der menschlichen Bevölkerung ganz [[Azeroth]]s sehr misstrauisch beäugt wird, gilt sie als Heldin des letzten Krieges. \r\n==Aktuelles==\r\nNun herrscht [[Tandred Prachtmeer]], Jainas Bruder, über den Inselstaat. Eine Armee der [[Naga]] und [[Murlocs]] attackiert beständig die Küsten, offenbar mit dem Ziel, die [[Menschen]] zu vernichten. Auch das auf der kleinen Insel [[Tol Barad]] errichtete magische Gefängnis, in dem [[Dämonen]], Hexer und Schlimmeres gefangen gehalten werden, bereitet immer wieder Probleme. Erneut erhärten sich auch Gerüchte , dass die [[Menschen]] von Kul Tiras kriegerische Maßnahmen gegen die der [[Orcs]], [[Durotar]], planen. Abwegig ist dies ganz gewiss nicht, den die Inselfeste [[Theramore]] liegt vor [[Durotar]]s Küste. Die Schiffahrts-Nation war sehr beschützerisch, was seine Flotten-Oberherrschaft anging.",},
			["Kundschafter der Blutelfen"] = { content = "#REDIRECT [[Blutelfenschurke]]", redirect = "Blutelfenschurke",},
			["Kur'talos Rabenkrone"] = { content = "==Allgemeines==\r\nFürst Kur'talos Rabenkrone war der ursprüngliche Kommandeur der [[Nachtelfen]]armee, die gegen die erste Invasion der [[Brennende Legion|Brennenden Legion]] kämpfte. Er war der offizielle Patron von [[Illidan]] Sturmgrimm, der Meister der Schwarzen Felsenfestung und Führer des Widerstandes während des [[Krieg der Uralten|Krieges der Uralten]]. \r\nRabenkrone war ein Politiker und weigerte sich, die Nicht-Kaldorei Rassen um Hilfe zu kontaktieren, weil er den Treubruch der konservativen Kommandanten fürchtete. So lehnte er etwa alle Vorschläge ab, die [[Irdene]]n oder die [[Tauren]] um Hilfe zu bitten, und obwohl er [[Drachen]] als extrem mächtig einschätzte, nahm er doch an, sie würden alle Abgesandten der Sterblichen einfach auffressen. Daher verbot er allen [[Nachtelfen]], die [[Drachen]] um Unterstützung im Kampf gegen die [[Brennende Legion]] zu bitten. Doch schließlich gab er nach und akzeptierte die [[Tauren]] und [[Irdene]]n. Jeder von ihnen brachte andere Verbündete in die Gemeinschaft. \r\nKur'talos war zutiefst loyal gegenüber [[Königin Azshara]] und konnte nicht glauben, dass sie etwas mit dem Auftauchen der [[Dämonen]] der [[Brennende Legion|Brennenden Legion]] auf [[Azeroth]] zu tun hatte. Er rief sogar den Namen der Königin wieder und wieder als Schlachtruf, während er die Truppen der [[Nachtelfen]] in den Kampf gegen die [[Brennende Legion]] führte.\r\nIronischerweise war es [[Königin Azshara]] selber, die schließlich ihrem Stellvertreter Hauptmann [[Varo'then]] den Befehl gab, Kur'talos zu töten. Ihre ganze Loyalität gehörte zu diesem Zeitpunkt schon [[Sargeras]], dem Herrscher der Legion, und es ärgerte [[Königin Azshara|Azshara]], dass die [[Nachtelfen]]armee weiter gegen die [[Brennende Legion]] kämpfte, weil dadurch die Heerschar der [[Dämonen]] gespalten und [[Sargeras]] Eintritt nach [[Azeroth]] verzögert wurde.\r\nBegierig, seiner Königin zu Gefallen zu sein, schickte [[Varo'then]] einen Attentäter an die Front. Der [[Orcs|Orc]] [[Broxigar]] entdeckte ihn in letzter Sekunde und versuchte noch Kur'talos zu warnen, aber zu spät: Der Attentäter stach Kur'talos von hinten durch den Hals und versuchte dann zu fliehen. Doch [[Broxigar]] holte ihn schnell ein und tötete ihn.\r\nLord [[Desdel Sternauge]], der als Stellvertreter unter Kur'talos gedient hatte, übernahm nach seinem Tod den Posten als Kommandeur der [[Nachtelfen]]verteidiger, aber Rabenkrones Ideale (und generelle Kompetenz) wurden nicht aufrecht erhalten bis [[Jarod Schattensang]] den Mantel übernahm. \r\n==Herkunft==\r\nDer Klan der Rabenkrones war adlig, doch er gehörte nicht zur Kaste der [[Hochgeborene]]n. Im Gegenteil, wie die meisten [[Nachtelfen]] betrachtete Kur'talos die [[Hochgeborene]]n mit Missfallen und Misstrauen. \r\n==Charakter==\r\nEr war ein vernünftiger Mann, ein erfahrener Kämpfer und ein inspirierender Anführer auf dem Schlachtfeld. Es war für ihn ebenso eine Ehrensache wie eine praktische Überlegung, an der Seite seiner Truppen zu kämpfen. Seine Anwesenheit beflügelte andere zu besonders guten Leistungen und mutigen Bravourstücken. Trotzdem war auch Kur'talos nicht frei von vielen der alten Vorurteile, die [[Nachtelfen]] gegenüber anderen Völkern hegen. \r\n'''Anmerkung''': Es gibt ebenso ein Ingame-Schwert namens Rabenkrones Vermächtnis, welches vermutlich dasselbe ist, das er vor 10.000 Jahren benutzte.",},
			["Kurdran"] = { content = "#REDIRECT [[Kurdran Wildhammer]]", redirect = "Kurdran Wildhammer",},
			["Kurdran Wildhammer"] = { content = "'''Kurdran Wildhammer''' war ein zwergischer [[Greifenreiter]] und Meister der Greifenbändigung. Dieser stolze und streitlustige [[Zwerg]] aus den Bergen des [[Nistgipfel]]s war einer der berühmt berüchtigtsten Drachenkämpfer und Helden des Zweiten Krieges. Es wird berichtet, und das von vielen Leuten, das er es zustande gebracht hatte, neun ausgewachsene Drachen im Kampf zu besiegen, ja gar zu töten. Seither standen Kurdran und seine Greifenreiter in dem Ruf, die unbestrittenen Meister der Lüfte zu sein. Er war der Kommandant der Greifenreiterdivision, die als Teil der Expedition der Allianz in Draenor, der Heimat der Orcs, einmarschiert ist. Der Zwerg diente bis zu seinem Tod der [[Allianz]], und es gibt nur wenige, die sich mit seinen Taten messen können... \r\n'''Quellen'''",},
			["Kurenai"] = { content = "#REDIRECT [[Zerschlagene der Kurenai]]", redirect = "Zerschlagene der Kurenai",},
			["Kurinnaxx"] = { content = "'''Kurinnaxx''' zählt zu den [[Sandhäscher]]n und ist der erste Boss in den [[Ruinen von Ahn'Qiraj]]. Über über seine Herkunft und Vergangenheit ist zu diesem Zeitpunkt nichts bekannt.\r\n==Taktik==\r\nKurinnaxx sieht aus wie ein großer Skorpion und hält viele Spezialfähigkeiten für seine Gegner bereit. Noch während der Boss gepullt und auf einer Position in der Mitte des Raums getankt wird, sollten sich die Fernkämpfer und Heiler kreisförmig um Kurinaxx postieren und langsam mit ihrem Job beginnen. Kurinaxx besitzt abgesehen von einer starken Doppelschlagattacke 2 Angriffstechniken, die den Kampf prägen.\r\n===Sterbliche Wunden===\r\nKurinaxx zaubert einen Debuff in Blickrichtung, welcher die Heilung auf den Betroffenen um 10 % verringert. Dieser Debuff stapelt sich bis zu zehn Mal, was ein schnelles Ableben des Tanks zur Folge hat. Deshalb ist bei diesem Kampf eine Tank-Rotation nötig. Die beiden Neben-Tanks beginnen kurz nach dem Haupt-Tank damit, Aggro erzeugen. Wenn der Haupt-Tank den Debuff zwei bis drei Mal auf sich hat, stellt er alle Aggro erzeugenden Handlungen ein und der nächste Tank übernimmt seinen Job. Nach 20 Sekunden verschwindet der Debuff und der erste Tank kann wieder einsteigen. Hierbei ist zu beachten, dass die Tanks ihre möglichst so aufeinander abstimmen, dass sie nahezu gleich viel Aggro erzeugen. Sonst wird es schwer, den Tankwechsel reibungslos über die Bühne gehen zu lassen.\r\n===Sandfalle===\r\nDiese Fallen werden zufällig in der Schlachtzuggruppe platziert, fügen ca. 2000 Punkte Naturschaden zu, bringen das Ziel für 20 Sekunden zum schweigen und senken während dieser Zeit die Trefferchance um 75 %. Dies ist der Grund, warum der Raid sich möglichst weit verteilen sollte. Nachdem man einer Sandfalle getroffen wurde sollte man wenn möglich die „nutzlose“ Zeit damit verbringen, sich selbst zu verbinden. Sollten die Tanks zu oft von Sandfallen betroffen sein, kann es mitunter zu recht haarigen Übergängen kommen, da auch diese ihre Fähigkeiten nicht einsetzen können, während sie schweigen.\r\nHat Kurinaxx nur noch 30 % seiner Lebensenergie, verfällt er in Rage. Hier müssen nun vor allem die Priester die anfallenden Schadensspitzen mit Blitzheilung ausgleichen. \r\n'''Quelle:'''",},
			["Kurken"] = { content = "Kurken ist ein zweiköpfiger [[Nian]]-Hund in der [[Tannenruhfeste]] auf der [[Azurmythosinsel]].\r\nNachdem der Kristallsturm auf der [[Azurmythosinsel]] nachgelassen hatte, der beim Absturz der [[Exodar]] verursacht wurde, erschien eine mythische Bestie im Dorf der [[Furbolgs der Tannenruhfeste]]. Das Untier, Kurken, das von den einfallenden [[Eulenbestien der Tannenruhfeste]] in die [[Tannenruhfeste]] gebracht wurde, legte alles in Trümmer. Zahlreiche [[Furbolgs]] wurden bei der Verteidigung ihres Landes von der Bestie getötet und beim Versuch, das Untier zu bezwingen, ließen viele weitere ihr Leben.",},
			["Kurzens Truppenlager"] = { content = "[[Colonel Kurzen]] hat in seinem Lager im [[Schlingendorntal]] eine große Anzahl an Medizinmännern um sich versammelt, die seine Streitkräfte mit Dschungelarzneien heilen und die Kämpfer mit Giftfarnextrakt vergiften. Seine Medizinmänner haben die Arzneien und die Extrakte werden vermutlich irgendwo in den Vorratskästen im Lager verstaut. Kurzens Kommandosoldaten und Kopfschrumpfer sind loyal und grausam.\r\n==Personen==\r\n* '''Buchhalter Herod''' war die Kontaktperson vom Gefreiten Thorsen in Kurzens Lager. Herod ist Kurzens Nachschuboffizier und weiß alles über den Betrieb im Truppenlager. Das Büro des Buchhalters war im oberen Stock des einzigen zweistöckigen Gebäudes dort und seine Aufzeichnungen sind vermutlich immer noch dort zu finden. In den Berichten wird kein Wort über den Gefreiten Thorsen verloren, jedoch im Einband eines von Herods Geschäftsbüchern findet sich ein kleiner Messingschlüssel und nach genauerem Studium seiner Notizen finden sich in den verschiedenen Dokumenten einige Verweise auf eine \"sichere Geldkassette\". Die Geldkassette befindet sich irgendwo innerhalb des Vorratslagers - des Höhlenkomplexes weiter hinten in Kurzens Truppenlager. Wenn diese sichere Geldkassette gefunden wird und der kleine Messingschlüssel ihn öffnen kann, dann kann das Geheimnis um Thorsens Entdeckung vielleicht offenbart werden. Unter den Wertgegenständen in der Geldkassette befindet sich eine schlammverschmierte, gekritzelte Notiz. Wenn sie auch kaum lesbar ist, so scheint es, als wäre es eine Abhandlung über den Gefreiten Thorsen. Sie beschreibt ausführlich seine Patrouillenrouten, mit wem er so spricht und wie er seine Zeit bei den Rebellen verbringt. Sie ist nur mit einem einzelnen Buchstaben unterschrieben: -M. Dennoch muss, wer auch immer diese Notiz verfasst hat, stets in Thorsens Nähe gewesen sein. Wer auch immer diese Notiz verfasst hat, ist der Verräter im [[Rebellenlager]].\r\n* [[Colonel Kurzen]]",},
			["Kurzgeschichte: Im Nether"] = { content = "Anthrazides wagte kaum die Augen zu öffnen. Auf seinen Lidern spielte sich ein Gewitter aus roten und orangefarbenen Lichtern ab, während seine Ohren von einem Brausen und Tosen erfüllt waren, das ab und an durch einen langgezogenen, tiefen Donner oder das kurze Knacken eines Blitzes unterbrochen wurden. Die Luft war heiss und stürmisch und prickelte, aufgeladen von den mächtigen Energien der Elemente. Der Forscher konnte dem Sturm kaum standhalten und konzentrierte sich deshalb auf die Informationen, welche die Sensoren seines Helms ihm zur Verfügung stellten. Das, wonach er suchte, konnte er schimmernd und glühend in der Ferne leuchten sehen. Hârkenbrandt hatte mit der Optimierung der Sensorik auf jene Signatur die dort vor Anthrazides? geistigem Auge glühte, ganze Arbeit geleistet.\r\nSchließlich übermannte ihn die Neugierde. Anthrazides wusste genau, das der Anblick, den er gleich ergattern würde, ihn seinen Verstand kosten konnte. In unzähligen Folianten hatte er geblättert, um die wenigen Berichte jener Unglückseeligen einzusehen, die in diese Dimension geworfen worden waren und diese auf Kosten großer Teile ihres Verstandes hatten wieder verlassen dürfen.\r\nAnthrazides stand auf einem Felsvorsprung aus schwarzem Stein. Vor ihm das Panorama einer gewaltigen, von Schluchten und Rissen durchzogenen Ebene. Aus dem Erdboden stiessen gewaltige Geysire aus purer arkaner Energie in den Himmel. Dort zuckte und wandt sich ein riesiges Band aus grüner Energie wie ein Wurm von einem Horizont zum anderen, erfüllt von mächtigen Blitzen, die diese Welt für sekundenbruchteile in gleissendes Licht tauchten. Dort, wo das grüne Band am Horizont verschwand, erhob sich eine Schaar geflügelter, schlangenförmiger Kreaturen in den sturmumtosten Himmel. Auf halbem Weg zwischen dem Felsvorsprung und den Netherdrachen war ein großer Krater in der Ebene auszumachen, von dem einige Schluchten in alle Richtungen hinfort führten. Aus diesem dunklen Loch heraus qualmte, dampfte und zischte es beständig, und grob waren die Spitzen einer gewaltigen, schwarzen Zitadelle auszumachen, die in diesen Krater gebaut worden war. Dann erkannte Anthrazides die abertausenden von Sklaven, die rund um diesen Krater ihren blutigen Frondienst in aller Ewigkeit leisteten: Kreaturen aus allen nur erdenklichen Welten des Kosmos schleppten gewaltige Quader über die Ebene hin zu diesem Bollwerk des Bösen, das sich unaufhaltsam aus der Tiefe des dunklen Loches erhob. Angetrieben unter den Peitschenhieben der Verdammniswachen, welche die Trecks begleiteten, war dies also das Los für all jene Narren die zu Lebzeiten keinen Seelenbürgen gefunden hatten. Verteilt über die Ebene waren kleinere Enklaven von Siedlungen auszumachen, nicht mehr als ein paar unscheinbare Gebäude. Linkerhand in weiterer Entfernung, eingehüllt vom Dunst der sich am Horizont staute, ragte die Silhouette eines schlanken Turmes in den Himmel, den ein gezackter Kopf zierte.\r\nIn diesem Moment erzitterte der Boden und die gesamte Ebene wurde von einem Beben erfüllt, der selbst die Trecks dort unten auf der Ebene für einem Moment innehalten liess. Aus den Rissen quer über die Ebene stiessen heisse Dampfwolken empor, und Schwärme von Abermillionen von Netherwespen ergossen sich wie schwarzer, todbringender Rauch aus den Tiefen unter der Ebene in die Luft um sich ihre Opfer unter den schutzlosen Sklaven dort unten zu suchen. Das angsterfüllte, gepeinigte Geschrei der Verdammten drang bis zu Anthrazides hinauf. Er kniff die Augen zusammen und sah hinüber zur Zitadelle. Grünes Licht drang aus den hohen, schmalen Fenstern der Kuppel, die über der Zitadelle thronte.\r\nAnthrazides griff an die Seite und berührte den Gürtel, an den er das Seil gebunden hatte. Er löste es und schlang es um einen der schwarzen Stalagmiten, die sich zu Dutzenden auf der schwebenden Felsinsel aus dem Boden erhoben. Er schloss noch kurz die Augen und wurde sich des Glühens gewahr, das die Position des gefangenen Großinquisitors anzeigte. Anthrazides hatte alle Zeit der Welt - fünf Tage im Nether waren fünf Minuten in der Existenzebene. Kerzufal war nicht tot, und der Herr der Grube vor ihm, Mongrethod, erwartete ihn bereits. Es wäre töricht von Anthrazides gewesen zu glauben, das sein Eindringen in diese Dimension von den Grubenherren unbemerkt geblieben war. Anthrazides sah hinter sich auf den von ihm künstlich aufgetanen Dimensionsspalt und rief sich Malwin in Erinnerung, der dort nun mit dem Seil in der Hand stand, das hier mit dem Stalagmiten verbunden war. Glaubte dieser Mann wirklich, Anthrazides der Fabelhafte hätte diese gefährliche Reise aus reinem Altruismus auf sich genommen? Monate der Vorbereitung, der Forschung, des Studierens von netherischen Schwingungen und Strahlungen und den Aufzeichnungen derer, die bereits dort gewesen waren, lagen hinter ihm und die Männer und Frauen der Heiligen Inquisition würden ihm, Anthrazides dem Fabelhaften, auf ewig dankbar sein für seinen Dienst, der sich, gemessen an dem, was er hier eigentlich vor hatte, als ein Spaziergang herausstellen würde. Nun, vorausgesetzt, sein Plan würde aufgehen. Denn wenn nicht... Anthrazides sah hinunter zu den Verdammten, viele davon eingehüllt in dunkle Wolkenaus Netherwespen, welche die Gepeinigten über die Ebene jagten.\r\nEin kurzes Lächeln huschte über sein Gesicht. Anthrazides kniff die Augen zusammen und spähte hinunter auf die Ebene. Seine Hand glitt in die Westentasche und er steckte sich eine seiner guten Zigarren aus Booty Bay in den Mundwinkel, die er mit einem Fingerschnippen entzündete.\r\n\"Zeit, Geschäfte zu machen.\"",},
			["Kurzgeschichte: In der Scherbenwelt"] = { content = "Sporensäcke. Reife Sporensäcke.\r\nDie Luft ist voll von Sporen, Fasern, Filzen, Schwämmen und Blütenstaub, die von einer leichten, warmen Brise sanft durch die Luft getragen werden. Die Szenerie ist bizarr und insgeheim hoffe ich, das die Landschaft, durch die ich mich bewege, nicht die Ausgeburt einer kranken Fantasie sind. Wer weiß ob diese Riesenpilze nicht halluzinogene Düfte aussenden? Ab und an tröpfelt es, aber ich bezweifle, das es Regen ist. Vielmehr vermutlich kondensiertes Brackwasser, das von den gewaltigen Kappen der Pilze weit über mir wieder heruntertropft.\r\nNicht drüber nachdenken, einfach weiter. Sporensäcke. Da hinten blubbert etwas, könnte in der Tat einer dieser Sporensäcke sein. Frag mich, wozu die Pilzgesichter das Zeug brauchen. Hätte besser aufpassen sollen, aber bei dieser undeutlichen, feuchten Aussprache, die der kleine, hässliche Kerl hatte, verging mir die Lust zum zuhören beim ersten Wort. Erbärmliche Kreaturen sind das, die ihr Leben hier in diesem Morast zubringen. Kein Aas kümmert es, wenn die Legion diesen Sumpf trockenlegt. Aber nein, unsere ökologisch stets korrekten Freunde von der Cenariuswacht - oh wie ich sie hasse! - denen fällt natürlich wieder irgendein überflüssiger Mist ein, um Leute wie mich für eine gute Tat durch die Marschen zu schicken.\r\nIch habe Wasser in den Stiefeln. Feuchte Socken seit drei Tagen. Die Feuchtigkeit kriecht durch den ganzen Körper. Ich habe das Gefühl, mir wachsen Pilze unter den Achseln. So langsam werde ich selbst zu einem Pilz. Dazu kommt das Gebruddel von Hathnak, dem Leerwandler. Ich hätte ihn schon längst wieder zurück in den Nether geschickt, wenn ich ihn hier nicht bräuchte, um mir das lästige, in vielfältiger Form auftretende Geschmeiss vom Leib zu halten. Die Oger sind mir da noch am liebsten, ehrlich. Freundliche, hart arbeitende Oger. Hauen hier einen nach dem anderen verdammten Pilz um. Neulich hat mich doch tatsächlich einer von den haarlosen Blauhäutern gefragt, ob ich nicht ein paar Nagas für ihn jagen möchte. Wozu, bei Sargeras? eitrigen Beulen, sollte ich das tun? Die legen den ganzen Sumpf trocken und bald ist hier nichts mehr übrig ausser einer wunderschönen, weiten Wüste! Keine Marschenläufer und Fennschreiter mehr, keine Sporensegler, keine hässlichen kleinen Pilzleute! Und keine Moskitos! Mit Abstand die schlimmste Seuche, die dieses Sumpfland befallen konnte - von der Legion mal abgesehen.\r\nBald bin ich wieder in Shattrath, der einzige Ort auf diesem durch das große Dunkel schwebenden Schrotthaufen, den ein paar ganz große Geister liebevoll \"Scherbenwelt\" getauft haben, von dem man bisher als \"Stadt\" hat reden können. Obwohl das auch schon viel zu gutmütig ausgedrückt ist. Shattrath ist eine Halle, in dem die haarlosen Blauhäuter von Sonstwoher ihren Anführer anbeten. Anführer heißt in diesem Falle, ein leuchtendes, schwebendes Etwas, das aussieht wie ein Mobile und in kleinerer Ausführung auch als Wohnzimmerdekoration durchgehen würde. Aber alle haben sie ganz dick Respekt vor dem Ding, sogar Altmeister Kadghar, von dem alle geglaubt haben, er wäre tot und das sicher auch besser so gewesen wäre. Nein, der Meistermagier ist ganz begeistert von der mit telepathischen Kräften gesegneten Wohnzimmerdekoration. Ich glaube ja, der Alte hat sie nicht mehr alle.\r\nAuf der anderen Seite von Shattrath, das von einem wundervollen Ghettogürtel umgeben wird, leben die Seher. Klingt vielversprechend, ist es nicht. Außer ein paar Golems, die die Straßen Patrouillieren und wie von Geisterhand kehrenden Besen haben die dort ansässigen Blutelfen - die Seher - nicht viel drauf. Kauen einem das Ohr ab mit ihrer erbärmlichen Geschichte. Vielleicht hätte es sie aufgemuntert, wenn ich ihnen den Vorschlag unterbreitet hätte, zur Belustigung der Völker in Wichtelkostümen zum nächsten Winterhauchfest in Sturmwind aufzutreten. Ich glaube, das würden die richtig gut machen.\r\nIch schätze mal, es ist die Strahlung, die hier ungebremst aus dem großen Dunkel auf diese kaputte Welt einwirkt. So langsam drehen hier alle durch. Angefangen hat das schon auf der Ehrenfeste. Da geht es zu wie beim Schlussverkauf: Man proletet mit den \"Schätzen\" herum, die man hier und dort aus dem Schlamm graben konnte und überhaupt herrscht eine Stimmung wie auf dem Rummelplatz. Leute - es ist Krieg, nicht Karneval! Auch wenn ich bald wieder zurück in Sturmwind in meiner Pension sitze, eine Zigarre rauche und an meinem Bourbon nippe, während ich über meinen Memoiren brüte - mit der Ankunft der haarlosen Blauhäuter, der Öffnung des Portals nach Kaputtistan und den Ambitionen der Winterhauchwichtelelfen aus Quel?Thalas, Weltmacht zu werden, sehen wir uns in der Zukunft mit neuen Herausforderungen konfrontiert.\r\nIch meine, das ist alles hochgradiger Pfusch. Sturmwind ist gerade so ruhig, friedlich und idyllisch. Man sollte das Tor einfach zu machen, wenn alle auf der anderen Seite sind. Herrlich wäre diese Ruhe...\r\nHathnak bruddelt irgendwas unverständliches...\r\nIch habe immer noch nicht genügend Sporensäcke...\r\n... und ist das Schlamm zwischen meinen Zehen?\r\n----\r\nVon Anthrazides",},
			["Königin Azshara"] = { content = "'''Azshara''' war die Königin der [[Nachtelfen]] und die mächtigste [[Magier]]in der [[Hochgeborene]]n. Es hieß, dass ihr Körper so schön war, dass sie jeden förmlich bezauberte. Im Moment gehört sie dem Volk der [[Naga]] an, die sie auch als Königin verehren.\r\n===Geschichte===\r\nAzshara und ihre [[Hochgeborene]]n experimentieren mit der [[Magie]]. Ohne wirklich zu begreifen, was sie taten, öffneten sie einen kleinen Riss hinein in den Nether. In jenem Moment regte sich etwas uraltes und böses in der Dunkelheit. Die [[Hochgeborene]]n hatten die Aufmerksamkeit von [[Sargeras]] und seiner [[Brennende Legion|Brennenden Legion]] geweckt. [[Sargeras]] verführte und verzaubterte jeden [[Magier]], der in den Riss schaute, sodass sie in ihren Bemühungen bestärkt wurden, den Riss zu vergrößern. Der mächtige [[Magier]] Xavius war der erste. Er war es auch, der Azshara in den Riss blicken ließ. Die beiden waren vom Anblick der ersten [[Dämon]]en, die aus dem Nether traten nicht erschreckt, nein sogar erstaunt, beinahe beglückt.\r\nMit Hilfe verschiedenster [[Dämon]]en, darunter auch [[Dämon]]enlords wie z.B. [[Mannoroth]], [[Archimonde]] und [[Hakkar der Hundemeister]], gelang es den [[Hochgeborene]]n mit einigen Rückschlägen, verursacht durch Angriffe [[Malfurion]]s und seinen Begleitern, den Riss zu einem kleinen Portal zu erweitern. Ganze Armeen schritten hindurch und so begann der [[Krieg der Ahnen]]. Doch einer Allianz aus [[Tauren]], [[Nachtelfen]], [[Irdene]]n und [[Furbolgs]], unterstützt durch die alten und mystischen Wesen der Natur und ihrer Waldgötter, z.B. [[Cenarius]], [[Malorne]] usw., gelang es, die [[Dämon]]en unter großen Verlusten zurückzutreiben. Auch die [[Drachen]] versuchten zu Helfen. Doch durch den Verrat von [[Neltharion]], sollten sich die Drachenschwärme bis heute nicht mehr ganz von dem Krieg erholen können.\r\nAls das Portal zusammenbrach explodierte auch der [[Brunnen der Ewigkeit]]. Der Kontinent wurde gespalten und die Explosion riss die [[Hochgeborene]]n in die Tiefen des Meeres. Obwohl Azshara zu Lebzeiten unglaublich mächtig war, sodass selbst [[Mannoroth]] ihre Macht respektieren, ja vielleicht sogar fürchten musste, wurde auch sie nicht von den hereinbrechenden Fluten verschont. Von den überlebenden [[Hochgeborene]]n war einzig und allein Azhsara in der Lage sich vor den erdrückenden Wassermassen, zumindest für eine kurze Zeit, durch ein magisches Schild, zu schützen. Es war das erste Mal in ihrem Leben, dass sie etwas anstrengte. Im angesicht des Todes, hörte sie plötzlich ein Flüstern, beinahe wie ein gemeinsames Echo dreier Wesen: \"Es gibt einen Weg... es gibt einen Weg... du wirst mehr sein als jemals zuvor... wir können helfen... dir helfen...\" Schmerzen durchfuhren Azshara. Ihr Körper wandte und drehte sich. \"Du wirst mehr sein als jemals zuvor. Und wenn die Zeit reif ist für das, was wir dir schenken... wirst du eine gute Dienerin sein\". Schreie der anderen [[Hochgeborene]]n erklangen, der Schildzauber brach zusammen und Azsharas Lungen füllten sich mit Wasser. Aber sie ertrank nicht. Die [[Naga]] waren geboren.\r\nDoch ein neues stärkeres Leben war nicht das einzige, das die Drei Azshara schenkten. Obwohl sie bereits unglaublich mächtig war, statteten die Drei sie mit zusätzlichen Fähigkeiten, der Unsterblichkeit und mit einer Macht aus, die sie sich kaum hätte vorstellen können. Ihr Körper umfasst gar soviel Kraft, wie ein Sterblicher sie nicht mehr ertragen kann. Sie muss beständig [[Magie]] wirken, oder ihre Kraft nimmt solche Ausmaße an, sodass sie irgendwann stirbt. Auch Gegenstände, sogar einzigartige Artefakte, können durch ihre Berührung eine Magische Überladung abbekommen und so zerstört werden.",},
			["Königliche Apothekervereinigung"] = { content = "Die '''Königliche Apothekervereinigung''' ist eine Organisation aus hochbegabten [[Alchimist]]en der [[Verlassene]]n, die im Auftrag von Lady [[Sylvanas Windläufer]] an einer neuen Seuche forschen, eine Seuche, tödlicher als jedes Leiden in ganz [[Azeroth]]. Diese neue Krankheit wird [[Arthas]]' Armee der [[Geißel]] ins Verderben stürzen. Die dunkle Fürstin glaubt, dass ihr alchemistisches Wissen, gepaart mit der neuentdeckten [[Magie]], der Schlüssel zu [[Arthas]]' Untergang sein wird. Auch erzeugen sie alchemistische Kreaturen , wie [[Faranell]]s [[Monstrositäten]].\r\n==Eifrige Forschungen==\r\nEin paar unglückliche Opfer zu vergiften, ist eine Kleinigkeit; doch eine ganze Welt erkranken zu lassen, erweist sich als etwas komplizierter. Und so haben sich die dunklen Apotheker in ihre Forschungen gestürzt, denn Zeit ist ein Luxus, den sich diejenigen, die für Lady [[Sylvanas Windläufer|Sylvanas]] arbeiten, nicht leisten können. Die Königliche Apothekervereinigung steht unter enormem Druck seitens der dunklen Fürstin. Sie arbeiten sehr hart und haben bereits einige Fortschritte gemacht. \r\n===Austausch der Erkenntnisse===\r\nDie [[Apotheker]] denken, dass der Erfolg sich umso schneller einstellen wird, wenn sie innerhalb der Vereinigung Informationen austauschen und so ist es Pflicht, als Mitglied der Apothekervereinigung sein Wissen mit Kollegen zu teilen, auf dass ihre gemeinsamen Bemühungen der dunklen Fürstin eines Tages die neue Seuche bescheren werden, die sie so ersehnt. Als Meister ist es [[Apothekermeister Faranell]]s Aufgabe, die anspruchsvollsten der alchimistischen Versuche zu überwachen. \r\n===Forschungsgebiete===\r\nFür die Königliche Apothekervereinigung ist es immer von Interesse, wenn neue Toxinformen entdeckt werden, und sie befassen sich mit einigen sehr interessanten Experimenten, wie z.B. dem Blut der [[Schattenhund]]e für eine neue Seuche, den Schuppen der [[Murlocs der Finsterflossen]] oder dem Gift der [[Nachtweber]]spinnen. Wenn sie [[Arthas]]' Vormarsch im Norden und die menschliche Plage im Süden stoppen wollen, müssen sie alle Möglichkeiten ihres untoten Daseins nutzen.\r\n==Persönlichkeiten==\r\n* [[Apothekermeister Faranell]] in [[Unterstadt]] hat die Leitung über die Königliche Apothekervereinigung\r\nWeitere Bekannte Mitglieder sind:\r\n* [[Apotheker Berard]]\r\n* [[Apotheker Faustin]]\r\n* [[Apotheker Helbrim]]\r\n* [[Apotheker Johaan]]\r\n* [[Apotheker Keifer]]\r\n* [[Apotheker Lycanus]]\r\n* [[Apotheker Lydon]]\r\n* [[Apotheker Renferrel]]\r\n* [[Apotheker Venustus]]\r\n* [[Apothekerin Katrina]]\r\n* [[Apothekerin Vallia]]\r\n* [[Apothekerin Zamah]]\r\n* [[Apothekerin Zelana]]\r\n* [[Apothekerin Zinge]] \r\n* [[Jungapotheker Holland]]",},
			["Königreich Lordaeron"] = { content = "* [[Lordaeron (Königreich)]] - Gebiet\r\n* [[Königreich Lordaeron (Gilde)]] - Gilde der Horde",},
			["König Gordok"] = { content = "'''König Gordok''' ist ein gewaltiger [[Oger]] in [[Düsterbruch]] (Nord).",},
			["König Llane"] = { content = "#REDIRECT [[König Llane Wrynn]]", redirect = "König Llane Wrynn",},
			["König Llane Wrynn"] = { content = "König Llane Wrynn I. gilt als einer der legendären Helden des Königreiches [[Sturmwind]]. Er war der Vater des verschollenen König [[Varian Wrynn]] und Großvater des amtierenden Kindkönig [[Anduin Wrynn]] von [[Sturmwind]].\r\n==Geschichte==\r\nNach dem Tod seines Vaters König [[Adamant Wrynn III]]. im [[Der Erste Krieg|Ersten Krieg]] wurde Prinz Llane im Alter von 20 Jahren zum König gekrönt und schwor, das [[Azeroth]] von den [[Orcs]] zu befreien. Er hatte erkannt, dass die [[Orcs]] zwar unglaublich stark und bösartig waren, aber selten wirksame Kampftaktiken anwendeten. Durch Strategie und List konnten seine Soldaten selbst zahlenmäßig überlegene Marodeure besiegen und die [[Horde]] in Schach halten. Doch mit [[Rend Schwarzfaust]]s Aufstieg zum Kriegsherrn der [[Horde]] und dem Kampf für die Verteidigung des Königreiches brachen die dunklen Tage des Ersten Krieges an. Die Kriegswirren sollten [[Azeroth]] fast fünf Jahre lang verwüsten und diesmal hatte Llane die erbarmungslosen Klans unterschätzt - sie richteten schreckliche Massaker an. Das stolze Königreich und seine Verteidiger wurden in die Knie gezwungen und als König Llane heimtückisch ermordet wurde, nahm sich Sir [[Anduin Lothar]] der geschlagenen Armeen von [[Azeroth]] an und schart seine Landsleute um sich.",},
			["König Terenas Menethil II."] = { content = "'''König Terenas''' war der inständige und wohlwollende Herrscher über [[Lordaeron]] und die [[Allianz]], welche er auf Bitten [[Anduin Lothar]] mit einigen [[Menschen]]reichen gründete. Terenas ist einer der mächtigsten Herrscher seit [[Arathor]] gewesen und unter seiner Führung wurden viele Schlachten geschlagen, so auch die des ersten und des [[Der Zweite Krieg|zweiten Krieges]]. Die [[Allianz]] zerbrach jedoch an der Frage, was aus den besiegten [[Orcs]] werden sollte. Denn viele von ihnen waren in Internierungslagern. [[Thoras Trollbann]] zum Beispiel forderte ein Massaker an den Kriegern aus [[Draenor]]. Doch Terenas ließ die [[Orcs]] vorerst in den von [[Aedelas Schwarzmoor]] geführten Internierungslagern. [[Orgrim Schicksalshammer]], der Kriegsführer der [[Horde]], wurde als persönlicher Gefangene von Terenas gehalten. Doch er entkam ... Dreizehn Jahre später hatten beide ihre Zöglinge zu Kriegern erzogen. Schicksalshammer hatte den jungen [[Thrall]] ausgebildet. Terenas hatte seinen Sohn erzogen und ihn dem Führer des [[Silberne Hand| Ordens der Silbernen Hand]], [[Uther Lichtbringer]], übergeben. [[Thrall]] führte sein Volk in die Freiheit, [[Arthas]] seines in den kalten Tod... \r\nNachdem er [[Mal'Ganis]] auf [[Nordend]] mit Hilfe des Schwertes Frostmourne getötet hatte, fiel wenige Wochen später sein Vater, König Terenas dem Schwert zum Opfer. Aus dem einst so glorreichem [[Lordaeron]] wurde ein Land der Pest und des Todes...\r\nTerenas bewahrte seinen Halt bei der Führung der [[Allianz]] größtenteils wegen der Arbeit der [[Kirin Tor]] und Admiral [[Daelin Prachtmeer]]s offener Unterstützung. Er diskutierte die Hauptpunkte: \"[[Alterac]]\" entweder zu seinem eigenen Königreich zu annektieren oder einen neuen und vernünftigeren Monarchen auf seinen Thron einzusetzen ... vermutlich mit einem verständnisvollem Ohr für [[Lordaeron]]s Beweggründe.\r\n==Inschrift des Grabmals in [[Unterstadt]]==\r\nHier ruht König Terenas Menethil II. – der letzte wahre König von [[Lordaeron]]. Groß waren seine Taten – lang währte seine Herrschaft – undenkbar schien sein Tod. Möge der Vater unschuldig an des Sohnes Taten ruhen. Möge die blutige Krone verloren und vergessen bleiben.",},
			["König Ymiron"] = { content = "Der schlafende [[König Ymiron]] ist der Oberhaupt der [[Vrykul]], inbesondere des [[Vrykul der Drachenschinder|Drachenschinderklans]], im [[Der heulende Fjord|Heulenden Fjord]]. Als anhaltende Missgeburten unter den Vrykul zu der Annahme führten, ihre alten Göttern, die [[Titanen]], sich von ihnen abgewendet und sie mit einem Fluch belegt hätten, schwor ihr König Ymiron, sein Volk von diesem Fluch zu befreien und begab sich in den Einfluß des [[Lichkönig]]s.",},
			["Kürschner"] = { content = "Durch das Häuten von Tieren erhalt man Leder und Felle. Leder und Felle werden für die [[Lederer|Lederverarbeitung]] benötigt. Leder wird des Weiteren für einige [[Schmied]]ekunst-, [[Ingenieur]]skunst- und [[Schneider]]ei-Anleitungen benötigt.\r\n'''Quelle:''' wow-europe.com",},
			["Küste des Nebelrandes"] = { content = "Nahe des Nebelrandufers im Norden von [[Dunkelküste]] liegen zwei havarierte Schiffe - die \"[[Silbermorgen]]\" und die \"[[Nebelschleier]]\". Vor einiger Zeit kollidierten die beiden Schiffe wegen der [[Murlocs]], als sie über das weite Meer nach [[Auberdine]] segelten. Jetzt liegen sie auf dem Grund des Ozeans als Trophäen für diese Satanskreaturen. Beide Kapitäne haben es in dieser Nacht nicht geschafft, ihre Schiffe zu verlassen. Ihre Logbücher und anderen Habseligkeiten befinden sich immer noch dort unten in Schließkassetten.\r\n==Personen==\r\n* '''Gelkak Gyromasts''' Schiff sank vor der Küste und schuld daran sind diese dreisten [[Dreschadon]]s. Er muss seinen Ersten Maat, den Dreschonator 4100, funktionstüchtig wiederhaben, doch als er an Land gespült wurde, zerbrach der Schlüssel für seinen Ersten Maat an den Felsen und wurde von den Biesterchen von [[Dunkelküste]] geraubt. Aus den Augenwinkeln sah er tobende Kriecher, riesige Waldschreiter und [[Murlocs]], die das Wrack durchstöberten. Die Murlocs und ihr Häuptling werden nich so froh sein, wenn der Erste Maat sie zu fassen kriegt.",},
			["Lady Falther'ess"] = { content = "[[Lady Falther'ess]] ist eine [[Banshee]] in den [[Hügel der Klingenhauer|Hügel der Klingenhauer]] während der [[Invasion der Geißel]].",},
			["Lady Illucia Barov"] = { content = "'''Lady Illucia Barov''' ist ein [[Untoter]] [[Geist]] aus dem [[Haus Barov]] in der unteren Etage der [[Scholomance]]. Zu Lebzeiten war sie eine [[Nekromant]]in und die Ehefrau von [[Lord Alexei Barov]], sowie die Mutter von [[Alexi Barov]], [[Jandice Barov]] und [[Weldon Barov]]. Doch wie so viele ihrer Familie verfiel auch sie der [[Geißel]].",},
			["Lady Jaina Prachtmeer"] = { content = "'''Jaina Prachtmeer''', möglicherweise eine der begabtesten Zauberinnen, die seit Generationen in [[Dalaran]] ausgebildet wurde, ist eine kluge, wissbegierige junge Frau und stets bemüht, ihre Kräfte zu verbessern und ihr magisches Wissen zu vertiefen. Ihr Vater, Admiral [[Daelin Prachtmeer]] aus [[Kul Tiras]], war einer der größten Helden des Zweiten Krieges. Jaina verspürte ständig den Druck, dem Namen ihres Vaters gerecht zu werden, wollte aber eigentlich nur studieren und ihre magischen Forschungen betreiben. Wie [[Arthas]], so war auch Jaina zutiefst verletzt, als ihre Affäre mit dem jungen Prinzen zu Ende ging. Allerdings ließ sie nie zu, dass sich ihre Enttäuschung auf ihr Studium oder ihre anstrengenden Forschungen auswirkte. Ihr Mentor, der Erzmagier [[Antonidas]], behauptete stets, dass sie die größte Zauberin werden könnte, die die Menschheit jemals hervorgebracht hat.",},
			["Lady Katrana Prestor"] = { content = "'''Lady Katrana Prestor''' ist die Beraterin von Kind-König [[Anduin Wrynn]]. Auf ihren Geheiß wurde der junge [[Anduin Wrynn]] zum König gekrönt nachdem sein Vater König [[Varian Wrynn]] unter mysteriösen Umständen auf dem Weg zu einem diplomatischen Gipfeltreffen auf der Insel [[Theramore]] verschwunden ist und seither vermisst wird.\r\nAuch wenn ihre Absichten scheinbar nur dem Wohle [[Sturmwind]]s dienen ist an ihr mehr dran als man auf den ersten Blick erahnen könnte.",},
			["Lady Liadrin"] = { content = "'''Lady Liadrin''' ist die Matriarchin der [[Blutritter]] in [[Silbermond]].\r\nAls ihnen der Naaru [[M'uru]] von Prinz [[Kael'thas Sonnenwanderer]] überbracht wurde, glaubte sie und ihr Orden, seine Macht würde ihnen helfen, ihr Volk in ein neues Zeitalter zu führen. Doch Lady Liadrin hat erkannt, dass ihr Weg der falsche war, denn sie wurde von dem Mann verraten, den sie ihren Prinzen nannte. In seiner Machtgier sandte Kael'thas die [[Teufelsblutelfen|Teufelsblütigen]], um die Blutelfen anzugreifen und entführte M'uru zum [[Sonnenbrunnen]]. Nun sieht Liadrin klar und widerruft ihr Loyalität zum Hause Sonnenwanderer und seinem falschen Prinzen. Sie verpflichtet stattdessen die Klingen ihrer Blutritter der Bezwingung [[Kil'jaeden]]s und der Wiederherstellung Silbermonds. Deshalb wird sie nun an [[A'dal]]s Seite kämpfen.",},
			["Lady Prestor"] = { content = "#REDIRECT [[Lady Katrana Prestor]]", redirect = "Lady Katrana Prestor",},
			["Lady Sarevess"] = { content = "Lady Sarevess ist eine sehr verdorbene [[Naga]] Zauberin in der [[Tiefschwarze Grotte|Tiefschwarzen Grotte]]. Sie befaßt sich oberflächlich mit dem Reich der Magie und kann für einen Zauberer ein bischen zäh sein.",},
			["Lady Serpentra"] = { content = "Lady Serpentra war ein mystischer General in der Armee der [[Naga]] und früher eine [[Quel'dorei]], eine Dienerin der Nachtelfen-[[Königin Azshara]]. Als der [[Brunnen der Ewigkeit]] explodierte, wurde sie verflucht und in eine [[Naga]] [[Meerhexe]] verwandelt, um unter den Wellen zu wohnen bis [[Illidan Sturmgrimm]], ihre einstiger und zukünftiger Verbündeter, sie aus ihrem Unterwasser Gefängnis befreite. Sie kämpfte mit in den Schlachten um die Zerschmetterten Inseln im Dritten Krieg, verteidigte [[Illidan]] und attackierte [[Maiev Schattensang]] als diese nicht geschützt war. [[Tyrande]] und [[Malfurion]] kamen herbei um [[Maiev Schattensang|Maievs]] Basis zu befestigen und töteten Lady Serpentra.",},
			["Lady Vashj"] = { content = "==Allgemeines==\r\n===Fähigkeiten===\r\nVashj verläßt sich mehr auf ihre Kampf-Fähigkeiten als auf ihre Zauberei, aber sie ist trotzdem noch eine beachtliche Zauberin. Mit ihrem Magischen Bogen ist sie unvergleichlich. [[Sylvanas Windläufer]] und [[Shandris Mondfeder]] sind die einzigen Bogenschützen, die besser sind. Sie bevorzugt Wind- und Wasser-Elementar Kräfte, wenn sie offensiv zaubert. Ein Gefolge von [[Naga]] Myrmidonen als Leibwächter begleitet sie immer.\r\n===Verhalten / Charakter===\r\nBis zum heutigen Tag dient Lady Vashj ihrem Meister [[Illidan]] in den Einöden der [[Scherbenwelt]]. Obwohl ihr Herz und Loyalität bei ihrer Königin und ihrer Rasse liegt, genießt es Vashj mit [[Illidan]] zu arbeiten und Uneinigkeit und Schrecken zu säen wo immer sie können. \r\n==Geschichte==\r\nAls Angehörige der [[Hochgeborene]]n betrachtete Vashj es als ihr Geburtsrecht, [[Königin Azshara]] zu dienen. Vashj ahmte die Frisur und die Kleidung der Königin nach, so weit das möglich war. Als die [[Königin Azshara|Königin]] sie dann zu ihrer Ersten Zofe machte, war es fortan Vashjs einziges Bestreben, sich das Wohlwollen der [[Königin Azshara|Königin]] zu bewahren.\r\n===Der Krieg der Urtume===\r\nAls der [[Titanen|Titan]] [[Sargeras]] Kontakt zu den [[Hochgeborene]]n aufnahm, war [[Königin Azshara|Azshara]] von seiner gewaltigen Macht fasziniert. Wie die [[Königin Azshara|Königin]] erwartete auch Vashj sehnlichst sein Eintreffen auf [[Azeroth]]; beide Frauen waren sich sicher, dass [[Sargeras]] [[Königin Azshara|Azshara]] unwiderstehlich finden würde.\r\nDie [[Königin Azshara|Königin]] besaß wirklich eine Menge Charisma, welches sie zweifellos magisch verstärkte. Mit einem leisen Wort oder einem Augenaufschlag konnte [[Königin Azshara|Azshara]] eine ganze Reihe gewaltiger Emotionen auslösen. Ihre Favoriten waren dabei Leidenschaft und Zorn. Angetrieben von Eifersucht stritten sich ihre Untertanen um ihre Gunst und trugen sogar Duelle im Namen ihrer Ehre aus. Die [[Königin Azshara|Königin]] war von solchen Zurschaustellungen eher amüsiert und schritt nicht immer ein, um die Kombattanten vor Schaden zu bewahren.\r\nEs war genau diese Art von Besessenheit, die Vashj packte, als [[Königin Azshara|Azshara]] und ihre Zofen der gefangenen Hohe[[priester]]in [[Tyrande|Tyrande Wisperwind]] einen Besuch abstatteten. [[Tyrande]] war von der [[Brennende Legion|Brennenden Legion]] ergriffen und im Palast eingekerkert worden. Aus einer Laune heraus bot die [[Königin Azshara|Königin]] [[Tyrande]] an, sie zu ihrer Zofe zu machen, aber [[Tyrande]] lehnte dankend ab und sagte, sie müsse ihre Gelübde an [[Elune]] über alle anderen Loyalitäten stellen. [[Königin Azshara|Azshara]] war von [[Tyrande]]s Weigerung irritiert, so diplomatisch sie auch formuliert war, und verließ sie kurz darauf.\r\nVashj aber konnte das Angebot der [[Königin Azshara|Königin]] nicht so leicht vergessen. Die Erinnerung daran wurde für sie zur Qual. Trotz der Tatsache, dass [[Tyrande]] abgelehnt hatte, sah Vashj die [[Priester]]in fortan als Rivalin um die Gunst von [[Königin Azshara|Azshara]]. In ihrem Wahn versuchte sie, [[Tyrande]] umzubringen, versagte jedoch und floh aus der Zelle, bevor der Anschlag auf [[Tyrande]]s Leben entdeckt werden konnte.\r\n===Verflucht und verwandelt===\r\nTrotz der Bemühungen der [[Hochgeborene]]n, der [[Brennende Legion|Legion]] bei der Beschwörung von [[Sargeras]] zu helfen, wurde das [[Dunkle Portal|Portal]] in den Wirbelnden [[Nether]] letztendlich geschlossen, bevor [[Sargeras]] nach [[Azeroth]] gelangen konnte. Der [[Brunnen der Ewigkeit]] konnte dieser letzten arkanen Belastung nicht mehr standhalten und begann, zu kollabieren. Durch den plötzlichen Einschlag, wurde der Brunnen Richtung Meeresboden geschleudert - und er riss die gesamte Stadt [[Azshara|Zin-Azshari]] mit sich. Der Brunnen durchbohrte sogar noch den geschmolzenen Kern des Planeten, bevor er völlig vernichtet wurde.\r\nDas antike [[Kalimdor]] wurde auseinandergerissen, und der Ozean raste tosend heran, um die Leere zwischen den beiden neuen Landmassen auszufüllen. Die [[Königin Azshara|Königin]], ihre Zofen, ihre Wachen und eine Menge anderer [[Hochgeborene]]r wurden von den Wassermassen begraben. Doch statt zu ertrinken, wurden Vashj und viele andere verflucht und in [[Naga]] verwandelt.\r\nTrotz ihrer nachfolgenden Mutationen hat Vashj einen Teil ihrer Erinnerungen und ihrer Persönlichkeit bewahren können. Außerdem wurde sie unsterblich, und sie ist nicht die einzige [[Naga]], die dieses unerwartete Geschenk erhielt.\r\n===Im Dienste des Verräters===\r\nMehrere Monate nach dem Dritten Krieg kam der [[Dämon]]enfürst [[Kil'jaeden]] in die [[Scherbenwelt]] und nahm Kontakt zu [[Illidan|Illidan Sturmgrimm]] auf. Auch wenn [[Illidan]] in der Vergangenheit auch gegen die Interessen der [[brennende Legion|Legion]] gehandelt hatte, erklärte sich [[Kil'jaeden]] trotzdem bereit, [[Illidan]] noch eine Chance zu geben. Wenn [[Illidan]] es schaffte, den Frostthron zu vernichten, versprach [[Kil'jaeden]], ihm alles zu gewähren, was er sich wünschte.\r\nSo suchte sich [[Illidan]] neue Verbündete. Mit einem mächtigen Zauber erreichte er den Meeresboden, und eine Gruppe [[Naga]] unter der Führung von Lady Vashj antwortete ihm. Vashj und viele andere erinnerten sich an [[Illidan]], der vor der Teilung berüchtigt gewesen war. Die [[Naga]] respektierten seine Macht, besonders, da [[Illidan]] jetzt ein [[Dämon]] geworden war. Sie waren einverstanden, ihm zu dienen.\r\n[[Illidan]] und die [[Naga]] errangen ein magisches Artefakt, das Auge von [[Sargeras]], und sie kanalisierten einen Vernichtungszauber hindurch, um den Frostthron zu zerstören. Doch ihr Versuch schlug fehl, und [[Illidan]] zog sich schnell zur [[Scherbenwelt]] zurück in der Hoffnung, dadurch [[Kil'jaeden]]s Zorn zu entgehen.\r\n===Weitere Verbündete===\r\nAuf [[Illidan]]s Anweisung, suchten Lady Vashj und ihre [[Naga]] Prinz [[Kael'thas]] Sonnenwanderer und seine Gruppe [[Blutelfen]] auf. Der verzweifelte Prinz zögerte zunächst, die Hilfe der [[Naga]] beim Kampf gegen die [[Geißel]] anzunehmen, doch am Ende siegte sein gesunder Elfenverstand. Dann aber entdeckten [[Kael'thas]]' [[Menschen]]verbündete dieses Zweckbündnis. Sie beschuldigten die [[Blutelfen]], mit dem Feind zu paktieren, und nahmen sie gefangen. Noch einmal kamen Vashj und die [[Naga]] den [[Blutelfen]] zu Hilfe und ermöglichten ihnen die Flucht aus den Kerkern von [[Dalaran]].\r\nInzwischen litten die [[Blutelfen]] furchtbar unter dem Entzug der [[Magie]]. Vashj erklärte ihnen, dass auch die [[Naga]] süchtig seien nach [[Magie]], und sie meinte, [[Illidan]] könne den [[Blutelfen]] helfen. Sie führte sie zum [[dunkle Portal|Portal]], welches [[Kel´Thuzad]] während des Dritten Krieges geöffnet (und somit [[Archimonde]] den Weg nach [[Azeroth]] geebnet) hatte. Ohne eine andere Wahl zu haben, folgten [[Kael'thas]] und seine Mitstreiter Vashj in die [[Scherbenwelt]], wo [[Blutelfen]] und [[Naga]] zusammen [[Illidan]] aus der Gewalt der Aufseherin [[Maiev Schattensang]] befreiten, die [[Illidan]] wieder in seinen Kerker zurückbringen wollte.\r\n[[Kael'thas]] schwor [[Illidan]] die Treue, und gemeinsam besiegten er, Vashj und [[Illidan]] den Grubenfürsten [[Magtheridon]] und übernahmen seine Festung, die [[Schwarze Zitadelle]]. Doch [[Illidan]] und seine Verbündeten konnten ihre Eroberung nicht lange feiern. In einem Gewitter aus [[Magie]] und Zorn stieg [[Kil'jaeden]] auf die [[Scherbenwelt]] herab und verlangte, dass [[Illidan]] noch einmal versuche, den Frostthron zu zerstören.\r\n[[Illidan]] blieb keine andere Wahl, und so führte er die [[Naga]] und [[Blutelfen]] zurück nach [[Azeroth]]. Die Schlacht wurde schließlich durch einen Zweikampf zwischen [[Illidan]] und dem [[Arthas|Todesritter Arthas Menethil]] entschieden. [[Arthas]] gewann das Duell und warnte [[Illidan]], er solle den Planeten verlassen und niemals zurückkehren. Seit dieser Zeit leben [[Illidan]] und seine Verbündeten, darunter auch Vashj, im [[Schwarzer Tempel|Schwarzen Tempel]] in der [[Scherbenwelt]].\r\n'''Quelle:''' wow-europe.com",},
			["Lager der Bleichborken"] = { content = "Das '''Lager der Bleichborken''' liegt im südöstlichen [[Arathihochland]] in der Nähe der [[Halle der Felsfäuste]]. Es ist das Revier der [[Trolle der Bleichborken]]. Geführt wird dieses Dorf von [[Zalas Bleichborke]], dem Anführer der Kriegsmeute der Bleichborken dort.",},
			["Lager der Blutschläger"] = { content = "Das '''Lager der Blutschläger''' befindet sich im [[Schergrat]] im Norden des [[Messergrat]]es. Man gelangt dorthin, indem man den nordwestlichen Weg aus dem [[Ruuanwald]] hinab nimmt. In der Nähe gibt es einen Murmeltierbau. Er befindet sich im Norden in der [[Dolchrachenklamm]] hinter dem [[Zirkel des Blutes]]. [[Rexxar]] benutzt die Murmeltiere dazu, das Gift in den Fässern der [[Blutschläger]] zu verteilen. Die [[Oger]] planen einen Angriff gegen [[Sylvanaar]] und den [[Rabenwald]]. Man weiß nicht, wer oder was sie dazu treibt, dies zu tun, doch die Angriffe sollen vom Lager der Blutschläger aus starten. [[Dorgok]] ist einer Anführer der Blutschläger und trägt ein Abzeichen in Form einer kleinen Statuette, die frappierende Ähnlichkeit mit einem [[Gronn]] hat.",},
			["Lager der Distelfelle"] = { content = "Das '''Lager der Distelfelle''' liegt direkt im Norden von [[Astranaar]] im [[Eschental]]. Es ist das Revier der [[Furbolgs der Distelfelle]] unter Führung ihres Häuptlings [[Dal Blutklaue]]. Ihre Zahl hat sich in den letzten Monaten stark erhöht. Schon jetzt waren sie eine ständige Bedrohung für die Nachtelfen in [[Astranaar]]. \r\n==Troll-Glücksbringer==\r\nIn den Kisten am Ende des Lagers der Distelfelle befanden sich Trollglücksbringer, die die Distelfelle bei einem Überfall auf eine Gruppe von [[Dunkelspeertrolle]]n erbeutet hatten, die unterwegs zum [[Zoram'gar-Außenposten]] waren. Deswegen waren viele der Meinung, dass diese Furbolgs verflucht sind. Doch diese Trollglücksbringer hatten durchaus hohen Wert und [[Mitsuwa]] beim [[Außenposten von Zoram'gar]] wollte sie zurück! \r\n==Ruul Schneehuf==\r\nDort gefangen findet man den Tauren [[Ruul Schneehuf]]. Die Furbolgs hielten ihn für einen Bären und fingen ihn. Jetzt lassen sie ihn verhungern und seine Kraft schwindet.\r\n==Persönlichkeiten==\r\n* [[Dal Blutklaue]]\r\n* [[Ruul Schneehuf]]",},
			["Lager der Fäulnisklauen"] = { content = "Das '''Lager der Fäulnisklauen''' befindet sich im [[Eschental]], südlich der Straße, die von [[Astranaar]] nach Osten führt. \r\n==Allgemeines==\r\nHier haben die [[Furbolgs der Fäulnisklauen]] ihr Revier und greifen entlang dieser Straße immer wieder Reisende an. Es gibt zwar nicht so viele von ihnen wie das bei den Distelfellen der Fall ist, aber nicht nur die Horde fürchtet, dass ihre Wildheit sich in der Zukunft zu einem Problem auswachsen könnte. [[Karang Amakkar]] beim [[Zoram'gar-Außenposten]] wollte diese Bedrohung durch eine Demonstration der Macht beseitigen und forderte deshalb [[Häuptling Murgut]], den König der Fäulnisklauen, heraus. \r\n==Personen==\r\n* [[Häuptling Murgut]]",},
			["Lager der Schwarzfelle"] = { content = "#REDIRECT [[Furbolgs der Schwarzfelle]]", redirect = "Furbolgs der Schwarzfelle",},
			["Lager der Sichelklauen"] = { content = "#REDIRECT [[Furbolgs der Sichelklauen]]", redirect = "Furbolgs der Sichelklauen",},
			["Lager der Speerspießer"] = { content = "Das '''Lager der Speerspießer''' befindet sich außerhalb von [[Gruuls Unterschlupf]] am nördlichen Ende der [[Dolchrachenklamm]]. Leokk, [[Rexxar]]s Flügeldrachen wird in der Mitte des Lagers in einem Käfig gefangen gehalten. Geisterschwinge, Rexxars Begleiter, hat ihn gefunden. Einer der [[Oger]] muss den Schlüssel dazu haben. Leokk hat den Kopf eines Schwarzen Drachens von [[Drachenend]] gebracht, damit können sie [[Goc]], den [[Gronn]], der ihn gefangen genommen hat, erzürnen und ihn in die Schlacht locken.",},
			["Lager der Totenwaldfelle"] = { content = "#REDIRECT [[Furbolgs der Totenwaldfelle]]", redirect = "Furbolgs der Totenwaldfelle",},
			["Lager der Winterfelle"] = { content = "Den '''Lager der Winterfelle''' findet man in [[Winterquell]].\r\n==Allgemeines==\r\nHier leben die [[Furbolgs der Winterfelle]].",},
			["Lager der Winterhufe"] = { content = "Das '''Lager der Winterhufe''' im Norden des [[Der heulende Fjord|Heulenden Fjords]] ist der Sitz der [[Taunka]] vom Stamm der [[Taunka der Winterhufe|Winterhufe]], die in einem Teich am Rande des Dorfes unter Leitung von [[Windzähmer Kagan]] das [[Luftelementar]] [[Zyklothar]] beschwören.\r\n==Personen==\r\n* '''Großmutter Ankha''' - Großmutter Ankha ist die Mutter von Weiser Nebelläufer beim [[Stählernes Tor|Stählernen Tor]].",},
			["Laj"] = { content = "'''Laj''' ist ein übergroßer [[Peitscher]] in der [[Botanika]], einem Teilkomplex der [[Festung der Stürme]]. \r\n==Fähigkeiten==\r\n* '''GIFTWOLKE:''' Der Boss beschwört unter sich eine stationäre Giftwolke, die Naturschaden anrichtet\r\n* '''ALLERGISCHE REAKTION:''' Krankheit, die erlittenen Naturschaden erhöht\r\n* '''DORNENSCHINDER''': Beschwört zwei [[Dornenschinder]], die die Gruppe mit DORNEN und GEDANKENSCHINDEN attackieren.\r\n* [[ELEMENTARRESISTENZ]]: Immun gegen den farblich passenden Elementarschaden",},
			["Lake Wintergrasp"] = { content = "#REDIRECT [[Tausendwintersee]]", redirect = "Tausendwintersee",},
			["Lakota'mani"] = { content = "Der riesige [[Kodo]] Lakota'manis lebt im südlichen [[Brachland]] und sein Huf ist bei den [[Tauren]] ein Symbol für die Kraft der großen [[Kodos]].",},
			["Landeplatz von Bash'ir"] = { content = "Der '''Landeplatz von Bash'ir''' befindet sich am nördlichsten Rand des [[Schergrat]]s. Es ist eine kleine Kristallschmiede des [[Astraleum]]s, einer Gruppe von [[Astrale]]n die Fremden gegenüber nicht gerade freundlich sind. Man gelangt dorthin, indem man auf sein fliegendes Reittier steigt und in Richtung Nord, Nordosten reist, bis man ein gutes Stück hinter dem [[Konstruktionslager: Wut]] ist, dann müsste man den besagten Landeplatz sehen. \r\nIn Bash'ir gibt es große Gefängnisse: Die Stasiskammern. Diese Kammern enthalten wilde Bestien und Kreaturen von vielen verschiedenen Welten. Das [[Astraleum]] hofft, eines Tages Kontrolle über diese Bestien zu gewinnen und sie ihrem Willen zu unterwerfen. Die [[Schlüsseltafel des Astraleums - Alpha]] gewährt Zugang zu einer ganz bestimmten Kammer, die als Stasiskammer Alpha bekannt ist.",},
			["Lantresor von der Klinge"] = { content = "'''Lantresor von der Klinge''' in [[Nagrand]] lebt auf einer der höheren Ebenen der [[Ruinen der Brennenden Klinge]]. Er ist ein [[Klingenmeister]] von halborcischer Abstammung und der Anführer der [[Oger der Felsfäuste]]. Er hat in der Zeit der Väter das [[Dunkle Portal]] durchschritten und ist nun in sein Heimatland zurückgekehrt. Lantresor ist halb Orc und halb Draenei. Und deshalb ist er weder das Eine noch das Andere. Kein Orc, kein Draenei. Seine Art ist selten. Die meisten von ihnen wurden vor Jahrzehnten getötet... Er lebt noch, weil er einen starken Willen hat. Er hat in seinem Leben Dinge gesehen, von denen andere nur in Legenden gehört haben. Er hat Männer, Frauen und Kinder ohne Gnade getötet. Er hat unter dem Banner zweier Kriegshäuptlinge der Horde gedient... und nun regiert er die Oger der Felsfäuste auf dem Land der Oger, denn vor den Orcs und vor den Draenei waren hier die Oger.",},
			["Lar'korwi"] = { content = "'''Lar'korwi''' lebt im [[Un'Goro Krater]] und ist wahrscheinlich der größte [[Ravasaurus]]-[[Raptor]] in diesem Gebiet. Er ist eine der gefährlichsten Bestien, die der erfahrene Jäger [[Torwa Pfadfinder]] je gesehen hat. Auf Taurisch heißt Lar'korwi so viel wie \"Scharfe Klaue\", aber das wird ihm nicht gerecht. Wenn man Lar'korwi provozieren will, sucht man nach seiner letzten Jagdbeute und stiehlt ihm etwas Fleisch. Als dominantem Männchen steht es Lar'korwi zu, sich mit jedem Weibchen zu paaren, das ihm gefällt - und ihm gefallen viele. Die Weibchen produzieren in einer Drüse an ihrem Kopf einen abscheulichen Gestank, der die Männchen wissen lässt, dass sie paarungsbereit sind.",},
			["Larah Saldean"] = { content = "==Aussehen==\r\nLarah ist eine groß gewachsene, junge Frau (schätzungsweise Ende 20). Auf ihrer zarten Wange sieht man ein paar kleine Kratzer. Das besondere an Ihr sind aber ihre großen intensiven, dunklen Augen die pechschwarzen Haare (die an manchen Stellen etwas verfilzt sind) und ihre ruhige Ausstrahlung. \r\nTrotz der etwas mitgenommenen Erscheinung (Sie sieht aus, als hätte sie sich eben noch durchs Unterholz eines dicht bewachsenen Waldes geschlagen) geht von ihr ein wohltuender Duft aus der an Frühlingsblumen erinnert. Um ihren Hals trägt Larah eine kleine Kette mit einer schlichten Muschel mit Loch dran. - In ihrer Nase, an einer ihrer Augenbrauen und an ihren Ohren trägt sie silberne Ringe (die sie sich auf ihren Reisen als Piratin stechen lassen hat).\r\n==Geschichte==\r\nLarah ist wohlbehütet bei ihren Stiefeltern in [[Westfall]] aufgewachsen. Der geregelte Tagesablauf damals bedeutete für sie, auf dem [[Hof der Saldeans]] mit zu helfen und ein Mal in der Woche mit ihrem Stiefvater auf den damals noch stattfindenden Markt in [[Goldhain]] zu fahren. Mit 15 Jahren erfuhr sie, dass die Saldeans nicht ihre leiblichen Eltern sind. Eines Abends erzählte ihr Stiefvater ihr, durch einen gegebenen Anlass von ihrer Geschichte:\r\nEs war ein stürmischer Morgen und machte nicht den Anschein, als ob das Wetter am Tage noch besser werden würde. Bauer Saldean blickte etwas zwiegespalten nach draussen, durch die beschlagenen Scheiben seines kleinen Hofes im Herzen von Westfall. Es war noch sehr früh, und im Zwielicht des Morgens und bei dem starken Regen, der auf die matschige Erde niederprasselte, konnte er nicht sehr weit schauen. Er wird vorsichtig sein müssen, wenn er an den Strand von Westfall geht. Allzu viele Gefahren lauern in den Gewässern und zwischen den Dünen. Doch für den Eintopf, den seine Frau machen wollte, brauchte er nun mal die drei Murlocaugen. Als er an jenem Morgen am Strand an kam, da entdeckte er unzählige Gegenstände und Holzplanken die im Meer schwammen und von der Brandung an das Ufer gespült wurden. Vorsichtig näherte er sich den Wrackteilen und hörte auf ein Mal ein schluchzendes Geräusch. Erst bekam er es mit der Angst zu tun und blickte sich hastig um. Doch da erkannte er, dass das Schluchzen das er hörte von einem kleinen Kind kam, das kreidebleich, durchnässt und zitternd zwischen den angeschwämmten Planken saß. Bauer Saldean zog seinen schweren Regenmantel aus und legte ihn vorsichtig um das kleine Mädchen. An diesem Tag kam er ohne den Zutaten für den Eintopf nach Hause, aber mit einem kleinen, dunkelhaarigen Mädchen, dass schon halb erfroren war. Das Mädchen erholte sich schnell, doch zwei Tage nach dem Vorfall kamen drei Soldaten von der Späherkuppe und klopften an die Tür des kleinen Bauernhauses. Sie fragten Bauer Saldean, ob er etwas von dem angestrandeten Piratenschiffs-Wrack mitbekommen habe und dass er sehr seinen Hof gut verschließen sollte, da es wohl einige Überlebende gab und hier in Westfall nun einige Piraten unterwegs seien. Bauer Saldean erzählte den Soldaten nichts von dem kleinen Mädchen, dass er gefunden hatte. Stattdessen nahm er sie in seine Familie auf und gab ihr den Namen \"\"Larah\"\".\r\nAls sie jedoch 15 war und ihr Vater ihr von allem erzählte hatte dies einen Grund. Es waren einige grausame Piraten nach Westfall eingefallen und er vermutete, dass Larah der Grund dafür war. Er wollte sie nicht zurück an die Piraten verlieren. Also entschied er, dass sie nach [[Nordhain]] ins Kloster gehen sollte, bis die Gefahr vorüber ist. Dort wurde sie von den Nonnen und Mönchen mit offenen Armen empfangen. Nachts wurde Larah immer wieder von Alpträumen von einer steinigen Höhle und einem bösen Dämon heimgesucht. Doch tagsüber führte sie ein glückliches Leben. Nach wenigen Monaten entdeckte Khelden Bremen, der dortige Magielehrer, das Talent der jungen Dame. Er entschied sie eigenhändig zur Arkanmagierin aus zu bilden. Schnell lernte sie dazu und mit ihrem 17. Geburtstag konnte er ihr nicht mehr bei bringen. Sie kehrte daraufhin der schönen Zeit in Nordhain den Rücken zu und ging nach [[Sturmwind]]. Monate verbrachte sie in den großen Bibliotheken der Magier und ging immer wieder auf Reisen bei denen sie ihre Fähigkeiten ausbaute. Natürlich verbrachte sie auch sehr viel Zeit bei ihrer Familie in Westfall und half bei der Suche nach den Zutaten für den berühmten Eintopf ihrer Stiefmutter, die für sie immer noch wie eine leibliche Mutter war. Doch immer wieder zog es die freiheitsliebende Larah in die Ferne. \r\nIn [[Goldhain]] lernte sie ihre große Liebe kennen und verbrachte mit ihm die schönsten Zeiten. Überall in den [[östlichen Königreichen]] reisten sie gemeinsam herum. Eines Tages aber entschied Larah sich, sie war gerade 20 Jahre jung, ihren leiblichen Vater zu suchen. Sie reiste Richtung Süden, auf den Spuren ihres Piraten-Vaters gelangte sie bis nach [[Durotar]] in [[Kalimdor]]. Das Land der Orcs und Trolle. Dort entdeckte sie die Höhle aus ihren Alpträumen die sie die letzten Jahre plagte. In dieser Höhle begegnete sie einem Dämon, der sie durch seinem bösen Zauber mit einer Wand aus Eis umschloss. Zuerst versuchte sie durch ihre Magie das Eis zu brechen, doch das schaffte sie nicht. So fristete sie Stunden, Tage und Monate in ihrem kalten Gefängnis. Aus den Monaten wurden Jahre. Und eines Tages erschienen drei stämmige Gestalten hinter der Eiswand. Larah konnte sie nur schemenhaft erkennen. Alle hatten sie lange Stöcke in den klobigen Händen und sie hielten sie in die Höhe. Langsam schmolz das Eis um Larah herum und die Jahre der Schmerzen und Qualen hatten ein Ende. Geschwächt fiel sie zu Boden und musste alle Mühe auf bringen nach oben zu blicken, wer es war der sie aus ihrem Schicksal befreit hatte. Über ihr standen drei [[Orc]]s und blickten sie mit eiserne Miene an. Der mittlere sagte etwas zu ihr, doch sie konnte es nicht verstehen. Geschwächt viel Larah in einen langen Schlaf und als sie auf wachte lag sie nicht mehr in der Höhle, sondern in der Wiese unter einem Baum in der Nähe des [[Brachland]]es. Es ging ihr wieder viel besser und sie war alleine. Also machte sie sich auf nach Hause. In ihre alte Heimat. \r\nNach den Jahren ihrer Gefangenschaft hatte sich viel Verändert. Ihre Stiefeltern waren glücklich sie wieder zu sehen, doch ihre Freunde und ihre große Liebe waren verschwunden. Unglücklich erzählte sie ihre Geschichte einem Fremden. Dieser Fremde war aber wohl genau der falsche dem sie es erzählen konnte. Er antwortete mit einer Vision die er hatte. Eine Piratin aus Durotar die mit Orcs im Bunde war wird übles Unheil über die [[Allianz]] bringen schrie er. Im hysterischen Wahn schaarte er Leute um sich die Larah sofort hinrichten wollten. Larah schaffte es zu fliehen. Sie war nun 24 und schloss sich einigen Piraten an und segelte über das Meer. Sie überfielen einige Dörfer und Siedlungen. Ihren Vater fand sie auch zu dieser Zeit nie. Doch als die Piraten mit denen sie segelte in Westfall einfallen wollten, stellte sie sich gegen sie. Die Piraten fielen nicht in Westfall ein, aber abermals musste Larah einen Lebensabschnitt hinter sich lassen.\r\nZiellos streifte sie nun unglücklich durch die Lande. Sie hatte gar kein Bedürfnis ihre Stiefeltern die sie eigentlich so liebte in Westfall zu besuchen. Anstatt dessen ging sie zu einem mächtigen Magier in die Lehre, der ihr in seinem Turm und auf Reisen durch diese und die [[Scherbenwelt]] alles bei brachte was er konnte. Larah war nach dieser Zeit sehr ausgeglichen und besuchte nach vielen Jahren wieder ihre Stiefeltern in ihrem kleinen Hof in Westfall. Larah ist nun 27 Jahre alt.",},
			["Lariss Pavillon"] = { content = "Lariss Pavillon liegt tief in der Wildnis im nordöstlichen [[Feralas]], oberhalb von [[Camp Mojache]]. Der [[Nachtelfen]]-Älteste Azj'Tordin ist hier zu finden und dieser möchte, dass man nach [[Düsterbruch]] reist und den Dämonen [[Pusillin]] ausfindig macht, um ihn mit allen Mitteln zu überzeugen, Azj'Tordin's [[Buch der Zauberformeln]] zu herauszugeben. Denn in seiner Eile, dem Griff des gefallenen Prinzen zu entkommen, wurde Azj'Tordin ausgeraubt. Ein besonders widerlicher Dämon, namens [[Pusillin]], stahl ihm sein [[Buch der Zauberformeln]] und den Schlüssel zu den einstmals großen Hallen von [[Eldre'Thalas]]. Sein Interesse am Schlüssel ist verloschen als er seine Unsterblichkeit gegen die Freiheit eingetauscht hat, doch er benötigt unbedingt sein Buch der Zauberformeln.",},
			["Lashhversteck"] = { content = "#REDIRECT [[Arakkoa der Lashh'an]]", redirect = "Arakkoa der Lashh'an",},
			["Latosius"] = { content = "'''Latosius''' war schon eines der älteren Mitglieder der [[Mondgarde]], als der [[Krieg der Uralten]] begann. Der [[Nachtelf]] hatte schon lange Zauberei praktiziert und hielt sich für einen der bedeutendsten [[Magier]] seines Ordens. \r\n==Geschichte==\r\nLatosius war einer der [[Zauberer]], die zur Festung [[Black Rook Hold]] geschickt wurden, der Festung von Lord [[Kur'talos Rabenkrone]], um dort die Gefangenen [[Malfurion Sturmgrimm]], [[Broxigar]] und [[Rhonin]] zu befragen. Malfurion erzählte ihm eine wild klingende Geschichte, wie die [[Hochgeborene]]n mit ihrer Magie den [[Brunnen der Ewigkeit]] missbrauchten. Wie viele Nachtelfen der niederen Kasten war auch Latosius nur zu gerne bereit, Schlechtes über die Hochgeborenen zu glauben. Doch wie die meisten sah auch er [[Königin Azshara]] nicht in dem gleichen negativen Licht, trotz der Tatsache, dass sie auch eine Hochgeborene war. Als die [[Brennende Legion]] und ihre sterblichen Verbündeten den Zugang zum Brunnen sperrten, unterbrachen sie damit auch abrupt Latosius’ magisches Verhör von Malfurion. Die Mondwache versuchte wiederholt, das Verhör neu zu beginnen, doch ihre Zauber versagten ohne direkte Verbindung zu den Energien des Brunnens. Latosius war erfüllt von Angst und Zorn. \r\nBoten trafen auf der Festung Black Rook ein und überbrachten noch schlimmere Nachrichten: Dämonen griffen [[Zin-Azshari]] an. Kur’talos und seine Soldaten waren überzeugt, dass die Königin eine Gefangene in ihrem eigenen Palast war. Daher setzen sie sich nach Zin-Azshari in Marsch, um sie zu befreien und die Dämonen zu besiegen. Obwohl die magischen Fähigkeiten der Mondwache stark angeschlagen waren, begleiteten Latosius und seine Kameraden die Armee. Der Krieg eskalierte und als höchstrangiger Zauberer übernahm Latosius die Führung der Mondwache und lenkte ihren Einsatz auf dem Schlachtfeld. Später bemerkten einige der anderen Verteidiger, dass Latosius sich zu sehr in Details verzettelte und deshalb keinen Überblick über die Gesamtsituation hatte. Schließlich wurde der ältliche Magier vom Gegner überrascht, ein Hexer der [[Eredar]] tötete ihn mit seinem Zauber. Rhonin rächte Latosius’ Tod, indem er den Eredar-Hexer tötete. Gleichzeitig begab sich [[Illidan Sturmgrimm]] schon über das Schlachtfeld, um die Leitung der restlichen Mondwachen zu übernehmen. Illidan war zwar kein Angehöriger ihrer Truppe, besaß aber eindeutig überlegene magische Fähigkeiten, und er erwies sich als deutlich besser als Latosius bei der Koordination der Mondgarde.",},
			["Laubschattental"] = { content = "Das Laubschattental liegt im Nordosten von [[Teldrassil]] und ist das Startgebiet der [[Nachtelfen]], wo sich auch der Baum [[Aldrassil]] befindet.\r\nDie Frühjahrsniederschläge waren hier dieses Jahr besonders heftig, was dafür sorgte, dass einige Tiere des Waldes gediehen, während andere darunter litten. Unglücklicherweise sind die Bestände an [[Nachtsäbler]]n und [[Disteleber]]n zu stark angewachsen. Das Laubschattental kann nur eine gewisse Menge Futter für diese Tiere erzeugen und die Ressourcen des Waldes werden sich zu schnell erschöpfen, wenn sich niemand um das Problem kümmert. Mutter Naturs Wildtiere zu töten, ist ein notwendiges Übel zum Besten von allen, die sich das Land teilen. Aber auch die [[Grell]]s und [[Grellkin]] suchen die Gegend heim und bedrohen die Einwohner des Laubschattentals.\r\n==Personen==\r\n* '''Dirania Silberschein''' - Dirania Silberschein hat einen guten Freund, [[Iverron]], der sie jeden Tag um dieselbe Zeit besucht. Komischerweise ist er heute noch nicht da gewesen - genau genommen ist er sogar schon etliche Stunden über seiner sonstigen Zeit und sie muss zugeben, dass sie etwas besorgt ist und möchte, dass er gesucht wird. Sie dürfte in der Lage sein, Iverron, der von den [[Waldweberspinnen]] vergiftet wurde, zu helfen, denn sie kennt ein Gegengift, das gegen das Gift wirkt. Aber bevor sie es herstellen kann, benötigt sie einige Zutaten, wie z.B. Hyazinthpilze, Mondblütenlilien und Waldwebersekret. Das Gegengift muss anschließend zu Iverron gebracht werden, bevor die Zeit um ist, denn es ist nur 5 Minuten wirksam.\r\n* '''Konservator Ilthalaine''' - Ilthalaines Aufgabe in Laubschattental ist es, für den Erhalt des Gleichgewichts der Natur zu sorgen. \r\n* '''Porthannius''' - Porthannius hat ein Päckchen Kräuter, das er an Gastwirt [[Keldamyr]] nach [[Dolanaar]] liefern muss. Aber er hat noch etwas mit den Druiden im Laubschattental zu regeln und kann nicht weg. \r\n* '''Tarindrella''' - Tarindrella ist ein [[Dryade]] südwestlich von [[Aldrassil]]. Sie ist die geheimnisvolle Beschützerin des Waldlandes und nun nach Laubschattental zurückgekehrt. Jahrelang war die Gegenwart der [[Dryade]] in den Wäldern [[Kalimdor]]s nicht zu spüren. Sicherlich stimmt irgendetwas nicht, wenn sie jetzt wieder in diese Gegend zurückgekommen ist.",},
			["Lauerergift"] = { content = "Lauerergift kann von den im [[Loch Modan]] heimischen Spinnen gewonnen werden und dient zum entschärfen von Sprengstoffen.",},
			["Lauerfels"] = { content = "Der Lauerfels ist ein Hügel im [[Hinterland]] mit Ruinen ehemaliger Bauten der [[Trolle der Blutfratzen]]. Darunter befindet sich eine weitläufige Höhle, in denen sich einst Stellungen der [[Horde]] befanden, die jedoch aufgegeben wurden. Jetzt wimmelt es dort von üblen [[Brühschleimer]]n und [[Brühschlammer]]n; die angeblich von einer Art Oberbrühschlammer geführt werden. Die [[Zwerge der Wildhämmer]] haben Pläne für dieses Gebiet, aber zuerst muss eine Aufräummannschaft dort eine Bresche hineinschlagen. Dieser verlassene Außenposten der [[Horde]] verfügt über ein Lager mit Hinterländer Honigwein aus der Zeit, als sie noch im Geschäft waren. Solch feine Welle bekommt man sonst nirgendwo.",},
			["Lauerwurzranke"] = { content = "Die Draenei bei der [[Exodar]] haben herausgefunden, dass die Ranken der Pflanzenkreaturen, den sogenannten [[Peitscher]]n, auf der [[Azurmythosinsel]] eine regenerierende Eigenschaft besitzen. Wenn man die Ranken richtig verarbeitet, kann man aus ihnen eine hochwirksame Heilsalbe herstellen. Man kann diese Ranke im Osten der [[Azurwacht]] finden.",},
			["Lava-Elementar"] = { content = "#REDIRECT [[Lava-Elementare]]", redirect = "Lava-Elementare",},
			["Lava-Elementare"] = { content = "Lava Elementare sind ein Gemisch aus [[Feuerelementare|Feuer-]] und [[Erdelementare]]n. Die Lava-Elementare befinden sich in der [[Brennende Steppe|Brennenden Steppe]], in der [[Sengende Schlucht|Sengenden Schlucht]], im [[Flammenschlund]] und im [[Schwarzfels]].\r\n==Arten==\r\n* [[Lavavernichter]]\r\n==Bekannte Lava-Elementare==\r\n* [[Garr]]\r\n* [[Magmafürst Bokk]]",},
			["LBRS"] = { content = "#REDIRECT [[Untere Schwarzfelsspitze]]", redirect = "Untere Schwarzfelsspitze",},
			["Lebender Hain"] = { content = "Vor kurzem hat die [[Allianz]] im Westen des [[Schergrat]]s Einzug gehalten und mit Hilfe der [[Nachtelfen]]-Magie ein Dorf und einen Hain praktisch aus dem Nichts entstehen lassen. Aber nun haben sie die Kontrolle über die Hainpischerluchse dort verloren. Einst war ihre Population gleichmäßig, aber nun kommen die Luchse immer näher an [[Sylvanaar]] heran. In letzter Zeit gab es schon einige unerfreuliche Zwischenfälle. [[Starkast Tiefenwurz]] ist ein [[Urtum des Krieges]] und Chefverteidiger des lebenden Hains.",},
			["Lebenswurz"] = { content = "Lebenswurz findet man in freier Natur oder bei den Moderrankenbestien aus den [[Düstermarschen]]. Normalerweise wird diese Wurzel von [[Alchimist]]en verwendet, aber [[Bath'rah der Windbehüter]] benötigt sie auch, um damit die Lebensessenz des [[Luftelementar]]s [[Cyclonian]] in diese Welt zu ziehen.",},
			["Lederer: Rezepte"] = { content = "Hier können Charaktere eintragen werden und welche besonderen Rezepte sie ab der Seltenheits-Stufe \"Rar\" in diesem Beruf beherrschen.\r\n==Behälter==\r\n* '''''' (24 Platz Ledertasche) \r\n* Allianz: [[Gibin]]\r\n* Horde: [[Durathror]], [[Gorthag]], [[Torvus]]\r\n* '''''' (28 Platz Bergbautasche) \r\n* Allianz: [[Gibin]]\r\n* Horde: [[Baodur]], [[Bullrin]], [[Durathror]], [[Gorthag]], [[Sedjuhnak]], [[Torvus]]\r\n==Gegenstandsverbesserung==\r\n* '''''' \r\n* Allianz: \r\n* Horde: [[Baodur]], [[Bullrin]], [[Sedjuhnak]], [[Torvus]]\r\n* ''''''\r\n* Allianz: \r\n* Horde: [[Torvus]]\r\n* ''''''\r\n* Allianz: \r\n* Horde: [[Sedjuhnak]]\r\n* ''''''\r\n* Allianz: [[Gibin]], [[Marieth]]\r\n* Horde: [[Baodur]], [[Bullrin]], [[Durathror]], [[Mokkda]], [[Gorthag]], [[Sedjuhnak]], [[Torvus]]\r\n* ''''''\r\n* Allianz: [[Gibin]], [[Marieth]]\r\n* Horde: [[Baodur]], [[Bullrin]], [[Durathror]], [[Mokkda]], [[Gorthag]], [[Sedjuhnak]], [[Torvus]]\r\n* ''''''\r\n* Allianz: \r\n* Horde: [[Bullrin]], [[Torvus]]\r\n* ''''''\r\n* Allianz: [[Hildegard]]\r\n* Horde: [[Baodur]], [[Bullrin]], [[Gorthag]], [[Torvus]]\r\n* ''''''\r\n* Allianz: [[Hildegard]], [[Gibin]]\r\n* Horde: [[Baodur]], [[Torvus]]\r\n* ''''''\r\n* Allianz: [[Gibin]]\r\n* Horde: [[Baodur]], [[Sedjuhnak]]\r\n* ''''''\r\n* Allianz: \r\n* Horde: [[Bullrin]], [[Durathror]], [[Gorthag]], [[Torvus]]\r\n* ''''''\r\n* Allianz: \r\n* Horde: [[Baodur]], [[Gorthag]], [[Torvus]]\r\n==Leder (Stufe 61-70)==\r\n* ''''''\r\n* Allianz: [[Hildegard]], [[Gibin]]\r\n* Horde: [[Gorthag]], [[Torvus]]\r\n* ''''''\r\n* Allianz: [[Hildegard]]\r\n* Horde: \r\n* ''''''\r\n* Allianz: \r\n* Horde: [[Torvus]]\r\n* ''''''\r\n* Allianz: [[Gibin]]\r\n* Horde:\r\n* ''''''\r\n* Allianz: \r\n* Horde: [[Torvus]]\r\n* ''''''\r\n* Allianz: [[Khyrinda]]\r\n* Horde: [[Shálimar]], [[Torvus]]\r\n* ''''''\r\n* Allianz: \r\n* Horde: [[Baodur]]\r\n* ''''''\r\n* Allianz: \r\n* Horde: [[Shálimar]]\r\n* ''''''\r\n* Allianz: [[Gibin